heading\":false,\"text\":\"For life\'s estate with you.\"},{\"heading\":false,\"text\":\"Of mines I little know, myself,\"},{\"heading\":false,\"text\":\"But just the names of gems, —\"},{\"heading\":false,\"text\":\"The colors of the commonest;\"},{\"heading\":false,\"text\":\"And scarce of diadems\"},{\"heading\":false,\"text\":\"So much that, did I meet the queen,\"},{\"heading\":false,\"text\":\"Her glory I should know:\"},{\"heading\":false,\"text\":\"But this must be a different wealth,\"},{\"heading\":false,\"text\":\"To miss it beggars so.\"},{\"heading\":false,\"text\":\"I \'m sure \'t is India all day\"},{\"heading\":false,\"text\":\"To those who look on you\"},{\"heading\":false,\"text\":\"Without a stint, without a blame, —\"},{\"heading\":false,\"text\":\"Might I but be the Jew!\"},{\"heading\":false,\"text\":\"I \'m sure it is Golconda,\"},{\"heading\":false,\"text\":\"Beyond my power to deem, —\"},{\"heading\":false,\"text\":\"To have a smile for mine each day,\"},{\"heading\":false,\"text\":\"How better than a gem!\"},{\"heading\":false,\"text\":\"At least, it solaces to know\"},{\"heading\":false,\"text\":\"That there exists a gold,\"},{\"heading\":false,\"text\":\"Although I prove it just in time\"},{\"heading\":false,\"text\":\"Its distance to behold!\"},{\"heading\":false,\"text\":\"It \'s far, far treasure to surmise,\"},{\"heading\":false,\"text\":\"And estimate the pearl\"},{\"heading\":false,\"text\":\"That slipped my simple fingers through\"},{\"heading\":false,\"text\":\"While just a girl at school!\"},{\"heading\":false,\"text\":\"IV.\"},{\"heading\":false,\"text\":\"THE CONTRACT.\"},{\"heading\":false,\"text\":\"I gave myself to him,\"},{\"heading\":false,\"text\":\"And took himself for pay.\"},{\"heading\":false,\"text\":\"The solemn contract of a life\"},{\"heading\":false,\"text\":\"Was ratified this way.\"},{\"heading\":false,\"text\":\"The wealth might disappoint,\"},{\"heading\":false,\"text\":\"Myself a poorer prove\"},{\"heading\"