alse,\"text\":\"Prithee, my pretty housewives!\"},{\"heading\":false,\"text\":\"Who may expected be?\"},{\"heading\":false,\"text\":\"The neighbors do not yet suspect!\"},{\"heading\":false,\"text\":\"The woods exchange a smile —\"},{\"heading\":false,\"text\":\"Orchard, and buttercup, and bird —\"},{\"heading\":false,\"text\":\"In such a little while!\"},{\"heading\":false,\"text\":\"And yet how still the landscape stands,\"},{\"heading\":false,\"text\":\"How nonchalant the wood,\"},{\"heading\":false,\"text\":\"As if the resurrection\"},{\"heading\":false,\"text\":\"Were nothing very odd!\"},{\"heading\":false,\"text\":\"V.\"},{\"heading\":false,\"text\":\"TO MARCH.\"},{\"heading\":false,\"text\":\"Dear March, come in!\"},{\"heading\":false,\"text\":\"How glad I am!\"},{\"heading\":false,\"text\":\"I looked for you before.\"},{\"heading\":false,\"text\":\"Put down your hat —\"},{\"heading\":false,\"text\":\"You must have walked —\"},{\"heading\":false,\"text\":\"How out of breath you are!\"},{\"heading\":false,\"text\":\"Dear March, how are you?\"},{\"heading\":false,\"text\":\"And the rest?\"},{\"heading\":false,\"text\":\"Did you leave Nature well?\"},{\"heading\":false,\"text\":\"Oh, March, come right upstairs with me,\"},{\"heading\":false,\"text\":\"I have so much to tell!\"},{\"heading\":false,\"text\":\"I got your letter, and the birds\';\"},{\"heading\":false,\"text\":\"The maples never knew\"},{\"heading\":false,\"text\":\"That you were coming, — I declare,\"},{\"heading\":false,\"text\":\"How red their faces grew!\"},{\"heading\":false,\"text\":\"But, March, forgive me —\"},{\"heading\":false,\"text\":\"And all those hills\"},{\"heading\":false,\"text\":\"You left for me to hue;\"},{\"heading\":false,\"text\":\"There was no purple suitable,\"},{\"heading\":false,\"text\":\"You took it all with you.\"},{\"heading\":false,\"text\":\"Who knocks? That April!\"},{\"heading\":false,\"text\":\"Lock the door!\"},{\"heading\":false,\"text\":\"I will not be pursued!\"},{\"heading\":false,\"text\":\"He stayed away a year, to call\"},{\"heading\":false,\"text\":\"When I am occupied.\"},{\"heading\":false,\"text\":\"But trifles look so trivial\"},{\"heading\":false,\"text\":\"As soon as you have come,\"},{\"heading\":false,\"text\":\"That blame is just as dear as praise\"},{\"heading\":false,\"text\":\"And praise as mere as blame.\"},{\"heading\":false,\"text\":\"VI.\"},{\"heading\":false,\"text\":\"MARCH.\"},{\"heading\":false,\"text\":\"We like March, his shoes are purple,\"},{\"heading\":false,\"text\":\"He is new and high;\"},{\"heading\":false,\"text\":\"Makes he mud for dog and peddler,\"},{\"heading\":false,\"text\":\"Makes he forest dry;\"},{\"heading\":false,\"text\":\"Knows the adder\'s tongue his coming,\"},{\"heading\":false,\"text\":\"And begets her spot.\"},{\"heading\":false,\"text\":\"Stands the sun so close and mighty\"},{\"heading\":false,\"text\":\"That our minds are hot.\"},{\"heading\":false,\"text\":\"News is he of all the others;\"},{\"heading\":false,\"text\":\"Bold it were to die\"},{\"heading\":false,\"text\":\"With the blue-birds buccaneering\"},{\"heading\":false,\"text\":\"On his British sky.\"},{\"heading\":false,\"text\":\"VII.\"},{\"heading\":false,\"text\":\"DAWN.\"},{\"heading\":false,\"text\":\"Not knowing when the dawn will come\"},{\"heading\":false,\"text\":\"I open every door;\"},{\"heading\":false,\"text\":\"Or has it feathers like a bird,\"},{\"heading\":false,\"text\":\"Or billows like a shore?\"},{\"heading\":false,\"text\":\"VIII.\"},{\"heading\":false,\"text\":\"A murmur in the trees to note,\"},{\"heading\":false,\"text\":\"Not loud enough for wind;\"},{\"heading\":false,\"text\":\"A star not far enough to seek,\"},{\"heading\":false,\"text\":\"Nor near enough to find;\"},{\"heading\":false,\"text\":\"A long, long yellow on the lawn,\"},{\"heading\":false,\"text\":\"A hubbub as of feet;\"},{\"heading\":false,\"text\":\"Not audible, as ours to us,\"},{\"heading\":false,\"text\":\"But