,{\"heading\":false,\"text\":\"XII.\"},{\"heading\":false,\"text\":\"High from the earth I heard a bird;\"},{\"heading\":false,\"text\":\"He trod upon the trees\"},{\"heading\":false,\"text\":\"As he esteemed them trifles,\"},{\"heading\":false,\"text\":\"And then he spied a breeze,\"},{\"heading\":false,\"text\":\"And situated softly\"},{\"heading\":false,\"text\":\"Upon a pile of wind\"},{\"heading\":false,\"text\":\"Which in a perturbation\"},{\"heading\":false,\"text\":\"Nature had left behind.\"},{\"heading\":false,\"text\":\"A joyous-going fellow\"},{\"heading\":false,\"text\":\"I gathered from his talk,\"},{\"heading\":false,\"text\":\"Which both of benediction\"},{\"heading\":false,\"text\":\"And badinage partook,\"},{\"heading\":false,\"text\":\"Without apparent burden,\"},{\"heading\":false,\"text\":\"I learned, in leafy wood\"},{\"heading\":false,\"text\":\"He was the faithful father\"},{\"heading\":false,\"text\":\"Of a dependent brood;\"},{\"heading\":false,\"text\":\"And this untoward transport\"},{\"heading\":false,\"text\":\"His remedy for care, —\"},{\"heading\":false,\"text\":\"A contrast to our respites.\"},{\"heading\":false,\"text\":\"How different we are!\"},{\"heading\":false,\"text\":\"XIII.\"},{\"heading\":false,\"text\":\"COBWEBS.\"},{\"heading\":false,\"text\":\"The spider as an artist\"},{\"heading\":false,\"text\":\"Has never been employed\"},{\"heading\":false,\"text\":\"Though his surpassing merit\"},{\"heading\":false,\"text\":\"Is freely certified\"},{\"heading\":false,\"text\":\"By every broom and Bridget\"},{\"heading\":false,\"text\":\"Throughout a Christian land.\"},{\"heading\":false,\"text\":\"Neglected son of genius,\"},{\"heading\":false,\"text\":\"I take thee by the hand.\"},{\"heading\":false,\"text\":\"XIV.\"},{\"heading\":false,\"text\":\"A WELL.\"},{\"heading\":false,\"text\":\"What mystery pervades a well!\"},{\"heading\":false,\"text\":\"The water lives so far,\"},{\"heading\":false,\"text\":\"Like neighbor from another world\"},{\"heading\":false,\"text\":\"Residing in a jar.\"},{\"heading\":false,\"text\":\"The grass does not appear afraid;\"},{\"heading\":false,\"text\":\"I often wonder he\"},{\"heading\":false,\"text\":\"Can stand so close and look so bold\"},{\"heading\":false,\"text\":\"At what is dread to me.\"},{\"heading\":false,\"text\":\"Related somehow they may be, —\"},{\"heading\":false,\"text\":\"The sedge stands next the sea,\"},{\"heading\":false,\"text\":\"Where he is floorless, yet of fear\"},{\"heading\":false,\"text\":\"No evidence gives he.\"},{\"heading\":false,\"text\":\"But nature is a stranger yet;\"},{\"heading\":false,\"text\":\"The ones that cite her most\"},{\"heading\":false,\"text\":\"Have never passed her haunted house,\"},{\"heading\":false,\"text\":\"Nor simplified her ghost.\"},{\"heading\":false,\"text\":\"To pity those that know her not\"},{\"heading\":false,\"text\":\"Is helped by the regret\"},{\"heading\":false,\"text\":\"That those who know her, know her less\"},{\"heading\":false,\"text\":\"The nearer her they get.\"},{\"heading\":false,\"text\":\"XV.\"},{\"heading\":false,\"text\":\"To make a prairie it takes a clover and one bee, —\"},{\"heading\":false,\"text\":\"One clover, and a bee,\"},{\"heading\":false,\"text\":\"And revery.\"},{\"heading\":false,\"text\":\"The revery alone will do\"},{\"heading\":false,\"text\":\"If bees are few.\"},{\"heading\":false,\"text\":\"XVI.\"},{\"heading\":false,\"text\":\"THE WIND.\"},{\"heading\":false,\"text\":\"It\'s like the light, —\"},{\"heading\":false,\"text\":\"A fashionless delight\"},{\"heading\":false,\"text\":\"It\'s like the bee, —\"},{\"heading\":false,\"text\":\"A dateless melody.\"},{\"heading\":false,\"text\":\"It\'s like the woods,\"},{\"heading\":false,\"text\":\"Private like breeze,\"},{\"heading\":false,\"text\":\"Phraseless, yet it stirs\"},{\"heading\":false,\"text\":\"The proudest trees.\"},{\"heading\":false,\"text\":\"It\'s like the morning, —\"},{\"heading\":false,\"text\":