ng\":false,\"text\":\"My holiday shall be\"},{\"heading\":false,\"text\":\"That they remember me;\"},{\"heading\":false,\"text\":\"My paradise, the fame\"},{\"heading\":false,\"text\":\"That they pronounce my name.\"},{\"heading\":false,\"text\":\"XXVII.\"},{\"heading\":false,\"text\":\"INVISIBLE.\"},{\"heading\":false,\"text\":\"From us she wandered now a year,\"},{\"heading\":false,\"text\":\"Her tarrying unknown;\"},{\"heading\":false,\"text\":\"If wilderness prevent her feet,\"},{\"heading\":false,\"text\":\"Or that ethereal zone\"},{\"heading\":false,\"text\":\"No eye hath seen and lived,\"},{\"heading\":false,\"text\":\"We ignorant must be.\"},{\"heading\":false,\"text\":\"We only know what time of year\"},{\"heading\":false,\"text\":\"We took the mystery.\"},{\"heading\":false,\"text\":\"XXVIII.\"},{\"heading\":false,\"text\":\"I wish I knew that woman\'s name,\"},{\"heading\":false,\"text\":\"So, when she comes this way,\"},{\"heading\":false,\"text\":\"To hold my life, and hold my ears,\"},{\"heading\":false,\"text\":\"For fear I hear her say\"},{\"heading\":false,\"text\":\"She\'s \'sorry I am dead,\' again,\"},{\"heading\":false,\"text\":\"Just when the grave and I\"},{\"heading\":false,\"text\":\"Have sobbed ourselves almost to sleep, —\"},{\"heading\":false,\"text\":\"Our only lullaby.\"},{\"heading\":false,\"text\":\"XXIX.\"},{\"heading\":false,\"text\":\"TRYING TO FORGET.\"},{\"heading\":false,\"text\":\"Bereaved of all, I went abroad,\"},{\"heading\":false,\"text\":\"No less bereaved to be\"},{\"heading\":false,\"text\":\"Upon a new peninsula, —\"},{\"heading\":false,\"text\":\"The grave preceded me,\"},{\"heading\":false,\"text\":\"Obtained my lodgings ere myself,\"},{\"heading\":false,\"text\":\"And when I sought my bed,\"},{\"heading\":false,\"text\":\"The grave it was, reposed upon\"},{\"heading\":false,\"text\":\"The pillow for my head.\"},{\"heading\":false,\"text\":\"I waked, to find it first awake,\"},{\"heading\":false,\"text\":\"I rose, — it followed me;\"},{\"heading\":false,\"text\":\"I tried to drop it in the crowd,\"},{\"heading\":false,\"text\":\"To lose it in the sea,\"},{\"heading\":false,\"text\":\"In cups of artificial drowse\"},{\"heading\":false,\"text\":\"To sleep its shape away, —\"},{\"heading\":false,\"text\":\"The grave was finished, but the spade\"},{\"heading\":false,\"text\":\"Remained in memory.\"},{\"heading\":false,\"text\":\"XXX.\"},{\"heading\":false,\"text\":\"I felt a funeral in my brain,\"},{\"heading\":false,\"text\":\"And mourners, to and fro,\"},{\"heading\":false,\"text\":\"Kept treading, treading, till it seemed\"},{\"heading\":false,\"text\":\"That sense was breaking through.\"},{\"heading\":false,\"text\":\"And when they all were seated,\"},{\"heading\":false,\"text\":\"A service like a drum\"},{\"heading\":false,\"text\":\"Kept beating, beating, till I thought\"},{\"heading\":false,\"text\":\"My mind was going numb.\"},{\"heading\":false,\"text\":\"And then I heard them lift a box,\"},{\"heading\":false,\"text\":\"And creak across my soul\"},{\"heading\":false,\"text\":\"With those same boots of lead, again.\"},{\"heading\":false,\"text\":\"Then space began to toll\"},{\"heading\":false,\"text\":\"As all the heavens were a bell,\"},{\"heading\":false,\"text\":\"And Being but an ear,\"},{\"heading\":false,\"text\":\"And I and silence some strange race,\"},{\"heading\":false,\"text\":\"Wrecked, solitary, here.\"},{\"heading\":false,\"text\":\"XXXI.\"},{\"heading\":false,\"text\":\"I meant to find her when I came;\"},{\"heading\":false,\"text\":\"Death had the same design;\"},{\"heading\":false,\"text\":\"But the success was his, it seems,\"},{\"heading\":false,\"text\":\"And the discomfit mine.\"},{\"heading\":false,\"text\":\"I meant to tell her how I longed\"},{\"heading\":false,\"text\":\"For just this single time;\"},{\"heading\":false,\"text\":\"But Death had told her so the first,\"},{\"heading\":false,\"text\":\"And she had hearkened him.\"},{\"heading\":false,\"text\":\"To wander now is my abode;\"},{\"heading\":false,\"text\":\"To rest, — to rest would be\"},{\"heading\":false,\"text\":\"A privilege of hurricane\"},{\"heading\":false,\"text\":\"To memory and me.\"},{\"heading\":false,\"text\":\"XXXII.\"},{\"heading\":false,\"text\":\"WAITING.\"},{\"heading\":false,\"text\":\"I sing to use the waiting,\"},{\"heading\":false,\"text\":\"My bonnet but to tie,\"},{\"heading\":false,\"text\":\"And shut the door unto my house;\"},{\"heading\":false,\"text\":\"No more to do have I,\"},{\"heading\":false,\"text\":\"Till, his best step approaching,\"},{\"heading\":false,\"text\":\"We journey to the day,\"},{\"heading\":false,\"text\":\"And tell each other how we sang\"},{\"heading\":false,\"text\":\"To keep the dark away.\"},{\"heading\":false,\"text\":\"XXXIII.\"},{\"heading\":false,\"text\":\"A sickness of this world it most occasions\"},{\"heading\":false,\"text\":\"When best men die;\"},{\"heading\":false,\"text\":\"A wishfulness their far condition\"},{\"heading\":false,\"text\":\"To occupy.\"},{\"heading\":false,\"text\":\"A chief indifference, as foreign\"},{\"heading\":false,\"text\":\"A world must be\"},{\"heading\":false,\"text\":\"Themselves forsake contented,\"},{\"heading\":false,\"text\":\"For Deity.\"},{\"heading\":false,\"text\":\"XXXIV.\"},{\"heading\":false,\"text\":\"Superfluous were the sun\"},{\"heading\":false,\"text\":\"When excellence is dead;\"},{\"heading\":false,\"text\":\"He were superfluous every day,\"},{\"heading\":false,\"text\":\"For every day is said\"},{\"heading\":false,\"text\":\"That syllable whose faith\"},{\"heading\":false,\"text\":\"Just saves it from despair,\"},{\"heading\":false,\"text\":\"And whose \'I\'ll meet you\' hesitates\"},{\"heading\":false,\"text\":\"If love inquire, \'Where?\'\"},{\"heading\":false,\"text\":\"Upon his dateless fame\"},{\"heading\":false,\"text\":\"Our periods may lie,\"},{\"heading\":false,\"text\":\"As stars that drop anonymous\"},{\"heading\":false,\"text\":\"From an abundant sky.\"},{\"heading\":false,\"text\":\"XXXV.\"},{\"heading\":false,\"text\":\"So proud she was to die\"},{\"heading\":false,\"text\":\"It made us all ashamed\"},{\"heading\":false,\"text\":\"That what we cherished, so unknown\"},{\"heading\":false,\"text\":\"To her desire seemed.\"},{\"heading\":false,\"text\":\"So satisfied to go\"},{\"heading\":false,\"text\":\"Where none of us should be,\"},{\"heading\":false,\"text\":\"Immediately, that anguish stooped\"},{\"heading\":false,\"text\":\"Almost to jealousy.\"},{\"heading\":false,\"text\":\"XXXVI.\"},{\"heading\":false,\"text\":\"FAREWELL.\"},{\"heading\":false,\"text\":\"Tie the strings to my life, my Lord,\"},{\"heading\":false,\"text\":\"Then I am ready to go!\"},{\"heading\":false,\"text\":\"Just a look at the horses —\"},{\"heading\":false,\"text\":\"Rapid! That will do!\"},{\"heading\":false,\"text\":\"Put me in on the firmest side,\"},{\"heading\":false,\"text\":\"So I shall never fall;\"},{\"heading\":false,\"text\":\"For we must ride to the Judgment,\"},{\"heading\":false,\"text\":\"And it\'s partly down hill.\"},{\"heading\":false,\"text\":\"But never I mind the bridges,\"},{\"heading\":false,\"text\":\"And never I mind the sea;\"},{\"heading\":false,\"text\":\"Held fast in everlasting race\"},{\"heading\":false,\"text\":\"By my own choice and thee.\"},{\"heading\":false,\"text\":\"Good-by to the life I used to live,\"},{\"heading\":false,\"text\":\"And the world I used to know;\"},{\"heading\":false,\"text\":\"And kiss the hills for me, just once;\"},{\"heading\":false,\"text\":\"Now I am ready to go!\"},{\"heading\":false,\"text\":\"XXXVII.\"},{\"heading\":false,\"text\":\"The dying need but little, dear, —\"},{\"heading\":false,\"text\":\"A glass of water\'s all,\"},{\"heading\":false,\"text\":\"A flower\'s unobtrusive face\"},{\"heading\":false,\"text\":\"To punctuate the wall,\"},{\"heading\":false,\"text\":\"A fan, perhaps, a friend\'s regret,\"},{\"heading\":false,\"text\":\"And certainly that one\"},{\"heading\":false,\"text\":\"No color in the rainbow\"},{\"heading\":false,\"text\":\"Perceives when you are gone.\"},{\"heading\":false,\"text\":\"XXXVIII.\"},{\"heading\":false,\"text\":\"DEAD.\"},{\"heading\":false,\"text\":\"There\'s something quieter than sleep\"},{\"heading\":false,\"text\":\"Within this inner room!\"},{\"heading\":false,\"text\":\"It wears a sprig upon its breast,\"},{\"heading\":false,\"text\":\"And will not tell its name.\"},{\"heading\":false,\"text\":\"Some touch it and some kiss it,\"},{\"heading\":false,\"text\":\"Some chafe its idle hand;\"},{\"heading\":false,\"text\":\"It has a simple gravity\"},{\"heading\":false,\"text\":\"I do not understand!\"},{\"heading\":false,\"text\":\"While simple-hearted neighbors\"},{\"heading\":false,\"text\":\"Chat of the \'early dead,\'\"},{\"heading\":false,\"text\":\"We, prone to periphrasis,\"},{\"heading\":false,\"text\":\"Remark that birds have fled!\"},{\"heading\":false,\"text\":\"XXXIX.\"},{\"heading\":false,\"text\":\"The soul should always stand ajar,\"},{\"heading\":false,\"text\":\"That if the heaven inquire,\"},{\"heading\":false,\"text\":\"He will not be obliged to wait,\"},{\"heading\":false,\"text\":\"Or shy of troubling her.\"},{\"heading\":false,\"text\":\"Depart, before the host has slid\"},{\"heading\":false,\"text\":\"The bolt upon the door,\"},{\"heading\":false,\"text\":\"To seek for the accomplished guest, —\"},{\"heading\":false,\"text\":\"Her visitor no more.\"},{\"heading\":false,\"text\":\"XL.\"},{\"heading\":false,\"text\":\"Three weeks passed since I had seen her, —\"},{\"heading\":false,\"text\":\"Some disease had vexed;\"},{\"heading\":false,\"text\":\"\'T was with text and village singing\"},{\"heading\":false,\"text\":\"I beheld her next,\"},{\"heading\":false,\"text\":\"And a company — our pleasure\"},{\"heading\":false,\"text\":\"To discourse alone;\"},{\"heading\":false,\"text\":\"Gracious now to me as any,\"},{\"heading\":false,\"text\":\"Gracious unto none.\"},{\"heading\":false,\"text\":\"Borne, without dissent of either,\"},{\"heading\":false,\"text\":\"To the parish night;\"},{\"heading\":false,\"text\":\"Of the separated people\"},{\"heading\":false,\"text\":\"Which are out of sight?\"},{\"heading\":false,\"text\":\"XLI.\"},{\"heading\":false,\"text\":\"I breathed enough to learn the trick,\"},{\"heading\":false,\"text\":\"And now, removed from air,\"},{\"heading\":false,\"text\":\"I simulate the breath so well,\"},{\"heading\":false,\"text\":\"That one, to be quite sure\"},{\"heading\":false,\"text\":\"The lungs are stirless, must descend\"},{\"heading\":false,\"text\":\"Among the cunning cells,\"},{\"heading\":false,\"text\":\"And touch the pantomime himself.\"},{\"heading\":false,\"text\":\"How cool the bellows feels!\"},{\"heading\":false,\"text\":\"XLII.\"},{\"heading\":false,\"text\":\"I wonder if the sepulchre\"},{\"heading\":false,\"text\":\"Is not a lonesome way,\"},{\"heading\":false,\"text\":\"When men and boys, and larks and June\"},{\"heading\":false,\"text\":\"Go down the fields to hay!\"},{\"heading\":false,\"text\":\"XLIII.\"},{\"heading\":false,\"text\":\"JOY IN DEATH.\"},{\"heading\":false,\"text\":\"If tolling bell I ask the cause.\"},{\"heading\":false,\"text\":\"\'A soul has gone to God,\'\"},{\"heading\":false,\"text\":\"I\'m answered in a lonesome tone;\"},{\"heading\":false,\"text\":\"Is heaven then so sad?\"},{\"heading\":false,\"text\":\"That bells should joyful ring to tell\"},{\"heading\":false,\"text\":\"A soul had gone to heaven,\"},{\"heading\":false,\"text\":\"Would seem to me the proper way\"},{\"heading\":false,\"text\":\"A good news should be given.\"},{\"heading\":false,\"text\":\"XLIV.\"},{\"heading\":false,\"text\":\"If I may have it when it\'s dead\"},{\"heading\":false,\"text\":\"I will contented be;\"},{\"heading\":false,\"text\":\"If just as soon as breath is out\"},{\"heading\":false,\"text\":\"It shall belong to me,\"},{\"heading\":false,\"text\":\"Until they lock it in the grave,\"},{\"heading\":false,\"text\":\"\'T is bliss I cannot weigh,\"},{\"heading\":false,\"text\":\"For though they lock thee in the grave,\"},{\"heading\":false,\"text\":\"Myself can hold the key.\"},{\"heading\":false,\"text\":\"Think of it, lover! I and thee\"},{\"heading\":false,\"text\":\"Permitted face to face to be;\"},{\"heading\":false,\"text\":\"After a life, a death we\'ll say, —\"},{\"heading\":false,\"text\":\"For death was that, and this is thee.\"},{\"heading\":false,\"text\":\"XLV.\"},{\"heading\":false,\"text\":\"Before the ice is in the pools,\"},{\"heading\":false,\"text\":\"Before the skaters go,\"},{\"heading\":false,\"text\":\"Or any cheek at nightfall\"},{\"heading\":false,\"text\":\"Is tarnished by the snow,\"},{\"heading\":false,\"text\":\"Before the fields have finished,\"},{\"heading\":false,\"text\":\"Before the Christmas tree,\"},{\"heading\":false,\"text\":\"Wonder upon wonder\"},{\"heading\":false,\"text\":\"Will arrive to me!\"},{\"heading\":false,\"text\":\"What we touch the hems of\"},{\"heading\":false,\"text\":\"On a summer\'s day;\"},{\"heading\":false,\"text\":\"What is only walking\"},{\"heading\":false,\"text\":\"Just a bridge away;\"},{\"heading\":false,\"text\":\"That which sings so, speaks so,\"},{\"heading\":false,\"text\":\"When there\'s no one here, —\"},{\"heading\":false,\"text\":\"Will the frock I wept in\"},{\"heading\":false,\"text\":\"Answer me to wear?\"},{\"heading\":false,\"text\":\"XLVI.\"},{\"heading\":false,\"text\":\"DYING.\"},{\"heading\":false,\"text\":\"I heard a fly buzz when I died;\"},{\"heading\":false,\"text\":\"The stillness round my form\"},{\"heading\":false,\"text\":\"Was like the stillness in the air\"},{\"heading\":false,\"text\":\"Between the heaves of storm.\"},{\"heading\":false,\"text\":\"The eyes beside had wrung them dry,\"},{\"heading\":false,\"text\":\"And breaths were gathering sure\"},{\"heading\":false,\"text\":\"For that last onset, when the king\"},{\"heading\":false,\"text\":\"Be witnessed in his power.\"},{\"heading\":false,\"text\":\"I willed my keepsakes, signed away\"},{\"heading\":false,\"text\":\"What portion of me I\"},{\"heading\":false,\"text\":\"Could make assignable, — and then\"},{\"heading\":false,\"text\":\"There interposed a fly,\"},{\"heading\":false,\"text\":\"With blue, uncertain, stumbling buzz,\"},{\"heading\":false,\"text\":\"Between the light and me;\"},{\"heading\":false,\"text\":\"And then the windows failed, and then\"},{\"heading\":false,\"text\":\"I could not see to see.\"},{\"heading\":false,\"text\":\"XLVII.\"},{\"heading\":false,\"text\":\"Adrift! A little boat adrift!\"},{\"heading\":false,\"text\":\"And night is coming down!\"},{\"heading\":false,\"text\":\"Will no one guide a little boat\"},{\"heading\":false,\"text\":\"Unto the nearest town?\"},{\"heading\":false,\"text\":\"So sailors say, on yesterday,\"},{\"heading\":false,\"text\":\"Just as the dusk was brown,\"},{\"heading\":false,\"text\":\"One little boat gave up its strife,\"},{\"heading\":false,\"text\":\"And gurgled down and down.\"},{\"heading\":false,\"text\":\"But angels say, on yesterday,\"},{\"heading\":false,\"text\":\"Just as the dawn was red,\"},{\"heading\":false,\"text\":\"One little boat o\'erspent with gales\"},{\"heading\":false,\"text\":\"Retrimmed its masts, redecked its sails\"},{\"heading\":false,\"text\":\"Exultant, onward sped!\"},{\"heading\":false,\"text\":\"XLVIII.\"},{\"heading\":false,\"text\":\"There\'s been a death in the opposite house\"},{\"heading\":false,\"text\":\"As lately as to-day.\"},{\"heading\":false,\"text\":\"I know it by the numb look\"},{\"heading\":false,\"text\":\"Such houses have alway.\"},{\"heading\":false,\"text\":\"The neighbors rustle in and out,\"},{\"heading\":false,\"text\":\"The doctor drives away.\"},{\"heading\":false,\"text\":\"A window opens like a pod,\"},{\"heading\":false,\"text\":\"Abrupt, mechanically;\"},{\"heading\":false,\"text\":\"Somebody flings a mattress out, —\"},{\"heading\":false,\"text\":\"The children hurry by;\"},{\"heading\":false,\"text\":\"They wonder if It died on that, —\"},{\"heading\":false,\"text\":\"I used to when a boy.\"},{\"heading\":false,\"text\":\"The minister goes stiffly in\"},{\"heading\":false,\"text\":\"As if the house were his,\"},{\"heading\":false,\"text\":\"And he owned all the mourners now,\"},{\"heading\":false,\"text\":\"And little boys besides;\"},{\"heading\":false,\"text\":\"And then the milliner, and the man\"},{\"heading\":false,\"text\":\"Of the appalling trade,\"},{\"heading\":false,\"text\":\"To take the measure of the house.\"},{\"heading\":false,\"text\":\"There\'ll be that dark parade\"},{\"heading\":false,\"text\":\"Of tassels and of coaches soon;\"},{\"heading\":false,\"text\":\"It\'s easy as a sign, —\"},{\"heading\":false,\"text\":\"The intuition of the news\"},{\"heading\":false,\"text\":\"In just a country town.\"},{\"heading\":false,\"text\":\"XLIX.\"},{\"heading\":false,\"text\":\"We never know we go, — when we are going\"},{\"heading\":false,\"text\":\"We jest and shut the door;\"},{\"heading\":false,\"text\":\"Fate following behind us bolts it,\"},{\"heading\":false,\"text\":\"And we accost no more.\"},{\"heading\":false,\"text\":\"L.\"},{\"heading\":false,\"text\":\"THE SOUL\'S STORM.\"},{\"heading\":false,\"text\":\"It struck me every day\"},{\"heading\":false,\"text\":\"The lightning was as new\"},{\"heading\":false,\"text\":\"As if the cloud that instant slit\"},{\"heading\":false,\"text\":\"And let the fire through.\"},{\"heading\":false,\"text\":\"It burned me in the night,\"},{\"heading\":false,\"text\":\"It blistered in my dream;\"},{\"heading\":false,\"text\":\"It sickened fresh upon my sight\"},{\"heading\":false,\"text\":\"With every morning\'s beam.\"},{\"heading\":false,\"text\":\"I thought that storm was brief, —\"},{\"heading\":false,\"text\":\"The maddest, quickest by;\"},{\"heading\":false,\"text\":\"But Nature lost the date of this,\"},{\"heading\":false,\"text\":\"And left it in the sky.\"},{\"heading\":false,\"text\":\"LI.\"},{\"heading\":false,\"text\":\"Water is taught by thirst;\"},{\"heading\":false,\"text\":\"Land, by the oceans passed;\"},{\"heading\":false,\"text\":\"Transport, by throe;\"},{\"heading\":false,\"text\":\"Peace, by its battles told;\"},{\"heading\":false,\"text\":\"Love, by memorial mould;\"},{\"heading\":false,\"text\":\"Birds, by the snow.\"},{\"heading\":false,\"text\":\"LII.\"},{\"heading\":false,\"text\":\"THIRST.\"},{\"heading\":false,\"text\":\"We thirst at first, — \'t is Nature\'s act;\"},{\"heading\":false,\"text\":\"And later, when we die,\"},{\"heading\":false,\"text\":\"A little water supplicate\"},{\"heading\":false,\"text\":\"Of fingers going by.\"},{\"heading\":false,\"text\":\"It intimates the finer want,\"},{\"heading\":false,\"text\":\"Whose adequate supply\"},{\"heading\":false,\"text\":\"Is that great water in the west\"},{\"heading\":false,\"text\":\"Termed immortality.\"},{\"heading\":false,\"text\":\"LIII.\"},{\"heading\":false,\"text\":\"A clock stopped — not the mantel\'s;\"},{\"heading\":false,\"text\":\"Geneva\'s farthest skill\"},{\"heading\":false,\"text\":\"Can\'t put the puppet bowing\"},{\"heading\":false,\"text\":\"That just now dangled still.\"},{\"heading\":false,\"text\":\"An awe came on the trinket!\"},{\"heading\":false,\"text\":\"The figures hunched with pain,\"},{\"heading\":false,\"text\":\"Then quivered out of decimals\"},{\"heading\":false,\"text\":\"Into degreeless noon.\"},{\"heading\":false,\"text\":\"It will not stir for doctors,\"},{\"heading\":false,\"text\":\"This pendulum of snow;\"},{\"heading\":false,\"text\":\"The shopman importunes it,\"},{\"heading\":false,\"text\":\"While cool, concernless No\"},{\"heading\":false,\"text\":\"Nods from the gilded pointers,\"},{\"heading\":false,\"text\":\"Nods from the seconds slim,\"},{\"heading\":false,\"text\":\"Decades of arrogance between\"},{\"heading\":false,\"text\":\"The dial life and him.\"},{\"heading\":false,\"text\":\"LIV.\"},{\"heading\":false,\"text\":\"CHARLOTTE BRONTË\'S GRAVE.\"},{\"heading\":false,\"text\":\"All overgrown by cunning moss,\"},{\"heading\":false,\"text\":\"All interspersed with weed,\"},{\"heading\":false,\"text\":\"The little cage of \'Currer Bell,\'\"},{\"heading\":false,\"text\":\"In quiet Haworth laid.\"},{\"heading\":false,\"text\":\"This bird, observing others,\"},{\"heading\":false,\"text\":\"When frosts too sharp became,\"},{\"heading\":false,\"text\":\"Retire to other latitudes,\"},{\"heading\":false,\"text\":\"Quietly did the same,\"},{\"heading\":false,\"text\":\"But differed in returning;\"},{\"heading\":false,\"text\":\"Since Yorkshire hills are green,\"},{\"heading\":false,\"text\":\"Yet not in all the nests I meet\"},{\"heading\":false,\"text\":\"Can nightingale be seen.\"},{\"heading\":false,\"text\":\"Gathered from many wanderings,\"},{\"heading\":false,\"text\":\"Gethsemane can tell\"},{\"heading\":false,\"text\":\"Through what transporting anguish\"},{\"heading\":false,\"text\":\"She reached the asphodel!\"},{\"heading\":false,\"text\":\"Soft fall the sounds of Eden\"},{\"heading\":false,\"text\":\"Upon her puzzled ear;\"},{\"heading\":false,\"text\":\"Oh, what an afternoon for heaven,\"},{\"heading\":false,\"text\":\"When \'Brontë\' entered there!\"},{\"heading\":false,\"text\":\"LV.\"},{\"heading\":false,\"text\":\"A toad can die of light!\"},{\"heading\":false,\"text\":\"Death is the common right\"},{\"heading\":false,\"text\":\"Of toads and men, —\"},{\"heading\":false,\"text\":\"Of earl and midge\"},{\"heading\":false,\"text\":\"The privilege.\"},{\"heading\":false,\"text\":\"Why swagger then?\"},{\"heading\":false,\"text\":\"The gnat\'s supremacy\"},{\"heading\":false,\"text\":\"Is large as thine.\"},{\"heading\":false,\"text\":\"LVI.\"},{\"heading\":false,\"text\":\"Far from love the Heavenly Father\"},{\"heading\":false,\"text\":\"Leads the chosen child;\"},{\"heading\":false,\"text\":\"Oftener through realm of briar\"},{\"heading\":false,\"text\":\"Than the meadow mild,\"},{\"heading\":false,\"text\":\"Oftener by the claw of dragon\"},{\"heading\":false,\"text\":\"Than the hand of friend,\"},{\"heading\":false,\"text\":\"Guides the little one predestined\"},{\"heading\":false,\"text\":\"To the native land.\"},{\"heading\":false,\"text\":\"LVII.\"},{\"heading\":false,\"text\":\"SLEEPING.\"},{\"heading\":false,\"text\":\"A long, long sleep, a famous sleep\"},{\"heading\":false,\"text\":\"That makes no show for dawn\"},{\"heading\":false,\"text\":\"By stretch of limb or stir of lid, —\"},{\"heading\":false,\"text\":\"An independent one.\"},{\"heading\":false,\"text\":\"Was ever idleness like this?\"},{\"heading\":false,\"text\":\"Within a hut of stone\"},{\"heading\":false,\"text\":\"To bask the centuries away\"},{\"heading\":false,\"text\":\"Nor once look up for noon?\"},{\"heading\":false,\"text\":\"LVIII.\"},{\"heading\":false,\"text\":\"RETROSPECT.\"},{\"heading\":false,\"text\":\"\'T was just this time last year I died.\"},{\"heading\":false,\"text\":\"I know I heard the corn,\"},{\"heading\":false,\"text\":\"When I was carried by the farms, —\"},{\"heading\":false,\"text\":\"It had the tassels on.\"},{\"heading\":false,\"text\":\"I thought how yellow it would look\"},{\"heading\":false,\"text\":\"When Richard went to mill;\"},{\"heading\":false,\"text\":\"And then I wanted to get out,\"},{\"heading\":false,\"text\":\"But something held my will.\"},{\"heading\":false,\"text\":\"I thought just how red apples wedged\"},{\"heading\":false,\"text\":\"The stubble\'s joints between;\"},{\"heading\":false,\"text\":\"And carts went stooping round the fields\"},{\"heading\":false,\"text\":\"To take the pumpkins in.\"},{\"heading\":false,\"text\":\"I wondered which would miss me least,\"},{\"heading\":false,\"text\":\"And when Thanksgiving came,\"},{\"heading\":false,\"text\":\"If father\'d multiply the plates\"},{\"heading\":false,\"text\":\"To make an even sum.\"},{\"heading\":false,\"text\":\"And if my stocking hung too high,\"},{\"heading\":false,\"text\":\"Would it blur the Christmas glee,\"},{\"heading\":false,\"text\":\"That not a Santa Claus could reach\"},{\"heading\":false,\"text\":\"The altitude of me?\"},{\"heading\":false,\"text\":\"But this sort grieved myself, and so\"},{\"heading\":false,\"text\":\"I thought how it would be\"},{\"heading\":false,\"text\":\"When just this time, some perfect year,\"},{\"heading\":false,\"text\":\"Themselves should come to me.\"},{\"heading\":false,\"text\":\"LIX.\"},{\"heading\":false,\"text\":\"ETERNITY.\"},{\"heading\":false,\"text\":\"On this wondrous sea,\"},{\"heading\":false,\"text\":\"Sailing silently,\"},{\"heading\":false,\"text\":\"Ho! pilot, ho!\"},{\"heading\":false,\"text\":\"Knowest thou the shore\"},{\"heading\":false,\"text\":\"Where no breakers roar,\"},{\"heading\":false,\"text\":\"Where the storm is o\'er?\"},{\"heading\":false,\"text\":\"In the silent west\"},{\"heading\":false,\"text\":\"Many sails at rest,\"},{\"heading\":false,\"text\":\"Their anchors fast;\"},{\"heading\":false,\"text\":\"Thither I pilot thee, —\"},{\"heading\":false,\"text\":\"Land, ho! Eternity!\"},{\"heading\":false,\"text\":\"Ashore at last!\"},{\"heading\":false,\"text\":\"A bird came down the walk:\\nA charm invests a face\\nA clock stopped — not the mantel\'s;\\nA death-blow is a life-blow to some\\nA deed knocks first at thought,\\nA dew sufficed itself\\nA door just opened on a street —\\nA drop fell on the apple tree,\\nA face devoid of love or grace,\\nA lady red upon the hill\\nA light exists in spring\\nA little road not made of man,\\nA long, long sleep, a famous sleep\\nA modest lot, a fame petite,\\nA murmur in the trees to note,\\nA narrow fellow in the grass\\nA poor torn heart, a tattered heart,\\nA precious, mouldering pleasure \'t is\\nA route of evanescence\\nA sepal, petal, and a thorn\\nA shady friend for torrid days\\nA sickness of this world it most occasions\\nA sloop of amber slips away\\nA solemn thing it was, I said,\\nA something in a summer\'s day,\\nA spider sewed at night\\nA thought went up my mind to-day\\nA throe upon the features\\nA toad can die of light!\\nA word is dead\\nA wounded deer leaps highest,\\nAdrift! A little boat adrift!\\nAfraid? Of whom am I afraid?\\nAfter a hundred years\\nAll overgrown by cunning moss,\\nAlter? When the hills do.\\nAmple make this bed.\\nAn altered look about the hills;\\nAn awful tempest mashed the air,\\nAn everywhere of silver,\\nAngels in the early morning\\nApparently with no surprise\\nArcturus is his other name, —\\nAre friends delight or pain?\\nAs by the dead we love to sit,\\nAs children bid the guest good-night,\\nAs far from pity as complaint,\\nAs if some little Arctic flower,\\nAs imperceptibly as grief\\nAshes denote that fire was;\\nAt half-past three a single bird\\nAt last to be identified!\\nAt least to pray is left, is left.\\nBecause I could not stop for Death,\\nBefore I got my eye put out,\\nBefore the ice is in the pools,\\nBefore you thought of spring,\\nBelshazzar had a letter, —\\nBereaved of all, I went abroad,\\nBesides the autumn poets sing,\\nBlazing in gold and quenching in purple,\\nBless God, he went as soldiers,\\nBring me the sunset in a cup,\\nCome slowly, Eden!\\nCould I but ride indefinite,\\nCould mortal lip divine\\nDare you see a soul at the white heat?\\nDear March, come in!\\nDeath is a dialogue between\\nDeath is like the insect\\nDeath sets a thing significant\\nDelayed till she had ceased to know,\\nDelight becomes pictorial\\nDeparted to the judgment,\\nDid the harebell loose her girdle\\nDoubt me, my dim companion!\\nDrab habitation of whom?\\nDrowning is not so pitiful\\nEach life converges to some centre\\nEach that we lose takes part of us;\\nElysium is as far as to\\nEssential oils are wrung:\\nExcept the heaven had come so near,\\nExcept to heaven, she is nought;\\nExperiment to me\\nExultation is the going\\nFar from love the Heavenly Father\\nFarther in summer than the birds,\\nFate slew him, but he did not drop;\\nFather, I bring thee not myself, —\\nFew get enough, — enough is one;\\nFinite to fail, but infinite to venture.\\nFor each ecstatic instant\\nForbidden fruit a flavor has\\nFrequently the woods are pink,\\nFrom all the jails the boys and girls\\nFrom cocoon forth a butterfly\\nFrom us she wandered now a year,\\nGiven in marriage unto thee,\\nGlee! The great storm is over!\\nGod gave a loaf to every bird,\\nGod made a little gentian;\\nGod permits industrious angels\\nGoing to heaven!\\n\\\"Going to him! Happy letter! Tell him —\\nGood night! which put the candle out?\\nGreat streets of silence led away\\nHave you got a brook in your little heart,\\nHe ate and drank the precious words,\\nHe fumbles at your spirit\\nHe preached upon \\\"breadth\\\" till it argued him narrow, —\\nHe put the belt around my life, —\\nHe touched me, so I live to know\\nHeart not so heavy as mine,\\nHeart, we will forget him!\\nHeaven is what I cannot reach!\\nHer final summer was it,\\nHigh from the earth I heard a bird;\\nHis bill an auger is,\\nHope is a subtle glutton;\\nHope is the thing with feathers\\nHow dare the robins sing,\\nHow happy is the little stone\\nHow many times these low feet staggered,\\nHow still the bells in steeples stand,\\nHow the old mountains drip with sunset,\\nI asked no other thing,\\nI breathed enough to learn the trick,\\nI bring an unaccustomed wine\\nI can wade grief,\\nI cannot live with you,\\nI died for beauty, but was scarce\\nI dreaded that first robin so,\\nI envy seas whereon he rides,\\nI felt a clearing in my mind\\nI felt a funeral in my brain,\\nI found the phrase to every thought\\nI gained it so,\\nI gave myself to him,\\nI had a daily bliss\\nI had a guinea golden;\\nI had been hungry all the years;\\nI had no cause to be awake,\\nI had no time to hate, because\\nI have a king who does not speak;\\nI have no life but this,\\nI have not told my garden yet,\\nI heard a fly buzz when I died;\\nI held a jewel in my fingers\\nI hide myself within my flower,\\nI know a place where summer strives\\nI know some lonely houses off the road\\nI know that he exists\\nI like a look of agony,\\nI like to see it lap the miles,\\nI live with him, I see his face;\\nI lived on dread; to those who know\\nI lost a world the other day.\\nI many times thought peace had come,\\nI meant to find her when I came;\\nI meant to have but modest needs,\\nI measure every grief I meet\\nI never hear the word \\\"escape\\\"\\nI never lost as much but twice,\\nI never saw a moor,\\nI noticed people disappeared,\\nI read my sentence steadily,\\nI reason, earth is short,\\nI shall know why, when time is over,\\nI should have been too glad, I see,\\nI should not dare to leave my friend,\\nI sing to use the waiting,\\nI started early, took my dog,\\nI stepped from plank to plank\\nI taste a liquor never brewed,\\nI think just how my shape will rise\\nI think the hemlock likes to stand\\nI took my power in my hand.\\nI went to heaven, —\\nI went to thank her,\\nI wish I knew that woman\'s name,\\nI wonder if the sepulchre\\nI worked for chaff, and earning wheat\\nI years had been from home,\\nI\'ll tell you how the sun rose, —\\nI\'m ceded, I\'ve stopped being theirs;\\nI\'m nobody! Who are you?\\nI\'m wife; I\'ve finished that,\\nI\'ve got an arrow here;\\nI\'ve seen a dying eye\\nIf I can stop one heart from breaking,\\nIf I may have it when it\'s dead\\nIf I should die,\\nIf I shouldn\'t be alive\\nIf anybody\'s friend be dead,\\nIf recollecting were forgetting,\\nIf the foolish call them \'flowers,\'\\nIf tolling bell I ask the cause.\\nIf you were coming in the fall,\\nImmortal is an ample word\\nIn lands I never saw, they say,\\nIs Heaven a physician?\\nIs bliss, then, such abyss\\nIt can\'t be summer, — that got through;\\nIt dropped so low in my regard\\nIt is an honorable thought,\\nIt makes no difference abroad,\\nIt might be easier\\nIt sifts from leaden sieves,\\nIt sounded as if the streets were running,\\nIt struck me every day\\nIt tossed and tossed, —\\nIt was not death, for I stood up,\\nIt was too late for man,\\nIt\'s like the light, —\\nIt\'s such a little thing to weep,\\nJust lost when I was saved!\\nLay this laurel on the one\\nLet down the bars, O Death!\\nLet me not mar that perfect dream\\nLife, and Death, and Giants\\nLike mighty footlights burned the red\\nLike trains of cars on tracks of plush\\nLook back on time with kindly eyes,\\nLove is anterior to life,\\nMe! Come! My dazzled face\\nMine by the right of the white election!\\nMine enemy is growing old, —\\nMorning is the place for dew,\\nMorns like these we parted;\\nMuch madness is divinest sense\\nMusicians wrestle everywhere:\\nMy cocoon tightens, colors tease,\\nMy country need not change her gown,\\nMy friend must be a bird,\\nMy life closed twice before its close;\\nMy river runs to thee:\\nMy worthiness is all my doubt,\\nNature rarer uses yellow\\nNature, the gentlest mother,\\nNew feet within my garden go,\\nNo brigadier throughout the year\\nNo rack can torture me,\\nNot any higher stands the grave\\nNot in this world to see his face\\nNot knowing when the dawn will come\\nNot with a club the heart is broken,\\nOf all the souls that stand create\\nOf all the sounds despatched abroad,\\nOf bronze and blaze\\nOf tribulation these are they\\nOn such a night, or such a night,\\nOn the bleakness of my lot\\nOn this long storm the rainbow rose,\\nOn this wondrous sea,\\nOne blessing had I, than the rest\\nOne day is there of the series\\nOne dignity delays for all,\\nOne need not be a chamber to be haunted,\\nOne of the ones that Midas touched,\\nOur journey had advanced;\\nOur lives are Swiss, —\\nOur share of night to bear,\\nPain has an element of blank;\\nPerhaps you\'d like to buy a flower?\\nPigmy seraphs gone astray,\\nPink, small, and punctual,\\nPompless no life can pass away;\\nPoor little heart!\\nPortraits are to daily faces\\nPrayer is the little implement\\nPresentiment is that long shadow on the lawn\\nProud of my broken heart since thou didst break it,\\nRead, sweet, how others strove,\\nRemembrance has a rear and front, —\\nRemorse is memory awake,\\nSafe in their alabaster chambers,\\nShe died, — this was the way she died;\\nShe laid her docile crescent down,\\nShe rose to his requirement, dropped\\nShe slept beneath a tree\\nShe sweeps with many-colored brooms,\\nShe went as quiet as the dew\\nSleep is supposed to be,\\nSo bashful when I spied her,\\nSo proud she was to die\\nSoftened by Time\'s consummate plush,\\nSome keep the Sabbath going to church;\\nSome rainbow coming from the fair!\\nSome things that fly there be, —\\nSome, too fragile for winter winds,\\nSoul, wilt thou toss again?\\nSouth winds jostle them,\\nSplit the lark and you\'ll find the music,\\nStep lightly on this narrow spot!\\nSuccess is counted sweetest\\nSummer for thee grant I may be\\nSuperfluous were the sun\\nSuperiority to fate\\nSurgeons must be very careful\\nSweet hours have perished here;\\nSweet is the swamp with its secrets,\\nTaken from men this morning,\\nTalk with prudence to a beggar\\nThat I did always love,\\nThat is solemn we have ended, —\\nThat short, potential stir\\nThat such have died enables us\\nThe bat is dun with wrinkled wings\\nThe bee is not afraid of me,\\nThe body grows outside, —\\nThe bone that has no marrow;\\nThe brain is wider than the sky,\\nThe brain within its groove\\nThe bustle in a house\\nThe butterfly\'s assumption-gown,\\nThe clouds their backs together laid,\\nThe cricket sang,\\nThe daisy follows soft the sun,\\nThe day came slow, till five o\'clock,\\nThe distance that the dead have gone\\nThe dying need but little, dear, —\\nThe farthest thunder that I heard\\nThe gentian weaves her fringes,\\nThe grass so little has to do, —\\nThe grave my little cottage is,\\nThe heart asks pleasure first,\\nThe last night that she lived,\\nThe leaves, like women, interchange\\nThe moon is distant from the sea,\\nThe moon was but a chin of gold\\nThe morns are meeker than they were,\\nThe mountain sat upon the plain\\nThe murmur of a bee\\nThe murmuring of bees has ceased;\\nThe mushroom is the elf of plants,\\nThe nearest dream recedes, unrealized.\\nThe night was wide, and furnished scant\\nThe one that could repeat the summer day\\nThe only ghost I ever saw\\nThe past is such a curious creature,\\nThe pedigree of honey\\nThe rat is the concisest tenant.\\nThe reticent volcano keeps\\nThe robin is the one\\nThe rose did caper on her cheek,\\nThe show is not the show,\\nThe skies can\'t keep their secret!\\nThe sky is low, the clouds are mean,\\nThe soul selects her own society,\\nThe soul should always stand ajar,\\nThe soul unto itself\\nThe spider as an artist\\nThe springtime\'s pallid landscape\\nThe stimulus, beyond the grave\\nThe sun just touched the morning;\\nThe sun kept setting, setting still;\\nThe thought beneath so slight a film\\nThe way I read a letter \'s this:\\nThe wind begun to rock the grass\\nTheir height in heaven comforts not,\\nThere came a day at summer\'s full\\nThere came a wind like a bugle;\\nThere is a flower that bees prefer,\\nThere is a shame of nobleness\\nThere is a word\\nThere is no frigate like a book\\nThere\'s a certain slant of light,\\nThere\'s been a death in the opposite house\\nThere\'s something quieter than sleep\\nThese are the days when birds come back,\\nThey dropped like flakes, they dropped like stars,\\nThey say that \'time assuages,\' —\\nThey won\'t frown always, — some sweet day\\n This is my letter to the world,\\nThis is the land the sunset washes,\\nThis merit hath the worst, —\\nThis was in the white of the year,\\nThis world is not conclusion;\\nThough I get home how late, how late!\\nThree weeks passed since I had seen her, —\\nThrough the straight pass of suffering\\n\'T is so much joy! \'T is so much joy!\\n\'T is sunrise, little maid, hast thou\\n\'T is whiter than an Indian pipe,\\nTie the strings to my life, my Lord,\\nTo fight aloud is very brave,\\nTo hang our head ostensibly,\\nTo hear an oriole sing\\nTo help our bleaker parts\\nTo know just how he suffered would be dear;\\nTo learn the transport by the pain,\\nTo lose one\'s faith surpasses\\nTo lose thee, sweeter than to gain\\nTo make a prairie it takes a clover and one bee, —\\nTo my quick ear the leaves conferred;\\nTo venerate the simple days\\nTriumph may be of several kinds.\\n\'T is little I could care for pearls\\n\'T was a long parting, but the time\\n\'T was just this time last year I died.\\n\'T was later when the summer went\\n\'T was such a little, little boat\\nTwo butterflies went out at noon\\nTwo swimmers wrestled on the spar\\nUndue significance a starving man attaches\\nUnto my books so good to turn\\nUpon the gallows hung a wretch,\\nVictory comes late,\\nWait till the majesty of Death\\nWater is taught by thirst;\\nWe cover thee, sweet face.\\nWe learn in the retreating\\nWe like March, his shoes are purple,\\nWe never know how high we are\\nWe never know we go, — when we are going\\nWe outgrow love like other things\\nWe play at paste,\\nWe thirst at first, — \'t is Nature\'s act;\\nWent up a year this evening!\\nWhat if I say I shall not wait?\\nWhat inn is this\\nWhat mystery pervades a well!\\nWhat soft, cherubic creatures\\nWhen I hoped I feared,\\nWhen I was small, a woman died.\\nWhen night is almost done,\\nWhen roses cease to bloom, dear,\\nWhere every bird is bold to go,\\nWhere ships of purple gently toss\\nWhether my bark went down at sea,\\nWhile I was fearing it, it came,\\nWho has not found the heaven below\\nWho never lost, are unprepared\\nWho never wanted, — maddest joy\\nWho robbed the woods,\\n\\\"Whose are the little beds,\\\" I asked,\\nWild nights! Wild nights!\\nWill there really be a morning?\\nWithin my reach!\\nYou cannot put a fire out;\\nYou left me, sweet, two legacies, —\\nYou\'ve seen balloons set, haven\'t you?\\nYour riches taught me poverty.\"}]}]', 'en', NULL, '{\"en\":{\"title\":\"Introduction\",\"blocks\":[{\"heading\":false,\"text\":\"Emily Dickinson (1830–1886) wrote 1,775 poems, almost all unpublished in life. Published since 1890, they combine brevity, script and expressive capital.\"},{\"heading\":true,\"text\":\"Short Form\"},{\"heading\":false,\"text\":\"Quartets, hymns and ballads with rhythm of march and pause. The script cuts the verse like a breath.\"},{\"heading\":true,\"text\":\"Obsessions\"},{\"heading\":false,\"text\":\"Death, nature, eternity and mind appear with domestic images — garden, bee, coffin — metaphysical turns.\"},{\"heading\":true,\"text\":\"Reading\"},{\"heading\":false,\"text\":\"You should read quietly and let the pause make sense. Each poem is a minimal scene that expands.\"},{\"heading\":true,\"text\":\"The edition\"},{\"heading\":false,\"text\":\"The local text is in English. This introduction in Spanish provides context without replacing Dickinson\'s words.\"}]},\"es\":{\"title\":\"Introducción\",\"blocks\":[{\"heading\":false,\"text\":\"Emily Dickinson (1830–1886) escribió 1.775 poemas, casi todos inéditos en vida. Publicados desde 1890, combinan brevedad, guion y mayúscula expresiva.\"},{\"heading\":true,\"text\":\"Forma breve\"},{\"heading\":false,\"text\":\"Cuartetas, himnos y baladas con ritmo de marcha y pausa. El guion corta el verso como una respiración.\"},{\"heading\":true,\"text\":\"Obsesiones\"},{\"heading\":false,\"text\":\"Muerte, naturaleza, eternidad y mente aparecen con imágenes domésticas —jardín, abeja, ataúd— vueltas metafísicas.\"},{\"heading\":true,\"text\":\"Cómo leer\"},{\"heading\":false,\"text\":\"Conviene leer en voz baja y dejar que la pausa haga sentido. Cada poema es una escena mínima que se expande.\"},{\"heading\":true,\"text\":\"La edición\"},{\"heading\":false,\"text\":\"El texto local está en inglés. Esta introducción en español ofrece contexto sin reemplazar las palabras de Dickinson.\"}]}}');
INSERT INTO libros (id, titulo, autor, genero, cover, secciones, idioma, fuente, introducciones) VALUES (13608, 'Filosofía Fundamental, Tomo I', 'Jaime Luciano Balmes', 'filosofia', 'https://www.gutenberg.org/cache/epub/13608/pg13608.cover.medium.jpg', '[{\"title\":\"Prólogo\",\"blocks\":[{\"heading\":false,\"text\":\"El título de _Filosofía fundamental_, no significa una pretension vanidosa, sino el objeto de que se trata. No me lisonjeo en _fundar_ de filosofía, pero me propongo examinar sus cuestiones fundamentales; por esto llamo á la obra: _Filosofía fundamental_. Me ha impulsado á publicarla el deseo de contribuir á que los estudios filosóficos adquieran en España mayor amplitud de la que tienen en la actualidad; y de prevenir, en cuanto alcancen mis débiles fuerzas, un grave peligro que nos amenaza: el de introducirsenos una filosofía plagada de errores trascendentales. A pesar de la turbacion de los tiempos, se nota en España un desarrollo intelectual que dentro de algunos años se hará sentir con mucha fuerza; y es preciso guardarnos de que los errores que se han extendido por moda, se arraiguen por principios. Tamaña calamidad solo puede precaverse con estudios sólidos y bien dirigidos: en nuestra época el mal no se contiene con la sola represion; es necesario ahogarle con la abundancia del bien. La presente obra ¿podrá conducir á este objeto? El público lo ha de juzgar.\"},{\"heading\":false,\"text\":\"LIBRO PRIMERO.\"},{\"heading\":false,\"text\":\"DE LA CERTEZA.\"}]},{\"title\":\"CAPÍTULO I\",\"blocks\":[{\"heading\":false,\"text\":\"IMPORTANCIA Y UTILIDAD DE LAS CUESTIONES SOBRE LA CERTEZA\"},{\"heading\":false,\"text\":\"[1.] El estudio de la filosofía debe comenzar por el exámen de las cuestiones sobre la certeza; antes de levantar el edificio es necesario pensar en el cimiento.\"},{\"heading\":false,\"text\":\"Desde que hay filosofía, es decir, desde que los hombres reflexionan sobre sí mismos y sobre los seres que los rodean, se han agitado cuestiones que tienen por objeto la base en que estriban los conocimientos humanos: esto prueba que hay aquí dificultades serias. La esterilidad de los trabajos filosóficos no ha desalentado á los investigadores: esto manifiesta que en el último término de la investigacion, se divisa un objeto de alta importancia.\"},{\"heading\":false,\"text\":\"Sobre las cuestiones indicadas han cavilado los filósofos de la manera mas extravagante; en pocas materias nos ofrece la historia del espíritu humano tantas y tan lamentables aberraciones. Esta consideracion podria sugerir la sospecha de que semejantes investigaciones nada sólido presentan al espíritu y que solo sirven para alimentar la vanidad del sofista. En la presente materia, como en muchas otras, no doy demasiada importancia á las opiniones de los filósofos, y estoy lejos de creer que deban ser considerados como legítimos representantes de la razon humana; pero no se puede negar al menos, que en el órden intelectual son la parte mas activa del humano linaje. Cuando todos los filósofos disputan, disputan en cierto modo la humanidad misma. Todo hecho que afecta al linaje humano es digno de un exámen profundo; despreciarle por las cavilaciones que le rodean, seria caer en la mayor de ellas: la razon y el buen sentido no deben contradecirse, y esta contradiccion existiria si en nombre del buen sentido se despreciara como inútil lo que ocupa la razon de las inteligencias mas privilegiadas. Sucede con frecuencia que lo grave, lo significativo, lo que hace meditar á un hombre pensador, no son ni los resultados de una disputa, ni las razones que en ella se aducen, sino la existencia misma de la disputa. Esta vale tal vez poco por lo que es en sí, pero quizás vale mucho por lo que indica.\"},{\"heading\":false,\"text\":\"[2.] En la cuestion de la certeza están encerradas en algun modo todas las cuestiones filosóficas: cuando se la ha desenvuelto completamente, se ha examinado bajo uno ú otro aspecto todo lo que la razon humana puede concebir sobre Dios, sobre el hombre, sobre el universo. A primera vista se presenta quizás como un mero cimiento del edificio científico: pero en este cimiento, si se le examina con atencion, se ve retratado el edificio entero: es un plano en que se proyectan de una manera muy visible, y en hermosa perspectiva, todos los sólidos que ha de sustentar.\"},{\"heading\":false,\"text\":\"[3.] Por mas escaso que fuere el resultado directo é inmediato de estas investigaciones, es sobre manera útil el hacerlas. Importa mucho acaudalar ciencia, pero no importa menos conocer sus límites. Cercanos á los límites se hallan los escollos, y estos debe conocerlos el navegante. Los límites de la ciencia humana se descubren en el exámen de las cuestiones sobre la certeza.\"},{\"heading\":false,\"text\":\"Al descender á las profundidades á que estas cuestiones nos conducen, el entendimiento se ofusca y el corazon se siente sobrecogido de un religioso pavor. Momentos antes contemplábamos el edificio de los conocimientos humanos, y nos llenábamos de orgullo al verle con sus dimensiones colosales, sus formas vistosas, su construccion galana y atrevida; hemos penetrado en él, se nos conduce por hondas cavidades, y como si nos halláramos sometidos á la influencia de un encanto, parece que los cimientos se adelgazan, se evaporan, y que el soberbio edificio queda flotando en el aire.\"},{\"heading\":false,\"text\":\"[4.] Bien se echa de ver que al entrar en el exámen de la cuestion sobre la certeza no desconozco las dificultades de que está erizada; ocultarlas no seria resolverlas; por el contrario, la primera condicion para hallarles solucion cumplida, es verlas con toda claridad, sentirlas con viveza. Que no se apoca el humano entendimiento por descubrir el borde mas allá del cual no le es dado caminar; muy al contrario esto le eleva y fortalece: así el intrépido naturalista que en busca de un objeto ha penetrado en las entrañas de la tierra, siente una mezcla de terror y de orgullo al hallarse sepultado en lóbregos subterráneos, sin mas luz que la necesaria para ver sobre su cabeza inmensas moles medio desgajadas, y descurrir á sus plantas abismos insondables.\"},{\"heading\":false,\"text\":\"En la oscuridad de los misterios de la ciencia, en la misma incertidumbre, en los asaltos de la duda que amenaza arrebatarnos en un instante la obra levantada por el espíritu humano en el espacio de largos siglos, hay algo de sublime que atrae y cautiva. En la contemplacion de esos misterios se han saboreado en todas épocas los hombres mas grandes: el genio que agitara sus alas sobre el Oriente, sobre la Grecia, sobre Roma, sobre las escuelas de los siglos medios, es el mismo que se cierne sobre la Europa moderna. Platon, Aristóteles, san Agustin, Abelardo, san Anselmo, santo Tomás de Aquino, Luis Vives, Bacon, Descartes, Malebranche, Leibnitz; todos, cada cual á su manera, se han sentido poseidos de la inspiracion filosófica, que inspiracion hay tambien en la filosofía, é inspiracion sublime.\"},{\"heading\":false,\"text\":\"Todo lo que concentra al hombre llamándole á elevada contemplacion en el santuario de su alma, contribuye á engrandecerle, porque le despega de los objetos materiales, le recuerda su alto orígen, y le anuncia su inmenso destino. En un siglo de metálico y de goces, en que todo parece encaminarse á no desarrollar las fuerzas del espíritu, sino en cuanto pueden servir á regalar el cuerpo, conviene que se renueven esas grandes cuestiones, en que el entendimiento divaga con amplísima libertad por espacios sin fin.\"},{\"heading\":false,\"text\":\"Solo la inteligencia se examina á sí propia. La piedra cae sin conocer su caida; el rayo calcína y pulveriza, ignorando su fuerza; la flor nada sabe de su encantadora hermosura; el bruto animal sigue sus instintos, sin preguntarse la razon de ellos; solo el hombre, en frágil organizacion que aparece un momento sobre la tierra para deshacerse luego en polvo, abriga un espíritu que despues de abarcar el mundo, ansía por comprenderse, encerrándose en sí propio, allí dentro, como en un santuario donde él mismo es á un tiempo el oráculo y el consultor. Quién soy, qué hago, qué pienso, por qué pienso, cómo pienso, qué son esos fenómenos que experimento en mí, por qué estoy sujeto á ellos, cuál es su causa, cuál el órden de su produccion, cuáles sus relaciones; hé aquí lo que se pregunta el espíritu; cuestiones graves, cuestiones espinosas, es verdad; pero nobles, sublimes, perenne testimonio de que hay dentro nosotros algo superior á esa materia inerte, solo capaz de recibir movimiento y variedad de formas, de que hay algo que con su actividad íntima, espontánea, radicada en su naturaleza misma, nos ofrece la imágen de la actividad infinita que ha sacado el mundo de la nada con un solo acto de su voluntad[I].\"}]},{\"title\":\"CAPÍTULO II\",\"blocks\":[{\"heading\":false,\"text\":\"VERDADERO ESTADO DE LA CUESTION.\"},{\"heading\":false,\"text\":\"[5.] ¿Estamos ciertos de algo? á esta pregunta responde afirmativamente el sentido comun. ¿En qué se funda la certeza? ¿cómo la adquirimos? estas son dos cuestiones difíciles de resolver en el tribunal de la filosofía.\"},{\"heading\":false,\"text\":\"La cuestion de la certeza encierra tres muy diferentes, cuya confusion contribuye no poco á crear dificultades y á embrollar materias que, aun deslindados con suma exactitud los varios aspectos que presentan, son siempre harto complicadas y espinosas.\"},{\"heading\":false,\"text\":\"Para fijar bien las ideas conviene distinguir con mucho cuidado entre la existencia de la certeza, los fundamentos en que estriba, y el modo con que la adquirimos. Su existencia es un hecho indisputable; sus fundamentos son objeto de cuestiones filosóficas; el modo de adquirirla es en muchos casos un fenómeno oculto que no está sujeto á la observacion.\"},{\"heading\":false,\"text\":\"[6.] Apliquemos esta distincion á la certeza sobre la existencia de los cuerpos.\"},{\"heading\":false,\"text\":\"Que los cuerpos existen, es un hecho del cual no duda nadie que esté en su juicio. Todas las cuestiones que se susciten sobre este punto no harán vacilar la profunda conviccion de que al rededor de nosotros existe lo que llamamos mundo corpóreo: esta conviccion es un fenómeno de nuestra existencia, que no acertaremos quizás á explicar, pero destruirle nos es imposible: estamos sometidos á él como á una necesidad indeclinable.\"},{\"heading\":false,\"text\":\"¿En qué se funda esta certeza? Aquí ya nos hallamos no con un simple hecho, sino con una cuestion que cada filósofo resuelve á su manera: Descartes y Malebranche recurren á la veracidad de Dios; Locke y Condillac se atienen al desarrollo y carácter peculiar de algunas sensaciones.\"},{\"heading\":false,\"text\":\"¿Cómo adquiere el hombre esta certeza? no lo sabe: la poseia antes de reflexionar; oye con extrañeza que se suscitan disputas sobre estas materias; y jamás hubiera podido sospechar que se buscase porque estamos ciertos de la existencia de lo que afecta nuestros sentidos. En vano se le interroga sobre el modo con que ha hecho tan preciosa adquision, se encuentra con ella como con un hecho apenas distinto de su existencia misma. Nada recuerda del órden de las sensaciones en su infancia; se halla con el espíritu desarrollado, pero ignora las leyes de este desarrollo, de la propia suerte que nada conoce de las que han presidido á la generacion y crecimiento de su cuerpo.\"},{\"heading\":false,\"text\":\"[7.] La filosofía debe comenzar no por disputar sobre el hecho de la certeza sino por la explicacion del mismo. No estando ciertos de algo nos es absolutamente imposible dar un solo paso en ninguna ciencia, ni tomar una resolucion cualquiera en los negocios de la vida. Un escéptico completo seria un demente, y con demencia llevada al mas alto grado; imposible le fuera toda comunicacion con sus semejantes, imposible toda serie ordenada de acciones externas, ni aun de pensamientos ó actos de la voluntad. Consignemos pues el hecho, y no caigamos en la extravagancia de afirmar que en el umbral del templo de la filosofía está sentada la locura.\"},{\"heading\":false,\"text\":\"Al examinar su objeto, debe la filosofía analizarle, mas no destruirle; que si esto hace se destruye á sí propia. Todo raciocinio ha de tener un punto de apoyo, y este punto no puede ser sino un hecho. Que sea interno ó externo, que sea una idea ó un objeto, el hecho ha de existir; es necesario comenzar por suponer algo; á este algo le llamamos hecho: quien los niega todos ó comienza por dudar de todos, se asemeja al anatómico que antes de hacer la diseccion quemase el cadáver y aventase las cenizas.\"},{\"heading\":false,\"text\":\"[8.] Entonces la filosofía, se dirá, no comienza por un exámen sino por una afirmacion; sí, no lo niego, y esta es una verdad tan fecunda que su consignacion puede cerrar la puerta á muchas cavilaciones y difundir abundante luz por toda la teoría de la certeza.\"},{\"heading\":false,\"text\":\"Los filósofos se hacen la ilusion de que comienzan por la duda; nada mas falso; por lo mismo que piensan afirman, cuando no otra cosa, su propia duda; por lo mismo que raciocinan afirman el enlace de las ideas, es decir, de todo el mundo lógico.\"},{\"heading\":false,\"text\":\"Fichte, por cierto nada fácil de contentar, al tratarse del punto de apoyo de los conocimientos humanos, empieza no obstante por una afirmacion, y así lo confiesa con una ingenuidad que le honra. Hablando de la reflexion que sirve de base á su filosofía, dice: «Las reglas á que esta reflexion se halla sujeta, no están todavía demostradas; se las supone tácitamente admitidas. En su orígen mas retirado, se derivan de un principio _cuya legitimidad_ no puede ser establecida, sino bajo la condicion de que _ellas sean justas_. Hay un círculo, pero _círculo inevitable_. Y supuesto que es inevitable, y que lo confesamos francamente, es permitido, para asentar el principio mas elevado, _confiarse á todas las leyes de la lógica general_. En el camino donde vamos á entrar con la reflexion, debemos partir de una proposicion cualquiera que nos sea concedida por todo el mundo, sin ninguna contradiccion.» (Fichte, Doctrina de la ciencia, 1.ª parte, § 1).\"},{\"heading\":false,\"text\":\"[9.] La certeza es para nosotros una feliz necesidad; la naturaleza nos la impone, y de la naturaleza no se despojan los filósofos. Vióse un dia Pirron acometido por un perro, y como se deja suponer, tuvo buen cuidado de apartarse, sin detenerse á examinar si aquello era un perro verdadero ó solo una apariencia; riéronse los circunstantes echándole en cara la incongruencia de su conducta con su doctrina, mas Pirron les respondió con la siguiente sentencia que para el caso era muy profunda: «es difícil despojarse totalmente de la naturaleza humana.»\"},{\"heading\":false,\"text\":\"[10.] En buena filosofía, pues, la cuestion no versa sobre la existencia de la certeza, sino sobre los motivos de ella y los medios de adquirirla. Este es un patrimonio de que no podemos privarnos, aun cuando nos empeñemos en repudiar los títulos que nos garantizan su propiedad. ¿Quién no está cierto de que piensa, siente, quiere, de que tiene un cuerpo propio, de que en su alrededor hay otros semejantes al suyo, de que existe el universo corpóreo? Anteriormente á todos los sistemas, la humanidad ha estado en posesion de esta certeza, y en el mismo caso se halla todo individuo, aun cuando en su vida no llegue á preguntarse qué es el mundo, qué es un cuerpo, ni en qué consisten la sensacion, el pensamiento y la voluntad. Despues de examinados los fundamentos de la certeza, y reconocidas las graves dificultades que sobre ellos levanta el raciocinio, tampoco es posible dudar de todo. No ha habido jamás un verdadero escéptico en toda la propiedad de la palabra.\"},{\"heading\":false,\"text\":\"[11.] Sucede con la certeza lo mismo que en otros objetos de los conocimientos humanos. El hecho se nos presenta de bulto, con toda claridad, mas no penetramos su íntima naturaleza. Nuestro entendimiento está abundantemente provisto de medios para adquirir noticia de los fenómenos así en el órden material como en el espiritual, y posee bastante perspicacia para descubrir, deslindar y clasificar las leyes á que están sujetos; pero cuando trata de elevarse al conocimiento de la esencia misma de las cosas, ó investigar los principios en que se funda la ciencia de que se gloría, siente que sus fuerzas se debiliten, y como que el terreno donde fija su planta, tiembla y se hunde.\"},{\"heading\":false,\"text\":\"Afortunadamente el humano linaje está en posesion de la certeza independientemente de los sistemas filosóficos, y no limitada á los fenómenos del alma, sino extendiéndose á cuanto necesitamos para dirigir nuestra conducta con respecto á nosotros y á los objetos externos. Antes que se pensase en buscar si habia certeza, todos los hombres estaban ciertos de que pensaban, querian, sentian, de que tenian un cuerpo con movimiento sometido á la voluntad, y de que existia el conjunto de varios cuerpos que se llama universo. Comenzadas las investigaciones, la certeza ha continuado la misma entre todos los hombres, inclusos los que disputaban sobre ella; ninguno de estos ha podido ir mas allá que Pirron y encontrar fácil el despojarse de la naturaleza humana.\"},{\"heading\":false,\"text\":\"[12.] No es posible determinar hasta qué punto haya alcanzado á producir duda sobre algunos objetos el esfuerzo del espíritu de ciertos filósofos empeñados en luchar con la naturaleza; pero es bien cierto: primero, que ninguno ha llegado á dudar de los fenómenos internos cuya presencia sentia íntimamente; segundo, que si alguno ha podido persuadirse de que á estos fenómenos no les correspondia algun objeto externo, esta habrá sido una excepcion tan extraña que, en la historia de la ciencia y á los ojos de una buena filosofía, no debe tener mas peso que las ilusiones de un maniático. Si á este punto llegó Berkeley al negar la existencia de los cuerpos, haciendo triunfar sobre el instinto de la naturaleza las cavilaciones de la razon, el filósofo de Cloyne, aislado, y en oposicion con la humanidad entera, mereceria el dictado que con razon se aplica á los que se hallan en situacion semejante: la locura por ser sublime no deja de ser locura.\"},{\"heading\":false,\"text\":\"Los mismos filósofos que llevaron mas lejos el escepticismo, han convenido en la necesidad de acomodarse en la práctica á las apariencias de los sentidos, relegando la duda al mundo de la especulacion. Un filósofo disputará sobre todo, cuanto se quiera; pero en cesando la disputa deja de ser filósofo, continúa siendo hombre á semejanza de los demás, y disfruta de la certeza como todos ellos. Asi lo confiesa Hume que negaba con Berkeley la existencia de los cuerpos: «Yo como, dice, juego al chaquete, hablo con mis amigos, soy feliz en su compañía, y cuando despues de dos ó tres horas de diversion vuelvo á estas especulaciones, me parecen tan frias, tan violentas, tan ridiculas, que no tengo valor para continuarlas. Me veo pues absoluta y necesariamente forzado á vivir, hablar y obrar como los demás hombres en los negocios comunes de la vida.» (Tratado de la naturaleza humana, tomo 1.º).\"},{\"heading\":false,\"text\":\"[13.] En las discusiones sobre la certeza es necesario precaverse contra el prurito pueril de conmover los fundamentos de la razon humana. Lo que se debe buscar en esta clase de cuestiones es un conocimiento profundo de los principios de la ciencia y de las leyes que presiden al desarrollo de nuestro espíritu. Empeñarse en destruir estas leyes es desconocer el objeto de la verdadera filosofía; basta que las sometamos á nuestra observacion, de la propia suerte que determinamos las del mundo material sin intencion de trastornar el órden admirable que reina en el universo. Los escépticos que comienzan por dudar de todo para hacer mas sólida su filosofía, se parecen á quien, curioso de observar y fijar con exactitud los fenómenos de la vida, se abriese sin piedad el pecho y aplicase el escalpelo á su corazon palpitante.\"},{\"heading\":false,\"text\":\"La sobriedad es tan necesaria al espíritu para sus adelantos como al cuerpo para su salud; no hay sabiduría sin prudencia, no hay filosofía sin cordura. Existe en el fondo de nuestra alma una luz divina que nos conduce con admirable acierto, si no nos obstinamos en apagarla; su resplandor nos guia, y en llegando al límite de la ciencia nos le muestra, haciéndonos leer con claros caractéres la palabra _basta_. No vayais mas allá; quien la ha escrito es el Autor de todos los seres, el que ha establecido las leyes que rigen al espíritu como al cuerpo, y que contiene en su esencia infinita la última razon de todo.\"},{\"heading\":false,\"text\":\"[14.] La certeza que preexiste á todo exámen no es ciega; antes por el contrario, ó nace de la claridad de la vision intelectual, ó de un instinto conforme á la razon: no es contra la razon, es su basa. Cuando discurrimos, nuestro espíritu conoce la verdad por el enlace de las proposiciones, como si dijéramos por la luz que refleja de unas verdades á otras. En la certeza primitiva, la vision es por luz directa, no necesita de reflexion.\"},{\"heading\":false,\"text\":\"Al consignar pues la existencia de la certeza no hablamos de un hecho ciego, no queremos extinguir la luz en su mismo orígen, antes decimos que allí la luz es mas brillante que en sus raudales. Tenemos á la vista un cuerpo cuyos resplandores iluminan el mundo en que vivimos; si se nos pide que expliquemos su naturaleza y sus relaciones con los demás, ¿comenzaremos por apagarle? Los físicos para buscar la naturaleza de la luz y determinar las leyes á que está sometida, no han comenzado por privarse de la luz misma y ponerse á oscuras.\"},{\"heading\":false,\"text\":\"[15.] Este método de filosofar tiene algo de dogmatismo, pero dogmatismo tal que, como hemos visto, tiene en su apoyo á los mismos Pirron, Hume, Fichte, mal de su grado. No es un simple método filosófico, es la sumision voluntaria á una necesidad indeclinable de nuestra propia naturaleza; es la combinacion de la razon con el instinto, es la atencion simultánea á las diferentes voces que resuenan en el fondo de nuestro espíritu. Pascal ha dicho: «la naturaleza confunde á los pirrónicos, y la razon á los dogmáticos.» Este pensamiento que pasa por profundo, y que lo es bajo cierto aspecto, encierra no obstante alguna inexactitud. La confusion no es igual en ambos casos: la razon no confunde al dogmático si no se la separa de la naturaleza; y la naturaleza confunde al pirrónico, ya sola, ya unida con la razon. El verdadero dogmático comienza por dar á la razon el cimiento de la naturaleza; emplea una razon que se conoce á sí misma, que confiesa la imposibilidad de probarlo todo, que no toma arbitrariamente el postulado que ha menester, sino que lo recibe de la naturaleza misma. Así la razon no confunde al dogmático que guiado por ella busca el fundamento que la puede asegurar. Cuando la naturaleza confunde á los pirrónicos atestigua el triunfo de la razon de los dogmáticos, cuyo argumento principal contra aquellos, es la voz de la misma naturaleza. El pensamiento de Pascal seria mas exacto reformado de esta manera: «La naturaleza confunde á los pirrónicos, y es necesaria á la razon de los dogmáticos.» Habria menos antítesis, pero mas verdad. La necesidad de la naturaleza no la desconocen los dogmáticos; sin esta basa la razon nada puede; para ejercer su fuerza exige un punto de apoyo; con él ofrecia Arquímedes levantar la tierra; sin él la inmensa palanca no hubiera movido un solo átomo (II).\"}]},{\"title\":\"CAPÍTULO III\",\"blocks\":[{\"heading\":false,\"text\":\"DOS CERTEZAS: LA DEL GÉNERO HUMANO Y LA FILOSOFÍA.\"},{\"heading\":false,\"text\":\"[16.] La certeza no nace de la reflexion; es un producto espontáneo de la naturaleza del hombre, y va aneja al acto directo de las facultades intelectuales y sensitivas. Como que es una condicion necesaria al ejercicio de ambas, y que sin ella la vida es un caos, la poseemos instintivamente y sin reflexion alguna, disfrutando de este beneficio del Criador como de los demás que acompañan inseparablemente nuestra existencia.\"},{\"heading\":false,\"text\":\"[17.] Es preciso pues distinguir entre la certeza del género humano, y la filosófica; bien que hablando ingenuamente, no se comprende bastante lo que pueda valer una certeza humana diferente de la del género humano.\"},{\"heading\":false,\"text\":\"Prescindiendo de los esfuerzos que por algunos instantes hace el filósofo para descubrir la base de los humanos conocimientos, es fácil de notar que él mismo se confunde luego con el comun de los hombres. Esas cavilaciones no dejan rastro en su espíritu en lo tocante á la certeza de todo aquello de que está cierta la humanidad. Descubre entonces que no era una verdadera duda lo que sentia, aunque quizás él mismo se hiciese la ilusion de lo contrario; eran simples suposiciones, nada mas. En interrumpiendo la meditacion, y aun si bien se observa, mientras ella dura, se halla tan cierto como el mas rústico, de sus actos interiores, de la existencia del cuerpo propio, de los demás que rodean el suyo, y de mil otras cosas que constituyen el caudal de conocimiento necesario para los usos de la vida.\"},{\"heading\":false,\"text\":\"Desde el niño de pocos años hasta el varon de edad provecta y juicio maduro, preguntadles sobre la certeza de la existencia propia, de sus actos, internos y externos, de los parientes y amigos, del pueblo en que residen y de otros objetos que han visto, ó de que han oido hablar, no observaréis vacilacion alguna; y lo que es mas, ni diferencia de ninguna clase, entre los grados de semejante certeza; de modo que si no tienen noticia de las cuestiones filosóficas que sobre estas materias se agitan, leeréis en sus semblantes la admiracion y el asombro de que haya quien pueda ocuparse seriamente en averiguar cosas tan _claras_.\"},{\"heading\":false,\"text\":\"[18.] Como no es posible saber de qué manera se van desenvolviendo las facultades sensitivas intelectuales y morales de un niño, no es dable tampoco demostrar _á priori_, por el análisis de las operaciones que en su espíritu se realizan, que á la formacion de la certeza no concurren los actos reflejos; pero no será difícil demostrarlo por los indicios que de sí arroja el ejercicio de estas facultades, cuando ya se hallan en mucho desarrollo.\"},{\"heading\":false,\"text\":\"Si bien se observa, las facultades del niño tienen un hábito de obrar en un sentido directo, y no reflejo, lo cual manifiesta que su desarrollo no se ha hecho por reflexion, sino directamente.\"},{\"heading\":false,\"text\":\"Si el desarrollo primitivo fuese por reflexion, la fuerza reflexiva seria grande; y sin embargo no sucede así: son muy pocos los hombres dotados de esta fuerza, y en la mayor parte es poco menos que nula. Los que llegan á tenerla, la adquieren con asiduo trabajo, y no sin haberse violentado mucho, para pasar del conocimiento directo al reflejo.\"},{\"heading\":false,\"text\":\"[19.] Enseñad á un niño un objeto cualquiera y lo percibe bien; pero llamadle la atencion sobre la percepcion misma, y desde luego su entendimiento se oscurece y se confunde.\"},{\"heading\":false,\"text\":\"Hagamos la experiencia. Supongamos un niño á quien se enseñan los rudimentos de la geometría.--¿Ves esta figura, que se cierra con las tres líneas? Esto se llama triángulo: las líneas tienen el nombre de lados, y esos puntos donde se reunen las líneas se apellidan vértices de sus ángulos.--Lo comprendo bien.--¿Ves esa otra que se cierra con cuatro líneas? es un cuadrilátero; el cual como el triángulo, tiene tambien sus lados y sus vértices.--Muy bien.--¿Un cuadrilátero puede ser triángulo ó vice-versa?--Nó señor.--Jamás?--Jamás.--¿Y por qué?--¿No ve V. que aqui hay cuatro y aqui tres lados? ¿cómo pueden ser una misma cosa?--Pero quién sabe?..... á tí te lo parece..... pero.....--¿Nó señor, no lo ve V. aqui? este tres, ese otro cuatro, y no es lo mismo cuatro que tres.\"},{\"heading\":false,\"text\":\"Atormentad el entendimiento del niño tanto como querais, no le sacaréis de su tema: siempre notaréis su percepcion y su razon obrando en sentido directo, esto es, fijándose sobre el objeto; pero no lograréis que por sí solo dirija la atencion á los actos interiores, que piense en su pensamiento, que combine ideas reflejas, ni que en ellas busque la certeza de su juicio.\"},{\"heading\":false,\"text\":\"[20.] Y hé aquí un defecto capital del arte de pensar, tal como se ha enseñado hasta ahora. A una inteligencia tierna, se la ejercita luego con lo mas difícil que ofrece la ciencia, el reflexionar: lo que es tan desacertado como si se comenzase el desarrollo material del niño, por los ejercicios mas arduos de la gimnástica. El desarrollo científico del hombre se ha de fundar sobre el natural, y este no es reflejo sino directo.\"},{\"heading\":false,\"text\":\"[21.] Aplíquese la misma observacion al uso de los sentidos.\"},{\"heading\":false,\"text\":\"¿Oye Vd. qué música? dice el niño.--Cómo, qué música?--No oye Vd.? está Vd. sordo?--A tí te lo parece.--Pero señor, ¡si se oye tan bien!... ¿cómo es posible?--Pero, ¿cómo lo sabes?--Señor si lo oigo!.....\"},{\"heading\":false,\"text\":\"Y de ese _lo oigo_ no se le podrá sacar, y no lograréis que vacile, ni que para deshacerse de las importunidades apele á ningun acto reflejo: «yo la oigo; ¿no la oye Vd.?» para él no hay mas razon, y toda vuestra filosofía no valdría tanto como la _irresistible fuerza_ de la sensacion que le asegura de que hay música, y que quien lo dude, ó se chancea ó está sordo.\"},{\"heading\":false,\"text\":\"[22.] Si las facultades del niño se hubiesen desarrollado en una alternativa de actos directos y reflejos, si al irse cerciorando de las cosas hubiese pensado en algo mas que en las cosas mismas, claro es que una continuacion de actos semejantes hubiera dejado huella en su espíritu, y que al encontrarse en una situacion apremiadora en que se le preguntaban los motivos de su certeza, hubiera echado mano de los mismos medios que le sirvieron en el sucesivo desarrollo de sus facultades, se hubiera desentendido del objeto, se hubiera replegado sobre sí mismo, y de un modo ú otro habria pensado en su pensamiento, y contestado á la dificultad en el mismo sentido. Nada de esto sucede; lo que indica que no han existido tales actos reflejos, que no ha habido mas que las percepciones acompañadas de la conciencia íntima y de la certeza de ellas; pero todo en confuso, de una manera instintiva, sin nada que parecerse pudiera á reflexiones filosóficas.\"},{\"heading\":false,\"text\":\"[23.] Y es de notar que lo que acontece al niño, se verifica tambien en los hombres adultos, por claro y despejado que sea su entendimiento. Si no están iniciados en las cuestiones filosóficas, recibiréis á poca diferencia las mismas respuestas al proponerles dificultades sobre los expresados objetos, y aun sobre muchísimos otros en que al parecer podria caber mas duda. La experiencia prueba mejor que todos los discursos, que nadie adquiere la certeza por acto reflejo.\"},{\"heading\":false,\"text\":\"[24.] Dicen los filósofos que las fuentes de la certeza son el sentido íntimo ó la conciencia de los actos, los sentidos exteriores, el sentido comun, la razon, la autoridad. Veamos con algunos ejemplos lo que hay de reflejo en todas estas fuentes, cómo piensa el comun de los hombres, y hasta los mismos filósofos, cuando no piensan como filósofos sino como hombres.\"},{\"heading\":false,\"text\":\"[25.] Una persona de entendimiento claro, pero sin noticia de las cuestiones sobre la certeza, acaba de ver un monumento que deja en el alma una impresion viva y duradera, _el Escorial_ por ejemplo. Al ponderar lo grato del recuerdo, suscitadle dudas sobre la existencia de este en su espíritu, y su correspondencia, ya con el acto pasado de ver, ya con el edificio visto; es bien seguro que si no piensa que os chanceais, le desconcertaréis completamente haciéndole sospechar que habeis perdido el juicio. Entre cosas tan diferentes como son: la existencia actual del recuerdo, su correspondencia con el acto pasado de ver, y la conveniencia de todo con el edificio visto, él no descubre diferencia alguna. Para este caso no sabe mas que un niño de seis años: «me acuerdo; lo vi; es tal como lo recuerdo:» hé aquí toda su ciencia; nada de reflexion, nada de separacion, todo directo y simultáneo.\"},{\"heading\":false,\"text\":\"Haced las suposiciones que bien os parezcan, no sacaréis del comun de los hombres, con respecto al sentido íntimo, mas que lo que habeis sacado del recuerdo del Escorial: «es asi y no hay mas.» Aquí no hay actos reflejos, la certeza acompaña al directo; y todas las reflexiones filosóficas no son capaces de añadir un adarme de seguridad, á la que nos da la fuerza misma de las cosas, el instinto de la naturaleza.\"},{\"heading\":false,\"text\":\"[26.] Ejemplo del testimonio de los sentidos.\"},{\"heading\":false,\"text\":\"Se presenta á nuestros ojos un objeto cualquiera, y si está á la correspondiente distancia y con la luz suficiente, juzgamos luego de su tamaño, figura y color; quedándonos muy seguros de la verdad de nuestro juicio, aun cuando en nuestra vida no hayamos pensado en las teorías de las sensaciones, ni en las relaciones de nuestros órganos entre sí y con los objetos externos. Ningun acto reflejo acompaña la formacion del juicio; todo se hace instintivamente, sin que intervengan consideraciones filosóficas. Lo vemos y nada mas; esto nos basta para la certeza. Solo despues de haber manejado los libros donde se ventilan semejantes cuestiones, volvemos la atencion sobre nuestros actos; y aun es de notar, que esta atencion dura, interin nos ocupamos del análisis científico; pues en olvidándonos de esto, lo que sucede bien pronto, entramos de nuevo en la corriente universal, y solo echamos mano de la filosofía en casos muy contados.\"},{\"heading\":false,\"text\":\"Nótese que aquí se habla de la certeza del juicio formado á consecuencia de la sensacion, solo en cuanto está ligado con los usos de la vida, y de ninguna manera en lo tocante á su mayor ó menor exactitud con respecto á la naturaleza de las cosas. Así, poco importa que los colores por ejemplo, sean considerados como calidades inherentes á los cuerpos, aun cuando esto sea ilusion; basta que el juicio formado no altere en nada nuestras relaciones con los objetos, sea cual fuere la teoría filosófica.\"},{\"heading\":false,\"text\":\"[27.] Ejemplo del sentido comun.\"},{\"heading\":false,\"text\":\"En presencia de un concurso numeroso, arrojad á la aventura en el suelo un cajon de caractéres de imprenta, y decid á los circunstantes que resultarán escritos los nombres de todos ellos; por unanimidad se reirán de vuestra insensatez; y ¿en qué se fundan? ¿han reflexionado sobre el fundamento de su certeza? Nó, de seguro.\"},{\"heading\":false,\"text\":\"[28.] Ejemplo de la razon.\"},{\"heading\":false,\"text\":\"Todos raciocinamos, y en muchos casos con acierto. Sin arte, sin reflexion de ninguna clase, distinguimos con frecuencia lo sólido de lo fútil, lo sofístico de lo concluyente. Para esto no necesitamos atender al curso que sigue nuestro entendimiento; sin advertirlo siquiera nos vamos por el buen camino; y tal hombre habrá formado en su vida millones de raciocinios muy rigurosos y exactos, que no habrá atendido una sola vez al modo con que raciocina. Aun los mas versados en el artificio de la dialéctica se olvidan á menudo de ella; la practican quizás muy bien, pero sin atender expresamente á ninguna de sus reglas.\"},{\"heading\":false,\"text\":\"[29.] Los ideólogos escriben volúmenes enteros sobre las operaciones de nuestro entendimiento; y estas operaciones las ejecuta el hombre mas rústico sin pensar que las hace. ¡Cuánto no se ha escrito sobre la abstraccion, sobre la generalizacion, sobre los universales! Y no hay hombre que no tenga todo esto muy bien arreglado en su cabeza, aunque no sepa que existe una ciencia que lo examina. En su lenguaje, hallaréis expresado lo universal y lo particular, notaréis que en su discurso cada cosa ocupa el puesto que le corresponde; sus actos directos no le ofrecen dificultad. Pero llamadle la atencion sobre esos mismos actos, sobre la abstraccion por ejemplo: lo que en el órden directo del pensamiento era tan claro y luminoso, se convierte en un caos al pasar al órden reflejo.\"},{\"heading\":false,\"text\":\"Se echa pues de ver que en el medio de suyo mas reflexivo, cual es el raciocinio, obra muy poco la reflexion, que tiene por objeto el mismo acto que se ejerce.\"},{\"heading\":false,\"text\":\"[30.] Ejemplo de la autoridad.\"},{\"heading\":false,\"text\":\"Ningun habitante de paises civilizados ignora que existe una nacion llamada _Inglaterra_; y la mayor parte de ellos, no lo saben sino por haberlo oido ó leido, es decir, por autoridad. Claro es que la certeza de la existencia de la Inglaterra es tanta, que no la excede la de los mismos objetos que se tienen á la vista; y sin embargo, ¿cuántos son los que han pensado en el análisis de los fundamentos en que se apoya semejante certeza? Muy pocos. ¿Y esta será mayor en los que se hayan ocupado de ella que en los demás? Nó, seguramente. Luego en el presente caso y otros infinitos análogos, para nada intervienen los actos reflejos; la certeza se forma instintivamente, sin el auxilio de ningun medio parecido á los filosóficos.\"},{\"heading\":false,\"text\":\"[31.] Estos ejemplos manifiestan que la humanidad en lo tocante á la certeza, anda por caminos muy diferentes de los de la filosofía: el Criador que ha sacado de la nada á los seres, los ha provisto de lo necesario para ejercer sus funciones segun el lugar que ocupan en el universo; y una de las primeras necesidades del ser inteligente era la certeza de algunas verdades. ¿Qué seria de nosotros si al comenzar á recibir impresiones, al germinar en nuestro entendimiento las primeras ideas, nos encontrásemos con el fatigoso trabajo de labrar un sistema que nos pusiese á cubierto de la incertidumbre? Si así fuese, nuestra inteligencia moriria al nacer; porque envuelta en el caos de sus propias cavilaciones en el momento de abrir los ojos á la luz, y cuando sus fuerzas son todavía tan escasas, no alcanzaria á disipar las nubes que se levantarian de todos lados, y acabarian por sumirla en una completa oscuridad.\"},{\"heading\":false,\"text\":\"Si los filósofos mas aventajados, si las inteligencias mas claras y penetrantes, si los genios de mas pujanza y brio, han trabajado con tan escaso fruto por asentar los principios sólidos que pudiesen servir de fundamento á las ciencias, ¿qué sucediera si el Criador no hubiese acudido á esta necesidad, proveyendo de certeza á la tierna inteligencia, del propio modo que para la conservacion del cuerpo ha preparado el aire que le vivifica, y la leche que le alimenta?\"},{\"heading\":false,\"text\":\"[32.] Si alguna parte de la ciencia debe ser considerada como puramente especulativa, es sin duda la que versa sobre la certeza: y esta proposicion por mas que á primera vista parezca una paradoja, es sin embargo una verdad nada difícil de demostrar.\"},{\"heading\":false,\"text\":\"[33.] ¿Qué puede proponerse en este particular la filosofía? ¿Producir la certeza? Esta existe, independiente de todos los sistemas filosóficos: nadie habia pensado en semejantes cuestiones, cuando la humanidad estaba ya cierta de infinitas cosas. Todavía mas: despues de suscitada la cuestion, han sido pocos los que se han ocupado de ella, comparados con la totalidad del género humano: lo mismo sucede ahora, y sucederá en adelante. Luego cuantas teorías se excogiten sobre este punto en nada pueden influir en el fenómeno de la certeza. Lo que se dice con respecto á producirla, puede extenderse al intento de consolidarla. ¿Cuándo han tenido ó tendrán ni ocasion ni tiempo el comun de los hombres, para ocuparse de semejantes cuestiones?\"},{\"heading\":false,\"text\":\"[34.] Si algo hubiera podido producir la filosofía en esta parte, habria sido el escepticismo; pues que la variedad y oposicion de los sistemas eran mas propias para engendrar dudas que para disiparlas. Afortunadamente, la naturaleza se resiste al escepticismo de una manera insuperable; y los sueños del gabinete de los sabios no trascienden á los usos de la vida del comun de los hombres, ni aun de los mismos que los padecen ó los fingen.\"},{\"heading\":false,\"text\":\"[35.] El objeto mas razonable que en esta cuestion puede proponerse la filosofía es el examinar simplemente los cimientos de la certeza, solo con la mira de conocer mas á fondo al espíritu humano, sin lisonjearse de producir ninguna alteracion en la práctica: á la manera que los astrónomos observan la carrera de los astros, y procuran averiguar y determinar las leyes á que está sujeta, sin que por esto presuman poder modificarlas.\"},{\"heading\":false,\"text\":\"[36.] Mas aun en esta suposicion, se halla la filosofía en situacion nada satisfactoria: porque si recordamos lo que arriba se lleva establecido, echaremos de ver que la ciencia observa un fenómeno real y verdadero, pero le da una explicacion gratuita, haciendo de él un análisis imaginario.\"},{\"heading\":false,\"text\":\"En efecto, se ha demostrado con la experiencia que nuestro entendimiento no se guia por ninguna de las consideraciones que tienen presentes los filósofos; su asenso, en los casos en que va acompañado de mayor certeza, es un fruto espontáneo de un instinto natural, no de combinaciones; una adhesion firme arrancada por la evidencia de la verdad, ó la fuerza del sentido íntimo ó el impulso del instinto, no una conviccion producida por una serie de raciocinios; luego esas combinaciones y raciocinios, solo existen en la mente del filósofo, mas no en la realidad; luego cuando se quieren señalar los cimientos de la certeza, se indica lo que tal vez pudiera ó debiera haber, pero no lo que hay.\"},{\"heading\":false,\"text\":\"Si los filósofos se guiasen por sus sistemas y no se olvidasen ó no prescindiesen de ellos, tan pronto como acaban de explicarlos, y aun mientras los explican, pudiera decirse que si no se da razon de la certeza humana, se da de la certeza filosófica; pero limitándose los mismos filósofos á usar de sus medios científicos, solo cuando los desenvuelven en sus cátedras, resulta que los pretendidos cimientos son una pura título que poco ó nada tiene que ver con la realidad de las cosas.\"},{\"heading\":false,\"text\":\"[37.] Esta demostracion de la vanidad de los sistemas filosóficos en lo tocante á los fundamentos de la certeza, lejos de conducir al escepticismo, lleva á un punto directamente opuesto: porque haciéndonos apreciar en su justo valor la vanidad de las cavilaciones humanas, y comparando su impotencia con la irresistible fuerza de la naturaleza, nos aparta del necio orgullo de sobreponernos á las leyes dictadas por el Criador á nuestra inteligencia, nos hace entrar en el cauce por donde corre la humanidad en el torrente de los siglos, y nos inclina á aceptar con una filosofía juiciosa, lo mismo que de todos modos nos fuerzan á aceptar las leyes de nuestra naturaleza (III).\"}]},{\"title\":\"CAPÍTULO IV\",\"blocks\":[{\"heading\":false,\"text\":\"SI EXISTE LA CIENCIA TRASCENDENTAL EN EL ÓRDEN INTELECTUAL ABSOLUTO.\"},{\"heading\":false,\"text\":\"[38.] Los filósofos han buscado un primer principio de los conocimientos humanos: cada cual le ha señalado á su manera, y despues de tanta discusion, todavía es dudoso quién ha acertado, y hasta si ha acertado nadie.\"},{\"heading\":false,\"text\":\"Antes de preguntar cuál era el primer principio, era necesario saber si existia. Esta última cuestion no puede suponerse resuelta en sentido afirmativo, pues como veremos luego, es susceptible de diferentes resoluciones segun el aspecto bajo el cual se la mira.\"},{\"heading\":false,\"text\":\"El primer principio de los conocimientos puede entenderse de dos maneras: ó en cuanto significa una verdad única de la cual nazcan todas las demás; ó en cuanto expresa una verdad cuya suposicion sea necesaria, si no se quiere que desaparezcan todas las otras. En el primer sentido se busca un manantial del cual nazcan todas las aguas que riegan una campiña; en el segundo, se pide un punto de apoyo para afianzar sobre él un gran peso.\"},{\"heading\":false,\"text\":\"[39.] ¿Existe una verdad de la cual dimanen todas las otras? En la realidad, en el órden de los seres, en el órden intelectual universal, sí; en el órden intelectual humano, nó.\"},{\"heading\":false,\"text\":\"[40.] En el órden de los seres hay una verdad orígen de todas; porque la verdad es la realidad, y hay un Ser, autor de todos los seres. Este ser es una verdad, la verdad misma, la plenitud de verdad; porque es el ser por esencia, la plenitud del ser.\"},{\"heading\":false,\"text\":\"Esta unidad de orígen la han reconocido en cierto modo todas las escuelas filosóficas. Los ateos hablan de la fuerza de la naturaleza, los panteistas, de la sustancia única, de lo absoluto, de lo incondicional; unos y otros han abandonado la idea de Dios, y trabajan por reemplazarla con algo que sirva de orígen á la existencia del universo y al desarrollo de sus fenómenos.\"},{\"heading\":false,\"text\":\"[41.] En el órden intelectual universal hay una verdad de la cual dimanan todas; es decir, que esa unidad de orígen de todas las verdades, no solo se halla en las verdades realizadas, ó en los seres considerados en sí mismos, sino tambien en el encadenamiento de ideas que representan á estos seres. Por manera que si nuestro entendimiento pudiese elevarse al conocimiento de todas las verdades, abrazándolas en su conjunto, en todas las relaciones que las unen, veria que á pesar de la dispersion en que se nos ofrecen en las direcciones mas remotas y divergentes, en llegando á cierta altura van convergiendo á un centro, en el cual se enlazan, como las madejas de luz en el punto luminoso que las despide.\"},{\"heading\":false,\"text\":\"[42.] Los teólogos al paso que explican los dogmas de la Iglesia, siembran á menudo en sus tratados doctrinas filosóficas muy profundas. Así santo Tomás en sus cuestiones sobre el entendimiento de los ángeles, y en otras partes de sus obras, nos ha dejado una teoría muy interesante y luminosa. Segun él, á proporcion que los espíritus son de un órden superior, entienden por un menor número de ideas; y así continúa la disminucion hasta llegar á Dios, que entiendo por medio de una idea única, que es su misma esencia. De esta suerte segun el Santo Doctor, hay no solo un ser autor de todos los seres, sino tambien una idea única, infinita, que las encierra todas. Quien la posea plenamente lo verá todo en ella; pero como esta plenitud, que en términos teológicos se llama comprension, es propia únicamente de la inteligencia infinita de Dios, las criaturas cuando en la otra vida alcancen la vision beatífica, que consiste en la intuicion de la esencia divina, verán mas ó menos objetos en Dios segun sea la mayor ó menor perfeccion con que le posean. ¡Cosa admirable! El dogma de la vision beatífica bien examinado, es tambien una verdad que derrama torrentes de luz sobre las teorías filosóficas! El sueño sublime de Malebranche sobre las ideas, era quizás una reminiscencia de sus estudios teológicos.\"},{\"heading\":false,\"text\":\"[43.] La ciencia trascendental, que las abraza y explica todas, es una quimera para nuestro espíritu mientras habita sobre la tierra; pero es una realidad para otros espíritus de un órden superior, y lo será para el nuestro cuando desprendido del cuerpo mortal, llegue á las regiones de la luz.\"},{\"heading\":false,\"text\":\"[44.] En cuanto podemos conjeturar por analogías, tenemos pruebas de que existe en efecto esa ciencia trascendental que las encierra todas, y que á su vez se refunde en un solo principio, ó mejor, en una sola idea, en una sola intuicion. Observando la escala de los seres, los grados en que están distribuidas las inteligencias individuales, y el sucesivo progreso de las ciencias, se nos presenta la imágen de esta verdad de una manera muy notable.\"},{\"heading\":false,\"text\":\"Uno de los caractéres distintivos de la inteligencia es el generalizar, el percibir lo comun en lo vario, el reducir lo múltiplo á la unidad; y esta fuerza es proporcional al grado de inteligencia.\"},{\"heading\":false,\"text\":\"[45.] El bruto está limitado á sus sensaciones, y á los objetos que se las causan. Nada de generalizar, nada de clasificar, nada que se eleve sobre la impresion recibida, y el instinto de satisfacer sus necesidades. El hombre, tan pronto como abre los ojos de su inteligencia, percibe desde luego un sinnúmero de relaciones; lo que ha visto en un caso lo aplica á otros diferentes: generaliza, encerrando en una idea muchísimas otras. Quiere el niño alcanzar un objeto, no puede llegar á él; y al instante improvisa su escalera arrimando una silla ó un banquillo. Un bruto estará mirando largas horas la tajada que le hechiza, pero que está colgada demasiado alto, sin que le ocurra que pudiera practicar la misma operacion que el niño, y formar una escalera. Si se le disponen los objetos á propósito para subir, sube; pero es incapaz de pensar que en situaciones semejantes se debe ejecutar la misma operacion. En un caso vemos un ser que tiene la idea general de un _medio_ y de sus relaciones con el _fin_, y que cuando la necesita la emplea; en el segundo, vemos otro ser que tiene delante de sus ojos el fin y el medio, pero que no percibe su relacion, y que por consiguiente no se eleva sobre la individualidad material de los objetos.\"},{\"heading\":false,\"text\":\"En el primero hay la percepcion de la unidad; en el segundo, no hay ningun lazo que reuna la variedad de los hechos particulares.\"},{\"heading\":false,\"text\":\"En este ejemplo tan sencillo se nota que la infinidad de casos, en que por estar el objeto demasiado alto ofrece dificultad el alcanzarle, los tiene reducidos el niño á uno solo: posee por decirlo así la fórmula del pequeño problema.\"},{\"heading\":false,\"text\":\"Por cierto que él no se da cuenta á sí mismo de esta fórmula, es decir que no hace acto reflejo sobre ella: pero en la realidad la tiene, y la prueba es, que en ofreciéndose el caso, la aplica instantáneamente. Aun mas: no le pongais delante un objeto determinado, y habladle en general de cosas demasiado altas, indicándole velozmente unas tras otras; veréis que con la rapidez del relámpago aplica siempre la idea general de un medio auxiliar. Serán los brazos de sus padres, ó de un hermano mayor, ó de un criado; será una silla si está en su casa, será un monton de piedras si se halla en el campo; de todo se vale, en todo descubre la _relacion del medio con el fin_. Cuando el fin se presenta, su atencion se vuelve instantáneamente hácia el medio; la idea general, busca un caso en que individualizarse.\"},{\"heading\":false,\"text\":\"[46.] ¿Qué es un arte? ¿es un conjunto de reglas para hacer bien alguna cosa? ¿y cuándo es mas perfecto? lo es tanto mas, cuanto encierra mayor número de casos en cada regla, y por consiguiente cuanto es menor el número de estas. Antes de que se hubiesen formulado las de la arquitectura, se habian construido sin duda edificios sólidos, hermosos, y adaptados al uso á que se destinaban: pero el gran progreso de la inteligencia en lo relativo á la construccion de edificios consistió en encontrar lo que tenian de _comun_ los bien construidos; en fijar la causa de la solidez y de la belleza en sí mismas, pasando de lo individual á lo universal, es decir, formándose ideas generales de solidez y de belleza aplicables á un sinnumero de casos particulares: simplificando.\"},{\"heading\":false,\"text\":\"[47.] Lo dicho de la arquitectura, puede extenderse á las demás artes liberales y mecánicas: en todas se encontrará que el adelanto de la inteligencia se cifra en reducir á la unidad la multiplicidad, en hacer que en el menor número de ideas posible, se encierre el mayor número de aplicaciones posible. Por esta razon los amantes de las letras y de las bellas artes, se afanan en busca de la idea de la belleza en general, con la mira de encontrar un tipo aplicable á todos los objetos literarios y artísticos. Tambien podemos observar que los que se ocupan de artes mecánicas, discurren siempre por reducir sus procedimientos á pocas reglas, y aquel se tiene por mas adelantado que alcanza á combinar mayor variedad de los productos con mas sencillez en los medios, haciendo depender de una sola idea lo que otros tienen vinculado con muchas. Al contemplar una máquina que nos da admirables productos con una combinacion muy sencilla, no tributamos menos elogios al artífice por lo segundo que por lo primero: «esto es magnífico, decimos, y lo mas asombroso es la sencillez con que se ejecuta.»\"},{\"heading\":false,\"text\":\"[48.] Hagamos aplicacion de esta doctrina á las ciencias naturales y exactas.\"},{\"heading\":false,\"text\":\"El mérito del sistema actual de numeracion consiste en encerrar en una sola idea la espresion de todos los números, haciendo el valor de cada guarismo, décuplo del que tiene á la derecha, y supliendo los huecos con el cero. La expresion de la infinidad de los números, está reducida á una sola regla, fundada en una sola idea: la relacion del lugar con el décuplo del valor. La aritmética ha hecho un grande adelanto disminuyendo el número de sus operaciones fundamentales por medio de los logaritmos: reduciendo á sumar y restar las de multiplicar y dividir. El álgebra no es mas que la generalizacion de las expresiones y operaciones aritméticas: su simplificacion. La aplicacion del álgebra á la geometría, es la generalizacion de las expresiones geométricas: las fórmulas de las líneas, de las figuras, de los cuerpos, no son mas que la expresion de su idea universal. En ella, como en un tipo conserva el geómetra la idea matriz, generadora, bástanle las aplicaciones mas sencillas para formar cálculos exactos de todas las líneas de la misma clase que puedan ofrecérsele en la práctica. En la sencilla expresion dz/dx = A, apellidada coeficiente diferencial, se encierra la idea matriz del cálculo infinitesimal; ella dimanó de consideraciones geométricas, pero tan pronto como fué concebida en su universalidad, esparció sobre todos los ramos de las matemáticas y de las ciencias naturales un raudal de luz que hizo descubrir un nuevo mundo cuyos confines no se alcanzan. La prodigiosa fecundidad de este cálculo dimana de su simplicidad, de que generaliza por decirlo así de un golpe la misma álgebra y la geometría, reuniéndolas en un solo punto que es la relacion de los límites de las diferencias de toda funcion.\"},{\"heading\":false,\"text\":\"[49.] Esta unidad de idea, es el objeto de la ambicion de la humana inteligencia, y una vez encontrada es el manantial de los mayores adelantos. La gloria de los genios mas grandes se ha cifrado en descubrirla; el progreso de las ciencias ha consistido en aprovecharla. Vieta expone y aplica el principio de la expresion general de las cantidades aritméticas; Descartes hace lo mismo con respecto á las geométricas; Newton asienta el principio de la gravitacion universal; él propio, al mismo tiempo que Leibnitz, inventa el cálculo infinitesimal; y las ciencias naturales y exactas alumbradas por una grande antorcha marchan á pasos agigantados por caminos antes desconocidos. ¿Y por qué? porque la inteligencia se ha aproximado á la unidad, ha entrado en posesion de una idea matriz en que se encierran otras infinitas.\"},{\"heading\":false,\"text\":\"[50.] Es digno de notarse que á medida que se va adelantando en las ciencias se encuentran entre ellas numerosos puntos de contacto, estrechas relaciones que á primera vista nadie hubiera podido sospechar. Cuando los matemáticos antiguos se ocupaban de las secciones cónicas estaban muy lejos de creer que la idea de la elipse hubiese de servir de base á un sistema astronómico; los focos eran simples puntos, la curva una línea y nada mas; las relaciones de aquellos con esta, eran objeto de combinaciones estériles, sin aplicacion. Siglos despues esos focos son el sol, y la curva las órbitas de los planetas. Las líneas de la mesa del geómetra representaban un mundo!.....\"},{\"heading\":false,\"text\":\"El íntimo enlace de las ciencias matemáticas con las naturales es un hecho fuera de duda; ¿y quién sabe hasta qué punto se enlazan unas y otras con las ontológicas, psicológicas, teológicas y morales? La dilatada escala en que están distribuidos los seres, y que á primera vista pudiera parecer un conjunto de objetos inconexos, va manifestándose á los ojos de la ciencia como una cadena delicadamente trabajada cuyos eslabones presentan sucesivamente mayor belleza y perfeccion. Los diferentes reinos de la naturaleza se muestran enlazados con íntimas relaciones; así las ciencias que los tienen por objeto, se prestan recíprocamente sus luces, y entran alternativamente la una en el terreno de la otra. La complicacion de los objetos entre sí, trae consigo esa complicacion de conocimientos; y la unidad de las leyes que rigen diferentes órdenes de seres, aproximan todas las ciencias y las encaminan á formar una sola. ¡Quién nos diera ver la identidad de orígen, la unidad del fin, la sencillez de los caminos! Entonces poseeríamos la verdadera ciencia trascendental, la ciencia única, que las encierra todas; ó mejor diremos, la idea única en que todo se pinta tal como es, en que todo se ve sin necesidad de combinar, sin esfuerzo de ninguna clase, como en un clarísimo espejo se retrata un magnífico paisage, con su tamaño, figura y colores! Entretanto, nos es preciso contentarnos con sombras de la realidad; y en el instinto de nuestro entendimiento para simplificar, para reducirlo todo ó aproximarlo cuando menos á la unidad, debemos ver el indicio, el anuncio, de esa ciencia única, de esa intuicion de la idea única, infinita; así como en el deseo de felicidad que agita nuestro corazon, en la sed de gozar que nos atormenta, hallamos la prueba de que no acaba todo aquí, de que nuestra alma ha sido criada para la posesion de un bien que no se alcanza en la vida mortal.\"},{\"heading\":false,\"text\":\"[51.] Lo mismo que hemos observado en la escala de los seres, y en el progreso de las ciencias, podemos notarlo comparando hombres con hombres, y atendiendo el carácter que ofrece el punto mas elevado de la humana inteligencia: el genio. Los hombres de verdadero genio se distinguen por la unidad y amplitud de su concepcion. Si tratan una cuestion difícil y complicada, la simplifican y allanan tomando un punto de vista elevado, fijando una idea principal que comunica luz á todas las otras; si se proponen contestar á una dificultad, señalan la raíz del error, y destruyen con una palabra toda la ilusion del sofisma; si emplean la síntesis, aciertan desde luego en el principio que ha de servir de base, y de un rasgo trazan el camino que se ha de seguir para llegar al resultado que se desea; si se valen del análisis atinan en el punto por donde debe empezar la descomposicion, en el resorte oculto, y de un golpe por decirlo asi, nos abren el objeto, nos ponen de manifiesto sus interioridades mas recónditas; si se trata de una invencion, mientras los demás están buscando acá y acullá, ellos hieren el suelo con el pie, y dicen «el tesoro está aquí.» Nada de dilatados raciocinios; nada de rodeos: pocos pensamientos, pero fecundos: pocas palabras, pero en cada una de ellas engastada una perla de inmenso valor.\"},{\"heading\":false,\"text\":\"[52.] No cabe pues duda alguna de que en el órden intelectual hay una verdad de la cual dimanan todas las verdades, hay una idea que encierra todas las ideas; así nos lo enseña la filosofía, así nos los indican los esfuerzos, las tendencias naturales, instintivas, de toda inteligencia, cuando se afana por la simplificacion y la unidad; así lo estima el sentido comun, que considera tanto mas alto y noble el pensamiento, cuanto es mas vasto y mas uno (IV).\"}]},{\"title\":\"CAPÍTULO V\",\"blocks\":[{\"heading\":false,\"text\":\"NO EXISTE LA CIENCIA TRASCENDENTAL EN EL ORDEN INTELECTUAL HUMANO NO PUEDE DIMANAR DE LOS SENTIDOS.\"},{\"heading\":false,\"text\":\"[53.] En el órden intelectual humano, mientras vivimos sobre la tierra, no hay una verdad de la cual dimanen todas: en vano la han buscado los filósofos; no la han encontrado porque no era posible encontrarla. Y en efecto, ¿dónde se hallaria la deseada verdad?\"},{\"heading\":false,\"text\":\"[54.] ¿Dimanará de los sentidos?\"},{\"heading\":false,\"text\":\"Las sensaciones son tan varias como los objetos que las producen. Por ellas adquirimos noticia de cosas individuales y materiales; y en ninguna de estas ni en las sensaciones que de ellas dimanan, puede hallarse la verdad, fuente de todas las demás.\"},{\"heading\":false,\"text\":\"[55.] Observando las impresiones que por los sentidos recibimos, podemos notar que con respecto á producir certeza, todas son iguales entre sí. Tan ciertos estamos de la sensacion que nos causa un ruido cualquiera como de la producida por la presencia de un objeto á nuestros ojos, de un cuerpo oloroso cercano al olfato, de uno sabroso aplicado al paladar, ó de otro que afecte vivamente el tacto. En la certeza producida por aquellas sensaciones no hay gradacion, todas son iguales; porque si hablamos de la sensacion misma, esta la experimentamos de una manera que no nos consiente incertidumbre; y si se trata de la relacion de la sensacion con la existencia del objeto externo que la causa, tan ciertos estamos de que á la sensacion que se llama _vision_, corresponde un objeto externo _visto_, como que á lo que se apellida _tacto_, corresponde un objeto externo _tocado_.\"},{\"heading\":false,\"text\":\"Se infiere de lo dicho, que no hay una sensacion orígen de la certeza de las demás; en este punto todas son iguales; y para el comun de los hombres no hay mas razon que los asegure de la certeza, sino que lo experimentan así. No ignoro que lo sucedido con los individuos á quienes se ha hecho la operacion de las cataratas, indica que para apreciar debidamente el objeto _sentido_ no es suficiente la simple sensacion, y que unos sentidos auxilian á los otros; pero esto no prueba la preferencia de ninguno de ellos; pues así como el ciego á quien se dió repentinamente la vista, no formaba por la simple vision juicio exacto sobre el tamaño y distancia de los objetos vistos, sino que necesitaba el auxilio del tacto; así es muy probable que si suponemos á una persona con vista, privada de tacto desde su nacimiento, y se lo damos despues repentinamente, tampoco formará juicio exacto de los objetos tocados, hasta que con el auxilio de la vista, se haya ido acostumbrando á combinar el nuevo órden de sensaciones con el antiguo, aprendiendo con el ejercicio á fijar las relaciones de la sensacion con el objeto y á conocer por medio de aquella las propiedades de este.\"},{\"heading\":false,\"text\":\"[56.] El mismo hecho del ciego á quien se quitaron las cataratas, está contrariado por otros que conducen á un resultado directamente opuesto. La jóven á quien hizo la misma operacion el oculista Juan Janin, y unos ciegos de nacimiento á quienes el profesor Luis de Gregori restituyó en parte la vista, no creyeron como el ciego de Cheselden, que los objetos estuviesen pegados á sus ojos, sino que luego los vieron como cosas realmente externas y separadas. Así lo refiere Rosmini (Ensayo sobre el orígen de las ideas parte 5. cap. 4. Tomo, 2. p. 286 citando el opúsculo «de las cataratas de los ciegos de nacimiento, observaciones teórico-químicas, del profesor de química y oftalmia Luis de Gregori, Romano.» Roma 1826); bien que dando la preferencia al de Cheselden que dice fué renovado en Italia por el profesor Jacobo de Pavía, con toda diligencia y con el mismo resultado en todas sus partes.\"},{\"heading\":false,\"text\":\"[57.] El modo con que esta combinacion de unas sensaciones con otras nos enseña á juzgar bien de los objetos externos es difícil saberlo: porque cabalmente el desarrollo de nuestras facultades sensitivas é intelectuales se verifica antes que podamos reflexionar sobre él; y así nos encontramos ya ciertos de la existencia y propiedades de las cosas, sin que hayamos pensado en la certeza, ni mucho menos en los medios de adquirirla.\"},{\"heading\":false,\"text\":\"[58.] Pero aun suponiendo que despues nos ocupemos de las sensaciones mismas, y de sus relaciones con los objetos, prescindiendo de la certeza que ya tenemos y haciendo como que la buscamos, es imposible hallar una sensacion que pueda servir de punto de apoyo á la certeza de los demás. Las dificultades que estas nos ofrecieran las encontraríamos en aquella.\"},{\"heading\":false,\"text\":\"[59.] El fijar las relaciones del sentido de la vista con el del tacto, y el determinar hasta qué punto dependen uno de otro, da lugar á cuestiones que pienso examinar mas abajo con alguna extension; y por lo mismo me abstendré de entrar en ellas por ahora, ya porque no son tales que puedan ventilarse por incidencia, ya tambien porque su resolucion sea en el sentido que fuere, en nada se opone á lo que me propongo establecer aquí.\"},{\"heading\":false,\"text\":\"[60.] Nada adelantaríamos con saber que la certeza de todas las sensaciones está, filosóficamente hablando, vinculada en una. Toda sensacion es un hecho individual contingente; ¿cómo podemos sacar de él la luz para guiarnos á las verdades necesarias? Considérese bajo el aspecto que se quiera la sensacion, no es mas que la impresion que recibimos por conducto de los órganos. De la impresion estamos seguros porque está intimamente presente á nuestra alma; de sus relaciones con el objeto que la produce, nos cercioramos por la repeticion de ella, con el auxilio de otras sensaciones, ya del mismo sentido, ya de otros; pero todo instintivamente, con poca ó ninguna reflexion, y siempre condenados, por mas que reflexionemos, á llegar á un punto del cual no podemos pasar porque allí nos detiene la naturaleza.\"},{\"heading\":false,\"text\":\"[61.] Lejos pues de encontrar en ninguna sensacion un hecho fundamental en que podamos apoyarnos para establecer una certeza filosófica, vemos un conjunto de hechos particulares, muy distintos entre sí, pero que se parecen en cuanto á producir en nosotros esa seguridad que se llama certeza. En vano es que se descomponga al hombre, que se le reduzca primero á una máquina inanimada, que luego se le otorgue un sentido haciéndole percibir diferentes sensaciones, que despues se le conceda otro, haciéndole combinar las nuevas con las antiguas, y así se proceda sintéticamente hasta llegar á la posesion y ejercicio de todos; estas cosas son buenas para entretener la curiosidad, alimentar pretensiones filosóficas, y dar un viso de probabilidad á sistemas imaginarios; pero en la realidad se adelanta poco ó nada: las evoluciones que finge el observador, no se parecen á las de la naturaleza; y el verdadero filósofo debe examinar, nó lo que en su concepto pudiera haber, sino lo que hay.\"},{\"heading\":false,\"text\":\"Condillac animando progresivamente su estatua y haciendo dimanar de una sensacion todo el caudal de los conocimientos humanos, se parece á aquellos sacerdotes que se ocultaban dentro de la estatua del ídolo y desde allí emitian sus oráculos. No es la estatua que se va animando lo que piensa y habla, es Condillac que está dentro. Concedámosle al filósofo sensualista todo lo que quiera; dejémosle que arregle á su modo la dependencia respectiva de las sensaciones; todo se le desconcierta desde el momento en que le exigis que no discurra sino con sensaciones puras, por mas que las suponga transformadas. Pero reservemos estas cuestiones para el lugar en que examinaremos la naturaleza y el orígen de las ideas.\"},{\"heading\":false,\"text\":\"[62.] ¿Por qué estoy seguro de que la grata sensacion que experimento en el sentido del olfato procede de un objeto que se llama _rosa_? Porque así me lo atestigua el recuerdo de mil otras ocasiones en que he experimentado la misma impresion, porque con el testimonio del olfato están de acuerdo el tacto y la vista. Pero ¿cómo puedo saber que estas sensaciones son algo mas que impresiones que recibe mi alma? ¿por qué no he de creer que viene de una causa cualquiera sin relacion á objetos externos? ¿Será porque dicen lo contrario los demás hombres? ¿Me consta que existan? ¿Y cómo saben ellos lo que me dicen? ¿cómo sé que los oigo bien? La misma dificultad que se ofrece con respeto á los otros sentidos existe en cuanto al oido; si dudo del testimonio de tres, ¿por qué no dudo del de cuatro? No adelanto pues nada con el raciocinio; este me conduciria á cavilaciones tales, que me exigirian una duda imposible, que me arrancarian una seguridad de que no puedo desprenderme por mas esfuerzos que haga.\"},{\"heading\":false,\"text\":\"Además, si para apoyar la verdad de la sensacion apelo á los principios del raciocinio, ya salgo del terreno de las sensaciones, ya no pongo en estas la verdad primitiva orígen de las otras, no cumplo lo que habia ofrecido.\"},{\"heading\":false,\"text\":\"[63.] De lo dicho resulta: 1.º que no se encuentra una sensacion orígen de la certeza de las otras, lo que me he contentado con indicarlo aquí, reservándome demostrarlo al tratar de las sensaciones; 2.° que aun cuando existiese esta sensacion, no bastaria á fundar nada en el órden intelectual, pues con las solas sensaciones no es posible ni aun pensar; 3.º que las sensaciones lejos de poder ser la basa de la ciencia trascendental, no sirven por sí solas para establecer ninguna ciencia; pues de ellas, por ser hechos contingentes, no pueden dimanar las verdades necesarias (V).\"}]},{\"title\":\"CAPÍTULO VI\",\"blocks\":[{\"heading\":false,\"text\":\"CONTINÚA LA DISCUSION SOBRE LA CIENCIA TRASCENDENTAL. INSUFICIENCIA DE LAS VERDADES REALES.\"},{\"heading\":false,\"text\":\"[64.] Ha sido conveniente rebatir de paso el sistema de Condillac, no por su importancia intrínseca, ni porque no esté ya bastante desacreditado, sino para dejar el campo libre á investigaciones mas elevadas, mas propiamente filosóficas. Es preciso no perder ocasion de indemnizar á la filosofía de los perjuicios que le irrogara un sistema tan vanidoso como estéril. Todo lo mas sublime de la ciencia del espíritu, desaparecia con el _hombre-estatua_, y las sensaciones transformadas; venguemos pues los derechos de la razon humana, manifestando que antes de entrar en las cuestiones mas trascendentales, le es indispensable descartar el sistema de Condillac; como para construir un buen camino se quita ante todo la broza que obstruye el paso.\"},{\"heading\":false,\"text\":\"[65.] Vamos ahora á probar que en el órden intelectual humano, tal como es en esta vida, no existe ningun principio que sea fuente de todas las verdades; porque no hay ninguna verdad que las encierre todas.\"},{\"heading\":false,\"text\":\"Las verdades son de dos clases: reales ó ideales. Llamo verdades reales á los hechos, ó lo que existe; llamo ideales el enlace necesario de las ideas. Una verdad real puede expresarse por el verbo _ser_ tomado sustantivamente, ó al menos supone una proposicion en que el verbo se haya tomado en este sentido; una verdad ideal se expresa por el mismo verbo tomado copulativamente, en cuanto significa la relacion necesaria de un predicado con un sujeto, prescindiendo de la existencia de uno y de otro. _Yo soy_, esto es, _yo existo_, expresa una verdad real, un hecho. _Lo que piensa existe_; expresa una verdad ideal, pues no se afirma que haya quien piense ni quien exista, sino que si hay quien piensa, existe; ó en otros términos, se afirma una relacion necesaria entre el pensamiento y el ser. A las verdades reales corresponde el mundo real, el mundo de las existencias; á las ideales el mundo lógico, el de la posibilidad.\"},{\"heading\":false,\"text\":\"El verbo _ser_ se toma á veces copulativamente sin que la relacion que por él se expresa sea necesaria; así sucede en todas las proposiciones contingentes, ó cuando el predicado no pertenece á la esencia del sujeto. A veces la necesidad es condicional, es decir que supone un hecho; y en tal caso tampoco hay necesidad absoluta, pues el hecho supuesto es siempre contingente. Cuando hablo de las verdades ideales, me refiero á las que expresan una relacion absolutamente necesaria, prescindiendo de todo órden á la existencia; y por el contrario, comprendo entre las reales á todas las que suponen una proposicion en que se haya establecido un hecho. A esta clase pertenecen las de las ciencias naturales, por suponer todas algun hecho objeto de observacion.\"},{\"heading\":false,\"text\":\"[66.] Ninguna verdad real finita puede ser orígen de todas las demás. La verdad de esta clase es la expresion de un hecho particular, contingente; y que por lo mismo no puede encerrar en sí ni las demás verdades reales, ó sea el mundo de las existencias, ni tampoco las verdades ideales, que solo se refieren á las relaciones necesarias en el mundo de la posibilidad.\"},{\"heading\":false,\"text\":\"[67.] Si nosotros viésemos intuitivamente la existencia infinita, causa de todas las demás, conoceríamos una verdad real, orígen de las otras; pero como esta existencia infinita no la conocemos por intuicion, sino por discurso, resulta que no conocemos el hecho de la existencia en que se contiene la razon de todas las demás existencias. Despues que por el discurso nos hemos elevado á dicho conocimiento, tampoco nos es posible explicar desde aquel punto de vista la existencia de lo finito por sola la existencia de lo infinito; porque si prescindimos de la existencia de lo finito, desaparece el discurso por el cual nos habiamos elevado hasta el conocimiento de lo infinito, y por consiguiente se hunde todo el edificio de nuestra ciencia. Dad á un hombre por medio del discurso la demostracion de la existencia de Dios, y pedidle que prescindiendo del punto de partida, y fijándose solo en la idea de lo infinito explique la creacion, no solo en su posibilidad sino en su realidad, no lo podrá verificar. Con solo prescindir de lo finito se hunde todo su discurso, sin que ningun esfuerzo sea bastante á evitarlo; se halla en el caso de un arquitecto á quien, habiendo construido una soberbia cúpula, se le exigiese que la sostuviera, quitando el cimiento al edificio.\"},{\"heading\":false,\"text\":\"[68.] Tómese una verdad real cualquiera, el hecho mas seguro, mas cierto para nosotros; nada se puede sacar de él si no se le fecunda con verdades ideales. Yo existo, yo pienso, yo siento. Hé aqui hechos indudables; pero ¿qué puede deducir de ellos la ciencia? nada: son hechos particulares, contingentes, cuya existencia ó no existencia, no afecta á los demás hechos ni alcanza al mundo de las ideas.\"},{\"heading\":false,\"text\":\"Estas verdades son de puro sentimiento; en sí solas nada tienen que ver con el órden científico, y solo se elevan hasta él, cuando se las combina con verdades ideales. Descartes, al consignar el hecho del pensamiento y de la existencia, pasaba sin advertirlo, del órden real al órden ideal, forzado por su propósito de levantar el edificio científico. _Yo pienso_, decia; si se hubiese limitado á esto, se habria reducido su filosofía á una simple intuicion de su conciencia; pero queria hacer algo mas, queria discurrir, y por necesidad echaba mano de una verdad ideal: _Lo que piensa existe_. Así fecundaba el hecho individual, contingente, con la verdad universal y necesaria; y como habia menester una regla para conducirse en adelante, la buscaba en la legitimidad de la evidencia de las ideas. Por donde se echa de ver como este filósofo, que con tanto afan buscaba la unidad, se encontraba desde luego con la triplicidad: _un hecho, una verdad objetiva, un criterio_. Un hecho en la conciencia del _yo_; una verdad objetiva en la relacion necesaria del pensamiento con la existencia; un criterio, en la legitimidad de la evidencia de las ideas.\"},{\"heading\":false,\"text\":\"Se puede desafiar á todos los filósofos del mundo á que discurran sobre un hecho cualquiera sin el auxilio de las verdades ideales. La esterilidad que hemos encontrado en el hecho de la _conciencia_, se hallará en todos los demás. Esto no es una conjetura, es una demostracion rigurosa. Solo una existencia contiene la razon de todas las demás; en no conociéndola pues de una manera inmediata, intuitiva, nos es imposible encontrar una verdad real orígen de todas las otras.\"},{\"heading\":false,\"text\":\"[69.] Aun suponiendo que en el órden de la creacion hubiese un hecho primitivo de tal naturaleza que todo el universo no fuera mas que un simple desarrollo suyo, tampoco habriamos encontrado la verdad real, fuente de toda ciencia; pues con esto nada adelantaríamos con respecto al mundo de la posibilidad, es decir, al órden ideal, infinitamente mayor que el de las existencias infinitas.\"},{\"heading\":false,\"text\":\"Supongamos que el progreso de las ciencias naturales conduzca al descubrimiento de una ley simple, única, que presida al desarrollo de todas las demás, y cuya aplicacion, variada segun las circunstancias, sea suficiente para dar razon de todos los fenómenos que ahora se reducen á muchas y muy complicadas. Este seria sin duda un adelanto inmenso en las ciencias que tienen por objeto el mundo visible; ¿pero qué sabríamos por esto del mundo de las inteligencias? ¿qué del mundo de la posibilidad? (VI).\"}]},{\"title\":\"CAPÍTULO VII\",\"blocks\":[{\"heading\":false,\"text\":\"ESTERILIDAD DE LA FILOSOFÍA DEL _yo_ PARA PRODUCIR LA CIENCIA TRASCENDENTAL.\"},{\"heading\":false,\"text\":\"[70.] El testimonio de la conciencia es seguro, irresistible, pero nada tiene que ver con el de la evidencia. Aquel tiene por objeto un hecho particular y contingente, este una verdad necesaria. Que yo pienso ahora, es absolutamente cierto para mí; pero este pensar mio no es una verdad necesaria sino muy contingente, ya que podia muy bien suceder que jamás hubiese pensado ni existido; es un hecho puramente individual, pues no sale de mí, y su existencia y no existencia en nada afecta las verdades universales.\"},{\"heading\":false,\"text\":\"La conciencia es un áncora nó un faro; basta para evitar el naufragio de la inteligencia, nó para indicarle el derrotero. En los asaltos de la duda universal, ahí está la conciencia que no deja perecer; pero si le pedís que os dirija, os presenta hechos particulares, nada mas.\"},{\"heading\":false,\"text\":\"Estos hechos no tienen un valor científico sino cuando se objetivan, permítaseme la expresion; ó bien cuando reflexionando sobre ellos el espíritu, los baña con la luz de las verdades necesarias.\"},{\"heading\":false,\"text\":\"Yo pienso; yo siento; yo soy libre; hé aquí hechos; pero ¿qué sacais de ellos por sí solos? nada. Para fecundarlos es necesario que los tomeis como una especie de materia de las ideas universales. El pensamiento se inmoviliza, se hiela, si no le haceis andar con el impulso de estas ideas; la sensacion os es comun con los brutos; y la libertad carece de objeto, de vida, si no hay combinacion de motivos presentados por la razon.\"},{\"heading\":false,\"text\":\"[71.] Aquí se encuentra la causa de la oscuridad y esterilidad de la filosofía alemana, desde Fichte. Kant, se fijaba en el sujeto, pero sin destruir la objetividad en el mundo interior; y por esto su filosofía, si bien contiene muchos errores, ofrece al entendimiento algunos puntos luminosos; pero fué mas allá, se colocó en el _yo_, no sirviéndose de la objetividad sino en cuanto le era necesaria para establecerse mas hondamente en un simple hecho de conciencia; así no encontró mas que regiones tenebrosas ó contradicciones.\"},{\"heading\":false,\"text\":\"La inteligencia de hombres de talento se ha fatigado en vano para hacer brotar un rayo de luz de un punto condenado á la oscuridad. El _yo_ se manifiesta á sí mismo por sus actos; y para ser concebido de sí propio no disfruta de ningun privilegio sobre los seres distintos de él, sino el de presentar inmediatamente los hechos que pueden conducir á su conocimiento. ¿Qué sabria el alma de sí misma, si no sintiera su pensamiento, su voluntad, y el ejercicio de todas sus facultades? ¿Cómo discurre sobre su propia naturaleza sino fundándose en lo que le suministra el testimonio de sus actos? El _yo_ pues no es visto por sí propio intuitivamente; no se ofrece á sus mismos ojos, sino mediantamente, esto es por sus propios actos; es decir que en cuanto á ser conocido, se halla en un caso semejante al de los seres externos, que lo son por los efectos que nos causan.\"},{\"heading\":false,\"text\":\"El _yo_ considerando en sí, no es un punto luminoso; es un sustentáculo para el edificio de la razon; mas nó la regla para construirle. La verdadera luz se halla en la objetividad; pues en ella está propiamente el blanco del conocimiento. El _yo_ no puede ni ser conocido, ni pensado de ninguna manera, sino en cuanto se toma á sí mismo por objeto, y por consiguiente en cuanto se coloca en la línea de los demás seres, para sujetarse á la actividad intelectual que solo obra en fuerza de las verdades objetivas.\"},{\"heading\":false,\"text\":\"[72.] La inteligencia no se concibe sin objetos al menos internos; y estos objetos serán estériles, si el entendimiento no concibe en ellos relaciones y por consiguiente verdades. Estas verdades, no tendrán ningun enlace, serán hechos sueltos, si no entrañan alguna necesidad; y aun las relaciones que se refieran á hechos particulares suministrados por la experiencia, no serán susceptibles de ninguna combinacion, si al menos condicionalmente, no incluyen algo de necesario. El brillo de la luz en el aposento en que escribo es en sí un hecho particular y contingente; y la ciencia como tal, no puede ocuparse de él, sino sujetando el movimiento de la luz á leyes geométricas, es decir á verdades necesarias.\"},{\"heading\":false,\"text\":\"Luego el _yo_ en sí mismo, como sujeto, no es punto de partida para la ciencia, aunque sea un punto de apoyo. Lo individual no sirve para lo universal, ni lo contingente para lo necesario. La ciencia del individuo A, es cierto que no existiria si el individuo A no existiese; pero esta ciencia que necesita del _yo_ individual, no es la ciencia propiamente dicha, sino el conjunto de actos individuales con que el individuo percibe la ciencia. Mas lo percibido no es esto; lo percibido es comun á todas las inteligencias; no necesita de este ó aquel individuo; el fondo de verdades que constituyen la ciencia no ha nacido de aquel conjunto de actos individuales, hechos contingentes que se pierden cual gotas imperceptibles en el océano de la inteligencias.\"},{\"heading\":false,\"text\":\"¿Cómo se quiere pues fundar la ciencia sobre el simple _yo_ subjetivo? ¿Cómo de este _yo_ se quiere hacer brotar el objeto? El hecho de la conciencia nada tiene que ver con la ciencia, sino en cuanto ofrece hechos á los cuales se pueden aplicar los principios objetivos, universales, necesarios, independientes de toda individualidad finita, que constituyen el patrimonio de la razon humana, pero que no han menester la existencia de ningun hombre.\"},{\"heading\":false,\"text\":\"[73.] Analícense cuanto se quiera los hechos de la conciencia, jamás se encontrará en ellos uno que pueda engendrar la luz científica. Aquel acto será ó una percepcion directa ó refleja. Si es directa, su valor no es subjetivo sino objetivo; no es el acto lo que funda la ciencia, sino la verdad percibida, no el sujeto sino el objeto, no el _yo_ sino lo visto por el _yo_. Si el acto es reflejo, supone otro acto anterior, á saber, el objeto de la reflexion; no es pues aquel el primitivo sino este.\"},{\"heading\":false,\"text\":\"La combinacion del acto directo con el reflejo, tampoco sirve para nada científico, sino en cuanto se somete á las verdades necesarias, objetivas, independientes del _yo_. ¿Qué es un acto individualmente considerado? un fenómeno interior. Y ¿qué nos enseña este fenómeno separado de las verdades objetivas? nada. El fenómeno representa algo en la ciencia, en cuanto es considerado bajo las ideas generales, de ser, de causa, de efecto, de principio ó de producto de actividad, de modificacion, de sus relaciones con su sujeto que es el _substratum_ de otros actos semejantes; es decir cuando es considerado como un caso particular, comprendido en las ideas generales, como un fenómeno contingente, apreciable con el auxilio de las verdades necesarias, como un hecho esperimental, al cual se aplica una teoría.\"},{\"heading\":false,\"text\":\"El acto reflejo no es mas que el conocimiento de un conocimiento, ó sentimiento, ó de algun fenómeno interior sea cual fuere; y así toda reflexion sobre la conciencia presupone acto anterior directo. Este acto directo no tiene por objeto el _yo_; luego el conocimiento no tiene por principio fundamental el _yo_, sino como una condicion necesaria (pues no puede haber pensamiento sin sujeto pensante), mas nó como objeto conocido.\"},{\"heading\":false,\"text\":\"[74.] Estas consideraciones derriban por su cimiento el sistema de Fichte y de cuantos toman el _yo_ humano por punto de partida en la carrera de las ciencias. El _yo_ en sí mismo, no se nos presenta; lo que conocemos de él lo sabemos por sus actos, y en esto participa de una calidad de los demás objetos, que no nos ofrecen inmediatamente su esencia sino lo que de ella emana, por la actividad con que obran sobre nosotros.\"},{\"heading\":false,\"text\":\"De esta manera nos elevamos por raciocinio al conocimiento de las cosas mismas, guiados por las verdades objetivas y necesarias, que son la ley de nuestro entendimiento, el tipo de las relaciones de los seres, y por tanto una regla segura para juzgar de ellos. ¿Qué sabemos de nuestro espíritu? que es simple: ¿y esto, cómo lo sabemos? porque piensa, y lo compuesto, lo múltiplo, no puede pensar. Hé aquí como conocemos el _yo_. La conciencia nos manifiesta su actividad pensadora; esta es la materia suministrada por el hecho; pero luego viene el principio, la verdad objetiva, iluminando el hecho, mostrando la repugnancia entre el pensamiento y la composicion, el enlace necesario entre la simplicidad y la conciencia.\"},{\"heading\":false,\"text\":\"Si bien se observa, este raciocinio se aplica no solo al _yo_, sino á todo ser que piense; y así es que la misma demostracion la extendemos á todos; el _yo_ pues que la aplica no crea esta verdad, solo la conoce, y se conoce á sí propio como un caso particular comprendido en la regla general.\"},{\"heading\":false,\"text\":\"[75.] El pretender que del _yo_ subjetivo surja la verdad, es comenzar por suponer al _yo_ un ser absoluto, infinito, orígen de todas las verdades, y razon de todos los seres: lo que equivale á comenzar la filosofía divinizando el entendimiento del hombre. Y como á esta divinizacion no tiene mas derecho un individuo que otro, el admitirla equivale á establecer el panteismo racional, que como veremos en su lugar, dista poco ó nada del panteismo absoluto.\"},{\"heading\":false,\"text\":\"Suponiendo que las razones individuales no son mas que fenómenos de la razon única y absoluta; y que por tanto lo que llamamos espíritus, no son verdaderas substancias, sino simples modificaciones de un espíritu único, y las conciencias particulares meras apariciones de la conciencia universal, se concibe por qué se busca en el _yo_ la fuente de toda verdad, y se interroga á la conciencia propia como una especie de oráculo por el cual habla la conciencia universal. Pero la dificultad está en que la suposicion es gratuita: y que tratándose de buscar la razon de todas las verdades, se principia por establecer la mas incomprensible y repugnante de las proposiciones. ¿Quién es capaz de persuadirnos que nuestras conciencias no son mas que una modificacion de una tercera? ¿Quién nos hará creer que eso que llamamos el _yo_, es comun á todos los hombres, á todos los seres inteligentes, y que no hay mas diferencia que la de modificaciones de un ser absoluto? Este ser absoluto, ¿por qué no tiene conciencia de todas las conciencias que comprende? ¿Por qué ignora lo que encierra en sí, lo que le modifica? ¿Por qué se cree múltiplo si es uno? ¿Dónde está el lazo de tanta multiplicidad? ¿Las conciencias particulares, tendrán su unidad, su vínculo de todo lo que les acontece, á pesar de no ser mas que modificaciones; y este vínculo, esta unidad, faltarán á la substancia que ellas modifican?\"},{\"heading\":false,\"text\":\"[76.] Como quiera, aun con la suposicion del panteismo, nada adelantan en sus pretensiones los amigos de la filosofía del _yo_. Con su panteismo, legitiman por decirlo así su pretension, mas no logran lo que pretenden. Se llaman á sí mismos dioses; y así tienen razon en que en ellos está la fuente de verdad; pero como en su conciencia no hay mas que una aparicion de su divinidad, una sola fase del astro luminoso, no pueden ver en ella otra cosa que lo que se les presenta; y su divinidad se encuentra sujeta á ciertas leyes que la imposibilitan para dar la luz que la filosofía le pide.\"},{\"heading\":false,\"text\":\"[77.] Si interrogamos nuestra conciencia sobre las verdades necesarias, notaremos que lejos de pretender ó fundarlas ó crearlas, las conoce, las confiesa independientes de sí misma. Pensemos en esta proposicion: «es imposible que á un mismo tiempo, una cosa sea y no sea» y preguntémonos si la verdad de ella nace de nuestro pensamiento; desde luego la conciencia misma responde que no. Antes de que mi conciencia existiera, la proposicion era verdad; si yo no existiese ahora, seria tambien verdad; cuando no pienso en ella, es tambien verdad; el _yo_ no es mas que un ojo que contempla el sol, pero que no es necesario para la existencia del sol.\"},{\"heading\":false,\"text\":\"[78.] Otra consideracion hay que demuestra la esterilidad de toda filosofía que busque en el solo _yo_ el orígen único y universal de los conocimientos humanos. Todo conocimiento exige un objeto; el conocimiento puramente subjetivo es inconcebible; aun suponiendo identidad entre el sujeto y el objeto, se necesita la dualidad de relacion, real ó concebida; es decir que el sujeto en cuanto conocido, esté en cierta oposicion al menos concebida, con el mismo sujeto en cuanto conoce. Ahora bien; ¿cuál es el objeto en el acto primitivo que se busca? Es el _no yo_? Entonces la filosofía del _yo_ entra en el cauce de las demás filosofías: pues en este _no yo_ están las verdades objetivas, ¿Es el _yo_? Entonces preguntaremos, si es el _yo_ en sí, ó en sus actos; si es el _yo_ en sus actos, entonces la filosofía del _yo_ se reduce á un análisis ideológico, nada tiene de característico; si es el _yo_ en sí, diremos que este no es conocido intuitivamente; y que menos que nadie pueden pretender á esta intuicion, los que le llaman el _absoluto_. Para ellos mas que para los otros, es el _yo_ un abismo tenebroso. En vano os inclinais sobre este abismo y gritais para evocar la verdad; el sordo ruido que os llega á los oidos es el eco de vuestra voz misma, son vuestras palabras que la honda cavidad os devuelve mas ahuecadas y misteriosas.\"},{\"heading\":false,\"text\":\"[79.] Entre estos filósofos que se pierden en vanas cavilaciones, descuella el autor de la _Doctrina de la ciencia_, Fichte, de cuyo sistema ha dicho con mucha gracia Madama de Stael, que se parece algun tanto al dispertar de la estatua de Pigmalion, que tocándose alternativamente á sí misma y á la piedra sobre que está sentada, dice: soy yo, no soy yo.\"},{\"heading\":false,\"text\":\"Fichte comienza su obra titulada _Doctrina de la ciencia_, diciendo que se propone buscar el principio mas absoluto, el principio absolutamente incondicional de todo conocimiento humano. Hé aquí un método erróneo; se comienza por suponer lo que se ignora, la unidad del principio, y ni aun se sospecha que en la basa del conocimiento humano puede haber una verdadera multiplicidad. Yo creo que la puede haber y la hay en efecto, que las fuentes de nuestro conocimiento son varias, de órdenes diversos, y que no es posible llegar á la unidad, sino saliéndose del hombre y remontándose á Dios. Lo repito, hay aqui una equivocacion en que se ha incurrido con demasiada generalidad, resultando de ella el fatigar inútilmente los espíritus investigadores, y arrojarlos á sistemas extravagantes.\"},{\"heading\":false,\"text\":\"Pocos filósofos habrán hecho un esfuerzo mayor que Fichte para llegar á este principio absoluto. ¿Y qué consiguió? Lo diré francamente; nada: ó repite el principio de Descartes, ó se entretiene en un juego de palabras. Lástima da el verle forcejar con tal ahinco y con tan poco resultado. Ruego al lector que tenga paciencia para seguirme en el exámen de la doctrina del filósofo aleman, no con la esperanza de adquirir una luz que le guie en los senderos de la filosofía, sino para poder juzgar con conocimiento de causa, doctrinas que tanto ruido meten en el mundo.\"},{\"heading\":false,\"text\":\"«Si este principio, dice Fichte, es verdaderamente el mas absoluto, no podrá ser ni definido ni demostrado. Deberá expresar el acto que no se presenta ni puede presentarse entre las determinaciones empíricas de nuestra conciencia; por el contrario, sobre él descansa toda conciencia, y solo él la hace posible (1.° parte § 1.).«\"},{\"heading\":false,\"text\":\"Sin ningun antecedente, sin ninguna razon, sin tomarse siquiera la pena de indicar en qué se funda, asegura Fichte que el primer principio deberá expresar un acto. ¿Por qué no podria ser una verdad objetiva? esto merecia cuando menos algun exámen, ya que todas las escuelas anteriores, incluso la de Descartes, no habian colocado el primer principio entre los actos, sino entre las verdades objetivas. El mismo Descartes al consignar el hecho del pensamiento y de la existencia, echa mano de una verdad objetiva. «Lo que piensa existe» ó en otros términos: «Lo que no existe, no puede pensar.»\"},{\"heading\":false,\"text\":\"[80.] La observacion que precede, señala uno de los vicios radicales de la doctrina de Fichte y otros filósofos alemanes, que dan á la filosofía subjetiva, ó del sujeto, una importancia que no merece. Ellos acusan á los demás de hacer con demasiada facilidad la transicion del sujeto al objeto, y olvidan que al propio tiempo ellos pasan del pensamiento objetivo al sujeto puro, sin ninguna razon ni título que los autorice. Ateniéndonos al citado pasaje de Fichte, ¿qué será un acto que no se presenta, ni se puede presentar entre las determinaciones empíricas de nuestra conciencia? El principio buscado, por ser absoluto, no se exime de ser conocido, pues si no lo conocemos, mal podremos afirmar que es absoluto; y si no se presenta ni se puede presentar entre las determinaciones empíricas de nuestra conciencia, ni es, ni puede ser conocido. El hombre no conoce lo que no se presenta en su conciencia.\"},{\"heading\":false,\"text\":\"El principio absoluto en que toda conciencia descansa y que la hace posible, pertenece ó nó á la conciencia. Si lo primero, sufre todas las dificultades que afectan á los demás actos de la conciencia; si lo segundo, no puede ser objeto de observacion, y por consiguiente nada sabemos de él.\"},{\"heading\":false,\"text\":\"Para llegar al acto primitivo, separando del mismo todo lo que no le pertenece realmente, confiesa Fichte que es necesario suponer valederas las reglas de toda reflexion, y partir de una proposicion cualquiera de las muchas que se podrian escoger entre aquellas que todo el mundo concede sin ningun reparo. «Concediéndosenos esta proposicion, dice, se nos debe conceder al mismo tiempo como acto, lo que queremos poner como principio de la ciencia del conocimiento; y el resultado de la reflexion debe ser que este acto nos sea concedido como principio, junto con la proposicion. Ponemos un hecho cualquiera de la conciencia empírica, y quitamos de él una tras otra todas las determinaciones empíricas, hasta que se reduzca á toda su pureza, sin contener mas que lo que el pensamiento no puede absolutamente excluir y de lo que nada puede quitar; (ibid.).»\"},{\"heading\":false,\"text\":\"Se ve por estas palabras que el filósofo aleman se proponia elevarse á un acto de conciencia enteramente puro, sin ninguna determinacion. Esto es imposible: ó Fichte toma el acto en un sentido muy lato, entendiendo por él el _substratum_ de toda conciencia, en cuyo caso no hace mas que expresar en otros términos la idea de substancia; ó habla de un acto propiamente dicho, esto es, de un ejercicio cualquiera de esa actividad, de esa espontaneidad que sentimos dentro de nosotros; y en este concepto el acto de conciencia no puede estar libre de toda determinacion so pena de destruir su individualidad y su existencia. No se piensa sin pensar algo; no se quiere sin querer algo; no se siente sin sentir algo; no se reflexiona sobre los actos internos, sin que la reflexion se fije en algo. En todo acto de conciencia hay determinacion: un acto del todo puro, abstraido de todo, enteramente indeterminado, es imposible, absolutamente imposible; ya subjetivamente, porque el acto de conciencia aun considerado en el sujeto, exige una determinacion; ya objetivamente, porque un acto semejante es inconcebible como individual, y por tanto como existente, pues que nada determinado ofrece al espíritu.\"},{\"heading\":false,\"text\":\"[81.] El acto indeterminado de Fichte no es mas que la idea de acto en general; el filósofo aleman creyó haber hecho un gran descubrimiento cuando en el fondo no concebia otra cosa que el principio de los actos, es decir la idea de la substancia aplicada á ese ser activo cuya existencia nos atestigua la conciencia misma.\"},{\"heading\":false,\"text\":\"Si he de decir ingenuamente lo que pienso, séame permitido manifestar que en mi concepto Fichte con todo el alambicar de su análisis, no ha hecho adelantar un solo paso á la filosofía en la investigacion del primer principio. Por lo dicho hasta aquí se echa de ver que es muy fácil detenerle con solo pedirle cuenta de las suposiciones que hace desde la primera página de su libro. Sin embargo, para proceder en la impugnacion con cumplida lealtad, no quiero extractar sus ideas, sino dejarle que las explique él mismo.\"},{\"heading\":false,\"text\":\"«Todo el mundo concede la proposicion: A es A, así como que A = A, porque esto es lo que significa la cópula lógica, y esto es admitido sin reflexion alguna como completamente cierto. Si alguno pidiese la demostracion, nadie pensaria en dársela sino que se sostendria que esta proposicion es cierta absolutamente, es decir, sin razon alguna mas desarrollada. Procediendo así incontestablemente con el asentimiento general, nos atribuimos el derecho de poner alguna cosa absolutamente.»\"},{\"heading\":false,\"text\":\"«Al afirmar que la proposicion precedente es cierta en sí, no se pone la existencia de A. La proposicion A es A, no equivale á esta A es, ó hay un A. (_Ser,_ puesto sin predicado, tiene un significado muy distinto de _ser_ con predicado, segun veremos despues). Si se admite que A designa un espacio comprendido entre dos rectas, la proposicion permanece exacta, aun cuando en este caso la proposicion A es, sea de una falsedad evidente. Lo que se pone es, que si A es, A es así. La cuestion no está en si A es ó nó; se trata aquí nó del contenido de la proposicion, sino únicamente de su forma; nó de un objeto del cual se sepa algo, sino de lo que se sabe de todo objeto sea el que fuere.»\"},{\"heading\":false,\"text\":\"«De la certeza absoluta de la proposicion precedente resulta que entre el _si_ y el _así_ hay una relacion necesaria: ella es la que está puesta absolutamente y sin otro fundamento; á esta relacion necesaria la llamo previsoriamente X.»\"},{\"heading\":false,\"text\":\"Todo este aparato de análisis no significa mas de lo que sabe un estudiante de lógica; esto es, que en toda proposicion la cópula, ó el verbo _ser_, no significa la existencia del sujeto, sino su relacion con el predicado; para decirnos una cosa tan sencilla no eran necesarias tantas palabras, ni tan afectados esfuerzos de entendimiento, mucho menos tratándose de una proposicion idéntica. Pero tengamos paciencia para continuar oyendo al filósofo aleman.\"},{\"heading\":false,\"text\":\"«¿Este A es ó no es? nada hay decidido todavía sobre el particular; se presenta pues la siguiente cuestion, bajo qué condicion A es?\"},{\"heading\":false,\"text\":\"«En cuanto á X ella está en el _yo_ y es puesta por el _yo_; porque el _yo_ es quien juzga en la proposicion expresada y hasta juzga con verdad, con arreglo á X como una ley; por consiguiente X es dada al _yo_; y siendo puesta absolutamente y sin otro fundamento, debe ser dada al _yo_ por el _yo_ mismo.»\"},{\"heading\":false,\"text\":\"[82.] A qué se reduce toda esa algarabia? hélo aquí traducido al lenguaje comun; en las proposiciones de identidad ó igualdad, hay una relacion, el espíritu la conoce, la juzga y falla sobre lo demás con arreglo á ella. Esta relacion es dada á nuestro espíritu, en las proposiciones idénticas no necesitamos de ninguna prueba para el asenso. Todo esto es muy verdadero, muy claro, muy sencillo; pero cuando Fichte añade que esta relacion debe ser dada al _yo_ por el mismo _yo_, afirma lo que no sabe ni puede saber. ¿Quién le ha dicho que las verdades objetivas nos vienen de nosotros mismos? ¿tan ligeramente, de una sola plumada, se resuelve una de las principales cuestiones de la filosofía, cual es la del orígen de la verdad? nos ha definido por ventura el _yo_? nos ha dado de él alguna idea? Sus palabras ó no significan nada ó expresan lo siguiente. Juzgo de una relacion; este juicio está en mí; esta relacion como conocida, y prescindiendo de su existencia real, está en mí; todo lo cual se reduce á lo mismo que con mas sencillez y naturalidad dijo Descartes: «Yo pienso, luego existo.»\"},{\"heading\":false,\"text\":\"[83.] Examinando detenidamente las palabras de Fichte se ve con toda claridad que nada mas adelantaba sobre lo dicho por el filósofo francés. «No sabemos, continúa, si A está puesto, ni cómo lo es; pero debiendo X expresar una relacion entre un poner desconocido de A y un poner absoluto del mismo A, en tanto por lo menos que la relacion es puesta, A existe en el _yo_, y está puesto por el _yo_, lo mismo que X. X no es posible sino relativamente á un A; es así que X es realmente puesta en el _yo_; luego A debe estar puesto en el _yo_, si en él se encuentra la X.» ¡Qué lenguaje mas embrollado y misterioso para decir cosas muy comunes! ¡cuán grande parece Descartes al lado de Fichte! Ambos comienzan su filosofía por el hecho de conciencia que revela la existencia. El uno expresa lo que piensa con claridad, con sencillez, en un lenguaje que todo el mundo entiende y no puede menos de entender; y el otro para hacer como que inventa, para no manifestarse discípulo de nadie, se envuelve en una nube misteriosa, rodeada de tinieblas, y desde allí con voz ahuecada pronuncia sus oráculos. Descartes dice: «yo pienso, de esto no puedo dudar, es un hecho que me atestigua mi sentido íntimo; nada puede pensar sin existir; luego yo existo.» Esto es claro, es sencillo, ingenuo, esto manifiesta un verdadero filósofo, un hombre sin afectacion ni pretensiones. El otro dice: «déseme una proposicion cualquiera, por ejemplo A es A» explica en seguida que en las proposiciones el verbo ser no expresa la existencia absoluta del sujeto, sino su relacion con el predicado; todo con un aparato de doctrina, que cansa por su forma y hace reir por su esterilidad; ¿y para qué? para decirnos que A está en el _yo_ porque la relacion del predicado con el sujeto ó sea la X, no es posible sino en un ser, pues que A significa un ser cualquiera. Pongamos en parangon los dos silogismos. Descartes dice: «nada puede pensar sin existir, es así que yo pienso, luego existo.» Fichte dice literalmente lo que sigue: «X no es posible sino relativamente á un A; es así que X es realmente puesto en el _yo_; luego A debe estar puesto en el _yo_.» ¿Cuál es en el fondo la diferencia? ninguna, ¿Cuál es en la forma? la que va del lenguaje de un hombre sencillo á un hombre vano.\"},{\"heading\":false,\"text\":\"Repito que en el fondo los silogismos no son diferentes. La mayor de Descartes es: «nada puede pensar sin existir.» No la prueba, y confiesa que no se puede probar. La mayor de Fichte es: «X no es posible sino relativamente á un A» ó en otros términos: una relacion de un predicado con un sujeto, en cuanto conocida, no es posible sin un ser que conozca. «Debiendo X expresar una relacion entre un _poner_ desconocido de A, y un _poner_ absoluto del mismo A, en tanto por lo menos que _esta relacion es puesta_» es decir en tanto que es conocida. ¿Y cómo prueba Fichte que un _poner_ relativo, supone un _poner_ absoluto, esto es, un sujeto en que se _ponga_? Lo mismo que Descartes: de ninguna manera. No hay A relativo, si no le hay absoluto; nada puede pensar sin existir; esto es claro, es evidente, y ni Descartes ni Fichte van mas allá.\"},{\"heading\":false,\"text\":\"La menor de Descartes es esta: yo pienso; la prueba de esta menor no la da el filósofo, se refiere al sentido íntimo y de allí confiesa que no puede pasar. La menor de Fichte, es la siguiente: X es realmente puesta en el _yo_, lo que equivale á decir, la relacion del predicado con el sujeto es realmente conocida por el _yo_; y como la proposicion podia ser escogida á arbitrio segun el mismo Fichte, siendo indiferente la una ó la otra, decir la relacion del predicado con el sujeto es conocida por el _yo_, es lo mismo que decir una relacion cualquiera es conocida por el _yo_, lo que podia expresarse en términos mas claros: _yo_ pienso.\"},{\"heading\":false,\"text\":\"[84.] Y nótese bien; si hay aquí alguna diferencia, toda la ventaja está de parte del filósofo francés. Descartes entiende por pensamiento todo fenómeno interno de que tenemos conciencia. Para consignar este hecho, no necesita analizar proposiciones, ni confundir el entendimiento, cuando cabalmente es menester mas claridad y precision. Para llegar al mismo hecho Fichte da largos rodeos, Descartes lo señala con el dedo, y dice: aquí está. Lo primero es propio del sofista, lo segundo del genio.\"},{\"heading\":false,\"text\":\"Estas formas del filósofo aleman aunque poco á propósito para ilustrar la ciencia, no tendrian otro inconveniente que el de fatigar al lector, si se las limitase á lo que hemos visto hasta aquí; pero desgraciadamente, ese _yo_ misterioso que se nos hace aparecer en el vestíbulo mismo de la ciencia, y que á los ojos de la sana razon, no es ni puede ser otra cosa que lo que fué para Descartes, á saber, el espíritu humano que conoce su existencia por su propio pensamiento, va dilatándose en manos de Fichte como una sombra gigantesca, que comenzando por un punto acaba por ocultar su cabeza en el cielo y sus pies en el abismo. Ese _yo_ sujeto absoluto, es luego un ser que existe simplemente porque se pone á sí mismo; es un ser que se crea á sí propio, que lo absorbe todo, que lo es todo, que se revela en la conciencia humana como en una de las infinitas fases que comparten la existencia infinita.\"},{\"heading\":false,\"text\":\"Basta la presente indicacion para dar á conocer las tendencias del sistema de Fichte. Tratándose de la certeza y de sus fundamentos no seria oportuno adelantar lo que pienso decir largamente en el lugar que corresponde, al exponer la idea de sustancia y refutar el panteismo.\"},{\"heading\":false,\"text\":\"Este es uno de los graves errores de la filosofía de nuestra época; en todas partes, y bajo todos los aspectos, es menester combatirle; y para hacerlo con fruto conviene detenerle en sus primeros pasos. Por esto, he examinado con detencion la reflexion fundamental de Fichte en su _Doctrina de la ciencia_; despojándola de la importancia que el filósofo pretende atribuirle para establecer sobre ella una ciencia trascendental, pues que se lisonjea de poder determinar el principio absolutamente incondicional de todos los conocimientos humanos (VII).\"}]},{\"title\":\"CAPÍTULO VIII\",\"blocks\":[{\"heading\":false,\"text\":\"LA IDENTIDAD UNIVERSAL.\"},{\"heading\":false,\"text\":\"[85.] Para dar unidad á la ciencia apelan algunos á la identidad universal; pero esto no es encontrar la unidad, sino refugiarse en el caos.\"},{\"heading\":false,\"text\":\"Por de pronto la identidad universal, cuando no fuese absurda, es una hipótesis destituida de fundamento. Excepto la unidad de la conciencia, nada encontramos en nosotros que sea uno: muchedumbre de ideas, de percepciones, de juicios, de actos de voluntad, de impresiones las mas varias; esto es lo que sentimos en nosotros; multitud en los seres que nos rodean ó si se quiere en las apariencias; esto es lo que experimentamos con relacion á los objetos externos. ¿Dónde están pues la unidad y la identidad, si no se las encuentra ni en nosotros, ni fuera de nosotros?\"},{\"heading\":false,\"text\":\"[86.] Si se dice que todo cuanto se nos ofrece no son mas que fenómenos, y que no alcanzamos á la realidad, á la unidad idéntica y absoluta que se oculta debajo de ellos, se puede replicar con el siguiente dilema: ó nuestra experiencia se limita á los fenómenos, ó llega á la naturaleza misma de las cosas; si lo primero, no podemos saber lo que bajo los fenómenos se esconde, y la unidad idéntica y absoluta nos será desconocida; si lo segundo, luego la naturaleza no es una sino múltipla, pues que encontramos por todas partes la multiplicidad.\"},{\"heading\":false,\"text\":\"[87.] Es curioso observar la ligereza con que hombres escépticos en las cosas mas sencillas, se convierten de repente en dogmáticos, precisamente al llegar al punto donde mas motivos se ofrecen de duda. Para ellos el mundo exterior es ó una pura apariencia, ó un ser que nada tiene de semejante á lo que se figura el linaje humano; el criterio de la evidencia, el del sentido comun, el del testimonio de los sentidos son de escasa importancia para obligar al asenso; solo el vulgo debe contentarse con fundamentos tan ligeros: el filósofo necesita otros mucho mas robustos. Pero, ¡cosa singular! el mismo filósofo que llamaba á la realidad apariencia engañosa, que veia oscuro lo que el humano linaje considera claro, tan pronto como sale del mundo fenomenal y llega á las regiones de lo absoluto, se encuentra alumbrado por un resplandor misterioso, no necesita discurrir, sino que por una intuicion purísima ve lo incondicional, lo infinito, lo único, en que se refunde todo lo múltiplo, la gran realidad cimiento de todos los fenómenos, el gran todo que en su seno tiene la variedad de todas las existencias, que lo reasume todo, que lo absorbe todo en la mas perfecta identidad; fija la mirada del filósofo en aquel foco de luz y de vida, ve desarrollarse como en inmensas oleadas el piélago de la existencia, y así explica lo vario por lo uno, lo compuesto por lo simple, lo finito por lo infinito. Para estos prodigios no ha menester salir de sí propio, le basta ir destruyendo todo lo _empírico_, remontarse hasta el acto puro, por senderos misteriosos á todos desconocidos menos á él. Ese _yo_ que se creyera una existencia fugaz, dependiente de otra existencia superior, se asombra al descubrirse tan grande; en sí encuentra el orígen de todos los seres, ó por mejor decir el ser único del cual todos los demás son modificaciones fenomenales; él es el universo mismo que por un desarrollo gradual ha llegado á tener conciencia de sí propio; todo lo que contempla fuera de sí y que á primera vista le parece distinto, no es mas que él mismo, no es mas que un reflejo de sí propio, que se presenta á sus ojos y se desenvuelve bajo mil formas como un soberbio panorama.\"},{\"heading\":false,\"text\":\"¿Creerán los lectores que finjo un sistema para tener el gusto de combatirle? nada de eso: la doctrina que se acaba de exponer es la doctrina de Schelling.\"},{\"heading\":false,\"text\":\"[88.] Una de las causas de este error es la oscuridad del problema del conocimiento. El conocer es una accion inmanente y al propio tiempo relativa á un objeto externo, exceptuando los casos en que el ser inteligente se toma por objeto á sí propio con un acto reflejo. Para conocer una verdad sea la que fuere, el espíritu no sale de sí mismo; su accion no se ejerce fuera de sí mismo: la conciencia íntima le está diciendo que permanece en sí y que su actividad se desenvuelve dentro de sí.\"},{\"heading\":false,\"text\":\"Esta accion inmanente se extiende á los objetos mas distantes en lugar y tiempo y diferentes en naturaleza. ¿Cómo puede el espíritu ponerse en contacto con ellos? ¿Cómo puede explicarse que estén conformes la realidad y la representacion? Sin esta última no hay conocimiento; sin conformidad no hay verdad, el conocimiento es una pura ilusion á que nada corresponde, y el entendimiento humano es continuo juguete de vanas apariencias.\"},{\"heading\":false,\"text\":\"No puede negarse que hay en este problema dificultades gravísimas, quizás insuperables á la ciencia del hombre mientras vive sobre la tierra. Aquí se ofrecen todas las cuestiones ideológicas y psicológicas que han ocupado á los metafísicos mas eminentes. Pero como quiera que no es mi ánimo adelantar discusiones que pertenecen á otro lugar, me limitaré al punto de vista indicado por la cuestion que examino sobre la certeza y su principio fundamental.\"},{\"heading\":false,\"text\":\"[89.] Que existe la representacion es un hecho atestiguado por el sentido íntimo; sin ella no hay pensamiento; y la afirmacion _yo pienso_, es, si no el orígen de toda filosofía, al menos su condicion indispensable.\"},{\"heading\":false,\"text\":\"[90.] ¿De dónde viene la representacion? ¿cómo se explica que un ser se ponga en tal comunicacion con los demás, y no por una accion transitiva sino inminente? ¿cómo se explica la conformidad entre la representacion y los objetos? Este misterio, ¿no está indicando que en el fondo de todas las cosas hay unidad, identidad, que el ser que conoce es el mismo ser conocido que se aparece á sí propio bajo distinta forma, y que todo lo que llamamos realidades no son mas que fenómenos de un mismo ser siempre idéntico, infinitamente activo, que desenvuelve sus fuerzas en sentidos varios, constituyendo con su desarrollo ese conjunto que llamamos universo? Nó: no es así, no puede ser así, esto es un absurdo que la razon mas estraviada no alcanza á devorar; este es un recurso tan desesperado como impotente para explicar un misterio si se quiere, pero mil veces menos oscuro que el sistema con que se le pretende aclarar.\"},{\"heading\":false,\"text\":\"[91.] La identidad universal nada explica, mas bien confunde; no disipa la dificultad, la robustece, la hace insoluble. Es cierto que no es fácil dar razon del modo con que se ofrece al espíritu la representacion de cosas distintas de él; pero no es mas fácil el darla de cómo el espíritu puede tener representacion de sí propio. Si hay unidad, sí hay completa identidad, entre el sujeto y el objeto, ¿cómo es que los dos se nos ofrecen cual cosas distintas? de la unidad ¿cómo sale esta dualidad? de la identidad ¿cómo puede nacer la diversidad?\"},{\"heading\":false,\"text\":\"Es un hecho atestiguado por la experiencia, y no por la experiencia de los objetos exteriores, sino por la del sentido íntimo, por lo mas recóndito de nuestra alma, que en todo conocimiento hay sujeto y objeto, percepcion y cosa percibida, y sin esta diferencia no es posible el conocimiento. Aun cuando por un esfuerzo de reflexion nos tomamos por objetos á nosotros mismos, la dualidad aparece; si no existe la fingimos, pues sin esta ficcion no alcanzamos á pensar.\"},{\"heading\":false,\"text\":\"[92.] Si bien se observa, aun en la reflexion mas íntima y concentrada, la dualidad se halla, no por ficcion como á primera vista pudiera parecer, sino realmente. Cuando la inteligencia se vuelve sobre sí misma, no ve su esencia, pues no le es dada la intuicion directa de sí propia; lo que ve son sus actos, y á estos toma por objeto. Ahora bien; el acto reflexivo no es el mismo acto reflexionado; cuando pienso que pienso, el primer pensar es distinto del segundo, y tan distinto, que el uno sucede al otro, no pudiendo existir el pensar reflexivo, sin que antes haya existido el pensar reflexionado.\"},{\"heading\":false,\"text\":\"[93.] Un profundo análisis de la reflexion confirma lo que se acaba de explicar. ¿Es posible reflexionar sin objeto reflexionado? Es evidente que no. ¿Cuál es este objeto en el caso que nos ocupa? El pensamiento propio; luego este pensamiento ha debido preexistir á la reflexion. Si se supone que no hay necesidad de que se sucedan en diferentes instantes de tiempo, y que la dependencia se salva á pesar de la simultaneidad, todavía queda en pie la fuerza del argumento; dado y no concedido que lo simultaneidad sea posible, no lo es al menos la dependencia, si no hay distincion. La dependencia es una relacion; la relacion supone oposicion de extremos; y esta oposicion trae consigo la distincion.\"},{\"heading\":false,\"text\":\"[94.] Que estos actos son distintos, aun cuando se supongan simultáneos, se puede demostrar todavía de otra manera. Uno de ellos, el reflexionado, puede existir sin el reflexivo. Se piensa continuamente sin pensar en que se piensa; y de toda reflexion sea la que fuere, se puede verificar lo mismo, ya sea no presentándose ella para ocuparse del acto pensado, ya desapareciendo y dejando solo al acto directo: luego estos actos son no solo distintos sino separables; luego la dualidad de sujeto y de objeto existe no solo con respecto al mundo exterior, sino en lo mas íntimo, en lo mas puro de nuestra alma.\"},{\"heading\":false,\"text\":\"[95.] No vale decir que la reflexion no tiene por objeto un acto determinado, sino el pensamiento en general. Esto es falso en muchos casos, pues no solo pensamos que pensamos, sino que pensamos una cosa determinada. Además, aun cuando la reflexion tenga por objeto algunas veces el pensamiento en general, ni aun entonces la dualidad desaparece: el acto subjetivo es en tal caso un acto individual, que existe en determinado instante de tiempo, y su objeto es el pensamiento en general, es decir, una idea representante de todo pensamiento, una idea que envuelve una especie de recuerdo confuso de todos los actos pasados, ó de eso que se llama actividad, fuerza intelectual. La dualidad existe pues, mas evidente sí cabe, que cuando el objeto es un pensamiento determinado. En un caso se comparaban al menos dos actos individuales; mas en este se compara un acto individual con una idea abstracta, una cosa que existe en un instante de tiempo, con una idea que ó prescinde de él, ó abarca confusamente todo el trascurrido desde la época en que ha comenzado la conciencia del ser que reflexiona.\"},{\"heading\":false,\"text\":\"[96.] Estas razones tienen mucha mas fuerza dirigiéndose contra filósofos que ponen la esencia del espíritu, no en la fuerza de pensar, sino en el pensamiento mismo, que no dan al _yo_ mas existencia de la que nace de su propio conocimiento, afirmando que solo existe porque se _pone_ á sí mismo conociéndose, y que solo existe en cuanto se _pone_, es decir, en cuanto se conoce. Con este sistema no solo existe la dualidad ó mas bien la pluralidad en los actos, sino en el mismo _yo_; porque ese _yo_ es un acto, y los actos se suceden como una serie de fluxiones desenvueltas hasta lo infinito. Así, lejos de salvarse la unidad absoluta, ni la identidad entre el sujeto y el objeto, se establece la pluralidad y multiplicidad en el sujeto mismo; y la misma unidad de conciencia, en peligro de ser rasgada por las cavilaciones filosóficas, tiene que guarecerse á la sombra de la invencible naturaleza.\"},{\"heading\":false,\"text\":\"[97.] Queda probado pues de una manera incontestable, que hay en nosotros una dualidad primitiva entre el sujeto y el objeto; que sin esta no se concibe el conocimiento; y que la representacion misma es una palabra contradictoria, si de un modo ú otro no se admiten en los arcanos de la inteligencia cosas realmente distintas. Permítaseme recordar que de esta distincion hallamos un tipo sublime en el augusto misterio de la Trinidad, dogma fundamental de nuestra sacrosanta religion, cubierto con un velo impenetrable, pero de donde salen torrentes de luz para ilustrar las cuestiones filosóficas mas profundas. Este misterio no es explicado por el débil hombre; pero es para el hombre una explicacion sublime. Asi Platon se apoderó de las vislumbres de aquel arcano como de un tesoro de inmenso valor para las teorías filosóficas; asi los santos padres y los teólogos al esforzarse por aclararle con algunas razones de congruencia, han ilustrado los mas recónditos misterios del pensamiento humano.\"},{\"heading\":false,\"text\":\"[98.] Los sostenedores de la identidad universal á mas de contradecir uno de los hechos primitivos y fundamentales de la conciencia, no adelantan nada para explicar ni el orígen de la representacion intelectual, ni su conformidad con los objetos. Es evidente que ningun hombre posee la intuicion de la naturaleza del _yo_ individual, y mucho menos del ser absoluto que estos filósofos suponen como el _substratum_, de todo lo que existe ó aparece. Sin esta intuicion, no les será posible explicar _à priori_ la representacion de los objetos, ni tampoco la conformidad de estos con aquella. El hecho pues en que se quiere cimentar toda la filosofía, ó no existe, ó nos es desconocido, en ambos casos no puede servir para fundar un sistema.\"},{\"heading\":false,\"text\":\"Si este hecho existiese no se podria presentar á nuestro entendimiento por medio de una enunciacion á que llegásemos por raciocinio. Ha de ser mas bien visto que conocido; ó ha de ocupar el primer lugar ó ninguno. Si empezamos por raciocinar sin tomarle á él por fundamento, estribamos en lo aparente para llegar á lo verdadero; nos valemos de la ilusion para alcanzar la realidad. Así resulta evidentemente del sistema de nuestros adversarios, que, ó la filosofía debe comenzar por la intuicion mas poderosa que imaginarse pueda, ó no le es dable adelantar un paso.\"},{\"heading\":false,\"text\":\"[99.] Las escuelas distinguian entre el principio de ser y el de conocer, _principium essendi et principium cognoscendi_; mas esta distincion no tiene cabida en el sistema filosófico que impugnamos; el ser se confunde con el conocer; lo que existe, existe porque se conoce, y solo existe en cuanto se conoce. Deducir la serie de los conocimientos es desenvolver la serie de la existencia. No hay ni siquiera dos movimientos paralelos, no hay mas que un movimiento; el _yo_ es el universo, el universo es el _yo_; todo cuanto existe es un desarrollo del hecho primitivo, es el mismo hecho que se despliega ofreciendo diferentes formas, extendiéndose como un océano infinito: su lugar es un espacio sin límites, su duracion la eternidad (VIII).\"}]},{\"title\":\"CAPÍTULO IX\",\"blocks\":[{\"heading\":false,\"text\":\"CONTINÚA EL EXÁMEN DEL SISTEMA DE LA IDENTIDAD UNIVERSAL.\"},{\"heading\":false,\"text\":\"[100.] Estos sistemas tan absurdos como funestos, y que bajo formas distintas y por diversos caminos, van á parar al panteismo, encierran no obstante una verdad profunda, que desfigurada por vanas cavilaciones, se presenta como un abismo de tinieblas, cuando en sí es un rayo de vivísima luz.\"},{\"heading\":false,\"text\":\"El espíritu humano busca con el discurso lo mismo á que le impele un instinto intelectual: el modo de reducir la pluralidad á la unidad, de recoger por decirlo así la variedad infinita de las existencias en un punto del cual todas dimanen y en que se confundan. El entendimiento conoce que lo condicional ha de refundirse en lo incondicional, lo relativo en lo absoluto, lo finito en lo infinito, lo múltiplo en lo uno. En esto convienen todas las religiones, todas las escuelas filosóficas. La proclamacion de esta verdad no pertenece á ninguna exclusivamente; se la encuentra en todos los paises del mundo, en los tiempos primitivos, junto á la cuna de la humanidad. Tradicion bella, tradicion sublime, que conservada al través de todas las generaciones, entre el flujo y reflujo de los acontecimientos, nos presenta la idea de la divinidad presidiendo al orígen y al destino del universo.\"},{\"heading\":false,\"text\":\"[101.] Sí: la unidad buscada por los filósofos es la Divinidad misma, es la Divinidad cuya gloria anuncia el firmamento y cuya faz augusta nos aparece en lo interior de nuestra conciencia con resplandor inefable. Sí: ella es la que ilumina y consuela al verdadero filósofo, y ciega y perturba al orgulloso sofista; ella es la que el verdadero filósofo llama Dios, á quien acata y adora en el santuario de su alma, y la que el filósofo insensato apellida el _yo_ con profanacion sacrílega; ella es la que considerada con su personalidad, con su conciencia, con su inteligencia infinita, con su perfectísima libertad, es el cimiento y la cúpula de la religion; ella es la que distinta del mundo le ha sacado de la nada, la que le conserva, le gobierna, le conduce por misteriosos senderos al destino señalado en sus decretos inmutables.\"},{\"heading\":false,\"text\":\"[102.] Hay pues unidad en el mundo; hay unidad en la filosofía; en esto convienen todos; la diferencia está en que unos separan con muchísimo cuidado lo infinito de lo finito, la fuerza creatriz de la cosa creada, la unidad de la multiplicidad, manteniendo la comunicacion necesaria entre la libre voluntad del agente todopoderoso y las existencias finitas, entre la sabiduría de la soberana inteligencia y la ordenada marcha del universo; mientras los otros tocados de una ceguera lamentable, confunden el efecto con la causa, lo finito con lo infinito, lo vario con lo uno; y reproducen en la region de la filosofía el caos de los tiempos primitivos; pero todo en dispersion, todo en confusion espantosa, sin esperanza de reunion ni de órden: la tierra de esos filósofos está vacía, las tinieblas yacen sobre la faz del abismo, mas no hay el espíritu de Dios llevado sobre las aguas para fecundar el caos y hacer que surjan de las sombras y de la muerte piélagos de luz y de vida.\"},{\"heading\":false,\"text\":\"Con los absurdos sistemas excogitados por la vanidad filosófica, nada se aclara; con el sistema de la religion que es al propio tiempo el de la sana filosofía y el de la humanidad entera, todo se explica; el mundo de las inteligencias como el mundo de los cuerpos es para el espíritu humano un caos desde el momento en que desecha la idea de Dios; ponedla de nuevo, y el órden reaparece.\"},{\"heading\":false,\"text\":\"[103.] Los dos problemas capitales: ¿de dónde nace la representacion intelectual? ¿de dónde su conformidad con los objetos? tienen entre nosotros una explicacion muy sencilla. Nuestro entendimiento aunque limitado, participa de la luz infinita: esta luz no es la que existe en el mismo Dios, es una semejanza comunicada á un ser, criado á imágen del mismo Dios.\"},{\"heading\":false,\"text\":\"Con el auxilio de esta luz resplandecen los objetos á los ojos de nuestro espíritu; ya sea que aquellos estén en comunicacion con este por medios que nos son desconocidos; ya sea que la representacion nos haya sido dada directamente por Dios á la presencia de los objetos.\"},{\"heading\":false,\"text\":\"La conformidad de la representacion con la cosa representada, es un resultado de la veracidad divina. Un Dios infinitamente perfecto no puede complacerse en engañar á sus criaturas. Esta es la teoría de Descartes y Malebranche: pensadores eminentes que no sabian dar un paso en el órden intelectual sin dirigir una mirada al Autor de todas las luces, que no acertaban á escribir una página donde no pusiesen la palabra Dios.\"},{\"heading\":false,\"text\":\"[104.] Como veremos en su lugar, admitia Malebranche que el hombre lo ve todo en Dios mismo, aun en esta vida; pero su sistema lejos de identificar el _yo_ humano con el ser infinito, los distinguia cuidadosamente, no encontrando otro medio para sostener é iluminar al primero que acercarle y unirle al segundo. Basta leer la obra inmortal del insigne metafísico para convencerse de que su sistema no era el de esa intuicion primitiva, purísima, que es un acto despegado de todo empirismo, y que parece salir de las regiones de la individualidad, de esa intuicion del hecho simple, orígen de todas las ideas y de todos los hechos, y en que, uno de los dogmas de nuestra religion; la vision beatífica, parece realizado sobre la tierra, en la region de la filosofía. Estas son pretensiones insensatas, que estaban muy lejos del ánimo y del sistema de Malebranche (IX).\"}]},{\"title\":\"CAPÍTULO X\",\"blocks\":[{\"heading\":false,\"text\":\"EL PROBLEMA DE LA REPRESENTACION. MÓNADAS DE LEIBNITZ.\"},{\"heading\":false,\"text\":\"[105.] La pretension de encontrar una verdad real en que se funden todas las demás, es sumamente peligrosa, por mas que á primera vista parezca indiferente. El panteismo ó la divinizacion del _yo_, dos sistemas que en el fondo coinciden, son una consecuencia que difícilmente se evita, si se quiere que toda la ciencia humana nazca de un hecho.\"},{\"heading\":false,\"text\":\"[106.] La verdad real, ó el hecho que serviria de base á toda ciencia, debiera ser percibido inmediatamente. Sin esta inmediacion le faltaria el carácter de orígen y cimiento de las demás verdades; pues que el medio con que le percibiriamos, tendria mas derecho que él al título de verdad primera. Si este hecho mediador fuese causa del otro, es evidente que este último no seria el primero; y si la anterioridad no se refiriese al órden de ser sino de conocer, entonces resultarian las mismas dificultades que tenemos ahora para explicar la transicion del sujeto al objeto, ó sea la legitimidad del medio que nos haría percibir el hecho primitivo.\"},{\"heading\":false,\"text\":\"Siendo necesaria la inmediacion, la union íntima de la inteligencia con el hecho conocido, claro es que como esta inmediacion no la tiene el _yo_ sino para sí mismo y para sus propios actos, el hecho buscado ha de ser el mismo _yo_. Lo que tenemos inmediatamente presente son los hechos de nuestra conciencia; por ellos nos ponemos en comunicacion con lo que es distinto de nosotros mismos. En el caso pues de deberse encontrar un hecho primitivo orígen de todos los demás, este hecho seria el mismo _yo_. En no admitiendo esta consecuencia, es necesario declarar inadmisible la posibilidad de encontrar el hecho fuente de la ciencia trascendental. Hé aquí como las pretensiones filosóficas en apariencia mas inocentes, conducen á resultados funestos.\"},{\"heading\":false,\"text\":\"[107.] Hay aquí un efugio, bien débil por cierto, pero que es bastante especioso para que merezca ser examinado.\"},{\"heading\":false,\"text\":\"El hecho, orígen científico de todos los demás, no es necesario que sea orígen verdadero. Distinguiendo entre el principio de ser y el principio de conocer, parecen quedar salvadas todas las dificultades. Es absurdo, y además contrario al sentido comun, que el _yo_ sea orígen de todo lo que existe; pero no lo es que sea principio representativo de todo lo que se conoce y se puede conocer. La representacion no es sinónima de causalidad. Las ideas representan y no causan los objetos representados. ¿Por qué pues no se podria admitir que existe un hecho representativo de todo lo que el humano entendimiento puede conocer? Es cierto que la percepcion de este hecho ha de ser inmediata, que se le ha de suponer íntimamente presente á la inteligencia que le percibe, por cuyo motivo no puede ser otra cosa que el mismo _yo_; pero esto no diviniza al _yo_, solo le concede una fuerza representativa que puede haberle sido comunicada por un ser superior. Hace del _yo_, nó una causa universal, sino un espejo en que reflejan el mundo interno y el externo.\"},{\"heading\":false,\"text\":\"Esta explicacion recuerda el famoso sistema de las mónadas de Leibnitz, sistema ingenioso, arranque sublime de uno de los genios mas poderosos que honraron jamás al humano linaje. El mundo entero formado de seres indivisibles, todos representativos del mismo universo del cual forman parte, pero con representacion adecuada á su categoría respectiva y con arreglo al punto de vista que les corresponde segun el lugar que ocupan; desenvolviéndose en una serie inmensa que principiando por el órden mas inferior va subiendo en gradacion continua hasta los umbrales de lo infinito; y en la cúspide de todas las existencias la mónada que contiene en sí la razon de todas, que las ha sacado de la nada, les ha dado la fuerza representativa, las ha distribuido en sus convenientes categorías estableciendo entre todas ellas una especie de paralelismo de percepcion, de voluntad, de accion, de movimiento, de tal suerte que sin comunicarse nada las unas á las otras, marchen todas en la mas perfecta conformidad, en inefable armonía; esto es grande, esto es bello, esto es asombroso, esta es una hipótesis colosal que solo concebir pudiera el genio de Leibnitz.\"},{\"heading\":false,\"text\":\"[108.] Pagado este tributo de admiracion al eminente autor de la _Monadología_, advertiré que su concepcion gigantesca es solo una hipótesis que todos los recursos del talento de su inventor no bastaron á fundar en ningun hecho que le diera visos de probabilidad. Prescindiré tambien de las dificultades gravísimas que, contra la voluntad del autor sin duda, ofrece esta hipótesis á la explicacion del libre alvedrío: me ceñiré al exámen de las relaciones de dicho sistema con la cuestion que me ocupa.\"},{\"heading\":false,\"text\":\"En primer lugar, siendo la representacion de las mónadas una mera hipótesis, no sirve para explicar nada, á no ser que la filosofía se convierta en un juego de combinaciones ingeniosas. El _yo_ es una mónada, esto es, una unidad indivisible; en esto no cabe duda; el _yo_ es una mónada representativa del universo; esta es una afirmacion absolutamente gratuita. Hasta que se la pruebe de un modo ú otro, tenemos derecho á no querer ocuparnos de ella.\"},{\"heading\":false,\"text\":\"[109.] Pero supongamos que la fuerza representativa tal como la entiende Leibnitz, exista en el _yo_; esta hipótesis no destruye lo que se ha dicho contra el orígen primitivo de la ciencia trascendental. Si bien se observa, la hipótesis de Leibnitz explica el orígen de las ideas, mas nó su enlace. Hace del alma un espejo en que por efecto de la voluntad creatriz, se representa todo; pero no explica el órden de estas representaciones, no da razon de cómo unas nacen de otras, ni les señala otro vínculo que la unidad de la conciencia. Este sistema pues, se halla fuera de la cuestion; no disputamos sobre el modo con que las representaciones existen en el alma, ni sobre la procedencia de ellas, sino que examinamos la opinion que pretende fundar toda la ciencia en un solo hecho, desenvolviendo todas las ideas, como simples modificaciones del mismo. Esto jamás lo ha dicho Leibnitz; ni en sus obras se encuentra nada que indique semejante pensamiento. Además, las diferencias entre el sistema del autor de la Monadología y el de los filósofos alemanes que estamos impugnando, son demasiado palpables para que puedan ocultarse á nadie.\"},{\"heading\":false,\"text\":\"1.º Tan lejos está Leibnitz de la identidad universal, que establece una pluralidad y multiplicidad infinitas: sus mónadas son seres realmente distintos y diferentes entre sí.\"},{\"heading\":false,\"text\":\"2.º Todo el universo compuesto de mónadas ha procedido segun Leibnitz, de una mónada infinita; y esta procedencia no es por emanacion sino por creacion.\"},{\"heading\":false,\"text\":\"3.º En la mónada infinita ó en Dios, pone Leibnitz la razon suficiente de todo.\"},{\"heading\":false,\"text\":\"4.º El conocimiento les ha sido dado á las mónadas _libremente_ por el mismo Dios.\"},{\"heading\":false,\"text\":\"5.º Dicho conocimiento y la conciencia de él, les pertenece á las mónadas individualmente, sin que Leibnitz pensase ni remotamente en ese _absoluto_, fondo de todas las cosas, que con sus trasformaciones se eleva de naturaleza á conciencia, ó desciende de la region de la conciencia y se convierte en naturaleza.\"},{\"heading\":false,\"text\":\"[110.] Estas diferencias tan marcadas, no han menester comentarios; ellas manifiestan hasta la última evidencia que los filósofos alemanes modernos no pueden escudarse con el nombre de Leibnitz; bien que á decir verdad no es este el flaco de esos filósofos; lejos de buscar guias, todos aspiran á la originalidad, siendo esta una de las principales causas de sus estravagancias. Hegel, Schelling y Fichte todos pretenden ser fundadores de una filosofía; y Kant abrigaba la misma ambicion, hasta el punto de hacer alteraciones gravísimas en su segunda edicion de la _Crítica de la razon pura_, por temor de que se le tuviese por plagiario del idealismo de Berkeley (X).\"}]},{\"title\":\"CAPÍTULO XI\",\"blocks\":[{\"heading\":false,\"text\":\"EXÁMEN DEL PROBLEMA DE LA REPRESENTACION.\"},{\"heading\":false,\"text\":\"[111.] Todo lo conocemos por la representacion; sin ella el conocimiento es inconcebible; no obstante ¿qué es la representacion considerada en sí? Lo ignoramos; nos ilumina para lo demás, pero nó para conocerla á ella misma.\"},{\"heading\":false,\"text\":\"Bien se echa de ver que no disimulo las gravísimas dificultades que ofrece la solucion del presente problema; por el contrario las señalo con toda claridad para evitar desde el principio la vana presuncion, que pierde en las ciencias como en todo. Mas no se crea que intente desterrar esta cuestion del dominio de la filosofía; opino que las dificultades aunque son muchas y espinosas, permiten sin embargo conjeturas bastante probables.\"},{\"heading\":false,\"text\":\"[112.] La fuerza representativa puede dimanar de tres fuentes: identidad, causalidad, idealidad. Me explicaré. Una cosa puede representarse á si misma; esta representacion es la que llamo de identidad. Una causa puede representar á sus efectos; esto entiendo por representacion de causalidad. Un ser, sustancia ó accidente, puede ser representativo de otro, distinto de él y que no es su efecto; á este llamo representacion de idealidad.\"},{\"heading\":false,\"text\":\"No veo que puedan señalarse otras fuentes de la representacion; y así teniendo la division por completa, voy á examinar sus tres partes, llamando muy especialmente sobre este punto la atencion del lector, por ser uno de los mas importantes de la filosofía.\"},{\"heading\":false,\"text\":\"[113.] Lo que representa ha de tener alguna relacion con la cosa representada. Esencial ó accidental, propia ó comunicada, la relacion ha de existir. Dos seres que no tienen absolutamente ninguna relacion, y sin embargo, el uno representante del otro, son una monstruosidad. Nada hay sin razon suficiente; y no existiendo ninguna relacion entre el representante y el representado, no habria razon suficiente de la representacion.\"},{\"heading\":false,\"text\":\"Téngase en cuenta que por ahora prescindo de la naturaleza de esta relacion, no afirmo que sea real ni ideal, solo digo que entre lo representante y lo representado ha de haber algun vínculo sea el que fuere. Sus misterios, su incomprensibilidad, no destruirian su existencia. La filosofía será impotente quizás para explicar el enigma, pero es bastante á demostrar que el vínculo existe. Así es que prescindiendo de toda experiencia, se puede demostrar _à priori_ que hay una relacion entre el _yo_ y los demás seres, por el mero hecho de existir la representacion de estos en aquel.\"},{\"heading\":false,\"text\":\"La incesante comunicacion en que están las inteligencias entre sí y con el universo, prueba que hay un punto de reunion para todo. La sola representacion es de ello una prueba incontestable; tantos seres en apariencia dispersos é indiferentes unos á otros, están íntimamente unidos en algun centro; por manera que el simple fenómeno de la inteligencia nos conduce á la afirmacion del vínculo comun, de la unidad en que se enlaza la pluralidad. Esta unidad es para los panteistas la identidad universal, para nosotros es Dios.\"},{\"heading\":false,\"text\":\"[114.] Adviértase que esta relacion entre lo representante y lo representado, no es necesario que sea directa ó inmediata; basta que sea con un tercero; así han de admitirla tanto los que explican la representacion por la identidad, como los que dan razon de ella por las ideas intermedias, sin que para el caso presente, haya ninguna diferencia entre los que las consideran producidas por la accion de los objetos sobre nuestro espíritu, y los que las hacen dimanar inmediatamente de Dios.\"},{\"heading\":false,\"text\":\"[115.] Todo la que representa contiene en cierto modo la cosa representada; esta no puede tener carácter de tal si de alguna manera no se halla en la representacion. Puede ser ella misma ó una imágen suya, pero esta imágen no representará al objeto si no se sabe que es imágen. Toda idea pues, encierra la relacion de objetividad, de otro modo no representaria al objeto, sino á sí misma. El acto de entender es inmanente, pero de tal modo que el entendimiento sin salir de sí, se apodera del objeto mismo. Cuando pienso en un astro colocado á millones de leguas de distancia, mi espíritu no va ciertamente al punto donde el astro se halla; pero por medio de la idea salva en un instante la inmensa distancia y se une con el astro mismo. Lo que percibe, no es la idea sino el objeto de ella; si esta idea no envolviese una relacion al objeto, dejaria de ser idea para el espíritu, no le representaria nada, á no ser que se representase á sí misma.\"},{\"heading\":false,\"text\":\"[116.] Hay pues en toda percepcion una union del ser que percibe con la cosa percibida; cuando esta percepcion no es inmediata, el medio ha de ser tal que contenga una relacion necesaria al objeto; se ha de ocultar á sí propio para no ofrecer á los ojos del espíritu sino la cosa representada. Desde el momento que él se presenta, que es visto ó solamente advertido, deja de ser idea y pasa á ser objeto. Es la idea un espejo que será tanto mas perfecto cuanto mas completa produzca la ilusion. Es necesario que presente los objetos solos, proyectándolos á la conveniente distancia, sin que el ojo vea nada del cristalino plano que los refleja.\"},{\"heading\":false,\"text\":\"[117.] Esta union de lo representante con lo representado, de lo inteligente con lo entendido, puede explicarse en algunos casos por la identidad. En general no se descubre ninguna contradiccion en que una cosa se represente á si misma á los ojos de una inteligencia, si se supone que de un modo ú otro estén unidas. En el caso pues de que la cosa conocida sea ella misma inteligente, no se ve ninguna dificultad en que ella sea para sí misma su propia representacion y que de consiguiente se confundan en un mismo ser la idealidad y la realidad.\"},{\"heading\":false,\"text\":\"Si una idea puede representar á un objeto, ¿por qué este no se podrá representar á sí mismo? si un ser inteligente puede conocer un objeto, mediante una idea, ¿por qué no le podrá conocer inmediatamente? La union de la cosa entendida con la inteligente será para nosotros un misterio, es verdad; ¿pero lo es menos la union, que se hace por medio de la idea? A esta se puede objetar todo lo que se diga contra la cosa misma; y aun si bien se considera, mas inexplicable es el que una cosa represente á otra, que no que se represente á sí misma. Lo representante y lo representado tienen entre sí una especie de relacion de continente y contenido; fácilmente se concibe que lo idéntico se contenga á sí mismo, pues que la identidad expresa mucho mas que el contener; pero no se concibe tan bien cómo el accidente _puede contener_ á la substancia, lo transitorio á lo permanente, lo ideal á lo real. Es pues la identidad un verdadero principio de representacion.\"},{\"heading\":false,\"text\":\"[118.] Aquí advertiré lo siguiente, que es muy necesario para evitar equivocaciones.\"},{\"heading\":false,\"text\":\"1º. No afirmo la relacion necesaria entre la identidad y la representacion; de lo contrario se afirmaria que todo ser ha de ser representativo, ya que todo ser es idéntico consigo mismo. Establezco esta proposicion: «la identidad puede ser orígen de representacion;» pero niego las siguientes: «la identidad es orígen _necesario_ de representacion;» «la representacion es signo de identidad.»\"},{\"heading\":false,\"text\":\"2º. Nada determino con respecto á la aplicacion de las relaciones entre la representacion y la identidad en lo que concierne á los seres finitos.\"},{\"heading\":false,\"text\":\"3º. Prescindo de la dualidad que existe por solo suponer sujeto y objeto, y no entro en ninguna cuestion sobre la naturaleza de esta dualidad.\"},{\"heading\":false,\"text\":\"[119.] Fijadas las ideas, advertiré que tenemos una prueba irrecusable de que no hay repugnancia intrínseca entre la identidad y la representacion, en dos dogmas de la religion católica; el de la vision beatífica y el de la inteligencia divina. El dogma de la vision beatífica nos enseña que el alma humana en la mansion de los bienaventurados, está unida íntimamente con Dios, viéndole cara á cara, en su misma esencia. Nadie ha dicho que esta vision se hiciese por medio de una idea, antes bien los teólogos enseñan lo contrario, entre ellos Santo Tomás. Tenemos pues la identidad unida con la representacion, es decir la esencia divina representándose ó mas bien presentándose á sí propia á los ojos del espíritu humano. El dogma de la inteligencia divina nos enseña que Dios es infinitamente inteligente. Dios, para entender, no sale de sí mismo, no se vale de ideas distintas, se ve á sí mismo en su esencia. Dios no se distingue de su esencia; tenemos pues la identidad unida con la representacion, y el ser inteligente identificado con la cosa entendida (XI).\"}]},{\"title\":\"CAPÍTULO XII\",\"blocks\":[{\"heading\":false,\"text\":\"INTELIGIBILIDAD INMEDIATA.\"},{\"heading\":false,\"text\":\"[120.] No todas las cosas tienen representacion activa ni aun pasiva; quiero decir que no todas están dotadas de actividad intelectual, ni son aptas para terminar el acto del entendimiento ni aun pasivamente.\"},{\"heading\":false,\"text\":\"Por lo tocante á la fuerza de representacion activa, que en el fondo no es mas que la capacidad de entender, es evidente que son muchos los seres destituidos de ella. Alguna mayor dificultad puede haber con respecto á la representacion pasiva ó á la disposicion para ser objeto _inmediato_ de la inteligencia.\"},{\"heading\":false,\"text\":\"[121.] Un objeto no puede ser conocido inmediatamente, es decir, sin la mediacion de una idea, si el propio no hace las veces de esta idea, uniéndose al entendimiento que lo ha de conocer. Esta sola razon quita á todas las cosas materiales el carácter de _inmediatamente_ inteligibles, por manera que fingiendo un espíritu á quien no se hubiese dado una idea del universo corpóreo, nada conoceria de este aunque estuviese en medio del mismo por toda la eternidad.\"},{\"heading\":false,\"text\":\"Resulta de esto que la materia no es ni puede ser ni inteligente ni inteligible; las ideas que tenemos de ella han dimanado de otra parte; sin cuyo auxilio podriamos estar ligados á la misma, sin conocerla nunca, ni sospechar que existiese.\"},{\"heading\":false,\"text\":\"[122.] Aquí se me ofrece la oportunidad de exponer una doctrina de Santo Tomás sumamente curiosa. Este metafísico eminente es de parecer que requiere mas perfeccion el ser inmediatamente inteligible que el ser inteligente, de manera que el alma humana dotada de la inteligencia no posee la inteligibilidad.\"},{\"heading\":false,\"text\":\"En la primera parte de la Suma teológica, cuestion 87, artículo 1º, pregunta el Santo Doctor si el alma se conoce á sí misma por su esencia, y responde que nó, apoyando su opinion de la manera siguiente. Las cosas son inteligibles en cuanto están en acto y no en cuanto están en potencia; lo que cae bajo el conocimiento es el ser, lo verdadero, en cuanto está en acto, así como la vista percibe, no lo que puede ser colorado, sino lo que lo es. De esto se sigue que las substancias inmateriales en tanto son inteligibles por su esencia, en cuanto están en acto, y así la esencia de Dios; que es un acto puro y perfecto, es absoluta y perfectamente inteligible por sí misma, y de aquí es que por ella Dios se conoce á sí mismo y á todas las cosas. La esencia del ángel pertenece al género de las cosas inteligibles en cuanto es acto; pero como no es acto puro ni completo, su entender no se completa por su esencia. Pues aunque el ángel se conozca á sí mismo por su esencia, no conoce las demás cosas sino por ideas que las representan. El entendimiento humano, en el género de las cosas inteligibles, se halla como un ser en potencia tan solamente, por lo cual considerado en su esencia tiene facultad para entender mas nó para ser entendido, sino en cuanto se pone en acto. Por esta causa los platónicos señalaron á los seres inteligibles un rango superior á los entendimientos, porque el entendimiento no entiende sino por la participacion inteligible; y segun ellos, el que participa es menos perfecto que la cosa participada. Si pues el entendimiento humano se pusiese en acto por la participacion de las formas inteligibles separadas como opinaron los platónicos, el entendimiento humano se conoceria á sí mismo por la participacion de ellas; pero como es natural á nuestro entendimiento en la presente vida el entender con relacion á las cosas sensibles, no se pone en acto sino por las ideas sacadas de la experiencia sensible por la luz del entendimiento agente que es el acto de las cosas inteligibles; y así el entendimiento no se conoce por su esencia sino por su propio acto. Esta es en substancia, la doctrina de Santo Tomás; que mas bien he traducido que no extractado.\"},{\"heading\":false,\"text\":\"El cardenal Cayetano, uno de los entendimientos mas penetrantes y sutiles que han existido jamás, pone sobre este lugar un comentario digno del texto. Hé aquí sus palabras: «de lo dicho en el texto resultan dos cosas. 1.ª Que nuestro entendimiento tiene por sí mismo la facultad de entender. 2.ª Que no tiene la de ser entendido; de donde se sigue que el órden de los entendimientos es inferior al de las cosas inteligibles; pues que si la perfeccion que de sí tiene nuestro entendimiento le basta para entender, mas nó para ser entendido, se infiere que se necesita mas perfeccion para ser entendido que para entender. Y como Santo Tomás veia que así resultaba de lo dicho, y esto á primera vista no parece ser verdad, antes se le podia objetar lo mismo como un inconveniente, por esto excluye semejante aprehension manifestando que así lo debian admitir no solo los peripatéticos, en cuya doctrina se fundaba, sino tambien los platónicos.»\"},{\"heading\":false,\"text\":\"Mas abajo, respondiendo á una dificultad de Escoto, llamado el doctor sutil, añade, «Para entender se necesita entendimiento é inteligible. La relacion de aquel á este es la de lo perfectible á la propia perfeccion; pues que el estar el entendimiento en acto consiste en que él sea la misma cosa inteligible segun se ha dicho antes; de donde se sigue que los seres inmateriales se distribuyen en dos órdenes, inteligibles é inteligentes. Y como el ser inteligible consiste un ser inmaterialmente perfectivo; resulta que una cosa en tanto es inteligible, en cuanto es inmaterialmente perfectiva. Que la inteligibilidad exija la inmaterialidad lo demuestra el que las cosas materiales no son inteligibles sino en cuanto están abstraidas de la materia............................................................. .......Se ha manifestado mas arriba que una cosa es inteligente en cuanto es no solo ella misma sino las otras en el órden ideal; este modo de ser es en acto ó en potencia, y así no es mas que ser perfeccionado ó perfectible por la cosa entendida.»\"},{\"heading\":false,\"text\":\"[123.] Esta teoría será mas ó menos sólida, pero de todos modos es algo mas que ingeniosa; suscita un nuevo problema filosófico de la mas alta importancia: señalar las condiciones de la inteligibilidad. Además tiene la ventaja de estar acorde con un hecho atestiguado por la experiencia, cual es, la dificultad que siente el espíritu en conocerse á sí propio. Si fuese inteligible inmediatamente, ¿por qué no se conoce á sí mismo? ¿qué condicion le falta? ¿Acaso la presencia íntima? tiene no solo la presencia sino la identidad. ¿Por ventura el esfuerzo para conocerse? la mayor parte de la filosofía no tiene otro fin que este conocimiento. Negando al alma la inteligibilidad inmediata se explica por qué es tanta la dificultad que envuelven las investigaciones ideológicas y psicológicas, señalándose la razon de la obscuridad que sentimos al pasar de los actos directos á los reflejos.\"},{\"heading\":false,\"text\":\"[124.] La opinion de Santo Tomás sobre no ser una simple conjetura, por fundarse en algun modo sobre un hecho, puede apoyarse en una razon que en mi concepto la robustece mucho, y que tal vez puede ser mirada como una ampliacion de la señalada mas arriba.\"},{\"heading\":false,\"text\":\"Para ser una cosa inmediatamente inteligible es menester suponerle dos calidades, 1.ª La inmaterialidad. 2.ª La actividad necesaria para operar sobre el ser inteligente. Esta actividad es indispensable; porque si bien se observa, en la operacion de entender, la accion nace de la idea; el entendimiento en cierto modo está pasivo. Cuando la idea se ofrece, no es posible no entender; y cuando falta, es imposible entender; la idea pues fecunda al entendimiento, y este sin aquella nada puede. Por consiguiente si admitimos que un ser puede servir de idea á un entendimiento, es necesario que le concedamos una actividad para excitar la operacion intelectual y que por tanto le hagamos superior al entendimiento excitado.\"},{\"heading\":false,\"text\":\"De esta suerte se explica por qué nuestro entendimiento, al menos mientras nos hallamos en esta vida, no es inteligible por si mismo para sí mismo. La experiencia atestigua que su actividad ha menester excitacion. Entregado á sí propio como que duerme: es uno de los hechos psicológicos mas constantes la falta de actividad en nuestro espíritu, cuando no han precedido influencias excitantes.\"},{\"heading\":false,\"text\":\"No es esto decir que estemos destituidos de espontaneidad, y que ninguna accion sea posible sin una causa externa determinante; pero sí que el mismo desarrollo espontáneo no existiria, si anteriormente no hubiésemos estado sometidos al influjo de causas que han dispertado nuestra actividad. Podemos aprender cosas que no se nos enseñan; pero nada podriamos aprender si al primitivo desarrollo de nuestro espíritu no hubiese presidido la enseñanza. Hay en nuestro espíritu muchas ideas que no son sensaciones ni pueden haber dimanado de ellas, es verdad; pero tambien lo es que un hombre que careciese de todos los sentidos, nada pensaria por faltarle á su espíritu la causa excitante.\"},{\"heading\":false,\"text\":\"[125.] Me he detenido en la explicacion del problema de la inteligibilidad, porque en mi concepto es poco menos importante que el de la inteligencia, por mas que no se le vea tratado cual merece en las obras filosóficas. Ahora voy á reducir la doctrina anterior á proposiciones claras y sencillas; ya para que el lector se forme de ella concepto mas cabal; ya tambien para deducir algunas consecuencias que no se han tocado en la exposicion, ó han sido solamente indicadas.\"},{\"heading\":false,\"text\":\"1.ª Para ser una cosa inmediatamente inteligible, debe ser inmaterial.\"},{\"heading\":false,\"text\":\"2.ª La materia por sí misma no puede ser inteligible.\"},{\"heading\":false,\"text\":\"3.ª La relacion entre los espíritus y los cuerpos, ó la representacion de estos en aquellos, no puede ser de pura objetividad.\"},{\"heading\":false,\"text\":\"4.ª Es necesario admitir algun otro género de relacion con que se explique la union representativa del mundo de las inteligencias y del mundo corpóreo.\"},{\"heading\":false,\"text\":\"5.ª La representacion objectiva inmediata, supone actividad en el objeto.\"},{\"heading\":false,\"text\":\"6.ª La fuerza de representarse un objeto por sí mismo á los ojos de una inteligencia, supone en aquel una facultad de obrar sobre esta.\"},{\"heading\":false,\"text\":\"7.ª Esta facultad de obrar produce necesariamente su efecto; y por consiguiente envuelve una especie de superioridad del objeto sobre la inteligencia.\"},{\"heading\":false,\"text\":\"8.ª Un ser inteligente puede no ser inmediatamente inteligible.\"},{\"heading\":false,\"text\":\"9.ª La inteligibilidad inmediata, parece encerrar mayor perfeccion que la misma inteligencia.\"},{\"heading\":false,\"text\":\"10.ª Aunque no todo ser inteligente sea inteligible, todo ser inteligible es inteligente.\"},{\"heading\":false,\"text\":\"11.ª Dios, actividad infinita en todos sentidos, es infinitamente inteligente é infinitamente inteligible para sí mismo.\"},{\"heading\":false,\"text\":\"12.ª Dios es inteligible para todos los entendimientos creados, siempre que él quiera presentarse inmediatamente á ellos, fortaleciéndolos y elevándolos de la manera conveniente.\"},{\"heading\":false,\"text\":\"13.ª No hay ninguna repugnancia en que la inteligibilidad inmediata se haya comunicado á algunos espíritus, y por consiguiente el que estos sean inteligibles por sí mismos.\"},{\"heading\":false,\"text\":\"14.ª Nuestra alma mientras está unida al cuerpo, no es inmediatamente inteligible, y solo la conocemos por sus actos.\"},{\"heading\":false,\"text\":\"15.ª En esta falta de inteligibilidad inmediata se encuentra la razon de la dificultad de los estudios ideológicos y psicológicos, y de la obscuridad que experimentamos al pasar del conocimiento directo al reflejo.\"},{\"heading\":false,\"text\":\"16.ª Luego la filosofía del _yo_, ó la que quiere explicar el mundo interno y externo, partiendo del _yo_, es imposible, y comienza por prescindir de uno de los hechos fundamentales de la psicología.\"},{\"heading\":false,\"text\":\"17.ª Luego la doctrina de la identidad universal es absurda tambien; pues que da á la materia inteligencia e inteligibilidad inmediata, cuando no puede tener ni uno ni otro.\"},{\"heading\":false,\"text\":\"18.ª Luego el espiritualismo es una verdad que nace así de la filosofía subjetiva como de la objetiva, así de la inteligencia como de la inteligibilidad.\"},{\"heading\":false,\"text\":\"19.ª Luego es necesario salir de nosotros mismos y elevarnos además sobre el universo, para encontrar el orígen de la representacion así subjetiva como objetiva.\"},{\"heading\":false,\"text\":\"20.ª Luego es necesario llegar á una actividad primitiva, infinita, que ponga en comunicacion á las inteligencias entre sí y con el mundo corpóreo.\"},{\"heading\":false,\"text\":\"21.ª Luego la filosofía puramente ideológica y psicológica nos conduce á Dios.\"},{\"heading\":false,\"text\":\"22.ª Luego la filosofía no puede comenzar por un hecho único, orígen de todos los hechos; sino que debe acabar y acaba por este hecho supremo, por la existencia infinita, que es Dios (XII).\"}]},{\"title\":\"CAPÍTULO XIII\",\"blocks\":[{\"heading\":false,\"text\":\"REPRESENTACION DE CAUSALIDAD Y DE IDEALIDAD.\"},{\"heading\":false,\"text\":\"[126.] A mas de la representacion por identidad, hay la que he llamado de causalidad. Un ser puede representarse á sí propio; una causa puede representar á sus efectos. La actividad productiva no se concibe si el principio de la accion productriz, no contiene en algun modo á la cosa producida. Por esto se dice que Dios, causa universal de todo lo que existe y puede existir, contiene en sí á todos los seres reales y posibles de una manera virtual eminente. Si un ser puede representarse á sí propio, puede representar tambien lo que en sí contiene; luego la causalidad, con tal que existan las demás condiciones arriba expresadas, puede ser orígen de representacion.\"},{\"heading\":false,\"text\":\"[127.] Aquí haré notar cuán profundo filósofo se muestra Santo Tomás al explicar el modo con que Dios conoce las criaturas. En la Suma teológica cuestion 14, artículo 5, pregunta si Dios conoce las cosas distintas de sí mismo (alia à se) y responde afirmativamente, no porque considere á la esencia divina como un espejo, sino que apelando á una consideracion mas profunda, busca el orígen de este conocimiento en la causalidad. Hé aquí en pocas palabras extractada su doctrina. Dios se conoce perfectamente á sí mismo; luego conoce todo su poder y por consiguiente todas las cosas á que este poder se extiende. Otra razon ó mas bien ampliacion de la misma. El ser de la primera causa, es su mismo entender: todos los efectos preexisten en Dios, como en su causa, luego han de estar en él, en un modo inteligible, siendo su mismo entender. Dios pues, se ve á sí mismo por su misma esencia; pero las demás cosas las ve, no en sí mismas sino en sí mismo, en cuanto su esencia contiene la semejanza de todo. La misma doctrina se halla en la cuestion 12 artículo 8.º donde pregunta si los que ven la esencia divina ven en Dios todas las cosas.\"},{\"heading\":false,\"text\":\"[128.] La representacion por idealidad es la que no dimana ni de la identidad de la cosa representante con la representada, ni de la relacion de causa con efecto. Nuestras ideas se hallan en este caso, pues ni se identifican con los objetos ni los causan. Nos es imposible saber si á mas de esa fuerza representativa que experimentamos en nuestras ideas, existen substancias finitas capaces de representar cosas distintas de ellas y no causadas por ellas. Está por la afirmativa Leibnitz; pero como se ha visto en su lugar, su sistema de las mónadas debe ser considerado como meramente hipotético. Siendo preferible no decir nada á entretenerse en conjeturas que no podrian conducir á ningun resultado, me contentaré con asentar las proposiciones siguientes.\"},{\"heading\":false,\"text\":\"1.ª Si hay algun ser que represente á otro que no sea su efecto, esta fuerza representativa no la tiene propia, le ha sido dada.\"},{\"heading\":false,\"text\":\"2.ª La comunicacion de las inteligencias no puede explicarse sino apelando á una inteligencia primera que siendo causa de las mismas, pueda darles la fuerza de influir una sobre otra, y por consiguiente de producirse representaciones.\"},{\"heading\":false,\"text\":\"[129.] La causalidad puede ser principio de representacion, pero no es razon suficiente de ella.\"},{\"heading\":false,\"text\":\"En primer lugar, una causa no será representativa de sus efectos, si ella en sí misma no es inteligible. Así, aun cuando atribuyéramos á la materia una actividad propia, no deberíamos concederle la fuerza de representacion de sus efectos, por faltarle la condicion indispensable que es la inteligibilidad inmediata.\"},{\"heading\":false,\"text\":\"[130.] Para que los efectos sean inteligibles en la causa, es necesario que esta tenga completamente el carácter de causa, reuniendo todas las condiciones y determinaciones necesarias para la produccion del efecto. Las causas libres no representan á sus efectos porque estos se hallan relativamente á ellas en la sola esfera de la posibilidad. Puede realizarse la produccion, pero no es necesaria; y así en la causa se verá lo posible mas nó lo real. Dios conoce los futuros contingentes que dependen de la voluntad humana, no precisamente porque conoce la actividad de esta, sino porque ve en sí mismo, sin sucesion de tiempo, no solo todo lo que puede suceder sino lo que ha de suceder, pues que nada puede existir ni en lo presente ni en lo futuro sin su voluntad ó permision. Conoce tambien los futuros contingentes dependientes de su sola voluntad, porque desde toda la eternidad sabe lo que tiene resuelto y sus decretos son inmutables é indefectibles.\"},{\"heading\":false,\"text\":\"[131.] Aun refiriéndonos al órden necesario de la naturaleza, y suponiendo conocida una ó mas causas secundarias, no es posible ver en ellas todos sus efectos con toda seguridad, á no ser que la causa obrase aisladamente ó que junto con ella se conociesen todas las demás. Como la experiencia nos enseña que las partes de la naturaleza están en comunicacion íntima y recíproca, no es dado suponer el indicado aislamiento, y por consiguiente la accion de toda causa secundaria está sujeta á la combinacion de otras que pueden ó impedir su efecto ó modificarle. De aquí la dificultad de establecer leyes generales enteramente seguras en todo lo que concierne á la naturaleza.\"},{\"heading\":false,\"text\":\"[132.] Es de notar que las consideraciones precedentes son una nueva demostracion de la absurdidad de la ciencia trascendental, si se la quiere fundar en un hecho del cual dimanen todos los demás. La representacion intelectual no se explica sustituyendo la emanacion necesaria á la creacion libre. Aun suponiendo que la variedad del universo sea puramente fenomenal, no existiendo en el fondo mas que un ser siempre idéntico, siempre único, siempre absoluto, no puede negarse que las apariencias están sujetas á ciertas leyes y sometidas á condiciones muy varias. O el entendimiento humano puede ver lo absoluto de tal manera que con una intuicion simple descubra todo lo que en él se encierra, todo lo que es y puede ser bajo todas las formas posibles, ó está condenado á seguir el desarrollo de lo incondicional, absoluto y permanente, al través de sus formas condicionales, relativas y variables: lo primero, que es una especie de plagio ridículo del dogma de la vision beatífica, es un absurdo tan palpable tratándose del entendimiento en su estado actual, que no merece ni refutacion ni contestacion; lo secundo sujeta al entendimiento si todas las fatigas de la observacion, destruyendo de un golpe las ilusiones que se le habian hecho concebir prometiéndole la ciencia trascendental.\"},{\"heading\":false,\"text\":\"[133.] Nuestro entendimiento está sujeto en sus actos á una ley de sucesion, ó sea á la idea del tiempo. El mismo hecho domina en la naturaleza; ya sea que así se verifique en la realidad, ya sea que el tiempo deba ser considerado como una condicion subjetiva que nosotros trasladamos á los objetos; sea lo que fuere de esta doctrina de Kant, cuyo valor examinaré en el lugar debido, lo cierto es que la sucesion existe, al menos para nosotros, y que de ella no podemos prescindir. En este supuesto, ningun desarrollo infinito puede sernos conocido sino con el auxilio de un tiempo infinito. Así estamos privados por necesidad metafísica, de conocer no solo el desarrollo futuro de lo absoluto, sino el presente y el pasado. Siendo este desarrollo necesario absolutamente, segun la doctrina á que me refiero, ha debido precedernos una sucesion infinita; por manera que la organizacion actual del universo ha de ser mirada como un punto de una escala sin límites que asi en lo pasado como en lo futuro no tiene otra medida que la eternidad. Cuál sea el estado actual del mundo no lo podemos saber con sola la observacion, sino en una parte muy pequeña, y por tanto nos será preciso sacarlo de la idea de lo absoluto, siguiéndole en su desarrollo infinito. Esto, aun cuando en sí no fuera radicalmente imposible, tiene el inconveniente de que no cabe en el tiempo de vida otorgado á un solo hombre, ni en la suma de los tiempos que han vivido todos los hombres juntos.\"},{\"heading\":false,\"text\":\"[134.] Pero volvamos á la representacion de causalidad. Si bien se observa, la representacion ideal va á refundirse en la causal; porque no pudiendo un espíritu tener idea de un objeto que no ha producido, sino en cuanto se la comunica otro espíritu causa de la cosa representada, se infiere que todas las representaciones puramente ideales proceden directa ó indirectamente, inmediata ó mediatamente, de la causa de los objetos conocidos. Y como por otro lado segun hemos visto ya (127), el primer Ser no conoce las cosas distintas de sí mismo, sino en cuanto es causa de ellas, tenemos que la representacion de idealidad viene á refundirse en la de causalidad, verificándose en parte el principio de un profundo pensador napolitano, Vico, «la inteligencia solo conoce lo que ella hace.»\"},{\"heading\":false,\"text\":\"[135.] De la doctrina expuesta se siguen dos consecuencias que es preciso notar.\"},{\"heading\":false,\"text\":\"1.º Las fuentes primitivas de representacion intelectual son solo dos: identidad y causalidad. La de idealidad es necesariamente derivada de la de causalidad.\"},{\"heading\":false,\"text\":\"2.º En el órden real, el principio de ser es idéntico al principio de conocer. Solo lo que da el ser puede dar el conocimiento; solo lo que da el conocimiento puede dar el ser. La causa primera, en tanto puede dar el conocimiento en cuanto da el ser; representa porque causa.\"},{\"heading\":false,\"text\":\"[136.] La representacion de idealidad, aunque enlazada con la de causalidad, es realmente distinta. Bien que la explicacion de su naturaleza pertenezca al tratado de las ideas, no quiero dejar sin alguna aclaracion un punto tan íntimamente ligado con el problema de la representacion intelectual.\"},{\"heading\":false,\"text\":\"Conciben algunos las ideas como una especie de imágenes ó retratos del objeto: si bien se observa, esto no tiene sentido sino refiriéndose á las representaciones de la imaginacion, es decir, á lo puramente corpóreo; y en cuyo caso, aun exige la suposicion de que el mundo externo sea tal cual nos lo presentan los sentidos, lo que bajo muchos aspectos no es verdad. Para convencerse de cuán ilusoria es la teoría fundada en la semejanza de las cosas sensibles, basta preguntar ¿qué es la imágen de una relacion? ¿cómo se retratan el tiempo, la causalidad, la substancia, el ser? Hay en la percepcion de estas ideas algo mas profundo, algo de un órden enteramente distinto de cuanto se parece á cosas sensibles; la necesidad ha obligado á comparar el entendimiento con un ojo que ve, y á la idea con una imágen presente; pero esto es una comparacion; la realidad es algo mas misterioso, mas secreto, mas íntimo; entre la percepcion y la idea hay una union inefable; el hombre no la explica pero la experimenta.\"},{\"heading\":false,\"text\":\"[137.] La conciencia nos atestigua que hay en nosotros unidad de ser, que el _yo_ es siempre idéntico á sí mismo, y que permanece constante á pesar de la variedad de ideas y de actos que pasan por él como las olas sobre la superficie de un lago. Las ideas son un modo de ser del espíritu; pero ¿qué es este modo? ¿en qué consiste su naturaleza? La produccion y reproduccion de las ideas ¿dimana de una causa distinta que influya perennemente sobre nuestra alma y le produzca inmediatamente esos modos de ser que llamamos representaciones é ideas, ó deberemos admitir que le haya sido dada al espíritu una actividad productriz de estas representaciones, bien que sujeta á la determinacion de causas existentes? Estas son cuestiones que por ahora me contento con indicar (XIII).\"}]},{\"title\":\"CAPÍTULO XIV\",\"blocks\":[{\"heading\":false,\"text\":\"IMPOSIBILIDAD DE HALLAR EL PRIMER PRINCIPIO EN EL ÓRDEN IDEAL.\"},{\"heading\":false,\"text\":\"[138.] Lo que no hemos encontrado en la region de los hechos, tampoco lo hallaremos en la de las ideas; pues no hay ninguna verdad ideal orígen de todas las verdades.\"},{\"heading\":false,\"text\":\"La verdad ideal es aquella que solo expresa relacion necesaria de ideas, prescindiendo de la existencia de los objetos á que se refieren; luego resulta en primer lugar, que las verdades ideales son absolutamente incapaces de producir el conocimiento de la realidad.\"},{\"heading\":false,\"text\":\"Para conducir á algun resultado en el órden de las existencias, toda verdad ideal necesita un hecho al cual se pueda aplicar. Sin esta condicion, por mas fecunda que fuese en el órden de las ideas, seria absolutamente estéril en el de los hechos. Sin la verdad ideal, el hecho queda en su individualidad aislada, incapaz de producir otra cosa que el conocimiento de sí mismo; pero en cambio la verdad ideal separada del hecho, permanece en el mundo lógico, de pura objetividad, sin miedo para descender al terreno de las existencias.\"},{\"heading\":false,\"text\":\"[139.] Hagamos aplicacion de esta doctrina á los principios ideales mas ciertos, mas evidentes, y que por contenerse en las ideas que expresan lo mas general del ser, deben de poseer la fecundidad que estamos buscando, si es que sea dable encontrarla.\"},{\"heading\":false,\"text\":\"«Es imposible que una cosa sea y no sea á un mismo tiempo.» Ente es el famoso principio de contradiccion, que sin duda puede pretender á ser considerado como una de las fuentes de verdad para el entendimiento humano. Las ideas que en él se contienen son las mas sencillas y mas claras que puedan concebirse; en él se afirma la repugnancia del ser al no ser, y del no ser al ser á un mismo tiempo; lo que es evidente en el mas alto grado. Pero ¿qué se adelanta con este principio solo? Presentadle al entendimiento mas penetrante ó al genio mas poderoso, dejadle solo con él, y no resultará mas que una intuicion pura, clarísima, si, pero estéril. Como no se afirma que algo sea, ó que no sea, nada se podrá inferir en pro ni en contra de ninguna existencia; lo que se ofrece al espíritu es una relacion condicional, que si algo existe repugna que no exista á un mismo tiempo y vice-versa; pero si no se pone la condicion de la existencia, ó no existencia, el sí el nó son indiferentes en el órden real, nada se sabe con respecto á ellos por grande que sea la evidencia en el órden ideal.\"},{\"heading\":false,\"text\":\"Para pasar del mundo lógico al mundo de la realidad, bastará un hecho que sirva como de puente; si le ofrecemos al entendimiento, las dos riberas se aproximan, y la ciencia nace. Yo siento, yo pienso, yo existo. Hé aquí hechos de conciencia; combínese uno cualquiera de ellos con el principio de contradiccion, y lo que antes eran intuiciones estériles, se desenvuelven en raciocinios fecundos que se dilatan á un tiempo por el mundo de las ideas y el de la realidad.\"},{\"heading\":false,\"text\":\"[140.] Aun en el órden puramente ideal, el principio de contradiccion es estéril si no se junta con verdades particulares del mismo órden. En la geometría, por ejemplo, se hace uso con mucha frecuencia del raciocinio siguiente. «Tal cantidad es mayor ó menor que otra, ó le es igual; porque de lo contrario resultaría mayor y menor, igual y desigual á un mismo tiempo, lo que es absurdo;» aquí se aplica con fruto el principio de contradiccion, mas nó solo, sino unido con una verdad ideal particular que hace útil la aplicacion dicha. Así, en el raciocinio citado, no se podria hacer uso del principio de contradiccion para probar la igualdad ó la desigualdad, si antes no se hubiese probado ó supuesto que existe, ó no existe una de las dos; lo cual no resulta ni puede resultar del principio de contradiccion que no encierra ninguna idea particular, sino las mas generales que se ofrecen al entendimiento humano.\"},{\"heading\":false,\"text\":\"[141.] Las verdades generales por sí solas, aun en el órden puramente ideal, no conducen á nada, por lo indeterminado de las ideas que contienen; y por el contrario, las verdades particulares por sí solas, tampoco producen ningun resultado, porque se limitan á lo que son, imposibilitando el discurso que no puede dar un paso sin el auxilio de las ideas y proposiciones generales. De la union de unas con otras resulta la luz; con la separacion, no se obtiene mas que, o una intuicion abstracta y vaga, o la contemplacion de una verdad particular que, limitada á pequeña esfera, nada puede enseñar sobre los seres considerados bajo un aspecto científico.\"},{\"heading\":false,\"text\":\"[142.] Veremos al tratar de las ideas, que nuestro entendimiento las tiene de dos clases muy diferentes: unas que suponen el espacio, y no pueden prescindir de él, como son todas las geométricas; otras que no se refieren al espacio, como son todas las no geométricas. Estos dos órdenes de ideas están separados por un abismo que solo se puede salvar procurando la aproximacion con el uso simultáneo de unas y otras. El mismo órden ideal queda incompleto si no se hace la aproximacion; y el órden real del universo se vuelve un caos, ó por mejor decir desaparece, ni no se combinan en ambos órdenes, tanto geométrico como no geométrico, las verdades reales con las ideales. De todas las ideas geométricas imaginables, consideradas en toda su pureza ideal, no resultaría nada para el órden ideal geométrico, ni tampoco para el mundo de las realidades aun las materiales, mucho menos de las inmateriales; y por el contrario, de las ideas no geométricas por sí solas, no se podria sacar ni la idea de una recta. Esta observacion acaba de demostrar que en el órden ideal no hay para nosotros la verdad única, porque si la tomamos en el órden geométrico, nos limitamos á combinaciones que no salen de él; y si en el órden no geométrico, nos falta la idea del espacio, y con ella perdemos hasta la posibilidad de concebir el mundo corpóreo (XIV).\"}]},{\"title\":\"CAPÍTULO XV\",\"blocks\":[{\"heading\":false,\"text\":\"LA CONDICION INDISPENSABLE DE TODO CONOCIMIENTO HUMANO.\"},{\"heading\":false,\"text\":\"MEDIOS DE PERCEPCION DE LA VERDAD.\"},{\"heading\":false,\"text\":\"[143.] No hemos podido encontrar ni en el órden real ni en el ideal, una verdad orígen de todas las demás, para nuestro entendimiento, mientras nos hallamos en esta vida. Queda pues demostrado que la ciencia trascendental propiamente dicha, es para nosotros una quimera. Nuestros conocimientos sin embargo han de tener algun punto de apoyo: éste es el que vamos á buscar ahora.\"},{\"heading\":false,\"text\":\"Para la mejor inteligencia de lo que me propongo examinar, recordaré el verdadero estado de la cuestion. No busco un primer principio tal que ilumine por sí solo todas las verdades, ó que las produzca, sino una verdad que sea condicion indispensable de todo conocimiento; por esto no la llamo orígen, sino punto de apoyo: el edificio no nace del cimiento pero estriba en él. Como un cimiento hemos de considerar el principio buscado, así como en los capítulos anteriores tratábamos de encontrar una semilla: estas dos imágenes, semilla y cimiento, expresan perfectamente mis ideas y deslindan con toda exactitud las dos cuestiones.\"},{\"heading\":false,\"text\":\"[144.] ¿Existe un punto de apoyo para la ciencia, y para todo conocimiento, sea ó nó científico? Si existe, ¿cuál es? ¿hay uno solo, ó son muchos?\"},{\"heading\":false,\"text\":\"Es evidente que el punto de apoyo ha de existir; si se nos pregunta el por qué de un asenso cierto, hemos de llegar al fin á un hecho o á una proposicion de donde no podemos pasar; ya que no es dable admitir el proceso hasta lo infinito. El punto en que nos sea preciso detenernos, es para nosotros el primero, y por consiguiente el de apoyo para la certeza.\"},{\"heading\":false,\"text\":\"[145.] Partiendo de un asenso dado, quizás podemos ser conducidos á principios diferentes, independientes unos de otros, todos igualmente fundamentales para nuestro espíritu; en cuyo caso no habrá un punto solo de apoyo, sino muchos.\"},{\"heading\":false,\"text\":\"No creo posible determinar _á priori_, si en esta parte hay para nuestro entendimiento unidad ó pluralidad. Que la ciencia humana se haya de reducir á un principio solo, es una proposicion que se afirma mas no se prueba. No existiendo en el hombre la fuente de toda verdad como se ha demostrado en los capítulos anteriores, es claro que los principios en que se funde su conocimiento han de ser comunicados. ¿Quién nos asegura que estos no sean muchos y de órdenes diferentes? ¿No cabe pues resolver nada _á priori_ en la cuestion presente; es preciso descender al terreno de la observacion ideológica y psicológica.\"},{\"heading\":false,\"text\":\"[146.] Nuestro espíritu alcanza la verdad, o al menos su apariencia; es decir, que de un modo ú otro tiene estos actos que llamamos percibir y sentir. Que la realidad corresponda ó nó á los actos de nuestra alma, nada importa por ahora; no es esto lo que buscamos; ponemos la cuestion en un terreno en que pueden caber hasta los mas escépticos; ni aun estos niegan la percepcion y la sensacion: si destruyen la realidad, admiten al menos la apariencia.\"},{\"heading\":false,\"text\":\"[147.] Los medios con que percibimos la verdad son de varios órdenes; lo que hace que las verdades mismas percibidas correspondan tambien á órdenes diferentes, paralelos por decirlo así, con los respectivos medios de percepcion.\"},{\"heading\":false,\"text\":\"Conciencia, evidencia, instinto intelectual ó sentido comun, hé aquí los tres medios; verdades de sentido íntimo, verdades necesarias, verdades de sentido comun, hé aquí lo correspondiente á dichos medios. Estas son cosas distintas, diferentes, que en muchos casos no tienen nada que ver entre sí: es preciso deslindarlas con mucho cuidado, si se quieren adquirir ideas exactas y cabales en las cuestiones relativas al primer principio de los conocimientos humanos.\"},{\"heading\":false,\"text\":\"[148] El medio que he llamado de conciencia, es decir, el sentido íntimo de lo que pasa en nosotros, de lo que experimentamos, es independiente de todos los demás. Destrúyase la evidencia, destrúyase el instinto intelectual, la conciencia permanece. Para experimentar y estar seguros de que experimentamos y de lo que experimentamos, no hemos menester sino la experiencia misma. Si se supone en duda el principio de contradiccion, todavía no se hará vacilar la certeza de que sufrimos cuando sufrimos, de que gozamos cuando gozamos, de que pensamos cuando pensamos. La presencia del acto ó de la impresion allá en el fondo de nuestro espíritu, es íntima, inmediata, de una eficacia irresistible para hacer que nos sobrepongamos á toda duda. El sueño y la vigilia, la demencia y la cordura, son indiferentes para el testimonio de la conciencia; el error puede estar en el objeto mas nó en el fenómeno interno. El loco que cree contar numerosas talegas no las cuenta ciertamente, y en esto se engaña; pero tiene en su espíritu la conciencia de que lo hace, y en esto es infalible. El que sueña haber caido en manos de ladrones se engaña en lo tocante al objeto externo; mas nó en lo que pertenece al acto mismo con que lo cree.\"},{\"heading\":false,\"text\":\"La conciencia es independiente de todo testimonio extrínseco á ella; es de una necesidad indeclinable, de una fuerza irresistible para producir certeza; es infalible en lo que concierne á ella sola: si existe no puede menos de dar testimonio de sí misma; si no existe no lo puede dar. En ella la realidad y la apariencia se confunden: no puede ser aparente sin ser real; la apariencia por sí sola, es ya una verdadera conciencia.\"},{\"heading\":false,\"text\":\"[149.] Comprendo en el testimonio de la conciencia todo lo que experimentamos en nuestra alma, todo lo que afecta á lo que se llama el _yo_ humano: ideas, pensamientos de todas clases, actos de voluntad, sentimientos, sensaciones, en una palabra, todo aquello de que podemos decir: lo experimento.\"},{\"heading\":false,\"text\":\"[150.] Es claro que las verdades de conciencia son mas bien hechos que se pueden señalar, que no combinaciones enunciables en una proposicion. No es esto decir que no se puedan enunciar, sino que ellas en sí mismas prescinden de toda forma intelectual, que son simples elementos de que el entendimiento se puede ocupar ordenándolos y comparándolos de varios modos, pero que por sí solos no dan ninguna luz, que ellos por sí mismos nada _representan_, que solo _presentan_ lo que son, son meros hechos, mas allá de los cuales no se puede ir.\"},{\"heading\":false,\"text\":\"[151.] La costumbre de reflexionar sobre la conciencia, y el andar mezcladas las operaciones puramente intelectuales con los hechos de simple experiencia interna, hace que no se conciba fácilmente ese aislamiento en que se encuentra por su naturaleza todo lo que es puramente subjetivo. Se quiere prescindir de la reflexion, pero se reflexiona sobre el esfuerzo mismo que se hace para prescindir de ella: nuestro entendimiento es una luz que se enciende por una parte cuando se la apaga en otra; la insistencia misma en apagarla suele hacerla mas viva y centelleante. De aquí la dificultad de distinguir los dos caractéres de lo puramente subjetivo y puramente objetivo, de deslindar la evidencia de la conciencia, lo conocido de lo experimentado. Sin embargo, la separacion de dos elementos tan diferentes se puede facilitar considerando que los brutos, á su modo, tienen tambien conciencia de lo que experimentan dentro de sí mismos: no suponiéndolos meras máquinas, es preciso otorgarles la conciencia, es decir, la presencia íntima de sus sensaciones: sin esto, ni aun la sensacion se concibe; no tendrá sensacion lo que no siente que siente. El bruto no reflexiona sobre lo que pasa en su interior, lo experimenta, nada mas. Las sensaciones se suceden unas á otras en su alma, sin mas vínculo que la unidad del ser que las experimenta; pero este no las toma por objeto y por consiguiente no las combina ni transforma de ninguna manera, las deja lo que son, simples hechos. De aquí podemos sacar alguna luz para concebir lo que son en nosotros los simples hechos de conciencia, abandonados á sí solos, en todo su aislamiento, sin ninguna mezcla de operaciones puramente intelectuales, y sin estar sujetos á la actividad reflexiva que combinándolos de varias maneras y elevándolos á la region de lo puramente ideal, nos los presenta de tal modo que nos hace olvidar su pureza primitiva.\"},{\"heading\":false,\"text\":\"Es necesario esforzarse en percibir con toda claridad lo que son los hechos de conciencia, lo que es su testimonio; pues sin esto es imposible adelantar un paso en la investigacion del primer principio de los conocimientos humanos. La confusion en este punto hace incurrir en equivocaciones trascendentales. Ocasion tendremos de notarlo en lo sucesivo; y hemos encontrado ya lastimosos ejemplos de semejantes extravíos en los errores de la filosofía del _yo_.\"},{\"heading\":false,\"text\":\"[152.] La evidencia, suele decirse, es una luz intelectual: esta es una metáfora muy oportuna y hasta muy exacta si se quiere; pero que adolece del mismo defecto que todas las metáforas, las cuales, por sí solas, sirven poco para explicar los misterios de la filosofía. Luz intelectual tambien la encontramos en muchos actos de conciencia. En aquella presencia íntima con que una operacion ó una impresion se ofrece al espíritu, tambien hay una especie de luz clara, viva, que hiere por decirlo así el ojo del alma, y no le permite dejar de ver lo que tiene delante. Si pues para definir la evidencia nos contentamos con llamarla luz del entendimiento, la confundimos con la conciencia, ó á lo menos damos ocasion, con un lenguaje ambiguo, á que otros la confundan.\"},{\"heading\":false,\"text\":\"No se crea que me proponga inculpar á los que han empleado la metáfora de la luz, ni que me lisonjee de poder definir la evidencia con toda propiedad: ¿quién expresa con palabras este fenómeno de nuestro entendimiento? Al querer emplear alguna, se ofrece la de luz como la mas adecuada. Porque en verdad, cuando atendemos á la evidencia, para examinar ya su naturaleza, ya sus efectos sobre el espíritu, se nos presenta naturalísimamente bajo la imágen de una luz cuyos resplandores alumbran los objetos para que nuestra alma pueda contemplarlos: pero esto, repito, no es suficiente: y así, aunque no formo el empeño de definirla con exactitud, voy á señalar un carácter que la distingue de todo lo que no es ella.\"},{\"heading\":false,\"text\":\"[153.] La evidencia anda siempre acompañada de la necesidad, y por consiguiente de la universalidad de las verdades que atestigua. No la hay cuando no existen las dos condiciones señaladas. De lo contingente no hay evidencia, sino en cuanto está sometido á un principio de necesidad.\"},{\"heading\":false,\"text\":\"Expliquemos esta doctrina comprando ejemplos tomados respectivamente de la conciencia y de la evidencia.\"},{\"heading\":false,\"text\":\"Que hay en mí un ser que piensa, esto no lo sé por evidencia sino por conciencia. Que lo que piensa existe, esto no lo sé por conciencia sino por evidencia. En ambos casos hay certeza absoluta, irresistible; pero en el primero, versa sobre un hecho particular, contingente; en el segundo sobre una verdad universal y necesaria. Que yo piense es cierto para mí, pero no es preciso que lo sea para los demás; la desaparicion de mi pensamiento no trastorna el mundo de las inteligencias; si mi pensamiento dejase ahora de existir, la verdad en sí misma no sufriría ninguna alteracion; otras inteligencias podrian continuar y continuarian percibiéndola; ni en el órden real ni en el ideal, se echarian de menos el concierto y la armonía.\"},{\"heading\":false,\"text\":\"Me pregunto á mí mismo si pienso; y en el fondo de mi alma leo que sí; me pregunto si este pensamiento es necesario, y á mas de que la experiencia me dice que nó, tampoco encuentro razon ninguna en que fundar la necesidad. Aun suponiendo que mi pensamiento deja de existir, veo que continúo discurriendo con buen órden; así examino lo que hubiera sucedido si yo no existiese, ó lo que podria suceder en adelante, y asiento principios y saco consecuencias, sin quebrantar ninguna de las leyes intelectuales. El mundo ideal y el real se ofrecen á mis ojos como un magnífico espectáculo al cual yo asisto ciertamente, si, pero de donde puedo retirarme sin que la representacion cese, ni se altere nada, ni resulte otra mudanza que la de quedar vacío el imperceptible lugar que estoy ocupando. Muy de otro modo sucede en las verdades objeto de evidencia; no es necesario que yo piense, pero es tan necesario que lo que piensa exista, que todos mis esfuerzos no bastan para prescindir por un momento de esta necesidad. Si supongo lo contrario, si colocándome en el terreno de lo absurdo finjo por un instante que queda cortada la relacion entre el pensar y el ser, se rompe el vínculo que mantiene en órden al universo entero: todo se trastorna, todo se confunde, y lo que se me presenta á la vista no sé si es el caos ó la nada. ¿Qué ha sucedido? Nada mas sino que el entendimiento ha supuesto una cosa contradictoria, afirmando y negando á un mismo tiempo el pensar, porque afirmaba un pensamiento al cual negaba la existencia. Se ha quebrantado una ley universal, absolutamente necesaria; en faltando ella todo se hunde en el caos; la certeza de la existencia del _yo_ afianzada en el testimonio de la conciencia, no basta á impedir la confusion: la inteligencia contradiciéndose, se ha negado á sí propia; de su palabra insensata no ha salido el ser sino la nada, no la luz sino las tinieblas; y esas tinieblas que ella ha soplado sobre todo lo existente y lo posible, vuelven á caer á torrentes sobre ella misma y la envuelven en eterna noche.\"},{\"heading\":false,\"text\":\"[154.] Hé aquí fijados y deslindados los caractéres de la conciencia y de la evidencia. La primera tiene por objeto lo individual y contingente; la segunda lo universal y necesario: solo Dios, fuente de toda verdad, principio universal y necesario de ser y de conocer, tiene identificada la conciencia con la evidencia en sí propio: en aquel ser infinito que todo lo encierra, ve la razon de todas las esencias y de todas las existencias, y no le es dable prescindir de sí mismo, del testimonio de su conciencia, sin anonadarlo todo. ¿Qué quedaria en el mundo, se dice la criatura, si tú desaparecieses? y se responde á si misma: _todo excepto tú_. Si Dios se dirigiese esta pregunta, se respondería á sí propio: _nada_.\"},{\"heading\":false,\"text\":\"[155.] He llamado instinto intelectual á ese impulso que nos lleva á la certeza en muchos casos, sin que medien ni el testimonio de la conciencia, ni el de la evidencia. Si se indica á un hombre un blanco de una línea de diámetro, y luego se le vendan los ojos y despues de haberle hecho dar muchas vueltas á la aventura, se le pone un arco en la mano para que dispare y se asegura que la flecha irá á clavarse precisamente en el pequeñísimo blanco, dirá que esto es imposible y nadie será capaz de persuadirle tamaño dislate. ¿Y porqué? ¿se apoya en el testimonio de la conciencia? nó, porque se trata de objetos externos. ¿Se funda en la evidencia? tampoco, porque esta tiene por objeto las cosas necesarias, y no hay ninguna imposibilidad intrínseca en que la flecha vaya á dar en el punto señalado. ¿En qué estriba pues la profunda conviccion de la negativa? Si suponemos que este hombre nada sabe de las teorías de probabilidades y combinaciones, que ni aun tiene noticia de esta ciencia, ni ha pensado nunca en cosas semejantes, su certeza será igual, sin embargo de que no podrá fundarla en cálculo de ninguna especie; igual la tendrán todos los circunstantes rudos ó cultos, ignorantes ó sabios: sin necesidad de reflexion, instantáneamente, todos dirán ó pensarán: «esto es imposible, esto no se verificará.» ¿En qué fundan, repito, tan fuerte conviccion? Es claro que no naciendo ni de la conciencia, ni de la evidencia inmediata ni mediata, no puede tener otro orígen que esa fuerza interior que llamo instinto intelectual, y que dejaré llamar sentido comun ó lo que se quiera, con tal que se reconozca la existencia del hecho. Don precioso que nos ha otorgado el Criador para hacernos razonables aun antes de raciocinar; y á fin de que dirijamos nuestra conducta de una manera prudente, cuando no tenemos tiempo para examinar las razones de prudencia.\"},{\"heading\":false,\"text\":\"[156.] Ese instinto intelectual abraza muchísimos objetos de órden muy diferente; es, por decirlo asi, la guia y el escudo de la razon; la guia, porque la precede y le indica el camino verdadero, antes de que comience á andar; el escudo, porque la pone á cubierto de sus propias cavilaciones, haciendo enmudecer el sofisma en presencia del sentido comun.\"},{\"heading\":false,\"text\":\"[157.] El testimonio de la autoridad humana, tan necesario al individuo y á la sociedad, arranca nuestro asenso por medio de un instinto intelectual. El hombre cree al hombre, cree á la sociedad, antes de pensar en los motivos de su fe; pocos los examinan, y sin embargo la fe es universal.\"},{\"heading\":false,\"text\":\"No se trata ahora de saber si el instinto intelectual nos engaña algunas veces, en qué casos y por qué; al presente solo quiero consignar su existencia; y con respecto á los errores á que nos conduce, me contentaré con observar que en un ser débil como es el hombre, la regla se dobla muy á menudo; y que así como no es posible encontrar en él lo bueno sin mezcla de lo malo, tampoco es dable hallar la verdad sin mezcla de error.\"},{\"heading\":false,\"text\":\"[158.] Si bien se observa, no objetivamos las sensaciones sino en fuerza de un instinto irresistible. Nada mas cierto, mas evidente á los ojos de la filosofía que la subjetividad de toda sensacion; es decir, que las sensaciones son fenómenos inmanentes, ó que están dentro de nosotros y no salen fuera de nosotros; y sin embargo, nada mas constante que el tránsito que hace el género humano entero de lo subjetivo á lo objetivo, de lo interno á lo externo, del fenómeno á la realidad. ¿En qué se funda este tránsito? Cuando los filósofos mas eminentes han tenido tanta dificultad en encontrar el puente, por decirlo así, que une las dos riberas opuestas, cuando algunos de ellos cansados de investigar han dicho resueltamente que no era posible encontrarle, ¿lo descubrirá el comun de los hombres desde su mas tierna niñez? es evidente que el tránsito que hacen no puede explicarse por motivos de raciocinio, y que es preciso apelar al instinto de la naturaleza. Luego hay un instinto que por sí solo nos asegura de la verdad de una proposicion, á cuya demostracion llega difícilmente la filosofía mas recóndita.\"},{\"heading\":false,\"text\":\"[159.] Aquí observaré lo errado de los métodos que aislan las facultades del hombre, y que para conocer mejor el espíritu, le desfiguran y mutilan. Es uno de los hechos mas constantes y fundamentales de las ciencias ideológicas y psicológicas, la multiplicidad de actos y facultades de nuestra alma, á pesar de su simplicidad atestiguada por la unidad de conciencia. Hay en el hombre como en el universo un conjunto de leyes cuyos efectos se desenvuelven simultáneamente, con una regularidad armoniosa; separarlas equivale muchas veces á ponerlas en contradiccion; porque no siendo dado á ninguna de ellas el producir su efecto aisladamente, sino en combinacion con las demás, cuando se les exige que obren por sí solas, en vez de efectos regulares, producen monstruosidades las mas deformes. Si dejais sola en el mundo la ley de gravitacion no combinándola con ninguna fuerza de proyeccion, todo se precipitará hácia un centro; en vez de esa infinidad de sistemas que hermosean el firmamento, tendréis una mole ruda é indigesta: si quitáis la gravitacion y dejais la fuerza de proyeccion, los cuerpos todos se descompondrán en átomos imperceptibles, dispersándose cual éter levísimo por las regiones de la inmensidad (XV).\"}]},{\"title\":\"CAPÍTULO XVI\",\"blocks\":[{\"heading\":false,\"text\":\"CONFUSION DE IDEAS EN LAS DISPUTAS SOBRE EL PRINCIPIO FUNDAMENTAL.\"},{\"heading\":false,\"text\":\"[160.] En mi concepto hay varios principios que con relacion al entendimiento humano pueden llamarse igualmente fundamentales, ya porque todos sirven de cimiento en el órden comun y en el científico, ya porque no se apoyan en otro; no siendo dable señalar uno que disfrute de esta calidad como privilegio exclusivo. Al buscarse en las escuelas el principio fundamental, suele advertirse que no se trata de encontrar una verdad de la cual dimanen todas las otras; pero sí un axioma tal que su ruina traiga consigo la de todas las verdades, y su firmeza las sostenga, al menos indirectamente; de manera que quien las negare pueda ser reducido por demostracion indirecta ó _ad absurdum_; es decir, que admitido dicho axioma, se podrá conseguir que quien niegue los otros sea convencido de hallarse en oposicion con el que habia reconocido como verdadero.\"},{\"heading\":false,\"text\":\"[161.] Mucho se ha disputado sobre si era este ó aquel principio el merecedor de la preferencia; yo creo que hay aquí cierta confusion de ideas, nacida en buena parte, de no deslindar suficientemente testimonios tan distintos como son el de la conciencia, el de la evidencia y el del sentido comun.\"},{\"heading\":false,\"text\":\"El famoso principio de Descartes «yo pienso, luego soy;» el de contradiccion, «es imposible que una cosa sea y no sea á un mismo tiempo;» el otro que llaman de los cartesianos, «lo que está contenido en la idea clara y distinta de una cosa, se puede afirmar de ella con toda certeza;» son los tres principios que han dividido las escuelas. En favor de todos ellos se alegaban razones poderosísimas, y hasta concluyentes contra el adversario, atendido el terreno en que estaba colocada la cuestion.\"},{\"heading\":false,\"text\":\"Si no estais seguros de que pensais, argüiria un partidario de Descartes, no podeis estarlo ni aun del principio de contradiccion, ni tampoco de la legitimidad del criterio de la evidencia; para saber todo esto, es necesario pensar; quien afirma ó niega, piensa; sin suponer el pensamiento, no son posibles ni la afirmacion ni la negacion. Pero admitamos el pensamiento; tenemos ya un punto de apoyo, y de tal naturaleza, que lo encontramos en nosotros mismos, atestiguado por el sentido íntimo, imponiéndonos con una eficacia irresistible la certeza de su existencia. Establecido el fundamento, veamos cómo se puede levantar el edificio: para esto, no es necesario salir del pensamiento propio; allí está el punto luminoso para guiarnos en el camino de la verdad; sigamos sus resplandores, y fijado un punto inmóvil hagamos salir de él el hilo misterioso que nos conduzca en el laberinto de la ciencia. Así, nuestro principio es el primero, es la basa de todos los demás, posee una fuerza propia para sostenerse y la tiene sobrante para comunicar firmeza á los otros.\"},{\"heading\":false,\"text\":\"Este lenguaje es razonable ciertamente; pero hay la desgracia de que la conviccion que pudiera producir, está neutralizada con otro lenguaje no menos razonable, en sentido directamente opuesto. He aquí cómo pudiera contestar un sostenedor del principio de contradiccion. Si nos dais por supuesto que es imposible que una cosa sea y no sea á un mismo tiempo, será posible que á un mismo tiempo penséis y no penséis; vuestra afirmacion pues «yo pienso» no significa nada; porque junto con ella se puede verificar la opuesta «yo no pienso». En tal caso, la ilacion de la existencia queda destruida; porque aun admitiendo la legitimidad de la consecuencia «yo pienso, luego existo», como por otra parte sabríamos que es posible esta otra premisa, «yo no pienso,» la deduccion no tendria lugar. Sin el principio de contradiccion tampoco vale nada el otro: «lo que está contenido en la idea clara y distinta de una cosa se puede afirmar de ella con toda certeza»: porque si á un mismo tiempo es posible el ser y el no ser, una idea podrá ser clara y oscura, distinta y contusa; un predicado podrá estar contenido en un sujeto y no contenido; podrá haber certeza é incertidumbre; afirmacion y negacion; luego esta regla no sirve para nada.\"},{\"heading\":false,\"text\":\"Y tiene mucha razon el que discurre de este modo; pero lo curioso es, que el tercer contrincante las alegará igualmente fuertes contra sus dos adversarios. ¿Cómo se sabe, podrá preguntar, que el principio de contradiccion es verdadero? claro es que no lo sabemos sino porque en la idea del ser vemos la imposibilidad del no ser á un mismo tiempo y vice-versa; luego no estais seguros del principio de contradiccion sino aplicando mi principio: «lo que está contenido en la idea clara y distinta de una cosa, se puede afirmar de ella con toda certeza.» Si nada puede sostenerse en cayendo al principio de contradiccion, y este se funda en el mio, el mio es el cimiento de todo.\"},{\"heading\":false,\"text\":\"[162.] Los tres tienen razon y no la tiene ninguno. La tienen los tres, en cuanto afirman que negado el respectivo principio se arruinan los demás; no la tiene ninguno, en cuanto pretenden que negados los demás no se arruina el propio. ¿De dónde pues nace la disputa? de la confusion de ideas, de que se comparan principios de órdenes muy diferentes, todos de seguro muy verdaderos, pero que no pueden parangonarse por la misma razon que no se compara lo blanco con lo caliente, disputando si una cosa tiene mas grados de calor que de blancura. Para la comparacion, se necesita cierta oposicion en los extremos; pero estos deben tener algo comun; si son enteramente disparatados, la comparacion es imposible.\"},{\"heading\":false,\"text\":\"El principio de Descartes es la anunciacion de un simple hecho de conciencia; el de contradiccion es una verdad conocida por evidencia; y el otro es la afirmacion de la legitimidad del criterio de la evidencia misma; es una verdad de reflexion que expresa el impulso intelectual por el que somos llevados á creer verdadero lo que conocemos con evidencia.\"},{\"heading\":false,\"text\":\"La importancia de la cuestion exige que examinemos por separado los tres principios; así lo haré en los capítulos siguientes (XVI).\"}]},{\"title\":\"CAPÍTULO XVII\",\"blocks\":[{\"heading\":false,\"text\":\"LA EXISTENCIA Y EL PENSAMIENTO. PRINCIPIO DE DESCARTES.\"},{\"heading\":false,\"text\":\"[163.] ¿Estoy seguro de que existo? sí. ¿Puedo probarlo? nó. La prueba supone un raciocinio; no hay raciocinio sólido sin principio firme en que estribe; y no hay principio firme, si no está supuesta la existencia del ser que raciocina.\"},{\"heading\":false,\"text\":\"En efecto: si quien discurre no está seguro de su existencia, no puede estarlo ni de la existencia de su propio discurso; pues no habrá discurso si no hay quien discurre. Luego sin este supuesto no hay principios sobre que fundar, no hay nada; no hay mas que ilusion, y bien mirado, ni ilusion siquiera, pues no hay ilusion si no hay iluso.\"},{\"heading\":false,\"text\":\"Nuestra existencia no puede ser demostrada: tenemos de ella una conciencia tan clara, tan viva, que no nos deja la menor incertidumbre; pero probarla con el raciocinio es imposible.\"},{\"heading\":false,\"text\":\"[164.] Es una preocupacion, un error de fatales consecuencias, el creer que podemos probarlo todo con el uso de la razon; antes que el uso de la razon están los principios en que ella se funda; y antes que uno y otro, está la existencia de la razon misma, y del ser que raciocina.\"},{\"heading\":false,\"text\":\"Lejos de que todo sea demostrable, se puede demostrar que hay cosas indemostrables. La demostracion es una argumentacion en la cual se infiere de proposiciones evidentes una proposicion evidentemente enlazada con ellas. Si las premisas son evidentes por sí mismas, no consentirán demostracion; si suponemos que ellas á su vez sean demostrables, tendremos la misma dificultad con respecto á las otras en que se funde la nueva demostracion; luego, ó es preciso detenerse en un punto indemostrable, ó proceder hasta lo infinito, lo que equivaldria á no acabar jamás la demostracion.\"},{\"heading\":false,\"text\":\"[165.] Y es de observar que la indemostrabilidad, por decirlo así, no es propia únicamente de ciertas premisas: se la halla en algun modo en todo raciocinio, por su misma naturaleza, prescindiendo de las proposiciones de que se compone. Sabemos que las premisas A y B son ciertas; de ellas inferiremos la proposicion C. ¿Con qué derecho? Porque vemos que C se enlaza con las A y B. ¿Y cómo sabemos esto? Si es con evidencia inmediata, por intuicion: hé aquí otra cosa indemostrable: el enlace de la conclusion con las premisas. Si es por raciocinio, fundándonos en los principios del arte de raciocinar, entonces hay dos consideraciones, ambas conducentes á demostrar la indemostrabilidad. 1.ª Si los principios del arte son indemostrables, tenemos ya una cosa indemostrable; si lo son, al fin hemos de valernos de otros que les sirvan de basa, y ó pararnos en alguno que no consienta demostracion, ó proceder hasta lo infinito. 2.ª ¿Cómo sabemos que los principios del raciocinio se aplican á este caso? ¿Será por otro raciocinio? resultan los mismos inconvenientes que en el caso anterior. ¿Será porque lo vemos así? ¿porque es evidente con evidencia inmediata? hénos aquí en otro punto indemostrable.\"},{\"heading\":false,\"text\":\"Estas reflexiones no dejan ninguna duda de que el pedir la prueba de todo es pedir lo imposible.\"},{\"heading\":false,\"text\":\"[166.] El ser que no piensa, no tiene conciencia de sí mismo: la piedra existe, mas ella no lo sabe, y en un caso semejante se encuentra el hombre mismo cuando todas sus facultades intelectuales y sensitivas se hallan en completa inaccion. La diferencia de estos dos estados se concibe muy bien recordando lo que acontece al pasar de la vigilia á un sueño profundo, y al volver de este á la vigilia.\"},{\"heading\":false,\"text\":\"El primer punto de partida para dar un paso en nuestros conocimientos, es esta presencia íntima de nuestros actos interiores, prescindiendo de las cuestiones que suscitarse puedan sobre la naturaleza de ellos. Si todo existiese como ahora, y existiesen infinitos mundos diferentes del que tenemos á la vista, nada existiria para nosotros, si nos faltasen esos actos interiores de que estamos hablando. Seríamos como el cuerpo insensible colocado en la inmensidad del espacio, que se halla lo mismo ahora que si todo desapareciese alrededor de él, y no percibiria mudanza alguna aun cuando él propio se sumiese de nuevo en el abismo de la nada. Al contrario, si suponemos que todo se aniquila excepto este ser que dentro de nosotros siente, piensa y quiere; todavía queda un punto donde hacer estribar el edificio de los humanos conocimientos: este ser, solo en la inmensidad, se dará cuenta á sí mismo de sus propios actos, y segun el alcance de sus facultades intelectuales, podrá arrojarse á innumerables combinaciones que tengan por objeto lo posible, ya que nó la realidad.\"},{\"heading\":false,\"text\":\"[167.] Se ha combatido mucho el famoso principio de Descartes: _«yo_ pienso, luego _existo_;» el ataque es justo y concluyente, si en efecto el filósofo hubiese entendido su principio en el sentido que se le acostumbra dar en las escuelas. Si Descartes le hubiese presentado como un verdadero raciocinio, como un entimema en que asentado el antecedente dedujera la consecuencia, claro es que el argumento claudicaba por su basa, estaba en el aire. Porque, cuando él dijera: «voy á probar mi existencia con este entimema: yo pienso, luego soy», se le podia objetar lo siguiente: vuestro entimema se reduce á un silogismo en esta forma: «todo lo que piensa existe; es así que yo pienso, luego existo.» Este silogismo, en el supuesto de una duda universal, en que no se dé por supuesta ni aun la misma existencia, es inadmisible en sus proposiciones y en la trabazon de ellas. En primer lugar: ¿cómo sabeis que todo lo que piensa existe?--Porque nada puede pensar sin existir.--Y esto ¿cómo se sabe?--Porque lo que no existe no obra.--Y esto ¿cómo se sabe? Suponiendo que de todo se duda, que nada se sabe, no se pueden saber estos principios; de otra suerte faltamos á la suposicion de la duda universal, y por consiguiente nos salimos de la cuestion. Si alguno de estos principios se ha de admitir sin prueba, tanto valia admitir desde luego la existencia propia, y ahorrarse el trabajo de probarla con un entimema.\"},{\"heading\":false,\"text\":\"En segundo lugar: ¿cómo sabéis que pensais? Se os puede hacer el siguiente argumento, retorciendo el vuestro, como dicen los dialécticos: nada puede pensar sin existir, vuestra existencia es dudosa, tratais de probarla, luego no estais seguros de pensar.\"},{\"heading\":false,\"text\":\"[168.] Queda pues en claro que el principio de Descartes es insostenible tomado como un verdadero raciocinio; y siendo tan fácil de alcanzar su flaqueza, parece imposible que no la viese un entendimiento tan claro y penetrante. Es probable pues que Descartes entendió su principio en un sentido muy diferente, y voy á exponer en pocas palabras el que en mi juicio debió de darle el ilustre filósofo.\"},{\"heading\":false,\"text\":\"Suponiéndose por un momento en una duda universal, sin aceptar como cierto nada de cuanto sabia, se concentraba dentro de sí mismo, y buscaba en el fondo de su alma un punto de apoyo donde hacer estribar el edificio de los conocimientos humanos. Claro es que, aun haciendo abstraccion de todo cuanto nos rodea, no podemos prescindir de nosotros mismos, de nuestro espíritu que se presenta á sus propios ojos con tanta mayor lucidez, cuanto es mayor la abstraccion en que nos constituimos con respecto á los objetos externos. Ahora bien, en esa concentracion, en ese acto de ensimismarse, retrayéndose el hombre de todo por temor de errar, e interrogándose á sí mismo, si hay algo cierto, si hay algo que pueda servir de apoyo, si hay un punto de partida en la carrera de los conocimientos, lo primero que se ofrece es la conciencia del pensamiento, la presencia misma de los actos de nuestra alma, de eso que se llama pensar. Hé aquí si no me engaño la mente de Descartes; «yo quiero dudar de todo; me retraigo de afirmar como de negar nada; me aislo de cuanto me rodea, porque ignoro si esto es algo mas que una ilusion. Pero en este mismo aislamiento me encuentro con el sentimiento íntimo de mis actos interiores, con la presencia de mi espíritu: yo pienso, luego soy: yo pienso, así lo experimento de una manera que no me consiente duda, ni incertidumbre; luego soy, es decir, ese sentimiento de mi pensamiento me hace sabedor de mi existencia.»\"},{\"heading\":false,\"text\":\"[169.] Así se explica cómo Descartes no presentaba su principio cual un mero entimema, cual un raciocinio comun; sino como la consignacion de un hecho que se le ofrecia el primero en el órden de los hechos; y cuando del pensamiento inferia la existencia, no era con una deduccion propiamente dicha, sino como un hecho comprendido en otro, expresado por otro, ó mejor diremos, _identificado_ con él.\"},{\"heading\":false,\"text\":\"He dicho _identificado_, porque en realidad es así en concepto de Descartes; y esto acaba de confirmar lo que he asentado anteriormente, que el filósofo no presentaba un raciocinio, sino que consignaba un hecho. Sabido es que, segun él, la esencia del espíritu es el mismo pensamiento, de suerte que así como otras escuelas filosóficas distinguen entre la substancia y su acto, considerando al espíritu en la primera clase y al pensamiento en la segunda, Descartes sostenia que no habia distincion alguna entre el espíritu y el pensamiento, que era una misma cosa: que el pensamiento constituia la esencia del alma. «Aunque un atributo, dice, sea suficiente para hacernos conocer la substancia, hay sin embargo en cada una de ellas, uno que constituye su naturaleza y esencia, y del cual dependen todos los demás. La extension en longitud, latitud y profundidad, constituye la esencia de la substancia corpórea; _y el pensamiento constituye la naturaleza de la substancia que piensa_» (Descartes, Principios de la filosofía, 1ª parte). De esto se infiere que Descartes al asentar el principio «yo pienso, luego existo;» no hacía mas que consignar un hecho atestiguado por el sentido íntimo; y tan simple le consideraba, tan único por decirlo así, que en el desarrollo de su sistema, identificó el pensamiento con el alma, y la esencia de esta con su misma existencia. Sintió el pensamiento, y dijo: «este pensamiento es el alma; soy yo.» No trato de apreciar ahora el valor de esta doctrina, y sí tan solo de explicar en qué consiste (XVII).\"}]},{\"title\":\"CAPÍTULO XVIII\",\"blocks\":[{\"heading\":false,\"text\":\"MAS SOBRE EL PRINCIPIO DE DESCARTES. SU MÉTODO.\"},{\"heading\":false,\"text\":\"[170.] Descartes al anunciar y explicar su principio, no siempre se expresó con la debida exactitud, lo cual dió motivo á que se interpretasen mal sus palabras. Al paso que señalaba la conciencia del propio pensamiento y de la existencia, como la basa sobre la cual debian estribar todos los conocimientos, empleaba términos de los cuales se podia inferir que no solo queria consignar un hecho, sino que intentaba presentar un verdadero raciocinio. Sin embargo, leyendo con atencion sus palabras, y cotejándolas unas con otras, se ve que no era esta su idea; aunque tal vez no habria inconveniente en decir que no se daba exacta cuenta á sí propio de la diferencia que acabo de indicar, entre un raciocinio y la simple consignacion de un hecho; y que al concentrarse en sí mismo, no tuvo un conocimiento _reflejo_ bastante claro del modo con que se apoyaba en su principio fundamental.\"},{\"heading\":false,\"text\":\"Para convencernos de esto, examinemos sus mismas palabras. «Mientras desechamos de esta manera todo aquello de que podemos dudar, y que hasta _fingimos_ que es falso, suponemos fácilmente que no hay Dios, ni cielo, ni tierra, y que ni aun tenemos cuerpo, pero no _alcanzamos á suponer que no existimos_, mientras dudamos de la verdad de todas estas cosas; porque tenemos tanta repugnancia á concebir que lo que piensa no existe verdaderamente al mismo tiempo que piensa; que no obstante las suposiciones mas extravagantes, no podemos dejar de creer que esta conclusion «yo pienso, luego soy» no sea verdadera, y por consiguiente la primera y la mas cierta que se presenta al que conduce sus pensamientos con órden.» (Descartes, Principios de la filosofía, P. 1. § 6 y 7.).\"},{\"heading\":false,\"text\":\"En este pasaje nos encontramos con un verdadero silogismo: «Lo que piensa existe; yo pienso, luego existo.» «Tenemos, dice Descartes, tanta repugnancia á concebir, que lo que piensa no existe mientras piensa,» lo que equivale á decir: «Lo que piensa existe;» esto en términos escolásticos, se llama establecer la mayor; luego continúa que «no obstante las suposiciones mas extravagantes, no podemos dejar de creer que esta conclusion «yo pienso, luego soy» sea verdadera;» lo que equivale á poner la menor y la consecuencia del silogismo. Se conoce que Descartes estaba algo preocupado con la idea de querer probar, al mismo tiempo que trataba de consignar. Este era el prurito general de su época; y aun los mas ardientes reformadores se preservan con mucha dificultad de la atmósfera que los rodea. En todo el curso de sus meditaciones se encuentra este mismo espíritu, bien que enlazado admirablemente con el de observacion.\"},{\"heading\":false,\"text\":\"Pero al través de esas explicaciones oscuras ó ambiguas, ¿qué es lo que se descubre? ¿cuál es el pensamiento que se halla en el fondo del sistema de _Descartes_, prescindiendo de sí él se daba ó nó á sí mismo exacta cuenta de lo que experimentaba? Hélo aquí. «Yo por un esfuerzo de mi espíritu, puedo dudar de la verdad de todo; pero este esfuerzo tiene un límite en mí mismo. Cuando la atencion se convierte sobre mí, sobre la conciencia de mis actos interiores, sobre mi existencia, la duda se detiene, no puede llegar á tal punto, encuentra una _tal repugnancia_, que las suposiciones mas extravagantes no alcanzan á vencer.» Esto es lo que indican sus mismas palabras, mas al consignar este hecho se eleva á una proposicion general, muy verdadera sin duda, saca una consecuencia, muy legítima tambien; pero que para nada eran necesarias en el caso presente, y que ó explicaban mal su misma opinion ó la hacian vacilar.\"},{\"heading\":false,\"text\":\"[171.] Si bien se observa, no hacia mas Descartes en este punto, que lo que hacen todos los filósofos; y por mas extraño que pueda parecer, no estaba en desacuerdo con los gefes de la escuela metafísica diametralmenle opuesta: la de Locke y Condillac. En efecto: que el hombre al querer examinar el orígen de sus conocimientos, y los principios en que estriba su certeza, se encuentra con el hecho de la conciencia de sus actos internos, que esta conciencia produce una certeza firmísima, y que nada podemos concebir mas cierto para nosotros que ella, es un hecho en que están de acuerdo todos los ideólogos, y que todos asientan, bien que con diferentes palabras. Cuanto mas se medita sobre estas materias, mas se descubre en ellas la realizacion de un principio confirmado por la razon y la experiencia, de que muchas verdades no son nuevas, sino presentadas de una manera nueva; que muchos sistemas no son nuevos, sino formulados de una manera nueva.\"},{\"heading\":false,\"text\":\"[172.] La misma duda universal de Descartes, cuerdamente entendida, es practicada por todo filósofo; con lo cual se ve que las bases de su sistema, combatidas por muchos, son en el fondo adoptadas por todos. ¿En qué consiste el método de Descartes? todo se reduce á dos pasos: 1.º Quiero dudar de todo. 2.° Cuando quiero dudar de mí mismo no puedo.\"},{\"heading\":false,\"text\":\"Examinemos estos dos pasos, y veremos que con Descartes los da todo filósofo.\"},{\"heading\":false,\"text\":\"¿Por qué Descartes quiere dudar de todo? Porque se propone examinar el orígen y la certeza de sus conocimientos; quiere llamar á exámen todo su saber, y por lo mismo no puede empezar suponiendo nada verdadero. Si supone algo, ya no examinará el orígen y los motivos de la certeza de todo; pues exceptúa aquello que supone verdadero. Le es preciso no suponer, como tal, nada; antes por el contrario suponer que no sabe nada de nada; sin esto no puede decir que examina los fundamentos de todo. Ò no hay tal cuestion filosófica, que sin embargo se la encuentra en todos los libros de filosofía, ó es necesario emplear el método de Descartes.\"},{\"heading\":false,\"text\":\"¿Pero en qué consiste esta duda? Racionalmente hablando ¿puede ser una duda real y verdadera? Nó: esto es imposible, absolutamente imposible. El hombre, por ser filósofo, no alcanza á destruir su naturaleza: y la naturaleza se opone invenciblemente á esta duda, tomada en el sentido riguroso.\"},{\"heading\":false,\"text\":\"[173.] ¿Qué es pues esta duda? Nada mas que una _suposicion_, una _ficcion_, suposicion y ficcion que hacemos á cada paso en todas las ciencias, y que en realidad no es mas que la _no atencion_ á un convencimiento que abrigamos. Esta duda se la emplea para descubrir la primera verdad en que estriba nuestro entendimiento; á cuyo fin basta que la duda sea ficticia; no hay ninguna necesidad de que sea positiva; porque es evidente, que lo mismo se logra dudando efectivamente de todo, no admitiendo absolutamente nada, que diciendo: «si supongo que no tengo por cierto nada, que no sé nada, que no admito nada.» Un ejemplo aclarará esta explicacion hasta la última evidencia. Quien conozca los rudimentos de geometría sabrá que en un triángulo al mayor lado se opone el mayor ángulo, y está absolutamente cierto de la verdad del teorema: pero si se propone dar á otro la demostracion, ó repetírsela á sí propio, prescinde de dicha certeza, procede como si no la tuviera, para manifestar que se la puede fundar en algo.\"},{\"heading\":false,\"text\":\"En todos los estudios ejecutamos á cada paso esto mismo. Son vulgares las expresiones: «esto es así, es evidente; pero _supongamos_ que no lo sea; ¿qué resultará?» «Esta demostracion es concluyente, pero prescindamos de ella, supongamos que no la tenemos, ¿cómo podriamos demostrar lo que deseamos?» Los argumentos _ad absurdum_ tan en uso en todas las ciencias, y muy particularmente en las matemáticas, estriban no solo en prescindir de lo que conocemos, sino en suponer una cosa directamente contraria á lo que conocemos. «Si la línea A, dice á cada paso el geómetra, no es igual á la B, será mayor ó menor; supongamos que es mayor: etc. etc.» Por manera que para la investigacion de la verdad prescindimos frecuentemente de lo que sabemos, y hasta suponemos lo contrario de lo que sabemos. Aplíquese este sistema á la investigacion del principio fundamental de nuestros conocimientos y resultará la duda universal de Descartes, en el único sentido que puede ser admisible en el tribunal de la razon, y posible á la humana naturaleza.\"},{\"heading\":false,\"text\":\"Es probable que el ilustre filósofo la entendia en el mismo sentido, si bien es menester confesar que sus palabras son ambiguas. No se concibe qué objeto podia proponerse en entenderlas de diferente modo, supuesto que no trataba de otra cosa que de allanar el camino á la investigacion de la verdad. Con su manera de expresarse dió lugar á disputas, que con alguna mayor claridad se habrian evitado.\"},{\"heading\":false,\"text\":\"Así como Descartes no se explicaba con la claridad suficiente, sus adversarios no le estrechaban quizás con toda la precision y nervio que podian. En mi concepto, para resolver la cuestion bastaba dirigirle esta pregunta: «¿Entendeis que al comenzar las investigaciones filosóficas, haya de haber un momento en que _real_ y _efectivamente_ dudemos de todo; ó juzgais bastante el _prescindir_ de la certeza, suponiendo que no la tenemos, como se hace con frecuencia en todos los estudios?»\"},{\"heading\":false,\"text\":\"[174.] Descartes se encontró en el caso de todos los reformadores. Están dominados de una idea; y la expresan tan fuertemente, que al parecer no consienten otra á su lado. Todo en su lenguaje es absoluto, exclusivo. Preven la lucha que habrán de sostener, quizás la experimentan ya; y así concentran toda su fuerza en la idea cuyo triunfo se proponen, y llegan á perder de vista todo lo que no es ella. No se puede inferir que el reformador no tenga otras que modifiquen notablemente la principal; mas para hacer frente á sus adversarios que le dicen: «esto es absolutamente falso,» él dice: «esto es verdadero absolutamente.» La historia y la experiencia nos presentan innumerables ejemplos de estas exageraciones.\"},{\"heading\":false,\"text\":\"La idea dominante de Descartes era arruinar la filosofía que á la sazon reinaba en las escuelas; y daba el impulso tan fuerte que hacia temblar el mundo. Véase cómo expresaba su desden para con muchos que se apellidan filósofos. «La experiencia enseña, que los que hacen profesion de filósofos, son frecuentemente menos sabios y razonables que otros que no se han aplicado nunca á este estudio.» (Prefacio de los Principios de filosofía).\"},{\"heading\":false,\"text\":\"[175.] La segunda parte del método de Descartes, consiste en tomar el pensamiento propio por punto de partida, estableciendo que al esforzarse el hombre por dudar de todo, encuentra un límite en la conciencia de su pensamiento, de su existencia. Es evidente, que este es el fenómeno que naturalmente resta inmóvil en la mente del observador, despues de haber procurado dudar de todo. Al menos no podrá dudar de que duda; y por consiguiente de su pensamiento; siendo de notar que este es un argumento que se ha hecho siempre á los escépticos, lo que equivalia á emplear el método de Descartes, esto es, á consignar como un fenómeno innegable una certeza superior á todas las extravagancias: la conciencia de sí mismo.\"},{\"heading\":false,\"text\":\"Cuando Descartes decia «yo pienso» entendia por esta palabra todo acto interno, todo fenómeno presente al alma inmediatamente; no hablaba del pensamiento tomado en un sentido puramente intelectual, sino que comprendia todo aquello de que tenemos conciencia inmediata. «Por la palabra _pensar_, dice, entiendo todo aquello que se hace en nosotros, de tal suerte, que lo percibimos inmediatamente por nosotros mismos; así es que aquí el pensar no significa tan solo entender, querer, imaginar, sino tambien sentir. Porque si digo que veo ó que ando, y de ahí infiero que existo, si entiendo hablar de la accion que se hace con mis ojos ó mis piernas, esta conclusion no es tan infalible, que no ofrezca algun motivo de duda, ya que puede suceder que yo crea ver ó andar sin que abra los ojos, ni me mueva de mi sitio; pues que esto me acontece cuando duermo, y quizás podria acontecer lo mismo si yo no tuviese cuerpo; pero si entiendo hablar únicamente de la accion de mi pensamiento ó del sentimiento, es decir, del conocimiento que hay en mí, por el cual me parece que veo ó ando, esta conclusion es verdadera tan absolutamente que no me es posible dudar de ella, á causa de que se refiere al alma, única que tiene la facultad de sentir ó bien de pensar, de cualquier modo que esto sea.»(Principios de filosofía, 1.ª parte, § 9).\"},{\"heading\":false,\"text\":\"[176.] Este pasaje manifiesta bien claro las ideas de Descartes; lo arruinaba todo con la duda, pero habia una cosa que resistía á todos los esfuerzos: la conciencia de sí mismo. Y esta conciencia la tomaba él como punto de apoyo, sobre el cual y con toda certeza, pudiera levantar de nuevo el edificio de las ciencias, Locke y Condillac no han hecho otra cosa: han seguido un camino muy diferente del de Descartes: pero el punto de partida ha sido el mismo. Oigamos á Locke. «En primer lugar examinaré cuál es el orígen de las ideas, nociones, ó como se las quiera llamar, que el hombre percibe en su alma, y que su _propio sentimiento_ le hace descubrir en ella.» (Ensayo sobre el entendimiento humano. Prólogo.) «Pues que el espíritu no tiene otro objeto de sus pensamientos y raciocinios que sus propias ideas, las cuales son la única cosa que el contempla ó que puede contemplar, es evidente que nuestro conocimiento se funda _todo entero_ sobre nuestras ideas.» (Ibid. lib. 4, cap. 1). «Sea que nos remontemos hasta los cielos, por hablar metafóricamente, dice Condillac, sea que descendamos á los abismos, no salimos de nosotros, y jamás percibimos otra cosa que nuestro propio pensamiento.» (Ensayo sobre el orígen de los conocimientos humanos. Cap. 1).\"},{\"heading\":false,\"text\":\"[177.] Todos los trabajos ideológicos comienzan pues por la consignacion del hecho de la conciencia de nuestras ideas; y no puede ser de otro modo con respecto á su certeza. El hombre al trastornarlo todo, al arruinarlo todo, al anonadarlo todo, se encuentra consigo mismo, que es quien trastorna, arruina y anonada. Cuando haya llegado á dudar de la existencia de Dios, del mundo, de sus semejantes, de su cuerpo, en medio de aquella inmensa soledad se encuentra todavía á sí mismo. El esfuerzo por anonadarse á sus propios ojos, solo sirve para hacerle mas visible: es una sombra que no muere con ningun golpe, y que por cada herida que se le abre, despide nuevos torrentes de luz. Si duda que siente, siente al menos que duda; si duda de esta duda, siente que duda de la misma duda; por manera que en dudando de los actos directos entra en una serie interminable de actos reflejos que se encadenan por necesidad unos con otros, y se desenvuelven á la vista interior como los pliegues de un lienzo sin fin (XVIII).\"}]},{\"title\":\"CAPÍTULO XIX\",\"blocks\":[{\"heading\":false,\"text\":\"LO QUE VALE EL PRINCIPIO: YO PIENSO.\"},{\"heading\":false,\"text\":\"SU ANÁLISIS.\"},{\"heading\":false,\"text\":\"[178.] El principio de Descartes considerado como un entimema, ya hemos visto que no puede aspirar al título de fundamental. En todo raciocinio hay premisas y consecuencia, y para que sea concluyente son necesarias la verdad de las primeras y la legitimidad de la segunda. Decir que un raciocinio puede ser principio fundamental, es una contradiccion manifiesta.\"},{\"heading\":false,\"text\":\"Pero si tomamos el principio de Descartes en el sentido explicado anteriormente, esto es, nó como un raciocinio sino como la consignacion de un hecho, la contradiccion cesa; y es cuestion digna de examinarse la de si merece ó nó el título de principio fundamental y de qué manera. En los capítulos anteriores se ha esclarecido ya en parte esta materia, pero nó hasta tal punto que se la pueda dar por suficientemente dilucidada: mas bien se han presentado reflexiones preliminares para aclarar el estado de la cuestion que no se la ha resuelto cumplidamente.\"},{\"heading\":false,\"text\":\"[179.] La proposicion «yo pienso» no expresa, como se ha notado ya, el solo pensamiento propiamente dicho; abraza los actos de la voluntad, los sentimientos, las sensaciones, los actos é impresiones de todas clases que se realizan en nuestro interior, comprende todos los fenómenos que presentes á nuestro espíritu con presencia inmediata, nos son atestiguados por el sentido íntimo ó por la conciencia.\"},{\"heading\":false,\"text\":\"Nada que distinga entre las varias clases de actos ó impresiones puede servirnos de principio fundamental; la distincion supone el análisis, y el análisis no existe sin reflexion. No se reflexiona sin reglas y sin objeto conocidos ya: por consiguiente admitir clasificaciones en el primer principio, es despojarle de su carácter, es contradecirse.\"},{\"heading\":false,\"text\":\"[180.] Conviene no confundir lo expresado por la proposicion «yo pienso» con la proposicion misma; el fondo y la forma son aquí cosas muy diferentes; pudiendo la naturaleza de esta hacer concebir ideas equivocadas sobre aquel. El fondo es un hecho simplicísimo; la forma es una combinacion lógica que encierra elementos muy heterogéneos. Esto necesita explicacion.\"},{\"heading\":false,\"text\":\"El hecho de conciencia considerado en sí mismo, prescinde de relaciones, no es nada mas que el mismo, no conduce á nada mas que á sí mismo, es la presencia del acto ó de la impresion, ó mas bien es el acto mismo, la impresion misma, que están presentes al espíritu. Nada de combinacion de ideas, nada de análisis de conceptos; cuando se llega á esto último, se sale del terreno de la conciencia pura y se entra en las regiones objetivas de la actividad intelectual. Pero como el lenguaje es para expresar los productos de esa actividad; como no está vaciado, por decirlo así, en el molde de la conciencia pura sino en el del entendimiento, nos es imposible hablar sin alguna combinacion lógica ó ideal. Si quisiéramos encontrar una expresion de la conciencia pura sin mezcla de elementos intelectuales, deberíamos buscarla, nó en el lenguaje, sino en el signo natural del dolor ó de la alegria ó de una pasion cualquiera; solo en este caso se expresa con espontaneidad y sin combinaciones de elementos ajenos, que pasa algo en nuestro espíritu, que tenemos conciencia de alguna cosa; pero desde el momento en que hablamos, expresamos algo mas que la conciencia pura; el verbo externo indica el interno, producto de la actividad intelectual, concepto de ella, que envuelve ya un sujeto y un objeto, y que por tanto se halla ya en una region muy superior á la de la conciencia pura.\"},{\"heading\":false,\"text\":\"[181.] Para demostrar la verdad de lo que acabo de decir, examinemos la expresion «yo pienso.» Esta es una verdadera proposicion que sin alterarse en lo mas mínimo, puede presentarse bajo una forma rigurosamente lógica: «yo soy pensante.» Aquí encontramos sujeto, predicado y cópula. El sujeto es el _yo_, es decir que nos hallamos ya con la idea de un ser, sujeto de actos é impresiones, posesor de una actividad significada en el predicado; ese _yo_, pues, se nos ofrece como algo muy superior al órden de la conciencia pura, es nada menos que la idea de substancia. Analicemos mas detenidamente lo que en él se encierra.\"},{\"heading\":false,\"text\":\"Tenemos en primer lugar la unidad de conciencia; el _yo_ carece de sentido, si no significa algo que es uno é idéntico, á pesar de la pluralidad y diversidad que en él se realizan. La unidad experimental de conciencia trae consigo por consecuencia precisa la unidad del ser que la experimenta. Este ser es el sujeto en que se realizan las variaciones, sin lo cual no su podria decir: _yo_. Tenemos pues, que en una expresion tan simple están envueltas las ideas de unidad y de su relacion á la pluralidad, de substancia, y de su relacion á los accidentes; es decir que la idea del _yo_, bien que expresiva de una unidad simplicísima, es compuesta bajo el aspecto lógico, encerrando varias cosas del órden ideal, y que no se hallan en la conciencia pura. La idea del _yo_ propiamente dicha, aunque comun en cierto modo á todos los hombres, es en sí misma altamente filosófica, por encerrar una combinacion de elementos que pertenecen al órden intelectual puro.\"},{\"heading\":false,\"text\":\"[182.] El predicado _pensante_ es la expresion de una idea general, comprensiva, no solo de todo pensamiento, sino tambien de todo fenómeno que afecta inmediatamente al espíritu. Estos fenómenos considerados en lo que tienen de comun, bajo la idea general de presentes al espíritu, vienen significados en la palabra _pensante_.\"},{\"heading\":false,\"text\":\"La relacion del predicado con el sujeto, ó la conveniencia de _pensante_ al _yo_, expresa tambien un análisis digno de atencion. Por el pronto se echa de ver una descomposicion del concepto del _yo_ en dos ideas: la de sujeto de varias modificaciones, y la de pensante; sin esto la proposicion carece de sentido, ó mejor, su expresion se hace imposible. La idea de sujeto, envuelve las de unidad y de substancia; y la de pensante encierra la de actividad ó bien la de pasividad (permítaseme la expresion) acompañada de conciencia.\"},{\"heading\":false,\"text\":\"[183.] Para que la proposicion sea posible, es preciso suponer que la descomposicion de las ideas ha comenzado en algun punto: es decir, que ó en la del _yo_ hemos encontrado la de _pensante_, ó en esta última la del _yo_. Colocándonos en el _yo_, prescindiendo de _pensante_, nos encontramos con la idea de sujeto ó de substancia en general, donde por mas que cavilemos no alcanzaremos á descubrir la de _pensante_. El _yo_ en sí, no se nos manifiesta, le conocemos por el pensamiento, y por tanto en este debemos fijar el punto de partida, y nó en aquel; de lo que se infiere que en dicha proposicion, lo primitivamente conocido, es mas bien el predicado que el sujeto; y que de los dos conceptos, el del sujeto tiene mas bien el carácter de contenido que el de continente.\"},{\"heading\":false,\"text\":\"En efecto: el _yo_ nace, digámoslo así, para sí mismo, con la presencia del pensamiento; si la actividad intelectual se concentra para buscar su primer apoyo, se encuentra nó con el _yo_ puro, sino con sus actos; es decir, con su pensamiento. Este último es por consiguiente el objeto primitivo de la actividad intelectual reflexiva; este es su primer elemento de combinacion, su primer dato para la resolucion del problema. Fijando la vista en este elemento, descubre una unidad en medio de la pluralidad, descubre un ser que continúa el mismo en medio del flujo y reflujo de los fenómenos de la conciencia: esta identidad se la atestigua de una manera irresistible la conciencia misma. La idea del _yo_ pues está sacada del pensamiento, y por consiguiente mas bien nace el sujeto del predicado que nó el predicado del sujeto.\"},{\"heading\":false,\"text\":\"[184.] El pensamiento de donde se saca la idea del _yo_, no es el pensamiento en general, sino realizado, existente en nosotros mismos. Pero esta realidad es infecunda, si no se ofrece al espíritu bajo una idea general; porque es evidente que el _yo_ no sale de un acto solo, pues que es la unidad sujeto de la pluralidad. Para llegar á la idea del _yo_ necesitamos la unidad de conciencia, y esta no la conocemos sino en cuanto la tenemos experimentada, es decir, en cuanto percibimos la relacion de lo uno á lo múltiplo, de un sujeto á sus modificaciones.\"},{\"heading\":false,\"text\":\"Tanta elaboracion es necesaria para producir una expresion tan sencilla como «yo pienso;» por donde se echa de ver con cuánta razon he distinguido entre el fondo y la forma, y cuán inconsideradamente proceden los que confunden cosas tan diversas. Así, y por falta del debido análisis, se dan en la filosofía saltos inmensos pasando de un órden á otro, confundiendo las ideas y embrollando las cuestiones.\"},{\"heading\":false,\"text\":\"[185.] Para dilucidar completamente la materia examinaré las relaciones de la existencia con el pensamiento; exámen que será muy fácil teniendo presentes las observaciones anteriores.\"},{\"heading\":false,\"text\":\"Es cierto que concebimos la existencia anterior al pensamiento: nada puede pensar sin existir, la existencia es para el pensamiento una condicion indispensable; pensar y no existir, es una contradiccion manifiesta. Pero lo que se ofrece primitivamente á nuestro espíritu, no es la existencia sino el pensamiento; y este nó en abstracto, sino determinado, experimental, empírico como se dice ahora. La idea de existencia es general, comprende á todo ser, y la conciencia no puede comenzar por ella; ora lleguemos á esta idea por abstraccion, ora sea una forma preexistente en nuestro espíritu, no es lo primero que se nos ocurre; ó para hablar con mas exactitud, no es el último punto que encontramos al seguir con movimiento retrógrado el hilo de nuestros conocimientos para descubrir su punto de partida. Este es la conciencia, que despues de objetivada, y habiendo sufrido el análisis del concepto que ofrece, nos presenta la idea de existencia como contenido en ella.\"},{\"heading\":false,\"text\":\"Se infiere de esto, que el _luego existo_, no es rigurosamente hablando una consecuencia del «yo pienso,» sino la intuicion de la idea de existencia en la de pensamiento. Hay aquí dos proposiciones _per se notæ_ como dicen los escolásticos; una general: «lo pensante es existente;» otra particular; «yo pensante, soy existente.» La primera pertenece al órden puramente ideal, es de evidencia intrínseca, independientemente de toda conciencia particular; la segunda participa de los dos órdenes; real é ideal; real, en cuanto encierra el hecho particular de la conciencia; ideal, en cuanto incluye una combinacion de la idea general de la existencia con el hecho particular: pues solo así es concebible la union del predicado con el sujeto.\"},{\"heading\":false,\"text\":\"[186.] Ahora será sumamente fácil resolver todas las cuestiones que se agitan en las escuelas.\"},{\"heading\":false,\"text\":\"Primera cuestion. ¿El principio «yo pienso» depende de otro? Debe responderse con distincion: si se entiende por este principio el simple hecho de la conciencia, es evidente que nó. Para nuestro entendimiento, no hay nada anterior á nosotros; todo lo que conocemos, en cuanto conocido por nosotros, supone nuestra conciencia; si la suprimimos, lo destruimos todo; y si ensayamos el destruirlo todo, ella permanece indestructible: no depende pues de nada, no presupone nada.\"},{\"heading\":false,\"text\":\"Si por el principio «yo pienso» se entiende una proposicion, en tal caso no puede haber dimanado sino de un raciocinio, ó mas bien de un análisis: y así no puede ser el principio fundamental de nuestros conocimientos.\"},{\"heading\":false,\"text\":\"[187.] Segunda cuestion. Faltando los demás principios, ¿falta tambien el presente? Aplíquese la misma distincion: como simple hecho, nó; como proposicion, sí. Niéguese todo, incluso el principio de contradiccion, la conciencia subsiste. Pero negado el principio de contradiccion, queda destruida toda proposicion; toda combinacion es absurda; el análisis, la relacion del predicado con el sujeto, son palabras vacías de sentido.\"},{\"heading\":false,\"text\":\"[188.] Tercera cuestion. Admitido el principio «yo pienso», ¿puede ser conducido á la verdad al menos indirectamente, quien niegue los demás? Es menester distinguir: ó se trata de reducirle por raciocinio ó por observacion; es decir, ó se le quiere combatir con argumentos ó se trata de llamarle la atencion sobre sí propio, como se hace con un hombre distraido ó con uno que padece enagenacion mental. Lo segundo se puede hacer; lo primero nó. Quien niega todos los principios incluso el de contradiccion, hace imposible todo raciocinio; en vano pues se discurre contra él. Ensayémoslo.\"},{\"heading\":false,\"text\":\"Tú piensas, se le dirá; al menos así lo afirmas cuando admites el principio «yo pienso.»\"},{\"heading\":false,\"text\":\"Es verdad.\"},{\"heading\":false,\"text\":\"Luego debes admitir tambien el principio de contradiccion.\"},{\"heading\":false,\"text\":\"¿Por qué?\"},{\"heading\":false,\"text\":\"Porque de otro modo podrias pensar y no pensar á un mismo tiempo.\"},{\"heading\":false,\"text\":\"No hay inconveniente.\"},{\"heading\":false,\"text\":\"Pero entonces destruyes tu pensamiento....\"},{\"heading\":false,\"text\":\"¿Por qué?\"},{\"heading\":false,\"text\":\"¿Piensas? ¿no es verdad?\"},{\"heading\":false,\"text\":\"Cierto.\"},{\"heading\":false,\"text\":\"Segun tú mismo, es posible que no pienses al mismo tiempo.\"},{\"heading\":false,\"text\":\"Estamos conformes.\"},{\"heading\":false,\"text\":\"Luego destruyes tu pensamiento: porque cuando no piensas se destruye el «yo pienso;» y como todo esto es simultáneo, resulta que destruyes tu propio pensamiento.\"},{\"heading\":false,\"text\":\"Nada de eso: lo que hay en el argumento que se me objeta es que se supone verdadero lo que yo niego; incurriéndose en el sofisma que los dialécticos llaman peticion de principio. En efecto, por lo mismo que niego el principio de contradiccion, no admito que el no ser destruya al ser, ni el ser al no ser; y por consiguiente, que el no pienso pueda destruir el yo pienso. Cuando se me arguye en este sentido, se supone lo mismo que se busca; se me ataca por principios que yo no reconozco. En vuestro sistema, en que el ser destruye al no ser y vice-versa, es cierto que el pensar y el no pensar son incompatibles; pero en mis principios el caso es muy sencillo, como segun ellos no es imposible que una cosa sea y no sea á un mismo tiempo, cuando no pienso no dejo de pensar.\"},{\"heading\":false,\"text\":\"Este lenguaje es absurdo, pero consecuente: negado el principio, la deduccion es necesaria; y si se le replica que en tal caso no puede ni hacer el raciocinio que se acaba de oir, podrá él contestar, que tampoco pueden raciocinar los adversarios; ó que si se quiere, no halla inconveniente en que se raciocine y no se raciocine.\"},{\"heading\":false,\"text\":\"No hay otro medio de reducir á un hombre extraviado de esta manera que el de la observacion; se ha salido de la razon y por tanto es imposible volverle á ella por medio de ella misma. Las observaciones que se le dirigen han de ser mas bien un llamamiento, una especie de grito para despertar la razon, que nó una combinacion para reconstruirla; es un hombre dormido ó desvanecido á quien se llama y se toca para volverle en sí, nó un adversario con quien se disputa (XIX).\"}]},{\"title\":\"CAPÍTULO XX\",\"blocks\":[{\"heading\":false,\"text\":\"VERDADERO SENTIDO DEL PRINCIPIO DE CONTRADICCION.\"},{\"heading\":false,\"text\":\"OPINION DE KANT.\"},{\"heading\":false,\"text\":\"[189.] Antes de examinar el valor del principio de contradiccion como punto de apoyo de todo conocimiento, será bien fijar con exactitud su verdadero sentido. Esto me obliga á entrar en algunas consideraciones sobre una opinion de Kant manifestada en su _Crítica de la razon pura_, á propósito de la forma con que el principio de contradiccion ha sido enunciado hasta el presente en todas las escuelas filosóficas. Conviene el metafísico aleman en que sea cual fuere la materia de nuestro conocimiento y de cualquier modo que se le refiera el objeto, es condicion general aunque puramente negativa, de todos nuestros juicios, el que no se contradigan mutuamente; de otro modo, aun sin órden al objeto, no son nada en sí mismos. Asentada esta doctrina advierte que se llama principio de contradiccion el siguiente: «un predicado que repugna á una cosa no le conviene;» observando en seguida que este es un criterio universal de toda verdad, aunque puramente negativo; mas que por lo mismo pertenece exclusivamente á la lógica, pues que vale para los conocimientos puramente como conocimientos en general, sin relacion á su objeto, y declara que la contradiccion los hace desaparecer completamente. «Hay sin embargo, continúa, una fórmula de este célebre principio puramente formal y desprovisto de contenido, fórmula que encierra una síntesis confundida mal á propósito con el principio mismo, y sin la menor necesidad. Héla aquí; es imposible que una cosa sea y no sea á _un mismo tiempo_. A mas de que la certeza apodíctica ha sido añadida inútilmente aquí (por la palabra _imposible_), certeza que debe de sí misma estar comprendida en la proposicion, este juicio se halla además afectado por la condicion del tiempo y significa en algun modo lo siguiente: _una cosa_ = A, que es alguna cosa = B, no puede al mismo tiempo ser no B; pero puede muy bien ser sucesivamente lo uno y lo otro (B y no B). Por ejemplo, un hombre que es jóven no puede ser viejo á un mismo tiempo; pero este mismo hombre puede muy bien ser jóven en un tiempo y ser viejo ó no ser jóven en otro; es así que el principio de contradiccion, como principio puramente lógico, no debe restringir su significado á relaciones de tiempo; luego esta fórmula es del todo contraria al objeto del principio mismo. La equivocacion nace de que se comienza por separar el predicado de una cosa del concepto de ella; y en seguida se une á este mismo predicado su contrario, lo que no da jamás una contradiccion con el sujeto sino únicamente con su predicado que le está unido sintéticamente; contradiccion que ni aun tiene lugar sino en cuanto el primer predicado y el segundo son puestos al mismo tiempo. Si digo, un hombre que es ignorante no es instruido, la condicion _al mismo tiempo_ debe estar expresada, porque el que es ignorante en un tiempo puede muy bien ser instruido en otro. Pero si digo, ningun hombre ignorante es instruido, la proposicion será analítica, porque el carácter de la ignorancia constituye ahora el concepto del sujeto, en cuyo caso la proposicion negativa dimana inmediatamente de la proposicion contradictoria, sin que la condicion _al mismo tiempo_ deba intervenir. Por esta razon he cambiado mas arriba la fórmula del principio de contradiccion, de manera que por ella fuese explicada claramente la naturaleza de una proposicion analítica.» (Lógica trascendental, libro 2.º cap. 2.º seccion 1.ª).\"},{\"heading\":false,\"text\":\"[190.] El lector no comprenderá bien el sentido de este pasaje, ya de suyo no muy claro, si no sabe lo que Kant entiende por proposiciones analíticas y sintéticas; lo explicaré. En todos los juicios afirmativos la relacion de un predicado con un sujeto es posible de dos maneras: ó el predicado pertenece al sujeto como contenido en él, ó le es completamente extraño, aunque en realidad esté ligado con él mismo. En el primer caso, el juicio es analítico, en el segundo sintético. Los juicios analíticos afirmativos son aquellos en que la union del predicado con el sujeto es concebida por identidad; al contrario se llaman sintéticos aquellos en que dicha union está concebida sin identidad. Kant aclara su idea con los ejemplos siguientes. «Cuando digo todos los cuerpos son extensos, este es un juicio analítico, pues no necesito salir del concepto de cuerpo para encontrarle unida la extension; me basta descomponerle, es decir, que es suficiente el tener conciencia de la diversidad que pensamos siempre en este concepto, para encontrar en él el predicado de que se trata. Este es pues un juicio analítico. Al contrario, cuando digo, todos los cuerpos son pesados, aquí el predicado es una cosa del todo diferente de lo que pienso en general por el simple concepto de cuerpo: la union pues de semejante predicado da un juicio sintético.» (Crítica de la razon pura. Introduccion § 1).\"},{\"heading\":false,\"text\":\"Échase de ver fácilmente la razon de la nueva nomenclatura empleada por el filósofo aleman. Llama analíticos á los juicios en que basta descomponer el sujeto para encontrar en él el predicado, sin necesidad de añadirle nada que no estuviese ya pensado en el concepto mismo del sujeto, á lo menos oscuramente; y apellida sintéticos ó de composicion, aquellos en que es preciso añadir algo al concepto del sujeto, pues que el predicado no se encuentra en este concepto por mas que se le descomponga.\"},{\"heading\":false,\"text\":\"[191.] Esta division de juicios en analíticos y sintéticos es muy nombrada en la filosofía moderna, sobre todo entre los alemanes; y de seguro no falta quien se imagina que este es un descubrimiento del autor de la _Crítica de la razon pura_; la misma novedad del nombre puede dar orígen á la equivocacion. Sin embargo, en todos los autores escolásticos que olvidados y cubiertos de polvo yacen ahora en el fondo de las bibliotecas, se habla de juicios analíticos y sintéticos; bien que nó con estos nombres. Se decia que los juicios eran de dos especies: unos en que el predicado estaba contenido en la idea del sujeto y otros en que nó; á las proposiciones que expresaban los juicios de la primera clase se las llamaba _per se notæ_ ó conocidas por sí mismas, á causa de que entendida la significacion de los términos se veia que el predicado estaba contenido en la idea ó en el concepto del sujeto. Se les daba tambien el nombre de primeros principios, y á la percepcion de ellos se la llamaba _inteligencia, intellectus_, distinguiéndola de la _razon_ en cuanto esta versaba sobre los conocimientos de evidencia mediata ó de raciocinio.\"},{\"heading\":false,\"text\":\"Véase si dejan algo que desear ni en claridad ni en precision, los siguientes textos de Santo Tomás. «Una proposicion es conocida por sí, _per se nota_, cuando el predicado está incluido en la razon del sujeto, como el hombre es animal; pues que animal es de la esencia del hombre. Si pues todos conocen lo que es el sujeto y el predicado, la proposicion será conocida por sí, para todos; como se ve en los primeros principios de las demostraciones cuyos términos son cosas comunes que nadie ignora, como ser y no ser; todo y parte y otras semejantes.» (1.ª Parte. Cuest. 2. art. 1.º)\"},{\"heading\":false,\"text\":\"«Cualquiera proposicion cuyo predicado es de la esencia del sujeto, es conocida por sí, bien que puede suceder que no lo sea para quien ignore lo que significa la definicion del sujeto: así esta proposicion, «el hombre es racional,» es de su naturaleza conocida por sí; pues _quien dice hombre dice racional_.» (1.ª 2.ª Cuest. 94. Art. 2).\"},{\"heading\":false,\"text\":\"[192.] Por estos ejemplos, y otros muchos que seria fácil aducir, se ve que la distincion entre los juicios analíticos y sintéticos era vulgar en las escuelas muchos siglos antes de Kant. Los analíticos eran todos los que se formaban por evidencia inmediata; y sintéticos, los que resultaban de evidencia mediata, ya fuese esta del órden puramente ideal, ya dependiese en algun modo de la experiencia. Se sabia muy bien que hay conceptos de sujeto en los cuales está pensado el predicado, á lo menos en confuso: y por esto se explicaba esta union ó identidad, diciendo que las proposiciones en que se enunciaba, eran _per se notæ ex terminis_. El predicado en los juicios analíticos está ya en el sujeto; nada se le añade segun Kant; solo se le explica; «Quien dice _hombre_ dice _racional_;» así habla Santo Tomás: la idea es la misma que la del filósofo aleman.\"},{\"heading\":false,\"text\":\"[193.] Pero volvamos al exámen de si debe ó nó mudarse la fórmula en que hasta ahora se ha expresado el principio de contradiccion.\"},{\"heading\":false,\"text\":\"La primera observacion de Kant se refiere á la palabra _imposible_ por juzgarla añadida inútilmente, ya que la certeza apodíctica que se quiere expresar, debe estar comprendida en la misma proposicion. Kant formula el principio de esta manera: «un predicado que _repugna_ á una cosa no le conviene.» ¿Qué se entiende por la palabra imposible? «posible é imposible absolutamente, se dice por la relacion de los términos: posible porque el predicado no repugna al sujeto; imposible, cuando el predicado repugna al sujeto;» así se expresa Santo Tomás (1 P. Cuest. 25. Art. 3.) y con él todas las escuelas; luego la imposibilidad es la repugnancia del predicado al sujeto, luego ser una cosa imposible es ser repugnante, luego emplea Kant el mismo lenguaje que reprende en los otros. La fórmula comun podria expresarse de esta manera: «que una cosa sea y no sea al mismo tiempo, repugna; ó bien hay repugnancia entre el ser y el no ser; ó bien el ser excluye al no ser;» todo viene á parar á lo mismo, y nada mas expresa Kant cuando dice: un predicado que repugna á una cosa, no le conviene.\"},{\"heading\":false,\"text\":\"[194.] Tratándose de un criterio universal, hay mas exactitud en la fórmula comun que en la de Kant. Esta ciñe el principio á la relacion de predicado y sujeto, y por consiguiente le encierra en el órden puramente ideal, no valiendo para el real sino por una especie de ampliacion. Esta ampliacion aunque muy legítima y muy fácil, no la necesita la fórmula comun: con decir, el ser excluye al no ser, abraza lo ideal y lo real, y presenta al entendimiento la imposibilidad, no solo de los juicios contradictorios, sino tambien de las cosas contradictorias.\"},{\"heading\":false,\"text\":\"Kant admite que este principio es la condicion _sine qua non_ de la verdad de nuestros conocimientos, de manera que debemos tener cuidado de no ponernos jamás en contradiccion con él so pena de anonadar todo conocimiento. Hágase la prueba: á un hombre que no se haya ocupado á fondo de estas materias, aunque sepa muy bien lo que se entiende por predicado y sujeto, dénsele las dos fórmulas; ¿cuál de ellas se le presentará como mas fácil para todos los usos así en lo externo como en lo interno? es claro que no será la de Kant. Que una cosa no puede ser y no ser á un mismo tiempo, al instante se ve con toda generalidad, y se aplica el principio á todos los usos así en el órden real como en el ideal. Se trata de un objeto externo y se dice: esto no puede ser y no ser á un mismo tiempo; se trata de juicios contradictorios, de ideas que se excluyen, y se dice sin dificultad: esto no puede ser, porque es imposible que á un mismo tiempo una cosa sea y no sea. Pero no se ve con la misma facilidad y prontitud cómo se hace el tránsito del órden ideal al real, ó cómo pueden tener uso en el órden de los hechos las ideas puramente lógicas de sujeto y predicado. Luego la fórmula comun, á mas de ser igualmente exacta que la de Kant, es mas sencilla, mas inteligente, y mas fácilmente aplicable. ¿Pueden desearse calidades mejores para un criterio universal, para la condicion _sine qua non_ de la verdad de nuestros conocimientos?\"},{\"heading\":false,\"text\":\"[195.] Hasta aquí he dado por supuesto que la fórmula de Kant expresaba realmente el principio de contradiccion; pero esta suposicion es cuando menos inexacta. No cabe duda que seria una contradiccion el que un predicado que repugnase á un sujeto, le conviniese; y en este sentido se puede decir que el principio de contradiccion está de algun modo expresado en la fórmula de Kant. Mas esto no es suficiente: porque de lo contrario seria preciso decir que todo axioma expresa el principio de contradiccion, pues no es posible negar ningun axioma sin una contradiccion. La fórmula del principio debe expresar _directamente_ la exclusion recíproca, la repugnancia entre el ser y el no ser; esto es lo que se quiere significar; jamás se ha entendido otra cosa por el principio de contradiccion. Kant en su nueva fórmula no expresa directamente esta exclusion: lo que expresa es, que cuando de la idea de un sujeto está excluido el predicado, este no le conviene. Si bien se mira, lejos de que esta fórmula exprese el principio de contradiccion, es la famosa de los cartesianos: lo que está comprendido en la idea clara y distinta de una cosa, se puede afirmar de ella con toda certeza. En substancia las dos fórmulas expresan lo mismo, y solo se distinguen por dos diferencias puramente accidentales: 1ª. en que la de Kant es mas concisa; 2.ª en que la de este filósofo es negativa y la de los cartesianos afirmativa.\"},{\"heading\":false,\"text\":\"[196.] Kant viene á decir: «lo que está _excluido_ de la idea clara y distinta de una cosa, se puede negar de ella.» _Predicado que repugna_ á un sujeto, es lo mismo que lo que está _excluido_ de la idea de una cosa; _no le conviene_, es lo mismo que _se puede negar de él_. Y como por otra parte es evidente que el principio de los cartesianos debe entenderse en ambos sentidos, afirmativo y negativo, pues que al decir que lo que está comprendido en la idea clara y distinta de una cosa, se puede afirmar de la misma, entendian tambien que cuando una cosa estaba excluida, se podia negar; resulta que Kant dice lo mismo que ellos; así intentando corregir á todas las escuelas, ha incurrido en una equivocacion no muy á propósito para abonar su perspicacia.\"},{\"heading\":false,\"text\":\"Claro es que la misma fórmula de Kant implica esta otra: el predicado contenido en la idea de un sujeto, le conviene. Esta proposicion es tambien condicion _sine qua non_, de todos los juicios analíticos afirmativos: pues estos desaparecen, si no conviene al sujeto lo que está en su idea. En tal caso, no hay diferencia ni aun aparente entre la fórmula de Kant y la de los cartesianos; solo hay variedad en los términos: la proposicion es exactamente la misma. Por donde se echa de ver que antes de afirmar que en el punto mas claro y mas fundamental de los conocimientos humanos, se han expresado mal todas las escuelas, es necesario andar con mucho tiento: testigo la _originalidad_ de la fórmula de Kant.\"},{\"heading\":false,\"text\":\"[197.] No fué mas feliz el autor de la _Crítica de la razon pura_ al censurar la condicion _á un mismo tiempo_, que se añade generalmente á la fórmula del principio de contradiccion. Ya que él se tomó la libertad de creer que ningun filósofo antes de él habia expresado de la manera conveniente este principio, permítaseme decir que él no entendió bien lo que querian significar los otros. No creo que con decir esto cometa una profanacion filosófica; si para ciertos hombres Kant es un oráculo, todos los filósofos juntos y la humanidad entera son tambien oráculos que deben ser oidos y respetados.\"},{\"heading\":false,\"text\":\"Segun el mismo Kant, el principio de contradiccion es condicion _sine qua non_ de todos los conocimientos humanos. Si pues esta condicion ha de servir para su objeto, es necesario que se la exprese de un modo aplicable á todos los casos. Nuestros conocimientos no se componen únicamente de elementos necesarios, sino que admiten en buena parte ideas enlazadas con lo contingente; pues como hemos visto ya, las verdades puramente ideales no conducen á nada positivo si no se las hace descender al terreno de la realidad. Los seres contingentes están sometidos á la condicion del tiempo; y todos los conocimientos que á ellos se refieren, deben contar siempre con esta condicion. Su existencia se limita á un determinado espacio de tiempo; y conforme á esta determinacion es preciso pensar y hablar de la misma. Aun las propiedades esenciales están afectadas en cierto modo por la condicion del tiempo; porque si bien prescinden de él, si se las considera en general, no es así cuando están realizadas, es decir, cuando dejan de ser una pura abstraccion y son una cosa positiva. Hé aquí pues la razon, y razon bien poderosa y profunda, de que todas las escuelas hayan juntado la condicion del tiempo con la fórmula del principio de contradiccion: razon bien profunda, repito, y que es extraño se escapase á la penetracion del filósofo aleman.\"},{\"heading\":false,\"text\":\"[198.] La importancia de la materia reclama todavía ulteriores aclaraciones. Lo esencial en el princio de contradiccion, es la exclusion del ser por el no ser y del no ser por el ser. La fórmula debe expresar este hecho, esta verdad que se nos ofrece con evidencia inmediata y que es contemplada por el entendimiento con una intuicion clarísima que no consiente duda ni oscuridad de ninguna especie.\"},{\"heading\":false,\"text\":\"El verbo _ser_ puede tomarse de dos maneras: sustantivamente, en cuanto significa la existencia, y copulativamente, en cuanto expresa la relacion de un predicado con un sujeto. Pedro es; aquí el verbo _es_ significa la existencia de Pedro, y equivale á esta otra: Pedro existe. El triángulo equilátero es equiángulo; aquí el verbo _es_ se toma copulativamente; pues no se afirma que exista ningun triángulo equilátero, y solo se establece la relacion de la igualdad de los ángulos con la igualdad de los lados, prescindiendo absolutamente de que existan unos ni otros.\"},{\"heading\":false,\"text\":\"El principio de contradiccion debe extenderse á los casos en que el verbo _ser_ es copulativo y á los en que es sustantivo; porque cuando decimos que es imposible que una cosa sea y no sea, no hablamos únicamente del órden ideal ó de las relaciones entre predicados y sujetos, sino tambien del órden real: si no se refiriese á este último tendríamos que el mundo entero de las existencias estaria falto de la condicion indispensable para todo conocimiento sino tambien para todo ser en sí mismo, prescindiendo de que sea conocido y de que sea inteligente. ¿Qué fuera un ser real que pudiese ser y no ser? ¿qué significa una contradiccion realizada? luego el principio se ha de extender no solo al verbo _ser_ como copulativo, sino tambien como sustantivo. Todas las existencias finitas, inclusa la nuestra, son medidas por una duracion sucesiva; luego si la fórmula del principio de contradiccion no ha de ser inaplicable á todo cuanto conocemos en el universo, ha de estar acompañado de la condicion del tiempo. De todas las cosas finitas que existen se ha verificado que no existian y de todas se podria verificar que no existiesen: de ninguna se afirmaria con verdad que su no existencia fuese imposible; esta imposibilidad nace de la existencia en un tiempo dado, y solo con respecto á este tiempo se la puede afirmar. Luego la condicion del tiempo es absolutamente necesaria en la fórmula del principio de contradiccion, si esta fórmula ha de poder servirnos para lo existente, es decir, para lo que tienen de objeto real nuestros conocimientos.\"},{\"heading\":false,\"text\":\"[199.] Veamos ahora lo que sucede en el órden puramente ideal, donde el verbo _ser_ se toma copulativamente. Las proposiciones del órden puramente ideal son de dos clases: unas tienen por sujeto una idea genérica que con la union de la diferencia, puede pasar á una especie determinada; otras tienen por sujeto la misma especie, ó sea la idea genérica junto con la determinacion de la diferencia. La palabra _ángulo_ expresa la idea genérica comprensiva de todos los ángulos, idea que unida con la diferencia correspondiente, puede constituir las especies de ángulo recto, agudo ú obtuso. Sucédenos á cada paso el modificar la idea genérica de varias maneras; y como en esto entra por necesidad una sucesion en que se nos representan distintos conceptos que todos tienen por base la idea genérica, resulta que consideramos á esta como un ser que sucesivamente se transforma. Para expresar esta sucesion puramente intelectual, empleamos la idea de tiempo; y hé aquí una de las razones que justifican el empleo de esta condicion aun en el órden puramente ideal. Así decimos: un ángulo no puede ser á un mismo tiempo recto y no recto; porque encontramos que la idea de ángulo puede estar sucesivamente determinada por la diferencia que le constituye recto y no recto; pero estas determinaciones no pueden coexistir ni aun en nuestro concepto, por cuya razon no afirmamos la imposibilidad absoluta de la union de la diferencia con el género, sino que la limitamos á la condicion de la simultaneidad.\"},{\"heading\":false,\"text\":\"En esta proposicion: un ángulo recto no puede ser obtuso; el sujeto no es la idea genérica sola, sino unida con la diferencia _recto_. En el concepto del sujeto formado de estas dos ideas, ángulo y recto, vemos la imposibilidad de que se les una la idea _obtuso_. Esto sin ninguna condicion de tiempo, y en este caso tampoco se la expresa. Se dice con frecuencia: un ángulo no puede ser al mismo tiempo recto y obtuso; pero jamás se dice el ángulo recto no puede _á un mismo tiempo_ ser obtuso, sino absolutamente: el ángulo recto no puede ser obtuso.\"},{\"heading\":false,\"text\":\"[200.] Observa Kant que la equivocacion dimana de que se comienza por separar el predicado de una cosa del concepto de esta cosa, y que en seguida se le junta á este mismo predicado su contrario, lo que no da jamás una contradiccion con el sujeto sino con el predicado que le está unido sintéticamente; contradiccion que no tiene lugar sino en cuanto el primero y el segundo predicado están puestos á un mismo tiempo. Esta observacion de Kant es en el fondo muy verdadera; pero adolece de dos defectos: el que se la presenta como original cuando no dice sino cosas muy sabidas; y el que se le emplea para combatir una equivocacion que no existe sino en la mente del filósofo que pretende quitarla á los demás. Las dos proposiciones analizadas en el párrafo anterior confirman lo que acabo de decir: el ángulo no puede ser recto y no recto. Aquí la condicion del tiempo es necesaria porque la repugnancia no está entre el predicado y el sujeto sino entre los dos predicados. El ángulo puede ser recto ó no recto, con tal que esto se verifique en tiempos diferentes. El ángulo recto no puede ser obtuso; aquí la condicion del tiempo no debe ser expresada, porque entrando en el concepto del sujeto la idea _recto_, está enteramente excluida la de _obtuso_.\"},{\"heading\":false,\"text\":\"[201.] Si el principio de contradiccion hubiese de servir únicamente para los juicios analíticos, esto es, para aquellos en que el predicado está contenido en la idea del sujeto, la condicion del tiempo no debiera ser expresada nunca; pero como este principio ha de guiarnos tambien para todos los demás juicios, se sigue que en la fórmula general no podia prescindirse de una condicion absolutamente indispensable en la mayor parte de los casos. En el estado actual de nuestro entendimiento, mientras nos hallamos en esta vida, el no prescindir del tiempo es la regla, el prescindir la excepcion: ¿y se queria que una fórmula general se refiriese solo á la excepcion y dejase en olvido la regla?\"},{\"heading\":false,\"text\":\"[202.] No se concibe la razon que pudo mover á Kant á ilustrar esta materia con los ejemplos arriba citados. No cabe decir cosas mas comunes é inoportunas que las añadidas por este filósofo cuando ilustra la materia con algunos ejemplos. «Si digo, un hombre que es ignorante no es instruido, la condicion _al mismo tiempo_ debe estar expresada; porque el que es ignorante en un tiempo, puedo muy bien ser instruido en otro.» Esto á mas de ser comun é inoportuno, es sobre manera inexacto. Si la proposicion fuese: un hombre no puede ser ignorante é instruido; entonces la condicion _al mismo tiempo_ debiera añadirse, porque no dándose preferencia á ningun predicado con respecto al otro, se indicaria el motivo de la repugnancia, que es de predicado á predicado y no de predicado á sujeto. Pero en el ejemplo aducido por Kant, «el hombre que es ignorante no es instruido,» el sujeto no es solo hombre, sino hombre ignorante; el predicado instruido recae sobre el hombre modificado con el predicado ignorante; y por consiguiente la expresion del tiempo no es necesaria ni se la emplea en el lenguaje comun.\"},{\"heading\":false,\"text\":\"Hay mucha diferencia entro estas dos proposiciones: el hombre que es ignorante _no es_ instruido; el hombre que es ignorante, _no puede ser_ instruido. En la primera, la condicion del tiempo no debe estar expresada por las razones dichas: en la segunda sí, porque hablándose de la imposibilidad de un modo absoluto, se negaria al ignorante hasta la _potencia_ de ser instruido.\"},{\"heading\":false,\"text\":\"[203.] El otro ejemplo de Kant es el siguiente: «pero si digo, ningun hombre ignorante es instruido, la proposicion será analítica, porque el carácter de la ignorancia constituye ahora el concepto del sujeto y por tanto la proposicion negativa se deriva inmediatamente de la proposicion contradictoria sin que la condicion _al mismo tiempo_ deba intervenir.» No se ve la razon porque establece Kant tanta diferencia entre estas dos proposiciones: un hombre que es ignorante no es instruido; ningun hombre ignorante es instruido; en ambas el predicado no se refiere tan solo á hombre, sino á hombre ignorante, y tanto vale decir hombre que es ignorante, como hombre ignorante. Si pues la expresion del tiempo no es necesaria en la una, tampoco lo será en la otra.\"},{\"heading\":false,\"text\":\"Si la idea de ignorante afecta al sujeto mismo, el predicado está necesariamente excluido, porque las ideas de instruccion y de ignorancia, son contradictorias: entonces nos hallamos con la regla de los dialécticos de que en materias necesarias, la proposicion indefinida equivale á la universal.\"},{\"heading\":false,\"text\":\"De esta discusion resulta que la fórmula del principio de contradiccion debe ser conservada tal como está, y que no debe suprimirse la condicion del tiempo, porque de otro modo se inutilizaria la fórmula para muchísimos casos (XX).\"}]},{\"title\":\"CAPÍTULO XXI\",\"blocks\":[{\"heading\":false,\"text\":\"SI EL PRINCIPIO DE CONTRADICCION MERECE EL TÍTULO DE FUNDAMENTAL; Y EN QUÉ SENTIDO.\"},{\"heading\":false,\"text\":\"[204.] Aclarado ya el verdadero sentido del principio de contradiccion, veamos si merece el título de fundamental, reuniendo todos los caractéres exigidos para esta dignidad científica. Estos son tres: primero, que no se apoye en otro principio. Segundo, que cayendo él, se arruinen todos los demás. Tercero, que permaneciendo él firme, pueda argüirse de una manera concluyente contra quien niegue los demás, reduciéndole á buen camino por demostracion, al menos indirecta.\"},{\"heading\":false,\"text\":\"[205.] Para resolver cumplidamente todas las cuestiones que se refieren al principio de contradiccion, asentaré algunas proposiciones acompañándolas con la demostracion correspondiente.\"},{\"heading\":false,\"text\":\"PRIMERA PROPOSICION.\"},{\"heading\":false,\"text\":\"Si se niega el principio de contradiccion, se desploma toda certeza, toda verdad, todo conocimiento.\"},{\"heading\":false,\"text\":\"Demostracion. Si una cosa puede ser y no ser á un mismo tiempo, podemos estar ciertos y no ciertos, conocer y no conocer, existir y no existir; la afirmacion puede estar junto con la negacion, las cosas contradictorias pueden hermanarse, las distintas identificarse, las idénticas distinguirse; la inteligencia es un caos en toda la extension de la palabra; la razon se trastorna, el lenguaje es absurdo, el sujeto y el objeto se chocan en medio de espantosas tinieblas, toda luz intelectual se ha extinguido para siempre. Todos los principios están envueltos en la ruina universal; y la misma conciencia vacilaria, si al hacer esta suposicion absurda no se hallase sostenida por la invencible mano de la naturaleza. Pero en medio de la absurda hipótesis, la conciencia que no desaparece porque no puede desaparecer, se siente arrastrada tambien por el violento torbellino que lo arroja todo á las tinieblas del caos; en vano se esfuerza por conservar sus ideas, todas desaparecen por la fuerza de la contradiccion; en vano hace brotar otras nuevas para sustituirlas á las que va perdiendo, desaparecen tambien; en vano busca objetos nuevos, desaparecen tambien; y ella misma no continúa sino para sentir la imposibilidad radical de pensar nada; solo ve á la contradiccion que señoreada de la inteligencia, destruye con fuerza irresistible cuanto se quiera levantar.\"},{\"heading\":false,\"text\":\"SEGUNDA PROPOSICION.\"},{\"heading\":false,\"text\":\"[206.] No basta que no se suponga falso el principio de contradiccion; es preciso además suponerle verdadero, si no se quiere que se arruine toda certeza, todo conocimiento, toda verdad.\"},{\"heading\":false,\"text\":\"Demostracion. Las razones alegadas con respecto á la proposicion anterior podrian reproducirse por entero. En el primer caso se supone negada la verdad del principio; en el segundo no se le da por verdadero ni por falso; pero es evidente que la indiferencia no basta; porque desde el momento en que el principio de contradiccion no esté fuera de toda duda, volvemos á caer en las tinieblas, debemos dudar de todo.\"},{\"heading\":false,\"text\":\"No quiero decir que para tener certeza de cualquiera cosa, sea necesario pensar explícitamente en dicho principio; pero sí que debemos tenerle por firmemente asentado, que no podemos abrigar sobre él la menor duda, y que en viendo alguna cosa ligada con él mismo, es preciso considerarla como asida de un punto inmóvil; la menor vacilacion, el mas ligero _quién sabe_!.... sobre este principio, lo arruina todo: la posibilidad de un absurdo es ya por si misma un absurdo.\"},{\"heading\":false,\"text\":\"TERCERA PROPOSICION\"},{\"heading\":false,\"text\":\"[207.] Es imposible encontrar un principio que nos asegure de la verdad del de contradiccion.\"},{\"heading\":false,\"text\":\"Demostracion. Hemos visto que en todo conocimiento es necesario suponer la verdad del principio de contradiccion; luego ninguna puede servir para demostrarle á él. En cualquiera raciocinio que con este objeto se haga, habrá por necesidad un círculo vicioso; se probará el principio de contradiccion con otro principio que á su vez supondrá siempre el de contradiccion. Tendremos pues un edificio que estribará sobre un cimiento y un cimiento que estribará sobre el mismo edificio.\"},{\"heading\":false,\"text\":\"CUARTA PROPOSICION.\"},{\"heading\":false,\"text\":\"[208.] A quien niegue el principio de contradiccion, no se le puede reducir directa ni indirectamente por ningun otro.\"},{\"heading\":false,\"text\":\"Demostracion. Seria curioso oir los argumentos dirigidos contra un hombre que admite la posibilidad del sí y del nó en todo. Cuando se le reduzca al sí, no se le hará perder el nó, y vice-versa. Es imposible no solo argumentar, sino hablar, ni pensar en suposicion semejante.\"},{\"heading\":false,\"text\":\"QUINTA PROPOSICION.\"},{\"heading\":false,\"text\":\"[209.] No es exacto lo que suele decirse que con el principio de contradiccion podamos argüir de una manera concluyente contra quien niegue los demás.\"},{\"heading\":false,\"text\":\"Adviértase que solo digo que _no es exacto_; porque en efecto creo que en el fondo es verdadero, pero mezclado con alguna inexactitud. Para manifestarlo examinemos el valor de la demostracion que se da en casos semejantes. En forma de diálogo las razones, las contestaciones y las réplicas se presentarán con mas claridad y viveza. Supongamos que uno niega este axioma. El todo es mayor que la parte.\"},{\"heading\":false,\"text\":\"Si V. niega esto, admite que una cosa puede ser y no ser á un mismo tiempo.\"},{\"heading\":false,\"text\":\"Esto es lo que se me ha de probar.\"},{\"heading\":false,\"text\":\"El todo de V. será todo y no lo será, y la parte será parte y no parte.\"},{\"heading\":false,\"text\":\"¿Por qué?\"},{\"heading\":false,\"text\":\"En primer lugar, será todo, porque así se supone.\"},{\"heading\":false,\"text\":\"Admitido.\"},{\"heading\":false,\"text\":\"Al mismo tiempo no lo será....\"},{\"heading\":false,\"text\":\"Negado.\"},{\"heading\":false,\"text\":\"No lo será porque no será mayor que su parte.\"},{\"heading\":false,\"text\":\"Buen modo de argumentar; esto es una peticion de principio: yo comienzo por afirmar que el todo no es mayor que su parte, y V. me arguye en el supuesto contrario; pues me dice que el todo no será todo si no es mayor que su parte. Si yo concediese que el todo es mayor que su parte, y luego negase esta propiedad, entonces incurriría en contradiccion haciendo un todo que segun mis principios no seria todo; pero como ahora niego que el todo haya de ser mayor que su parte, debo negar tambien que deje de ser todo, por no ser mayor que su parte.\"},{\"heading\":false,\"text\":\"[210.] ¿A quien discurre de esta manera qué se le puede replicar? nada absolutamente en forma de raciocinio; lo que se puede hacer es llamarle la atencion hácia el absurdo en que se coloca; pero esto nó argumentando, sino determinando con toda exactitud el sentido de las palabras y analizando los conceptos que por ellas se expresan. Esto es lo único que se puede y debe hacer. La contradiccion existe, es cierto; y lo que conviene es que la vea el que ha incurrido en la misma; para lo cual, ó será suficiente la explicacion de los términos y el análisis de los conceptos, ó no bastará nada.\"},{\"heading\":false,\"text\":\"Veámoslo en el mismo ejemplo. El todo es mayor que su parte. ¿Qué es todo? es el conjunto de las partes, es las partes mismas reunidas. En la idea del todo entran pues las partes. ¿Qué significa mayor? Una cosa se dice mayor que otra, cuando además de contener cantidad igual á esta, contiene alguna otra; el siete es mayor que el cinco, porque á mas de contener el mismo cinco, contiene tambien el dos. El todo contiene á la parte y además á las otras partes, luego en la idea de todo entra la idea de ser mayor que su parte. Así se podria reducir á quien negase este principio: método que mas bien que de argumentacion, podria llamarse de explicacion de términos y análisis de conceptos, porque es claro que no se ha hecho mas que definir aquellos y descomponer estos.\"},{\"heading\":false,\"text\":\"SEXTA PROPOSICION.\"},{\"heading\":false,\"text\":\"[211.] El principio de contradiccion no puede ser conocido sino por evidencia inmediata.\"},{\"heading\":false,\"text\":\"Demostracion. Se han de probar dos cosas. Que el conocimiento es por evidencia, y que la evidencia es inmediata. Tocante á lo primero observaré que el principio de contradiccion no es un simple hecho de conciencia sino una verdad puramente ideal. El hecho de conciencia envuelve la realidad, no puede expresarse de ningun modo sin que se afirme alguna existencia; el principio de contradiccion no afirma ni niega nada positivo; esto es, no dice que algo exista ó no exista; solo expresa la repugnancia del ser al no ser, y del no ser al ser, prescindiendo de que el verbo _ser_ se tome sustantiva ó copulativamente.\"},{\"heading\":false,\"text\":\"[212.] Todo hecho de conciencia es algo, no solo existente sino determinado; no es un pensamiento en abstracto, sino tal ó cual pensamiento. El principio de contradiccion no contiene nada determinado; no solo prescinde de la existencia de las cosas sino tambien de la esencia, pues no se refiere á solas las existentes sino tambien á las posibles; y entre estas no distingue especies, sino que las abraza todas en su mayor generalidad. Cuando se dice «es imposible que una cosa sea y no sea,» la palabra _cosa_ no restringe su significacion de ninguna manera; expresa el ser en general, en su mayor indeterminacion. En el _sea_ ó _no sea_, el verbo _ser_ no expresa solo la existencia sino toda clase de relaciones de esencias, tambien en su mas completa indeterminacion. Así el principio se aplica igualmente en estas dos proposiciones; es imposible que la luna sea y no sea; es imposible que un círculo sea y no sea círculo; no obstante que la primera es del órden real, y en ella el verbo _ser_ expresa existencia; y la segunda es del órden ideal, y el verbo _ser_ significa únicamente relacion de predicado á sujeto.\"},{\"heading\":false,\"text\":\"[213.] Todo hecho de conciencia es individual, el principio de contradiccion es lo mas universal que imaginarse pueda; todo hecho de conciencia es contingente, el principio de contradiccion es absolutamente necesario: necesidad que es uno de los caractéres de las verdades conocidas por evidencia.\"},{\"heading\":false,\"text\":\"[214.] El principio de contradiccion es una ley de toda inteligencia; es de una necesidad absoluta tanto para lo finito como para lo infinito: ni la inteligencia infinita se halla fuera de esta necesidad, porque la infinita perfeccion no puede ser un absurdo. El hecho de conciencia como puramente individual, se refiere tan solo al ser que lo experimenta; de que yo exista ó no exista ni el órden de las inteligencias ni el de las verdades sufre alteracion alguna.\"},{\"heading\":false,\"text\":\"[215.] El principio de contradiccion, á mas del carácter de universalidad y necesidad con que se distinguen las verdades de evidencia, posee tambien el del ser visto con esa claridad intelectual inmediata, de que mas arriba se ha tratado. En la idea del ser vemos clarísimamente la exclusion del no ser.\"},{\"heading\":false,\"text\":\"De esto se infiere la prueba de la segunda parte de la proposicion: porque hay evidencia inmediata de la relacion de un predicado con un sujeto, cuando para verla nos basta la sola idea del sujeto sin necesidad de ninguna combinacion con otras ideas; así se verifica en el caso presente, pues no solo no es necesaria ninguna combinacion, sino que todas son imposibles si no se presupone la verdad del principio (XXI).\"}]},{\"title\":\"CAPÍTULO XXII\",\"blocks\":[{\"heading\":false,\"text\":\"EL PRINCIPIO DE LA EVIDENCIA.\"},{\"heading\":false,\"text\":\"[216.] Entre los principios que han figurado en las escuelas en primera línea, con pretension al título de fundamentales, se encuentra el que ha solido llamarse de los cartesianos. «Lo que está comprendido en la idea clara y distinta de una cosa, se puede afirmar de ella con toda certeza.» Ya hemos visto que Kant resucita, aunque en otras palabras, este principio, tomándole equívocamente por sinónimo del de contradiccion. Bien examinada la cosa se echa de ver que tanto la fórmula de los cartesianos como la de Kant no son mas que la expresion de la legitimidad del criterio de la evidencia. Ambas podrian reducirse á otras mas sencillas: la evidencia es criterio de verdad; ó bien, lo evidente es verdadero. Como esta transformacion me ha de servir en adelante para distinguir ideas, en mi opinion muy confusas, daré la razon de ella manifestando la igualdad de las dos expresiones.\"},{\"heading\":false,\"text\":\"[217.] Decir que una cosa está comprendida en la idea clara y distinta de otra, es lo mismo que decir que hay evidencia de que un predicado conviene á un sujeto; las palabras no tienen ni pueden tener otro sentido; «estar comprendido en una idea clara y distinta,» equivale á decir que vemos una cosa en otra con aquella luz intelectual que llamamos evidencia: luego esta expresion, «lo que está comprendido en la idea clara y distinta de una cosa» es exactamente igual á esta: «lo que es evidente.»\"},{\"heading\":false,\"text\":\"Decir que una cosa se puede afirmar de otra con toda certeza, es lo mismo que decir: «la cosa es verdadera, y de esto podemos estar completamente seguros.» Lo que se puede afirmar, es la verdad y solo la verdad: luego esta expresion, «se puede afirmar de ella con toda certeza,» es exactamente igual á esta otra: «es verdadero.»\"},{\"heading\":false,\"text\":\"Así, la expresion de los cartesianos puede transformarse en esta: «lo evidente es verdadero,» ó en su equivalente: «la evidencia es seguro criterio de verdad.»\"},{\"heading\":false,\"text\":\"[218.] «El predicado que repugna á un sujeto, no le conviene,» esta es la fórmula de Kant. La repugnancia de que aquí se trata es la que se encuentra en las ideas, esto es, cuando de la idea del sujeto está necesariamente excluido el predicado por _repugnancia_ intrínseca. La expresion pues «el predicado que repugna á un sujeto,» equivale á esta otra: «cuando de la idea del sujeto se ve con claridad excluido el predicado;» la que á su vez es igual á esta «la exclusion ó la repugnancia entre el sujeto y el predicado es evidente.»\"},{\"heading\":false,\"text\":\"«No le conviene» significa lo mismo que es verdadero que no le conviene; y como estas fórmulas tienen dos valores, uno para los casos afirmativos, otro para los negativos, pues si se dice: el predicado que repugna á un sujeto no le conviene, se puede decir con la misma razon, el predicado contenido en la idea del sujeto le conviene, resulta que la fórmula de Kant coincide exactamente con esta: «lo que es evidente es verdadero.»\"},{\"heading\":false,\"text\":\"[219.] Con esta transformacion se logra mayor sencillez y mas generalidad: sencillez, por la expresion misma; generalidad, porque están contenidos tanto los casos afirmativos como los negativos. Las palabras «lo que es evidente» abrazan tanto las afirmaciones como las negaciones; porque tan evidente puede ser la inclusion de un predicado en un sujeto como su mutua repugnancia. Se puede ver que está contenida una cosa en la idea de otra, como que está excluida de ella. Bajo todos los conceptos es preferible la fórmula: lo que es evidente es verdadero; y si se quiere expresar nó como principio sino como regla aplicable, se puede convertir en esta otra: «la evidencia es seguro criterio de verdad.»\"},{\"heading\":false,\"text\":\"[220.] No se crea que el análisis precedente tenga por único objeto la transformacion indicada; bien que en estas materias la claridad y la precision deben ser llevadas al mas alto punto posible, no obstante me hubiera abstenido de entrar en semejantes consideraciones si solo me hubiese propuesto lograr una innovacion que en la práctica puede producir muy escaso resultado; lo mismo se expresa de un modo que de otro, quien no entienda las primeras fórmulas no entenderá la última. Pero no era esta innovacion mi objeto principal; sino el manifestar la confusion de ideas que hay en este punto cuando se examina si el principio que contiene la legitimidad del criterio de la evidencia debe ser considerado ó nó como fundamental y preferido al de contradiccion y al de Descartes.\"},{\"heading\":false,\"text\":\"[221.] Comienzo por asentar una proposicion que parecerá la mas extraña paradoja, pero que está muy lejos de serlo. _El principio de la evidencia no es evidente._\"},{\"heading\":false,\"text\":\"Demostracion. Este principio puesto en forma mas sencilla es el que sigue. Lo evidente es verdadero. Yo digo que esta proposicion no es evidente. ¿Cuándo es evidente una proposicion? cuando en la idea del sujeto vemos el predicado; esto no sucede aquí. Evidente es lo mismo que visto con claridad, que ofrecido al entendimiento de una manera muy luminosa. Verdadero es lo mismo que conformidad de la idea con el objeto. Pregunto ahora ¿por mas que se analice esta idea: «visto con claridad» se puede descubrir esta otra, «conforme al objeto?» nó. Se da aquí un salto inmenso, se pasa de la subjetividad á la objetividad, se afirma que las condiciones subjetivas son el reflejo de las objetivas, se hace el tránsito de la idea á su objeto, tránsito que constituye el problema mas trascendental, mas difícil, mas oscuro de la filosofía. Vea pues el lector si he dicho con fundamento que no era una paradoja esta asercion: El principio de la evidencia no es evidente.\"},{\"heading\":false,\"text\":\"[222.] ¿Qué diremos pues de esta proposicion: lo evidente es verdadero? hélo aquí. No es un axioma porque el predicado no está contenido en la idea del sujeto; no es una proposicion demostrable porque toda demostracion estriba en principios evidentes y consiste en deducir de los mismos una consecuencia evidentemente enlazada con ellos; lo que no puede tener lugar si no se presupone la legitimidad de la evidencia, es decir, lo mismo que es objeto de la demostracion. Al comenzar el raciocinio se podria preguntar desde luego, ¿cómo es conocido el principio en que se le quiere fundar? ¿cómo se sabe que sea verdadero? ¿por la evidencia? recuérdese que se trata de probar que lo evidente es verdadero, y por tanto hay una peticion de principio. La verdad de las leyes lógicas á que debe conformarse todo raciocinio, es conocida solo por evidencia: luego si no se supone que lo evidente es verdadero, no se puede ni raciocinar siquiera.\"},{\"heading\":false,\"text\":\"[223.] Tenemos pues que el principio de la evidencia no puede apoyarse en otro, y por consiguiente reune el primer carácter de principio fundamental. Cayendo él caen tambien todos los demás, incluso el de contradiccion, que como todos, no es conocido sino por evidencia; este es otro de los caractéres del principio fundamental. Veamos sí reune el tercero, á saber, que con su auxilio se pueda reducir á quien niegue los demás.\"},{\"heading\":false,\"text\":\"Difícil es encontrar quien niegue el principio de contradiccion y admita el de evidencia; sin embargo haciendo esta suposicion extravagante, si algun principio pudiera servir para el caso seria este sin duda, porque la cuestion estaria reducida á si confesaria que los principios son para él evidentes; si no lo son, su entendimiento es diferente del de los demás hombres; si lo son, el argumento que se le hace es concluyente. Segun V. confiesa lo evidente es verdadero; tal ó cual principio es evidente para V., luego es verdadero. Las premisas son admitidas por él mismo; la legitimidad de la consecuencia es evidente, y por tanto debe reconocerla tambien, ya que por regla general admite el criterio de la evidencia.\"},{\"heading\":false,\"text\":\"[224.] ¿De qué nacen las extrañezas que hemos notado en este principio? No es evidente, ni es demostrable; es necesario para todos los demás, y con su auxilio se puede reducir á quien los niegue; ¿de dónde semejante extrañeza? de un orígen muy sencillo. Es que el principio de la evidencia no expresa ninguna verdad objetiva, y por consiguiente no es demostrable; no es un simple hecho de conciencia porque expresa la relacion del sujeto al objeto y por consiguiente no puede limitarse á lo puramente subjetivo; es una proposicion que conocemos por acto reflejo y que expresa la ley primitiva de todos nuestros conocimientos objetivos. Estos se fundan en la evidencia; así lo experimentamos; pero cuando el espíritu se pregunta ¿por qué debes fiarte de la evidencia? no puede responder otra cosa sino que lo evidente es verdadero. ¿En qué funda esta proposicion? ordinariamente en nada: se conforma á la misma sin haber pensado nunca en ella; pero si se empeña en reflexionar encuentra tres motivos para asentir á la misma. Primero: un irresistible instinto de la naturaleza. Segundo: el ver que no admitiendo la legitimidad del criterio de la evidencia, se hunden todos sus, conocimientos y le es imposible pensar. Tercero: el notar que admitiendo este criterio todo se pone en órden en la inteligencia, que en vez de un caos halla un universo ideal con trabazon admirable, y se siente con los medios necesarios para raciocinar y construir un edificio científico con respecto al universo real del que tiene conocimiento por la experiencia (XXII).\"}]},{\"title\":\"CAPÍTULO XXIII\",\"blocks\":[{\"heading\":false,\"text\":\"CRITERIO DE LA CONCIENCIA.\"},{\"heading\":false,\"text\":\"[225.] Apreciado el mérito de los tres principios, de conciencia, de contradiccion y de evidencia, con respecto á la dignidad de principio fundamental, vamos ahora á examinar el valor intrínseco de los diferentes criterios. Para esto nos suministra mucha luz la doctrina de los capítulos anteriores, de la cual son los siguientes un desarrollo y complemento. Comencemos por la conciencia ó sentido íntimo.\"},{\"heading\":false,\"text\":\"El testimonio de la conciencia ó del sentido íntimo, comprende todos los fenómenos que activa ó pasivamente se realizan en nuestra alma. Por su naturaleza, es puramente subjetivo; de modo que considerado en sí mismo, separadamente del instinto intelectual y de la luz de la evidencia, nada atestigua con respecto á los objetos. Por él sabemos lo que experimentamos, nó lo que es; percibimos el fenómeno, nó la realidad; él nos autoriza á decir: me _parece_ tal cosa; pero nó, _es_ tal cosa.\"},{\"heading\":false,\"text\":\"La transicion del sujeto al objeto, de la idea representante á la cosa representada, de la impresion á la causa imprimente, pertenece á otros criterios: la conciencia se limita á lo interior, ó por mejor decir á ella misma, que no es mas que un hecho de nuestra alma.\"},{\"heading\":false,\"text\":\"[226.] Conviene distinguir entre la conciencia directa y la refleja; aquella acompaña á todo fenómeno interno, esta nó; aquella es natural, esta es filosófica; aquella prescinde de los actos de la razon, esta es uno de estos actos.\"},{\"heading\":false,\"text\":\"La conciencia directa es la presencia misma del fenómeno al espíritu, ya sea una sensacion, ya una idea, ya un acto ó impresion cualquiera, en el órden intelectual ó moral.\"},{\"heading\":false,\"text\":\"Por esta definicion se echa de ver que la conciencia directa acompaña á todo ejercicio de las facultades de nuestra alma, activo ó pasivo. Decir que estos fenómenos existen en el alma y no están presentes á ella, es una contradiccion.\"},{\"heading\":false,\"text\":\"Estos fenómenos no son modificaciones como las que se verifican en las cosas insensibles; se trata de modificaciones vivas por decirlo así, en un ser vivo tambien: en la idea de las mismas está contenida su presencia al espíritu.\"},{\"heading\":false,\"text\":\"Es imposible sentir sin que la sensacion se experimente: porque quien dice sentir, dice experimentar la sensacion; esta experiencia es la presencia misma: una sensacion experimentada es una sensacion presente.\"},{\"heading\":false,\"text\":\"El pensamiento es por su esencia una representacion, la que no puede existir ni aun concebirse sin la presencia; el nombre mismo lo está indicando; y la idea que le unimos confirma el significado de la palabra. Cuando de representacion hablamos, entendemos que hay algun objeto real ó imaginario, que mediata ó inmediatamente se ofrece á un sujeto: hay pues presencia en toda representacion, y por consiguiente en todo pensamiento.\"},{\"heading\":false,\"text\":\"Si de lo pasivo como son las sensaciones y representaciones, pasamos á lo activo, es decir, á los fenómenos en que el alma desenvuelve libremente su fuerza en el órden intelectual ó moral, _combinando_ ó _queriendo_, la presencia es, si cabe, mas evidente. El ser que obra de este modo no obedece á un impulso natural, sino á motivos que él se propone, y á que puede atender ó dejar de atender: combinar intelectualmente, ejercer actos de voluntad, sin que ni lo primero ni lo segundo estén presentes al alma, son afirmaciones contradictorias.\"},{\"heading\":false,\"text\":\"[227.] La conciencia refleja, que los franceses suelen llamar apercepcion, del verbo _s\'apercevoir_, apercibirse, que entre ellos puede significar percepcion de la percepcion, es el acto con que el espíritu conoce explícitamente algun fenómeno que en él se realiza. En la actualidad oigo ruido; la simple sensacion presente á mi espíritu afectándole, constituye lo que he llamado conciencia directa; pero si á mas de oir me apercibo (permítaseme el galicismo) de que oigo, entonces no solo oigo sino que pienso que oigo: esto es lo que llamo conciencia refleja.\"},{\"heading\":false,\"text\":\"[228.] Claro es por el ejemplo que se acaba de aducir, que la conciencia directa y la refleja son no solo distintas, sino separables; puedo oir sin pensar que oigo, y esto se verifica infinitas veces.\"},{\"heading\":false,\"text\":\"[229.] El comun de los hombres tiene poca conciencia refleja y la mayor fuerza intelectual es en sentido directo. Este hecho ideológico se enlaza con verdades morales de la mayor importancia. El espíritu humano no ha nacido para contemplarse á sí propio, para pensar que piensa; los afectos no le han sido concedidos para objetos de reflexion, sino como impulsos que le llevan á donde es llamado; el objeto principal de su inteligencia y de su amor es el ser infinito así en esta vida como en la otra. El culto de sí propio es una aberracion del orgullo cuya pena son las tinieblas.\"},{\"heading\":false,\"text\":\"[230.] Los grandes adelantos científicos son todos con relacion á los objetos, nó al sujeto. Las ciencias exactas, las naturales y tambien las morales, no han nacido de la reflexion sobre el _yo_, sino del conocimiento de los objetos y de sus relaciones. Aun las ciencias metafísicas, en lo que tienen de mas sólido, que es lo ontológico, cosmológico y teológico, son puramente objetivas; la ideología y psicología que versan sobre el sujeto, se resienten ya de la oscuridad inherente á todo lo subjetivo; la ideología apenas sale de los límites de la pura observacion de los fenómenos internos, observacion que para decirlo de paso suele ser escasa y muy mal hecha, se pierde en vanas cavilaciones; y la misma psicología, ¿qué es lo que tiene verdaderamente demostrado sino la simplicidad del espíritu, consecuencia precisa de la unidad de conciencia? En todo lo demás hace lo mismo que la ideología, y hasta cierto punto se confunde con ella; observa fenómenos que luego deslinda y clasifica bien ó mal, sin que acierte á explicar su misteriosa naturaleza.\"},{\"heading\":false,\"text\":\"[231.] El sentido íntimo ó la conciencia, es el fundamento de los demás criterios, nó como una proposicion que les sirva de apoyo, sino como un hecho que es para todos ellos una condicion indispensable.\"},{\"heading\":false,\"text\":\"[232.] La conciencia nos dice que vemos la idea de una cosa contenida en la de otra; hasta aquí no hay mas que apariencia: la fórmula en que podria expresarse el testimonio seria: _me parece_, designándose un fenómeno puramente subjetivo. Pero este fenómeno anda acompañado de un instinto intelectual, de un irresistible impulso de la naturaleza, el cual nos hace asentir á la verdad de la relacion, no solo en cuanto está en nosotros, sino tambien en cuanto se halla fuera de nosotros, en el órden puramente objetivo, ya sea en la esfera de la realidad, ó de la posibilidad. Así se explica cómo la evidencia se funda en la conciencia, nó identificándose con ella, sino estribando sobre la misma como en un hecho imprescindible, pero encerrando algo mas: á saber, el instinto intelectual que nos hace creer verdadero lo evidente.\"},{\"heading\":false,\"text\":\"[233.] La sensacion considerada en sí misma, es un hecho de pura conciencia, pues que es inmanente; lejos de que sea un acto por el cual el espíritu salga de sí trasladándose al objeto, debe mas bien ser mirada como una pasion que como una accion; lo que está acorde con el lenguaje comun, que le da el significado del ejercicio de una facultad pasiva mas bien que activa. Sin embargo, sobre este puro hecho de conciencia se funda en algun modo lo que se llama el testimonio de los sentidos, y por consiguiente todo el conocimiento del mundo externo y de sus propiedades y relaciones.\"},{\"heading\":false,\"text\":\"En la sensacion de ver el sol, hay dos cosas: primera: la sensacion misma; es decir, esta representacion que experimento en mi, y que llamo _ver_; segunda: la correspondencia de esta sensacion con un objeto externo que llamo sol. Es evidente que estas son cosas muy distintas, y sin embargo las hacemos andar siempre juntas. La conciencia es ciertamente la primera base para formar el juicio, pero no es suficiente para él; ella en sí, atestigua lo que se siente, nó lo que esto es. ¿Cómo se completa el juicio? por medio de un instinto natural que nos hace objetivar las sensaciones, es decir, nos hace creer en un objeto externo correspondiente al fenómeno interno. Hé aquí cómo el testimonio de los sentidos se funda en algun modo sobre la conciencia; pero no nace de ella sola, sino que ha menester el instinto natural que hace formar con toda seguridad el juicio.\"},{\"heading\":false,\"text\":\"[234.] Aquí es de notar que el testimonio de los sentidos, aun en la parte que encierra de intelectual, en cuanto se juzga que á la sensacion le corresponde un objeto externo, nada tiene que ver con la evidencia. En la idea de la sensacion como puramente subjetiva, no se encierra la idea de la existencia ó posibilidad de un objeto externo: condicion indispensable para que el criterio de la evidencia pueda tener lugar. Esto, á mas de ser claro de suyo, se confirma con la experiencia de todos los dias. La representacion de lo externo considerada subjetivamente, como puro fenómeno de nuestra alma, la tenemos continuamente sin que le correspondan objetos reales: mas ó menos clara, en la sola imaginacion durante la vigilia; viva, vivísima, hasta producir una ilusion completa, en el estado de sueño.\"},{\"heading\":false,\"text\":\"[235.] Con la exposicion que precede podemos determinar fijamente el valor y la extension del criterio de la conciencia, lo que haré en las siguientes proposiciones, advirtiendo que en todas ellas me refiero á la conciencia directa.\"},{\"heading\":false,\"text\":\"PROPOSICION PRIMERA.\"},{\"heading\":false,\"text\":\"El testimonio de la conciencia se extiende á todos los fenómenos que se realizan en nuestra alma, considerada como un ser intelectual y sensitivo.\"},{\"heading\":false,\"text\":\"PROPOSICION SEGUNDA.\"},{\"heading\":false,\"text\":\"[236.] Si en nuestra alma existen fenómenos de algun otro órden, es decir, que ella pueda ser modificada en algun modo en facultades no representativas, á estos fenómenos no se extiende el testimonio de la conciencia.\"},{\"heading\":false,\"text\":\"Esta proposicion no la establezco sin fundado motivo. Es posible y además muy probable, que nuestra alma tiene facultades activas de cuyo ejercicio no tiene conciencia: sin esta suposicion parece difícil explicar los misterios de la vida orgánica. El alma está unida al cuerpo, y es para él un principio vital cuya separacion produce la muerte, manifestada en una desorganizacion y descomposicion completas. Esta actividad se ejerce sin conciencia, así en cuanto al modo, como en cuanto á la existencia misma del ejercicio.\"},{\"heading\":false,\"text\":\"Tal vez se pueda objetar que hay en esto una serie de aquellas percepciones confusas de que nos habla Leibnitz en su monadología; tal vez estas percepciones sean tan tenues, tan pálidas por decirlo así, que no dejen rastro en la memoria ni puedan ser objeto de reflexion; pero todo esto son conjeturas, nada mas. Es difícil persuadirse que el feto al encontrarse todavía en el seno de la madre, tenga conciencia de la actividad ejercida para el desarrollo de la organizacion; es difícil persuadirse que aun en los adultos haya conciencia de esa misma actividad productora de la circulacion de la sangre, de la nutricion y demás fenómenos que constituyen la vida. Si estos fenómenos son producidos por el alma, como es cierto, hay en ella un ejercicio de actividad de que, ó no tiene conciencia, ó la tiene tan confusa y tan débil que es como si no la tuviese.\"},{\"heading\":false,\"text\":\"PROPOSICION TERCERA.\"},{\"heading\":false,\"text\":\"[237.] El testimonio de la conciencia considerado en _sí mismo_, se limita de tal modo á lo puramente interno, que _por sí solo_ nada vale para lo externo: ya sea para el criterio de la evidencia, ya para el de los sentidos.\"},{\"heading\":false,\"text\":\"PROPOSICION CUARTA.\"},{\"heading\":false,\"text\":\"El testimonio de la conciencia es fundamento de los demás criterios en cuanto es un hecho que todos ellos han menester, y sin el cual son imposibles.\"},{\"heading\":false,\"text\":\"PROPOSICION QUINTA.\"},{\"heading\":false,\"text\":\"[238.] De la combinacion de la conciencia con el instinto intelectual, nacen todos los demás criterios (XXIII).\"}]},{\"title\":\"CAPÍTULO XXIV\",\"blocks\":[{\"heading\":false,\"text\":\"CRITERIO DE LA EVIDENCIA.\"},{\"heading\":false,\"text\":\"[239.] Hay dos especies de evidencia: inmediata y mediata. Se llama evidencia inmediata, la que solo ha menester la inteligencia de los términos; y mediata, la que necesita raciocinio. Que el todo es mayor que su parte, es evidente con evidencia inmediata; que el cuadrado de la hipotenusa sea igual á la suma de los cuadrados de los catetos, lo sabemos por evidencia mediata, esto es, por raciocinio demostrativo.\"},{\"heading\":false,\"text\":\"[240.] Se dijo mas arriba que uno de los caractéres distintivos de la evidencia era la necesidad y universalidad de su objeto. Este carácter conviene tanto á la evidencia mediata como á la inmediata.\"},{\"heading\":false,\"text\":\"A mas de este carácter existe otro que con mayor razon puede llamarse constitutivo, bien que hay alguna dificultad sobre si comprende ó nó á la evidencia mediata, y es, el que la idea del predicado se halle contenida en la del sujeto. Esta es la nocion esencial mas cumplida del criterio de la evidencia inmediata; por la cual se distingue del de la conciencia y del sentido comun.\"},{\"heading\":false,\"text\":\"He dicho que hay alguna dificultad sobre si este carácter conviene ó nó á la evidencia mediata: con lo cual doy á entender que tambien en la evidencia mediata la idea del predicado podria estar contenida en la del sujeto. Al indicar esto, no es mi ánimo desconocer la diferencia que hay entre los teoremas y los axiomas, sino llamar la atencion sobre una doctrina que me propongo desenvolver al tratar de la evidencia mediata. En el presente capítulo, no me ocuparé de esta cuestion; ó me ceñiré á la evidencia en general, ó trataré tan solo de la mediata.\"},{\"heading\":false,\"text\":\"[241.] La evidencia exige relacion, porque implica comparacion. Cuando el entendimiento no compara, no tiene evidencia, tiene simplemente una percepcion que es un puro hecho de conciencia; por manera que la evidencia no se refiere á la sola percepcion, sino que siempre supone ó produce un juicio.\"},{\"heading\":false,\"text\":\"En todo acto donde hay evidencia se encuentran dos cosas: primera, la pura intuicion de la idea; segunda, la descomposicion de esta idea en varios conceptos, acompañada de la percepcion de las relaciones que estos tienen entre sí. Expliquemos esto con un ejemplo de geometría. El triángulo tiene tres lados: esta es una proposicion evidente, porque en la misma idea de triángulo encuentro los tres lados, y al pensar el triángulo, ya pensaba en algun modo sus tres lados. Si me hubiese limitado á la contemplacion de la simple idea de triángulo, hubiera tenido intuicion de la idea, pero no evidencia, que no principia sino cuando descomponiendo el concepto de triángulo y considerando en él la idea de figura en general, la de lado, y la del número tres, encuentro que todas ellas están ya contenidas en el concepto primitivo: en la clara percepcion de esto, consiste la evidencia.\"},{\"heading\":false,\"text\":\"Tanta verdad es lo que acabo de decir, que la fuerza misma de las cosas obliga al lenguaje comun á ser filosófico. No se dice que una idea es evidente, pero sí un juicio; nadie llama evidente á un término, pero sí á una proposicion. ¿Por qué? porque el término expresa simplemente la idea sin relacion alguna, sin descomposicion en sus conceptos parciales; y por el contrario, la proposicion expresa el juicio, es decir, la afirmacion ó negacion de que un concepto está contenido en otro, lo que en la materia de que se trata, supone la descomposicion del concepto total.\"},{\"heading\":false,\"text\":\"[242.] La evidencia inmediata es la percepcion de la identidad entre varios conceptos, que la fuerza analítica del entendimiento habia separado; esta identidad, combinada en cierto modo con la diversidad, no es una contradiccion como á primera vista pudiera parecer, es una cosa muy natural si se atiende á uno de los hechos mas constantes de nuestra inteligencia, cual es, la facultad de descomponer los conceptos mas simples y de ver relaciones entre cosas idénticas.\"},{\"heading\":false,\"text\":\"¿Qué son todos los axiomas? ¿qué todas las proposiciones que se llaman _per se notæ_? no son mas que expresiones en que se afirma un predicado que pertenece á la esencia del sujeto ó está contenido en su idea. El solo concepto del sujeto incluye ya el predicado; el término que significa al primero, significa tambien al segundo; sin embargo el entendimiento, con una misteriosa fuerza de descomposicion, distingue entre cosas idénticas y luego las compara para volverlas á identificar. Quien dice triángulo, dice figura compuesta de tres lados y tres ángulos; pero el entendimiento puede tomar esta idea y considerar en ella la idea del número tres, la del lado, la del ángulo, y compararlas con el concepto primitivo. En esta distincion no hay engaño, hay solo el ejercicio de la facultad que mira la cosa bajo aspectos diferentes, para venir á parar á la intuicion y afirmacion de la identidad de las mismas cosas que antes habia distinguido.\"},{\"heading\":false,\"text\":\"[243.] La evidencia es una especie de cuenta y razon del entendimiento, por la cual halla en el concepto descompuesto lo mismo que él puso en un principio, ó que le dieron contenido en él. De aquí nace la necesidad y universalidad del objeto de la evidencia, en cuanto y del modo que está expresado por la idea. En esto no caben excepciones: ó un predicado estaba puesto en el concepto primitivo, ó nó; si estaba puesto, allí está, so pena de faltar al principio de contradiccion; ó estaba excluido del concepto ó nó; si ya el concepto mismo le excluia ó le negaba, negado está en fuerza del mismo principio de contradiccion.\"},{\"heading\":false,\"text\":\"Hé aquí cómo de los dos caractéres de la evidencia arriba señalados, es mas fundamental el de que la idea del predicado está contenido en la idea del sujeto. De esto dimanan la necesidad y universalidad: pues que en verificándose la condicion de estar contenida la idea del predicado en la del sujeto, ya es imposible que el predicado no convenga _necesariamente á todos_ los sujetos.\"},{\"heading\":false,\"text\":\"[244.] Hasta ahora no encontramos dificultad, porque se trata de la evidencia considerada subjetivamente, es decir, en cuanto se refiere á los conceptos puros; mas el entendimiento no se para en el concepto sino que se extiende al objeto y dice, no solo que ve la cosa, sino que la cosa es como él la ve. Así el principio de contradiccion mirado en el órden puramente subjetivo, significa que el concepto del ser repugna al del no ser, que le destruye, así como el concepto del no ser destruye el del ser; significa que al esforzarnos en pensar juntamente estas dos cosas, queriéndolas hacer coexistir, se entabla en el fondo de nuestro espíritu una especie de lucha de pensamientos que se anonadan recíprocamente, lucha que el entendimiento está condenado á presenciar sin esperanza de poner la paz entre los contendientes. Si nos limitamos á consignar este fenómeno, nada se nos puede objetar; los experimentamos así y no hay mas cuestion; pero al anunciar el principio queremos anunciar algo mas que la incompatibilidad de los conceptos, trasladamos esta incompatibilidad á las cosas mismas y aseguramos que á esta ley están sometidos no solo nuestros conceptos sino todos los seres reales y posibles. Sea cual fuere el objeto de que se trate, sean cuales fueren las condiciones en que se le suponga existente ó posible, decimos que mientras es, no puede no ser, y que mientras no es, no puede ser. Afirmamos pues la ley de contradiccion no solo para nuestros conceptos, sino para las cosas mismas: el entendimiento aplica á todo la ley que encuentra necesaria para si.\"},{\"heading\":false,\"text\":\"¿Con qué derecho? inconcuso, porque es la ley de la necesidad: ¿con qué razon? con ninguna, porque tocamos al cimiento de la razon: aquí hay para el humano entendimiento el _non plus ultra:_ la filosofía no va mas allá. Sin embargo, no se crea que intente abandonar el campo á los escépticos ó atrincherarme en la necesidad, contento con señalar un hecho de nuestra naturaleza; la cuestion es susceptible de diferentes soluciones, que si no alcanzan á llevarnos mas lejos del _non plus ultra_ de nuestro espíritu, dejan mal parada la causa de los escépticos.\"},{\"heading\":false,\"text\":\"[245.] Preguntar la razon de la legitimidad del criterio de la evidencia, pedir el por qué de esta proposicion «lo evidente es verdadero,» es suscitar la cuestion de la objetividad de las ideas. La diferencia fundamental entre los dogmáticos y los escépticos no está en que estos no admitan los hechos de conciencia; no llega á tanto el mas refinado escepticismo: unos y otros convienen en reconocer la apariencia ó sea el fenómeno puramente subjetivo; la diferencia está en que los dogmáticos fundan en la conciencia la ciencia, y los escépticos sostienen que este es un tránsito ilegítimo, que es necesario desesperar de la ciencia y limitarse á la mera conciencia.\"},{\"heading\":false,\"text\":\"Segun esta doctrina las ideas son vanas formas de nuestro entendimiento que no significan nada, ni pueden conducir á nada; no obstante de que entretienen á nuestra inteligencia ofreciéndole un campo inmenso para sus combinaciones, el mundo que le presentan es de pura ilusion que para nada puede servir en la realidad. Al contemplar estas formas enteramente vacías, el entendimiento es juguete de visiones fantásticas de cuyo conjunto resulta el espectáculo que ora nos parece de realidad ora de posibilidad, no obstante de que ó es un puro nada, ó si es algo, no puede cerciorarnos jamás de la realidad que posee.\"},{\"heading\":false,\"text\":\"[246.] Difícil es combatir al escepticismo colocado en este terreno: situado fuera de los dominios de la razon. De todos le será lícito apelar, ya que comienza recusando al juez á título de incompetencia. Sin embargo, estos escépticos ya que admiten la conciencia, justo será que la defiendan contra quien se la intente arrebatar: pues bien, yo creo que negada la objetividad de las ideas se anonada no solo la ciencia sino tambien la conciencia; y que se puede acusar de inconsecuentes á los escépticos, porque al paso que niegan la objetividad de ciertas ideas admiten la de otras. La conciencia propiamente dicha, no puede existir si esta objetividad se destruye absolutamente. Ruego al lector me siga con atencion en un breve pero severo análisis de los hechos de conciencia en sus relaciones con la objetividad de las ideas (XXIV).\"}]},{\"title\":\"CAPÍTULO XXV\",\"blocks\":[{\"heading\":false,\"text\":\"VALOR OBJETIVO DE LAS IDEAS.\"},{\"heading\":false,\"text\":\"[247.] La transicion del sujeto al objeto, ó de la apariencia subjetiva á la realidad objetiva, es el problema que atormenta á la filosofía fundamental. El sentido íntimo no nos permite dudar de que ciertas cosas nos _parecen_ de tal manera, pero ¿_son_ en realidad lo que nos parecen? ¿Cómo nos consta esto? Esa conformidad de la idea con el objeto, ¿cómo se nos asegura?\"},{\"heading\":false,\"text\":\"La cuestion no se refiere únicamente á las sensaciones, se extiende á las ideas puramente intelectuales, aun á las que están inundadas de esa luz interior que llamamos evidencia. «Lo que veo evidentemente en la idea de una cosa, es como yo lo veo» han dicho los filósofos, y con ellos está la humanidad entera. Nadie duda de aquello que se le ofrece como verdadero evidentemente. Pero, ¿cómo se prueba que la evidencia sea un criterio legítimo de verdad?\"},{\"heading\":false,\"text\":\"[248.] «Dios es veraz, dice Descartes; él no ha podido engañarnos; no ha podido complacerse en hacernos víctimas de ilusiones perpetuas.» Todo esto es verdad; pero ¿cómo sabemos, dirá el escéptico, que Dios es veraz, y aun que existe? Si lo fundamos en la idea misma de un ser infinitamente perfecto, como lo funda el citado filósofo, nos quedamos con la misma dificultad sobre la correspondencia del objeto con la idea. Si la demostracion de la veracidad y de la existencia de Dios la sacamos de las ideas de los seres contingentes y necesarios, de efectos y causas, de órden y de inteligencia, tropezamos otra vez con el mismo obstáculo, y todavía no sabemos cómo hacer el tránsito de la idea al objeto.\"},{\"heading\":false,\"text\":\"Cavílese cuanto se quiera, nunca saldremos de este círculo, siempre volveremos al mismo punto. El espíritu no puede pensar fuera de sí mismo; lo que conoce, lo conoce por medio de sus ideas; si estas le engañan, carece de medios para rectificarse. Toda rectificacion, toda prueba, deberia emplear ideas, que á su vez necesitarian de nueva prueba y rectificacion.\"},{\"heading\":false,\"text\":\"[249.] En muchos libros de filosofía se ponderan las ilusiones de los sentidos, y la dificultad de asegurarnos de la realidad sensible resolviendo la siguiente cuestion: «así lo siento, pero ¿es como lo siento?» En estos mismos libros se habla luego del órden de las ideas con seguridad igual á la desconfianza que se manifiesta sobre el órden sensible; este proceder no parece muy lógico: porque los fenómenos relativos á los sentidos, pueden examinarse á la luz de la razon, para ver hasta qué punto concuerdan con ella; pero ¿cuál será la piedra de toque de los fenómenos de la razon misma? Si en lo sensible hay dificultad, la hay tambien en lo intelectual; y tanto mas grave, cuanto afecta la base misma de todos los conocimientos, inclusos los que se refieren á las sensaciones.\"},{\"heading\":false,\"text\":\"Si dudamos de la existencia del mundo exterior que nos presentan los sentidos, podremos apelar al enlace de las sensaciones con causas que no están en nosotros, y así sacar por demostracion las relaciones de las apariencias con la realidad; mas para esto necesitamos las ideas de causa y efecto, necesitamos la verdad, algunos principios generales, como por ejemplo que nada se produce á sí mismo, y otros semejantes, y sin ellos no podemos dar un paso.\"},{\"heading\":false,\"text\":\"[250.] No creo que el hombre pueda señalar una razon satisfactoria en pro de la veracidad del criterio de la evidencia; no obstante de que le es imposible dejar de rendirse á ella. El enlace pues de la evidencia con la realidad, y por tanto el tránsito de la idea al objeto, es un hecho primitivo de nuestra naturaleza, una ley necesaria de nuestro entendimiento, es el fundamento de todo lo que hay en él, fundamento que á su vez no estriba ni estribar puede en otra cosa que en Dios criador de nuestro espíritu.\"},{\"heading\":false,\"text\":\"[251.] Es de notar sin embargo, la contradiccion en que incurren los filósofos que dicen: «yo no puedo dudar de lo que es subjetivo, esto es, de lo que me afecta á mí mismo, de lo que siento en mí, pero no tengo derecho á salir de mi mismo, y afirmar que lo que pienso es en realidad como lo pienso.» ¿Sabes que sientes, que piensas, que tienes en ti tal ó cual apariencia? ¿Lo puedes probar? Es evidente que nó. Lo que haces es ceder á un hecho, á una necesidad íntima que te fuerza á creer que piensas, que sientes, que te parece tal ó cual cosa; pues bien, igual necesidad hay en el enlace del objeto con la idea, igual necesidad te fuerza á _creer_ que lo que evidentemente te parece que es de tal ó cual manera, es en efecto de la misma manera; ninguno de los dos casos admite demostracion, en ambos hay indeclinable necesidad; ¿dónde está pues la filosofía cuando tanta diferencia se quiere establecer entre cosas que no admiten ninguna?\"},{\"heading\":false,\"text\":\"Fichte ha dicho: «Es imposible explicar de una manera precisa cómo un pensador ha podido salir jamás del _yo_» (Doct. de la Ciencia 1. Par. § 3.), y con igual derecho se le podria decir á él que no se concibe cómo ha podido levantar su sistema sobre el _yo_. ¿A qué apela? á un hecho de conciencia; es decir, á una necesidad. Y el asenso á la evidencia, la certeza de que á la apariencia corresponde la realidad, ¿no es tambien una necesidad? ¿En qué funda Fichte su sistema del _yo_ y del _no yo_? Basta leer su obra, para ver que no estriba sino en consideraciones que suponen un valor á ciertas ideas, una verdad á ciertos juicios. Sin esto es imposible hablar ni pensar; y hasta él propio lo reconoce cuando al comenzar sus investigaciones sobre el principio de nuestros conocimientos dice lo que ya tengo copiado mas arriba (§ 8). Allí confiesa que no puede dar un paso sin confiarse á todas las leyes de la lógica general, que no están _todavía demostradas, y que se suponen tácitamente admitidas_. ¿Y qué son esas leyes, sin verdad objetiva? Qué son sin el valor de las ideas, sin la correspondencia de estas con los objetos? Es un círculo, dice bien Fichte; y de él no sale este filósofo, como no han salido los demás.\"},{\"heading\":false,\"text\":\"[252.] El quitar á las ideas su valor objetivo, el reducirlas á meros fenómenos subjetivos, el no ceder á esa necesidad íntima que nos obliga á admitir la correspondencia del _yo_ con los objetos, arruina la conciencia misma del _yo_. Esto es lo que se deberia haber visto, y lo que creo poder demostrar hasta la última evidencia.\"},{\"heading\":false,\"text\":\"[253.] Tengo conciencia de mí mismo. Prescindo ahora de lo que siento, de lo que soy; pero sé que siento, y que soy. Esta experiencia es para mí tan clara, tan viva, que no puedo resistir á la verdad de lo que ella me dice. Pero ese _yo_ no es solo el _yo_ de este instante, es tambien el _yo_ de ayer, y de todo el tiempo anterior de que tengo conciencia. Yo soy el mismo que era ayer; yo soy el mismo en quien se verifica esa sucesion de fenómenos; el mismo á quien se presentan esa variedad de apariencias. La conciencia del _yo_, encierra pues la identidad de un ser, en distintos tiempos, en situaciones varias, con diferentes ideas, con diversas afecciones: la identidad de un ser que _dura_, que es el mismo, á pesar de las mudanzas que en él se suceden. Si esa duracion de identidad se rompe; si no estoy seguro que soy el mismo _yo_ ahora que era antes, se destruye la conciencia del _yo_. Existirá una serie de hechos inconexos, de conciencias aisladas; mas nó esa conciencia íntima que ahora experimento. Esto es indudable; esto lo siente todo hombre en sí mismo; esto para nadie admite discusion ni prueba, para nadie las necesita. En el momento en que esa conciencia de identidad nos faltase, nos anonadaríamos á nuestros ojos; fuéramos lo que fuésemos en la realidad, para nosotros no seríamos nada. ¿Qué es la conciencia de un ser, formada de una serie de conciencias, sin trabazon, sin relacion entre sí? Es un ser que se revela sucesivamente á sí propio; pero nó como él mismo, sino como un ser nuevo; un ser que nace y muere, y muere y nace á sus ojos, sin que él propio sepa que el que nace es el que murió, ni el que muere el que nació: una luz que se enciende y se extingue, y vuelve á encenderse y á extinguirse otra vez, sin que se sepa que es la misma.\"},{\"heading\":false,\"text\":\"[254.] Esta conciencia la arruinan completamente los que niegan el enlace de la idea con el objeto. Demostracion. En el instante A, yo no tengo otra presencia subjetiva de mis actos, que el acto mismo que en aquel instante estoy ejerciendo: luego no puedo cerciorarme de haber tenido los anteriores, sino en cuanto están representados en la idea actual; luego hay un enlace entre esta y su objeto. Luego ateniéndonos simplemente á los fenómenos de la conciencia, á la simple conciencia del _yo_, encontramos que por indeclinable necesidad atribuimos á las ideas un valor objetivo, á los juicios una verdad objetiva.\"},{\"heading\":false,\"text\":\"[255.] Sin esta verdad objetiva, es imposible todo recuerdo cierto, hasta de los fenómenos interiores, y por consiguiente, todo raciocinio, todo juicio, todo pensamiento.\"},{\"heading\":false,\"text\":\"El recuerdo es de actos pasados: cuando los recordamos ya no son; pues si fueran, no habria recuerdo con respecto á ellos, sino conciencia de presente. Aun cuando en el acto de recordarlos tengamos otros actos semejantes, estos no son los mismos; pues en la idea de recuerdo entra siempre la de tiempo pasado. Luego, de ellos no puede haber mas certeza que por el enlace que tienen con el acto presente, por su correspondencia con la idea que nos los ofrece.\"},{\"heading\":false,\"text\":\"[256.] He dicho que en faltando la certeza de la verdad objetiva en los fenómenos interiores, era imposible todo raciocinio. En efecto, todo raciocinio supone una _sucesion_ de actos: cuando el uno existe en el espíritu, ya no existe el otro: luego hay necesidad de pequeños recuerdos continuos, para que la cadena no se quebrante: es así que sin esta cadena no hay raciocinio, y sin recuerdo no hay esa cadena, y sin verdad objetiva no hay recuerdo cierto; luego sin verdad objetiva no hay raciocinio.\"},{\"heading\":false,\"text\":\"[257.] Tambien parecen imposibles todos los juicios. Estos son de dos clases: los que no necesitan demostracion, ó los que la necesitan. Los que han menester demostracion serán imposibles, porque no hay demostracion sin raciocinio, y este en tal caso seria imposible tambien. En cuanto á los que no la han menester porque brillan con evidencia inmediata, serian imposibles todos los que no se refiriesen al acto presente del alma, en el instante mismo en que se emitiera el juicio. Luego no habria mas juicio que el del acto presente: es decir, la conciencia del momento sin relacion con nada de lo anterior. Pero lo curioso es que aun con respecto á los actos de conciencia, este juicio seria poco menos que imposible: porque cuando formamos el juicio sobre el acto de conciencia, no es con este, sino con un acto reflejo: esta reflexion implica sucesion: y lo sucesivo no es conocido con certeza si no hay verdad objetiva.\"},{\"heading\":false,\"text\":\"Es muy dudoso que ni aun fueran posibles los juicios de evidencia inmediata. Ellos, como se ha explicado en el capítulo anterior, suponen la relacion de los conceptos parciales en que se ha descompuesto el total: ¿cómo se descompone sin sucesion? Si hay sucesion hay recuerdo, si hay recuerdo no hay presencia inmediata de lo recordado; es necesaria por consiguiente la objetividad de la idea representante con relacion á la cosa recordada.\"},{\"heading\":false,\"text\":\"[258.] Semejantes consecuencias espantan, pero son indeclinables: si quitamos la verdad objetiva, desaparece todo pensamiento razonado. Este encierra cierta continuidad de actos correspondientes á diversos instantes: si esta continuidad se rompe, el pensamiento humano deja de ser lo que es: deja de existir como _razon_: es una serie de actos sin conexion de ninguna especie y que á nada pueden conducir. En tal caso desaparece toda expresion, toda palabra: nada tiene un valor seguro: todo se hunde, así en el órden intelectual y moral como en el material, y el hombre queda hasta sin el consuelo de poseerse á sí mismo; se desvanece en sus propias manos cual vana sombra.\"},{\"heading\":false,\"text\":\"[259.] Las sensaciones podrán existir como serie inconexa tambien; pero no habrá de ellas ningun recuerdo cierto, pues falta la verdad objetiva: y las sensaciones pasadas no existen sino como pasadas, y por tanto como simples objetos.\"},{\"heading\":false,\"text\":\"Toda reflexion intelectual sobre ellas será imposible; porque la reflexion no es la sensacion: esto es un objeto de aquella, mas nó ella misma. Así el rudo tiene la misma sensacion que el filósofo, pero nó la reflexion sobre ella. Mil veces sentimos sin reflexionar que sentimos. La conciencia sensible, es muy diferente de la intelectual: la primera es la simple presencia de la sensacion, la sensacion misma: la segunda es el acto del entendimiento que se ocupa de la sensacion.\"},{\"heading\":false,\"text\":\"[260.] Esta distincion se encuentra tambien en todos los actos puramente intelectuales: la reflexion sobre el acto no es el acto mismo. El uno es objeto del otro: no se identifican, ya que con frecuencia se encuentran separados; si no hubiese pues verdad objetiva la reflexion seria imposible.\"},{\"heading\":false,\"text\":\"[261.] Es difícil tambien de comprender cómo seria posible ningun acto de la conciencia del yo, aun de presente. Ya hemos visto como desaparece el _yo_, en rompiéndose la serie de los recuerdos, pero hay además, que sin verdad objetiva no os posible concebir el _yo_ ni aun por un momento. El _yo_ pensante, no conoce al _yo_ pensado, sino como objeto. Sea que lo _sienta_, sea que lo _conozca_, para darse cuenta á sí mismo de sí mismo necesita reflexionar sobre sí mismo, tomarse á sí mismo por objeto. Y en no habiendo verdad objetiva, no se concibe que ningun objeto pueda tener ningun valor.\"},{\"heading\":false,\"text\":\"De esto se infiere, que los que atacan la objetividad, atacan una ley fundamental de nuestro espíritu, destruyen el pensamiento, y arruinan hasta la conciencia, hasta todo lo subjetivo, que les servía de base.\"},{\"heading\":false,\"text\":\"[262.] Contra la certeza objetiva suele argumentarse fundándose en los errores á que ella nos induce. El delirante cree ver objetos que no existen; el loco cree firmemente en la verdad de sus pensamientos desconcertados: ¿por qué lo que en un caso nos engaña, no podria engañarnos en otros, ó en todos? Un criterio que alguna vez flaquea, ¿podrá pasar por seguro? ¿Por qué no atenernos á lo puramente subjetivo? El delirante, el maniático, el loco se engañan en el objeto, mas nó en el sujeto: aunque no sea verdad lo que ellos piensan, es bien cierto y verdadero que ellos lo piensan.\"},{\"heading\":false,\"text\":\"Esta objecion es especiosa; pero deja en pie todas las dificultades en contra del sistema á cuyo favor se aduce; y por otra parte no carece de respuesta, en cuanto tiende á debilitar la verdad objetiva.\"},{\"heading\":false,\"text\":\"El delirante, el maniático, el loco tienen tambien recuerdos de cosas que no han existido nunca. Esos recuerdos no se refieran tan solo á lo exterior, sino tambien ú sus actos interiores. El demente que se llama rey, se acuerda de lo que pensó, de lo que sintió, cuando lo coronaron, cuando le destronaron, y de una larga historia de semejantes actos: y sin embargo estos fenómenos intelectuales no existieron: y sea como fuere, tantos recuerdos se los puede producir él mismo. Tenemos pues que el criterio con respecto á la memoria, flaquea en este caso: y por lo mismo no podrá servir en ninguno. Luego, aun cuando mas arriba no hubiésemos demostrado que sin verdad objetiva no hay recuerdo ni aun de lo interior, el argumento de los adversarios bastaria para arruinarlos todos. Esta objecion, si algo probase, confirmaria todo lo que se ha dicho para demostrar que sin objetividad no hay conciencia propiamente dicha, lo cual no lo admiten los adversarios.\"},{\"heading\":false,\"text\":\"[263.] Además: desde luego salta á los ojos lo que puede valer en el tribunal de la razon, lo que comienza por apoyarse en la locura. Todo esto prueba á lo mas, la debilidad de nuestra naturaleza; la posibilidad de que en algunos desgraciados se trastorne el órden establecido para la humanidad; que la regla de la verdad en el hombre, como que existe en una criatura tan débil, admite algunas excepciones; pero estas son conocidas, porque tienen caractéres marcados. La excepcion no destruye la regla, sino que la confirma (XXV).\"}]},{\"title\":\"CAPÍTULO XXVI\",\"blocks\":[{\"heading\":false,\"text\":\"SI TODOS LOS CONOCIMIENTOS SE REDUCEN Á LA PERCEPCION DE LA IDENTIDAD.\"},{\"heading\":false,\"text\":\"[264.] La evidencia inmediata tiene por objeto las verdades que el entendimiento alcanza con toda claridad, y á que asiente con absoluta certeza sin que intervenga ningun _medio_, como lo dice el mismo nombre. Estas verdades se enuncian en las proposiciones llamadas _per se notæ_, primeros principios ó axiomas; en las cuales basta entender el sentido de los términos, para ver que el predicado está contenido en la idea del sujeto. Las proposiciones de esta clase son pocas en todas las ciencias: la mayor parte de nuestros conocimientos es fruto de raciocinio, el cual procede por evidencia mediata. En la geometría son en muy reducido número las proposiciones que no han menester ser demostradas sino explicadas; el cuerpo de la ciencia geométrica con las dimensiones colosales que tiene en la actualidad, ha dimanado del raciocinio: aun en las obras mas extensas los axiomas ocupan pocas páginas; lo demás está formado de teoremas, esto es, de proposiciones que no siendo evidentes por sí mismas, necesitan demostracion. Lo mismo se verifica en todas las ciencias.\"},{\"heading\":false,\"text\":\"[265.] Como en los axiomas percibe el entendimiento la identidad del sujeto con el predicado, viendo por intuicion que la idea de este se halla contenida en la de aquel, surge aquí una cuestion filosófica sumamente grave, que puede ser muy difícil y dar pie á extrañas controversias, si no se tiene cuidado de colocarla en su verdadero terreno. ¿Todo conocimiento humano se reduce á la simple percepcion de la identidad? y su fórmula general, ¿podria ser la siguiente: A es A, ó bien una cosa es ella misma? Filósofos de nota opinan por la afirmativa, otros sienten lo contrario. Yo creo que hay en esto cierta confusion de ideas, relativa mas bien al estado de la cuestion que no al fondo de ella misma. Conduce mucho á resolverla con acierto el formarse ideas bien claras y exactas de lo que es el juicio, y la relacion que por él se afirma ó se niega.\"},{\"heading\":false,\"text\":\"[266.] En todo juicio hay percepcion de identidad ó de no identidad segun es afirmativo ó negativo. El verbo _es_ no expresa union de predicado con el sujeto, sino identidad; cuando va acompañado de la negacion diciéndose _no es_, se expresa simplemente la no identidad, prescindiendo de la union ó separacion. Esto es tan verdadero y exacto, que en cosas realmente unidas no cabe juicio afirmativo por solo faltarles la identidad; en tales casos, para poder afirmar, es preciso expresar el predicado en concreto, esto es, envolviendo en él de algun modo la idea del sujeto mismo; por manera que la misma propiedad que en concreto debiera ser afirmada, no puede serle en abstracto, antes bien debe ser negada. Así se puede decir: el hombre es racional; pero nó, el hombre es la racionalidad; el cuerpo es extenso; pero nó, el cuerpo es la extension; el papel es blanco; pero nó el papel es la blancura. Y esto ¿por qué? ¿es que la racionalidad no está en el hombre, que la extension no se halle unida al cuerpo y la blancura al papel? nó ciertamente; pero, aunque la racionalidad esté en el hombre y la extension en el cuerpo y la blancura en el papel, basta que no percibamos identidad entre los predicados y los sujetos para que la afirmacion no pueda tener cabida: por el contrario, lo que la tiene es la negacion, á pesar de la union: así se podrá decir: el hombre no es la racionalidad; el cuerpo no es la extension; el papel no es la blancura.\"},{\"heading\":false,\"text\":\"He dicho que para salvar la expresion de identidad empleábamos el nombre concreto en lugar del abstracto, envolviendo en aquel la idea del sujeto. No se puede decir el papel es la blancura, pero sí el papel es blanco: porque esta última proposicion significa el papel es una cosa blanca; es decir, que en el predicado, blanco, en concreto, hacemos entrar la idea general de _una cosa_, esto es, de un sujeto modificable, y este sujeto es idéntico al papel modificado por la blancura.\"},{\"heading\":false,\"text\":\"[267.] Así se echa de ver que la expresion: _union del predicado con el sujeto_, es cuando menos inexacta. En toda proposicion afirmativa se expresa la identidad del predicado con el sujeto; el uso autoriza estos modos de hablar, que sin embargo no dejan de producir alguna confusion cuando se trata de entender perfectamente estas materias. Y es de notar que el lenguaje comun por sí solo, es en este punto como en muchos otros, admirablemente propio y exacto; nadie dice, el papel es la blancura, sino el papel es blanco; solo cuando se quiere encarecer mucho la perfeccion con que un sujeto posee una calidad, se la expresa en abstracto, uniéndole el pronombre _mismo_: así se dice hiperbólicamente: es la misma belleza, es la misma blancura, es la misma bondad.\"},{\"heading\":false,\"text\":\"[268.] Hasta lo que se llama igualdad en las matemáticas, viene á significar tambien identidad, de suerte que en esta clase de juicios, á mas de lo que hemos observado de general en todos, á saber, la identidad salvada por la expresion del predicado en concreto, hay que la misma relacion de igualdad significa identidad: esto necesita explicacion.\"},{\"heading\":false,\"text\":\"Si digo 6 + 3 = 9, expreso lo mismo que 6 + 3 es idéntico á 9. Claro es que en la afirmacion de igualdad no se atiende á la forma con que las cantidades están expresadas, sino á las cantidades mismas; pues de lo contrario, no solo no se podria afirmar la identidad, pero ni aun la igualdad: porque es evidente que 6 + 3 en cuanto á su forma, ni escrita, ni hablada, ni pensada, no es idéntico ni igual con 9. La igualdad se refiere á los valores expresados, y estos no solo son iguales, sino idénticos: 6 + 3 es lo mismo que 9. El todo no se distingue de sus partes reunidas: el 9 es el todo; 6 + 3 con sus partes reunidas.\"},{\"heading\":false,\"text\":\"El modo diferente con que se conciben 9 y 6 + 3, no excluye la identidad: esta diferencia es relativa á la forma intelectual; y tiene lugar no solo en este caso, sino en las percepciones de las cosas mas simples; no hay nada que nosotros no concibamos bajo aspectos diferentes, y cuyo concepto no podamos descomponer de diversos modos; y sin embargo nó por esto se dice que la cosa deje de ser simple é idéntica consigo misma.\"},{\"heading\":false,\"text\":\"Lo que se aplica á una ecuacion aritmética, puede extenderse á las algebráicas y geométricas. Si se tiene una ecuacion en que el primer miembro sea muy sencillo, por ejemplo Z, y el segundo muy complicado, por ejemplo el desarrollo de una serie, no se quiere decir que la expresion primera sea igual á la segunda; la igualdad se refiere, nó á la misma expresion sino á lo expresado, al valor que con las letras se designa: esto último es verdadero; lo primero seria evidentemente falso.\"},{\"heading\":false,\"text\":\"Dos circunferencias que tengan un mismo radio son iguales. Aquí parece que se trata solamente de igualdad, pues que hay en efecto dos objetos distintos que son las dos circunferencias, las cuales pueden trazarse en el papel ó representarse en la imaginacion: no obstante, ni aun en este caso la distincion es verdadera y sí solo aparente, verificándose lo que en las ecuaciones aritméticas y algebráicas, de que hay distincion y hasta diversidad en las formas, é identidad en el fondo. Desde luego se puede combatir el argumento principal en que se funda la distincion, si se observa que las circunferencias que se pueden trazar ó representar, no son mas que formas de la idea, y de ningun modo la idea misma. Ya se tracen ya se representen, tendrán una magnitud determinada y una cierta posicion en los planos que se tengan á la vista ó que se imaginen: en la idea y en la proposicion que á ella se refiere, no hay nada de esto; se prescinde de todas las magnitudes, de todas las posiciones, se habla en un sentido general y absoluto. Es verdad que las representaciones pueden ser infinitas, ya en la imaginacion ya en lo exterior: pero esto, lejos de probar su identidad con la idea, indica su diversidad; pues que la idea es única, ellas son infinitas; la idea es constante, ellas son variables; la idea es independiente de las mismas, y ellas son dependientes de la idea, teniendo el carácter y la denominacion de circunferencias en cuanto se le aproximan representando lo que ella contiene.\"},{\"heading\":false,\"text\":\"¿Qué se expresa pues en la proposicion: dos circunferencias que tengan un mismo radio, son iguales? la idea fundamental es que el valor de la circunferencia depende del radio; y la proposicion aquí enunciada no es mas que una aplicacion de aquella propiedad al caso de igualdad de los radios. Luego las circunferencias que concebimos como distintas, no son mas que ejemplos que nos ponemos en lo interior para hacernos visible la verdad de la aplicacion; pero en el fondo puramente intelectual, no se encuentra mas que la descomposicion de la idea misma de la circunferencia, ó su relacion con el radio aplicada al caso de igualdad. No hay pues dos circunferencias en el órden puramente ideal; hay una sola cuyas propiedades conocemos bajo diferentes conceptos y que expresamos de diversas maneras.\"},{\"heading\":false,\"text\":\"Si en todos los juicios hay afirmacion de identidad ó no identidad, y todos nuestros conocimientos ó nacen de un juicio ó van á parar á él, parece que todos se han de reducir á una simple percepcion de identidad: entonces, la fórmula general de nuestros conocimientos será: A es A, ó una cosa es ella misma. Este resultado parece una paradoja extravagante, y lo es segun el modo con que se le entiende; pero si se explica como se debe, puede ser admitido como una verdad, y verdad muy sencilla. Por lo dicho en los párrafos anteriores, se puede columbrar cuál es el sentido de esta opinion; pero la importancia de la materia exige otras aclaraciones.\"}]},{\"title\":\"CAPÍTULO XXVII\",\"blocks\":[{\"heading\":false,\"text\":\"CONTINUACION.\"},{\"heading\":false,\"text\":\"[269.] Es hasta ridículo el decir que los conocimientos de los mas sublimes matemáticos, se hayan reducido á esta ecuacion: A es A. Esto, dicho absolutamente, es no solo falso sino contrario al sentido comun; pero ni es contrario al sentido comun, ni es falso, el decir que los conocimientos de todos los matemáticos, son percepciones de identidad, la cual presentada bajo diferentes conceptos sufre infinitas variaciones de forma, que fecundan al entendimiento y constituyen la ciencia. Para mayor claridad tomemos un ejemplo y sigamos una idea al través de sus transformaciones.\"},{\"heading\":false,\"text\":\"[270.] La ecuacion círculo = círculo(1) es muy verdadera, pero nó muy luminosa, pues no sirve para nada, á causa de que hay identidad no solo de ideas sino tambien de conceptos y expresion. Para que haya un verdadero progreso en la ciencia, no basta que la expresion se mude, es necesario que se varié en algun modo el concepto bajo el cual se presenta la cosa idéntica. Asi es que si la ecuacion anterior la abreviamos en esta forma C = círculo(2) nada hemos adelantado, sino en cuanto á la expresion puramente material. La única ventaja que puede resultarnos, es el que aliviamos un tanto la memoria porque en vez de expresar el círculo por una palabra la expresamos por una letra, la inicial C. ¿Por qué? porque la variedad está en la expresion, no en el concepto.\"},{\"heading\":false,\"text\":\"Si en vez de considerar la identidad en toda su simplicidad en ambos miembros de la ecuacion, referimos el valor del círculo al de la circunferencia, tendremos C = circunferencia x ½ R (3) es decir que el valor del círculo es igual á la circunferencia multiplicada por la mitad del radio. En la ecuacion (3) hay identidad como en las (1) y (2) porque en ella se significa que el valor expresado por C es el mismo expresado por circunferencia x ½ R; de la propia suerte que en las anteriores se expresa que el valor del círculo es el valor del círculo. ¿Pero hay alguna diferencia de esta ecuacion á las anteriores? sí, y muy grande. ¿Cuál es? en las primeras se expresaba simplemente la identidad concebida bajo un mismo punto de vista; el círculo expresado en el segundo miembro no excitaba ninguna idea que no excitase el primero; pero en la última el segundo miembro expresa el mismo círculo sí, pero en sus relaciones con la circunferencia y el radio, y por consiguiente á mas de contener una especie de análisis de la idea del círculo, recuerda el análisis que anteriormente se ha hecho de la idea de la circunferencia con relacion á la del radio. La diferencia pues no está en la sola expresion material, sino en la variedad de conceptos bajo los cuales se presenta una cosa misma.\"},{\"heading\":false,\"text\":\"Llamando N el valor de la relacion de la circunferencia con el diámetro, y C al círculo, la ecuacion se nos convierte en esta otra C = N R¹(4). Aquí hay tambien identidad en los valores, pero encontramos un progreso notable en la expresion del segundo miembro, en el cual se nos ofrece el valor del círculo desembarazado de sus relaciones con el de la circunferencia y dependiente tan solo de un valor numérico N y de una recta que es el radio. Sin perder pues la identidad y solo por sucesion de percepciones de identidad, hemos llegado á adelantar en la ciencia, y habiendo partido de una proposicion tan estéril como círculo = círculo, nos encontramos en otra por la cual podemos desde luego calcular el valor de un círculo cualquiera con tal que se nos dé su radio.\"},{\"heading\":false,\"text\":\"Saliendo de la geometría elemental y considerando el círculo como una curva referida á dos ejes y cuyos puntos se determinan con respecto á estos, tendremos Z = 2Bx-x¹ (5); expresando Z el valor de la ordenada; B el de una parte constante del eje de las abscisas; y x la abscisa correspondiente á Z. Aquí encontramos ya otro progreso de ideas todavía mas notable; en ambos miembros, no expresamos ya el valor del círculo sino el de unas líneas, con las cuales se determinan todos los puntos de la curva; y concebimos fácilmente que esta curva que nos cerraba la figura cuyas propiedades determinábamos en la geometría elemental, puede ser concebida bajo tal forma que pertenezca á un género de curvas de las cuales ella constituya una especie por la particular relacion de las cantidades 2 x y B; de manera que modificando la expresion con la añadidura de una nueva cantidad combinada de este ó de aquel modo, puede resultarnos una curva de otra especie. Entonces, si queremos determinar el valor de la superficie encerrada en esto círculo, podremos considerarla, no simplemente con respecto al radio, sino á las áreas encerradas entre las varias perpendiculares cuyos extremos determinan los puntos de la curva y que se llaman ordenadas: con lo cual resultará que el mismo valor del círculo se determinará bajo conceptos diferentes, no obstante de que ese valor es siempre idéntico: la transicion de unos conceptos á otros será la sucesion de las percepciones de identidad presentada bajo formas diferentes.\"},{\"heading\":false,\"text\":\"Consideremos ahora que el valor del círculo depende del radio, lo cual nos da C = funcion x (6). Ecuacion que nos lleva á concebir el círculo bajo la idea general de una funcion de su radio ó de x, y por consiguiente nos autoriza á someterle á todas las leyes á que una funcion está sujeta y nos conduce á las propiedades de las diferencias, de los límites, y de las relaciones de estos; con lo cual entramos en el cálculo infinitesimal cuyas expresiones nos presentan la identidad bajo una forma que nos recuerda una serie de conceptos de análisis detenida y profunda. Así, expresando la diferencial del círculo por dc; y su integral por S. dc; tendremos c = S. dc (7) ecuacion en que se expresan los mismos valores que en aquella otra, círculo = círculo, pero con la diferencia de que la (7) recuerda inmensos trabajos analíticos, es el resultado de la dilatada sucesion de conceptos del cálculo integral, del diferencial, de los límites de las diferencias de las funciones, de la aplicacion del álgebra á la geometría y de una muchedumbre de nociones geométricas elementales, reglas y combinaciones algebráicas y de todo cuanto ha sido menester para llegar al resultado. Entonces, cuando se integre la diferencial, y por integracion se llegue á sacar el valor del círculo, es claro que seria lo mas extravagante el afirmar que la ecuacion integral no es mas que la de círculo = círculo; pero no lo es el decir que en el fondo hay identidad, y que la diversidad de expresion á que hemos llegado es el fruto de una sucesion de percepciones de la misma identidad presentada bajo aspectos diferentes. Suponiendo que los conceptos por los cuales haya sido necesario pasar sean A B C D E M; la ley de su enlace científico podrá expresarse de esta manera: A = B, B = C, C = D, D = E, E = M; luego A = M.\"},{\"heading\":false,\"text\":\"[271.] Lo que acabo de explicar no puede comprenderse bien si no se recuerdan algunos caractéres de nuestra inteligencia, en los cuales se encuentra la razon de tamañas anomalías. Nuestro entendimiento tiene la debilidad de no poder percibir muchas cosas sino sucesivamente, y de que aun en las ideas mas claras, no ve lo que en ellas se contiene, sino con mucho trabajo. De esto resulta una necesidad á la cual corresponde con admirable armonía una facultad que la satisface: una necesidad de concebir bajo varias formas no solo distintas sino diferentes, aun las cosas mas simples; una facultad de descomponer un concepto en muchas partes, multiplicando en el órden de las ideas lo que en realidad es uno. Esta facultad de descomposicion seria inútil si al pasar el entendimiento por la sucesion de conceptos, no tuviese medio de enlazarlos y retenerlos, en cuyo caso iría perdiendo el fruto de sus tareas escapándosele de la mano tan pronto como lo acababa de coger. Afortunadamente, este medio le tiene en los signos escritos, hablados ó pensados; expresiones misteriosas que á veces designan no solo una idea, sino que son como el compendio de los trabajos de una larga vida y quizás de una dilatada serie de siglos. Al presentársenos el signo, no vemos ciertamente con entera claridad todo lo que por él se expresa, ni las razones de la legitimidad de la expresion; pero sabemos en confuso el significado que allí se encierra, sabemos que en caso necesario nos basta tomar el hilo de las percepciones por las cuales hemos pasado, volviendo así con paso retrógrado hasta los elementos mas simples de la ciencia. Al hacer los cálculos, el matemático mas eminente no ve con toda claridad lo que significan las expresiones que va empleando, sino en cuanto se refieren al objeto que le ocupa; pero está cierto que aquellas expresiones no le engañan, que las reglas por las cuales se guia son enteramente seguras; porque sabe que en otro tiempo las afianzó en inconcusas demostraciones. El desarrollo de una ciencia puede compararse á una serie de colunas en las cuales se han marcado las distancias de un camino; el ingeniero que ha hecho las operaciones se sirve de los guarismos de las colunas, sin necesidad de recordar las operaciones que le condujeron á marcar la cantidad que tiene á la vista; bástale saber que las operaciones fueron bien hechas y que el resultado de ellas se escribió bien.\"},{\"heading\":false,\"text\":\"[272.] La prueba de esta necesidad de descomposicion, á mas de tenerla ampliamente consignada en los ejemplos anteriores, se la encuentra en los elementos de toda enseñanza, donde se hace preciso explicar bajo una forma de demostracion proposiciones que nada mas dicen que las definiciones ó axiomas que se han asentado. Por ejemplo, en las obras elementales de geometría se encuentra este teorema: todos los diámetros de un círculo son iguales; y si se quiere que los principiantes le comprendan, es necesario dar la forma de demostracion á lo que no es ni puede ser mas que una explicacion, y casi un recuerdo de la idea del círculo. Cuando se traza la circunferencia se fija un punto en torno del cual se hace girar una línea que se llama radio; pues bien, no siendo el diámetro otra cosa que el conjunto de los dos radios continuados en una misma línea, parece que debiera bastar la enunciacion del teorema para que se le viese evidentemente contenido en la idea del círculo y como una especie de repeticion del postulado en que se funda la construccion de la curva; sin embargo no sucede así, y es necesario explicar, haciendo como que se prueba, y mostrar el diámetro igual á dos radios, y recordar que estos son iguales, y á veces repetir que así se supone en la misma construccion; en una palabra, emplear una porcion de conceptos para convencer de una verdad que debiera ser conocida con la simple intuicion de uno solo, como sucede cuando las fuerzas geométricas del entendimiento han adquirido cierta robustez.\"},{\"heading\":false,\"text\":\"[273.] Ahora podrémos apreciar en su justo valor la opinion de Dugald-Steward en sus _Elementos de la filosofía del espíritu humano_, cuando dice: «es lícito dudar que aun esta ecuacion aritmética 2 x 2 = 4 pueda ser representada con exactitud por la fórmula A = A. Esta ecuacion es una proposicion que enuncia _la equivalencia de dos expresiones diferentes_, equivalencia cuyo descubrimiento puede ser de la mayor importancia en una infinidad de casos. La fórmula es una proposicion del todo insignificante y frivola que no puede en ningun caso recibir la menor aplicacion práctica; ¿qué pensaremos pues de esta proposicion A = A, si se la compara con la fórmula del binomio de Newton á la cual en tal caso representaria? sin duda cuando se la aplica á la ecuacion 2 x 2 = 4 (que por su extrema simplicidad y vulgaridad puede pasar por un axioma) la paradoja no presenta tan de bulto su monstruosidad; pero en este segundo caso parece del todo imposible que tenga ni aun significacion» (2. p. cap. 2. seccion 3. § 2.). Este filósofo no advierte que la pretendida monstruosidad nace de la errada interpretacion que él mismo da á la opinion de sus adversarios. Nadie ha pensado en negar la importancia de los descubrimientos en que se prueba la equivalencia de expresiones diferentes; nadie dudará de que la fórmula del binomio de Newton sea un gran progreso sobre la fórmula A = A; pero la cuestion no está aquí, está en ver si la fórmula del binomio de Newton es mas que la expresion de cosas idénticas, y si aun el mérito mismo de la expresion, es ó no el fruto de una serie de percepciones de identidad. Si la cuestion se presentase bajo el punto de vista de Dugald-Steward, seria hasta indigna de ser ventilada: en buena filosofía no puede disputarse sobre cosas no solo absurdas sino ridiculas.\"}]},{\"title\":\"CAPÍTULO XXVIII\",\"blocks\":[{\"heading\":false,\"text\":\"CONTINUACION.\"},{\"heading\":false,\"text\":\"[274.] Expliquemos ahora cómo la doctrina de la identidad se aplica en general á todos los raciocinios, versen ó no sobre objetos matemáticos; para esto examinaremos algunas de las formas dialécticas en las cuales está consignado el arte de raciocinar.\"},{\"heading\":false,\"text\":\"Todo A es B; M es A, luego M es B. En este silogismo encontramos en la mayor, la identidad de todo A con B, y en la menor la de M con A, de lo cual sacamos la de M con B. En las tres proposiciones hay afirmacion de identidad, y por consiguiente percepcion de ella: veamos lo que sucede en el enlace que constituye la fuerza del raciocinio.\"},{\"heading\":false,\"text\":\"¿Por qué digo que M es B? porque M es A, y todo A es B. M es uno de los A, que estaba expresado ya en las palabras: todo A; luego cuando digo M es A, no digo nada nuevo sobre lo que habia dicho por todo A; ¿qué diferencia hay pues? hay la diferencia de que en la expresion todo A, no hacia atencion á uno de sus contenidos M, del cual sin embargo afirmaba que era B, por lo mismo que decia todo A es B. Si en la expresion todo A hubiese visto distintamente á M, no hubiera sido necesario el silogismo, pues por lo mismo que decia todo A es B, hubiera entendido M es B.\"},{\"heading\":false,\"text\":\"Esta observacion es tan verdadera y exacta, que en tratándose de relaciones demasiado claras se suprime el silogismo y se le reemplaza por el entimema. El entimema es ciertamente la abreviacion del silogismo; pero en esta abreviacion debemos ver algo mas que un ahorro de palabras; hay un _ahorro de conceptos_, porque el entendimiento ve intuitivamente lo uno en lo otro sin necesidad de descomposicion. Es hombre, luego es racional; callamos la mayor y ni aun la pensamos, porque en la idea de hombre y en su aplicacion á un individuo, vemos intuitivamente la de racional, sin gradacion de ideas ni sucesion de conceptos.\"},{\"heading\":false,\"text\":\"Supongamos que se trata de demostrar que el perímetro de un polígono inscrito en un círculo es menor que la circunferencia, y que se hace el siguiente silogismo: todo conjunto de rectas inscritas en sus respectivas curvas es menor que el conjunto de las mismas curvas; es así que el perímetro del polígono es un conjunto de rectas, y la circunferencia un conjunto de arcos ó curvas; luego el perímetro inscrito os menor que la circunferencia. Pregunto ahora, si quien sepa que el conjunto de rectas es menor que el conjunto de curvas no verá con igual facilidad que el perímetro es menor que la circunferencia circunscrita, con tal que entienda perfectamente el significado de las palabras; es evidente que sí. ¿Para qué pues se necesita el recuerdo del principio general? ¿es para añadir nada al concepto particular? nó por cierto; porque nada puede haber mas claro que las siguientes proposiciones: el perímetro del polígono es un conjunto de rectas; la circunferencia es un conjunto de arcos ó curvas; lo que se hace pues con el principio general es llamar la atencion sobre una fase del concepto particular, para que con la reflexion se vea en este lo que sin la reflexion no se veia. La certeza de la conclusion no depende del principio general; pues que si se hubiese pensado en las relaciones de mayoría y minoría, solo con respecto á las rectas del perímetro y á los arcos cuyo conjunto forma la circunferencia, se hubiera inferido lo mismo.\"},{\"heading\":false,\"text\":\"Con este ejemplo se confirma que el entimema no es una simple abreviacion de palabras, y se explica por qué le empleamos en los raciocinios que versan sobre materias familiares al entendimiento. Entonces, en uno cualquiera de los conceptos vemos lo que necesitamos para la consecuencia, y por esto tenemos bastante con una premisa, en la cual incluimos la otra, mas bien que no la sobreentendemos. El principiante dirá: el arco es mayor que la cuerda, porque la curva es mayor que la recta; pero cuando se haya familiarizado con las ideas geométricas dirá simplemente, el arco es mayor que la cuerda, viendo en la misma idea del arco la idea de curva, en la de cuerda la de recta, sin ninguna descomposicion. ¿Por ventura es verdad que el arco sea mayor que la cuerda porque toda curva es mayor que su recta? nó, de ninguna manera; si no existiese la idea abstracta de curva y la única curva pensada fuese la particular arco de círculo; si no existiese tampoco la idea abstracta de recta y la única recta pensada fuese la cuerda, seria verdad como ahora que el arco es mayor que la cuerda.\"},{\"heading\":false,\"text\":\"[275.] En tratándose de las relaciones _necesarias_ de los objetos, los principios generales, los términos medios, y cuantos recursos nos ofrece la dialéctica para auxiliar el raciocinio, no son mas en el fondo que invenciones del arte para inducirnos á reflexionar sobre el concepto de la cosa, haciéndonos ver en él lo que antes no veíamos. De esto se sigue que todos los juicios sobre los objetos necesarios, son en cierto modo analíticos; equivocándose Kant cuando afirma que los hay sintéticos prescindiendo de la experiencia. Si esta no existe, no tenemos ningun dato de la cosa, solo poseemos su concepto; de lo extraño á este nada podemos saber. No quiero decir que todas las proposiciones expresen tal relacion del predicado al sujeto, que el concepto de este sea suficiente para que descubramos aquel; pero sí que la razon de la insuficiencia está en que el concepto es incompleto ó en sí ó con respecto á nuestra comprension; y que suponiéndole completo en sí mismo y la debida capacidad en nuestro entendimiento para comprender todo lo que él nos dice, encontraríamos en el mismo todo lo que puede formar materia científica.\"},{\"heading\":false,\"text\":\"[276.] Un ejemplo geométrico aclarará mis ideas. El triángulo tiene muchas propiedades cuya explicacion, demostracion y aplicaciones ocupan largas páginas en los libros de geometría. En el concepto del triángulo entran el de rectas y el de los ángulos que estas forman: pregunto ahora ¿en todas las explicaciones y demostraciones de las propiedades de los triángulos en general, ¿se sale jamás de las ideas de ángulo y de recta? nó, jamás, ni se sale, ni se puede salir; de lo contrario flaquearia cuanto se dijese fundado en nuevos elementos que se hubiesen introducido en el concepto. Estos elementos serian ajenos al triángulo, y por consiguiente le quitarían su naturaleza. En las relaciones necesarias no cabe mas ni menos, ni añadiduras, ni sustracciones de ninguna clase: lo que es es, y nada mas. Cuando se pasa del triángulo en general á sus varias especies, como equilátero, isósceles, rectángulo, oblicuángulo etc. etc., es de notar que la demostracion se atiene rigurosamente á lo contenido en el concepto general modificado con la propiedad determinante de la especie, es decir, á la igualdad de los tres lados, ó de dos, ó á la desigualdad de todos, ó á la suposicion de un ángulo recto etc. etc.\"},{\"heading\":false,\"text\":\"[277.] En la aplicacion del álgebra á la geometría, se ve con mas claridad lo que estoy explicando. Una curva se expresa por una fórmula que contiene el concepto de la misma curva; es decir, su esencia. Para demostrar todas las propiedades de la curva, el geómetra no necesita salir de la fórmula; en todas las cuestiones que se suscitan lleva la fórmula en la mano como la piedra de toque, y en la misma encuentra todo cuanto ha menester. Es verdad que traza triángulos ú otras figuras dentro de la misma curva, que de la misma tira rectas á puntos fuera de ella, pero jamás sale del concepto expresado en la fórmula; lo que hace es descomponerle y descubrir en él cosas que antes no habia descubierto.\"},{\"heading\":false,\"text\":\"En esta ecuacion z² = e²/E² (2 Ex - x³) se encuentra la expresion de las relaciones constitutivas de la elipse, expresando E el semieje mayor, e el semieje menor, z las ordenadas, y x las abscisas. Con esta ecuacion desenvuelta y transformada de varias maneras, se determinan las propiedades de la curva; ¿y cómo? haciendo ver con la ayuda de las construcciones, que la nueva propiedad está contenida en el concepto mismo, y que basta analizarle para encontrarla en él.\"},{\"heading\":false,\"text\":\"Si suponemos un entendimiento que concibe la esencia de la curva, con inmediata intuicion de la ley que preside á la inflexion de los puntos, sin necesidad de referirla á ninguna línea, ó bien bastándole un eje en vez de necesitar dos, ó de algun otro modo que nosotros no podemos ni siquiera imaginar, resultará que no habrá menester dar los rodeos que nosotros para demostrar las propiedades de la curva, pues las verá claramente pensadas en el mismo concepto de ella. Esta suposicion no es arbitraria: hasta cierto punto la vemos realizada todos los dias, aunque en escala menor; un geómetra vulgar tiene el concepto de una curva como lo tenia Pascal: en este mismo concepto el geómetra vulgar ve las propiedades de la misma con largo trabajo, y limitándose á las comunes; Pascal veia las mas recónditas poco menos que de una ojeada. Kant, por no haberse hecho cargo de esta doctrina, no puede dar solucion al problema filosófico de los juicios sintéticos puros: profundizando mas la materia hubiera visto que hablando en rigor, no hay tales juicios, y en vez de cansarse por resolver el problema se hubiera abstenido de suscitarle (XXVI).\"}]},{\"title\":\"CAPÍTULO XXIX\",\"blocks\":[{\"heading\":false,\"text\":\"SI HAY VERDADEROS JUICIOS SINTÉTICOS _à priori_, EN EL SENTIDO DE KANT.\"},{\"heading\":false,\"text\":\"[278.] La mucha importancia que da el filósofo aleman á su imaginado descubrimiento exige que le examinemos con detencion. Júzguese de esta importancia por lo que él mismo dice: «si algun antiguo hubiese tenido la idea de solo proponer la presente cuestion, ella hubiera sido una barrera poderosa contra todos los sistemas de la razon pura hasta nuestros dias, y habria ahorrado muchas tentativas infructuosas que se han emprendido _ciegamente sin saber de qué se trataba._» (Crítica de la razon pura. Introduccion). El pasaje no es nada modesto, y excita naturalmente la curiosidad de saber en qué consiste un problema cuyo solo planteo habria sido bastante á evitar los extravíos de la razon pura.\"},{\"heading\":false,\"text\":\"Hé aquí sus palabras: «en los juicios sintéticos á mas del concepto del sujeto debo tener alguna otra cosa (x) sobre la cual el entendimiento se apoye para reconocer que un predicado no contenido en este concepto, no obstante le pertenece.\"},{\"heading\":false,\"text\":\"»Tocante á los juicios empíricos ó de experiencia, no hay ninguna dificultad; porque esta x es la experiencia completa del objeto que conozco por un concepto _a_, el cual no forma mas que una parte de esta experiencia. En efecto: aunque yo no comprenda en el concepto de cuerpo en general el predicado pesadez, este concepto indica no obstante una parte total de la experiencia; puedo por consiguiente añadirle otra parte de la misma experiencia como perteneciente al primer concepto. De antemano puedo reconocer analíticamente el concepto de cuerpo por los caractéres de extension, impenetrabilidad, figura etc., caractéres concebidos todos en este concepto. Pero si extiendo mi conocimiento volviendo la atencion del lado de la experiencia de donde he sacado este concepto; entonces hallo siempre la pesadez unida á los caractéres precedentes. Esta x que está fuera del concepto _a_ y que es el fundamento de la posibilidad de la síntesis del predicado pesadez, con el concepto _a_, pertenece pues á la experiencia.\"},{\"heading\":false,\"text\":\"»Pero en los juicios sintéticos _à priori_, este medio falla absolutamente. Si debo salir del concepto _a_ para conocer otro concepto _b_ como unido con aquel, ¿dónde me apoyaré y cómo será posible la síntesis, cuando no me es dable volverme hácia el campo de la experiencia?\"},{\"heading\":false,\"text\":\"»Hay pues aquí un cierto misterio, cuya explicacion puede solo asegurar el progreso en el campo ilimitado del conocimiento intelectual puro» (ibid.).\"},{\"heading\":false,\"text\":\"[279.] La razon de esta síntesis, la encontramos en la facultad de nuestro entendimiento para formar conceptos totales, en los que descubra la _relacion_ de los parciales que los componen; y la legitimidad de la misma síntesis, se funda en los principios en que estriba el criterio de la evidencia.\"},{\"heading\":false,\"text\":\"La síntesis de que se habla en las escuelas, consiste en la reunion de conceptos, y no se opone á que se tengan por analíticos los conceptos totales, de cuya descomposicion resulta el conocimiento de las relaciones de los parciales.\"},{\"heading\":false,\"text\":\"Si Kant se hubiese ceñido á los juicios de experiencia, no habria inconveniente en su doctrina; pero extendiéndola al órden intelectual puro, ó es inadmisible, o cuando menos está expresada con poca exactitud.\"},{\"heading\":false,\"text\":\"[280.] Afirma Kant que los juicios matemáticos son todos sintéticos, y que esta verdad que en su juicio es «ciertamente incontestable y muy importante por sus consecuencias, parece haber escapado hasta aquí á la sagacidad de los analistas de la razon humana, haciendo muy contrarias sus conjeturas;» yo creo que lo que falta aquí no es la sagacidad de los analistas, sino la de su Aristarco. Lo demostraré.\"},{\"heading\":false,\"text\":\"«Tal vez se podria creer á primera vista que la proposicion 7 + 5 = 12, es una proposicion puramente analítica que resulta de la idea de siete mas cinco, segun el principio de contradiccion; pero bien mirado se encuentra que el concepto de la suma de siete y de cinco, no contiene otra cosa que la reunion de dos números en uno solo, lo que de ningun modo trae consigo el pensamiento de lo que es este número único compuesto de los otros dos.»\"},{\"heading\":false,\"text\":\"Si se dijese que quien oye siete mas cinco, no siempre piensa doce, porque no ve bastante bien que un concepto es el otro, aunque bajo diferente forma, se diria verdad; pero no lo es que por esta razon el concepto no sea puramente analítico. La simple explicacion de ambos es bastante á manifestar su identidad.\"},{\"heading\":false,\"text\":\"Para que se comprenda mejor, tomemos la inversa 12 = 7 + 5. Es evidente que quien no sepa que 7 + 5 = 12, tampoco sabrá que 12 = 7 + 5; y pregunto ahora, examinando el concepto 12, ¿no veo contenido en él el 7 + 5? es cierto: luego el concepto de 12 se identifica con el de 7 + 5; luego asi como de que oyendo 12 no siempre se piensa 7 + 5 no se puede inferir que el concepto de 12 no contenga el 7 + 5, tampoco de que quien oiga el 7 + 5 no siempre comprenda 12, no se puede deducir que el primer concepto no incluya el segundo.\"},{\"heading\":false,\"text\":\"La causa de la equivocacion está en que dos conceptos idénticos están presentados al entendimiento bajo diferente forma; y hasta que quitándoles la forma se ve el fondo, no se descubre la identidad. No hay propiamente _raciocinio_ sino _explicacion._\"},{\"heading\":false,\"text\":\"Lo que añade Kant sobre la necesidad de apelar en este caso á una intuicion, con respecto á uno de los dos números, añadiendo al siete el cinco expresado sucesivamente por los dedos de la mano, es sobre manera fútil. 1.º Añádase como se quiera el cinco, nunca será mas que el cinco añadido, y por tanto nada dará ni quitará á 7 + 5. 2.º La sucesiva adicion por _los dedos_ equivale á decir 1 + 1 + 1 + 1 + 1 = 5. Lo que trasforma la espresion 7 + 5 = 12, en esta otra 7 + 1 + 1 + 1 + 1 + 1 = 12; es asi que la misma relacion tiene el concepto 1 + 1 + 1 + 1 + 1 con 5, que 7 + 5 con 12; luego si de estos el uno no está contenido en el otro, tampoco lo estarán los de Kant. Se replicará que Kant no habla de identidad sino de intuicion; pero esta intuicion no es la sensacion, sino la idea; si es la idea, es el concepto explicado, nada mas. 3.º Este método de intuicion vemos que no es necesario ni aun para los niños. 4.º Dicho método es imposible en los números grandes.\"},{\"heading\":false,\"text\":\"[281.] Añade Kant que esta proposicion: «entre dos puntos, la línea recta es la mas corta» no es puramente analítica, porque en la idea de _recta_ no entra la de _mas corta_. Prescindiré de que hay autores que demuestran ó pretenden demostrar esta proposicion; y me ceñiré únicamente á la razon de Kant. Este autor olvida que no se trata de la recta sola, sino de la recta _comparada_. En la recta sola, no entra ni puede entrar lo de _mas_, ni de _menos_, pues esto supone comparacion; pero desde el momento en que se comparan la recta y la curva, con respecto á la _longitud_, en el concepto de la curva, se ve el exceso sobre la recta. La proposicion pues resulta de la simple comparacion de dos conceptos puramente analíticos, con un tercero que es _longitud_.\"},{\"heading\":false,\"text\":\"[282.] Sí la razon de Kant fuese de algun valor, se inferiria que ni aun el juicio «el todo es mayor que su parte» es analítico; porque en la idea de _todo_, no entra la de _mayor_, hasta que se la compara con la de _parte_. Tampoco seria juicio analítico este: 4 es mayor que 3; porque en el concepto de 4, no entra la idea de mayor, hasta que se le compara con el de 3.\"},{\"heading\":false,\"text\":\"El axioma: cosas iguales á una tercera son iguales entre si, tampoco seria juicio analítico: porque en el concepto de _cosas iguales á una tercera_, tampoco entra la igualdad entre sí, hasta que se reflexiona que la igualdad del medio implica la de los extremos.\"},{\"heading\":false,\"text\":\"Esa _x_ de que nos habla Kant, se encontraría en casi todos los juicios, si no pudiésemos formar conceptos totales en que se envolviese la comparacion de los parciales: en cuyo caso no tendríamos mas juicios analíticos que los puramente idénticos, ó los comprendidos directamente en esta fórmula A es A.\"},{\"heading\":false,\"text\":\"[283.] La comparacion de dos conceptos con un tercero no quita al resultado el carácter de juicio analítico, así como el que un predicado no pueda verse desde luego en la idea del sujeto sin el auxilio de dicha comparacion. Esta la necesitamos muchas veces, porque pensamos solo muy confusamente lo que se halla en el concepto que ya tenemos, y hasta sucede que no lo pensemos de ningun modo. A cada paso estamos viendo que una persona dice una cosa y sin notarlo se contradice luego, por no advertir que lo que añade se opone á lo mismo que habia dicho. Son comunes en la conversacion las siguientes réplicas: ¿no ve V. que supone lo contrario de lo que ahora dice? ¿no ve V. que en las mismas condiciones antes asentadas, se implica lo contrario de lo que ahora establece?\"},{\"heading\":false,\"text\":\"[284.] En un concepto no solo se incluye lo que expresamente se piensa en él, sino todo lo que se puede pensar. Si descomponiéndole encontramos en el mismo cosas nuevas, no se puede decir que las añadimos, sino que las descubrimos: no hay entonces síntesis, sino análisis; de lo contrario seria preciso inferir que no hay ningun concepto analítico ó que solo lo son los puramente idénticos. Excepto este último caso cuya fórmula general es, A es A, siempre hay en el predicado algo mas de lo pensado en el sujeto, si nó en cuanto á la sustancia, al menos en cuanto al modo. El círculo es una curva: esta es sin duda una proposicion analítica de las mas sencillas que imaginarse pueden; y no obstante, el predicado expresa la razon general de curva, que en el sujeto puede estar envuelta de un modo confuso con relacion á una especie particular de las curvas. Siguiendo una gradacion en las proposiciones geométricas se podria notar que no hay mas que lo dicho en la proposicion anterior, sino la mayor ó menor dificultad de descomponer el concepto y ver en él lo que antes no se veia.\"},{\"heading\":false,\"text\":\"Si digo: el círculo es una seccion cónica; el predicado no está pensado en el sujeto por quien no sepa lo que significan los términos ó no haya reflexionado sobre su verdadero sentido. Al concepto del círculo nada le añado, solo le descubro una propiedad que antes no conocia, y este descubrimiento nace de su comparacion con el cono. ¿Hay aquí síntesis? nó, de ningun modo; lo que hay es análisis comparado de los dos conceptos; círculo y cono.\"},{\"heading\":false,\"text\":\"[285.] Como esta doctrina destruye por su base el sistema de Kant en este punto, voy á desenvolverla y darle mas sólido fundamento.\"},{\"heading\":false,\"text\":\"Para que haya síntesis propiamente dicha, es menester que se una al concepto una cosa que de ningun modo le pertenece, como se ve en el ejemplo aducido por el mismo Kant. La figurabilidad se encuentra en el concepto del cuerpo; pero la pesadez es una idea totalmente extraña, y que solo podemos unir al concepto del cuerpo porque así nos lo atestigua la experiencia. Solo con esta añadidura se verifica propiamente la síntesis; pero nó con la union de ideas que nazcan del mismo concepto de la cosa, aunque para fecundarle se necesite la comparacion. Los conceptos no son enteramente absolutos; contienen relaciones, y el descubrimiento de estas no es una síntesis sino un análisis mas completa. Si se replica que en tal caso hay algo mas que el concepto primitivo, observaré que esto se verifica en todos los que no son puramente idénticos. Además que con la comparacion se forma un concepto total nuevo, resultante de los conceptos primitivos; en cuyo caso las propiedades de las relaciones son vistas nó por síntesis sino por el análisis del concepto total.\"},{\"heading\":false,\"text\":\"Segun Kant, la verdadera síntesis necesita reunion de cosas extrañas entre sí, y tan extrañas, que el lazo que las une es una especie de misterio, una _x_ cuya determinacion es un gran problema filosófico. Si esta _x_ se encuentra en la relacion esencial de los conceptos parciales que entran en el concepto total, se ha resuelto el problema por la simple análisis; ó para hablar con mas exactitud, se ha manifestado que el problema no existia pues la _x_ era una cantidad conocida.\"},{\"heading\":false,\"text\":\"Yo no sé que pueda haber juicio mas analítico que aquel en el cual vemos las partes en el todo: pues este no es mas que las mismas partes reunidas. Si digo; uno y uno son dos, ó bien dos es igual á uno mas uno, no puede negarse que tengo un concepto total dos, en cuya descomposicion hallo uno mas uno: si esto no es analítico, es decir, si aquí el predicado no está contenido en la idea del sujeto, no se alcanza cuándo podrá estarlo. Pues bien, aquí mismo hay diferentes conceptos, uno mas uno, se los reune y de ellos se forma el concepto total. Aunque sencillísima, la relacion existe; y el que sea mas ó menos sencilla ó complicada y que por consiguiente sea vista con mas ó menos facilidad, no altera el carácter de los juicios convirtiéndolos de analíticos en sintéticos.\"},{\"heading\":false,\"text\":\"[286.] Completemos esta explicacion con un ejemplo de geometría elemental. Si se dice un paralelógramo oblicuángulo es igual en superficie á un rectángulo de la misma base y altura, tenemos: 1.º Que en la idea de paralelógramo oblicuángulo no vemos la de igualdad con el rectángulo. Ni tampoco la podemos ver, porque la relacion no existe cuando no hay otro extremo al cual se refiera. En la idea de paralelógramo no entra la de rectángulo, y por consiguiente no puede entrar la de igualdad. 2.° La relacion nace de la comparacion del oblicuángulo con el rectángulo, y por consiguiente se la ha de encontrar en un concepto total en que entren los dos. Entonces no puede decirse que al concepto del oblicuángulo le añadamos algo que no le pertenezca, sino que por el contrario esta igualdad la vemos surgir del concepto del oblicuángulo y del rectángulo como conceptos parciales del total en que los dos se combinan. El análisis de este concepto total, nos lleva á descubrir la relacion buscada; siendo de notar, que cuando la simple reunion de los conceptos comparados no basta, nos valemos de otro que comprenda á los mismos y alguno mas; y del concepto del nuevo debidamente analizado, sacamos la relacion de las dos partes comparadas.\"},{\"heading\":false,\"text\":\"[287.] Precisamente en la construccion geométrica que suele hacerse para demostrar el teorema que me sirve de ejemplo, puede sensibilizarse por decirlo así lo que acabo de explicar con respecto á los conceptos totales que contienen otros á mas de los comparados. Confundidas las bases del paralelógramo rectángulo y oblicuángulo, se ve desde luego una parte que les es comun, y es el triángulo formado por la base, una parte de un lado del oblicuángulo y otra de uno del rectángulo; para esto no se necesita ni síntesis ni análisis, pues hay perfecta coincidencia, lo que en geometría equivale á identidad. La dificultad está en las dos partes restantes, es decir, en los trapecios á que se reducen los dos paralelógramos quitado el triángulo comun. La simple intuicion de las figuras nada dice con respecto á la equivalencia de las dos superficies: solo se ve que los dos lados del oblicuángulo van extendiéndose, encerrando menor distancia á proporcion que el ángulo va siendo mas oblicuo, hallándose estas dos condiciones de longitud de lados y disminucion de distancias entre dos límites, de los cuales el uno es lo infinito y el otro el rectángulo. Se puede demostrar la relacion de la equivalencia de las superficies, prolongando la paralela opuesta á la base, y formando así un cuadrilátero del cual son partes los trapecios; para descubrir la igualdad de estos trapecios basta descomponer el cuadrilátero atendiendo á la igualdad de dos triángulos formados respectivamente cada uno por uno de los trapecios y un triángulo comun. ¿Añado con esto nada al concepto de cada trapecio? nó; solo le comparo. Esta comparacion no la he podido hacer directamente, y por esto los he incluido en un concepto total cuya simple análisis me ha bastado para descubrir la relacion que buscaba. Esta relacion no se la da el concepto, solo la manifiesta; por manera que si el concepto de las dos figuras comparadas fuese mas perfecto, de suerte que viésemos intuitivamente la relacion que existe entre el aumento de los lados y el decremento de la distancia de los mismos, veríamos que hay aquí una ley constante que suple de una parte lo que se pierde por otra; y por consiguiente en el mismo concepto del oblicuángulo descubriríamos la razon fundamental de la igualdad, es decir la no alteracion del valor de la superficie por la mayor ó menor oblicuidad de los ángulos, teniendo así lo que despues sacamos por la expresada comparacion y que generalizamos refiriéndonos á dos valores lineales constantes: base y altura. Lo mismo nos sucederia con respecto á la equivalencia de todas las cantidades variables expresadas de diferente modo, si sus conceptos pudiésemos reducirlos á fórmulas tan claras y sencillas como las de las funciones aparentes, por ejemplo n s/m s, donde sea cual fuere el valor de la variable resulta siempre el mismo el valor de la expresion, el cual es constante, á saber n/m.\"},{\"heading\":false,\"text\":\"[288.] No se crea que estas investigaciones sean inútiles: en la cuestion presente como en muchas otras, sucede que de un problema filosófico, al parecer meramente especulativo, están pendientes verdades importantísimas. Así en el caso que nos ocupa, notaremos que Kant explica el principio de causalidad de una manera inexacta, y que segun como se interpreten sus palabras debe llamarse completamente falsa; y quizás la raíz de su equivocacion está en que considera el principio de causalidad como sintético, aunque _á priori_, cuando en realidad debe ser tenido por analítico, como demostraré al tratar de la idea de causa.\"},{\"heading\":false,\"text\":\"Considerando de la mayor importancia el tener ideas claras y distintas en la presente materia, voy á resumir en pocas palabras la doctrina expuesta sobre la evidencia inmediata y la mediata.\"},{\"heading\":false,\"text\":\"[289.] Hay evidencia inmediata cuando por el concepto del sujeto vemos la conveniencia ó repugnancia del predicado, sin necesitar otro medio que la simple reflexion sobre el significado de las palabras. A los juicios de esta clase, se los llama con propiedad analíticos, porque basta descomponer el concepto del sujeto para encontrar en él la conveniencia ó repugnancia del predicado.\"},{\"heading\":false,\"text\":\"Hay evidencia mediata cuando por el simple concepto del sujeto, no vemos desde luego la conveniencia ó repugnancia del predicado; por lo cual necesitamos apelar á un medio que nos la manifieste.\"},{\"heading\":false,\"text\":\"[290.] Surge aqui la cuestion de si los juicios de evidencia mediata pueden llamarse analíticos. Claro es que si por analíticos se entienden solamente aquellos en los cuales basta entender el significado de los términos para ver la conveniencia ó repugnancia del predicado, no pueden llamarse tales los de evidencia mediata. Pero si entendemos por juicio analítico aquel en que basta _descomponer_ un concepto para encontrar en él la conveniencia ó repugnancia del predicado, hallaremos que los juicios de evidencia mediata pertenecen tambien á dicha clase, y que el medio empleado no es mas que la formacion de un concepto total en que se hacen entrar los parciales cuya relacion se quiere descubrir. En la _reunion_ de estos conceptos parciales hay síntesis, es verdad, pero no la hay en el _descubrimiento_ de sus relaciones, pues este se hace por análisis.\"},{\"heading\":false,\"text\":\"El que se hayan tenido que reunir varios conceptos para formar un juicio, no destruye su carácter de analítico, pues de otro modo seria menester decir que no hay ningun juicio analítico. Si se afirma: el hombre es racional; en el concepto de hombre entran dos, animal y racional, lo que no quita que el juicio sea analítico. Este carácter consiste en que como lo dice su mismo nombre, baste la descomposicion de un concepto para encontrar en él ciertos predicados, y prescinde del modo con que se ha formado el concepto que se descompone y de si se han hecho entrar en él dos ó mas conceptos.\"},{\"heading\":false,\"text\":\"[291.] De esta doctrina resulta con claridad en qué consiste la evidencia mediata. El predicado está tambien contenido en la idea del sujeto, pero la limitacion de nuestra inteligencia hace que ó estas ideas sean incompletas, o no las veamos en toda su extension, ó no distingamos bien lo que en las mismas pensamos ya de un modo confuso; y de aquí dimana el que no sea suficiente entender el significado de las palabras para ver desde luego contenido el predicado en la idea del sujeto. Además, los objetos, aun los puramente ideales, se nos presentan como dispersos; de aquí es que no conociendo el conjunto, vamos pasando sucesivamente de unos á otros, descubriendo las relaciones que tienen entre sí, á medida que los vamos aproximando.\"},{\"heading\":false,\"text\":\"[292.] De lo dicho se infiere que en el órden puramente ideal todos los juicios son analíticos, pues todo conocimiento de este órden se hace con la intuicion de lo que hay en un concepto mas ó menos complicado, y que no hay mas síntesis que la necesaria para aproximar los objetos reuniendo sus conceptos en uno total que nos sirva para el descubrimiento de la relacion de los parciales.\"},{\"heading\":false,\"text\":\"[293.] La x pues de que nos habla Kant, y cuyo despejo es uno de los problemas mas importantes de la filosofía, no será mas que la facultad del entendimiento para reunir en un concepto total conceptos de cosas diferentes y descubrir en aquel las relaciones que estos tienen entre sí. Esta facultad no es un descubrimiento nuevo; pues que con este ó aquel nombre, la han reconocido todas las escuelas. Nadie ha disputado al entendimiento la facultad de comparar; y la comparacion es una operacion por la cual el entendimiento se pone á la vista dos ó mas conceptos para conocer las relaciones que tienen entre sí. En este acto se forma un concepto total del cual los comparados son una parte; así como hemos visto que en las construcciones geométricas para averiguar la relacion de varias figuras, se construye una que las comprenda todas y que sea como el campo en el cual se haga la comparacion.\"},{\"heading\":false,\"text\":\"Basta por ahora lo dicho sobre los juicios analíticos y sintéticos, pues que no proponiéndome tratarlos sino en general, y en cuanto tienen relacion con la certeza, no descenderé á pormenores haciendo aplicacion á varias ideas, cuyo análisis corresponde á otros lugares de esta obra.\"}]},{\"title\":\"CAPÍTULO XXX\",\"blocks\":[{\"heading\":false,\"text\":\"CRITERIO DE VICO.\"},{\"heading\":false,\"text\":\"[294.] Con las cuestiones de los capítulos anteriores relativas á la evidencia inmediata y á la mediata, está enlazada la doctrina de Vico sobre el criterio de la verdad. Cree este filósofo que dicho criterio consiste en haber hecho la verdad conocida; que nuestros conocimientos son completamente ciertos cuando se verifica dicha circunstancia; y que van perdiendo de su certeza á proporcion que el entendimiento pierde su carácter de causa con respecto á los objetos. Dios, causa de todo, lo conoce perfectamente todo; la criatura, de causalidad muy limitada, conoce tambien con mucha limitacion; y si en alguna esfera puede asemejarse á lo infinito, es en ese mundo ideal que ella propia se construye, y que puede extender á su voluntad, sin que sea dable señalarle un linde que no pueda todavía retirar.\"},{\"heading\":false,\"text\":\"Dejemos hablar al mismo autor. «Los términos _verum et factum_, lo verdadero y lo hecho, se ponen el uno por el otro entre los latinos, o como dice la escuela, se convierten. Para los latinos _intelligere_, comprender, es lo mismo que leer con claridad y conocer con evidencia. Llamaban _cogitare_ lo que en italiano se dice _pensare e andar raccogliendo_; _ratio_, razon, designaba entre ellos una coleccion de elementos numéricos, y ese don que distingue al hombre de los brutos y constituye su superioridad. Llamaban ordinariamente al hombre un animal partícipe de la razon (_rationis particeps_) y que por tanto no la posee absolutamente. Así como las palabras son los signos de las ideas, las ideas son los signos y representaciones de las cosas. Así como leer _legere_, es reunir los elementos de la escritura de los cuales se forman las palabras, la inteligencia, _intelligere_, consiste en reunir todos los elementos de una cosa, de lo que resulta la idea perfecta. Por donde podemos conjeturar que los antiguos italianos admitian la doctrina siguiente sobre lo verdadero: lo verdadero es lo hecho mismo; y por consiguiente Dios es la verdad primera porque es el primer hacedor (_factor_), la verdad infinita porque ha hecho todas las cosas, la verdad absoluta, pues que representa todos los elementos de las cosas tanto internos como externos, porque los contiene. Saber es reunir los elementos de las cosas; de donde se sigue que el pensamiento (_cogitatio_) es propio del espíritu humano, y la inteligencia lo es del espíritu divino: porque Dios reune todos los elementos de las cosas internos y externos á causa de que los contiene, y él propio es quien los dispone; mientras el espíritu humano limitado como es, y fuera de todo lo que no es él mismo, puede aproximar los puntos extremos mas nó reunirlo todo; de manera que puede pensar sobre las cosas, pero no comprenderlas; y hé aquí por qué participa de la razon, mas no la posee. Para aclarar estas ideas con una comparacion: lo verdadero divino es una imágen sólida de las cosas, como una figura plástica; lo verdadero humano es una imágen plana sin profundidad, como una pintura. Así como lo verdadero divino lo es, porque Dios en el acto mismo de su conocimiento dispone y produce, lo verdadero humano es para las cosas en que el hombre dispone y crea de una manera semejante. La ciencia es el conocimiento del modo con que la cosa se hace; conocimiento en el cual el espíritu mismo hace el objeto, pues que recompone sus elementos. El objeto es un sólido para Dios que comprende todas las cosas; una superficie para el hombre que no comprende sino lo exterior. Establecidos estos puntos para ponerlos mas fácilmente en armonía con nuestra religion, conviene saber, que los antiguos filósofos de Italia identificaban lo verdadero con lo hecho, porque creian el mundo eterno: asi los filósofos paganos adoraron un Dios que obraba siempre _ad extra_, cosa desechada por nuestra teología. Por cuyo motivo en nuestra religion, en la cual profesamos que el mundo ha sido criado de la nada en el tiempo, es necesario establecer una distincion, identificando lo verdadero criado con lo hecho, y lo verdadero increado con el _engendrado_ (genito). Así la Sagrada Escritura con una elegancia verdaderamente divina, llama Verbo à la sabiduría de Dios que contiene en sí las ideas de todas las cosas y los elementos de las ideas mismas. En este Verbo, lo verdadero es la comprension misma de todos los elementos de este universo, la cual podria formar infinitos mundos. De estos elementos conocidos y contenidos en la omnipotencia divina, se forma el Verbo real absoluto, conocido desde toda la eternidad por el Padre y engendrado por él, tambien desde toda la eternidad.» (De la antigua sabiduría de la Italia, lib. 1. cap. 1).\"},{\"heading\":false,\"text\":\"[295.] De estos principios saca Vico consecuencias muy trascendentales, entre ellas la de explicar la causa de la division de nuestra ciencia en muchos ramos, y de los diferentes grados de certeza con que se distinguen. Las matemáticas son las mas ciertas porque son una especie de creacion del entendimiento, el que partiendo de la unidad y de un punto, se construye un mundo de formas y de números, prolongando las líneas y multiplicando la unidad, hasta lo infinito. Así conoce lo que él mismo produce, resultando que los mismos teoremas tenidos vulgarmente como objetos de pura contemplacion, han menester accion como los problemas. La mecánica ya es menos cierta que la geometría y la aritmética, porque considera el movimiento realizado en las máquinas; y la física lo es todavía menos, porque no considera como la mecánica el movimiento externo de las circunferencias sino el movimiento interno de los centros. En las ciencias del órden moral hay todavía menos certeza, porque no se ocupan de los movimientos de los cuerpos, los cuales dimanan de un orígen cierto y constante que es la naturaleza, sino de los movimientos de las almas que se realizan á grandes profundidades y con frecuencia nacen del capricho.\"},{\"heading\":false,\"text\":\"«La ciencia humana, dice, ha nacido de un defecto del espíritu humano, que en su extrema limitacion está fuera de todas las cosas, no contiene nada de lo que quiere conocer, y por consiguiente no puede hacer la verdad á la cual aspira. Las ciencias mas ciertas son las que expian el vicio de su orígen, y se asimilan como creacion á la ciencia divina, es decir, aquellas en que lo verdadero y lo hecho son mutuamente convertibles.\"},{\"heading\":false,\"text\":\"«De lo que precede se puede inferir que el criterio de lo verdadero y la regla para reconocerlo, es el _haberlo hecho_; por consiguiente la idea clara y distinta que tenemos de nuestro espíritu, no es un criterio de lo verdadero, y no es ni aun un criterio de nuestro espíritu; porque el alma conociéndose, no se hace á sí misma; y pues que no se hace, no sabe la manera con que se conoce. Como la ciencia humana tiene por base la abstraccion, las ciencias son tanto menos ciertas cuanto mas se acercan á la materia corporal................. ....................................................................\"},{\"heading\":false,\"text\":\"«Para decirlo en una palabra, lo verdadero es convertible con lo bueno, si lo que es conocido como verdadero tiene su ser del espíritu que lo conoce, imitando la ciencia humana á la divina por la cual Dios conociendo lo verdadero lo engendra _en lo interior_ en la eternidad, y lo hace _en lo exterior_ en el tiempo. En cuanto al criterio de verdad es para Dios el comunicar la bondad á los objetos de su pensamiento (vidit Deus quod essent bona): y para los hombres el haber _hecho lo verdadero que conocen_.» (Ibidem § 1).\"},{\"heading\":false,\"text\":\"[296.] No puede negarse que el sistema de Vico revela un pensador profundo que ha meditado detenidamente sobre los problemas de la inteligencia. La línea divisoria en cuanto á la certeza de las ciencias es sobre manera interesante. A primera vista nada mas especioso que la diferencia señalada entre las ciencias matemáticas y las naturales y morales. Las matemáticas son absolutamente ciertas porque son obra del entendimiento, son como el entendimiento las ve, porque él mismo las construye; al contrario, las naturales y morales versan sobre objetos independientes de la razon, que tienen por sí mismos una existencia propia, y de aquí es que el entendimiento conoce poco de ellos; y en esto se engaña con tanta mas facilidad cuanto mas penetra en la esfera donde su construccion no alcanza. He llamado especioso á este sistema porque examinado á fondo se le encuentra destituido de cimiento sólido; al paso que he reconocido en su autor un pensamiento profundo, porque efectivamente lo hay en considerar las ciencias bajo el punto de vista que él las considera.\"},{\"heading\":false,\"text\":\"[297.] La inteligencia solo conoce lo que hace. Esta proposicion que resume todo el sistema de Vico, no puede afianzarse en nada; y el filósofo napolitano se encontraría detenido en sus primeros pasos con solo pedirle la prueba de lo que afirma. ¿Por qué la inteligencia solo conoce lo que hace? ¿Por qué el problema de la representacion no ha de tener solucion posible sino en la causalidad? Creo haber demostrado que á mas de este orígen se encuentra otro en la identidad, y tambien en la idealidad enlazado del modo debido con la causalidad.\"},{\"heading\":false,\"text\":\"[298.] Entender no es causar: puede haber, y la hay en efecto, una inteligencia productora; pero en general el acto de entender y el de causar ofrecen ideas distintas. La inteligencia supone una actividad, porque sin ésta no se concibe aquella vida íntima que distingue al ser inteligente: pero esta actividad no es productora de los objetos conocidos, se ejerce de un modo inmanente sobre estos objetos, presupuestos ya en union con la inteligencia, mediata ó inmediatamente.\"},{\"heading\":false,\"text\":\"[299.] Si la inteligencia estuviese condenada á no conocer sino lo que ella misma hace, no es fácil concebir cómo el acto de entender pudiera comenzar; colocándonos en el momento inicial, no sabremos cómo explicar el desarrollo de esta actividad: porque si no puede entender sino lo que ella hace, ¿qué entenderá en el primer momento cuando aun no ha hecho nada? En el sistema que nos ocupa, no hay otro objeto para la inteligencia que el que ella misma se produce; por otra parte entender sin objeto entendido es una contradiccion; así, en el momento inicial, no habiendo nada producido, no puede haber nada entendido; y por consiguiente la inteligencia es inexplicable. No cabe suponer que la actividad se despliega ciegamente; no hay nada ciego cuando se trata de representacion, y la actividad productiva se refiere esencialmente á cosas representadas en cuanto representadas. El que estas sean producidas en lo exterior con existencia distinta de la representacion intelectual, es indiferente para el problema de la inteligencia. Así, como explica el mismo Vico, la razon humana conoce lo que ella construye en un mundo puramente ideal, y Dios conoce al Verbo que engendra, no obstante de que este Verbo no está fuera de la esencia divina sino identificado con ella.\"},{\"heading\":false,\"text\":\"[300.] No se contenta el filósofo napolitano con aplicar su sistema á la razon humana; lo generaliza á todas las inteligencias, inclusa la divina; bien que procurando con loable religiosidad, conciliar sus doctrinas ideológicas con los dogmas del cristianismo. Y en verdad que los problemas de la inteligencia no pueden resolverse cumplidamente sino encumbrándose á tanta altura. Para conocer al entendimiento humano, no basta seguir los pasos de la humana razon; es necesario proponerse además el problema general de la inteligencia misma, ora se limite como la nuestra á flacas vislumbres, ora se dilate por las regiones de la infinidad en un piélago de luz. Las sublimes palabras con que san Juan comienza su Evangelio, encierran, á mas de la verdad augusta enseñada por la inspiracion divina, doctrinas trascendentales que aun miradas bajo un punto de vista meramente filosófico, son de una importancia mayor de la que encontrarse pudiera en las palabras de ningun hombre.\"},{\"heading\":false,\"text\":\"Al identificar lo verdadero con lo hecho, advierte Vico que segun el dogma de nuestra religion, es necesario distinguir entre lo creado y lo increado. A lo primero se le debe llamar hecho, á lo segundo engendrado. Pondera la elegancia divina con que la Escritura santa llama Verbo á la Sabiduría de Dios, en la cual se contienen las ideas de todas las cosas, y los elementos de las ideas mismas; sin embargo, las palabras de Vico son muy inexactas, cuando al explicar la concepcion de dicho Verbo, parecen dar á entender que solo resulta de los elementos conocidos y contenidos en la omnipotencia divina. «En este Verbo, dice, lo verdadero es la comprension misma de todos los elementos de este universo, la cual podria formar infinitos mundos; de estos elementos conocidos y contenidos en la omnipotencia divina, se _forma_ el Verbo real, absoluto, conocido desde toda la eternidad por el Padre, y engendrado por él desde toda la eternidad.» (De la Antigua Sabiduría de la Italia, lib. 1, cap. 1.) Si el autor quiere significar que el Verbo es concebido por solo el conocimiento de lo contenido en la omnipotencia divina, su asercion es falsa; si no quiso significar esto, su locucion es inexacta.\"},{\"heading\":false,\"text\":\"Santo Tomás (1 part., cuest. 34, art. 3.)pregunta si en el nombre del Verbo se contiene alguna relacion á la criatura «utrum in nomine Verbi importetur respectus ad creaturam» y allí resuelve la cuestion con admirable laconismo y solidez. «Respondo que en el Verbo se contiene relacion á la criatura. Dios conociéndose á sí mismo, conoce á toda criatura. El verbo pues, concebido en la mente, es representativo de todo aquello que actualmente se entiende. Así en nosotros hay diversos verbos segun son diversas las cosas entendidas. Pero como Dios con un solo acto se conoce á sí y á todas las cosas, su único Verbo es expresivo no solo del padre sino tambien de las criaturas. Y asi como la ciencia de Dios en cuanto á Dios, es solo conocimiento, pero en cuanto á las criaturas es conocimiento y causa, así el Verbo de Dios con respecto á Dios Padre, es solo expresivo, pero con relacion á las criaturas es expresivo y productivo, por cuya razon se dice en el salmo 32: dijo, y las cosas fueron hechas, porque en el Verbo se contiene la razon productiva de las cosas que Dios hace[1].»\"},{\"heading\":false,\"text\":\"[Footnote 1: Respondeo dicendum, quod in Verbo importatur respectus ad creaturam. Deus enim cognoscendo se, cognoscit omnem creaturam. Verbum igitur in mente conceptum est representativum omnis eius, quod actu intelligitur. Unde in nobis sunt diverso verbo, secundum diversa, quæ intelligimus. Sed quia Deus uno actu et se, et omnia intelligit, unicum verbum eius est expressivum, non solum Patris sed etiam creaturarum. Et sicut Dei scientia, Dei quidem est congnoscitiva tantum, creaturarum autem cognoscitiva et factiva; ila verbum Dei, eius quod in Deo Patre est, est expressivum tantum, creaturarum vero est expressivum, et operativum, et propter hoc dicitur in Psal. 32. Dixit, et facta sunt, quia importatur in verbo ratio factiva eorum qua Deus facit.]\"},{\"heading\":false,\"text\":\"Por este pasaje se echa de ver que segun la doctrina de Santo Tomás, el Verbo expresa tambien á las criaturas, pero que él es concebido no solo por el conocimiento de estas, sino y primariamente, por el conocimiento de la esencia divina; «el Padre, dice en otra parte el Santo Doctor, entendiéndose á sí y al Hijo y al Espíritu Santo y á todas las cosas contenidas en su ciencia, concibe al Verbo de manera que toda la Trinidad es _dicha_ en el Verbo y tambien toda criatura[2].»\"},{\"heading\":false,\"text\":\"[Footnote 2: Pater enim intelligendo se et Filium et Spiritum Sanctum et omnia alia quæ eius scientia continentur, concipit Verbum, ut sic tota Trinitas Verbo dicatur, et etiam omnis creatura (1. par. q. 31. art. 1 - ad. 3.)]\"},{\"heading\":false,\"text\":\"[301.] Hay tambien otra doctrina de Santo Tomás que se opone al sistema de Vico. Segun éste, la inteligencia conoce lo que hace, y solo lo que hace, y solo por qué lo hace; pues que lo hecho y lo verdadero son convertibles, siendo lo hecho el único criterio de verdad. Esta doctrina la aplica Vico á la inteligencia divina sustituyendo á _hecho, engendrado;_ con lo cual invierte el órden de las ideas, pues que ni segun nuestro modo de concebir, Dios entiende porque engendra, sino que engendra porque entiende; no se concibe la generacion del Verbo sin concebir antes la inteligencia. «En quien entiende, dice Santo Tomás, por lo mismo que entiende, procede alguna cosa dentro de él, lo cual es el concepto de la cosa entendida, y proviene de la fuerza intelectual y de su noticia[3]».\"},{\"heading\":false,\"text\":\"[Footnote 3: Quicumque autem intelligit ex hoc ipso quod intelligit, procedit aliquid intra ipsum, quod est conceptio rei intellectæ ex vi intellectiva proveniens et ex eius notitia procedens. Quam quidem conceptionem vox significat, et dicitur verbum cordis, significatum verbo vocis. (1. p. q. 27. art. 1.).]\"},{\"heading\":false,\"text\":\"Esta doctrina de Santo Tomás confirma la opinion expuesta mas arriba, sobre la imposibilidad de explicar el acto intelectual por sola la produccion. Es evidente que para producir en el órden intelectual, es necesario entender ya: y por consiguiente en el momento inicial de toda inteligencia, no puede ponerse la accion productiva, sino la intuicion del objeto. En este mismo sentido habla Santo Tomás, en el modo que hablar puede el hombre de las cosas divinas: no funda en la generacion del Verbo la inteligencia divina; antes por el contrario, en la inteligencia funda la generacion del Verbo. Dios, segun Santo Tomás, engendra al Verbo porque entiende, no entiende porque engendra: y si bien en este Verbo pone el Santo Doctor la expresion de todo cuanto está contenido en Dios, es presuponiendo la inteligencia divina, con la cual se hace posible decir ó proferir el Verbo. El órden de los conceptos, pues, es el siguiente: entendimiento, objeto entendido, verbo procedente de la accion de entender por el cual el ser inteligente se expresa, se dice á sí propio, la misma cosa entendida. Aplicadas estas ideas á Dios, serán: Dios Padre inteligente; esencia divina con todo lo que ella contiene, entendida; Verbo ó Hijo engendrado por este acto intelectual, y expresivo de todo lo que se encierra en este acto generador.\"},{\"heading\":false,\"text\":\"[302.] No es mi ánimo inculpar á Vico; solo he querido hacer notar la inexactitud de sus palabras, haciéndole por otra parte la justicia de creer que él entendia las cosas del mismo modo que las he explicado, aunque no acertó á expresarse con la debida claridad. Pasemos ahora á considerar el sistema de Vico bajo puntos de vista menos delicados.\"},{\"heading\":false,\"text\":\"Es fácil notar que admitiendo lo hecho por único criterio de verdad, la inteligencia queda incomunicada con todo lo que no sean sus obras. Ni á sí misma se puede conocer, porque no se hace. «El alma, conociéndose, dice Vico, no se hace, y por lo mismo no sabe la manera con que se conoce;» de suerte que prescindiendo del problema de la inteligibilidad que se ha ventilado mas arriba (cap. XII,) niega Vico á nuestra alma el criterio de sí propia por la única razon de que no se causa á sí misma. Entonces, la identidad lejos de ser un orígen de representacion como se ha probado (cap. XI), es incompatible con ella; nada podrá conocerse á sí mismo porque nada se hace á sí mismo.\"},{\"heading\":false,\"text\":\"De esto resulta un gravísimo error; pues que se infiere que tampoco Dios puede conocerse á sí mismo; porque no se causa á sí mismo. Ni basta decir que se conoce en el Verbo, pues que si no se supone la inteligencia, el Verbo es imposible.\"},{\"heading\":false,\"text\":\"[303.] Todo el mundo de la realidad distinto del ser intelectual, será desconocido para siempre; de donde se deduce que el sistema de Vico lleva al escepticismo mas riguroso. ¿Qué admite el filósofo napolitano? el conocimiento por el espíritu, de la obra misma del espíritu; en esto se comprenden los actos de conciencia y todos los objetos puramente ideales que en ella nos creamos; esto tambien lo admiten los escépticos, ninguno de ellos dejará de convenir que hay en nosotros conciencia, que hay un mundo ideal, obra de esta conciencia misma ó atestiguado por ella.\"},{\"heading\":false,\"text\":\"Si pues no admitimos otro criterio de verdad que lo hecho, abrimos la puerta al escepticismo, abandonamos el mundo de las realidades para establecernos en el de las apariencias. No obstante ¡singularidad de las opiniones humanas! Vico pensaba todo lo contrario; él creia que solo con su sistema era posible rebatir á los escépticos. Es curioso oirle decir con admirable seriedad «el único medio de destruir el escepticismo es tomar por criterio de verdad, que cada cual está seguro de lo verdadero que hace.»\"},{\"heading\":false,\"text\":\"¿En qué puede fundarse tamaña extrañeza? oigamos al filósofo, que dice cosas muy buenas, pero que no se alcanza cómo pueden conducir á la destruccion del escepticismo. «Los escépticos van repitiendo siempre que las cosas les _parecen_, pero que ignoran lo que ellas son en realidad; confiesan los efectos y conceden por consiguiente que estos efectos tienen sus causas; pero afirman que no conocen á estas porque ignoran el género ó la forma segun la cual las cosas se hacen. Admitid estas proposiciones, y retorcedlas contra ellos de la manera siguiente: esta comprension de causas que contiene todos los géneros ó todas las formas bajo las cuales son dados todos los efectos, cuyas apariencias confiesa ver el escéptico, pero cuya esencia real asegura ignorar; esta comprension de causas se halla en la primera verdad que las comprende todas, y donde todas están contenidas hasta las últimas. Y pues que esta verdad las comprende todas, es infinita, y no excluye ninguna, y tiene la prioridad sobre el cuerpo que no es mas que un efecto. Por consiguiente esta verdad es alguna cosa espiritual, en otros términos es Dios, el Dios que confesamos nosotros los cristianos; sobre esta verdad debemos medir la verdad humana, pues que la verdad humana es aquella cuyos elementos hemos ordenado nosotros mismos, aquello que contenemos en nosotros y que por medio de ciertos postulados podemos prolongar y seguir hasta lo infinito. Ordenando estas verdades las conocemos, y las hacemos á un mismo tiempo; y hé aquí por qué en este caso poseemos el género ó la forma segun la cual hacemos» (Ibid. 3.).\"},{\"heading\":false,\"text\":\"En esta refutacion de los escépticos nada encuentro que pueda destruir el escepticismo. Aun suponiendo que todos admiten el principio de causalidad, lo que no es exacto, ¿qué se puede sacar de este principio cuando se señala por único criterio la obra del mismo entendimiento que ha de emplear el principio? Si no hay mas criterio que el de causalidad, el entendimiento se encuentra aislado, sin poder ir mas allá en el órden de los efectos, que hasta donde llegan los producidos por él mismo; y en el de las causas, no puede subir mas arriba que de sí propio; porque si sube, ya conoce cosas que él no ha hecho, á saber, la causa que le ha producido á él. En este supuesto los escépticos quedan triunfantes; el conocimiento se reduce al mundo interior, á las simples apariencias; cuando de estas se quiera salir se tropieza con el obstáculo del criterio único, el cual se opone al conocimiento de todo lo _no hecho_ por el entendimiento mismo. Entonces la realidad nos está vedada y nos hallamos separados de ella por un vallado insalvable. El mundo en sí, será lo que se quiera suponer; mas para nosotros no será nada. Esta ley se aplicará á todas las inteligencias, de manera que la realidad solo podrá ser conocida por la causa primera.\"},{\"heading\":false,\"text\":\"Estas consecuencias son inadmisibles en no arrojándose sin reserva al campo del escepticismo, y no obstante son inevitables en el sistema de Vico. Original ocurrencia la de querer combatir el escepticismo con un sistema que le abre la mas anchurosa puerta.\"}]},{\"title\":\"CAPÍTULO XXXI\",\"blocks\":[{\"heading\":false,\"text\":\"CONTINUACION.\"},{\"heading\":false,\"text\":\"[304.] Si en algun terreno pudiera ser admitido el criterio del filósofo napolitano, seria en el de las verdades ideales. Como estas prescinden absolutamente de la existencia, puede suponérselas conocidas hasta por un entendimiento que no las produzca en la realidad. En cuanto conocidas por el entendimiento nada envuelven de real, y por consiguiente no entrañan ninguna condicion que exija fuerza productiva, á no ser que esta se refiera á un órden de pura idealidad. En este órden parece que la razon humana produce efectivamente: porque tomando por ejemplo la geometría, es fácil de notar que aun en su parte mas elevada y de mayor complicacion, no es mas que una especie de construccion intelectual donde solo se halla lo que la razon ha puesto. Esta razon es la que á fuerza de trabajo ha ido reuniendo los elementos y combinándolos de distintas maneras hasta llegar al asombroso resultado del cual pueda decir con verdad: esto es mi obra.\"},{\"heading\":false,\"text\":\"Sígase con atenta observacion el desarrollo de la ciencia geométrica y se echará de ver que la dilatada serie de axiomas, teoremas, problemas, demostraciones, resoluciones, arranca de unos cuantos postulados, y que continúa siempre con la ayuda ó de estos mismos ó de otros que la razon excogita, conforme lo exige la necesidad ó la utilidad.\"},{\"heading\":false,\"text\":\"¿Qué es la línea? una serie de puntos. La línea pues es una construccion intelectual, no envuelve otra cosa que las fluxiones sucesivas de un punto. ¿Qué es el triángulo? una construccion intelectual en que se reunen los extremos de tres líneas. ¿Qué es el círculo? es otra construccion intelectual, el espacio encerrado por la circunferencia, formada á su vez por el extremo de una línea que gira al rededor de un punto. ¿Qué son todas las demás curvas? líneas marcadas por el movimiento de un punto con arreglo á una cierta ley de inflexion. ¿Qué es la superficie? ¿no se engendra su idea con el movimiento de una línea, así como el sólido con el movimiento de una superficie? ¿Qué son todos los objetos de la geometría sino líneas, superficies y sólidos de varias especies y con diversas combinaciones?\"},{\"heading\":false,\"text\":\"La aritmética universal es una creacion del entendimiento, ora la consideremos en la aritmética propiamente dicha, ora en el álgebra. El número es un conjunto de unidades; el entendimiento es quien las reune: el dos no es mas que uno mas uno, el tres es dos mas uno, y de esta suerte se forman todos los valores numéricos, por consiguiente las ideas expresivas de estos valores contienen una creacion de nuestro espíritu, son su obra, nada encierran sino lo que él mismo ha puesto en ellas.\"},{\"heading\":false,\"text\":\"Ya se ha notado que el álgebra es una especie de lenguaje. Sus reglas tienen una parte de convencionales, y las fórmulas mas complicadas se resuelven en un principio convencional. Tomemos una muy sencilla: $a^0=1$; ¿por qué? porque $a^0=a^{n-n}$; ¿por qué? La razon es porque se ha convenido en señalar la division por la resta de los esponentes; y de consiguiente $\\\\frac{a^n}{a^n}$ que evidentemente es igual á uno; se puede expresar por $\\\\frac{a^n}{a^n}=a^{n-n}=a^0$.\"},{\"heading\":false,\"text\":\"[305.] Estas observaciones parecen probar que en realidad es verdadero el sistema de Vico en lo que concierne á las matemáticas puras, es decir á una ciencia del órden puramente ideal. Aunque tal vez podria ensayarse lo mismo con relacion á otras ciencias, por ejemplo á la metafísica, no lo haré, porque en saliendo de las matemáticas, ya es difícil encontrar un terreno donde no haya opiniones opuestas. Además, que en habiendo manifestado hasta qué punto es admisible el sistema de Vico en las ciencias matemáticas, quedarán tambien resueltas las dificultades que puede haber en lo que concierne á otros ramos.\"},{\"heading\":false,\"text\":\"[306.] El entendimiento construye en un órden puramente ideal, es innegable; y en esto convienen todas las escuelas. Nadie duda de que la razon supone, combina, compara, deduce: operaciones que no pueden concebirse sin una especie de construccion intelectual. En este caso el entendimiento sabe lo que hace, porque su obra le está presente; cuando combina sabe lo que combina, cuando compara y deduce, sabe lo que deduce y compara, cuando estriba en ciertas suposiciones que él mismo ha establecido, sabe en qué consisten, pues se apoya en ellas.\"},{\"heading\":false,\"text\":\"[307.] El entendimiento conoce lo que hace, pero conoce mas de lo que hace; hay verdades que no son ni pueden ser su obra, pues que son el cimiento de todas sus obras: por ejemplo el principio de contradiccion. ¿Puede decirse que la imposibilidad de ser y no ser una cosa á un mismo tiempo, sea obra de nuestra razon? nó ciertamente. La razon misma es imposible si el principio no está supuesto ya; el entendimiento le encuentra en si propio como una ley absolutamente necesaria, como una condicion _sine qua non_ de todos sus actos. Hé aquí fallido el criterio de Vico: «el entendimiento solo conoce la verdad que hace;» sin embargo la verdad del principio de contradiccion, el entendimiento la conoce y no la hace.\"},{\"heading\":false,\"text\":\"[308.] Los hechos de conciencia son conocidos por la razon, no obstante de que no son su obra. Estos hechos á mas de estar presentes á la conciencia, son objeto de las combinaciones de la razon; hé aquí otro caso en que falla el criterio de Vico.\"},{\"heading\":false,\"text\":\"[309.] Aun en las cosas que son obra puramente intelectual, el entendimiento conoce lo que hace, pero no hace lo que quiere; de lo contrario seria menester decir que las ciencias son absolutamente arbitrarias; en vez de los resultados geométricos que tenemos ahora, podriamos tener tantos otros cuantos son los hombres que piensan en líneas, superficies y sólidos. ¿Esto qué indica? que la razon está sometida á ciertas leyes, que sus construcciones están ligadas á condiciones de que no se puede prescindir: una de ellas es el principio de contradiccion, al cual no se puede faltar nunca so pena de anonadar todo conocimiento. Es verdad que se llega á sacar el volúmen de una esfera por medio de una serie de construcciones intelectuales; pero yo pregunto: ¿pueden dos entendimientos llegar á dos valores diferentes? nó, esto es absurdo; seguirán quizás diversos caminos, expresarán sus demostraciones y sus resultados de distintas maneras, pero el valor es el mismo; si hay diferencia, hay error por una ú otra parte.\"},{\"heading\":false,\"text\":\"[310.] Profundizando la materia se echa de ver que la construccion intelectual de que nos habla Vico, es una cosa generalmente admitida. Lo que hay de nuevo en el sistema de este filósofo son dos cosas, una buena y otra mala: la buena, es el haber indicado una de las razones de la certeza de las matemáticas y demás ciencias de un órden puramente ideal; la mala es el haber exagerado el valor de su criterio.\"},{\"heading\":false,\"text\":\"He dicho que el sistema del filósofo napolitano expresaba un hecho generalmente reconocido, mas que por su parte lo habia exagerado. No cabe duda en que el entendimiento crea en algun modo las ciencias ideales ¿pero de qué manera? nó de otra sino tomando postulados, y combinando los datos de varias maneras. Aquí se acaba su fuerza creatriz; porque en esos postulados y en esas combinaciones encuentra verdades necesarias que él no ha puesto.\"},{\"heading\":false,\"text\":\"¿Qué es el triángulo en el órden puramente ideal? una creacion del entendimiento: él es quien dispone las líneas en forma triangular, él es quien, salva esa misma forma, la modifica de infinitas maneras. Hasta aquí no hay mas que un postulado y diferentes combinaciones del mismo. Pero las propiedades del triángulo dimanan por absoluta necesidad de las condiciones del mismo postulado; estas propiedades el entendimiento no las hace, las encuentra. El ejemplo del triángulo es aplicable á toda la geometría; el entendimiento toma un postulado, esta es su obra libre, con tal que no se ponga en lucha con el principio de contradiccion; de este postulado dimanan consecuencias absolutamente necesarias, independientes de la accion intelectual, que encierran una verdad absoluta conocida por el entendimiento mismo. Por consiguiente con respecto á ellas, es falso el decir que las hace. Un hombre pone un cuerpo en tal disposicion que abandonado á su gravedad cae al suelo; ¿es el hombre quien le da la fuerza de caer? nó por cierto, sino la naturaleza. Lo que el hombre hace es poner la condicion bajo la cual la fuerza de gravedad pueda producir sus efectos: desde que la condicion existe, la caida es inevitable. Hé aquí una semejanza que manifiesta con claridad y exactitud lo que sucede en el órden puramente ideal: el entendimiento pone las condiciones, pero de estas dimanan otras verdades, _no hechas_ por el entendimiento, sino conocidas; esta verdad es absoluta, es como si dijéramos la fuerza de gravedad en el órden de las ideas. Hé aquí deslindado lo que hay de admisible é inadmisible en el sistema de Vico. Admisible, la fuerza de combinacion, hecho generalmente reconocido; inadmisible, la exageracion de este hecho extendido á todas las verdades, cuando solo comprende los postulados en sus varias combinaciones.\"},{\"heading\":false,\"text\":\"En las reglas algebráicas hay una parte de convencional, en cuanto se refieren á la _expresion_; porque es evidente que esta podria haber sido diferente. Pero supuesta la expresion, el desarrollo de las reglas, no es convencional, sino necesario. En la misma expresion a^n/a^n, claro es que el número de veces que la cantidad a entra por factor, podia haberse expresado de infinitas maneras; pero supuesto que se ha adoptado la presente, no es convencional la regla sino absolutamente necesaria; pues que sea cual fuere la expresion, siempre es cierto que la division de una cantidad por sí misma con distintos exponentes, da por resultado la disminucion del número de veces que entra por factor; lo que se significa por la resta de los exponentes; y por tanto, si el número de veces es igual en el dividendo y en el divisor, el resultado ha de ser = 0. Por donde se echa de ver, que aun en el álgebra, lo que hace el entendimiento es poner las condiciones, y expresarlas como mejor le parece: mas aquí concluye su obra libre, pues de estas condiciones resultan verdades necesarias; él no las hace, solo las conoce.\"},{\"heading\":false,\"text\":\"El mérito de Vico en este punto consiste en haber emitido una idea muy luminosa sobre la causa de la mayor certeza en las ciencias puramente ideales. En estas el entendimiento pone él propio las condiciones bajo las cuales ha de levantar el edificio; él escoge por decirlo así el terreno, forma el plan, y levanta las construcciones con arreglo á este; en el órden real este terreno lo es previamente señalado, así como el plan del edificio y los materiales con que lo ha de levantar. En ambos casos está sometido á las leyes generales de la razon; pero con la diferencia de que en el órden puramente ideal, ha de atender á esas leyes y á nada mas; pero en el real, no puede prescindir de los objetos considerados en sí, y está condenado á sufrir todos los inconvenientes que por su naturaleza le ofrecen. Aclaremos estas ideas con un ejemplo. Si quiero determinar la relacion de los lados de un triángulo bajo ciertas condiciones, me basta suponerlas y atenerme á ellas; el triángulo ideal es en mi entendimiento una cosa enteramente exacta y además fija: si le supongo isósceles con la relacion de los lados á la base como de cinco á tres, esta razon es absoluta, inmutable, mientras yo no altere el supuesto; en todas las operaciones que haga sobre estos datos puedo engañarme en el cálculo, pero el error no provendrá de la inexactitud de los datos. El entendimiento conoce bien, porque lo conocido es su misma obra. Si el triángulo no es puramente ideal sino realizado sobre el papel ó en el terreno, el entendimiento vacila; porque las condiciones que él fija con toda exactitud en el órden ideal, no pueden ser trasladadas de la misma manera al órden real: y aun cuando lo fuesen, el entendimiento carece de medios para apreciarlo. Hé aquí por qué dice Vico con mucha verdad, que nuestros conocimientos pierden en certeza á proporcion que se alejan del órden ideal y se engolfan en la realidad de las cosas.\"},{\"heading\":false,\"text\":\"[311.] Dugald Steward se aprovecharia probablemente de esta doctrina de Vico al explicar la causa de la mayor certeza de las ciencias matemáticas. Dice que esta no se funda en los axiomas sino en las definiciones; es decir que con corta diferencia, viene á parar al sistema del filósofo napolitano de que las matemáticas son las ciencias mas ciertas, porque son una construccion intelectual fundada en ciertas condiciones que el mismo entendimiento pone, y que están expresadas por la definicion.\"},{\"heading\":false,\"text\":\"[312.] Esta diferencia entre el órden puramente ideal y el real no se habia escapado á los filósofos escolásticos. Era comun entre ellos el dicho de que de los contingentes y particulares no hay ciencia, que las ciencias solo son de las cosas necesarias y universales: sustituid á la palabra contingente la de real, pues toda realidad finita es contingente; en vez de universal poned ideal, pues lo puramente ideal es todo universal; y encontraréis expresado lo mismo con distintas palabras. Difícil es deslindar hasta qué punto se hayan aprovechado los filósofos modernos de las doctrinas de los escolásticos en lo tocante á la distincion entre los conocimientos puros y los empíricos; pero lo cierto es que en las obras de los escolásticos se hallan sobre estas cuestiones, pasajes sumamente luminosos. No fuera extraño que hubiesen sido leidos por algunos modernos, particularmente por los alemanes, cuya laboriosidad es proverbial, especialmente en lo que toca á las materias de erudicion (XXVII).\"}]},{\"title\":\"CAPÍTULO XXXII\",\"blocks\":[{\"heading\":false,\"text\":\"CRITERIO DEL SENTIDO COMUN.\"},{\"heading\":false,\"text\":\"[313.] _Sentido comun_, hé aquí una expresion sumamente vaga. Como todas las expresiones que encierran muchas y diferentes ideas, la de sentido comun debe ser considerada bajo dos aspectos, el de su valor etimológico, y el de su valor real. Estos dos valores no siempre son idénticos: á veces discrepan muchísimo; pero aun en su discrepancia, suelen conservar íntimas relaciones. Para apreciar debidamente el significado de expresiones semejantes, es preciso no limitarse al sentido filosófico y no desdeñarse del vulgar. En este último hay con frecuencia una filosofía profunda, porque en tales casos el sentido vulgar es una especie de sedimento precioso que ha dejado sobre la palabra el tránsito de la razon por espacio de muchos siglos. Sucede á menudo que entendido y analizado el sentido vulgar, está fijado el sentido filosófico, y se resuelven con facilidad suma las cuestiones mas intrincadas.\"},{\"heading\":false,\"text\":\"[314.] Es notable que aparte los sentidos corporales, haya otro criterio llamado sentido comun. _Sentido_; esta palabra excluye la reflexion, excluye todo raciocinio, toda combinacion nada de esto tiene cabida en el significado de la palabra _sentir_. Cuando sentimos, el espíritu mas bien se halla pasivo que activo; nada pone de sí propio; no da, recibe; no ejerce una accion, la sufre. Este análisis nos conduce á un resultado importante, el separar del sentido comun todo aquello en que el espíritu ejerce su actividad, y el fijar uno de los caractéres de este criterio, cual es, el que con respecto á él, no hace mas el entendimiento que someterse á una ley que siente, á una necesidad instintiva que no puede declinar.\"},{\"heading\":false,\"text\":\"[315.] _Comun_: esta palabra excluye todo lo individual, é indica que el objeto del sentido comun es general á todos los hombres.\"},{\"heading\":false,\"text\":\"Los simples hechos de conciencia son de sentido, mas nó de sentido comun; el espíritu los siente prescindiendo de la objetividad y de la generalidad; lo que experimenta en sí propio es experiencia exclusivamente suya, nada tiene que ver con la de los demás.\"},{\"heading\":false,\"text\":\"En la palabra comun, se significa que los objetos de este criterio lo son para todos los hombres, y de consiguiente se refieren al órden objetivo; pues que lo puramente subjetivo, como tal, se ciñe á la individualidad, en nada afecta á la generalidad. Esta observacion es tan exacta que en el lenguaje ordinario jamás se llama opuesto al sentido comun un fenómeno interior por extravagante que sea, con tal que se exprese simplemente el fenómeno y se prescinda de su relacion al objeto. A un hombre que dice, yo experimento tal ó cual sensacion, me parece que veo tal ó cual cosa, no se le opone el sentido comun; pero si dice: tal cosa es de tal manera, si la asercion es extravagante, se le objeta: esto es contrario al sentido comun.\"},{\"heading\":false,\"text\":\"[316.] Yo creo que la expresion, sentido comun, significa una ley de nuestro espíritu, diferente en apariencia segun son diferentes los casos á que se aplica, pero que en realidad y á pesar de sus modificaciones, es una sola, siempre la misma, y consiste en una inclinacio natural de nuestro espíritu á dar su asenso á ciertas verdades, no atestiguadas por la conciencia, ni demostradas por la razon; y que todos los hombres han menester para satisfacer las necesidades de la vida sensitiva, intelectual ó moral.\"},{\"heading\":false,\"text\":\"Poco importa el nombre si se conviene en el hecho; sentido comun, sea ó nó la expresion mas adecuada para significarle, es cuestion de lenguaje, nó de filosofía. Lo que debemos hacer es examinar si en efecto existe esta inclinacion de que hablamos, bajo qué formas se presenta, á qué casos se aplica y hasta qué punto y en qué grado puede ser considerada como criterio de verdad.\"},{\"heading\":false,\"text\":\"En la complicacion de los actos y facultades de nuestro espíritu, y en la muchedumbre y diversidad de objetos que se le ofrecen, claro es que dicha inclinacion no puede presentarse siempre con el mismo carácter y que ha de sufrir varias modificaciones, capaces de hacerla considerar como un hecho distinto, aunque en realidad no sea mas que el mismo, transformado de la manera conveniente. El mejor medio de evitar la confusion de ideas, es deslindar los varios casos en que tiene cabida el ejercicio de esta inclinacion.\"},{\"heading\":false,\"text\":\"[317.] Desde luego la encontramos con respecto á las verdades de evidencia inmediata. El entendimiento no las prueba ni las puede probar, y sin embargo necesita asentir á ellas so pena de extinguirse, como una luz que carece de pábulo. Para la vida intelectual es condicion indispensable la posesion de una ó mas verdades primitivas; sin ellas la inteligencia es un absurdo. Nos encontramos pues con un caso comprendido en la definicion del sentido comun: imposibilidad de prueba; necesidad intelectual que se ha de satisfacer con el asenso; irresistible y universal inclinacion á dicho asenso.\"},{\"heading\":false,\"text\":\"¿Hay algun inconveniente en dar á esta inclinacion el nombre de sentido comun? por mi parte no disputaré de palabras, consigno el hecho, y no necesito nada mas en el terreno de la filosofía. Convengo en que al tratarse de la evidencia inmediata, la inclinacion al asenso no suele llamarse sentido comun: esto no carece de razon. Para que se aplique con propiedad el nombre de _sentido_, es necesario que el entendimiento mas bien sienta que conozca, y en la evidencia inmediata mas bien conoce que siente. Como quiera, repito que el nombre nada importa, aunque no seria difícil encontrar algun autor grave que ha dado al criterio de evidencia el título de sentido comun; lo que deseo es consignar esa ley de nuestra naturaleza que nos inclina á dar asenso á ciertas verdades, independientes de la conciencia y del raciocinio.\"},{\"heading\":false,\"text\":\"No es solo la evidencia inmediata, la que tiene en su favor la irresistible inclinacion de la naturaleza; lo propio se verifica en la mediata. Nuestro entendimiento asiente por necesidad, no solo á los primeros principios, sí que tambien á todas las proposiciones enlazadas claramente con ellos.\"},{\"heading\":false,\"text\":\"[318.] Esta natural inclinacion al asenso, no se limita al valor subjetivo de las ideas, se extiende tambien al objetivo. Ya se ha visto que esa objetividad tampoco es demostrable directamente y _á priori_, no obstante que la necesitamos. Si nuestra inteligencia no se ha de limitar á un mundo puramente ideal y subjetivo, es preciso que no solo sepamos que las cosas nos _parecen_ tales con evidencia inmediata ó mediata, sino que _son_ en realidad como nos parecen. Hay pues necesidad de asentir á la objetividad de las ideas, y nos hallamos con la irresistible y universal inclinacion á este asenso.\"},{\"heading\":false,\"text\":\"[319.] Lo dicho de la evidencia mediata é inmediata con respecto al valor objetivo de las ideas, tiene lugar no solo en el órden puramente intelectual sino tambien en el moral. El espíritu, dotado como está de libertad, ha menester reglas para dirigirse; si los primeros principios intelectuales son necesarios para conocer, no lo son menos los morales para querer y obrar; lo que son para el entendimiento la verdad y el error, son para la voluntad el bien y el mal. A mas de la vida del entendimiento, hay la vida de la voluntad; aquel se anonada si carece de principios en que pueda estribar; esta perece tambien como ser moral, ó es una monstruosidad inconcebible, si no tiene ninguna regla cuya observancia ó quebrantamiento constituya su perfeccion ó imperfeccion. Hé aquí otra necesidad del asenso á ciertas verdades morales, y hé aquí por qué encontramos tambien esa irresistible y universal inclinacion al asenso.\"},{\"heading\":false,\"text\":\"Y es de notar, que como en el órden moral no basta conocer, sino que es necesario obrar, y uno de los principios de accion es el sentimiento, las verdades morales no solo son conocidas sino tambien sentidas: cuando se ofrecen al espíritu, el entendimiento asiente á ellas como á inconcusas, y el corazon las abraza con entusiasmo y con amor.\"},{\"heading\":false,\"text\":\"[320.] Las sensaciones consideradas como puramente subjetivas, tampoco bastan para las necesidades de la vida sensitiva. Es preciso que estemos seguros de la correspondencia de nuestras sensaciones con un mundo exterior, nó puramente fenomenal, sino real y verdadero. El comun de los hombres no posee ni la capacidad ni el tiempo que son menester para ventilar las cuestiones filosóficas sobre la existencia de los cuerpos, y decidirlas en pro ó en contra de Berkeley y sus secuaces: lo que necesita es estar enteramente seguro de que los cuerpos existen, de que las sensaciones tienen en realidad un objeto externo. Esta seguridad la poseen todos los hombres, asintiendo á la objetividad de las sensaciones, esto es, á la existencia de los cuerpos, con asenso irresistible.\"},{\"heading\":false,\"text\":\"[321.] La fe en la autoridad humana nos ofrece otro caso de este instinto admirable. El individuo y la sociedad necesitan esa fe; sin ella, la sociedad y la familia serian imposibles; el mismo individuo estaria condenado al aislamiento, y por tanto á la muerte. Sin la fe en la palabra del hombre, el linaje humano desapareceria. Esta creencia tiene distintos grados segun las diferentes circunstancias, pero existe siempre; el hombre se inclina á creer al hombre por un instinto natural. Cuando son muchos los hombres que hablan, y no tienen contra sí otros que hablan en sentido opuesto, la fuerza de la inclinacion es mayor á proporcion que es mayor el número de los testigos, hasta llegar á un punto en que es irresistible: ¿quién duda de que existe Constantinopla? y sin embargo los mas, solo lo sabemos por la palabra de otros hombres.\"},{\"heading\":false,\"text\":\"¿En qué se funda la fe en la autoridad humana? las razones filosóficas que se pueden señalar no las conoce el comun de los hombres; mas por esto su fe no deja de ser igualmente viva que la de los filósofos. ¿Cuál es la causa? es que hay una necesidad, y á su lado el instinto para satisfacerla; el hombre necesita creer al hombre, y le cree. Y nótese bien, cuanto mayor es la necesidad tanto mayor es la fe: los muy ignorantes, los imbéciles, creen todo lo que se les dice; su guia está en los demás hombres y ellos la siguen á ciegas; el tierno niño que nada conoce por sí propio, cree con absoluto abandono las mayores extravagancias; la palabra de cuantos le rodean es para él un infalible criterio de verdad.\"},{\"heading\":false,\"text\":\"[322.] A mas de los primeros principios intelectuales y morales, de la objetividad de las ideas y sensaciones, y del valor de la autoridad humana, necesita el hombre el asenso instantáneo á ciertas verdades que, si bien con la ayuda del tiempo podria demostrar, no le es permitido hacerlo, atendido el modo repentino con que se le ofrecen, exigiendo formacion de juicio y á veces accion. Para todos estos casos hay una inclinacion natural que nos impele al asenso.\"},{\"heading\":false,\"text\":\"De aquí dimana el que juzguemos instintivamente por imposible ó poco menos que imposible, obtener un efecto determinado por una combinacion fortúita: por ejemplo el formar una página de Virgilio arrojando á la aventura algunos caractéres de imprenta; el dar en un blanco pequeñísimo sin apuntar hácia él, y otras cosas semejantes. ¿Hay aquí una razon filosófica? ciertamente; pero no es conocida del vulgo. Esta razon se evidencia en la teoría de las probabilidades, y es una aplicacion instintiva del principio de causalidad y de la natural oposicion de nuestro entendimiento á suponer efecto cuando no hay causa, órden cuando no hay inteligencia ordenadora.\"},{\"heading\":false,\"text\":\"[323.] En la vida humana son necesarios en infinitos casos los argumentos de analogía; ¿cómo sabemos que el sol saldrá mañana? por las leyes de la naturaleza. ¿Cómo sabemos que continuarán rigiendo? claro es que al fin hemos de parar á la analogía: saldrá mañana porque ha salido hoy, y salió ayer, y no ha faltado nunca; ¿cómo sabemos que la primavera traerá consigo las flores, y el otoño los frutos? porque así sucedió en los años anteriores. Las razones que se pueden alegar fundando el argumento de analogía en la constancia de las leyes de la naturaleza y en la relacion de ciertas causas físicas con determinados efectos, no las conoce el comun de los hombres; pero necesita el asenso, y le tiene.\"},{\"heading\":false,\"text\":\"[324.] En todos los casos que acabo de enumerar la inclinacion al asenso se puede llamar y se llama en realidad sentido comun, excepto quizás el de la evidencia inmediata. La razon de que esta se exceptúe es que en ella, si bien no cabe demostracion, hay sin embargo vision clarísima de que el predicado está contenido en la idea del sujeto; pero en los demás casos no hay ni la demostracion, ni esa vision: el hombre asiente por un impulso natural; cuando se le objeta algo contra su creencia no llama la atencion sobre el concepto, como sucede en la evidencia inmediata; se halla completamente desconcertado, sin saber qué responder; entonces aplica á la objecion, no el nombre de error ni de absurdo, sino de despropósito, de cosa contraria al sentido comun.\"},{\"heading\":false,\"text\":\"Veámoslo en algunos ejemplos. Supóngase á la vista un gran monton de arena en el cual se arroja al acaso un grano muy pequeño, revolviendo en seguida en todas direcciones; llega un hombre y dice: voy á meter la mano en el monton y á sacar al instante el grano oculto; ¿qué se le objeta á este hombre? ¿qué le responden los circunstantes? nada; desconcertados se mirarán unos á otros diciéndose de palabra ó con la vista: ¡qué despropósito! no tiene sentido comun. Otro dice: todo lo que vemos es nada, ni hay mundo externo, ni nosotros tenemos cuerpo. Otro dice eso que nos cuentan de que existe una ciudad llamada Lóndres, no es verdad. En todos estos casos nadie sabe qué objetar: se oye el desatino, se le rechaza por un impulso natural, el espíritu siente que aquello es un desatino, sin verlo.\"},{\"heading\":false,\"text\":\"[325.] El sentido comun, ¿es criterio seguro de verdad? ¿lo es en todos los casos? ¿en cuáles? ¿qué caractéres debe poseer para ser tenido como criterio infalible? esto es lo que vamos á examinar.\"},{\"heading\":false,\"text\":\"El hombre no puede despojarse de su naturaleza; cuando esta habla, la razon dice que no se la puede despreciar. Una inclinacion natural es á los ojos de la filosofía una cosa muy respetable, por solo ser natural; á la razon y al libre albedrío corresponde el no dejarla extraviar. Lo que es natural en el hombre no es siempre enteramente fijo como en los brutos. En estos el instinto es ciego, porque debe serlo donde no hay razon ni libertad. En el hombre las inclinaciones naturales están subordinadas en su ejercicio, á la libertad y á la razon: por esto, cuando se las llama instintos, la palabra debe tener acepcion muy diferente de la que le damos al aplicarla á los brutos. Esto que sucede en el órden moral, se verifica tambien en el intelectual: no solo debemos cuidar de nuestro corazon sino tambien de nuestro entendimiento: ambos están sujetos á la ley de perfectibilidad; el bien y el mal, la verdad y el error son los objetos que se nos ofrecen; la naturaleza misma nos dice cuál es el sendero que debemos tomar, pero no nos fuerza á tomarle: delante tenemos la vida y la muerte: lo que nos agrada, aquello se nos da.\"},{\"heading\":false,\"text\":\"[326.] Independientemente de la accion del libre albedrío, hay en el hombre una cualidad muy á propósito para que las inclinaciones naturales se desvien con frecuencia de su objeto: la debilidad. Así pues no es de extrañar que estas inclinaciones se extravien tan á menudo, conduciéndonos al error en lugar de la verdad; esto hace mas necesario el fijar los caractéres del sentido comun, que pueda servir de criterio _absolutamente infalible_.\"},{\"heading\":false,\"text\":\"[327.] Señalaré las condiciones que en mi concepto tiene el verdadero sentido comun, que no engaña nunca.\"},{\"heading\":false,\"text\":\"CONDICION 1.ª\"},{\"heading\":false,\"text\":\"La inclinacion al asenso es de todo punto irresistible, de manera que el hombre ni aun con la reflexion, puede resistirle ni despojarse de ella.\"},{\"heading\":false,\"text\":\"CONDICION 2.ª\"},{\"heading\":false,\"text\":\"De la primera dimana la otra, á saber: toda verdad de sentido comun es absolutamente cierta para todo el linaje humano.\"},{\"heading\":false,\"text\":\"CONDICION 3.ª\"},{\"heading\":false,\"text\":\"Toda verdad de sentido comun puede sufrir el exámen de la razon.\"},{\"heading\":false,\"text\":\"CONDICION 4.ª\"},{\"heading\":false,\"text\":\"Toda verdad de sentido comun tiene por objeto la satisfaccion de alguna gran necesidad de la vida sensitiva, intelectual ó moral.\"},{\"heading\":false,\"text\":\"[328.] Cuando estos caractéres se reunen, el criterio del sentido comun es absolutamente infalible, y se puede desafiar á los escépticos á que señalen un ejemplo en que haya fallado. A proporcion que estas condiciones se reunen en mas alto grado, el criterio del sentido comun es mas seguro, debiéndose medir por ellas los grados de su valor. Expliquémoslo con algunos ejemplos.\"},{\"heading\":false,\"text\":\"No cabe duda en que el comun de los hombres objetiva las sensaciones hasta el punto de trasladar á lo exterior lo mismo que ellos sienten, sin distinguir entre lo que hay de subjetivo y de objetivo. Los colores, el linaje humano los considera en las cosas mismas; para él lo verde no es la sensacion de lo verde, sino una cierta cosa, una calidad ó lo que se quiera llamar, inherente al objeto. ¿Es así en realidad? nó ciertamente: en el objeto externo hay la causa de la sensacion, hay la disposicion de las partes para producir por medio de la luz esa impresion que llamamos _verde_. El sentido comun nos engaña, ya que el análisis filosófico le convence de falaz. ¿Pero tiene todas las condiciones arriba señaladas? nó. Por lo pronto le falta el ser capaz de sufrir el exámen de la razon; tan luego como se reflexiona sobre el particular, se descubre que hay aquí una ilusion tan inocente como hermosa. Le falta además al asenso la condicion de irresistible; porque desde el momento en que nos convencemos de que hay ilusion, el asenso deja de existir. No es universal el asenso pues no le tienen los filósofos. No es indispensable para satisfacer alguna necesidad de la vida; y por consiguiente no tiene ninguna de las condiciones arriba señaladas. Lo que se ha dicho de la vista puede aplicarse á todas las sensaciones; ¿hasta qué punto será valedero pues el testimonio del sentido comun en cuanto nos lleva á objetivar la sensacion? hélo aquí.\"},{\"heading\":false,\"text\":\"Para las necesidades de la vida es necesaria la seguridad de que á las sensaciones les corresponden objetos externos; á esto asentimos con impulso irresistible, todos los hombres, sin distincion alguna. La reflexion no basta para despojarnos de la inclinacion natural; y la razon, aun la mas cavilosa, si alguna vez puede hacer vacilar los fundamentos de esta creencia, no alcanza á convencerla de errónea. Los que dan mayor importancia á esas cavilaciones podrán decir que no sabemos si existen los cuerpos, pero nó probar que no existan.\"},{\"heading\":false,\"text\":\"En este punto pues, la inclinacion natural reune todos los caractéres para elevarse al rango de criterio infalible; es irresistible, es universal, satisface una gran necesidad de la vida y sufre el exámen de la razon.\"},{\"heading\":false,\"text\":\"Por lo que toca á las calidades, objeto directo de la sensacion, no necesitamos que existan en los mismos cuerpos; nos basta que en estos haya algo que nos produzca de cualquiera modo que sea, la impresion correspondiente. Poco importa que el color verde y el anaranjado sean ó nó calidades de los objetos, con tal que en ellos sea constante la calidad que nos produce en los casos respectivos, la sensacion de anaranjado ó de verde. Para todos los usos de la vida resulta lo mismo en un caso que en otro; aun cuando el análisis filosófico se generalizase, no se perturbarian las relaciones del hombre con el mundo sensible. Hay quizás una especie de desencanto de la naturaleza, pues que el mundo despojado de las sensaciones no es ni con mucho tan bello; pero el encanto continúa para la generalidad de los hombres; á él está sometido tambien el filósofo excepto en los breves instantes de reflexion; y aun en estos, siente un encanto de otro género, al considerar que gran parte de esa belleza que se atribuye á los objetos la lleva el hombre en sí mismo, y que basta el simple ejercicio de las facultades armónicas de un ser sensible para que el universo entero se revista de esplendor y de galas (XXVIII).\"}]},{\"title\":\"CAPÍTULO XXXIII\",\"blocks\":[{\"heading\":false,\"text\":\"ERROR DE LA-MENNAIS SOBRE EL CONSENTIMIENTO COMUN.\"},{\"heading\":false,\"text\":\"[329.] La fe instintiva en la autoridad humana de que hablo en el capítulo anterior, es un hecho atestiguado por la experiencia y que ningun filósofo ha puesto en duda. Esa fe, dirigida por la razon de la manera conveniente, constituye uno de los criterios de verdad. Los errores á que en ciertos casos puede inducir, son inherentes á la debilidad humana, y están abundantemente compensados por las ventajas que dicha fe produce al individuo y á la sociedad.\"},{\"heading\":false,\"text\":\"Un célebre escritor ha querido refundir todos los criterios en el de la autoridad humana, afirmando resueltamente que el «consentimiento comun, _sensus communis_, es para nosotros el sello de la verdad, y que no hay otro,» (La-Mennais Ensayo sobre la indiferencia en materia de religion tom. 2 cap. 13). Este sistema tan erróneo como extraño, y en que se confunden palabras tan diversas como _sensus_ y _consensus_, está defendida con aquella elocuente exageracion que caracteriza al eminente escritor; bien que al lado de la elocuencia se echa de menos la profundidad filosófica. Los resultados de semejante doctrina se hallan patentes en la triste suerte que ha cabido á tan brillante como malogrado ingenio; abrió una sima en que se hundia toda verdad; el primero que se ha sepultado en ella, ha sido él mismo. Apelar á la autoridad de los demás en todo y para todo, despojar al individuo de todo criterio, era anonadarlos todos, incluso el que se pretendia establecer.\"},{\"heading\":false,\"text\":\"No se concibe cómo un sistema semejante puede tener cabida en tan elevado entendimiento; cuando se leen las elocuentes páginas en que está desenvuelto, se siente una pena inexplicable al ver empleados rasgos tan brillantes en repetir todas las vulgaridades de los escépticos, para venir á parar á la paradoja mas insigne y al sistema menos filosófico que se pueda imaginar.\"},{\"heading\":false,\"text\":\"Único criterio llama La-Mennais al consentimiento comun; sin embargo basta dar una ojeada sobre los demás para convencerse de la esterilidad del nuevo para producirlos.\"},{\"heading\":false,\"text\":\"[330.] En primer lugar, el testimonio de la conciencia no puede apoyarse de ningun modo en la autoridad ajena. Formado como está por una serie de hechos íntimamente presentes á nuestro espíritu, sin que sea dable ni aun concebir sin ellos el pensamiento individual, claro es que ha de preexistir á la aplicacion de todo criterio, pues que el criterio es imposible para quien no piense.\"},{\"heading\":false,\"text\":\"Nada mas débil bajo el aspecto científico, que la refutacion que pretende hacer Mr. de La-Mennais del principio de Descartes. «Cuando Descartes para salir de su duda metódica establece esta proposicion, _yo pienso luego soy_, salva un abismo inmenso, y coloca en el aire la primera piedra del edificio que pretende levantar; porque en rigor no podemos decir yo pienso, yo soy; no podemos decir _luego_, ni afirmar nada por via de consecuencia» (Ibid.). El principio de Descartes era digno de mas detenido exámen para quien trataba de inventar un sistema; oponerle que no podemos decir _luego_, es repetir el manoseado argumento de las escuelas; y el afirmar que no podemos decir, yo pienso, es contrariar un hecho de la conciencia que no han negado los mismos escépticos. En el lugar correspondiente llevo explicado con la debida extension cuál es, ó al menos cuál debe ser, el sentido del principio de Descartes.\"},{\"heading\":false,\"text\":\"Sí segun La-Mennais, no podemos decir yo pienso, menos podremos decir que piensan los demás; y como el pensamiento ajeno le necesitamos absolutamente en el sistema que asienta por único criterio el consentimiento comun, resulta que su primera piedra la pone La-Mennais mas en el aire que los que hacen estribar la filosofía en un hecho de conciencia.\"},{\"heading\":false,\"text\":\"[331.] Un criterio, mayormente si tiene la pretension de ser el único, ha de reunir dos condiciones: no suponer otro, y tener aplicacion á todos los casos. Cabalmente el del consentimiento comun es el que menos las reune; antes que él está el testimonio de la conciencia; antes que él está tambien el testimonio de los sentidos; pues no podemos saber que los demás consienten, si de esto no nos cercioran el oido ó la vista.\"},{\"heading\":false,\"text\":\"[332.] Este criterio no es posible en estos casos, y en muchos otros es harto difícil, cuando no imposible del todo. ¿Hasta qué punto se necesita el consentimiento comun? si la palabra _comun_ se refiere á todo el linaje humano, ¿cómo se recogen los votos de toda la humanidad? si el consentimiento no debe ser unánime, ¿hasta qué punto la contradiccion ó el simple no asentimiento de algunos, destruirá la legitimidad del criterio?\"},{\"heading\":false,\"text\":\"[333.] El orígen del error de La-Mennais está en que tomó el efecto por la causa, y la causa por el efecto. Vió que hay ciertas verdades en que convienen todos, y dijo: la garantía del acierto de cada uno, está en el consentimiento de la totalidad. Analizando bien la materia hubiera notado que la razon de la seguridad del individuo, no nace del consentimiento de los demás, sino que ser el contrario la razon de que convienen todos, es que cada uno de por sí se siente obligado á convenir. En esa gran votacion del linaje humano, vota cada uno en cierto sentido, por el impulso mismo de la naturaleza; y como todos experimentan el mismo impulso, todos votan de la misma manera. La-Mennais ha dicho: cada uno vota de un mismo modo porque todos votan así; no advirtiendo que de esta suerte la votacion no podria acabar ni aun comenzar. Esta comparacion no es una ocurrencia satírica, es un argumento rigurosamente filosófico á que nada se puede contestar; él basta para poner de manifiesto lo infundado y contradictorio del sistema de La-Mennais, así como indica por otra parte el orígen de la equivocacion, que consiste en tomar el efecto por la causa.\"},{\"heading\":false,\"text\":\"[334.] La-Mennais apela al testimonio de la conciencia para probar que su criterio es el único: yo creo que este testimonio enseña todo lo contrario. ¿Quién ha esperado jamás la autoridad de los otros para cerciorarse de la existencia de los cuerpos? ¿no vemos que los mismos brutos en fuerza de un instinto natural, objetivan á su modo las sensaciones? Para prestar asenso á la palabra de los hombres, si no tuviésemos mas criterio que el consentimiento comun, no podriamos jamás creer á ninguno, por la sencilla razon de que no es dable asegurarnos de lo que dicen ó piensan los demás sin comenzar por creer á alguno. El niño para dar fe á lo que le cuenta su madre, ¿se refiere por ventura á la autoridad de los otros? ¿no obedece mas bien al instinto natural que con mano benéfica le ha comunicado el Criador? El niño no cree porque todos creen; por el contrario, todos los niños creen porque cada uno cree; la creencia individual no nace de la general; antes bien la general se forma del conjunto de las creencias individuales: no es natural porque es universal, sino que es universal porque es natural.\"},{\"heading\":false,\"text\":\"[335.] El Aquiles de La-Mennais consiste en que en ciertos casos para asegurarnos de la verdad con respecto á los demás criterios, apelamos al consentimiento comun, y que la locura misma no es mas que el desvío de este consentimiento. A un hombre se le dice que sus ojos le engañan con respecto á un objeto que tiene á la vista; instintivamente se vuelve hacia los demás y les pregunta si no lo ven de la misma manera. Si todos convienen en que yerra y está seguro de que no se chancean, sentirá vacilar por un momento la fe en el testimonio de la vista, se acercará al objeto, se colocará en otra posicion, ó empleará el medio que mejor le parezca para cerciorarse de que no se engaña. Si á pesar de esto ve el objeto de la misma manera, y las mismas personas y cuantas sobrevienen persisten en asegurar que la cosa no es como él la ve, si está en su juicio, desconfiará del testimonio de la vista y se creerá atacado de alguna enfermedad que le desordena la vision. A esto se reduce el argumento de La-Mennais. ¿Qué resulta de él? nada en favor del sistema del consentimiento comun: es cierto que los demás criterios están sujetos á error en circunstancias excepcionales; es cierto que en tales casos, y en naciendo la duda, se apela al testimonio de los otros; mas, ¿para qué? Para asegurarse de si el que teme errar, ha sufrido uno de estos trastornos á que está sujeta la miseria humana. Se sabe que lo natural es general; y el paciente que duda, pregunta á los otros para saber si por algun accidente está fuera del estado ordinario de la naturaleza, ¿Quién no ve la sinrazon de elevar un medio excepcional al rango de criterio general y único? ¿Quién no ve la extravagancia de afirmar que estamos seguros del testimonio de los sentidos, por la autoridad de los demás hombres, solo porque en casos extremos, y al temer algun trastorno de nuestros órganos, preguntamos á los demás si les parece lo mismo que á nosotros?\"},{\"heading\":false,\"text\":\"[336.] No es posible llevar mas allá la exageracion de lo que hace La-Mennais cuando afirma «que las ciencias exactas se fundan tambien en el consentimiento comun, que en esta parte no disfrutan ningun privilegio, y que el mismo nombre de _exactas_ no es mas que uno de esos _vanos títulos_ con que el hombre engalana su flaqueza; que la geometría misma no subsiste sino en virtud de un convenio tácito de admirar ciertas verdades necesarias, convenio que puede expresarse en los términos siguientes: _nosotros nos obligamos á tener tales principios por ciertos; y á cualquiera que se niegue á creerlos sin demostracion, le declaramos culpable de rebeldía contra el sentido comun, que no es mas que la autoridad del gran número._» Esta exageracion es intolerable: los argumentos que en las notas aduce La-Mennais para probar la incertidumbre intrínseca de las matemáticas, son sumamente débiles; y alguno de ellos pudiera hacernos sospechar que el autor del _Ensayo sobre la indiferencia_ no era tan profundo matemático como escritor elocuente.\"},{\"heading\":false,\"text\":\"No desconozco lo que se ha dicho contra la certeza de las ciencias exactas, ni las dificultades que se ofrecen cuando se las llama al tribunal de la metafísica: en el tomo 1.° del _Protestantismo comparado con el Catolicismo_, tengo dedicado un capítulo á lo que llamo instinto de fe, y en él me hago cargo de que este instinto ejerce tambien su influencia en las ciencias exactas. No levantemos á estas sobre las morales; tengamos en mas á las morales que á las exactas; pero guardémonos de una exageracion que las destruye todas.\"}]},{\"title\":\"CAPÍTULO XXXIV\",\"blocks\":[{\"heading\":false,\"text\":\"RESÚMEN Y CONCLUSION.\"},{\"heading\":false,\"text\":\"[337.] Quiero terminar este libro, presentando en resúmen mis opiniones sobre la certeza. En este resúmen se manifestará tambien el enlace de las doctrinas expuestas en los capítulos anteriores.\"},{\"heading\":false,\"text\":\"Cuando la filosofía se encuentra con un hecho necesario, tiene el deber de consignarle. Tal es la certeza: disputar sobre su existencia, es disputar sobre el resplandor de la luz del sol en medio del dia. El humano linaje está cierto de muchas cosas; lo están igualmente los filósofos, inclusos los escépticos; el escepticismo absoluto es imposible.\"},{\"heading\":false,\"text\":\"Descartadas las cuestiones sobre la existencia de la certeza, la filosofía está libre de extravagancias, y situada en los dominios de la razon; entonces se puede examinar cómo adquirimos la certeza, y en qué se funda.\"},{\"heading\":false,\"text\":\"El linaje humano posee la certeza, como una calidad aneja á la vida; como un resultado espontáneo del desarrollo de las facultades del espíritu. La certeza es natural; precede por consiguiente á toda filosofía, y es independiente de las opiniones de los hombres. Por lo mismo, las cuestiones sobre la certeza, aunque importantes para el conocimiento de las leyes á que está sujeto nuestro espíritu, son y serán siempre estériles en resultados prácticos. Esta es una línea divisoria, que la razon aconseja fijar, para que de las regiones abstractas, no descienda jamás nada que pueda perjudicar á la sociedad ni al individuo. Así, desde el principio de las investigaciones, la filosofía y el buen sentido forman una especie de alianza, y se comprometen á no hostilizarse jamás.\"},{\"heading\":false,\"text\":\"Al examinar los fundamentos de la certeza, surge la cuestion sobre el primer principio de los conocimientos humanos: ¿existe? ¿cuál es?\"},{\"heading\":false,\"text\":\"Esta cuestion ofrece dos sentidos: ó se busca una primera verdad, que contenga todas las demás como la semilla las plantas y los frutos, ó se busca simplemente un punto de apoyo; lo primero da lugar á las cuestiones sobre la ciencia trascendental; lo segundo, produce las disputas de las escuelas sobre la preferencia de diferentes verdades con respecto á la dignidad de primer principio.\"},{\"heading\":false,\"text\":\"Si hay verdad, ha de haber medios de conocerla: esto da orígen á las cuestiones sobre el valor de los criterios.\"},{\"heading\":false,\"text\":\"En el órden de los seres, hay una verdad orígen de todas: Dios. En el órden intelectual absoluto, hay tambien esta verdad orígen de todas: Dios. En el órden intelectual humano, no hay una verdad orígen de todas, ni en el órden real, ni en el ideal. La filosofía del _yo_ no puede conducir á ningun resultado, para fundar la ciencia trascendental. La doctrina de la identidad absoluta es un absurdo, que además tampoco explica nada.\"},{\"heading\":false,\"text\":\"Aquí se ofrece el problema de la representacion. Esta puede ser de identidad, causalidad, ó idealidad. La tercera es distinta de la segunda, pero se funda en ella.\"},{\"heading\":false,\"text\":\"A mas del problema de la representacion, se examina el de la inteligibilidad inmediata: problema difícil, pero importantísimo para completar el conocimiento del mundo de las inteligencias.\"},{\"heading\":false,\"text\":\"Las disputas sobre el valor de los diferentes principios con respecto á la dignidad de fundamental, nacen de la confusion de las ideas. Se quieren comparar cosas de órden muy diverso, lo que no es posible. El principio de Descartes es la enunciacion de un simple hecho de conciencia; el de contradiccion, es una verdad objetiva, condicion indispensable de todo conocimiento; el llamado de los cartesianos es la expresion de una ley que preside á nuestro espíritu. Cada cual en su clase, y á su manera, los tres no son necesarios: ninguno de ellos es del todo independiente; la ruina de uno, sea el que fuere, trastorna nuestra inteligencia.\"},{\"heading\":false,\"text\":\"Hay en nosotros varios criterios; pueden reducirse á tres: la conciencia ó sentido íntimo, la evidencia, y el instinto intelectual, ó sentido comun. La conciencia abraza todos los hechos presentes á nuestra alma con presencia inmediata, como puramente subjetivos. La evidencia se extiende á todas las verdades objetivas en que se ejercita nuestra razon. El instinto intelectual es la natural inclinacion al asenso en los casos que están fuera del dominio de la conciencia y de la evidencia.\"},{\"heading\":false,\"text\":\"El instinto intelectual, nos obliga á dar á las ideas un valor objetivo; en este caso, se mezcla con las verdades de evidencia, y en el lenguaje ordinario se confunde con ella.\"},{\"heading\":false,\"text\":\"Cuando el instinto intelectual versa sobre objetos no evidentes, y nos inclina al asenso, se llama _sentido comun._\"},{\"heading\":false,\"text\":\"La conciencia y el instinto intelectual, forman los demás criterios.\"},{\"heading\":false,\"text\":\"El criterio de la evidencia encierra dos cosas: la apariencia de las ideas; esto pertenece á la conciencia: el valor objetivo, existente ó posible; esto pertenece al instinto intelectual.\"},{\"heading\":false,\"text\":\"El testimonio de los sentidos, encierra tambien dos partes: la sensacion, como puramente subjetiva; esto es de la conciencia: la creencia en la objetividad de la sensacion; esto es del instinto intelectual.\"},{\"heading\":false,\"text\":\"El testimonio de la autoridad humana se compone del de los sentidos, que nos pone en relacion con nuestros semejantes, y del instinto intelectual, que nos induce á creerle.\"},{\"heading\":false,\"text\":\"No todo se puede probar; pero todo criterio sufre el exámen de la razon. El de la conciencia es un hecho primitivo de nuestra naturaleza; en el de la evidencia se descubre la condicion indispensable para la existencia de la razon misma; en el del instinto intelectual, para objetivar las ideas, se halla una ley de la naturaleza, indispensable tambien para la existencia de la razon; en el del sentido comun, propiamente dicho, hay el asenso instintivo á verdades, que luego examinadas, se nos presentan altamente razonables; en el de los sentidos y de la autoridad humana, se encuentra lo que en los demás casos del sentido comun, y es un medio para satisfacer las necesidades de la vida sensitiva, intelectual y moral.\"},{\"heading\":false,\"text\":\"Los criterios no se dañan, se favorecen, y se fortifican recíprocamente. Ni la razon lucha con la naturaleza, ni la naturaleza con la razon; ambas nos son necesarias; ambas nos dirigen con acierto; aunque las dos están sujetas á extravío, como que pertenecen á un ser limitado y muy débil.\"},{\"heading\":false,\"text\":\"[338.] Una filosofía que no considera al hombre sino bajo un aspecto, es una filosofía incompleta, que está en peligro de degenerar en falsa. En lo tocante á la certeza, conviene no perder de vista la observacion que precede: hacerse demasiado exclusivo, es colocarse al borde del error. Analícense enhorabuena las fuentes de verdad; pero al mirarlas por separado, no se pierda de vista el conjunto. Concebir de antemano un sistema, y querer sujetarlo todo á sus exigencias, es poner la verdad en el lecho de Procusto. La unidad es un gran bien; pero es menester contentarse con la medida que nos impone la naturaleza. La verdad, es preciso buscarla por los medios humanos, y en proporcion de nuestro alcance. Las facultades de nuestro espíritu están sometidas á ciertas leyes de que no podemos prescindir.\"},{\"heading\":false,\"text\":\"Una de las leyes mas constantes de nuestro ser, es la necesidad de un ejercicio simultáneo de facultades, no solo para cerciorarse de la verdad sino tambien para encontrarla. El hombre reune con la simplicidad la mayor multiplicidad; uno su espíritu, está dotado de varias facultades, está unido á un cuerpo de tal variedad y complicacion, que con mucha razon ha sido llamado un pequeño mundo. Las facultades están en relacion íntima y recíproca; influyen de contínuo las unas sobre las otras. Aislarlas es mutilarlas, y á veces extinguirlas. Esta consideracion es importante, porque indica el vicio radical de toda filosofía exclusiva.\"},{\"heading\":false,\"text\":\"El hombre sin sensaciones carece de materiales para el entendimiento, y además se halla privado del estímulo sin el cual su inteligencia permanece adormecida. Cuando Dios ha unido nuestra alma con un cuerpo, ha sido para que sirviese el uno al otro; por lo cual ha establecido esa admirable correspondencia entre las impresiones del cuerpo, y las afecciones del alma. Esta necesita pues el cuerpo como un medio, como un instrumento, ya se suponga una verdadera accion de él sobre ella, ya una simple ocasion para la causalidad de un órden superior.\"},{\"heading\":false,\"text\":\"Aun cuando sin sensacion, el hombre pensase, no pensaría mas que como un espíritu puro; no estaria en relacion con el mundo exterior, no seria hombre en el sentido que damos á esta palabra. En tal caso el cuerpo sobra; y no hay razon porque estén unidos.\"},{\"heading\":false,\"text\":\"Si admitimos las sensaciones y prescindimos de la razon, el hombre se nos convierte en un bruto. Siente, mas no piensa; nada de combinacion en las impresiones que experimenta, porque es incapaz de reflexionar: todo se sucede en él como una serie de fenómenos necesarios, aislados, que nada indican, á nada conducen, nada son, sino afecciones de un ser particular, que ni los comprende, ni se da á sí mismo cuenta de ellos. Hasta es difícil decir de qué clase son sus relaciones con el mundo externo. Discurriendo por apariencias y por analogía, se hace probable que los brutos objetivan tambien sus sensaciones; pero es regular que su objetividad se distingue de la nuestra en muchos casos. Tomemos por ejemplo el sueño. Si los brutos sueñan, como parece probable, y lo indican algunas apariencias, no fuera extraño que no distinguiesen entre el sueño y la vigilia del modo que lo hacemos nosotros. Esto supone alguna reflexion sobre los actos, alguna comparacion entre el órden y constancia de los unos con el desórden é inconstancia de los otros: reflexion que hace el hombre desde su infancia, y que continua haciendo toda su vida sin advertirlo. Cuando despertamos de un sueño muy vivo, estamos á veces por algunos momentos dudando de si hay sueño ó realidad; esta sola duda ya supone la reflexion comparativa de los dos estados. ¿Y qué hacemos para resolver la duda? Atendemos al lugar donde nos hallamos; y el hecho de estar en la cama, en la oscuridad y silencio de la noche, nos indica que la vision anterior no tiene ningun enlace con nuestra situacion, y que por tanto es un sueño. Sin esta reflexion, se habrian encadenado las sensaciones del sueño con las de la vigilia, confundidas todas en una misma clase.\"},{\"heading\":false,\"text\":\"El instinto concedido á los brutos y negado al hombre, es un indicio de que para apreciar las sensaciones se nos ha dado la razon.\"},{\"heading\":false,\"text\":\"No hay pues en el hombre criterios de verdad enteramente aislados. Todos están en relacion; se afirman y completan recíprocamente; siendo de notar que las verdades de que están ciertos todos los hombres, están apoyadas de algun modo por todos los criterios.\"},{\"heading\":false,\"text\":\"Las sensaciones nos llevan instintivamente á creer en la existencia de un mundo exterior; y si dicha creencia se sujeta al exámen de la razon, esta confirma la misma verdad, fundándose en las ideas generales de causas y de efectos. El entendimiento puro conoce ciertos principios, y asiente á ellos como á verdades necesarias; si se sujetan los principios á la experiencia de los sentidos, salen confirmados, en cuanto lo consiente la perfeccion de estos, ó de los instrumentos con que se auxilian. «En un círculo todos los radios son iguales.» Esta es una verdad necesaria; los sentidos no ven ningun círculo perfecto; pero ven sí que los radios se acercan tanto mas á la igualdad, cuanto mas perfecto es el instrumento con que se le construye. «No hay mudanza, sin causa que la produzca.» Los sentidos no pueden comprobar la proposicion en toda su universalidad, pues por su naturaleza se limitan á un número determinado de casos particulares; pero en todo cuanto se somete á su experiencia, encuentran el órden de dependencia en la sucesion de los fenómenos.\"},{\"heading\":false,\"text\":\"Los sentidos se auxilian recíprocamente: la sensacion de un sentido, se compara con las de otros, cuando hay duda sobre la correspondencia entre ella y un objeto. Nos parece oir el ruido del viento; pero nuestro oido nos ha engañado otras veces; para asegurarnos de la verdad miramos si hay movimiento en los árboles ó en otros objetos. La vista nos muestra un bulto; no hay bastante luz para discernirle de una sombra: nos acercamos y tocamos.\"},{\"heading\":false,\"text\":\"Las facultades intelectuales y morales, ejercen tambien entre sí esta influencia saludable. Las ideas rectifican los sentimientos, y los sentimientos las ideas. El valor de las ideas de un órden se comprueba con las de otro órden; y lo mismo se verifica en los sentimientos. La compasion por el castigado inspira el perdon de todo criminal; la indignacion inspirada por las víctimas del crímen, induce á la aplicacion del castigo: ambos sentimientos encierran algo bueno: mas el uno podria engendrar la impunidad, el otro la crueldad; para temperarlos existen las ideas de justicia. Pero esta justicia á su vez podria dar fallos demasiado absolutos; la justicia es una, y las circunstancias de los pueblos son muy diferentes. La justicia no considera mas que los grados de culpabilidad, y falla en consecuencia. Este fallo podria no ser conveniente: ahí están otras ideas morales de un órden distinto, la enmienda del culpable combinada con la reparacion hecha á la víctima; ahí están además las ideas de conveniencia pública, que no repugnan á la sana moral, y pueden guiar en las aplicaciones.\"},{\"heading\":false,\"text\":\"La verdad completa, como el bien perfecto, no existen sin la armonía: esta es una ley necesaria, y á ella está sujeto el hombre. Como nosotros no vemos intuitivamente la verdad infinita en que todas las verdades son una, en que todos los bienes son uno, y como estamos en relacion con un mundo de seres finitos y por consecuencia múltiplos, hemos menester diferentes potencias que nos pongan en contacto, por decirlo así, con esa variedad de verdades y bondades finitas; pero como estas á su vez nacen de _un_ mismo principio y se dirigen á _un_ mismo fin, están sometidas á la armonía, que es la unidad de la multiplicidad.\"},{\"heading\":false,\"text\":\"[339.] Con estas doctrinas, creo posible la filosofía sin escepticismo: el exámen no desaparece, por el contrario se extiende y se completa. Este método trae consigo otra ventaja, y es que no hace á la filosofía extravagante, no hace de los filósofos hombres excepcionales. La filosofía no puede generalizarse hasta el punto de ser una cosa popular; á este se opone la humana naturaleza; pero tampoco tiene necesidad de condenarse á un aislamiento misantrópico, á fuerza de pretensiones extravagantes. En tal caso la filosofía degenera en filosofismo. Consignacion de los hechos, exámen concienzudo; lenguage claro; hé aquí cómo concibo la buena filosofía. Por esto no dejará de ser profunda, á no ser que por profundidad entendamos tinieblas: los rayos solares alumbran en las mas remotas profundidades del espacio.\"},{\"heading\":false,\"text\":\"[340.] Ya sé que no piensan de este modo algunos filósofos de nuestra época: ya sé que al examinar las cuestiones fundamentales de la filosofía creen necesario conmover los cimientos del mundo; sin embargo, yo jamás he podido persuadirme que para examinar fuese necesario destruir, ni que para ser filósofos debiéramos hacernos insensatos. La sinrazon y extravagancia de esos maestros de la humanidad, puede hacerse sensible con una alegoría, siquiera la amenidad de las formas mortifique un tanto su profundidad filosófica. Bien necesita el lector algun solaz y descanso despues de tratados tan abstrusos, que todos los esfuerzos del escritor no alcanzan á esclarecer, cuanto menos hermosear.\"},{\"heading\":false,\"text\":\"Hay una familia noble, rica y numerosa, que posee un magnífico archivo donde están los títulos de su nobleza, parentesco y posesiones. Entre los muchos documentos, hay algunos mal legibles ó por el carácter de su escritura, ó por su mucha antigüedad, ó por el deterioro que naturalmente han producido los años. Tambien se sospecha que los hay apócrifos en bastante cantidad; bien que ciertamente ha de haber muchos auténticos, pues que la nobleza y demás derechos de la familia, tan universalmente reconocidos, en algo deben de fundarse; y se sabe que no existe otra coleccion de documentos. Todos están allí.\"},{\"heading\":false,\"text\":\"Un curioso entra en el archivo, echa una ojeada sobre los estantes, armarios y cajones, y dice: «esto es una confusion; para distinguir lo auténtico de lo apócrifo, y arreglarlo todo en buen órden, es necesario pegar fuego al archivo por sus cuatro ángulos, y luego examinar la ceniza.»\"},{\"heading\":false,\"text\":\"¿Qué os parece de la ocurrencia? Pues este curioso es el filósofo que para distinguir lo verdadero de lo falso en nuestros conocimientos, empieza por negar toda verdad, toda certeza, toda razon.\"},{\"heading\":false,\"text\":\"Se nos dirá, no se trata de negar sino de dudar; pero quien duda de toda verdad, la destruye; quien duda de toda certeza la niega; quien duda de toda razon, la anonada.\"},{\"heading\":false,\"text\":\"La prudencia, el buen sentido en las cosas pequeñas, se funda en los mismos principios que la sabiduría en las grandes. Sigamos la alegoría, y veamos lo que el buen sentido indicaria en dicho caso.\"},{\"heading\":false,\"text\":\"Tomar inventario de todas las existencias, sin olvidar nada por despreciable que pareciese; hacer las clasificaciones provisionales, que se creyesen mas propias á facilitar el exámen, reservando para el fin la clasificacion definitiva; notar cuidadosamente las fechas, los caractéres, las referencias, y distinguir así la prioridad ó posterioridad; ver si en aquella balumba se encuentran algunas escrituras primitivas, que no se refieran á otras anteriores, y que contengan la fundacion de la casa; establecer reglas claras para distinguir las primitivas de las secundarias; no empeñarse en referir todos los documentos á uno solo exigiéndoles una unidad, que quizás no tienen, pues podria suceder que hubiese varios primitivos, é independientes entre sí. Aun distinguido lo auténtico de lo apócrifo, seria bueno guardarse de quemar nada; porque á veces lo apócrifo guia para la interpretacion de lo auténtico, y puede convenir el estudiar quiénes fueron los falsarios y por qué motivos falsificaron. Además, ¿quién sabe si se juzga apócrifo un documento, que solo lo parece porque no se le entiende bien? Guárdese pues todo, con la debida separacion; que si lo apócrifo no sirve para fundar derechos ni defenderlos, puede servir para la historia del mismo archivo, lo que no es de poca importancia para distinguir lo apócrifo de lo auténtico.\"},{\"heading\":false,\"text\":\"El espíritu humano no se examina á sí mismo hasta que llega á mucho desarrollo: entonces, á la primera ojeada ve en sí un conjunto de sensaciones, ideas, juicios, afecciones de mil clases, y todo enlazado de una manera inextricable. Para aumentar la complicacion, no se halla solo, sino en compañía, en íntima relacion con sus semejantes, en recíproca comunicacion de sensaciones, de ideas, de sentimientos; y todos á su vez en contacto, y bajo la influencia de seres desemejantes, de asombrosa variedad, y cuyo conjunto forma el universo. ¿Comenzará por echarlo todo abajo? ¿Querrá reducirlo todo á cenizas, sin exceptuarse á sí propio, y esperando renacer de la pira, cual otro fénix? Así lo hacen los que para ser filósofos comienzan por negarlo todo, ó dudar de todo. ¿Escogerá arbitrariamente un hecho, un principio, diciendo «algo he de tomar por punto de apoyo, tomo este, y sobre él voy á fundar la ciencia?» ¿Antes de examinar, antes de analizar, dirá: «todo esto es uno; no hay nada si no hay la unidad absoluta; en ella me coloco, y rechazo todo lo que no veo desde mi punto de vista?» Nó: lo que debe hacer es saber primero lo que hay en su espíritu, y luego examinarlo, clasificarlo, apreciarlo en su justo valor: no comenzar por insensatos é impotentes esfuerzos contra la naturaleza, sino por prestar á las inspiraciones de la misma un oido atento.\"},{\"heading\":false,\"text\":\"No hay filosofía sin filósofo; no hay razon sin ser racional; la existencia del _yo_ es pues una suposicion necesaria. No hay razon posible, cuando la contradiccion del ser y no ser no es imposible; toda razon pues supone verdadero el principio de contradiccion. Cuando se examina la razon, la razon es quien examina; la razon ha menester reglas, luz; todo exámen pues supone esta luz, la evidencia, y la legitimidad de su criterio. El hombre no se hace á sí propio, se encuentra hecho ya: las condiciones de su ser, no es él quien las pone: se las halla impuestas. Estas condiciones son las leyes de su naturaleza: ¿á qué luchar contra ellas? «A mas de las _preocupaciones_ facticias, dice Schelling, las hay _primordiales_ puestas en el hombre, no por la educacion, sino por _la naturaleza misma_, que para _todos_ los hombres ocupan el lugar de principios del conocimiento, y son un _escollo_ para el pensador libre,» Por mi parte no quiero ser mas que todos los hombres: no quiero estar reñido con la naturaleza: si no puedo ser filósofo, sin dejar de ser hombre, renuncio á la filosofía y me quedo con la humanidad.\"},{\"heading\":false,\"text\":\"NOTAS\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO I.)\"},{\"heading\":false,\"text\":\"(I.) Conviene distinguir entre la certeza y la verdad: entre las dos hay relaciones íntimas, pero son cosas muy diferentes. La verdad es la conformidad del entendimiento con la cosa. La certeza es un firme asenso á una verdad, real ó aparente.\"},{\"heading\":false,\"text\":\"La certeza no es la verdad, pero necesita al menos la ilusion de la verdad. Podemos estar ciertos de una cosa falsa; mas no lo estaríamos, sino la creyésemos verdadera.\"},{\"heading\":false,\"text\":\"No hay verdad hasta que hay juicio, pues sin juicio no hay mas que percepcion, nó comparacion de la idea con la cosa; y sin comparacion no puede haber conformidad ni discrepancia. Si concibo una montaña de mil leguas de elevacion, concibo una cosa que no existe, mas no yerro mientras me guardo de afirmar la existencia de la montaña. Si la afirmo, entonces hay oposicion de mi juicio con la realidad, lo que constituye el error.\"},{\"heading\":false,\"text\":\"El objeto del entendimiento es la verdad; por esto necesitamos al menos la ilusion de ella para estar ciertos; nuestro entendimiento es débil; y de aquí es que su certeza está sujeta al error. Lo primero es una ley del entendimiento, lo segundo un indicio de su flaqueza.\"},{\"heading\":false,\"text\":\"La filosofía, ó mejor, el hombre, no puede contentarse con apariencias, ha menester la realidad; quien se convenciere de que no tiene mas que apariencia, ó dudase de si tiene algo mas, perderia la misma certeza; esta admite la apariencia, con la condicion de que le sea desconocida.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO II.)\"},{\"heading\":false,\"text\":\"(II.) El mismo Pirron, no dudaba de todo como creen algunos: admitia las sensaciones en cuanto pasivas, y se resignaba á las consecuencias de estas impresiones, conviniendo en la necesidad de acomodarse en la práctica á lo que ellas nos indican. Nadie hasta ahora ha negado las apariencias; las disputas versan sobre la realidad; sosteniendo los unos que el hombre debe contentarse con decir: _parece_; y otros que puede llegar á decir: _es_. Conviene tener presente esta distincion, que evita confusion de ideas en la historia de la filosofía, y conduce á esclarecer las cuestiones sobre la certeza. Así de las tres cuestiones: hay certeza; en qué se funda; cómo se adquiere; la primera está resuelta en un mismo sentido por todas los escuelas, en cuanto se refiere á un hecho de nuestra alma; con solo admitir las apariencias admitian la certeza de ellas.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO III.)\"},{\"heading\":false,\"text\":\"(III.) Para formarse ideas claras sobre el desarrollo del entendimiento y demás facultades de nuestro espíritu véase lo que digo en la obra titulada _El Criterio_, particularmente en los capítulos I, II, III, XII, XIII, XIV, XVIII y XXII.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO IV.)\"},{\"heading\":false,\"text\":\"(IV.) Pongo á continuacion los notables pasajes de Santo Tomás, á que me he referido en el texto, sobre la unidad y multiplicidad de ideas. Creo que los leerán con gusto todos los amantes de una metafísica sólida y profunda.\"},{\"heading\":false,\"text\":\"In omnibus enim substantiis intellectualibus, invenitur virtus intellectiva per influentiam divini luminis. Quod quidem in primo principio est unum et simplex, et quanto magis creatura intellectuales distant à primo principio, tanto magis dividitur illud lumen, et diversificatur, sicut accidit in lineis à centro egredientibus. Et inde est quod Deus per suam essentiam omnia intelligit; superiores autem intellectualium substantiarum, etsi per plures formas intelligant, tamen intelligunt per pauciores et magis universales, et virtuosiores ad comprehensionem rerum, propter efficaciam virtutis intellectivæ, quæ est in eis. In inferioribus autem sunt formæ plures et minus universales, et minus efficaces ad comprehensionem rerum in quantum deficiunt à virtute intellectiva superiorum. Si ergo inferiores substantiæ haberent formas in illa universalitate, in qua habent superiores; quia non sunt tantæ efficaciæ in intelligendo, non acciperent per eas perfectam cognitionem de rebus, sed in quadam communitate, et confusione, quod aliqualiter apparet in hominibus. Nam qui sunt debilioris intellectus, per universales conceptiones magis intelligentium, non accipiunt perfectam cognitionem, nisi eis singula in speciali explicentur (1 p., q. 89, art, 1.).\"},{\"heading\":false,\"text\":\"Intellectus quanto est altior et perspicacior tanto ex uno potest plura cognoscere. Et quia intellectus divinus est altissimus, per unam simplicem essentiam suam onmia cognoscit: nec est ibi aliqua pluralitas formarum idealium, nisi secundum diversos respectus divinæ essentiæ ad res cognitas; sed in intellectu creato multiplicatur secundum rem quod est unum secundum rem in mente divina, ut non possit omnia per unum cognoscere: ita tamen quod quanto intellectus creatus est altior, tanto pauciores habet formas ad plura cognoscenda efficaces. Et hoc est quod Dio. dicit, 12. cæ. hier. quod superiores ordines habent scientiam magis universalem in inferioribus. Et in lib. de causis dicitur, quod intelligentiæ superiores habent formas magis universales: hoc tamen observato, quod in infimis angelis sunt formæ adhuc universales in tantum, quod per unam formam possunt cognoscere omnia individua unius speciei; ita quod illa species sit propria uniuscuiusque particularium secundum diversos respectus eius ad particularia, sicut essentia divina efficitur propria similitudo singulorum secundum diversos respectus; sed intellectus humanus qui est ultimus in ordine substantiarum intellectualium habet formas in tantum particulatas quod non potest per unam speciem nisi unum quid cognoscere. Et ideo similitudo speciei existens in intellectu humano non sufficit ad cognoscenda plura singularia; et propter hoc intellectui adjuncti sunt sensus quibus singularia accipiat (Quodlib. 7. art. 3.).\"},{\"heading\":false,\"text\":\"Respondeo dicendum, quod ex hoc sunt in rebus aliqua superiora, quod sunt uni primo, quod est Deus, propinquiora et similiora. In Deo autem tota plenitudo intellectualis cognitionis continetur in uno, scilicet in essentia divina, per quam Deus omnia cognoscit. Quæ quidem intelligibilis plenitudo, in intelligibilibus creaturis inferiori modo et minus simpliciter invenitur. Unde oportet, quod ea quæ Deus cognoscit per unum, inferiores intellectus cognoscant per multa: et tanto amplius per plura, quanto amplius intellectus inferior fuerit. Sic igitur quanto Angelus fuerit superior, tanto per pauciores species universitatem intelligibilium apprehendere poterit, et ideo oportet quod eius formæ sint universaliores, quasi ad plura se extendentes unaquæque earum. Et de hoc, exemplum aliqualiter in nobis perspici potest: sunt enim quidam, qui veritatem intelligibilem capere non possunt; nisi eis particulatim per singula explicetur. Et hoc quidem ex debilitate intellectus eorum contingit. Alii vero qui sunt fortioris intellectus, ex paucis multa capere possunt (1 p., q. 55. art. 3.).\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO V.)\"},{\"heading\":false,\"text\":\"(V.) Hé aquí explicada por el mismo Condillac la idea de su hombre estatua: «Para llenar este objeto nos imaginamos una estatua organizada interiormente como nosotros y animada de un espíritu, sin ninguna especie de ideas, suponiéndola además de un exterior toda de mármol que no le permitia el uso de ningun sentido, nos reservamos la libertad de abrírselos á las diferentes impresiones de que son susceptibles, segun mejor nos pareciese.\"},{\"heading\":false,\"text\":\"«Creimos deber empezar por el olfato, porque esto es el sentido que parece contribuir menos á los conocimientos del espíritu humano. En seguida examinamos los otros; y despues de haberlos considerado separadamente y en conjunto, vimos que la estatua llegaba á ser un animal capaz de velar por su conservacion.\"},{\"heading\":false,\"text\":\"«El principio que determina el desarrollo de sus facultades es simple; las sensaciones mismas le contienen; porque siendo todas por necesidad agradables ó desagradables, la estatua está interesada en gozar de las unas y evitarse las otras. El lector se convencerá de que este interés es suficiente para dar lugar á las operaciones del entendimiento y de la voluntad. El juicio, la reflexion, los deseos, las pasiones no son otra cosa que la sensacion misma que se transforma de diferentes maneras; por esta razon nos pareció inútil el suponer que el alma recibe inmediatamente de la naturaleza todas las facultades de que está dotada: la naturaleza nos da órganos para advertirnos por el placer, lo que debemos buscar, y por el dolor, lo que debemos huir; pero se detiene allí, y deja á la experiencia el cuidado de hacernos contraer hábitos y de acabar la obra que ella comenzó.\"},{\"heading\":false,\"text\":\"«Este objeto es nuevo, y manifiesta toda la sencillez de las vias del Autor de la naturaleza: ¿no es cosa digna de admiracion el que haya bastado hacer al hombre sensible al placer y al dolor, para que naciesen en él ideas, deseos, hábitos, talentos de toda especie?» (Tratado de las sensaciones, _Idea de la obra_).\"},{\"heading\":false,\"text\":\"Lo que admira no es el sistema de Condillac, sino la candidez de su autor: y todavía mas el que siquiera por breve tiempo, haya podido tener numerosos secuaces un sistema tan superficial y tan pobre. Proponese el autor la dificultad de que no siendo todo lo que hay en el alma mas que la sensacion transformada, es extraño que los brutos que tambien tienen sensaciones, no estén dotados de las mismas facultades que el hombre. ¿Atinaría el lector en la profunda razon señalada por el filósofo francés? mucho lo dudamos. Héla aquí, como un pensamiento curioso: «el órgano del _tacto_ es en los brutos _menos perfecto_, y por consiguiente no puede ser para ellos la causa ocasional de todas las operaciones que se notan en nosotros.» Bien hizo en adoptar el lema: nec tamen quasi Pythius Apollo.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO VI.)\"},{\"heading\":false,\"text\":\"(VI.) En estas materias, son dignas de leerse las obras de los escolásticos: al tratar del _objeto de la ciencia_, son á un tiempo exactos y profundos. Difícilmente se puede excogitar nada con respecto á clasificaciones de verdades, que ellos no hayan explicado ó indicado.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO VII.)\"},{\"heading\":false,\"text\":\"(VII.) No se crea que juzgo con demasiada severidad las formas adoptadas por los filósofos alemanes. Sabido es como habla de ellos Madama de Stael; pero felizmente puedo citar en mi apoyo un juez mas competente todavía, Schelling, uno de los jefes de la filosofía alemana. Dice así: «Los alemanes han filosofado tan largo tiempo entre sí solos, que poco á poco se han apartado en sus ideas y en su lenguaje, de las formas universalmente inteligibles, llegando á tomar por medida del talento filosófico los grados de apartamiento de la manera comun de pensar y de expresarse; fácil me seria citar ejemplos; ha sucedido á los alemanes lo que á las familias que se separan del resto del mundo para vivir únicamente entre ellas, y que acaban por adoptar, á mas de otras singularidades, expresiones que les son propias y que solo ellas mismas pueden entender. Despues de algunos esfuerzos infructuosos para difundir en el extranjero la filosofía de Kant, renunciaron á hacerse inteligibles á las demás naciones, acostumbráronse á mirarse como el pueblo escogido de la filosofía, y la consideraron como una cosa que existió por sí misma con existencia absoluta e independiente; olvidando que el objeto de toda filosofía, objeto al cual se falta con harta frecuencia, pero que jamás debe perderse de vista, es obtener el asentimiento universal, haciéndose universalmente inteligible. No es esto decir que las obras de pensamiento deban ser juzgadas como ejercicios de estilo; pero toda filosofía que no puede ser inteligible para todas las naciones ilustradas y accesible á todas las lenguas, no puede ser por lo mismo una filosofía verdadera y universal. (_Juicio de M. de Schelling sobre la filosofía de M. Cousin y sobre el estado de la filosofía francesa y de la filosofía alemana en general_. 1834).\"},{\"heading\":false,\"text\":\"Lisonjéase M. Schelling de que la filosofía alemana irá entrando en mejor camino con respecto á la claridad, y añade: «el filósofo que hace diez años no habria podido apartarse del lenguaje y de las formas de la escuela so pena de dañar á su reputacion científica, podrá en adelante libertarse de semejantes trabas; la profundidad la buscará en los pensamientos; y una incapacidad absoluta de expresarse con claridad, no será mirada como la señal del talento y de la inspiracion filosófica.» Nada tengo que añadir al pasaje de Schelling; solo recordaré á su autor aquello de _mututo nomine, de te fabula ista narratur_.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO VIII.)\"},{\"heading\":false,\"text\":\"(VIII.) La lectura de la obra de Schelling, titulada _Sistema del idealismo trascendental_, no deja ninguna duda sobre su modo de pensar con respecto á esa identidad, que en el fondo no es ni puede ser otra cosa que el panteismo; sin embargo, en obsequio de la verdad confesaré que Schelling parece haber modificado su doctrina, o temido sus consecuencias, si hemos de atenernos á las indicaciones que se hallan en su discurso pronunciado en la apertura de su curso de filosofía en Berlin el 15 de noviembre de 1841. En él se lee el siguiente pasaje, digno de llamar la atencion de todos los hombres pensadores. «Los dificultades y los obstáculos de todas clases contra los que lucha la filosofía, son visibles, y en vano los quisiéramos disimular.\"},{\"heading\":false,\"text\":\"»Jamás se verificó contra la filosofía, reaccion mas poderosa de parte de la vida activa y real, que en la época presente; esto prueba que la filosofía ha penetrado hasta en las cuestiones mas vitales de la sociedad, en las que á nadie es permitido ser indiferente. Mientras una filosofía se halla en los primeros rudimentos de su formacion, y aun en los primeros pasos de su marcha, nadie se ocupa de ella, sino los mismos filósofos: los demás hombres aguardan á la filosofía en su última palabra; pues no adquiere importancia para el público en general, sino por sus resultados.\"},{\"heading\":false,\"text\":\"»Confieso que no se debe tomar por resultado práctico de una filosofía sólida y meditada profundamente, lo que se le antoja á cualquiera señalar como tal; si así fuese, el mundo deberia someterse á las doctrinas mas contrarias á la sana moral, aun á aquellas que zapasen sus cimientos. No, nadie juzga una filosofía por las conclusiones prácticas sacadas por la ignorancia o la presuncion. Además, que en este punto tampoco seria posible el engaño: el público rechazaria una filosofía que tuviese tales resultados, sin querer ni aun juzgarla en sus principios; diria que nada entiende sobre el fondo de las cuestiones, ni la marcha artificial e intrincada de los argumentos; mas sin pararse en esto, decidiría bien pronto que una filosofía que conduce á tales conclusiones, no puede ser verdadera en sus bases. Lo que la moral romana ha dicho de lo útil, _nihil utile nisi quod honestum_, se aplica igualmente á la investigacion de la verdad; _ninguna filosofía que se respete, confesará que lleve á la irreligion_. Sin embargo, la actual filosofía se halla precisamente en situacion tal que por mas que prometa un resultado religioso, nadie se lo concede; pues que las deducciones que de ella se sacan, convierten los dogmas de la Religion cristiana en una vana fantasmagoría.\"},{\"heading\":false,\"text\":\"»En esto convienen abiertamente algunos de sus discípulos mas fieles; la sospecha sea o no fundada, basta su existencia, y que esta opinion se haya establecido.\"},{\"heading\":false,\"text\":\"»Pero en último resultado la vida activa tiene siempre razon; de suerte que la filosofía está expuesta á grandes riesgos. Los que hacen la guerra á una cierta filosofía, están muy cercanos á condenarlas todas; ellos que dicen en su corazon: no haya mas filosofía en el mundo. Yo mismo no estoy exento de sus condenaciones; pues que _el primer impulso de esta filosofía, al presente tan mal conceptuada, á causa de sus resultados religiosos, se pretende que soy yo quien lo he dado_.\"},{\"heading\":false,\"text\":\"»¿Cómo me defenderé? por cierto que yo no atacaré jamás una filosofía por sus últimos resultados; pero la juzgaré en sus primeros principios como debe hacerlo todo espíritu filosófico. Además, es bastante sabido que desde luego me he manifestado poco satisfecho de la filosofía de que hablo, y poco de acuerdo con ella................................. ......................................................................\"},{\"heading\":false,\"text\":\"»El mundo moral y espiritual se halla tan dividido, que debe ser un motivo de contento el hallar siquiera por un instante, un punto de reunion. Además, el destruir es cosa muy triste cuando no se tiene nada con que reemplazar lo destruido: «hazlo mejor» se dice al que solo sabe criticar.................................................... ......................................................................\"},{\"heading\":false,\"text\":\"»Yo me consagro pues todo entero á la mision de que estoy encargado; para vosotros viviré, para vosotros trabajaré sin descanso, mientras haya en mí un soplo de vida, y me lo permita _Aquel_ sin cuya voluntad no puede caer de nuestras cabezas un cabello, y menos aun salir de nuestra boca una palabra profundamente sentida; _Aquel_, sin cuya inspiracion no puede brillar en nuestro espíritu una idea luminosa, ni un pensamiento de verdad y de libertad alumbrar nuestra alma.»\"},{\"heading\":false,\"text\":\"Este pasaje manifiesta todo lo embarazoso de la posicion del filósofo aleman, y las consecuencias irreligiosas que se achacan á sus doctrinas; es consolador el verle tributar un cierto homenaje á la verdad, pero aflige el notar que todavía pretende salvar su inconsecuencia.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO IX.)\"},{\"heading\":false,\"text\":\"(IX.) En estos últimos tiempos no ha faltado quien pretendiese contar al ilustre Malebranche entre los partidarios del panteismo. No se concibe cómo Mr. Cousin ha podido decir: «Malebranche es con Espinosa, el mas grande discípulo de Descartes: ambos han sacado de los principios de su comun maestro, las consecuencias que en los mismos se contenian. Malebranche es al pie de la letra el Espinosa cristiano» (Fragmentos filosóficos, tom. 2, pág. 167). No se concibe, repito, cómo ha podido asentar tamaña paradoja quien haya leido siquiera las obras del insigne metafísico. Basta echar la vista sobre sus escritos para ver en ellos el espiritualismo mas elevado unido con el respeto mas profundo á los dogmas de nuestra religion sacrosanta. Al esponer los varios sistemas filosóficos sobre el orígen de las ideas y el problema del universo, se me ofrecerán nuevas ocasiones de vindicar al sabio y piadoso autor de la _Investigacion de la verdad_; pero no he querido dejar la presente, sin hacerle la debida justicia defendiéndole de esas imputaciones que él, si viviese, rechazaria con horror como intolerables calumnias. ¡Quién se lo dijera al escribir aquellas páginas donde á cada paso se encuentran Dios, el espíritu, la religion cristiana, la verdad eterna, el pecado original, con numerosos textos de la Sagrada Escritura y de san Agustin, que andando el tiempo habia de verse al lado de Espinosa, bien que con el absurdo epiteto de Espinosa _cristiano!_ Esta es á veces la triste suerte de los grandes hombres, de ser tenidos por gefes de sectas que ellos detestaron. Malebranche llamaba á Espinosa el _impio de nuestros dias_, y M. Cousin se atreve á llamar á Malebranche el Espinosa cristiano.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO X.)\"},{\"heading\":false,\"text\":\"(X.) No ignoro las dificultades á que están sujetos los sistemas de Leibnitz; pero es preciso dejar bien consignado que en la mente de este grande hombre no tenian cabida las erróneas doctrinas de los modernos alemanes. «La última razon de todas las cosas, dice en su _Monadología,_ se halla en una substancia necesaria donde está el orígen de todas las mudanzas, á la que llamamos Dios.\"},{\"heading\":false,\"text\":\"»Siendo esta substancia la razon suficiente de todo el universo, no hay mas que un Dios, y este Dios basta.\"},{\"heading\":false,\"text\":\"»Como esta substancia suprema, que es única, universal y necesaria, no tiene nada fuera de ella que sea independiente de la misma, debe ser incapaz de límites y contener tantas realidades como es posible.\"},{\"heading\":false,\"text\":\"»De donde se infiere que Dios es absolutamente perfecto; pues que la perfeccion no es otra cosa que el grandor de la realidad positiva tomada precisamente, dejando á un lado los límites en las cosas que los tienen. Donde no hay límites, como se verifica en Dios, la perfeccion es absolutamente infinita.\"},{\"heading\":false,\"text\":\"»De aqui se deduce que las criaturas reciben sus perfecciones de la accion de Dios; pero tienen sus imperfecciones de su propia naturaleza, incapaz de ser ilimitada, en lo que se distinguen de Dios.\"},{\"heading\":false,\"text\":\"»Es verdad tambien que en Dios se halla no solo el manantial de las existencias, sino tambien el de las esencias, en cuanto reales, ó en lo que la posibilidad contiene de real.»\"},{\"heading\":false,\"text\":\"En su disertacion sobre la filosofía platónica, combate las tendencias panteistas de Valentin Vegelio con estas palabras: «Yo quisiera que Valentin Vegelio explicando en un tratado particular la vida bienaventurada por la transformacion en Dios, y preconizando con frecuencia una muerte y un reposo de este género, no hubiese dado motivo á la sospecha de que él y otros quietistas adoptaban esta opinion. Al mismo punto se dirige Espinosa bien que por otro camino: no admite mas que una sola substancia que es Dios, las criaturas son modificaciones de esta substancia, como las figuras que con el movimiento nacen y perecen de continuo en la cera blanda. Síguese de esto lo mismo que de la opinion de Almerio, que el alma no subsiste despues de la muerte, sino por su ser ideal en Dios, como ha existido allí desde toda la eternidad.\"},{\"heading\":false,\"text\":\"«Pero yo nada encuentro en Platon para creer que su opinion haya sido que los espíritus no conservan su propia substancia. Esta doctrina es incontestable á los ojos de todos los que razonan sabiamente en filosofía; y ni aun es posible formarse idea de la opinion contraria, á no ser que nos figuremos á Dios y al alma como seres corpóreos, pues de otro modo las almas no podrian ser sacadas de Dios como partículas: pero es absurdo formarse semejantes ideas de Dios y del alma» (T. 2, diss. de phil. platonica, p. 224, epist. ad Hanschium, an. 1707, y se halla entre los _Pensamientos de Leibnitz_ sobre la religion y la moral publicados por M. Emery).\"},{\"heading\":false,\"text\":\"Tan lejos estaba Leibnitz de abrigar tendencia al panteismo, ni de reputarle por una filosofía elevada, que antes bien, como acabamos de ver, le considera como el resultado de una imaginacion grosera. Es muy notable que así bajo el aspecto metafísico como histórico, está completamente de acuerdo Leibnitz con Santo Tomás, manifestando ambos las mismas ideas con palabras muy semejantes. Busca el santo Doctor si el alma es hecha de la substancia de Dios, y con esta ocasion examina el orígen del error, y dice lo siguiente: «Respondeo dicendum, quod dicere animam esse de substantia Dei, manifestam improbabilitatem continet. Ut enim ex dictis patet, anima humana est quandoque intelligens in potentia, et scientiam quodammodo à rebus acquirit, et habet diversas potentias quæ omnia aliena sunt à Dei natura, qui est actus purus, et nihil ab alio accipiens, et nullam in se diversitatem habens, ut supra probatum est.\"},{\"heading\":false,\"text\":\"»Sed hic error principium habuisse videtur ex duabus positionibus antiquorum. Primi enim, qui naturas rerunt considerare inceperunt, imaginationem transcendere non valentes, nihil præter corpora esse possuerunt. Et ideo Deum dicebant esse quoddam corpus, quod aliorum corporum judicabant esse principium. Et quia animam ponebant esse de natura illius corporis, quod dicebant esse principium, ut _dicitur in primo de anima_, per consequens sequebatur quod anima esset deo substantia Dei. Juxta quam positionem etiam Manichari, Deum esse quamdam lucem corpoream existimantes, quamdam partem illius lucis animam esse possuerunt corpori alligatam. Secundo vero processuoi fuit ad hoc quod aliqui aliquid incorporeum esse apprehenderunt: non tamen á corpore separatum, sed corporis formam. Unde et Varro dixit quod Deus est anima, mundum intuitu, vel motu et ratione gubernans: ut Augu. narrat 7 de civit. Dei. Sic igitur illius totalis animæ partem, aliqui possuerunt animam hominis: sicut homo est pars totius mundi: non valentes intellectu pertingere ad distinguendos spiritualium substantiarum gradus, nisi secundum distinctionas corporum. Hæc autem omnia sunt impossibilia, ut supra probatum est, unde manifeste falsum est animam esse de substantia Dei(1 p. q. 90. art. 1).\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO XI.)\"},{\"heading\":false,\"text\":\"(XI) En los escolásticos se encuentra á menudo que el entendimiento es la misma cosa entendida, aun tratándose de los entendimientos creados; pero esta identidad se limita á un órden puramente ideal, y no significa mas que la íntima union de la idea con el entendimiento. Sabido es cuánta importancia tienen en la filosofía escolástica las materias y formas; y esta distincion se la aplica tambien á los fenómenos de la inteligencia. Bien que la idea era considerada como una cosa distinta del entendimiento, no obstante como este era perfeccionado por ella y puesto en relacion con la cosa representada, se decia que el entendimiento era la misma cosa entendida. Así deben explicarse los pasajes que se encuentran en Santo Tomás y otros escolásticos; pues aunque las expresiones de que se valen, consideradas aisladamente, serian inexactas; no lo son si se atiende al sentido que ellos les atribuyen y que resulta bien claro de los principios en que se fundan. Por ejemplo Santo Tomás (quodlibet 7. art. 2) para probar que el entendimiento criado no puede entender muchas cosas á un mismo tiempo dice: «Sed quod intellectus simul intelligat plura intelligibilia, primò et principaliter, est impossibile. Cuius ratio est, quia _intellectus secundum actum est omninò, id est perfectè res intellecta: ut dicitur_ in 3. de anima. _Quod quidem intelligendum, est non quòd essentia intellectus fiat res intelecta_ vel species eius; sed quia completè informatur per speciem rei intellectæ, dum eam actu intelligit. Unde intellectum simul plura intelligere primò, idem est acsi res una simul esset plura. In rebus enim materialibus videmus quod una res numero non potest esse simul plura in actu, sed plura in potentia................................. .....................................................................\"},{\"heading\":false,\"text\":\"»Unde patet quòd sicut una res materialis non potest esse simul plura actu, ita unus intellectus non potest simul plura intelligere primo. Et hoc est quòd Alga, dicit, quòd sicut unum corpus non potest simul figurari pluribus figuris: ita unus intellectus non potest simul plura intelligere. Nec potest dici quod intellectus informetur perfectè simul pluribus speciebus intelligibilibus, sicut unum corpus simul informatur figura et colore: quia figura et color non sunt formæ unius generis, nec in eodem ordine accipiuntur quia non ordinantur ad perficiendum in esse unius rationis: sed omnes formæ intelligibiles in quantum huiusmodi, sunt unius generis, et in eodem ordine se habent ad intellectum, in quantum perficiunt intellectum in hoc quod est esse intellectum. Unde plures species intelligibiles se habent sicut figuræ plures; vel plures colores qui simul in actu in eodem esse non possunt secundum idem.»\"},{\"heading\":false,\"text\":\"Por el anterior pasaje se echa de ver que el sentido de la identidad del entendimiento con la cosa entendida, no era otro que el explicado al principio de esta nota, á saber, el de la union íntima de la idea ó especie inteligible con el entendimiento, como una forma con su materia; forma que perfeccionaba al entendimiento, haciéndole pasar del estado de potencia al de acto, y poniéndole en relacion con la cosa representada.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO XII.)\"},{\"heading\":false,\"text\":\"(XII.) La doctrina de la inteligibilidad inmediata, es susceptible de ulteriores aclaraciones; pero como estas no podrian ser cabales sin examinar á fondo la naturaleza de la idea, lo que no corresponde al presente tratado, me reservo darlas en el lugar oportuno.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO XIII.)\"},{\"heading\":false,\"text\":\"(XIII.) Quizás no bastará lo dicho en el texto para que todos los lectores se formen ideas bastante claras y completas de la representacion de causalidad; pero debo advertir que esta doctrina en lo tocante á la inteligencia primera, está intimamente enlazada con las cuestiones sobre el fundamento de la posibilidad aun de las cosas no existentes, cuestiones que no podria exponer aquí, sin trastornar el órden de las materias.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO XIV.)\"},{\"heading\":false,\"text\":\"(XIV.) La distincion de los órdenes de ideas, geométrico y no geométrico, es de la mayor importancia para la ideología. He adelantado esta distincion porque la necesitaba para no dejar incompleto el exámen de la posibilidad de una verdad fundamental entre las puramente ideales. Pero su explicacion y los cimientos en que estriba, se encontrarán en el tratado sobre las ideas del espacio y de la extension.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE CAPÍTULO XV.)\"},{\"heading\":false,\"text\":\"(XV.) La palabra _instinto_ aplicada al entendimiento, claro es que se toma en una acepcion muy diferente de cuando se habla de los irracionales. No encierra aquí ningun significado ignoble; lo que está de acuerdo con el uso que de la misma se hace, aun para las cosas divinas. Una de las acepciones que le da el Diccionario de la lengua, es: «impulso ó movimiento del Espíritu Santo hablando de inspiraciones sobrenaturales.» El latin _instinctus_, significaba _inspiracion_: sacro mens _instincta_ furore.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO XVI.)\"},{\"heading\":false,\"text\":\"(XVI.) El orígen de la confusion de ideas en la presente cuestion, es esa tendencia á la unidad de que he tratado en el capítulo IV. Se comienza por suponer que no ha de haber mas que un principio, y se busca cuál es; cuando antes de investigar cuál es, se deberia saber si existe solo, como se lo supone. Ya hemos visto que el sistema de Fichte estriba en la misma suposicion: por manera que la misma causa que en las escuelas producia disputas inocentes, puede llevar á extravíos de la mayor trascendencia.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO XVII.)\"},{\"heading\":false,\"text\":\"(XVII.) Creo haber interpretado fielmente el pensamiento de Descartes, mas por si alguna dificultad quedase sobre el particular, pongo á continuacion un notable pasaje del mismo autor, en su respuesta á las objeciones recogidas por el P. Mersenne de boca de varios filósofos y teólogos contra las _Meditaciones_ II, III, IV, V y VI.\"},{\"heading\":false,\"text\":\"«Cuando conocemos que somos una cosa que piensa, esta primera nocion _no está sacada de ningun silogismo_; y cuando alguno dice: _yo pienso luego soy_ ó existo, no _infiere_ su existencia del pensamiento como _por la fuerza de un silogismo_ sino como una cosa conocida por sí misma, _la ve por una simple inspeccion del espíritu_; pues que si la dedujera de un silogismo habria necesitado conocer de antemano esta mayor: todo lo que piensa es ó existe. Por el contrario, esta proposicion se la manifiesta su propio sentimiento, de que no puede suceder que piense sin existir. Este es el carácter propio de nuestro espíritu de formar proposiciones generales por el conocimiento de las particulares.» No siempre se expresa Descartes con la misma lucidez; se conoce que las objeciones de sus adversarios le hacian meditar mas profundamente su doctrina, y contribuian á que aclarase sus ideas.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO XVIII.)\"},{\"heading\":false,\"text\":\"(XVIII.) Para formarnos ideas cabales sobre la mente de Descartes, oigámosle á él mismo explicando su sistema.\"},{\"heading\":false,\"text\":\"«Como los sentidos nos engañan algunas veces, quise _suponer_ que no habia nada parecido á lo que ellos nos hacen imaginar; como hay hombres que se engañan raciocinando aun sobre las materias mas sencillas de geometría y hacen paralogismos, juzgando yo que estaba tan sujeto á errar como ellos, deseché como falsas todas las razones que antes habia tomado por demostraciones; y considerando en fin que aun los mismos pensamientos que tenemos durante la vigilia, pueden venirnos en el sueño sin que entonces ninguno de ellos sea verdadero, me resolví á _fingir_ que todas las cosas que habian entrado en mi espíritu no encerraban mas verdad que las ilusiones de los sueños. Pero desde luego advertí que mientras queria pensar que todo era falso, era necesario que yo que lo pensaba, fuese alguna cosa; y notando que esta verdad, yo pienso luego soy, era tan firme y segura que las mas extravagantes suposiciones de los escépticos no eran capaces de conmoverla, juzgué que podia recibirla sin escrúpulo por el primer principio de filosofía» (_Discurso sobre el Método_, cuarta parte).\"},{\"heading\":false,\"text\":\"He dicho que la duda de Descartes era una _suposicion_, una _ficcion_; y cabalmente estas son las palabras que emplea el mismo autor. En la ya citada respuesta á las objeciones recogidas por el P. Mersenne, se halla el siguiente pasaje:\"},{\"heading\":false,\"text\":\"«He leido con mucha satisfaccion las observaciones que me habeis hecho sobre mi primer tratado de la filosofía, porque ellas me dan á conocer vuestra benevolencia para conmigo, vuestra piedad hácia Dios, y el cuidado que os tomais por el progreso de su gloria. No puedo dejar de alegrarme, no solo de que hayais juzgado mis razones dignas de vuestra censura, sino tambien de que nada decis á que yo no pueda contestar fácilmente.\"},{\"heading\":false,\"text\":\"»En primer lugar me recordais que _nó veras sino tan solo por una mera ficcion_, he desechado las ideas ó los fantasmas de los cuerpos para concluir que yo soy una cosa que pienso, por temor quizás que yo no crea que se sigue de esto que yo no soy sino una cosa que pienso; mas ya os he hecho ver en mi segunda Meditacion que yo me acordaba de esto, ya que decia lo siguiente: «pero puede suceder que estas cosas que yo _supongo_ que no son, porque no las conozco, no sean en efecto diferentes de mí á quien conozco; no sé nada de esto, no me ocupo de esto en la actualidad.»............................................... ......................................................................\"},{\"heading\":false,\"text\":\"Como se ve, Descartes no rechaza el que su duda no sea una mera ficcion; hasta dice en términos expresos que no hace mas que aplicar un método cuya necesidad reconocen todos los filósofos.\"},{\"heading\":false,\"text\":\"«Os suplico, continúa, que recordeis que por lo tocante á las cosas relativas á la voluntad, he puesto siempre una gran distincion entre la contemplacion de la verdad y los usos de la vida: con respecto á estos, tan distante me hallo de pensar que solo debamos seguir las cosas conocidas muy claramente, que por el contrario creo que ni aun es preciso aguardar siempre las mas verosímiles, sino que es preciso á veces entre muchas cosas del todo desconocidas é inciertas, escoger una, y atenerse á ella firmemente, mientras no se vean razones en contra, cual si la hubiésemos escogido por motivos ciertos y evidentes, como lo tengo ya explicado en el _Discurso sobre el Método_; pero cuando solo se trata de la contemplacion de la verdad ¿_quién ha dudado jamás que sea necesario suspender el juicio sobre las cosas obscuras ó que no son distintamente conocidas_?»\"},{\"heading\":false,\"text\":\"¿Entonces, se nos dirá, en qué consiste el mérito de Descartes? En haber _aplicado_ una regla que todos conocen, y pocos emplean; y en haberlo hecho en una época en que la preocupacion á favor de las doctrinas aristotélicas, era todavía muy poderosa. Descartes lo dice terminantemente; su método de dudar no es nuevo, lo que le faltaba era la aplicacion; pues por lo tocante al principio en que se funda, «_quién ha dudado jamás que sea necesario suspender el juicio_ sobre las cosas obscuras, ó que no son distintamente conocidas?»\"},{\"heading\":false,\"text\":\"Entendido el método de Descartes en este sentido, es decir tomando la duda como una suposicion, como una mera ficcion, no se opone á los buenos principios religiosos y morales. El profundo filósofo no se desdeña de tranquilizar sobre este punto á los lectores, manifestando ingenuamente que al comenzar sus investigaciones habia puesto en salvo sus creencias religiosas.\"},{\"heading\":false,\"text\":\"«Y en fin, como antes de empezar á reconstruir la casa en que se habita, no basta el derribarla y hacer provision de materiales y de arquitectos ó ejercitarse en la arquitectura y en trazar cuidadosamente el diseño del nuevo edificio, sino que es preciso estar provisto de algun otro donde se pueda vivir cómodamente mientras se trabaja en el nuevo; para que no estuviese irresoluto en mis acciones en tanto que la razon me obligaba á estarlo en mis juicios, y para no dejar de vivir entre tanto lo mas felizmente que pudiera, me formé una moral provisoria que consistia en tres ó cuatro máximas que voy á exponer. La primera es el obedecer á las leyes y costumbres de mi pais _conservando constantemente la Religion en que por la gracia de Dios habia sido instruido desde mi infancia_............................. ....................................................................\"},{\"heading\":false,\"text\":\"»Despues de haberme asegurado de estas máximas y haberlas puesto aparte _con las verdades de la fe, que han sido siempre las primeras en mi creencia_, juzgué que podia deshacerme libremente del resto de mis opiniones» (_Discurso sobre el Método_, tercera parte).\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO XIX.)\"},{\"heading\":false,\"text\":\"(XIX.) Con respecto á la distincion entre el testimonio de la conciencia y el de la evidencia, así como en lo tocante al análisis de la proposicion: yo pienso, luego soy, no cabe duda que Descartes no se expresa con bastante precision y exactitud. Véase por ejemplo el siguiente pasaje donde se nota alguna confusion de ideas.\"},{\"heading\":false,\"text\":\"«Despues de esto consideré en general lo que se necesita para que una proposicion sea verdadera y cierta, porque ya que yo acababa de encontrar una que tenia dicho carácter, pensé que debia saber tambien en qué consiste esta certeza, y habiendo notado que en la proposicion, yo pienso, luego soy, no hay nada que me asegure de que yo digo la verdad, sino que veo muy claramente que para pensar es preciso ser, juzgué que podia tomar por regla general que las cosas concebidas con mucha claridad y distincion, son todas verdaderas; pero que solo hay alguna dificultad en notar bien cuáles son las que concebimos distintamente» (_Discurso sobre el Método_, cuarta parte).\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO XX.)\"},{\"heading\":false,\"text\":\"(XX.) La certeza _apodíctica_ de que habla Kant en el citado pasaje, es la que resulta de la evidencia intrínseca de las ideas; ó en otros términos, es la misma que en las escuelas suele llamarse metafísica.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO XXI.)\"},{\"heading\":false,\"text\":\"(XXI.) A mas de las cuestiones sobre el principio de contradiccion, como único fundamento de certeza, hay otras con respecto á su importancia y fecundidad científicas. Nada he querido prejuzgar aquí sobre estos puntos, porque me reservo ventilar largamente dichas cuestiones, al tratar de la idea del _ser_ en general.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO XXII.)\"},{\"heading\":false,\"text\":\"(XXII.) Por un pasaje de Descartes de la cuarta parte de su _Discurso sobre el Método_, citado en la nota (XIX), se echa de ver que á mas del principio, yo pienso luego soy, admitia el de la legitimidad de la evidencia; pues al buscar lo que se necesita para que una proposicion sea verdadera y cierta, dice que habiendo notado que si estaba seguro de la verdad de esta proposicion, yo pienso luego soy, era tan solo porque lo veia claramente así, creyó que podia tomar por _regla general_, que _las cosas conocidas con claridad y distincion son todas verdaderas_. Por donde se echa de ver que en el sistema de Descartes entran dos principios ligados entre sí, pero muy diferentes: 1.º el hecho de conciencia del pensamiento; 2.º La regla general de la legitimidad del criterio de la evidencia.\"},{\"heading\":false,\"text\":\"Es de notar tambien que hay aquí cierta confusion de ideas que he señalado ya en otra parte. No es exacto que el principio yo pienso luego soy, sea evidente: la evidencia se refiere á la _consecuencia_, pero en cuanto al acto de pensar, no hay evidencia propiamente dicha, sino conciencia. La evidencia es un criterio, mas nó el único.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO XXIII.)\"},{\"heading\":false,\"text\":\"(XXIII.) Lo dicho en la proposicion segunda de este capítulo (236), es independiente de las disputas sobre el modo con que el alma y el cuerpo ejercen su influencia recíproca, cuestiones que no son de este lugar. Sea cual fuere el sistema que se adopte, la influencia es un hecho que la experiencia nos atestigua; lo que me basta para lo que me propongo establecer allí.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO XXIV.)\"},{\"heading\":false,\"text\":\"(XXIV.) Para entender mejor lo que se dice en este capítulo sobre la evidencia, será útil enterarse bien de las doctrinas expuestas mas abajo desde el XXVI, hasta el XXXI inclusive.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO XXV.)\"},{\"heading\":false,\"text\":\"(XXV.) Por lo dicho en este capítulo se manifiesta la verdad de lo que digo en el XXIV, sobre el enlace de los diferentes criterios y la necesidad de no atenerse á una filosofía exclusiva. El sentido íntimo, ó la conciencia, sirve de base á los demás, como un hecho indispensable; pero él mismo se destruye, si se niegan los otros.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE LOS CAPÍTULOS XXVI, XXVII Y XXVIII.)\"},{\"heading\":false,\"text\":\"(XXVI.) Dugald-Steward (P. 2. Cap. 2. Seccion 3. §. 2.) cita un pasaje de una disertacion publicada en Berlin en 1764, que no parece tan poco razonable como pretende el autor de la _Filosofía del espíritu humano_. Lo pongo á continuacion, porque la opinion del filósofo aleman me parece ser la misma que he sostenido en el texto.\"},{\"heading\":false,\"text\":\"«Omnes mathematicorum propositiones sunt identicæ et representantur hac formula, A = A. Sunt veritates identicæ sub varia forma expressæ, imo ipsum quod dicitur contradictionis principium vario modo enuntiatum et involutum; si quidem omnes hujus generis propositiones revera in eo continentur. Secundum nostram autem intelligendi facultatem ea est propositionum differentia, quod quædam longa ratiociniorum serie, alia autem breviore via, ad primum omnium principium reducantur, et in illud resolvantur. Sic v.g. propositio 2 + 2 = 4 statim huc cedit: 1 + 1 + 1 + 1 = 1 + 1 + 1 + 1; id est, idem est idem; et, proprie loquendo, hac modo enunciari debet:--si contingat adesse vel existere quatuor entia, tum existunt quatuor entia; nam de existentia non agunt geometræ, sed ea hypothetice tantum subintelligitur. Inde summa oritur certitudo ratiocinia perspicienti; observat nempe idearum identitatem; et hæc est evidentia assensum immediate cogens, quam mathematicam aut geometricam vocamus. Mathesi tamen sua natura priva non est et propria; oritur etenim ex identitatis perceptione, quæ locum habere potest, etiamsi ideæ non repræsentent extensum.»\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE LOS CAPÍTULOS XXX Y XXXI.)\"},{\"heading\":false,\"text\":\"(XXVII.) He indicado que quizás Dugald-Steward se habia aprovechado de las doctrinas de Vico; sin que por esto quiera hacerle el cargo que se dirigió contra su maestro Reid, de quien se dijo que resucitaba las doctrinas del P. Buffier jesuita. No obstante, para que el lector pueda juzgar con pleno conocimiento de causa, pongo á continuacion un notable pasaje del filósofo escocés, por el cual se verá la coincidencia de algunas de sus observaciones con las del filósofo napolitano. Me inclino á creer que si Dugald-Steward hubiese leido á Vico, no se quejaria de la _confusion_ con que explicaron esta doctrina varios autores antiguos y modernos.\"},{\"heading\":false,\"text\":\"«El carácter particular de esta especie de evidencia llamada demostrativa, y que tan marcadamente distingue las conclusiones matemáticas de las de otras ciencias, es un hecho que debe haber llamado la atencion de cualquiera que conozca los elementos de la geometría; y sin embargo yo dudo que su causa haya sido señalada de una manera satisfactoria.» Locke nos dice: «lo que constituye la demostracion es la evidencia intuitiva de cada paso del raciocinio;» convengo en que si esta evidencia faltase en un solo punto, toda la demostracion se arruinaria; mas no creo que la evidencia demostrativa de la conclusion dependa de esta circunstancia, aun cuando añadiésemos esta otra condicion sobre la cual Reid insiste mucho: «que para la evidencia demostrativa es necesario que los primeros principios sean intuitivamente ciertos.» Al tratar de los axiomas, hice notar la inexactitud de esta observacion, manifestando además que en las matemáticas, los primeros principios de nuestros raciocinios no son los axiomas sino las definiciones. Sobre esta última circunstancia, es decir, sobre esta condicion de discurrir partiendo de definiciones, se debe fundar la verdadera teoría de la demostracion matemática. Voy á desenvolver aquí extensamente esta doctrina, indicando al mismo tiempo algunas de las consecuencias mas importantes que de ella dimanan.\"},{\"heading\":false,\"text\":\"»Como no quiero reclamar injustamente los honores de la invencion, debo comenzar por declarar que la idea matriz de esta doctrina ha sido manifestada y aun desenvuelta con extension por diversos autores tanto antiguos como modernos; pero en todos ellos se la encuentra de tal modo confundida con otras consideraciones del todo extrañas al punto de la discusion, que la atencion del autor y del lector se distrae del único principio del cual depende la solucion del problema....... ................................................................\"},{\"heading\":false,\"text\":\"»Hemos visto ya en el primer capítulo de esta parte que mientras en las demás ciencias las proposiciones que se han de establecer expresan siempre hechos reales ó supuestos, las demostradas en las matemáticas enuncian simplemente una conexion entre ciertas suposiciones y ciertas consecuencias. Así en las matemáticas nuestros raciocinios tienen un objeto muy diferente del que nos sirve en los otros usos de las facultades intelectuales; pues que se proponen, nó consignar verdades relativas á existencias reales, sino determinar la filiacion lógica de las consecuencias que dimanan de una hipótesis dada. Si partiendo de esta hipótesis raciocinamos con exactitud, es claro que nada puede faltar á la evidencia del resultado, pues que este se limita á afirmar un enlace necesario entre la suposicion y la conclusion; en las otras ciencias, aun suponiendo evitada la ambigüedad del lenguaje, y rigurosamente exactos todos los pasos de la deduccion, nuestras conclusiones serian siempre mas ó menos inciertas, pues que en definitiva estriban sobre principios que pueden corresponder ó no corresponder con los hechos» (P. 2. Cap. 2. Secc. 3.). Esta es exactamente la doctrina de Vico sobre la causa de la diferencia en los grados de evidencia y certeza; bien que este filósofo eleva á un sistema general, para explicar el problema de la inteligencia, lo que el escocés solo consigna como un hecho para señalar la razon de la evidencia matemática. El P. Buffier (Trat. de las primeras verdades, P. 1. Cap. 11.) explica lo mismo con mucha claridad.\"},{\"heading\":false,\"text\":\"He dicho tambien que atendida la infatigable laboriosidad que distingue á los alemanes, no fuera extraño que hubiesen leido á los escolásticos: esto se confirma, si se advierte que Leibnitz recomienda mucho esta lectura; y no es regular que se hayan olvidado del consejo de un autor tan competente, los alemanes mas modernos.\"},{\"heading\":false,\"text\":\"Entre los varios pasajes de Leibnitz sobre los escolásticos, prefiero aducir el siguiente que me parece sumamente curioso. «La verdad está mas difundida de lo que se cree; pero con harta frecuencia se la halla envuelta, debilitada, mutilada, corrompida con adiciones que la echan á perder, ó la hacen menos útil. Notando esas huellas de verdad en los antiguos, ó para hablar mas generalmente, en los _anteriores_, se sacaria oro del fango, el diamante de su mina, luz de las tinieblas; y esto seria en realidad _perennis quædam philosophia_. Hasta se puede decir que se notaria algun progreso en los conocimientos. Los orientales tienen ideas grandes y hermosas sobre la divinidad; los griegos añadieron el raciocinio y una forma científica; los Padres de la Iglesia desecharon lo que habia de malo en la filosofía de los griegos; pero los escolásticos trataron de emplear útilmente para el cristianismo lo que habia de aceptable en la filosofía de los paganos. Repetidas veces he dicho: _aurum latere in stercore illo scolastico barbarico_; y desearia que se pudiese encontrar algun hombre hábil, versado en esta filosofía irlandesa y española, que tuviese inclinacion y capacidad para sacar lo que en ella hay de bueno. _Estoy seguro que su trabajo seria recompensado con muchas verdades bellas é importantes_. En otro tiempo hubo en Suiza un escritor que _matematizó_ en la escolástica; sus obras son poco conocidas; pero lo que de ellas he visto me ha parecido profundo y digno de consideracion» (Carta 3. á M. Remond de Montmort).\"},{\"heading\":false,\"text\":\"Así habla Leibnitz, uno de los hombres mas eminentes de los tiempos modernos, y de quien Fontenelle ha dicho con razon, que «conducia de frente todas las ciencias.» Véase pues si anduve descaminado al recomendar al estudio de aquellos autores, á quien desee adquirir en filosofía conocimientos profundos. Aun prescindiendo de la utilidad intrínseca, seria conveniente dicho estudio para poder juzgar con conocimiento de causa, unas escuelas que, valgan lo que valieren, ocupan una página en la historia del espíritu humano.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"(SOBRE EL CAPÍTULO XXXII.)\"},{\"heading\":false,\"text\":\"(XXVIII.) El autor á quien aludo (317) es Fenelon, quien bajo el nombre de sentido comun, comprende tambien el criterio de la evidencia, como se echa de ver en el siguiente pasaje: «¿Qué es el sentido comun? ¿no consiste en las primeras nociones que todos los hombres tienen de las mismas cosas? Este sentido comun que siempre y en todas partes es el mismo, que previene todo exámen y hasta le tiene por ridículo en ciertas cuestiones, en las cuales se rie en vez de examinar; que reduce al hombre á no poder dudar por mas que en ello se esfuerce; este sentido que pertenece á todos los hombres, que solo espera ser consultado para mostrarse y descubrirnos desde luego la evidencia ó lo absurdo de la cuestion, ¿_no es esto lo que yo llamo mis ideas_? Hélas aquí, pues, estas ideas ó nociones generales, que yo no puedo contradecir ni examinar, segun las cuales por el contrario, lo examino y lo juzgo todo, de manera que en vez de contestar me rio, cuando se me propone algo claramente opuesto á lo que me representan estas _ideas inmutables_» (Existencia de Dios, p. 2, n. 33).\"},{\"heading\":false,\"text\":\"Es indudable que en este pasaje habla Fenelon de la evidencia, pues que á mas de que emplea este mismo nombre, se refiere á las ideas inmutables; por sentido comun entiende las mismas ideas generales por las cuales juzgamos de todo, ó en otros términos, las ideas de donde nace la evidencia.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"FIN DE LAS NOTAS.\"},{\"heading\":false,\"text\":\"ÍNDICE DE LAS MATERIAS DEL TOMO PRIMERO.\"},{\"heading\":false,\"text\":\"LIBRO PRIMERO.\"},{\"heading\":false,\"text\":\"DE LA CERTEZA.\"},{\"heading\":false,\"text\":\"CAPÍTULO PRIMERO. _Importancia y utilidad de las cuestiones sobre la certeza_.\"},{\"heading\":false,\"text\":\"Cimiento de la filosofía. Universalidad y constancia de las disputas sobre la certeza. Significado. Amplitud de la cuestion. Utilidad. Su influencia sobre el espíritu.\"},{\"heading\":false,\"text\":\"CAPÍTULO II. _Verdadero estado de la cuestion_.\"},{\"heading\":false,\"text\":\"Tres cuestiones. Ejemplo. Objeto y deberes de la filosofía en este punto. No comienza por un exámen. Fichte. Pirron. Necesidad de la certeza. Su existencia y su naturaleza. Berkeley. Confesion de Hume. Un prurito pueril. Sobriedad necesaria al espíritu. La certeza anterior á todo exámen no es ciega. El dogmatismo y el escepticismo. Se rectifica un dicho de Pascal.\"},{\"heading\":false,\"text\":\"CAPÍTULO III. _Dos certezas_.\"},{\"heading\":false,\"text\":\"La del género humano y la filosófica. La certeza y la reflexion. El desarrollo de las facultades humanas no es reflexivo. Experimentos. Esterilidad de la filosofía con respecto á la certeza. Sus peligros. Su objeto mas razonable. Contradiccion de los filósofos. Resultado.\"},{\"heading\":false,\"text\":\"CAPÍTULO IV. _Si existe la ciencia trascendental en el órden intelectual absoluto_.\"},{\"heading\":false,\"text\":\"Primer principio. Observacion preliminar. Verdad primera. Diferentes aspectos de la cuestion. Santo Tomás. Malebranche. Conjetura sobre la ciencia trascendental, uno de los caractéres distintivos de la inteligencia. La inteligencia y la unidad. Ejemplos de las artes y de las ciencias. Medida de la elevacion de las inteligencias. Carácter del genio.\"},{\"heading\":false,\"text\":\"CAPÍTULO V. _No existe la ciencia trascendental en el órden intelectual humano; no puede dimanar de los sentidos_.\"},{\"heading\":false,\"text\":\"Objeto de la sensacion. No hay una, orígen de la certeza de las demás. Operacion de las cataratas. Dificultad de explicar el desarrollo de los sentidos, y la relacion de las sensaciones. Inutilidad de esta explicacion para la ciencia trascendental. La estatua de Condillac. Observaciones. Resultado.\"},{\"heading\":false,\"text\":\"CAPÍTULO VI. _Continúa la discusion sobre la ciencia trascendental_.\"},{\"heading\":false,\"text\":\"Insuficiencia de las verdades reales. Descrédito del sensualismo. Verdades reales y verdades ideales. Insuficiencia de la verdad real finita. Dos conocimientos de la verdad primera. Necesidad de fecundar las verdades reales con verdades ideales. La unidad de Descartes es triple. La ley única del universo. Sus reaciones con la ciencia trascendental.\"},{\"heading\":false,\"text\":\"CAPÍTULO VII. _Esterilidad de la filosofía del_ yo _para producir la ciencia trascendental_.\"},{\"heading\":false,\"text\":\"Conciencia y evidencia. Una de las causas de la oscuridad y esterilidad de la filosofía alemana desde Fichte. Una ventaja de Kant. Esterilidad del _yo_ como elemento científico. Lo subjetivo y lo objetivo. Acto directo y acto reflejo. Esterilidad de su combinacion si les faltan las verdades necesarias. Lo que sabemos del _yo_. La conciencia universal. El panteismo espiritualista. Dualidad de relacion en todo acto de inteligencia. Dilema contra la filosofía del _yo_. Reflexion fundamental del sistema de Fichte. Su método erróneo. Aserciones gratuitas. Acto primitivo. Reflexiones. Acto indeterminado. Esterilidad de la doctrina de Fichte para encontrar el primer principio. A qué se reduce el aparato de su análisis. Fichte y Descartes. Ventaja del filósofo francés. Panteismo del sistema de Fichte.\"},{\"heading\":false,\"text\":\"CAPÍTULO VIII. _La identidad universal_.\"},{\"heading\":false,\"text\":\"Lo infundado de este error. Un dilema. Contradiccion de ciertos filósofos. Su sistema. Schelling. Una causa de este error. Dificultades del problema del conocimiento. Argumento de los sostenedores de la identidad. Inutilidad de esta doctrina para explicar el conocimiento. Dualidad envuelta en el acto de conocer. Desarrollo de esta observacion. Su mayor fuerza contra la filosofía del _yo_. El misterio de la Trinidad. Platon. Intuicion del _yo_. Principio de ser y de conocer.\"},{\"heading\":false,\"text\":\"CAPÍTULO IX. _Continúa el exámen del sistema de la identidad universal_.\"},{\"heading\":false,\"text\":\"Instinto intelectual en busca de la unidad. Qué es esta unidad. La unidad en la filosofía. La filosofía y la religion. Dos problemas capitales sobre la representacion intelectual. Descartes. Vindicacion de Malebranche.\"},{\"heading\":false,\"text\":\"CAPÍTULO X. _El problema de la representacion_.\"},{\"heading\":false,\"text\":\"Mónadas de Leibnitz. Peligros de la exageracion en la unidad científica. Hecho único. Sus inconvenientes. Un efugio. Mónadas de Leibnitz. Lo infundado de estas hipótesis. Tampoco funda la ciencia trascendental. Diferencias entre este sistema y el de los panteistas modernos.\"},{\"heading\":false,\"text\":\"CAPÍTULO XI. _Exámen del problema de la representacion_.\"},{\"heading\":false,\"text\":\"Tres fuentes de representacion. Relacion de lo representante con lo representado. Consecuencia en favor de la existencia de Dios, sacada de las relaciones de los seres intelectuales y del universo corpóreo. Dos relaciones inmediata y mediata. Objetividad de toda idea. Union de lo inteligente con lo entendido. La identidad fuente de representacion. Cuándo y de qué manera.\"},{\"heading\":false,\"text\":\"CAPÍTULO XII. _Inteligibilidad inmediata_.\"},{\"heading\":false,\"text\":\"Representacion activa y pasiva. Doctrina de Santo Tomás y del cardenal Cayetano. Reflexiones. Un hecho en su apoyo. Dos condiciones de la inteligibilidad inmediata. Consecuencias ideológicas. Resúmen de la doctrina sobre la inteligibilidad.\"},{\"heading\":false,\"text\":\"CAPÍTULO XIII. _Representacion de causalidad y de idealidad_.\"},{\"heading\":false,\"text\":\"La causalidad orígen de representacion. Profundidad de Santo Tomás como filósofo. Idealidad. Dos proposiciones capitales. Condiciones para que la causalidad sea suficiente orígen de representacion. Una observacion sobre las ciencias naturales. Nueva refutacion de la ciencia trascendental. Lo absoluto. Reflexiones sobre esta doctrina. La representacion ideal se refunde en la causal. Vico. Dos consecuencias importantes. Una observacion sobre las ideas-retratos. Indicacion de varias cuestiones sobre las ideas.\"},{\"heading\":false,\"text\":\"CAPÍTULO XIV. _Imposibilidad de hallar el primer principio en el órden ideal_.\"},{\"heading\":false,\"text\":\"Esterilidad de las verdades ideales con respecto al mundo real. Aplicaciones. Necesidad de la union de las verdades reales con las ideales. Esterilidad del órden no geométrico para el geométrico y vice-versa.\"},{\"heading\":false,\"text\":\"CAPÍTULO XV. _La condicion indispensable de todo conocimiento humano_.\"},{\"heading\":false,\"text\":\"Medios de percepcion de la verdad. Estado de la cuestion. Distincion. Conciencia. Evidencia. Instinto intelectual ó sentido comun. Tres órdenes de verdades. Carácter y diferencias de los medios de percepcion y sus objetos. Una observacion sobre el desarrollo de las facultades del hombre.\"},{\"heading\":false,\"text\":\"CAPÍTULO XVI. _Confusion de ideas en las disputas sobre el principio fundamental_.\"},{\"heading\":false,\"text\":\"Anomalías. Sus causas. Estado de la cuestion.\"},{\"heading\":false,\"text\":\"CAPÍTULO XVII. _La existencia del pensamiento_.\"},{\"heading\":false,\"text\":\"Principio de Descartes. Indemostrabilidad de la existencia. No todo se puede demostrar. Aplicaciones. Punto de partida de nuestros conocimientos. Dos sentidos del principio de Descartes. Se explica la mente del filósofo.\"},{\"heading\":false,\"text\":\"CAPÍTULO XVIII. _Mas sobre el principio de Descartes_.\"},{\"heading\":false,\"text\":\"Su método. Ambigüedad del lenguaje de Descartes. Su idea capital. Su duda metódica. En qué sentido es posible. Aplicaciones. Observacion sobre los extravíos de los reformadores. Acuerdo de Descartes con todas las escuelas. Locke. Condillac.\"},{\"heading\":false,\"text\":\"CAPÍTULO XIX. _Lo que vale el principio, yo pienso_.\"},{\"heading\":false,\"text\":\"Su análisis. Significado de la proposicion, yo pienso. Cómo se distingue de la proposicion misma. Exámen de ella bajo el aspecto lógico. Condiciones de su posibilidad. Formacion de la idea del _yo_. Relaciones de la existencia con el pensamiento. Resolucion de tres cuestiones.\"},{\"heading\":false,\"text\":\"CAPÍTULO XX. _Verdadero sentido del principio de contradiccion_.\"},{\"heading\":false,\"text\":\"Opinion de Kant. Fórmula del principio. Opinion del filósofo aleman. Juicios analíticos y sintéticos. Antigüedad de esta distincion. Enmienda de Kant en la fórmula del principio. No tiene fundamento. Equivocacion en la fórmula de Kant. Aplicaciones. Rectificaciones.\"},{\"heading\":false,\"text\":\"CAPÍTULO XXI. _Si el principio de contradiccion merece el título de fundamental, y en qué sentido._\"},{\"heading\":false,\"text\":\"Seis proposiciones sobre esta materia.\"},{\"heading\":false,\"text\":\"CAPÍTULO XXII. _El principio de la evidencia_.\"},{\"heading\":false,\"text\":\"Fórmula llamada de los cartesianos. Su transformacion. Su cotejo con la de Kant. El principio de la evidencia no es evidente. Anomalía. Su explicacion.\"},{\"heading\":false,\"text\":\"CAPÍTULO XXIII. _Criterio de la conciencia_.\"},{\"heading\":false,\"text\":\"Objeto de este criterio. Conciencia directa y conciencia refleja. Sus caractéres y diferencias. Observaciones sobre la fuerza intelectual en estos dos sentidos. Relacion de la conciencia con los demás criterios. Cinco proposiciones que resúmen la doctrina sobre el criterio de la conciencia.\"},{\"heading\":false,\"text\":\"CAPÍTULO XXIV. _Criterio de la evidencia_.\"},{\"heading\":false,\"text\":\"Sus caractéres. Evidencia inmediata. La evidencia es una especie de cuenta y razon. De dónde dimana su necesidad y universalidad. Valor subjetivo de la evidencia. Valor objetivo. Cuestion importante.\"},{\"heading\":false,\"text\":\"CAPÍTULO XXV. _Valor objetivo de las ideas_.\"},{\"heading\":false,\"text\":\"Estado de la cuestion. Doctrina de Descartes. Si se puede probar la veracidad de la evidencia. Un argumento en pro fundado en la necesidad. Fichte. Si se niega la objetividad de las ideas se arruina la unidad de conciencia. Consecuencias absurdas.\"},{\"heading\":false,\"text\":\"CAPÍTULO XXVI. _Si todos los conocimientos se reducen á la percepcion de la identidad_.\"},{\"heading\":false,\"text\":\"Observaciones preliminares. Qué se afirma ó se niega en todo juicio. Qué significa la igualdad en los juicios matemáticos.\"},{\"heading\":false,\"text\":\"CAPÍTULO XXVII. _Continuacion_.\"},{\"heading\":false,\"text\":\"La fórmula A es A. Cómo se aplica á las matemáticas. Ejemplo en las transformaciones de una ecuacion. Reflexiones. Caractéres de nuestra inteligencia. Una necesidad, y una facultad. Dugald-Steward. Se contesta á una dificultad de este autor.\"},{\"heading\":false,\"text\":\"CAPÍTULO XXVIII. _Continuacion_.\"},{\"heading\":false,\"text\":\"Aplicacion de la doctrina de la identidad á los silogismos. Una observacion sobre el entimema. Objeto y utilidad de los medios dialécticos. Ampliacion de la doctrina con ejemplos geométricos y algebráicos.\"},{\"heading\":false,\"text\":\"CAPÍTULO XXIX. _Si hay verdaderos juicios sintéticos á priori, en el sentido de Kant_.\"},{\"heading\":false,\"text\":\"Doctrina del filósofo aleman. Exageracion de sus pretensiones. Su equivocacion sobre los juicios matemáticos. Combinacion del análisis de los conceptos con su comparacion. Qué se necesita para la síntesis segun Kant. En qué consiste la x que él busca. Resúmen de la doctrina sobre los juicios analíticos y sintéticos.\"},{\"heading\":false,\"text\":\"CAPÍTULO XXX. _Criterio de Vico_.\"},{\"heading\":false,\"text\":\"Su sistema. Su aplicacion teológica. Exámen. Objeciones, bajo el aspecto filosófico y el teológico. Doctrina de Santo Tomás. El criterio de Vico y el escepticismo.\"},{\"heading\":false,\"text\":\"CAPÍTULO XXXI. _Continuacion_.\"},{\"heading\":false,\"text\":\"El criterio de Vico en el órden de las verdades ideales. Argumentos en su favor. Impugnacion. Juicio del sistema de Vico. Hasta qué punto es aceptable. Su mérito. Sus inconvenientes Dugald-Steward, de acuerdo con Vico. Los escolásticos.\"},{\"heading\":false,\"text\":\"CAPÍTULO XXXII. _Criterio del sentido comun_.\"},{\"heading\":false,\"text\":\"Significado de estas palabras. Aplicaciones. En qué consiste. Reseña con respecto á los demás criterios. Si es criterio infalible. Cuatro caractéres de su infalibilidad. Ejemplo.\"},{\"heading\":false,\"text\":\"CAPÍTULO XXXIII. _Error de La-Mennais sobre el consentimiento comun_.\"},{\"heading\":false,\"text\":\"Su sistema. Confusion de las dos palabras _sensus_ y _consensus_. Su criterio no puede ser el único. Demostracion. Reseña. Orígen del error de La-Mennais. Se deshace una dificultad. Sus paradojas sobre las matemáticas. Una observacion.\"},{\"heading\":false,\"text\":\"CAPÍTULO XXXIV. _Resúmen y conclusion_.\"},{\"heading\":false,\"text\":\"Rápida exposicion de las doctrinas contenidas en este tomo. Enlace de las mismas. Alianza de los criterios. Una ley de nuestro espíritu. Inconvenientes de una filosofía exclusiva. La filosofía es posible sin escepticismo y sin extravagancias. Un método filosófico puesto en forma de alegoría.\"},{\"heading\":false,\"text\":\"--Notas.\"},{\"heading\":false,\"text\":\"FIN.\"}]}]', 'es', 'https://www.gutenberg.org/ebooks/13608', '{}');
INSERT INTO libros (id, titulo, autor, genero, cover, secciones, idioma, fuente, introducciones) VALUES (15725, 'Doña Perfecta', 'Benito Pérez Galdós', 'novela', 'https://www.gutenberg.org/cache/epub/15725/pg15725.cover.medium.jpg', '[{\"title\":\"Capítulo I\",\"blocks\":[{\"heading\":false,\"text\":\"=Villahorrenda!... cinco minutos!...=\"},{\"heading\":false,\"text\":\"Cuando el tren mixto descendente número 65 (no es preciso nombrar la línea), se detuvo en la pequeña estación situada entre los kilómetros 171 y 172, casi todos los viajeros de segunda y tercera clase se quedaron durmiendo o bostezando [5] dentro de los coches, porque el frío penetrante de la madrugada no convidadas a pasear por el desamparado andén. El único viajero de primera que en el tren venía bajó apresuradamente, y dirigiéndose a los empleados, preguntóles si aquél era el apeadero de Villahorrenda. (Este [10] nombre, como otros muchos que después se verán, es propiedad del autor.)\"},{\"heading\":false,\"text\":\"--En Villahorrenda estamos--repuso el conductor, cuya voz se confundió con el cacarear de las gallinas que en aquel momento eran subidas al furgón.--Se me había olvidado [15] llamarle a usted, Sr. de Rey. Creo que ahí le esperan a usted con las caballerías.\"},{\"heading\":false,\"text\":\"--¡Pero hace aquí un frío de tres mil demonios!--dijo el viajero envolviéndose en su manta.--¿No hay en el apeadero algún sitio donde descansar y reponerse antes de [20] emprender un viaje a caballo por este país de hielo?\"},{\"heading\":false,\"text\":\"No había concluído de hablar, cuando el conductor, llamado por las apremiantes obligaciones de su oficio, marchóse, dejando a nuestro desconocido caballero con la 2 palabra en la boca. Vió éste que se acercaba otro empleado con un farol pendiente de la derecha mano, el cual movíase al compás de la marcha, proyectando geométricas series de [5] ondulaciones luminosas. La luz caía sobre el piso del andén, formando un _zig zag_ semejante al que describe la lluvia de una regadera.\"},{\"heading\":false,\"text\":\"--¿Hay fonda o dormitorio en la estación de Villahorrenda? preguntó el viajero al del farol.\"},{\"heading\":false,\"text\":\"[10] --Aquí no hay nada--respondió éste secamente, corriendo hacia los que cargaban y echándoles tal rociada de votos, juramentos, blasfemias y atroces invocaciones, que hasta las gallinas, escandalizadas de tan grosera brutalidad, murmuraron dentro de sus cestas.\"},{\"heading\":false,\"text\":\"--Lo mejor será salir de aquí a toda prisa--dijo el [15] caballero para su capote.--El conductor me anunció que ahí estaban las caballerías.\"},{\"heading\":false,\"text\":\"Esto pensaba, cuando sintió que una sutil y respetuosa mano le tiraba suavemente del abrigo. Volvióse y vió una obscura masa de paño pardo sobre sí misma revuelta y por [20] cuyo principal pliegue asomaba el avellanado rostro astuto de un labriego castellano. Fijóse en la desgarbada estatura que recordaba al chopo entre los vegetales; vió los sagaces ojos que bajo el ala de ancho sombrero de terciopelo viejo resplandecían; vió la mano morena y acerada que empuñaba [25] una vara verde y el ancho pie que, al moverse, hacía sonajear el hierro de la espuela.\"},{\"heading\":false,\"text\":\"--¿Es usted el Sr. D. José de Rey?--preguntó, echando mano al sombrero.\"},{\"heading\":false,\"text\":\"--Sí; y usted--repuso el caballero con alegría--será [30] el criado de doña Perfecta, que viene a buscarme a este apeadero para conducirme a Orbajosa.\"},{\"heading\":false,\"text\":\"--El mismo. Cuando usted guste marchar... La jaca corre como el viento. Me parece que el Sr. D. José ha de ser buen ginete. Verdad es que a quien de casta le viene...\"},{\"heading\":false,\"text\":\"--¿Por dónde se sale?--dijo el viajero con impaciencia. 3\"},{\"heading\":false,\"text\":\"--Vamos, vámonos de aquí, señor... ¿Cómo se llama usted?\"},{\"heading\":false,\"text\":\"--Me llamo Pedro Lucas--respondió el del paño pardo, [5] repitiendo la intención de quitarse el sombrero; pero me llaman el tío Licurgo. ¿En dónde está el equipaje del señorito?\"},{\"heading\":false,\"text\":\"--Allí bajo el reloj lo veo. Son tres bultos. Dos maletas y un mundo de libros para el Sr. D. Cayetano. Tome [10] usted el talón.\"},{\"heading\":false,\"text\":\"Un momento después señor y escudero hallábanse a espaldas de la barraca llamada estación, frente a un caminejo que partiendo de allí se perdía en las vecinas lomas desnudas, donde confusamente se distinguía el miserable [15] caserío de Villahorrenda. Tres caballerías debían transportar todo, hombres y mundos. Una jaca de no mala estampa era destinada al caballero. El tío Licurgo oprimiría los lomos de un cuartago venerable, algo desvencijado, aunque seguro; y el macho, cuyo freno debía regir [20] un joven zagal de piernas listas y fogosa sangre, cargaría el equipaje.\"},{\"heading\":false,\"text\":\"Antes de que la caravana se pusiese en movimiento, partió el tren, que se iba escurriendo por la vía con la parsimoniosa cachaza de un tren mixto. Sus pasos, retumbando [25] cada vez más lejanos, producían ecos profundos bajo tierra. Al entrar en el túnel del kilómetro 172, lanzó el vapor por el silbato y un aullido estrepitoso resonó en los aires. El túnel, echando por su negra boca un hálito blanquecino, clamoreaba como una trompeta, y al oír su [30] enorme voz, despertaban aldeas, villas, ciudades, provincias. Aquí cantaba un gallo, más allá otro. Principiaba a amanecer.\"},{\"heading\":false,\"text\":\"4\"}]},{\"title\":\"Capítulo II\",\"blocks\":[{\"heading\":false,\"text\":\"=Un viaje por el corazón de España=\"},{\"heading\":false,\"text\":\"Cuando empezada la caminata dejaron a un lado las casuchas de Villahorrenda, el caballero, que era joven y de muy buen ver, habló de este modo:\"},{\"heading\":false,\"text\":\"--Dígame usted, Sr. Solón...\"},{\"heading\":false,\"text\":\"[5] --Licurgo, para servir a usted...\"},{\"heading\":false,\"text\":\"--Eso es, Sr. Licurgo. Bien decía yo que era usted un sabio legislador de la antigüedad. Perdone usted la equivocación. Pero vamos al caso. Dígame usted, ¿cómo está mi señora tía?\"},{\"heading\":false,\"text\":\"[10] --Siempre tan guapa--repuso el labriego, adelantando algunos pasos su caballería.--Parece que no pasan años por la señora doña Perfecta. Bien dicen que al bueno Dios le da larga vida. Así viviera mil años ese ángel del Señor. Si las bendiciones que le echan en la tierra fueran [15] plumas, la señora no necesitaría más alas para subir al cielo.\"},{\"heading\":false,\"text\":\"--¿Y mi prima la señorita Rosario?\"},{\"heading\":false,\"text\":\"--¡Bien haya quien a los suyos parece!--dijo el aldeano.\"},{\"heading\":false,\"text\":\"--¿Qué he de decirle de doña Rosarito, sino que es el vivo retrato de su madre? Buena prenda se lleva usted, caballero [20] D. José, si es verdad, como dicen, que ha venido para casarse con ella. Tal para cual, y la niña no tiene tampoco por qué quejarse. Poco va de Pedro a Pedro.\"},{\"heading\":false,\"text\":\"--¿Y el Sr. D. Cayetano?\"},{\"heading\":false,\"text\":\"--Siempre metidillo en la faena de sus libros. Tiene [25] una biblioteca más grande que la catedral, y también escarba la tierra para buscar piedras llenas de unos demonches de garabatos que dicen escribieron los moros.\"},{\"heading\":false,\"text\":\"--¿En cuánto tiempo llegaremos a Orbajosa?\"},{\"heading\":false,\"text\":\"--A las nueve, si Dios quiere. Poco contenta se va a [30] poner la señora cuando vea a su sobrino.... Y la señorita 5 Rosarito que estaba ayer disponiendo el cuarto en que usted ha de vivir.... Como no le han visto nunca, la madre y la hija están que no viven, pensando en cómo será o cómo no será este Sr. D. José. Ya llegó el tiempo de que callen [5] cartas y hablen barbas. La prima verá al primo y todo será fiesta y gloria. Amanecerá Dios y medraremos, como dijo el otro.\"},{\"heading\":false,\"text\":\"--Como mi tía y mi prima no me conocen todavía--dijo sonriendo el caballero,--no es prudente hacer proyectos.\"},{\"heading\":false,\"text\":\"[10] --Verdad es; por eso se dijo que uno piensa el bayo y otro el que lo ensilla--repuso el labriego.--Pero la cara no engaña... ¡qué alhaja se lleva usted! ¡Y qué buen mozo ella!\"},{\"heading\":false,\"text\":\"El caballero no oyó las últimas palabras del tío Licurgo, [15] porque iba distraído y algo meditabundo. Llegaban a un recodo del camino, cuando el labriego, torciendo la dirección a las caballerías, dijo:\"},{\"heading\":false,\"text\":\"--Ahora tenemos que echar por esta vereda. El puente está roto y no se puede vadear el río sino por el cerrillo de [20] los Lirios.\"},{\"heading\":false,\"text\":\"--¿El cerrillo de los Lirios?--dijo el caballero, saliendo de su meditación.--¡Cómo abundan los nombres poéticos en estos sitios tan feos! Desde que viajo por estas tierras, me sorprende la horrible ironía de los nombres. Tal sitio [25] que se distingue por su yermo aspecto y la desolada tristeza del negro paisaje, se llama _Valleameno_. Tal villorrio de adobes que miserablemente se extiende sobre un llano árido y que de diversos modos pregona su pobreza, tiene la insolencia de nombrarse _Villarica_; y hay un barranco pedregoso [30] y polvoriento, donde ni los cardos encuentran jugo, y que sin embargo se llama _Valdeflores_. ¿Eso que tenemos delante es el _Cerrillo de los Lirios_? ¿Pero dónde están esos lirios, hombre de Dios? Yo no veo más que piedras y yerba descolorida. Llamen a eso el _Cerrillo de la Desolación_ y hablarán a derechas. Exceptuando _Villahorrenda_, que 6 parece ha recibido al mismo tiempo el nombre y la hechura, todo aquí es ironía. Palabras hermosas, realidad prosaica y miserable. Los ciegos serían felices en este país, que [5] para la lengua es paraíso y para los ojos infierno.\"},{\"heading\":false,\"text\":\"El Sr. Licurgo o no entendió las palabras del caballero Rey o no hizo caso de ellas. Cuando vadearon el río, que turbio y revuelto corría con impaciente precipitación, como si huyera de sus propias orillas, el labriego extendió el brazo [10] hacia unas tierras que a la siniestra mano en grande y desnuda extensión se veían, y dijo:\"},{\"heading\":false,\"text\":\"--Estos son los _Alamillos de Bustamente_.\"},{\"heading\":false,\"text\":\"--¡Mis tierras!--exclamó con júbilo el caballero, tendiendo la vista por los tristes campos que alumbraban las [15] primeras luces de la mañana.--Es la primera vez que veo el patrimonio que heredé de mi madre. La pobre hacía tales ponderaciones de este país y me contaba tantas maravillas de él, que yo, siendo niño, creía que estar aquí era estar en la gloria. Frutas, flores, caza mayor y menor, [20] montes, lagos, ríos, poéticos arroyos, oteros pastoriles, todo lo había en los _Alamillos de Bustamente_, en esta tierra bendita, la mejor y más hermosa de todas las tierras.... ¡Qué demonio! La gente de este país vive con la imaginación. Si en mi niñez, y cuando vivía con las ideas y con [25] el entusiasmo de mi buena madre, me hubieran traído aquí, también me habrían parecido encantadores estos desnudos cerros, estos llanos polvorientos o encharcados, estas vetustas casas de labor, estas norias desvencijadas, cuyos cangilones lagrimean lo bastante para regar media docena de [30] coles, esta desolación miserable y perezosa que estoy mirando.\"},{\"heading\":false,\"text\":\"--Es la mejor tierra del país--dijo el señor Licurgo--y para el garbanzo es de lo que no hay.\"},{\"heading\":false,\"text\":\"--Pues lo celebro, porque desde que las heredé no me han producido un cuarto estas célebres tierras.\"},{\"heading\":false,\"text\":\"El sabio legislador espartano se rascó la oreja y dió un 7 suspiro.\"},{\"heading\":false,\"text\":\"--Pero me han dicho--continuó el caballero--que algunos propietarios colindantes han metido su arado en estos [5] grandes estados míos, y poco a poco me los van cercenando. Aquí no hay mojones, ni linderos, ni verdadera propiedad, Sr. Licurgo.\"},{\"heading\":false,\"text\":\"El labriego, después de una pausa, durante la cual parecía ocupar su sutil espíritu en profundas disquisiciones, se expresó [10] de este modo:\"},{\"heading\":false,\"text\":\"--El tío Pasolargo, a quien llamamos el _Filósofo_ por su mucha trastienda, metió el arado en los _Alamillos_ por encima de la ermita, y roe que roe, se ha zampado seis fanegadas.\"},{\"heading\":false,\"text\":\"--¡Qué incomparable escuela!--exclamó riendo el caballero. [15] --Apostaré que no ha sido ese el único... filósofo.\"},{\"heading\":false,\"text\":\"--Bien dijo el otro, que quien las sabe las tañe, y si al palomar no le falta cebo no le faltarán palomas.... Pero usted, Sr. D. José, puede decir aquello de que el ojo del amo engorda la vaca, y ahora que está aquí ver de recobrar [20] su finca.\"},{\"heading\":false,\"text\":\"--Quizás no sea tan fácil, Sr. Licurgo--repuso el caballero, a punto que entraban por una senda a cuyos lados se veían hermosos trigos que con su lozanía y temprana madurez recreaban la vista.--Este campo parece mejor cultivado. [25] Veo que no todo es tristeza y miseria en los _Alamillos_.\"},{\"heading\":false,\"text\":\"El labriego puso cara de lástima, y afectando cierto desdén hacia los campos elogiados por el viajero, dijo en tono humildísimo:\"},{\"heading\":false,\"text\":\"--Señor, esto es mío.\"},{\"heading\":false,\"text\":\"[30] --Perdone usted--replicó vivamente el caballero--ya quería yo meter mi hoz en los estados de usted. Por lo visto, la filosofía aquí es contagiosa.\"},{\"heading\":false,\"text\":\"Bajaron inmediatamente a una cañada, que era lecho de pobre y estancado arroyo, y pasado éste, entraron en un campo lleno de piedras, sin la más ligera muestra de vegetación. 8 --Esta tierra es muy mala--dijo el caballero, volviendo el rostro para mirar a su guía y compañero que se había [5] quedado un poco atrás.--Difícilmente podrá usted sacar partido de ella, porque todo es fango y arena.\"},{\"heading\":false,\"text\":\"Licurgo, lleno de mansedumbre, contestó:\"},{\"heading\":false,\"text\":\"--Esto... es de usted.\"},{\"heading\":false,\"text\":\"--Veo que aquí todo lo malo es mío--afirmó el caballero, [10] riendo jovialmente.\"},{\"heading\":false,\"text\":\"Cuando esto hablaban, tomaron de nuevo el camino real. Ya la luz del día, entrando en alegre irrupción por todas las ventanas y claraboyas del hispano horizonte, inundó de esplendorosa claridad los campos. El inmenso cielo sin [15] nubes parecía agrandarse más y alejarse de la tierra para verla y en su contemplación recrearse desde más alto. La desolada tierra sin árboles, pajiza a trechos, a trechos de color gredoso, dividida toda en triángulos y cuadriláteros amarillos o negruzcos, pardos o ligeramente verdegueados, [20] semejaba en cierto modo a la capa del harapiento que se pone al sol. Sobre aquella capa miserable el cristianismo y el islamismo habían trabado épicas batallas. Gloriosos campos, sí, pero los combates de antaño les habían dejado horribles.\"},{\"heading\":false,\"text\":\"--Me parece que hoy picará el sol, Sr. Licurgo--dijo el [25] caballero, desembarazándose un poco del abrigo en que se envolvía.--¡Qué triste camino! No se ve ni un solo árbol en todo lo que alcanza la vista. Aquí todo es al revés. La ironía no cesa. ¿Por qué, si no hay aquí álamos grandes ni chicos, se ha de llamar esto los _Alamillos_?\"},{\"heading\":false,\"text\":\"[30] El tío Licurgo no contestó a la pregunta, porque con toda su alma atendía a ciertos lejanos ruidos que de improviso se oyeron, y con ademán intranquilo detuvo su cabalgadura, mientras exploraba el camino y los cerros lejanos con sombría mirada.\"},{\"heading\":false,\"text\":\"--¿Qué hay?--preguntó el viajero, deteniéndose también. 9\"},{\"heading\":false,\"text\":\"--¿Trae usted armas, D. José?\"},{\"heading\":false,\"text\":\"--Un revólver.... ¡Ah! ya comprendo. ¿Hay [5] ladrones?\"},{\"heading\":false,\"text\":\"--Puede...--repuso el labriego con mucho recelo.-- Me parece que sonó un tiro.\"},{\"heading\":false,\"text\":\"--Allá lo veremos... ¡adelante!--dijo el caballero picando su jaca.--No serán tan temibles.\"},{\"heading\":false,\"text\":\"[10] --Calma, Sr. D. José--exclamó el aldeano deteniéndole. --Esa gente es más mala que Satanás. El otro día asesinaron a dos caballeros que iban a tomar el tren.... Dejémonos de fiestas. Gasparón el Fuerte, Pepito Chispillas, Merengue y Ahorca Suegras no me verán la cara en mis [15] días. Echemos por la vereda.\"},{\"heading\":false,\"text\":\"--Adelante, Sr. Licurgo.\"},{\"heading\":false,\"text\":\"--Atrás, Sr. D. José--replicó el labriego con afligido acento.--Usted no sabe bien qué gente es esa. Ellos fueron los que en el mes pasado robaron de la iglesia del [20] Carmen el copón, la corona de la Virgen y dos candeleros; ellos fueron los que hace dos años robaron el tren que iba para Madrid.\"},{\"heading\":false,\"text\":\"Don José, al oír tan lamentables antecedentes, sintió que aflojaba un poco su intrepidez.\"},{\"heading\":false,\"text\":\"[25] --¿Ve usted aquel cerro grande y empinado que hay allá lejos? Pues allí se esconden esos pícaros en unas cuevas que llaman la _Estancia de los Caballeros_.\"},{\"heading\":false,\"text\":\"--¡De los Caballeros!\"},{\"heading\":false,\"text\":\"--Sí señor. Bajan al camino real, cuando la Guardia [30] civil se descuida, y roban lo que pueden. ¿No ve usted más allá de la vuelta del camino una cruz, que se puso en memoria de la muerte que dieron al alcalde de Villahorrenda cuando las elecciones?\"},{\"heading\":false,\"text\":\"--Sí, veo la cruz.\"},{\"heading\":false,\"text\":\"--Allí hay una casa vieja, en la cual se esconden para 10 aguardar a los tragineros. A aquel sitio llamamos las _Delicias_.\"},{\"heading\":false,\"text\":\"--¡Las Delicias!...\"},{\"heading\":false,\"text\":\"[5] --Si todos los que han sido muertos y robados al pasar por ahí resucitaran, podría formarse con ellos un ejército.\"},{\"heading\":false,\"text\":\"Cuando esto decían, oyéronse más de cerca los tiros, lo que turbó un poco el esforzado corazón de los viajantes, [10] pero no el del zagalillo que, retozando de alegría, pidió al Sr. Licurgo licencia para adelantarse y ver la batalla que tan cerca se había trabado. Observando la decisión del muchacho, avergonzóse D. José de haber sentido miedo, o cuando menos un poco de respeto a los ladrones, y exclamó, [15] espoleando la jaca:\"},{\"heading\":false,\"text\":\"--Pues allá iremos todos. Quizás podamos prestar auxilio a los infelices viajeros que en tan gran aprieto se ven, y poner las peras a cuarto a los _caballeros_.\"},{\"heading\":false,\"text\":\"Esforzábase el labriego en convencer al joven de la temeridad [20] de sus propósitos, así como de lo inútil de su generosa idea, porque los robados robados estaban y quizás muertos, y en situación de no necesitar auxilio de nadie. Insistía el señor a pesar de estas sesudas advertencias, contestaba el aldeano, poniendo la más viva resistencia, cuando la presencia [25] de dos o tres carromateros que por el camino abajo tranquilamente venían conduciendo una galera, puso fin a la cuestión. No debía de ser grande el peligro, cuando tan sin cuidado venían aquéllos, cantando alegres coplas; y así fué en efecto, porque los tiros, según dijeron, no eran disparados [30] por los ladrones, sino por la Guardia civil, que de este modo quería cortar el vuelo a media docena de cacos que ensartados conducía a la cárcel de la villa.\"},{\"heading\":false,\"text\":\"--Ya, ya sé lo que ha sido--dijo Licurgo, señalando leve humareda que a mano derecha del camino y a regular distancia se descubría.--Allí les han escabechado. Esto 11 pasa un día sí y otro no.\"},{\"heading\":false,\"text\":\"El caballero no comprendía.\"},{\"heading\":false,\"text\":\"--Yo le aseguro al Sr. D. José--añadió con energía el [5] legislador lacedemonio,--que está muy retebién hecho; porque de nada sirve formar causa a esos pillos. El juez les marea un poco y después les suelta. Si al cabo de seis años de causa, alguno va a presidio, a lo mejor se escapa, o le indultan y vuelve a la Estancia de los Caballeros. Lo [10] mejor es esto: ¡fuego en ellos! Se les lleva a la cárcel, y cuando se pasa por un lugar a propósito... \\\"¡ah! perro, que te quieres escapar... pum, pum\\\".... Ya está hecha la sumaria, requeridos los testigos, celebrada la vista, dada la sentencia.... Todo en un minuto. Bien [15] dicen, que si mucho sabe la zorra, más sabe el que la toma.\"},{\"heading\":false,\"text\":\"--Pues adelante, y apretemos el paso, que este camino, a más de largo, no tiene nada de ameno--dijo Rey.\"},{\"heading\":false,\"text\":\"Al pasar junto a las Delicias, vieron, a poca distancia del camino, a los guardias que minutos antes habían ejecutado [20] la extraña sentencia que el lector sabe. Mucha pena causó al zagalillo que no le permitieran ir a contemplar de cerca los palpitantes cadáveres de los ladrones, que en horroroso grupo se distinguían a lo lejos, y siguieron todos adelante. Pero no habían andado veinte pasos, cuando sintieron el [25] galopar de un caballo que tras ellos venía con tanta rapidez, que por momentos les alcanzaba. Volvióse nuestro viajero y vió un hombre, mejor dicho, un Centauro, pues no podía concebirse más perfecta armonía entre caballo y ginete, el cual era de complexión recia y sanguínea, ojos grandes, [30] ardientes, cabeza ruda, negros bigotes, mediana edad y el aspecto en general brusco y provocativo, con indicios de fuerza en toda su persona. Montaba un soberbio caballo de pecho carnoso, semejante a los del Partenón, enjaezado según el modo pintoresco del país, y sobre la grupa llevaba una gran balija de cuero, en cuya tapa se veía en letras 12 gordas la palabra _Correo_.\"},{\"heading\":false,\"text\":\"--Hola, buenos días, Sr. Caballuco--dijo Licurgo, saludando al ginete, cuando estuvo cerca.--¡Cómo le hemos [5] tomado la delantera! pero usted llegará antes si se pone a ello.\"},{\"heading\":false,\"text\":\"--Descansemos un poco--repuso el señor Caballuco, poniendo su cabalgadura al paso de la de nuestros viajeros, y observando atentamente al más principal de los tres.-- [10] Puesto que hay tan buena compaña....\"},{\"heading\":false,\"text\":\"--El señor--dijo Licurgo sonriendo,--es el sobrino de doña Perfecta.\"},{\"heading\":false,\"text\":\"--¡Ah!... por muchos años... muy señor mío y mi dueño....\"},{\"heading\":false,\"text\":\"[15] Ambos personajes se saludaron, siendo de notar que Caballuco hizo sus urbanidades con una expresión de altanería y superioridad que revelaba cuando menos la conciencia de un gran valer o de una alta posición en la comarca. Cuando el orgulloso ginete se apartó y por breve momento [20] se detuvo hablando con dos Guardias civiles que llegaron al camino, el viajero preguntó a su guía:\"},{\"heading\":false,\"text\":\"--¿Quién es este pájaro?\"},{\"heading\":false,\"text\":\"--¿Quién ha de ser? Caballuco.\"},{\"heading\":false,\"text\":\"--¿Y quién es Caballuco?\"},{\"heading\":false,\"text\":\"[25] --¡Toma!... ¿pero no le ha oído usted nombrar?-- dijo el labriego, asombrado de la ignorancia supina del sobrino de doña Perfecta.--Es un hombre muy valiente, gran ginete, y el primer caballista de todas estas tierras a la redonda. En Orbajosa le queremos mucho; pues él es... [30] dicho sea en verdad... tan bueno como la bendición de Dios... Ahí donde le ve, es un cacique tremendo, y el Gobernador de la provincia se le quita el sombrero.\"},{\"heading\":false,\"text\":\"--Cuando hay elecciones...\"},{\"heading\":false,\"text\":\"--Y el Gobierno de Madrid le escribe oficios con mucha vuecencia en el rétulo.... Tira a la barra como un San 13 Cristóbal, y todas las armas las maneja como manejamos nosotros nuestros propios dedos. Cuando había fielato no podían con él, y todas las noches sonaban tiros en las [5] puertas de la ciudad... Tiene una gente que vale cualquier dinero, porque lo mismo es para un fregado que para un barrido.... Favorece a los pobres, y el que venga de fuera y se atreva a tentar el pelo de la ropa a un hijo de Orbajosa, ya puede verse con él.... Aquí no vienen [10] casi nunca soldados de los Madriles; cuando han estado, todos los días corría la sangre, porque Caballuco les buscaba camorra por un no y por un sí. Ahora parece que vive en la pobreza y se ha quedado con la conducción del correo; pero está metiendo fuego en el Ayuntamiento para que haya [15] otra vez fielato y rematarlo él. No sé cómo no le ha oído usted nombrar en Madrid, porque es hijo de un famoso Caballuco que estuvo en la facción, el cual Caballuco padre era hijo de otro Caballuco abuelo, que también estuvo en la facción de más allá.... Y como ahora andan diciendo que [20] vuelve a haber facción, porque todo está torcido y revuelto, tememos que Caballuco se nos vaya también a ella, poniendo fin de esta manera a las hazañas de su padre y abuelo, que por gloria nuestra nacieron en esta ciudad.\"},{\"heading\":false,\"text\":\"Sorprendido quedó nuestro viajero al ver la especie de [25] caballería andante que aún subsistía en los lugares que visitaba, pero no tuvo ocasión de hacer nuevas preguntas, porque el mismo que era objeto de ellas se les incorporó, diciendo de mal talante:\"},{\"heading\":false,\"text\":\"--La Guardia civil ha despachado a tres. Ya le he dicho [30] al cabo que se ande con cuidado. Mañana hablaremos el Gobernador de la provincia y yo....\"},{\"heading\":false,\"text\":\"--¿Va usted a X?\"},{\"heading\":false,\"text\":\"--No, que el Gobernador viene acá, señor Licurgo; sepa usted que nos van a meter en Orbajosa un par de regimientos.\"},{\"heading\":false,\"text\":\"--Sí--dijo vivamente el viajero, sonriendo.--En Madrid 14 oí decir que había temor de que se levantaran en este país algunas partidillas... Bueno es prevenirse.\"},{\"heading\":false,\"text\":\"--En Madrid no dicen más que desatinos...--exclamó [5] violentamente el Centauro, acompañando su afirmación de una retahíla de vocablos de esos que levantan ampolla. En Madrid no hay más que pillería... ¿A qué nos mandan soldados? ¿Para sacarnos más contribuciones y un par de quintas seguidas? ¡Por vida de!... que si no hay [10] facción debería haberla. Con que usted--añadió, mirando socarronamente al joven caballero,--¿con que usted es el sobrino de doña Perfecta?\"},{\"heading\":false,\"text\":\"Esta salida de tono y el insolente mirar del bravo enfadaron al joven.\"},{\"heading\":false,\"text\":\"[15] --Sí, señor. ¿Se le ofrece a usted algo?\"},{\"heading\":false,\"text\":\"--Soy amigo de la señora y la quiero como a las niñas de mis ojos--dijo Caballuco.--Puesto que usted va a Orbajosa, allá nos veremos.\"},{\"heading\":false,\"text\":\"Y sin decir más picó espuelas a su corcel, el cual, partiendo [20] a escape, desapareció entre una nube de polvo.\"},{\"heading\":false,\"text\":\"Después de media hora de camino, durante la cual el Sr. D. José no se mostró muy comunicativo, ni el Sr. Licurgo tampoco, apareció a los ojos de entrambos apiñado y viejo caserío asentado en una loma, y del cual se destacaban [25] algunas negras torres y la ruinosa fábrica de un despedazado castillo en lo más alto. Un amasijo de paredes deformes de casuchas de tierra pardas y polvorosas como el suelo, formaba la base, con algunos fragmentos de almenadas murallas, a cuyo amparo mil chozas humildes alzaban [30] sus miserables frontispicios de adobes, semejantes a caras anémicas y hambrientas que pedían una limosna al pasajero. Pobrísimo río ceñía, como un cinturón de hojalata, el pueblo, refrescando al pasar algunas huertas, única frondosidad que alegraba la vista. Entraba y salía la gente en caballerías o a pie, y el movimiento humano, aunque pequeño, 15 daba cierta apariencia vital a aquella gran morada, cuyo aspecto arquitectónico era más bien de ruina y muerte que de progreso y vida. Los innumerables y repugnantes [5] mendigos que se arrastraban a un lado y otro del camino, pidiendo el óbolo del pasajero, ofrecían lastimoso espectáculo. No podían verse existencias que mejor cuadraran, ni que más apropiadas fueran a las grietas de aquel sepulcro, donde una ciudad estaba no sólo enterrada sino también [10] podrida. Cuando nuestros viajeros se acercaban, algunas campanas tocando desacordemente indicaban con su expresivo son que aquella momia tenía todavía un alma.\"},{\"heading\":false,\"text\":\"Llamábase Orbajosa, ciudad que no en Geografía caldea o cophta, sino en la de España, figura con 7,324 habitantes, [15] Ayuntamiento, sede episcopal, partido judicial, seminario, depósito de caballos sementales, instituto de segunda enseñanza y otras prerogativas oficiales.\"},{\"heading\":false,\"text\":\"--Están tocando a misa mayor en la catedral--dijo el tío Licurgo.--Llegamos antes de lo que pensé.\"},{\"heading\":false,\"text\":\"[20] --El aspecto de su patria de usted--dijo el caballero, examinando el panorama que delante tenía,--no puede ser más desagradable. La histórica ciudad de Orbajosa,[1] cuyo nombre es, sin duda, corrupción de _urbs augusta_, parece un gran muladar.\"},{\"heading\":false,\"text\":\"[Nota 1: Ya se ha dicho que todos los nombres locales son imaginarios.]\"},{\"heading\":false,\"text\":\"[25] --Es que de aquí no se ven más que los arrabales--afirmó con disgusto el guía.--Cuando entre usted en la calle Real y en la del Condestable, verá fábricas tan hermosas como la de la catedral.\"},{\"heading\":false,\"text\":\"--- No quiero hablar mal de Orbajosa antes de conocerla--dijo [30] el caballero.--Lo que he dicho no es tampoco señal de desprecio; que humilde y miserable, lo mismo que hermosa y soberbia, esa ciudad será siempre para mí muy querida, no sólo por ser patria de mi madre, sino porque en ella viven personas a quienes amo ya sin conocerlas. Entremos, 16 pues, en la ciudad _augusta_.\"},{\"heading\":false,\"text\":\"Subían ya por una calzada próxima a las primeras calles, e iban tocando las tapias de las huertas.\"},{\"heading\":false,\"text\":\"[5] --¿Ve usted aquella gran casa que está al fin de esta gran huerta por cuyo bardal pasamos ahora?--dijo el tío Licurgo, señalando el enorme paredón revocado de la única vivienda que tenía aspecto de habitabilidad cómoda y alegre.\"},{\"heading\":false,\"text\":\"--Ya... ¿aquella es la vivienda de mi tía?\"},{\"heading\":false,\"text\":\"[10] --Justo y cabal. Lo que vemos es la parte trasera de la casa. El frontis da a la calle del Condestable, y tiene cinco balcones de hierro que parecen cinco castillos. Esta hermosa huerta que hay tras la tapia es la de la casa, y si usted se alza sobre los estribos, la verá toda desde aquí.\"},{\"heading\":false,\"text\":\"[15] --Pues estamos ya en casa--dijo el caballero.--¿No se puede entrar por aquí?\"},{\"heading\":false,\"text\":\"--Hay una puertecilla; pero la señora la mandó tapiar.\"},{\"heading\":false,\"text\":\"El caballero se alzó sobre los estribos, y alargando cuanto pudo la cabeza, miró por encima de las bardas.\"},{\"heading\":false,\"text\":\"[20] --Veo la huerta toda--indicó.--Allí, bajo aquellos árboles, está una mujer, una chiquilla... una señorita....\"},{\"heading\":false,\"text\":\"--Es la señorita Rosario--repuso Licurgo.\"},{\"heading\":false,\"text\":\"Y al instante se alzó también sobre los estribos para mirar.\"},{\"heading\":false,\"text\":\"[25] --¡Eh! señorita Rosario--gritó, haciendo con la derecha mano gestos muy significativos.--Ya estamos aquí... aquí le traigo a su primo.\"},{\"heading\":false,\"text\":\"--Nos ha visto--dijo el caballero, estirando el pescuezo hasta el último grado.--Pero si no me engaño, al lado de [30] ella está un clérigo... un señor sacerdote.\"},{\"heading\":false,\"text\":\"--Es el señor Penitenciario--repuso con naturalidad el labriego.\"},{\"heading\":false,\"text\":\"--Mi prima nos ve... deja solo al clérigo, y echa a correr hacia la casa... Es bonita....\"},{\"heading\":false,\"text\":\"--Como un sol. 17\"},{\"heading\":false,\"text\":\"--Se ha puesto más encarnada que una cereza. Vamos, vamos, Sr. Licurgo.\"}]},{\"title\":\"Capítulo III\",\"blocks\":[{\"heading\":false,\"text\":\"=Pepe Rey=\"},{\"heading\":false,\"text\":\"Antes de pasar adelante, conviene decir quién era Pepe [5] Rey y qué asuntos le llevaban a Orbajosa.\"},{\"heading\":false,\"text\":\"Cuando el brigadier Rey murió en 1841, sus dos hijos, Juan y Perfecta, acababan de casarse, ésta con el más rico proprietario de Orbajosa, aquél con una joven de la misma ciudad. Llamábase el esposo de Perfecta don Manuel María [10] José de Polentinos, y la mujer de Juan, María Polentinos; pero a pesar de la igualdad de apellido, su parentesco era un poco lejano y de aquellos que no coge un galgo. Juan Rey era insigne jurisconsulto graduado en Sevilla, y ejerció la abogacía en esta misma ciudad durante treinta años, con [15] tanta gloria como provecho. En 1845 era ya viudo y tenía un hijo que empezaba a hacer diabluras; solía tener por entretenimiento el construir con tierra en el patio de la casa viaductos, malecones, estanques, presas, acequias, soltando después el agua para que entre aquellas frágiles [20] obras corriese. El padre le dejaba hacer y decía: \\\"tú serás ingeniero.\\\"\"},{\"heading\":false,\"text\":\"Perfecta y Juan dejaron de verse desde que uno y otro se casaron, porque ella se fué a vivir a Madrid con el opulentísimo Polentinos, que tenía tanta hacienda como buena [25] mano para gastarla. El juego y las mujeres cautivaban de tal modo el corazón de Manuel María José, que habría dado en tierra con toda su fortuna, si más pronto que él para derrocharla no estuviera la muerte para llevárselo a él. En una noche de orgía acabaron de súbito los días de aquel [30] ricacho provinciano, tan vorazmente chupado por las sanguijuelas de la corte y por el insaciable vampiro del juego. 18 Su única heredera era una niña de pocos meses. Con la muerte del esposo de Perfecta se acabaron los sustos en la familia; pero empezó el gran conflicto. La casa de [5] Polentinos estaba arruinada; las fincas en peligro de ser arrebatadas por los prestamistas, todo en desorden, enormes deudas, lamentable administración en Orbajosa, descrédito y ruina en Madrid.\"},{\"heading\":false,\"text\":\"Perfecta llamó a su hermano, el cual, acudiendo en auxilio [10] de la pobre viuda, mostró tanta diligencia y tino, que al poco tiempo la mayor parte de los peligros habían desaparecido. Principió por obligar a su hermana a residir en Orbajosa, administrando por sí misma sus vastas tierras, mientras él hacía frente en Madrid al formidable empuje de los [15] acreedores. Poco a poco fué descargándose la casa del enorme fardo de sus deudas, porque el bueno de D. Juan Rey, que tenía la mejor mano del mundo para tales asuntos, lidió con la curia, hizo contratos con los principales acreedores, estableció plazos para el pago, resultando de este [20] hábil trabajo que el riquísimo patrimonio de Polentinos saliese a flote, y pudiera seguir dando por luengos años esplendor y gloria a la ilustre familia.\"},{\"heading\":false,\"text\":\"La gratitud de Perfecta era tan viva, que al escribir a su hermano desde Orbajosa, donde resolvió residir hasta que [25] creciera su hija, le decía entre otras ternezas: \\\"Has sido más que hermano para mí, y para mi hija más que su propio padre. ¿Cómo te pagaremos ella y yo tan grandes beneficios? ¡Ay! querido hermano, desde que mi hija sepa discurrir y pronunciar un nombre, yo le enseñaré a bendecir [30] el tuyo. Mi agradecimiento durará toda mi vida. Tu hermana indigna siente no encontrar ocasión de mostrarte lo mucho que te ama y de recompensarte de un modo apropiado a la grandeza de tu alma y a la inmensa bondad de tu corazón.\\\"\"},{\"heading\":false,\"text\":\"Cuando esto se escribía, Rosarito tenía dos años. Pepe 19 Rey, encerrado en un colegio de Sevilla, hacía rayas en un papel, ocupándose en probar que _la suma de los ángulos interiores de un polígono vale tantas veces dos rectos como lados [5] tiene menos dos_. Estas enfadosas perogrulladas le traían muy atareado. Pasaron años y más años. El muchacho crecía y no cesaba de hacer rayas. Por último, hizo una que se llama _De Tarragona a Montblanch_. Su primer juguete formal fué el puente de 120 metros sobre el río [10] Francolí.\"},{\"heading\":false,\"text\":\"Durante mucho tiempo, doña Perfecta siguió viviendo en Orbajosa. Como su hermano no salió de Sevilla, pasaron unos pocos años sin que uno y otro se vieran. Una carta trimestral, tan puntualmente escrita como puntualmente [15] contestada, ponía en comunicación aquellos dos corazones, cuya ternura ni el tiempo ni la distancia podían enfriar. En 1870, cuando D. Juan Rey, satisfecho de haber desempeñado bien su misión en la sociedad, se retiró a vivir en su hermosa casa de Puerto Real, Pepe, que ya había trabajado [20] algunos años en las obras de varias poderosas compañías constructoras, emprendió un viaje de estudio a Alemania e Inglaterra. La fortuna de su padre (tan grande como puede serlo en España la que sólo tiene por origen un honrado bufete), le permitía librarse en breves períodos del yugo del [25] trabajo material. Hombre de elevadas ideas y de inmenso amor a la ciencia, hallaba su más puro goce en la observación y estudio de los prodigios con que el genio del siglo sabe cooperar a la cultura y bienestar físico y perfeccionamiento moral del hombre.\"},{\"heading\":false,\"text\":\"[30] Al regresar del viaje, su padre le anunció la revelación de un importante proyecto, y como Pepe creyera que se trataba de un puente, dársena o cuando menos saneamiento de marismas, sacóle de tal error D. Juan, manifestándole su pensamiento en estos términos:\"},{\"heading\":false,\"text\":\"--Estamos en Marzo y la carta trimestral de Perfecta no 20 podía faltar. Querido hijo, léela, y si estás conforme con lo que en ella manifiesta esa santa y ejemplar mujer, mi querida hermana, me darás la mayor felicidad que en mi [5] vejez puedo desear. Si no te gustase el proyecto, deséchalo sin reparo, aunque tu negativa me entristezca; que en él no hay ni sombra de imposición por parte mía. Sería indigno de mí y de ti que esto se realizase por coacción de un padre terco. Eres libre de aceptar o no, y si hay en tu [10] voluntad la más ligera resistencia, originada en ley del corazón o en otra causa, no quiero que te violentes por mí.\"},{\"heading\":false,\"text\":\"Pepe dejó la carta sobre la mesa, después de pasar la vista por ella, y tranquilamente dijo:\"},{\"heading\":false,\"text\":\"--Mi tía quiere que me case con Rosario.\"},{\"heading\":false,\"text\":\"[15] --Ella contesta aceptando con gozo mi idea--dijo el padre muy conmovido.--Porque la idea fué mía... sí, hace tiempo, hace tiempo que la concebí... pero no había querido decirte nada, antes de conocer el pensamiento de mi hermana. Como ves, Perfecta acoge con júbilo mi plan; [20] dice que también había pensado en lo mismo; pero que no se atrevía a manifestármelo, por ser tú... ¿no ves lo que dice? \\\"por ser tú un joven de singularísimo mérito, y su hija una joven aldeana educada sin brillantez, ni mundanales atractivos....\\\" Así mismo lo dice.... ¡Pobre [25] hermana mía! ¡Qué buena es!... Veo que no te enfadas; veo que no te parece absurdo este proyecto mío, algo parecido a la previsión oficiosa de los padres de antaño, que casaban a sus hijos sin consultárselo, y las más veces haciendo uniones disparatadas y prematuras.... Dios [30] quiera que ésta sea o prometa ser de las más felices. Es verdad que no conoces a mi sobrina; pero tú y yo tenemos noticias de su virtud, de su discreción, de su modestia y noble sencillez. Para que nada le falte, hasta es bonita.... Mi opinión--añadió festivamente,--es que te pongas en camino y pises el suelo de esa recóndita ciudad episcopal, 21 de esa _urbs augusta_, y allí, en presencia de mi hermana y de su graciosa Rosarito, resuelvas si ésta ha de ser algo más que mi sobrina.\"},{\"heading\":false,\"text\":\"[5] Pepe volvió a tomar la carta y la leyó con cuidado. Su semblante no expresaba alegría ni pesadumbre. Parecía estar examinando un proyecto de empalme de dos vías férreas.\"},{\"heading\":false,\"text\":\"--Por cierto--decía D. Juan,--que en esa remota [10] Orbajosa, donde, entre paréntesis, tienes fincas que puedes examinar ahora, se pasa la vida con la tranquilidad y dulzura de los idilios. ¡Qué patriarcales costumbres! ¡Qué nobleza en aquella sencillez! ¡Qué rústica paz virgiliana! Si en vez de ser matemático fueras latinista, repetirías al [15] entrar allí el _ergo tua rura manebunt_. ¡Qué admirable lugar para dedicarse a la contemplación de nuestra propia alma y prepararse a las buenas obras! Allí todo es bondad, honradez; allí no se conocen la mentira y la farsa como en nuestras grandes ciudades; allí renacen las santas [20] inclinaciones que el bullicio de la moderna vida ahoga; allí despierta la dormida fe, y se siente vivo impulso indefinible dentro del pecho, al modo de pueril impaciencia que en el fondo de nuestra alma grita: \\\"quiero vivir.\\\"\"},{\"heading\":false,\"text\":\"Pocos días después de esta conferencia, Pepe salió de [25] Puerto Real. Había rehusado meses antes una comisión del Gobierno para examinar bajo el punto de vista minero la cuenca del río Nahara en el valle de Orbajosa; pero los proyectos a que dió lugar la conferencia referida, le hicieron decir:--\\\"Conviene aprovechar el tiempo. Sabe Dios lo [30] que durará ese noviazgo y el aburrimiento que traerá consigo.\\\" Dirigióse a Madrid, solicitó la comisión de explorar la cuenca del Nahara, se la dieron sin dificultad, a pesar de no pertenecer oficialmente al cuerpo de minas, púsose luego en marcha, y después de trasbordar un par de veces, el tren mixto número 65 le llevó, como se ha visto, a los amorosos 22 brazos del tío Licurgo.\"},{\"heading\":false,\"text\":\"Frisaba la edad de este excelente joven en los treinta y cuatro años. Era de complexión fuerte y un tanto hercúlea, [5] con rara perfección formado, y tan arrogante, que si llevara uniforme militar, ofrecería el más guerrero aspecto y talle que puede imaginarse. Rubios el cabello y la barba, no tenía en su rostro la flemática imperturbabilidad de los Sajones, sino por el contrario, una viveza tal, que sus ojos [10] parecían negros sin serlo. Su persona bien podía pasar por un hermoso y acabado símbolo, y si fuera estatua, el escultor habría grabado en el pedestal estas palabras: _inteligencia, fuerza_. Si no en caracteres visibles, llevábalas él expresadas vagamente en la luz de su mirar, en el poderoso atractivo [15] que era don propio de su persona, y en las simpatías a que su trato cariñosamente convidaba.\"},{\"heading\":false,\"text\":\"No era de los más habladores: sólo los entendimientos de ideas inseguras y de movedizo criterio propenden a la verbosidad. El profundo sentido moral de aquel insigne [20] joven le hacía muy sobrio de palabras en las disputas que constantemente traban sobre diversos asuntos los hombres del día; pero en la conversación urbana sabía mostrar una elocuencia picante y discreta, emanada siempre del buen sentido y de la apreciación mesurada y justa de las cosas [25] del mundo. No admitía falsedades, ni mistificaciones, ni esos retruécanos del pensamiento con que se divierten algunas inteligencias impregnadas de gongorismo; y para volver por los fueros de la realidad, Pepe Rey solía emplear a veces, no siempre con comedimiento, las armas de la burla. [30] Esto casi era un defecto a los ojos de gran número de personas que le estimaban, porque nuestro joven aparecía un poco irrespetuoso en presencia de multitud de hechos comunes en el mundo y admitidos por todos. Fuerza es decirlo, aunque se amengüe su prestigio: Rey no conocía la dulce tolerancia del condescendiente siglo que ha inventado singulares 23 velos de lenguaje y de hechos para cubrir lo que a los vulgares ojos pudiera ser desagradable.\"},{\"heading\":false,\"text\":\"Así, y no de otra manera, por más que digan calumniadoras [5] lenguas, era el hombre a quien el tío Licurgo introdujo en Orbajosa en la hora y punto en que la campana de la catedral tocaba a misa mayor. Luego que uno y otro, atisbando por encima de los bardales, vieron a la niña y al Penitenciario y la veloz corrida de aquélla hacia la casa, [10] picaron sus caballerías para entrar en la calle Real, donde gran número de vagos se detenían para mirar al viajero como extraño huésped intruso de la patriarcal ciudad. Torciendo luego a la derecha, en dirección a la catedral, cuya corpulenta fábrica dominaba todo el pueblo, tomaron la calle [15] del Condestable, en la cual, por ser estrecha y empedrada, retumbaban con estridente sonsonete las herraduras, alarmando al vecindario, que por ventanas y balcones se mostraba para satisfacer su curiosidad. Abríanse con singular chasquido las celosías, y caras diversas, casi todas de hembra, [20] asomaban arriba y abajo. Cuando Pepe Rey llegó al arquitectónico umbral de la casa de Polentinos, ya se habían hecho multitud de comentarios diversos sobre su figura.\"}]},{\"title\":\"Capítulo IV\",\"blocks\":[{\"heading\":false,\"text\":\"=La llegada del primo=\"},{\"heading\":false,\"text\":\"EL señor Penitenciario, cuando Rosarito se separó bruscamente de él, miró a los bardales, y viendo las cabezas del [25] tío Licurgo y de su compañero de viaje, dijo para sí:\"},{\"heading\":false,\"text\":\"--Vamos, ya está ahí ese prodigio.\"},{\"heading\":false,\"text\":\"Quedóse un rato meditabundo, sosteniendo el manteo con ambas manos cruzadas sobre el abdomen, fija la vista en el suelo, con los anteojos de oro deslizándose suavemente hacia la punta de la nariz, saliente y húmedo el labio 24 inferior, y un poco fruncidas las blanquinegras cejas. Era un santo varón piadoso y de no común saber, de intachables costumbres clericales, algo más de sexagenario, de afable [5] trato, fino y comedido, gran repartidor de consejos y advertencias a hombres y mujeres. Desde luengos años era maestro de latinidad y retórica en el Instituto, cuya noble profesión dióle gran caudal de citas horacianas y de floridos tropos, que empleaba con gracia y oportunidad. Nada más [10] conviene añadir acerca de este personaje, sino que cuando sintió el trote largo de las cabalgaduras que corrían hacia la calle del Condestable, se arregló el manteo, enderezó el sombrero, que no estaba del todo bien puesto en la venerable cabeza, y marchando hacia la casa, murmuró--\"},{\"heading\":false,\"text\":\"[15] --Vamos a ver ese prodigio.\"},{\"heading\":false,\"text\":\"En tanto, Pepe bajaba de la jaca, y en el mismo portal le recibía en sus amantes brazos doña Perfecta, anegado en lágrimas el rostro y sin poder pronunciar sino palabras breves y balbucientes, expresión sincera de su cariño.\"},{\"heading\":false,\"text\":\"[20] --¡Pepe... pero qué grande estás!... y con barbas... Me parece que fué ayer cuando te ponía sobre mis rodillas... ya estás hecho un hombre, todo un hombre... ¡Cómo pasan los años!... ¡Jesús! Aquí tienes a mi hija Rosario.\"},{\"heading\":false,\"text\":\"[25] Diciendo esto, habían llegado a la sala baja, ordinariamente destinada a recibir, y doña Perfecta presentóle a su hija.\"},{\"heading\":false,\"text\":\"Era Rosarita una muchacha de apariencia delicada y débil, que anunciaba inclinaciones a lo que los portugueses [30] llaman _saudades_. En su rostro fino y puro se observaba algo de la pastosidad nacarada, que la mayor parte de los novelistas atribuyen a sus heroínas, y sin cuyo barniz sentimental parece que ninguna Enriqueta y ninguna Julia pueden ser interesantes. Pero lo principal en Rosario era que tenía tal expresión de dulzura y modestia, que al verla 25 no se echaban de menos las perfecciones de que carecía. No es esto decir que era fea; mas también es cierto que habría pasado por hiperbólico el que la llamara hermosa, [5] dando a esta palabra su riguroso sentido. La hermosura real de la niña de doña Perfecta consistía en una especie de trasparencia, prescindiendo del nácar, del alabastro, del marfil y demás materias usadas en la composición descriptiva de los rostros humanos; una especie de transparencia, digo, [10] por la cual todos las honduras de su alma se veían claramente, honduras no cavernosas y horribles como las del mar, sino como las de un manso y claro río. Pero allí faltaba materia para que la persona fuese completa; faltaba cauce, faltaban orillas. El vasto caudal de su espíritu se [15] desbordaba, amenazando devorar las estrechas riberas. Al ser saludada por su primo se puso como la grana, y sólo pronunció algunas palabras torpes.\"},{\"heading\":false,\"text\":\"--Estarás desmayado--dijo doña Perfecta a su sobrino.--Ahora mismo te daremos de almorzar.\"},{\"heading\":false,\"text\":\"[20] --Con permiso de usted--repuso el viajero,--voy a quitarme el polvo del camino....\"},{\"heading\":false,\"text\":\"--Muy bien pensado--dijo la señora.--Rosario, lleva a tu primo al cuarto que le hemos preparado. Despáchate pronto, sobrino. Voy a dar mis órdenes.\"},{\"heading\":false,\"text\":\"[25] Rosario llevó a su primo a una hermosa habitación situada en el piso bajo. Desde que puso el pie dentro de ella, Pepe reconoció en todos los detalles de la vivienda la mano diligente y cariñosa de una mujer. Todo estaba puesto con arte singular, y el aseo y frescura de cuanto allí había [30] convidaban a reposar en tan hermoso nido. El huésped reparó minuciosidades que le hicieron reír.\"},{\"heading\":false,\"text\":\"--Aquí tienes la campanilla--dijo Rosarito, tomando el cordón de ella, cuya borla caía sobre la cabecera del lecho.\"},{\"heading\":false,\"text\":\"--No tienes más que alargar la mano. La mesa de escribir está puesta de modo que recibas la luz por la izquierda.... 26 Mira, en esta cesta echarás los papeles rotos.... ¿Tú fumas?\"},{\"heading\":false,\"text\":\"--Tengo esa desgracia--repuso Pepe Rey.\"},{\"heading\":false,\"text\":\"[5] --Pues aquí puedes echar las puntas de cigarro--dijo ella, tocando con la punta del pie un mueble de latón dorado lleno de arena.--No hay cosa más fea que ver el suelo lleno de colillas de cigarro.... Mira el lavabo.... Para la ropa tienes un ropero y una cómoda.... Creo que la relojera [10] está mal aquí y se te debe poner junto a la cama.... Si te molesta la luz, no tienes más que correr el transparente tirando de la cuerda... ¿ves?... rich....\"},{\"heading\":false,\"text\":\"El ingeniero estaba encantado.\"},{\"heading\":false,\"text\":\"Rosarito abrió una ventana.\"},{\"heading\":false,\"text\":\"[15] --Mira--dijo--esta ventana da a la huerta. Por aquí entra el sol de tarde. Aquí tenemos colgado la jaula de un canario, que canta como un loco. Si te molesta, la quitaremos.\"},{\"heading\":false,\"text\":\"Abrió otra ventana del testero opuesto.\"},{\"heading\":false,\"text\":\"[20] --Esta otra ventana--añadió,--da a la calle. Mira, de aquí se ve la catedral, que es muy hermosa y está llena de preciosidades. Vienen muchos Ingleses a verla. No abras las dos ventanas a un tiempo, porque las corrientes de aire son muy malas.\"},{\"heading\":false,\"text\":\"[25] --Querida prima--dijo Pepe, con el alma inundada de inexplicable gozo--en todo lo que está delante de mis ojos veo una mano de ángel que no puede ser sino la tuya. ¡Qué hermoso cuarto es este! Me parece que he vivido en él toda mi vida. Está convidando a la paz.\"},{\"heading\":false,\"text\":\"[30] Rosarito no contestó nada a estas cariñosas expresiones, y sonriendo salió.\"},{\"heading\":false,\"text\":\"--No tardes--dijo desde la puerta;--el comedor está también abajo... en el centro de esta galería.\"},{\"heading\":false,\"text\":\"Entró el tío Licurgo con el equipaje. Pepe le recompensó con una largueza a que el labriego no estaba acostumbrado; 27 y éste, después de dar las gracias con humildad, llevóse la mano a la cabeza, como quien ni se pone ni se quita el sombrero, y en tono embarazoso, mascando las palabras, [5] como quien no dice ni deja de decir las cosas, se expresó de este modo:\"},{\"heading\":false,\"text\":\"--¿Cuándo será la mejor hora para hablar al Sr. D. José de un... de un asuntillo?\"},{\"heading\":false,\"text\":\"--¿De un asuntillo? Ahora mismo--repuso Pepe, [10] abriendo un baúl.\"},{\"heading\":false,\"text\":\"--No es oportunidad--dijo el labriego.--Descanse el Sr. D. José, que tiempo tenemos. Más días hay que longanizas, como dijo el otro; y un día viene tras otro día.... Que usted descanse, Sr. D. José.... Cuando quiera dar [15] un paseo... la jaca no es mala.... Con que buenos días, Sr. D. José. Que viva usted mil años.... ¡Ah! se me olvidaba--añadió, volviendo a entrar después de algunos segundos de ausencia.--Si quiere usted algo para el señor juez municipal.... Ahora voy allá a hablarle de [20] nuestro asuntillo....\"},{\"heading\":false,\"text\":\"--Déle usted expresiones--dijo festivamente, no encontrando mejor fórmula para sacudirse de encima al legislador espartano.\"},{\"heading\":false,\"text\":\"--Pues quede con Dios el Sr. D. José.\"},{\"heading\":false,\"text\":\"[25] --Abur.\"},{\"heading\":false,\"text\":\"El ingeniero no había sacado su ropa, cuando aparecieron por tercera vez en la puerta los sagaces ojuelos y la marrullera fisonomía del tío Licurgo.\"},{\"heading\":false,\"text\":\"--Perdone el Sr. D. José--dijo mostrando en afectada [30] risa sus blanquísimos dientes.--Pero... quería decirle que si usted desea que esto se arregle por amigables componedores.... Aunque, como dijo el otro, pon lo tuyo en consejo y unos dirán que es blanco y otros que es negro....\"},{\"heading\":false,\"text\":\"--Hombre, ¿quiere usted irse de aquí?\"},{\"heading\":false,\"text\":\"--Dígolo porque a mí me carga la justicia. No quiero 28 nada con justicia. Del lobo un pelo y ese de la frente. Con que con Dios, Sr. don José. Dios le conserve sus días para favorecer a los pobres....\"},{\"heading\":false,\"text\":\"[5] --Adiós, hombre, adiós.\"},{\"heading\":false,\"text\":\"Pepe echó la llave a la puerta y dijo para sí:\"},{\"heading\":false,\"text\":\"--La gente de este pueblo parece ser muy pleitista.\"}]},{\"title\":\"Capítulo V\",\"blocks\":[{\"heading\":false,\"text\":\"_¿Habrá desavenencia?_\"},{\"heading\":false,\"text\":\"Poco después Pepe se presentaba en el comedor.\"},{\"heading\":false,\"text\":\"--Si almuerzas fuerte--le dijo doña Perfecta con [10] cariñoso acento,--se te va a quitar la gana de comer. Aquí comemos a la una. Las modas del campo no te gustarán.\"},{\"heading\":false,\"text\":\"--Me encantan, señora tía.\"},{\"heading\":false,\"text\":\"--Pues di lo que prefieres: ¿almorzar fuerte ahora o tomar una cosita ligera para que resistas hasta la hora de [15] comer?\"},{\"heading\":false,\"text\":\"--Escojo la cosa ligera para tener el gusto de comer con ustedes; y si en Villahorrenda hubiera encontrado algún alimento, nada tomaría a esta hora.\"},{\"heading\":false,\"text\":\"--Por supuesto, no necesito decirte que nos trates con [20] toda franqueza. Aquí puedes mandar como si estuvieras en tu casa.\"},{\"heading\":false,\"text\":\"--Gracias, tía.\"},{\"heading\":false,\"text\":\"--¡Pero cómo te pareces a tu padre!--añadió la señora, contemplando con verdadero arrobamiento al joven mientras [25] éste comía.\"},{\"heading\":false,\"text\":\"--Me parece que estoy mirando a mi querido hermano Juan. Se sentaba como te sientas tú y comía lo mismo que tú. En el modo de mirar sobre todo sois como dos gotas de agua.\"},{\"heading\":false,\"text\":\"Pepe la emprendió con el frugal desayuno. Las expresiones, 29 así como la actitud y las miradas de su tía y prima, le infundían tal confianza, que se creía ya en su propia casa.\"},{\"heading\":false,\"text\":\"--¿Sabes lo que me decía Rosario esta mañana?--indicó [5] doña Perfecta, fija la vista en su sobrino,--Pues me decía que tú, como hombre hecho a las pompas y etiquetas de la corte y a las modas del extranjero, no podrás soportar esta sencillez un poco rústica con que vivimos y esta falta de buen tono, pues aquí todo es a la pata la llana.\"},{\"heading\":false,\"text\":\"[10] --¡Qué error!--repuso Pepe, mirando a su prima.--Nadie aborrece más que yo las falsedades y comedias de lo que llaman alta sociedad. Crean ustedes que hace tiempo deseo darme, como decía no sé quién, un baño de cuerpo entero en la Naturaleza; vivir lejos del bullicio, en la soledad [15] y sosiego del campo. Anhelo la tranquilidad de una vida sin luchas, sin afanes, ni envidioso ni envidiado, como dijo el poeta. Durante mucho tiempo, mis estudios primero y mis trabajos después, me han impedido el descanso que necesito y que reclaman mi espíritu y mi cuerpo; pero [20] desde que entré en esta casa, querida tía, querida prima, me he sentido rodeado de la atmósfera de paz que deseo. No hay que hablarme, pues, de sociedades altas ni bajas, ni de mundos grandes ni chicos, porque de buen grado los cambio todos por este rincón.\"},{\"heading\":false,\"text\":\"[25] Esto decía, cuando los cristales de la puerta que comunicaba el comedor con la huerta se obscurecieron por la superposición de una larga opacidad negra. Los vidrios de unos espejuelos despidieron, heridos por la luz de sol, fugitivo rayo; rechinó el picaporte, abrióse la puerta, y el [30] señor Penitenciario penetró con gravedad en la estancia. Saludó y se inclinó, quitándose la canaleja hasta tocar con el ala de ella al suelo.\"},{\"heading\":false,\"text\":\"--Es el señor Penitenciario de esta Santa Catedral--dijo doña Perfecta,--persona a quien estimamos mucho y de quien espero serás amigo. Siéntese usted, Sr. D. 30 Inocencio.\"},{\"heading\":false,\"text\":\"Pepe estrechó la mano del venerable canónigo, y ambos se sentaron.\"},{\"heading\":false,\"text\":\"[5] --Pepe, si acostumbras fumar después de comer, no dejes de hacerlo--manifestó benévolamente doña Perfecta,--ni el señor Penitenciario tampoco.\"},{\"heading\":false,\"text\":\"A la sazón el buen D. Inocencio sacaba de debajo de la sotana una gran petaca de cuero, marcada con irrecusables [10] señales de antiquísimo uso, y la abrió, desenvainando de ella dos largos pitillos, uno de los cuales ofreció a nuestro amigo. De un cartoncejo que irónicamente llaman los españoles _wagón_, sacó Rosario un fósforo, y bien pronto ingeniero y canónigo echaban su humo el uno sobre el otro.\"},{\"heading\":false,\"text\":\"[15] --¿Y qué le parece al Sr. D. José nuestra querida ciudad de Orbajosa?--preguntó el canónigo, cerrando fuertemente el ojo izquierdo, según su costumbre mientras fumaba.\"},{\"heading\":false,\"text\":\"--Todavía no he podido formar idea de este pueblo--dijo Pepe.--Por lo poco que he visto, me parece que no le [20] vendrían mal a Orbajosa media docena de grandes capitales dispuestos a emplearse aquí, un par de cabezas inteligentes que dirigieran la renovación de este país y algunos miles de manos activas. Desde la entrada del pueblo hasta la puerta de esta casa he visto más de cien mendigos. La [25] mayor parte son hombres sanos y aun robustos. Es un ejército lastimoso, cuya vista oprime el corazón.\"},{\"heading\":false,\"text\":\"--- Para eso está la caridad--afirmó don Inocencio.--Por lo demás, Orbajosa no es un pueblo miserable. Ya sabe usted que aquí se producen los primeros ajos de toda España. [30] Pasan de veinte las familias ricas que viven entre nosotros.\"},{\"heading\":false,\"text\":\"--Verdad es--indicó doña Perfecta--que los últimos años han sido detestables a causa de la seca; pero aun así las paneras no están vacías, y se han llevado últimamente al mercado muchos miles de ristras de ajos.\"},{\"heading\":false,\"text\":\"--En tantos años que llevo de residencia en Orbajosa--dijo 31 el clérigo, frunciendo el ceño--he visto llegar aquí innumerables personajes de la Corte, traídos unos por la gresca electoral, otros por visitar algún abandonado terruño [5] o ver las antigüedades de la catedral, y todos entran hablándonos de arados ingleses, de trilladoras mecánicas, de saltos de aguas, de bancos y qué sé yo cuántas majaderías. El estribillo es que esto es muy malo y que podía ser mejor. Váyanse con mil demonios, que aquí estamos muy bien sin [10] que los señores de la Corte nos visiten, mucho mejor sin oír ese continuo clamoreo de nuestra pobreza y de las grandezas y maravillas de otras partes. Más sabe el loco en su casa que el cuerdo en la ajena, ¿no es verdad, Sr. D. José? Por supuesto, no se crea ni remotamente que lo digo por usted. [15] De ninguna manera. Pues no faltaba más. Ya sé que tenemos delante a uno de los jóvenes más eminentes de la España moderna, a un hombre que sería capaz de transformar en riquísimas comarcas nuestras áridas estepas.... Ni me incomodo porque usted me cante la vieja canción de [20] los arados ingleses y la arboricultura y la selvicultura.... Nada de eso; a hombres de tanto, de tantísimo talento, se les puede dispensar el desprecio que muestran hacia nuestra humildad. Nada, amigo mío, nada, Sr. D. José, está usted autorizado para todo, incluso para decirnos que somos poco [25] menos que cafres.\"},{\"heading\":false,\"text\":\"Esta filípica, terminada con marcado tono de ironía y harto impertinente toda ella, no agradó al joven; pero se abstuvo de manifestar el más ligero disgusto y siguió la conversación, procurando en lo posible huir de los puntos [30] en que el susceptible patriotismo del señor canónigo hallase fácil motivo de discordia. Éste se levantó en el momento en que la señora hablaba con su sobrino de asuntos de familia y dió algunos pasos por la estancia.\"},{\"heading\":false,\"text\":\"Era ésta vasta y clara, cubierta de antiguo papel, cuyas flores y ramos, aunque descoloridos, conservaban su 32 primitivo dibujo, gracias al aseo que reinaba en todas y cada una de las partes de la vivienda. El reloj, de cuya caja colgaban al descubierto, al parecer, las inmóviles pesas y el voluble [5] péndulo, diciendo perpetuamente que _no_, ocupaba con su abigarrado horario el lugar preeminente entre los sólidos muebles del comedor, completando el ornato de las paredes una serie de láminas francesas que representaban las hazañas del conquistador de Méjico, con prolijas explicaciones al [10] pie, en las cuales se hablaba de un _Ferdinand Cortez_ y de una _Donna Marine_ tan inverosímiles como las figuras dibujadas por el ignorante artista. Entre las dos puertas vidrieras que comunicaban con la huerta había un aparato de latón, que no es preciso describir desde que se diga que [15] servía de sustentáculo a un loro, el cual se mantenía allí con la seriedad y circunspección propias de estos animalejos, observándolo todo. La fisonomía irónica y dura de los loros, su casaca verde, su gorrete encarnado, sus botas amarillas y por último las roncas palabras burlescas que [20] suelen pronunciar, les dan un aspecto extraño y repulsivo entre serio y ridículo. Tienen no sé qué rígido empaque de diplomáticos. A veces parecen bufones, y siempre se asemejan a ciertos finchados hombres, que por querer parecer muy superiores, tiran a la caricatura.\"},{\"heading\":false,\"text\":\"[25] Era el Penitenciario muy amigo del loro. Cuando dejó a la señora y a Rosario en coloquio con el viajero, llegóse a él, y dejándose morder con la mayor complacencia el dedo índice, le dijo:\"},{\"heading\":false,\"text\":\"--Tunante, bribón, ¿por qué no hablas? Poco valdrías, [30] si no fueras charlatán. De charlatanes está lleno el mundo de los hombres y el de los pájaros.\"},{\"heading\":false,\"text\":\"Luego cogió con su propia venerable mano algunos garbanzos del cercano cazuelillo y se los dió a comer. El animal empezó a llamar a la criada pidiéndole chocolate, y sus palabras distrajeron a las dos damas y al caballero de 33 una conversación que no debía de ser muy importante.\"}]},{\"title\":\"Capítulo VI\",\"blocks\":[{\"heading\":false,\"text\":\"=Donde se ve que puede surgir la desavenencia cuando menos se espera=\"},{\"heading\":false,\"text\":\"De súbito se presentó el Sr. D. Cayetano Polentinos, hermano político de doña Perfecta, el cual entró con los [5] brazos abiertos, gritando:\"},{\"heading\":false,\"text\":\"--Venga acá, Sr. D. José de mi alma.\"},{\"heading\":false,\"text\":\"Y se abrazaron cordialmente. D. Cayetano y Pepe se conocían, porque el distinguido erudito y bibliófilo solía hacer excursiones a Madrid cuando se anunciaba almoneda [10] de libros, procedente de la testamentaría de algún _buquinista_. Era D. Cayetano alto y flaco, de edad mediana, si bien el continuo estudio o los padecimientos le habían desmejorado mucho; se expresaba con una corrección alambicada que le sentaba a las mil maravillas, y era cariñoso y amable, a [15] veces con exageración. Respecto de su vasto saber, ¿qué puede decirse sino que era un verdadero prodigio? En Madrid su nombre no se pronunciaba sin respeto, y si D. Cayetano residiera en la capital, no se escapara sin pertenecer, a pesar de su modestia, a todas las academias [20] existentes y por existir. Pero él gustaba del tranquilo [aislamiento,] y el lugar que en el alma de otros tiene la vanidad, teníalo en el suyo la pasión pura de los libros, el amor al estudio solitario y recogido, sin otra ulterior mira y aliciente que los propios libros y el estudio mismo.\"},{\"heading\":false,\"text\":\"[25] Había formada en Orbajosa una de las más ricas bibliotecas que en toda la redondez de España se encuentran, y dentro de ella pasaba largas horas del día y de la noche, compilando, clasificando, tomando apuntes y entresacando diversas suertes de noticias preciosísimas, o realizando 34 quizás algún inaudito y jamás soñado trabajo, digno de tan gran cabeza. Sus costumbres eran patriarcales; comía poco, bebía menos, y sus únicas calaveradas consistían en [5] alguna merienda en los Alamillos, en días muy sonados, y paseos diarios a un lugar llamado Mundogrande, donde a menudo eran desenterradas del fango de veinte siglos medallas romanas y pedazos de arquitrabe, extraños plintos de desconocida arquitectura y tal cual ánfora o cubicularia [10] de inestimable precio.\"},{\"heading\":false,\"text\":\"Vivían D. Cayetano y doña Perfecta en una armonía tal, que la paz del Paraíso no se le igualara. Jamás riñeron. Es verdad que él no se mezclaba para nada en los asuntos de la casa, ni ella en los de la biblioteca más que para [15] hacerla barrer y limpiar todos los sábados, respetando con religiosa admiración los libros y papeles que sobre la mesa y en diversos parajes estaban de servicio.\"},{\"heading\":false,\"text\":\"Después de las preguntas y respuestas propias del caso, D. Cayetano dijo:\"},{\"heading\":false,\"text\":\"[20] --Ya he visto la caja. Siento mucho que no me trajeras la edición de 1527. Tendré que hacer yo mismo un viaje a Madrid.... ¿Vas a estar aquí mucho tiempo? Mientras más, mejor, querido Pepe. ¡Cuánto me alegro de tenerte aquí! Entre los dos vamos a arreglar parte de mi biblioteca [25] y a hacer un índice de escritores de la Gineta. No siempre se encuentra a mano un hombre de tanto talento como tú.... Verás mi biblioteca.... Podrás darte en ella unos atracones de lectura.... Todo lo que quieras.... Verás maravillas, verdaderas maravillas, tesoros inapreciables, [30] rarezas que sólo yo poseo, sólo yo.... Pero, en fin, me parece que ya es hora de comer, ¿no es verdad, José? ¿No es verdad, Perfecta? ¿No es verdad, Rosarito? ¿No es verdad, Sr. D. Inocencio?... hoy es usted dos veces Penitenciario: dígolo porque nos acompañará usted a hacer penitencia. El canónigo se inclinó, y sonriendo mostraba 35 simpáticamente su aquiescencia. La comida fué cordial, y en todos los manjares se advertía la abundancia desproporcionada de los banquetes de pueblo, realizada a costa de la variedad. [5] Había para atracarse doble número de personas que las allí reunidas. La conversación recayó en asuntos diversos.\"},{\"heading\":false,\"text\":\"--Es preciso que visite usted cuanto antes nuestra catedral--dijo el canónigo.--¡Como ésta hay pocas, Sr. D. José!... Verdad es que usted, que tantas maravillas [10] ha visto en el extranjero, no encontrará nada notable en nuestra vieja iglesia.... Nosotros los pobres patanes de Orbajosa la encontramos divina. El maestro López de Berganza, racionero de ella, la llamaba en el siglo XVI _pulchra augustina_.... Sin embargo, para hombres de tanto [15] saber como usted, quizá no tenga ningún mérito, y cualquier mercado de hierro será más bello.\"},{\"heading\":false,\"text\":\"Cada vez disgustaba más a Pepe Rey el lenguaje irónico del sagaz canónigo; pero resuelto a contener y disimular su enfado, no contestó sino con palabras vagas. Doña Perfecta [20] tomó en seguida la palabra, y jovialmente se expresó así:\"},{\"heading\":false,\"text\":\"--Cuidado, Pepito; te advierto que si hablas mal de nuestra santa iglesia, perderemos las amistades. Tú sabes mucho y eres un hombre eminente que de todo entiendes; [25] pero si has de descubrir que esa gran fábrica no es la octava maravilla, guárdate en buen hora tu sabiduría y no nos saques de bobos....\"},{\"heading\":false,\"text\":\"--Lejos de creer que este edificio no es bello--repuso Pepe--lo poco que de su exterior he visto me ha parecido [30] de imponente hermosura. De modo, señora tía, que no hay para qué asustarse; ni yo soy sabio ni mucho menos.\"},{\"heading\":false,\"text\":\"--Poco a poco--dijo el canónigo, extendiendo la mano y dando paz a la boca por breve rato para que, hablando, descansase del mascar.--Alto allá: no venga usted aquí haciéndose el modesto, Sr. D. José, que hartos estamos de 36 saber lo muchísimo que usted vale, la gran fama de que goza y el papel importantísimo que desempeñará donde quiera que se presente. No se ven hombres así todos los [5] días. Pero ya que de este modo ensalzo los méritos de usted....\"},{\"heading\":false,\"text\":\"Detúvose para seguir comiendo, y luego que la sin hueso quedó libre, continuó así:\"},{\"heading\":false,\"text\":\"--Ya que de este modo ensalzo los méritos de usted, [10] permítaseme expresar otra opinión con la franqueza que es propia de mi carácter. Sí, Sr. D. José: sí, Sr. D. Cayetano; sí, señora y niña mías; la ciencia, tal como la estudian y la propagan los modernos, es la muerte del sentimiento y de las dulces ilusiones. Con ella la vida del espíritu se amengua; [15] todo se reduce a reglas fijas, y los mismos encantos sublimes de la Naturaleza desaparecen. Con la ciencia destrúyese lo maravilloso en las artes, así como la fe en el alma. La ciencia dice que todo es mentira y todo lo quiere poner en guarismos y rayas, no sólo _maria ac terras_, donde [20] estamos nosotros, sino también _caelumque profundum_, donde está Dios... Los admirables sueños del alma, su arrobamiento místico; la inspiración misma de los poetas, mentira. El corazón es una esponja, el cerebro una gusanera.\"},{\"heading\":false,\"text\":\"Todos rompieron a reír, mientras él daba paso a un trago [25] de vino.\"},{\"heading\":false,\"text\":\"--Vamos, ¿me negará el Sr. D. José--añadió el sacerdote--que la ciencia, tal como se enseña y se propaga hoy, va derecho a hacer del mundo y del género humano una gran máquina?\"},{\"heading\":false,\"text\":\"[30] --Eso según y conforme--dijo D. Cayetano.--Todas las cosas tienen su pro y su contra.\"},{\"heading\":false,\"text\":\"--Tome usted más ensalada, señor Penitenciario--dijo doña Perfecta.--Está cargadita de mostaza, como a usted le gusta.\"},{\"heading\":false,\"text\":\"Pepe Rey no gustaba de entablar vanas disputas, ni era 37 pedante, ni alardeaba de erudito, mucho menos ante mujeres y en reuniones de confianza; pero la importuna verbosidad agresiva del canónigo necesitaba, según él, un correctivo. [5] Para dárselo le pareció mal sistema exponer ideas que, concordando con las del canónigo, halagasen a éste, y decidió manifestar las opiniones que más contrariaran y más acerbamente mortificasen al mordaz Penitenciario.\"},{\"heading\":false,\"text\":\"--Quieres divertirte conmigo--dijo para sí.--Verás [10] qué mal rato te voy a dar.\"},{\"heading\":false,\"text\":\"Y luego añadió en voz alta:\"},{\"heading\":false,\"text\":\"--Cierto es todo lo que el señor Penitenciario ha dicho en tono de broma. Pero no es culpa nuestra que la ciencia esté derribando a martillazos un día y otro tanto ídolo vano, [15] la superstición, el sofisma, las mil mentiras de lo pasado, bellas las unas, ridículas las otras, pues de todo hay en la viña del Señor. El mundo de las ilusiones, que es como si dijéramos un segundo mundo, se viene abajo con estrépito. El misticismo en religión, la rutina en la ciencia, el [20] amaneramiento en las artes, caen como cayeron los dioses paganos, entre burlas. Adiós, sueños torpes, el género humano despierta y sus ojos ven la claridad. El sentimentalismo vano, el misticismo, la fiebre, la alucinación, el delirio desaparecen, y el que antes era enfermo hoy está sano y se goza con [25] placer indecible en la justa apreciación de las cosas. La fantasía, la terrible loca, que era el ama de la casa, pasa a ser criada.... Dirija usted la vista a todos lados, señor Penitenciario, y verá el admirable conjunto de realidad que ha sustituído a la fábula. El cielo no es una bóveda, las [30] estrellas no son farolillos, la luna no es una cazadora traviesa, sino un pedrusco opaco; el sol no es un cochero emperegilado y vagabundo, sino un incendio fijo. Las sirtes no son ninfas, sino dos escollos; las sirenas son focas, y en el orden de las personas Mercurio es Manzanedo; Marte es un viejo barbilampiño, el conde de Moltke; 38 Néstor puede ser un señor de gabán que se llama monsieur Thiers; Orfeo es Verdi; Vulcano es Krupp; Apolo es cualquier poeta. ¿Quiere usted más? Pues Júpiter, un [5] Dios digno de ir a presidio si viviera aún, no descarga el rayo, sino que el rayo cae cuando a la electricidad le da la gana. No hay Parnaso, no hay Olimpo; no hay laguna Estigia, ni otros Campos Elíseos que los de París. No hay ya más bajada al infierno que las de la geología, y este [10] viajero, siempre que vuelve, dice que no hay condenados en el centro de la tierra. No hay más subidas al cielo que las de la astronomía, y ésta a su regreso asegura no haber visto los seis o siete pisos de que hablan el Dante y los místicos y soñadores de la Edad Media. No encuentra sino astros [15] y distancias, líneas, enormidades de espacio y nada más. Ya no hay falsos cómputos de la edad del mundo, porque la paleontología y la prehistoria han contado los dientes de esta calavera en que vivimos y averiguado su verdadera edad. La fábula, llámese paganismo o idealismo cristiano, [20] ya no existe, y la imaginación está de cuerpo presente. Todos los milagros posibles se reducen a los que yo hago cuando se me antoja en mi gabinete con una pila de Bunsen, un hilo inductor y una aguja imantada. Ya no hay más multiplicaciones de panes y peces que las que hace la [25] industria con sus moldes y máquinas y las de la imprenta, que imita a la Naturaleza sacando de un solo tipo millones de ejemplares. En suma, señor canónigo de mi alma, se han corrido las órdenes para dejar cesantes a todos los absurdos, falsedades, ilusiones, ensueños, sensiblerías y [30] preocupaciones que ofuscan el entendimiento del hombre. Celebremos el suceso.\"},{\"heading\":false,\"text\":\"Cuando concluyó de hablar, en los labios del canónigo retozaba una sonrisilla, y sus ojos habían tomado animación extraordinaria. D. Cayetano se ocupaba en dar diversas formas, ora romboides, ora prismáticas, a una bolita de pan. 39 Pero doña Perfecta estaba pálida y fijaba sus ojos en el canónigo con insistencia observadora. Rosarito contemplaba llena de estupor a su primo. Éste se inclinó hacia [5] ella, y al oído le dijo disimuladamente en voz muy baja:\"},{\"heading\":false,\"text\":\"--No me hagas caso, primita. Digo estos disparates para sulfurar al señor canónigo.\"}]},{\"title\":\"Capítulo VII\",\"blocks\":[{\"heading\":false,\"text\":\"=La desavenencia crece=\"},{\"heading\":false,\"text\":\"--Puede que creas--indicó doña Perfecta con ligero acento de vanidad,--que el señor D. Inocencio se va a [10] quedar callado sin contestarte a todos y cada uno de esos puntos.\"},{\"heading\":false,\"text\":\"--¡Oh, no!--exclamó el canónigo, arqueando las cejas.\"},{\"heading\":false,\"text\":\"--No mediré yo mis escasas fuerzas con adalid tan valiente y al mismo tiempo tan bien armado. El Sr. D. José lo [15] sabe todo, es decir, tiene a su disposición todo el arsenal de las ciencias exactas. Bien sé que la doctrina que sustenta es falsa; pero yo no tengo talento ni elocuencia para combatirla. Emplearía yo las armas del sentimiento; emplearía argumentos teológicos, sacados de la revelación, de [20] la fe, de la palabra divina; pero ¡ay! el Sr. D. José, que es un sabio eminente, se reiría de la teología, de la fe, de la revelación, de los santos profetas, del Evangelio. Un pobre clérigo ignorante, un desdichado que no sabe matemáticas, ni filosofía alemana en que hay aquello de _yo_ y _no [25] yo,_ un pobre dómine que no sabe más que la ciencia de Dios y algo de poetas latinos, no puede entrar en combate con estos bravos corifeos.\"},{\"heading\":false,\"text\":\"Pepe Rey prorrumpió en francas risas.\"},{\"heading\":false,\"text\":\"--Veo que el Sr. D. Inocencio--dijo,--ha tomado [30] por lo serio estas majaderías que he dicho. Vaya, señor canónigo, vuélvanse cañas las lanzas y todo se acabó. 40 Seguro estoy de que mis verdaderas ideas y las de usted no están en desacuerdo. Usted es un varón piadoso e [5] instruído. Aquí el ignorante soy yo. Si he querido bromear, dispénsenme todos: yo soy así.\"},{\"heading\":false,\"text\":\"--Gracias--repuso el presbítero visiblemente contrariado.--¿Ahora salimos con ésa? Bien sé yo, bien sabemos todos que las ideas que usted ha sustentado son las suyas. No podía ser de otra manera. Usted es el hombre [10] del siglo. No puede negarse que su entendimiento es prodigioso, verdaderamente prodigioso. Mientras usted hablaba, yo, lo confieso ingénuamente, al mismo tiempo que en mi interior deploraba error tan grande, no podía menos de admirar lo sublime de la expresión, la prodigiosa facundia, [15] el método sorprendente de su raciocinio, la fuerza de los argumentos.... ¡Qué cabeza, señora doña Perfecta, qué cabeza la de este joven sobrino de usted! Cuando estuve en Madrid y me llevaron al Ateneo, confieso que me quedé absorto al ver el asombroso ingenio que Dios ha dado a los [20] ateos y protestantes.\"},{\"heading\":false,\"text\":\"--Sr. D. Inocencio--dijo doña Perfecta, mirando alternativamente a su sobrino y a su amigo,--creo que usted al juzgar a este chico, traspasa los límites de la benevolencia.... No te enfades, Pepe, ni hagas caso de lo que digo, [25] porque yo ni soy sabia ni filósofa, ni teóloga; pero me parece que el señor D. Inocencio acaba de dar una prueba de su gran modestia y caridad cristiana, negándose a apabullarte, como podía hacerlo, si hubiese querido.\"},{\"heading\":false,\"text\":\"--¡Señora, por Dios!--dijo el eclesiástico.\"},{\"heading\":false,\"text\":\"[30] --Él es así--añadió la señora.--Siempre haciéndose la mosquita muerta.... Y sabe más que los siete doctores. ¡Ay, Sr. D. Inocencio, qué bien le sienta a usted el nombre que tiene! Pero no se nos venga acá con humildades importunas. Si mi sobrino no tiene pretensiones.... Si él sabe lo que le han enseñado y nada más.... Si ha 41 aprendido el error, ¿qué más puede desear sino que usted le ilustre y le saque del infierno de sus falsas doctrinas?\"},{\"heading\":false,\"text\":\"--Justamente, no deseo otra cosa, sino que el señor [5] Penitenciario me saque....--murmuró Pepe, comprendiendo que, sin quererlo, se había metido en un laberinto.\"},{\"heading\":false,\"text\":\"--Yo soy un pobre clérigo que no sabe más que la ciencia antigua--repuso D. Inocencio.--Reconozco el inmenso valor científico mundano del Sr. D. José, y ante tan brillante [10] oráculo, callo y me postro.\"},{\"heading\":false,\"text\":\"Diciendo esto, el canónigo cruzaba ambas manos sobre el pecho, inclinando la cabeza. Pepe Rey estaba un si es no es turbado a causa del giro que diera su tía a una vana disputa festiva en la que tomó parte tan sólo por acalorar [15] un poco la conversación. Creyó lo más prudente poner punto en tan peligroso tratado, y con este fin dirigió una pregunta al Sr. D. Cayetano, cuando éste, despertando del vaporoso letargo que tras los postres le sobrevino, ofrecía a los comensales los indispensables palillos clavados en un [20] pavo de porcelana que hacía la rueda.\"},{\"heading\":false,\"text\":\"--Ayer he descubierto una mano empuñando el asa de un ánfora, en la cual hay varios signos hieráticos. Te la enseñaré--dijo D. Cayetano, gozoso de plantear un tema de su predilección.\"},{\"heading\":false,\"text\":\"[25] --Supongo que el Sr. de Rey será también muy experto en cosas de arqueología--dijo el canónigo que, siempre implacable, corría tras su víctima, siguiéndola hasta su más escondido refugio.\"},{\"heading\":false,\"text\":\"--Por supuesto--dijo doña Perfecta.--¿De qué no [30] entenderán estos despabilados niños del día? Todas las ciencias las llevan en las puntas de los dedos. Las universidades y las academias les instruyen de todo en un periquete, dándoles patente de sabiduría.\"},{\"heading\":false,\"text\":\"--¡Oh! eso es injusto--repuso el canónigo, observando la penosa impresión que manifestaba el semblante del 42 ingeniero.\"},{\"heading\":false,\"text\":\"--Mi tía tiene razón--afirmó Pepe.--Hoy aprendemos un poco de todo, y salimos de las escuelas con rudimentos [5] de diferentes estudios.\"},{\"heading\":false,\"text\":\"--Decía--añadió el canónigo,--que será usted un gran arqueólogo.\"},{\"heading\":false,\"text\":\"--No sé una palabra de esa ciencia--repuso el joven.--Las ruinas son ruinas, y nunca me ha gustado empolvarme [10] en ellas.\"},{\"heading\":false,\"text\":\"Don Cayetano hizo una mueca muy expresiva.\"},{\"heading\":false,\"text\":\"--No es esto condenar la arqueología--dijo vivamente el sobrino de doña Perfecta, advirtiendo con dolor que no pronunciaba una palabra sin herir a alguien.--Bien sé que [15] del polvo sale la historia. Esos estudios son preciosos y utilísimos.\"},{\"heading\":false,\"text\":\"--Usted--dijo el Penitenciario, metiéndose el palillo en la última muela,--se inclinará más a los estudios de controversia. Ahora se me ocurre una excelente idea. Sr. D. [20] José, usted debiera ser abogado.\"},{\"heading\":false,\"text\":\"--La abogacía es una profesión que aborrezco--replicó Pepe Rey.--Conozco abogados muy respetables, entre ellos a mi padre, que es el mejor de los hombres. A pesar de tan buen ejemplo, en mi vida me hubiera sometido a ejercer [25] una profesión que consiste en defender lo mismo el pro que el contra de las cuestiones. No conozco error, ni preocupación, ni ceguera más grande que el empeño de las familias en inclinar a la mejor parte de la juventud a la abogacía. La primera y más terrible plaga de España es la turbamulta [30] de jóvenes abogados, para cuya existencia es necesaria una fabulosa cantidad de pleitos. Las cuestiones se multiplican en proporción de la demanda. Aun así, muchísimos se quedan sin trabajo, y como un señor jurisconsulto no puede tomar el arado ni sentarse al telar, de aquí proviene ese brillante escuadrón de holgazanes, llenos de pretensiones, 43 que fomentan la empleomanía, perturban la política, agitan la opinión y engendran las revoluciones. De alguna parte han de comer. Mayor desgracia sería que hubiera pleitos [5] para todos.\"},{\"heading\":false,\"text\":\"--Pepe, por Dios, mira lo que hablas--dijo doña Perfecta, con marcado tono de severidad.--Pero dispénsele usted, Sr. D. Inocencio... porque él ignora que usted tiene un sobrinito, el cual, aunque recién salido de la Universidad, [10] es un portento en la abogacía.\"},{\"heading\":false,\"text\":\"--Yo hablo en términos generales--manifestó Pepe con firmeza.--Siendo, como soy, hijo de un abogado ilustre, no puedo desconocer que algunas personas ejercen esta noble profesión con verdadera gloria.\"},{\"heading\":false,\"text\":\"[15] --No... si mi sobrino es un chiquillo todavía--dijo el canónigo, afectando humildad.--Muy lejos de mi ánimo afirmar que es un prodigio de saber, como el Sr. de Rey. Con el tiempo ¿quién sabe?... Su talento no es brillante ni seductor. Por supuesto, las ideas de Jacintito son [20] sólidas, su criterio sano; lo que sabe lo sabe a macha martillo. No conoce sofisterías ni palabras huecas....\"},{\"heading\":false,\"text\":\"Pepe Rey aparecía cada vez más inquieto. La idea de que, sin quererlo, estaba en contradicción con las ideas de los amigos de su tía, le mortificaba, y resolvió callar por [25] temor a que él y D. Inocencio concluyeran tirándose los platos a la cabeza. Felizmente, el esquilón de la catedral, llamando a los canónigos a la importante tarea del coro, le sacó de situación tan penosa. Levantóse el venerable varón y se despidió de todos, mostrándose con Pepe tan [30] lisonjero, tan amable, cual si la amistad más íntima desde largo tiempo les uniera. El canónigo, después de ofrecerse a él para servirle en todo, le prometió presentarle a su sobrino, a fin de que le acompañase a ver la población, y le dijo las expresiones más cariñosas, dignándose agraciarle al salir con una palmadita en el hombro. Pepe Rey, aceptando 44 con gozo aquellas fórmulas de concordia, vió, sin embargo, el cielo abierto cuando el sacerdote salió del comedor y de la casa.\"}]},{\"title\":\"Capítulo VIII\",\"blocks\":[{\"heading\":false,\"text\":\"=A toda prisa=\"},{\"heading\":false,\"text\":\"[5] Poco después la escena había cambiado. Don Cayetano, encontrando descanso a sus sublimes tareas en un dulce sueño que de él se amparó, yacía blandamente en un sillón del comedor. Doña Perfecta andaba en la casa tras sus quehaceres. Rosarito, sentándose junto a una de las [10] vidrieras que a la huerta se abrían, miró a su primo, diciéndole con la muda oratoria de los ojos:\"},{\"heading\":false,\"text\":\"--Primo, siéntate aquí junto a mí, y dime todo eso que tienes que decirme.\"},{\"heading\":false,\"text\":\"Éste, aunque matemático, lo comprendió.\"},{\"heading\":false,\"text\":\"[15] --Querida prima--dijo Pepe,--¡cuánto te habrás aburrido hoy con nuestras disputas! Bien sabe Dios que por mi gusto no habría pedanteado como viste; pero el señor canónigo tiene la culpa.... ¿Sabes que me parece singular ese señor sacerdote?...\"},{\"heading\":false,\"text\":\"[20] --¡Es una persona excelente!--repuso Rosarito, demostrando el gozo que sentía por verse en disposición de dar a su primo todos los datos y noticias que necesitase.\"},{\"heading\":false,\"text\":\"--¡Oh! sí, una excelente persona. ¡Bien se conoce!\"},{\"heading\":false,\"text\":\"--Cuando le sigas tratando, conocerás....\"},{\"heading\":false,\"text\":\"[25] --Que no tiene precio. En fin, basta que sea amigo de tu mamá y tuyo para que también lo sea mío--afirmó el joven.--¿Y viene mucho acá?\"},{\"heading\":false,\"text\":\"--Toditos los días. Nos acompaña mucho--- repuso Rosarito con ingenuidad.--¡Qué bueno y qué amable es! [30] ¡Y cómo me quiere!\"},{\"heading\":false,\"text\":\"--Vamos, ya me va gustando ese señor. 45\"},{\"heading\":false,\"text\":\"--Viene también por las noches a jugar al tresillo--añadió la joven,--porque a prima noche se reunen aquí algunas personas, el juez de primera instancia, el promotor fiscal, [5] el deán, el secretario del obispo, el alcalde, el recaudador de contribuciones, el sobrino de D. Inocencio....\"},{\"heading\":false,\"text\":\"--¡Ah! Jacintito, el abogado.\"},{\"heading\":false,\"text\":\"--Ése. Es un pobre muchacho, más bueno que el pan. Su tío le adora. Desde que vino de la Universidad, con su [10] borla de doctor... porque es doctor de un par de facultades, y sacó nota de sobresaliente... ¿qué crees tú? ¡vaya!... pues desde que vino, su tío le trae aquí con mucha frecuencia. Mamá también le quiere mucho.... Es un muchacho muy formalito. Se retira temprano con [15] su tío; no va nunca al Casino por las noches, no juega ni derrocha, y trabaja en el bufete de D. Lorenzo Ruiz, que es el primer abogado de Orbajosa. Dicen que Jacinto será un gran defensor de pleitos.\"},{\"heading\":false,\"text\":\"--Su tío no exageraba al elogiarle--dijo Pepe.--Siento [20] mucho haber dicho aquellas tonterías sobre los abogados.... Querida prima, ¿no es verdad que estuve inconveniente?\"},{\"heading\":false,\"text\":\"--Calla, si a mí me parece que tienes mucha razón.\"},{\"heading\":false,\"text\":\"--¿Pero de veras, no estuve un poco?\"},{\"heading\":false,\"text\":\"--Nada, nada.\"},{\"heading\":false,\"text\":\"[25] --¡Qué peso me quitas de encima! La verdad es que me encontré, sin saber cómo, en una contradicción constante y penosa con ese venerable sacerdote. Lo siento mucho.\"},{\"heading\":false,\"text\":\"--Lo que yo creo--dijo Rosarito, clavando en él sus ojos llenos de expresión cariñosa,--es que tú no eres para [30] nosotros.\"},{\"heading\":false,\"text\":\"--¿Qué significa eso?\"},{\"heading\":false,\"text\":\"--No sé si me explico bien, primo. Quiero decir que no es fácil te acostumbres a la conversación ni a las ideas de la gente de Orbajosa. Se me figura... es una suposición.\"},{\"heading\":false,\"text\":\"--¡Oh! no: yo creo que te equivocas. 46\"},{\"heading\":false,\"text\":\"--Tú vienes de otra parte, de otro mundo, donde las personas son muy listas, muy sabias, y tienen unas maneras finas y un modo de hablar ingenioso, y una figura... [5] puede ser que no me explique bien. Quiero decir que estás habituado a vivir entre una sociedad escogida; sabes mucho... Aquí no hay lo que tú necesitas; aquí no hay gente sabia, ni grandes finuras. Todo es sencillez, Pepe. Se me figura que te aburrirás, que te aburrirás mucho, y al [10] fin tendrás que marcharte.\"},{\"heading\":false,\"text\":\"La tristeza, que era normal en el semblante de Rosarito, se mostró con tintas y rasgos tan notorios, que Pepe Rey sintió una emoción profunda.\"},{\"heading\":false,\"text\":\"--Estás en un error, querida prima. Ni yo traigo aquí [15] la idea que supones, ni mi carácter ni mi entendimiento están en disonancia con los caracteres y las ideas de aquí. Pero vamos a suponer por un momento que lo estuvieran.\"},{\"heading\":false,\"text\":\"--Vamos a suponerlo....\"},{\"heading\":false,\"text\":\"--En ese caso, tengo la firme convicción de que entre tú [20] y yo, entre nosotros dos, querida Rosario, se establecerá una armonía perfecta. Sobre esto no puedo engañarme. El corazón me dice que no me engaño.\"},{\"heading\":false,\"text\":\"Rosarito se ruborizó; pero esforzándose en hacer huir su sonrojo con sonrisas y miradas dirigidas aquí y allí, dijo:\"},{\"heading\":false,\"text\":\"[25] --No vengas ahora con artificios. Si lo dices porque yo he de encontrar siempre bien todo lo que digas, tienes razón.\"},{\"heading\":false,\"text\":\"--Rosario--exclamó el joven.--Desde que te vi, mi alma se sintió llena de una alegría muy viva... he sentido [30] al mismo tiempo un pesar, el de no haber venido antes a Orbajosa.\"},{\"heading\":false,\"text\":\"--Eso sí que no lo he de creer--dijo ella, afectando jovialidad para encubrir medianamente su emoción.--¿Tan pronto?... No vengas ahora con palabrotas... Mira, Pepe, yo soy una lugareña; yo no sé hablar más que cosas 47 vulgares; yo no sé francés; yo no me visto con elegancia; yo apenas sé tocar el piano; yo....\"},{\"heading\":false,\"text\":\"--¡Oh, Rosario!--exclamó con ardor el joven.--Dudaba [5] que fueses perfecta; ahora ya sé que lo eres.\"},{\"heading\":false,\"text\":\"Entró de súbito la madre. Rosarito, que nada tenía que contestar a las últimas palabras de su primo, conoció, sin embargo, la necesidad de decir algo, y mirando a su madre, habló así:\"},{\"heading\":false,\"text\":\"[10] --¡Ah! se me había olvidado poner la comida al loro.\"},{\"heading\":false,\"text\":\"--No te ocupes de eso ahora. ¿Para qué os estáis ahí? Lleva a tu primo a dar un paseo por la huerta.\"},{\"heading\":false,\"text\":\"La señora se sonreía con bondad maternal, señalando a su sobrino la frondosa arboleda que tras los cristales [15] aparecía.\"},{\"heading\":false,\"text\":\"--Vamos allá--dijo Pepe levantándose.\"},{\"heading\":false,\"text\":\"Rosarito se lanzó como un pájaro puesto en libertad hacia la vidriera.\"},{\"heading\":false,\"text\":\"--Pepe, que sabe tanto y ha de entender de árboles--afirmó [20] doña Perfecta,--te enseñará cómo se hacen los ingertos. A ver qué opina él de esos peralitos que se van a trasplantar.\"},{\"heading\":false,\"text\":\"--Ven, ven--dijo Rosarito desde fuera.\"},{\"heading\":false,\"text\":\"Llamaba a su primo con impaciencia. Ambos desaparecieron [25] entre el follaje. Doña Perfecta les vió alejarse, y después se ocupó del loro. Mientras le renovaba la comida, dijo en voz muy baja, con ademán pensativo:\"},{\"heading\":false,\"text\":\"--¡Qué despegado es! Ni siquiera le ha hecho una caricia al pobre animalito.\"},{\"heading\":false,\"text\":\"[30] Luego en voz alta añadió, creyendo en la posibilidad de ser oída por su cuñado:\"},{\"heading\":false,\"text\":\"--Cayetano, ¿qué te parece el sobrino?... ¡Cayetano!\"},{\"heading\":false,\"text\":\"Sordo gruñido indicó que el anticuario volvía al conocimiento de este miserable mundo.\"},{\"heading\":false,\"text\":\"--Cayetano.... 48\"},{\"heading\":false,\"text\":\"--Eso es... eso es...--murmuró con torpe voz el sabio,--ese caballerito sostendrá como todos la opinión errónea de que las estatuas de Mundogrande proceden de [5] la primera inmigración fenicia. Yo le convenceré....\"},{\"heading\":false,\"text\":\"--Pero Cayetano....\"},{\"heading\":false,\"text\":\"--Pero Perfecta.... ¡Bah! ¿También ahora sostendrás que he dormido?\"},{\"heading\":false,\"text\":\"--No, hombre, ¡qué he de sostener yo tal desatino!... [10] ¿Pero no me dices qué te parece ese joven?\"},{\"heading\":false,\"text\":\"Don Cayetano se puso la palma de la mano ante la boca para bostezar más a gusto, y después entabló una larga conversación con la señora. Los que nos han transmitido las noticias necesarias a la composición de esta historia, [15] pasan por alto aquel diálogo, sin duda porque fué demasiado secreto. En cuanto a lo que hablaron el ingeniero y Rosarito en la huerta aquella tarde, parece evidente que no es digno de mención.\"},{\"heading\":false,\"text\":\"En la tarde del siguiente día ocurrieron, sí, cosas que no [20] deben pasarse en silencio, por ser de la mayor gravedad. Hallábanse solos ambos primos a hora bastante avanzada de la tarde, después de haber discurrido por distintos parajes de la huerta, atentos el uno al otro y sin tener alma ni sentidos más que para verse y oírse.\"},{\"heading\":false,\"text\":\"[25] --Pepe--decía Rosario,--todo lo que me has dicho es una fantasía, una cantinela de esas que tan bien sabéis hacer los hombres de chispa. Tú piensas que, como soy lugareña, creo cuanto me dicen.\"},{\"heading\":false,\"text\":\"--Si me conocieras, como yo creo conocerte a ti, sabrías [30] que jamás digo sino lo que siento. Pero dejémonos de sutilezas tontas y de argucias de amantes que no conducen sino a falsear los sentimientos. Yo no hablaré contigo más lenguaje que el de la verdad. ¿Eres acaso una señorita a quien he conocido en el paseo o en la tertulia y con la cual pienso pasar un rato divertido? No. Eres mi prima. 49 Eres algo más.... Rosario, pongamos de una vez las cosas en su verdadero lugar. Fuera rodeos. Yo he venido aquí a casarme contigo.\"},{\"heading\":false,\"text\":\"[5] Rosario sintió que su rostro se abrasaba y el corazón no le cabía en el pecho.\"},{\"heading\":false,\"text\":\"--Mira, querida prima--añadió el joven,--te juro que si no me hubieras gustado, ya estaría lejos de aquí. Aunque la cortesía y la delicadeza me habrían obligado a hacer [10] esfuerzos, no me hubiera sido fácil disimular mi desengaño. Yo soy así.\"},{\"heading\":false,\"text\":\"--Primo, casi acabas de llegar--dijo lacónicamente Rosarito, esforzándose en reír.\"},{\"heading\":false,\"text\":\"--Acabo de llegar y ya sé todo lo que tenía que saber; [15] sé que te quiero; que eres la mujer que desde hace tiempo me está anunciando el corazón, diciéndome noche y día... \\\"ya viene, ya está cerca; que te quemas.\\\"\"},{\"heading\":false,\"text\":\"Esta frase sirvió de pretexto a Rosario para soltar la risa que en sus labios retozaba. Su espíritu se desvanecía [20] alborozado en una atmósfera de júbilo.\"},{\"heading\":false,\"text\":\"--Tú te empeñas en que no vales nada--continuó Pepe,--y eres una maravilla. Tienes la cualidad admirable de estar a todas horas proyectando sobre cuanto te rodea la divina luz de tu alma. Desde que se te ve, desde que se te [25] mira, los nobles sentimientos y la pureza de tu corazón se manifiestan. Viéndote, se ve una vida celeste que por descuido de Dios está en la tierra; eres un ángel y yo te adoro como un tonto.\"},{\"heading\":false,\"text\":\"Al decir esto, parecía haber desempeñado una grave [30] misión. Rosarito vióse de súbito dominada por tan viva sensibilidad, que la escasa energía de su cuerpo no pudo corresponder a la excitación de su espíritu, y desfalleciendo, dejóse caer sobre una piedra que hacía las veces de asiento en aquellos amenos lugares. Pepe se inclinó hacia ella. Notó que cerraba los ojos, apoyando la frente en la palma 50 de la mano. Poco después, la hija de doña Perfecta Polentinos dirigía a su primo, entre dulces lágrimas, una mirada tierna, seguida de estas palabras:\"},{\"heading\":false,\"text\":\"[5] --Te quiero desde antes de conocerte.\"},{\"heading\":false,\"text\":\"Apoyadas sus manos en las del joven, se levantó, y sus cuerpos desaparecieron entre las frondosas ramas de un paseo de adelfas. Caía la tarde, y una dulce sombra se extendía por la parte baja de la huerta, mientras el último [10] rayo del sol poniente coronaba de varios resplandores las cimas de los árboles. La ruidosa república de pajarillos armaba espantosa algarabía en las ramas superiores. Era la hora en que, después de corretear por la alegre inmensidad de los cielos, iban todos a acostarse, y se disputaban [15] unos a otros la rama que escogían por alcoba. Su charla parecía a veces recriminación y disputa, a veces burla y gracejo. Con su parlero trinar se decían aquellos tunantes las mayores insolencias, dándose de picotazos y agitando las alas, así como los oradores agitan los brazos cuando [20] quieren hacer creer las mentiras que están diciendo. Pero también sonaban por allí palabras de amor, que a ello convidaban la apacible hora y el hermoso lugar. Un oído experto hubiera podido distinguir las siguientes:\"},{\"heading\":false,\"text\":\"[25] --Desde antes de conocerte te quería, y si no hubieras venido me habría muerto de pena. Mamá me daba a leer las cartas de tu padre, y como en ellas hacía tantas alabanzas de ti, yo decía: \\\"éste debiera ser mi marido.\\\" Durante mucho tiempo, tu padre no habló de que tú y yo nos [30] casáramos, lo cual me parecía un descuido muy grande. Yo no sabía qué pensar de semejante negligencia.... Mi tío Cayetano, siempre que te nombraba, decía: \\\"Como ése hay pocos en el mundo. La mujer que le pesque, ya se puede tener por dichosa....\\\" Por fin tu papá dijo lo que no podía menos de decir.... Sí, no podía menos de 51 decirlo: yo lo esperaba todos los días....\"},{\"heading\":false,\"text\":\"Poco después de estas palabras, la misma voz añadió con zozobra:\"},{\"heading\":false,\"text\":\"[5] --Alguien viene tras de nosotros.\"},{\"heading\":false,\"text\":\"Saliendo de entre las adelfas, Pepe vió a dos personas que se acercaban, y tocando las hojas de un tierno arbolito que allí cerca había, dijo en alta voz a su compañera:\"},{\"heading\":false,\"text\":\"--No es conveniente aplicar la primera poda a los árboles [10] jóvenes como éste hasta su completo arraigo. Los árboles recién plantados no tienen vigor para soportar dicha operación. Tú bien sabes que las raíces no pueden formarse sino por el influjo de las hojas: así es que si le quitas las hojas....\"},{\"heading\":false,\"text\":\"--¡Ah! Sr. D. José--exclamó el Penitenciario con [15] franca risa, acercándose a los dos jóvenes y haciéndoles una reverencia.--¿Está usted dando lecciones de horticultura? _Insere nunc, Miliboee, piros, pone ordine vitis_, que dijo el gran cantor de los trabajos del campo. Ingerta los perales, caro Melibeo, arregla las parras.... ¿Con que cómo estamos [20] de salud, Sr. D. José?\"},{\"heading\":false,\"text\":\"El ingeniero y el canónigo se dieron las manos. Luego éste volvióse, y señalando a un jovenzuelo que tras él venía, dijo sonriendo:\"},{\"heading\":false,\"text\":\"--Tengo el gusto de presentar a usted a mi querido [25] Jacintillo... una buena pieza... un tarambana, Sr. D. José.\"}]},{\"title\":\"Capítulo IX\",\"blocks\":[{\"heading\":false,\"text\":\"=La desavenencia sigue creciendo y amenaza convertirse en discordia=\"},{\"heading\":false,\"text\":\"Junto a la negra sotana se destacó un sonrosado y fresco rostro. Jacintito saludó a nuestro joven, no sin cierto embarazo.\"},{\"heading\":false,\"text\":\"Era uno de esos chiquillos precoces a quienes la indulgente [30] Universidad lanza antes de tiempo a las arduas luchas del mundo, haciéndoles creer que son hombres porque son 52 doctores. Tenía Jacintito semblante agraciado y carilleno, con mejillas de rosa como una muchacha, y era rechoncho de cuerpo, de estatura pequeña, tirando un poco a pequeñísima, [5] y sin más pelo de barba que el suave bozo que lo anunciaba. Su edad excedía poco de los veinte años. Habíase educado desde la niñez bajo la dirección de su excelente y discreto tío, con lo cual dicho se está que el tierno arbolito no se torció al crecer. Una moral severa le [10] mantenía constantemente derecho, y en el cumplimiento de sus deberes escolásticos apenas tenía pero. Concluídos los estudios universitarios con aprovechamiento asombroso, pues no hubo clase en que no ganase las más eminentes notas, empezó a trabajar, prometiendo con su aplicación y [15] buen tino para la abogacía perpetuar en el foro el lozano verdor de los laureles del aula.\"},{\"heading\":false,\"text\":\"A veces era travieso como un niño, a veces formal como un hombre. En verdad, en verdad, que si a Jacintito no le gustaran un poco, y aun un mucho, las lindas muchachas, [20] su buen tío le creería perfecto. No dejaba de sermonearle a todas horas, apresurándose a cortarle los audaces vuelos; pero ni aun esta inclinación mundana del jovenzuelo lograba enfriar el mucho amor que nuestro buen canónigo tenía al encantador retoño de su cara sobrina María Remedios. [25] En tratándose del abogadillo, todo cedía. Hasta las graves y metódicas prácticas del buen sacerdote se alteraban siempre que se tratase de algún asunto referente a su precoz pupilo. Aquel método riguroso y fijo como un sistema planetario, solía perder su equilibrio cuando Jacintito [30] estaba enfermo o tenía que hacer un viaje. ¡Inútil celibato el de los clérigos! Si el Concilio de Trento les prohibe tener hijos, Dios, no el Demonio, les da sobrinos para que conozcan los dulces afanes de la paternidad.\"},{\"heading\":false,\"text\":\"Examinadas imparcialmente las cualidades de aquel aprovechado niño, era imposible desconocer que no carecía de 53 mérito. Su carácter era por lo común inclinado a la honradez, y las acciones nobles despertaban franca admiración en su alma. Respecto a sus dotes intelectuales y a su saber [5] social, tenía todo lo necesario para ser con el tiempo una notabilidad de estas que tanto abundan en España; podía ser lo que a todas horas nos complacemos en llamar hiperbólicamente un _distinguido patricio_ o _un eminente hombre público_, especies que por su mucha abundancia apenas son apreciadas [10] en su justo valor. En aquella tierna edad en que el grado universitario sirve de soldadura entre la puericia y la virilidad, pocos jóvenes, mayormente cuando han sido mimados por sus maestros, están libres de una pedantería fastidiosa, que si les da gran prestigio junto al sillón de sus [15] mamás, es muy risible entre hombres hechos y formales. Jacintito tenía este defecto, disculpable no sólo por sus pocos años, sino porque su buen tío fomentaba aquella vanidad pueril con imprudentes aplausos.\"},{\"heading\":false,\"text\":\"Luego que los cuatro se reunieron, continuaron paseando. [20] Jacinto callaba. El canónigo, volviendo al interrumpido tema de los _piros_ que se habían de ingertar y de las _vitis_ que se debían poner en orden, dijo:\"},{\"heading\":false,\"text\":\"--Ya sé que D. José es un gran agrónomo.\"},{\"heading\":false,\"text\":\"--Nada de eso; no sé una palabra--repuso el joven, [25] viendo con mucho disgusto aquella manía de suponerle instruido en todas las ciencias.\"},{\"heading\":false,\"text\":\"--¡Oh! sí; un gran agrónomo--añadió el Penitenciario;--pero en asuntos de agronomía no me citen tratados novísimos. Para mí toda esa ciencia, Sr. de Rey, está condensada [30] en lo que yo llamo la _Biblia del campo_, en las _Geórgicas_ del inmortal latino. Todo es admirable, desde aquella gran sentencia _Nec vero terrae ferre omnes omnia possunt_, es decir, que no todas las tierras sirven para todos los árboles, Sr. D. José, hasta el minucioso tratado de las abejas, en que el poeta explana lo concerniente a estos doctos animalitos, y 54 define al zángano, diciendo:\"},{\"heading\":false,\"text\":\"......................._Ille horridus alter Desidia, latamque trahens inglorius alvum_,\"},{\"heading\":false,\"text\":\"[5] de figura horrible y perezosa, arrastrando el innoble vientre pesado, Sr. D. José....\"},{\"heading\":false,\"text\":\"--Hace usted bien en traducírmelo--dijo Pepe,--porque entiendo muy poco el latín.\"},{\"heading\":false,\"text\":\"--¡Oh! los hombres del día ¿para qué habían de entretenerse [10] en estudiar antiguallas?--añadió el canónigo con ironía.--Además, en latín sólo han escrito los calzonazos como Virgilio, Cicerón y Tito Livio. Yo, sin embargo, estoy por lo contrario, y sea testigo mi sobrino, a quien he enseñado la sublime lengua. El tunante sabe más que yo. [15] Lo malo es que con las lecturas modernas lo va olvidando, y el mejor día se encontrará que es un ignorante, sin sospecharlo. Porque, señor D. José, a mi sobrino le ha dado por entretenerse con libros novísimos y teorías extravagantes, y todo es Flammarión arriba y abajo, y nada más sino que las [20] estrellas están llenas de gente. Vamos, se me figura que ustedes dos van a hacer buenas migas. Jacinto, ruégale a este caballero que te enseñe las matemáticas sublimes, que te instruya en lo concerniente a los filósofos alemanes, y ya eres un hombre.\"},{\"heading\":false,\"text\":\"[25] El buen clérigo se reía de sus propias ocurrencias, mientras Jacinto, gozoso de ver la conversación en terreno tan de su gusto, se excusó con Pepe Rey, y de buenas a primeras le descargó esta pregunta:\"},{\"heading\":false,\"text\":\"--Dígame el Sr. D. José, ¿qué piensa usted del Darwinismo?\"},{\"heading\":false,\"text\":\"[30] Sonrió nuestro joven al oír pedantería tan fuera de sazón, y de buena gana excitara al joven a seguir por aquella senda de infantil vanidad; pero creyendo más prudente no intimar mucho con el sobrino ni con el tío, contestó sencillamente:\"},{\"heading\":false,\"text\":\"--Yo no puedo pensar nada de las doctrinas de Darwin, 55 porque apenas las conozco. Los trabajos de mi profesión no me han permitido dedicarme a esos estudios.\"},{\"heading\":false,\"text\":\"--Ya--dijo el canónigo riendo.--Todo se reduce a que [5] descendemos de los monos... Si lo dijera sólo por ciertas personas que yo conozco, tendría razón.\"},{\"heading\":false,\"text\":\"--La teoría de la selección natural--añadió enfáticamente Jacinto,--dicen que tiene muchos partidarios en Alemania.\"},{\"heading\":false,\"text\":\"--No lo dudo--dijo el clérigo.--En Alemania no debe [10] sentirse que esa teoría sea verdadera, por lo que toca a Bismarck.\"},{\"heading\":false,\"text\":\"Doña Perfecta y el Sr. D. Cayetano aparecieron frente a los cuatro.\"},{\"heading\":false,\"text\":\"--¡Qué hermosa está la tarde!--dijo la señora.--¿Qué [15] tal, sobrino, te aburres mucho?...\"},{\"heading\":false,\"text\":\"--Nada de eso--repuso el joven.\"},{\"heading\":false,\"text\":\"--No me lo niegues. De eso veníamos hablando Cayetano y yo. Tú estás aburrido, y te empeñas en disimularlo. No todos los jóvenes de estos tiempos tienen la abnegación [20] de pasar su juventud, como Jacinto, en un pueblo donde no hay Teatro Real, ni Bufos, ni bailarinas, ni filósofos, ni ateneos, ni papeluchos; ni Congresos, ni otras diversiones y pasatiempos.\"},{\"heading\":false,\"text\":\"--Yo estoy aquí muy bien--repuso Pepe.--Ahora le [25] estaba diciendo a Rosario que esta ciudad y esta casa me son tan agradables, que me gustaría vivir y morir aquí.\"},{\"heading\":false,\"text\":\"Rosario se puso muy encendida y los demás callaron. Sentáronse todos en una glorieta, apresurándose Jacinto a ocupar el lugar a la izquierda de la señorita.\"},{\"heading\":false,\"text\":\"[30] --Mira, sobrino, tengo que advertirte una cosa--dijo doña Perfecta, con aquella risueña expresión de bondad que emanaba de su alma, como de la flor el aroma.--Pero no vayas a creer que te reprendo, ni que te doy lecciones: tú no eres niño y fácilmente comprenderás mis ideas.\"},{\"heading\":false,\"text\":\"--Ríñame usted, querida tía; que sin duda lo mereceré--replicó 56 Pepe, que ya empezaba a acostumbrarse a las bondades de la hermana de su padre.\"},{\"heading\":false,\"text\":\"--No, no es más que una advertencia. Estos señores [5] verán como tengo razón.\"},{\"heading\":false,\"text\":\"Rosarito oía con toda su alma.\"},{\"heading\":false,\"text\":\"--Pues no es más--añadió la señora,--sino que cuando vuelvas a visitar nuestra hermosa catedral procures estar en ella con un poco más de recogimiento.\"},{\"heading\":false,\"text\":\"[10] --Pues ¿qué he hecho yo?\"},{\"heading\":false,\"text\":\"--No extraño que tú mismo no conozcas tu falta--indicó la señora con aparente jovialidad.--Es natural; acostumbrado a entrar con la mayor desenvoltura en los ateneos, clubs, academias y congresos, crees que de la misma manera [15] se puede entrar en un templo donde está la Divina Majestad.\"},{\"heading\":false,\"text\":\"--Pero señora, dispénseme usted--dijo Pepe, con gravedad.--Yo he entrado en la catedral con la mayor compostura.\"},{\"heading\":false,\"text\":\"--Si no te riño, hombre, si no te riño. No lo tomes así, [20] porque tendré que callarme. Señores, disculpen ustedes a mi sobrino. No es de extrañar un descuidillo, una distracción... ¿Cuántos años hace que no pones los pies en lugar sagrado?\"},{\"heading\":false,\"text\":\"--Señora, yo juro a usted... Pero en fin, mis ideas [25] religiosas podrán ser lo que se quiera; pero acostumbro guardar la mayor compostura dentro de la iglesia.\"},{\"heading\":false,\"text\":\"--Lo que yo aseguro... vamos, si te has de ofender, no sigo... lo que aseguro es que muchas personas lo notaron esta mañana. Notáronlo los señores de González, [30] doña Robustiana, Serafinita, en fin... con decirte que llamaste la atención del señor obispo... Su Ilustrísima me dió las quejas esta tarde en casa de mis primas. Díjome que no te mandó plantar en la calle porque le dijeron que eras sobrino mío.\"},{\"heading\":false,\"text\":\"Rosario contemplaba con angustia el rostro de su primo, 57 procurando adivinar sus contestaciones antes que las diera.\"},{\"heading\":false,\"text\":\"--Sin duda me han tomado por otro.\"},{\"heading\":false,\"text\":\"--No... no... fuiste tú... Pero no vayas a ofenderte, [5] que aquí estamos entre amigos y personas de confianza. Fuiste tú, yo misma te vi.\"},{\"heading\":false,\"text\":\"--¡Usted!\"},{\"heading\":false,\"text\":\"--Justamente. ¿Negarás que te pusiste a examinar las pinturas, pasando por un grupo de fieles que estaban oyendo [10] misa?... Te juro que me distraje de tal modo con tus idas y venidas, que... Vamos... es preciso que no lo vuelvas a hacer. Luego entraste en la capilla de San Gregorio; alzaron en el altar mayor y ni siquiera te volviste para hacer una demostración de religiosidad. Después [15] atravesaste de largo a largo la iglesia, te acercaste al sepulcro del Adelantado, pusiste las manos sobre el altar, pasaste en seguida otra vez por entre el grupo de los fieles, llamando la atención. Todas las muchachas te miraban y tú parecías satisfecho de perturbar tan lindamente la devoción y ejemplaridad [20] de aquella buena gente.\"},{\"heading\":false,\"text\":\"--¡Dios mío! ¡Todo lo que he hecho!...--exclamó Pepe, entre enojado y risueño.--Soy un monstruo y ni siquiera lo sospechaba.\"},{\"heading\":false,\"text\":\"--No, bien sé que eres un buen muchacho--dijo doña [25] Perfecta, observando el semblante afectadamente serio e inmutable del canónigo, que parecía tener por cara una máscara de cartón.--Pero, hijo, de pensar las cosas a manifestarlas así con cierto desparpajo, hay una distancia que el hombre prudente y comedido no debe salvar nunca. [30] Bien sé que tus ideas son... no te enfades; si te enfadas, me callo... digo que una cosa es tener ideas religiosas y otra manifestarlas... Me guardaré muy bien de vituperarte porque creas que no nos crió Dios a su imagen y semejanza, sino que descendemos de los micos; ni porque niegues la existencia del alma, asegurando que ésta es una 58 droga como los papelillos de magnesia o de ruibarbo que se venden en la botica....\"},{\"heading\":false,\"text\":\"--Señora, por Dios...--exclamó Pepe con disgusto.--Veo [5] que tengo muy mala reputación en Orbajosa.\"},{\"heading\":false,\"text\":\"Los demás seguían guardando silencio.\"},{\"heading\":false,\"text\":\"--Pues decía que no te vituperaré por esas ideas... Además de que no tengo derecho a ello, si me pusiera a disputar contigo, tú, con tu talentazo descomunal, me confundirías [10] mil veces... no, nada de eso. Lo que digo es que estos pobres y menguados habitantes de Orbajosa son piadosos y buenos cristianos, si bien ninguno de ellos sabe filosofía alemana; por lo tanto no debes despreciar públicamente sus creencias.\"},{\"heading\":false,\"text\":\"[15] --Querida tía--dijo el ingeniero con gravedad.--Ni yo he despreciado las creencias de nadie, ni yo tengo las ideas que usted me atribuye. Quizás haya estado un poco irrespetuoso en la iglesia; soy algo distraído. Mi entendimiento y mi atención estaban fijos en la obra arquitectónica, y [20] francamente no advertí... pero no era esto motivo para que el señor obispo intentase echarme a la calle, y usted me supusiera capaz de atribuir a un papelillo de la botica las funciones del alma. Puedo tolerar eso como broma, nada más que como broma.\"},{\"heading\":false,\"text\":\"[25] Pepe Rey sentía en su espíritu excitación tan viva, que a pesar de su mucha prudencia y mesura no pudo disimularla.\"},{\"heading\":false,\"text\":\"--Vamos, veo que te has enfadado--dijo doña Perfecta, bajando los ojos y cruzando las manos.--¡Todo sea por [30] Dios! Si hubiera sabido que lo tomabas así, no te habría dicho nada. Pepe, te ruego que me perdones.\"},{\"heading\":false,\"text\":\"Al oír esto y al ver la actitud sumisa de su bondadosa tía, Pepe se sintió avergonzado de la dureza de sus anteriores palabras, y procuró serenarse. Sacóle de su embarazosa situación el venerable Penitenciario, que sonriendo 59 con su habitual benevolencia, habló de este modo:\"},{\"heading\":false,\"text\":\"--Señora doña Perfecta, es preciso tener tolerancia con los artistas... ¡oh! yo he conocido muchos. Estos [5] señores, como vean delante de sí una estatua, una armadura mohosa, un cuadro podrido o una pared vieja, se olvidan de todo. El Sr. D. José es artista, y ha visitado nuestra catedral, como la visitan los Ingleses, los cuales de buena gana se llevarían a sus museos hasta la última baldosa de [10] ella... Que estaban los fieles rezando; que el sacerdote alzó la Sagrada Hostia; que llegó el instante de la mayor piedad y recogimiento; pues bien... ¿qué le importa nada de esto a un artista? Es verdad que yo no sé lo que vale el arte, cuando se le disgrega de los sentimientos que [15] expresa... pero en fin, hoy es costumbre adorar la forma, no la idea... Líbreme Dios de meterme a discutir este tema con el Sr. D. José, que sabe tanto, y argumentando con la primorosa sutileza de los modernos, confundiría al punto mi espíritu, en el cual no hay más que fe.\"},{\"heading\":false,\"text\":\"[20] --El empeño de ustedes de considerarme como el hombre más sabio de la tierra, me mortifica bastante--dijo Pepe, recobrando la dureza de su acento.--Ténganme por tonto; que prefiero la fama de necio a poseer esa ciencia de Satanás que aquí me atribuyen.\"},{\"heading\":false,\"text\":\"[25] Rosarito se echó a reír, y Jacinto creyó llegado el momento más oportuno para hacer ostentación de su erudita personalidad.\"},{\"heading\":false,\"text\":\"--El panteísmo o panenteísmo están condenados por la Iglesia, así como por las doctrinas de Schopenhauer y el [30] moderno Hartmann.\"},{\"heading\":false,\"text\":\"--Señores y señoras--manifestó gravemente el canónigo,--los hombres que consagran culto tan fervoroso al arte, aunque sólo sea atendiendo a la forma, merecen el mayor respeto. Más vale ser artista y deleitarse ante la belleza, aunque sólo esté representada en las ninfas desnudas, que 60 ser indiferente y descreído en todo. En espíritu que se consagra a la contemplación de la belleza no entrará completamente el mal. _Est Deus in nobis... Deus_, entiéndase [5] bien. Siga, pues, el señor D. José admirando los prodigios de nuestra iglesia; que por mi parte le perdonaré de buen grado las irreverencias, salva la opinión del señor prelado.\"},{\"heading\":false,\"text\":\"--Gracias, Sr. D. Inocencio--dijo Pepe, sintiendo en sí [10] punzante y revoltoso el sentimiento de hostilidad hacia el astuto canónigo y no pudiendo dominar el deseo de mortificarle. --Por lo demás, no crean ustedes que absorbían mi atención las bellezas artísticas de que suponen lleno el templo. Esas bellezas, fuera de la imponente arquitectura [15] de una parte del edificio y de los tres sepulcros que hay en las capillas del ábside y de algunos entalles del coro, yo no las veo en ninguna parte. Lo que ocupaba mi entendimiento era la consideración de la deplorable decadencia de las artes religiosas, y no me causaban asombro, sino cólera, [20] las innumerables monstruosidades artísticas de que está llena la catedral.\"},{\"heading\":false,\"text\":\"El estupor de los circunstantes fué extraordinario.\"},{\"heading\":false,\"text\":\"--No puedo resistir--añadió Pepe,--aquellas imágenes charoladas y bermellonadas, tan semejantes, perdóneme [25] Dios la comparación, a las muñecas con que juegan las niñas grandecitas. ¿Qué puedo decir de los vestidos de teatro con que las cubren? Vi un San José con manto, cuya facha no quiero calificar por respeto al Santo Patriarca y a la Iglesia que le adora. En los altares se acumulan [30] imágenes del más deplorable gusto artístico, y la multitud de coronas, ramos, estrellas, lunas y demás adornos de metal o papel dorado forman un aspecto de quincallería que ofende el sentimiento religioso y hace desmayar nuestro espíritu. Lejos de elevarse a la contemplación religiosa, se abate, y la idea de lo cómico le perturba. Las grandes 61 obras del arte, dando formas sensibles a las ideas, a los dogmas, a la fe, a la exaltación mística, realizan misión muy noble. Los mamarrachos y las aberraciones del gusto, las [5] obras grotescas con que una piedad mal entendida llena las iglesias, también cumplen su objeto; pero éste es bastante triste: fomentan la superstición, enfrían el entusiasmo, obligan a los ojos del creyente a apartarse de los altares, y con los ojos se apartan las almas que no tienen fe muy profunda [10] ni muy segura.\"},{\"heading\":false,\"text\":\"--La doctrina de los iconoclastas--dijo Jacintito,--también parece que está muy extendida en Alemania.\"},{\"heading\":false,\"text\":\"--Yo no soy iconoclasta, aunque prefiero la destrucción de todas las imágenes a esta exhibición de chocarrerías de [15] que me ocupo--continuó el joven.--Al ver esto, es lícito defender que el culto debe recobrar la sencillez augusta de los antiguos tiempos; pero no: no se renuncie al auxilio admirable que las artes todas, empezando por la poesía y acabando por la música, prestan a las relaciones entre el [20] hombre y Dios. Vivan las artes, despliéguese la mayor pompa en los ritos religiosos. Yo soy partidario de la pompa....\"},{\"heading\":false,\"text\":\"--Artista, artista y nada más que artista--exclamó el canónigo, moviendo la cabeza con expresión de lástima.--Buenas [25] pinturas, buenas estatuas, bonita música... Gala de los sentidos, y el alma que se la lleve el Demonio.\"},{\"heading\":false,\"text\":\"--Y a propósito de música--dijo Pepe Rey, sin advertir el deplorable efecto que sus palabras producían en la madre y la hija,--figúrense ustedes qué dispuesto estaría mi espíritu [30] a la contemplación religiosa al visitar la catedral, cuando de buenas a primeras y al llegar al ofertorio en la misa mayor, el señor organista tocó un pasaje de _La Traviata_.\"},{\"heading\":false,\"text\":\"--En eso tiene razón el Sr. de Rey--dijo el abogadillo enfáticamente.--El señor organista tocó el otro día todo el brindis y el wals de la misma ópera y después un rondó de 62 _La Gran Duquesa_.\"},{\"heading\":false,\"text\":\"--Pero cuando se me cayeron las alas del corazón--continuó el ingeniero implacablemente,--fué cuando vi [5] una imagen de la Virgen que parece estar en gran veneración, según la mucha gente que ante ella había y la multitud de velas que la alumbraban. La han vestido con ahuecado ropón de terciopelo bordado de oro, de tan extraña forma que supera a las modas más extravagantes del día. Desaparece [10] su cara entre un follaje espeso, compuesto de mil suertes de encajes rizados con tenacillas, y la corona de media vara de alto, rodeada de rayos de oro, es un disforme catafalco que le han armado sobre la cabeza. De la misma tela y con los mismos bordados son los pantalones del Niño [15] Jesús... No quiero seguir, porque la descripción de cómo están la madre y el hijo me llevaría quizás a cometer alguna irreverencia. No diré más, sino que me fué imposible tener la risa y que por breve rato contemplé la profanada imagen, exclamando: \\\"¡Madre y señora mía, cómo te han puesto!\\\"\"},{\"heading\":false,\"text\":\"[20] Concluídas estas palabras, Pepe observó a sus oyentes, y aunque a causa de la sombra crepuscular no se distinguían bien los semblantes, creyó ver en alguno de ellos señales de amarga consternación.\"},{\"heading\":false,\"text\":\"--Pues Sr. D. José--exclamó vivamente el canónigo, [25] riendo y con expresión de triunfo,--esa imagen que a la filosofía y panteísmo de usted parece tan ridícula, es nuestra Señora del Socorro, patrona y abogada de Orbajosa, cuyos habitantes la veneran de tal modo que serían capaces de arrastrar por las calles al que hablase mal de ella. Las [30] crónicas y la historia, señor mío, están llenas de los milagros que ha hecho, y aun hoy día vemos constantemente pruebas irrecusables de su protección. Ha de saber usted también que su señora tía doña Perfecta es camarera mayor de la Santísima Virgen del Socorro, y que ese vestido que a usted le parece tan grotesco... pues... digo que ese 63 vestido tan grotesco a los impíos ojos de usted, salió de esta casa, y que los pantalones del Niño obra son juntamente de la maravillosa aguja y de la acendrada piedad de [5] su prima de usted, Rosarito, que nos está oyendo.\"},{\"heading\":false,\"text\":\"Pepe Rey se quedó bastante desconcertado. En el mismo instante levantóse bruscamente doña Perfecta, y sin decir una palabra se dirigió hacia la casa, seguida por el señor Penitenciario. Levantáronse también los restantes. [10] Disponíase el aturdido joven a pedir perdón a su prima por la irreverencia, cuando observó que Rosarito lloraba. Clavando en su primo una mirada de amistosa y dulce reprensión, exclamó:\"},{\"heading\":false,\"text\":\"--¡Pero qué cosas tienes!\"},{\"heading\":false,\"text\":\"[15] Oyóse la voz de doña Perfecta que con alterado acento gritaba:\"},{\"heading\":false,\"text\":\"--¡Rosario, Rosario!\"},{\"heading\":false,\"text\":\"Ésta corrió hacia la casa.\"}]},{\"title\":\"Capítulo X\",\"blocks\":[{\"heading\":false,\"text\":\"=La existencia de la discordia es evidente=\"},{\"heading\":false,\"text\":\"Pepe Rey se encontraba turbado y confuso, furioso contra [20] los demás y contra sí mismo, procurando indagar la causa de aquella pugna entablada a pesar suyo entre su pensamiento y el pensamiento de los amigos de su tía. Pensativo y triste, augurando discordias, permaneció breve rato sentado en el banco de la glorieta, con la barba apoyada en el pecho, [25] fruncido el ceño, cruzadas las manos. Se creía solo.\"},{\"heading\":false,\"text\":\"De repente sintió una alegre voz que modulaba entre dientes el estribillo de una canción de zarzuela. Miró y vio a D. Jacinto en el rincón opuesto de la glorieta.\"},{\"heading\":false,\"text\":\"--¡Ah! Sr. de Rey--dijo de improviso el rapaz,--no [30] se lastiman impunemente los sentimientos religiosos de la inmensa mayoría de una nación... Si no, considere usted 64 lo que pasó en la primera revolución francesa....\"},{\"heading\":false,\"text\":\"Cuando Pepe oyó el zumbidillo de aquel insecto, su irritación creció. Sin embargo, no había odio en su alma [5] contra el mozalvete doctor. Éste le mortificaba como mortifican las moscas; pero nada más. Rey sintió la molestia que inspiran todos los seres importunos, y como quien ahuyenta un zángano, contestó de este modo:\"},{\"heading\":false,\"text\":\"--¿Qué tiene que ver la revolución francesa con el manto [10] de la Virgen María?\"},{\"heading\":false,\"text\":\"Levantóse para marchar hacia la casa, pero no había dado cuatro pasos, cuando oyó de nuevo el zumbar del mosquito que decía:\"},{\"heading\":false,\"text\":\"--Sr. D. José, tengo que hablar a usted de un asunto que [15] le interesa mucho, y que puede traerle algún conflicto....\"},{\"heading\":false,\"text\":\"--¿Un asunto?--preguntó el joven retrocediendo.--Veamos qué es eso.\"},{\"heading\":false,\"text\":\"--Usted lo sospechará tal vez--dijo Jacinto, acercándose a Pepe, y sonriendo con expresión parecida a la de los [20] hombres de negocios, cuando se ocupan de alguno muy grave.--Quiero hablar a usted del pleito....\"},{\"heading\":false,\"text\":\"--¿Qué pleito?... Amigo mío, yo no tengo pleitos. Usted, como buen abogado, sueña con litigios y ve papel sellado por todas partes.\"},{\"heading\":false,\"text\":\"[25] --¿Pero cómo?... ¿No tiene usted noticia de su pleito?--exclamó con asombro el niño.\"},{\"heading\":false,\"text\":\"--¡De mi pleito!... Cabalmente, yo no tengo pleitos, ni los he tenido nunca.\"},{\"heading\":false,\"text\":\"--Pues si no tiene usted noticia, más me alegro de habérselo [30] advertido para que se ponga en guardia... Sí, señor, usted pleiteará.\"},{\"heading\":false,\"text\":\"--Y ¿con quién?\"},{\"heading\":false,\"text\":\"--Con el tío Licurgo y otros colindantes del predio llamado los _Alamillos_.\"},{\"heading\":false,\"text\":\"Pepe Rey se quedó estupefacto. 65\"},{\"heading\":false,\"text\":\"--Sí señor--añadió el abogadillo.--Hoy hemos celebrado el Sr. Licurgo y yo una larga conferencia. Como soy tan amigo de esta casa, no he querido dejar de advertírselo [5] a usted, para que si lo cree conveniente, se apresure a arreglarlo todo.\"},{\"heading\":false,\"text\":\"--Pero yo ¿qué tengo que arreglar? ¿Qué pretende de mí esa canalla?\"},{\"heading\":false,\"text\":\"--Parece que unas aguas que nacen en el predio de usted [10] han variado de curso y caen sobre unos tejares del susodicho Licurgo y un molino de otro, ocasionando daños de consideración. Mi cliente... porque se ha empeñado en que le he de sacar de este mal paso... mi cliente, digo, pretende que usted restablezca el antiguo cauce de las aguas, para [15] evitar nuevos desperfectos y que le indemnice de los perjuicios que por indolencia del propietario superior ha sufrido.\"},{\"heading\":false,\"text\":\"--¡Y el propietario superior soy yo!... Si entro en un litigio, ese será el primer fruto que en toda la vida me han dado los célebres Alamillos, que fueron míos, y que [20] ahora, según entiendo, son de todo el mundo, porque lo mismo Licurgo que otros labradores de la comarca, me han ido cercenando poco a poco, año tras año, pedazos de terreno, y costará mucho restablecer los linderos de mi propiedad.\"},{\"heading\":false,\"text\":\"[25] --Ésa es cuestión aparte.\"},{\"heading\":false,\"text\":\"--Ésa no es cuestión aparte. Lo que hay--exclamó el ingeniero, sin poder contener su cólera,--es que el verdadero pleito será el que yo entable contra tal gentuza, que se propone sin duda aburrirme y desesperarme, para que [30] abandone todo y les deje continuar en posesión de sus latrocinios. Veremos si hay abogados y jueces que apadrinen los torpes manejos de esos aldeanos legistas, que viven pleiteando y son la polilla de la propiedad ajena. Caballerito, doy a usted las gracias por haberme advertido los ruines propósitos de esos palurdos más malos que Caco. 66 Con decirle a usted que ese mismo tejar y ese mismo molino en que Licurgo apoya sus derechos, son míos....\"},{\"heading\":false,\"text\":\"--Debe hacerse una revisión de los títulos de propiedad [5] y ver si ha podido haber prescripción en esto--dijo Jacintito.\"},{\"heading\":false,\"text\":\"--¡Qué prescripción ni qué....! Esos infames no se reirán de mí. Supongo que la administración de justicia sea honrada y leal en la ciudad de Orbajosa....\"},{\"heading\":false,\"text\":\"--¡Oh, lo que es eso!--exclamó el letradillo con [10] expresión de alabanza. El juez es una persona excelente. Viene aquí todas las noches.... Pero es extraño que usted no tuviera noticias de las pretensiones del Sr. Licurgo. ¿No le han citado aún para el juicio de conciliación?\"},{\"heading\":false,\"text\":\"--No.\"},{\"heading\":false,\"text\":\"[15] --Será mañana.... En fin, yo siento mucho que el apresuramiento del Sr. Licurgo me haya privado del gusto y de la honra de defenderle a usted, pero como ha de ser.... Licurgo se ha empeñado en que yo le he de sacar de penas. Estudiaré la materia con el mayor detenimiento. Estas [20] pícaras servidumbres son el gran escollo de la jurisprudencia.\"},{\"heading\":false,\"text\":\"Pepe entró en el comedor en un estado moral muy lamentable. Vió a doña Perfecta hablando con el Penitenciario, y a Rosarito sola, con los ojos fijos en la puerta. [25] Esperaba sin duda a su primo.\"},{\"heading\":false,\"text\":\"--Ven acá, buena pieza--dijo la señora, sonriendo con muy poca espontaneidad.--Nos has insultado, gran ateo; pero te perdonamos. Ya sé que mi hija y yo somos dos palurdas incapaces de remontarnos a las regiones de las [30] matemáticas, donde tú vives; pero en fin... todavía es posible que algún día te pongas de rodillas ante nosotros, rogándonos que te enseñemos la doctrina.\"},{\"heading\":false,\"text\":\"Pepe contestó con frases vagas y fórmulas de cortesía y arrepentimiento.\"},{\"heading\":false,\"text\":\"--Por mi parte--dijo D. Inocencio, poniendo en los 67 ojos expresión de modestia y dulzura,--si en el curso de estas vanas disputas he dicho algo que pueda ofender al Sr. D. José, le ruego que me perdone. Aquí todos somos [5] amigos.\"},{\"heading\":false,\"text\":\"--Gracias. No vale la pena.\"},{\"heading\":false,\"text\":\"--A pesar de todo--indicó doña Perfecta, sonriendo ya con más naturalidad,--yo soy siempre la misma para mi querido sobrino, a pesar de sus ideas extravagantes y [antireligiosas...] [10] ¿De qué creerás que me pienso ocupar esta noche? Pues de quitarle de la cabeza al tío Licurgo esas terquedades con que te piensa molestar. Le he mandado venir, y en la galería me está esperando. Descuida, que yo lo arreglaré, pues aunque conozco que no le falta [15] razón....\"},{\"heading\":false,\"text\":\"--Gracias, querida tía--repuso el joven, sintiéndose invadido por la onda de generosidad que tan fácilmente nacía en su alma.\"},{\"heading\":false,\"text\":\"Pepe Rey dirigió la vista hacia donde estaba su prima, [20] con intención de unirse a ella; pero algunas preguntas sagaces del canónigo le retuvieron al lado de doña Perfecta. Rosario estaba triste, oyendo con indiferencia melancólica las palabras del abogadillo, que instalándose junto a ella, había comenzado una retahila de conceptos empalagosos, [25] con importunos chistes sazonada y fatuidades del peor gusto.\"},{\"heading\":false,\"text\":\"--Lo peor para ti--dijo doña Perfecta a su sobrino cuando le sorprendió observando la desacorde pareja que formaban Rosario y Jacinto,--es que has ofendido a la [30] pobre Rosario. Debes hacer todo lo posible por desenojarla. ¡La pobrecita es tan buena!...\"},{\"heading\":false,\"text\":\"--¡Oh, sí, tan buena!--añadió el canónigo,--que no dudo perdonará a su primo.\"},{\"heading\":false,\"text\":\"--Creo que Rosario me ha perdonado ya--afirmó Rey.\"},{\"heading\":false,\"text\":\"--Y si no, en corazones angelicales no dura mucho el 68 resentimiento--dijo D. Inocencio melifluamente.--Yo tengo gran ascendiente sobre esa niña, y procuraré disipar en su alma generosa toda prevención contra usted. En cuanto yo [5] le diga dos palabras....\"},{\"heading\":false,\"text\":\"Pepe Rey sintió que por su pensamiento pasaba una nube y dijo con intención:\"},{\"heading\":false,\"text\":\"--Tal vez no sea preciso.\"},{\"heading\":false,\"text\":\"--No le hablo ahora--añadió el capitular,--porque [10] está embelesada oyendo las tonterías de Jacintillo.... ¡Demonches de chicos! Cuando pegan la hebra, hay que dejarles.\"},{\"heading\":false,\"text\":\"De pronto se presentaron en la tertulia el juez de primera instancia, la señora del alcalde y el deán de la catedral. Todos saludaron al ingeniero, demostrando en sus palabras [15] y actitudes que satisfacían, al verle, la más viva curiosidad. El juez era un mozalvete despabilado, de estos que todos los días aparecen en los criaderos de eminencias, aspirando recién empollados a los primeros puestos de la administración y de la política. Dábase suma importancia, y [20] hablanco de sí mismo y de su juvenil toga, parecía manifestar indirectamente gran enojo, porque no le hubieran hecho de golpe y porrazo presidente del Tribunal Supremo. En aquellas manos inexpertas, en aquel cerebro henchido de viento, en aquella presunción ridícula había puesto el Estado las [25] funciones más delicadas y más difíciles de la humana justicia. Sus maneras eran de perfecto cortesano, y revelaba escrupuloso y detallado esmero en todo lo concerniente a su persona. Tenía la maldita manía de estarse quitando y poniendo a cada instante los lentes de oro, y en su [30] conversación frecuentemente indicaba el empeño de ser transladado pronto a _Madriz_, para prestar sus imprescindibles servicios en la secretaría de Gracia y Justicia.\"},{\"heading\":false,\"text\":\"La señora del alcalde era una dama bonachona, sin otra flaqueza que suponerse muy relacionada en la Corte. Dirigió a Pepe Rey diversas preguntas sobre modas, citando establecimientos industriales donde le habían hecho una manteleta 69 o una falda en su último viaje, coetáneo de la visita de Muley-Abbas, y también nombró a una docena de duquesas [5] y marquesas, tratándolas con tanta familiaridad como a amiguitas de escuela. Dijo también que la condesa de M. (por sus tertulias famosa) era amiga suya, y que el 60 estuvo a visitarla, y la condesa la convidó a su palco en el Real, donde vio a Muley-Abbas en traje de moro, acompañado [10] de toda su morería. La alcaldesa hablaba por los codos, como suele decirse, y no carecía de chiste.\"},{\"heading\":false,\"text\":\"El señor deán era un viejo de edad avanzada, corpulento y encendido, pletórico, apoplético, un hombre que se salía fuera de sí mismo por no caber en su propio pellejo, según [15] estaba de gordo y morcilludo. Procedía de la exclaustración; no hablaba más que de asuntos religiosos, y desde el principio mostró hacia Pepe Rey el desdén más vivo. Éste se mostraba cada vez más inepto para acomodarse a sociedad tan poco de su gusto. Era su carácter nada maleable, [20] duro y de muy escasa flexibilidad, y rechazaba las perfidias y acomodamientos de lenguaje para simular la concordia cuando no existía. Mantúvose, pues, bastante grave durante el curso de la fastidiosa tertulia, obligado a resistir el ímpetu oratorio de la alcaldesa que, sin ser la Fama, tenía el privilegio [25] de fatigar con cien lenguas el oído humano. Si en el breve respiro que esta señora daba a sus oyentes, Pepe Rey quería acercarse a su prima, pegábasele el Penitenciario como el molusco a la roca, y llevándole aparte con ademán misterioso, le proponía un paseo a Mundogrande con el [30] Sr. D. Cayetano o una partida de pesca en las claras aguas del Nahara.\"},{\"heading\":false,\"text\":\"Por fin esto concluyó, porque todo concluye en este mundo. Retiróse el señor deán, dejando la casa vacía, y bien pronto no quedó de la señora alcaldesa más que un eco, semejante al zumbido que recuerda en la humana oreja 70 el reciente paso de una tempestad. El juez privó también a la tertulia de su presencia, y por fin D. Inocencio dió a su sobrino la señal de partida.\"},{\"heading\":false,\"text\":\"[5] --Vamos, niño, vámonos que es tarde--le dijo sonriendo. --¡Cuánto has mareado a la pobre Rosarito!... ¿Verdad, niña? Anda, buena pieza, a casa pronto.\"},{\"heading\":false,\"text\":\"--Es hora de acostarse--dijo doña Perfecta.\"},{\"heading\":false,\"text\":\"--Hora de trabajar--repuso el abogadillo.\"},{\"heading\":false,\"text\":\"[10] --Por más que le digo que despache los negocios de día--añadió el canónigo,--no hace caso.\"},{\"heading\":false,\"text\":\"--¡Son tantos los negocios... pero tantos...!\"},{\"heading\":false,\"text\":\"--No, di más bien que esa endiablada obra en que te has metido... Él no lo quiere decir, Sr. D. José; pero sepa [15] usted que se ha puesto a escribir una obra sobre _La influencia de la mujer en la sociedad cristiana_, y además una _Ojeada sobre el movimiento católico en_... no sé dónde. ¿Qué entiendes tú de _ojeadas_ ni de _influencias_?... Estos rapaces del día se atreven a todo. ¡Uf... qué chicos!... [20] Con que vámonos a casa. Buenas noches, señora doña Perfecta... buenas noches, Sr. D. José... Rosarito....\"},{\"heading\":false,\"text\":\"--Yo esperaré al Sr. D. Cayetano--dijo Jacinto,--para que me dé el _Augusto Nicolás._\"},{\"heading\":false,\"text\":\"--¡Siempre cargando libros... hombre!... A veces [25] entras en casa que pareces un burro. Pues bien, esperemos.\"},{\"heading\":false,\"text\":\"--El Sr. D. Jacinto--dijo Pepe Rey,--no escribe a la ligera y se prepara bien para que sus obras sean un tesoro de erudición.\"},{\"heading\":false,\"text\":\"--Pero ese niño va a enfermar de la cabeza, Sr. D. Inocencio-- [30] objetó doña Perfecta.--Por Dios, mucho cuidado. Yo le pondría tasa en sus lecturas.\"},{\"heading\":false,\"text\":\"--Ya que esperamos--indicó el doctorcillo con notorio acento de presunción,--me llevaré también el tercer tomo de _Concilios_, ¿No le parece a usted, tío?...\"},{\"heading\":false,\"text\":\"--Hombre, sí; no dejes eso de la mano. Pues no 71 faltaba más.\"},{\"heading\":false,\"text\":\"Felizmente llegó pronto el Sr. D. Cayetano (que tertuliaba de ordinario en casa de D. Lorenzo Ruiz), y entregados los [5] libros, marcháronse tío y sobrino.\"},{\"heading\":false,\"text\":\"Rey leyó en el triste semblante de su prima deseo muy vivo de hablarle. Acercóse a ella mientras doña Perfecta y D. Cayetano trataban a solas de un negocio doméstico.\"},{\"heading\":false,\"text\":\"--Has ofendido a mamá--le dijo Rosario.\"},{\"heading\":false,\"text\":\"[10] Sus facciones indicaban una especie de terror.\"},{\"heading\":false,\"text\":\"--Es verdad--repuso el joven.--He ofendido a tu mamá: te he ofendido a ti....\"},{\"heading\":false,\"text\":\"--No; a mí no. Ya se me figuraba a mí que el Niño Jesús no debe gastar calzones.\"},{\"heading\":false,\"text\":\"[15] --Pero espero que una y otra me perdonarán. Tu mamá me ha manifestado hace poco tanta bondad....\"},{\"heading\":false,\"text\":\"La voz de doña Perfecta vibró de súbito en el ámbito del comedor, con tan discorde acento, que el sobrino se estremeció cual si oyese un grito de alarma. La voz dijo [20] imperiosamente:\"},{\"heading\":false,\"text\":\"--¡Rosario, vete a acostar!\"},{\"heading\":false,\"text\":\"Turbada y llena de congoja, la muchacha dió varias vueltas por la habitación, haciendo como que buscaba alguna cosa. Con todo disimulo pronunció al pasar por [25] junto a su primo estas vagas palabras:\"},{\"heading\":false,\"text\":\"--Mamá está enojada....\"},{\"heading\":false,\"text\":\"--Pero....\"},{\"heading\":false,\"text\":\"--Está enojada... no te fíes, no te fíes.\"},{\"heading\":false,\"text\":\"Y se marchó. Siguióla después doña Perfecta, a quien [30] aguardaba el tío Licurgo, y durante un rato, las voces de la señora y del aldeano oyéronse confundidas en familiar conferencia. Quedóse solo Pepe con D. Cayetano, el cual, tomando una luz, habló así:\"},{\"heading\":false,\"text\":\"--Buenas noches, Pepe. No crea usted que voy a dormir, voy a trabajar... ¿Pero por qué está usted tan 72 meditabundo? ¿Qué tiene usted?... Pues, sí, a trabajar. Estoy sacando apuntes para un _Discurso-Memoria_ sobre los _Linajes de Orbajosa_... He encontrado datos y noticias de [5] grandísimo precio. No hay que darle vueltas. En todas las épocas de nuestra historia los orbajosenses se han distinguido por su hidalguía, por su nobleza, por su valor, por su entendimiento. Díganlo si no la conquista de Méjico, las guerras del Emperador, las de Felipe contra herejes... [10] ¿Pero está usted malo? ¿Qué le pasa a usted?... Pues, sí, teólogos eminentes, bravos guerreros, conquistadores, santos, obispos, poetas, políticos, toda suerte de hombres esclarecidos florecieron en esta humilde tierra del ajo... No, no hay en la cristiandad pueblo más ilustre que el [15] nuestro. Sus virtudes y sus glorias llenan toda la historia patria y aun sobra algo... Vamos, veo que lo que usted tiene es sueño: buenas noches... Pues, sí, no cambiaría la gloria de ser hijo de esta noble tierra por todo el oro del mundo. _Augusta_ llamáronla los antiguos, _augustísima_ la [20] llamo yo ahora, porque ahora, como entonces, la hidalguía, la generosidad, el valor, la nobleza, son patrimonio de ella... Con que buenas noches, querido Pepe... se me figura que usted no está bueno. ¿Le ha hecho daño la cena?... Razón tiene Alonzo González de Bustamante [25] en su _Floresta amena_ al decir que los habitantes de Orbajosa bastan por sí solos para dar grandeza y honor a un reino. ¿No lo cree usted así?\"},{\"heading\":false,\"text\":\"--¡Oh! sí, señor, sin duda ninguna--repuso Pepe Rey, dirigiéndose bruscamente a su cuarto.\"},{\"heading\":false,\"text\":\"73 XI\"},{\"heading\":false,\"text\":\"=La discordia crece=\"},{\"heading\":false,\"text\":\"En los días sucesivos Rey hizo conocimiento con varias personas de la población y visitó el Casino, trabando amistades con algunos individuos de los que pasaban la vida en las salas de aquella corporación.\"},{\"heading\":false,\"text\":\"[5] Pero la juventud de Orbajosa no vivía constantemente allí, como podrá suponer la malevolencia. Veíanse por las tardes en la esquina de la catedral y en la plazoleta formada por el cruce de las calles del Condestable y la Tripería, algunos caballeros que gallardamente envueltos en sus capas [10] estaban como de centinela viendo pasar la gente. Si el tiempo era bueno, aquellas eminentes lumbreras de la cultura _urbsaugustense_ se dirigían, siempre con la indispensable capita, al titulado paseo de las Descalzas, el cual se componía de dos hileras de tísicos olmos y algunas retamas descoloridas. [15] Allí la brillante pléyade atisbaba a las niñas de D. Fulano o de D. Perencejo, que también habían ido a paseo, y la tarde se pasaba regularmente. Entrada la noche, el Casino se llenaba de nuevo, y mientras una parte de los socios entregaba su alto entendimiento a las delicias [20] del monte, los otros leían periódicos, y los más discutían en la sala del café sobre asuntos de diversa índole, como política, caballos, toros, o bien sobre chismes locales. El resumen de todos los debates era siempre la supremacía de Orbajosa y de sus habitantes sobre los demás pueblos y [25] gentes de la tierra.\"},{\"heading\":false,\"text\":\"Eran aquellos varones insignes lo más granado de la ilustre ciudad, propietarios ricos los unos, pobrísimos los otros, pero libres de altas aspiraciones todos. Tenían la imperturbable serenidad del mendigo, que nada apetece [30] mientras no le falte un mendrugo para engañar el hambre y el sol para calentarse. Lo que principalmente distinguía a 74 los orbajosenses del Casino era un sentimiento de viva hostilidad hacia todo lo que de fuera viniese. Y siempre que algún forastero de viso se presentaba en las augustas [5] salas, creíanle venido a poner en duda la superioridad de la patria del ajo, o a disputarle por envidia las preeminencias incontrovertibles que Natura le concediera.\"},{\"heading\":false,\"text\":\"Cuando Pepe Rey se presentó, recibiéronle con cierto recelo, y como en el Casino abundaba la gente graciosa, al [10] cuarto de hora de estar allí el nuevo socio, ya se habían dicho acerca de él toda suerte de cuchufletas. Cuando a las reiteradas preguntas de los socios contestó que había venido a Orbajosa con encargo de explorar la cuenca hullera del Nahara y estudiar un camino, todos convinieron en que [15] el Sr. D. José era un fatuo, que quería darse tono inventando criaderos de carbón y vías férreas. Alguno añadió:\"},{\"heading\":false,\"text\":\"--Pero en buena parte se ha metido. Estos señores sabios creen que aquí somos tontos y que se nos engaña con palabrotas... Ha venido a casarse con la niña de [20] doña Perfecta, y cuanto diga de cuencas hulleras es para echar facha.\"},{\"heading\":false,\"text\":\"--Pues esta mañana--indicó otro, que era un comerciante quebrado,--me dijeron en casa de las de Domínguez que ese señor no tiene una peseta, y viene a que su [25] tía le mantenga y a ver si puede pescar a Rosarito.\"},{\"heading\":false,\"text\":\"--Parece que ni es tal ingeniero ni cosa que lo valga--añadió un propietario de olivos, que tenía empeñadas sus fincas por el doble de lo que valían.--Pero ya se ve... Estos hambrientos de Madrid se creen autorizados para [30] engañar a los pobres provincianos, y como creen que aquí andamos con taparrabos, amigo....\"},{\"heading\":false,\"text\":\"--Bien se conoce que tiene hambre.\"},{\"heading\":false,\"text\":\"--Pues entre bromas y veras nos dijo anoche que éramos unos bárbaros holgazanes.\"},{\"heading\":false,\"text\":\"--Que vivíamos como los beduinos, tomando el sol. 75\"},{\"heading\":false,\"text\":\"--Que vivíamos con la imaginación.\"},{\"heading\":false,\"text\":\"--Eso es: que vivíamos con la imaginación.\"},{\"heading\":false,\"text\":\"--Y que esta ciudad era lo mismito que las de Marruecos.\"},{\"heading\":false,\"text\":\"[5] --Hombre, no hay paciencia para oír eso. ¿Dónde habrá visto él (como no sea en París) una calle semejante a la del Condestable, que presenta un frente de siete casas alineadas, todas magníficas, desde la de doña Perfecta a la de Nicolasito Hernández?... Se figuran estos canallas [10] que uno no ha visto nada, ni ha estado en París....\"},{\"heading\":false,\"text\":\"--También dijo con mucha delicadeza que Orbajosa era un pueblo de mendigos, y dió a entender que aquí vivimos en la mayor miseria sin darnos cuenta de ello.\"},{\"heading\":false,\"text\":\"--¡Válgame Dios! si me lo llega a decir a mí, hay un [15] escándalo en el Casino--exclamó el recaudador de contribuciones. --¿Por qué no le dijeron la cantidad de arrobas de aceite que produjo Orbajosa el año pasado? ¿No sabe ese estúpido que en años buenos Orbajosa da pan para toda España y aun para toda Europa? Verdad es que ya llevamos [20] no sé cuántos años de mala cosecha; pero eso no es ley. Pues ¿y la cosecha del ajo? ¿A que no sabe ese señor que los ajos de Orbajosa dejaron bizcos a los señores del Jurado en la Exposición de Londres?\"},{\"heading\":false,\"text\":\"Estos y otros diálogos se oían en las salas del Casino por [25] aquellos días. A pesar de estas hablillas tan comunes en los pueblos pequeños, que por lo mismo que son enanos suelen ser soberbios, Rey no dejó de encontrar amigos sinceros en la docta corporación, pues ni todos eran maldicientes ni faltaban allí personas de buen sentido. Pero [30] tenía nuestro joven la desgracia, si desgracia puede llamarse, de manifestar sus impresiones con inusitada franqueza, y esto le atrajo algunas antipatías.\"},{\"heading\":false,\"text\":\"Iban pasando días. Además del disgusto natural que las costumbres de la sociedad episcopal le producían, diversas causas todas desagradables empezaban a desarrollar en su 76 ánimo honda tristeza, siendo de notar principalmente, entre aquellas causas, la turba de pleiteantes que cual enjambre voraz se arrojó sobre él. No era sólo el tío Licurgo, sino [5] otros muchos colindantes los que le reclamaban daños y perjuicios, o bien le pedían cuentas de tierras administradas por su abuelo. También le presentaron una demanda por no sé qué contrato de aparcería que celebró su madre y no fué al parecer cumplido, y asimismo le exigieron el reconocimiento [10] de una hipoteca sobre las tierras de _Alamillos_, hecha en extraño documento por su tío. Era un hormiguero, una inmunda gusanera de pleitos. Había hecho propósito de renunciar a la propiedad de sus fincas; pero entre tanto su dignidad le obligaba a no ceder ante las [15] marrullerías de los sagaces palurdos; y como el Ayuntamiento le reclamó también por supuesta confusión de su finca con un inmediato monte de Propios, vióse el desgraciado joven en el caso de tener que disipar las dudas que acerca de su derecho surgían a cada paso. Su honra estaba [20] comprometida, y no había otro remedio que pleitear o morir.\"},{\"heading\":false,\"text\":\"Habíale prometido doña Perfecta en su magnanimidad ayudarle a salir de tan torpes líos por medio de un arreglo amistoso; pero pasaban días y los buenos oficios de la ejemplar señora no daban resultado alguno. Crecían los [25] pleitos con la amenazadora presteza de una enfermedad fulminante. Pepe Rey pasaba largas horas del día en el Juzgado dando declaraciones, contestando a preguntas y a repreguntas, y cuando se retiraba a su casa, fatigado y colérico, veía aparecer la afilada y grotesca carátula del [30] escribano, que le traía regular porción de papel sellado lleno de horribles fórmulas... para que fuese estudiando la cuestión.\"},{\"heading\":false,\"text\":\"Se comprende que aquél no era hombre a propósito para sufrir tales reveses, pudiendo evitarlos con la ausencia.\"},{\"heading\":false,\"text\":\"Representábase en su imaginación a la noble ciudad de su 77 madre como una horrible bestia que en él clavaba sus feroces uñas y le bebía la sangre. Para librarse de ella bastábale, según su creencia, la fuga; pero un interés [5] profundo, como interés del corazón, le detenía, atándole a la peña de su martirio con lazos muy fuertes. Sin embargo, llegó a sentirse tan fuera de su centro, llegó a verse tan extranjero, digámoslo así, en aquella tenebrosa ciudad de pleitos, de antiguallas, de envidia y de maledicencia, que [10] hizo propósito de abandonarla sin dilación, insistiendo al mismo tiempo en el proyecto que a ella le condujera. Una mañana, encontrando ocasión a propósito, formuló su plan ante doña Perfecta.\"},{\"heading\":false,\"text\":\"--Sobrino mío--repuso la señora con su acostumbrada [15] dulzura:--no seas arrebatado. Vaya, que pareces de fuego. Lo mismo era tu padre ¡qué hombre! Eres una centella... Ya te he dicho que con muchísimo gusto te llamaré hijo mío. Aunque no tuvieras las buenas cualidades y el talento que te distinguen (salvo los defectillos, que también [20] los hay); aunque no fueras un excelente joven, basta que esta unión haya sido propuesta por tu padre, a quien tanto debemos mi hija y yo, para que la acepte. Rosario no se opondrá tampoco, queriéndolo yo. ¿Qué falta, pues? Nada; no falta nada más que un poco tiempo. No se [25] puede hacer el casamiento con la precipitación que tú deseas, y que daría lugar a interpretaciones quizás desfavorables a la honra de mi querida hija... Vaya, que tú como no piensas más que en máquinas, todo lo quieres hacer al vapor. Espera, hombre, espera... ¿qué prisa tienes? [30] Ese aborrecimiento que le has cogido a nuestra pobre Orbajosa es un capricho. Ya se ve: no puedes vivir sino entre condes y marqueses y oradores y diplomáticos... ¡Quieres casarte y separarme de mi hija para siempre!--añadió enjugándose una lágrima.--Ya que así es, inconsiderado joven, ten al menos la caridad de retardar algún tiempo esa 78 boda que tanto deseas... ¡Qué impaciencia! ¡Qué amor tan fuerte! No creí que una pobre lugareña como mi hija inspirase pasiones tan volcánicas.\"},{\"heading\":false,\"text\":\"[5] No convencieron a Pepe Rey los razonamientos de su tía; pero no quiso contrariarla. Resolvió, pues, esperar cuanto le fuese posible. Una nueva causa de disgustos unióse bien pronto a los que ya amargaban su existencia. Hacía dos semanas que estaba en Orbajosa, y durante este tiempo no [10] había recibido ninguna carta de su padre. No podía achacarse esto a descuidos de la Administración de Correos de Orbajosa, porque siendo el funcionario encargado de aquel servicio amigo y protegido de doña Perfecta, ésta le recomendaba diariamente el mayor cuidado para que las cartas dirigidas [15] a su sobrino no se extraviasen. También iba a la casa el conductor de la correspondencia, llamado Cristóbal Ramos, y por apodo Caballuco, personaje a quien ya conocimos, y a éste solía dirigir doña Perfecta amonestaciones y reprimendas tan enérgicas como la siguiente:\"},{\"heading\":false,\"text\":\"[20] --¡Bonito servicio de correos tenéis!... ¿Cómo es que mi sobrino no ha recibido una sola carta desde que está en Orbajosa?... Cuando la conducción de la correspondencia corre a cargo de semejante tarambana, ¡cómo han de andar las cosas! Yo le hablaré al señor Gobernador de [25] la provincia para que mire bien qué clase de gente pone en la Administración.\"},{\"heading\":false,\"text\":\"Caballuco, alzando los hombros, miraba a Rey con expresión de la más completa indiferencia.\"},{\"heading\":false,\"text\":\"Un día entró con un pliego en la mano.\"},{\"heading\":false,\"text\":\"[30] --¡Gracias a Dios!--dijo doña Perfecta a su sobrino.--Ahí tienes cartas de tu padre. Regocíjate, hombre. Buen susto nos hemos llevado por la pereza de mi señor hermano en escribir... ¿Qué dice? está bueno sin duda--añadió al ver que Pepe Rey abría el pliego con febril impaciencia.\"},{\"heading\":false,\"text\":\"El ingeniero se puso pálido al recorrer las primeras 79 líneas.\"},{\"heading\":false,\"text\":\"--¡Jesús, Pepe... qué tienes!--exclamó la señora, levantándose con _zozobra_.--¿Está malo tu papá?\"},{\"heading\":false,\"text\":\"[5] --Esta carta no es de mi padre--repuso Pepe, revelando en su semblante la mayor consternación.\"},{\"heading\":false,\"text\":\"--¿Pues qué es eso?...\"},{\"heading\":false,\"text\":\"--Una orden del Ministerio de Fomento, en que se me releva del cargo que me confiaron....\"},{\"heading\":false,\"text\":\"[10] --¡Cómo... es posible!\"},{\"heading\":false,\"text\":\"--Una destitución pura y simple, redactada en términos muy poco lisonjeros para mí.\"},{\"heading\":false,\"text\":\"--¿Hase visto mayor picardía?--exclamó la señora, volviendo de su estupor.\"},{\"heading\":false,\"text\":\"[15] --¡Qué humillación!--murmuró el joven.--Es la primera vez en mi vida que recibo un desaire semejante.\"},{\"heading\":false,\"text\":\"--¡Pero ese Gobierno no tiene perdón de Dios! ¡Desairarte a ti! ¿Quieres que yo escriba a Madrid? Tengo allá muy buenas relaciones y podré conseguir que el Gobierno [20] repare esa falta brutal y te dé una satisfacción.\"},{\"heading\":false,\"text\":\"--Gracias, señora, no quiero recomendaciones--replicó el joven con displicencia.\"},{\"heading\":false,\"text\":\"--¡Es que se ven unas injusticias; unos atropellos! ...Destituir así a un joven de tanto mérito, a una eminencia [25] científica.... Vamos; si no puedo contener la cólera.\"},{\"heading\":false,\"text\":\"--Yo averiguaré--dijo Pepe, con la mayor energía,--quién se ocupa en hacerme daño....\"},{\"heading\":false,\"text\":\"--Ese señor ministro.... Pero de estos politiquejos [30] infames ¿qué se puede esperar?\"},{\"heading\":false,\"text\":\"--Aquí hay alguien que se ha propuesto hacerme morir de desesperación--afirmó el joven visiblemente alterado.--Esto no es obra del ministro, ésta y otras contrariedades que experimento son resultado de un plan de venganza, de un cálculo desconocido, de una enemistad irreconciliable, y 80 este plan, este cálculo, esta enemistad, no lo dude usted, querida tía, están aquí, en Orbajosa.\"},{\"heading\":false,\"text\":\"--Tú te has vuelto loco--replicó doña Perfecta, demostrando [5] un sentimiento semejante a la compasión.--¿Que tienes enemigos en Orbajosa? ¿Que alguien quiere vengarse de ti? Vamos, Pepillo, tú has perdido el juicio. Las lecturas de esos libros en que se dice que tenemos por abuelos a los monos o a las cotorras, te han trastornado la [10] cabeza.\"},{\"heading\":false,\"text\":\"Sonrió con dulzura al decir la última frase, y después, tomando un tono de familiar y cariñosa amonestación, añadió:\"},{\"heading\":false,\"text\":\"--Hijo mío, los habitantes de Orbajosa seremos palurdos [15] y toscos labriegos sin instrucción, sin finura, ni buen tono; pero a lealtad y buena fe no nos gana nadie, nadie, pero nadie.\"},{\"heading\":false,\"text\":\"--No crea usted--dijo el joven,--que acuso a las personas de esta casa. Pero sostengo que en la ciudad está [20] mi implacable y fiero enemigo.\"},{\"heading\":false,\"text\":\"--Deseo que me enseñes ese traidor de melodrama--repuso la señora, sonriendo de nuevo.--Supongo que no acusarás al tío Licurgo ni a los demás que te han puesto pleito, porque los pobrecitos creen defender su derecho. [25] Y entre paréntesis, no les falta razón en el caso presente. Además, el tío Lucas te quiere mucho. Así mismo me lo ha dicho. Desde que te conoció, dice que le entraste por el ojo derecho, y el pobre viejo te ha puesto un cariño....\"},{\"heading\":false,\"text\":\"--¡Sí... profundo cariño!--murmuró Pepe.\"},{\"heading\":false,\"text\":\"[30] --No seas tonto--añadió la señora, poniéndole la mano en el hombro y mirándole de cerca.--No pienses disparates, y convéncete de que tu enemigo, si existe, está en Madrid, en aquel centro de corrupción, de envidia y rivalidades, no en este pacífico y sosegado rincón, donde todo es buena voluntad y concordia... Sin duda algún envidioso de tu 81 mérito... Te advierto una cosa, y es, que si quieres ir allá para averiguar la causa de este desaire y pedir explicaciones al gobierno, no dejes de hacerlo por nosotras.\"},{\"heading\":false,\"text\":\"[5] Pepe Rey fijó los ojos en el semblante de su tía, cual si quisiera escudriñarla hasta en lo más escondido de su alma.\"},{\"heading\":false,\"text\":\"--Digo que si quieres ir, no dejes de hacerlo--repitió la señora con calma admirable, confundiéndose en la expresión de su semblante la naturalidad con la honradez [10] más pura.\"},{\"heading\":false,\"text\":\"--No, señora. No pienso ir allá.\"},{\"heading\":false,\"text\":\"--Mejor; ésa es también mi opinión. Aquí estás más tranquilo, a pesar de las cavilaciones con que te estás atormentando. ¡Pobre Pepillo! Tu entendimiento, tu descomunal [15] entendimiento, es la causa de tu desgracia. Nosotros, los de Orbajosa, pobres aldeanos rústicos, vivimos felices en nuestra ignorancia. Yo siento mucho que no estés contento. ¿Pero es culpa mía que te aburras y desesperes sin motivo? ¿No te trato como a un hijo? ¿No te [20] he recibido como la esperanza de mi casa? ¿Puedo hacer más por ti? Si a pesar de eso, no nos quieres, si nos muestras tanto despego, si te burlas de nuestra religiosidad, si haces desprecios a nuestros amigos, ¿es acaso porque no te tratemos bien?\"},{\"heading\":false,\"text\":\"[25] Los ojos de doña Perfecta se humedecieron.\"},{\"heading\":false,\"text\":\"--Querida tía--dijo Rey, sintiendo que se disipaba su encono.--También yo he cometido algunas faltas desde que soy huésped de esta casa.\"},{\"heading\":false,\"text\":\"--No seas tonto... ¡Qué faltas ni faltas! Entre [30] personas de la misma familia, todo se perdona.\"},{\"heading\":false,\"text\":\"--Pero Rosario ¿dónde está?--preguntó el joven levantándose.-- ¿Tampoco la veré hoy?\"},{\"heading\":false,\"text\":\"--Está mejor. ¿Sabes que no ha querido bajar?\"},{\"heading\":false,\"text\":\"--Subiré yo.\"},{\"heading\":false,\"text\":\"--Hombre, no. Esa niña tiene unas terquedades... Hoy 82 se ha empeñado en no salir de su cuarto. Se ha encerrado por dentro.\"},{\"heading\":false,\"text\":\"--¡Qué rareza!\"},{\"heading\":false,\"text\":\"[5] --Se le pasará. Seguramente se le pasará. Veremos si esta noche le quitamos de la cabeza sus ideas melancólicas. Organizaremos una tertulia que le divierta. ¿Por qué no te vas a casa del Sr. D. Inocencio y le dices que venga por acá esta noche y que traiga a Jacintillo?\"},{\"heading\":false,\"text\":\"[10] --¡A Jacintillo!\"},{\"heading\":false,\"text\":\"--Sí, cuando a Rosario le dan estos accesos de melancolía, ese jovencito es el único que la distrae...\"},{\"heading\":false,\"text\":\"--Pero yo subiré...\"},{\"heading\":false,\"text\":\"--Hombre, no.\"},{\"heading\":false,\"text\":\"[15] --Cuidado que hay etiqueta en esta casa.\"},{\"heading\":false,\"text\":\"--Tú te estás burlando de nosotros. Haz lo que te digo.\"},{\"heading\":false,\"text\":\"--Pues quiero verla.\"},{\"heading\":false,\"text\":\"--Pues no. ¡Qué mal conoces a la niña!\"},{\"heading\":false,\"text\":\"[20] --Yo creí conocerla bien... Bueno, me quedaré... Pero esta soledad es horrible.\"},{\"heading\":false,\"text\":\"--Ahí tienes al señor escribano.\"},{\"heading\":false,\"text\":\"--Maldito sea él mil veces.\"},{\"heading\":false,\"text\":\"[25] --Y me parece que ha entrado también el señor procurador... es un excelente sujeto.\"},{\"heading\":false,\"text\":\"--Así le ahorcaran.\"},{\"heading\":false,\"text\":\"--Hombre, los asuntos de intereses, cuando son propios, sirven de distracción. Alguien llega... Me parece que es el perito agrónomo. Ya tienes para un rato.\"},{\"heading\":false,\"text\":\"[30] --¡Para un rato de infierno!\"},{\"heading\":false,\"text\":\"--Hola, hola, si no me engaño, el tío Licurgo y el tío Pasolargo acaban de entrar. Puede que vengan a proponerte un arreglo.\"},{\"heading\":false,\"text\":\"--Me arrojaré al estanque.\"},{\"heading\":false,\"text\":\"--¡Qué descastado eres! ¡Pues todos ellos te quieren 83 tanto!... Vamos, para que nada falte, ahí está también el alguacil. Viene a citarte.\"},{\"heading\":false,\"text\":\"--A crucificarme.\"},{\"heading\":false,\"text\":\"[5] Todos los personajes nombrados fueron entrando en la sala.\"},{\"heading\":false,\"text\":\"--Adiós, Pepe, que te diviertas--dijo doña Perfecta.\"},{\"heading\":false,\"text\":\"--¡Trágame, tierra!--exclamó el joven con desesperación.\"},{\"heading\":false,\"text\":\"[10] --Sr. D. José....\"},{\"heading\":false,\"text\":\"--Mi querido Sr. D. José....\"},{\"heading\":false,\"text\":\"--Estimable Sr. D. José....\"},{\"heading\":false,\"text\":\"--Sr. D. José de mi alma....\"},{\"heading\":false,\"text\":\"--Mi respetable amigo Sr. D. José....\"},{\"heading\":false,\"text\":\"[15] Al oir estas almibaradas insinuaciones, Pepe Rey exhaló un hondo suspiro y se entregó. Entregó su cuerpo y su alma a los sayones, que esgrimieron horribles hojas de papel sellado, mientras la víctima, elevando los ojos al cielo, decía para sí con cristiana mansedumbre:\"},{\"heading\":false,\"text\":\"[20] --Padre mío, ¿por qué me has abandonado?\"}]},{\"title\":\"Capítulo XII\",\"blocks\":[{\"heading\":false,\"text\":\"=Aquí fué Troya=\"},{\"heading\":false,\"text\":\"Amor, amistad, aire sano para la respiración moral, luz para el alma, simpatía, fácil comercio de ideas y de sensaciones era lo que Pepe Rey necesitaba de una manera imperiosa. No teniéndolo, aumentaban las sombras que [25] envolvían su espíritu, y la lobreguez interior daba a su trato displicencia y amargura. Al día siguiente de las escenas referidas en el capítulo anterior, mortificóle más que nada el ya demasiado largo y misterioso encierro de su prima, motivado, al parecer, primero por una enfermedad sin importancia, después por caprichos y nerviosidades de difícil 84 explicación.\"},{\"heading\":false,\"text\":\"Rey extrañaba conducta tan contraria a la idea que había formado de Rosarito. Habían transcurrido cuatro días sin [5] verla, no ciertamente porque a él le faltasen deseos de estar a su lado; y tal situación comenzaba a ser desairada y ridícula, si con un acto de firme iniciativa no ponía remedio en ello.\"},{\"heading\":false,\"text\":\"--¿Tampoco hoy veré a mi prima?--preguntó de mal [10] talante a su tía, cuando concluyeron de comer.\"},{\"heading\":false,\"text\":\"--Tampoco. ¡Sabe Dios cuánto lo siento!... Bastante le he predicado hoy. A la tarde veremos....\"},{\"heading\":false,\"text\":\"La sospecha de que en tan injustificado encierro su adorable prima era más bien víctima sin defensa que autora [15] resuelta con actividad propia e iniciativa, le indujo a contenerse y esperar. Sin esta sospecha, hubiera partido aquel mismo día. No tenía duda alguna de ser amado por Rosario, mas era evidente que una presión desconocida actuaba entre los dos para separarlos, y parecía propio de varón [20] honrado averiguar de quién procedía aquella fuerza maligna, y contrarrestarla hasta donde alcanzara la voluntad humana.\"},{\"heading\":false,\"text\":\"--Espero que la obstinación de Rosario no durará mucho--dijo a doña Perfecta disimulando sus verdaderos sentimientos.\"},{\"heading\":false,\"text\":\"[25] Aquel día tuvo una carta de su padre, en la cual éste se quejaba de no haber recibido ninguna de Orbajosa, circunstancia que aumentó las inquietudes del ingeniero, confundiéndole más. Por último, después de vagar largo rato solo por la huerta de la casa, salió y fue al Casino. Entró en él, [30] como un desesperado que se arroja al mar.\"},{\"heading\":false,\"text\":\"Encontró en las principales salas a varias personas que charlaban y discutían. En un grupo desentrañaban con lógica sutil difíciles problemas de toros; en otro disertaban sobre cuáles eran los mejores burros entre las castas de Orbajosa y Villahorrenda. Hastiado hasta lo sumo, Pepe 85 Rey abandonó estos debates y se dirigió a la sala de periódicos, donde hojeó varias revistas sin encontrar deleite en la lectura; y poco después, pasando de sala en sala, fué a [5] parar sin saber cómo a la del juego. Cerca de dos horas estuvo en las garras del horrible demonio amarillo, cuyos resplandecientes ojos de oro producen tormento y fascinación. Ni aun las emociones del juego alteraron el sombrío estado de su alma, y el tedio que antes le empujara hacia [10] el verde tapete, apartóle también de él. Huyendo del bullicio, dió con su cuerpo en una estancia destinada a tertulia, en la cual a la sazón no había alma viviente, y con indolencia se sentó junto a la ventana de ella, mirando a la calle.\"},{\"heading\":false,\"text\":\"[15] Era ésta angostísima y con más ángulos y recodos que casas, sombreada toda por la pavorosa catedral, que al extremo alzaba su negro muro carcomido. Pepe Rey miró a todos lados, arriba y abajo, y observó un plácido silencio de sepulcro: ni un paso, ni una voz, ni una mirada. De [20] pronto hirieron su oído rumores extraños, como cuchicheo de femeniles labios, y después el chirrido de cortinajes que se corrían, algunas palabras, y por fin el tararear suave de una canción, el ladrido de un falderillo, y otras señales de existencia social que parecían muy singulares en tal sitio. [25] Observando bien, Pepe Rey vió que tales rumores procedían de un enorme balcón con celosías, que frente por frente a la ventana mostraba su corpulenta fábrica. No había concluído sus observaciones, cuando un socio del Casino apareció de súbito a su lado, y riendo le interpeló de este [30] modo:\"},{\"heading\":false,\"text\":\"--¡Ah! Sr. D. Pepe, ¡picarón! ¿se ha encerrado usted aquí para hacer cocos a las niñas?\"},{\"heading\":false,\"text\":\"El que esto decía era D. Juan Tafetán, un sujeto amabilísimo, y de los pocos que habían manifestado a Rey en el Casino cordial amistad y verdadera admiración. Con su 86 carilla bermellonada, su bigotejo teñido de negro, sus ojuelos vivarachos, su estatura mezquina, su pelo con gran estudio peinado para ocultar la calvicie, D. Juan Tafetán [5] presentaba una figura bastante diferente de la de Antinoo; pero era muy simpático, tenía mucho gracejo y felicísimo ingenio para contar aventuras graciosas. Reía mucho, y al hacerlo, su cara se cubría toda, desde la frente a la barba, de grotescas arrugas. A pesar de estas cualidades y del [10] aplauso que debía estimular su disposición a las picantes burlas, no era maldiciente. Queríanle todos, y Pepe Rey pasaba con él ratos agradables. El pobre Tafetán, empleado antaño en la Administración civil de la capital de la provincia, vivía modestamente de su sueldo en la Secretaría [15] de Beneficencia, y completaba su pasar tocando gallardamente el clarinete en las procesiones, en las solemnidades de la catedral y en el teatro, cuando alguna trailla de desesperados cómicos aparecía por aquellos países con el alevoso propósito de dar funciones en Orbajosa.\"},{\"heading\":false,\"text\":\"[20] Pero lo más singular en D. Juan Tafetán era su afición a las muchachas guapas. Él mismo, cuando no ocultaba su calvicie con seis pelos llenos de pomada, cuando no se teñía el bigote, cuande andaba derechito y espigado por la poca pesadumbre de los años, había sido un Tenorio formidable. [25] Oírle contar sus conquistas era cosa de morirse de risa, porque hay Tenorios de Tenorios, y aquél fué de los más originales.\"},{\"heading\":false,\"text\":\"--¿Qué niñas? Yo no veo niñas en ninguna parte--repuso Pepe Rey.\"},{\"heading\":false,\"text\":\"[30] --Hágase usted el anacoreta.\"},{\"heading\":false,\"text\":\"Una de las celosías del balcón se abrió, dejando ver un rostro juvenil, encantador y risueño, que desapareció al instante como una luz apagada por el viento.\"},{\"heading\":false,\"text\":\"--Ya, ya veo.\"},{\"heading\":false,\"text\":\"--¿No las conoce usted? 87\"},{\"heading\":false,\"text\":\"--Por mi vida que no.\"},{\"heading\":false,\"text\":\"--Son las Troyas, las niñas de Troya. Pues no conoce usted nada bueno... Tres chicas preciosísimas, hijas de [5] un coronel de Estado Mayor de Plazas, que murió en las calles de Madrid el 54.\"},{\"heading\":false,\"text\":\"La celosía se abrió de nuevo y comparecieron dos caras.\"},{\"heading\":false,\"text\":\"--Se están burlando de nosotros--dijo Tafetán haciendo una seña amistosa a las niñas.\"},{\"heading\":false,\"text\":\"[10] --¿Las conoce usted?\"},{\"heading\":false,\"text\":\"--¿Pues no las he de conocer? Las pobres están en la miseria. Yo no sé cómo viven. Cuando murió D. Francisco Troya, se hizo una suscripción para mantenerlas; pero esto duró poco.\"},{\"heading\":false,\"text\":\"[15] --¡Pobres muchachas! Me figuro que no serán un modelo de honradez....\"},{\"heading\":false,\"text\":\"--¿Por qué no?... Yo no creo lo que en el pueblo se dice de ellas.\"},{\"heading\":false,\"text\":\"Funcionó de nuevo la celosía.\"},{\"heading\":false,\"text\":\"[20] --Buenas tardes, niñas--gritó D. Juan Tafetán dirigiéndose a las tres, que artísticamente agrupadas aparecieron.--Este caballero dice que lo bueno no debe esconderse, y que abran ustedes toda la celosía.\"},{\"heading\":false,\"text\":\"Pero la celosía se cerró y alegre concierto de risas difundió [25] una extraña alegría por la triste calle. Creeríase que pasaba una bandada de pájaros.\"},{\"heading\":false,\"text\":\"--¿Quiere usted que vayamos allá?--dijo de súbito Tafetán.\"},{\"heading\":false,\"text\":\"Sus ojos brillaban, y una sonrisa picaresca retozaba en [30] sus amoratados labios.\"},{\"heading\":false,\"text\":\"--¿Pero qué clase de gente es esa?\"},{\"heading\":false,\"text\":\"--Ande usted, Sr. de Rey... Las pobrecitas son honradas. ¡Bah! Si se alimentan del aire como los camaleones. Diga usted, el que no come, ¿puede pecar?\"},{\"heading\":false,\"text\":\"Bastante virtuosas son las infelices. Y si pecaran, limpiarían 88 su conciencia con el gran ayuno que hacen.\"},{\"heading\":false,\"text\":\"--Pues vamos.\"},{\"heading\":false,\"text\":\"Un momento después, D. Juan Tafetán y Pepe Rey [5] entraban en la sala. El aspecto de la miseria, que con horribles esfuerzos pugnaba por no serlo, afligió al joven. Las tres muchachas eran muy lindas, principalmente las dos más pequeñas, morenas, pálidas, de negros ojos y sutil talle. Bien vestidas y bien calzadas, habrían parecido [10] retoños de duquesa en candidatura para entroncar con príncipes.\"},{\"heading\":false,\"text\":\"Cuando la visita entró, las tres se quedaron muy cortadas; pero bien pronto mostraron la índole de su genial frívolo y alegre. Vivían en la miseria, como los pájaros en la prisión, [15] sin dejar de cantar tras los hierros lo mismo que en la opulencia del bosque. Pasaban el día cosiendo, lo cual indicaba por lo menos un principio de honradez; pero en Orbajosa ninguna persona de su posición se trataba con ellas. Estaban hasta cierto punto proscritas, degradadas, [20] acordonadas, lo cual indicaba también algún motivo de escándalo. Pero en honor de la verdad, debe decirse que la mala reputación de las Troyas consistía, más que nada, en su fama de chismosas, enredadoras, traviesas y despreocupadas. Dirigían anónimos a graves personas; ponían [25] motes a todo viviente de Orbajosa, desde el obispo al último zascandil; tiraban piedrecitas a los transeuntes; chicheaban escondidas tras las rejas para reírse con la confusión y azoramiento del que pasaba; sabían todos los sucesos de la vecindad, para lo cual tenían en constante uso los tragaluces [30] y agujeros todos de la parte alta de la casa; cantaban de noche en el balcón; se vestían de máscara en Carnaval para meterse en las casas más alcurniadas, con otras majaderías y libertades propias de los pueblos pequeños. Pero cualquiera que fuese la razón, ello es que el graciado triunvirato Troyano tenía sobre sí un estigma de esos que una 89 vez puestos por susceptible vecindario, acompañan implacablemente hasta más allá de la tumba.\"},{\"heading\":false,\"text\":\"--¿Éste es el caballero que dicen ha venido a sacar [5] minas de oro?--dijo una.\"},{\"heading\":false,\"text\":\"--¿Y a derribar la catedral para hacer con las piedras de ella una fábrica de zapatos?--añadió otra.\"},{\"heading\":false,\"text\":\"--Y a quitar de Orbajosa la siembra del ajo para poner algodón o el árbol de la canela.\"},{\"heading\":false,\"text\":\"[10] Pepe no pudo reprimir la risa ante tales despropósitos.\"},{\"heading\":false,\"text\":\"--No viene sino a hacer una recolección de niñas bonitas para llevárselas a Madrid--dijo Tafetán.\"},{\"heading\":false,\"text\":\"--¡Ay! ¡De buena gana me iría!--exclamó una.\"},{\"heading\":false,\"text\":\"--A las tres, a las tres me las llevo--afirmó Pepe.--Pero [15] sepamos una cosa; ¿por qué se reían ustedes de mí cuando estaba en la ventana del Casino?\"},{\"heading\":false,\"text\":\"Tales palabras fueron la señal de nuevas risas.\"},{\"heading\":false,\"text\":\"--Éstas son unas tontas--dijo la mayor.\"},{\"heading\":false,\"text\":\"--Fué porque dijimos que usted se merece algo más que [20] la niña de doña Perfecta.\"},{\"heading\":false,\"text\":\"--Fué porque ésta dijo que usted está perdiendo el tiempo y que Rosarito no quiere sino gente de iglesia.\"},{\"heading\":false,\"text\":\"--¡Qué cosas tienes! Yo no he dicho tal cosa. Tú dijiste que este caballero es ateo luterano, y entra en la [25] catedral fumando y con el sombrero puesto.\"},{\"heading\":false,\"text\":\"--Pues yo no lo inventé--manifestó la menor,--que eso me lo dijo ayer Suspiritos.\"},{\"heading\":false,\"text\":\"--¿Y quién es esa Suspiritos que dice de mí tales tonterías?\"},{\"heading\":false,\"text\":\"[30] --Suspiritos es... Suspiritos.\"},{\"heading\":false,\"text\":\"--Niñas mías--dijo Tafetán con semblante almibarado. Por ahí va el naranjero. Llamadle, que os quiero convidar a naranjas.\"},{\"heading\":false,\"text\":\"Una de las tres llamó al naranjero.\"},{\"heading\":false,\"text\":\"La conversación entablada por las niñas desagradó bastante 90 a Pepe Rey, disipando la ligera impresión de contento que experimentó al encontrarse entre aquella chusma alegre y comunicativa. No pudo, sin embargo, contener [5] la risa cuando vió a D. Juan Tafetán descolgar un guitarrillo y rasguearlo con la gracia y destreza de los años juveniles.\"},{\"heading\":false,\"text\":\"--Me han dicho que ustedes saben cantar a las mil maravillas--manifestó Rey.\"},{\"heading\":false,\"text\":\"[10] --Que cante D. Juan Tafetán.\"},{\"heading\":false,\"text\":\"--Yo no canto.\"},{\"heading\":false,\"text\":\"--Ni yo--dijo la segunda, ofreciendo al ingeniero algunos cascos de la naranja que acababa de mondar.\"},{\"heading\":false,\"text\":\"--María Juana, no abandones la costura--dijo la Troya [15] mayor.--Es tarde y hay que acabar la sotana esta noche.\"},{\"heading\":false,\"text\":\"--Hoy no se trabaja. Al demonio las agujas--exclamó Tafetán.\"},{\"heading\":false,\"text\":\"En seguida entonó una canción.\"},{\"heading\":false,\"text\":\"[20] --La gente se para en la calle--dijo la Troya segunda asomándose al balcón.--Los gritos de D. Juan Tafetán se oyen desde la plaza... ¡Juana, Juana!\"},{\"heading\":false,\"text\":\"--¿Qué?\"},{\"heading\":false,\"text\":\"--Por la calle va Suspiritos.\"},{\"heading\":false,\"text\":\"[25] La más pequeña voló al balcón.\"},{\"heading\":false,\"text\":\"--Tírale una cascara de naranja.\"},{\"heading\":false,\"text\":\"Pepe Rey se asomó también; vió que por la calle pasaba una señora, y que con diestra puntería la menor de las Troyas le asestó un cascarazo en el moño. Después [30] cerraron precipitadamente, y las tres se esforzaban en sofocar convulsamente su risa para que no se oyera desde la vía pública.\"},{\"heading\":false,\"text\":\"--Hoy no se trabaja--gritó una volcando de un puntapié la cesta de la costura.\"},{\"heading\":false,\"text\":\"--Es lo mismo que decir, \\\"mañana no se come\\\"--añadió 91 la mayor, recogiendo los enseres.\"},{\"heading\":false,\"text\":\"Pepe Rey se echó instintivamente mano al bolsillo. De buena gana les hubiera dado una limosna. El espectáculo [5] de aquellas infelices huérfanas, condenadas por el mundo a causa de su frivolidad, le entristecía sobre manera. Si el único pecado de las Troyas, si el único desahogo con que compensaban su soledad, su pobreza y abandono, era tirar cortezas de naranja al transeunte, bien se las podía disculpar. [10] Quizás las austeras costumbres del poblachón en que vivían las había preservado del vicio; pero las desgraciadas carecían de compostura y comedimiento, fórmula común y más visible del pudor, y bien podía suponerse que habían echado por la ventana algo más que cáscaras. Pepe Rey sentía [15] hacia ellas una lástima profunda. Observó sus miserables vestidos, compuestos, arreglados y remendados de mil modos para que pareciesen nuevos, observó sus zapatos rotos... y otra vez se llevó la mano al bolsillo.\"},{\"heading\":false,\"text\":\"--Podrá el vicio reinar aquí--dijo para sí;--pero las [20] fisonomías, los muebles, todo me indica que estos son los infelices restos de una familia honrada. Si estas pobres muchachas fueran tan malas como dicen, no vivirían tan pobremente ni trabajarían. ¡En Orbajosa hay hombres ricos!\"},{\"heading\":false,\"text\":\"[25] Las tres niñas se le acercaban sucesivamente. Iban de él al balcón, del balcón a él, sosteniendo conversación picante y ligera, que indicaba, fuerza es decirlo, una especie de inocencia en medio de tanta frivolidad y despreocupación.\"},{\"heading\":false,\"text\":\"[30] --Sr. D. José, ¡qué excelente señora es doña Perfecta!\"},{\"heading\":false,\"text\":\"--Es la única persona de Orbajosa que no tiene apodo, la única persona de que no se habla mal en Orbajosa.\"},{\"heading\":false,\"text\":\"--Todos la respetan.\"},{\"heading\":false,\"text\":\"--Todos la adoran.\"},{\"heading\":false,\"text\":\"A estas frases el joven respondía con alabanzas de su 92 tía; pero se le pasaban ganas de sacar dinero del bolsillo y decir: \\\"María Juana, tome usted para unas botas. Pepa, tome usted para que se compre un vestido. Florentina, [5] tome usted para que coman una semana....\\\" Estuvo a punto de hacerlo como lo pensaba. En un momento en que las tres corrieron al balcón para ver quién pasaba, don Juan Tafetán se acercó a él y en voz baja le dijo:\"},{\"heading\":false,\"text\":\"--¡Qué monas son! ¿No es verdad?... ¡Pobres [10] criaturas! Parece mentira que sean tan alegres, cuando... bien puede asegurarse que hoy no han comido.\"},{\"heading\":false,\"text\":\"--Don Juan, D. Juan--gritó Pepilla.--Por ahí viene su amigo de usted Nicolasito Hernández, o sea _Cirio Pascual_, con su sombrero de tres pisos. Viene rezando en voz baja, [15] sin duda por las almas de los que ha mandado al hoyo con sus usuras.\"},{\"heading\":false,\"text\":\"--¿A que no le dicen ustedes el remoquete?\"},{\"heading\":false,\"text\":\"--¡A que sí!\"},{\"heading\":false,\"text\":\"--Juana, cierra las celosías. Dejémosle que pase, y [20] cuando vaya por la esquina, yo gritaré: _¡Cirio, Cirio Pascual_!...\"},{\"heading\":false,\"text\":\"Don Juan Tafetán corrió al balcón.\"},{\"heading\":false,\"text\":\"--Venga usted, D. José, para que conozca este tipo.\"},{\"heading\":false,\"text\":\"Pepe Rey aprovechó el momento en que las tres muchachas [25] y D. Juan se regocijaban en el balcón, llamando a Nicolasito Hernández con el apodo que tanto le hacía rabiar, y acercándose con toda cautela a uno de los costureros que en la sala había, colocó dentro de él media onza que le quedaba del juego.\"},{\"heading\":false,\"text\":\"[30] Después corrió al balcón, a punto que las dos más pequeñas gritaban entre locas risas: _¡Cirio Pascual, Cirio Pascual!_\"},{\"heading\":false,\"text\":\"93\"}]},{\"title\":\"Capítulo XIII\",\"blocks\":[{\"heading\":false,\"text\":\"=Un casus belli=\"},{\"heading\":false,\"text\":\"Después de esta travesura, las tres entablaron con los dos caballeros una conversación tirada sobre asuntos y personas de la ciudad. El ingeniero, recelando que su fechoría se descubriese, estando él presente, quiso marcharse, lo cual [5] disgustó mucho a las Troyas; una de éstas que había salido fuera de la sala, regresó diciendo:\"},{\"heading\":false,\"text\":\"--Ya está Suspiritos en campaña colgando la ropa.\"},{\"heading\":false,\"text\":\"--Don José querrá verla--indicó otra.\"},{\"heading\":false,\"text\":\"--Es una señora muy guapa. Y ahora se peina a estilo [10] de Madrid. Vengan ustedes.\"},{\"heading\":false,\"text\":\"Lleváronles al comedor de la casa (pieza de rarísimo uso), del cual se salía a un terrado, donde había algunos tiestos de flores y no pocos trastos abandonados y hechos pedazos. Desde allí veíase el hondo patio de una casa colindante, [15] con una galería llena de verdes enredaderas y hermosas macetas esmeradamente cuidadas. Todo indicaba allí una vivienda de gente modesta, pulcra y hacendosa.\"},{\"heading\":false,\"text\":\"Las de Troya, acercándose al bordo de la azotea, miraron atentamente a la casa vecina, e imponiendo silencio a los [20] galanes, se retiraron luego a aquella parte del terrado, desde donde nada se veía ni había peligro de ser visto.\"},{\"heading\":false,\"text\":\"--Ahora sale de la despensa con un cazuelo de garbanzos--dijo María Juana, estirando el cuello para ver un poco.\"},{\"heading\":false,\"text\":\"[25] --¡Zás!--exclamó otra, arrojando una piedrecilla.\"},{\"heading\":false,\"text\":\"Oyóse el ruido del proyectil al chocar contra los cristales de la galería, y luego una colérica voz que gritaba:\"},{\"heading\":false,\"text\":\"--Ya nos han roto otro cristal ésas....\"},{\"heading\":false,\"text\":\"Ocultas las tres en el rincón del terrado, junto a los dos [30] caballeros, sofocaban la risa.\"},{\"heading\":false,\"text\":\"--La señora Suspiritos está muy incomodada--dijo 94 Rey.--¿Por qué la llaman así?\"},{\"heading\":false,\"text\":\"--Porque siempre que habla suspira entre palabra y palabra, y aunque de nada carece siempre se está [5] lamentando.\"},{\"heading\":false,\"text\":\"Hubo un momento de silencio en la casa de abajo. Pepita Troya atisbó con cautela.\"},{\"heading\":false,\"text\":\"--Allá viene otra vez--murmuró en voz baja, imponiendo silencio.--María, dame una china. A ver... ¡zás!... [10] allá va.\"},{\"heading\":false,\"text\":\"--No la has acertado. Dió en el suelo.\"},{\"heading\":false,\"text\":\"--A ver si yo puedo... Esperaremos a que salga otra vez de la despensa.\"},{\"heading\":false,\"text\":\"--Ya, ya sale. En guardia, Florentina.\"},{\"heading\":false,\"text\":\"[15] --¡A la una, a las dos, a las tres!... ¡Paf!...\"},{\"heading\":false,\"text\":\"Oyóse abajo un grito de dolor, un voto, una exclamación varonil, pues era un hombre el que la daba. Pepe Rey pudo distinguir claramente estas palabras:\"},{\"heading\":false,\"text\":\"--¡Demonche! Me han agujereado la cabeza ésas... [20] ¡Jacinto, Jacinto! ¿Pero qué canalla de vecindad es esta?...\"},{\"heading\":false,\"text\":\"--¡Jesús, María y José, lo que he hecho!--exclamó llena de consternación Florentina,--le he dado en la cabeza al Sr. D. Inocencio.\"},{\"heading\":false,\"text\":\"[25] --¿Al Penitenciario?--dijo Pepe Rey.\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Vive en esa casa?\"},{\"heading\":false,\"text\":\"--¿Pues dónde ha de vivir?\"},{\"heading\":false,\"text\":\"--Esa señora de los suspiros....\"},{\"heading\":false,\"text\":\"[30] --Es su sobrina, su ama o no sé qué. Nos divertimos con ella porque es muy cargante, pero con el señor Penitenciario no solemos gastar bromas.\"},{\"heading\":false,\"text\":\"Mientras rápidamente se pronunciaban las palabras de este diálogo, Pepe Rey vió que frente al terrado, y muy cerca de él, se abrían los cristales de una ventana perteneciente a la misma casa bombardeada; vió que aparecía 95 une cara risueña, una cara conocida, una cara cuya vista le aturdió y le consternó y le puso pálido y trémulo. Era [5] Jacintito, que interrumpido en sus graves estudios, abrió la ventana de su despacho, presentándose en ella con la pluma en la oreja. Su rostro púdico, fresco y sonrosado daba a tal aparición aspecto semejante al de una aurora.\"},{\"heading\":false,\"text\":\"[10] --Buenas tardes, Sr. D. José--dijo festivamente. La voz de abajo gritaba de nuevo:\"},{\"heading\":false,\"text\":\"--¡Jacinto, pero Jacinto!\"},{\"heading\":false,\"text\":\"--Allá voy. Estaba saludando a un amigo....\"},{\"heading\":false,\"text\":\"--Vámonos, vámonos--gritó Florentina con zozobra.--El [15] señor Penitenciario va a subir al cuarto de _D. Nominavito_ y nos echará un responso.\"},{\"heading\":false,\"text\":\"--Vámonos, sí; cerremos la puerta del comedor.\"},{\"heading\":false,\"text\":\"Abandonaron en tropel el terrado.\"},{\"heading\":false,\"text\":\"--Debieron ustedes prever que Jacinto las vería desde [20] su templo del saber--dijo Tafetán.\"},{\"heading\":false,\"text\":\"--_Don Nominavito_ es amigo nuestro--repuso una de ellas.--Desde su templo de la ciencia nos dice a la calladita mil ternezas, y también nos echa besos volados.\"},{\"heading\":false,\"text\":\"--¿Jacinto?--preguntó el ingeniero,--¿qué endiablado [25] nombre le han puesto ustedes?\"},{\"heading\":false,\"text\":\"--_Don Nominavito_....\"},{\"heading\":false,\"text\":\"Las tres rompieron a reír.\"},{\"heading\":false,\"text\":\"--Lo llamamos así porque es muy sabio.\"},{\"heading\":false,\"text\":\"--No: porque cuando nosotras éramos chicas, él era [30] chico también; pues... sí. Salíamos al terrado a jugar, y le sentíamos estudiando en voz alta sus lecciones.\"},{\"heading\":false,\"text\":\"--Sí, y todo el santo día estaba cantando.\"},{\"heading\":false,\"text\":\"--Declinando, mujer. Eso es: se ponía de este modo: _Nominavito rosa, Genivito, Davito, Acusavito_.\"},{\"heading\":false,\"text\":\"--Supongo que yo también tendré mi nombre postizo--dijo 96 Pepe Rey.\"},{\"heading\":false,\"text\":\"--Que se lo diga a usted María Juana--replicó Florentina ocultándose.\"},{\"heading\":false,\"text\":\"[5] --¿Yo?... díselo tú, Pepa.\"},{\"heading\":false,\"text\":\"--Usted no tiene nombre todavía, D. José.\"},{\"heading\":false,\"text\":\"--Pero lo tendré. Prometo que vendré a saberlo, a recibir la confirmación--dijo el joven con intención de retirarse.\"},{\"heading\":false,\"text\":\"[10] --¿Pero se va usted?\"},{\"heading\":false,\"text\":\"--Sí. Ya han perdido ustedes bastante tiempo. Niñas, a trabajar. Esto de arrojar piedras a los vecinos y a los transeuntes, no es la ocupación más a propósito para unas jóvenes tan lindas y de tanto mérito... Con que abur....\"},{\"heading\":false,\"text\":\"[15] Y sin esperar más razones ni hacer caso de los cumplidos de las muchachas, salió a toda prisa de la casa, dejando en ella a don Juan Tafetán.\"},{\"heading\":false,\"text\":\"La escena que había presenciado; la vejación sufrida por [20] el canónigo; la inopinada aparición del doctorcillo, aumentaron las confusiones, recelos y presentimientos desagradables que turbaban el alma del pobre ingeniero. Deploró con toda su alma haber entrado en casa de las Troyas, y resuelto a emplear mejor el tiempo, mientras su hipocondría le durase, recorrió las calles de la población.\"},{\"heading\":false,\"text\":\"[25] Visitó el mercado, la calle de la Tripería, donde estaban las principales tiendas; observó los diversos aspectos que ofrecían la industria y comercio de la gran Orbajosa, y como no hallara sino nuevos motivos de aburrimiento, encaminóse al paseo de las Descalzas; pero no vió en él [30] más que algunos perros vagabundos, porque con motivo del viento molestísimo que reinaba, caballeros y señoras se habían quedado en sus casas. Fué a la botica, donde hacían tertulia diversas especies de progresistas rumiantes, que estaban perpetuamente masticando un tema sin fin; pero allí se aburrió más. Pasaba al fin junto a la catedral, 97 cuando sintió el órgano y los hermosos cantos del coro. Entró, arrodillóse delante del altar mayor, recordando las advertencias que acerca de la compostura dentro de la [5] iglesia le hiciera su tía; visitó luego una capilla, y se disponía a entrar en otra, cuando un acólito, celador o perrero se le acercó, y con modales muy descorteses y descompuesto lenguaje, le habló así:\"},{\"heading\":false,\"text\":\"--Su Ilustrísima dice que se plante usted en la calle.\"},{\"heading\":false,\"text\":\"[10] El ingeniero sintió que la sangre se agolpaba en su cerebro. Sin decir una palabra obedeció. Arrojado de todas partes por fuerza superior o por su propio hastío, no tenía más recurso que ir a casa de su tía, donde le esperaban:\"},{\"heading\":false,\"text\":\"1.° El tío Licurgo, para anunciarle un segundo pleito. [15] 2.° El Sr. D. Cayetano, para leerle un nuevo trozo de su discurso sobre los linajes de Orbajosa. 3.° Caballuco, para un asunto que no había manifestado. 4.° Doña Perfecta y su sonrisa bondadosa, para lo que se verá en el capítulo siguiente.\"}]},{\"title\":\"Capítulo XIV\",\"blocks\":[{\"heading\":false,\"text\":\"=La discordia sigue creciendo=\"},{\"heading\":false,\"text\":\"[20] Una nueva tentativa de ver a su prima Rosario fracasó al caer de la tarde. Pepe Rey se encerró en su cuarto para escribir varias cartas, y no podía apartar de su mente una idea fija.\"},{\"heading\":false,\"text\":\"--Esta noche o mañana--decía,--se acabará esto de [25] una manera o de otra.\"},{\"heading\":false,\"text\":\"Cuando le llamaron para la cena, doña Perfecta se dirigió a él en el comedor, diciéndole de buenas a primeras:\"},{\"heading\":false,\"text\":\"--Querido Pepe, no te apures, yo aplacaré al Sr. D. Inocencio... Ya estoy enterada. María Remedios, que [30] acaba de salir de aquí, me lo ha contado todo.\"},{\"heading\":false,\"text\":\"El semblante de la señora irradiaba satisfacción, semejante 98 a la de un artista orgulloso de su obra.\"},{\"heading\":false,\"text\":\"--¿Qué?\"},{\"heading\":false,\"text\":\"--Yo te disculparé, hombre. Tomarías algunas copas [5] en el Casino, ¿no es esto? He aquí el resultado de las malas compañías. ¡D. Juan Tafetán, las Troyas!... Esto es horrible, espantoso. ¿Has meditado bien?...\"},{\"heading\":false,\"text\":\"--Todo lo he meditado, señora--repuso Pepe, decidido a no entrar en discusiones con su tía.\"},{\"heading\":false,\"text\":\"[10] --Me guardaré muy bien de escribirle a tu padre lo que has hecho.\"},{\"heading\":false,\"text\":\"--Puede usted escribirle lo que guste.\"},{\"heading\":false,\"text\":\"--Vamos: te defenderás desmintiéndome.\"},{\"heading\":false,\"text\":\"--Yo no desmiento.\"},{\"heading\":false,\"text\":\"[15] --Luégo confiesas que estuviste en casa de esas....\"},{\"heading\":false,\"text\":\"--Estuve.\"},{\"heading\":false,\"text\":\"--Y que les diste media onza, porque, según me ha dicho María Remedios, esta tarde bajó Florentina a la tienda del extremeño a que le cambiaran media onza. Ellas no podían [20] haberla ganado con su costura. Tú estuviste hoy en casa de ellas; luégo....\"},{\"heading\":false,\"text\":\"--Luégo yo se la di. Perfectamente.\"},{\"heading\":false,\"text\":\"--¿No lo niegas?\"},{\"heading\":false,\"text\":\"--¡Qué he de negarlo! Creo que puedo hacer de mi [25] dinero lo que mejor me convenga.\"},{\"heading\":false,\"text\":\"--Pero de seguro sostendrás que no apedreaste al señor Penitenciario.\"},{\"heading\":false,\"text\":\"--Yo no apedreo.\"},{\"heading\":false,\"text\":\"--Quiero decir que ellas en presencia tuya....\"},{\"heading\":false,\"text\":\"[30] --Eso es otra cosa.\"},{\"heading\":false,\"text\":\"--E insultaron a la pobre María Remedios.\"},{\"heading\":false,\"text\":\"--Tampoco lo niego.\"},{\"heading\":false,\"text\":\"--¿Y cómo justificarás tu conducta? Pepe... por Dios.--No dices nada; no te arrepientes, no protestas... no....\"},{\"heading\":false,\"text\":\"--Nada, absolutamente nada, señora. 99\"},{\"heading\":false,\"text\":\"--Ni siquiera procuras desagraviarme.\"},{\"heading\":false,\"text\":\"--Yo no he agraviado a usted....\"},{\"heading\":false,\"text\":\"--- Vamos, ya no te falta más que... Hombre, coge [5] ese palo y pégame.\"},{\"heading\":false,\"text\":\"--Yo no pego.\"},{\"heading\":false,\"text\":\"--¡Qué falta de respeto! ¡qué!... ¿No cenas?\"},{\"heading\":false,\"text\":\"--Cenaré.\"},{\"heading\":false,\"text\":\"Hubo una pausa de más de un cuarto de hora. D. Cayetano, [10] doña Perfecta y Pepe Rey comían en silencio. Éste se interrumpió cuando D. Inocencio entró en el comedor.\"},{\"heading\":false,\"text\":\"--¡Cuánto lo he sentido, Sr. D. José de mi alma!... Créame usted que lo he sentido de veras--dijo estrechando la mano al joven y mirándole con expresión de lástima.\"},{\"heading\":false,\"text\":\"[15] El ingeniero no supo qué contestar; tanta era su confusión.\"},{\"heading\":false,\"text\":\"--Me refiero al suceso de esta tarde.\"},{\"heading\":false,\"text\":\"--¡Ah!... ya.\"},{\"heading\":false,\"text\":\"--A la expulsión de usted del sagrado recinto de la [20] iglesia catedral.\"},{\"heading\":false,\"text\":\"--El señor obispo--dijo Pepe Rey,--debía pensarlo mucho antes de arrojar a un cristiano de la iglesia.\"},{\"heading\":false,\"text\":\"--Y es verdad, yo no sé quién le ha metido en la cabeza a Su Ilustrísima que usted es hombre de malísimas costumbres; [25] yo no sé quién le ha dicho que usted hace alarde de ateísmo en todas partes; que se burla de las cosas y personas sagradas, y aun que proyecta derribar la catedral para edificar con sus piedras una gran fábrica de alquitrán. Yo he procurado disuadirle; pero Su Ilustrísima es un poco [30] terco.\"},{\"heading\":false,\"text\":\"--Gracias por tanta bondad.\"},{\"heading\":false,\"text\":\"--Y eso que el señor Penitenciario no tiene motivos para guardarte tales consideraciones. Por poco más le dejan en el sitio esta tarde.\"},{\"heading\":false,\"text\":\"--¡Bah!... ¿pues qué?--dijo el sacerdote riendo.--¿Ya 100 se tiene aquí noticia de la travesurilla?... Apuesto a que María Remedios vino con el cuento. Pues se lo prohibí, se lo prohibí de un modo terminante. La cosa en [5] sí no vale la pena, ¿no es verdad, Sr. de Rey?\"},{\"heading\":false,\"text\":\"--Puesto que usted lo juzga así....\"},{\"heading\":false,\"text\":\"--Ése es mi parecer. Cosas de muchachos... La juventud, digan lo que quieran los modernos, se inclina al vicio y a las acciones viciosas. El Sr. D. José, que es una persona de grandes prendas, no podía ser perfecto... ¿qué tiene de particular que esas graciosas niñas le sedujeran, y después de sacarle el dinero le hicieran cómplice de sus desvergonzados y criminales insultos a la vecindad? Querido amigo mío, por la dolorosa parte que me cupo en [15] los juegos de esta tarde--añadió, llevándose la mano a la región lastimada,--no me doy por ofendido, ni siquiera mortificaré a usted con recuerdos de tan desagradable incidente. He sentido verdadera pena al saber que María Remedios había venido a contarlo todo... Es tan chismosa [20] mi sobrina... Apostamos a que también contó lo de la media onza, y los retozos de usted con las niñas en el tejado, y las carreras y pellizcos, y el bailoteo de D. Juan Tafetán... ¡Bah! estas cosas debieran quedarse en secreto.\"},{\"heading\":false,\"text\":\"[25] Pepe Rey no sabía lo que le mortificaba más, si la severidad de su tía o las hipócritas condescendencias del canónigo.\"},{\"heading\":false,\"text\":\"--¿Por qué no se han de decir?--indicó la señora.--Él mismo no parece avergonzado de su conducta. Sépanlo [30] todos. Únicamente se guardará secreto de esto a mi querida hija, porque en su estado nervioso son temibles los accesos de cólera.\"},{\"heading\":false,\"text\":\"--Vamos, que no es para tanto, señora--añadió el Penitenciario.--Mi opinión es que no se vuelva a hablar del asunto, y cuando esto lo dice el que recibió la pedrada, los 101 demás pueden darse por satisfechos... Y no fué broma lo del trastazo, Sr. D. José, pues creí que me abrían un boquete en el casco y que se me salían por él los sesos....\"},{\"heading\":false,\"text\":\"[5] --¡Cuánto siento este incidente!...--balbució Pepe Rey.--Me causa verdadera pena, a pesar de no haber tomado parte....\"},{\"heading\":false,\"text\":\"--La visita de usted a esas señoras Troyas llamará la atención en el pueblo--dijo el canónigo.--Aquí no estamos [10] en Madrid, señores, aquí no estamos en ese centro de corrupción, de escándalo....\"},{\"heading\":false,\"text\":\"--Allá puedes visitar los lugares más inmundos--manifestó doña Perfecta,--sin que nadie lo sepa.\"},{\"heading\":false,\"text\":\"--Aquí nos miramos mucho--prosiguió D. Inocencio.--Reparamos [15] todo lo que hacen los vecinos, y con tal sistema de vigilancia, la moral pública se sostiene a conveniente altura... Créame usted, amigo mío, créame usted, y no digo esto por mortificarle; usted ha sido el primer caballero de su posición que a la luz del día... el primero, sí señor [20] ... _Trojae qui primus ab oris_.\"},{\"heading\":false,\"text\":\"Después se echó a reír, dando algunas palmadas en la espalda al ingeniero en señal de amistad y benevolencia.\"},{\"heading\":false,\"text\":\"--¡Cuán grato es para mí--dijo el joven, encubriendo su cólera con las palabras que creyó más propias para contestar [25] a la solapada ironía de sus interlocutores,--ver tanta generosidad y tolerancia, cuando yo merecía por mi criminal proceder!....\"},{\"heading\":false,\"text\":\"--¿Pues qué? A un individuo que es de nuestra propia sangre y que lleva nuestro mismo nombre--dijo doña Perfecta,--¿se [30] le puede tratar como a un cualquiera? Eres mi sobrino, eres hijo del mejor y más santo de los hombres, mi querido hermano Juan, y esto basta. Ayer tarde estuvo aquí el secretario del señor obispo, a manifestarme que Su Ilustrísima está muy disgustado porque te tengo en mi casa.\"},{\"heading\":false,\"text\":\"--¿También eso?--murmuró el canónigo. 102\"},{\"heading\":false,\"text\":\"--También eso. Yo dije que, salvo el respeto que el señor obispo me merece y lo mucho que le quiero y reverencio, mi sobrino es mi sobrino, y no puedo echarle de mi [5] casa.\"},{\"heading\":false,\"text\":\"--Es una nueva singularidad que encuentro en este país--dijo Pepe Rey, pálido de ira.--Por lo visto, aquí el obispo gobierna las casas ajenas.\"},{\"heading\":false,\"text\":\"--Él es un bendito. Me quiere tanto, que se le figura [10] ... se le figura que nos vas a comunicar tu ateísmo, tu despreocupación, tus raras ideas... Yo le he dicho repetidas veces que tienes un fondo excelente.\"},{\"heading\":false,\"text\":\"--Al talento superior debe siempre concedérsele algo--manifestó D. Inocencio.\"},{\"heading\":false,\"text\":\"[15] --Y esta mañana, cuando estuve en casa de las de Cirujeda, ¡ay! tú no puedes figurarte cómo me pusieron la cabeza... Que si habías venido a derribar la catedral; que si eras comisionado de los protestantes ingleses para ir predicando la herejía por España; que pasabas la noche [20] entera jugando en el Casino; que salías borracho... \\\"Pero señoras--les dije,--¿quieren ustedes que yo envíe a mi sobrino a la posada?\\\" Además, en lo de las embriagueces no tienen razón, y en cuanto al juego, no sé que jugaras hasta hoy.\"},{\"heading\":false,\"text\":\"[25] Pepe Rey se hallaba en esa situación de ánimo en que el hombre más prudente siente dentro de sí violentos ardores y una fuerza ciega y brutal que tiende a estrangular, abofetear, romper cráneos y machacar huesos. Pero doña Perfecta era señora y además su tía, D. Inocencio era [30] anciano y sacerdote. Además de esto las violencias de obra son de mal gusto e impropias de personas cristianas y bien educadas. Quedaba el recurso de dar libertad a su comprimido encono por medio de la palabra manifestada decorosamente y sin faltarse a sí mismo; pero aun le pareció prematuro este postrer recurso, que no debía emplear, 103 según su juicio, hasta el instante de salir definitivamente de aquella casa y de Orbajosa. Resistiendo, pues, el furibundo ataque, aguardó.\"},{\"heading\":false,\"text\":\"[5] Jacinto llegó cuando la cena concluía.\"},{\"heading\":false,\"text\":\"--Buenas noches, Sr. D. José...--dijo, estrechando la mano del joven.--Usted y sus amigas no me han dejado trabajar esta tarde. No he podido escribir una línea.¡Y tenía que hacer!...\"},{\"heading\":false,\"text\":\"[10] --¡Cuánto lo siento, Jacinto! Pues, según me dijeron, usted las acompaña algunas veces en sus juegos y retozos.\"},{\"heading\":false,\"text\":\"--¡Yo!--exclamó el rapaz, poniéndose como la grana.--¡Bah! bien sabe usted que Tafetán no dice nunca palabra de verdad... ¿Pero es cierto, Sr. de Rey, que se [15] marcha usted?\"},{\"heading\":false,\"text\":\"--¿Lo dicen por ahí?...\"},{\"heading\":false,\"text\":\"--Sí; lo he oído en el Casino, en casa de D. Lorenzo Ruiz.\"},{\"heading\":false,\"text\":\"Rey contempló durante un rato las frescas facciones de [20] _D. Nominavito_. Después dijo:\"},{\"heading\":false,\"text\":\"--Pues no es cierto. Mi tía está muy contenta de mí; desprecia las calumnias con que me están obsequiando los orbajosenses... y no me arrojará de su casa, aunque en ello se empeñe el señor obispo.\"},{\"heading\":false,\"text\":\"[25] --Lo que es arrojarte... jamás. ¡Qué diría tu padre!...\"},{\"heading\":false,\"text\":\"--A pesar de sus bondades, queridísima tía, a pesar de la amistad cordial del señor canónigo, quizás decida yo marcharme....\"},{\"heading\":false,\"text\":\"[30] --¡Marcharte!\"},{\"heading\":false,\"text\":\"--¡Marcharse usted!\"},{\"heading\":false,\"text\":\"En los ojos de doña Perfecta brilló una luz singular. El canónigo, a pesar de ser hombre muy experto en el disimulo, no pudo ocultar su júbilo.\"},{\"heading\":false,\"text\":\"--Sí; y tal vez esta misma noche.... 104\"},{\"heading\":false,\"text\":\"--¡Pero hombre, qué arrebatado eres!... ¿Por qué no esperas siquiera a mañana temprano?... A ver... Juan, que vayan a llamar al tío Licurgo para que prepare [5] la jaca.... Supongo que llevarás algún fiambre.... ¡Nicolasa!... ese pedazo de ternera que está en el aparador.... Librada, la ropa del señorito....\"},{\"heading\":false,\"text\":\"--No, no puedo creer que usted tome determinación tan brusca--dijo D. Cayetano, creyéndose obligado a tomar [10] alguna parte en aquella cuestión.\"},{\"heading\":false,\"text\":\"--¿Pero volverá usted... no es eso?--preguntó el canónigo.\"},{\"heading\":false,\"text\":\"--¿A qué hora pasa el tren de la mañana?--preguntó doña Perfecta, por cuyos ojos claramente asomaba la febril [15] impaciencia de su altura.\"},{\"heading\":false,\"text\":\"--Sí, me marcho esta misma noche.\"},{\"heading\":false,\"text\":\"--Pero hombre, si no hay luna.\"},{\"heading\":false,\"text\":\"En el alma de doña Perfecta, en el alma del Penitenciario, en la juvenil alma del doctorcillo retumbaron como una [20] armonía celeste estas palabras: \\\"esta misma noche.\\\"\"},{\"heading\":false,\"text\":\"--Por supuesto, querido Pepe, tú volverás.... Yo he escrito hoy a tu padre, a tu excelente padre....--exclamó doña Perfecta, con todos los síntomas fisiognómicos que aparecen cuando se va a derramar una lágrima.\"},{\"heading\":false,\"text\":\"[25] --Molestaré a usted con algunos encargos--manifestó el sabio.\"},{\"heading\":false,\"text\":\"--Buena ocasión para pedir el cuaderno que me falta de la obra del abate Gaume--indicó el abogadejo.\"},{\"heading\":false,\"text\":\"--Vamos, Pepe, que tienes unos arrebatos y unas salidas--murmuró [30] la señora sonriendo, con la vista fija en la puerta del comedor.--Pero se me olvidaba decirte que Caballuco está esperando para hablarte.\"},{\"heading\":false,\"text\":\"105\"}]},{\"title\":\"Capítulo XV\",\"blocks\":[{\"heading\":false,\"text\":\"=Sigue creciendo, hasta que se declara la guerra=\"},{\"heading\":false,\"text\":\"Todos miraron hacia la puerta, donde apareció la imponente figura del Centauro, serio, cejijunto, confuso al querer saludar con amabilidad, hermosamente salvaje, pero desfigurado por la violencia que hacía para sonreír urbanamente [5] y pisar quedo y tener en correcta postura los hercúleos brazos.\"},{\"heading\":false,\"text\":\"--Adelante, Sr. Ramos--dijo Pepe Rey.\"},{\"heading\":false,\"text\":\"--Pero no--objetó doña Perfecta.--Si es una tontería lo que tiene que decirte.\"},{\"heading\":false,\"text\":\"[10] --Que lo diga.\"},{\"heading\":false,\"text\":\"--Yo no debo consentir que en mi casa se ventilen estas cuestiones ridículas....\"},{\"heading\":false,\"text\":\"--¿Qué quiere de mí el Sr. Ramos?\"},{\"heading\":false,\"text\":\"Caballuco pronunció algunas palabras.\"},{\"heading\":false,\"text\":\"[15] --Basta, basta... exclamó doña Perfecta, riendo.--No molestes más a mi sobrino. Pepe, no hagas caso de ese majadero.... ¿Quieren ustedes que les diga en qué consiste el enojo del gran Caballuco?\"},{\"heading\":false,\"text\":\"--¿Enojo? Ya me lo figuro--indicó el Penitenciario, [20] recostándose en el sillón y riendo expansivamente y con estrépito.\"},{\"heading\":false,\"text\":\"--Yo quería decirle al Sr. D. José....--gruñó el formidable ginete.\"},{\"heading\":false,\"text\":\"--Hombre, calla por Dios, no nos aporrees los oídos.\"},{\"heading\":false,\"text\":\"[25] --Sr. Caballuco--dijo el canónigo,--no es mucho que los señores de la Corte desbanquen a los rudos caballistas de estas salvajes tierras....\"},{\"heading\":false,\"text\":\"--En dos palabras, Pepe, la cuestión es esta. Caballuco es no sé qué....\"},{\"heading\":false,\"text\":\"[30] La risa le impidió continuar.\"},{\"heading\":false,\"text\":\"--No sé qué--añadió D. Inocencio,--de una de las 106 niñas de Troya, de Mariquita Juana, si no estoy equivocado.\"},{\"heading\":false,\"text\":\"--¡Y está celoso! Después de su caballo, lo primero de la Creación es Mariquilla Troya.\"},{\"heading\":false,\"text\":\"[5] --¡Bonito apunte!--exclamó la señora.--¡Pobre Cristóbal! ¿Has creído que una persona como mi sobrino?... Vamos a ver, ¿qué ibas a decirle? Habla.\"},{\"heading\":false,\"text\":\"--Ya hablaremos el Sr. D. José y yo--repuso bruscamente el bravo de la localidad.\"},{\"heading\":false,\"text\":\"[10] Y sin decir más se retiró.\"},{\"heading\":false,\"text\":\"Poco después Pepe Rey salió del comedor para ir a su cuarto. En la galería hallóse frente a frente con su troyano antagonista, y no pudo reprimir la risa al ver la torva seriedad del ofendido cortejo.\"},{\"heading\":false,\"text\":\"[15] --Una palabra--dijo éste plantándose descaradamente ante el ingeniero.--¿Usted sabe quién soy yo?\"},{\"heading\":false,\"text\":\"Diciendo esto puso la pesada mano en el hombro del joven con tan insolente franqueza, que éste no pudo menos de rechazarle enérgicamente.\"},{\"heading\":false,\"text\":\"[20] --No es preciso aplastar para eso.\"},{\"heading\":false,\"text\":\"El valentón, ligeramente desconcertado, se repuso al instante, y mirando a Rey con audacia provocativa, repitió su estribillo.\"},{\"heading\":false,\"text\":\"--¿Sabe usted quién soy yo?\"},{\"heading\":false,\"text\":\"[25] --Sí: ya sé que es usted un animal.\"},{\"heading\":false,\"text\":\"Apartóle bruscamente hacia un lado y entró en su cuarto. Según el estado del cerebro de nuestro desgraciado amigo en aquel instante, sus acciones debían sintetizarse en el siguiente brevísimo y definitivo plan: romperle la cabeza a [30] Caballuco sin pérdida de tiempo; despedirse en seguida de su tía con razones severas, aunque corteses, que le llegaran al alma; dar un frío adiós al canónigo y un abrazo al inofensivo D. Cayetano; administrar, por fin de fiesta, una paliza al tío Licurgo; partir de Orbajosa aquella misma noche y sacudirse el polvo de los zapatos a la salida de la 107 ciudad.\"},{\"heading\":false,\"text\":\"Pero los pensamientos del perseguido joven no podían apartarse, en medio de tantas amarguras, de otro [5] desgraciado ser a quien suponía en situación más aflictiva y angustiosa que la suya propia. Tras el ingeniero entró en la estancia una criada.\"},{\"heading\":false,\"text\":\"--¿Le diste mi recado?--preguntó él.\"},{\"heading\":false,\"text\":\"--Sí, señor, y me dió esto.\"},{\"heading\":false,\"text\":\"[10] Rey tomó de las manos de la muchacha un pedacito de periódico, en cuyo margen leyó estas palabras: \\\"Dicen que te vas. Yo me muero.\\\"\"},{\"heading\":false,\"text\":\"Cuando volvió al comedor, el tío Licurgo se asomaba a la puerta preguntando:\"},{\"heading\":false,\"text\":\"[15] --¿A qué hora hace falta la jaca?\"},{\"heading\":false,\"text\":\"--A ninguna--contestó vivamente Rey.\"},{\"heading\":false,\"text\":\"--¿Luégo no te vas esta noche?--dijo doña Perfecta.--Mejor es que lo dejes para mañana.\"},{\"heading\":false,\"text\":\"--Tampoco.\"},{\"heading\":false,\"text\":\"[20] --¿Pues cuándo?\"},{\"heading\":false,\"text\":\"--Ya veremos--dijo fríamente el joven mirando a su tía con imperturbable calma.--Por ahora no pienso marcharme.\"},{\"heading\":false,\"text\":\"Sus ojos lanzaban enérgico reto.\"},{\"heading\":false,\"text\":\"[25] Doña Perfecta se puso primero encendida, pálida después. Miró al canónigo que se había quitado las gafas de oro para limpiarlas, y luego clavó sucesivamente la vista en los demás que ocupaban la estancia, incluso Caballuco que, entrando poco antes, se sentara en el borde de una silla. [30] Doña Perfecta les miró como mira un general a sus queridos cuerpos de ejército. Después examinó el semblante meditabundo y sereno de su sobrino, de aquel estratégico enemigo que se presentaba de improviso cuando se le creía en vergonzosa fuga.\"},{\"heading\":false,\"text\":\"¡Ay! ¡Sangre, ruina y desolación!... Una gran 108 batalla se preparaba.\"}]},{\"title\":\"Capítulo XVI\",\"blocks\":[{\"heading\":false,\"text\":\"=Noche=\"},{\"heading\":false,\"text\":\"Orbajosa dormía. Los mustios farolillos del público alumbrado despedían en encrucijadas y callejones su postrer [5] fulgor como cansados ojos que no pueden vencer el sueño. A su débil luz se escurrían envueltos en sus capas los vagabundos, los rondadores, los jugadores. Sólo el graznar del borracho o el canto del enamorado turbaban la callada paz de la ciudad histórica. De pronto el _Ave María Purísima_ [10] de vinoso sereno sonaba como un quejido enfermizo del durmiente poblachón.\"},{\"heading\":false,\"text\":\"En la casa de doña Perfecta también había silencio. Turbábalo tan sólo un diálogo que en la biblioteca del Sr. D. Cayetano sostenían éste y Pepe Rey. Sentábase el [15] erudito reposadamente en el sillón de su mesa de estudio, la cual aparecía cubierta por diversas suertes de papeles, conteniendo notas, apuntes y referencias, sin que el más pequeño desorden las confundiese, a pesar de su mucha diversidad y abundancia. Rey fijaba los ojos en el copioso [20] montón de papeles; pero sus pensamientos volaban sin duda en regiones muy distantes de aquella sabiduría.\"},{\"heading\":false,\"text\":\"--Perfecta--dijo el anticuario,--aunque es una mujer excelente, tiene el defecto de escandalizarse por cualquier acción frívola e insignificante. Amigo, en estos pueblos de [25] provincia el menor desliz se paga caro. Nada encuentro de particular en que usted fuese a casa de las Troyas. Se me figura que D. Inocencio, bajo su capita de hombre de bien, es algo cizañoso. ¿A él qué le importa?...\"},{\"heading\":false,\"text\":\"--Hemos llegado a un punto, Sr. D. Cayetano, en que [30] es preciso tomar una determinación enérgica. Yo necesito ver y hablar a Rosario.\"},{\"heading\":false,\"text\":\"--Pues véala usted. 109\"},{\"heading\":false,\"text\":\"--Es que no me dejan--respondió el ingeniero dando un puñetazo en la mesa.--Rosario está secuestrada....\"},{\"heading\":false,\"text\":\"--¡Secuestrada!--exclamó el sabio con incredulidad.--La [5] verdad es que no me gusta su cara, ni su aspecto, ni menos el estupor que se pinta en sus bellos ojos. Está triste, habla poco, llora.... Amigo D. José, me temo mucho que esa niña se vea atacada de la terrible enfermedad que ha hecho tantas víctimas en los individuos de mi [10] familia.\"},{\"heading\":false,\"text\":\"--¡Una terrible enfermedad! ¿Cuál?\"},{\"heading\":false,\"text\":\"--La locura... mejor dicho, manías. En mi familia no ha habido uno solo que se librara de ellas. Yo, yo soy el único que he logrado escapar.\"},{\"heading\":false,\"text\":\"[15] --¡Usted!... Dejando a un lado las manías--dijo Rey con impaciencia,--yo quiero ver a Rosario.\"},{\"heading\":false,\"text\":\"--Nada más natural. Pero el aislamiento en que su madre la tiene es un sistema higiénico, querido Pepe, el único sistema que se ha empleado con éxito en todos los [20] individuos de mi familia. Considere usted que la persona cuya presencia y voz debe de hacer más impresión en el delicado sistema nervioso de Rosarillo, es el elegido de su corazón.\"},{\"heading\":false,\"text\":\"--A pesar de todo--insistió Pepe,--yo quiero verla.\"},{\"heading\":false,\"text\":\"[25] --Quizás Perfecta no se oponga a ello--dijo el sabio fijando la atención en sus notas y papeles.--No quiero meterme en camisa de once varas.\"},{\"heading\":false,\"text\":\"El ingeniero, viendo que no podía sacar partido del buen Polentinos, se retiró para marcharse.\"},{\"heading\":false,\"text\":\"[30] --Usted va a trabajar, y no quiero estorbarle.\"},{\"heading\":false,\"text\":\"--No; aún tengo tiempo. Vea usted el cúmulo de preciosos datos que he reunido hoy. Atienda usted.... \\\"En 1537 un vecino de Orbajosa, llamado Bartolomé del Hoyo, fué a Civita-Vecchia en las galeras del Marqués de Castel Rodrigo.\\\" Otra. \\\"En el mismo año dos hermanos, hijos 110 también de Orbajosa y llamados Juan y Rodrigo González del Arco, se embarcaron en los seis navíos que salieron de Maestrique el 20 de Febrero y que a la altura de Calais [5] toparon con un navío inglés y los flamencos que mandaba Van-Owen....\\\" En fin, fué aquello una importante hazaña de nuestra marina. He descubierto que un orbajosense, un tal Mateo Díaz Coronel, alférez de la Guardia, fué el que escribió en 1709 y dió a la estampa en Valencia el [10] _Métrico encomio, fúnebre canto, lírico elogio, descripción numérica, gloriosas fatigas, angustiadas glorias de la Reina de los Ángeles._ Poseo un preciosísimo ejemplar de esta obra, que vale un Perú.... Otro orbajosense es autor de aquel famoso _Tractado de las diversas suertes de la Gineta_, que [15] enseñé a usted ayer, y, en resumen, no doy un paso por el laberinto de la historia inédita sin tropezar con algún paisano ilustre. Yo pienso sacar todos esos nombres de la injusta obscuridad y olvido en que yacen. ¡Qué goce tan puro, querido Pepe, es devolver todo su lustre a las glorias, [20] ora épicas, ora literarias del país en que hemos nacido! Ni qué mejor empleo puede dar un hombre al escaso entendimiento que del cielo recibiera, a la fortuna heredada y al tiempo breve con que puede contar en el mundo la más dilatada existencia.... Gracias a mí, se verá que Orbajosa [25] es ilustre cuna del genio español. Pero ¿qué digo? ¿No se conoce bien su prosapia ilustre en la nobleza, en la hidalguía de la actual generación _urbsaugustana_? Pocas localidades conocemos en que crezcan con más lozanía las plantas y arbustos de todas las virtudes, libres de la maléfica [30] hierba de los vicios. Aquí todo es paz, mutuo respeto, humildad cristiana. La caridad se practica aquí como en los tiempos evangélicos; aquí no se conoce la envidia; aquí no se conocen las pasiones criminales, y si oye usted hablar de ladrones y asesinos, tenga por seguro que no son hijos de esta noble tierra, o que pertenecen al número de 111 los infelices pervertidos por las predicaciones demagógicas. Aquí verá usted el carácter nacional en toda su pureza, recto, hidalgo, incorruptible, puro, sencillo, patriarcal, [5] hospitalario, generoso.... Por eso gusto tanto vivir en esta pacífica soledad, lejos del laberinto de las ciudades, donde reinan ¡ay! la falsedad y el vicio. Por eso no han podido sacarme de aquí los muchos amigos que tengo en Madrid; por eso vivo en la dulce compañía de mis leales paisanos y [10] de mis libros, respirando sin cesar esta salutífera atmósfera de honradez, que se va poco a poco reduciendo en nuestra España, y sólo existe en las humildes y cristianas ciudades que con las emanaciones de sus virtudes saben conservarla. Y no crea usted, este sosegado aislamiento ha contribuído [15] mucho, queridísimo Pepe, a librarme de la terrible enfermedad connaturalizada en mi familia. En mi juventud yo, lo mismo que mis hermanos y padre, padecía lamentable propensión a las más absurdas manías; pero aquí me tiene usted tan pasmosamente curado, que no conozco tal enfermedad [20] sino cuando la veo en los demás. Por eso mi sobrinilla me tiene tan inquieto.\"},{\"heading\":false,\"text\":\"--Celebro que los aires de Orbajosa le hayan preservado a usted--dijo Rey, no pudiendo reprimir un sentimiento de burlas que por ley extraña nació en medio de su tristeza.--A [25] mí me han probado tan mal, que creo he de ser maniático dentro de poco tiempo si sigo aquí. Con que buenas noches, y que trabaje usted mucho.\"},{\"heading\":false,\"text\":\"--Buenas noches.\"},{\"heading\":false,\"text\":\"Dirigióse a su habitación; mas no sintiendo sueño ni [30] necesidad de reposo físico, sino por el contrario, fuerte excitación que le impulsaba a agitarse y divagar, cavilando y moviéndose, se paseó de un ángulo a otro de la pieza. Después abrió la ventana que daba a la huerta, y poniendo los codos en el antepecho de ella, contempló la inmensa negrura de la noche. No se veía nada. Pero el hombre 112 ensimismado lo ve todo, y Rey, fijos los ojos en la obscuridad, miraba cómo se iba desarrollando sobre ella el abigarrado paisaje de sus desgracias. La sombra no le permitía [5] ver las flores de la tierra, ni las del cielo, que son las estrellas. La misma falta casi absoluta de claridad producía el efecto de un ilusorio movimiento en las masas de árboles, que se extendían al parecer, iban perezosamente y regresaban enroscándose, como el oleaje de un mar de [10] sombras. Formidable flujo y reflujo, una lucha entre fuerzas no bien manifiestas, agitaban la silenciosa esfera. El matemático, contemplando aquella extraña proyección de su alma sobre la noche, decía:\"},{\"heading\":false,\"text\":\"--La batalla será terrible. Veremos quién sale [15] triunfante.\"},{\"heading\":false,\"text\":\"Los insectos de la noche hablaron a su oído, diciéndole misteriosas palabras. Aquí un chirrido áspero; allí un chasquido semejante al que hacemos con la lengua; allá lastimeros murmullos; más lejos un son vibrante parecido [20] al de la esquila suspendida al cuello de la res vagabunda. De súbito sintió Rey una consonante extraña, una rápida nota propia tan sólo de la lengua y de los labios humanos. Esta exhalación cruzó por el cerebro del joven como un relámpago. Sintió culebrear dentro de sí aquella S fugaz, [25] que se repitió una y otra vez, aumentando de intensidad. Miró a todos lados, miró hacia la parte alta de la casa, y en una ventana creyó distinguir un objeto semejante a un ave blanca que movía las alas. Por la mente excitada de Pepe Rey cruzó en un instante la idea del fénix, de la paloma, de [30] la garza real... y sin embargo, aquella ave no era más que un pañuelo.\"},{\"heading\":false,\"text\":\"El ingeniero saltó por la ventana a la huerta. Observando bien, vió la mano y el rostro de su prima. Le pareció distinguir el tan usual movimiento de imponer silencio llevando el dedo a los labios. Después la simpática sombra 113 alargó el brazo hacia abajo y desapareció. Pepe Rey entró de nuevo en su cuarto rápidamente y procurando no hacer ruido, pasó a la galería, avanzando después lentamente por [5] ella. Sentía el palpitar de su corazón, como si recibiera hachazos dentro del pecho. Esperó un rato... al fin oyó distintamente tenues golpes en los peldaños de la escalera. Uno, dos, tres.... Producían aquel rumor unos zapatitos.\"},{\"heading\":false,\"text\":\"[10] Dirigióse hacia allá en medio de una obscuridad casi profunda, y alargó los brazos para prestar apoyo a quien bajaba. En su alma reinaba una ternura exaltada y profunda; pero ¿a qué negarlo? tras aquel dulce sentimiento surgió de repente, como infernal inspiración, otro que era [15] un terrible deseo de venganza. Los pasos se acercaban descendiendo. Pepe Rey avanzó, y unas manos que tanteaban en el vacío chocaron con las suyas. Las cuatro ¡ay! se unieron en estrecho apretón.\"}]},{\"title\":\"Capítulo XVII\",\"blocks\":[{\"heading\":false,\"text\":\"=Luz a obscuras=\"},{\"heading\":false,\"text\":\"La galería era larga y ancha. A un extremo estaba la [20] puerta del cuarto donde moraba el ingeniero; en el centro la del comedor, y al otro extremo la escalera y una puerta grande y cerrada, con un peldaño en el umbral. Aquella puerta era la de una capilla, donde los Polentinos tenían los santos de su devoción doméstica. Alguna vez se celebraba [25] en ella el santo sacrificio de la misa.\"},{\"heading\":false,\"text\":\"Rosario dirigió a su primo hacia la puerta de la capilla, y se dejó caer en el escalón.\"},{\"heading\":false,\"text\":\"--¿Aquí?...--murmuró Pepe Rey.\"},{\"heading\":false,\"text\":\"Por los movimientos de la mano derecha de Rosario, [30] comprendió que ésta se santiguaba.\"},{\"heading\":false,\"text\":\"--Prima querida, Rosario... ¡gracias por haberte 114 dejado ver!--exclamó estrechándola con ardor entre sus brazos.\"},{\"heading\":false,\"text\":\"Sintió los dedos fríos de la joven sobre sus labios, [5] imponiéndole silencio. Los besó con frenesí.\"},{\"heading\":false,\"text\":\"--Estás helada... Rosario... ¿por qué tiemblas así?\"},{\"heading\":false,\"text\":\"Daba diente con diente, y su cuerpo todo se estremecía con febril convulsión. Rey sintió en su cara el abrasador fuego del rostro de su prima, y alarmado exclamó:\"},{\"heading\":false,\"text\":\"[10] --Tu frente es un volcán. Tienes fiebre.\"},{\"heading\":false,\"text\":\"--Mucha.\"},{\"heading\":false,\"text\":\"--¿Estás enferma realmente?\"},{\"heading\":false,\"text\":\"--Sí....\"},{\"heading\":false,\"text\":\"--Y has salido....\"},{\"heading\":false,\"text\":\"[15] --Por verte.\"},{\"heading\":false,\"text\":\"El ingeniero la estrechó entre sus brazos para darle abrigo; pero no bastaba.\"},{\"heading\":false,\"text\":\"--Aguarda--dijo vivamente levantándose.--Voy a mi cuarto a traer mi manta de viaje.\"},{\"heading\":false,\"text\":\"[20] --Apaga la luz, Pepe.\"},{\"heading\":false,\"text\":\"Rey había dejado encendida la luz dentro de su cuarto, y por la puerta de éste salía una tenue claridad, iluminando la galería. Volvió al instante. La obscuridad era ya profunda. Tentando las paredes pudo llegar hasta donde [25] estaba su prima. Reuniéronse y la arropó cuidadosamente de los pies a la cabeza.\"},{\"heading\":false,\"text\":\"--¿Qué bien estás ahora, niña mía?\"},{\"heading\":false,\"text\":\"--Sí, ¡qué bien!... Contigo.\"},{\"heading\":false,\"text\":\"--Conmigo... y para siempre--exclamó con [30] exaltación el joven.\"},{\"heading\":false,\"text\":\"Pero observó que se desasía de sus brazos y se levantaba.\"},{\"heading\":false,\"text\":\"--¿Qué haces?\"},{\"heading\":false,\"text\":\"Sintió el ruido de un hierrecillo. Rosario entraba una llave en la invisible cerradura, y abría cuidadosamente la puerta en cuyo umbral se habían sentado. Leve olor de 115 humedad, inherente a toda pieza cerrada por mucho tiempo, salía de aquel recinto obscuro como una tumba. Pepe Rey se sintió llevado de la mano, y la voz de su prima dijo muy [5] débilmente:\"},{\"heading\":false,\"text\":\"--Entra.\"},{\"heading\":false,\"text\":\"Dieron algunos pasos. Creíase él conducido a ignotos lugares Elíseos por el ángel de la noche. Ella tanteaba. Por fin volvió a sonar su dulce voz, murmurando:\"},{\"heading\":false,\"text\":\"[10] --Siéntate.\"},{\"heading\":false,\"text\":\"Estaban junto a un banco de madera. Los dos se sentaron. Pepe Rey la abrazó de nuevo. En el mismo instante su cabeza chocó con un cuerpo muy duro.\"},{\"heading\":false,\"text\":\"--¿Qué es esto?\"},{\"heading\":false,\"text\":\"[15] --Los pies.\"},{\"heading\":false,\"text\":\"--Rosario... ¿qué dices?\"},{\"heading\":false,\"text\":\"--Los pies del divino Jesús, de la imagen de Cristo Crucificado, que adoramos en mi casa.\"},{\"heading\":false,\"text\":\"Pepe Rey sintió como una fría lanzada que le traspasó el [20] corazón.\"},{\"heading\":false,\"text\":\"--Bésalos--dijo imperiosamente la joven.\"},{\"heading\":false,\"text\":\"El matemático besó los helados pies de la santa imagen.\"},{\"heading\":false,\"text\":\"--Pepe--exclamó después la señorita, estrechando ardientemente la mano de su primo.--¿Tú crees en Dios?\"},{\"heading\":false,\"text\":\"[25] --¡Rosario!... ¿qué dices ahí? ¡Qué locuras piensas!--repuso con perplejidad el primo.\"},{\"heading\":false,\"text\":\"--Contéstame.\"},{\"heading\":false,\"text\":\"Pepe Rey sintió humedad en sus manos.\"},{\"heading\":false,\"text\":\"--¿Porqué lloras?--dijo lleno de turbación.--Rosario, [30] me estás matando con tus dudas absurdas. ¡Que si creo en Dios! ¿Lo dudas tú?\"},{\"heading\":false,\"text\":\"--Yo no; pero todos dicen que eres ateo.\"},{\"heading\":false,\"text\":\"--Desmerecerías a mis ojos, te despojarías de tu aureola de pureza y de prestigio, si dieras crédito a tal necedad.\"},{\"heading\":false,\"text\":\"--Oyéndote calificar de ateo, y sin poder convencerme 116 de lo contrario por ninguna razón, he protestado desde el fondo de mi alma contra tal calumnia. Tú no puedes ser [5] ateo. Dentro de mí tengo yo vivo y fuerte el sentimiento de tu religiosidad, como el de la mía propia.\"},{\"heading\":false,\"text\":\"--¡Qué bien has hablado! ¿Entonces, por qué me preguntas si creo en Dios?\"},{\"heading\":false,\"text\":\"--Porque quería escucharlo de tu misma boca y recrearme oyéndotelo decir. ¡Hace tanto tiempo que no oigo [10] el acento de tu voz!... ¿qué mayor gusto que oírlo de nuevo, después de tan gran silencio, diciendo: \\\"creo en Dios\\\"?\"},{\"heading\":false,\"text\":\"--Rosario, hasta los malvados creen en él. Si existen ateos, que lo dudo, son los calumniadores, los intrigantes [15] de que está infestado el mundo.... Por mi parte, me importan poco las intrigas y las calumnias, y si tú te sobrepones a ellas y cierras tu corazón a los sentimientos de discordia que una mano aleve quiere introducir en él, nada se opondrá a nuestra felicidad.\"},{\"heading\":false,\"text\":\"[20] --¿Pero qué nos pasa? Pepe, querido Pepe... ¿tú crees en el Diablo?\"},{\"heading\":false,\"text\":\"El ingeniero calló. La obscuridad de la capilla no permitía a Rosario ver la sonrisa con que su primo acogiera tan extraña pregunta.\"},{\"heading\":false,\"text\":\"[25] --Será preciso creer en él--dijo al fin.\"},{\"heading\":false,\"text\":\"--¿Qué nos pasa? Mamá me prohibe verte; pero fuera de lo del ateísmo no habla mal de ti. Díceme que espere; que tú decidirás; que te vas, que vuelves.... Hablame con franqueza.... ¿Has formado mala idea de [30] mi madre?\"},{\"heading\":false,\"text\":\"--De ninguna manera--replicó Rey, apremiado por su delicadeza.\"},{\"heading\":false,\"text\":\"--¿No crees, como yo, que me quiere mucho; que nos quiere a los dos, que sólo desea nuestro bien, y que al fin hemos de alcanzar de ella el consentimiento 117 que deseamos?\"},{\"heading\":false,\"text\":\"--Si tú lo crees así, yo también.... Tu mamá nos adora a entrambos.... Pero, querida Rosario, es preciso [5] confesar que el Demonio ha entrado en esta casa.\"},{\"heading\":false,\"text\":\"--No te burles--repuso ella con cariño....--¡Ay! mamá es muy buena. Ni una sola vez me ha dicho que no fueras digno de ser mi marido. No insiste más que en lo del ateísmo. Dicen además que tengo manías, y que ahora [10] me ha entrado la de quererte con toda mi alma. En nuestra familia es ley no contrariar de frente las manías congénitas que tenemos, porque atacándolas se agravan más.\"},{\"heading\":false,\"text\":\"--Pues yo creo que a tu lado hay buenos médicos que se han propuesto curarte, y que al fin, adorada niña mía, lo van [15] a conseguir.\"},{\"heading\":false,\"text\":\"--No, no, no mil veces--exclamó Rosario, apoyando su frente en el pecho de su novio.--Quiero volverme loca contigo. Por ti estoy padeciendo; por ti estoy enferma; por ti desprecio la vida y me expongo a morir.... Ya lo [20] preveo, mañana estaré peor, me agravaré.... Moriré; ¡qué me importa!\"},{\"heading\":false,\"text\":\"--Tú no estás enferma--repuso él con energía; tú no tienes sino una perturbación moral, que naturalmente trae ligeras afecciones nerviosas; tú no tienes más que la pena [25] ocasionada por esta horrible violencia que están ejerciendo sobre ti. Tu alma sencilla y generosa no lo comprende. Cedes; perdonas a los que te hacen daño; te afliges, atribuyendo tu desgracia a funestas influencias sobrenaturales; padeces en silencio; entregas tu inocente cuello al verdugo; [30] te dejas matar, y el mismo cuchillo, hundido en tu garganta, te parece la espina de una flor que se te clavó al pasar. Rosario, desecha esas ideas: considera nuestra verdadera situación, que es grave: mira la causa de ella donde verdaderamente está, y no te acobardes, no cedas a la mortificación que se te impone, enfermando tu alma y tu cuerpo. 118 El valor de que careces te devolverá la salud, porque tú no estás realmente enferma, querida niña mía, tú estás... ¿quieres que lo diga? estás asustada, aterrada. Te pasa [5] lo que los antiguos no sabían definir y llamaban maleficio. ¡Rosario, ánimo, confía en mí! Levántate y sígueme. No te digo más.\"},{\"heading\":false,\"text\":\"--¡Ay, Pepe... primo mío!... se me figura que tienes razón--exclamó Rosarito anegada en llanto.--Tus [10] palabras resuenan en mi corazón como golpes violentos que, estremeciéndome, me dan nueva vida. Aquí en esta obscuridad, donde no podemos vernos las caras, una luz inefable sale de ti y me inunda el alma. ¿Qué tienes tú, que así me transformas? Cuando te conocí, de repente fuí [15] otra. En los días en que he dejado de verte me he visto volver a mi antiguo estado insignificante, a mi cobardía primera. Sin ti vivo en el Limbo, Pepe mío.... Haré lo que me dices, me levanto y te sigo. Iremos juntos a donde quieras. ¿Sabes que me siento bien? ¿Sabes que no [20] tengo ya fiebre, que recobro las fuerzas, que quiero correr y gritar, que todo mi ser se renueva, y se aumenta y se centuplica para adorarte? Pepe, tienes razón. Yo no estoy enferma, yo no estoy sino acobardada; mejor dicho, fascinada.\"},{\"heading\":false,\"text\":\"[25] --Eso es, fascinada.\"},{\"heading\":false,\"text\":\"--Fascinada. Terribles ojos me miran y me dejan muda y trémula. Tengo miedo; ¿pero a qué?... Tú sólo tienes el extraño poder de devolverme la vida. Oyéndote, resucito. Yo creo que si me muriera y fueras a pasear [30] junto a mi sepultura, desde lo hondo de la tierra sentiría tus pasos. ¡Oh, si pudiera verte ahora!... Pero estás aquí, a mi lado, y no puedo dudar que eres tú.... ¡Tanto tiempo sin verte!... Yo estaba loca. Cada día de soledad me parecía un siglo.... Me decían que mañana, que mañana, y vuelta con mañana. Yo me asomaba por las 119 noches a la ventana, y la claridad de la luz de tu cuarto me servía de consuelo. A veces tu sombra en los cristales era para mí una aparición divina. Yo extendía los brazos hacia [5] fuera, derramaba lágrimas y gritaba con el pensamiento, sin atreverme a hacerlo con la voz. Cuando recibí tu recado por conducto de la criada; cuando recibí tu carta diciéndome que te marchabas, me puse muy triste, creí que se me iba saliendo el alma del cuerpo y que me moría por grados. [10] Yo caía, caía como el pájaro herido cuando vuela, que va cayendo y muriéndose, todo al mismo tiempo.... Esta noche, cuando te vi despierto tan tarde, no pude resistir el anhelo de hablarte, y bajé. Creo que todo el atrevimiento que puedo tener en mi vida lo he consumido y empleado en [15] una sola acción, en ésta, y que ya no podré dejar de ser cobarde.... Pero tú me darás aliento; tú me darás fuerzas; tú me ayudarás, ¿no es verdad?... Pepe, primo mío querido, dime que sí; dime que tengo fuerzas, y las tendré; dime que no estoy enferma, y no lo estaré. Ya [20] no lo estoy. Me encuentro tan bien, que me río de mis males ridículos.\"},{\"heading\":false,\"text\":\"Al decir esto, Rosarito se sintió frenéticamente enlazada por los brazos de su primo. Oyóse un ¡ay! pero no salió de los labios de ella, sino de los de él, porque habiendo [25] inclinado la cabeza, tropezó violentamente con los pies del Cristo. En la obscuridad es donde se ven las estrellas.\"},{\"heading\":false,\"text\":\"En el estado de su ánimo y en la natural alucinación que producen los sitios obscuros, a Rey le parecía, no que su [30] cabeza había topado con el santo pie, sino que éste se había movido, amonestándole de la manera más breve y más elocuente. Entre serio y festivo alzó la cabeza, y dijo así:\"},{\"heading\":false,\"text\":\"--Señor, no me pegues, que no haré nada malo.\"},{\"heading\":false,\"text\":\"En el mismo instante Rosario tomó la mano del joven, 120 oprimiéndola contra su corazón. Oyóse una voz pura, grave, angelical, conmovida, que habló de este modo:\"},{\"heading\":false,\"text\":\"--Señor que adoro, Señor Dios del mundo y tutelar de mi [5] casa y de mi familia; Señor a quien Pepe también adora; Santo Cristo bendito que moriste en la Cruz por nuestros pecados; ante Ti, ante tu cuerpo herido, ante tu frente coronada de espinas, digo que éste es mi esposo, y que después de Ti, es el que más ama mi corazón; digo que le declaro mi [10] esposo, y que antes moriré que pertenecer a otro. Mi corazón y mi alma son suyos. Haz que el mundo no se oponga a nuestra felicidad, y concédeme el favor de esta unión, que juro sea buena ante el mundo como lo es en mi conciencia.\"},{\"heading\":false,\"text\":\"--Rosario, eres mía,--exclamó Pepe con exaltación.--Ni [15] tu madre ni nadie lo impedirá.\"},{\"heading\":false,\"text\":\"La prima inclinó su hermoso busto inerte sobre el pecho del primo. Temblaba en los amantes brazos varoniles, como la paloma en las garras del águila.\"},{\"heading\":false,\"text\":\"Por la mente del ingeniero pasó como un rayo la idea de [20] que existía el Demonio; pero entonces el Demonio era él. Rosario hizo ligero movimiento de miedo; tuvo como el temblor de sorpresa que anuncia el peligro.\"},{\"heading\":false,\"text\":\"--Júrame que no desistirás--dijo turbadamente Rey, atajando aquel movimiento.\"},{\"heading\":false,\"text\":\"[25] --Te lo juro por las cenizas de mi padre, que están....\"},{\"heading\":false,\"text\":\"--¿Dónde?\"},{\"heading\":false,\"text\":\"--Bajo nuestros pies.\"},{\"heading\":false,\"text\":\"El matemático sintió que se levantaba bajo sus pies la losa... pero no, no se levantaba: es que él creyó notarlo [30] así, a pesar de ser matemático.\"},{\"heading\":false,\"text\":\"--Te lo juro--repitió Rosario,--por las cenizas de mi padre y por Dios que nos está mirando.... Que nuestros cuerpos, unidos como están, reposen bajo estas losas cuando Dios quiera llevarnos de este mundo.\"},{\"heading\":false,\"text\":\"--Sí--repitió Pepe Rey, con emoción profunda, 121 sintiendo llena su alma de una turbación inexplicable.\"},{\"heading\":false,\"text\":\"Ambos permanecieron en silencio durante breve rato. Rosario se había levantado.\"},{\"heading\":false,\"text\":\"[5] --¿Ya?\"},{\"heading\":false,\"text\":\"Volvió a sentarse.\"},{\"heading\":false,\"text\":\"--Tiemblas otra vez--dijo Pepe.--Rosario, tú estas mala; tu frente abrasa.\"},{\"heading\":false,\"text\":\"--Parece que me muero--murmuró la joven con [10] desaliento.--No sé qué tengo.\"},{\"heading\":false,\"text\":\"Cayó sin sentido en brazos de su primo. Agasajándola, notó que el rostro de la joven se cubría de helado sudor.\"},{\"heading\":false,\"text\":\"--Está realmente enferma--dijo para sí.--Esta salida [15] es una verdadera calaverada.\"},{\"heading\":false,\"text\":\"Levantóla en sus brazos, tratando de reanimarla, pero ni el temblor de ella ni el desmayo cesaban, por lo cual resolvió sacarla de la capilla, a fin de que el aire fresco la reanimase. Así fué en efecto. Recobrado el sentido, manifestó [20] Rosario mucha inquietud por hallarse a tal hora fuera de su habitación. El reloj de la catedral dió las cuatro.\"},{\"heading\":false,\"text\":\"--¡Qué tarde!--exclamó la joven.--Suéltame, primo. Me parece que puedo andar. Verdaderamente estoy muy mala.\"},{\"heading\":false,\"text\":\"[25] --Subiré contigo.\"},{\"heading\":false,\"text\":\"--Eso de ninguna manera. Antes iré arrastrándome hasta mi cuarto.... ¿No te parece que se oye un ruido?...\"},{\"heading\":false,\"text\":\"Ambos callaron. La ansiedad de su atención determinó un silencio absoluto.\"},{\"heading\":false,\"text\":\"[30] --¿No oyes nada, Pepe?\"},{\"heading\":false,\"text\":\"--Absolutamente nada.\"},{\"heading\":false,\"text\":\"--Pon atención.... Ahora, ahora vuelve a sonar. Es un rumor que no sé si suena lejos, muy lejos, o cerca, muy cerca. Lo mismo podría ser la respiración de mi madre que el chirrido de la veleta que está en la torre de la 122 catedral. ¡Ah! Tengo un oído muy fino.\"},{\"heading\":false,\"text\":\"--Demasiado fino.... Con que, querida prima, te subiré en brazos.\"},{\"heading\":false,\"text\":\"[5] --Bueno, súbeme hasta lo alto de la escalera. Después iré yo sola. En, cuanto descanse un poco, me quedaré como si tal cosa.... ¿Pero no oyes?\"},{\"heading\":false,\"text\":\"Detuviéronse en el primer peldaño.\"},{\"heading\":false,\"text\":\"--Es un sonido metálico.\"},{\"heading\":false,\"text\":\"[10] --¿La respiración de tu mamá?\"},{\"heading\":false,\"text\":\"--No, no es eso. El rumor viene de muy lejos. ¿Será el canto de un gallo?\"},{\"heading\":false,\"text\":\"--Podrá ser.\"},{\"heading\":false,\"text\":\"--Parece que suenan dos palabras, diciendo: _allá voy_, [15] _allá voy_.\"},{\"heading\":false,\"text\":\"--Ya, ya oigo--murmuró Pepe Rey.\"},{\"heading\":false,\"text\":\"--Es un grito.\"},{\"heading\":false,\"text\":\"--Es una corneta.\"},{\"heading\":false,\"text\":\"--¡Una corneta!\"},{\"heading\":false,\"text\":\"[20] --Sí. Sube pronto. Orbajosa va a despertar.... Ya se oye con claridad. No es trompeta sino clarín. La tropa se acerca.\"},{\"heading\":false,\"text\":\"--¡Tropa!\"},{\"heading\":false,\"text\":\"--No sé por qué me figuro que esta invasión militar ha [25] de ser provechosa para mí.... Estoy alegre. Rosario, arriba pronto.\"},{\"heading\":false,\"text\":\"--También yo estoy alegre. Arriba.\"},{\"heading\":false,\"text\":\"En un instante la subió, y los dos amantes se despidieron, hablándose al oído tan quedamente, que apenas se oían.\"},{\"heading\":false,\"text\":\"[30] --Me asomaré por la ventana que da a la huerta, para decirte que he llegado a mi cuarto sin novedad. Adiós.\"},{\"heading\":false,\"text\":\"--Adiós, Rosario. Ten cuidado de no tropezar con los muebles.\"},{\"heading\":false,\"text\":\"--Por aquí navego bien, primo. Ya nos veremos otra vez. Asómate a la ventana de tu cuarto si quieres recibir 123 mi parte telegráfico.\"},{\"heading\":false,\"text\":\"Pepe Rey hizo lo que se le mandaba; pero aguardó largo rato y Rosario no apareció en la ventana. El ingeniero [5] creía sentir agitadas voces en el piso alto.\"}]},{\"title\":\"Capítulo XVIII\",\"blocks\":[{\"heading\":false,\"text\":\"=Tropa=\"},{\"heading\":false,\"text\":\"Los habitantes de Orbajosa oían en la crepuscular vaguedad de su último sueño aquel clarín sonoro, y abrían los ojos diciendo:\"},{\"heading\":false,\"text\":\"--Tropa.\"},{\"heading\":false,\"text\":\"[10] Unos hablando consigo mismos, mitad dormidos, mitad despiertos, murmuraban:\"},{\"heading\":false,\"text\":\"--Por fin nos han mandado esa canalla.\"},{\"heading\":false,\"text\":\"Otros se levantaban a toda prisa, gruñendo así:\"},{\"heading\":false,\"text\":\"--Vamos a ver a esos condenados.\"},{\"heading\":false,\"text\":\"[15] Alguno apostrofaba de este modo:\"},{\"heading\":false,\"text\":\"--Anticipo forzoso tenemos.... Ellos dicen quintas, contribuciones; nosotros diremos palos y más palos.\"},{\"heading\":false,\"text\":\"En otra casa se oyeron estas palabras, pronunciadas con alegría:\"},{\"heading\":false,\"text\":\"[20] --¡Si vendrá mi hij!... ¡Si vendrá mi hermano!...\"},{\"heading\":false,\"text\":\"Todo era saltar del lecho, vestirse a prisa, abrir las ventanas para ver el alborotador regimiento que entraba con las primeras luces del día. La ciudad era tristeza, silencio, vejez; el ejército alegría, estrépito, juventud. Entrando el [25] uno en la otra, parecía que la momia recibía por arte maravillosa el don de la vida, y bulliciosa saltaba fuera del húmedo sarcófago para bailar en torno de él. ¡Qué movimiento, qué algazara, qué risas, qué jovialidad! No existe nada tan interesante como un ejército. Es la patria en su aspecto juvenil y vigoroso. Lo que en el concepto individual 124 tiene o puede tener esa misma patria de inepta, de levantisca, de supersticiosa unas veces, de blasfema otras, desaparece bajo la presión férrea de la disciplina, que de [5] tantas figurillas insignificantes hace un conjunto prodigioso. El soldado, o sea el corpúsculo, al desprenderse, después de un _rompan filas_, de la masa en que ha tenido vida regular y a veces sublime, suele conservar algunas de las cualidades peculiares del ejército. Pero esto no es lo más común. A [10] la separación suele acompañar súbito encanallamiento, de lo cual resulta que si un ejército es gloria y honor, una reunión de soldados puede ser calamidad insoportable, y los pueblos que lloran de júbilo y entusiasmo al ver entrar en su recinto un batallón victorioso, gimen de espanto y tiemblan [15] de recelo cuando ven libres y sueltos a los señores soldados.\"},{\"heading\":false,\"text\":\"Esto último sucedió en Orbajosa, porque en aquellos días no había glorias que cantar ni motivo alguno para tejer coronas ni trazar letreros triunfales, ni mentar siquiera [20] hazañas de nuestros bravos, por cuya razón todo fué miedo y desconfianza en la episcopal ciudad, que si bien pobre, no carecía de tesoros en gallinas, frutas, dinero y doncellez, los cuales corrían gran riesgo desde que entraron los consabidos alumnos de Marte. Además de esto, la patria de los [25] Polentinos, como ciudad muy apartada del movimiento y bullicio que han traído el tráfico, los periódicos, ferrocarriles y otros agentes que no hay para qué analizar ahora, no gustaba que la molestasen en su sosegada existencia.\"},{\"heading\":false,\"text\":\"Siempre que se le ofrecía coyuntura propicia, mostraba [30] asimismo viva repulsión a someterse a la autoridad central que mal o bien nos gobierna; y recordando sus fueros de antaño y mascullándolos de nuevo, como rumia el camello la yerba que ha comido el día antes, solía hacer alarde de cierta independencia levantisca, deplorables resabios de behetría que a veces dieron no pocos quebraderos de cabeza 125 al gobernador de la provincia.\"},{\"heading\":false,\"text\":\"Otrosí debe tenerse en cuenta que Orbajosa tenía antecedentes, o mejor dicho abolengo faccioso. Sin duda conservaba [5] en su seno algunas fibras enérgicas de aquellas que] en edad remota, según la entusiasta opinión de don Cayetano, la impulsaron a inauditas acciones épicas; y aunque en decadencia, sentía de vez en cuando violento afán de hacer grandes cosas, aunque fueran barbaridades y desatinos. [10] Como dió al mundo tantos egregios hijos, quería sin duda que sus actuales vástagos, los Caballucos, Merengues y Pelosmalos renovasen las _Gestas_ gloriosas de los de antaño.\"},{\"heading\":false,\"text\":\"Siempre que hubo facciones en España, aquel pueblo dió [15] a entender que no existía en vano sobre la faz de la tierra, si bien nunca sirvió de teatro a una verdadera guerra. Su genio, su situación, su historia la reducían al papel secundario de levantar partidas. Obsequió al país con esta fruta nacional en 1827 cuando los Apostólicos, durante la guerra [20] de los siete años, en 1848, y en otras épocas de menos eco en la historia patria. Las partidas y los partidarios fueron siempre populares, circunstancia funesta que procedía de la guerra de la Independencia, una de esas cosas buenas que han sido origen de infinitas cosas detestables. _Corruptio [25] optimi pessima_. Y con la popularidad de las partidas y de los partidarios, coincidía, siempre creciente, la impopularidad de todo lo que entraba en Orbajosa con visos de delegación o instrumento del poder central. Los soldados fueron siempre tan mal vistos allí, que siempre que los ancianos [30] narraban un crimen, robo, asesinato, violación, o cualquiera otro espantable desafuero, añadían: _esto sucedió cuando vino la tropa_.\"},{\"heading\":false,\"text\":\"Y ya que se ha dicho esto tan importante, bueno será añadir que los batallones enviados allá en los mismos días de la historia que referimos, no iban a pasearse por las 126 calles, pues que llevaban un objeto que clara y detalladamente se verá más adelante. Como dato de no escaso interés, apuntaremos que lo que aquí se va contando ocurrió [5] en un año que no está muy cerca del presente, ni tampoco muy lejos, así como también se puede decir que Orbajosa (entre los romanos _urbs augusta_, si bien algunos eruditos modernos examinando el _ajosa_, opinan que este rabillo lo tiene por ser patria de los mejores ajos del mundo), no está [10] muy lejos ni tampoco muy cerca de Madrid, no debiendo tampoco asegurarse que enclave sus gloriosos cimientos al Norte ni al Sur, ni al Este ni al Oeste, sino que es posible esté en todas partes, y por do quiera que los españoles revuelvan sus ojos y sientan el picar de sus ajos.\"},{\"heading\":false,\"text\":\"[15] Repartidas por el municipio las cédulas de alojamiento, cada cual se fué en busca de su hogar prestado. Les recibían de muy mal talante, dándoles acomodo en los lugares más atrozmente inhabitables de las casas. Las muchachas del pueblo no eran en verdad las más descontentas; pero [20] se ejercía sobre ellas una gran vigilancia, y no era decente mostrar alegría por la visita de tal canalla. Los pocos soldados hijos de la comarca eran los únicos que estaban a cuerpo de rey. Los demás eran considerados como extranjeros.\"},{\"heading\":false,\"text\":\"[25] A las ocho de la mañana un teniente coronel de caballería entró con su cédula en casa de doña Perfecta Polentinos. Recibiéronle los criados, por encargo de su señora, que hallándose en deplorable situación de ánimo, no quiso bajar al encuentro del soldadote, y señaláronle para vivienda [30] la única habitación al parecer disponible de la casa, el cuarto que ocupaba Pepe Rey.\"},{\"heading\":false,\"text\":\"--Que se acomoden como puedan--dijo doña Perfecta con expresión de hiel y vinagre.--Y si no caben que se vayan a la calle.\"},{\"heading\":false,\"text\":\"¿Era su intención molestar de este modo al infame 127 sobrino, o realmente no había en el edificio otra pieza disponible? No lo sabemos, ni las crónicas de donde esta verídica historia ha salido dicen una palabra acerca de tan [5] importante cuestión. Lo que sabemos de un modo incontrovertible es que lejos de mortificar a los dos huéspedes que les embaularan juntos, causóles sumo gusto por ser amigos antiguos. Grande y alegre sorpresa tuvieron uno y [10] y lanzar exclamaciones, ponderando la extraña casualidad que los unía en tal sitio y ocasión.\"},{\"heading\":false,\"text\":\"--Pinzón... ¡tú por aquí!... ¿Pero qué es esto? No sospechaba que estuvieras tan cerca...\"},{\"heading\":false,\"text\":\"--Yo oí decir que andabas por estas tierras, Pepe Rey; [15] pero tampoco creí encontrarte en la horrible, en la salvaje Orbajosa.\"},{\"heading\":false,\"text\":\"--¡Pero qué casualidad feliz!... porque esta casualidad es felicísima, providencial... Pinzón, entre tú y yo vamos a hacer algo grande en este poblacho.\"},{\"heading\":false,\"text\":\"[20] --Y tendremos tiempo de meditarlo--repuso el otro sentándose en el lecho donde el ingeniero estaba acostado,--porque según parece viviremos los dos en esta pieza. ¿Qué demonios de casa es ésta?\"},{\"heading\":false,\"text\":\"--Hombre, la de mi tía. Habla con más respeto. ¿No [25] conoces a mi tía?... Pero voy a levantarme.\"},{\"heading\":false,\"text\":\"--Me alegro, porque con eso me acostaré yo, que bastante lo necesito... ¡Qué camino, amigo Pepe, qué camino y qué pueblo!\"},{\"heading\":false,\"text\":\"--Dime, ¿venís a pegar fuego a Orbajosa?\"},{\"heading\":false,\"text\":\"[30] --¡Fuego!\"},{\"heading\":false,\"text\":\"--Dígolo porque yo tal vez os ayudaría.\"},{\"heading\":false,\"text\":\"--¡Qué pueblo! ¡pero qué pueblo!--exclamó el militar tirando el chacó, poniendo a un lado espada y tahalí, cartera de viaje y capote.--Es la segunda vez que nos mandan aquí. Te juro que a la tercera pido la licencia 128 absoluta.\"},{\"heading\":false,\"text\":\"--No hables mal de esta buena gente. ¡Pero qué a tiempo has venido! Parece que te manda Dios en mi [5] ayuda, Pinzón... Tengo un proyecto terrible, una aventura, si quieres llamarla así, un plan, amigo mío... y me hubiera sido muy difícil salir adelante sin ti. Hace un momento me volvía loco cavilando y dije lleno de ansiedad: \\\"Si yo tuviera aquí un amigo, un buen amigo\\\"... [10] --Proyecto, plan, aventura... Una de dos, señor matemático, o es dar la dirección a los globos o algo de amores...\"},{\"heading\":false,\"text\":\"--Es formal, muy formal. Acuéstate, duerme un poco y después hablaremos.\"},{\"heading\":false,\"text\":\"[15] --Me acostaré, pero no dormiré. Puedes contarme todo lo que quieras. Sólo te pido que hables lo menos posible de Orbajosa.\"},{\"heading\":false,\"text\":\"--Precisamente de Orbajosa te quiero hablar. ¿Pero tú también tienes antipatía a esa cuna de tantos varones [20] insignes?\"},{\"heading\":false,\"text\":\"--Estos ajeros... Los llamamos los ajeros... pues digo que serán todo lo insignes que tú quieras; pero a mí me pican como los frutos del país. Este es un pueblo dominado por gentes que enseñan la desconfianza, la superstición [25] y el aborrecimiento a todo el género humano. Cuando estemos despacio te contaré un sucedido... un lance, mitad gracioso, mitad terrible que me pasó aquí el año pasado... Cuando te lo cuente tú te reirás y yo echaré chispas de cólera... Pero en fin, lo pasado, [30] pasado.\"},{\"heading\":false,\"text\":\"--Lo que a mí me pasa no tiene nada de gracioso.\"},{\"heading\":false,\"text\":\"--Pero los motivos de mi aborrecimiento a este poblachón son diversos. Has de saber que aquí asesinaron a mi padre el 48 unos desalmados partidarios. Era brigadier y estaba fuera de servicio. Llamóle el Gobierno, y pasaba 129 por Villahorrenda para ir a Madrid, cuando fué cogido por media docena de tunantes... Aquí hay varias dinastías de guerrilleros. Los Aceros, los Caballucos, los Pelosmalos... un [5] periódico suelto, como dijo quien sabía muy bien lo que decía.\"},{\"heading\":false,\"text\":\"--Supongo que la venida de dos regimientos con alguna caballería no será por gusto de visitar estos amenos vergeles.\"},{\"heading\":false,\"text\":\"--¿Qué ha de ser? Venimos a recorrer el país. Hay [10] muchos depósitos de armas. El Gobierno no se atreve a destituir a la mayor parte de los Ayuntamientos sin desparramar algunas compañías por estos pueblos. Como hay tanta agitación facciosa por esta tierra; como dos provincias cercanas están ya infestadas, y como además este distrito [15] municipal de Orbajosa tiene una historia tan brillante en todas las guerras civiles, hay temores de que los bravos de por aquí se echen a los caminos a saquear lo que encuentren.\"},{\"heading\":false,\"text\":\"--¡Buena precaución! Pero creo que mientras esta [20] gente no perezca y vuelva a nacer; mientras hasta las piedras no muden de forma, no habrá paz en Orbajosa.\"},{\"heading\":false,\"text\":\"--Ésa es también mi opinión--dijo el militar encendiendo un cigarrillo.--¿No ves que los partidarios son la gente mimada en este país? A todos los que asolaron la [25] comarca en 1848 y en otras épocas, o a falta de ellos a sus hijos, les encuentras colocados en los fielatos, en puertas, en el Ayuntamiento, en la conducción del correo: los hay que son alguaciles, sacristanes, comisionados de apremios. Algunos se han hecho temibles caciques, y son los que [30] amasan las elecciones y tienen influjo en Madrid, reparten destinos... en fin, esto da grima.\"},{\"heading\":false,\"text\":\"--Dime, ¿y no se podrá esperar que los partidarios hagan una fechoría en estos días? Si así fuera, ustedes arrasarían el pueblo, y yo les ayudaría.\"},{\"heading\":false,\"text\":\"--Si en mí consistiera... Ellos harán de las suyas--dijo 130 Pinzón,--porque las facciones de las dos provincias cercanas crecen como una maldición de Dios. Y acá para entre los dos, amigo Rey, yo creo que esto va largo. Algunos [5] se ríen y aseguran que no puede haber otra guerra civil] como la pasada. No conocen el país, no conocen a Orbajosa y sus habitantes. Yo sostengo que esto que ahora empieza lleva larga cola, y que tendremos una nueva lucha cruel y sangrienta que durará lo que Dios quiera. ¿Qué [10] opinas tú?\"},{\"heading\":false,\"text\":\"--Amigo, en Madrid me reía yo de todos los que hablaban de la posibilidad de una guerra civil tan larga y terrible como la de siete años; pero ahora, después que estoy aquí...\"},{\"heading\":false,\"text\":\"[15] --Es preciso engolfarse en estos países encantadores: ver de cerca esta gente y oírle dos palabras para saber de qué pie cojea.\"},{\"heading\":false,\"text\":\"--Pues sí... sin poderme explicar en qué fundo mis ideas, ello es que desde aquí veo las cosas de otra manera, [20] y pienso en la posibilidad de largas y feroces guerras.\"},{\"heading\":false,\"text\":\"--Exactamente.\"},{\"heading\":false,\"text\":\"--Pero ahora, más que la guerra pública, me preocupa una privada en que estoy metido y que he declarado hace poco.\"},{\"heading\":false,\"text\":\"[25] --¿Dijiste que ésta es la casa de tu tía? ¿Cómo se llama?\"},{\"heading\":false,\"text\":\"--Doña Perfecta Rey de Polentinos.\"},{\"heading\":false,\"text\":\"--¡Ah! La conozco de nombre. Es una persona excelente, y la única de quien no he oído hablar mal a los [30] ajeros. Cuando estuve aquí la otra vez, en todas partes oía ponderar su bondad, su caridad, sus virtudes.\"},{\"heading\":false,\"text\":\"--Sí, mi tía es muy bondadosa, muy amable--dijo Rey.\"},{\"heading\":false,\"text\":\"Después quedó pensativo breve rato.\"},{\"heading\":false,\"text\":\"--Pero ahora recuerdo...--exclamó de súbito Pinzón.--Cómo 131 se van atando cabos... Sí, en Madrid me dijeron que te casabas con una prima. Todo está descubierto. ¿Es aquella linda y celestial Rosarito?...\"},{\"heading\":false,\"text\":\"[5] --Pinzón, vamos a hablar detenidamente.\"},{\"heading\":false,\"text\":\"--Se me figura que hay contrariedades.\"},{\"heading\":false,\"text\":\"--Hay algo más. Hay luchas terribles. Se necesitan amigos poderosos, listos, de iniciativa, de gran experiencia en los lances difíciles, de gran astucia y valor.\"},{\"heading\":false,\"text\":\"[10] --Hombre, eso es todavía más grave que un desafío.\"},{\"heading\":false,\"text\":\"--Mucho más grave. Se bate uno fácilmente con otro hombre. Con mujeres, con invisibles enemigos que trabajan en la sombra, es imposible.\"},{\"heading\":false,\"text\":\"--Vamos: ya soy todo oídos.\"},{\"heading\":false,\"text\":\"[15] El teniente coronel Pinzón descansaba cuan largo era sobre el lecho. Pepe Rey acercó una silla y apoyando en el mismo lecho el codo y en la mano la cabeza, empezó su conferencia, consulta, exposición de plan o lo que fuera, y habló larguísimo rato. Oíale Pinzón con curiosidad profunda [20] y sin decir nada, salvo algunas preguntillas sueltas para pedir nuevos datos o la aclaración de alguna obscuridad. Cuando Rey concluyó, Pinzón estaba serio. Estiróse en la cama, desperezándose con la placentera convulsión de quien no ha dormido en tres noches, y después dijo así:\"},{\"heading\":false,\"text\":\"[25] --Tu plan es arriesgado y difícil.\"},{\"heading\":false,\"text\":\"--Pero no imposible.\"},{\"heading\":false,\"text\":\"--¡Oh! no, que nada hay imposible en este mundo. Piénsalo bien.\"},{\"heading\":false,\"text\":\"--Ya lo he pensado.\"},{\"heading\":false,\"text\":\"[30] --¿Y estás resuelto a llevarlo adelante? Mira que esas cosas ya no se estilan. Suelen salir mal, y no dejan bien parado a quien las hace.\"},{\"heading\":false,\"text\":\"--Estoy resuelto.\"},{\"heading\":false,\"text\":\"--Pues por mi parte, aunque el asunto es arriesgado y grave, muy grave, estoy dispuesto a ayudarte en todo y por 132 todo.\"},{\"heading\":false,\"text\":\"--¿Cuento contigo?\"},{\"heading\":false,\"text\":\"--Hasta morir.\"}]},{\"title\":\"Capítulo XIX\",\"blocks\":[{\"heading\":false,\"text\":\"=Combate terrible.--Estrategia=\"},{\"heading\":false,\"text\":\"[5] Los primeros fuegos no podían tardar. A la hora de la comida, después de ponerse de acuerdo con Pinzón respecto al plan convenido, cuya primera condición era que ambos amigos fingirían no conocerse, Pepe Rey fué al comedor. Allí encontró a su tía que acababa de llegar de la catedral, [10] donde pasaba, según su costumbre, toda la mañana. Estaba sola y parecía hondamente preocupada. El ingeniero observó que sobre aquel semblante pálido y marmóreo, no exento de cierta hermosura, se proyectaba la misteriosa sombra de un celaje. Al mirar recobraba la claridad [15] siniestra; pero miraba poco, y después de una rápida observación del rostro de su sobrino, el de la bondadosa dama se ponía otra vez en su estudiada penumbra.\"},{\"heading\":false,\"text\":\"Aguardaban en silencio la comida. No esperaron a D. Cayetano, porque éste había ido a Mundogrande. Cuando [20] empezaron a comer, doña Perfecta dijo:\"},{\"heading\":false,\"text\":\"--Y ese militarote que nos ha regalado hoy el Gobierno, ¿no viene a comer?\"},{\"heading\":false,\"text\":\"--Parece tener más sueño que hambre--repuso el ingeniero sin mirar a su tía.\"},{\"heading\":false,\"text\":\"[25] --¿Le conoces tú?\"},{\"heading\":false,\"text\":\"--No le he visto en mi vida.\"},{\"heading\":false,\"text\":\"--Pues estamos divertidos con los huéspedes que nos manda el Gobierno. Aquí tenemos nuestras camas y nuestra comida para cuando a esos perdidos de Madrid se les [30] antoje disponer de ellas.\"},{\"heading\":false,\"text\":\"--Es que hay temores de que se levanten partidas--dijo 133 Pepe Rey, sintiendo que una centella corría por todos sus miembros,--y el Gobierno está decidido a aplastar a los orbajosenses, a aplastarlos, a hacerlos polvo.\"},{\"heading\":false,\"text\":\"[5] --Hombre, pára, pára por Dios, no nos pulverices--exclamó la señora con sarcasmo.--¡Pobrecitos de nosotros! Ten piedad, hombre, y deja vivir a estas infelices criaturas. Y qué, ¿serás tú de los que ayuden a la tropa en la grandiosa obra de nuestro aplastamiento?\"},{\"heading\":false,\"text\":\"[10] --Yo no soy militar. No haré más que aplaudir cuando vea extirpados para siempre los gérmenes de guerra civil, de insubordinación, de discordia, de behetría, de bandolerismo y de barbarie que existen aquí para vergüenza de nuestra época y de nuestro país.\"},{\"heading\":false,\"text\":\"[15] --Todo sea por Dios.\"},{\"heading\":false,\"text\":\"--Orbajosa, querida tía, casi no tiene más que ajos y bandidos, porque bandidos son los que en nombre de una idea política o religiosa, se lanzan a correr aventuras cada cuatro o cinco años.\"},{\"heading\":false,\"text\":\"[20] --Gracias, gracias, querido sobrino--dijo doña Perfecta, palideciendo.--¿Con que Orbajosa no tiene más que eso? Algo más habrá aquí, algo más que tú no tienes y que has venido a buscar entre nosotros.\"},{\"heading\":false,\"text\":\"Rey sintió el bofetón. Su alma se quemaba. Érale muy [25] difícil guardar a su tía las consideraciones que por sexo, estado y posición merecía. Hallábase en el disparadero de la violencia, y un ímpetu irresistible le empujaba, lanzándole contra su interlocutora.\"},{\"heading\":false,\"text\":\"--Yo he venido a Orbajosa--dijo,--porque usted me [30] mandó llamar; usted concertó con mi padre....\"},{\"heading\":false,\"text\":\"--Sí, sí es verdad--repuso la señora, interrumpiéndole vivamente y procurando recobrar su habitual dulzura.--No lo niego. Aquí el verdadero culpable he sido yo. Yo tengo la culpa de tu aburrimiento, de los desaires que nos haces, de todo lo desagradable que en mi casa ocurre con motivo 134 de tu venida.\"},{\"heading\":false,\"text\":\"--Me alegro de que usted lo conozca.\"},{\"heading\":false,\"text\":\"--En cambio, tú eres un santo. ¿Será preciso también [5] que me ponga de rodillas ante tu graciosidad y te pida perdón?...\"},{\"heading\":false,\"text\":\"--Señora--dijo Pepe Rey gravemente, dejando de comer,--ruego a usted que no se burle de mí de una manera tan despiadada. Yo no puedo ponerme en ese terreno.... No [10] he dicho más sino que vine a Orbajosa llamado por usted.\"},{\"heading\":false,\"text\":\"--Y es cierto. Tu padre y yo concertamos que te casaras con Rosario. Viniste a conocerla. Yo te acepté desde luego como hijo.... Tú aparentaste amar a Rosario....\"},{\"heading\":false,\"text\":\"--Perdóneme usted--objetó Pepe.--Yo amaba y amo [15] a Rosario; usted aparentó aceptarme por hijo; usted, recibiéndome con engañosa cordialidad, empleó desde el primer momento todas las artes de la astucia para contrariarme y estorbar el cumplimiento de las proposiciones hechas a mi padre; usted se propuso desde el primer día [20] desesperarme, aburrirme, y con los labios llenos de sonrisas y de palabras cariñosas, me ha estado matando, achicharrándome a fuego lento; usted ha lanzado contra mí en la obscuridad y a mansalva un enjambre de pleitos; usted me ha destituído del cargo oficial que traje a Orbajosa; usted [25] me ha desprestigiado en la ciudad; usted me ha expulsado de la catedral; usted me ha tenido en constante ausencia de la escogida de mi corazón; usted ha mortificado a su hija con un encierro inquisitorial que le hará perder la vida, si Dios no pone su mano en ello.\"},{\"heading\":false,\"text\":\"[30] Doña Perfecta se puso como la grana. Pero aquella viva llamarada de su orgullo ofendido y de su pensamiento descubierto pasó rápidamente dejándola pálida y verdosa. Sus labios temblaban. Arrojando el cubierto con que comía, se levantó de súbito. El sobrino se levantó también. 135\"},{\"heading\":false,\"text\":\"--¡Dios mío, Santa Virgen del Socorro!--exclamó la señora, llevándose ambas manos a la cabeza y comprimiéndosela según el ademán propio de la desesperación.--¿Es posible que yo merezca tan atroces insultos? Pepe, hijo [5] mío, ¿eres tú el que habla?... Si he hecho lo que dices, en verdad que soy muy pecadora.\"},{\"heading\":false,\"text\":\"Dejóse caer en el sofá y se cubrió el rostro con las manos. Pepe, acercándose lentamente a ella, observó el angustioso sollozar de su tía y las lágrimas que abundantemente [10] derramaba. A pesar de su convicción no pudo vencer el ligero enternecimiento que se apoderó de él, y sintiéndose cobarde, experimentó cierta pena por lo mucho y fuerte que había dicho.\"},{\"heading\":false,\"text\":\"--Querida tía--indicó, poniéndole la mano en el hombro.--Si me contesta usted con lágrimas y suspiros, me [15] conmoverá, pero no me convencerá. Razones y no sentimientos me hacen falta. Hábleme usted, dígame que me equivoco al pensar lo que pienso, pruébemelo después, y reconoceré mi error.\"},{\"heading\":false,\"text\":\"--Déjame. Tú no eres hijo de mi hermano. Si lo [20] fueras no me insultarías como me has insultado. ¿Con que yo soy una intrigante, una comedianta, una harpía hipócrita, una diplomática de enredos caseros?...\"},{\"heading\":false,\"text\":\"Al decir esto, la señora había descubierto su rostro y contemplaba a su sobrino con expresión beatífica. Pepe [25] estaba perplejo. Las lágrimas, así como la dulce voz de la hermana de su padre, no podían ser fenómenos insignificantes para el alma del matemático. Las palabras le retozaban en la boca para pedir perdón. Hombre de gran energía por lo común, cualquier accidente de sensibilidad, [30] cualquier agente que obrase sobre su corazón, le trocaba de súbito en niño. Achaques de matemático. Dicen que Newton era también así.\"},{\"heading\":false,\"text\":\"--Yo quiero darte las razones que pides--dijo doña Perfecta, indicándole que se sentase junto a ella.--Yo quiero desagraviarte. Para que veas si soy buena, si soy 136 indulgente, si soy humilde.... ¿Crees que te contradiré, que negaré en absoluto los hechos de que me has acusado?... Pues no, no los niego.\"},{\"heading\":false,\"text\":\"[5] El ingeniero se quedó asombrado.\"},{\"heading\":false,\"text\":\"--No los niego--prosiguió la señora.--Lo que niego es la dañada intención que les atribuyes. ¿Con qué derecho te metes a juzgar lo que no conoces sino por indicios y conjeturas? ¿Tienes tú la suprema inteligencia que se [10] necesita para juzgar de plano las acciones de los demás y dar sentencia sobre ellas? ¿Eres Dios para conocer las intenciones?\"},{\"heading\":false,\"text\":\"Pepe se asombró más.\"},{\"heading\":false,\"text\":\"--¿No es lícito emplear alguna vez en la vida medios [15] indirectos para conseguir un fin bueno y honrado? ¿Con qué derecho juzgas acciones mías que no comprendes bien? Yo, querido sobrino, ostentando una sinceridad que tú no mereces, te confieso que sí, que efectivamente me he valido de subterfugios para conseguir un fin bueno, para conseguir [20] lo que al mismo tiempo era beneficioso para ti y para mi hija.... ¿No comprendes? Parece que estás lelo.... ¡Ah! Tu gran entendimiento de matemático y de filósofo alemán no es capaz de penetrar estas sutilezas de una madre prudente.\"},{\"heading\":false,\"text\":\"[25] --Es que me asombro más y más cada vez--dijo el ingeniero.\"},{\"heading\":false,\"text\":\"--Asómbrate todo lo que quieras, pero confiesa tu barbaridad--manifestó la dama, aumentando en bríos;--reconoce tu ligereza y brutal comportamiento conmigo, al [30] acusarme como lo has hecho. Eres un mozalvete sin experiencia ni otro saber que el de los libros, que nada enseñan del mundo ni del corazón. Tú de nada entiendes más que de hacer caminos y muelles. ¡Ay! señorito mío. En el corazón humano no se entra por los túneles de los ferrocarriles, ni se baja a sus hondos abismos por los pozos de las 137 minas. No se lee en la conciencia ajena con los microscopios de los naturalistas, ni se decide la culpabilidad del prójimo nivelando las ideas con teodolito.\"},{\"heading\":false,\"text\":\"[5] --¡Por Dios, querida tía!...\"},{\"heading\":false,\"text\":\"--¿Para qué nombras a Dios si no crees en él?--dijo doña Perfecta con solemne acento.--Si creyeras en él, si fueras buen cristiano, no aventurarías pérfidos juicios sobre mi conducta. Yo soy una mujer piadosa, ¿entiendes? Yo [10] tengo mi conciencia tranquila, ¿entiendes? Yo sé lo que hago y por qué lo hago, ¿entiendes?\"},{\"heading\":false,\"text\":\"--Entiendo, entiendo, entiendo.\"},{\"heading\":false,\"text\":\"--Dios, en quien tú no crees, ve lo que tú no ves ni puedes ver, el intento. Y no te digo más; no quiero entrar en [15] explicaciones largas porque no lo necesito. Tampoco me entenderías si te dijera que deseaba alcanzar mi objeto sin escándalo, sin ofender a tu padre, sin ofenderte a ti, sin dar que hablar a las gentes con una negativa explícita.... Nada de esto te diré, porque tampoco lo entenderás, Pepe. [20] Eres matemático. Ves lo que tienes delante y nada más; la naturaleza brutal y nada más; rayas, ángulos, pesos y nada más. Ves el efecto y no la causa. El que no cree en Dios no ve causas. Dios es la suprema intención del mundo. El que le desconoce, necesariamente ha de juzgar [25] de todo como juzgas tú, a lo tonto. Por ejemplo, en la tempestad no ve más que destrucción, en el incendio estragos, en la sequía miseria, en los terremotos desolación, y sin embargo, orgulloso señorito, en todas esas aparentes calamidades, hay que buscar la bondad de la intención... [30] sí señor, la intención siempre buena de quien no puede hacer nada malo.\"},{\"heading\":false,\"text\":\"Esta embrollada, sutil y mística dialéctica no convenció a Rey; pero no quiso seguir a su tía por la áspera senda de tales argumentaciones, y sencillamente le dijo:\"},{\"heading\":false,\"text\":\"--Bueno; yo respeto las intenciones.... 138\"},{\"heading\":false,\"text\":\"--Ahora que pareces reconocer tu error--prosiguió la piadosa señora, cada vez más valiente,--te haré otra confesión, y es que voy comprendiendo que hice mal en [5] adoptar tal sistema, aunque mi objeto era inmejorable. Dado tu carácter arrebatado, dada tu incapacidad para comprenderme, debí abordar la cuestión de frente y decirte: \\\"sobrino mío, no quiero que seas esposo de mi hija.\\\"\"},{\"heading\":false,\"text\":\"--Ese es el lenguaje que debió emplear usted conmigo [10] desde el primer día--repuso el ingeniero, respirando con desahogo, como quien se ve libre de enorme peso.--Agradezco mucho a usted esas palabras. Después de ser acuchillado en las tinieblas, ese bofetón a la luz del día me complace mucho.\"},{\"heading\":false,\"text\":\"[15] --Pues te repito el bofetón, sobrino--afirmó la señora con tanta energía como displicencia.--Ya lo sabes. No quiero que te cases con Rosario.\"},{\"heading\":false,\"text\":\"Pepe calló. Hubo una larga pausa, durante la cual los dos estuvieron mirándose atentamente, cual si la cara de cada [20] uno fuese para el contrario la más perfecta obra del arte.\"},{\"heading\":false,\"text\":\"--¿No entiendes lo que te he dicho?--repitió ella.--Que se acabó todo, que no hay boda.\"},{\"heading\":false,\"text\":\"--Permítame usted, querida tía--dijo el joven con entereza,--que no me aterre con la intimación. En el estado [25] a que han llegado las cosas, la negativa de usted es de escaso valor para mí.\"},{\"heading\":false,\"text\":\"--¿Qué dices?--gritó fulminante doña Perfecta.\"},{\"heading\":false,\"text\":\"--Lo que usted oye. Me casaré con Rosario.\"},{\"heading\":false,\"text\":\"Doña Perfecta se levantó indignada, majestuosa, terrible. [30] Su actitud era la del anatema hecho mujer. Rey permaneció sentado, sereno, valiente, con el valor pasivo de una creencia profunda y de una resolución inquebrantable. El desplome de toda la iracundia de su tía, que le amenazaba, no le hizo pestañear. Él era así.\"},{\"heading\":false,\"text\":\"--Eres un loco. ¡Casarte tú con mi hija, casarte tú con 139 ella, no queriendo yo!...\"},{\"heading\":false,\"text\":\"Los labios trémulos de la señora articularon estas palabras con el verdadero acento de la tragedia.\"},{\"heading\":false,\"text\":\"[5] --¡No queriendo usted!... Ella opina de distinto modo.\"},{\"heading\":false,\"text\":\"--¡No queriendo yo!...--repitió la dama.--Sí, y lo digo y lo repito: no quiero, no quiero.\"},{\"heading\":false,\"text\":\"--Ella y yo lo deseamos.\"},{\"heading\":false,\"text\":\"[10] --Menguado, ¿acaso no hay en el mundo más que ella y tú? ¿No hay padres, no hay sociedad, no hay conciencia, no hay Dios?\"},{\"heading\":false,\"text\":\"--Porque hay sociedad, porque hay conciencia, porque hay Dios--afirmó gravemente Rey, levantándose y alzando [15] el brazo y señalando al cielo,--digo y repito que me casaré con ella.\"},{\"heading\":false,\"text\":\"--¡Miserable, orgulloso! Y si todo lo atropellaras, ¿crees que no hay leyes para impedir tu violencia?\"},{\"heading\":false,\"text\":\"--Porque hay leyes digo y repito que me casaré con [20] ella.\"},{\"heading\":false,\"text\":\"--Nada respetas.\"},{\"heading\":false,\"text\":\"--Nada que sea indigno de respeto.\"},{\"heading\":false,\"text\":\"--Y mi autoridad, y mi voluntad, yo... ¿yo no soy nada?\"},{\"heading\":false,\"text\":\"[25] --Para mí su hija de usted es todo: lo demás nada.\"},{\"heading\":false,\"text\":\"La entereza de Pepe Rey era como los alardes de una fuerza incontrastable, con perfecta conciencia de sí misma. Daba golpes secos, contundentes, sin atenuación de ningún género. Sus palabras parecían, si es permitida la comparación, [30] una artillería despiadada.\"},{\"heading\":false,\"text\":\"Doña Perfecta cayó de nuevo en el sofá; pero no lloraba, y una convulsión nerviosa agitaba sus miembros.\"},{\"heading\":false,\"text\":\"--De modo que para este ateo infame--exclamó con franca rabia,--no hay conveniencias sociales, no hay nada más que un capricho. Eso es una avaricia indigna. Mi 140 hija es rica.\"},{\"heading\":false,\"text\":\"--Si piensa usted herirme con esa arma sutil, tergiversando la cuestión e interpretando torcidamente mis [5] sentimientos, para lastimar mi dignidad, se equivoca, querida tía. Llámeme usted avaro. Dios sabe lo que soy.\"},{\"heading\":false,\"text\":\"--No tienes dignidad.\"},{\"heading\":false,\"text\":\"--Ésa es una opinión como otra cualquiera. El mundo podrá tenerla a usted en olor de infalibilidad. Yo no. Estoy [10] muy lejos de creer que las sentencias de usted no tengan apelación ante Dios.\"},{\"heading\":false,\"text\":\"--¿Pero es cierto lo que dices?... ¿Pero insistes después de mi negativa?... Tú lo atropellas todo, eres un monstruo, un bandido.\"},{\"heading\":false,\"text\":\"[15] --Soy un hombre.\"},{\"heading\":false,\"text\":\"--¡Un miserable! Acabemos: yo te niego a mi hija, yo te la niego.\"},{\"heading\":false,\"text\":\"--¡Pues yo la tomaré! No tomo más que lo que es mío.\"},{\"heading\":false,\"text\":\"--Quítate de mi presencia--exclamó la señora, levantándose [20] de súbito.--Fatuo, ¿crees que mi hija se acuerda de ti?\"},{\"heading\":false,\"text\":\"--Me ama, lo mismo que yo a ella.\"},{\"heading\":false,\"text\":\"--¡Mentira, mentira!\"},{\"heading\":false,\"text\":\"--Ella misma me lo ha dicho. Dispénseme usted si en esta cuestión doy más fe a la opinión de ella que a la de [25] su mamá.\"},{\"heading\":false,\"text\":\"--¿Cuándo te lo ha dicho, si no la has visto en muchos días?\"},{\"heading\":false,\"text\":\"--La he visto anoche y me ha jurado ante el Cristo de la capilla que sería mi mujer.\"},{\"heading\":false,\"text\":\"[30] --¡Oh escándalo y libertinaje!... ¿Pero qué es esto? ¡Dios mío, qué deshonra!--exclamó doña Perfecta comprimiéndose otra vez con ambas manos la cabeza y dando algunos pasos por la habitación.--¿Rosario salió anoche de su cuarto?\"},{\"heading\":false,\"text\":\"--Salió para verme. Ya era tiempo. 141\"},{\"heading\":false,\"text\":\"--¡Qué vil conducta la tuya! Has procedido como los ladrones, has procedido como los seductores adocenados.\"},{\"heading\":false,\"text\":\"--He procedido según la escuela de usted. Mi intención [5] era buena.\"},{\"heading\":false,\"text\":\"--¡Y ella bajó!... ¡Ah! lo sospechaba. Esta mañana al amanecer la sorprendí vestida en su cuarto. Díjome que había salido no sé a qué.... El verdadero criminal lo eres tú, tú.... Esto es una deshonra. Pepe, esperaba [10] todo de ti, menos tan grande ultraje.... Todo acabó. Márchate. No existes para mí. Te perdono, con tal de que te vayas.... No diré una palabra de esto a tu padre.... ¡Qué horrible egoísmo! No, no hay amor en ti. ¡Tú no amas a mi hija!\"},{\"heading\":false,\"text\":\"[15] --Dios sabe que la adoro, y me basta.\"},{\"heading\":false,\"text\":\"--No pongas a Dios en tus labios, blasfemo, y calla--exclamó doña Perfecta.--En nombre de Dios, a quien puedo invocar, porque creo en él, te digo que mi hija no será jamás tu mujer. Mi hija se salvará, Pepe; mi hija [20] no puede ser condenada en vida al infierno, porque infierno es la unión contigo.\"},{\"heading\":false,\"text\":\"--Rosario será mi esposa--repitió el matemático con patética calma.\"},{\"heading\":false,\"text\":\"Irritábase más la piadosa señora con la energía serena de [25] su sobrino. Con voz entrecortada habló así:\"},{\"heading\":false,\"text\":\"--No creas que me amedrentan tus amenazas. Sé lo que digo. Pues qué, ¿se puede atropellar un hogar, una familia; se puede atropellar la autoridad humana y divina?\"},{\"heading\":false,\"text\":\"--Yo atropellaré todo--dijo el ingeniero, empezando a [30] perder su calma y expresándose con alguna agitación.\"},{\"heading\":false,\"text\":\"--¡Lo atropellarás todo! ¡Ah! Bien se ve que eres un bárbaro, un salvaje, un hombre que vive de la violencia.\"},{\"heading\":false,\"text\":\"--No, querida tía. Soy manso, recto, honrado y enemigo de violencia; pero entre usted y yo, entre usted que es la ley y yo que soy el destinado a acatarla, está una pobre 142 criatura atormentada, un ángel de Dios sujeto a inicuos martirios. Este espectáculo, esta injusticia, esta violencia inaudita es la que convierte mi rectitud en barbarie, mi [5] razón en fuerza, mi honradez en violencia parecida a la de los asesinos y ladrones; este espectáculo, señora mía, es lo que me impulsa a no respetar la ley de usted, lo que me impulsa a pasar sobre ella, atropellándolo todo. Esto que parece un desatino es una ley ineludible. Hago lo que [10] hacen las sociedades, cuando una brutalidad tan ilógica como irritante se opone a su marcha. Pasan por encima y todo lo destrozan con feroz acometida. Tal soy yo en este momento: yo mismo no me conozco. Era razonable y soy un bruto: era respetuoso y soy insolente: era culto y me [15] encuentro salvaje. Usted me ha traído a este horrible extremo, irritándome y apartándome del camino del bien por donde tranquilamente iba. ¿De quién es la culpa, mía o de usted?\"},{\"heading\":false,\"text\":\"--¡Tuya, tuya!\"},{\"heading\":false,\"text\":\"[20] --Ni usted ni yo lo podemos resolver. Creo que ambos carecemos de razón. En usted violencia e injusticia; en mí injusticia y violencia. Hemos venido a ser tan bárbaro el uno como el otro, y luchamos y nos herimos sin compasión. Dios lo permite así. Mi sangre caerá sobre la [25] conciencia de usted, la de usted caerá sobre la mía.... Basta ya, señora. No quiero molestar a usted con palabras inútiles. Ahora entraremos en los hechos.\"},{\"heading\":false,\"text\":\"--¡En los hechos, bien!--dijo doña Perfecta más bien rugiendo que hablando.--No creas que en Orbajosa falta [30] Guardia civil.\"},{\"heading\":false,\"text\":\"--Adiós, señora. Me retiro de esta casa. Creo que nos volveremos a ver.\"},{\"heading\":false,\"text\":\"--Vete, vete, vete ya--gritó ella señalando la puerta con enérgico ademán.\"},{\"heading\":false,\"text\":\"Pepe Rey salió. Doña Perfecta, después de pronunciar 143 algunas palabras incoherentes que eran la más clara expresión de su ira, cayó en un sillón con muestras de cansancio o de ataque nervioso. Acudieron las criadas.\"},{\"heading\":false,\"text\":\"[5] --¡Que vayan a llamar al Sr. D. Inocencio!--gritó.--Al instante... ¡pronto!... ¡que venga!...\"},{\"heading\":false,\"text\":\"Después mordió el pañuelo.\"}]},{\"title\":\"Capítulo XX\",\"blocks\":[{\"heading\":false,\"text\":\"=Rumores.--Temores=\"},{\"heading\":false,\"text\":\"Al día siguiente de esta disputa lamentable, corrieron por toda Orbajosa de casa en casa, de círculo en círculo, [10] desde el Casino a la botica, y desde el paseo de las Descalzas a la puerta de Baidejos, rumores varios sobre Pepe Rey y su conducta. Todo el mundo los repetía, y los comentarios iban siendo tantos, que si D. Cayetano los recogiese y compilase, formaría con ellos un rico _Thesaurum_ de la [15] benevolencia orbajosense. En medio de la diversidad de especies que corrían, había conformidad en algunos puntos culminantes, uno de los cuales era el siguiente:\"},{\"heading\":false,\"text\":\"Que el ingeniero, enfurecido porque doña Perfecta se negaba a casar a Rosario con un ateo, había _alzado la [20] mano_ a su tía.\"},{\"heading\":false,\"text\":\"Estaba viviendo el joven en la posada de la viuda de Cuzco, establecimiento _montado_ como ahora se dice, no a la altura, sino a la bajeza de los más primorosos atrasos del país. Visitábale con frecuencia el teniente coronel [25] Pinzón, para ponerse de acuerdo respecto al enredo que entre manos traían, y para cuyo eficaz desempeño mostraba el soldado felices disposiciones. Ideaba a cada instante nuevas travesuras y artimañas, apresurándose a llevarlas del pensamiento a la obra con excelente humor, si bien solía [30] decir a su amigo:\"},{\"heading\":false,\"text\":\"--El papel que estoy haciendo, querido Pepe, no se debe 144 contar entre los más airosos; pero por dar un disgusto a Orbajosa y su gente, andaría yo a cuatro pies.\"},{\"heading\":false,\"text\":\"No sabemos qué sutiles trazas empleó el ladino militar, [5] maestro en ardides del mundo; pero lo cierto es que a los tres días de alojamiento había logrado hacerse muy simpático en la casa. Agradaba su trato a doña Perfecta, que no podía oír sin emoción sus zalameras alabanzas del buen porte de la casa, de la grandeza, piedad y magnificencia [10] augusta de la señora. Con D. Inocencio estaba a partir un confite. Ni la madre, ni el Penitenciario le estorbaban que hablase a Rosario (a quien se dió libertad después de la ausencia del feroz primo); y con sus cortesanías alambicadas, su hábil lisonja y destreza suma, adquirió en la casa [15] de Polentinos considerable auge y hasta familiaridad. Pero el objeto de todas sus artes era una criada, que tenía por nombre Librada, a quien sedujo (castamente hablando) para que transportase recados y cartitas a Rosario, fingiéndose enamorado de ésta. No resistió la muchacha al [20] soborno, realizado con bonitas palabras y mucho dinero, porque ignoraba la procedencia de las esquelas y el verdadero sentido de tales líos; pues si llegara a entender que todo era una nueva diablura de D. José, aunque éste le gustaba mucho, no hiciera traición a su señora por todo el [25] dinero del mundo.\"},{\"heading\":false,\"text\":\"Estaban un día en la huerta doña Perfecta, D. Inocencio, Jacinto y Pinzón. Hablóse de la tropa y de la misión que traía a Orbajosa, en cuyo tratado el señor Penitenciario halló tema para condenar la tiránica conducta del Gobierno, [30] y, sin saber cómo, nombraron a Pepe Rey.\"},{\"heading\":false,\"text\":\"--Todavía está en la posada--dijo el abogadillo.--Le he visto ayer, y me ha dado memorias para usted, doña Perfecta.\"},{\"heading\":false,\"text\":\"--¿Hase visto mayor insolencia?... ¡Ah! Sr. Pinzón, no extrañe usted que emplee este lenguaje, tratándose de un sobrino carnal... ya sabe usted... aquel caballerito 145 que se aposentaba en el cuarto que usted ocupa.\"},{\"heading\":false,\"text\":\"--¡Sí, ya lo sé! No le trato; pero le conozco de vista y de fama. Es amigo íntimo de nuestro brigadier.\"},{\"heading\":false,\"text\":\"[5] --¿Amigo íntimo del brigadier?\"},{\"heading\":false,\"text\":\"--Sí, señora, del que manda la brigada que ha venido a este país, y que se ha repartido entre diferentes pueblos.\"},{\"heading\":false,\"text\":\"--¿Y dónde está?--preguntó la dama.\"},{\"heading\":false,\"text\":\"--En Orbajosa.\"},{\"heading\":false,\"text\":\"[10] --Creo que se aposenta en casa de Polavieja--indicó Jacinto.\"},{\"heading\":false,\"text\":\"--Su sobrino de usted--continuó Pinzón,--y el brigadier Batalla son íntimos amigos, se quieren entrañablemente, y a todas horas se les ve juntos por las calles del pueblo.\"},{\"heading\":false,\"text\":\"[15] --Pues, amiguito, mala idea formo de ese señor jefe--repuso doña Perfecta.\"},{\"heading\":false,\"text\":\"--Es un... es un infeliz--dijo Pinzón en el tono propio de quien por respeto no se atreve a aplicar una calificación dura.\"},{\"heading\":false,\"text\":\"[20] --Mejorando lo presente, Sr. Pinzón, y haciendo una salvedad honrosísima en honor de usted--afirmó la señora--no puede negarse que en el ejército español hay cada tipo....\"},{\"heading\":false,\"text\":\"--Nuestro brigadier era un excelente militar antes de darse al espiritismo....\"},{\"heading\":false,\"text\":\"[25] --¡Al espiritismo!\"},{\"heading\":false,\"text\":\"--¡Esa secta que llama a los fantasmas y duendes por medio de las patas de las mesas!...--exclamó el canónigo riendo.\"},{\"heading\":false,\"text\":\"--Por curiosidad, sólo por curiosidad--dijo Jacintillo [30] con énfasis,--he encargado a Madrid la obra de Allan Cardec. Bueno es enterarse de todo.\"},{\"heading\":false,\"text\":\"--¿Pero es posible que tales disparates?... ¡Jesús! Dígame usted, Pinzón, ¿mi sobrino también es de esa secta de pie de banco?\"},{\"heading\":false,\"text\":\"--Me parece que él fué quien catequizó a nuestro bravo 146 brigadier Batalla.\"},{\"heading\":false,\"text\":\"--¡Pero, Jesús!\"},{\"heading\":false,\"text\":\"--Eso es; y cuando se le antoje--dijo don Inocencio [5] sin poder contener la risa--hablará con Sócrates, San Pablo, Cervántes y Descartes, como hablo yo ahora con Librada para pedirle un fosforito. ¡Pobre Sr. de Rey! Bien dije yo que aquella cabeza no estaba buena.\"},{\"heading\":false,\"text\":\"--Por lo demás--continuó Pinzón,--nuestro brigadier [10] es un buen militar. Si de algo peca es de excesivamente duro. Toma tan al pie de la letra las órdenes del Gobierno, que si le contrarían mucho aquí, será capaz de no dejar piedra sobre piedra en Orbajosa. Sí, les prevengo a ustedes que estén con cuidado.\"},{\"heading\":false,\"text\":\"[15] --Pero ese monstruo nos va a cortar la cabeza a todos. ¡Ay! Sr. D. Inocencio, estas visitas de la tropa me recuerdan lo que he leído en la vida de los mártires, cuando se presentaba un procónsul romano en un pueblo de cristianos....\"},{\"heading\":false,\"text\":\"[20] --No deja de ser exacta la comparación--dijo el[20] Penitenciario, mirando al militar por encima de las gafas.\"},{\"heading\":false,\"text\":\"--Es un poco triste; pero siendo verdad, debe decirse--manifestó Pinzón con benevolencia.--Ahora, señores míos, están ustedes a merced de nosotros.\"},{\"heading\":false,\"text\":\"[25] --Las autoridades del país--objetó Jacinto,--funcionan aún perfectamente.\"},{\"heading\":false,\"text\":\"--Creo que se equivoca usted--repuso el soldado, cuya fisonomía observaban con profundo interés la señora y el Penitenciario.--Hace una hora ha sido destituído el alcalde [30] de Orbajosa.\"},{\"heading\":false,\"text\":\"--¿Por el gobernador de la provincia?\"},{\"heading\":false,\"text\":\"--El gobernador ha sido sustituído por un delegado del Gobierno que debió llegar esta mañana. Los Ayuntamientos todos cesarán hoy. Así lo ha mandado el ministro, porque temía, no sé con qué motivo, que no prestaban apoyo 147 a la autoridad central.\"},{\"heading\":false,\"text\":\"--Bien, bien estamos--murmuró el canónigo frunciendo el ceño y echando adelante el labio inferior.\"},{\"heading\":false,\"text\":\"[5] Doña Perfecta meditaba.\"},{\"heading\":false,\"text\":\"--También han sido quitados algunos jueces de primera instancia, entre ellos el de Orbajosa.\"},{\"heading\":false,\"text\":\"--¡El juez! ¡Periquito!... ¿Ya no es juez Periquito?--exclamó doña Perfecta con voz y gesto semejantes [10] a los de las personas que tienen la desgracia de ser picadas por una víbora.\"},{\"heading\":false,\"text\":\"--Ya no es juez de Orbajosa el que lo era--dijo Pinzón.--Mañana vendrá el nuevo.\"},{\"heading\":false,\"text\":\"--¡Un desconocido!\"},{\"heading\":false,\"text\":\"[15] --¡Un desconocido!\"},{\"heading\":false,\"text\":\"--Un tunante quizás.... ¡El otro era tan honrado!...--dijo la señora con zozobra.--Jamás le pedí cosa alguna que al punto no me concediera. ¿Sabe usted quién será el alcalde nuevo?\"},{\"heading\":false,\"text\":\"[20] --Dicen que viene un corregidor.\"},{\"heading\":false,\"text\":\"--Vamos, diga usted de una vez que viene el Diluvio, y acabaremos--manifestó el canónigo levantándose.\"},{\"heading\":false,\"text\":\"--¿De modo que estamos a merced del señor brigadier?\"},{\"heading\":false,\"text\":\"--Por algunos días, ni más ni menos. No se enfaden [25] ustedes conmigo. A pesar de mi uniforme, soy enemigo del militarismo; pero nos mandan pegar... y pegamos. No puede haber oficio más canalla que el nuestro.\"},{\"heading\":false,\"text\":\"--Sí que lo es, sí que lo es--dijo la señora, disimulando mal su furor.--Ya que usted lo ha confesado.... Con [30] que ni alcalde ni juez....\"},{\"heading\":false,\"text\":\"--Ni gobernador de la provincia.\"},{\"heading\":false,\"text\":\"--Que nos quiten también al señor obispo y nos manden un monaguillo en su lugar.\"},{\"heading\":false,\"text\":\"--Es lo que falta.... Si aquí les dejan hacerlo-- murmuró D. Inocencio, bajando los ojos,--no se pararán 148 en pelillos.\"},{\"heading\":false,\"text\":\"--Y todo es porque se teme el levantamiento de partidas en Orbajosa--exclamó la señora, cruzando las manos y [5] agitándolas de arriba a bajo, desde la barba a las rodillas. Francamente, Pinzón, no sé cómo no se levantan hasta las piedras. No le deseo mal ninguno a usted; pero lo justo sería que el agua que beben ustedes se les convirtiera en lodo.... ¿Dijo usted que mi sobrino es íntimo amigo del [10] brigadier?\"},{\"heading\":false,\"text\":\"--Tan íntimo que no se separan en todo el día; fueron compañeros de colegio. Batalla le quiere como un hermano y le complace en todo. En su lugar de usted, señora, yo no estaría tranquilo.\"},{\"heading\":false,\"text\":\"[15] --¡Oh! ¡Dios mío! ¡Temo un atropello!...--exclamó ella muy desasosegada.\"},{\"heading\":false,\"text\":\"--Señora--afirmó el canónigo con energía.--Antes que consentir un atropello en esta honrada casa, antes que consentir el menor vejamen hecho a esta nobilísima familia, yo [20] ... mi sobrino... los vecinos todos de Orbajosa....\"},{\"heading\":false,\"text\":\"Don Inocencio no concluyó. Su cólera era tan viva, que se le trababan las palabras en la boca. Dió algunos pasos marciales, y después se volvió a sentar.\"},{\"heading\":false,\"text\":\"--Me parece que no son vanos esos temores--dijo [25] Pinzón.--En caso necesario yo....\"},{\"heading\":false,\"text\":\"--Y yo....--repitió Jacinto.\"},{\"heading\":false,\"text\":\"Doña Perfecta había fijado los ojos en la puerta vidriera del comedor, tras la cual dejóse ver una graciosa figura. Mirándola, parecía que en el semblante de la señora se [30] ennegrecían más las sombrías nubes del temor.\"},{\"heading\":false,\"text\":\"--Rosario, pasa aquí, Rosario--dijo saliendo a su encuentro.--Se me figura que tienes hoy mejor cara y estás más alegre, sí.... ¿No les parece a ustedes que Rosario tiene mejor cara? Si parece otra.\"},{\"heading\":false,\"text\":\"Todos convinieron en que tenía retratada en su semblante 149 la más viva felicidad.\"}]},{\"title\":\"Capítulo XXI\",\"blocks\":[{\"heading\":false,\"text\":\"=Desperta, ferro=\"},{\"heading\":false,\"text\":\"Por aquellos días publicaron los periódicos de Madrid las siguientes noticias:\"},{\"heading\":false,\"text\":\"[5] \\\"No es cierto que en los alrededores de Orbajosa se haya levantado partida alguna. Nos escriben de aquella localidad que el país está tan poco dispuesto a aventuras, que se considera inútil en aquel punto la presencia de la brigada Batalla.\\\"\"},{\"heading\":false,\"text\":\"[10] \\\"Dícese que la brigada Batalla saldrá de Orbajosa, porque no hacen falta allí fuerzas del ejército, e irá a Villajuán de Nahara, donde han aparecido algunas partidas.\\\"\"},{\"heading\":false,\"text\":\"\\\"Ya es seguro que los Aceros recorren con algunos ginetes el término de Villajuán, próximo al distrito judicial de [15] Orbajosa. El gobernador de la provincia de X... ha telegrafiado al Gobierno diciendo que Francisco Acero entró en las Roquetas, donde cobró un semestre y pidió raciones. Domingo Acero (Faltriquera) vagaba por la sierra del Jubileo, activamente perseguido por la Guardia [20] civil, que le mató un hombre y aprehendió a otro. Bartolomé Acero fué el que quemó el registro civil de Lugarnoble, llevándose en rehenes al alcalde y a dos de los principales propietarios.\\\"\"},{\"heading\":false,\"text\":\"\\\"En Orbajosa reina tranquilidad completa, según carta [25] que tenemos a la vista, y allí no piensan más que en trabajar el campo para la próxima cosecha de ajos, que promete ser magnífica. Los distritos inmediatos sí están infestados de partidas; pero la brigada Batalla dará buena cuenta de ellas.\\\"\"},{\"heading\":false,\"text\":\"En efecto; Orbajosa estaba tranquila.--Los Aceros, 150 aquella dinastía aguerrida, merecedora, según algunas gentes, de figurar en el _Romancero_, había tomado por su cuenta la provincia cercana; pero la insurrección no cundía en el [5] término de la ciudad episcopal. Creeríase que la cultura moderna había al fin vencido en su lucha con las levantiscas costumbres de la gran behetría, y que ésta saboreaba las delicias de una paz duradera. Y esto es tan cierto, que el mismo Caballuco, una de las figuras más caracterizadas de [10] la rebeldía histórica de Orbajosa, decía claramente a todo el mundo que él no quería _reñir con el Gobierno_ ni _meterse en danzas_ que podían costarle caras.\"},{\"heading\":false,\"text\":\"Dígase lo que se quiera, el arrebatado carácter de Ramos había tomado asiento con los años, enfriándose un poco la [15] fogosidad que con la existencia recibiera de los Caballucos padres y abuelos, la mejor casta de guerreros que ha asolado la tierra. Cuéntase además que por aquellos días el nuevo gobernador de la provincia _celebró una conferencia_ con este importante personaje, _oyendo de sus labios las mayores [20] seguridades_ de contribuir al reposo público y evitar toda ocasión de disturbios. Aseguran fieles testigos que se le veía en amor y compaña con los militares, partiendo un piñón con este o el otro sargento en la taberna, y hasta se dijo que le iban a dar un buen destino en el Ayuntamiento de la capital [25] de la provincia. ¡Oh! cuán difícil es para el historiador, que presume de imparcial, depurar la verdad en esto de las opiniones y pensamientos de los insignes personajes que han llenado el mundo con su nombre! No sabe uno a qué atenerse, y la falta de datos ciertos da origen a lamentables [30] equivocaciones. En presencia de hechos tan culminantes como la jornada de Brumario, como el saco de Roma por Borbón, como la ruina de Jerusalén, ¿qué psicólogo, ni qué historiador podrá determinar los pensamientos que les precedieron o les siguieron en la cabeza de Bonaparte, Carlos V y Tito?--¡Responsabilidad inmensa la nuestra! Para 151 librarnos en parte de ella, refiramos palabras, frases y aun discursos del mismo emperador orbajosense, y de este modo cada cual formará la opinión que le parezca más acertada.\"},{\"heading\":false,\"text\":\"[5] No cabe duda alguna de que Cristóbal Ramos salió, ya anochecido, de su casa, y atravesando por la calle del Condestable, vió tres labriegos que en sendas mulas venían en dirección contraria a la suya, y preguntándoles que a dó caminaban, repusieron que a la casa de la señora doña [10] Perfecta a llevarle varias primicias de frutos de las huertas y algún dinero de las rentas vencidas. Eran el señor Pasolargo, un mozo a quien llamaban Frasquito González, y el tercero, de mediana edad y recia complexión, recibía el nombre de Vejarruco, aunque el suyo verdadero era José [15] Esteban Romero. Volvió atrás Caballuco, solicitado por la buena compañía de aquella gente, con quien tenía franca y antigua amistad, y entró con ellos en casa de la señora. Esto ocurría, según los más verosímiles datos, al anochecer, y dos días después de aquél en que doña Perfecta y Pinzón [20] hablaron lo que en el anterior capítulo ha podido ver quien lo ha leído. Entretúvose el gran Ramos dando a Librada ciertos recados de poca importancia que una vecina confiara a su buena memoria, y cuando entró en el comedor ya los tres labriegos antes mencionados y el señor Licurgo, que [25] asimismo por singular coincidencia estaba presente, habían entablado conversación sobre asuntos de la cosecha y de la casa. La señora tenía un humor endiablado; a todo ponía faltas, y reprendíales ásperamente por la sequía del cielo y la infecundidad de la tierra, fenómenos de que ellos los [30] pobrecitos no tenían culpa. Presenciaba la escena el Sr. Penitenciario. Cuando entró Caballuco, saludóle afectuosamente el buen canónigo, señalándole un asiento a su lado.\"},{\"heading\":false,\"text\":\"--Aquí está el personaje--dijo la señora con desdén.--¡Parece mentira que se hable tanto de un hombre de tan poco valer! Dime, Caballuco, ¿es verdad que te han dado 152 de bofetadas unos soldados esta mañana?\"},{\"heading\":false,\"text\":\"--¡A mí! ¡A mí!--dijo el Centauro levantándose indignado cual si recibiera el más grosero insulto.\"},{\"heading\":false,\"text\":\"[5] --Así lo han dicho--añadió la señora.--¿No es verdad? Yo lo creí, porque quien en tan poco se tiene.... Te escupirán, y tú te creerás honrado con la saliva de los militares.\"},{\"heading\":false,\"text\":\"--¡Señora!--vociferó Ramos con energía.--Salvo el [10] respeto que debo a usted, que es mi madre, más que mi madre, mi señora, mi reina... pues digo que salvo el respeto que debo a la persona que me ha dado todo lo que tengo... salvo el respeto....\"},{\"heading\":false,\"text\":\"--¿Qué?... Parece que vas a decir mucho y no dices [15] nada.\"},{\"heading\":false,\"text\":\"--Pues digo que salvo el respeto, eso de la bofetada es una calumnia--añadió, expresándose con extraordinaria dificultad.--Todos hablan de mí, que si entro o si salgo, que si voy, que si vengo.... Y todo, ¿por qué? Porque [20] quieren tomarme por figurón para que revuelva el país. Bien está Pedro en su casa, señoras y caballeros. ¿Que ha venido la tropa?... malo es; ¿pero qué le vamos a hacer?... ¿Que han quitado al alcalde y al secretario y al juez?... malo es; yo quisiera que se levantaran contra [25] ellos las piedras de Orbajosa; pero di mi palabra al gobernador, y hasta ahora yo....\"},{\"heading\":false,\"text\":\"Rascóse la cabeza, frunció el adusto ceño, y con lengua cada vez más torpe, prosiguió así:\"},{\"heading\":false,\"text\":\"--Yo seré bruto, pesado, ignorante, querencioso, testarudo [30] y todo lo que quieran; pero a caballero no me gana nadie.\"},{\"heading\":false,\"text\":\"--Lástima de Cid Campeador--dijo con el mayor desprecio doña Perfecta.--¿No cree usted, como yo, señor Penitenciario, que en Orbajosa no hay ya un solo hombre que tenga vergüenza?\"},{\"heading\":false,\"text\":\"--Grave opinión es ésa--repuso el capitular, sin mirar 153 a su amiga ni apartar de su barba la mano en que apoyaba el-meditabundo rostro.--Pero se me figura que este vecindario ha aceptado con excesiva sumisión el pesado yugo del [5] militarismo.\"},{\"heading\":false,\"text\":\"Licurgo y los tres labradores reían con toda su alma.\"},{\"heading\":false,\"text\":\"--Cuando los soldados y las autoridades nuevas--dijo la señora,--nos hayan llevado el último real, después de deshonrado el pueblo, enviaremos a Madrid, en una urna de [10] cristal, a todos los valientes de Orbajosa para que los pongan en el Museo o les enseñen por las calles.\"},{\"heading\":false,\"text\":\"--¡Viva la señora!--exclamó con vivo ademán el que llamaban Vejarruco.--Lo que ha dicho es como el oro. No se dirá por mí que no hay valientes, pues no estoy con [15] los Aceros por aquello de que tiene uno tres hijos y mujer y puede suceder cualquier estropicio; que si no....\"},{\"heading\":false,\"text\":\"--¿Pero tú no has dado tu palabra al gobernador?--le preguntó la señora.\"},{\"heading\":false,\"text\":\"--¡Al gobernador!--exclamó el nombrado Frasquito [20] González.--No hay en todo el país tunante que más merezca un tiro. Gobernador y Gobierno, todos son lo mismo. El cura nos predicó el domingo tantas cosas altisonantes sobre las herejías y ofensas a la religión que hacen en Madrid.... ¡Oh! había que oírle.... Al fin dió muchos gritos en el [25] púlpito, diciendo que la religión ya no tenía defensores.\"},{\"heading\":false,\"text\":\"--Aquí está el gran Cristóbal Ramos--dijo la señora, dando fuerte palmada en el hombro del Centauro.--Monta a caballo; se pasea en la plaza y en el camino real, para llamar la atención de los soldados; venle éstos, se espantan [30] de la fiera catadura del héroe y echan todos a correr muertos de miedo.\"},{\"heading\":false,\"text\":\"La señora terminó su frase con una risa exagerada que se hacía más chocante por el profundo silencio de los que la oían. Caballuco estaba pálido.\"},{\"heading\":false,\"text\":\"--Señor Pasolargo--continuó la dama, poniéndose seria,--esta 154 noche, cuando vaya usted a su casa, mándeme acá a su hijo Bartolomé para que se quede aquí. Necesito tener buena gente en casa; y aun así, bien podrá suceder que el [5] mejor día amanezcamos mi hija y yo asesinadas.\"},{\"heading\":false,\"text\":\"--¡Señora!--exclamaron todos.\"},{\"heading\":false,\"text\":\"--¡Señora!--gritó Caballuco levantándose.--¿Eso es broma o qué es?\"},{\"heading\":false,\"text\":\"--Señor Vejarruco, Sr. Pasolargo--continuó la señora, [10] sin mirar al bravo de la localidad;--no estoy segura en mi casa. Ningún vecino de Orbajosa lo está, y menos yo. Vivo con el alma en un hilo. No puedo pegar los ojos en toda la noche.\"},{\"heading\":false,\"text\":\"--Pero ¿quién, quién se atreverá?...\"},{\"heading\":false,\"text\":\"[15] --Vamos--exclamó Licurgo con ardor,--que yo, viejo y enfermo, seré capaz de batirme con todo el ejército español si tocan el pelo de la ropa a la señora....\"},{\"heading\":false,\"text\":\"--Con el Sr. Caballuco--dijo Frasquito González,--basta y sobra.\"},{\"heading\":false,\"text\":\"[20] --¡Oh! no--repuso doña Perfecta con cruel sarcasmo.--No ven ustedes que Ramos ha dado su palabra al Gobernador....\"},{\"heading\":false,\"text\":\"Caballuco volvió a sentarse, y poniendo una pierna sobre otra, cruzó las manos sobre ellas.\"},{\"heading\":false,\"text\":\"[25] --Me basta un cobarde--añadió implacablemente el ama,--con tal que no haya dado palabras. Quizás pase yo por el trance de ver asaltada mi casa, de ver que me arrancan de los brazos a mi querida hija, de verme atropellada e insultada del modo más infame....\"},{\"heading\":false,\"text\":\"[30] No pudo continuar. La voz se ahogó en su garganta y rompió a llorar desconsoladamente.\"},{\"heading\":false,\"text\":\"--¡Señora, por Dios, cálmese usted!... Vamos... no hay motivo todavía....--dijo precipitadamente y con semblante y voz de aflicción suma D. Inocencio.--También es preciso un poquito de resignación para soportar las 155 calamidades que Dios me envía.\"},{\"heading\":false,\"text\":\"--Pero ¿quién... señora? ¿Quién se atreverá a tales vituperios?--preguntó uno de los cuatro.--Orbajosa toda [5] se pondría sobre un pie para defender a la señora.\"},{\"heading\":false,\"text\":\"--Pero ¿quién, quién?--repitieron todos.\"},{\"heading\":false,\"text\":\"--Vaya, no la molesten ustedes con preguntas importunas--dijo con oficiosidad el Penitenciario.--Pueden retirarse.\"},{\"heading\":false,\"text\":\"[10] --No, no, que se queden--manifestó vivamente la señora, secando sus lágrimas.--La compañía de mis buenos servidores es para mí un gran consuelo.\"},{\"heading\":false,\"text\":\"--Maldita sea mi casta--dijo el tío Lucas, dándose un puñetazo en la rodilla,--si todos estos gatuperios no son [15] obra del mismísimo sobrino de la señora.\"},{\"heading\":false,\"text\":\"--¿Del hijo de D. Juan Rey?\"},{\"heading\":false,\"text\":\"--Desde que le vi en la estación de Villahorrenda y me habló con su voz melosilla y sus mimos de hombre cortesano-- manifestó Licurgo,--le tuve por un grandísimo... no [20] quiero acabar por respeto a la señora.... Pero yo le conocí... le señalé desde aquel día, y yo no me equivoco. Sé muy bien, como dijo el otro, que por el hilo se saca el ovillo, por la muestra se conoce el paño, y por la uña el león.\"},{\"heading\":false,\"text\":\"--No se hable mal en mi presencia de ese desdichado [25] joven--dijo la de Polentinos severamente.--Por grandes que sean sus faltas, la caridad nos prohibe hablar de ellas y darles publicidad.\"},{\"heading\":false,\"text\":\"--Pero la caridad--manifestó D. Inocencio con cierta energía,--no nos impide precavernos contra los malos; y [30] de eso se trata. Ya que han decaído tanto los caracteres y el valor en la desdichada Orbajosa; ya que este pueblo parece dispuesto a poner la cara para que escupan en ella cuatro soldados y un cabo, busquemos alguna defensa uniéndonos.\"},{\"heading\":false,\"text\":\"--Yo me defenderé como pueda--dijo con resignación 156 y cruzando las manos doña Perfecta.--¡Hágase la voluntad del Señor!\"},{\"heading\":false,\"text\":\"--Tanto ruido para nada.... ¡Por vida de!... ¡En [5] esta casa son de la piel del miedo!...--exclamó Caballuco, entre serio y festivo.--No parece sino que el tal D. Pepito es una _región_ (léase legión) de demonios. No se asuste usted, señora mía. Mi sobrinillo Juan, que tiene trece años, guardará la casa, y veremos, sobrino por sobrino, [10] quién puede más.\"},{\"heading\":false,\"text\":\"--Ya sabemos todos lo que significan tus guapezas y valentías--replicó la dama.--¡Pobre Ramos, quieres echártela de bravucón cuando ya se ha visto que no vales para nada!\"},{\"heading\":false,\"text\":\"[15] Ramos palideció ligeramente, fijando en la señora una mirada singular en que se confundían el espanto y el respeto.\"},{\"heading\":false,\"text\":\"--Sí, hombre, no me mires así. Ya sabes que no me asusto de fantasmones. ¿Quieres que te hable de una vez con claridad? Pues eres un cobarde.\"},{\"heading\":false,\"text\":\"[20] Ramos, moviéndose como el que tiene por diversas partes de su cuerpo molestas picazones, demostraba gran desasosiego. Su nariz expelía y recogía el aire como la de un caballo. Dentro de aquel corpachón combatía consigo misma por echarse fuera rugiendo y destrozando, una [25] tormenta, una pasión, una barbaridad. Después de modular a medias algunas palabras, mascando otras, levantóse y bramó de esta manera:\"},{\"heading\":false,\"text\":\"--¡Le cortaré la cabeza al Sr. Rey!\"},{\"heading\":false,\"text\":\"--¡Qué desatino! Eres tan bruto como cobarde--dijo [30] palideciendo la señora.--¿Qué hablas ahí de matar, si yo no quiero que maten a nadie, y mucho menos a mi sobrino, persona a quien amo a pesar de sus maldades?\"},{\"heading\":false,\"text\":\"--¡El homicidio! ¡Qué atrocidad!--exclamó el Sr. D. Inocencio escandalizado.--Ese hombre está loco.\"},{\"heading\":false,\"text\":\"--¡Matar!... La idea tan sólo de un homicidio me 157 horroriza, Caballuco--dijo la señora cerrando los dulces ojos.--¡Pobre hombre! Desde que has querido mostrar valentía, has aullado como un lobo carnicero. Vete de [5] aquí, Ramos; me causas espanto.\"},{\"heading\":false,\"text\":\"--¿No dice la señora que tiene miedo? ¿No dice que atropellarán la casa, que robarán a la niña?\"},{\"heading\":false,\"text\":\"--Sí, lo temo.\"},{\"heading\":false,\"text\":\"--Y eso lo ha de hacer un solo hombre--dijo Ramos [10] con desprecio volviendo a sentarse.--Eso lo ha de hacer D. Pepe Poquita Cosa con sus matemáticas. Hice mal en decir que le rebanaría el pescuezo. A un muñeco de ese estambre, se le coge de una oreja y se le echa de remojo en el río.\"},{\"heading\":false,\"text\":\"[15] --Sí, ríete ahora, bestia. No es mi sobrino solo quien ha de cometer todos esos desafueros que has mencionado y que yo temo; pues si fuese él solo no le temería. Mandaría a Librada que se pusiera en la puerta con una escoba ... y bastaba.... No es él solo, no.\"},{\"heading\":false,\"text\":\"[20] --¿Pues quién?\"},{\"heading\":false,\"text\":\"--Hazte el borrico. ¿No sabes tú que mi sobrino y el brigadier que manda esa condenada tropa se han confabulado?...\"},{\"heading\":false,\"text\":\"--¡Confabulado!--exclamó Caballuco demostrando no [25] entender la palabra.\"},{\"heading\":false,\"text\":\"--Que están de compinche--dijo Licurgo.--Fabulearse quiere decir estar de compinche. Ya me barruntaba yo lo que dice la señora.\"},{\"heading\":false,\"text\":\"--Todo se reduce a que el brigadier y los oficiales son [30] uña y carne de D. José, y lo que él quiera lo quieren esos soldadotes, y esos soldadotes harán toda clase de atropellos y barbaridades, porque ese es su oficio.\"},{\"heading\":false,\"text\":\"--Y no tenemos alcalde que nos ampare.\"},{\"heading\":false,\"text\":\"--Ni juez.\"},{\"heading\":false,\"text\":\"--Ni gobernador. Es decir, que estamos a merced de 158 esa infame gentuza.\"},{\"heading\":false,\"text\":\"--Ayer--dijo Vejarruco,--unos soldados se llevaron engañada a la hija más chica del tío Julián, y la pobre no [5] se atrevió a volver a su casa; mas la encontraron llorando y descalza junto a la fuentecilla vieja, recogiendo los pedazos de la cántara rota.\"},{\"heading\":false,\"text\":\"--¡Pobre D. Gregorio Palomeque! el escribano de Naharilla Alta--dijo Frasquito.--Estos pillos le robaron todo [10] el dinero que tenía en su casa. Pero el brigadier, cuando se lo contaron, contestó que era mentira.\"},{\"heading\":false,\"text\":\"--Tiranos, más tiranos no nacieron de madre--manifestó el otro.--¡Cuando digo que por punto no estoy con los Aceros!...\"},{\"heading\":false,\"text\":\"[15] --¿Y qué se sabe de Francisco Acero?--preguntó mansamente doña Perfecta.--Sentiría que le ocurriera algún percance. Dígame usted, D. Inocencio, ¿Francisco Acero no nació en Orbajosa?\"},{\"heading\":false,\"text\":\"--No; él y su hermano son de Villajuán.\"},{\"heading\":false,\"text\":\"[20] --Lo siento por Orbajosa--dijo doña Perfecta.--Esta pobre ciudad ha entrado en desgracia. ¿Sabe usted si Francisco Acero dió palabra al gobernador de no molestar a los pobres soldaditos en sus robos de doncellas, en sus irreligiosidades, en sus sacrilegios, en sus infames felonías?\"},{\"heading\":false,\"text\":\"[25] Caballuco dió un salto. Ya no se sentía punzado, sino herido por atroz sablazo. Encendido el rostro y con los ojos llenos de fuego, gritó de este modo:\"},{\"heading\":false,\"text\":\"--Yo di mi palabra al gobernador, porque el gobernador me dijo que venían con buen fin.\"},{\"heading\":false,\"text\":\"[30] --Bárbaro, no grites. Habla como la gente y te escucharemos.\"},{\"heading\":false,\"text\":\"--Yo prometí que ni yo ni ninguno de mis amigos levantaríamos partidas en tierra de Orbajosa.... A todo el que ha querido salir porque le retozaba la guerra en el cuerpo, le he dicho: _Vete con los Aceros, que aquí no nos movemos_. 159 Pero tengo mucha gente honrada, sí señora, y buena, sí señora, y valiente, sí señora, que está desperdigada por los caseríos y las aldeas y los arrabales y los montes, cada uno [5] en su casa, ¿eh? Y en cuanto yo les diga la mitad de media palabra, ¿eh? ya están todos descolgando las escopetas, ¿eh? y echando a correr a caballo o a pie para ir a donde yo les mande.... Y no me anden con gramáticas, que si yo di mi palabra, fué porque la di, y si no salgo es porque [10] no quiero salir, y si quiero que haya partidas las habrá, y si no quiero, no; porque yo soy quien soy, el mismo hombre de siempre, bien lo saben todos.... Y digo otra vez que no vengan con gramáticas, ¿estamos?... y que no me digan las cosas al revés, ¿estamos?... y si quieren que [15] salga me lo declaren con toda la boca abierta, ¿estamos? ... porque para eso nos ha dado Dios la lengua, para decir esto y aquello. Bien sabe la señora quien soy, así como bien sé yo que le debo la camisa que me pongo, y el pan que cómo hoy, y el primer garbanzo que chupé cuando [20] me despecharon, y la caja en que enterraron a mi padre cuando murió, y las medicinas y el médico que me pusieron bueno cuando estuve enfermo; y bien sabe la señora que si ella me dice: \\\"Caballuco, rómpete la cabeza,\\\" voy a aquel rincón y contra la pared me la rompo; bien sabe la señora [25] que si ahora dice ella que es de día, yo, aunque vea la noche, creeré que me equivoco y que es claro día; bien sabe la señora que ella y su hacienda son antes que mi vida, y que si delante de mí la pica un mosquito, le perdono porque es mosquito; bien sabe la señora que la quiero más [30] que a cuanto hay debajo del sol.... A un hombre de tanto corazón se le dice: \\\"Caballuco, so animal, haz esto o lo otro,\\\"... y basta de ritólicas y mete y saca de palabrejas y sermoncillos al revés y pincha por aquí y pellizca por allá.\"},{\"heading\":false,\"text\":\"--Vamos, hombre, sosiégate--dijo doña Perfecta con 160 bondad.--Te has sofocado como aquellos oradores republicanos que venían a predicar aquí la religión libre, el amor libre y no sé cuántas cosas libres.... Que te traigan un [5] vaso de agua.\"},{\"heading\":false,\"text\":\"Caballuco hizo con el pañuelo una especie de rodilla, apretado envoltorio o más bien pelota, y se lo pasó por la ancha frente y cogote para limpiarse ambas partes, cubiertas de sudor. Trajéronle un vaso de agua, y el señor [10] canónigo, con una mansedumbre que cuadraba perfectamente a su carácter sacerdotal, lo tomó de manos de la criada para presentárselo y sostener el plato mientras bebía. El agua se escurría por el gaznate de Caballuco, produciendo un claqueteo sonoro.\"},{\"heading\":false,\"text\":\"[15] --Ahora tráigame usted otro a mí, señora Librada--dijo D. Inocencio.--También tengo un poco de fuego dentro.\"}]},{\"title\":\"Capítulo XXII\",\"blocks\":[{\"heading\":false,\"text\":\"=¡Desperta!=\"},{\"heading\":false,\"text\":\"--Respecto a lo de las partidas--dijo doña Perfecta cuando concluyeron de beber,--sólo te digo que hagas lo que tu conciencia te dicte.\"},{\"heading\":false,\"text\":\"[20] --Yo no entiendo de ditados--gritó Ramos.--Haré lo que sea del gusto de la señora.\"},{\"heading\":false,\"text\":\"--Pues yo no te aconsejaré nada en asunto tan grave--repuso ella con la circunspección y comedimiento que tan bien le sentaban.--Eso es muy grave, gravísimo, y yo no [25] puedo aconsejarte nada.\"},{\"heading\":false,\"text\":\"--Pero el parecer de usted....\"},{\"heading\":false,\"text\":\"--Mi parecer es que abras los ojos y veas, que abras los oídos y oigas.... Consulta tu corazón... yo te concedo que tienes un gran corazón.... Consulta a ese juez, a [30] ese consejero que tanto sabe, y haz lo que él te mande.\"},{\"heading\":false,\"text\":\"Caballuco meditó, pensó todo lo que puede pensar una 161 espada.\"},{\"heading\":false,\"text\":\"--Los de Naharilla Alta--dijo Vejarruco,--nos contamos ayer y éramos trece, propios para cualquier cosita [5] mayor.... Pero como temíamos que la señora se enfadara, no hicimos nada. Es tiempo ya de trasquilar.\"},{\"heading\":false,\"text\":\"--No te preocupes de la trasquila--dijo la señora.--Tiempo hay. No se dejará de hacer por eso.\"},{\"heading\":false,\"text\":\"--Mis dos muchachos--manifestó Licurgo--riñeron ayer [10] el uno con el otro, porque uno quería irse con Francisco Acero y el otro no. Yo les dije: \\\"Despacio, hijos míos, que todo se andará. Esperad, que tan buen pan hacen aquí como en Francia.\\\"\"},{\"heading\":false,\"text\":\"--Anoche me dijo Roque Pelosmalos--manifestó el tío [15] Pasolargo,--que en cuanto el Sr. Ramos dijera tanto así, ya estaban todos con las armas en la mano. ¡Qué lástima que los dos hermanos Burguillos se hayan ido a labrar las tierras de Lugarnoble!\"},{\"heading\":false,\"text\":\"--Vaya usted a buscarlos--dijo el ama vivamente.--Sr. [20] Lucas, proporciónele usted un caballo al tío Pasolargo.\"},{\"heading\":false,\"text\":\"--Yo, si la señora me lo manda, y el señor Ramos también--dijo Frasquito González,--iré a Villahorrenda a ver si Robustiano, el guarda de montes y su hermano Pedro quieren también....\"},{\"heading\":false,\"text\":\"[25] --Me parece buena idea. Robustiano no se atreve a venir a Orbajosa, porque me debe un piquillo. Puedes decirle que le perdono los seis duros y medio.... Esta pobre gente, que tan generosamente sabe sacrificarse por una buena idea, se contenta con tan poco.... ¿No es [30] verdad, Sr. D. Inocencio?\"},{\"heading\":false,\"text\":\"--Aquí nuestro buen Ramos--repuso el canónigo,--me dice que sus amigos están descontentos con él por su tibieza; pero que en cuanto le vean determinado se pondrán todos la canana al cinto.\"},{\"heading\":false,\"text\":\"--Pero qué, ¿estás determinado a echarte a la calle?--dijo 162 la señora.--No te he aconsejado yo tal cosa, y si lo haces es por tu voluntad. Tampoco el Sr. D. Inocencio te habrá dicho una palabra en este sentido. Pero cuando tú [5] lo decides así, razones muy poderosas tendrás.... Dime, Cristóbal, ¿quieres cenar? ¿quieres tomar algo?... con franqueza....\"},{\"heading\":false,\"text\":\"--En cuanto a que yo aconseje al Sr. Ramos que se eche al campo--dijo D. Inocencio, mirando por encima de los [10] cristales de sus anteojos,--razón tiene la señora. Yo, como sacerdote, no puedo aconsejar tal cosa. Sé que algunos lo hacen; y aun toman las armas; pero esto me parece impropio, muy impropio, y no seré yo quien los imite. Llevo mi escrupulosidad hasta el extremo de no decir una [15] palabra al Sr. Ramos sobre la peliaguda cuestión de su levantamiento en armas. Yo sé que Orbajosa lo desea; sé que le bendecirán todos los habitantes de esta noble ciudad; sé que vamos a tener aquí hazañas dignas de pasar a la historia; pero, sin embargo, permítaseme un discreto [20] silencio.\"},{\"heading\":false,\"text\":\"--Está muy bien dicho--añadió doña Perfecta.--No me gusta que los sacerdotes se mezclen en tales asuntos. Un clérigo ilustrado debe conducirse de este modo. Bien sabemos que en circunstancias solemnes y graves, por [25] ejemplo, cuando peligran la patria y la fe, están los sacerdotes en su terreno incitando a los hombres a la lucha y aun figurando en ella. Pues que Dios mismo ha tomado parte en célebres batallas, bajo la forma de ángeles o santos, bien pueden sus ministros hacerlo. Durante la guerra contra [30] los infieles, ¿cuántos obispos acaudillaron las tropas castellanas?\"},{\"heading\":false,\"text\":\"--Muchos, y algunos fueron insignes guerreros. Pero estos tiempos no son como aquellos, señora. Verdad es que si vamos a mirar atentamente las cosas, la fe peligra ahora más que antes.... ¿Pues qué representan esos 163 ejércitos que ocupan nuestra ciudad y pueblos inmediatos? ¿qué representan? ¿Son otra cosa más que el infame instrumento de que se valen para sus pérfidas conquistas [5] y el exterminio de las creencias, los ateos y protestantes de que está infestado Madrid?... Bien lo sabemos todos. En aquel centro de corrupción, de escándalo, de irreligiosidad y descreimiento, unos cuantos hombres malignos, comprados por el oro extranjero, se emplean en destruir en [10] nuestra España la semilla de la fe.... ¿Pues qué creen ustedes? Nos dejan a nosotros decir misa y a ustedes oírla por un resto de consideración, por vergüenza... pero el mejor día.... Por mi parte, estoy tranquilo. Soy un hombre que no se apura por ningún interés temporal y [15] mundano. Bien lo sabe la señora doña Perfecta, bien lo saben todos los que me conocen. Estoy tranquilo y no me asusta el triunfo de los malvados. Sé muy bien que nos aguardan días terribles; que cuantos vestimos el hábito sacerdotal tenemos la vida pendiente de un cabello, porque [20] España, no lo duden ustedes, presenciará escenas como aquellas de la revolución francesa, en que perecieron miles de sacerdotes piadosísimos en un mismo día.... Mas no me apuro. Cuando toquen a degollar presentaré mi cuello; ya he vivido bastante. ¿Para qué sirvo yo? Para nada, [25] para nada.\"},{\"heading\":false,\"text\":\"--Comido de perros me vea yo--exclamó Vejarruco, mostrando el puño, no menos duro y fuerte que un martillo,--si no acabamos pronto con toda esa canalla ladrona.\"},{\"heading\":false,\"text\":\"--Dicen que la semana que viene comienza el derribo [30] de la catedral--indicó Frasquito.\"},{\"heading\":false,\"text\":\"--Supongo que la derribarán con picos y martillos--dijo el canónigo sonriendo.--Hay artífices que no tienen esas herramientas, y sin embargo adelantan más edificando. Bien saben ustedes que, según tradición piadosa, nuestra hermosa capilla del Sagrario fué derribada por los moros en 164 un mes y reedificada en seguida por los ángeles en una sola noche.... Dejarles, dejarles que derriben.\"},{\"heading\":false,\"text\":\"--En Madrid, según nos contó la otra noche el cura de [5] Naharilla--dijo Vejarruco,--ya quedan tan pocas iglesias, que algunos curas dicen misa en medio de la calle, y como les aporrean y les dicen injurias y también les escupen, muchos no la quieren decir.\"},{\"heading\":false,\"text\":\"--Felizmente aquí, hijos míos--manifestó D. Inocencio,--no [10] hemos tenido aún escenas de esa naturaleza. ¿Por qué? Porque saben qué clase de gente sois; porque tienen noticia de vuestra piedad ardiente y de vuestro valor.... No les arriendo la ganancia a los primeros que pongan la mano en nuestros sacerdotes y en nuestro culto.... Por [15] supuesto, dicho se está que si no se les ataja a tiempo, harán diabluras. ¡Pobre España, tan santa y tan humilde y tan buena! ¡Quién había de decir que llegarían a estos apurados extremos!... Pero yo sostengo que la impiedad no triunfará, no señor. Todavía hay gente valerosa, [20] todavía hay gente de aquella de antaño, ¿no es verdad, Sr. Ramos?\"},{\"heading\":false,\"text\":\"--Todavía la hay, sí señor--repuso éste.\"},{\"heading\":false,\"text\":\"--Yo tengo una fe ciega en el triunfo de la ley de Dios. Alguno ha de salir en defensa de ella. Si no son unos, [25] serán otros. La palma de la victoria, y con ella la gloria eterna, alguien se la ha de llevar. Los malvados perecerán, si no hoy mañana. Aquél que va contra la ley de Dios caerá, no hay remedio. Sea de esta manera, sea de la otra, ello es que ha de caer. No le salvan ni sus argucias, ni [30] sus escondites, ni sus artimañas. La mano de Dios está alzada sobre él y le herirá sin falta. Tengámosle compasión y deseemos su arrepentimiento... en cuanto a vosotros, hijos míos, no esperéis que os diga una palabra sobre el paso que seguramente vais a dar. Sé que sois buenos, sé que vuestra determinación generosa y el noble fin que os 165 guía lavan toda mancha pecaminosa por causa del derramamiento de sangre que pudierais recibir; sé que Dios os bendice, que vuestra victoria, lo mismo que vuestra muerte, [5] os sublimarán a los ojos de los hombres y a los de Dios; sé que se os deben palmas y alabanzas y toda suerte de honores; pero a pesar de esto, hijos míos, mi labio no os incitará a la pelea. No lo ha hecho nunca ni lo hará ahora. Obrad con arreglo al ímpetu de vuestro noble corazón. Si [10] él os manda que os estéis en vuestras casas, estáos en ellas; si él os manda que salgáis, salid en buen hora. Me resigno a ser mártir y a inclinar mi cuello ante el verdugo, si esa miserable tropa continúa aquí. Pero si un impulso hidalgo y ardiente y pío de los hijos de Orbajosa contribuye a la [15] grande obra de la extirpación de las desventuras patrias, me tendré por el más dichoso de los hombres sólo con ser paisano vuestro; y toda mi vida de estudios, de penitencia, de resignación, no me parecerá tan meritoria para aspirar al cielo, como un día solo de vuestro heroísmo.\"},{\"heading\":false,\"text\":\"[20] --¡No se puede decir más y mejor!--exclamó doña Perfecta arrebatada de entusiasmo.\"},{\"heading\":false,\"text\":\"Caballuco se había inclinado hacia adelante en su asiento, poniendo los codos sobre las rodillas. Cuando el canónigo acabó de hablar, tomóle la mano y se la besó con fervor.\"},{\"heading\":false,\"text\":\"[25] --Hombre mejor no ha nacido de madre--dijo el tío Licurgo enjugando o haciendo que enjugaba una lágrima.\"},{\"heading\":false,\"text\":\"--¡Que viva el señor Penitenciario!--gritó Frasquito González poniéndose en pie y arrojando hacia el techo su gorra.\"},{\"heading\":false,\"text\":\"[30] --Silencio--dijo doña Perfecta.--Siéntate, Frasquito. Tú eres de los de mucho ruido y pocas nueces.\"},{\"heading\":false,\"text\":\"--¡Bendito sea Dios, que le dió a usted ese pico de oro!--exclamó Cristóbal inflamado de admiración.--¡Qué dos personas tengo delante! Mientras vivan las dos, ¿para qué se quiere más mundo?... Toda la gente de España 166 debiera ser así... pero ¡cómo ha de ser así si no hay más que pillería! En Madrid, que es la corte de donde vienen leyes y mandarines, todo es latrocinio y farsa. [5] ¡Pobre religión, cómo la han puesto!... No se ven más que pecados.... Señora doña Perfecta, señor D. Inocencio, por el alma de mi padre, por el alma de mi abuelo, por la salvación de la mía, juro que deseo morir.\"},{\"heading\":false,\"text\":\"--¡Morir!\"},{\"heading\":false,\"text\":\"[10] --Que me maten esos perros tunantes, y digo que me maten, porque yo no puedo descuartizarlos a ellos. Soy muy chico.\"},{\"heading\":false,\"text\":\"--Ramos, eres grande--dijo solemnemente la señora.\"},{\"heading\":false,\"text\":\"--¿Grande, grande?... Grandísimo por el corazón; [15] pero ¿tengo yo plazas fuertes, tengo caballería, tengo artillería?\"},{\"heading\":false,\"text\":\"--Esa es una cosa, Ramos--dijo doña Perfecta sonriendo,--de que yo no me ocuparía. ¿No tiene el enemigo lo que a ti te hace falta?\"},{\"heading\":false,\"text\":\"[20] --Sí.\"},{\"heading\":false,\"text\":\"--Pues quítaselo....\"},{\"heading\":false,\"text\":\"--Se lo quitaremos, sí, señora. Cuando digo que se lo quitaremos....\"},{\"heading\":false,\"text\":\"[25] --Querido Ramos--exclamó D. Inocencio.--Envidiable posición es la de usted.... ¡Destacarse, elevarse sobre la vil muchedumbre, ponerse al igual de los mayores héroes del mundo... poder decir que la mano de Dios guía su mano.... ¡Oh, qué grandeza y honor! Amigo mío, no es lisonja. ¡Qué apostura, qué gentileza, qué gallardía!... [30] No; hombres de tal temple no pueden morir. El Señor va con ellos y la bala y hierro enemigos detiénense... no se atreven... ¿qué se han de atrever viniendo de cañón y de manos de herejes?... Querido Caballuco, al ver a usted, al ver su bizarría y caballerosidad, vienen a mi memoria, sin poderlo remediar, los versos de aquel romance 167 de la conquista del imperio de Trapisonda:\"},{\"heading\":false,\"text\":\"Llegó el valiente Roldán de todas armas armado, [5] en el fuerte Briador, su poderoso caballo, y la fuerte Durlindana muy bien ceñida a su lado, la lanza como una entena, [10] el fuerte escudo embrazado.... Por la visera del yelmo fuego venía lanzando; retemblando con la lanza como un junco muy delgado, [15] y a toda la hueste junta fieramente amenazando.\"},{\"heading\":false,\"text\":\"--Muy bien--exclamó Licurgo batiendo palmas.--Y yo digo como D. Renialdos:\"},{\"heading\":false,\"text\":\"¡Nadie en don Renialdos toque [20] si quiere ser bien librado! Quien otra cosa quisiere él será tan bien pagado, que todo el resto del mundo no se escape de mi mano [25] sin quedar pedazos hecho o muy bien escarmentado.\"},{\"heading\":false,\"text\":\"--Ramos, tú querrás cenar; tú querrás tomar algo, ¿no es verdad?--dijo la señora.\"},{\"heading\":false,\"text\":\"--Nada, nada--repuso el Centauro,--denme si acaso [30] un plato de pólvora.\"},{\"heading\":false,\"text\":\"Diciendo esto, soltó estrepitosa carcajada, dió varios paseos por la habitación, observado atentamente por todos, y deteniéndose junto al grupo, fijó los ojos en doña Perfecta, y con atronadora voz profirió estas palabras:\"},{\"heading\":false,\"text\":\"[35] --Digo que no hay más que decir. ¡Viva Orbajosa, muera Madrid!\"},{\"heading\":false,\"text\":\"Descargó la mano sobre la mesa, con tal fuerza que 168 retembló el piso de la casa.\"},{\"heading\":false,\"text\":\"--¡Qué poderoso brío!--dijo D. Inocencio.\"},{\"heading\":false,\"text\":\"--Vaya que tienes unos puños....\"},{\"heading\":false,\"text\":\"[5] Todos contemplaban la mesa que se había partido en dos pedazos.\"},{\"heading\":false,\"text\":\"Fijaban luego los ojos en el nunca bastante admirado Renialdos o Caballuco. Indudablemente había en su semblante hermoso, en sus ojos verdes, animados por extraño [10] resplandor felino, en su negra cabellera, en su cuerpo hercúleo, cierta expresión y aire de grandeza, un resabio o más bien recuerdo de las grandes razas que dominaron al mundo. Pero su aspecto general era el de una degeneración lastimosa, y costaba trabajo encontrar la filiación noble y [15] heroica en la brutalidad presente. Se parecía a los grandes hombres de D. Cayetano, como se parece el mulo al caballo.\"}]},{\"title\":\"Capítulo XXIII\",\"blocks\":[{\"heading\":false,\"text\":\"=Misterio=\"},{\"heading\":false,\"text\":\"Después de lo que hemos referido, duró mucho la conferencia; pero omitimos lo restante por no ser indispensable para la buena inteligencia de esta relación. Retiráronse al [20] fin, quedando para lo último, como de costumbre, el Sr. D. Inocencio. No habían tenido tiempo aún la señora y el canónigo para cambiar dos palabras, cuando entró en el comedor una criada de edad y mucha confianza, que era el brazo derecho de doña Perfecta, y como ésta la viera [25] inquieta y turbada, llenóse también de turbación, sospechando que algo malo en la casa ocurría.\"},{\"heading\":false,\"text\":\"--No encuentro a la señorita por ninguna parte--dijo la criada, respondiendo a las preguntas de la señora.\"},{\"heading\":false,\"text\":\"--¡Jesús! ¡Rosario!... ¿dónde está mi hija?\"},{\"heading\":false,\"text\":\"--¡Válgame la Virgen del Socorro!--gritó el 169 Penitenciario, tomando el sombrero y disponiéndose a correr tras la señora.\"},{\"heading\":false,\"text\":\"--Buscadla bien.... ¿Pero no estaba contigo en su [5] cuarto?\"},{\"heading\":false,\"text\":\"--Sí, señora--repuso temblando la criada vieja;--pero el demonio me tentó y me quedé dormida.\"},{\"heading\":false,\"text\":\"--¡Maldito sea tu sueño!... ¡Jesús mío!... ¿qué es esto? ¡Rosario, Rosario.... Librada!\"},{\"heading\":false,\"text\":\"[10] Subieron, bajaron, tornaron a bajar y a subir, llevando luz y registrando todas las piezas. Por último oyóse la voz del Penitenciario en la escalera, que decía con júbilo:\"},{\"heading\":false,\"text\":\"--Aquí está, aquí está. Ya pareció.\"},{\"heading\":false,\"text\":\"Un instante después madre e hija se encontraban la una [15] frente a la otra en la galería.\"},{\"heading\":false,\"text\":\"--¿Dónde estabas?--preguntó con severo acento doña Perfecta, examinando el rostro de su hija.\"},{\"heading\":false,\"text\":\"--En la huerta--repuso la niña más muerta que viva.\"},{\"heading\":false,\"text\":\"--¿En la huerta a estas horas? ¡Rosario!...\"},{\"heading\":false,\"text\":\"[20] --Tenía calor, me asomé a la ventana, se me cayó el pañuelo y bajé a buscarlo.\"},{\"heading\":false,\"text\":\"--¿Por qué no dijiste a Librada que te lo alcanzase?... ¡Librada!... ¿Dónde está esa muchacha? ¿Se ha dormido también?\"},{\"heading\":false,\"text\":\"[25] Librada apareció al fin. Su semblante pálido indicaba la consternación y el recelo del delincuente.\"},{\"heading\":false,\"text\":\"--¿Qué es esto? ¿Dónde estabas?--preguntó con terrible enojo la dama.\"},{\"heading\":false,\"text\":\"--Pues, señora... bajé a buscar la ropa que está en [30] el cuarto de la calle... y me quedé dormida.\"},{\"heading\":false,\"text\":\"--Todas duermen aquí esta noche. Me parece que alguna no dormirá en mi casa mañana. Rosario, puedes retirarte.\"},{\"heading\":false,\"text\":\"Comprendiendo que era indispensable proceder con prontitud y energía, la señora y el canónigo emprendieron sin tardanza sus investigaciones. Preguntas, amenazas, ruegos, 170 promesas, fueron empleadas con habilidad suma para inquirir la verdad de lo acontecido. No resultó ni sombra de culpabilidad en la criada anciana; pero Librada confesó de [5] plano entre lloros y suspiros todas sus bellaquerías, que sintetizaremos del modo siguiente:\"},{\"heading\":false,\"text\":\"Poco después de alojarse en la casa, el señor Pinzón empezó a hacer cocos a la señorita Rosario. Dió dinero a Librada, según ésta dice, para tenerla por mensajera de [10] recados y amorosas esquelas. La señorita no se mostró enojada, sino antes bien gozosa, y pasaron algunos días de esta manera. Por último, la sirvienta declara que aquella noche Rosario y el Sr. Pinzón habían concertado verse y hablarse en la ventana de la habitación de este último, que [15] da a la huerta. Confiaron su pensamiento a la doncella, quien ofreció protegerlo mediante una cantidad que se le entregara en el acto. Según lo convenido, el Pinzón debía salir de la casa a la hora de costumbre y volver ocultamente a las nueve, y entrar en su cuarto, del cual y de la casa [20] saldría también clandestinamente más tarde, para volver sin tapujos a la hora avanzada de costumbre. De este modo no podría sospecharse de él. La Librada aguardó al Pinzón, el cual entró muy envuelto en su capote sin hablar palabra. Metióse en su cuarto a punto que la señorita [25] bajaba a la huerta. La Librada, mientras duró la entrevista, que no presenció, estuvo de centinela en la galería para avisar a Pinzón cualquier peligro que ocurriese; y al cabo de una hora salió éste como antes, muy bien cubierto con su capote y sin hablar una palabra. Concluída la [30] confesión, D. Inocencio preguntó a la desdichada:\"},{\"heading\":false,\"text\":\"--¿Estás segura de que el que entró y salió era el Sr. Pinzón?\"},{\"heading\":false,\"text\":\"La reo no contestó nada, y sus facciones indicaban gran perplejidad.\"},{\"heading\":false,\"text\":\"La señora se puso verde de ira. 171\"},{\"heading\":false,\"text\":\"--¿Tú le viste la cara?\"},{\"heading\":false,\"text\":\"--¿Pero quién podría ser sino él?--repuso la doncella.--Yo tengo la seguridad de que era él. Fué derecho a su [5] cuarto... conocía muy bien el camino.\"},{\"heading\":false,\"text\":\"--Es raro--dijo el canónigo.--Viviendo en la casa no necesitaba emplear tales tapujos.... Podía haber pretextado una enfermedad y quedarse.... ¿No es verdad, señora?\"},{\"heading\":false,\"text\":\"[10] --Librada--exclamó ésta con exaltación de ira,--te juro por Dios que irás a presidio.\"},{\"heading\":false,\"text\":\"Después cruzó las manos, clavándose los dedos de la una en la otra con tanta fuerza, que casi se hizo sangre.\"},{\"heading\":false,\"text\":\"--Sr. D. Inocencio--exclamó.--Muramos... no hay [15] más remedio que morir.\"},{\"heading\":false,\"text\":\"Después rompió a llorar desconsolada.\"},{\"heading\":false,\"text\":\"--Valor, señora mía--dijo el clérigo con acento patético.--Mucho valor.... Ahora es preciso tenerlo grande. Esto requiere serenidad y gran corazón.\"},{\"heading\":false,\"text\":\"[20] --El mío es inmenso--dijo entre sollozos la de Polentinos.\"},{\"heading\":false,\"text\":\"--El mío es pequeñito...--dijo el canónigo;--pero allá veremos.\"}]},{\"title\":\"Capítulo XXIV\",\"blocks\":[{\"heading\":false,\"text\":\"=La confesión=\"},{\"heading\":false,\"text\":\"Entre tanto Rosario, con el corazón hecho pedazos, sin [25] poder llorar, sin poder tener calma ni sosiego, traspasada por el frío acero de un dolor inmenso, con la mente pasando en veloz carrera del mundo a Dios y de Dios al mundo, aturdida y media loca, estaba a altas horas de la noche en su cuarto, puesta de hinojos, cruzadas las manos, con los [30] pies desnudos sobre el suelo, la ardiente sien apoyada en el borde del lecho, a obscuras, a solas, en silencio. Cuidaba 172 de no hacer el menor ruido, para no llamar la atención de su mamá, que dormía o aparentaba dormir en la habitación inmediata. Elevó al cielo su exaltado pensamiento en esta [5] forma:\"},{\"heading\":false,\"text\":\"--Señor, Dios mío, ¿por qué antes no sabía mentir y ahora sé? ¿Por qué antes no sabía disimular y ahora disimulo? ¿Soy una mujer infame?... Esto que siento y que a mí me pasa es la caída de las que no vuelven a [10] levantarse. ¿He dejado de ser buena y honrada?... Yo no me conozco. ¿Soy yo misma, o es otra la que está en este sitio?... ¡Qué de terribles cosas en tan pocos días! ¡Cuántas sensaciones diversas! ¡Mi corazón está consumido de tanto sentir!... Señor, Dios mío, ¿oyes [15] mi voz, o estoy condenada a rezar eternamente sin ser oída?... Yo soy buena, nadie me convencerá de que no soy buena. Amar, amar muchísimo, ¿es acaso maldad?... Pero no... esto no es una ilusión, un engaño. Soy más mala que las peores mujeres de la tierra. Dentro de mí [20] una gran culebra me muerde y me envenena el corazón.... ¿Qué es esto que siento? ¿Por qué no me matas, Dios mío? ¿Por qué no me hundes para siempre en el Infierno?... Es espantoso, pero lo confieso, lo confieso a solas a Dios, que me oye, y lo confesaré ante el sacerdote. [25] Aborrezco a mi madre. ¿En qué consiste esto? No puedo explicármelo. Él no me ha dicho una palabra en contra de mi madre. Yo no sé cómo ha venido esto.... ¡Qué mala soy! Los demonios se han apoderado de mí. Señor, ven en mi auxilio, porque no puedo con mis propias fuerzas [30] vencerme.... Un impulso terrible me arroja de esta casa. Quiero huir, quiero correr fuera de aquí. Si él no me lleva, me iré tras él arrastrándome por los caminos.... ¿Qué divina alegría es ésta que dentro de mi pecho se confunde con tan amarga pena?... Señor, Dios padre mío, ilumíname. Quiero amar tan sólo. Yo no nací para este 173 rencor que me está devorando. Yo no nací para disimular, ni para mentir, ni para engañar. Mañana saldré a la calle, gritaré en medio de ella, y a todo el que pase le diré: _amo, [5] aborrezco_.... Mi corazón se desahogará de esta manera.... ¿Qué dicha sería poder conciliario todo, amar y respetar a todo el mundo! La Virgen Santísima me favorezca.... Otra vez la idea terrible. No lo quiero pensar, y lo pienso. No lo quiero sentir, y lo siento. ¡Ah! no [10] puedo engañarme sobre este particular. No puedo ni destruirlo ni atenuarlo... pero puedo confesarlo y lo confieso, diciéndote: ¡Señor, que aborrezco a mi madre!\"},{\"heading\":false,\"text\":\"Al fin se aletargó. En su inseguro sueño, la imaginación le reproducía todo lo que había hecho aquella noche, [15] desfigurándolo, sin alterarlo en su esencia. Oía el reloj de la catedral dando las nueve; veía con júbilo a la criada anciana, durmiendo con beatífico sueño, y salía del cuarto muy despacito para no hacer ruido; bajaba la escalera suavemente, que no movía un pie hasta no estar segura de [20] poder evitar el más ligero ruido. Salía a la huerta, dando una vuelta por el cuarto de las criadas y la cocina; en la huerta deteníase un momento para mirar al cielo, que estaba negro y tachonado de estrellas. El viento callaba. Ningún viento interrumpía el hondo sosiego de la noche. [25] Parecía existir en ella una atención fija y silenciosa, propia de ojos que miran sin pestañear y oídos que acechan en la expectativa de un gran suceso.... La noche observaba.\"},{\"heading\":false,\"text\":\"Acercábase después a la puerta vidriera del comedor, y miraba con cautela a cierta distancia, temiendo que la vieran [30] los de dentro. A la luz de la lámpara del comedor veía a su madre de espaldas. El Penitenciario estaba a la derecha y su perfil se descomponía de un modo extraño; crecíale la nariz, asemejándose al pico de un ave inverosímil, y toda su figura se tornaba en una recortada sombra, negra y espesa, con ángulos aquí y allí, irrisoria, escueta y delgada. 174 Enfrente estaba Caballuco, más semejante a un dragón que a un hombre. Rosario veía sus ojos verdes, como dos grandes linternas de convexos cristales. Aquel fulgor y la [5] imponente figura del animal le infundían miedo. El tío Licurgo y los otros tres se le presentaban como figuritas grotescas. Ella había visto, en alguna parte, sin duda en los muñecos de barro de las ferias, aquel reír estúpido, aquellos semblantes toscos y aquel mirar lelo. El dragón [10] agitaba sus brazos, que en vez de accionar, daban vueltas como aspas de molino, y revolvía los globos verdes, tan semejantes a los fanales de una farmacia, de un lado para otro. Su mirar cegaba.... La conversación parecía interesante. El Penitenciario agitaba las alas. Era una [15] presumida avecilla que quería volar y no podía. Su pico se alargaba y se retorcía. Erizábansele las plumas con síntomas de furor, y después, recogiéndose y aplacándose, escondía la pelada cabeza bajo el ala. Luego las figurillas de barro se agitaban queriendo ser personas, y Frasquito [20] González se empeñaba en pasar por hombre.\"},{\"heading\":false,\"text\":\"Rosario sentía un pavor inexplicable en presencia de aquel amistoso concurso. Alejábase de la vidriera y seguía adelante paso a paso, mirando a todos lados por ver si era observada. Sin ver a nadie, creía que un millón de ojos se [25] fijaban en ella.... Pero sus temores y su vergüenza disipábanse de improviso. En la ventana del cuarto donde habitaba el Sr. Pinzón aparecía un hombre azul; brillaban en su cuerpo los botones como sartas de lucecillas. Ella se acercaba. En el mismo instante sentía que unos brazos [30] con galones la suspendían como una pluma, metiéndola con rápido movimiento dentro de la pieza. Todo cambiaba. De súbito sonó un estampido, un golpe seco que estremeció la casa en sus cimientos. Ni uno ni otro supieron la causa de tal estrépito. Temblaban y callaban.\"},{\"heading\":false,\"text\":\"Era el momento en que el dragón había roto la mesa del 175 comedor.\"}]},{\"title\":\"Capítulo XXV\",\"blocks\":[{\"heading\":false,\"text\":\"=Sucesos imprevistos.--Pasajero desconcierto=\"},{\"heading\":false,\"text\":\"La escena cambia. Ved una estancia hermosa, clara, humilde, alegre, cómoda y de un aseo sorprendente. Fina [5] estera de junco cubre el piso, y las blancas paredes se adornan con hermosas estampas de santos y algunas esculturas de dudoso valor artístico. La antigua caoba de los muebles brilla lustrada por los frotamientos del sábado, y el altar, donde una pomposa Virgen, de azul y plata vestida, recibe [10] doméstico culto, se cubre de mil graciosas chucherías, mitad sacras, mitad profanas. Hay además cuadritos de mostacilla, pilas de agua bendita, una relojera con _Agnus Dei_, una rizada palma de Domingo de Ramos y no pocos floreros de inodoras flores de trapo. Enorme estante de roble contiene [15] una rica y escogida biblioteca, y allí está Horacio el epicúreo y sibarita junto con el tierno Virgilio, en cuyos versos se ve palpitar y derretirse el corazón de la inflamada Dido; Ovidio el narigudo, tan sublime como obsceno y adulador, junto con Marcial, el tunante lenguaraz y [20] conceptista; Tibulo el apasionado con Cicerón el grande; el severo Tito Livio con el terrible Tácito, verdugo de los Césares; Lucrecio el panteísta; Juvenal, que con la pluma desollaba; Plauto, el que imaginó las mejores comedias de la antigüedad dando vueltas a la rueda de un molino; Séneca el [25] filósofo, de quien se dijo que el mejor acto de su vida fué la muerte; Quintiliano el retórico; Salustio el pícaro, que tan bien habla de la virtud; ambos Plinios, Suetonio y Varrón, en una palabra, todas las letras latinas, desde que balbucieron su primera palabra con Livio Andronico, hasta que [30] exhalaron su postrer suspiro con Rutilio.\"},{\"heading\":false,\"text\":\"Pero haciendo esta inútil, aunque rápida enumeración, no 176 hemos observado que dos mujeres han entrado en el cuarto. Es muy temprano, pero en Orbajosa se madruga mucho. Los pajaritos cantan que se las pelan en sus jaulas; tocan [5] a misa las campanas de las iglesias, y hacen sonar sus alegres esquilas las cabras que van a dejarse ordeñar a las puertas de las casas.\"},{\"heading\":false,\"text\":\"Las dos señoras que vemos en la habitación descrita vienen de oír misa. Visten de negro, y cada cual trae en [10] la mano derecha su librito de devoción y el rosario envuelto en los dedos.\"},{\"heading\":false,\"text\":\"--Tu tío no puede tardar ya--dijo una de ellas,--le dejamos empezando la misa; pero él despacha pronto, y a estas horas estará en la sacristía quitándose la casulla. Yo [15] me hubiera quedado a oírle la misa, pero hoy es día de mucha fatiga para mí.\"},{\"heading\":false,\"text\":\"--Yo no he oído hoy más que la del señor magistral--dijo la otra;--la del señor magistral que las dice en un suspiro, y creo que no me ha sido de provecho, porque [20] estaba muy preocupada, sin poder apartar el entendimiento de estas cosas terribles que nos pasan.\"},{\"heading\":false,\"text\":\"--¡Cómo ha de ser!... Es preciso tener paciencia... Veremos lo que nos aconseja tu tío.\"},{\"heading\":false,\"text\":\"--¡Ay!--exclamó la segunda exhalando un hondo y [25] patético suspiro.--Yo tengo la sangre abrasada.\"},{\"heading\":false,\"text\":\"--Dios nos amparará.\"},{\"heading\":false,\"text\":\"--¡Pensar que una persona como usted, una señora como usted se ve amenazada por un!... Y él sigue en sus trece... Anoche, señora doña Perfecta, conforme usted [30] me lo mandó, volví a la posada de la viuda del Cuzco, y he pedido nuevos informes. El don Pepito y el brigadier Batalla están siempre juntos conferenciando... ¡ay Jesús, Dios y Señor mío!... conferenciando sobre sus infernales planes y despachando botellas de vino. Son dos perdidos, dos borrachos. Sin duda discurren alguna maldad muy 177 grande. Como me intereso tanto por usted, anoche, estando yo en la posada, vi salir al D. Pepito y le seguí....\"},{\"heading\":false,\"text\":\"--¿Y a dónde fué?\"},{\"heading\":false,\"text\":\"[5] --Al Casino, sí, señora, al Casino--repuso la otra turbándose ligeramente.--Después volvió a su casa. ¡Ay! cuánto me reprendió mi tío por haber estado hasta muy tarde ocupada en este espionaje... pero no lo puedo remediar... ¡Jesús divino, ampárame! No lo puedo remediar, y mirando a una persona como usted en trances 10 tan peligrosos, me vuelvo loca... Nada, nada, señora, estoy viendo que a lo mejor esos tunantes asaltan la casa y nos llevan a Rosarito....\"},{\"heading\":false,\"text\":\"Doña Perfecta, pues era ella, fijando la vista en el suelo, [15] meditó largo rato. Estaba pálida y ceñuda. Por fin exclamó:\"},{\"heading\":false,\"text\":\"--Pues no veo el modo de impedirlo.\"},{\"heading\":false,\"text\":\"--Yo sí lo veo--dijo vivamente la otra, que era la sobrina del Penitenciario y madre de Jacinto.--Veo un [20] medio muy sencillo, el que he manifestado a usted y no le gusta. ¡Ah! señora mía, usted es demasiado buena. En ocasiones como esta conviene ser un poco menos perfecta ... dejar a un ladito los escrúpulos. Pues qué, ¿se va a ofender Dios por eso?\"},{\"heading\":false,\"text\":\"[25] --María Remedios--dijo la señora con altanería,--no digas desatinos.\"},{\"heading\":false,\"text\":\"--¡Desatinos!... Usted, con sus sabidurías, no podrá ponerle las peras a cuarto al sobrinejo. ¿Qué cosa más sencilla que la que yo propongo? Puesto que ahora no hay [30] justicia que nos ampare, hagamos nosotros la gran justiciada. ¿No hay en casa de usted hombres que sirvan para cualquier cosa? Pues llamarles y decirles: \\\"Mira, Caballuco, Pasolargo o quien sea, esta misma noche te tapujas bien, de modo que no seas conocido; llevas contigo a un amiguito de confianza, y te pones detrás de la esquina de la 178 calle de Santa Faz. Aguardáis un rato, y cuando D. José Rey pase por la calle de la Tripería para ir al Casino, porque de seguro irá al Casino, ¿entendéis bien? cuando pase [5] le salís al encuentro y le dais un susto\\\"...\"},{\"heading\":false,\"text\":\"--María Remedios, no seas tonta--indicó con magistral dignidad la señora.\"},{\"heading\":false,\"text\":\"--Nada más que un susto, señora: atienda usted bien a lo que digo, un susto. Pues qué, ¿había yo de aconsejar [10] un crimen?... ¡Jesús, Padre y Redentor mío! Sólo la idea me llena de horror, y parece que veo señales de sangre y fuego delante de mis ojos. Nada de eso, señora mía... Un susto, y nada más que un susto, por lo cual comprenda ese bergante que estamos bien defendidas. Él va solo al [15] Casino, señora, enteramente solo, y allí se junta con sus amigotes, los del sable y morrioncete. Figúrese usted que recibe el susto y que además le quedan algunos huesos quebrantados, sin nada de heridas graves se entiende... pues en tal caso, o se acobarda y huye de Orbajosa, o se [20] tiene que meter en la cama por quince días. Eso sí, hay que recomendarles que el susto sea bueno. Nada de matar ... cuidadito con eso, pero sentar bien la mano.\"},{\"heading\":false,\"text\":\"--María--dijo doña Perfecta con altanería,--tú eres incapaz de una idea elevada, de una resolución grande y [25] salvadora. Eso que me aconsejas es una indignidad cobarde.\"},{\"heading\":false,\"text\":\"--Bueno, pues me callo... ¡Ay de mí, qué tonta soy!--exclamó con humildad la sobrina del Penitenciario.--Me guardaré mis tonterías para consolarla a usted después [30] que haya perdido a su hija.\"},{\"heading\":false,\"text\":\"--¡Mi hija!... ¡perder a mi hija!...--exclamó la señora con súbito arrebato de ira.--- Sólo oírlo me vuelve loca. No, no me la quitarán. Si Rosario no aborrece a ese perdido, como yo deseo, le aborrecerá. De algo sirve la autoridad de una madre... Le arrancaremos su pasión, 179 mejor dicho, su capricho, como se arranca una yerba tierna que aún no ha tenido tiempo de echar raíces... No, esto no puede ser, Remedios. ¡Pase lo que pase, no será! [5] No le valen a ese loco ni los medios más infames. Antes que verla esposa de mi sobrino, acepto cuanto de malo pueda pasarle, incluso la muerte.\"},{\"heading\":false,\"text\":\"--Antes muerta, antes enterrada y hecha alimento de gusanos--afirmó Remedios cruzando las manos como quien [10] dice una plegaria,--que verla en poder de... ¡Ay! señora, no se ofenda usted si le digo una cosa, y es que sería gran debilidad ceder porque Rosarito haya tenido algunas entrevistas secretas con ese atrevido. El caso de anteanoche, según lo contó mi tío, me parece una treta [15] infame de D. José para conseguir su objeto por medio del escándalo. Muchos hacen esto... ¡Ay, Jesús Divino, no sé cómo hay quien le mire la cara a un hombre no siendo sacerdote!\"},{\"heading\":false,\"text\":\"--Calla, calla--dijo doña Perfecta con vehemencia,--no [20] me nombres lo de anteanoche. ¡Qué horrible suceso! María Remedios... comprendo que la ira puede perder un alma para siempre. Yo me abraso... ¡Desdichada de mí, ver estas cosas y no ser hombre!... Pero si he de decir la verdad sobre lo de anteanoche, aún tengo mis [25] dudas. Librada jura y perjura que fue Pinzón el que entró. ¡Mi hija niega todo, mi hija nunca ha mentido!... Yo insisto en mi sospecha. Creo que Pinzón es un bribón encubridor; pero nada más....\"},{\"heading\":false,\"text\":\"--Volvemos a lo de siempre, a que el autor de todos los [30] males es el dichoso matemático... ¡Ay! No me engañó el corazón cuando le vi por primera vez... Pues, señora mía, resígnese usted a presenciar algo más terrible todavía, si no se decide a llamar a Caballuco y decirle: \\\"Caballuco, espero que\\\"...\"},{\"heading\":false,\"text\":\"--Vuelta a lo mismo; pero tú eres simple.... 180\"},{\"heading\":false,\"text\":\"--¡Oh! Si yo soy muy simplota, lo conozco; pero si no alcanzo más, ¿qué puedo hacer? Digo lo que se me ocurre, sin sabidurías.\"},{\"heading\":false,\"text\":\"[5] --Lo que tú imaginas, esa vulgaridad tonta de la paliza y del susto se le ocurre a cualquiera. Tú no tienes dos dedos de frente, Remedios; cuando quieres resolver un problema grave, sales con tales patochadas. Yo imagino un recurso más digno de personas nobles y bien nacidas. [10] ¡Apalear! ¡qué estupidez! Además, no quiero que mi sobrino reciba un rasguño por orden mía: eso de ninguna manera. Dios le enviará su castigo por cualquiera de los admirables caminos que Él sabe elegir. Sólo nos corresponde trabajar porque los designios de Dios no hallen [15] obstáculo, María Remedios: es preciso en estos asuntos ir directamente a las causas de las cosas. Pero tú no entiendes de causas... tú no ves más que pequeñeces.\"},{\"heading\":false,\"text\":\"--Será así--dijo humildemente la sobrina del cura.--¡Para qué me hará Dios tan necia, que nada de esas [20] sublimidades entiendo!\"},{\"heading\":false,\"text\":\"--Es preciso ir al fondo, al fondo, Remedios. ¿Tampoco entiendes ahora?\"},{\"heading\":false,\"text\":\"--Tampoco.\"},{\"heading\":false,\"text\":\"--Mi sobrino, no es mi sobrino, mujer: es la blasfemia, [25] el sacrilegio, el ateísmo, la demagogia... ¿Sabes lo que es la demagogia?\"},{\"heading\":false,\"text\":\"--Algo de esa gente que quemó a París con petróleo, y los que derriban las iglesias y fusilan las imágenes... Hasta ahí vamos bien. [30] --Pues mi sobrino es todo eso... ¡Ah! ¡si él estuviera solo en Orbajosa!... Pero no, hija mía. Mi sobrino, por una serie de fatalidades, que son otras tantas pruebas de los males pasajeros que a veces permite Dios para nuestro castigo, equivale a un ejército, equivale a la autoridad del Gobierno, equivale al alcalde, equivale al 181 juez; mi sobrino no es mi sobrino; es la nación oficial, Remedios; es esa segunda nación, compuesta de los perdidos que gobiernan en Madrid, y que se ha hecho dueña de [5] la fuerza material; de esa nación aparente, porque la real es la que calla, paga y sufre; de esa nación ficticia que firma al pie de los decretos y pronuncia discursos y hace una farsa de gobierno y una farsa de autoridad y una farsa de todo. Eso es hoy mi sobrino; es preciso que te acostumbres [10] a ver lo interno de las cosas. Mi sobrino es el Gobierno, el brigadier, el alcalde nuevo, el juez nuevo, porque todos le favorecen a causa de la unanimidad de sus ideas; porque son uña y carne, lobos de la misma manada... Entiéndelo bien; hay que defenderse de todos ellos, [15] porque todos son uno, y uno es todos; hay que atacarles de común, y no con palizas al volver de una esquina, sino como atacaban nuestros abuelos a los moros, a los moros, Remedios!... Hija mía, comprende bien esto; abre tu entendimiento y deja entrar en él una idea que no sea vulgar... [20] remóntate; piensa en alto, Remedios....\"},{\"heading\":false,\"text\":\"La sobrina de D. Inocencio estaba atónita ante tanta grandeza. Abrió la boca para decir algo en consonancia con tan maravilloso pensamiento; pero sólo exhaló un suspiro.\"},{\"heading\":false,\"text\":\"[25] --Como a los moros--repitió doña Perfecta.--Es cuestión de moros y cristianos. ¡Y creías tú que con asustar a mi sobrino se concluía todo!... ¡Qué necia eres! ¿No ves que le apoyan sus amigos? ¿No ves que estamos a merced de esa canalla? ¿No ves que cualquier tenientejo [30] es capaz de pegar fuego a mi casa si se le antoja?... ¿Pero tú no alcanzas esto? ¿No comprendes que es necesario ir al fondo? ¿No comprendes la inmensa grandeza, la terrible extensión de mi enemigo, que no es un hombre, sino una secta?... ¿No comprendes que mi sobrino, tal como está hoy enfrente de mí, no es una calamidad sino una 182 plaga?... Contra ella, querida Remedios, tendremos aquí un batallón de Dios que aniquile la infernal milicia de Madrid. Te digo que esto va a ser grande y glorioso....\"},{\"heading\":false,\"text\":\"[5] --Si al fin fuera....\"},{\"heading\":false,\"text\":\"--¿Pero tú lo dudas? Hoy hemos de ver aquí cosas terribles...--dijo con gran impaciencia la señora.--Hoy, hoy. ¿Qué hora es? Las siete. ¡Tan tarde y no ocurre nada!...\"},{\"heading\":false,\"text\":\"[10] --Quizás sepa algo mi tío, que está aquí ya. Le siento subir la escalera.\"},{\"heading\":false,\"text\":\"--Gracias a Dios...--dijo doña Perfecta levantándose para salir al encuentro del Penitenciario.--Él nos dirá algo bueno.\"},{\"heading\":false,\"text\":\"[15] Don Inocencio entró apresurado. Su demudado rostro indicaba que aquella alma, consagrada a la piedad y a los estudios latinos, no estaba tan tranquila como de ordinario.\"},{\"heading\":false,\"text\":\"--Malas noticias--dijo poniendo sobre una silla el sombrero y desatando los cordones del manteo.\"},{\"heading\":false,\"text\":\"[20] Doña Perfecta palideció.\"},{\"heading\":false,\"text\":\"--Están prendiendo gente--añadid D. Inocencio, bajando la voz, cual si debajo de cada silla estuviera un soldado. Sospechan, sin duda, que los de aquí no les aguantarían sus pesadas bromas y han ido de casa en casa [25] echando mano a todos los que tenían fama de valientes....\"},{\"heading\":false,\"text\":\"La señora se arrojó en un sillón y apretó fuertemente los dedos contra la madera de los brazos del mueble.\"},{\"heading\":false,\"text\":\"--Falta que se hayan dejado prender--- indicó Remedios.\"},{\"heading\":false,\"text\":\"[30] --Muchos de ellos... pero muchos--dijo D. Inocencio con ademanes encomiados, dirigiéndose a la señora,--han tenido tiempo de huir y se han ido con armas y caballos a Villahorrenda.\"},{\"heading\":false,\"text\":\"--¿Y Ramos?\"},{\"heading\":false,\"text\":\"--En la catedral me dijeron que es el que buscan con 183 más empeño... ¡Oh, Dios mío! prender así a unos infelices que nada han hecho todavía... Vamos, no sé cómo los buenos españoles tienen paciencia. Señora mía doña [5] Perfecta, refiriendo esto de las prisiones, me he olvidado decir a usted que debe marcharse a su casa al momento.\"},{\"heading\":false,\"text\":\"--Sí, al momento... ¿Registrarán mi casa esos bandidos?\"},{\"heading\":false,\"text\":\"--Quizás. Señora, estamos en un día nefasto--dijo D. [10] Inocencio con solemne y conmovido acento.--¡Dios se apiade de nosotros!\"},{\"heading\":false,\"text\":\"--En mi casa tengo media docena de hombres muy bien armados--repuso la dama, vivamente alterada. ¡Qué iniquidad! ¿Serán capaces de querer llevárselos también?...\"},{\"heading\":false,\"text\":\"[15] --De seguro el Sr. Pinzón no se habrá descuidado en denunciarlos. Señora, repito que estamos en un día nefasto. Pero Dios amparará la inocencia.\"},{\"heading\":false,\"text\":\"--Me voy. No deje usted de pasar por allá.\"},{\"heading\":false,\"text\":\"--Señora, en cuanto despache la clase... y me figuro [20] que con la alarma que hay en el pueblo, todos los chicos harán novillos hoy; pero haya o no clase, iré después por allá... No quiero que salga usted sola, señora. Andan por las calles esos zánganos de soldados con unos humos... ¡Jacinto, Jacinto!\"},{\"heading\":false,\"text\":\"[25] --No es preciso. Me marcharé sola.\"},{\"heading\":false,\"text\":\"--Que vaya Jacinto--dijo la madre de éste.--Ya debe estar levantado.\"},{\"heading\":false,\"text\":\"Sintiéronse los precipitados pasos del doctorcillo que bajaba a toda prisa la escalera del piso alto. Venía con el [30] rostro encendido, fatigado el aliento.\"},{\"heading\":false,\"text\":\"--¿Qué hay?--le preguntó su tío.\"},{\"heading\":false,\"text\":\"--En casa de las Troyas--dijo el jovenzuelo,--en casa de esas... pues....\"},{\"heading\":false,\"text\":\"--Acaba de una vez.\"},{\"heading\":false,\"text\":\"--Está Caballuco. 184\"},{\"heading\":false,\"text\":\"--¿Allá arriba?... ¿En casa de las Troyas?\"},{\"heading\":false,\"text\":\"--Sí, señor... Me ha hablado desde el terrado, y me ha dicho que está temiendo le vayan a coger allí.\"},{\"heading\":false,\"text\":\"[5] --¡Oh, qué bestia!... Ese majadero se va a dejar prender--exclamó doña Perfecta, hiriendo el suelo con el inquieto pie.\"},{\"heading\":false,\"text\":\"--Quiere bajar aquí y que le escondamos en casa.\"},{\"heading\":false,\"text\":\"--¿Aquí?\"},{\"heading\":false,\"text\":\"[10] Canónigo y sobrina se miraron.\"},{\"heading\":false,\"text\":\"--¡Que baje!--dijo doña Perfecta con vehemente frase.\"},{\"heading\":false,\"text\":\"--¿Aquí?--repitió D. Inocencio poniendo cara de mal humor.\"},{\"heading\":false,\"text\":\"[15] --Aquí--contestó la señora.--No conozco casa donde pueda estar más seguro.\"},{\"heading\":false,\"text\":\"--Puede saltar fácilmente por la ventana de mi cuarto--dijo Jacinto.\"},{\"heading\":false,\"text\":\"--Pues si es indispensable....\"},{\"heading\":false,\"text\":\"[20] --María Remedios--dijo la señora.--Si nos cogen a este hombre, todo se ha perdido.\"},{\"heading\":false,\"text\":\"--Tonta y simple soy--repuso la sobrina del canónigo, poniéndose la mano en el pecho y ahogando el suspiro que sin duda iba a salir al público;--pero no le cogerán.\"},{\"heading\":false,\"text\":\"[25] La señora salió rápidamente, y poco después el Centauro se arrellanaba en la butaca donde el Sr. D. Inocencio solía sentarse a escribir sus sermones.\"},{\"heading\":false,\"text\":\"No sabemos cómo llegó a oídos del brigadier Batalla; pero es indudable que este diligente militar tenía noticia de [30] que los orbajosenses habían variado de intenciones, y en la mañana de aquel día dispuso la prisión de los que en nuestro rico lenguaje insurreccional solemos llamar _caracterizados_. Salvóse por milagro el gran Caballuco, refugiándose en casa de las Troyas; pero no creyéndose allí seguro, bajó, como se ha visto, a la santa y no sospechosa mansión del 185 buen canónigo.\"},{\"heading\":false,\"text\":\"Por la noche la tropa, establecida en diversos puntos del pueblo, ejercía la mayor vigilancia con los que entraban y [5] salían; pero Ramos logró evadirse burlando o quizás sin burlar las precauciones militares. Esto acabó de encender los ánimos, y multitud de gente se conjuraba en los caseríos cercanos a Villahorrenda, juntándose de noche para dispersarse de día y preparar así el arduo negocio de su levantamiento. [10] Ramos recorrió las cercanías allegando gente y armas, y como las columnas volantes andaban tras los Aceros en tierra de Villajuán de Nahara, nuestro héroe caballeresco adelantó mucho en poco tiempo.\"},{\"heading\":false,\"text\":\"Por las noches arriesgábase con audacia suma a entrar en [15] Orbajosa; valiéndose de medios de astucia o tal vez de sobornos. Su popularidad y la protección que recibía dentro del pueblo servíanle hasta cierto punto de salvaguardia, y no será aventurado decir que la tropa no desplegaba ante aquel osado campeón el mismo rigor que ante los hombres [20] insignificantes de la localidad. En España, y principalmente en tiempo de guerras, que son siempre aquí desmoralizadoras, suelen verse esas condescendencias infames con los grandes, mientras se persigue sin piedad a los pequeñuelos. Valido, pues, de su audacia, del soborno, o no sabemos de [25] qué, Caballuco entraba en Orbajosa, reclutaba más gente, reunía armas y acopiaba dinero. Para mayor seguridad de su persona, o para cubrir el expediente, no ponía los pies en su casa, apenas entraba en la de doña Perfecta para tratar de asuntos importantes, y solía cenar en casa de este o del [30] otro amigo, prefiriendo siempre el respetado domicilio de algún sacerdote, y principalmente el de don Inocencio, donde recibiera asilo en la mañana funesta de las prisiones.\"},{\"heading\":false,\"text\":\"En tanto Batalla había telegrafiado al Gobierno diciéndole que, descubierta una conspiración facciosa, estaban presos sus autores, y los pocos que lograron escapar andaban 186 dispersos y fugitivos, _activamente perseguidos por nuestras columnas_.\"}]},{\"title\":\"Capítulo XXVI\",\"blocks\":[{\"heading\":false,\"text\":\"María Remedios\"},{\"heading\":false,\"text\":\"Nada más entretenido que buscar el origen de los sucesos [5] interesantes que nos asombran o perturban, ni nada más grato que encontrarlo. Cuando vemos arrebatadas pasiones en lucha encubierta o manifiesta, llevados del natural impulso inductivo que acompaña siempre a la observación humana, logramos descubrir la oculta fuente de donde aquel revuelto [10] río ha traído sus aguas, experimentamos sensación muy parecida al gozo de los geógrafos y buscadores de tierras.\"},{\"heading\":false,\"text\":\"Este gozo nos lo ha concedido Dios ahora, porque explorando los escondrijos de los corazones que laten en esta historia, hemos descubierto un hecho que seguramente es el [15] engendrador de los hechos más importantes que hemos narrado; una pasión que es la primera gota de agua de esta alborotada corriente, cuya marcha estamos observando.\"},{\"heading\":false,\"text\":\"Continuemos, pues, la narración. Para ello dejemos a la señora de Polentinos, sin cuidarnos de lo que pudo ocurrirle [20] en la mañana de su diálogo con María Remedios. Penetra llena de zozobra en su vivienda, donde se ve obligada a soportar las excusas y cortesanías del Sr. Pinzón, quien asegura que mientras él existiera, la casa de la señora no sería registrada. Le responde doña Perfecta de un modo [25] altanero, sin dignarse fijar en él los ojos, por cuya razón él pide urbanamente explicaciones de tal desvío, a lo cual ella contesta rogando al Sr, Pinzón abandone su casa, sin perjuicio de dar oportunamente cuenta de su alevosa conducta dentro de ella. Llega D. Cayetano y se cruzan palabras de [30] caballero a caballero; pero como ahora nos interesa más otro asunto, dejemos a los Polentinos y al teniente coronel 187 que se las compongan como puedan, y pasemos a examinar aquello de los manantiales arriba mencionados.\"},{\"heading\":false,\"text\":\"Fijemos la atención en María Remedios, mujer estimable, [5] a la cual es urgente consagrar algunas líneas. Era una señora, una verdadera señora, pues a pesar de su origen humildísimo, las virtudes de su tío carnal el Sr. D. Inocencio, también de bajo origen, mas sublimado por el Sacramento así como por su saber y respetabilidad, [10] habían derramado extraordinario esplendor sobre toda la familia.\"},{\"heading\":false,\"text\":\"El amor de Remedios a Jacinto era una de las más vehementes pasiones que en el corazón maternal pueden caber. Le amaba con delirio; ponía el bienestar de su hijo sobre [15] todas las cosas humanas; creíale el más perfecto tipo de la belleza y del talento, creados por Dios, y diera por verle feliz y grande y poderoso, todos los días de su vida y aun parte de la eterna gloria. El sentimiento materno es el único que, por lo muy santo y noble, admite la exageración; [20] el único que no se bastardea con el delirio. Sin embargo, ocurre un fenómeno singular que no deja de ser común en la vida, y es que si esta exaltación del afecto materno no coincide con la absoluta pureza del corazón y con la honradez perfecta, suele extraviarse y convertirse en frenesí [25] lamentable, que puede contribuir como otra cualquiera pasión desbordada, a grandes faltas y catástrofes.\"},{\"heading\":false,\"text\":\"En Orbajosa, María Remedios pasaba por un modelo de virtud y de sobrinas: quizás lo era en efecto. Servía cariñosamente a cuantos la necesitaban; jamás dió motivo a [30] hablillas y murmuraciones de mal género; jamás se mezcló en intrigas. Era piadosa, no sin dejarse llevar a extremos de mojigatería chocante; practicaba la caridad; gobernaba la casa de su tío con habilidad suprema; era bien recibida, admirada y obsequiada en todas partes, a pesar del sofoco casi intolerable que producía su continuo afán de suspirar y 188 expresarse siempre en tono quejumbroso.\"},{\"heading\":false,\"text\":\"Pero en casa de doña Perfecta, aquella excelente señora sufría una especie de _capitis diminutio_. En tiempos remotos [5] y muy aciagos para la familia del buen Penitenciario, María Remedios (si es verdad, ¿por qué no se ha de decir?) había sido lavandera en la casa de Polentinos. Y no se crea por esto que doña Perfecta la miraba con altanería: nada de eso. Tratábala sin orgullo: sentía hacia ella un cariño [10] verdaderamente fraternal; comían juntas; rezaban juntas; referíanse sus cuitas; ayudábanse mutuamente en sus caridades y en sus devociones, así como en los negocios de la casa... ¡pero fuerza es decirlo! siempre había algo, siempre había una raya invisible, pero infranqueable, entre [15] la señora improvisada y la señora antigua. Doña Perfecta tuteaba a María, y ésta jamás pudo prescindir de ciertas fórmulas. Sentíase tan pequeña la sobrina de D. Inocencio en presencia de la amiga de éste, que su humildad nativa tomaba un tinte extraño de tristeza. Veía que el buen [20] canónigo era en la casa una especie de consejero áulico inamovible; veía a su idolatrado Jacintillo en familiaridad casi amorosa con la señorita, y sin embargo, la pobre madre y sobrina frecuentaba la casa lo menos posible. Es preciso indicar que María Remedios se deseñoraba bastante (pase [25] la palabra) en casa de doña Perfecta, y esto le era desagradable, porque también en aquel espíritu suspirón había, como en todo lo que vive, un poco de orgullo... ¡Ver a su hijo casado con Rosarito; verle rico y poderoso; verle emparentado con doña Perfecta, con la señora!... ¡Ay! [30] esto era para María Remedios la tierra y el cielo, esta vida y la otra, el presente y el más allá, la totalidad suprema de la existencia. Hacía años que su pensamiento y su corazón se llenaban de aquella dulce luz de esperanza. Por esto era buena y mala, por esto era religiosa y humilde o terrible y osada, por esto era todo cuanto hay que ser, porque sin 189 tal idea, María, que era la encarnación de su proyecto, no existiría.\"},{\"heading\":false,\"text\":\"En su físico, María Remedios no podía ser más insignificante. [5] Distinguíase por una lozanía sorprendente que aminoraba en apariencia el valor numérico de sus años, y vestía siempre de luto, a pesar de que su viudez era ya cuenta muy larga.\"},{\"heading\":false,\"text\":\"Habían pasado cinco días desde la entrada de Caballuco [10] en casa del señor Penitenciario. Principiaba la noche. Remedios entró con la lámpara encendida en el cuarto de su tío, y después de dejarla sobre la mesa, se sentó frente al anciano, que desde media tarde permanecía inmóvil y meditabundo en su sillón, cual si le hubieran clavado en él. [15] Sus dedos sostenían la barba, arrugando la morena piel no rapada en tres días.\"},{\"heading\":false,\"text\":\"--¿Caballuco dijo que vendría a cenar aquí esta noche?--preguntó a su sobrina.\"},{\"heading\":false,\"text\":\"--Sí, señor, vendrá. En estas casas respetables es donde [20] el pobrecito está más seguro.\"},{\"heading\":false,\"text\":\"--Pues yo no las tengo todas conmigo a pesar de la respetabilidad de mi casa--repuso el Penitenciario.--¡Cómo se expone el valiente Ramos!... Y me han dicho que en Villahorrenda y su campiña hay mucha gente... qué [25] sé yo cuánta gente... ¿Qué has oído tú?\"},{\"heading\":false,\"text\":\"--Que la tropa está haciendo unas barbaridades....\"},{\"heading\":false,\"text\":\"--¡Es milagro que esos caribes no hayan registrado mi casa! Te juro que si veo entrar uno de los de pantalón encarnado, me caigo sin habla.\"},{\"heading\":false,\"text\":\"[30] --¡Buenos, buenos estamos!--dijo Remedios, echando en un suspiro la mitad de su alma.--No puedo apartar de mi mente la tribulación en que se encuentra la señora doña Perfecta... ¡Ay, tío! debe usted ir allá.\"},{\"heading\":false,\"text\":\"--¿Allá esta noche?... Andan las tropas por las calles. Figúrate que a un soldadote se le antoja... La 190 señora está bien defendida. El otro día registraron la casa y se llevaron los seis hombres armados que allí tenía; pero después se los han devuelto. Nosotros no tenemos quien [5] nos defienda en caso de un atropello.\"},{\"heading\":false,\"text\":\"--Yo he mandado a Jacinto a casa de la señora para que la acompañe un ratito. Si Caballuco viene le diremos que pase también por allá... Nadie me quita de la cabeza que alguna gran fechoría preparan esos pillos contra nuestra [10] amiga. ¡Pobre señora, pobre Rosarito!... Cuando uno piensa que esto podía haberse evitado con lo que propuse a doña Perfecta hace dos días....\"},{\"heading\":false,\"text\":\"--Querida sobrina--dijo flemáticamente el Penitenciario,--hemos hecho todo cuanto en lo humano cabía para [15] realizar nuestro santo propósito... Ya no se puede más. Hemos fracasado, Remedios. Convéncete de ello, y no seas terca: Rosarito no puede ser la mujer de nuestro idolatrado Jacintillo. Tu sueño dorado, tu ideal dichoso que un tiempo nos pareció realizable, y al cual consagré yo las [20] fuerzas todas de mi entendimiento, como buen tío, se ha trocado ya en una quimera, se ha disipado como el humo. Entorpecimientos graves, la maldad de un hombre, la pasión indudable de la niña y otras cosas que callo, han vuelto las cosas del revés. Ibamos venciendo, y de pronto somos [25] vencidos. ¡Ay, sobrina mía! Convéncete de una cosa. Hoy por hoy, Jacinto merece mucho más que esa niña loca.\"},{\"heading\":false,\"text\":\"--Caprichos y terquedades--repuso María con displicencia bastante irrespetuosa.--Vaya con lo que sale usted ahora, tío. Pues las grandes cabezas se están luciendo... [30] Doña Perfecta con sus sublimidades y usted con sus cavilaciones, sirven para cualquier cosa. Es lástima que Dios me haya hecho a mí tan tonta, y dádome este entendimiento de ladrillo y argamasa, como dice la señora, porque si así no fuera, yo resolvería la cuestión.\"},{\"heading\":false,\"text\":\"--¿Tú? 191\"},{\"heading\":false,\"text\":\"--Si ella y usted me hubieran dejado, resuelta estaría ya.\"},{\"heading\":false,\"text\":\"--¿Con los palos?\"},{\"heading\":false,\"text\":\"--No asustarse, ni abrir tanto los ojos, porque no se trata [5] de matar a nadie... ¡vaya!\"},{\"heading\":false,\"text\":\"--Eso de los palos--dijo el canónigo sonriendo,--es como el rascar... ya sabes.\"},{\"heading\":false,\"text\":\"--¡Bah!... diga usted también que soy cruel y sanguinaria... me falta valor para matar un gusanito; bien lo [10] sabe usted... Ya se comprende que no había yo de querer la muerte de un hombre.\"},{\"heading\":false,\"text\":\"--En resumen, hija mía, por más vueltas que le des, el Sr. D. Pepe Rey se lleva la niña. Ya no es posible evitarlo. Él está dispuesto a emplear todos los medios, incluso la [15] deshonra. Si la Rosarito... cómo nos engañaba con aquella carita circunspecta y aquellos ojos celestiales, ¿eh? ... si la Rosarito, digo, no le quisiera... vamos ... todo podría arreglarse; pero ¡ay! le ama como ama el pecador al demonio; está abrasada en criminal fuego; cayó, [20] sobrina mía, cayó en la infernal trampa libidinosa. Seamos honrados y justos; volvamos la vista de la innoble pareja, y no pensemos más en el uno ni en la otra.\"},{\"heading\":false,\"text\":\"--Usted no entiende de mujeres, tío--dijo Remedios con lisonjera hipocresía;--usted es un santo varón; usted [25] no comprende que lo de Rosarito no es más que un caprichillo de esos que pasan, de esos que se curan con un par de refregones en los morros o media docena de azotes.\"},{\"heading\":false,\"text\":\"--Sobrina--dijo D. Inocencio grave y sentenciosamente,--cuando ha habido cosas mayores, los caprichillos no se [30] llaman caprichillos, sino de otra manera.\"},{\"heading\":false,\"text\":\"--Tío, usted no sabe lo que dice--repuso la sobrina, cuyo rostro se inflamó súbitamente.--Pues qué, ¿será usted capaz de suponer en Rosarito?... ¡qué atrocidad! Yo la defiendo, sí, la defiendo... Es pura como un ángel.... Vamos, tío, con esas cosas se me suben los colores a la cara 192 y me pone usted soberbia.\"},{\"heading\":false,\"text\":\"Al decir esto, el semblante del buen clérigo se cubría de una sombra de tristeza, que en apariencia le envejecía diez [5] años.\"},{\"heading\":false,\"text\":\"--Querida Remedios--añadió.--Hemos hecho todo lo humanamente posible y todo lo que en conciencia podía y debía hacerse. Nada más natural que nuestro deseo de ver a Jacintillo emparentado con esa gran familia, la primera [10] de Orbajosa; nada más natural que nuestro deseo de verle dueño de las siete casas del pueblo, de la dehesa de Mundogrande, de las tres huertas del cortijo de Arriba, de la Encomienda, y demás predios urbanos y rústicos que posee esa niña. Tu hijo vale mucho, bien lo saben todos. Rosarito [15] gustaba de él y él de Rosarito. Parecía cosa hecha. La misma señora, sin entusiasmarse mucho, a causa sin duda de nuestro origen, parecía bien dispuesta a ello, a causa de lo mucho que me estima y venera, como a confesor y amigo... Pero de repente se presenta ese malhadado joven. [20] La señora me dice que tiene un compromiso con su hermano y que no se atreve a rechazar la proposición por éste hecha. ¡Conflicto grave! Pero ¿qué hago yo en vista de esto? ¡Ay! no lo sabes tú bien. Yo te soy franco: si hubiera visto en el Sr. de Rey un hombre de buenos principios, [25] capaz de hacer feliz a Rosario, no habría intervenido en el asunto; pero el tal joven me pareció una calamidad, y como director espiritual de la casa debí tomar cartas en el asunto y las tomé. Ya sabes que le puse la proa, como vulgarmente se dice. Desenmascaré sus vicios; descubrí su [30] ateísmo; puse a la vista de todo el mundo la podredumbre de aquel corazón materializado, y la señora se convenció de que entregaba a su hija al vicio... ¡Ay! qué afanes pasé. La señora vacilaba; yo fortalecía su ánimo indeciso; aconsejábale los medios lícitos que debía emplear contra el sobrinejo para alejarle sin escándalo; sugeríale ideas ingeniosas, y como ella me mostraba a menudo su pura conciencia 193 llena de alarmas, yo la tranquilizaba demarcando hasta qué punto eran lícitas las batallas que librábamos contra [5] aquel fiero enemigo. Jamás aconsejé medios violentos ni sanguinarios, ni atrocidades de mal género, sino sutiles trazas que no contenían pecado. Estoy tranquilo, querida sobrina. Pero bien sabes tú que he luchado, que he trabajado como un negro. ¡Ay! cuando volvía a casa por las [10] noches y decía: \\\"Mariquilla, vamos bien, vamos muy bien,\\\" tú te volvías loca de contento y me besabas las manos cien veces, y decías que era yo el hombre mejor del mundo. ¿Por qué te enfureces ahora, desfigurando tu noble carácter y pacífica condición? ¿Por qué me riñes? ¿Por qué dices [15] que estás soberbia y me llamas en buenas palabras Juan Lanas?\"},{\"heading\":false,\"text\":\"--Porque usted--dijo la mujer sin cejar en su irritación,--se ha acobardado de repente.\"},{\"heading\":false,\"text\":\"--Es que todo se nos vuelve en contra, mujer. El maldito [20] ingeniero, favorecido por la tropa, está resuelto a todo. La chiquilla le ama, la chiquilla... no quiero decir más. No puede ser, te digo que no puede ser.\"},{\"heading\":false,\"text\":\"--¡La tropa! Pero usted cree como doña Perfecta que va a haber una guerra, y que para echar de aquí a D. Pepe, [25] se necesita que media nación se levante contra la otra media... La señora se ha vuelto loca, y usted allá se le va.\"},{\"heading\":false,\"text\":\"--Creo lo mismo que ella. Dada la íntima conexión de Rey con los militares, la cuestión personal se agranda... Pero ¡ay! sobrina mía, si hace dos días tuve esperanza de [30] que nuestros valientes echaran de aquí a puntapiés a la tropa, desde que he visto el giro que han tomado las cosas; desde que he visto que la mayor parte son sorprendidos antes de pelear, y que Caballuco se esconde y que esto se lo lleva la trampa, desconfío de todo. Los buenos principios no tienen aún bastante fuerza material para hacer pedazos 194 a los ministros y emisarios del error... ¡Ay! sobrina mía, resignación, resignación.\"},{\"heading\":false,\"text\":\"Apropiándose entonces D. Inocencio el medio de expresión [5] que caracterizaba a su sobrina, suspiró dos o tres veces ruidosamente. María, contra todo lo que podía esperarse, guardó profundo silencio. No había en ella, al menos aparentemente, ni cólera, ni tampoco el sentimentalismo superficial de su ordinaria vida; no había sino una aflicción profunda [10] y modesta. Poco después de que el buen tío concluyera su perorata, dos lágrimas rodaron por las sonrosadas mejillas de la sobrina: no tardaron en oírse algunos sollozos mal comprimidos, y poco a poco, así como van creciendo en ruido y forma la hinchazón y tumulto de un mar que empieza [15] a alborotarse, así fué encrespándose aquel oleaje del dolor de María Remedios, hasta que rompió en deshecho llanto.\"}]},{\"title\":\"Capítulo XXVII\",\"blocks\":[{\"heading\":false,\"text\":\"El tormento de un canónigo\"},{\"heading\":false,\"text\":\"--¡Resignación, resignación!--volvió a decir D. Inocencio.\"},{\"heading\":false,\"text\":\"[20] --¡Resignación, resignación!--repitió ella, enjugando sus lágrimas.--Puesto que mi querido hijo ha de ser siempre un pelagatos, séalo en buen hora. Los pleitos escasean; bien pronto llegará el día en que lo mismo será la abogacía que nada. ¿De qué vale el talento? ¿De qué valen [25] tanto estudio y romperse la cabeza? ¡Ay! Somos pobres. Llegará un día, Sr. D. Inocencio, en que mi pobre hijo no tendrá una almohada sobre que reclinar la cabeza.\"},{\"heading\":false,\"text\":\"--¡Mujer!\"},{\"heading\":false,\"text\":\"--¡Hombre!... Y si no, dígame: ¿qué herencia piensa [30] usted dejarle cuando cierre el ojo? Cuatro cuartos, seis libruchos, miseria y nada más... Van a venir unos tiempos... 195 ¡qué tiempos, señor tío!... ¡Mi pobre hijo, que se está poniendo muy delicado de salud, no podrá trabajar ... ya se le marea la cabeza desde que lee un libro; ya le [5] dan bascas y jaqueca siempre que trabaja de noche!... tendrá que mendigar un destinejo; tendré yo que ponerme a la costura, y quién sabe, quién sabe... como no tengamos que pedir limosna.\"},{\"heading\":false,\"text\":\"--¡Mujer!\"},{\"heading\":false,\"text\":\"[10] --Bien sé lo que digo... Buenos tiempos van a venir--añadió la excelente mujer, forzando más el sonsonete llorón con que hablaba.--¡Dios mío! ¿Qué va a ser de nosotros? ¡Ah! Sólo el corazón de una madre siente estas cosas... Sólo las madres son capaces de sufrir tantas [15] penas por el bienestar de un hijo. Usted, ¿cómo lo ha de comprender? No: una cosa es tener hijos y pasar amarguras por ellos, y otra cosa es cantar el _gori gori_ en la catedral y enseñar latín en el Instituto... Vea usted de qué le vale a mi hijo el ser sobrino de usted y el haber sacado [20] tantas notas de sobresaliente, y ser el primor y la gala de Orbajosa... Se morirá de hambre, porque ya sabemos lo que da la abogacía, o tendrá que pedir a los diputados un destino en la Habana, donde le matará la fiebre amarilla....\"},{\"heading\":false,\"text\":\"--¡Pero mujer!\"},{\"heading\":false,\"text\":\"[25] --No, si no me apuro, si ya callo, si no le molesto a usted más. Soy muy impertinente, muy llorona, muy suspirona, y no se me puede aguantar, porque soy madre cariñosa y miro por el bien de mi amado hijo. Yo me moriré, sí señor, me moriré en silencio y ahogaré mi dolor, me beberé [30] mis lágrimas para no mortificar al señor canónigo... Pero mi idolatrado hijo me comprenderá, y no se tapará los oídos como usted hace en este momento... ¡ay de mí! El pobre Jacinto sabe que me dejaría matar por él, y que le proporcionaría la felicidad a costa de mi vida. ¡Pobrecito niño de mis entrañas! Tener tanto mérito, y vivir condenado 196 a un pasar mediano, a una condición humilde, porque no, señor tío, no se ensoberbezca usted... Por más que echemos humos, siempre será usted el hijo del tío Tinieblas, [5] el sacristán de San Bernardo... y yo no seré nunca más que la hija de Ildefonso Tinieblas, su hermano de usted, el que vendía pucheros, y mi hijo será el nieto de los Tinieblas ... que tenemos un tenebrario en nuestra casta, y nunca saldremos de la obscuridad, ni poseeremos un pedazo [10] de terruño donde decir: \\\"esto es mío,\\\" ni trasquilaremos una oveja propia, ni ordeñaremos jamás una cabra propia, ni meteré mis manos hasta el codo en un saco de trigo trillado y aventado en nuestras eras... todo esto a causa de su poco ánimo de usted, de su bobería y corazón amerengado....\"},{\"heading\":false,\"text\":\"[15] --¡Pero... pero mujer!\"},{\"heading\":false,\"text\":\"Subía más de tono el canónigo cada vez que repetía esta frase, y puestas las manos en los oídos, sacudía a un lado y otro la cabeza con doloroso ademán de desesperación. La chillona cantinela de María Remedios era cada vez más [20] aguda, y penetraba en el cerebro del infeliz y ya aturdido clérigo como una saeta. Pero de repente transformóse el rostro de aquella mujer, mudáronse los plañideros sollozos en una voz bronca y dura, palideció su rostro, temblaron sus labios, cerráronse sus puños, cayéronle sobre la frente algunas [25] guedejas del desordenado cabello, secáronse por completo sus ojos al calor de la ira que bramaba en su pecho, levantóse del asiento, y no como una mujer, sino como una harpía, gritó de este modo:\"},{\"heading\":false,\"text\":\"--¡Yo me voy de aquí, yo me voy con mi hijo!... [30] Nos iremos a Madrid; no quiero que mi hijo se pudra en este poblachón. Estoy cansada de ver que mi hijo, al amparo de la sotana, no es ni será nunca nada. ¿Lo oye usted, señor tío? ¡Mi hijo y yo nos vamos! Usted no nos verá nunca más; pero nunca más.\"},{\"heading\":false,\"text\":\"Don Inocencio había cruzado las manos y recibía los furibundos 197 rayos de su sobrina con la consternación de un reo a quien la presencia del verdugo quita ya toda esperanza.\"},{\"heading\":false,\"text\":\"--Por Dios, Remedios--murmuró con voz dolorida,--por [5] la Virgen Santísima....\"},{\"heading\":false,\"text\":\"Aquellas crisis y horribles erupciones del manso carácter de la sobrina eran tan fuertes como raras, y se pasaban a veces cinco o seis años sin que D. Inocencio viera a Remedios convertirse en una furia.\"},{\"heading\":false,\"text\":\"[10] --¡Soy madre!... ¡Soy madre!... y puesto que nadie mira por mi hijo, miraré yo, yo misma--rugió la improvisada leona.\"},{\"heading\":false,\"text\":\"--Por María Santísima, mujer, no te arrebates... Mira que estás pecando... Recemos un Padre nuestro y un [15] Ave María, y verás cómo se te pasa eso.\"},{\"heading\":false,\"text\":\"Diciendo esto, el Penitenciario temblaba y sudaba. ¡Pobre pollo en las garras del buitre! La mujer transformada acabó de estrujarle con estas palabras:\"},{\"heading\":false,\"text\":\"--Usted no sirve para nada; usted es un mandria... [20] Mi hijo y yo nos marcharemos de aquí para siempre, para siempre. Yo le conseguiré una posición a mi hijo, yo le buscaré una buena conveniencia, ¿entiende usted? Así como estoy dispuesta a barrer las calles con la lengua, si de este modo fuera preciso ganarle la comida, así también [25] revolveré la tierra para buscar una posición a mi hijo, para que suba, y sea rico, y personaje, y caballero, y propietario, y señor, y grande, y todo cuanto hay que ser, todo, todo.\"},{\"heading\":false,\"text\":\"--¡Dios me favorezca!--exclamó D. Inocencio dejándose caer en el sillón e inclinando la cabeza sobre el pecho.\"},{\"heading\":false,\"text\":\"[30] Hubo una pausa, durante la cual se oía el agitado resuello de la mujer furiosa.\"},{\"heading\":false,\"text\":\"--Mujer--dijo al fin D. Inocencio,--me has quitado diez años de vida; me has abrasado la sangre; me has vuelto loco... ¡Dios me dé la serenidad que para aguantarte necesito! Señor, paciencia, paciencia es lo que 198 quiero; y tú, sobrina, hazme el favor de llorar y lagrimear y estar suspirando a moco y baba diez años, pues tu maldita maña de los pucheros, que tanto me enfada, es preferible a [5] esas locas iras. Si no supiera que en el fondo eres buena... Vaya, que para haber confesado y recibido a Dios esta mañana, te estás portando.\"},{\"heading\":false,\"text\":\"--Sí, pero es por usted, por usted.\"},{\"heading\":false,\"text\":\"--¿Porque en el asunto de Rosario y de Jacinto te digo [10] \\\"resignación\\\"?\"},{\"heading\":false,\"text\":\"--Porque cuando todo marcha bien, usted se vuelve atrás y permite que el Sr. Rey se apodere de Rosarito.\"},{\"heading\":false,\"text\":\"--¿Y cómo lo voy a evitar? Bien dice la señora que tienes entendimiento de ladrillo. ¿Quieres que salga por [15] ahí con una espada, y en un quítame allá esas pajas haga picadillo a toda la tropa, y después me encare con Rey y le diga: \\\"o usted me deja en paz a la niña o le corto el pescuezo\\\"?\"},{\"heading\":false,\"text\":\"--No, pero cuando aconsejé a la señora que diera un [20] susto a su sobrino, usted se ha opuesto, en vez de aconsejarle lo mismo que yo.\"},{\"heading\":false,\"text\":\"--Tú estás loca con eso del susto.\"},{\"heading\":false,\"text\":\"--Porque \\\"muerto el perro se acabó la rabia.\\\"\"},{\"heading\":false,\"text\":\"--Yo no puedo aconsejar eso que llamas susto y que [25] puede ser una cosa tremenda.\"},{\"heading\":false,\"text\":\"--Sí, porque soy una matona, ¿no es verdad, tío?\"},{\"heading\":false,\"text\":\"--Ya sabes que los juegos de manos son juegos de villanos. Además, ¿crees que ese hombre se dejará asustar? ¿Y sus amigos?\"},{\"heading\":false,\"text\":\"[30] --De noche sale solo.\"},{\"heading\":false,\"text\":\"--¿Tú qué sabes?\"},{\"heading\":false,\"text\":\"--Lo sé todo, y no da un paso sin que yo me entere, ¿estamos? La viuda del Cuzco me tiene al tanto de todo.\"},{\"heading\":false,\"text\":\"--Vamos, no me vuelvas loco. ¿Y quién le va a dar ese 199 susto?... Sepámoslo.\"},{\"heading\":false,\"text\":\"--Caballuco.\"},{\"heading\":false,\"text\":\"--¿De modo qué él está dispuesto?...\"},{\"heading\":false,\"text\":\"[5] --No, pero lo estará si usted se lo manda.\"},{\"heading\":false,\"text\":\"--Vamos, mujer, déjame en paz. Yo no puedo mandar tal atrocidad. ¡Un susto! ¿Y qué es eso? ¿Tú le has hablado ya?\"},{\"heading\":false,\"text\":\"--Sí, señor; pero no me ha hecho caso, mejor dicho, se [10] niega a ello. En Orbajosa no hay más que dos personas que puedan decidirle con una simple orden: usted o doña Perfecta.\"},{\"heading\":false,\"text\":\"--Pues que se lo mande la señora si quiere. Jamás aconsejaré que se empleen medios violentos y brutales. [15] ¿Querrás creer que cuando Caballuco y algunos de los suyos estaban tratando de levantarse en armas, no pudieron sacarme una sola palabra incitándoles a derramar sangre? No, eso no... Si doña Perfecta quiere hacerlo....\"},{\"heading\":false,\"text\":\"--Tampoco quiere. Esta tarde he estado hablando con [20] ella dos horas, y dice que predicará la guerra favoreciéndola por todos los medios; pero que no mandará a un hombre que hiera por la espalda a otro. Tendría razón en oponerse si se tratara de cosa mayor... pero no quiero que haya heridas; yo no quiero más que un susto.\"},{\"heading\":false,\"text\":\"[25] --Pues si doña Perfecta no quiere ordenar que se dé sustos al ingeniero, yo tampoco, ¿entiendes? Antes que nada es mi conciencia.\"},{\"heading\":false,\"text\":\"--Bueno--repuso la sobrina.--Dígale usted a Caballuco que me acompañe esta noche... no le diga usted [30] más que eso.\"},{\"heading\":false,\"text\":\"--¿Vas a salir tarde?\"},{\"heading\":false,\"text\":\"--Voy a salir, sí señor. Pues qué, ¿no salí también anoche?\"},{\"heading\":false,\"text\":\"--¿Anoche? No lo supe; si lo hubiera sabido, me hubiera enfadado, sí señora.\"},{\"heading\":false,\"text\":\"--No le diga usted a Caballuco sino lo siguiente: \\\"Querido 200 Ramos, le estimaré mucho que acompañe a mi sobrina a cierta diligencia que tiene que hacer esta noche, y que la defienda si acaso se ve en algún peligro.\\\"\"},{\"heading\":false,\"text\":\"[5] --Eso sí lo puedo hacer. Que te acompañe... que te defienda. ¡Ah, picarona! tú quieres engañarme, haciéndome cómplice de alguna majadería.\"},{\"heading\":false,\"text\":\"--Ya... ¿qué cree usted?--dijo irónicamente María Remedios.--Entre Ramos y yo vamos a degollar mucha [10] gente esta noche.\"},{\"heading\":false,\"text\":\"--No bromees. Te repito que no le aconsejaré a Ramos nada que tenga visos de maldad. Me parece que está ahí....\"},{\"heading\":false,\"text\":\"Oyóse ruido en la puerta de la calle. Luego sonó la voz [15] de Caballuco que hablaba con el criado, y poco después el héroe de Orbajosa penetró en la estancia.\"},{\"heading\":false,\"text\":\"--Noticias, vengan noticias, Sr. Ramos--dijo el clérigo.--Vaya, que si no nos da usted alguna esperanza en cambio de la cena y de la hospitalidad... ¿Qué hay en [20] Villahorrenda?\"},{\"heading\":false,\"text\":\"--Alguna cosa--repuso el valentón sentándose con muestras de cansancio.--Pronto verá usted si servimos para algo.\"},{\"heading\":false,\"text\":\"Como todas las personas que tienen importancia o quieren dársela, Caballuco mostraba gran reserva.\"},{\"heading\":false,\"text\":\"[25] --Esta noche, amigo mío, se llevará usted, si quiere, el dinero que me han dado para....\"},{\"heading\":false,\"text\":\"--Buena falta hace... Como lo huelan los de tropa no me dejarán pasar--dijo Ramos riendo brutalmente.\"},{\"heading\":false,\"text\":\"--Calle usted, hombre... Ya sabemos que usted pasa [30] siempre que se le antoja. Pues no faltaba más. Los militares son gente de manga ancha... y si se pusieran pesados, con un par de duros, ¿eh? Vamos, veo que no viene usted mal armado... No le falta más que un cañón de a ocho. Pistolitas, ¿eh?... También navaja.\"},{\"heading\":false,\"text\":\"--Por lo que pueda suceder--dijo Caballuco, sacando 201 el arma del cinto y mostrando su horrible hoja.\"},{\"heading\":false,\"text\":\"--¡Por Dios y la Virgen!--exclamó María Remedios, cerrando los ojos y apartando con miedo el rostro.--Guarde [5] usted ese chisme. Me horrorizo sólo de verlo.\"},{\"heading\":false,\"text\":\"--Si ustedes no lo llevan a mal--dijo Ramos cerrando el arma,--cenaremos.\"},{\"heading\":false,\"text\":\"María Remedios dispuso todo con precipitación, para que el héroe no se impacientase.\"},{\"heading\":false,\"text\":\"[10] --Oiga usted una cosa, Sr. Ramos--dijo D. Inocencio a su huésped cuando se pusieron a cenar.--¿Tiene usted muchas ocupaciones esta noche?\"},{\"heading\":false,\"text\":\"--Algo hay que hacer--repuso el bravo.--Ésta es la última noche que vengo a Orbajosa, la ultima. Tengo que [15] recoger algunos muchachos que quedan por aquí, y vamos a ver cómo sacamos el salitre y el azufre que está en casa de Cirujeda.\"},{\"heading\":false,\"text\":\"--Lo decía--añadió bondadosamente el cura, llenando el plato de su amigo,--porque mi sobrina quiere que la [20] acompañe usted un momento. Tiene que hacer no sé qué diligencia y es algo tarde para ir sola.\"},{\"heading\":false,\"text\":\"--¿Va a casa de doña Perfecta?--preguntó Ramos.--Allí he estado hace un momento; no quise detenerme.\"},{\"heading\":false,\"text\":\"--¿Cómo está la señora?\"},{\"heading\":false,\"text\":\"[25] --Miedosilla. Esta noche he sacado los seis mozos que tenía en la casa.\"},{\"heading\":false,\"text\":\"--Hombre: ¿cree usted que no hacen falta allí?--dijo Remedios con zozobra.\"},{\"heading\":false,\"text\":\"--Más falta hacen en Villahorrenda. Dentro de las [30] casas se pudre la gente valerosa, ¿no es verdad, señor canónigo?\"},{\"heading\":false,\"text\":\"--Señor Ramos, aquella casa no debe estar nunca sola--dijo el Penitenciario.\"},{\"heading\":false,\"text\":\"--Con los criados basta y sobra. ¿Pero usted cree, Sr.\"},{\"heading\":false,\"text\":\"D. Inocencio, que el brigadier se ocupa de asaltar casas 202 ajenas?\"},{\"heading\":false,\"text\":\"--Sí; pero bien sabe usted que ese ingeniero de tres mil docenas de demonios....\"},{\"heading\":false,\"text\":\"[5] --Para eso... en la casa no faltan escobas--manifestó Cristóbal jovialmente.--Si al fin y al cabo no tendrán más remedio que casarlos... Después de lo que ha pasado....\"},{\"heading\":false,\"text\":\"--Señor Ramos--dijo Remedios súbitamente enojada,--se [10] me figura que no entiende usted gran cosa en esto de casar a la gente.\"},{\"heading\":false,\"text\":\"--Dígolo porque esta noche, hace un momento, vi que la señora y la niña estaban haciendo al modo de una reconciliación. Doña Perfecta besuqueaba a Rosarito, y todo era [15] echarse palabrillas tiernas y mimos.\"},{\"heading\":false,\"text\":\"--¡Reconciliación! usted con eso de los armamentos ha perdido la chaveta... Pero en fin, ¿me acompaña usted o no?\"},{\"heading\":false,\"text\":\"--No es a la casa de la señora donde quiere ir--dijo el [20] clérigo,--sino a la posada de la viuda de Cuzco. Estaba diciendo que no se atreve a ir sola, porque teme ser insultada....\"},{\"heading\":false,\"text\":\"--¿Por quién?\"},{\"heading\":false,\"text\":\"--Bien se comprende. Por ese ingeniero de tres mil o [25] cuatro mil docenas de demonios. Anoche mi sobrina le vió allí y le dijo cuatro frescas, por cuya razón no las tiene todas consigo esta noche. El mocito es vengativo y procaz.\"},{\"heading\":false,\"text\":\"--No sé si podré ir...--indicó Caballuco,--como ando ahora escondido, no puedo desafiar al D. José Poquita [30] Cosa. Si yo no estuviera como estoy, con media cara tapada y la otra medio descubierta, ya le había roto treinta veces el espinazo. ¿Pero qué sucede si caigo sobre él? Que me descubro; caen sobre mí los soldados, y adiós Caballuco. En cuanto a darle un golpe a traición, es cosa que no sé hacer, ni está en mi natural, ni la señora lo consiente 203 tampoco. Para solfas con alevosía no sirve Cristóbal Ramos.\"},{\"heading\":false,\"text\":\"--Pero hombre, ¿estamos locos?... ¿qué está usted [5] hablando?--dijo el Penitenciario con innegables muestras de asombro.--Ni por pienso le aconsejo yo a usted que maltrate a ese caballero. Antes me dejaré cortar la lengua que aconsejar una bellaquería. Los malos caerán, es verdad; pero Dios es quien debe fijar el momento, no yo. No [10] se trata tampoco de dar palos. Antes recibiré yo diez docenas de ellos que recomendar a un cristiano la administración de tales medicinas. Sólo digo a usted una cosa (añadió, mirando al bravo por encima de los espejuelos), y es, que como mi sobrina va allá, como es probable, muy [15] probable, ¿no es eso, Remedios?... que tenga que decir algunas palabrejas a ese hombre, recomiendo a usted que no la desampare en caso de que se vea insultada....\"},{\"heading\":false,\"text\":\"--Esta noche tengo que hacer--repuso lacónica y secamente Caballuco.\"},{\"heading\":false,\"text\":\"[20] --Ya lo oyes, Remedios. Deja tu diligencia para mañana.\"},{\"heading\":false,\"text\":\"--Eso sí que no puede ser. Iré sola.\"},{\"heading\":false,\"text\":\"--No, no irás, sobrina mía. Tengamos la fiesta en paz. El Sr. Ramos tiene que hacer y no puede acompañarte. [25] Figúrate que eres injuriada por ese hombre grosero....\"},{\"heading\":false,\"text\":\"--¡Insultada... insultada una señora por ese!...--exclamó Caballuco.--Vamos, no puede ser.\"},{\"heading\":false,\"text\":\"--Si usted no tuviera ocupaciones... ¡bah, bah! ya estaría yo tranquilo.\"},{\"heading\":false,\"text\":\"[30] --Ocupaciones tengo--dijo el Centauro levantándose de la mesa;--pero si es empeño de usted....\"},{\"heading\":false,\"text\":\"Hubo una pausa. El Penitenciario había cerrado los ojos y meditaba.\"},{\"heading\":false,\"text\":\"--Empeño mío es, Sr. Ramos--dijo al fin.\"},{\"heading\":false,\"text\":\"--Pues no hay más que hablar. Iremos, señora doña María. 204\"},{\"heading\":false,\"text\":\"--Ahora, querida sobrina--- dijo D. Inocencio entre serio y jovial,--puesto que hemos concluído de cenar, tráeme la jofaina.\"},{\"heading\":false,\"text\":\"[5] Dirigió a su sobrina una mirada penetrante, y acompañándolas de la acción correspondiente, profirió estas palabras:\"},{\"heading\":false,\"text\":\"--Yo me lavo las manos.\"}]},{\"title\":\"Capítulo XXVIII\",\"blocks\":[{\"heading\":false,\"text\":\"De Pepe Rey a D. Juan Rey\"},{\"heading\":false,\"text\":\"_Orbajosa 12 de Abril_.\"},{\"heading\":false,\"text\":\"\\\"Querido padre: perdóneme usted si por primera vez le desobedezco no saliendo de aquí, ni renunciando a mi propósito. [10] El consejo y ruego de usted son propios de un padre bondadoso y honrado: mi terquedad es propia de un hijo insensato; pero en mí pasa una cosa singular; terquedad y honor se han juntado y confundido de tal modo, que la idea de disuadirme y ceder me causa vergüenza. He [15] cambiado mucho. Yo no conocía estos furores que me abrasan. Antes me reía de toda obra violenta, de las exageraciones de los hombres impetuosos, como de las brutalidades de los malvados. Ya nada de esto me asombra, porque en mí mismo encuentro a todas horas cierta capacidad [20] terrible para la perversidad. A usted puedo hablarle como se habla a solas con Dios y con la conciencia; a usted puedo decirle que soy un miserable, porque es un miserable quien carece de aquella poderosa fuerza moral contra sí mismo, que castiga las pasiones y somete la vida al duro [25] régimen de la conciencia. He carecido de la entereza cristiana que contiene el espíritu del hombre ofendido en un hermoso estado de elevación sobre las ofensas que recibe y los enemigos que se las hacen; he tenido la debilidad de abandonarme a una ira loca, poniéndome al bajo nivel de 205 mis detractores, devolviéndoles golpes iguales a los suyos, y tratando de confundirles por medios aprendidos en su propia indigna escuela. ¡Cuánto siento que no estuviera usted [5] a mi lado para apartarme de este camino! Ya es tarde. Las pasiones no tienen espera. Son impacientes, y piden su presa a gritos y con la convulsión de una espantosa sed moral. He sucumbido. No puedo olvidar lo que tantas veces me ha dicho usted, y es que la ira puede llamarse la [10] peor de las pasiones, porque transformando de improviso nuestro carácter, engendra todas las demás maldades, y a todas les presta su infernal llamarada.\"},{\"heading\":false,\"text\":\"\\\"Pero no ha sido sola la ira, sino un fuerte sentimiento expansivo lo que me ha traído a tal estado, el amor profundo [15] y entrañable que profeso a mi prima, única circunstancia que me absuelve. Y si el amor no, la compasión me habría impulsado a desafiar el furor y las intrigas de su terrible hermana de usted, porque la pobre Rosario, colocada entre su afecto irresistible y su madre, es hoy uno de los seres [20] más desgraciados que existen sobre la tierra. El amor que me tiene y que corresponde al mío, ¿no me da derecho a abrir, como pueda, las puertas de su casa y sacarla de allí, empleando la ley hasta donde la ley alcance, y usando la fuerza desde el punto en que la ley me desampare? Creo [25] que la rigurosísima escrupulosidad moral de usted no dará una respuesta afirmativa a esta proposición; pero yo he dejado de ser aquel carácter metódico y puro, conformado en su conciencia con la exactitud de un tratado. Yo no soy aquel a quien una educación casi perfecta dió pasmosa [30] en sus sentimientos; ahora soy un hombre como irregularidadotro cualquiera; de un solo paso he entrado en el terreno común de lo injusto y de lo malo. Prepárese usted a oír cualquier barbaridad, que será obra mía. Yo cuidaré de notificar a usted las que vaya cometiendo.\"},{\"heading\":false,\"text\":\"\\\"Pero ni la confesión de mis culpas me quitará la 206 responsabilidad de los sucesos graves que han ocurrido y ocurrirán; ni ésta, por mucho que argumente, recaerá toda entera sobre su hermana de usted. La responsabilidad de doña [5] Perfecta es inmensa, seguramente. ¿Cuál será la extensión de la mía? ¡Ah, querido padre! No crea usted nada de lo que oiga respecto a mí, y aténgase tan sólo a lo que yo le revele. Si le dicen que he cometido una villanía deliberada, responda que es mentira. Difícil, muy difícil me es juzgarme [10] a mí mismo en el estado de turbación en que me hallo; pero me atrevo a asegurar que no he producido deliberadamente el escándalo. Bien sabe usted a dónde puede llegar la pasión favorecida en su horrible crecimiento invasor por las circunstancias.\\\"\"},{\"heading\":false,\"text\":\"[15] \\\"Lo que más amarga mi vida es haber empleado la ficción, el engaño y bajos disimulos. ¡Yo que era la verdad misma! He perdido mi propia hechura.... Pero, ¿es esto la perversidad mayor en que puede incurrir el alma? ¿Empiezo ahora o acabo? Nada sé. Si Rosario con su [20] mano celeste no me saca de este infierno de mi conciencia, deseo que venga usted a sacarme. Mi prima es un ángel, y padeciendo por mí, me ha enseñado muchas cosas que antes no sabía.\\\"\"},{\"heading\":false,\"text\":\"\\\"No extrañe usted la incoherencia de lo que escribo. [25] Diversos sentimientos me inflaman. Me asaltan a ratos ideas dignas verdaderamente de mi alma inmortal; pero a ratos caigo también en un desfallecimiento lamentable, y pienso en los hombres débiles y menguados, cuya bajeza me ha pintado usted con vivos colores para que los aborrezca. [30] Tal como hoy me hallo, estoy dispuesto al mal y al bien. Dios tenga piedad de mí. Ya sé lo que es la oración, una suplica grave y reflexiva, tan personal que no se aviene con fórmulas aprendidas de memoria; una expansión del alma que se atreve a extenderse hasta buscar su origen; lo contrario del remordimiento, que es una contradicción de la 207 misma alma, envolviéndose y ocultándose con la ridicula pretensión de que nadie la vea. Usted me ha enseñado muy buenas cosas; pero ahora estoy en prácticas, como [5] decimos los ingenieros; hago estudios sobre el terreno, y con esto mis conocimientos se ensanchan y fijan.... Se me está figurando ahora que no soy tan malo como yo mismo creo. ¿Será así?\\\"\"},{\"heading\":false,\"text\":\"\\\"Concluyo esta carta a toda prisa. Tengo que enviarla [10] con unos soldados que van hacia la estación de Villahorrenda, porque no hay que fiarse del correo de esta gente.\\\"\"},{\"heading\":false,\"text\":\"_14 de Abril_.\"},{\"heading\":false,\"text\":\"\\\"Le divertiría a usted, querido padre, si pudiera hacerle comprender cómo piensa la gente de este poblachón. Ya sabrá usted que casi todo este país se ha levantado en [15] armas. Era cosa prevista, y los políticos se equivocan si creen que es cosa de un par de días. La hostilidad contra nosotros y contra el Gobierno la tienen los orbajosenses en su espíritu, formando parte de él como la fe religiosa. Concretándome a la cuestión particular con mi tía, diré a usted [20] una cosa singular, y es que la pobre señora, que tiene el feudalismo en la médula de los huesos, ha imaginado que yo voy a atacar su casa para robarle su hija, como los señores de la Edad Media atacaban un castillo enemigo para consumar cualquier desafuero. No se ría usted, que es [25] verdad: tales son las ideas de esta gente. Excuso decir a usted que me tiene por un monstruo, por una especie de rey moro herejote; y los militares con quienes he hecho amistad aquí no merecen mejor concepto. En casa de doña Perfecta es cosa corriente que la tropa y yo formamos una [30] coalición diabólica y antireligiosa para quitarle a Orbajosa sus tesoros, su fe y sus muchachas. Me consta que su hermana de usted cree a pie juntillas que yo le voy a tomar 208 por asalto la casa, y no es dudoso que detrás de la puerta habrá alguna barricada.\\\"\"},{\"heading\":false,\"text\":\"\\\"Pero no puede ser de otra manera. Aquí tienen las [5] ideas más anticuadas acerca de la sociedad, de la religión, del Estado, de la propiedad. La exaltación religiosa que les impulsa a emplear la fuerza contra el Gobierno, por defender una fe que nadie ha atacado y que ellos no tienen tampoco, despierta en su ánimo resabios feudales, y como [10] resolverían sus cuestiones por la fuerza bruta y a sangre y fuego, degollando a todo el que no piense como ellos, creen que no hay en el mundo quien emplee otros medios.\\\"\"},{\"heading\":false,\"text\":\"\\\"Lejos de ser mi intento hacer quijotadas en la casa de esa señora, he procurado evitarle algunas molestias, de que [15] no se libraron los demás vecinos. Por mi amistad con el brigadier no les han obligado a presentar, como se mandó, una lista de todos los hombres de su servidumbre que se han marchado con la facción; y si se le registró la casa, me consta que fue por fórmula; y si le desarmaron los seis [20] hombres que allí tenía, después ha puesto otros tantos y nada se le ha hecho. Vea usted a lo que está reducida mi hostilidad a la señora.\\\"\"},{\"heading\":false,\"text\":\"\\\"Verdad es que yo tengo el apoyo de los jefes militares; pero lo utilizo tan sólo para no ser insultado o maltratado [25] por esta gente implacable. Mis probabilidades de éxito consisten en que las autoridades recientemente puestas por el jefe militar son todas amigas. Tomo de ellas mi fuerza moral y les intimido. No sé si me veré en el caso de cometer alguna acción violenta; pero no se asuste usted, que el [30] asalto y toma de la casa es una pura y loca preocupación feudal de su hermana de usted. La casualidad me ha puesto en situación ventajosa. La ira, la pasión que arde en mí, me impulsarán a aprovecharla. No sé hasta dónde iré.\\\"\"},{\"heading\":false,\"text\":\"_17 de Abril._ 209\"},{\"heading\":false,\"text\":\"\\\"La carta de usted me ha dado un gran consuelo. Sí; puedo conseguir mi objeto, usando tan sólo los recursos de la ley, eficaces completamente para esto. He consultado a las autoridades de aquí, y todas me confirman en lo que [5] usted me indica. Estoy contento. Ya que he inculcado en el ánimo de mi prima la idea de la desobediencia, que sea al menos al amparo de las leyes sociales. Haré lo que usted me manda, es decir, renunciaré a la colaboración un poco fea de Pinzón; destruiré la solidaridad aterradora que [10] establecí con los militares; dejaré de envanecerme con el poder de ellos; pondré fin a las aventuras, y en el momento oportuno procederé con calma, prudencia y toda la benignidad posible. Mejor es así. Mi coalición, mitad seria, mitad burlesca, con el ejército, ha tenido por objeto ponerme [15] al amparo de las brutalidades de los orbajosenses y de los criados y deudos de mi tía. Por lo demás, siempre he rechazado la idea de lo que llamamos _la intervención armada_.\\\"\"},{\"heading\":false,\"text\":\"\\\"El amigo que me favorecía ha tenido que salir de la casa; pero no estoy en completa incomunicación con mi [20] prima. La pobrecita demuestra un valor heroico en medio de sus penas, y me obedecerá ciegamente.\\\"\"},{\"heading\":false,\"text\":\"\\\"Esté usted sin cuidado respecto a mi seguridad personal. Por mi parte nada temo y estoy muy tranquilo.\\\"\"},{\"heading\":false,\"text\":\"_20 de Abril._\"},{\"heading\":false,\"text\":\"\\\"Hoy no puedo escribir más que dos líneas. Tengo [25] mucho que hacer. Todo concluirá dentro de unos días. No me escriba usted más a este lugarón. Pronto tendrá el gusto de abrazarle su hijo.\\\"\"},{\"heading\":false,\"text\":\"\\\"PEPE.\\\"\"},{\"heading\":false,\"text\":\"210\"}]},{\"title\":\"Capítulo XXIX\",\"blocks\":[{\"heading\":false,\"text\":\"De Pepe Rey a Rosarito Polentinos\"},{\"heading\":false,\"text\":\"\\\"Dale a Estebanillo la llave de la huerta y encárgale que cuide del perro. El muchacho está vendido a mí en cuerpo y alma. No temas nada. Sentiré mucho que no puedas bajar, como la otra noche. Haz todo lo posible por conseguirlo. [5] Yo estaré allí después de media noche. Te diré lo que he resuelto, y lo que debes hacer. Tranquilízate, niña mía, porque he abandonado todo recurso imprudente y brutal. Ya te contaré. Esto es largo y debe ser hablado. Me parece que veo tu susto y congoja al considerarme tan [10] cerca de ti. Pero hace ocho días que no te he visto. He jurado que esta ausencia de ti concluirá pronto, y concluirá. El corazón me dice que te veré. Maldito sea yo si no te veo.\\\"\"}]},{\"title\":\"Capítulo XXX\",\"blocks\":[{\"heading\":false,\"text\":\"El ojeo\"},{\"heading\":false,\"text\":\"Una mujer y un hombre penetraron después de las diez [15] en la posada de la viuda de Cuzco, y salieron de ella dadas las once y media.\"},{\"heading\":false,\"text\":\"--Ahora, señora doña María--dijo el hombre,--la llevaré a usted a su casa, porque tengo que hacer.\"},{\"heading\":false,\"text\":\"--Aguarde usted, Sr. Ramos, por amor de Dios--repuso [20] ella.--¿Por qué no nos llegamos al Casino a ver si sale? Ya ha oído usted.... Esta tarde estuvo hablando con él Estebanillo, el chico de la huerta.\"},{\"heading\":false,\"text\":\"--¿Pero usted busca a D. José?--preguntó el Centauro de muy mal humor.--¿Qué nos importa? El noviazgo con [25] doña Rosario paró donde debía parar, y ahora no hay más remedio sino que la señora tiene que casarlos. Ésa es mi opinión.\"},{\"heading\":false,\"text\":\"--Usted es un animal--dijo Remedios con enfado. 211\"},{\"heading\":false,\"text\":\"--Señora, yo me voy.\"},{\"heading\":false,\"text\":\"--Pues qué, hombre grosero, ¿me va usted a dejar sola en medio de la calle?\"},{\"heading\":false,\"text\":\"[5] --Si usted no se va pronto a su casa, sí señora.\"},{\"heading\":false,\"text\":\"--Eso es... me deja usted sola, expuesta a ser insultada.... Oiga usted, Sr. Ramos. Don José saldrá ahora del Casino, como de costumbre. Quiero saber si entra en su casa o sigue adelante. Es un capricho, nada más que [10] un capricho.\"},{\"heading\":false,\"text\":\"--Yo lo que sé es que tengo que hacer, y van a dar las doce.\"},{\"heading\":false,\"text\":\"--Silencio--dijo Remedios,--ocultémonos detrás de la esquina.... Un hombre viene por la calle de la Tripería [15] Alta. Es él.\"},{\"heading\":false,\"text\":\"--Don José.... Le conozco en el modo de andar. Se ocultaron y el hombre pasó.\"},{\"heading\":false,\"text\":\"--Sigámosle--dijo María Remedios con zozobra.-- Sigámosle a corta distancia, Ramos.\"},{\"heading\":false,\"text\":\"[20] --Señora....\"},{\"heading\":false,\"text\":\"--Nada más sino hasta ver si entra en su casa.\"},{\"heading\":false,\"text\":\"--Un minutillo nada más, doña Remedios. Después me marcharé.\"},{\"heading\":false,\"text\":\"Anduvieron como treinta pasos, a regular distancia del [25] hombre que observaban. La sobrina del Penitenciario se detuvo al fin, y pronunció estas palabras:\"},{\"heading\":false,\"text\":\"--No entra en su casa.\"},{\"heading\":false,\"text\":\"--Irá a casa del brigadier.\"},{\"heading\":false,\"text\":\"--El brigadier vive hacia arriba, y D. Pepe va hacia [30] abajo, hacia casa de la señora.\"},{\"heading\":false,\"text\":\"--¡De la señora!--exclamó Caballuco andando a prisa. Pero se engañaban; el espiado pasó por delante de la casa de Polentinos, y siguió adelante.\"},{\"heading\":false,\"text\":\"--¿Ve usted cómo no?\"},{\"heading\":false,\"text\":\"--Señor Ramos, sigámosle--dijo Remedios, oprimiendo 212 convulsamente la mano del Centauro.--Tengo una corazonada.\"},{\"heading\":false,\"text\":\"--Pronto hemos de saberlo, porque el pueblo se acaba.\"},{\"heading\":false,\"text\":\"[5] --No vayamos tan de prisa... puede vernos.... Lo que yo pensé, Sr. Ramos; va a entrar por la puerta condenada de la huerta.\"},{\"heading\":false,\"text\":\"--¡Señora, usted se ha vuelto loca!\"},{\"heading\":false,\"text\":\"--Adelante, y lo veremos.\"},{\"heading\":false,\"text\":\"[10] La noche era obscura y no pudieron los observadores precisar dónde había entrado el Sr. de Rey; pero cierto ruido de visagras mohosas que oyeron, y la circunstancia de no encontrar al joven en todo lo largo de la tapia, les convencieron de que se había metido dentro de la huerta. Caballuco [15] miró a su interlocutora con estupor. Parecía lelo.\"},{\"heading\":false,\"text\":\"--¿En qué piensa usted?... ¿Todavía duda?\"},{\"heading\":false,\"text\":\"--¿Qué debo hacer?--preguntó el bravo lleno de confusión.-- ¿Le daremos un susto?... No sé lo que pensará la señora. Dígolo, porque esta noche estuve a verla, y me [20] pareció que la madre y la hija se reconciliaban.\"},{\"heading\":false,\"text\":\"--No sea usted bruto.... ¿Por qué no entra?\"},{\"heading\":false,\"text\":\"--Ahora me acuerdo de que los mozos armados ya no están ahí, porque yo les mandé salir esta noche.\"},{\"heading\":false,\"text\":\"--Y aún duda este marmolejo lo que ha de hacer. Ramos, [25] no sea usted cobarde y entre en la huerta.\"},{\"heading\":false,\"text\":\"--¿Por dónde, si han cerrado la puertecilla?\"},{\"heading\":false,\"text\":\"--Salte usted por encima de la tapia.... ¡Qué pelmazo! Si yo fuera hombre....\"},{\"heading\":false,\"text\":\"--Pues arriba.... Aquí hay unos ladrillos gastados [30] por donde suben los chicos a robar fruta.\"},{\"heading\":false,\"text\":\"--Arriba pronto. Yo voy a llamar a la puerta principal para que despierte la señora, si es que duerme.\"},{\"heading\":false,\"text\":\"El Centauro subió, no sin dificultad. Montó a caballo breve instante sobre el muro, y después desapareció entre la negra espesura de los árboles. María Remedios corrió 213 desalada hacia la calle del Condestable, y cogiendo el aldabón de la puerta principal, llamó... llamó tres veces con toda el alma y la vida.\"}]},{\"title\":\"Capítulo XXXI\",\"blocks\":[{\"heading\":false,\"text\":\"Doña Perfecta\"},{\"heading\":false,\"text\":\"[5] Ved con cuánta tranquilidad se consagra a la escritura la señora doña Perfecta. Penetrad en su cuarto, a pesar de lo avanzado de la hora, y la sorprenderéis en grave tarea, compartido su espíritu entre la meditación y unas largas y concienzudas cartas que traza a ratos con segura pluma y [10] correctos perfiles. Dale de lleno en el rostro y busto y manos la luz del quinqué, cuya pantalla deja en dulce penumbra el resto de la persona y la pieza casi toda. Parece una figura luminosa evocada por la imaginación en medio de las vagas sombras del miedo.\"},{\"heading\":false,\"text\":\"[15] Es extraño que hasta ahora no hayamos hecho una afirmación muy importante, y es que doña Perfecta era hermosa, mejor dicho, era todavía hermosa, conservando en su semblante rasgos de acabada belleza. La vida del campo, la falta absoluta de presunción, el no vestirse, el no acicalarse, el [20] odio a las modas, el desprecio de las vanidades cortesanas eran causa de que su nativa hermosura no brillase o brillase muy poco. También la desmejoraba la intensa amarillez que tenía su rostro, indicando una fuerte constitución biliosa.\"},{\"heading\":false,\"text\":\"Negros y rasgados los ojos, fina y delicada la nariz, ancha [25] y despejada la frente, todo observador la consideraba como acabado tipo de la humana figura; pero había en aquellas facciones cierta expresión de dureza y soberbia que era causa de antipatía. Así como otras personas, aun siendo feas, llaman, doña Perfecta despedía. Su mirar, aun acompañado [30] de bondadosas palabras, ponía entre ella y las personas extrañas la infranqueable distancia de un respeto 214 receloso; mas para las de casa, es decir, para sus deudos, parciales y allegados, tenía una singular atracción. Era maestra en dominar, y nadie la igualó en el arte de hablar\"},{\"heading\":false,\"text\":\"Su hechura biliosa, y el comercio excesivo con personas y cosas devotas, que exaltaban sin fruto ni objeto su imaginación, la habían envejecido prematuramente, y siendo joven no lo parecía. Podría decirse de ella que con sus hábitos y [10] su sistema de vida se había labrado una corteza, un forro pétreo, insensible, encerrándose dentro como el caracol en su casa portátil. Doña Perfecta salía pocas veces de su concha.\"},{\"heading\":false,\"text\":\"Sus costumbres intachables, y aquella bondad pública que [15] hemos observado en ella desde el momento de su aparición en nuestro relato, eran causa de su gran prestigio en Orbajosa. Sostenía además relaciones con excelentes damas de Madrid, y por este medio consiguió la destitución de su sobrino. Ahora, en el momento presente de nuestra historia, [20] la hallamos sentada junto al pupitre, que es el confidente único de sus planes y el depositario de sus cuentas numéricas con los aldeanos, y de sus cuentas morales con Dios y la sociedad. Allí escribió las cartas que trimestralmente recibía su hermano; allí redactaba las esquelitas [25] para incitar al juez y al escribano a que embrollaran los pleitos de Pepe Rey; allí armó el lazo en que éste perdiera la confianza del Gobierno; allí conferenciaba largamente con D. Inocencio. Para conocer el escenario de otras acciones cuyos efectos hemos visto, sería preciso seguirla al [30] palacio episcopal y a varias casas de familias amigas.\"},{\"heading\":false,\"text\":\"No sabemos cómo hubiera sido doña Perfecta amando. Aborreciendo tenía la inflamada vehemencia de un ángel tutelar del odio y de la discordia entre los hombres. Tal es el resultado producido en un carácter duro y sin bondad nativa por la exaltación religiosa, cuando ésta, en vez de nutrirse 215 de la conciencia y de la verdad revelada en principios tan sencillos como hermosos, busca su savia en fórmulas estrechas que sólo obedecen a intereses eclesiásticos. Para que [5] la mojigatería sea inofensiva, es preciso que exista en corazones muy puros. Es verdad que aun en este caso es infecunda para el bien. Pero los corazones que han nacido sin la seráfica limpieza que establece en la tierra un Limbo prematuro, cuidan bien de no inflamarse mucho con lo que ven [10] en los retablos, en los coros, en los locutorios y en las sacristías, si antes no han elevado en su propia conciencia un altar, un pulpito y un confesonario.\"},{\"heading\":false,\"text\":\"La señora, dejando a ratos la escritura, pasaba a la pieza inmediata donde estaba su hija. A Rosarito se le había [15] mandado que durmiera; pero ella, precipitada ya por el despeñadero de la desobediencia, velaba.\"},{\"heading\":false,\"text\":\"--¿Por qué no duermes?--le preguntó su madre.--Yo no pienso acostarme en toda la noche. Ya sabes que Caballuco se ha llevado los hombres que teníamos aquí. Puede [20] suceder cualquier cosa, y yo vigilo.... Si yo no vigilara, ¿qué sería de ti y de mí?...\"},{\"heading\":false,\"text\":\"--¿Qué hora es?--preguntó la muchacha.\"},{\"heading\":false,\"text\":\"--Pronto será media noche.... Tú no tendrás miedo ... pero yo lo tengo.\"},{\"heading\":false,\"text\":\"[25] Rosarito temblaba, y todo indicaba en ella la más negra congoja. Sus ojos se dirigían al cielo como cuando se quiere orar; miraban luego a su madre, expresando un vivo terror.\"},{\"heading\":false,\"text\":\"--¿Pero qué tienes?\"},{\"heading\":false,\"text\":\"[30] --¿Ha dicho usted que era media noche?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--Pues.... ¿Pero es ya media noche?\"},{\"heading\":false,\"text\":\"Rosario quería hablar, sacudía la cabeza, encima de la cual se le había puesto un mundo.\"},{\"heading\":false,\"text\":\"--Tú tienes algo... a ti te pasa algo--dijo la madre 216 clavando en ella los sagaces ojos.\"},{\"heading\":false,\"text\":\"--Sí... quería decirle a usted--balbució la muchacha,-- quería decir... Nada, nada, me dormiré.\"},{\"heading\":false,\"text\":\"[5] --Rosario, Rosario. Tu madre lee en tu corazón como en un libro--exclamó doña Perfecta con severidad.--Tú estás agitada. Ya te he dicho que estoy dispuesta a perdonarte si te arrepientes; si eres niña buena y formal...\"},{\"heading\":false,\"text\":\"--Pues qué, ¿no soy buena yo? ¡Ay, mamá, mamá mía, [10] yo me muero!\"},{\"heading\":false,\"text\":\"Rosario porrumpió en llanto congojoso y dolorido.\"},{\"heading\":false,\"text\":\"--¿A qué vienen esos lloros?--dijo su madre abrazándola.-- Si son lágrimas del arrepentimiento, benditas sean.\"},{\"heading\":false,\"text\":\"--Yo no me arrepiento, yo no puedo arrepentirme--gritó [15] la joven con arrebato de desesperación que la puso sublime.\"},{\"heading\":false,\"text\":\"Irguió la cabeza, y en su semblante se pintó súbita, inspirada energía. Los cabellos le caían sobre la espalda. No se ha visto imagen más hermosa de un ángel dispuesto a rebelarse.\"},{\"heading\":false,\"text\":\"[20] --¿Pero te vuelves loca o qué es esto?--dijo doña Perfecta, poniéndole ambas manos sobre los hombros.\"},{\"heading\":false,\"text\":\"--¡Me voy, me voy!--dijo la joven, expresándose con la exaltación del delirio.\"},{\"heading\":false,\"text\":\"Y se lanzó fuera del lecho.\"},{\"heading\":false,\"text\":\"[25] --Rosario, Rosario... Hija mía... ¡Por Dios! ¿Qué es esto?\"},{\"heading\":false,\"text\":\"--¡Ay! mamá, señora--exclamó la joven, abrazándose a su madre.--Áteme usted.\"},{\"heading\":false,\"text\":\"--En verdad, lo merecías... ¿Qué locura es esta?\"},{\"heading\":false,\"text\":\"[30] --Áteme usted... Yo me marcho, me marcho con él.\"},{\"heading\":false,\"text\":\"Doña Perfecta sintió borbotones de fuego que subían de su corazón a sus labios. Se contuvo, y sólo con sus ojos negros, más negros que la noche, contestó a su hija.\"},{\"heading\":false,\"text\":\"--¡Mamá, mamá mía, yo aborrezco todo lo que no sea él!--exclamó Rosario.--Óigame usted en confesión, porque 217 quiero confesarlo a todos, y a usted la primera.\"},{\"heading\":false,\"text\":\"--Me vas a matar, me estás matando.\"},{\"heading\":false,\"text\":\"--Yo quiero confesarlo, para que usted me perdone... [5] Este peso, este peso que tengo encima no me deja vivir...\"},{\"heading\":false,\"text\":\"--¡El peso de un pecado!... Añádele encima la maldición de Dios, y prueba a andar con ese fardo, desgraciada ... Sólo yo puedo quitártelo.\"},{\"heading\":false,\"text\":\"--No, usted no, usted no--gritó Rosario con desesperación.-- [10] Pero óigame usted, quiero confesarlo todo, todo ... Después arrójeme usted de esta casa, donde he nacido.\"},{\"heading\":false,\"text\":\"--¡Arrojarte yo!...\"},{\"heading\":false,\"text\":\"--Pues me marcharé.\"},{\"heading\":false,\"text\":\"[15] --Menos. Yo te enseñaré los deberes de hija que has olvidado.\"},{\"heading\":false,\"text\":\"--Pues huiré; él me llevará consigo.\"},{\"heading\":false,\"text\":\"--¿Te lo ha dicho, te lo ha aconsejado, te lo ha mandado? --preguntó la madre, lanzando estas palabras como rayos [20] sobre su hija.\"},{\"heading\":false,\"text\":\"--Me lo aconseja... Hemos concertado casarnos. Es preciso, mamá, mamá mía querida. Yo la amaré a usted ... Conozco que debo amarla... Me condenaré si no la amo.\"},{\"heading\":false,\"text\":\"[25] Se retorcía los brazos, y cayendo de rodillas, besó los pies a su madre.\"},{\"heading\":false,\"text\":\"--¡Rosario, Rosario!--exclamó doña Perfecta con terrible acento.--Levántate.\"},{\"heading\":false,\"text\":\"Hubo una pequeña pausa.\"},{\"heading\":false,\"text\":\"[30] --¿Ese hombre, te ha escrito?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Le has vuelto a ver después de aquella noche?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¡Y tú!...\"},{\"heading\":false,\"text\":\"--Yo también... ¡Oh! señora. ¿Por qué me mira 218 usted así? Usted no es mi madre.\"},{\"heading\":false,\"text\":\"--Ojalá no. Gózate en el daño que me haces. Me matas, me matas sin remedio--gritó la señora con indecible [5] agitación.--Dices que ese hombre...\"},{\"heading\":false,\"text\":\"--Es mi esposo... Yo seré suya, protegida por la ley ... Usted no es mujer... ¿Por qué me mira usted de ese modo que me hace temblar? Madre, madre mía, no me condene usted.\"},{\"heading\":false,\"text\":\"[10] --Ya tú te has condenado; basta. Obedéceme y te perdonaré ... Responde: ¿cuándo recibiste cartas de ese hombre?\"},{\"heading\":false,\"text\":\"--Hoy.\"},{\"heading\":false,\"text\":\"--¡Qué traición! ¡Qué infamia!--exclamó la madre, [15] antes bien rugiendo que hablando.--¿Esperabais veros?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Cuándo?\"},{\"heading\":false,\"text\":\"--Esta noche.\"},{\"heading\":false,\"text\":\"--¿Dónde?\"},{\"heading\":false,\"text\":\"[20] --Aquí, aquí. Todo lo confieso, todo. Sé que es un delito... Soy una infame; pero usted, que es mi madre, me sacará de este infierno. Consienta usted... Dígame usted una palabra, una sola.\"},{\"heading\":false,\"text\":\"--¡Ese hombre aquí, en mi casa!--gritó doña Perfecta, [25] dando algunos pasos que parecían saltos hacia el centro de la habitación.\"},{\"heading\":false,\"text\":\"Rosario la siguió de rodillas. En el mismo instante oyéronse tres golpes, tres estampidos, tres cañonazos. Era el corazón de María Remedios que tocaba a la puerta, agitando [30] la aldaba. La casa se estremecía con temblor pavoroso. Madre e hija se quedaron como estatuas.\"},{\"heading\":false,\"text\":\"Bajó a abrir un criado, y poco después en la habitación de doña Perfecta entró María Remedios, que no era mujer, sino un basilisco envuelto en un mantón. Su rostro, encendido 219 por la ansiedad, despedía fuego.\"},{\"heading\":false,\"text\":\"--- Ahí está, ahí está--dijo al entrar.--Se ha metido en la huerta por la puertecilla condenada...\"},{\"heading\":false,\"text\":\"[5] Tomaba aliento a cada sílaba.\"},{\"heading\":false,\"text\":\"--Ya entiendo--repitió doña Perfecta con una especie de bramido.\"},{\"heading\":false,\"text\":\"Rosario cayó exánime al suelo y perdió el conocimiento.\"},{\"heading\":false,\"text\":\"--Bajemos--dijo doña Perfecta sin hacer caso del desmayo [10] de su hija.\"},{\"heading\":false,\"text\":\"Las dos mujeres se deslizaron por la escalera como dos culebras. Las criadas y el criado estaban en la galería sin saber qué hacer. Doña Perfecta pasó por el comedor a la huerta, seguida de María Remedios.\"},{\"heading\":false,\"text\":\"[15] --Afortunadamente tenemos ahí a Ca... Ca... Caballuco --dijo la sobrina del canónigo.\"},{\"heading\":false,\"text\":\"--¿Dónde?\"},{\"heading\":false,\"text\":\"--En la huerta también... Sal... sal... saltó la tapia.\"},{\"heading\":false,\"text\":\"[20] Doña Perfecta exploró la obscuridad con sus ojos llenos de ira. El rencor les daba la singular videncia de la raza felina.\"},{\"heading\":false,\"text\":\"--Allí veo un bulto--dijo.--Va hacia las adelfas.\"},{\"heading\":false,\"text\":\"--Es él--gritó Remedios.--Pero allá aparece Ramos... [25] ¡Ramos!\"},{\"heading\":false,\"text\":\"Distinguieron perfectamente la colosal figura del Centauro.\"},{\"heading\":false,\"text\":\"--¡Hacia las adelfas!... ¡Ramos, hacia las adelfas!...\"},{\"heading\":false,\"text\":\"Doña Perfecta adelantó algunos pasos. Su voz ronca, que vibraba con acento terrible, disparó estas palabras:\"},{\"heading\":false,\"text\":\"[30] --Cristóbal, Cristóbal... ¡mátale!\"},{\"heading\":false,\"text\":\"Oyóse un tiro. Después otro.\"},{\"heading\":false,\"text\":\"220\"}]},{\"title\":\"Capítulo XXXII\",\"blocks\":[{\"heading\":false,\"text\":\"FINAL\"},{\"heading\":false,\"text\":\"De D. Cayetano Polentinos a un su amigo de Madrid\"},{\"heading\":false,\"text\":\"_Orbajosa 21 de Abril_.\"},{\"heading\":false,\"text\":\"\\\"Querido amigo: Envíeme usted sin tardanza la edición de 1562 que dice ha encontrado entre los libros de la testamentaría de Corchuelo. Pago ese ejemplar a cualquier precio. Hace tiempo que lo busco inútilmente, y me tendré [5] por mortal virtuosísimo poseyéndolo. Ha de hallar usted en el colophón un casco con emblema sobre la palabra _Tractado_, y la X de la fecha MDLXII ha de tener el rabillo torcido. Si en efecto concuerdan estas señas con el ejemplar, póngame usted un parte telegráfico, porque estoy muy [10] inquieto... aunque ahora me acuerdo de que el telégrafo, con motivo de estas importunas y fastidiosas guerras, no funciona. A correo vuelto espero la contestación.\\\"\"},{\"heading\":false,\"text\":\"\\\"Pronto, amigo mío, pasaré a Madrid con objeto de imprimir este tan esperado trabajo de los _Linajes de Orbajosa_. [15] Agradezco a usted su benevolencia, mi querido amigo; pero no puedo admitirla en lo que tiene de lisonja. No merece mi trabajo, en verdad, los pomposos calificativos con que usted lo encarece; es obra de paciencia y estudio, monumento tosco, pero sólido y grande, que elevo a las [20] grandezas de mi amada patria. Pobre y feo en su hechura, tiene de noble la idea que lo ha engendrado, la cual no es otra que convertir los ojos de esta generación descreída y soberbia hacia los maravillosos hechos y acrisoladas virtudes de nuestros antepasados. ¡Ojalá que la juventud estudiosa de nuestro país diera este paso a que con todas mis fuerzas la incito! ¡Ojala fueran puestos en perpetuo olvido los abominables estudios y hábitos intelectuales introducidos por el desenfreno filosófico y las erradas doctrinas! ¡Ojalá se emplearan exclusivamente nuestros sabios en la contemplación 221 de aquellas gloriosas edades, para que, penetrados de la substancia y benéfica savia de ellas los modernos tiempos, desapareciera este loco afán de mudanzas y esta [5] ridicula manía de apropiarnos ideas extrañas, que pugnan] con nuestro primoroso organismo nacional. Temo mucho que mis deseos no se vean cumplidos, y que la contemplación de las perfecciones pasadas quede circunscrita al estrecho círculo en que hoy se halla, entre el torbellino de la [10] demente juventud que corre detrás de vanas utopias y bárbaras novedades. ¿Cómo ha de ser, amigo mío? Creo que dentro de algún tiempo ha de estar nuestra pobre España tan desfigurada, que no se conocerá ella misma ni aun mirándose en el clarísimo espejo de su limpia historia.\\\"\"},{\"heading\":false,\"text\":\"[15] \\\"No quiero levantar mano de esta carta sin participar a usted un suceso desagradable: la desastrosa muerte de un estimable joven, muy conocido en Madrid, el ingeniero de caminos D. José de Rey, sobrino de mi cuñada. Acaeció este triste suceso anoche en la huerta de nuestra casa, y aún [20] no he formado juicio exacto sobre las causas que pudieron arrastrar al desgraciado Rey a esta horrible y criminal determinación. Según me ha referido Perfecta esta mañana cuando volví de Mundogrande, Pepe Rey, a eso de las doce de la noche, penetró en la huerta de esta casa y se [25] pegó un tiro en la sien derecha, quedando muerto en el acto. Figúrese usted la consternación y alarma que se producirían en esta pacífica y honrada mansión. La pobre Perfecta se impresionó tan vivamente, que nos hemos asustado; pero ya está mejor, y esta tarde hemos logrado que tome un sopicaldo. [30] Empleamos todos los medios de consolarla, y como es buena cristiana, sabe soportar con edificante resignación las mayores desgracias.\\\"\"},{\"heading\":false,\"text\":\"\\\"Acá, para entre los dos, amigo mío, diré a usted que en el terrible atentado del joven Rey contra su propia existencía, debió influir grandemente una pasión contrariada, tal 222 vez los remordimientos por su conducta y el estado de hipocondría amarguísima en que se encontraba su espíritu. Yo le apreciaba mucho; creo que no carecía de excelentes [5] cualidades; pero aquí estaba tan mal estimado, que ni una sola vez oí hablar bien de él. Según dicen, hacía alarde de ideas y opiniones extravagantísimas; burlábase de la religión; entraba en la iglesia fumando y con el sombrero puesto; no respetaba nada, y para él no había en el mundo [10] pudor, ni virtudes, ni alma, ni ideal, ni fe, sino tan sólo teodolitos, escuadras, reglas, máquinas, niveles, picos y azadas. ¿Qué tal? En honor de la verdad, debo decir que en sus conversaciones conmigo, siempre disimuló tales ideas, sin duda por miedo a ser destrozado por la metralla de mis [15] argumentos; pero de público se refieren de él mil cuentos de herejías y estupendos desafueros.\\\"\"},{\"heading\":false,\"text\":\"\\\"No puedo seguir, querido, porque en este momento siento tiros de fusilería. Como no me entusiasman los combates, ni soy guerrero, el pulso me flaquea un tantico. [20] Ya le impondrá a usted de ciertos pormenores de esta guerra su afectísimo, etc., etc.\\\"\"},{\"heading\":false,\"text\":\"_22 de Abril._\"},{\"heading\":false,\"text\":\"\\\"Mi inolvidable amigo: Hoy hemos tenido una sangrienta refriega en las inmediaciones de Orbajosa. La gran partida levantada en Villahorrenda ha sido atacada por las [25] tropas con gran coraje. Ha habido muchas bajas por una y otra parte. Después se dispersaron los bravos guerrilleros; pero van muy envalentonados, y quizá oiga usted maravillas. Mándalos, a pesar de estar herido en un brazo, no se sabe cómo ni cuándo, Cristóbal Caballuco, hijo de [30] aquel egregio Caballuco que usted conoció en la pasada guerra. Es el caudillo actual de grandes condiciones para el mando, y además honrado y sencillo. Como al fin hemos de presenciar un arreglito amistoso, presumo que Caballuco 223 será general del ejército español, con lo cual uno y otro ganarán mucho.\\\"\"},{\"heading\":false,\"text\":\"\\\"Yo deploro esta guerra, que va tomando proporciones [5] alarmantes; pero reconozco que nuestros bravos campesinos no son responsables de ella, pues han sido provocados al cruento batallar por la audacia del Gobierno; por la desmoralización de sus sacrilegos delegados; por la saña sistemática con que los representantes del Estado atacan lo [10] más venerando que existe en la conciencia de los pueblos, la fe religiosa y el acrisolado españolismo, que por fortuna se conservan en lugares no infestados aún de la asoladora pestilencia. Cuando a un pueblo se le quiere quitar su alma para infundirle otra; cuando se le quiere descastar, [15] digámoslo así, mudando sus sentimientos, sus costumbres, sus ideas, es natural que ese pueblo se defienda, como el que en mitad de solitario camino se ve asaltado de infames ladrones. Lleven a las esferas del Gobierno el espíritu y la pura salutífera substancia de mi obra de los _Linajes_ [20] (perdóneme usted la inmodestia), y entonces no habrá guerras.\\\"\"},{\"heading\":false,\"text\":\"\\\"Hoy hemos tenido aquí una cuestión muy desagradable. El clero, amigo mío, se ha negado a enterrar en sepultura sagrada al infeliz Rey. Yo he intervenido en este asunto, [25] impetrando del señor obispo que levantara anatema de tanto peso; pero nada se ha podido conseguir. Por fin hemos empaquetado el cuerpo del joven en un hoyo que se hizo en el campo de Mundogrande, donde mis pacienzudas exploraciones han descubierto la riqueza arqueológica que usted [30] conoce. He pasado un rato muy triste, y aún me dura la penosísima impresión que recibí. D. Juan Tafetán y yo somos los únicos que acompañaron el fúnebre cortejo. Poco después fueron allá (cosa rara) esas que llaman aquí las Troyas, y rezaron largo rato sobre la rústica tumba del matemático. Aunque esto parecía una oficiosidad ridícula, me 224 conmovió.\\\"\"},{\"heading\":false,\"text\":\"\\\"Respecto de la muerte de Rey, corre por el pueblo el rumor de que fué asesinado. No se sabe por quién. Aseguran [5] que él lo declaró así, pues vivió como hora y media. Guardó secreto, según dicen, respecto a quién fué su matador. Repito esta versión sin desmentirla ni apoyarla. Perfecta no quiere que se hable de este asunto, y se aflige mucho siempre que lo tomo en boca.\\\"\"},{\"heading\":false,\"text\":\"[10] \\\"La pobrecita, apenas ocurrida una desgracia, experimenta otra que a todos nos contrista mucho. Amigo mío, ya ha hecho una nueva víctima la funestísima y rancia enfermedad connaturalizada en nuestra familia. La pobre Rosario, que iba saliendo adelante, gracias a nuestros cuidados, [15] está ya perdida de la cabeza. Sus palabras incoherentes, su atroz delirio, su palidez mortal, recuérdanme a mi madre y hermana. Este caso es el más grave que he presenciado en mi familia, pues no se trata de manías, sino de verdadera locura. Es triste, tristísimo, que entre tantos yo [20] sea el único que ha logrado escapar conservando mi juicio sano y entero, y totalmente libre de ese funesto mal.\\\"\"},{\"heading\":false,\"text\":\"\\\"No he podido dar sus expresiones de usted a D. Inocencio, porque el pobrecito se nos ha puesto malo de repente, y no recibe a nadie ni permite que le vean sus más íntimos [25] amigos. Pero estoy seguro de que le devuelve a usted sus recuerdos, y no dude que pondrá mano al instante en la traducción de varios epigramas latinos que usted le recomienda.... Suenan tiros otra vez. Dicen que tendremos gresca esta tarde. La tropa acaba de salir.\\\"\"},{\"heading\":false,\"text\":\"_Barcelona 1° de Junio._\"},{\"heading\":false,\"text\":\"[30] \\\"Acabo de llegar aquí, después de dejar a mi sobrina Rosario en San Baudilio de Llobregat. El director del establecimiento me ha asegurado que es un caso incurable.\\\"\"},{\"heading\":false,\"text\":\"\\\"Tendrá, sí, una asistencia esmeradísima en aquel alegre y 225 grandioso manicomio. Mi querido amigo, si alguna vez caigo yo también, llévenme a San Baudilio. Espero encontrar a mi vuelta pruebas de los _Linajes_. Pienso añadir seis [5] pliegos, porque sería gran falta no publicar las razones que tengo para sostener que Mateo Díaz Coronel, autor del _Métrico Encomio_, desciende por la línea materna de los Guevaras y no de los Burguillos, como ha sostenido erradamente el autor de la _Floresta amena_.\\\"\"},{\"heading\":false,\"text\":\"[10] \\\"Escribo esta carta principalmente para hacerle a usted una advertencia. He oído aquí a varias personas hablar de la muerte de Pepe Rey, refiriéndola tal como sucedió efectivamente. Yo revelé a usted este secreto cuando nos vimos en Madrid, contándole lo que supe algún tiempo [15] después del suceso. Extraño mucho que no habiéndolo dicho yo a nadie más que a usted, lo cuenten aquí con todos sus pelos y señales, explicando cómo entró en la huerta, cómo descargó su revólver sobre Caballuco cuando vió que éste le acometía con la navaja, cómo Ramos le disparó después [20] con tanto acierto que le dejó en el sitio.... En fin, mi querido amigo, por si inadvertidamente ha hablado de esto con alguien, le recuerdo que es un secreto de familia, y con esto basta para una persona tan prudente y discreta como usted.\\\"\"},{\"heading\":false,\"text\":\"[25] \\\"Albricias, albricias. En un periodiquillo he leído que Caballuco ha derrotado al brigadier Batalla.\\\"\"},{\"heading\":false,\"text\":\"_Orbajosa 12 de Diciembre._\"},{\"heading\":false,\"text\":\"\\\"Una sensible noticia tengo que dar a usted. Ya no tenemos Penitenciario, no precisamente porque haya pasado a mejor vida, sino porque el pobrecito está desde el mes [30] de Abril tan acongojado, tan melancólico, tan taciturno, que no se le conoce. Ya no hay en él ni siquiera dejos de aquel humor ático, de aquella jovialidad correcta y clásica que le hacía tan amable. Huye de la gente, se encierra en su 226 casa, no recibe a nadie, apenas toma alimento, y ha roto toda clase de relaciones con el mundo. Si le viera usted no le conocería, porque se ha quedado en los puros huesos. [5] Lo más particular es que ha reñido con su sobrina y vive solo, enteramente solo en una casucha del arrabal de Baidejos. Ahora dicen que renuncia su silla en el coro de la catedral y se marcha a Roma. ¡Ay! Orbajosa pierde mucho, perdiendo a su gran latino. Me parece que pasarán años [10] tras años y no tendremos otro. Nuestra gloriosa España se acaba, se aniquila, se muere.\\\"\"},{\"heading\":false,\"text\":\"_Orbajosa 23 de Diciembre._\"},{\"heading\":false,\"text\":\"\\\"El joven que recomendé a usted en carta llevada por él mismo, es sobrino de nuestro querido Penitenciario, abogado con puntas de escritor. Esmeradamente educado por su [15] tío, tiene ideas juiciosas. ¡Cuán sensible sería que se corrompiera en ese lodazal de filosofismo e incredulidad! Es honrado, trabajador y buen católico, por lo cual creo que hará carrera en un bufete como el de usted.... Quizás le llevará una ambicioncilla (pues también la tiene) a las lides [20] políticas, y creo que no sería mala ganancia para la causa del orden y la tradición, hoy que la juventud está pervertida y acaparada por los _de la cáscara amarga_. Acompáñale su madre, una mujer ordinaria y sin barniz social, pero que tiene un corazón excelente y acendrada piedad. El amor [25] materno toma en ella la forma algo abigarrada de la ambición mundana, y dice que su hijo ha de ser Ministro. Bien puede serlo.\\\"\"},{\"heading\":false,\"text\":\"\\\"Perfecta me da expresiones para usted. No sé a punto fijo qué tiene; pero ello es que nos inspira cuidado. Ha [30] perdido el apetito de una manera alarmante, y o yo no entiendo de males, o allí hay un principio de ictericia. Esta casa está muy triste desde que falta Rosario, que la alegraba con su sonrisa y su bondad angelical. Ahora parece que 227 hay una nube negra encima de nosotros. La pobre Perfecta habla frecuentemente de esta nube, que cada vez se pone más negra, mientras ella se vuelve cada día más [5] amarilla. La pobre madre halla consuelo a su dolor en la religión y en los ejercicios del culto, que practica cada vez con más ejemplaridad y edificación. Pasa casi todo el día en la iglesia, y gasta su gran fortuna en espléndidas funciones, en novenas y manifiestos brillantísimos. Gracias a ella, el culto [10] ha recobrado en Orbajosa su esplendor de otros días. Esto no deja de ser un consuelo en medio de la decadencia y acabamiento de nuestra nacionalidad....\\\"\"},{\"heading\":false,\"text\":\"\\\"Mañana irán las pruebas.... Añadiré otros dos pliegos, porque he descubierto un nuevo orbajosense ilustre. [15] Bernardo Amador de Soto, que fué espolique del duque de Osuna, le sirvió durante la época del vireinato de Nápoles, y aun hay indicios de que no hizo nada, absolutamente nada, en el complot contra Venecia.\\\"\"}]},{\"title\":\"Capítulo XXXIII\",\"blocks\":[{\"heading\":false,\"text\":\"Esto se acabó. Es cuanto por ahora podemos decir de [20] las personas que parecen buenas y no lo son.\"}]}]', 'es', 'https://www.gutenberg.org/ebooks/15725', '{}');
INSERT INTO libros (id, titulo, autor, genero, cover, secciones, idioma, fuente, introducciones) VALUES (49660, 'La Alhambra: leyendas árabes', 'Manuel Fernández y González', 'historia', 'https://www.gutenberg.org/cache/epub/49660/pg49660.cover.medium.jpg', '[{\"title\":\"El rey nazar. — capítulo I: La colina roja.\",\"blocks\":[{\"heading\":false,\"text\":\"Por los tiempos en que acontecian los sucesos que vamos á referir, esto es: por los años de 1240 de la era cristiana, y 637 de la Hegira[1], el monte en que se levanta la Alhambra, tenia un aspecto enteramente distinto del que hoy tiene.\"},{\"heading\":false,\"text\":\"No se veian las esbeltas torres orladas de puntiagudas almenas, con sus estrechas saeteras y sus bellos ajimeces calados; ni los robustos muros que enlazan estas torres; ni las cúpulas destellando bajo los rayos del sol los cambiantes de sus tejas de colores; ni la torre de la Vela con su campana pendiente de un arco, ni el palacio del _Emperador_, ni el bellísimo _Mirador de la Sultana_, ni mucho menos la modesta torre de la iglesia de Santa María: ni siguiendo la ladera del monte de la _Silla del moro_, el verde y florido Generalife con sus galerías aéreas, y su altísimo ciprés de la _Sultana_, ni más allá, sobre el _Cerro del sol_, el famoso y resplandeciente palacio de los _Alijares_.\"},{\"heading\":false,\"text\":\"Nada de esto existia aun: solo se veía una colina áspera, pedregosa, de color rogizo, cubierta de retamas y espinos; en el estremo occidental, de esta colina se alzaba únicamente una vieja torre, especie de atalaya de origen y antigüedad dudosos; pero que conservaba algunos vestigios de haber andado en su construccion los fenicios; y en la parte media de la colina, en la direccion de Este á Sur, las ruinas de un templo romano consagrado á Diana.\"},{\"heading\":false,\"text\":\"Esta colina se llamaba la Colina Roja.\"},{\"heading\":false,\"text\":\"A escepcion de las ruinas del templo y de la atalaya, ninguna otra habitacion humana se veía en ella, y en cuanto á los montes que mas adelante se llamaron la Silla del moro y el Cerro del sol, estaban completamente abandonados á los lagartos y á los grillos.\"},{\"heading\":false,\"text\":\"En las ruinas del templo no habitaba nadie, como no fuese momentáneamente algun bandido ó cazador furtivo, ni en la atalaya vivian mas que algunos soldados moros, que desde aquella altura observaban la Vega y las fronteras, para avisar el peligro en el caso de que los cristianos fronterizos hiciesen alguna entrada.\"},{\"heading\":false,\"text\":\"No era, sin embargo, esta la única torre fuerte que existía en Granada: en la colina que entonces se llamaba de Albunest, y hoy de los Mártires, se alzaba el castillo de las Torres Bermejas, dentro de cuya jurisdiccion murada, se encerraba una pequeña poblacion llamada Garnat-Al-Jaud, ó Granada la de los judíos, y sobre la colina en que se estendia el Albaicin, teniendo á sus faldas el Zenet y el barrio del Hajeriz[2] se alzaban los fuertes muros y las torres chatas, cuadradas las unas, redondas las otras, de la alcaza Cadima, y mas allá el antiguo palacio que antes de la construccion de la Alhambra habitaban los emires árabes, y los primeros reyezuelos moros de Granada, construido por Aben-Habuz, y llamado por él mismo _Casa del Gallo de viento_.\"},{\"heading\":false,\"text\":\"Pero á pesar de la aridez y soledad de la Colina Roja, el panorama que desde ella se descubria era encantador; procuraremos describirle, si es que pueden describirse aquel cielo radiante, que parece transparentar en su límpido azul la luz de los ojos de Dios: el verdor inmarchito de aquella tierra de bendicion: la nítida blancura del manto de nieve de las montañas y su puro matiz de cobalto, procuraremos hacer sentir á nuestros lectores la belleza sin igual de aquel jardin de delicias, que sirve de alfombra mágica al trono de la hermosa ciudad á quien llamaban los moros, la _cándida y la clara_.\"},{\"heading\":false,\"text\":\"Levántase al Oriente una montaña altísima, siempre cubierta de nieve, á la que sirven de base, grupos de montañas azules, escalones maravillosos de aquella maravillosa pirámide construida por la palabra de Dios: esta montaña es Sierra Nevada: nace en ella el Genil, que torciéndose entre valles odoríferos, bajo la sombra de los álamos, orlado de flores, arrastra su clara corriente sobre arenas de plata, y desemboca en la estendida Vega, atravesándola en toda su estension hasta los montes de Loja, aumentando su corriente por el raudal del humilde Darro, que se une á él á los pies de Granada, habiendo atravesado antes, desde su nacimiento, pintorescos valles, y dividido la Colina Roja del barrio del Hajeriz, con sus ruidosas linfas, que ruedan sobre arenas de oro.\"},{\"heading\":false,\"text\":\"Y esta magnífica llanura que se llama la Vega, que nace á los pies de Sierra Nevada y se estiende hasta la volcánica Sierra Elvira, deja ver desde la Colina Roja, bajo el diáfano horizonte que recortan las lejanas sierras al Poniente, sus mil aldeas blancas como nidos de tórtolas, con los humildes campanarios de sus iglesias, con los leves penachos de humo de sus hogares, entre bordaduras de colores, que tales parecen las alamedas con su verde esmeralda, los olivares con su verde oscuro, los riachuelos y las acequias que brillan entre los sembrados, cuya diversidad de matices hace parecer á la Vega, valiéndonos de una frase muy usada por nuestros poetas, un chal de colores bordado de plata, y luego levantándose en anfiteatro sobre aquella Vega, á la derecha y á la izquierda de la Colina Roja, dos montes cubiertos por la poblacion mora; y en esta poblacion brotando entre las casas, como ramilletes en su búcaro, grupos de cipreses, de naranjos, de limoneros; y entre estas casas con sus pardos tejados, y entre estos ramilletes de verdura con sus vivos esmaltes, torreones altivos y robustos muros, campanarios y miradores: y sirviendo de dosel á todo esto el Cerro de Santa Elena, y el del Aceituno, y la Silla del moro y el Cerro del Sol; y sobre este, al otro lado de un Occéano de aire y de luz la Sierra Nevada, que viene á ser el diamante del magnífico anillo de montañas que rodean á Granada y á la Vega.\"},{\"heading\":false,\"text\":\"Quien no ha visto el cielo de Granada no puede comprender hasta qué grado de luz y de esplendor alcanza el dia: quien no ha visto sus árboles, no puede saber á cuanta fuerza de esmalte alcanza la vegetacion, quien no ha dormido entre flores, al lado de una fuente, en los cármenes[3] del Darro, no puede formar una idea de hasta donde puede ser armonioso, ese himno que consagra la creacion al Creador, en el magnífico acorde de los pájaros que cantan, las frondas que zumban, los arroyos que murmuran, los insectos que vuelan, el aura que suspira en largas é indolentes ráfagas. Andalucía es el jardin del mundo, y Granada es el edem de Andalucía.\"},{\"heading\":false,\"text\":\"Pues bien: esas sierras blancas ó azules, esa vega matizada, esas aldeas que salpican esa vega, esos rios que la atraviesan, esas colinas cubiertas de casas, de jardines, de torreones, y el firmamento azul que alumbra con su radiante luz todo este maravilloso conjunto, es el panorama que se veía hace mas de seis siglos desde la Colina Roja, y que se ve hoy, aunque modificado en la parte de poblacion por los cambios que el tiempo efectúa en las obras de los hombres.\"},{\"heading\":false,\"text\":\"Por la situacion de la colina en que ha sido construida, por el panorama que desde ella se descubre, por el cielo que la alumbra, la Alhambra es el alcázar mas bellamente situado del mundo.\"},{\"heading\":false,\"text\":\"En 1240, si bien Granada era ya la perla de los musulmanes españoles, si tenia cuanto bello y maravilloso puede producir la naturaleza, la faltaba el magnífico _acrópolo_ que debia ser la corona de magestad de la _reina de Occidente_.\"},{\"heading\":false,\"text\":\"Este acrópolo debia ser la Alhambra, y lo fué.\"},{\"heading\":false,\"text\":\"Hemos contraido el empeño de relataros la historia de ese alcázar maravilloso: no esa historia árida y severa que solo se ocupa de sangrientas conquistas y horrorosas catástrofes; no la historia de la construccion con su lento desarrollo y la insoportable descripcion del edificio, detalle por detalle, sino la historia romancesca, con todo su palpitante interés: queremos recoger, compilar en un solo libro, los dramas que en el recinto de aquel alcázar se han representado; queremos recoger en una copa todas las lágrimas que en él se han vertido; queremos haceros sentir, aspirar, los estremecimientos, los latidos de los corazones que allí han amado, que allí han odiado, que allí han sufrido; queremos consignar las hazañas y las traiciones que allí han tenido lugar; queremos hacer pasar delante de vuestra vista, como los espectros de una linterna mágica, los reyes, las sultanas, las esclavas del harem, las leyendas de encantamentos, los misterios de cada uno de aquellos retretes, las citas de enamorados en aquellos sombrosos y floridos jardines, al rayo de la luna; queremos levantar delante de vosotros generaciones muertas, y presentároslas llenas de vida, con su generoso valor, sus amores, sus ódios, su civilizacion y su grandeza; queremos, en fin, que sepais cuánto vale el pasado de ese alcázar que se asentaba sobre cuatro montes, y del cual solo queda hoy una pequeña parte mutilada.\"},{\"heading\":false,\"text\":\"Tal es el difícil empeño que hemos contraido: para llevarle á cabo, es necesario que nos anticipemos á la construccion de la Alhambra.\"},{\"heading\":false,\"text\":\"Por eso os hemos llevado al sitio en que fué construida.\"},{\"heading\":false,\"text\":\"Por eso al llevaros á la Colina Roja, os la hemos presentado árida y desierta.\"}]},{\"title\":\"El rey nazar. — capítulo II: La casita del remanso.\",\"blocks\":[{\"heading\":false,\"text\":\"Era el oscurecer de una lánguida tarde de primavera.\"},{\"heading\":false,\"text\":\"Los soldados moros que hasta entonces habian vagado alrededor del viejo torreon de la Colina Roja, habian penetrado en él; se habia cerrado su puerta de hierro, y poco despues una espiral de humo habia aparecido saliendo de una saetera junto á las almenas.\"},{\"heading\":false,\"text\":\"En las ventanas de las casas de la Villa de los judíos y del Albaicin, empezaba á verse acá y allá el reflejo de las lámparas en el interior de las habitaciones.\"},{\"heading\":false,\"text\":\"La luna llena, con su bello color nacarado, asomó sobre la cumbre de la Sierra Nevada, se elevó lentamente é inundó con su blanda luz las distantes montañas, perdidas tras la neblina, la vega cubierta con un velo de vapores, y la ciudad que levantaba como fantasmas sobre las colinas sus torreones y sus alminares.\"},{\"heading\":false,\"text\":\"La Colina Roja estaba desierta; pero un momento despues de la salida de la luna, quien hubiera estado oculto entre las retamas y los jaramagos que cubrian las ruinas del templo de Diana, hubiera visto aparecer por entre una oscura grieta, enteramente cubierta de espinos, una forma humana.\"},{\"heading\":false,\"text\":\"Miró con recelo en torno suyo, y cuando vió que la Colina estaba completamente desierta, adelantó recatadamente, y deslizándose por entre las escabrosidades del terreno, atravesó la cima y bajó á la carrera por la vertiente que iba á concluir en el valle del Darro.\"},{\"heading\":false,\"text\":\"Luego siguiendo la corriente del rio arriba, atravesando con frecuencia su escaso raudal, que serpeaba entre los altos barrancos que se llaman todavía las _Angosturas del Darro_, continuó su marcha por espacio de una hora, y no se detuvo sino en un lugar donde el rio hacia un profundo remanso, apilando su corriente como en un estanque, en una ancha y profunda hondonada del terreno.\"},{\"heading\":false,\"text\":\"El lugar en que el incógnito se habia detenido, era sumamente pintoresco; anchas y tupidas cortinas de yedra cubrian las cortaduras de aquel ensanchamiento circular que tenia la forma de un gigantesco anfiteatro. Las dos estrechas aberturas por donde entraba y salia el rio, estaban unidas como por un pabellon flotante, por cortinages de enredaderas que descendian hasta la corriente: sobre los bordes de las cortaduras, como verdes cabelleras, se levantaban las frondas odoríferas de los árboles frutales; brillaba la luna en la tranquila agua del remanso, y en los blancos muros de una casita que se veia en la márgen opuesta entre álamos y cipreses: delante de esta casa se veia un jardin, el perfume de cuyas flores traia consigo el aura de la noche, y un ruiseñor enamorado cantaba entre la espesura uniendo sus cadenciosos trinos al monótono murmullo del rio.\"},{\"heading\":false,\"text\":\"Al lado opuesto en la estrecha faja de arena pedregosa que dejaba libre el remanso, se veia una negra abertura entre la maleza, que servia sin duda de entrada á una gruta.\"},{\"heading\":false,\"text\":\"El incógnito miró en torno suyo, y despues de contemplar indolentemente cuanto le rodeaba, se sentó sobre una gruesa piedra á la orilla de las aguas.\"},{\"heading\":false,\"text\":\"La luna le iluminaba de lleno con su blanca luz.\"},{\"heading\":false,\"text\":\"Era un mancebo como de veinte años: por su apostura, por la espresion de su semblante y por lo rico de sus vestidos y de sus armas, podia decirse que pertenecia á una poderosa y nobilísima familia mora.\"},{\"heading\":false,\"text\":\"Examinémosle, puesto que la luna nos alumbra, y la soledad y la belleza del sitio nos convidan al reposo.\"},{\"heading\":false,\"text\":\"Era blanco como la espuma de las aguas, y de formas delicadas y hermosas como las de una dama: sus ojos negros brillaban en una mirada indolente, pero fija, poderosa, audaz; ni el mas ligero bozo asomaba en su semblante de niño, á pesar de que su aventajada estatura, y lo robusto y desarrollado de sus miembros representaban á un hombre: un casco de plata con arabescos de oro y esmaltes de colores cubria su cabeza: ceñía su pecho un coselete de Damasco, bajo una túnica corta de brocado, sujeta á la cintura bajo una faja de la India: en esta faja se veian atravesados un largo yatagan y un puñal; vestia calzas de grana, y ceñian sus pies borceguíes de cuero de Marruecos bordados de oro: por último, llevaba pendiente de su costado izquierdo una aljaba con flechas, y se apoyaba en un largo arco de acebo.\"},{\"heading\":false,\"text\":\"Este jóven á la luz de la luna relumbraba: parecia en aquel lugar tan ameno, tan fresco, tan lánguidamente sonoro, un antiguo caballero encantado por una hada celosa.\"},{\"heading\":false,\"text\":\"Sentado sobre la piedra, apoyado el estremo del arco en la arena, afirmada la mano en el arco y reposando la cabeza en el brazo, el mancebo estuvo mirando fijamente la blanca casita que entre los álamos y los cipreses se veia al otro lado del remanso al rayo de la luna.\"},{\"heading\":false,\"text\":\"Ni el mas leve ruido salia de ella; ni en sus galerías ni en sus ajimeces se veia el reflejo de una luz.\"},{\"heading\":false,\"text\":\"O aquella casa estaba inhabitada, ó sus moradores, á pesar que era el principio de la noche, se habian entregado ya al reposo.\"},{\"heading\":false,\"text\":\"Pero de repente, una voz de mujer, mas dulce que la del ruiseñor que cantaba en la espesura, mas grave que el murmurio del rio, mas suspirante que el gemido de las brisas, cantó poco despues de la llegada del mancebo como para demostrar que todos los habitantes de aquella casa no estaban entregados al sueño.\"},{\"heading\":false,\"text\":\"Hé aquí el romance que aquella voz cantó al son de una guzla; romance cuyas palabras llegaron claras, distintas y tentadoras á los oidos del mancebo.\"},{\"heading\":false,\"text\":\"Del encantado palacio--de las Perlas soy el genio, y esperando mis amores--envuelta en su encanto duermo. Guárdanme como la joya--del avaro entre el misterio de tenebrosos conjuros--velada en niebla y silencio. Ven, ¡oh, lumbre de mis ojos,--que me abrasas en tu fuego, y para tí mi hermosura--y mis alcázares tengo! Soy virgen y de mi frente--dicen que mata el destello, en dulce encanto de amores--ó en triste penar de celos. Son mis alcázares reales--la maravilla del tiempo, y en motes de amor tu nombre--está en dorados letreros en cintas de azul y grana--escrito en sus aposentos. Regaladas alkatifas--para tu descanso tengo, y velarán blancas gasas--de tus amores el sueño. ¡Ven, esposo de mi vida!--¡Regalado sol que anhelo! ¡Ven! mis alcázares tienen--para tí sombra y silencio, y en ellos con mis amores--luz de mis ojos te espero.\"},{\"heading\":false,\"text\":\"El jóven escuchó trasportado este romance, sus ojos se animaron gradualmente, y cuando la voz cesó, se levantó de una manera nerviosa, dejó caer el arco, y estendió sus brazos hácia la blanca casita.\"},{\"heading\":false,\"text\":\"--¡Oh! tú quien quiera que seas, esclamó, muger ó hurí, fruto bendito de una muger, ó arcángel del sétimo cielo; héme aquí que es la tercera vez que abandonando á mis guerreros vengo en tu busca: héme aquí ciego sin la luz de tu hermosura, y si no apagas con tu amor la sed de mi corazon, moriré como la triste florecilla á quien faltan los rayos del sol.\"},{\"heading\":false,\"text\":\"Apenas habia pronunciado el jóven estas palabras, cuando revoló, viniendo no sabemos de donde, alrededor de su cabeza un enorme buho. Al sentir el ruido de sus alas el mancebo se estremeció: al verlo recogió el arco que habia dejado caer, armó en él una flecha y la asestó al pájaro nocturno; este se precipitó en un largo vuelo sobre la casita blanca, y penetró en ella por el oscuro arco de un ajimez; la flecha disparada por el mancebo penetró por aquel mismo ajimez en la casita.\"},{\"heading\":false,\"text\":\"Entonces el jóven creyó oir una carcajada leve, que al parecer salia de la casa; carcajada burlona, intencionada, cruel, en que habia algo de desesperado, algo de insensato.\"},{\"heading\":false,\"text\":\"--¡Siempre! esclamó: ¡siempre ese pájaro maldito! ¡en mi torreon de Loja, en las ruinas del templo romano, aquí! ¡y esa carcajada que me hiela la sangre y que me parece una amenaza!... ¡Una amenaza! ¿y por qué?\"},{\"heading\":false,\"text\":\"En aquel momento cayó á los pies del jóven, enviada sin duda de la casita, la misma flecha que habia disparado; en las plumas de la flecha se veia enrollado un pergamino.\"},{\"heading\":false,\"text\":\"Recogió la flecha el jóven, desató el pergamino, le desenvolvió, le leyó á la luz de la luna, y vió que decia:\"},{\"heading\":false,\"text\":\"«Si me amas y vienes por mis amores, encaminate á la gruta que tienes á tus espaldas.»--Bekralbayda[4].\"},{\"heading\":false,\"text\":\"El jóven besó la carta; arrojó otro beso á la casita, puso la flecha en la aljaba, y se dirigió hácia la oscura gruta esclamando:\"},{\"heading\":false,\"text\":\"--¡Oh! ¡bendito sea el buho, por quien ha penetrado mi flecha hasta la doncella de la frente pálida!\"}]},{\"title\":\"El rey nazar. — capítulo III: La dama blanca.\",\"blocks\":[{\"heading\":false,\"text\":\"Pero cuando el mancebo llegó á la entrada de la gruta, se vió precisado á romper con su yatagan, para abrirse paso, las tupidas zarzas que la cubrian.\"},{\"heading\":false,\"text\":\"Despues penetró de una manera resuelta en el oscuro antro.\"},{\"heading\":false,\"text\":\"Por algun tiempo descendió en línea recta por una estrecha y resvaladiza rampa: luego se vió obligado á volver y revolver oscurísimas sinuosidades, por una pendiente mayor y mas resvaladiza, y al fin la inclinacion del terreno se hizo tal, que perdió los pies, resvaló y se sintió descender de una manera violenta.\"},{\"heading\":false,\"text\":\"Entonces se acordó del buho, de la carcajada, de cien supersticiosas consejas musulmanas: se retiró, é invocó á Dios: hubo un momento en que creyó que el terreno le faltaba, que caia despeñado en un abismo, dió un grito de espanto y perdió el conocimiento.\"},{\"heading\":false,\"text\":\"Cuando volvió en sí se encontró en un magnífico lecho de pieles de tigre y respiró una atmósfera impregnada de perfumes: lo primero que vió ante sí fué una alta figura blanca que estaba de pié é inmóvil delante de él á los pies del lecho.\"},{\"heading\":false,\"text\":\"Era una muger.\"},{\"heading\":false,\"text\":\"Pero una muger hermosísima, irresistible á pesar de que habia pasado de su primera juventud.\"},{\"heading\":false,\"text\":\"Sin embargo, y aunque parecia contar mas de treinta años, su semblante blanco, nacarado, pálido, un tanto demacrado, exhalaba de sí tal fuerza de vida, que hacia bendecir á Dios que habia creado una criatura, en la cual parecia haberse estacionado la juventud mas brillante.\"},{\"heading\":false,\"text\":\"Sus negros ojos fijos en el príncipe, con una espresion ardiente y melancólica, brillaba con no sabemos qué fuego dulce, concentrado, bajo la sombra de sus negras y convexas pestañas: su boca entreabierta, por la que parecia salir una alma llena de sufrimiento y de dolores en un continuo suspiro, dejaba ver sus voluptuosos labios contraidos por una triste sonrisa y pálidos como sus megillas: por último, sus largos y brillantes cabellos caian en flotantes rizos sobre sus hombros y sobre sus espaldas, y era alta, esbelta, magestuosa, y vestida únicamente con una larga túnica de lana blanca, sujeta en el cuello, de mangas perdidas y suelta enteramente hasta cubrir los pies, ocultando las formas de aquella singular belleza bajo su ancha plegadura.\"},{\"heading\":false,\"text\":\"Ni un solo adorno, ni una joya, ni una flor se veia sobre esta muger.\"},{\"heading\":false,\"text\":\"En su mano derecha tenia una lámpara de plata.\"},{\"heading\":false,\"text\":\"Jamás habia visto el jóven una figura tan hermosa, tan imponente; de aspecto tan sencillo, á un tiempo.\"},{\"heading\":false,\"text\":\"La habitacion en que se encontraba era tambien severa y sencilla, pero rica; cuatro paredes labradas de arabescos dorados sobre fondo blanco, y una cúpula de estalácticas, blancas tambien, con filetes de oro: la puerta de arco de herradura estaba cubierta por una cortina blanca de seda y oro, y de seda blanca y oro eran tambien los divanes que orlaban las paredes, y la alfombra que cubria el pavimento.\"},{\"heading\":false,\"text\":\"Debemos advertir que en aquellos tiempos entre los moros, el vestir completamente de blanco era una señal de luto, y que se admitia en el luto el oro, como se admite ahora en los negros túmulos de las iglesias y en las lápidas de las tumbas.\"},{\"heading\":false,\"text\":\"Esta estraña muger y esta habitacion, produjeron en el jóven el mismo efecto que produciria en nosotros una persona enteramente vestida de negro, en una habitacion enteramente negra tambien con adornos dorados.\"},{\"heading\":false,\"text\":\"La impresion de todo esto al volver en sí preocupó al jóven; pero lo que mas le preocupó, cuando de la dama enlutada pasó su vista á la habitacion, fué ver sobre sus armas, que estaban en un divan, un buho enorme que dormia sobre una de sus patas, teniendo escondida la otra entre su plumage.\"},{\"heading\":false,\"text\":\"El jóven se incorporó violentamente y fijó una mirada vacilante en la dama enlutada, cuyas negras pupilas estaban fijas en él, destellando en su oscuro foco, una chispa de fuego intenso y opaco.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡hermoso! ¡hermoso como su padre! esclamó aquella muger con una voz tan ardiente que el jóven se estremeció.\"},{\"heading\":false,\"text\":\"--¿Quién eres tú, que has nombrado á mi padre? esclamó.\"},{\"heading\":false,\"text\":\"--¡Yo soy la maga de las humbrías! contestó la enlutada.\"},{\"heading\":false,\"text\":\"--¡La maga de las humbrías! esclamó el jóven.\"},{\"heading\":false,\"text\":\"--Sí, dijo la dama sonriendo tristemente; yo soy la maga de las humbrías.\"},{\"heading\":false,\"text\":\"Hubo un momento de solemne silencio, durante el cual continuaron cruzándose y confundiéndose las miradas de la dama y del jóven, que se sentia arrastrar por un poder desconocido hácia aquella muger.\"},{\"heading\":false,\"text\":\"--No, tu no eres maga, la dijo: tu no eres un espíritu maldito: la amargura con que me has contestado me lo prueban, tu eres una muger que sufres y lloras.\"},{\"heading\":false,\"text\":\"--Las lágrimas han hervido en mi corazon y se han secado, respondió aquella muger.\"},{\"heading\":false,\"text\":\"El jóven se levantó, se acercó á la dama, la tomó una mano que ella no retiró.\"},{\"heading\":false,\"text\":\"--¿Por qué quieres engañarme? la dijo con dulzura; en el momento en que abrí los ojos me aterró esta desolacion; el luto que te cubre, el que reviste estas paredes: creí haber cerrado los ojos á la vida; que el puente de Sirat[5] que todos hemos de pasar, se habia abierto para mí, y que me encontraba en las regiones de la eterna sombra: ¡y luego ese buho!\"},{\"heading\":false,\"text\":\"--Ese buho es mi compañero.\"},{\"heading\":false,\"text\":\"--Ese buho ha revolado tres veces en derredor de mi cabeza cuando me encontraba junto al remanso del rio.\"},{\"heading\":false,\"text\":\"--El desdichado sale de noche, vuela, se pierde entre las espesuras, asusta á los murciélagos y se vuelve á dormir.\"},{\"heading\":false,\"text\":\"--Ese buho se precipitó en la casa blanca que está al otro lado del remanso, entre los cipreses.\"},{\"heading\":false,\"text\":\"--En esa casa le conocen y le aman.\"},{\"heading\":false,\"text\":\"--Tras ese buho entró en esa casa por un ajimez una flecha mia.\"},{\"heading\":false,\"text\":\"--¡Hé aquí la maldad humana! ¡el hombre destruye por el placer de destruir! ¿Qué daño le habia hecho ese pobre pájaro?\"},{\"heading\":false,\"text\":\"--Antes de que te conteste respóndeme á una pregunta: ¿me conoces tú?\"},{\"heading\":false,\"text\":\"--No te he visto hasta ahora y sé tu nombre.\"},{\"heading\":false,\"text\":\"--¿Por tu ciencia de maga?\"},{\"heading\":false,\"text\":\"--Sí, por mi ciencia, dijo la dama repitiendo la estraña sonrisa que le era peculiar.\"},{\"heading\":false,\"text\":\"--¿Y quién soy yo?\"},{\"heading\":false,\"text\":\"--Tu eres el príncipe Sidy Mohammet-Abd\'Allah, hijo y compañero en el mando del poderoso Sultan de Andalucía, Nazar-ebn-Al-Hhamar el magnífico.\"},{\"heading\":false,\"text\":\"Y el acento de la dama, al pronunciar el nombre del Sultan de Granada, era amargo y doloroso.\"},{\"heading\":false,\"text\":\"--Sí, yo soy; pues bien: voy á decirte ahora por qué me horrorizan los buhos.\"},{\"heading\":false,\"text\":\"La dama hizo un leve mohin de impaciencia.\"},{\"heading\":false,\"text\":\"--Dicen nuestros viejos que el dia en que nació mi padre, en la fiesta de las buenas hadas, cuando todos los circunstantes estaban alegres y regocijados, un buho entró en la sala y apagó las luces: aquella noche mi abuela murió á consecuencia del alumbramiento.\"},{\"heading\":false,\"text\":\"--¡Ah!\"},{\"heading\":false,\"text\":\"--Siendo mozo mi padre, salió la primera vez en algara contra cristianos: era de noche: un buho revoló tres veces alrededor de su cabeza, y mi padre fué gravemente herido en el combate.\"},{\"heading\":false,\"text\":\"--¿De modo que tu padre, el poderoso sultan Nazar, dijo con profundo acento la dama; el invencible, el fuerte, acabó por estremecerse al nombre solo de una de esas alimañas?\"},{\"heading\":false,\"text\":\"--Déjame continuar. Conoció mi padre allá en los años de su juventud una princesa africana (esto me lo ha contado muchas veces con las lágrimas en los ojos) que habia ido á Córdoba á buscar en la ciencia de sus sabios la curacion de una grave dolencia.\"},{\"heading\":false,\"text\":\"--¿Y de qué adolecia esa princesa? preguntó con indolencia la dama que conceptuando que la relacion seria larga, puso la lámpara en un nicho calado y se sentó en un divan.\"},{\"heading\":false,\"text\":\"--La princesa africana adolecia de tristeza, contestó el príncipe sentándose á los pies del lecho: del mismo mal de que adolezco yo.\"},{\"heading\":false,\"text\":\"--Ocupémonos ahora de la dolencia de la princesa, que tiempo tendremos de llegar á la tuya. Continúa.\"},{\"heading\":false,\"text\":\"--La princesa, mejor dicho, la sultana[6] Leila-Radhyah[7] habia ido á Córdoba acompañada por uno de los wacires de su padre, Mohamet Al-Mostansir-Billah, rey de Tlencen y servida por un número considerable de hermosas esclavas.\"},{\"heading\":false,\"text\":\"--Por lo que veo tu padre el poderoso Nazar tiene harto presente el nombre de esa sultana. ¿Cuándo te refirió tu padre esa historia?\"},{\"heading\":false,\"text\":\"--Hace un año, al proclamarme su heredero, y hacerme su partícipe en el gobierno del reino.\"},{\"heading\":false,\"text\":\"--Continúa.\"},{\"heading\":false,\"text\":\"--Ya te he dicho que la sultana Leila-Radhyah, habia ido desde Tlencen á Córdoba, á buscar alivio á su dolencia: pues bien, la noche antes de que la princesa llegase á las fronteras de Córdoba, un buho entró por la ventana del aposento donde dormia mi padre, batió las alas sobre su cabeza y le despertó.\"},{\"heading\":false,\"text\":\"--¿Y qué desgracia aconteció al noble Al-Hhamar?\"},{\"heading\":false,\"text\":\"--Mi padre vió huir al buho por la ventana, y se acordó del buho que habia girado en derredor de su cabeza la noche antes de la batalla en que tan peligrosamente le hirieron, y de aquel otro buho que apagó las luces en las fiestas de su nacimiento. Pero lo tuvo á casualidad y sin pensar mas en ello se durmió de nuevo, cuando hé aquí que le despertaron las voces de sus soldados. Levántase mi padre, sale de su aposento y pregunta al primero que encuentra.--Las atalayas de la frontera hacen señal de que los cristianos han entrado por la tierra y la llevan á sangre y fuego: entre las sombras de la noche se ven las llamas de las alkarias incendiadas:--Y el que esto le contesta corre á donde están ya sus compañeros armados.--Mi padre llama á sus esclavos, se arma tambien, reune á sus soldados alrededor de su bandera y parte con ellos de Córdoba el primero, con su valiente taifa de ginetes, en busca del cristiano.--Otros muchos walíes salen tambien de Córdoba con sus gentes armadas, pero mi padre les lleva la delantera y al amanecer encuentra á los cristianos.\"},{\"heading\":false,\"text\":\"--¿Y qué desgracia aconteció á tu padre?\"},{\"heading\":false,\"text\":\"--Mi padre venció en la primera embestida á los infieles, los puso en fuga y les quitó la presa que habian hecho. Entre la presa iba una doncella mora de maravillosa hermosura. Aquella doncella era la sultana Leila-Radhyah.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡era la sultana!\"},{\"heading\":false,\"text\":\"--Sí; al llegar á la frontera, la encontraron los cristianos, mataron al wacir del rey de Tlencen, á los esclavos que la acompañaban, y la hicieron cautiva con sus esclavas.--Mi padre mandó que la condujesen en un palanquin á Córdoba, y fué conversando con ella todo el camino.--Era tan hermosa, tan pura y tan resplandeciente como un dia sereno en un valle del Hedjaz.--Mi padre se enamoró de ella...\"},{\"heading\":false,\"text\":\"--¿Y ella?\"},{\"heading\":false,\"text\":\"--Amó á mi padre.\"},{\"heading\":false,\"text\":\"--¡Murió sin duda la desdichada! dijo la dama blanca con una profunda amargura; porque de no, tu padre que es noble y generoso la hubiera hecho su esposa.\"},{\"heading\":false,\"text\":\"--No, dijo el príncipe bajando los ojos.\"},{\"heading\":false,\"text\":\"--¡La envió sin duda á su padre el rey de Tlencen!\"},{\"heading\":false,\"text\":\"--No; mi padre la amaba demasiado para no temer perderla, y mi padre entonces no podia aspirar á que una sultana fuese su esposa.--Nuestra familia es humilde: mis abuelos fueron labradores, y este es el mayor orgullo de mi padre: haber llegado á tan alto habiendo nacido tan bajo.--Mi padre cuando se apoderó de la sultana Leila-Radhyah, era walí; tenia riquezas y una bella casa en Córdoba.\"},{\"heading\":false,\"text\":\"--¿Pero qué hizo tu padre de la sultana Leila-Radhyah?\"},{\"heading\":false,\"text\":\"--La llevó á su casa.\"},{\"heading\":false,\"text\":\"--¡Ah! tu padre dijo: los cristianos se llevaban esta doncella para hacer con ella una ramera: ¿por qué no he de hacerla yo mi esclava? lo que el guerrero encuentra en el campo es suyo. ¡Hizo tu padre bien! Pero continúa: la sultana, por mejor decir, la esclava, debió morir de vergüenza.\"},{\"heading\":false,\"text\":\"--No: un año despues de sus amores con mi padre desapareció de su casa, encontróse sangre en su aposento, y mi padre, que la amaba, lloró su pérdida y la llora todavía.\"},{\"heading\":false,\"text\":\"--¿Y no te ha contado tu padre mas acerca de la sultana esclava?\"},{\"heading\":false,\"text\":\"--No; pero cuando me contó esos amores cuya desgracia anunció sin duda el buho, mi padre lloraba.\"},{\"heading\":false,\"text\":\"--¿Y qué otras desgracias le anunció ese buho tan terrible?\"},{\"heading\":false,\"text\":\"--Le vió la noche antes de la funesta batalla de Hins-Alacab[8]. Le vió la alborada en que Córdoba cayó en poder de los cristianos: la noche que precedió al dia de la pérdida de Sevilla, le vió tambien, y por último, la misma noche en que murió asesinado por el walí de Almería el desdichado Aben-Hud.\"},{\"heading\":false,\"text\":\"--¿Y no ha vuelto á ver tu padre á ese terrible buho?\"},{\"heading\":false,\"text\":\"--Sí, hace poco tiempo: precavido ya con las desventuras que le habian acontecido, mi padre llamó á sus sabios y les consultó.\"},{\"heading\":false,\"text\":\"--Ese buho te anuncia una nueva desgracia, le dijeron los sabios.\"},{\"heading\":false,\"text\":\"--¿Y qué desgracia es esa?\"},{\"heading\":false,\"text\":\"--Necesitamos consultar las estrellas para responderte.\"},{\"heading\":false,\"text\":\"--Consultadlas, pues, dijo mi padre.\"},{\"heading\":false,\"text\":\"Los sabios pasaron tres noches mirando el cielo, y dijeron á mi padre.\"},{\"heading\":false,\"text\":\"--Aparta de Granada al príncipe Mohammet Abd\'Allah.\"},{\"heading\":false,\"text\":\"--¿Y por qué? preguntó mi padre.\"},{\"heading\":false,\"text\":\"--Apártale, contestaron los sabios.\"},{\"heading\":false,\"text\":\"--¿Pero qué tengo que temer acerca de mi hijo?\"},{\"heading\":false,\"text\":\"--Las estrellas nos han dicho que amenazan á tu hijo y á tí lo mismo, grandes desgracias si el príncipe continúa en Granada durante la luna de las flores.\"},{\"heading\":false,\"text\":\"Mi padre mandó á los sabios que consultasen de nuevo las estrellas.\"},{\"heading\":false,\"text\":\"Pero una, dos y tres veces, las estrellas guardaron un profundo misterio acerca del peligro que nos amenazaba, y solo repitieron que debia yo huir de Granada.\"},{\"heading\":false,\"text\":\"Entonces mi padre me envió á Alhama.\"},{\"heading\":false,\"text\":\"Yo estaba triste. Mi corazon tenia sed. Mi alma anhelaba un misterio: pasaron para mí los dias sin luz y las noches sin reposo. Yo me sentia morir.\"},{\"heading\":false,\"text\":\"En vano mis ginetes lidiaban toros, y justaban y corrian cañas y sortijas: mi enfermedad, mi misteriosa enfermedad crecia: la tristeza me mataba: mis esclavos no lograban arrancarme una sonrisa; ni sus danzas me alhagaban, ni sus cantos me entretenian, ni como otras veces, me adormia en su regazo: hasta me olvidé de la oracion, llevando solo mi cuerpo á la casa de Dios, pero no mi alma.\"},{\"heading\":false,\"text\":\"Yo palidecia, yo enlanguidecia.\"},{\"heading\":false,\"text\":\"--¡Como la sultana Leila-Radhyah!\"},{\"heading\":false,\"text\":\"--Sí; como la sultana. Súpolo mi padre, y vino á Alhama sin que yo lo supiese y preparó grandes fiestas para ver si yo me distraia. En el mismo punto en que mi padre entró en Alhama, segun supe despues, un buho entró en mi retrete y apagó la lámpara.\"},{\"heading\":false,\"text\":\"--Veamos la desgracia que te anunciaba ese buho.\"},{\"heading\":false,\"text\":\"--Al dia siguiente me sorprendió bajo mis ventanas una inusitada y alegre música de dulzainas, guzlas y atabaljos que tañian en un son concertado. Abrí un ajimez, entró por él un dorado rayo de sol de la mañana. Era el primer sol de la luz de las flores. El jardin parecia reir: parecian reir sus fuentes; parecia que sus flores, y sus árboles, y sus pájaros cantaban todos juntos; y que cantaba el cielo, y que cantaba el sol. Hermosas esclavas danzaban y tañian cuando yo aparecí en el ajimez, entonando un romance de amores en loor mio.\"},{\"heading\":false,\"text\":\"Estuve contemplando aquello durante un corto espacio, y luego me separé del ajimez con los ojos llenos de lágrimas.\"},{\"heading\":false,\"text\":\"Al volverme encontré delante de mí á mi padre que me miraba con tierno cuidado.\"},{\"heading\":false,\"text\":\"--¿Por qué estás abatido mi hermoso leoncillo? me dijo: ¿por qué vierten tus ojos lágrimas y están pálidas tus megillas?\"},{\"heading\":false,\"text\":\"--No lo sé, le contesté: mis ojos no tienen luz ni alegría mi alma: la vida me pesa como la losa de una tumba.\"},{\"heading\":false,\"text\":\"--¿Amas á alguna muger? si amas, dímelo; y esa muger será tuya, ya sea una humilde labradora ó una poderosa sultana, me dijo.\"},{\"heading\":false,\"text\":\"--Ninguna muger entristece mi alma, esclamé arrojándome entre sus brazos.\"},{\"heading\":false,\"text\":\"Mi padre procuró alegrarme, me mandó vestir mis mejores galas, montar uno de mis mejores caballos, y así, él á mi lado y seguidos de lo mas resplandeciente de la córte, salimos de los muros, y llegamos á un ameno campo, donde durante aquella noche habia hecho levantar mi padre una plaza de madera cubierta de paños de púrpura y oro.\"},{\"heading\":false,\"text\":\"Dentro de aquella plaza debian correrse toros, cañas y sortijas, y las graderías y los estrados estaban henchidos de hermosas damas cubiertas de galas menos resplandecientes que su hermosura.\"},{\"heading\":false,\"text\":\"En cuanto entré en la plaza, mis ojos se volvieron como si les hubiese obligado á ello el deseo, á un estrado puesto junto al estrado real, y se fijaron en una muger.\"},{\"heading\":false,\"text\":\"Aquella muger estaba, como tú, vestida de blanco; sin joyas como tú, y mas jóven que tú, aunque no mas hermosa.\"},{\"heading\":false,\"text\":\"Aquella muger era una doncella como de veinte años, pálida y triste como la luna, y hermosa y magnífica como el sol: tras de ella habia un hombre alto, flaco, viejo, vestido tambien enteramente de blanco, con los ojos relucientes como carbunclos que se fijaban en mí y en mi padre de una manera que me espantaba.\"},{\"heading\":false,\"text\":\"Pero la doncella alegraba mi alma con su hermosura, la embriagaba con su mirada, sentia ante ella que una nueva vida me hacia fuerte y poderoso, y me volví á mi padre para decirle:--allí está la hurí que yo amo, la alegría de mi alma, la paz de mi sueño, la vida de mi vida; es necesario que esa muger sea mia, esclava ó sultana, dama ó labradora.\"},{\"heading\":false,\"text\":\"Pero cuando miré á mi padre, ví sus ojos fijos, absortos, asombrados, en la doncella.\"},{\"heading\":false,\"text\":\"Ví en sus ojos amor, un amor ardiente. Tuve miedo y callé.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡tu padre se habia enamorado como tú de la doncella blanca!\"},{\"heading\":false,\"text\":\"--Hé ahí, hé ahí la desgracia que me habia anunciado el buho.\"},{\"heading\":false,\"text\":\"Las fiestas fueron para mí muy tristes. Mi padre no volvió á preguntarme mas acerca de mi tristeza. Estaba absorto en la contemplacion de la doncella blanca á quien yo no me atrevia á mirar por temor á mi padre.\"},{\"heading\":false,\"text\":\"Al dia siguiente mi padre se volvió á Granada.\"},{\"heading\":false,\"text\":\"¿Se habria llevado consigo á su harem á la hermosa doncella?\"},{\"heading\":false,\"text\":\"Tuve celos: celos horribles porque eran celos de mi padre.\"},{\"heading\":false,\"text\":\"Pregunté á mis wacires, á los alcaides, á los kadis de Alhama, si conocian á una dama enlutada que con un viejo enlutado tambien, habia asistido á las fiestas.\"},{\"heading\":false,\"text\":\"El alcaide del alcázar me contestó que un viejo enlutado habia estado hablando mucho tiempo con el rey antes de su partida y que despues no le habian vuelto á ver. Que aquel viejo era forastero y que nadie le conocia en Alhama.\"},{\"heading\":false,\"text\":\"¿A qué preguntar mas?\"},{\"heading\":false,\"text\":\"Mi padre habia comprado aquella doncella sin duda, y por su amor se habia olvidado de su hijo.\"},{\"heading\":false,\"text\":\"Pero me resigné con la voluntad de Dios.\"},{\"heading\":false,\"text\":\"Volvió mi tristeza mas dolorosa, mas desesperada, y volvieron ó mas bien continuaron mis noches sin sueño.\"},{\"heading\":false,\"text\":\"Yo veia siempre delante de mí á la doncella blanca, de dia en las nubes, en las flores, en el fondo de las aguas: de noche en la luz de la lámpara, en los ángulos de mi cámara, escondida tras las cortinas de mi lecho: luego cuando el buho entraba y apagaba la luz, en medio de las tinieblas iluminándolas con el resplandor de su hermosura.\"},{\"heading\":false,\"text\":\"Yo me volvia loco.\"},{\"heading\":false,\"text\":\"Al tercer dia de la partida de mi padre, al entrar en mi cámara de vuelta de un solitario paseo por los jardines, encontré sobre mi divan una gacela enrollada y perfumada en que estaban escritos con elegantes caractéres azules los siguientes versos:\"},{\"heading\":false,\"text\":\"La perla de las perlas; la cándida y la pura; el sol de las hermosas; la rosa del Eden; la vírgen de tus sueños; tu sueño de ventura, espera á su adorado cuando á la noche oscura, los trémulos luceros fulgor y sombra dén.\"},{\"heading\":false,\"text\":\"Si buscas de sus ojos la fúlgida mirada; si de su aliento quieres la esencia respirar; si es vida de tu vida; si es llama consagrada, alma del alma tuya, que para tí guardada Dios tiene en sus misterios sobre escondido altar;\"},{\"heading\":false,\"text\":\"si quieres encontrarla; si anhelas sus amores, ven, príncipe, la noche te brinda con su amor: las márgenes del Darro la guardan entre flores, y en el silencio arrulla su sueño de dolores, trinando en los cipreses, el triste ruiseñor.\"},{\"heading\":false,\"text\":\"Detúvose el príncipe, reclinó la cabeza entre sus manos, y exhaló un ardiente suspiro.\"},{\"heading\":false,\"text\":\"--¿Era de ella? preguntó la dama.\"},{\"heading\":false,\"text\":\"--No lo sé, contestó el príncipe levantando la cabeza: solo sé que tanto leí los versos, que los aprendí de memoria, y luego... ella me llamaba: llamé al alcaide de mi palacio y le dije que durante siete dias no permitiese entrar á nadie en mi cámara.--Luego mandé que me ensillasen un caballo, y salí aquella misma noche de Alhama por un postigo de la alcazaba.\"},{\"heading\":false,\"text\":\"La gacela me decia que la doncella blanca moraba entre flores en los cármenes del Darro; aguijé, pues, mi caballo hácia Granada, á la que llegué antes del amanecer, rodeé por el cerro de Al-Bahul, trepé á la falda del cerro del Sol, bajé á la cumbre de la Colina Roja y me oculté con mi caballo en las ruinas del templo romano. Vino el dia; yo veia á lo lejos su luz por entre las grietas de las ruinas: un dia largo como una eternidad, en que la impaciencia me hizo olvidarme de mí mismo hasta el punto de no tocar á las provisiones que llevaba conmigo. Al fin se estinguió la luz y la reemplazó otra mas pálida: salí de las ruinas: era de noche: la luna iluminaba los montes: me arrastré por entre la maleza, para evitar que me viesen los soldados de la atalaya, y ganando la vertiente de la Colina, bajé al lecho del Darro, contra cuya corriente subí: anduve largo espacio: yo miraba á los cármenes; pero no veia cipreses; no escuchaba el trino del ruiseñor, sino á lo lejos y perdido en el silencio de la noche: al fin ví delante de mi un remanso en que brillaba la luz de la luna; al otro lado del remanso y mas allá de un jardin una casita blanca, y tras de ella un bosque de cipreses entre los cuales cantaba un ruiseñor.\"},{\"heading\":false,\"text\":\"Allí debia morar la doncella blanca: la hermosura del sitio era digna de su hermosura; su encanto digno de su encanto; su melancólico reposo compañero de su tristeza.\"},{\"heading\":false,\"text\":\"Esperé contemplando la casa y el jardin: esperé con el corazon ansioso, pero llegó el alba y nada ví; nada mas que la luna que desapareció: nada oí, nada mas que al ruiseñor que cantaba y que calló cuando los gallos anunciaron la mañana.\"},{\"heading\":false,\"text\":\"Me volví á las ruinas del templo mas triste y mas enfermo que nunca.\"},{\"heading\":false,\"text\":\"Pasé otro dia mas largo, mas terrible, y volví al remanso del rio; pasé delante de él, y como la noche anterior no ví mas que la luna brillando en las aguas, no oí mas que al ruiseñor cantando entre los cipreses.\"},{\"heading\":false,\"text\":\"Al fin, esta noche cuando ya desesperado llamé á la doncella blanca, un buho revoló alrededor de mi cabeza, me aterré, pretendí matarle, el buho se lanzó en la casita blanca, y mi flecha como te he dicho entró tras él.\"},{\"heading\":false,\"text\":\"Luego esta misma flecha cayó á mis pies trayendo entre sus plumas esta gacela que me envia á tí.\"},{\"heading\":false,\"text\":\"Y el príncipe sacó de entre su faja el pergamino, y le mostró á la dama.\"},{\"heading\":false,\"text\":\"--¿Y á pesar de que el buho anunciador de desdichas á tu familia ha revolado alrededor de tu cabeza, quieres ver á Bekralbayda?\"},{\"heading\":false,\"text\":\"--¡Oh! ¿aunque me costase la salvacion de mi alma? esclamó el jóven juntando los manos.\"},{\"heading\":false,\"text\":\"--¡Tú la amas!\"},{\"heading\":false,\"text\":\"--Como el arroyo al rio, como el rio al mar, como las flores á los céfiros, como el dia al sol.\"},{\"heading\":false,\"text\":\"--Príncipe, dijo solemnemente la dama: pues lo quieres, ven.\"},{\"heading\":false,\"text\":\"Y tomó la lámpara que habia dejado en el nicho, y salió de la cámara guiando al jóven.\"}]},{\"title\":\"El rey nazar. — capítulo IV: Bekralbayda.\",\"blocks\":[{\"heading\":false,\"text\":\"Despues de haber atravesado algunas pequeñas habitaciones en las cuales el príncipe no reparó por efecto de su preocupacion, de haber subido una estrecha escalera y de haber salido por una pequeña casita á un jardin, la dama hizo pasar al príncipe al otro lado del rio por un estrecho puente formado con troncos de árboles.\"},{\"heading\":false,\"text\":\"La dama habia dejado su lámpara en la pequeña casa por donde habian salido á la parte alta de la cortadura en cuyo fondo corria el Darro.\"},{\"heading\":false,\"text\":\"Solo les alumbraba la fantástica luz de la luna.\"},{\"heading\":false,\"text\":\"Vista á su rayo la dama con su larga túnica flotante, con sus negros cabellos sueltos, que agitaban las brisas de la noche, tenia algo de sobrenatural, de estraordinario.\"},{\"heading\":false,\"text\":\"Cuando hubieron atravesado el puente rústico, se encontraron en un jardin frondosísimo; las copas de los árboles se unian hasta el punto de no dejar paso á los rayos de la luna; la estrecha calle por donde marchaban estaba cubierta de cesped, y á uno de sus costados corria un arroyo que dejaba oir su melancólico y monótono murmurio; el ruiseñor continuaba cantando.\"},{\"heading\":false,\"text\":\"Las parras y las enredaderas, y la madreselva y la yedra, y los jazmines silvestres, cruzándose de árbol en árbol, formaban una magnífica bóveda natural bajo la que solo podian comprenderse el reposo y el amor.\"},{\"heading\":false,\"text\":\"La dama y el príncipe adelantaban bajo aquella enramada en medio de una luz opaca y lánguida: la tortuosa senda se hizo al fin recta y ancha: se encontraban á la entrada de una verde sala, ancha, elevada, tapizada de flores y revestida de un oscuro follage en cuyos mil aromas se impregnaba el viento.\"},{\"heading\":false,\"text\":\"Al entrar en aquella galería el príncipe se detuvo y dió un paso atrás: su corazon latió violentamente y lanzó una esclamacion ardiente, inarticulada.\"},{\"heading\":false,\"text\":\"Al fondo de aquella galería habia visto una sombra blanca iluminada enteramente por la luna que penetraba por un claro de la espesura.\"},{\"heading\":false,\"text\":\"--¿Qué sombra es aquella? dijo alentando apenas el príncipe á la dama.\"},{\"heading\":false,\"text\":\"--Es Bekralbayda que te espera, contestó la dama.\"},{\"heading\":false,\"text\":\"--¡Bekralbayda! ¡ella! ¡esperándome en medio de la noche y del silencio en este lugar de delicias! esclamó el jóven que se sentia morir.\"},{\"heading\":false,\"text\":\"Cuando el príncipe se volvió á buscar á su hermosa guia, esta habia desaparecido.\"},{\"heading\":false,\"text\":\"Estaba solo.\"},{\"heading\":false,\"text\":\"Delante de él, inmóvil, blanca, bajo el rayo de la luna, permanecia Bekralbayda.\"},{\"heading\":false,\"text\":\"El ruiseñor cantaba: el arroyo murmuraba; el viento agitaba levemente el follage.\"},{\"heading\":false,\"text\":\"El príncipe adelantó hácia Bekralbayda, dudando de sus ojos, de su razon; creyéndose entregado á un sueño.\"},{\"heading\":false,\"text\":\"Sin embargo, aquel no era sueño.\"},{\"heading\":false,\"text\":\"Llegó al fin junto á ella.\"},{\"heading\":false,\"text\":\"La jóven estaba al lado de una fuente.\"},{\"heading\":false,\"text\":\"Tenia la cabeza baja, la vista fija en el césped, y el príncipe á pesar de la luna creyó ver teñido de rubor su semblante.\"},{\"heading\":false,\"text\":\"--¡Alma de mi alma! esclamó el príncipe contemplándola estasiado.\"},{\"heading\":false,\"text\":\"--¡Alma de tu alma! esclamó Bekralbayda levantando sus lucientes ojos negros y posando su mirada sobre el príncipe: ¡alma de tu alma, yo!\"},{\"heading\":false,\"text\":\"--¡Oh! ¡sí! desde el dia en que te ví no aliento: desde el dia en que te ví te guardo en mi memoria, como un consuelo y como un infierno: desde el dia en que te ví, lo he olvidado todo para no pensar mas que en tí: no he vivido sino para tí: solo por tí he esperado.\"},{\"heading\":false,\"text\":\"--¿Y dónde me has visto, señor?\"},{\"heading\":false,\"text\":\"--¡Ah! ¿has olvidado, sultana, el lugar donde te he visto?\"},{\"heading\":false,\"text\":\"--Solo una vez, dijo Bekralbayda, he visto damas cubiertas de joyas y galas; caballeros resplandecientes cabalgando en briosos corceles; soldados y banderas; fiesta régia; alegre música, toros y cañas: me habian hablado mucho de ello, habia leido poemas en que se contaban todas estas grandezas, me habian dicho que sería un dia sultana: pero yo no he salido nunca de aquí; ni he visto nunca mas que...\"},{\"heading\":false,\"text\":\"Bekralbayda se detuvo.\"},{\"heading\":false,\"text\":\"--¿Mas que á quién? dijo con cierto celoso anhelo el príncipe.\"},{\"heading\":false,\"text\":\"--Yo no puedo decir quien es la persona á quien veo junto á mí desde mi infancia.\"},{\"heading\":false,\"text\":\"--Pero esa persona...\"},{\"heading\":false,\"text\":\"--Es un hombre...\"},{\"heading\":false,\"text\":\"--¿Un hombre viejo?...\"},{\"heading\":false,\"text\":\"--Sí, un anciano.\"},{\"heading\":false,\"text\":\"--¿El que te acompañaba en las fiestas de Alhama?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"Tranquilizóse el príncipe.\"},{\"heading\":false,\"text\":\"--¿Y no recuerdas haberme visto en las fiestas?\"},{\"heading\":false,\"text\":\"--No reparé en nada; aquella magnificencia, aquel esplendor, aquella multitud de damas y caballeros me aturdian.\"},{\"heading\":false,\"text\":\"--Pues en esas fiestas te conocí y te amé.\"},{\"heading\":false,\"text\":\"--¡Amor! ¿y qué es amar? dijo Bekralbayda.\"},{\"heading\":false,\"text\":\"--¡Oh! ¿no sabes lo que es amor?\"},{\"heading\":false,\"text\":\"--¡El amor! le he visto en palabras en los poemas: he comprendido que amar es morir.\"},{\"heading\":false,\"text\":\"--El amor es la vida cuando el ser que amamos nos ama.\"},{\"heading\":false,\"text\":\"--¿Y cuando no somos amados?...\"},{\"heading\":false,\"text\":\"--El amor es la muerte.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿el amor es muerte y vida?\"},{\"heading\":false,\"text\":\"--Escucha: dijo el príncipe asiendo una mano á Bekralbayda y llevándola á un banco de cesped donde se sentaron: el amor es la vida, cuando se satisface: el amor es la muerte cuando se desea sin esperanza.\"},{\"heading\":false,\"text\":\"--No te entiendo.\"},{\"heading\":false,\"text\":\"--Entonces si no me entiendes, ¿cómo has escrito la gacela en que que llamabas y que me has arrojado con mi flecha?\"},{\"heading\":false,\"text\":\"--¡Ah! ¡tu flecha! esclamó estremeciéndose Bekralbayda.\"},{\"heading\":false,\"text\":\"--¿Por qué tiemblas alma mia?\"},{\"heading\":false,\"text\":\"--¡Tu flecha!... estaba yo reclinada en mi divan: acababa de cantar un antiguo romance de los amores de una hada.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿con que ese romance no lo cantabas para mí?\"},{\"heading\":false,\"text\":\"--No, hace mucho tiempo que lo sé de memoria, contestó sonriendo Bekralbayda.\"},{\"heading\":false,\"text\":\"Sofocó un suspiro de despecho el príncipe.\"},{\"heading\":false,\"text\":\"--Acababa de cantar, continuó Bekralbayda, cuando entró precipitadamente por la ventana Abu-al-abu.\"},{\"heading\":false,\"text\":\"--¿Y quién es Abu-al-abu?\"},{\"heading\":false,\"text\":\"--Es un buho á quien por viejo he puesto yo ese nombre.[9] Tras Abu-al-abu entró una flecha, que cortó la rosa que yo tenia prendida en los cabellos y se clavó detrás de mí en la pared.\"},{\"heading\":false,\"text\":\"Estremecióse el príncipe con aquel relato: al querer matar al buho habia cortado con su flecha la corona de flores de la muger de su amor.\"},{\"heading\":false,\"text\":\"Los moros eran muy supersticiosos, y tenian una gran sutileza para aplicar una causa á un acontecimiento algo estraordinario: Mohammet Abd-Allah creyó que no habiendo acertado al buho con su flecha, y habiendo estado á punto de matar con ella á Bekralbayda, se esponia á causarla la muerte si mataba no ya á Abu-al-abu, sino cualquier otro buho.\"},{\"heading\":false,\"text\":\"Los buhos, pues, se hicieron sagrados para el príncipe.\"},{\"heading\":false,\"text\":\"Por nada del mundo hubiera disparado sobre un buho.\"},{\"heading\":false,\"text\":\"Pero el amor y la hermosura de Bekralbayda, le habian inspirado una consecuencia sumamente lógica, considerada la cuestion bajo el punto de vista en que su supersticion le habia colocado; la consecuencia era esta:\"},{\"heading\":false,\"text\":\"Si habia tal paridad, tal union vital y estraordinaria entre los buhos y Bekralbayda, y siendo los buhos fatales á su familia, Bekralbayda debia serle tambien fatal.\"},{\"heading\":false,\"text\":\"Tan cierto es que el hombre no vé mas que lo que quiere ver.\"},{\"heading\":false,\"text\":\"Dominóse sin embargo el príncipe, y dijo á la hermosísima Bekralbayda:\"},{\"heading\":false,\"text\":\"--¿Y quién arrancó la flecha de la pared?\"},{\"heading\":false,\"text\":\"Bajó los ojos Bekralbayda como aquel que no estando acostumbrado á mentir se ruboriza antes de pronunciar una mentira, y contestó:\"},{\"heading\":false,\"text\":\"--Yo arranqué la flecha.\"},{\"heading\":false,\"text\":\"--¿Y pusiste en ella la gacela?\"},{\"heading\":false,\"text\":\"--Sí, yo escribí la gacela, yo la puse en la flecha, yo la arrojé á tus pies.\"},{\"heading\":false,\"text\":\"--Y dime... ahora que lo recuerdo: ¿quien se rió dentro de la habitacion donde se refugió el buho?\"},{\"heading\":false,\"text\":\"Fijó Bekralbayda sus grandes y candorosos ojos en el príncipe, los bajó y contestó sonriéndose:\"},{\"heading\":false,\"text\":\"--El que dió aquella carcajada fué Abu-al-abu.\"},{\"heading\":false,\"text\":\"--¿El buho?\"},{\"heading\":false,\"text\":\"--Sí; ¿no has leido los poemas de Antar?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Y en ellos no hablan los animales?\"},{\"heading\":false,\"text\":\"--Sí, pero...\"},{\"heading\":false,\"text\":\"--Pues bien Abu-al-abu es uno de los animales que hablan como hablaban en tiempos de Antar.\"},{\"heading\":false,\"text\":\"Las respuestas de Bekralbayda que mas adelante comprenderemos, asustaban al príncipe.\"},{\"heading\":false,\"text\":\"Para él era indudable, que un alma condenada encerrada en el cuerpo de un buho perseguia á su familia.\"},{\"heading\":false,\"text\":\"--Y si no conoces el amor, si no me amas ¿cómo en nombre de tu amor me has llamado? ¿te lo aconsejó acaso Abu-al-abu?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Y fué tambien Abu-al-abu el que llevó tus versos á mi alcazaba de Alhama?\"},{\"heading\":false,\"text\":\"Letre dib.º y lit.ª Lot. de J. J. Martinez. Desengaño, 10 Madrid.]\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Pero para qué me has llamado?\"},{\"heading\":false,\"text\":\"Bajó los ojos de nuevo Bekralbayda, su rostro se cubrió de un rubor vivísimo, tembló y quiso en vano pronunciar algunas palabras.\"},{\"heading\":false,\"text\":\"El príncipe insistió, y entonces ella, levantó el bello y purísimo semblante, miró frente á frente con ansiedad al príncipe y contestó.\"},{\"heading\":false,\"text\":\"--Te he llamado para ser tu esclava.\"},{\"heading\":false,\"text\":\"Y luego se cubrió el rostro con las manos, y procuró en vano contener su llanto.\"},{\"heading\":false,\"text\":\"--Aquí hay un misterio que no comprendo, luz de mis ojos: ¡tú mi esclava! ¡tú, que eres la señora de mi alma! ¡tú, por quién únicamente vivo! ¡tú lloras por mi causa! ¿qué misterio es este, sol de hermosura? ¿qué maldicion pesa sobre nosotros que así te aflije mi presencia? ¿Será acaso que Eblís[10] se ha puesto entre nosotros, encerrado en el cuerpo de Abu-al-abu?\"},{\"heading\":false,\"text\":\"Al pronunciar el príncipe estas palabras sonó á alguna distancia de él, á sus espaldas, la misma carcajada acerada, fria, sarcástica, burlona, que habia escuchado antes.\"},{\"heading\":false,\"text\":\"Bekralbayda volvió azorada el rostro á donde habia sonado la carcajada, y el príncipe se puso violentamente de pie.\"},{\"heading\":false,\"text\":\"--¡Ah! dijo la jóven á media voz, como para sí misma. Ya lo sabia yo. ¡Estaba ahí!\"},{\"heading\":false,\"text\":\"--¿Quién estaba ahí? preguntó el príncipe que habia escuchado estas palabras.\"},{\"heading\":false,\"text\":\"--Abu-al-abu, contestó la jóven en el mismo tono.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡buho maldito! esclamó el príncipe.\"},{\"heading\":false,\"text\":\"Entonces resonó otra vez la carcajada pero lejana, muy lejana.\"},{\"heading\":false,\"text\":\"Entonces asió con ánsia Bekralbayda las manos del príncipe.\"},{\"heading\":false,\"text\":\"--¡Oh! esclamó con acento ardiente y precipitado: ¡estamos un momento solos! ¡quien se rió antes, quien se ha reido ahora: no es el buho, es Yshac-el-Rumi: el viejo que me guarda!\"},{\"heading\":false,\"text\":\"--¡Ah! esclamó el príncipe.\"},{\"heading\":false,\"text\":\"--El fué quien me llevó á Alhama: él quien me hizo reparar en tí: él quien comprando á uno de tus esclavos, introdujo en tu cámara unos versos; él quien arrancó la flecha; quien puso en ella la gacela... él quien te ha traido aquí.\"},{\"heading\":false,\"text\":\"--Pero...\"},{\"heading\":false,\"text\":\"--Necesitamos aprovechar el tiempo; yo te amo, te amo, príncipe, como me amas tú; y...\"},{\"heading\":false,\"text\":\"La jóven se detuvo, miró entre la espesura á un ajimez de la casita blanca y esclamó con alegría.\"},{\"heading\":false,\"text\":\"--¡Estamos libres, enteramente libres! ¡podemos hablar cuanto queramos sin temor de ser escuchados! ¡podemos comprendernos!\"},{\"heading\":false,\"text\":\"--No te entiendo.\"},{\"heading\":false,\"text\":\"--¿Ves aquel ajimez?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Ves un hombre que esta apoyado en él, y tras el cual se vé el reflejo de una lámpara?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--Pues bien, aquel es Yshac-el-Rumi.\"},{\"heading\":false,\"text\":\"Dicho esto Bekralbayda respiró libremente como quien descansa de una larga jornada, guardó algun tiempo silencio y luego dijo al príncipe.\"},{\"heading\":false,\"text\":\"--Escúchame, te voy á contar una historia.\"},{\"heading\":false,\"text\":\"El príncipe escuchó con toda su alma.\"}]},{\"title\":\"El rey nazar. — capítulo V: Una historia muy sencilla.\",\"blocks\":[{\"heading\":false,\"text\":\"Una alborada de primavera subió Yshac-el-Rumi, al terrado de su casa.\"},{\"heading\":false,\"text\":\"En él encontró un canastillo de palma primorosamente labrado, y cubierto de hermosas flores.\"},{\"heading\":false,\"text\":\"De entre las flores salia el vaguido de una criatura al parecer recien nacida.\"},{\"heading\":false,\"text\":\"Yshac quitó las flores y encontró debajo una niña vestida de blanco.\"},{\"heading\":false,\"text\":\"Pendiente del cuello de la niña se veia un amuleto, y á su lado un pergamino en que estaban escritas estas palabras:\"},{\"heading\":false,\"text\":\"«Una sultana la ha dado á luz. Las buenas hadas la han llamado Bekralbayda.\"},{\"heading\":false,\"text\":\"»Que ojos humanos no vean su hermosura, porque seria desgraciada y lo serias tú.»\"},{\"heading\":false,\"text\":\"Yshac, me sacó del canastillo, llamó á una nodriza y me crió secretamente.\"},{\"heading\":false,\"text\":\"Porque aquella niña, como te lo ha dicho mi nombre, era yo.\"},{\"heading\":false,\"text\":\"No recuerdo los primeros años de mi infancia.\"},{\"heading\":false,\"text\":\"Sin embargo, algunas veces como un sueño lejano, confuso, creo recordar á una muger.\"},{\"heading\":false,\"text\":\"Recuerdo tambien confusamente que era muy jóven y muy hermosa.\"},{\"heading\":false,\"text\":\"Yshac afirma, sin embargo, que no me vió otra muger que mi nodriza, que era una rústica que nada tenia de hermosa, mientras que la muger que yo creo recordar era hermosísima.\"},{\"heading\":false,\"text\":\"Pasaron los años.\"},{\"heading\":false,\"text\":\"Este jardin, estos árboles, estas fuentes han visto mi infancia y mi juventud; fuera de ellos yo no habia visto nada, ni persona humana, mas que á Yshac-el-Rumi, que se ocupaba en cultivar mi espíritu.\"},{\"heading\":false,\"text\":\"Parecia que viviamos solos.\"},{\"heading\":false,\"text\":\"Yo no escuchaba en la casa ruido alguno.\"},{\"heading\":false,\"text\":\"Y á pesar de esto bastaba con que yo estuviese durante algun tiempo fuera de mi retrete, oyendo la sabia palabra de Yshac, que me sujetaba todos los dias á muchas horas de estudio, para que al volver viese renovadas las flores en los búcaros, renovado el fuego y los perfumes de los braserillos, limpio y arreglado el lecho.\"},{\"heading\":false,\"text\":\"Yshac no se habia separado de mí; luego alguien, á quien yo no sentia, á quien yo no veia, nos acompañaba en la casa.\"},{\"heading\":false,\"text\":\"Yo preguntaba á Yshac, pero Yshac callaba.\"},{\"heading\":false,\"text\":\"Cuando insistia solia responderme.\"},{\"heading\":false,\"text\":\"--Aun no es tiempo.\"},{\"heading\":false,\"text\":\"Yo me entristecia al pensar en el misterio que me rodeaba.\"},{\"heading\":false,\"text\":\"Porque Yshac me habia enseñado á leer, á escribir, á componer frases valiéndome de las flores, y me habia dado libros en que se hablaba de un mundo que yo no conocia, de un mundo en que habia poderosos y nobles reyes, hermosas sultanas, valientes caballeros, enamorados, damas, fiestas, aventuras, amores.\"},{\"heading\":false,\"text\":\"¡Oh! yo ansiaba conocer todo esto, y cuando espresaba mi deseo á Yshac me decia:\"},{\"heading\":false,\"text\":\"--Aun no es tiempo.\"},{\"heading\":false,\"text\":\"--¿Pero cuando llegará ese tiempo? le dije cansada ya de tan misteriosa contestacion.\"},{\"heading\":false,\"text\":\"--Cuando hayan pasado sobre tu vida veinte años: cuando el amor haya hablado á tu corazon.\"},{\"heading\":false,\"text\":\"--¿Y cuándo hablará en mi corazon eso que tú llamas amor?\"},{\"heading\":false,\"text\":\"--Aun no es tiempo, me contestaba Yshac.\"},{\"heading\":false,\"text\":\"Me resigné al fin y pasé mi vida entre flores y fuentes; entre la armonia del canto de mis ruiseñores y de mi guzla.\"},{\"heading\":false,\"text\":\"Yo no conocia á otra persona que á Yshac; no tenia mas amigo que á Abu-al-abu.\"},{\"heading\":false,\"text\":\"El viejo buho habia sido mi compañero desde la infancia: en cuanto oscurecia entraba por una ventana ó por un ajimez en la habitacion que yo me encontraba, se posaba sobre mi hombro, ó sobre mis rodillas, ó sobre un almohadon del divan: esponjaba su plumaje, batia levemente las alas, y lanzaba de tiempo en tiempo un ténue silvido; Abu-al-abu queria sin duda decirme algo; pero yo no comprendia su lenguaje.\"},{\"heading\":false,\"text\":\"Cuando yo le acariciaba pasando mi mano sobre sus alas, Abu-al-abu se estremecia y repetia sus silvidos mas ténues, mas dulces y esponjaba mas su plumaje y acababa por dormirse.\"},{\"heading\":false,\"text\":\"Yo amo á ese pobre viejo; él y mis pájaros y mis flores, son los únicos que tienen para mí demostraciones de afecto; y sonoros cantos y suaves perfumes.\"},{\"heading\":false,\"text\":\"Yshac está siempre sombrío, hosco, me mira con sobrecejo, habla conmigo muy pocas palabras, y con mucha frecuencia en medio de la noche, me estremece su risa, esa risa dolorosa y terrible, esa risa de condenado.\"},{\"heading\":false,\"text\":\"Pasaba así mi vida; llegó al fin un dia en que me sentí llena de una vida nueva; sentia en mi corazon una ansiedad lenta, dulce, pero que á pesar de su dulzura me atormentaba, cuando leia los hermosos poemas de Antar: cuando leia que un caballero enamorado iba venciendo peligros en busca de una dama encantada, yo me decia:\"},{\"heading\":false,\"text\":\"--¿Cuál será el caballero que me saque de mi encanto?\"},{\"heading\":false,\"text\":\"Yo quiero que sea blanco como las cándidas rosas de mi jardin; que tenga los ojos negros como el fondo de las grutas del rio; que sea mas gentil que el álamo, mas amoroso que el ruiseñor cuando trina: yo quiero que mi amado sea valiente, leal y buen caballero: yo le quiero ver en el esplendor de su poder y de su juventud.\"},{\"heading\":false,\"text\":\"--Y yo preguntaba al buho:\"},{\"heading\":false,\"text\":\"--¿Dónde está el amado de mi alma?\"},{\"heading\":false,\"text\":\"Y el buho silvaba dolorosamente.\"},{\"heading\":false,\"text\":\"Y preguntaba al ruiseñor, y el ruiseñor callaba.\"},{\"heading\":false,\"text\":\"Y preguntaba á las flores, y las flores parecia que querian apartarse de mí volviéndose sobre su tallo.\"},{\"heading\":false,\"text\":\"Y preguntaba á Yshac, y él me contestaba:\"},{\"heading\":false,\"text\":\"--Aun no es tiempo.\"},{\"heading\":false,\"text\":\"Y al escuchar estas desconsoladoras respuestas, mis ojos se llenaban de lágrimas y en mi pensamiento despierta, y en mis sueños dormida, veia yo al mancebo de mí amor, mas enamorado, mas valiente, mas generoso, enlazadas mis manos á las suyas, viviendo en su vida.\"},{\"heading\":false,\"text\":\"Y--Yo le amo, yo le espero, decia al buho y al ruiseñor y á las fuentes y á las flores.\"},{\"heading\":false,\"text\":\"Y todos ellos me contestaban de una manera dolorosa como si hubieran querido decirme:\"},{\"heading\":false,\"text\":\"--El amor de tu amado será fatal para tí.\"},{\"heading\":false,\"text\":\"Y empecé á ponerme pálida, como los claveles cuando les falta el rayo del sol.\"},{\"heading\":false,\"text\":\"Y empezó el sueño á huir de mis noches, y la paz desapareció completamente de mis dias.\"},{\"heading\":false,\"text\":\"Todo era triste para mí.\"},{\"heading\":false,\"text\":\"El cielo y la tierra: el sol y las nubes: y las flores.\"},{\"heading\":false,\"text\":\"Un dia... hace muy poco tiempo, Yshac me dijo:\"},{\"heading\":false,\"text\":\"--Ha llegado la hora.\"},{\"heading\":false,\"text\":\"--¿La hora de conocer á mi amado?\"},{\"heading\":false,\"text\":\"--Sí, me contestó.\"},{\"heading\":false,\"text\":\"Al dia siguiente me montó en un asno sencillamente enjaezado y cubierta con un haike, y él detrás, cubierto con su albornoz, me sacó del jardin; seguimos el rio abajo, atravesamos una hermosa ciudad, salimos a una deliciosísima vega y caminamos por ella hácia donde se pone el sol.\"},{\"heading\":false,\"text\":\"Aquella noche llegamos á otra ciudad rodeada de fuertes muros y altísimas torres.\"},{\"heading\":false,\"text\":\"¿Qué ciudad es aquella, pregunté á Yshac, que brilla como plata bajo la luz de la luna?\"},{\"heading\":false,\"text\":\"--En esa ciudad está el amado de tu alma, me contestó.\"},{\"heading\":false,\"text\":\"Y no dijo mas palabra, por mas que le pregunté.\"},{\"heading\":false,\"text\":\"Dormimos aquella noche en una casa, junto al rio, cerca de la ciudad.\"},{\"heading\":false,\"text\":\"Mejor hubiera dicho que pasamos la noche, porque yo no dormí.\"},{\"heading\":false,\"text\":\"En medio de mi vela me sorprendió el ruido de un aleteo.\"},{\"heading\":false,\"text\":\"Era Abu-al-abu que entraba por la ventana.\"},{\"heading\":false,\"text\":\"El pobre viejo nos habia seguido.\"},{\"heading\":false,\"text\":\"Se posó sobre mi hombro y estuvo largo rato silvando á mi oido de una manera lastimosa: luego se precipitó por la ventana y desapareció.\"},{\"heading\":false,\"text\":\"Al amanecer, Yshac me hizo montar en el asno y me llevó... al lugar donde te ví.\"},{\"heading\":false,\"text\":\"Cuando entramos, él mismo me quitó el haike y quedé con el rostro descubierto.\"},{\"heading\":false,\"text\":\"Todos me miraban, damas y caballeros.\"},{\"heading\":false,\"text\":\"Todos estrañaban, sin duda mi luto y el de Yshac.\"},{\"heading\":false,\"text\":\"Yo miraba á todos los mancebos que pasaban junto á mi ó que estaban á mi lado: ninguno era el de mis sueños, el ser á quien yo amaba sin conocerle.\"},{\"heading\":false,\"text\":\"Pero de repente sonó una música poderosa de trompetas y atabales, de dulzainas y añafiles, y entró el rey en la plaza.\"},{\"heading\":false,\"text\":\"A la derecha del rey venias tú.\"},{\"heading\":false,\"text\":\"Al verte mi corazon se estremeció, fijé en tí mis ojos y ya no los aparté mas.\"},{\"heading\":false,\"text\":\"Porque tú eras el hombre de mi amor. Mi corazon me lo dijo.\"},{\"heading\":false,\"text\":\"Pero tú me miraste un momento, y luego... apartaste de mí los ojos y no me volviste á mirar mas.\"},{\"heading\":false,\"text\":\"En cambio otro hombre me miraba tenazmente.\"},{\"heading\":false,\"text\":\"Era el rey.\"},{\"heading\":false,\"text\":\"Yo apartaba los ojos del rey, los fijaba en tí y no veia nada de lo que tenia alrededor.\"},{\"heading\":false,\"text\":\"Y las fiestas se acabaron y tú desapareciste, y yo quedé ciega y desdichada, con el corazon frio y los ojos llenos de lágrimas.\"},{\"heading\":false,\"text\":\"Al dia siguiente Yshac me trajo otra vez al jardin.\"},{\"heading\":false,\"text\":\"Al entrar en él me dijo:\"},{\"heading\":false,\"text\":\"--Tu amado vendrá y tú serás sultana.\"},{\"heading\":false,\"text\":\"Yo te esperaba.\"},{\"heading\":false,\"text\":\"Hoy me dijo Yshac:\"},{\"heading\":false,\"text\":\"--Tu amado vendrá esta noche: tú saldrás á su encuentro: las flores y las fuentes y las enramadas serán vuestros únicos testigos. Sé su esclava.\"},{\"heading\":false,\"text\":\"Yo quise hablar pero Yshac me dijo con fiereza.\"},{\"heading\":false,\"text\":\"--El destino lo quiere: la esclava debe esperar á su señor: pero que su señor no sepa la historia de su esclava; porque si la supiera moririas tú y moriria él.\"},{\"heading\":false,\"text\":\"Yshac no nos escucha, añadió Bekralbayda: está en aquel ajimez, y yo he podido contarte mi historia, he podido decirle te amo, soy tu esclava; tú eres la sed de mi corazon, el sol de mi vida; te veo, me escuchas y soy feliz.\"},{\"heading\":false,\"text\":\"Mientras Bekralbayda habia contado su sencilla historia al príncipe, la luna habia descendido y se habia ocultado al fin: la sombra habia cubierto árboles, fuentes y flores: despues que calló Bekralbayda, no se vió mas que la sombra de Yshac-el-Rumi en el ajimez en que lucia un resplandor opaco, ni se oyó mas que el murmullo de las fuentes y el aleteo de un buho que revolaba entre la enramada.\"}]},{\"title\":\"El rey nazar. — capítulo VI: El rey nazar visto por el lado histórico.\",\"blocks\":[{\"heading\":false,\"text\":\"Mohammet-ebn-Abd-Allah-ebn-Juzef-ebn-Al-Hhamar-al Nazar[11], el vencedor y el magnífico, sultan de Granada, era un poderoso rey, valiente y justiciero, que habia logrado reunir dentro de los muros de Granada, de la ciudad rival de Damasco, todos los restos dispersos del pueblo moro español, que las conquistas del santo rey Fernando III habian arrojado sucesivamente de Sevilla, de Córdoba, de Ubeda, de Baeza y de Jaen.\"},{\"heading\":false,\"text\":\"Granada, pues, habia reconcentrado en una reducida estension de terreno una poblacion inmensa: sus villas se habian ensanchado; la Vega, las vertientes de Sierra Nevada y las Alpujarras, se habian salpicado de aldeas, alquerías y castillos, y la misma Granada habia visto aparecer rápidamente sobre las laderas de sus montes, los barrios del Zenete y del Albaicin, fundados por los fugitivos de Baeza.\"},{\"heading\":false,\"text\":\"Granada en un dia de combate arrojaba por sus puertas ochenta mil ginetes, que juntos con los caballeros y gente ligera de la Vega y de las montañas componian un ejército de doscientos mil hombres fuertes y prácticos en la guerra contra el cristiano.\"},{\"heading\":false,\"text\":\"Fernando III, por la parte de Castilla y Andalucía, y don Jaime de Aragon por la de Valencia y Murcia, se vieron contenidos por aquella última barrera en que habian concentrado su pujanza los restos vencidos de los moros españoles.\"},{\"heading\":false,\"text\":\"Como cabeza de este reino de esta última esperanza de los moros en España, se veia al poderoso Ebn-Al-Hhamar-al-Nazar.\"},{\"heading\":false,\"text\":\"Digamos algo de este rey, el primero de la dinastía Nazerita, y fundador de la Alhambra.\"},{\"heading\":false,\"text\":\"Al-Hhamar era descendiente de la tribu de los beni-al-Ansari[12], un pariente ó sobrino de un Ansari que acompañó á Mahoma en su fuga de Medina á la Meca, llamado Ebada, habia venido de la Arabia á establecerse en España en los tiempos de la conquista de los árabes sobre la Península. De este Ansari, pues, descendia Al-Hhamar.\"},{\"heading\":false,\"text\":\"Pero fuese por las vicisitudes de la fortuna ó por otra causa cualquiera, los padres de Al-Hhamar eran labradores de Arjona, entonces populosa y rica villa de la Andalucía oriental.\"},{\"heading\":false,\"text\":\"A pesar de la escasa fortuna de sus padres, Al-Hhamar fué educado ventajosamente.\"},{\"heading\":false,\"text\":\"Era de despierto ingenio, y le enviaron á la universidad de Córdoba.\"},{\"heading\":false,\"text\":\"Gallardo, galan, fuerte y valiente causaba ya en su mocedad temor á los alentados, y habiendo demostrado aficion al ejercicio de las armas; su padre le dió una bolsa, una lanza y un caballo, le predicó un sermon que duró una hora larga acerca de la generosidad, del valor y demás deberes de un caballero, y le envió á buscar fortuna por el mundo.\"},{\"heading\":false,\"text\":\"Fuése á Córdoba con algunas cartas de recomendacion que habia recogido de sus parientes de Arjona y hubo de resignarse, por el momento, no á entrar con un cargo en el ejército, sino á desempeñar algunos oficios administrativos. Al fin, aprovechando las disidencias y las guerras civiles en que habia caido el califato de Córdoba, bajo el gobierno de los emires sucesores de Juzef-Amir Al-Mumenin, sirviendo ya al uno ya al otro, pero atendiendo siempre á la justicia de la causa á cuya defensa se decidia; ganada una y otra victoria, adquirió muy pronto en el ejército el dictado de Al-Nazar[13] que debia dar nombre á la dinastía fundada mas tarde por él.\"},{\"heading\":false,\"text\":\"Empezaba á menguar la sangrienta luna de los almoravides[14]; el califato de Córdoba se habia hundido; la guerra civil le despedazaba: los Almohades[15] predicando su doctrina religiosa que los almoravides llamaban herética, habian irrumpido de Africa sobre España, y Lotawak-Aben-Hud, último de los emires almoravides, luchaba con todas sus fuerzas.\"},{\"heading\":false,\"text\":\"Al-Hhamar sirvió á Aben-Hud, pero muy pronto volvió las armas contra él: tomó á Jaen por asalto, se apoderó de Arjona, de Guadix, de Baeza, y se hizo proclamar en los pueblos sujetos á su señorío, sultan y altísimo emir de los fieles[16].\"},{\"heading\":false,\"text\":\"Quedóse aislado Aben-Hud.\"},{\"heading\":false,\"text\":\"En aquellas circunstancias los reyes de Castilla y de Aragon, don Fernando el Santo y don Jaime el Conquistador, emprendieron á un tiempo su espedicion de conquista sobre los moros, el uno por la parte de Andalucía, el otro por la de Valencia.\"},{\"heading\":false,\"text\":\"Sorprendida Córdoba en una lluviosa noche de invierno, por Domingo Muñoz, alcaide de Andujar, vé ocupado su barrio de la Ajarquia[17] sin poder echar de él á los audaces cristianos que se han fortalecido dentro de la ciudad. Avisan á Aben-Hud para que acuda con su ejército, pero ha acudido antes el rey de Castilla. La traicion de un prisionero castellano que Aben-Hud envia á reconocer al ejército enemigo, le hace creer que las fuerzas de este son infinitamente superiores á las suyas, y se retira dejando en libertad á Fernando de estrechar á Córdoba entregada á sí misma.\"},{\"heading\":false,\"text\":\"En su retirada encuentra Aben-Hud á un mensagero del emir de Valencia que le pide auxilio contra el rey de Aragon que le estrecha; se decide Aben-Hud á prestárselo, pero en el camino, una noche en el castillo de Almería, es ahogado por el walí Abderraman, que proclama á Al-Hhamar.\"},{\"heading\":false,\"text\":\"Huérfana Granada asimismo de emir por la muerte de Aben-Hud, proclama al afortunado caudillo, y encuéntrase por lo tanto Al-Hhamar, rey del estado mas considerable de la dominacion musulmana sobre España, despues del califato de Córdoba.\"},{\"heading\":false,\"text\":\"Esta ciudad, Valencia, Murcia y despues Sevilla, han caido en poder de los cristianos, lo que resta á los moros en España, es ya la única y esclusiva monarquia del rey Nazar.\"},{\"heading\":false,\"text\":\"Sin embargo, se vió obligado á aliarse con Fernando III, á ayudarle con un cuerpo de caballería á la conquista de Sevilla, á declararse su vasallo rindiéndole pleito homenage y á pagarle un tributo anual.\"},{\"heading\":false,\"text\":\"Esto no aconteció sino despues de haberse visto obligado Al-Hhamar á rechazar una entrada de los cristianos, y hacer despues levantar el estrecho sitio que puso sobre Granada el mismo Fernando III[18].\"},{\"heading\":false,\"text\":\"Tal era la historia del rey Nazar. Valiente, sabio, religioso, defendió su reino, fundó en él escuelas y mezquitas, y se dedicó á la proteccion de las artes y de la industria.\"},{\"heading\":false,\"text\":\"Sin embargo, este gran rey moraba aun en la antigua casa del Gallo de viento; no tenia un alcázar digno de su grandeza y de su poder; Al-Hhamar-al-Nazar antes que en la suya propia, habia pensado en la felicidad de sus vasallos.\"}]},{\"title\":\"El rey nazar. — capítulo VII: El rey nazar visto por el lado de adentro.\",\"blocks\":[{\"heading\":false,\"text\":\"Habia nacido Al-Hhamar en Arjona, el miércoles 9 de la luna de Xaban[19] del año 591 de la hegira[20]; contaba pues, cuarenta y cinco años en el momento en que le presentamos á nuestros lectores.\"},{\"heading\":false,\"text\":\"Era sin embargo, muy hermoso; sus cejas estaban negrísimas y pobladas y en su larga barba bermeja, semejante al oro, no asomaba una sola cana; sus megillas blancas y brotando el color de la salud, no tenian arrugas; sus ojos brillaban con la fuerza de la juventud y tenian el reflejo de la prudencia: la toca blanca que envolvia su cabeza, dejando ver las puntas de oro de su corona, y su largo caftan negro, daban una gran magestad á su aspecto.\"},{\"heading\":false,\"text\":\"El rey Nazar era todavía hermoso, y sino era jóven no parecia viejo.\"},{\"heading\":false,\"text\":\"Aun podia pensar en el amor.\"},{\"heading\":false,\"text\":\"En amores habia sido muy desgraciado Al-Hhamar.\"},{\"heading\":false,\"text\":\"Su primera esposa, Zobeya, madre del príncipe Mohammet-ebn-Abd-Allah, habia muerto al dar á luz á este príncipe.\"},{\"heading\":false,\"text\":\"La segunda, que no habia sido su esposa, sino su cautiva, su esclava, la princesa Leila-Radhyah, habia desaparecido dejando un rastro de sangre en la casa de Nazar.\"},{\"heading\":false,\"text\":\"La tercera, Wadah, era una muger terrible, una africana hermosísima, madre de su segundo hijo el príncipe Juzef, de la cual hacia mucho tiempo que le tenia apartado una repugnancia invencible, una antipatía mortal.\"},{\"heading\":false,\"text\":\"Wadah, la soberbia africana, le amaba; y sus celos eran un continuo tormento para Al-Hhamar.\"},{\"heading\":false,\"text\":\"Y sin embargo, Wadah no tenia razon alguna para tener celos del rey Nazar.\"},{\"heading\":false,\"text\":\"No amaba á ninguna muger.\"},{\"heading\":false,\"text\":\"Ni aun pasaba de las puertas de su harem.\"},{\"heading\":false,\"text\":\"El rey Nazar hubiera podido pasar por un morabitho[21] á no ser por sus academias con sus sabios y poetas, ó por sus continuas escursiones por sus estados para asegurar con su presencia el amor de sus vasallos y la fidelidad de sus alcaides y walíes.\"},{\"heading\":false,\"text\":\"Gozaba Nazar de una profunda paz como rey: en su reino todo florecia: sus ejércitos eran inumerables: tenia satisfecha su ambicion.\"},{\"heading\":false,\"text\":\"Pero como hombre estaba en una contínua guerra con un deseo misterioso, con una sed no satisfecha: estaba solo en el mundo: el amor de sus hijos no era bastante para satisfacer aquel deseo.\"},{\"heading\":false,\"text\":\"Necesitaba otro amor.\"},{\"heading\":false,\"text\":\"La sultana Wadah no podia tampoco satisfacerlo: un contínuo y sombrio disgusto que se veía impreso en su semblante, y su soberbia siempre provocadora, siempre agresiva, la separaban del rey.\"},{\"heading\":false,\"text\":\"Y luego habia dos fantasmas ardientes en forma de muger que se levantaban dentro de su alma.\"},{\"heading\":false,\"text\":\"Lejano, perdido allá en la inmensidad de los recuerdos el uno; cercano, candente, abrasador, el otro.\"},{\"heading\":false,\"text\":\"La una muger era la sultana Leila-Radhyah.\"},{\"heading\":false,\"text\":\"Al-Hhamar no habia podido olvidarla.\"},{\"heading\":false,\"text\":\"Podia decirse que la sultana Leila-Radhyah habia sido su primer amor.\"},{\"heading\":false,\"text\":\"La habia buscado en vano, en vano habia gastado sus tesoros para descubrir su paradero.\"},{\"heading\":false,\"text\":\"Una circunstancia terrible le hacia recordar de una manera sombría su pérdida.\"},{\"heading\":false,\"text\":\"Durante sus amores con Leila-Radhyah, Al-Hhamar habia contraido con Wadah uno de esos casamientos que se llaman de conveniencia. Wadah era poderosa.\"},{\"heading\":false,\"text\":\"Se la atribuia un poder mágico.\"},{\"heading\":false,\"text\":\"Ya hemos dicho que los moros son muy dados á la supersticion.\"},{\"heading\":false,\"text\":\"Cuando conoció Al-Hhamar á Leila-Radhyah, mejor dicho, cuando se apoderó de ella, era simplemente walí[22]; su cautiva era una doncella de sangre real hija de un poderoso emir de Africa.\"},{\"heading\":false,\"text\":\"Al-Hhamar que al verla habia sentido por ella un amor voráz, necesitando de consuelo por la muerte de su esposa Zobeya, madre del príncipe Mahommet, ni se atrevió á devolver la doncella real á su padre, porque esto era perderla, ni á casarse con ella, porque sabia demasiado que el rey de Tlemcen no se avendria á dar por esposa á un simple walí una sultana hija suya.\"},{\"heading\":false,\"text\":\"La ocultó, pues, en su casa, gozó sus amores, é hizo feliz durante algun tiempo á la pobre jóven que le amaba y todo lo posponia á su amor.\"},{\"heading\":false,\"text\":\"Pero llegó un dia en que Al-Hhamar se casó con Wadah, quedando reducida Leila-Radhyah á la posicion de una concubina, de una esclava que ningun derecho tenia.\"},{\"heading\":false,\"text\":\"Poco despues desapareció como hemos dicho Leila-Radhyah, dejando en su aposento sangrientas señales. El rey la creyó muerta y la lloró.\"},{\"heading\":false,\"text\":\"Aquella misma noche, Al-Hhamar escuchó en las habitaciones de su esposa, la hermosísima Wadah, terribles gritos, gritos semejantes á rugidos de leona.\"},{\"heading\":false,\"text\":\"Cuando entró en aquellas habitaciones, encontró á Wadah medio desnuda, destrenzados los cabellos, delirante, frenética, buscando acá y allá, levantando tapices, asomándose á los ajimeces, mirando al oscuro fondo de los patios y gritando sin intermision:\"},{\"heading\":false,\"text\":\"--¡Asesinos! ¡asesinos! ¡asesinos!\"},{\"heading\":false,\"text\":\"Wadah mostraba en sus manos un pequeño lienzo cuadrado de seda manchado de sangre.\"},{\"heading\":false,\"text\":\"Cuando vió á Al-Hhamar, guardó el paño entre sus ropas descompuestas y lanzó una horrible carcajada.\"},{\"heading\":false,\"text\":\"En vano la preguntó Al-Hhamar acerca de sus gritos, de aquel lienzo ensangrentado, de aquel desvarío: Wadah guardó el mas profundo silencio.\"},{\"heading\":false,\"text\":\"Al dia siguiente Al-Hhamar supo por los alcaides de su harem, que dos esclavos habian desaparecido.\"},{\"heading\":false,\"text\":\"El uno era Leila-Radhyah, el otro un cautivo cristiano.\"},{\"heading\":false,\"text\":\"Wadah desde aquella noche no volvió á sonreirse ni á hablar: amaba á Al-Hhamar con delirio, pero le rechazaba con horror; algunas veces en el mismo punto en que se estremecia de placer entre sus brazos le rechazaba gritando:\"},{\"heading\":false,\"text\":\"--¡Asesino! ¡asesino! ¡asesino!\"},{\"heading\":false,\"text\":\"Al-Hhamar habia llegado á sentir horror hácia Wadah, y á recordar con mas intensidad á su perdida Leila-Radhyah.\"},{\"heading\":false,\"text\":\"La otra muger cuyo recuerdo se levantaba próximo, ardiente, tentador en el alma del rey Nazar era Bekralbayda.\"},{\"heading\":false,\"text\":\"Desde tres dias antes que la habia visto en las fiestas de Alhama no habia podido olvidarla.\"},{\"heading\":false,\"text\":\"Nunca habia sentido un deseo mas exigente.\"},{\"heading\":false,\"text\":\"Aquella niña llenaba su alma, pero sin destruir el amor que sentia hácia Leila-Radhyah.\"},{\"heading\":false,\"text\":\"Habia llamado en vano á Yshac-el-Rumi.\"},{\"heading\":false,\"text\":\"Yshac le habia contestado:\"},{\"heading\":false,\"text\":\"--Aun no es tiempo.\"},{\"heading\":false,\"text\":\"--¿Pero de qué familia es esa niña?\"},{\"heading\":false,\"text\":\"--No es tiempo, replicaba Yshac.\"},{\"heading\":false,\"text\":\"--¿Es libre ó esclava? añadia el rey.\"},{\"heading\":false,\"text\":\"Y como si solo se hubiera provisto de una sola respuesta Yshac, repetia:\"},{\"heading\":false,\"text\":\"--Aun no es tiempo.\"},{\"heading\":false,\"text\":\"Y sin pronunciar otra palabra el sabio se despidió del rey, dejándole envenenada el alma.\"},{\"heading\":false,\"text\":\"Por eso el rey se paseaba triste, sombrío, apenado, por una de las estensas y sonoras cámaras de su palacio del Gallo de viento.\"},{\"heading\":false,\"text\":\"Por eso de tiempo en tiempo murmuraba exhalando un profundo suspiro:\"},{\"heading\":false,\"text\":\"--¡Aun no es tiempo que yo sea feliz!\"}]},{\"title\":\"El rey nazar. — capítulo VIII: La venta de una muger.\",\"blocks\":[{\"heading\":false,\"text\":\"Era ya tarde.\"},{\"heading\":false,\"text\":\"En medio de su distraccion escuchó el rey Nazar el ruido sonoro de las pisadas de alguno que se acercaba.\"},{\"heading\":false,\"text\":\"Entonces compuso su semblante para que nadie pudiese comprender por él lo que pasaba en su alma.\"},{\"heading\":false,\"text\":\"Levantóse el tapiz de una puerta, y un esclavo negro magníficamente vestido con un sayo de escarlata y con una argolla de oro al cuello, se prosternó y dijo con voz gutural y respetuosa:\"},{\"heading\":false,\"text\":\"--¡Magnífico sultan de los creyentes! un viejo enlutado solicita arrojarse á tus plantas: dice que vá en ello mas de lo que puede pensarse.\"},{\"heading\":false,\"text\":\"Al oir el rey Nazar que le buscaba un hombre enlutado, se apresuró á mandarle introducir, lo que en aquella hora no hubiese hecho por nadie, ni aun por sus mismos hijos.\"},{\"heading\":false,\"text\":\"Entró en la cámara algun tiempo despues un hombre alto, pálido, enteramente cubierto por un turbante blanco, y por un ancho alquicel, blanco tambien, sin dejar descubierto mas que un semblante huesoso en cuyas profundas órbitas se revolvian dos ojos brillantes como carbunclos.\"},{\"heading\":false,\"text\":\"Aquel hombre no se prosternó ante el rey Nazar: por el contrario adelantó hácia él, rígido, enhiesto, sin producir ruido al andar, como un fantasma, y con la mirada candente y fija en el rey Nazar, que retrocedió.\"},{\"heading\":false,\"text\":\"--¡No me conoces, Al-Hhamar, el vencedor y el magnífico! dijo deteniéndose á poca distancia del rey.\"},{\"heading\":false,\"text\":\"--Tú eres el viejo que acompañaba á la doncella blanca, dijo el rey Nazar sin poder dominar su fascinacion.\"},{\"heading\":false,\"text\":\"--Sí, yo soy el astrólogo Yshac, contestó aquel hombre permaneciendo inmóvil en el sitio donde se habia parado.\"},{\"heading\":false,\"text\":\"--Tú eres el que me dijiste, cuando yo te ofrecia montañas de oro por la doncella blanca: aun no es tiempo.\"},{\"heading\":false,\"text\":\"--Yo soy.\"},{\"heading\":false,\"text\":\"--¿Y á qué vienes?\"},{\"heading\":false,\"text\":\"--Vengo á venderte á Bekralbayda.\"},{\"heading\":false,\"text\":\"--¡A vendérmela! pide cuanto desees, cuanto quieras.\"},{\"heading\":false,\"text\":\"--Yo no quiero dinero.\"},{\"heading\":false,\"text\":\"--¿Qué quieres pues?\"},{\"heading\":false,\"text\":\"--Dos cosas solas.\"},{\"heading\":false,\"text\":\"--Habla.\"},{\"heading\":false,\"text\":\"--Quiero que Bekralbayda sea doncella de tu esposa.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡poner junto á la terrible Wadah, á ese arcángel del sétimo cielo! ¿Sabes tú quién es Wadah?\"},{\"heading\":false,\"text\":\"--Soy astrólogo y mago: lo sé.\"},{\"heading\":false,\"text\":\"Tembló imperceptiblemente el rey Nazar.\"},{\"heading\":false,\"text\":\"Ni uno ni otro se habian movido del sitio donde se habian parado.\"},{\"heading\":false,\"text\":\"Vistos á cierta distancia parecian dos sombras; la una blanca, y la otra negra, que no se atrevian á unirse, que se rechazaban.\"},{\"heading\":false,\"text\":\"--¿Sabes que la sultana Wadah está loca?\"},{\"heading\":false,\"text\":\"--Lo sé.\"},{\"heading\":false,\"text\":\"Por un cambio natural en la disposicion del ánimo del rey, preguntó con ansia á Yshac.\"},{\"heading\":false,\"text\":\"--¿Sabes por qué causa está loca la sultana?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--Dímelo.\"},{\"heading\":false,\"text\":\"--Aun no es tiempo.\"},{\"heading\":false,\"text\":\"El rey se estremeció de nuevo.\"},{\"heading\":false,\"text\":\"--¿Y sabiendo que está loca la sultana quieres poner á su lado á Bekralbayda?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Pero cómo pueden satisfacerse mis amores estando Bekralbayda al lado de la sultana?\"},{\"heading\":false,\"text\":\"--Ese es negocio tuyo.\"},{\"heading\":false,\"text\":\"--¿Y qué mas quieres para entregarme esa doncella aunque sea de ese modo?\"},{\"heading\":false,\"text\":\"--Ser tu astrólogo: vivir en tu alcázar.\"},{\"heading\":false,\"text\":\"--¡Y nada mas pides! esclamó con asombro el rey Nazar.\"},{\"heading\":false,\"text\":\"--Nada mas quiero, contestó con voz cavernosa el astrólogo.\"},{\"heading\":false,\"text\":\"--Puedes traer mañana á Bekralbayda al alcázar.\"},{\"heading\":false,\"text\":\"--Pues bien; mañana la traeré. A Dios.\"},{\"heading\":false,\"text\":\"Y salió tan silenciosamente como habia entrado, dejando fascinado y mudo al rey Nazar.\"}]},{\"title\":\"El rey nazar. — capítulo IX: De cómo el príncipe mohammet estuvo á punto de ser ahorcado por ladron.\",\"blocks\":[{\"heading\":false,\"text\":\"Bekralbayda era feliz.\"},{\"heading\":false,\"text\":\"Es verdad que aun no sabia el nombre de sus padres, pero sabia el de su amado.\"},{\"heading\":false,\"text\":\"Las sombras y el silencio habian protegido el delirio de sus amores con el príncipe.\"},{\"heading\":false,\"text\":\"El príncipe, por su parte no podia ser tampoco mas feliz: la muger de su amor era suya en cuerpo y en alma.\"},{\"heading\":false,\"text\":\"Los dos amantes se habian separado antes del amanecer, dándose cita para la noche siguiente.\"},{\"heading\":false,\"text\":\"Yshac-el-Rumi habia pasado la noche en vela, inmóvil, apoyado en el alfeizar del ajimez.\"},{\"heading\":false,\"text\":\"La dama blanca habia dado salida al príncipe por el portillo de una cerca.\"},{\"heading\":false,\"text\":\"Bekralbayda, embellecida por un nuevo encanto, se habia dirigido á su retrete, se habia arrojado en su lecho y habia dormido un sueño de amores.\"},{\"heading\":false,\"text\":\"El príncipe se habia encaminado á la Colina Roja, y se habia ocultado en las ruinas del templo de Diana.\"},{\"heading\":false,\"text\":\"Pero antes de entrar en ellas, habia arrojado una mirada al frontero Albaicin á la casa del Gallo de viento, y habia esclamado al ver el reflejo de una luz en un ajimez del retrete del rey Nazar:\"},{\"heading\":false,\"text\":\"--¿Porqué velará á estas horas mi padre?\"},{\"heading\":false,\"text\":\"Pasó el dia: un diáfano y radiante dia de primavera.\"},{\"heading\":false,\"text\":\"Llegó la noche.\"},{\"heading\":false,\"text\":\"Una noche serena, lánguida, tranquila, sin luna, pero dulce y misteriosamente alumbrada por los luceros.\"},{\"heading\":false,\"text\":\"El príncipe salió de las ruinas del templo, bajó á la márgen del rio y se encaminó á la casita blanca del remanso.\"},{\"heading\":false,\"text\":\"A la casita donde, sin duda, impaciente y estremecida de amor como él, le esperaba Bekralbayda.\"},{\"heading\":false,\"text\":\"Pero esperó una hora y nada interrumpió el silencio y la soledad de aquellos lugares.\"},{\"heading\":false,\"text\":\"Pasó aun mas tiempo y nadie vino á llevar al príncipe junto á su amor.\"},{\"heading\":false,\"text\":\"Encaminóse á la oscura gruta y penetró en ella, pero en vano procuró dar con la pendiente entrada por donde habia resvalado la noche antes, y que le habia llevado al palacio de la dama blanca.\"},{\"heading\":false,\"text\":\"Por todas partes, en todas direcciones, encontraba la roca tajada, áspera, húmeda y nada mas.\"},{\"heading\":false,\"text\":\"--¿Me habré engañado? se preguntó.\"},{\"heading\":false,\"text\":\"Y volvió á salir.\"},{\"heading\":false,\"text\":\"Pero aquella era la estrecha grieta cubierta de maleza por donde habia penetrado la noche anterior.\"},{\"heading\":false,\"text\":\"Para confirmarle en ello estaban allí las ramas que habia cortado con su yatagan para abrirse paso.\"},{\"heading\":false,\"text\":\"Sin embargo, aunque penetró una y otra vez, solo halló una estrecha escavacion en la roca, en la cual no habia ninguna abertura.\"},{\"heading\":false,\"text\":\"Desesperado, abandonó aquel lugar y subió á las cortaduras del rio y rodeó por los cármenes, buscando el postigo por donde le habia dado salida la dama blanca.\"},{\"heading\":false,\"text\":\"Pero no halló la cerca.\"},{\"heading\":false,\"text\":\"En cambio se perdió en un laberinto de enramadas, que se intrincaban mas á medida que el príncipe se revolvia mas en ellas.\"},{\"heading\":false,\"text\":\"Llegó un punto en que quiso salir y no pudo. No encontraba la salida, ni aun lograba dar con el rio cuya corriente le habia guiado.\"},{\"heading\":false,\"text\":\"--¿Habrá aquí algun encantamento? dijo.\"},{\"heading\":false,\"text\":\"Y apenas habia hecho esta esclamacion, cuando oyó un ronco ladrido, y poco despues se vió acometido por un enorme perro campestre y por una ronda de labradores armados de chuzos, uno de los cuales llevaba una linterna.\"},{\"heading\":false,\"text\":\"Cuando esto acontecia habia pasado ya largo tiempo. Era la media noche.\"},{\"heading\":false,\"text\":\"--Hé aquí el ladron de nuestras hortalizas...\"},{\"heading\":false,\"text\":\"--El talador de nuestras flores.\"},{\"heading\":false,\"text\":\"--El caballero que se divierte en matar nuestros perros y seducir nuestras hijas, esclamaron en coro aquellos hombres, con gran sorpresa del admirado príncipe.\"},{\"heading\":false,\"text\":\"La verdad del caso era, que como aquellos honrados labriegos tenian mugeres y parientas hermosas, algunos jóvenes caballeros habian dado en la flor de ir á meterse en vedado por aquellos frondosos cármenes, pisando las flores que encontraban á su paso, pero con la cautela y la malicia del ladron, favorecidos por alguna de las flores pisadas, y el príncipe Mohammet pagaba sin culpa las culpas de otros.\"},{\"heading\":false,\"text\":\"--¿Qué decis de vuestras flores y de vuestras hijas? dijo el príncipe: yo no vengo ni por las unas ni por las otras: me hé perdido en vuestros cármenes y os ruego que me saqueis de ellos.\"},{\"heading\":false,\"text\":\"--¿Qué te saquemos? pues ya se vé que te sacaremos: esclamaron los rústicos, pero será para llevarte preso al rey que nos hará justicia.\"},{\"heading\":false,\"text\":\"Estremecióse el príncipe.\"},{\"heading\":false,\"text\":\"--Vosotros no hareis eso, dijo, cuando sepais quién soy yo.\"},{\"heading\":false,\"text\":\"--Seas quien fueres, por ladron te tenemos ¿no has pasado nuestros términos de noche sin nuestra licencia?\"},{\"heading\":false,\"text\":\"--Yo no he encontrado cerca alguna.\"},{\"heading\":false,\"text\":\"--Tu has escalado la cerca: por lo mismo morirás ahorcado.\"},{\"heading\":false,\"text\":\"En efecto el príncipe habia saltado una pequeña tapia.\"},{\"heading\":false,\"text\":\"--¿Y para qué queremos llevarle al rey? dijo otro: nosotros podemos ahorcarle, ¿acaso no es un ladron armado? ¿no sabeis que el que coje á un ladron armado puede ahorcarle allí donde le pille?\"},{\"heading\":false,\"text\":\"--Pero yo no he hecho resistencia: esclamó el príncipe.\"},{\"heading\":false,\"text\":\"--¿Y quién sabe si la has hecho ó no? ¿lo dirás tú despues de muerto?\"},{\"heading\":false,\"text\":\"--Si vosotros me ahorcárais, mi padre os descuartizaria vivos, contestó con altivez el príncipe.\"},{\"heading\":false,\"text\":\"--Es que nosotros tenemos un padre que nos defenderá del tuyo por poderoso que sea: porque nuestro padre es el poderoso y justiciero rey Nazar.\"},{\"heading\":false,\"text\":\"--Pues bien de rodillas ante su hijo el príncipe Mohammet, dijo con altivez el jóven.\"},{\"heading\":false,\"text\":\"--¿Tú el príncipe Mohammet, el valiente y virtuoso hijo del rey Nazar? dijeron los rústicos: no puede ser; ¿qué tiene que buscar nuestro buen príncipe por estos sitios y á estas horas?\"},{\"heading\":false,\"text\":\"--Es un mal caballero que miente por salvarse.\"},{\"heading\":false,\"text\":\"--Un burlador de la justicia del rey y de nuestra honra.\"},{\"heading\":false,\"text\":\"--Un libertino.\"},{\"heading\":false,\"text\":\"--Un infame.\"},{\"heading\":false,\"text\":\"--Ahorquémosle.\"},{\"heading\":false,\"text\":\"--No; casémosle con la muger que vendrá á buscar y que sin duda es hija de uno de nosotros.\"},{\"heading\":false,\"text\":\"--Yo no conozco á vuestras hijas: os repito que soy el príncipe Mohammet.\"},{\"heading\":false,\"text\":\"--Pues bien; te llevaremos al rey, y el rey dirá si eres príncipe ó no.\"},{\"heading\":false,\"text\":\"Y arremetiendo á él, y sin que el príncipe pudiera valerse, le arrastraron consigo, le llevaron al otro lado del rio, y por el camino y la puerta de Guadix le metieron en el Albaicin.\"}]},{\"title\":\"El rey nazar. — capítulo X: La torre del gallo de viento.\",\"blocks\":[{\"heading\":false,\"text\":\"Aun velaba el rey la misma noche en que habia dado audiencia á Yshac, cuando un esclavo, el mismo que le habia anunciado la llegada del astrólogo, le anunció que unos labradores traian preso al príncipe Mohammet.\"},{\"heading\":false,\"text\":\"Porque el príncipe habia sido reconocido en el alcázar, y se habia detenido á los labradores, que estaban aterrados por su torpeza en haber preso al príncipe.\"},{\"heading\":false,\"text\":\"Nublóse el semblante de Al-Hhamar.\"},{\"heading\":false,\"text\":\"Era el primer disgusto que le daba su hijo.\"},{\"heading\":false,\"text\":\"Mandó que introdujesen al príncipe y los labradores.\"},{\"heading\":false,\"text\":\"El príncipe se presentó confuso.\"},{\"heading\":false,\"text\":\"Los labradores aterrados se arrojaron á los pies del rey Nazar.\"},{\"heading\":false,\"text\":\"--Perdon, señor, perdon, esclamaron: nosotros no conocíamos al esclarecido príncipe, tu hijo.\"},{\"heading\":false,\"text\":\"--El nos dijo quien era.\"},{\"heading\":false,\"text\":\"--Pero nosotros no le creimos.\"},{\"heading\":false,\"text\":\"--Porque los caballeros de Granada se entran de noche en nuestros cármenes.\"},{\"heading\":false,\"text\":\"--Y nos roban las flores...\"},{\"heading\":false,\"text\":\"--Las flores de nuestra alma.\"},{\"heading\":false,\"text\":\"--Nuestras esposas y nuestras hijas.\"},{\"heading\":false,\"text\":\"--Y creimos que el príncipe fuera uno de estos ladrones.\"},{\"heading\":false,\"text\":\"--Porque le encontramos dentro de nuestros cármenes.\"},{\"heading\":false,\"text\":\"--Que están cercados.\"},{\"heading\":false,\"text\":\"--Que están guardados.\"},{\"heading\":false,\"text\":\"--Nosotros no sabiamos que era el príncipe.\"},{\"heading\":false,\"text\":\"Impuso el rey Nazar silencio á los labradores, que hablaban á un tiempo y en coro, impulsados por el miedo, y preguntó á su hijo:\"},{\"heading\":false,\"text\":\"--¿Es cierto lo que estos dicen?\"},{\"heading\":false,\"text\":\"--Me han encontrado en los cármenes, señor, contestó el jóven.\"},{\"heading\":false,\"text\":\"--¿De noche y armado?\"},{\"heading\":false,\"text\":\"--Si señor.\"},{\"heading\":false,\"text\":\"--¡Idos! dijo el rey á los labradores.\"},{\"heading\":false,\"text\":\"Estos no esperaron á que el rey repitiese su mandato, y salieron en tropel como una jauria espantada, no sin sufrir algunos latigazos de los esclavos y de los soldados en su tránsito por el alcázar.\"},{\"heading\":false,\"text\":\"El rey Nazar se habia quedado solo con el príncipe, y le miraba ceñudo.\"},{\"heading\":false,\"text\":\"--¿No estabas en mi castillo real de Alhama? dijo al fin Al-Hhamar.\"},{\"heading\":false,\"text\":\"--Si señor, constestó el príncipe.\"},{\"heading\":false,\"text\":\"--¿No te habia mandado que no vinieses á Granada?\"},{\"heading\":false,\"text\":\"--Si señor.\"},{\"heading\":false,\"text\":\"--¿Por qué has venido? ¿qué causa grave tienes que alegar en tu disculpa?\"},{\"heading\":false,\"text\":\"El príncipe sabia que su padre estaba enamorado de Bekralbayda, y no se atrevió á confesar la verdad.\"},{\"heading\":false,\"text\":\"--Tu hijo no tiene disculpa ninguna, poderoso sultan de los creyentes, contestó.\"},{\"heading\":false,\"text\":\"--Si uno de tus walíes abandonase un gobierno que tú le hubieses encomendado, si su gobierno estuviese en la frontera enemiga, ¿qué harias?\"},{\"heading\":false,\"text\":\"--Mandaria cortar la cabeza al walí, contestó con mesura, pero con firmeza el príncipe.\"},{\"heading\":false,\"text\":\"--¿Porque el walí habria sido traidor y rebelde?\"},{\"heading\":false,\"text\":\"--Si señor.\"},{\"heading\":false,\"text\":\"--¿Tú eres príncipe: tú eres mi compañero en el mando? tú eres casi el sultan de Granada: tu culpa por lo mismo es mayor. ¿A qué has venido á Granada?\"},{\"heading\":false,\"text\":\"--Estaba triste en Alhama.\"},{\"heading\":false,\"text\":\"--¿Y tienes aquí tu alegría?\"},{\"heading\":false,\"text\":\"--Si señor.\"},{\"heading\":false,\"text\":\"--¿Y... tu alegría cómo se llama?\"},{\"heading\":false,\"text\":\"--Mi alegría no tiene nombre.\"},{\"heading\":false,\"text\":\"--¿Pero por qué has venido á Granada desobedeciéndome? ¿por qué has abandonado mi estandarte en la frontera?\"},{\"heading\":false,\"text\":\"--Por respirar las auras de la noche en los cármenes del Darro.\"},{\"heading\":false,\"text\":\"--¡Oh! yo sabré tu secreto, dijo el rey.\"},{\"heading\":false,\"text\":\"Y llamando á dos de los mas ancianos y prudentes de sus wazires[23] les mandó que encerrasen al príncipe en lo mas alto de la torre del Gallo de viento.\"},{\"heading\":false,\"text\":\"Esta antiquísima torre, cuadrada, alta, maciza, en la cual no se veia mas que estrechas saeteras y una ventana en cada frente, junto á las almenas, estaba largo tiempo hacia inhabitada y protegida por el terror supersticioso que inspiraba.\"},{\"heading\":false,\"text\":\"Decíase que habitaba en ella el _alma del rey Aben-Habuz el sabio_.\"},{\"heading\":false,\"text\":\"Esta torre estaba situada en el centro de un patio del palacio á que daba nombre, y en su parte inferior no tenia puerta. Entrábase en ella por su altura media, por un pasadizo cubierto, en forma de puente que la unia con uno de los lados del patio.\"},{\"heading\":false,\"text\":\"Aquel pasadizo tenia una puerta de hierro macizo y mohoso, cuyos cerrojos y candados era fama que no se habian abierto en centenares de años. Despues de aquel pasadizo y en el corazon de la torre, que parecia maciza tambien, se retorcia una estrecha escalera de caracol, iluminada apenas por la escasa claridad que penetraba cansada por estrechas y profundísimas saeteras, y en lo mas alto de la torre terminaba la escalera, en una cámara de ocho pies en cuadro, baja de bóveda y envejecida mas que por el tiempo por el humo de un hornillo que se veia como escondido en uno de los rincones.\"},{\"heading\":false,\"text\":\"En esta cámara á nivel del pavimento resquebrajado y sucio, una compuerta de hierro cerraba la escalera, y cuatro ventanas semicirculares se abrian en direccion á los cuatro puntos cardinales.\"},{\"heading\":false,\"text\":\"Además del centro ó clave de la bóveda descendia hasta la parte media de la altura de la cámara un eje de hierro, del que estaba suspendido un pequeño ginete de hierro tambien, con el caballo en actitud de correr y con la lanza baja.\"},{\"heading\":false,\"text\":\"Aquel eje se volvia obedeciendo á la veleta de la parte superior, y la punta de la lanza del caballero señalaba á la parte donde iba el viento.\"},{\"heading\":false,\"text\":\"Contábanse de esta torre cosas estupendas: decian que algunas noches se veia por sus altísimas ventanas un resplandor rojo como de infierno, y por entre sus almenas un humo luminoso: y de lo que mas se hablaba, era de un buho enormísimo, tan grande como la mas grande águila que anidaba junto á las almenas; y á propósito del resplandor, y del humo, y del buho, se contaban tales cosas, que bastaban para aterrar á los muchachos y hacerlos callar cuando se obstinaban en el llanto, para lo que tambien bastaba nombrar simplemente el alma de Aben-Habuz, fundador de la torre y del palacio que tenia á sus pies.\"},{\"heading\":false,\"text\":\"Por una coincidencia singular, el patio en que esta torre se levantaba, era el mas alegre y bello del palacio: esbeltas columnitas sostenian sus galerías, flores, fuentes y estanques se veian en su terreno, y en él vagaban las hermosas esclavas de la servidumbre de la sultana Wadah.\"},{\"heading\":false,\"text\":\"Porque en aquel patio estaban las habitaciones de la esposa del rey Nazar.\"},{\"heading\":false,\"text\":\"Veíase, además desde las ventanas de la torre toda Granada, la Vega, las sierras hasta los distantes confines: en una palabra, aquella torre era una escelente atalaya.\"},{\"heading\":false,\"text\":\"Los wazires condujeron hasta allí con un profundo respeto al príncipe, y este, que al asomarse á una ventana habia visto la Colina Roja, dijo á los wazires:\"},{\"heading\":false,\"text\":\"--Ahí, en el cercano monte, en las ruinas del templo romano, está mi caballo: no es justo que dejemos perecer á nuestro compañero de batalla; haced que le vayan á buscar.\"},{\"heading\":false,\"text\":\"Los wazires se inclinaron profundamente, y salieron dejando solo al príncipe, que á los primeros rayos del sol de la mañana se puso á contemplar desde su altura el estrecho valle por donde el Darro atravesaba á Granada.\"},{\"heading\":false,\"text\":\"Porque en las márgenes del Darro, moraba su vida y la mitad de su alma: Bekralbayda.\"}]},{\"title\":\"El rey nazar. — capítulo XI: De cómo el rey nazar comprendió que no podia ser feliz.\",\"blocks\":[{\"heading\":false,\"text\":\"Al-Hhamar habia quedado profundamente triste.\"},{\"heading\":false,\"text\":\"A la tristeza por sus amores, se unia la que le causaba la rebeldía de su hijo.\"},{\"heading\":false,\"text\":\"Porque su hijo (sus ojos de padre se lo habian dicho) guardaba dentro de su alma un secreto.\"},{\"heading\":false,\"text\":\"¿Y qué secreto era este que no queria revelar á su padre?\"},{\"heading\":false,\"text\":\"Y mientras el rey Nazar se deshacia en conjeturas, la solucion del secreto entraba en su palacio con el caballo del príncipe, que los wazires habian ido á recojer en persona á la Colina Roja.\"},{\"heading\":false,\"text\":\"Uno de los wazires se presentó al rey.\"},{\"heading\":false,\"text\":\"Llevaba en las manos unas pequeñas pero pesadas alforjas de seda, bordadas, en cuyas bolsas se contenia sin duda dinero.\"},{\"heading\":false,\"text\":\"--Esto hemos encontrado sobre el caballo del príncipe, señor, dijo el wazir presentando las alforjas á Al-Hhamar.\"},{\"heading\":false,\"text\":\"El rey puso las alforjas sobre el divan y despidió al wazir.\"},{\"heading\":false,\"text\":\"Apenas se vió solo examinó con una impaciencia febril las dos bolsas de las alforjas; por su contenido esperaba deducir el objeto de la secreta venida del príncipe á Granada.\"},{\"heading\":false,\"text\":\"Pero solo encontró una razonable cantidad de _dirahmes_[24] de plata, lo que bastaba para un caballero, pero que era insuficiente para pagar una rebeldia: además encontró un pequeño envoltorio de seda.\"},{\"heading\":false,\"text\":\"Dentro de él halló dos cartas y un rizo do cabellos negros, sedosos, brillantes, largos, pesados, que exhalaban un delicioso perfume.\"},{\"heading\":false,\"text\":\"--¡Ha venido á Granada por una muger! ¡ama! ¿pero quién es esa muger? ruin debe ser cuando me la recata: estas cartas me lo dirán:\"},{\"heading\":false,\"text\":\"Abrió la primera que estaba escrita en verso y decia así:\"},{\"heading\":false,\"text\":\"«La perla de las perlas, la cándida y la pura...»\"},{\"heading\":false,\"text\":\"Era en fin la carta que el príncipe habia encontrado en su retrete en Alhama, la que le habia servido de medio para encontrar á Bekralbayda.\"},{\"heading\":false,\"text\":\"La segunda carta mas esplícita, era la que habia sido enviada al príncipe en su misma flecha desde la casita blanca.\"},{\"heading\":false,\"text\":\"Al leer el nombre de Bekralbayda que firmaba esta carta, el rey se sintió herido en el corazon.\"},{\"heading\":false,\"text\":\"--¡Con que se aman! esclamó: y acaso, acaso... sí... indudablemente: esta carta es una cita: y luego este rizo de cabellos...\"},{\"heading\":false,\"text\":\"El rey quedó profundamente pensativo, y se puso á pasear á largos pasos á lo largo de su cámara.\"},{\"heading\":false,\"text\":\"--Pero ellos no han podido conocerse, no han podido verse sino consintiéndolo ese viejo enlutado, ese Yshac-el Rumi, ese hombre estraño que me hace temblar. Pero si ese miserable sabe que mi hijo y Bekralbayda son amantes, ¿por qué me vende esa muger? ¡y con tan estrañas condiciones! no me ha pedido oro... únicamente que Bekralbayda esté al lado de la sultana Wadah, de esa terrible loca, y estar él á mi lado, ser mi astrólogo: ¡oh poderoso señor de Ismael! ¡tú dador de la ciencia! ¡tú misericordioso! aquí hay un misterio que no alcanzo á esplicarme: ¡ilumíname tú, señor, tú que amparas á los que en tí creen!... ¡ábreme camino, porque yo me siento cegar!\"},{\"heading\":false,\"text\":\"Y el rey siguió en su paseo, con la mirada escandecida, el aliento ardiente y entrecortado, las megillas pálidas, el paso incierto.\"},{\"heading\":false,\"text\":\"Luchaba dentro de sí de una manera espantosa.\"},{\"heading\":false,\"text\":\"--¡Oh? dijo al fin: Dios castiga en mí algun pecado de mi raza: yo no puedo ser feliz.\"},{\"heading\":false,\"text\":\"Y siguió paseando.\"},{\"heading\":false,\"text\":\"--¿Y por qué no? dijo de repente: ¿quién sabe? acaso...\"},{\"heading\":false,\"text\":\"El rey volvió á su paseo.\"},{\"heading\":false,\"text\":\"Anunciáronle que un viejo y una dama enlutados querian hablarle.\"},{\"heading\":false,\"text\":\"El rey Nazar hizo un movimiento semejante al de quien despierta de un sueño al impulso de una mano estraña; tomó un pergamino y escribió en él durante un breve espacio: luego dobló el pergamino y le selló.\"},{\"heading\":false,\"text\":\"--Que entren el viejo y la muger, dijo.\"},{\"heading\":false,\"text\":\"Poco despues entró Yshac-el-Rumi llevando de la mano y sin velo á Bekralbayda que inclinaba ruborosa la cabeza.\"},{\"heading\":false,\"text\":\"Entrambos se prosternaron ante el rey Nazar que los alzó.\"},{\"heading\":false,\"text\":\"--¿Sabes á lo que vienes á mi palacio? le preguntó Al-Hhamar.\"},{\"heading\":false,\"text\":\"--Sé que me han vendido al poderoso sultan de Granada, dijo con acento trémulo Bekralbayda.\"},{\"heading\":false,\"text\":\"--¿Pero no te han dicho que el sultan Nazar que te ama, quiere tu amor y no tu sumision?\"},{\"heading\":false,\"text\":\"Bekralbayda calló.\"},{\"heading\":false,\"text\":\"--Vas á servir á la poderosa sultana Wadah: está enferma: procura aliviar con tus consuelos sus dolencias: en cuanto á mí en ocasion mejor te diré cuánto eres grata á mis ojos. Entre tanto pon aquí tu nombre.\"},{\"heading\":false,\"text\":\"El rey la presentó el pergamino que habia escrito y sellado poco antes.\"},{\"heading\":false,\"text\":\"--¿Y qué es esto, señor? dijo con recelo Yshac-el-Rumi.\"},{\"heading\":false,\"text\":\"--Aquí, salva la voluntad de Dios, está decretado invariablemente el destino de Bekralbayda. Sellado con mi sello, signado con su nombre, nadie abrirá ese pergamino hasta que ella misma le abra.\"},{\"heading\":false,\"text\":\"Y llamando el rey á sus esclavos les mandó que llevasen á Bekralbayda á las habitaciones de su esposa.\"},{\"heading\":false,\"text\":\"Yshac-el-Rumi se quedó entre los sabios y astrólogos que vivian en el palacio del rey.\"}]},{\"title\":\"El rey nazar. — capítulo XII: El palacio de rubies.\",\"blocks\":[{\"heading\":false,\"text\":\"Habian pasado muchos dias.\"},{\"heading\":false,\"text\":\"El rey habia tenido muchas entrevistas con Bekralbayda.\"},{\"heading\":false,\"text\":\"El príncipe continuaba preso.\"},{\"heading\":false,\"text\":\"Yshac-el-Rumi empezaba por su ciencia á privar con el rey.\"},{\"heading\":false,\"text\":\"Ninguno mejor que él descifraba los sueños del rey, ni respondia mejor á sus dudas.\"},{\"heading\":false,\"text\":\"El rey Nazar empalidecia.\"},{\"heading\":false,\"text\":\"Comprendíase que minaba algo su existencia.\"},{\"heading\":false,\"text\":\"Sus ojos empezaban á tener cierto brillo fosforescente como los de la sultana Wadah.\"},{\"heading\":false,\"text\":\"Dormia poco, y aun así de una manera inquieta.\"},{\"heading\":false,\"text\":\"En medio de sus sueños, quien hubiera estado cerca de él, le hubiera oido pronunciar el nombre de su hijo y de Bekralbayda.\"},{\"heading\":false,\"text\":\"Una noche el rey velaba.\"},{\"heading\":false,\"text\":\"Tenia junto á sí en una pequeña mesa un cuadrante y un pergamino estendido.\"},{\"heading\":false,\"text\":\"El rey marcaba con tinta roja sobre el pergamino líneas y compartimientos, los media con un compás, y volvia á meditar y á marcar líneas y puntos y á tomar medidas.\"},{\"heading\":false,\"text\":\"Quien le hubiera visto entonces, no le hubiera creido el sultan de Granada, el poderoso Nazar, sino un alarife[25] que se ocupaba en formar el plano de un palacio.\"},{\"heading\":false,\"text\":\"El rey se ocupaba profundamente de su trabajo.\"},{\"heading\":false,\"text\":\"Pero de repente le interrumpió un ruido inesperado.\"},{\"heading\":false,\"text\":\"El batir de las alas de un pájaro.\"},{\"heading\":false,\"text\":\"El rey Nazar se estremeció y miró.\"},{\"heading\":false,\"text\":\"Vió un enorme buho que revolaba en su cámara.\"},{\"heading\":false,\"text\":\"El rey Nazar se puso mortalmente pálido, y se levantó en busca de su arco.\"},{\"heading\":false,\"text\":\"Pero el buho estrechó su vuelo sobre la mesa, apagó la lámpara y escapó por la ventana.\"},{\"heading\":false,\"text\":\"Entonces resonó á alguna distancia una carcajada hueca.\"},{\"heading\":false,\"text\":\"El rey Nazar dió voces: entraron sus esclavos con luces.\"},{\"heading\":false,\"text\":\"El rey Nazar hizo que encendiesen la lámpara, que cerrasen las celosías de los ajimeces y las puertas, y que trajesen al momento al astrólogo Yshac-el-Rumi.\"},{\"heading\":false,\"text\":\"Poco despues el viejo estaba delante del rey Nazar y á solas con él.\"},{\"heading\":false,\"text\":\"--Siéntate, le dijo el rey.\"},{\"heading\":false,\"text\":\"El astrólogo se sentó con la misma altivez que si hubiera sido otro rey.\"},{\"heading\":false,\"text\":\"--¿Sabes lo que me sucede? le dijo.\"},{\"heading\":false,\"text\":\"--Yo lo sé todo, dijo con autoridad el mago.\"},{\"heading\":false,\"text\":\"--Veamos.\"},{\"heading\":false,\"text\":\"--En primer lugar estás cada dia mas embriagado por los encantos de Bekralbayda.\"},{\"heading\":false,\"text\":\"--Es verdad.\"},{\"heading\":false,\"text\":\"--La sultana Wadah lo sabe y tiene celos.\"},{\"heading\":false,\"text\":\"--Es cierto.\"},{\"heading\":false,\"text\":\"--Bekralbayda quiere antes de ser tuya poner á prueba tu amor.\"},{\"heading\":false,\"text\":\"--¿Y me exige grandes sacrificios?\"},{\"heading\":false,\"text\":\"--Sé que á pretesto de que este palacio es triste, en lo que no la falta razon, te ha pedido que construyas para ella sola un alcázar.\"},{\"heading\":false,\"text\":\"--Es verdad.\"},{\"heading\":false,\"text\":\"--Tú te has puesto esta noche, poderoso sultan, á idear ese alcázar, y un buho ha entrado por la ventana y ha apagado la lámpara.\"},{\"heading\":false,\"text\":\"--¿Y por qué ese buho?...\"},{\"heading\":false,\"text\":\"--Porque ese buho quiere que ese alcázar se construya en el lugar donde está construido invisiblemente, el encantado Palacio-de-Rubíes.\"},{\"heading\":false,\"text\":\"--¡El Palacio-de-Rubíes!\"},{\"heading\":false,\"text\":\"--Sí, en la Colina Roja.\"},{\"heading\":false,\"text\":\"--Esplícame, esplícame eso.\"},{\"heading\":false,\"text\":\"--Escucha.\"},{\"heading\":false,\"text\":\"Reclinóse el astrólogo indolentemente en el divan, y empezó despues de algun tiempo de meditacion de esta manera:\"},{\"heading\":false,\"text\":\"--Allá en los primeros años despues de la conquista de los árabes sobre España, era señor de Granada Abu-Mozni-el-Zeirita.\"},{\"heading\":false,\"text\":\"Este rey, siendo ya viejo, murió y dejó su herencia, esto es, el señorío de Granada, á un sobrino suyo, viejo tambien, que residia en Africa, y que se llamaba Aben-Habuz.\"},{\"heading\":false,\"text\":\"Cuando Aben-Habuz vino á Granada á recojer la herencia de su viejísimo tio, solo halló un negro y carcomido castillo, puesto sobre la cima de un monte, al pie de las vertientes de una sierra, y en el castillo algunos cientos de feroces guerreros que miraban el ataud de roble de su señor, apoyados en las picas con la misma espresion que el perro de montería que pierde al amo que le arrojaba sobre el rastro.\"},{\"heading\":false,\"text\":\"Aben-Habuz no conocia á Abu-Mozni, y por lo tanto no se entristeció. Humillóle, sí, que un pariente suyo fuese llevado á la sepultura sin embalsamar y con un ataud y unos vestidos tan humildes, porque Abu-Mozni habia gastado el dinero de sus tierras y de sus vasallos, en perros y murallas, y no habia pensado ni una sola vez en su vida en tener un alcázar ni un harem, ni en proveerse de un lecho de piedra en donde dormir el último sueño.\"},{\"heading\":false,\"text\":\"Aben-Habuz mandó á sus médicos que embalsamasen los restos de su feróz tio: hizo quemar el ataud de roble y el sayo de lana, le encerró vestido de púrpura en un féretro de brocado, dentro de un sepulcro de mármol sobre el cual hizo esculpir un pomposo epitafio, largamente meditado por sus sabios, y despues de estos últimos deberes, satisfechos mas bien que á la memoria de su tio, á su orgullo de rey, se lanzó con los tostados africanos que encontró en su herencia y con el ejército que habia traido de allende el mar, sobre los enemigos, que aprovechándose de la muerte de Abu-Mozni-el-Zeirita, habian invadido su territorio; y despues de haber corrido las fronteras tras ellos, de haberles incendiado castillos y aldeas, y robádoles ganados y mugeres, se tornó á su alcazaba; repartió el botin entre los soldados, encerró las mugeres en una torre, y se echó á buscar un sitio donde edificar una residencia mas digna de un rey, que el ahumado torreon donde habia pasado largas veladas, tendido sobre una piel de tigre, el primer señor árabe de Granada.\"},{\"heading\":false,\"text\":\"Llamó á sus faquies y á sus astrólogos, y estos, despues de haber consultado las estrellas, le llevaron á la cresta de la colina poco distante de la torre de la alcazaba, y le dijeron:\"},{\"heading\":false,\"text\":\"--Aquí señor debes alzar tu alcázar y la atalaya de tu reino; porque desde esta loma se vén la estendida vega y las distantes fronteras, y porque un rey debe estar siempre atento á la defensa de su pueblo.\"},{\"heading\":false,\"text\":\"Y Aben-Habuz hizo un alcázar y levantó una torre altísima en el lugar que le dijeron los faquies y los astrólogos, y sobre la torre puso un caballero de hierro con la lanza en ristre y girando á todos los vientos, y en la adarga del caballero mandó pintar un gallo y poner debajo esta leyenda:\"},{\"heading\":false,\"text\":\"Dice el sabio Aben-Habuz, que así se defiende el Andaluz.\"},{\"heading\":false,\"text\":\"Porque el viejo rey tenia por una de sus mas preciosas máximas la de que un guerrero debia ser vigilante como un gallo, ligero como el viento, para volverse y correr á la parte por donde amenazase el peligro, y por esto y por otras razones que á nadie dijo, llamó á la torre de su alcazaba, torre del Gallo de viento.\"},{\"heading\":false,\"text\":\"Y encerrábase en ella el viejo rey, y se dormia al rechinar de la veleta, y la consultaba cada vez que soplaba el viento de la tormenta, y allí donde el caballero tenia asestada la punta de su lanza, corria con sus gentes, y hacia Eblís[26] que siempre encontrase enemigos á quienes destrozaba volviéndose cargado de presas á su castillo.\"},{\"heading\":false,\"text\":\"Y sucedió que una de estas veces, en vez de encontrar enemigos solo halló un viejo astrólogo, que al ver llegar al rey entre aquella muchedumbre de guerreros, se prosternó por tierra, pidió amparo á Aben-Habuz, y le prometió si le dejaba la vida, edificarle un alcázar tal, que fuese maravilla de los siglos venideros.\"},{\"heading\":false,\"text\":\"Rióse el rey del temor del astrólogo, hízole cabalgar á la grupa de uno de sus africanos, le trajo á Granada, y se encerró con él en la torre del Gallo de viento, sin dar oidos á otras palabras que á las del astrólogo, ni salir de la torre mas que para hacer las azalaes[27] en la mezquita.\"},{\"heading\":false,\"text\":\"Y aconteció que el rey olvidó la guerra por la astrología, y pasaron lunas enteras sin que saliese contra los cristianos; á pesar de que estos, mal escarmentados siempre, corrian la tierra haciendo talas y desaguisados, y los habitantes de las villas fronterizas, temerosos de ellos, corrieron á encerrarse tras los muros de la alcazaba Cadima y de la villa de los Judios.\"},{\"heading\":false,\"text\":\"Cansóse el caballero de la torre de avisar el peligro, y desde entonces no volvió á inclinar su lanza al lugar por donde aparecian enemigos, y perdió su virtud el talisman, mientras el rey pasaba las noches en claro en la torre del Gallo de viento á la luz del hornillo donde el sabio hervia en sus vasijas de vidrio brevajes repugnantes.\"},{\"heading\":false,\"text\":\"Al fin una noche el sabio y el rey salieron de la alcazaba por un postigo del muro, bajaron al valle formado por el Darro, y subieron á la Colina Roja.\"},{\"heading\":false,\"text\":\"Era la noche oscura y la tormenta hacia rechinar la veleta de la torre del Gallo de viento: la lanza del caballero señalaba entonces á la Colina Roja donde estaba el astrólogo con el rey.\"},{\"heading\":false,\"text\":\"Hay quien dice que el astrólogo solo queria vengarse del rey por haberle este arrebatado una hermosa doncella hija suya de la villa de los Judios y que habia dado al rey un filtro que habia secado su cerebro tornándole loco.\"},{\"heading\":false,\"text\":\"Sea como quiera, el astrólogo encendió una hoguera en la parte oriental de la Colina Roja en el mismo sitio donde estaban las ruinas de una antigua alcazaba, y arrojó al fuego, pronunciando palabras misteriosas, unos polvos mágicos fabricados por él delante del rey. Entonces la tierra tembló, condensóse el aire, tomó formas el humo de la hoguera y aparecieron cuatro hadas hermosas, apenas cubiertas con velos de seda, batiendo sus trasparentes alas de mariposa.\"},{\"heading\":false,\"text\":\"Aquellas hadas que por el poder del conjuro del astrólogo habian sido arrancadas del quinto cielo, eran los genios del Palacio-de-Rubíes.\"},{\"heading\":false,\"text\":\"Llamábase la una Aliento-de-las flores[28], la segunda Eco-de-las-armonías; la tercera Suspiro-de-amor; la cuarta Espejo-de-Dios.\"},{\"heading\":false,\"text\":\"Al aparecer las cuatro hadas, se habia levantado como por encanto alrededor del rey un alcázar de incomparable hermosura: el astrólogo habia desaparecido: solo quedaban las cuatro hadas revolando alrededor del rey que corria frenético por las galerías y los retretes y las cámaras y los patios del alcázar encantado; de aquel magnífico alcázar fresco, riente y sonoro, con el canto de sus aves, la fragancia de sus flores, el murmullo de sus fuentes y el eco de sus armonías.\"},{\"heading\":false,\"text\":\"El rey corria, y corria, y lanzaba grandes carcajadas.\"},{\"heading\":false,\"text\":\"Aben-Habuz tenia un alcázar de oro y pórfido, era astrólogo y sabio, pero habia perdido el juicio.\"},{\"heading\":false,\"text\":\"El judío se habia vengado.\"},{\"heading\":false,\"text\":\"Las hadas giraban alrededor del rey, danzando unas veces, revolando en las cúpulas otras, perdiéndose en el fondo de los estanques, ó deshaciéndose en vapores perfumados entre las esbeltas columnatas de las galerías.\"},{\"heading\":false,\"text\":\"Y Aben-Habuz seguia corriendo con la barba descompuesta, la túnica flotante, la toca deshecha, riendo siempre, de una manera insensata, y las hadas repetian su risa de loco; deteníase cansado y las hadas se replegaban silenciosas en sus lechos de algas y flores; de perfumes y oro: de repente volvian á aparecer ante el rey y escitado Aben-Habuz por su hermosura corria en vano tras ellas; y el insensato reia de pena, y sufria riendo, y en vano queria contener aquella risa fatal que salia á su pesar de su pecho.\"},{\"heading\":false,\"text\":\"Y tornábase con la aurora á la torre del Gallo de viento, y en vano pretendia ver desde sus almenas el palacio donde habia pasado la noche; la Colina Roja se presentaba á su vista escueta y árida, como antes del ensalmo del astrólogo, y el rey se impacientaba y preguntaba á sus cadíes y á sus wazires, si veian sobre la Colina las torres, los muros y los minaretes de un alcázar.\"},{\"heading\":false,\"text\":\"Los sabios de su corte se entristecian y tenian al rey por loco, porque nada veian.\"},{\"heading\":false,\"text\":\"Todas las noches Aben-Habuz subia á la Colina Roja, y entonces el alcázar se presentaba ante él soberbio con sus altísimas torres, sus enhiestas almenas reales, sus cavas profundas y sus puertas de hierro, que se abrian para darle entrada hasta el Palacio-de-Rubíes, donde tornaba á su insensata alegría y á su risa cruel.\"},{\"heading\":false,\"text\":\"Y cada noche que el rey penetraba en el palacio encantado parecíale este mas hermoso, mas diáfano, y mas rico de resplandores y de armonía; miraba su nombre escrito con oro entre los lazos de las atauxias[29] y de los alicatados[30] y le enardecian las leyendas de amor, en que hablaban para él, con el lenguaje del paraiso huríes invisibles.\"},{\"heading\":false,\"text\":\"Y el desdichado sufria, reia y tornaba á su castillo, cada vez mas insensato, cada vez mas débil.\"},{\"heading\":false,\"text\":\"Su vida se consumia como una lámpara á la que falta pávilo, y aquel terrible rey tan fiero y justador á su llegada á Granada, solo era ya una sombra de lo que habia sido: un cadáver animado.\"},{\"heading\":false,\"text\":\"Llegó á hacerse su locura terrible: azotaba á sus mugeres, reventaba á sus perros, cortaba la cabeza á sus sabios, y se reia siempre; y al eco de su risa huian todos, porque habia llegado á ser un eco de muerte.\"},{\"heading\":false,\"text\":\"Una noche se ciñó su corona de rey sobre su frente de loco, y salió como acostumbraba, de su castillo al que, por fortuna de sus vasallos, no debia volver sino en hombros de los señores de su córte.\"},{\"heading\":false,\"text\":\"Rugia la tormenta y el huracan zumbaba entre las quebraduras de los cerros.\"},{\"heading\":false,\"text\":\"Aben-Habuz subió impávido el repecho de la Colina Roja, llegó á la puerta de hierro del alcázar encantado, que se abrió ante él, y llegó hasta el fondo de un magnífico patio, entre cuyas galerías se habian refugiado las cuatro hadas huyendo de la tormenta.\"},{\"heading\":false,\"text\":\"Cuando el rey Aben-Habuz las vió á la diáfana luz que alumbraba el alcázar, emanada del mismo, soltó una sonora carcajada, abrió con entrambas manos su alquicel para que las hadas no pudiesen escaparse, y se fué hácia ellas pretendiendo abrazarlas.\"},{\"heading\":false,\"text\":\"Pero Espejo-de-Dios, pasó sobre él deshaciéndose en lluvia; Aliento-de-las-flores huyó, envolviéndole en perfumes; Eco-de-las-armonías se deslizó junto á él, rozando sus vestiduras y haciéndole escuchar cantos perdidos; y Suspiro-de-amor le burló infiltrando en su corazon ardientes deseos.\"},{\"heading\":false,\"text\":\"Tras esta burla las hadas fueron á posarse en un ángulo distante, y Aben-Habuz corria tras ellas, riendo siempre y empeñándose en aquel juego fatal que agotaba sus fuerzas y su vida.\"},{\"heading\":false,\"text\":\"Y desaparecian y tornaban á aparecer, y las columnas y los arcos, los muros y las cúpulas, parecian girar, uniéndose á aquel baile terrible, y las leyendas escritas con oro y colores, y los mármoles y los alicatados, lanzaban lánguidos destellos y repetian enamorados cantares y parecian exhalar céfiros lascivos impregnados de suavísimos perfumes.\"},{\"heading\":false,\"text\":\"Y el desdichado loco reia, y cada carcajada era mas desgarradora y sus pasos cada vez mas inciertos y vacilantes: y el alcázar continuaba girando alrededor de él y acreciendo en destellos, en fragancia, en armonía.\"},{\"heading\":false,\"text\":\"Al fin, Aben-Habuz vaciló, sentóse fatigado sobre el pavimento, sus ojos se nublaron, la muerte voló en torno suyo, y volvió á la razon.\"},{\"heading\":false,\"text\":\"Entonces cesó su risa: quiso levantarse y no pudo, y miró á las hadas con los ojos inyectados de sangre:\"},{\"heading\":false,\"text\":\"--¡Malditos génios! dijo con voz espirante: ¡habeis hecho insensato á un rey, pero este rey es sabio y se vengará! Dormid aquí, con mi corona y mis amores, hasta que un rey poderoso, descendiente del compañero del Profeta venga con el poder que le presta á la ciencia, á despertaros de vuestro sueño.\"},{\"heading\":false,\"text\":\"Y cayó por tierra, y sus ojos se cerraron y la muerte fué con él.\"},{\"heading\":false,\"text\":\"Al mismo tiempo se derrumbó con estruendo el alcázar, y las hadas quedaron sepultadas entre sus ruinas.\"},{\"heading\":false,\"text\":\"--Yo soy descendiente del Ansari, dijo sin poderse contenerse el rey Nazar.\"},{\"heading\":false,\"text\":\"--Sí, sí, tu eres el destinado á mostrar á las gentes el Palacio-de-Rubíes, dijo Yshac-el-Rumi: por eso, cuando por complacer á Bekralbayda, has pensado en hacer un alcázar, ese buho ha entrado y ha apagado tu luz.\"},{\"heading\":false,\"text\":\"--¡Pero ese buho!...\"},{\"heading\":false,\"text\":\"--El rey Aben-Habuz, fué encontrado muerto sobre la Colina Roja: y conducido á su castillo fué sepultado en una tumba magnífica. Pero el alma del rey Aben-Habuz, ha quedado sobre la tierra, encantada en el cuerpo de un buho.\"},{\"heading\":false,\"text\":\"--¿Y quién te ha rebelado ese misterio y esa maravillosa leyenda? dijo el rey Nazar; temeroso de que aquel relato fuese una impostura de Yshac-el-Rumi.\"},{\"heading\":false,\"text\":\"--Hace mucho tiempo, señor, dijo el viejo de una manera inalterable, que he consultado tu horóscopo con las estrellas.\"},{\"heading\":false,\"text\":\"--¿Y mi horóscopo cual es?\"},{\"heading\":false,\"text\":\"Letre dib.º y lit.ª Lit. de J. J. Martinez. Desengaño, 10 Madrid.]\"},{\"heading\":false,\"text\":\"--Tú serás el fundador de ese alcázar que admirarán las gentes, que construirás por el amor de una muger, y al que darás tu nombre.\"},{\"heading\":false,\"text\":\"--¿Y ese alcázar existe?\"},{\"heading\":false,\"text\":\"--Existe encantado.\"},{\"heading\":false,\"text\":\"--¿Y puedo yo verle?\"},{\"heading\":false,\"text\":\"--Sí, poderoso señor, pero enloquecerías y moririas como el rey Aben-Habuz.\"},{\"heading\":false,\"text\":\"--¡Y bien! sino puedo verle, ¿cómo he de construir en el lugar donde se encuentra, un alcázar semejante?\"},{\"heading\":false,\"text\":\"--Yo te traeré pintado en pergamino el alcázar; medido y dispuesto desde lo mas chico hasta lo mas grande, de modo que los alarifes y los oficiales solo tengan que labrar la piedra y la madera.\"},{\"heading\":false,\"text\":\"--¿Y cuando me traerás ese pergamino?\"},{\"heading\":false,\"text\":\"--Pasada una luna.\"},{\"heading\":false,\"text\":\"--¡Una luna todavía!\"},{\"heading\":false,\"text\":\"--Necesito ese tiempo para visitar el alcázar encantado, y puesto que tanto amas á mi hija, aprovéchate tú para reducirla á tu amor.\"},{\"heading\":false,\"text\":\"--Dentro de una luna te espero, dijo el rey Nazar: vete.\"},{\"heading\":false,\"text\":\"--Dentro de una luna yo te haré conocer el Palacio-de-Rubíes. ¡Que el Altísimo y Misericordioso quede contigo, rey Nazar!\"},{\"heading\":false,\"text\":\"Y el astrólogo salió.\"},{\"heading\":false,\"text\":\"--¡Oh! esclamó el rey Nazar; ¡el sabio rey Aben-Habuz, encantado en un buho! ¡este buho inspirándome el amor de Bekralbayda! ¡ella pidiéndome un alcázar en cambio de sus amores! ¡ese viejo contándome un estraño encantamiento! ¡mi hijo enamorado de ella, guardando su secreto, y ella, enamorada de mi hijo y ocultando tambien su amor! y luego: ¡yo conozco á ese viejo: yo le he visto alguna vez! pues bien: ¡dejemos correr la cosas, y Dios me guiará!\"},{\"heading\":false,\"text\":\"Fortalecido y tranquilo por su confianza en Dios, el rey Nazar se reclinó en su diván, se envolvió en su alquicel y se durmió.\"}]},{\"title\":\"El rey nazar. — capítulo XIII: La sultana loca.\",\"blocks\":[{\"heading\":false,\"text\":\"¡Qué hermosa era aquella muger á pesar de su locura!\"},{\"heading\":false,\"text\":\"Negros sus ojos y sus cabellos, como los ojos y los cabellos del ángel de la noche, su frente, su cuello y sus hombros eran mas blancos que la espuma de un torrente, cuando la ilumina la luz de la luna.\"},{\"heading\":false,\"text\":\"¡Qué hermosa era la sultana Wadah!\"},{\"heading\":false,\"text\":\"Las flores palidecian de envidia al verla, y los ruiseñores cantaban estremecidos de amor cuando ella pasaba lenta y pensativa bajo las enramadas de los jardines del alcázar.\"},{\"heading\":false,\"text\":\"Muchas veces pasaba largas horas sentada á la márgen de las corrientes, mirando abstraida el contínuo trenzar y destrenzar de las aguas ó con la mirada absorsta y fija en esas estrañas figuras que forman las nubes cuando las agrupa y las amontona el viento.\"},{\"heading\":false,\"text\":\"Otras veces se la sorprendia escribiendo sobre la arena con una varita acabada de arrancar á un box, estrañas figuras y caracteres ininteligibles, ó ya retirada en sus retretes, entonando un cántico monótono y misterioso.\"},{\"heading\":false,\"text\":\"Nadie la habia visto reir, pero nadie tampoco la habia visto llorar.\"},{\"heading\":false,\"text\":\"Y á pesar de su enagenacion, y de lo estraño de sus palabras y de sus acciones, nadie á escepcion del rey Nazar la creia loca.\"},{\"heading\":false,\"text\":\"Por el contrario la creian maga, y poseida por un espíritu invisible.\"},{\"heading\":false,\"text\":\"Sus esclavos estaban con terror á su lado y aprovechaban la primera ocasion para huir de ella.\"},{\"heading\":false,\"text\":\"De ella que era tan hermosa.\"},{\"heading\":false,\"text\":\"Pero la mirada de sus negros ojos tenian una fijeza tal, parecian tan hambrientos que aterraban.\"},{\"heading\":false,\"text\":\"El mismo rey Nazar habia acabado por espantarse de ella.\"},{\"heading\":false,\"text\":\"La sultana no lloraba, pero cantaba cada dia de una manera mas triste.\"},{\"heading\":false,\"text\":\"Y aquel canto era la lluvia de lágrimas de su alma.\"},{\"heading\":false,\"text\":\"Hacia muchos años, casi veinte, desde el nacimiento del príncipe Juzef-Abdallah, segundo hijo del rey Nazar, que la sultana Wadah, estaba loca, ó como lo pretendian sus aterrados esclavos, poseida por un espíritu invisible.\"},{\"heading\":false,\"text\":\"Wadah amaba al rey Nazar con un amor desesperado; muchas noches se la escucha llamando de una manera desesperada á Al-Hhamar, y otras abalanzándose y pretendiendo forzar las puertas que conducian á las habitaciones de su esposo.\"},{\"heading\":false,\"text\":\"Otras veces se la oia rugir como una leona, y cuando acudian los esclavos encargados de sujetarla en aquellos accesos, la veian ir de acá para allá levantando tapices corriendo á todos los lugares oscuros, revolviéndolo todo como si buscase algo.\"},{\"heading\":false,\"text\":\"No habia duda: la desdichada sultana Wadah, estaba poseida de un espíritu invisible.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Un dia se abrió la puerta dorada de su retrete.\"},{\"heading\":false,\"text\":\"Wadah exhaló un grito de alegría.\"},{\"heading\":false,\"text\":\"Por aquella puerta solo podia venir el rey Nazar.\"},{\"heading\":false,\"text\":\"El rey entró y cerró de nuevo.\"},{\"heading\":false,\"text\":\"La sultana se abalanzó á él.\"},{\"heading\":false,\"text\":\"--Yo te amo, te amo siempre, esclamó.\"},{\"heading\":false,\"text\":\"Y le besó en la boca.\"},{\"heading\":false,\"text\":\"El rey Nazar contestó estremeciéndose á aquel beso, con un beso trémulo.\"},{\"heading\":false,\"text\":\"--Tú te aterras junto á mí, dijo Wadah, tú me temes ¿por qué temes á tu amada?\"},{\"heading\":false,\"text\":\"El rey no supo qué contestar.\"},{\"heading\":false,\"text\":\"--¿Has visto acaso otra muger mas hermosa que yo? dijo la sultana fijando su terrible mirada en Al-Hhamar.\"},{\"heading\":false,\"text\":\"--¡Oh! no: esclamó el rey: tú eres la muger mas hermosa de la tierra.\"},{\"heading\":false,\"text\":\"Y el rey Nazar se estremecia, porque las megillas de la sultana temblaban, y una leve espuma empezaba á blanquear sus labios rojos, como una banda de grana.\"},{\"heading\":false,\"text\":\"--Sí, sí: esclamó Wadah corriendo hácia un gigantesco espejo de plata y arrancándose sus vestiduras hasta quedar medio desnuda: yo me veo ahí; yo soy cada dia mas hermosa: yo embellezco las joyas y doy brillo á los diamantes: yo soy mas blanca y mas nacarada que las perlas: y yo le amo, yo le amo y él me abandona: ¿habrá visto á otra muger mas hermosa que yo?\"},{\"heading\":false,\"text\":\"El rey Nazar conoció que habia ido á ver á la sultana en uno de sus mas graves momentos de locura.\"},{\"heading\":false,\"text\":\"Wadah continuó delante del espejo, destrozándose los cabellos y arracándose las joyas que la cubrian.\"},{\"heading\":false,\"text\":\"--Sí, sí; soy muy hermosa, Nazar; mírame, amado mio, mírame y ámame; solo he perdido el color de mis megillas: me he quedado blanca, blanca como la luna: pero... eso fué desde un dia...\"},{\"heading\":false,\"text\":\"Destellaron un relámpago salvaje los ojos de la sultana, se estremeció toda, lanzó un grito horrible, y casi desnuda, arrastrando su larga túnica de brocado, destrenzados los larguísimos cabellos, flotando sobre los tersos y redondos hombros, empezó á buscar por los rincones de la cámara, á revolver los almohadones del divan, á levantar los tapices de los retretes.\"},{\"heading\":false,\"text\":\"--¡Mi rosa blanca! gritaba: ¡mi rosa blanca! ¡yo la tenia escondida y me la han robado!\"},{\"heading\":false,\"text\":\"Y luego se sentó en el suelo, cruzó sus manos sobre sus rodillas y se puso á cantar una melodía vaga, sin palabras, triste y lánguida como un suspiro.\"},{\"heading\":false,\"text\":\"El rey Nazar la contemplaba inmóvil, y lágrimas de compasion asomaban á sus ojos suspendidas sobre sus megillas.\"},{\"heading\":false,\"text\":\"¡La rosa blanca!\"},{\"heading\":false,\"text\":\"Jamás Wadah habia pronunciado una sola palabra que aclarase el misterio de la causa de su locura.\"},{\"heading\":false,\"text\":\"¡La rosa blanca!\"},{\"heading\":false,\"text\":\"Hé aquí lo único que se la oía pronunciar en medio de su delirio.\"},{\"heading\":false,\"text\":\"El rey habia preguntado á sus sabios, y estos se habian esforzado en vano por descifrar aquel misterio.\"},{\"heading\":false,\"text\":\"En una ocasion se habia puesto una magnífica rosa blanca, en una copa de oro, oculta tras un tapiz, y el mismo rey Nazar habia observado á su esposa escondido.\"},{\"heading\":false,\"text\":\"Llegado el acceso, la sultana habia buscado, segun costumbre, por todas partes, y al encontrar la rosa, se habia arrojado sobre ella y la habia despedazado esclamando.\"},{\"heading\":false,\"text\":\"--Mi rosa era mas blanca, y mas pura, y mas fragante.\"},{\"heading\":false,\"text\":\"El rey habia renunciado ya á conocer el misterio de la locura de su esposa.\"},{\"heading\":false,\"text\":\"Y habian pasado años y años.\"},{\"heading\":false,\"text\":\"Sin embarco, Wadah no habia olvidado su perdida rosa blanca.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Seguia sentada en el suelo cruzadas las manos delante de sus rodillas, y entonando su triste y lánguida melodía.\"},{\"heading\":false,\"text\":\"--¡Wadah! la dijo el rey.\"},{\"heading\":false,\"text\":\"--¿Quién me llama? esclamó la sultana escuchando con atencion.\"},{\"heading\":false,\"text\":\"--Soy yo... dijo el rey, yo que te amo.\"},{\"heading\":false,\"text\":\"--¡Ah! dijo la sultana, el rey Nazar: el rey Nazar es un ingrato; cuando yo le conocí, solo tenia una pequeña, una pobrecilla bandera y doscientos esclavos, ginetes en yeguas negras y armados de lanzas: era un pobre walí... pero yo le amé y fué poderoso.\"},{\"heading\":false,\"text\":\"Wadah pronunciaba estas palabras con una cadencia lenta, gutural y tenia fija la vista en las bovedillas doradas de la cúpula.\"},{\"heading\":false,\"text\":\"--Yo era maga... un mago me habia traido de las montañas donde nace el Nilo.\"},{\"heading\":false,\"text\":\"Yo amaba entonces solamente á mi rosa blanca, y la escondia para que nadie la marchitara con sus miradas.\"},{\"heading\":false,\"text\":\"Pero ví á Al-Hhamar y le amé; le amo tanto como á mi rosa blanca.\"},{\"heading\":false,\"text\":\"Le favorecí con mi poder; le dí un amuleto que le hizo invencible, y Al-Hhamar se apoderó primero de un pueblo y luego de otro y se hizo rey, rey fuerte, y sus soldados le llamaron el vencedor y el magnífico.\"},{\"heading\":false,\"text\":\"La rosa blanca tuvo celos de mi amor al rey Nazar y me abandonó.\"},{\"heading\":false,\"text\":\"Y el rey Nazar me abandonó tambien, á pesar de que sabia que era mi alma.\"},{\"heading\":false,\"text\":\"El rey Nazar amaba á otra muger.\"},{\"heading\":false,\"text\":\"¡Leila-Radhyah! ¡ah! ¡Leila-Radhyah! ¡pero tú tampoco has gozado los amores de Nazar! ¡yo sé que Nazar llora por tí!\"},{\"heading\":false,\"text\":\"Estremecióse Al-Hhamar. Era la primera vez que la sultana Wadah nombraba á la princesa africana.\"},{\"heading\":false,\"text\":\"¿Sabria Wadah lo que habia sido de ella?\"},{\"heading\":false,\"text\":\"Pero no se atrevió á preguntarla.\"},{\"heading\":false,\"text\":\"Continuó callando y escuchando con toda su alma.\"},{\"heading\":false,\"text\":\"Wadah permaneció sentada en el suelo con la mirada fija en la cúpula y hablando como si estuviese sola.\"},{\"heading\":false,\"text\":\"--El rey Nazar es un ingrato: me lo debe todo y me vé morir y no tiene compasion de mí. Una sola palabra suya seria para mí como el rocío de la alborada para las flores marchitas, y no pronuncia esa palabra.\"},{\"heading\":false,\"text\":\"Al-Hhamar se acercó á Wadah, la levantó en sus brazos, la estrechó en ellos y la besó en la boca.\"},{\"heading\":false,\"text\":\"Wadah se estremeció; dió un grito, miró de hito en hito al rey Nazar, y rompió á llorar.\"},{\"heading\":false,\"text\":\"Era la primera vez que lloraba despues de veinte años.\"},{\"heading\":false,\"text\":\"Su mirada lúcida, radiante, se posó en el rey y sus labios sonrieron.\"},{\"heading\":false,\"text\":\"--¡Ah, eres tú, tú! ¿cuanto tiempo hace que no te he visto? esclamó: ¡ah! ¿quién me ha arrancado mis vestiduras, quién ha destrenzado mis cabellos?... ¿has sido tú?\"},{\"heading\":false,\"text\":\"No: no; es imposible, tú tienes abandonada á tu esposa, tú no la amas.\"},{\"heading\":false,\"text\":\"--¡Wadah! ¡Wadah! esclamó el rey, ¿por qué dudas de mí?\"},{\"heading\":false,\"text\":\"--Dime: continuó Wadah, ¿por qué has traido á mi lado una doncella que yo no conocia, una hermosísima doncella á quien enamoras?\"},{\"heading\":false,\"text\":\"--Bekralbayda es una esclava que he comprado para tí.\"},{\"heading\":false,\"text\":\"--Sí; es verdad, dijo Wadah: tambien Leila-Radhyah, era una esclava, y sin embargo tú la amabas, Nazar.\"},{\"heading\":false,\"text\":\"--¡Leila-Radhyah! dijo el rey: dejemos en paz á los muertos.\"},{\"heading\":false,\"text\":\"--¡Sí es verdad, dijo Wadah: dejemos en paz á los muertos! pero tú la amabas, Nazar.\"},{\"heading\":false,\"text\":\"--Yo no he amado á ninguna mas que á tí: tú en cambio amas á un fantasma, á un misterio, mas que á tu esposo.\"},{\"heading\":false,\"text\":\"--¡Yo!\"},{\"heading\":false,\"text\":\"--Sí; tú amas mas que á mí á tu rosa blanca.\"},{\"heading\":false,\"text\":\"--¡Oh! esclamó la sultana Wadah, y en sus negros ojos brillaba la razon: ¡cuán torpes son los hombres! ¿No has comprendido cuál era mi rosa blanca?\"},{\"heading\":false,\"text\":\"--No, nunca lo has esplicado.\"},{\"heading\":false,\"text\":\"--La rosa blanca... era mi alma... mi alma que me la han robado los que me robaron tu amor: yo hé debido estar loca, Nazar.\"},{\"heading\":false,\"text\":\"--Acaso Dios lo haya permitido.\"},{\"heading\":false,\"text\":\"--Yo recuerdo, como sueños confusos, sueños horribles.\"},{\"heading\":false,\"text\":\"--Es necesario no recaer mas en esos sueños, amor de mi alma, dijo el rey estrechándola entre sus brazos.\"},{\"heading\":false,\"text\":\"--Necesito el amor y la compañía de mi esposo, dijo Wadah.\"},{\"heading\":false,\"text\":\"--Y bien, la tendrás.\"},{\"heading\":false,\"text\":\"--Necesito que vivas á mi lado.\"},{\"heading\":false,\"text\":\"--Viviré.\"},{\"heading\":false,\"text\":\"--Quiero que tu hijo el príncipe Mohammet...\"},{\"heading\":false,\"text\":\"--¿Qué sabes tú del príncipe?\"},{\"heading\":false,\"text\":\"--Sé que está preso.\"},{\"heading\":false,\"text\":\"--¿Quién te lo ha dicho?\"},{\"heading\":false,\"text\":\"--Bekralbayda mi esclava, que le vé lodos los dias asomado á un ajimez en lo alto de la torre del Gallo de viento.\"},{\"heading\":false,\"text\":\"Palideció levemente el rey Nazar y Wadah aspiró aquella palidez.\"},{\"heading\":false,\"text\":\"--Mi hijo ha cometido un delito de inobediencia y es necesario que le castigue.\"},{\"heading\":false,\"text\":\"--¿Y no habla por él en tu corazon el amor de su madre?\"},{\"heading\":false,\"text\":\"--¡Wadah!\"},{\"heading\":false,\"text\":\"--Perdónale, señor, perdónale... aunque no sea mas que por la memoria de tu perdida Leila-Radhyah.\"},{\"heading\":false,\"text\":\"Pronunció la sultana con tal sarcasmo estas palabras, que el rey empezó á sospechar lo que nunca habia sospechado: que su esposa hubiese tenido parte en la muerte de la princesa.\"},{\"heading\":false,\"text\":\"Y como si Wadah solo hubiese recobrado por un momento la razon para aterrar al rey Nazar, volvió á su violento estado de locura.\"},{\"heading\":false,\"text\":\"El rey salió aterrado de la cámara.\"},{\"heading\":false,\"text\":\"Apenas se perdió el ruido de las pisadas del rey, cuando Wadah se alzó del suelo donde de nuevo se habia sentado, sombría, terrible: en sus ojos habia vuelto á aparecer la razon.\"},{\"heading\":false,\"text\":\"--¡La ama! ¡ama á esa doncella! esclamó: ¡ha palidecido al saber que Bekralbayda ama á su hijo! Pues bien: ¡mis celos mataron á Leila-Radhyah! ¡mis celos matarán á Bekralbayda!\"},{\"heading\":false,\"text\":\"Y acabó de componer el desórden de sus ropas: recogió sus cabellos y salió lenta y fatídica de la cámara dorada, por una puerta opuesta á aquella por donde habia salido el rey.\"}]},{\"title\":\"El rey nazar. — capítulo XIV: Lo que se veia desde la torre del gallo de viento.\",\"blocks\":[{\"heading\":false,\"text\":\"Mientras pasaba la luna fijada por plazo por Yshac-el-Rumi para mostrar al rey la reproduccion de las maravillas del Palacio-de-Rubíes, acontecian en el palacio del Gallo de viento pequeños sucesos pero graves, y que no son para pasados en olvido.\"},{\"heading\":false,\"text\":\"El príncipe se desesperaba en la prision de la torre.\"},{\"heading\":false,\"text\":\"Encerrado allí como una águila en su jaula sufria esa tortura lenta del prisionero, que vé los azules horizontes, la gente que vá y que viene, que entra y que sale, y la envidia, porque su paso no puede estenderse mas allá de los muros de su prision.\"},{\"heading\":false,\"text\":\"Inaccion forzada, terrible, que irrita, que desespera, que desalienta, y tanto mas cuando no se conoce el término de ese estado aflictivo, cuando no se sabe si se saldrá de la prision para la tumba ó para el destierro.\"},{\"heading\":false,\"text\":\"Y cuando el que está preso ama como amaba el príncipe: cuando se tienen celos como el príncipe los tenia: cuando se vé desde la prision lo que el príncipe veia lodos los dias, la vida llega á hacerse insoportable.\"},{\"heading\":false,\"text\":\"Al amanecer, por medio de las calles de cesped de un jardin que veia el príncipe desde su empinada prision, atravesaba una forma blanca, leve y gentil y se perdia entre la espesura de los bosquecillos.\"},{\"heading\":false,\"text\":\"Aquella forma, aquella muger hechicera, era Bekralbayda.\"},{\"heading\":false,\"text\":\"Poco despues una forma negra, lenta, grave, magestuosa, se perdia por el mismo lugar por donde habia entrado la jóven.\"},{\"heading\":false,\"text\":\"Aquella forma negra, aquel hombre de andar reposado y magestuoso, era el rey Nazar.\"},{\"heading\":false,\"text\":\"Pasaba el tiempo: el príncipe devorado de celosa rabia contaba por cada instante un siglo.\"},{\"heading\":false,\"text\":\"Al fin el rey y Bekralbayda salian del bosquecillo, atravesaban juntos el sendero y se perdian bajo los pórticos.\"},{\"heading\":false,\"text\":\"No era solo el príncipe el que veia esto.\"},{\"heading\":false,\"text\":\"Lo veia la sultana Wadah, estremecida de rabia desde sus miradores.\"},{\"heading\":false,\"text\":\"Veíalo tambien estremecido de una cruel alegría desde una torrecilla del muro, el astrólogo Yshac-el-Rumi.\"},{\"heading\":false,\"text\":\"Llegó al fin el plazo prefijado por el astrólogo.\"},{\"heading\":false,\"text\":\"Una noche entró en la cámara del rey con un voluminoso rollo de pergaminos.\"},{\"heading\":false,\"text\":\"Hízole sentar Al-Hhamar y le dijo:\"},{\"heading\":false,\"text\":\"--Estoy impaciente por construir ese alcázar: mi amor hácia tu hija es cada dia mas grande.\"},{\"heading\":false,\"text\":\"--Mi hija es muy afortunada, poderoso señor.\"},{\"heading\":false,\"text\":\"--Pero tu hija se obstina en no corresponder á mi amor sino cuando haya construido para ella un alcázar.\"},{\"heading\":false,\"text\":\"--Aquí tienes las trazas de él, magnífico sultan, cuadra por cuadra, rico y magestuoso, como ha querido hacerle Dios.\"},{\"heading\":false,\"text\":\"El astrólogo estendió uno por uno todos los pergaminos.\"},{\"heading\":false,\"text\":\"En él estaban pintadas primorosamente las habitaciones del alcázar, los patios, las fuentes, las galerías caladas, las blancas columnatas de mármol, los claros estanques, los techos de oro, rojo y azul, las cúpulas estrelladas; una gran inmensidad de esquisitas labores, de alicatados maravillosos, de labradas maderas, de celosías, de puertas: aquello era un prodigio que maravilló al rey.\"},{\"heading\":false,\"text\":\"--Mira, señor, le decia el astrólogo, cuán bello es este patio: sus columnatas forman un espeso bosque cuando se le mira desde sus galerías, y los graciosos arcos parecen las copas de jóvenes palmeras que se cruzan; mira cuán magnífica es esa fuente que se sustenta sobre esos doce leones: pues las cuatro salas que rodean el patio, parecen robadas del paraiso: sus cúpulas son cielos estrellados y sus ajimeces parecen tan hermosos como los ojos de una hurí.\"},{\"heading\":false,\"text\":\"--Indudablemente Dios es grande sobre todas las grandezas, decia el rey, y este alcázar es una de sus maravillas.\"},{\"heading\":false,\"text\":\"Sus arcadas son tan ligeras, que parece que ha de hacerlas mover la brisa; sus columnas son tallos de azucenas en búcaros de nacar.\"},{\"heading\":false,\"text\":\"Sus estanques son espejos de Dios, y cada uno de sus jardines parecen el chal de una hurí.\"},{\"heading\":false,\"text\":\"¿Qué hombre podrá realizar tanta maravilla?\"},{\"heading\":false,\"text\":\"Ya no estraño que el rey Aben-Habuz se volviese loco al ver tanto prodigio.\"},{\"heading\":false,\"text\":\"--Tú realizarás esta obra admirable, poderoso sultan Nazar, dijo el astrólogo.\"},{\"heading\":false,\"text\":\"--Yo he construido en mi Granada cien mezquitas y doscientos algibes, dijo el rey: yo he abierto á la ciencia multitud de escuelas: yo he rodeado el recinto de muros que orlan mil y treinta torres y treinta mil almenas: yo he invertido ciertamente en todas esas obras grandes tesoros: ¿pero qué tesoros bastarian para construir este alcázar, maravilla de las maravillas?\"},{\"heading\":false,\"text\":\"--El palacio en que vives no es digno de tu grandeza.\"},{\"heading\":false,\"text\":\"--Sea feliz y próspero mi pueblo, que yo tengo bastante con una torre para morar y una piel de tigre para reclinar mi cabeza, como el viejo rey Abu-Mozni-el-Zeirita.\"},{\"heading\":false,\"text\":\"--Tú amas á mi hija.\"},{\"heading\":false,\"text\":\"Calló el rey.\"},{\"heading\":false,\"text\":\"--Mi hija no te concederá su amor, sino cuando hayas construido para ella este rico alcázar.\"},{\"heading\":false,\"text\":\"--Tu hija me pide mucho. Es una esclava demasiado cara.\"},{\"heading\":false,\"text\":\"--Mi hija será sultana.\"},{\"heading\":false,\"text\":\"Se estremeció el rey.\"},{\"heading\":false,\"text\":\"--Mi hija es mas hermosa y mas preciada que ese alcázar que tanto te enamora.\"},{\"heading\":false,\"text\":\"Meditó un momento el rey, y luego dijo levantándose de una manera decidida.\"},{\"heading\":false,\"text\":\"--¡Construiremos el alcázar de las maravillas, Yshac! ¡yo te lo juro!\"}]},{\"title\":\"El rey nazar. — capítulo XV: Uno para cada almena.\",\"blocks\":[{\"heading\":false,\"text\":\"Y es de advertir que cuando el rey Nazar formó la resolucion de construir aquel magnífico alcázar, no tenia una sola dobla en su tesoro.\"},{\"heading\":false,\"text\":\"Porque el rey Nazar invertia sumas cuantiosísimas en la construccion de hospitales, mezquitas, escuelas, y otros establecimientos, y en pagar sabios que enseñasen al pueblo.\"},{\"heading\":false,\"text\":\"El rey habia concebido un proyecto, para llevar el cual á cabo, envió cartas á todas las villas del reino, llamando á todos los caballeros sus vasallos.\"},{\"heading\":false,\"text\":\"Ocho dias despues hervia Granada en forasteros.\"},{\"heading\":false,\"text\":\"Deslumbraban las galas y el aparato con que aquellos habian venido á la córte, y las posadas estaban llenas, y se preguntaban los unos á los otros para qué habria hecho el rey aquel llamamiento.\"},{\"heading\":false,\"text\":\"Al fin un dia los convocó el rey Nazar á su palacio de la torre del Gallo de viento, y cuando todos estuvieron reunidos, salió vestido magníficamente en un caballo cubierto de paramentos de brocado, llevado de las riendas de púrpura por dos wazires, rodeado de sus sabios y de sus walíes y seguido de los esclavos negros de su guardia.\"},{\"heading\":false,\"text\":\"Precedian al rey Nazar timbaleros y trompetas, y de este modo, llevando tras sí á todos los nobles que habia convocado, bajó por Al-Acab[31] á la calle de Elvira, y atravesando el barrio que poblaba la tribu de los Gomeles, subió á la Colina Roja.\"},{\"heading\":false,\"text\":\"En el centro de la cumbre habia una magnífica tienda de seda y oro levantada para el rey.\"},{\"heading\":false,\"text\":\"Delante de la tienda habia un trono.\"},{\"heading\":false,\"text\":\"Cuando el rey Nazar llegó junto al trono, descabalgó y descabalgaron los de su comitiva, y de igual manera descabalgaron los caballeros.\"},{\"heading\":false,\"text\":\"El rey subió sobre el trono, rodeándole los de su séquito, y luego delante del trono y en media luna se estendieron todos los nobles, que pasarian de cuatro mil.\"},{\"heading\":false,\"text\":\"El rey Nazar paseó por ellos una mirada orgullosa.\"},{\"heading\":false,\"text\":\"La mirada de un rey que contemplaba delante de sí una caballería tan rica, tan noble y tan valiente.\"},{\"heading\":false,\"text\":\"--Os he llamado, dijo el rey, para concederos una gracia.\"},{\"heading\":false,\"text\":\"Salió una aclamacion unánime de las bocas de los caballeros.\"},{\"heading\":false,\"text\":\"--Todos sois nobles y valientes, y la paz en que estamos con el cristiano, os tenia ociosos y disgustados, convertidos en labradores.\"},{\"heading\":false,\"text\":\"Contestaron al rey unánimes señales de asentimiento.\"},{\"heading\":false,\"text\":\"--Mirad las distantes sierras: aquellas son las fronteras de nuestro territorio: de una parte hácia la tramontana tenemos á Murcia, de otra á Jaen, de otra á Córdoba, y allá al frente á Africa.\"},{\"heading\":false,\"text\":\"Volviéronse las miradas de los caballeros á las distantes fronteras con una avaricia feroz.\"},{\"heading\":false,\"text\":\"--Vosotros volariais sobre vuestros caballos y sobre vuestras almadias, atravesariais esas fronteras y ese mar, y hariais la guerra si yo os lo permitiese.\"},{\"heading\":false,\"text\":\"--¡Sí, sí, sí! gritaron enardecidos de entusiasmo todos los caballeros.\"},{\"heading\":false,\"text\":\"--Pero yo no puedo permitiros la guerra; tengo asentadas las paces con los reyes de Castilla y Aragon y con los emires de Africa.\"},{\"heading\":false,\"text\":\"Nublóse el atezado rostro de todos aquellos bravíos guerreros.\"},{\"heading\":false,\"text\":\"--Mi estandarte real no puede ir delante de vosotros, añadió el rey Nazar.\"},{\"heading\":false,\"text\":\"--¿Y cómo hemos de pasar las fronteras cristianas y embestir las riberas de Africa, tienes asentadas paces con los emires moros y los reyes cristianos? dijo uno de los caballeros.\"},{\"heading\":false,\"text\":\"--Yo no puedo permitiros la guerra: pero vosotros podeis hacer una sola algarada[32].\"},{\"heading\":false,\"text\":\"Volvió á brillar la alegría en el rostro de los caballeros.\"},{\"heading\":false,\"text\":\"--¿Una algarada á todo trance, señor? dijo el mismo anciano.\"},{\"heading\":false,\"text\":\"--Sí, respondió el rey.\"},{\"heading\":false,\"text\":\"--¿A la redonda en las fronteras del reino?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Y contra las riberas de Africa?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Y ningun daño nos parará, poderoso señor?\"},{\"heading\":false,\"text\":\"--Ninguno; pero atended lo que os voy á decir.\"},{\"heading\":false,\"text\":\"Creció el silencio entre los caballeros.\"},{\"heading\":false,\"text\":\"--Os permito una algarada de sol á sol contra las fronteras de Córdoba, Jaen, y Murcia, y contra la ribera opuesta de Africa frente á nosotros. Una algarada de sol á sol y nada mas. ¿Me entendeis bien?\"},{\"heading\":false,\"text\":\"--Sí, sí, poderoso señor.\"},{\"heading\":false,\"text\":\"--Pero entended mejor lo que os voy á decir: dentro de ocho dias me habeis de entregar en Granada treinta mil cautivos.\"},{\"heading\":false,\"text\":\"--¡Treinta mil cautivos! esclamaron con asombro los caballeros moros.\"},{\"heading\":false,\"text\":\"--Sí, treinta mil cautivos, dijo el rey: uno para cada almena.\"},{\"heading\":false,\"text\":\"--¿Pero dónde encontraremos tantos cautivos, poderoso señor?\"},{\"heading\":false,\"text\":\"--Buscadlos; y... al campo vuestras banderas; á la mar vuestras fustas: pasados ocho soles, me habeis de entregar en Granada treinta mil cautivos, uno para cada almena.\"},{\"heading\":false,\"text\":\"Y el rey despidió á sus caballeros y se volvió á su castillo.\"},{\"heading\":false,\"text\":\"--¡Treinta mil cautivos! decian poco despues aquellos feroces guerreros galopando por los caminos en busca de sus villas y alquerías.\"},{\"heading\":false,\"text\":\"--¡Uno para cada almena! murmuraban otros pensativos.\"},{\"heading\":false,\"text\":\"--¿Qué pretenderá hacer el rey Nazar? añadian todos.\"}]},{\"title\":\"El rey nazar. — capítulo XVI: Uno para cada cautivo.\",\"blocks\":[{\"heading\":false,\"text\":\"Maravilláronse los sabios y aturdiéronse los ignorantes con la estraña resolucion del rey Nazar.\"},{\"heading\":false,\"text\":\"¿Para qué queria aquellos treinta mil esclavos?\"},{\"heading\":false,\"text\":\"¿Qué treinta mil almenas eran aquellas de que habia hablado?\"},{\"heading\":false,\"text\":\"No se murmuraba de otra cosa en la córte.\"},{\"heading\":false,\"text\":\"Pero creció la maravilla cuando el rey llamó á ciertos oficiales que se ocupaban en labrar piedras, y encerrado con ellos en su castillo, les dijo:\"},{\"heading\":false,\"text\":\"--Yo tengo en la sierra canteras de preciosos mármoles: mio es el blanco y brillante, que al marfil semeja: mia la serpentina verde como la esmeralda: mio el granito rojo, verde y azul, y el manchado, que imita á la piel del tigre: ¿cuánto me dareis si os dejo sacar mármoles por dos años de esas canteras?\"},{\"heading\":false,\"text\":\"--Te daremos diez mil doblas marroquíes, señor, dijo el principal de aquellos menestrales.\"},{\"heading\":false,\"text\":\"Movió el rey la cabeza.\"},{\"heading\":false,\"text\":\"--Te daremos veinte mil doblas marroquíes.\"},{\"heading\":false,\"text\":\"Repitió el rey su movimiento negativo.\"},{\"heading\":false,\"text\":\"--Te daremos treinta mil doblas marroquíes.\"},{\"heading\":false,\"text\":\"--Dadme treinta mil morteros de granito negro, dijo el rey, uno para cada cautivo.\"},{\"heading\":false,\"text\":\"--¡Ah! señor, ¿y con qué compraremos el granito?\"},{\"heading\":false,\"text\":\"--Tomadle de mis canteras.\"},{\"heading\":false,\"text\":\"--¿Y cómo traeremos tanto mortero?\"},{\"heading\":false,\"text\":\"--Dejadlos al pie de las canteras.\"},{\"heading\":false,\"text\":\"--¿Y en cuánto tiempo, señor, hemos de arrancar el granito y labrarlo?\"},{\"heading\":false,\"text\":\"--En quince soles.\"},{\"heading\":false,\"text\":\"--¡Ah, poderoso señor! ¡tú quieres que hagamos maravillas!\"},{\"heading\":false,\"text\":\"--Vuestro es el mármol de todo género que podais arrancar durante dos años de mis canteras: pero habeis de entregarme dentro de quince soles treinta mil morteros de granito negro con su maza, uno para cada esclavo.\"},{\"heading\":false,\"text\":\"Consultaron algun tiempo entre sí los menestrales.\"},{\"heading\":false,\"text\":\"--¿Y si dentro de los quince soles nos faltase algun número de morteros, señor?\"},{\"heading\":false,\"text\":\"--Entonces perdereis los que hallais fabricado y no os daré nada.\"},{\"heading\":false,\"text\":\"Volvieron á consultar entre sí los mecánicos.\"},{\"heading\":false,\"text\":\"--Dentro de quince soles, señor, dijeron, tendrás al pie de las canteras de la sierra, treinta mil morteros con su maza.\"},{\"heading\":false,\"text\":\"--Sí, sí, dijo el rey: eso es, treinta mil: uno para cada cautivo.\"},{\"heading\":false,\"text\":\"Los menestrales salieron maravillados:\"},{\"heading\":false,\"text\":\"--¿Para qué querrá el rey, se decian, treinta mil morteros?\"}]},{\"title\":\"El rey nazar. — capítulo XVII: ¡el rey nazar se ha vuelto loco!\",\"blocks\":[{\"heading\":false,\"text\":\"Uno de los que mas se maravillaban y mas recelosos andaban con la determinacion del rey Nazar, era el mismo que le habia metido en la tentacion de construir el Palacio-de-Rubíes.\"},{\"heading\":false,\"text\":\"Yshac-el-Rumi.\"},{\"heading\":false,\"text\":\"Aquel estraño viejo daba en vano vueltas á su imaginacion para adivinar los proyectos del rey.\"},{\"heading\":false,\"text\":\"El destino que queria dar á aquellos treinta mil esclavos y el objeto á que destinaba aquellos treinta mil morteros, eran dos acertijos.\"},{\"heading\":false,\"text\":\"Sin embargo, aquellos dos acertijos, como veremos mas adelante, eran de muy facil resolucion.\"},{\"heading\":false,\"text\":\"A pesar de la facilidad de esta resolucion, Yshac-el-Rumi no daba con ella.\"},{\"heading\":false,\"text\":\"Lo que demostraba que tenia mas de charlatan que de astrólogo.\"},{\"heading\":false,\"text\":\"Sin embargo, Yshac-el-Rumi, como veremos mas adelante no era un hombre malo.\"},{\"heading\":false,\"text\":\"Se habia propuesto motivar un gran acto de justicia, y para ello se habia valido como medio de lo maravilloso, porque sabia demasiado lo dados que eran á la supersticion los musulmanes.\"},{\"heading\":false,\"text\":\"Y cuando decimos los musulmanes, como separando de ellos á Yshac-el-Rumi, parece que decimos que Yshac no era musulman.\"},{\"heading\":false,\"text\":\"En efecto, no lo era originariamente: su mismo sobrenombre de Rumi lo decia[33].\"},{\"heading\":false,\"text\":\"Si ahora os contáramos la historia de Yshac-el-Rumi, perderia gran parte de su interés nuestro relato.\"},{\"heading\":false,\"text\":\"Básteos saber que Yshac-el-Rumi no era astrólogo mas que en la charla, que el cuento del rey Aben-Habuz habia sido una invencion suya para maravillar al rey, que el encantado alcázar de Rubíes era una mentira, y que los hermosos planos, dibujos y vistas que habia mostrado al rey y que tanto le habian encantado, los habia comprado á un alarife africano que habia muerto en la miseria, sin lograr que ningun emir de oriente quisiese gastar sus tesoros en la construccion de aquel magnífico alcázar con el cual habia soñado veinte años de su vida, invertidos en la composicion, distribucion, trazas y adornos que estaban demostrados en los pergaminos.\"},{\"heading\":false,\"text\":\"El alarife moribundo, vendió á Yshac-el-Rumi aquellos planos, dibujos y trazas mediante á una estraña condicion, fundada en una historia de amores y desgracias, y por algunos dirahmes de plata con los cuales debia ser comprada una sepultura de piedra.\"},{\"heading\":false,\"text\":\"El alarife habia entregado todos los sueños de su vida á Yshac-el-Rumi, á trueque de una estrecha vivienda donde dormir por toda una eternidad.\"},{\"heading\":false,\"text\":\"Además, el alarife habia entregado á Yshac-el-Rumi una muger y una niña.\"},{\"heading\":false,\"text\":\"La muger era hermosísima, la niña daba señales de serlo.\"},{\"heading\":false,\"text\":\"Fiel Yshac á su juramento, habia embalsamado y puesto en su lecho de piedra al africano: se habia consagrado á aquella niña y á aquella muger, y estaba á punto de realizar los sueños del difunto.\"},{\"heading\":false,\"text\":\"El rey Nazar conocia á la niña.\"},{\"heading\":false,\"text\":\"El príncipe Mohammet la amaba.\"},{\"heading\":false,\"text\":\"Porque aquella niña era Bekralbayda.\"},{\"heading\":false,\"text\":\"El alcázar maravilloso iba á construirse.\"},{\"heading\":false,\"text\":\"Pero no podia Yshac-el-Rumi sacar en claro para qué queria el rey Nazar aquellos treinta mil cautivos y aquellos treinta mil morteros.\"},{\"heading\":false,\"text\":\"Y no era solo Yshac-el-Rumi el que andaba pensativo y confuso por aquel misterio: llegó á interesarse en él todo el reino.\"},{\"heading\":false,\"text\":\"Porque autorizados los walíes, capitanes y arrayaces vasallos del rey Nazar para entrar en algara por las tierras cristianas y las riberas de Africa, empezaron á tomar gente á sueldo, y no se veian por do quier mas que escuadrones armados y banderas tendidas, atravesando la Vega y los desfiladeros de las montañas: y por otra parte los alarifes y labradores de mármol, buscaban cuantos oficiales podian, y pagándolos á precio de oro, se los llevaban á las canteras del rey, donde trabajaban de dia y de noche.\"},{\"heading\":false,\"text\":\"Entre tanto el rey Nazar hacia frecuentes escursiones con Yshac-el-Rumi, y llevando consigo los maravillosos pergaminos, á la Colina Roja.\"},{\"heading\":false,\"text\":\"--Pero aquí no cabe este alcázar, decia á su falso astrólogo: será necesario subir con los muros por la ladera del cerro, y correr por su cumbre, y bajar despues á la Colina de Al-Bahul, cerrando las dos alas del alcázar como con un herrete, con una muralla que cierre el barrio de los Gomeles. ¡Oh! ¡quién tuviera vida para ver terminada esta maravilla!\"},{\"heading\":false,\"text\":\"Yshac se maravillaba de que el rey Nazar pidiese á Dios vida y no tesoros para construir aquel alcázar.\"},{\"heading\":false,\"text\":\"--Muy rico debe ser el rey, decia para sus adentros.\"},{\"heading\":false,\"text\":\"--Cien torres y treinta mil almenas en ellas y en los muros, decia el rey Nazar contemplando los planos: un cautivo para cada almena, un mortero para cada cautivo: treinta mil dirahmes de oro cada un dia; ¡sí, sí, por Allah! hay lo bastante para construir una nueva Damasco. ¡Treinta mil cautivos! ¡uno para cada almena! ¡treinta mil morteros! ¡uno para cada cautivo! ¡treinta mil dirahmes de oro cada un dia!\"},{\"heading\":false,\"text\":\"Yshac-el-Rumi se contristó, porque creyó que el rey habia perdido el juicio, y esto echaba á tierra todos sus proyectos.\"},{\"heading\":false,\"text\":\"Y no era solamente Yshac el que pensaba de esta manera.\"},{\"heading\":false,\"text\":\"Los habitantes de Granada decian tambien, pero en voz baja por temor de ser castigados:\"},{\"heading\":false,\"text\":\"--¡El rey Nazar se ha vuelto loco!\"}]},{\"title\":\"El rey nazar. — capítulo XVIII: ¡el rey nazar es un sabio!\",\"blocks\":[{\"heading\":false,\"text\":\"Pasaron los ocho dias que el rey habia concedido á los caballeros del reino para un solo dia de algarada alrededor de las fronteras y al frente de la costa.\"},{\"heading\":false,\"text\":\"El mismo dia en que se cumplia el plazo, amanecieron delante de las puertas de Granada los cuatro mil caballeros, con sus banderas y sus taifas en número de cincuenta mil hombres[34].\"},{\"heading\":false,\"text\":\"En el centro del aduar ó campamento formado por cada una de estas taifas, se veian las presas hechas en las fronteras cristianas y en la ribera de Africa, consistiendo la mayor parte de estas presas en cautivos.\"},{\"heading\":false,\"text\":\"Notábase que todos estos cautivos eran hombres y hombres robustos; si los caballeros habian hecho cautivas, se habian abstenido sin duda de llevarlas á Granada, enviándolas con algun ligero resguardo á sus posesiones.\"},{\"heading\":false,\"text\":\"El rey Nazar que esperaba, no sin fundamento, que sus caballeros cumplirian fielmente su promesa, estaba preparado, y cuando le avisaron de la presencia de aquellas gentes de la Vega, salió de su castillo rodeado de su córte y seguido por los mismos esclavos de su guardia.\"},{\"heading\":false,\"text\":\"Cuando el rey salió á la Vega por la puerta de Elvira, las dulzainas, las trompetas, los tambores, los atabales y las atakeviras de sus caballeros, tocaron la zambra, á la que contestaron los músicos del rey.\"},{\"heading\":false,\"text\":\"Al pasar por medio de los cerrados escuadrones, los soldados gritaban:\"},{\"heading\":false,\"text\":\"--Al-Hhamar le galib[35].\"},{\"heading\":false,\"text\":\"A lo que el rey Nazar contestaba, sonriéndose benévolamente, á walíes y soldados.\"},{\"heading\":false,\"text\":\"--¡We! ¡le galib ille Allah![36]\"},{\"heading\":false,\"text\":\"El rey llegó al fin acompañado por los xeques[37] de las tribus, y de los principales walíes, á una magnífica tienda alrededor de la cual habia amontonado un botin inmenso.\"},{\"heading\":false,\"text\":\"--Hé ahí poderoso y magnífico señor, dijo el mas anciano de los xeques, señalándole los despojos amontonados, la quinta parte de nuestra presa que te corresponde como emir y sultan de los creyentes.\"},{\"heading\":false,\"text\":\"Y empezó á poner de manifiesto la presa.\"},{\"heading\":false,\"text\":\"Consistia esta en dinero, en oro y plata, en cálices, copones, viriles, cruces, ornamentos y otros objetos sagrados robados á las iglesias, y por último, en una multitud de armas y de alhajas de uso particular.\"},{\"heading\":false,\"text\":\"--Buena grangería habeis hecho, dijo el rey.\"},{\"heading\":false,\"text\":\"--Nos ha costado en cambio mucha sangre, señor.\"},{\"heading\":false,\"text\":\"--Si los cristianos se dejasen entrar á saco sin resistencia, las algaras serian el mejor entretenimiento del mundo: todo tiene su precio: la presa de las algaras se paga.\"},{\"heading\":false,\"text\":\"--Allá quedan sobre la sangrienta frontera centenares de muslimes y millares de infieles.\"},{\"heading\":false,\"text\":\"--Pero no es esto lo que os he pedido.\"},{\"heading\":false,\"text\":\"--Espera, espera, señor; dentro de la tienda está la presa que han hecho los que han pasado á Africa.\"},{\"heading\":false,\"text\":\"Entró en la tienda el rey Nazar.\"},{\"heading\":false,\"text\":\"Estaba enteramente cubierta de telas de brocado: la mirra, el aloe y el incienso, formaban grandes montones; brillaban, dentro de cajas, diamantes y perlas y otras piedras preciosas. Veíanse en gran número pieles de leon y de tigre, y en el centro una gran caja llena de doblas marroquíes.\"},{\"heading\":false,\"text\":\"--Pero yo no os he pedido oro, ni perfumes, ni alhajas, ni preciosidades, dijo el rey Nazar: y ¡ay de vosotros, si solo esto habeis traido!\"},{\"heading\":false,\"text\":\"--Es, dijo el xeque, que entre africanos y españoles, te traemos justos y cabales los treinta mil esclavos.\"},{\"heading\":false,\"text\":\"--¡Los treinta mil esclavos! esclamó el rey.\"},{\"heading\":false,\"text\":\"--Sí, poderoso señor.\"},{\"heading\":false,\"text\":\"--¿Y todos fuertes y robustos?\"},{\"heading\":false,\"text\":\"--Sí, magnífico señor, porque hemos matado á los viejos, á los niños y á los enfermos.\"},{\"heading\":false,\"text\":\"--¡Treinta mil cautivos! esclamó el rey: ¡un dirahme de oro cada un dia por cada cautivo!\"},{\"heading\":false,\"text\":\"--¡Treinta mil dirahmes de oro cada un dia! murmuraron por lo bajo los circunstantes. ¿Y de dónde vá á sacar ese tesoro el rey Nazar?\"},{\"heading\":false,\"text\":\"--El rey Nazar está loco.\"},{\"heading\":false,\"text\":\"--¿Y dónde teneis esos treinta mil cautivos? dijo con ansia el rey Nazar.\"},{\"heading\":false,\"text\":\"--Al punto van á pasar por delante de tí, magnífico sultan.\"},{\"heading\":false,\"text\":\"Y saliendo algunos walíes, se oyó poco despues la música tañendo la zambra.\"},{\"heading\":false,\"text\":\"El rey Nazar, en la puerta de la tienda, á caballo, rodeado de su córte, á ambos lados los xeques y los walíes espedicionarios, empezaron á pasar por delante de él entre ginetes moros escuadronados, los cautivos.\"},{\"heading\":false,\"text\":\"Iban delante los africanos atezados y fieros en medio de su vencimiento: todos jóvenes, todos robustos, todos bravíos: su número llegaria á diez mil: venian despues los cautivos españoles, avergonzados por su derrota, pero al mismo tiempo altivos: conocíase que pertenecian á todas las clases y condiciones, desde el orgulloso noble hasta el humilde pechero: todos fuertes, todos robustos, todos jóvenes; pero impresas en las frentes de todos la desesperacion de la desgracia.\"},{\"heading\":false,\"text\":\"El rey Nazar contempló los esclavos trasportado de alegría.\"},{\"heading\":false,\"text\":\"En aquellos tiempos estos azares de la fortuna eran tan comunes, que la desolacion de un esclavo no conmovia á nadie.\"},{\"heading\":false,\"text\":\"Aquella época endurecia el corazon.\"},{\"heading\":false,\"text\":\"Por lo tanto nada tenia de repugnante la alegría del rey Nazar.\"},{\"heading\":false,\"text\":\"Cuando hubieron acabado de pasar los cautivos, el rey Nazar se volvió á los xeques y á los walíes, y les dijo:\"},{\"heading\":false,\"text\":\"--Guardaos vuestra presa por completo: yo no os he pedido oro sino cautivos; me los habeis traido y estoy satisfecho.\"},{\"heading\":false,\"text\":\"Y haciendo que se encargasen de la guarda de los cautivos los walíes de los seis mil de su guardia negra, se fué con su presa la Vega adelante.\"},{\"heading\":false,\"text\":\"--¡No quiere oro! esclamaban maravillados los espedicionarios: ¡y le hemos ofrecido una riqueza inmensa! no hay duda: ¡el rey Nazar está loco!\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Entre tanto el rey, llevando consigo su córte y sus treinta mil cautivos, custodiados por sus seis mil esclavos negros, rodeó por fuera de los muros, llegó al lecho del rio Darro, y siguió por su corriente arriba.\"},{\"heading\":false,\"text\":\"Siguiéronle la córte, los esclavos y los cautivos.\"},{\"heading\":false,\"text\":\"El rey atravesó la ciudad, se metió por las angosturas del rio, y siguió adelante.\"},{\"heading\":false,\"text\":\"--¿A dónde irá el rey? se preguntaban los señores de su córte.\"},{\"heading\":false,\"text\":\"Pero el rey seguia caminando en silencio y aguijando su caballo, siempre contra la corriente del rio.\"},{\"heading\":false,\"text\":\"El rey avanzaba, el sol habia llegado á su mayor altura, y el rey seguia aguijando á su caballo.\"},{\"heading\":false,\"text\":\"Habian quedado atrás los frondosos cármenes y las alegres alquerías, y empezaron á marchar por las anchas ramblas de la montaña, cerca del nacimiento del rio.\"},{\"heading\":false,\"text\":\"Al fin el rey dejó el lecho del rio, y trepó por el repecho de una colina deprimida y estrechísima.\"},{\"heading\":false,\"text\":\"En la cumbre de ella se detuvo.\"},{\"heading\":false,\"text\":\"--¡Mi buen alarife Kathan-ebn-Kaleb! dijo el rey Nazar dirigiéndose á un anciano que iba entre su córte.\"},{\"heading\":false,\"text\":\"--¿Qué me mandas, poderoso señor?\"},{\"heading\":false,\"text\":\"--¿Ves aquellos pinares que sombrean la sierra?\"},{\"heading\":false,\"text\":\"--Los veo, señor.\"},{\"heading\":false,\"text\":\"--¿Ves esas piedras que se amontonan sobre el lecho del rio?\"},{\"heading\":false,\"text\":\"--Sí señor.\"},{\"heading\":false,\"text\":\"--Pues bien, derroca esos pinos, levanta esas piedras, y haz aquí el aduar de los cautivos.\"},{\"heading\":false,\"text\":\"Despues revolviendo su caballo, gritó:\"},{\"heading\":false,\"text\":\"--¡Ah del alcaide de mi guardia negra!\"},{\"heading\":false,\"text\":\"Adelantó un africano atlético.\"},{\"heading\":false,\"text\":\"--Te dejo seis mil soldados: guarda con ellos mis cautivos, y ten presente, que si te falta uno solo de los treinta mil que te entrego, te corto la cabeza: ahora mis buenos amigos á Granada.\"},{\"heading\":false,\"text\":\"Y solo con su córte se volvió al Albaicin.\"},{\"heading\":false,\"text\":\"--No hay duda, decian los wazires y los sabios en vista de todo aquello: el buen rey Nazar se ha vuelto loco.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Se levantó una ciudad rústica en la colina que habia señalado el rey por aduar de sus cautivos.\"},{\"heading\":false,\"text\":\"Los pinos habian sido derrocados de la montaña, y las piedras alzadas del lecho del rio.\"},{\"heading\":false,\"text\":\"La poblacion habia sido dividida en cuarteles.\"},{\"heading\":false,\"text\":\"Al frente de cada cuartel habia un alcaide encargado de vigilar á los cautivos y de cuidar que trabajasen.\"},{\"heading\":false,\"text\":\"En solo cuatro dias el aduar habia sido levantado.\"},{\"heading\":false,\"text\":\"Los cautivos ya no tenian nada que hacer, y sus guardianes se preguntaban:\"},{\"heading\":false,\"text\":\"--¿Querrá el rey levantar en estas solitarias breñas una ciudad?\"},{\"heading\":false,\"text\":\"Y volvian á recaer en la opinion de que el rey se habia vuelto loco.\"},{\"heading\":false,\"text\":\"Se acercaba el dia que el rey Nazar habia fijado á los mecánicos para que tuviesen concluidos los treinta mil morteros de granito negro con su maza.\"},{\"heading\":false,\"text\":\"Dos dias antes, el rey Nazar convocó su córte, salió con ella de su palacio del Gallo de viento, y tomó el camino de la sierra.\"},{\"heading\":false,\"text\":\"Al llegar á Dar-al-Huet[38], encontraron los que le acompañaban escuadronados sobre una loma los treinta mil cautivos custodiados por seis mil esclavos negros de la guardia del rey Nazar.\"},{\"heading\":false,\"text\":\"A una señal del rey la guardia y los cautivos siguieron tras de la córte, y caminaron hasta que llegaron á unos altísimos barrancos, sobre los cuales brillaba el sol en cortados mármoles de mil colores distintos: aquellas eran las ricas canteras de la sierra, las canteras del rey Nazar: una maravilla de la mano de Dios.\"},{\"heading\":false,\"text\":\"Aquellos lugares, famosos hoy por sus mármoles, se llaman el barranco de San Juan.\"},{\"heading\":false,\"text\":\"Muchos de los que iban con el rey no habian visto aquel prodigio, y les maravilló su hermosura. Pero lo que mas les maravilló, fué ver en el fondo del barranco una interminable sucesion de filas de morteros de granito negro con su maza.\"},{\"heading\":false,\"text\":\"Los canteros, los menestrales, orgullosos con su gigantesca obra, salian á recibir al rey Nazar tocando sus dulzainas y atabalejos, como celebrando una gran fiesta.\"},{\"heading\":false,\"text\":\"--¿Están los treinta mil? preguntó con anhelo el rey.\"},{\"heading\":false,\"text\":\"--Sí señor, contestó el que hacia de cabeza de los mecánicos: sin faltar ni sobrar uno.\"},{\"heading\":false,\"text\":\"El rey mandó que cada cautivo tomase sobre sus hombros un mortero, y se notó que solo quedaba un mortero, cuando llegó el último cautivo.\"},{\"heading\":false,\"text\":\"Cuando al dia siguiente entró el rey en Granada con aquella estraña procesion, todos se confirmaron en que habia perdido el juicio.\"},{\"heading\":false,\"text\":\"--¿A no ser, decian algunos, que quiera moler á todos sus vasallos?\"},{\"heading\":false,\"text\":\"Pero cuando los curiosos vieron algunos dias despues que á lo largo del rio Darro, desde Granada hasta su nacimiento, se estendian los treinta mil cautivos machacando arenas sacadas del rio hasta reducirlas á polvo; cuando vieron que lavadas aquellas arenas dejaban en el fondo de los morteros partículas de oro; cuando supieron que el oro obtenido por este medio por cada esclavo, ascendia al valor de mas de una dobla, entonces el desprecio se trocó en admiracion, y todos, chicos y grandes, esclamaron:\"},{\"heading\":false,\"text\":\"--¡El rey Nazar es un sabio!\"}]},{\"title\":\"El rey nazar. — capítulo XIX: El surco del rey nazar.\",\"blocks\":[{\"heading\":false,\"text\":\"Y tenian razon.\"},{\"heading\":false,\"text\":\"El rey Nazar habia podido muy bien, para proporcionarse tesoros, oprimir á sus vasallos con impuestos; pero el rey Nazar sabia muy bien que los pueblos oprimidos suelen acabar por hacer pedazos á la mano que los oprime.\"},{\"heading\":false,\"text\":\"El rey Nazar sabia esto porque habia estudiado la historia de los tiempos y conocido las catástrofes causadas por los tiranos.\"},{\"heading\":false,\"text\":\"Además de esto, el rey Nazar queria ser amado por sus súbditos, y un rey para ser amado, necesita ser el padre de su pueblo, no su verdugo.\"},{\"heading\":false,\"text\":\"Habia preferido, pues, arrancar sus tesoros á la tierra de promision de que era rey.\"},{\"heading\":false,\"text\":\"Leyendo en una ocasion un antiguo libro romano, habia encontrado la manera de sacar el oro y la plata de las arenas de los rios.\"},{\"heading\":false,\"text\":\"El Darro era abundantísimo de oro, y el rey recurrió á él.\"},{\"heading\":false,\"text\":\"Hubiera podido tambien, estremando la tiranía, haber obligado á sus vasallos á aquel áspero trabajo de machacar arena durísima.\"},{\"heading\":false,\"text\":\"El rey prefirió que aquel rudísimo trabajo cayese sobre cautivos tomados en la tierra de sus enemigos.\"},{\"heading\":false,\"text\":\"Así es, que ningun sacrificio costaban los tesoros del rey Nazar á los naturales del reino de Granada.\"},{\"heading\":false,\"text\":\"Era, pues, un rey bueno y sabio.\"},{\"heading\":false,\"text\":\"Es verdad que las correrías de sus caballeros sobre las fronteras de los reyes con quien tenia ajustadas paces, produjeron algunas enérgicas embajadas; pero el rey Nazar contestó que no estaba en su mano el evitar aquellos sucesos, que en otras ocasiones los cristianos fronterizos hacian lo mismo con los moros, y despues de muchas idas y venidas no se volvió á hablar mas del asunto; los tratados de paz continuaron en su fuerza y vigor, y los cautivos machacando arena en las márgenes del Darro.\"},{\"heading\":false,\"text\":\"El rey Nazar era un gran rey.\"},{\"heading\":false,\"text\":\"Pero se preguntaban los que diariamente iban á ver trabajar á los cautivos:\"},{\"heading\":false,\"text\":\"--¿En qué empleará el rey Nazar tanto oro?\"},{\"heading\":false,\"text\":\"Porque todos sabian que el rey no era avaro, ni queria sus riquezas mas que para invertirlas de una manera útil y beneficiosa á su reino.\"},{\"heading\":false,\"text\":\"Habian pasado dos meses desde el dia en que los cautivos habian empezado á estraer oro de las arenas.\"},{\"heading\":false,\"text\":\"Los canteros, que por la labranza de los treinta mil morteros, habian obtenido el derecho esclusivo durante dos años á los mármoles de las canteras de la sierra, habian recibido del rey la órden de cortar grandes trozos á propósito para columnas, pavimentos y otras piezas de fábrica.\"},{\"heading\":false,\"text\":\"Aquel mármol habia sido pagado á gran precio por el oro del Darro acuñado en la Casa de la moneda.\"},{\"heading\":false,\"text\":\"--¿Qué obra irá á hacer el rey Al-Hhamar? se preguntaban los curiosos.\"},{\"heading\":false,\"text\":\"Al-Hhamar entre tanto hacia frecuentes escursiones con Yshac-el-Rumi á la Colina Roja.\"},{\"heading\":false,\"text\":\"La recorria en toda su estension, subia el repecho del monte, se estendia hasta el Cerro del Sol, bajaba hasta la Colina de Al-Bahul, y observaba todos los diferentes puntos de vista que se ofrecian desde estas alturas.\"},{\"heading\":false,\"text\":\"Al fin, un dia, se vió salir de la casa del Gallo de viento á Al-Hhamar seguido de su córte. Pero lo que mas se estrañó fué que entre la córte iban dos hermosos bueyes ayuntados, cubiertos de paramentos de seda y oro, y de penachos y campanillas de plata, y arrastrando un arado.\"},{\"heading\":false,\"text\":\"Cuando llegaron á la Colina Roja, el rey descabalgó y descabalgaron todos; el walí que guiaba la yunta la llevó por órden del rey á la parte estrema occidental de la colina; entonces el rey volvió sobre la tierra la corva punta del arado, y apoyándose fuertemente en la mancera, dijo clavando el hierro en la colina:\"},{\"heading\":false,\"text\":\"--¡Aquí será mi alcazaba!\"},{\"heading\":false,\"text\":\"Y los bueyes siguieron adelante guiados por el walí; y el rey tras ellos afirmado en la mancera y abriendo un profundo surco.\"},{\"heading\":false,\"text\":\"Asomaba el sol por cima de la Sierra Nevada, cuando la yunta empezó á andar en direccion de occidente á oriente.\"},{\"heading\":false,\"text\":\"El walí seguia guiando la yunta.\"},{\"heading\":false,\"text\":\"El rey se apoyaba en la mancera, y levantaba pedazos de tierra, acaso jamás tocada por el arado.\"},{\"heading\":false,\"text\":\"Detrás seguia la córte admirada.\"},{\"heading\":false,\"text\":\"Al llegar á la parte media de la Colina Roja, frente por frente del alto y distante monte de Aynadamar, el rey se detuvo y esclamó:\"},{\"heading\":false,\"text\":\"--¡Aquí se levantará mi trono de justicia!\"},{\"heading\":false,\"text\":\"Y luego siguió adelante.\"},{\"heading\":false,\"text\":\"--El rey Nazar vá á construir un alcázar, dijeron entre sí los cortesanos. ¿Pero por qué no lo construye allá arriba en lo alto del cerro?\"},{\"heading\":false,\"text\":\"La yunta siguió, y al llegar á un barranco torció á diestra mano, siguió la configuracion de la Colina hácia oriente, siguió torciendo á diestra mano, y al llegar á la parte media oriental de la Colina, se detuvo y dijo:\"},{\"heading\":false,\"text\":\"--¡Aquí abriré la puerta de mi alcázar sobre una torre de siete bóvedas!\"},{\"heading\":false,\"text\":\"Y siguió adelante.\"},{\"heading\":false,\"text\":\"Y los cortesanos repitieron:\"},{\"heading\":false,\"text\":\"--¿Por qué el rey no construye su fortaleza en lo mas alto?\"},{\"heading\":false,\"text\":\"Siguió la yunta marchando hácia la parte media occidental de la Colina al mismo punto donde el rey habia empezado el surco, pero antes de llegar á aquel punto se detuvo otra vez y dijo:\"},{\"heading\":false,\"text\":\"--¡Aquí se alzará la torre de la puerta por donde entrarán los que hayan menester justicia! ¡Torre y puerta del juicio se llamarán!\"},{\"heading\":false,\"text\":\"Y continuó.\"},{\"heading\":false,\"text\":\"--Pequeño alcázar construye el rey, murmuraron los cortesanos: ya han pasado los tiempos en que un Abd-el-Rahman construia la ciudad de Azarah.\"},{\"heading\":false,\"text\":\"Pero cuando el rey hubo llegado al punto de donde aquel surco habia partido, mandó que volviesen la yunta hácia el estremo occidental, del frontero cerro de Al-Bahul.\"},{\"heading\":false,\"text\":\"Habia que descender por un áspero repecho, bajar hasta la puerta donde empezaba el barrio de los Gomeles, y subir otro repecho para llegar á la Colina de Al-Bahul.\"},{\"heading\":false,\"text\":\"El walí, la yunta y el rey descendieron; cuando el rey llegó á la puerta de los Gomeles, se detuvo otra vez:\"},{\"heading\":false,\"text\":\"--¡Esta será la puerta de mis alcázares y castillos: aquí el siervo sacudirá su calzado para entrar en la morada real de su señor!\"},{\"heading\":false,\"text\":\"Y trepó por el opuesto repecho.\"},{\"heading\":false,\"text\":\"Y señaló con un surco á la redonda el cerro de Al-Bahul, y luego por la parte de oriente del cerro, abrió de nuevo el surco, trepó al cerro del Sol, siguió en un estensísimo círculo, rodeó su cumbre, abrió otro surco en el pequeño valle que separa al cerro del Sol del cerro que domina la Colina Roja, y al llegar á su estremo esclamó:\"},{\"heading\":false,\"text\":\"--¡Esta será la Silla del rey moro, su fortaleza y su atalaya, desde donde se verán sus jardines, su harem, el campo de escaramuza de sus ginetes, sus bosques y su alcázar; cascadas de aguas cristalinas se derrumbarán por las laderas, cubriendo de flores y de verdor esta tierra bravía y árida; cien torres con sus muros y treinta mil almenas, serán la coraza de esta maravilla, y sobre las ruinas del templo de los ídolos, se alzará la aljama dedicada al Dios Altísimo y único!\"},{\"heading\":false,\"text\":\"Los cortesanos no se atrevian á creer las palabras del rey, porque solo veian dentro del estendido surco que el rey Nazar habia abierto, una tierra rogiza, árida y pedregosa.\"},{\"heading\":false,\"text\":\"El rey descendió por la ladera de la Silla del moro hasta la Colina Roja, y cuando llegó á ella el sol trasponia en el occidente.\"},{\"heading\":false,\"text\":\"Al amanecer del dia siguiente un número incalculable de trabajadores, dirigidos por alarifes, á los cuales mandaba el alarife del rey, que obedecia á Yshac-el-Rumi, abrian profundos cimientos de torres y muros sobre el cerro, y una numerosa multitud de curiosos seguian maravillados aquella línea, que comprendia dentro de sí cuatro montes.\"},{\"heading\":false,\"text\":\"Granada estaba orgullosa con su rey.\"},{\"heading\":false,\"text\":\"Y eso que hasta entonces solo habia visto el surco del rey Nazar.\"}]},{\"title\":\"El mirador de la sultana. — capítulo I: ¿sultana ó esclava? ¿amante ó hija?\",\"blocks\":[{\"heading\":false,\"text\":\"Empezaron á cruzar por Granada centenares de pesadas carretas de bueyes, cargadas de mármoles labrados.\"},{\"heading\":false,\"text\":\"Veíanse las delgadas columnas de alabastro jaspeado y brillante y los bellos capiteles labrados de arabescos, y las primorosas fuentes, y las durísimas losas de mármol.\"},{\"heading\":false,\"text\":\"Acarreaban la piedra, y el ladrillo, y el estuco, y la cal.\"},{\"heading\":false,\"text\":\"En toda la estension que habia marcado el surco del rey, iban creciendo los muros y las torres, y levantándose los compartimientos, formando un verdadero laberinto.\"},{\"heading\":false,\"text\":\"Veíanse bajo tinglados de madera multitud de moros teniendo delante otros pedazos de madera, en que trazaban con el compás y con la escuadra las peregrinas labores que habian de enriquecer la obra maravillosa del rey Nazar.\"},{\"heading\":false,\"text\":\"Yshac-el-Rumi andaba entre ellos corrigiendo al uno, advirtiendo al otro, estimulando con alabanzas á los mas.\"},{\"heading\":false,\"text\":\"Por todas partes se trabajaba y la obra se veia crecer; un número incalculable de albañiles y de alarifes se empleaban en ella.\"},{\"heading\":false,\"text\":\"Los treinta mil cautivos continuaban robando su oro al Darro, y la Casa de la moneda no cesaba de acuñar aquel oro que inmediatamente se repartia entre los industriales de Granada.\"},{\"heading\":false,\"text\":\"Los cuatro montes se veian cubiertos de gente activa é incansable, y por todas partes resonaba el martillo, y por todas partes se escuchaba el sordo y contínuo ruido del pison de hierro, que hacia con tierra murallas de piedra.\"},{\"heading\":false,\"text\":\"El rey Nazar se levantaba con el alba, iba á buscar á Bekralbayda, se perdia con ella entre los bosquecillos de los jardines del harem de la casa del Gallo de viento, causando mortales angustias á su hijo el príncipe Mohammet que los veia desde su alta prision, y horribles celos á la sultana Wadah, que acechaba escondida tras las celosías de los miradores.\"},{\"heading\":false,\"text\":\"Despues de una hora de soledad con Bekralbayda, el rey Nazar iba á sentarse en su trono en la puerta de justicia del palacio del Gallo de viento: oía las quejas y las peticiones de sus súbditos; las castigaba ó premiaba, y despues de esto y de una ligera comida se trasladaba á la Colina Roja donde permanecia hasta la puesta del sol que se retiraban los trabajadores.\"},{\"heading\":false,\"text\":\"Entonces el rey se volvia á la casa del Gallo de viento, hacia su segunda comida, se encerraba en su cámara, y pasaba la noche hasta una hora avanzada leyendo antiguos libros, ó estudiando y comentando leyes.\"},{\"heading\":false,\"text\":\"La obra del Palacio-de-Rubíes crecia, pero su estraordinaria magnitud la hacia mas lenta de lo que el buen rey Nazar hubiera querido.\"},{\"heading\":false,\"text\":\"--¡Oh, señor Dios! esclamaba contristado: ¿no tendré yo vida para ver terminada y resplandeciente esta maravilla?\"},{\"heading\":false,\"text\":\"Pero habia una parte de la obra en que se habian agolpado cuantos trabajadores podian funcionar sin embarazarse los unos á los otros: los muros habian sido levantados en muy pocos dias; el interior habia sido embaldosado, alicatado, pintado, dorado y artesonado tambien en muy poco tiempo: al fin, un dia el sol pudo arrancar fúlgidos destellos de los vidrios y de las tejas de colores y de la aguja dorada de su cúpula.\"},{\"heading\":false,\"text\":\"Aquel era un pequeñito alcázar, al que el rey Nazar habia dado el nombre de Mirador de la sultana.\"},{\"heading\":false,\"text\":\"Se componia de una torrecilla que en su parte superior tenia una elegante columnata de alabastro, cerrada por la parte interior con celosías doradas.\"},{\"heading\":false,\"text\":\"Una galería con columnas semejantes é iguales celosías: tres pequeños retretes con alhamíes ó alcobas, pavimentadas de mosáicos, con las paredes labradas de preciosa y menuda labor: con leyendas del Koram y versos amorosos en sus inscripciones, con techos en que la madera imitaba de una manera maravillosa el cedro, el sándalo, el nacar, el marfil, la plata y el oro, entrelazados, combinados, dispuestos de una manera tal, que recreaban la vista y la perdian en cambiantes de luz, y en cien ingeniosas labores, formaban aquel delicioso apartamento.\"},{\"heading\":false,\"text\":\"Una escalera de mármol estrecha y como construida por el genio del misterio, conducia á otros no menos lindos compartimientos bajos, que daban á una galería semejante á la galería superior, de arcos calados sostenidos en columnas, y de aquella galería se pasaba á un jardin formado de repente, con árboles y flores trasplantados de los cármenes del Darro.\"},{\"heading\":false,\"text\":\"Las copas de los árboles frutales que se cruzaban; las galerías de cipreses y laureles que se estendian formando bóvedas, y que iban á concurrir en una cúpula de verdor, bajo la cual, en medio de un suelo cubierto de cesped, se veia una fuente de mármol de la que saltaba un rico surtidor, hacia que desde ninguna parte pudiese verse á las personas que vagaban por aquel jardin tan freco, tan sombroso, entre cuyas ramas estaban escondidos en jaulas ruiseñores y gilgueros y cuantos pájaros tienen un canto melodioso.\"},{\"heading\":false,\"text\":\"Al menos, dijo el rey Nazar cuando vió terminado aquel pequeñito alcázar, ya no moriré sin haber visto una de las maravillas de esta obra del hombre: ahora es necesario que venga á ser su alma una de las maravillas de la obra de Dios.\"},{\"heading\":false,\"text\":\"Y mandó poner en el alcázar alfombras y divanes y pabellones de oro, y cuando todo estuvo preparado, y en cada cámara una esclava, en la parte esterna; y en la parte que correspondia á los adarves de la fortaleza soldados de guarda, y en el jardin eunucos mudos, mandó trasladar á aquella primera construccion á Bekralbayda.\"},{\"heading\":false,\"text\":\"Vióse, pues un dia subir á la Colina Roja un palanquin cerrado, conducido por cuatro esclavos, y rodeado de una numerosa guardia mandada por un walí, que acompañaba al alcaide de los eunucos del rey.\"},{\"heading\":false,\"text\":\"Aquel palanquin pasó por medio de los trabajadores y fué á perderse en el pórtico del Mirador de la sultana.\"},{\"heading\":false,\"text\":\"Poco despues una jóven, cuya hermosura resplandecia mas que el deslumbrador brocado de su túnica; mas blanca que las gruesas perlas del collar que rodeaba su cuello; con los ojos mas resplandecientes que los diamantes que entrelazaban sus negrísimas trenzas, entró en las magníficas habitaciones bajas del Mirador de la sultana, acompañada del alcaide de los eunucos.\"},{\"heading\":false,\"text\":\"Aquella muger cuya hermosura resplandecia de tal modo, era Bekralbayda.\"},{\"heading\":false,\"text\":\"A pesar de lo anchuroso de los pliegues de su túnica de brocado, un ojo un tanto observador, hubiera notado que Bekralbayda estaba en cinta.\"},{\"heading\":false,\"text\":\"Este estado de maternidad, y la dulce palidez de sus megillas y lo apasionadamente melancólico de su mirada, en que ardia un fuego recóndito y casi divino, la hacian parecer mas hermosa.\"},{\"heading\":false,\"text\":\"--El poderoso, el invencible, el magnífico rey Nazar, dijo el alcaide, quiere que el lucero del amor, el sol de la hermosura, la sonrisa de Dios, el ramillete de dulzura, la esclarecida sultana Bekralbayda, vea si la contenta el alcázar que ha construido para ella.\"},{\"heading\":false,\"text\":\"--Yo no puedo llamarme ya Bekralbayda, dijo suspirando la jóven, por única contestacion á las hiperbólicas alabanzas del eunuco[39].\"},{\"heading\":false,\"text\":\"--Venturoso aquel, dijo inclinándose profundamente el eunuco, á quien dés una hermosa prenda de tus amores, estrella de las sultanas: á quien dés un príncipe poderoso ó una sultana tan hermosa como su noble madre.\"},{\"heading\":false,\"text\":\"--¡Me llamas sultana! dijo con acento de estrañeza y de gran interés Bekralbayda; ¡saludas á lo que nacerá si Allah lo permite, príncipe si es varon y sultana si es hembra! ¿Sabes tú, acaso, algo acerca de mi destino?\"},{\"heading\":false,\"text\":\"--Solo Dios sabe lo oculto, contestó inclinándose de nuevo y mas profundamente el alcaide de los eunucos.\"},{\"heading\":false,\"text\":\"--Me han puesto vestiduras régias, perlas sobre el seno, diamantes y esmeraldas en los cabellos; han puesto arracadas de gran valor en mis orejas, y ajorcas de oro, cuajadas de piedras preciosas en mis brazos; antes me han bañado en aguas olorosas, han vertido sobre mí esencias: ¿no se engalana así á las esclavas del harem á quien el señor elije para sus placeres?\"},{\"heading\":false,\"text\":\"--Pero el alcaide de los eunucos solo acompaña á las sultanas: solo las sultanas pueden llevar la piadosa empresa del rey Nazar (y el eunuco señaló con una mirada respetuosa, un roseton de diamantes y rubíes que Bekralbayda llevaba cerrando su riquísimo caftan sobre su medio desnudo seno, en el centro de cuyo roseton se veia el escudo real de Al-Hhamar, con su empresa en que se leia en caracteres africanos ¡solo Dios es vencedor!) Solo las sultanas son servidas por esclavas doncellas, y guardadas por esclavos negros: y una perla del jardin de Hiram, un rayo desprendido del sol, no puede ser esclava. Por eso te llamo sultana, alegría del mundo; por eso me humillo ante tí, lucero de los luceros.\"},{\"heading\":false,\"text\":\"Y se inclinó de nuevo.\"},{\"heading\":false,\"text\":\"--¿Pero nada seguro puedes decirme?\"},{\"heading\":false,\"text\":\"--Solo Dios sabe lo oculto, repitió el eunuco.\"},{\"heading\":false,\"text\":\"--¿Es decir que solo me acompañas para mostrarme este alcázar?\"},{\"heading\":false,\"text\":\"--Para que el esclarecido y poderoso sultan sepa si te agrada.\"},{\"heading\":false,\"text\":\"Lit de J.J. MARTINEZ Madrid LETRE dibº y Litº]\"},{\"heading\":false,\"text\":\"--Dí al noble y magnífico sultan Nazar, que para quien tiene el alma triste nada hay alegre; que para quien llora no hay nada hermoso mas que su esperanza, y que la soledad y las lágrimas son los mejores compañeros de un desventurado.\"},{\"heading\":false,\"text\":\"--Tú se lo dirás al señor, noble sultana, porque el señor se acerca: ya oigo la zambra que le saluda: el siervo no puede permanecer aquí; que Allah te acompañe y te cubra de prosperidad, luz de los cielos.\"},{\"heading\":false,\"text\":\"Y el alcaide de los eunucos hizo una profunda reverencia, se retiró andando para atrás y repitió su reverencia otras dos veces antes de desaparecer por la puerta.\"},{\"heading\":false,\"text\":\"Bekralbayda se sentó en un divan, y se replegó en sí misma, acongojada y pensativa; una dulce luz dorada que penetraba lánguida y vaga por las celosías de la cúpula, hacia brillar los diamantes de su prendido y daba un tono incitante y lascivo á la blancura de su cuello y de sus hombros desnudos; el blanco humo de un pebetero estendiéndose delante de ella, la hacia aparecer dulcemente velada y mas hermosa, con una hermosura eminentemente fantástica.\"},{\"heading\":false,\"text\":\"Y luego, aquella niña tan incitantemente hermosa, tan deliciosamente pura, con su tristeza de amor, con sus lágrimas de desconsuelo, con lo elocuente de la mirada de sus negros ojos, que se elevaban al cielo como implorando la misericordia de Dios, era una poesía viva, una poesía humana, colocada en medio de otra poesía inmóvil, muda, pero resplandeciente, como animada por la luz que hacia brillar sus arabescos dorados, sus alicatados de colores, su alfombra de oro y seda, mientras á través de una puerta se veia un fondo oscuro y misterioso, y á través de la otra las enramadas tupidas y verdes de los cenadores de jazmines y laureles, amortiguando la luz del dia, y dejando ver por alguna abertura un pedazo de cielo resplandeciente, azul, diáfano, incomparable.\"},{\"heading\":false,\"text\":\"Sintiéronse leves pasos por la parte de la puerta del fondo oscuro, y poco despues apareció en la puerta un hombre y se detuvo, se cruzó de brazos y contempló profundamente conmovido á Bekralbayda.\"},{\"heading\":false,\"text\":\"Ella ni habia sentido sus pasos ni le habia visto.\"},{\"heading\":false,\"text\":\"Un silencio profundo envolvia la cámara, silencio que solo rompian de una manera vaga por la parte del jardin, los lejanos y cadenciosos trinos de los pájaros; por la otra parte el zumbido unísono, ténue, perdido de los trabajadores.\"},{\"heading\":false,\"text\":\"El hombre que de una manera tan afectuosa, tan llena de interés, contemplaba á la jóven, era el rey Nazar.\"},{\"heading\":false,\"text\":\"Venia sencillamente vestido; únicamente brillaban en su cabeza entre su toca, las puntas de su corona, y la empuñadura de su espada entre su faja.\"},{\"heading\":false,\"text\":\"Durante algun tiempo permaneció inmóvil en su benévola contemplacion; luego adelantó y fué á sentarse silenciosamente en el mismo divan en que estaba replegada Bekralbayda, pero á cierta distancia.\"},{\"heading\":false,\"text\":\"Entonces la jóven pareció despertar de un sueño, se estremeció, levantó la cabeza, fijó una mirada ansiosa en el rey Nazar, y cruzando la manos, esclamó:\"},{\"heading\":false,\"text\":\"--¡Ah, señor!\"},{\"heading\":false,\"text\":\"--¡Yo te amo! dijo negligentemente el rey Nazar.\"},{\"heading\":false,\"text\":\"Bekralbayda se puso de pie, mas pálida aun que lo que estaba, aterida, muda, como aniquilada; guardó durante algunos momentos silencio, y luego esclamó:\"},{\"heading\":false,\"text\":\"--¡Pero yo no puedo amarte... no!... ¡no puedo amarte como tú quieres que te ame... no! ¡Allah, el grande, el poderoso Allah lo sabe: no puedo amarte así!\"},{\"heading\":false,\"text\":\"--Cuando te confesé mi amor, dijo reposadamente el rey Nazar, tú me contestaste...\"},{\"heading\":false,\"text\":\"--¡Mentí! ¡mentí! esclamó toda asustada Bekralbayda.\"},{\"heading\":false,\"text\":\"--Cuando te confesé mi amor, continuó impasible el rey, me dijiste, quiero ser sultana.\"},{\"heading\":false,\"text\":\"--¡Ah, misericordioso Dios! ¡Mentí!\"},{\"heading\":false,\"text\":\"--Yo te dije: en buen hora sea: Dios te ha dado en sus bondades una hermosura superior á la de las mugeres de la tierra; eres una hurí que el Altísimo ha permitido aliente en las entrañas de una muger: digna eres de ser sultana: mi esposa la sultana Wadah, ha enloquecido... está apartada de mí: tú ocuparás el lugar de la sultana Wadah, que por su locura se la puede considerar muerta.\"},{\"heading\":false,\"text\":\"--¡Ah, poderoso señor!\"},{\"heading\":false,\"text\":\"--Tú sabes que la locura de la sultana Wadah es verdad.\"},{\"heading\":false,\"text\":\"--La sultana Wadah es muy desdichada: la sultana Wadah llora una hija perdida.\"},{\"heading\":false,\"text\":\"--¡Una hija! esclamó, levantándose aterrado, trémulo, herido como por un rayo por aquella terrible revelacion, el rey Nazar. ¿Quién te ha dicho que la sultana Wadah ha perdido una hija?\"},{\"heading\":false,\"text\":\"--¡Qué! ¿no has perdido tú tambien tu hija, poderoso señor? esclamó aterrada por su imprudencia Bekralbayda.\"},{\"heading\":false,\"text\":\"--Yo no he tenido de la sultana Wadah mas que un hijo: el príncipe Juzef, contestó con voz cavernosa el rey Nazar.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡yo me he engañado! ¡yo me he engañado! esclamó trémula la jóven.\"},{\"heading\":false,\"text\":\"--Tú no sabes mentir: dijo severamente el rey.\"},{\"heading\":false,\"text\":\"--¡Ah, señor!\"},{\"heading\":false,\"text\":\"--Tú eres cándida y pura como la azucena de los valles.\"},{\"heading\":false,\"text\":\"--Yo me he engañado.\"},{\"heading\":false,\"text\":\"--Pero... ¿por qué te has engañado?\"},{\"heading\":false,\"text\":\"--Yo he visto á la sultana buscar una rosa blanca.\"},{\"heading\":false,\"text\":\"--¡Ah!\"},{\"heading\":false,\"text\":\"--Yo la he escuchado decir...\"},{\"heading\":false,\"text\":\"--¡Oh! ¿qué has escuchado?...\"},{\"heading\":false,\"text\":\"--¡Mi rosa blanca! ¡la rosa de mis entrañas!\"},{\"heading\":false,\"text\":\"--¿Y no has escuchado mas?\"},{\"heading\":false,\"text\":\"--¿Y á qué puede llamar una muger la flor de sus entrañas, sino á su hija? esclamó cubriéndose de un vivísimo rubor Bekralbayda.\"},{\"heading\":false,\"text\":\"--Sí, sí, te has engañado, dijo el rey Nazar reprimiéndose, volviendo á la tranquila y benévola espresion de su semblante, y sentándose de nuevo en el divan: ¡la rosa blanca! esa es una manía de la sultana.\"},{\"heading\":false,\"text\":\"--¡Infeliz! murmuró Bekralbayda.\"},{\"heading\":false,\"text\":\"--La locura de la sultana Wadah me obliga á tomar otra esposa, te dije: puesto que quieres ser sultana, lo serás.\"},{\"heading\":false,\"text\":\"--¡Yo mentia! repitió Bekralbayda.\"},{\"heading\":false,\"text\":\"--Luego, continuó el rey, añadiste: no me basta ser sultana: yo quiero que me dés un alcázar tan hermoso como no le hayan visto ojos humanos: cuando me dés ese alcázar seré tuya.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡no! ¡no!\"},{\"heading\":false,\"text\":\"--Yo he mandado fabricar este alcázar, una de cuyas pequeñísimas partes es la que ocupamos...\"},{\"heading\":false,\"text\":\"--¡Pues bien! acaba ese alcázar, señor... y entonces...\"},{\"heading\":false,\"text\":\"--Este alcázar, que será la maravilla de las gentes, no puedo terminarlo yo, ni lo verá terminado mi hijo ni mi nieto; si para cuando esté terminado este alcázar has de darme tus amores... seria preciso que Dios parase para nosotros solos el tiempo y que le apresurase para los demás.\"},{\"heading\":false,\"text\":\"--Pero lo que yo te he prometido no me obliga hasta que hayas cumplido tu promesa: hasta que hayas terminado el Palacio-de-Rubíes: si para entonces hemos muerto, la culpa no es mia.\"},{\"heading\":false,\"text\":\"--¡Cuán mal parece la mentira en boca tan hermosa! dijo el rey Nazar.\"},{\"heading\":false,\"text\":\"Ruborizóse Bekralbayda.\"},{\"heading\":false,\"text\":\"--¡Ah señor! si yo miento, esclamó arrojándose á sus pies, es porque la mentira es la única arma que tengo para defenderme de tí.\"},{\"heading\":false,\"text\":\"El rey Nazar la levantó dulcemente y la sentó junto á sí.\"},{\"heading\":false,\"text\":\"--¿Piensas, la dijo, que si yo quisiera te podrias defender de mí?\"},{\"heading\":false,\"text\":\"--El generoso, el grande, el vencedor, el magnífico Nazar, no puede ni debe amar á una desdichada que no puede amarle.\"},{\"heading\":false,\"text\":\"--Y... ¿por qué no puedes amarme?\"},{\"heading\":false,\"text\":\"--¡Porque amo á otro! esclamó con desesperacion Bekralbayda, ¡porque mi alma está en la suya! ¡porque llevo en mis entrañas la flor de mis amores!\"},{\"heading\":false,\"text\":\"Y Bekralbayda se cubrió el rostro con las manos y rompió á llorar.\"},{\"heading\":false,\"text\":\"El rey Nazar sintió que sus ojos se arrasaban: se dominó, apartó las manos de la jóven de su rostro, y no pudiendo contenerse, inflamado de un amor inmenso, no á la muger, sino á la madre de su nieto, la atrajo á sí y la estrechó entre sus brazos esclamando conmovido:\"},{\"heading\":false,\"text\":\"--¡Ah! ¡hija mia! ¡hija de mi alma!\"},{\"heading\":false,\"text\":\"Y luego, como pesaroso de haberse dejado arrastrar de su corazon, separó de sí á Bekralbayda, compuso su semblante, recobró su impasibilidad, aunque aparente, y dijo:\"},{\"heading\":false,\"text\":\"--¿Amas á un hombre y eres madre?\"},{\"heading\":false,\"text\":\"--Tú me has llamado hija, señor; esclamó con ansiedad Bekralbayda.\"},{\"heading\":false,\"text\":\"--¡Yo! ¡que yo te he llamado hija! ¡no sabes que te quiero para esposa!\"},{\"heading\":false,\"text\":\"--¡Y serias tú, poderoso sultan de los creyentes, esposo de una muger que ama á otro hombre, que ha sido suya, y que es madre!\"},{\"heading\":false,\"text\":\"--Yo te amo sobre todas las cosas: no importa que ames, si morando en mi alcázar no vuelves á ver al hombre á quien amas, no importa que seas madre... porque todos creerán que ese hijo es mio: eres mi esclava.\"},{\"heading\":false,\"text\":\"--¡Me matarás! ¡puedes matarme! ¡pero no puedes hacer que yo olvide mi amor, que yo le ofenda! ¡no! ¡no! esclamó Bekralbayda desesperada.\"},{\"heading\":false,\"text\":\"--Escucha, dijo el rey: te cubriré de oro y perlas: te daré esclavas á millares: te rodearé de cuanta grandeza puede disponer un rey tan poderoso como yo.\"},{\"heading\":false,\"text\":\"--¡No! esclamó con energía Bekralbayda.\"},{\"heading\":false,\"text\":\"--No volverás á ver á ese hombre.\"},{\"heading\":false,\"text\":\"--Pero le guardaré su amor, mi pureza dentro de mi alma como en un santuario.\"},{\"heading\":false,\"text\":\"--Yo buscaré á ese hombre y le mataré.\"},{\"heading\":false,\"text\":\"--El querrá morir mejor que verme en tus brazos.\"},{\"heading\":false,\"text\":\"--Cuando nazca tu hijo te lo quitaré.\"},{\"heading\":false,\"text\":\"--Me volveré loca como la sultana Wadah, y llamaré en mi delirio á la flor de mis amores, pero no seré tuya.\"},{\"heading\":false,\"text\":\"El rey Nazar se estremeció.\"},{\"heading\":false,\"text\":\"--¿Y si yo matase á tu hijo?\"},{\"heading\":false,\"text\":\"--Por la vida de mi hijo no mataré á su padre.\"},{\"heading\":false,\"text\":\"--¿Pero estás segura de que ese hombre merece tu amor?\"},{\"heading\":false,\"text\":\"--¡Oh! yo soy para él la luz, la alegría, la vida.\"},{\"heading\":false,\"text\":\"--¿Y si por acaso no pudiera ser tu esposo?\"},{\"heading\":false,\"text\":\"--Seria su esclava.\"},{\"heading\":false,\"text\":\"--¿Quién es ese hombre á quien tanto amas? esclamó afectando un furor que no sentia el rey Nazar, como no ignoraba que el hombre á quien amaba Bekralbayda, era su hijo el príncipe Mohammet.\"},{\"heading\":false,\"text\":\"--El hombre á quien amo... es un mancebo humilde... pobre... pero yo le amo así... y no le cambiaria por todos los sultanes de la tierra...\"},{\"heading\":false,\"text\":\"--¿Qué, amas así á?...\"},{\"heading\":false,\"text\":\"El rey Nazar se detuvo; iba á decir, ¡á mi hijo!\"},{\"heading\":false,\"text\":\"--Quítame, señor, dijo la jóven, estas galas de sultana, estas alhajas; no me dés para vivir este rico alcázar; no me saques de la condicion de esclava: déjame sola, pobre con mi amor, y te bendeciré.\"},{\"heading\":false,\"text\":\"--Tú serás sultana, dijo el rey Nazar.\"},{\"heading\":false,\"text\":\"--¡Ah señor! ¡ten compasion de mí!\"},{\"heading\":false,\"text\":\"--Tú serás sultana, repitió el rey Nazar y salió.\"},{\"heading\":false,\"text\":\"Bekralbayda quedó anonadada.\"},{\"heading\":false,\"text\":\"En tanto el rey murmuraba saliendo:\"},{\"heading\":false,\"text\":\"--Es digna de mi hijo: digna de la corona de Granada: sultana será y sultan mi hijo... ¡pero esa hija perdida de Wadah!... ¡ese misterio! ¡si Allah me ayuda, ese misterio ha de aclararse ante mis ojos!... y si fuera... ¡ah! ¡si fuera ella!... ¡si Bekralbayda fuera esa hija!\"},{\"heading\":false,\"text\":\"El rey Nazar se perdió poco despues entre los trabajadores del alcázar.\"}]},{\"title\":\"El mirador de la sultana. — capítulo II: La mejor noche del rey nazar.\",\"blocks\":[{\"heading\":false,\"text\":\"El rey se encaminó á la tienda que desde que principiaron las obras se habia levantado para él en la Colina Roja.\"},{\"heading\":false,\"text\":\"Entró en ella, arrojóse en un divan, y quedó profundamente pensativo.\"},{\"heading\":false,\"text\":\"--Desde el momento en que descubrí, murmuraba, que mi hijo era el amante de Bekralbayda, el horror que me inspiró el solo pensamiento de robar á mi hijo su amante, me curó de todo punto del amor que tenia hácia ella. Es verdad que la he enamorado, que he pretendido probar si es digna de ser sultana de Granada... y ha respondido á la prueba: ahora la amo como si fuera mi hija; y despues que he sabido que es madre... ¡oh! el amor de otro nuevo hijo de mi sangre... de un descendiente de mi raza, que será como ella hermoso, y valiente y gallardo como él, porque será un príncipe, Dios me favorece: pero esa revelacion de Bekralbayda... _¡lo que ha vuelto loca á la sultana Wadah, es la pérdida de una hija!..._ una muger vé mejor que un hombre en el alma de otra muger: ella no se engaña: yo recuerdo... el dia en que desapareció de mi lado Leila-Radhyah, se encontraron en sus habitaciones manchas de sangre: aquel mismo dia desapareció uno de mis esclavos y Wadah se volvió de repente loca: desde entonces han pasado diez y siete años... la edad de Bekralbayda... Yshac-el-Rumi es un hombre misterioso. De una manera misteriosa me ha entregado á Bekralbayda... ese hombre á quien he hecho seguir, ha sido visto alguna vez en los cármenes del Darro acompañado de una muger... ¡oh! ¡esta misma noche! sí... sí... ¡esta misma noche!\"},{\"heading\":false,\"text\":\"El rey esperó con impaciencia á que el sol traspusiese: se fué como de costumbre á su palacio de la torre del Gallo de viento, y exhaló un suspiro cuando vió el reflejo de la luz en las ventanas de la torre donde continuaba preso el príncipe Mohammet.\"},{\"heading\":false,\"text\":\"Luego entró en su cámara, comió como de costumbre, se quitó la corona y las vestiduras reales, púsose unos vestidos cortos y sencillos, se rebozó en un albornoz, y salió de su palacio por una puerta escusada y solo.\"},{\"heading\":false,\"text\":\"La noche era oscura: el rey, embozado en su alquicel negro, se deslizó como una sombra junto á los muros de la alcazaba Cadima, llegó al barrio del Hajeriz, descendiendo por sus pendientes calles, llegó al valle donde corre el Darro y siguiendo su corriente arriba, se metió por las angosturas.\"},{\"heading\":false,\"text\":\"Muy pronto llegó á la casita del remanso.\"},{\"heading\":false,\"text\":\"--Aquí es: este me han dicho es el sitio donde Yshac-el-Rumi desaparece por la entrada de una cueva y vuelve á aparecer allá arriba sobre las cortaduras, acompañado de una muger enlutada como él; es necesario buscar la entrada de esa cueva: frente á la casa del remanso me han dicho que tiene la entrada: pero la noche es demasiado oscura... no importa, Dios me guiará; Dios que conoce el pensamiento que me trae aquí.\"},{\"heading\":false,\"text\":\"En efecto, el rey encontró despues de algun tiempo la entrada de la cueva que buscaba.\"},{\"heading\":false,\"text\":\"Pero al penetrar por ella oyó un sordo ruido; el batir de las alas de un pájaro que pasó junto á él rozándole el rostro con las estremidades de las plumas.\"},{\"heading\":false,\"text\":\"El rey se detuvo y se estremeció:\"},{\"heading\":false,\"text\":\"--¡El buho! ¡siempre ese pájaro maldito que me persigue! pero no importa, añadió sobreponiéndose á su terror: el Altísimo y único, el amparador de quien le confiesa y le adora me ayudará.\"},{\"heading\":false,\"text\":\"Y penetró resueltamente en la cueva.\"},{\"heading\":false,\"text\":\"Al entrar en ella, vió á sus pies como en el fondo de una sima, una línea de luz como la que puede verse un momento á través de una puerta que se cierra.\"},{\"heading\":false,\"text\":\"--¡Oh! esclamó el rey, aquí moran séres humanos. He visto cerrarse allá abajo una puerta, y he creido escuchar despues los pasos de la persona que ha cerrado esa puerta que se alejaban. ¡Oh, señor, fuerte y misericordioso! ¡ampárame!\"},{\"heading\":false,\"text\":\"Y el rey Nazar palpó, encontró la entrada de una estrecha comunicacion subterránea, y al poner el pié en ella, notó que el piso era pendiente y resvaladizo.\"},{\"heading\":false,\"text\":\"El rey Nazar se asió á las escabrosidades naturales de uno de los costados de aquel pasage tenebroso, y descendió ayudando con las manos, que se asian fuertemente á la roca, á los pies que resvalaban sobre la pendiente.\"},{\"heading\":false,\"text\":\"Al fin, despues de haber descendido algun espacio, tropezó con la roca áspera y cortada que le cerraba el paso.\"},{\"heading\":false,\"text\":\"El rey Nazar palpó: la escavacion ó el seno terminaba allí: no tenia continuacion.\"},{\"heading\":false,\"text\":\"--Aquí debe haber una puerta oculta, dijo el rey; yo he visto cerrarse esa puerta. Pues bien, suceda lo que quiera, no he de retroceder.\"},{\"heading\":false,\"text\":\"Y desnudando su puñal dió un fuerte golpe con su pomo sobre una piedra saliente que estaba incrustada en la roca.\"},{\"heading\":false,\"text\":\"Pero en vez de sonar como piedra al toque del rey Nazar, respondió un sonido vibrante, metálico como el de una campana.\"},{\"heading\":false,\"text\":\"--¡Oh poderoso señor! esclamó el rey, ó aquí hay encantamento, ó he dado por acaso en un lugar que sirve para llamar á los que conocen el secreto: encantamento ó realidad preparémonos.\"},{\"heading\":false,\"text\":\"Y el rey se desprendió rápidamente parte de la toca blanca que ceñía su cabeza, y la cruzó sobre su rostro, no dejando mas que un estrecho resquicio para su ojo derecho.\"},{\"heading\":false,\"text\":\"Acababa el rey de encubrirse, cuando resonaron leves y casi perdidos al otro lado de la roca, pasos de muger: oyóse luego un rechinamiento áspero, como el del hierro sobre la piedra, brilló entre la oscuridad una línea de luz, y se abrió una puerta.\"},{\"heading\":false,\"text\":\"Delante del rey Nazar, con sus flotantes cabellos negros, sus ojos, su mirada profunda y melancólica, y su ancha y suelta túnica de lana, estaba la Dama blanca con una lámpara en la mano.\"},{\"heading\":false,\"text\":\"El rey se estremeció: contuvo un grito y un movimiento, y permaneció inmóvil.\"},{\"heading\":false,\"text\":\"--¿A quién buscas? dijo la Dama blanca.\"},{\"heading\":false,\"text\":\"--A tí, contestó el rey con acento conmovido y alterado.\"},{\"heading\":false,\"text\":\"--¿Quién te envia?\"},{\"heading\":false,\"text\":\"Detúvose un momento el rey, y meditando que acaso aquella muger no conocia otra persona que al astrólogo, contestó.\"},{\"heading\":false,\"text\":\"--Me envia el sábio Yshac-el-Rumi.\"},{\"heading\":false,\"text\":\"--Ven conmigo, dijo la Dama blanca.\"},{\"heading\":false,\"text\":\"Y siguió adelante por una estrecha mina abierta en la roca.\"},{\"heading\":false,\"text\":\"Poco despues llegaron á una puerta forrada de hierro, que empujó la dama, y al fin se encontró con ella el rey Nazar en la misma cámara blanca y dorada, donde el príncipe habia vuelto en sí algun tiempo antes.\"},{\"heading\":false,\"text\":\"--Espera aquí, dijo la Dama blanca dejando sobre un nicho calado la lámpara que tenia en la mano y desapareciendo por una puerta.\"},{\"heading\":false,\"text\":\"--¡Oh poderoso señor, esclamó el rey cuando se vió solo, y cuán incomprensibles son tus decretos! ¡por cuán torcidos caminos llevas al hombre de la mano!\"},{\"heading\":false,\"text\":\"Y el rey se sentó en el lecho y quedó meditando profundamente en la estraña aventura en que se encontraba empeñado.\"},{\"heading\":false,\"text\":\"Pasó un largo rato: al cabo oyó el rey el paso de una muger acompañado del crugir de una túnica de seda; abrióse al fin la puerta y apareció la Dama blanca, ó mas bien una hurí descendida del paraiso.\"},{\"heading\":false,\"text\":\"El rey se puso de pié de una manera involuntaria, y dió un paso hácia la dama como si le hubiera atraido su hermosura.\"},{\"heading\":false,\"text\":\"Porque la Dama blanca se habia transformado: es verdad que su semblante y su cuello y sus hombros aparecian un tanto enflaquecidos, sumamente pálido su semblante, estraordinariamente melancólicos sus ojos, pero esto aumentaba su hermosura, dándola el encanto del sufrimiento.\"},{\"heading\":false,\"text\":\"Y luego su peinado, y sus joyas y sus magníficas vestiduras...\"},{\"heading\":false,\"text\":\"Las anchas y largas trenzas de sus cabellos, brillantes por sí mismos, aumentado su brillo por las piedras preciosas que los salpicaban, estaban entrelazadas alrededor de una riquísima diadema de sultana: pendia de su cuello un ancho collar de rosetones de diamantes y perlas; cubria apenas su seno la parte superior de una túnica finísima de lino bordado con plata; sobre esta túnica llevaba otra de seda verde, recamada de bordaduras de oro, ancha, flotante, larga hasta tocar el pavimento, cayendo sobre él en una magnífica plegadura; sobre esta túnica tenia otra larga, solo hasta las rodillas, de brocado blanco, con bordaduras de aljófar, ciñéndose sobre la redonda y esbelta cintura de la dama, por un joyel de pedrería y cerrándose sobre el pecho con herretes de esmeraldas; por último, un caftan ó sobretodo que no pasaba de las rodillas, de anchas mangas perdidas de seda roja cubierta de arabescos negros, dos magníficas ajorcas ó brazaletes de pedrería, y unas ricas y deslumbrantes arracadas completaban el atavío y el prendido de la Dama blanca, transformada por su maravilloso traje en sultana.\"},{\"heading\":false,\"text\":\"--Estoy pronta, dijo la dama tomando de sobre un divan un ancho albornoz de lana blanca y cubriéndose con él enteramente hasta el punto de que solo se veia bajo él la orla de la rozagante túnica verde: estoy pronta y te sigo.\"},{\"heading\":false,\"text\":\"--Sácame antes de aquí, dijo el rey Nazar, cuya voz se mostraba á cada momento mas conmovida.\"},{\"heading\":false,\"text\":\"--Ven conmigo, dijo la dama.\"},{\"heading\":false,\"text\":\"La dama tomó la lámpara, atravesó, precediendo al rey Nazar, algunas habitaciones, subió por unas escaleras, y en fin, por los mismos lugares por donde habia conducido en otra ocasion al príncipe Mohammet, salió al aire libre, atravesó una calle de árboles, llegó á una cerca, abrió un postigo, salió con el rey, cerró el postigo, y dijo:\"},{\"heading\":false,\"text\":\"--Estamos en el campo: cúmpleme tu promesa.\"},{\"heading\":false,\"text\":\"--¿Qué te ha dicho que yo he prometido Yshac-el-Rumi?\"},{\"heading\":false,\"text\":\"--Me ha dicho, contestó con una estrañeza recelosa la dama, que tú me llevarias al alcázar que ha construido el rey para Bekralbayda.\"},{\"heading\":false,\"text\":\"--Cumpliré mi promesa, dijo el rey, pero ásete á mi brazo, sultana: la noche está oscura.\"},{\"heading\":false,\"text\":\"--Pero pronto saldrá la luna, dijo la dama, y es necesario aprovechar la oscuridad.\"},{\"heading\":false,\"text\":\"Y se asió al brazo del rey.\"},{\"heading\":false,\"text\":\"--¿Por qué me has llamado sultana? dijo la dama.\"},{\"heading\":false,\"text\":\"--¿Por qué?... porque puedes y debes ser la sultana de la hermosura.\"},{\"heading\":false,\"text\":\"--Conócese, dijo con alguna severidad la dama, que estás acostumbrado á adular á las esclavas de tu señor.\"},{\"heading\":false,\"text\":\"--En alabarte no hay adulacion: el lenguaje de los hombres no puede ponderar tu hermosura.\"},{\"heading\":false,\"text\":\"--¿Eres tú el alcaide de los eunucos del rey Nazar? dijo creciendo en recelo la dama.\"},{\"heading\":false,\"text\":\"--Sí, contestó el rey sin vacilar.\"},{\"heading\":false,\"text\":\"--¡Es estraño! murmuró ella.\"},{\"heading\":false,\"text\":\"Y guardó silencio.\"},{\"heading\":false,\"text\":\"--¿Dónde me llevas? dijo al fin: paréceme que nos alejamos en direccion opuesta á la Colina Roja, donde el rey Nazar ha construido ese alcázar donde enamora á Bekralbayda.\"},{\"heading\":false,\"text\":\"--Voy á ganar la espesura por cima de los cármenes, dijo el rey, toda precaucion es poca.\"},{\"heading\":false,\"text\":\"--Pero este terreno es muy áspero.\"},{\"heading\":false,\"text\":\"--Apóyate bien en mi brazo, sultana, y si no bastare, yo te llevaré sobre mis hombros.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡no! ¡sigamos! ¡anhelo llegar!\"},{\"heading\":false,\"text\":\"--¡Anhelas llegar! ¿puede un esclavo atreverse á preguntarte?\"},{\"heading\":false,\"text\":\"--¿Acostumbran los esclavos del rey á entrometerse en los secretos de su señor, ó es que no basta el oro que te se ha dado y necesitas mas para ser respetuoso?\"},{\"heading\":false,\"text\":\"--¡Oh Dios misericordioso! ¡perdona si te he ofendido, sultana!\"},{\"heading\":false,\"text\":\"La dama siguió andando y no contestó.\"},{\"heading\":false,\"text\":\"--Dime, dijo al cabo de un breve espacio de silencio: ¿el rey ama á Bekralbayda?\"},{\"heading\":false,\"text\":\"--No.\"},{\"heading\":false,\"text\":\"--¡Que no la ama!\"},{\"heading\":false,\"text\":\"--El rey no puede amar á la que destina por esposa á su hijo el príncipe Mohammet.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿te ha dicho eso el rey?\"},{\"heading\":false,\"text\":\"--El rey me favorece con su confianza.\"},{\"heading\":false,\"text\":\"--¡Pero... si el rey enamora á Bekralbayda!\"},{\"heading\":false,\"text\":\"--El rey solo ha querido probar si Bekralbayda es digna de ser esposa de su hijo, y la ha finjido amores, y la ha prometido tesoros. Bekralbayda aunque ignora que el rey sabe sus amores con el príncipe, ha resistido á todas las tentaciones. ¡Oh! ¡sí! ¡es digna de ser sultana, y lo será!\"},{\"heading\":false,\"text\":\"Guardó de nuevo silencio la dama.\"},{\"heading\":false,\"text\":\"--¿A quién ama el rey Nazar? dijo.\"},{\"heading\":false,\"text\":\"--A una muger por quien llora hace diez y siete años.\"},{\"heading\":false,\"text\":\"--Mientes; mas de diez y siete años hace que el rey Nazar hizo su esposa á la sultana Wadah: la adoraba; ha tenido de ella...\"},{\"heading\":false,\"text\":\"--Ha tenido de ella un hijo, y ese hijo tiene ya veinte años. Hace diez y siete que la sultana Wadah está loca, y que el rey llora á sus solas, cuando nadie puede burlarse de su llanto, por una muger.\"},{\"heading\":false,\"text\":\"--Pero se consuela con las esclavas de su harem.\"},{\"heading\":false,\"text\":\"--El rey Nazar tiene harem porque es rey; pero jamás pasa sus puertas: el rey Nazar tiene el alma cubierta de luto.\"},{\"heading\":false,\"text\":\"--¿Por la muger que le arrebataron hace diez y siete años? dijo alentando apenas la dama.\"},{\"heading\":false,\"text\":\"--El rey encontró sangre en el retrete de la luz de sus ojos, del alma de su alma, de su adorada Leila-Radhyah; pero su alma habia desaparecido: el rey lloró y llora: el rey daria su grandeza y su vida por volverla la existencia.\"},{\"heading\":false,\"text\":\"La dama no contestó una sola palabra.\"},{\"heading\":false,\"text\":\"--¿Dónde me llevas? dijo con cuidado la dama viendo que el rey se alejaba cada vez mas: la luna empieza á salir.\"},{\"heading\":false,\"text\":\"--Allí hay un bosquecillo de avellanos, contestó el rey; necesito hablarte donde nadie nos pueda oir.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿necesitas hablarme? ¿pues qué, hay alguna dificultad para lo que deseo?\"},{\"heading\":false,\"text\":\"--Tal vez.\"},{\"heading\":false,\"text\":\"--¿Por qué tiemblas?\"},{\"heading\":false,\"text\":\"--¡Ah! ¿y quién no temblará á tu lado, asido á tu brazo, reina del amor?\"},{\"heading\":false,\"text\":\"--¿Qué esto? dijo la dama con terror y con orgullo, ¡tú no puedes ser el enviado de Yshac-el-Rumi!\"},{\"heading\":false,\"text\":\"--¡Oh! ¡la luna sale! ¡espera, espera á que descubra enteramente su disco y te contestaré!\"},{\"heading\":false,\"text\":\"--No daré ni un paso mas, dijo con terror y con cólera la dama, ¿quién eres? tú no eres el alcaide de los eunucos, ó si lo eres, eres un miserable, un traidor.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡la luna! ¡la luna!\"},{\"heading\":false,\"text\":\"--¡Vuélveme, vuélveme á mi asilo! esclamó la dama pugnando por desasirse del rey que la detenia.\"},{\"heading\":false,\"text\":\"--¡Volver, volver á donde otros puedan verme á tu lado! ¡oh! Dios me ha traido hasta ti: Dios quiere que solo él sea testigo de lo que vá á suceder entre los dos.\"},{\"heading\":false,\"text\":\"--¿Y qué puede suceder?.. esclamó con terror la dama.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡mi amor y tu hermosura! ¡Dios misericordioso! ¿y cómo podia esperar yo tanta felicidad?\"},{\"heading\":false,\"text\":\"--¿Qué dice este hombre? esclamó en el colmo de su terror la dama.\"},{\"heading\":false,\"text\":\"--¡La luna! ¡héla allí, llena y resplandeciente que se presenta en toda la plenitud de su belleza, para alumbrar á mis amores, para brillar una vez sobre mis lágrimas de alegría, como ha brillado tantas otras sobre mis lágrimas desesperadas!\"},{\"heading\":false,\"text\":\"--¡Ah! ¡has cambiado de voz, fingías el acento! ¡yo... yo recuerdo tu acento!.. ¿quién eres? esclamó trémula la dama.\"},{\"heading\":false,\"text\":\"--¿Te has engalanado para deslumbrar con tu hermosura al rey Nazar, no es verdad, luz de mis ojos? dijo el rey.\"},{\"heading\":false,\"text\":\"--¡Quién eres! dijo la dama con doble ansiedad.\"},{\"heading\":false,\"text\":\"--Y el rey Nazar sentiria romperse su corazon de gozo, de felicidad, aunque solo te hubieras presentado ante él, con tu hermosa crencha negra suelta, y suelta tu túnica de luto, alma de mi vida, mi infortunada, mi hermosa, mi sultana, Leila-Radhyah.\"},{\"heading\":false,\"text\":\"La dama dió un grito de sorpresa, de angustia, de ansiedad, y arrancó la toca de sobre el semblante del rey en que reflejó de lleno la luz de la luna.\"},{\"heading\":false,\"text\":\"--¡Ah!.. ¡ah!.. ¡Dios poderoso!.. ¡Nazar!\"},{\"heading\":false,\"text\":\"Esclamó y se desmayó entre los brazos del rey.\"},{\"heading\":false,\"text\":\"Encontrábanse junto á una fuente á la entrada de una espesura de avellanos, en una meseta de la montaña; veian desde allí á lo lejos el Albaicin y la parte de la Colina Roja donde se alzaba el pequeñito alcázar habitado por Bekralbayda.\"},{\"heading\":false,\"text\":\"El rey Nazar llevó á Leila-Radhyah, á la única muger á quien habia amado, á la que habia llorado muerta, á la que habia cambiado su nombre por el de Maga de las humbrías, al lado de la fuente y la roció el rostro con agua.\"},{\"heading\":false,\"text\":\"Pero Leila-Radhyah no volvia en sí; gemia como si demasiado comprimido su corazon estuviese próximo á romperse.\"},{\"heading\":false,\"text\":\"El rey estaba aterrado y redoblaba sus esfuerzos para hacerla volver en sí; al fin, Leila-Radhyah abrió los ojos, se incorporó entre los brazos del rey Nazar, le miró faz á faz, y se pasó las manos por la frente como si hubiese pretendido volver en sí de un sueño.\"},{\"heading\":false,\"text\":\"Luego esclamó con un acento profundamente conmovido, ardiente, enamorado, loco:\"},{\"heading\":false,\"text\":\"--¡Oh! ¡señor, señor! ¡es él! ¡es él! ¡mi Nazar!\"},{\"heading\":false,\"text\":\"Y se arrojó á su cuello, le retuvo en sus brazos, y rompió á llorar; pero en un llanto de alegría.\"},{\"heading\":false,\"text\":\"--¡Oh! esclamaba entre sus lágrimas con un acento indefinible, de amor y de alegría, ¡me ha creido muerta y no me ha olvidado!\"},{\"heading\":false,\"text\":\"--Yo ví sangre en tu retrete, contestó el rey Nazar.\"},{\"heading\":false,\"text\":\"--¡Oh! sí, dijo Leila-Radhyah: fué una noche horrible... horrible... mira rey mio, señor de mi alma: mira.\"},{\"heading\":false,\"text\":\"Y Leila-Radhyah se abrió con una mano trémula de impaciencia la túnica interior y mostró al rey las señales de tres anchas puñaladas.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡qué horror!.. y... ¿quién fué? preguntó con acento cobarde el rey...\"},{\"heading\":false,\"text\":\"--¡Ella, ella, la hechicera, la maldita!.. contestó Leila-Radhyah.\"},{\"heading\":false,\"text\":\"--¡Wadah! murmuró el rey.\"},{\"heading\":false,\"text\":\"--¡Sí, sí, Wadah, esa terrible hechicera sedienta de sangre! ¿Y sabes tú para qué me he puesto yo estas ropas, estas joyas, esta diadema?..\"},{\"heading\":false,\"text\":\"--¡Oh! ¡no!\"},{\"heading\":false,\"text\":\"--Para impedir un nuevo crímen.\"},{\"heading\":false,\"text\":\"--¡Un nuevo crímen!\"},{\"heading\":false,\"text\":\"--Sí: para impedir que se lleve á cabo una venganza horrorosa: para impedir que Wadah asesine á Bekralbayda.\"},{\"heading\":false,\"text\":\"El rey se alzó pálido, terrible.\"},{\"heading\":false,\"text\":\"--¡Qué, Wadah pretende asesinar á Bekralbayda! esclamó.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡tú amas á esa doncella! esclamó Leila-Radhyah.\"},{\"heading\":false,\"text\":\"--¡Bekralbayda ha sido amante de mi hijo! esclamó el rey.\"},{\"heading\":false,\"text\":\"--¡Ah! esclamó Leila-Radhyah.\"},{\"heading\":false,\"text\":\"--¡Pero ese asesinato! esclamó el rey que estaba desencajado, ¡el pronóstico del buho maldito!\"},{\"heading\":false,\"text\":\"--¿De qué buho hablas?\"},{\"heading\":false,\"text\":\"--De uno que me persigue, que salió de la cueva por donde llegué hasta tí rozando mi rostro con sus alas.\"},{\"heading\":false,\"text\":\"--Era Abu-al-Abu, á quien yo solté para que volase, como todas las noches, fuera del subterráneo.\"},{\"heading\":false,\"text\":\"--Ese buho me predice una desgracia horrible.\"},{\"heading\":false,\"text\":\"--Pero esa desgracia no será la muerte de Bekralbayda, yo te lo juro; te lo juro por el Dios Altísimo y Unico.\"},{\"heading\":false,\"text\":\"--¿Pero esta horrible traicion?...\"},{\"heading\":false,\"text\":\"--¿Cómo has venido á mi asilo, al asilo donde he estado oculta desde que eres rey de Granada? ¿te lo ha revelado á caso el alcaide de los eunucos?\"},{\"heading\":false,\"text\":\"--No, no, Dios es el que me ha traido junto á ti: pero el tiempo vuela...\"},{\"heading\":false,\"text\":\"--Empieza ahora la noche, y hasta que medie, Wadah no irá al alcázar que has construido para Bekralbayda. Pero es necesario que me lleves á él; que me ocultes; que te apoderes del alcaide de los eunucos para que no pueda revelar nada.\"},{\"heading\":false,\"text\":\"--¿Y quién introducirá á Wadah en el Mirador de la sultana?\"},{\"heading\":false,\"text\":\"--Yshac-el-Rumi.\"},{\"heading\":false,\"text\":\"--¡Yshac-el-Rumi!...\"},{\"heading\":false,\"text\":\"--Sí, sí, pero vamos, rey mio, vamos y tú mismo sabrás, tú mismo verás lo horrible del ódio de Wadah: tú sabrás en lo que consiste su locura: tú sabrás que tu Leila-Radhyah, tu sultana, es digna de tí. Ven.\"},{\"heading\":false,\"text\":\"--Sí, sí, vamos, dijo el rey.\"},{\"heading\":false,\"text\":\"Leila-Radhyah se envolvió en su albornoz, se asió al brazo del rey, y ambos, siguiendo la ladera de la montaña, se encaminaron á la Colina Roja.\"}]},{\"title\":\"El mirador de la sultana. — capítulo III: De cómo la sultana wadah creyó en la resurreccion de los muertos.\",\"blocks\":[{\"heading\":false,\"text\":\"Arrojaba la luna su blanca luz sobre la Colina Roja.\"},{\"heading\":false,\"text\":\"Solo se veian los paredones en construccion, los andamios, el Mirador de la sultana, que se levantaba silencioso al norte, y los guardas que vagaban entre las obras, cantando para no dormirse.\"},{\"heading\":false,\"text\":\"En el vestíbulo del Mirador de la sultana, apoyado en una columna, se veia un moro envuelto en un alquicel blanco.\"},{\"heading\":false,\"text\":\"Aquel hombre esperaba sin duda, porque miraba de tiempo en tiempo con impaciencia á la desembocadura de un callejon formado por dos trozos de muralla en construccion.\"},{\"heading\":false,\"text\":\"Al cabo aquella sombra blanca se afirmó sobre los piés, y salió al encuentro de dos sombras que desembocaban por el callejon.\"},{\"heading\":false,\"text\":\"Era la una una muger; la otra un hombre.\"},{\"heading\":false,\"text\":\"Al salir el que esperaba al encuentro de los dos que venian, retrocedió.\"},{\"heading\":false,\"text\":\"--Tú no eres el alcaide, dijo al hombre.\"},{\"heading\":false,\"text\":\"--Yo soy el rey, dijo Al-Hhamar con voz tonante.\"},{\"heading\":false,\"text\":\"--¡El rey! esclamó el que les habia salido al encuentro.\"},{\"heading\":false,\"text\":\"--Y se inclinó profundamente.\"},{\"heading\":false,\"text\":\"--Levántate y llévame á donde llevarias á esta dama si la hubiera traido el alcaide.\"},{\"heading\":false,\"text\":\"--¡Señor! murmuró aterrado el moro.\"},{\"heading\":false,\"text\":\"--Levántate y guia, añadió con acento de amenaza el rey.\"},{\"heading\":false,\"text\":\"El moro se levantó, se encaminó al vestíbulo, torció á la derecha, abrió un pequeño postigo y entró por él.\"},{\"heading\":false,\"text\":\"--Esto está oscuro, dijo el rey.\"},{\"heading\":false,\"text\":\"--Así me han mandado tenerlo, señor.\"},{\"heading\":false,\"text\":\"--Busca una luz...\"},{\"heading\":false,\"text\":\"El moro obedeció, y volvió con una lámpara de los guardas.\"},{\"heading\":false,\"text\":\"Subieron por unas escaleras, atravesaron una galería y entraron en un precioso retrete.\"},{\"heading\":false,\"text\":\"--Cierra esa puerta, dijo el rey al moro.\"},{\"heading\":false,\"text\":\"El moro cerró.\"},{\"heading\":false,\"text\":\"--Descúbrete, le dijo el rey Nazar.\"},{\"heading\":false,\"text\":\"El moro echó atrás la capucha de su albornoz con la que hasta entonces habia tenido cubierta la cabeza.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡eres mi walí Aliathar! ¡mi bravo africano! ¡el walí de la guarda de este alcázar en quien yo depositaba mi entera confianza! ¡y te has atrevido á hacerme traicion!\"},{\"heading\":false,\"text\":\"El walí cayó de rodillas.\"},{\"heading\":false,\"text\":\"--No quiero saber el precio en que me has vendido: solo quiero que obres como si no me hubieras encontrado, y te perdono.\"},{\"heading\":false,\"text\":\"--¡Ah, poderoso señor!\"},{\"heading\":false,\"text\":\"--Que nadie sepa que yo estoy aquí.\"},{\"heading\":false,\"text\":\"--¡Ah, señor!\"},{\"heading\":false,\"text\":\"--Cumple fielmente con lo que te han encargado aquellos á quien te has vendido.\"},{\"heading\":false,\"text\":\"--Solo tengo que esperar á la media noche á que se presenten un hombre y una muger para introducirlos aquí.\"},{\"heading\":false,\"text\":\"--Pues bien, introdúcelos, y cuando estén dentro, no los dejes salir.\"},{\"heading\":false,\"text\":\"--Así lo haré, señor.\"},{\"heading\":false,\"text\":\"--¿No está contigo en la guardia el walí Abd-el-Melek?\"},{\"heading\":false,\"text\":\"--Si señor, pero no sabe nada.\"},{\"heading\":false,\"text\":\"--No importa; dí al walí Abd-el-Melek, que vaya con cuarenta hombres á las Angosturas del Darro; que en el ensanchamiento donde está el primer remanso, busque la entrada de una cueva, que se oculte en ella, que prenda al hombre que entre y que le lleve á las mazmorras de la Alcazaba.\"},{\"heading\":false,\"text\":\"--Asi lo diré á Abd-el-Melek, magnífico señor.\"},{\"heading\":false,\"text\":\"--Dí á esta dama lo que tengas que decirla.\"},{\"heading\":false,\"text\":\"--Por esta celosía, se vé la cámara donde reposa la sultana Bekralbayda, dijo Aliathar que temblaba de terror.\"},{\"heading\":false,\"text\":\"En efecto, por una celosía dorada se veia una pequeña cámara octógona, donde se veia un ancho divan de brocado á la opaca luz de una lámpara.\"},{\"heading\":false,\"text\":\"--Por esta puerta, añadió el walí, señalando una pequeña situada en un ángulo, y por unas escaleras estrechas se baja á un alhamí que está cerrado por una puerta de cedro.\"},{\"heading\":false,\"text\":\"--Basta, dijo Leila-Radhyah, que permanecia encubierta: lo demás ya lo se.\"},{\"heading\":false,\"text\":\"El walí se inclinó profundamente.\"},{\"heading\":false,\"text\":\"--Oye ahora, dijo el rey, y cumple fiel lo que voy á mandarte; vé y espera á ese hombre y á esa mujer; pero en el momento que entraren, haz una señal leve: para poder percibirla, voy á trasladarme á la cámara que está sobre el vestíbulo.\"},{\"heading\":false,\"text\":\"--Yo sé silvar como un buho, dijo el walí.\"},{\"heading\":false,\"text\":\"Se estremeció el rey.\"},{\"heading\":false,\"text\":\"--Bien, bien, no importa, silva cuando ese hombre y esa muger hayan entrado: y no les avises, porque si no sucede aquí esta noche lo que debe suceder, te arrojo á mi verdugo para que me arroje tu cabeza.\"},{\"heading\":false,\"text\":\"--¡Ah, señor!\"},{\"heading\":false,\"text\":\"--Y sobre todo, que Abd-el-Melek, vaya á ocultarse en la cueva del rio, y cumpla las órdenes que te he dado. Vete.\"},{\"heading\":false,\"text\":\"El walí salió estremecido de miedo.\"},{\"heading\":false,\"text\":\"--Ven conmigo, alma de mi alma, dijo el rey tomando la lámpara y asiendo de la mano á Leila-Radhyah.\"},{\"heading\":false,\"text\":\"Atravesó con ella un estrecho corredor, abrió una puerta y entró en un pequeño y bellísimo retrete.\"},{\"heading\":false,\"text\":\"--¿Quién diria que la tosca lámpara de hierro de un guarda de las obras de mis alcázares habia de alumbrar mi felicidad?\"},{\"heading\":false,\"text\":\"Y dejó la lámpara sobre el alfeizar de una ventana.\"},{\"heading\":false,\"text\":\"Despues estremecido de pasion arrancó el albornoz á Leila-Radhyah.\"},{\"heading\":false,\"text\":\"--¡Oh santo Dios de Ismael y qué hermosa me la vuelves! ¡qué hermosa y qué enamorada! añadió al ver la mirada candente, lúcida, que Leila-Radhyah posaba en sus ojos.\"},{\"heading\":false,\"text\":\"--¿Te olvidas, señor, por tu pobre esclava, del motivo que nos trae aquí? dijo Leila-Radhyah, cuyas megillas cubria un leve y dulce matiz de púrpura.\"},{\"heading\":false,\"text\":\"--Siento que mi cabeza se desvanece: en mis oidos resuena una música regalada: la fragancia que me rodea me embriaga: ¡y es el resplandor de tu hermosura que me ciega! ¡es tu voz que resuena en mi alma! ¡es tu aliento que respiro! ¡ah! ¡y qué misericordioso y qué grande es Dios!\"},{\"heading\":false,\"text\":\"--¡Oh! ¡rey, rey mio! esclamó Radhyah exhalando estas palabras entre un suspiro.\"},{\"heading\":false,\"text\":\"Hubo un momento de silencio.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡qué feliz, qué feliz soy!.. ¡la felicidad que siento, me comprime el corazon, me mata!.. esclamó Leila-Radhyah: ¡oh! ¡mi Nazar! ¡oh! ¡mi alma!\"},{\"heading\":false,\"text\":\"--Tu amor ha consagrado este alcázar, luz de mis ojos: esclamó el rey mirando con delicia á la princesa africana: ¡oh! ¿por qué tenemos mas en qué pensar que en nuestro amor?\"},{\"heading\":false,\"text\":\"--Oye, rey mio... ¿no es verdad que yo para tí no soy sultana ni esclava? ¿no es verdad que no soy para tí mas que Leila-Radhyah?\"},{\"heading\":false,\"text\":\"Al-Hhamar la estrechó entre sus brazos.\"},{\"heading\":false,\"text\":\"--Para esa infame hechicera, para esa Wadah fatal, justicia: para tí, mi noble mártir, mi amor, mi vida, mi alcázar y mi corona.\"},{\"heading\":false,\"text\":\"--Y para tí mi alma, esclamó Leila-Radhyah exhalando toda su alma en una divina sonrisa.\"},{\"heading\":false,\"text\":\"Callaron entrambos dominados por su amor, porque un amor que, comprimido, desgarrado, cubierto de luto y de dolores durante diez y siete años, estallaba al fin inmenso.\"},{\"heading\":false,\"text\":\"--Oye, dijo Leila-Radhyah: quiero contarte mi historia.\"},{\"heading\":false,\"text\":\"--¡Tu historia! ¡una historia de desdichas!\"},{\"heading\":false,\"text\":\"--No, porque ha habido dos nobles y generosos hombres que me han protegido, que se han consagrado á mí: mi historia es muy sencilla y muy breve.\"},{\"heading\":false,\"text\":\"--¡Oh! te escucho: tu voz es para mí tan dulce y tan amada como puede serlo la voz de los arcángeles al Señor.\"},{\"heading\":false,\"text\":\"--¿Te acuerdas del dia en que nos conocimos?\"},{\"heading\":false,\"text\":\"--¡Oh! esclamó el rey Nazar.\"},{\"heading\":false,\"text\":\"--Nos rodeaba el horror del combate: estaba yo cercada de cadáveres despedazados: los cristianos que me habian robado en la frontera cuando me dirigia á Córdoba, que habian muerto al wacir que me acompañaba, á mis doncellas, á mis esclavos, habian sido muertos á su vez por tus soldados y yo lloraba desolada porque me veia cautiva cuando empezaba mi juventud: ¿te acuerdas?... apenas tenia doce años, y ya era una muger: ya mi corazon languidecia de amor.\"},{\"heading\":false,\"text\":\"--¡Hija de Africa, alentada por el viento del desierto! esclamó con entusiasmo Al-Hhamar: ¡oh! ¡y qué hermosa eras ya! pero ahora eres mas hermosa: yo nunca hubiera creido que ojos de muger pudieran brillar tanto, arder tanto, exhalar tanta dulzura... ¡oh! entonces eras una hermosa doncella... que llorabas... ahora eres un arcángel de fuego...\"},{\"heading\":false,\"text\":\"--Pero el dolor ha enflaquecido mi cuerpo y empalidecido mis megillas.\"},{\"heading\":false,\"text\":\"--¡Oh, Dios mio! y si la felicidad, si mi amor te embelesan, dime... ¿quién tendrá vida bastante fuerte para resistir tu hermosura, cuando en estos momentos tu hermosura mata?\"},{\"heading\":false,\"text\":\"--¿Y si eso fuese, si yo llegase á ser tan hermosa, tan resplandeciente como una hurí del Señor, no creerias mi hermoso, mi valiente Nazar, que el Altísimo empezaba á recompensarte sobre la tierra? Pero es que tu amor me embellece á tus ojos: hace diez y ocho años... ¡oh! ¡entonces si que era hermosa!.. pero tú entonces eras mas hermoso que yo... me acuerdo, ¡oh! me acuerdo como si hoy mismo me estuviera sucediendo, que vi de repente junto á mí un jóven caballero en una yegua ensangrentada hasta el petral de acero: me acuerdo que cuando vi fija en mi mirada la mirada absorta de aquel mancebo, sentí inundada mi alma de una alegría, de una felicidad inmensas; lo olvidé todo: que me encontraba sola, esclava en tierra estraña. Y ¿te acuerdas, Nazar, rey mio, con cuánta alegría me arrojé en tus brazos cuando tú me dijiste yo te amo? ¿te acuerdas de ese tiempo de amor en que fuí toda tuya en cuerpo y en alma, sintiendo no tener mas vida para consagrártela, para confundirla con la tuya? ¡oh! ¡y cuánto te amé desde el punto en que te ví! ¡oh! ¡cuánto he llorado, sufrido, odiado, deseado y maldecido desde el momento en que te perdí!... ¡oh! ¡cuán dichosa, cuán llena de insensata alegría, cuán enamorada, cuán transportada al cielo, ahora que te veo, que te hablo, que eres mio, mio para no volverte á separar de mí! porque ahora... tú eres poderoso, Nazar, tú eres un gran rey, tú amas á tu Leila-Radhyah y no habrá poder humano que pueda separarme ya de tí.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡no! tú serás mi sultana... tú la alegría de mis alcázares; tú el genio del amor y de la armonía, que vivirá eternamente en ellos en el lugar que ocuparon, cuando el tiempo, que todo lo destruye inflexible, los haya destruido.\"},{\"heading\":false,\"text\":\"--Cuando en los primeros dias de nuestro amor vagábamos en las claras noches de luna por los jardines de Córdoba, yo creia que jamás podia tener fin mi ventura: ¿te acuerdas? tú hijo el príncipe Mohammet aun estaba en la cuna: yo le amaba, yo le mecia sobre mis rodillas, yo quise reemplazar á la madre que habia perdido.\"},{\"heading\":false,\"text\":\"--¡Ah! esclamó el rey Nazar:\"},{\"heading\":false,\"text\":\"--Acuérdate cuán feliz era yo: por tí habia olvidado mi padre, mis alcázares de Fez, mi altivez de sultana: á tu lado no deseaba nada, en nada pensaba mas que en tí: si me cubria de galas, era por agradarte: si tañia la guzla y cantaba, era para hacer mas lánguido el sueño que dormias reclinada tu cabeza en mi regazo: si sonreia era por tí y para tí. ¡Oh señor! yo creia que aquella felicidad iba á ser eterna.\"},{\"heading\":false,\"text\":\"--Satanás se puso en medio de nosotros.\"},{\"heading\":false,\"text\":\"--¡Oh! no recordemos eso: no lo recordemos: tú no dejaste de amarme, no, no: tú me amabas con mas fuerza: te habian dicho que Wadah era una poderosa maga... y tú... Wadah te vió y te amó, y compró á un hombre y vendió á otro, por ser tuya, ó mas bien, porque tú fueses suyo.\"},{\"heading\":false,\"text\":\"--¡Qué, compró á un hombre y vendió á otro! esclamó Al-Hhamar.\"},{\"heading\":false,\"text\":\"--Sí, compró á uno de tus mayores amigos, á un pariente de tu padre, á David-ebn-Kotham, cuyos consejos seguias tú ciegamente.\"},{\"heading\":false,\"text\":\"--¡Oh! no, te engañas, Leila mia; el noble David-ebn-Kotham no podia venderse: era el mejor caballero de Córdoba.\"},{\"heading\":false,\"text\":\"--Cada hombre tiene su precio: Wadah hizo creer á David en su poder y en su ciencia, y en que el hombre que fuese su esposo llegaria á ser un rey valiente y vencedor. David la creyó y se vendió á ella por amor á tí: te hizo conocerla de una manera misteriosa, y tú... pero no hablemos mas de eso, esa maldita muger te hechizó.\"},{\"heading\":false,\"text\":\"--¿Y quién fué el hombre á quien vendió Wadah?\"},{\"heading\":false,\"text\":\"--Un hombre á quien amaba y del cual tenia una hija.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡con que es cierto!..\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Y esa hija es Bekralbayda?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Pero cómo pudo Wadah ocultarla?...\"},{\"heading\":false,\"text\":\"--Bekralbayda pasaba por hija de una de sus esclavas.\"},{\"heading\":false,\"text\":\"--¡Ah!\"},{\"heading\":false,\"text\":\"--De ese modo podia tenerla junto á sí en tu misma casa: pero no se atrevió á tener del mismo modo á su antiguo amante, á quien vendió, porque su amante era un esclavo africano.\"},{\"heading\":false,\"text\":\"--¿Y cómo se llamaba ese esclavo?\"},{\"heading\":false,\"text\":\"--Daniel-el-Bokarí.\"},{\"heading\":false,\"text\":\"--¡El alarife!...\"},{\"heading\":false,\"text\":\"--Sí, el gran alarife que ideó el Palacio-de-Rubíes, el maravilloso alcázar que tú estás construyendo.\"},{\"heading\":false,\"text\":\"--Continúa.\"},{\"heading\":false,\"text\":\"--El Bokarí fué vendido, por fortuna, á un amo piadoso: este, al verle triste y abatido, con las señales de la desesperacion mas profunda, quiso saber el secreto de sus penas. El Bokarí, celoso, furioso contra Wadah, se las reveló: entonces su amo le dijo: ¿qué sabrás tú hacer que valga el precio que he dado por tu alma?--Yo soy alarife, dijo el Bokarí.--Pues entonces hazme un palacio en una de mis huertas del Guadalquivir y eres libre.\"},{\"heading\":false,\"text\":\"El Bokarí construyó el palacio y labró los jardines en la huerta, y tan satisfecho quedó su dueño, que no solo le dió la libertad, sino otro tanto valor como el que habia pagado por él á Wadah.\"},{\"heading\":false,\"text\":\"Habia pasado un año desde tu casamiento con Wadah. Yo estaba abandonada en un apartado aposento de tu casa. Nadie se cuidaba de mí; tú me habias abandonado enteramente, hechizado por esa maldita; solo me servia una esclavilla, una pobre niña etiope: pasaba desesperada mis largas noches sin sueño, y de dia me iba á pasear acompañada de la esclava por las riberas del Guadalquivir por los lugares mas solitarios.\"},{\"heading\":false,\"text\":\"Allí, meditando en mi desventura, recordando mi infancia, mi juventud, mis alcázares, las esclavas que allí me habian servido de rodillas, y mi padre que se miraba en mis ojos, lloraba y me entristecía: pero nunca habia pensado en vengarme ni de tí ni de Wadah.\"},{\"heading\":false,\"text\":\"Una tarde, ya se habia puesto el sol, me volvia á Córdoba, cuando un jóven se aproximó á mí.\"},{\"heading\":false,\"text\":\"--Allah te guarde y te recompense, me dijo, si te dignares escucharme.\"},{\"heading\":false,\"text\":\"--¿Y qué tendrás tú que decirme? le respondí con despego.\"},{\"heading\":false,\"text\":\"--Estás triste y lloras, repuso.\"},{\"heading\":false,\"text\":\"--¿Y qué te importa eso? repliqué.\"},{\"heading\":false,\"text\":\"--Yo tambien estoy triste y lloro.\"},{\"heading\":false,\"text\":\"--Déjame seguir en paz mi camino, le dije con enfado.\"},{\"heading\":false,\"text\":\"--Una misma persona causa nuestra tristeza y nuestro llanto, añadió: la hechicera, la maga, la esposa de Al-Hhamar.\"},{\"heading\":false,\"text\":\"Cuando esto me dijo, ya le escuché de buen grado, y si entonces se hubiera separado de mí, yo le hubiera detenido.\"},{\"heading\":false,\"text\":\"--¿Y qué tienes tú que ver con Wadah? le dije.\"},{\"heading\":false,\"text\":\"--No es este sitio para hablar de esas cosas. Viene contigo esa esclava. Pero si quieres ayudarme y que yo te ayude contra esa muger, espérame esta noche.\"},{\"heading\":false,\"text\":\"--Te esperaré.\"},{\"heading\":false,\"text\":\"--A tus habitaciones da un patio que tiene un postigo sobre el rio.\"},{\"heading\":false,\"text\":\"--Es verdad.\"},{\"heading\":false,\"text\":\"--Pues bien, yo llegaré esta noche al mediar con una barca por ese postigo.\"},{\"heading\":false,\"text\":\"--¿Y fué? dijo el rey Nazar.\"},{\"heading\":false,\"text\":\"--A la media noche, repuso Leila-Radhyah: yo escitada por lo que aquel hombre me habia dicho, le franqueé el postigo.\"},{\"heading\":false,\"text\":\"Hacia una noche tempestuosa y oscura, llovia, tronaba.\"},{\"heading\":false,\"text\":\"Aquel hombre me dijo:\"},{\"heading\":false,\"text\":\"--Espérame en tu aposento, sultana.\"},{\"heading\":false,\"text\":\"Y sin esperar á mas se perdió por uno de los arcos del patio.\"},{\"heading\":false,\"text\":\"Yo absorta sin saber qué hacer, dudé un momento acerca del partido que debia tomar: pero no se por qué me habia inspirado una gran confianza el Bokarí, que él era, y fuí á esperarle en mis habitaciones.\"},{\"heading\":false,\"text\":\"Apenas habia entrado en ellas, cuando se abrió una puerta y apareció el Bokarí; traia entre su alquicel una niña como de dos años, dormida.\"},{\"heading\":false,\"text\":\"--He tenido mas suerte de la que esperaba, me dijo: he encontrado abierto el aposento de mi hija y á su nodriza dormida.\"},{\"heading\":false,\"text\":\"--¡De tu hija! esclamé.\"},{\"heading\":false,\"text\":\"--Sí; esta niña es hija mia y de Wadah.\"},{\"heading\":false,\"text\":\"--¡Ah!\"},{\"heading\":false,\"text\":\"--Ahora, si tú quieres, sultana, sígueme.\"},{\"heading\":false,\"text\":\"--¿Que te siga?\"},{\"heading\":false,\"text\":\"--Sí; ¿qué pretendes esperar aquí? Al-Hhamar, fascinado por Wadah, ni aun se acuerda de tí: cuando Wadah eche de menos á su hija, creerá que tú eres quien se la ha robado, y pretenderá vengarse de tí: aquí estás en peligro, huye.\"},{\"heading\":false,\"text\":\"--No me separaré de la casa donde vive Al-Hhamar, le contesté.\"},{\"heading\":false,\"text\":\"--Pero esa muger es terrible y sanguinaria.\"},{\"heading\":false,\"text\":\"--No importa: llévate tu hija; yo me quedo aquí.\"},{\"heading\":false,\"text\":\"En vano el Bokarí pretendió convencerme: yo no podia separarme del lugar en que, aunque sin verte, estaba próxima á tí.\"},{\"heading\":false,\"text\":\"Al fin cansado de la inutilidad de sus esfuerzos, y viendo que la noche avanzaba, el Bokarí salió.\"},{\"heading\":false,\"text\":\"--Deja abierto el postigo, me dijo, hasta el amanecer.\"},{\"heading\":false,\"text\":\"--¿Y á qué propósito?\"},{\"heading\":false,\"text\":\"--Déjale abierto, sultana, porque yo quiero velar por tí.\"},{\"heading\":false,\"text\":\"No se qué estraña confianza me inspiraba aquel hombre, que cedí y dejé abierto el postigo.\"},{\"heading\":false,\"text\":\"Cuando entré en mi aposento me aterré: Wadah desmelenada, pálida, desceñida la túnica, buscaba por todas partes en mi aposento y rugia y lloraba.\"},{\"heading\":false,\"text\":\"Al verme se abalanzó á mí como una leona.\"},{\"heading\":false,\"text\":\"--¡Dáme mi rosa blanca, miserable! ¡dámela! gritó.\"},{\"heading\":false,\"text\":\"--¡Tu rosa blanca! esclamé, ¡tu hija!\"},{\"heading\":false,\"text\":\"--¡Sí! ¡mi hija! ¡dáme á mi hija que me has robado! gritó.\"},{\"heading\":false,\"text\":\"--Dáme tú mi Al-Hhamar, repuse.\"},{\"heading\":false,\"text\":\"--¡Qué! ¿no me darás mi hija, ladrona? esclamó Wadah palideciendo.\"},{\"heading\":false,\"text\":\"--¡Tu hija! ¡tu hija! esclamé, saboreando aquella venganza inesperada que me habia procurado el Bokarí: ya no volverás á ver á tu hija, hechicera.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡ni tú volverás á ver el sol! gritó.\"},{\"heading\":false,\"text\":\"Luego sentí tres golpes terribles sobre el pecho; despues nada: una densa niebla habia cubierto mis ojos; mi cabeza se habia hecho pesada, como de plomo.\"},{\"heading\":false,\"text\":\"Cuando volví en mí me encontré en una habitacion humilde, pero limpia y alegre.\"},{\"heading\":false,\"text\":\"Un hombre estaba á mi lado contemplándome con interés.\"},{\"heading\":false,\"text\":\"Era el Bokarí.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡Dios sea loado! esclamó: creí que no volverias á la vida, sultana.\"},{\"heading\":false,\"text\":\"Quise hablar, pero me hizo señal de que callase, y él mismo guardó silencio.\"},{\"heading\":false,\"text\":\"Algunos dias despues, como yo le preguntase por qué razon estaba en su poder me contestó.\"},{\"heading\":false,\"text\":\"--Yo quise que dejaras abierto el postigo para protegerte: poco despues oí los gritos de Wadah y los tuyos; me precipité en tu socorro, pero llegué tarde. Wadah habia desaparecido, y tú estabas por tierra ensangrentada y sin sentido. Cargué contigo; te llevé á mi barca, te restañé la sangre de la mejor manera posible, y apartándome con mi barca de aquel lugar maldito, te he traido aquí. Tenias tres puñaladas en el pecho que me hicieron temer por tu vida: pero la misericordia de Dios no ha querido que mueras.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿y para qué quiero yo vivir?\"},{\"heading\":false,\"text\":\"--¿Te has olvidado de tu padre, sultana?\"},{\"heading\":false,\"text\":\"--Mi padre no me recibirá.\"},{\"heading\":false,\"text\":\"--¿Quién sabe?\"},{\"heading\":false,\"text\":\"--Mi padre me pedirá cuentas de mi honra.\"},{\"heading\":false,\"text\":\"--Que se las pida á Al-Hhamar. ¿Acaso Al-Hhamar no te hizo su esclava? En el momento que tus heridas lo permitan iremos á Africa. Es necesario que tu poderoso padre te vengue de Al-Hhamar.\"},{\"heading\":false,\"text\":\"Pasó así algun tiempo.\"},{\"heading\":false,\"text\":\"El Bokarí, salvas algunas horas de la tarde y de la noche, estaba á mi lado refiriéndome alegres cuentos para entretener mi tristeza.\"},{\"heading\":false,\"text\":\"Lo demás del tiempo lo pasaba encerrado.\"},{\"heading\":false,\"text\":\"--¿Qué estás haciendo? le dije un dia.\"},{\"heading\":false,\"text\":\"--Estoy haciendo un alcázar tan maravilloso, que no habrá rey que se atreva á construirle.\"},{\"heading\":false,\"text\":\"--Pero si le haces tú, no hay necesidad de que le haga un rey.\"},{\"heading\":false,\"text\":\"--Sí, pero yo le hago imitado en gacela, y para levantarle, para que se toque con las manos como ahora se toca con la vista, serian necesarios grandísimos tesoros.\"},{\"heading\":false,\"text\":\"--¡Y no me enseñarás ese alcázar! le dije.\"},{\"heading\":false,\"text\":\"--Ven conmigo, me contestó.\"},{\"heading\":false,\"text\":\"Llevóme á una torrecilla, y en ella colgados de las paredes y estendidos por el pavimento, vi una multitud de pergaminos, sobre cada uno de los cuales habia pintada una maravillosa habitacion ó un patio incomparable ó un jardin deleitoso.\"},{\"heading\":false,\"text\":\"--Este es el Palacio-de-Rubíes, sultana, me dijo el Bokarí: el rey que posea este alcázar, será el rey mas poderoso de la tierra.\"},{\"heading\":false,\"text\":\"Cuando el Bokarí dijo esto, mi pensamiento se fijó en tí, mi valiente Nazar, y dije.\"},{\"heading\":false,\"text\":\"--El llegará á ser rey, él será un rey grande y poderoso: él construirá este alcázar.\"},{\"heading\":false,\"text\":\"--¿Quién sabe? dijo el Bokarí, pero para cuando Al-Hhamar sea rey, ya habré yo muerto. Es necesario buscar otro rey que pueda construir esta obra. Necesitamos pasar á Africa.\"},{\"heading\":false,\"text\":\"--Cuando quieras, le dije: nada espero aquí.\"},{\"heading\":false,\"text\":\"Algunos dias despues llegábamos á Málaga, y nos embarcábamos en una galeota de un amigo del Bokarí.\"},{\"heading\":false,\"text\":\"Llegamos al fin á Tlencen.\"},{\"heading\":false,\"text\":\"El Bokarí, bajo pretesto de mostrar á mi padre el Palacio-de-Rubíes, logró que le recibiese en su alcázar.\"},{\"heading\":false,\"text\":\"Maravilló tanto á mi padre la riqueza de la obra que habia pintado el Bokarí, que no teniendo tesoros bastantes para realizarla, quiso al menos que en su alcázar hiciese algunas habitaciones semejantes el Bokarí.\"},{\"heading\":false,\"text\":\"Pasó algun tiempo.\"},{\"heading\":false,\"text\":\"El Bokarí iba todos los dias á los alcázares de mi padre á labrar las nuevas habitaciones.\"},{\"heading\":false,\"text\":\"Mi padre habia llegado á tenerle ya amor.\"},{\"heading\":false,\"text\":\"Atrevióse al fin un dia á decirle el Bokarí:\"},{\"heading\":false,\"text\":\"--¿Dónde quieres que ponga esta inscripcion que acabo de labrar?\"},{\"heading\":false,\"text\":\"La inscripcion á que el Bokarí se referia era mi nombre.\"},{\"heading\":false,\"text\":\"--¡Leila-Radhyah! esclamó mi padre demudado: ¿quién te ha dicho su nombre?\"},{\"heading\":false,\"text\":\"--Es el de una dama muy hermosa que yo conozco, dijo el Bokarí.\"},{\"heading\":false,\"text\":\"--¿Y qué edad tiene esa dama?\"},{\"heading\":false,\"text\":\"--Diez y siete años.\"},{\"heading\":false,\"text\":\"Creció la palidez de Al-Mostansir.\"},{\"heading\":false,\"text\":\"--¿Y dónde has conocido á esa dama?\"},{\"heading\":false,\"text\":\"--En Córdoba: es cautiva de un valiente walí.\"},{\"heading\":false,\"text\":\"--¡Ah! dijo mi padre; ¿no mas que cautiva?\"},{\"heading\":false,\"text\":\"--Poderoso rey, dijo el Bokarí, la cautiva ama á su señor.\"},{\"heading\":false,\"text\":\"--¿Y su señor la ama á ella?\"},{\"heading\":false,\"text\":\"--Se ha casado con otra.\"},{\"heading\":false,\"text\":\"--¿Cómo se llama ese walí, que se casa con una muger teniendo en su poder otra que se llama Leila-Radhyah?\"},{\"heading\":false,\"text\":\"--Se llama Mohammet-ebn-Juzef-Al-Hhamar.\"},{\"heading\":false,\"text\":\"--Pero Al-Hhamar no es ya solamente un valiente walí; es un rey.\"},{\"heading\":false,\"text\":\"--¡Rey!\"},{\"heading\":false,\"text\":\"--Si por cierto: el califato de Córdoba se hunde: cada walí se cree bastante poderoso para declararse rey: Aben-Hud acabará mal; su corona se divide en muchas coronas.\"},{\"heading\":false,\"text\":\"--¿Y dices, señor, que Juzef-Al-Hhamar es rey?\"},{\"heading\":false,\"text\":\"--Sí; rey de Jaen, Guadix y Baeza. No hablemos mas de esto.\"},{\"heading\":false,\"text\":\"--¿Pero esta inscripcion?\"},{\"heading\":false,\"text\":\"--Rómpela.\"},{\"heading\":false,\"text\":\"--¿Olvidais que es el nombre de Leila-Radhyah?\"},{\"heading\":false,\"text\":\"--Rómpela.\"},{\"heading\":false,\"text\":\"--¿Pero por qué tanta severidad, señor? ¿No os digo que Al-Hhamar?...\"},{\"heading\":false,\"text\":\"--No hablemos mas de esto; esa desdichada ha debido morir... y no ha sabido morir. Rompe su nombre, y no le vuelvas á poner delante de mis ojos ni á enviarlo á mis oidos.\"},{\"heading\":false,\"text\":\"--¡Ah Leila, Leila de mi alma! esclamó el rey Nazar: ¡y cuán culpable he sido para contigo!\"},{\"heading\":false,\"text\":\"--Eso ha sido un sueño, una pesadilla que ha pasado, dijo Leila-Radhyah sonriendo tristemente: déjame continuar.\"},{\"heading\":false,\"text\":\"El Bokarí no volvió á hablar mas de mí á mi padre hasta que se concluyeron las obras. Cuando mi padre le hubo pagado, el Bokarí se atrevió á decirle:\"},{\"heading\":false,\"text\":\"--Voy á España, señor: ¿qué diré á la desdichada que en aquella region llora?\"},{\"heading\":false,\"text\":\"--Cuéntala lo de la inscripcion; le respondió mi padre.\"},{\"heading\":false,\"text\":\"El Bokarí salió triste y acongojado de los alcázares de Al-Mostansir Billah, porque me amaba y habia concebido esperanzas de que mi padre me volveria su afecto.\"},{\"heading\":false,\"text\":\"Pero ni una palabra me dijo acerca de esto, sino cuando un año adelante le ví próximo á la muerte.\"},{\"heading\":false,\"text\":\"Entonces me lo reveló todo; y un amigo suyo, un renegado español, quedaba encargado de mí, de Bekralbayda y del Palacio-de-Rubíes.\"},{\"heading\":false,\"text\":\"Daniel-el-Bokarí murió al cabo, y entonces conocí á Yshac-el-Rumi.\"},{\"heading\":false,\"text\":\"Ya le conoces tú.\"},{\"heading\":false,\"text\":\"Su historia es muy breve.\"},{\"heading\":false,\"text\":\"Se halló en la batalla de Alarcos, como soldado del rey Alonso de Castilla, y fué hecho cautivo, vendido y traido á Africa.\"},{\"heading\":false,\"text\":\"En Africa estudió toda la ciencia que poseia su amo, que era astrólogo, y se enamoró de una hermosa hija que el astrólogo tenia. Ella se enamoró tambien de él, y sin que su padre lo supiese se comunicaban. Pero un dia se apercibió de ello el viejo y quiso matarlos á entrambos.\"},{\"heading\":false,\"text\":\"--Me casaré con ella, dijo Yshac.\"},{\"heading\":false,\"text\":\"--Tú no puedes casarte con mi hija, dijo colérico el viejo: porque eres cristiano.\"},{\"heading\":false,\"text\":\"--Me haré musulman.\"},{\"heading\":false,\"text\":\"--Pero eres mi esclavo.\"},{\"heading\":false,\"text\":\"--¿Y qué, no vale nada la honra de tu hija?\"},{\"heading\":false,\"text\":\"El astrólogo, á pesar de su codicia, cedió; Yshac se hizo musulman y se casó con su amante.\"},{\"heading\":false,\"text\":\"Pero la infeliz murió poco despues al dar á luz una criatura que nació muerta.\"},{\"heading\":false,\"text\":\"--Ahora comprendo, dijo el rey Nazar, la razon de la sombría tristeza de ese hombre: pero lo que no puedo comprender es la conducta que ha seguido y sigue conmigo.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡pues es muy fácil de comprender! Yshac me ama.\"},{\"heading\":false,\"text\":\"Frunció el entrecejo el rey Nazar.\"},{\"heading\":false,\"text\":\"--Me ama como un padre ama á su hija, y quiere vengarme y vengar al pobre Daniel-el-Bokarí, de quien fué grande amigo.\"},{\"heading\":false,\"text\":\"--¿Y por qué entonces el misterio de que te ha rodeado y la especie de traicion de haber arrojado á Bekralbayda en los brazos de mi hijo Mohammet, y habérmela vendido despues?\"},{\"heading\":false,\"text\":\"--Yshac-el-Rumi y yo amamos á Bekralbayda como si fuese nuestra hija: Yshac la llevó á Alhama para que el príncipe la viese y la amase: yo quise que tú la conocieses tambien.\"},{\"heading\":false,\"text\":\"--¿Y para qué?\"},{\"heading\":false,\"text\":\"--Para que tuviese celos Wadah.\"},{\"heading\":false,\"text\":\"--Pero los celos de Wadah matan.\"},{\"heading\":false,\"text\":\"--Te juro que no matarán á Bekralbayda. ¿No estaba á tu lado en tu alcázar Yshac-el-Rumi?\"},{\"heading\":false,\"text\":\"--No comprendo bien esto.\"},{\"heading\":false,\"text\":\"--Antes de mucho lo comprenderás.\"},{\"heading\":false,\"text\":\"--¿Pero esa diadema, esas joyas, esas galas que te cubren y que valen un tesoro, Leila?\"},{\"heading\":false,\"text\":\"--¡Ah! ¡desconfias de mi!\"},{\"heading\":false,\"text\":\"--No, no desconfio: pero en tu habitacion de Córdoba se encontraron todas tus joyas, joyas que yo he conservado, como un precioso tesoro de mi corazon, porque creí que esas joyas y esas ropas eran lo único que me quedaba de tí.\"},{\"heading\":false,\"text\":\"--Despues de la muerte de el Bokarí, permanecimos algunos meses en Tlencen; pero al fin, yo que ansiaba volver á Andalucía, porque en Andalucía estabas tú, escité á Yshac á que viniésemos á vivir á Granada, y cediendo á mis deseos Yshac dispuso el viaje.\"},{\"heading\":false,\"text\":\"Al dia siguiente un esclavo de mi padre entró en nuestra casa.\"},{\"heading\":false,\"text\":\"--Te llamas Yshac-el-Rumi, dijo á este.\"},{\"heading\":false,\"text\":\"--Sí, contestó.\"},{\"heading\":false,\"text\":\"--El poderoso rey Al-Mostansir Billah te ordena que vayas á su alcázar.\"},{\"heading\":false,\"text\":\"Yshac fué.\"},{\"heading\":false,\"text\":\"Al-Mostansir Billah le dió un cofre de hierro muy pequeño y una carta, y le dijo:\"},{\"heading\":false,\"text\":\"--Entrega esto á Leila-Radhyah.\"},{\"heading\":false,\"text\":\"Al-Mostansir Billah cuando hubo entregado el cofre y la carta y dicho estas palabras á Yshac, le volvió la espalda.\"},{\"heading\":false,\"text\":\"Yshac me entregó el cofre y la carta.\"},{\"heading\":false,\"text\":\"Abrí la carta antes que el cofre y ví que decia:\"},{\"heading\":false,\"text\":\"«Un rey tenia una hija:\"},{\"heading\":false,\"text\":\"Y esta hija del rey era muy hermosa.\"},{\"heading\":false,\"text\":\"Y tan hermosa era, que los sabios le habian dicho:\"},{\"heading\":false,\"text\":\"Tu hija será causa de crímenes y desdichas.\"},{\"heading\":false,\"text\":\"El rey encerró á su hija; pero la princesa empezó á languidecer.\"},{\"heading\":false,\"text\":\"El rey llamó á los sabios y les mostró la princesa:\"},{\"heading\":false,\"text\":\"¿Qué enfermedad padece mi hija? les preguntó.\"},{\"heading\":false,\"text\":\"Y los sabios le respondieron:\"},{\"heading\":false,\"text\":\"Tu hija languidece de amor.\"},{\"heading\":false,\"text\":\"Nosotros no nos atrevemos á volverle la salud; pero hemos consultado las estrellas, y las estrellas nos han dicho:\"},{\"heading\":false,\"text\":\"Allá en el Andalucía, del otro lado del mar, en la hermosa Córdoba, la hija del rey encontrará alivio á su dolencia.\"},{\"heading\":false,\"text\":\"Y el rey que amaba mucho á su hija la envió á Córdoba.\"},{\"heading\":false,\"text\":\"Pero su hija no volvió.\"},{\"heading\":false,\"text\":\"Han pasado muchos años.\"},{\"heading\":false,\"text\":\"Tú que vas á Córdoba, señora, busca á Leila-Radhyah y dála esas joyas.\"},{\"heading\":false,\"text\":\"Pero no la digas que su padre la dá un tesoro, porque Leila-Radhyah no tiene ya padre.\"},{\"heading\":false,\"text\":\"No la digas que venga, porque si su padre la vé delante de sí, la matará.»\"},{\"heading\":false,\"text\":\"--Tu padre fué demasiado severo contigo, dijo el rey Nazar.\"},{\"heading\":false,\"text\":\"--Mi padre me ama, dijo Leila-Radhyah con los ojos arrasados de lágrimas.\"},{\"heading\":false,\"text\":\"--¡Te ama, y á pesar de tu inocencia no te ha recibido!..\"},{\"heading\":false,\"text\":\"--Mi padre me ha enviado hace pocos dias otra carta.\"},{\"heading\":false,\"text\":\"--¡Otra carta!\"},{\"heading\":false,\"text\":\"--Sí, mírala.\"},{\"heading\":false,\"text\":\"Leila sacó de su seno una bolsita de seda verde y oro, y de ella un pergamino enrollado.\"},{\"heading\":false,\"text\":\"El rey Nazar leyó:\"},{\"heading\":false,\"text\":\"«Leila-Radhyah, decia aquella carta:\"},{\"heading\":false,\"text\":\"He tenido nuevas que han reanimado mi esperanza.\"},{\"heading\":false,\"text\":\"Un walí granadino, me ha dicho que la sultana Wadah está loca.\"},{\"heading\":false,\"text\":\"El rey Nazar puede, pues, apartarla de sí.\"},{\"heading\":false,\"text\":\"El rey Nazar puede ser tu esposo.\"},{\"heading\":false,\"text\":\"Te envio joyas y galas de sultana.\"},{\"heading\":false,\"text\":\"Si quieres tener padre y hermanos, consiente en ser la esposa de Nazar.\"},{\"heading\":false,\"text\":\"Si consientes, yo te enviaré servidumbre y esclavos y guardas, para que puedas presentarte en Granada, como debe ser vista la hija de un rey.\"},{\"heading\":false,\"text\":\"Tu padre te ama, Leila-Radhyah, pero no puede abrazarte hasta que laves tu deshonra.\"},{\"heading\":false,\"text\":\"Procura ser esposa de Al-Hhamar.»\"},{\"heading\":false,\"text\":\"--¿Y qué has contestado á tu padre? dijo el rey Nazar.\"},{\"heading\":false,\"text\":\"--No le he contestado todavía; pero mi respuesta la llevará un embajador tuyo: un embajador que le diga: tu hija Leila-Radhyah, es sultana de Granada.\"},{\"heading\":false,\"text\":\"--¡Oh! ese embajador partirá para Tlencen, antes que salga el sol del nuevo dia.\"},{\"heading\":false,\"text\":\"En aquel momento se oyó fuera un ténue silvido, un silvido semejante al de un buho.\"},{\"heading\":false,\"text\":\"El rey y Leila-Radhyah salieron del retrete donde se encontraban y se trasladaron á oscuras á aquel desde donde se veia la cámara de Bekralbayda.\"},{\"heading\":false,\"text\":\"Veamos lo que pasaba en esta cámara.\"},{\"heading\":false,\"text\":\"Estaba desierta.\"},{\"heading\":false,\"text\":\"Bekralbayda velaba en el jardin, mirando desde sus espesuras la torre del Gallo de viento, que se veia á lo lejos allá en el distante estremo del Albaicin bajo la luz de la luna, y en cuyas ventanas se veia el reflejo de una luz.\"},{\"heading\":false,\"text\":\"Bekralbayda creia ver en aquella ventana al príncipe que velaba como ella.\"},{\"heading\":false,\"text\":\"Estaba abstraida, absorta en su amor, cuando un esclavo se acercó á ella, se prosternó, y la dijo con voz humilde:\"},{\"heading\":false,\"text\":\"--Poderosa sultana, la noble sultana Wadah acaba de llegar y desea verte.\"},{\"heading\":false,\"text\":\"--¿Y dónde está la sultana? esclamó con cierta alegría Bekralbayda, porque amaba á Wadah.\"},{\"heading\":false,\"text\":\"--Te espera en tu cámara, señora, contestó el esclavo.\"},{\"heading\":false,\"text\":\"Bekralbayda se encaminó precipitadamente hácia su cámara.\"},{\"heading\":false,\"text\":\"En ella, sentada en el divan que servia de lecho, estaba Wadah, indolente, hermosa, mas hermosa que nunca, y muy sencillamente vestida.\"},{\"heading\":false,\"text\":\"Al ver á Bekralbayda, se levantó, corrió á ella y la besó en la boca.\"},{\"heading\":false,\"text\":\"--¡Oh! esclamó: ¡qué hermosa estás, hija mia! ¡cuánto he sufrido desde el dia en que te sacaron del palacio del Gallo de viento! porque yo te amo, ya lo sabes.\"},{\"heading\":false,\"text\":\"--¡Ah, señora! esclamó Bekralbayda: ¡y vienes á visitar á tu esclava!\"},{\"heading\":false,\"text\":\"--¡Esclava! ¡no! ¡tú no eres esclava! ¡tú eres sultana! escucha; vengo á revelarte un secreto que te va á llenar de placer: el rey...\"},{\"heading\":false,\"text\":\"Bekralbayda palideció.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡y cómo le ama! pensó Wadah conteniendo mal su celosa rabia: el rey piensa casarte... con...\"},{\"heading\":false,\"text\":\"--¿Con quién?... esclamó pálida Bekralbayda.\"},{\"heading\":false,\"text\":\"--Con mi hijo: respondió la sultana.\"},{\"heading\":false,\"text\":\"--¡Con tu hijo! ¡con el príncipe Juzef-Abdallah!\"},{\"heading\":false,\"text\":\"--¿Qué, no te parece bastante hermoso mi hijo?..\"},{\"heading\":false,\"text\":\"--¡Ah! ¡sí! si señora, pero es muy jóven... demasiado jóven.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿tú quisieras para esposo un hombre de la edad de su padre?\"},{\"heading\":false,\"text\":\"--Yo... no... ya es demasiado.\"},{\"heading\":false,\"text\":\"--¡Jóven el uno! ¡el otro viejo!\"},{\"heading\":false,\"text\":\"--¿Pero qué importa eso, señora? ¿por qué ha de pensar el rey en casarme? te equivocas... te equivocas... sultana: yo sé que el rey no quiere casarme con nadie.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡no quiere casarte con nadie! ¡pues mira, yo habia creido!.. el otro dia me dijo: Wadah, estoy pensando en casar á nuestro hijo.--¿Y con quién, señor?--Con una doncella jóven, hermosa, pura, á quien tú conoces.--¿Que yo conozco?--Sí, pero quiero sorprenderte y no te diré su nombre.--Y no me lo dijo: pero al dia siguiente te sacó del alcázar, y te trajo á este otro alcázar: puso junto á tí eunucos, esclavos y guardas... magestad de sultana, y yo... yo creí que era porque te destinaba á nuestro hijo... al príncipe Juzef. ¡Y no amas tú á mi hijo!\"},{\"heading\":false,\"text\":\"--¡Ah, señora! le respeto... pero amarle... no.\"},{\"heading\":false,\"text\":\"--¿Y á quién amas?\"},{\"heading\":false,\"text\":\"--Yo... á nadie.\"},{\"heading\":false,\"text\":\"--¡A nadie!.. ¿y el estado en que te encuentras, pobre niña?\"},{\"heading\":false,\"text\":\"Y la mirada de Wadah se fijó de una manera marcada en Bekralbayda.\"},{\"heading\":false,\"text\":\"La pobre jóven se cubrió el rostro con las manos.\"},{\"heading\":false,\"text\":\"--Ha sido una violencia, una horrible violencia...\"},{\"heading\":false,\"text\":\"--¡Del rey!\"},{\"heading\":false,\"text\":\"--¡Del rey! esclamó asombrada Bekralbayda.\"},{\"heading\":false,\"text\":\"--¿Por qué tiemblas?...\"},{\"heading\":false,\"text\":\"--Has dicho que el rey...\"},{\"heading\":false,\"text\":\"--Es tu amante.\"},{\"heading\":false,\"text\":\"--No; no; y cien veces no.\"},{\"heading\":false,\"text\":\"Wadah habia dejado al fin su continente tranquilo.\"},{\"heading\":false,\"text\":\"Sus ojos arrojaban llamas.\"},{\"heading\":false,\"text\":\"Estaba trémula de cólera.\"},{\"heading\":false,\"text\":\"--¿Pues si no ha sido el rey, quién ha sido? añadió con la voz opaca por los celos y por el ódio Wadah.\"},{\"heading\":false,\"text\":\"--¿Pero qué te he hecho, señora, para que me trates así? esclamó Bekralbayda.\"},{\"heading\":false,\"text\":\"--¿Qué me has hecho? ¿qué me has hecho? ¿Pues no te ama el rey Nazar?\"},{\"heading\":false,\"text\":\"--¡Dios mio!\"},{\"heading\":false,\"text\":\"--¿No eres tú su esclava querida?\"},{\"heading\":false,\"text\":\"--Soy su esclava... sí, es verdad, pero...\"},{\"heading\":false,\"text\":\"--No, tú no eres su esclava: tú eres su señora.\"},{\"heading\":false,\"text\":\"--Yo... ¿pero tú estas loca, sultana?\"},{\"heading\":false,\"text\":\"--¡Loca! ¡loca! ¡sí, es verdad! ¡loca de celos! ¿sabes tú quién soy yo?\"},{\"heading\":false,\"text\":\"--¡Ah! ¡Dios mio! esclamó Bekralbayda levantándose y pretendiendo huir.\"},{\"heading\":false,\"text\":\"Wadah la asió de un brazo y la atrajo á sí:\"},{\"heading\":false,\"text\":\"--¡Socorro! gritó la jóven: ¡socorredme!.. ¡libradme de esta muger!\"},{\"heading\":false,\"text\":\"--Nadie puede oirte: están cerradas las puertas y los que te sirven alejados; nadie te oirá.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡Señor, Señor de misericordia! esclamó la jóven cayendo de rodillas.\"},{\"heading\":false,\"text\":\"--Sí, sí, prostérnate, dijo Wadah; porque así debes estar delante de mí: delante de la esposa á quien has injuriado.\"},{\"heading\":false,\"text\":\"--Yo os juro que no amo al rey.\"},{\"heading\":false,\"text\":\"--Pero él te ama.\"},{\"heading\":false,\"text\":\"--Yo no puedo impedirlo.\"},{\"heading\":false,\"text\":\"--Pero no se ama á los muertos.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡qué dices! ¡pero no, tú no piensas así!.. ¡tú no quieres asesinarme!.. ¿no es verdad? yo no tengo la culpa... no... yo no amo al rey... yo no he sido suya... no puedo ser suya... antes la muerte... no... no puedo ser suya.\"},{\"heading\":false,\"text\":\"--Te obligará.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡no! porque si quiere violentarme, yo le diré: soy amante del príncipe Mohammet: el hijo que llevo en mis entrañas es tu nieto.\"},{\"heading\":false,\"text\":\"--¡Mientes! ¡mientes! ¡quieres salvarte! ¿qué? ¿no te he visto yo perderte en los bosquecillos con el rey?\"},{\"heading\":false,\"text\":\"--Pero yo no tengo la culpa...\"},{\"heading\":false,\"text\":\"--Escucha: en otro tiempo otra muger me disputaba los amores de Nazar... yo maté á aquella muger.\"},{\"heading\":false,\"text\":\"--¡Oh, Dios mio!\"},{\"heading\":false,\"text\":\"--Pero la maté á puñaladas y su sangre...\"},{\"heading\":false,\"text\":\"Wadah se detuvo.\"},{\"heading\":false,\"text\":\"--Yo veo su sangre corriendo siempre delante de mí como un torrente: yo me estremezco de noche y me tapo la cabeza para que no caiga sobre ella la sangre de aquella muger, la sangre de Leila-Radhyah. Yo no quiero ver mas sangre y no te mataré á puñaladas.\"},{\"heading\":false,\"text\":\"--¡Matarme! ¡matarme! ¡pero eso no puede ser! señora... no... yo te amaba...\"},{\"heading\":false,\"text\":\"--¡Que me amabas!\"},{\"heading\":false,\"text\":\"--Sí... como amaría á mi madre.\"},{\"heading\":false,\"text\":\"--¡A tu madre! ¡á tu madre! ¡Oh! yo tenia una hija: una hija que tendria tu misma edad: y aquella miserable Leila-Radhyah la mató... la mató: yo encontré sus ropas ensangrentadas... por eso maté á esa miserable muger que se me presenta todavía á cada paso delante de los ojos, hermosa y pálida como un espectro... por eso la dí de puñaladas: pero á tí no: yo te mataré de modo que no salga fuera de tu cuerpo una sola gota de sangre... no... tú no te presentarás ante mí en mis sueños, en mis soledades, roja de los pies á la cabeza... yo soy sábia... yo conozco las yerbas que matan y las yerbas que enloquecen: mira.\"},{\"heading\":false,\"text\":\"Y mostró á Bekralbayda un frasquito de oro.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿y qué es eso?... esclamó aterrada la jóven.\"},{\"heading\":false,\"text\":\"--Esto... esto es... mira, tú beberás esto.\"},{\"heading\":false,\"text\":\"--Yo... yo no beberé... no... yo resistiré... yo gritaré...\"},{\"heading\":false,\"text\":\"--Resistir... ¿piensas acaso que puedes resistirme?... gritarás... ¿te escuchará alguien? tú beberás...\"},{\"heading\":false,\"text\":\"--¡Oh Dios poderoso!\"},{\"heading\":false,\"text\":\"--Beberás y sentirás entorpecidos tus ojos, pesada tu cabeza... te dormirás y no despertarás... no despertarás... y yo no tendré celos, porque no se ama á los muertos, y Al-Hhamar me volverá su amor.\"},{\"heading\":false,\"text\":\"Bekralbayda miraba fascinada á Wadah.\"},{\"heading\":false,\"text\":\"Wadah se habia replegado en un ángulo del divan como una pantera, y fijaba sus ojos estraviados y escandencidos en Bekralbayda.\"},{\"heading\":false,\"text\":\"--¡Oh! ciertamente que eres muy hermosa... solo he conocido una muger que á tu edad fuese tan hermosa como tú, y esa muger la veia en mi espejo, porque esa muger era yo... pero ella, mi rosa blanca, seria mas hermosa que tú... sí, mas hermosa... y la mataron... ¡la mataron!... yo maté á su asesino, á la infame... á la miserable Leila-Radhyah... ahora tú me robas á Al-Hhamar... ¡has matado el amor que Al-Hhamar me tenia, y morirás... morirás tambien!\"},{\"heading\":false,\"text\":\"--¡Oh! ¡señora! ¡yo no amo al rey! ¡te lo juro! no le amo.... el rey me aterra, me persigue, me enamora... pero yo... yo no puedo amar al rey... yo no puedo ser suya... yo he sido de su hijo... de su hijo, lo entiendes... de su hijo que está perseguido y aborrecido de su padre porque me ama.\"},{\"heading\":false,\"text\":\"Wadah miraba á Bekralbayda con una espresion letal.\"},{\"heading\":false,\"text\":\"La jóven continuó:\"},{\"heading\":false,\"text\":\"--Soy muy desgraciada, dijo, y poco me importaria morir... pero él me ama; él moriria si yo muriese...\"},{\"heading\":false,\"text\":\"--¡El! y ¿quién es él? gritó Wadah levantándose furiosa: ¿quién es el que tú amas y morirá si tú mueres?\"},{\"heading\":false,\"text\":\"--¡El príncipe Mohammet! esclamó con angustia Bekralbayda juntando sus manos.\"},{\"heading\":false,\"text\":\"--¡El príncipe! ¡el príncipe! ¡tú me engañas!\"},{\"heading\":false,\"text\":\"--No; no te engaño: escucha: busca al príncipe, pregúntale: pregúntale á quien ama, el te dirá: yo amo á Bekralbayda.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡no! ¡no! ¡eso no es verdad!\"},{\"heading\":false,\"text\":\"--Sí, sí, pregúntale: ¿ha sido tu esclava Bekralbayda? y él te contestará: pregúntalo á los bosquecillos de la casita del remanso: pregúntalo á las fuentes, á las flores, á la noche silenciosa y oscura y ellos te dirán: nosotros hemos sido testigos de su felicidad, se aman, se aman, y Bekralbayda lleva en su seno la vida de su amor.\"},{\"heading\":false,\"text\":\"--¡Mientes! ¡mientes! gritó Wadah.\"},{\"heading\":false,\"text\":\"--¡Oh! no, no miento; y si defiendo mi vida... espera, espera algun tiempo, sultana; espera que nazca mi hijo, y mátame despues: pero no mates á mi hijo, no... mi hijo es inocente.\"},{\"heading\":false,\"text\":\"--Inocente era tambien mi hija y la mataron.\"},{\"heading\":false,\"text\":\"--¿Pero tienes las entrañas de pedernal? esclamó desesperada Bekralbayda.\"},{\"heading\":false,\"text\":\"--¡Tengo celos! ¡estoy loca! ¡Al-Hhamar me desprecia, y me desprecia por tí!\"},{\"heading\":false,\"text\":\"Y Wadah pálida, terrible, convulsa, adelantó hácia Bekralbayda.\"},{\"heading\":false,\"text\":\"La jóven cayó de rodillas.\"},{\"heading\":false,\"text\":\"--¡Perdon! esclamó: ¡perdon! yo no tengo la culpa.\"},{\"heading\":false,\"text\":\"--¡Bebe! esclamó Wadah con voz ronca asiendo violentamente de un brazo á Bekralbayda y presentándola el frasquito de oro.\"},{\"heading\":false,\"text\":\"--¡No! ¡no! gritó Bekralbayda ronca de terror y de desesperacion rechazando el pomo.\"},{\"heading\":false,\"text\":\"--¡Bebe! repitió con acento mas concentrado y terrible Wadah.\"},{\"heading\":false,\"text\":\"--No, gritó con toda la fuerza de su alma la jóven.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡no quieres beber! ¡será preciso que corra otra vez sangre!\"},{\"heading\":false,\"text\":\"--¡Sangre! ¡piadoso Allah! ¡sangre! gritó Bekralbayda: no, no: tú no serás tan infame: yo no te hecho ningun mal.\"},{\"heading\":false,\"text\":\"--¡Que no me has hecho ningun mal y te ama Nazar, y por tí me desprecia, como me despreciaba por Leila-Radhyah!\"},{\"heading\":false,\"text\":\"Y arrastraba furiosa á la jóven que oponia una resistencia desesperada.\"},{\"heading\":false,\"text\":\"De repente Bekralbayda dió un grito agudísimo; uno de esos gritos que el terror arranca del alma: habia visto brillar un puñal en la mano de Wadah, la muerte en sus ojos.\"},{\"heading\":false,\"text\":\"Pero en aquel momento sonó una voz grave, acentuada, terrible, voz que parecia salir de la eternidad, que contuvo el brazo de Wadah y la hizo temblar.\"},{\"heading\":false,\"text\":\"--¡Wadah! habia pronunciado aquella voz.\"},{\"heading\":false,\"text\":\"Y al mismo tiempo se habia abierto con estruendo una puerta frente á Wadah, y habia aparecido en ella Leila-Radhyah.\"},{\"heading\":false,\"text\":\"Wadah dió un grito horrible, dejó caer el puñal y quedó como petrificada, mirando con estupor, con espanto á Leila-Radhyah.\"},{\"heading\":false,\"text\":\"--¡Ella! ¡siempre ella! esclamó con voz sorda: ¡siempre su sombra ensangrentada!\"},{\"heading\":false,\"text\":\"--Sí, sí, yo soy que vengo á impedir un horrible crímen, dijo Leila-Radhyah con acento solemne.\"},{\"heading\":false,\"text\":\"Y adelantó y asió á Bekralbayda que la miraba asombrada, la levantó en sus brazos y la besó en la boca.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡hija mia! esclamó: ¡pobre hija mia!\"},{\"heading\":false,\"text\":\"--¡Su hija! esclamó Wadah con asombro.\"},{\"heading\":false,\"text\":\"--¡Mi hija! ¡crees que es mi hija! ¡pues bien, mira! dijo Leila-Radhyah.\"},{\"heading\":false,\"text\":\"Y desabrochando rápidamente la túnica de Bekralbayda, la descubrió el hombro derecho y mostró á Wadah un lunar rojo que Bekralbayda tenia sobre el hombro.\"},{\"heading\":false,\"text\":\"--¡Mátala si te atreves! esclamó Leila-Radhyah.\"},{\"heading\":false,\"text\":\"Pasó una espresion de indecible angustia por el semblante de Wadah, su frente se cubrió de sudor, sus ojos se dilataron, se puso la mano sobre el corazon, cayó de rodillas y se abalanzó á Bekralbayda; la abrazó y la besó llorando y riendo.\"},{\"heading\":false,\"text\":\"--¡Mi rosa blanca! esclamó: ¡mi hija!\"},{\"heading\":false,\"text\":\"--¡Tu hija! esclamó Bekralbayda rechazándola: no, tú no eres mi madre: si fueras mi madre, la sangre te lo hubiera dicho, no hubieras querido matarme; ¡mi madre tú!\"},{\"heading\":false,\"text\":\"--¡Sí, sí, yo soy tu madre! esclamó arrastrándose á sus pies Wadah: mírame mírame bien... yo tuve una hija... yo creí que la habian matado... pero\"},{\"heading\":false,\"text\":\"Lit de J.J. MARTINEZ, Madrid LETRE dibº y litª]\"},{\"heading\":false,\"text\":\"no... no, eres tú... yo te conozco ahora... ese lunar que tienes sobre el hombro, ese lunar que yo besaba cuando eras pequeñita y te tenia sobre mis rodillas: ¡oh! ¡sí, sí! ¡tú eres mi hija: mi hermosa hija; mi preciosa rosa blanca!\"},{\"heading\":false,\"text\":\"Y abrazaba las rodillas de Bekralbayda que se retiraba constantemente de ella.\"},{\"heading\":false,\"text\":\"--¡Esa muger está loca! dijo Bekralbayda.\"},{\"heading\":false,\"text\":\"--¡Oh! sí, sí, dijo Wadah, he estado loca por tí, hija mia; porque te lloraba muerta: pero he vuelto á encontrarte y ya no estoy loca, no... ¿no es verdad que no estoy loca Leila-Radhyah? ¿no es verdad? díselo tú, díselo, dile que es mi hija... no te vengues de mí porque te maté... yo te maté porque creí que habias matado á mi hija... ¡perdóname! ¡perdóname! ¿qué hubieras tú hecho con la muger que hubiera matado á tu hija?\"},{\"heading\":false,\"text\":\"--Tú no me mataste Wadah: el Dios Unico y Misericordioso no quiso que yo muriese: yo he vivido para ser la madre de tu hija.\"},{\"heading\":false,\"text\":\"--¡Ah! esclamó Wadah levantándose y pasándose ambas manos por la frente como si hubiera pretendido arrancar de su cabeza una vision de sangre; ¿con que no eres un espectro? ¿con que eres tú... tú... la amante de Al-Hhamar viva delante de mí? ¿con que lo que sucedió aquella noche fué un horrible sueño?\"},{\"heading\":false,\"text\":\"--Sueño que ha durado diez y siete años, dijo profundamente Leila-Radhyah; pero yo no sé vengarme, sultana: vete, vete, has querido matar á tu hija sin conocerla, y yo he impedido ese crímen.\"},{\"heading\":false,\"text\":\"--¡Mi hija! esclamó Wadah y lanzó una horrible carcajada: ¡mi hija amante de mi esposo! ¡ah! ¡ah!\"},{\"heading\":false,\"text\":\"Wadah volvia a su locura.\"},{\"heading\":false,\"text\":\"--¡Mi madre! esclamó Bekralbayda volviendo de su sorpresa, ¡es mi madre!\"},{\"heading\":false,\"text\":\"--Sí, tu madre es, dijo Leila-Radhyah.\"},{\"heading\":false,\"text\":\"--¡Y es hijo suyo el príncipe Mohammet! esclamó con espanto Bekralbayda.\"},{\"heading\":false,\"text\":\"--No, dijo el rey Nazar entrando en la cámara: el príncipe Mohammet es hijo de Sobeya mi primera esposa.\"},{\"heading\":false,\"text\":\"--¡Nazar! ¡Nazar! ¡perdóname! ¡perdóname! esclamó Wadah, que tornó por un fenómeno del sentimiento á la razon: perdóname Nazar: yo te engañé; pero yo te amaba... estaba loca por tí... yo te encubrí mi historia, yo te oculté la existencia de la hija de mis entrañas.\"},{\"heading\":false,\"text\":\"--Esto ha sido un sueño, un sueño sombrío, dijo Al-Hhamar.\"},{\"heading\":false,\"text\":\"--¡Un sueño!\"},{\"heading\":false,\"text\":\"--¡Sí! yo no te he conocido Wadah: tú no has existido para mí, vete.\"},{\"heading\":false,\"text\":\"--¡Me arrojas, me arrojas de tí como una esclava! esclamó llorando Wadah.\"},{\"heading\":false,\"text\":\"--No, no te arrojo, dijo el rey Nazar: vivirás en mi alcázar, te servirán esclavos, pero no me volverás á ver.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡no!.. ¡rechazada por mi hija, rechazada por tí... sola y desesperada!.. ¡no... no... Nazar! ¡yo no puedo vivir así!\"},{\"heading\":false,\"text\":\"--Yo soy la que debe desaparecer, dijo Leila Radhyah: quedaos vosotros y sed felices.\"},{\"heading\":false,\"text\":\"--El embajador que ha de anunciar á tu padre que eres sultana de Granada ha partido ya, dijo Nazar.\"},{\"heading\":false,\"text\":\"--¡Sultana de Granada tú, Leila Radhyah! esclamó en el colmo del dolor Wadah; sí, sí, sélo en buen hora, pero yo no lo veré.\"},{\"heading\":false,\"text\":\"Y antes de que ninguno de los que la acompañaba pudiera evitarlo ni impedirlo, apuró el contenido del pomo de oro.\"},{\"heading\":false,\"text\":\"--¡Qué has hecho! esclamó horrorizado el rey Nazar.\"},{\"heading\":false,\"text\":\"--¡Morir! contestó Wadah, arrojándose sobre el divan y cubriéndose el rostro con las manos.\"},{\"heading\":false,\"text\":\"--Esta es la justicia de Dios, dijo una voz sonora á la puerta de la cámara.\"},{\"heading\":false,\"text\":\"Era la voz de Yshac-el-Rumi que entró.\"},{\"heading\":false,\"text\":\"--¡Ah! vienes á tiempo, esclamó el rey: tú eres sábio, tú eres astrólogo: tú encontrarás un medio de salvar á esa desdichada.\"},{\"heading\":false,\"text\":\"--Mira, sultan Nazar, dijo Yshac-el-Rumi, apartando las manos de Wadah de su semblante que estaba pálido é inmóvil.\"},{\"heading\":false,\"text\":\"--¡Muerta! esclamó el rey Nazar.\"},{\"heading\":false,\"text\":\"--Sí, muerta: era necesario que fuesen vengados Leila-Radhyah y Daniel el Bokarí.\"},{\"heading\":false,\"text\":\"--¿Y has sido tú?\"},{\"heading\":false,\"text\":\"--Sí, yo he sido el brazo de la justicia de Dios.\"},{\"heading\":false,\"text\":\"--¡Y tú, tú acaso tambien!... esclamó el rey mirando con ansiedad á Leila-Radhyah.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡no! esclamó horrorizada Leila-Radhyah: ¡yo no se asesinar!\"},{\"heading\":false,\"text\":\"--He sido yo, dijo Yshac-el-Rumi, y salió lentamente de la cámara.\"},{\"heading\":false,\"text\":\"El rey Nazar huyó de ella.\"},{\"heading\":false,\"text\":\"Leila-Radhyah levantó á Bekralbayda y se la llevó consigo.\"},{\"heading\":false,\"text\":\"El cadáver de Wadah quedó allí solo y abandonado.\"}]},{\"title\":\"El mirador de la sultana. — capítulo IV: En que yshac-el-rumi hace pensar al rey nazar.\",\"blocks\":[{\"heading\":false,\"text\":\"Pasaron algunos dias.\"},{\"heading\":false,\"text\":\"Wadah habia sido enterrada con toda la pompa que corresponde á una sultana.\"},{\"heading\":false,\"text\":\"La córte del rey Nazar llevó luto.\"},{\"heading\":false,\"text\":\"El mismo dia en que se sepultó á Wadah, apareció en un palo en la plaza de Raab-Abayda en el Albaicin la cabeza del alcaide de los eunucos.\"},{\"heading\":false,\"text\":\"El rey habia llamado á Yshac, y Yshac se le habia presentado.\"},{\"heading\":false,\"text\":\"--Toma mi cabeza, señor, si te place, le dijo: yo he hecho lo que he debido hacer: he cumplido la última voluntad de Daniel-el-Bokarí: le he vengado de esa infame Wadah, he casado su hija con tu hijo; porque tú los casarás sultan, y te he obligado á construir, por tu amor á Bekralbayda, el Palacio-de-Rubíes: además de eso te he devuelto tu amada Leila-Radhyah.\"},{\"heading\":false,\"text\":\"--¿Y si yo hubiese sido amante de la amante de mi hijo? esclamó severamente el rey.\"},{\"heading\":false,\"text\":\"--Yo sabia que Bekralbayda no podia amarte; que no seria tuya sino por la violencia, y que tú eras demasiado noble y grande, para valerte de la violencia contra una débil muger.\"},{\"heading\":false,\"text\":\"--¿Pero si me hubiere enloquecido el amor?\"},{\"heading\":false,\"text\":\"--Yo te he seguido como tu sombra: en el momento preciso yo me hubiera puesto entre tí y Bekralbayda y te hubiera dicho: es la esposa de tu hijo: es la hija de tu esposa.\"},{\"heading\":false,\"text\":\"--¿Y por qué antes no me lo has revelado todo?\"},{\"heading\":false,\"text\":\"--¿Ha podido Wadah concluir de una manera mas justiciera y en que menos parte hubieras tú podido tener en su muerte?\"},{\"heading\":false,\"text\":\"El rey se puso á pasear lentamente por su cámara.\"},{\"heading\":false,\"text\":\"--Has jugado imprudentemente con el leon, dijo.\"},{\"heading\":false,\"text\":\"--Toma mi cabeza, señor, en buen hora: pero tómala despues que yo haya visto á Bekralbayda esposa de tu hijo: á Leila-Radhyah esposa tuya.\"},{\"heading\":false,\"text\":\"--Tu cabeza me hace suma falta, dijo el rey alzando á Yshac que se habia prosternado á sus pies.\"},{\"heading\":false,\"text\":\"--No en vano te llaman los tuyos el justo y el magnífico; esclamó Yshac.\"},{\"heading\":false,\"text\":\"--No se, no se, si soy bastante justo dejando de castigarte: pero á tí debe mi hijo una esposa noble, pura, digna de él: á tí debe mi Granada, el alcázar que construyo, y yo en fin te debo el amor de mi alma: la muger á quien nunca debí haber abandonado, la hermosa sultana Leila-Radhyah. No me atrevo, pues, á tocar á tu cabeza.\"},{\"heading\":false,\"text\":\"--Tú eres grande y justo, repitió Yshac.\"},{\"heading\":false,\"text\":\"--Mañana dijo el rey, se harán en el alcázar dos bodas; consulta las estrellas, Yshac.\"},{\"heading\":false,\"text\":\"--Las estrellas son mudas, dijo el anciano.\"},{\"heading\":false,\"text\":\"--¡Mudas! sin embargo, tú me has hablado en nombre de ellas.\"},{\"heading\":false,\"text\":\"--Me preguntaba tu supersticion.\"},{\"heading\":false,\"text\":\"--¿Es decir que la astrología es mentira?\"},{\"heading\":false,\"text\":\"--Pregunta á un astrólogo cuando vá á morir.\"},{\"heading\":false,\"text\":\"--Tú me has contado cosas maravillosas.\"},{\"heading\":false,\"text\":\"--Era necesario usar contigo de todos los medios para llegar al punto donde hemos llegado.\"},{\"heading\":false,\"text\":\"--Me has contado la historia maravillosa del rey Abuz-Aben-Huz el sábio.\"},{\"heading\":false,\"text\":\"--Ha sido un cuento inventado por mí.\"},{\"heading\":false,\"text\":\"--¿Y el buho, ese terrible buho que me persigue?\"},{\"heading\":false,\"text\":\"--En Granada hay muchas torres, y en sus mechinales anidan muchos buhos: es muy fácil encontrar de noche esas alimañas.\"},{\"heading\":false,\"text\":\"--¿Con que es decir, que la ciencia es mentira?\"},{\"heading\":false,\"text\":\"--Sí; la ciencia, que quiere soberbia y vana sobreponerse á la voluntad de Dios, que ha querido que el hombre no conozca mas que lo que pueda conocer, es una mentira y un pecado.\"},{\"heading\":false,\"text\":\"--¡Seria necesario, pues, castigar á los astrólogos!\"},{\"heading\":false,\"text\":\"--No seria prudente, porque el vulgo los cree inspirados por Dios, y te demandarian de impiedad.\"},{\"heading\":false,\"text\":\"--Déjame solo, dijo el rey que se habia quedado profundamente pensativo.\"},{\"heading\":false,\"text\":\"Yshac salió.\"},{\"heading\":false,\"text\":\"El rey continuó paseándose por su cámara.\"},{\"heading\":false,\"text\":\"--¡Con que la ciencia de lo infinito es una mentira! ¡con que solo Dios conoce lo oculto! esclamó el rey: y sin embargo, nos dejamos arrastrar por las imágenes de la astrología; ¡con que es decir que el hombre camina á tientas por un sendero de tinieblas al borde de un abismo, y solo la virtud puede servirle de guia segura é impedirle que caiga! No sé qué pensar de ese Yshac: su mirada erraba sombría cuando hablaba conmigo; parecia poseido de una tristeza profunda y de una aguda desesperacion. Y sin embargo, no se por qué desconfio de él: hasta ahora no me ha hecho mas que bien.\"},{\"heading\":false,\"text\":\"El rey siguió paseando.\"},{\"heading\":false,\"text\":\"De repente se detuvo y llamó á su wacir.\"},{\"heading\":false,\"text\":\"Presentóse el anciano.\"},{\"heading\":false,\"text\":\"--Irás á las habitaciones de la sultana Bekralbayda.\"},{\"heading\":false,\"text\":\"--Iré señor.\"},{\"heading\":false,\"text\":\"--La dirás que tú, sabiendo que ama al príncipe Mohammet, quieres conducirla á su prision.\"},{\"heading\":false,\"text\":\"--¿Y la conduciré?\"},{\"heading\":false,\"text\":\"--Sí; esta noche.\"},{\"heading\":false,\"text\":\"--¿Y cuánto tiempo permanecerá allí la sultana?\"},{\"heading\":false,\"text\":\"--Déjalos solos y avísame.\"},{\"heading\":false,\"text\":\"El wacir se inclinó y salió.\"},{\"heading\":false,\"text\":\"El rey Nazar atravesó algunas cámaras, llegó á una puerta y la abrió.\"},{\"heading\":false,\"text\":\"Una muger se arrojó en sus brazos.\"},{\"heading\":false,\"text\":\"Aquella muger era Leila-Radhyah.\"}]},{\"title\":\"El mirador de la sultana. — capítulo V: Celos y misterio.\",\"blocks\":[{\"heading\":false,\"text\":\"Era la media noche.\"},{\"heading\":false,\"text\":\"El príncipe Mohammet velaba en su alto calabozo de la torre del Gallo de viento.\"},{\"heading\":false,\"text\":\"La veleta rechinaba.\"},{\"heading\":false,\"text\":\"Sin embargo, la lanza del caballero no se fijaba en ningun punto.\"},{\"heading\":false,\"text\":\"El príncipe, para entretener su tristeza, leia los amores del poeta cordobés, Abu-Amar, que tenian mucha semejanza con los suyos.\"},{\"heading\":false,\"text\":\"De tiempo en tiempo se asomaba á una ventana y miraba á un ángulo del patio á un ajimez donde se veia el reflejo de una luz y delante de aquel reflejo una sombra de muger.\"},{\"heading\":false,\"text\":\"Pero una de las veces que el príncipe miró á aquel ajimez, le encontró oscuro.\"},{\"heading\":false,\"text\":\"Pasó algun tiempo, y el ajimez permaneció abandonado.\"},{\"heading\":false,\"text\":\"Al fin, vió luz en la galería inferior y aparecieron una muger que iba enteramente cubierta con un velo, acompañada de un anciano que la alumbraba con una lámpara.\"},{\"heading\":false,\"text\":\"A pesar de ir tan cuidadosamente encubierta la dama, el príncipe la reconoció.\"},{\"heading\":false,\"text\":\"--¿A dónde irá á estas horas y acompañada de un viejo Bekralbayda? esclamó con celos y con rabia.\"},{\"heading\":false,\"text\":\"La muger y el viejo atravesaron el patio y desaparecieron por otra parte de la galería.\"},{\"heading\":false,\"text\":\"El príncipe continuó abstraido en la ventana.\"},{\"heading\":false,\"text\":\"Poco despues se oyó un ligero ruido en la escalera de la torre.\"},{\"heading\":false,\"text\":\"Luego la llave de los cerrojos de la compuerta.\"},{\"heading\":false,\"text\":\"Al cabo la compuerta se alzó, y apareció una muger.\"},{\"heading\":false,\"text\":\"Volvió á caer la compuerta y la muger quedó sola é inmóvil aunque estremecida delante del príncipe.\"},{\"heading\":false,\"text\":\"El príncipe creyó reconocerla de nuevo y la arrancó el velo.\"},{\"heading\":false,\"text\":\"No se habia engañado.\"},{\"heading\":false,\"text\":\"Era Bekralbayda, pero de luto.\"},{\"heading\":false,\"text\":\"A causa de la sencillez de su trage, estaba mas hermosa.\"},{\"heading\":false,\"text\":\"El príncipe fué á arrojarse en sus brazos.\"},{\"heading\":false,\"text\":\"--Detente, dijo ella, la desgracia nos separa.\"},{\"heading\":false,\"text\":\"--¡La desgracia! esclamó el príncipe.\"},{\"heading\":false,\"text\":\"--Sí; tu padre no consiente en nuestra union.\"},{\"heading\":false,\"text\":\"--¡Ah! esclamó el príncipe; me habia olvidado, es verdad.\"},{\"heading\":false,\"text\":\"--Y... ¿qué es verdad?\"},{\"heading\":false,\"text\":\"--Tú no puedes ser mi esposa, porque...\"},{\"heading\":false,\"text\":\"--¿Por qué?\"},{\"heading\":false,\"text\":\"--Yo te he visto perderte con mi padre en los bosques de los jardines.\"},{\"heading\":false,\"text\":\"--¿Y has creido acaso?\"},{\"heading\":false,\"text\":\"--Yo sé que mi padre te ama.\"},{\"heading\":false,\"text\":\"--Sí, es verdad; el rey Nazar me ama.\"},{\"heading\":false,\"text\":\"--Cúmplase la voluntad de Dios.\"},{\"heading\":false,\"text\":\"--Pero yo no he sido del rey Nazar.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡tú me engañas!\"},{\"heading\":false,\"text\":\"--Dios no ha permitido que yo sea del rey Nazar, porque no ha querido que se cometan dos crímenes.\"},{\"heading\":false,\"text\":\"--¡Dos crímenes!\"},{\"heading\":false,\"text\":\"--Yo hubiera muerto de vergüenza y dolor si el rey Nazar me hubiera hecho suya por la violencia; y el rey Nazar haciéndome suya hubiera cometido un incesto.\"},{\"heading\":false,\"text\":\"--¡Un incesto!\"},{\"heading\":false,\"text\":\"--Sí, ¿no vés mi luto?\"},{\"heading\":false,\"text\":\"--¡Ese luto!\"},{\"heading\":false,\"text\":\"--Este luto es por mi madre.\"},{\"heading\":false,\"text\":\"--¡Por tu madre! ¿y quién es tu madre?\"},{\"heading\":false,\"text\":\"--La sultana Wadah.\"},{\"heading\":false,\"text\":\"--¡La sultana Wadah! ¡la esposa de mi padre!\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Eres acaso mi hermana?\"},{\"heading\":false,\"text\":\"--No: Dios no lo ha querido.\"},{\"heading\":false,\"text\":\"--¿Pero si eres hija de la sultana Wadah...?\"},{\"heading\":false,\"text\":\"--Yo habia nacido antes de que el rey Nazar conociese á mi madre.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿y sabe el rey mi padre que tú eres hija de su esposa?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¡Ah! de modo que...\"},{\"heading\":false,\"text\":\"--Sí... sí... el rey Nazar no me perseguirá mas; pero...\"},{\"heading\":false,\"text\":\"--Te encerrará, te guardará, tendrá celos...\"},{\"heading\":false,\"text\":\"--¿Tendrá celos de tí?\"},{\"heading\":false,\"text\":\"--¡De mí! ¡Dios mio! yo sabia que mi padre te amaba, y aunque en los primeros momentos he tenido celos, despues estos celos me han horrorizado: mi padre es mi señor, yo soy su hijo y su siervo: él puede hacer de mí y de lo mio lo que mejor quiera: yo no puedo dejar de amarle y respetarle.\"},{\"heading\":false,\"text\":\"--Por lo mismo, Mohammet, yo he aprovechado la buena voluntad de un wacir de tu padre que se ha brindado á traerme aquí.\"},{\"heading\":false,\"text\":\"--¿Y para qué vienes?\"},{\"heading\":false,\"text\":\"--Para decirte que es necesario que me olvides.\"},{\"heading\":false,\"text\":\"--¿Me olvidarás tú?\"},{\"heading\":false,\"text\":\"--¡Ah! esclamó Bekralbayda.\"},{\"heading\":false,\"text\":\"Y se echó á llorar.\"},{\"heading\":false,\"text\":\"--Tu padre te tiene preso por mi amor: añadió la jóven.\"},{\"heading\":false,\"text\":\"--Mi padre me matará quitándome tu amor: esclamó el príncipe.\"},{\"heading\":false,\"text\":\"--Hemos nacido muy desgraciados.\"},{\"heading\":false,\"text\":\"--Que se cumpla la voluntad de Dios.\"},{\"heading\":false,\"text\":\"En aquel momento se oyeron en las escaleras pasos de muchos hombres armados.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡Dios poderoso! esclamó el príncipe, viene gente á mi prision y es necesario que te ocultes.\"},{\"heading\":false,\"text\":\"--¡Que me oculte! ¿y dónde?\"},{\"heading\":false,\"text\":\"--¡Ah! es verdad, esclamó con desesperacion Mohammet, cúbrete con tu velo.\"},{\"heading\":false,\"text\":\"Bekralbayda se cubrió precipitadamente.\"},{\"heading\":false,\"text\":\"Poco despues se oyeron los cerrojos de la compuerta que se abrió.\"},{\"heading\":false,\"text\":\"Apareció un walí, que se prosternó ante el príncipe.\"},{\"heading\":false,\"text\":\"--¿Qué quereis? le dijo este.\"},{\"heading\":false,\"text\":\"--El poderoso y magnífico sultan tu padre me manda llevarte á su presencia con las personas que se encuentren contigo.\"},{\"heading\":false,\"text\":\"--¿Lo manda así el sultan?\"},{\"heading\":false,\"text\":\"--Así lo manda.\"},{\"heading\":false,\"text\":\"El príncipe se encaminó á las escaleras y las bajó resueltamente.\"},{\"heading\":false,\"text\":\"Bekralbayda le siguió.\"},{\"heading\":false,\"text\":\"Tras él iban el walí y los soldados silenciosos.\"},{\"heading\":false,\"text\":\"Cuando estuvieron en la parte del alcázar habitada por el sultan Nazar, el walí abrió la puerta de una cámara donde dejó solos al príncipe y á Bekralbayda.\"}]},{\"title\":\"El mirador de la sultana. — capítulo VI: Misterios.\",\"blocks\":[{\"heading\":false,\"text\":\"Aquella cámara era de las mas bellas del palacio del Gallo de viento.\"},{\"heading\":false,\"text\":\"Un ancho divan de seda y una lámpara velada convidaban al reposo.\"},{\"heading\":false,\"text\":\"Búcaros de flores se veian por todas partes.\"},{\"heading\":false,\"text\":\"Braserillos de oro quemaban deliciosos perfumes.\"},{\"heading\":false,\"text\":\"A lo lejos, entre el silencio, se oia una guzla á cuyo son cantaba una voz de muger una cancion de amores.\"},{\"heading\":false,\"text\":\"El príncipe y Bekralbayda estaban de pié en medio de la cámara.\"},{\"heading\":false,\"text\":\"Esperaban.\"},{\"heading\":false,\"text\":\"Pero pasó el tiempo... mucho tiempo y nadie apareció.\"},{\"heading\":false,\"text\":\"Bekralbayda se sentó, al fin cansada, en el divan.\"},{\"heading\":false,\"text\":\"El príncipe fué á apoyarse en silencio en el alfeizar de un ajimez.\"},{\"heading\":false,\"text\":\"No se atrevian á acercarse ni á hablarse por temor de ser oidos y escuchados.\"},{\"heading\":false,\"text\":\"Pasó la noche y llegó el alba.\"},{\"heading\":false,\"text\":\"El príncipe oyó el ruido de los añafiles y de las atakebiras que despertaban á los soldados del rey Nazar.\"},{\"heading\":false,\"text\":\"Poco despues vió pasar bajo el ajimez caballos magníficamente enjaezados, esclavos deslumbrantemente vestidos, banderas y soldados.\"},{\"heading\":false,\"text\":\"--¿Qué fiesta irá á celebrarse hoy? pensaba el príncipe al ver todo aquello.\"},{\"heading\":false,\"text\":\"Bekralbayda, que no habia dormido, oia tambien todo aquel tráfago y se maravillaba.\"},{\"heading\":false,\"text\":\"De repente se abrió la puerta de la izquierda de la cámara y apareció el nuevo alcaide de los eunucos.\"},{\"heading\":false,\"text\":\"--Poderosa sultana, dijo prosternándose ante Bekralbayda, ven si quieres á que tus esclavas engalanen tu hermosura.\"},{\"heading\":false,\"text\":\"--¿Lo manda el sultan?\"},{\"heading\":false,\"text\":\"--El esclarecido y magnífico sultan Nazar quiere que arrojes de tí la tristeza, luz de los cielos.\"},{\"heading\":false,\"text\":\"--Cúmplase la voluntad del señor: dijo Bekralbayda y se levantó y siguió al alcaide de los eunucos.\"},{\"heading\":false,\"text\":\"El príncipe vió salir á Bekralbayda con inquietud.\"},{\"heading\":false,\"text\":\"En aquel punto se abrió la puerta de la derecha y apareció el alcaide de los esclavos de palacio.\"},{\"heading\":false,\"text\":\"--Poderoso príncipe y señor, dijo prosternándose, ven si te place á que tus esclavos te cubran de las vestiduras reales.\"},{\"heading\":false,\"text\":\"El príncipe salió.\"},{\"heading\":false,\"text\":\"La cámara quedó desierta.\"},{\"heading\":false,\"text\":\"Fuera crecia á cada momento el ruido de las gentes de armas, de las pisadas de los caballos, y del toque de añafiles y timbales.\"},{\"heading\":false,\"text\":\"Asomaba por el oriente un sol esplendoroso y todo anunciaba un gran dia.\"}]},{\"title\":\"El mirador de la sultana. — capítulo VII: El pergamino sellado.\",\"blocks\":[{\"heading\":false,\"text\":\"Aun no habia acabado de levantarse el sol sobre la cumbre del Veleta, cuando el rey Nazar departia mano á mano con Yshac-el-Rumi.\"},{\"heading\":false,\"text\":\"--Estoy satisfecho de ellos, le decia, y soy feliz.\"},{\"heading\":false,\"text\":\"--¡Ah señor! tú has nacido para la gloria y para la fortuna: esclamó Yshac tristemente.\"},{\"heading\":false,\"text\":\"--¿Paréceme que te pesa de mi felicidad? dijo con recelo el rey.\"},{\"heading\":false,\"text\":\"--¡Ah! no, no señor: es que soy tan desgraciado que la alegría me entristece, y hoy hasta el dia es alegre.\"},{\"heading\":false,\"text\":\"Hubo un momento de silencio:\"},{\"heading\":false,\"text\":\"--Pero esto no importa, continuó Yshac; lo que yo queria lo he conseguido, Leila-Radhyah y Bekralbayda son felices; ¿qué mas puedo yo desear?\"},{\"heading\":false,\"text\":\"--A propósito, es necesario que vayas á traer á Bekralbayda; el camino es por aquí.\"},{\"heading\":false,\"text\":\"Y el rey abrió una puerta secreta.\"},{\"heading\":false,\"text\":\"Cuando salia Yshac, entraba por otra puerta una muger magnífica y resplandeciente: era Leila-Radhyah.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡luz de mis ojos! esclamó el rey: al fin luce para nosotros el dia de la felicidad.\"},{\"heading\":false,\"text\":\"--Y para nuestros hijos tambien.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡y cuán lejos está de sospechar su ventura mi hijo!\"},{\"heading\":false,\"text\":\"--¡Y cuán digno es de ser feliz! ¡pobre niño! tres meses encerrado con su amor y su desesperacion en aquella torre.\"},{\"heading\":false,\"text\":\"--Eso le hará mas querido á su esposa, y le enseñará á respetar mas mis órdenes; pero ve, ve tú por él, vida de mi vida: quiero que tú seas quien me le traiga á mis pies para que le perdone.\"},{\"heading\":false,\"text\":\"Leila-Radhyah sonrió de una manera enloquecedora, lanzó un relámpago de amor de sus negros ojos al rey, y desapareció por una puerta.\"},{\"heading\":false,\"text\":\"Al-Hhamar el magnífico, sacó entonces de un arca un pliego cerrado y le puso en una bandeja de oro sobre una mesa.\"},{\"heading\":false,\"text\":\"Pasó algun tiempo, y al fin aparecieron por dos puertas distintas Leila-Radhyah, trayendo de la mano al príncipe Mohammet; Yshac-el-Rumi, llevando del mismo modo á Bekralbayda.\"},{\"heading\":false,\"text\":\"Al verse los dos jóvenes delante del rey, palidecieron y temblaron.\"},{\"heading\":false,\"text\":\"No sabian lo que iba á ser de ellos.\"},{\"heading\":false,\"text\":\"El rey adelantó hácia Bekralbayda, la besó en la frente, la asió de la mano y la llevó hasta su hijo, á quien abrazó.\"},{\"heading\":false,\"text\":\"--Tú amas á Bekralbayda, dijo el rey Nazar al príncipe Mohammet.\"},{\"heading\":false,\"text\":\"El príncipe bajó los ojos, creció su palidez y mirando al fin á su padre con temor le dijo con acento trémulo:\"},{\"heading\":false,\"text\":\"--Tanto la amo, que por ella he provocado tu enojo, señor.\"},{\"heading\":false,\"text\":\"--Y tú, tú tambien amas al príncipe mi hijo, Bekralbayda.\"},{\"heading\":false,\"text\":\"--El destino ha querido que sea suya mi alma, contestó Bekralbayda.\"},{\"heading\":false,\"text\":\"--Tú, dijo el rey Nazar dirigiéndose á su hijo, has tenido celos de tu padre.\"},{\"heading\":false,\"text\":\"--¡Ah señor! murmuró el príncipe.\"},{\"heading\":false,\"text\":\"--Y tú, añadió el rey, volviéndose á Bekralbayda te has creido amada por mí.\"},{\"heading\":false,\"text\":\"Bekralbayda calló.\"},{\"heading\":false,\"text\":\"--Es verdad dijo el rey que yo he buscado tus amores.\"},{\"heading\":false,\"text\":\"Leila-Radhyah palideció intensamente al oir esta confesion del rey y dió un paso hácia adelante.\"},{\"heading\":false,\"text\":\"--Pero antes de pedirte amores, continuó el rey Nazar, escribí lo que se contiene en ese pergamino que está cerrado sobre esa bandeja y sellado con mi sello. Tú Bekralbayda escribiste tu nombre sobre el pergamino cerrado ¿le conoces?\"},{\"heading\":false,\"text\":\"El rey tomó el pergamino y le mostró á Bekralbayda.\"},{\"heading\":false,\"text\":\"--Sí señor, dijo la jóven, este es el pergamino que tú escribiste la primera vez que hablaste conmigo, que cerraste y sobre el cual me mandaste escribir mi nombre.\"},{\"heading\":false,\"text\":\"--¿Recuerdas esta circunstancia, Yshac-el-Rumi? añadió el rey volviéndose al viejo.\"},{\"heading\":false,\"text\":\"--Sí señor, dijo este, tú escribiste ese pergamino y le sellaste y mandaste que pusiese sobre él su nombre á Bekralbayda, la primera vez que hablaste con ella.\"},{\"heading\":false,\"text\":\"--Rompe el sello de ese pergamino, Bekralbayda, desenróllale y léele en alta voz.\"},{\"heading\":false,\"text\":\"La jóven obedeció, desenrolló el pergamino y leyó con voz trémula lo siguiente:\"},{\"heading\":false,\"text\":\"«He conocido una doncella blanca de ojos negros.\"},{\"heading\":false,\"text\":\"Es hermosa como las huríes que el Señor promete á sus escogidos, y pura como la violeta que se esconde entre el cesped á la márgen de los arroyos.\"},{\"heading\":false,\"text\":\"Mi hijo primogénito, el príncipe Mohammet Abd-Allah, mi sucesor y mi compañero en el gobierno de mis reinos, la conoce tambien y la ama.\"},{\"heading\":false,\"text\":\"Por ella ha desobedecido mis órdenes, ha dejado abandonadas en el castillo de Alhama mi bandera y mis gentes de guerra, y se ha venido á Granada enloquecido de amor.\"},{\"heading\":false,\"text\":\"Yo debo castigar al príncipe y le castigaré.\"},{\"heading\":false,\"text\":\"Pero yo tambien debo hacer su felicidad y procuraré hacerla.\"},{\"heading\":false,\"text\":\"Ama con toda su alma á Bekralbayda.\"},{\"heading\":false,\"text\":\"Bekralbayda será esposa de mi hijo si es digna de su amor.\"},{\"heading\":false,\"text\":\"Yo rodearé á Bekralbayda de cuantas seducciones pueden enloquecer á una muger.\"},{\"heading\":false,\"text\":\"Me fingiré enamorado de ella.\"},{\"heading\":false,\"text\":\"La ofreceré mis tesoros, y si esto no bastare, la ofreceré mi trono.\"},{\"heading\":false,\"text\":\"Si resistiere á esto, procuraré aterrarla.\"},{\"heading\":false,\"text\":\"Si Bekralbayda no resiste á la ambicion, la alejaré de mi hijo.\"},{\"heading\":false,\"text\":\"Porque una muger que ama, y que ha pertenecido á otro hombre debe despreciarlo todo por el hombre de su amor.\"},{\"heading\":false,\"text\":\"Si resistiere á la ambicion y sucumbiere al miedo, la apartaré tambien de mi hijo, porque una muger que ama, debe morir antes que ofender al hombre de su amor.\"},{\"heading\":false,\"text\":\"»Pero si Bekralbayda conservare la fé que ha jurado al príncipe mi hijo, á pesar de mis dádivas, de mis promesas y de mis amenazas, será esposa del príncipe, porque será digna de él.\"},{\"heading\":false,\"text\":\"Yo por mí mismo pondré á prueba la virtud de Bekralbayda, porque tratándose de la felicidad de mi hijo, de nadie me fio mas que de mí mismo.\"},{\"heading\":false,\"text\":\"Despues de haber adoptado esta resolucion he escrito esta gacela, que enrollaré y sellaré, y sobre la cual pondrá Bekralbayda su nombre.\"},{\"heading\":false,\"text\":\"De este modo, ya la entregue á mi hijo, ya la separe de él, podré hacerla comprender cuáles han sido mis intenciones al pedirla amores, y no podrá dudar de mi nobleza y de mi fé como caballero y como rey.»\"},{\"heading\":false,\"text\":\"Bekralbayda habia leido lentamente y con acento trémulo este escrito; durante su lectura el corazon del príncipe y de la sultana Leila-Radhyah habian latido violentamente.\"},{\"heading\":false,\"text\":\"--Ya lo habeis oido, dijo el rey: necesitaba saber si Bekralbayda era digna de mi hijo, y la he sujetado á grandes pruebas: Bekralbayda ha salido de ellas victoriosa: Bekralbayda es la esposa de mi hijo.\"},{\"heading\":false,\"text\":\"Y asiendo á la jóven de la mano, la arrojó en los brazos del príncipe.\"},{\"heading\":false,\"text\":\"Los dos jóvenes se arrojaron á los pies del rey Nazar, llorando de alegría.\"},{\"heading\":false,\"text\":\"Leila-Radhyah lloraba tambien.\"},{\"heading\":false,\"text\":\"Yshac-el-Rumi, estaba pálido, trémulo, con la vista fija en el suelo.\"},{\"heading\":false,\"text\":\"En aquel momento resonó fuera una alegre música, y luego alto alarido de trompetas y ronco doblar de timbales y atambores.\"},{\"heading\":false,\"text\":\"--Ha llegado la hora, dijo el rey Nazar: hoy serán las bodas del sultan de Granada con la noble y hermosa sultana Leila-Radhyah, y las de su hijo el príncipe Mohammet, con el sol de los soles la sultana Bekralbayda.\"},{\"heading\":false,\"text\":\"Y asiendo de la mano á Leila-Radhyah, salió de la cámara, seguido de su hijo y de Bekralbayda, á los que seguia con paso lento y á alguna distancia con la cabeza inclinada Yshac-el-Rumi, que murmuraba en acento ininteligible:\"},{\"heading\":false,\"text\":\"--¡Todos son felices! ¡todos menos yo!\"}]},{\"title\":\"El mirador de la sultana. — capítulo VIII: En que se da fin á esta maravillosa historia.\",\"blocks\":[{\"heading\":false,\"text\":\"Y hubo aquella noche zambra en el alcázar en celebridad de aquellas dobles bodas, y durante ocho dias justas, sortijas, toros y cañas en Bibarrambla.\"},{\"heading\":false,\"text\":\"Se dieron cuantiosas limosnas á los pobres, y se pusieron en libertad centenares de cautivos.\"},{\"heading\":false,\"text\":\"Todo el mundo estaba alegre.\"},{\"heading\":false,\"text\":\"Granada disfrutaba de una paz inalterable bajo el justo y sábio dominio del sultan Nazar; crecia en comercio y en industria, y por lo tanto en riqueza, y en aquellas alegres y felices bodas veian los súbditos de Al-Hhamar el augurio de nuevas prosperidades.\"},{\"heading\":false,\"text\":\"Solo un hombre asistió triste y silencioso á aquellas bodas, á pesar de que el rey le habia honrado y favorecido nombrándole wacir y concediéndole grandes mercedes.\"},{\"heading\":false,\"text\":\"Aquel hombre era Yshac-el-Rumi.\"},{\"heading\":false,\"text\":\"Terminadas las fiestas, Yshac desapareció sin despedirse del rey ni de Leila-Radhyah, ni del príncipe ni de Bekralbayda.\"},{\"heading\":false,\"text\":\"En vano el rey movido de piedad, porque creia comprender la causa de la desaparicion de Yshac, ofreció una fuerte cantidad al que le encontrase.\"},{\"heading\":false,\"text\":\"Nadie supo lo que habia sido de él.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Entretanto la construccion del Palacio-de-Rubíes continuaba.\"},{\"heading\":false,\"text\":\"Nazar le habia dado su nombre.\"},{\"heading\":false,\"text\":\"Aquel alcázar que prometia ser maravilloso, se llamaba la Alhambra[40].\"},{\"heading\":false,\"text\":\"Al-Hhamar habia terminado la Alcazaba que mira al occidente, donde se levantan aún la torre de la Vela, la del Homenage y los Adarves; la plaza de las Cisternas, colocadas entre el muro interno de la Alcazaba y la fachada principal del alcázar, y toda la parte de este, desde la plaza de las Cisternas (hoy de los Algibes) hasta la torre de las Siete Bóvedas, y la de las Infantas; lo restante del recinto crecia: levantábanse ya sobre la ladera del monte los muros de Djene-al-Arife[41], mas arriba los del castillo de la Silla del Moro, mas allá, en el cerro del Sol, los del palacio de los Alijares, y por último, sobre la colina de Al-Bunets (hoy de los Mártires), crecian los muros del recinto de las Torres Bermejas.\"},{\"heading\":false,\"text\":\"Pero Al-Hhamar no pudo ver terminado su alcázar; solo habia visto parte de él: la torre del Juicio; la parte en que hoy se alza el palacio del emperador Cárlos V; la gran mezquita en cuyo mirab habia ocho columnas con capiteles de oro, en cuyo lugar se levanta hoy la iglesia de Santa María; la mezquita del palacio que aun se conserva; el patio del Mexuar ó del Consejo (hoy del Estanque ó de los Arrayanes); la sala de Comares y el Mirador de la sultana.\"},{\"heading\":false,\"text\":\"Los demás retretes, cámaras, patios, jardines y departamentos estaban únicamente comenzados, trazados, preparados, pero en embrion.\"},{\"heading\":false,\"text\":\"Sus nietos debian terminar aquella maravilla.\"},{\"heading\":false,\"text\":\"Su hijo, su nieto y su biznieto continuaron lentamente su construccion.\"},{\"heading\":false,\"text\":\"Su tercer nieto Ismail Abul-Walid concluyó el delicioso palacio del Generalife; por último, su cuarto nieto Juzef-Abul-Hhedjadj, vió al fin completo aquel acrópolo inmenso que cubria cuatro montes, compuesto por la Alhambra, por el Generalife, por el palacio de la Silla del moro, por el de los Alijares y por las Torres Bermejas.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Por el año de la Hegira 650, durante la luna de Xawan, unos labradores trajeron al rey Nazar, que ya contaba sesenta años, una caja de lata cerrada, sobre la cual se leia.\"},{\"heading\":false,\"text\":\"«Solo el poderoso sultan Nazar ó su hijo, si ha muerto, cuando se encuentre esta caja deben ver, so pena de traicion de quien la encuentre, lo que en ella se contiene.»\"},{\"heading\":false,\"text\":\"Aquella caja se habia encontrado en lo profundo de una gruta del rio Darro, cuya entrada correspondia á un ensanchamiento en que habia un remanso, entre las ropas podridas de un esqueleto humano.\"},{\"heading\":false,\"text\":\"El rey Nazar mandó abrir aquella caja, y dentro se encontró un pergamino muy bien conservado, en que se leia lo siguiente:\"},{\"heading\":false,\"text\":\"«Yo amaba con toda mi alma á la sultana Leila-Radhyah.\"},{\"heading\":false,\"text\":\"Pero jamás conoció esta mi amor.\"},{\"heading\":false,\"text\":\"Leila-Radhyah amaba á un poderoso rey.\"},{\"heading\":false,\"text\":\"Yo la vengué de su enemiga, cuya sombra lívida acompaña á mi espíritu condenado, y la entregué al rey á quien amaba y la hice dichosa.\"},{\"heading\":false,\"text\":\"He cumplido la última voluntad de Daniel-el-Bokarí: su hija será sultana y el Palacio-de-Rubíes se levantará sobre cuatro montes.\"},{\"heading\":false,\"text\":\"Pero no he podido sobrevivir á mis celos.\"},{\"heading\":false,\"text\":\"No he podido ver á Leila-Radhyah entre los brazos de otro hombre.\"},{\"heading\":false,\"text\":\"He preferido la muerte, y un tósigo me ha abierto las puertas de la region de las sombras.\"},{\"heading\":false,\"text\":\"Para que se sepa cuánto he amado á Leila-Radhyah, y cuánto he sufrido por ella; para que se sepa hasta qué punto me he sacrificado por cumplir el último y ardiente deseo de mi único amigo, dejo escrito este pergamino que algun dia se encontrará sobre mi cadáver.==Yshac-el-Rumi.»\"},{\"heading\":false,\"text\":\"El rey se enjugó una lágrima y mandó poner en un sepulcro de mármol los restos de Yshac-el-Rumi con esta inscripcion.\"},{\"heading\":false,\"text\":\"«En el nombre de Dios piadoso y misericordioso: el sultan Nazar á los restos del mártir del amor y de la amistad. Que Dios, el Altísimo y Unico tenga compasion de su alma.»\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"El Mirador de la sultana permaneció cerrado y deshabitado mientras vivieron los que tenian memoria de la desastrosa muerte que habia sobrevenido en él á la terrible sultana Wadah.\"},{\"heading\":false,\"text\":\"Hay quien cree que durante las oscuras noches de tormenta se ven vagar dos sombras blancas y diáfanas que exhalan de sí una claridad ténue, mate y pálida, por las galerías del Mirador de la sultana, precedidas de un buho que vuela lentamente en derredor de las columnas.\"},{\"heading\":false,\"text\":\"¿Serán las sombras de la sultana Wadah y de Yshac-el-Rumi? ¿de la víctima y del verdugo?\"},{\"heading\":false,\"text\":\"¿Será aquel buho Abu-al-Abu?\"},{\"heading\":false,\"text\":\"¿Será, en fin, todo esto una ilusion causada por una tradicion romancesca?\"},{\"heading\":false,\"text\":\"Nosotros, sin embargo, conociendo la tradicion hemos entrado algunas noches en las galerías del Mirador de la sultana, cuando la tempestad rugia en el espacio: ninguna sombra, ningun buho hemos visto, mas que las blancas columnas que aparecian un momento á la fugitiva luz del relámpago.\"},{\"heading\":false,\"text\":\"¿Será acaso que la tradicion haya mentido, ó que al coronar la cruz, las cúpulas de la Alhambra, hayan desaparecido de ella fantasmas y encantamentos, quedando solo y abandonado el Mirador de la sultana?\"}]},{\"title\":\"El alma de la cisterna.\",\"blocks\":[{\"heading\":false,\"text\":\"Nos hemos propuesto relatar á nuestros lectores todas las maravillosas leyendas de las tradiciones árabes de la Alhambra.\"},{\"heading\":false,\"text\":\"Revolviendo un dia unos antiguos papeles encontrados en un desvan en una casa del Albaicin, hallamos uno que se decia traslado del arábigo al romance, de una historia árabe en que se esplicaba la causa por qué de tiempo en tiempo durante la noche, solia oirse un tristísimo suspiro saliendo por los brocales de los algibes de la Alhambra y muy semejante al gemido de un espíritu condenado.\"},{\"heading\":false,\"text\":\"La traduccion, aunque pesada y hecha bajo el mal gusto literario de la mayor parte de los prosistas españoles del siglo XVII, es tan bella en el fondo, tiene tal sabor oriental, que no hemos podido resistir al deseo de intercalarla entre las leyendas tradicionales é históricas referentes á la Alhambra.\"},{\"heading\":false,\"text\":\"Es un asunto fantástico; en él figuran hadas, conjuros y encantamentos, y aunque es un tanto embrollado y oscuro nosotros hemos procurado darle claridad.\"},{\"heading\":false,\"text\":\"Este cuento ha sido inspirado sin duda á algun poeta moro por la Alhambra, porque los árabes siempre buscan á las cosas que les impresionan por bellas ó por terribles un orígen maravilloso.\"},{\"heading\":false,\"text\":\"Antes de empezar á trascribir el cuento que llamaremos _El alma de la cisterna_, debemos describir esta cisterna que aun existe hoy con el nombre de los Algibes de la Alhambra.\"},{\"heading\":false,\"text\":\"Son estensísimos, como que ocupan todo el terreno comprendido entre la Alcazaba, y el lugar donde empezaban los muros de la fachada del alcázar, en un espacio como de cien pasos de anchura y trescientos poco mas ó menos de longitud.\"},{\"heading\":false,\"text\":\"Se componen de dos arcadas sostenidas en el centro por dos hileras de pilares, y se baja á ellos por dos escaleras situadas á sus dos estremos.\"},{\"heading\":false,\"text\":\"Junto á la escalera del estremo que mira al Albaicin están los dos anchos brocales por donde se saca el agua.\"},{\"heading\":false,\"text\":\"El techo es muy elevado y el muro interior por la continuacion del contacto del agua durante centenares de años, está cubierto de un fuerte revestimento de risco.\"},{\"heading\":false,\"text\":\"Conocidos los algibes, veamos la tradicion árabe fantástica que los supone habitados por un espíritu maldito.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"En los primeros tiempos de la Hegira, cuando Mahoma estendió el conocimiento del Dios Altísimo y Unico entre su pueblo, el cielo de Granada no era tan resplandeciente, ni su tierra tan fértil como ahora; su cielo era de color de plomo, cargado continuamente de oscuros nublados; en sus vastos eriales solo crecia el espino y el cardo silvestre, y en las altas y peladas crestas de sus sierras, jamás se vió blanco manto de nieve, ni corrió por sus vertientes raudal fecundador: era una tierra muerta, azotada por furiosos huracanes y el fuego de Dios brotaba por entre las anchas grietas de sus montañas volcánicas.\"},{\"heading\":false,\"text\":\"Pasaban sobre ella, forzando su vuelo, las viajeras golondrinas que huyendo del invierno se lanzaban de Gecira-Alandalus[42] á las costas de Africa, y nadie la habitaba, sino los moradores de Gebel-Elveira[43], que sufrian la esterilidad de la tierra y la tiranía de los godos, y habitábanla solo acaso porque el poderoso Allah ha dispuesto que no haya tierra sobre la que no fije el hombre la huella de su planta.\"},{\"heading\":false,\"text\":\"Tierra de muerte era para las razas dominadoras de Gecira-Alandalus, y la sangre de las batallas habia enrogecido muchas veces sus secos campos y sus peladas crestas.\"},{\"heading\":false,\"text\":\"Y nunca el caliente aire del estío habia oreado en ella las espigas de las mieses, ni las auras de la primavera habian volado entre la blanca y aromática flor de sus almendros.\"},{\"heading\":false,\"text\":\"Por aquellos tiempos existia ya la vieja torre, que se levanta hoy en el estremo occidental de la Colina Roja[44] y delante de ella una profunda cisterna construida por los romanos.\"},{\"heading\":false,\"text\":\"Es tradicion que salian de la cisterna profundos gemidos, que bramaba en su seno haciendo retemblar la tierra un viento impetuoso, y que todas las noches salian de las oscuras bocas de aquel infierno, sombras medrosas que vagaban sobre la colina, y danzaban y flotaban en los aires bajo el rayo sombrío de una luna sangrienta, dejando oir tristes cantos de amor desesperado, y largos y profundos gemidos.\"},{\"heading\":false,\"text\":\"Nunca tornó á su tienda ó á su hogar cazador imprudente ni errante peregrino, que durante las sombras se atreviese á poner su planta sobre la Colina Roja, ni nadie, durante las horas mas claras del dia, asomó la frente á cualquiera de los profundos brocales de la cisterna sin que fuese tragado por él.\"},{\"heading\":false,\"text\":\"Y desaparecieron ginetes y guerreros, y damas y doncellas, y poderosos señores y ruines esclavos, y llegó á inspirar tal horror la cisterna maldita, que ningun mortal, ave ó fiera, se aventuró á pasar junto á ella sino á la distancia de una legua á la redonda.\"},{\"heading\":false,\"text\":\"Cuentan antiguas historias, que por los tiempos en que los romanos dominaban á Gecira-Alandalus, esta tierra era tan rica de fuentes y de verdor como ahora, sombrios bosques cubrian su tierra, y las amantes palomas anidaban en las grietas de las rocas sobre los frescos manantiales.\"},{\"heading\":false,\"text\":\"Y la ciudad, tendida hoy allá á lo lejos en ruinas sobre la peñascosa Gebel-Elveira, era rica y floreciente y venian á ella gentes de todas las naciones y la enriquecian dejándola su oro á trueque de sus mercaderías.\"},{\"heading\":false,\"text\":\"Y entre los estranjeros vino un hombre mago, y corrió la tierra, y fundó la torre que aun hoy existe en la parte occidental de la Colina Roja, y la cisterna para proveerla de agua, valiéndose de la alquimia para pagar á los alarifes romanos que construyeron la cisterna y la torre; y en lo mas alto de la torre labró un aposento hecho con tal virtud, que á través de una abertura de su bóveda, se veian de dia claro las estrellas.\"},{\"heading\":false,\"text\":\"Desde entonces empezó á decaer el comercio de Elveira, y sus mugeres, antes puras y honestas, se entregaron á la licencia y al desenfreno, y los hombres faltaron á sus pactos y volvieron unos contra otros sus armas, y la miseria y el hambre les afligieron como un azote de Dios.\"},{\"heading\":false,\"text\":\"El mago causador con sus conjuros de tantos males era un réprobo vendido á Satanás y la tierra sobre la cual habia puesto sus plantas, habia sufrido un terrible castigo.\"},{\"heading\":false,\"text\":\"Y este hombre á quien Satanás habia dado su poder, quiso en su soberbia ser como Dios, y vivir con los tiempos y gozar de cuanto alumbra el sol en la tierra y en los aires, y pensó edificar un palacio mágico, cuya hermosura atrajese á todas las gentes, comparable solo al jardin de Hiram, y en el cual hubiese un pozo de aguas tan milagrosas como las del pozo Zemzem.\"},{\"heading\":false,\"text\":\"--Yo fundaré, dijo, un palacio maravilla de las maravillas, y le enriqueceré con todas las hermosas flores que Dios crió, y regaré estas flores con aguas olorosas; y arderán en el palacio dia y noche aceites aromáticos en lámparas de oro, y sobre sus pavimentos de pórfido pondré alfombras de resplandores, y envolveré sus muros y sus cúpulas en un blanco velo de suaves perfumes, y arrancaré para que le habiten, sus hadas al quinto cielo, y á él vendrán las mugeres mas hermosas del mundo, y sus mesas se cubrirán con los manjares mas esquisitos, y me alhagarán los mas hermosos sueños, y tal será el paraiso que yo haga para mí sobre esta tierra, que me mirarán con envidia los arcángeles del sétimo cielo.\"},{\"heading\":false,\"text\":\"Y el mago encendió sus hornillos, y sacó del jugo de yerbas estrañas filtros poderosos y escribió con ellos sobre pieles de serpiente signos cabalísticos formando terribles conjuros, y evocó á las hadas del quinto cielo, y cuando las vió ante sí, adoró su propio poder, sin alcanzar en su ciencia, ciego por su soberbia, que no hay poder que no venga de Dios, ni obra que no sea obra de su voluntad.\"},{\"heading\":false,\"text\":\"Cuando el mago vió en torno de sí á las hadas, repitió sus conjuros, y el palacio mágico se levantó sobre la Colina Roja, y las hadas fueron á esconderse en sus retretes, en sus jardines, en sus cúpulas y en sus estanques.\"},{\"heading\":false,\"text\":\"Entonces el mago fué á la cisterna que estaba á las puertas del palacio y la conjuró tambien.\"},{\"heading\":false,\"text\":\"Sus aguas se hicieron mágicas, é infiltraban en quien las bebia pensamientos impuros; les hacia olvidarse de su alma por los placeres de su cuerpo, y el mago llegó á ser un ídolo adorado por cuantos atraidos por la fama del palacio maravilloso, venian á la Colina Roja, y abrasados por la sed bebian el agua de la cisterna maldita.\"},{\"heading\":false,\"text\":\"Y así pasaron muchos años hasta la venida de Mohamet-ebn-Abd-Allah[45] á difundir la luz de la verdad y el conocimiento de la ley alcoránica entre el pueblo de Ismael.\"},{\"heading\":false,\"text\":\"Moraba en aquel tiempo en las llanuras del Yemen un Ismaelita, hombre de gran ciencia y virtud.\"},{\"heading\":false,\"text\":\"Bajo su tienda de pelo de camello, encontraba hospitalidad el peregrino, pan el pobre, remedio á sus dolencias el enfermo; la bendicion de Dios era sobre su raza, y sus innumerables rebaños, jamás eran acometidos por las panteras, ni robados por los errantes árabes del Hedjaz.\"},{\"heading\":false,\"text\":\"Nadab, que este era el nombre del justo, no dejaba ningun dia de bendecir á Dios por sus beneficios, y nunca dejó de prosternarse y de adorar su omnipotencia, cuando el sol aparecia tras la alborada, ó cuando se dejaba ver el lucero de la tarde precediendo á la noche.\"},{\"heading\":false,\"text\":\"Y era muger de Nadab, Sarah, y de ella habia tenido una hija única que habia consagrado á Dios, llamándola Yémina[46].\"},{\"heading\":false,\"text\":\"Y Yémina creció y con los años su hermosura llegó á ser maravillosa y á medida que su edad avanzaba era mas y mas lozana su juventud, mas tersa su frente, mas radiantes sus ojos, mas frescas sus megillas y mas húmedos y sonrosados sus lábios.\"},{\"heading\":false,\"text\":\"Nadab, que adoraba á su hija, y empezaba á olvidarse por ella de su adoracion á Dios, dejó de ser pastor nómada, vendió sus rebaños, abandonó las llanuras del Yemen y subió á las montañas del Hedjaz, sobre una de las cuales fabricó un bello palacio, adoptó la religion del Islam para poder ser rey de los pueblos comarcanos y lo fué, vertiendo su oro entre los xeques[47] de las kabilas[48] cercanas.\"},{\"heading\":false,\"text\":\"Hacia esto por Yémina; por ella se habia olvidado de Dios; por ella habia querido ser rey, y lo era para que Yémina fuese princesa.\"},{\"heading\":false,\"text\":\"Y corrió la fama de la hermosura de Yémina, y poderosos reyes de paises lejanos fueron al palacio de su padre á ofrecerla ricos presentes y á demandarla por esposa; pero ella no sentia el amor y rechazaba los presentes y se negaba á las pretensiones.\"},{\"heading\":false,\"text\":\"Y se tornaban los mensageros con los ricos regalos, y Yémina se mostraba cada dia mas jóven, mas hermosa y mas agena al amor.\"},{\"heading\":false,\"text\":\"Nadab llegó, al fin, por el amor de su hija á la idolatría, olvidándose de la ley de Dios, y lo que era peor, despreciándola; adoró á su hija, y levantó en su reino su estátua de oro, ante la cual hizo sacrificar víctimas segun el uso hebreo.\"},{\"heading\":false,\"text\":\"Y su impiedad trajo sobre él la justicia de Dios.\"},{\"heading\":false,\"text\":\"Ofendidos los reyes que habian sufrido la repulsa de Yémina, vinieron con poderosas huestes sobre el reino de aquel hombre, hecho rey por su soberbia y por sus tesoros, le acometieron, le vencieron y solo por permision de Allah, que le tenia reservado para otros fines, pudo salvarse con alguno de los suyos, pobre, disfrazado de pastor, llevando consigo á Yémina sobre un camello.\"},{\"heading\":false,\"text\":\"Y así, curando él enfermedades malignas y diciendo el horóscopo, viviendo de limosna y perseguido siempre do quiera que ponia la planta, atravesó el Africa y llegó al estrecho de Gebal-Tarik donde se vió detenido por el mar, sin medios para embarcarse y espuesto á los rigores de su destino.\"},{\"heading\":false,\"text\":\"En tanto el mago de la Colina Roja, que por sus conjuros, al evocar ante sí á la muger mas hermosa del mundo, habia visto la imágen de Yémina, supo su llegada al otro lado del estrecho y consultó las estrellas.\"},{\"heading\":false,\"text\":\"--Esa muger que es tan pura, tan jóven y tan hermosa, guarda tu destino, le contestaron las estrellas.\"},{\"heading\":false,\"text\":\"El mago las contestó con una impía carcajada.\"},{\"heading\":false,\"text\":\"--¿Acaso tengo yo destino? dijo: el porvenir es mio y será mi voluntad.\"},{\"heading\":false,\"text\":\"--Esa muger, repusieron las estrellas, causará tu destino sino te ama y traerá la esterilidad sobre esta tierra, porque así está escrito. Pero si logras sus amores serás inmortal y será tambien inmortal ella y eterno con vosotros el palacio mágico que has construido.\"},{\"heading\":false,\"text\":\"El mago avivó el fuego de sus hornillos, arrojó en ellos unos polvos mágicos, pronunció un conjuro, y en aquel momento Nadab y su hija fueron trasladados por un poder oculto, mientras dormian, á la Colina Roja.\"},{\"heading\":false,\"text\":\"Al despertar Nadab y su hija se miraron con asombro.\"},{\"heading\":false,\"text\":\"--¿Qué tierra es esta tan fértil y tan hermosa, dijo Nadab: y qué palacio de maravillas el que tenemos ante los ojos?\"},{\"heading\":false,\"text\":\"--Tierra de bendicion es ciertamente, padre mío, dijo Yémina.\"},{\"heading\":false,\"text\":\"--Siento sed y una sed devoradora, dijo Nadab.\"},{\"heading\":false,\"text\":\"--Yo tengo los labios áridos y secos, dijo Yémina.\"},{\"heading\":false,\"text\":\"En aquel momento vieron el agua límpida y trasparente que brotaba por encima de los brocales de la cisterna maldita.\"},{\"heading\":false,\"text\":\"Hija y padre se precipitaron á los brocales y apagaron su sed bebiendo largamente de aquel agua envenenada.\"},{\"heading\":false,\"text\":\"Nadab sintió como todos los que antes que él habian bebido, abrasarse su corazon en un fuego impuro, arder su sangre y dilatarse su ser.\"},{\"heading\":false,\"text\":\"Yémina que no se habia contaminado con el insensato orgullo de su padre, que habia conservado su piedad, su fé en el Dios Altísimo y Unico, y la inmaculada pureza de su alma, bebió tambien, pero protegida por la mano de Dios, aquella agua terrible que hacia olvidarse de sus mas sagrados deberes á los justos y temerosos de Allah, solo sirvió para acrecentar en ella la pureza y la virtud, y para realzar su hermosura harto resplandeciente como la de una hurí.\"},{\"heading\":false,\"text\":\"Cuando el mago la vió ante sus ojos, sintió abrasarse su alma en el fuego eterno, quiso tocar la túnica de Yémina, y sus manos se secaron, quiso hablarla y quedó mudo, quiso anegar sus ojos en su hermosura y cegó.\"},{\"heading\":false,\"text\":\"El mago habia levantado altares á su hermosura y moría esterminado por su mismo deseo.\"},{\"heading\":false,\"text\":\"La sentencia de las estrellas de que se habia burlado el mago, se habia cumplido.\"},{\"heading\":false,\"text\":\"Y á la presencia de Yémina, huyeron las impuras rameras que poblaban el palacio mágico, y desaparecieron los viles esclavos, y las hadas libertadas del encanto volvieron al quinto cielo.\"},{\"heading\":false,\"text\":\"Y el ángel Azrael, tendió sus negras alas sobre el palacio, agitó su espada de fuego, y el palacio se hundió reduciéndose á polvo.\"},{\"heading\":false,\"text\":\"Y las antes claras y engañosas aguas de la cisterna maldita se cambiaron en turbias y cenagosas.\"},{\"heading\":false,\"text\":\"Y el ángel dijo:\"},{\"heading\":false,\"text\":\"--¡Maldito mago, que tu espíritu condenado more desde ahora en la cisterna de las aguas maravillosas, y que solo puedas salir de su infierno durante las tinieblas de la noche!\"},{\"heading\":false,\"text\":\"El espíritu condenado del mago fué á morar en la cisterna, escondido en un oscuro ángulo, y el cielo antes tan diáfano se convirtió en un cielo de color de plomo, y la tierra antes tan fértil en un erial infecundo donde solo brotaban abrojos.\"},{\"heading\":false,\"text\":\"Nadab y Yémina quedaron solos, errantes en medio de una tierra desierta y maldecida por Dios.\"},{\"heading\":false,\"text\":\"Nadab llevando de la mano á su hija atravesó la pedregosa llanura, antes risueña vega, y en vano quiso salir de aquel pais donde sufria el castigo de su impiedad y de su soberbia: llegaba á los distantes valles, á las peladas montañas, pero montañas y valles presentaban para él y para su hija abismos insuperables que detenian su marcha, y les obligaban á tornar al punto de donde habian partido.\"},{\"heading\":false,\"text\":\"Desesperado Nadab y no encontrando otro albergue que la torre situada en la Colina Roja junto á la cisterna maldita, hizo en ella para Yémina una pequeña habitacion, y se dedicó á estudiar en el cielo y en la tierra las virtudes de las yerbas y de los reptiles ponzoñosos.\"},{\"heading\":false,\"text\":\"Y llegó á ser astrólogo estudiando en los libros cabalísticos del mago que habia encontrado en la torre, y conoció las virtudes de todas las yerbas y alcanzó á hacer filtros para matar, para enamorar y para enloquecer.\"},{\"heading\":false,\"text\":\"Si alguna vez un viajero errante ó un cazador estraviado penetraban en aquella tierra, cuya entrada y salida solo eran inaccesibles para Nadab y su hija; si este viajero ó este cazador entraban por acaso en la modesta vivienda de Yémina y veian su hermosura durante la ausencia de Nadab, este, sabedor de ello por sus conjuros, evocaba al desventurado, que enloquecia ó desaparecia tragado por la cisterna maldita.\"},{\"heading\":false,\"text\":\"Y crecia en encantos y en fuerza de juventud Yémina á pesar de que habian pasado muchos años desde el dia de su nacimiento.\"},{\"heading\":false,\"text\":\"Llegó el año 92 de la Hegira.\"},{\"heading\":false,\"text\":\"Reinaba en Damasco sobre las tierras de oriente el califa Walid-ebn-Abd-el-Melik, y era emir de Africa Muzay-ebn-Nosir, caudillo de gran fama, conquistador de Magreb[49] desde las regiones del poniente hasta los desiertos del mediodía, que pasó el estrecho de Al-Zacab ó de las Angosturas[50] realizando el ensueño de Ocba, gran guerrero que veinte y cinco años antes, no teniendo mas tierras que conquistar allende el mar, llegando á su orilla se metió en él con su caballo hasta las cinchas, y dijo:\"},{\"heading\":false,\"text\":\"--¡Oh! ¡Señor Allah! ¡si estas profundas aguas no me detuvieran, yo seguiría para llevar mas adelante el conocimiento de tu ley y santo nombre!\"},{\"heading\":false,\"text\":\"Muza pasó en cien galeotas el estrecho, y su caudillo Tarik taló la Bética, y siguió hollando á los duques godos, arrasando sus castillos e incendiando sus ciudades.\"},{\"heading\":false,\"text\":\"Y no iba solo, como capitan de la hueste, Tarik.\"},{\"heading\":false,\"text\":\"Acompañábale un godo traidor, un conde miserable, que por vengar á una hija deshonrada, vendia la libertad de su patria, abriendo á los árabes la puerta de Gecira-Alandalus.\"},{\"heading\":false,\"text\":\"Aquel conde traidor se llamaba don Julian.\"},{\"heading\":false,\"text\":\"Su hija Florinda.\"},{\"heading\":false,\"text\":\"El hombre que habia deshonrado á su hija, don Rodrigo.\"},{\"heading\":false,\"text\":\"Don Rodrigo era rey de los godos.\"},{\"heading\":false,\"text\":\"Su último rey.\"},{\"heading\":false,\"text\":\"Esperad, esperad: vamos á contaros una leyenda maravillosa.\"},{\"heading\":false,\"text\":\"Despues volveremos á la cisterna maldita.\"},{\"heading\":false,\"text\":\"El destino nos llevará á ella.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Era don Rodrigo de noble sangre goda.\"},{\"heading\":false,\"text\":\"Antes que don Rodrigo habia reinado Witiza.\"},{\"heading\":false,\"text\":\"Witiza el maldito.\"},{\"heading\":false,\"text\":\"El que hacia sus concubinas á las mugeres y á las hijas de sus vasallos.\"},{\"heading\":false,\"text\":\"El que martirizaba á los sacerdotes que le reprendian por sus vicios; el que desangraba con tributos á sus pueblos para labrar alcázares de oro para sus mancebas.\"},{\"heading\":false,\"text\":\"Pero los nobles se avergonzaron de servir á tal rey y se sublevaron contra él.\"},{\"heading\":false,\"text\":\"Con los nobles se sublevó todo el reino.\"},{\"heading\":false,\"text\":\"Witiza fué vencido y muerto y elegido rey don Rodrigo.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Pero una vez rey don Rodrigo, dió el torpe ejemplo de los mismos ó mayores vicios que Witiza.\"},{\"heading\":false,\"text\":\"Sórdido y avaro acreció los tributos y no respetó nada.\"},{\"heading\":false,\"text\":\"Se entregó á los placeres, pasó la vida en las orgías sin apercibirse del poder árabe que desde la cercana ribera del Africa amenazaba á su reino ansioso de su conquista, y lo olvidó todo entre los festines y las monterías, sin tener en cuenta que habia subido al trono por la destitucion de Witiza, cuyos vicios y desórdenes continuaba, aumentándolos.\"},{\"heading\":false,\"text\":\"Era ya don Rodrigo hombre anciano, y á pesar de su avanzada edad, habia tomado por esposa á Aylat (Egila) noble doncella, hermosa y prudente; admirábanla sus vasallos, amábanla los mancebos y dolíanse todos, aun los mas adictos al rey, de que aquella hermosa flor, entonces en todo el brillo de su pureza, partiese su alhamí y su divan, con aquel hombre ya caduco, gastado por los escesos de su juventud, en los cuales no habia cesado, y con un pié ya al borde del sepulcro.\"},{\"heading\":false,\"text\":\"Don Oppas, arzobispo de Sevilla, que fué grande amigo del rey Witiza en los tiempos de su prosperidad, era uno de aquellos que creian una gran desdicha para Aylat, su union con don Rodrigo, hombre que por su carácter y por sus ideas no podia menos de hacerla desdichada. Creyó por lo mismo que la noble señora sería sensible al alhago de otros amores, y ansioso de envenenar el corazon de don Rodrigo, rodeó de asechanzas á Aylat, la puso delante hermosos mancebos y tentaciones infernales, y procuró, en fin, por todos los medios herir en el corazon á don Rodrigo.\"},{\"heading\":false,\"text\":\"Pero Aylat, pura y virtuosa, comprendió que su deber era sacrificarse al lado de aquel árbol viejo y corroido sin herirle por el pié, y desesperado don Oppas de vencer la virtud de Aylat, tomó otro camino para herir al rey.\"},{\"heading\":false,\"text\":\"Moraba por entonces en Tanja (Tanger) una raza de árabes hebraizantes venida del Yemen, que desde muchos años atrás moraban en el Magreb; aquella raza sujeta á la dominacion goda en la Mauritania Tingitana, habia sufrido grandes persecuciones desde el tiempo del rey Egica, se habia visto injuriada, despojada de sus haciendas, vendida por esclava, insultada en sus hijas y en sus esposas, y á trocar sus creencias musulmanas por la religion de Cristo.\"},{\"heading\":false,\"text\":\"Era una raza cautiva, llena de ódio, ansiosa de venganza y pronta á tomarla de los godos á la primera ocasion.\"},{\"heading\":false,\"text\":\"Dominando á esta raza estaba de gobernador de los godos en Tanger un hombre nobilísimo.\"},{\"heading\":false,\"text\":\"Llamaban á este hombre el conde don Julian.\"},{\"heading\":false,\"text\":\"Era costumbre entonces, que los que iban á gobernar por el rey tierras distantes y mal seguras, dejasen en la córte sus hijos como en rehenes.\"},{\"heading\":false,\"text\":\"Segun esta costumbre, el conde don Julian tenia en la córte del rey don Rodrigo, en rehenes, pero como doncella de la reina Aylat, á la única hija del conde don Julian.\"},{\"heading\":false,\"text\":\"Esta doncella se llamaba Florinda.\"},{\"heading\":false,\"text\":\"Nacida y criada en Tanger, Florinda tenia en su trage y en sus costumbres, por mas que fuese de pura sangre goda, mucho de las costumbres de los árabes.\"},{\"heading\":false,\"text\":\"Florinda no entraba en Toledo mas que cuando sus obligaciones la llamaban al lado de la reina; lo demás del tiempo vivia en un estrecho valle poco distante de la ciudad situado entre dos montañas bajo un cielo triste y sombrío; por medio de este valle pasaba el Tajo, lamiendo los cimientos de una altísima torre sombría y solitaria; su gran puerta de hierro estaba cubierta de signos estraños y en sus muros renegridos por los vientos y por las lluvias, no se veian ni un ajimez, ni una ventana; en torno de ella crecia la maleza tupida y enmarañada, sin señales que demostrasen que pié humano habia llegado á la puerta de la torre en centenares de años.\"},{\"heading\":false,\"text\":\"Contábanse acerca de esta torre terribles consejas: creíanla construida por Satanás, durante una tormenta, á la aparicion de las razas del norte sobre las tierras del mediodía, y que guardaba, por un poderoso ensalmo, el destino del pueblo godo: habia quien aseguraba que el dia que se abriese aquella puerta, unas gentes guerreras venidas de la parte del mundo por donde aparece el sol, acometerian la Europa por el estrecho de Hércules y se harian dueños de España.\"},{\"heading\":false,\"text\":\"Fuese por horror ó abandono, ningun rey se habia atrevido á abrir aquella puerta, y la terrible torre era aun en el año 92 de la Hegira, un objeto de terror.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Frente á ella, bañando sus muros en las aguas del Tajo, se alzaba un recinto almenado, defendido por cuatro torrecillas: la construccion de aquel castillejo era estraña: sus almenas puntiagudas, sus puertas ojivas, sus ajimeces calados y sus agudas agujas la hacian parecer tanto goda como árabe.\"},{\"heading\":false,\"text\":\"Aquel castillejo que pertenecia al conde don Julian, habia sido en efecto construido por árabes hebraizantes, enviados por el conde á Toledo con el solo objeto de esta construccion.\"},{\"heading\":false,\"text\":\"En aquel castillejo vivia Florinda, acompañada de un viejo servidor de su padre, y servida por algunas doncellas y esclavos.\"},{\"heading\":false,\"text\":\"A pesar de ser doncella noble de su esposa Aylat, el rey don Rodrigo no conocia á Florinda.\"},{\"heading\":false,\"text\":\"Pero conocíala por su desgracia don Oppas, que la habia elegido para ser el instrumento de perdicion del rey.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"--¿Por qué está triste el noble señor, gloria de los godos? decia una tarde de verano al trasponer el sol, el obispo don Oppas á don Rodrigo, mientras paseaba con él por las frondosas huertas de Toledo.\"},{\"heading\":false,\"text\":\"--Mi espíritu está triste, dijo el rey; en vano busco el agua que ha de calmar la sed de mi alma; en los festines, en las mugeres mas hermosas, solo encuentro un tósigo abrasador que aumenta mi sed y devora mis entrañas.\"},{\"heading\":false,\"text\":\"A tal punto habia llegado la corrupcion de aquellos tiempos, que un rey que debia representar la justicia de Dios sobre la tierra, y un hombre que debia ser todo virtud y santidad, hablaban sin avergonzarse de tales asuntos.\"},{\"heading\":false,\"text\":\"--Tal vez encontraremos, señor, algo que consuele tu tristeza, dijo don Oppas: algun raudal fresco y puro que temple tu sed sin abrasar tus entrañas.\"},{\"heading\":false,\"text\":\"--¿Y dónde está ese manantial milagroso? dijo con ánsia el rey.\"},{\"heading\":false,\"text\":\"--¿Conoces á las doncellas nobles de tu esposa? dijo don Oppas.\"},{\"heading\":false,\"text\":\"--Conozco á la hermana del conde Arnoldo, á la hija del duque de Cantábria, á la sobrina del marqués Euríco...\"},{\"heading\":false,\"text\":\"--¿Pero no conoces á la hija del conde don Julian?\"},{\"heading\":false,\"text\":\"--No; respondió con ánsia el rey, y dicen que es muy hermosa.\"},{\"heading\":false,\"text\":\"--¡Ah! es un sol de Africa: sus miradas queman, su sonrisa embriaga, cuando canta adormece el alma, cuando danza arrebata los sentidos: no es rubia, ni tiene los ojos azules como nuestras mugeres hijas del norte: sus cabellos y sus ojos son negros como la desesperacion de un enamorado, y su frente blanca y cándida como el primer sueño de amor de una virgen. ¿Pero para qué me esfuerzo? tú mismo puedes verla dentro de un momento.\"},{\"heading\":false,\"text\":\"--¡Yo!\"},{\"heading\":false,\"text\":\"--Sí, tú, poderoso señor, y verla como no la ha visto hombre alguno.\"},{\"heading\":false,\"text\":\"--¡Cómo!\"},{\"heading\":false,\"text\":\"--Allá abajo entre aquellas espesuras se baña con sus doncellas en un remanso del Tajo.\"},{\"heading\":false,\"text\":\"--¿Y cómo sabes tú eso? ¿la has visto tú? dijo con acento celoso don Rodrigo.\"},{\"heading\":false,\"text\":\"--No, no me he atrevido ni aun á poner mis ojos en la que ha de ser la alegría y la ventura de mi señor, contestó servilmente don Oppas: pero he comprado á una de sus doncellas y sé el lugar donde se baña: para que puedas mirarla sin que turbes el sol de su hermosura te hé inclinado á que vengas á estos lugares, señor.\"},{\"heading\":false,\"text\":\"--¿Y dónde? ¿dónde dices que se baña esa hermosura?\"},{\"heading\":false,\"text\":\"--Toma por aquel sendero entre los árboles, señor, y pronto darás con el lugar oculto que ha elegido para sus baños Florinda.\"},{\"heading\":false,\"text\":\"El rey tomó á gran paso por el sendero que don Oppas le habia señalado, y este quedó sonriendo de una manera horrible porque veia el principio de la realizacion de sus proyectos, que tenian por objeto vengar á Witiza y poner sobre el trono de los godos á sus hijos.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"A poco que anduvo don Rodrigo por el sendero, llegaron á sus oidos risas y cánticos femeniles.\"},{\"heading\":false,\"text\":\"LETRE dibº y litª Lit de J.J. MARTINEZ Madrid]\"},{\"heading\":false,\"text\":\"Guiado por ellos adelantó y llegó al fin á un lugar sombrío donde sin ser visto vió un espectáculo encantador.\"},{\"heading\":false,\"text\":\"En un remanso tranquilo y trasparente del rio, vió á una muger, mejor dicho, á una niña, en el momento de salir del baño.\"},{\"heading\":false,\"text\":\"Sus doncellas la esperaban con las ropas entendidas para cubrirla, pero no la cubrieron tan pronto que don Rodrigo no sorprendiese un tesoro de hermosura desnudo.\"},{\"heading\":false,\"text\":\"Por un momento el rey permaneció inmóvil y fascinado. Luego cuando Florinda y sus doncellas se perdieron entre los árboles, se volvió demudado, enloquecido, en busca de don Oppas.\"},{\"heading\":false,\"text\":\"--¿La has visto, señor? le preguntó sonriendo de una manera infame don Oppas.\"},{\"heading\":false,\"text\":\"--¡Oh! pluguiera á Dios que no la hubiese visto, porque he cegado, dijo el rey.\"},{\"heading\":false,\"text\":\"--Florinda te matará, murmuró de una manera ininteligible don Oppas y luego añadió en voz alta: esta noche puedes ser huesped de esa hermosura.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Era la hora del crepúsculo de aquella misma tarde.\"},{\"heading\":false,\"text\":\"El castillo del conde don Julian, la morada de su hija Florinda, aparecia iluminada por una leve luz rojiza á las orillas del Tajo.\"},{\"heading\":false,\"text\":\"En una habitacion reducida del castillo habia en aquellos momentos un hombre y una muger.\"},{\"heading\":false,\"text\":\"La muger era de gran hermosura y muy jóven; sus cabellos negrísimos estaban entrelazados á una faja de oro que ceñia su cabeza; la blancura de su frente se confundia con la de su velo, y sus cejas dilatadas, negrísimas y suavemente arqueadas coronaban sus ojos negros, grandes, brillantes, á que daban sombra y fuerza sus larguísimas pestañas; vestia una túnica larga hasta cubrir sus pies; baja lo bastante para dejar descubiertos en su parte superior un cuello deslumbrante de blancura, sus redondos hombros y el nacimiento de su seno; sus brazos, sus admirables brazos desnudos, estaban adornados con ajorcas de oro y perlas; un cíngulo, de oro tambien, rodeaba á su reducida cintura su túnica de lana blanca, y entre este cíngulo relucia el pomo de un puñal.\"},{\"heading\":false,\"text\":\"Esta jóven, que apenas contaria quince años, era Florinda, la hija única del conde don Julian, la hermosura á quien habia sorprendido en el baño el rey don Rodrigo.\"},{\"heading\":false,\"text\":\"El hombre dormia en un ángulo distante, ó fingia dormir, tendido sobre unos almohadones; era un nubio, negro como el ébano, y estaba envuelto en un ropon rojo; aquel hombre era sin duda un esclavo, á juzgar por la argolla dorada que tenia al cuello.\"},{\"heading\":false,\"text\":\"Este esclavo se llamaba Kaib.\"},{\"heading\":false,\"text\":\"Florinda hilaba sentada junto á un mirador desde donde se veia el rio, de tiempo en tiempo arrojaba una mirada distraida al lugar donde el esclavo estaba reclinado, y al sentir la mirada de Florinda, de los entreabiertos párpados del nubio salia un relámpago de amor desesperado, que ó no notaba Florinda ó fingia no notar.\"},{\"heading\":false,\"text\":\"Empezaba á oscurecer; Florinda dejó su rueca, se levantó del sillon de roble donde estaba sentada, fué á apoyarse en la balaustrada del mirador y fijó su mirada distraida en la corriente del Tajo.\"},{\"heading\":false,\"text\":\"La luna llena empezaba á salir entre las quebraduras.\"},{\"heading\":false,\"text\":\"El nubio se levantó lentamente y fué á apoyarse en la balaustrada donde se apoyaba Florinda.\"},{\"heading\":false,\"text\":\"--Hija de don Julian, la dijo señalándola el poniente teñido aun con las últimas ráfagas del crepúsculo; el cielo está ensangrentado, la muerte y el estrago adelantan por el oriente y el buitre olfatea ya los cadáveres. ¡Vírgen de los godos, nacida bajo el sol del Africa! ¡menguado fué el dia en que abriste los ojos á la luz! ¡hora de maldicion aquella en que mis ojos te vieron!\"},{\"heading\":false,\"text\":\"Florinda callaba aterrada por lo solemne de las palabras del esclavo, porque no era aquella la primera vez que la hablaba de tal modo, y le tenia por sábio y aun por hechicero:\"},{\"heading\":false,\"text\":\"--¡Oh! ¡cuánto arnés roto, y cuánto caballero muerto, hija de don Julian! continuó Kaib: el oriente vendrá sobre el occidente y las gentes del norte empaparán con su sangre las campiñas del mediodia. ¡Oh! ¡y cuánto arnés roto! ¡cuánto caballero muerto!\"},{\"heading\":false,\"text\":\"Florinda siguió callando.\"},{\"heading\":false,\"text\":\"--¡Huye, hija de don Julian! ¡huye! continuó Kaib despues de un instante de silencio: ¡huye! ¡yo te salvaré! ¡tú serás la reina allá en mi patria distante, y yo seré el último de tus esclavos! ¡huye, huye conmigo, hija de don Julian, porque el cielo mana sangre, y el buitre olfatea ya los cadáveres!\"},{\"heading\":false,\"text\":\"--¿Qué me quieres anunciar Kaib? dijo Florinda volviéndose gravemente al esclavo.\"},{\"heading\":false,\"text\":\"--El imperio de los godos se hunde, y tú serás la causa, contestó Kaib.\"},{\"heading\":false,\"text\":\"--¡La causa yo!\"},{\"heading\":false,\"text\":\"--Sí, un hombre funesto ha visto tu hermosura: ese hombre te hará su manceba.\"},{\"heading\":false,\"text\":\"--¡Yo! ¡manceba yo de nadie, vil esclavo! esclamó con indignacion Florinda: ¡y así te atreves á insultarme porque te trato con misericordia!\"},{\"heading\":false,\"text\":\"--¡Mata al esclavo, señora! dijo Kaib fijando de una manera poderosa sus resplandecientes ojos en Florinda: ¡mata al esclavo, pero escucha antes al sabio!\"},{\"heading\":false,\"text\":\"Florinda tembló.\"},{\"heading\":false,\"text\":\"--¿Me amenaza algun peligro? dijo.\"},{\"heading\":false,\"text\":\"--Tú serás profanada por un hombre funesto, y tu profanacion producirá torrentes de sangre vengadora.\"},{\"heading\":false,\"text\":\"--¡Tú me amas! dijo con altivez Florinda.\"},{\"heading\":false,\"text\":\"--Mi corazon y mi alma son tuyos, dijo Kaib: mis amores no tienen esperanza: sé que amas á Belay[51], al noble Belay, y que él te ama: sé que sino te salvas caeré contigo, y que tu Belay te perderá.\"},{\"heading\":false,\"text\":\"--¿Pero se salvará Belay?\"},{\"heading\":false,\"text\":\"--El será el único príncipe godo que se salve del estrago: él será rey por la virtud de su espada: él será el primero de los salvadores del pueblo español.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡si Belay se salva me salvaré con él!\"},{\"heading\":false,\"text\":\"--¡Dudas de mi ciencia y la desprecias! dijo profundamente Kaib: pues bien, cuando desesperada y loca me llames en la hora de la desgracia, me tendrás á tu lado: esa hora se acerca: ¡hasta entonces, hija de don Julian!\"},{\"heading\":false,\"text\":\"Y el esclavo se apartó de la balaustrada y se perdió en el interior de la habitacion.\"},{\"heading\":false,\"text\":\"--¡Oh! murmuró Florinda: ¿qué puedo yo temer amándome Belay, mi valiente Belay?\"},{\"heading\":false,\"text\":\"Y permaneció en el mirador, inundada por la luz de la luna, y resplandeciente de hermosura.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Entretanto, viniendo de Toledo avanzaba una cabalgata hácia el castillo de don Julian.\"},{\"heading\":false,\"text\":\"Al frente de aquella cabalgata venia el arzobispo don Oppas.\"},{\"heading\":false,\"text\":\"Florinda, que permanecia en el mirador, vió acercarse á aquellas gentes con un espanto instintivo.\"},{\"heading\":false,\"text\":\"Muy pronto resonó la voz de una vocina bajo los muros del castillo.\"},{\"heading\":false,\"text\":\"Entonces, Lotario, el antiguo servidor del conde don Julian á quien este habia confiado la guarda de su hija, se asomó á los adarves.\"},{\"heading\":false,\"text\":\"--¿Qué quereis? dijo á los que llamaban.\"},{\"heading\":false,\"text\":\"--Somos cazadores que nos hemos estraviado, contestó don Oppas, y esperamos de tí hospitalidad por esta noche.\"},{\"heading\":false,\"text\":\"--La paz del Señor sea con vosotros, contestó Lotario en un acento que por lo bravío desmentia lo amistoso de sus palabras: voy á ordenar que se os abran las puertas.\"},{\"heading\":false,\"text\":\"Poco despues Kaib dejaba caer el puente sobre el foso, y entraban en el castillo don Oppas y dos gallardos mancebos, con sus monteros: estos últimos entraron en los aposentos bajos del castillo, y don Oppas y los dos jóvenes entraron en los aposentos de Florinda, acompañados de Lotario y seguidos del receloso Kaib: poco despues el esclavo cubria de viandas una ancha mesa, alumbrada por lámparas de bronce.\"},{\"heading\":false,\"text\":\"Lotario como huesped y Kaib como esclavo, empezaron á servir á don Oppas y á los dos jóvenes que se habian sentado en sillones de roble.\"},{\"heading\":false,\"text\":\"Era don Oppas un hombre como hasta de cincuenta años: vestia una túnica y un manto pardos, y bajo ellos se veia el reluciente hierro de un arnés, cuyo capacete cubria sus cabellos ya grises.\"},{\"heading\":false,\"text\":\"La espresion del semblante de este hombre era noble y benévola; dábale autoridad su barba larguísima y entrecana, y dificil era comprender en sus ojos una espresion de astucia y de doblez, que pasaba por ellos de tiempo en tiempo como un relámpago: don Oppas observaba con astucia desde que entró en el castillo, mientras sus compañeros observaban tambien, aunque con reserva, cuanto pasaba en torno suyo.\"},{\"heading\":false,\"text\":\"Lotario observaba tambien con la misma reserva, á los mancebos: vestian estos clámides de escarlata, sandalias de riquísimo cuero, capacetes, armas y acicates de oro: los dos eran tan semejantes, que vistos cada uno de por sí se les hubiera tomado al uno por el otro: como en sus trages y sus armas, habia mucho de régio en los semblantes de los mancebos: sus miradas eran fijas, severas, llenas de imperio y una nube fatídica parecia cubrir sus frentes magestuosas y rodearlas de una aureola.\"},{\"heading\":false,\"text\":\"Todos, los de adentro y los de afuera guardaban silencio: todos observaban y eran observados.\"},{\"heading\":false,\"text\":\"--Muy rico eres, dijo al fin don Oppas como por decir algo á Lotario, levantando una copa de oro llena de vino: oro es este mas acendrado que el del tesoro de don Rodrigo, y tu vino es vino de las Galias.\"},{\"heading\":false,\"text\":\"--¡Don Rodrigo! dijo Lotario: es verdad: el oro de la copa en que bebes, es mas acendrado que el de la copa del rey, como es mas acendrada la lealtad del conde don Julian mi señor, cuya es la copa que tienes en la mano, que la de los magnates que rodean al rey en la córte: bebed hijos de Witiza: bebed el vino del conde don Julian y comed su pan; bebed y reposad y preparaos, porque se acerca el dia en que cada cual pruebe su lealtad.\"},{\"heading\":false,\"text\":\"Los dos jóvenes se levantaron, tomaron dos copas, las chocaron y las apuraron de una sola vez.\"},{\"heading\":false,\"text\":\"Don Oppas bebió lentamente la mitad del contenido de la suya y ofreció el resto á Lotario.\"},{\"heading\":false,\"text\":\"Este rehusó.\"},{\"heading\":false,\"text\":\"--He jurado al Señor, dijo, no beber mas que agua hasta que llegue el dia del esterminio.\"},{\"heading\":false,\"text\":\"--¿Quién eres tú, le dijo el mayor de los hijos de Witiza, que conoces nuestro nombre, y nos auguras el porvenir?\"},{\"heading\":false,\"text\":\"Lotario miró al esclavo nubio, como si esperase de él la inspiracion de sus palabras; el esclavo le miraba de una manera fija y singular.\"},{\"heading\":false,\"text\":\"--Escuchad, dijo: yo aunque me llamo Lotario, no soy godo; aunque me confieso cristiano, mis padres no lo fueron; yo he nacido en una tierra muy distante de España, bajo un cielo ardiente, sobre un suelo siempre bañado por los rayos de un sol rojo y brillante: me he criado allí, he amado allí; mi único deseo ha sido reposar en aquella tierra bendita, en la fosa de mis padres y de mis hermanos: los sectarios de Mahoma me han arrojado de ella con mi raza hasta las regiones de occidente, y nos hemos visto pobres, desnudos, sujetos á la religion y á las costumbres de los godos en la Mauritania Tingitana; allí he conocido y he servido al conde don Julian, y de allí he venido para guardar y proteger á Florinda, la hija de mi señor.\"},{\"heading\":false,\"text\":\"--¡Florinda! dijo como si escuchase un nombre estraño don Oppas: no la conozco.\"},{\"heading\":false,\"text\":\"--Pluguiera á Dios que no la hubieseis conocido, dijo con profundo acento Kaib; ella será el pretesto de una guerra terrible; un pueblo vendrá sobre otro pueblo y ella será la llave que abra al conquistador las puertas del Tanja. La cabeza del tirano caerá, pero sobre ella se levantarán otros tiranos, y el nombre de la Kaba zumbará en la posteridad como un eco de traicion. La hija de don Julian ha nacido en mal hora á la luz, porque su nombre será maldito y maldita la raza de los suyos y maldita la generacion de ellos.\"},{\"heading\":false,\"text\":\"Era terrible y solemne el acento de Kaib; sus ojos radiantes parecian tener fija su mirada en el porvenir, su negro rostro parecia dar una fuerza sobrenatural á su discurso.\"},{\"heading\":false,\"text\":\"--¿Y acaso no pueden evitarse tantas desdichas? dijo don Oppas dirigiendo la palabra á Lotario, como en desprecio de Kaib.\"},{\"heading\":false,\"text\":\"--Lo que está escrito en los astros se cumplirá, dijo Kaib, aunque las palabras no se habian dirigido á él: has venido á ver á la hija de don Julian: hé aquí que el destino te la trae: mira.\"},{\"heading\":false,\"text\":\"Florinda habia aparecido en la puerta de la cámara.\"},{\"heading\":false,\"text\":\"--Pronto el conde don Julian tendrá una injuria que vengar: pronto la puerta de aquella torre se abrirá ante un rey, añadió dirigiéndose al mirador y señalando la torre solitaria que se veia al otro lado del rio iluminada fatídicamente por la luz de la luna: al abrirse aquella funesta puerta respetada por los hombres y por los siglos, las tribus del oriente caerán sobre el occidente; afilad vuestras espadas, hijos de Witiza y vengad á vuestro padre asesinado por don Rodrigo, pero olvidad su trono, porque está escrito que la raza de los godos sea esterminada: y huid: habeis venido creyendo encontrar hombres que se vendieran á la traicion: cuando tengamos que vengar una injuria la vengaremos ó la vengarán los que nos sobrevivan, pero no será una venganza vendida la que caiga sobre el causador de la injuria.\"},{\"heading\":false,\"text\":\"Kaib mas que un esclavo parecia el señor del castillo.\"},{\"heading\":false,\"text\":\"Florinda permanecia inmóvil en la puerta.\"},{\"heading\":false,\"text\":\"Don Oppas miraba con cólera al esclavo.\"},{\"heading\":false,\"text\":\"Los hijos de Witiza con asombro.\"},{\"heading\":false,\"text\":\"--Hemos venido, dijo don Oppas, á pediros hospitalidad, no insultos: la voz del esclavo ha resonado insolente en nuestros oidos: sea en buena hora: habeis llamado la tempestad sobre vuestras cabezas: vuestra será la culpa si las hiere el rayo.\"},{\"heading\":false,\"text\":\"Kaib no contestó á don Oppas, arrojó una triste mirada sobre Florinda y murmuró con voz ronca y conmovida:\"},{\"heading\":false,\"text\":\"--¡Hija de don Julian, en mal hora nacida á la luz, lo que está escrito se cumplirá!\"},{\"heading\":false,\"text\":\"Despues añadió:\"},{\"heading\":false,\"text\":\"--Nada teneis ya que hacer aquí: el buitre ha visto á la paloma y afila sus garras: ¡idos!\"},{\"heading\":false,\"text\":\"--¡Idos! repitió Lotario.\"},{\"heading\":false,\"text\":\"--¡A Dios! dijo don Oppas levantándose: nos has dado hospitalidad é injurias; la hospitalidad y las injurias serán pagadas. A Dios.\"},{\"heading\":false,\"text\":\"Y salió con los hijos de Witiza.\"},{\"heading\":false,\"text\":\"Florinda permanecia inmóvil en la cámara.\"},{\"heading\":false,\"text\":\"--Hija del conde don Julian: cuando llegue la hora de la desgracia me tendrás á tu lado, dijo Kaib.\"},{\"heading\":false,\"text\":\"Y salió lentamente de la cámara.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Don Oppas y los hijos de Witiza regresaron á Toledo.\"},{\"heading\":false,\"text\":\"Los dos mancebos se perdieron por las altas y estrechas callejuelas de la ciudad, y el obispo, seguido de los monteros, llegó al palacio, descabalgó delante de la puerta de los Leones, y á través de la guarda, que se inclinó respetuosamente á su paso, se encaminó á la cámara del rey don Rodrigo.\"},{\"heading\":false,\"text\":\"Ante su puerta, jóvenes godos con mantos de púrpura y oro y hermosas mugeres con los cuellos y los brazos desnudos, departian de amores y cacerías, de galantes aventuras, de ruidosos banquetes; los soldados se apoyaban en sus lanzas, inmóviles como estátuas de hierro, á lo largo de los muros de la gigantesca antecámara, y los esclavos se veian tras ellos entregados á un silencio estúpido.\"},{\"heading\":false,\"text\":\"Poco tiempo antes de la llegada de don Oppas al palacio, se abrió la puerta frontera á la de la cámara real, y apareció en ella un viejo, alto, flaco, pálido, con escasos cabellos grises y barba blanca, cubierto por una hopalanda parda.\"},{\"heading\":false,\"text\":\"Este hombre adelantó hasta el centro de la antecámara, y sin dirigirse á persona alguna, dijo con acento grave y sonoro:\"},{\"heading\":false,\"text\":\"--Yo soy Gutz, el hebreo.\"},{\"heading\":false,\"text\":\"Agitóse el círculo de damas y caballeros, y de entre ellos adelantó hasta el recien llegado un noble cubierto con un arnés de guerra, caudillo al parecer, de la guarda del rey.\"},{\"heading\":false,\"text\":\"--¿Eres tú el joyero de la calle del Sol? preguntó á Gutz.\"},{\"heading\":false,\"text\":\"--Yo soy, contestó el viejo.\"},{\"heading\":false,\"text\":\"--¿El hechicero?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Te espera el rey?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"Tras estas breves palabras el noble adelantó hasta la puerta de la cámara real, levantó su tapiz y dijo:\"},{\"heading\":false,\"text\":\"--¡Señor! ¡Gutz el hebreo, joyero y hechicero!\"},{\"heading\":false,\"text\":\"Una voz gutural y débil, aunque imperiosa, contestó desde adentro.\"},{\"heading\":false,\"text\":\"--Mi leal Singiberto, deja entrar á ese perro infiel.\"},{\"heading\":false,\"text\":\"Singiberto hizo una seña á Gutz, y este, pasando con desden é insolencia entre los cortesanos, se perdió tras el tapiz que cubria la puerta de la cámara real.\"},{\"heading\":false,\"text\":\"Era tan frecuente entonces la entrada de embaucadores y magos en el palacio, que nadie tomó en aprecio la llegada de Gutz, y jóvenes y damas siguieron las pláticas interrumpidas.\"},{\"heading\":false,\"text\":\"A punto dos escuderos, uno de los cuales llevaba una adarga blasonada, y otro una espada, penetraron en la antecámara, precedidos por un faraute, que con no menos insolencia que Gutz, se detuvo en el centro, y dijo en alta voz:\"},{\"heading\":false,\"text\":\"--El noble y poderoso señor don Oppas, arzobispo de Sevilla.\"},{\"heading\":false,\"text\":\"Singiberto anunció de nuevo, é hizo seña al faraute de que don Oppas podia entrar en la cámara real.\"},{\"heading\":false,\"text\":\"Una antorcha de oro, alimentada con aceite aromático, alumbraba la cámara de don Rodrigo. Sus paredes estaban revestidas de riquísimos tapices, en los que se veian pintadas mugeres hermosas desnudas en el baño, mancebos reclinados en la sombra de verdes enramadas entre los brazos de náyades, trofeos de amor é impudentes pinturas de deleite.\"},{\"heading\":false,\"text\":\"Sentado sobre una silla de marfil de preciosa labor, estaba don Rodrigo envuelto en una clámide de púrpura, y ceñidos sus blanquísimos cabellos por una corona de hierro.\"},{\"heading\":false,\"text\":\"Plegado sobre sus rodillas, envuelto en su ancha clámide, solo se podia juzgar de su semblante pálido y de espresion noble, aunque degradada é indolente: sus ojos azules conservaban aun el brillo de la juventud y una de sus manos blanca y tersa como la de una dama, se ocupaba en levantar hasta su nariz recta y afilada un pomo de oro lleno de esencias aromáticas que aspiraba con deleite, y de las cuales dejaba caer de tiempo en tiempo algunas gotas sobre su barba plateada y profusa, rizada con mas esmero que la cabellera de una muger.\"},{\"heading\":false,\"text\":\"A un lado, junto á la silla en que reposaba don Rodrigo, habia una mesa de la cual partian reflejos deslumbrantes arrancados por la luz de la antorcha. Segun las crónicas de aquel tiempo, la tabla de esta mesa era una sola esmeralda encontrada por Fatimah la santa[52] junto al pozo Zemzem, y sus piés, fabricados por los genios, eran de oro macizo, de una labor sorprendente, y cuajados de perlas y diamantes.\"},{\"heading\":false,\"text\":\"Esta joya de inestimable valor era la famosa mesa de Salomon: habia pasado en herencia á la tribu de Heber y fué robada á sus descendientes por el rey Egica, cuando sujetó á feudo y tributo á los árabes hebraizantes, desterrados del Yemen y refugiados en el Magreb. Esta misma mesa fué la que mas tarde, despues de la conquista de Gezira-Alandalus por los árabes, produjo fatales desavenencias entre el emir Muza-ebn-Noser, y su walí, el valiente sin par, Tarik-ebn-Ziad.\"},{\"heading\":false,\"text\":\"Sobre esta mesa estaba como un adorno la espada de don Rodrigo, y sobre su empuñadura se posaba un azor[53] sujeto á la mesa por una sutil cadena de oro.\"},{\"heading\":false,\"text\":\"Todo revelaba allí el hombre sensual, degradado y envilecido.\"},{\"heading\":false,\"text\":\"Aquella arma de caballero, arrojada como al acaso sobre aquella mesa, era un contraste estraño, un mudo reproche á tanta degradacion, á tanto abandono.\"},{\"heading\":false,\"text\":\"Cuando resonaron sobre la cámara real, al andar de don Oppas, las piezas de su arnés, el rey que, á pesar de la presencia de Gutz, que estaba prosternado á sus pies, no habia salido de su inmovilidad, se estremeció al áspero rechinar del acero, y levantó la cabeza arrojando en torno suyo una mirada inquieta que tornó á ser indolente cuando reconoció al obispo.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿eres tú, don Oppas? dijo: en verdad que te esperaba. ¿Qué perro es ese que se tiende á mis pies? añadió reparando en Gutz.\"},{\"heading\":false,\"text\":\"--Lo ignoro, señor, contestó don Oppas.\"},{\"heading\":false,\"text\":\"--Es Gutz tu esclavo, poderoso rey, contestó el hebreo sin levantar la frente de la alfombra.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿eres tú? dijo don Rodrigo: levántate esclavo, te he mandado llamar no me acuerdo para qué. ¿Eres hechicero?\"},{\"heading\":false,\"text\":\"--Tal dicen, señor; pero solo Dios sabe lo oculto.\"},{\"heading\":false,\"text\":\"--¿Y crees tú, don Oppas, dijo don Rodrigo dirigiéndose al arzobispo, en el poder de la hechicería?\"},{\"heading\":false,\"text\":\"--Tanto creo, señor, contestó don Oppas, que, si saber mi destino quisiera, me dirigiria sin vacilar á uno de esos sabios que, alejados del mundo, han estudiado el lenguage de las estrellas.\"},{\"heading\":false,\"text\":\"--Pues hé aquí que á mi vez he tenido ese deseo, repuso el rey, y he mandado buscar á uno de esos buhos que pasan la noche en vela mirando al cielo.\"},{\"heading\":false,\"text\":\"Don Oppas cruzó una mirada de inteligencia con Gutz.\"},{\"heading\":false,\"text\":\"--Dime tú, sabio, dijo don Rodrigo con indolencia: ¿dónde está el límite de mi vida? yo la siento fuerte y vigorosa dentro de mi cuerpo envejecido, y mi alma se revuelve ardiente como en los dias de mi lejana juventud: pero mis noches sombrías, mis sueños apenadores, mis deseos insensatos: yo veo en lo recóndito de mi espíritu una muger hija de mi fantasía á cuya hermosura no alcanzan las mas hermosas de mis concubinas. Aun mas, yo he visto hoy, esta tarde á esa muger, viva, desnuda delante de mis ojos, saliendo como Venus de la espuma de las aguas. Yo la amo; mi corazon se quema por ella. ¿Qué puedo yo esperar de esa muger?\"},{\"heading\":false,\"text\":\"Gutz inclinó profundamente su cabeza, dejó caer los brazos á lo largo de su cuerpo y sus ojos se cerraron como dominados por un sueño profundo: levantóse su pecho dilatado por una respiracion poderosa, contrajéronse los músculos de su semblante, y se borraron las profundas arrugas de su frente.\"},{\"heading\":false,\"text\":\"Don Rodrigo, replegado aun sobre su silla de marfil, miraba al hebreo con la ávida atencion de un niño; estaba hastiado y la espectativa de un acontecimiento cualquiera le divertia.\"},{\"heading\":false,\"text\":\"--Pronto, esclavo, dijo con impaciencia: dime lo que puedo esperar ó temer de esa muger.\"},{\"heading\":false,\"text\":\"Gutz abrió los ojos, levantó con altivez la cabeza, miró frente á frente á don Rodrigo y dijo con voz ronca y acentuada:\"},{\"heading\":false,\"text\":\"--Tu destino ¡oh rey! es incierto: una nube oscura colocada delante de mis ojos, no me deja ver claramente tu horóscopo, pero esa nube tiene ráfagas rojas; la sangre y el fuego habitan en ella.\"},{\"heading\":false,\"text\":\"Don Rodrigo se irguió: las palabras del hebreo le aterraban vagamente: su mirada antes glacial se habia animado, y sus labios se agitaban en una imperceptible convulsion.\"},{\"heading\":false,\"text\":\"--Lo que me has dicho es muy oscuro, esclamó el rey, con acento convulso é irritado; yo quiero que tus ojos descifren mi porvenir: habla, hechicero.\"},{\"heading\":false,\"text\":\"--Poderoso señor, dijo el hebreo: has que tus trompetas de guerra llamen tus gentes al combate: despliega tu bandera de rey y desnuda tu espada, por que yo veo estrañas gentes cabalgando en batalla contra tu pueblo, y el lugar de tu sepultura espera ya tus restos ensangrentados.\"},{\"heading\":false,\"text\":\"Don Rodrigo se lanzó de su silla al lugar donde se encontraba el hebreo, y asió furioso su túnica.\"},{\"heading\":false,\"text\":\"--Perro infiel, gritó: sino mientes, haz que yo vea mi horóscopo; rasga delante de mí el velo que cubre el porvenir: vea yo esas gentes que cabalgan contra mi pueblo, ó por el Dios de Moisés y de Abraham, que he de poner tu cabeza sobre la aguja mas alta de la torre mayor de mi castillo.\"},{\"heading\":false,\"text\":\"--¡Rey! continuó el hebreo sin inmutarse alentado por una segunda mirada de don Oppas: lo que escribe la mano de Dios es siempre un misterio para los ojos mortales: en el valle, cerca de tu palacio, sobre las riberas del Tajo, hay una torre misteriosa cuya terrible puerta jamás ha sido tocada por la mano de un rey; si tu mano toca esa puerta, ella se abrirá, y dentro de la torre encontrarás tu destino.\"},{\"heading\":false,\"text\":\"--Pero esa torre, dijo el rey palideciendo, guarda una tradicion oscura: segun esa tradicion, el rey que la abra ó morirá ó será tan rico, tan sabio y tan poderoso como el rey Salomon; esa torre fué construida durante una tempestad por los magos que acompañaban á Attila, y desde aquel terrible rey hasta mí, ninguno ha osado penetrar en ella.\"},{\"heading\":false,\"text\":\"--Y tú mismo, rey, nada verás en la torre, añadió Gutz, obedeciendo á una tercera mirada de don Oppas, sino llevas contigo el triunfo de la pureza de una vírgen.\"},{\"heading\":false,\"text\":\"--¿Y qué vírgen es esa?\"},{\"heading\":false,\"text\":\"--Esa vírgen es Florinda, la hija del conde don Julian.\"},{\"heading\":false,\"text\":\"--¡Pues bien! esclamó don Rodrigo, Florinda será mia, y luego mi mano tocará la puerta de la torre; buscaré en ella, en su recinto mas tenebroso, el misterio de mi porvenir y arrostraré con valor mi destino. ¡Hola Singiberto!\"},{\"heading\":false,\"text\":\"El noble á quien el rey llamaba, apareció en la puerta de la cámara.\"},{\"heading\":false,\"text\":\"--Llévate á ese hebreo, le dijo, y guárdale en la torre mas fuerte del palacio.\"},{\"heading\":false,\"text\":\"--Gutz adelantó hácia Singiberto y salió con él.\"},{\"heading\":false,\"text\":\"--Debo triunfar de la pureza de Florinda, antes de ir á la torre misteriosa, esclamó el rey. Y bien, ¿has reconocido ya la vivienda de la hija de don Julian? añadió dirigiéndose á don Oppas.\"},{\"heading\":false,\"text\":\"--Sí, si señor; y si tú quieres, esta misma noche Florinda será tuya.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡esta noche! ¡esta noche! esclamó el rey.\"},{\"heading\":false,\"text\":\"--Para vencerla será necesario que apeles á malas artes.\"},{\"heading\":false,\"text\":\"--¡Cómo!\"},{\"heading\":false,\"text\":\"--Si Florinda se viese sujeta á un letargo...\"},{\"heading\":false,\"text\":\"--¡Ah!\"},{\"heading\":false,\"text\":\"--Toma, señor, dijo don Oppas sacando de entre sus ropas un pomo de oro.\"},{\"heading\":false,\"text\":\"--¿Y qué es esto?\"},{\"heading\":false,\"text\":\"--Aquí se guarda el zumo de una yerba que produce un sueño delicioso.\"},{\"heading\":false,\"text\":\"El rey guardó con ansia el pomo.\"},{\"heading\":false,\"text\":\"--Florinda será tuya, señor, y despues...\"},{\"heading\":false,\"text\":\"--Sí, despues entraremos en la terrible torre: pero quiero que para entrar en ella me acompañen mis nobles, mis magnates: quiero entrar en la torre con toda mi grandeza de rey. Haré que estén preparados mis magnates, mis soldados y mis esclavos. Tú vendrás conmigo. Vete y vuelve al punto.\"},{\"heading\":false,\"text\":\"Don Oppas salió de la cámara murmurando:\"},{\"heading\":false,\"text\":\"--Dentro de poco se verá obligado á vengar una injuria el conde don Julian.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Poco tiempo despues, como lo habia ordenado don Rodrigo, multitud de nobles godos á caballo y armados de guerra, penetraron en el átrio del palacio.\"},{\"heading\":false,\"text\":\"Don Oppas con escuderos y esclavos de su casa llegó el primero, paró bajo el pórtico y entró en el palacio.\"},{\"heading\":false,\"text\":\"Poco despues, sin acompañamiento, sin galas, con clámides oscuras sobre los arneses, cubiertas las cabezas con bonetes de acero, anchas espadas al cinto, y cabalgando en caballos de batalla, llegaron al átrio, viniendo de distintos puntos tres mancebos.\"},{\"heading\":false,\"text\":\"Los soldados y las gentes del pueblo, que estaban agolpados á la puerta del átrio, abrieron paso á los tres ginetes inclinándose respetuosamente ante ellos, y los nombres de Belay, Teodomiro y Favila corrieron de boca en boca mientras todos los ojos se fijaban en los tres príncipes que, sin descabalgar, fueron á situarse en silencio en un oscuro ángulo del átrio.\"},{\"heading\":false,\"text\":\"Multitud de pajes, ricamente vestidos, giraban en todas direcciones enrojeciendo los muros con la luz de sus antorchas, y venciendo con ellas la blanca y tranquila luz de la luna.\"},{\"heading\":false,\"text\":\"Un rumor confuso de voces contenidas por el temor, se levantaba mas allá de los pórticos esteriores del palacio, donde la plebe, contenida por los soldados del rey, se agolpaba curiosa y asombrada.\"},{\"heading\":false,\"text\":\"Habíase estendido, girado y penetrado en las plazas, en los barrios, y en las callejas mas apartadas de Toledo, una noticia pavorosa. Decíase que la misteriosa torre que todos los reyes antecesores de don Rodrigo habian respetado: la terrible torre nunca abierta, tras cuyos muros se guardaba el destino del pueblo godo, iba á ser profanada por la planta del rey: un terror semejante al que causa el amago de una calamidad que no se conoce, habia dominado todos los corazones, y cristianos y judios abandonando sus casas, llenos de ansiedad, se agolpaban y se estrechaban hacia algun tiempo ante los pórticos del palacio.\"},{\"heading\":false,\"text\":\"Los arcos, los miradores, las balaustradas de las calles circunvecinas, estaban llenos de gentes que maldecian en voz baja y contenida por el temor á don Rodrigo, al par que hablaban con el acento de la esperanza á los tres príncipes Belay, Teodomiro y Favila, cuyas nobles frentes no se habian manchado con los vicios de la córte.\"},{\"heading\":false,\"text\":\"El pueblo los habia visto armados de guerra en medio de los otros príncipes y magnates cubiertos de galas, y en esto habian comprendido una valiente promesa.\"},{\"heading\":false,\"text\":\"Al fin, tras una larga espera, se abrieron las puertas del palacio, y el rey cubierto con un manto de púrpura, ceñida la cabeza con la corona de hierro, pendiente de su costado la espada de oro, apareció sobre su blanco caballo Orelia, al que llevaban de las riendas dos nobles con túnicas y bonetes de escarlata; á su derecha cabalgaba don Oppas, á su izquierda Singiberto; precedíanle pajes con antorchas y le rodeaban cien esclavos negros de su guarda africana.\"},{\"heading\":false,\"text\":\"Los nobles que esperaban en el átrio, se unieron á la comitiva, á la cual, tristes y silenciosos, siguieron al lento paso de sus caballos Belay, Teodomiro y Favila.\"},{\"heading\":false,\"text\":\"La córte se abrió paso por medio del pueblo que se agitaba sombriamente, sin que una aclamacion de amor ó de respeto llegase á los oidos de don Rodrigo.\"},{\"heading\":false,\"text\":\"La cabalgata bajó del palacio, atravesó la ciudad, y penetró en el valle, á cuyo fin, una frente á otro, teniendo en medio el Tajo, se alzaban la torre misteriosa y el castillo de don Julian.\"},{\"heading\":false,\"text\":\"Cabalgaba delante el rey; su caballo galopaba con ardor como impulsado por una fuerza mágica; los pajes y los peones seguian jadeando á la carrera la rápida marcha de los ginetes; alguna vez un paje ó un esclavo caian cansados, y el caballo del rey pasaba sobre ellos como hubiera podido pasar por cima de un monton de hojas secas.\"},{\"heading\":false,\"text\":\"Florinda, en el mirador de su cámara, apoyada en su balaustrada, veia impasible, pálida, inmóvil, descender aquellas antorchas por la vertiente del valle, adelantar, llegar y parar al fin, ante el foso de su castillo.\"},{\"heading\":false,\"text\":\"Sonaron las trompetas y la voz de Singiberto gritó:\"},{\"heading\":false,\"text\":\"--¡Vasallo! ¡abrid al rey!\"},{\"heading\":false,\"text\":\"Crugieron las cadenas del puente y don Rodrigo, don Oppas, Singiberto, y los dos nobles que llevaban las riendas de Orelia entraron en el castillo.\"},{\"heading\":false,\"text\":\"Poco despues arremetieron tambien por la poterna, Belay, Teodomiro y Favila.\"},{\"heading\":false,\"text\":\"Las demás gentes del rey rodearon el castillo.\"},{\"heading\":false,\"text\":\"Florinda permanecia en el mirador, siempre pálida, siempre impasible.\"},{\"heading\":false,\"text\":\"Pasó algun tiempo, y al cabo una sombra oscura apareció en el mirador junto á Florinda.\"},{\"heading\":false,\"text\":\"--Ha llegado la hora, dijo sombriamente Kaib.\"},{\"heading\":false,\"text\":\"Florinda se volvió á él y le contempló gravemente.\"},{\"heading\":false,\"text\":\"--¿La hora de qué? dijo.\"},{\"heading\":false,\"text\":\"--El rey don Rodrigo es tu huesped, señora.\"},{\"heading\":false,\"text\":\"--Y bien: que sirvan al rey; que mis manjares cubran su mesa; que el vino llene los jarros de oro; que le sirvan mis esclavos.\"},{\"heading\":false,\"text\":\"--Segun antigua costumbre, el señor del castillo debe servir al rey.\"},{\"heading\":false,\"text\":\"--Mi padre le está sirviendo en Tanja.\"},{\"heading\":false,\"text\":\"--Por lo mismo; en ausencia de tu padre tú estas obligada á servir al rey, repuso sombriamente Kaib.\"},{\"heading\":false,\"text\":\"Guardó por un momento silencio Florinda; una espresion singular pasó por sus ojos; acreció su palidez, y al fin dijo:\"},{\"heading\":false,\"text\":\"--Ruega al rey me perdone si le hago esperar mientras me engalanan, para servirle dignamente, mis esclavas.\"},{\"heading\":false,\"text\":\"Y volviendo las espaldas á Kaib, se encaminó lentamente á una puerta, por la cual desapareció.\"},{\"heading\":false,\"text\":\"Kaib tuvo fija en ella, mientras pudo verla, una mirada profundamente conmovida.\"},{\"heading\":false,\"text\":\"Luego esclamó con acento tembloroso:\"},{\"heading\":false,\"text\":\"--¡Que se cumpla lo que está escrito!\"},{\"heading\":false,\"text\":\"Y fué á llevar el mensage de Florinda al rey.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"El rey se paseaba impaciente por una magnífica cámara.\"},{\"heading\":false,\"text\":\"Trofeos de guerra, arrancados á los enemigos en diferentes épocas, ennoblecian los muros, atestiguando el valor de los ascendientes del conde don Julian.\"},{\"heading\":false,\"text\":\"Una ancha mesa, cubierta con paños de púrpura, dejaba ver humeantes viandas en platos de oro, y jarros del mismo metal, rodeados de anchas copas, rebosaban el vino.\"},{\"heading\":false,\"text\":\"Cuatro candelabros de oro alumbraban la mesa.\"},{\"heading\":false,\"text\":\"Todo demostraba la gran riqueza del dueño del castillo.\"},{\"heading\":false,\"text\":\"Delante de la mesa solo habia un enorme sillon cubierto con un dosel: el sillon del castellano cedido al rey.\"},{\"heading\":false,\"text\":\"Don Oppas, Belay, Teodomiro y Favila, estaban agrupados y en silencio á cierta distancia del rey, medida por el respeto.\"},{\"heading\":false,\"text\":\"No tuvo que esperar mucho don Rodrigo.\"},{\"heading\":false,\"text\":\"Abrióse una puerta y apareció Florinda resplandeciente con su juventud, su pureza, su hermosura, sus joyas y sus magníficas galas.\"},{\"heading\":false,\"text\":\"Adelantó lentamente, arrastrando su pesada y brillante túnica de seda y oro, con la frente alta y ceñida con la diadema de las nobles godas.\"},{\"heading\":false,\"text\":\"A alguna distancia del rey se detuvo.\"},{\"heading\":false,\"text\":\"--Bien venido seas, señor, dijo con voz reposada y grave, al hogar del conde don Julian.\"},{\"heading\":false,\"text\":\"Don Rodrigo, mudo de asombro ante tanta hermosura, no le contestó mas que con la elocuente sorpresa de su semblante y la encendida mirada de sus ojos.\"},{\"heading\":false,\"text\":\"Florinda silenciosa, inmóvil, imponente, fijaba en el rey una mirada altiva y severa.\"},{\"heading\":false,\"text\":\"Parecia que no veia á las otras personas que habia en la cámara, aunque entre ellas estaba Belay, el amado de su alma.\"},{\"heading\":false,\"text\":\"El rey temblaba; con la mirada fija en Florinda; la llama de un amor infernal se habia apoderado de su alma, y lo habia olvidado todo; el descontento de sus vasallos y los funestos amagos del porvenir que guardaba para él la terrible torre que se levantaba escueta, solitaria y muda al otro lado del Tajo.\"},{\"heading\":false,\"text\":\"Las primeras palabras que pronunció don Rodrigo representaban su deseo.\"},{\"heading\":false,\"text\":\"--Salid, dijo á don Oppas y á los tres príncipes, salid y esperad afuera.\"},{\"heading\":false,\"text\":\"--¡Que salgamos! esclamó obedeciendo á la voz de sus celos Belay.\"},{\"heading\":false,\"text\":\"--¿Quién habla cuando el señor manda? gritó el rey.\"},{\"heading\":false,\"text\":\"--Esa doncella, esclamó adelantándose Belay, es mi esposa.\"},{\"heading\":false,\"text\":\"--¡Tu esposa, Florinda! esclamó palideciendo mortalmente el rey y temblando de cólera.\"},{\"heading\":false,\"text\":\"--Me ha jurado la fé de su amor ante Dios.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿y no es mas que eso? príncipe: yo creí que en efecto la hija de don Julian era tu esposa... pero no lo es... ni lo será, porque yo que soy tu señor no te la concederé.\"},{\"heading\":false,\"text\":\"--Dicen, rey don Rodrigo, observó con un marcado acento de amenaza Belay, que para tí nada hay respetable mas que tu voluntad: que allí donde tus ojos se fijan van la impureza y la deshonra.\"},{\"heading\":false,\"text\":\"--¿Y quién dice eso, mi leal Belay, mi buen pariente, mi hermoso príncipe? dijo el rey dominando mal su cólera.\"},{\"heading\":false,\"text\":\"--Lo dicen las desdichadas que has deshonrado, los viejos cuyas canas has escarnecido, las madres á quienes has arrojado cubiertas de vergüenza las hijas de sus entrañas.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿y no te han dicho que el rey castiga de muerte á los traidores que se atreven á insultarle? dijo don Rodrigo adelantando furioso hacia Belay, que puso la mano sobre la empuñadura de su espada.\"},{\"heading\":false,\"text\":\"Don Oppas cubria con una frialdad hipócrita la alegria de su alma; veia al hasta entonces leal y respetuoso Belay, revelado contra don Rodrigo; veia al rey decidido á todo; sabia que para que cayese la ira de un vasallo poderoso, del conde don Julian, sobre don Rodrigo, bastaba con que este tocase solamente á la orla de la túnica de Florinda; veia ya rebosar de Tánger millares de combatientes salvages, los veia atravesar el estrecho de Alzacac, poner las plantas en Calpe, devastar la Bética y prestar una poderosa ayuda á los hijos de Witiza.\"},{\"heading\":false,\"text\":\"Veia acercarse el momento en que el conde don Julian seria injuriado por don Rodrigo en Florinda.\"},{\"heading\":false,\"text\":\"Belay lo veia del mismo modo y esperaba al rey con la mano puesta en la empuñadura de su espada.\"},{\"heading\":false,\"text\":\"Florinda se interpuso.\"},{\"heading\":false,\"text\":\"--El rey lo manda; dijo con acento dominador: salid príncipes, el rey está en el hogar de un noble vasallo, y tiene derecho á ser obedecido en él. Salid: la hija del conde don Julian cumplirá con lo que debe á su sangre.\"},{\"heading\":false,\"text\":\"Belay vaciló, pero una mirada de Florinda le decidió á obedecer; salió, y tras él salieron Teodomiro y Favila y, al fin, don Oppas que apenas podia contener su feroz alegria.\"},{\"heading\":false,\"text\":\"Florinda y el rey quedaron solos.\"},{\"heading\":false,\"text\":\"--Sentaos, señor, sentaos, dijo la jóven; estais bajo un techo amigo: honrad la copa de mi padre bebiendo en ella.\"},{\"heading\":false,\"text\":\"Y Florinda llenó de vino una ancha copa de oro.\"},{\"heading\":false,\"text\":\"El rey fijó una mirada codiciosa en la copa, mientras que revolvia en su mano entre sus ropas, el pomo que le habia dado don Oppas.\"},{\"heading\":false,\"text\":\"¿Pero cómo verter el contenido del pomo en la copa sin que lo notase Florinda?\"},{\"heading\":false,\"text\":\"Una idea surgió en el pensamiento del rey.\"},{\"heading\":false,\"text\":\"--Me han dicho, dijo, que cantas de una manera maravillosa.\"},{\"heading\":false,\"text\":\"--¿Y quién te ha dicho eso, señor?\"},{\"heading\":false,\"text\":\"--No recuerdo bien: ¡ah! sí, algunas noches he oido el son de una lira en los aposentos de la reina: el sonido de aquella lira me ha arrebatado, ha resonado dulcemente en mi corazon, y la voz que ha cantado unida á aquella lira me ha parecido la voz de un arcángel; por la mañana he preguntado: ¿quién era la muger que tan dulces armonías exhalaba en los aposentos de la reina Aylat? y me han contestado.--Era la hermosa hija del conde don Julian.\"},{\"heading\":false,\"text\":\"--Te han engañado, señor, contestó Florinda. Nunca he cantado en los aposentos de mi señora.\"},{\"heading\":false,\"text\":\"Tembló el rey temiendo que Florinda no supiese tañer la lira.\"},{\"heading\":false,\"text\":\"--Pero si quieres, señor, dijo la jóven, cantaré para tí.\"},{\"heading\":false,\"text\":\"El alma del rey se dilató.\"},{\"heading\":false,\"text\":\"--Espera un momento, señor; voy á pedir á mis esclavas mi lira de marfil.\"},{\"heading\":false,\"text\":\"Apenas hubo vuelto Florinda la espalda, cuando don Rodrigo trémulo, dominado por una ardiente y próxima esperanza, vertió el contenido del pomo que le habia dado don Oppas en la copa que habia llenado Florinda.\"},{\"heading\":false,\"text\":\"Poco despues la jóven volvió preludiando de una manera mágica en las cuerdas de oro de una magnífica lira de marfil.\"},{\"heading\":false,\"text\":\"El semblante de Florinda estaba triste y apenado como si un funesto presentimiento oprimiera su alma, y permaneció de pie preludiando en su lira á poca distancia del rey.\"},{\"heading\":false,\"text\":\"--¿No bebes, señor? le dijo despues de un momento de silencio ¿recelas acaso de la copa de tu vasallo?\"},{\"heading\":false,\"text\":\"--Es antigua costumbre que el vasallo beba primero cuando ofrece la copa á su rey, dijo don Rodrigo.\"},{\"heading\":false,\"text\":\"Y presentó la copa á Florinda.\"},{\"heading\":false,\"text\":\"La jóven sostuvo con su brazo izquierdo su lira, tomó la copa y bebió un sorbo.\"},{\"heading\":false,\"text\":\"--La libacion completa, dijo el rey sonriendo, esa es la costumbre.\"},{\"heading\":false,\"text\":\"Florinda apuró la copa.\"},{\"heading\":false,\"text\":\"--¡Ah! murmuró el rey: tu hermosura es mia.\"},{\"heading\":false,\"text\":\"--¿Qué dices, señor?\"},{\"heading\":false,\"text\":\"--Que me llenes otra vez la copa.\"},{\"heading\":false,\"text\":\"Llenóla Florinda y el rey la apuró.\"},{\"heading\":false,\"text\":\"Fuese que el pequeño resto que habia quedado en la copa inficionase el vino nuevamente echado en ella por Florinda, fuese que le embriagase la hermosura de la jóven, el rey sintió en su cabeza un vago y delicioso delirio; parecióle que la hermosura de Florinda se aumentaba y crecia hasta hacerse sobrenatural; que las luces se amortiguaban, y que solo quedaba la luz de la hermosura de Florinda: luego vió como en un sueño fijos en los suyos los ojos de la jóven que le decian amores: la vió tomar un escabel, sentarse á sus pies, mirarle sonriendo, como solo mira á un hombre la muger que le adora, y al cabo escuchó un canto dulcísimo.\"},{\"heading\":false,\"text\":\"Creyóse arrebatado al paraiso, y luego cesar la música, rodear su cuello los frescos brazos de Florinda, y posarse en sus labios áridos unos labios húmedos y ardientes.\"},{\"heading\":false,\"text\":\"Florinda resplandecia; Florinda le embriagaba, y en medio de su embriaguez y de su delirio, no pudo escuchar el rey estas palabras, pronunciadas con acento terrible por una voz ronca tras el tapiz de una puerta de la cámara:\"},{\"heading\":false,\"text\":\"--¡Lo que estaba escrito se ha cumplido: el oriente avanza contra el occidente, y el buitre se cierne ya sobre el campo de la matanza esperando los cadáveres!\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Entretanto el rey, que habia salido del castillo, seguido de don Oppas, de Belay, de Teodomiro, de Favila y de sus cortesanos, atravesó el Tajo en barcas que estaban preparadas, y llegó cerca de la torre situada en la otra orilla, hasta la cual habian abierto paso algunos esclavos rompiendo con sus espadas la maleza.\"},{\"heading\":false,\"text\":\"El rey descabalgó al fin delante de la puerta de la torre.\"},{\"heading\":false,\"text\":\"Todos temblaron en aquel momento solemne: el rey de impaciencia, don Oppas de esperanza, los demás de la comitiva de terror.\"},{\"heading\":false,\"text\":\"Solo Belay y los dos príncipes sus nobles amigos no temblaron, pero invocaron á Dios con las manos puestas en las empuñaduras de sus espadas.\"},{\"heading\":false,\"text\":\"Porque á la llegada del rey, dentro de la torre, en torno de ella, cerca y lejos, en los aires y en las entrañas de la tierra se habia oido un rumor lejano y confuso de batalla; lentamente aquel rumor creció; oyóse al fin de una manera distinta el choque del hierro contra el hierro, los gritos de guerra, los clamores de los moribundos, el relinchar de los caballos, el alarido de las trompetas, el silvo de las flechas, el áspero rechinar de las ruedas de los carros y el doblar de los tambores y atabales.\"},{\"heading\":false,\"text\":\"Sin que nadie tocase á la puerta, esta se abrió con estruendo, y una luz pálida, sin oriente ni ocaso, alumbró el interior.\"},{\"heading\":false,\"text\":\"Al abrirse la puerta el estruendo creció; parecia que el valle lanzaba guerreros en todas direcciones; mugió sordamente el Tajo, condensóse la niebla, tembló la tierra bajo los cascos de millares de caballos, el aire vibró herido por innumerables y salvajes gritos de guerra, y un cálido y nauseabundo olor de sangre lo envolvió todo.\"},{\"heading\":false,\"text\":\"Y en medio de aquel estruendo pavoroso, dominándole como el bramido del huracan domina al ruido del aguacero en la tormenta, una voz cavernosa retumbó dentro de la torre, que vaciló al sonido de aquella voz sobre sus fortísimos cimientos.\"},{\"heading\":false,\"text\":\"--¿Quiénes sois y qué quereis? dijo la voz.\"},{\"heading\":false,\"text\":\"--Soy don Rodrigo, rey de los godos, contestó el rey.\"},{\"heading\":false,\"text\":\"Al escuchar estas palabras, salió de la torre una esplosion de carcajadas y un coro infinito gritó:\"},{\"heading\":false,\"text\":\"--¡Es el rey don Rodrigo! ¡el último rey! ¡el último rey de los godos!\"},{\"heading\":false,\"text\":\"Y al mismo tiempo avanzaron hácia la puerta, pero sin pasar de ella, sombras envueltas en flotantes velos, pálidas y macilentas como cadáveres insepultos, y los ojos de todas las sombras se fijaban en el rey que estaba fascinado, y las bocas de todas las sombras le saludaban con insolentes carcajadas, y los brazos de todas las sombras se estendian hácia él.\"},{\"heading\":false,\"text\":\"Y sus calvas cabezas relucian, y sus monstruosos cuerpos se retorcian, y sus infernales bocas chillaban, gritaban, ahullaban, rugian, y á la vista de aquella espantosa vision la comitiva del rey huyó aterrada hasta las márgenes del rio y hasta los remotos confines del valle.\"},{\"heading\":false,\"text\":\"Solo quedaron, delante de la puerta de la torre, el rey con los cabellos herizados de espanto, detenido por un poder superior, y Belay, Teodomiro y Favila, á pié, envueltos en sus clámides rojas, con las espadas desnudas en las manos diestras, las siniestras sobre el corazon y el nombre de Dios en los lábios.\"},{\"heading\":false,\"text\":\"El rey, aterrado, trémulo, fijaba la inmóvil mirada de sus ojos en la tremenda vision; los tres príncipes sentian latir en sus venas su sangre de valientes sin miedo y sin tacha.\"},{\"heading\":false,\"text\":\"--¡Adentro, señor! gritó Belay adelantando con la espada en alto: ¡adelante, hermanos mios! ¡ya que hemos llegado hasta aquí, es preciso que las artes de Satanás no detengan á cuatro príncipes cristianos!\"},{\"heading\":false,\"text\":\"Y asió de don Rodrigo, y seguido de Teodomiro y Favila penetró en la torre.\"},{\"heading\":false,\"text\":\"La vision desapareció, como por ensalmo, apenas el rey y los tres príncipes pisaron el interior de la torre; apagóse la claridad lívida que antes la habia alumbrado y solo quedó el ténue reflejo de la luna.\"},{\"heading\":false,\"text\":\"--¡Una antorcha! gritó Belay.\"},{\"heading\":false,\"text\":\"Desde la márgen del rio adelantó uno de los pajes mas atrevidos, y entregó una antorcha al príncipe.\"},{\"heading\":false,\"text\":\"El noble godo adelantó aun mas, dentro de la torre, y la reconoció á la luz de la antorcha.\"},{\"heading\":false,\"text\":\"Era la torre inmensa, tétrica, bastante á imponer terror por sí sola, sin la ayuda de sus apariciones, al corazon mas valiente: formábala una bóveda circular sustentada en el centro por un gigantesco pilar; la altura de esta bóveda se perdia en la oscuridad, y sobre sus muros y en torno de la pilastra, se veian, labrados en la roca, mónstruos informes, reptiles horribles, esqueletos de gigantes; todo allí, como petrificado por un conjuro ó por una maldicion; oscuras inscripciones orlaban los muros en fajas de piedra, con letras de sangre, y sangre parecia brotar el pavimento húmedo y resbaladizo.\"},{\"heading\":false,\"text\":\"Belay conduciendo al rey y seguido de Teodomiro y Favila, recorrió la torre y solo se detuvo ante una especie de nicho en el cual habia un arca de hierro mohoso.\"},{\"heading\":false,\"text\":\"Al verla don Rodrigo, ya mas sereno por la desaparicion de las sombras, que, siempre incrédulo é impío habia juzgado un delirio de su razon, dió un grito de alegria.\"},{\"heading\":false,\"text\":\"--¡Abrid! ¡abrid! dijo á los príncipes: ¡allí debe encerrarse un riquísimo tesoro, ¡abrid!\"},{\"heading\":false,\"text\":\"Belay levantó la pesada tapa y alumbró el interior del arca.\"},{\"heading\":false,\"text\":\"Don Rodrigo lanzó dentro de ella una mirada codiciosa.\"},{\"heading\":false,\"text\":\"Pero en vez de joyas solo vió veinte y cinco coronas de hierro atadas en una cadena; su blason real roto y manchado, su espada enmohecida y su manto real hecho girones y ensangrentado.\"},{\"heading\":false,\"text\":\"Un libro escrito en caracteres árabes, el Korán, estaba puesto sobre la Biblia abierta y deshojada, y el verde pendon del Profeta, envolvia en sus pliegues otro objeto.\"},{\"heading\":false,\"text\":\"Belay sacudió la bandera y de ella, una cabeza humana cayó sobre el pavimento.\"},{\"heading\":false,\"text\":\"Aquella cabeza separada de su tronco era tan semejante á la que aun vivia sobre los hombros de don Rodrigo, que los príncipes se estremecieron y el rey tembló, y sintió correr por sus venas el frio de la muerte.\"},{\"heading\":false,\"text\":\"--¡A las armas, hermanos mios! gritó Belay: ¡corramos á nuestros castillos! ¡que el pueblo godo se levante á tu voz, señor, porque la tradicion se cumple y en esta torre fatal está encerrado tu destino!\"},{\"heading\":false,\"text\":\"--¡Los árabes! esclamó don Rodrigo levantando por primera vez su cabeza en un movimiento de energía: ¡pues bien! ¡que vengan! ¡las canas no me impedirán cubrir mi cabeza con mi capacete coronado, y bajo la púrpura vestiré la lóriga! ¡la corona en la frente y la espada en la mano cabalgaré delante de mi pueblo, y si está escrito que hayamos de sucumbir, sucumbiremos como valientes! ¿no es verdad príncipes?\"},{\"heading\":false,\"text\":\"Los tres príncipes se miraron con estupor. Habian creido hasta entonces que el rey habia muerto para el valor y que solo vivia para la molicie y para la corrupcion.\"},{\"heading\":false,\"text\":\"--Venid, mis valientes caudillos; pronto mis huestes y las de mis nobles, probarán si es incontrastable lo que está escrito por el destino. Entre tanto, á Dios.\"},{\"heading\":false,\"text\":\"Y salió delante de ellos de la torre, cabalgó en su corcel y llamó en voz alta á don Oppas.\"},{\"heading\":false,\"text\":\"LETRE dibº y litº Lit de J.J. MARTINEZ, MADRID.]\"},{\"heading\":false,\"text\":\"Don Oppas se acercó temblando.\"},{\"heading\":false,\"text\":\"--A Toledo, dijo el rey con acento sombrío.\"},{\"heading\":false,\"text\":\"Poco despues la brillante cabalgata aterrada, triste y silenciosa volvió á entrar en la ciudad.\"},{\"heading\":false,\"text\":\"Antes del amanecer salió de ella á pie, por la puerta de los Leones un hombre envuelto en una clámide roja, y en silencio y á gran paso se encaminó al valle del Tajo.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Desde que salió el rey del castillo del conde don Julian, Florinda pálida, pintada en el semblante una espresion de despecho y de desesperacion horrible, habia permanecido en su mirador, dejando brillar las lágrimas, que corrian silenciosamente por sus megillas, á los rayos de la luna.\"},{\"heading\":false,\"text\":\"Recordaba de una manera confusa una cosa horrible; se sentia lacerada en el cuerpo y en el alma, y su pensamiento pasaba tan pronto del rey don Rodrigo, su infame burlador, á Belay, el amado de su alma.\"},{\"heading\":false,\"text\":\"Florinda no comprendia la razon de su momentáneo delirio entre los brazos del rey: la desdichada no sabia que habia sido embriagada por un filtro terrible.\"},{\"heading\":false,\"text\":\"Conocia sin embargo su vergüenza y anhelaba venganza, una venganza cruda.\"},{\"heading\":false,\"text\":\"Hubo un momento en que una horrible decision se pintó en su semblante, se apartó bruscamente del mirador; corrió á su cámara, tomó un pergamino y escribió en él apresuradamente algunas líneas.\"},{\"heading\":false,\"text\":\"Despues llamó á Kaib.\"},{\"heading\":false,\"text\":\"Este apareció de improviso como si hubiese estado detrás de la puerta.\"},{\"heading\":false,\"text\":\"--Ha llegado la hora de la tribulacion, Florinda, y me has llamado, héme aquí: ¿qué quieres?\"},{\"heading\":false,\"text\":\"--Es necesario que lleves esta carta á mi padre á Tanja.\"},{\"heading\":false,\"text\":\"--Iré, dijo Kaib.\"},{\"heading\":false,\"text\":\"--Pues bien, vete y que el nuevo sol te vea cabalgando hácia el oriente.\"},{\"heading\":false,\"text\":\"--Antes de partir es necesario que yo te deje segura y libre del infame.\"},{\"heading\":false,\"text\":\"--¡Ah! esclamó Florinda cubriéndose de rubor: ¿sabes?...\"},{\"heading\":false,\"text\":\"--Lo sé todo: yo soy mago.\"},{\"heading\":false,\"text\":\"--¿Y habias previsto la horrible desgracia que me iba á acontecer?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Y por qué no me salvaste? esclamó con desesperacion Florinda.\"},{\"heading\":false,\"text\":\"--Estaba escrito que tú fueses sacrificada, para que el pueblo godo fuese destruido.\"},{\"heading\":false,\"text\":\"--¡Ah!\"},{\"heading\":false,\"text\":\"--Pero yo no puedo dejarte abandonada. El infame don Rodrigo arde en tus amores, su delirio por tí crece, siempre tendrá para enloquecerte un filtro, un ensalmo. La ciencia se vende al oro. Pero ven: yo te daré un amuleto que te libre de las asechanzas del rey. Ven hija de don Julian: ven.\"},{\"heading\":false,\"text\":\"Arrastrada por el acento solemne del esclavo, Florinda le siguió: salieron del castillo por un postigo, atravesaron el Tajo en una barca y llegaron á la torre maravillosa, apenas se habian alejado de ella el rey y sus gentes.\"},{\"heading\":false,\"text\":\"Kaib desnudó su puñal y tocó con el pomo en la gran puerta de hierro.\"},{\"heading\":false,\"text\":\"El eco despertó, como de las profundidades de un abismo, el ruido causado por la mano del hombre.\"},{\"heading\":false,\"text\":\"Una voz pujante como á la llegada del rey, gritó desde adentro.\"},{\"heading\":false,\"text\":\"--¿Quiénes sois y qué quereis?\"},{\"heading\":false,\"text\":\"--Somos Florinda y Kaib, contestó el esclavo.\"},{\"heading\":false,\"text\":\"Entonces la puerta se abrió en silencio y por sí misma.\"},{\"heading\":false,\"text\":\"Una claridad lívida iluminaba el interior.\"},{\"heading\":false,\"text\":\"--No tiembles, Florinda, dijo con voz segura Kaib, porque si tiemblas, esa puerta se cerrará y no volverá á abrirse mas para nosotros.\"},{\"heading\":false,\"text\":\"Florinda procuró dominarse y lo consiguió, á pesar de que vagaban con paso lento, en torno suyo, sombras envueltas en sudarios blancos, pálidas y sombrías, como cadáveres insepultos; cada una de ellas fijaba sus hundidos ojos en la jóven de una manera horrible y cruel.\"},{\"heading\":false,\"text\":\"--Todos estos han llamado como nosotros á esta puerta, dijo Kaib: todos ellos han sucumbido al pavor y velan encantados aquí: mira, hay valientes guerreros y hermosas damas; todos han venido en busca del tesoro que encierra esta torre y ese tesoro está guardado para tí.\"},{\"heading\":false,\"text\":\"Florinda sentia dentro de su espíritu un poder superior; su corazon dominaba todos aquellos terrores; su vista se estendia sin vacilar por los ámbitos de la torre, abarcándolos con su mirada serena y poderosa.\"},{\"heading\":false,\"text\":\"Y era porque Florinda estaba desesperada, y no podia aterrarse porque tenia sed de venganza, y aquella ansiosa rabia la daba valor.\"},{\"heading\":false,\"text\":\"Kaib, llevando de la mano á Florinda, avanzó hasta el pié de la pilastra que sostenia la bóveda de la torre y puso la mano sobre la cabeza de un horrible jorobado de piedra, que estaba como incrustado al pié de la pilastra.\"},{\"heading\":false,\"text\":\"--Yo he leido en los astros, dijo: yo soy mago: los astros me han revelado que tú guardas un amuleto que defiende á las mugeres de la impureza de los hombres y de su propia impureza.\"},{\"heading\":false,\"text\":\"El enano rugió sordamente, levantó la cabeza y volteó en sus órbitas, mirando á Kaib y á Florinda, sus torbos ojos de piedra, que por un momento parecieron de fuego.\"},{\"heading\":false,\"text\":\"Ninguno de los dos tembló.\"},{\"heading\":false,\"text\":\"Entonces el jorobado se arrancó de la pilastra y caminó delante de los dos, haciendo resonar sobre el pavimento las secas pisadas de sus enormes piés de mármol.\"},{\"heading\":false,\"text\":\"--Hé aquí la piedra de los siete sellos, dijo deteniéndose en la parte oriental de la pilastra; si esa muger es la sentenciada por el destino á causar la ruina del pueblo godo, su mano romperá el encanto, y el precioso talisman será suyo.\"},{\"heading\":false,\"text\":\"Sobre la losa que servia de puerta á un arco, habia á cada lado tres signos, y otro en el centro: aquellos siete signos eran enteramente iguales entre sí, y parecian láminas de oro sobrepuestas al mármol; consistian estos sellos en dos triángulos cruzados, dentro de los cuales se leia en caracteres caldeos: ¡DIOS!\"},{\"heading\":false,\"text\":\"Florinda tocó con su dedo el signo del centro, que desapareció absorvido por el mármol, como una gota de agua que cae sobre una plancha de hierro caldeado.\"},{\"heading\":false,\"text\":\"Tocó el segundo, el tercero, hasta el sétimo y todos desaparecieron de igual modo.\"},{\"heading\":false,\"text\":\"--Hé aquí la Kaba de los árabes, dijo el enano: lo que estaba escrito se ha cumplido.\"},{\"heading\":false,\"text\":\"Y asiendo la piedra por uno de los bordes, la separó, á pesar de su enorme peso, con la misma facilidad que si hubiera levantado la hoja seca de un árbol.\"},{\"heading\":false,\"text\":\"Entonces quedó descubierto un precioso arco árabe de oro, calado, esmaltado y cincelado, que daba entrada á un pequeño retrete resplandeciente.\"},{\"heading\":false,\"text\":\"Una luz brillantísima emanaba de una caja de esmeralda, colocada sobre almohadones de púrpura, oro y piedras preciosas.\"},{\"heading\":false,\"text\":\"--En esa caja está el amuleto; dijo el enano: la muger que le tenga pendiente de su cuello, estará libre de la impureza, pero no de las desgracias, de las injurias, ni de la muerte.\"},{\"heading\":false,\"text\":\"Muger consagrada á Dios será y la muerte y la condenacion caerán sobre el hombre que ponga en ella su mano, mientras tenga sobre su seno el amuleto.\"},{\"heading\":false,\"text\":\"--Escrito está, murmuró Kaib: ¡cúmplase la voluntad del Dios grande y justo!\"},{\"heading\":false,\"text\":\"Florinda abrió la caja.\"},{\"heading\":false,\"text\":\"Dentro habia un collar de gruesas perlas y de inestimable precio y en el centro de él, pendiente de la perla mas gruesa, habia una manecita negra de ébano, sobre la cual y de una manera imperceptible, estaba grabado el sello de Salomon, en cuyo centro en caracteres caldeos, se leia la palabra ¡DIOS!\"},{\"heading\":false,\"text\":\"Nada teneis que hacer ya aquí, dijo el enano: el decreto del destino se ha cumplido: la Florinda de los godos, la Kaba de los árabes, ha roto los siete sellos que guardaban la ruina de un pueblo. Idos.\"},{\"heading\":false,\"text\":\"El jorobado fué á enclavarse de nuevo en el lugar que habia abandonado, tornando á su marmórea inmovilidad.\"},{\"heading\":false,\"text\":\"Florinda fué á ceñirse el amuleto.\"},{\"heading\":false,\"text\":\"--Espera, dijo Kaib: yo te amo.\"},{\"heading\":false,\"text\":\"Florinda miró con los ojos arrasados de lágrimas al esclavo.\"},{\"heading\":false,\"text\":\"--Yo te amo, continuó Kaib, como ama el hermano á la hermana, la madre á la hija, el dia al sol; pero Kaib no ha encontrado gracia en tus ojos, hija de don Julian; amas á un hombre que no puede ser tu esposo, y tu pureza ha sido arrebatada por un infame á quien no podias amar. Nos vemos por la última vez, Florinda.\"},{\"heading\":false,\"text\":\"--¡Por la última vez!\"},{\"heading\":false,\"text\":\"--Sí; yo moriré pronto, moriré junto á tu padre que vendrá á vengarte.\"},{\"heading\":false,\"text\":\"--¡Y mi padre!\"},{\"heading\":false,\"text\":\"--Morirá tambien.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡Dios mio! ¿y mi pueblo?\"},{\"heading\":false,\"text\":\"--Será esclavo.\"},{\"heading\":false,\"text\":\"--¡Y todo por mí!\"},{\"heading\":false,\"text\":\"--¡Estaba escrito!\"},{\"heading\":false,\"text\":\"--Pero el destino es injusto.\"},{\"heading\":false,\"text\":\"--Dios te ha elegido por víctima.\"},{\"heading\":false,\"text\":\"--Pues bien, que se cumpla la voluntad de Dios.\"},{\"heading\":false,\"text\":\"Y Florinda levantó la frente radiante de magestad y de valor.\"},{\"heading\":false,\"text\":\"--No volveremos á vernos mas, dijo Kaib: abrázame, hija de don Julian.\"},{\"heading\":false,\"text\":\"Florinda se arrojó entre los brazos del nubio, como pudiera haberse arrojado entre los brazos de su padre, y lloró sobre su robusto pecho.\"},{\"heading\":false,\"text\":\"Kaib la besó en la cabeza sobre los cabellos y la separó de sí.\"},{\"heading\":false,\"text\":\"Florinda rodeó á su cuello el amuleto.\"},{\"heading\":false,\"text\":\"Entonces pareció que su hermosura crecia: sus ojos brillaban con un resplandor sobrenatural: la blancura de su tez se habia hecho deslumbrante: el amor volaba en torno suyo, irresistible, impregnado de ambrosía y de pureza.\"},{\"heading\":false,\"text\":\"Kaib sintió abrasarse su corazon en un fuego infinito y voraz: Florinda no era entonces una muger: era mas que una hurí; era un arcángel.\"},{\"heading\":false,\"text\":\"A su vista se agitaron los millares de mónstruos enclavados en los muros y en la pilastra, y en la bóveda de la torre, sobre sus alveolos de piedra, chocaron sus duras cabezas, y un grito de guerra retumbó inmenso en las concavidades.\"},{\"heading\":false,\"text\":\"Pero lentamente volvió el silencio á dominar la torre, se apagó el crepúsculo frio y nebuloso que la iluminaba, y solo quedó el reflejo de la luz de la luna que penetraba blanca y débil por la ancha arcada de la puerta, por la que salieron los jóvenes.\"},{\"heading\":false,\"text\":\"La puerta se cerró inmediatamente.\"},{\"heading\":false,\"text\":\"--He cumplido con lo que me prescribian el destino y el amor, dijo Kaib. ¡Hija de don Julian! ¡un poder superior te protege, y en vano quiere envolverte en sus alas el negro espíritu de los amores impuros!\"},{\"heading\":false,\"text\":\"Florinda callaba; sus ojos, fijos en la luna, estaban llenos de lágrimas.\"},{\"heading\":false,\"text\":\"Parecia que su vista alcanzaba á leer en la inmensidad el porvenir.\"},{\"heading\":false,\"text\":\"--A Dios, dijo Kaib.\"},{\"heading\":false,\"text\":\"--¿Cómo? ¿me abandonas aquí, sola, junto á esta terrible torre?\"},{\"heading\":false,\"text\":\"--Siento los pasos de un hombre que se acerca, y ese hombre te acompañará: ese hombre es Belay.\"},{\"heading\":false,\"text\":\"--¡Belay! esclamó Florinda alentando apenas.\"},{\"heading\":false,\"text\":\"Y aprovechando su sorpresa y su conmocion, Kaib se alejó.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Poco despues apareció á los rayos de la luna un hombre.\"},{\"heading\":false,\"text\":\"Florinda habia quedado inmóvil junto á la puerta de la torre.\"},{\"heading\":false,\"text\":\"Por un secreto instinto, al acercarse aquel hombre, le reconoció.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡Belay! ¡Belay! ¿á dónde vas? le dijo.\"},{\"heading\":false,\"text\":\"--¡Florinda! esclamó el jóven príncipe alentando apenas al escuchar la voz de su amada.\"},{\"heading\":false,\"text\":\"--Sí, yo soy.\"},{\"heading\":false,\"text\":\"--¿Qué haces aquí?\"},{\"heading\":false,\"text\":\"--¿A qué vienes tú?\"},{\"heading\":false,\"text\":\"--Vengo á penetrar en esta terrible torre; vengo á evocar al espíritu maldito que la habita: á preguntarle lo que debemos temer ó lo que podemos esperar. ¿Y cuando vengo aquí anhelando la salvacion de mi patria, te encuentro, Florinda, sola, junto á esta tremenda torre?...\"},{\"heading\":false,\"text\":\"--Yo no soy ya Florinda... tu Florinda, la que debia ser tu esposa... soy la manceba del rey don Rodrigo.\"},{\"heading\":false,\"text\":\"--¡Tú! gritó Belay exhalando su corazon hecho pedazos en su grito: ¡tú, la manceba del rey!\"},{\"heading\":false,\"text\":\"--¡Dios lo quiere!\"},{\"heading\":false,\"text\":\"--¡Que Dios quiere que tú mancilles la honra de tus abuelos! esclamó Belay: ¡esa es una horrible blasfemia! ¡tú estás loca, Florinda!\"},{\"heading\":false,\"text\":\"Florinda aceptaba su destino de una manera heróica: amaba á Belay, y por lo mismo queria apartarle de ella: aborrecia de muerte al rey, y por lo mismo queria unirse á él.\"},{\"heading\":false,\"text\":\"¿No la habia dicho aquel terrible jorobado de piedra, que el hombre que pusiese sobre ella sus manos impuras, mientras tuviese pendiente de su cuello el amuleto de Salomon, perderia su cuerpo y su alma?\"},{\"heading\":false,\"text\":\"Florinda, por vengarse, queria buscar al rey; embriagarle con sus amores; ser su manceba; ser, en fin, para él un doble tósigo para su cuerpo y para su alma: el cuerpo ensangrentado: el alma condenada.\"},{\"heading\":false,\"text\":\"--Yo amo al rey, dijo con voz lánguida Florinda.\"},{\"heading\":false,\"text\":\"--¿Y así olvidas tus promesas, mi amor, mi vida?\"},{\"heading\":false,\"text\":\"--Ama á otra hermosura.\"},{\"heading\":false,\"text\":\"--¡Ah Florinda! ¡Florinda! ¡tú estás loca!\"},{\"heading\":false,\"text\":\"--¡No, no! ¡recuerda bien! ¡esta noche!...\"},{\"heading\":false,\"text\":\"--¡Ah! ¡esta noche!...\"},{\"heading\":false,\"text\":\"--El rey vino á mi castillo.\"},{\"heading\":false,\"text\":\"--Es verdad.\"},{\"heading\":false,\"text\":\"--El rey pretendió que yo le sirviese la copa.\"},{\"heading\":false,\"text\":\"--Es verdad.\"},{\"heading\":false,\"text\":\"--Tú quisiste oponerte á que yo quedase sola con el rey.\"},{\"heading\":false,\"text\":\"--Sí, sí, es verdad.\"},{\"heading\":false,\"text\":\"--Pues bien; yo habia llamado al rey.\"},{\"heading\":false,\"text\":\"--¡Tú!\"},{\"heading\":false,\"text\":\"--Sí, yo. Yo que le serví la copa de mis amores.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡maldita seas tú, muger, que has herido de un solo golpe la honra del padre y el corazon del amante!\"},{\"heading\":false,\"text\":\"Y fuera de sí se volvió á la puerta de la torre, se arrojó contra ella y la golpeó con las manos.\"},{\"heading\":false,\"text\":\"La puerta se abrió y Belay se precipitó dentro.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Cuando salió empezaba á amanecer.\"},{\"heading\":false,\"text\":\"La frente de Belay se mostraba radiante de valor.\"},{\"heading\":false,\"text\":\"--¡Que la causa de su pérdida es Florinda! esclamó con acento profundo: ¡que su padre el conde don Julian será traidor, que los árabes vencerán á los godos, y que yo, yo, Belay, duque de Cantábria seré el primer rey de otro árbol de reyes! ¡Oh! ¡hagamos callar nuestro corazon; ahoguemos en él la voz de nuestro amor y de nuestros celos; la patria necesita nuestro brazo, y nuestro amor es todo entero de la patria!\"},{\"heading\":false,\"text\":\"El generoso mancebo se encaminó á Toledo.\"},{\"heading\":false,\"text\":\"En aquellos momentos, Florinda engalanada como una reina, y sonriendo de amor, entraba en la cámara de don Rodrigo, y se arrojaba entre sus brazos.\"},{\"heading\":false,\"text\":\"Kaib galopaba sobre un potro negro, atravesando la España para ir á llevar al gobernador de Tanja, al conde don Julian, la carta en que Florinda le avisaba de su deshonra.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"El sol habia descendido y aparecido ocho veces desde que Kaib habia partido con la carta.\"},{\"heading\":false,\"text\":\"Habia llegado al monte Calpe, á la ribera del estrecho de Alzacac, y habia entrado en una nave de mercaderes para trasladarse á Tanja.\"},{\"heading\":false,\"text\":\"Muy pronto la nave se acercó á las riberas de Africa.\"},{\"heading\":false,\"text\":\"Al lejos, Kaib inmóvil y de pié sobre la proa, vió en el horizonte de un mar abrillantado por los rayos del sol, una ciudad agarena, cuyos altos minaretes parecian desafiar á las tempestades.\"},{\"heading\":false,\"text\":\"Aquella ciudad era Tanja.\"},{\"heading\":false,\"text\":\"Fuera de los muros, junto á la espuma de las aguas, se veian levantadas algunas tiendas: multitud de árabes á caballo armados de lanzas, caracoleaban al rededor de las tiendas, ejercitándose en sus armas, como soldados que se disponen á una empresa cercana.\"},{\"heading\":false,\"text\":\"Mas próxima al mar que las otras, habia una tienda, sobre la cual ondeaba un pendon de seda roja y verde; á la puerta de esta tienda dos hombres paseaban amigablemente y miraban al mar, en cuyo lejano horizonte aparecia un punto negro.\"},{\"heading\":false,\"text\":\"Aquel punto negro era la nave que conducia á Kaib.\"},{\"heading\":false,\"text\":\"La edad de los hombres que paseaban delante de la tienda, parecia ser la de cincuenta años. Los dos mostraban en su semblante el sello de dominio que la costumbre del mando imprime en los caudillos.\"},{\"heading\":false,\"text\":\"El uno llevaba el capacete de oro y la clámide de púrpura de los nobles godos; su semblante pálido y triste parecia reflejar el presentimiento de una gran desgracia, y su paso era lento, grave y magestuoso.\"},{\"heading\":false,\"text\":\"El otro hombre que con él paseaba, era un árabe hijo de Damasco, cuya frente atezada, estaba cubierta por una toca roja y verde: causaba terror la mirada incontrastable, salvaje, cruel, de sus ojos negros como el ébano; vestia un alquicel blanco, un caftan rojo, y una lóriga de guerra; en su ancha faja de Persia escondia un corvo puñal, y sujetaba una larga espada con empuñadura de hierro.\"},{\"heading\":false,\"text\":\"Este árabe era Muza-ebn-Nosir, vasallo del califa Walid y conquistador del Magreb, hasta la Mauritania Tingitana.\"},{\"heading\":false,\"text\":\"Muza y el conde don Julian hablaban de gravísimos asuntos.\"},{\"heading\":false,\"text\":\"--Inútil es cuanto te esfuerzes, emir, en convencerme á que haga traicion á mi rey, decia el conde. Por él tengo el gobierno de la Mauritania Tingitana, y la defenderé á todo poder contra tí y contra todos los que enviare el califa tu señor. No me pidas que te abra las puertas de mi patria, que no vengo de raza de traidores, ni hay oro bastante en el mundo para obligarme á ser traidor.\"},{\"heading\":false,\"text\":\"--Nobles y leales son tus palabras, conde, y leal y noble eres, y es por cierto grande lástima que tan buen caballero sirva á un rey tan tirano como don Rodrigo.\"},{\"heading\":false,\"text\":\"--El reino le castigará como á Witiza y pondrá otro rey en su lugar, dijo el conde, si necesario fuese: por lo mismo, si yo te he recibido de paz, es porque de paz has venido, y porque yo siempre tenderé mi mano á los prudentes y á los esforzados.\"},{\"heading\":false,\"text\":\"Muza no insistió al ver la firmeza del conde, pero no dejó de mirar con anhelo, y sin saber por qué causa, á la nave que conducia á Kaib.\"},{\"heading\":false,\"text\":\"Durante algun tiempo el godo y el árabe continuaron paseando y hablando de sus respectivas patrias, señalando y ponderando cada uno las escelencias de la suya, como si hubieran sido los amigos mas grandes del mundo.\"},{\"heading\":false,\"text\":\"Entre tanto la nave habia llegado á la ribera y de ella habia saltado en tierra Kaib, que al ver á su señor corrió hácia él.\"},{\"heading\":false,\"text\":\"Una palidez sombría cubrió las megillas de don Julian al ver la precipitacion con que se acercaba á él uno de sus esclavos que habia reconocido.\"},{\"heading\":false,\"text\":\"Kaib no tardó en arrojarse á los pies de su señor.\"},{\"heading\":false,\"text\":\"--¿Qué nuevas me traes? dijo alentando apenas el conde don Julian.\"},{\"heading\":false,\"text\":\"--Esta carta de tu hija te las revelará, señor, dijo Kaib sacando del seno el pergamino que le habia encomendado Florinda y entregándolo al conde don Julian.\"},{\"heading\":false,\"text\":\"Este rompió los sellos y leyó.\"},{\"heading\":false,\"text\":\"--¡Oh! ¿que es esto, Dios, poderoso Dios? dijo el conde dejando caer el pergamino apenas le hubo leido, y llevándose las manos á la cabeza como si hubiese temido que se le escapase.\"},{\"heading\":false,\"text\":\"Muza recogió el pergamino, pasó la vista por la escritura, y luego, sonriendo con un gozo cruel, leyó en voz alta el contenido.\"},{\"heading\":false,\"text\":\"Decia así:\"},{\"heading\":false,\"text\":\"«Padre: la cólera de Dios ha caido sobre nuestras cabezas.\"},{\"heading\":false,\"text\":\"»El destino se cumple y la muerte acecha.\"},{\"heading\":false,\"text\":\"»Nuestro hogar ha sido profanado.\"},{\"heading\":false,\"text\":\"»El infame rey don Rodrigo ha mancillado, valiéndose de malas artes, la pureza de tu hija.\"},{\"heading\":false,\"text\":\"»Tu Florinda está deshonrada y morirá de vergüenza.\"},{\"heading\":false,\"text\":\"»Padre: desnuda tu espada, desnúdala y venga á tu hija.»\"},{\"heading\":false,\"text\":\"Mientras el árabe leia, los ojos de Kaib se inyectaban de sangre.\"},{\"heading\":false,\"text\":\"Al fin esclamó con una voz semejante á un rugido y como si hubiese ignorado lo que contenia la carta.\"},{\"heading\":false,\"text\":\"--Mientes tú, perro infiel; es imposible que esa carta diga lo que tú supones que dice.\"},{\"heading\":false,\"text\":\"Al verse insultado el soberbio Muza de tal modo por un esclavo, una palidez de muerte cubrió su semblante y desnudó trasportado de cólera su puñal.\"},{\"heading\":false,\"text\":\"Kaib no tuvo tiempo de huir ni de defenderse; el árabe le habia herido de una puñalada.\"},{\"heading\":false,\"text\":\"Kaib cayó murmurando:\"},{\"heading\":false,\"text\":\"--Estaba escrito.\"},{\"heading\":false,\"text\":\"Y espiró.\"},{\"heading\":false,\"text\":\"--¡Oh! ¿que es esto? dijo don Julian volviendo en sí.\"},{\"heading\":false,\"text\":\"--Esto es, dijo Muza mostrándole la carta, tu hija deshonrada y tu esclavo muerto.\"},{\"heading\":false,\"text\":\"El conde don Julian arrebató el pergamino á Muza y se alejó frenético.\"},{\"heading\":false,\"text\":\"El emir entró en su tienda murmurando.\"},{\"heading\":false,\"text\":\"--Lo que no han hecho la ambicion ni el oro, lo hace la venganza, Gecira-Alandalus será esclava del Islam.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Pocos dias despues el conde don Julian decia á Muza en un aposento de su palacio de Tanja:\"},{\"heading\":false,\"text\":\"--¡Emir de Africa! ¡caudillo del poderoso Walid, reune tus soldados! yo te abro las puertas de Tanja; yo te doy los galeones de los godos! ¡emir del poderoso Walid! ¡pisa las playas de España! ¡adelante, al galope de los caballos de tus feroces árabes! ¡yo voy contigo! ¡yo que voy por la cabeza de don Rodrigo!\"},{\"heading\":false,\"text\":\"Muza sonrió de una manera horrible y esclamó:\"},{\"heading\":false,\"text\":\"--¡Estaba escrito! ¡lo que no pudo hacer la ambicion lo hace la venganza!\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Algunos dias despues un ejército árabe pasaba en cien galeones el estrecho y pisaba las playas de la Bética.\"},{\"heading\":false,\"text\":\"Antes el walí Tarik-ebn-Zyad, con una caballería escogida, habia pasado en cuatro grandes barcos de Tanja á Sebta y de Sebta á Andalucía con éxito venturoso.\"},{\"heading\":false,\"text\":\"Tarik habia devastado algunas comarcas de la Bética y habia avisado á Muza de que podia pasar con su ejército.\"},{\"heading\":false,\"text\":\"Cuando el príncipe godo Tadmir[54] supo esta invasion: escribió á don Rodrigo la carta siguiente:\"},{\"heading\":false,\"text\":\"«Señor: aquí han llegado gentes enemigas de la parte de Africa, yo no sé si del cielo ó de la tierra; yo me hallé acometido de ellos de improviso, resistí con todas mis fuerzas para defender la entrada, pero me fué forzoso ceder á la muchedumbre y al ímpetu suyo: ahora, á mi pesar, acampan en nuestra tierra. Ruégote, señor, pues tanto te cumple, que vengas á socorrernos con la mayor diligencia y con cuanta gente se pueda allegar; ven tú, señor, en persona, que será lo mejor.»\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"El espanto cundió entre los godos, y el rey don Rodrigo se levantó aterrado de entre los brazos de Florinda, donde le sorprendió la noticia.\"},{\"heading\":false,\"text\":\"El sangriento vaticinio de la horrible torre empezaba á cumplirse.\"},{\"heading\":false,\"text\":\"La corona de los godos y la cabeza de don Rodrigo estaban amenazadas.\"},{\"heading\":false,\"text\":\"Don Oppas veia con placer acercarse el dia en que fuese derrocado el enemigo de Witiza.\"},{\"heading\":false,\"text\":\"Los hijos de aquel rey gozaban ya con su venganza.\"},{\"heading\":false,\"text\":\"Florinda miraba ya próximo el momento en que el infame tirano caeria ensangrentado á los pies del conde don Julian.\"},{\"heading\":false,\"text\":\"Don Rodrigo, reuniendo cuantas gentes pudo, partió para la Bética y llegó con un innumerable ejército á Sidonia.\"},{\"heading\":false,\"text\":\"Tarik, la valiente espada del Islam, le salió al encuentro.\"},{\"heading\":false,\"text\":\"El trono de los godos cayó por tierra en la batalla de Wad-al-Lette[55].\"},{\"heading\":false,\"text\":\"Don Rodrigo cayó muerto á manos de Tarik.\"},{\"heading\":false,\"text\":\"El traidor don Julian cayó tambien horrorizado de haber vendido á su patria por lavar su honor.\"},{\"heading\":false,\"text\":\"Pero Florinda estaba vengada.\"},{\"heading\":false,\"text\":\"Los árabes, por haber sido ella la causa de la pérdida de un reino, la llamaron la Kaba[56].\"},{\"heading\":false,\"text\":\"Los árabes siguieron adelante en su triunfo, y la bandera del Islam tremoló sobre Toledo.\"},{\"heading\":false,\"text\":\"Solo quedaron algunos godos reunidos por Belay en las montañas de Asturias, sin rendir homenaje á los vencedores.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Las gentes de Damasco vinieron á buscar la tierra fértil de Gecira-Alandalus, y se dirigieron á la Bética, y en ella buscaron á Iliberis.\"},{\"heading\":false,\"text\":\"Porque así estaba escrito.\"},{\"heading\":false,\"text\":\"Y quiso Dios que cuando asomaron, viniendo de la parte de las marinas por la cumbre de un monte, á cuyo pie tiempo adelante se levantó la villa de Al-Padul, voló el arcángel de la vida y de la alegría con sus alas de oro y su flotante túnica celeste recamada de estrellas, sobre la tierra árida y seca de Iliberis y disipó los vapores que la cubrian, y dijo con una voz dulce y sonora como el murmurio de las auras entre las flores.\"},{\"heading\":false,\"text\":\"«Vuelve á ser lo que eras, tierra maldita, antes de la impiedad de tus antiguos moradores.\"},{\"heading\":false,\"text\":\"»Cúbrete de praderas y de fuentes, de bosques y de sotos.\"},{\"heading\":false,\"text\":\"Alégrate animal viviente y ave voladora.\"},{\"heading\":false,\"text\":\"Y cúbranse tus sierras de nieve.\"},{\"heading\":false,\"text\":\"Y tus montes de verdura.\"},{\"heading\":false,\"text\":\"Y muéstrate riente y engalanada bajo tu cielo azul.\"},{\"heading\":false,\"text\":\"Porque Dios te bendice para que seas el paraiso de su pueblo.\"},{\"heading\":false,\"text\":\"Pero quede en tí la señal de su maldicion, como recuerdo de una historia pasada.\"},{\"heading\":false,\"text\":\"Y que la parda sierra donde es Iliberis, no produzca ni yerba ni fruto.\"},{\"heading\":false,\"text\":\"Ni de asilo sirva á ave ni á fiera, sino á inmundo reptil y á vívora ponzoñosa.»\"},{\"heading\":false,\"text\":\"Y dicho esto, el ángel batió su ligera y dorada pluma.\"},{\"heading\":false,\"text\":\"Y se deshizo en lluvia de flores y aromas.\"},{\"heading\":false,\"text\":\"Y se alegró el cielo y regocijóse la tierra.\"},{\"heading\":false,\"text\":\"Brotaron las fuentes de las alturas y corrieron los rios.\"},{\"heading\":false,\"text\":\"Y columpiáronse las auras en las verdes frondas de las arboledas.\"},{\"heading\":false,\"text\":\"Y cantaron los pájaros.\"},{\"heading\":false,\"text\":\"Y balaron las ovejas en los altozanos.\"},{\"heading\":false,\"text\":\"Pero allá en el confin opuesto á Geb-el-Solair quedó la sierra de Iliberis infecunda y triste, despoblada de gentes y de animales y desnudas de verdor sus ásperas crestas, entre cuyas grietas asomaba su amarillenta luz el fuego de los volcanes.\"},{\"heading\":false,\"text\":\"Y cuando los de Damasco llegaron á la cumbre del alto del Padul, se creyeron trasladados á un jardin de delicias.\"},{\"heading\":false,\"text\":\"Y fijaron sus ojos asombrados en el monte de la Alcazaba, y en la Colina Roja y en la villa de los judíos.\"},{\"heading\":false,\"text\":\"Y al ver los castillos sobre los montes, al pié de otros montes mas altos.\"},{\"heading\":false,\"text\":\"Y la corona de nieve de la sierra.\"},{\"heading\":false,\"text\":\"Y la estendida alfombra de verdura de la vega, esclamaron:\"},{\"heading\":false,\"text\":\"--¡Allah Kuakbar[57] este es el Jardin-de-Delicias.\"},{\"heading\":false,\"text\":\"Y la ciudad de los castillos sobre los montes Al-Garb-Nat[58].\"},{\"heading\":false,\"text\":\"Y llamaron desde entonces á la Alcazaba, y á la Colina, y á la villa, Garbnat.\"},{\"heading\":false,\"text\":\"Y las ocuparon y edificaron en ellas sobre las ruinas romanas torres y muros y una aljama á Dios dentro de los muros y defendida por las torres.\"},{\"heading\":false,\"text\":\"Y llamaron al monte de Iliberis Gebel-Elveira,[59] á causa de su esterilidad.\"},{\"heading\":false,\"text\":\"Y llamaron al castillo antiguo que encontraron Hins-al-Roman[60].\"},{\"heading\":false,\"text\":\"Y construyeron frente á él, al otro lado de la fortaleza, otro que se llama hoy alcazaba Cadima.\"},{\"heading\":false,\"text\":\"Y labraron esta alcazaba el año 148 de la Egira, en tiempos de Ased-ebn-Abd-el-Rajman-el-Schevaní, primer walí de Granada.\"},{\"heading\":false,\"text\":\"Nadab, á la llegada de aquellas gentes estrangeras, escondió mas á Yémina, trasladándola á una escabacion abierta en la cisterna de la Colina Roja, receloso de aquellas tribus de oriente que con las lanzas teñidas aun en la sangre de los godos, avanzaban á la carrera de sus caballos de Africa, en direccion á las montañas.\"},{\"heading\":false,\"text\":\"Y Ased-el-Schevaní era un sirio feroz, que, mancebo aun, habia venido con el caudillo Ocba-ebn-Nafe-el-Farih, sobre las tierras del Magreb, y habia ensangrentado su caballo hasta las cinchas en sangre berberisca treinta y cinco años antes de la conquista de España por los árabes.\"},{\"heading\":false,\"text\":\"Y así es que, al tiempo en que los de Damasco allegaron á las tierras de Granada, las nieblas del invierno y el sol del estío habian pasado ochenta veces sobre su cabeza.\"},{\"heading\":false,\"text\":\"Y era su barba blanca y su tez roja.\"},{\"heading\":false,\"text\":\"Y mostraba gran cuerpo y fuerza á pesar de sus muchos años.\"},{\"heading\":false,\"text\":\"Y era respetado por sabio y por valiente entre los mas doctos y esforzados de su tribu.\"},{\"heading\":false,\"text\":\"Nunca habia tenido mugeres, ni habia amado.\"},{\"heading\":false,\"text\":\"Ased-el-Schevaní decia que el amor era una enfermedad del espíritu, y la muger el demonio tentador que Allah ha arrojado sobre el camino del hombre para hacerle débil y apartarle de toda fuerza y merecimiento.\"},{\"heading\":false,\"text\":\"Pero como el amor es ley invencible, yugo inevitable, luz del cielo sin la cual el hombre seria una fiera, y la muger la antorcha de oro y perlas donde ha puesto Dios el resplandor de su hermosura, estaba escrito que Ased-el-Schevaní habia de arder alguna vez en su fuego.\"},{\"heading\":false,\"text\":\"Y ardió; pero de una manera voraz, insensata.\"},{\"heading\":false,\"text\":\"Hasta el punto de consumir en aquel fuego su corazon, y bajar á la tumba débil, desesperado y loco.\"},{\"heading\":false,\"text\":\"Y sucedió así.\"},{\"heading\":false,\"text\":\"Sobre la cumbre del monte fronterizo á la Colina Roja, los de Damasco, huyendo de la esterilidad de Elvira, buscando aires puros y aguas saludables, tierra fértil y pabellones de verdura; habian levantado la torre que hoy se vé ruinosa cerca de la plaza de Bib-al-Bonut, mirando al cerro donde mas tarde se levantó la torre del Aceituno[61].\"},{\"heading\":false,\"text\":\"En aquella torre, labrada por cautivos cristianos, moraba el walí de Granada, y desde ella veia, durante el dia, levantarse lentamente las fuertes murallas de la Alcazaba Cadima y vigilaba las Torres-Bermejas, y se dejaba caer desde ella sobre los enemigos de su tierra, que en medio de las disensiones que habian empezado á arder entre los hijos del Islam, apenas conquistada España, corrian sus fronteras en algaras devastadoras, y pretendian encender la guerra civil, que mas tarde debia arrancar la España del dominio de los califas de oriente.\"},{\"heading\":false,\"text\":\"Velaba una noche Ased-el-Schevaní.\"},{\"heading\":false,\"text\":\"Apoyado en las almenas de su fuerte morada, contemplaba al lejos la altísima sierra ostentando su cándido velo de nieve á los rayos de la luna, y la Vega, dormida bajo el dulce reflejo, y silencioso todo en torno como si el genio del sueño hubiera batido sus blancas alas sobre Granada.\"},{\"heading\":false,\"text\":\"Recordaba Ased-el-Schevaní el apacible cielo de la Siria, sus fértiles campos; la luna, alumbrando blandamente las cúpulas y los almenares de la soberbia Jerusalem, su patria; suspiraba en su orgullo de guerrero porque no veia ante sí otras torres y otros muros semejantes en que la luna quebrase sus rayos, y el viento sus alas, y la sombra su manto de oscuridad.\"},{\"heading\":false,\"text\":\"Y parecióle cuando esto pensaba que en la cumbre de la Colina Roja se levantaba tromba de niebla, y que la niebla se condensaba y tomaba formas de muros y torres, que mostraban tras sus ajimeces luces y sombras, regocijo de zambra y ecos de armonía.\"},{\"heading\":false,\"text\":\"Creyó ver ginetear al rededor de aquel castillo, sobre la pelada vertiente de la colina hasta el lecho del rio, multitud de caballeros que parecian vagar en los aires como sombras, y esconderse en oscuras grietas como reptiles; parecióle que una aureola de luz coronaba aquel alcázar de los sueños, y de las hadas, y de los encantados, y llamó á su katib[62], que dormia en su aposento sobre una piel de camello.\"},{\"heading\":false,\"text\":\"--¿No ves Aruhm, le dijo, una corona de perlas y rubíes sobre la cabeza de aquel monte? parece que un manto de oro y resplandores se ha estendido sobre él, y que las hadas del quinto cielo han descendido á la tierra en una fiesta del Edem.\"},{\"heading\":false,\"text\":\"El viejo Aruhm se frotó los ojos y nada vió.\"},{\"heading\":false,\"text\":\"Porque estaba escrito que solo los señores de Granada alcanzarian á ver con sus ojos de hombre el Palacio-de-Rubíes.\"},{\"heading\":false,\"text\":\"--Yo nada veo, señor, contestó el katib; sino las ruinas del templo romano y una opaca luz que brilla entre sus pórticos destrozados.\"},{\"heading\":false,\"text\":\"Y así era la verdad: velando entre las ruinas, el sabio Nadab pronunciaba el conjuro que hacia ver á Ased-el-Schevaní aquellas maravillas.\"},{\"heading\":false,\"text\":\"Porque Nadab necesitaba atraer á la Colina Roja y á la cisterna donde estaba escondida Yémina á Ased-el-Schevaní.\"},{\"heading\":false,\"text\":\"Este comprendió al fin que en la vision perenne ante sus ojos se encerraba un misterio; despidió ágriamente á Aruhm, y tomando su alquicel, su arco y su aljaba, salió con recato de la torre, bajó el repecho de la Alcazaba, atravesó el rio sobre un puente romano, y empezó á trepar por la vertiente de la Colina Roja.\"},{\"heading\":false,\"text\":\"Cuando salió del bosque que la rodeaba y miró á su cumbre, nada vió: la Colina solitaria solo mostraba las ruinas, la torre y los anchos brocales de la cisterna.\"},{\"heading\":false,\"text\":\"Pero Ased-el-Schevaní andaba impulsado por el destino, y avanzó hasta la cumbre; parecióle escuchar un dulce y perdido canto de muger en las profundidades de la cisterna, y cuando puso el pié sobre el brocal mas inmediato, sintió sobre su cabeza un ruido sordo y ténue, semejante al que produce una tienda de seda que se despliega; brilló en sus ojos un resplandor vivísimo; alhagó sus oidos una música armoniosa sobre todas las armonías, aspiró un ambiente saturado de perfumes, y lánguidas y frescas brisas agitaron su barba y el flotante estremo de su toca.\"},{\"heading\":false,\"text\":\"El invisible Palacio-de-Rubíes se habia levantado en torno suyo con todo su esplendor oriental, pero mas bello, mas delicado, mas rico, que cuantos alcázares habia visto hasta entonces el Schevaní.\"},{\"heading\":false,\"text\":\"Aquel maravilloso palacio parecia ser una profecía de lo que con el tiempo serian los alcázares de la Alhambra, y el walí contemplaba absorto sus jardines, sus galerías, sus retretes, con todas sus galas, sus labores de oro, sus leyendas de amor y su voluptuosidad, y escuchaba con delicia sus blandos é incitantes rumores, que parecian emanar de huríes invisibles.\"},{\"heading\":false,\"text\":\"Ased-el-Schevaní, absorto de admiracion, avanzó por aquellos encantados ámbitos precedido de hermosas mugeres que bailaban la zambra al son de guzlas de marfil, y rodeado de silenciosos esclavos y seguido de feroces guerreros.\"},{\"heading\":false,\"text\":\"--¡Oh señor Allah! esclamó Ased-el-Schevaní: ¿qué alcázar de luz es este que guarda tantas maravillas, sino es el jardin de Hiram que ve en sueños el justo cuando atraviesa el desierto en su peregrinacion á la santa ciudad?[63] Yo le he visto una vez, señor, y no era tan fresco, ni tan sonoro como este, ni eran sus flores tan bellas, ni sus aguas tan claras, ni sus retretes tan magníficos. ¡Oh, señor Allah! ¿Qué quieres de tu siervo el Schevaní?\"},{\"heading\":false,\"text\":\"Calló el anciano porque cerca de él, á través de un arco primorosamente calado, escuchó unas voces juveniles que le nombraban departiendo alegremente.\"},{\"heading\":false,\"text\":\"--Sí, hermanas mias, decia una de ellas, Ased-el-Schevaní es un leopardo de Africa que siempre ha resistido á los alhagos del amor.\"},{\"heading\":false,\"text\":\"--Pero no resistirá á los encantos de la hermosura de Yémina, repuso otra de ellas.\"},{\"heading\":false,\"text\":\"--Ni á los filtros de su padre Nadab, añadió una tercera.\"},{\"heading\":false,\"text\":\"--Ni á las locuras de su ambicion, dijo otra.\"},{\"heading\":false,\"text\":\"--Os engañais, repuso la primera que habia hablado, escuchándonos está y no llega, porque aborrece á la muger.\"},{\"heading\":false,\"text\":\"--Por la muger enloquecerá.\"},{\"heading\":false,\"text\":\"--No.\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"Y aquellas mugeres, que con voz tan incitante hablaban, aparecieron de repente ante el Schevaní.\"},{\"heading\":false,\"text\":\"Plegó el árabe su poblado y cano entrecejo al ver ante sí una turba de muchachas de ojos negros, vestidas de blanco y coronadas de flores, que le sonreian y le provocaban bailando voluptuosamente en torno suyo, y envolviéndole en deleites que nunca habia sentido.\"},{\"heading\":false,\"text\":\"Pero en vano quiso luchar; dominóle tanta fascinacion, y cayó desvanecido sobre un divan.\"},{\"heading\":false,\"text\":\"--¡Guala![64] dijo vencido enteramente estendiéndose con molicie sobre el divan: ¡guala! he sido un necio en dejar correr mi vida sin buscar el amor.\"},{\"heading\":false,\"text\":\"Y cayó en un sueño dulce, ardiente y lleno de encantos, de alegría y de felicidad.\"},{\"heading\":false,\"text\":\"Cuando despertó, miró en torno suyo y se creyó encerrado en una prision; era el ambiente húmedo, los muros tristes, profundas las grietas donde arraigaban plantas parásitas, y sobre altos pilares romanos, en la cóncava y oscura bóveda, á través de la cual, contínuas infiltraciones dejaban caer sobre el pavimento, anchas gotas de agua, que producian un ruido monótono y solemne sobre los turbios charcos corrompidos, en cuyo fondo se revolvian reptiles acuáticos; en la oscura bóveda, repetimos, parecian vagar fantasmas sombríos.\"},{\"heading\":false,\"text\":\"Sintió por la primera vez el feroz Ased-el-Schevaní pavor en el corazon; sus dientes se entrechocaron de frio, y sintió comprimida su alma por una angustia desconocida para él.\"},{\"heading\":false,\"text\":\"--¡Por Allah, dijo estremeciéndose, que mis enemigos se han valido de malas artes para encantarme y estoy en poder de Eblís!\"},{\"heading\":false,\"text\":\"--No, dijo una voz dulcísima resonando en la oscuridad: no; sino en poder del amor.\"},{\"heading\":false,\"text\":\"--¡Amor! esclamó el wali con desden, y ¿qué es el amor para mí, espada del Islam, que hé vencido al desierto su espalda de arenales y hecho mis abluciones con sangre de enemigos?\"},{\"heading\":false,\"text\":\"--¡Recuerda! dijo otra voz.\"},{\"heading\":false,\"text\":\"El árabe tembló: por primera vez sentia el remordimiento delante de un recuerdo terrible.\"},{\"heading\":false,\"text\":\"--Aun brota sangre la tumba de la desdichada hija del conde don Julian, repitió la voz.\"},{\"heading\":false,\"text\":\"El árabe irguió la cabeza.\"},{\"heading\":false,\"text\":\"--¡Era una vil ramera! gritó.\"},{\"heading\":false,\"text\":\"Entonces, y contestando al Schevaní, la voz cantó:\"},{\"heading\":false,\"text\":\"»Tres veces el sol ha trasmontado los horizontes de Gecira-Alandalus entre nubes rojas.\"},{\"heading\":false,\"text\":\"Tres veces vapor de sangre ha enrojecido mas a aquellas nubes.\"},{\"heading\":false,\"text\":\"Y el sol ha dorado tres veces las bravías frentes del árabe y del godo, cuyos brazos no han cesado de herir.\"},{\"heading\":false,\"text\":\"¿Qué ginete es aquel que se envuelve en la pelea?\"},{\"heading\":false,\"text\":\"Su caftan está ensangrentado y rompe entre los enemigos hiriendo en ellos con el asta de una bandera del Islam.\"},{\"heading\":false,\"text\":\"¡Avanza, Ased-el-Schevaní! ¡tus feroces siros te siguen!\"},{\"heading\":false,\"text\":\"¡Aprieta el hierro en tu mano, y desgarra los hijares de tu corcel!\"},{\"heading\":false,\"text\":\"¡Los árabes cejan, y la victoria empieza á batir sus alas sobre los godos!\"},{\"heading\":false,\"text\":\"¡Aprieta el hierro en tu mano, Schevaní!\"},{\"heading\":false,\"text\":\"¡Que los godos de vencedores se conviertan en vencidos!\"},{\"heading\":false,\"text\":\"¡Que no quede uno!\"},{\"heading\":false,\"text\":\"¡He allí á Tarik! ¡á Tarik el valiente, el del caballo negro y la sangrienta espada!\"},{\"heading\":false,\"text\":\"¡Tarik, el genio del combate!\"},{\"heading\":false,\"text\":\"¡Adelante, muslimes! ¡adelante!\"},{\"heading\":false,\"text\":\"Tarik ha enrojecido su espada en la sangre de don Rodrigo.\"},{\"heading\":false,\"text\":\"Del último rey de los godos.\"},{\"heading\":false,\"text\":\"El valiente Orelia ha huido asombrado con la muerte de su real ginete.\"},{\"heading\":false,\"text\":\"¡Un esfuerzo mas!\"},{\"heading\":false,\"text\":\"¡Los godos huyen!\"},{\"heading\":false,\"text\":\"El implacable Wad-al-Lette les cierra el paso ó los ahoga en sus ondas.\"},{\"heading\":false,\"text\":\"¡Un esfuerzo mas! ¡Gecira-Alandalus, es esclava del Islam!\"},{\"heading\":false,\"text\":\"Tarik el invencible, ha hollado la púrpura de los godos.\"},{\"heading\":false,\"text\":\"A sus pies, sobre una alfombra de cadáveres, revuelve tos ojos espirantes el infortunado don Rodrigo.\"},{\"heading\":false,\"text\":\"¡Enviad su cabeza al califa!\"},{\"heading\":false,\"text\":\"Una cabeza de rey es el mejor presente que puede enviarle un muslim.\"},{\"heading\":false,\"text\":\"¡Cortadla!\"},{\"heading\":false,\"text\":\"¿Por qué tú, Tarik, tan valiente y tan fiero, no cercenas la cabeza de tu enemigo?\"},{\"heading\":false,\"text\":\"Tú no eres verdugo.\"},{\"heading\":false,\"text\":\"Pero hé allí á Ased-el-Schevaní.\"},{\"heading\":false,\"text\":\"Ased-el-Schevaní; el leopardo de oriente insaciable de sangre.\"},{\"heading\":false,\"text\":\"El hombre cuya amada es la muerte y cuyo mejor alcázar es el campo de la pelea.\"},{\"heading\":false,\"text\":\"¡Hélo que llega!\"},{\"heading\":false,\"text\":\"¡Oh! el yatagan de Ased-el-Schevaní, se ha teñido en la sangre del moribundo don Rodrigo, y su siniestra mano muestra entre un círculo de guerreros horrorizados, la cabeza de un rey sin fortuna.\"},{\"heading\":false,\"text\":\"¡Paso al verdugo!\"},{\"heading\":false,\"text\":\"¡Paso á Ased-el-Schevaní!»\"},{\"heading\":false,\"text\":\"Y la voz que así cantaba, lanzó una estridente carcajada.\"},{\"heading\":false,\"text\":\"Y á impulsos del terror, la carne del walí se despegó de sus huesos.\"},{\"heading\":false,\"text\":\"Y la voz siguió su canto.\"},{\"heading\":false,\"text\":\"--«La luna brilla.\"},{\"heading\":false,\"text\":\"La tienda del árabe se eleva en la llanura.\"},{\"heading\":false,\"text\":\"Allá en los altos duerme una ciudad.\"},{\"heading\":false,\"text\":\"¡Corona de un imperio poderoso! ¡córte de cien reyes! ¡Tolaitola![65].\"},{\"heading\":false,\"text\":\"¡Cómo alzas tus robustas torres en medio de las brumas de las sombras y de las nieblas del Tajo!\"},{\"heading\":false,\"text\":\"Pero tu puerta de Zocodover se abre.\"},{\"heading\":false,\"text\":\"Una muger sale por ella, desciende al llano y llega á la tienda del árabe.\"},{\"heading\":false,\"text\":\"Es hermosa, pero está pálida y triste como una flor cortada de su tallo.\"},{\"heading\":false,\"text\":\"Con ella va su desventura.\"},{\"heading\":false,\"text\":\"Es Florinda, la infeliz hija del conde don Julian.\"},{\"heading\":false,\"text\":\"La Kaba de los árabes.\"},{\"heading\":false,\"text\":\"Su túnica está rasgada y cubierta de lodo.\"},{\"heading\":false,\"text\":\"Sus rubios cabellos destrenzados, flotan en torno de su semblante, en que aparece la terrible espresion de su locura.\"},{\"heading\":false,\"text\":\"Muchos dolores han pasado por ella.\"},{\"heading\":false,\"text\":\"Ha visto morir á su padre y á los suyos.\"},{\"heading\":false,\"text\":\"Está sola, sola en el mundo.\"},{\"heading\":false,\"text\":\"Sola con su deshonra y su desventura.\"},{\"heading\":false,\"text\":\"Y las mugeres árabes la siguen, arrojándola lodo y gritando:\"},{\"heading\":false,\"text\":\"¡Esa es la Kaba!\"},{\"heading\":false,\"text\":\"Una mano amiga ha abierto para ella las puertas de la ciudad.\"},{\"heading\":false,\"text\":\"Y la desventurada corre por el campo.\"},{\"heading\":false,\"text\":\"Corre y la luna alumbra su pálido semblante y los ecos nocturnos repiten sus insensatas carcajadas.\"},{\"heading\":false,\"text\":\"¡Ay de la gacela que huye!\"},{\"heading\":false,\"text\":\"El leopardo acecha.\"},{\"heading\":false,\"text\":\"Acecha sediento de sangre, y se estremece de placer al sentir los pasos de una nueva víctima que se acerca.\"},{\"heading\":false,\"text\":\"El tapiz de la tienda se abre.\"},{\"heading\":false,\"text\":\"Y Ased-el-Schevaní fija su sombría mirada en Florinda.\"},{\"heading\":false,\"text\":\"Y el hombre de hierro se estremece.\"},{\"heading\":false,\"text\":\"Porque aquella muger es muy hermosa, y su túnica descuidada, muestra su incitante desnudez.\"},{\"heading\":false,\"text\":\"¡Acuérdate, Ased-el-Schevaní!»\"},{\"heading\":false,\"text\":\"Cesó por un momento la voz que cantaba, como para dar tiempo á Ased-el-Schevaní de recoger sus recuerdos, y acreció su temblor y un sudor frio corrió á lo largo de su cuerpo, y fantasmas vengadoras tomaron formas para él en el oscuro fondo de la cisterna.\"},{\"heading\":false,\"text\":\"Recordó una noche de luna, en que, volviendo de Damasco con la cabeza del rey don Rodrigo canforada, dentro de una caja de sándalo, se detuvo á poca distancia de Toledo, para entrar en él ostentando clavado en el hierro de su lanza, el hediendo y miserable despojo.\"},{\"heading\":false,\"text\":\"La luna brillaba.\"},{\"heading\":false,\"text\":\"Los árabes que acompañaban al Schevaní dormian junto á sus caballos.\"},{\"heading\":false,\"text\":\"Y él velaba.\"},{\"heading\":false,\"text\":\"Medió la noche y una sombra blanca y vaga adelantó entre las brumas, se acercó vacilante, y entró en la tienda del walí.\"},{\"heading\":false,\"text\":\"A la luz de la lámpara que la alumbraba, Ased-el-Schevaní vió una muger hermosísima, pálida é inmóvil delante de él.\"},{\"heading\":false,\"text\":\"Sus hombros y su seno, deslumbrantes de blancura, estaban desnudos, suelto el cabello de oro, y al rededor de su cuello se veia un collar de diamantes del cual pendia un amuleto.\"},{\"heading\":false,\"text\":\"Aquel amuleto era una manecita de ébano engastada en oro.\"},{\"heading\":false,\"text\":\"Era la mano mágica, símbolo del Islam, que pendia de la esmeralda cabalística de Salomon.\"},{\"heading\":false,\"text\":\"--Yo soy Florinda, dijo la hermosa acercándose al walí y mirándole con los ojos vagos y estraviados, yo soy un arcángel del sétimo cielo, castigado por Allah y convertido en muger.\"},{\"heading\":false,\"text\":\"La infeliz estaba en uno de sus momentos de locura.\"},{\"heading\":false,\"text\":\"--Mira: yo soy muy hermosa, dijo al Schevaní: por mí un pueblo ha venido sobre otro pueblo, y han corrido rios de sangre; por mí el pueblo de Ismael es señor de los godos de occidente, y ese pueblo me insulta porque dice que soy ramera.\"},{\"heading\":false,\"text\":\"--Y mienten, añadió Florinda, asiéndose estremecida á los hombros del Schevaní, mienten: yo soy vírgen, y mis hermanos los arcángeles vienen á acompañarme en mis sueños; pero mis piés están heridos por los abrojos y mi túnica desgarrada, y tengo hambre y frio.\"},{\"heading\":false,\"text\":\"Y la infeliz temblaba: una palidez mortal cubria con un velo terrible su semblante.\"},{\"heading\":false,\"text\":\"Y Ased-el-Schevaní no tuvo compasion de ella.\"},{\"heading\":false,\"text\":\"--¡Ah! la dijo: ¡tú eres Florinda! ¡la manceba de don Rodrigo!\"},{\"heading\":false,\"text\":\"Su horrible boca dejó ver en una feroz sonrisa sus blancos y agudos dientes de tigre.\"},{\"heading\":false,\"text\":\"--En verdad que es muy hermosa esta muchacha, murmuró sintiendo por primera vez un deseo amoroso. ¡Está loca! ¡la noche es solitaria! ¡mis guerreros duermen! ¡nadie podrá arrojarme á la cara una debilidad! ¡y luego!...\"},{\"heading\":false,\"text\":\"El Schevaní lanzó una sombría mirada á Florinda poniendo la mano en el pomo de su puñal.\"},{\"heading\":false,\"text\":\"Florinda le contemplaba con la curiosidad fria y vaga de los insensatos.\"},{\"heading\":false,\"text\":\"--Mira, le dijo: yo amo á un hombre y ese hombre es generoso, noble y valiente.\"},{\"heading\":false,\"text\":\"Yo guardo su nombre y su recuerdo en mi corazon, y temo que se me escape y quedar sola; sola, porque ese recuerdo me acompaña y duerme conmigo.\"},{\"heading\":false,\"text\":\"Déjame reclinarme en tu divan y guárdame, porque me persiguen.\"},{\"heading\":false,\"text\":\"Si mi amado estuviera aquí, él velaria mi sueño, porque me ama.\"},{\"heading\":false,\"text\":\"Los celos y la envidia irritaron al Schevaní al ver el amor que hácia otro hombre resplandecia en la mirada de la pobre loca.\"},{\"heading\":false,\"text\":\"--Tu amante es un cobarde, dijo, un perro traidor que te abandona en tu miseria.\"},{\"heading\":false,\"text\":\"--No, no es cobarde, dijo con voz dulce Florinda: ¡Si tú supieras su nombre!...\"},{\"heading\":false,\"text\":\"Y la desdichada miró en torno suyo con espanto, como el avaro que teme que le roben su tesoro.\"},{\"heading\":false,\"text\":\"Pero su mirada se tranquilizó: nadie habia que la escuchase, mas que Ased-el-Schevaní.\"},{\"heading\":false,\"text\":\"Florinda llevó al wali á un ángulo de la tienda.\"},{\"heading\":false,\"text\":\"--Mi amado es príncipe, le dijo: mi amado es hermoso como los arreboles de la tarde; mi amado conquistará palmo á palmo las tierras que ha conquistado en Gezira-Alandalus el Islam, y me vengará de los que me insultan llamándome ramera. ¡Ay del Islam ante la espada de Belay! el vendrá de Asturias como un vendabal y aportillará los muros de Tolaitola y pondrá los pendones de la cruz sobre sus almenas: entonces yo seré reina, pero no moriré como Aylat[66]. ¡Ay! ¡la mataron sin compasion estas gentes feroces! ¡la mataron sobre mi seno, y aun las negras manchas de su sangre están sobre mi túnica! ¡Defiéndeme tú, hasta que venga Belay, porque me van á matar como á Aylat!\"},{\"heading\":false,\"text\":\"Ased-el-Schevaní, palideció de cólera, irritóse su ojo voraz y un caliente hálito de sangre le embriagó: la crueldad rebosaba de su corazon, y tomó la caja de sándalo que guardaba la cabeza de don Rodrigo.\"},{\"heading\":false,\"text\":\"--Mira, la dijo: abriendo la caja y mostrándola la cabeza del rey: hé ahí la suerte que espera á tu Belay.\"},{\"heading\":false,\"text\":\"Florinda dió un grito: habia reconocido al rey en aquel sangriento despojo, y la habian horrorizado sus cabellos blancos manchados de negra sangre coagulada.\"},{\"heading\":false,\"text\":\"Por un momento desapareció su locura y miró á Ased-el-Schevaní á la luz de la razon.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡Eres tú, tú el verdugo!... ¡tú, el que yo ví en Tolaitola llevando en tu lanza la cabeza del rey! ¡tú, á quien desde aquel dia no he podido olvidar!... ¡Déjame huir de tí! ¡tu mano no se cansa de herir, ni tus ojos de mirar la muerte! ¡apártate de mi camino, porque tu mirada me hiela, y me das horror! ¡Mas horror que los árabes que me insultan y me llaman la Kaba!\"},{\"heading\":false,\"text\":\"--Florinda, amante de Belay, dijo Ased-el-Schevaní, dejando á un lado la caja que contenia la cabeza del rey don Rodrigo, y mirando con el gozo de la crueldad á la jóven: ¡oh! yo mancharé tu pureza y te enviaré deshonrada al hombre de tu amor. ¡Oh! ¡Belay! ¡el insensato que levanta aun una bandera cristiana delante del Koram y se atreve á llamarse rey de Gecira-Alandalus! ¡Oh! ¡y te tengo en mi poder! ¡y él te ama! pues bien; serás la esclava de mis esclavos, y dormirás en mis caballerizas entre los pies de mis corceles, junto á la jaula de mi pantera de Africa.\"},{\"heading\":false,\"text\":\"Y Ased-el-Schevaní, midió con una feroz ojeada á Florinda y se lanzó sobre ella.\"},{\"heading\":false,\"text\":\"Pero Florinda no retrocedió: un poder superior la protegia.\"},{\"heading\":false,\"text\":\"En vano el Schevaní pretendia llegar hasta ella.\"},{\"heading\":false,\"text\":\"Entonces sus ojos se inyectaron de sangre como los de un lobo rabioso, tomó una azagaya y la lanzó á la desdichada: la terrible arma se abrió paso á través de su seno, brotó de la herida un ancho surtidor de sangre, los ojos de Florinda se empañaron, y cayó murmurando entre su suspiro de agonía el nombre de Belay.\"},{\"heading\":false,\"text\":\"Una vez dado el primer paso de crueldad, el Schevaní no se contuvo; Florinda se revolvia sobre un lecho de sangre y el talisman se desprendió de su cuello.\"},{\"heading\":false,\"text\":\"El génio del horror y de la impureza se posó sobre la tienda del Schevaní, y Dios arrojó sobre ella su maldicion.\"},{\"heading\":false,\"text\":\"La Nat de los hebraizantes, la Florinda de los godos, la Kaba de los árabes, habia caido bajo su funesto horóscopo: sus miembros desgarrados fueron abandonados en el lugar que ocupaba la tienda, y el poderoso talisman recogido por Ased-el-Schevaní, habia aumentado el valor de su tesoro.\"},{\"heading\":false,\"text\":\"Ased-el-Schevaní no conocia la virtud de aquel poderoso talisman: le creia solo una alhaja de gran valor.\"},{\"heading\":false,\"text\":\"El Schevaní, despues de aquella noche, olvidó aquella historia de horror, y pidió al califa le concediese una tierra en Gecira-Alandalus para sus gentes de Damasco.\"},{\"heading\":false,\"text\":\"El califa le concedió la tierra de Iliberis.\"},{\"heading\":false,\"text\":\"Pero estaba escrito que seria castigado, y su crueldad con Florinda y su codicia en conservar como un rico despojo el amuleto que llevaba al cuello la jóven, fué la causa de su castigo.\"},{\"heading\":false,\"text\":\"Nadab, el padre de Yémina, sabia que el amuleto estaba en el tesoro de Ased-el-Schevaní; sabia que aquel amuleto tenia la virtud de defender de la impureza agena á la muger que lo llevase sobre sí, y quiso apoderarse de aquel talisman valiéndose para ello de la misma Yémina.\"},{\"heading\":false,\"text\":\"Para atraerle le habia hecho ver, valiéndose de sus conjuros, el encantado Palacio-de-Rubíes.\"},{\"heading\":false,\"text\":\"Ased-el-Schevaní estaba transido de horror.\"},{\"heading\":false,\"text\":\"Veia la macilenta cabeza del rey don Rodrigo y á Florinda, fria, impasible, pálida, ensangrentada, atormentándole con el recuerdo de su ser.\"},{\"heading\":false,\"text\":\"--Y ¡acuérdate! repetia la voz dulcísima que parecia venir de la bóveda de la cisterna, y en la cual creia recordar el árabe la dulce voz de Florinda.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡sí! ¡yo te amo Florinda! esclamó arrojándose por tierra el feroz walí.\"},{\"heading\":false,\"text\":\"--¿Por qué dijiste, pues, contestó con sarcasmo la voz, que no conocias el amor?\"},{\"heading\":false,\"text\":\"-¡Oh! ¡piedad! ¡piedad, Florinda! esclamó el walí: ó haz que lo que ha\"},{\"heading\":false,\"text\":\"LETRE dibº y litº Lit de J.J.MARTINEZ, Madrid.]\"},{\"heading\":false,\"text\":\"sucedido sea un sueño, ó quita de delante de mis ojos esta terrible vision que me atormenta.\"},{\"heading\":false,\"text\":\"Y como si aquella voz solo hubiese resonado para despertar los remordimientos en el alma de Ased-el-Schevaní, quedó la cisterna muda y oscura; desaparecieron los fantasmas, y Ased-el-Schevaní se atrevió á adelantar buscando la salida.\"},{\"heading\":false,\"text\":\"Entre las sombrías penumbras, encontró una puerta y entró en una cámara tan rica y tan bella como las del Palacio-de-Rubíes, alumbrada por una lámpara, á cuya luz se veia dormida sobre un lecho una muger.\"},{\"heading\":false,\"text\":\"Era Yémina.\"},{\"heading\":false,\"text\":\"Al verla el viejo y feroz walí tembló.\"},{\"heading\":false,\"text\":\"Creyó ver ante sí á Florinda, pero radiante de hermosura, sonriente de felicidad; la jóven despertó y fijó de una manera intensa la mirada de sus grandes ojos celestes en el walí.\"},{\"heading\":false,\"text\":\"--Tú eres Ased-el-Schevaní, dijo la jóven sin levantar la cabeza del almohadon donde la tenia reclinada.\"},{\"heading\":false,\"text\":\"El árabe tembló, pero no de terror.\"},{\"heading\":false,\"text\":\"Un amor inmenso, un amor de los cielos, inundaba su alma; porque Yémina, como lo decia su nombre, era la felicidad.\"},{\"heading\":false,\"text\":\"Sus ojos azules, límpidos como el cielo, lucientes como él, como él hermosos, le sonreian y le acariciaban.\"},{\"heading\":false,\"text\":\"Sintió Ased-el-Schevaní dentro de sí una vida nueva; encontróse jóven, ardiente, feliz.\"},{\"heading\":false,\"text\":\"Sus lábios murmuraron armónicos versos exhalados de su alma como el mas escelente poeta pudiera haberlos exhalado delante de la hermosísima vírgen de sus amores.\"},{\"heading\":false,\"text\":\"--Yo te amo hurí, esclamó; te amo y por tí me siento capaz de todo.\"},{\"heading\":false,\"text\":\"Eres para mí mas preciada que la clara y fresca fuentecilla que brota entre flores á la sombra del oasis del desierto para el cansado y sediento caminante.\"},{\"heading\":false,\"text\":\"Tú eres la luz y la vida, el sueño de paz y la esperanza de ventura.\"},{\"heading\":false,\"text\":\"Por tí seria yo capaz de conquistar los cielos, aunque defendiese su puerta el arcángel de fuego.\"},{\"heading\":false,\"text\":\"--No quiero tanto, dijo Yémina: si me concedes lo que voy á pedirte, creeré que me amas y te amaré.\"},{\"heading\":false,\"text\":\"--¿Y qué puedes pedirme que yo no te conceda, luz esplendorosa de mi alma?\"},{\"heading\":false,\"text\":\"--¿Te acuerdas de una muger á quien amaste?\"},{\"heading\":false,\"text\":\"--¡Ah! ¡Florinda! ¡Florinda! esclamó el Schevaní; ¿por qué me recuerdas mi crímen? Era una noche triste y sombría: la luna estaba velada por vapores de sangre: tú estabas delante de mí, pálida, loca aunque hermosa, manchada de lodo la túnica: no estabas tan hermosa como ahora, sultana de las huríes: no, yo... me irrité... yo no habia amado... escitaste mi furor... pero yo no te he olvidado... yo he llorado tu muerte... porque no creí que volveria á encontrarte tan resplandeciente, tan hermosa como la mayor de las hermosuras. ¿Por qué me recuerdas mi crímen y me despedazas el alma?\"},{\"heading\":false,\"text\":\"--Yo no soy Florinda, dijo Yémina: si á tus ojos la represento, es porque Dios quiere en castigo de tu crueldad que tú veas siempre á Florinda en la muger que ames. Tú ves mis cabellos dorados y mis ojos azules. Pues bien, mira por un momento.\"},{\"heading\":false,\"text\":\"Se transformó Yémina y se presentó á Ased-el-Schevaní con sus cabellos negros y brillantes, sus ojos negros y deslumbradores, su frente cándida y purísima y su boca purpúrea, exhalando ambrosía.\"},{\"heading\":false,\"text\":\"Aquella vision duró un momento.\"},{\"heading\":false,\"text\":\"Deslumbró á Ased-el-Schevaní como si en sus ojos hubiera brillado el sol.\"},{\"heading\":false,\"text\":\"Y pasó como un relámpago y volvió á ver en Yémina á Florinda.\"},{\"heading\":false,\"text\":\"Ased-el-Schevaní empezó á enloquecer, y soltó una insensata carcajada.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡yo te amo! ¡yo te amo! esclamó: ámame y seremos los dos seres mas felices de la tierra. ¿Por qué no me amas tú tambien? ¿Acaso me conservas rencor?\"},{\"heading\":false,\"text\":\"--Yo te amaré si me das lo que te pida, repuso Yémina.\"},{\"heading\":false,\"text\":\"--Y bien, ¿qué quieres? respondió anhelante Ased-el-Schevaní.\"},{\"heading\":false,\"text\":\"--Acuérdate: cuando mataste á Florinda la quitaste un collar de perlas que llevaba sobre su seno.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡ah! ¡el rico collar de perlas! esclamó Ased-el-Schevaní lanzando una larga carcajada.\"},{\"heading\":false,\"text\":\"Y luego tomando una guzla de marfil con cuerdas de oro, que se veia junto á Yémina, se sentó á sus piés y cantó, con la voz fresca y pura como un jóven, él, que nunca habia hecho versos ni habia cantado, el romance siguiente:\"},{\"heading\":false,\"text\":\"«Hermosa de las hermosas,--flor preciada, luz del cielo: ¿Para qué quieres las joyas,--si sus pálidos reflejos han de amenguar lo brillante--de tus dorados cabellos? envidia tendrán las perlas--si las posas en tu seno, porque es nacar animado--que de amores guarda incendios. No hay zafir como tus ojos,--ni diamantes de alto precio que se atrevan á igualarse--en lo luciente con ellos. Eres búcaro de flores--que para el amor nacieron, y de Hiram en los jardines--de Dios las meció el aliento. Eres joya de su mano--pura, como allá en los cielos, la nubecilla que pasa--al leve impulso del viento, ante el sol que la colora, en lumbre de amor traspuesto. Que Allah, hermosa, te bendiga,--pues eres cerrado huerto, que para tu amante guardas--de tu pureza el misterio.\"},{\"heading\":false,\"text\":\"Ased-el-Schevaní dejó la guzla y lanzó otra insensata carcajada.\"},{\"heading\":false,\"text\":\"Su locura crecia.\"},{\"heading\":false,\"text\":\"--Quiero el collar de Florinda, dijo Yémina con voz dulce acariciando con sus rosados dedos la larga barba blanca del Schevaní.\"},{\"heading\":false,\"text\":\"--¡El collar de Florinda! esclamó el árabe: ¡un collar que vale muchos cuentos de doblas!\"},{\"heading\":false,\"text\":\"La locura y el amor no habian logrado dominar la codicia del Schevaní.\"},{\"heading\":false,\"text\":\"--No te amaré, dijo Yémina.\"},{\"heading\":false,\"text\":\"--¡Que no me amarás! esclamó con fiereza el árabe.\"},{\"heading\":false,\"text\":\"--No, repuso reposadamente Yémina.\"},{\"heading\":false,\"text\":\"--¡Acuérdate! dijo á su vez el árabe.\"},{\"heading\":false,\"text\":\"--¡Tú heriste á Florinda! esclamó con desprecio la jóven.\"},{\"heading\":false,\"text\":\"Ciego de cólera ante aquel desprecio el feroz siro, un pensamiento de sangre pasó por su alma y desnudó fuera de sí su puñal.\"},{\"heading\":false,\"text\":\"Pero cuando descargó el golpe sintió un agudo dolor en la mano y se encontró...\"},{\"heading\":false,\"text\":\"En su lecho en la alcazaba del Albaicin.\"},{\"heading\":false,\"text\":\"--Ha sido un sueño, dijo; he creido que heria á aquella muger y he dado con el puño en el muro; ¡pero que sueño tan horrible y tan hermoso!\"},{\"heading\":false,\"text\":\"Ased-el-Schevaní no logró volver á dormirse.\"},{\"heading\":false,\"text\":\"Veia delante de sí, radiante de hermosura, á Yémina.\"},{\"heading\":false,\"text\":\"A la noche siguiente volvió á subir á la plataforma de la torre mas alta de su castillo, y como la noche anterior se apoyó en las almenas.\"},{\"heading\":false,\"text\":\"Entonces volvió á ver sobre la cumbre de la Colina Roja el esplendoroso alcázar, y los caballeros que giraban á su al rededor en los aires y en la tierra y oyó la distante y armoniosa música de la zambra que se exhalaba por los calados ajimeces del alcázar.\"},{\"heading\":false,\"text\":\"--No, pues ahora no sueño, poderoso Allah: esclamó Ased-el-Schevaní; yo afirmo los piés en mi castillo y mis manos en sus almenas: yo veo la luna triste y pálida que sigue lentamente su curso; el viento de la noche refresca mi frente, y allí, allí, sobre la Colina Roja, se levanta ese alcázar maravilloso y se agitan aquellos caballeros sobrenaturales, y se escucha esa armonía incomparable. ¡No, no es un sueño, poderoso Señor!\"},{\"heading\":false,\"text\":\"Y como la noche antes salió de su alcazaba por un postigo y se trasladó á la Colina Roja.\"},{\"heading\":false,\"text\":\"Y como la noche antes vió el Palacio-de-Rubíes, y escuchó la voz de sus remordimientos en el fondo de la cisterna, y vió á Yémina, y la enamoró; y Yémina le volvió á pedir el amuleto de Salomon que habia robado á Florinda, y como la noche anterior se irritó y quiso herir á Yémina como á Florinda habia herido, y volvió á sentir su mano lastimada y á encontrarse en su lecho en la alcazaba del Albaicin.\"},{\"heading\":false,\"text\":\"Durante siete noches se repitió este prodijio, y durante estos siete dias Ased-el-Schevaní, se presentaba á sus vasallos mas loco y mas feroz.\"},{\"heading\":false,\"text\":\"Al fin á la octava noche, el árabe no subió á la plataforma de la torre, sino que bajó á un profundo subterráneo de su castillo donde tenia su tesoro.\"},{\"heading\":false,\"text\":\"Abrió un enorme cofre de hierro, y de entre otras muchas joyas, tomó el collar de perlas de Florinda, y se encaminó á la Colina Roja.\"},{\"heading\":false,\"text\":\"El amor y el deseo habian dominado en él á la codicia.\"},{\"heading\":false,\"text\":\"Cuando entró en el Palacio-de-Rubíes, no resonó en sus oidos la voz de su remordimiento, ni descendió á la oscura cisterna.\"},{\"heading\":false,\"text\":\"Le protegia el talisman.\"},{\"heading\":false,\"text\":\"Yémina salió á su encuentro y le sonrió.\"},{\"heading\":false,\"text\":\"--¿Me traes el hermoso collar? dijo.\"},{\"heading\":false,\"text\":\"--Sí, contestó todo trémulo Ased-el-Schevaní sacándole de su seno: vale un tesoro, pero mi vida vale mas, y sino me amas moriré. ¿Me amarás tú, si te doy esta inestimable joya?\"},{\"heading\":false,\"text\":\"--¡Oh! ¡sí! ¡te amaré siempre! dijo la jóven.\"},{\"heading\":false,\"text\":\"E inclinó su hermosa cabeza delante de Ased-el-Schevaní.\"},{\"heading\":false,\"text\":\"El árabe puso el talisman alredor del cuello de Yémina, y cuando se le hubo puesto quiso abrazarla.\"},{\"heading\":false,\"text\":\"Pero le rechazó una fuerza incontrastable.\"},{\"heading\":false,\"text\":\"--Sí, sí, dijo Yémina, te amaré siempre como ama el remordimiento al crímen. Yo apareceré á cada momento mas hermosa ante tí; seré tu eterna desesperacion, tu infierno.\"},{\"heading\":false,\"text\":\"Y al decir Yémina estas palabras, Ased-el-Schevaní se encontró entre las tinieblas y el ambiente húmedo de la cisterna, y vió delante de sí como un cuerpo lúcido, y cada vez mas hermosa á Yémina.\"},{\"heading\":false,\"text\":\"Si queria acercarse á ella, parecia que un muro invisible le contenia.\"},{\"heading\":false,\"text\":\"Si pretendia herirla, su puñal encontraba un cuerpo duro é impenetrable como el diamante; si desesperado, no pudiendo resistir el martirio de la vista de tanta hermosura, pretendia huir, el terrible fantasma se le ponia siempre delante, cada vez mas hermoso, cada vez mas incitador.\"},{\"heading\":false,\"text\":\"Yémina se habia convertido en el infierno de Ased-el-Schevaní.\"},{\"heading\":false,\"text\":\"Porque Ased-el-Schevaní habia muerto.\"},{\"heading\":false,\"text\":\"Sus wazires habian encontrado su cadáver en su lecho, y le habian enterrado con gran pompa en el panteon de la alcazaba.\"},{\"heading\":false,\"text\":\"Lo que quedaba sufriendo penas eternas en la cisterna era el alma de Ased-el-Schevaní.\"},{\"heading\":false,\"text\":\"De Ased-el-Schevaní, el alma condenada de la cisterna de la Alhambra.\"},{\"heading\":false,\"text\":\"Algunas noches oscuras, frias, tempestuosas, salen por los brocales de la cisterna gritos débiles, perdidos, desesperados.\"},{\"heading\":false,\"text\":\"Son los gemidos de desesperacion de Ased-el-Schevaní.\"},{\"heading\":false,\"text\":\"Del verdugo del rey don Rodrigo.\"},{\"heading\":false,\"text\":\"Del infame asesino, del torpe profanador de Florinda.\"},{\"heading\":false,\"text\":\"Otras serenas y tranquilas noches de luna, cuando todos duermen, hasta los guardas de los adarves, se percibe un canto dulcísimo y perdido.\"},{\"heading\":false,\"text\":\"Es la voz de Yémina que escita la desesperacion de Ased-el-Schevaní.\"},{\"heading\":false,\"text\":\"Pero ya sea la noche oscura ó apacible; ya la alumbre la verde luz del relámpago ó el pálido reflejo de la luna, si pasais junto á los brocales de la cisterna y escuchais ya un gemido, ya un canto, no os asomeis al oscuro brocal, porque puede tragaros el abismo y haceros probar el mismo infierno que prueba hace centenares de años Ased-el-Schevaní.\"},{\"heading\":false,\"text\":\"Esta es la historia maravillosa del alma de la cisterna.\"},{\"heading\":false,\"text\":\"Sed, pues, justos, buenos y caritativos, porque Dios, Altísimo y Unico, condena al pecador con lo mismo con que pecó.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"He aquí la tradicion referente á los algibes de la Alhambra.\"},{\"heading\":false,\"text\":\"¿Dónde pudo tener origen?\"},{\"heading\":false,\"text\":\"¿Escuchó algun poeta moro, durante una noche melancólica el derrumbe del agua en los algibes, ó algun gemido del viento en sus altas bóvedas romanas y de ello tomó asunto para escribir una bella leyenda árabe?\"},{\"heading\":false,\"text\":\"No lo sabemos.\"},{\"heading\":false,\"text\":\"Pero sabemos sí, que muchas noches oscuras y tempestuosas nos hemos asomado á uno de los brocales de la cisterna y hemos escuchado atentamente.\"},{\"heading\":false,\"text\":\"Solo hemos oido el crugir de las gotas de la lluvia sobre el agua allí depositada, pero nunca nos hemos podido hacer la ilusion de que aquel ruido procediese del gemido de un alma condenada, ni del canto de un ser sobrenatural.\"},{\"heading\":false,\"text\":\"Esto acaso consiste en que nuestra imaginacion es menos impresionable que la del poeta moro autor de la leyenda _El alma de la cisterna_.\"}]},{\"title\":\"La puerta del juicio. — capítulo I\",\"blocks\":[{\"heading\":false,\"text\":\"Cuando se pasa de la puerta de los Gomeles, y de las tres pendientes avenidas que se presentan á la vista, bajo los tupidos toldos de verdura de las frondas de los álamos que se cruzan, se toma la mas pendiente, la de la izquierda; ya cerca de su terminacion se encuentra un cubo de fortificacion á la usanza del siglo XVI, y mas allá, apoyándose en este cubo, una magnífica fuente greco-romana del gusto del renacimiento, denominada _Pilar del emperador Cárlos V_.\"},{\"heading\":false,\"text\":\"Siguiendo adelante á lo largo del muro en que está esculpida la decoracion de la fuente, y torciendo á la izquierda, se levanta de improviso ante los ojos, como una sorpresa, la magestuosa _Puerta del juicio_, entrada principal del alcázar de la Alhambra.\"},{\"heading\":false,\"text\":\"Esta puerta, formada por dos torreones, unidos en la parte media de su altura por un gigantesco arco de herradura, tiene en su fondo un muro en el cual se abre una puerta mas pequeña de arco de herradura tambien, labrada en rico mármol blanco de la sierra, y sustentado por dos bellas columnas con caprichosos capiteles, y galanamente ornamentado con flores y cintas entrelazadas.\"},{\"heading\":false,\"text\":\"Sobre la clave del arco mayor se ve esculpida una mano estendida y vuelta la palma; sobre la del arco menor hay esculpida una llave.[67]\"},{\"heading\":false,\"text\":\"En los tiempos á que nos referimos en la leyenda que empezamos á relatar á nuestros lectores, esto es, en el año 724 de la Hegira, y 1325 de Jesucristo, cuando se pasaba de la puerta de los Gomeles, fuertemente torreada y defendida por adarves, se veia una larga avenida de edificios chatos, de un solo piso, que servian de cuarteles á los soldados de la guardia del rey, en la vertiente del pequeño valle comprendido entre la Alcazaba, y las Torres Bermejas, y por ambos lados hasta el pie de los muros, la escarpadura desnuda sin árboles que pudiesen encubrir á los enemigos que lograsen forzar aquel primer puesto fortificado de la puerta de los Gomeles.\"},{\"heading\":false,\"text\":\"Siguiendo aquella ancha avenida, siempre poblada de soldados y esclavos, se llegaba en lo mas alto, á la torre de las _Siete bóvedas_,[68] entrada principal de la Alhambra y su mas magnífica; pero antes de llegar á esta torre, en la parte media de la avenida, á la izquierda, se encontraba un camino llano orlado de cipreses y laureles, desde cuyo principio se veia levantarse al fondo, sencilla y magestuosa la torre del Juicio, entrada principal del alcázar de los reyes moros.\"},{\"heading\":false,\"text\":\"Entonces, delante de esta torre solo se veia una bella plazoleta circular rodeada de jardines; no existian ni el pilar del Emperador ni el cubo de fortificacion, existiendo solo por la parte que este cubo ocupa un adarve que iba á dar sobre la escarpadura de la fortaleza por aquella parte.\"},{\"heading\":false,\"text\":\"El muro que se apoya hoy á la derecha sobre la torre del Juicio, no era, como ahora, un muro de tierra y piedra, sino de brillante y tersa argamasa roja que dejaba comprender su dureza marmórea, y en cuya parte superior corria la columnata de una galería que correspondia á un jardin del alcázar.[69]\"},{\"heading\":false,\"text\":\"En el segundo arco de la Puerta del Juicio, entre sus adornos, se leia entonces como ahora la inscripcion siguiente: _Dios sea loado: no hay otro Dios que Dios y Mahoma su profeta: no hay fortaleza sin Dios_: y sobre este arco y estos adornos, en una ancha faja de estuco, con caracteres cúficos entrelazados de flores y cintas se leia esta otra inscripcion: _Mandó labrar esta portada, llamada judiciaria, con la cual Dios Altísimo haga dichosa la ley de los hijos de salvacion, Abul-Giux-Nazar-ebn-Abdallah-ebn-Nazar, mantenga Dios en las morismas sus obras pias y caritativas. Labróse á 27 dias de la luna de Maulud el engendradizo, año de 647._\"},{\"heading\":false,\"text\":\"De modo que en los tiempos de nuestra leyenda, solo hacia setenta y siete años, desde que se habia terminado la torre del Juicio ó al menos desde que se habia hecho su portada.\"},{\"heading\":false,\"text\":\"Llamábase la puerta principal del alcázar torre del Juicio, porque habiendo seguido los árabes y continuádola los moros la costumbre de los tiempos primitivos, el rey en persona ó en representacion suya el cadí de los cadíes ó justicia mayor del reino, oian en aquella puerta en audiencia pública las quejas de los súbditos, y dirimian sus contiendas y pleitos de una manera ejecutiva.\"},{\"heading\":false,\"text\":\"De contínuo aquella puerta estaba cerrada, con sus dos grandes hojas forradas de hierro y fuertemente claveteadas, y por fuera de ella, como en respeto de la autoridad real, se veian los esclavos de la guardia berberisca ricamente vestidos y dando la guardia.\"},{\"heading\":false,\"text\":\"Solo se abria un postigo para la entrada de los magnates y caballeros; de par en par solo se abria la puerta para dar salida ó entrada al rey ó á los embajadores de reyes; cuando aquella puerta se abria enteramente pasaba siempre bajo ella el estandarte real, acompañando al rey ó á los embajadores, y despues la puerta cerraba sus dos tremendas hojas de hierro.\"},{\"heading\":false,\"text\":\"Todos los giumas (viernes), á la hora de la salida del sol, aquella puerta se abria, y aparecia tras ella un espectáculo sorprendente: el trono de justicia, con su dosel rojo, sus almohadas de púrpura y brocado, y sus siete gradas cubiertas con una alfombra de Persia: á los piés de estas gradas, á la derecha, el alférez mayor del reino con el estandarte real, y al otro lado el alguacil mayor con la espadada de justicia, y walíes, y arrayaces, y caballeros, y eunucos: en lo alto, el rey sentado en los almohadones, y delante de la puerta, en semicírculo, para contener al pueblo que asistia á la audiencia, los esclavos berberiscos con sus largas lanzas, sus bruñidas armaduras y sus turbantes rojos.\"},{\"heading\":false,\"text\":\"Cuando en vez del rey hacia justicia el cadí de los cadíes, sentábase este en un almohadon en la primera grada, y en vez de la córte que acompañaba al rey, le acompañaban ciertos funcionarios del órden judicial, pero nunca faltaban el estandarte real y la espada de justicia, como representantes de la autoridad regia.\"},{\"heading\":false,\"text\":\"Un katib (secretario), colocado en el centro del semicírculo determinado por los esclavos berberiscos, llamaba por su órden á los que habian pedido audiencia, y los dejaba pasar hasta los piés del trono de justicia.\"},{\"heading\":false,\"text\":\"Despues que esta habia acabado de administrarse, la puerta se cerraba, y el rey, la córte y el trono desaparecian tras ella.\"},{\"heading\":false,\"text\":\"¿Quién podria comprender ahora, á la vista de aquella puerta abandonada, de aquel torreon cuyas almenas reales ha derrocado el tiempo, y á las cuáles ha sustituido el conquistador con un desnudo pretil, con una especie de grosero ribete de mampostería, el magnífico esplendor de que en los tiempos de la dominacion mora se vió rodeado, y el profundo respeto con que los musulmanes de Granada miraban aquella puerta, lugar sagrado, donde en nombre de las leyes podia ir el mas pobre, el mas abyecto á ejercitar su derecho?\"},{\"heading\":false,\"text\":\"Hoy un centinela indiferente, provisto de una prosáica consigna, se pasea con el fusil al brazo ó se apoya en él de pié é inmóvil, sin sospechar siquiera la grandeza pasada de aquel lugar, y en el sitio donde hace cuatro siglos se levantaba el trono de justicia de los reyes de Granada, se ve hoy la mezquina mesa cubierta con una manta de lana donde escribe sus partes el sargento de la guardia.\"},{\"heading\":false,\"text\":\"El tiempo, que todo lo muda, que todo lo empalidece, que todo lo gasta, que todo lo pulveriza, ha convertido en un desnudo esqueleto de lo que fué, á la torre del Juicio, ó de justicia de los reyes de la Alhambra.\"},{\"heading\":false,\"text\":\"Por eso, nosotros que somos exageradamente entusiastas, no hemos podido pasar nunca bajo el arco de mármol de la torre del Juicio, de la hermosa y poética puerta del alcázar moro, sin sentir algo de respeto, sin creernos trasportados á otros tiempos y á otras gentes, como si hubiese pasado junto á nosotros rozándonos la cabeza con sus alas el genio de lo que fué.\"},{\"heading\":false,\"text\":\"Además, para que nosotros sintamos una conmocion indefinible al pasar bajo aquel arco, al pisar aquel dintel de mármol, existe una razon poderosa.\"},{\"heading\":false,\"text\":\"Nosotros sabemos que sobre aquel dintel, al pié de su trono de justicia, cayó asesinado un rey de la dinastía nazerita.\"},{\"heading\":false,\"text\":\"Su sangre ha caido allí, y allí acaso la vé aun la justicia del cielo.\"},{\"heading\":false,\"text\":\"Porque el rey asesinado era un buen caballero, un corazon leal, lleno de caridad y de justicia.\"},{\"heading\":false,\"text\":\"Aquel rey era el sultan de Andalucía y de Granada, Abul-Walid-Ismail-Abul-Said, quinto descendiente coronado del Magnífico rey Nazar.\"}]},{\"title\":\"La puerta del juicio. — capítulo II\",\"blocks\":[{\"heading\":false,\"text\":\"El dia ocho de la luna de Regeb del año 725 de la Hegira[70], despues de la oracion de azobih, á punto que se dejaban ver en el oriente las primeras ráfagas rosadas precursoras del sol, los berberiscos que daban la guardia de la puerta del Juicio, acudieron presurosos, llamados por los atabales, y se formaron en dos filas formando calle á ambos lados de la puerta.\"},{\"heading\":false,\"text\":\"Poco despues la puerta se abrió, salió un tropel de ginetes armados sobre caballos de guerra, entre los cuales ondeaba el estandarte real, y tras estos caballeros, en medio de una córte resplandeciente, apareció el rey Abul-Walid, armado con un arnés esmaltado de oro y colores, con corona en la cabeza y manto de púrpura sobre los hombros, cabalgando en un poderoso corcel con paramento de brocado sobre sus lórigas de acero.\"},{\"heading\":false,\"text\":\"Piafaba el soberbio bruto hijo de las llanuras de Baeza, orgulloso de su ginete; y en verdad, que nunca las moras granadinas habian visto, ocultas tras las celosias, un hombre mas hermoso ni de aspecto mas noble y régio que el sultan de Granada Abul-Walid-Nazar.\"},{\"heading\":false,\"text\":\"Era blanco y mostraba la barba bermeja, como su quinto abuelo Al-Hhamar, el vencedor; sus ojos tenian en su mirada la dulzura de la gacela cuando contemplaban la hermosura, ó el sombrío y aterrador fuego de los del leon irritado cuando los revolvia entre el combate; cuando nada le distraia ó le irritaba mostraba su semblante una melancolía vaga, una ansiedad profunda, una sed insaciable, pero sed de felicidad: el poderoso Abul-Walid no era feliz.\"},{\"heading\":false,\"text\":\"Sentia remordimientos, y no habia encontrado venturas en el amor.\"},{\"heading\":false,\"text\":\"Sus remordimientos le recordaban á su tio el rey de Granada, Abul-Giux-Nazar á quien habia destronado.\"},{\"heading\":false,\"text\":\"Digamos algo acerca de la historia de Abul-Walid.\"},{\"heading\":false,\"text\":\"Para que se comprenda bien esta historia, necesitamos remontarnos á los tiempos del sultan Mohammet-ebn-Abdalah-ebn-Nazar hijo de Al-Hhamar el Magnífico.\"},{\"heading\":false,\"text\":\"El rey Al-Hhamar el Magnífico, el primer rey independiente de Granada, el fundador de la dinastía nazerita, habia muerto de un accidente estraño, y segun algunos por tósigo, á las puestas del sol del viernes 29 de giumada postrera, del año 671 de la Hegira[71]. Honrado por amigos y enemigos este gran rey, fué consolado en su último trance por el infante don Felipe, hermano del rey Alfonso de Castilla que le acompañaba.\"},{\"heading\":false,\"text\":\"Murió cerca de Granada, en su tienda, en ocasion en que iba en persona á reprimir la rebeldía de los walíes de Málaga, Guadix y Comares.\"},{\"heading\":false,\"text\":\"Hé aquí el epitafio que su hijo el sultan Mohammet II hizo esculpir sobre su sepulcro, y que pudieron ver nuestros abuelos en el panteon de la Alhambra:\"},{\"heading\":false,\"text\":\"«Este es el sepulcro del sultan alto, fortaleza del Islam, decoro del género humano, gloria del dia y de la noche, lluvia de generosidad, rocío de clemencia para los pueblos, polo de la _secta_, esplendor de la ley, amparo de la _tradicion_, espada de _verdad_, mantenedor de las criaturas, leon de la guerra, ruina de los enemigos, apoyo del estado, defensor de las fronteras, vencedor las huestes, domador de los tiranos, triunfador de los impíos, príncipe de los fieles, sábio adalid del pueblo escogido, defensa de la fé, honra de los reyes y sultanes, el vencedor por Dios, el ocupado en el camino de Dios. Abu-Abdalah-ebn-Juzef-ebn-Nazar-el-Ansarí: ensálcele Dios al grado de los altos y justificados y le coloque entre los profetas, justos, mártires y santos, y complázcase Dios en él y le sea misericordioso, pues fué servido que naciese el año 591 y que fuese su tránsito dia giuma (viernes) despues de la azala de alazar á 29 de la luna giumada postrera, año 671. Alabado sea aquel cuyo imperio no fina, cuyo reinado no principió, cuyo tiempo no fallecerá, que no hay mas Dios que él, el Misericordioso y Clemente[72].»\"},{\"heading\":false,\"text\":\"Sucedióle su hijo Mohammet, mancebo animoso y valiente, y que á pesar de la grandeza de su padre, encontró el reino ya un tanto dividido en bandos y amenazado por las rebeldías de algunos walíes, aunque por lo demás próspero y floreciente.\"},{\"heading\":false,\"text\":\"Apenas proclamado rey se trasladó á la córte de Alfonso X, á renovar la alianza que su padre habia mantenido con Castilla, y tan simpático supo hacerse al sabio rey cristiano, que quiso armarle y le armó por sí mismo caballero.\"},{\"heading\":false,\"text\":\"Pero Mohammet no habia hecho de buen grado esta alianza; contribuia á su disgusto el que la reina doña Violante, esposa de Alfonso le comprometió, abusando de su galantería, á que se aviniese con los walíes de Málaga, Guadix y Comares.\"},{\"heading\":false,\"text\":\"Aprovechando Mohammet II la ausencia de los reyes de Castilla y Aragon para asistir al concilio de Leon, alentó el proyecto de recobrar la Andalucía entera. Pareciéndole, sin embargo, demasiado árdua la empresa para él solo, entró en tratos de alianza con el emir de Marruecos, Abu-Juzef, jefe de la poderosa tribu de los Beri-Merines; aceptó Juzef, y vino de Africa con una poderosa hueste de caballería á Algeciras donde le esperaba el rey de Granada.\"},{\"heading\":false,\"text\":\"Acometida la empresa por la parte de Jaen, el adelantado de la frontera don Nuño, murió en la jornada como valiente, pereciendo además ocho mil cristianos.\"},{\"heading\":false,\"text\":\"Abu-Juzef envió la cabeza del adelantado al rey de Granada, y al verla este, que habia tratado mucho en vida á don Nuño, se cubrió el rostro con ambas manos esclamando.\"},{\"heading\":false,\"text\":\"--¡Guala, mi buen amigo, que no me lo mereciais!...\"},{\"heading\":false,\"text\":\"Por otra parte, don Sancho, hijo del rey de Aragon, arzobispo titular de Granada, acometió á los moros con un formidable ejército, pero el rey Mohammet le desvarató y le hizo á él mismo prisonero, siendo ocasion esta presa de don Sancho para que se pusiesen á punto de volver sus armas los moros los unos contra los otros, porque los africanos querian enviar al cautivo al emir de Marruecos, y los andaluces al rey de Granada; pero el arraez Ebn-Nazar, infante de la casa de Granada, que presenciaba la contienda, arremetió hacia el cautivo don Sancho esclamando:\"},{\"heading\":false,\"text\":\"--No quiera Dios que por un perro se pierdan tantos buenos caballeros como aquí están.\"},{\"heading\":false,\"text\":\"Y pasándole de una lanzada, de la que el infeliz cayó muerto, le mandó le cortasen la mano derecha y la cabeza; envióse la mano con su anillo al rey de Granada, y la cabeza al emir de Marruecos.\"},{\"heading\":false,\"text\":\"¡Tremenda manera de obviar la cuestion!\"},{\"heading\":false,\"text\":\"Supo Alfonso de Castilla en Leon, esta brava acometida de los moros, y abandonando por entonces el negocio de su coronacion como emperador de Alemania, para lo que únicamente habia ido al concilio, volvió en defensa de la ya poseida corona de Castilla, y firmó con el emir de Marruecos, y con el rey de Granada un armisticio de dos años.\"},{\"heading\":false,\"text\":\"Mas adelante, puesto por Alfonso sitio á Algeciras, y destrozada su armada en el mar y su ejército en tierra, levantóse contra él, en su propio reino, una tempestad terrible; coligáronse contra él la reina su esposa, los infantes sus hijos, sus magnates; y el infante don Sancho, su primogénito, se hizo el caudillo de esta conspiracion contra su padre, y se apoderó de su corona.\"},{\"heading\":false,\"text\":\"El infeliz Alfonso, vencido, fugitivo, abandonado de todos, pidió sucesivamente ayuda á los reyes de Portugal, de Aragon y de Francia, que se escusaron, como asimismo el papa, que se limitó á decirle que se resignase; desesperado entonces Alfonso recurrió á la ayuda del emir de Marruecos, su enemigo, que se encontraba fortificando á Algeciras, y que al recibirle en medio de su ejército le puso á su derecha y le dejó oir estas memorables palabras.\"},{\"heading\":false,\"text\":\"--Te trato así porque eres desgraciado, y me uno á tí para vengar la causa comun de todos los reyes y de todos los padres.\"},{\"heading\":false,\"text\":\"La alianza del rey destronado con el emir de Marruecos impuso terror al hijo rebelde, y al fin se humilló, devolvió la corona á su padre, y obtuvo su perdon.\"},{\"heading\":false,\"text\":\"Entretanto el rey de Granada, para consolidar y robustecer su reino, aprovechaba las disidencias entre los reyes cristianos del resto de España. El rey de Aragon estaba en guerra con Francia por la posesion de Sicilia, y Sancho IV, que habia heredado al fin el trono de Castilla por muerte de Alfonso, se veia obligado á reprimir las sediciones de sus vasallos.\"},{\"heading\":false,\"text\":\"Dominó Mohammet los elementos rebeldes de su reino, se hizo respetar del emir de Marruecos, que pretendia tener predominio en los asuntos de los moros en España. Recobró ciudades y villas á los cristianos, y al fin, cubierto de gloria murió el domingo 8 de la luna de jaban del año 701[73].\"},{\"heading\":false,\"text\":\"Dejó tres hijos; Mohammet su primogénito y compañero, el que le sucedió en el trono.\"},{\"heading\":false,\"text\":\"Farax, que conspiró contra la vida de su hermano.\"},{\"heading\":false,\"text\":\"Y Nazar, que reinó tambien.\"},{\"heading\":false,\"text\":\"Fué proclamado Mohammet III, con el nombre de Abu-Abdalah Mohammet.\"},{\"heading\":false,\"text\":\"Era este rey hermoso sobre toda ponderacion; y tan dado al cuidado de los negocios, que no habia wazires que pudiesen estar á su lado tanto tiempo como él trabajaba.\"},{\"heading\":false,\"text\":\"Este trabajo asiduo le hizo perder la salud.\"},{\"heading\":false,\"text\":\"Otros contratiempos vinieron á agravar sus cuidados.\"},{\"heading\":false,\"text\":\"Apenas habia subido al trono, cuando un pariente suyo, Abul-Hegiag-ebn-Nazar, se le reveló en la ciudad de Guadix, donde era walí, y se negó á venir á Granada á su solemne jura de rey: reprimió al fin esta rebeldía, y se concertó con el rey de Aragon don Jaime.\"},{\"heading\":false,\"text\":\"Tomó á Ceuta en Africa y otras villas y lugares en España, y ya respetado de unos y de otros, se dedicó á hermosear á Granada y á continuar la obra de la Alhambra.\"},{\"heading\":false,\"text\":\"Sacóle de repente de esta pacífica existencia el rey don Jaime, que rompiendo la tregua vino con un formidable ejército sobre la ciudad de Almería y la sitió.\"},{\"heading\":false,\"text\":\"El rey de Castilla cercaba en tanto á Algeciras.\"},{\"heading\":false,\"text\":\"Avínose con este último, que levantó el cerco mediante la cesion de otras villas y castillos, pero el rey de Aragon, mas tenaz, se fortificó en su campo y continuó el cerco sobre Almería.\"},{\"heading\":false,\"text\":\"Mientras el rey Mohammet se ocupaba del gobierno y de la defensa de su reino, su hermano Nazar, á quien aguijoneaba su ambicion, se hizo un fuerte partido en Granada, y pretendió abiertamente la corona.\"},{\"heading\":false,\"text\":\"Daba por pretesto para su pretension que el rey estaba enfermo de los ojos, que necesitaba fiarse de los agenos, y que no podia confiarse prudentemente el cuidado del reino á un rey ciego.\"},{\"heading\":false,\"text\":\"Concertóse la conspiracion con tal reserva, que nada pudo traslucirse de ella hasta el último dia de Rhamazan, en que al amanecer los conjurados cercaron el alcázar con muchas gentes del pueblo bajo, que sin pretender entrar y sin armas, se limitaban á gritar:\"},{\"heading\":false,\"text\":\"--¡Viva el rey Nazar! ¡viva el rey Nazar!\"},{\"heading\":false,\"text\":\"Otro número inmenso del populacho acudió á la casa del wazir Abu-Abdalah-el-Lachmi, que por su severidad estaba aborrecido de los magnates que ayudaban en la conjuracion á Nazar, y echaron las puertas abajo y penetraron dentro robando oro, plata, vestidos, armas, caballos, destruyendo sus alhajas, sus libros y sus muebles.\"},{\"heading\":false,\"text\":\"Luego corrieron al alcázar, y con pretesto de apoderarse del wazir, que se habia refugiado en él, atropellaron la guardia, entraron furiosos sin respetar al rey Mohammet que les salió al paso, y en su presencia mataron al wazir y saquearon el mismo alcázar de la Alhambra.\"},{\"heading\":false,\"text\":\"Mohammet se vió obligado á huir, pero le cercaron en una torre y le intimaron á que abdicase en su hermano Nazar.\"},{\"heading\":false,\"text\":\"Viéndose solo y desamparado Mohammet, abdicó aquella noche solemnemente la corona en su hermano Nazar, que no quiso verle y le envió al palacio del Príncipe, fuera de Granada, y despues á la fortaleza de Almuñecar.\"},{\"heading\":false,\"text\":\"Nazar fué jurado rey.\"},{\"heading\":false,\"text\":\"No tardó mucho el rey Nazar en verse tratado de la misma manera que él habia tratado á su hermano.\"},{\"heading\":false,\"text\":\"Un sobrino suyo, Abul-Said, hijo de una de sus hermanas y del walí de Málaga Ferag-ebn-Nazar, andaba procurándose parciales con harta ambicion; mandóle prender Nazar, pero el mancebo fué avisado y huyó de Granada; escribió el rey á su cuñado Ferag para que corrigiese á su hijo, pero el walí de Málaga le contestó severamente que si su hijo le destronaba, no haria mas que imitar la conducta que él mismo habia observado con su hermano el rey Mohammet.\"},{\"heading\":false,\"text\":\"Aconteció por este tiempo al rey Nazar un accidente de apoplegía; tuviéronle por muerto: divulgóse como cierta esta noticia, y los parciales del destronado Mohammet III corrieron á la fortaleza de Almuñecar, le sacaron de ella y le llevaron á Granada.\"},{\"heading\":false,\"text\":\"Pero ¿cuál fué la sorpresa de estos cuando al entrar en Granada supieron que el rey Nazar habia recobrado la salud, y que Granada ardia en fiestas por su restablecimiento? El buen Mohammet pretestó que su venida habia sido á visitarle sabiendo el quebranto de su salud. Nazar afectó creerle, y le mandó volver á Almuñecar y que le acompañasen los que le habian traido.\"},{\"heading\":false,\"text\":\"Por aquel tiempo entró Fernando IV de Castilla en tierras de Granada, y puso sitio á Alcaudete. Gentes hubo que atribuyeron esta entrada del castellano á sugestiones del destronado Mohammet, aunque el desgraciado estaba completamente ageno á ella.\"},{\"heading\":false,\"text\":\"Pero cuando el rey de Castilla se ponia sobre Martos, emplazado por unos hermanos llamados los Carvajales á quienes habia mandado dar injustamente muerte, murió cabalmente en el mismo tiempo en que los hermanos le habian citado ante el tribunal de Dios.\"},{\"heading\":false,\"text\":\"Por esa razon llamóse desde entonces á Fernando IV de Castilla el _Emplazado_.\"},{\"heading\":false,\"text\":\"Por aquel tiempo á principios de la luna de jawal del año 713[74], murió en Almuñecar el desterrado Mohammet, y su hermano Nazar, mandó trasladarle al panteon de la Alhambra y poner sobre su sepulcro la siguiente inscripcion:\"},{\"heading\":false,\"text\":\"«Este es el sepulcro del sultan virtuoso, príncipe justo, sábio en el temor de Dios, uno de los reyes virtuosos, sufrido en los trabajos, laborioso en el camino de Dios, el apacible, el austero, el temeroso de Dios, el humilde, el resignado en Dios en las desventuras y en las prosperidades, morador de los dos paraisos con su meditacion y sus alabanzas, el que encaminaba á las criaturas y mantenia la justicia, camino patente de la confianza y de la bondad, mantenedor del pueblo en su honra con victorias ganadas con propio valor, justicia del trono, decoro y luz resplandeciente del estado, puerta de la ley y de la fé, constante loador de Dios en sus males y en sus desgracias, lucirá en el dia de la cuenta, exacto en la tradiccion y en las obras de la ley y en las altas purificaciones: el dispuesto siempre contra infieles con paso de firmeza y meritorio, observador de la justa medida, carta franca de humanidad, amparador de los templos, defensor de la religion, el escogido, el ínclito, el heredero de los Nazares, heredero de sus estados y de su justicia y laborioso celo en la defensa y gobierno de los pueblos, y en acrecentar sus ventajas y utilidades, el clemente rey, príncipe de los muzlimes, honor de los creyentes, domador irresistible de los incrédulos, el vencedor por la gracia de Dios, Abu-Abdalah, hijo del príncipe de los fieles el sultan escelso, prefecto de la direccion, nube de rocío, vida de la tradicion, apoyo de la secta, el laborioso en el camino de Dios, amparador de la ley de Dios, Abu-Abdalah, hijo del príncipe de los fieles, el vencedor por Dios Abu-Abdalah-ebn-Juzef-ebn-Nazar, honre Dios su mansion y sea venturoso por su bondad: nació, complázcase Dios de él, en dia miércoles tres de jaban honrado del año 655, y murió, santifique Dios su espíritu, y refrigere su sepulcro con las copas suaves de su benignidad, en dia lunes tres de jawal del año 713. Llévele Dios á las mas altas mansiones de los justos, por la verdad de la ley, y bendiga á los que quedan de su casa. Bendiga Dios á nuestro señor y á nuestro dueño Mohammet, y á los suyos con bendicion cumplida.»\"},{\"heading\":false,\"text\":\"Por el otro lado de la piedra se gravó una inscripcion en verso en que se rogaba á Dios le concediese el premio de sus virtudes; que refrigerase con benignas auras su sepulcro; que le regase con apacible rocío y liberales nubes de clemencia; que le vistiese y adornase de las preciosas vestiduras de su misericordia, y que le colocase en las eternas y felices moradas del paraiso.\"},{\"heading\":false,\"text\":\"Parecia que ocupando ya Abul-Giux-Nazar legítimamente el trono por la muerte de su hermano Mohammet III, debian desaparecer los partidos; pero no fué así; la codicia del mando y de los altos empleos del gobierno, traian enemistados y divididos á los principales caballeros de Granada, y vueltos todos contra el wazir ó primer ministro del rey Mohammet-ebn--Alí-al-Hagib, hombre astuto y cruel, causa de las grandes alteraciones que hubo en su tiempo, y particularmente de la ruina del rey Nazar.\"},{\"heading\":false,\"text\":\"Porque Al-Hagib, en su desmedida ambicion, tenia alejados del palacio á los principales señores de Granada, para que ninguno se procurase la gracia del rey, y desterraba á los unos é injuriaba á los otros, hasta el punto de que fueron ya tantos los ofendidos que formaron bando para destruirle, y destruir, si era necesario, al rey Nazar que le protegia.\"},{\"heading\":false,\"text\":\"Volvieron otra vez á alentar las pretensiones del jóven hijo del walí de Málaga, cuñado del rey y le ofrecieron la corona.\"},{\"heading\":false,\"text\":\"Abul-Walid aceptó; se puso en inteligencias con los conjurados, y el walí su padre envió á Granada ciertas gentes que levantaron un motin, pidiendo la cabeza del wazir Al-Hagib.\"},{\"heading\":false,\"text\":\"Pero el rey le amaba; salió, habló á los amotinados y pudo por el momento conjurar el peligro. Castigóse imprudentemente á algunos, y esto fué origen de una sedicion mas respetable. Muchos caballeros de Granada huyeron á Málaga, incitaron al walí á que se rebelase contra Nazar, y al fin lograron que su hijo, Abul-Walid, partiese contra Granada, acaudillando una hueste numerosa.\"},{\"heading\":false,\"text\":\"Al saberse esto, Granada se dividió en bandos; robábanse y matábanse los unos á los otros, y saciaban mútuamente sus ódios y sus venganzas. Una noche entera duró este conflicto, y al amanecer los que llevaban la peor parte, abrieron las puertas del Albaicin á Abul-Walid, que se apoderó de la alcazaba vieja.\"},{\"heading\":false,\"text\":\"Abul-Giux-Nazar se fortaleció en la Alhambra, donde le cercaron los soldados de Abul-Walid.\"},{\"heading\":false,\"text\":\"Viéndose perdido Nazar, envió cartas al rey don Pedro de Castilla que se encontraba en Córdoba, pidiéndole socorro; pero por pronto que el rey castellano entró en tierras de Granada, tuvo tiempo el walí de Málaga para estrechar á Nazar y obligarle á rendirse, con la condicion de que su sobrino Abul-Walid-Abu-Said, ya rey, le concediese la ciudad de Guadix y su comarca, y seguridad y perdon para los que habian seguido su bando.\"},{\"heading\":false,\"text\":\"Concediólo todo en la alegría del triunfo el nuevo rey; partió Nazar para Guadix, y el rey don Pedro de Castilla, sabiendo estas nuevas, y que ya su ayuda era inútil á Nazar, se volvió; pero no sin talar y saquear cuanto encontró á su vuelta, apoderándose de la fortaleza de Huete.\"},{\"heading\":false,\"text\":\"Nazar vivió tranquilamente en Guadix algunos años sin dar oidos á los consejos de los que le incitaban á que procurase recobrar su corona, y murió tranquilo, resignado con su suerte.\"},{\"heading\":false,\"text\":\"Trajeron su cadáver al panteon de la Alhambra, y el rey mandó se le dedicase esta inscripcion:\"},{\"heading\":false,\"text\":\"«Este es el sepulcro del sultan alto, poderoso, ilustre, de muy gran casa, descendiente de los reyes muy nobles, y de la mas preciada prosapia de los escelentes Al-Ansaríes, el mas alto de linaje, esplendor real y defensa invencible de los suyos. El cuarto de los reyes de Beni-Nazar, defensores de la ley y de la direccion, escogidos celadores laboriosos en el camino de Dios, el rey clemente con los hombres, liberal entre los liberales, en su bondad noble, generoso, bien intencionado, santo, misericordioso, Abul-Giux-Nazar, hijo del sultan alto, amparador, ilustre defensor, rey justo, ínclito, humano, defensor de la ley del Islam, aniquilador de los idólatras, el favorecido, el vencedor, el piadoso, el santo príncipe de los fieles Abu-Abdalah, hijo del sultan noble, rey, honor de los hombres, caudillo de los fieles, rey de los que temen á Dios, y de los bien intencionados, depósito fiel de la tradicion y palabras del Islam, amparo de la religion y de la fé, el vencedor por Dios, el victorioso por la gracia de Dios, el santo, el misericordioso príncipe de los muzlimes, Abu-Abdalah-ebn-Nazar; sálvele Dios, y cúbrale con su misericordia y su clemencia, colóquele en morada de santidad, escríbale entre aquellos con quienes se complace. Fué su nacimiento dia lunes 24 de la luna de ramazán el grande, año de 686[75]. Fué jurado en dia viernes 2 de jawal año de 708[76], y murió, sepultado la noche del miércoles 6 de la luna de dilcada, año 722[77]. Alabado sea el rey de la verdad, el claro heredero de la tierra y de lo que hay sobre ella, que él es el mejor de los herederos.»\"},{\"heading\":false,\"text\":\"Y por el otro lado se leia la siguiente inscripcion en verso:\"},{\"heading\":false,\"text\":\"«¡Oh sepulcro del generoso! sobre tu polvo caigan nubes celestes de amparo, de misericordia y de paz; en tu estrado se oiga siempre la bendicion á un rey noble, generoso de los mas generosos; delicia del género humano, bondad de corazon sobre todas las criaturas; caridad, manantial perenne de gloria, seas feliz con Nazar, el cuarto de los reyes de Beni-Nazar, defensores del Islam. Desde la salida del lucero de la religion, desde el alba de la ley, fué su trono de ellos, el mejor amparo de las criaturas. ¡Oh señor de la bondad y de la humanidad! tu casa fué mina de juicio, de prudencia, de virtud y de beneficencia, y hallaron en tí lo que deseaban cuantos tuvieron la suerte de conocerte y acercarse á tí, la nobleza y escelencia del orbe; el resplandor de la bondad en su cara, como la luz del dia que quita las sombras. Nunca estuvo la luna en mas perfecto y hermoso plenilunio: los altos méritos de Abul-Giux dan de sí olor vivo como el mosco precioso se descubre aun en sellado bote. Cúbrale Dios con su misericordia, con lo cual se sirva ponerle en la eterna morada de las delicias.»\"},{\"heading\":false,\"text\":\"Abul-Walid-Abu-Said no pudo destruir los bandos á beneficio de cuya lucha habia subido al trono: habianse acostumbrado los magnates de Granada á disponer del poder real y á no concederlo sino á aquel que mas favorecia su ambicion: pero como eran muchos y los altos empleos del reino no bastaban para contentar á todos, se dividian, se hacian la guerra, andaban en perpétuas intrigas y conspiraciones, y el rey para entretenerlos se veia obligado, ya que no podia darles otra cosa, á llevarlos contínuamente contra las fronteras cristianas, de las cuales se volvian generalmente cargados con una rica presa.\"},{\"heading\":false,\"text\":\"Pero esto tenia sus inconvenientes: no siempre los de Granada alcanzaban la victoria: habíanselas con los fronteros cristianos, que de padres á hijos estaban avezados á la guerra: entre estos desastres fué uno la batalla de Hins-Ailai, por otro nombre de Fortuna, donde los fronteros de Martos hicieron un horrible destrozo en los moros de Granada, y poco despues los castellanos tomaron con horrible estrago la fortaleza de Tiscar, obligando á rendirse con mil y quinientos hombres al valiente alcaide Muhamad-Hamdum.\"},{\"heading\":false,\"text\":\"Con tales reveses, con los partidos cada dia mas enconados dentro de su reino, Abul-Walid empezó á recelar de su fortuna y á sentir remordimientos.\"},{\"heading\":false,\"text\":\"Parecióle que lo que le acontecia no era otra cosa que un castigo de Dios por la traicion que habia obrado con el otro rey Abul-Giux Nazar, que le estaba reservada igual suerte, y que solo venciendo á los enemigos de Dios podria alcanzar el perdon de sus pecados.\"},{\"heading\":false,\"text\":\"Por eso el rey estaba triste: por eso de una manera tan sombría, en medio de la pompa de su magestad, salia por la Puerta del Juicio de su alcázar de la Alhambra contra los cristianos.\"}]},{\"title\":\"La puerta del juicio. — capítulo III\",\"blocks\":[{\"heading\":false,\"text\":\"Tenia además el rey Abul-Walid otra razon para estar triste y apenado.\"},{\"heading\":false,\"text\":\"Esta razon era un sueño.\"},{\"heading\":false,\"text\":\"Un sueño tenaz de amores.\"},{\"heading\":false,\"text\":\"Durante siete noches consecutivas, y despues de un letargo profundo, habia visto brillar un punto rojo en medio de las tinieblas de su letargo, ensancharse aquel punto, estenderse como un velo de sangre, y luego aquel velo ir cambiando de color hasta volverse de color de rosa, y trocarse al fin en un espacio diáfano circundado de una luz blanca, radiante y dulce.\"},{\"heading\":false,\"text\":\"En medio de aquel espacio habia visto cada una de las siete noches aparecer una figura muy pequeñita, y apenas perceptible, acercarse, crecer, mostrar al fin las formas de una doncella jóven y hermosa que se acercaba con la túnica flotante como una nube impelida por el viento, al divan donde reposaba el rey.\"},{\"heading\":false,\"text\":\"A medida que la doncella se acercaba, el rey sentia ir creciendo un delicado y fresco perfume que parecia emanado de ella, y luego veia claramente sus ojos negros amorosamente fijos en los suyos y sus flotantes cabellos que semejaban ebras de oro, y su frente blanca como el marfil, y cándida y pura como la mirada de la jóven tortolilla que aun no ha amado: veia sus hombros y su garganta desnudos, nacarados, palpitantes, sus manos y sus brazos cruzados en una actitud de pudor sobre su seno, y sus pequeños pies que cubria y descubria caprichosamente la flotante halda de la túnica.\"},{\"heading\":false,\"text\":\"Luego el semblante de la doncella, con los ojos nublados de amor y la fresca y fragante boca entreabierta en un leve suspiro, se acercaba al semblante del rey; pero cuando el rey iba á besarla, la virgen desaparecia y solo quedaba ante el rey, brillando entre las mas densas tinieblas, una cruz de sangre y fuego.\"}]},{\"title\":\"La puerta del juicio. — capítulo IV\",\"blocks\":[{\"heading\":false,\"text\":\"A la primera noche que el rey vió esta vision, despertó encendido de amor y transido de terror.\"},{\"heading\":false,\"text\":\"Túvolo al fin por delirio de su pensamiento, y volvió á reclinarse en los almohadones de su divan.\"},{\"heading\":false,\"text\":\"Pero no logró dormirse.\"},{\"heading\":false,\"text\":\"Veia fijos en él los ojos de la doncella soñada; aquellos ojos que le brindaban amor, y su boca, aquella boca que le prometia delicias.\"},{\"heading\":false,\"text\":\"Al alba se levantó, y ansioso de olvidar aquel sueño que le atormentaba, salió de caza: pero en el monte y en el valle, en la selva y en el altozano, en las márgenes del rio y en el arenoso fondo de los barrancos, en el fondo melancólico de las espesuras, y en el oscuro antro de las grutas, allí, en todas partes veía á la hermosa doncella flotando delante de él; y cuando irritado por la vision tendia hácia ella su arco en el furor de su delirio, la vision de amores desaparecia y quedaba en su lugar una cruz de sangre y fuego.\"},{\"heading\":false,\"text\":\"Durante siete noches el rey vió en sueños á la doncella misteriosa cada vez mas pura, cada vez mas enamorada, cada vez mas resplandeciente.\"},{\"heading\":false,\"text\":\"Durante siete dias que salió á caza pretendiendo borrar la impresion de su sueño en medio de la luz y del aire de los campos y de las montañas, vió en la luz á la doncella enamorada, en la sombra la cruz de fuego, y el aire le trajo el perfume suavísimo, que como emanacion de la doncella misteriosa, respiraba en sus sueños.\"}]},{\"title\":\"La puerta del juicio. — capítulo V\",\"blocks\":[{\"heading\":false,\"text\":\"Vivia en la torre de las Siete bóvedas, en una habitacion alta que le habia concedido el rey, un astrólogo viejísimo; y tanto, que nadie se atrevia á calcular los años de su vida.\"},{\"heading\":false,\"text\":\"Era calvo; tenia el semblante arrugado como un pergamino viejo, sobre el cual ha secado el sol la lluvia: sus ojos pequeños y redondos apenas se veian cubiertos por las largas cerdas de sus cejas, que de una manera estraña caian delante de ellos como un velo; su nariz larga y afilada sobresalia duramente de unas megillas salientes, cubiertas de una piel árida y de color verdoso; su barba era larguísima, cana, de color impuro, y su túnica caia hasta cubrir sus pies en una larga plegadura, como podia haber caido sobre un armazon de caña.\"},{\"heading\":false,\"text\":\"Aquel viejo no habia venido de ninguna parte, ó á lo menos no se sabia de dónde habia venido.\"},{\"heading\":false,\"text\":\"Una noche los guardas de la torre de las Siete bóvedas vieron en los ajimeces de la parte mas alta de la torre un resplandor sanguíneo, y vieron á la luz de la luna salir un humo espeso y luminoso por las ventanas de la cúpula.\"},{\"heading\":false,\"text\":\"El alcaide de la torre avisó de ello al alcaide de palacio, el alcaide de palacio al wazir del rey, el wazir á Abul-Walid.\"},{\"heading\":false,\"text\":\"El rey mandó á su wazir Masud-Almoharaví que fuese á ver lo que era aquello, y fué el wazir; y cuando llegó á la parte alta de la torre encontró al viejísimo astrólogo, que meditaba sobre un cuadrante tendido en una estera.\"},{\"heading\":false,\"text\":\"Maravillóse el wazir de ver aquel espectáculo, y de la misma manera se maravilló el alcaide de la torre.\"},{\"heading\":false,\"text\":\"Aquel viejo imponia espanto.\"},{\"heading\":false,\"text\":\"Además las alfombras, los pebeteros, los divanes, las labores de aquella rica habitacion donde el rey solia pasar algunos momentos, habian desaparecido: quedaban en su lugar unas paredes negras y lustrosas, cubiertas de pinturas de estraños animales y de caracteres desconocidos, rojos los unos; blancos, verdes ó azules los otros: en tablas á lo largo de los muros se veian redomas, cráneos y hosamentas de hombres y animales, arrugadas pieles de serpiente, y enormes libros amarillos apilados en los ángulos y arrojados por el suelo.\"},{\"heading\":false,\"text\":\"A un lado habia un hornillo, y sobre los carbones apagados se veía una enorme ampolla de vidrio, que contenia un licor negro y viscoso.\"},{\"heading\":false,\"text\":\"--¿Qué hombre es ese? preguntó el wazir que era muy soberbio al alcaide desdeñándose de dirigir la palabra al viejo: ¿cómo ha entrado aquí? ¿por qué has permitido que haga tal trasformacion en este aposento que era una alegría?\"},{\"heading\":false,\"text\":\"--¿Sabes tú cómo ha venido tu alma á tu cuerpo ó cómo se separará de ella? dijo el viejo con voz ronca sin levantar los ojos de su cuadrante, y mientras el alcaide guardaba un silencio de asombro.\"},{\"heading\":false,\"text\":\"--¿Es decir, dijo Masud-Almoharaví, que tú has venido á ser el alma de la torre?\"},{\"heading\":false,\"text\":\"--¡Tú lo has dicho! esclamó el viejo.\"},{\"heading\":false,\"text\":\"--¿Pero cómo le habeis dejado entrar tú y los tuyos? dijo con irritacion el wazir al alcaide.\"},{\"heading\":false,\"text\":\"--Nosotros, escelente señor, no hemos visto á este hombre ni yo ni mis soldados. Como has visto, las escaleras y las puertas que hasta aquí conducen estaban cerradas: las llaves las tiene el rey, y tú has traido esas llaves: ese hombre solo ha podido entrar aquí por el aire, y aun así invisible; porque ni yo ni los mios le hemos visto entrar.\"},{\"heading\":false,\"text\":\"--¿Quién eres? dijo con desabrimiento el wazir al viejo.\"},{\"heading\":false,\"text\":\"--Quiero contestarte, dijo el viejo levantándose y dirigiéndose al wazir, aunque tu soberbia merecia que no te diese contestacion: yo soy Abu-Jacub-Al-Hakem-Bilah[78].\"},{\"heading\":false,\"text\":\"--¿De dónde has venido?\"},{\"heading\":false,\"text\":\"--¡De la eternidad! contestó huecamente el sabio.\"},{\"heading\":false,\"text\":\"Irritóse el wazir porque no era hombre á quien se dominaba con facilidad, y acostumbrado á la adulacion de los mas grandes señores, le sentaba muy mal la audaz manera de aquel viejo decrépito.\"},{\"heading\":false,\"text\":\"--¿Será que quieras que yo te envie á la eternidad haciéndote morir azotado por los frenos de los caballos de la torre?\"},{\"heading\":false,\"text\":\"--De la eternidad vengo y á la eternidad voy; dijo el viejo sin dar muestras del mas leve temor: y no serás tú ciertamente el que á la eternidad me envie. He venido aquí, porque esta es la única parte del mundo que me quedaba que visitar, y deseaba ver este alcázar maravilloso y esta ciudad de delicias: me he aposentado donde me ha convenido, y me he hecho huesped del rey de Granada, sin meterme á averiguar si le placeria ó no: como estoy acostumbrado á vivir á mi gusto y me desagradaban los adornos afeminados y las inscripciones de amor que se veian en esta cámara, la he preparado para mi uso como mejor me ha convenido. Además, como me gusta conocer las personas en cuya casa vivo, me ocupaba en levantar el horóscopo del rey de Granada, y en averiguar cuánto tiempo estará levantado este alcázar sobre la tierra. Por lo demás, todo lo que pretendas contra mí es inútil; quédate ó vete, como mejor te plazca, y si quieres puedes decir al rey que si viene á visitarme le recibiré, y que si no quiere venir iré á buscarle. Te he dicho cuanto te tenia que decir.\"},{\"heading\":false,\"text\":\"Y el viejo se reclinó de nuevo en la estera, y volvió á consultar su cuadrante.\"},{\"heading\":false,\"text\":\"--¿Qué haces? dijo con irritacion el wazir; ¿así crees que puedes burlarme?\"},{\"heading\":false,\"text\":\"--Estoy leyendo una parte oscura de tu pasado; dijo el viejo sin levantar los ojos del cuadrante. Por ejemplo, estoy leyendo el nombre de Abul-Fath-Nazir-el-Ferih, tu predecesor en el empleo de wazir del rey.\"},{\"heading\":false,\"text\":\"Púsose pálido Masud-Almoharaví, y mandando al alcaide que se retirase, se quedó solo con Al-Hakem-Bilah.\"},{\"heading\":false,\"text\":\"--Sí, continuó este: veo el nombre del pasado wazir, sobre una tumba, acompañado de pomposos elogios; la enemistad no pasa del sepulcro, y la hora de la muerte de un hombre es tambien la hora en que le elogie su enemigo. Veo dentro de esa tumba un cadáver corroido por un tósigo voraz; averiguando de donde ha salido ese tósigo, veo un cerbatillo humeante, sobre una fuente de plata; esta fuente está puesta sobre una mesa, en que hay pan candeal y frutas y confituras, y licores malditos por Dios y prohibidos á sus creyentes. A ambos lados de la mesa veo dos hombres; el uno es el muerto del sepulcro, pero vivo y lleno de salud y robustez; es Abul-Fath-Nazir-el-Ferih: el otro es un hombre pálido, soberbio, que se domina mal, que encubre mal el ódio que siente hácia el que está sentado frente á él: ese hombre eres tú, tú mismo; pero diez años mas jóven. La habitacion donde estos dos hombres están, forma parte de un hermoso cármen situado en las angosturas del Darro; por último, un hermoso sol de primavera hace pasar sus rayos por los cristales de colores de las ventanas de la cúpula, bajo la cual estais sentados, teniendo en medio una mesa, tú y el anterior wazir.\"},{\"heading\":false,\"text\":\"La altivez de Masud-Almoharaví se habia desplomado, y pálido y convulso escuchaba, sin ser poderoso á pronunciar una sola palabra, al sábio Jacub.\"},{\"heading\":false,\"text\":\"--Es mucho, es mucho lo que veo, añadió el viejo sin mover los ojos del cuadrante; en un bellísimo retrete del mismo cármen hay reclinada en un divan, y sencillamente vestida, una niña de quince años.\"},{\"heading\":false,\"text\":\"¡Y qué hermosa es!\"},{\"heading\":false,\"text\":\"¡Pero tambien cuán terrible!\"},{\"heading\":false,\"text\":\"El espíritu del mal ha llenado su corazon, y en su boca, que todavía no han marchitado los años, es ya fingida la sonrisa.\"},{\"heading\":false,\"text\":\"El hombre que habla con el wazir Abul-Fath-Nazir-el-Ferih, tú, es un envenenador que se finge amigo de su víctima: la niña que allá en su retiro revuelve pensamientos ambiciosos, es una envenenadora, una parricida, un arcángel condenado, que ha servido tranquila á su padre el plato funesto y se ha retirado despues.\"},{\"heading\":false,\"text\":\"El temblor de Masud-Almoharaví crecia; su palidez se habia hecho lívida.\"},{\"heading\":false,\"text\":\"--De los dos amigos, el uno comió del manjar envenenado; el otro se disculpó con haber satisfecho con los otros manjares anteriores su apetito y no comió.\"},{\"heading\":false,\"text\":\"Al dia siguiente apareció muerto en su lecho el wazir Abul-Fath-Nazir-el-Ferih, y sus asesinos, afectando gran sentimiento, se presentaron vestidos de luto al rey Abul-Walid.\"},{\"heading\":false,\"text\":\"Tú llevabas á Ketirah, á la parricida, asida de la mano; tú fuiste quien levantaste de su frente de vírgen maldita el velo tras el cual debia ver el rey Abul-Walid la condenacion de su alma; porque el rey se enamoró de Ketirah.\"},{\"heading\":false,\"text\":\"Pero Ketirah era ambiciosa, y exigió el puesto de la sultana.\"},{\"heading\":false,\"text\":\"Tú á quien el rey habia hecho su wazir, tú que eras el tercero en los amores del rey con la hija del difunto wazir, hiciste que aquel obstáculo desapareciese: la sultana Aleidah, murió por haber aspirado demasiado la fuerte fragancia de un ramillete de flores.\"},{\"heading\":false,\"text\":\"Ketirah fué sultana; pero no sé que señales vieron los parientes de la sultana Aleidah en su semblante, que sospecharon y sospecharon de tí... porque tú eras quien habias presentado al rey la hermosa Ketirah, la tentadora hija del wazir difunto, y Ketirah por muerte de Aleidah habia llegado á ser sultana.\"},{\"heading\":false,\"text\":\"Los bandos de Granada se han aumentado con un bando mas: con los parciales de Mohammet-ebn-Ismail, hijo del walí de Algeciras, primo del rey Abul-Walid, y primo tambien de la difunta sultana Aleidah.\"},{\"heading\":false,\"text\":\"Para desdicha tuya, y digo desdicha, porque tus enemigos son temibles, el jóven Mohammet es ambicioso; hace mucho tiempo que tiene puestos los ojos en la corona de Granada, y amaba además de una manera desesperada á la difunta sultana Aleidah; tú eres un obstáculo á su ambicion, y sabe ó cree que tú eres el asesino de Aleidah.\"},{\"heading\":false,\"text\":\"De modo que es muy posible que en vez de morir yo al rigor de los azotes con que querias castigar en mi un pretendido delito, caigas tú bajo el puñal de los que ven en tí al causador de dos infames y cobardes asesinatos.\"},{\"heading\":false,\"text\":\"¡Es mucho! ¡es mucho lo que he visto al consultar tu horóscopo!\"},{\"heading\":false,\"text\":\"--¿Y me matará el hijo del walí de Algeciras? dijo con acento trémulo el wazir.\"},{\"heading\":false,\"text\":\"--No; morirás como has matado.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿y cuándo?\"},{\"heading\":false,\"text\":\"--Tendrás tiempo para poner en el trono al hijo primogénito de tu señor.\"},{\"heading\":false,\"text\":\"--¿Pues qué, va á morir el buen rey Abul-Walid?\"},{\"heading\":false,\"text\":\"--¿Acaso pretendes que el rey sea eterno?\"},{\"heading\":false,\"text\":\"--Pero es jóven.\"},{\"heading\":false,\"text\":\"--La muerte no cuenta los años.\"},{\"heading\":false,\"text\":\"--¿Y cómo morirá el rey?\"},{\"heading\":false,\"text\":\"--Mas te importa saber cómo morirás tú.\"},{\"heading\":false,\"text\":\"--¿Y yo?..\"},{\"heading\":false,\"text\":\"--Ya lo sabrás.\"},{\"heading\":false,\"text\":\"--¿Nada mas me dirás?\"},{\"heading\":false,\"text\":\"--Nada.\"},{\"heading\":false,\"text\":\"--¿Qué quieres que diga al poderoso Abul-Walid?\"},{\"heading\":false,\"text\":\"--Dile que en su alcázar está quien es mas poderoso que él.\"},{\"heading\":false,\"text\":\"--¿Quieres esclavos que te sirvan, muchachas de ojos negros que te deleiten, perfumes que te embriaguen, manjares que te regalen?\"},{\"heading\":false,\"text\":\"--A lo que vengo vengo, y Dios no me ha enviado á encenagarme en torpezas; ¿crees tú que si yo deseára la muger mas hermosa de la tierra, no la tendria con solo pronunciar una palabra? ¿Y qué son para mí las mugeres de la tierra, ni los arcángeles del cielo, ni las huríes del paraiso?\"},{\"heading\":false,\"text\":\"--¿Con que nada puedo darte?\"},{\"heading\":false,\"text\":\"--¿Has visto que alguna vez dé el esclavo al señor, el pobre al rico, el débil al fuerte? yo soy un águila, tú eres un vencejo. Vete.\"},{\"heading\":false,\"text\":\"El wazir salió sin saber lo que le acontecia y transido de terror.\"},{\"heading\":false,\"text\":\"Dominóse sin embargo, durante su tránsito hasta palacio, y encontrando en él al rey en la magnífica sala de las dos Hermanas, le habló pomposamente del sábio Abu-Jacub, le encareció las maravillas de la transformacion que habia notado en la torre, y tanto que cuando el rey quedó solo dijo profundamente pensativo:\"},{\"heading\":false,\"text\":\"--Dicen los hombres de Dios, y yo lo tengo por cosa cierta, que Satanás anda siempre alrededor de los palacios de los reyes, y que algunas veces se aposenta en ellos y se hace visible.\"},{\"heading\":false,\"text\":\"¿Será ese astrólogo Satanás?\"},{\"heading\":false,\"text\":\"¿Y si es, qué quiere?\"},{\"heading\":false,\"text\":\"¿No soy un rey temeroso de Dios?\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"}]},{\"title\":\"La puerta del juicio. — capítulo VI\",\"blocks\":[{\"heading\":false,\"text\":\"Abul-Walid fué á visitar aquella noche al viejo astrólogo que de una manera tan estraña, y sin pedirle licencia, se habia aposentado en la mejor cámara de la torre de la puerta de su castillo real, y que tan á su gusto habia transformado el interior de aquella cámara.\"},{\"heading\":false,\"text\":\"Abu-Jacub-Al-Hakem habia prometido en una y otra entrevista al rey levantarle figura y descifrarle su horóscopo: pero con el pretesto de que las conjunciones planetarias no eran propicias, alegando otras veces escusas plausibles, el rey no habia logrado saber ni una sola palabra acerca de su destino por boca de Abu-Jacub.\"},{\"heading\":false,\"text\":\"Pero cuando se vió afligido por la ardiente vision, que tentadora y misteriosa se habia repetido para él siete noches consecutivas, el rey, no pudiendo resistir mas, se trasladó una noche á la torre de las Siete bóvedas, y se entró resueltamente en la vivienda de Abu-Jacub.\"},{\"heading\":false,\"text\":\"--Sé á lo que vienes, dijo este.\"},{\"heading\":false,\"text\":\"--Pues bien, puesto que te he honrado en mi córte, que todos te reverencian y que te llamas mi astrólogo, descíframe mi sueño.\"},{\"heading\":false,\"text\":\"--Ese sueño es una tentacion, rey Abul-Walid; una tentacion que pone á prueba tu nobleza y tu caridad.\"},{\"heading\":false,\"text\":\"--No te comprendo.\"},{\"heading\":false,\"text\":\"--Vas á comprenderme.\"},{\"heading\":false,\"text\":\"Y el sabio abrió uno de los ajimeces.\"},{\"heading\":false,\"text\":\"--Ven acá, dijo al rey.\"},{\"heading\":false,\"text\":\"El rey fué al ajimez.\"},{\"heading\":false,\"text\":\"--Mira hácia el poniente.\"},{\"heading\":false,\"text\":\"--Nada veo, es la noche muy oscura.\"},{\"heading\":false,\"text\":\"Abu-Jacub tocó los ojos del rey.\"},{\"heading\":false,\"text\":\"--Vuelve á mirar, dijo.\"},{\"heading\":false,\"text\":\"--Veo las fronteras de mi reino y la villa fronteriza de Martos.\"},{\"heading\":false,\"text\":\"--Mira aun.\"},{\"heading\":false,\"text\":\"--Veo una casa de solar cristiana: sobre su puerta, en un blason, hay una cruz roja.\"},{\"heading\":false,\"text\":\"--¿No has visto una cruz roja en tu sueño?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Y no crees que esa cruz roja que se vé sobre el blason de la casa del corregidor Sancho de Arias tiene relacion con tu sueño?\"},{\"heading\":false,\"text\":\"--Sí; ¿pero qué quiere decir esa cruz?\"},{\"heading\":false,\"text\":\"--Esa cruz quiere decir que una cristiana causará tu muerte, poderoso rey Abul-Walid.\"},{\"heading\":false,\"text\":\"--¿Es acaso esa cristiana la doncella que yo he visto en sueños?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--Quiero verla.\"},{\"heading\":false,\"text\":\"--Vas á verla en una ocasion solemne: mira.\"},{\"heading\":false,\"text\":\"El rey miró.\"},{\"heading\":false,\"text\":\"--Veo un ancho dormitorio: en aquel dormitorio un enorme lecho; en aquel lecho un caballero anciano, con la cabeza cubierta por un vendaje sangriento, y espirante.\"},{\"heading\":false,\"text\":\"A un lado del lecho hay un faqui cristiano leyendo en una Biblia; al otro lado una muger sencillamente vestida, vuelta de espaldas, que parece orar y tener asidas las manos del herido.\"},{\"heading\":false,\"text\":\"--No veo á la muger de mi sueño; dijo el rey.\"},{\"heading\":false,\"text\":\"--Si por cierto: es esa que está vuelta de espaldas; como se encuentra replegada sobre el lecho no puedes admirar su gentileza; pero tiempo tendrás de verla.\"},{\"heading\":false,\"text\":\"--¿Y qué significa lo que allí sucede?\"},{\"heading\":false,\"text\":\"--Significa que el buen corregidor Sancho de Arias muere á consecuencia de heridas.\"},{\"heading\":false,\"text\":\"--¡Heridas!\"},{\"heading\":false,\"text\":\"--Sí, heridas recibidas hace tres dias en las fronteras de tu reino.\"},{\"heading\":false,\"text\":\"--No tengo noticia de ningun encuentro con los cristianos.\"},{\"heading\":false,\"text\":\"--Tu alcaide de Loja, que intentó una algara sobre la frontera, ha sido vencido, y como prudente no te ha dado noticia de su desastre: ha dejado sobre la frontera cristiana la flor de sus caballeros muertos á manos de los vecinos de Martos, á quienes acaudillaba su corregidor; pero el desdichado no gozó el triunfo; recibió algunos hachazos en la cabeza de manos del tremendo Alí-Athar, tu alcaide en Loja, y hélo ahí espirante. Escucha lo que se habla en esa habitacion.\"},{\"heading\":false,\"text\":\"--Nada oigo; dijo el rey: la vega y las montañas están envueltas en el mas profundo silencio.\"},{\"heading\":false,\"text\":\"Tocó Abu-Jacub los oidos del rey y repitió:\"},{\"heading\":false,\"text\":\"--Escucha.\"},{\"heading\":false,\"text\":\"--Oigo al faqui cristiano rezar en rumy[79]; oigo el sobrealiento y la fatiga del herido que está dominado por un letargo.\"},{\"heading\":false,\"text\":\"--Escucha aun.\"},{\"heading\":false,\"text\":\"--La muger llora.\"},{\"heading\":false,\"text\":\"--Y el herido despierta y parece que cobra aliento, como si le ayudára la mano de Dios.\"},{\"heading\":false,\"text\":\"El rey siguió escuchando.\"},{\"heading\":false,\"text\":\"Hé aquí lo que el rey oyó:\"},{\"heading\":false,\"text\":\"--Padre, dijo el herido: sé que voy á morir, y que necesito de vuestro auxilio y de vuestra presencia: pero veo á mi lado á mi hija; siento su mano sobre mis manos, y recuerdo que antes de morir necesito confiarla un importante secreto, que solo sabe Dios... y yo; y que solo ella debe saber. Dejadnos solos, padre mio, que cuando haya concluido con este último deber que me prescribe mi conciencia, volveré á ampararme de vos.\"},{\"heading\":false,\"text\":\"El fraile salió.\"},{\"heading\":false,\"text\":\"Quedaron solos el anciano que moria, y la jóven que de verle morir lloraba.\"}]},{\"title\":\"La puerta del juicio. — capítulo VII\",\"blocks\":[{\"heading\":false,\"text\":\"--Levántate y siéntate al lado de mi lecho, María, dijo Sancho de Arias.\"},{\"heading\":false,\"text\":\"Al levantarse María, al sentarse, dejó ver al rey Abul-Walid su semblante.\"},{\"heading\":false,\"text\":\"--¡Es ella! ¡es ella! la hermosísima y casta vírgen de mis sueños de amores: esclamó el rey.\"},{\"heading\":false,\"text\":\"--Escucha, dijo secamente Abu-Jacub-Al-Hakem.\"},{\"heading\":false,\"text\":\"--Tienes quince años, María, dijo el moribundo.\"},{\"heading\":false,\"text\":\"--Pluguiera á Dios que no hubiera nacido, señor, si habia de veros en tan miserable estado.\"},{\"heading\":false,\"text\":\"--Muero como debe morir un cristiano y un caballero; dijo Sancho de Arias: defendiendo á mi Dios, á mi patria y á mi rey. Además que ya mis años son muchos, y confio en que Dios en su misericordia me reciba en su seno: como hombre he cumplido con arreglo á la ley de Dios; como ministro del rey, la vara de la justicia no se ha quebrado ni torcido en mis manos; respecto á mis semejantes, tú eres una prueba de que he tenido caridad hasta para con mis enemigos.\"},{\"heading\":false,\"text\":\"--¡Yo, señor!...\"},{\"heading\":false,\"text\":\"--Sí; ha llegado el solemne momento en que lo sepas. No eres mi hija.\"},{\"heading\":false,\"text\":\"--¡Pués de quien soy yo hija, señor! esclamó María.\"},{\"heading\":false,\"text\":\"--Eres hija de moro, de un infiel del reino de Granada.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡señor!\"},{\"heading\":false,\"text\":\"--La verdad es dura, pero es necesario que la sepas. Hace diez años era yo alcaide por el rey del castillo de Alcaudete. Tenia una buena esposa y dos hijas tan hermosas como tú, tan puras como tú, como tú tan buenas. Llamóme por entonces el adelantado de Jaen, y obedeciendo como debia, acudí á su llamamiento.\"},{\"heading\":false,\"text\":\"Apenas habia llegado á las puertas de Jaen, cuando la campana del castillo fronterizo de la Guardia empezó á tocar apresuradamente á rebato.\"},{\"heading\":false,\"text\":\"Poco despues, y cuando acababa de entrar en casa del adelantado, llegó un corredor cubierto de sudor, de polvo y de sangre, y mi corazon al verle se heló. Era un vecino de Alcaudete: los moros habian pasado la frontera en número formidable, habian embestido la villa y el castillo, y los habian entrado á sangre y fuego; los vecinos, sorprendidos, apenas habian tenido tiempo de huir, y los que quedaron dentro fueron degollados.\"},{\"heading\":false,\"text\":\"A aquella noticia, los vecinos de Jaen, los de la Guardia, los de los lugares cercanos, corrieron á las armas, juntóse un escuadron de infantería con cuatro banderas y doscientos rocines, y todos marchamos desalados en socorro de Alcaudete.\"},{\"heading\":false,\"text\":\"Pero llegamos tarde: los fugitivos que se nos unian nos daban noticias aterradoras: los moros habian saqueado la villa, la habian puesto fuego, habian degollado á los hombres y á las mugeres viejas, y se habian llevado cautivas á las mugeres jóvenes y á las niñas.\"},{\"heading\":false,\"text\":\"Cuando yo entré en el castillo, lo primero que encontré fué el cadáver de mi esposa: mas allá mis dos hijas abrazadas y muertas al pié del muro debajo de una ventana: segun las señales, las desgraciadas se habian arrojado por aquella ventana, prefiriendo la muerte de los mártires á la deshonra y al alejamiento de la ley de Jesucristo entre los infieles.\"},{\"heading\":false,\"text\":\"El anciano pronunciaba estas palabras con voz lenta y lúgubre, pero de una manera terrible, sin derramar una sola lágrima.\"},{\"heading\":false,\"text\":\"El rey Abul-Walid, desde la torre de las Siete bóvedas, avanzado al ajimez, pálido, anhelante, con los ojos inmóviles, presenciaba aquella escena que pasaba tan lejos de él, de la misma manera que si hubiera estado en el aposento donde el corregidor de Martos moribundo hacia aquella revelacion á la misteriosa virgen de sus sueños, y lo oia y lo veia todo por virtud de la ciencia de Abu-Jacub-Al-Hakem.\"},{\"heading\":false,\"text\":\"--Yo juré, continuó el anciano, sobre la sangre de las prendas de mi alma, vengarlas de los infieles; y desde entonces, acometí en continuas correrías las fronteras del reino de Granada; asalté aldeas, las puse á sangre y fuego, y no me hartaba, no me hartaba de sangre, porque toda me parecia poca para vengar la de mi esposa y la de mis hijas.\"},{\"heading\":false,\"text\":\"Una noche... una noche lóbrega y terrible, pasé la frontera y me acerqué por atajos y trochas á la villa de Yllora.\"},{\"heading\":false,\"text\":\"En su castillo habia fiesta: un príncipe moro habia ido á aquel pueblo á gozar de la pureza de sus aguas y de sus aires y á recobrar la salud quebrantada: le divertian con una zambra.\"},{\"heading\":false,\"text\":\"Los moros descuidados, sin recelar que hubiese peligro en una fortaleza en que se encerraban centenares de hombres llevados por el príncipe infiel en su guarda, no velaron como debian en las murallas: mis buenos fronteros arrimaron en silencio sus escalas á los muros, y treparon y saltaron dentro del castillo y yo delante de ellos.\"},{\"heading\":false,\"text\":\"Un momento despues los cantos moriscos se habian convertido en gritos de combate y ayes de agonía. Sorprendidos los moros creyendo tener sobre sí todo el ejército de Castilla, huyeron despavoridos; y yo y mis gentes nos cebamos en su alcance. Fué una buena carnicería de infieles, que llenó de luto á Granada, y la presa magnífica; porque el príncipe moro habia llevado consigo grandes riquezas en muebles, en tapices, en joyas y en dinero. Pero el principal tesoro que encontré, fuiste tú, María.\"},{\"heading\":false,\"text\":\"--¡Yo! esclamó la jóven.\"},{\"heading\":false,\"text\":\"--Sí; cuando ya cansados de matar y de amontonar riquezas nos retirábamos, al pasar por delante de una cámara, oí el triste llanto de un niño abandonado.\"},{\"heading\":false,\"text\":\"Entré. En una magnífica cuna, cubierta de amuletos segun el uso moro, ví una niña que al acercarme yo me tendió sus bracitos.\"},{\"heading\":false,\"text\":\"Y ¿qué daño ha hecho á nadie esta infeliz criatura? me dije. No permita Dios que yo tiña mis manos en sangre inocente, ni que robe un alma al cielo.\"},{\"heading\":false,\"text\":\"Y te tomé en mis brazos y te llevé sobre el caparazon de mi caballo á Alcaudete; y te mande bautizar, y te llamaste María en ofrenda á la santa Vírgen, y te adopté por hija, y pensando yo en que algun dia serias muger, y amarias...\"},{\"heading\":false,\"text\":\"--¡Ah, señor!\"},{\"heading\":false,\"text\":\"--Sí; que amarias... y has amado; amas.\"},{\"heading\":false,\"text\":\"--Es verdad.\"},{\"heading\":false,\"text\":\"--Amas á un buen hidalgo, á un valiente: á un mozo temeroso de Dios, á Gonzalo Nuñez.\"},{\"heading\":false,\"text\":\"--Es verdad, dijo María ruborizándose.\"},{\"heading\":false,\"text\":\"Al escuchar Abul-Walid que María amaba, los celos, y unos celos crueles, vengativos, llenaron su alma.\"},{\"heading\":false,\"text\":\"--¡Ama! esclamó roncamente: ¡ama la hermosa vírgen de mis sueños!\"},{\"heading\":false,\"text\":\"--Pero tú matarás su amor; dijo con un acento singular el sombrío Abu-Jacub.\"},{\"heading\":false,\"text\":\"--Escuchemos, escuchemos, dijo el rey.\"},{\"heading\":false,\"text\":\"Sancho de Arias y María habian guardado por un breve espacio silencio: él como quien cansado reposa para tomar nuevas fuerzas; ella dominada por lo solemne de la revelacion del anciano moribundo.\"},{\"heading\":false,\"text\":\"--Amas, y yo apruebo tu amor: Gonzalo Nuñez es digno de tí, y tú eres digna de él. Yo he conocido vuestro amor, aunque me lo has ocultado.\"},{\"heading\":false,\"text\":\"--¡Ah, señor! él es muy pobre, y esperaba á que el rey le diese un oficio para poder casarse conmigo.\"},{\"heading\":false,\"text\":\"--Si él es pobre, tú eres rica, María.\"},{\"heading\":false,\"text\":\"--¡Rica yo!\"},{\"heading\":false,\"text\":\"--Sí; ya te he dicho que cuando te adopté pensé en que un dia serias muger, en que amarias, en que te casarias, y quise que tuvieses una buena dote: pensando en esto, guardé para tí un tesoro que encontré en la habitacion donde habias quedado abandonada.\"},{\"heading\":false,\"text\":\"--¡Un tesoro!\"},{\"heading\":false,\"text\":\"--Sí; y un tesoro de inestimable valor. Busca debajo de mi almohada. Encontrarás una bolsa.\"},{\"heading\":false,\"text\":\"--Héla aquí: dijo María sacando de debajo de la almohada una bolsa de seda á manera de saco, cerrada por dos cordones.\"},{\"heading\":false,\"text\":\"--Abre la bolsa y toma una llave que encontrarás en ella.\"},{\"heading\":false,\"text\":\"María sacó de la bolsa una pequeña llave.\"},{\"heading\":false,\"text\":\"--Abre ahora aquel armario, dijo el anciano señalándola uno que habia al fondo de la alcoba.\"},{\"heading\":false,\"text\":\"La jóven se levantó, fué al armario y le abrió.\"},{\"heading\":false,\"text\":\"--Está vacío: dijo.\"},{\"heading\":false,\"text\":\"--No importa, tira hácia tí de la primera tabla; sácala.\"},{\"heading\":false,\"text\":\"María desencajó la tabla.\"},{\"heading\":false,\"text\":\"--Mira bien al fondo del armario, dijo Sancho de Arias. ¿Qué ves?\"},{\"heading\":false,\"text\":\"La jóven miró con cuidado.\"},{\"heading\":false,\"text\":\"--Veo un cajon muy encajado y muy disimulado, y en el centro de él un agujero.\"},{\"heading\":false,\"text\":\"--Mete la misma llave del armario y tira.\"},{\"heading\":false,\"text\":\"María tiró.\"},{\"heading\":false,\"text\":\"--Saca lo que encuentres dentro.\"},{\"heading\":false,\"text\":\"María metió la mano en el cajon, y encontró otra bolsa de seda pero mas grande que la que habia encontrado bajo la almohada y pesadísima con relacion á su volúmen.\"},{\"heading\":false,\"text\":\"Aquella bolsa estaba tambien cerrada con un cordon y en un papel cosido á ella estaban escritas estas palabras. «Dote de María.»\"},{\"heading\":false,\"text\":\"Además la bolsa estaba recamada con arabescos de oro y plata.\"},{\"heading\":false,\"text\":\"--Abre la bolsa, dijo el moribundo, y mira lo que contiene.\"},{\"heading\":false,\"text\":\"Abrió la bolsa María, metió la mano, encontró un objeto, y le sacó.\"},{\"heading\":false,\"text\":\"Era un largo y pesado collar de gruesas perlas, con broche de diamantes y rubíes, y en el centro pendiente de la perla mas gruesa, una cruz de oro, cubierta de diamantes.\"},{\"heading\":false,\"text\":\"--¡Oh, Dios mio! dijo la jóven, ¿y habeis pasado estrecheces, señor, teniendo esta rica joya?\"},{\"heading\":false,\"text\":\"--Era parte de tu dote, pero aun queda mas.\"},{\"heading\":false,\"text\":\"La jóven metió la mano y sacó dos magníficos brazaletes, cincelados, esmaltados, cuajados de pedrería, que estaban unidos el uno al otro por una cinta de seda.\"},{\"heading\":false,\"text\":\"María miró sin codicia aquellas dos admirables joyas, como sin ella habia mirado el collar y las puso junto á este á los pies del lecho del moribundo.\"},{\"heading\":false,\"text\":\"Volvió á meter la mano y sacó dos arracadas tan ricas y tan maravillosas como el collar y los brazaletes; sucesivamente sacó veinticinco sortijas de grande precio atadas en una cinta, dos ajorcas y un ceñidor de oro, perlas, diamantes y rubíes.\"},{\"heading\":false,\"text\":\"El aderezo completo por último de una mora riquísima, de una sultana.\"},{\"heading\":false,\"text\":\"Todas aquellas joyas puestas sobre el lecho de Sancho de Arias brillaban, relucian, arrojaban destellos fúlgidos al recibir la móvil luz de la lámpara que alumbraba el dormitorio.\"},{\"heading\":false,\"text\":\"--Como ya te he dicho, continuó el moribundo, esas joyas las encontré en la misma habitacion en que tú estabas, en una arca en que habia ropas de muger, que no tomé por embarazosas. Su valor me maravilló; pero lo que me maravilló mas, fué el ver en la casa de un infiel la hermosa cruz del collar. ¿Qué muger podia haber llevado aquella alhaja? Sábelo Dios; pudo ser tú madre.\"},{\"heading\":false,\"text\":\"--¡Mi madre!\"},{\"heading\":false,\"text\":\"--Dios lo sabe.\"},{\"heading\":false,\"text\":\"--¿Pero no sabeis quienes fueron mis padres?\"},{\"heading\":false,\"text\":\"--Por la habitacion en que te encontré, por la cuna en que estabas, por los amuletos que te cubrian á la usanza mora, juzgué que debias ser hija de aquel príncipe moro, que habia escapado al verse sorprendido por mis fronteros... Pero despues nada supe. ¿Y qué te importa? vale mas que pases como hija de un hidalgo honrado y cristiano, que no que sepan que eres hija de un infiel, por mas que este infiel fuese príncipe, rico y poderoso. Este secreto debe quedarse entre nosotros. Conmigo le guardará la tumba. Guárdale tú si no es que quieres, cediendo á la soberbia humana, aparecer como hija de uno de los grandes de la tierra, por mas que ese grande, como infiel, esté desheredado del cielo.\"},{\"heading\":false,\"text\":\"--¡Ah! no, no; yo no tengo vanidad, padre mio: y esas joyas...\"},{\"heading\":false,\"text\":\"--Servirán para asegurar el pan á tus hijos si te casas con Gonzalo Nuñez.\"},{\"heading\":false,\"text\":\"--¡Gonzalo Nuñez! sabe Dios lo que habrá sido de él. Hace un año, padre, que se despidió de mí: he recibido una sola carta suya allá desde la frontera de Murcia, donde estaba sirviendo el rey de Aragon, y... no he vuelto á tener noticias suyas. Acaso ha muerto buscando fortuna para ser mi esposo.\"},{\"heading\":false,\"text\":\"--¡Muerto! ¿quién sabe? y en fin, si ha muerto, ha muerto como bueno, como muero yo.\"},{\"heading\":false,\"text\":\"--¡Oh, Dios mio! ¡si eso fuera cierto!..\"},{\"heading\":false,\"text\":\"--Si fuera cierto, seria asunto de sentirlo, pero no de desesperarse. Eres jóven, hermosa y rica, y no te faltaría un nuevo amor.\"},{\"heading\":false,\"text\":\"--Pero yo no puedo, yo no debo amar á otro mas que á él.\"},{\"heading\":false,\"text\":\"--¡Que no debes!... ¿acaso, María, has sido débil? ¿acaso has olvidado lo que no debe olvidar jamás una doncella honrada?\"},{\"heading\":false,\"text\":\"--¡Ah! ¡no, no, padre mio! repuso la jóven poniéndose densamente encendida. Vuestra hija no ha olvidado jamás lo que debe á vuestra honra, ni él jamás ha pretendido de mí nada deshonroso.\"},{\"heading\":false,\"text\":\"Al escuchar estas palabras el rey Abul-Walid respiró recio como aquel que se vé libre de una carga, y aprovechando un momento en que guardaron silencio el moribundo y la jóven, dijo á Abu-Jacub sin apartar la vista de aquel remoto dormitorio de Martos.\"},{\"heading\":false,\"text\":\"--Amor de niños; amor que pasa con la ausencia; que no sobrevive al amante muerto. Y es posible que su amante haya muerto.\"},{\"heading\":false,\"text\":\"--No, no ha muerto, dijo con acento seco y duro Abu-Jacub: aparta por un momento la vista de María y de Sancho de Arias y fíjala en el camino de Castilla, á la frontera, cerca de Martos.\"},{\"heading\":false,\"text\":\"--Está la noche muy oscura y no veo, dijo el rey.\"},{\"heading\":false,\"text\":\"--Mira: dijo el mago tocando de nuevo los ojos de Abul-Walid.\"},{\"heading\":false,\"text\":\"Entonces el rey, á pesar de la oscuridad, vió un largo y estrecho camino y galopando por él, cerca de Martos, dos ginetes armados de todas armas, caladas las viseras, las lanzas en las cujas, y llevando cada uno de ellos sobre la grupa de su caballo una maleta.\"},{\"heading\":false,\"text\":\"--¿Vienen acaso esos cristianos, dijo el rey, de la frontera de Murcia á avisar á María de que su amante vive?\"},{\"heading\":false,\"text\":\"--Mas que eso: el que cabalga delante con arnés tranzado y espuela de caballero, es el mismo Gonzalo Nuñez; el que cabalga detrás, su escudero; lo que llevan en esas dos maletas, oro puro. El amante de María vuelve armado caballero por el rey don Jaime II de Aragon, honrado por sus hazañas y rico por las presas que ha hecho á los moros de Murcia. Síguelos, y verás cómo sin vacilar entran en la villa, cómo antes de ir á su propia casa Gonzalo Nuñez llega á la casa del corregidor Sancho de Arias y llama á grandes aldabadas; María le abre, un escudero le dice que su amo está espirando, y el jóven á pesar de lo embarazoso y pesado de la armadura, sube á saltos las escaleras, cruza y atraviesa la sala; ya entra en el dormitorio y se queda helado de espanto al ver la situacion en que se encuentra el que cree padre de su amada.\"},{\"heading\":false,\"text\":\"Escucha ahora y mira.\"},{\"heading\":false,\"text\":\"--¿Qué es esto, señor? dijo Gonzalo Nuñez levantándose la visera: ¿cómo os encuentro así?... ¿pero Dios no querrá?...\"},{\"heading\":false,\"text\":\"--Dios lo quiere, y llegais muy á tiempo, Gonzalo: Dios os trae; la vida se me acaba y mi hija va á quedar huerfana.\"},{\"heading\":false,\"text\":\"--No lo será mientras yo viva, señor.\"},{\"heading\":false,\"text\":\"--Sí, vos sereis su esposo.\"},{\"heading\":false,\"text\":\"--¡Cómo, señor! ¿sabeis?\"},{\"heading\":false,\"text\":\"--Lo sé todo; sé que por su amor habeis ido á buscar fortuna á cambio de vuestra vida.\"},{\"heading\":false,\"text\":\"--Y la he encontrado, señor, vuelvo rico, y alentando la esperanza que vos habeis realizado de que María fuese mi esposa.\"},{\"heading\":false,\"text\":\"--Sí; hijos mios, sí, y escuchad: casaos inmediatamente.\"},{\"heading\":false,\"text\":\"--¡Cómo! dijo María mientras Gonzalo guardaba un silencio de asentimiento egoista; ¿caliente aun vuestro cadáver?...\"},{\"heading\":false,\"text\":\"--Lleva por mí tu luto en el corazon, no en los vestidos, María; no esperes huerfana y doncella por cumplir con el juicio de las gentes el que pase un año despues de mi muerte. Únete á él, y para que tengas una obligacion de hacerlo... acercaos, hijos mios, acercaos.\"},{\"heading\":false,\"text\":\"Los jóvenes se acercaron y el anciano asió sus manos y las unió.\"},{\"heading\":false,\"text\":\"Entonces los dos jóvenes cayeron de rodillas.\"},{\"heading\":false,\"text\":\"--Vuestro padre moribundo os une, dijo Sancho de Arias con voz conmovida y cada vez mas débil: que os bendiga Dios, hijos mios, y que apenas muerto yo... ¿pero á qué esperar mi muerte?.. ¿no hay en la casa un sacerdote?...\"},{\"heading\":false,\"text\":\"Pero como si Dios no hubiera querido que Sancho de Arias llevase á la tumba este consuelo, fatigado en demasia por la conversacion que habia sostenido, le atacó una tos violenta, se le abrieron las heridas, y arrojó un vómito de sangre: tras el vómito vino la muerte.\"},{\"heading\":false,\"text\":\"--¿A qué quieres presenciar los llantos y la desolacion de esa casa? dijo el mago borrando la vision de los ojos del rey que solo vieron el fondo oscuro de la noche.\"},{\"heading\":false,\"text\":\"--Pero se casará la vírgen de mis sueños con ese cristiano? dijo pálido y convulso Abul-Walid.\"},{\"heading\":false,\"text\":\"--No, si tú quieres, dijo el mago: pero para evitarlo será necesario que levantes tu estandarte, que reunas tus gentes de guerra y que caigas como una tempestad sobre la villa fronteriza de Martos.\"},{\"heading\":false,\"text\":\"--Caeré, caeré, gritó Abul-Walid, y la doncella de la frente pálida no será de otro que será mia.\"},{\"heading\":false,\"text\":\"Y arrojando su bolsa al mago, salió de su morada y se precipitó rápidamente por las escaleras de la torre.\"},{\"heading\":false,\"text\":\"--Vé, vé, Abul-Walid-Abu-Said, dijo soltando una carcajada horrible el mago: eres mio: vas á buscar tu condenacion en esa muger.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Incitado, pues, por el amor de María, y con el pretesto de hacer una algara en las fronteras cristianas, salió el rey Abul-Walid por la Puerta del Juicio de la Alhambra, desplegado su estandarte de guerra y rodeado de sus caballeros.\"}]},{\"title\":\"La puerta del juicio. — capítulo VIII\",\"blocks\":[{\"heading\":false,\"text\":\"¡Qué hermosa está una virgen cuando se atavia para sus bodas!\"},{\"heading\":false,\"text\":\"¡Qué bello sobre su frente de azucena, el encendido color del clavel, que enciende un enamorado y misterioso pensamiento!\"},{\"heading\":false,\"text\":\"¡Oh! ¡y cuán hermosa estaba María!\"},{\"heading\":false,\"text\":\"Han pasado tres dias desde la muerte de Sancho de Arias, y el dolor que esta muerte la ha causado, dá á sus ojos, á sus megillas, á su boca, una dulce languidez que la hace mas hermosa.\"},{\"heading\":false,\"text\":\"La impaciencia de Gonzalo ha triunfado, ayudada por el último deseo de su padre, y acaso tal vez por una impaciencia de que ella no quiere darse cuenta.\"},{\"heading\":false,\"text\":\"Se está engalanando: se está poniendo sobre sus galas las magníficas joyas que habia guardado para ella Sancho de Arias.\"},{\"heading\":false,\"text\":\"Los espera el altar: despues caerá sumisa y enamorada entre los brazos de su esposo, y al dia siguiente guardará aquellas joyas y aquellas galas para vestirse un luto justo.\"},{\"heading\":false,\"text\":\"Pero la vírgen no debe ir al altar enlutada: seria un casamiento demasiado lúgubre, al que pareceria asistir como un testigo invisible la muerte.\"},{\"heading\":false,\"text\":\"Una anciana, que la ha servido de nodriza, la engalana llorando.\"},{\"heading\":false,\"text\":\"Porque la esperiencia fria dice á la anciana que cuando una muger se casa, entra en una nueva via á cuyo fin puede encontrar el mayor de los infortunios.\"},{\"heading\":false,\"text\":\"El infortunio del corazon.\"},{\"heading\":false,\"text\":\"Nadie mas asiste al atavío de la hermosa.\"},{\"heading\":false,\"text\":\"Sus cabellos destrenzados, sus hombros y su seno desnudos, no la obligan á avergonzarse, porque quien la vé es casi su madre: ha visto nacer aquellos encantos; nada hay en María que la sea ageno: la cree su hechura, y la jóven no cree que la ven los ojos de otro, porque los ojos de la anciana son como si fueran sus ojos.\"},{\"heading\":false,\"text\":\"Y sin embargo, hay una espresion de orgullo en los ojos de la nodriza, y,\"},{\"heading\":false,\"text\":\"--¿Qué hermosa eres? esclama: ¿dichoso el hombre para quien Dios te ha criado? ¡Oh! ¿qué feliz será?\"},{\"heading\":false,\"text\":\"Y la jóven se sonrie y se ruboriza.\"},{\"heading\":false,\"text\":\"Y entre tanto el hombre que vá á ser feliz, espera impaciente en otra habitacion, rodeado de sus deudos y de sus amigos, á que la desposada acabe de ataviarse, y cuenta el tiempo por los latidos de su corazon, y en cada ruido que llega hasta él, cree percibir el ruido de los pasos de su amada.\"},{\"heading\":false,\"text\":\"Hace un hermoso dia: Dios le bendiga.\"},{\"heading\":false,\"text\":\"El sol ha amanecido mas puro que nunca.\"},{\"heading\":false,\"text\":\"Parece que el sol ama tambien y toma parte en las bodas.\"},{\"heading\":false,\"text\":\"La campana de la iglesia llama á la oracion.\"},{\"heading\":false,\"text\":\"Los pájaros cantan en el huerto.\"},{\"heading\":false,\"text\":\"Las brisas de la mañana agitan con blando ruido las enredaderas del balcon.\"},{\"heading\":false,\"text\":\"¡Oh! ¿qué dia tan hermoso?\"},{\"heading\":false,\"text\":\"Y las jóvenes que van á la iglesia á oir la primera misa, dicen con acento de enamorada codicia á su vecina:\"},{\"heading\":false,\"text\":\"--Hoy se casa María, la hija del difunto corregidor.\"},{\"heading\":false,\"text\":\"--¿Con quién se casa? dice una vieja.\"},{\"heading\":false,\"text\":\"--Con el hijo de Nuño Nuñez, con Gonzalo.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡bendígalos Dios! dice la vieja: ¡tal para cual!\"},{\"heading\":false,\"text\":\"Y la noticia cunde por la villa, y hay quien deja el trabajo por ver casarse á la doncella mas hermosa de la frontera, con el galan que en toda la frontera se conoce por mas gentil y mas bravo.\"},{\"heading\":false,\"text\":\"Y hay quien añade:\"},{\"heading\":false,\"text\":\"--El difunto corregidor no ha querido que le entierren hasta que esté casada su hija con Gonzalo Nuñez.\"},{\"heading\":false,\"text\":\"Y otro dice:\"},{\"heading\":false,\"text\":\"--Y ha querido que su hija vaya hecha un ascua de oro, con ciertas alhajas que él allá en otro tiempo tomó á los moros. Ya vereis, ya vereis como María viene hecha una imágen.\"},{\"heading\":false,\"text\":\"La iglesia se va llenando de gente: y los monaguillos suben á la torre, para repicar cuando asomen los novios allá por lo último de la calle Real, y el sacristan saca el terno mas lujoso para el señor beneficiado, y luego cubre de blandones el altar mayor, y manda avisar al organista.\"},{\"heading\":false,\"text\":\"Porque el señor Gonzalo Nuñez ha vuelto rico de la guerra, y quiere casarse como un rey, con música y luces, y la iglesia colgada de damasco rojo con espejuelos.\"},{\"heading\":false,\"text\":\"Y cada vez van acudiendo mas muchachas engalanadas, y la iglesia se llena y todos esperan.\"},{\"heading\":false,\"text\":\"Y el rey Abul-Walid-Abu-Said, desgarra entre tanto los hijares de su corcel, y blande la lanza de dos hierros, y mira ansioso el camino adelante, y tras él van sus moros de Granada, sus moros, que cubren el camino como una larga serpiente herizada de lanzas, y que corren, corren, vuelan como el semoum, detrás de su rey que cabalga el delantero, y de su estandarte real, que ondea junto al pendoncillo de la lanza del rey.\"},{\"heading\":false,\"text\":\"--Y ¡corre, corre que el sol sube! grita Abul-Walid á su caballo; ¡corre que tocan á fiesta las campanas de Martos, y ese toque me espanta! ¡corre, Lucero mio, y te regalaré un pretal de oro, y te coronaré de garzotas de diamantes! ¡corre, Lucero mio, corre, que me roba el cristiano la vírgen de la frente pálida!\"},{\"heading\":false,\"text\":\"Y cada moro dice á su caballo:\"},{\"heading\":false,\"text\":\"--¡Corre, corre, que el rey vuela! ¡corre, que allí están la doncellas cristianas y la rica presa, y los cautivos que se truecan por oro! ¡corre, corcel mio, corre, que el rey vuela, y allí en la cercana villa, están el amor y la fortuna!\"},{\"heading\":false,\"text\":\"Y pasan como un torbellino y zumban como el huracan, y los labriegos al verlos acercarse huyen despavoridos hácia los muros gritando:\"},{\"heading\":false,\"text\":\"--¡Los moros! ¡al arma la tierra! ¡los moros de Granada vienen en busca de nuestras mugeres y de nuestra plata!\"},{\"heading\":false,\"text\":\"Y allá van los campesinos que huyen, y el rey moro que vuela, y la gente que le sigue.\"},{\"heading\":false,\"text\":\"Y las campanas de la villa siguen repicando.\"},{\"heading\":false,\"text\":\"Y el sol inundando la tierra con su primer esplendor de la mañana.\"},{\"heading\":false,\"text\":\"Y los pájaros cantando en las arboledas.\"},{\"heading\":false,\"text\":\"Y entre tanto por la calle Real de la villa, hácia la plaza, vá María, hermosa y resplandeciente, modesta y pálida, los ojos en el suelo, agitado el seno, pensando á un tiempo en su amor y en su padre muerto, y en aquel otro padre moro á quien no conoce, y en las alhajas que la adornan cree sentir el espíritu de su madre.\"},{\"heading\":false,\"text\":\"Y el amor, y el dolor, y la duda, y la ansiedad, hacen correr de tiempo en tiempo dos lágrimas tranquilas por sus megillas.\"},{\"heading\":false,\"text\":\"Y la rodean dueñas y doncellas, y se asoman á las ventanas para mirarla, y los que la miran y los que pasan por la calle, se paran; la bendicen.\"},{\"heading\":false,\"text\":\"Y las mugeres miran con envidia al novio, y á María y á sus alhajas.\"},{\"heading\":false,\"text\":\"Y los hombres fijan una mirada de deseo en la novia y otra de envidia en el novio que vá tras de María, con los ojos fijos en ella, al lado de su padre, rodeado de sus hermanos y seguido de sus amigos y parientes.\"},{\"heading\":false,\"text\":\"Ya llegan á la iglesia, atraviesan con trabajo por entre la gente, se acercan al presbiterio y se arrodillan en los almohadones.\"},{\"heading\":false,\"text\":\"Y empieza la misa.\"},{\"heading\":false,\"text\":\"Todos callan: todos están de rodillas.\"},{\"heading\":false,\"text\":\"Solo se oye lento y grave el canto del sacerdote y el órgano que le acompaña.\"},{\"heading\":false,\"text\":\"Pero de repente otro ruido horrible se sobrepone á la voz del beneficiado y á la del órgano.\"},{\"heading\":false,\"text\":\"Un trueno seco, poderoso, concentrado, que retumba en el espacio, y luego otro y otro.\"},{\"heading\":false,\"text\":\"Todos se levantan sobrecogidos, todos se revuelven, todos se confunden, todos quieren huir á un tiempo.\"},{\"heading\":false,\"text\":\"Porque aquel trueno, seco, rápido, poderoso, es la voz de las máquinas de esterminio[80].\"},{\"heading\":false,\"text\":\"Los hombres corren á las armas; las mugeres van estremecidas de espanto en busca de sus hijos para huir con ellos, y las jóvenes siguen á sus madres estremecidas como el cerbatillo que siente la trompa del cazador y el ladrido de los perros.\"},{\"heading\":false,\"text\":\"La fiesta se ha trocado en combate.\"},{\"heading\":false,\"text\":\"Los fronteros de Martos, á medio armar, sorprendidos, pelean en las calles, desde las casas, desde las torres, con los moros que avanzan, que van llegando hasta el corazon de la villa como un torrente que nada puede contener.\"},{\"heading\":false,\"text\":\"Zumba roncamente la jara y crujen secas y desapacibles las cuerdas de las ballestas.\"},{\"heading\":false,\"text\":\"Oyése el chasquido de la honda y la piedra lanzada por un brazo vigoroso, hiende los aires produciendo un ronco mugido, y va á abollar las jacarillas templadas con las aguas del Genil.\"},{\"heading\":false,\"text\":\"Algunos vecinos pretenden atajar el paso á los moros, pero Abul-Walid rompe por ellos y los arremolina y los holla, arrojándolos muertos á ambos lados de su paso; como el javalí se abre una senda por medio de la maleza que rompe con sus colmillos.\"},{\"heading\":false,\"text\":\"--¡Y pisa, pisa á esos perros! gritó Abul-Walid á su caballo: ¡avanza, Lucero mio, avanza; báñate en sangre hasta las cinchas, que yo te regalaré un pretal de oro, y coronaré tu cabeza con garzotas de diamantes! ¡Avanza, Lucero mio, avanza! ¡holla á esos perros! ¡la vírgen de mis sueños dirige mi lanza, que por sus negros ojos, esparce entre los cristianos las sombras de la muerte!\"},{\"heading\":false,\"text\":\"Y el valiente Lucero embravecido por el combate, avanza gallardo y feroz, y salta sobre los cadáveres y lleva á su real ginete allí donde los fronteros están mas apiñados.\"},{\"heading\":false,\"text\":\"Y los venablos, y las piedras, y las jaras rebotan sobre la armadura dorada del rey como sobre una roca, y Abul-Walid, con la lanza baja y la mirada sangrienta é impaciente avanza siempre, hiriendo cuanto encuentra y gritando sin cesar á su caballo:\"},{\"heading\":false,\"text\":\"--¡Písalos, Lucero mio, písalos: y yo te honraré poniendo sobre tu espalda la hermosa vírgen de las crenchas de oro!\"},{\"heading\":false,\"text\":\"Y como ha sido el delantero en el camino el rey, es el delantero en el combate.\"},{\"heading\":false,\"text\":\"Y como por el camino le han seguido sus moros, le siguen por las calles de la villa.\"},{\"heading\":false,\"text\":\"Sus moros, los feroces africanos de su guardia que llevan los alquiceles rojos para que no los manche la sangre.\"},{\"heading\":false,\"text\":\"¿Pero quién es aquel otro ginete que por la otra parte de la villa avanza llevando tras sí una taifa de caballeros abencerrajes entre los cuales ondea un estandarte verde?\"},{\"heading\":false,\"text\":\"Monta en una yegua blanca como la aurora; ciñe lucientes armas, y sobre su casco ondean plumas azules y encarnadas.\"},{\"heading\":false,\"text\":\"Y hermoso, y jóven, y valiente, y fiero.\"},{\"heading\":false,\"text\":\"Brilla en sus ojos algo de régio que impone respeto, y algo de sombrío que espanta.\"},{\"heading\":false,\"text\":\"Su semblante es dorado como el sol, y su rizada y negra barba, remeda sortijas de ébano.\"},{\"heading\":false,\"text\":\"Es Mohammet-ebn-Ismail, infante de Granada, primo del rey, hijo del walí de Algeciras.\"},{\"heading\":false,\"text\":\"Bien se conoce en su semblante y en sus proezas la autoridad de su persona, y en la bravura con que hiende por los cristianos lo guerrero de su raza.\"},{\"heading\":false,\"text\":\"Es muy jóven, y sin embargo ya ha ceñido muchas veces la sangrienta corona de la victoria, y acompaña en esta ocasion al rey de Granada, porque un caballero que tanto vale no puede quedarse en la ciudad adormido al son regalado de las zambras, mientras su rey oye el alarido de la pelea.\"},{\"heading\":false,\"text\":\"Pero Mohammet solo busca nuevos triunfos, mientras el rey amores: Mohammet grita mientras el rey invoca á la vírgen de sus sueños.--¡Solo Dios es vencedor!\"},{\"heading\":false,\"text\":\"Y Dios fortalece su brazo, y le convierte en un rayo que destruye cuanto toca.\"},{\"heading\":false,\"text\":\"¡Ay de los fronteros de Martos!\"},{\"heading\":false,\"text\":\"Sus hombres y sus mancebos han caido bajo los pies de los caballos de los moros vencedores.\"},{\"heading\":false,\"text\":\"Los viejos huyen y se esconden, y en la fuga los encuentra la implacable espada, y en el lugar donde se han escondido es el fuego no menos implacable.\"},{\"heading\":false,\"text\":\"Solo quedan en Martos niños y mugeres.\"},{\"heading\":false,\"text\":\"Mugeres y niños que los moros sacan cautivos á vuelta de la presa.\"},{\"heading\":false,\"text\":\"Las telas, las ropas, el oro, la plata, los ornamentos y los vasos sagrados, van á amontonarse revueltos sobre charcos de sangre.\"},{\"heading\":false,\"text\":\"Y los esclavos van cargando en las bestias que encuentran en la villa el botin que de la villa arrebatan los moros y lo llevan al campo para hacer el reparto.\"},{\"heading\":false,\"text\":\"Nadie hay que resista ya.\"},{\"heading\":false,\"text\":\"Y sin embargo, una gran casa, se defiende aun del infante Mohamet-ebn-Ismail y de sus gentes que la cercan.\"},{\"heading\":false,\"text\":\"Cada ventana, cada tronera, cada rendija de aquella casa dá salida á la muerte.\"},{\"heading\":false,\"text\":\"Los abencerrajes la embisten una y otra vez y son rechazados.\"},{\"heading\":false,\"text\":\"El infante Ebn-Ismail ruge como un tigre irritado, y avanza hacha en mano hácia la puerta.\"},{\"heading\":false,\"text\":\"Otro jóven, de la familia mas esclarecida de los abencerrajes, Aben-Osmin, se adelanta armado de otra hacha junto á él.\"},{\"heading\":false,\"text\":\"Gime, cruge la puerta; resiste algunos instantes y al fin cede.\"},{\"heading\":false,\"text\":\"Una nube de venablos sale del zaguan, y el infante Ebn-Ismail, oye á su derecha un grito de muerte.\"},{\"heading\":false,\"text\":\"El bravo Aben-Osmin ha caido á su lado atravesado el pecho por una vira.\"},{\"heading\":false,\"text\":\"Y al verle caer, el infante gritó á los suyos:\"},{\"heading\":false,\"text\":\"--Pensaba hacerles gracia de la vida por valientes, pero mi caudillo Osmin ha muerto; que no quede uno, ni hombre, ni muger, ni niño.\"},{\"heading\":false,\"text\":\"Y se lanza hambriento de venganza en la casa.\"},{\"heading\":false,\"text\":\"¿Pero qué le detiene de repente?\"},{\"heading\":false,\"text\":\"Ha entrado en una gran sala.\"},{\"heading\":false,\"text\":\"Aquella sala está colgada de negro.\"},{\"heading\":false,\"text\":\"En medio de ocho blandones hay un cadáver.\"},{\"heading\":false,\"text\":\"El cadáver de un cristiano armado, cubierto por una bandera mora, y á cuya noble y cana cabeza sirve de pabellon otra bandera.\"},{\"heading\":false,\"text\":\"Pero no es esto lo que detiene al infante; sus esclavos que han entrado á la par con él, que han escuchado su grito de esterminio, se apoderan de una hermosísima doncella, cubierta de galas y de joyas, cuya hermosura aumenta el terror que lucha débilmente con los esclavos, y sobre la cual se levantan los corvos alfanges.\"},{\"heading\":false,\"text\":\"Y un grito de horror del infante detiene á los esclavos y el infante llega y mira á la doncella.\"},{\"heading\":false,\"text\":\"Y apenas ha tenido tiempo de mirarla, cuando salvo de las armas de los fronteros, se siente herido en el corazon por los ojos de aquella niña.\"},{\"heading\":false,\"text\":\"Y tiembla, y palidece, y tartamudea, y dice al fin á la hermosa asiéndola dulcemente una mano.\"},{\"heading\":false,\"text\":\"--No tiembles gacela de oro, flor de la humbría, lucero de la tarde, sol de la hermosura.\"},{\"heading\":false,\"text\":\"No tiembles porque no has nacido para morir sino para matar.\"},{\"heading\":false,\"text\":\"No para ser cautiva sino señora.\"},{\"heading\":false,\"text\":\"Yo entré aquí libre y bravo, y héme cobarde y cautivo.\"},{\"heading\":false,\"text\":\"Yo vivia y muero.\"},{\"heading\":false,\"text\":\"Yo veía y he cegado.\"},{\"heading\":false,\"text\":\"No tiembles gacela de oro, rocío del alba, luz de los cielos.\"},{\"heading\":false,\"text\":\"Quien tú has muerto te dá vida.\"},{\"heading\":false,\"text\":\"Quien te ha cautivado te hace señora.\"},{\"heading\":false,\"text\":\"Aunque el moro sabe el habla castellana, trasportado por su amor la habla en árabe.\"},{\"heading\":false,\"text\":\"Que cuando amamos, cuando queremos comunicar todo nuestro amor al alma que nos lo inspira, no encontramos otro lenguaje mas elocuente que el dulce lenguaje de la patria.\"},{\"heading\":false,\"text\":\"La doncella solo comprende que el jóven príncipe la enamora, porque el acento del amor se hace entender á todas las gentes, se ruboriza, palidece, baja los ojos y prorrumpe en llanto.\"},{\"heading\":false,\"text\":\"Entonces el infante mas repuesto habla en castellano.\"},{\"heading\":false,\"text\":\"--¿Por qué lloras? la dice, ¿acaso has perdido á tu madre?\"},{\"heading\":false,\"text\":\"--¡Mi padre ha muerto! dice María, señalando el cadáver de Sancho de Arias, ¡mi padre ha muerto!\"},{\"heading\":false,\"text\":\"--Yo honraré su cadáver, y le seguirán arrastrando los pendoncillos de sus lanzas por el polvo en señal de luto mis caballeros abencerrajes.\"},{\"heading\":false,\"text\":\"--¡Mi esposo ha debido morir tambien! El uno ayer, el otro hoy ¡oh! ¡que os maldiga Dios!\"},{\"heading\":false,\"text\":\"--¡Tu esposo! ¡amabas á un hombre!\"},{\"heading\":false,\"text\":\"--Y le amo, esclamó llorando María.\"},{\"heading\":false,\"text\":\"El infante se pone pálido y luego dominándose dice apartando á un lado á María.\"},{\"heading\":false,\"text\":\"--¿Estás segura que tu esposo ha muerto?\"},{\"heading\":false,\"text\":\"--Sí, porque me tienes en tu poder y no le veo, contesta María.\"},{\"heading\":false,\"text\":\"--¿Estaba contigo aquí en esta casa?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--Escucha, amor de los cielos; oyéme y no me mires como á un enemigo. No sé por qué te amo, te amo como si fueras alma de mi alma, y no tengo celos de ese hombre á quien amas. Escúchame, sultana de las huríes; por enjugar tu llanto, daria yo mi nombre y mis riquezas, y mis victorias y mis frondosos cármenes del Darro, y mi castillo de Al-Padul; y mi libertad y mi vida. Escúchame: buscaremos á tu esposo, le buscaremos, y si vive yo le protegeré á todo mi poder, y si está herido yo haré que mi sábio médico le cure, y si ha muerto... ¡oh! ¡que haré yo para secar tu llanto, luz de mis ojos, hermana mia!\"},{\"heading\":false,\"text\":\"--¡Oh! ¿es verdad lo que decís, señor? esclama María no acertando á comprender en un moro á quien mira con ódio tanta generosidad.\"},{\"heading\":false,\"text\":\"--¡Que si es verdad! mentira sea la luz del sol y el azul de los cielos y quede mi alma en tinieblas si te engaño. ¿Y á qué habia yo de engañarte, lucero de mi vida? ¿No te tengo en mi poder? ¿quién podria defenderte de mí, si yo mismo no te defendiese?\"},{\"heading\":false,\"text\":\"--¡Oh! ¡señor! ¡Dios os bendiga! dice María arrojándose á sus pies.\"},{\"heading\":false,\"text\":\"--Escucha: la contesta alzándola el infante; eres muy hermosa, y si el rey te vé podrá codiciarte. ¡Ay entonces del rey! ¡ay entonces de mí! las joyas que te engalanan traerian sobre tí todas las miradas, dame esas joyas sultana; yo te las guardaré, y te las daré dobladas; si son de tu madre yo te daré la mitad de las joyas de la mia. Pero pronto, que se oyen los atabales; dame esas joyas, envuélvete en tu velo y sígueme.\"},{\"heading\":false,\"text\":\"María se quita una tras otra las joyas y las entrega al infante Mohammet que las guarda en su escarcela, luego se cubre con su velo y el infante la ase de la mano y dice á sus esclavos:\"},{\"heading\":false,\"text\":\"--Quedaos aquí y guardad ese honrado cadáver que duerme el sueño de los valientes bajo los trofeos de la victoria. Que nadie se atreva á insultarle. Sígueme sultana, es necesario ponerte cuanto antes en salvo, entre mis ginetes. Yo te rodearé de lanzas como de un muro, y mi caballo de batalla se convertirá en cordero del amor.\"},{\"heading\":false,\"text\":\"--¡Y mi esposo! dice acreciendo en llanto María.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡es verdad! ¿decias que estaba en esta casa?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Que la defendia?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡quiera Dios!.. y el infante se detiene temeroso de que las palabras lastimen el corazon de María.\"},{\"heading\":false,\"text\":\"Y la lleva consigo, y recorren todos los aposentos mirando los cadáveres que vuelven los esclavos.\"},{\"heading\":false,\"text\":\"Y--¡Ese era su padre! ¡ese era su hermano! ¡ese era su amigo! esclama á cada uno que vé, anegada en lágrimas María.\"},{\"heading\":false,\"text\":\"Pero de repente, en el zaguan la infeliz á la vista de un caballero ensangrentado é inerte, dá un grito horrible.\"},{\"heading\":false,\"text\":\"--¡El es! esclama.\"},{\"heading\":false,\"text\":\"Y cae desvanecida entre los brazos del infante.\"},{\"heading\":false,\"text\":\"--¡Ese! ¡ese mancebo era su esposo! esclama con compasion y con ira al mismo tiempo Ebn-Ismail. ¡El! ¡el matador de mi amigo, de mi hermano Aben-Osmin! ¡El! ¡á quien en venganza de la sangre de mi hermano de guerra, abrí yo las puertas de la muerte con mi hacha!\"},{\"heading\":false,\"text\":\"Y es verdad: Gonzalo Nuñez tiene la cabeza herida de un hachazo.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡el matador de Aben-Osmin! esclama el infante. Sí, le conozco bien á pesar de la sangre que le cubre el rostro. El fué el primero á quien encontramos cuando se abrió la puerta. Y si no ha muerto, ¿he de salvar yo á este hombre? Y bien: esta infeliz le ama: seamos generosos y caritativos en nombre de Dios Altísimo y misericordioso, y que él tenga compasion de nuestra alma, añade arrojando una mirada de amor desesperado á María.\"},{\"heading\":false,\"text\":\"--Que venga al punto mi sabio médico Ayub, añade: buscadle: él me sigue siempre en el combate.\"},{\"heading\":false,\"text\":\"Y--Aquí estoy, noble señor, responde un anciano de luenga barba blanca, vestido sencillamente con una túnica parda, y ceñida la cabeza con una toca blanca.\"},{\"heading\":false,\"text\":\"--¿Hay un soplo siquiera de vida en ese caballero? le dice el infante.\"},{\"heading\":false,\"text\":\"--Sí, si señor; dice el sabio despues de haber observado profundamente a Gonzalo. Vive; pero solo Dios que sabe lo oculto, sabe si sobrevivirá á la herida.\"},{\"heading\":false,\"text\":\"--¡La ciencia es hija de Dios! ¡Ayub: alienta esa vida! ¡aliéntala como si fuera la de mi hermano, y si le salvas te llamaré mi padre! Partamos de aquí antes que el tumulto crezca: partamos á mi castillo de Al-Padul antes que sobrevenga el rey. Ocultémosla á sus ojos. Salvémosla para su amor.\"},{\"heading\":false,\"text\":\"Y dejando momentáneamente á María en brazos de un wazir de sus abencerrages, cabalga sobre su caballo, que le tienen de la rienda dos esclavos, y luego toma sobre el arzon á María, y parte rodeado de sus caballeros.\"},{\"heading\":false,\"text\":\"Pero al salir de la villa los esclavos de la guardia del rey le detienen.\"},{\"heading\":false,\"text\":\"--Soy el infante de Granada Sidy-ebn-Ismail, esclamó con altivez. Paso esclavos.\"},{\"heading\":false,\"text\":\"Y los esclavos, inclinados y respetuosos, pero con firmeza, le contestan:\"},{\"heading\":false,\"text\":\"--El rey manda que ninguna muger salga de los reales.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Y Abal-Walid, ébrio de amor y de desesperacion, porque no la encuentra, busca entre tanto por todas partes de la villa á María; levanta los velos de todas las mugeres, y las entrega irritado á su soldadesca: entra y sale en las casas hasta en las que están arruinadas; hace revolver las ruínas y nada halla; pasan las horas y crece la desesperacion y la cólera del rey, y al fin llega la tarde sin haber encontrado á María.\"},{\"heading\":false,\"text\":\"Y cuando el sol estaba próximo á ponerse, cuando ya desesperado iba levantar el campo, un esclavo le dice:\"},{\"heading\":false,\"text\":\"--Tú buscas, señor, á una hermosa cautiva.\"},{\"heading\":false,\"text\":\"Y el rey le responde:\"},{\"heading\":false,\"text\":\"--Sí: ¿la conoces tú?\"},{\"heading\":false,\"text\":\"--Hé visto una hermosísima cristiana, entre las gentes del infante Ebn-Ismail.\"},{\"heading\":false,\"text\":\"--¿Tiene los cabellos rubios?\"},{\"heading\":false,\"text\":\"--Como el oro.\"},{\"heading\":false,\"text\":\"--¿Y la frente blanca?\"},{\"heading\":false,\"text\":\"--Como el alba.\"},{\"heading\":false,\"text\":\"--¿Y los ojos negros?\"},{\"heading\":false,\"text\":\"--Como la noche.\"},{\"heading\":false,\"text\":\"--¿Y dices que esa doncella está en poder del infante Ebn-Ismail?\"},{\"heading\":false,\"text\":\"--Entre sus taifas de abencerrages la he visto, magnífico sultan.\"},{\"heading\":false,\"text\":\"El rey arroja su garzota de diamantes al esclavo, y mira ansioso al lugar del campo donde ondea el estandarte rojo de los Beni-Serag[81].\"},{\"heading\":false,\"text\":\"Y entonces vé, que saliendo de las enfiladas tiendas, un caballero ismaelita adelanta llevando de la mano á una cristiana á un cercano bosque, y el rey, apartándose bruscamente de los suyos, aprieta los acicates á su valiente Lucero, se dirige por otro lado al bosque, descabalga, y sin cuidarse de atar su caballo, que le sigue como un perro, se pierde solo en la espesura.\"}]},{\"title\":\"La puerta del juicio. — capítulo IX\",\"blocks\":[{\"heading\":false,\"text\":\"Y entre tanto el infante Ebn-Ismail y María se dirigen al bosque.\"},{\"heading\":false,\"text\":\"Ella vá enteramente cubierta con el velo, y bajo él corren las lágrimas y se oyen sollozos ahogados.\"},{\"heading\":false,\"text\":\"--No llores, hermana mia, dice Ebn-Ismail: tu llanto me despedaza el corazon: no sé por qué te amo como amaba á mi madre: no llores, el hombre á quien amas acaso no ha muerto, acaso yo pueda volvértele; y tu padre, sus nobles restos, serán respetados y honrados.\"},{\"heading\":false,\"text\":\"María continúa sollozando.\"},{\"heading\":false,\"text\":\"--Escucha, la dice el infante: muy pronto ese bosque nos habrá ocultado del rey que podria cegar ante tu hermosura: ¡ay del rey si pretendiera hacerte su esclava! pero no temas; tú y yo y algunos de los mios esperaremos aquí ocultos, y cuando el rey haya partido yo te pondré en salvo.\"},{\"heading\":false,\"text\":\"Y María continúa callando.\"},{\"heading\":false,\"text\":\"--Mira, repite el infante; yo tengo en una aldea cerca de Granada, en la Azubia, un hermoso y retirado palacio: allí hay hermosos jardines, frescas fuentes, apartamentos misteriosos que te ocultarán á las miradas de todos, y ni el sol te verá, si no quieres que el sol te vea. ¿Por qué lloras, pues, hermana mia? ¿pretendo yo ser tu tirano?\"},{\"heading\":false,\"text\":\"--¡Mi padre! ¡mi esposo! esclama la infeliz María, acreciendo en sus lágrimas.\"},{\"heading\":false,\"text\":\"--Tu padre está en el lugar que el Altísimo concede á los honrados y á los valientes: tu esposo... ¿sabes tú si algun dia le encontrarás?\"},{\"heading\":false,\"text\":\"--¡Oh! ¡pluguiera á Dios, para que se secáran mis lágrimas! dice María.\"},{\"heading\":false,\"text\":\"De repente el infante se detiene y pone mano á su espada.\"},{\"heading\":false,\"text\":\"Un hombre ha aparecido de improviso en una revuelta de la espesura, y adelanta como un tigre hambriento hácia el infante y hácia María.\"},{\"heading\":false,\"text\":\"--¿Por qué te detienes? dice esta al infante.\"},{\"heading\":false,\"text\":\"--¡El rey! murmura el infante con voz estremecida por la cólera.\"},{\"heading\":false,\"text\":\"--¡El rey! repite María, y sin saber por qué se estremece y tiembla.\"}]},{\"title\":\"La puerta del juicio. — capítulo X\",\"blocks\":[{\"heading\":false,\"text\":\"--¡Guárdete Allah, mi valiente primo! dice el rey acercándose. ¿A dónde llevas á esa cristiana?\"},{\"heading\":false,\"text\":\"--Es mi esclava, dice Ebn-Ismail: el apoderarme de ella me ha costado mucha sangre de mis escuadrones, y la pérdida de mi amigo Aben-Osmin, que se cuenta entre los mártires de la victoria. ¿Acaso pretendes, señor, que yo no tenga potestad sobre esta esclava?\"},{\"heading\":false,\"text\":\"María calla y tiembla.\"},{\"heading\":false,\"text\":\"--¡Mio es el quinto de las presas! esclamó con voz temblorosa el rey: ¡mia la potestad de elegir entre la presa lo que mejor quiera! ¡Yo soy el señor y tú eres el esclavo! ¿Te atreverás á oponerte á mi voluntad?\"},{\"heading\":false,\"text\":\"--Tu siervo soy y lo confieso, dice Ebn-Ismail conteniéndose á duras penas, porque por el lado por donde habia venido el rey empezaban á asomar esclavos de su guardia africana: tu siervo soy; ¿pero no merecen mí valor y la sangre que por Dios y por tí he vertido en una y otra batalla, que me concedas esta esclava?\"},{\"heading\":false,\"text\":\"El rey entonces adelanta hácia María y la levanta de sobre el rostro el velo; y al verla tan hermosa, con el semblante cubierto de rubor, inclinado á la tierra, y temblando de espanto, la reconoce; su corazon se abrasa en un fuego impuro, y grita fuera de sí:\"},{\"heading\":false,\"text\":\"--¡Esta es mia!\"},{\"heading\":false,\"text\":\"--¡Tuya! esclama el infante en el colmo de su furor.\"},{\"heading\":false,\"text\":\"Pero los esclavos africanos llegan; el infante está solo; medita que una resistencia inútil solo servirá para privar á María de un defensor generoso, y contesta:\"},{\"heading\":false,\"text\":\"--Tuyo es, señor, cuanto es de tu siervo: llévate á la cristiana, y si en ello crees que hay un sacrificio por mi parte, sirva para aumentar en uno los sacrificios que por tí he hecho.\"},{\"heading\":false,\"text\":\"Y sin decir mas palabra se vuelve desesperado, se aleja dejando en poder del rey á María, llega á sus abencerrages, y,\"},{\"heading\":false,\"text\":\"--¡A caballo! les grita; ¡á caballo y á Granada!\"},{\"heading\":false,\"text\":\"Y el valiente escuadron de los abencerrages, plega las tiendas, cabalga y parte en silencio y á la carrera tras de su caudillo, que lleva un infierno en el alma.\"}]},{\"title\":\"La puerta del juicio. — capítulo XI\",\"blocks\":[{\"heading\":false,\"text\":\"Han pasado tres dias.\"},{\"heading\":false,\"text\":\"Es la noche del tercero.\"},{\"heading\":false,\"text\":\"En el real Generalife hay una alegre zambra.\"},{\"heading\":false,\"text\":\"Las damas cubiertas de pedrería, y de galas y de brocados, mas hermosa la mas fea que el rubí mas precioso, bailan con gentiles mancebos, que tres dias antes estaban cubiertos de sangre desde el acicate hasta el creston del capacete.\"},{\"heading\":false,\"text\":\"Las dulzainas, y las leilas, y las bandolinas, y las guzlas llenan la noche de armonías.\"},{\"heading\":false,\"text\":\"Dentro de las cámaras se estiende el blanco y aromático humo de los pebeteros que agitan las brisas nocturnas, que penetran por los ajimeces y por las galerías, y llevan consigo la fragancia que han robado á las flores de los jardines.\"},{\"heading\":false,\"text\":\"Algunos enamorados discurren fuera de las cámaras, entre las sombrosas enramadas, diciendo su amor á la hermosa de su alma, entre el misterio del silencio y de la noche.\"},{\"heading\":false,\"text\":\"La luna brilla tranquila en los estanques, y todo es paz, todo es melancolía, todo es amor.\"},{\"heading\":false,\"text\":\"Solo hay dos caballeros en el Generalife que no participan de la alegría de los otros; que vagan tristes, y solos, y silenciosos.\"},{\"heading\":false,\"text\":\"Son el rey Abul-Walid, y el infante Ebn-Ismail.\"},{\"heading\":false,\"text\":\"El infante sigue al rey como una sombra, y el rey está tan abismado en sus pensamientos, que no vé al infante que le sigue.\"},{\"heading\":false,\"text\":\"El rey piensa en María, y el infante siguiéndole, piensa tambien en ella.\"},{\"heading\":false,\"text\":\"María es para el rey un arcángel de fuego.\"},{\"heading\":false,\"text\":\"Su recuerdo le quema el alma.\"},{\"heading\":false,\"text\":\"La memoria de su desden le desespera.\"},{\"heading\":false,\"text\":\"La Alhambra, tan hermosa, tan alegre, tan resplandeciente, se ha tornado en una tumba para el rey.\"},{\"heading\":false,\"text\":\"Porque María es su vida, y María le desprecia.\"},{\"heading\":false,\"text\":\"Porque el rey la adora, y María cuando le dice su amor calla, fria y muda como una estátua.\"},{\"heading\":false,\"text\":\"Y el rey ha puesto á sus pies su corona, y la ha ofrecido la mitad de su tálamo y el nombre de sultana.\"},{\"heading\":false,\"text\":\"Pero María tiene allá su corazon en el humeante Martos: y entre sus ruinas ensangrentadas, vé contínuamente el cadáver de su padre, y el de su amado Gonzalo.\"},{\"heading\":false,\"text\":\"Y María llora inconsolable, y cuando el rey la habla de amores le vuelve la espalda.\"},{\"heading\":false,\"text\":\"Por eso el rey está triste.\"},{\"heading\":false,\"text\":\"Por eso cuando piensa en María, (y está siempre pensando en ella) su corazon se abrasa en un fuego volcánico, y se revuelven en su cabeza sombríos pensamientos.\"},{\"heading\":false,\"text\":\"Por eso el rey no danza, ni sonrie á las damas, ni se acompaña de nadie.\"},{\"heading\":false,\"text\":\"Por eso el fresco, riente y perfumado Generalife, no tiene para él ni mugeres hermosas, ni armonías, ni sombrosos jardines, ni los tersos espejos de sus estanques, ni la luz de la luna, ni el cielo azul, ni los trémulos luceros que en los estanques reflejan.\"},{\"heading\":false,\"text\":\"Por eso, Generalife el hermoso, Generalife el engalanado, Generalife el de las zambras, es para el rey una tumba, como lo es tambien su magnífico y resplandeciente alcázar.\"},{\"heading\":false,\"text\":\"Porque María es para el rey un terrible arcángel de fuego.\"},{\"heading\":false,\"text\":\"Y el infante Ebn-Ismail, piensa de otro modo en María.\"},{\"heading\":false,\"text\":\"María es para él la fresca fuentecilla, que brota á la sombra de las palmeras del desierto, con su raudal trasparente y puro, á cuyo lado, sobre la verde yerba, se reclina el viagero cansado, y se aduerme el fuerte camello.\"},{\"heading\":false,\"text\":\"Ebn-Ismail, vé á través de la pura y candorosa mirada de María su alma, como pudiera ver el fondo tranquilo de la fuentecilla del desierto, á través de su límpida superficie.\"},{\"heading\":false,\"text\":\"Y Ebn-Ismail no ha pensado siquiera en enturbiar ni aun con su hálito aquella pura fuente, pero vé al leon sediento que vaga en torno de ella y ruge, y centellea miradas de fuego, y á quien solo la voluntad de Dios contiene para que no enturbie la fuente purísima, con su espumosa y ardiente boca.\"},{\"heading\":false,\"text\":\"Por eso, silencioso, sombrío, escondida la mano bajo su jaqueta, y manoseando impaciente el pomo de su puñal, sigue al rey.\"},{\"heading\":false,\"text\":\"Al rey que abandona triste, solo y mudo el sarao, y se pierde en los jardines.\"},{\"heading\":false,\"text\":\"El infante se pierde tambien bajo su sombra tras el rey.\"},{\"heading\":false,\"text\":\"Y el rey vá tan absorto pensando en María, que no siente que el infante le sigue.\"},{\"heading\":false,\"text\":\"Y avanza.\"},{\"heading\":false,\"text\":\"Avanza su paso precipitado como el que se impacienta por la distancia que le separa del objeto de su deseo.\"},{\"heading\":false,\"text\":\"El rey baja por una escalinata oscura, al estremo de uno de los jardines, y entra en una ancha arcada oscurísima[82].\"},{\"heading\":false,\"text\":\"Pero sigue por ella su paso seguro y rápido á pesar de la oscuridad, como quien conoce bien el lugar por donde camina.\"},{\"heading\":false,\"text\":\"Sirven de guia al infante los pasos del rey, y la oscuridad le inspira proyectos horribles.\"},{\"heading\":false,\"text\":\"Pero el rey adelanta con tal rapidez, que el infante, cuyo paso es inseguro, no logra alcanzarle.\"},{\"heading\":false,\"text\":\"Dios no quiere que se cometa un regicidio entre las tinieblas.\"},{\"heading\":false,\"text\":\"Quiere que todos vean el rostro del asesino.\"},{\"heading\":false,\"text\":\"Y el rey, protegido por Dios, se salva aquella noche.\"},{\"heading\":false,\"text\":\"El infante sigue aun sirviéndole de guia los pasos del rey; se le acerca: ya es pequeña la distancia, y el infante desnuda su puñal.\"},{\"heading\":false,\"text\":\"Pero de improviso suena una llave en una cerradura, se abre y se cierra instantáneamente una puerta, resuena otra vez la llave cerrando por dentro, y el infante queda perdido en la oscuridad.\"},{\"heading\":false,\"text\":\"Piensa volverse, y adelanta palpando con las manos estendidas.\"},{\"heading\":false,\"text\":\"Al fin una dulce claridad brilla á un estremo de la mina, apresura su paso el infante, llega á una escalinata, la sube y se encuentra á la luz de la luna en un pequeño espacio, al lado de un foso, entre altos muros, y al pie de una torre orlada de puntiagudas almenas.\"},{\"heading\":false,\"text\":\"El infante quiere en vano reconocer aquella torre: se parece á otras muchas de la Alhambra, y nunca ha estado en aquellos sitios.\"},{\"heading\":false,\"text\":\"En la parte media de la torre hay un mirador, al que dá paso un ajimez calado, por entre cuyo doble arco se vé el interior de una magnífica cámara iluminada por una lámpara que luce colgada en el centro de ella como una luna opaca.\"},{\"heading\":false,\"text\":\"El infante, sin saber por qué, fija los ojos en el mirador, y escucha con toda su alma.\"},{\"heading\":false,\"text\":\"Pero nada turba el silencio mas que á lo lejos los sonidos de la zambra de Generalife, repetidos débilmente por los ecos, y cerca la voz de los guardas de los muros que de tiempo en tiempo lanzan un grito de vigilancia.\"},{\"heading\":false,\"text\":\"Pero de repente se oyen fuertes pasos, pasos de muger en la cámara á que corresponde el mirador, y aparece en este una forma blanca, que se ase á la balaustrada y vuelve con fiereza su rostro al interior.\"},{\"heading\":false,\"text\":\"Tras aquella forma blanca, gentil, hechicera, que inundan los rayos de la luna, aparece una sombra oscura, en la que el infante cree reconocer al rey.\"},{\"heading\":false,\"text\":\"Al acercarse aquella forma sombría á la forma blanca, esta se avanza á la balaustrada y esclama con un acento desesperado, que llega entero á los oidos del infante.\"},{\"heading\":false,\"text\":\"--Si dás un solo paso mas hácia á mí, me arrojo al pie del muro.\"},{\"heading\":false,\"text\":\"Y el infante oye una horrible maldicion que parece salir de la boca del rey, y luego vé que la sombra oscura se retira.\"},{\"heading\":false,\"text\":\"La sombra blanca permanece en el mirador asida á la balaustrada.\"},{\"heading\":false,\"text\":\"Pasa algun tiempo y el infante avanza, llega al pie del muro y permanece por un breve espacio silencioso, oculto en la penumbra.\"},{\"heading\":false,\"text\":\"--¡María! dice al fin: ¡María!\"},{\"heading\":false,\"text\":\"Y la blanca sombra al escuchar aquel nombre dos veces repetido, se inclina sobre la balaustrada y busca con la vista en el lugar de donde ha salido la voz á la persona que ha pronunciado aquel nombre.\"},{\"heading\":false,\"text\":\"--¿Quién eres? dice con la voz alterada aun por el terror la muger.\"},{\"heading\":false,\"text\":\"--Soy... tu hermano el infante Ismail.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡pues si verdaderamente eres mi hermano, sálvame, sálvame de este hombre! ¡lo temo todo!... ¡esta noche ha podido defenderme la muerte!... ¡pero mañana!... ¿quién sabe?\"},{\"heading\":false,\"text\":\"--¡Mañana! ¡mañana la muerte te habrá defendido! dice con voz ronca el infante.\"},{\"heading\":false,\"text\":\"--¡La muerte! ¡no te comprendo!\"},{\"heading\":false,\"text\":\"--¡Mañana el rey no te amará!\"},{\"heading\":false,\"text\":\"--¡Ah! esclama María comprendiendo al infante: ¡siempre la muerte en torno mio!\"},{\"heading\":false,\"text\":\"--Pero Gonzalo vive.\"},{\"heading\":false,\"text\":\"--¡Que vive Gonzalo! esclama con un acento de inmensa alegría la jóven.\"},{\"heading\":false,\"text\":\"--Sí; y cuida de él mi sabio médico allá en mi castillo de Hins-haleux, en la frontera.\"},{\"heading\":false,\"text\":\"--¡Que Dios te bendiga! esclama llorando de gozo María.\"},{\"heading\":false,\"text\":\"--Y á Dios, dice el infante: nada temas; mañana el rey no te amará.\"},{\"heading\":false,\"text\":\"--¡Dios te bendiga! repite María y desaparece.\"},{\"heading\":false,\"text\":\"--¿Y cómo piensas valerte para que mañana el rey no ame á esa doncella? dice una voz áspera, bronca, cavernosa, al mismo tiempo que una mano descansa en su hombro.\"},{\"heading\":false,\"text\":\"El infante Ebn-Ismail se vuelve y vé delante de sí un viejo horrible, envuelto en una túnica estraña, alto, seco, espantoso.\"},{\"heading\":false,\"text\":\"Aquel viejo es Abu-Jacub-al-Hakem-Billah.\"},{\"heading\":false,\"text\":\"--¿Quién eres tú? dice el infante que no le conoce.\"},{\"heading\":false,\"text\":\"--Yo soy quien puedo ayudarte, contesta el mago.\"},{\"heading\":false,\"text\":\"--¡Ayudarme! ¿y para qué necesito yo tu ayuda?\"},{\"heading\":false,\"text\":\"--Pretendes matar al rey.\"},{\"heading\":false,\"text\":\"--Y le mataré mañana mismo.\"},{\"heading\":false,\"text\":\"--Ciertamente; para matar á un hombre basta otro hombre: pero cuando se trata de matar á un rey, si el hombre que le mate no quiere morir, necesita parciales que le ayuden.\"},{\"heading\":false,\"text\":\"--¿Y qué se me dá de morir ó no despues de vengarme?\"},{\"heading\":false,\"text\":\"--Recuerda que en tu castillo de Hins-haleux, hay un pobre herido que necesita de tu proteccion.\"},{\"heading\":false,\"text\":\"--¡Es verdad! dice el infante.\"},{\"heading\":false,\"text\":\"--Recuerda aun que en esa torre está tu hermana.\"},{\"heading\":false,\"text\":\"Y el mago pronuncia esta última palabra de una manera singular, hasta el punto de que repara en ello el infante.\"},{\"heading\":false,\"text\":\"Y como si el mago adivinara su pensamiento, añade:\"},{\"heading\":false,\"text\":\"--Muestra las joyas que tu hermana llevaba el dia en que la encontraste en Martos, y muéstralas á tu padre el walí de Algeciras.\"},{\"heading\":false,\"text\":\"--¿Esplícame?...\"},{\"heading\":false,\"text\":\"--Tu padre te lo esplicará. Por ahora lo que mas importa es proteger á María: si tú mueres por haber matado al rey, María quedará sola y abandonada, y no habrá dejado de ser cautiva de Abul-Walid, sino para serlo de su hijo. María es hermosa...\"},{\"heading\":false,\"text\":\"--¡Es verdad!\"},{\"heading\":false,\"text\":\"--Comprende, pues, por qué debes procurar que la muerte del rey no cause la tuya.\"},{\"heading\":false,\"text\":\"El infante inclina la cabeza y permanece pensativo.\"},{\"heading\":false,\"text\":\"--¿Y qué hacer? dice al fin.\"},{\"heading\":false,\"text\":\"--El wazir del rey Masud-Almoharaví tiene muchos enemigos.\"},{\"heading\":false,\"text\":\"--Es soberbio, iracundo y rapaz; ofende contínuamente á los mas poderosos, apartándolos del rey, y trata como á sus esclavos á los vasallos del rey.\"},{\"heading\":false,\"text\":\"--Por lo mismo esta noche están congregados algunos caballeros tratando de su muerte; pero no se atreven á ella, porque les falta una cabeza poderosa, un infante de Granada, como tú por ejemplo.\"},{\"heading\":false,\"text\":\"--¿Y dónde se reunen esos caballeros?\"},{\"heading\":false,\"text\":\"--En las cuevas de Dinadamar: si tú los buscas, ellos te acogerán con alegría; y ayudado por ellos podrás matar al rey impunemente.\"},{\"heading\":false,\"text\":\"--¿Será necesario sublevar á Granada contra el wazir?\"},{\"heading\":false,\"text\":\"--Busca el medio mas seguro: eso es de cuenta tuya. Ya te he dicho bastante. Quédate en paz.\"},{\"heading\":false,\"text\":\"Y el mago, sin que el infante pudiera esplicarse cómo, desaparece de sus ojos.\"},{\"heading\":false,\"text\":\"--Ebn-Ismail permanece algun tiempo inmóvil, despues levanta la cabeza, fija la vista en el mirador, y esclama:\"},{\"heading\":false,\"text\":\"--¡Mañana el rey no te amará, hermana mia! ¡A las cuevas de Dinadamar!\"}]},{\"title\":\"La puerta del juicio. — capítulo XII\",\"blocks\":[{\"heading\":false,\"text\":\"Fuera de sí el infante, busca de nuevo las escaleras y la mina; llega á Generalife, y para que no puedan sospechar de su ausencia anterior ni de la que deba seguirla, se deja ver en la zambra.\"},{\"heading\":false,\"text\":\"Y no solo se deja ver, sino que se dirige á la sultana Ketirah, y como infante de Granada la dice:\"},{\"heading\":false,\"text\":\"--¿Primavera de flores que no se marchitan, alegría del mundo, alma del alma del magnífico y vencedor sultan de Andalucía, querrás honrar á tu esclavo, con la honra mayor de la tierra, y hacerle dichoso con la felicidad mayor de la vida, bailando con él esta zambra?\"},{\"heading\":false,\"text\":\"La sultana le mira, y su semblante antes frio, severo, que parece empañado por una nube funesta, se dilata, sonrie y tiende su mano al infante.\"},{\"heading\":false,\"text\":\"--¿Y no palidecerá de celos, le dice de modo que nadie pueda oirlo, al verme danzar contigo la amada de tu alma?\"},{\"heading\":false,\"text\":\"--La amada de mi alma vive en mi corazon, responde el infante con voz insegura y temblorosa, y no puede tener celos de tí, sultana.\"},{\"heading\":false,\"text\":\"Y el infante al pronunciar estas palabras, recuerda dolorosamente á su perdida sultana Aleidah, envenenada por Masud-Almoharaví, para poner en el trono á Ketirah.\"},{\"heading\":false,\"text\":\"Aleidah, el arcángel de paz que amaba á Ebn-Ismail en el misterio de su alma, como Ebn-Ismail la amaba á ella, que jamás le confesó su amor ni con un relámpago de sus negros ojos, ni con un suspiro de su alto seno, ni con una sonrisa de su purpúrea boca.\"},{\"heading\":false,\"text\":\"Aleidah, la honesta, la cándida y la pura, que bajó á la tumba llevando con ella el secreto de su amor.\"},{\"heading\":false,\"text\":\"--¿Y sabe la amada de tu corazon que vive en él? dice Ketirah con voz desfallecida, abandonándose lánguidamente á la zambra entre los brazos del infante, que se sorprende á aquellas palabras porque no las espera.\"},{\"heading\":false,\"text\":\"Pero en aquel momento comprende que Ketirah le ama, que puede herir el alma de Abul-Walid en su honra antes que herir su cuerpo, y se propone engañar el amor de la sultana, que espera su respuesta, fijando en sus ojos la ardiente y lánguida mirada de sus ojos garzos.\"},{\"heading\":false,\"text\":\"El rey, que ha vuelto á la zambra, y que vaga sombrío y ceñudo por los salones, vé de improviso la mirada que se cruza entre la sultana y el infante; nota su conversacion en voz baja, cree adivinar sus palabras, y su honra ofendida, sino su amor; porque el que siente por María le impide amar á otra muger; rugen en violenta lucha en su corazon, y abarca en una mirada de ódio salvage á los dos imprudentes que osan mancillar su nombre.\"},{\"heading\":false,\"text\":\"Y Ketirah no nota aquella mirada, porque hace mucho tiempo que ama en secreto á Ebn-Ismail, desesperada, y la primera palabra de amor del infante la ha enloquecido.\"},{\"heading\":false,\"text\":\"Nada vé, nada oye, nada siente mas que la traidora mirada de Ebn-Ismail, y el brazo con que este estrecha fuertemente su cintura.\"},{\"heading\":false,\"text\":\"Ketirah lo ha olvidado todo, no vive mas que para el infante.\"},{\"heading\":false,\"text\":\"Pero el infante observa al rey, y le vé trémulo, terrible, dudando.\"},{\"heading\":false,\"text\":\"--No te atreverás á deshonrarte delante de tu córte, dice para sí el infante: procurarás vengarte, porque comprendes que porque me has robado á la cautiva cristiana, te robo yo tu esposa. Yo no sabia que tu esposa me amaba, pero ya que me ama, mi venganza será completa: primero tu honra, despues tu vida. Cuando quieras vengarte será tarde.\"},{\"heading\":false,\"text\":\"Y sigue danzando con la sultana, con la sultana que le sonríe amorosa, mostrándole por sus entreabiertos labios, que dan salida á ardientes suspiros, perlas mas blancas, mas puras, mas frescas que la del rico collar que al compás de la danza se agita en su cuello de nacar sobre su alto y palpitante seno.\"},{\"heading\":false,\"text\":\"Ketirah es muy hermosa.\"},{\"heading\":false,\"text\":\"Sus negros cabellos flotan perfumados como una nube negra y densa en medio de la cual, pálida de amores, brilla la luna llena en toda su hermosura; una luna en que hay dos soles que despiden rayos.\"},{\"heading\":false,\"text\":\"Su cintura es redonda y mórvida y cimbradora, y la falda de la túnica dejaba ver, al flotar, un pie por el que envidiarian ser pisadas las flores.\"},{\"heading\":false,\"text\":\"Y no se balancea con mas gracia una palmera al impulso de las auras que la gallarda sultana en la danza, entre los brazos de Ebn-Ismail.\"},{\"heading\":false,\"text\":\"Y hay un momento en que el infante á pesar de su eterno amor á su per dida Aleidah, se siente embriagado como el que ha bebido con esceso el nectar prohibido á los creyentes.\"},{\"heading\":false,\"text\":\"Todo lo que hay en torno suyo vaga, gira confuso, y no vé nada; nada mas que los ojos y la boca de Ketirah.\"},{\"heading\":false,\"text\":\"¡Ketirah! ¡el demonio tentador! ¡el tósigo libado en copa de oro! ¡la maga maldita de la tentacion!\"},{\"heading\":false,\"text\":\"¡Ketirah! ¡á quien para ser comparada á una hurí solo la faltan los ojos negros, y que hace suspirar al creyente, porque sabe que en el paraiso no encontrará una hurí que tenga los ojos garzos como Ketirah!\"},{\"heading\":false,\"text\":\"¡Ketirah! ¡que atrae á sí los corazones y los abrasa con un leve relámpago de sus ojos!\"},{\"heading\":false,\"text\":\"¡Ketirah la envenenadora! ¡Ketirah la adúltera!\"},{\"heading\":false,\"text\":\"¡La adúltera!\"},{\"heading\":false,\"text\":\"Vedlos: se pierden en los jardines.\"},{\"heading\":false,\"text\":\"Ved al rey que los sigue.\"},{\"heading\":false,\"text\":\"Ved despues que ellos tornan, y sus miradas son mas amantes y guardan un destello de felicidad.\"},{\"heading\":false,\"text\":\"--¿Y por qué no? dice el infante vacilando de su virtud: muger mas hermosa no he conocido, y me ama como las flores al sol. ¿Por qué no amarla? ¿No he sido bastante tiempo fiel, á mi malogrado, á mi ignorado amor por Aleidah? ¿me amaba ella acaso? ¿era acaso mas hermosa, mas enamorada que Ketirah?\"},{\"heading\":false,\"text\":\"Satanás se ha apoderado del infante, solo á Ketirah vé, solo á Ketirah ama, solo por Ketirah vive.\"},{\"heading\":false,\"text\":\"Ha olvidado á su hermana, á la pobre María.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡si el rey muriese y tú fueras rey! dice en un momento de pasion Ketirah.\"},{\"heading\":false,\"text\":\"--¿Y no aborrecerias tú á quien matase á Abul-Walid? dice el infante.\"},{\"heading\":false,\"text\":\"--Yo le daria mis joyas, porque con la muerte del rey me habria dado la joya de mi corazon que eres tú, amado mio, luz de mi alma, sueño de mi sueño. ¡Oh! ¿cuánto he sufrido amándote sin que tú comprendieras mi amor? Creía que Dios me castigaba dándome un infierno. Y esta noche, esta noche cuando me has pedido la honra de bailar contigo, cuando me has llamado respetuosamente sultana, he llorado dentro de mi corazon, porque no me creias tu esclava, como lo crees ahora. Porque tú sabes que soy tu esclava, que mi voluntad es tu voluntad, mi alegría tu alegría y un suspiro de amor de tu boca el suspiro de mis suspiros. Mata á Abul-Walid, mátale. Yo no le amo: me uní á él por ambicion, y le aborrecí y aborrecí su grandeza cuando fuí suya. Mátale, y sino te atreves á matarle, le mataré yo.\"},{\"heading\":false,\"text\":\"Ebn-Ismail recordó entonces la conjuracion de los enemigos de Masud-Almoharaví en las cuevas de Dinadamar, y recordó á María.\"},{\"heading\":false,\"text\":\"--Mañana morirá el rey, dice con voz segura á Ketirah.\"},{\"heading\":false,\"text\":\"--¡Mañana!\"},{\"heading\":false,\"text\":\"--Sí; pero para que mañana muera, es necesario que me separe de tí esta noche.\"},{\"heading\":false,\"text\":\"--¡Oh! pues si nuestra separacion ahora, ha de procurarnos una union eterna, vé, amado mio, vé, mañana te espero.\"},{\"heading\":false,\"text\":\"El infante se separa de la sultana y pasa sereno y tranquilo delante del rey.\"},{\"heading\":false,\"text\":\"--¡Oh! dice Abul-Walid: no diré á nadie mí deshonra, pero me vengaré: primero tú infante de Granada, para que el corazon de esa infame que te ama se rompa, y luego ella para que te acompañe... en la muerte.\"},{\"heading\":false,\"text\":\"Y el rey disimulando su rabia se acerca á la sultana, la saluda y la sonrie.\"}]},{\"title\":\"La puerta del juicio. — capítulo XIII\",\"blocks\":[{\"heading\":false,\"text\":\"Ebn-Ismail entre tanto, sale de Generalife por la parte alta, desciende rápidamente por la falda de la Silla del Moro, llega á los cármenes del Darro, atraviesa el rio, trepa por la opuesta vertiente, recorre una ladera y se encuentra en el barranco donde están las cuevas de Dinadamar.\"},{\"heading\":false,\"text\":\"Pero reina un silencio profundo: la luna ilumina en paz desde lo mas alto del cielo el barranco: todas las cuevas están cerradas[83] y oscuras.\"},{\"heading\":false,\"text\":\"--¿Me habrá engañado el viejo que encontré en el castillo? dice Ebn-Ismail adelantando por el barranco: ¿aquí no hay señal alguna de conspiracion ni de conspiradores?\"},{\"heading\":false,\"text\":\"Pero no ha acabado aun de pronunciar el infante estas palabras, cuando de detrás de una breña salta un moro cubierto el rostro con la toca, y le pone al pecho una ballesta armada y le dice:\"},{\"heading\":false,\"text\":\"--Detente sino quieres morir.\"},{\"heading\":false,\"text\":\"Y el infante se detiene y se alegra, porque en aquel hombre que le amenaza, vé un indicio de la conspiracion.\"},{\"heading\":false,\"text\":\"--¿Quién eres? le pregunta el moro encubierto.\"},{\"heading\":false,\"text\":\"--Soy el infante Ebn-Ismail, que busco á los caballeros que conspiran contra el wazir Masud-Almoharaví.\"},{\"heading\":false,\"text\":\"--¿Sabes los nombres de esos caballeros, ó siquiera el de uno solo de ellos?\"},{\"heading\":false,\"text\":\"--No lo sé.\"},{\"heading\":false,\"text\":\"--Pues entonces debes morir.\"},{\"heading\":false,\"text\":\"--No; mas bien llévame entre ellos: vengo solo, nadie me sigue: si soy traidor mas seguro estaré entre los conjurados, y si me matas, la conjuracion no tendrá efecto, porque yo soy el que la ha de alentar y hacer posible.\"},{\"heading\":false,\"text\":\"Parecian contener al moro estas palabras, dá un silvido y acuden otros moros; habla con ellos algunas palabras en voz baja el primero, y los otros van á reconocer los alrededores. Cuando se convencen que nadie hay en ellos, que el infante viene solo, vuelven, asen del infante, le vendan los ojos, le levantan en alto y le llevan: el infante siente abrir una puerta, bajar despues á los que le conducen unas escaleras, atravesar un largo espacio pendiente, detenerse y adelantarse uno de ellos solo. Poco despues escucha los pasos de aquel hombre que llega á los otros, habla en voz baja con ellos y siguen con el infante y le dejan en tierra y se retiran.\"},{\"heading\":false,\"text\":\"Entonces oye una voz que le dice:\"},{\"heading\":false,\"text\":\"--¿Eres tú el infante Mohammet-Ebn-Ismail, hijo del walí de Algeciras y primo del rey?\"},{\"heading\":false,\"text\":\"--Sí, contesta el infante.\"},{\"heading\":false,\"text\":\"--¿Quién te ha dado noticias de que estábamos aquí reunidos?\"},{\"heading\":false,\"text\":\"--Un astrólogo á quien he consultado.\"},{\"heading\":false,\"text\":\"--Has sido imprudente.\"},{\"heading\":false,\"text\":\"--El astrólogo no nos hará traicion.\"},{\"heading\":false,\"text\":\"--¿Y te conjuras tú contra el rey?\"},{\"heading\":false,\"text\":\"--Sí, quiero matarle.\"},{\"heading\":false,\"text\":\"--¿Por qué razon?\"},{\"heading\":false,\"text\":\"--Me ha quitado una cautiva en la toma de Martos.\"},{\"heading\":false,\"text\":\"--Y crees tú que se pueda matar al rey.\"},{\"heading\":false,\"text\":\"--Yo, si me ayudais le mataré mañana.\"},{\"heading\":false,\"text\":\"--¡Mañana!\"},{\"heading\":false,\"text\":\"--Sí, yo mismo, por mi mano.\"},{\"heading\":false,\"text\":\"--¿Será preciso que se amotine el pueblo?\"},{\"heading\":false,\"text\":\"--Se le amotina.\"},{\"heading\":false,\"text\":\"--No tenemos bastante dinero para ello.\"},{\"heading\":false,\"text\":\"--Le tengo yo, dice el infante: y se arranca la venda de los ojos.\"}]},{\"title\":\"La puerta del juicio. — capítulo XIV\",\"blocks\":[{\"heading\":false,\"text\":\"Encontróse en un ancho subterráneo de negra bóveda y de muros húmedos.\"},{\"heading\":false,\"text\":\"Aquel subterráneo presenta por todas partes señales indudables de que es una cisterna.\"},{\"heading\":false,\"text\":\"Alrededor hay de pie multitud de moros, algunos de los cuales tienen hachas encendidas en las manos.\"},{\"heading\":false,\"text\":\"El infante vé que la mayor parte de aquellos caballeros son amigos suyos.\"},{\"heading\":false,\"text\":\"--¿Por qué, pues, habeis desconfiado de mí? dice.\"},{\"heading\":false,\"text\":\"--Se vé el rostro de los amigos, contesta el que antes habia hablado, pero no se vé el corazon.\"},{\"heading\":false,\"text\":\"--Aprovechemos el tiempo, replica el infante: ya es alta la noche, y yo pienso matar al rey mañana cuando esté en su trono de justicia.\"},{\"heading\":false,\"text\":\"--¿Y tambien al wazir Masud-Almoharaví? preguntan algunos.\"},{\"heading\":false,\"text\":\"--Al wazir tambien, dice el infante.\"},{\"heading\":false,\"text\":\"--Si nos dás el oro que sea necesario, aun nos queda tiempo bastante para pagar la gente aventurera, los mendigos y los alborotadores, y producir un motin, dice otro.\"},{\"heading\":false,\"text\":\"--Oro tendreis cuanto sea necesario, replica el infante.\"},{\"heading\":false,\"text\":\"--Pero, si hemos de matar al rey, dice el que primero ha hablado, es necesario que pensemos en quién ha de sucederle.\"},{\"heading\":false,\"text\":\"--¿Y quién ha de sucederle mejor que su hijo y de la sultana Aleidah? dice el infante.\"},{\"heading\":false,\"text\":\"--El príncipe Mohammet es muy jóven aun, dicen la mayor parte de los conjurados.\"},{\"heading\":false,\"text\":\"Y--No faltará quien gobierne durante su juventud, dice el infante.\"},{\"heading\":false,\"text\":\"Trátase al fin el negocio, líganse unos á otros con juramentos, dánse señas, salen de la cueva, y dos de ellos acompañan al infante á su casa á recibir el dinero con que habia de pagarse la sublevacion del populacho.\"},{\"heading\":false,\"text\":\"El infante queda solo.\"},{\"heading\":false,\"text\":\"Pero no se recoge al lecho.\"},{\"heading\":false,\"text\":\"Pasa lo que resta de noche paseándose por su cámara, delirando como un ébrio, y encendida el alma con el ardiente recuerdo de las caricias de la tentadora sultana Ketirah.\"}]},{\"title\":\"La puerta del juicio. — capítulo XV\",\"blocks\":[{\"heading\":false,\"text\":\"Al dia siguiente el infante Ebn-Ismail, su hermando Yshac, y como hasta cincuenta caballeros parciales suyos, aparecen en la Puerta del Juicio de la Alhambra dentro del círculo de los guardas, y al pie del trono de justicia.\"},{\"heading\":false,\"text\":\"Su nobleza les concede aquel lugar que nadie les ha disputado.\"},{\"heading\":false,\"text\":\"Aun no ha salido el sol, y el rey no se ha sentado en el trono de justicia.\"},{\"heading\":false,\"text\":\"Pero ya están allí el estandarte real, y los guardas, y los que esperan para esponer sus quejas.\"},{\"heading\":false,\"text\":\"Nótase algo de sombrío en el semblante de Ebn-Ismail y de los caballeros que le acompañan.\"},{\"heading\":false,\"text\":\"Sus miradas inquietas parece que esperan la aparicion de algo que tarda, y sus oidos atentos un rumor que no suena.\"},{\"heading\":false,\"text\":\"Y no es el rey lo solo que esperan. No es el alarido de las trompetas que anuncian su llegada el ruido único que ansían escuchar; porque sus miradas y su atencion tanto parecen dividirse entre el interior del alcázar y el esterior de él.\"},{\"heading\":false,\"text\":\"Al fin suena un alto alarido de trompetas, añafiles y atakebiras en la parte de adentro, y el infante Ebn-Ismail y los caballeros que le acompañan se inquietan y palidecen.\"},{\"heading\":false,\"text\":\"El rumor se acerca mas.\"},{\"heading\":false,\"text\":\"Nuevas guardias rodean el trono de justicia, y al fin aparece el rey Abul-Walid, que se sienta en medio de su magestad en el trono, y,\"},{\"heading\":false,\"text\":\"--¿Qué quieren mi noble primo y mis caballeros? dice con voz ronca al infante y á los que le rodean al pie del trono.\"},{\"heading\":false,\"text\":\"El infante mira á los suyos, y estos como que parecen decirle con sus miradas espera; y,\"},{\"heading\":false,\"text\":\"--Venimos á pedirte justicia, señor, contesta Ebn-Ismail: pero los pobres y los menestrales esperan tambien: juzga sus agravios antes que los nuestros, invencible sultan.\"},{\"heading\":false,\"text\":\"LETRE dibº y litº Lit de J.J. MARTINEZ Madrid]\"},{\"heading\":false,\"text\":\"Masud-Almoharaví, que acompaña al rey, mira con recelo al infante y á los suyos, pero no se atreve á espresar sus temores, porque no son por la vida del rey, sino porque espera que aquellos caballeros se quejen de él amargamente al rey, y el segundo wazir, que tambien al rey acompaña, permanece en su puesto y sin recelar nada, grave é inmóvil.\"},{\"heading\":false,\"text\":\"Empieza la audiencia, y sigue, y es larga, porque son muchos los querellosos que acuden al rey.\"},{\"heading\":false,\"text\":\"Quedan sin embargo pocos, y los conjurados no oyen el rumor que esperaban, y que debe ser la señal para consumar su delito.\"},{\"heading\":false,\"text\":\"En fin, el último de los del pueblo es oido, y no habiendo ya mas á quien juzgar, el rey dirige severamente la palabra á Ebn-Ismail.\"},{\"heading\":false,\"text\":\"--¿De qué tienes que quejarte, mi noble primo? le dice.\"},{\"heading\":false,\"text\":\"En aquel momento suena un rumor sordo en la parte de la ciudad, allá abajo, que aumenta y zumba.\"},{\"heading\":false,\"text\":\"El semblante de Ebn-Ismail palidece aun mas; sus ojos centellean, y dice adelantando hácia el trono.\"},{\"heading\":false,\"text\":\"--Me querello de tu tiranía, dice sin inclinarse, con la frente alta y terrible acento de amenaza.\"},{\"heading\":false,\"text\":\"El rey palidece y tiembla de cólera; salta abajo del trono empuñando su espada, y se dirige furioso á Ebn-Ismail apellidándole traidor.\"},{\"heading\":false,\"text\":\"Pero Ebn-Ismail mas pronto, ó mas afortunado, ase al rey por sus vestiduras, le arroja contra la puerta, saca un puñal de la manga de su aljuba, y dice con voz terrible hiriendo al rey:\"},{\"heading\":false,\"text\":\"--¡Tú me robaste en Martos una doncella cristiana, y yo te robo la vida!\"},{\"heading\":false,\"text\":\"Y en el mismo punto, y cuando el rey cae exánime, y el segundo wazir, que ha pretendido defender al rey, cae hecho pedazos por los conjurados, el rumor, los gritos que se acercan, resuenan ya distintos, y se escucha á una turba inmensa que adelanta hácia el alcázar gritando:\"},{\"heading\":false,\"text\":\"--¡Muera el wazir Masud-Almoharaví! ¡muera el tirano!\"},{\"heading\":false,\"text\":\"Y la confusion cunde, y los guardas se arremolinan, y Ebn-Ismail y los suyos se abren paso con sus espadas entre la revuelta y sorprendida guardia africana, y se reunen al populacho que llega sediento de la sangre del wazir, escitado y pagado por los caballeros de la conjuracion, y gritando cada vez con mas furor:\"},{\"heading\":false,\"text\":\"--¡Muera el wazir Masud-Almoharaví! ¡muera el ladron! ¡muera el tirano!\"},{\"heading\":false,\"text\":\"Y en aquel momento terrible, el wazir amenazado, ase al rey moribundo, le carga sobre sus hombros, y se pierde con él en el interior del alcázar, despues de gritar á los de la guardia africana:\"},{\"heading\":false,\"text\":\"--¡Cerrad las puertas! ¡á los muros los ballesteros! ¡sígame, siga al rey el que no sea traidor!\"},{\"heading\":false,\"text\":\"Y la puerta cierra sus dos hojas de hierro antes que puedan llegar los conjurados, que sacian su corage despedazando á los africanos que han quedado fuera, y combaten inútilmente durante todo aquel dia el alcázar, del cual son rechazados.\"}]},{\"title\":\"La puerta del juicio. — capítulo XVI\",\"blocks\":[{\"heading\":false,\"text\":\"Todo es confusion dentro y fuera de palacio.\"},{\"heading\":false,\"text\":\"El rey moribundo ha sido conducido á la cámara de la sultana Ketirah, cuya alma se alegra, pero á cuyos ojos asoman lágrimas.\"},{\"heading\":false,\"text\":\"Arrójase sobre el rey, llora, gime, se mesa los cabellos y pretende cerrar con sus labios sus heridas.\"},{\"heading\":false,\"text\":\"Y el rey moribundo vuelve á ella los turbios ojos, la reconoce y grita:\"},{\"heading\":false,\"text\":\"--¡Esta! ¡esta! ¡la infame adúltera, es la causa mi muerte! ¡Apartadla, apartadla de mí, y descabezadla! ¿No lo oís? ¿No soy yo el rey? ¿Nadie me obedece?\"},{\"heading\":false,\"text\":\"Pero con la sultana y con el rey solo está Masud-Almoharaví: el cómplice del parricidio de Ketirah, el envenenador de la sultana Aleidah, y no se mueve.\"},{\"heading\":false,\"text\":\"--¿Es verdad lo que el sultan moribundo dice? pregunta el wazir á Ketirah.\"},{\"heading\":false,\"text\":\"--Sí, sí: amo al infante Ebn-Ismail, dice Ketirah la terrible muger que no sabe conservar mucho tiempo el disimulo: le amo y me ama. ¿Qué me importa todo? yo no negaré nunca mi amor.\"},{\"heading\":false,\"text\":\"Masud se estremece y mira si hay alguien que los escuche.\"},{\"heading\":false,\"text\":\"Pero nadie hay en la cámara.\"},{\"heading\":false,\"text\":\"--¡Silencio, imprudente! grita poniendo una mano en la boca de la sultana. ¡Si alguien te oyera rodarian nuestras cabezas! ¡Pero ese hombre está espirando! añade mirando al rey: ¡Granada está alborotada! ¡Es necesario prevenir el primer ímpetu de la irritada muchedumbre! ¡Voy!... ¡es preciso que yo salga de aquí! ¡Quédate tú; no te separes de él; está espirando; pero si antes de espirar entrase alguien!... ¡antes de que hable, Ketirah!...\"},{\"heading\":false,\"text\":\"Ketirah lanza una mirada terrible al rey, que dice á Masud que ella le ha comprendido y Masud sale.\"},{\"heading\":false,\"text\":\"Y el rey que lo ha oido todo, que ha comprendido lo horrible de su situacion, pretende levantarse y prorrumpe en gritos.\"},{\"heading\":false,\"text\":\"Pero Ketirah sofoca sus gritos, cubriéndole la cabeza con su almaizar, y el rey lucha, y con la lucha sale á borbotones la sangre de las heridas.\"},{\"heading\":false,\"text\":\"El rey ya no puede gritar, nadie puede oirle.\"},{\"heading\":false,\"text\":\"Ketirah continúa sofocándole, implacable y terrible con el almaizar.\"},{\"heading\":false,\"text\":\"Y el rey continúa luchando.\"},{\"heading\":false,\"text\":\"Y la sangre brotando de las heridas.\"},{\"heading\":false,\"text\":\"Satanás se sonrie escondido en la cúpula.\"}]},{\"title\":\"La puerta del juicio. — capítulo XVII\",\"blocks\":[{\"heading\":false,\"text\":\"Entre tanto Masud-Almoharaví sale al patio á sosegar á la guardia que está revuelta, y la gente que se agolpa fuera del alcázar, y les dice:--Que el rey está vivo, que sus heridas son leves, y que pronto le verán sano y salvo.\"},{\"heading\":false,\"text\":\"Para sincerarse, ó mas bien para evitar toda sospecha respecto á Ketirah, manda prender de órden de la sultana á algunos de los que habian estado en el motín, y de órden de la sultana los descabeza en el acto y manda poner sus cabezas en las almenas de la Puerta del Juicio.\"},{\"heading\":false,\"text\":\"Despues entra de nuevo en la cámara de la sultana.\"},{\"heading\":false,\"text\":\"El rey habia muerto.\"},{\"heading\":false,\"text\":\"La sultana le miraba friamente.\"},{\"heading\":false,\"text\":\"Acababa de espirar, y Ketirah tenia las manos teñidas en sangre.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡qué es eso! esclama Masud al ver las rojas manos de la sultana.\"},{\"heading\":false,\"text\":\"--Una puñalada mas; responde friamente Ketirah. Tardaba mucho en morir, sentí pasos que se acercaban, y no sabiendo que eran los tuyos, sentí miedo.\"},{\"heading\":false,\"text\":\"Y Ketirah se encamina á la fuente que surge en el centro de la cámara y lava tranquilamente sus manos y su puñal, que cuando está limpio envaina y guarda entre su ceñidor de púrpura.\"},{\"heading\":false,\"text\":\"--Yo amo al infante Ebn-Ismail, dice poniendo las manos en los hombros de Masud y acariciándole con su mirada. Quiero que sea sultan. Quiero ser su sultana.\"},{\"heading\":false,\"text\":\"Masud se estremece.\"},{\"heading\":false,\"text\":\"--¡Imposible! esclama: hé mandado cortar las cabezas de algunos paciales del infante Ebn-Ismail, y este anda huyendo.\"},{\"heading\":false,\"text\":\"--¿Y por qué has ajusticiado á esos hombres?\"},{\"heading\":false,\"text\":\"--Para que el pueblo no nos hiciera pedazos.\"},{\"heading\":false,\"text\":\"--Quiero que el amado de mi alma sea sultan, y yo ser sultana; replica con doble insistencia Ketirah.\"},{\"heading\":false,\"text\":\"--El pueblo no recibirá un rey que tiene teñidas las mano en la sangre de Abul-Walid, á quien amaba. El pueblo mirará con horror á la esposa de Abul-Walid entre los brazos de su asesino.\"},{\"heading\":false,\"text\":\"--¿Y qué hemos de hacer? ¿hé de perder yo á mi amado?\"},{\"heading\":false,\"text\":\"--Gozar puedes sus amores sin zozobra y en secreto, siendo gobernadora del reino conmigo á nombre del príncipe Mohammet.\"},{\"heading\":false,\"text\":\"--¡El hijo de Aleidah!\"},{\"heading\":false,\"text\":\"--¿No murió su madre?...\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿No es débil de salud el príncipe?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--Si dentro de un año, pasado ya el horror que hoy siente el pueblo por el infante Ebn-Ismail, muriese el rey Mohammet...\"},{\"heading\":false,\"text\":\"--¿Entonces mi adorado podria ser proclamado rey?\"},{\"heading\":false,\"text\":\"--Quién lo duda.\"},{\"heading\":false,\"text\":\"--¿Y seré yo entre tanto gobernadora?...\"},{\"heading\":false,\"text\":\"--Conmigo.\"},{\"heading\":false,\"text\":\"--¡Vé entonces, vé, Masud! ¡yo me quedo guardando al rey muerto! ¡vé tú á proclamar al rey vivo!\"},{\"heading\":false,\"text\":\"Vuelve á salir Masud de la cámara de Ketirah, y dice á la guardia berberisca y á su caudillo Ozmin que el rey vá muy bien.\"},{\"heading\":false,\"text\":\"Luego sale por la ciudad, habla á sus amigos y les dice que vayan á palacio para autorizar y defender lo que conviene al bien comun y particular de todos ellos.\"},{\"heading\":false,\"text\":\"Trae á cuantos amigos puede á palacio, los deja en el patio con la guardia, y entra en la cámara de la sultana.\"},{\"heading\":false,\"text\":\"Poco despues envia un mensage al caudillo Ozmin y á todos los caballeros diciéndoles que pasen al salon, que el rey, mas restablecido, les quiere hablar.\"},{\"heading\":false,\"text\":\"Entran todos en el salon de Embajadores, y cuando toda la nobleza de la córte está junta, se presenta la sultana Ketirah doliente, llorosa y enlutada, llevando de la mano al príncipe Mohammet, niño de poca edad.\"},{\"heading\":false,\"text\":\"Masud les anuncia la muerte del rey, y los compele á que juren al jóven príncipe.\"},{\"heading\":false,\"text\":\"Amigos los unos del rey difunto, sobrecogidos otros, aunque no faltaban ambiciones, juran á Mohammet-ebn-Ismail-ebn-Nazar por su rey y señor.\"},{\"heading\":false,\"text\":\"Luego toda la nobleza y la guardia salen por las calles y repiten en Granada la proclamacion del nuevo rey.\"},{\"heading\":false,\"text\":\"Pero aquella noche una sombra se desliza por la cuesta que rodea las espaldas de la Alhambra, llega al pie de una torre y hace una señal; cae una escala, y el bulto trepa por ella hasta un ajimez.\"},{\"heading\":false,\"text\":\"Luego se escucha un beso entre el silencio, y el ajimez se cierra.\"},{\"heading\":false,\"text\":\"El asesino y su cómplice la adúltera, están entregados á su amor, y Masud-Almoharaví, el infame, vela sus placeres.\"}]},{\"title\":\"La puerta del juicio. — capítulo XVIII\",\"blocks\":[{\"heading\":false,\"text\":\"El desdichado rey Abul-Walid fué sepultado en la randa ó panteon del alcázar junto á sus abuelos.\"},{\"heading\":false,\"text\":\"Sobre su tumba se puso la inscripcion siguiente:\"},{\"heading\":false,\"text\":\"«Este es el sepultcro del rey mártir, conquistador de las fronteras, defensor de la religion, el ínclito, el escogido, el reparador de la familia de los Nazares, el príncipe justo, el amparador, el denodado, el héroe de la guerra y de las batallas, el noble, el generoso, el mas afortunado de los reyes de su dinastía, el mas aventajado en piedad y celo de la honra de Dios, espada de la guerra santa, muro de los pueblos, fortaleza de los caudillos, amparo de los nobles, alivio de los pobres, el compasivo con los que temian, el domador de los soberbios, laborioso en el camino de Dios, vencedor por la gracia de Dios, príncipe de los Muzlimes Abul-Walid-Ismail, hijo del amparador escelso, del vencedor, escogido, noble, vengador, engrandecedor de la familia Nazaria, columna de la dinastía Algalibia, el piadoso, el compasivo Abu-Said-Ferag, hijo del noble y esclarecido defensor de los defensores del Islam, decoro de los príncipes algalibes, honor, alteza de la prosapia, el santo, el piadoso Abul-Walid-Ismail-ebn-Nazar, santificado sea su espíritu en bienaventuranza, sea refrigerado con el rocío de la misericordia, séale concedido ámplio galardon por premio de sus certámenes meritorios, por su martirio, pues lo hizo Dios conquistador de pueblos, debelador de soberbios reyes enemigos suyos, y fué atesorando méritos hasta el dia señalado que Dios le destinó para que llegado el plazo sellase sus dias con buenas obras; recíbale y colóquele en lugar de retribucion y honra, lugar que tenia preparado por su santo celo: murió, Dios le perdone, á traicion, pero con gloria y en la firme pura confesion de los reyes sus antepasados, y fué elevado á las moradas de eterna felicidad: nació, complázcase Dios de él, en hora bienaventurada entre manos del alba del dia giuma diez y siete de la luna de jawal, año seiscientos setenta y siete[84]: fué jurado dia jueves veinte y siete de jawal, año setecientos trece[85], y fué muerto en dia lunes veinte y seis de la luna de regeb insigne, año setecientos veinte y cinco[86]. Alabado sea el rey verdadero, que mientras todas las criaturas acaban y se suceden, permanece eterno é inmutable.»\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"La leyenda que acabamos de relataros es la referente á las manchas sangrientas de la Puerta del Juicio del alcázar de la Alhambra.\"}]},{\"title\":\"La torre de la cautiva. — capítulo I\",\"blocks\":[{\"heading\":false,\"text\":\"Si cuando os encontrais en la plaza de los algibes de la Alhambra os volveis hácia el palacio del emperador Cárlos V, y siguiendo á lo largo de su fachada meridional, torceis á la izquierda entre este mismo palacio y la iglesia de Santa María, y seguís luego un pequeño paseo plantado de titos, continuando por el camino que conduce á la puerta de Hierro, os encontrareis al poco espacio delante de la torre de los Picos.\"},{\"heading\":false,\"text\":\"Por cima de los adarves del muro que se apoya en la torre, vereis sobre el monte frontero, verde con el eterno verdor de sus laureles, las blancas torrecillas y las galerías de Generalife: á la izquierda se estenderá vuestra vista en un espacio mas ancho; vereis el monte de San Miguel con el verde pálido de sus nopales, y la ermita del santo Arcángel en la cima, y mas allá, dominándole, el alto y árido cerro de Ainadamar.\"},{\"heading\":false,\"text\":\"Pero si volveis la vista á la derecha encontrareis á pocos pasos un muro revestido de espesa yedra, que se apoya en la torre de los Picos, y en el cual hay un porton de tablas.\"},{\"heading\":false,\"text\":\"Llegad, llamad á aquel porton, y pedid que os dejen pasar por favor, porque aquella es una propiedad particular.\"},{\"heading\":false,\"text\":\"Una vez dentro, encontrareis un arroyo ruidoso que corre junto á las banquetas de los adarves, por la izquierda, entre yerbecillas y violetas, á la derecha árboles frutales y hortalizas, y entre estas y el arroyo el estrecho sendero por donde marchais.\"},{\"heading\":false,\"text\":\"A poco que adelanteis encontrareis una pequeña torre, la torre del Tesoro, abierta por el lado que mira á la parte de adentro del muro, dejando ver los tramos cortados y ruinosos de su estrecha escalera árabe, sus bóvedas grieteadas y su plataforma que amenaza un hundimiento. Seguid adelante, y á medio tiro de fusil encontrareis la torre que vamos buscando.\"},{\"heading\":false,\"text\":\"La torre de la Cautiva.\"},{\"heading\":false,\"text\":\"Entrase á esta torre por una puerta baja de herradura, situada al norte: despues de un desmantelado ingreso, se entra en un patio sostenido en pilares de ladrillo, patio cuya luz es tan estrecha, que mas que patio parece una chimenea: al fondo de este patio sombrío está una pequeña puerta, á la que se llega dejando á la izquierda la estrecha escalera que conduce, ascendiendo, á la plataforma, descendiendo, á una habitacion inferior y despues á los subterráneos.\"},{\"heading\":false,\"text\":\"Abierta la pequeña puerta del fondo que hemos citado, se penetra en una cámara destrozada, pero que por los restos que en ella quedan de estucos labrados, de alhamies, de ajimeces, de la cúpula de estalácticas; por la faja de mosáico que orla la parte inferior de las paredes, se comprende que debió ser tan magnífica como cualquiera otra de las hermosas cámaras del alcázar.\"},{\"heading\":false,\"text\":\"Pero sus adornos están ahumados por el fogon de la pobre familia que tiene por albergue miserable un alcázar destruido: tabiques que sirven de compartimientos alteran el plano; los ajimeces están tapiados y cubiertos por miserables ventanas de tablas tendidas; el pavimento destrozado, polvoroso; la cúpula agujereada, rota por la lluvia que se filtra por la desnuda plataforma, en la cual brota la yerba. Con la Alhambra se han cometido y se están cometiendo barbáries inauditas: no parece sino que se tiene empeño en que desaparezca, en que se destruya. ¡Como si fuera una cosa fácil y hacedera el construir una Alhambra!\"},{\"heading\":false,\"text\":\"Algunas tardes de invierno, envueltos en nuestra capa, cubierto el rostro con un ancho calañés, bajo un cielo densamente nublado, bajo la lluvia, hemos pasado por el sendero de esa huerta, junto á las torres de los Picos, de la Cautiva y de las Infantas, y por las puertas y por las ventanas de todas ellas hemos visto salir un humo espeso que arrebataba incesantemente el viento, y que incesantemente se reproducia. Era que las pobres familias habitantes de esas torres infortunadas, se calentaban con la leña húmeda y verde que acababan de arrancar de los desnudos árboles de la huerta.\"},{\"heading\":false,\"text\":\"Era que una nueva capa de ollin caia sobre los arabescos.\"},{\"heading\":false,\"text\":\"Y al ver esto, rebosaba de nuestro pecho un hondo suspiro, porque no éramos bastante ricos, bastante poderosos para arrancar á aquellas torres de su ignominiosa esclavitud.\"}]},{\"title\":\"La torre de la cautiva. — capítulo II\",\"blocks\":[{\"heading\":false,\"text\":\"Pero en 1325, época de la muerte del rey Abul-Walid, era distinto el estado y el destino de esta torre.\"},{\"heading\":false,\"text\":\"Entonces la puerta, que correspondia á un pequeño y bello jardin, era de graciosa herradura, ornamentada, embaldosado de mármol blanco el ingreso, cerrada por dos hojas de alerce labrado con labores y cintas caprichosamente entrelazadas; aquel patio de paredes blancas y brillantes tenia mas luz; aquella cámara, en fin, con su preciosa puerta estucada, con sus tres alhamies con ajimeces al fondo, con sus paredes resplandecientes y matizadas como el mas bello brocado, con su cúpula de estalácticas, estrellada como un cielo, con su lámpara de ágata pendiente de la cúpula, con su alizar ó faja de mosáicos, con su pavimento de mosáico tambien, semejante á una rica alfombra, y en el centro del cual corria clara y murmurante el agua de una fuente; aquella cámara, repetimos, era un apartamento delicioso, donde solo podía pensarse en el amor.\"},{\"heading\":false,\"text\":\"Debajo de esta cámara habia otra mas pequeña, menos alumbrada, pero con una luz mas vaga, mas misteriosa; habia en entrambas la misma riqueza; en entrambas orlaban las paredes blandos divanes, en entrambas los braserillos de plata consumian continuamente los perfumes mas preciados: aquella torre tan severa por la parte esterior, tan desnuda como un guerrero revestido de su coraza, en su parte interna, era un nido de amor.\"},{\"heading\":false,\"text\":\"Era en fin el retiro donde el rey Abul-Walid habia encerrado á María, y por esta razon la torre se llama, desde entonces, torre de la Cautiva.\"}]},{\"title\":\"La torre de la cautiva. — capítulo III\",\"blocks\":[{\"heading\":false,\"text\":\"Aun estaban calientes los restos de Abul-Walid, aun llevaba por él luto la corte, cuando dos sombras cuidadosamente encubiertas salian del alcázar, atravesaban pegados á los adarves la parte alta de la Alhambra, llegaban á la torre de la Cautiva, y una de ellas abria su puerta, entraban las dos sombras y la puerta tornaba á cerrarse.\"},{\"heading\":false,\"text\":\"Entonces á la luz de una lámpara que iluminaba el patio de la torre se veia que estas dos personas, que se habian despojado ya, seguras de no ser vistas, la una de su velo, la otra del capuz de su almaizar, eran la sultana Ketirah y el wazir Masud-Almoharaví.\"},{\"heading\":false,\"text\":\"Los dos infames cómplices.\"},{\"heading\":false,\"text\":\"Ella bajo su ancho haike iba deslumbrantemente engalanada.\"},{\"heading\":false,\"text\":\"El mostraba brocados bajo su ancho almaizar.\"},{\"heading\":false,\"text\":\"El wazir bajaba con la sultana por las escaleras á la habitacion inferior de la torre.\"},{\"heading\":false,\"text\":\"Luego subia otra vez las escaleras, llegaba á la puerta de la habitacion superior, la abria y entraba.\"},{\"heading\":false,\"text\":\"La sultana cuando se quedaba sola, abria una ventana que daba sobre el pendiente barranco que rodea la espalda de la Alhambra.\"},{\"heading\":false,\"text\":\"Y allí, ya fuese la noche serena, oscura, solo alumbrada de una manera vaga é infinita por el débil resplandor de los luceros, ya la pálida luna inundase la torre, la ventana, y la frente, tan maldita como hermosa de Ketirah; ya la tormenta bramase en los aires, y el relámpago rasgase las tinieblas, y la lluvia azotase su frente, y el huracan desordenase sus cabellos, la sultana permanecia inmóvil, anhelante, con el corazon estremecido, con la mirada candente y fija en lo profundo del oscuro barranco.\"},{\"heading\":false,\"text\":\"Y pasaban algunas veces horas perezosas, largas, apenadoras, sin que la sultana oyese mas que el zumbar del viento, ó el suspirar de las auras entre las frondas del cercano Generalife, ó el retumbar del trueno ó el dulce canto de los ruiseñores enamorados.\"},{\"heading\":false,\"text\":\"Y Ketirah no tenia oidos ni ojos mas que para el infante Ebn-Ismail, y parecíale estar escuchando su voz enamorada, y estar viendo siempre su hermoso semblante, pálido de amor, y sus negros ojos fijos en los suyos.\"},{\"heading\":false,\"text\":\"Solo habia un ruido que la sultana percibia desde muy lejos aunque silvase el viento y gotease la lluvia y rebramase el trueno; y este ruido era el de los pasos de un hombre que, invariablemente, tardando mas ó menos, subia por el barranco, adelantaba, se detenia al pie de la torre y lanzaba un ténue silvido.\"},{\"heading\":false,\"text\":\"Y entonces la sultana trémula de impaciencia, y estremecida de amor, enloquecida, trasportada, arrojaba una larga escala fuera de la torre, afianzaba cuidadosamente sus garfios en el alfeizar de la ventana, y avanzaba el cuerpo hácia afuera solícita y cuidadosa.\"},{\"heading\":false,\"text\":\"Poco despues la escala se atirantaba, balanceaba, y un hombre subia, llegaba al alfeizar y saltaba dentro de la habitacion entre los brazos de la sultana.\"},{\"heading\":false,\"text\":\"La lámpara que ardia lánguidamente en la cámara, alumbraba la frente del que habia entrado.\"},{\"heading\":false,\"text\":\"Aquel hombre era el infante Ebn-Ismail.\"},{\"heading\":false,\"text\":\"El infante que aun estaba fascinado por los tentadores encantos de Ketirah.\"},{\"heading\":false,\"text\":\"El infante que estaba vendido á Satanás.\"}]},{\"title\":\"La torre de la cautiva. — capítulo IV\",\"blocks\":[{\"heading\":false,\"text\":\"Entre tanto el wazir Masud-Almoharaví, estaba delante de María.\"},{\"heading\":false,\"text\":\"De María; la amante de Gonzalo, la cautiva del malaventurado Abul-Walid, la pobre huerfana abandonada, olvidada por el infante Ebn-Ismail.\"},{\"heading\":false,\"text\":\"Una noche, la noche siguiente á la en que el infante la habia prometido salvarla de los amores del rey, María, replegada en el ángulo de un divan, inmóvil y silenciosa, lloraba.\"},{\"heading\":false,\"text\":\"Y no cesaba su llanto, y un secreto temor la oprimia el alma, y triste y apenada, no se atrevia á pensar en Gonzalo.\"},{\"heading\":false,\"text\":\"Porque no sabia si le perderia porque la muerte se lo arrebatára, ó porque su desdicha la arrebatára á Gonzalo.\"},{\"heading\":false,\"text\":\"Porque María estaba resuelta á morir antes que otro hombre la robase al amado de su alma.\"},{\"heading\":false,\"text\":\"Durante el dia habia oido gritos tumultuosos al otro lado de la Alhambra por la parte de mediodía: habia visto correr á los soldados hácia el oriente por los cercanos adarves, y el eunuco mudo que la servia se habia olvidado de llevarla la comida.\"},{\"heading\":false,\"text\":\"Del mismo modo se habia olvidado de encender la lámpara.\"},{\"heading\":false,\"text\":\"La cámara estaba iluminada solo por el reflejo de la luna que entraba por un ajimez, y por los trasparentes de estuco de la cúpula, en rayos plateados.\"},{\"heading\":false,\"text\":\"Nunca tan fantástica aquella cámara; nunca mas hermosa María que entonces, apenada, doliente, anegada en llanto, al reflejo pálido de aquella luz fantástica.\"},{\"heading\":false,\"text\":\"Y, como hemos dicho, á pesar de que era la estacion de los calores, María sintió un frio mortal, un terror vago, profundo, una inquietud horrible; la parecia que no estaba sola, que habia junto á ella alguien á quien no veia, y que á pesar de no verle le parecia un ser horrible, sobrenatural, maldito.\"},{\"heading\":false,\"text\":\"María, de tiempo en tiempo y como atraida por una fuerza invisible fijaba sus ojos en el fondo oscuro del arco de la puerta de la cámara.\"},{\"heading\":false,\"text\":\"De repente pareció que en aquel fondo oscuro brillaba como humo débilmente luminoso, una forma indeterminada, que aquella forma vaga se condensaba, que tomaba al fin la figura de un hombre alto y negro.\"},{\"heading\":false,\"text\":\"Aquel hombre, ó aquella sombra adelanta lentamente hácia María.\"},{\"heading\":false,\"text\":\"Y María no gritó porque hay terrores que ahogan la voz, que hielan la sangre, y que si duran mucho tiempo, matan.\"},{\"heading\":false,\"text\":\"Aquella sombra se detuvo en el centro de la cámara, debajo de la lámpara, y estendió el brazo hasta ella y la tocó.\"},{\"heading\":false,\"text\":\"Y sin saber María cómo podia ser, porque no habia visto luz en las manos de aquel hombre, al tocar aquella mano á la lámpara, la lámpara ardió.\"},{\"heading\":false,\"text\":\"Entonces María vió á un viejo horrible.\"},{\"heading\":false,\"text\":\"En una palabra, al mago Abu-Jacub-Al-Hhakem-Billah.\"},{\"heading\":false,\"text\":\"--Estás estremecida de espanto, dijo el sabio, y es necesario que no temas, ¿y por qué has de temer? Cuando los hombres se olvidan de tí, Dios me envia á salvarte.\"},{\"heading\":false,\"text\":\"Y María como si su alma obedeciese á una voluntad poderosa, perdió su temor y miró, tranquila ya, á Abu-Jacub.\"},{\"heading\":false,\"text\":\"--¿Quién eres? le pregunta.\"},{\"heading\":false,\"text\":\"--¿Quién soy yo? replicó el viejo, ¿y qué te importa? no era mas natural que me dijeses: ¿quién soy yo?\"},{\"heading\":false,\"text\":\"--Yo soy una desdichada que muere apartada de cuanto la era amado en el mundo: la muerte me arrebató a mi padre...\"},{\"heading\":false,\"text\":\"--¡Tu padre! ¡hé aquí lo que son los hijos del hombre! ¡para ellos el corazon y la conciencia no es mas que la costumbre! ¡Tu padre! ¿sabes tú quién es tu padre?\"},{\"heading\":false,\"text\":\"--He conocido un noble anciano, que me llamaba su hija, que me amaba como á su hija, á quien yo amaba como a mi padre.\"},{\"heading\":false,\"text\":\"--¿Y crees tú que era menos noble, el padre que te dió el ser?\"},{\"heading\":false,\"text\":\"--¿Le conoceis vos?\"},{\"heading\":false,\"text\":\"--¿Qué si le conozco? ya lo creo.\"},{\"heading\":false,\"text\":\"--¿Y os envia él?\"},{\"heading\":false,\"text\":\"--No, ya te lo he dicho, me envia Dios. Hoy me envia á esta cámara, mañana me enviará debajo de esta cámara.\"},{\"heading\":false,\"text\":\"--No os comprendo.\"},{\"heading\":false,\"text\":\"--Ni te importa nada el no comprenderme en esta parte. Hablábamos de tu padre.\"},{\"heading\":false,\"text\":\"--¡Oh! ¿si habeis conocido á mi padre, conoceriais tambien á mi madre?\"},{\"heading\":false,\"text\":\"--Cierto que la conocí...\"},{\"heading\":false,\"text\":\"--¡Ah! ¿decidme?...\"},{\"heading\":false,\"text\":\"--Tu madre; doña Catalina de Cardona...\"},{\"heading\":false,\"text\":\"--¡Ah! ¿era castellana?...\"},{\"heading\":false,\"text\":\"--Era catalana...\"},{\"heading\":false,\"text\":\"--¿Pero los catalanes son cristianos?\"},{\"heading\":false,\"text\":\"--Sí ciertamente, y cristiana era tu madre, y noble, y pura, y hermosa; la muger mas hermosa de la córte de Aragon.\"},{\"heading\":false,\"text\":\"--Mi padre, el noble caballero que me ha criado y á quién no puedo menos de llamar mi padre, me dijo que me habia encontrado muy niña en mi primera infancia en una villa del reino de Granada en poder de infieles. ¿Será que acaso los moros me robaron á mis padres?\"},{\"heading\":false,\"text\":\"--No: dijo Abu-Jacub, me obligas á contarte una historia y voy á hacerlo.\"},{\"heading\":false,\"text\":\"Escúchame, pues.\"},{\"heading\":false,\"text\":\"Y Abu-Jacub empezó de esta manera.\"}]},{\"title\":\"La torre de la cautiva. — capítulo V\",\"blocks\":[{\"heading\":false,\"text\":\"Hace veinte años, el rey de Granada envió una ostentosa embajada al rey de Aragon.\"},{\"heading\":false,\"text\":\"Era embajador del rey de Granada un valiente, noble y hermoso mancebo infante de la casa real, que se llamaba Abd-el-Rahhaman-el-Ferih.\"},{\"heading\":false,\"text\":\"Se trataba de asentar unas treguas, y el rey de Granada escogió á su primo Abd-el-Rahhaman, porque era persuasivo, dulce, sabia ganar las voluntades de todo el mundo, y era además valiente y discreto.\"},{\"heading\":false,\"text\":\"Con Abd-el-Rahhaman envió el rey de Granada al de Aragon un riquísimo presente; se contaban por cientos las piedras preciosas, por docenas los caballos de arabia, y las alfombras de Persia y los perfumes y las barras de oro y plata.\"},{\"heading\":false,\"text\":\"Entre estos presentes iba una doncella de sangre real, que con un crecidísimo dote enviaba el rey moro al rey cristiano, ya para que la tomase por suya, ya para que la casase, como en honra, con el caballero de su corte que mas le viniese en agrado, ó con cualquier caballero que aunque no fuese natural de sus reinos fuese vasallo suyo.\"},{\"heading\":false,\"text\":\"Walidé, que así se llamaba la infanta granadina, habia salido del harem donde la habian criado sus ayas, con alegría: hasta entonces no habia visto mas gentes que las mugeres del harem, ni mas hombre que el rey su tio, y los silenciosos eunucos, ni se habia espaciado su vista mas que en el azul firmamento: que, en cuanto á la tierra, no habia podido pasar de los muros de los jardines del harem.\"},{\"heading\":false,\"text\":\"Ni amaba, ni sabia lo que era amor.\"},{\"heading\":false,\"text\":\"Tenia solo catorce años, y el amor dormia aun desconocido para ella en su alma.\"},{\"heading\":false,\"text\":\"Era á pesar de su juventud una muger poderosamente hermosa, blanca, gentil, modesta; pura la dulce sonrisa de sus ojos, pura la tranquila y cándida sonrisa de su boca.\"},{\"heading\":false,\"text\":\"Cuando Walidé se vió fuera de la Alhambra, sobre las amugas de brocado de su blanca hacanca, rodeada de guardas negros á caballo y acompañada de Abd-el-Rahhaman, que solícito no se apartaba de ella un punto, sonrió al primer hombre hermoso que veia.\"},{\"heading\":false,\"text\":\"Y Abd-el-Rahhaman, á pesar de haberse casado cuatro años antes y de tener un hijo, se estremeció ante aquello primera sonrisa de amor casi virgen, ante aquella dulce y tranquila mirada que decia amor sin saberlo.\"},{\"heading\":false,\"text\":\"Y luego, cuando Walidé salió por la puerta de Elvira de la ciudad, y vió estenderse ante ella la ancha vega con sus mil colores, con sus mil aldeas, con sus lejanas montañas azules, sonrió y miró con amor á aquel verdor riente, engalanado, magnífico con sus vapores dorados bajo el sol de la mañana, como habia sonreido y mirado con amor al hermoso y gentil infante Abd-el-Rahhaman.\"},{\"heading\":false,\"text\":\"Walidé empezaba á vivir.\"},{\"heading\":false,\"text\":\"Empezaba á abrir su alma al amor, pero de una manera tranquila, inocente, como era tranquila é inocente su alma.\"},{\"heading\":false,\"text\":\"En mal hora el rey su tio, necesitado de paces con el cristiano, habia fijado su mirada fria en la cándida hermosura de la infanta, para enviarla casi esclava á una tierra estraña, á ser la esposa de alguno de los zafios montañeses, vasallos del rey de Aragon.\"},{\"heading\":false,\"text\":\"Porque el rey de Aragon no podia como cristiano tener mas que una esposa, y siendo presentada de una manera solemne y pública en su corte Walidé, no podia hacerla su manceba sin grave escándalo.\"},{\"heading\":false,\"text\":\"El rey de Granada enviaba, pues, una doncella casadera, hermosa, noble y rica, para que su suerte se jugase á la suerte: para que deshojase aquella flor delicada el rudo choque con un montañés bravío.\"},{\"heading\":false,\"text\":\"Y la desdicha mayor fué, que el embajador del rey de Granada, su primo el infante Abd-el-Rahhaman, se enamorase ciegamente de Walidé, hasta el punto de que hizo para sí el razonamiento siguiente:\"},{\"heading\":false,\"text\":\"--Mi primo el señor rey de Granada, envia á la infanta al rey de Aragon para que la tenga para si ó la dé en matrimonio á uno de sus vasallos. El rey de Aragon no guardará para sí la infanta: sus costumbres cristianas se lo vedan: pues bien; antes de dar mi embajada al rey de Aragon, le rendiré pleito homenage por mis castillos de la frontera de Murcia, me declararé su vasallo... y despues... aunque sea necesario escitar su interés con algunos miles de doblas, procuraré que yo sea el vasallo que el rey de Aragon elija para esposo de la infanta.\"},{\"heading\":false,\"text\":\"Y fiando demasiado en sus cálculos el enamorado embajador, se dedicó á enamorar á Walidé.\"},{\"heading\":false,\"text\":\"Cuando llegaron á Tarazona, donde tenia su córte por aquellos dias el rey de Aragon don Alonso IV, ya Walidé y Abd-el-Rahhaman se amaban mútuamente, y lo que es mas, se lo habian concedido todo.\"},{\"heading\":false,\"text\":\"Porque el infante habia dilatado cuanto habia podido el viaje, haciendo jornadas muy cortas y deteniéndose á veces en un pueblo tres dias. Walidé se habia enamorado del infante desde el momento en que le habia visto, y Abd-el-Rahhaman no habia sido el mas fiel depositario.\"},{\"heading\":false,\"text\":\"Los primeros dias Walidé fué llevada por su hacanca, pero al poco tiempo, con la ocasion de pasar un rio cuyo puente se habia roto, por un vado, el infante, para asegurar á la infanta de un tropiezo y de una caida al agua, la puso sobre un cogin sobre el arzon delantero de su caballo, y la rodeó la redonda y esbelta cintura con un brazo tembloroso.\"},{\"heading\":false,\"text\":\"Walidé se estremeció y esperimentó una sensacion dulce, infinita.\"},{\"heading\":false,\"text\":\"Hasta entonces ella y él solo habian hablado con los ojos.\"},{\"heading\":false,\"text\":\"Era el principio de la noche: la numerosa embajada del infante, con sus ginetes y con sus acémilas, atravesaba una ancha sábana del Guadalquivir.\"},{\"heading\":false,\"text\":\"La luna reflejaba en las aguas, y se duplicaba en los dos brillantes ojos de Walidé, que se fijaban en ella con una dulce y pensativa melancolía, mientras el infante, conduciéndola en el arzon de su caballo, estrechaba enamorado su cintura, y bebia con su ardiente mirada, la mirada de la infanta fija en la suya.\"},{\"heading\":false,\"text\":\"Y entonces la infanta, que estaba entregada á un sueño de amor, oyó junto á sí una voz dulce, ardiente, trémula, que la decia:\"},{\"heading\":false,\"text\":\"--Yo te amo.\"},{\"heading\":false,\"text\":\"Te amo como la noche á la luna que la dá su blanca y dulce luz: te amo como el alba al sol que tiñe sus megillas de púrpura.\"},{\"heading\":false,\"text\":\"Te amo como á la tierra el mar que contínuamente la besa, y como el viento á la palmera que contínuamente la mece.\"},{\"heading\":false,\"text\":\"Amame tú, maga de mis sueños, á quien yo he amado antes de ver tu hermosura.\"},{\"heading\":false,\"text\":\"Amame tú, sino quieres que mi alma esté lóbrega como una noche sin luna, fria como una alborada sin sol, silenciosa como la tierra á quien el mar no besa, y triste y mustia como una palmera á quien no acaricia el viento.\"},{\"heading\":false,\"text\":\"--¿Y qué es amor? dijo Walidé apartando su mirada de la luna y fijándola cándida y enamorada en el infante. ¿Es por ventura el amor ese tranquilo afan del alma, que sueña y vé en sus sueños un hombre? ¿Es por ventura un dulce fuego que llena el alma y la aduerme en una delicia sin fin, junto al hombre del sueño? ¿Es por ventura el amor el que estremece la cintura de la muger cuando el hombre que ha soñado la rodea con su brazo? ¡Oh! si ese es el amor que acaricia al alma, y la consuela, y la dilata, y la enciende en un dulce fuego; si es el amor el que dá á los ojos de la muger un alma cariñosa, y dulce por los ojos de un hombre, yo te amo, señor; yo te amo como la noche á la luna, como el alba al sol, como el mar á la tierra, como el viento á la palma. Si amar es no vivir, ni pensar, ni alentar mas que para un hombre, yo te amo, señor, yo te amo.\"},{\"heading\":false,\"text\":\"Y Walidé reclinó la cabeza sobre el hombro de Abd-el-Rahhaman, que la besó en la frente.\"},{\"heading\":false,\"text\":\"Walidé se estremeció de una manera mas poderosa, y murmuró:\"},{\"heading\":false,\"text\":\"--Yo te amo: mi vida es tu amor, si me falta tu amor yo moriré.\"},{\"heading\":false,\"text\":\"Cuando llegaron, pues, á Tarazona ella y él eran los amantes mas dichosos de la tierra.\"},{\"heading\":false,\"text\":\"Abd-el-Rahhaman, en cuanto anunció su embajada á Alonso IV de Aragon, le pidió permiso para verle particularmente, y el rey se apresuró á concedérselo: al atravesar el infante una galería del alcázar, cruzó por delante de él una dama cristiana, y se detuvo un momento y palideció.\"},{\"heading\":false,\"text\":\"El infante sintió tambien á la vista de la dama no sé qué estraño presentimiento.\"},{\"heading\":false,\"text\":\"La dama siguió adelante murmurando:\"},{\"heading\":false,\"text\":\"--¡Oh! ¡qué moro tan gentil!\"},{\"heading\":false,\"text\":\"Y el infante siguió diciendo para sus adentros:\"},{\"heading\":false,\"text\":\"--¡Oh! ¡qué cristiana tan hermosa!\"},{\"heading\":false,\"text\":\"Pero ella amaba á otro hombre, y él amaba á Walidé.\"},{\"heading\":false,\"text\":\"Aquella dama que habia cruzado como una tentacion la galería, era doña Catalina de Cardona, doncella noble de la reina de Aragon.\"},{\"heading\":false,\"text\":\"--¡Era mi madre!\"},{\"heading\":false,\"text\":\"--Sí, tu madre era: respondió el mago, y despues de un momento de silencio continuó.\"}]},{\"title\":\"La torre de la cautiva. — capítulo VI\",\"blocks\":[{\"heading\":false,\"text\":\"Pero á pesar del amor que el infante sentia hácia Walidé habia quedado fija en su memoria, y en su corazon, sin poderse esplicar con qué deseo, con qué afan vago y misterioso, el recuerdo de doña Catalina de Cardona.\"},{\"heading\":false,\"text\":\"Era muy hermosa esta dama: blanca y pálida, con hermosos cabellos rubios como el oro, con hermosos ojos negros como el ébano y lucientes como el carbunclo, y magestuosa y gentil, y esbelta á maravilla: era muy jóven y su frente resplandecia de pureza.\"},{\"heading\":false,\"text\":\"Y el infante adelantaba hácia la cámara donde el rey de Aragon le esperaba, murmurando sin ser poderoso á otro pensamiento:\"},{\"heading\":false,\"text\":\"--¡Oh! ¡qué cristiana tan hermosa!\"},{\"heading\":false,\"text\":\"Y sin embargo el amor que sentia por Walidé permanecia vivo, ardiente en su corazon.\"},{\"heading\":false,\"text\":\"Cuando entró á la presencia del rey, el infante dobló una rodilla.\"},{\"heading\":false,\"text\":\"--Poderoso sultan de Aragon, dijo: el esclarecido, el vencedor, el magnífico sultan de Granada y del Andalucía, mi señor, á tí me envia: pero antes de notificarte el objeto de mi embajada, quiero declararme vasallo tuyo, no embargante el vasallage que confieso al rey mi señor natural el noble sultan de Granada, y á rendirte pleito homenaje, por mis villas y castillos de la frontera de Murcia.\"},{\"heading\":false,\"text\":\"Maravilló al rey de Aragon el vasallaje de un infante moro á quien no conocia y con el cual nunca habia tenido amistad ni guerra, pero se lo agradeció, lo aceptó, mandó llamar á su canciller, solemnizóse el pleito homenaje, y el rey de Aragon le abrazó y le besó en la megilla, mandando escribir su nombre entre los de los grandes vasallos de sus reinos.\"},{\"heading\":false,\"text\":\"--¿Por qué me habrá rendido vasallaje este moro? dijo para sí Alonso IV, cuando Abd-el-Rahhaman salia de la cámara.\"},{\"heading\":false,\"text\":\"Y Abd-el-Rahhaman murmuraba saliendo:\"},{\"heading\":false,\"text\":\"--Solo me falta satisfacer la codicia del consejero favorito del rey cristiano: yo averiguaré quién este consejero sea: le daré cuanto oro sea necesario, y Walidé será mia.\"},{\"heading\":false,\"text\":\"Y á seguida murmuraba suspirando:\"},{\"heading\":false,\"text\":\"--¡Oh! ¡y cuán hermosa! ¡cuán hermosa es aquella cristiana!\"}]},{\"title\":\"La torre de la cautiva. — capítulo VII\",\"blocks\":[{\"heading\":false,\"text\":\"Dijeron al infante que el favorito del rey de Aragon, era un noble caballero muy valiente y muy bravo, llamado Men Roger de Cardona.\"},{\"heading\":false,\"text\":\"El infante envió á Men Roger un caballo de Arabia, un arnés de Damasco, una lanza de dos hierros con pendoncillo de brocado, un rico capellar y una túnica de púrpura.\"},{\"heading\":false,\"text\":\"Men Roger recibió el presente creyendo que se trataba de que influyese con el rey de Aragon para el feliz éxito de las pretensiones del rey de Granada.\"},{\"heading\":false,\"text\":\"Men Roger, el soberbio rico-hombre de Aragon, convidó á comer al infante moro.\"},{\"heading\":false,\"text\":\"Al dia siguiente al sentarse á la mesa, vió junto á sí Abd-el-Rahhaman á la hermosísima cristiana que habia encontrado en el alcázar dos dias antes, y se turbó: ella se turbó tambien y bajó los ojos.\"},{\"heading\":false,\"text\":\"--Es mi hermana doña Catalina, dijo Men Roger al infante.\"},{\"heading\":false,\"text\":\"Y durante las cuatro horas que aquella comida duró, el infante habló de las magnificencias de la córte de Granada, y ponderó sus caballeros y sus damas, pero al ponderar á estas añadió:\"},{\"heading\":false,\"text\":\"--Y sin embargo, no he visto en Granada ni en todo su reino ni en las Alpujarras, ni en Murcia, ni en Almería, ni en Algeciras, mi patria, una dama tan hermosa como la que ví en el alcázar del rey cristiano la primera vez que entré en él.\"},{\"heading\":false,\"text\":\"Y doña Catalina al oir esto miró al moro, y el moro vió amor en la mirada de doña Catalina, y Men Roger no vió nada, porque estaba gravemente ocupado en trinchar un faisan.\"},{\"heading\":false,\"text\":\"Y al recibir la mirada de doña Catalina, dijo para sí el infante:\"},{\"heading\":false,\"text\":\"--¡Oh! ¡si yo no amase tanto á Walidé!\"},{\"heading\":false,\"text\":\"Y doña Catalina dijo tambien para sus adentros:\"},{\"heading\":false,\"text\":\"--¡Oh! ¡sino fuera moro este mancebo!\"}]},{\"title\":\"La torre de la cautiva. — capítulo VIII\",\"blocks\":[{\"heading\":false,\"text\":\"Cuando concluyó la comida, doña Catalina se retiró y el baron catalan y el infante granadino quedaron solos.\"},{\"heading\":false,\"text\":\"Despues de hablar de varios asuntos, Abd-el-Rahhaman dijo á Men Roger:\"},{\"heading\":false,\"text\":\"--Tú eres valido del rey tu señor.\"},{\"heading\":false,\"text\":\"--El noble rey don Alonso conoce mi lealtad y la premia concediéndome su confianza, contestó el aragonés con cierta reserva porque no sabia á donde iba á parar el moro.\"},{\"heading\":false,\"text\":\"--¿De modo que si tú pidieras una gracia para mí al rey tu señor, para mí que desde ayer soy su vasallo?...\"},{\"heading\":false,\"text\":\"--¿Y qué gracia es esa?\"},{\"heading\":false,\"text\":\"--Una muger.\"},{\"heading\":false,\"text\":\"--¿Una vasalla del rey?\"},{\"heading\":false,\"text\":\"--Sí; mas que eso aun; una sierva.\"},{\"heading\":false,\"text\":\"--¿Para hacerla tu esposa?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Y quién es?... ¡sierva del rey! ¡no puede ser noble!\"},{\"heading\":false,\"text\":\"--El rey puede concedérmela.\"},{\"heading\":false,\"text\":\"--Te prometo que si concedértela puede, te la concederá.\"},{\"heading\":false,\"text\":\"El infante estrechó la mano del baron catalan, y poco despues se separó de él.\"}]},{\"title\":\"La torre de la cautiva. — capítulo IX\",\"blocks\":[{\"heading\":false,\"text\":\"Al dia siguiente se presentó Abd-el-Rahhaman con toda la ostentacion de su embajada al rey de Aragon.\"},{\"heading\":false,\"text\":\"Le precedian los presentes del rey de Granada.\"},{\"heading\":false,\"text\":\"Entre ellos iba Walidé maravillosamente vestida y cubierta con un velo de gasa que sin cubrir su hermosura la aumentaba, como una ligera nubecilla aumenta la belleza de la luna.\"},{\"heading\":false,\"text\":\"El infante adelantó con ella llevándola asida de la mano y la presentó al rey, levantando su velo con una mano y dando con la otra á Alfonso IV una cédula en pergamino, en que constaba la voluntad del rey de Granada respecto á su sobrina la infanta Walidé al presentarla al rey de Aragon.\"},{\"heading\":false,\"text\":\"Un interprete leyó aquel pergamino.\"},{\"heading\":false,\"text\":\"Al escuchar los caballeros de la córte de Alfonso IV, que estaban presentes, que el rey de Aragon podia dar en matrimonio, con su rico dote aquella muger, aquella niña de tan maravillosa hermosura, todas las miradas se fijaron con codicia en Walidé, especialmente la de Men Roger de Cardona.\"},{\"heading\":false,\"text\":\"Despues Abd-el-Rahhaman notificó al rey el objeto de su embajada.\"},{\"heading\":false,\"text\":\"Las treguas que el rey de Granada pedia, convenian tambien al de Aragon, y fueron concedidas y estipuladas sin dificultad. Cuando el tratado estuvo concluido, Abd-el-Rahhaman dijo á Alonso IV:\"},{\"heading\":false,\"text\":\"--Recordarás noble y poderoso rey que soy tu vasallo.\"},{\"heading\":false,\"text\":\"--Es cierto, dijo el rey de Aragon: hace tres dias me rendiste pleíto homenaje, y yo le recibí: ¿pero por qué me recuerdas eso?\"},{\"heading\":false,\"text\":\"--El rey de Granada al entregarte la infanta Walidé, ha sido con la condicion de que la tengas para tí, ó de que la dés por esposa á uno de tus vasallos. Ahora bien: ¿guardas tú para tí á la infanta?\"},{\"heading\":false,\"text\":\"--Yo no tengo ni tendré mas que una esposa, dijo el rey.\"},{\"heading\":false,\"text\":\"--Pues entonces, señor, replicó el infante, yo te pido por esposa á la infanta Walidé.\"},{\"heading\":false,\"text\":\"Y antes de que el rey pudiese contestar, Men Roger de Cardona adelantó pálido y trémulo hácia el dosel del rey y esclamó:\"},{\"heading\":false,\"text\":\"--Y yo la pido tambien á vuestra señoría, yo que soy rico-hombre de solar, y que he vertido mi sangre en cien batallas matando moros.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡tú eres un perro traidor, sin fé y sin lealtad en sus palabras! dijo el infante á Men Roger.\"},{\"heading\":false,\"text\":\"--Pídeme mi hermana y te la daré, infante, dijo el baron catalan: pero yo pido al rey esa doncella.\"},{\"heading\":false,\"text\":\"--Y me la pides tú tambien infante de Granada, mi vasallo? dijo Alfonso\"}]},{\"title\":\"La torre de la cautiva. — capítulo IV\",\"blocks\":[{\"heading\":false,\"text\":\"--Sí, si señor, esclamó con toda su alma Abd-el-Rahhaman: es mi prima, la amo y ella me ama.\"},{\"heading\":false,\"text\":\"La incertidumbre hacia temblar á Men Roger.\"},{\"heading\":false,\"text\":\"--Yo os la concedo á los dos, dijo el rey: á tí canciller de mis reinos, valiente y leal vasallo mio, á tí infante de Granada mi noble vasallo.\"},{\"heading\":false,\"text\":\"--Pero señor, esclamó Abd-el-Rahhaman, la infanta no puede dividirse en dos: sobra pues uno.\"},{\"heading\":false,\"text\":\"--Dices bien, esclamó todo descompuesto Men Roger: sobra uno de los dos.\"},{\"heading\":false,\"text\":\"--Pues caballeros, dijo el rey, que Dios y San Jaime decidan vuestra contienda: dentro de tres dias en la Tela, en un palenque cerrado, obtendrá por premio de su victoria la infanta de Granada, cualquiera de los dos que venza.\"},{\"heading\":false,\"text\":\"Y el rey despidió á su córte, y Walidé se quedó en el alcázar del rey, y Abd-el-Rahhaman y Men Roger salieron cada cual por su lado, convertidos en los enemigos mas implacables del mundo.\"}]},{\"title\":\"La torre de la cautiva. — capítulo X\",\"blocks\":[{\"heading\":false,\"text\":\"Pasaron los tres dias del plazo.\"},{\"heading\":false,\"text\":\"Fuera de los muros de Tarazona se habia levantado un palenque.\"},{\"heading\":false,\"text\":\"Aquel palenque era el campo cerrado donde las armas debian dirimir la contienda de dos hombres enamorados de una muger.\"},{\"heading\":false,\"text\":\"Aunque el plazo habia sido breve, la fama del duelo habia cundido; gran número de damas y caballeros de las ciudades y villas cercanas á Tarazona habian acudido á presenciar aquel raro litigio entre un cristiano y un moro, que debia sentenciarse por Dios y por San Jaime.\"},{\"heading\":false,\"text\":\"Desde muy temprano los estrados y las barreras estaban llenos de gente: en los primeros se veian hermosas damas, hidalgos, caballeros y mesnaderos, todos engalanados, todos impacientes porque llegase la hora del trance. En las barreras se agolpaba el popular ruidoso, que á cada momento crecia, y los ballesteros del rey guardaban aquellas barreras y aseguraban el palenque.\"},{\"heading\":false,\"text\":\"A un estremo de él estaba un tablado cubierto de hermosos tapices, y sobre aquel tablado dos doseles; el uno mas rico y mas bello que el otro.\"},{\"heading\":false,\"text\":\"Pero es de advertir que en el dosel menos rico estaban recamadas las armas de Aragon, y en el otro mas adornado, mas bello, se veia entre flores una aljaba, un arco y un cendal, armas del amor.\"},{\"heading\":false,\"text\":\"Al pie de estos dos doseles habia una larga gradería cubierta de almohadones rojos y alfombras á los pies, donde debian sentarse, en la primera grada las damas de la reina, en la segunda y tercera los oficiales de la casa del rey.\"},{\"heading\":false,\"text\":\"A la derecha de estos dos doseles, habia un estrado cubierto por paños rojos; aquel estrado debian ocuparle los jueces del campo, los heraldos, los farautes, los persevantes, los escuderos y demás oficiales de armas: á la izquierda se levantaba otro estrado cubierto de paños turquíes con estrellas de plata, donde debian presenciar el duelo los caballeros granadinos que habian venido acompañando en su embajada al infante Abd-el-Rahhaman.\"},{\"heading\":false,\"text\":\"Al otro estremo del palenque habia dos tiendas de las mejores que se habian visto en mucho tiempo, aunque diferentes entre sí: la una era cuadrada, de tafetan verde con galones de oro, y sembrada toda de un blason rojo con cuatro vástagos de oro, armas de la casa de Cardona, lo que demostraba que aquella tienda, en la cual habia guarda de hombres de armas con el mismo blason que se veia en la tienda al pecho, estaba destinada á Men Roger de Cardona, rico-hombre de Aragon y gran privado del rey Alonso IV.\"},{\"heading\":false,\"text\":\"La otra tienda era redonda y resplandecia por su tela de oro y seda recamada de ricas labores arabescas y rodeada de una alfombra de Persia: á su puerta habia, dando la guarda, esclavos negros con marlotas y capellares rojos y arneses dorados, lo que decia claro que aquella era la tienda del infante de Granada Abd-el-Rahhaman.\"},{\"heading\":false,\"text\":\"Y todo esto, los dos nobles doseles, los estrados, las graderías, las tiendas, la arena igualada y estendida dentro de las barreras, la multitud noble y plebeya que llenaba andamios, estrados y graderías: las galas de las damas, las empresas de los caballeros, el aspecto feróz de los ballesteros aragoneses, las brillantes armaduras de los hombres de armas y escuderos de Men Roger, y los ostentosos trages y las armaduras doradas de los esclavos del infante de Granada, ofrecian vivos matices, y brillantes destellos, y cien cambiantes de color y de luz, bajo el sol que salia por un horizonte azul y despejado.\"}]},{\"title\":\"La torre de la cautiva. — capítulo XI\",\"blocks\":[{\"heading\":false,\"text\":\"Apenas habia asomado el sol en el oriente, como si aquella fuese una señal, oyóse fuera del palenque una ruidosa y alta trompetería, á cuyo sonido todos los que esperaban desde el amanecer rompieron en una aclamacion ruidosa.\"},{\"heading\":false,\"text\":\"La corte se acercaba.\"},{\"heading\":false,\"text\":\"Al fin se abrió una poterna y entraron cuatro reyes de armas á caballo, con sus estoques dorados en las manos.\"},{\"heading\":false,\"text\":\"Seguian detrás cuatro heraldos con sus dalmáticas de terciopelo rojo guarnecidas de oro, y con sus mazas al hombro.\"},{\"heading\":false,\"text\":\"Luego una turba de farautes, persevantes y escuderos, á caballo tambien, despues diez y seis trompeteros y otros tantos timbaleros, ginetes en caballos blancos, tocando á un tiempo sus instrumentos:\"},{\"heading\":false,\"text\":\"Luego el Condestable con la espada real, y junto á él el Alférez mayor con el estandarte de Aragon, y todos los oficiales de la casa del rey.\"},{\"heading\":false,\"text\":\"Luego en unas andas muy vistosas, cubiertas de paños de brocado y flores, y deslumbrantemente engalanadas, precedida de muchachas vestidas de blanco, que bailaban acompañándose de sus panderetas, rodeada de doncellas nobles de la reina, en hacancas blancas, llevada cada una de la rienda por un caballero, entró Walidé, confusa y ruborosa, suspendiendo á los hombres y haciendo morir de envidia á las mugeres con su hermosura.\"},{\"heading\":false,\"text\":\"Despues venian á caballo el rey y la reina, él en su corcel de batalla, ella en su blanco palafren; los rico-hombres, los pages, los escuderos, y por último un escuadron de hombres de armas.\"},{\"heading\":false,\"text\":\"Toda esta comitiva atravesó lentamente el palenque; cuando llegaron á la gradería del estrado donde estaban levantados los doseles, el mismo rey en persona descabalgó, fué á las andas en que era llevada la infanta Walidé, que bajó de ellas, y conducida de la mano por el rey, subió la gradería, y fué á ocupar el trono del amor en medio de los murmullos y de las aclamaciones que arrancaban á todos los presentes la hermosura y las resplandecientes galas de que iba cubierta Walidé.\"},{\"heading\":false,\"text\":\"Al pie del dosel se estendieron pages y doncellas, y cuando la infanta de Granada se hubo sentado, el rey bajó de nuevo la gradería, y llevó su esposa al trono, donde se sentó á su lado; los rico-hombres, los mesnaderos, los pages, se estendieron á los pies de la grada, donde estaban sentadas en almohadones las damas de la reina, los jueces del campo y los reyes de armas, y los demás oficiales ocuparon el tablado que les estaba destinado, y la comitiva mora del infante Abd-el-Rahhaman el suyo.\"},{\"heading\":false,\"text\":\"Entonces á una señal del rey don Alonso, el rey de armas _Cataluña_, á caballo, seguido de sus oficiales de armas y precedido de los trompeteros y timbaleros, dió una grida ó pregon en que manifestó á todos los circunstantes:\"},{\"heading\":false,\"text\":\"«Cómo el rey moro de Granada habia enviado al señor rey de Aragon una doncella mora, infanta de su casa, para que la casase con aquel de sus vasallos que mas le pluguiese.\"},{\"heading\":false,\"text\":\"»Otro sí: cómo habiendo venido por embajador del rey de Granada el noble infante, su primo, Abd-el-Rahhaman, el infante habia rendido pleito homenaje y vasallaje al señor rey de Aragon.\"},{\"heading\":false,\"text\":\"»Otro sí: cómo el infante de Granada Abd-el-Rahhaman, y el noble, alto y poderoso señor Men Roger de Cardona, vasallos ambos del señor rey de Aragon, habian pedido á un tiempo á dicho señor rey les concediese por esposa la infanta Walidé, que se hallaba presente en el trono de la hermosura.\"},{\"heading\":false,\"text\":\"»Y finalmente, que el susodicho señor rey de Aragon habia ordenado que para no ofender á ninguno de los dos pretendientes, riñesen á la infanta Walidé, en palenque cerrado de poder á poder, en trance de muerte, si necesario fuese, ante Dios y el bienaventurado apóstol San Jaime.»\"},{\"heading\":false,\"text\":\"El rey de armas Cataluña repitió este pregon en los cuatro ángulos del palenque, y luego leyó los capítulos del combate.\"},{\"heading\":false,\"text\":\"Segun ellos se tendria por vencido:\"},{\"heading\":false,\"text\":\"«El que se saliere del palenque dejando en él á su contrario.\"},{\"heading\":false,\"text\":\"»El que cayere del corcel al suelo.\"},{\"heading\":false,\"text\":\"»El que pidiere suspension del duelo.\"},{\"heading\":false,\"text\":\"»El que usare de malas artes, prohibidas por las leyes de la caballería.\"},{\"heading\":false,\"text\":\"»El que hiriere de mala manera á su contrario.»\"},{\"heading\":false,\"text\":\"Y otros muchos y prolijos capítulos que se leian en tales ocasiones, y que estaban autorizados por la ley y por la costumbre.\"},{\"heading\":false,\"text\":\"Despues de esto se dió otro pregon para que nadie fuese osado, por cosa que sucediere á cualquiera de los dos caballeros, á dar voces ó aviso, ó á hacer seña con la mano, so pena de que al que hablare se le cortaria la lengua, y al que hiciere seña se le cortaria la mano.\"},{\"heading\":false,\"text\":\"A seguida se retiraron el rey de armas y sus oficiales, y los jueces del campo mandaron tocar las trompetas y los timbales, á cuyo son salieron cada cual de su tienda á caballo y armados, el infante Abd-el-Rahhaman y Men Roger de Cardona, rodeados cada cual de sus escuderos y caballeros.\"},{\"heading\":false,\"text\":\"Llevaba el infante de Granada un bonete forrado de oro ricamente labrado, y coronado por una garzota de plumas verdes en señal de esperanza; un arnés tunecino redoblado, forrado de tela de oro; una túnica de brocado de rica labor, y un capellar de grana con flecos y borlas de oro; montaba en un caballo andaluz poderoso, que hacia retemblar la tierra bajo sus cascos; embrazaba una adarga de cuero de Marruecos, perpuntada y bordada de oro y seda, y empuñaba una lanza de ébano, de dos hierros, de Toledo.\"},{\"heading\":false,\"text\":\"Men Roger mostraba las resplandecientes armas, la marlota y la lanza de dos hierros que le habia regalado el infante, y montaba el hermoso caballo de Arabia que habia acompañado á aquel regalo, lo que el infante tomó por insolencia, y el rey y todos los circunstantes por descortesía, porque aquello era lo mismo que decir al infante:\"},{\"heading\":false,\"text\":\"--Te combato con tus propias armas.\"},{\"heading\":false,\"text\":\"El infante tomó por un lado de la liza, y el aragonés por el otro, y al pasar por delante de los reyes y de la infanta Walidé, para saludarlos, se cruzaron, y despues fueron á ponerse uno frente al otro, cada uno á un estremo de la liza.\"},{\"heading\":false,\"text\":\"Entonces bajaron los jueces del campo y les partieron el sol[87], reconocieron sus armas, las dieron por buenas, y les tomaron juramento por su honor de que no llevaban sobre sí amuletos ni hechizos en daño de su contrario, despues de lo cual se retiraron.\"},{\"heading\":false,\"text\":\"Entonces, cuando los caballeros habian quedado en sus puestos, teniendo el freno de cada uno de sus caballos un faraute, el rey hizo una señal con su baston y las trompetas y los timbales rompieron en alto alarido.\"},{\"heading\":false,\"text\":\"A este primer son los caballeros pusieron sus lanzas en los ristres, se adargaron é inclinaron el cuerpo sobre el arzon delantero.\"},{\"heading\":false,\"text\":\"Entonces sonó el toque de arremetida, los farautes soltaron los frenos, y el moro y el catalan partieron el uno contra el otro como dos rayos, y se encontraron con terrible pujanza y estruendo en medio de la liza.\"},{\"heading\":false,\"text\":\"Las dos lanzas se rompieron contra las adargas, sin que ninguno de los dos adversarios se descompusiese.\"},{\"heading\":false,\"text\":\"Pasaron y todos aplaudieron, porque entrambos, el moro y el cristiano en aquella primer carrera, habian sido muy buenos caballeros.\"},{\"heading\":false,\"text\":\"Los escuderos del campo les dieron nuevas lanzas, y volvieron á partir y á encontrarse.\"},{\"heading\":false,\"text\":\"El infante de Granada hizo dar un rodeo al catalan, falseándole la adarga é hiriéndole ligeramente por la parte falsa del arnés, debajo del brazo, y el catalan pasó sin tocar al moro.\"},{\"heading\":false,\"text\":\"La ventaja estaba de parte del infante.\"},{\"heading\":false,\"text\":\"La sangre corria á borbotones de la herida de Men Roger, y los que habian apostado por su triunfo empezaron á dar por perdido su dinero. Pero de repente el caballo del infante, sin que nadie pudiera dar con la causa, se inquietó, empezó á encabritarse, mordió el freno, y escapó de la liza sin que pudiese estorbarlo su ginete.\"},{\"heading\":false,\"text\":\"Todos lo tuvieron á hechicería, tal vez á malas artes del baron catalan; pero como uno de los capítulos del duelo era que el caballero que se saliera de la liza fuese declarado vencido, fúelo el infante, y el rey declaró que Men Roger de Cardona habia ganado buena y lealmente á la infanta, y se la concedió por esposa.\"},{\"heading\":false,\"text\":\"Al saber esto Walidé, palideció intensamente y murmuró:\"},{\"heading\":false,\"text\":\"--No ha vencido al amado de mi alma sino valiéndose de Satanás, que le ha ayudado con malas artes. Pues bien, esposo mio, yo te juro, no solo no ser tuya, sino vengar al infante de la traicion que has obrado con él.\"},{\"heading\":false,\"text\":\"Y todos se engañaron en lo de las hechicerías; la verdad era que al errar el golpe el catalan habia herido sin quererlo en un hijar al caballo del infante, y este irritado por el dolor de la herida habia partido.\"}]},{\"title\":\"La torre de la cautiva. — capítulo XII\",\"blocks\":[{\"heading\":false,\"text\":\"Entre tanto Abd-el-Rahhaman, sin poder contener á su caballo, era llevado por él con la velocidad del huracan á través de los campos.\"},{\"heading\":false,\"text\":\"Nadie supo en Tarazona lo que habia sido del infante.\"},{\"heading\":false,\"text\":\"A los tres dias los caballeros y las gentes y los esclavos que habian acompañado á Abd-el-Rahhaman en su embajada, partieron de Tarazona.\"},{\"heading\":false,\"text\":\"El rey, antes de que partiesen, les preguntó por el infante.\"},{\"heading\":false,\"text\":\"--No sabemos lo que ha sido del bravo Abd-el-Rahhaman, señor, respondió un xeque que habia acompañado al infante.\"},{\"heading\":false,\"text\":\"--Dios le ayude, dijo el rey de Aragon, porque es un buen caballero.\"}]},{\"title\":\"La torre de la cautiva. — capítulo XIII\",\"blocks\":[{\"heading\":false,\"text\":\"Tres dias despues se efectuaron las bodas de Men Roger de Cardona y de la infanta Walidé.\"},{\"heading\":false,\"text\":\"La hermosa jóven se habia presentado alegre y riente, dejadas sus ropas moras por otras magníficas á la usanza de los cristianos, y mas hermosa que nunca.\"},{\"heading\":false,\"text\":\"Men Roger llevaba vendado el brazo izquierdo, y suspendido de una venda de seda que se sujetaba en su cuello.\"},{\"heading\":false,\"text\":\"La infanta, por medio de un intérprete, declaró que voluntariamente se instruiria en la religion cristiana y se bautizaria apenas estuviese instruida, todo por amor á su esposo.\"},{\"heading\":false,\"text\":\"--¡Lo que son las mugeres! esclamó para sí el rey al ver que tan pronto olvidaba sus amores la infanta. ¡Una aragonesa se hubiera dejado matar!\"}]},{\"title\":\"La torre de la cautiva. — capítulo XIV\",\"blocks\":[{\"heading\":false,\"text\":\"Pero al dia siguiente dieron una terrible nueva al rey, por la cual no supo decir si la infanta amaba como toda muger debe amar, ó si amaba demasiado.\"},{\"heading\":false,\"text\":\"En la cámara nupcial, se habia encontrado muerto, cosido á puñaladas, á Men Roger de Cardona.\"},{\"heading\":false,\"text\":\"Sobre su pecho, sujeto por un puñal, se veia un pergamino y en él escrito en árabe lo siguiente:\"},{\"heading\":false,\"text\":\"«Las moras de Granada matamos ó morimos, cuando nos entregan á un hombre á quien no amamos.»\"},{\"heading\":false,\"text\":\"El rey se aterró por la muestra que habia dado de sí aquel amor terrible, y mandó prender á la infanta.\"},{\"heading\":false,\"text\":\"Pero la infanta habia desaparecido.\"},{\"heading\":false,\"text\":\"Y lo que era mas estraño; la hermosa doña Catalina de Cardona, la hermana del difunto, habia desaparecido tambien.\"}]},{\"title\":\"La torre de la cautiva. — capítulo XV\",\"blocks\":[{\"heading\":false,\"text\":\"--¿Y cómo aconteció eso? dijo María, que escuchaba con sumo interés al mago.\"},{\"heading\":false,\"text\":\"--De una manera muy sencilla. El infante cuando pudo dominar á su caballo, comprendió la situacion en que se encontraba: no le cupo duda de que su enemigo habia sido declarado vencedor y de que se le habria entregado la infanta Walidé.\"},{\"heading\":false,\"text\":\"Al pensar esto, la venganza lució como un relámpago sombrío en el alma del infante.\"},{\"heading\":false,\"text\":\"--¡Oh! dijo, tú me has robado mi amante, yo te robaré tu hermana, la hermosa doncella de las crenchas de oro.\"},{\"heading\":false,\"text\":\"Y desde que el infante adoptó esta resolucion, como que le pareció menos dolorosa la pérdida de Walidé.\"},{\"heading\":false,\"text\":\"Pero para ello era necesario ser muy prudente. Se encontraba en medio de los campos y se dirigió sin vacilar á un caserío.\"},{\"heading\":false,\"text\":\"Un labriego le salió al encuentro.\"},{\"heading\":false,\"text\":\"--Tú eres pobre: le dijo el infante, que hablaba bien el español.\"},{\"heading\":false,\"text\":\"--Ni pobre ni rico, le contestó el labriego.\"},{\"heading\":false,\"text\":\"--Pero no te vendria mal que yo te cambiase este hermoso caballo mio por uno de tus rocines.\"},{\"heading\":false,\"text\":\"--No por cierto, señor.\"},{\"heading\":false,\"text\":\"--Ni que yo trocase todas mis galas por un vestido tuyo.\"},{\"heading\":false,\"text\":\"--¡Ah! no por cierto.\"},{\"heading\":false,\"text\":\"--Pues bien, dijo el infante descabalgando, entremos en tu casa.\"},{\"heading\":false,\"text\":\"Allí se efectuó el cambio.\"},{\"heading\":false,\"text\":\"--Escucha, le dijo el infante: cura á este caballo, la herida es ligera, y bien merece por hermoso y bravo que se cuide de él.\"},{\"heading\":false,\"text\":\"--¡Ah! si señor, dijo admirado el labriego.\"},{\"heading\":false,\"text\":\"--Oye aun: mete este caballo en tu establo y guarda estas armas y estas ropas; mañana vendrán á comprártelo todo, y te darán por ello un monte de oro.\"},{\"heading\":false,\"text\":\"--¡Ah! señor.\"},{\"heading\":false,\"text\":\"--Y á persona viviente digas que me has visto.\"},{\"heading\":false,\"text\":\"--Descuidad, señor.\"},{\"heading\":false,\"text\":\"Y el infante montando en el rocin de labor que le habia cambiado el campesino por su magnífico caballo de batalla, y vestido como un rústico, se alejó hácia Tarazona; esperó á que cerrase la noche, y cuando esta hubo estendido su sombra entró en la ciudad, sin que nadie reparase en él á causa de su disfraz y se entró en la casa donde estaban las gentes de su embajada.\"},{\"heading\":false,\"text\":\"--Abdelamar: dijo á uno de sus escuderos favoritos, tú no me has visto: guarda un profundo secreto, y búscame una de esas viejas embaucadoras que dicen que hay en todas las poblaciones de los cristianos.\"},{\"heading\":false,\"text\":\"Abdelamar salió y poco despues volvió con una de esas viejas que viven de ser corredoras del amor, y favorecedoras de doncellas y galanes.\"},{\"heading\":false,\"text\":\"El infante se encerró con ella, y la dijo:\"},{\"heading\":false,\"text\":\"--Amo á una noble dama de esta ciudad y no puedo decirla mi amor: ¿quieres tú, buena muger, encargarte de llevarla un mensage mio?\"},{\"heading\":false,\"text\":\"Y puso en manos de la vieja un bolsillo.\"},{\"heading\":false,\"text\":\"--¿Y cómo se llama esa doncella, hermoso señor?\"},{\"heading\":false,\"text\":\"--Doña Catalina de Cardona, contestó el infante.\"},{\"heading\":false,\"text\":\"--¡Ah, señor! ¡que es mas dura que una peña! ¡tiene amores con un caballero muy noble y muy rico, que se llama Men Jorge de Ariza, y diz que se vá á casar con él; muchos enamorados me han encargado de lo mismo que vos me encargais; pero aunque la he hablado, porque yo tengo un compadre que es escudero de su hermano, no he podido recabar nada de ella: ni aun siquiera que se asome á los miradores para que la vea el enamorado!\"},{\"heading\":false,\"text\":\"--No importa, dijo el infante: id, puesto que podeis hablarla y decidla que un caballero estrangero á quien vió hace cinco dias en el alcázar, y que hace cuatro comió á su mesa con ella y con su hermano, muere por ella; que no ha podido olvidarla un momento y que la ruega le permita la ventura de hablarla á solas.\"},{\"heading\":false,\"text\":\"--Iré, hermoso señor, iré; pero mucho me temo que mi ida sea en vano como tantas otras.\"},{\"heading\":false,\"text\":\"Y la vieja salió, y el infante se quedó entregado á su rabia y á su duda, y despues de haberse dado á conocer á los principales caballeros de su embajada, de haberles recomendado el secreto, y de haberles mandado que se despidiesen del rey de Aragon, como si él no hubiese parecido, se encerró en un aposento y se acostó para no dormir.\"},{\"heading\":false,\"text\":\"Al dia siguiente al medio dia, Abdelamar avisó al infante de que la vieja que habia hablado con él la noche anterior estaba en el zaguan.\"},{\"heading\":false,\"text\":\"El infante mandó que tragese á la vieja y se encerró con ella.\"},{\"heading\":false,\"text\":\"Revosaba la alegría del semblante de aquella muger.\"},{\"heading\":false,\"text\":\"--¡Ah, señor! esclamó: ¡y qué dichoso sois! ¡doña Catalina os ama! ¡una doncella tan noble, y tan hermosa, y tan rica! ¡oh! ¡qué buena ventura os acompaña, señor!\"},{\"heading\":false,\"text\":\"--¡Que me ama! ¡os lo ha dicho ella! esclamó el infante cuyo corazon se habia abrasado al recibir aquella noticia, en un fuego para él desconocido.\"},{\"heading\":false,\"text\":\"--Ella no me lo ha dicho, señor, dijo la vieja: pero yo no necesito que me digan las cosas: cuando la dí vuestro recado me contestó poniéndose muy pálida:--¿Es un caballero jóven, moreno, que tiene los ojos negros?--El mismo, señora mia, la contesté.--¿Y decis que quiere hablarme?--Por veros muere.--Guardó algun tiempo silencio aquella luz de los cielos, y luego poniéndose muy colorada me dijo:--Id y avisadle, que aprovechando el estar mi hermano en el lecho guardando una herida, le veré esta noche por la reja del huerto, á la media noche. Que venga solo y disfrazado.--Y cuando yo oí esto vine deshalada á avisároslo, mi hermoso señor.\"},{\"heading\":false,\"text\":\"Informóse el infante de las señas del lugar de la cita de doña Catalina, dió otro bolsillo á la dueña y la despidió.\"},{\"heading\":false,\"text\":\"Cuando llegó la hora de la cita, que el infante esperó con una impaciencia mortal, salió, atravesó las calles desiertas iluminadas á medias por la luz de la luna, y llegó á un lugar, despues de haber andado mucho, donde en una tapia, por cima de la cual se veian árboles frutales, vió una ancha reja.\"},{\"heading\":false,\"text\":\"Pero aquella reja estaba cerrada.\"},{\"heading\":false,\"text\":\"Acercóse á ella el infante y esperó muriendo de ansiedad.\"},{\"heading\":false,\"text\":\"Pasó algun tiempo y ya temia que la vieja le hubiese engañado, cuando sintió por dentro de la reja unas pisadas de muger, que se acercaron, y detrás de la reja se detuvieron.\"},{\"heading\":false,\"text\":\"Al fin, y pasado un corto espacio rechinaron los postigos, se abrieron y apareció á la luz de la luna una muger vestida de blanco.\"},{\"heading\":false,\"text\":\"Era doña Catalina.\"}]},{\"title\":\"La torre de la cautiva. — capítulo XVI\",\"blocks\":[{\"heading\":false,\"text\":\"--¡Oh! ¡hermoso lucero de mi oscura noche! esclamó el infante asiéndose á la reja y mirando con ansia á la hermosísima doña Catalina.\"},{\"heading\":false,\"text\":\"--Mirad no os equivoqueis caballero, dijo con seriedad la doncella, y no digais esas palabras creyendo que yo soy la hermosa infanta que habeis traido de Granada.\"},{\"heading\":false,\"text\":\"--¡Oh! no: no: se que sois vos: vos la alegría de mi alma, el agua regalada que mi sed desea.\"},{\"heading\":false,\"text\":\"--Si vuestro caballo no se hubiera espantado, hubiérais vencido á mi hermano, hubiera sido vuestra la infanta, y no os hubiérais acordado de mí. Sin duda que me hablais de amor por vengaros de mi hermano, y si yo he consentido de veros ha sido para deciros por mí misma, que os habeis engañado torpemente al elegirme por medio para vuestra venganza.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡partiérame una lanza el corazon antes de que yo escuchára de vuestros hermosos labios tan crueles palabras!\"},{\"heading\":false,\"text\":\"Pronunció el infante de una manera tan doloroso estas palabras, que doña Catalina repuso dulcificando su acento:\"},{\"heading\":false,\"text\":\"--¿Me amais en efecto, no me engañais, puedo fiar en vuestro honor de caballero? ¿y si me amais, cómo es que habeis reñido en duelo la mano de la hermosa infanta granadina?\"},{\"heading\":false,\"text\":\"--Porque creia amarla, señora; pero me engañaba: yo no he amado hasta que os he visto, no: os lo juro por la santa piedra de la Kaba, por el arcángel Gabriel, por Dios, por mi alma. ¡Ah! yo no sabia lo que era morir por una muger hasta ahora; no, no, os lo juro.\"},{\"heading\":false,\"text\":\"--¡Es singular! dijo doña Catalina: yo amaba á un hombre.\"},{\"heading\":false,\"text\":\"Y doña Catalina se detuvo ruborosa.\"},{\"heading\":false,\"text\":\"--Seguid, alegría de mi vida, seguid: dijo con anhelo el infante.\"},{\"heading\":false,\"text\":\"--Sí; continuó doña Catalina con la voz trémula: yo amaba ó creia amar pero... si es cierto lo que decís... me ha sucedido lo mismo que á vos...\"},{\"heading\":false,\"text\":\"Doña Catalina se detuvo de nuevo.\"},{\"heading\":false,\"text\":\"--¡Me amais como yo os amo! esclamó el infante loco de alegría: hemos nacido el uno para el otro, vos cristiana yo moro, y al vernos hemos comprendido lo que es el amor; que no habiamos amado hasta que nos hemos visto.\"},{\"heading\":false,\"text\":\"Doña Catalina guardó silencio.\"},{\"heading\":false,\"text\":\"--Hablad, hablad, dijo el infante: ¿no veis que muero?\"},{\"heading\":false,\"text\":\"Y Abd-el-Rahhaman se asía á la reja para sostenerse y temblaba.\"},{\"heading\":false,\"text\":\"--Yo os amo, dijo doña Catalina con la voz apagada.\"},{\"heading\":false,\"text\":\"El infante reclinó su cabeza en la reja y rompió á llorar porque las lágrimas acompañan tanto á las grandes alegrías como á los grandes dolores.\"},{\"heading\":false,\"text\":\"Y al ver llorar á un hombre tan valiente y tan bravo, las entrañas enamoradas de doña Catalina se abrieron.\"},{\"heading\":false,\"text\":\"--Somos muy desgraciados, dijo.\"},{\"heading\":false,\"text\":\"--¡Desgraciados! esclamó el infante levantando á doña Catalina los ojos nublados por las lágrimas en que reflejaba la luna. ¡Desgraciados! ¿y por qué?\"},{\"heading\":false,\"text\":\"--Vos sois moro; yo soy cristiana.\"},{\"heading\":false,\"text\":\"--Para los que se aman no hay mas Dios que el amor.\"},{\"heading\":false,\"text\":\"--Sois enemigo de mi hermano.\"},{\"heading\":false,\"text\":\"--Le perdono.\"},{\"heading\":false,\"text\":\"--Mi hermano no os perdonará.\"},{\"heading\":false,\"text\":\"--Le diré: amo á vuestra hermana, soy hijo de reyes.\"},{\"heading\":false,\"text\":\"--Mi hermano os pedirá lo que yo no os pido.\"},{\"heading\":false,\"text\":\"-¡Qué!\"},{\"heading\":false,\"text\":\"--Que renegueis de vuestra patria y de vuestro Dios.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡no! ¡nunca!\"},{\"heading\":false,\"text\":\"--Lo sé y por eso os amaré siempre: yo no podria amar á quien por mí se envileciese.\"},{\"heading\":false,\"text\":\"Guardaron entrambos silencio.\"},{\"heading\":false,\"text\":\"--¿Me pediriais vos que renegase de mi Dios? dijo doña Catalina.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡no! respondió el infante.\"},{\"heading\":false,\"text\":\"--Pues bien, amémonos: dijo doña Catalina.\"},{\"heading\":false,\"text\":\"El infante quiso en la locura de su alegría asir una mano que la hermosísima cristiana tenia apoyada en la reja.\"},{\"heading\":false,\"text\":\"Doña Catalina la retiró.\"},{\"heading\":false,\"text\":\"--Amémonos pero desde lejos: guardemos cada uno dentro de nuestra alma, como en un santuario, nuestro amor.\"},{\"heading\":false,\"text\":\"--¡Amarnos desde lejos! ¿y por qué no unirnos?\"},{\"heading\":false,\"text\":\"--No lo quiere Dios: vos sois moro, yo soy cristiana.\"},{\"heading\":false,\"text\":\"--Vos seguireis siendo cristiana y yo seguiré siendo moro.\"},{\"heading\":false,\"text\":\"Pronunció de una manera tan sentida estas palabras el infante, que doña Catalina no contestó.\"},{\"heading\":false,\"text\":\"Permaneció por un momento en silencio dominada por el amor que el infante la inspiraba.\"},{\"heading\":false,\"text\":\"--¿Y cómo, cómo, dijo al fin, no separarnos?\"},{\"heading\":false,\"text\":\"--Seguidme.\"},{\"heading\":false,\"text\":\"--¡Que os siga! ¡qué habeis dicho!\"},{\"heading\":false,\"text\":\"--Necesito veros contínuamente, teneros contínuamente a mi lado para vivir: sin vos los cielos no tienen luz para mi ni el sol resplandores, ni brillan las estrellas, sin vos moriré... ¡ah! ¡vos cuando os negais á seguirme no me amais!\"},{\"heading\":false,\"text\":\"--Amo antes que á vos á mi honra, contestó con voz severa doña Catalina.\"},{\"heading\":false,\"text\":\"Pero su voz temblaba.\"},{\"heading\":false,\"text\":\"--En fin, ¿no sereis mia? ¿no partireis conmigo á mi Granada?\"},{\"heading\":false,\"text\":\"--¡No! esclamó doña Catalina.\"},{\"heading\":false,\"text\":\"Y guardando silencio por un momento, dijo:\"},{\"heading\":false,\"text\":\"--¡A Dios!\"},{\"heading\":false,\"text\":\"--¡A Dios! ¿es decir que me dejais?\"},{\"heading\":false,\"text\":\"--Me aparto de vos.\"},{\"heading\":false,\"text\":\"--¿Y no volveremos á vernos?\"},{\"heading\":false,\"text\":\"--No nos debemos ver: á Dios.\"},{\"heading\":false,\"text\":\"--Esperad, esperad, vida de mi vida, ved que desdeñando mis amores, me matais.\"},{\"heading\":false,\"text\":\"--A Dios, repitió doña Catalina.\"},{\"heading\":false,\"text\":\"Y cerró la reja.\"},{\"heading\":false,\"text\":\"Abd-el-Rahhaman permaneció algunos momentos delante de aquella reja, mudo, y anonadado y luego alzó con resolucion la cabeza, y dijo:\"},{\"heading\":false,\"text\":\"--Por el Dios Altísimo y Unico, hermosa cristiana que has de ser mia.\"}]},{\"title\":\"La torre de la cautiva. — capítulo XVII\",\"blocks\":[{\"heading\":false,\"text\":\"--¿Y lo fué? preguntó María con gran interés al mago.\"},{\"heading\":false,\"text\":\"--Sí; ¿no te he dicho que tú eres hija de doña Catalina de Cardona?\"},{\"heading\":false,\"text\":\"--¡Ah!\"},{\"heading\":false,\"text\":\"--El infante de Granada insistió, suplicó, lloró, y al fin como tu madre estaba enamorada, se rindió.\"},{\"heading\":false,\"text\":\"--¿Huyó con mi padre?\"},{\"heading\":false,\"text\":\"--Sí, con el infante de Granada Abd-el-Rahhaman, la misma noche en que se celebraban las bodas de Men Roger de Cardona, con la infanta Walidé. Asistamos á las bodas, voy á presentártelas. Mira.\"},{\"heading\":false,\"text\":\"Iluminóse el fondo de la habitacion, y María vió una sala rica, colgada de banderas y tapices, y reluciente de luces: al fondo de la sala habia un altar: á un lado del altar habia multitud de damas y al otro gran número de caballeros.\"},{\"heading\":false,\"text\":\"Se abrió una puerta, y entró una dama ya de edad provecta llevando de la mano á otra dama muy jóven, muy hermosa y magníficamente ataviada.\"},{\"heading\":false,\"text\":\"La una dama era la reina de Aragon, la otra la infanta Walidé.\"},{\"heading\":false,\"text\":\"Se abrió otra puerta y apareció otro caballero llevando á otro de la mano.\"},{\"heading\":false,\"text\":\"El que le llevaba, era el rey de Aragon: el que era llevado, Men Roger de Cardona.\"},{\"heading\":false,\"text\":\"Seguian á la reina y á la novia, multitud de damas: al rey y al novio, gran número de caballeros.\"},{\"heading\":false,\"text\":\"Cuando la infanta y Men Roger estuvieron delante del altar, se arrodillaron en unos almohadones.\"},{\"heading\":false,\"text\":\"Luego por una puertecita situada junto al altar, salió el obispo de Tarazona con sus clérigos y su báculo de oro, hizo una plática á los novios y despues les echó la bendicion nupcial.\"},{\"heading\":false,\"text\":\"Y á seguida, en otra cámara mas estensa y mas rica empezó el sarao, que duró hasta muy entrada la noche.\"},{\"heading\":false,\"text\":\"Al fin la reina asió de la mano á la desposada y la condujo á la cámara nupcial donde la dejó sola.\"},{\"heading\":false,\"text\":\"El rey llevó á aquella misma cámara al desposado y se despidió de él á la puerta.\"},{\"heading\":false,\"text\":\"Men Roger y la infanta Walidé quedaron solos.\"},{\"heading\":false,\"text\":\"La infanta no comprendia el dialecto aragonés, pero comprendia sí el lenguaje de los ojos.\"},{\"heading\":false,\"text\":\"Men Roger adelantaba hácia ella pálido de deseo.\"},{\"heading\":false,\"text\":\"La infanta estaba en medio de la estancia, delante del gran lecho nupcial, cruzada de brazos y con la vista inclinada al suelo.\"},{\"heading\":false,\"text\":\"Men Roger se acercó á ella y la abrazó.\"},{\"heading\":false,\"text\":\"Ella no resistió el abrazo.\"},{\"heading\":false,\"text\":\"Pero de repente, cuando Men Roger fué á estampar un beso en la boca de Walidé, dió un grito y cayó de espaldas. Walidé al ser abrazada le habia herido en un costado con un puñal que tenia prevenido, y luego cuando cayó, Walidé, horrible con su venganza, dió de puñaladas al infeliz, sacó de su seno un papel, y con la última puñalada le clavó sobre el pecho de Men Roger.\"},{\"heading\":false,\"text\":\"Aquel papel decia en letras arábigas:\"},{\"heading\":false,\"text\":\"--Las moras de Granada matamos ó morimos cuando nos entregan á un hombre á quien no amamos.\"}]},{\"title\":\"La torre de la cautiva. — capítulo XVIII\",\"blocks\":[{\"heading\":false,\"text\":\"--Pero lo que hizo aquella muger fué infame, dijo María.\"},{\"heading\":false,\"text\":\"--Escucha, escucha, continuó el mago, y verás hasta dónde puede llegar el amor de una mora.\"},{\"heading\":false,\"text\":\"María escuchó de nuevo y el mago continuó:\"},{\"heading\":false,\"text\":\"--Cuando Walidé vió ante sí muerto y ensangrentado á Men Roger, tuvo miedo. Buscó una puerta, y huyó á la ventura, atravesó una galería, llegó á unas escaleras, las bajó, se encontró en un huerto; iluminado por la luna, le recorrió buscando otra salida y encontró un postigo.\"},{\"heading\":false,\"text\":\"Aquel postigo tenia la cerradura rota y corridos los cerrojos.\"},{\"heading\":false,\"text\":\"Estaba abierto.\"},{\"heading\":false,\"text\":\"Walidé se lanzó, á la ventura siempre, por aquel postigo.\"},{\"heading\":false,\"text\":\"Pero de repente se encontró con un hombre.\"},{\"heading\":false,\"text\":\"La luna daba de lleno en su semblante, y Walidé arrojó un grito de alegría.\"},{\"heading\":false,\"text\":\"Porque aquel hombre era el infante Abd-el-Rahhaman, que mientras sus gentes ponian en salvo á doña Catalina, que habia huido, se habia quedado con algunos de los suyos cubriendo por sí mismo la salida, y resuelto á todo.\"},{\"heading\":false,\"text\":\"Del mismo modo que Walidé habia reconocido al infante, este la reconoció á ella.\"},{\"heading\":false,\"text\":\"Una intensa alegría inundó el alma de entrambos.\"},{\"heading\":false,\"text\":\"La de ella, porque se veia al fin salvada por el hombre que vivia en su alma; la de él, porque se vengaba de una doble manera de la falta de fé de Men Roger.\"},{\"heading\":false,\"text\":\"Walidé comprendió que no debia decir á su amante que habia matado á su esposo.\"},{\"heading\":false,\"text\":\"Abd-el-Rahhaman comprendió que debia encubrir el motivo porque se encontraba allí á tales horas.\"},{\"heading\":false,\"text\":\"--¡He huido! ¡he huido, amado mio, aprovechando la confusion de la fiesta de mis bodas! dijo Walidé ¡pero vámonos de aquí, vámonos porque dentro de poco nos perseguirán!\"},{\"heading\":false,\"text\":\"--¡Ah! dijo el infante asiendo de Walidé y llevándola consigo: yo creia que te habian avisado que encontrarias franco el postigo del huerto, y que yo te esperaba fuera para salvarte.\"},{\"heading\":false,\"text\":\"--¡Oh! nadie me ha dicho nada, dijo Walidé siguiendo á buen paso al infante, al que á medida que adelantaba se iban incorporando sus gentes, que estaban apostadas en las calles inmediatas: pero antes de ser de otro hombre lo arrostré todo; sino te hubiera encontrado, sino hubiera podido huir, me hubiera dejado matar antes que faltar á tu fé.\"},{\"heading\":false,\"text\":\"--¡Alma de mi alma! esclamó el infante.\"},{\"heading\":false,\"text\":\"Pero al pronunciar aquella esclamacion mentia: su amor hácia Walidé habia pasado vencido por el amor de doña Catalina de Cardona.\"},{\"heading\":false,\"text\":\"El infante y los suyos iban vestidos á la aragonesa: la infanta para no hacerse reparable, si por ventura los encontraban los guardas de la ciudad, se habia despojado de sus joyas y habia cubierto su rico trage con la capa del infante. Además de esto Abd-el-Rahhaman y los suyos llevaban puestas las manos en las empuñaduras de las espadas.\"},{\"heading\":false,\"text\":\"Muy pronto, franqueada por los guardas pagados una de las puertas de la ciudad, los fugitivos se encontraron en el campo.\"},{\"heading\":false,\"text\":\"El infante llamó á parte Abdelamar.\"},{\"heading\":false,\"text\":\"--Oye, le dijo: sigue tú adelante, muy adelante con la cristiana, de modo que durante el camino hasta Granada no pueda verla la infanta Walidé, con la cual seguiré yo el mismo camino. Que ninguno de los tuyos se quede atrás y pueda decir que contigo vá una muger. Adelante, adelante y á la carrera.\"},{\"heading\":false,\"text\":\"Y montando á caballo, tomó sobre el arzon á Walidé, y partió.\"},{\"heading\":false,\"text\":\"Muy pronto los fugitivos se perdieron entre el silencio y las brumas de la noche.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"En vano el rey de Aragon quiso saber lo que habia sido de la infanta mora, y de la rica-hembra cristiana.\"},{\"heading\":false,\"text\":\"Parecia que el mar se habia tragado á Walidé y á doña Catalina.\"},{\"heading\":false,\"text\":\"Alonso IV, pues, hubo de contentarse con hacer unas ostentosas exequias á su favorito.\"},{\"heading\":false,\"text\":\"Hablóse de ello durante muchos dias en la córte, y al fin todos se olvidaron de Men Roger, de su hermana y de la infanta Walidé.\"},{\"heading\":false,\"text\":\"LETRE dibº y litº Lit de J.J. MARTINEZ, Madrid]\"}]},{\"title\":\"La torre de la cautiva. — capítulo XIX\",\"blocks\":[{\"heading\":false,\"text\":\"Durante una hermosa noche de verano, una sombra blanca, acompañada de otra sombra negra, penetraron por el claro de un vallado, en uno de los bellos y frondosos cármenes del Darro.\"},{\"heading\":false,\"text\":\"Los rayos de la luna, se detenian en la fronda de los árboles frutales, y bajo ellos encontraban un camino oscuro y oculto, la sombra blanca y la sombra negra.\"},{\"heading\":false,\"text\":\"Cuando las dos sombras llegaron á un punto desde el cual se veia una blanca casa en medio de un jardin iluminado enteramente por la luz de la luna, se detuvieron.\"},{\"heading\":false,\"text\":\"--Te habia prometido, dijo la sombra negra á la sombra blanca, traerte al lugar donde tu esposo viene á pasar las noches entre los brazos de una muger.\"},{\"heading\":false,\"text\":\"--Si me lo haces ver seré tuya, dijo con voz irritada y ronca la sombra blanca.\"},{\"heading\":false,\"text\":\"--¿Ves aquella luz que brilla detrás de aquel ajimez?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--Pues allí reposa la cristiana que sacó de Tarazona el infante Abd-el-Rahhaman, la misma noche en que te libró de tu mal destino.\"},{\"heading\":false,\"text\":\"--Para condenarme á otro peor, dijo Walidé que ella era; para condenarme á la desesperacion de verme despreciada por otra muger. ¿Y es esa muger hermosa?\"},{\"heading\":false,\"text\":\"--Como el lucero de la tarde al principiar una noche de primavera.\"},{\"heading\":false,\"text\":\"--Pues bien, Abdelamar, despues de que haya visto á mi esposo salir de esa casa, quiero conocer á esa muger.\"},{\"heading\":false,\"text\":\"--Será necesario gastar algun oro.\"},{\"heading\":false,\"text\":\"--¿Y qué importa? dijo la infanta: ¿no estoy muriendo de celos? ¡la vida que me pidieses la daria por vengarme!\"},{\"heading\":false,\"text\":\"--¡Oh! ¡y cuánto amas al infante! dijo suspirando Abdelamar.\"},{\"heading\":false,\"text\":\"--Te juro que le aborrezco.\"},{\"heading\":false,\"text\":\"--¿Y por qué no huyes de él y le desprecias?\"},{\"heading\":false,\"text\":\"--Quiero vengarme.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡mal haya la hora, dijo Abdelamar, en que el infante me puso á tu lado para servirte! ¡un dia y otro dia he dominado mi amor, que un dia y otro dia ha ido en aumento.\"},{\"heading\":false,\"text\":\"--¿¿Y no te amo yo?\"},{\"heading\":false,\"text\":\"--¡Tú no puedes amar á nadie!... ¡tu alma no es tuya!\"},{\"heading\":false,\"text\":\"--Cuando me hayas vengado te convencerás de que el amor del infante ha pasado para mí.\"},{\"heading\":false,\"text\":\"--¿Y por qué deseas la muerte de esa cristiana y no la del infante? dijo Abdelamar.\"},{\"heading\":false,\"text\":\"--Porque el infante la ama tanto, que preferiria morir á perderla: porque la pérdida de esa muger le desgarrará el corazon, y su recuerdo le quemará eternamente el alma. ¡Morir! ¡qué es morir! ¡un dolor breve! ¡una breve agonía! No: ¡yo quiero que viva! ¡yo quiero que llore! ¡yo quiero que sepa que me he vengado!\"},{\"heading\":false,\"text\":\"Walidé, aquella niña tan inocente, tan cándida, tan pura, tan dulce en otro tiempo, se habia convertido en un demonio por el amor.\"},{\"heading\":false,\"text\":\"Abdelamar, el amigo mas que el siervo de Abd-el-Rahhaman, puesto por él al lado de Walidé, enloquecido por la hermosura de la infanta, habia hecho traicion á su señor: él era el que habia revelado á Walidé los amores del infante con doña Catalina de Cardona, él era quien habia prometido, en cambio de su amor, á Walidé una venganza terrible; él era, en fin, quien la habia llevado á aquel frondoso y apartado cármen, donde ignorada de todos vivia doña Catalina, ardiendo en el amor del infante y de su pequeña hija.\"},{\"heading\":false,\"text\":\"Porque tú María, añadió el mago, acababas de nacer.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡Dios mio! ¡y mi madre! ¡qué fué de mi pobre madre! esclamó María.\"},{\"heading\":false,\"text\":\"--Tu madre cayó ante los celos de Walidé.\"},{\"heading\":false,\"text\":\"--¡Cómo!\"},{\"heading\":false,\"text\":\"--Walidé no pudo tener duda de que el infante amaba á otra: le vió salir de aquella casa acompañado de una muger, que llegó con él hasta cerca del bosquecillo donde estaba oculta con Abdelamar. Oyó hablar á su esposo y á aquella muger un habla estrangera, vió á la luz de la luna la incomparable hermosura de doña Catalina, y se decidió á todo.\"},{\"heading\":false,\"text\":\"Algunos dias despues, cuando el infante trasportado de amor fué una noche á embriagarse entre los brazos de tu madre, la encontró muerta.\"},{\"heading\":false,\"text\":\"--¡Muerta!\"},{\"heading\":false,\"text\":\"--Sí: Abdelamar habia comprado á fuerza de oro á la esclava cocinera de doña Catalina, y la infeliz fué envenenada. Tú misma estuviste á punto de muerte, y fué necesaria toda la ciencia de los mas famosos médicos para salvarte.\"},{\"heading\":false,\"text\":\"--¡Yo!\"},{\"heading\":false,\"text\":\"--Sí: tú te habias alimentado del pecho de tu madre despues de haber sido esta envenenada.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡Dios mio! ¡Dios mio! ¡y quedó sin castigo tanto crímen!\"},{\"heading\":false,\"text\":\"--El crímen continúa en la raza de Walidé.\"},{\"heading\":false,\"text\":\"--¡En la raza de Walidé!\"},{\"heading\":false,\"text\":\"--Sí; en su hija Ketirah.\"},{\"heading\":false,\"text\":\"--¡En su hija! ¿Y dónde está esa muger?\"},{\"heading\":false,\"text\":\"--En los brazos de tu hermano: en la cámara que está bajo esta.\"},{\"heading\":false,\"text\":\"--¡Mi hermano! ¿y quién es mi hermano?\"},{\"heading\":false,\"text\":\"--El generoso caballero que te amparó en Martos: el que recogió á tu amante, á tu Gonzalo, y le hizo conducir á Hins-aleux donde vive, y muere de impaciencia pensando en tí.\"},{\"heading\":false,\"text\":\"--¡Que vive Gonzalo! esclamó trémula de alegría la jóven.\"},{\"heading\":false,\"text\":\"--Sí, vive, y te rescatará y será tu esposo: pero es necesario para ello que tú misma contribuyas á tu libertad.\"},{\"heading\":false,\"text\":\"--¡Dios mio! ¿y cómo? ¡sola, abandonada!\"},{\"heading\":false,\"text\":\"--Oyendo los amores de Masud-Almoharaví.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡nunca! esclamó María.\"},{\"heading\":false,\"text\":\"--Engáñale, domínale...\"},{\"heading\":false,\"text\":\"--Yo no sé mentir.\"},{\"heading\":false,\"text\":\"--Tu mentira servirá para castigar el crímen.\"},{\"heading\":false,\"text\":\"--¿Para castigar el crímen de quién?\"},{\"heading\":false,\"text\":\"--De la muger que está entre los brazos de tu hermano, de la miserable que por ser sultana, se unió en una infame alianza con un hombre miserable y ambicioso y mató al que creia su padre.\"},{\"heading\":false,\"text\":\"--¿Pues quién era el padre de esa muger?\"},{\"heading\":false,\"text\":\"--Esa muger era hija de Walidé y del infante Abd-el-Rahhaman.\"},{\"heading\":false,\"text\":\"--¡Pero entonces, el infanta Ebn-Ismail, esa muger y yo, somos hermanos!\"},{\"heading\":false,\"text\":\"--¡Ya se vé, tienen los moros tantas mugeres! Dos años antes de conocer á Walidé, tuvo Abd-el-Rahhaman un hijo de su primera esposa: ese hijo es el infante Ebn-Ismail: poco despues de su vuelta de Aragon con Walidé y con tu madre, tuvo Abd-el-Rahhaman una hija de Walidé que se llamó Ketirah, y algunos años despues de sus amores con tu madre, que resistió mucho tiempo á sus deseos á pesar de su amor, y que á pesar de su amor pasó tambien algunos años sin darle hijos, naciste tú. De modo que tu hermano Ebn-Ismail, infante de Granada, tiene veintisiete años; Ketirah, veinticinco, y tú quince, y todos sois hermanos hijos de un mismo hombre y de distinta madre cada uno. Zobeya la primera muger de Abd-el-Rahhaman, murió al dar á luz á su hijo: doña Catalina, tu madre, fué envenenada por Walidé, y al envenenarla, Walidé huyó, temiendo verse vendida por Abdelamar su cómplice sino cedia á sus amores: huyó y se refugió en la casa de un pariente suyo, wazir del difunto rey Abul-Walid, que se llamaba Abul-Fath-Nazir-el-Ferih. Ocultóla este, tuvo amores con ella, y viéndola triste, porque era madre, y no tenia consigo á su hija, la robó de los palacios de Abd-el-Rahhaman, la ocultó tanto como habia ocultado á su madre, y Ketirah, cuando asesinó á Abul-Fath-Nazir-el-Ferih, creyó que asesinaba á su padre.\"},{\"heading\":false,\"text\":\"--Pero esa es una sucesion de crímenes horrorosa.\"},{\"heading\":false,\"text\":\"--Ketirah estaba maldita en su madre, que habia muerto al fin devorada por el remordimiento; Ketirah es el demonio bajo la figura de un arcángel: si Ketirah sabe que su amante, su hermoso Ebn-Ismail, te libró del rey Abul-Walid y le mató por tí, en sus celos, en su rabia, te matará.\"},{\"heading\":false,\"text\":\"--¿Y quién puede decir eso á esa muger?\"},{\"heading\":false,\"text\":\"--Masud-Almoharaví, si le desprecias.\"},{\"heading\":false,\"text\":\"--Yo la diré que soy su hermana.\"},{\"heading\":false,\"text\":\"--Aunque te creyese, ¿piensas que se detendria mucho en matar á su hermana, la que no se detuvo en matar al que creia su padre?\"},{\"heading\":false,\"text\":\"--¡Oh! ¡qué muger tan horrible! ¡parricida, incestuosa!...\"},{\"heading\":false,\"text\":\"--Y adúltera.\"},{\"heading\":false,\"text\":\"--¿Y cómo salvarme de ella?\"},{\"heading\":false,\"text\":\"--Primero escribiendo á tu padre.\"},{\"heading\":false,\"text\":\"--¿A mi padre?\"},{\"heading\":false,\"text\":\"--Sí, al walí de Algeciras, el noble, el poderoso, Mohammet-Abd-el-Rahhman.\"},{\"heading\":false,\"text\":\"Y Abu-Jacub, sacó de entre su hopalanda un pergamino enrollado, y un tintero.\"},{\"heading\":false,\"text\":\"--Pero yo no sé escribir.\"},{\"heading\":false,\"text\":\"--No importa: yo escribiré por tí. Al fin, yo llevaré tu mano para que escribas tu nombre.\"},{\"heading\":false,\"text\":\"María estaba fascinada, pendiente de las palabras del mago que desenvolvió el pergamino y se puso á escribir sobre sus rodillas.\"},{\"heading\":false,\"text\":\"Lo que escribia el mago, era la historia de la sorpresa de Illora por los fronteros de Alcaudete acaudillados por Sancho de Arias: el robo por este de la hija de doña Catalina, y la existencia de las alhajas de aquella infortunada en poder del infante Ebn-Ismail.\"},{\"heading\":false,\"text\":\"«Además, señor, decia la carta: solo con verme me conocereis; porque los que conocieron á mi madre, á quien tanto amasteis, dicen que soy una viva imágen suya.»\"},{\"heading\":false,\"text\":\"La carta concluia diciendo al walí de Algeciras el peligro en que se encontraba su hijo penetrando todas las noches en la Alhambra para ver á la sultana Ketirah, y esponiéndose si era visto á ser preso y muerto como asesino del rey Abul-Walid.\"},{\"heading\":false,\"text\":\"--Firma: dijo el mago, cuando hubo leido esta carta á María.\"},{\"heading\":false,\"text\":\"--Pero ya os he dicho que yo no sé escribir.\"},{\"heading\":false,\"text\":\"El mago se apoderó de la mano de la jóven, y la hizo escribir al pie del pergamino y con caracteres arábigos su nombre.\"},{\"heading\":false,\"text\":\"--Tu padre vendrá á salvarte, dijo el mago, y tu hermano te entregará á tu amante.\"},{\"heading\":false,\"text\":\"--¿Pero quién llevará esta carta á mi padre?\"},{\"heading\":false,\"text\":\"--La recibirá dentro de un momento, dijo el mago guardándola entre su ropon talar.\"},{\"heading\":false,\"text\":\"--¡Qué! ¿está mi padre en Granada?\"},{\"heading\":false,\"text\":\"--¿Y qué te importa? Lo que te importa, es entretener con esperanzas á Masud-Almoharaví para dar tiempo á que llegue tu padre.\"},{\"heading\":false,\"text\":\"--No.\"},{\"heading\":false,\"text\":\"--Acuérdate de Gonzalo.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡Dios mio!\"},{\"heading\":false,\"text\":\"--Acuérdate de que tu hermano, amando á la sultana Ketirah, está entregado á Satanás.\"},{\"heading\":false,\"text\":\"--Pues bien; mentiré.\"},{\"heading\":false,\"text\":\"--Pues es preciso que te prepares, porque siento ya los pasos de Masud-Almoharaví que se acerca. A Dios.\"},{\"heading\":false,\"text\":\"Y el mago se levantó, adelantó hácia la puerta, y se desvaneció en su penumbra.\"},{\"heading\":false,\"text\":\"María quedó entregada á una fascinacion incomprensible.\"}]},{\"title\":\"La torre de la cautiva. — capítulo XX\",\"blocks\":[{\"heading\":false,\"text\":\"Apenas el mago habia salido ó desaparecido, cuando se abrió la puerta, y deslumbrante de galas y de brocados, entró Masud-Almoharaví.\"},{\"heading\":false,\"text\":\"María se estremeció; pero recordando las últimas palabras del mago dominó su conmocion.\"},{\"heading\":false,\"text\":\"--Hermosa sultana del amor, dijo Masud-Almoharaví; que Allah te guarde y te bendiga. Héme ante tí, que vengo á ofrecerte mi amor y mi alma.\"},{\"heading\":false,\"text\":\"--¡Tu amor y tu alma! lo mismo me dice el rey, y tú eres su siervo.\"},{\"heading\":false,\"text\":\"--El rey ha muerto, dijo con voz lúgubre el wazir.\"},{\"heading\":false,\"text\":\"--¡Que ha muerto el rey!\"},{\"heading\":false,\"text\":\"--¿No has oido hoy rumor de combate?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿No has visto correr los esclavos negros por los adarves?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Y nada has sospechado?\"},{\"heading\":false,\"text\":\"--He creido por un momento que los cristianos...\"},{\"heading\":false,\"text\":\"--¡Llegar los cristianos á la Alhambra! ¡cuando los cristianos lleguen á sus muros, los montones de cadáveres serán mas altos que las sierras, y la Vega se habrá convertido en un mar de sangre!\"},{\"heading\":false,\"text\":\"--¿Y quién ha matado al rey?\"},{\"heading\":false,\"text\":\"--Yo, dijo Masud-Almoharaví, mintiendo porque no queria decir á María que el infante Ebn-Ismail habia matado por ella al rey.\"},{\"heading\":false,\"text\":\"--¿Y por qué le has matado? dijo María.\"},{\"heading\":false,\"text\":\"--¡Le amabas!\"},{\"heading\":false,\"text\":\"--¡Amarle yo! esclamó con horror María.\"},{\"heading\":false,\"text\":\"--Agradéceme entonces su muerte, porque con ella te he librado de una suerte horrible.\"},{\"heading\":false,\"text\":\"María, recordando siempre las últimas palabras del mago, se dominó.\"},{\"heading\":false,\"text\":\"--Sí, sí, es verdad, dijo: el rey Abul-Walid era un tirano. Anoche... ¡oh que horror!... pero siéntate, siéntate junto á mí.\"},{\"heading\":false,\"text\":\"Masud-Almoharaví se sentó trasportado de deseo junto á María.\"},{\"heading\":false,\"text\":\"Y la jóven, con el magnífico trage musulman que la habia obligado á vestir el rey Abul-Walid, quitándola sus ropas castellanas; con sus ricos cabellos rubios agrupados en anchas y largas trenzas; con su blancura nacarada, con sus resplandecientes ojos negros, y con el encendido color que asomaba á sus megillas, escitado por la situacion difícil en que se encontraba, era el hermosísimo trasunto de un sueño de amores.\"},{\"heading\":false,\"text\":\"Masud-Almoharaví contrastaba enérgicamente con ella: era ya viejo, estaba pálido y demacrado: sus enormes ojos, en que se traslucia la raza africana, tenian un no se qué de terrible, de fiero, de amenazador, aun cuando querian dulcificarse y espresar el amor ó la amistad: sobre su frente habia impreso una profunda arruga el remordimiento, y sus ricas galas hacian contrastar esta fealdad del cuerpo y del alma que aparecian en su semblante.\"},{\"heading\":false,\"text\":\"Masud-Almoharaví no habia amado hasta entonces mas que á su ambicion; pero desde un dia en que acompañando al rey Abul-Walid vió á María, su corazon se abrió al amor, y á un amor tan violento cuanto habia tardado en conocerle su corazon.\"},{\"heading\":false,\"text\":\"En el breve espacio que habia pasado entre el dia en que el rey Abul-Walid habia traido de Martos á la jóven, hasta que el rey murió, Masud-Almoharaví la habia visto algunas veces.\"},{\"heading\":false,\"text\":\"La última la habia hablado de amor.\"},{\"heading\":false,\"text\":\"María le rechazó.\"},{\"heading\":false,\"text\":\"Por esta razon María conocia a Masud-Almoharaví.\"},{\"heading\":false,\"text\":\"Por el anterior desdén de María, el enamorado wazir se maravillaba de que la jóven le sonriese y le hubiese mandado sentar á su lado.\"},{\"heading\":false,\"text\":\"--La muger, como el hombre, dijo para sí Masud, tiene ambicion: cuando el rey la enamoraba, esta rosa de Hiram rae despreció: ahora que el rey ha muerto es distinto: yo puedo ser para ella el prendido de perlas que ciña su cabeza, los perfumes que suavicen su cuerpo, las telas brillantes que realcen su hermosura: yo daré á esta doncella cuanto quiera, y será mia.\"},{\"heading\":false,\"text\":\"Y obedeciendo á este pensamiento, Masud la dijo:\"},{\"heading\":false,\"text\":\"--Esta torre es muy triste, ¿no es verdad?\"},{\"heading\":false,\"text\":\"--No, no señor; dijo María: por el contrario, ¡es tan bella esa quebrada que serpea al pie de la torre! ¡suena tan blandamente el arroyo que por esa quebrada se despeña! ¡cantan con una música tan regalada los ruiseñores que anidan en los laureles del cercano monte, y es esta torre tan hermosa! Desde aquella ventana veo salir el sol, y por esa otra le miro ponerse: la luna parece mas hermosa en medio de este silencio: solo estaría mejor que en esta torre....\"},{\"heading\":false,\"text\":\"--¿En dónde?\"},{\"heading\":false,\"text\":\"--En los lugares donde nací... ó al menos donde me crié, añadió María recordando que habia nacido en uno de los cármenes de Granada.\"},{\"heading\":false,\"text\":\"--¡Oh! ¿vivirias mas alegre en Martos? dijo Masud.\"},{\"heading\":false,\"text\":\"--¡Oh! si señor, allí reposan los restos de mi padre.\"},{\"heading\":false,\"text\":\"Y los ojos de María se llenaron de lágrimas á la memoria del buen Sancho de Arias.\"},{\"heading\":false,\"text\":\"--¿Y no dejaste allí un amante?\"},{\"heading\":false,\"text\":\"María se acordó de las palabras del mago, y replicó sin vacilar:\"},{\"heading\":false,\"text\":\"--¡Ah! no señor; nunca he amado.\"},{\"heading\":false,\"text\":\"--¿No has amado tampoco al rey Abul-Walid?\"},{\"heading\":false,\"text\":\"--¿Si le amara, no lloraria por su muerte?\"},{\"heading\":false,\"text\":\"--El rey era hermoso y jóven aun, y galan y enamorado: dijo Masud-Almoharaví dominando un estremecimiento, porque no podia alejar de sí el recuerdo del instante en que vió ante sí á Ketirah, lavando el puñal con que habia acabado de malar al rey.\"},{\"heading\":false,\"text\":\"--Sí, sí, dijo María; el rey moro era hermoso, y tierno y enamorado: ¿pero no era yo su cautiva? ¿no me habia arrancado de mi patria? yo no puedo amar lejos de mi patria: yo mientras esté en prisiones solo puedo gemir como el ruiseñor, aun cuando esté encerrado en una jaula de oro.\"},{\"heading\":false,\"text\":\"--Pues bien; si solo en tu patria puedes amar, cristiana, yo acaudillaré mis ginetes é iré á apoderarme de Martos, construiré en él para tí un alcázar, y vivirás en él.\"},{\"heading\":false,\"text\":\"--¿Pero Martos no estaba en poder de los moros?\"},{\"heading\":false,\"text\":\"--El rey Abul-Walid dejó en él poca guarda y los fronteros de Alcaudete y de Jaen han vuelto á apoderarse de la villa. Pero no importa, yo llevaré á Martos mi bandera, yo reduciré de nuevo aquella villa, te llevaré á ella y viviré á tu lado.\"},{\"heading\":false,\"text\":\"Presentóse de repente á la vista de María, Martos entregado de nuevo al degüello y al incendio, sus viejos y sus niños muertos, sus doncellas, las que hubiesen quedado del rebato anterior, hechas cautivas, y se estremeció.\"},{\"heading\":false,\"text\":\"--No, no, dijo: creo que lo que me impide amar, no es el estar separada de mi patria, sino el dolor que siento por la muerte de mi padre.\"},{\"heading\":false,\"text\":\"--¡Oh! esclamó Masud: yo seré á un tiempo para tí, tu padre, tu esposo, tu hermano, si tú quisieres: yo haré venir para tí de Oriente los perfumes mas preciados, la púrpura mas encendida, las telas de oro y plata, cuantas preciosidades crió Dios y descubrieron los hombres; yo te daré mi alma, y tú serás mi arcángel y mi hurí, sobre la tierra.\"},{\"heading\":false,\"text\":\"--Espera, dijo María.\"},{\"heading\":false,\"text\":\"--¡Que espere! ¡tú no sabes lo que es esperar cuando se ama! ¡tú no sabes lo que es vivir muriendo en la duda! yo no lo sabia tampoco hasta que te ví, cristiana; pero desde que le he visto, en mis sueños, en mi vela, donde quiera que estoy me persigue tu imágen: por tí vivo y por tí muero: sin tí el mundo me es odioso y triste; contigo la mansion mas lóbrega seria para mí un paraiso.\"},{\"heading\":false,\"text\":\"--¡Espera! repitió María.\"},{\"heading\":false,\"text\":\"--¿Y llegará un dia en que me ames?\"},{\"heading\":false,\"text\":\"--Yo no he amado nunca, dijo María recordando las palabras del mago.\"},{\"heading\":false,\"text\":\"--Pues bien; yo haré tanto, que tú me amarás, dijo Masud.\"},{\"heading\":false,\"text\":\"Y enamorando á María, y contenido por un poder incomprensible, pasó con ella gran parte de la noche hasta que oyó tres palmadas.\"},{\"heading\":false,\"text\":\"Era la seña de la sultana Ketirah, que le avisaba de que ya era hora de volver al alcázar.\"},{\"heading\":false,\"text\":\"Empezaba á alborear.\"},{\"heading\":false,\"text\":\"Masud-Almoharaví salió, prometiendo á María que volveria á la noche siguiente.\"},{\"heading\":false,\"text\":\"Cuando María se quedó sola, se arrodilló y oró á Dios, primero por el alma de su madre, luego por la de Sancho de Arias, y al fin por su Gonzalo y por su amor.\"}]},{\"title\":\"La torre de la cautiva. — capítulo XXI\",\"blocks\":[{\"heading\":false,\"text\":\"Y pasaron algunas noches, y todas ellas la sultana fué á la torre de la Cautiva á recibir entre sus brazos al infante Ebn-Ismail, y Masud á decir sus amores á María.\"},{\"heading\":false,\"text\":\"El infante se mostraba cada vez mas enamorado de Ketirah.\"},{\"heading\":false,\"text\":\"María decia siempre á Masud:\"},{\"heading\":false,\"text\":\"--¡Espera!\"},{\"heading\":false,\"text\":\"Y la sultana moria de amor entre los brazos del infante, y Masud de impaciencia y de amor al lado de María.\"},{\"heading\":false,\"text\":\"Habia llegado aquella noche, en que, como dijimos al principio de esta leyenda, Masud estaba delante de María.\"},{\"heading\":false,\"text\":\"De María, que mas pálida y mas triste que de costumbre, doblegaba la cabeza bajo uno de esos presentimientos oscuros que nos oprimen el corazon, porque no sabemos si vá á acontecernos una gran ventura, ó una gran desgracia.\"},{\"heading\":false,\"text\":\"La sultana Ketirah, por su parte, en la habitacion inferior, estaba consternada.\"},{\"heading\":false,\"text\":\"Al entrar el infante por el ajimez la habia rechazado, y su semblante estaba lívido y sombrío.\"},{\"heading\":false,\"text\":\"Para que nuestros lectores comprendan lo que pasó aquella noche en la torre de la Cautiva, es necesario que retrocedamos á la noche aquella en que el mago tuvo su última entrevista con María.\"}]},{\"title\":\"La torre de la cautiva. — capítulo XXII\",\"blocks\":[{\"heading\":false,\"text\":\"Pero al retroceder vamos á encontrarnos, no en la Alhambra, sino en la cámara de un fuerte castillo; no en Granada, sino en Algeciras.\"},{\"heading\":false,\"text\":\"Es ya tarde.\"},{\"heading\":false,\"text\":\"Los atalayas del muro entonan de tiempo en tiempo un grito de alerta.\"},{\"heading\":false,\"text\":\"La luna se sepulta en el mar, que abrillantado por su reflejo, parece una inmensa llanura de plata.\"},{\"heading\":false,\"text\":\"A lo lejos se vé á Gibraltar saliendo como un negro fantasma sobre las ondas.\"},{\"heading\":false,\"text\":\"En la magnífica cámara de la torre del homenage del alcázar de Algeciras, sobre un divan de pieles de tigre, duerme un hombre.\"},{\"heading\":false,\"text\":\"Es ya casi anciano, pero hermoso todavía.\"},{\"heading\":false,\"text\":\"Su sueño parece agitado, y la cercana luz de la lámpara deja ver la contraccion de su semblante.\"},{\"heading\":false,\"text\":\"Sueña, y su sueño le tortura el alma.\"},{\"heading\":false,\"text\":\"Sueña con su hijo.\"},{\"heading\":false,\"text\":\"Con el infante Ebn-Ismail.\"},{\"heading\":false,\"text\":\"Porque el hombre que duerme es Mohammet-Abd-el-Rahhaman, infante de Granada y walí de Algeciras.\"},{\"heading\":false,\"text\":\"El amante de Walidé y de doña Catalina de Cardona.\"},{\"heading\":false,\"text\":\"El walí sueña con su hijo:\"},{\"heading\":false,\"text\":\"Con su hijo, que despues de haber muerto al rey de Granada, no se sabe dónde para.\"},{\"heading\":false,\"text\":\"Su padre cree verle entre los brazos de una muger.\"},{\"heading\":false,\"text\":\"Y aquella muger le horroriza.\"},{\"heading\":false,\"text\":\"Porque cree conocerla, aunque no la ha visto nunca.\"},{\"heading\":false,\"text\":\"En la hermosa frente de aquella muger le parece leer una maldicion.\"},{\"heading\":false,\"text\":\"Y que su hijo, uniéndose á ella, está maldito.\"},{\"heading\":false,\"text\":\"Y el sueño vá condensándose en la imaginacion del walí, hasta convertirse en una horrible pesadilla.\"},{\"heading\":false,\"text\":\"Parécele que aquella muger devora á su hijo... que mas que una muger es un vampiro, una mala hada.\"},{\"heading\":false,\"text\":\"El walí despierta aterrado y salta del divan.\"},{\"heading\":false,\"text\":\"Y para refrescar la fiebre de su frente con las auras nocturnas, se asoma á un ajimez.\"},{\"heading\":false,\"text\":\"La luna ha acabado de ponerse; el mar no brilla, la noche ha quedado densamente lóbrega.\"},{\"heading\":false,\"text\":\"--Asi está mi alma, dice el walí; sin luz, sin alegría, como esta noche: pero esta noche pasará, y primero la blanca aurora, y despues el esplendente sol brillarán en la mar, y todo estará alegre menos mi corazon.\"},{\"heading\":false,\"text\":\"El walí suspira.\"},{\"heading\":false,\"text\":\"--¡Oh! continúa: ¡desde el dia en que la ví muerta! ¡mi cristiana, mi amor!\"},{\"heading\":false,\"text\":\"El walí inclina la cabeza, doblegado por el pesar.\"},{\"heading\":false,\"text\":\"--¡Han pasado catorce años, y no he podido olvidarla! aun soy jóven y ya mi barba está blanca, y arrugadas mis megillas. Es que el llanto las ha blanqueado, es que al pasar por mis megillas ha dejado en ellas un surco de fuego.\"},{\"heading\":false,\"text\":\"Calló un momento Abd-el-Rahhaman y lanzó su mirada al inmenso espacio, como pretendiendo anegar en él su alma.\"},{\"heading\":false,\"text\":\"--¡Mi hija! ¡mi pobre hija! esclamó; no la hija de aquella muger maldita; de aquella terrible Walidé, que era tan horrible como su madre; sino la hija de mi cristiana, de la luz de mi alma, de mi perdida Catalina: la hija de mis entrañas; mi hermosa María.\"},{\"heading\":false,\"text\":\"Calló de nuevo el infante.\"},{\"heading\":false,\"text\":\"--Su madre, continuó, quiso que se llamase así, que fuese cristiana.... y yo la hice bautizar en secreto por un sacerdote cautivo, á quien dí la libertad... y me robaron á mi pequeña María en aquella funesta sorpresa de Illora. ¡Oh! ¿qué habrá sido de ella?\"},{\"heading\":false,\"text\":\"El walí se retiró de la ventana y se puso á pasear agitado por la cámara. De repente, sus ojos se fijaron en un objeto blanco que habia sobre el diván.\"},{\"heading\":false,\"text\":\"Se acercó y lo tomó: era un pergamino enrollado.\"},{\"heading\":false,\"text\":\"Acercóse á la luz de la lámpara, tomó aquel pergamino, y le leyó.\"},{\"heading\":false,\"text\":\"A medida que le leia, una conmocion profunda le agitaba, y se ponia cada vez mas pálido.\"},{\"heading\":false,\"text\":\"--¡Mi hija! ¡mi hija! esclamó: ¡conque mi hija vive, y está cautiva en la Alhambra de Granada, y mi hijo se aduerme entre los brazos de esa sultana adúltera! ¡Oh! ¡es necesario correr, volar, salvarlos á los dos! ¡Zuleka! ¡Zuleka!\"},{\"heading\":false,\"text\":\"Y á la voz del walí se abrió una puerta y apareció un moro.\"},{\"heading\":false,\"text\":\"--Pronto, Zuleka, mi caballo, el tuyo, cien ginetes: vamos á partir ahora mismo á Granada.\"},{\"heading\":false,\"text\":\"Zuleka desapareció: poco despues, el walí Abd-el-Rahhaman, su katib ó secretario Zuleka, y cien esclavos, cavalgaban á la carrera por un oscuro camino.\"}]},{\"title\":\"La torre de la cautiva. — capítulo XXIII\",\"blocks\":[{\"heading\":false,\"text\":\"Al tercer dia de viage, el walí Abd-el-Rahhman entró en el reino de Granada por la parte de la frontera de Murcia.\"},{\"heading\":false,\"text\":\"Era un caloroso crepúsculo de verano: el sol, que ya habia traspuesto, habia dejado anchos girones rojos en el horizonte: relámpagos producidos por el calor, se mezclaban momentáneamente á aquel color rogizo, tiñendo con él el espacio y las montañas, en cuyos altísimos picos reflejaba el postrer rayo del sol, que ya se habia ocultado para los valles.\"},{\"heading\":false,\"text\":\"Negros nubarrones avanzaban por el mediodía, impulsados por un viento abrasador, y roncos y pesados truenos retumbaban en la inmensidad.\"},{\"heading\":false,\"text\":\"--¡Arriba, arriba, señor! esclamó Zuleka dirigiéndose al walí y tomando con su caballo uno de los repechos de la montaña: la tormenta avanza, y muy pronto la rambla será un torrente. ¡Arriba, arriba, señor!\"},{\"heading\":false,\"text\":\"Abd-el-Rahhman, que iba profundamente distraido, tornó en sí á la voz de Zuleka, vió que el cielo se ponia rojo; vió las negras nubes que avanzaban en escuadron cerrado; escuchó los roncos bramidos del trueno y el sordo silvar del viento, y empezó á trepar por la ladera en que se habia aventurado ya Zuleka.\"},{\"heading\":false,\"text\":\"Los cien ginetes de su resguardo le siguieron.\"},{\"heading\":false,\"text\":\"Trepaban por la tortuosa senda de una asperísima montaña.\"},{\"heading\":false,\"text\":\"Aquella senda que serpeaba por la falda no llegaba hasta la cumbre, sino que iba á parar á la oscura boca de una caverna, situada á la mitad del acceso.\"},{\"heading\":false,\"text\":\"Los caballos trepaban con trabajo.\"},{\"heading\":false,\"text\":\"Los del walí y Zuleka, iban mucho mas delanteros que los de los ginetes moros, no porque fuesen mas fuertes, sino porque los moros refrenaban á sus caballos procurando, aunque simuladamente, que no adelantasen.\"},{\"heading\":false,\"text\":\"Lo que producia esta resistencia á adelantar en los ginetes, era una voz que habia corrido entre ellos en el mismo momento en que entraban en el sendero que conducia á la caverna.\"},{\"heading\":false,\"text\":\"--Vamos á la cueva de las trescientas cincuenta y cuatro malas hadas, habia dicho uno de ellos, que era del pais por el cual marchaban á la sazon.\"},{\"heading\":false,\"text\":\"--¡De las trescientas cincuenta y cuatro malas hadas has dicho! replicó otro moro.\"},{\"heading\":false,\"text\":\"--Sí; de las malditas, que salen de noche de su caverna, roban de sus cunas á los niños, los devoran, y á la noche siguiente van á poner sus corazones roidos envueltos en sus ropas ensangrentadas, en las mismas cunas de donde los robaron, para que los vean sus madres.\"},{\"heading\":false,\"text\":\"--Pero nosotros no somos niños, dijo otro de los soldados.\"},{\"heading\":false,\"text\":\"--Pues peor; mucho peor, dijo el que referia: somos hombres... y no sabeis lo que las malas hadas que moran en la caverna hacen con los hombres.\"},{\"heading\":false,\"text\":\"--No.\"},{\"heading\":false,\"text\":\"--¿Qué hacen?\"},{\"heading\":false,\"text\":\"--Cuando un hombre jóven, ó aun cuando no sea jóven, cuando un hombre fuerte, pasa por este desfiladero, la mayor, esto es, la primera nacida de las hadas, sale á la puerta de la caverna y arroja al viento un puñado de sal diciendo: ¡Hermana mia, la tempestad, ven! y apenas la maldita, la condenada de Dios, dice estas palabras, cuando sucede lo que está sucediendo ahora: el viento zumba, las nubes salen no se sabe de donde, retumba el trueno, arden los relámpagos, el cielo se cubre y se pone negro, y cae en medio de las mas profundas tinieblas un aguacero violento que dura á veces algunas horas: cuando pasa, el torrente producido en la rambla por la lluvia parece sangre.\"},{\"heading\":false,\"text\":\"--¿Y para qué llama la hermana mayor de las hadas malas á su hermana la tempestad?\"},{\"heading\":false,\"text\":\"--Y para que el viagero á quien la tempestad sorprende busque albergue en la caverna.\"},{\"heading\":false,\"text\":\"--¡Ah!\"},{\"heading\":false,\"text\":\"--¿Y qué hacen con el viagero?\"},{\"heading\":false,\"text\":\"--Las hadas que moran en esa caverna, continuó el narrador, son los espíritus de trescientas cincuenta y cuatro doncellas, cuyas madres murieron enamoradas de su padre antes de darlas á luz. Sienten una sed de amor rabiosa, que procuran satisfacer sin conseguirlo, con todos los que pasan este desfiladero, y que ignorando el peligro, se olvidan de llevar consigo, para que los defienda de la impureza de las hadas, el sello cabalístico del poderoso Salomon.\"},{\"heading\":false,\"text\":\"--Pues yo no lo llevo.\"},{\"heading\":false,\"text\":\"--Ni yo.\"},{\"heading\":false,\"text\":\"--Ni yo.\"},{\"heading\":false,\"text\":\"--Y acaso tampoco lo lleve nuestro señor, que ya está cerca de la gruta, dijo el narrador.\"},{\"heading\":false,\"text\":\"--¿Y por qué no le avisamos?\"},{\"heading\":false,\"text\":\"--¿Y quién se atreve? Ya sabeis que nuestro señor castiga á sangre á quien le habla cuando él no le pregunta: ya sabeis que dice que el que se entromete á hablar á su señor cuando él no le habla, comete un atrevimiento, y que siervo que se atreve á su dueño, está muy cerca de ser traidor. Si yo le hablara, á la primera palabra me tenderia á sus pies. ¿Le hablaria alguno de vosotros?\"},{\"heading\":false,\"text\":\"--¡No!\"},{\"heading\":false,\"text\":\"--¡No!\"},{\"heading\":false,\"text\":\"--¡No!\"},{\"heading\":false,\"text\":\"--Pues ni yo tampoco. ¡Que Dios tenga piedad de él!\"},{\"heading\":false,\"text\":\"A pesar de que los ginetes refrenaban un tanto sus caballos, habian llegado cerca de la gruta á una especie de plataforma de la montaña.\"},{\"heading\":false,\"text\":\"Zuleka entonces se volvió y dejó oir en medio de los mugidos de la tempestad la voz, de su corneta, que en dos toques consecutivos, mandó á los ginetes hacer alto y echar pie á tierra.\"},{\"heading\":false,\"text\":\"Los ginetes obedecieron, y teniendo de las bridas á los caballos, se agruparon alrededor del que contaba el cuento.\"},{\"heading\":false,\"text\":\"Abd-el-Rahhaman y Zuleka, seguian ya á pie y llevando los caballos del diestro, porque la senda se hacia muy áspera hácia la gruta.\"},{\"heading\":false,\"text\":\"--¿Y qué? ¿qué sucede á los que entran en esa caverna? dijeron algunos.\"},{\"heading\":false,\"text\":\"--¡Oid! ¡oid! ya la tormenta se echa encima y empieza á llover: amparémonos de la saliente de esta roca, y entretengamos la espera con un cuento maravilloso.\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¡Cuento!\"},{\"heading\":false,\"text\":\"--¿Es la historia del encanto de la caverna?\"},{\"heading\":false,\"text\":\"--Si por cierto, la historia de un rey mago, que fué el padre de las trescientas cincuenta y cuatro hadas.\"},{\"heading\":false,\"text\":\"Y los ginetes fueron á ponerse bajo el resalto gigantesco de una roca, y se agruparon en torno del cuentista.\"},{\"heading\":false,\"text\":\"La tempestad descargó entonces en todo su furor, y empezó á oirse el mugido de las aguas que se despeñaban por la rambla y que crecian á cada momento mezclando su bramido cada vez mas ronco y poderoso, al pujante bramido de lo tempestad.\"}]},{\"title\":\"La torre de la cautiva. — capítulo XXIV\",\"blocks\":[{\"heading\":false,\"text\":\"--Habeis de saber, amigos, dijo el cuentista, con la importancia y el placer del que tiene pendiente de su palabra la atencion de muchos hombres, que habia en esta tierra, no se sabe cuando, pero sí que hace mucho tiempo, un rey muy poderoso, que habia pasado los años de su vida estudiando la astrología, y la ciencia maldita de lo oculto: era pues, muy sabio, y muy poderoso, pero no era feliz: no tenia que necesitaba, y para procurárselo, conjuró á Satanás.\"},{\"heading\":false,\"text\":\"--¿Y Satanás obedeció?\"},{\"heading\":false,\"text\":\"--Sí, porque el rey habia estudiado los siete libros mágicos de Salomon, y se habia hecho mago.\"},{\"heading\":false,\"text\":\"--¿Y que pidió el rey mago á Satanás?\"},{\"heading\":false,\"text\":\"--¡La felicidad!\"},{\"heading\":false,\"text\":\"--¿Y se la dió Satanás?\"},{\"heading\":false,\"text\":\"--Le dió lo que él creia la felicidad, esto es, riquezas, y vasallos; poder invencible contra sus enemigos, y una juventud y una hermosura inauditas, durante trescientos cincuenta y cinco años.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡y qué rey tan feliz! dijo un ginete de barba blanca: ¡un hombre que durante trescientos cincuenta y cinco años, seria jóven, rico, invencible y hermoso, y no sirviendo á nadie.\"},{\"heading\":false,\"text\":\"--Te engañas, dijo el cuentista: el rey mago era esclavo de sí mismo.\"},{\"heading\":false,\"text\":\"--¡Ah!\"},{\"heading\":false,\"text\":\"--¡Oh!\"},{\"heading\":false,\"text\":\"--¿Y cómo?\"},{\"heading\":false,\"text\":\"--Ya vereis: el rey mago estaba cansado de todo; porque hacia mucho tiempo, que las aves del aire, los animales de la tierra, los peces del mar, y los frutos de todo el mundo le servian por su ciencia de manjares, y no encontraba nada que no le repugnase y que pudiese escitar su apetito.\"},{\"heading\":false,\"text\":\"--¡Ah!\"},{\"heading\":false,\"text\":\"--Además de esto, el mago era soberbio, y queria tener un palacio como no le hubiera en el mundo, y en aquel palacio un harém en que hubiera las mugeres mas maravillosamente hermosas de la tierra. Era además cruel y se gozaba con la sangre, con la muerte y el estrago.\"},{\"heading\":false,\"text\":\"--¡Ah, maldito!\"},{\"heading\":false,\"text\":\"--En el mismo punto en que pactó con Satanás, que durante trescientos cincuenta y cinco años le tendria por esclavo, con la condicion de que pasados los trescientos cincuenta y cinco años, él seria esclavo suyo por toda una eternidad...\"},{\"heading\":false,\"text\":\"--¿Tanto valía el alma del rey mago?\"},{\"heading\":false,\"text\":\"--El diablo habia tratado con él de mala fé, porque si el diablo fuese una vez honrado, dejaria de ser el diablo. Ya vereis. En el mismo punto en que estuvo hecho aquel trato, que se hizo por cierto en aquella gruta, el rey mago, dijo á Satanás:--Quiero tener un alcázar como no lo haya tenido el poderoso Salomon.\"},{\"heading\":false,\"text\":\"Apenas dijo el mago estas palabras, cuando sobre la cumbre de esta montaña, apareció un alcázar... yo no puedo deciros como era el alcázar, porque no hay palabras en lo humano para encarecerle. Pero era mas bello, mucho mas bello que la Alhambra, y eso que dicen que la hicieron las buenas hadas del rey Nazar.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡oh! esclamaron todos los ginetes en coro.\"},{\"heading\":false,\"text\":\"--Y eso que Satanás habia construido el alcázar en un momento.\"},{\"heading\":false,\"text\":\"Repitióse el murmullo de asombro.\"},{\"heading\":false,\"text\":\"--Cuando el rey mago vió aquel palacio tan maravilloso, dijo al diablo:--Satanás, tengo hambre, los frutos y los animales de la tierra me enojan: dame un fruto que no le haya ni en la tierra, ni en el cielo, ni en el infierno.\"},{\"heading\":false,\"text\":\"Y Satanás desapareció por un momento, y volvió á aparecer con una hermosa manzana en la mano. Habia ido por ella al jardin de Hiram y la habia cogido del árbol de la vida.\"},{\"heading\":false,\"text\":\"--¡Ah!\"},{\"heading\":false,\"text\":\"--Cuando el rey mago comió la manzana, su corazon ardió, sus ojos se pusieron rojos, le devoró una sed terrible, y gritó:--Satanás, quiero recrear mis ojos en ver el esterminio; quiero ver los cadáveres hechos pedazos sobre el campo de batalla, y devorados por los buitres; tengo sed, y quiero aplacarla con sangre humana.--En el mismo punto, Satanás tomó al rey sobre sus alas de murciélago, y en un solo instante le condujo á un campo donde se embestian los egércitos de dos reyes enemigos: y cuando el horno de la pelea estaba encendido y bravo, Satanás se mezcló con el rey entre los combatientes, y el rey veia morir, las unas á las manos de las otras, criaturas de Dios: y se recreaba en cada herida, se alegraba con cada muerte, bebia la sangre de los moribundos, y luego, cuando se hubo acabado la batalla y traspuso el sol, vió á los buitres venir en bandadas, caer sobre el campo de batalla y devorar los cadáveres desnudos. Y entonces esclamó:--¡Satanás! la noche empieza; tengo sueño; la sangre me ha embriagado; quiero dormir mi embriaguez entre los brazos de la doncella mas hermosa del mundo; llévame donde yo repose y temple mi sed de amor.--Y como Satanás era su esclavo, le tomó sobro sus hombros y le llevó á una cabaña.\"},{\"heading\":false,\"text\":\"--¡A una cabaña!\"},{\"heading\":false,\"text\":\"--Las mugeres mas hermosas, son las que respiran el aire saludable de las montañas, las que se egercitan apacentando sus rebaños, las que templan su sed con el agua pura de los manantiales, y satisfacen su hambre con los sazonados frutos de los árboles; las que nunca se han pintado con alheña las uñas y los cabellos, las que nunca han oprimido con el ceñidor su cintura, ni con el borceguí su pie; las que no han olido otro perfume, que el de los romeros y el que los vientecillos arrancan de las flores; las que para enamorar no conocen el artificio, ni mienten ni tienen celos, ni las devora la envidia: ¡oh! ¡sí! las montañesas de mi tierra son las mugeres mas hermosas del mundo.--Pues, como decia, el diablo llevó á la cabaña de una de estas vírgenes al mago, y como el mago era hermoso y parecia jóven, y le ayudaba Satanás, la pobre muchacha, aunque estaba enamorada de otro, se enamoró de él y le sonrió amorosa, y el mago satisfizo su sed de amor, y durmió entre sus brazos su embriaguez de sangre; y cuando despertó, dijo á Satanás:--Esta muchacha me enoja; llévame á mi alcázar.--Y el diablo le llevó, y este fué el primer dia del pacto del rey mago con Satanás.--Y cuando la muchacha despertó se encontró sola, y buscó enamorada al rey y no le encontró, y empezó á empalidecer y á enflaquecer, y murió á los pocos dias y con ella murió antes de nacer, y teniendo ya un alma impura, la hija que la desdichada habia concebido en sus breves amores con el rey mago.\"},{\"heading\":false,\"text\":\"Y el segundo dia de su pacto con el diablo, el rey comió otra manzana del árbol de la vida, y vió otra batalla, y bebió sangre, y tuvo otra doncella, y la doncella murió, y con ella una hija no nacida.\"},{\"heading\":false,\"text\":\"Y durante el primer año de su pacto con el diablo, comió el rey mago trescientas cincuenta y cuatro manzanas del árbol de la vida, y vió otras tantas batallas, y se embriagó otras tantas veces con sangre humana, y el diablo le dió otras tantas doncellas, que murieron abandonadas, y con ellas, antes de ver la luz, sus hijas. Y el dia en que se cumplia el año, todas estas hijas no nacidas vinieron al palacio del rey mago convertidas en unas hermosísimas hadas, engalanadas con vestiduras tales, tan sútiles, tan trasparentes y tan ricas, como no hay artífice que las hiciese iguales, y adornadas con oro, perlas y diamantes, como no se encuentran ni en los senos de la tierra, ni en las entrañas de las rocas, ni en los abismos del mar. Y el mago vió alrededor de sí, trescientas cincuenta y cuatro hijas, una por cada año de la vida que le habia concedido Satanás, y todas tan hermosas, tan resplandecientes, tan magníficas como el rey mago no habia podido soñar en sus mas ardientes sueños de deseo. Sucedió que cuando el mago vió delante de sí á su primera hija se enamoró perdidamente de ella, y su hija de él; pero por mas que hacian por unirse, los separaba siempre un muro invisible, impenetrable, que les impedia tocarse: y el mago y la hada gemian y giraban alrededor el uno del otro, siempre separados por un muro tan delgado como un cabello y tan claro como el diamante, y como el diamante tan duro. Y cuando el mago vió su segunda hija mas hermosa que la primera, se obstinó más, y así sucesivamente hasta que, rodeado de las trescientas cincuenta y cuatro, y rodeándose todas ellas, y siempre sin poder tocarse, llamó desesperado á Satanás.--Yo muero, dijo; dame la mas hermosa de mis hijas.--Por cada hija tuya, un año de tu vida, dijo Satanás.--Te lo doy, dijo el mago.--Y Satanás rompió el muro de diamante que le separaba de la primera hija, y el uno y el otro se estrecharon en sus brazos.\"},{\"heading\":false,\"text\":\"--¡Ah, malditos, malditos!\"},{\"heading\":false,\"text\":\"Pero apenas tocó el mago á su primera hija, sintió cansancio de ella y le pareció mas hermosa la segunda.--Dáme mi segunda hija, Satanás, dijo el mago.--¿Me darás por ella otro año de tu vida?--Sí, contestó el mago.--Ten, pues, dijo Satanás, y le entregó su segunda hija. Pero apenas la tocó el mago, la aborreció. Pidió una tercera á Satanás, y Satanás le pidió otro año de su vida.--Y así, pidiendo una á una sus hijas á Satanás, y dándole por cada una de ellas un año de su vida, y aborreciendo á sus hijas apenas las tocaba, desde el anochecer de una noche de horror, hasta el amanecer de un dia de tormenta, el diablo dió al mago sus trescientas cincuenta y cuatro hijas, y el mago gastó sus trescientos cincuenta y cuatro años sin haber apagado su sed de amor, sin haber cometido un solo incesto. Dios no lo quiso permitir, y el diablo se alegró de ello, porque en un año que llevaba de servir al rey mago, habia conocido que su esclavitud era insoportable. Cuando el mago rechazaba á su última hija, cantó el gallo en la alborada.--Eres mi esclavo, dijo Satanás al mago; tus vicios han sido mas poderosos que tu ciencia, y has gastado en una noche de deseo los trescientos cincuenta y cuatro años que yo te dí por tu alma.--Y asiéndose del rey mago, le arrebató consigo á los abismos, y con el rey mago se hundió su negro palacio, y solo quedó esa caverna, donde sedientas de amor, penan las trescientas cincuenta y cuatro[88] hadas malas, sus hijas. Y por su sed de amor, cuando un hombre que no lleva sobre si un amuleto entra en la rambla, las hadas malas llaman á la tempestad, y el viagero, huyendo de ella, trepa á la gruta, y cuando está dentro las hadas se apoderan de él y todas le quieren para sí, y lo despedazan pretendiendo arrebatárselo las unas á las otras, y en el momento en que el desdichado muere, mordido, arañado, sofocado, estrangulado, despedazado, cesa la tempestad y se vé el torrente que se precipita por la rambla, rojo como sangre humana.\"},{\"heading\":false,\"text\":\"¡Y nuestro señor ha entrado en esa maldita caverna!\"},{\"heading\":false,\"text\":\"--Dios tenga piedad de él si no lleva consigo un amuleto.\"},{\"heading\":false,\"text\":\"--¿Y quién te ha contado ese cuento?\"},{\"heading\":false,\"text\":\"--¡Qué! ¿dudareis de él?\"},{\"heading\":false,\"text\":\"--No dudo; ¿pero cómo se sabe lo que pasa en esa caverna, si todos los que entran en ella mueren?\"},{\"heading\":false,\"text\":\"--Yo no sé quien lo habrá contado; algun varon justo y temeroso de Dios.\"},{\"heading\":false,\"text\":\"--Además de eso, ¿crees tú que sea falso un cuento que tiene tan provechosa enseñanza?\"},{\"heading\":false,\"text\":\"--¿Y qué enseñanza es esa?\"},{\"heading\":false,\"text\":\"--Que al hombre le matan sus vicios, le hacen odioso á Dios, y le condenan.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡ah!\"},{\"heading\":false,\"text\":\"--Pero ved que la tempestad pasa y sale la luna.\"},{\"heading\":false,\"text\":\"--Es verdad; pero nuestro señor no sale de la caverna.\"},{\"heading\":false,\"text\":\"--Sí; pero su katib Zuleka, está sentado tranquilamente á su entrada.\"},{\"heading\":false,\"text\":\"--¡No importa! ¡no importa! ¿qué habrá sucedido á nuestro señor?\"}]},{\"title\":\"La torre de la cautiva. — capítulo XXV\",\"blocks\":[{\"heading\":false,\"text\":\"¿Qué habia acontecido, pues, dentro de la caverna de las trescientas cincuenta y cuatro malas hadas al walí Abd-el-Rahhaman?\"},{\"heading\":false,\"text\":\"Apenas entró en ella, sintió un vértigo inesplicable y se sentó junto á una piedra.\"},{\"heading\":false,\"text\":\"Poco despues reclinó su cabeza en sus rodillas y se durmió.\"},{\"heading\":false,\"text\":\"De repente sintió que le movian suavemente, y oyó una voz que le dijo:\"},{\"heading\":false,\"text\":\"--¡Despierta! infante Abd-el-Rahhaman.\"},{\"heading\":false,\"text\":\"El walí abrió los ojos, y no se encontró ya en la gruta, si no en un alcázar maravilloso.\"},{\"heading\":false,\"text\":\"Pero aquel alcázar tenia algo de terrible.\"},{\"heading\":false,\"text\":\"Parecia que sus cúpulas estaban perdidas en una niebla vaga, infinita, á través de la cual penetraba una claridad fria.\"},{\"heading\":false,\"text\":\"Los arcos, las galerías, las columnas, estaban abiertos á un espacio nebuloso tambien, infinito, frio, apenador.\"},{\"heading\":false,\"text\":\"El alcázar parecia estar suspendido en el abismo, y flotar sobre él.\"},{\"heading\":false,\"text\":\"Entre los arcos, entre las galerías, entre las columnas, pasaban y cruzaban, y volvian á pasar y á cruzar, confundiéndose, mezclándose, sombras indecisas, que como las nubes, se estendian y cambiaban de forma, dejándose ver á veces cerca y determinadas como mugeres hermosas y ricamente engalanadas, que fijaban por un momento sus ojos negros y relucientes, en Abd-el-Rahhaman, y luego se alejaban como empujadas por el viento, y se confundian en la niebla volviendo á dejarse ver en una nueva oleada.\"},{\"heading\":false,\"text\":\"--¡Oh, poderoso Allah! dijo el walí; ¿qué doncellas son estas, que así vienen y ván, y que así me miran y que no se acercan á mí? Todas son resplandecientes como gotas de rocío á los rayos del sol, y todas hermosas, y todas anhelantes y tristes. ¿Por qué turban mi razon esas mugeres, y me embriagan y avivan recuerdos de mi juventud ya acibarados por los años y por las desgracias?\"},{\"heading\":false,\"text\":\"--¡Abd-el-Rahhaman! dijo una voz que parecia salir de la inmensidad, sonora, vibrante, que puso espanto en el corazon del walí: ¿qué has hecho de tus hijos?\"},{\"heading\":false,\"text\":\"--¡Mis hijos! esclamó Abd-el-Rahhaman: ¡mis hijos, genio invisible, yo no tengo mas que un hijo!\"},{\"heading\":false,\"text\":\"--A más del asesino del rey Abul-Walid, has tenido dos hijas: ¿qué has hecho de ellas?\"},{\"heading\":false,\"text\":\"--La una me la robó su madre; la otra me la robaron los cristianos, contestó el walí.\"},{\"heading\":false,\"text\":\"--Dos de tus hijos están malditos, esclamó la voz.\"},{\"heading\":false,\"text\":\"--¡Ah, perdon para ellos! repuso el walí.\"},{\"heading\":false,\"text\":\"--La última hija tuya, tu María...\"},{\"heading\":false,\"text\":\"--¡Ah! ¿qué es de María? esclamó el walí.\"},{\"heading\":false,\"text\":\"--¡María! corre á la Alhambra, walí, corre á la Alhambra, y salva á María porque la impureza y el crimen la acechan.\"},{\"heading\":false,\"text\":\"--El walí guardó silencio aterrado.\"},{\"heading\":false,\"text\":\"--¿Te acuerdas de tu sobrina Aleidah, la sultana de Granada?\"},{\"heading\":false,\"text\":\"--¡Ah, infeliz!\"},{\"heading\":false,\"text\":\"--Fué envenenada por una muger terrible.\"},{\"heading\":false,\"text\":\"--¿Y quién es esa muger; vive, puedo tomar venganza de ella?\"},{\"heading\":false,\"text\":\"--Esa muger ocupó el tálamo vacío de Abul-Walid; esa muger fué sultana; esa muger envenenó al que creia su padre...\"},{\"heading\":false,\"text\":\"--¿Pues quién fué su padre?\"},{\"heading\":false,\"text\":\"--Su nombre está envuelto en un misterio para tí, porque es necesario que se cumpla una venganza terrible.\"},{\"heading\":false,\"text\":\"--¿Y sabré el nombre del padre de esa muger?\"},{\"heading\":false,\"text\":\"--Cuando la hayas esterminado.\"},{\"heading\":false,\"text\":\"--¡Matadora de Aleidah! ¡envenenadora del que creia su padre!\"},{\"heading\":false,\"text\":\"--Y la condenacion del alma de tu hijo.\"},{\"heading\":false,\"text\":\"--¡De mi hijo!\"},{\"heading\":false,\"text\":\"--Sí; de tu hijo que enloquece entre los brazos de la adúltera: de tu hijo que amaba á su prima la sultana Aleidah, y que al estremecerse de amor entre los brazos de la sultana que mató á su padre y á su esposo, ignora que mató tambien á la anterior sultana.\"},{\"heading\":false,\"text\":\"--¡Invisible genio! ¿me haces esta revelacion para que castigue tantos crímenes?\"},{\"heading\":false,\"text\":\"--Sí; toma.\"},{\"heading\":false,\"text\":\"Un pergamino enrollado cayó á los pies del infante Abd-el-Rahhaman.\"},{\"heading\":false,\"text\":\"--¿Qué es esto, poderoso genio? dijo el infante.\"},{\"heading\":false,\"text\":\"--Esa es la historia de los crímenes de la sultana Ketirah, y de su cómplice el wacir Masud-Almoharaví: dá esta historia á tu hijo.\"},{\"heading\":false,\"text\":\"--¿Y dónde encontraré á mi hijo, poderoso genio?\"},{\"heading\":false,\"text\":\"--Mañana, cuando la noche sobrevenga, en el sendero por donde marches, encontrarás sentado y de frente á tí, un perro blanco de montería. Cuando te llegues á él, el perro se levantará y correrá delante de tí; sigue á ese perro y él te llevará á el lugar de donde todas las noches sale tu hijo para perder su alma entre los brazos de Ketirah.\"},{\"heading\":false,\"text\":\"--¡Poderoso genio!... dijo el walí.\"},{\"heading\":false,\"text\":\"--Yo no soy genio... soy un condenado que vaga sobre la tierra, hasta el dia en que, siendo el vengador de los crímenes de los hombres, alcance mi perdon.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿tú has sido hombre?\"},{\"heading\":false,\"text\":\"--Sí; yo he sido el rey mago, Abu-Jacub-el-Alime, y esas doncellas que ves aparecer y desaparecer entre la niebla y que no te despedazan porque te protejo yo, son mis trescientas cincuenta y cuatro hijas malditas: una por cada dia de pecado.\"},{\"heading\":false,\"text\":\"Y apenas la voz del mago Abu-Jacub, pronunció estas palabras, cuando el alcázar fantástico y sus hadas malditas se desvanecieron en una niebla impura, resonaron gritos horribles, como de mugeres desesperadas que se alejaban, y se perdieron al fin en el silencio, y el rey se puso de pie, y se encontró en medio de la caverna, por cuya abertura penetraba la luz de la luna.\"},{\"heading\":false,\"text\":\"--¡Oh! ha sido un sueño, un horrible sueño: yo habia oido contar muchas veces el cuento de las hadas malditas hijas del mago, pero no sabia que fuese esta la caverna; además, llevo conmigo un anillo mágico que me protege, pero este pergamino, añadió reparando en uno enrollado que tenia entre los pliegues de su faja... ¡Oh! ¡este pergamino escrito!... ¿con que esto ha sido mas que un sueño? ¡Oh, poderoso Allah! ¡que se cumpla lo que está escrito! ¡si encuentro un perro blanco de montería, le seguiré, y si encuentro á mi hijo le daré este pergamino! ¡Oh, poderoso Señor! ¡que se cumpla tu voluntad!\"},{\"heading\":false,\"text\":\"Y saliendo de la gruta, despertó á su secretario Zuleka, que dormia á su entrada.\"},{\"heading\":false,\"text\":\"--¡A caballo! dijo el infante, y prosigamos nuestro camino.\"},{\"heading\":false,\"text\":\"Zuleka se llevó la corneta á los labios y tocó á cabalgar: los cien ginetes salieron de debajo del resalte de la roca, donde se habian acogido durante la tempestad, y poco despues, el infante, Zuleka y los esclavos, cabalgaban á la orilla del torrente rojo que la tormenta habia formado en la rambla.\"}]},{\"title\":\"La torre de la cautiva. — capítulo XXVI\",\"blocks\":[{\"heading\":false,\"text\":\"Era la noche del siguiente dia: la luna brillaba en medio del firmamento.\"},{\"heading\":false,\"text\":\"El walí de Algeciras habia soltado las riendas sobre el cuello de su caballo, habia inclinado la cabeza y se habia dormido.\"},{\"heading\":false,\"text\":\"A Zuleka le habia acontecido otro tanto.\"},{\"heading\":false,\"text\":\"Otro tanto á los cien ginetes.\"},{\"heading\":false,\"text\":\"Los caballos seguian uno tras otro por un sendero de la montaña.\"},{\"heading\":false,\"text\":\"De repente el caballo del infante, que iba el delantero, se paró, erguió el cuello, olfateó el aire, rehiló las orejas y lanzó un largo relincho.\"},{\"heading\":false,\"text\":\"Luego partió á la carrera, raudo y pujante como la tormenta, perdiéndose por entre las revueltas de la montaña con la misma valentía con que hubiera corrido por el llano.\"},{\"heading\":false,\"text\":\"Muy pronto quedaron atrás Zuleka y los ginetes, y las rocas y las colinas parecian huir deslizándose junto al caballo.\"},{\"heading\":false,\"text\":\"Y cuando el caballo encontraba una roca en medio del sendero, la salvaba de un salto, y de la misma manera salvaba las cortaduras que se le oponian.\"},{\"heading\":false,\"text\":\"Y el infante, á pesar de la rápida carrera de su caballo, seguia durmiendo.\"},{\"heading\":false,\"text\":\"Súbito se oyó entre las quebraduras un ladrido potente, ronco, prolongado; y como si aquel ladrido hubiera tenido mas fuerza que la violenta carrera del caballo, el infante despertó.\"},{\"heading\":false,\"text\":\"Y al despertar el infante, el caballo se paró de repente, como si le hubiera dominado un encanto.\"},{\"heading\":false,\"text\":\"Y Abd-el-Rahhaman vió delante de sí, en la entrada de un sendero, á la luz de la luna, un enorme perro de montería, sentado y mirándole de hito en hito, con unos ojos que parecian brasas.\"},{\"heading\":false,\"text\":\"El infante invocó á Dios.\"},{\"heading\":false,\"text\":\"Aquel perro era horrible, feróz.\"},{\"heading\":false,\"text\":\"Sus largas lanas blancas arrastraban por el suelo.\"},{\"heading\":false,\"text\":\"Al ver ante sí al infante se levantó, se volvió, y se dió á correr por la montaña.\"},{\"heading\":false,\"text\":\"El infante apretó los acicates á su caballo, que partió tras el perro.\"},{\"heading\":false,\"text\":\"Y el perro siguió corriendo por cortaduras, por precipicios, por ramblas y por desfiladeros.\"},{\"heading\":false,\"text\":\"A cada paso que adelantaban, el paisage se hacia mas agreste y bravio, mas triste y mas opaca la luz de la luna.\"},{\"heading\":false,\"text\":\"Al fin el perro se detuvo en la cumbre de un cerro, delante de una vieja torre de atalaya.\"},{\"heading\":false,\"text\":\"El infante refrenó su caballo.\"},{\"heading\":false,\"text\":\"Y echó pie á tierra.\"},{\"heading\":false,\"text\":\"Cuando buscó al perro, este habia desaparecido.\"},{\"heading\":false,\"text\":\"Por una de las saeteras de la torre se veia una luz rojiza.\"},{\"heading\":false,\"text\":\"La puerta de hierro de la atalaya estaba cerrada.\"},{\"heading\":false,\"text\":\"Cuando el walí de Algeciras se dirigió á ella para llamar, oyó dentro el relincho de un caballo y el crugir de un cerrojo por la parte de adentro de la puerta, que se abrió al fin, dejando ver dos hombres.\"},{\"heading\":false,\"text\":\"Uno de ellos era un esclavo negro: llevaba en la una mano una antorcha, y en la otra tenia del diestro un hermoso caballo árabe.\"},{\"heading\":false,\"text\":\"El otro hombre, era un hermoso y jóven caballero moro.\"},{\"heading\":false,\"text\":\"Al verle, el walí de Algeciras dió un paso atrás.\"},{\"heading\":false,\"text\":\"Aquel caballero era su hijo, el infante de Granada Ebn-Ismail.\"},{\"heading\":false,\"text\":\"El asesino del rey Abul-Walid, el amante de su hermana la sultana Ketirah, el que se habia olvidado de su otra hermana María.\"},{\"heading\":false,\"text\":\"No deben olvidar los que leyeren esta historia, que el mago Jacub-Al-Hakem habia ocultado al walí Abd-el-Rahhaman, que Ketirah era su hija; que el infante Ebn-Ismail ignoraba que fuese su hermana, y que solo conocia este horrible secreto María, que no habia podido revelarlo á nadie recluida en la torre de la Cautiva.\"},{\"heading\":false,\"text\":\"El infante retrocedió á su vez al reconocer á la luz de la luna á su padre.\"},{\"heading\":false,\"text\":\"--Al fin te encuentro, dijo con voz ronca el walí: á tí, que huyes de la luz del sol, de la justicia de los hombres y de la indignacion de tu padre.\"},{\"heading\":false,\"text\":\"--¡Ah, señor! contestó todo trémulo el infante.\"},{\"heading\":false,\"text\":\"--Zenko, dijo el walí al esclavo de su hijo, ténme el caballo, y tú, añadió dirigiendo severamente su voz al infante, llévame á donde podamos hablar sin que nos escuchen mas oidos que los de Dios.\"},{\"heading\":false,\"text\":\"El infante todo confuso, tomó la antorcha de las manos de Zenko, se dirigió al interior de la torre, y subió por unas escaleras.\"},{\"heading\":false,\"text\":\"Se encontraron al fin en un pequeño espacio, en el que ni lecho habia, y el infante Ebn-Ismail puso la antorcha entre una grieta del muro.\"},{\"heading\":false,\"text\":\"--¡Digno albergue de un asesino! esclamó el walí mirando severamente á su hijo: cuadra bien á quien tal crímen ha cometido mancillando mis canas; una vieja atalaya abandonada, por refugio, en lo mas áspero de una montaña.\"},{\"heading\":false,\"text\":\"--¿Sabes tú, padre y señor, por qué maté yo al rey Abul-Walid? dijo Ebn-Ismail levantando los ojos y posándolos en su padre.\"},{\"heading\":false,\"text\":\"--Y aun querrás disculparte de aquel crímen.\"},{\"heading\":false,\"text\":\"--Yo maté á un tirano en medio de su córte, con peligro, y combatí despues la Alhambra; si no pude tomarla no fué mia la culpa si no de la suerte, que me volvió las espaldas.\"},{\"heading\":false,\"text\":\"--Tú mataste al rey, por gozar libremente los amores de la maldita sultana Ketirah.\"},{\"heading\":false,\"text\":\"--¡Ah! no: es cierto que despues la sultana me ha enloquecido, pero... yo maté al rey, porque pretendia deshonrar á una cautiva que me robó en Martos: fué necesario matarle, para que no sacrificase á sus deseos á la infeliz María.\"},{\"heading\":false,\"text\":\"--¡María! esclamó Abd-el-Rahhaman: ¡María! ¿es la cristiana que está cautiva en la Alhambra?\"},{\"heading\":false,\"text\":\"--Si señor; ella es.\"},{\"heading\":false,\"text\":\"--Y dime, hijo mio... ¿has amado tú á esa doncella?\"},{\"heading\":false,\"text\":\"--Sí, si señor, pero de una manera tranquila, pura, como se ama á una hermana.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡gracias! ¡gracias, poderoso Señor, que no has permitido que el hermano deshonre á su hermana!\"},{\"heading\":false,\"text\":\"--¿Qué decís, señor?\"},{\"heading\":false,\"text\":\"--¡Oh! nada, nada. Digo que has hecho muy bien en matar al rey.\"},{\"heading\":false,\"text\":\"--Y habeis dicho tambien que María es mi hermana; eso mismo me dijo una noche de una manera misteriosa, un mago, un astrólogo: la noche que precedió al dia en que maté á Abul-Walid, y cuando quise que el mago me esplicase sus palabras, me dijo: «Muestra á tu padre el walí de Algeciras las joyas que tu hermana llevaba el dia en que la encontraste en Martos.»\"},{\"heading\":false,\"text\":\"--¿Y dónde están esas joyas? dijo con anhelo el walí.\"},{\"heading\":false,\"text\":\"--Aquí, bajo una piedra, escondidas en este mismo aposento.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡muéstrame, muéstrame esas joyas!\"},{\"heading\":false,\"text\":\"El infante fué á un ángulo del aposento, levantó una piedra, socavó debajo de ella la tierra con su puñal, y sacó un talego de seda, que entregó á su padre.\"},{\"heading\":false,\"text\":\"El walí sacó con ansia aquellas joyas y las examinó.\"},{\"heading\":false,\"text\":\"Eran las mismas que Sancho de Arias habia dado á María.\"},{\"heading\":false,\"text\":\"--¡Ah! esclamó el walí; ¡las joyas de su madre!\"},{\"heading\":false,\"text\":\"--¿Y quién era su madre? dijo Ebn-Ismail.\"},{\"heading\":false,\"text\":\"--Su madre no era la tuya; pero ella es mi hija. ¡Y el rey Ismail se habia atrevido á la honra de esa doncella!... Has hecho bien en matarle: has hecho bien, porque le has matado defendiendo á tu hermana.\"},{\"heading\":false,\"text\":\"--¡Mi hermana! ¡mi hermana! esclamó Ebn-Ismail: harto me lo decia el corazon!\"},{\"heading\":false,\"text\":\"--Y sin embargo, respecto á otra muger el corazon te ha sido infiel, dijo Abd-el Rahhaman.\"},{\"heading\":false,\"text\":\"--¡Otra muger!\"},{\"heading\":false,\"text\":\"--La infame sultana Ketirah.\"},{\"heading\":false,\"text\":\"--¡La infame sultana has dicho, padre y señor!\"},{\"heading\":false,\"text\":\"--Sí; la muger que por ser sultana envenenó á su padre.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡Dios mio!\"},{\"heading\":false,\"text\":\"--La que ayudándose de Masud-Almoharaví, y ayudándole á él, mató á tu prima la sultana Aleidah.\"},{\"heading\":false,\"text\":\"--¡La prueba, padre, la prueba! esclamó Ebn-Ismail.\"},{\"heading\":false,\"text\":\"--La conciencia de la sultana Ketirah te dará esa prueba, si quieres, esta misma noche.\"},{\"heading\":false,\"text\":\"--¡Esta misma noche!\"},{\"heading\":false,\"text\":\"--Sí; ¿para qué salías cuando yo llegué de la torre? Para ir á arrojarte en los brazos de Ketirah.\"},{\"heading\":false,\"text\":\"--Es verdad.\"},{\"heading\":false,\"text\":\"Además este pergamino le revelará los crímenes de la sultana y de su cómplice.\"},{\"heading\":false,\"text\":\"Y dió á su hijo el pergamino que le habia dado el mago en la caverna de las hadas malditas.\"},{\"heading\":false,\"text\":\"--Pues bien; vé, añadió el walí, pero vé á vengar á tu prima la sultana Aleidah, á salvar á tu hermana María: yo te acompañaré.\"},{\"heading\":false,\"text\":\"Y tras estas palabras salieron del aposento y bajaron las escaleras, tomaron los caballos y partieron por entre los cerros á la Alhambra, que ya estaba próxima, el padre y el hijo.\"}]},{\"title\":\"La torre de la cautiva. — capítulo XXVII\",\"blocks\":[{\"heading\":false,\"text\":\"--Padre, dijo el infante Ebn-Ismail mientras marchaban, ¿quieres la felicidad de tu hija la cristiana?\"},{\"heading\":false,\"text\":\"--¡Qué si quiero su felicidad!... yo la he llorado muerta; yo la he recordado continuamente en mis sueños, sin poder olvidarla; y era que mi hija vivia y su espíritu se hacia sentir del mio. ¡Oh! ¡que si quiero hacerla feliz! ¡Dudarías tú, Mohammet, de que yo desease tu felicidad!\"},{\"heading\":false,\"text\":\"--La felicidad de mi hermana María puede serte muy dolorosa, señor.\"},{\"heading\":false,\"text\":\"--¡Dolorosa! ¿y por qué?\"},{\"heading\":false,\"text\":\"--María ama á un hombre.\"},{\"heading\":false,\"text\":\"--¿Y á qué hombre ama?\"},{\"heading\":false,\"text\":\"--A un cristiano.\"},{\"heading\":false,\"text\":\"Detúvose un instante contrariado Abd-el-Rahhaman.\"},{\"heading\":false,\"text\":\"--¡Ah! dijo, me la robaron los cristianos; ha crecido entre ellos... ha debido, pues, amar á un cristiano.... ¿Y ese cristiano es digno de ella y de nuestra sangre?\"},{\"heading\":false,\"text\":\"--Es un valiente caballero de Martos: el dia en que iba á casarse con María, el rey Abul-Walid acometió la villa, y Gonzalo Nuñez sacó á María de la iglesia, la llevó á su casa, y defendió aquella casa con sus parientes y amigos. Yo la acometia. En la acometida mis gentes cayeron como la mies bajo la hoz del segador, y ese valiente mancebo, Gonzalo Nuñez, el amante de mi hermana, cayó al fin á mis pies.\"},{\"heading\":false,\"text\":\"--¿Y murió?\"},{\"heading\":false,\"text\":\"--No; no lo quiso Dios. Cuando salvé á mi hermana del furor y de la codicia de mis esclavos, porque es muy hermosa y estaba cubierta con las ricas joyas que has visto, padre; cuando la ví llorando, aterrada, trémula, sentí por ella un amor como nunca le habia sentido, dulce, tranquilo. Procuré consolarla, y ella me dijo que habia perdido á su padre y á su esposo. Su padre estaba muerto; pero no se sabia lo que habia sido de su esposo, y le buscamos entre los cadáveres, y le encontramos.\"},{\"heading\":false,\"text\":\"--¡Vivo!\"},{\"heading\":false,\"text\":\"--Con muy pocas esperanzas de vida. Yo le dejé con mi sabio médico y dí órden á mis esclavos de que le llevasen á mi castillo de Hins-Aleux. Despues pretendí salvar á María, pero no pude. El rey la vió, la codició, y me la robó. Algunos dias despues, maté al rey.\"},{\"heading\":false,\"text\":\"--¿Y el esposo de María, vive?\"},{\"heading\":false,\"text\":\"--¡Oh! si señor, vive y está restablecido y fuerte. ¿Quieres hacer feliz á tu hija, señor?\"},{\"heading\":false,\"text\":\"--¡Oh! sí.\"},{\"heading\":false,\"text\":\"--Pues bien, separémonos en la entrada del camino de Granada que ya está cercano: corre tú al castillo de Hins-Aleux. La noche empieza; picando, bien puedes llegar y traer á Gonzalo antes de la media noche, y entregarle tu hija.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡poderoso Señor!\"},{\"heading\":false,\"text\":\"--Yo entretanto, veré á la sultana Ketirah, y si no te han engañado, padre y señor, si ella ha sido la envenenadora de mi perdida Aleidah... ¡oh! yo te juro castigarla, señor, y de tal modo, que cause horror á las gentes.\"},{\"heading\":false,\"text\":\"--¿Y cuando vuelva con Gonzalo, ¿cómo sabré donde está mi hija?\"},{\"heading\":false,\"text\":\"--Entra señor por detrás de la Alhambra y llega hasta la torre de la puerta de Hierro, un esclavo mio te esperará y te guiará. Pero he allí el camino de Granada, señor, yo voy á seguir por los cerros hácia la Alhambra, tú por el camino, gana la Vega y llega á Hins-Aleux. Dí á Gonzalo que eres mi padre, que todo lo sabes y que vas á entregarle tu hija.\"},{\"heading\":false,\"text\":\"--Adios, pues, infante de Granada, hijo mio; adios, pues: ha llegado la hora de comenzar un grande sacrificio y de efectuar una gran venganza.\"},{\"heading\":false,\"text\":\"Y el padre acercó su caballo al de su hijo y le abrazó.\"},{\"heading\":false,\"text\":\"Luego se separó, bajó por un sendero á un ancho camino y partió por él á la carrera.\"},{\"heading\":false,\"text\":\"Ebn-Ismail se lanzó tambien á la carrera por un valle cercano y se perdió en la montaña repitiendo:\"},{\"heading\":false,\"text\":\"--¡La sultana Ketirah, esa hermosura que parece un arcángel del sétimo cielo y á quien yo adoraba, es la infame envenenadora de mi perdida sultana Aleidah! si mi padre no se ha engañado.... ¡oh, mas la valiera no haber nacido!\"}]},{\"title\":\"La torre de la cautiva. — capítulo XXVIII\",\"blocks\":[{\"heading\":false,\"text\":\"En una magnífica cámara de un fuerte castillo moro, se paseaba solo un jóven con trage castellano.\"},{\"heading\":false,\"text\":\"Estaba pálido, como acabado de salir de una enfermedad.\"},{\"heading\":false,\"text\":\"Pero era hermoso, muy hermoso, y en la apariencia muy bravo.\"},{\"heading\":false,\"text\":\"Apenas contaría veinte y cuatro años.\"},{\"heading\":false,\"text\":\"De una de las columnas que sostenian la techumbre de cedro de la cámara, estaba colgado un arnés completo castellano, y apoyada en él una larga lanza.\"},{\"heading\":false,\"text\":\"Bajo este arnés se veian los jaeces de un caballo.\"},{\"heading\":false,\"text\":\"El jóven se asomaba de tiempo en tiempo á un ajimez, y miraba á la luna.\"},{\"heading\":false,\"text\":\"Y sus ojos se llenaban de lágrimas.\"},{\"heading\":false,\"text\":\"--¡Oh! esclamaba: ¿te mirará ella á tí, blanca lámpara de la noche, como yo te miro pensando en ella? ¡Oh, María, mi María!\"},{\"heading\":false,\"text\":\"Y el jóven se apartaba del ajimez, y volvia á pasearse por la cámara.\"},{\"heading\":false,\"text\":\"De repente se escuchó en la poterna el sonido de una bocina; se oyó el estruendo del puente y del rastrillo, y poco despues un moro asomó á la puerta de la cámara y dijo:\"},{\"heading\":false,\"text\":\"--¡Cristiano! el padre de mi noble y poderoso señor, el esclarecido é invencible walí de Algeciras, Abd-el-Rahhaman, desea verte.\"},{\"heading\":false,\"text\":\"--¡Oh! que entre, que entre al momento, dijo Gonzalo.\"},{\"heading\":false,\"text\":\"Poco despues entraba en la cámara Ab-el-Rahhaman.\"},{\"heading\":false,\"text\":\"Observó durante algunos segundos en silencio al jóven, y el noble semblante del walí resplandeció con la espresion de la benevolencia.\"},{\"heading\":false,\"text\":\"--Guárdete Dios, mancebo, y te proteja, le dijo: ¿sabes quién soy?\"},{\"heading\":false,\"text\":\"--Sé, segun acaban de decirme, que eres el padre de un caballero moro á quien mi desdicha hizo mi vencedor, y á quien despues me he visto obligado á amar, porque le debo la vida.\"},{\"heading\":false,\"text\":\"--¡Oh! Ebn-Ismail, mi hijo, te ama tambien, cristiano, y á tí me enviía.\"},{\"heading\":false,\"text\":\"--Gracias doy al cielo de haber conocido un tan grande caballero como demuestras ser. Pero ¿qué me quieres?\"},{\"heading\":false,\"text\":\"--¿No deseas nada?\"},{\"heading\":false,\"text\":\"--¡Desear!... sí, si por cierto... deseo la muerte.\"},{\"heading\":false,\"text\":\"--¡La muerte!\"},{\"heading\":false,\"text\":\"--Sí; estoy fuera de mi patria, vencido...\"},{\"heading\":false,\"text\":\"--Pero no eres cautivo. En mi hijo has encontrado un hermano; en mí un padre.\"},{\"heading\":false,\"text\":\"--Dios os lo pague, dijo Gonzalo; ¿pero me podreis dar vosotros lo que yo he perdido?\"},{\"heading\":false,\"text\":\"--Hablas como mancebo, y como mancebo enamorado: sobre tí no han llovido todavía todas las amarguras las nubes de la desgracia. Amas y eres amado, y si por algun tiempo el destino te ha robado mi hija...\"},{\"heading\":false,\"text\":\"--¡Tu hija!... yo no conozco á tu hija, contestó con estrañeza Gonzalo.\"},{\"heading\":false,\"text\":\"--¡Que no la conoces, y mueres por ella!\"},{\"heading\":false,\"text\":\"--Te engañas, señor; yo no he amado mas que á una muger, y esa muger es cristiana.\"},{\"heading\":false,\"text\":\"--Mi hija es cristiana tambien.\"},{\"heading\":false,\"text\":\"--La muger que yo amo tiene el hermoso nombre de la santa Vírgen madre de Dios.\"},{\"heading\":false,\"text\":\"--El nombre de la madre de Jesus, es el nombre de mi hija.\"},{\"heading\":false,\"text\":\"--¡María!\"},{\"heading\":false,\"text\":\"--Sí, María.\"},{\"heading\":false,\"text\":\"--Pero es imposible. La María de mi amor, ha vivido siempre en Martos, y era hija del corregidor Sancho de Arias.\"},{\"heading\":false,\"text\":\"--En Martos ha vivido mi hermosa María, y por hija del corregidor Sancho de Arias pasaba.\"},{\"heading\":false,\"text\":\"--¡Oh! esto no puede ser.\"},{\"heading\":false,\"text\":\"--Dios, que es Todo poderoso, ha querido que sea.\"},{\"heading\":false,\"text\":\"--¡Hija tuya, María!\"},{\"heading\":false,\"text\":\"--Sí; y de una rica-hembra aragonesa.\"},{\"heading\":false,\"text\":\"--¡Oh! no alcanzo á comprenderlo.\"},{\"heading\":false,\"text\":\"--Hace centenares de años que primero los árabes, y despues los moros, estamos en contínuo trato con los cristianos: las razas se han mezclado, porque el amor es mas poderoso que el odio: ya ha sido una hermosa doncella originaria de Africa, cautiva en la entrada de una villa, la que ha dado su sangre á los hijos del cristiano; ya una hermosa cristiana arrebatada á su familia, la que ha dado su sangre á los hijos del Islam. ¿Te parece tan estraño que yo en mis mocedades tomase por esposa á una cristiana, y que la hija, fruto de estos amores, me fuese robada por los cristianos?\"},{\"heading\":false,\"text\":\"--¡Oh! bien puede ser, dijo Gonzalo.\"},{\"heading\":false,\"text\":\"--¿Y amarías tú menos á María porque fuese mi hija?\"},{\"heading\":false,\"text\":\"--¡Aborrecerla! ¿quién habla de aborrecerla? ¿puedo aborrecerla acaso? Y luego, ¿no debo á tu hijo la vida?\"},{\"heading\":false,\"text\":\"--Y tu amor y el honor de María. Si mi hijo no hubiera matado al rey de Granada, ¿qué hubiera sido de ella? ¡Estaria deshonrada, triste y sola en el harem de la Alhambra!\"},{\"heading\":false,\"text\":\"--¡Oh! ¡Dios mio! ¿y ahora dónde está?\"},{\"heading\":false,\"text\":\"--Cautiva en una torre de la Alhambra.\"},{\"heading\":false,\"text\":\"--¿Pero, pura... salvada?\"},{\"heading\":false,\"text\":\"--A que me ayudes á salvarla vengo por tí.\"},{\"heading\":false,\"text\":\"--¡Por mí!\"},{\"heading\":false,\"text\":\"--Sígueme y te entrego á María.\"},{\"heading\":false,\"text\":\"--¡Oh, si te sigo! dijo Gonzalo dirijiéndose á su armadura.\"},{\"heading\":false,\"text\":\"--Voy á ser tu escudero; dijo el infante Abd-el-Rahhaman tomando las piezas de aquella armadura.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡sí; pronto! ¡pronto, si de salvarla se trata!\"},{\"heading\":false,\"text\":\"--¡Salvarla! ¡sí! ¿y crees tú que el salvar á mi hija no me cuesta un inmenso sacrificio?\"},{\"heading\":false,\"text\":\"--¡Un sacrificio!\"},{\"heading\":false,\"text\":\"--Sí, salvarla es hacerla feliz, segun me ha dicho mi hijo, María te ama de tal modo, que no puede ser feliz sino siendo tu esposa. Tú la llevarás contigo, y yo, que hace catorce años que no la veo, que no la he visto crecer, la veré un momento para perderla despues.\"},{\"heading\":false,\"text\":\"--¡Perderla! ¿y por qué no seguirnos, señor?\"},{\"heading\":false,\"text\":\"--¡Seguiros! ¿y á dónde queriais que yo fuese con vosotros?\"},{\"heading\":false,\"text\":\"--A Castilla.\"},{\"heading\":false,\"text\":\"--¡Entre cristianos!\"},{\"heading\":false,\"text\":\"--¿Y no es tu hija cristiana?\"},{\"heading\":false,\"text\":\"--Para darte á María, dijo con severidad el infante; ¿te he pedido yo que te quedes entre nosotros, y que apostates de tu religion?\"},{\"heading\":false,\"text\":\"--¡Ah, señor, perdon!\"},{\"heading\":false,\"text\":\"--¡Alí! ¡Alí! dijo el infante acabando de enhevillar la última pieza del arnés de Gonzalo: un caballo de batalla, y veinte ginetes. Pronto, pronto.\"},{\"heading\":false,\"text\":\"El esclavo que habia aparecido á la puerta, desapareció.\"},{\"heading\":false,\"text\":\"--No hablemos, pues, mas de esto, dijo el infante dirijiendo de nuevo su palabra á Gonzalo. Así lo ha querido Dios, y así es, porque no puede ser que deje de cumplirse la voluntad de Dios. Ahora, cristiano, sígueme y roguemos á Dios que nos proteja, porque la empresa que vamos á acometer es peligrosa.\"},{\"heading\":false,\"text\":\"Y salió con Gonzalo de la cámara.\"},{\"heading\":false,\"text\":\"Poco despues, el moro y el cristiano cabalgaban por el camino de Granada y á gran prisa, seguidos de veinte ginetes moros.\"}]},{\"title\":\"La torre de la cautiva. — capítulo XXIX\",\"blocks\":[{\"heading\":false,\"text\":\"Volvamos, pues á la relacion que dejamos interrumpida en el momento en que despues de haber entrado el infante Ebn-Ismail, por un ajimez en la habitacion de la torre de la Cautiva donde le esperaba la sultana Ketirah, rechazó á esta, que como solia, se habia arrojado entre sus brazos.\"},{\"heading\":false,\"text\":\"Esta accion, inesperada, violenta, y la espresion lívida del semblante de Ebn-Ismail, sobrecogieron á la sultana.\"},{\"heading\":false,\"text\":\"--¿Qué te he hecho yo, desdichada de mí, esclamó, para que así me arrojes de tus brazos? ¿en qué te ha ofendido tu esclava, señor de mí alma, ó es que ya no me amas, y quieres abandonarme?\"},{\"heading\":false,\"text\":\"--¡Quisiera Dios que nunca te hubiera amado! esclamó el infante.\"},{\"heading\":false,\"text\":\"--¡Habla! ¡habla! esclamó trémula la sultana: ¡esplícame la razon de tus palabras!\"},{\"heading\":false,\"text\":\"--Aun no es tiempo, dijo el infante; faltan tres personas aquí.\"},{\"heading\":false,\"text\":\"--¿Qué faltan tres personas?\"},{\"heading\":false,\"text\":\"--Sí; haz llamar á Masud-Almoharaví.\"},{\"heading\":false,\"text\":\"--¡A Masud! esclamó la sultana; ¡oh! ¡si fuera verdad lo que sospecho!\"},{\"heading\":false,\"text\":\"--¿Y qué sospechas?\"},{\"heading\":false,\"text\":\"--¡Tú quieres ser rey de Granada!\"},{\"heading\":false,\"text\":\"--¡Yo!\"},{\"heading\":false,\"text\":\"--Sí; sabes que yo te amo antes que á mi alma, sabes que Masud no puede negarme nada y... ansías esa corona...\"},{\"heading\":false,\"text\":\"--Puede ser... esclamó despues de un momento de profunda meditacion Ebn-Ismail.\"},{\"heading\":false,\"text\":\"--Y es el sueño mas ardiente de mi alma, dijo Ketirah: ¡tú sultan de Granada! ¡yo tu sultana! el hijo de Abul-Walid y de Aleidah, la difunta sultana, el rey Mohammet, es débil de salud; puede morir de un momento á otro.\"},{\"heading\":false,\"text\":\"--Llama á Masud-Almoharaví; repitió el infante.\"},{\"heading\":false,\"text\":\"Ketirah se levantó y salió.\"},{\"heading\":false,\"text\":\"Poco despues volvió acompañada del wazir.\"},{\"heading\":false,\"text\":\"--¡Masud! ¡Masud! esclamó Ketirah; ¡ha llegado el momento, quiere la corona de Granada!\"},{\"heading\":false,\"text\":\"--¡Qué quiere la corona de Granada... el infante Ebn-Ismail, el matador del rey Abul-Walid! aun no es tiempo... aun no es tiempo, mas adelante...\"},{\"heading\":false,\"text\":\"--Pero ya es tiempo de castigar vuestros crímenes, dijo Ebn-Ismail que habia corrido á la puerta de la cámara, la habia cerrado, y se habia guardado la llave.\"},{\"heading\":false,\"text\":\"--¡Oh! ¿qué es esto? dijo Masud-Almoharaví, mientras la sultana miraba aterrada al infante: ¿de qué crímenes hablas?\"},{\"heading\":false,\"text\":\"--Aun faltan dos personas; dijo sombriamente Ebn-Ismail.\"},{\"heading\":false,\"text\":\"--Pero yo no te comprendo, no puedo comprenderte, esclamó Ketirah.\"},{\"heading\":false,\"text\":\"--Faltan; mi padre y el esposo de mi hermana.\"},{\"heading\":false,\"text\":\"Y se puso á pasear sombriamente á lo largo de la cámara.\"},{\"heading\":false,\"text\":\"La sultana y el wazir se encontraban en una situacion estraña; en vano le hablaba, le suplicaba la sultana Ketirah: el infante continuaba en su sombrío silencio, y en su paseo inalterable.\"},{\"heading\":false,\"text\":\"En vano Masud-Almoharaví, queria resolver aquella situacion por la fuerza.\"},{\"heading\":false,\"text\":\"El feróz y reconocido valor del infante le contenia.\"},{\"heading\":false,\"text\":\"Pesaba sobre la sultana un presentimiento horrible: el presentimiento de lo desconocido.\"},{\"heading\":false,\"text\":\"Masud-Almoharaví temblaba porque en el semblante del infante aparecia una espresion terrible.\"},{\"heading\":false,\"text\":\"Pasaron así dos horas: el infante paseando, ceñudo, pálido y silencioso murmurando palabras ininteligibles, la sultana y el wazir temiéndolo todo, retirados é inmóviles en un ángulo.\"},{\"heading\":false,\"text\":\"Al fin, sonó abajo, al pie de la torre, un ténue silvido.\"},{\"heading\":false,\"text\":\"El infante corrió al ajimez.\"},{\"heading\":false,\"text\":\"A la luz de la luna, vió al pie de la torre en el barranco, dos ginetes y algunos hombres á pie.\"},{\"heading\":false,\"text\":\"Entonces el infante dió otro silvido en el ajimez, y echó abajo la larguísima escala.\"},{\"heading\":false,\"text\":\"Descabalgaron los dos ginetes, los de á pie tuvieron los caballos, y los que habian desmontado el uno tras el otro, treparon por la escala.\"},{\"heading\":false,\"text\":\"Un momento despues, entraron por el ajimez, Gonzalo Nuñez y el walí Abd-el-Rahhaman, armados de todas armas.\"},{\"heading\":false,\"text\":\"--He aquí que ha llegado el momento del juicio, esclamó Ebn-Ismail dirijiendo su ronca palabra á la sultana y al wazir; adelantad, padre mio; adelantad, hermano mio; he aquí á los asesinos de la sultana Aleidah.\"}]},{\"title\":\"La torre de la cautiva. — capítulo XXX\",\"blocks\":[{\"heading\":false,\"text\":\"Al oir aquella acusacion, un grito de espanto se exhaló á un tiempo de las bocas de la sultana y del wazir.\"},{\"heading\":false,\"text\":\"Al escuchar aquel grito, Ebn-Ismail se puso pálido, y avanzó hacia Ketirah y Masud.\"},{\"heading\":false,\"text\":\"--¿Conque son ciertos los crímenes de que os acusa este pergamino? esclamó sacando de entre su faja el que le habia dado su padre.\"},{\"heading\":false,\"text\":\"El infante Abd-el-Rahhaman, se cruzó entre su hijo y los dos miserables que estaban aterrados.\"},{\"heading\":false,\"text\":\"--Donde está el padre el hijo calla, dijo con gran autoridad.\"},{\"heading\":false,\"text\":\"Y apartó á Ebn-Ismail, que se hizo atrás pálido y sombrío.\"},{\"heading\":false,\"text\":\"--Y tú cristiano, mira y escucha como un caudillo moro hace justicia en nombre de Dios.\"},{\"heading\":false,\"text\":\"Gonzalo ante lo que veia estaba profundamente maravillado.\"},{\"heading\":false,\"text\":\"--He ahí, continuó Abd-el-Rahhaman, una muger que parece ser un arcángel, y que dentro de sí tiene el alma de Satanás: he ahí un viejo que debia ser un espejo de justicia y de valor para los vasallos del rey de Granada, y que sin embargo es un miserable zorro, que salió de su oscura madriguera para subir á la luz por la senda del crímen.\"},{\"heading\":false,\"text\":\"--¿Y con qué derecho te atreves á insultarme á mí, á la madre de tu rey, infante de Granada? esclamó la sultana que habia logrado dominarse.\"},{\"heading\":false,\"text\":\"--Con el que me dá la justicia de Dios, contestó el infante; con el que me dán vuestros crímenes.\"},{\"heading\":false,\"text\":\"--¡Mis crímenes! ¿y cuáles son mis crímenes? esclamó la sultana.\"},{\"heading\":false,\"text\":\"--¿Qué hacías aquí, á qué has venido á esta torre, hermosa Ketirah? esclamó con sarcasmo Abd-el-Rahhaman.\"},{\"heading\":false,\"text\":\"--¡Qué á que he venido aquí! esclamó Ketirah con audacia: engañada por tu hijo.\"},{\"heading\":false,\"text\":\"--¿Por mi hijo?\"},{\"heading\":false,\"text\":\"--Sí, tu hijo habia solicitado verme...\"},{\"heading\":false,\"text\":\"--¡Y tú te prestaste á ver al matador de tu esposo, en el solitario aposento de una torre del muro, donde el regicida debia entrar por medio de una escala, para apurar un placer adúltero entre los brazos de una muger infame!\"},{\"heading\":false,\"text\":\"--¡Padre! esclamó confundido Ebn-Ismail.\"},{\"heading\":false,\"text\":\"--Ya que tuviste razones bastantes para matar al rey, ¿has tenido las mismas para consumar unos horribles amores con su viuda?\"},{\"heading\":false,\"text\":\"--¡Padre!\"},{\"heading\":false,\"text\":\"--Silencio cuando yo hablo. He venido á hacer justicia en nombre de Dios, y habrá justicia para todos.\"},{\"heading\":false,\"text\":\"--Sí, para todos habrá justicia, dijo una voz terrible y retumbante al otro lado de la cerrada puerta.\"},{\"heading\":false,\"text\":\"Y sin que aquella puerta se abriese apareció en la cámara el viejo rey mago condenado, Abu-Jacub-el-Alime, el padre de las trescientas cincuenta y cuatro hadas malditas.\"},{\"heading\":false,\"text\":\"Su aparicion aterró á todos, incluso Gonzalo, que nunca habia pensado existiese un viejo tan horrible como Jacub.\"},{\"heading\":false,\"text\":\"--Sí, habrá justicia para todos, esclamó el mago adelantando en medio del silencio general y sentándose en el suelo sobre la alfombra en el centro de la cámara. Para todos habrá castigo y recompensa: tú, cristiano, que no has ofendido á Dios, que no has manchado tus manos con sangre, que no te has vendido á Satanás, tendrás por recompensa á tu buena, á tu pura, á tu inocente, á tu amada María; pero tú, infante de Granada Abd-el-Rahhaman, tú, que amparaste á Walidé cuando la encontraste con las manos teñidas en sangre; tú, que casi renegaste de Dios por los amores de una cristiana; tú, que diste ocasion con tus pasiones á que Walidé se tiñera en la sangre de doña Catalina; tú, que cuando desapareció Walidé huyendo de tu furor y llevándose consigo una hija tuya, olvidaste á tu hija por odio á su madre, y la abandonaste á su destino, y la olvidaste, y has causado su perdicion por tu abandono; tú, que huiste cobardemente de Illora cuando te acometieron los fronteros de Alcaudete y con tu cobardia dejaste entre los cristianos á otra hija tuya, que criada entre otras gentes adoró á otros dioses; tú, que con tu soberbia has ensoberbecido á tu hijo, que ha matado á su rey; tú, que despues no has castigado á tu hijo; tú, infante de Granada, walí de Algeciras, Mohammet-Abd-el Rahhaman, tú serás castigado: pasarás dias de horror y noches de tinieblas y de llanto, y el remordimiento roerá tu corazon, porque tú, por saciar una venganza contra un enemigo, has producido las desgracias de tu familia, maldecida por Dios.\"},{\"heading\":false,\"text\":\"Abd-el-Rahhaman quiso contestar y no pudo: los ojos del rey mago condenado, fijos en él, le helaban la sangre.\"},{\"heading\":false,\"text\":\"--¿Y qué te diré yo, Ketirah, teñida en la sangre del que llamabas tu padre; que ocupaste el trono de Abul-Walid, manchado con la sangre de su esposa asesinada por tí; que despues distes el golpe de misericordia, la última puñalada á tu esposo, asesinado por tu amante, y abriste los brazos á ese mismo amante teñido en la sangre de tu esposo?\"},{\"heading\":false,\"text\":\"Ketirah abrió los labios para contestar, y la palabra se heló en ellos.\"},{\"heading\":false,\"text\":\"El mago se volvió terrible á Masud Almoharaví, que temblaba.\"},{\"heading\":false,\"text\":\"--Y tú, esclamó, amigo traidor del pasado wazir Abul-Fath-Nazir-el-Ferih, tú, el que por sustituirle alhagaste la ambicion e la infame Ketirah, y la impulsaste á que envenenara al que creia su padre....\"},{\"heading\":false,\"text\":\"--¡Pues qué! esclamó Ketirah, ¿no era mi padre Abul-Fath-Nazir?\"},{\"heading\":false,\"text\":\"El mago condenado no contestó á Ketirah, sino que siguió dirijiendo su tremenda palabra á Masud, que estaba doblegado ante aquella terrible acusacion que parecia la voz de su conciencia.\"},{\"heading\":false,\"text\":\"--Tú, tirano, codicioso y soberbio, que ayudaste á Ketirah en la muerte de la sultana Aleidah; tú, que la llevaste al tálamo de Abul-Walid, tú, que has sido el cómplice de los crímenes de esa muger, ¿qué te puedo yo decir sino que la justicia de Dios está suspendida sobre tu cabeza?\"},{\"heading\":false,\"text\":\"LETRE dibº y litº Lit de J.J. MARTINEZ, Madrid]\"},{\"heading\":false,\"text\":\"Calló el mago, y todos callaron, y un silencio de muerte dominó en la torre.\"},{\"heading\":false,\"text\":\"--¿Y qué haces tú, infante de Granada Abd-el-Rahhaman, tú que habias venido á salvar á tu hija la cristiana y á castigar á la parricida, á la adúltera, á la incestuosa?\"},{\"heading\":false,\"text\":\"--¡A la incestuosa! esclamó Ketirah adelantando pálida como un cadáver.\"},{\"heading\":false,\"text\":\"--Esperad, esperad, dijo el mago; siento á una persona que se acerca; esa persona es María: Masud, al llamarle Ketirah, se encontraba con María, y por olvido, al bajar ha dejado abierta la puerta de la prision de la cristiana. Ella ha aprovechado esta circunstancia y ha recorrido la torre: pero su puerta estaba cerrada, y al cabo despues de bajar desde el almenar hasta los subterráneos, ha estado ahí tras esa puerta escuchando estremecida de terror. Vé y abre á tu hermana, infante Ebn-Ismail; abre esa puerta y entrégala á su esposo, pero despues que haya pronunciado la revelacion que ha de ser vuestro castigo.\"},{\"heading\":false,\"text\":\"El infante Ebn-Ismail dominado por el acento del mago, fué á la puerta y la abrió: María entró pálida, fatal, aterrada, y adelantando hácia Ketirah dijo con acento solemne:\"},{\"heading\":false,\"text\":\"--¡Yo he oido nombrar aquí á la sultana de Granada! yo he oido una voz de muger, y aquí no hay mas muger que tú: ¿serás tu acaso mi hermana; la hija de Walidé, la segunda esposa de mi padre?\"},{\"heading\":false,\"text\":\"--Yo soy hija de Abul-Fath-Nazir-el-Ferih, dijo con acento de horror Ketirah.\"},{\"heading\":false,\"text\":\"--Abul-Fath-Nazir, esclamó el mago, amparó en su fuga á Walidé, que te llevaba consigo; Abul-Fath-Nazir, gozó los amores de tu madre y te llamó su hija. Metió contigo una vívora en su seno, porque tú le mataste.\"},{\"heading\":false,\"text\":\"Un grito de horror salió de todas las bocas.\"},{\"heading\":false,\"text\":\"Las palabras del mago, tenian tal autoridad, tal acento de revelacion, que nadie dudó de ellas.\"},{\"heading\":false,\"text\":\"María no pudo resistir á tanto horror, y cayó desmayada en los brazos de Gonzalo.\"},{\"heading\":false,\"text\":\"--¡Salvadla! ¡salvadla! ¡apartadla de este infierno! gritó el mago.\"},{\"heading\":false,\"text\":\"Y obediente á su voz, Ebn-Ismail y Gonzalo cargaron con María, fueron al ajimez, salió por él Gonzalo y descendió por la escala llevando consigo á María desmayada.\"},{\"heading\":false,\"text\":\"El infante Ebn-Ismail, aseguraba la escala.\"},{\"heading\":false,\"text\":\"Abd-el-Rahhaman y Masud fijaban una mirada ansiosa en el ajimez por donde habia desaparecido María.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡mi hija! ¡mi hija! ¡ya no volveré á verla! esclamó Abd-el-Rahhaman avalanzándose al ajimez.\"},{\"heading\":false,\"text\":\"De repente Masud, á quien arrastraba su amor tras María, se avanzó tambien al ajimez, saltó por cima del infante Ebn-Ismail, y se asió á la escala recibiendo una puñalada en el pecho de manos del infante.\"},{\"heading\":false,\"text\":\"Y sin embargo, como si el amor hubiera sido para él una segunda vida, se deslizó por la escala y llegó al pié de ella á tiempo que Gonzalo con María, desmayada aun, montaba á caballo.\"},{\"heading\":false,\"text\":\"Masud montó en el otro caballo que tenia del diestro un esclavo, le arrebató la lanza y siguió á la carrera, tras el caballo de Gonzalo que corria barranco arriba.\"},{\"heading\":false,\"text\":\"Y, ¡cosa estraña! delante del caballo que montaba Masud, corria dando horribles ladridos, el lanudo y gigantesco perro que habia guiado al wali de Algeciras aquella misma noche al albergue donde se ocultaba su hijo.\"}]},{\"title\":\"La torre de la cautiva. — capítulo XXXI\",\"blocks\":[{\"heading\":false,\"text\":\"Cuando el padre y el hijo se retiraron del ajimez, el maldito rey mago habia desaparecido.\"},{\"heading\":false,\"text\":\"Solo quedaba en la cámara Ketirah, pero en un estado horrible.\"},{\"heading\":false,\"text\":\"Estaba replegada en el diván, muda, sombría, con la mirada estraviada, y jadeante.\"},{\"heading\":false,\"text\":\"Tenia en la mano un pomo de oro.\"},{\"heading\":false,\"text\":\"De aquel pomo, salian algunas gotas de un licor verdoso.\"},{\"heading\":false,\"text\":\"--¡Oh! esclamaron á un tiempo su padre y su hermano corriendo hácia ella. ¿Qué has hecho desdichada?\"},{\"heading\":false,\"text\":\"--¡Adúltera! ¡parricida! ¡incestuosa! esclamó con acento terrible, la sultana Ketirah.\"},{\"heading\":false,\"text\":\"El padre y el hijo cayeron de rodillas.\"},{\"heading\":false,\"text\":\"Ketirah, continuó delirando.\"},{\"heading\":false,\"text\":\"--¡La vida! ¡la vida! ¿para que quiero yo esta vida de horror?\"},{\"heading\":false,\"text\":\"¡Maldito sea mi padre, que me abandonó!\"},{\"heading\":false,\"text\":\"¡Maldito sea mi hermano, que puso los ojos en mi hermosura!\"},{\"heading\":false,\"text\":\"Y Abd-el-Rahhaman y Ebn-Ismail, cayeron de rostro contra el suelo y sintieron sobre sí la mano de Dios.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"En vano los esclavos que esperaban á su señor al pie de la torre, esperaron toda la noche; al amanecer, temerosos de ser vistos se retiraron.\"},{\"heading\":false,\"text\":\"La escala quedó pendiente del ajimez.\"},{\"heading\":false,\"text\":\"Pero cuando subieron á la torre, los que entraron en ella, la encontraron abandonada.\"},{\"heading\":false,\"text\":\"El padre y los dos hijos, habian desaparecido.\"},{\"heading\":false,\"text\":\"¿Qué habia sido de ellos?\"},{\"heading\":false,\"text\":\"Nadie volvió á ver mas ni á la sultana Ketirah, ni á Masud-Almoharaví, ni Abd-el-Rahhaman, ni á Ebn-Ismail.\"},{\"heading\":false,\"text\":\"Un profundo misterio habia envuelto su suerte.\"},{\"heading\":false,\"text\":\"En cuanto á la torre, como muchos sabian que en ella habia estado cautiva una doncella cristiana, que habia causado la muerte de Abul-Walid; como habian encontrado pendiente de uno de los ajimeces una escala, y á los pies de la torre las huellas de pisadas de caballos, dióse por segura la fuga de la cautiva cristiana, y por aquella singularidad, llamaron á la torre, y siguen llamándola hasta hoy por tradicion, la torre de la Cautiva.\"},{\"heading\":false,\"text\":\"Algunos pretenden que durante las noches oscuras de invierno, se iluminan con un fuego sombrio los destrozados ajimeces de la torre de la Cautiva; que se vé, cantando lúgubremente sobre ella, una sombra negra envuelta en una nube impura, y que se oyen dentro gemidos y ruido de cadenas.\"},{\"heading\":false,\"text\":\"Nosotros creemos que estas maravillas son hijas de la imaginacion impresionable de los andaluces; bramidos del viento contra la torre, y efectos de la momentánea luz del relámpago que durante la tormenta la iluminan.\"},{\"heading\":false,\"text\":\"Sin embargo, las gentes sencillas creen como en un artículo de fé en la tradicion de la torre de la Cautiva.\"},{\"heading\":false,\"text\":\"¿Pero cómo esplicar la desaparicion de todos los personages del cuento?\"},{\"heading\":false,\"text\":\"Para esplicarla hay que atravesar la parte alta de la Alhambra é ir á buscar otra tradicion en la torre cuyo nombre sirve de título á la leyenda siguiente.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"}]},{\"title\":\"La torre de los siete suelos. — capítulo I\",\"blocks\":[{\"heading\":false,\"text\":\"Si vais á Granada, y en la parte meridional de la Alhambra, veis dos torres rajadas, aportillados los muros, las vides serpeando hasta las almenas, al pie un arroyo, y junto al arroyo flores y árboles; si tropezais en fragmentos desprendidos, en escombros amontonados, aquella parte que veis, teniendo delante un cubo, en que crecen los jaramagos y las malvas locas, y sobre el cubo las dos torres, orladas por una tapia de tierra con aspilleras, y entre las dos torres un muro, y en este muro una puerta tapiada, podeis decir que estais en la torre de los Siete Suelos, entrada principal de la Alhambra en otros dias, y hoy ruina miserable insultada por los hombres y por el tiempo.\"},{\"heading\":false,\"text\":\"Difícilmente puede comprenderse la pasada magnificencia de aquella puerta.\"},{\"heading\":false,\"text\":\"A principios del siglo actual, los franceses, los hijos de ese pueblo ilustradísimo, que vinieron á España con el no menos ilustradísimo, sabio, prepotente colosal Bonaparte, tuvieron el buen gusto de minar la Alhambra y de barrenar sus muros: no podian llevársela como se llevaron otras tantas cosas que aun no han vuelto, y quisieron destruirla; afortunadamente un soldado de los inválidos del castillo, tuvo valor bastante para cortar la mina, pero cuando ya habia volado la magnífica torre del Agua, cuyos vestigios se vén con vergüenza de los civilizadores del mundo en la parte sur de la Alhambra, donde yacen arrojados fragmentos de los muros sobre el barranco. Del mismo modo por la parte de adentro de los muros, junto á la torre de los Siete Suelos, se vé un colosal fragmento de bóveda, surcado por los barrenos, fragmento que debia tener sobre si una inscripcion que dijese:\"},{\"heading\":false,\"text\":\"«No fueron españoles los que esto hicieron, sino los franceses que trajo á España para civilizarla Napoleon el Grande.»\"},{\"heading\":false,\"text\":\"De la misma manera en la torre de los Picos, en la bellísima torre de los Picos, debia escribirse:\"},{\"heading\":false,\"text\":\"«Las balas rasas que dejaron sus señales como se vén en el muro de esa torre, fueron disparadas desde las baterías de la Silla del Moro, por los franceses que acaudillaba el mariscal Sebastiani.»\"},{\"heading\":false,\"text\":\"Y debia añadirse:\"},{\"heading\":false,\"text\":\"«La Alhambra no resistió; esas ruinas fueron hechas con la sola intencion de destruir; las señales de esas balas de treinta y seis, no las recibió en medio del combate la torre de los Picos; los franceses las dispararon inútilmente para destruir la torre, que resistió como un viejo soldado tras su coraza á prueba. La Alhambra tembló bajo la esplosion de las minas, se rajaron sus torres y sus muros, pero resistió, no se destruyó enteramente, como si un génio invisible la hubiera protejido.»\"},{\"heading\":false,\"text\":\"Sin embargo, la torre de los Siete Suelos quedó destrozada, su parte interior y sus adornos volaron, algunos fragmentos de las magníficas enjutas de mármol de su puerta, han parecido ahora entre los escombros, y están en poder de uno de los amigos del autor.\"},{\"heading\":false,\"text\":\"Como si no hubiera sido bastante el bárbaro atentado de los franceses, un dia, durante la última guerra civil, cuando tuvo lugar sobre Castilla y Andalucía la espedicion de Gomez, púsosele en la cabeza á un capitan general de Granada fortificar la Alhambra, y un ingeniero para orlar la torre de los Siete Suelos de una tapia aspillerada, voló su parte superior que los franceses habian rajado.\"},{\"heading\":false,\"text\":\"Ahora, por último, la intendencia de la Casa Real, ha retirado las escasas cantidades destinadas para restaurar la Alhambra; parece, pues, que estraños y propios, montescos y capeletes, han tomado por empresa que la Alhambra desaparezca de sobre la haz de la tierra.\"},{\"heading\":false,\"text\":\"Nosotros al ver esto bajamos la cabeza, y decimos como los árabes:\"},{\"heading\":false,\"text\":\"¡Qué se cumpla lo que esta escrito!\"}]},{\"title\":\"La torre de los siete suelos. — capítulo II\",\"blocks\":[{\"heading\":false,\"text\":\"Pero en los tiempos antiguos, era distinto.\"},{\"heading\":false,\"text\":\"La torre de los Siete Suelos, era una magnífica torre.\"},{\"heading\":false,\"text\":\"Alzaba con altivez sus muros orlados de almenas reales.\"},{\"heading\":false,\"text\":\"Ostentaba los bellos mármoles labrados de su ingreso, y los ajimeces calados del muro, y sus matacanes y sus ladroneras y su ancho cubo, sobre cuya plataforma vagaban los soldados del rey moro.\"},{\"heading\":false,\"text\":\"El sol al salir alumbraba con alegría aquella puerta.\"},{\"heading\":false,\"text\":\"Pero antes del rey Abul-Walid, la torre de los Siete Suelos, no tenia unida á sí la terrible tradicion que con ella vive.\"},{\"heading\":false,\"text\":\"Esta tradicion es sombría.\"},{\"heading\":false,\"text\":\"Dícese que todas las noches, al dar el reloj las doce, sale de la torre un caballero moro, ginete en un caballo blanco sin cabeza, y precedido por un enorme y lanudo perro blanco, que recorren con la rapidez del relámpago los bosques de la Alhambra, y que al espirar la última campanada de las doce, vuelven á la torre y á su último suelo, del que no vuelven á salir hasta la noche siguiente.\"},{\"heading\":false,\"text\":\"Dícese que el que por acaso vé al _Belludo_ y al _Descabezado_ durante su brevísima escursion nocturna, esperimenta una desgracia.\"},{\"heading\":false,\"text\":\"Añádese, que el moro que cabalga en el _Descabezado_ es un espíritu maldito.\"},{\"heading\":false,\"text\":\"Y preguntad á las buenas gentes de los alrededores, si es verdad lo del perro lanudo y lo del caballo sin cabeza, y os contestarán sin vacilar:\"},{\"heading\":false,\"text\":\"--Yo los he visto, una ó mas veces, y me ha acontecido tal ó cual desgracia.\"},{\"heading\":false,\"text\":\"Habia un guarda en los bosques de la Alhambra que se llamaba por apodo _el Coronel_: era un escelente hombre y un escelente cazador, y vivia en una cueva casi frente por frente de la torre de los Siete Suelos.\"},{\"heading\":false,\"text\":\"Una mañana de invierno el autor subió á la Alhambra.\"},{\"heading\":false,\"text\":\"Hacia un hermoso dia; pero la noche anterior habia sido una noche de tormenta.\"},{\"heading\":false,\"text\":\"El autor encontró al _Coronel_ sentado tristemente al sol, en el poyo de piedras que habia junto á la puerta de la cueva.\"},{\"heading\":false,\"text\":\"--Eh, _Coronel_, le dijo; buenos dias: ¿qué hace Vd. ahí tan triste y tan cariacontecido?\"},{\"heading\":false,\"text\":\"--¡Ay, señor de mi alma! me contestó: anoche, cuando mas arreciaba el temporal, me dieron tentaciones de salir, porque de estas noches se valen los matuteros[89], y abrí la puerta á punto que daban las doce: el _Belludo_ y el _Descabezado_ pasaron junto á mí como alma que lleva el diablo.\"},{\"heading\":false,\"text\":\"--¡Bah! le dije: estaría Vd. medio dormido.\"},{\"heading\":false,\"text\":\"--¡Cá! no señor: hace diez años los ví otra noche, y al dia siguiente murió mi muger.\"},{\"heading\":false,\"text\":\"--¿Y qué desgracia le ha sucedido á Vd. ahora?\"},{\"heading\":false,\"text\":\"--¡Se me ha muerto la lebrela!\"},{\"heading\":false,\"text\":\"Cuando un hombre habla con tanta fé, no hay mas recurso que oir y callar.\"},{\"heading\":false,\"text\":\"Es pues, una tradicion reconocida, creida como un hecho indudable la existencia en la torre de los Siete Suelos de la Alhambra de un caballo sin cabeza y de un perro con muchas lanas.\"},{\"heading\":false,\"text\":\"En cuanto á los Siete Suelos misteriosos no están en la torre, sino en el cubo semicircular de defensa que está situado delante de la torre[90].\"},{\"heading\":false,\"text\":\"Uno de estos suelos es una galería semicircular, en la cual de trecho en trecho hay una especie de nicho profundo y abocinado que atraviesa el muro, en cuya parte esterior hay una piedra con una abertura obalada y sobre ella una cruz calada.\"},{\"heading\":false,\"text\":\"Aquellos nichos estaban destinados á los escuchas.\"},{\"heading\":false,\"text\":\"En el pavimento, y tambien de trecho en trecho, hay aberturas cuadradas, respiraderos sin duda, de las galerías inferiores.\"},{\"heading\":false,\"text\":\"Cuando se arroja una piedra por uno de aquellos respiraderos, se la siente caer retumbando, como en una sima.\"},{\"heading\":false,\"text\":\"En cuanto á los Siete Suelos, estando cegada la escalera que conducia al tercero, nada puede asegurarse.\"},{\"heading\":false,\"text\":\"Pero cuentan los viejos, que cuando aquellas escaleras no estaban cegadas se bajaba bien al tercer suelo, pero que en el cuarto la atmósfera era espesa; que en el quinto no se podia ya respirar, que se apagaban las luces, por bien preparadas que fuesen, y por último, que los que se habian atrevido á llegar hasta la escalera que conducia al sesto piso, habian oido un estruendo sordo y pavoroso, y se habian vuelto aterrados.\"},{\"heading\":false,\"text\":\"Quede consignado, pues, que en Granada se cree en el _Belludo_ y el _Descabezado_ de la torre de los Siete Suelos; que se cree dominada la torre por un encanto, y que nadie ha bajado ni podria bajar hasta el sétimo suelo.\"},{\"heading\":false,\"text\":\"Veamos ahora la tradicion mora.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo III\",\"blocks\":[{\"heading\":false,\"text\":\"Allá por los tiempos en que los árabes emprendieron su conquista sobre España, en el sitio donde ahora se levanta la torre de los Siete Suelos, dicen que habia una sima profundísima, en cuya parte interior, naciendo en su borde, se torcia un estrecho, escarpado y peligroso sendero.\"},{\"heading\":false,\"text\":\"Una tarde, á tiempo que el sol trasponia, apareció entre los montes un caballo que llevaba sobre sí una dama.\"},{\"heading\":false,\"text\":\"Aquella dama era negra, pero hermosa, como la reina de Saba; llevaba los cabellos sueltos y desordenados, vestida una flotante y larga túnica de púrpura, y en el cuello y en los brazos, collar y brazaletes de gruesas perlas.\"},{\"heading\":false,\"text\":\"El caballo era blanco é iba en pelo.\"},{\"heading\":false,\"text\":\"Solo tenia un freno de oro y riendas de oro tambien, con las que le regia la dama.\"},{\"heading\":false,\"text\":\"Aquella dama, en la inquietud de la mirada de sus negros ojos, en la sobreescitacion de su alto seno y en el ardiente álito que emanaba de su boca purpúrea y entreabierta, se comprendia que estaba amenazada de un grave peligro, y en la precipitacion con que lanzaba su caballo á través del tortuoso sendero abierto entre el enmarañado bosque que entonces cubria la Colina Roja, la Silla del Moro y el Cerro del Sol, demostraba claro que huia.\"},{\"heading\":false,\"text\":\"Apenas habia la dama llegado al barranco que hoy se llama Peña-Partida, y que está ya próximo al lugar donde hoy se levanta la torre de los Siete Suelos, y donde antes existia la sima que hemos citado, cuando se oyeron roncos ladridos y apareció por el mismo lugar por donde habia llegado la dama, un enorme perro blanco de montería.\"},{\"heading\":false,\"text\":\"Al sentir sus ladridos, la dama se estremeció, y aguijó su caballo que partió por el descenso del barranco, y se dirijió como una flecha al borde de la sima.\"},{\"heading\":false,\"text\":\"Al verle la dama, dió un grito de horror y se arrojó del caballo al suelo, quedando desmayada por la violencia del golpe, junto al borde de la sima.\"},{\"heading\":false,\"text\":\"El caballo se lanzó en ella y desapareció, produciendo con su caida un ruido sordo, terrible, atronador, en las profundidades lóbregas de aquel agujero horrible.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo IV\",\"blocks\":[{\"heading\":false,\"text\":\"La dama habia quedado suspendida entre los espinos sobre el abismo; el perro llegó al borde, asió con los dientes su túnica y la sacó fuera.\"},{\"heading\":false,\"text\":\"Entretanto llegó un hombre, y dió un puntapié al perro que se hizo atrás, y enseñó sus dientes amenazadores al hombre aquel, pero no le acometió.\"},{\"heading\":false,\"text\":\"Aquel hombre tenia un aspecto terrible.\"},{\"heading\":false,\"text\":\"Era su frente de color cobrizo, su cabellera bermeja, casi roja, como si se la hubiera teñido con sangre, y tan áspera que sus cabellos, mas que cabellos parecian cerdas: del mismo modo, su barba prolongada, revuelta, era áspera y roja, y cubria de tal modo su semblante, que apenas se le veian las narices anchas y romas, y dos ojillos grises, pero móviles, duros, feroces, de espresion cruel y perversa: de su boca y por cima de la revuelta barba, se veian salir cruzados cuatro colmillos blancos y agudos: era de estatura atlética, de miembros fornidos y cobrizos, estaba desnudo y descalzo, y solo cubria una parte de su cuerpo una especie de taparrabo negro de una tela de lana tosca: de la cintura de esta prenda, colgaba un hacha enorme con un astil de hierro muy corto; llevaba á la espalda un arco de fresno largo y poderoso, atravesadas en la especie de cinturon de que pendia el hacha, como hasta una docena de flechas, y se apoyaba en una pica corta y gruesa de roble, en una especie de chuzo, en cuyo estremo superior se veia enhastado un ancho y reluciente hierro de dos filos.\"},{\"heading\":false,\"text\":\"Habia cerrado la noche.\"},{\"heading\":false,\"text\":\"Una luna pálida, opaca, lanzaba un resplandor turbio, sombrío, impuro, casi rojo, en el claro del bosque, en el centro del cual, se abria la boca de la sima.\"},{\"heading\":false,\"text\":\"Aquella luz fantástica, pavorosa en el centro de un bosque solitario, sin oirse otro ruido que el del viento que zumbaba desapacible y frio entre las encinas; aquella dama negra desmayada, aquel hombre singular, bravío, de aspecto feróz, que la contemplaba con una alegria repugnante, y aquel perro sentado, con su enorme estatura, sus larguísimas lanas blancas, y sus ojos amenazadores y relucientes fijos en el hombre, eran un cuadro estraño tras el cual como que se adivinaba una historia sombría y terrible.\"},{\"heading\":false,\"text\":\"De repente, y cuando el hombre rojo se inclinaba sobre la hermosa dama negra, los ecos del bosque repitieron el sonido atronador de una bocina.\"},{\"heading\":false,\"text\":\"A aquel sonido, el hombre rojo se irguió, arrojó á sus pies la pica, se quitó el arco de la espalda, le templó, armó en él una flecha, y miró con fiereza al sitio de donde habia provenido el son de la bocina.\"},{\"heading\":false,\"text\":\"Retumbó un segundo toque mas cercano: el salvage entezó el arco, y esperó aun.\"},{\"heading\":false,\"text\":\"Por tercera vez, y ya á muy poca distancia, se oyó el sonido de la bocina, y apareció una forma humana entre la primera línea de los árboles.\"},{\"heading\":false,\"text\":\"Entonces el hombre rojo estendió el arco, le forzó y dejó ir la cuerda, y una flecha partió silvando, y fué á rebotar como sobre en una roca, en el bulto que adelantaba, que se precipitó á la carrera por la vertiente, de la colina, y llegó al fin al lugar donde estaban el hombre rojo, la dama desmayada y el perro.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo V\",\"blocks\":[{\"heading\":false,\"text\":\"El hombre nuevamente aparecido, venia completamente armado por un arnés negro y reluciente.\"},{\"heading\":false,\"text\":\"Bajo su casco sin visera, redondo y liso, sin adorno alguno, se veia un semblante blanco, hermoso, melancólico, con unos grandes y lucientes ojos negros.\"},{\"heading\":false,\"text\":\"Pero en el fondo de aquellos ojos habia algo que causaba espanto.\"},{\"heading\":false,\"text\":\"El hombre rojo y el de la armadura negra, se miraron fijamente y en silencio, durante algunos segundos, pero con un odio infinito.\"},{\"heading\":false,\"text\":\"--Te has valido de tus malas artes, y de la amistad que tienes con el diablo, Kaibar, por robar del alcázar del rey Al-bahul, á la hermosa Zairah, dijo el de la armadura negra; pues bien, has trabajado para mí; porque voy á matarte, y despues nadie me preguntará por Zairah, á quien amo.\"},{\"heading\":false,\"text\":\"--¿Y dónde has visto tú á Zairah, Jacub? esclamó con voz ronca y sarcástica Kaibar.\"},{\"heading\":false,\"text\":\"--Me la ha mostrado en sueños el espíritu que me ayuda.\"},{\"heading\":false,\"text\":\"--¿Y cómo sabias tú que existia Zairah?\"},{\"heading\":false,\"text\":\"--Un dia estaba triste, muy triste; dijo Jacub, sentándose sobre una de las asperezas del borde de la sima con la misma tranquilidad que si no hubiera tenido delante un enemigo: velaba yo, apoyado en las almenas en la torre grande de la alcazaba de Cairvan[91]: brillaba como ahora la luna triste y sombría.\"},{\"heading\":false,\"text\":\"Y mi alma estaba envuelta en tinieblas.\"},{\"heading\":false,\"text\":\"--¡Por qué, dije levantando los ojos al cielo, por qué, grande y poderoso Allah, conturbas mi espíritu y le sumerges en sombra!\"},{\"heading\":false,\"text\":\"¿No soy yo hijo del poderoso rey Al-Bahul, el de los ojos de diamante y la barba de oro? ¿No tengo riquezas y esclavos, soldados invencibles, y corazon valiente que no se estremece ante el peligro? ¿Por qué, pues, mi corazon arde en un deseo misterioso como si encerrase un volcán?\"},{\"heading\":false,\"text\":\"Apenas habia pronunciado estas palabras, cuando sonó en mi oido una música regalada, que parecia venir de muy lejos, pero que, sin embargo, yo oia como si sonase junto á mí.\"},{\"heading\":false,\"text\":\"Aquella música parecia provenir de las cuerdas de oro de una guzla, y poco despues la acompañó una voz dulce, dulcísima, que resonó en mi corazon como el arrullo de la tórtola en los oidos de su compañera enamorada.\"},{\"heading\":false,\"text\":\"¡Oh! esclamé al ver que aquella voz templaba el fuego de mi corazon como una dulce lluvia de rocio: ya sé lo que deseo; ya sé lo que siento; yo amo á esa vírgen que canta.\"},{\"heading\":false,\"text\":\"--¿Y qué cantaba la vírgen? dijo con ronca voz el salvage.\"},{\"heading\":false,\"text\":\"--Cantaba un romance muy triste, contestó Jacub.\"},{\"heading\":false,\"text\":\"--¿Y te acuerdas de él? repuso Kaibar.\"},{\"heading\":false,\"text\":\"--Quedó fijo en mi memoria, como el bote de una lanza de Damasco queda señalado sobre una adarga de Kufa.\"},{\"heading\":false,\"text\":\"--Yo quiero oir ese romance, dijo Kaibar, que cediendo á una especie de fascinacion estraña desarmó su arco y se sentó frente á Jacub.\"},{\"heading\":false,\"text\":\"Zairah desmayada aun, estaba entre los dos.\"},{\"heading\":false,\"text\":\"El lanudo perro, tomando parte en aquella escena, miraba alternativamente al uno y al otro.\"},{\"heading\":false,\"text\":\"--Sí, yo quiero oir ese romance, repitió Kaibar.\"},{\"heading\":false,\"text\":\"--Pues óyelo, dijo Jacub.\"},{\"heading\":false,\"text\":\"Y empezó de este modo con voz lenta y cadenciosa.\"},{\"heading\":false,\"text\":\"Libres los vientos--zumbando vagan; libres navegan--las nubes blancas, del firmamento--la azul campaña; libres batiendo--las leves alas las golondrinas--besan las aguas, del ancho lago--que riza el aura; libres las ondas--la curva playa, amantes orlan--de espumas cándidas; las mariposas--engalanadas ora revuelan,--ora se paran, entre las flores--de mi ventana, y yo entretanto--me miro esclava, me cercan muros,--puertas me guardan, y en mis megillas--el sol vé lágrimas, cuando aparece--por la mañana, y aun vé mis ojos--que el llanto empaña cuando á los mares--cansado baja.\"},{\"heading\":false,\"text\":\"Calló Jacub, y Kaibar que le habia escuchado atentamente, le dijo:\"},{\"heading\":false,\"text\":\"--¿Y qué hiciste despues de oir ese cantar?\"},{\"heading\":false,\"text\":\"--Me pareció que mi alma entera se habia trasladado al lugar desconocido de donde parecia haber venido aquel canto; conoci que la tristeza que antes me aquejaba era una tristeza de amor.\"},{\"heading\":false,\"text\":\"--¿Y amaste?\"},{\"heading\":false,\"text\":\"--¡Con toda mi alma!\"},{\"heading\":false,\"text\":\"--¿Y conociste á la virgen de tu amor?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Y era ella? dijo Kaibar señalando con un ademán enérgico á la dama que aun estaba desmayada.\"},{\"heading\":false,\"text\":\"--Sí, era Zairah, dijo Jacub: con la diferencia de que cuando yo la conocí era blanca como un rayo de la luna, y cuando me dió su amor, cuando fué mia, cuando apuré en sus brazos la sed de mi amor, su tornó negra.\"},{\"heading\":false,\"text\":\"--¡Qué ha sido tuya Zairah! esclamó Kaibar levantándose demudado y feróz, y empuñando de nuevo su arco.\"},{\"heading\":false,\"text\":\"Jacub se levantó y miró con desprecio al salvage.\"},{\"heading\":false,\"text\":\"--¡Vete! le dijo; eres una bestia feróz, Kaibar.\"},{\"heading\":false,\"text\":\"--O me dejas á Zairah, ó tu vida, esclamó el salvage haciéndose atrás y armando de nuevo la flecha en el arco.\"},{\"heading\":false,\"text\":\"--¡Vete! repitió Jacub, ¡vete! y no me obligues á matarte.\"},{\"heading\":false,\"text\":\"El salvage palideció de cólera, entezó su arco, y disparó.\"},{\"heading\":false,\"text\":\"Pero la flecha rebotó en el coselete de Jacub, que se lanzó furioso sobre el salvage y le estrechó entre sus brazos.\"},{\"heading\":false,\"text\":\"Parecia que Kaibar debia ahogar entre los suyos á Jacub: tanto, al parecer, le aventajaba en fuerzas.\"},{\"heading\":false,\"text\":\"Pero no sucedió así.\"},{\"heading\":false,\"text\":\"Como si la armadura de Jacub hubiese tenido vida, fuerza y voluntad, aquella negra y reluciente armadura se movia, estrechaba, sofocaba al salvage.\"},{\"heading\":false,\"text\":\"--¡Oh! tú tambien tienes pacto con Satanás, dijo Kaibar, y Satanás te protege, esclamó redoblando sus esfuerzos.\"},{\"heading\":false,\"text\":\"Pero en aquel momento, Jacub levantó su brazo armado con su puñal y le sepultó por tres veces en el pecho del salvage: á la primera puñalada, los brazos de este dejaron de oprimir á Jacub; á la segunda se doblegó; á la tercera cayó rebotando en la sima, impulsado vigorosamente por Jacub.\"},{\"heading\":false,\"text\":\"El perro lanzó un gruñido horrible y se puso á lamer la sangre de Kaibar que habia quedado entre las piedras.\"},{\"heading\":false,\"text\":\"En aquel momento volvió en sí Zairah.\"},{\"heading\":false,\"text\":\"Ningun vestigio habia quedado del crímen. Kaibar habia desaparecido en la sima; el perro habia lamido su sangre; Jacub habia arrojado al abismo su puñal.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo VI\",\"blocks\":[{\"heading\":false,\"text\":\"Para que nuestros lectores puedan comprender con claridad la leyenda que otros nos contaron, y que nosotros contamos á nuestra vez, necesitamos dejar á Jacub, á Zairah y al perro, al borde de la sima donde mas adelante se construyó la torre de los Siete Suelos, é ir á buscar la historia de un rey de Africa.\"},{\"heading\":false,\"text\":\"Este rey se llamaba Yaks-Al-Baul.\"},{\"heading\":false,\"text\":\"Este rey no habia nacido de príncipe.\"},{\"heading\":false,\"text\":\"Por el contrario, no se sabia quienes fueron sus padres.\"},{\"heading\":false,\"text\":\"Un dia le encontraron unos cazadores de leones de Tánger, en un antro en el momento en que le amamantaba una leona al par que á un estraño cachorro.\"},{\"heading\":false,\"text\":\"La leona fué muerta, y Yaks-Al-Baul y el cachorro llevados como testimonio de un milagro, al gran faquí de la mezquita mayor de Tánger.\"},{\"heading\":false,\"text\":\"Yaks era un muchacho bermejo como las guedejas de su nodriza, y de mirada feróz como ella, y muy robusto y crecido.\"},{\"heading\":false,\"text\":\"El cachorro tenia tanto de perro como de leon, y era horrible.\"},{\"heading\":false,\"text\":\"El faquí, que era un grande astrólogo, recibió al niño y al perro; oyó atentamente la relacion de los cazadores, y cuando se quedó solo se puso á consultar sus cuadrantes y sus astrolabios.\"},{\"heading\":false,\"text\":\"Comprendió al fin, por lo que sus primeras tentativas astrológicas le revelaron, que nada sabria si no evocaba al diablo.\"},{\"heading\":false,\"text\":\"Estremecióse el bueno de Almedí, porque era religioso y justo, y no le gustaba tratar con los espíritus condenados; pero con la intencion de servir á Dios, se subió á una torrecilla de su casa y conjuró á Satanás.\"},{\"heading\":false,\"text\":\"Apenas habia pronunciado su conjuro, cuando oyó un zumbido sordo y tenáz y vió un moscardon negro y reluciente que habia entrado por la ventana y volaba alrededor de su cabeza.\"},{\"heading\":false,\"text\":\"--En el nombre de Dios altísimo y único, dijo Almedí, ¿eres tú el arcángel rebelde?\"},{\"heading\":false,\"text\":\"--Yo soy, contestó una voz que zumbaba como el vuelo del moscardon.\"},{\"heading\":false,\"text\":\"--¿Y por qué te me presentas en esa forma?\"},{\"heading\":false,\"text\":\"--Porque es la mas á mano que he encontrado.\"},{\"heading\":false,\"text\":\"--Eres mi esclavo.\"},{\"heading\":false,\"text\":\"--Ya lo sé: has pronunciado el conjuro mas terrible de Salomon.\"},{\"heading\":false,\"text\":\"--Toma otra forma, dijo Almedí.\"},{\"heading\":false,\"text\":\"--Esa es una tiranía inútil que le puede costar cara, contestó el maldito.\"},{\"heading\":false,\"text\":\"--Toma otra forma, repitió con doble imperio Almedí.\"},{\"heading\":false,\"text\":\"--Sea, pues que tú lo quieres.\"},{\"heading\":false,\"text\":\"Y no solo tomó otra forma el diablo, sino que la tomó tambien el interior de la torrecilla donde estaba Almedí.\"},{\"heading\":false,\"text\":\"Este vió, primero, una dama hermosa sobre toda ponderacion, engalanada sobre todo encarecimiento, que fijaba en él una mirada enamorada, dulce capaz de volver locos á cien faquíes ascéticos: la habitacion se habia trasformado en un retrete dorado, matizado, resplandeciente, adornado con divanes, con lámparas, con alfombras, como no habia visto ningun Almedí.\"},{\"heading\":false,\"text\":\"El bueno del faquí, en cuanto vió aquella hermosísima niña con sus sedosos cabellos negros sueltos en largos y anchos rizos sobre los desnudos hombros; la rica y doble gargantilla de perlas que rodeaba su cuello de blancura deslumbradora y descansaba sobre un seno medio descubierto; los encantos irresistibles que se veian á través de la magnífica y descuidada túnica, se olvidó de los dos engendros que le habian llevado los cazadores de leones y del deseo de saber su historia. Y sin embargo, la hermosísima jóven tenia en los brazos al pequeño hombre-fiera de cabellos y ojos de leon, y á sus pies, echado en el diván de seda y oro, al estraño animal, monstruosa mezcla de la deformidad del leon y del perro.\"},{\"heading\":false,\"text\":\"Y aquella niña, ó por mejor decir, el diablo, acariciaba á los dos pequeñuelos, y al recibir sus caricias, el niño lloraba y el perro ahullaba.\"},{\"heading\":false,\"text\":\"--¡Eh! ¿qué tal te parezco? dijo el diablo con una voz tan cavernosa, tan estridente, de acento tan cruelmente burlon, que no parecia sino que lo pronunciaba otra persona detrás de la jóven.\"},{\"heading\":false,\"text\":\"--Vete, dijo el faquí creyendo que el diablo se habia escondido tras de la hermosa niña que ocupaba el diván.\"},{\"heading\":false,\"text\":\"Al pronunciar Almedí su mandato, hermosa, diván y retrete desaparecieron, y solo quedaron el niño llorando y el perro ahullando.\"},{\"heading\":false,\"text\":\"Pero Almedí habia perdido su alma.\"},{\"heading\":false,\"text\":\"Se habia enamorado frenéticamente de Satanás, ó lo que era lo mismo, aunque él no lo sabia, de la hermosa doncella.\"},{\"heading\":false,\"text\":\"Y la llamó á voces, descompuesto el semblante, temblándole la larga barba.\"},{\"heading\":false,\"text\":\"Una carcajada mugeril, pero dulce, incitante, tentadora, le contestó.\"},{\"heading\":false,\"text\":\"Almedí corrió al ángulo de la torrecilla donde habia resonado aquella carcajada con los brazos estendidos creyendo que el diablo habia hecho invisible á la hermosa dama.\"},{\"heading\":false,\"text\":\"Pero al llegar á aquel ángulo donde nada encontró, en el ángulo opuesto resonó otra carcajada mas dulce, mas sonora, mas incitante.\"},{\"heading\":false,\"text\":\"El diablo jugaba con Almedí al esconder, y entretanto el pequeño hombre-fiera y el aborto de perro y leon acrecian en su llanto y sus engruñados.\"},{\"heading\":false,\"text\":\"Tenian hambre.\"},{\"heading\":false,\"text\":\"Despues de algun tiempo de inútil lucha, el faquí se sentó en medio de la habitacion agotadas sus fuerzas.\"},{\"heading\":false,\"text\":\"Inclinó la cabeza sobre sus rodillas, cerró los ojos y alimentó el recuerdo de aquella hermosísima vision que habia desaparecido.\"},{\"heading\":false,\"text\":\"Y recordando, vino á recordar que aquella vision se le habia presentado á causa de su conjuro al diablo.\"},{\"heading\":false,\"text\":\"Y como ardia en deseos de volver á ver á aquella seductora doncella, volvió á conjurar á Satanás.\"},{\"heading\":false,\"text\":\"Entonces un sapo negro y verde, como si hubiera caido del techo, cayó sobre la halda de la túnica de lana blanca del faquí y se puso á mirarle frente á frente.\"},{\"heading\":false,\"text\":\"--¿Eres tú, Satanás? dijo Almedí.\"},{\"heading\":false,\"text\":\"--Yo soy, dijo una voz atronadora que no se podia concebir saliese del cuerpo del sapo.\"},{\"heading\":false,\"text\":\"--¿Por qué has tomado esa figura? dijo Almedí.\"},{\"heading\":false,\"text\":\"--¿Qué, no soy yo dueño de tomar la figura que mas me agrade? ¿No dices tú en tus sermones en la grande aljamia: Buenos creyentes, temerosos de Dios; cuando entre en vuestra casa un moscon negro y reluciente, zumbando, zumbando, orad á Dios á fin de ahuyentarle, porque ese moscon es el diablo que viene á susurrar en vuestros oidos palabras de perdicion: cuando veais junto á una fuente un sapo negro y verde, aunque os aqueje la sed no bebais, porque aquel sapo será el diablo que habrá escupido en el agua, y si bebeis os hará suyo? ¿Por qué te quejas, pues, de que yo tome las dos figuras que tú me has supuesto?\"},{\"heading\":false,\"text\":\"--Hazme ver á la doncella blanca de los ojos negros, dijo Almedí, que á duras penas habia tenido paciencia para escuchar la réplica del diablo.\"},{\"heading\":false,\"text\":\"--No quiero, dijo éste; eres un viejo ridículo: ¿qué se ha hecho de tu santidad? Eva la ha desvanecido como el sol desvanece la niebla.\"},{\"heading\":false,\"text\":\"--¿Se llama Eva la doncella hermosa?\"},{\"heading\":false,\"text\":\"--Eva es la muger, ó por mejor decir, el conjunto de tentaciones de todas las mugeres.\"},{\"heading\":false,\"text\":\"--Pues bien, que aparezca Eva.\"},{\"heading\":false,\"text\":\"--Quiero ser generoso contigo; renuncio á tu posesion; no quieras ver á Eva, pues que si la vés eres mio.\"},{\"heading\":false,\"text\":\"--¿Pues no era Eva la que he visto?\"},{\"heading\":false,\"text\":\"--Era Eva, despues de haber hablado conmigo, la Eva del pecado y de la impureza; la que perseguia á Adan por los bosques del paraiso perdido, poniéndose entre él y Dios.\"},{\"heading\":false,\"text\":\"--Mientes; en tiempo de Eva, no se habia descubierto el oro, ni las perlas, ni existia Cachemira, ni Kufa, ni Damasco.\"},{\"heading\":false,\"text\":\"--Pero existen hoy, y yo he vestido á Eva como he querido. Estos sábios son insufribles: ¿si sabré yo lo que me hago?\"},{\"heading\":false,\"text\":\"--No, no lo sabes, porque te estoy pidiendo que me presentes ante los ojos á Eva, y resistes.\"},{\"heading\":false,\"text\":\"--Porque tengo lástima de tí, pobre tonto.\"},{\"heading\":false,\"text\":\"--Me obligarás á que pronuncie de nuevo el conjuro.\"},{\"heading\":false,\"text\":\"--No, no lo hagas, porque el sonido de ese conjuro me hace padecer horriblemente; pero ya que me obligas, voy á vengarme de tí: mira.\"},{\"heading\":false,\"text\":\"Sintió Almedí un sonido semejante al de una tienda de tela sútil y crugiente que se desplegase sobre su cabeza.\"},{\"heading\":false,\"text\":\"Y en efecto, una tienda se habia desplegado.\"},{\"heading\":false,\"text\":\"Tienda tegida de hilos sútiles y resplandecientes de mil colores como los rayos del sol que pasan por la lluvia: compartidos estos colores en labores caladas, en sútiles mallas que dejaban ver una luz resplandeciente, pero de una manera dulcísima, grata sobre todos los alhagos á los sentidos. Sostenian la tienda columnas en que no se veian mas que los resplandores de las piedras preciosas de que estaban cuajadas, y que giraban incesantemente, pareciendo un raudal purísimo que subia del pavimento.\"},{\"heading\":false,\"text\":\"Y aquel pavimento era un relumbrante alicatado (mosáico) de diamantes, de rubíes, de carbunclos, de esmeraldas, de topacios, de amatistas, de perlas negras y de perlas blancas, de cuantas preciosidades encerró Dios en las entrañas de la tierra y en las profundidades de los mares.\"},{\"heading\":false,\"text\":\"Y en medio del pavimento habia una fuente labrada de un solo diamante, y de la fuente surgía un agua clarísima y tan olorosa, tan rica de ambrosía como los manantiales del paraiso donde apagará su sed el justo toda una eternidad con sola una vez que beba una sola gota.\"},{\"heading\":false,\"text\":\"Y mas allá de la fuente, tendida en un lecho cándido y resplandeciente como la luna, habia una muger, mas hermosa que todas las hermosuras de la tierra, mas resplandeciente que la tienda en que se encontraba, y casta y pura como el pensamiento de un niño que murmura las primeras palabras con que su madre procura encaminar su espíritu á Dios.\"},{\"heading\":false,\"text\":\"Y tenia los cabellos, las cejas y las pestañas tan negros, que junto á ellos hubieran parecido blancas las alas de un cuervo de Egipto.\"},{\"heading\":false,\"text\":\"Y eran sus megillas como los arreboles del sol de la mañana.\"},{\"heading\":false,\"text\":\"Y era su carne tan blanca, que junto á ella hubiera parecido negra la nieve de las cumbres donde no se posa planta humana.\"},{\"heading\":false,\"text\":\"Y una túnica riquísima pero trasparente aumentaba los hechizos de aquella imágen de la muger que Dios crió para que fuese como la sultana de las huríes, para hacer feliz á Adan en el paraiso.\"},{\"heading\":false,\"text\":\"Era la imágen de Eva antes del pecado.\"},{\"heading\":false,\"text\":\"Almedí cayó de rostro sobre el pavimento con el alma abrasada en un fuego impuro, y adoró á Satanás en la imágen de Eva.\"},{\"heading\":false,\"text\":\"El niño-fiera, y el cachorro de perro y de leon, el uno entre los brazos y el otro á los pies de la Eva maldita, lloraban, gritaban, ahullaban, rugian con mas fuerza que nunca.\"},{\"heading\":false,\"text\":\"--Levántate, dijo la ronca y temerosa voz del diablo. Eres ya mio; pero quiero concederte un medio de volver á tu libertad. Voy á decirte en una historia, en la historia de esos dos hermanos, á dónde pueden llevar á una criatura el olvido de Dios por la muger, y por los impuros placeres de un amor idólatra.\"},{\"heading\":false,\"text\":\"--Dame á Eva, replicó Almedí.\"},{\"heading\":false,\"text\":\"--Te la daré, si me la pides despues de haber escuchado la historia de esos dos hermanos, y señaló al niño y al perro.\"},{\"heading\":false,\"text\":\"--Dame á Eva.\"},{\"heading\":false,\"text\":\"--Escucha.\"},{\"heading\":false,\"text\":\"Y dominado por un poder oculto y misterioso, Almedí con los ojos fijos en la imágen de Eva, sentado sobre sus rodillas, inmóvil, pálido, atento, escuchó.\"},{\"heading\":false,\"text\":\"Y el diablo le contó una historia.\"},{\"heading\":false,\"text\":\"Y la historia era esta.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo VII\",\"blocks\":[{\"heading\":false,\"text\":\"Hay allá, en las tierras de occidente, una tierra fértil, de cielo radiante, cubierta de flores y de verdor.\"},{\"heading\":false,\"text\":\"La guardan sierras que la dan su nieve en claros raudales; la surcan rios que fertilizan sus praderas, y sobre la vega y sobre sus montes se ven alquerías blancas y torres bermejas.\"},{\"heading\":false,\"text\":\"Esta tierra, paraiso del mundo, jardin de delicias, huerto de amores, bendita y riente, guardada por Dios para los mas valientes y fervorosos de sus escogidos, estaba entonces en poder de unos cristianos, nietos de unos bárbaros que habian venido á las regiones del mediodia, desde las regiones donde jamás se derrite el hielo.\"},{\"heading\":false,\"text\":\"Aquellos cristianos eran los visigodos.\"},{\"heading\":false,\"text\":\"Corria el año de seiscientos sententa y cuatro.\"},{\"heading\":false,\"text\":\"Era rey de los visigodos Wamba.\"},{\"heading\":false,\"text\":\"Wamba, á quien habian obligado á ser rey.\"},{\"heading\":false,\"text\":\"Este rey era muy bravo.\"},{\"heading\":false,\"text\":\"En los primeros tiempos de su reinado subleváronse algunos de sus mas poderosos vasallos; pero Wamba fué sobre ellos, los venció y les puso en temor y respeto de su nombre.\"},{\"heading\":false,\"text\":\"Entre estos grandes, habia uno que se llamaba Ervigio.\"},{\"heading\":false,\"text\":\"Era mancebo y hermoso á maravilla, y tenia tanta soberbia como hermosura.\"},{\"heading\":false,\"text\":\"Era pariente del pasado rey Recesvinto, y aunque no se atrevia á declarar abiertamente sus intentos, alentaba esperanzas de ser rey y se procuraba en secreto parciales.\"},{\"heading\":false,\"text\":\"Pero luchaba con el temor que imponia la bravura de Wamba, y andaba desalentado y triste.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo VIII\",\"blocks\":[{\"heading\":false,\"text\":\"Una tarde de primavera, Ervigio se paseaba solo por las huertas del Tajo, á los pies de la altura donde se asienta Toledo.\"},{\"heading\":false,\"text\":\"Iba pensativo, pensando en como haria para arrebatar á Wamba su corona y ceñirla á su cabeza.\"},{\"heading\":false,\"text\":\"El sol trasponia.\"},{\"heading\":false,\"text\":\"Ervigio se alejaba por la orilla del rio.\"},{\"heading\":false,\"text\":\"De repente tropezó en un objeto, y oyó una voz áspera que se quejaba.\"},{\"heading\":false,\"text\":\"Ervigio habia tropezado con un hombre, que estaba sentado al borde de una roca sobre el rio, con una caña de pescar en la mano.\"},{\"heading\":false,\"text\":\"Aquel hombre era muy singular, tan pequeño que apenas llegaba á la cintura de Ervigio, jorobado, patizambo, tuerto y viejo.\"},{\"heading\":false,\"text\":\"Alzóse al ser tropezado en ademán amenazador y puso mano ferozmente á su puñal y se encogió como el tigre para dar el salto sobre su presa.\"},{\"heading\":false,\"text\":\"Ervigio puso mano á su espada.\"},{\"heading\":false,\"text\":\"Pero al verle el enano, se amansó, envainó su puñal, sonrió horriblemente, arrojó su caña al rio, y dijo con acento singular entre burlon y cruel.\"},{\"heading\":false,\"text\":\"--He aquí que el rio no me ha dado ni un solo pececillo, pero la tierra me ha dado una buena pesca. Yo te esperaba.\"},{\"heading\":false,\"text\":\"--¿Qué me esperabas?\"},{\"heading\":false,\"text\":\"--Sí, ella me habia dicho: el dia en que te sentares en la roca, y echares tu anzuelo al rio y no sacares del agua peces, desde que el sol salga hasta que se ponga, aquel dia habrás encontrado al que mi alma adora.\"},{\"heading\":false,\"text\":\"--¡Ah! dijo Ervigio; ¿esa profecía te la habia hecho conocer una muger?\"},{\"heading\":false,\"text\":\"--Sí, poderoso y afortunado señor, una vírgen hermosa.\"},{\"heading\":false,\"text\":\"--Déjame continuar mi camino, dijo Ervigio, que como estaba poseido de la ambicion, rechazaba al amor.\"},{\"heading\":false,\"text\":\"Pero el enano no se apartó del sendero.\"},{\"heading\":false,\"text\":\"--El sol se ha puesto y no he sacado del rio ni el mas pequeño pececillo; tú eres, pues, el mancebo á quien ella ama, yo te esperaba, has venido y yo te he hallado, rey de los godos.\"},{\"heading\":false,\"text\":\"--¡Rey de los godos! esclamó Ervigio.\"},{\"heading\":false,\"text\":\"--Sí, tú serás rey por el amor de ella. Sígueme.\"},{\"heading\":false,\"text\":\"Y el enano saltó de la roca abajo á la selva, y Ervigio, que habia oido saludarle como rey por aquel estraño jorobado le siguió.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo IX\",\"blocks\":[{\"heading\":false,\"text\":\"Habia en el centro de una oscura selva de encinas, sobre una eminencia, rodeada por un arroyo, una torre triste y solitaria, cubierta de musgo y enmohecida su puerta de hierro.\"},{\"heading\":false,\"text\":\"Nadie, ni una sola persona se veia ni en el claro de la selva, ni al pie de la eminencia donde estaba construida la torre, ni en la torre misma.\"},{\"heading\":false,\"text\":\"Esta no tenia ventanas ni respiradero alguno al esterior.\"},{\"heading\":false,\"text\":\"Ninguna senda se veia en el bosque que condugese á la torre.\"},{\"heading\":false,\"text\":\"Era de noche y brillaba la luna.\"},{\"heading\":false,\"text\":\"Una luna rojiza y opaca.\"},{\"heading\":false,\"text\":\"Dominaba en torno de la torre y en el bosque un silencio de muerte.\"},{\"heading\":false,\"text\":\"Pero en medio de este silencio, se oyó de repente como el ruido de dos espadas que cortaban la maleza.\"},{\"heading\":false,\"text\":\"Poco despues, por un sendero que ellos mismos se habian abierto, aparecieron dos seres humanos.\"},{\"heading\":false,\"text\":\"El uno alto, esbelto, que andaba con gran magestad.\"},{\"heading\":false,\"text\":\"El otro pequeño, contrahecho, monstruoso, que remedaba en su andar al lobo traidor cuando se acerca al redil que guardan los mastines.\"},{\"heading\":false,\"text\":\"Eran Ervigio y el jorobado, á quien habia encontrado pescando en la márgen del rio.\"},{\"heading\":false,\"text\":\"Adelantaron entrambos hasta la torre, y cuando llegaron á su puerta, el enano dijo á Ervigio:\"},{\"heading\":false,\"text\":\"--Si tú eres aquel á quien ella espera, la puerta de la torre se abrirá al tocarla tú.\"},{\"heading\":false,\"text\":\"--¿Hay en esto algun arte de Satanás? dijo Ervigio.\"},{\"heading\":false,\"text\":\"--¿Y qué te importa? ¿no quieres ser rey?\"},{\"heading\":false,\"text\":\"La ambicion habló mas alto que el temor de Dios en el corazon de Ervigio, y tocó con una mano audaz las planchas de hierro de la puerta de la torre.\"},{\"heading\":false,\"text\":\"Apenas la habia tocado Ervigio, cuando la puerta se abrió con un silencio pavoroso.\"},{\"heading\":false,\"text\":\"Dentro no se veian mas que tinieblas.\"},{\"heading\":false,\"text\":\"--Si eres tú á quien ella ama, dijo el jorobado, cuando entres dentro, las tinieblas desaparecerán y oirás maravillas.\"},{\"heading\":false,\"text\":\"Ervigio impulsado siempre por su ambicion, penetró en la torre.\"},{\"heading\":false,\"text\":\"Apenas habia penetrado en el lóbrego dintel, cuando apareció á sus ojos iluminado por un resplandor rojizo, un ancho lago de sangre, en medio del cual habia un palacio rojo tambien, y reluciente.\"},{\"heading\":false,\"text\":\"--¡Oh! esto es horrible, dijo Ervigio.\"},{\"heading\":false,\"text\":\"--Para ser rey es necesario atravesar ese lago.\"},{\"heading\":false,\"text\":\"Una barca negra, á la que nadie guiaba, salió por las puertas del alcázar rojo, que se abrieron, y adelantó hasta tocar á la orilla donde se encontraban Ervigio y el enano.\"},{\"heading\":false,\"text\":\"Entrambos saltaron dentro.\"},{\"heading\":false,\"text\":\"Apenas habia tocado Ervigio la negra barca con sus plantas, cuando ésta se hundió entre un remolino del lago, desapareciendo entre sus rojas ondas.\"},{\"heading\":false,\"text\":\"Y se oyó la voz del enano que rugia en medio del estruendo atronador del remolino.\"},{\"heading\":false,\"text\":\"--La virgen maldita ha encontrado á su maldito esposo, y su generacion es mia.\"},{\"heading\":false,\"text\":\"Y aquellas palabras retronaron, se estendieron, vibraron y fueron repetidas por mil ecos pavorosos.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo X\",\"blocks\":[{\"heading\":false,\"text\":\"Y ahora, dijo Satanás dirijiéndose á Almedí, quiero que sepas quien era la muger que habia atraido así con sus encantamientos al ambicioso Ervigio.\"},{\"heading\":false,\"text\":\"Era una doncella que aun no habia cumplido los quince años, hermosa á maravilla, pero con una hermosura terrible.\"},{\"heading\":false,\"text\":\"El color de su tez era dorado, sus cabellos dorados tambien, sus ojos leonados con las pupilas negras, flexible el cuerpo como el de una pantera, y esbelta, gentil, y voluptuosa á maravilla.\"},{\"heading\":false,\"text\":\"Era una muger como no habia dos sobre la tierra.\"},{\"heading\":false,\"text\":\"Parecia una mezcla de fiera y de criatura humana.\"},{\"heading\":false,\"text\":\"Y á pesar del color de su piel, de sus cabellos y de sus ojos, era tal la brillantez, la suavidad y la trasparencia de su piel, tan sedosos, tan ricos, tan rizados sus cabellos, tan grandes, poderosos y lucientes sus ojos, tan preciadas las joyas que la engalanaban, y tan ricas y tan bellas tas túnicas que vestia, que no hubiera habido un hombre que la hubiese visto que no hubiera desfallecido de amor.\"},{\"heading\":false,\"text\":\"Era judía, y se llamaba Asenéth.\"},{\"heading\":false,\"text\":\"Su madre se habia llamado Zelpha, y habia sido una jóven hermosísima.\"},{\"heading\":false,\"text\":\"Pero con una hermosura semejante á la de las demás mugeres, y enteramente distinta de la de su hija.\"},{\"heading\":false,\"text\":\"Zelpha habia tenido un hermano judío tambien, y que se habia llamado Jamné.\"},{\"heading\":false,\"text\":\"Jamné habia sido mercader de sedas, y de púrpura y de paños preciados.\"},{\"heading\":false,\"text\":\"Habia sido un miserable, vendido á mí, y cuando hubo cometido cuantos crímenes son imaginables, el robo, la calumnia, la usura, la hechicería, y el envenenamiento, quiso cometer el último y mas horrible de los crímenes: el incesto.\"},{\"heading\":false,\"text\":\"Zelpha, la hermosísima Zelpha, era sin embargo sábia: su madre, famosa hechicera, la habia enseñado la astrología judiciaria, y el arte de los ensalmos y de los encantamientos, y á confeccionar filtros y hechizos, y á evocar los muertos, y á hacer comparecer los vivos, y á leer en sus pensamientos.\"},{\"heading\":false,\"text\":\"Zelpha, que era mas sábia que su hermano, adivinó sus intentos, y antes de que éste la hechizara para reducida á su voluntad, determinó hechizarle á él.\"},{\"heading\":false,\"text\":\"Para ello, una noche se arrancó tres de sus hermosos cabellos negros, los ató cabalísticamente, los quemó á la luz de su lámpara y me llamó.\"},{\"heading\":false,\"text\":\"Era una doncella hermosa y de quien yo esperaba mucho, y me presenté á ella en la forma de un hermoso mancebo.\"},{\"heading\":false,\"text\":\"--Sé, me dijo, que mi hermano quiere hacerme suya. Yo le aborrezco. Verme entre sus brazos sería para mí un tormento horrible.\"},{\"heading\":false,\"text\":\"--¿Y por qué aborreces á tu hermano?\"},{\"heading\":false,\"text\":\"--Es miserable y receloso, dijo; me tiene vestida de lana parda, me da de comer pan de avena y me tiene encerrada donde ni aun la luz del sol veo.\"},{\"heading\":false,\"text\":\"--¿Y qué quieres?\"},{\"heading\":false,\"text\":\"--Quiero... lo que no alcanza á hacer la ciencia que me enseñó mi madre. Yo quisiera castigar á mi hermano por la tiranía con que me trata, y por la impureza que por mí siente: es una bestia feróz.\"},{\"heading\":false,\"text\":\"--¿Y te vales de mí? la dije.\"},{\"heading\":false,\"text\":\"--Sí, me contestó.\"},{\"heading\":false,\"text\":\"--¿Y qué me darás en cambio?\"},{\"heading\":false,\"text\":\"--Estoy enamorada de un hombre.\"},{\"heading\":false,\"text\":\"--¿Y qué hombre es ese?\"},{\"heading\":false,\"text\":\"--El duque godo, Wamba.\"},{\"heading\":false,\"text\":\"--Valiente hombre.\"},{\"heading\":false,\"text\":\"--Y hermoso.\"},{\"heading\":false,\"text\":\"--Y temeroso de Dios. No sé si podrán vencerlo tus malas artes.\"},{\"heading\":false,\"text\":\"--Wamba sueña conmigo.\"},{\"heading\":false,\"text\":\"--¡Ah!\"},{\"heading\":false,\"text\":\"--Sí; un dia que estaba yo muy triste porque se habia despertado en mi alma el primer deseo del amor, evoqué la imágen de un hombre, que fuese hermoso, noble, rico, valiente y que no hubiese amado á ninguna muger.\"},{\"heading\":false,\"text\":\"Cuando yo le evoqué era la alta noche, y mi aposento estaba envuelto en tinieblas: entre mi lecho y la pared apareció un hombre como de unos treinta años.\"},{\"heading\":false,\"text\":\"Era rubío, blanco, y sus ojos azules eran tan hermosos, que me abrasaban de amor.\"},{\"heading\":false,\"text\":\"--¿Quién es ese hombre? ¿cómo se llama? pregunté al espíritu.\"},{\"heading\":false,\"text\":\"Entonces sobre su cabeza, en la pared oscura, apareció en letras de fuego este nombre: WAMBA.\"},{\"heading\":false,\"text\":\"--¿De qué pueblo es y qué religion profesa? añadí.\"},{\"heading\":false,\"text\":\"--Es lusitano; de la ciudad de Igeditania, descendiente de los visigodos, y cristiano: magnate de la córte de sus reyes, es un capitan bravo é invencible, y tanto ama la guerra, que no ha sentido amor por muger alguna.\"},{\"heading\":false,\"text\":\"--Que mi imagen vaya al sueño de ese hombre, y que me ame, dige al espíritu.\"},{\"heading\":false,\"text\":\"Entonces ví que los ojos de Wamba me miraban con amor y con deseo; que se fijaban en mi boca y en mi seno desnudo, y que sus megillas palidecian.\"},{\"heading\":false,\"text\":\"Wamba me habia visto en sueños, y obedeciendo á mis conjuros, me amaba: ahora bien; yo no puedo romper mis prisiones, ayúdame tú, Satanás. Convierte á mi hermano en una bestia feróz obediente á mi voluntad.\"},{\"heading\":false,\"text\":\"Entonces yo trasformé en leon á Jamné y le traje humilde y manso á los pies de Zelpha.\"},{\"heading\":false,\"text\":\"--Has hecho mi voluntad, dijo ella, y te lo agradezco.\"},{\"heading\":false,\"text\":\"--Pues si no me das lo que te pido, volveré á tu hermano á su antigua forma y te entregaré á él.\"},{\"heading\":false,\"text\":\"--¿Y qué quieres?\"},{\"heading\":false,\"text\":\"--Quiero la descendencia que tuvieres de Wamba.\"},{\"heading\":false,\"text\":\"Zelpha, mala hija y mala hermana, era tambien antes de serlo mala madre.\"},{\"heading\":false,\"text\":\"Maltrató á Jamné, que habia encontrado en sus mismos crímenes el castigo, abrió sus arcas y sus armarios, se apoderó de sus riquezas, se vistió como una sultana, y al dia siguiente abrió la tienda, y se puso á vender telas, joyas y perfumes, teniendo á sus pies al leon rojo en que yo habia trasformado á su hermano.\"},{\"heading\":false,\"text\":\"Y no sabes tú con cuanta rábia veia Jamné, en cuyo cuerpo de leon vivia su alma de hombre, á su hermana engalanada, hermosísima, magnífica, prodigando sus sonrisas á los compradores, y escuchando sus palabras de amor.\"},{\"heading\":false,\"text\":\"La tienda de la hermosa judía, que tenia á sus pies encadenado y manso á un formidable leon de Africa, llegó á ser la mas concurrida de Toledo: frecuentábanla los caballeros mas principales, y todos enamoraban á Zelpha, y ella los escuchaba á todos, pero solo se bajaban sus ojos y se estremecia su corazon ante un hombre.\"},{\"heading\":false,\"text\":\"Aquel hombre era Wamba.\"},{\"heading\":false,\"text\":\"Con asombro de todos los que conocian la severidad del noble godo, y su desprecio á las mugeres, le vieron concurrir á la tienda de la hermosa israelita y palidecer de celos cuando veia á esta hablando ó sonriendo con otro señor.\"},{\"heading\":false,\"text\":\"Zelpha queria irritar la pasion de Wamba, y se veia reducida á esperarlo todo de su amor, porque el amor que sentia por Wamba la dominaba haciendo inútil su ciencia de hechicera.\"},{\"heading\":false,\"text\":\"Wamba pasaba todos los dias por la tienda de Zelpha y entraba en ella con frecuencia la compraba telas, joyas y perfumes, la miraba mucho de una manera ardiente é involuntaria, pero no la decia una sola palabra de amor.\"},{\"heading\":false,\"text\":\"Un dia por la mañana, cuando Zelpha abria su tienda, y amarraba por la parte de adentro á su hermano, trasformado en leon, un esclavo negro se sentó á la parte de afuera de la tienda y se puso á mirar de hito en hito á la jóven.\"},{\"heading\":false,\"text\":\"--¿Qué quieres? le dijo esta con altivez.\"},{\"heading\":false,\"text\":\"--Si no te enojaras, lumbre de Dios, dijo el esclavo, yo te daria un mensage que traigo para tí.\"},{\"heading\":false,\"text\":\"--¿Tal es, que pueda ofenderme?\"},{\"heading\":false,\"text\":\"--Es un mensage de amor.\"},{\"heading\":false,\"text\":\"--¿Quién te envia?\"},{\"heading\":false,\"text\":\"--Un señor muy noble y muy rico.\"},{\"heading\":false,\"text\":\"--¿Cómo se llama?\"},{\"heading\":false,\"text\":\"--Wamba.\"},{\"heading\":false,\"text\":\"--¡Ah! dijo Zelpha.\"},{\"heading\":false,\"text\":\"--¿Qué diré á mi señor? preguntó el esclavo.\"},{\"heading\":false,\"text\":\"--Díle que esta tarde pasearé á la puesta del sol por las huertas del rey.\"},{\"heading\":false,\"text\":\"--¿Y nada mas?\"},{\"heading\":false,\"text\":\"--Nada mas.\"},{\"heading\":false,\"text\":\"El esclavo partió.\"},{\"heading\":false,\"text\":\"Zelpha cerró la tienda, porque necesitaba ataviarse deslumbrantemente para parecer mas hermosa á su adorado Wamba.\"},{\"heading\":false,\"text\":\"Entrelazó sus cabellos de diamantes y de perlas de los que habia amontonado su hermano, se vistió con las mejores túnicas de lino de seda y de brocado, que tenia para venderlas á precios exhorbitantes en la tienda, en todo lo cual invirtió mucho tiempo, comió de una manera suculenta á pesar de su impaciencia para que el ayuno no la robase sus bellos colores, y allá á la tarde, dejando encerrado y hambriento á su hermano, que rugia de hambre y de rabia, se envolvió en un largo velo que la cubria de pies á cabeza, y en paso lento se encaminó á las huertas del rey y se puso á vagar por entre las alamedas á las orillas del rio.\"},{\"heading\":false,\"text\":\"Vió bajar con impaciencia el sol al occidente y ponerse al fin.\"},{\"heading\":false,\"text\":\"Si Zelpha hubiese conservado para con Wamba su poder de hechicera, le hubiera evocado.\"},{\"heading\":false,\"text\":\"Pero Zelpha amaba, y el amor domina y no permite otra hechicería.\"},{\"heading\":false,\"text\":\"A punto que el sol se ocultaba, apareció por una avenida de la alameda un caballero ricamente vestido.\"},{\"heading\":false,\"text\":\"Zelpha le reconoció á pesar de la distancia, su corazon se agitó, y se sentó para esperar á su amado Wamba en una piedra al lado de la corriente.\"},{\"heading\":false,\"text\":\"Wamba llegó hasta ella.\"},{\"heading\":false,\"text\":\"--¿Serás tú acaso á quien yo busco?\"},{\"heading\":false,\"text\":\"--¿Y á quién buscais, señor? contestó temblorosa Zelpha.\"},{\"heading\":false,\"text\":\"--Busco á la doncella mas hermosa de Toledo.\"},{\"heading\":false,\"text\":\"--¿Será esa acaso la judía de la calle del Sol?\"},{\"heading\":false,\"text\":\"--¡Oh! ¡ella es á quien amo! Adios.\"},{\"heading\":false,\"text\":\"--¿Por qué te vas, señor?\"},{\"heading\":false,\"text\":\"--Voy á buscar á esa doncella.\"},{\"heading\":false,\"text\":\"--¡Oh! pues no sigas, señor mio, porque esa doncella enamorada está á tus pies.\"},{\"heading\":false,\"text\":\"Y Zelpha echándose atrás el velo, y descubriendo su resplandeciente hermosura, aumentada por sus resplandecientes galas, asió las manos de Wamba que la levantó en sus brazos.\"},{\"heading\":false,\"text\":\"Nadie los veia mas que la blanca luna que acababa de aparecer en el oriente.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XI\",\"blocks\":[{\"heading\":false,\"text\":\"Por un postigo del muro de Toledo, entraban aquella misma noche una muger envuelta de los pies á la cabeza en un velo blanco, y un hombre envuelto asimismo, de la cabeza á los pies, en una clámide roja.\"},{\"heading\":false,\"text\":\"El hombre y la muger atravesaron las calles de la ciudad, subieron á lo alto, y el hombre se detuvo junto al muro de un frondoso huerto, y llamó á un postigo.\"},{\"heading\":false,\"text\":\"Un esclavo abrió, y el hombre y la muger entraron.\"},{\"heading\":false,\"text\":\"Siguieron adelante, y penetraron en una noble cámara estensa y hermosa.\"},{\"heading\":false,\"text\":\"Pero los adornos de aquella cámara eran banderas africanas, y los muebles severos, y las paredes desnudas de tapicerías.\"},{\"heading\":false,\"text\":\"Una lámpara de hierro la iluminaba.\"},{\"heading\":false,\"text\":\"Cuando estuvieron dentro, la muger se desenvolvió de su velo y el hombre de su clámide.\"},{\"heading\":false,\"text\":\"Eran Wamba y Zelpha.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Zelpha, durante muchos dias, permaneció al lado de Wamba.\"},{\"heading\":false,\"text\":\"Su tienda estaba cerrada, y los rugidos del leon hambriento asustaban á los vecinos y á los que pasaban por la calle.\"},{\"heading\":false,\"text\":\"Zelpha, sin embargo, no parecia.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XII\",\"blocks\":[{\"heading\":false,\"text\":\"Pero llegó un momento en que Zelpha tuvo celos.\"},{\"heading\":false,\"text\":\"Celos, no ciertamente de una muger, sino celos de la guerra.\"},{\"heading\":false,\"text\":\"Wamba la habia dicho:\"},{\"heading\":false,\"text\":\"--Voy á partir á Africa.\"},{\"heading\":false,\"text\":\"--Llévame contigo, habia contestado Zelpha.\"},{\"heading\":false,\"text\":\"--Aquella tierra abrasa, tus megillas se quemarán bajo aquel sol ardiente, y luego... esponerte á los peligros... no, no: el guerrero, solo debe llevar al combate su lanza y su escudo.\"},{\"heading\":false,\"text\":\"Wamba era muy firme; Zelpha no tenia sobre él mas poder que el de su hermosura, y se acercaba el dia de la partida.\"},{\"heading\":false,\"text\":\"Zelpha quiso detenerle, y no pudiendo detenerle por su voluntad, pensó en valerse de un filtro.\"},{\"heading\":false,\"text\":\"Pero no queria confiarse á nadie, ni podia tampoco hacer el filtro en el palacio de Wamba.\"},{\"heading\":false,\"text\":\"Una mañana muy temprano, con el pretesto de ir á visitar su casa, salió del palacio de Wamba.\"},{\"heading\":false,\"text\":\"Al acercarse á la tienda, la sorprendieron los horribles rugidos del leon su hermano, y una espiral de negro humo que salia por encima de la casa.\"},{\"heading\":false,\"text\":\"--¿Qué será eso? dijo Zelpha.\"},{\"heading\":false,\"text\":\"Aquello era que Jamné, que aunque habia perdido la forma de hombre no habia perdido la inteligencia, hambriento, celoso, desesperado, habia llamado al infierno y hablaba conmigo.\"},{\"heading\":false,\"text\":\"Me pedia que yo le restituyese á su forma de hombre y á su poder de hechicero.\"},{\"heading\":false,\"text\":\"Pero yo no podia hacerlo, porque Jamné estaba hechizado por un conjuro invencible para mí.\"},{\"heading\":false,\"text\":\"--Pero le dije: Zelpha se acerca.\"},{\"heading\":false,\"text\":\"Jamné se echó á temblar.\"},{\"heading\":false,\"text\":\"--Y me maltratará, dijo, porque me aborrece y es cruel.\"},{\"heading\":false,\"text\":\"--Zelpha no puede maltratarte, le dije.\"},{\"heading\":false,\"text\":\"--¿Y por qué?\"},{\"heading\":false,\"text\":\"--Porque ha perdido su poder y su ciencia al perder su pureza entre los brazos de Wamba.\"},{\"heading\":false,\"text\":\"--¡Ah! esclamó Jamné en un rugido mezcla de dolor y de alegría; ¿conque Zelpha apagará la sed de mi amor?\"},{\"heading\":false,\"text\":\"--Recuerda que es tu hermana.\"},{\"heading\":false,\"text\":\"--¿Y qué me importa?\"},{\"heading\":false,\"text\":\"--Ofenderás á Dios, y Dios te castigará.\"},{\"heading\":false,\"text\":\"--Yo la amo.\"},{\"heading\":false,\"text\":\"--Si tu hermana es tuya, concebirá y tendrá una hija.\"},{\"heading\":false,\"text\":\"--No importa.\"},{\"heading\":false,\"text\":\"--Zelpha morirá al ser madre, y su hija heredará la ciencia y el poder que ella ha perdido.\"},{\"heading\":false,\"text\":\"-¡Ah!\"},{\"heading\":false,\"text\":\"--Y como has amado á tu hermana amarás á tu hija, porque estás maldito de Dios; y tu hija, que no le conocerá, será mas cruel contigo que lo ha sido Zelpha.\"},{\"heading\":false,\"text\":\"--¡No importa! esclamó rugiendo con mas fuerza Jamné, yo la amo.\"},{\"heading\":false,\"text\":\"--Pues héla que abre la puerta, le dije; quedad en paz.\"},{\"heading\":false,\"text\":\"Y desaparecí.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XIII\",\"blocks\":[{\"heading\":false,\"text\":\"Lo que sucedió cuando Zelpha abrió la puerta fué horrible.\"},{\"heading\":false,\"text\":\"Jamné, irritado, hambriento, feróz, enamorado, tomó de su hermana una venganza completa.\"},{\"heading\":false,\"text\":\"Zelpha fué suya, y no solo fué suya, sino que fué su esclava.\"},{\"heading\":false,\"text\":\"Zelpha no volvió á ver á Wamba.\"},{\"heading\":false,\"text\":\"Habia partido á la guerra y estaba en Africa.\"},{\"heading\":false,\"text\":\"Jamné habia dicho á su hermana.\"},{\"heading\":false,\"text\":\"--Abre la tienda y vende; toma una esclava que te sirva, y tú y yo, ya que por tu crueldad y tu infamia me veo reducido á esta forma, que solo tú podias quitarme, y que ya no puedes porque has perdido tu poder, comamos y vivamos lo mejor posible. El daño que me has hecho se vuelve contra tí; te ves reducida á ser la amante de un leon, cuando podias haberlo sido de un hombre. Abre la tienda y toma la esclava, pero no pienses en mas, porque yo estaré siempre junto á tí y en cuanto intentares huir te despedazaré.\"},{\"heading\":false,\"text\":\"Zelpha hizo lo que Jamné la mandaba, porque tenia miedo.\"},{\"heading\":false,\"text\":\"Habia probado su poder mágico, y su antiguo poder no habia respondido.\"},{\"heading\":false,\"text\":\"Desde el momento en que habia perdido su pureza entre los brazos de Wamba habia perdido su poder, y habia quedado reducida á la condicion de una muger vulgar.\"},{\"heading\":false,\"text\":\"Jamné en cambio, habia recobrado todo su poder mágico menos para volver á su antigua forma.\"},{\"heading\":false,\"text\":\"En el tiempo preciso, desde que Zelpha habia caido de nuevo en poder de su hermano, dió á luz una hija.\"},{\"heading\":false,\"text\":\"Aquella hija, tenia los cabellos y los ojos del color de los del leon, y la piel dorada.\"},{\"heading\":false,\"text\":\"Pero era un prodigio de hermosura.\"},{\"heading\":false,\"text\":\"Zelpha, murió al darla á luz.\"},{\"heading\":false,\"text\":\"Jamné evocó á una hada maldita para que la criase, y la hada se presentó y amamantó á la niña.\"},{\"heading\":false,\"text\":\"Jamné la puso por nombre Asenéth, y quiso obtener por mí lo que no podia obtener por sí mismo.\"},{\"heading\":false,\"text\":\"Y repitiendo sus conjuros, me evocó.\"},{\"heading\":false,\"text\":\"--Génio, me dijo, cuando me presenté á él; un palacio encantado para guardar á mi hija, y criarla para mí.\"},{\"heading\":false,\"text\":\"Apenas habia dicho estas palabras, cuando se encontraron en un palacio magnífico.\"},{\"heading\":false,\"text\":\"Pero todo en él era rojo; el oro, las piedras preciosas, las columnas de pórfido, hasta las aguas que corrian de las fuentes.\"},{\"heading\":false,\"text\":\"Aquel palacio, era invisible para los que no conociesen su encanto, y estaba guardado por un lago de sangre.\"},{\"heading\":false,\"text\":\"Solo un hombre podia entrar en él, el hombre para quien habia nacido destinada Asenéth.\"},{\"heading\":false,\"text\":\"Hadas condenadas la sirvieron como esclavas, y mecieron su cuna durante su infancia. Génios invisibles y malditos, llenaban para ella los aires en armonía, y de encantos los sueños.\"},{\"heading\":false,\"text\":\"Para ella, el alcázar encantado no era rojo.\"},{\"heading\":false,\"text\":\"Tenia por do quiera, frescos y brillantes apartamentos en que corrian sobre fuentes cristalinas, aguas olorosas, hasta cuyas cúpulas subia el fragante humo de los perfumes; aquellos apartamentos, salian á deliciosos jardines donde habia cuantos árboles, cuantas flores, cuantas plantas crió Dios, para arrojarlas sobre el mundo, cada cual en su lugar y su estacion. Curvos y trasparentes lagos, relumbraban acá y allá en medio de los jardines, bajo un sol siempre eterno, siempre brillante, siempre de rayos tibios, en un firmamento siempre azul, por el cual solo pasaban nubecillas rosadas, nunca la densa y negra niebla de la tormenta.\"},{\"heading\":false,\"text\":\"Ella, que era espíritu de tinieblas, solo conocia al dia.\"},{\"heading\":false,\"text\":\"Ella, que era el producto y el castigo á un tiempo de un horrible pecado, no conocia los pesares.\"},{\"heading\":false,\"text\":\"La felicidad moraba en su alma, y amaba desde los primeros años, con toda su alma, con toda su voluntad á un ser que veia niño como ella, cuando era niño, mancebo cuando fué muger, á quien veia, digo, por todas partes, en las nubecillas rosadas del cielo, en el fondo de los lagos, entre las flores de los jardines, á la sombra de las enramadas, en los ángulos de sus retretes, entre el humo blanco y aromático de los pebeteros, y sobre los surtidores de las fuentes.\"},{\"heading\":false,\"text\":\"Asenéth oia su voz que le decia; yo te amo, en el murmurio de las aguas, en el vuelo de las brisas, en los cantares lejanos y perdidos que las hadas malditas entonaban para adormirla.\"},{\"heading\":false,\"text\":\"Y cuando se dormia, le veia en sus sueños; pero en sus sueños, como en su vigilia, jamás tocaba á aquel mancebo, ni se obstinaba por llegar á él: bastábale con ver su hermosura, con amarle, con sentirse amada de él. Asenéth, que habia heredado toda la ciencia que su madre habia perdido, que era por lo tanto mas sábia que su padre Jamné, sabia que al cumplir los quince años se decidiria su destino, que perteneceria á su padre si vencia al hombre de su amor cuando entrase en el palacio encantado, ó que perteneceria al hombre de su amor, si este le vencia.\"},{\"heading\":false,\"text\":\"Jamné, menos sábio que su hija, no conocia sus pensamientos.\"},{\"heading\":false,\"text\":\"La acompañaba continuamente como un perro, y se echaba á sus pies, y aunque la desesperacion y la terrible fiebre de que adolecia la fiera, en la cual se habia trasformado su hermana, le aquejasen, no rugia por no despertar ó incomodar á su hija con sus rugidos.\"},{\"heading\":false,\"text\":\"Para Jamné, el palacio encantado no era ni claro, ni fresco, ni oloroso.\"},{\"heading\":false,\"text\":\"Por el contrario, era horriblemente rojo, lleno de un aire cálido que abrasaba su pecho, y respiraba por todas partes el nauseabundo olor de sangre fresca que irritaba sus ardientes fauces.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XIV\",\"blocks\":[{\"heading\":false,\"text\":\"Llegó, no la primavera del año, porque en el alcázar encantado todo el tiempo era una perpétua primavera para Asenéth, y un abrasador estío para Jamné, sino la primavera de la vida de Asenéth.\"},{\"heading\":false,\"text\":\"Faltaba únicamente un dia para que la doncella maldita cumpliese los quince años.\"},{\"heading\":false,\"text\":\"Aquella noche, cuando Jamné dormia á los pies del diván de su hija, Asenéth fijó en él una mirada sombría.\"},{\"heading\":false,\"text\":\"--Mañana, dijo, el diablo, mi esclavo, se pondrá á pescar en el rio, y si pasa por allí el amado de mi alma, le traerá á mis brazos.\"},{\"heading\":false,\"text\":\"Y si para entonces, tú eres leon, despedazarás á mi amado.\"},{\"heading\":false,\"text\":\"Pero si eres perro, mi amado le despedazará á tí y yo quedaré libre de mi encanto.\"},{\"heading\":false,\"text\":\"Y Jamné bien ageno de la crueldad de su hija, dormia.\"},{\"heading\":false,\"text\":\"Asenéth se levantó, fué á un ajimez de su retrete, y miró á las estrellas.\"},{\"heading\":false,\"text\":\"--Hablad para mí, dijo.\"},{\"heading\":false,\"text\":\"Y las estrellas temblaron en su inmensidad y enviaron á Asenéth trémulos resplandores.\"},{\"heading\":false,\"text\":\"Asenéth, leyó en aquellos resplandores las siguientes palabras:\"},{\"heading\":false,\"text\":\"--«Evoca al génio de la vida.»\"},{\"heading\":false,\"text\":\"--Poderoso génio de la vida, dijo Asenéth asiendo un amuleto obra del sábio rey Salomon, ven.\"},{\"heading\":false,\"text\":\"Apareció un génio horroroso.\"},{\"heading\":false,\"text\":\"Tenia cuatro pechos, cuatro ojos, cuatro manos y una cabellera de fuego.\"},{\"heading\":false,\"text\":\"En la una mano tenia una llave de oro, y en la otra una llave de plomo.\"},{\"heading\":false,\"text\":\"Su cabeza era de jóven, su pecho y sus brazos de hombre, su vientre hinchado y sus pies vacilantes.\"},{\"heading\":false,\"text\":\"Andaba en paso lento, pero no cesaba de andar.\"},{\"heading\":false,\"text\":\"Asenéth, siguió tras él, porque el génio no se detenia.\"},{\"heading\":false,\"text\":\"A medida que adelantaba, su paso se hacia mas rápido; marchaba por un camino rodeado de jardines.\"},{\"heading\":false,\"text\":\"--Poderoso génio, le dijo Asenéth: ¿sabes para que te he llamado?\"},{\"heading\":false,\"text\":\"--Sí. Tú temes a tu padre, tienes poder para trasformarle, para debilitarle y entregarle al furor de tu amante.\"},{\"heading\":false,\"text\":\"--Y dime: ¿mi amante le matará?\"},{\"heading\":false,\"text\":\"--No, dijo el génio, porque tú padre no ha cumplido aun su destino.\"},{\"heading\":false,\"text\":\"--Y dime, ¿cuál es el destino de mi padre?\"},{\"heading\":false,\"text\":\"--El de llevar al último límite la maldicion de su raza. Tu serás la ramera de tu padre.\"},{\"heading\":false,\"text\":\"Se estremeció Asenéth.\"},{\"heading\":false,\"text\":\"--¿Y no puedo evitarlo?\"},{\"heading\":false,\"text\":\"--Sí, si tienes valor para ello.\"},{\"heading\":false,\"text\":\"--¿Y qué he de hacer?\"},{\"heading\":false,\"text\":\"--Cuando mañana llegue á tí Ervigio...\"},{\"heading\":false,\"text\":\"--¿Se llama Ervigio, el amado de mi alma?\"},{\"heading\":false,\"text\":\"--Sí, y por tí morirá, ó por tí será rey.\"},{\"heading\":false,\"text\":\"--¡Será rey! dijo con altivez Asenéth, y yo seré reina.\"},{\"heading\":false,\"text\":\"--Tú serás la ramera de tu padre, si Ervigio no muere delante de tí despedazado por él.\"},{\"heading\":false,\"text\":\"--¿Y si yo eso hiciere?...\"},{\"heading\":false,\"text\":\"--Tú, has nacido destinada en tu pureza á Ervigio, tú le amas desde antes de nacer; tú por él has enloquecido; consentir en su muerte seria lo mismo que matar tu alma: Dios aceptaria tu sacrificio, te perdonaria por él, y perdonaria á tu familia. Tú habrias sido la víctima espiatoria.\"},{\"heading\":false,\"text\":\"--¡Matando á Ervigio!\"},{\"heading\":false,\"text\":\"--Sacrificándote en él.\"},{\"heading\":false,\"text\":\"--No, dijo con una inmensa valentía Asenéth.\"},{\"heading\":false,\"text\":\"--Tú y los tuyos caereis en el fuego eterno.\"},{\"heading\":false,\"text\":\"--No importa.\"},{\"heading\":false,\"text\":\"--¿Entonces para qué me has llamado?\"},{\"heading\":false,\"text\":\"--Para preguntarte cuantos son los dias de mi padre.\"},{\"heading\":false,\"text\":\"--Mas que los tuyos.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿y cómo podré yo hacer para que los dias de ese maldito terminen mañana?\"},{\"heading\":false,\"text\":\"--De ningun modo.\"},{\"heading\":false,\"text\":\"--¿Pero puedo dejarle encantado en mi palacio?\"},{\"heading\":false,\"text\":\"--Dios romperá el encanto cuando llegue la hora del castigo.\"},{\"heading\":false,\"text\":\"--¿Pero Ervigio, será mi esposo?\"},{\"heading\":false,\"text\":\"--Será tu amante...\"},{\"heading\":false,\"text\":\"--¿No mas que mi amante?\"},{\"heading\":false,\"text\":\"--Ervigio cuando sea rey te abandonará.\"},{\"heading\":false,\"text\":\"--No le haré rey.\"},{\"heading\":false,\"text\":\"--No puedes, á no ser que le dejes despedazar por tu padre.\"},{\"heading\":false,\"text\":\"--Yo soy sábia, soy hechicera...\"},{\"heading\":false,\"text\":\"--Lo que está escrito, se cumplirá.\"},{\"heading\":false,\"text\":\"--Desaparece de mi vista, génio maldito.\"},{\"heading\":false,\"text\":\"El génio de la vida desapareció con estruendo en las entrañas de la tierra.\"},{\"heading\":false,\"text\":\"Asenéth se sentó pensativa bajo un árbol de sus jardines.\"},{\"heading\":false,\"text\":\"Brillaba una luna plácida y tranquila.\"},{\"heading\":false,\"text\":\"Y apenas se sentó, oyó cantar un ruiseñor.\"},{\"heading\":false,\"text\":\"Asenéth comprendia el lenguaje de las aves, y oyó que el ruiseñor decia:\"},{\"heading\":false,\"text\":\"--¿Qué haces tú ahí, hermana golondrina, desvelada en un nido ageno?\"},{\"heading\":false,\"text\":\"--Estoy muy cansada y no he podido llegar al alcázar de Toledo; me he parado en este ciprés, y sin embargo no he podido dormirme.\"},{\"heading\":false,\"text\":\"--¿Te ha sucedido algo que te aflija, hermana?\"},{\"heading\":false,\"text\":\"--Sí; esta mañana con el alba salí de Africa; allí quema ya el sol, y los manantiales están secos, rugen los leones sedientos y los vencejos caen sofocados de calor.\"},{\"heading\":false,\"text\":\"Yo habia dejado mi nido en el alcázar de Toledo, y dije á mi esposo:\"},{\"heading\":false,\"text\":\"--Amado mio, yo me voy á España, sígueme.\"},{\"heading\":false,\"text\":\"--Tengo que arreglar aquí unos negocios con nuestro rey, se acerca la grande partida, pero vete tu sola si el calor te sofoca, ya sabes el camino, arregla nuestra casa para cuando lleguemos.\"},{\"heading\":false,\"text\":\"Me despedí de él, y llegué á España cuando ya el sol quemaba.\"},{\"heading\":false,\"text\":\"Estaba muy cansada.\"},{\"heading\":false,\"text\":\"Volaba entonces sobre la hermosa tierra del Iliberis.\"},{\"heading\":false,\"text\":\"Mis alas estaban doloridas.\"},{\"heading\":false,\"text\":\"Abatí el vuelo sobre un frondoso bosque y me escondí con delicia en un sicomoro.\"},{\"heading\":false,\"text\":\"¡Ay hermano ruiseñor! estaba escrito que yo no reposase.\"},{\"heading\":false,\"text\":\"Apenas habia plegado mis alas y esponjado mis plumas, cuando he aquí que de una negra sima que se veia á poca distancia desde el sicomoro, salió un culebron enorme.\"},{\"heading\":false,\"text\":\"Yo me aterré y me dí por perdida, y no pude moverme.\"},{\"heading\":false,\"text\":\"Creí morir.\"},{\"heading\":false,\"text\":\"Pero el culebron, no reparó en mí.\"},{\"heading\":false,\"text\":\"Empezó á silvar, y yo entendia sus silvidos.\"},{\"heading\":false,\"text\":\"El culebron decia:\"},{\"heading\":false,\"text\":\"--Hermano lagarto, el de las escamas blancas, verdes y azules, ven.\"},{\"heading\":false,\"text\":\"Ven, hermano lagarto, el de las escamas azules, verdes y blancas.\"},{\"heading\":false,\"text\":\"Y se oyó ruido entre la yerba, y un lagarto enorme se asomó al borde de la sima y se puso á mirar á la culebra agitando la cola.\"},{\"heading\":false,\"text\":\"--¿Qué sucede, hermana mia? dijo el lagarto.\"},{\"heading\":false,\"text\":\"--¿Te acuerdas? dijo la culebra.\"},{\"heading\":false,\"text\":\"--¿De qué?\"},{\"heading\":false,\"text\":\"--De la tarde de horrores.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿de aquella tarde en que un anciano de barba blanca, que venia montado en un asno, y acompañado de sus dos hijos, hombre y muger, se detuvo al pié de la acacia junto á la fuente?\"},{\"heading\":false,\"text\":\"--Sí. ¿Te acuerdas?\"},{\"heading\":false,\"text\":\"--Me acuerdo de que el viejo se apeó, se sentó junto á la fuente, sacó su hijo provisiones de unas alforjas, comieron él y su padre y su hermana, y luego el viejo se tendió bajo la acacia y se durmió.\"},{\"heading\":false,\"text\":\"--¡Sí! ¡sí! veo que te acuerdas, y te acordarás tambien de que los dos hijos del viejo eran muy jóvenes: el tendria veinte años y ella catorce. El era hermoso y fuerte, y ella delicada y pura como una flor.\"},{\"heading\":false,\"text\":\"--Sí, es verdad, dijo el lagarto; él se llamaba Jamné y ella Zelpha.\"},{\"heading\":false,\"text\":\"--¿Y eran judíos?\"},{\"heading\":false,\"text\":\"--Y malditos.\"},{\"heading\":false,\"text\":\"--¿Te acuerdas?\"},{\"heading\":false,\"text\":\"--El asno que era muy fuerte iba muy cargado y pacia la yerba; pero paciendo, paciendo, no quitaba ojo del viejo que dormia.\"},{\"heading\":false,\"text\":\"--¿Y no te acuerdas de mas? dijo la culebra.\"},{\"heading\":false,\"text\":\"--¡Vaya! me acuerdo de lo que dijeron los dos malditos, ¿y tú?\"},{\"heading\":false,\"text\":\"--Yo tambien.\"},{\"heading\":false,\"text\":\"--Jamné se acercó á su padre y le examinó atentamente: el viejo no se movia: entonces Jamné sacó de entre su hopalanda un largo y reluciente puñal, y acercó su hoja á la entreabierta boca de su padre.\"},{\"heading\":false,\"text\":\"La brillante hoja del puñal no se empañó.\"},{\"heading\":false,\"text\":\"--Nuestro padre no despertará, dijo Jamné á Zelpha.\"},{\"heading\":false,\"text\":\"--¿Y por qué? dijo Zelpha.\"},{\"heading\":false,\"text\":\"--Porque nuestro padre ha comido un dátil que yo traia guardado para él desde Africa.\"},{\"heading\":false,\"text\":\"Zelpha se encojió de hombros.\"},{\"heading\":false,\"text\":\"--De modo que, dijo, lo que el asno trae sobre sí, es nuestro.\"},{\"heading\":false,\"text\":\"--Nuestro es el tesoro de perlas, diamantes y telas preciosas que trae sobre sí el asno.\"},{\"heading\":false,\"text\":\"--¿Y dónde iremos á llevar esas riquezas?\"},{\"heading\":false,\"text\":\"--A la córte imperial de los godos, á Toledo. Pero para que no interrumpan el sueño de nuestro padre, acostémosle en un lecho eterno.\"},{\"heading\":false,\"text\":\"Lit de J.J. Martinez, Madrid. Letre dibº y litº]\"},{\"heading\":false,\"text\":\"--¿Y cómo abriremos ese lecho? no tenemos mas hierro que tu puñal.\"},{\"heading\":false,\"text\":\"--Aquí hay una ancha sepultura, dijo Jamné señalando á la sima.\"},{\"heading\":false,\"text\":\"--¡Ah! es verdad. El diablo nos esperaba, dijo sonriendo de una manera horrible Zelpha, y ha abierto la sepultura de nuestro padre.\"},{\"heading\":false,\"text\":\"--Ayúdame á arrojarle en ella, hermana.\"},{\"heading\":false,\"text\":\"--¿Y no temes que algun dia nos llame á esta sepultura la voz de nuestro padre? dijo Zelpha:\"},{\"heading\":false,\"text\":\"--Dios es Satanás, dijo impíamente Jamné, ¿te acuerdas, hermano lagarto?\"},{\"heading\":false,\"text\":\"--Vaya si me acuerdo, y me acuerdo tambien de que al escuchar aquella blasfemia me estremecí: los hombres son impíos, porque son soberbios, y una poca de ciencia les hace revelarse contra Dios: los dos hermanos malditos eran sábios, conocian la ciencia del mal, y como el dios del mal era quien les inspiraba, creian que no habia mas Dios que Satanás: Satanás, á quien el asesinato, el parricidio y la impureza son agradables. ¡Vaya si me acuerdo! Luego, los dos hermanos asieron el cadáver de su padre, el uno por los pies, y el otro por la cabeza, le mecieron un momento y le arrojaron en medio de la sima.\"},{\"heading\":false,\"text\":\"--Y luego, añadió la culebra, los dos miserables se acercaron al asno: ¿te acuerdas de lo que sucedió?\"},{\"heading\":false,\"text\":\"--Sucedió que el asno al acercarse el parricida, se volvió y le dió una coz en la frente y no le hizo daño, pero marcó sobre su frente maldita una mancha roja é indeleble.\"},{\"heading\":false,\"text\":\"--Así fué, así fué, hermano lagarto. Luego Jamné castigó al asno, montó en él á su hermana Zelpha, tiró del jumento y desaparecieron entre los árboles.\"},{\"heading\":false,\"text\":\"--Yo me quedé horrorizado, dijo el lagarto.\"},{\"heading\":false,\"text\":\"--Y yo tambien, añadió la culebra.\"},{\"heading\":false,\"text\":\"--Y yo, dijo la golondrina, que escuchaba todo esto, sentia que las plumas se me arrancaban de la carne, amigo ruiseñor.\"},{\"heading\":false,\"text\":\"--Los hombres son infames y réprobos, añadió el ruiseñor; se gozan en el mal: yo no los puedo ver.\"},{\"heading\":false,\"text\":\"--Ni yo: el año pasado me destruyeron mi nido.\"},{\"heading\":false,\"text\":\"--Y á mi hace pocos dias me mataron mi compañera, por eso canto tan tristemente.\"},{\"heading\":false,\"text\":\"--¡Pobre ruiseñor!\"},{\"heading\":false,\"text\":\"--¿Y no dijeron mas el lagarto y la culebra?\"},{\"heading\":false,\"text\":\"--Sí, sí dijeron: y yo los escuchaba, porque aunque tenia mucho miedo, tenia mas curiosidad.\"},{\"heading\":false,\"text\":\"--Hembra al fin, dijo el ruiseñor.\"},{\"heading\":false,\"text\":\"--Pues como decia, continuó la golondrina desentendiéndose en la observacion del ruiseñor, el lagarto y la culebra siguieron hablando, y yo escuchándolos.\"},{\"heading\":false,\"text\":\"--Tú y yo, dijo la culebra, cuando desaparecieron los dos infames, nos despedimos escandalizados y llenos de horror por lo que habiamos visto, tú te metiste en tu grieta y yo me bajé abajo á lo profundo, donde tú no has querido nunca bajar.\"},{\"heading\":false,\"text\":\"--Está aquello muy lóbrego y muy oscuro; y aunque tú me has dicho que en pasando de lo oscuro hay maravillas, he tenido miedo: en una ocasion quise bajar, y al llegar á cierto punto me volví asustado: se oia un ruido atronador, sordo, espantable.\"},{\"heading\":false,\"text\":\"--Es el alma de Abraham, el padre de Jamné y de Zelpha, que se revuelve rugiente y maldice de contínuo á sus hijos y á las generaciones de sus hijos.\"},{\"heading\":false,\"text\":\"--Y tiene razon, dijo el lagarto.\"},{\"heading\":false,\"text\":\"--Pero él se tuvo la culpa de lo que le sucedió: bien claro se lo dijeron los astrólogos.\"},{\"heading\":false,\"text\":\"--¿Y qué le dijeron los astrólogos? preguntó el lagarto.\"},{\"heading\":false,\"text\":\"--Oye la historia de Abraham.\"},{\"heading\":false,\"text\":\"El lagarto se acomodó en la yerba para oir mejor, y yo apliqué mi oido con cuanta atencion pude; mi curiosidad crecia.\"},{\"heading\":false,\"text\":\"--Hace veinte años, un médico judío que ya pasaba de los treinta, entró montado en un asno por una de las puertas de Damasco.\"},{\"heading\":false,\"text\":\"Aquel médico era Abraham.\"},{\"heading\":false,\"text\":\"Conocia las virtudes de las yerbas, y sabia hacer filtros; pero nunca habia hecho venenos ni invocado á Satanás: era demasiado caritativo para que pudiese hacer lo uno, y harto temeroso de Dios para que pudiese hacer lo otro. Siendo muy niño habia perdido á sus padres, y entrado á servir para que lo sustentase á un famoso médico árabe. Le acompañaba á las montañas y á los valles á buscar yerbas salutíferas, y luego á ver á los enfermos: en doce años que estuvo al lado del médico se hizo tan sábio como él, y conoció todas las yerbas que él conocia, y aprendió á curar todas las enfermedades que él curaba. Con el ejemplo del sábio árabe, que era muy religioso, se hizo creyente, temeroso de Dios, y caritativo y buen hombre.\"},{\"heading\":false,\"text\":\"El médico árabe le queria como á un hijo.\"},{\"heading\":false,\"text\":\"Y sin embargo, el mismo dia en que Abraham cumplia sus treinta años, y siendo ya muy viejo el médico árabe, éste le dijo:\"},{\"heading\":false,\"text\":\"--Ya eres hombre crecido, sabes todo lo que yo sé y no es bien que continúes en la servidumbre: te compraré un asno, una bolsa y yerbas medicinales, y te irás por el mundo á probar fortuna.\"},{\"heading\":false,\"text\":\"--Pero yo no quiero separarme de tí, que eres mi padre, dijo Abraham: quédante pocos años de vida y quiero estar á tu lado para cerrarte los ojos.\"},{\"heading\":false,\"text\":\"--Tú no puedes permanecer en mi casa, dijo el médico, porque si permaneces vendrá sobre tí y sobre mí una gran desgracia.\"},{\"heading\":false,\"text\":\"--¿Pero qué desgracia puede sucedernos, siendo como lo somos, piadosos y guardadores de los preceptos de Dios?\"},{\"heading\":false,\"text\":\"--No puedes permanecer en mi casa, dijo el anciano.\"},{\"heading\":false,\"text\":\"--Si tú me arrojares de ella, me iré, pero permaneceré en la ciudad esperando que pase tu enojo y que me llames á tí.\"},{\"heading\":false,\"text\":\"--Yo no estoy enojado contigo, pero te aconsejo y te mando que salgas de mi casa. Dios lo quiere.\"},{\"heading\":false,\"text\":\"--¿Y no me dirás el secreto de tu resolucion?\"},{\"heading\":false,\"text\":\"--No debo decírtelo. Vé, hijo mio, vé, que donde quiera que fueses, irá contigo mi bendicion.\"},{\"heading\":false,\"text\":\"Era tal y tan firme la resolucion del anciano médico, que Abraham se vió obligado á obedecer: tomó la bolsa y algunas ropas que le dió el viejo, montó en el asno y se alejó llorando y desolado; pero no salió de Alejandría, en cuya ciudad moraban, sino que se fué á vivir á un barrio fuera de los muros, y se dió á conocer como médico, y empezó á curar y adquirir fama, hasta el punto de que se hizo en muy pocos dias el médico mas famoso de la ciudad.\"},{\"heading\":false,\"text\":\"--¿Quién te ha contado esa historia, hermana culebra? dijo con acento de incredulidad el lagarto.\"},{\"heading\":false,\"text\":\"--Me la ha contado el alma del mismo Abraham, hermano lagarto, dijo ofendida la culebra; y si tú no hubieses sido cobarde y hubieras bajado al último suelo de la sima, al palacio encantado y maravilloso donde pena Abraham por desobediente á Dios, el alma de Abraham te hubiera contado tambien esta historia.\"},{\"heading\":false,\"text\":\"--No te ofendas, amiga culebra, dijo el lagarto; pero es tan maravilloso lo que me cuentas...\"},{\"heading\":false,\"text\":\"--Pues aun quedan mas maravillas.\"},{\"heading\":false,\"text\":\"--¿Y dime, por qué amando de tal modo á Abraham el viejo médico árabe le echó de su casa?\"},{\"heading\":false,\"text\":\"--Por que el viejo tenia una hija hermosísima.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿y se habia enamorado de ella Abraham?\"},{\"heading\":false,\"text\":\"--No, porque Abraham no la conocia. El médico tenia escondida á su hija como un tesoro.\"},{\"heading\":false,\"text\":\"Porque Abraham era avaro y fundaba en su hija grandes esperanzas.\"},{\"heading\":false,\"text\":\"Leila-Fatimah[92] era una doncella de diez y seis años.\"},{\"heading\":false,\"text\":\"Parecia que Dios se habia complacido en ella.\"},{\"heading\":false,\"text\":\"Si algun hombre la hubiera visto hubiera desfallecido de amor como á la vista de una hurí.\"},{\"heading\":false,\"text\":\"Su frente era un arca de pureza, sus ojos dos lumbreras de amor, sus cabellos redes de almas, y su cuello, y su seno, y su talle, atractivo de corazones.\"},{\"heading\":false,\"text\":\"Al verla en sus primeros años tan hermosa, el avaro médico dijo:\"},{\"heading\":false,\"text\":\"--Mi esposa me ha dado una perla: pues bien, embellezcamos esta perla; rodeémosla de atractivos, pulámosla y hagámosla tan hermosa que sea inapreciable.\"},{\"heading\":false,\"text\":\"Y la enseñó todo lo que sabia, que no era poco, y quiso que aprendiese lo que él no sabia, que era mucho.\"},{\"heading\":false,\"text\":\"Buscó á una maga y la pagó espléndidamente para que enseñase á Leila-Fatimah la ciencia de los astros y de lo infinito; pero del infinito que viene de Dios, no de lo infinito del mal, que viene del diablo.\"},{\"heading\":false,\"text\":\"Pero la maga era mala, y sin que lo supiese el viejo médico enseño á Leila-Fatimah la ciencia de lo oculto, y la hechicería y la cábala.\"},{\"heading\":false,\"text\":\"Y la ciencia hacia cada vez mas hermosa á Leila-Fatimah, dando á su mirada un brillo sobrenatural, á su frente una magestad irresistible, á su sonrisa un poder del infierno.\"},{\"heading\":false,\"text\":\"Y el anciano médico, cada vez que veia crecer á su hija en ciencia y en hermosura, se frotaba alegremente las manos y esclamaba:\"},{\"heading\":false,\"text\":\"--Cuando tú hayas llegado á la fuerza de tu juventud y á la cumbre de la ciencia, yo te llevaré á Damasco y te presentaré al califa. Y el califa se enamorará de tí, porque no podrá menos de enamorarse, y tú serás sultana, y yo seré wazir del califa, y tendré alcázares y tesoros, y esclavos, y recojeré al fin el fruto digno de mis vigilias durante tantos años.\"},{\"heading\":false,\"text\":\"Y cuando el codicioso médico vió que su hija era sábia, aunque era todavía niña, quiso que tuviese todo lo que hace amable á una muger, y buscó bayaderas y las llevó á su casa, y las bayaderas, espléndidamente pagadas, enseñaron á Leila-Fatimah las danzas lúbricas que ellas bailaban en las plazas, agitando sus panderetas al son de sus guzlas.\"},{\"heading\":false,\"text\":\"Y al poco tiempo Leila-Fatimah, bailaba como la mejor bayadera, tocaba la guzla y la tiorba y la guitarra, y repicaba las castañuelas como una hija de Egipto, y hacia hermosos versos, y cantaba como una alondra.\"},{\"heading\":false,\"text\":\"Y era mas: Leila-Fatimah amaba, porque el diablo la habia enseñado á amar.\"},{\"heading\":false,\"text\":\"Y era el amor de Leila-Fatimah ardiente y voluptuoso, como inspirado por el diablo.\"},{\"heading\":false,\"text\":\"Y soñaba con sus amores, sin objeto y se abrasaba en ellos, y como no veia á nadie, por que su padre la tenia casi emparedada, un dia en que el delirio de su amor de vírgen era mas intenso, evocó al diablo.\"},{\"heading\":false,\"text\":\"El diablo se la presentó en la figura de Abraham.\"},{\"heading\":false,\"text\":\"Abraham era muy hermoso, y Leila se enamoró de él.\"},{\"heading\":false,\"text\":\"Y fué á arrojarse en sus brazos.\"},{\"heading\":false,\"text\":\"Pero como el diablo era un espíritu, se le huyó.\"},{\"heading\":false,\"text\":\"--¿Por qué huyes de mí, luz de mis ojos, alegría de mi alma, agua fresca y cristalina de mi sed, dijo llorando Leila-Fatimah.\"},{\"heading\":false,\"text\":\"El diablo, que se habia propuesto representar á Abraham, la dijo:\"},{\"heading\":false,\"text\":\"--Yo no puedo ser tuyo, mientras viva tu padre.\"},{\"heading\":false,\"text\":\"--¿Y por qué?\"},{\"heading\":false,\"text\":\"--Porque entre estas paredes desfallezco, me ahogo; yo no puedo darte mi amor si no en medio de los jardines, á la luz de la luna, libres tú y yo como los pájaros que vuelan de una enramada á otra enramada.\"},{\"heading\":false,\"text\":\"--¿Y quién eres tú?\"},{\"heading\":false,\"text\":\"--Yo soy un discípulo de tu padre, médico como él, y como él sábio. Yo no puedo ser tuyo, porque como tu padre te guarda, me he valido de la ciencia para meterme en tus habitaciones convertido en un soplo de aire por las rendijas dé las puertas, y me he dejado el cuerpo fuera.\"},{\"heading\":false,\"text\":\"--Pero yo te veo; veo tus ojos, veo tu boca que me sonrie.\"},{\"heading\":false,\"text\":\"--Sí, sí, eso es verdad; es que mi espíritu toma la apariencia de mi cuerpo, pero para que te convenzas, llega á mí y áseme si puedes.\"},{\"heading\":false,\"text\":\"Leila-Fatimah se dirijió al diablo, disfrazado con la figura de Abraham, y aunque el diablo no huyó, solo cojió Leila aire.\"},{\"heading\":false,\"text\":\"--¿Y cómo te llamas? dijo jadeante de deseo la hermosísima doncella.\"},{\"heading\":false,\"text\":\"--Abraham.\"},{\"heading\":false,\"text\":\"--¿Y vives en la casa de mi padre?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¡Oh! pues yo haré que mi padre abra las puertas de mis habitaciones para que pueda entrar tu cuerpo.\"},{\"heading\":false,\"text\":\"--Tu padre no consentirá, porque te guarda para el califa de Damasco.\"},{\"heading\":false,\"text\":\"--¡Para el califa, que será un señor muy sério y muy déspota que me tratará como á una esclava! dijo Leila-Fatimah; no, yo te amo á tí, y solo seré tuya: mi padre me ama y no me negará el ser tu esposa.\"},{\"heading\":false,\"text\":\"--Tú no serás mi esposa mientras tu padre viva.\"},{\"heading\":false,\"text\":\"--Mi padre me ama.\"},{\"heading\":false,\"text\":\"--Tu padre ama mas al oro, y espera que el califa le pague esplendidamente tu hermosura.\"},{\"heading\":false,\"text\":\"--¡Oh!¡oh! dijo Leila-Fatimah, en cuyos ojos apareció una espresion terrible: pues si eso es verdad, mi padre no me venderá al califa. Yo soy sábia, mas sábia que él, ¡oh! ¡oh! mi padre no me venderá al califa, y tú serás mio, yo te le juro.\"},{\"heading\":false,\"text\":\"--Ya eres muger y hermosa, y dentro de tres dias, tu padre te meterá en un palanquin y te llevará á Damasco.\"},{\"heading\":false,\"text\":\"--No me llevará.\"},{\"heading\":false,\"text\":\"--Lo veremos; tu padre se acerca, y yo me voy, quédate en paz.\"},{\"heading\":false,\"text\":\"Y el diablo, se desvaneció como humo.\"},{\"heading\":false,\"text\":\"Leila-Fatimah, se quedó desesperada.\"},{\"heading\":false,\"text\":\"Poco despues, sonaron llaves y cerrojos y puertas, y el severo médico entró en el retrete donde acurrucada en un diván estaba su hija llorando.\"},{\"heading\":false,\"text\":\"Al verla el médico, pálida y desolada, se aterró.\"},{\"heading\":false,\"text\":\"--¿Qué te contrista, alegría de mi vida, esperanza de mis canas? dijo el médico.\"},{\"heading\":false,\"text\":\"--Amo á un hombre, buen padre mio, dijo Leila fijando en él sus hermosos ojos negros llenos de lágrimas.\"},{\"heading\":false,\"text\":\"El médico, á pesar de sus años, dió un salto.\"},{\"heading\":false,\"text\":\"--¡Que amas!... ¡que amas á un hombre! esclamó temblándole la barba de miedo y de cólera. ¿Mas cuándo has visto á un hombre?\"},{\"heading\":false,\"text\":\"--Yo amo á tu discípulo Abraham.\"},{\"heading\":false,\"text\":\"--¿Pero dónde has visto tú á mi discípulo? esclamó en el colmo de su cólera, el médico.\"},{\"heading\":false,\"text\":\"--Yo le amo, y quiero ser su esposa, contestó Leila-Fatimah llorando como un niño voluntarioso.\"},{\"heading\":false,\"text\":\"--Tú no has nacido para ese perro judío, esclamó completamente fuera de sí el médico.\"},{\"heading\":false,\"text\":\"--Yo le amo y le quiero, repitió Leila llorando mas fuerte.\"},{\"heading\":false,\"text\":\"--Pero ¿cómo, cuando, donde le has visto?\"},{\"heading\":false,\"text\":\"Leila no quiso decir la verdad á su padre porque amaba á Abraham, y no queria esponerle á la cólera del viejo.\"},{\"heading\":false,\"text\":\"--Yo soy sábia, padre: un dia mi corazon se abrasaba en un fuego dulce y desconocido: tenia sed en el alma. Entonces evoqué á un génio y le dije:\"},{\"heading\":false,\"text\":\"--¿Por qué mi sueño es fatigoso; por qué lloro sin causa; por qué mi corazon se estremece, y mi alma está triste?\"},{\"heading\":false,\"text\":\"--Tú amas, me dijo el génio: has llegado á la edad en que el corazon de una vírgen se abre como el capullo de una rosa para recibir el rocío de la mañana.\"},{\"heading\":false,\"text\":\"El médico se desesperó porque no habia contado con la naturaleza, que habla al alma de las niñas aunque se las guarde en el fondo de un pozo.\"},{\"heading\":false,\"text\":\"Porque el amor nace con ellas, y llega un dia en que habla, y seduce y enloquece.\"},{\"heading\":false,\"text\":\"Y se arrepintió de haberla hecho sábia.\"},{\"heading\":false,\"text\":\"Pero quiso saber hasta el fin todo el secreto de los vírgenes amores de su hija.\"},{\"heading\":false,\"text\":\"--¿Y dónde has visto á Abraham? la dijo.\"},{\"heading\":false,\"text\":\"--¡Soy sábia! dijo con énfasis Leila.\"},{\"heading\":false,\"text\":\"--¡Ah! has buscado un hombre y ha venido á tí la imágen del que tenias mas cerca: pues bien, yo apartaré de tí ese peligro.\"},{\"heading\":false,\"text\":\"--Si le apartas de mí moriremos, padre, dijo con acento solemne Leila.\"},{\"heading\":false,\"text\":\"--¡Que moriremos! esclamó con espanto el médico.\"},{\"heading\":false,\"text\":\"--Sí, porque yo moriré sin su amor, y el remordimiento de haber causado mi muerte, te matará.\"},{\"heading\":false,\"text\":\"Leila, invirtiendo su pensamiento se habia sentenciado.\"},{\"heading\":false,\"text\":\"Un terror vago llenó de un frio apenador el alma del médico, y huyó encerrando de nuevo á su hija.\"},{\"heading\":false,\"text\":\"Procuró dominarse, sin embargo, y llamó á Abraham, y sin decirle la causa de su resolucion, le despidió.\"},{\"heading\":false,\"text\":\"Abraham, pues, que nada sabia, tomó la bolsa que le dió su maestro, el médico, montó en el asno, y se alejó de la casa.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XV\",\"blocks\":[{\"heading\":false,\"text\":\"Apenas habia pasado una luna, desde que Abraham habia salido de casa de su maestro, de su segundo padre, cuando una noche llamaron á grandes golpes á la puerta de su casa.\"},{\"heading\":false,\"text\":\"Abrió y vió á uno de los esclavos del médico.\"},{\"heading\":false,\"text\":\"--Mi señor se muere, dijo el negro; se muere de una enfermedad desconocida, le han visto todos los médicos de Alejandría y ninguno ha podido descubrir la causa de su mal, tú eres el único que no le ha visitado, ven.\"},{\"heading\":false,\"text\":\"--¡Que mi padre, mi buen anciano padre se muere! esclamó todo asustado y trémulo el buen Abraham.\"},{\"heading\":false,\"text\":\"Se echó sobre los hombros su capellar, y sin toca para no detenerse, siguió á la carrera al esclavo negro.\"},{\"heading\":false,\"text\":\"Cuando llegó á la casa del padre de Leila, le encontró delirando.\"},{\"heading\":false,\"text\":\"El viejo no le conoció.\"},{\"heading\":false,\"text\":\"Algunos médicos estaban alrededor de su lecho.\"},{\"heading\":false,\"text\":\"--Esta es una lámpara que se apaga, dijo llorando Abraham, pero yo no sé que aceite pueda reanimarla.\"},{\"heading\":false,\"text\":\"--Ni yo.\"},{\"heading\":false,\"text\":\"--Ni yo.\"},{\"heading\":false,\"text\":\"--Ni yo, dijeron los otros médicos.\"},{\"heading\":false,\"text\":\"Revolviéronse los autores mas graves que tenia entre sus buenos libros el difunto, y en ninguno se encontró ni la mas leve noticia, ni la mas leve indicacion de la enfermedad misteriosa que mataba al viejo.\"},{\"heading\":false,\"text\":\"Y su vida se acababa, se acababa.\"},{\"heading\":false,\"text\":\"Y los médicos profundamente contrariados porque se veian en aquel momento ignorantes, miraban con cólera los progresos del mal, que se les reia en sus barbas acabando de una manera rápida, segura y cada vez creciente, con el enfermo.\"},{\"heading\":false,\"text\":\"Al fin, el viejo dió una gran voz pronunciando el nombre de su hija en acento amenazador como si la hubiera emplazado ante la justicia del Altísimo, y espiró.\"},{\"heading\":false,\"text\":\"En aquellos momentos, el diablo, que estaba delante de Leila-Fatimah, bajo la figura de Abraham, dijo á la infame virgen parricida:\"},{\"heading\":false,\"text\":\"--He cumplido tu voluntad, tu padre no te venderá al califa de Damasco, porque tu padre ha muerto.\"},{\"heading\":false,\"text\":\"Y la maldita parricida se levantó de sobre su diván, y esclamó:\"},{\"heading\":false,\"text\":\"--Al fin soy libre como las aves de la selva, y el aire del firmamento, y la luz del sol, soy sábia, y buscaré á mi amado y me uniré á él.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Al mismo tiempo, los médicos uno tras otro contrariados y cabizbajos, salieron de la casa.\"},{\"heading\":false,\"text\":\"Solo se quedó en ella Abraham, pálido, consternado y lloroso, velando los restos de su maestro.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XVI\",\"blocks\":[{\"heading\":false,\"text\":\"Al fin, el cadí y los ministros de justicia, fueron á la casa, y mandaron sacar el cadáver y sepultarle.\"},{\"heading\":false,\"text\":\"Abraham, se fué con la túnica rasgada, descalzo y con la cabeza baja en señal de luto tras el féretro do su maestro.\"},{\"heading\":false,\"text\":\"Cuando le enterraron, aun quedó en el cementerio sentado sobre el montecillo de tierra removida de su sepultura.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XVII\",\"blocks\":[{\"heading\":false,\"text\":\"Entre tanto, el cadí recorria la casa del difunto, y hacia inventario de sus riquezas.\"},{\"heading\":false,\"text\":\"Porque el médico, cuyo único pecado era la avaricia, habia amontonado inmensos tesoros.\"},{\"heading\":false,\"text\":\"Encontraron ánforas llenas las unas de oro acuñado, las otras de perlas, las otras de diamantes, y de piedras inestimables otras muchas.\"},{\"heading\":false,\"text\":\"Todo esto, lo habian encontrado en un sótano tapiado.\"},{\"heading\":false,\"text\":\"De buena gana el cadí se hubiera quedado con todo aquello, porque el difunto habia disimulado de tal modo por avaricia su riqueza, que todos le creian pobre.\"},{\"heading\":false,\"text\":\"Pero iban con él muchos ministros de justicia, y los dos esclavos negros, y la esclava cocinera del médico, y se vió obligado á ser justo y recto, y á hacer un fiel inventario.\"},{\"heading\":false,\"text\":\"--Gran herencia encuentra aquí el califa, dijo el cadí que creia que el médico habia muerto sin herederos.\"},{\"heading\":false,\"text\":\"--Te engañas, dijo uno de los esclavos, porque nuestro señor tiene una hija.\"},{\"heading\":false,\"text\":\"--Lo ignoraba, dijo el cadí con alegria, porque tratándose de un heredero muger, creyó que le seria facil abusar de su ignorancia y quedarse con parte de la herencia.\"},{\"heading\":false,\"text\":\"--Nada tiene de estraño que no lo supieras, dijo la esclava, porque mi señora es muy hermosa, y su padre la recataba mucho, y la tenia siempre encerrada de modo que ningun hombre la ha visto, ni ella ha visto á ningun hombre.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡ah! he ahí una buena crianza, dijo el cadí; vuestro amo era un varon sábio y justo y temeroso de Dios, y no hacia como esos padres que dejan ver á todos la hermosura de sus hijas, y comercian con su impureza. Y en verdad, en verdad, dijo el cadí que examinaba unos pergaminos del difunto, he aquí una escritura en que vuestro amo declara que tiene una hija llamado Leila-Fatimah (hermoso nombre), y declara para en el caso de que le sorprenda la muerte, que no tiene otro hijo y que esa doncella es la heredera de todas sus riquezas. ¿Quién habia de creer que vuestro señor era tan rico y que tenia por hija una tal joya?\"},{\"heading\":false,\"text\":\"Y el cadí se hizo conducir á las habitaciones de Leila-Fatimah, á la que encontró durmiendo apaciblemente ó fingiendo que dormia.\"},{\"heading\":false,\"text\":\"Sus esclavas doncellas que la servian tan emparedadas como ella, la despertaron y Leila salió soñolienta y admirada á recibir al cadí.\"},{\"heading\":false,\"text\":\"Al saber que su padre habia muerto, Leila fingió la mayor desesperacion; se mesó los cabellos, se rasgó los vestidos y maldijo la hora en que nació para ver morir á su padre.\"},{\"heading\":false,\"text\":\"Satanás, escondido en un rincon del retrete, se reia, enseñando sus negros colmillos, del fingido dolor de Leila-Fatimah.\"},{\"heading\":false,\"text\":\"Entrególa el cadí las riquezas de su padre, la saludó con las frases mas pomposas, la deseó fecundos consuelos, y llamándose su esclavo, salió de la casa con sus gentes.\"},{\"heading\":false,\"text\":\"Leila-Fatimah, protestando que queria quedarse enteramente sola para llorar á su padre y dejarse acabar por el sentimiento, dió á cada uno de sus esclavos la libertad y algunas monedas de oro, y los despidió.\"},{\"heading\":false,\"text\":\"Los esclavos salieron de la casa como los pájaros á quienes una mano compasiva abre la jaula donde han estado encerrados largo tiempo, y bendijeron la muerte del viejo médico, que aunque los habia tratado bien, porque no era malo, los habia tenido largos años enflaquecidos y hambrientos, porque era avaro.\"},{\"heading\":false,\"text\":\"Leila se quedó en su casa enteramente sola.\"},{\"heading\":false,\"text\":\"Entonces, valiéndose de su ciencia mágica, evocó al diablo.\"},{\"heading\":false,\"text\":\"--Aquí estoy, señora mia, dijo Satanás presentándose como siempre, bajo la figura de Abraham, ¿qué me quereis?\"},{\"heading\":false,\"text\":\"Leila fué á arrojarse entre sus brazos, pero el diablo se le huyó.\"},{\"heading\":false,\"text\":\"--¿Por qué no ha entrado hasta mí tu cuerpo con tu alma? dijo la enamorada jóven: ¿no están abiertas mis puertas?\"},{\"heading\":false,\"text\":\"--Yo no tengo cuerpo, dijo el diablo.\"},{\"heading\":false,\"text\":\"--¿Pues quién eres tú? dijo asombrada Leila-Fatimah.\"},{\"heading\":false,\"text\":\"--¿No te lo dice tu ciencia?\"},{\"heading\":false,\"text\":\"Leila se reconcentró, miró fijamente al diablo, y esclamó:\"},{\"heading\":false,\"text\":\"--¡Ah, tú eres Satanás!\"},{\"heading\":false,\"text\":\"--Al fin, me has mirado con los ojos de la ciencia y no con los del corazon, y me has reconocido.\"},{\"heading\":false,\"text\":\"--¿Y Abraham? dijo Leila.\"},{\"heading\":false,\"text\":\"--Está llorando sobre la sepultura de tu padre.\"},{\"heading\":false,\"text\":\"--¿Y no piensa en mí?\"},{\"heading\":false,\"text\":\"Abraham no te conoce.\"},{\"heading\":false,\"text\":\"--¿Pues no ha hablado su espíritu conmigo?\"},{\"heading\":false,\"text\":\"--He sido yo que he tomado su figura.\"},{\"heading\":false,\"text\":\"--¿Y no me amará Abraham?\"},{\"heading\":false,\"text\":\"--Sí, si tú quieres.\"},{\"heading\":false,\"text\":\"--Quiero presentarme á él como una hada.\"},{\"heading\":false,\"text\":\"--Hazlo, eres sábia.\"},{\"heading\":false,\"text\":\"--No puedo, yo soy sábia para hechizar, para enamorar, para matar; conozco el lenguaje de las estrellas, puedo obligarlas á que me digan lo que ha de suceder; pero no puedo trasladarme con el pensamiento á donde mejor quiera, no puedo trasformarme, no puedo construir en un momento un palacio, y yo lo quisiera hacer.\"},{\"heading\":false,\"text\":\"--Entre las joyas que ha dejado tu padre, hay un poderoso talisman.\"},{\"heading\":false,\"text\":\"--¿Y qué talisman es ese?\"},{\"heading\":false,\"text\":\"--Un abanico de oro, perlas y plumas. Búscale.\"},{\"heading\":false,\"text\":\"Leila fué al lugar donde estaba el tesoro que su padre habia amontonado, y despues de revolver mucho encontró un precioso abanico, formado de plumas de los mas raros colores, y como no habia visto ninguno de ninguna ave Leila: su mango era de oro con cercos de perlas, de diamantes y de rubíes, y este sujeto por una cadena de oro á un brazalete que se cerraba con una pequeña llave hecha de una esmeralda, pendiente del brazalete, que deslumbraba con la riqueza de sus piedras, por una sútil cadena.\"},{\"heading\":false,\"text\":\"--Tu padre prestó á un wazir muchos miles de doblas sobre ese abanico, el wazir se obligó á pagarle el préstamo en un tiempo dado, trascurrido el cual el abanico seria de tu padre.\"},{\"heading\":false,\"text\":\"El wazir habia robado su abanico del tesoro del califa, donde estaba de padres á hijos, desde que un ángel dió de parte de Dios ese talisman á Fatimah la santa, madre del Profeta.\"},{\"heading\":false,\"text\":\"Las plumas son de aves del paraiso, y el oro y las piedras, cogidas en los valles del Edém.\"},{\"heading\":false,\"text\":\"Un arcángel le fabricó, y Dios le dió la virtud que tiene.\"},{\"heading\":false,\"text\":\"El califa no solo no sabia la virtud de este talisman, sino que ni tampoco conocia su poder. El wazir creyéndole simplemente una alhaja de precio incomparable, le empeñó á tu padre, porque como lo habia robado al califa, no queria tenerlo en su poder.\"},{\"heading\":false,\"text\":\"Tu padre, le guardó entre sus tesoros, sin saber tampoco cuanta era su virtud.\"},{\"heading\":false,\"text\":\"Pero yo, que te he dado el filtro que ha apagado la vida de tu padre, te doy tambien ese talisman.\"},{\"heading\":false,\"text\":\"--¿Y cuál es su virtud? dijo Leila.\"},{\"heading\":false,\"text\":\"--No te lo diré si no me lo pagas.\"},{\"heading\":false,\"text\":\"--Ya te he dado mi alma por la vida de mi padre.\"},{\"heading\":false,\"text\":\"--Dame las almas de tus hijos.\"},{\"heading\":false,\"text\":\"--¡Oh! eso no.\"},{\"heading\":false,\"text\":\"--Pues bien, Abraham no te amará.\"},{\"heading\":false,\"text\":\"--Y si te doy mi descendencia...\"},{\"heading\":false,\"text\":\"--Abraham será tuyo.\"},{\"heading\":false,\"text\":\"--Pues te la doy.\"},{\"heading\":false,\"text\":\"--Firma aquí, dijo el diablo poniendo un pergamino escrito con fuego delante de los ojos de Leila-Fatimah: firma con tu sangre.\"},{\"heading\":false,\"text\":\"Leila se arrancó un alfiler de oro de su peinado, y se rasgó un dedo.\"},{\"heading\":false,\"text\":\"Corrió la sangre, y con ella firmó la jóven el escrito que el diablo le habia presentado, y que era una escritura solemne, por la cual Leila cedia su descendencia al espíritu de las tinieblas.\"},{\"heading\":false,\"text\":\"--Dime ahora la virtud de ese talisman.\"},{\"heading\":false,\"text\":\"--Tiene muchas: en primer lugar, á ese talisman obedece un génio.\"},{\"heading\":false,\"text\":\"--¿Y cómo he de hacerle aparecer?\"},{\"heading\":false,\"text\":\"--Cuando quieras hablarle, ponte el abanico primero sobre el corazon, luego sobre los ojos, y últimamente sobre la cabeza. Luego di por tres veces: génio esclavo del abanico de Fatimah la Santa, ven.\"},{\"heading\":false,\"text\":\"Leila, estaba impaciente por conocer la virtud del talisman, é hizo lo que el diablo le habia dicho.\"},{\"heading\":false,\"text\":\"Inmediatamente la habitacion en que la jóven estaba, se llenó de un humo rojo y denso, que se fué haciendo mas denso, hasta que se convirtió en una nubecilla; luego la nubecilla, cayó al suelo, se prolongó, se adelgazó, tomó formas, y apareció un hombrecillo, tal y tan diminuto, como el dedo índice de Leila, que era muy pequeñito.\"},{\"heading\":false,\"text\":\"Aquel hombrecillo, saltó del suelo y se asió al broche del seno de Leila, y la miró con unos ojillos relucientes y negros como los de un pequeño raton.\"},{\"heading\":false,\"text\":\"Era de color cobrizo, con la nariz larga, el rostro largo y la barba puntiaguda: tenia puesto un gorro dorado, y el diminuto cuerpo vestido con un sayo dorado, en la mano tenia una vara delgada y larga como una fina aguja, y en la punta de la vara un cascabel que sonaba, sonaba sin cesar; y el geniecillo se reia mirando á Leila-Fatimah.\"},{\"heading\":false,\"text\":\"Leila se desaferró del broche de diamantes de su seno, y al genio le puso sobre la palma de su mano.\"},{\"heading\":false,\"text\":\"--¿Qué quieres? la dijo el genio haciéndola un mohin y dando una cabriola y con una vocecita como la de un pájaro.\"},{\"heading\":false,\"text\":\"--Quiero un palacio mas rico que el del sultan de la India.\"},{\"heading\":false,\"text\":\"Inmediatamente Leila se encontró en un magnífico y resplandeciente alcázar, dentro de un pabellon desde el cual y entre columnas de resplandecientes mármoles, se veian torres y muros dorados, y mas allá de los muros, jardines y lagos y horizontes azules.\"},{\"heading\":false,\"text\":\"El diablo habia desaparecido.\"},{\"heading\":false,\"text\":\"El alcázar era sonoro.\"},{\"heading\":false,\"text\":\"Parecia exhalar de sí una música deliciosa que convidaba al sueño.\"},{\"heading\":false,\"text\":\"Anchos y blandos divanes ofrecian reposo.\"},{\"heading\":false,\"text\":\"Fuentes de aguas olorosas refrescaban y embalsamaban el ambiente.\"},{\"heading\":false,\"text\":\"Todo aquello era magnífico.\"},{\"heading\":false,\"text\":\"--Quiero que venga aquí el tesoro de mi padre, añadió Leila.\"},{\"heading\":false,\"text\":\"Anforas, cofres y sacos aparecieron en el centro del retrete.\"},{\"heading\":false,\"text\":\"--Quiero que guarde ese tesoro un arca de hierro pulimentado como un espejo, bellamente labrado, y que solo se abra cuando le toque yo.\"},{\"heading\":false,\"text\":\"Cubrió el tesoro una magnífica arca que deslumbraba por su brillantez, cerrada con siete candados y cubierta de peregrinas labores.\"},{\"heading\":false,\"text\":\"Leila llegó al arca, y al tocarla, el arca se abrió.\"},{\"heading\":false,\"text\":\"Cada parte del tesoro estaba en un compartimiento separado, aquí las perlas, acullá las piedras, cada una segun su género, y las monedas de oro y plata, cada una segun su valor.\"},{\"heading\":false,\"text\":\"--Quiero un bruñido espejo de plata, dijo Leila despues de haber cerrado el arca, y trasladádose á otra magnífica habitacion.\"},{\"heading\":false,\"text\":\"Apareció un espejo gigantesco de resplandeciente plata, en que se reprodujo enteramente la hermosa figura de la jóven.\"},{\"heading\":false,\"text\":\"--Quiero parecer mas niña, dijo Leila.\"},{\"heading\":false,\"text\":\"--¿Mas niña? esclamó el génio: eso no puede ser: aun no has cumplido los quince años y tu juventud es fuerte, rica, incomparable como el primer verdor de la primavera.\"},{\"heading\":false,\"text\":\"--Quiero parecer mas niña y ser mas muger, dijo Leila.\"},{\"heading\":false,\"text\":\"Y entonces, pareció como que su semblante resplandecia, como que sus ojos deslumbraban, como que sus cabellos se hacian mas finos y mas pesados y mas bellos sus rizos y mas negros: y se levantó su estatura, y se alzó su seno y sus brazos, y su cuello y las demás partes de su cuerpo, se volvieron tales, como solo Dios puede imaginar para hacer un ángel muger.\"},{\"heading\":false,\"text\":\"Y Leila-Fatimah, se veia desnuda en el espejo y sonreia orgullosa á aquella nueva hermosura que no habia desfigurado ni una sola de sus formas, porque Dios habia ya criado á Leila demasiado hermosa.\"},{\"heading\":false,\"text\":\"--Quiero que se peinen mis cabellos y se adornen de joyas, dijo Leila.\"},{\"heading\":false,\"text\":\"--Me estás convirtiendo en tu esclava, dijo el génio:\"},{\"heading\":false,\"text\":\"--Lo quiero.\"},{\"heading\":false,\"text\":\"Los hermosos cabellos de Leila, se trenzaron, rodearon su cabeza, cayeron en rizos y en lazos junto á sus megillas, y sobre sus hombros y sobre su seno, y entre ellos brillaban racimos de perlas y de diamantes y de rubíes y de corales, formando al rededor de su cabeza una como corona de hojas de vid con fruto.\"},{\"heading\":false,\"text\":\"--Quiero un hermoso collar para mi garganta y unas hermosas arracadas para mis orejas, y brazaletes y ajorcas para mis brazos y mis piernas.\"},{\"heading\":false,\"text\":\"El génio cumplió la voluntad de Leila.\"},{\"heading\":false,\"text\":\"Y no parecia sino que aquellas joyas habian sido buscadas á propósito para realzar la blancura y la belleza de la jóven.\"},{\"heading\":false,\"text\":\"--Quiero un ceñidor interior para mi cintura que defienda mi pureza y me haga invulnerable y fuerte, capaz de vencer á uno, á diez, á un cuento de caballeros armados.\"},{\"heading\":false,\"text\":\"--Te basta para eso con tu hermosura y con tus ojos, sultana, dijo el génio: ¡qué hermosa eres, señora mia! ¡qué hermosa! yo te amo.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡ah! ¡ah! dijo riendo la jóven, ¿y cómo harias tú para satisfacer tu amor?\"},{\"heading\":false,\"text\":\"El génio saltó de la mano al redondo y blanquísimo hombro de Leila, y la mordió en su incomparable cuello.\"},{\"heading\":false,\"text\":\"Leila dió un grito agudo, se puso de repente pálida como si no la hubiese quedado una sola gota de sangre en las venas, pero aquella palidez aumentó su hermosura.\"},{\"heading\":false,\"text\":\"Leila se sintió desfallecer.\"},{\"heading\":false,\"text\":\"Un ardiente fuego, el fuego de un volcán, llenaba sus venas, y la consumia.\"},{\"heading\":false,\"text\":\"Su vida se habia multiplicado.\"},{\"heading\":false,\"text\":\"El resplandor de su hermosura se habia hecho irresistible.\"},{\"heading\":false,\"text\":\"--Vuelve á mi mano, maldito, esclamó Leila.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡qué hermosa, qué hermosa eres, sultana mia! esclamó el génio volviendo de nuevo á la mano de la jóven. Tú no sabias el peligro que corrias conmigo, ¿no es verdad? dijo el génio. Pero ya no tiene remedio; tú tendrás siempre una sed inestinguible de amor, sufrirás eternamente el infierno de tu pecado, y amarás como no ha amado otra muger sobre la tierra.\"},{\"heading\":false,\"text\":\"--¿Y no veré satisfecho mi amor?\"},{\"heading\":false,\"text\":\"--Tú serás muy feliz durante algunos años, ¿pero que serán esos años? un instante, menos que un instante en la eternidad: Satanás ha sido muy cruel contigo: porque tú has sido muy cruel con tu padre.\"},{\"heading\":false,\"text\":\"--¿Quién se acuerda ahora de aquel viejo avaro que me tenia emparedada?\"},{\"heading\":false,\"text\":\"--Dices bien: ¿á qué acordarse de eso? tu padre duerme tranquilo en la tumba.\"},{\"heading\":false,\"text\":\"--Quiero ver á mi adorado, dijo Leila dejándose caer sobre un diván.\"},{\"heading\":false,\"text\":\"--¿Y vas á recibirle así? es virtuoso y casto, y tu desnudez le sonrojaria.\"},{\"heading\":false,\"text\":\"--Vísteme de túnicas de luz, dijo Leila.\"},{\"heading\":false,\"text\":\"Inmediatamente lucientes y finísimas túnicas cubrieron á la jóven.\"},{\"heading\":false,\"text\":\"Leila entonces parecia un astro caido del firmamento.\"},{\"heading\":false,\"text\":\"Pero sus resplandores no ofendian á la vista.\"},{\"heading\":false,\"text\":\"--Quiero ver á mi amado, ¿dónde está?\"},{\"heading\":false,\"text\":\"--Llorando sobre la tumba de tu padre.\"},{\"heading\":false,\"text\":\"--Que se sequen sus lágrimas, y que sienta mi amor en su corazon.\"},{\"heading\":false,\"text\":\"--Ya no llora y se estremece dulcemente alhagado por un fuego desconocido.\"},{\"heading\":false,\"text\":\"--Ahora, llévame con mi palacio á Damasco.\"},{\"heading\":false,\"text\":\"--Mira por aquella ventana, ¿qué vés?\"},{\"heading\":false,\"text\":\"--Veo fuertes torres á la luz de la luna, dijo Leila.\"},{\"heading\":false,\"text\":\"--Aquel es el alcázar del califa.\"},{\"heading\":false,\"text\":\"--Veo á los pies de la altura donde está ese alcázar una ciudad cubierta por la sombra.\"},{\"heading\":false,\"text\":\"--Esa ciudad es Damasco. ¿Qué mas quieres?\"},{\"heading\":false,\"text\":\"--Quiero que al despertar mañana, el califa vea mi resplandeciente palacio; que lo vean desde la ciudad, y que vean esclavos en sus pórticos, y que dentro haya bailarinas que me alegren, y doncellas que me sirvan, y músicos que me recreen.\"},{\"heading\":false,\"text\":\"--Mira, dijo el génio; ¿vés allá entre las quebraduras de una distante sierra una lucecita?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Sabes dónde arde esa lucecita?\"},{\"heading\":false,\"text\":\"--No.\"},{\"heading\":false,\"text\":\"--Voy á mostrártelo.\"},{\"heading\":false,\"text\":\"--Leila, se encontró en una cabaña miserable; en ella un anciano y un jóven lloraban desconsoladamente junto á una muger jóven y hermosa, pero enferma y enflaquecida, que moria.\"},{\"heading\":false,\"text\":\"--¿Y á qué me has traido aquí? dijo Leila.\"},{\"heading\":false,\"text\":\"--Escucha, esas pobres gentes son labradores.\"},{\"heading\":false,\"text\":\"--¿Y qué me importa?\"},{\"heading\":false,\"text\":\"--Escucha, los años anteriores han sido malos, no solo no han podido esos infelices pagar su tributo al califa, sino que se han privado de lo mas necesario; hace quince dias que los encargados de cobrar las contribuciones del califa, fueron á esa choza, y á pesar de las lágrimas de esa familia, se llevaron los dos jumentillos con que araban sus tierras, su cabra, sus semillas y hasta su lecho; esa familia hace quince dias que está hambrienta; el padre y el hijo se han sustentado con yerbas y raices, pero la pobre Haraxa, no ha podido resistir y muere entre los brazos de su padre y de su esposo. Invocan á Dios, ¿no los oyes? tú tienes poder; díme: levanta del suelo á esa muger, y la levanto; dales pan y medios de vivir y de ser felices, y se lo doy; ¿no ves lo que pende del pecho de esa desgraciada? un niño que procura amamantarse del pecho exhausto y no puede.\"},{\"heading\":false,\"text\":\"--¿Y que tengo yo que ver con eso? dijo con dureza Leila; yo me abraso de amor. Llévame á mi alcázar.\"},{\"heading\":false,\"text\":\"--Héte en él, pero no tienes caridad: Dios, que hizo ese talisman de que soy esclavo, le construyó para la santa Madre de su Enviado, ¡oh, y cuán diferente uso hacia en su poder aquella alma noble!\"},{\"heading\":false,\"text\":\"--Calla.\"},{\"heading\":false,\"text\":\"--Un momento, señora mia: lo que tú no has querido hacer con una pobre familia lo ha hecho Dios; los habia castigado porque la prosperidad los habia hecho un tanto soberbios, los habia reducido á esa cabaña, á esa desdicha. Pero han invocado con fé á Dios, eran buenos, y Dios los ha enviado un ángel en figura de peregrino.\"},{\"heading\":false,\"text\":\"Con el ángel, ha entrado la Providencia de Dios en la cabaña.\"},{\"heading\":false,\"text\":\"Han tenido alimento, y el ángel les ha dejado al partir un saco lleno de oro.\"},{\"heading\":false,\"text\":\"--Has que venga naturalmente atraido á mi, mi adorado Abraham, dijo Leila.\"},{\"heading\":false,\"text\":\"--Tú no tienes caridad. Hélo aquí que viene.\"},{\"heading\":false,\"text\":\"--Vete, dijo Leila.\"},{\"heading\":false,\"text\":\"El génio saltó de la mano al suelo, y desapareció como habia aparecido, desvaneciéndose en humo.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XVIII\",\"blocks\":[{\"heading\":false,\"text\":\"--¿Sabes hermana culebra, que tu cuento me está maravillando? dijo el lagarto. ¿Crees tú que eso pueda haber sucedido?\"},{\"heading\":false,\"text\":\"--Eso y mucho mas puede hacer Dios, que es Todopoderoso, hermano lagarto.\"},{\"heading\":false,\"text\":\"--Sí, sí, pero esa muger endemoniada....\"},{\"heading\":false,\"text\":\"--Dios la castigaba con sus mismas pasiones. Cuando el alma de Abraham, que está allá abajo penando donde tú no te has atrevido á bajar, me contaba esto, la desdichada alma se estremecia.\"},{\"heading\":false,\"text\":\"--Sigue, hermana culebra, sigue; tengo impaciencia por saber el fin del cuento.\"},{\"heading\":false,\"text\":\"--Pues escucha, hermano lagarto, y aprende y escarmienta.\"},{\"heading\":false,\"text\":\"--Yo, añadió la golondrina, hermano ruiseñor, escuchaba sin dormirme aunque estaba muy cansada.\"},{\"heading\":false,\"text\":\"--Como te escucho yo, amiga golondrina, dijo el ruiseñor, y como te escucha esa maldita Asenéth, que como Leila-Fatimah, quiere matar á su padre por gozar sus amores.\"},{\"heading\":false,\"text\":\"--¡Oh! esclamó Asenéth, pájaros habladores, seguid, seguid vuestro cuento de los amores de la maga con el judío Abraham, mi abuelo.\"},{\"heading\":false,\"text\":\"La golondrina, calló un momento como quien recuerda, y luego continuó:\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XIX\",\"blocks\":[{\"heading\":false,\"text\":\"La culebra siguió diciendo á su amigo el lagarto:\"},{\"heading\":false,\"text\":\"--Entre tanto, el buen Abraham, que habia dejado de llorar de repente, y se habia sentido inflamar por un fuego dulce y desconocido, olvidó enteramente á su protector, y saliendo del cementerio montó en su asno, y se volvió hácia un lugar donde le llamaba una fuerza misteriosa que le atraia, le atraia, sin que fuese poderoso á contrarestarla y sin saber á dónde.\"},{\"heading\":false,\"text\":\"Y el asno andaba con la velocidad del Borac[93], y la tierra se quedaba rápidamente atrás, y parecia un rio que huia.\"},{\"heading\":false,\"text\":\"Y antes del amanecer, Abraham se encontró no lejos de una populosa ciudad y á la puerta de un jardin deleitoso.\"},{\"heading\":false,\"text\":\"En medio del estensísimo jardin, habia un palacio resplandeciente que arrojaba sobre el jardin y sobre los montes una luz diáfana, mas diáfana que la de la aurora.\"},{\"heading\":false,\"text\":\"El asno se detuvo en la puerta del jardin, levantó la cabeza, abrió sus narices al viento y rebuznó.\"},{\"heading\":false,\"text\":\"En el momento se abrió la puerta del jardin, y aparecieron muchos esclavos negros.\"},{\"heading\":false,\"text\":\"--¿Eres tú, dijeron, el sábio médico á quien nuestra señora espera?\"},{\"heading\":false,\"text\":\"--¿Y quién es vuestra señora? Yo al ver la hermosura de estos sitios y los resplandores de aquel palacio, habia creido que Dios el Misericordioso, me mostraba su jardin de Hiram.\"},{\"heading\":false,\"text\":\"--Estos no son los jardines de Hiram, sino los de nuestra señora, que está enferma y te espera.\"},{\"heading\":false,\"text\":\"--¿Es acaso la sultana de este imperio vuestra señora?\"},{\"heading\":false,\"text\":\"--Nuestra señora es la poderosa maga Leila-Fatimah.\"},{\"heading\":false,\"text\":\"Al oir la palabra maga, Abraham invocó á Dios, y le invocó tan de corazon, que fueron inútiles para con él en aquel momento los hechizos de Leila-Fatimah.\"},{\"heading\":false,\"text\":\"Revolvió su asno, y escapó á cuanto correr pudo el asno por la campiña.\"},{\"heading\":false,\"text\":\"El cuadrúpedo tomó por una senda, y al fin de ella se paró delante de un humilde edificio.\"},{\"heading\":false,\"text\":\"--Loado sea Dios, que me trae á su santa casa, dijo Abraham.\"},{\"heading\":false,\"text\":\"En efecto, el asno se habia detenido en una pequeña mezquita, donde hacia penitencia un hombre de Dios, un santo morabitho.\"},{\"heading\":false,\"text\":\"Abraham descabalgó de su asno, y entró en la mezquita.\"},{\"heading\":false,\"text\":\"El morabitho estaba prosternado delante del mirab.\"},{\"heading\":false,\"text\":\"Prosternose tambien Abraham, y oró.\"},{\"heading\":false,\"text\":\"Cuando se levantó, vió delante de sí al morabitho, que era un anciano de barba blanca.\"},{\"heading\":false,\"text\":\"--¿Qué buscas ante Dios? dijo el morabitho.\"},{\"heading\":false,\"text\":\"--La tentacion me ha acometido, hermano, dijo Abraham, cuando oraba esta noche sobre la sepultura de mi padre.\"},{\"heading\":false,\"text\":\"--Dios solo es veráz, y Satanás es pérfido; lleno de lazos tendidos por el demonio está el camino de la vida: dichosos los que, como tú, acuden en sus tribulaciones á Dios.\"},{\"heading\":false,\"text\":\"--Es que me siento vacilar, hermano mio.\"},{\"heading\":false,\"text\":\"--¿Qué te dice el diablo?\"},{\"heading\":false,\"text\":\"--Ha llenado de amor mi corazon.\"},{\"heading\":false,\"text\":\"--Amar puede el hombre; para él ha nacido la muger.\"},{\"heading\":false,\"text\":\"--Pero mi amor es ardiente, desenfrenado.\"},{\"heading\":false,\"text\":\"--Recurre á la penitencia.\"},{\"heading\":false,\"text\":\"--Mi corazon vacila.\"},{\"heading\":false,\"text\":\"--Véncele.\"},{\"heading\":false,\"text\":\"--¿Querrás consultar la voluntad de Dios en las estrellas, hermano?\"},{\"heading\":false,\"text\":\"--Las consultaré por tu amor, porque te veo lleno de tribulacion.\"},{\"heading\":false,\"text\":\"--Dios te lo pagará.\"},{\"heading\":false,\"text\":\"--Quédate entre tanto conmigo, bajo el amparo de la casa de Dios.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XX\",\"blocks\":[{\"heading\":false,\"text\":\"Entretanto, Leila se paseaba furiosa por el magnífico alcázar, viendo que Abraham se le huia.\"},{\"heading\":false,\"text\":\"Consultaba al génio esclavo del abanico de Fatimah la Santa, y el génio se le reia diciéndole que no podia nada contra Dios.\"},{\"heading\":false,\"text\":\"--Pero Abraham saldrá alguna vez de la mezquita, decia la enamorada maga.\"},{\"heading\":false,\"text\":\"--Cuando salga te prometo traértelo. Entretanto, y para que te diviertas, te voy á traer al califa que se ha asombrado al ver levantarse desde sus miradores este magnífico alcázar que yo he construido para tí.\"},{\"heading\":false,\"text\":\"--En efecto, el califa al ver aquellas altas torres, y aquellos magníficos jardines que el dia anterior no existian delante de su palacio afrentándole con su hermosura, llamó á los sábios y les dijo:\"},{\"heading\":false,\"text\":\"--¿Qué alcázar es aquel resplandeciente que se levanta sobre un monte donde ayer era un llano cubierto de viñas?\"},{\"heading\":false,\"text\":\"Los sábios miraron y se restregaron los ojos, porque dudaban.\"},{\"heading\":false,\"text\":\"Y del mismo modo las gentes de Damasco se asomaban á los terrados de sus casas, maravilladas de aquello.\"},{\"heading\":false,\"text\":\"Y los sábios dijeron al califa:\"},{\"heading\":false,\"text\":\"--Artes mágicas debe haber en esto, porque ni los hombres pueden hacer una obra tan grande en tan poco tiempo, ni el mas sábio trabajando toda su vida podria idear una obra tan magnífica.\"},{\"heading\":false,\"text\":\"El califa envió á su wazir para que se informara de aquello.\"},{\"heading\":false,\"text\":\"El wazir volvió asombrado y enloquecido.\"},{\"heading\":false,\"text\":\"--No vayas, señor, le dijo, á ese alcázar, porque en él encontrarás una muger tal y tan hermosa que perderás tu alma.\"},{\"heading\":false,\"text\":\"Esto mismo incitó con mas fuerza al califa para ver aquella peregrina hermosura que, como una perla en su concha, se escondia en una obra tan magnífica.\"},{\"heading\":false,\"text\":\"Hízose preceder por sus esclavos, montó en un caballo blanco, y precedido de su córte se encaminó al alcázar misterioso.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XXI\",\"blocks\":[{\"heading\":false,\"text\":\"--Hé aquí que el califa de Oriente se acerca, dijo el geniecillo a Leila-Fatimah. Mira si quieres ser sultana.\"},{\"heading\":false,\"text\":\"--Por Abraham maté á mi padre, y solo de Abraham seré, dijo la vírgen maldita.\"},{\"heading\":false,\"text\":\"--¿Pero no recibirás al califa?\"},{\"heading\":false,\"text\":\"--Sí, le recibiré, y le enloqueceré, para que me sirva.\"},{\"heading\":false,\"text\":\"--Pues ya se acerca.\"},{\"heading\":false,\"text\":\"--Vete, pues.\"},{\"heading\":false,\"text\":\"Poco despues, un esclavo eunuco tocaba con una varita de oro á la puerta del retrete de la jóven.\"},{\"heading\":false,\"text\":\"Levantóse ésta del diván, abrió la puerta, y al verla tan resplandeciente y tan hermosa, el califa su prosternó.\"},{\"heading\":false,\"text\":\"--¡Levántate, Walid, emir de los creyentes, dijo Leila; y no te prosternes ante tu esclava!\"},{\"heading\":false,\"text\":\"Y alzó al sultan.\"},{\"heading\":false,\"text\":\"Luego cerró la puerta y se quedó sola con él.\"},{\"heading\":false,\"text\":\"Walid, que aun era mancebo, desfallecia de amor.\"},{\"heading\":false,\"text\":\"Leila le hizo sentarse en el diván, y se sentó junto á él.\"},{\"heading\":false,\"text\":\"--Clara y dichosa ha sido el alba en que has aparecido junto á Damasco, cabeza de mi imperio, sultana de las huríes, dijo el califa. ¿Por qué has venido á alegrar esta tierra con tu hermosura?\"},{\"heading\":false,\"text\":\"--Venia á buscarte, señor.\"},{\"heading\":false,\"text\":\"--¡A buscarme! ¿será acaso que Dios se ha propuesto premiarme por mi fé y por mis victorias contra los infieles, y me envia un pedazo de su paraiso, y con él un arcángel del sétimo cielo?\"},{\"heading\":false,\"text\":\"--Dios me envia á salvarte, señor.\"},{\"heading\":false,\"text\":\"--¿A salvarme dándome tu amor?\"},{\"heading\":false,\"text\":\"Mi amor no puede ser de los hombres de la tierra.\"},{\"heading\":false,\"text\":\"Walid se prosternó.\"},{\"heading\":false,\"text\":\"--¡Oh! poderoso génio, esclamó: ¿por qué te han visto mis ojos, si no ha de ser mia tu hermosura?\"},{\"heading\":false,\"text\":\"--No pienses en el amor, cuando Dios me envia á salvar tu imperio.\"},{\"heading\":false,\"text\":\"--¿A salvar mi imperio?\"},{\"heading\":false,\"text\":\"--Si los hijos de Abbas despliegan en silencio la sangrienta bandera contra los hijos de Omeya: ¡ay de tí, y ay de los tuyos, si yo por mandado de Dios no te revelase la traicion que se acerca á ti en silencio!\"},{\"heading\":false,\"text\":\"--¡Habla, poderoso génio! dijo Walid, aterrado por aquella oscura profecía.\"},{\"heading\":false,\"text\":\"--Ven acá, dijo Leila, llevándole á un mirador: ¿ves aquella mezquita en el valle junto á la vertiente de la montaña?\"},{\"heading\":false,\"text\":\"--Allí mora un santo.\"},{\"heading\":false,\"text\":\"--Allí mora la traicion.\"},{\"heading\":false,\"text\":\"--¿La traicion dices?\"},{\"heading\":false,\"text\":\"--Sí, en aquella mezquita se oculta un sábio médico llamado Abraham, que viene á alentar á los partidarios de Abul-Abbas.\"},{\"heading\":false,\"text\":\"--¿Y qué he de hacer, poderoso génio?\"},{\"heading\":false,\"text\":\"--Escucha; cuando medie la noche, rodearás tú mismo con tus gentes aquella mezquita.\"},{\"heading\":false,\"text\":\"--Lo haré.\"},{\"heading\":false,\"text\":\"--Sacarás fuera al morabitho y al hebreo Abraham.\"},{\"heading\":false,\"text\":\"--Lo haré.\"},{\"heading\":false,\"text\":\"--Despues te llevarás á esos dos traidores á la alcazaba, y los encerrarás en una mazmorra.\"},{\"heading\":false,\"text\":\"Sí, ¿y luego?\"},{\"heading\":false,\"text\":\"--Luego... mira... primero crucificarás al morabitho.\"},{\"heading\":false,\"text\":\"--¿Y despues?\"},{\"heading\":false,\"text\":\"--Despues cortarás por ti mismo la cabeza, y á solas con él encerrado en su mazmorra, al hebreo Abraham.\"},{\"heading\":false,\"text\":\"--¿Y habré salvado mi corona?\"},{\"heading\":false,\"text\":\"--Tu corona, tu familia y tus parciales.\"},{\"heading\":false,\"text\":\"--¿Y despues no me amarás tú?\"},{\"heading\":false,\"text\":\"--Consiste eso en la voluntad de Dios.\"},{\"heading\":false,\"text\":\"--¡Oh! yo serviré de tal modo á Dios, que Dios me recompensará dándome tu amor.\"},{\"heading\":false,\"text\":\"--Sí, yo te amo... dijo lánguidamente Leila.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡sol ardiente de mi alma! esclamó Walid.\"},{\"heading\":false,\"text\":\"--Pero no te daré mi amor hasta que hayas esterminado á los traidores y á los impíos.\"},{\"heading\":false,\"text\":\"--¡Oh! pues los esterminaré.\"},{\"heading\":false,\"text\":\"Y el califa y Leila siguieron hablando familiarmente hasta la caida de la tarde.\"},{\"heading\":false,\"text\":\"Walid cada vez mas enamorado: Leila cada vez mas traidora con él.\"},{\"heading\":false,\"text\":\"Pero á pesar de su amor, Walid se sentia dominado, sujeto por un poder invencible.\"},{\"heading\":false,\"text\":\"Y era que protegia la pureza de Leila el cíngulo mágico que rodeaba su cintura.\"},{\"heading\":false,\"text\":\"El califa salió del alcázar de Leila al empezar la noche, afirmándola que haria pedazos á los traidores y que volveria al dia siguiente.\"},{\"heading\":false,\"text\":\"Cuando el califa salió, Leila-Fatimah se puso el abanico sobre el corazon, sobre los ojos y sobre la cabeza, y llamó al génio.\"},{\"heading\":false,\"text\":\"El génio acudió.\"},{\"heading\":false,\"text\":\"--El califa sacará á la media noche á Abraham de la casa de Dios, le dijo: prepárate á hacerle venir.\"},{\"heading\":false,\"text\":\"--¿Y vendrá?\"},{\"heading\":false,\"text\":\"--Vendrá.\"},{\"heading\":false,\"text\":\"Ahora prepárame mi aposento nupcial, y aumenta mis galas y mi hermosura.\"},{\"heading\":false,\"text\":\"El geniecillo al escuchar aquel mandato, soltó una carcajada tal, y tan siniestra, que aterró á Leila.\"},{\"heading\":false,\"text\":\"--¿Por qué te ries, dijo la maga?\"},{\"heading\":false,\"text\":\"--Me rio por la locura de tu amor, contestó el génio: pero ya he hecho tu cámara nupcial, y he aumentado tu hermosura y tus galas: ven á ver mi obra, y á mirar tu belleza.\"},{\"heading\":false,\"text\":\"Y ella fué á examinar aquel nuevo milagro del génio.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XXII\",\"blocks\":[{\"heading\":false,\"text\":\"Llegaba la media noche.\"},{\"heading\":false,\"text\":\"El anciano morabitho de la mezquita del valle, consultaba tristemente las estrellas.\"},{\"heading\":false,\"text\":\"Junto á él estaba Abraham.\"},{\"heading\":false,\"text\":\"--El espíritu del mal te persigue, dijo el morabitho al hebreo.\"},{\"heading\":false,\"text\":\"--¿Y cómo podré conjurarle? dijo este.\"},{\"heading\":false,\"text\":\"--La muerte se acerca: si la arrostras sin temblar serás salvado, pero si no caerás en poder de Satanás y te perderás.\"},{\"heading\":false,\"text\":\"--¿Y no hablan mas claro las estrellas?\"},{\"heading\":false,\"text\":\"--Las estrellas hablan siempre misteriosamente; pues te avisan de un peligro y te dan el medio de conjurarlo; ese medio es morir con el valor de un mártir sin estremecerte ante la muerte.\"},{\"heading\":false,\"text\":\"--Voy á orar, dijo Abraham, para que Dios me dé su fortaleza.\"},{\"heading\":false,\"text\":\"--Oremos juntos, hermano, dijo el morabitho, porque la hora de la tribulacion se acerca para los dos.\"},{\"heading\":false,\"text\":\"--Y entraron en la mezquita y entrambos se prosternaron ante el mirab.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XXIII\",\"blocks\":[{\"heading\":false,\"text\":\"Poco tiempo despues llamaron á la puerta.\"},{\"heading\":false,\"text\":\"--Hé ahí la muerte, dijo el morabitho.\"},{\"heading\":false,\"text\":\"--Abrid al califa magnífico y vencedor, dijo fuera una voz robusta.\"},{\"heading\":false,\"text\":\"--El momento ha llegado, dijo el morabitho á Abraham, valor y fé en Dios, y dentro de poco tiempo nos encontraremos juntos en el paraiso.\"},{\"heading\":false,\"text\":\"--Moriré como un mártir, dijo Abraham; vé, y abre al califa, hermano.\"},{\"heading\":false,\"text\":\"El morabitho abrió.\"},{\"heading\":false,\"text\":\"Walid se arrojó frenético dentro de la mezquita, y dijo á los esclavos que le seguian:\"},{\"heading\":false,\"text\":\"--¡Apoderaos de esos dos traidores, y cargadlos de cadenas!\"},{\"heading\":false,\"text\":\"Abraham y el morabitho fueron conducidos á la alcazaba del califa, y arrojados en profundas mazmorras.\"},{\"heading\":false,\"text\":\"Abraham sin temor estuvo orando á Dios.\"},{\"heading\":false,\"text\":\"Sentia, sin embargo, en su alma un combate rudo que no era terror á la muerte.\"},{\"heading\":false,\"text\":\"Parecíale que una voz poderosa le llamaba, y que una fuerza irresistible tiraba de él.\"},{\"heading\":false,\"text\":\"Era que Leila, viéndole fuera de la casa de Dios, donde únicamente estaba protegido por sus encantos, compelia al génio á que le trajese á sí.\"},{\"heading\":false,\"text\":\"Pero Abraham, tenia fijo el pensamiento en Dios, no le habia asaltado el temor de la muerte, y Dios le amparaba.\"},{\"heading\":false,\"text\":\"Pero de repente se oyeron gemidos de agonía.\"},{\"heading\":false,\"text\":\"Gemidos horribles.\"},{\"heading\":false,\"text\":\"Y junto á los gemidos, gritos y risas de verdugos.\"},{\"heading\":false,\"text\":\"Era que crucificaban al morabitho.\"},{\"heading\":false,\"text\":\"Al oir aquellos lastimosos gemidos, Abraham dejó de orar.\"},{\"heading\":false,\"text\":\"Un terror vago empezó á apoderarse de él.\"},{\"heading\":false,\"text\":\"De repente se abrió la puerta de la mazmorra, y unos feroces esclavos entraron con un hornillo encendido y unos hierros de forma horrorosa.\"},{\"heading\":false,\"text\":\"Entonces Abraham temió á la muerte, y esclamó:\"},{\"heading\":false,\"text\":\"--¿Acaso no se habrá engañado el morabitho? y llegó... yo no quiero morir...\"},{\"heading\":false,\"text\":\"Apenas habia pronunciado estas palabras, cuando se encontró en una magnífica y resplandeciente cámara nupcial delante de Leila, cuya hermosura era tal, como la de un arcángel.\"},{\"heading\":false,\"text\":\"Abraham creyó que le habian matado en la mazmorra, y que se encontraba en el paraiso delante de su hurí.\"},{\"heading\":false,\"text\":\"--Sí, sí, dijo Leila; has muerto y eres mio.\"},{\"heading\":false,\"text\":\"Pero quítame mi cingulo de pureza, porque de otro modo no podré ser tuya.\"},{\"heading\":false,\"text\":\"Y se abrió sus magníficas túnicas, dejando descubierto el cingulo que tenia sobre su cintura desnuda.\"},{\"heading\":false,\"text\":\"Abraham se arrodilló, y quitó el cingulo á Leila.\"},{\"heading\":false,\"text\":\"En aquel momento se oyó un estruendo pavoroso como el de un inmenso edificio que se desplomara: oyóse una carcajada horrible, y la voz de Satanás que dijo:\"},{\"heading\":false,\"text\":\"--Has perdido el talisman de la madre del profeta por tu impureza, y al derrocarse el alcázar de tus locos deseos, se ha sepultado con él el tesoro que habia reunido la avaricia de tu padre.\"},{\"heading\":false,\"text\":\"--Pero Abraham es tuyo.\"},{\"heading\":false,\"text\":\"--Suya eres tú.\"},{\"heading\":false,\"text\":\"--Y bien: su amor me basta, esclamó Leila-Fatimah.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XXIV\",\"blocks\":[{\"heading\":false,\"text\":\"Encontróse de repente Abraham caminando entre montañas, llevando delante su asno, y sobre su asno una muger hermosísima y sencillamente vestida.\"},{\"heading\":false,\"text\":\"Abraham habia perdido completamente la memoria de lo que le habia acontecido.\"},{\"heading\":false,\"text\":\"Del mismo modo la habia perdido Leila-Fatimah.\"},{\"heading\":false,\"text\":\"Pero Abraham se abrasaba en los amores de ella, y ella en los amores de él.\"},{\"heading\":false,\"text\":\"Aquel amanecer llegaron á Damasco.\"},{\"heading\":false,\"text\":\"Abraham tomó una casita en los arrabales de la ciudad, y empezó á curar como médico.\"},{\"heading\":false,\"text\":\"Y como era muy sábio, adquirió una gran fama, y le llamaron los mas ricos, y le pagaron maravillosamente sus curas.\"},{\"heading\":false,\"text\":\"Antes del año de haberse unido Abraham y Leila-Fatimah, ésta dió á luz un niño.\"},{\"heading\":false,\"text\":\"Aquel niño se llamó Jamné.\"},{\"heading\":false,\"text\":\"Púsose enfermo el califa, y de tal modo y con una enfermedad tan estraña, que los médicos de la córte no atinaban con ella.\"},{\"heading\":false,\"text\":\"Al fin fué llamado Abraham.\"},{\"heading\":false,\"text\":\"Y Abraham, despues de muchos dias, restituyó su salud al califa.\"},{\"heading\":false,\"text\":\"Y el califa dió á Abraham, en premio de su curacion, un palacio con jardines dentro del mismo Damasco, y muchos miles de mitcales de oro.\"},{\"heading\":false,\"text\":\"Y entonces dijo Leila á Abraham:\"},{\"heading\":false,\"text\":\"--Oye, amado mio, el oficio de médico es trabajoso: ir de acá para allá, correr todo el dia; levantarte de noche de entre mis brazos para ir á curar dolencias... te tengo muy poco tiempo á mi lado, y yo te amo mucho, con toda mi alma, y quisiera estar siempre á tu lado.\"},{\"heading\":false,\"text\":\"--¿Y qué hemos de hacer?\"},{\"heading\":false,\"text\":\"--Deja de curar á otro que al califa: pídele licencia para vender el palacio que te ha dado, y que es muy grande y demasiado magnífico para nosotros, y con el dinero de la venta del palacio, y el que te ha dado el califa, compremos joyas y ricas telas y perfumes, y pongamos una tienda: yo atraeré á los magnates, que comprarán sin escusar el precio por hablar conmigo, y además prestaremos con usura y nos pondremos muy ricos.\"},{\"heading\":false,\"text\":\"--Pero eso es ofender á Dios.\"},{\"heading\":false,\"text\":\"--Yo no tengo mas Dios que tú, y además, tenemos un hijo.\"},{\"heading\":false,\"text\":\"--Lo pensaré, dijo Abraham.\"},{\"heading\":false,\"text\":\"Abraham hasta entonces era inocente: no habia ofendido á Dios; creia haber encontrado en un camino sola y abandonada á una hermosa y casta doncella que habia huido de casa de unos parientes codiciosos que querian venderla, porque habia olvidado lo del encanto y aquel resplandeciente alcázar donde habia quitado su cíngulo de pureza á Leila-Fatimah, que al perder el talisman no habia perdido su ciencia y habia engañado á Abraham. Este se habia casado con ella y habia seguido siendo bueno y compasivo.\"},{\"heading\":false,\"text\":\"Cuando Leila le propuso que aumentara su dinero con la usura, Abraham, que amaba ciegamente á su esposa, vaciló; pero aun le quedaba temor de Dios, y consultó á los astrólogos.\"},{\"heading\":false,\"text\":\"Estos, uno tras otro, hasta siete, á quienes buscó, le dijeron una misma cosa.\"},{\"heading\":false,\"text\":\"--Esto es: sepárate de tu muger, que le perderá: porque es un espíritu maldito vendido al diablo.\"},{\"heading\":false,\"text\":\"Pero creia tan buena y tan inocente á su esposa Abraham, que creyó mas bien que los astrólogos eran unos ignorantes, que no que decian la verdad, y despreció sus avisos.\"},{\"heading\":false,\"text\":\"Desde aquel momento pecó Abraham desoyendo las revelaciones de Dios.\"},{\"heading\":false,\"text\":\"Y como amaba á Leila-Fatimah, sobre todas las cosas, cedió al fin á sus halagos; vendió con licencia del califa en una gran cantidad á un príncipe de Persia el palacio que el califa le habia regalado, y con este dinero, y el que antes tenia, compró púrpuras, y sedas, y brocados, y perfumes, y alhajas, y puso una hermosa tienda en el bazar de Damasco.\"},{\"heading\":false,\"text\":\"Al mismo tiempo se negó á curar á todo el mundo, menos al califa, lo que fué una falta de caridad, y se pasaba los dias enteros en el fondo de la tienda, sobre una tarima y una alfombrilla, mascando opio, jugando sobre sus rodillas con su pequeñuelo Jamné, y tocando la guitarra, mientras Leila escitaba con sus miradas á los hombres poderosos que pasaban por delante de su tienda, y que compraban muy caro el breve placer de hablar algun tiempo con la hermosísima mercadera.\"},{\"heading\":false,\"text\":\"A puestas del sol se cerraba la tienda, y los dos esposos comian espléndidamente, bebian contra la ley licores espirituosos, y luego se entregaban á un amor desenfrenado.\"},{\"heading\":false,\"text\":\"Su oro se habia aumentado y se aumentaba cada dia mas, por medio de la usura.\"},{\"heading\":false,\"text\":\"Desde muy pequeñito, Leila á hurtadillas de su padre, enseñaba á su hijo su ciencia maldita.\"},{\"heading\":false,\"text\":\"Los dos esposos estaban continuamente ofendiendo á Dios.\"},{\"heading\":false,\"text\":\"Pero se amaban de una manera tal, que eran felices.\"},{\"heading\":false,\"text\":\"Las artes mágicas de Leila-Fatimah aumentaban cada dia el amor de Abraham.\"},{\"heading\":false,\"text\":\"Y así pasaron seis años, durante los cuales, Leila no tuvo mas hijos.\"},{\"heading\":false,\"text\":\"Pero al empezar el sétimo se encontró en cinta.\"},{\"heading\":false,\"text\":\"Al cumplirse los siete años del nacimiento de Jamné, Leila dió á luz una niña.\"},{\"heading\":false,\"text\":\"Aquella niña se llamó Zelpha.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XXV\",\"blocks\":[{\"heading\":false,\"text\":\"Pasaron otros siete años, durante los cuales se multiplicó la riqueza de los dos esposos.\"},{\"heading\":false,\"text\":\"Leila por medio de su ciencia hacia que siempre apareciese para ella jóven y buen mozo Abraham, y que ella pareciese á Abraham hermosísima; pero no sucedia lo mismo con los estraños.\"},{\"heading\":false,\"text\":\"Leila, en verdad, aparecia cada vez mas hermosa; pero Abraham, gastado por los placeres y por los licores, parecia ya un viejo decrépito, cuando en realidad era aun jóven.\"},{\"heading\":false,\"text\":\"Al ver las gentes tan solícita y tan enamorada á la hermosísima mercadera de su viejo marido, se maravillaban y decian:\"},{\"heading\":false,\"text\":\"--Ese hombre debe de haber dado á su muger hechizos para que le ame de tal modo.\"},{\"heading\":false,\"text\":\"Y las gentes no sabian que el hechizado era Abraham.\"},{\"heading\":false,\"text\":\"Porque Leila parecia la mejor muger del mundo, con sus grandes y dulces ojos de gacela y su alegre sonrisa.\"},{\"heading\":false,\"text\":\"Pasaron aun siete años.\"},{\"heading\":false,\"text\":\"Centuplicóse el caudal de los esposos.\"},{\"heading\":false,\"text\":\"Jamné era ya un hermoso mancebo y un terrible mago, y su hermana Zelpha una hermosa niña de siete años, que parecia haber nacido de una sonrisa de la aurora.\"},{\"heading\":false,\"text\":\"Al cumplirse los siete años de la vida de Zelpha, Jamné empezó á amarla con un amor incestuoso y maldito.\"},{\"heading\":false,\"text\":\"Zelpha estaba crecida de una manera maravillosa.\"},{\"heading\":false,\"text\":\"Parecia una muger.\"},{\"heading\":false,\"text\":\"Y Leila se complacia en el amor de Jamné hácia su hermana.\"},{\"heading\":false,\"text\":\"Esta no habia llegado aun á la edad del amor, y aunque su madre la enseñaba la mágia y la astrología, su corazon aun no habia hablado.\"},{\"heading\":false,\"text\":\"Se acercaba el dia en que se cumplia el tercer periodo de siete años, desde el dia en que habia nacido Jamné.\"},{\"heading\":false,\"text\":\"Las riquezas de los esposos habian llegado á una suma maravillosa.\"},{\"heading\":false,\"text\":\"La hermosura de Leila, en vez de amenguarse, habia crecido.\"},{\"heading\":false,\"text\":\"Abraham estaba decrépito para las gentes; pero cada dia mas fuerte y mas hermoso para Leila.\"},{\"heading\":false,\"text\":\"Jamné era un mancebo hermoso, sabio, valiente, y amaba cada dia mas á su hermana.\"},{\"heading\":false,\"text\":\"Zelpha era una doncella hermosísima; tan hermosa como su madre, y soñaba ya con su primer amor.\"},{\"heading\":false,\"text\":\"Pero aquel primer amor no era para su hermano.\"},{\"heading\":false,\"text\":\"Era para un hombre soñado.\"},{\"heading\":false,\"text\":\"Todos envidiaban á Abraham, que era tan rico y que tenia una muger tan hermosa y unos tan hermosos hijos.\"},{\"heading\":false,\"text\":\"¡No sabian á qué precio pagaba Abraham aquella felicidad!\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XXVI\",\"blocks\":[{\"heading\":false,\"text\":\"Una noche velaba sola é impaciente Leila en su retrete.\"},{\"heading\":false,\"text\":\"Estaba sola porque habian venido á llamar á Abraham para curar al califa, que se habia puesto enfermo, y de quien seguia siendo médico.\"},{\"heading\":false,\"text\":\"Estaba impaciente porque Abraham tardaba y no sabia vivir sin él.\"},{\"heading\":false,\"text\":\"De repente Leila oyó ruido cerca de la habitacion, y su alma se inundó de alegría, porque creyó que era Abraham.\"},{\"heading\":false,\"text\":\"Se levantó del divan y corrió á la puerta; pero al llegar á ella retrocedió aterrada y dió un grito.\"},{\"heading\":false,\"text\":\"Una figura horrorosa se habia presentado en ella.\"},{\"heading\":false,\"text\":\"Era Satanás.\"},{\"heading\":false,\"text\":\"--¿Qué quieres? le dijo Leila. Yo no te he llamado.\"},{\"heading\":false,\"text\":\"--Vengo por tí, dijo el diablo; ha llegado la hora.\"},{\"heading\":false,\"text\":\"--¿La hora de qué? dijo estremecida de espanto Leila.\"},{\"heading\":false,\"text\":\"--Han pasado tres veces siete años desde que nació tu hijo, respondió Satanás; pronto llegará la hora precisa, y tu cuerpo morirá.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡no! ¡no! yo creo que solo ha pasado un instante desde que bebí el amor en los brazos de Abraham.\"},{\"heading\":false,\"text\":\"--¡Tres veces siete años! dijo el diablo: esa era la cuenta de tu vida, y eres mia.\"},{\"heading\":false,\"text\":\"--Pídeme lo que quieras y no me mates, esclamó juntando las manos Leila.\"},{\"heading\":false,\"text\":\"--Has tenido en tu mano la vida eterna, la felicidad eterna, y la has cambiado por una felicidad de muerte.\"},{\"heading\":false,\"text\":\"--¡La vida! ¡la vida! esclamó Leila que empezaba á sentir un frio estraño.\"},{\"heading\":false,\"text\":\"--Solo Dios podia dártela, y los decretos de Dios son inmutables.\"},{\"heading\":false,\"text\":\"--Te daré lo que me pidas.\"},{\"heading\":false,\"text\":\"--No puedes darme nada: me diste tu alma y despues las almas de tus hijos: tus hijos que son malditos, como tú, me darán el alma de sus nietos.\"},{\"heading\":false,\"text\":\"--¡La vida! ¡oh mi vida de amores! ¡un instante mas! que me vea yo a antes de morir entre los brazos de Abraham.\"},{\"heading\":false,\"text\":\"--El momento llega, ya han pasado tres veces siete años desde que nació Jamné, el maldito.\"},{\"heading\":false,\"text\":\"Y mientras Satanás decia estas palabras, Leila cayó sobre el diván, y se puso fria, muy fria.\"},{\"heading\":false,\"text\":\"Murió.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XXVII\",\"blocks\":[{\"heading\":false,\"text\":\"En aquel mismo punto Abraham, á despecho de su ciencia, veia morir en el palacio al califa.\"},{\"heading\":false,\"text\":\"Salió de allí con el alma entristecida, y cuando entró en su casa, encontró á Leila muerta.\"},{\"heading\":false,\"text\":\"Sus hijos dormian.\"},{\"heading\":false,\"text\":\"Cuando los despertaron los gritos de desesperacion de su padre, miraron á su madre muerta con los ojos enjutos.\"},{\"heading\":false,\"text\":\"Abraham lloró desconsoladamente sobre el cadáver de Leila.\"},{\"heading\":false,\"text\":\"Luego la mandó embalsamar como á una sultana, y la sepultó bajo una ostentosa tumba.\"},{\"heading\":false,\"text\":\"Despues, no permitiéndole su dolor vivir en Damasco, redujo á un pequeño volúmen sus tesoros, empleándolos en piedras maravillosas, en perlas incomparables, y en algunas telas de púrpura, oro y piedras preciosas que solo podia comprar un rey poderoso.\"},{\"heading\":false,\"text\":\"Cargó su tesoro en un asno, puso sobre él á su hija Zelpha, y acompañándole su hijo Jamné, salió un dia de Damasco.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Por aquel tiempo el caudillo Ocba-ebn-Nafhe, habia conquistado el poniente de Africa.\"},{\"heading\":false,\"text\":\"Abraham, para poder vender sus costosísimas joyas, fué á buscar aquel ejército vencedor que se habia enriquecido con los despojos de la victoria.\"},{\"heading\":false,\"text\":\"Pero una vez en la parte occidental de Africa en Tánger, supo Abraham que mas allá, al otro lado del estrecho de Alzacab, estaba la tan poderosa tierra de las Hespérides; que eran señores de ellas unas gentes riquísimas; y que allí podria vender sus tesoros, y llorar tranquilamente bajo un cielo tan azul como el de la Siria, á su perdida Leila-Fatimah.\"},{\"heading\":false,\"text\":\"Abraham se embarcó con sus hijos y con el jumento que conducia su tesoro, y pasó el estrecho.\"},{\"heading\":false,\"text\":\"Al fin puso sus plantas en España.\"},{\"heading\":false,\"text\":\"Y una tarde, ya te acuerdas, hermano lagarto, al encontrarse Jamné en un bosque solitario, en este mismo bosque al lado de esta sima, vió llegada para él la ocasion mas propicia para deshacerse del viejo padre, y apoderarse de su tesoro y de su hermana.\"},{\"heading\":false,\"text\":\"Ya sabes lo que sucedió la tarde de horrores.\"},{\"heading\":false,\"text\":\"--Sí, sí, lo sé, amiga culebra.\"},{\"heading\":false,\"text\":\"--Pero lo que tu no sabes, es que en la misma hora en que fué arrojado á la sima por sus malditos hijos Abraham, se contaban justos tres veces siete años, desde que Abraham poseyó la maldita hermosura de Leila-Fatimah.\"},{\"heading\":false,\"text\":\"--¿Y no sabes mas, hermana culebra?\"},{\"heading\":false,\"text\":\"--Sí, sé que el alma de Abraham, por no haber sido dócil al consejo de los siete astrólogos á quienes habia consultado, cuando Leila le propuso ofender á Dios, estará penando hasta que sobre esta sima se levante una torre fuerte de siete suelos, que será la puerta de un alcázar como no habrá otra sobre la tierra, y hasta que muera en este alcázar y venga á penar en la torre, una muger que haya sido parricida, adúltera é incestuosa.\"},{\"heading\":false,\"text\":\"--¿Y quién te ha dicho eso, hermana culebra?\"},{\"heading\":false,\"text\":\"--El alma en pena de Abraham.\"},{\"heading\":false,\"text\":\"--¿Y no sabes lo que fué de los hijos de Abraham?\"},{\"heading\":false,\"text\":\"--No se lo pregunté.\"},{\"heading\":false,\"text\":\"--Dios es vengador, y justo é inexorable, hermana culebra.\"},{\"heading\":false,\"text\":\"--Tienes razon, hermano lagarto. Dios es Dios y no hay otro Señor que él: él ha criado este sol que abrasa mas de lo que yo quisiera, y me voy á mis profundidades.\"},{\"heading\":false,\"text\":\"--Y yo á mi grieta.\"},{\"heading\":false,\"text\":\"La culebra y el lagarto desaparecieron, y yo me quedé horrorizada, amigo ruiseñor, y no pude descansar, añadió la golondrina: de modo que cuando me puse en camino por la tarde para Toledo, estaba tan rendida, que me he visto obligada á pararme aquí.\"},{\"heading\":false,\"text\":\"--Vente á mi nido, y en él descansarás: es blando y mullido, dijo amorosamente el ruiseñor.\"},{\"heading\":false,\"text\":\"--Dios castiga á los adúlteros, dijo con enojo la golondrina, y como ya he descansado, me voy de un vuelo á mi nido del alcázar de Toledo.\"},{\"heading\":false,\"text\":\"Y la golondrina voló, y el ruiseñor se quedó gorgeando:\"},{\"heading\":false,\"text\":\"--¡Solo! ¡solo! ¡solo!\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XXVIII\",\"blocks\":[{\"heading\":false,\"text\":\"Asenéth permaneció por algun tiempo inmóvil donde se habia sentado.\"},{\"heading\":false,\"text\":\"Luego, á pesar de la terrible historia de sus abuelos, que habia oido cantar á la golondrina, se levantó y dijo:\"},{\"heading\":false,\"text\":\"--¡Yo amo á Ervigio!\"},{\"heading\":false,\"text\":\"Y se volvió al palacio maravilloso.\"},{\"heading\":false,\"text\":\"Aun dormia á los pies del diván, donde habia estado reclinada, su padre.\"},{\"heading\":false,\"text\":\"Asenéth le contempló profundamente.\"},{\"heading\":false,\"text\":\"--¿Con que si te dejo tu fuerza, esclamó la jóven maldita, despedazarás á mi mas amado?\"},{\"heading\":false,\"text\":\"Jamné, aunque dormido, hizo un movimiento que parecia una contestacion afirmativa á la pregunta de su hija.\"},{\"heading\":false,\"text\":\"--¡Oh! no le despedazarás, dijo Asenéth, porque yo te reduciré á un estado miserable.\"},{\"heading\":false,\"text\":\"Y pronunciando un horrible conjuro, esclamó:\"},{\"heading\":false,\"text\":\"--¡Oh tú, hombre convertido en leon, conviértete en un perro viejo é impotente.\"},{\"heading\":false,\"text\":\"Inmediatamente el leon se trasformó en un perro lanudo, cojo, ciego, miserable, que empezó á arrastrarse gruñendo dolorosamente á los pies de Asenéth.\"},{\"heading\":false,\"text\":\"Pero Asenéth, le hirió con el pie en el vientre, le arrojó lejos de sí, y abandonó la cámara donde Jamné, castigado de nuevo por Dios, quedaba lanzando dolorosos ahullidos.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XXIX\",\"blocks\":[{\"heading\":false,\"text\":\"Al dia siguiente, cuando Asenéth se encontraba mas abstraido en sus pensamientos de amor, tembló el alcázar todo, y yo, Satanás, dije desde las entrañas de la tierra:\"},{\"heading\":false,\"text\":\"--Ervigio me ha encontrado pescando en la orilla del rio, ha tenido valor para arrostrar el encanto, y tú y él sois mios.\"},{\"heading\":false,\"text\":\"Inmediatamente Ervigio se presentó á Asenéth.\"},{\"heading\":false,\"text\":\"A la vista de su hermosura, el noble godo palideció y tembló.\"},{\"heading\":false,\"text\":\"--¿Quién eres tú, diosa, dijo, que así brillas ante mis ojos con la plenitud de tu hermosura?\"},{\"heading\":false,\"text\":\"Yo soy tu esclava, dijo la impaciente Asenéth, arrojándose en sus brazos.\"},{\"heading\":false,\"text\":\"Y Jamné, ciego, cojo, viejo, enfermo, vagaba gruñendo dolorosamente al rededor de la habitacion donde su hija, olvidándose de todo, deliraba entre los brazos de Ervigio.\"},{\"heading\":false,\"text\":\"Y Ervigio permaneció siete dias en el alcázar encantado, y siempre que salia del misterioso retrete de amor de Asenéth, encontraba á Jamné, y le daba con el pie, esclamando:\"},{\"heading\":false,\"text\":\"--Horrible y asqueroso animal, ¿qué haces en el paraiso de las delicias?\"},{\"heading\":false,\"text\":\"Y Asenéth no reparaba en que su padre habia sido maltratado, y seguia bebiendo con sus ojos enamorados, la mirada de amor de Ervigio.\"},{\"heading\":false,\"text\":\"La noche del sétimo dia, él y ella se sentaron en el mismo lugar donde ella habia oido la conversacion del ruiseñor y de la golondrina.\"},{\"heading\":false,\"text\":\"Ervigio estaba profundamente pensativo.\"},{\"heading\":false,\"text\":\"--¿Por qué estas triste, alegría de mi alma? dijo Asenéth: ¿no tienes aquí cuanto puede desear una criatura? ¿ó es que mi hermosura no es ya bastante para alegrarte ni mi amor para satisfacerte, señor de mi alma?\"},{\"heading\":false,\"text\":\"--¡Ah! no, no, dijo Ervigio: pero yo quiero ser rey.\"},{\"heading\":false,\"text\":\"--¡Rey! ¿y de los godos acaso?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--Pero Wamba es su rey.\"},{\"heading\":false,\"text\":\"--¿Y qué importa? ¿no me amas tú?\"},{\"heading\":false,\"text\":\"¡Qué si te amo! tu eres mi luz y mi vida, pero...\"},{\"heading\":false,\"text\":\"--¿Quieres ser rey?\"},{\"heading\":false,\"text\":\"--Sí. Mas que eso: quiero vencer á Wamba.\"},{\"heading\":false,\"text\":\"--¡Le vencerás! ven conmigo.\"},{\"heading\":false,\"text\":\"Ervigio siguió á Asenéth que le llevó al alcázar mágico.\"},{\"heading\":false,\"text\":\"Dejóle en una cámara, se encerró en otra, y á poco salió con un pomito de oro en las manos.\"},{\"heading\":false,\"text\":\"--Haz que den esto á Wamba y eres rey, le dijo.\"},{\"heading\":false,\"text\":\"--¿Y cómo he de hacerlo sino salgo de este alcázar? contestó el godo.\"},{\"heading\":false,\"text\":\"--¿Me olvidarás, Ervigio, cuando te encuentres fuera de aquí? dijo Asenéth rodeándole los hermosos brazos al cuello.\"},{\"heading\":false,\"text\":\"--Antes se olvidará el sol de alumbrar el dia que yo te olvide, repuso Ervigio.\"},{\"heading\":false,\"text\":\"--Pues bien, sino vinieres cuando seas rey, yo iré á buscarte. Acuérdate de que me quedo.\"},{\"heading\":false,\"text\":\"Ervigio besó amorosamente los ojos de Asenéth.\"},{\"heading\":false,\"text\":\"--Vas á verle en el alcázar de Wamba.\"},{\"heading\":false,\"text\":\"Apenas pronunció Asenéth estas palabras, cuando Ervigio se vió en las galerías del alcázar de Toledo.\"},{\"heading\":false,\"text\":\"Y entonces le pareció un sueño lo que le habia acontecido en el alcázar mágico; pero vió en sus manos el pomo de oro que le habia dado Asenéth, y esclamó:\"},{\"heading\":false,\"text\":\"--No ha sido un sueño: hé aquí el filtro que me ha dado la maga enamorada. Veamos si por medio de este filtro seré rey.\"},{\"heading\":false,\"text\":\"Y buscó en el alcázar á uno de sus parciales en quien tenia estremada confianza Wamba, y se encerró con él, y estuvieron hablando largo tiempo.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XXX\",\"blocks\":[{\"heading\":false,\"text\":\"Al dia siguiente, Wamba adoleció.\"},{\"heading\":false,\"text\":\"Habia bebido el filtro compuesto por Asenéth.\"},{\"heading\":false,\"text\":\"Perdió el sentido súbitamente á las primeras horas de la noche, y todos creyeron que moria.\"},{\"heading\":false,\"text\":\"Para enterrarle con muestras de humildad, cortáronle el cabello, señal de nobleza entre los godos, y le pusieron la mortaja.\"},{\"heading\":false,\"text\":\"Cuando Wamba volvió en sí, y encontró su cabeza trasquilada, esclamó:\"},{\"heading\":false,\"text\":\"--Hé aquí que queda franco mi trono á los traidores, porque yo no puedo ser rey[94].\"},{\"heading\":false,\"text\":\"Y en aquel mismo punto, pidió que le trajesen á Ervigio.\"},{\"heading\":false,\"text\":\"Wamba estaba loco.\"},{\"heading\":false,\"text\":\"--Yo he muerto le dijo; pero tú vives y eres fuerte; ¿querrás tú la corona que se me ha caido de la cabeza? ¡Ah! ¡ah! ¡y qué bien llevarás tú mi corona!\"},{\"heading\":false,\"text\":\"Y los parciales de Ervigio, aprovechándose de aquella estraña locura de Wamba, le hicieron firmar la renunciacion de su corona en Ervigio.\"},{\"heading\":false,\"text\":\"Luego Wamba espresó su deseo de retirarse del mundo, y partiendo á Pampliega tomó el hábito de monge.\"},{\"heading\":false,\"text\":\"Ervigio era rey de los godos.\"},{\"heading\":false,\"text\":\"Debíalo á las artes mágicas de Asenéth, y sin embargo de la embriaguez de su grandeza se olvidó de Asenéth.\"},{\"heading\":false,\"text\":\"Y en vano Asenéth le llamó; en vano desesperada con su soledad y con sus lágrimas me evocó y me pidió que la ayudase.\"},{\"heading\":false,\"text\":\"--Mata á Ervigio, decia yo.\"},{\"heading\":false,\"text\":\"Pero ella no se atrevia á matarle porque le amaba.\"},{\"heading\":false,\"text\":\"Pasaron siete años; siete años desde que Ervigio poseyó á Asenéth y Ervigio murió.\"},{\"heading\":false,\"text\":\"Murió de una enfermedad desconocida, y Asenéth á causa de su ciencia le vió morir, se aterró y esclamó:\"},{\"heading\":false,\"text\":\"--Sea yo llevada de esta tierra maldita, donde le he conocido, donde le he amado, donde le he esperado y donde reposan sus cenizas: conviértame Dios en una fiera, que no pueda amar á hombre, ni de hombre ser amada, y noche de quebranto y de duelo sea conmigo.\"},{\"heading\":false,\"text\":\"Y apenas Asenéth, impulsada por su desesperacion, habia pronunciado estas palabras, cuando se encontró en un profundo y oscuro antro.\"},{\"heading\":false,\"text\":\"Junto á ella habia un perro.\"},{\"heading\":false,\"text\":\"Pero un perro formidable: habia pasado el poder de Asenéth, y su padre habia recobrado su fuerza de leon.\"},{\"heading\":false,\"text\":\"Asenéth, convertida en leon, rugia de dolor por la muerte de Ervigio.\"},{\"heading\":false,\"text\":\"Y entonces Jamné fué dueño de su hija, y así vivieron algun tiempo en aquel profundo antro los dos malditos.\"},{\"heading\":false,\"text\":\"Pero Jamné fué un dia muerto por unos cazadores.\"},{\"heading\":false,\"text\":\"Asenéth quedó sola.\"},{\"heading\":false,\"text\":\"Y en su soledad dió á luz esos dos gemelos que tengo sobre mis rodillas; el uno hombre con cabellos, ojos y piel de leon, el otro estraña mezcla de leon y de perro.\"},{\"heading\":false,\"text\":\"Ya sabes la larga historia de los padres y de los abuelos de ese niño, y de ese perro, Almedí.\"},{\"heading\":false,\"text\":\"¿Quieres ahora que te dé los amores de la Eva maldita?\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XXXI\",\"blocks\":[{\"heading\":false,\"text\":\"Almedí habia escuchado atentamente aquel largo relato, y se habia estremecido mas de una vez.\"},{\"heading\":false,\"text\":\"Cuando Satanás concluyó aquel cuento, Almedí invocó poderosamente á Dios.\"},{\"heading\":false,\"text\":\"Entonces la Eva, la hermosísima Eva maldita, y el maravilloso alcázar que la contenia desaparecieron.\"},{\"heading\":false,\"text\":\"Solo quedaron delante de Almedí, el pequeño hombre-fiera, y el estraño cachorro de perro y de leon.\"},{\"heading\":false,\"text\":\"Almedí circuncidó al hombre-fiera y le puso por nombre Jask-Al-bahul.\"},{\"heading\":false,\"text\":\"Buscó una nodriza á propósito para cada uno de los dos hermanos, y se dedicó á la enseñanza del que podia comprenderle y serle comprensible, por que Almedí no conocia el lenguaje de los animales.\"},{\"heading\":false,\"text\":\"Cuando Jask-Al-bahul fué crecido, le contó su historia, revelóle que aquel lanudísimo perro era hermano suyo, que debia tratarle como á tal, y ser bueno y temeroso de Dios si queria apartar de sobre sí la maldicion que pesaba sobre su familia.\"},{\"heading\":false,\"text\":\"Jask-Al-bahul, por el contrario de los suyos, crecia en la virtud, amaba á su hermano, aunque bajo aquella figura, y el feróz perro era para él, como para Almedí, sumiso y manso como un cordero.\"},{\"heading\":false,\"text\":\"Y pasaron así desde el nacimiento de Jask-Al-bahul y de su hermano, tres veces siete años.\"},{\"heading\":false,\"text\":\"Almedí murió, teniendo de un lado al hombre-fiera y del otro al perro-leon.\"},{\"heading\":false,\"text\":\"Despues que le hubieron enterrado y honrado, Jask-Al-bahul, dijo á su hermano:\"},{\"heading\":false,\"text\":\"--Hemos quedado solos, pero somos fuertes y valientes; yo voy á vender la escasa herencia que nos ha dejado el buen Almedí, y compraré una lanza y un caballo, iremos al ejército de los árabes que siguen sus conquistas en Africa, y ganaremos nuestro sustento en batalla.\"},{\"heading\":false,\"text\":\"El perro movió la cola y lanzó un leve gruñido como aprobando la determinacion de su hermano, y éste vendió lo que les habia dejado Almedí; compró una lanza y un caballo y salió de Tánger precedido de su hermano que rastreaba el camino.\"},{\"heading\":false,\"text\":\"El perro-leon habia tomado el camino de las montañas, y caminaba aprisa, tan aprisa, que apenas podia seguirle el caballo de Jask-Al-bahul.\"},{\"heading\":false,\"text\":\"--¿Y dónde me llevas, hermano? decia Jask.\"},{\"heading\":false,\"text\":\"El perro seguia rastreando y callando, y cada vez mas de prisa.\"},{\"heading\":false,\"text\":\"Al fin, para no perderle de vista, Jask tuvo que poner su caballo á la carrera.\"},{\"heading\":false,\"text\":\"Muy pronto se aventuraron en la montaña.\"},{\"heading\":false,\"text\":\"Corria el perro, y corria el caballo.\"},{\"heading\":false,\"text\":\"--¿Y adónde me llevas, hermano? decia Jask.\"},{\"heading\":false,\"text\":\"Y el perro y el caballo, el uno detrás del otro, seguian corriendo.\"},{\"heading\":false,\"text\":\"Llegó la tarde, bajo el sol, apareció la noche y lució en los cielos la luna.\"},{\"heading\":false,\"text\":\"Y el perro y el caballo seguian corriendo.\"},{\"heading\":false,\"text\":\"De repente se presentó á los ojos de Jask una llanura inmensa, inmensísima.\"},{\"heading\":false,\"text\":\"Las anchas colinas de arena, se perdian en el horizonte.\"},{\"heading\":false,\"text\":\"Allá á lo lejos se veia una ciudad.\"},{\"heading\":false,\"text\":\"Y antes de la ciudad una torre.\"},{\"heading\":false,\"text\":\"Y el perro siguió corriendo hasta la torre.\"},{\"heading\":false,\"text\":\"Algunos hombres pasaban por el camino en sus camellos, y decian á Jask:\"},{\"heading\":false,\"text\":\"--¿Vas á caso en busca de la doncella pálida, buen caballero? Si así es, que Dios te ayude.\"},{\"heading\":false,\"text\":\"Y uno tras otro siete viageros, dijeron las mismas palabras á Jask.\"},{\"heading\":false,\"text\":\"Cuando le habló el sétimo, Jask procuró detener á su caballo, y por primera vez, el caballo obedeció; paróse, y delante de él se tendió en tierra el perro.\"},{\"heading\":false,\"text\":\"--Díme tú por tu vida, así Dios te ayude, ¿qué doncella es esa pálida, de que me hablas?\"},{\"heading\":false,\"text\":\"Detuvo el viagero su camello y contestó:\"},{\"heading\":false,\"text\":\"--Esa doncella es la mas hermosa doncella del mundo; túvola el rey de estas regiones, Almunassar, de una maga con quien se habia casado; pero por ser tan hermosa esta doncella, su madre, que no queria que se casase sino con un hombre muy valiente, hizo que el rey Almunassar encerrase á la doncella en una torre, que es aquella que se vé allá, bajo los rayos de la luna, y para que la guardase, puso un jigante, que siempre de dia y de noche sin comer y sin dormir, está dando vueltas alrededor de la torre con su clava al hombro. Muchos caballeros muy valientes, atraidos por la fama de la hermosura de Aydamarah, que este es el nombre de la doncella pálida, y aun por el tesoro que encontrara con esta doncella el que venciese al jigante, han venido, pero los huesos de todos blanquean allá alrededor de la torre formando una muralla horrorosa, porque han venido miles de caballeros y á todos los ha esterminado el jigante, que es invulnerable y solo puede matársele hiriéndole en el ojo izquierdo: pero tiene puesta sobre el ojo una defensa de acero tan fuerte, y es tal su destreza para guardarse de los golpes, que todos los que han pretendido matar al gigante han perecido; además, para vencerle es necesario pronunciar al herirle ciertas palabras misteriosas que nadie sabe; con que así, buen caballero, si vas en busca de la doncella pálida, que Dios te ayude.\"},{\"heading\":false,\"text\":\"Y tras estas palabras el viagero arreó á su camello, y siguió su camino.\"},{\"heading\":false,\"text\":\"Jask era tan valiente como la fiera á quien se parecia tanto, y bastó con que conociese aquel peligro, para que desease vencerlo.\"},{\"heading\":false,\"text\":\"--Y llévame á la torre donde se guarda por ese gigante la doncella de la frente pálida, la hermosa hija del rey Almunassar y de la maga, dijo al perro:\"},{\"heading\":false,\"text\":\"Y el perro partió de nuevo á la carrera, y siguióle á la carrera el caballo de Jask.\"},{\"heading\":false,\"text\":\"Y se acercaba la torre, se acercaba hasta el punto de ver sus almenas y sus ajimeces, y el jigante que como una muralla de hierro movible, daba vueltas alrededor de ella, relumbrando bajo los rayos de la luna.\"},{\"heading\":false,\"text\":\"Y el perro y Jask seguian corriendo.\"},{\"heading\":false,\"text\":\"De improviso se escuchó un bramido tan aterrador y tan fuerte como el de una tempestad desencadenada, y se vió venir hácia el perro y hácia Jask al jigante.\"},{\"heading\":false,\"text\":\"Y resonaban las piezas de su armadura, retemblando y retumbando á la redonda con un estridor atronante y pavoroso, y parecia que la tierra temblaba bajo los pies del monstruo, que adelantaba con su terrible maza en alto.\"},{\"heading\":false,\"text\":\"El perro se paró, se replegó sobre sí mismo amenazador y rugiente, y Jask detuvo su caballo, y requirió su lanza para arrojarla al jigante, antes de que éste pudiese tocarle.\"},{\"heading\":false,\"text\":\"Llegó al fin el momento, faltaba poco espacio para que llegase á los dos hermanos el jigante, cuando Jask se aseguró en los estribos, y poniendo su corazon en Dios, esclamó arrojando su lanza contra el monstruo:\"},{\"heading\":false,\"text\":\"--¡Señor! ¡señor! ¡tú solo eres el Fuerte y el Invencible!\"},{\"heading\":false,\"text\":\"Y despues de haber arrojado su lanza con toda la fuerza de su brazo de leon contra el gigante, cerró los ojos y esperó la muerte.\"},{\"heading\":false,\"text\":\"Pero en aquel punto oyóse un estruendo horrible; tembló la llanura y gimieron los distantes ecos.\"},{\"heading\":false,\"text\":\"Jask abrió los ojos, y vió al jigante tendido delante de él; su lanza estaba clavada en el ojo izquierdo del monstruo.\"},{\"heading\":false,\"text\":\"Y al mismo tiempo se abrió la puerta de la torre, y lucieron antorchas y sonó una alegre música, y aparecieron doncellas vestidas de blanco, cada una de las cuales llevaba en las manos una luminaria.\"},{\"heading\":false,\"text\":\"Y todas aquellas doncellas cantaban en coro y decian en su canto:\"},{\"heading\":false,\"text\":\"«Bien venido sea el esposo, el esposo de la doncella pálida.»\"},{\"heading\":false,\"text\":\"«Para él, valiente entre los valientes, hermoso entre los hermosos, guarda Aidamarah su hermosura.»\"},{\"heading\":false,\"text\":\"«Bien venido sea el esposo de la doncella pálida á poseer su belleza y sus tesoros.»\"},{\"heading\":false,\"text\":\"«Bien venido sea.»\"},{\"heading\":false,\"text\":\"Y las doncellas adelantaron, y llegaron á Jask y se arrodillaron y le presentaron un palanquin en que Jask subió, y las doncellas blancas le llevaron á la torre, y una conducia su caballo, y otras rodeaban y acariciaban á su hermano el perro.\"},{\"heading\":false,\"text\":\"Y cuando llegaron á la torre, otras doncellas le desnudaron y le lavaron con aguas olorosas, y le vistieron preciosas túnicas.\"},{\"heading\":false,\"text\":\"Y entonces, otras doncellas mas hermosas aun le tomaron en medio, y cantando y tocando alegremente, le llevaron á una hermosa cámara.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XXXII\",\"blocks\":[{\"heading\":false,\"text\":\"A la puerta de aquella cámara se retiraron las doncellas.\"},{\"heading\":false,\"text\":\"Jask adelantó solo.\"},{\"heading\":false,\"text\":\"La puerta se cerró silenciosamente.\"},{\"heading\":false,\"text\":\"Y entonces de un divan se levantó una doncella cuya hermosura deslumbró á Jask.\"},{\"heading\":false,\"text\":\"Y se acercó á él y le miró, y luego se arrojó en sus brazos.\"},{\"heading\":false,\"text\":\"El perro, que habia seguido á Jask, que nunca se separaba de él, gruñó dolorosamente y se echó á los pies del divan sobre la alfombra de pieles de tigre.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XXXIII\",\"blocks\":[{\"heading\":false,\"text\":\"Súpose que el jigante guardador de la hermosísima Aidamarah habia sido vencido por un estrangero, y el rey Almunassar corrió á ver á aquel á quien los hados habian consentido llegar á tanta ventura.\"},{\"heading\":false,\"text\":\"Maravilló al rey el estraño color de los ojos y de los cabellos, y de la piel de Jask; pero no se estrañó de encontrar á Aidamarah enamorada locamente de él, porque Jask era muy hermoso.\"},{\"heading\":false,\"text\":\"Y hubo fiestas, y zambras, y regocijos, y luminarias en la córte de Almunassar.\"},{\"heading\":false,\"text\":\"Y se celebraron con régia pompa y aparato las bodas de Jask y de Aidamarah, y á ellas asistió tristemente echado á los pies de su hermano el perro-leon.\"},{\"heading\":false,\"text\":\"Y cuando pasaron las fiestas, y la zambra, y la luna de las delicias, el rey Almunassar llamó á su yerno y se encerró con él y le dijo:\"},{\"heading\":false,\"text\":\"--Mi reino, hijo mio, es un reino desconocido, puesto en los linderos del desierto, donde no llegan los de otras tierras. Yo no sé de donde tú vienes, ni quiénes son los tuyos, ni te lo pregunto, porque eres hermoso y valiente; has librado á mi hija y la harás venturosa; pero para que esa ventura sea completa, es necesario que mi reino, que está gobernado en justicia, tenga paz: unos vecinos bárbaros y feroces nos la turban; enemigos que no hemos podido vencer, que vienen todos los años y nos roban y desaparecen despues en el desierto. ¿Te atreverias tú, hijo mio, á ir contra esas gentes?\"},{\"heading\":false,\"text\":\"Jask aseguró al rey Almunassar que iria contra aquellos bárbaros y los venceria.\"},{\"heading\":false,\"text\":\"--Innumerables son como las arenas del desierto y jigantescos como las rocas. Si ellos no nos destruyen completamente, es para que podamos criar nuestras hijas y enseñarlas el canto y la danza; pero cuando nuestras hijas están crecidas, vienen y nos las arrebatan.\"},{\"heading\":false,\"text\":\"--Yo venceré á esos descreidos, señor, dijo Jask, los venceré, y tu reino quedará libre y tranquilo.\"},{\"heading\":false,\"text\":\"--Necesario será construir torres con ruedas, dentro de las cuales vayan nuestros soldados, dijo el rey; de otro modo, los jigantes del desierto nos despedazarian á la primera embestida.\"},{\"heading\":false,\"text\":\"--Iré yo solo, señor, dijo Jask, y con la ayuda de Dios los venceré.\"},{\"heading\":false,\"text\":\"--¡Tú solo!\"},{\"heading\":false,\"text\":\"--¿No vencí al terrible jigante que guardaba á mi esposa?\"},{\"heading\":false,\"text\":\"--¡Dios es misericordioso y vencedor! dijo el rey Almunassar.\"},{\"heading\":false,\"text\":\"Y se despidió triste de Jask, porque su hija le amaba, y Jask acometia una empresa en la que debia morir.\"},{\"heading\":false,\"text\":\"Los jigantes del desierto eran innumerables.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XXXIV\",\"blocks\":[{\"heading\":false,\"text\":\"Al dia siguiente muy temprano, y mientras su esposa dormia, Jask se levantó silenciosamente, besó á Aidamarah en la boca sin despertarla, se vistió la armadura, y sobre ella una túnica de oro; bajó á las caballerizas, enjaezó su caballo, montó en él, y precedido de su hermano el perro, salió antes de que fuese de dia y sin que nadie le viese, de la ciudad por un postigo del muro.\"},{\"heading\":false,\"text\":\"Cuando se vió en el campo y lejos de la ciudad á punto que alboreaba, se detuvo ante una fuente, descabalgó, hizo su ablucion, y dirijió á Dios desde el fondo de su alma la oracion de azobhí (del alba).\"},{\"heading\":false,\"text\":\"Luego se volvió al perro y le dijo:\"},{\"heading\":false,\"text\":\"--Sus, hermano mio, guia, guia al campo de los jigantes.\"},{\"heading\":false,\"text\":\"Y el perro partió rastreando y á la carrera.\"},{\"heading\":false,\"text\":\"Y las palmeras se quedaron atrás.\"},{\"heading\":false,\"text\":\"Y se quedaron atrás las colinas verdes.\"},{\"heading\":false,\"text\":\"Y se quedaron atrás los arroyos.\"},{\"heading\":false,\"text\":\"Y el perro seguia rastreando y corriendo sobre ásperas y peladas rocas.\"},{\"heading\":false,\"text\":\"Graznaban las águilas en las altísimas cortaduras.\"},{\"heading\":false,\"text\":\"Zumbaba contra ellas el viento.\"},{\"heading\":false,\"text\":\"Rocas y águilas se quedaron atrás.\"},{\"heading\":false,\"text\":\"Y el perro seguia rastreando y corriendo sobre montes de arena roja, como si la hubiesen empapado en sangre.\"},{\"heading\":false,\"text\":\"Mas allá solo habia una niebla roja é impura, como el resplandor de un horno.\"},{\"heading\":false,\"text\":\"Y acá y allá se oia el rugido de los leones y de las panteras.\"},{\"heading\":false,\"text\":\"Y las colinas rojas su quedaron atrás.\"},{\"heading\":false,\"text\":\"Y ya no se escuchó el rugido de las fieras.\"},{\"heading\":false,\"text\":\"Y el perro seguia rastreando y corriendo entre la niebla roja é impura.\"},{\"heading\":false,\"text\":\"Y el caballo de Jask le seguia.\"},{\"heading\":false,\"text\":\"Y Jask se inclinaba sobre el arzon de su caballo, con la adarga al pecho, y la lanza en ristre, invocando el nombre de Dios.\"},{\"heading\":false,\"text\":\"De repente se escuchó una voz dulcísima que parecia salir de las entrañas de aquella tierra enrojecida:\"},{\"heading\":false,\"text\":\"--«¿El hermoso caballero, á dónde va?\"},{\"heading\":false,\"text\":\"»¿A dónde va el hermoso caballero?\"},{\"heading\":false,\"text\":\"»El aire de fuego secará sus ojos, y sus plantas se abrasarán, como si pisase sobre un volcan.\"},{\"heading\":false,\"text\":\"»¿El hermoso caballero, dónde va?\"},{\"heading\":false,\"text\":\"»Si logra pasar la niebla encendida encontrará mas allá la muerte.\"},{\"heading\":false,\"text\":\"»Cada grano de arena se levantará contra él.\"},{\"heading\":false,\"text\":\"»Cada átomo del sol le herirá.\"},{\"heading\":false,\"text\":\"»Mas allá de la niebla de fuego están los hambrientos jigantes.\"},{\"heading\":false,\"text\":\"»¿El hermoso caballero dónde va?\"},{\"heading\":false,\"text\":\"»Vuélvete á la tierra verde y humbrosa, gentil caballero.\"},{\"heading\":false,\"text\":\"»Donde corren los arroyos, y las tórtolas cantan entre los álamos negros.\"},{\"heading\":false,\"text\":\"«Vuélvete donde la amada de tu alma llora por tu ausencia.\"},{\"heading\":false,\"text\":\"«Vuélvete si no quieres que su llanto no se seque jamás.»\"},{\"heading\":false,\"text\":\"--¿Quién eres tú, génio misterioso, que así me hablas? dijo Jask deteniendo su caballo; tu acento es dulce como el gorjeo del ruiseñor, y melancólico como el zumbido del vientecillo de la tarde en las hojas de la palmera. ¿Por qué no te dejas ver de mí?\"},{\"heading\":false,\"text\":\"Tembló ligeramente la tierra, arrojó una llamarada roja, y quedó ante Jask una muger hermosísima.\"},{\"heading\":false,\"text\":\"Sus cabellos negros, negrísimos, y tan largos que caian hasta sus pies en anchos rizos, estaban ceñidos por una corona de mirto seco.\"},{\"heading\":false,\"text\":\"Su semblante era moreno, sus ojos negros, brillantes, ardientes, y su túnica blanca con una blancura que deslumbraba.\"},{\"heading\":false,\"text\":\"La hermosura de aquella muger, quemaba el corazon.\"},{\"heading\":false,\"text\":\"--¿Quién eres? la preguntó Jask.\"},{\"heading\":false,\"text\":\"--Yo soy Giazul, el génio del desierto, respondió la hermosa jóven; mi carro es la niebla roja, y mis potentes caballos son el Simoun.\"},{\"heading\":false,\"text\":\"Al desplegarse mi túnica, se enrojece el cielo, la tierra tiembla espantada, las palmeras gimen, las rocas se estremecen, las águilas apresuran su vuelo, y las fieras rugen asombradas y yertas de espanto.\"},{\"heading\":false,\"text\":\"Al ruido de mi carro de combate, los caravaneros palidecen, los camellos apresuran su marcha, y los caballos corren, corren, corren, gimiendo.\"},{\"heading\":false,\"text\":\"Cuando yo he pasado, ni palmeras, ni rocas, ni águilas, ni fieras, ni caravanas; montes de arena blanca y reluciente, son las fúnebres huellas de mi paso.\"},{\"heading\":false,\"text\":\"¡Ay del insensato que se atreva á poner la planta en mis dominios, si no le ayuda Dios el Misericordioso y el Invencible!\"},{\"heading\":false,\"text\":\"Vuélvete, hermoso caballero, vuélvete; aunque yo plegue mi túnica y duerma mientras tú pasas;\"},{\"heading\":false,\"text\":\"Aunque las arenas del desierto permanezcan inmóviles, mas allá están los terribles jigantes.\"},{\"heading\":false,\"text\":\"No quieras condenar al dolor de la viudez á tu amada, y á la orfandad á la hija que vive en sus entrañas.\"},{\"heading\":false,\"text\":\"--¿Qué importa que muera yo, si muero por salvar un pueblo entero? dijo Jask.\"},{\"heading\":false,\"text\":\"Destellaron un brillante relámpago los ojos de Giazul.\"},{\"heading\":false,\"text\":\"--Noble y generoso es lo qué acabas de decir, esclamó el génio; quiero ayudarte. ¿Pero tienes tú el alma bastante fuerte para resistir á la prueba?\"},{\"heading\":false,\"text\":\"--Habla, poderoso génio, habla; dijo Jask.\"},{\"heading\":false,\"text\":\"--Solo puedes vencer de una manera á los jigantes.\"},{\"heading\":false,\"text\":\"Allá lejos, muy lejos, hay una laguna salada.\"},{\"heading\":false,\"text\":\"Entre las rocas de sus orillas relumbra cuajada la blanca sal.\"},{\"heading\":false,\"text\":\"Si tú lograses llegar hasta la laguna salada;\"},{\"heading\":false,\"text\":\"Si llenares de la sal que blanquea sus orillas el saco de tu caballo;\"},{\"heading\":false,\"text\":\"Con esparcir á tu alrededor aquella sal cuando te acometiesen los jigantes habrás vencido.\"},{\"heading\":false,\"text\":\"Los jigantes habrán sido esterminados.\"},{\"heading\":false,\"text\":\"Pero para llegar á la laguna salada, es necesario esponer el cuerpo y el alma.\"},{\"heading\":false,\"text\":\"En el camino encontrarás por do quiera la tentacion.\"},{\"heading\":false,\"text\":\"Y si á la tentacion cedieres, serás convertido en roca, en roca del desierto, y dentro de ella encontrarás tu infierno.\"},{\"heading\":false,\"text\":\"--Dios el Altísimo y Unico me ayudará.\"},{\"heading\":false,\"text\":\"--Voy á abrirte el camino de la laguna salada. Ese camino está lleno de peligros; ¡ay de tí si no sabes vencerlos!\"},{\"heading\":false,\"text\":\"El génio se elevó de la tierra.\"},{\"heading\":false,\"text\":\"Su blanca túnica se abrió como un abanico.\"},{\"heading\":false,\"text\":\"Sus negros cabellos se estendieron alrededor de su frente como una negra aureola.\"},{\"heading\":false,\"text\":\"Sus ojos brillaron como dos soles.\"},{\"heading\":false,\"text\":\"Sus dos brazos estendidos, parecian tocar el uno el oriente y el otro el occidente.\"},{\"heading\":false,\"text\":\"Sonó un sordo y potente bramido, tembló la tierra, y el génio creció, creció, creció, hasta cubrirlo todo.\"},{\"heading\":false,\"text\":\"Y las arenas del desierto se levantaron en potentes remolinos, y una atmósfera de fuego envolvió á Jask, á su caballo y á su hermano el perro.\"},{\"heading\":false,\"text\":\"Y el caballo inmóvil con las orejas rehiladas, temblaba.\"},{\"heading\":false,\"text\":\"Y el perro-leon lanzaba un poderoso ahullido.\"},{\"heading\":false,\"text\":\"Y Jask invocaba á Dios.\"},{\"heading\":false,\"text\":\"Y pasaban junto á él las ardientes arenas, los fragmentos de las rocas, las palmeras arrancadas de su asiento.\"},{\"heading\":false,\"text\":\"Pasaban sin tocarle.\"},{\"heading\":false,\"text\":\"Sin tocar á su hermano el perro.\"},{\"heading\":false,\"text\":\"Y la tromba aumentaba, y el ronco mugido crecia, y el perro ahullaba con mas fuerza, y el temblor del caballo crecia.\"},{\"heading\":false,\"text\":\"Y Jask, con el corazon sereno, continuaba invocando el nombre de Dios.\"},{\"heading\":false,\"text\":\"Pasó la tromba.\"},{\"heading\":false,\"text\":\"A la niebla caliginosa é impura, sucedió un cielo azul y radiante, como Jask no le habia visto jamás.\"},{\"heading\":false,\"text\":\"La tierra estaba cubierta de verdor.\"},{\"heading\":false,\"text\":\"Frescos bosquecillos se levantaban en torno de claros lagos, y el camino por donde Jask marchaba, estaba cubierto de flores.\"},{\"heading\":false,\"text\":\"Jask caminaba solo: su hermano el perro y su valiente caballo, habian desaparecido.\"},{\"heading\":false,\"text\":\"Cerca se veia una magnífica ciudad.\"},{\"heading\":false,\"text\":\"Al fijar en ella sus ojos Jask, las puertas de la ciudad se abrieron.\"},{\"heading\":false,\"text\":\"Por ella salió una comitiva numerosa.\"},{\"heading\":false,\"text\":\"Venian delante ginetes armados con arneses resplandecientes, guiados por un estandarte dorado: tras los ginetes, se oia una música tan armoniosa que regalaba los sentidos.\"},{\"heading\":false,\"text\":\"Aquellos ginetes avanzaron rápidamente.\"},{\"heading\":false,\"text\":\"Al llegar junto á Jask, su caudillo echó pie á tierra, y se arrodilló á los pies de Jask.\"},{\"heading\":false,\"text\":\"--Tú eres nuestro rey, le dijo mostrándole una corona que traia un magnate en una bandeja de oro sobre un paño de púrpura.\"},{\"heading\":false,\"text\":\"--Yo soy un viajero, contestó Jask; dejadme pasar: yo voy allá lejos, muy lejos.\"},{\"heading\":false,\"text\":\"--Si eres nuestro rey, nada se opondrá á tu voluntad: esclavos tuyos seremos, y esclavos tuyos serán los pueblos cerca y lejos, porque nosotros somos invencibles.\"},{\"heading\":false,\"text\":\"--Yo no soy soberbio, dijo Jask Al-Bahul; ¿para qué quiero esclavizar á nadie? Dejadme pasar.\"},{\"heading\":false,\"text\":\"--Si fueres nuestro rey, serás el mas temido de los hombres, dijo el que estaba arrodillado á sus pies.\"},{\"heading\":false,\"text\":\"--Yo no quiero que me teman mis vasallos, sino que me amen, esclamó Jask; dejadme pasar.\"},{\"heading\":false,\"text\":\"--Si fueres nuestro rey, serás como Dios, porque nuestra corona es mágica.\"},{\"heading\":false,\"text\":\"--Yo adoro al Dios Altísimo y Unico, repuso el jóven. Dejadme hacer mi camino, dejadme pasar.\"},{\"heading\":false,\"text\":\"Entonces desapareció todo lo que se habia presentado ante los ojos de Jask, y se encontró marchando por el mismo camino.\"},{\"heading\":false,\"text\":\"Las tentaciones de la soberbia nada habian podido con él.\"},{\"heading\":false,\"text\":\"Siguiendo el camino, se encontró en un bosque de sauces.\"},{\"heading\":false,\"text\":\"El ambiente era fresco y balsámico, mullido y espeso el césped sobre que marchaba, y salpicado de bellas florecillas; una armonía sensual parecia salir de entre las enramadas; una ambrosía suavísima halagaba los sentidos.\"},{\"heading\":false,\"text\":\"Al revolver de una senda, Jask se encontró de repente en un espacio redondo, en medio del cual habia un pequeño lago.\"},{\"heading\":false,\"text\":\"Alegres y seductoras risas se escuchaban, como si las produjesen mugeres invisibles.\"},{\"heading\":false,\"text\":\"Jask vió agitarse una forma hermosísima en el fondo cristalino del lago.\"},{\"heading\":false,\"text\":\"Luego se rompió su tersa superficie, y salió al encuentro de Jask una hada desnuda.\"},{\"heading\":false,\"text\":\"Fascinaban sus miradas, embriagaba su aliento; sus brazos estrechaban á Jask, su seno se comprimia contra el suyo, su boca fresquísima y llena de ambrosía, le besaba, y su acento ardiente y opaco le decia:\"},{\"heading\":false,\"text\":\"--¡Yo te amo!\"},{\"heading\":false,\"text\":\"--Yo solo puedo amar á una muger, dijo Jask rechazando á la hada.\"},{\"heading\":false,\"text\":\"--Aidamarah es una mortal, y yo soy el génio inmortal del amor; mis placeres serán para ti eternos; yo te anegaré en delicias y cada dia seré mas hermosa, mas resplandeciente; ámame porque yo desfallezco por tí.\"},{\"heading\":false,\"text\":\"--Mi corazon es de Aidamarah, esclamó de nuevo Jask, y rechazó vigorosamente la tentacion.\"},{\"heading\":false,\"text\":\"--Tú serás como Dios, si me poseyeres, dijo la hada.\"},{\"heading\":false,\"text\":\"--No hay mas Dios que Dios el Altísimo y Unico, esclamó Jask.\"},{\"heading\":false,\"text\":\"Y la hada impura, y el trasparente lago, y el sombroso bosquecillo, desaparecieron.\"},{\"heading\":false,\"text\":\"La lujuria habia sido tan impotente para con Jask, como lo habia sido la soberbia.\"},{\"heading\":false,\"text\":\"De repente Jask, se encontró en un palacio: un viejo encorvado y trémulo, marchaba delante de él: llevaba un haz de llaves.\"},{\"heading\":false,\"text\":\"Aquel viejo, se detenia de tiempo en tiempo delante de una fuerte arca.\"},{\"heading\":false,\"text\":\"--Hé aquí plata, decia volviéndose á Jask.\"},{\"heading\":false,\"text\":\"Jask seguia adelante.\"},{\"heading\":false,\"text\":\"El viejo dejaba el arca abierta, adelantaba á Jask, abria otra arca y le decia:\"},{\"heading\":false,\"text\":\"--Hé aquí oro.\"},{\"heading\":false,\"text\":\"Jask seguia andando mas de prisa.\"},{\"heading\":false,\"text\":\"El viejo corria y se adelantaba.\"},{\"heading\":false,\"text\":\"--Hé aquí perlas y rubíes, esclamaba abriendo otra arca.\"},{\"heading\":false,\"text\":\"Jask, siempre en silencio, apresuraba su paso.\"},{\"heading\":false,\"text\":\"Pero el viejo se ponia delante y abria otra arca.\"},{\"heading\":false,\"text\":\"--Hé aquí esmeraldas y carbunclos.\"},{\"heading\":false,\"text\":\"Y Jask corria.\"},{\"heading\":false,\"text\":\"El viejo se adelantaba jadeando, y abria otra arca.\"},{\"heading\":false,\"text\":\"--Hé aquí diamantes grandes como huevos de paloma.\"},{\"heading\":false,\"text\":\"Y Jask apresuraba su carrera.\"},{\"heading\":false,\"text\":\"--El que posea estas riquezas, será señor del mundo, gritaba el viejo no pudiendo seguir á Jask.\"},{\"heading\":false,\"text\":\"--No hay mas Señor que Dios en la tierra y en los cielos, esclamó Jask.\"},{\"heading\":false,\"text\":\"Entonces desapareció el palacio.\"},{\"heading\":false,\"text\":\"Jask habia triunfado de la avaricia, como habia triunfado de la soberbia y de la lujuria.\"},{\"heading\":false,\"text\":\"De repente Jask se encontró desnudo, roto, y pobre en la plaza de una ciudad; todos los que pasaban y los que se cruzaban, se le ponian al paso, le miraban descaradamente, y se le reian.\"},{\"heading\":false,\"text\":\"--¿Adónde irá este? esclamaban.\"},{\"heading\":false,\"text\":\"--El horrible.\"},{\"heading\":false,\"text\":\"--El imbécil.\"},{\"heading\":false,\"text\":\"--El mendigo.\"},{\"heading\":false,\"text\":\"--El cobarde.\"},{\"heading\":false,\"text\":\"--El hijo de la ramera.\"},{\"heading\":false,\"text\":\"--Insultadle, para que no se atreva á mostrar su hediondez entre nosotros.\"},{\"heading\":false,\"text\":\"Y Jask impasible decia:\"},{\"heading\":false,\"text\":\"--Apartaos y dejadme hacer mi camino.\"},{\"heading\":false,\"text\":\"--¿Y adónde irás tu? ¡á algun tremedal, único lugar digno de tí!\"},{\"heading\":false,\"text\":\"--Arrojadle lodo hasta que le sepulteis; ¿quién le ha traido á manchar con su presencia nuestra hermosa ciudad?\"},{\"heading\":false,\"text\":\"Y le arrojaban lodo y le escupian, y Jask seguia adelante sin irritarse y esclamando siempre:\"},{\"heading\":false,\"text\":\"--Dejadme, dejadme hacer mi camino.\"},{\"heading\":false,\"text\":\"--Es un cobarde, decia una muger impura; ¿no veis cual sufre los insultos?\"},{\"heading\":false,\"text\":\"Y le hirió con su chapin en la cara.\"},{\"heading\":false,\"text\":\"--No hay otro valiente que Dios, esclamó Jask; solo El es el Fuerte y el Invencible.\"},{\"heading\":false,\"text\":\"Desapareció todo aquello.\"},{\"heading\":false,\"text\":\"Jask habia vencido á la ira como á la soberbia, á la lujuria y á la avaricia.\"},{\"heading\":false,\"text\":\"Pero estaba cansado y hambriento, no caminaba ya sobre flores, ni sobre alfombras, ni sobre plazas enarenadas, trepaba penosamente entre ásperas rocas.\"},{\"heading\":false,\"text\":\"Durante mucho tiempo sufrió, pero al fin no pudo resistir.\"},{\"heading\":false,\"text\":\"--Tengo hambre y sed, dijo.\"},{\"heading\":false,\"text\":\"--Come y bebe, señor, dijo un génio apareciendo de repente y mostrándole una hermosa tienda.\"},{\"heading\":false,\"text\":\"Jask entró en ella.\"},{\"heading\":false,\"text\":\"Encontró dentro un blando diván, y delante del diván, sobre una magnífica alfombra, vió vagilla de oro, y copas y trasparentes frascos.\"},{\"heading\":false,\"text\":\"Y las fuentes llenas de viandas, y los frascos llenos de licores.\"},{\"heading\":false,\"text\":\"--Come, señor, y reposa, dijo el génio.\"},{\"heading\":false,\"text\":\"Jask examinó los manjares; pero todos estaban prohibidos por la ley.\"},{\"heading\":false,\"text\":\"Aquella gran diversidad de platos, estaban compuestos con las diferentes partes del cerdo.\"},{\"heading\":false,\"text\":\"El pan estaba amasado con la manteca de este animal.\"},{\"heading\":false,\"text\":\"Los frascos estaban llenos de licores.\"},{\"heading\":false,\"text\":\"--Agua y pan de avena, dijo Jask.\"},{\"heading\":false,\"text\":\"--Deja eso para los miserables, señor, dijo el génio; ¿qué importa la ley? tienes hambre y sed, estás cansado, come, bebe, reposa, si no morirás.\"},{\"heading\":false,\"text\":\"--¡Dichoso del que muere alimentando su alma con el temor de Dios! dijo Jask.\"},{\"heading\":false,\"text\":\"Entonces los manjares y la tienda y el génio, desaparecieron.\"},{\"heading\":false,\"text\":\"Jask habia triunfado de la tentacion de la gula, como de las tentaciones anteriores.\"},{\"heading\":false,\"text\":\"Pero se encontraba marchando por un terreno mas árido y quebrado, bajo los rayos de un sol abrasador.\"},{\"heading\":false,\"text\":\"--¡Oh, Señor, Señor, sostenme! esclamó; ¡dame tu fortaleza, porque me siento desfallecer!\"},{\"heading\":false,\"text\":\"Y siguió su camino vacilante, trémulo, débil, seca la garganta, sufriendo el crudo aguijon del hambre, desvanecida la cabeza.\"},{\"heading\":false,\"text\":\"Resbaló sobre una roca, y cayó desde una altura inmensa.\"},{\"heading\":false,\"text\":\"Encontróse del lado de un camino por donde pasaba mucha gente.\"},{\"heading\":false,\"text\":\"Unos iban en hombros de sus esclavos, otros ginetes en poderosos caballos, otros en camellos, otros en jumentos, aquellos en carretas de bueyes.\"},{\"heading\":false,\"text\":\"Todos hacian cómodamente su camino.\"},{\"heading\":false,\"text\":\"Jask, hambriento, estropeado, se arrastraba sobre sus manos.\"},{\"heading\":false,\"text\":\"--Mira, decia una voz misteriosa á su oido; aquel faquí va cómodamente sentado sobre las hamugas, va satisfecho y repleto. ¡Si tú fueras como él!\"},{\"heading\":false,\"text\":\"--Dios le prospere, decia Jask.\"},{\"heading\":false,\"text\":\"--Aquel walí va ginete en un poderoso caballo, mira como galopa... allá va, allá va... ya se pierde... ya se perdió... y tú sigues arrastrándote.\"},{\"heading\":false,\"text\":\"--Dios me ayudará para que llegue al fin de mi camino.\"},{\"heading\":false,\"text\":\"--Pero tu camino es un camino doloroso...\"},{\"heading\":false,\"text\":\"--Todo camino es dulce y toda fatiga poca, cuando se marcha á una buena obra. El camino estrecho y áspero, es el camino del paraiso.\"},{\"heading\":false,\"text\":\"Y al decir estas palabras Jask, se encontró de repente de pie, fuerte, sin hambre, sin sed, con sus sandalias nuevas y en las manos su báculo de viaje.\"},{\"heading\":false,\"text\":\"Habia sufrido su miseria sin irritarse ante la dicha de los demás.\"},{\"heading\":false,\"text\":\"Habia vencido á la envidia.\"},{\"heading\":false,\"text\":\"Marchaba por un camino ancho y llano.\"},{\"heading\":false,\"text\":\"A lo lejos, pero muy lejos, legísimos, se veia relumbrar una línea blanca en el horizonte.\"},{\"heading\":false,\"text\":\"--¿Será aquella la laguna salada? esclamó; pero si es, ¡cuán lejos!\"},{\"heading\":false,\"text\":\"Y siguió andando.\"},{\"heading\":false,\"text\":\"De repente sintió que sus miembros se entumecian, que sus párpados se ponian pesados, que una suave languidez se apoderaba de su cuerpo.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡cuán lejos está el lago de las aguas saladas! esclamó.\"},{\"heading\":false,\"text\":\"Entonces dijo una voz tentadora á su oido:\"},{\"heading\":false,\"text\":\"--Mira, allí hay un sombroso bosquecillo de acacias; en él las aves difunden su grata armonía, y los arroyos murmuran dulcemente; los rayos del sol abrasan, queda aun mucho dia, descansa y luego á la tarde continuarás tu camino.\"},{\"heading\":false,\"text\":\"--El que se detiene en el camino del bien, se espone á caer en la tentacion, no me detendré hasta que agotadas mis fuerzas caiga. Entonces Dios tendrá piedad de mí, porque no habrá consistido en mi voluntad.\"},{\"heading\":false,\"text\":\"--El lago de las aguas saladas está muy lejos, y te rinde la fatiga.\"},{\"heading\":false,\"text\":\"--Confio en la misericordia de Dios que me dará su fortaleza.\"},{\"heading\":false,\"text\":\"Aun no habia acabado de pronunciar estas palabras Jask, cuando se encontró cabalgando de nuevo en su caballo, que corria, corria, siguiendo al perro, que corria tambien.\"},{\"heading\":false,\"text\":\"Jask habia vencido á la pereza, como á las otras seis mortales tentaciones.\"},{\"heading\":false,\"text\":\"Dios le habia premiado.\"},{\"heading\":false,\"text\":\"Su caballo le llevó con la velocidad del huracán, á las orillas del lago de las aguas saladas.\"},{\"heading\":false,\"text\":\"Entonces una voz maravillosa, voz que parecia provenir de los cielos, le dijo:\"},{\"heading\":false,\"text\":\"--Descansa y cobra fuerzas para cumplir la voluntad de Dios.\"},{\"heading\":false,\"text\":\"Jask desmontó y se echó á dormir bajo la sombra de una roca.\"},{\"heading\":false,\"text\":\"Su hermano el perro, se echo á sus pies y se durmió tambien.\"},{\"heading\":false,\"text\":\"El caballo inclinó la cabeza y durmió.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XXXV\",\"blocks\":[{\"heading\":false,\"text\":\"Pasó la tarde, pasó la noche, y llegó el alba del dia siguiente.\"},{\"heading\":false,\"text\":\"Jask, su hermano y su caballo, dormian.\"},{\"heading\":false,\"text\":\"A la primera claridad de la mañana, la misma voz que le habia ordenado que descansase, despertó á Jask.\"},{\"heading\":false,\"text\":\"--Levántate y prepárate, dijo; el momento se acerca.\"},{\"heading\":false,\"text\":\"Jask despertó, despertó á su perro, y despertó al caballo.\"},{\"heading\":false,\"text\":\"Entonces Jask, tomó el saco donde llevaba el pienso de su cabalgadura, le vació, y le llenó de la sal cuajada entre las rocas.\"},{\"heading\":false,\"text\":\"Cuando le hubo llenado, Jask montó de nuevo á caballo y dijo al perro-leon:\"},{\"heading\":false,\"text\":\"--Hermano mio, llévame al campo de los jigantes.\"},{\"heading\":false,\"text\":\"El perro partió á la carrera bordeando la laguna salada.\"},{\"heading\":false,\"text\":\"El caballo le seguia rápido como una exhalacion.\"},{\"heading\":false,\"text\":\"Muy pronto la laguna se quedó atrás.\"},{\"heading\":false,\"text\":\"Se acercaban á una selva de árboles jigantescos, de negros follajes, y en cuyo seno solo se veian tinieblas.\"},{\"heading\":false,\"text\":\"El perro se lanzó en aquella selva.\"},{\"heading\":false,\"text\":\"Le siguió el caballo.\"},{\"heading\":false,\"text\":\"Apenas hubieron revuelto el primer seno de la selva, se encontraron en una oscuridad profunda.\"},{\"heading\":false,\"text\":\"El perro seguia corriendo en medio de las tinieblas y ladrando.\"},{\"heading\":false,\"text\":\"El caballo corriendo y relinchando.\"},{\"heading\":false,\"text\":\"Jask entonando un himno á la grandeza de Dios.\"},{\"heading\":false,\"text\":\"Y parecia que los árboles chocaban rudamente sus troncos.\"},{\"heading\":false,\"text\":\"Y se oia el áspero y terrible estridor de las ramas que se desgajaban.\"},{\"heading\":false,\"text\":\"Y el mugido sordo y pavoroso de torrentes invisibles.\"},{\"heading\":false,\"text\":\"Y de tiempo en tiempo un relámpago azul temblaba entre las tinieblas esclareciéndolas por un instante.\"},{\"heading\":false,\"text\":\"Y á su resplandor momentáneo se veian agitarse sombras jigantescas girando en torbellino alrededor de Jask.\"},{\"heading\":false,\"text\":\"Y se oia espantoso chocar de armas.\"},{\"heading\":false,\"text\":\"Y rechinar de carros.\"},{\"heading\":false,\"text\":\"Y relinchos de caballos.\"},{\"heading\":false,\"text\":\"Todo esto llevado por un huracán pujante que rebramaba, que zumbaba, que silbaba, pero que no se sentia.\"},{\"heading\":false,\"text\":\"Y todo aquello era pavoroso, terrible.\"},{\"heading\":false,\"text\":\"Sin embargo, Jask tenia su corazon puesto en el Señor Fuerte, y su confianza en El, y no se aterraba.\"},{\"heading\":false,\"text\":\"Y el perro corria y corria.\"},{\"heading\":false,\"text\":\"Y el caballo le seguia, le seguia como una exhalacion.\"},{\"heading\":false,\"text\":\"¿Cuánto tiempo duró el paso de Jask por la selva de los Espantos?\"},{\"heading\":false,\"text\":\"Solo Dios lo sabe.\"},{\"heading\":false,\"text\":\"Al fin se encontró en una llanura árida.\"},{\"heading\":false,\"text\":\"En medio de ella, allá lejos, muy lejos, se alzaba una ciudad jigantesca.\"},{\"heading\":false,\"text\":\"A pesar de la distancia, Jask veia sus puertas de quince codos de altura, y las enormísimas piedras de sus muros.\"},{\"heading\":false,\"text\":\"El camino por donde marchaba Jask estaba sembrado de huesos humanos.\"},{\"heading\":false,\"text\":\"Apenas el caballo de Jask hubo puesto los cascos en aquella llanura, cuando se oyó un horrísono estruendo en la distante ciudad.\"},{\"heading\":false,\"text\":\"Por sus cien puertas empezaron á rebosar en la árida llanura ejércitos de jigantes.\"},{\"heading\":false,\"text\":\"Sus voces formidables como las del trueno, juntas y discordantes, ensordecian el espacio.\"},{\"heading\":false,\"text\":\"El perro se hizo atrás, se sentó amenazador y rugió.\"},{\"heading\":false,\"text\":\"El caballo se plantó, enbiestó el cuello y tembló.\"},{\"heading\":false,\"text\":\"Solo Jask permaneció impávido.\"},{\"heading\":false,\"text\":\"Y los jigantes adelantaban inundando la llanura.\"},{\"heading\":false,\"text\":\"Desnudos y negros y feroces eran, con pinos por clavas en las manos.\"},{\"heading\":false,\"text\":\"En medio de ellos ondeaba una bandera, tan grande como una gran nube, y que ocultaba los rayos del sol.\"},{\"heading\":false,\"text\":\"Y adelantaban los jigantes con la velocidad de la tormenta.\"},{\"heading\":false,\"text\":\"Cuando estuvieron cerca, Jask escitó á su hermano y aguijó á su corcel.\"},{\"heading\":false,\"text\":\"El perro y el caballo, aunque estremecidos de terror, se lanzaron de frente contra los jigantes.\"},{\"heading\":false,\"text\":\"Jask llevaba un puñado de sal en la mano.\"},{\"heading\":false,\"text\":\"Cuando ya le separaba muy poca distancia de los monstruos, cuando sus jigantescos cuerpos le daban sombra, cuando casi podian alcanzarse con las clavas, cuando le rodearon rugientes y amenazadores, Jask arrojó á su alrededor el puñado de sal que tenia en la mano.\"},{\"heading\":false,\"text\":\"Entonces los primeros jigantes, los que estaban mas próximos á Jask, se detuvieron y quedaron inmóviles; sus formas se hincharon; de negros que eran se convirtieron en rojos, y al cabo quedaron convertidos en enormes rocas.\"},{\"heading\":false,\"text\":\"Jask pasó entre ellos arrojando á derecha é izquierda puñados de sal.\"},{\"heading\":false,\"text\":\"A medida que adelantaba, quedaban á los dos lados en su marcha rocas y rocas; rocas que habian sido jigantes.\"},{\"heading\":false,\"text\":\"Cuando llegó á la ciudad, á la ciudad monstruosa, huian desordenados delante de él, millares de monstruos aterrados por el ejemplo de la desgracia de sus compañeros.\"},{\"heading\":false,\"text\":\"Delante de todos iba el que llevaba la bandera.\"},{\"heading\":false,\"text\":\"Pero el perro y el caballo corrian mas que los jigantes.\"},{\"heading\":false,\"text\":\"Los alcanzaban, y Jask arrojaba nuevos puñados de sal, y aparecian nuevas rocas.\"},{\"heading\":false,\"text\":\"Al fin solo quedó un jigante, pero doblemente mayor que los otros.\"},{\"heading\":false,\"text\":\"Aquel era su rey.\"},{\"heading\":false,\"text\":\"Aquel llevaba la inmensísima bandera.\"},{\"heading\":false,\"text\":\"Jask no le alcanzó hasta el centro de la plaza de la ciudad.\"},{\"heading\":false,\"text\":\"Y aquella plaza era un campo de muchas leguas.\"},{\"heading\":false,\"text\":\"Jask arrojó un puñado de sal al jigante, que inmediatamente se convirtió en roca.\"},{\"heading\":false,\"text\":\"Y la bandera cayó de sus manos, y se estendió en la plaza.\"},{\"heading\":false,\"text\":\"Y Jask recorrió la ciudad arrojando sal en medio de ella.\"},{\"heading\":false,\"text\":\"Y no menguaba la sal del saco, por mucha que Jask sacaba.\"},{\"heading\":false,\"text\":\"Y las casas y los palacios, y las calles y las plazas, se convertian en montañas, en cordilleras, en valles.\"},{\"heading\":false,\"text\":\"Y de los valles, y de las vertientes de las montañas, salian mugeres y hombres y niños, innumerables cautivos que los salvajes tenian aprisionados para alimentarse con ellos, y cuyas prisiones habia roto la fortaleza del alma de Jask, que no habia caido en el pecado, ni temblado ante el terror.\"},{\"heading\":false,\"text\":\"Y Jask tardó siete dias en trasformar la ciudad maldita, y á la tarde del sétimo, se encontró de nuevo en la que habia sido plaza de la ciudad, y que entonces era un campo yermo y estenso, en medio del cual estaba estendida la roja bandera de los jigantes.\"},{\"heading\":false,\"text\":\"Y el perro y el caballo se precipitaron sobre aquella bandera; y sobre la bandera puso los pies la innumerable muchedumbre de viejos, jóvenes, mugeres y niños que Jask habia libertado.\"},{\"heading\":false,\"text\":\"Y cuando no quedó ni uno solo que no estuviese sobre la bandera, esta se levantó en los aires y flotó rápidamente en el espacio, y poco despues descendió: y Jask y los que le acompañaban se encontraron en una llanura, delante de las puertas de la ciudad del rey Al-Munassar.\"},{\"heading\":false,\"text\":\"Los habitantes, que habian visto aparecer á lo lejos sobre el horizonte aquella nube roja, adelantar rápidamente hácia la ciudad, pasar sobre ella y descender, salieron asustados no sabiendo lo que aquello fuese.\"},{\"heading\":false,\"text\":\"Pero cuando vieron adelantar á Jask-Al-bahul, sobre su corcel de guerra precedido de su perro, y seguido de gentes que habian sido robadas en años anteriores por los jigantes, una esclamacion de júbilo y de alegría retumbó en los aires en honor de Jask.\"},{\"heading\":false,\"text\":\"Y Aidamarah se arrojó desfallecida en sus brazos.\"},{\"heading\":false,\"text\":\"Porque le habia creido muerto.\"},{\"heading\":false,\"text\":\"Jask habia invertido en su espedicion, siete veces siete dias.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XXXVI\",\"blocks\":[{\"heading\":false,\"text\":\"Los libertados y sus familias, proclamaron su padre á Jask.\"},{\"heading\":false,\"text\":\"El rey Al-Munassar renunció con alegría su corona, y la puso sobre sus sienes.\"},{\"heading\":false,\"text\":\"La bandera de los jigantes, doblada y redoblada, fué á servir de alfombra á la grande Aljama, y en ella se bordaron inscripciones en loor de Dios por mandato de Jask que no quiso que se consagrasen en honor suyo.\"},{\"heading\":false,\"text\":\"Su reino desde entonces fué feliz y próspero; ya no se vieron talados los campos, ni yermas las aldeas.\"},{\"heading\":false,\"text\":\"Los moradores durmieron tranquilos sin temor á los jigantes, y no hubo uno solo que no fuese á ser testigo del prodigio de la trasformacion de aquellos monstruos en rocas.\"},{\"heading\":false,\"text\":\"Sobre cada una de aquellas rocas, habia una palma agostada y estéril.\"},{\"heading\":false,\"text\":\"Aquella palma habia sido la clava del jigante.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XXXVII\",\"blocks\":[{\"heading\":false,\"text\":\"Algun tiempo despues, y cuando Jask era un rey adorado por sus vasallos y respetado por sus vecinos, que le pagaban tributo, Aidamarah dió á luz una niña.\"},{\"heading\":false,\"text\":\"En la fiesta de las buenas hadas, pusieron por nombre á aquella niña Zairah.\"},{\"heading\":false,\"text\":\"Era hermosa á maravilla, de apacible sonrisa y de mirada dulce y tranquila.\"},{\"heading\":false,\"text\":\"Jask quiso saber el horóscopo de su hija, y los astrólogos, despues de haber consultado siete veces las estrellas en siete veces distintas, le dijeron:\"},{\"heading\":false,\"text\":\"--Tu hija ¡oh rey! está sujeta á grandes desgracias.\"},{\"heading\":false,\"text\":\"--¿Y qué desgracias son esas?\"},{\"heading\":false,\"text\":\"--Tendrás otros dos hijos, el uno se llamará Jacub y el otro Kaibar.\"},{\"heading\":false,\"text\":\"Jacub será un hermoso mancebo, pero continuará en él la maldicion de tu raza, que el Altísimo ha suspendido para tí.\"},{\"heading\":false,\"text\":\"El otro será salvage y feróz, amará la sangre y el crímen y participará de la crueldad y la malicia de tus padres.\"},{\"heading\":false,\"text\":\"Tus hijos serán tu postrera prueba.\"},{\"heading\":false,\"text\":\"Si la resistieses sin entregarte á la desesperacion y sin blasfemar de Dios, se abrirán para tí las puertas del paraiso.\"},{\"heading\":false,\"text\":\"Pero prepárate, rey, porque le esperan grandes dolores.\"},{\"heading\":false,\"text\":\"--Cúmplase la voluntad de Dios, replicó Jask: ¿y qué dolores son esos que Dios me envia para prueba? ¿os los han puesto patentes los astros?\"},{\"heading\":false,\"text\":\"--Tu hermosa Aidamarah morirá cuando dé á luz á Kaibar: sus entrañas se romperán al dar á luz á tal monstruo.\"},{\"heading\":false,\"text\":\"--Dios me la ha dado, y Dios puede quitármela, esclamó Jask con los ojos llenos de lágrimas. ¿Y cuándo morirá la luz de mi alma?\"},{\"heading\":false,\"text\":\"--Pasadas tres veces siete lunas.\"},{\"heading\":false,\"text\":\"--¿Y qué mas desgracias me amenazan?\"},{\"heading\":false,\"text\":\"--Pasados tres veces siete años, tus hijos conocerán á su hermana y la amarán.\"},{\"heading\":false,\"text\":\"--¡Oh, Señor!\"},{\"heading\":false,\"text\":\"--Y ella amará á su hermano Jacub y será suya.\"},{\"heading\":false,\"text\":\"--¡Oh, Señor!\"},{\"heading\":false,\"text\":\"--Y Kaibar conocerá tambien á su hermana, y la amará.\"},{\"heading\":false,\"text\":\"Y ambos por el amor á su hermana se venderán á Satanás.\"},{\"heading\":false,\"text\":\"Y despues el un hermano matará á su hermano por celos de Zairah.\"},{\"heading\":false,\"text\":\"--¡Oh, Señor, Señor, y cuán dura es esta prueba! esclamó Jask: y decidme, añadió; vosotros que sois sabios, ¿no sabeis si hay algun medio para prevenir tanta desgracia?\"},{\"heading\":false,\"text\":\"--Consultaremos de nuevo á los astros, dijeron los astrólogos.\"},{\"heading\":false,\"text\":\"Y el rey esperó á que trascurriesen otras siete noches.\"},{\"heading\":false,\"text\":\"--Señor, le dijeron los astrólogos trascurrido este tiempo: no te queda mas que una esperanza dudosa.\"},{\"heading\":false,\"text\":\"--¿Y cuál es esa esperanza?\"},{\"heading\":false,\"text\":\"--Aparta de tí á tu hija Zairah.\"},{\"heading\":false,\"text\":\"--¡A la prenda de mi amor!\"},{\"heading\":false,\"text\":\"--No la veas jamás.\"},{\"heading\":false,\"text\":\"--¡Ah!\"},{\"heading\":false,\"text\":\"--Pon entre tu reino y el lugar donde se encuentre los mares.\"},{\"heading\":false,\"text\":\"--¡Desdichado de mí!\"},{\"heading\":false,\"text\":\"--Entrega su crianza á varones justos y mugeres virtuosas, que no sepan que es hija de rey.\"},{\"heading\":false,\"text\":\"--¿Y para qué eso?\"},{\"heading\":false,\"text\":\"--Para que sea como si tu hija no hubiera nacido.\"},{\"heading\":false,\"text\":\"--Si así salvo su alma y la de mis otros hijos, lo haré.\"},{\"heading\":false,\"text\":\"--Además procura que tu hija no sea vista mas que durante su primera edad por los que pusieres á su lado para que aprenda á conocer á Dios. Luego, que nadie la vea ni ella pueda ver á nadie.\"},{\"heading\":false,\"text\":\"--¡Desdichada hija mia!\"},{\"heading\":false,\"text\":\"--Así acaso se librará de su funesto destino, y del crímen tus otros hijos.\"},{\"heading\":false,\"text\":\"--Cúmplase la voluntad de Dios.\"},{\"heading\":false,\"text\":\"--Pero para que esa dudosa esperanza se realice, es necesario que apartes de tí á Zairah antes que tu esposa dé á luz á otro hijo.\"},{\"heading\":false,\"text\":\"Y los sabios se inclinaron profundamente ante Jask y le dejaron solo.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XXXVIII\",\"blocks\":[{\"heading\":false,\"text\":\"Era Jask tan temeroso de Dios, que no vaciló en arrostrar el nuevo y terrible sacrificio que el Señor le exigía.\"},{\"heading\":false,\"text\":\"Aprovechando la ocasion del paso de los árabes á España, una noche, convirtiéndose en ladron de sí mismo, penetró en las habitaciones donde se criaba su hija y la robó recatadamente, y la sacó de su palacio.\"},{\"heading\":false,\"text\":\"Luego, disfrazándose de labrador, se fué á la campiña, y para que amamantase á su hija, sedujo con oro á una aldeana, que abandonó á su esposo y al pequeño hijo que criaba.\"},{\"heading\":false,\"text\":\"Jask, por imprevision, arrastrado por su amor de padre, habia cometido, sin sospecharlo, dos grandes pecados; habia robado una madre y una esposa á su familia, y habia dado por nodriza á su hija una mala madre y una mala esposa.\"},{\"heading\":false,\"text\":\"Débil para el dolor de Aidamarah, Jask habia cometido además otro pecado: habia amargado el corazon de su esposa haciéndola concebir la horrible duda de si su hija era muerta ó viva.\"},{\"heading\":false,\"text\":\"Jask además habia mentido.\"},{\"heading\":false,\"text\":\"Jask, sin sospecharlo, habia vuelto sus espaldas á Dios.\"},{\"heading\":false,\"text\":\"Su amor hácia Aidamarah le habia perdido.\"},{\"heading\":false,\"text\":\"Habia pecado, y no podia arrepentirse de su pecado porque no sabia que lo habia cometido.\"},{\"heading\":false,\"text\":\"Dios es infinito y único, é incomprensible.\"},{\"heading\":false,\"text\":\"¡Loado sea su nombre!\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XXXIX\",\"blocks\":[{\"heading\":false,\"text\":\"Jask tuvo algun tiempo escondida á su hija y á su nodriza en la cabaña de un valle.\"},{\"heading\":false,\"text\":\"El mismo cuidaba de la nodriza; la llevaba el alimento y las ropas, y cuanto habia menester.\"},{\"heading\":false,\"text\":\"Encubierto siempre; siempre desconocido para la nodriza.\"},{\"heading\":false,\"text\":\"Y entre tanto hacia correr á los suyos por todas las tierras comarcanas en busca de su hija.\"},{\"heading\":false,\"text\":\"Y todas las tardes cuando el sol se ponia, Aidamarah rodeaba sus brazos á su cuello y le decia con las lágrimas en los ojos y el seno palpitante, pálida y consternada:\"},{\"heading\":false,\"text\":\"--¿Han encontrado tus esploradores á nuestra hija?\"},{\"heading\":false,\"text\":\"Y Jask respondia tambien con las lágrimas en los ojos.\"},{\"heading\":false,\"text\":\"--Dios no lo quiere.\"},{\"heading\":false,\"text\":\"Aidamarah iba á sentarse en el suelo en un ángulo con el rostro vuelto á la pared, y allí permanecia inmóvil.\"},{\"heading\":false,\"text\":\"Jask se limpiaba los ojos con el estremo de la toca, y salía.\"},{\"heading\":false,\"text\":\"Y así pasaron una luna y otra, hasta siete.\"},{\"heading\":false,\"text\":\"Un dia Jask anunció á Aidamarah, que se veia obligado á hacer un largo viage á las tierras de occidente.\"},{\"heading\":false,\"text\":\"Aidamarah estaba de nuevo en cinta.\"},{\"heading\":false,\"text\":\"Al saber que su esposo, á quien amaba con toda su alma, iba á separarse de ella, la desdichada se desmayó.\"},{\"heading\":false,\"text\":\"Jask, aprovechando su desmayo, montó en su corcel y solo, al tiempo que amanecia, sin llevar consigo mas que una bolsa llena de oro, su espada, su lanza y su escudo, y su hermano el perro-leon que le precedia y que jamás se separaba de él, partió de la ciudad y se trasladó al valle donde la nodriza amamantaba á su hijo.\"},{\"heading\":false,\"text\":\"En el camino entró en un rebaño de camellos que pastaban en la ribera, y compró el mas fuerte y poderoso.\"},{\"heading\":false,\"text\":\"Al pasar por una aldea, compró jaeces y almohadones para el camello, y un palanquin cubierto.\"},{\"heading\":false,\"text\":\"Luego siguió su ruta, llegó á la cabaña del valle, puso sobre el camello á su hija y á la nodriza, agua y mantenimientos, y tomó el camino de Tánger.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XL\",\"blocks\":[{\"heading\":false,\"text\":\"Hay en las tierras de Hiberis, por bajo de la sierra Nevada, mirando al distante mar, un pequeño valle junto al cual pasa la corriente humilde aun del Genil.\"},{\"heading\":false,\"text\":\"En una eminencia del valle, se ven aun los restos, ó mas bien los cimientos cubiertos de musgo de un antiguo edificio, siglos hace arruinado.\"},{\"heading\":false,\"text\":\"En aquellos tiempos, sobre estos cimientos, se levantaban cuatro torres unidas por cuatro muros de muralla, y en medio de estas cuatro torres una torre mayor.\"},{\"heading\":false,\"text\":\"Esta torre no tenia en su parte superior mas que una cámara, y una galería que daba salida á las escaleras de la torre, y entrada á la cámara.\"},{\"heading\":false,\"text\":\"Esta cámara estaba dividida en dos por una pared, que no pasaba de la mitad de la altura del espacio general.\"},{\"heading\":false,\"text\":\"En cada uno de estos compartimientos habia un agimez, pero abiertos en tan espesos muros, que desde adentro solo se veian á lo lejos las distantes montañas, y el lejano mar, cuyos horizontes se perdian en la niebla de Africa.\"},{\"heading\":false,\"text\":\"Cada uno de estos agimeces tenian, por la parte de adentro, una fuerte verja que se abria y se cerraba.\"},{\"heading\":false,\"text\":\"Búcaros con flores llenaban el espacio del muro, desde la verja á la parte esterior.\"},{\"heading\":false,\"text\":\"Estos dos compartimientos, si eran alegres, se debia á los agimecillos trasparentes de la cúpula estrellada, á las labores doradas de las paredes, á sus esmaltes de colores, á los surtidores que emanaban de las fuentes de mármol, á los brillantes espejos de plata con marcos de oro, que se veian entre las columnas que sostenian la cúpula.\"},{\"heading\":false,\"text\":\"Estos dos compartimientos tenian dentro de sí cuanto puede apetecer una muger en su retrete. El baño, el divan, los pebeteros, las esencias mas preciadas, las tapicerías mas ricas.\"},{\"heading\":false,\"text\":\"Estos dos compartimientos eran exactamente iguales.\"},{\"heading\":false,\"text\":\"Ya en el uno, ya en el otro, moraba contínuamente una muger.\"},{\"heading\":false,\"text\":\"Pero una muger maravillosamente hermosa, y ricamente engalanada.\"},{\"heading\":false,\"text\":\"¿Para quién se engalanaba aquella muger?\"},{\"heading\":false,\"text\":\"Ella no conocia á nadie.\"},{\"heading\":false,\"text\":\"Recordaba sí á unas gentes que la habian criado.\"},{\"heading\":false,\"text\":\"A dos ancianos, el uno hombre, la otra muger.\"},{\"heading\":false,\"text\":\"Pero hacia muchos años que habia dejado de ver á aquellos dos séres.\"},{\"heading\":false,\"text\":\"Muchos años, durante los cuales, no habia visto mas séres vivientes; que las moscas azules que cruzaban la dorada atmósfera de sus retretes, ó las mariposas de oro y colores, que venian á pararse un momento sobre los ramilletes de los búcaros, ó las golondrinas que revolaban junto á sus nidos fabricados bajo las almenas de la torre.\"},{\"heading\":false,\"text\":\"Esta muger, mejor dicho, esta jóven; porque solo contaba veinte y un años, era Zairah, la infortunada hija de Jask-Al-bahul, y de su esposa Aidamarah.\"},{\"heading\":false,\"text\":\"Zairah, desde el momento en que cumplió los ocho años, mucho antes de que el amor pudiera hablar á su corazon, habia sido sentenciada á la soledad.\"},{\"heading\":false,\"text\":\"Habia tres años que no veia á persona viviente.\"},{\"heading\":false,\"text\":\"Servíanla, sin embargo, como á una sultana.\"},{\"heading\":false,\"text\":\"Cuando se levantaba del sueño con el alba, encontraba abierta la puerta del otro departamento.\"},{\"heading\":false,\"text\":\"En cuanto Zairah pasaba de ella, la puerta se cerraba, y poco despues volvia á abrirse.\"},{\"heading\":false,\"text\":\"El departamento en que habia pasado la noche, habia sido cuidadosamente limpiado, renovadas las flores y las ropas, y puestos escelentes manjares sobre una rica alfombra en vagillas de oro.\"},{\"heading\":false,\"text\":\"Cuando Zairah deseaba alguna cosa, un perfume, un pájaro, un libro, un instrumento, tocaba con una varita de oro sobre una copa puesta sobre una mesa, dejaba sobre ella escrito en un papel su deseo, y pasaba á la otra parte.\"},{\"heading\":false,\"text\":\"Inmediatamente se cerraba la puerta, volvia á abrirse al poco tiempo, y cuando Zairah volvia, encontraba el objeto que habia pedido.\"},{\"heading\":false,\"text\":\"En una ocasion, se sintió enferma y llamó, avisando en un papel su estado.\"},{\"heading\":false,\"text\":\"Inmediatamente apareció una persona, enteramente cubierta, examinó á la jóven, y la asistió hasta que estuvo completamente restablecida.\"},{\"heading\":false,\"text\":\"Así vivia la infeliz hija de Jask-Al-bahul y Aidamarah.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XLI\",\"blocks\":[{\"heading\":false,\"text\":\"Segun lo habian predicho los astrólogos, Aidamarah tuvo dos hijos trascurridos tres veces siete meses desde el nacimiento de Zairah.\"},{\"heading\":false,\"text\":\"El uno se llamó Jacub; el otro Kaibar.\"},{\"heading\":false,\"text\":\"Aidamarah murió al dar á luz al último.\"},{\"heading\":false,\"text\":\"Era este tan monstruoso y tan feróz, como hermoso y apacible era Jacub.\"},{\"heading\":false,\"text\":\"Jask hizo que los astrólogos consultasen el destino de sus dos hijos.\"},{\"heading\":false,\"text\":\"Los astrólogos consultaron las estrellas y dijeron al rey:\"},{\"heading\":false,\"text\":\"--Señor, aparta de tí á tus hijos, críalos al uno lejos del otro, porque si crecieren juntos ó si algun dia se encontraren se despedazarán.\"},{\"heading\":false,\"text\":\"Jask envió á Kaibar á la parte oriental de Africa.\"},{\"heading\":false,\"text\":\"A Jacub á la parte occidental.\"},{\"heading\":false,\"text\":\"Pasaron tres veces siete años.\"},{\"heading\":false,\"text\":\"Un dia Kaibar, cuyos instintos salvages no habia podido contrariar una escelente enseñanza, vagaba por las montañas de la Abisinia, desnudo, con el carcaj á la espalda, y en las manos el arco entezado.\"},{\"heading\":false,\"text\":\"Seguia á una corza, á quien seguia jadeante y cansado su corcillo.\"},{\"heading\":false,\"text\":\"Tendió el arco, é iba á disparar, cuando entre la inofensiva bestia y su cria se levantó una forma humana.\"},{\"heading\":false,\"text\":\"Era una muger negra, pero hermosa, como no habia visto otra Kaibar.\"},{\"heading\":false,\"text\":\"Vestia una túnica roja, y sobre sus cabellos negros y brillantes llevaba una diadema de corales.\"},{\"heading\":false,\"text\":\"--¿Quién eres? dijo Kaibar sintiéndose fascinado por primera vez por aquella imponente y negra belleza.\"},{\"heading\":false,\"text\":\"--Soy una sombra, dijo ella.\"},{\"heading\":false,\"text\":\"--¡Una sombra!\"},{\"heading\":false,\"text\":\"--Sí, la sombra de una muger.\"},{\"heading\":false,\"text\":\"--¿Esa muger ha muerto?\"},{\"heading\":false,\"text\":\"--No.\"},{\"heading\":false,\"text\":\"--¿Vive?\"},{\"heading\":false,\"text\":\"--Sí. Contémplame bien: yo soy su espíritu, que vago buscando el amor sobre la tierra, y el destino me ha traido á tí.\"},{\"heading\":false,\"text\":\"--¿Que buscas tú el amor?... ¿Pues cómo no te busca el amor á tí?\"},{\"heading\":false,\"text\":\"--He nacido para vivir sola; para morir sola.\"},{\"heading\":false,\"text\":\"--¡Ah! yo te amo, dijo Kaibar.\"},{\"heading\":false,\"text\":\"Y adelantó hácia la jóven.\"},{\"heading\":false,\"text\":\"Pero la jóven siguió delante de él ligera y feble como llevada á impulsos del vientecillo de la tarde.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡yo te amo, y si no eres mia... moriré! dijo Kaibar estendiendo los brazos hácia la hermosa.\"},{\"heading\":false,\"text\":\"--Consulta á un varon que encontrarás allá arriba, en la hendidura de aquella pared, y él te dirá lo que necesitas hacer para alcanzar el cuerpo de mi sombra.\"},{\"heading\":false,\"text\":\"Y la hermosa sombra negra desapareció como un vapor.\"},{\"heading\":false,\"text\":\"Kaibar habia quedado con el alma envenenada.\"},{\"heading\":false,\"text\":\"El sol ardia en lo mas alto del cielo.\"},{\"heading\":false,\"text\":\"Las palmeras y los nopales, inclinaban sus cabezas mustias bajo su rayo abrasador.\"},{\"heading\":false,\"text\":\"Kaibar empezó á trepar por la pendiente.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XLII\",\"blocks\":[{\"heading\":false,\"text\":\"Cuando llegó á la entrada de la grieta, encontró dentro á un ermitaño.\"},{\"heading\":false,\"text\":\"Era viejísimo, encorvado, con una larga barba blanca, calzados los pies con unas sandalias de piel de camello, vestido el cuerpo con un sayo de lana y ceñidos los lomos con una cuerda.\"},{\"heading\":false,\"text\":\"Sobre sus rodillas tenia abierto un libro negro.\"},{\"heading\":false,\"text\":\"Aquel libro estaba escrito con caractéres rojos.\"},{\"heading\":false,\"text\":\"Cuando entró el jóven, el ermitaño clavó en él sus pequeños ojos grises y relucientes.\"},{\"heading\":false,\"text\":\"Kaibar retrocedió.\"},{\"heading\":false,\"text\":\"Aquel hombre le ponia espanto.\"},{\"heading\":false,\"text\":\"--Si eres cobarde, dijo el ermitaño con voz profunda y cavernosa, ¿por qué vienes á mí?\"},{\"heading\":false,\"text\":\"--¿Quién eres? dijo Kaibar.\"},{\"heading\":false,\"text\":\"--Yo soy Eblís[95], el viejo.\"},{\"heading\":false,\"text\":\"--¡Tú! ¡tú Satanás!\"},{\"heading\":false,\"text\":\"--Yo soy.\"},{\"heading\":false,\"text\":\"--Y bien, dijo Kaibar; ¿me puedes tú dar los amores de la doncella negra?\"},{\"heading\":false,\"text\":\"--Sí; si tú los quieres.\"},{\"heading\":false,\"text\":\"--¡Que si los quiero! por ella se estremece mi corazon.\"},{\"heading\":false,\"text\":\"--¿Sabes quién es esa doncella?\"},{\"heading\":false,\"text\":\"--Debe ser hija de un rey poderoso ó de un poderoso genio.\"},{\"heading\":false,\"text\":\"--En efecto esa doncella es hija de un rey.\"},{\"heading\":false,\"text\":\"--¡De un rey! ¿y cómo se llama?\"},{\"heading\":false,\"text\":\"--Jask-Al-bahul.\"},{\"heading\":false,\"text\":\"--Yo he oido pronunciar el nombre de ese rey.\"},{\"heading\":false,\"text\":\"--Ya lo creo, como que ese rey es tu padre.\"},{\"heading\":false,\"text\":\"--¡Mi padre un rey!\"},{\"heading\":false,\"text\":\"--Sí, dijo el diablo; siéntate y escucha.\"},{\"heading\":false,\"text\":\"Kaibar se sentó.\"},{\"heading\":false,\"text\":\"Eblís le contó la historia de sus padres.\"},{\"heading\":false,\"text\":\"Kaibar le escuchó con atencion.\"},{\"heading\":false,\"text\":\"Cuando el diablo hubo concluido, preguntó á Kaibar:\"},{\"heading\":false,\"text\":\"--¿Y á pesar de saber que esa sombra que te ha enamorado, es la sombra de tu hermana Zairah, insistes en tus amores?\"},{\"heading\":false,\"text\":\"--¡La amo! ¡oh! ¡sí! ¡la amo! ¿pero por qué es negra la luz de mis ojos?\"},{\"heading\":false,\"text\":\"--Antes era blanca como la luna, pero desde que ha amado á tu hermano Jacub...\"},{\"heading\":false,\"text\":\"--¡A mi hermano Jacub!...\"},{\"heading\":false,\"text\":\"--Sí, el que vive en el Cairvan.\"},{\"heading\":false,\"text\":\"Un pensamiento de muerte pasó por el corazon de Kaibar.\"},{\"heading\":false,\"text\":\"--Pues bien, dijo, yo quiero ver á mi hermana Zairah, quiero ser amado por ella.\"},{\"heading\":false,\"text\":\"--La verás, la arrebatarás de su prision, pero yo no sé si te amará.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡véala yo! ¡sea mia!\"},{\"heading\":false,\"text\":\"--Para ello necesitas mi ayuda.\"},{\"heading\":false,\"text\":\"--¿Y no me la darás?\"},{\"heading\":false,\"text\":\"--Sí, pero dame tú tu alma.\"},{\"heading\":false,\"text\":\"--¡Mi alma! ¿pues quién eres tú?\"},{\"heading\":false,\"text\":\"--Yo soy Eblís.\"},{\"heading\":false,\"text\":\"--¿Y puedes tú darme lo que deseo?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--Pues toma en buen hora mi alma.\"},{\"heading\":false,\"text\":\"El diablo metió la mano debajo de su túnica y sacó un pedazo de caña, con la cual se habia hecho una especie de tubo, cerrado por un nudo natural en la parte inferior, y tapado con un pedazo de pino en la parte superior.\"},{\"heading\":false,\"text\":\"El diablo quitó aquel tapon y mostró á Kaibar el interior de la caña, relleno de una especie de pomada verde.\"},{\"heading\":false,\"text\":\"--Esta es la hiel de un enamorado loco que se ahorcó por una muger que no le amaba, dijo Satanás.\"},{\"heading\":false,\"text\":\"--¿Y para qué sirve este unto?\"},{\"heading\":false,\"text\":\"--Cuando quisieres penetrar hasta Zairah, úntate con él las sienes, sobre el corazon, en las palmas de las manos y en las plantas de los pies y pronuncia su nombre.\"},{\"heading\":false,\"text\":\"El diablo entregó la caña con su contenido maldito á Kaibar.\"},{\"heading\":false,\"text\":\"Kaibar se untó inmediatamente con aquella verde pomada las partes que el diablo le habia dicho, y pronunció el nombre de Zairah.\"},{\"heading\":false,\"text\":\"Aun no habia acabado de pronunciarle, cuando se encontró sobre una montaña al pie de un castillo, junto al muro de unos jardines.\"},{\"heading\":false,\"text\":\"Una muger jóven, negra y hermosa, adelantaba sobre un caballo negro, precedida por un perro, y seguida por un caballero armado con armas negras, ginete en otro poderoso caballo.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XLIII\",\"blocks\":[{\"heading\":false,\"text\":\"Al ver la dama á Kaibar se estremeció.\"},{\"heading\":false,\"text\":\"El perro-leon rugió.\"},{\"heading\":false,\"text\":\"El caballo se encabritó y luego partió á la carrera.\"},{\"heading\":false,\"text\":\"Tras el caballo que conducia á la jóven, partió el del caballero del arnés negro.\"},{\"heading\":false,\"text\":\"Kaibar con la pujanza de un jigante, siguió á la carrera al caballo que conducia la dama.\"},{\"heading\":false,\"text\":\"El destino habia reunido á los tres hermanos.\"},{\"heading\":false,\"text\":\"Muy pronto, y por distinto camino, se perdieron el caballo de la dama negra, y el del caballero del negro arnés.\"},{\"heading\":false,\"text\":\"--¡Y cosa estraña!\"},{\"heading\":false,\"text\":\"Delante de Kaibar corria, corria, como pretendiendo guiarle, su tio, el hermano de su padre, el perro-leon.\"},{\"heading\":false,\"text\":\"¿Quién era el otro caballero de las armas negras?\"},{\"heading\":false,\"text\":\"¿Cómo habia podido apoderarse de la negra y hermosísima dama?\"},{\"heading\":false,\"text\":\"Aquel caballero era Jacub, el otro hijo del rey Jask-Al-bahul.\"},{\"heading\":false,\"text\":\"El hermano de Kaibar.\"},{\"heading\":false,\"text\":\"Una noche velaba Jacub.\"},{\"heading\":false,\"text\":\"Ya lo sabeis.\"},{\"heading\":false,\"text\":\"El mismo nos lo ha dicho.\"},{\"heading\":false,\"text\":\"La pálida luz de la luna iluminaba las almenas de la torre de la alcazaba de Kaibar, donde el jóven príncipe se encontraba.\"},{\"heading\":false,\"text\":\"Estaba triste.\"},{\"heading\":false,\"text\":\"Un sueño vago y misterioso de amor habia enlanguidecido su alma.\"},{\"heading\":false,\"text\":\"Ansiaba, y no sabia lo que ansiaba.\"},{\"heading\":false,\"text\":\"Tenia sed, y no sabia en qué fuente podia templarla.\"},{\"heading\":false,\"text\":\"Su corazon ardia, y Jacub buscaba en vano la causa de aquel fuego.\"},{\"heading\":false,\"text\":\"De improviso, allá á lo lejos, como viniendo del otro lado de los mares, resonó una voz dulcísima y oyó aquel romance de amores que decia:\"},{\"heading\":false,\"text\":\"Libres los vientos--zumbando vagan; libres navegan--las nubes blancas, del firmamento--la azul campaña; libres batiendo--las leves alas, las golondrinas--besan las aguas, del ancho lago--que riza el aura; libres las ondas--la curva playa, amantes orlan--de espumas cándidas; las mariposas--engalanadas ora revuelan,--ora se paran, entre las flores--de mi ventana, y yo entretanto--me miro esclava, me cercan muros,--puertas me guardan, y en mis megillas--el sol vé lágrimas, cuando aparece--por la mañana, y aun vé mis ojos--que el llanto empaña cuando á los mares--cansado baja.\"},{\"heading\":false,\"text\":\"Y el eco lánguido y cadencioso, repetia débilmente aquel cantar que parecia habian traido á los oidos de Jacub hadas invisibles.\"},{\"heading\":false,\"text\":\"Jacub habia sido educado en Cairvan, sin conocer su orígen, por un anciano kadí.\"},{\"heading\":false,\"text\":\"Cuando despues de haber permanecido largo tiempo en las almenas de la torre, despues de que se hubo perdido en el silencio el lejano y voluptuoso eco de la cancion, bajó á la cámara, encontró prosternado y orando al anciano kadí.\"},{\"heading\":false,\"text\":\"--¿Qué tribulacion nos amenaza, mi buen Abu-Kair? dijo el jóven príncipe dirijiéndose al anciano.\"},{\"heading\":false,\"text\":\"--La tentacion vuela en torno de mí, dijo el anciano; Satanás ha rozado mi frente con sus alas de vampiro.\"},{\"heading\":false,\"text\":\"--¿Y qué te ha dicho Satanás?\"},{\"heading\":false,\"text\":\"--¡Oh! el pérfido me enseñaba una bolsa llena de oro.\"},{\"heading\":false,\"text\":\"--¡Una bolsa llena de oro!\"},{\"heading\":false,\"text\":\"--Y un anillo con una gruesa esmeralda.\"},{\"heading\":false,\"text\":\"--¡Ah!\"},{\"heading\":false,\"text\":\"--Y un rosario de coral y de diamantes.\"},{\"heading\":false,\"text\":\"--¡Cosa estraña! dijo el príncipe; ¡yo tengo oro y un anillo con una esmeralda y un rosario de corales y diamantes!\"},{\"heading\":false,\"text\":\"--En efecto, el diablo para ofrecerme estas cosas, habia tomado tu figura.\"},{\"heading\":false,\"text\":\"--¡Ah, el malo! ¡pues si yo estaba hace poco en lo alto de la torre!\"},{\"heading\":false,\"text\":\"--Ya lo sabia yo; y además habia conocido á Satanás, porque aunque habia tomado tu figura, no habia podido replegar de tal modo á sus espaldas sus negras alas que yo no las viese.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿y qué te decia?\"},{\"heading\":false,\"text\":\"--Yo amo á una muger, no la conozco; pero la siento en mi alma; debe ser muy hermosa, porque mis ojos la buscan ansiosos como el ciego busca la luz; muy jóven, porque mi alma al sentirla se refresca; muy pura, porque el fuego en que enciende mi alma es dulce y tibio como el sol del primer dia de la primavera.\"},{\"heading\":false,\"text\":\"--¡Ah! pues yo amo así; yo siento así, dijo el príncipe. ¿Y qué mas te decia el condenado?\"},{\"heading\":false,\"text\":\"--Esa doncella debe ser princesa, porque al presentirla, mi alma se enorgullece; hija de un poderoso debe ser.\"},{\"heading\":false,\"text\":\"--Sí, sí, así lo siento yo. Pero continúa relatándome lo que decia el negro espíritu bajo mi figura.\"},{\"heading\":false,\"text\":\"--Me decia: yo no sé quien soy y quiero saberlo, hánme criado sin decirme el nombre de mi padre, pero debe ser poderoso y noble, y debe amarme mucho, porque yo tengo hermosos caballos de Arabia, y armas de oro, y túnicas preciadas, y joyas, y tesoros. ¿Quién es mi padre?\"},{\"heading\":false,\"text\":\"--¿Y qué contestaste tú al diablo?\"},{\"heading\":false,\"text\":\"--Yo le dije, no te lo puedo decir. Entonces el diablo sacó una gran bolsa y me la mostró.\"},{\"heading\":false,\"text\":\"--¿Era cómo esta? dijo el príncipe sacando una bolsa, y mostrándola al kadí; cuyos ojos brillaron.\"},{\"heading\":false,\"text\":\"--Como esa era.\"},{\"heading\":false,\"text\":\"--Toma, pues, dijo el príncipe; quiero que tu sueño se realice.\"},{\"heading\":false,\"text\":\"El kadí se apoderó con ánsia de la bolsa.\"},{\"heading\":false,\"text\":\"--Pero dime lo que dijiste al diablo en mi figura; dijo el príncipe.\"},{\"heading\":false,\"text\":\"--Yo, dijo el kadí, dije al diablo: tú eres hijo de un rey.\"},{\"heading\":false,\"text\":\"--¡Hijo de un rey! ¡de un rey poderoso!\"},{\"heading\":false,\"text\":\"--Sí, de un rey que tiene sus dominios en los linderos del Desierto.\"},{\"heading\":false,\"text\":\"--¿Y cómo se llama ese rey?\"},{\"heading\":false,\"text\":\"--Lo mismo me preguntó el diablo, pero yo no quise contestar; entonces me enseñó una hermosa sortija con una gruesa esmeralda y me dijo: tuya es si me declaras el nombre de mi padre.\"},{\"heading\":false,\"text\":\"--Hé aquí la sortija, dijo el príncipe quitándose de un dedo de la mano izquierda una magnífica esmeralda.\"},{\"heading\":false,\"text\":\"El kadí se apoderó de la sortija con doble ánsia que con la que se habia apoderado de la bolsa.\"},{\"heading\":false,\"text\":\"--Tu padre se llama Jask-Al-bahul, dijo el kadí.\"},{\"heading\":false,\"text\":\"--Y dime, ¿tiene mi padre otros hijos? y téngalos ó no, ¿por qué me ha separado de sí?\"},{\"heading\":false,\"text\":\"--Esta misma pregunta me hizo el diablo, repuso el kadí, pero yo callé; entonces el diablo me enseñó un largo rosario de corales y diamantes, y me dijo:\"},{\"heading\":false,\"text\":\"--Esta joya es preciosa; si me revelas mi historia te la doy.\"},{\"heading\":false,\"text\":\"--Toma, toma, dijo el príncipe sacando do su seno un hermoso rosario de corales y diamantes; pero cuéntame mi historia.\"},{\"heading\":false,\"text\":\"El kadí se apoderó del rosario, y contó á Jacub la historia de su padre y el horóscopo suyo y el de sus hermanos.\"},{\"heading\":false,\"text\":\"Jask á nadie habia revelado aquel secreto, pero lo sabia el diablo que todo lo sabe, y tomando la figura del kadí, que dormia en otro aposento, habia revelado al jóven príncipe su destino, y al revelárselo se habia valido de aquellas trazas para quitarle el bolsillo, la sortija y el rosario, que eran tres talismanes que debian proteger al príncipe contra la desgracia.\"},{\"heading\":false,\"text\":\"Cuando el príncipe supo su historia, dijo:\"},{\"heading\":false,\"text\":\"--¡Ah! por noble y alta y poderosa que sea la princesa que me enamora, yo soy tambien alto, noble y poderoso; ¿pero dónde está esta princesa, cuya voz he oido dulce y enamorada, como viniendo de la inmensidad?\"},{\"heading\":false,\"text\":\"--Yo no puedo decírtelo, señor, contestó el falso kadí, esto es: el diablo que para perder al jóven, habia tomado la figura del kadí: pero puedo decirte donde hay un sábio, que te revelará lo que deseas.\"},{\"heading\":false,\"text\":\"--¿Y dónde mora ese sábio?\"},{\"heading\":false,\"text\":\"--En la selva cercana á Kairvan.\"},{\"heading\":false,\"text\":\"--Pero yo no puedo salir de este castillo.\"},{\"heading\":false,\"text\":\"--Yo te sacaré de él: sígueme; pero es necesario que te dejes vendar los ojos.\"},{\"heading\":false,\"text\":\"Y el diablo vendó los ojos al príncipe, le asió de la mano, y le guió.\"},{\"heading\":false,\"text\":\"Estuvieron andando durante mucho tiempo; primero subiendo y bajando escaleras, despues atravesando subterráneos, al cabo marchando por el campo.\"},{\"heading\":false,\"text\":\"Despues de algunas horas de marcha, el diablo se detuvo, quitó de los ojos la venda al príncipe, y este se encontró en una inmensa caverna, á cuyo fondo se despeñaba un torrente que salia por la entrada de la caverna y se perdia en la selva.\"},{\"heading\":false,\"text\":\"A la márgen izquierda del torrente, sobre unas peñas, debajo de la bóveda natural de la caverna y como escondida en un negro seno, habia una choza formada por troncos de árboles y ramas secas.\"},{\"heading\":false,\"text\":\"Dentro ardia una luz rojiza.\"},{\"heading\":false,\"text\":\"Sentado junto á aquella luz habia un viejo, viejísimo, que cantaba tristemente:\"},{\"heading\":false,\"text\":\"«Está escrito: la torre se levantará sobre la sima.\"},{\"heading\":false,\"text\":\"»Y la torre tendrá siete suelos.\"},{\"heading\":false,\"text\":\"»Y cada uno de estos suelos estará habitado por un espíritu maldito.\"},{\"heading\":false,\"text\":\"»Y cuando ya estuvieren en la torre los siete espíritus condenados, la guardará otro ginete en un caballo sin cabeza, acompañado de un perro velludo.\"},{\"heading\":false,\"text\":\"»Así está escrito, y lo que está escrito se cumple.\"},{\"heading\":false,\"text\":\"»Faltan aun centenares de años para que se cumpla lo que está escrito.\"},{\"heading\":false,\"text\":\"»Pero finados que sean esos años, lo que está escrito se cumplirá.»\"},{\"heading\":false,\"text\":\"Jacub, que habia oido esto, se volvió al diablo que habia tomado la figura del kadí para conducirle allí, y no le encontró.\"},{\"heading\":false,\"text\":\"Entonces, decidido á todo, entró en la oscura cabaña donde cantaba el viejo.\"},{\"heading\":false,\"text\":\"--¿Quién eres? le preguntó este al verle entrar.\"},{\"heading\":false,\"text\":\"--Yo soy el príncipe Jacub, hijo del poderoso rey Jask-Al-bahul.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿tú eres el que estás enamorado de tu hermana?\"},{\"heading\":false,\"text\":\"--¡Qué! esclamó el príncipe: ¿es el de mi hermana Zairah, el dulce, el ardiente espíritu que vive dentro de mi alma?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Y cómo haré para llegar á mi hermana?\"},{\"heading\":false,\"text\":\"--¿No te retrae de tus amores el saber que es hermana tuya?\"},{\"heading\":false,\"text\":\"--No.\"},{\"heading\":false,\"text\":\"--¿No temes perder tu alma logrando tus deseos?\"},{\"heading\":false,\"text\":\"--Yo la amo.\"},{\"heading\":false,\"text\":\"--¿Y si tu hermano la amase tambien?\"},{\"heading\":false,\"text\":\"--Mataria á mi hermano.\"},{\"heading\":false,\"text\":\"--¿Y si yo te pidiese tu alma por el cumplimiento de tus deseos?\"},{\"heading\":false,\"text\":\"--¿Pero quién eres tú?\"},{\"heading\":false,\"text\":\"--Yo soy Satanás.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿y necesitas mi alma á cambio de mi amor?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Y no me darás mi amor, si no te doy mi alma?\"},{\"heading\":false,\"text\":\"--No.\"},{\"heading\":false,\"text\":\"--Pues te la doy.\"},{\"heading\":false,\"text\":\"--Firma aquí, dijo el diablo, presentando á Jacub un papel en blanco.\"},{\"heading\":false,\"text\":\"Jacub enloquecido por su amor firmó.\"},{\"heading\":false,\"text\":\"--Dame mis amores, dijo despues de haber firmado.\"},{\"heading\":false,\"text\":\"El diablo hirió con el pie el suelo, tembló ligeramente la tierra, se oyó en sus entrañas un sordo bramido, y apareció saliendo de la tierra un caballo negro encubertado de batalla, llevando sobre su lomo una armadura negra completa, un escudo, una lanza, una hacha y una espada.\"},{\"heading\":false,\"text\":\"--Cíñete esas armas que están sobre el caballo, dijo el diablo.\"},{\"heading\":false,\"text\":\"Jacub se ciñó el arnés negro y reluciente.\"},{\"heading\":false,\"text\":\"Creyó entonces que su vida se aumentaba, que se aumentaban sus fuerzas, que se aumentaba su entendimiento. Sintióse mas jóven, mas ardiente, mas ágil.\"},{\"heading\":false,\"text\":\"Supo cosas que hasta entonces no habia sabido.\"},{\"heading\":false,\"text\":\"En una palabra: se trasformó en otro hombre y creció en hermosura.\"},{\"heading\":false,\"text\":\"--Monta á caballo, le dijo el diablo.\"},{\"heading\":false,\"text\":\"El príncipe montó, el caballo se encabritó feroz, pero el príncipe le contuvo, y le hizo piafar dócil á su mano.\"},{\"heading\":false,\"text\":\"--¿Y qué he de hacer ahora para llegar á la amada de mi alma?\"},{\"heading\":false,\"text\":\"--Ese caballo te llevará veloz como el pensamiento.\"},{\"heading\":false,\"text\":\"--¡Pero mi amada está encerrada tras fuertes murallas!\"},{\"heading\":false,\"text\":\"--Mientras lleves puesta esta armadura negra, no solo te defenderá ella de todos los peligros, de todos los golpes, de todas las asechanzas, sino que podrás entrar en donde quieras y salir cuando lo deseares. La persona que lleves asida de la mano, podrá entrar y salir del mismo modo, y asimismo las personas que vayan asidas á la que vaya asida á tí.\"},{\"heading\":false,\"text\":\"--¿De modo que podrá penetrar hasta Zairah?\"},{\"heading\":false,\"text\":\"--En este momento sueña Zairah contigo, y te llama.\"},{\"heading\":false,\"text\":\"--Pues bien, caballo mio; llévame hasta el castillo donde mora mi amada.\"},{\"heading\":false,\"text\":\"Apenas habia pronunciado el príncipe estas palabras, cuando el caballo partió como una flecha, salió de la caverna, atravesó la selva, atravesó la sierra, llegó al mar, le pasó, puso los cascos en las playas de Andalucía, trepó por las verdes vertientes de las Alpujarras, y poco despues quedaba inmóvil delante de la puerta de un fuerte castillo.\"},{\"heading\":false,\"text\":\"Aquel castillo era el en que estaba cautiva desde su infancia Zairah.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XLIV\",\"blocks\":[{\"heading\":false,\"text\":\"Velaba Zairah.\"},{\"heading\":false,\"text\":\"Una vision de amores la habia despertado de su sueño.\"},{\"heading\":false,\"text\":\"Veia ante sí un caballero blanco, pálido, hermoso, que la miraba intensamente, acariciándola con la dulce mirada de sus resplandecientes ojos negros.\"},{\"heading\":false,\"text\":\"--¡Oh tú, vision de mi deseo, dijo Zairah, ó semejanza de un hombre! ¡oh tú, á quien mi corazon ama! ¡sino existes desaparece, pero si vives, si me escuchas, si me amas como yo te amo, ven!\"},{\"heading\":false,\"text\":\"Ven, porque me siento morir.\"},{\"heading\":false,\"text\":\"Mi cautiverio me es ya insoportable.\"},{\"heading\":false,\"text\":\"Mi soledad horrorosa.\"},{\"heading\":false,\"text\":\"Ven, amado de mi alma.\"},{\"heading\":false,\"text\":\"Dá vida á mi corazon y libertad á mi tristeza, y consuelo á mi desesperacion.\"},{\"heading\":false,\"text\":\"Ven que yo te amo.\"},{\"heading\":false,\"text\":\"Y mi amor es vírgen, vírgen como el primer perfume de las pequeñas violetas azules y amarillas que orlan los bordes de mis búcaros en la primavera.\"},{\"heading\":false,\"text\":\"Ven, amado de mi alma, que soy hermosa.\"},{\"heading\":false,\"text\":\"Ven, y yo seré para tí la paloma amante que arrullará tu sueño.\"},{\"heading\":false,\"text\":\"Tú serás para mí el cedro oloroso y fuerte donde anida la paloma.\"},{\"heading\":false,\"text\":\"Ven, amado de mi alma, si existes; y si no existes, huye de mi pensamiento, fantasma tentador, y no me atormentes.\"},{\"heading\":false,\"text\":\"De improviso calló Zairah.\"},{\"heading\":false,\"text\":\"Habia sentido pisadas, unas pisadas que la eran desconocidas.\"},{\"heading\":false,\"text\":\"Sonó una puerta, y las pisadas se sintieron mas próximas.\"},{\"heading\":false,\"text\":\"Abrióse por fin la puerta del compartimiento donde se encontraba Zairah, y apareció Jacub.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XLV\",\"blocks\":[{\"heading\":false,\"text\":\"Zairah se puso de pie.\"},{\"heading\":false,\"text\":\"Al verla Jacub tan hermosa, tan deslumbrante, retrocedió y quedó inmóvil.\"},{\"heading\":false,\"text\":\"--¿Quién eres tú? dijo Zairah con voz dulce, adelantando hácia él.\"},{\"heading\":false,\"text\":\"--Yo te amo, dijo Jacub saliendo á su encuentro.\"},{\"heading\":false,\"text\":\"Y Zairah vió en Jacub al amante de su vision.\"},{\"heading\":false,\"text\":\"Y Jacub vió en Zairah á la amada de su pensamiento.\"},{\"heading\":false,\"text\":\"--Y yo te amo, dijo Zairah, arrojándose en los brazos de Jacub.\"},{\"heading\":false,\"text\":\"Entonces resonó leve, amarga, distante como venida de la inmensidad una carcajada horrible.\"},{\"heading\":false,\"text\":\"Una carcajada del infierno.\"},{\"heading\":false,\"text\":\"Y los jóvenes no la oyeron, porque habian nacido para amarse y estaban trasportados de amor el uno en los brazos del otro.\"},{\"heading\":false,\"text\":\"Y tras la infernal carcajada, sonó una voz tan pavorosa como ella.\"},{\"heading\":false,\"text\":\"Y aquella voz esclamó:\"},{\"heading\":false,\"text\":\"«Lo que está escrito se cumple: la descendencia de Abraham vuelve á ser maldita.»\"},{\"heading\":false,\"text\":\"Y zumbó el huracan al rededor de los muros.\"},{\"heading\":false,\"text\":\"Y penetrando en un pujante remolino por los ajimeces, apagó la lámpara que alumbraba el retrete de Zairah.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XLVI\",\"blocks\":[{\"heading\":false,\"text\":\"Empezó á amanecer.\"},{\"heading\":false,\"text\":\"Una blanca faja de luz orló el horizonte.\"},{\"heading\":false,\"text\":\"Aquella luz débil fué creciendo, creciendo, y al fin iluminó los objetos de la cámara de Zairah.\"},{\"heading\":false,\"text\":\"Zairah dormia en el divan.\"},{\"heading\":false,\"text\":\"En sus entreabiertos labios vagaba una sonrisa de deleite.\"},{\"heading\":false,\"text\":\"Y Jacub la contemplaba con espanto.\"},{\"heading\":false,\"text\":\"Porque Zairah, de blanca que era como el alba, se habia tornado negra como la noche.\"},{\"heading\":false,\"text\":\"Y sin embargo, su hermosura habia crecido hasta el punto de ser irresistible.\"},{\"heading\":false,\"text\":\"Del mismo modo que habia cambiado el color de su tez, habia cambiado el color de sus ropas.\"},{\"heading\":false,\"text\":\"Su túnica, de blanca que era se habia vuelto roja.\"},{\"heading\":false,\"text\":\"El collar de azabache que antes enaltecia la blancura de su garganta, se habia convertido en una gargantilla de perlas, cuya lasciva blancura contrastaba con el luciente negro de su cuello y de su seno.\"},{\"heading\":false,\"text\":\"Y Jacub la contemplaba con espanto y con adoracion á un tiempo.\"},{\"heading\":false,\"text\":\"Y como si la mirada fija y candente de Jacub hubiera tenido una fuerza sobrenatural, Zairah abrió los ojos.\"},{\"heading\":false,\"text\":\"¡Oh! ¡y qué mirada la de los ojos de Zairah!\"},{\"heading\":false,\"text\":\"Brillaban como astros de amor, enamoraban como las mas dulces palabras, como las mas regaladas armonías, como los perfumes mas suaves.\"},{\"heading\":false,\"text\":\"Jacub se sintió morir.\"},{\"heading\":false,\"text\":\"Y Zairah, al ver la luz del dia esclamó:\"},{\"heading\":false,\"text\":\"--¡Huyamos, amado mio! ¡huyamos! si es que puedes sacarme por donde tu has entrado; ¡huyamos! porque si te encuentran aquí, te matarán.\"},{\"heading\":false,\"text\":\"Huyamos y vivamos siempre juntos.\"},{\"heading\":false,\"text\":\"No quiero volver á estar sola.\"},{\"heading\":false,\"text\":\"Si tu me dejases, aquí moriria; y moriria desesperada.\"},{\"heading\":false,\"text\":\"Y tú no querrás que tu Zairah muera.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡no!\"},{\"heading\":false,\"text\":\"Cuánto te amo. Creo que tu amor me ha dado una nueva vida.\"},{\"heading\":false,\"text\":\"Y sí, sí; me estoy viendo en mi hermoso espejo de plata y estoy mas blanca, mas blanca: y mis ojos y mis cabellos son mas negros.\"},{\"heading\":false,\"text\":\"--¡Blanca! ¡blanca! esclamó con terror Jacub.\"},{\"heading\":false,\"text\":\"Y miró al espejo en que se miraba la jóven.\"},{\"heading\":false,\"text\":\"Y su terror se aumentó.\"},{\"heading\":false,\"text\":\"En efecto, en el espejo Zairah parecia blanca, de una manera deslumbradora.\"},{\"heading\":false,\"text\":\"Pero cuando la miraba Jacub, la veia negra.\"},{\"heading\":false,\"text\":\"¿Qué podia ser aquello?\"},{\"heading\":false,\"text\":\"Y Zairah esclamaba:\"},{\"heading\":false,\"text\":\"--¡Huyamos, amado mio! ¡huyamos! porque si te encuentran aquí te matarán.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XLVII\",\"blocks\":[{\"heading\":false,\"text\":\"Entre tanto, ó mejor, poco antes de que amaneciera, una inmensa nube flotaba en el espacio y adelantó de la parte de Oriente á la de Occidente.\"},{\"heading\":false,\"text\":\"Cuando estuvo cerca del castillo de las Alpujarras, donde habia estado encerrada veinte y un años Zairah, la nube descendió.\"},{\"heading\":false,\"text\":\"Empezaba á amanecer.\"},{\"heading\":false,\"text\":\"A la dudosa luz del crepúsculo pudo verse, que lo que parecia una nube era un inmenso paño rojo.\"},{\"heading\":false,\"text\":\"Era en efecto la bandera mágica que en los tiempos de su juventud habia tomado Jask-Al-bahul á los jigantes del Desierto.\"},{\"heading\":false,\"text\":\"La bandera descendió á los pies del castillo, sobre la cumbre de la montaña.\"},{\"heading\":false,\"text\":\"Sobre la nube venian Jask-Al-bahul, su caballo, en pelo, sin mas que el freno, y el perro-leon.\"},{\"heading\":false,\"text\":\"Cuando hubieron llegado, Jask, su hermano el perro y su caballo, salieron de la bandera.\"},{\"heading\":false,\"text\":\"En cuanto hubieron salido de ella, la bandera roja se evaporó como una emanacion de sangre.\"},{\"heading\":false,\"text\":\"Jask, llevando del diestro á su caballo y seguido por su hermano el perro se dirijió á la poterna del castillo.\"},{\"heading\":false,\"text\":\"Jask vió con terror que junto á la poterna habia un caballo encubertado.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡si habré llegado tarde! esclamó.\"},{\"heading\":false,\"text\":\"Y apresuró el paso, hácia la poterna.\"},{\"heading\":false,\"text\":\"Pero antes de llegar á ella, la poterna se abrió y apareció Jacub llevando de la mano á Zairah.\"},{\"heading\":false,\"text\":\"Jask la vió negra, como la veia Jacub, y al reparar en su color lanzó un grito de espanto y se arrojó hácia los dos jóvenes.\"},{\"heading\":false,\"text\":\"Pero antes de decir lo que aconteció, digamos por qué habia venido al castillo donde se guardaba su hija sobre la roja bandera de los jigantes el rey Jask-Al-bahul.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XLVIII\",\"blocks\":[{\"heading\":false,\"text\":\"Hacia algun tiempo que Jask veia en sueños una vision terrible.\"},{\"heading\":false,\"text\":\"Un jóven hermoso y pálido adelantaba hácia él llevando á una jóven de la mano.\"},{\"heading\":false,\"text\":\"Jask queria ponerse entre ambos jóvenes; pero en el punto en que lo pretendia, sus ojos se nublaban, zumbaban sus oidos y un frio de muerte helaba su corazon.\"},{\"heading\":false,\"text\":\"Este sueño se repitió siete veces consecutivas.\"},{\"heading\":false,\"text\":\"Entonces, lleno de un vago terror, Jask hizo que sus astrólogos consultasen las estrellas.\"},{\"heading\":false,\"text\":\"Y los astrólogos le dijeron:\"},{\"heading\":false,\"text\":\"--Señor, tú tienes una hija y dos hijos.\"},{\"heading\":false,\"text\":\"--Es verdad, dijo el rey.\"},{\"heading\":false,\"text\":\"En otro tiempo, por consejo de tus astrólogos, que habian consultado por tu mandato el libro infinito, alejaste de tí á tu hija y procuraste que de nadie fuese vista.\"},{\"heading\":false,\"text\":\"--Es verdad.\"},{\"heading\":false,\"text\":\"--Mas tarde separaste de tí á tus otros dos hijos; enviaste el uno al Oriente y el otro al Occidente, y procuraste que no conociese su origen.\"},{\"heading\":false,\"text\":\"--Es verdad.\"},{\"heading\":false,\"text\":\"--Pero el diablo los hará conocerse: es mas, los reunirá: tu hija será de uno de sus hermanos, y éste matará al otro. Además hay delante de tu horóscopo una nube roja.\"},{\"heading\":false,\"text\":\"--¿Y cuándo conocerá mi hijo á su hermana? ¿Cuándo el un hermano matará al otro?\"},{\"heading\":false,\"text\":\"--Dentro de muy pocas horas, dijeron los astrólogos, si hemos de creer á las estrellas.\"},{\"heading\":false,\"text\":\"--¡Dentro de muy pocas horas! esclamó aterrado Jask. ¿Y cómo impedir esas horribles desgracias? El castillo en que tengo encerrada á mi hija está al otro lado de los mares, en las tierras de Occidente: de aquí á allá hay centenares de leguas.\"},{\"heading\":false,\"text\":\"--Tú puedes hacer ese viaje en un instante, dijeron los astrólogos.\"},{\"heading\":false,\"text\":\"--¿Y cómo? un águila tardaria en llegar.\"},{\"heading\":false,\"text\":\"--Tú posées algo que vuela con mas rapidez que un águila.\"},{\"heading\":false,\"text\":\"--¡Yo!\"},{\"heading\":false,\"text\":\"--Sí, tú. Tienes en la grande aljama, sirviendo de alfombra....\"},{\"heading\":false,\"text\":\"--¡Ah! ¡sí, es verdad! la bandera de los jigantes que vencí con la ayuda de Dios.\"},{\"heading\":false,\"text\":\"--Pues bien; monta á caballo para llegar mas pronto á la grande aljama; toma esa bandera, ponte sobre ella, y ella te llevará á donde deseas; pero si cuando llegares vieres á tu hija convertida de blanca en negra, habrás llegado tarde; tu hija habrá sido la manceba de su hermano.\"},{\"heading\":false,\"text\":\"Bajó á las caballerizas, seguido del perro su hermano, puso un freno á su caballo de batalla, y sin entretenerse á encubertarle, ni aun á ensillarle, por no perder tiempo, montó en él en pelo y se dirijió á la carrera á la grande aljama; tomó la bandera, la estendió, y él, su hermano y su caballo se pusieron sobre ella.\"},{\"heading\":false,\"text\":\"Inmediatamente la bandera se levantó en los aires y condujo instantáneamente á Jask al castillo de las Alpujarras, á punto que salian por la poterna Zairah y Jacub asidos de las manos.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XLIX\",\"blocks\":[{\"heading\":false,\"text\":\"Jask se precipitó hácia ellos.\"},{\"heading\":false,\"text\":\"--¿A dónde vais, desdichados? esclamó.\"},{\"heading\":false,\"text\":\"--¿Quién eres tú? esclamó Jacub con fiereza.\"},{\"heading\":false,\"text\":\"--¡Yo!... ¿quién soy yo? esclamó Jask sin atreverse á contestar á aquella pregunta.\"},{\"heading\":false,\"text\":\"--¿Querrás tú impedir acaso que yo lleve conmigo á mi esposa?\"},{\"heading\":false,\"text\":\"--Zairah no puede ser tu esposa.\"},{\"heading\":false,\"text\":\"--Lo es ya, esclamó Jacub.\"},{\"heading\":false,\"text\":\"--¡Ah! sí, sí, era blanca y está convertida en negra, esclamó Jask cubriéndose el rostro con las manos.\"},{\"heading\":false,\"text\":\"--¿Qué quiere decir este hombre? esclamó Zairah, que se veia blanca como antes.\"},{\"heading\":false,\"text\":\"--¡Ese mancebo es tu hermano! esclamó con desesperacion Jask.\"},{\"heading\":false,\"text\":\"Al oir estas palabras Zairah, se vió negra, y exhaló un grito de horror.\"},{\"heading\":false,\"text\":\"Se desasió de la mano de Jacub, y pretendiendo huir de él, saltó en el caballo de batalla de su padre.\"},{\"heading\":false,\"text\":\"Al sentirla sobre sí el bruto, partió á correr.\"},{\"heading\":false,\"text\":\"--¡Ah! esclamó Jacub palideciendo de muerte y cerrando con su padre sin conocerle: tú me has robado á mi alma.\"},{\"heading\":false,\"text\":\"--¡Ah desdichado! esclamó Jask cayendo herido de muerte á los pies de Jacub: has sido impuro con tu hermana, y has teñido tus manos en la sangre de tu padre.\"},{\"heading\":false,\"text\":\"Y espiró.\"},{\"heading\":false,\"text\":\"Las últimas palabras de Jask-Al-bahul, retumbaron terribles en el corazon de Jacub.\"},{\"heading\":false,\"text\":\"Y sin embargo, saltó sobre el arzon de su caballo, y siguió á la carrera á Zairah que se alejaba.\"},{\"heading\":false,\"text\":\"Entonces fué cuando apareció Kaibar, y se puso en seguimiento de Zairah.\"},{\"heading\":false,\"text\":\"El perro-leon, rugió dolorosamente junto al cadáver de su hermano, y siguió á su sobrina, precediendo á Kaibar.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo L\",\"blocks\":[{\"heading\":false,\"text\":\"Durante todo el dia Kaibar siguió á Zairah.\"},{\"heading\":false,\"text\":\"El caballo de Jacub habia tomado otro camino y no parecia.\"},{\"heading\":false,\"text\":\"Al fin al trasponer el sol los horizontes, despues de haber corrido entre montañas y precipicios, desbocado su caballo, y con el terror en el alma, Zairah llegó á la sima, sobre la cual debia levantarse la torre de los siete suelos, y cayó desmayada á la aproximacion de Kaibar.\"},{\"heading\":false,\"text\":\"Jacub habia sobrevivido al fin, y un hermano, para que se cumpliese lo pronosticado por las estrellas, habia caido á las manos del otro durante el desmayo de Zairah.\"},{\"heading\":false,\"text\":\"Kaibar habia caido á lo profundo de la sima, el caballo de Jask-Al-bahul en que habia llegado Zairah, habia caido tambien despeñado en el abismo.\"},{\"heading\":false,\"text\":\"El perro habia lamido la sangre de Kaibar, Jacub habia lanzado á la sima su puñal ensangrentado.\"},{\"heading\":false,\"text\":\"Habia salido la luna.\"},{\"heading\":false,\"text\":\"Cuando Zairah volvió en sí, solo encontró á su lado á Jacub.\"},{\"heading\":false,\"text\":\"El perro-leon estaba sentado, amenazador y terrible en medio de los dos jóvenes.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo LI\",\"blocks\":[{\"heading\":false,\"text\":\"Zairah se pasó la mano por la frente, y apartó de sobre ella las pesadas bandas de sus cabellos.\"},{\"heading\":false,\"text\":\"Sus ojos miraban con espanto á Jacub.\"},{\"heading\":false,\"text\":\"--¡Con qué tú, esclamó; tú, el mancebo hermoso de mi amor, eres mi hermano!\"},{\"heading\":false,\"text\":\"--¡Tu hermano! miente aquel hombre que lo dijo, esclamó Jacub.\"},{\"heading\":false,\"text\":\"--¡Aquel hombre!... aquel hombre tenia algo que me espantaba, esclamó Zairah.\"},{\"heading\":false,\"text\":\"--Esto ha sido un sueño, un sueño que no debemos recordar, alma mía.\"},{\"heading\":false,\"text\":\"--¡Un sueño! no: yo era blanca como la nieve y ahora, mis brazos, mi senos están negros, negros como el carbon.\"},{\"heading\":false,\"text\":\"--¡Oh, no! ¡tú sueñas! esclamó estremeciéndose Jacub.\"},{\"heading\":false,\"text\":\"--Debemos de haber cometido un crímen horroroso, esclamó Zairah.\"},{\"heading\":false,\"text\":\"--El crímen de haber nacido destinados el uno para el otro.\"},{\"heading\":false,\"text\":\"--¿Quién sabe si nos ha unido el infierno?\"},{\"heading\":false,\"text\":\"--¡El infierno!\"},{\"heading\":false,\"text\":\"--¡He tenido un sueño! ¡una vision!\"},{\"heading\":false,\"text\":\"--¡Una vision!\"},{\"heading\":false,\"text\":\"--¡Sí! una vision horrorosa.\"},{\"heading\":false,\"text\":\"--La noche nos rodea, la luna brilla en los cielos, los aires son puros, todo nos convida á amar; ¿por qué hemos de hablar de cosas lúgubres?\"},{\"heading\":false,\"text\":\"Y Jacub adelantó hácia Zairah.\"},{\"heading\":false,\"text\":\"--No me toques: no me toques; esclamó la jóven retirándose.\"},{\"heading\":false,\"text\":\"--Tú no me amas, dijo sombriamente Jacub.\"},{\"heading\":false,\"text\":\"--¡Sí, sí! te amo, pero de otro modo.\"},{\"heading\":false,\"text\":\"--¡De otro modo!\"},{\"heading\":false,\"text\":\"--Sí, de una manera mas dulce, mas tranquila: te amo como amaría á mi hermano, y nada mas.\"},{\"heading\":false,\"text\":\"--¡Oh! cuando me viste la noche pasada junto á tí, no me hablabas de tal manera.\"},{\"heading\":false,\"text\":\"--Entonces era blanca, y ahora soy negra.\"},{\"heading\":false,\"text\":\"Jacub se estremeció.\"},{\"heading\":false,\"text\":\"--Pero yo te amo del mismo modo, con toda mi alma, dijo.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡no! ¡no! he soñado...\"},{\"heading\":false,\"text\":\"--¿Pero qué has soñado?\"},{\"heading\":false,\"text\":\"--Me parece que acabo de despertar del sueño, un sueño de sangre.\"},{\"heading\":false,\"text\":\"--¿De sangre?..\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--El terror de que estabas poseida....\"},{\"heading\":false,\"text\":\"--¿Dime que se ha hecho del buen caballero que nos dijo que éramos hermanos?\"},{\"heading\":false,\"text\":\"--Se fué, contestó con voz ronca Jacub.\"},{\"heading\":false,\"text\":\"--¡Se fué! ¿y aquel otro hombre horrible de la cabellera roja?\"},{\"heading\":false,\"text\":\"--¿El que te perseguia?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--Se fué tambien.\"},{\"heading\":false,\"text\":\"--Mira, yo los he visto en el sueño sombrío que acaba de pasar por mí.\"},{\"heading\":false,\"text\":\"--¿Que los has visto?\"},{\"heading\":false,\"text\":\"--Sí, ensangrentados y pálidos.\"},{\"heading\":false,\"text\":\"--No, no puede ser, esclamó Jacub, cuya turbacion crecia.\"},{\"heading\":false,\"text\":\"--Sí, sí, el caballero melancólico, grave, tenia abierto el pecho de una puñalada, y corria la sangre de la herida, y me miraba con dolor.\"},{\"heading\":false,\"text\":\"--¡Ah! no, no.\"},{\"heading\":false,\"text\":\"--Le he visto...\"},{\"heading\":false,\"text\":\"--Te lo repite tu terror.\"},{\"heading\":false,\"text\":\"--El otro, el de la cabellera bermeja, estaba despedazado, magullado, como un hombre que ha caido despeñado sobre rocas.\"},{\"heading\":false,\"text\":\"--¡Ah! no, no.\"},{\"heading\":false,\"text\":\"--Y el buen caballero me decia: tú eres mi hija.\"},{\"heading\":false,\"text\":\"--¡Te llamaba su hija!\"},{\"heading\":false,\"text\":\"--Y el hombre de la cabellera bermeja me decia: tú eres mi hermana.\"},{\"heading\":false,\"text\":\"--¡Su hermana! ¡no, no puede ser!\"},{\"heading\":false,\"text\":\"--Y el caballero añadia: mi hijo me ha asesinado: y el hombre bermejo decia: mi hermano me ha asesinado.\"},{\"heading\":false,\"text\":\"Jacub lanzó un gemido.\"},{\"heading\":false,\"text\":\"--Y alrededor de los que se decian mi padre y mi hermano, vagaban muchas sombras entre una atmósfera de fuego, y todas decian en coro:\"},{\"heading\":false,\"text\":\"--Nuestra raza se ha terminado, pero ha terminado maldita.\"},{\"heading\":false,\"text\":\"El terror de Jacub se aumentó, y adelantó hácia su hermana.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡no me toques! ¡no me toques! esclamó esta retirándose.\"},{\"heading\":false,\"text\":\"--Pero yo te amo.\"},{\"heading\":false,\"text\":\"--Nuestro amor es maldito.\"},{\"heading\":false,\"text\":\"--¿Y crees tú en sueños?\"},{\"heading\":false,\"text\":\"--Los sueños son avisos de Dios.\"},{\"heading\":false,\"text\":\"--O del infierno.\"},{\"heading\":false,\"text\":\"Y Jacub dió otro paso hácia Zairah.\"},{\"heading\":false,\"text\":\"--No me toques, esclamó esta; sino quieres morir y matarme.\"},{\"heading\":false,\"text\":\"--¡Cómo!\"},{\"heading\":false,\"text\":\"--No he acabado de decirte mi sueño: soñaba lo que está aconteciendo ahora mismo; en medio de los dos habia un perro horrible, tú pugnabas por acercarte á mí, el perro gruñia de una manera amenazadora y tú seguias acercándote como te acercas; al fin me asías una mano, y el perro, el perro nos arrastraba á los dos...\"},{\"heading\":false,\"text\":\"En aquel momento Jacub asió la mano de Zairah.\"},{\"heading\":false,\"text\":\"Un estremecimiento poderoso, un frio horrible, pasó por el cuerpo de los dos hermanos, y el perro lanzando roncos, desesperados ladridos, se lanzó en la sima.\"},{\"heading\":false,\"text\":\"Y como arrastrados, como atraidos por él, se precipitaron tambien en la sima los dos hermanos asidos de las manos.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo LII\",\"blocks\":[{\"heading\":false,\"text\":\"Y al caer los dos hermanos en la sima, un alarido atronador, un coro infernal de voces condenadas se levantó sobre ella.\"},{\"heading\":false,\"text\":\"«Nuestra raza maldita, se ha estinguido en la maldicion.\"},{\"heading\":false,\"text\":\"»La torre se levantará sobre la sima, y con la torre el castillo resplandeciente.\"},{\"heading\":false,\"text\":\"»Y pasarán para esto centenares de años.\"},{\"heading\":false,\"text\":\"»Y Jacub, el último hijo de la familia condenada, el incestuoso, el parricida, el fratricida, vagará insepulto alrededor de la torre, hasta que una sultana que haya sido parricida, adúltera é incestuosa, muera en el castillo.\"},{\"heading\":false,\"text\":\"»Y entonces nosotros descansaremos perdonados por nuestra espiacion en un infierno, y solo quedarán en el oscuro fondo de la torre la muger adúltera y parricida y su cómplice, y nuestro hermano el perro velando en la torre.\"},{\"heading\":false,\"text\":\"»Nuestra raza maldita se ha estinguido en la maldicion.\"},{\"heading\":false,\"text\":\"»La torre se levantará sobre la sima, y con la torre el castillo resplandeciente.»\"},{\"heading\":false,\"text\":\"Callaron las voces infernales, se apagó el eco que habian producido, y nada se escuchó cerca ó lejos de la sima: quedaron los alrededores desiertos y la luna alumbrando blandamente á la noche.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo LIII\",\"blocks\":[{\"heading\":false,\"text\":\"Poco tiempo despues de estos sucesos vinieron los árabes á España y la conquistaron.\"},{\"heading\":false,\"text\":\"Levantaron castillos en las montañas, y atalayas en las cumbres.\"},{\"heading\":false,\"text\":\"Sin embargo, la sima maldita permaneció abierta y sin que pasase junto á ella, hombre, animal, ni fiera, durante un espacio de mas de quinientos años.\"},{\"heading\":false,\"text\":\"Hasta que el rey Nazar construyó la Alhambra.\"},{\"heading\":false,\"text\":\"Entonces sobre la sima maldita, se levantó la torre de los Siete Suelos.\"},{\"heading\":false,\"text\":\"Y apenas se levantó la torre, cuando todas las noches salia de su fondo un espectro condenado, que vagaba por el alcázar, esperando á la sultana que habia de dar la señal con sus crímenes del descanso de la descendencia de Abraham y de Leila-Fatimah.\"},{\"heading\":false,\"text\":\"Pasaron sin embargo todavia mas de cien años.\"},{\"heading\":false,\"text\":\"Al fin, la sultana Ketirah, la esposa adúltera de Abul-Walid, murió en la torre de la Cautiva, y Jacub, que no era otro el mago que habia impulsado al rey Abul-Walid hácia los amores de María, pudo al fin decir á su familia:\"},{\"heading\":false,\"text\":\"--Descansad; vuestras penas están cumplidas, la sultana envenenadora, adúltera, incestuosa, ha muerto en el alcázar de la Alhambra; su complice va á bajar al infierno de la torre.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XLIV\",\"blocks\":[{\"heading\":false,\"text\":\"Y en efecto Masud-Almoharaví bajó al fondo de la torre, pero ginete en un caballo sin cabeza, y precedido de un perro lanudo.\"},{\"heading\":false,\"text\":\"¿Quién habia descabezado al caballo de Masud-Almoharaví?\"},{\"heading\":false,\"text\":\"Recordemos lo que ya hemos referido.\"},{\"heading\":false,\"text\":\"Cuando auxiliado por el infante Ebn-Ismail, Gonzalo se deslizaba con María, por la escala, fuera de la torre de la Cautiva, Masud-Almoharaví, se lanzó tras ellos, no sin recibir al lanzarse una puñalada del infante Ebn-Ismail.\"},{\"heading\":false,\"text\":\"Sin embargo, á pesar de lo mortal de la herida, al mismo tiempo que Gonzalo montaba en su caballo con María, desmayada aun, Masud montó en otro que tenia del diestro un esclavo, y partió á la carrera tras Gonzalo.\"},{\"heading\":false,\"text\":\"Delante del caballo que montaba Masud, corria ladrando el perro-leon, el lanudo perro hermano de Jask Al-bahul.\"},{\"heading\":false,\"text\":\"Cuando Gonzalo hubo salido del barranco notó que le seguian.\"},{\"heading\":false,\"text\":\"Al notarlo notó tambien que quien le seguia era un hombre solo.\"},{\"heading\":false,\"text\":\"Entonces revolvió su caballo, y acometió con la espada desnuda á Masud.\"},{\"heading\":false,\"text\":\"Masud sorprendido, sin tener tiempo de enristrar su lanza, encabritó para defenderse su caballo.\"},{\"heading\":false,\"text\":\"La espada de Gonzalo brilló como un relámpago, y la cabeza del caballo rodó por tierra.\"},{\"heading\":false,\"text\":\"Entonces aquel caballo sin cabeza, arrastró consigo á su ginete, siguiendo siempre al perro que ladraba, y perro, caballo y hombre, se encontraron en una magnífica cámara, sostenida por columnas y arcos calados en el fondo de la torre de los Siete Suelos.\"},{\"heading\":false,\"text\":\"Apenas se encontraron allí, el caballo quedó inmóvil en el centro de aquella magnífica cámara, el perro se echó á sus pies y se durmió, Masud-Almoharaví, el hombre condenado, se apoyó en su lanza, inclinó la cabeza y se durmió tambien.\"},{\"heading\":false,\"text\":\"Gonzalo y María entretanto, adelantaban hácia la frontera cristiana.\"},{\"heading\":false,\"text\":\"Llegaron al cabo á ella.\"},{\"heading\":false,\"text\":\"Algun tiempo despues eran esposos.\"},{\"heading\":false,\"text\":\"Y el espíritu de Masud-Almoharaví vió aquellas alegres bodas, y los celos fueron su tormento.\"},{\"heading\":false,\"text\":\"Y aguijado por su dolor, todas las noches á la media noche, sale de la torre en el caballo sin cabeza, precedido del perro, recorre los bosques de la Alhambra con la lanza en ristre, y vuelve al instante al fondo de la torre, de donde sale, y cae en un letargo de penas, soñando siempre en la felicidad de María.\"},{\"heading\":false,\"text\":\"Esta es la tradicion del _Belludo_ y del _Descabezado_ de la torre de los Siete Suelos.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"APUNTES HISTÓRICOS\"},{\"heading\":false,\"text\":\"en que se da una breve noticia de los reyes de Granada que existieron despues del rey Abul-Walid, y antes del rey Abu-Abdalah-al-Zaquies-el-Zogoibi, último señor moro de Granada.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo I\",\"blocks\":[{\"heading\":false,\"text\":\"El rey Abul-Walid, dejó cuatro hijos: Muhamad, su sucesor de doce años; Farag, el segundo; Abul-Hegiag, el tercero, é Ismail, el cuarto.\"},{\"heading\":false,\"text\":\"El mayor de estos cuatro hijos, fué proclamado bajo el nombre de Abu-Abdallah-Muhamad IV, el mismo dia en que murió su padre.\"},{\"heading\":false,\"text\":\"En razon á la corta edad del rey, el wazir Almabrub tomó sobre sí el gobierno del reino.\"},{\"heading\":false,\"text\":\"Muy pronto la altivez y avaricia de este wazir, provocaron el disgusto y las demostraciones del esclavizado pueblo, y tres años despues de su exaltacion al trono, el rey Muhamad, que solo tenia quince años, le mandó cortar la cabeza á la vuelta de una empresa sobre la frontera de Castilla, y tomó las riendas del gobierno.\"},{\"heading\":false,\"text\":\"En sus primeras espediciones, conquistó á Baeza y á Gibraltar.\"},{\"heading\":false,\"text\":\"Poco despues perdió á Gibraltar de nuevo, contra el emir de Fez Abul Hassau.\"},{\"heading\":false,\"text\":\"Pero en vez de disputarle Muhamad esta conquista, prefirió aliarse con él, y tan de buena fé lo hizo, que cuando los cristianos bajo las banderas de Alonso el XI de Castilla, fueron á cercar aquella plaza, acudió á socorrer al emir de Fez para que no se la arrebatasen.\"},{\"heading\":false,\"text\":\"Hizo levantar el sitio, y cuando penetró en la plaza, hizo conocer á los xaques y capitanes africanos con injuriosas pullas, el servicio que les habian prestado, y ofendidos estos le asesinaron, cuando se embarcaba para ir á visitar al emir de Fez su aliado.\"},{\"heading\":false,\"text\":\"Muhamad murió en la primavera de su juventud, aun no cumplidos los veinte años.\"},{\"heading\":false,\"text\":\"Inmediatamente los wazires y la nobleza proclamaron rey al hermano del difunto, Abul-Hegiag, y este mandó recoger el cuerpo de su hermano y le llevaron á Málaga, donde fué enterrado en una huerta del rey fuera de la ciudad.\"},{\"heading\":false,\"text\":\"Sobre su sepulcro se escribió el epitafio siguiente:\"},{\"heading\":false,\"text\":\"«Este es el sepulcro del noble rey, fuerte, magnánimo, liberal, esclarecido, Abu-Abdallah-Muhamad, de feliz memoria, de la real prosápia, prudente, virtuoso, ínclito guerrero, vencedor, caudillo de vencedoras huestes, de la antigua é ínclita familia de los Nazares, príncipe de los fieles, hijo del sultan Abul-Walid-ebn-Ferag-ebn-Nazar, á quien Dios haya perdonado y tenga en descanso. Nació (el Señor se complazca de él), dia ocho de Muharram del año de setecientos veinte y cinco, y murió (Dios le perdone), á trece de Dilhagia del año de setecientos treinta y tres. Loor y gloria á Dios Altísimo é Inmortal.»\"}]},{\"title\":\"La torre de los siete suelos. — capítulo II\",\"blocks\":[{\"heading\":false,\"text\":\"El nuevo rey Juzef-Abul-Hegiag, entabló inmediatamente negociaciones, por las que obtuvo una tregua de cuatro años entre Alonso XI de Castilla, el emir de Fez Abul-Hassau y él. Ocupóse durante esta paz transitoria en la administracion de sus reinos. Dió muchos decretos para precisar la acepcion de las leyes oscurecidas por las sutilezas de los imanes y de los katibs; estableció fórmulas sencillísimas para los actos públicos y particulares, creó distinciones honoríficas para recompensar los servicios á imitacion de sus vecinos cristianos, concluyó la Alhambra y erigió otros muchos monumentos de que él fué el único arquitecto.\"},{\"heading\":false,\"text\":\"Apenas terminada la tregua, el emir de Fez envió á su hijo á hacer escursiones en la Andalucía cristiana. Este jóven príncipe, murió en esta espedicion. Su padre Abul-Hassau juró vengar su muerte sujetando de nuevo a los matadores al antiguo dominio de los Almoravides, y publicó el _alqihed_ ó guerra santa, reuniendo sobre Ceuta las fuerzas de su imperio, y atravesando el estrecho con doscientas naves, en las que se trasladaban á España cuatrocientos mil infantes y sesenta mil caballos. El rey de Granada fué á unirse con él á Gezira Alhadra (Isla-verde), y los dos ejércitos combinados marcharon sobre Tarifa y la cercaron.\"},{\"heading\":false,\"text\":\"Los reyes cristianos se estremecieron de espanto ante este nuevo esfuerzo del Africa, y Alonso XI escitó á los reyes de Portugal y de Aragon para que su uniesen con él á fin de contrarestar al enemigo comun.\"},{\"heading\":false,\"text\":\"La batalla del Salado decidió la suerte de aquella empresa.\"},{\"heading\":false,\"text\":\"Los moros fueron vencidos.\"},{\"heading\":false,\"text\":\"El harem del emir de Fez, su hermana, su hijo y sus tesoros cayeron en poder de los cristianos.\"},{\"heading\":false,\"text\":\"Encerrado el rey de Granada en la Isla verde, se vió obligado para volver á Granada á embarcarse secretamente, yendo á desembarcar en Almuñecar.\"},{\"heading\":false,\"text\":\"Sucesivamente, Alonso de Castilla se apoderó de Tarifa, de la Isla verde y de Algeciras.\"},{\"heading\":false,\"text\":\"Juzef era decididamente desgraciado en la guerra.\"},{\"heading\":false,\"text\":\"Habia nacido para la paz, para la ciencia, para las artes.\"},{\"heading\":false,\"text\":\"Fué el Augusto de Granada.\"},{\"heading\":false,\"text\":\"Instituyó numerosas escuelas, y determinó para todas las del reino una enseñanza igual; embelleció con mezquitas, algibes, cisternas, hospitales y palacios la ciudad de Granada, y formó ó renovó sobre muchos objetos reglamentos que llevaron su nombre y que fueron, mientras subsistió el reino, sus leyes.\"},{\"heading\":false,\"text\":\"Al fin, en 1354, un loco asesinó á este gran rey mientras estaba orando en la mezquita.\"},{\"heading\":false,\"text\":\"Hé aquí el epitafio de su sepulcro:\"},{\"heading\":false,\"text\":\"«Aquí yace el rey mártir y de alto linage, gentil docto, virtuoso, cuya clemencia y bondad y demás escelentes virtudes, publica el reino de Granada, y hará época en la historia de la felicidad de su tiempo: soberano príncipe, ínclito caudillo, espada cortante del pueblo muzlime, esforzado alférez entre los mas valientes reyes, que por la gracia de Dios aventajó á todos en el gobierno de la paz y de la guerra, que defendió con su prudencia y valor al Estado, y que consiguió sus deseados fines con la ayuda de Dios, el príncipe de los fieles, Juzef-Abul-Hegiag, hijo del gran rey Abul-Walid, y nieto del escelente rey Abu-Walid-Ferag-ebn-Ismail, de la familia Nazarí, de los cuales el uno fué leon de Dios, invencible domador de sus enemigos y sojuzgador de los pueblos, mantenedor de los pueblos en justicia con leyes, y defensor de la religion con espada y lanza, y digno de la memoria eterna de los hombres: el otro á quien Dios haya recibido en su misericordia entre los bienaventurados; pues fué columna y decoro de su familia, y gobernó con loable felicidad y paz el reino, mirando por la pública y privada prosperidad, que en todas las cosas hacia notar su prudencia, justicia y benevolencia, hasta que Dios Todopoderoso, colmado ya de méritos, le llevó del mundo, coronándole antes con la corona del martirio, pues habiendo cumplido la obligacion del ayuno, cuando humildemente oraba postrado en la mezquita pidiendo á Dios perdon de sus debilidades y deslices, la violenta mano de un impío, permitiéndolo así Dios justísimo, para pena de aquel malvado, le quitó la vida, cuando mas cercano estaba de la gracia del Todopoderoso: lo que acaeció el dia primero de Jawal, año de setecientos cincuenta y cinco. ¡Ojalá esta muerte, que hizo ilustre el lugar y la ocasion le haya sido de galardon, y haya sido recibido en las moradas deliciosas del paraiso, entre sus felices mayores y antepasados! Principió á reinar miércoles catorce de Dilhagia, año setecientos treinta y tres. Habia nacido dia veinte y ocho de Rabie postrera, año setecientos diez y ocho; alabado sea Dios Unico y Eterno que da la muerte á los hombres y galardona con la bienaventuranza.»\"}]},{\"title\":\"La torre de los siete suelos. — capítulo III\",\"blocks\":[{\"heading\":false,\"text\":\"Al grande, al sabio, al justo rey Abul-Hegiag, sucedió su hijo Muhamad V, tenia veinte años de edad, era hermoso, de carácter firme, y de trato apacible, siendo además muy humano, generoso y franco. Dicen las crónicas árabes que era tan compasivo, «que muchas veces sus lágrimas manifestaban cuanto sentia su corazon las aflicciones y calamidades que le referian, y asimismo tan benéfico y liberal, que ganaba el amor de cuantos tenian la fortuna de tratarle; negó la entrada de su alcázar á los aduladores y ministros de lujo inútil y de vana ostentacion, y estableció en su casa un arreglado número de sirvientes, y cuanto convenia á la decente magnificencia de la casa del rey, de un estado ni opulento y vicioso, ni pobre ó malandante. Con estas virtudes solo era aborrecido de los malos y viciosos cortesanos; pero los principales y gente noble del reino le estimaban, y todo el pueblo le miraba con respeto, amor y confianza: sus principales entretenimientos y diversiones eran los libros y los ejercicios de caballería, torneos y gentilezas á caballo.\"},{\"heading\":false,\"text\":\"»Puso las avenencias con el rey de Castilla y con Abu-Salem de Fez, y gozaba el reino de bonancible calma. Luego que subió al trono cedió á su hermano Ismail, y á sus hermanos y madrastra el alcázar vecino al principal palacio de su padre, donde él moraba, casa magnífica y llena de comodidades, para que la habitasen con toda su familia. La sultana madre del infante Ismail habia sacado inmensas riquezas el dia de la muerte del rey Juzef, y desde luego trató de destinarlas en facilitar el camino del trono á su hijo Ismail: ganó á su hija que habia casado su padre con uno de los príncipes de la sangre, llamado Abu-Abdallah, que amaba perdidamente á su esposa, y por sus persuasiones entró en las intenciones de la reina, madre de Ismail y de su muger y por este príncipe y derramando riquezas, formaron un numeroso ejército de conjurados.»\"},{\"heading\":false,\"text\":\"Esta conjuracion empezó á dar resultados.\"},{\"heading\":false,\"text\":\"Poco tiempo despues de la exaltacion de Muhamad al trono, se reveló alzándose con título de rey en Gibraltar el walí de aquella fortaleza Iza-ebn-Alasun-ebn-Alí-Mandil-Alascarí, y trató cruelmente á los que habian permanecido fieles al rey. Pero las mismas crueldades de este walí, hicieron que se volvieran contra él todos los habitantes de Gibraltar, que le prendieron, enviándole á Ceuta con su hijo, donde murieron ambos entre los mas crueles tormentos á manos del reyezuelo de Africa, señor de Ceuta Abu-Anan.\"},{\"heading\":false,\"text\":\"Apesar de este mal éxito, las rebeldías continuaban sostenidas por la sultana madrastra del rey Muhamad, por su hermana y por su cuñado Abu-Abdallah.\"},{\"heading\":false,\"text\":\"Creyéronse al fin en estado de dar el golpe, y habiendo escogido ciento de los mas osados y valientes de sus parciales, escalaron de noche silenciosamente la parte mas alta de la Alhambra y se ocultaron hasta la media noche al canto del gallo del dia veinte y ocho de Ramazan del año setecientos setenta.\"},{\"heading\":false,\"text\":\"Dada la señal, los conjurados acometieron dando grandes voces, atropellando y matando á cuantos encontraban; al mismo tiempo otros conjurados rompieron las puertas de la casa del wazir y le mataron y á su hijo y á muchos de la familia: el príncipe Abu-Abdallah, cuñado del rey, entró en la Alhambra proclamando á su otro cuñado el infante Ismail, creyendo muerto al rey Muhamad; pero los encargados de matarle, se habian entretenido en el saqueo, y dieron tiempo para huir al rey Muhamad, á quien una de las doncellas del harem disfrazó de esclava, huyendo con él á caballo, sin parar hasta la ciudad de Guadix, donde libre el rey del peligro, fué recibido con entusiasmo por los leales habitantes.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo V\",\"blocks\":[{\"heading\":false,\"text\":\"El infante Ismail fué proclamado rey.\"},{\"heading\":false,\"text\":\"Paseole á caballo por la ciudad su cuñado y favorecedor Abu-Abdallah entre sus parciales, y sin perder tiempo escribió al rey de Castilla para que le favoreciese y le tuviese por su vasallo, lo que consiguió fácilmente.\"},{\"heading\":false,\"text\":\"Entretanto el destronado rey Muhamad, aunque confiaba en la lealtad de los de Guadix, envió mensageros al emir de Fez participándole lo que le acontecia y pidiéndole ayuda.\"},{\"heading\":false,\"text\":\"Pidiósela de igual modo al rey de Castilla.\"},{\"heading\":false,\"text\":\"Pero viendo que ninguno de los dos le socorria, partió de Guadix acompañado de gran número de caballeros, se embarcó en Marsella y se trasladó á Fez, donde el emir Abu-Salen le recibió con grande aprecio, honores y distinciones, obsequiándole con nunca visto aparato y magnificencia, prometiéndole su ayuda, y con tanta presteza y generosidad, que mandó levantar dos ejércitos que fuesen con él, y con los cuales se embarcó para dar la vuelta á Andalucía Muhamad, y cuando estuvo en España, escribió al rey de Castilla (Don Pedro el Cruel) participándole el estado de sus asuntos y las razones que le habian obligado á buscar auxilio en Africa.\"},{\"heading\":false,\"text\":\"Tembló España á la presencia de la inmensa morisma que habia desembarcado con Muhamad, y sobre todo, el usurpador Ismail, que se apresuró á salir contra aquella hueste á probar la fortuna de una batalla.\"},{\"heading\":false,\"text\":\"Pero Muhamad era desgraciado.\"},{\"heading\":false,\"text\":\"En estos momentos supremos, cuando las armas iban á decidir su fortuna, murió el emir de Fez Abu-Salen, que habia sido asesinado en Africa.\"},{\"heading\":false,\"text\":\"A esta noticia los caudillos de los berberiscos que ayudaban á Muhamad se volvieron á Africa dejando solo á Muhamad, que se refugió en Ronda, que se le mantenia fiel.\"},{\"heading\":false,\"text\":\"Desde allí volvió á pedir socorro al nuevo emir de Fez.\"},{\"heading\":false,\"text\":\"Entretanto, el usurpador Ismail-Ebn-Juzef ocupaba el trono de la Alhambra.\"},{\"heading\":false,\"text\":\"Era de buena estatura, y tan bello, que parecia una muger hermosa, pero tenia tambien el ánimo afeminado, débil, y dado á los deleites y al amor de las mugeres.\"},{\"heading\":false,\"text\":\"Su cuñado Abu-Albdallah-Abu-Sayd, que le habia ayudado á subir al trono, le trataba con desprecio, y muy pronto su ambicion no se satisfizo con mandar á nombre del débil rey, sino que quiso su corona.\"},{\"heading\":false,\"text\":\"Otra nueva conspiracion ensangrentó la Alhambra.\"},{\"heading\":false,\"text\":\"Abu-Sayd y sus parciales se apoderaron del alcázar, y el usurpador Ismail se vió obligado á huir al palacio del Albaicin, donde fué cercado y preso, y conducido á la Alhambra á la presencia de Abu-Sayd.\"},{\"heading\":false,\"text\":\"Este le trató con desprecio, le despojó de sus magníficas vestiduras y le envió á una prision.\"},{\"heading\":false,\"text\":\"En el camino, los soldados que le conducian, le mataron de órden de Abu-Sayd, y le cortaron la cabeza, que fué paseada en público.\"},{\"heading\":false,\"text\":\"De la misma manera cortaron la cabeza á su hermano menor el infante Caís.\"},{\"heading\":false,\"text\":\"Nadie se atrevió á recoger los cuerpos despedazados de los dos infelices infantes, que se pudrieron al aire, colmando el horror de aquella traicion miserable.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo V\",\"blocks\":[{\"heading\":false,\"text\":\"Abu-Sayd fué proclamado.\"},{\"heading\":false,\"text\":\"Entre tanto el depuesto rey Muhamad insistia pidiendo socorros para recobrar el trono al emir de Fez y al rey de Castilla.\"},{\"heading\":false,\"text\":\"Al fin el rey don Pedro, disgustado con la conducta del usurpador Abu-Sayd, envió á Muhamad un numeroso ejército de castellanos con mil y quinientos carros cargados de máquinas de guerra.\"},{\"heading\":false,\"text\":\"Poco despues el rey de Castilla se puso en persona al frente de este ejército y se encaminó con él á Ronda; al llegar don Pedro á Hins Casjara salióle al encuentro el rey Muhamad con su ejército, y se unió á él. Abu-Sayd, para resistir el empuje de esta alianza, se alió con el rey de Aragon, aquel enemigo del rey don Pedro de Castilla, primo suyo, Pedro tambien, llamado _El Ceremonioso_, y conocido entre los catalanes por el del _punjalet_.\"},{\"heading\":false,\"text\":\"Entre tanto los dos ejércitos, el de Castilla y el de Muhamad, unidos como si fuesen uno solo, continuaron sus marchas y entraron en Hins-Atara y la ocuparon, y los castillos y pueblos de la comarca que se iban entregando al rey Muhamad.\"},{\"heading\":false,\"text\":\"Los sucesos de la guerra iban prósperos: el reino de Granada se abria al legítimo rey; pero viendo este las tropelías que cometia en los lugares donde entraba la soldadesca castellana, «no lo pudo sufrir, dicen las crónicas árabes, su paternal corazon, y rogó al rey de Castilla encarecidamente que se quisiese tornar con sus gentes, porque no podia ver sin dolor las calamidades que causaba la guerra en sus pobres pueblos, y que por toda la riqueza y poderío del mundo no queria hacer á sus muzlimes tanto mal y daño.»\"},{\"heading\":false,\"text\":\"Don Pedro aprobó la determinacion del rey Muhamad, y ofreciéndole sinceramente venir en su ayuda siempre que le necesitase, volvió á Castilla dejando al buen Muhamad, que quiso mas bien continuar arrojado sin razon del trono, que envolver á sus vasallos en los horrores de la guerra civil.\"},{\"heading\":false,\"text\":\"Retiróse, pues á Ronda, donde resignado á su suerte vivió feliz, haciendo felices á sus vasallos con su gobierno paternal.\"},{\"heading\":false,\"text\":\"Muhamad se hacia amar por su templanza, al mismo tiempo que Abu-Sayd se hacia aborrecible por sus tiranías, á pesar de algunas ventajas que habia obtenido sobre los cristianos.\"},{\"heading\":false,\"text\":\"En una algara en que los walíes de Abu-Sayd, habian desbaratado á los fronteros de Andalucía, quedaron prisioneros muchos nobles de Castilla, y entre ellos al maestre de Calatrava don Diego Garcia de Padilla, hermano de la esposa del rey don Pedro[96], y los llevaron á Granada en triunfo.\"},{\"heading\":false,\"text\":\"El rey Abu-Sayd, pensando captarse la voluntad del rey don Pedro, honró y festejó al maestre y á los nobles castellanos que con él habian sido prisioneros, les dió ricos dones, y los puso con el maestre en libertad, suplicándoles interpusiesen su favor para que el rey de Castilla les ayudase, y así se lo prometieron.\"},{\"heading\":false,\"text\":\"En este tiempo los de Málaga, cansados de la tiranía de Abu-Sayd, proclamaron á Muhamad, y esta noticia que Abu-Sayd no esperaba, le sorprendió y le llenó de cuidado, haciéndole desconfiar de la suerte que hasta entonces le habia sido próspera.\"},{\"heading\":false,\"text\":\"Aumentaban sus recelos las contínuas deslealtades de sus mas privados y favorecidos que le abandonaban, y se pasaban á Muhamad, á quien empezaba á mostrarse próspera la fortuna, y al mismo tiempo le apuraba la falta de sus rentas administradas por manos poco fieles.\"},{\"heading\":false,\"text\":\"Apurado, pues, por todas partes, tomó una resolucion peligrosísima.\"},{\"heading\":false,\"text\":\"Creyó que le convenia pasar á Castilla y ponerse á la merced del rey don Pedro.\"},{\"heading\":false,\"text\":\"Partió, pues, de Granada el mal aconsejado Abu-Sayd con pompa y aparato y gran comitiva de caballeros, y con ricas joyas de su tesoro, así en pedrería de esmeraldas y balajes, como en aljófar y tejidos de oro y seda y ricos paños, y gran cantidad de doblas de oro, y caballos y jaeces y armas finas y bien labradas, creyendo que con esto, el rey de Castilla, que era codicioso, se pondria de su parte.\"},{\"heading\":false,\"text\":\"Llegó al fin á Sevilla, donde fué muy bien recibido por el rey don Pedro.\"},{\"heading\":false,\"text\":\"Pero aconsejado este por sus privados, acordó que Abu-Sayd debia morir, como usurpador del reino de Granada, enemigo del rey Muhamad, aliado del rey de Castilla, y por el mal que le habia hecho al rey, aliándose con el rey de Aragon su enemigo.\"},{\"heading\":false,\"text\":\"Determinado esto, quebrantando el rey de Castilla el seguro que habia dado á Abu-Sayd, le prendió con los caballeros, le sacó al campo de Tablado, vestido de encarnado, y allí, atado Abu-Sayd á una estaca, el rey de Castilla le mató de una lanzada por su propia mano.\"},{\"heading\":false,\"text\":\"Dicen que Abu-Sayd al morir esclamó:\"},{\"heading\":false,\"text\":\"--¡Oh Pedro! ¡qué torpe triunfo alcanzas hoy de mí! ¡qué ruin cabalgada hiciste contra quien de tí se fiaba!\"},{\"heading\":false,\"text\":\"Los cadáveres fueron amontonados, y sus cabezas cortadas fueron puestas en los muros de Sevilla.\"},{\"heading\":false,\"text\":\"Tal fué el fin desastroso del desgraciado Abu-Sayd, que dejó franco el trono al legítimo rey Muhamad.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo VI\",\"blocks\":[{\"heading\":false,\"text\":\"Trasladóse este á Granada, donde fué recibido con grandes aclamaciones y regocijos.\"},{\"heading\":false,\"text\":\"Fué su entrada á la hora de adohar[97], del sábado veinte de la luna de Giumada postrera del año setecientos sesenta y tres[98].\"},{\"heading\":false,\"text\":\"El rey de Castilla le envió la cabeza de Abu-Sayd, canforada dentro de una caja, cuyo horrible presente agradeció mucho el rey Muhamad, que envió en cambio á don Pedro el Cruel, veinte y cinco caballos de raza árabe de la yeguada real, criados á las orillas del Genil, diez de ellos con preciosos jaeces y ricos alfanges guarnecidos de oro y piedras preciosas.\"},{\"heading\":false,\"text\":\"Al mensajero que habia llevado la cabeza de Abu-Sayd, dió tambien magníficos regalos.\"},{\"heading\":false,\"text\":\"Poco tiempo despues suscitaron al rey Muhamad una rebelion algunos descontentos que proclamaron al walí Alí-ebn-Alí Ahmed-ebn-Nazar, infante de la familia real; pero el rey Muhamad le venció, le ahuyentó, y continuó su reinado en paz.\"},{\"heading\":false,\"text\":\"Muhamad, en muestra de agradecimiento al rey de Castilla por el favor que le debia, por haber dado muerte á su enemigo, dió la libertad sin rescate á todos los cautivos cristianos que habia en Granada, y firmó con el rey don Pedro un pacto de perpétua paz y alianza.\"},{\"heading\":false,\"text\":\"Como Castilla andaba revuelta de bandos civiles, no tuvo con ella guerras el rey de Granada. Pero don Pedro le pidió auxilio contra su enemigo el rey de Aragon y contra su hermano bastardo don Enrique de Trastamara, que intentaba destronarle.\"},{\"heading\":false,\"text\":\"Empezaban los castellanos á mostrarse contrarios á don Pedro por sus crueldades y tiranías, y para socorrerle, Muhamad escogió entre los mas valientes de su reino seiscientos caballeros, y se los envió acaudillados por el arraez Farag Reduan; y aunque estos seiscientos sirvieron á don Pedro con admirable valor, como pidiese nuevos auxilios, Muhamad le envió siete mil caballos escogidos y doble número de infantería que fueron á sitiar á Córdoba, á la que pusieron á punto de rendirse.\"},{\"heading\":false,\"text\":\"Pero la fortuna habia vuelto definitivamente la espalda al terrible rey don Pedro, y antes de que Muhamad pudiese llegar en su socorro con un nuevo ejército, murió á manos de su hermano bastardo don Enrique en el castillo de Montiel.\"},{\"heading\":false,\"text\":\"Don Enrique fué proclamado rey de Castilla.\"},{\"heading\":false,\"text\":\"Por no perder las ventajas que sobre el castellano le daban sus guerras civiles, el rey Muhamad, á pretesto de la amistad que habia tenido con el rey don Pedro, declaró la guerra á Enrique II, aunque este le habia ofrecido su amistad, y entró en cabalgada por la frontera y recorrió libremente la tierra robando y cautivando cuanto encontraba de muros afuera de las poblaciones, sin poner sitio formal á ninguna ciudad ni fortaleza.\"},{\"heading\":false,\"text\":\"Al año siguiente (1570), cayó con todo su ejército sobre la Isla verde y la tomó, y preveyendo que no podria sostener su conquista, la arruinó y desmanteló sus muros y fortalezas.\"},{\"heading\":false,\"text\":\"Temeroso de la pujanza de Muhamad, don Enrique le envió cartas de paz con el maestre de Calatrava, ofreciéndole su amistad para atender mas libremente á las guerras que le ocupaban, paz que Muhamad aceptó con alegria, porque le dejaba libre para atender al reparo y gobierno de su reino que mucho lo necesitaba.\"},{\"heading\":false,\"text\":\"Durante esta paz, el rey Muhamad mandó edificar la casa de Azaque para recoger pobres y curar sus enfermedades. Esta obra empezó en el año de seiscientos setenta y siete, y concluyó en seiscientos setenta y ocho[99]; edificio magnífico, con todas las comodidades imaginables, con fuentes y espaciosos estanques de pulidos mármoles, para comodidad y aseo de los enfermos[100].\"},{\"heading\":false,\"text\":\"Hermoseó tambien con muchos edificios públicos la ciudad de Guadix, donde solia pasar largas temporadas; y, en fin, durante la larga paz que sostuvo con todos los reyes vecinos, tanto de España como de Africa, fomentó en su reino, las artes, las manufacturas, el comercio y la agricultura, hasta tal punto que iban á Granada mercaderes de Siria, de Egipto, de Africa, de Italia; Almería era la escala célebre de España para los buques de todo el mundo, y se veian mezclados en las calles de Granada numerosas gentes de diversas patrias y religiones.\"},{\"heading\":false,\"text\":\"En este tiempo declaró é hizo jurar su sucesor y partícipe en el mando á su hijo Abu-Abdallah-Juzef, y concertó su matrimonio con la hija del emir de Fez, á la que trajo á Granada su hermano el príncipe de Fez, que casó con la hermosa Zairah, hija de Abu-Ayan, caballero rico y de los mas nobles y poderosos de Andalucía.\"},{\"heading\":false,\"text\":\"Con este motivo se celebraron justas y torneos y bizarras fiestas y gentilezas de caballería, en las que entraron caballeros de Africa, de Egipto, de España y de Francia, atraidos por la magnificencia y la fama de Granada, y protegidos por el seguro real de Muhamad, que los honró y hospedó magníficamente á su costa en el _fondaf_ de los genoveses.\"},{\"heading\":false,\"text\":\"Muhamad continuó prolongando sus paces con el rey de Castilla, y enviándole regalos y preseas, «y como poco despues, dicen las crónicas que seguimos, acaeciese la muerte del rey de Castilla, hubo mal intencionados que atribuian su muerte á maldad del rey de Granada, como que le hubiese enviado unos borceguíes preciosos inficionados de veneno mortal, pero nunca fué traidor ni asesino el rey Muhamad, y la muerte fué natural, y porque sus dias fueron cumplidos segun la divina voluntad.»\"},{\"heading\":false,\"text\":\"Algunos años despues, el setecientos noventa y cuatro[101], murió el rey Muhamad con general sentimiento de sus vasallos, y fué sepultado en el palacio de Djene-al-Arife (Generalife) al amanecer, poco despues de la oracion del alba (de Azzobih), siendo acompañado su entierro por todas las clases del Estado.\"},{\"heading\":false,\"text\":\"No consta la inscripcion del sepulcro de este rey.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo VII\",\"blocks\":[{\"heading\":false,\"text\":\"Sucedióle en el trono su hijo Abu-Abdallah Juzef II, que fué proclamado solemnemente, besándole la mano toda la nobleza de Granada y los principales alcaides y walíes de todas las tahas del reino.\"},{\"heading\":false,\"text\":\"Era muy semejante en las virtudes á su padre, y en su amor á la paz. Despues de las fiestas de su proclamacion, envió mensajeros á los reyes cristianos, ofreciéndoles mantener las treguas y amistad que con ellos habia tenido su padre.\"},{\"heading\":false,\"text\":\"Para obligar mas al rey de Castilla (don Juan el primero) dió libertad sin rescate á algunos cautivos que habian tomado sus corredores en la frontera, y los envió con el alcaide de Málaga, acompañándolos con un presente de seis caballos andaluces ricamente enjaezados, con armas preciosas y cubiertos de paños de oro.\"},{\"heading\":false,\"text\":\"Las treguas continuaron, y con ellas la prosperidad de Granada.\"},{\"heading\":false,\"text\":\"Pero habia llegado el momento en que las amarguras turbasen la felicidad del rey Juzef.\"},{\"heading\":false,\"text\":\"Tenia este cuatro hijos. El mayor se llamaba como él Juzef, el segundo Muhamad, Alí el tercero, y Ahmed el cuarto. Muhamad era de carácter violento, y ofendido de que su padre, por razones de primogenitura y afecto prefiriese á su hermano mayor Juzef, sucesor presunto del trono, concibió contra él un odio implacable, y olvidando todo respeto, concibió el proyecto de levantarse contra su padre y destronarle si la fortuna le ayudaba.\"},{\"heading\":false,\"text\":\"Tomó para ello por pretesto su celo por la religion.\"},{\"heading\":false,\"text\":\"Mirábase mal por el pueblo de Granada, enemigo de los cristianos y belicoso de suyo, la buena avenencia que Muhamad sostenia con los otros reyes de España, y que favoreciese en su córte á muchos caballeros castellanos refugiados en ella, hasta el punto de tratarlos con suma familiaridad: fué muy facil, pues, á Muhamad, hacer creer al pueblo por medio de sus parciales, que su padre era mal musulman, cristiano secretamente, y favorecedor público de infieles.\"},{\"heading\":false,\"text\":\"Tomó cuerpo esta calumnia, se desenfrenaron los descontentos del rey Juzef, y llegó el caso de que, irritados los mas audaces por los partidarios del infante Muhamad, produjeron un motin en que se pidió á voces la deposicion del rey: principió el alboroto en las puertas de la Alhambra; y aterrado el rey Juzef, estaba á punto de renunciar su soberanía y de ponerse en manos de su rebelde hijo, cuando el embajador de Fez, que estaba con él en el alcázar, hombre anciano y bravo, y de mucha autoridad y elocuencia, salió á caballo á la plaza y habló á los rebelados con tal energía, que los redujo á la obediencia del rey Juzef.\"},{\"heading\":false,\"text\":\"Aunque habia pasado esta tormenta, temeroso el rey de que, creyéndole amigo de los cristianos, se reprodujese con mas fuerza, dispuso sus tropas para una algazia ó correría á saco mano por las fronteras cristianas, y entró por las de Murcia y Lorca, talando los campos, robando ganados, incendiando aldeas, y matando y cautivando á cuantos cristianos habian á las manos.\"},{\"heading\":false,\"text\":\"Salieron contra ellos los fronteros, y despues de algunas escaramuzas con varia fortuna, el rey Juzef se volvió con la presa á Granada.\"},{\"heading\":false,\"text\":\"Pero como Juzef hacia la guerra á los cristianos, mas por satisfacer á sus vasallos y destruir sus sospechas de amistad con los cristianos, que por su voluntad, admitió fácilmente la tregua que le propuso el rey de Castilla, y aun se cree que él mismo la pidió, receloso de los grandes armamentos que contra él se hacian en Castilla y Aragon; tregua, que para evitar interpretaciones, concertó con acuerdo de un consejo compuesto de sus wazires y de sus walíes.\"},{\"heading\":false,\"text\":\"Sucedió por este tiempo que un ermitaño llamado Juan Sago, dijo al maestro de Alcántara don Martin Yañez de la Barbuda, que habia tenido revelacion de que el tal maestre ganaria grandes victorias contra moros si retase al rey de Granada.\"},{\"heading\":false,\"text\":\"Engañado el maestre por la fama de santidad del ermitaño, envió á algunos de los suyos á Granada, para que retasen al rey Juzef á hacer campo con el maestre, y que si el rey no quisiese aceptar entrarian en liza veinte, treinta ó cien cristianos contra un número doble de moros.\"},{\"heading\":false,\"text\":\"El rey Juzef, mas cuerdo que Martin Yañez, mandó que echasen de mala manera á tales embajadores, que volvieron maltratados y escarmentados al maestre.\"},{\"heading\":false,\"text\":\"Irritado este, dejándose llevar de su condicion soberbia y belicosa, levantó un golpe de gente allegadiza, aventurera y mal armada, y con trescientos caballos y hasta cinco mil peones ó infantes, gente toda floja y baldia, se atrevió á pasar la frontera, desoyendo los buenos consejos de los hermanos Alonso y Diego Fernandez de Córdoba, señores de Aguilár, que le salieron al camino con intento de disuadirle de su temeridad.\"},{\"heading\":false,\"text\":\"Pasó, pues, la frontera, y puso sitio á Hins-Egea, á cuyo socorro el rey Juzef envió las tropas de caballería que habia en Granada y toda la infantería que pudo reunir en el momento.\"},{\"heading\":false,\"text\":\"El maestre levantó el sitio para salir al encuentro de los de Granada, y encontrándolos, trabó con ellos la batalla, que fué muy sangrienta y reñida, porque los de la caballería cristiana peleaban como desesperados.\"},{\"heading\":false,\"text\":\"Pero vencidos al fin por los del rey Juzef, dominados por el número, murió el maestre desastradamente, sin que quedase vivo ni uno solo de los desdichados que habia llevado consigo á aquella temeraria empresa.\"},{\"heading\":false,\"text\":\"Poco despues, el rey de Castilla (Enrique III) envió embajadores al rey de Granada, disculpándose del rompimiento temerario del maestre que habia roto la tregua sin su consentimiento.\"},{\"heading\":false,\"text\":\"Esta victoria acaeció el año setecientos noventa y ocho[102].\"},{\"heading\":false,\"text\":\"Poco despues murió el rey Juzef.\"},{\"heading\":false,\"text\":\"Atribuyeron su muerte á traicion del emir de Fez, que entre otros regalos le habia enviado una rica aljuba inficionada de tósigo, que luego que la vistió, como hubiese corrido un caballo y hubiese sudado, sintió al punto graves dolores que no le dejaron, hasta que pasados mas de treinta dias murió.\"},{\"heading\":false,\"text\":\"Pero hay fundados motivos para creer, que murió de otra dolencia que padecia mucho tiempo antes.\"},{\"heading\":false,\"text\":\"Fué enterrado este en Generalife.\"},{\"heading\":false,\"text\":\"No consta la inscripcion de su tumba.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo VIII\",\"blocks\":[{\"heading\":false,\"text\":\"El ambicioso infante Muhamad habia hecho que sus intrigas y la ayuda de sus parciales, prevaleciesen sobre la voluntad de su padre, que habia dejado el reino á su hermano mayor Juzef, y le proclamasen en su lugar rey los mas poderosos del reino.\"},{\"heading\":false,\"text\":\"Su primer decreto fué el que reducia á prision á su hermano Juzef, que inmediatamente fué llevado á Jalubania (Salobreña) y encerrado en una torre, con órdenes rigorosísimas para que fuese bien guardado.\"},{\"heading\":false,\"text\":\"Permitióle, sin embargo, llevar consigo su familia y su harem, y dió órden para que nada faltase á su comodidad y regalo.\"},{\"heading\":false,\"text\":\"Era Muhamad hermoso, de buen ingenio, valiente, afable, y muy apropósito para ganarse la voluntad del pueblo.\"},{\"heading\":false,\"text\":\"Queriendo evitar un rompimiento con los cristianos, tomó una resolucion audaz. Partió de Granada sin pompa de ningun género, como un caballero particular, y de incógnito, fingiéndose embajador de sí mismo, acompañado de veinte y cinco valientes y esforzados caballeros, pasó á Toledo y se presentó al rey de Castilla, que le honró, y renovó con él las paces que habia tenido con su padre.\"},{\"heading\":false,\"text\":\"Al mismo tiempo escribió al rey de Fez escusándose de la determinacion que habia tomado de encerrar á su hermano, por el bien de la paz y la tranquilidad del reino.\"},{\"heading\":false,\"text\":\"Poco tiempo despues, los fronteros de Andalucía entraron en tierra de Granada adelante, talándola contra lo concertado en las treguas.\"},{\"heading\":false,\"text\":\"Muhamad prefirió tomar el desagravio por sí mismo, á quejarse al rey de Castilla, y entró á su vez en tierra de cristianos por el Algarbe, talando y saqueando, y apoderándose de la fortaleza de Ayamonte, que á pesar de las reclamaciones del rey de Castilla no devolvió, por lo que se rompió de todo punto la tregua.\"},{\"heading\":false,\"text\":\"Suspendió la llegada del invierno esta guerra en su principio, y cuando el rey de Granada esperaba que viniese sobre él en persona con un poderoso ejército el de Castilla, murió éste, dejando el reino a su hijo Yahye (Juan el II) que era muy niño, y la gobernacion, en su nombre, á su tio el infante don Fernando, conocido mas adelante con el renombre de _el de Antequera_.\"},{\"heading\":false,\"text\":\"Don Fernando continuó la guerra que no habia podido proseguir su difunto hermano don Enrique III, y tomó á Zahara y la fortaleza de Azeddin, y la de Setenil, y las de Ayamonte, Priego, Lacobin y Ortegicar.\"},{\"heading\":false,\"text\":\"En vez de salir Muhamad al encuentro de este ejército vencedor, y para dividirle y fatigarle, entró por el reino de Jaen talándolo todo y obligando á los cristianos á acudir al reparo, y á dejar sus recientes conquistas.\"},{\"heading\":false,\"text\":\"A principios del año siguiente, Muhamad marchó contra Alcalá con un ejército de siete mil caballos y doce mil infantes, con el cual sostuvo con los cristianos tantos y tan reñidos encuentros, que entrambas huestes perdieron sus principales capitanes, y se vieron obligadas de comun acuerdo á pactar una tregua de ocho meses, que fué ratificada por el rey de Castilla, á quien Muhamad envió sus mensageros.\"},{\"heading\":false,\"text\":\"Durante esta tregua se sintió tan enfermo Muhamad, que los médicos desconfiaron de curarle, y declararon que el término de aquella enfermedad era su muerte.\"},{\"heading\":false,\"text\":\"Creyólo al fin Muhamad, y por asegurar la corona en su heredero, determinó dar muerte á su hermano Juzef, que estaba preso en Jalubania, y escribió la siguiente carta al gobernador de aquella fortaleza.\"},{\"heading\":false,\"text\":\"«Alcaide de Jalubania, mi servidor, luego que de mano de mi arraez, Ahmed-ebn-Jarac recibas esta carta, quitarás la vida á Cid Juzef, mi hermano, y me enviarás su cabeza con el portador: espero que no hagas falta en mi servicio.»\"},{\"heading\":false,\"text\":\"Cuando el arraez llegó con esta funesta carta á Jalubania, Juzef, el príncipe sentenciado, jugaba al ajedrez con el alcaide de la fortaleza, sentados sobre preciosos tapices bordados de oro y en almohadones de oro y seda.\"},{\"heading\":false,\"text\":\"Cuando el alcaide leyó la órden, se inmutó y tembló, porque Juzef por sus escelentes prendas, se ganaba los corazones de todos.\"},{\"heading\":false,\"text\":\"El arraez daba prisa al alcaide para que cumpliese la órden del rey, y el alcaide no se atrevia á dar parte al príncipe de tan cruel decreto.\"},{\"heading\":false,\"text\":\"Pero Juzef, conociendo por la turbacion del alcaide la importancia de la órden, le dijo:\"},{\"heading\":false,\"text\":\"--¿Qué manda el rey? ¿trata de mi muerte? ¿pide mi cabeza?\"},{\"heading\":false,\"text\":\"Entonces el alcaide le dió la carta, y despues de leerla dijo al arraez:\"},{\"heading\":false,\"text\":\"--Permíteme algunas horas para despedirme de mis doncellas y distribuir mis alhajas entre mi familia.\"},{\"heading\":false,\"text\":\"--Señor, dijo el arraez: no puede detenerse la ejecucion, porque he traido por horas el tiempo de mi vuelta.\"},{\"heading\":false,\"text\":\"--Pues á lo menos, dijo Juzef, acabemos el juego, y acabaré perdiendo.\"},{\"heading\":false,\"text\":\"Era tanta la turbacion del alcaide, que no movia pieza que no cometiese un desacierto, y tanto el valor y la serenidad del príncipe, que le avisaba de sus equivocaciones.\"},{\"heading\":false,\"text\":\"Seguia el juego, y el arraez se impacientaba, cuando llegaron dos caballeros de Granada á rienda suelta, aclamando á Juzef y pregonando la muerte de su hermano Muhamad.\"},{\"heading\":false,\"text\":\"Dudaba de ello Juzef, y apenas creia lo que pasaba, cuando la llegada de otros caballeros principales confirmó la noticia, y Juzef fué llevado apresuradamente á Granada.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo IX\",\"blocks\":[{\"heading\":false,\"text\":\"La entrada fué magnífica: le salió á recibir toda la nobleza; las calles estaban adornadas de arcos de triunfo y cubiertas de flores; las paredes entapizadas de ricos paños de seda y oro, y por todas partes resonaban las aclamaciones populares.\"},{\"heading\":false,\"text\":\"Paseó la ciudad dos dias, manifestando su agradecimiento y amor á los habitantes, y cada vez las demostraciones del afecto popular crecian, porque sus virtudes y su afabilidad eran muy conocidas.\"},{\"heading\":false,\"text\":\"Fué proclamado con el nombre de Juzef III.\"},{\"heading\":false,\"text\":\"Inmediatamente envió un embajador al rey de Castilla don Juan II, participándole su advenimiento al trono, y para darle á conocer sus pacíficas intenciones, y cuánto era su deseo de establecer una paz sólida y duradera entre Granada y Castilla.\"},{\"heading\":false,\"text\":\"Recibieron favorablemente en la corte de Castilla al embajador, y se convinieron las treguas como en tiempo del difunto rey Muhamad.\"},{\"heading\":false,\"text\":\"Pasado el tiempo de la tregua, Juzef envió á su hermano Alí á Castilla, á que la prorogase, pero los gobernadores de Castilla pretendian que el rey Juzef se declarase vasallo de su rey.\"},{\"heading\":false,\"text\":\"El infante Cid Alí se negó á esta humillacion, y dijo que no tenia licencia de su hermano el rey para obligarse hasta tal punto, y se tornó á Granada sin concertar las treguas.\"},{\"heading\":false,\"text\":\"Por lo tanto, en el momento que terminaron las anteriores, el infante don Fernando, gobernador de Castilla, entró poderosamente en el reino de Granada, y puso sitio á la ciudad de Antequera.\"},{\"heading\":false,\"text\":\"Acudieron al socorro de la ciudad los infantes hermanos del rey Cid Ahmed y Cid Alí, pero el infante don Fernando habia mandado levantar una cerca muy alta al rededor de la ciudad, y estrechados los habitantes por el hambre, se avinieron á entregar la ciudad, saliendo salvos con todos sus haberes.\"},{\"heading\":false,\"text\":\"Desde entonces el infante de Castilla se llamó don Fernando el de Antequera.\"},{\"heading\":false,\"text\":\"Despues de la rendicion de esta ciudad, rindió á Hins-Híjar, y otras fortalezas de la comarca.\"},{\"heading\":false,\"text\":\"Por este tiempo, oprimidos los moros de Gibraltar por las tiranías y las exacciones de su walí, y cansados de su sujecion al rey de Granada, escribieron al emir de Fez, y se le ofrecieron por sus vasallos si les socorria.\"},{\"heading\":false,\"text\":\"El emir Abu-Sayd, recibió con gozo este embajador, y envió á su hermano Cid Abu-Sayd con dos mil hombres á que ocupase á Gibraltar.\"},{\"heading\":false,\"text\":\"Pasó el infante de Fez el estrecho, llegó á Gibraltar, abriéronle los de la ciudad las puertas, y el walí se retiró á la fortaleza, y viendo que no le acudia socorro de Granada, estaba á punto de entregarse cuando llegó el infante Cid Ahmed con un fuerte escuadron de caballería y rescató la ciudad.\"},{\"heading\":false,\"text\":\"Insistió de nuevo Juzef en sus treguas con el rey de Castilla, y las pactó por dos años.\"},{\"heading\":false,\"text\":\"Mientras vivió el rey Juzef, Granada gozó los beneficios de la paz, y la corte era el refugio de los caballeros agraviados de Castilla y Aragon: allí iban á concluir sus diferencias, eligiendo por juez al rey Juzef, y este les daba campo para sus desafíos y combates de honor; siendo al mismo tiempo tan conciliador, que despues de darles campo, y apenas principiada la lid, los daba por buenos caballeros y los hacia volver amigos y vivir juntos y honrados de su corte.\"},{\"heading\":false,\"text\":\"Amábanle, pues, propios y estraños, y especialmente la reina doña Catalina de Lancaster, madre del rey de Castilla, con quien mantenia correspondencia muy familiar, y se hacian mutuos presentes.\"},{\"heading\":false,\"text\":\"Este buen rey murió de una manera súbita en 1425.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo X\",\"blocks\":[{\"heading\":false,\"text\":\"Inmediatamente fué proclamado su hijo Muley[103] Muhamad-Nazar-ebn Juzef, conocido con el sobrenombre de Al-Hayzarí ó el Izquierdo, á causa de que lo era, ó mas bien, segun algunos quieren, tenia este sobrenombre no por defecto natural de las manos, sino por su aviesa y contraria fortuna.\"},{\"heading\":false,\"text\":\"Su nombre, cronológicamente considerado, fué el de Muhamad VII.\"},{\"heading\":false,\"text\":\"Despues de haber sepultado con gran pompa á su padre en el palacio de Djene-al-Arife, escribió á las ciudades y pueblos de cada tah, para que celebrasen su proclamacion con la solemnidad acostumbrada.\"},{\"heading\":false,\"text\":\"No imitó el buen gobierno de su padre sino en un solo punto, que fué en el de mantener la paz con los reyes de España y los emires de Africa; pero se cuidó muy poco de adquirirse el amor de sus vasallos; era vano, soberbio y déspota; los wazires, los cadíes y los walíes de su corte y de su ejército, los mas respetables magnates del reino, eran tratados por él como esclavos, creciendo de momento en momento su altanería hasta hacerse insoportable. Pasaba largos períodos de tiempo sin dar audiencia á sus vasallos, ni aun á los walíes que le buscaban para consultar con él los mas graves negocios.\"},{\"heading\":false,\"text\":\"Circunscribíase á mantener á todo trance la paz con los cristianos y con los de Africa, y á no dar por su parte ocasion á un rompimiento. Desdeñaba el trato con sus ciudadanos, y no consentia justas ni torneos ni otras fiestas guerreras á que estaba acostumbrada la belicosa nobleza de la corte. Solamente tenia influencia con él su wazir y kadí de Granada, Juzef-ebn-Zeragh[104], caballero ilustre de la mas noble y poderosa familia del reino, que pudo contener por algun tiempo con su prestigio el que estallase el ódio de los descontentos que pretendian la deposicion de Muhamad; pero al fin, ni su prudencia, ni su valor, ni su influencia, pudieron evitar que estallase una insurreccion popular en que fué proclamado Muhamad-al-Zaquir, primo del rey, y que algunos entrasen violentamente en el alcázar, de cuyo furor solo pudo escapar el rey, merced al valor de algunos guardias leales que protegieron su fuga por los jardines.\"},{\"heading\":false,\"text\":\"Una vez en salvo Muhamad Al-Hayzarí, pasó disfrazado de pescador en una barca á Africa, y se acogió al amparo de su amigo el emir de Túnez Abu-Faris, que le prometió su ayuda en el dia en que fuese para él probable la vuelta al trono.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XI\",\"blocks\":[{\"heading\":false,\"text\":\"Muhamad-al-Zaquir fué proclamado bajo el nombre de Muhamad VIII, en 1427.\"},{\"heading\":false,\"text\":\"Reconociéronle por su rey las principales ciudades del reino; hubo magníficas fiestas en Granada, y él mismo, que se jactaba de ser buen justador, entraba en las parejas y contiendas, y hacia notables gallardías arrojando las cañas con singular acierto y ligereza, evitando los tiros con facilidad, y volviendo y revolviendo con sin igual destreza su caballo.\"},{\"heading\":false,\"text\":\"Observando una conducta enteramente opuesta á la de Al-Hayzarí, frecuentaba el trato de sus caballeros, comia con ellos, les hacia ricos presentes, captándose su voluntad por todos los medios imaginables.\"},{\"heading\":false,\"text\":\"Del mismo modo cuidó de inutilizar á los partidarios del depuesto Al-Hayzarí, y el wacir Juzef-Ebn-Zeragh se vió obligado á salir de Granada con la mayor parte de los caballeros de su linage, que avisados á tiempo de las aviesas intenciones del rey hácia ellos, huyeron al reino de Murcia, donde tenian amigos que los ocultaron.\"},{\"heading\":false,\"text\":\"Algunos de estos abencerrages que se quedaron confiadamente en Granada, probaron el tiránico rigor de Al-Zaquir, que creyéndose ya asegurado en el trono, empezó á dar muestras de su condicion sanguinaria y cruel.\"},{\"heading\":false,\"text\":\"Con el wazir Juzef habian huido á Murcia veinte caballeros abencerrages, que habiendo recibido seguro del rey don Juan el II, pasaron á besarle la mano á la corte de Castilla.\"},{\"heading\":false,\"text\":\"Sabedor el rey, por la relacion de estos caballeros, de las tiranías de Al-Zaquir, y que huyendo de ellas habian pasado á Castilla y á África mas de quinientos caballeros, y movido á compasion por la desgracia de su aliado el rey Muhamad-Al-Hayzarí, ofreció al wazir Ebn-Zeragh restituir al trono al depuesto rey.\"},{\"heading\":false,\"text\":\"A este propósito acordó que el alcaide de Murcia, en compañía de Ebn-Zeragh, pasase á Túnez con cartas suyas para que el emir Abu-Farís ayudase á cobrar el reino de Granada y restituir al trono á su legítimo rey, y el de Castilla pedia al de Túnez que le enviase al destronado rey, que él haria de modo que fuese restituido á su anterior dignidad.\"},{\"heading\":false,\"text\":\"Recibido este mensage, el emir de Túnez dió órden para que Muhamad-Al-Hayzarí pasase á España con quinientos caballeros y muchas riquezas, y al mismo tiempo envió al rey de Castilla, con el alcaide de Murcia, telas de seda y oro, linos muy delicados, aromas, preciosidades, y una cria de leoncillos domesticados.\"},{\"heading\":false,\"text\":\"Al-Hayzarí pasó á Orán en compañía de Ebn-Zeragh y de sus caballeros, embarcóse en aquel puerto, saltó en tierra de Granada por la parte de Vera, cuya ciudad le recibió con aclamaciones de alegría, y Almería del mismo modo le recibió de nuevo por su rey.\"},{\"heading\":false,\"text\":\"Cuando estas novedades llegaron á oidos del usurpador Al-Zaquir se alarmó sériamente, y envió sin perder momento á su hermano con setecientos caballos escogidos, contra la gente del rey Al-Hayzarí, pero mas de la mitad de esta gente se pasó á la del rey, y el infante, no atreviéndose á acometer nada con los que le habian quedado, se volvió.\"},{\"heading\":false,\"text\":\"Facilitado el paso á los del rey Al-Hayzarí, desde Almería, adelantaron hasta Guadix, y esta ciudad abrió sus puertas y recibió por su señor al rey, jurándole obediencia en el mismo dia.\"},{\"heading\":false,\"text\":\"No tardaron en llegar á Guadix gran número de caballeros de Granada que animaron á Al-Hayzarí para pasar á ella, asegurándole tan buena acogida como en Almería y Guadix: así, pues, confiando en la fortuna, aunque con algun recelo, partió Al-Hayzarí á Granada, llevando consigo un gentío inmenso que de todas partes le seguia ávido de novedades, por las que sin otra causa ni motivo le aclamaba aquella muchedumbre.\"},{\"heading\":false,\"text\":\"Al ver el usurpador acercarse esta tormenta, tuvo miedo; se pasó de noche del Albaicin al alcázar de la Alhambra, y se fortificó en él.\"},{\"heading\":false,\"text\":\"Al dia siguiente entró Al-Hayzarí en Granada, que le recibió con grandes aclamaciones, y cercando á seguida la Alhambra, se apoderó de Al-Zaquir y le mandó cortar la cabeza.\"},{\"heading\":false,\"text\":\"Acaecieron estos sucesos en 1427.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XII\",\"blocks\":[{\"heading\":false,\"text\":\"Restaurado en su primera dignidad Al-Hayzarí, repuso en su empleo de wazir al leal Ebn-Zeragh, y estrechó su alianza con el rey de Castilla y el emir de Túnez.\"},{\"heading\":false,\"text\":\"Hizo mas: sabiendo que el rey de Castilla andaba en guerras y en bandos civiles, envióle como embajador á un principal caballero de Granada, llamado Abd-el-Menam, privado suyo, ofreciéndole auxilios de tropas contra sus enemigos.\"},{\"heading\":false,\"text\":\"Don Juan el II agradeció, pero no aceptó este ofrecimiento, y solo se trató de treguas y de que el rey de Granada pagase al de Castilla cierta cantidad de doblas de oro cada año, á título de vasallage.\"},{\"heading\":false,\"text\":\"Resistióse a esto Al-Hayzarí, confiado en que el rey de Castilla tendria bastante con sus negocios para mostrarse exigente, y que se contentaria con lo que de su propia voluntad quisiera darle.\"},{\"heading\":false,\"text\":\"Retiróse, pues, Abd-el-Menam á Granada sin haber concertado nada con el rey de Castilla, que ofendido de esto, escribió al emir de Túnez quejándose de la ingratitud de Al-Hayzarí y rogándole que no le ayudase en la guerra que pensaba hacerle para obligarle á cumplir con lo que debia.\"},{\"heading\":false,\"text\":\"Contestó Abu-Faris al rey de Castilla que así lo haria, y en vez de enviar á Al-Hayzarí las galeras y gentes que le habia prometido, le escribió aconsejándole que pagase al rey de Castilla, á quien debia la corona, la concertada suma de doblas que le pedia, y que de no hacerlo así, no esperase su ayuda mientras viviese: escribió asimismo al rey de Castilla suplicándole que fuese moderado en su venganza, y que no fuese demasiado rigoroso con Muhamad-Al-Hayzarí su pariente.\"},{\"heading\":false,\"text\":\"El rey de Castilla envió órden á sus fronteros para que corriesen la tierra de Granada, á todo trance, talando y cautivando cuanto encontrasen.\"},{\"heading\":false,\"text\":\"Los fronteros entraron á este tiempo por dos puntos distintos: por Ronda y por Cazorla.\"},{\"heading\":false,\"text\":\"La suerte en estas dos entradas fué distinta: los castellanos que entraron por Ronda vencian: los que entraron por Cazorla, eran vencidos por Al-Hayzarí; pero como le llegase nueva de que el rey de Castilla adelantaba con un poderoso ejército, temiendo que con esta novedad se suscitase contra él alguna rebeldía en Granada, partió apresuradamente á ella, dejando el mando de su ejército á sus principales walíes, y llegando á la ciudad armó veinte mil hombres para que la defendiesen.\"},{\"heading\":false,\"text\":\"Entretanto los cristianos corrian la tierra de Granada y se apoderaban de Illora, Tajajar, Archidona y otros lugares, y el rey de Castilla se volvió con una numerosa presa á Ecija, y de allí á Córdoba.\"},{\"heading\":false,\"text\":\"Como Al-Hayzarí temia, se levantó contra él una terrible conjuracion en Granada: un caballero de la sangre real, Juzef-ebn-Al-Hhamar, ambicioso y rico, se propuso arrojar del trono al rey y apoderarse de la corona de Granada con la ayuda del rey de Castilla.\"},{\"heading\":false,\"text\":\"Con acuerdo de sus parientes y parciales envió de mensagero á los nobles á un caballero de la tribu de los Beni-Egas, Geleil-ebn-Geleil, que habia casado por amores con la infanta Ceti-Merier, era fuerte y bravo, de linage de cristianos, y el rey por temor ó recelo le tenia desterrado en Alhama.\"},{\"heading\":false,\"text\":\"A este caballero, pues, como hablaba perfectamente la lengua castellana, se le confió la embajada ante el rey de Castilla, á nombre de Juzef-Ebn-Al-Hhamar. Ofrecia este que luego que el rey de Castilla entrase en la Vega de Granada, se le uniria con mas de ocho mil hombres, cuya mayor parte eran caballeros de las principales familias del reino, y aun si se apoderaba de él con la ayuda del rey de Castilla, seria su mas leal vasallo.\"},{\"heading\":false,\"text\":\"Esta proposicion fué bien acogida por el rey de Castilla, como quien de todos modos pensaba entrar por la Vega.\"},{\"heading\":false,\"text\":\"Alentados con esta promesa los del bando del rebelde Juzef, salieron poco á poco de Granada con el pretesto de ir al ejército de la frontera, y cuando poco despues el rey de Castilla entró talando la vega, Juzef-Ebn-Al-Hhamar se le presentó, le besó la mano en señal de vasallaje, y despues llegaron los caudillos y gentes de su bando en número de ocho mil hombres, la mayor parte caballeros.\"},{\"heading\":false,\"text\":\"Al-Hhamar, desde la falda de sierra Elvira, donde habia acampado el rey de Castilla, señalaba á este los principales edificios y fortalezas de Granada, la Alhambra, Torres-bermejas, Generalife y el Albaicin.\"},{\"heading\":false,\"text\":\"El rey de Castilla miraba la hermosa ciudad con deleite.\"},{\"heading\":false,\"text\":\"A este propósito se escribió la siguiente poesía que insertamos, porque su belleza agradará sin duda á nuestros lectores:\"},{\"heading\":false,\"text\":\"Don Juan, rey de España, cabalgando un dia, desde una montaña á Granada via.\"},{\"heading\":false,\"text\":\"Díjole prendado: «Hermosa ciudad, mírame afanado, tras de tu beldad.\"},{\"heading\":false,\"text\":\"»De mi amor en muestra, fé de caballero, le ofrezco mi diestra y la tuya espero.»\"},{\"heading\":false,\"text\":\"«Junta tus blasones con los de Castilla, y te traeré en dones Córdoba y Sevilla.\"},{\"heading\":false,\"text\":\"»Mucha ofrenda de oro, joyas muy preciadas, si dejais al moro te tengo guardadas.»\"},{\"heading\":false,\"text\":\"Respondió Granada: «Vuélvete á Toledo que yo estoy casada y amarte no puedo.»\"},{\"heading\":false,\"text\":\"«Tu ambicion modera, vete mas despacio: mira esa bandera que ondea en Palacio.»\"},{\"heading\":false,\"text\":\"«Guarda tu presente, y en vez de dinero, si te crees valiente prueba con acero.»\"},{\"heading\":false,\"text\":\"«Mil torres me guardan; cien mil campeones dispuestos aguardan á tus infanzones.»\"},{\"heading\":false,\"text\":\"Así tú decias; así tú mentias Granada es perjura, ¡grande desventura!\"},{\"heading\":false,\"text\":\"Un infiel maldito del Abencerrage, tiene el heredaje: ¡así estaba escrito!\"},{\"heading\":false,\"text\":\"Raza de valientes: ¿Quién te esterminó? ciudad de las fuentes ¿quién te cautivó?\"},{\"heading\":false,\"text\":\"Alhambra querida mansion del placer: ¿para qué es la vida si no te he de ver?\"},{\"heading\":false,\"text\":\"Al ver ante la ciudad el ejército de Castilla, los caballeros de Granada salieron contra él empeñando reñidas escaramuzas, hasta que al fin se empeñó una batalla campal que fué muy sangrienta, peleando con gran valor tanto los cristianos como los moros.\"},{\"heading\":false,\"text\":\"La matanza fué horrible por ambas partes, y la batalla se mantuvo igual todo el dia, hasta que á la tarde empezaron á ceder los moros, y al amparo de la noche dejaron el campo.\"},{\"heading\":false,\"text\":\"Aquella fué la batalla mas lamentable que tuvo el reino de Granada, que perdió en ella la flor de sus caballeros, y se vió combatida por sus propios hijos.\"},{\"heading\":false,\"text\":\"Llenáronse de tristeza los habitantes, pero la serenidad de ánimo del rey Al-Hayzarí, no les dejó tomar otro partido que el de la defensa.\"},{\"heading\":false,\"text\":\"Un fuerte temblor de tierra, coincidiendo con esta derrota, vino á aterrar á los de Granada, que supersticiosos de suyo, vieron en aquel accidente, puramente físico, el augurio de nuevas desdichas.\"},{\"heading\":false,\"text\":\"Pero el rey de Castilla se contentó con talar la vega, y levantó el campo con gran despecho del ambicioso Al-Hhamar, y se trasladó á Córdoba.\"},{\"heading\":false,\"text\":\"Allí, para consolar á Jusef-Ebn-Al-Hhamar de su despecho, y á sus gentes de la desconfianza en que habian caido, obligados á abandonar, por su rebeldía al rey Al-Hayzarí, sus haciendas y su patria, mandó proclamar rey de Granada á Juzef-Ebn-Al-Hhamar delante de su corte y de su ejército que solemnizó la proclamacion; ofrecióle de nuevo ponerle en el trono de Granada, y allí mismo encargó á los adelantados de las fronteras, que ayudasen á Al-Hhamar hasta conseguirlo.\"},{\"heading\":false,\"text\":\"Esta proclamacion de Al-Hhamar en la córte y campo del de Castilla produjo gran efecto en Granada en daño de Al-Hayzarí: muchos pueblos del rey se levantaron por Al-Hhamar, se le entregó Montefrío, y con la ayuda de los fronteros cristianos se apoderó de los pueblos y fortalezas de Illora, Cambil, Alabar, Ortejicar, Tajarja, Hins-Haleux, Ronda y la ciudad de Loja, de donde salieron para unírsele cuatrocientos caballeros; en Ardales otorgó su carta de vasallaje al rey de Castilla, obligándose á pagarle cada año cierta cantidad de doblas de oro, á ayudarle como vasallo en sus guerras con mil y quinientos caballos, y á acudir á sus cortes cuando las celebrase en cualquier lugar desde mas acá de Toledo hácia Granada.\"},{\"heading\":false,\"text\":\"Despues de este otorgamiento, Al-Hhamar marchó con un respetable ejército sobre la córte de Al-Hayzarí, que movió contra él á su wisir Juzef-Ebn-Zeragh, que llegando á las manos con los invasores, murió en la vega peleando como un leon, al decir de las crónicas árabes. La muerte de este bravo caudillo, causó la confusion y el espanto en el ejército de Al-Hayzarí, que entró en desórden en Granada, ponderando lo innumerable del ejército que los habia vencido, y que la mayor parte de los del rey Al-Hayzarí, habian sido muertos porque los enemigos no tomaban á prision.\"},{\"heading\":false,\"text\":\"Despues de esta victoria de Al-Hhamar, casi todas las taas del reino le proclamaron, y temiendo á las talas y desastres de la guerra, llegaban de todas partes á rendir homenage al vencedor.\"},{\"heading\":false,\"text\":\"Robustecido ya, legitimado por la victoria (el Korán da el califato al vencedor) Juzef-Ebn-Al-Hhamar marchó desde Illora sobre Granada, que se alborotó á su aproximacion, y los nobles y los principales vecinos se presentaron á Al-Hayzarí, y le manifestaron que era imposible la defensa, que con la resistencia se provocarian nuevos desastres, y que no le quedaba mas tiempo que el necesario para ponerse en salvo.\"},{\"heading\":false,\"text\":\"Viéndose, pues, abandonado de la fortuna, Muhamad-Al-Hayzarí, acompañado de sus vasallos mas fieles, llevando consigo su familia, su harem, el tesoro del alcázar y los dos hijos del rey Muhamad-Al-Zaquer, que tenia presos, huyó á la ciudad de Málaga, en cuya adhesion tenia gran confianza.\"},{\"heading\":false,\"text\":\"Juzef-Al-Hhamar, tuvo el buen tacto de entrar en Granada con solos doscientos caballeros, mas como guardia necesaria á su decoro de rey, que como medio de intimidacion á la ciudad.\"},{\"heading\":false,\"text\":\"Esta conducta produjo muy buen efecto: aquietáronse los ciudadanos, y los xeques, wazires, walíes, cadíes y alcaides del reino, salieron á recibirle, le proclamaron solemnemente rey, le juraron y le pasearon en triunfo por la ciudad.\"},{\"heading\":false,\"text\":\"A seguida el nuevo rey envió embajadores al rey de Castilla, confesándose agradecido vasallo suyo, y con la carta siguiente:\"},{\"heading\":false,\"text\":\"«Juzef-Muhamad-Ebn-Al-Hhamar, rey de Granada, vuestro vasallo, beso vuestras manos y me encomiendo á vuestra merced, á la que suplico se digne saber como partí de Illora y fuí á mi ciudad de Granada, y me salió á recibir toda la nobleza y caballería de ella, y me besaron las manos por su rey y señor y me entregaron la Alhambra, y todo esto, señor, por la gracia de Dios y vuestra fortuna. El rey Al-Hayzarí se huyó á Málaga y llevó consigo al hermano del alcaide Ahnaf, su sobrino y dos hijos del rey Muhamad-Zaquer, que dicen ha mandado degollar, y antes de partir robó estos alcázares, y se llevó cuanto en ellos habia. Ahora, señor, con la ayuda y gracia de Dios, y con el auxilio de vuestra grandeza, que Dios prospere, vá contra él vuestro adelantado don Gomez Rivera, y mis caballeros llegarán á Málaga, donde él está, y espero en Dios, que con el favor de vuestra alteza yo le habré en mis manos.»\"},{\"heading\":false,\"text\":\"Esta carta fué muy bien recibida por el rey don Juan, que se alegró mucho del triunfo de su vasallo, y al mismo tiempo llegó un enviado del emir de Túnez, en que éste pedia al rey de Castilla mirase por su pariente Muhamad-Al-Hayzarí, y no quisiese arruinarle ni arrojarle de su reino.\"},{\"heading\":false,\"text\":\"Don Juan el II se escusó con Abu-Faris, y Juzef-Ebn-Al-Hhamar continuó pacíficamente en el trono de Granada.\"},{\"heading\":false,\"text\":\"Pero era anciano, y á los seis meses de reinado, achacoso y débil, no pudo resistir el gran peso de los negocios del gobierno que habia tomado con demasiado fervor, y murió.\"},{\"heading\":false,\"text\":\"Su muerte concluyó los bandos que dividian á los granadinos, y los de una y otra bandería se unieron y llamaron y proclamaron de nuevo unánimemente al fugitivo Al-Hayzarí.\"},{\"heading\":false,\"text\":\"Recibió éste la noticia en Málaga, que se le habia mantenido fiel, y volvió á Granada y á ocupar por tercera vez el trono.\"},{\"heading\":false,\"text\":\"Nombró su wazir á Abdelbar, principalísimo caballero de Granada, y envió embajadores al rey de Castilla y al emir de Túnez, renovando con ellos su alianza y concertando treguas con los cristianos por un año, que cumplido, se prorogaron por otro mas.\"},{\"heading\":false,\"text\":\"Pero espirado el plazo, los fronteros entraron por las tierras de Granada y se apoderaron de la fortaleza de Beni-Maurel, al mismo tiempo que por la parte de Murcia los fronteros castellanos eran desastradamente batidos por la caballería del Algarbe, mandada por el wazir Abdelbar.\"},{\"heading\":false,\"text\":\"A pesar de esta ventaja por la parte de Murcia, el rompimiento de la tregua fué desventajoso para Granada, puesto que la ciudad de Huesca cayó tambien en poder de los cristianos, á pesar de la bravura con que acudió á su socorro el arraez de Baza Alcawun, que entró alguna de su gente en el castillo, rompiendo por medio de los cristianos.\"},{\"heading\":false,\"text\":\"En el año siguiente de ochocientos cuarenta[105] el wazir Abdelbar acometió á los cristianos en unas angosturas en el término de Archidona, y los venció, los persiguió é hizo en ellos una gran carnicería. Habian intentado los fronteros sorprender la villa por caminos estraviados, y Abdelbar, que en las citadas angosturas los esperaba, los destrozó como queda dicho, tomándoles la bandera de la órden de Alcántara, cautivando á casi todos los cristianos que no fueron muertos, y logrando salvarse milagrosamente con unos pocos el maestre de Alcántara, gracias á la velocidad de su caballo.\"},{\"heading\":false,\"text\":\"A seguida Abdelbar se volvió contra los castellanos que cercaban la villa de Huelma, y los obligó á levantar el cerco y retirarse á Jaen.\"},{\"heading\":false,\"text\":\"En el año siguiente la suerte de las armas continuó siendo favorable á los granadinos.\"},{\"heading\":false,\"text\":\"En el subsiguiente los fronteros de Murcia, acaudillados por el adelantado Ebn-Fayard[106], tomaron por avenencia las fronteras de Veladaviad y Veladalhamar[107].\"},{\"heading\":false,\"text\":\"Los habitantes quedaron como mudejares[108] ó mercenarios del rey de Castilla para evitar las talas y atropellos de que los hacian víctimas los bravos fronteros de Murcia, con sus continuas entradas. Con el mismo objeto solicitaron sujetarse al vasallaje del rey de Castilla las ciudades de Guadix y Baza; pero pretendiendo quedar libres, sin sujecion á los adelantados castellanos y sin tomar parte en las guerras que se hiciesen por el rey de Castilla; pero este queria que le rindiesen las fortalezas para hacer desde ellas la guerra al rey de Granada, á lo que no se convinieron, siguiendo por lo tanto las correrías y las talas de los cristianos todo aquel año, talas que fueron muy crueles, y durante las cuales los fronteros se apoderaron de Galera y otras fortalezas, obligando á los moradores á quedar por mudejares del rey de Castilla.\"},{\"heading\":false,\"text\":\"Por el mismo tiempo el conde de Niebla cercó á Gibraltar; pero los moradores salieron contra él, le desbarataron, y el mismo conde murió en la fuga ahogado con muchos de los suyos en el rio Palmones, que estaba crecido con la marea.\"},{\"heading\":false,\"text\":\"En el año siguiente de ochocientos cuarenta y dos[109], don Iñigo Lopez de Mendoza, señor de Ita y Buitrago, y gran poeta, y mejor soldado, tomó á Huelma y dejó salir salvos á los moradores.\"},{\"heading\":false,\"text\":\"Por este tiempo el caudillo Ebn-Zeragh, hijo del wazir Juzef-Ebn-Zeragh, marchó contra los cristianos que recorrian la frontera acaudillados por el adelantado de Cazorla.\"},{\"heading\":false,\"text\":\"Encontráronse en una llanura entrambas huestes y pelearon reñidamente sin sacarse ventaja los unos á los otros; pero el bravo Ebn-Zeragh dió tales ejemplos de valor á los suyos, que estimulados estos desbarataron á los cristianos, costando sin embargo la vida esta victoria al generoso Abencerrage, que cayó desangrado por las muchas heridas: tambien murió como bueno el adelantado de Cazorla Perea, y casi todos los cristianos.\"},{\"heading\":false,\"text\":\"Esta victoria hizo que los castellanos escarmentados se contuviesen en sus correrías, y la frontera disfrutó de algun reposo. Pero como Castilla estaba dividida en bandos y parcialidades, cual si hubiese contagiado á Granada, muchos caballeros ofendidos del rey Muhamad, dejaron el seguro y se fueron al servicio del rey de Castilla, yendo á la cabeza de estos descontentos Ebn-Ismail, sobrino del rey Muhamad, ofendido de él porque le negó el casamiento con una dama, á quien amaba, y la entregó á otro.\"},{\"heading\":false,\"text\":\"Otro sobrino del rey, Ebn-Ozmin, que estaba en Almería, al saber el descontento con que los principales de Granada miraban al rey, se trasladó secretamente á la córte, y comprando á fuerza de oro al populacho, escitando las pasiones y el descontento de los nobles, produjo un alboroto, se apoderó de la Alhambra y demás fortalezas de Granada, prendió á su tio el rey Muhamad-Al-Hayzarí, y le puso en prision.\"},{\"heading\":false,\"text\":\"Era la tercera vez que este desgraciado príncipe se veia depuesto despues de trece años de reinado, y Muhamad-Ebn-Ozmin-el-Ahnaf fué proclamado, aunque no por la voluntad de todos, puesto que le abandonaron muchos, entre ellos el wazir Albdelbar, que se retiró á Montefrio con todos sus parientes y amigos.\"},{\"heading\":false,\"text\":\"Tuvo lugar la tercera deposicion de Al-Hayzarí el año ochocientos cuarenta y nueve[110].\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XIII\",\"blocks\":[{\"heading\":false,\"text\":\"Conociendo el wazir Abdelbar, que tomar el nombre del preso rey Al-Hayzarí, para reponerle en el trono, era causar su muerte, escribió al otro sobrino del rey, Ebn-Ismail, que estaba en Castilla, ofreciéndole el trono, y para que pudiese venir sin que el rey de Castilla se lo estorbase, le envió las cartas escritas en cifra por medio de dos caballeros parientes suyos disfrazados.\"},{\"heading\":false,\"text\":\"Recibió á estos mensajeros el infante, pero en vez de recatarse del rey de Castilla, le confió el secreto, y don Juan el II, no solamente le concedió licencia para ir á apoderarse del trono de Granada, sino que le prometió su ayuda y le dió cartas para que los adelantados de la frontera le ayudasen en su entrada.\"},{\"heading\":false,\"text\":\"Partió el infante Ismail con todos los caballeros moros que estaban con él al servicio del rey de Castilla, y desde la frontera le acompañaron los adelantados castellanos con numerosa y escogida caballería: llegó á Montefrio, donde le recibieron alegremente Abdelbar y los de su bando, y le proclamaron rey de Granada.\"},{\"heading\":false,\"text\":\"Ebn-Ozmin, entretanto, pensó en vengarse de los cristianos que ayudaban á su competidor, y con un poderoso ejército acometió las fronteras castellanas, se apoderó de Benamaurel, pasó á cuchillo y cautivó á los cristianos que defendian la villa, entre ellos á su alcaide Herrera, y los fronteros de Andalucía no se atrevieron á ponerse delante del rey Ozmin, aterrados por la violenta entrada de Benamaurel.\"},{\"heading\":false,\"text\":\"Entretanto Ebn-Ozmin, se puso sobre la fortaleza de Aben-Zulema, que estaba defendida por una fuerte guarnicion de castellanos, y por medio del cautivo alcaide Herrera, les intimó que se rindiesen evitando la desdichada fortuna de los de Benamaurel. Pero los de Aben-Zulema resistieron, y acometidos con ardor por los moros á escala franca, fueron entrados, pasados á cuchillo y cautivados, despues de lo cual Ebn-Ozmin se volvió á Granada triunfante con una riquísima presa de ganados, armas y cautivos.\"},{\"heading\":false,\"text\":\"En el siguiente año, el rey Muhamad-Ebn-Ozmin, dividió en dos ejércitos sus fuerzas.\"},{\"heading\":false,\"text\":\"El un ejército marchó sobre la frontera cristiana, y el otro contra su primo Ismail.\"},{\"heading\":false,\"text\":\"El rey se puso en persona á la cabeza del que marchaba sobre la frontera, y tomó las villas de Huesca, Veladabiad y Veladalhamar, ocupó sus fortalezas, taló y quemó la tierra, cautivó hombres y mugeres, apresó gran cantidad de ganado, y contento y rico se volvió á Granada.\"},{\"heading\":false,\"text\":\"Para vengarse mas del rey de Castilla, por la proteccion que dispensaba á su primo el infante Ismail, envió ricos presentes á los reyes de Aragon y de Navarra, que estaban en guerra con don Juan el II, y aliándose con ellos, estipuló que mientras aquellos reyes acometían al de Castilla por sus fronteras naturales, él le embestiria por las de Granada.\"},{\"heading\":false,\"text\":\"El año siguiente, cumpliendo la oferta, entró Ebn-Ozmin por la frontera de Murcia, taló y quemó sus campos y alquerías, y venció á los cristianos que le salieron al encuentro acaudillados por Tellez Giron, matando y prendiendo á muchos que llevó en triunfo á Granada.\"},{\"heading\":false,\"text\":\"Durante dos años aun, los dos reyes rivales Ebn-Ismail en Montefrio, y Ebn-Ozmin, en Granada, conservaron sus mútuas posiciones: Ebn-Ismail, defendia los pueblos que le habian proclamado de las correrías de Ebn-Ozmin, y este talaba contínuamente las fronteras castellanas.\"},{\"heading\":false,\"text\":\"El wisir Abdelbar por su parte, servia eficazmente á Ebn-Ismail, escitando contra Ebn-Ozmin por medio de agentes secretos, la odiosidad de los caballeros de Granada, descontentos la mayor parte de Ebn-Ozmin: ensoberbecido este por sus triunfos sobre los cristianos, se habia hecho altanero y soberbio y tan sanguinario, que con el mas leve pretesto, mandaba matar á los caballeros mas principales del reino, despojaba de sus alcaidias y empleos á los leales y viejos caballeros que los tenian para premiar á los arrayazes que le acompañaban en sus afortunadas correrías. Del mismo modo hacia los matrimonios de la juventud á su antojo y forzaba á los padres á dar sus hijas contra su voluntad á quien él queria.\"},{\"heading\":false,\"text\":\"Aborrecíale por lo tanto la nobleza, y el resto de sus vasallos le temia mas que le respetaba, por su crueldad.\"},{\"heading\":false,\"text\":\"Estas cosas facilitaron y abrieron camino á sus enemigos para llevar sus intentos adelante, y habiendo concluido el rey de Castilla su guerra con los de Aragon y Navarra, con ansia de vengar el daño que le habia causado Ebn-Ozmin, envió un grueso ejército á Ebn-Ismail que con este auxilio y sus gentes marchó ya decididamente sobre Granada.\"},{\"heading\":false,\"text\":\"Salióle al encuentro Ebn-Ozmin, y se trabó en la vega una reñidísima batalla, en que ambos primos pelearon con heróico valor; pero al cabo Ebn-Ozmin fué vencido y obligado á huir con los escasos restos de su caballería á Granada.\"},{\"heading\":false,\"text\":\"Llamó nuevas gentes, que enemistadas con él por su crueldad, le acudieron en corto número, y comprendiendo que la fortuna le volvia las espaldas, mandó que se le presentaran gran número de caballeros, los metió en el alcázar de la Alhambra y se fortificó en él; pero viendo que Granada se alborotaba y que proclamaban á su primo Ebn-Ismail, no se atrevió á esperarle y huyó con unos pocos caballeros que se le habian mantenido leales, metiéndose en las sierras, en las que desapareció.\"},{\"heading\":false,\"text\":\"Fué esta huida del rey Muhamad-Ebn-Ozmin, el año ochocientos cincuenta y nueve[111].\"},{\"heading\":false,\"text\":\"Habia reinado diez años.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XIV\",\"blocks\":[{\"heading\":false,\"text\":\"Entró Ebn-Ismail en Granada, que le recibió en triunfo.\"},{\"heading\":false,\"text\":\"Despues de su solemne proclamacion, tanto en Granada como en las demas ciudades, villas y lugares del reino, envió embajadores al rey de Castilla, declarándose su vasallo, y demostrándole su agradecimiento con un magnífico presente de telas de oro y seda, caballos y jaeces preciosos: pero cuando poco despues murió el rey don Juan el II de Castilla, no renovó la tregua y el vasallaje con su hijo don Enrique IV por no disgustar á sus vasallos, que estaban descontentos y humillados con la amistad y vasallaje que rendia á los reyes de Castilla.\"},{\"heading\":false,\"text\":\"Dió, pues, licencia á sus fronteros de talar las tierras castellanas, y fué grande la presa de cautivos y ganados que se hicieron en las primeras correrías, porque los castellanos, confiados en la buena inteligencia que existia entre su rey y el de Granada, tenian desarmada la frontera.\"},{\"heading\":false,\"text\":\"No habiendo dado motivo los castellanos para este rompimiento, el rey don Enrique mandó levantar un ejército y fué sobre Granada con catorce mil caballos y un formidable número de peones, llevándolo todo á sangre y fuego, quemando las mieses, arruinando los árboles y destruyendo cuanto encontraba de muros á fuera de las poblaciones.\"},{\"heading\":false,\"text\":\"Ebn-Ismail temió esponerse al éxito de una batalla de poder á poder, y solo permitió que taifas ó compañías sueltas de campeadores saliesen á escaramuzar contra los cristianos, á los que llevaban mucha ventaja en estos ataques parciales, mientras en la ciudad todos estaban apercibidos para rechazar un ataque del ejército cristiano.\"},{\"heading\":false,\"text\":\"Al fin don Enrique, viendo que los moros no le presentaban batalla, que en sus escaramuzas mataban á sus mejores caballeros que salian del campo á medirse con ellos, y no atreviéndose tampoco á acometer la ciudad, que estaba muy bien defendida, taló la vega, y se retiró volviendo á aparecer de nuevo al año siguiente con un ejército tan poderoso como el pasado; y como salieran á su encuentro los campeadores de Granada á estorbar á los cristianos el daño que hacian, se fué trabando tan recia escaramuza, que, sin que lo pudiese impedir el rey de Castilla, toda su caballería peleaba en trozos acá y allá con la caballería de Granada, muriendo en una de ellas Garcilaso de la Vega, que era muy querido del rey de Castilla, que en venganza de su muerte hizo una cruelísima tala en la vega, cercó á Gimena, la tomó con su fortaleza y pasó á cuchillo á sus habitantes.\"},{\"heading\":false,\"text\":\"Al fin, deseoso el rey Ismail de poner término á tantos desastres, y no lográndolo por medio de las armas, envió embajadores al rey de Castilla, y con gran dificultad se pactó una tregua de cierto tiempo por entrambas partes, quedando esceptuada de la tregua la frontera de Jaen, que quedó abierta á la guerra.\"},{\"heading\":false,\"text\":\"Aprovechando esta circunstancia los campeadores de Granada, entraron por la parte de Jaen, causaron gran daño á los cristianos, prendieron al adelantado Castañeda, y le llevaron en triunfo á Granada.\"},{\"heading\":false,\"text\":\"Ismail, entretanto, aprovechando la tregua, gobernaba en justicia á sus vasallos, plantaba arbolados, mejoraba los edificios y casas de campo que la guerra habia maltratado, y entretenia á sus caballeros con justas y torneos, entrando algunas veces en sus parejas, y luciendo su maestria en manejar el caballo.\"},{\"heading\":false,\"text\":\"Tenia dos hijos. El mayor era ya mancebo y se llamaba Cid Abul-Hhacem, muy buen caballero, valiente y animoso. El menor Cid Abd-Allah. El príncipe Abul-Hhacem, deseoso de manifestar su valor en alguna jornada contra los cristianos, sin respetar la tregua que su padre tenia con ellos, cayó con un escuadron de caballería, escogida sobre la frontera de Andalucía, robó ganados en la comarca de Estepa, y cautivó y mató los habitantes de las aldeas.\"},{\"heading\":false,\"text\":\"Salieron contra él los fronteros de Osuna, y despues de una reñida pelea, le fué preciso al príncipe Abul-Hhacem, abandonar la presa para volverse á Granada.\"},{\"heading\":false,\"text\":\"El año de ochocientos sesenta y cinco[112], hizo el príncipe otra correría que le fué mas útil y menos peligrosa. Pero entretanto, los cristianos acaudillados por el duque de Medinasidonia tomaron á Gibraltar, y por otra parte don Pedro Giron tomó la fortaleza de Archidona.\"},{\"heading\":false,\"text\":\"Estas pérdidas obligaron de nuevo al rey Ismail, á pedir treguas al de Castilla, y al fin los dos reyes se vieron en la vega, y trataron amistosamente y comieron juntos en una magnífica tienda el año ochocientos sesenta y ocho[113], y despues de haber cambiado algunos ricos presentes, pactaron unas paces sólidas de tal modo, que los caballeros de Granada entraban y salian libremente en la corte de Castilla, y de igual modo los cristianos en la de Granada.\"},{\"heading\":false,\"text\":\"Ismail, en fin, acabó pacíficamente su reinado, muriendo en el alcázar de Almería el año ochocientos sesenta[114].\"},{\"heading\":false,\"text\":\"Al rey Ismail, sucedió su hijo Muley Abul-Hhacem.\"}]},{\"title\":\"La torre de los siete suelos. — capítulo XV\",\"blocks\":[{\"heading\":false,\"text\":\"Hasta aquí la cronología de los reyes de Granada, desde el rey Abul-Walid Abu-Sayd, hasta Muley Abul-Hhacem.\"},{\"heading\":false,\"text\":\"La historia de éste, la de su hermano Abd-Allah-el-Zagal, y de su hijo Abd-Allah (Boabdil), será la introduccion de la leyenda siguiente, última de nuestro libro.\"},{\"heading\":false,\"text\":\"Nuestros lectores nos perdonarán si les hemos robado algunas páginas de novela para copiar las crónicas moras de los reyes de Granada: pero nosotros hemos creido que tratándose de la Alhambra, debiamos dar á conocer á todos los reyes que se sentaron en su trono.\"}]},{\"title\":\"El patio de los leones. — capítulo I\",\"blocks\":[{\"heading\":false,\"text\":\"El patio de los Leones del alcázar de la Alhambra es la joya mas rica que ha sobrevivido á la ya centenares de años hace pasada arquitectura árabe.\"},{\"heading\":false,\"text\":\"En vano querreis dominar un sentimiento de doloroso entusiasmo, al ver de repente desde el magnífico arco festonado que sirve de entrada al patio de los Leones, yendo del del Mexuar, ó de los Arrayanes, las ciento veinticuatro esbeltas y bellísimas columnas que sostienen sus galerías y sus templetes, sus arcos apuntados ó redondos, de herradura ó semicirculares, estucados labrados, cubiertos de inscripciones bajo aleros de alerce tallados, pero áridos, secos, rotos, torcidos por el tiempo: la gran pila de su fuente de mármol, sostenida por doce leones, y sus estanques de mármol, por donde corre el agua de la fuente[115].\"},{\"heading\":false,\"text\":\"Vereis sus caprichosas y elegantes arcadas, enrojecidas por el tiempo, que ha borrado sus colores, su oro, sus menudos dibujos; los puntales de madera y las barras de hierro que sostienen los aéreos templetes para que no se vengan á tierra; las magníficas ensambladuras de sus techos, agujereadas, convertidas en una ruina miserable, rotos sus alicatados y su pavimento, y sin embargo hermoso todavía.\"},{\"heading\":false,\"text\":\"¿Por qué maldicion incomprensible se deja á esa joya abandonada sin defensa á la implacable y destructora accion del tiempo, que ciego y fatal pulveriza del mismo modo lo hermoso y lo deforme?\"},{\"heading\":false,\"text\":\"¿No merece la Alhambra que se gaste en ella algun oro, que se la cure, en una palabra, que se la devuelva su lozana juventud?\"},{\"heading\":false,\"text\":\"¿Esta realidad, superior á los encarecimientos de las Mil y una Noches, á los ponderados palacios del califa Aarum-al-Raschid?\"},{\"heading\":false,\"text\":\"Pero recordamos que ya en este libro hemos declamado á propósito de la ruina de otros lugares de la Alhambra.\"},{\"heading\":false,\"text\":\"Y como nuestras declamaciones no han de dar resultado.....\"},{\"heading\":false,\"text\":\"Continuemos.\"},{\"heading\":false,\"text\":\"Adheridos al patio de los Leones hay tres departamentos.\"},{\"heading\":false,\"text\":\"La sala de las dos Hermanas á la izquierda.\"},{\"heading\":false,\"text\":\"La de los Abencerrajes, ó de los Leones, á la derecha.\"},{\"heading\":false,\"text\":\"Y al fondo la admirable sala de Justicia.\"},{\"heading\":false,\"text\":\"En la galería que existe entre el patio y la sala de Justicia, y en su estremo derecho, hay una puerta pequeña que sirve de entrada á lo que fué _rauda_ ó pendon de los reyes de Granada.\"},{\"heading\":false,\"text\":\"Todas estas habitaciones con sus dependencias, forman el departamento, por decirlo así, del patio de los Leones.\"}]},{\"title\":\"El patio de los leones. — capítulo II\",\"blocks\":[{\"heading\":false,\"text\":\"La sala de las dos Hermanas es uno de los retretes mas suntuosos y mejor conservados del alcázar.\"},{\"heading\":false,\"text\":\"Llámase de las dos Hermanas, porque en su pavimento tiene dos jigantescas losas exactamente iguales.\"},{\"heading\":false,\"text\":\"Los alicatados, los adornos de los cuatro arcos, uno de los cuales la da entrada, dos corresponden á alcobas, y otro da paso al hechicero, al incomparable mirador de Lindaraja[116], son tan lindos, tan bellos, las paredes tan armónica, tan deliciosamente ornamentadas, tan caprichosas sus cenefas, tan magestuosa, tan variada, tan caprichosa su cúpula de estaláctitas, sostenida sobre veinticuatro columnas, entre las cuales se abren ajimeces calados; tan poética, tan misteriosa la luz que la inunda, que mas bien que una obra de los hombres parece el sueño realizado de un poeta[117].\"},{\"heading\":false,\"text\":\"Por el arco de frente al de entrada se pasa á una magnífica antesala, y de allí al mirador de Lindaraja.\"}]},{\"title\":\"El patio de los leones. — capítulo III\",\"blocks\":[{\"heading\":false,\"text\":\"El mirador de Lindaraja es perfectamente cuadrado, y da vista al patio que lleva su nombre, tiene un ajimez al frente y dos á cada costado.\"},{\"heading\":false,\"text\":\"Estos ajimeces son muy bajos, es decir, su alfeizar está muy poco levantado del pavimento, sin duda para que sentados sobre los almohadones se pudiese ver el valle del rio y el frontero Albaicin.\"},{\"heading\":false,\"text\":\"Ahora esto no puede verse, porque en tiempos de Cárlos V se construyó con parte de las columnas y materiales ornamentados del palacio árabe de invierno, que destruyó el _buen emperador_, por no decir otra cosa, para construir un palacio plateresco que podia muy bien haber construido en otra parte, en vez de echarse encima la calificacion de bárbaro que pueden aplicarle las artes. En vez de ese patio que hoy existe, y que se llama de Lindaraja, solo existia un jardin, y en ese jardin un adarve bajo que permitia ver la poblacion cercana.\"},{\"heading\":false,\"text\":\"Este mirador, así como la parte interior y alta de la sala de las Dos Hermanas, por la delicadeza de los adornos, por sus dimensiones, por su carácter general, por sus comunicaciones con los baños y jardines, parecian estar destinados á la mansion de las sultanas ó favoritas. Las celosías que cubren sus ajimeces, lo reducido de los retretes, su media luz lánguida, dan fundamento bastante para esta opinion.\"}]},{\"title\":\"El patio de los leones. — capítulo IV\",\"blocks\":[{\"heading\":false,\"text\":\"Frente á la sala de las Dos Hermanas, en el centro de la galería de la derecha del patio, está la cámara de los Leones, llamada hoy de los Abencerrages, en memoria del sangriento suceso que tuvo lugar en aquella sala y que consignaremos mas adelante.\"},{\"heading\":false,\"text\":\"Esta sala es muy semejante á la de las Dos Hermanas: diferénciase en que en vez de los dos arcos que tiene aquella á los costados, y que corresponden á dos alcobas ó alhamíes, tiene dos especies de cenadores sostenidos por una columna en el centro, y con techos planos de ensambladura en el interior; y en que la cúpula, en vez de ser octógona, es estrellada. Además, la fuente de la sala de las Dos Hermanas, está formada por un rebajo del pavimento, y la de los Abencerrages está levantada medio pie sobre el suyo.\"},{\"heading\":false,\"text\":\"Además, esta cámara, tal como está hoy, no tiene comunicacion con ninguna otra del alcázar.\"},{\"heading\":false,\"text\":\"En la fuente de su pavimento hay grandes manchas rojas.\"},{\"heading\":false,\"text\":\"Es tradicion, dice, que aquellas manchas rojas son el resultado de un horrible crímen.\"},{\"heading\":false,\"text\":\"Sobre aquellas manchas rojas se ha escrito la leyenda de que vamos á ocuparnos.\"}]},{\"title\":\"El patio de los leones. — capítulo V\",\"blocks\":[{\"heading\":false,\"text\":\"Granada estaba mas que nunca dividida en bandos.\"},{\"heading\":false,\"text\":\"Se acercaba la hora de que los cristianos se apoderasen al fin de aquella Alhambra tan codiciada, de aquella fortaleza cuyo dueño era el dueño de Granada, la cándida y la clara.\"},{\"heading\":false,\"text\":\"Habia en Granada tres reyes á un tiempo.\"},{\"heading\":false,\"text\":\"Uno en la Alhambra, otro en el palacio del Gallo de viento en el Albaicin, y el tercero en Málaga.\"},{\"heading\":false,\"text\":\"Era el uno el viejo rey Muley-Hhacem, hijo de Ismail.\"},{\"heading\":false,\"text\":\"El otro Muley Abu-Allah-al-Zagal[118], su hermano.\"},{\"heading\":false,\"text\":\"Y el tercero, hijo del uno y sobrino del otro, Muley Abu-Abd-Allah-al-Ssagir-al-Zogoibí[119], conocido mas vulgarmente por Boabdil, ó por el rey Chico de Granada.\"},{\"heading\":false,\"text\":\"Estos sobrenombres eran cosa de los bandos, para conocer á cada uno de los reyes.\"},{\"heading\":false,\"text\":\"Llamaban á Muley-Hhacem, el Viejo: á Muley Abd-Allah, el Mozo: á Muley Abu-Ebn-Allah el Chico.\"},{\"heading\":false,\"text\":\"Esto era muy cómodo, porque no podian equivocarse.\"}]},{\"title\":\"El patio de los leones. — capítulo VI\",\"blocks\":[{\"heading\":false,\"text\":\"La muerte del rey de Castilla, Enrique IV; la reunion de las dos coronas de Aragon y Castilla, por el casamiento de Isabel I y Fernando V; el formidable carácter del rey de Granada Abul-Hhacem, y la desunion de sus vasallos, habian marcado al momento en que debia sucumbir Granada.\"},{\"heading\":false,\"text\":\"Añadíanse otras ambiciones secundarias á las del hermano y el hijo de Muley-Hhacem, y otras rivalidades terribles.\"},{\"heading\":false,\"text\":\"Estas ambiciones eran las de dos hijos de Abul-Hhacem, llamados los infantes Cidí Yahye y Cidí Al-Hhamar, hijos de una renegada cristiana que Abul-Hhacem habia cautivado en su juventud en la frontera de Martos, por lo que habia repudiado á su prima la sultana Aixa-la-Horra[120], lo que habia establecido odios y banderías entre las dos sultanas, Aixa-la-Horra y Zoraya[121] la renegada[122].\"},{\"heading\":false,\"text\":\"Ayudaba la poderosa familia de los zegríes á la sultana Zoraya: la no menos poderosa de los abencerrages, á la Horra: los Zenetes, los Masamudes, los Mazas, los Gomeles, todas las familias, en fin, estaban entre sí enemistadas y divididas.\"},{\"heading\":false,\"text\":\"Los Reyes Católicos eran demasiado políticos para no volver en su provecho estas disensiones de Granada, y á su advenimiento al trono, al pretender Muley-Hhacem ratificar con ellos las treguas que habian tenido con Enrique IV, Fernando é Isabel le habian impuesto como condicion, que se confesase su vasallo y les pagase tributo.\"},{\"heading\":false,\"text\":\"La respuesta de Muley-Hhacem fué altiva y dura.\"},{\"heading\":false,\"text\":\"«Id y decid á vuestros reyes, dijo á los embajadores castellanos que habian ido á hacerle tal proposicion, que ya murieron los reyes de Granada que pagaban tributo á los cristianos, y que en Granada no se labra sino alfanges y lanzas contra nuestros enemigos.»\"},{\"heading\":false,\"text\":\"Dicho esto despidió á los embajadores y mandó hacer los preparativos para una guerra con Castilla, á pesar de que los Reyes Católicos concedieron la tregua sin otra condicion.\"},{\"heading\":false,\"text\":\"Pero no tardó él mismo en romperla: en el año de ochocientos ochenta y seis[123], aprovechando el descuido de los cristianos en la frontera, entró por ella á sangre y fuego; se puso sobre Zahara, villa situada entre Ronda y Medina Sidonia, y á pesar de que estaba bien guarnecida, la sorprendió durante las tinieblas de una noche oscurísima y tempestuosa, en que se desplomara el aguacero y bramaba el huracan. Los cristianos, á quienes la tregua y lo tempestuoso de la noche, hacian creerse seguros, despertaron despavoridos y pasaron del sueño á la muerte.\"},{\"heading\":false,\"text\":\"Al regresar Muley-Hhacem á Granada y en medio de los plácemes de sus cortesanos, dicen que el anciano fakí Al-Macer dijo con sobrado valor al salir del alcázar:\"},{\"heading\":false,\"text\":\"--«¡Las ruinas de Zahara caerán sobre nuestras cabezas! ¡Ojalá mienta yo, que el ánimo me dá que el fin y acabamiento de nuestro señorío en España es ya llegado!»\"},{\"heading\":false,\"text\":\"A pesar de esto, el rey Abul-Hhacem sin hacer caso de los alimes[124] y de los fakies[125] seguia en sus algaras y cabalgadas y amagaba á las villas fronterizas aunque no podia tomarlas, porque los cristianos, con el escarmiento de Zahara, estaban prevenidos, contentándose con talar la tierra y cautivar y robar lo que encontraba de muros afuera.\"},{\"heading\":false,\"text\":\"No se hizo esperar mucho tiempo la venganza de los cristianos por la desgracia de Zahara. A principios del año de ochocientos ochenta y siete[126], don Rodrigo Ponce de Leon, señor de Marchena, con gentes de Sevilla, se encaminó á la frontera con el bravo intento de tomar la ciudad de Alhama: á media legua de la ciudad, se detuvo con sus ginetes y peones en unos profundos valles rodeados de recuestos y collados muy altos, y oculto en aquel lugar esperó á la noche; cuando esta hubo llegado, y por cierto densa y oscura, se encaminaron á Alhama, y como al acercarse notasen que todo estaba tranquilo en el castillo, algunos de los cristianos pusieron con gran silencio escalas á la muralla, subieron con gran ánimo á ella, mataron los centinelas que encontraron dormidos, abrieron las puertas que daban al campo, y dieron entrada al resto de sus gentes. Los moros, sorprendidos por aquella hazaña, resistieron muy poco, y los mas se salieron del castillo, bajaron á la ciudad y cerraron sus puertas, procurando defenderse con palizadas y barreras.\"},{\"heading\":false,\"text\":\"A la venida del dia, los cristianos emprendieron el asalto; pusieron escalas por diferentes puntos, y á pesar de que los moros se defendian bravamente, los cristianos, aunque á costa de una gran mortandad, lograron penetrar en Alhama.\"},{\"heading\":false,\"text\":\"El combate duró todo el dia y parte de la noche.\"},{\"heading\":false,\"text\":\"Los moros se defendian de calle en calle, en las que hacian barreras con los muebles, con las puertas, con los carros, con cuanto encontraban á mano; pero la llegada de un refuerzo de cristianos, decidió en favor de estos la victoria.\"},{\"heading\":false,\"text\":\"Los moros fueron casi en su totalidad degollados.\"},{\"heading\":false,\"text\":\"Las mugeres, los viejos y los niños, que se habian acogido como débiles é inermes á la mezquita principal, fueron muertos sin compasion, y casas y calles y mezquitas solo mostraban cadáveres.\"},{\"heading\":false,\"text\":\"La venganza que los cristianos tomaron por el desastre de Zahara, fué completa y horrible.\"},{\"heading\":false,\"text\":\"La noticia de este desastre llenó de luto á Granada, los fakies cruzaban por las plazas y por las calles llorando á voces y pronunciando las mas terribles y funestas profecías: el pueblo estaba espantado, y aumentaba el espanto la llegada de los habitantes de las villas fronterizas que venian desalados á encerrarse en Granada con sus haberes, temerosos de una suerte igual á la de Alhacen.\"},{\"heading\":false,\"text\":\"Pero Muley-Hhacem no se aterró; reunió de golpe tres mil caballos y cincuenta mil peones y marchó sobre Alhama, pero con la precipitacion se habia olvidado de llevar artillería y no pudo recobrar la ciudad.\"},{\"heading\":false,\"text\":\"Mas adelante volvió á cercar á Alhama, y ya casi estaba á punto de rendirse cuando le avisaron de que su presencia era necesaria en Granada.\"},{\"heading\":false,\"text\":\"Su hijo y su hermano se le habian rebelado cada cual por su parte, y era llegado el momento en que los bandos interiores no le dejasen tiempo ni fuerza para atentar á la defensa de sus fronteras.\"}]},{\"title\":\"El patio de los leones. — capítulo VII\",\"blocks\":[{\"heading\":false,\"text\":\"Entretanto los cristianos tomaron á Loja, y mientras Muley-Hhacem fué á su socorro, su hijo Boabdil, ayudado por su bando, se rebeló abiertamente en Granada proclamándose rey; los vasallos leales del rey acudieron á su defensa, acaudillados por el wazir y por el walí de la ciudad: hubo un reñidísimo combate en las calles, y los rebeldes lograron apoderarse del Albaicin. El populacho ansioso de novedades y trastornos, se declaró por el hijo y desbarató á los que venian con gentes á nombre de su padre. En vano algunos buenos caballeros pretendian restablecer la paz: el rey Muley-Hhacem, dejando lo de Loja acudió á Granada, y ayudado por su hermano el infante Zelim walí de Almería, pudo recobrar la Alhambra á escepcion de una torre que defendia el alcaide Aben-Comixa, que despues fué wazir de Boabdil.\"},{\"heading\":false,\"text\":\"Con estas ventajas el rey viejo y el infante su hermano, se atrevieron á bajar á la llanura, pero fueron desbastados.\"},{\"heading\":false,\"text\":\"Encastillados el rey Chico y el rey Viejo, el uno en el Albaicin, el otro en la Alhambra, cansados de matarse sus parciales, se suspendieron los horrores de la guerra civil, pero sin ceder el padre ni el hijo.\"},{\"heading\":false,\"text\":\"Abul-Hhacem desesperado, y viendo que entretanto Loja se perdia, marchó de nuevo en su socorro, pero apenas salió de la Alhambra, cuando se apoderó de ella el alcaide Aben-Comixa y la entregó al rey Boabdil. Entretanto su padre hacia levantar el sitio de Loja á los cristianos.\"},{\"heading\":false,\"text\":\"Pero si Abul-Hhacem habia recobrado á Loja, habia perdido á Granada.\"},{\"heading\":false,\"text\":\"Boabdil habia sido proclamado rey.\"},{\"heading\":false,\"text\":\"Abul-Hhacem, no pudiendo hacer otra cosa, por consejo de su hermano Abdalá-al-Zagal, se retiró á Málaga, que con Guadix era de su alcaidia, y se mantuvieron fieles al rey.\"}]},{\"title\":\"El patio de los leones. — capítulo VIII\",\"blocks\":[{\"heading\":false,\"text\":\"Al fin, despues de desastrosos hechos civiles, en que cada dia se insurreccionaban las salas de Granada, y mientras el ejército de los castellanos acometian las fronteras, el rey Muley-Hhacem, viejo ya y achacosa, cedió la corona á su hermano Abdallah-al-Zagal.\"},{\"heading\":false,\"text\":\"Su hijo, que habia sido hecho cautivo por los cristianos en la batalla de Lucena.\"},{\"heading\":false,\"text\":\"La sultana Aixa-la-Horra, pedia su auxilio á los Reyes Católicos, y estos se lo concedian, mas porque Boabdil fuese á turbar con la guerra civil á Granada y á debilitarla, que por otra razon.\"},{\"heading\":false,\"text\":\"Boabdil, con la ayuda de los cristianos, se apoderó del Albaicin y despues de la Alhambra.\"},{\"heading\":false,\"text\":\"Su tio Abdallah-al-Zagal se retiró á Málaga y Almería.\"},{\"heading\":false,\"text\":\"Y siguió la guerra civil.\"},{\"heading\":false,\"text\":\"Y siguieron los cristianos adelantando en las fronteras.\"},{\"heading\":false,\"text\":\"Al fin Boabdil firmó una alianza con los Reyes Católicos, declarándose su vasallo.\"},{\"heading\":false,\"text\":\"Los Reyes Católicos, que ya se habian apoderado de Málaga ayudando á Boabdil contra su tio, se apoderaron de Baza, despues de un largo sitio.\"},{\"heading\":false,\"text\":\"Aterrado Al-Zagal con la pujanza de los cristianos, se presentó á la merced de los Reyes Católicos, firmó con ellos perpétua alianza, se declaró su vasallo, y les entregó sus ciudades de Guadix y Almería.\"},{\"heading\":false,\"text\":\"Los Reyes Católicos ofrecieron en cambio al Zagal la taa de Andarax y el valle de Alhaurin con todas sus alquerías y la mitad de las salinas de Maleha.\"},{\"heading\":false,\"text\":\"Rindiéronse asimismo las fortalezas de Taberna y Seron en el interior y las marinas de Almunekab y Jalubania, todo lo cual aconteció el año ochocientos noventa y seis[127].\"}]},{\"title\":\"El patio de los leones. — capítulo IX\",\"blocks\":[{\"heading\":false,\"text\":\"Quedaba, pues, único señor del reino, pero de un reino deshecho, despedazado por los bandos civiles y casi destruido, el rey Boabdil.\"},{\"heading\":false,\"text\":\"En tales tiempos está consignada la tradicion del patio de los Leones que vamos á referir á nuestros lectores despues de los antecedentes descriptivos é históricos que hemos creido necesarios.\"}]},{\"title\":\"El patio de los leones. — capítulo X: La sultana zoraida.\",\"blocks\":[{\"heading\":false,\"text\":\"Era esta desgraciada una joya de Dios.\"},{\"heading\":false,\"text\":\"Apenas habia cumplido veinte primaveras, y ya sus dias eran tristes y sus noches sin sueño.\"},{\"heading\":false,\"text\":\"¿Quién podrá encarecer su blancura, mas intensa que la de la plata vírgen, ni quién sus cabellos dorados como el oro de Arabia?\"},{\"heading\":false,\"text\":\"Sus ojos eran azules como el cielo despejado de una tarde de primavera, y sus pupilas negras como una noche de tempestad.\"},{\"heading\":false,\"text\":\"Y como de la tempestad salen los relámpagos, de las negras pupilas de Zoraida salian tambien relámpagos de amor.\"},{\"heading\":false,\"text\":\"¿Por qué aquella hurí mortal, aquel ramillete de perfeccion estaba triste y silenciosa, sentada en la fresca y embalsamada sala de los Divanes[128]?\"},{\"heading\":false,\"text\":\"LETRE dibº y litº Lit. de J. J. Martinez, Madrid]\"},{\"heading\":false,\"text\":\"¿Por qué las lágrimas corrian lentas é incesantes á lo largo de sus megillas?\"},{\"heading\":false,\"text\":\"¡Ay! Zoraida en aquella maravillosa cámara era una garza real aprisionada en una jaula de oro y pedrería.\"},{\"heading\":false,\"text\":\"Y como la garza desde su encierro recuerda los anchos espacios, y el magnífico espectáculo de la tierra vista desde las alturas, y al recordarlo inclina apenada la cabeza, así Zoraida recordaba otros espacios en que se habia remontado su alma hasta el cielo del amor y de la felicidad.\"},{\"heading\":false,\"text\":\"¿Qué se habian hecho sus sueños?\"},{\"heading\":false,\"text\":\"Habian desaparecido quemados por el beso impuro de Boabdil.\"},{\"heading\":false,\"text\":\"En mal hora su padre la habia arrebatado del silencioso alcázar de Málaga en donde pasó su infancia, arrullada por el canto de su nodriza y de sus doncellas.\"},{\"heading\":false,\"text\":\"En mal hora la llevó á Granada.\"},{\"heading\":false,\"text\":\"Y en dia de muerte la llevó á los miradores de Bib-Arrambla, para que con ocasion de unas cañas y torneos, sortijas y toros, fuese admirada y vista su hermosura por los caballeros granadinos.\"},{\"heading\":false,\"text\":\"Y por el rey Boabdil.\"},{\"heading\":false,\"text\":\"Y por el abencerrage Ebn-Ahmed.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Boabdil habia sido su esposo.\"},{\"heading\":false,\"text\":\"Ebn-Ahmed se habia atrevido á dirigirla primero miradas, y luego suspiros, y al fin palabras de amor.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"¡Oh, y cuán ardientes, cuán tristes, cuán apenadores eran los recuerdos de la sultana Zoraida!\"},{\"heading\":false,\"text\":\"Una lámpara de oro incrustada en nácar, enviaba al semblante de Zoraida una ténue y dulce claridad que brillaba en sus lágrimas.\"},{\"heading\":false,\"text\":\"Era muy tarde, y la sultana no habia dormido.\"},{\"heading\":false,\"text\":\"Era cerca del amanecer.\"},{\"heading\":false,\"text\":\"Los guardas de la muralla de la Alhambra, rendidos al sueño, no dejaban oir su grito de vigilancia: todo reposaba en el alcázar.\"},{\"heading\":false,\"text\":\"Sin embargo, por el adarve del jardin del mirador de Lindaraja, se veian alejarse dos sombras hácia un ángulo de la muralla: á la dudosa luz del alba que empezaba á esclarecer, se notaba que la una sombra era un hombre, la otra una muger.\"},{\"heading\":false,\"text\":\"Al llegar á aquel ángulo, la muger desenvolvió una escala y la arrojo á fuera.\"},{\"heading\":false,\"text\":\"--El dia viene, dijo al hombre: por fortuna he podido alejar á los guardas: aprovecha este momento para alejarte, walí: recuerda que no es tu vida la que espones, sino la vida y la honra de una desdichada.\"},{\"heading\":false,\"text\":\"--De un arcángel de muerte, murmuró con voz ronca el hombre.\"},{\"heading\":false,\"text\":\"-¡Ah! ¡infeliz!... ¡infeliz de ella! ¿olvidas que es esposa de Boabdil?\"},{\"heading\":false,\"text\":\"--¡Oh! ¡si me amara, qué importan la muerte y la deshonra, y los tormentos, á trueque de un instante de felicidad!...\"},{\"heading\":false,\"text\":\"--Vete, vete, walí Ebn-Ahmed; ¡si los guardas volvieran!...\"},{\"heading\":false,\"text\":\"--He subido por esta escala con la alegría del sol que sale, y la bajo con la tristeza del sol que se pone: yo habia esperado ver mi cielo; pero mi cielo ha estado nublado para mí.\"},{\"heading\":false,\"text\":\"--Oye, walí, y espera y alienta tu esperanza... mi señora me ha dicho para tí estas palabras:\"},{\"heading\":false,\"text\":\"«Esta noche en Generalife, al pie del ciprés de Abul-Walid.»\"},{\"heading\":false,\"text\":\"--¡Ah!\"},{\"heading\":false,\"text\":\"--Vete, pues.\"},{\"heading\":false,\"text\":\"--¡Otro dia!\"},{\"heading\":false,\"text\":\"--Un dia de hermosa esperanza, y despues... una noche de felicidad.\"},{\"heading\":false,\"text\":\"--¡Og-allah![129] esclamó Ebn-Ahmed; y arrancándose una joya la entregó á la esclava, y se deslizó por la escala.\"},{\"heading\":false,\"text\":\"Cuando la escala perdió su fuerte tension, señal clara de que el que habia descendido por ella habia tomado tierra, la muger la recogió.\"},{\"heading\":false,\"text\":\"Luego se inclinó sobre el adarve y escuchó atentamente.\"},{\"heading\":false,\"text\":\"Poco despues, allá á lo lejos, pasando por un puente del Darro, y trepando por la vecina cuesta del Chapiz, se escuchó el sonoro galope de un caballo.\"}]},{\"title\":\"El patio de los leones. — capítulo XI: El sultan boabdil.\",\"blocks\":[{\"heading\":false,\"text\":\"Granada estaba amenazada.\"},{\"heading\":false,\"text\":\"Los Reyes Católicos, despues de haber conquistado las principales villas y ciudades del reino, habian acampado delante de Granada, llevando consigo la flor de sus caballeros.\"},{\"heading\":false,\"text\":\"Y delante de Granada, en la vega, habian levantado su ciudad real.\"},{\"heading\":false,\"text\":\"La ciudad de Santa-Fé.\"},{\"heading\":false,\"text\":\"Un dia aquella ciudad, que solo habia sido antes un real, apareció cercada de muros.\"},{\"heading\":false,\"text\":\"Cuando aquello vieron los moros desde la Alhambra, se maravillaron porque la tarde antes no existian aquellos muros, y no podian comprender cómo se habian levantado en una sola noche.\"},{\"heading\":false,\"text\":\"Aquello era una industria de los cristianos.\"},{\"heading\":false,\"text\":\"Por ella se cantó aquel romance que dice:\"},{\"heading\":false,\"text\":\"Cercada está Santa-Fé de mucho lienzo encerado.\"},{\"heading\":false,\"text\":\"Pero muy pronto los muros de lienzo se convirtieron en muros de piedra, y el real de los Reyes Católicos se convirtió en ciudad.\"},{\"heading\":false,\"text\":\"Y á pesar de que aquella ciudad con sus muros, sus torres y su caba, se levantaba delante de Granada, el rey Boabdil dormia como si hubiese estado completamente en paz con los cristianos.\"},{\"heading\":false,\"text\":\"Dormia en el mirador de Lindaraja entre los brazos de una esclava.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Lentamente la luz del dia fué creciendo, y la esclava despertó, se envolvió en su túnica y se sentó en el diván.\"},{\"heading\":false,\"text\":\"Poco despues de la aparicion del alba, un ronco son de atakebiras, dulzamas y atavales rasgó el espacio, y cuando cesó este clamor guerrero, se escuchó la voz del mueden de la mezquita del alcázar que llamaba á la oracion de Azzobih.\"},{\"heading\":false,\"text\":\"Boabdil se levantó, sonrió á la esclava, y fué á hacer su ablucion á la fuente de la sala de las Dos Hermanas.\"},{\"heading\":false,\"text\":\"Despues se prosternó con el rostro vuelto al oriente, y oró un momento.\"},{\"heading\":false,\"text\":\"Luego fué al diván, se reclinó en él indolentemente é hizo una seña á su esclava.\"},{\"heading\":false,\"text\":\"Esta se levantó y fué á una puerta.\"},{\"heading\":false,\"text\":\"Salió, y poco despues entraron otras cuatro hermosísimas esclavas.\"},{\"heading\":false,\"text\":\"La una traia un arquilla llena de perfumes y aguas olorosas, la otra una fuente de oro, la otra un espejo, la otra una rica tohalla.\"},{\"heading\":false,\"text\":\"Las esclavas se arrodillaron, y luego se apoderaron del rey y le ataviaron.\"},{\"heading\":false,\"text\":\"Despues se retiraron las esclavas, y entraron cuatro walíes escuderos del rey.\"},{\"heading\":false,\"text\":\"Le armaron; pusiéronle su manto de púrpura sobre los hombros, la espada al costado, y la corona en la cabeza.\"},{\"heading\":false,\"text\":\"Despues el rey se trasladó á la cámara de Embajadores y recibió á su corte.\"},{\"heading\":false,\"text\":\"En el patio del Mexuar ondeaba su estandarte.\"},{\"heading\":false,\"text\":\"Los caballeros que le rodeaban, estaban cubiertos de resplandecientes arneses.\"},{\"heading\":false,\"text\":\"¿Salia Boabdil contra los cristianos?\"},{\"heading\":false,\"text\":\"No: iba á una fiesta de cañas en Bib-Arrambla.\"}]},{\"title\":\"El patio de los leones. — capítulo XII: Las cañas se vuelven lanzas.\",\"blocks\":[{\"heading\":false,\"text\":\"¡Cuán engalanada se muestra la plaza!\"},{\"heading\":false,\"text\":\"Parece que los bosques la han enviado sus aves, las praderas sus flores, sus sedas Damasco, sus púrpuras Tiro, sus resplandores Oriente.\"},{\"heading\":false,\"text\":\"Damas de hermosura, mas resplandeciente que sus resplandecientes galas, ocupan ventanas y balconcillos y miradores y estrados, y parecen un cielo que se mueve y gira y brilla agitando sus ventales de plumas y pedrería.\"},{\"heading\":false,\"text\":\"Y los galanes, mezclados con las damas, dejan ver sus aljubas verdes en señal de esperanza, labradas de oro fino y de perlas, y sus bonetes con plumas, cada cual del color de su dama.\"},{\"heading\":false,\"text\":\"Y hay entre muchas de aquellas toca, trenzas rubias y trenzas negras, prendas de amor; y lazos de oro en las mangas de las aljubas con motes de amor, y cadenas de amor al cuello de muchos caballeros.\"},{\"heading\":false,\"text\":\"Y á los pies de ventanas y miradores mas allá de los estrados, está la estendida tela[130], en que brilla apisonada la blanca y menuda arena del Genil.\"},{\"heading\":false,\"text\":\"Y al rededor de la tela las barreras de colores, con sus poternas de hierro dorado, y entre las barreras y los estrados, los africanos de la guardia del rey con sus armaduras doradas, sus capellares rojos y sus relucientes bonetes de acero, con plumas que ondean al viento.\"},{\"heading\":false,\"text\":\"Y allá al fondo de la tela está el trono del señor rey, con su cortina de púrpura bordada de oro y sembrada de estrellas de rubíes, con el blason de Al-Hhamar el Nazerí campeando en el centro, y que parece como empalidecido, como empañado al verse en un lugar de fiestas en vez de encontrarse delante del real de los cristianos que cercan á Granada.\"},{\"heading\":false,\"text\":\"Boabdil es un rey insensato.\"},{\"heading\":false,\"text\":\"Insensatas son esas damas, que están cubiertas de joyas, lazos y galas.\"},{\"heading\":false,\"text\":\"Insensatos esos mancebos, que enamoran cuando debian cabalgar contra el castellano.\"},{\"heading\":false,\"text\":\"Solo los fakís prosternados en la mezquita esclaman:\"},{\"heading\":false,\"text\":\"_¡Allah ku Akbar! ¡Allah ku Rhhaman! ¡Le galib ile Allah!_[131]\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Entretanto el rey ocupa su trono en Bib-Arrambla[132], y junto á él, pálida, triste y pensativa se asienta la sultana Zoraida, y delante las sultanas de la familia real[133], y mas abajo las favoritas y luego las esclavas.\"},{\"heading\":false,\"text\":\"Y detrás del trono los wazires, y los alcaides, y los kadies, y los valies, y los alimes, y los xeques.\"},{\"heading\":false,\"text\":\"Una aclamacion herida hiende los aires porque el rey ha hecho una seña con su lenzuelo y van á empezar las fiestas.\"},{\"heading\":false,\"text\":\"Un solo caballero vé con espresion sombria la seña del rey, y escucha con despecho el tañido de los instrumentos músicos y de guerra que llaman á las cuadrillas.\"},{\"heading\":false,\"text\":\"Está de pié á la derecha del rey, y tiene desnuda la ancha espada en que se apoya.\"},{\"heading\":false,\"text\":\"Es el único que no lleva galas, y que en vez de una ligera armadura dorada, como la que llevan los otros caballeros, se encuentra armado con un fuerte arnés de guerra de Milán.\"},{\"heading\":false,\"text\":\"En la barrera sus pajes tienen del diestro un bravo corcél encubertado de batalla, y sus escuderos mantienen la gruesa y larga lanza, la ancha y redoblada adarga de siete aceros, y el ferrado yelmo de encage.\"},{\"heading\":false,\"text\":\"Es jóven: en la fuerza de su juventud.\"},{\"heading\":false,\"text\":\"La magestad irradia de su alta y serena frente.\"},{\"heading\":false,\"text\":\"En sus negros ojos brilla un valor bravio.\"},{\"heading\":false,\"text\":\"En su boca aparece una sonrisa de valor y de desprecio.\"},{\"heading\":false,\"text\":\"Aquel mancebo es el infante Muza-Ebn-Abil-Gazan: el valiente de Granada, hijo de Muley Hhacem y de una esclava cristiana, hermano bastardo de Boabdil, indomable y vencedor alcaide de su caballería.\"},{\"heading\":false,\"text\":\"Cuando Muza cabalga en la vega contra los cristianos llevando tras sí las innumerables taifas de ginetes de Granada tras su bandera roja, allá vá el huracan.\"},{\"heading\":false,\"text\":\"Cuando salen á su encuentro Gonzalo de Córdoba, ó el Alcaide de los Donceles, ó el conde de Cabra, ó Hernan Perez del Pulgar con sus lanzas castellanas, parece que chocan dos montañas de acero lanzadas la una contra la otra por la mano de Dios.\"},{\"heading\":false,\"text\":\"Cuando entre los suyos está pálido, sombrio y ceñudo, los suyos tiemblan.\"},{\"heading\":false,\"text\":\"Muza está pálido: sus ojos centellean, su negra barba tiembla.\"},{\"heading\":false,\"text\":\"Su robusta mano empuña convulsivamente el pomo de su espada.\"},{\"heading\":false,\"text\":\"Su vista se fija en la puerta de Al-Bonut[134].\"},{\"heading\":false,\"text\":\"Por allí entran lucidas cuadrillas de zegríes.\"},{\"heading\":false,\"text\":\"A su frente, altivo, provocador, insolente, viene oprimiendo los lomos de un tordo rodado, Mahomet Zegrí, alcaide de la alcazaba Kadima, cubierto de galas rojas y arrastrando rojas gualdrapas: llevaba pintado en su adarga un salvaje sosteniendo un mundo, y por bajo este jactancioso mote: _Con mas puedo._\"},{\"heading\":false,\"text\":\"Su moreno semblante africano se volvió hacia el trono en el momento en que entró en la tela, y sonrió con sarcasmo á la sultana, con desprecio al rey, y fijó una mirada de odio y de reto en el infante Muza.\"},{\"heading\":false,\"text\":\"La sultana palideció, el rey bajó los ojos, Muza lanzó una mirada de muerte al Zegrí.\"},{\"heading\":false,\"text\":\"Seguian á Mohamet-Adel-Zegrí, de cuatro en cuatro, cien caballeros zegríes, ginetes en potros negros de pura sangre árabe.\"},{\"heading\":false,\"text\":\"Iban cubiertos de seda, sin mostrar mas que unos ligeros jacos,[135] forrados de tela de oro: sus aljubas, sus marlotas, sus almaizares, eran de brocado rojo como el de su caudillo, y sobre sus bonetes ondeaban plumas que parecian haber sido teñidas en sangre.\"},{\"heading\":false,\"text\":\"Al mismo tiempo por la puerta de Al-Kaissería, entró un hermoso mancebo, ginete en una yegua blanca, con bonete, aljuba y capellar de brocado verde, y gualdrapas de lo mismo.\"},{\"heading\":false,\"text\":\"En su adarga llevaba pintada un águila que volaba junto á un sol, y por bajo este letrero:\"},{\"heading\":false,\"text\":\"_«Mas alto vuelo.»_\"},{\"heading\":false,\"text\":\"Este caballero, que era muy hermoso, se llamaba Ahmed-Ebn-Zeragh, y era gefe de la poderosa familia de los abencerrages.\"},{\"heading\":false,\"text\":\"Seguíanle de cuatro en cuatro, ginetes como él en yeguas blancas, y como él vistiendo brocado verde, cien bravos caballeros abencerrages.\"},{\"heading\":false,\"text\":\"Los dos gefes de las dos tribus, Mahomet-Adel-Zegrí, y Aben-Ahmed-Aben-Zeragh, se unieron para ir á saludar al rey, y del mismo modo se unieron sus cuadrillas.\"},{\"heading\":false,\"text\":\"Despues del saludo, cada uno tomó por un costado de la liza: seguian á cada uno sus caballeros, y al fin los escuadrones se formaron el uno frente al otro: los abencerrages estaban á la derecha del trono, los zegríes á la izquierda: en medio la arena despejada: á una señal del rey, los escuderos de las fiestas saltaron las barreras y cargados de haces de cañas, forradas de vistosas cintas, proveyeron de ellas á los caballeros y se retiraron.\"},{\"heading\":false,\"text\":\"Entonces sonó la señal.\"},{\"heading\":false,\"text\":\"Los dos escuadrones se abrieron, desplegándose como un abanico.\"},{\"heading\":false,\"text\":\"Y caracolearon los caballos, y se mezclaron de una manera ordenada formando círculos y caprichosas combinaciones, y entrando y saliendo y remedando de una manera muy vistosa, una trabada escaramuza.\"},{\"heading\":false,\"text\":\"Y volaban las cañas, ondeando las cintas de colores, y las damas y los caballeros y el populacho y el mismo rey aplaudian y reian de muy buena gana, cuando un caballero torpe ó descuidado recibia un golpe de caña en el rostro.\"},{\"heading\":false,\"text\":\"Por una, dos y tres veces las cuadrillas quedaron sin cañas, se replegaron haciendo provision de nuevas cañas, y volvieron á juego; pero á la cuarta vez, un caballero abencerrage lanzó un grito de muerte y cayó de su yegua.\"},{\"heading\":false,\"text\":\"Algunos escuderos de los zegries habian saltado la valla y habian dado á sus dueños picas de combate.\"},{\"heading\":false,\"text\":\"Por esto se dijo el romance aquel:\"},{\"heading\":false,\"text\":\"No hay amigo para amigo; las cañas se vuelven lanzas.\"}]},{\"title\":\"El patio de los leones. — capítulo XII: La batalla.\",\"blocks\":[{\"heading\":false,\"text\":\"A aquella infame traicion de los zegríes, siguió un tumulto espantoso.\"},{\"heading\":false,\"text\":\"Los abencerrages, provistos de lanzas los unos, los otros valiéndose solo de las espadas, se revolvieron con un odio y una saña incomparables.\"},{\"heading\":false,\"text\":\"De los estrados, de las galerías, de las casas, bajaban á la liza caballeros, y aun el populacho empezaba á tomar parte, dividiéndose Granada en dos bandos.\"},{\"heading\":false,\"text\":\"El rey con la sultana, con sus mujeres, con sus consejeros, escapó y se encerró en la Alhambra.\"},{\"heading\":false,\"text\":\"El infante Muza quedó en la plaza revolviéndose entre los combatientes, y gritando para ponerlos en paz:\"},{\"heading\":false,\"text\":\"--Ved, caballeros, que tenemos á las puertas los cristianos, que el peligro arrecia, y que no es esta la ocasion de volver las armas los unos contra los otros, sino de ir juntos y alentados contra el enemigo de todos: ea, caballeros, bajad las armas, y mirad á Granada que llora: y si teneis sed de sangre, venid conmigo y busquémosla cristiana en el real de Santa-Fé.\"},{\"heading\":false,\"text\":\"Pero en vano tronaba la voz de Muza: los zegríes no obedecian y los abencerrages, que hubieran obedecido, se veian obligados á defenderse de los zegríes.\"},{\"heading\":false,\"text\":\"Entonces Muza dejó las persuasiones y apeló á la fuerza.\"},{\"heading\":false,\"text\":\"Reunió al rededor de su bandera á los africanos de la guarda del rey y á sus esclavos negros, y embistió con los zegríes.\"},{\"heading\":false,\"text\":\"Reforzados los abencerrages, se llevaron al fin por delante cuanto encontraron.\"},{\"heading\":false,\"text\":\"Los zegríes huyeron dejando sobre la plaza muchos cadáveres de los suyos, y fueron á encerrarse en el castillo de Bib-Ataubin[136].\"},{\"heading\":false,\"text\":\"Los abencerrages fueron á encerrarse con el rey en la Alhambra.\"}]},{\"title\":\"El patio de los leones. — capítulo XIV: El cipres de la sultana.\",\"blocks\":[{\"heading\":false,\"text\":\"Comprendieron los zegríes que vencidos como estaban, abandonados de todos, el rey podia hacer en ellos un terrible escarmiento.\"},{\"heading\":false,\"text\":\"Pensaron, pues, en engañar al rey.\"},{\"heading\":false,\"text\":\"La misma sultana Zoraya, la renegada á quien servian, envió á Mohamed-Adel-Zegrí, un mensagero, con el que le dijo que era necesario ganar tiempo y buscar sobre seguro otro medio de acometer al rey Boabdil.\"},{\"heading\":false,\"text\":\"La sultana Aixa-la-Horra por su parte, ayudada por el alcaide Muza, pugnaba en la Alhambra por decidir al rey á que cortase la cabeza á los traidores.\"},{\"heading\":false,\"text\":\"Pero el rey era débil y resistia.\"},{\"heading\":false,\"text\":\"Parecióle peligroso hacer justicia en unos caballeros tan turbulentos que tanto poder tenian y tan poderosos eran, y se avino á recibir á Mohamed-Adel-Zegrí.\"},{\"heading\":false,\"text\":\"El caudillo de los zegríes se esforzó por probar que un caballero zegrí que habia huido temiendo el castigo, habia sido el que por celos de una dama habia arrojado una lanza contra un abencerrage, y que el combate que despues habia seguido, habia sido una equivocacion lamentable. Que habian corrido voces en el momento de la lucha entre los zegríes de que querian destruirlos; que esto habia causado su tenaz resistencia; pero que aclarados los hechos, los zegríes no tenian el menor reparo en dar cuantas satisfacciones fueren necesarias al rey y á los abencerrages, y en renovar con ellos la antigua amistad, dando en rehenes de ella sus hijos y sus esposas.\"},{\"heading\":false,\"text\":\"Parecióle al rey bastante la satisfaccion de los zegríes, y los abencerrages sacrificaron su justo odio en favor de la patria: aquel mismo dia los cristianos habian corrido las dos leguas de vega que hay desde Santa-Fé á Granada; se habian estendido por una parte hasta la Azubia, y por otra hasta Viznar; y aldeanos y labradores habian entrado despavoridos en Granada.\"},{\"heading\":false,\"text\":\"Era, pues, necesario de todo punto la union mas estrecha entre los caballeros granadinos, el olvido de todos los odios y los esfuerzos comunes y unidos contra el enemigo comun.\"},{\"heading\":false,\"text\":\"Cedió, pues el rey por temor, cediendo los abencerrages por generosidad; concertaron una avenencia, y para celebrarla se dispuso una zambra en Generalife, donde debian echarse los lazos de una nueva amistad entre zegríes y abencerrages.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Llegó la noche.\"},{\"heading\":false,\"text\":\"Generalife estaba resplandeciente.\"},{\"heading\":false,\"text\":\"Sus cascadas corrian bajo sus verdes bóvedas de laurel, entre las que estaban escondidas jaulas con cuantos pájaros de voz armoniosa podia reunir el deseo.\"},{\"heading\":false,\"text\":\"Las lámparas de colores ardian en el oscuro fondo de las enramadas, esparciendo una dulce luz.\"},{\"heading\":false,\"text\":\"Las fuentes saltaban cruzando caprichosamente sus surtidores, bajo los que ardian mil luces.\"},{\"heading\":false,\"text\":\"Al lado de los estanques, entre los jardines, al dulce eco de la fiesta, vagaban parejas de damas y caballeros que hablaban de amor.\"},{\"heading\":false,\"text\":\"El cielo estaba plácido y tranquilo; la luna brillaba, y las frescas auras gemian entre las enramadas.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Pero habia un jardin en Generalife, en el cual no brillaban luces.\"},{\"heading\":false,\"text\":\"Unicamente la luna reflejaba en su largo estanque.\"},{\"heading\":false,\"text\":\"Un solo ruiseñor cantaba escondido en lo mas alto de un árbol jigantesco.\"},{\"heading\":false,\"text\":\"Aquel árbol era un ciprés.\"},{\"heading\":false,\"text\":\"El ciprés de Abul-Walid.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Si vais á Generalife encontrareis aun aquel jardin, aquel estanque, la antigua atarvea con flores ahora, como entonces, porque la naturaleza es mas próvida que los hombres; estos han dejado que se arruinen las galerías de estuco y mármol, los aleros, las cúpulas.... la primavera ha cuidado de cubrir cada año de flores las orillas del estanque, y cada año ha nacido una rama nueva al ciprés.\"},{\"heading\":false,\"text\":\"Cuando el _cicerone_ que os acompaña llega á aquel jardin, se detiene y os dice con un entusiasmo verdaderamente romancesco:\"},{\"heading\":false,\"text\":\"--Aquel es el Ciprés de la Sultana.\"},{\"heading\":false,\"text\":\"Y cuando os acercais á él, veis que los que han llegado primero que vos, han cortado con un entusiasmo tambien enteramente romancesco, una astilla del árbol, una especie de reliquia.\"},{\"heading\":false,\"text\":\"El ciprés, junto á su pié, á la altura de mi hombre, está roido ó mas bien desollado, por el entusiasmo de los viajeros.\"},{\"heading\":false,\"text\":\"Una tarde estaba el autor sentado, á la puesta del sol, en el pequeño jardin donde existe el ciprés.\"},{\"heading\":false,\"text\":\"Hablaba con un viejo inválido de la compañía de la Alhambra, y miraba á la altísima punta del árbol maquinalmente.\"},{\"heading\":false,\"text\":\"De improviso, viniendo de la parte de la Silla del Moro, un gran pájaro blanco se cernió un momento sobre la punta del ciprés, y se detuvo en ella.\"},{\"heading\":false,\"text\":\"--¿Qué clase de pájaro es ese, tio Juan? dijo el autor al inválido.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡ah! esclamó el viejo; es un animal muy raro: es un grajo.\"},{\"heading\":false,\"text\":\"--¡Un cuervo blanco!\"},{\"heading\":false,\"text\":\"--Si señor, un grajo cano de viejo: como que dicen que el Ciprés de la sultana tiene cuatrocientos años, y que ese cuervo es tan viejo como él.\"},{\"heading\":false,\"text\":\"--¿Quién ha dicho á V. eso, tio Juan?\"},{\"heading\":false,\"text\":\"--Mi padre se lo oyó decir á mi abuelo, que decia que se lo habia oido decir al suyo, y que el abuelo de mas allá se lo habia oido decir al de mas lejos.\"},{\"heading\":false,\"text\":\"--Vamos, esa es una noticia trasmitida de generacion en generacion: una tradicion, en una palabra.\"},{\"heading\":false,\"text\":\"--Como se sabe que la sultana que engañó al rey Chico de Granada, dejándose enamorar de un abencerrage al pie de ese árbol, era rubia y blanca, y tenia los ojos garzos y una pequeña rosa que le hacia mucha gracia, en la megilla derecha.\"},{\"heading\":false,\"text\":\"No me atreví á desmentir al tio Juan, que siguió contándome con la fé mas ciega, y como hubiera podido contarme un suceso del dia anterior, la tradicion de los amores de la sultana de Granada y del abencerrage Aben-Ahmed.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Oíase desde aquel solitario jardin, perdido y ténue á lo lejos, el concierto de la fiesta que se agitaba en Generalife.\"},{\"heading\":false,\"text\":\"El ruiseñor, escondido en el árbol, trinaba.\"},{\"heading\":false,\"text\":\"La luna brillaba en la tersa é inmóvil superficie del estanque.\"},{\"heading\":false,\"text\":\"Los bosquecillos de laureles proyectaban misteriosas penumbras.\"},{\"heading\":false,\"text\":\"La brisa de la noche volaba cargada del aroma de las flores.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Entre la oscura sombra de un bosquecillo se destacaron cuatro fantasmas blancos.\"},{\"heading\":false,\"text\":\"Eran cuatro hombres envueltos en sus almaizares.\"},{\"heading\":false,\"text\":\"Hablaban de una manera contenida.\"},{\"heading\":false,\"text\":\"Se deslizaron siempre en la sombra hácia el ciprés, y se ocultaron detrás de él en una espesura de rosales.\"},{\"heading\":false,\"text\":\"El que hubiera estado junto á ellos habria podido oir el diálogo siguiente:\"},{\"heading\":false,\"text\":\"--¿Y estas seguro, primo Mahandin, de lo que nos has confiado?\"},{\"heading\":false,\"text\":\"--Esta mañana, antes de amanecer, uno de los guardas del jardin de Lindaraja vió salir de los baños a Zaruhlemal[137], contestó el preguntado.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡la doncella favorita de la sultana! dijo otro.\"},{\"heading\":false,\"text\":\"--Con Zaruhlemal iba Aben-Ahmed. El guarda la oyó decir: Esta noche en Generalife, al pie del ciprés de Abul-Walid.\"},{\"heading\":false,\"text\":\"--¿Y no podrá ser que quien haya dado esa cita á Aben-Ahmed sea la misma Zaruhlemal?\"},{\"heading\":false,\"text\":\"--Aben-Ahmed no se hubiera espuesto por esa dama á escalar la Alhambra y á entrar en los baños del rey. No se hubiera pagado tan espléndidamente á los guardas para que se retirasen.\"},{\"heading\":false,\"text\":\"--Silencio; dijo uno de los cuatro: me parece que oigo abrir recatadamente una puerta de la galería.\"},{\"heading\":false,\"text\":\"--Ocultémonos bien, y silencio.\"},{\"heading\":false,\"text\":\"No volvieron á hablar una sola palabra.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Una muger salió de la galería y adelantó hácia el ciprés con paso tímido é irresoluto.\"},{\"heading\":false,\"text\":\"Cuando se puso bajo la luz de la luna, brilló el brocado de su túnica, y brillaron las alhajas de que venia prendida.\"},{\"heading\":false,\"text\":\"Traia cubierto el semblante con el velo.\"},{\"heading\":false,\"text\":\"Adelantó hácia el ciprés, miró en torno suyo con anhelo; se sentó al pie del árbol sobre el césped, y se descubrió echándose atras el velo.\"},{\"heading\":false,\"text\":\"Era la sultana Zoraida.\"},{\"heading\":false,\"text\":\"Estaba pálida, temblorosa, dominada por una escitacion profunda.\"},{\"heading\":false,\"text\":\"En sus magníficos ojos brillaban á un tiempo el amor, el temor, la amistad, la pureza contrariada, el orgullo comprimido.\"},{\"heading\":false,\"text\":\"Su seno, cubierto de deslumbrantes joyas, se levantaba y se deprimia.\"},{\"heading\":false,\"text\":\"Su aliento salia abrasador y fatigado, por sus entreabiertos labios.\"},{\"heading\":false,\"text\":\"Todo en ella revelaba una muger en cuyas venas latia sangre africana, a impulsos de un amor largo tiempo habia contrariado, dominado hasta el momento de la prueba.\"},{\"heading\":false,\"text\":\"Amor escondido en un delicioso misterio, cubierto por las alas del arcángel de la pureza, tranquilo hasta entonces como las aguas de un lago, profundo como el abismo, é indeleble como la marca puesta por el dedo de Dios sobre la frente de una criatura.\"},{\"heading\":false,\"text\":\"Aquel amor habia llevado hasta el pie de aquel ciprés á la sultana, de aquel funesto ciprés, mudo confidente de amores misteriosos, y allí entre un vacilante silencio, al tibio rayo de la luna, al suave y aromático aliento de las auras, que susurraban lentamente entre las flores y las enramadas, la desdichada Zoraida, recibió en el misterioso fondo de su alma la última y mas ardiente revelacion de aquel amor hasta entonces dominado, silencioso, vago, infinito que hacia mucho tiempo llenaba sus sueños.\"},{\"heading\":false,\"text\":\"Zoraida vió el abismo en el momento en que este se abria á sus pies, y quiso retroceder.\"},{\"heading\":false,\"text\":\"Quiso huir.\"},{\"heading\":false,\"text\":\"Se levantó trémula y se encaminó á la galería, pero de repente apareció junto á ella, saliendo de entre una enramada, un hombre.\"},{\"heading\":false,\"text\":\"Era Aben-Ahmed.\"},{\"heading\":false,\"text\":\"Galan, hermoso, enamorado.\"},{\"heading\":false,\"text\":\"Pretendió huir aun, pero encontró ante sus pies de rodillas al abencerrage pálido y tembloroso.\"},{\"heading\":false,\"text\":\"Y sintió sus manos asidas por otras manos convulsas, y unos labios ardientes y trémulos que besaban con delirio sus manos.\"},{\"heading\":false,\"text\":\"--¡Oh! ¿qué haces? esclamó la sultana.\"},{\"heading\":false,\"text\":\"--Desfallecer de amor, alma de mi alma, contestó el abencerraje.\"},{\"heading\":false,\"text\":\"Zoraida cayó sin fuerzas, rendida por su amor sobre el césped que rodeaba al ciprés.\"},{\"heading\":false,\"text\":\"Y entonces, cuando los dos amantes solo tenian ojos y oidos para sí mismos, los cuatro hombres que estaban ocultos tras el ciprés en la espesura, se alejaron con paso silencioso, y se perdieron á lo largo de los jardines.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Y Aben-Ahmed, entretanto, permanecia á los pies de Zoraida, y la decia fuera de sí:\"},{\"heading\":false,\"text\":\"--¡Oh! ¡bendita sea la noche que envuelve en su silencio nuestro amor! ¡bendita sea la luna que alumbra tu hermosura!\"},{\"heading\":false,\"text\":\"¡Tu frente encendida por el rubor y la agitacion de tu seno, son voces mudas que pronuncia tu alma, y que me dicen: ¡yo te amo!\"},{\"heading\":false,\"text\":\"Alza los ojos gacela, y pon tu mirada de delicias en mi mirada.\"},{\"heading\":false,\"text\":\"Ellos son la lumbre de mi vida.\"},{\"heading\":false,\"text\":\"Su fulgor, el fulgor de la estrella esplendorosa de mi destino.\"},{\"heading\":false,\"text\":\"Callaba la sultana: callaba y temblaba.\"},{\"heading\":false,\"text\":\"Aben-Ahmed enloquecia con su hermosura, y esclamaba:\"},{\"heading\":false,\"text\":\"--Sultana del amor, flor de las flores, lucero de los luceros, hurí de las huríes, rosa del paraiso, la noche nos envuelve en su silencio: huyamos: huyamos lejos de ese rey miserable y cobarde y de la ruina de Granada: salvemos nuestro amor.\"},{\"heading\":false,\"text\":\"Yo tengo en Africa alcázares.\"},{\"heading\":false,\"text\":\"Yo tengo en aquellos alcázares tesoros.\"},{\"heading\":false,\"text\":\"Yo soy el gefe de una valiente tribu.\"},{\"heading\":false,\"text\":\"De la tribu de los Beni-Zerahg.\"},{\"heading\":false,\"text\":\"Descendiente como Al-Hhamar-el-Nazerita, del Ansarí, mi estandarte verde ondea sobre las lanzas de mis bravos abencerrages.\"},{\"heading\":false,\"text\":\"Aquí la infamia nos rodea y la traicion nos acecha.\"},{\"heading\":false,\"text\":\"Huyamos, sultana.\"},{\"heading\":false,\"text\":\"Huyamos de esta corte de ignominia.\"},{\"heading\":false,\"text\":\"Yo daré en Africa á tu hermosura un trono mas resplandeciente que el de Boabdil.\"},{\"heading\":false,\"text\":\"Al oir el nombre del rey, la sultana volvió en sí como si despertase de un sueño.\"},{\"heading\":false,\"text\":\"--¡Ah! esclamó: ¡eres tú, Aben-Ahmed! ¿qué quieres á los pies de la sultana?\"},{\"heading\":false,\"text\":\"--¡Levántate, desdichado! ¡los esclavos del rey velan, y tu cabeza está mal segura en tus hombros!\"},{\"heading\":false,\"text\":\"¡Huye! ¡huye y sálvate! ¡que el sultan de Granada no pueda herirte!\"},{\"heading\":false,\"text\":\"Al escuchar el altivo acento de Zoraida, que habia logrado sobreponerse á su sueño, Aben-Ahmed se creyó humillado.\"},{\"heading\":false,\"text\":\"--¿Por qué me has llamado aquí en el silencio de una noche tranquila, sino me amas? esclamó: ¿por qué has venido sola á este apartado jardin donde todo convida al misterio y á los amores?\"},{\"heading\":false,\"text\":\"Si es que no te parezco bastante grande, yo lidiaré, y te lo repito, te conquistaré un trono, el trono de Damasco, y serás sultana del oriente y del occidente, desde el estrecho de Geb-al-Tarik, hasta las vastientes del Atlas y los linderos del gran Sahara.\"},{\"heading\":false,\"text\":\"--¡Oh! ¿qué dices? ¡aparta vasallo! ¡para ser sultana me basta un trono, para ser noble y leal á mi rey y a mi esposo, arde en mis venas la esclarecida sangre del sultan Ismail!\"},{\"heading\":false,\"text\":\"Aparta y vete.\"},{\"heading\":false,\"text\":\"La sultana ha venido aquí, te ha llamado aquí, para robar á tus insensatos amores la última esperanza: para apartarte de una horrible senda que solo conduce á un lago de sangre.\"},{\"heading\":false,\"text\":\"--Yo siento el buitre que se acerca, esclamó tristemente Aben-Ahmed.\"},{\"heading\":false,\"text\":\"Yo oigo en los aires lúgubres rumores.\"},{\"heading\":false,\"text\":\"Es Ariel[138], que bate sobre mí sus alas negras.\"},{\"heading\":false,\"text\":\"Quédate á Dios, sultana.\"},{\"heading\":false,\"text\":\"Si al trasponer el sol del próximo dia, al aparecer en el oriente el lucero de la tarde, ves pasar por delante de él una nubecilla roja, ese será mi espíritu que esperará trémulo de amor una sola mirada de tus ojos.\"},{\"heading\":false,\"text\":\"Y trémulo, pálido como un cadáver, se levantó el abencerrage de los pies de la sultana.\"},{\"heading\":false,\"text\":\"--¡Morir! dijo Zoraida estremecida, arrastrada por la invencible fuerza de su amor; ¡morir tú! ¿y por qué?\"},{\"heading\":false,\"text\":\"--Lo que está escrito se cumplirá, dijo con desesperacion Aben-Ahmed; ¿acaso puedo yo vivir en las tinieblas de la desesperacion, sin tu amor?\"},{\"heading\":false,\"text\":\"¡Oh! yo no te conocia cuando vine de Africa con mi tribu.\"},{\"heading\":false,\"text\":\"¡Yo no sabia que la Alhambra habia de ser para mí, como un vaso de oro y rubíes lleno de falaz tósigo!\"},{\"heading\":false,\"text\":\"Y sin embargo, los sabios de mi patria me habian dicho:\"},{\"heading\":false,\"text\":\"«¡Adónde vas, caudillo?\"},{\"heading\":false,\"text\":\"Cuando el alcion de Africa tienda su vuelo al occidente;\"},{\"heading\":false,\"text\":\"Cuando busque aires mas puros y mas frescos y tierras mas tapizadas de verdor;\"},{\"heading\":false,\"text\":\"Cuando abata su vuelo junto á las claras corrientes,\"},{\"heading\":false,\"text\":\"Sobre las pintadas flores,\"},{\"heading\":false,\"text\":\"Llegará al pie de una montaña coronada por la magestad de un alcázar;\"},{\"heading\":false,\"text\":\"Y en el alcázar encontrará una garza real.\"},{\"heading\":false,\"text\":\"Y la garza causará la muerte del alcion, porque le amará, y apartará de él los ojos, que posará en los de un cobarde gerifalte,\"},{\"heading\":false,\"text\":\"Y el gerifalte verterá con alevosía la sangre del alcion, viajero y peregrino, y velo de sombra estenderá sobre él,\"},{\"heading\":false,\"text\":\"--Lo que pronosticaron los sabios se ha cumplido.\"},{\"heading\":false,\"text\":\"Partí, llegué, te ví, y te amé.\"},{\"heading\":false,\"text\":\"Te amé... como ama el cielo al sol, el mar al viento.\"},{\"heading\":false,\"text\":\"Te amé... como ama el ciego la luz y el desdichado la esperanza.\"},{\"heading\":false,\"text\":\"Te amé... con toda mi alma, con toda mi vida, con todo mi deseo, con toda mi voluntad.\"},{\"heading\":false,\"text\":\"Te amé... para morir de amor.\"},{\"heading\":false,\"text\":\"Quédate á Dios, sultana.\"},{\"heading\":false,\"text\":\"Lo que está escrito se cumplirá.\"},{\"heading\":false,\"text\":\"¿Acaso puedo vivir?\"},{\"heading\":false,\"text\":\"¡No! insultaré á los zegríes y me matarán.\"},{\"heading\":false,\"text\":\"Y si quiero morir con gloria, ¿no velan en el real cristiano, sedientos de sangre mora, ese famoso Gonzalo de Córdoba, el bravo Ponce de Leon, Hernando del Pulgar, y don Alonso de Aguilar el Valiente?\"},{\"heading\":false,\"text\":\"Adios, sultana.\"},{\"heading\":false,\"text\":\"Ariel bate ya sus negras alas.\"},{\"heading\":false,\"text\":\"La hora se acerca.\"},{\"heading\":false,\"text\":\"Y fuera de sí Aben-Ahmed, se apartó de la sultana.\"},{\"heading\":false,\"text\":\"Zoraida no pudo contener su llanto.\"},{\"heading\":false,\"text\":\"Detúvose Aben-Ahmed estremecido de alegría, y tornó al sitio donde aun permanecia inmóvil la sultana.\"},{\"heading\":false,\"text\":\"--¿Por qué lloras? esclamó Aben-Ahmed: cada lágrima tuya vale un torrente de sangre. Si tú me amas, hurí, pronuncia una sola palabra, y cuanto se oponga á nuestro amor caerá ante mi espada.\"},{\"heading\":false,\"text\":\"--¡Vete! dijo la sultana dominando su conmocion y procurando ahogar sus sollozos.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡dejarte cuando todo el llanto que corre de tus ojos, la agitacion de tu seno, la palidez de tu semblante, me dicen que me amas!\"},{\"heading\":false,\"text\":\"--¡Vete! repitió Zoraida.\"},{\"heading\":false,\"text\":\"--No, no me alejaré. Alejarme seria morir.\"},{\"heading\":false,\"text\":\"--Permaneciendo morirás.\"},{\"heading\":false,\"text\":\"--¿Y qué importa?\"},{\"heading\":false,\"text\":\"--¿Y mi amor? esclamó con desesperacion Aben-Ahmed.\"},{\"heading\":false,\"text\":\"La sultana se levantó de una manera solemne: sus lágrimas se habian secado, brillaba su mirada, tranquila, grave, inspirada.\"},{\"heading\":false,\"text\":\"--Antes de conocerte, dijo, yo vivia otra vida tranquila, dulce, resignada, sin alegria, es verdad, pero tambien sin dolores; no amaba á mi esposo, porque no le eligió mi voluntad, porque Dios no habia querido que le amara; pero no le aborrecia.\"},{\"heading\":false,\"text\":\"Mi sueño era tranquilo.\"},{\"heading\":false,\"text\":\"Las flores tenian para mí colores y fragancia.\"},{\"heading\":false,\"text\":\"El aura era fresca y balsámica.\"},{\"heading\":false,\"text\":\"Mi aliento la aspiraba con delicia.\"},{\"heading\":false,\"text\":\"Yo veia al sol levantarse magestuosamente en el oriente y caer lleno de languidez en el occidente, como el camello que se reclina despues de una larga jornada.\"},{\"heading\":false,\"text\":\"Yo lo amaba todo; las flores, los pájaros, las auras, el sol, la tierra, los luceros que vierten una vaga y misteriosa luz en el firmamento.\"},{\"heading\":false,\"text\":\"Era yo entonces feliz: las buenas hadas me halagaban en mis sueños, y al despertar el alba me sonreia.\"},{\"heading\":false,\"text\":\"Pero cuando te ví, Aben-Ahmed, las megillas doradas por el sol de Africa, cabalgando al frente de tus bizarros abencerrages en tu yegua blanca, llevando tras tí el verde estandarte de la familia del profeta;\"},{\"heading\":false,\"text\":\"Cuando pasaste bajo mis celosías galan y hermoso, terciada la pica, la frente alta, suelta la toca al viento, resplandeciente la mirada;\"},{\"heading\":false,\"text\":\"¡Oh! cuando te ví, el ángel de la paz no batió ya sobre mí sus alas blancas, ni las flores, ni la alborada, ni el sol, tuvieron para mí fragancia, frescura, ni resplandores:\"},{\"heading\":false,\"text\":\"Los pasos de mi esposo, que se acercaba á mi retrete y que antes no me inquietaban, me aterraron.\"},{\"heading\":false,\"text\":\"Las puras frentes de mis hijos me causaron vergüenza.\"},{\"heading\":false,\"text\":\"Porque yo dentro de mi alma era adúltera.\"},{\"heading\":false,\"text\":\"Porque dentro de mi alma yo te amaba.\"},{\"heading\":false,\"text\":\"Y yo no debia amarte.\"},{\"heading\":false,\"text\":\"Quise vencer aquel amor vergonzoso y creció.\"},{\"heading\":false,\"text\":\"Quise contenerle al menos, y se desbordó.\"},{\"heading\":false,\"text\":\"Y cuando yo luchaba en vano conmigo misma, tú, enamorado de mí, me aquejabas con tu amor.\"},{\"heading\":false,\"text\":\"En la noche cuando todo callaba, cuando todo dormia, el sonido de una guitarra venia á estremecerme.\"},{\"heading\":false,\"text\":\"Y luego tu voz que cantaba á lo lejos en la márgen del rio, entre las espesuras de avellanos, llegaba, conducida por los traidores céfiros, hasta el mirador, desde el cual fijaba yo en la luna mis ojos llenos de lágrimas.\"},{\"heading\":false,\"text\":\"¿Quién sabia si aquel canto de amores buscaba á la sultana que gemia en su mirador, ó á una dama escondida tras sus celosías en los cármenes del Darro?\"},{\"heading\":false,\"text\":\"Yo sola sabia que aquel canto venia á buscarme.\"},{\"heading\":false,\"text\":\"Yo sola sabia que aquella palabra ardiente, que aquella armonía melancólica hablaba á la sultana.\"},{\"heading\":false,\"text\":\"Y yo me volvia loca.\"},{\"heading\":false,\"text\":\"Yo luchaba.\"},{\"heading\":false,\"text\":\"Quise al fin probar el último remedio.\"},{\"heading\":false,\"text\":\"Quise conocerte, tratarte, contemplarte de cerca, sorprender tus debilidades, tus miserias, encontrar razones para olvidarte.\"},{\"heading\":false,\"text\":\"Y te ví; y te hablé; y solo hallé en tí prendas para amarte mas.\"},{\"heading\":false,\"text\":\"Desesperada, quise probar el último esfuerzo, y te llamé aquí á este jardin solitario para hacer imposible mi vergüenza separándote de mí, apartándote de mí, irritándote, despreciándote.\"},{\"heading\":false,\"text\":\"Yo queria quedarme sola con mi amor.\"},{\"heading\":false,\"text\":\"Queria que huyeses, que me aborrecieses.\"},{\"heading\":false,\"text\":\"¡Y me has vencido!\"},{\"heading\":false,\"text\":\"¡Yo te amo, Aben-Ahmed!\"},{\"heading\":false,\"text\":\"¡Te amo antes que todo!\"},{\"heading\":false,\"text\":\"Pero vete... déjame...\"},{\"heading\":false,\"text\":\"Porque si yo fuese tuya, la vergüenza me mataria.\"},{\"heading\":false,\"text\":\"Porque no podria sobrevivir á mi infamia.\"},{\"heading\":false,\"text\":\"Tras esta apasionada declaracion, la sultana calló, y doblegó su frente bajo el peso de la vergüenza.\"},{\"heading\":false,\"text\":\"Aben-Ahmed llegó á la atarvea, cortó algunas rosas blancas, las enlazó, y las puso, á manera de corona, sobre la frente de la sultana.\"},{\"heading\":false,\"text\":\"--¡Oh! esclamó: si no puedes, si no debes ser mia, guarda estas flores como el emblema de nuestros castos amores, y cuando estas rosas estén marchitas, acuérdate de que el corazon de Aben-Ahmed estará marchito tambien.\"},{\"heading\":false,\"text\":\"--¡Oh! esclamó Zoraida levantando hácia Aben-Ahmed sus ojos inundados de lágrimas: ¡Oh! ¡si estas rosas no estuvieran sobre la pesada corona que ha ceñido á mi frente Boabdil!\"},{\"heading\":false,\"text\":\"Apenas habia pronunciado la sultana estas palabras, cuando entre la espesura de rosales, situada detrás del ciprés, apareció bajo el rayo de la luna, un semblante pálido, convulso, horrible, que abarcaba en una mirada de muerte á los dos amantes.\"},{\"heading\":false,\"text\":\"¡Era el rey Boabdil!\"},{\"heading\":false,\"text\":\"Tras él, ocultos en la sombra, se veian cuatro hombres envueltos en alquiceles blancos.\"},{\"heading\":false,\"text\":\"Aben-Ahmed y Zoraida se alejaba, entretanto, á lo largo del jardin, y muy pronto se perdieron entre la espesura.\"},{\"heading\":false,\"text\":\"El rey saltó como un tigre de entre la enramada, con la mano puesta en su puñal y la sangrienta mirada fija en el lugar por donde habian desaparecido los amantes.\"},{\"heading\":false,\"text\":\"Los cuatro hombres salieron tras él y le rodearon.\"},{\"heading\":false,\"text\":\"Eran Mahomet Adel-Zegrí, Hamet-Zegrí, Mahandon-Gomel, y Mahandin, todos zegríes, todos enemigos de Aben-Ahmed.\"},{\"heading\":false,\"text\":\"Hamet-Zegrí se puso delante del rey.\"},{\"heading\":false,\"text\":\"--¿Adónde vas, señor? le dijo: si matamos á Aben-Ahmed aquí, en Generalife, entre los brazos de la sultana, su muerte será un aviso para los demas abencerrages, y todos deben morir, porque todos son traidores. La venganza, señor, es mas sabrosa cuanto mas se espera. No caiga uno solo, una cabeza es poco.\"},{\"heading\":false,\"text\":\"--Sí, dices bien; esclamó el rey con acento opaco: ¡todos!... ¡todos!...\"},{\"heading\":false,\"text\":\"Y luego en un momento de horrible decision, esclamó:\"},{\"heading\":false,\"text\":\"--Id mañana á la Alhambra acompañados de mi verdugo.\"},{\"heading\":false,\"text\":\"Y apartándose bruscamente de los cuatro zegríes, se perdió por la oscura galería del fondo del jardin.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Al terminarse la zambra en Generalife, los abencerrages recibieron una invitacion del rey que los convidaba para un sarao en el patio de los Leones.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Desde aquella noche en que la sultana Zoraida escuchó al enamorado Aben-Ahmed y le confesó su amor en Generalife, se conoce el viejo árbol de Abul-Walid bajo el nombre tradicional de _Ciprés de la Sultana_.\"}]},{\"title\":\"El patio de los leones. — capítulo XV: La cámara de los leones.\",\"blocks\":[{\"heading\":false,\"text\":\"Al dia siguiente, recostado sobre un divan, en el fondo de uno de los magníficos alhamíes de la cámara de los Leones, habia un hombre cubierto de régias vestiduras.\"},{\"heading\":false,\"text\":\"Estaba pálido, sombrío, meditabundo.\"},{\"heading\":false,\"text\":\"Temblaba su barba bermeja, y temblaban de tiempo en tiempo en una contraccion poderosa los músculos de su semblante, y un largo y breve estremecimiento corria de tiempo en tiempo á lo largo de su cuerpo.\"},{\"heading\":false,\"text\":\"Aquel hombre era el sultan Boabdil.\"},{\"heading\":false,\"text\":\"Estaba solo.\"},{\"heading\":false,\"text\":\"Su mirada terrible, fija, lúgubre, se fijaba en la fuente de mármol colocada en el centro del pavimento, y en la cual no corrian las aguas.\"},{\"heading\":false,\"text\":\"La fuente de la cámara y el alhamí del frente del en que asentaba el rey, estaban cubiertos de tapices rojos.\"},{\"heading\":false,\"text\":\"La cámara estaba velada por una media luz.\"},{\"heading\":false,\"text\":\"El resplandor del sol penetraba fatigado por los dobles trasparentes de la cúpula estrellada, produciendo sobre los muros un reflejo perdido y fatídico, y dejando en sombra á los alhamíes.\"},{\"heading\":false,\"text\":\"Nada se oia, mas que el paso acompasado de los esclavos que guardaban en las galerías del patio de los Leones las puertas de las cámaras.\"},{\"heading\":false,\"text\":\"Notábase en el semblante del rey la impaciencia con que media el tiempo.\"},{\"heading\":false,\"text\":\"Sus miradas crueles, reconcentradas, pasaban tan pronto de la puerta de la cámara al tapiz rojo que cubria el alhamí del frente, como de este tapiz á la taza de mármol situada en el centro del pavimento.\"},{\"heading\":false,\"text\":\"Llegó al fin un punto en que el semblante del rey se dilató.\"},{\"heading\":false,\"text\":\"Habian resonado pasos en las galerías del patio de los Leones.\"},{\"heading\":false,\"text\":\"Los pasos se acercaron.\"},{\"heading\":false,\"text\":\"El tapiz de brocado rojo que cubria el magnífico arco de entrada de la cámara se levantó y apareció un hombre.\"},{\"heading\":false,\"text\":\"Era el abencerrage Aben-Ahmed.\"},{\"heading\":false,\"text\":\"Venia magníficamente vestido, y delante de su hermoso rostro parecia flotar una nube de tristeza.\"},{\"heading\":false,\"text\":\"Adelantó hácia el rey y dijo inclinándose profundamente:\"},{\"heading\":false,\"text\":\"--Allah te guarde y te prospere, magnífico sultan: ¿qué quieres de tu siervo?\"},{\"heading\":false,\"text\":\"Boabdil no contestó al abencerrage.\"},{\"heading\":false,\"text\":\"Se levantó y atravesó lentamente la cámara, llegó al alhamí del frente, levantó un tanto el tapiz rojo, miró al fondo; vió entre la oscuridad una sombra informe, y sonrió, con la espalda vuelta al abencerrage, de una manera horrorosa.\"},{\"heading\":false,\"text\":\"Luego, compuesto ya el semblante, pasó por delante de Aben-Ahmed, que miraba con recelo lo que el rey hacia, y levantó el tapiz de la puerta de entrada.\"},{\"heading\":false,\"text\":\"En aquel momento Mahandon-Gomel estendia en las galerias del patio de los Leones, feroces esclavos negros de la guarda del rey, armados hasta los dientes.\"},{\"heading\":false,\"text\":\"Boabdil dejó caer el tapiz, reconoció bajo sus ropas con su mano trémula su cota de mallas, probó si su puñal salia con facilidad de la vaina, y despues de esto volvió con paso lento al divan que habia dejado, y se sentó en él.\"},{\"heading\":false,\"text\":\"Aben-Ahmed adivinó un peligro, y un peligro inminente y terrible.\"},{\"heading\":false,\"text\":\"Pero era bravo y sereno, y ni un solo músculo de su semblante se contrajo.\"},{\"heading\":false,\"text\":\"Permanecia prosternado en el mismo lugar desde donde habia saludado á Boabdil, que fijaba en él una mirada reconcentrada.\"},{\"heading\":false,\"text\":\"Pero muy pronto aquella mirada perdió su espresion sombría, á la manera que los vapores de la mañana se deshacen, se evaporan, se pierden bajo el rayo del sol.\"},{\"heading\":false,\"text\":\"Su semblante pálido y hermoso dejó ver la lánguida é indolente sonrisa, y la espresion débil y sensual que le caracterizaban.\"},{\"heading\":false,\"text\":\"Sus ojos miraron con una paz profunda á Aben-Ahmed.\"},{\"heading\":false,\"text\":\"--Walí Aben-Ahmed, dijo el rey; despues de la miserable traicion que los zegríes cometieron contra tí y contra los caballeros de tu tribu, siento un indecible placer al verte vivo y salvo ante mí. Levántate, valiente caudillo de los abencerrages: te he llamado porque es muy justo que yo pretenda degraviar por mi parte á los generosos abencerrages. Levántate y ven á sentarte junto á mí.\"},{\"heading\":false,\"text\":\"Aben-Ahmed creyó sinceras las palabras del rey, y sintió un verdadero remordimiento, una profunda vergüenza al recordar que amaba á la esposa de un hombre que le trataba de una tan noble manera.\"},{\"heading\":false,\"text\":\"Obedeció al rey y se sentó en el diván.\"},{\"heading\":false,\"text\":\"El rey reparó en la espada del abencerrage.\"},{\"heading\":false,\"text\":\"Celebró las labores cinceladas de su empuñadura de oro.\"},{\"heading\":false,\"text\":\"Luego quiso ver la hoja.\"},{\"heading\":false,\"text\":\"Aben-Ahmed, perdido enteramente el recelo, desnudó la espada y la entregó al rey.\"},{\"heading\":false,\"text\":\"El rey ponderó el temple de la hoja y lo primoroso de sus labores.\"},{\"heading\":false,\"text\":\"Despues refiriéndose á la batalla del dia anterior, elogió el valor de Aben-Ahmed, y como premio de aquel valor le abrazó.\"},{\"heading\":false,\"text\":\"Ni halló loriga ni jacerina bajo las ropas del abencerrage.\"},{\"heading\":false,\"text\":\"Solo llevaba sedas y brocados.\"},{\"heading\":false,\"text\":\"Cuando Aben-Ahmed estaba completamente desarmado, el rey le dijo:\"},{\"heading\":false,\"text\":\"--Tú eres africano: tú habrás pasado muchas noches á la luz de las estrellas, y habrás consultado á los sabios; tú habrás oido á los xeques de tu tribu contar terribles historias durante las largas noches de invierno; pero jamás habrá sonado en tus oidos una tan terrible como la que vas á oir de boca de tu rey.\"},{\"heading\":false,\"text\":\"Aben-Ahmed tembló de una manera involuntaria.\"},{\"heading\":false,\"text\":\"Un presentimiento frio, lúgubre habia penetrado en su alma.\"},{\"heading\":false,\"text\":\"--Es una historia triste para uno: bella para dos: es una historia que un rey ofendido de una sultana miserable, y de un esclavo infame: una hermosa historia, por Allah.\"},{\"heading\":false,\"text\":\"Aben-Ahmed empezaba á comprender la verdad: pero se dominó sin embargo.\"},{\"heading\":false,\"text\":\"El rey continuó.\"},{\"heading\":false,\"text\":\"--Sí, es una bella historia; por los _Siete Durmientes_, estoy seguro que no habrás oido otra tal en toda tu vida, walí.\"},{\"heading\":false,\"text\":\"Escucha:\"},{\"heading\":false,\"text\":\"«Moraba en una ciudad fuerte y poderosa, un rey á quien todos llamaban débil y cobarde.\"},{\"heading\":false,\"text\":\"Todos se mofaban de él... á su espalda, porque es fama que aquel rey llevaba sus venganzas hasta la crueldad.\"},{\"heading\":false,\"text\":\"Y este rey, solo, perseguido de su destino, abandonado de sus vasallos, receloso de sus esclavos, llegó á encontrar triste y solitaria su morada real.\"},{\"heading\":false,\"text\":\"Y ten en cuenta que nunca poderoso sultan ó respetado emir, alcanzaron á ver juntos tanto oro y tantas alhajas, tantos mármoles y tantas grandezas como contenia el alcázar que aquel rey desdichado habia heredado de sus abuelos.\"},{\"heading\":false,\"text\":\"Aquel rey ruin, débil y cobarde, como decian sus vasallos.\"},{\"heading\":false,\"text\":\"Y como aquel rey tenia corazon, corazon agitado por miserables pasiones humanas, se dijo sondeando su corazon:\"},{\"heading\":false,\"text\":\"Buscaré entre las princesas de mi reino ó de regiones distantes, una muger hermosa, amante, de ojos brilladores, y frente pura que no empalidezca bajo el brillo de la corona.\"},{\"heading\":false,\"text\":\"Y así no estaré solo y abandonado.\"},{\"heading\":false,\"text\":\"Y buscó y encontró.\"},{\"heading\":false,\"text\":\"Y á mano, á fe; dentro de su misma tribu, en su misma familia, casi en su alcázar.\"},{\"heading\":false,\"text\":\"Y ella, la que debia ser sultana, escuchó ruborosa al anciano wazir que en nombre del rey la requirió para que fuese sultana, y aceptó.\"},{\"heading\":false,\"text\":\"Todo cambió.\"},{\"heading\":false,\"text\":\"Pareció que el casamiento del rey y de la princesa habia sido una evocacion mágica.\"},{\"heading\":false,\"text\":\"Porque despertaron de su inercia damas y caballeros, se prendieron las unas sus velos, y dejaron los otros sus arneses de batalla.\"},{\"heading\":false,\"text\":\"Y hubo toros y zambras, y se corrieron sortijas y cañas.\"},{\"heading\":false,\"text\":\"Y hubo fiestas magníficas que duraron muchos dias.\"},{\"heading\":false,\"text\":\"Y todo parecia sonreir al rey.\"},{\"heading\":false,\"text\":\"Y pasaron muchas lunas, y la sultana le dió hijos.\"},{\"heading\":false,\"text\":\"Pero llegó un dia fatal en que un walí de Africa, cabeza de una tribu, un mancebo de sangre real como tú, valiente como tú, como tú hermoso, y como tú rico y afortunado, vino de regiones apartadas cabalgando delante de su escuadron de lanzas á servir á aquel rey que estaba en guerra con un enemigo poderoso.\"},{\"heading\":false,\"text\":\"Y el walí africano y la sultana se conocieron.\"},{\"heading\":false,\"text\":\"Mas que no se amaron.\"},{\"heading\":false,\"text\":\"Y la vil muger, manchó entre un vergonzoso misterio la honra de su esposo.»\"},{\"heading\":false,\"text\":\"El rey se detuvo.\"},{\"heading\":false,\"text\":\"Aben-Ahmed temblaba por Zoraida.\"},{\"heading\":false,\"text\":\"El rey continuó:\"},{\"heading\":false,\"text\":\"--«Una noche... noche de fiesta... cuatro leales vasallos de aquel rey, encontraron en el apartamiento mas sombrio de su jardin en uno de los alcázares del rey, á la sultana en los brazos del walí.»\"},{\"heading\":false,\"text\":\"--Miente el traidor que tal haya dicho; esclamó sin poderse contener Aben-Ahmed; la sultana es mas pura, que infame la calumnia de sus acusadores.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿conocias á esa sultana? dijo friamente Boabdil: pues bien... escucha; aun queda lo mejor de la historia...\"},{\"heading\":false,\"text\":\"«El rey vió tambien lo que los otros habian visto.\"},{\"heading\":false,\"text\":\"Vió el semblante de los culpables al rayo de la luna, y pudo haberlos castigado allí.\"},{\"heading\":false,\"text\":\"Pero no bastaba á su venganza aquella poca sangre impura.\"},{\"heading\":false,\"text\":\"Necesitaba verterla á torrentes, porque aquel rey era cruel, muy cruel en sus venganzas.»\"},{\"heading\":false,\"text\":\"Al llegar el rey á este punto, sus ojos se dilataron como los de la fiera que acorrala á una presa.\"},{\"heading\":false,\"text\":\"Aben-Ahmed vió sangre en la mirada del rey, se encontró desarmado, y dominado por su terror pretendió lanzarse fuera de la cámara.\"},{\"heading\":false,\"text\":\"Pero al levantar el tapiz, vió por fuera una doble fila de esclavos africanos.\"},{\"heading\":false,\"text\":\"Retrocedió, y olvidando que la cámara no tenia otra salida, se lanzó al alhamí cubierto por el tapiz.\"},{\"heading\":false,\"text\":\"Cinco hombres salieron de detrás de él.\"},{\"heading\":false,\"text\":\"Los cuatro eran los zegríes acusadores.\"},{\"heading\":false,\"text\":\"El otro el verdugo del rey.\"},{\"heading\":false,\"text\":\"Un feroz esclavo desnudo hasta la cintura, rodeado á la frente un cendal rojo, y ceñido un ancho y corvo alfange.\"},{\"heading\":false,\"text\":\"Aben-Ahmed cerró involuntariamente los ojos á impulsos del horror.\"},{\"heading\":false,\"text\":\"Boabdil asió al abencerraje por la aljuba, y le arrastró junto á sí.\"},{\"heading\":false,\"text\":\"Sus ojos centelleaban.\"},{\"heading\":false,\"text\":\"Sus megillas estaban pálidas, y cárdenos y convulsos sus labios.\"},{\"heading\":false,\"text\":\"Su ronca voz era semejante al rugido de un tigre.\"},{\"heading\":false,\"text\":\"--¡Conoces mi historia! dijo á Aben-Ahmed; pero aun no sabes los nombres.\"},{\"heading\":false,\"text\":\"¡Oh! ¡yo te los diré! pero prostérnate, esclavo, delante de tu señor.\"},{\"heading\":false,\"text\":\"Y le arrojó á sus pies.\"},{\"heading\":false,\"text\":\"Aben-Ahmed, arrastrado por su funesto destino, aterrado por la fatalidad que ceñia una aureola de muerte á sus insensatos amores, permaneció prosternado, inerte, ante Boabdil.\"},{\"heading\":false,\"text\":\"--¡Oh! esclamó el rey: ¡por Allah, que la venganza es un placer infinito! ¡por Allah, que cuando se tiene poder para hacer pedazos á un enemigo, se puede rechazar el mote de _Desventuradillo_[139]! ¡yo soy el sultán de Andalucía! ¡yo el esposo ultrajado! ¡y tú... tú el esclavo vil que escupes á la frente de tu señor, y que vas á morir con tu cómplice, con la hermosa Zoraida, con la sultana adúltera de mi leyenda.\"},{\"heading\":false,\"text\":\"--¡Ella! esclamó Aben-Ahmed, levantándose de repente, en un ademan que hizo retroceder al rey: ¡ella tambien! ¡oh! ¡no! ¡tú, rey miserable y traidor, eres el que va á morir, calumniador de mugeres, vil renegado, que vendes tu patria, de miedo, por Allah!\"},{\"heading\":false,\"text\":\"Y se lanzó al rey para arrancarle su espada.\"},{\"heading\":false,\"text\":\"Boabdil dió un grito de espanto al sentirse asido por el abencerrage.\"},{\"heading\":false,\"text\":\"Pero á punto los cuatro testigos de aquella escena, se arrojaron sobre el abencerrage, y el verdugo á su vez, á una seña del rey, se apoderó de él.\"},{\"heading\":false,\"text\":\"Aben-Ahmed cayó.\"},{\"heading\":false,\"text\":\"El verdugo despues de haberle herido continuaba de pie é inmóvil junto á él.\"},{\"heading\":false,\"text\":\"--¡Su cabeza! gritó el rey trémulo de ira.\"},{\"heading\":false,\"text\":\"Aben-Ahmed se levantó sobre sus brazos ensangrentados y quiso acometer á los que le acosaban, pero le faltaron las fuerzas y cayó de nuevo sobre el pavimento; luchó aun, miró con desprecio al rey, y esclamó:\"},{\"heading\":false,\"text\":\"--¡Asesino!... ¡maldito seas!...\"},{\"heading\":false,\"text\":\"La voz de Aben-Ahmed se heló.\"},{\"heading\":false,\"text\":\"El verdugo habia cortado de un solo golpe de alfange su cabeza.\"},{\"heading\":false,\"text\":\"Boabdil miró con espanto aquella cabeza, poco antes tan hermosa, y entonces tan lívida y tan desencajada: la duda acerca del crimen de que habia sido acusado Aben-Ahmed asaltó su espíritu, y el remordimiento empezó á desgarrar su corazon.\"},{\"heading\":false,\"text\":\"Pero la vista de la sangre le cegaba.\"},{\"heading\":false,\"text\":\"Su caliente olor le embriagaba, y cayó en un terrible estado de demencia.\"},{\"heading\":false,\"text\":\"--¡Todos!... esclamó con voz ronca y lúgubre; ¡que perezcan todos! ¿acaso no soy yo el sultan de Andalucía? ¡Matadlos!... ¡son traidores!... ¡matad á todo el que pase esa puerta!... ¡que la sangre corra á lo largo de las atarveas y vaya á enrojecer mis albercas de mármol!\"},{\"heading\":false,\"text\":\"Los zegríes gozaban con un placer infinito su venganza en la cólera del rey.\"},{\"heading\":false,\"text\":\"--Pero repara, señor, dijo Mahandon, que si no se ocultan los esclavos que están en las galerías del patio, ninguno de los abencerrages entrará, los has convidado para una fiesta, y no es costumbre que asistan á las fiestas del alcázar hombres armados de guerra. Ocúltalos, señor, que con que quedemos aquí treinta zegríes y el verdugo, hay bastante para acabar con esos perros.\"},{\"heading\":false,\"text\":\"Y así se hizo.\"},{\"heading\":false,\"text\":\"Los esclavos africanos desaparecieron de las galerías del patio de los Leones; pero quedaron agrupados y ocultos tras las puertas del panteon y de los baños.\"},{\"heading\":false,\"text\":\"A poco, un venerable anciano de la tribu de los abencerrages, kadí de córte, llamado Abu-al-Hhakem, levantó el tapiz de la cámara de los Leones y adelantó para prosternarse ante el rey.\"},{\"heading\":false,\"text\":\"Pero sus débiles pies, resbalaron en la sangre del walí Aben-Ahmed, y cayó.\"},{\"heading\":false,\"text\":\"Y no volvió á levantarse, porque el verdugo se apoderó de él y le cortó la cabeza.\"},{\"heading\":false,\"text\":\"Y despues de esto fueron entrando en la cámara uno tras otro treinta y seis caballeros abencerrages.\"},{\"heading\":false,\"text\":\"Y así, uno tras otro, fueron sacrificados al furor de Boabdil y á la traicion de los zegríes.\"},{\"heading\":false,\"text\":\"Todos, en fin, hubieran sido esterminados si aquel horrible crimen no se hubiese revelado por sí mismo con un indicio terrible.\"},{\"heading\":false,\"text\":\"Al entrar el walí abencerraje Ebn-Alabéz en el alcázar, como adelantara pensativo y receloso por el patio del Mexuar, al pisar la galería que da entrada al patio de los Leones, sus ojos se fijaron con horror en la atarvea que cruzaba el pavimento de mármol.\"},{\"heading\":false,\"text\":\"Por aquella atarvea avanzaba una ola de negra sangre, tiñendo el blanco mármol de un color impuro, y aquella roja cinta de muerte emanaba ondeando de la cámara de los Leones.\"},{\"heading\":false,\"text\":\"Estremecióse de horror Ebn-Alabéz, detúvose, y escuchó.\"},{\"heading\":false,\"text\":\"Reinaba un profundo silencio, en medio del cual se percibia algun ahogado gemido.\"},{\"heading\":false,\"text\":\"En el momento, como el gamo que siente los perros sobre su rastro, el walí se volvió atrás, desenvainó su espada, y atropellando la guardia del alcázar, salió de él y bajó á la ciudad dando gritos y acusando la traicion del rey.\"},{\"heading\":false,\"text\":\"Muy pronto la Alhambra se vió acometida por los abencerrages que habian quedado vivos, por los caballeros de sus tribus amigas, que se les habian unido, y por un populacho numeroso, compuesto de esa clase de gentes que siempre están dispuestas á un motin.\"},{\"heading\":false,\"text\":\"Empezó el combate; mas bien que el combate, el asalto.\"},{\"heading\":false,\"text\":\"Crugian de una parte los falconetes y las lombardas, y de otra la arcabucería y la ballestería.\"},{\"heading\":false,\"text\":\"Aquel estruendo de combate llegó hasta la distante cámara de la sultana Zoraida, que viendo asaltada la Alhambra, salió de sus habitaciones en busca del rey, y le encontró en el patio del Mexuar, á punto que huia del de los Leones.\"},{\"heading\":false,\"text\":\"Donde quiera que ponian los pies el rey ó los zegríes que le acompañaban, dejaban señales rojas.\"},{\"heading\":false,\"text\":\"--¿Qué es esto, señor? dijo Zoraida; ¿vienes herido, ó ha llegado la hora del acabamiento de Granada? ¿Qué sangre es esa que corre por las atarveas?\"},{\"heading\":false,\"text\":\"Y siguiendo aquella sangre, temiéndolo todo, entró primero en el patio, y luego en la cámara de los Leones.\"},{\"heading\":false,\"text\":\"Al levantar el tapiz salió de su boca un grito agudo, rasgado, infinito.\"},{\"heading\":false,\"text\":\"Un grito de horror.\"},{\"heading\":false,\"text\":\"La fuente de la cámara rebosaba sangre.\"},{\"heading\":false,\"text\":\"Un círculo de cabezas cercenadas y horribles la rodeaba.\"},{\"heading\":false,\"text\":\"En un ángulo, cuerpos descabezados mostraban en los colores de sus vestidos las divisas de los abencerrajes.\"},{\"heading\":false,\"text\":\"Por un refinamiento de crueldad de Boabdil, la cabeza de Aben-Ahmed estaba pendiente de la cúpula en la cadena de oro de una magnífica lámpara de alabastro, cuyos fragmentos estaban esparcidos acá y allá.\"},{\"heading\":false,\"text\":\"Por un momento, los ojos de la sultana estuvieron fijos en aquel mísero despojo; comprimióse su corazon, brotaron lágrimas sus ojos, palideció su frente, hízose amenazadora y sombría, se crisparon sus miembros y se lanzó rugiente como una leona á Boabdil, que la habia seguido.\"},{\"heading\":false,\"text\":\"--¡Ven á mirarlo! ¡ven! le dijo asiéndole con fuerza desesperada por un brazo; ¡mira tu obra! ¡mírala frente á frente! ¡deleita en ella tu mirada! ¡hazaña digna de tí y de tus zegríes! ¡el lobo se une al lobo! ¡bien! ¡yo creia ser la esposa de un rey y de un caballero, y en vez de él solo encuentro un verdugo y un cobarde!\"},{\"heading\":false,\"text\":\"Boabdil miró sombriamente á la sultana, y sus labios se contrajeron con una sonrisa amarga, convulsiva, horrorosa.\"},{\"heading\":false,\"text\":\"--¡Ah! dijo lanzando una histérica carcajada; ¡hoy es un buen dia! ¡todos los traidores á la vez! ¡y tú tambien, sultana! ¡oh! ¡yo soy poderoso, yo soy el sultan de Andalucía! ¡sangre! ¡sangre! ¡verted sangre sobre mi cabeza, porque arde y va á romperse! ¡tú tambien, sultana!... ¡por los siete cielos de Dios que este lecho no es menos bello que la grama de Generalife! añadió con acento horroroso, señalando el pavimento ensangrentado; ¡vas á morir, sultana, porque eres adúltera, y has arrojado mancha de infamia sobre la faz de tu esposo y tu señor!\"},{\"heading\":false,\"text\":\"Zoraida lanzó una profunda mirada de desprecio al rey y á los zegríes agrupados tras él; su hermosa frente se levantó orgullosa, magnífica en su indignacion, y con voz severa acentuada, dijo con magestad á los zegríes:\"},{\"heading\":false,\"text\":\"--¿Hay alguno entre vosotros, que se atreva á decir, ni aun á pensar, que la sultana de Granada ha manchado su nombre limpio mas que el sol?\"},{\"heading\":false,\"text\":\"Callaron un momento los zegríes dominados por el soberbio ademan, por la palabra altiva de Zoraida, y el rey miró con impaciencia á los cuatro traidores causantes del asesinato de los abencerrages.\"},{\"heading\":false,\"text\":\"Aquella mirada los decidió.\"},{\"heading\":false,\"text\":\"--Yo, dijo Mahandin, adelantando, en nombre de estos tres caballeros (y señaló á Mahandon; á Mohamet y á Hamet-Zegrí), te acuso, sultana, ante Dios y los hombres, de adulterio, traicion y complicidad con el abencerrage Aben-Ahmed, contra el rey tu esposo y nuestro señor.\"},{\"heading\":false,\"text\":\"Estas palabras resonaron en medio de un silencio solemne, en medio de los zegríes, de los caballeros y de los esclavos de la guarda del rey que le habian rodeado al ruido del combate de los que habian seguido contra la Alhambra, al abencerrage Ebn-Alabéz.\"},{\"heading\":false,\"text\":\"Y la sultana, sobrecogida por aquella impudente acusacion, tornose al acusador lívida de cólera, temblorosos sus miembros; ardió en sus venas la sangre de su raza, y gritó con ronca y terrible voz:\"},{\"heading\":false,\"text\":\"--¡Mientes tú, villano y mal caballero, y los que contigo son; y yo Zoraida, nieta y esposa de rey, apelo contra vuestra acusacion al juicio de Dios en la prueba del duelo, os llamo infames y calumniadores, y á falta de guante, recibe tú, Mahandin, en tu rostro de cobarde y asesino, el chapín de la sultana!\"},{\"heading\":false,\"text\":\"Y fuera de sí Zoraida, olvidándose de quien era, se arrancó uno de sus preciosos chapines bordados de aljófar y azotó con él el rostro de Mahandin.\"},{\"heading\":false,\"text\":\"Aquel sangriento ultraje era mas de lo que podia sufrir gente dominada por bravias pasiones, originaria de Africa y feroz como los leones de su patria.\"},{\"heading\":false,\"text\":\"Las treinta espadas de los zegríes lucieron fuera de las vainas, interpúsose el rey, avanzaron los esclavos de su guardia, y se cernió sobre el alcázar durante un momento el genio de la muerte codicioso de mas cadáveres.\"},{\"heading\":false,\"text\":\"Pero de repente un tropel de esclavos negros precedido del infante Muza, penetró en el patio de los Leones, con las ballestas armadas y las frentes cubiertas de sudor.\"},{\"heading\":false,\"text\":\"--¡Huye, señor! gritó Muza dirigiéndose al rey: ¡huye! ¡el pueblo y las tribus amigas de los abencerrages han forzado las puertas de la Alhambra y llegan al alcázar! ¡escucha!\"},{\"heading\":false,\"text\":\"Un rumor sordo de voces, inmenso, rugiente, de entre el cual salian algunos disparos de arcabuz, llegó á los oidos del rey.\"},{\"heading\":false,\"text\":\"Los zegríes retrocedieron, envainaron sus espadas, asieron de Boabdil, y escaparon con él por un postigo de la sala de Justicia, á tiempo que los amotinados rompian las puertas del alcázar.\"},{\"heading\":false,\"text\":\"Muza asió de la sultana, que se habia desmayado, y escapó con ella por la puerta de la torre de _las Almenas_[140].\"},{\"heading\":false,\"text\":\"Los abencerrages y las tribus sus amigas, seguidos de un inmenso populacho á quien habia irritado el asesinato de Aben-Ahmed, que por su generosidad y valentía era muy querido en Granada, inundó el patio y la cámara de los Leones, y no quedó un zegrí con vida de los que no pudieron escapar del alcázar.\"},{\"heading\":false,\"text\":\"La infame traicion fué vengada hasta la saciedad.\"},{\"heading\":false,\"text\":\"Cuando los amotinados no encontraron á quien matar, rompieron todos los preciosos muebles del alcázar.\"},{\"heading\":false,\"text\":\"Los abencerrages, recogiendo sus tesoros, y llevando consigo sus mugeres y sus familias, salieron de Granada; los unos desesperados á servir contra Granada bajo la bandera de los Reyes Católicos, y los otros, fieles á su religion, á su patria y á su nombre de caballeros, pasaron á Africa, de donde, siete siglos antes, habian venido sus abuelos para conquistar las tierras de occidente, llevando consigo los restos del desventurado Aben-Ahmed, que fué sepultado á la sombra de una palmera en el suelo de su patria.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Desde aquel terrible dia, la cámara de los Leones, en memoria del asesinato, se llama _Sala de los Abencerrages_, y aun se muestran al viajero sobre el mármol de su fuente y de su pavimento, las manchas rojas que se dice son producidas por la sangre de aquellos valientes caballeros.\"}]},{\"title\":\"El patio de los leones. — capítulo XVI: El juicio de dios.\",\"blocks\":[{\"heading\":false,\"text\":\"Habia pasado una luna desde el dia en que la cámara de los Leones se manchó de una manera indeleble con la sangre de los abencerrages.\"},{\"heading\":false,\"text\":\"Era una noche oscura.\"},{\"heading\":false,\"text\":\"El Real de los Reyes Católicos, la ciudad de Santa Fé, dormia confiada su seguridad á la vigilancia de los atalayas y de los escuchas.\"},{\"heading\":false,\"text\":\"Los caballeros _continuos_ armados de guerra hacian su guarda en las tiendas de los reyes, y mas allá todo era silencio y soledad.\"},{\"heading\":false,\"text\":\"Pero de improviso, en una de las calles del Real, resonaron callados pasos y son de cabalgaduras.\"},{\"heading\":false,\"text\":\"Cuatro sombras, llevando caballos del diestro, se deslizaron á lo largo de la calle en direccion á la puerta del Real que miraba á Granada.\"},{\"heading\":false,\"text\":\"Cuando hubieron llegado á ella, se oyó entre el silencio una voz que gritó:\"},{\"heading\":false,\"text\":\"--¿Quién va?\"},{\"heading\":false,\"text\":\"--Haced que adelante el alférez de la guarda, contestó una de las cuatro sombras.\"},{\"heading\":false,\"text\":\"Levantóse el tapiz de una tienda cercana, dejándose ver el reflejo de una luz en el interior, y apareció otra sombra.\"},{\"heading\":false,\"text\":\"--¿Quién va? repitió.\"},{\"heading\":false,\"text\":\"--El _Alcaide de los Donceles_, contestó el primero dirigiéndose al que habia preguntado.\"},{\"heading\":false,\"text\":\"--Guárdete Dios, capitan, dijo aquel; ¿qué deseas?\"},{\"heading\":false,\"text\":\"--Salir á la vega con estos tres caballeros, que son don Alonso de Aguilar, don Manuel Ponce de Leon, y Don Juan Chacon.\"},{\"heading\":false,\"text\":\"Guardó silencio por un momento el alférez, como aquel á quien se pide una cosa difícil.\"},{\"heading\":false,\"text\":\"--¿Sabeis, caballeros, dijo al fin, que yo no puedo hacer lo que me pedís?\"},{\"heading\":false,\"text\":\"--Lo sabemos, y por eso lo suplicamos.\"},{\"heading\":false,\"text\":\"--¡Sus Altezas!...\"},{\"heading\":false,\"text\":\"--Sus Altezas no sabrán que hemos salido por esta puerta ni por otra, sino que no hemos entrado. Di, pues, al atalaya que nos deje paso franco.\"},{\"heading\":false,\"text\":\"--Puede sucedernos un fracaso, porque los moros rondan el campo á la redonda.\"},{\"heading\":false,\"text\":\"--¡Pardiez! ¿sabes, alférez, que tenemos empeñada una porfía con los capitanes de caballos Hernan Perez del Pulgar y Gonzalo Fernandez de Córdoba, sobre quién hará una mayor hazaña, y que no hemos de perderla sino con la vida?\"},{\"heading\":false,\"text\":\"--Pues porfía teneis, y con porfía lo pedís, salid, caballeros, y que Dios os ayude.\"},{\"heading\":false,\"text\":\"Y el alférez llegó al atalaya y le previno.\"},{\"heading\":false,\"text\":\"Y los cuatro capitanes cristianos salieron al campo, montaron á caballo, y se alejaron mas que á paso del Real.\"},{\"heading\":false,\"text\":\"Era á punto de amanecer.\"},{\"heading\":false,\"text\":\"Los cuatro caballeros cristianos aguijaron sus caballos.\"},{\"heading\":false,\"text\":\"Y como iban en busca de aventuras, les dejaron ir, para que la aventura fuese completa, por el primer camino que los animales tomaron.\"},{\"heading\":false,\"text\":\"Y él acaso, protector de locos y aventureros que todo es uno, les deparó aventura tal, que cuando á la vista de ella se encontraron, se dieron por tan satisfechos como quien ha logrado un imposible.\"},{\"heading\":false,\"text\":\"Y fué, que vieron venir el camino adelante de la parte de Granada y á la luz del alba que esclarecia, un bulto blanco, asaz en grandeza y ligero como un copo de plumas impulsado por el viento.\"},{\"heading\":false,\"text\":\"Verse, afirmarse en los estribos y correr á él, fué cosa de un momento.\"},{\"heading\":false,\"text\":\"Y el bulto al ver que los cuatro caballeros castellanos arremetian, se detuvo.\"},{\"heading\":false,\"text\":\"Y una voz dulce de muger dolorida y triste, se dirigió á ellos.\"},{\"heading\":false,\"text\":\"--Si sois caballeros, dijo, amparadme, que de caballeros es favorecer al desvalido, y yo soy una muger que viene de Granada, y va al Real de los cristianos.\"},{\"heading\":false,\"text\":\"--Muger sola y á esta hora, dijo el señor de Cartagena, don Juan Chacon, en grave conflicto hallarse debe, pues anda en tales caminos sola y desamparada.\"},{\"heading\":false,\"text\":\"--¡Ojalá fuesen mios el peligro y la desventura, replicó la dama, que no me hallarais tan menesterosa de amparo; mas, pues sois caballeros, segun lo indica vuestra mesura, y cristianos pues hablais en algaravia[141], os ruego me lleveis á punto donde yo pueda ver á don Juan Chacon, señor de Cartagena.\"},{\"heading\":false,\"text\":\"El dia entraba ya aprisa, y á su luz pudieron ver los castellanos á una mora vestida con ropas blancas, de gran juventud y hermosura, montada en una hacanea, y pálida y temerosa, al parecer, de hallarse entre enemigos.\"},{\"heading\":false,\"text\":\"--Si á don Juan Chacon buscas, hermosa doncella, dijo él mismo, hablar puedes de lo que con ese caballero te importa, porque yo y mis amigos lo somos suyos en gran manera.\"},{\"heading\":false,\"text\":\"--Bueno será que nos separemos del camino, dijo ella metiendo su hacanea por las hazas, y entrándose en una espesa alameda que allí a mano se veia.\"},{\"heading\":false,\"text\":\"Los cuatro caballeros la siguieron asaz maravillados del lance.\"},{\"heading\":false,\"text\":\"Cuando hubieron llegado á un lugar espeso, en el cual de nadie podian ser vistos, la mora sacó del seno una carta envuelta en un paño de seda y habló á los cristianos de esta manera:\"},{\"heading\":false,\"text\":\"--Yo me llamo Zaruhyemal, y soy doncella de la infeliz sultana de Granada, á quien persigue el destino hasta el punto de verse obligada á pedir amparo á sus enemigos.\"},{\"heading\":false,\"text\":\"Detúvose la mora y creció la curiosidad de los cristianos.\"},{\"heading\":false,\"text\":\"Escrito estaba, continuó ella, que Granada debia llegar á ocasion de vergüenza y de mala ventura.\"},{\"heading\":false,\"text\":\"Para que lo escrito se cumpliese, el Dios altísimo permitió que entraran en Granada unos caballeros sin fé, mentirosos y aleves con quienes alientan la traicion y la envidia.\"},{\"heading\":false,\"text\":\"Ya conocereis, caballeros, que hablo de los zegríes, raza feroz del Desierto, mal avenida con la generosidad y la cortesanía de la gente de Granada, sediciosos y rebeldes, promovedores de motines y causadores del mayor crímen que vieron los tiempos pasados ni verán los venideros.\"},{\"heading\":false,\"text\":\"Y Zaruhyemal les refirió los encarnizados ódios de los zegríes y de los abencerrages, la traicion de las cañas, la acusacion de la sultana, y el degüello de los abencerrages.\"},{\"heading\":false,\"text\":\"Que la sultana estaba presa en la torre de Comares de la Alhambra, esperando su salvacion y su honra del juicio de Dios, en la prueba del duelo.\"},{\"heading\":false,\"text\":\"Y que el plazo terminaba aquel dia que ya habia amanecido.\"},{\"heading\":false,\"text\":\"--Si sois caballeros, continuó; pues veis que una dama pone en grave riesgo su honra, yendo á entrar en un campo enemigo, hacedme la merced de llevar sin perder un instante esta carta y entregarla á aquel para quien es, y que Dios os juzgue, caballeros, tal como cumplais con un encargo en que se arriesgan la honra y la vida de una sultana.\"},{\"heading\":false,\"text\":\"Tomó la carta don Juan Chacon, rompió los hilos del sello de oro y la desenrolló.\"},{\"heading\":false,\"text\":\"--¿Qué haces, cristiano? esclamó con acento de reconvencion la mora.\"},{\"heading\":false,\"text\":\"--Si á don Juan Chacon es á quien va dirigida esta carta, señora, permite á don Juan Chacon, que está en tu presencia, bese tu mano, en albricias de la honra que le hace amparándose de él una señora tal como la sultana de Granada.\"},{\"heading\":false,\"text\":\"Y tomó la hermosa y blanca mano de Zaruhyemal y la besó, no sin que lo encendido de la vergüenza colorease las megillas de la mora.\"},{\"heading\":false,\"text\":\"Despues leyó á sus compañeros en alta voz la carta, que decia de esta manera:\"},{\"heading\":false,\"text\":\"«A tí, don Juan Chacon, señor de Cartagena, la sultana Zoraida te saluda y desea prosperidad.\"},{\"heading\":false,\"text\":\"»Tu clara valentía brilla lejos de tí, como el sol en los lejanos montes.\"},{\"heading\":false,\"text\":\"»Te conocen los desvalidos y te bendicen los desdichados.\"},{\"heading\":false,\"text\":\"»Pues siempre has sido generoso y amparador, ampárame, cristiano.\"},{\"heading\":false,\"text\":\"»Así Allah, multiplique y ennoblezca tu descendencia sobre las noblezas de tu raza.\"},{\"heading\":false,\"text\":\"»Así cierres los ojos á la luz tras una larga vida de bienandanzas.\"},{\"heading\":false,\"text\":\"»Mi honor ha sido mancillado por las lenguas viles de cuatro traidores.\"},{\"heading\":false,\"text\":\"»A punto estoy de la prueba del duelo confiando en Dios en tí y en mi inocencia.\"},{\"heading\":false,\"text\":\"»Y vencerás: yo lo espero.\"},{\"heading\":false,\"text\":\"»Una cristiana cautiva que me asiste, me ha dicho cuánto vales y cuánto puedes.\"},{\"heading\":false,\"text\":\"»Cuánto eres la honra de la hueste de los venturosos reyes que tienen vasallos tales como tú.\"},{\"heading\":false,\"text\":\"»¡Oh! han lanzado la sangre de mi amor á mi semblante y han roto mi corazon.\"},{\"heading\":false,\"text\":\"»Porque yo amaba, cristiano, á un hombre á quien han asesinado por mi causa.\"},{\"heading\":false,\"text\":\"»Pero con un amor puro, noble, exento de mancilla.\"},{\"heading\":false,\"text\":\"»Ven cristiano: ven con otros tres de tus amigos, que siéndolo tuyos no pueden ser sino generosos y valientes.\"},{\"heading\":false,\"text\":\"»Ven y cobra la sangre de Aben-Ahmed.\"},{\"heading\":false,\"text\":\"»Ven y lava mi deshonra.\"},{\"heading\":false,\"text\":\"»La doncella de mi casa que te entregará estas letras, te conducirá á donde encuentres armas y preseas bastantes á que puedas encubrir tu nombre y tu patria.\"},{\"heading\":false,\"text\":\"»Ven, ¡oh! ven cristiano, porque desamparada de todos, en tí confio.»\"},{\"heading\":false,\"text\":\"Don Juan se estremeció de alegria, y dijo á sus tres amigos:\"},{\"heading\":false,\"text\":\"Y bien; si buscábamos aventuras, ¿cuál mejor que esta? ¿Cómo podremos esclarecer nuestro nombre mejor que defendiendo á una sultana de cuatro enemigos tan valientes como los zegríes? ¡A caballo, caballeros! ¡á caballo, y que esta dama nos conduzca al sitio donde hemos de trocar armas y cabalgaduras!\"},{\"heading\":false,\"text\":\"Movió un tanto la cabeza el prudente don Alonso de Aguilar, y permaneció á pié mientras los otros tres castellanos montaban en sus caballos.\"},{\"heading\":false,\"text\":\"--¿Y cómo es, dijo á la mora mirándola profundamente, que no hay caballeros en Granada, que se llama la de los bravos, para arrojar el guante á los acusadores de la sultana?\"},{\"heading\":false,\"text\":\"--¡Cristiano! respondió con orgullo Zaruhyemal: ten en cuenta que una dama es la portadora de este mensage, y que un moro granadino no os daria otra cosa que el bote de su lanza, ni os hablaria con otra lengua que con la espada.\"},{\"heading\":false,\"text\":\"Si os place, venid: si temeis traicion, quedaos, que no faltarán aun en vuestros mismos reales caballeros que tomen sobre sí y con placer la empresa que vosotros no aceptais.\"},{\"heading\":false,\"text\":\"Calló cortesmente don Alonso á estas razones, ayudó á cabalgar á la mora, saltó en su caballo, y tras algunas breves palabras acerca del camino que elegirian, tomaron la vega adelante y al través, y dejando á mano siniestra á Granada, y siempre por fuera de camino y lejos de las alkerías para evitar un encuentro, se dirigieron, guiados por Zaruhyemal á las verdes colinas que se estienden cubiertas de olivares á la falda de Sierra Nevada.\"},{\"heading\":false,\"text\":\"Y anduvieron así dos horas, y al cabo de ellas llegaron, rodeando entre los olivares, á un pequeño alcázar rodeado de un bosque de laureles en las inmediaciones de una aldea llamada la Azubia.\"},{\"heading\":false,\"text\":\"Gozábase desde allí de la vista de un pais admirable.\"},{\"heading\":false,\"text\":\"Los resplandecientes Alijares con sus cúpulas altísimas; la Alhambra con sus torres rojizas y sus techos cubiertos de tejas de colores que lanzaban destellos de fuego heridas por el sol; la alcazaba con sus fuertes muros y sus altísimos cipreses; el cerro de Al-Bahul, cubierto de higueras de Túnez sobre las que descollaban cedros de Siria y palmeras de Africa; las vertientes de las colinas cubiertas de blancas y alegres casas, sobre las cuales descollaban las frondas de los jardines, luego la vega, tendida á los pies de Granada cercada de rios y acequias que relumbraban al sol, y mas allá las distantes sierras perdidas tras vapores fantásticos, que se elevaban en un cielo azul y radiante; todo esto era un espectáculo nuevo, maravilloso que fascinó á los caballeros, y los hizo suspirar por la llegada del dia en que el pendon real de Isabel y de Fernando ondease sobre aquel resplandeciente castillo, que guardaba como una veladora atalaya aquel jardin de delicias.\"},{\"heading\":false,\"text\":\"Zaruhyemal bajó entre tanto de la hacanea, y llamó al postigo de una cerca.\"},{\"heading\":false,\"text\":\"El postigo se abrió instantáneamente.\"},{\"heading\":false,\"text\":\"Los cristianos desmontaron, entraron en un jardin, y un esclavo negro asió de las cabalgaduras y las introdujo en el jardin tras sus ginetes.\"},{\"heading\":false,\"text\":\"El postigo tornó á cerrarse.\"},{\"heading\":false,\"text\":\"El jardin era una maravilla, y á su fondo se alzaba una magnífica arcada sostenida por algunas columnas de alabastro.\"},{\"heading\":false,\"text\":\"Al fondo de la arcada habia una gran puerta, por la cual entró Zaruhyemal guiando á los cuatro caballeros.\"},{\"heading\":false,\"text\":\"Subieron una escalera, atravesaron una galería y entraron en una magnífica cámara, que parecia haber sido construida para albergar al genio de los amores.\"},{\"heading\":false,\"text\":\"El ambiente, la luz, los perfumes, los muebles, la forma de la cámara, sostenida por grupos de columnas, con fondos labrados y matizados con caprichosos colores, con su alta cúpula casi perdida en la oscuridad, con su fuente de mármol en que un claro surtidor murmuraba ténuemente, al par que las brisas agitaban los tapices y venian á saturarse en los perfumes, todo era allí voluptuoso, todo convidaba á amar.\"},{\"heading\":false,\"text\":\"--¿A quién pertenece este alcázar? dijo el Alcaide de los Donceles a Zaruhyemal.\"},{\"heading\":false,\"text\":\"--Al infante Muza-Ebn-Abil-Gazan, contestó la hermosa jóven, y suyas son tambien las armas y las preseas que vais á vestiros, y los caballos que vais á montar.\"},{\"heading\":false,\"text\":\"Y guiándolos, atravesó otra galería, abrió otra puerta y los introdujo en una sala de armas.\"},{\"heading\":false,\"text\":\"Los castellanos se maravillaron: jamás, ni en los alcázares de sus reyes, habian visto una tan rica armería.\"},{\"heading\":false,\"text\":\"Cuatro esclavos les ciñeron los arneses que eligieron: les vistieron túnicas de brocado, y ocultaron sus cabellos bajo tocas á la usanza africana.\"},{\"heading\":false,\"text\":\"Avanzaba el dia, y los castellanos, armados ya y á punto de poder pasar por walíes africanos, bajaron al jardin, y fuera de la cerca encontraron cuatro caballos de la mas pura raza árabe, encubertados de guerra.\"},{\"heading\":false,\"text\":\"Y cabalgaron y se despidieron de la doncella mora, y tomaron la vuelta de los montes guiados por un africano de la servidumbre de Muza, para entrar en Granada por el camino de Almería, como si llegasen por las marinas.\"},{\"heading\":false,\"text\":\"Y era ya tiempo.\"},{\"heading\":false,\"text\":\"El sol habia llegado á la mitad de su carrera.\"},{\"heading\":false,\"text\":\"En la plaza de Bib-Arrambla, el palenque abierto, ocupadas las galerías por una multitud numerosa, mostraba en uno de sus estremos la tienda de los mantenedores de la acusacion contra Zoraida.\"},{\"heading\":false,\"text\":\"En el otro estremo se levantaba un cadalso enlutado, en que la desdichada Zoraida estaba vestida de blanco entre sus damas.\"},{\"heading\":false,\"text\":\"Delante de la tienda de los mantenedores habia clavadas cuatro lanzas en la arena, y pendiente de cada lanza una reluciente adarga.\"},{\"heading\":false,\"text\":\"A siniestra mano se veia el estrado destinado á los jueces del campo.\"},{\"heading\":false,\"text\":\"Eran estos jueces el infante Muza-Ebn-Abil-Gazan, el wazir Aben-Comixa y el katíb Abd-el-Kerun.\"},{\"heading\":false,\"text\":\"Mas allá, guardado por esclavos, se veia un astillero lleno de lanzas de batalla y algunos caballos encubertados de guerra, trabados de los pies.\"},{\"heading\":false,\"text\":\"Todo revelaba á primera vista el grave asunto que se sustentaba en aquel coso, no hacia muchos dias engalanado de fiesta.\"},{\"heading\":false,\"text\":\"La sultana Zoraida, sentada sobre un divan de seda negra y oro en el cadalso, parecia tranquila, á pesar de que bajo aquel cadalso estaban hacinados ramages que debian ser la hoguera de la adúltera si los zegríes sostenedores de la acusacion triunfaban, ó si llegado el término del plazo no se presentaban caballeros para defender la inocencia de la acusada.\"},{\"heading\":false,\"text\":\"Desde el amanecer, una multitud inmensa llenaba las graderías, y gran número de damas y caballeros, aunque con sencillas vestiduras de luto, ocupaban los estrados.\"},{\"heading\":false,\"text\":\"Boabdil habia llevado hasta el colmo su crueldad asistiendo á la prueba con galas de fiesta.\"},{\"heading\":false,\"text\":\"Y el pueblo murmuraba del rey, al paso que todos se dolian de la sultana y maldecian á los zegríes.\"},{\"heading\":false,\"text\":\"A la salida del sol, un alférez ó porta-bandera de los acusadores, precedido de añafiles y atabales, y seguido de ginetes armados, pregonó la acusacion contra la sultana á son de trompeta y arrojó cuatro guantes en la arena, retando á los presentes y por venir que la inocencia de la sultana defendieren.\"},{\"heading\":false,\"text\":\"Tras el estrado de los jueces, algunos caballeros se agitaron con visibles muestras de contestar al reto, pero el infante Muza los contuvo.\"},{\"heading\":false,\"text\":\"Nadie contestó.\"},{\"heading\":false,\"text\":\"Y pasó el tiempo.\"},{\"heading\":false,\"text\":\"El pueblo se impacientaba.\"},{\"heading\":false,\"text\":\"El sol ascendia.\"},{\"heading\":false,\"text\":\"Llegó al fin la oracion de adohar[142].\"},{\"heading\":false,\"text\":\"Tornó á salir de la tienda de los zegríes el alférez en la misma forma que la vez anterior, repitió la acusacion y el reto, y como antes, nadie contestó á él.\"},{\"heading\":false,\"text\":\"Y pasaba el tiempo, el sol descendia; sino habia campeones que defendiesen la inocencia de la sultana, esta debia morir de muerte de fuego como adúltera y enemiga del rey, en el punto en que el sol tocase á su ocaso.\"},{\"heading\":false,\"text\":\"El semblante antes sereno de Zoraida palideció, mas de indignacion que de terror.\"},{\"heading\":false,\"text\":\"Creyó que su súplica habia sido desatendida por los caballeros cristianos.\"},{\"heading\":false,\"text\":\"Su orgullo de sultana se irritó.\"},{\"heading\":false,\"text\":\"Y tal vez un pensamiento distinto cruzó por su mente y la arrancó una lágrima.\"},{\"heading\":false,\"text\":\"Bien hubiera podido suceder que sus campeones hubieran sido acometidos en la vega por fuerzas superiores.\"},{\"heading\":false,\"text\":\"Tal vez la muerte les impedia llegar al sitio á donde los llamaban.\"},{\"heading\":false,\"text\":\"Corria en tanto el tiempo.\"},{\"heading\":false,\"text\":\"Al fin el sol, que descendia, solo dejó ver una estrecha faja de rojiza luz en los aleros de la plaza opuestos al occidente.\"},{\"heading\":false,\"text\":\"Las miradas de todos se fijaban con ansiedad en aquella línea luminosa.\"},{\"heading\":false,\"text\":\"El sol se habia trasformado para la sultana en un relój implacable.\"},{\"heading\":false,\"text\":\"En el momento en que sus rayos dejasen de tocar enteramente aquel alero, debia repetirse la acusacion y el reto, y si nadie respondia a él, debia declararse á la sultana desamparada de Dios, y por lo tanto culpable.\"},{\"heading\":false,\"text\":\"Al fin desapareció aquel último rayo, y el sol se hundió tras el horizonte.\"},{\"heading\":false,\"text\":\"El mueden[143] de la mezquita mayor llamó á los fieles á la oracion de _almagreb_[144].\"},{\"heading\":false,\"text\":\"De nuevo el alférez, con su comitiva, adelantó al centro del palenque; pero aun no habian acabado de resonar los clarines, cuando se oyó gran alarido y gritería por la parte del Zacatin, resonó la trompeta del alcaide de la puerta de la Al-Kaissería, y el mismo alcaide adelantó á caballo, llegó ante el rey Boabdil, hizo arrodillarse ante él al bruto, y anunció al rey que cuatro caballeros berberiscos solicitaban se les diese campo para defender como campeones la inocencia de la sultana.\"},{\"heading\":false,\"text\":\"El rey, pálido de despecho, concedió la licencia, y el alcaide se tornó á la puerta.\"},{\"heading\":false,\"text\":\"Agitóse el pueblo, desalentado ya: levantóse un sordo rumor, corrieron los escuderos con los caballos á la tienda de los acusadores, subieron los jueces al estrado, y acreció la palidez de la ansiedad en el rostro de la sultana.\"},{\"heading\":false,\"text\":\"Abrióse á punto la puerta de la Al-Kaissería, y arremetieron por ella cuatro ginetes berberiscos, que atravesaron á la carrera el palenque y llegaron al pie del cadalso de la sultana.\"},{\"heading\":false,\"text\":\"Al ver sus armas, sus penachos, sus galas y sus magníficos corceles, el pueblo y las damas y los caballeros aplaudieron.\"},{\"heading\":false,\"text\":\"Entretanto, los cuatro caballeros berberiscos que llevaban caladas las viseras de sus yelmos de encage, desmontaron, y uno de ellos subió la gradería del cadalso, se arrodilló ante la sultana, y la dijo en arábigo aljamiado:\"},{\"heading\":false,\"text\":\"--Poderosa señora: yo y esos tres caballeros, que en tu defensa conmigo son, somos cuatro hermanos berberiscos, que venimos de Africa, y desembarcados en Almería, sabiendo que está amenazada por los cristianos esta hermosa ciudad, hemos querido contribuir con nuestras vidas á su defensa.\"},{\"heading\":false,\"text\":\"Y viniendo su vía, hemos sabido por un alkarreño[145], la afliccion en que te hallas, y á tus pies nos ponemos para ofrecerte nuestras vidas, y cuanto somos y tenemos.\"},{\"heading\":false,\"text\":\"Calló el caballero, y la sultana le contempló un tanto en silencio.\"},{\"heading\":false,\"text\":\"Pero una esclava cristiana que estaba junto á ella y que escuchaba atentamente, y con no menos atencion miraba al caballero que para hablar con la sultana se habia levantado la visera, la dijo:\"},{\"heading\":false,\"text\":\"--Acepta, señora, porque ese que á tus pies tienes, no es otro que don Juan Chacon, señor de Cartagena, á quien escribiste aquellas letras por mi consejo.\"},{\"heading\":false,\"text\":\"Sonrió tristemente la sultana, mirando con agradecimiento al capitan castellano, y le dijo con voz conmovida:\"},{\"heading\":false,\"text\":\"--Dios te premie y premie á tus hermanos, caballero, por la merced que me haceis: yo os acepto como defensores de mi inocencia, que en Allah y en vosotros confio, volverá á brillar, aunque tan vilmente han pretendido mancillarla los traidores zegríes.\"},{\"heading\":false,\"text\":\"Don Juan Chacon besó la mano á la sultana, se caló la visera, bajó del cadalso, cabalgó con sus otros tres compañeros, y los cuatro, estendidos al pie del cadalso, esperaron á que segun ley y uso reconocido se pronunciasen la acusacion y el reto.\"},{\"heading\":false,\"text\":\"Resonaron al fin las trompetas, y el alférez acusó á la sultana y retó á nacidos y por nacer, á presentes y ausentes, á vivos y á muertos, á chicos y á grandes, en nombre de los mantenedores de la acusacion.\"},{\"heading\":false,\"text\":\"Cuando hubo concluido, don Juan Chacon adelantó un tanto su caballo, y dijo con voz pujante que todos escucharon y en aljamia:\"},{\"heading\":false,\"text\":\"--Mientes tú, en lo que dices, como cobarde y mal nacido, y miente quien te lo manda decir, y quien lo sostenga miente, y miente quien al escucharlo calle, y en prenda y en señal de que admitimos el reto de los calumniadores de poder á poder y á todo trance de batalla, ved lo que haré y harán conmigo mis hermanos.\"},{\"heading\":false,\"text\":\"Y atravesando el palenque á media rienda, los cuatro caballeros hirieron con sus lanzas de dos hierros las adargas que cada uno de los mantenedores de la acusacion tenian suspendida de una pica clavada en tierra delante de su tienda.\"},{\"heading\":false,\"text\":\"Oyóse un ruido vibrante y metálico, las adargas cayeron á la arena, y los caballeros defensores tomaron campo y fueron á situarse al otro lado del palenque vuelta la espalda á la sultana, á tiempo que Hamet-Zegrí, Mahandin, Mahandon y Mahomet-Zegrí, tomando las adargas heridas de manos de sus escuderos, cabalgaron y adelantaron en el palenque, hasta ponerse frente á frente de los cuatro castellanos.\"},{\"heading\":false,\"text\":\"Mahomet-Zegrí enfiló con el Alcaide de los Donceles, don Diego Fernandez de Córdoba; Hamet-Zegrí, con don Manuel Ponce de Leon; Mahandon con don Alonso de Aguilar, y Mahandin con don Juan Chacon.\"},{\"heading\":false,\"text\":\"Bajaron los jueces del campo á la arena, demandaron juramento á los caballeros de lidiar como buenos y leales sin ayuda de hechicerías ni amuletos, les partieron el sol[146], y el infante Muza dijo en alta voz:\"},{\"heading\":false,\"text\":\"--Campo cerrado y batalla os concedemos, caballeros; partid y haced vuestro deber.\"},{\"heading\":false,\"text\":\"Al mismo tiempo hicieron señal los añafiles y los atabales, el rey arrojó á la arena un baston de oro, y los combatientes partieron uno contra otro, chocándose entre una nube de polvo en medio del palenque.\"},{\"heading\":false,\"text\":\"Retumbó el encuentro rudo y poderoso en los ámbitos de la plaza, y cuando se desvaneció el remolino, la multitud miró con ansiedad.\"},{\"heading\":false,\"text\":\"Todos los caballeros estaban en su lugar.\"},{\"heading\":false,\"text\":\"Las picas habian resbalado de las acicaladas adargas.\"},{\"heading\":false,\"text\":\"Tomaron de nuevo campo, y se encontraron con igual ímpetu.\"},{\"heading\":false,\"text\":\"La pica del Alcaide de los Donceles, arrojó desapoderado de los arzones al feroz Mohamet-Zegrí, y los otros seis caballeros no encontrando ventaja, volvieron á tomar campo.\"},{\"heading\":false,\"text\":\"Mahomet-Zegrí, en tanto, se habia levantado fuera de sí de cólera, yendo con rabia á desjarretar el caballo de don Diego Fernandez de Córdoba.\"},{\"heading\":false,\"text\":\"Pero las habia con un enemigo esperimentado, y le encontró pie á tierra junto á si con la espada en alto.\"},{\"heading\":false,\"text\":\"Antes de que el zegrí hubiera podido adargarse, vinieron al suelo las plumas y la mitad de su bonete, á un tremendo tajo del castellano.\"},{\"heading\":false,\"text\":\"El moro llevaba lo peor.\"},{\"heading\":false,\"text\":\"Acosábale don Diego, y caian sobre él los pesados golpes de su espada de á dos manos, rebotando sobre su adarga de Fez con igual ímpetu que el recio granizo de la tempestad sobre las altas cúpulas.\"},{\"heading\":false,\"text\":\"Retrocedia Mohamet, dejando tras sí pedazos de su desguarnecida armadura y girones de su rico sayo de púrpura.\"},{\"heading\":false,\"text\":\"Acorralábale sin descanso el bravo Alcaide de los Donceles.\"},{\"heading\":false,\"text\":\"Al cabo le puso entre su espada y la valla que sustentaba uno de los costados del cadalso de la sultana.\"},{\"heading\":false,\"text\":\"Rugia el moro como un tigre herido por un leon, y era espantoso de ver su semblante y los furiosos tajos que descargaba en vano sobre la adarga damasquina que embrazaba su enemigo.\"},{\"heading\":false,\"text\":\"Y duraba el combate.\"},{\"heading\":false,\"text\":\"Corria la sangre de entrambos campeones.\"},{\"heading\":false,\"text\":\"Zoraida, pálida y aterrada, miraba con ansiedad á don Diego, y éste cobró alientos al ver la suplicante mirada de la sultana.\"},{\"heading\":false,\"text\":\"Enojóle tanta resistencia; arrojó lejos de sí la adarga, alzó su espada á dos manos, describió con ella un ancho círculo sobre su cabeza, y esclamando, olvidado en su furor de su incógnito y del lugar en que se encontraba:--_¡Santiago y Castilla!_--la dejó caer con el ímpetu de una encina derrumbada por el huracan, sobre el moro.\"},{\"heading\":false,\"text\":\"Nadie, entre el estruendo del combate, que allá en el centro del palenque se sustentaba á caballo, oyó el grito de guerra del Alcaide de los Donceles, sino Mohamet-Zegrí, que cayó por tierra como herido por un rayo, esclamando:\"},{\"heading\":false,\"text\":\"--¡Traicion! ¡son castellanos!\"},{\"heading\":false,\"text\":\"Y su sangre se heló, rodaron sus ojos en sus órbitas, y la lividez de la muerte alteró su semblante.\"},{\"heading\":false,\"text\":\"El generoso alcaide saludó á la sultana.\"},{\"heading\":false,\"text\":\"Luego tomó el alfange del moro y le cortó la cabeza.\"},{\"heading\":false,\"text\":\"Subió la gradería del dadalso y puso en su última grada, á los pies de la sultana, aquel sangriento despojo.\"},{\"heading\":false,\"text\":\"Despues recogió su adarga, requirió su caballo, montó en él, y se retiró á un lado para ver la suerte del combate, que seguia encarnizado, entre los otros seis caballeros.\"},{\"heading\":false,\"text\":\"Los que mas á punto de vencimiento estaban eran don Juan Chacon y Mahandin.\"},{\"heading\":false,\"text\":\"Entrambos habian roto sus lanzas.\"},{\"heading\":false,\"text\":\"Entrambos se habian desguarnecido la cabeza y peleaban con ella descubierta.\"},{\"heading\":false,\"text\":\"Entrambos, apenas podian repararse por las adargas rotas y abolladas por los furiosos golpes.\"},{\"heading\":false,\"text\":\"Cruzaban y volvian á cruzarse los caballos.\"},{\"heading\":false,\"text\":\"Cada encuentro era una herida, cada choque un amago de muerte.\"},{\"heading\":false,\"text\":\"El moro mostraba los ojos inyectados de sangre, como la hiena que olfatea los cadáveres.\"},{\"heading\":false,\"text\":\"Don Juan Chacon le fascinaba con su ardiente mirada.\"},{\"heading\":false,\"text\":\"Pasaba el tiempo, la luz menguaba; la noche tendia ya sobre los cielos su manto de tinieblas.\"},{\"heading\":false,\"text\":\"Era preciso concluir.\"},{\"heading\":false,\"text\":\"Don Juan Chacon apretó los dientes y los puños, y su espada se rompió en la adarga del moro, dejándole el brazo desguarnecido,\"},{\"heading\":false,\"text\":\"Y sin darle tiempo para rehacerse, veloz como el relámpago, el señor de Cartagena tomó de su arzon la maza de armas, describió con ella en alto tres círculos; y la lanzó de sí.\"},{\"heading\":false,\"text\":\"La maza partió silbando y fué á chocar en la cabeza desarmada de Mahandin, que cayó por la grupa de su caballo, horriblemente ensangrentado.\"},{\"heading\":false,\"text\":\"Despues no se movió.\"},{\"heading\":false,\"text\":\"Estaba muerto.\"},{\"heading\":false,\"text\":\"Don Juan Chacon desmontó, cortó á Mahandin la cabeza, la llevó al cadalso de la sultana y la puso junto á la de Mohamet-Zegrí.\"},{\"heading\":false,\"text\":\"Un silencio de horror dominaba en el estenso palenque.\"},{\"heading\":false,\"text\":\"Por órden de Muza, esclavos con antorchas encendidas rodeaban á los combatientes alumbrándolos.\"},{\"heading\":false,\"text\":\"Aquello tenia un aspecto terriblemente fantástico.\"},{\"heading\":false,\"text\":\"Don Juan Chacon montó de nuevo á caballo y fué á situarse junto á la valla, al lado del Alcaide de los Donceles.\"},{\"heading\":false,\"text\":\"Solo rompian el lúgubre silencio el estruendo del combate de los cuatro caballeros y los alaridos de los parientes de los dos zegríes cuyas cabezas lívidas y ensangrentadas estaban á los pies de Zoraida.\"},{\"heading\":false,\"text\":\"Hicieron los jueces salir de la plaza á aquellas gentes para que no desalentasen con sus quejas á los caballeros que lidiaban, y luego solo se escuchó el áspero ruido de los golpes del combate.\"},{\"heading\":false,\"text\":\"Don Manuel Ponce de Leon, y don Alonso de Aguilar sintieron una generosa envidia al ver que sus compañeros habian _fenescido sus armas con tanta prez_, como se decia entonces, y arremetieron con nuevo furor á los moros.\"},{\"heading\":false,\"text\":\"El primero y Hamet-Zegrí habian tomado lanzas nuevas, y justaban como en torneo, entrando y saliendo en liza con gran bizarría y corage.\"},{\"heading\":false,\"text\":\"Parecia, á pesar de hacer ya gran tiempo que lidiaban, que no se habian tocado á los arneses, y sin embargo, crugian las adargas y recejaban los caballos, no siendo bastantes á sostener los poderosos golpes.\"},{\"heading\":false,\"text\":\"Hamet-Zegrí, enojado de la duracion del combate, furioso con la muerte desastrada de su pariente Mahandin, plantó su caballo en firme cuando venia á encontrarle Ponce de Leon á toda carrera, hizo el cuerpo atrás, tendió el brazo y le arrojó la lanza, que hendió los aires silbando como una jara desprendida de una ballesta.\"},{\"heading\":false,\"text\":\"Hubiéralo pasado mal el castellano á herirle de lleno el asta; pero la rabia hizo perder el tino al moro, descompúsose, y su pica resbaló en la adarga del castellano, que aguijó á su caballo para encontrar en la jacerina á Hamet-Zegrí.\"},{\"heading\":false,\"text\":\"El moro conoció lo terrible é inevitable del golpe, y encabritó su caballo, poniéndose casi en pie y cubriéndose con él.\"},{\"heading\":false,\"text\":\"La lanza de don Manuel hirió en el pecho por bajo de la cubertura al corcel, que cayó de espaldas, cogiendo debajo á su ginete.\"},{\"heading\":false,\"text\":\"El cristiano esperó á que se levantase; pero Hamet-Zegrí permaneció en tierra junto á su caballo muerto; el caparazon de hierro, al caer sobre él, habia roto su pecho, y por su boca manaba la sangre á borbotones.\"},{\"heading\":false,\"text\":\"Don Manuel Ponce de Leon cortó la cabeza á Hamet-Zegrí, fué al cadalso de la sultana, puso á sus pies aquella tercera cabeza, y fué á reunirse á sus amigos.\"},{\"heading\":false,\"text\":\"Y entonces la atencion general se fijó en don Alonso de Aguilar y en Mahandon.\"},{\"heading\":false,\"text\":\"El moro, desalentado ya por la muerte de sus compañeros, se batia con la fuerza de la desesperacion.\"},{\"heading\":false,\"text\":\"Suelto, ágil, vigoroso, forzudo, giraba como un torbellino en torno del cristiano; revolvíase este, encontrábanse, se martillaban, volvian á separarse, y se chocaban de nuevo.\"},{\"heading\":false,\"text\":\"Y parecia que la esperanza perdida daba fuerzas y actividad al moro.\"},{\"heading\":false,\"text\":\"Rompió la espada y tomó el hacha de armas: lanzóla á su enemigo, y la rechazó su adarga: entonces desnudó su puñal, arrimó los acicates á su corcel, y al pasar ceñido al de don Alonso, abrió los brazos, y con una ligereza increible, asió al castellano del cuello, pretendiendo derribarle del caballo.\"},{\"heading\":false,\"text\":\"Pero don Alonso se afirmó en los estribos; lanzó lejos de sí la adarga y la espada, abrazó al moro, le arrancó de los arzones, y sujetándole con un brazo vigoroso, hundió por tres veces en su cuello, bajo el falso de su armadura, su puñal de misericordia[147].\"},{\"heading\":false,\"text\":\"El moro abrió los brazos y cayó muerto á los pies del caballo de don Alonso, que echó pie á tierra, cortó la cabeza á su enemigo, y fué á colocarla junto á las otras tres en el cadalso de la sultana.\"},{\"heading\":false,\"text\":\"El pueblo, hasta entonces silencioso, lanzó una inmensa aclamacion de alegría, demostrando cuánto eran odiosos los zegríes.\"},{\"heading\":false,\"text\":\"Sonaron las trompetas en alto alarido de triunfo, y Muza, bajando á la sangrienta liza con los jueces del campo, gritó en medio del silencio del pueblo ansioso por escuchar sus palabras y señalando las cuatro cabezas lívidas de los zegríes alumbradas por cien antorchas:\"},{\"heading\":false,\"text\":\"--¡Hé aquí la justicia del Señor Altísimo, Unico y Misericordioso!\"},{\"heading\":false,\"text\":\"¡La sultana Zoraida es inocente!\"},{\"heading\":false,\"text\":\"Entonces adelantó una tropa de esclavos africanos en cuyo centro iba un hombre vestido de rojo.\"},{\"heading\":false,\"text\":\"Aquel hombre era el verdugo.\"},{\"heading\":false,\"text\":\"Tomó las cabezas de los vencidos, y se alejó con ellas.\"},{\"heading\":false,\"text\":\"Aquellas cabezas fueron puestas en escarpias en las puertas del castillo de Bib-Ataubin, como convenia se hiciese con asesinos y calumniadores.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"En tanto el rey bajó precipitadamente del estrado real y fué á estrechar entre sus brazos á la sultana.\"},{\"heading\":false,\"text\":\"Zoraida se retiró con horror.\"},{\"heading\":false,\"text\":\"--¡Aparta, asesino! le dijo: desde hoy, tú en la Alhambra, yo en el Albaicin.\"},{\"heading\":false,\"text\":\"Y arrojándose entre los brazos de Muza, que venia á declararla libre, salió de la plaza acompañada de los jueces y escoltada por los cuatro caballeros, castellanos, sus defensores.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Al dia siguiente, mientras los cuatro caballeros, vueltos de la Azubia á donde habian ido á tomar sus armas y sus caballos, curaban en secreto sus heridas en sus tiendas, en el Real de Santa Fé, un escudero del infante Muza-Ebn-Abil-Gazan, en nombre de la sultana Zoraida, les entregó como presentes magníficas joyas, y los caballos y armas con que habian vencido á los zegríes.\"},{\"heading\":false,\"text\":\"Al mismo tiempo, uno de los mas nobles caballeros de Granada, yendo de paz, entregó á los reyes Católicos un pergamino rodado y sellado con el sello de oro de la sultana, en que esta les relataba la grande hazaña de sus cuatro defensores.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"}]},{\"title\":\"El patio de los leones. — capítulo XVII: Los pronósticos.\",\"blocks\":[{\"heading\":false,\"text\":\"A medida que trascurria el tiempo, se iba haciendo mas angustiosa la situacion de Granada.\"},{\"heading\":false,\"text\":\"Los cristianos la cercaban por la parte de la vega y de las montañas á la parte de Almería, y sus campeadores corrian hasta sus puertas, llegando el caso de no atreverse á salir fuera de ellas los habitantes, por temor de ser muertos ó cautivos.\"},{\"heading\":false,\"text\":\"Solamente por la parte de las Alpujarras, lugar montañoso y habitado por gentes incontratables y bravías, estaban libres del cerco de los cristianos.\"},{\"heading\":false,\"text\":\"Por allí podia venir un refuerzo del Africa.\"},{\"heading\":false,\"text\":\"Pero Boabdil era débil, y los reyes de Castilla demasiado temidos, y los musulmanes de Africa abandonaron á sí misma aquella hermosa ciudad en donde estaban acorralados los últimos restos del imperio de los agarenos en España.\"},{\"heading\":false,\"text\":\"Cada dia acontecia una nueva hazaña de los cristianos, tal y tan grande, que ponia pavor en el ánimo de los sitiados.\"},{\"heading\":false,\"text\":\"Una noche, los habitantes de Granada de la parte del Zacatin, de la Al-Kaissería, y de los alrededores de la mezquita, despertaron asustados á las voces de ¡al arma! de los guardas nocturnos.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Dormia entonces Boabdil en el mirador de Lindaraja.\"},{\"heading\":false,\"text\":\"Frente á sí tenia la sala de las Dos Hermanas.\"},{\"heading\":false,\"text\":\"Mas allá el patio de los Leones.\"},{\"heading\":false,\"text\":\"Luego la terrible cámara de los Abencerrages.\"},{\"heading\":false,\"text\":\"Parecia que allí le habia llevado el remordimiento.\"},{\"heading\":false,\"text\":\"Boabdil no sabia separarse de aquel patio y de sus habitaciones.\"},{\"heading\":false,\"text\":\"Parecia que le llamaban á sí las sangrientas sombras de Aben-Ahmed y de los treinta y seis caballeros abencerrages degollados.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"El rey soñaba bajo el fresco halago de las auras que entraban saturadas de las fragancias de los cármenes por las celosías del mirador.\"},{\"heading\":false,\"text\":\"La noche era plácida y tranquila.\"},{\"heading\":false,\"text\":\"Los luceros brillaban allá perdidos en la inmensidad.\"},{\"heading\":false,\"text\":\"Cantaban los ruiseñores solitarios entre las alamedas del rio.\"},{\"heading\":false,\"text\":\"Y sin embargo, el sueño del rey era terrible.\"},{\"heading\":false,\"text\":\"Una horrorosa pesadilla de sangre.\"},{\"heading\":false,\"text\":\"Parecíale que por la puerta de la sala de los Abencerrages salia Aben-Ahmed, y tras él sus treinta y seis compañeros con las cabezas en las manos.\"},{\"heading\":false,\"text\":\"Cada una de aquellas cabezas dejaba caer sobre el pavimento un chorro de sangre.\"},{\"heading\":false,\"text\":\"Y los fantasmas adelantaban en procesion lúgubre y silenciosa.\"},{\"heading\":false,\"text\":\"Y llegaban al rey y suspendian sucesivamente sobre su cabeza sus cabezas cercenadas y la bañaban en caliente sangre.\"},{\"heading\":false,\"text\":\"El rey luchaba por apartar de sí aquella vision terrible y no podia.\"},{\"heading\":false,\"text\":\"Pero de repente le despertaron descompasadas voces, y estruendo de gentes que corrian y de armas que se chocaban.\"},{\"heading\":false,\"text\":\"Y las voces decian en recio alarido:\"},{\"heading\":false,\"text\":\"--¡A las armas! ¡á las armas! ¡los cristianos están en la ciudad!\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Despertó el rey y salió de su lecho.\"},{\"heading\":false,\"text\":\"Apenas se habia levantado cuando vió delante de sí á su hermano bastardo el infante Muza.\"},{\"heading\":false,\"text\":\"--¿Qué significa esto, hermano mio? dijo el rey.\"},{\"heading\":false,\"text\":\"--Esto significa, que tanta infamia, tanto crímen, tanta inocente sangre vertida, trae sobre nosotros la cólera de Dios.\"},{\"heading\":false,\"text\":\"--¡Tú tambien, hermano! ¡tú tambien! esclamó con angustia el rey.\"},{\"heading\":false,\"text\":\"--Los cristianos se atreven ya á entrar en nuestra ciudad y á poner el nombre de sus ídolos en la puerta de la mezquita.\"},{\"heading\":false,\"text\":\"--¡No te entiendo!\"},{\"heading\":false,\"text\":\"--¡Plaza! ¡plaza! gritó una voz al mismo tiempo en el patio de los Leones. ¡Quiero ver al poderoso sultan!\"},{\"heading\":false,\"text\":\"--Hé ahí al arrayaz Abd-Allah-ebn-Tarfe que llega dijo Muza. El te dirá el atrevimiento de los cristianos.\"},{\"heading\":false,\"text\":\"Entró á la sazon un moro atlético, armado de todas armas:\"},{\"heading\":false,\"text\":\"Llevaba en la mano un carton dorado, en el centro del cual, se veia escrito en grandes letras azules castellanas, el mote: AVE MARIA.\"},{\"heading\":false,\"text\":\"La advocacion mas dulce de la santa Vírgen Madre de Dios.\"},{\"heading\":false,\"text\":\"El moro estaba pálido y convulso, y sus ojos despedian llamas sacudiendo con furor el carton entre sus manos.\"},{\"heading\":false,\"text\":\"--¿Qué es eso? dijo Boabdil.\"},{\"heading\":false,\"text\":\"--Esto es, contestó Tarfe, que ese infiel á quien Dios maldiga, ese cristiano Hernan Perez del Pulgar, á quien llaman entre los suyos el de las _fazañas_, ha clavado sobre la puerta de alambre de la mezquita mayor este cartel con el nombre de María.\"},{\"heading\":false,\"text\":\"--¿Pero habrá encontrado el infiel la muerte? esclamó colérico el rey.\"},{\"heading\":false,\"text\":\"--El maldito ha escapado matando á alguno de los guardas.\"},{\"heading\":false,\"text\":\"--¿Pero si ha escapado, cómo le habeis conocido?\"},{\"heading\":false,\"text\":\"--Conocióle á la luz de las antorchas con que acudieron algunos vecinos un guarda que ha sido durante algun tiempo cautivo de los cristianos.\"},{\"heading\":false,\"text\":\"¿Y quién otro que el bravo Hernando del Pulgar pudiera atreverse á tanto?\"},{\"heading\":false,\"text\":\"¿No sabes que él con algunos pocos de los suyos tomó la fortaleza del Salar á escala franca, por lo cual sus reyes le hicieron alcaide de aquella fortaleza?\"},{\"heading\":false,\"text\":\"¿No sabes que desde ella nos ha corrido la tierra, nos ha incendiado las mieses y nos ha cogido cautivos y rebaños?\"},{\"heading\":false,\"text\":\"¿Acaso ignoras, ni lo ignora nadie, quién es Hernan Perez del Pulgar?\"},{\"heading\":false,\"text\":\"¿No sabes que el mote jactancioso que tiene en su escudo ese caballero es: _El pulgar quebrar y no doblar_?\"},{\"heading\":false,\"text\":\"--Dios permite que seamos humillados, esclamó con una vergonzosa desesperacion el rey.\"},{\"heading\":false,\"text\":\"--Pero quien nos humilla tiene cabeza, esclamó con energía Tarfe: dame licencia, señor, y yo iré á los Reales de Isabel y de Fernando por la cabeza de Pulgar.\"},{\"heading\":false,\"text\":\"--Vé, vé, mi valiente arrayaz, que siendo tú quien vas, no dudo que lavarás la afrenta que nos han hecho los cristianos.\"},{\"heading\":false,\"text\":\"Vé, mi valiente Tarfe, vé, y que Allah vaya en tu ayuda.\"},{\"heading\":false,\"text\":\"Tarfe y Muza salieron, salieron los que le acompañaban, y el rey quedó solo.\"},{\"heading\":false,\"text\":\"Volvióse á reclinar en el lecho, volvieron á entorpecerse sus sentidos, y volvió á su vision de sangre.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"En efecto, el bravo alcaide del Salar Hernan Perez del Pulgar, el de _las hazañas_, habia entrado en Granada.\"},{\"heading\":false,\"text\":\"Aquella tarde habia llamado á su tienda en el Real de Santa fé á sus escuderos.\"},{\"heading\":false,\"text\":\"Eran estos quince, apreciados en gran manera por su valor.\"},{\"heading\":false,\"text\":\"Sentáronse y se descubrieron respetuosamente ante su capitan, que les dijo con voz grave:\"},{\"heading\":false,\"text\":\"--Bien conozco, hidalgos, vuestra lealtad y vuestro esfuerzo, de que me habeis dado grandes pruebas, y yo á mi vez os pago prefiriéndoos para confiaros un gran intento, que llevado á cabo, pondrá nuestros nombres en el templo de la fama.\"},{\"heading\":false,\"text\":\"Miraron con anhelo sus escuderos á Pulgar, que continuó de la misma manera reposada y tranquila.\"},{\"heading\":false,\"text\":\"--Esta noche voy á entrar en Granada con la ayuda de Dios; pero como me tocaria al alma el que interponiéndose algunos infieles, malograsen mi propósito, quiero que vengais conmigo, no como en recompensa de la estimacion en que os tengo, ni como mandato, mas os lo habré en gran merced si consentís.\"},{\"heading\":false,\"text\":\"Levantóse uno de los escuderos llamado Francisco de Bedmar, y dijo:\"},{\"heading\":false,\"text\":\"--Donde vayas tú, capitan, iremos nosotros sin dudar, y si algun temor podemos tener, no será otro sino el de la pérdida de tan noble y valiente caudillo.\"},{\"heading\":false,\"text\":\"Miróle de hito en hito Pulgar.\"},{\"heading\":false,\"text\":\"--Tú, Bedmar, dijo, escalaste los muros de Alhama; tambien os he visto á vosotros tomar á escala franca el castillo del Salar, combatir en Velez y en Baza en los mismos llanos de la vega. Y ahora que estais á mi lado, _¿por qué poneis en Dios tan poca confianza y me contais con los muertos?_[148].\"},{\"heading\":false,\"text\":\"--Mal cumpliríamos con lo que le debemos, Hernando, observó otro de ellos, sino te aconsejáramos, cuando pretendes correr á una perdicion cierta.\"},{\"heading\":false,\"text\":\"--No es consejo lo que os pido, dijo gravemente Hernan Perez; lo que quiero es que me acompañeis hasta las puertas de Granada. Dios nos libertará, y si nos acorralan ¿qué importa? _ya aprendimos en el Zenete la manera de hacernos paso_[149].\"},{\"heading\":false,\"text\":\"Tendió, dicho esto, la mano á Bedmar y á los otros escuderos, y diciéndoles el lugar de la vega donde debian reunirse, despidiólos.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Era cerca del amanecer.\"},{\"heading\":false,\"text\":\"En la confluencia del Darro y del Genil, aparecieron viniendo de la parte de la vega algunos ginetes á caballo.\"},{\"heading\":false,\"text\":\"Solo podian apreciarse sus bultos porque la noche era lóbrega.\"},{\"heading\":false,\"text\":\"Detúvose al llegar á aquel punto el que cabalgaba delante de los ginetes, y al hablarles dejó conocer en su acento que era Hernando del Pulgar.\"},{\"heading\":false,\"text\":\"Los ginetes que le seguian eran sus escuderos.\"},{\"heading\":false,\"text\":\"--Ahora bien, amigos mios, y ya que hemos llegado, dijo Pulgar, ved de recoger entre esas alamedas algun ramage y procuradle seco en tal manera que arda á maravilla.\"},{\"heading\":false,\"text\":\"--Cómo, ¿pretendes poner fuego á Granada? dijo uno de los escuderos llamado Aguilera.\"},{\"heading\":false,\"text\":\"--Si tal, contestó Pulgar; y en Dios confio que hemos de volver al Real alumbrados por las llamas que devoren sus ponderadas casas y sus ricos alcázares.\"},{\"heading\":false,\"text\":\"Quedaron atónitos los hidalgos, pero conociendo la tenacidad de Pulgar, obedecieron y cargando de ramage seco la grupa de sus caballos, siguieron á su capitan, marchando por el cauce del Darro, para que con el ruido de la corriente no se notase el de las pisadas de los caballos.\"},{\"heading\":false,\"text\":\"Merced á esta precaucion y á lo oscurísimo de la noche, pasaron sin ser sentidos de los atalayas moros, por delante del castillo de Bib-Ataubin, y llegaron al puente de la puerta Real ó Bib-Al-Malekí, bajo el que se agruparon los quince escuderos en rededor de Pulgar.\"},{\"heading\":false,\"text\":\"Aguardadme aquí, les dijo, y tú, Pedro, que conoces mejor que nosotros la ciudad en que te criaste, carga en tu caballo ese ramage y sígueme.\"},{\"heading\":false,\"text\":\"Trabóse gran altercado entre los hidalgos.\"},{\"heading\":false,\"text\":\"Ninguno queria menos que acompañar á su capitan; vinieron á disputa, alteráronse, y á tal punto llegó la porfia, que Pulgar se vió obligado á consentir en que, echándolo á la suerte, le acompañasen algunos.\"},{\"heading\":false,\"text\":\"Al fin, guiado por Pedro, y acompañado de Bedmar y de otros cuatro, el alcaide del Salar siguió bajo el largo y lóbrego puente con el agua á la rodilla, penetró en la ciudad y siguió á oscuras á lo largo de la _Ribera de los curtidores_ hasta llegar frente por frente de su edificio magnífico[150].\"},{\"heading\":false,\"text\":\"Treparon uno tras otro el poco elevado muro que encajonaba el rio, y por una estrechísima calleja, que apenas daba lugar á un arroyo de desagüe[151], penetraron en una plaza de poca estension, donde se alzaban uno frente á otro dos altísimos edificios.\"},{\"heading\":false,\"text\":\"Era el uno la universidad[152] granadina, emporio de ciencia, santuario del saber, á donde habian refluido los sabios de Córdoba y Sevilla, y cuantos habian sido arrojados por las armas castellanas hasta aquel último recinto donde flotaba en España la enseña del Islam; el otro la gran mezquita de Granada[153], con su puerta de alambre dorado, sus ricos agimeces de mármol y sus aleros labrados, si bien entonces no podia verse tanta maravilla á causa de la gran oscuridad de la noche.\"},{\"heading\":false,\"text\":\"--¿Hemos llegado? dijo el alcaide del Salar al morisco Pedro del Pulgar[154].\"},{\"heading\":false,\"text\":\"--Si señor, dijo el cristiano nuevo: escucha cómo zumba el viento en el altísimo almiznar de la mezquita; esta pared que nos guarda es de la universidad, y esa gran casa oscura que ves en la sombra, la del fakí de los fakíes.\"},{\"heading\":false,\"text\":\"Acrecentóse la impaciencia de Pulgar, y pidiendo á Pedro menesteres de encender, prendió fuego al hachon que consigo traia, y sacó de debajo de su sobrevesta un carton dorado, en que se veia un nombre escrito en letras azules góticas.\"},{\"heading\":false,\"text\":\"--¡El _Ave María_! esclamaron con asombro los escuderos,\"},{\"heading\":false,\"text\":\"Pulgar llegó á la puerta de la mezquita y se arrodilló: los escuderos se arrodillaron tambien.\"},{\"heading\":false,\"text\":\"--Sed vosotros testigos, dijo á los cinco, que estaban entusiasmados y conmovidos con el tiernísimo interés de Pulgar, de como tomo posesion de esta mezquita en nombre de los reyes de Castilla, consagrándola desde ahora á la Reina del cielo, cuyo nombre dejo en poder de los infieles hasta que llegue la hora del rescate[155].\"},{\"heading\":false,\"text\":\"Y atando en el pomo de su puñal las cintas de que pendia el cartel, le clavó de una sola puñalada entre las mallas de alambre de la puerta.\"},{\"heading\":false,\"text\":\"Luego se levantó, y se levantaron los escuderos, y Pulgar dijo á Pedro:\"},{\"heading\":false,\"text\":\"--¿Dónde está la Al-Kaissería?\"},{\"heading\":false,\"text\":\"Pedro le señaló una estrecha calleja que comunicaba con el Zacatin, y le dijo:\"},{\"heading\":false,\"text\":\"--Por allí, señor.\"},{\"heading\":false,\"text\":\"--Alumbra y guia.\"},{\"heading\":false,\"text\":\"Cuando llegaron á la puerta de la Al-Kaissería, Pulgar le dijo:\"},{\"heading\":false,\"text\":\"--Echa ahí ese ramaje.\"},{\"heading\":false,\"text\":\"Y cuando Pedro le hubo echado, Pulgar arrojó sobre él el hacha encendida.\"},{\"heading\":false,\"text\":\"Pero á punto sintieron pasos de muchos hombres con faroles encendidos que rondaban guardando aquel riquísimo barrio.\"},{\"heading\":false,\"text\":\"Verlos y acometerlos espada en mano fué una misma cosa.\"},{\"heading\":false,\"text\":\"Gritaron los moros, alborotóse por aquella parte la ciudad, y Pulgar, temiendo que le venciese la muchedumbre, gritó á sus escuderos:\"},{\"heading\":false,\"text\":\"--¡Por el mismo camino! ¡corazon sereno, y espada pronta!\"},{\"heading\":false,\"text\":\"Y rompiendo por medio de los moros, escapó[156].\"},{\"heading\":false,\"text\":\"Y las llamas amenazaban á la Al-Kaissería, y los moros, acudiendo de todas partes, gritaban:\"},{\"heading\":false,\"text\":\"--¡Al arma! ¡los cristianos!\"},{\"heading\":false,\"text\":\"Aquellas eran las voces que habian llegado hasta el rey.\"},{\"heading\":false,\"text\":\"El cartel aquel, el que Tarfe habia llevado á la Alhambra.\"}]},{\"title\":\"El patio de los leones. — capítulo XVIII: Siguen los pronósticos.\",\"blocks\":[{\"heading\":false,\"text\":\"Granada, tan venturosa antes, tan afortunada, habia llegado al punto de que todo para ella se convirtiese en desdicha y mala ventura.\"},{\"heading\":false,\"text\":\"Sus caudillos emigraban á Africa ó morian en la Vega.\"},{\"heading\":false,\"text\":\"Sus sabios y sus fakíes estaban siempre pronosticando desdichas.\"},{\"heading\":false,\"text\":\"Todos tenian, no la fé de la salvacion, sino la certeza del acabamiento de la patria.\"},{\"heading\":false,\"text\":\"Todos miraban con terror al porvenir, y á un porvenir cercano.\"},{\"heading\":false,\"text\":\"Y Boabdil entretanto se adormia.\"},{\"heading\":false,\"text\":\"Boabdil no procuraba acabar con los bandos uniéndolos bajo su mano, y dándoles de este modo fuerza.\"},{\"heading\":false,\"text\":\"Por otra parte, la unión de Aragon y de Castilla, de España, en fin, bajo un mismo cetro, hacia imposible la lucha.\"},{\"heading\":false,\"text\":\"Maldecian, sin embargo, á Boabdil.\"},{\"heading\":false,\"text\":\"Como si él, á quien historiadores benévolos han llamado el _Desdichadillo_, hubiera podido oponerse á los decretos del destino:\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Es verdad que su inercia, su molicie, habian llegado al último punto.\"},{\"heading\":false,\"text\":\"No se le veia salir de los departamentos del patio de los Leones, donde tenia su harem, donde estaba el panteon en que reposaban sus antepasados, donde existia la fatal sala que encerraba sus remordimientos.\"},{\"heading\":false,\"text\":\"En aquel patio le tenian aprisionado los recuerdos de su dinastía, esto es, el pasado; sus placeres, esto es, el presente; y su conciencia, que venia a ser el decreto de su porvenir.\"},{\"heading\":false,\"text\":\"Y allí recibia las noticias, funestas todas, que le traian sus caballeros.\"},{\"heading\":false,\"text\":\"Allí escuchaba con la cabeza inclinada á sus sabios que le aconsejaban.\"},{\"heading\":false,\"text\":\"A sus valientes que pretendian sacarle de su inercia.\"},{\"heading\":false,\"text\":\"Allí, en la noche del mismo dia en que Tarfe le pidió licencia para ir á retar al audaz cristiano que se habia atrevido á penetrar en Granada, recibió la noticia de un nuevo desastre, que venia á ser un nuevo pronóstico de desgracias.\"}]},{\"title\":\"El patio de los leones. — capítulo XIX: El triunfo del ave maria.\",\"blocks\":[{\"heading\":false,\"text\":\"Apenas el sol habia desvanecido las nieblas de la noche anterior, y sus rayos tibios aun se tendian sobre Santa Fé, cuando un confuso rumor de pasos acelerados de armas que se chocaban y de gentes que subian á toda prisa las escaleras que conducian á los adarves, se dejó oir por la parte que mira á Granada.\"},{\"heading\":false,\"text\":\"Los reyes don Fernando y doña Isabel, el príncipe, don Juan, las infantas doña Juana y doña Isabel, fray Hernando de Talavera, Pulgar, Córdoba, Tendilla, Aguilar y cien nobles caballeros, rodeados de lanzas y ceñudos los semblantes, miraban al campo donde un moro ante ellos se mostraba acompañado de diez africanos á caballo y un trompeta armados.\"},{\"heading\":false,\"text\":\"Montaba en un poderoso caballo negro encubertado de guerra, y afianzaba una lanza, en cuyo hierro se veia pendiente el cartel de AVE MARIA que Pulgar habia fijado aquella noche en la puerta de la mezquita mayor de Granada.\"},{\"heading\":false,\"text\":\"Era el arrayaz Abd-Allah-ebn-Tarfe.\"},{\"heading\":false,\"text\":\"Llamas arrojaban los ojos del valiente moro.\"},{\"heading\":false,\"text\":\"Su roja sobrevesta parecia pedir sangre.\"},{\"heading\":false,\"text\":\"Sus megillas pálidas eran la clara muestra de la cólera que agitaba su alma.\"},{\"heading\":false,\"text\":\"El ronco son de su trompeta, habia llamado al adarve á los reyes, á los príncipes y á los caudillos cristianos.\"},{\"heading\":false,\"text\":\"Y todos se maravillaron de que aquel infiel se atreviese á presentarse con tamaño atrevimiento ante ellos.\"},{\"heading\":false,\"text\":\"Y Tarfe los miraba como mira el toro á la muchedumbre que le provoca desde la valla, y su cólera era cada vez mas convulsiva y su mano agitaba el cartel del AVE MARIA, blandiendo hasta hacerla crugir en el aire su fuerte lanza de dos hierros.\"},{\"heading\":false,\"text\":\"Mas cuando vió cubiertos de cristianos los adarves paseó la sombría mirada sobre ellos, reconociendo á cada uno de los capitanes á quienes habia visto el semblante entre el polvo de la batalla, y cuando vio competidores dignos hizo una seña al trompetero.\"},{\"heading\":false,\"text\":\"Por tres veces el son de la sonora trompeta rasgó el espacio y retumbando en la cercana Geb-el-Beira, fué repetido á lo lejos y en redondo por los ecos de las montañas.\"},{\"heading\":false,\"text\":\"Aquel sonido de atencion fué repetido de igual modo por las trompetas del Real.\"},{\"heading\":false,\"text\":\"El rey, la reina, el príncipe, los infantes, los caudillos y los soldados de Castilla y Aragon, España, en fin, escuchaban á un solo hombre.\"},{\"heading\":false,\"text\":\"Tarfe se alzó en los estribos, miró al adarve con fiereza y su voz poderosa se estendió en el espacio.\"},{\"heading\":false,\"text\":\"--¡Perros traidores! dijo: ¡vosotros los que entrais como el buho en nuestra ciudad amparados de las tinieblas para dejar en ella el nombre de vuestros ídolos! ¡yo soy Tarfe! ¡yo el que ha arrancado de la mezquita el nombre de MARIA, y le arrastra delante de vosotros, sobre el polvo de vuestros Reales!\"},{\"heading\":false,\"text\":\"¡Salid, canes ladradores!\"},{\"heading\":false,\"text\":\"¡Salid uno a uno, dos á dos, ciento á ciento!\"},{\"heading\":false,\"text\":\"¡Salid! ¡Tarfe os espera!\"},{\"heading\":false,\"text\":\"Mi lanza os conoce, villanos, y mi espada aun tiene en su filo la señal de vuestra sangre.\"},{\"heading\":false,\"text\":\"Calló el moro esperando la respuesta; pero ni una voz, ni un movimiento salieron de entre los cristianos, que parecian estatuas de hierro.\"},{\"heading\":false,\"text\":\"Irritóse Tarfe, hizo botar su corcel, le lanzó hasta salvar la mitad de la distancia que le separaba del muro, y gritó con doble furor:\"},{\"heading\":false,\"text\":\"--Y si no bastan las afrentas que habeis oido para que salgáis al campo, mirad, castellanos, donde pongo el nombre de MARIA; y si algun peon ó caballero, infante ó rey, de ello ha enojo, á esperarle voy en la Vega hasta que el sol trasponga las montañas de Loja.\"},{\"heading\":false,\"text\":\"Y esto diciendo, puso el cartel del AVE MARIA en la cinta que enrollaba la cola de su caballo, revolvió el freno, y seguido de los suyos, se alejó lentamente de los Reales hasta llegar á la espesura donde Zaruhyemal habia dado la carta de la sultana á don Juan Chacon, descendió del caballo, despidió á los esclavos y al trompetero, y se reclinó sobre el césped en la sombra, tendida á mano la pica y ceñido el talabarte de la adarga.\"},{\"heading\":false,\"text\":\"En tanto, en silencio se hundieron como sombras tras las almenas del Real de Santa Fe, reyes é infantes, damas y caballeros.\"},{\"heading\":false,\"text\":\"Ni una sola palabra acerca del suceso se cruzó entre aquel ejército de valientes.\"},{\"heading\":false,\"text\":\"El reto habia sido lanzado con sobrada insolencia para que se departiese sobre él.\"},{\"heading\":false,\"text\":\"Todos los semblantes estaban ceñudos; todos los corazones ardiendo.\"},{\"heading\":false,\"text\":\"Cada una de aquellas espadas estaba mal contenida en su vaina.\"},{\"heading\":false,\"text\":\"Pero lo que faltaba en palabras, sobraba en actividad.\"},{\"heading\":false,\"text\":\"De las almenas se pasó á las tiendas, y de la vestidura de paz al arnés de guerra.\"},{\"heading\":false,\"text\":\"Y entre aquellos viejos soldados endurecidos con la fatiga de los combates, un mancebo imberbe, hermoso como una dama, pero de mirada severa, y centelleante como la de un leon, atravesó en paso apresurado el Real, y al otro estremo entró en una tienda aislada.\"},{\"heading\":false,\"text\":\"--Pronto, Nuño, dijo á un soldado viejo que esperaba impaciente á la puerta; mi arnés, mi lanza y mi caballo: pronto, porque los capitanes del Real se arman á porfía, y no tardarán mucho cien buenas espadas en demandar licencia á sus altezas para rescatar la santa AVE MARIA de las manos de ese perro infiel.\"},{\"heading\":false,\"text\":\"Y así era,\"},{\"heading\":false,\"text\":\"Apenas don Fernando y doña Isabel habian entrado en sus tiendas, visiblemente alterados por el reto de Tarfe, cuando un tropel de capitanes, de caballeros, y aun de simples hidalgos, alféreces y demas cabos de los tercios, entraron armados hasta los dientes, pasando casi por cima de los _continuos_ y demandaron licencia para ir á rescatar con la muerte del moro el nombre de MARIA.\"},{\"heading\":false,\"text\":\"Cada cual alegó su derecho, y con tan buenas razones, y siendo todos pares en valor y merecimientos, don Fernando y doña Isabel reunieron su consejo para elegir el campeon que debia llevar á cabo tan importante empresa.\"},{\"heading\":false,\"text\":\"Mientras esto acaecia, el hermoso mancebo que habia corrido á su tienda en vez de correr como los otros á la de los reyes, se habia cubierto de un arnés de finísimo temple; habia embrazado una adarga de Fez, ganada por sus ascendientes á los moros en aquella misma Vega, y ginete en un fogoso potro cordobés, blandiendo una pesada y larga lanza de fresno, se lanzó á la carrera á través de una puerta cercana, sorprendiendo á la guardia de ella, dió la vuelta al Real y se lanzó en la Vega al escape de su caballo de batalla.\"},{\"heading\":false,\"text\":\"Pronto, muy pronto, desapareció entre una nube de polvo, á pesar de los gritos de la guarda del Real, y llegó á la arboleda donde esperaba Tarfe.\"},{\"heading\":false,\"text\":\"El mancebo caló su visera y llegó á un llano del bosque donde Tarfe con el descuido de los valientes, á los pies de su caballo, dormia sobre el blando césped.\"},{\"heading\":false,\"text\":\"Latió con doble impaciencia el corazon del mozo, y fijó una intensa mirada de cólera en el moro.\"},{\"heading\":false,\"text\":\"--¡Levántate! gritó poniendo los cascos de su caballo junto á Tarfe. ¡Levántate, jactancioso, y ven conmigo á batalla!\"},{\"heading\":false,\"text\":\"Tarfe despertó al sonido de la pujante voz del mancebo castellano.\"},{\"heading\":false,\"text\":\"Levantóse lentamente, púsose de pie y midió con una larga y profunda mirada á su adversario.\"},{\"heading\":false,\"text\":\"--¿Quién eres tú, le dijo con desprecio, caballero sin mote y sin empresa? ¿Acaso no hay en los Reales de Castilla valientes capitanes que vengan á medirse conmigo que soy el caudillo de cien combates?\"},{\"heading\":false,\"text\":\"--Es verdad, contestó el mozo: soy caballero novel, pero vengo por tu cabeza para hacer empresa con ella: y como cristiano, vengo á arrancarte el corazon y el cartel que te has atrevido á poner en la cola de tu caballo, cuando tiene escrito el nombre de la que sobre ángeles se asienta.\"},{\"heading\":false,\"text\":\"--Ea, vete, cristiano, dijo Tarfe con desden, que yo no he de probar mis armas con quien trae las suyas blancas y oculta su semblante.\"},{\"heading\":false,\"text\":\"El mozo se levantó con corage la visera, y mostró su hermosa y juvenil faz al moro.\"},{\"heading\":false,\"text\":\"Tarfe miró con asombro al mancebo.\"},{\"heading\":false,\"text\":\"La espresion de desprecio que antes aparecia en su semblante, se borró.\"},{\"heading\":false,\"text\":\"Solo quedó en ella una sonrisa de afecto.\"},{\"heading\":false,\"text\":\"--Valiente eres, rapaz, dijo: gran fama alcanzarás en el mundo si una lanza traidora no corta en flor tu vida, pero vete: que no soy asesino ni me mido con niños: vete y di á ese terrible Gonzalo Fernandez de Córdoba, que Tarfe le espera durmiendo.\"},{\"heading\":false,\"text\":\"Y fué á reclinarse de nuevo en el césped.\"},{\"heading\":false,\"text\":\"Pero el jóven caló su visera, levantó el cuento de su lanza, y la tendió con ira sobre la espalda del moro.\"},{\"heading\":false,\"text\":\"Al sentir este ultrage, Tarfe saltó como una pantera herida, embrazó su adarga, requirió su espada, cabalgó, tomó campo, y partió con la lanza baja contra el cristiano, gritando ronco de furor:\"},{\"heading\":false,\"text\":\"--Por Satanás, el mentiroso, villano, que has de pagar con tu sangre tan ruin y cobarde ultrage.\"},{\"heading\":false,\"text\":\"Y á este punto embistió contra el mozo que le acortó el trecho saliéndole al encuentro.\"},{\"heading\":false,\"text\":\"El aire gimió con el estruendo del choque.\"},{\"heading\":false,\"text\":\"La lanza de Tarfe, saltó hecha menudas astillas contra la adarga del castellano.\"},{\"heading\":false,\"text\":\"Este no se movió de los arzones.\"},{\"heading\":false,\"text\":\"Su pica falseó la adarga y la jacerina del moro, y le hirió levemente, rompiéndose tambien como hubiera podido romperse una caña.\"},{\"heading\":false,\"text\":\"Tarfe rugió de cólera, y su ancha y larga espada damasquina, lució como un rayo fuera de la vaina.\"},{\"heading\":false,\"text\":\"Desnudó á su vez el cristiano la suya, tornaron á tomar campo y se acometieron de nuevo con doble coraje, é ímpetu furioso.\"},{\"heading\":false,\"text\":\"Martillaban los aceros sobre el duro hierro de los arneses: los airones, los penachos, las sobrevestas y las galas eran despojos del combate: empezaban á desclavarse coseletes y grevas y la sangre corria de mas de una herida.\"},{\"heading\":false,\"text\":\"Rugia Tarfe como un hambriento leon del desierto:\"},{\"heading\":false,\"text\":\"Coloraba su frente la vergüenza de no haber esterminado á la primera embestida á aquel cristiano casi niño, que se habia atrevido á insultarle, y redoblaba sus golpes y sus embestidas, ligero como un halcon, incansable, feroz, irritado.\"},{\"heading\":false,\"text\":\"Y siempre encontraba apercibida la adarga del cristiano.\"},{\"heading\":false,\"text\":\"Siempre su caballo, caracoleando en su lomo, le divertia en una defensa fatigosa.\"},{\"heading\":false,\"text\":\"Y redoblábanse los tajos sobre el templado acero de su jaco.\"},{\"heading\":false,\"text\":\"Jadeaban ya los caballos.\"},{\"heading\":false,\"text\":\"El cristiano, á quien sin duda importaba la brevedad, hacia girar el suyo como un torbellino en derredor del moro.\"},{\"heading\":false,\"text\":\"Al fin, entrambos corceles fatigados, cubiertos de sudor, ensangrentados los ijares, obedecieron mal al freno, y el de Tarfe tropezó en el tronco de un árbol al tomar una vuelta y cayó arrastrando a su ginete.\"},{\"heading\":false,\"text\":\"El castellano contuvo generosamente al suyo para no atropellar al moro, echó pie á tierra, y adelantó cubierto con la adarga y la espada en alto contra su enemigo que se habia levantado cubierto de polvo y trémulo de furor.\"},{\"heading\":false,\"text\":\"Empeñóse de nuevo el combate á pie firme.\"},{\"heading\":false,\"text\":\"Silbaba el acero contra el acero.\"},{\"heading\":false,\"text\":\"El dios de las batallas, posado en una nube roja, miraba con asombro á los caballeros.\"},{\"heading\":false,\"text\":\"Y Tarfe apretó los puños y los dientes.\"},{\"heading\":false,\"text\":\"Describió un ancho círculo al rededor de su cabeza con su espada, y la dejó caer como un rayo sobre el cristiano.\"},{\"heading\":false,\"text\":\"La hoja damasquina saltó en pedazos al chocar la templadísima adarga del mancebo.\"},{\"heading\":false,\"text\":\"Tarfe estaba desarmado: solo le quedaba el puñal, arma débil é inútil.\"},{\"heading\":false,\"text\":\"Arrojó lejos de sí la adarga, y se fué con los brazos abiertos al castellano, que le imitó.\"},{\"heading\":false,\"text\":\"El combate pasaba á ser lucha.\"},{\"heading\":false,\"text\":\"Una sombría y sardónica carcajada salió por entre las barras del yelmo de Tarfe.\"},{\"heading\":false,\"text\":\"Membrudo, ajigantado, gran luchador, pensaba sofocar entre sus robustos brazos al castellano.\"},{\"heading\":false,\"text\":\"Y así hubiera sin duda acontecido.\"},{\"heading\":false,\"text\":\"Pero cuando el moro estrechaba al mancebo, cuando su coselete rechinaba entre aquel brazo de hierro, su mano buscó el falso de la armadura de su enemigo, y su daga buida penetró en su pecho.\"},{\"heading\":false,\"text\":\"Tarfe abrió los brazos, lanzó un grito terrible, y cayó de espaldas.\"},{\"heading\":false,\"text\":\"El AVE MARIA habia sido rescatada.\"},{\"heading\":false,\"text\":\"El mancebo alzó su visera.\"},{\"heading\":false,\"text\":\"Su rostro juvenil y hermoso, cubierto de sangriento sudor, se elevó al cielo, y sus elocuentes ojos negros dejaron brillar una lágrima de gratitud.\"},{\"heading\":false,\"text\":\"Oracion suave, dulce, perdida como un perfume en la inmensidad del abismo, y elevada hasta el trono de Dios: y luego fué al caballo del moro, quitó de su cola el cartel del AVE MARIA, le besó de hinojos y le suspendió de su cuello sobre su pecho, á manera del vasallo que ostenta el blason de su señor.\"},{\"heading\":false,\"text\":\"Y llegó á Tarfe; le desenlazó el yelmo, y al ver su frio semblante, afeado por la lividez de la muerte, esclamó con un orgullo disculpable en sus pocos años:\"},{\"heading\":false,\"text\":\"--Soberbio moro: el novel caballero tiene ya empresa para sus armas, y el AVE MARIA será un cuartel de gloria en el blason de los Garci-Lasos de Castilla.\"},{\"heading\":false,\"text\":\"Y cortó la cabeza á Tarfe, la colgó del arzon de su caballo, cabalgó, salió de la espesura y se encaminó al Real.\"},{\"heading\":false,\"text\":\"Allá á lo lejos se levantaba una nube de polvo bajo los pies de los caballos de un pequeño escuadron, que avanzó hasta dejar conocer á los que cabalgaban.\"},{\"heading\":false,\"text\":\"Era el capitan Gonzalo Fernandez de Córdoba con sus escuderos, que habia sido elegido por el consejo de guerra para responder al reto de Tarfe, y venia armado de todas armas y cubierto de lazos y penachos.\"},{\"heading\":false,\"text\":\"Pronto llegó junto al jóven y pudo ver en su pecho el AVE MARIA y en su arzon la sangrienta cabeza del moro.\"},{\"heading\":false,\"text\":\"Detúvose el capitan y con él sus escuderos.\"},{\"heading\":false,\"text\":\"--¡Pardiez, Garcilaso, dijo Gonzalo Fernandez al jóven, qué temprano empezais á ser hazañoso! vais apurando todas las grandes empresas; Chacon y don Diego de Córdoba, Ponce de Leon y Aguilar, entran en palenque en Bib-Arrambla y vencen delante de la córte de Granada; Pulgar pone el nombre de MARIA en la mezquita mayor en prenda de posesion; y vos, niño aun, rescatais esa sagrada AVE MARIA de un guerrero tan formidable como Abd-Allah-Ebn-Tarfe. ¿Qué dejais, pues, que hacer á Gonzalo Fernandez de Córdoba?\"},{\"heading\":false,\"text\":\"Y esto dijo sonriendo afablemente, como quien tiene harta gloria propia para no envidiar la agena, el hombre que debia ser la primera y mas clara gloria de las glorias guerreras de las Españas.\"},{\"heading\":false,\"text\":\"El que debia ser el último cercador de Granada.\"},{\"heading\":false,\"text\":\"El conquistador de Nápoles.\"},{\"heading\":false,\"text\":\"El terror de los franceses.\"},{\"heading\":false,\"text\":\"¡EL GRAN CAPITAN!\"},{\"heading\":false,\"text\":\"Tendiéronse las manos Gonzalo Fernandez y Garcilaso, y tomaron juntos la vuelta de Santa Fé.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Desde aquel dia, los Lasos son Lasos de la Vega, y en su blason campea el AVE MARIA; desde aquel dia tambien, las armas de la ciudad de Santa Fé son una pica, clavado el cuento en la cabeza de un moro, y pendiente de ella el cartel del AVE MARIA.\"}]},{\"title\":\"El patio de los leones. — capítulo XX: La agonia de granada.\",\"blocks\":[{\"heading\":false,\"text\":\"Gonzalo Fernandez de Córdoba habia sido encargado por los reyes don Fernando y doña Isabel de formalizar el sitio de la ciudad.\"},{\"heading\":false,\"text\":\"Acercábase la hora fatal en que la enseña del Islam debia ser arrebatada por el huracan de la almena que la sustentaba.\"},{\"heading\":false,\"text\":\"Cercada enteramente Granada, empezó á sentir el hambre.\"},{\"heading\":false,\"text\":\"Muy pronto esta se hizo intolerable.\"},{\"heading\":false,\"text\":\"Hablábase ya de rendicion entre los principales caballeros.\"},{\"heading\":false,\"text\":\"Y el rey Chico seguia dormitando en los perfumados departamentos del patio de los Leones.\"},{\"heading\":false,\"text\":\"Siempre delante de aquella sangrienta cámara.\"},{\"heading\":false,\"text\":\"Siempre delante de su remordimiento.\"},{\"heading\":false,\"text\":\"Empezaron á aparecer al descubierto las traiciones.\"},{\"heading\":false,\"text\":\"Súpose que los principales caudillos, temerosos por sus vidas y haciendas, andaban en tratos para la rendicion de la ciudad.\"},{\"heading\":false,\"text\":\"Quedaron patentes las causas de tantos sangrientos motines, de tantas batallas perdidas, de tantas esperanzas malogradas.\"},{\"heading\":false,\"text\":\"Y no fué ya tiempo de retroceder, ni de atender á males incurables arraigados de viejo en el corazon de Granada.\"},{\"heading\":false,\"text\":\"Sostúvose aun, sin embargo, algunos dias, con la esperanza de un socorro de Africa.\"},{\"heading\":false,\"text\":\"Pero los socorros no venian.\"},{\"heading\":false,\"text\":\"Aquejaba el hambre y se temia á cada momento la embestida decisiva del enemigo.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Una noche, Boabdil sintió pasos de algunos hombres en uno de los estremos del patio de los Leones.\"},{\"heading\":false,\"text\":\"Su corazon se estremeció.\"},{\"heading\":false,\"text\":\"Entre las voces de aquellos hombres que hablaban y que al parecer salian de la sala de Justicia, creyó reconocer el acento estranjero de los castellanos.\"},{\"heading\":false,\"text\":\"¿Qué hacian aquellos cristianos en su alcázar?\"},{\"heading\":false,\"text\":\"Trataban, sin duda, en medio del silencio de la noche, de la rendicion de la ciudad: la corona temblaba en su cabeza; el reino de Granada agonizaba.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Boabdil huyó despavorido, y se encontró, sin darse razon de cómo, en la funesta cámara de los Leones.\"},{\"heading\":false,\"text\":\"Sobre las señales rojas de la sangre de los abencerrages, á la luz de una lámpara de alabastro, estaba arrodillada una muger vestida con un blanco trage de luto.\"},{\"heading\":false,\"text\":\"El rey reconoció á la sultana Zoraida.\"},{\"heading\":false,\"text\":\"De la boca del rey salió un grito ahogado.\"},{\"heading\":false,\"text\":\"Zoraida levantó la cabeza y vió al rey.\"},{\"heading\":false,\"text\":\"Se levantó lentamente, y dijo al rey estendiendo su brazo de alabastro hácia la sala de Justicia:\"},{\"heading\":false,\"text\":\"--Allí, tus vasallos cobardes, entregan tu corona á los formidables reyes de Castilla. Aquí, la sangre de caballeros inocentes, se levanta hasta el Altísimo clamando contra tí venganza.\"},{\"heading\":false,\"text\":\"Y la sultana se separó del rey y se perdió como un fantasma entre las columnas del patio de los Leones.\"},{\"heading\":false,\"text\":\"El rey cayó anonadado sobre aquella sangre, y lloró.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"En efecto, el capitan de caballos, Gonzalo Fernandez de Córdoba, y Hernando de Zafra, secretario de los reyes don Fernando y doña Isabel, que habian entrado secretamente en la Alhambra por un postigo, trataban con los wazires Aben-Comixa, y Abul-Cazin-Abd-el-Melik de la rendicion de Granada.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Al dia siguiente el débil Abú-Abdalláh reunió en consejo á sus wazires, á sus faquíes y á sus kadíes, y les consultó sobre la resolucion que debia adoptarse en tan estrema situacion.\"},{\"heading\":false,\"text\":\"El resultado fué fatal.\"},{\"heading\":false,\"text\":\"Los unos, vendidos al enemigo, los otros temerosos de él, resolvieron la entrega de aquella ciudad, engrandecida por el famoso rey Nazar-Al-Hhamar, fuerte y poderosa hasta Abul-Hacen, y vencida, destronada bajo el débil cetro de Abu-Aba-Allah-el-Zogoibi.\"},{\"heading\":false,\"text\":\"Todos los del consejo se inclinaron á tratar de avenencia con los reyes enemigos, y solo el valiente Muza encontrando aun resistencia y brio en su corazon, dijo que _aun era temprano_.\"},{\"heading\":false,\"text\":\"Sin embargo, se determinó que el wazir Abul-Cazin-Abd-el-Melik saliese á proponer capitulacion á los cristianos.\"},{\"heading\":false,\"text\":\"Los reyes de Castilla y de Aragon recibieron bien á este noble caballero, y determinaron que Gonzalo Fernandez de Córdoba, Hernando de Zafra y algunos otros de los principales cristianos concertasen la entrega.\"},{\"heading\":false,\"text\":\"Estos caballeros, precedidos del wazir, entraron otra vez en la Alhambra, por una mina entre la torre del Agua y la puerta de Hierro, y encerrados secretamente en la sala de Justicia del patio de los Leones, hicieron las capitulaciones de la entrega de la ciudad.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Cuando al día siguiente el wazir las presentó en el consejo, la palidez del terror se pintó en todos los semblantes; la sultana madre, Aixa-la-Horra, tembló de cólera, y el rey desfallecido, con los ojos preñados de lágrimas, ocultó su dolor entre los brazos de su madre.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Y en medio de aquel espectáculo de desolacion, intenso en el alma el amor de la patria, sereno, aunque pálido, el intrépido y guerrero infante Muza se levantó, y abarcando en una larga y sombría mirada á los que le rodeaban, dijo con acento de la mas fria reconvencion:\"},{\"heading\":false,\"text\":\"--Dejad, señores, ese inútil llanto á los niños y á las delicadas hembras; seamos hombres y tengamos todavía corazon, no para derramar lágrimas, sino hasta la última gota de nuestra sangre; hagamos un esfuerzo de desesperacion, y peleando contra nuestros enemigos, ofrezcamos nuestros pechos á las contrapuestas lanzas.\"},{\"heading\":false,\"text\":\"Muía era un héroe; su voz vibraba inspirada, pujante, entre aquellos hombres, antes tan valientes, y entonces aterrados por el adverso destino.\"},{\"heading\":false,\"text\":\"--Yo estoy pronto á acaudillaros, continuó el infante con energía; para arrostrar con denuedo y corazon valiente la honrosa muerte en el campo de batalla.\"},{\"heading\":false,\"text\":\"Mas quiero que nos cuente la posteridad en el glorioso número de los que murieron por defender su patria, que no en el de los que presenciaron su entrega.\"},{\"heading\":false,\"text\":\"Y si este valor nos falta, oigamos con paciencia y serenidad estas mezquinas condiciones, y bajemos el cuello al duro y perpetuo yugo de envilecida esclavitud.\"},{\"heading\":false,\"text\":\"Veo tan caidos los ánimos del pueblo, que no es posible evitar la pérdida del reino.\"},{\"heading\":false,\"text\":\"Solo queda un recurso á los nobles pechos, que es la muerte; y yo prefiero morir libre, á los males que nos aguardan.\"},{\"heading\":false,\"text\":\"Si pensais que los cristianos serán fieles á lo que os prometen, y que el rey de la conquista será tan generoso vencedor como venturoso enemigo, os engañais.\"},{\"heading\":false,\"text\":\"Están sedientos de nuestra sangre y se hartarán de ella.\"},{\"heading\":false,\"text\":\"La muerte es lo menos que nos amenaza.\"},{\"heading\":false,\"text\":\"Tormentos y afrentas mas graves nos prepara nuestra enemiga fortuna: el robo y el saqueo de nuestras casas; la profanacion de nuestras mezquitas; los ultrajes y violencias de nuestras mugeres y de nuestras hijas; opresion, mandamientos injustos, intolerancia cruel, y ardientes hogueras, en que abrasarán nuestros míseros cuerpos.\"},{\"heading\":false,\"text\":\"Todo esto lo veremos por nuestros ojos: lo verán por lo menos los mezquinos que ahora temen la honrada muerte; que yo, ¡por Allah! que no lo veré.\"},{\"heading\":false,\"text\":\"La muerte es cierta y en todos muy cercana.\"},{\"heading\":false,\"text\":\"¿Pues por qué no empleamos el breve plazo que nos resta, donde no quedemos sin venganza?\"},{\"heading\":false,\"text\":\"¡Vamos á morir defendiendo nuestra libertad!\"},{\"heading\":false,\"text\":\"La madre tierra recibirá lo que produjo, y _al que faltare sepultura que le esconda, no faltará cielo que le cubra_.\"},{\"heading\":false,\"text\":\"No quiera Dios que se diga que los granadíes nobles no osaron morir por su patria[157].\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Calló Muza, y callaron todos los que allí estaban.\"},{\"heading\":false,\"text\":\"Y calló tambien el rey.\"},{\"heading\":false,\"text\":\"Y entonces Muza, viendo el abatimiento de wazíres, xeques, arrayaces y fakíes, se salió lleno de ira de la sala.\"},{\"heading\":false,\"text\":\"Y dicen los que de aquel tiempo y de aquellas cosas escribieron, que habiendo tomado de su casa armas y caballo, se salió de la ciudad por la puerta de Elvira, y que nunca mas pareció ni se supo qué habia sido de él[158].\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Entretanto el rey, viendo que en la ciudad y en todo el reino, faltaban á un mismo tiempo el ánimo y las fuerzas, resolvió escribir á los reyes sitiadores, que para evitar alborotos y novedades, queria entregarle la ciudad al momento.\"},{\"heading\":false,\"text\":\"El wazir Aben-Comixa, fué á Santa fé con esta carta y con un presente de caballos castizos, con ricos jaeces y alfanges.\"},{\"heading\":false,\"text\":\"Esta fatal determinacion fué el dia cuatro de la luna de rabie primera del año de ochocientos noventa y siete[159].\"}]},{\"title\":\"El patio de los leones. — capítulo XXI: La toma de granada.\",\"blocks\":[{\"heading\":false,\"text\":\"Amaneció el dia cinco de rabie primera.\"},{\"heading\":false,\"text\":\"Todo el ejército cristiano con sus reyes á la cabeza, en alto los estandartes reales de Castilla y Aragon, tendidas las banderas y apercibidas las huestes, marchó sobre Granada.\"},{\"heading\":false,\"text\":\"Iban engalanados ginetes y peones.\"},{\"heading\":false,\"text\":\"Ondeaban al viento penachos, preseas, banderolas y divisas.\"},{\"heading\":false,\"text\":\"El sol arrancaba fúlgidos destellos de las brillantes armas.\"},{\"heading\":false,\"text\":\"Y los timbales y las trompetas y los atambores y los pífanos del ejército cristiano, tañian juntos en alegre alarido, y el viento llevaba á Granada el clamor de triunfo de los vencedores que se acercaban.\"},{\"heading\":false,\"text\":\"A Granada, mustia y silenciosa, cubierta de luto y regada mas con las lágrimas de sus infortunados habitantes que con el agua de sus fuentes.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Entretanto, por la puerta de la torre de los Siete Suelos, acompañado de cincuenta caballeros de los mas nobles de Granada, salió vestido de luto, ya despojado de la corona perdida, el rey á quien los suyos habian llamado con tanta razon el _Desdichadillo_.\"},{\"heading\":false,\"text\":\"El wazir Aben-Comixa, le habia precedido para entregar las llaves de la ciudad á Fernando V de Aragon que esperaba en las márgenes del Genil.\"},{\"heading\":false,\"text\":\"Su familia habia salido antes.\"},{\"heading\":false,\"text\":\"La Alhambra habia quedado huérfana de sus antiguos señores, desamueblada, deshabitada, muda y fria, esperando á un nuevo señor.\"},{\"heading\":false,\"text\":\"El rey Chico descendió por las quebraduras del cerro de Al-Bahul.\"},{\"heading\":false,\"text\":\"De repente su caballo se detuvo como presintiendo al enemigo.\"},{\"heading\":false,\"text\":\"A poco apareció entre las quebraduras el conde de Tendilla don Iñigo Lopez de Mendoza, acompañado de don Pedro Gonzalez de Mendoza su hermano, gran cardenal de España, y de don Gutierre de Cárdenas, comendador mayor de Leon, de la órden de Santiago: llevaba el conde el estandarte real; el cardenal el guion de la cruz; el comendador el pendón de Santiago.\"},{\"heading\":false,\"text\":\"Seguian muchos capitanes á estos tres magnates, y en pos marchaban algunas banderas de infantería española.\"},{\"heading\":false,\"text\":\"Al ver á sus enemigos, el desdichado rey palideció y tembló.\"},{\"heading\":false,\"text\":\"Saludáronle sin embargo los vencedores, con la consideracion y el respeto que merece la desgracia, y mientras seguian adelante para ocupar la Alhambra, el infortunado rey descendió rápidamente por las quebraduras, llegó al sitio donde delante de su ejército esperaba el rey de Aragon, y quiso arrojarse al suelo para arrodillarse ante su vencedor.\"},{\"heading\":false,\"text\":\"Pero el noble Fernando V no se lo permitió, acercando á él su caballo.\"},{\"heading\":false,\"text\":\"Abu-Abd-Allah le besó en el brazo y le dijo:\"},{\"heading\":false,\"text\":\"--Tuyos somos, rey generoso y ensalzado: esta ciudad y reino te entregamos, que así lo quiere Allah, y confiamos que usarás de tu triunfo con clemencia y generosidad[160].\"},{\"heading\":false,\"text\":\"Despues, enmudecido por el dolor, rompiendo el llanto á sus ojos, saliendo la vergüenza á su semblante, rehusando volver á Granada con el conquistador tomó a rienda suelta seguido de sus caballeros el camino de las sierras, por alcanzar á su familia que habia salido algun tiempo antes por otro camino de la ciudad.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"En tanto, en la distante torre del Homenage de la Alhambra, vieron los castellanos tremolar un pendon rojo.\"},{\"heading\":false,\"text\":\"El ejército se prosternó.\"},{\"heading\":false,\"text\":\"La capilla real que acompañaba al ejército, entonó el _Te-Deum laudamus_.\"},{\"heading\":false,\"text\":\"Y allí, en una mezquita cercana, dieron gracias á Dios los conquistadores[161], é hicieron salvas las bombardas y la mosquetería.\"},{\"heading\":false,\"text\":\"El conde de Tendilla habia tremolado sobre la torre mas alta del alcázar de la Alhambra el estandarte de sus señores.\"},{\"heading\":false,\"text\":\"Granada, la perla de Occidente, la sultana de Andalucía, la _cándida y la clara_, era cautiva de los cristianos.\"}]},{\"title\":\"El patio de los leones. — capítulo XXII: El suspiro del moro.\",\"blocks\":[{\"heading\":false,\"text\":\"¡Ah! ¡y cómo corre entretanto el rey Chico!\"},{\"heading\":false,\"text\":\"¡Cómo hiere los ijares de su blanca yegua!\"},{\"heading\":false,\"text\":\"Parece que devora la distancia deseoso de perder en ella el estruendo de la alegria de los vencedores.\"},{\"heading\":false,\"text\":\"¡Ay! ¡y cómo corre tambien la comitiva del cuitado rey!\"},{\"heading\":false,\"text\":\"Huyen de su desventura y de su vergüenza, porque nadie los persigue.\"},{\"heading\":false,\"text\":\"Y los moros que van por el camino con sus mugeres en sus asnos y sus bienes en sus acémilas, maldicen al pasar el rey.\"},{\"heading\":false,\"text\":\"Y le llaman cobarde.\"},{\"heading\":false,\"text\":\"Y el rey aprieta los acicates á la yegua, que gime dolorosamente y apresura su carrera.\"},{\"heading\":false,\"text\":\"Y la comitiva del rey apresura tambien á sus caballos que vuelan.\"},{\"heading\":false,\"text\":\"Falta entre ellos el infante Muza: Muza el valiente.\"},{\"heading\":false,\"text\":\"Muza que no ha tenido bastante valor para presenciar la pérdida de su patria.\"},{\"heading\":false,\"text\":\"¡Corre, miserable rey!\"},{\"heading\":false,\"text\":\"¡Corre, como correrá tu llanto lejos de ese jardin de delicias donde brotan flores de púrpura bajo los rayos de un sol de oro!\"},{\"heading\":false,\"text\":\"¡Corre, miserable, corre, y oculta tu miseria y tu deshonra entre los pelados riscos de las Alpujarras!\"},{\"heading\":false,\"text\":\"Pero detente en esa aldea de Armilla.\"},{\"heading\":false,\"text\":\"Detente de nuevo y rinde un nuevo homenage.\"},{\"heading\":false,\"text\":\"Ahí en esa aldea está la reina Isabel de Castilla.\"},{\"heading\":false,\"text\":\"Arrójate de tu yegua, besa la mano de esa noble señora, torna á cabalgar, y huye de nuevo.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Ya las nieblas de la tarde flotan en el horizonte.\"},{\"heading\":false,\"text\":\"El último rayo del sol poniente refleja á lo lejos sobre las torres de Granada.\"},{\"heading\":false,\"text\":\"En esas torres, que eran antes tu castillo, y que ya no volverás á ver.\"},{\"heading\":false,\"text\":\"Míralas, Boabdil, míralas.\"},{\"heading\":false,\"text\":\"Entre sus almenas, ese último rayo del sol hace brillar limpias armas.\"},{\"heading\":false,\"text\":\"Pero esas armas no son las de tus moros.\"},{\"heading\":false,\"text\":\"Son las de tus conquistadores.\"},{\"heading\":false,\"text\":\"Detente, Boabdil, y mira por última vez á tu perdida Granada, porque cuando hayas bajado la vertiente opuesta de esa colina, ya, aunque vuelvas atrás los tristes ojos, no volverás á ver á tu ciudad.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"¡Oh! ¿por qué asesinaste los bandos?\"},{\"heading\":false,\"text\":\"¿Por qué asesinaste á los treinta y seis caballeros abencerrages?\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"El rey habia llegado á una colina á dos leguas de Granada.\"},{\"heading\":false,\"text\":\"Junto á ella habia encontrado á las dos sultanas, su madre y su esposa.\"},{\"heading\":false,\"text\":\"Aixa-la-Horra le miró con cólera.\"},{\"heading\":false,\"text\":\"Zoraida con desprecio.\"},{\"heading\":false,\"text\":\"En la cima de la colina se veia una estrecha quebradura, desde la cual se divisaba por última vez á Granada.\"},{\"heading\":false,\"text\":\"El rey, al llegar á aquella quebradura, se detuvo, echó pie á tierra, estendió los brazos hácia su querida Granada, y cayó de rodillas.\"},{\"heading\":false,\"text\":\"Luego esclamó exhalando un grito desgarrador:\"},{\"heading\":false,\"text\":\"--¡Alah-ku-Akbar[162]!\"},{\"heading\":false,\"text\":\"Y cayó de rostro contra el suelo, rompiendo en amargo llanto.\"},{\"heading\":false,\"text\":\"Y Aixa-la-Horra, su madre, cuando así le vió, dicen que dijo trémula y demudada señalando á la ciudad:\"},{\"heading\":false,\"text\":\"--Razon es que llores como muger, pues no fuiste para defenderte como hombre[163].\"},{\"heading\":false,\"text\":\"Y su wazir, Aben-Comixa, que le acompañaba, para consolarle dijo:\"},{\"heading\":false,\"text\":\"--Considera, señor, que las grandes y notables desventuras hacen tambien famosos á los hombres como las prosperidades y bienandanzas, procediendo en ellas con valor y fortaleza.\"},{\"heading\":false,\"text\":\"Y el cuitado rey llorando le dijo:\"},{\"heading\":false,\"text\":\"--¿Pues cuáles igualan á las estraordinarias adversidades mias?\"},{\"heading\":false,\"text\":\"Y montó á caballo, se volvió al oriente, y partió.\"},{\"heading\":false,\"text\":\"Al partir la yegua, dicen que dejó señaladas sus herraduras en la roca, y aun se muestran hoy al viajero aquellas señales.\"},{\"heading\":false,\"text\":\"Los moros, en memoria de aquella tristísima despedida, llamaron al alto del Padul, á la quebradura donde se prosternó el rey, _Ojo de lágrimas_, y los castellanos le señalan todavía con el nombre de _Suspiro del Moro_.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Entretanto los cristianos ponian una cruz en la sala de Justicia del patio de los Leones.\"},{\"heading\":false,\"text\":\"EPÍLOGO.\"},{\"heading\":false,\"text\":\"La historia de la Alhambra concluyó par decirlo así, en 1492.\"},{\"heading\":false,\"text\":\"Pero entonces, cuando acabó su historia de grandezas y de poder, comenzó su historia de destrucción.\"},{\"heading\":false,\"text\":\"Los Reyes Católicos destruyeron su magnífica mezquita, y levantaron sobre ella una iglesia.\"},{\"heading\":false,\"text\":\"Mas allá, en la parte alta, echaron por tierra maravillas del arte árabe, y fundaron sobre los escombros un convento de franciscanos.\"},{\"heading\":false,\"text\":\"El emperador don Carlos, su nieto, derribó gran parte del alcázar, y construyó sobre su terreno un palacio que pudo haber construido en otra parte.\"},{\"heading\":false,\"text\":\"Otro sí, para hacer habitaciones á su gusto en el alcázar, hizo puerta uno de los alhamíes de la sala de Embajadores, y puso una galería y un lienzo de habitaciones feas y destartaladas en que solo hay algunos buenos techos de ensambladura, delante del mirador de Lindaraja.\"},{\"heading\":false,\"text\":\"Mas tarde los franceses volaron la torre de los Siete Suelos, la del Agua y algunas otras.\"},{\"heading\":false,\"text\":\"Durante la guerra civil, con el pretesto de fortificar la Alhambra, se hizo saltar con barrenos su parte alta, y se la puso un feston de tapia de tierra con blindajes blanqueada y aspillerada.\"},{\"heading\":false,\"text\":\"Otro ingeniero cegó los baños de mármol del harem, y puso sobre ellos un jardin.\"},{\"heading\":false,\"text\":\"Y el tiempo, que nada respeta, sigue llevándose á fragmentos aquella magnífica joya.\"},{\"heading\":false,\"text\":\"Está escrito que la Alhambra desaparezca á causa de un inconcebible abandono, y lo que está escrito se cumplirá.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Hemos dicho buena y lealmente á nuestros lectores lo que sabiamos acerca de la historia y de la tradicion de ese alcázar.\"},{\"heading\":false,\"text\":\"Si no hemos hecho un libro mejor, no es porque no hayamos querido, sino porque no hemos podido mas.\"},{\"heading\":false,\"text\":\"FIN.\"},{\"heading\":false,\"text\":\"CRONOLOGÍA\"},{\"heading\":false,\"text\":\"DE LOS REYES DE GRANADA.\"},{\"heading\":false,\"text\":\"AÑOS\"},{\"heading\":false,\"text\":\"Mohhammed-Ebn-Al-Hhamar.                                    1238\"},{\"heading\":false,\"text\":\"Mohhammed II.                                               1273\"},{\"heading\":false,\"text\":\"Mohhammed III.                                              1303\"},{\"heading\":false,\"text\":\"Al-Nazar.                                                   1309\"},{\"heading\":false,\"text\":\"Ismail-Abul-Walid.                                          1312\"},{\"heading\":false,\"text\":\"Mohhammed IV.                                               1325\"},{\"heading\":false,\"text\":\"Juzef-Abul-Hhedjadj.                                        1333\"},{\"heading\":false,\"text\":\"Mohhammed V.                                                1354\"},{\"heading\":false,\"text\":\"Ismail II (por usurpacion).                                 1359\"},{\"heading\":false,\"text\":\"Abu-Sayd (idem).                                            1361\"},{\"heading\":false,\"text\":\"Mohhammed V (de nuevo).                                     1362\"},{\"heading\":false,\"text\":\"Juzef II.                                                   1391\"},{\"heading\":false,\"text\":\"Mohhammed VI.                                               1396\"},{\"heading\":false,\"text\":\"Juzef III.                                                  1408\"},{\"heading\":false,\"text\":\"Mohhammed VII, por sobrenombre Al-Hhayzarí.                 1425\"},{\"heading\":false,\"text\":\"Ebn-Ozmin.                                                  1445\"},{\"heading\":false,\"text\":\"Ebn-Ismail.                                                 1454\"},{\"heading\":false,\"text\":\"Abul-Hhasan.                                                1466\"},{\"heading\":false,\"text\":\"Abu-Abd-Allah-Al-Ssaquir-el-Zogoibi (Boabdil).              1482\"},{\"heading\":false,\"text\":\"Abd-Allah-Al-Ssaghar ó el Zagal (en union con Boabdil).                                                   1484\"},{\"heading\":false,\"text\":\"Boabdil (solo).                                             1490\"},{\"heading\":false,\"text\":\"INDICE.\"},{\"heading\":false,\"text\":\"PAGINAS.\"},{\"heading\":false,\"text\":\"LEYENDA I.--_El rey Nazar._                                            3\"},{\"heading\":false,\"text\":\"I      La colina roja.                                     id.\"},{\"heading\":false,\"text\":\"II      La casita del remanso.                               7\"},{\"heading\":false,\"text\":\"III      La dama blanca.                                     10\"},{\"heading\":false,\"text\":\"IV      Bekralbayda.                                        21\"},{\"heading\":false,\"text\":\"V      Una historia muy sencilla.                          26\"},{\"heading\":false,\"text\":\"VI      El rey Nazar visto por el lado histórico.           31\"},{\"heading\":false,\"text\":\"VII      El rey Nazar visto por el lado de adentro.          34\"},{\"heading\":false,\"text\":\"VIII      La venta de una muger.                              37\"},{\"heading\":false,\"text\":\"IX      De cómo el príncipe Mohhammed estuvo á punto de ser ahorcado por ladron.                 39\"},{\"heading\":false,\"text\":\"X      La torre del Gallo de Viento.                       42\"},{\"heading\":false,\"text\":\"XI      De cómo el rey Nazar comprendió que no podia ser feliz.                                 45\"},{\"heading\":false,\"text\":\"XII      El palacio de rubíes.                               48\"},{\"heading\":false,\"text\":\"XIII      La sultana loca.                                    55\"},{\"heading\":false,\"text\":\"XIV      Lo que se veia desde la torre del Gallo de Viento.                                           61\"},{\"heading\":false,\"text\":\"XV      Uno para cada almena.                               63\"},{\"heading\":false,\"text\":\"XVI      Uno para cada cautivo.                              66\"},{\"heading\":false,\"text\":\"XVII      El rey Nazar se ha vuelto loco.                     67\"},{\"heading\":false,\"text\":\"XVIII      ¡El rey Nazar es un sabio!                          69\"},{\"heading\":false,\"text\":\"XIX      El surco del rey Nazar.                              75\"},{\"heading\":false,\"text\":\"LEYENDA II.--_El mirador de la sultana._                              79\"},{\"heading\":false,\"text\":\"I      ¿Sultana ó esclava? ¿amante ó hija?                  id.\"},{\"heading\":false,\"text\":\"II      La mejor noche del rey Nazar.                        87\"},{\"heading\":false,\"text\":\"III      De cómo la sultana Wadah creyó en la resurreccion de los muertos.                         96\"},{\"heading\":false,\"text\":\"IV      En que Iskac-el-Rumí hace pensar al rey Nazar.                                          117\"},{\"heading\":false,\"text\":\"V      Celos y misterio.                                   119\"},{\"heading\":false,\"text\":\"VI      Misterios.                                          122\"},{\"heading\":false,\"text\":\"VII      El pergamino sellado.                               123\"},{\"heading\":false,\"text\":\"LEYENDA III.--_El alma de la Cisterna._                              131\"},{\"heading\":false,\"text\":\"LEYENDA IV.--_La Puerta del Juicio._                                 190\"},{\"heading\":false,\"text\":\"LEYENDA V.--_La torre de la Cautiva_ (continuacion de la anterior).  249\"},{\"heading\":false,\"text\":\"LEYENDA VI.--_La torre de los Siete Suelos_ (cuyo final sirve de epílogo á la anterior).                                           316\"},{\"heading\":false,\"text\":\"APUNTES HISTÓRICOS, en que se dá una breve noticia de los reyes de Granada que existieron despues del rey Abul-Walid y antes del rey Abu-Abd-Allah-al-Zaquír-el-Zogoibi, último señor moro de Granada.                                        427\"},{\"heading\":false,\"text\":\"LEYENDA VII.--_El patio de los Leones._                              461\"},{\"heading\":false,\"text\":\"PAUTA\"},{\"heading\":false,\"text\":\"para la colocacion de las láminas.\"},{\"heading\":false,\"text\":\"PÁGINAS.\"},{\"heading\":false,\"text\":\"La anteportada al cromo, delante de la portada impresa.\"},{\"heading\":false,\"text\":\"Te he llamado para ser tu esclava.                                    25\"},{\"heading\":false,\"text\":\"Y desaparecian y tornaban á desaparecer.                              54\"},{\"heading\":false,\"text\":\"Contemplo profundamente conmovida á Bekralbayda.                      83\"},{\"heading\":false,\"text\":\"¡Mátala si te atreves!                                               114\"},{\"heading\":false,\"text\":\"El rey permaneció inmóvil y fascinado.                               143\"},{\"heading\":false,\"text\":\"Sacudió la bandera y cayó al suelo una cabeza humana.                                                              162\"},{\"heading\":false,\"text\":\"Mira, la dijo, mostrándola la cabeza del rey.                        185\"},{\"heading\":false,\"text\":\"¡Esta es mia!                                                        230\"},{\"heading\":false,\"text\":\"Muerte de Abul-Walid.                                                243\"},{\"heading\":false,\"text\":\"¡He huido! ¡he huido, amado mio!                                     278\"},{\"heading\":false,\"text\":\"Fuga de María.                                                       313\"},{\"heading\":false,\"text\":\"Asieron el cadáver de su padre... y le arrojaron en medio de la sima.                                                 347\"},{\"heading\":false,\"text\":\"Le llevaron á una hermosa cámara.                                    385\"},{\"heading\":false,\"text\":\"El Belludo y el Descabezado.                                         426\"},{\"heading\":false,\"text\":\"La sultana Zoraida.                                                  472\"},{\"heading\":false,\"text\":\"El Suspiro del Moro.                                                 539\"},{\"heading\":false,\"text\":\"NOTAS:\"},{\"heading\":false,\"text\":\"[1] Hegira, huida, la era de los árabes: se cuenta desde el dia en que espulsado Mahoma de la Meca fué á refugiarse a Medinat-Yastreb. Esta huida ó Hegida aconteció el año 622 de J. C.\"},{\"heading\":false,\"text\":\"[2] Del deleite.\"},{\"heading\":false,\"text\":\"[3] Cármenes: jardines, huertos de placer.\"},{\"heading\":false,\"text\":\"[4] Traducido _la Doncella blanca_.\"},{\"heading\":false,\"text\":\"[5] Segun el Koram, el puente Sirat, que deben pasar los creyentes despues de su muerte, es delgado como un cabello, y cortante como una navaja de afeitar: los justos le pasarán salvos, pero se romperá bajo la planta de los réprobos que caerán en el fuego eterno.\"},{\"heading\":false,\"text\":\"[6] Llámanse desde muy antiguo sultanas entre los musulmanes, á las hijas de los reyes reconocidas por ellos.\"},{\"heading\":false,\"text\":\"[7] Noche apacible.\"},{\"heading\":false,\"text\":\"[8] La batalla de las Navas de Tolosa, en que Juzef Amyr-al-Mumenin fué vencido por el rey don Alonso VIII.\"},{\"heading\":false,\"text\":\"[9] Abu-al-abu quiere decir el abuelo.\"},{\"heading\":false,\"text\":\"[10] El espíritu de las tinieblas entre los árabes.\"},{\"heading\":false,\"text\":\"[11] Este largo nombre significa: Mahomet, hijo del servidor de Dios, hijo de Juzef, hijo del Rojo, el defensor: los árabes al nombrarse solian remontarse en su genealogia al cuarto abuelo y aun mas arriba, segun se vé en muchas inscripciones, singularmente en las sepulcrales, y los moros tomaron esta costumbre de los árabes.\"},{\"heading\":false,\"text\":\"[12] Ansari, compañero medinés del profeta.\"},{\"heading\":false,\"text\":\"[13] El defensor.\"},{\"heading\":false,\"text\":\"[14] Al-Morabethin, religiosos ó hermitaños.\"},{\"heading\":false,\"text\":\"[15] Al-Mohahedyn, bi-Ilah los dirigidos por Dios.\"},{\"heading\":false,\"text\":\"[16] Sultan; _scultan tala amir al Mumenyn._\"},{\"heading\":false,\"text\":\"[17] Del oriente.\"},{\"heading\":false,\"text\":\"[18] Se convino entre ambos reyes en que Al-Hhamar conservaría el reino de Granada bajo la soberania y la proteccion del rey de Castilla, á quien pagaria un tributo anual de ciento cincuenta mil doblas, y acudiria con hombres de guerra cuando como vasallo fuese requerido: bajo este concepto ayudó Al-Hhamar á don Fernando en la conquista da Sevilla.\"},{\"heading\":false,\"text\":\"[19] Entre los árabes el órden de los meses que llamaban lunas es el siguiente: Muharram, Safer, Rabié primera, Rabié segunda: Regeb, Jaban, Ramazan, Xawal, Dilcada y Dilhagia: cada mes se cuenta desde la aparicion de una luna nueva hasta la aparicion de otra luna, y este intérvalo nunca pasa de los treinta dias ni baja de los veinte y nueve, y así los computan alternadamente: pero el último mes en el año intercalar siempre tiene treinta dias.\"},{\"heading\":false,\"text\":\"[20] 19 de julio de 1195.\"},{\"heading\":false,\"text\":\"[21] Ermitaño.\"},{\"heading\":false,\"text\":\"[22] Capitan de soldados, ó gobernador de distrito.\"},{\"heading\":false,\"text\":\"[23] Wacir, y sus semejantes _alvazil_, _alvazir_, _alvasir_, _aluazir_, _aluacir_, significaban entre los árabes de España, ministro de estado: esta voz unia en aquellos tiempos á la significacion anterior, la esclarecida de gobernador ó presidente de un pueblo ó territorio, de capitan general, gefe de justicia y magistrado supremo, que en muchos casos tenia una potestad independiente de la del califa.\"},{\"heading\":false,\"text\":\"[24] Moneda árabe de poco valor que no tenia correspondencia con las nuestras.\"},{\"heading\":false,\"text\":\"[25] Arquitecto.\"},{\"heading\":false,\"text\":\"[26] Nombre que daban los árabes al diablo.\"},{\"heading\":false,\"text\":\"[27] Oraciones.\"},{\"heading\":false,\"text\":\"[28] Estos cuatro nombres tienen en árabe las correspondencias siguientes: _Aliento-de-las-flores_: Nafasu-al-Azjari; _Eco-de-las-armonías_: Sadan-al-Angámi; _Suspiro-del-amor_: Jasratu-Jobbati; _Espejo-de-Dios_: Miratu-Allaji. Dejamos en el testo la traduccion española de estos nombres porque son demasiado estraños, es decir: porque no tienen tan buen sonido como otros que hemos consignado en el testo.\"},{\"heading\":false,\"text\":\"[29] Adornos de flores y hojas, especie de filigrana caprichosísima de que están ornamentadas las paredes de la Alhambra.\"},{\"heading\":false,\"text\":\"[30] Mosáicos que sirven unas veces de zócalo á las paredes, otras de pavimento.\"},{\"heading\":false,\"text\":\"[31] La cuesta.\"},{\"heading\":false,\"text\":\"[32] Algarada: correría de pocas horas en tierra enemiga, durante la cual incendiaban aldeas y caseríos, cautivaban hombres y mugeres y se volvian con la presa: en esta ocasion la fé de Al-Hhamar respecto á los tratados con sus aliados, era una especie de fé púnica: segun el derecho internacional de aquellos tiempos, no se entendia rota una tregua ni falseado un tratado de paz, porque los vasallos de una de las dos altas partes contratantes, rompiesen por la frontera en algara, hiciesen presas y se volviesen sin pasar adelante: como en aquellos tiempos era muy dificil sostener á la gente rapaz y aventurera, estas correrías eran mútuas, y para prevenirlas no se tomaba otra precaucion que la de guarnecer fuertemente las fronteras: un rey, sin embargo, podia castigar á muerte sus vasallos que hubiesen entrado á saco y degüello por las tierras de aquel con quien tenian estipuladas paces: pero los corredores tenian muy buen cuidado de enviar parte de la presa al rey, mediante cuyo tributo el rey hacia, como suele decirse, la vista gorda, y aun solia elogiar la hazaña.\"},{\"heading\":false,\"text\":\"[33] _Rumi_, romano; así llamaban los árabes y los moros de España á los solariegos y á sus descendientes; esto es, á los españoles indígenas descendientes de los godos.\"},{\"heading\":false,\"text\":\"[34] No debe estrañarse que los capitanes y hombres de guerra del reino de Granada reuniesen bajo sus banderas particulares, tal número de ginetes: debe tenerse en cuenta que al reino de Granada se habian refugiado los restos dispersos por la conquista de los otros reinos moros, y consta por testimonios auténticos que solo la ciudad de Granada, una de las mayores entonces del mundo, tenia una poblacion de dos millones de almas, y arrojaba por sus puertas un dia de combate, ochenta mil caballos y un número incalculable de infantes: no hay que deducir su poblacion de entonces por la antigua demarcacion de sus muros, porque segun sus costumbres, en una habitacion muy reducida moraban y dormian diez, doce y aun veinte hombres, toda una familia: habia que contar además en la jurisdiccion particular de la ciudad, las aldeas y alquerías de la Vega, que eran entonces innumerables. Mas adelante veremos que por efecto de las guerras civiles y por las emigraciones á Africa, la poblacion de Granada habia decaido ya de una manera considerable en los tiempos de la conquista por los reyes católicos.\"},{\"heading\":false,\"text\":\"[35] Al-Hhamar el vencedor.\"},{\"heading\":false,\"text\":\"[36] ¡Bah! ¡solo Dios es vencedor! este es el mote de las armas de los reyes moros de Granada adoptado por Al-Hhamar. Este mote está escrito en carácter nedji africano, en una banda diagonal de oro saliendo de la boca de dos dragantes, sobre un escudo campo verde.\"},{\"heading\":false,\"text\":\"[37] Llaman xeque, al mas anciano, al mas autorizado de una tribu, que tiene gobierno sobre ella y derecho de vida y muerte.\"},{\"heading\":false,\"text\":\"[38] Casa del rio; hoy casa Gallinas.\"},{\"heading\":false,\"text\":\"[39] No debemos olvidarnos de que Bekralbayda significa la doncella blanca.\"},{\"heading\":false,\"text\":\"[40] _Al-Q\'ars-al-hhamar_ castillo del Rojo, por corrupcion Alhambra.\"},{\"heading\":false,\"text\":\"[41] Generalife.\"},{\"heading\":false,\"text\":\"[42] Península de España.\"},{\"heading\":false,\"text\":\"[43] Sierra de Iliberis.\"},{\"heading\":false,\"text\":\"[44] La torre de la Vela.\"},{\"heading\":false,\"text\":\"[45] Mahoma.\"},{\"heading\":false,\"text\":\"[46] Felicidad.\"},{\"heading\":false,\"text\":\"[47] Anciano, jefe de tribu.\"},{\"heading\":false,\"text\":\"[48] Tribu.\"},{\"heading\":false,\"text\":\"[49] Poniente de Africa.\"},{\"heading\":false,\"text\":\"[50] Estrecho de Gibraltar.\"},{\"heading\":false,\"text\":\"[51] Pelayo.\"},{\"heading\":false,\"text\":\"[52] Madre de Mahoma.\"},{\"heading\":false,\"text\":\"[53] Ave de cetrería.\"},{\"heading\":false,\"text\":\"[54] Teodomiro.\"},{\"heading\":false,\"text\":\"[55] Rio del Olvido, hoy por corrupcion, Guadalete.\"},{\"heading\":false,\"text\":\"[56] La mala muger.\"},{\"heading\":false,\"text\":\"[57] Dios es grande.\"},{\"heading\":false,\"text\":\"[58] La hermosa del poniente.\"},{\"heading\":false,\"text\":\"[59] Sierra Elvira.\"},{\"heading\":false,\"text\":\"[60] Castillo de los romanos.\"},{\"heading\":false,\"text\":\"[61] Esta torre no existe hoy: sobre sus cimientos está levantada la ermita de San Miguel.\"},{\"heading\":false,\"text\":\"[62] Secretario.\"},{\"heading\":false,\"text\":\"[63] La Meca.\"},{\"heading\":false,\"text\":\"[64] Por Dios.\"},{\"heading\":false,\"text\":\"[65] Toledo.\"},{\"heading\":false,\"text\":\"[66] La esposa de don Rodrigo.\"},{\"heading\":false,\"text\":\"[67] La mano es el símbolo del Islam: como la mano consta de cinco dedos y cada dedo de tres articulaciones, escepto el pulgar que solo tiene dos, y todas están sujetas á la unidad de la mano, del mismo modo el Korán contiene cinco principios fundamentales: primero: creer en Dios y que Mahoma es su profeta; segundo: hacer oracion; tercero: dar limosna; cuarto: ayunar en la cuaresma de Rahamadan; quinto: peregrinar á Medina y á la Meca. Cada uno de estos preceptos tiene tres modificaciones, escepto el quinto que puede reducirse á dos: buen corazon y buena obra: estos dogmas provienen de la unidad de Dios, y la mano con sus cinco dedos y sus catorce coyunturas simbolizan fundamentalmente el islamismo.\"},{\"heading\":false,\"text\":\"La llave es un símbolo que se refiere al Paraiso, y que debe abrir su puerta á los escogidos.\"},{\"heading\":false,\"text\":\"Estos dos signos, y no la media luna como creen muchos, eran la empresa religiosa de los moros de Granada.\"},{\"heading\":false,\"text\":\"[68] Conocida hoy vulgarmente con el nombre de torre de los Siete suelos.\"},{\"heading\":false,\"text\":\"[69] Hoy este lugar es una esplanada, al fondo de la que se levanta la parte meridional del palacio del Emperador.\"},{\"heading\":false,\"text\":\"[70] 1345 de Jesucristo.\"},{\"heading\":false,\"text\":\"[71] 1273 de Jesucristo.\"},{\"heading\":false,\"text\":\"[72] Hemos insertado este epitafio é insertaremos otros, porque estas inscripciones sepulcrales pertenecen á la Alhambra, y porque además dan á conocer el estilo apologético de los moros, con toda su exagerada hipérbole y su decidido y característico sabor poético y religioso.\"},{\"heading\":false,\"text\":\"[73] 1302 de Jesucristo.\"},{\"heading\":false,\"text\":\"[74] 1314 de Jesucristo.\"},{\"heading\":false,\"text\":\"[75] 1287 de Jesucristo.\"},{\"heading\":false,\"text\":\"[76] 1309 de Jesucristo.\"},{\"heading\":false,\"text\":\"[77] 1312 de Jesucristo.\"},{\"heading\":false,\"text\":\"[78] El padre Jacob, el sábio por Dios.\"},{\"heading\":false,\"text\":\"[79] En romano: esto es, en latin.\"},{\"heading\":false,\"text\":\"[80] La artillería. Las crónicas árabes dicen, describiendo la entrada en Martos en esta ocasion del rey Abul-Walid, que combatió la ciudad con máquinas é ingenios que lanzaban globos de fuego con grandes truenos, todos semejantes á los rayos de las tempestades y hacian grande estrago en las torres y muros de la ciudad.\"},{\"heading\":false,\"text\":\"[81] Abencerrages.\"},{\"heading\":false,\"text\":\"[82] En aquellos tiempos una mina, revestida de estuco y mármoles, servia de magnífica comunicacion á la Alhambra con Generalife, por la parte de la puerta de Hierro entre las torres de los Picos y de la Cautiva. Aun quedan en la subida de Generalife algunos vestigios de esta mina.\"},{\"heading\":false,\"text\":\"[83] Era costumbre de los moros pobres, vivir en cuevas que habilitaban lo mejor que les era posible: de este género de viviendas miserables, aun hay muchas en Granada habitadas generalmente por gitanos y gente pobre. Estas cuevas habitaciones tenian naturalmente puertas, y por eso hemos usado en el testo la frase: _cerradas_.\"},{\"heading\":false,\"text\":\"[84] 1278 de Jesucristo.\"},{\"heading\":false,\"text\":\"[85] 1313, idem.\"},{\"heading\":false,\"text\":\"[86] 1325, idem.\"},{\"heading\":false,\"text\":\"[87] Por partir el sol se entendia poner á los caballeros de tal modo que el reflejo de los rayos del sol en las armaduras no favoreciese al uno y perjudicase al otro, y ponerlos á cierta distancia con iguales condiciones, para que ninguno tuviese ventaja sobre el otro.\"},{\"heading\":false,\"text\":\"[88] El año de los árabes, es lunar y consta de 354 dias, escepto el año intercalar, que se cuenta de 34 á 34 años y tiene 355.\"},{\"heading\":false,\"text\":\"[89] Contrabandistas de carne.\"},{\"heading\":false,\"text\":\"[90] El autor ha visto dos de estos suelos y la escalera cegada que conduce al tercero.\"},{\"heading\":false,\"text\":\"[91] Ciudad á poca distancia de Túnez. Dicen las crónicas árabes que el walí-Moavia-ebn-Horeig, al llegar al sitio en que se levantó Cairvan, que era un valle cubierto de una espesa y enmarañada selva, poblada únicamente de leones, tigres y serpientes, dijo en altas voces: Salid de este lugar, fieras que morais en este valle; salid, dejad este bosque y espesa selva. Y que habiendo repetido estas voces tres veces, ó en tres dias, no quedó allí fiera, leon, onza ó sierpe que no dejase luego aquel bosque. Que luego mandó á su gente desmontar el terreno y cercarlo de altos muros, y clavando en medio su lanza dijo á los suyos: Este es, este es vuestro Cairvan. Como si hubiese dicho: este es vuestro parador, el descanso de vuestra jornada. Mas adelante el espacio comprendido por los muros se pobló, y la ciudad continuó con el nombre de Cairvan.\"},{\"heading\":false,\"text\":\"[92] Noche hermosa.\"},{\"heading\":false,\"text\":\"[93] Cuadrúpedo maravilloso y alado en que, segun dicen las leyendas musulmanas, hizo Mahoma una escursion al paraiso.\"},{\"heading\":false,\"text\":\"[94] Determinóse en el sesto concilio Toledano, que no pudiese ser rey de los godos el que tuviese tonsurados los cabellos.\"},{\"heading\":false,\"text\":\"[95] El diablo.\"},{\"heading\":false,\"text\":\"[96] Las crónicas árabes reconocen á doña María de Padilla como reina de Castilla.\"},{\"heading\":false,\"text\":\"[97] Mediodia.\"},{\"heading\":false,\"text\":\"[98] 1362 de J. C.\"},{\"heading\":false,\"text\":\"[99] 1375 y 76 de J. C.\"},{\"heading\":false,\"text\":\"[100] Créese con fundamento que este almarestan ú hospital, fuese el edificio que se conoce hoy en Granada con el nombre de Corral del Carbón, y cuya magnífica portada subsiste todavia.\"},{\"heading\":false,\"text\":\"[101] 1391 de J. C.\"},{\"heading\":false,\"text\":\"[102] 1394 de J. C.\"},{\"heading\":false,\"text\":\"[103] Malek significa rey; Muley es la corrupcion de Malek.\"},{\"heading\":false,\"text\":\"[104] De la tribu de los Beni-Zeraghs, ó Abencerrages.\"},{\"heading\":false,\"text\":\"[105] 1436 de J. C.\"},{\"heading\":false,\"text\":\"[106] Fajardo, apellido español: arabizado, Fayard.\"},{\"heading\":false,\"text\":\"[107] Velez Blanco y Velez Rubio.\"},{\"heading\":false,\"text\":\"[108] Moros convertidos al cristianismo.\"},{\"heading\":false,\"text\":\"[109] 1438 de J. C.\"},{\"heading\":false,\"text\":\"[110] 1445 de J. C.\"},{\"heading\":false,\"text\":\"[111] 1454 de J.C.\"},{\"heading\":false,\"text\":\"[112] 1463 de J. C.\"},{\"heading\":false,\"text\":\"[113] 1466 de J. C.\"},{\"heading\":false,\"text\":\"[114] 1469 de J. C.\"},{\"heading\":false,\"text\":\"[115] Esta fuente es un dodecágono de mármol blanco de la sierra, de diez pies y medio de diámetro y dos de fondo, sobre la cual asienta un pedestal que contiene otra pila menor, de cuatro pies de diámetro y uno y medio de fondo. En cada uno de los lados del dodecágono de la gran pila, hay una cenefa de adornos de hojas, lazos y flores, entre las cuales se leen las siguientes inscripciones interpretadas por don Pedro Lozano y el licenciado Castillo.\"},{\"heading\":false,\"text\":\"TRADUCCION DE LOZANO.\"},{\"heading\":false,\"text\":\"Bendito sea el que dió al príncipe Mohamad[*] una habitacion que con su hermosura sirve de adorno á las demás habitaciones.\"},{\"heading\":false,\"text\":\"[*] Mohamad VI.\"},{\"heading\":false,\"text\":\"Y si no, ahí está ese vergél en que hay maravillas que no ha permitido Dios haya otras que las igualen, ni aun en los dos santuarios.\"},{\"heading\":false,\"text\":\"Y un monton de trasparentes perlas, cuyo brillo resplandece con los saltos del aljófar, contínuamente agitada.\"},{\"heading\":false,\"text\":\"Y no sabemos cuál de los dos es el que mengua.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"¿No ves con qué confusion corre el agua, y sin embargo caen sobre ella otras corrientes?\"},{\"heading\":false,\"text\":\"A manera de un amante que se deshace en lágrimas por miedo de que haya quien las haga manifiestas.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Y quizá no es en realidad mas que una blanca nube que se desprende sobre los leones.\"},{\"heading\":false,\"text\":\"De tal modo se estiende la mano liberal del califa, que cuando franquea sus beneficios, alcanzan á los furiosos leones de la milicia.\"},{\"heading\":false,\"text\":\"¡Oh tú, que miras á esos leones, á quienes la falta de vida impide ejercer la furia!\"},{\"heading\":false,\"text\":\"¡Oh heredero de la sangre de los Nazeritas! No hay gloria que se iguale con la de haber heredado el poder y grandeza que te hará despreciar á los mas encumbrados magnates.\"},{\"heading\":false,\"text\":\"La paz de Dios sea contigo perpetuamente, teniendo en sujecion á tus súbditos, y domando á tus enemigos.\"},{\"heading\":false,\"text\":\"TRADUCCION DE CASTILLO.\"},{\"heading\":false,\"text\":\"Bendito sea aquel que dotó al adelantado rey Juçuf, de gracias que adornan su hermosura á las cosas preciadas. E sinó, ved como en este jardin hay riquezas, que Dios no permite que en la hermosura haya otras tales; de las cuales es esta hechura de aljófar de resplandeciente luz, cuyos estremos adornan los bailes del blanco aljófar, que cae sobre ellos en el círculo plateado, que á un mismo tiempo parece que se derrite en las claras é albísimas piezas de mármol, que con su hermosura y lustre parece á la vista que con ella se deshace la piedra dura, é no se entiende cuál es el licor que ansí se deshace. ¿Pues no ves como el agua corre al rededor de ella, é sobre ella hay otros profluvios? En semejanza de un apasionado amante que de sus ojos echa lágrimas, é por temor de su émulo, disimulando su afecto se las vuelve á tragar. E si bien la queremos comparar, no es la pila de esta fuente sino una roca blanquísima, de la cual salen profluvios de mantenimiento á los leones, en semejanza de la liberal mano de Juçuf, que reparte á los leones de la milicia sus tesoros. Pues ¡oh tú que ves los leones que están en guarda, á los cuales el no tener vida les hace no ejecutar su furia! Por tanto, ¡oh heredero de la sangre de los Naçere! Siéndote, como es tan congénito en ella, heredais alteza y poderio, con que á los grandes reyes tendreis en menos. La salud sea con vos perpetuamente, con triunfo é victoria de tus enemigos.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"La diferencia que se nota entre estas dos traducciones consiste: primero, en que la de Lozano es libre, y la de Castillo sujeta servilmente á la letra, y además en la múltiple y maravillosa variedad de la acepcion de las palabras de la lengua árabe, acaso la mas rica de todas. Hay además que tener en cuenta lo caprichoso de los caractéres, que desempeñan el doble objeto de espresar el concepto y de contribuir al adorno. Por tanto, las inscripciones de la Alhambra, especialmente las cúficas son de dificilísima interpretacion.\"},{\"heading\":false,\"text\":\"[116] Lindaraja, fuente de piedra.\"},{\"heading\":false,\"text\":\"[117] Entre los adornos de las fajas y medallones, de los arcos, de las enjutas y en los marcos de los arcos, y en estos arcos, se ven multitud de inscripciones en prosa y en verso.\"},{\"heading\":false,\"text\":\"Las en verso han sido traducidas en metros castellanos, no sabemos por quién, que encontramos en el libro del viajero de Granada del señor la Fuente Alcántara.\"},{\"heading\":false,\"text\":\"Hélas aquí:\"},{\"heading\":false,\"text\":\"Soy de forma muy preciosa; son prodigio mis labores y belleza; Soy creacion maravillosa: ¿de quién no arranca loores mi grandeza?\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Contemplad la piedra dura ya desbastada y bruñida diestramente, Cómo brilla en mi estructura: fuí tiniebla en luz vertida prontamente.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Las mármoles mas preciados en mi alcázar se pusieron con ingenio:\"},{\"heading\":false,\"text\":\"No bien fueron colocados del príncipe relucieron con el génio.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Mis esplendores deslumbran tanto que son envidiados por el cielo:\"},{\"heading\":false,\"text\":\"Luceros que en él alumbran son por mi luz sombreados en el suelo.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Y estas otras, sobre los arcos:\"},{\"heading\":false,\"text\":\"¿Has visto mucha grandeza? pues es mayor mi belleza.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Y dice al verme la gente: ¡qué linda! ¡qué clara fuente!\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Otro me vé, se recrea, y me llama: _Mar que ondea_.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Hé aquí la inscripcion en prosa:\"},{\"heading\":false,\"text\":\"Solo Dios es vencedor: Dése gloria á nuestro señor Abu-Abd-Allah, conceda Dios su perpétuo auxilio á nuestro señor Emir de los fieles.\"},{\"heading\":false,\"text\":\"[118] El Mozo.\"},{\"heading\":false,\"text\":\"[119] El Pequeño y el Desdichadillo.\"},{\"heading\":false,\"text\":\"[120] La Honesta.\"},{\"heading\":false,\"text\":\"[121] Lucero-de-la-mañana.\"},{\"heading\":false,\"text\":\"[122] Esta cristiana, segun la tradicion y las crónicas, era la hija del alcaide de Martos, Sancho Gimenez de Solís; cautivóla en una correria el rey Abul-Hhacem, y enamorado de ella, la hizo su esposa, cambiando su nombre de Isabel de Solís en el de Zoraya.\"},{\"heading\":false,\"text\":\"[123] 1481 de J. C.\"},{\"heading\":false,\"text\":\"[124] Sabios.\"},{\"heading\":false,\"text\":\"[125] Sacerdotes, doctores de la ley.\"},{\"heading\":false,\"text\":\"[126] 1482 de J. C.\"},{\"heading\":false,\"text\":\"[127] Este año árabe coincide con los de 1490 y 1491 de J. C.\"},{\"heading\":false,\"text\":\"[128] Conócese ahora esta habitacion, una de las mas bellas y mejor concluidas de la Alhambra, con el nombre de _cuarto de las camas_, y es un departamento de los baños: es un cuadrado de poca estension, sostenido por cuatro columnas de mármol blanco de Macael, mas allá de los cuales hay una estrecha galería: en sus lados, y abiertos en el hueco interior de la galería, hay dos alhamíes, cuyo techo está sostenido por una columna en el centro y otras dos empotradas á los estremos: la del centro se apoya sobre un plano revestido de alicatado (mosáico), y levantado del pavimento 24 pulgadas, cuyo plano estaba destinado á sostener el diván ó lecho donde los reyes reposaban despues del baño. El pavimento general del retrete es de mosáico, y en el centro tiene una fuente al nivel del pavimento los huecos están adornados con un zócalo de azulejos de dos varas de altura, sobrepuesta al cual, corre una cenefa; sobre esta galería baja, hay otra alta sostenida en cuatro pilastras, entre las cuales corre una barandilla de madera; galería donde, segun algunos autores afirman, se colocaban los músicos que tañian para hacer agradable á los reyes el reposo del baño. Encima de esta segunda galería, hay diez y seis ajimeces ó trasparentes pequeños, cuatro en cada lado, sobre los cuales asienta una cornisa de madera de bovedillas, de la que arranca la magnífica ensambladura cónica hasta terminar en un pequeño techo plano, en cuyo centro hay un precioso cupulino.\"},{\"heading\":false,\"text\":\"[129] Og-Allah: quiéralo Dios: hoy decimos ojalá.\"},{\"heading\":false,\"text\":\"[130] El terreno del campo para justas y torneos ó para duelos.\"},{\"heading\":false,\"text\":\"[131] ¡Dios es grande! ¡Dios es misericordioso! ¡Solo Dios es vencedor!\"},{\"heading\":false,\"text\":\"[132] Puerta del Arenal.\"},{\"heading\":false,\"text\":\"[133] Todas las princesas de sangre se llaman sultanas entre los musulmanes, aunque sean doncellas.\"},{\"heading\":false,\"text\":\"[134] De los Estandartes.\"},{\"heading\":false,\"text\":\"[135] Corazas pequeñas.\"},{\"heading\":false,\"text\":\"[136] De la puerta de los convertidos.\"},{\"heading\":false,\"text\":\"[137] Flor de hermosura.\"},{\"heading\":false,\"text\":\"[138] El arcángel de la muerte.\"},{\"heading\":false,\"text\":\"[139] Boabdil tenia el sobrenombre árabe de _Zogoibí_, que significa _Desventuradillo_.\"},{\"heading\":false,\"text\":\"[140] Hoy de los Picos.\"},{\"heading\":false,\"text\":\"[141] Corrupcion del árabe, usada para entenderse respectivamente moros y cristianos.\"},{\"heading\":false,\"text\":\"[142] Medio dia.\"},{\"heading\":false,\"text\":\"[143] Al-Mueden, especie de sacristan de mezquita, que llamaba á voces desde el almirar ó torre á la oracion. Los árabes no tenian campanas.\"},{\"heading\":false,\"text\":\"[144] Puestas del sol: oracion de la tarde.\"},{\"heading\":false,\"text\":\"[145] Aldeano, de alqueria ó alkaria, aldea.\"},{\"heading\":false,\"text\":\"[146] Esto es: el terreno por partes iguales.\"},{\"heading\":false,\"text\":\"[147] Daga larga y unida con que los antiguos caballeros remataban á sus enemigos vencidos.\"},{\"heading\":false,\"text\":\"[148] Histórico á la letra: crónica de Hernan Perez del Pulgar.\"},{\"heading\":false,\"text\":\"[149] Histórico á la letra: crónica de Hernan Perez del Pulgar.\"},{\"heading\":false,\"text\":\"[150] Llámase el edificio que citamos _Casa del Carbón_, porque hace años se depositaba en él este combustible por sus dueños hasta que obtenian licencia para venderle. A juzgar por sus restos, este edificio debió ser, en los dias de su esplendor, suntuosísimo: el arco de su fachada, guarnecido de greca con enjutas de labor persa es de herradura y de una riqueza admirable; corre sobre él una inscripcion casi borrada por el tiempo, y sobre ella se ven tres agimeces, tapiado el del centro y los laterales con restos de trasparentes, formados de ramage y hojas á semejanza de los del patio de los Leones. Tras este arco hay un pequeño vestíbulo, cubierto por una bóveda de estalacticas, y en los lados hay dos puertas labradas y tapiadas, levantándose delante de ellas y hasta el arranque del gran arco esterior, dos especies de cajones de tablas blanqueadas, que sirven de tienda á dos adobadores de pieles de gato, y que dan al viejo edificio todo el romántico colorido de un monumento profanado.\"},{\"heading\":false,\"text\":\"[151] Segun todas las probabilidades, Pulgar y los cinco escuderos entraron por la calle de la Gallinería, que corre paralela al rio hasta el puente del Carbon, y por el Zacatin y calleja del Tinte, al lugar donde ahora está la iglesia del Sagrario y donde antes estaba la mezquita mayor.\"},{\"heading\":false,\"text\":\"[152] Hoy casas capitulares.\"},{\"heading\":false,\"text\":\"[153] Hoy templo del Sagrario.\"},{\"heading\":false,\"text\":\"[154] Este era un moro cautivado por Pulgar, que al bautizarse tomó el nombre de Pedro del Pulgar.\"},{\"heading\":false,\"text\":\"[155] Crónica de Hernan Perez del Pulgar.\"},{\"heading\":false,\"text\":\"[156] Si no existiese un indudable documento histórico que testimonia esta gran hazaña de Hernan Perez del Pulgar, se creería arrancada de una novela caballeresca.\"},{\"heading\":false,\"text\":\"En el archivo del marquesado del Salar, libro I, leg 2.ª, tomo VIII, se encuentra una real cédula, original de los Reyes Católicos, á favor de los quince escuderos que entraron en Granada con Hernando Perez del Pulgar, y que copiada á la letra es como sigue:\"},{\"heading\":false,\"text\":\"«El rey é la reina:--Por la presente damos nuestra palabra real de facer merced á vos Gerónimo de Aguilera, é Francisco Bedmar, é Diego de Jaen, é Alvaro de Peñalver, é Diego Ximenez, é Pedro de Pulgar, Adalides, e Montesino de Avila, é Ramiro de Guzman, é Cristobal de Castro, é Tristan de Montemayor, é Diego de Baena é Torre, é Alfon de Almería, é Luis de Quero, é Rodrigo Velazquez, que todos sois _quince escuderos_, é á cada uno, de tierras é facienda en la ciudad de Granada, de que pluga á nuestro Señor, que esté rendida á nuestro dominio; la cual dicha merced os facemos porque entrasteis con Fernando del Pulgar, nuestro alcaide del Salar, á pegar fuego en la ciudad de Granada en la mezquita mayor, por el peligro á que os pusisteis.--Fecho en 30 de diciembre de 1491 años.--Yo el Rey.--Yo la Reina.--Por mandato del Rey é la Reina, Fernan Dálvarez.»\"},{\"heading\":false,\"text\":\"Además los Reyes Católicos hicieron merced á Hernan Perez del Pulgar de añadir á los cuarteles de su escudo el _Ave María_ y el privilegio para sí de ser enterrado en el mismo sitio donde llevó á cabo aquella grande empresa.\"},{\"heading\":false,\"text\":\"Archivo del Salar.\"},{\"heading\":false,\"text\":\"[157] Todo el discurso de Muza, es histórico á la letra.\"},{\"heading\":false,\"text\":\"[158] Histórico.\"},{\"heading\":false,\"text\":\"[159] 1492 de J. C.\"},{\"heading\":false,\"text\":\"[160] Histórico á la letra.\"},{\"heading\":false,\"text\":\"[161] Esta mezquita, poco distante de la confluencia del Darro y del Genil, consagrada despues en capilla con la advocacion de San Sebastian, profanada un dia y convertida en taberna con ofensa de sus recuerdos históricos y religiosos, conserva en su pared esterior que mira al oriente, una lápida de mármol blanco con la siguiente inscripcion en caracteres góticos:\"},{\"heading\":false,\"text\":\"«Habiendo Muley-Abdeli, último rey moro de Granada, entregado las llaves de dicha ciudad, el viernes 2 de enero en 1492, á las tres de la tarde en las puertas de la Alhambra, á nuestros católicos monarcas don Fernando V de Aragon y doña Isabel de Castilla, despues de 777 que esta ciudad sufria el yugo mahometano, desde la pérdida de España acaecida domingo dos de noviembre de setecientos catorce, salió dicho católico rey á despedir al espresado Boabdil hasta este sitio, _antes mezquita de moros, y ahora erigida en capilla de San Sebastian_, donde dieron las primeras gracias á Dios, el glorioso conquistador y su ejército, entonando la real capilla el _Te-Deum_, y tremolando en la _Torre de la Vela_ el pendon de la fé; en cuya memoria se toca á dicha hora la plegaria en la catedral, y se gana indulgencia plenaria rezando tres Padres nuestros y tres Ave-Marías.»\"},{\"heading\":false,\"text\":\"[162] ¡Dios es grande!\"},{\"heading\":false,\"text\":\"[163] Histórico.\"}]}]', 'es', 'https://www.gutenberg.org/ebooks/49660', '{}');
INSERT INTO libros (id, titulo, autor, genero, cover, secciones, idioma, fuente, introducciones) VALUES (49836, 'Niebla', 'Miguel de Unamuno', 'novela', 'https://www.gutenberg.org/cache/epub/49836/pg49836.cover.medium.jpg', '[{\"title\":\"Prólogo\",\"blocks\":[{\"heading\":false,\"text\":\"Se empeña don Miguel de Unamuno en que ponga yo un prólogo a este su libro en que se relata la tan lamentable historia de mi buen amigo Augusto Pérez y su misteriosa muerte, y yo no puedo menos sino escribirlo, porque los deseos del señor Unamuno son para mí mandatos, en la más genuina acepción de este vocablo. Sin haber yo llegado al extremo de escepticismo hamletiano de mi pobre amigo Pérez, que llegó hasta a dudar de su propia existencia, estoy por lo menos firmemente persuadido de que carezco de eso que los psicólogos llaman libre albedrío, aunque para mi consuelo creo también que tampoco goza don Miguel de él.\"},{\"heading\":false,\"text\":\"Parecerá acaso extraño a alguno de nuestros lectores que sea yo, un perfecto desconocido en la república de las letras españolas, quien prologue un libro de don Miguel que es ya ventajosamente conocido en ella, cuando la costumbre es que sean los escritores más conocidos los que hagan en los prólogos la presentación de aquellos otros que lo sean menos. Pero es que nos hemos puesto de acuerdo don Miguel y yo para alterar esta perniciosa costumbre, invirtiendo los términos, y que sea el desconocido el que al conocido presente. Porque en rigor los libros más se compran por el cuerpo del texto que no por el prólogo, y es natural por lo tanto que cuando un joven principiante como yo, desee darse a conocer, en vez de pedir a un veterano de las letras que le escriba un prólogo de presentación, debe rogarle que le permita ponérselo a una de sus obras. Y esto es a la vez resolver uno de los problemas de ese eterno pleito de los jóvenes y los viejos.\"},{\"heading\":false,\"text\":\"Únenme, además, no pocos lazos con don Miguel de Unamuno. Aparte de que este señor saca a relucir en este libro, sea novela o _nivola_ (véase pág. 158)—y conste que esto de la _nivola_ es invención mía—, no pocos dichos y conversaciones que con el malogrado Augusto Pérez tuve, y que narra también en ella la historia del nacimiento de mi tardío hijo Victorcito, parece que tengo algún lejano parentesco con don Miguel, ya que mi apellido es el de uno de sus antepasados, según doctísimas investigaciones genealógicas de mi amigo Antolín S. Paparrigópulos, tan conocido en el mundo de la erudición.\"},{\"heading\":false,\"text\":\"Yo no puedo prever ni la acojida que esta _nivola_ obtendrá de parte del público que lee a don Miguel, ni cómo se la tomarán a éste. Hace algún tiempo que vengo siguiendo con alguna atención la lucha que don Miguel ha entablado con la ingenuidad pública y estoy verdaderamente asombrado de lo profunda y cándida que es ésta. Con ocasión de sus artículos en el _Mundo Gráfico_ y en alguna otra publicación análoga, ha recibido don Miguel algunas cartas y recortes de periódicos de provincias que ponen de manifiesto los tesoros de candidez ingenua y de simplicidad palomina que todavía se conservan en nuestro pueblo. Una vez comentan aquella su frase de que el Sr. Cervantes (don Miguel) no carecía de algún ingenio y parece se escandalizan de la irreverencia; otra se enternecen por esas sus melancólicas reflexiones sobre la caída de las hojas; ya se entusiasman por su grito ¡guerra a la guerra! que le arrancó el dolor de ver que los hombres se mueren aunque no los maten; ya reproducen aquel puñado de verdades no paradójicas que publicó después de haberlas recojido por todos los cafés, círculos y cotarrillos, donde andaban podridas de puro manoseadas y hediendo a ramplonería ambiente, por lo que las reconocieron como suyas los que las reprodujeron, y hasta ha habido palomilla sin hiel que se ha indignado de que este logómaco de don Miguel escriba algunas veces Kultura con K mayúscula y después de atribuirse habilidad para inventar amenidades reconozca ser incapaz de producir colmos y juegos de palabras, pues sabido es que para este público ingenuo el ingenio y la amenidad se reducen a eso: a los colmos y los juegos de palabras.\"},{\"heading\":false,\"text\":\"Y menos mal que ese ingenuo público no parece haberse dado cuenta de alguna otra de las diabluras de don Miguel, a quien a menudo le pasa lo de pasarse de listo, como es aquello de escribir un artículo y luego subrayar al azar unas palabras cualesquiera de él, invirtiendo las cuartillas para no poder fijarse en cuáles lo hacía. Cuando me lo contó le pregunté por qué había hecho eso y me dijo: «¡Qué sé yo... por buen humor! ¡Por hacer una pirueta! Y además porque me encocoran y ponen de mal humor los subrayados y las palabras en bastardilla. Eso es insultar al lector, es llamarle torpe, es decirle: ¡fíjate, hombre, fíjate, que aquí hay intención! Y por eso le recomendaba yo a un señor que escribiese sus artículos todo en bastardilla para que el público se diese cuenta de que eran intencionadísimos desde la primera palabra a la última. Eso no es más que la pantomima de los escritos; querer sustituir en ellos con el gesto lo que no se expresa con el acento y entonación. Y fíjate, amigo Víctor, en los periódicos de la extrema derecha, de eso que llamamos integrismo, y verás cómo abusan de la bastardilla, de la versalita, de las mayúsculas, de las admiraciones y de todos los recursos tipográficos. ¡Pantomima, pantomima, pantomima! Tal es la simplicidad de sus medios de expresión, o más bien tal es la conciencia que tienen de la ingenua simplicidad de sus lectores. Y hay que acabar con esta ingenuidad.»\"},{\"heading\":false,\"text\":\"Otras veces le he oído sostener a don Miguel que eso que se llama por ahí humorismo, el legítimo, ni ha prendido en España apenas, ni es fácil que en ella prenda en mucho tiempo. Los que aquí se llaman humoristas, dice, son satíricos unas veces y otras irónicos, cuando no puramente festivos. Llamar humorista a Taboada, verbigracia, es abusar del término. Y no hay nada menos humorístico que la sátira áspera, pero clara y transparente de Quevedo, en la que se ve el sermón enseguida. Como humorista no hemos tenido más que Cervantes, y si éste levantara cabeza, ¡cómo había de reírse—me decía don Miguel—de los que se indignaron de que yo le reconociese algún ingenio, y, sobre todo, cómo se reiría de los ingenuos que han tomado en serio alguna de sus más sutiles tomaduras de pelo! Porque es indudable que entraba en la burla—burla muy en serio—que de los libros de caballerías hacía el remedar el estilo de éstos, y aquello de «no bien el rubicundo Febo, etc.» que como modelo de estilo presentan algunos ingenuos cervantistas no pasa de ser una graciosa caricatura del barroquismo literario. Y no digamos nada de aquello de tomar por un modismo lo de «la del alba sería» con que empieza un capítulo cuando el anterior acaba con la palabra _hora_.\"},{\"heading\":false,\"text\":\"Nuestro público, como todo público poco culto, es naturalmente receloso, lo mismo que lo es nuestro pueblo. Aquí nadie quiere que le tomen el pelo, ni hacer el primo, ni que se queden con él, y así en cuanto alguien le habla quiere saber desde luego a qué atenerse y si lo hace en broma o en serio. Dudo que en otro pueblo alguno moleste tanto el que se mezclen las burlas con las veras, y en cuanto a eso de que no se sepa bien si una cosa va o no en serio, ¿quién de nosotros lo soporta? Y es mucho más difícil que un receloso español de término medio se dé cuenta de que una cosa está dicha en serio y en broma a la vez, de veras y de burlas, y bajo el mismo respecto.\"},{\"heading\":false,\"text\":\"Don Miguel tiene la preocupación del bufo trágico y me ha dicho más de una vez que no quisiera morirse sin haber escrito una bufonada trágica o una tragedia bufa, pero no en que lo bufo o grotesco y lo trágico estén mezclados o yuxtapuestos, sino fundidos y confundidos en uno. Y como yo le hiciese observar que eso no es sino el más desenfrenado romanticismo, me contestó: «no lo niego, pero con poner motes a las cosas no se resuelve nada. A pesar de mis más de veinte años de profesar la enseñanza de los clásicos, el clasicismo que se opone al romanticismo no me ha entrado. Dicen que lo helénico es distinguir, definir, separar; pues lo mío es indefinir, confundir».\"},{\"heading\":false,\"text\":\"Y el fondo de esto no es más que una concepción, o mejor aún que concepción un sentimiento de la vida que no me atrevo a llamar pesimista porque sé que esta palabra no le gusta a don Miguel. Es su idea fija, monomaníaca, de que si su alma no es inmortal y no lo son las almas de los demás hombres y aun de todas las cosas, e inmortales en el sentido mismo en que las creían ser los ingenuos católicos de la Edad Media, entonces, si no es así, nada vale nada ni hay esfuerzo que merezca la pena. Y de aquí la doctrina del tedio de Leopardi después que pereció su engaño extremo,\"},{\"heading\":false,\"text\":\"ch’io eterno mi credea\"},{\"heading\":false,\"text\":\"de creerse eterno. Y esto explica que tres de los autores más favoritos de don Miguel sean Sénancour, Quental y Leopardi.\"},{\"heading\":false,\"text\":\"Pero este adusto y áspero humorismo confusionista, además de herir la recelosidad de nuestras gentes, que quieren saber desde que uno se dirige a ellas a qué atenerse, molesta a no pocos. Quieren reírse, pero es para hacer mejor la digestión y para distraer las penas, no para devolver lo que indebidamente se hubiesen tragado y que puede indigestárseles, ni mucho menos para digerir las penas. Y don Miguel se empeña en que si se ha de hacer reír a las gentes debe ser no para que con las contracciones del diafragma ayuden a la digestión, sino para que vomiten lo que hubieren engullido, pues se ve más claro el sentido de la vida y del universo con el estómago vacío de golosinas y excesivos manjares. Y no admite eso de la ironía sin hiel ni del humorismo discreto, pues dice que donde no hay alguna hiel no hay ironía y que la discreción está reñida con el humorismo, o como él se complace en llamarle: malhumorismo.\"},{\"heading\":false,\"text\":\"Todo lo cual le lleva a una tarea muy desagradable y poco agradecida, de la que dice que no es sino un masaje de la ingenuidad pública, a ver si el ingenio colectivo de nuestro pueblo se va agilizando y sutilizando poco a poco. Porque le saca de sus casillas el que digan que nuestro pueblo, sobre todo el meridional, es ingenioso. «Pueblo que se recrea en las corridas de toros y halla variedad y amenidad en ese espectáculo sencillísimo, está juzgado en cuanto a mentalidad», dice. Y agrega que no puede haber mentalidad más simple y más córnea que la de un aficionado. ¡Vaya usted con paradojas más o menos humorísticas al que acaba de entusiasmarse con una estocada de Vicente Pastor! Y abomina del género festivo de los revisteros de toros, sacerdotes del juego de vocablos y de toda la bazofia del ingenio de puchero.\"},{\"heading\":false,\"text\":\"Si a esto se añade los juegos de conceptos metafísicos en que se complace, se comprenderá que haya muchas gentes que se aparten con disgusto de su lectura, los unos porque tales cosas les levantan dolor de cabeza, y los otros porque, atentos a lo de que _sancta sancte tractanda sunt_, lo santo ha de tratarse santamente, estiman que esos conceptos no deben dar materia para burlas y jugueteos. Mas él dice a esto que no sabe por qué han de pretender que se trate en serio ciertas cosas los hijos espirituales de quienes se burlaron de las más santas, es decir, de las más consoladoras creencias y esperanzas de sus hermanos. Si ha habido quien se ha burlado de Dios, ¿por qué no hemos de burlarnos de la Razón, de la Ciencia y hasta de la Verdad? Y si nos han arrebatado nuestra más cara y más íntima esperanza vital, ¿por qué no hemos de confundirlo todo para matar el tiempo y la eternidad y para vengarnos?\"},{\"heading\":false,\"text\":\"Fácil es también que salga diciendo alguno que hay en este libro pasajes escabrosos, o si se quiere, pornográficos; pero ya don Miguel ha tenido buen cuidado de hacerme decir a mí algo al respecto en el curso de esta _nivola_. Y está dispuesto a protestar de esa imputación y a sostener que las crudezas que aquí puedan hallarse ni llevan intención de halagar apetitos de la carne pecadora, ni tienen otro objeto que ser punto de arranque imaginativo para otras consideraciones.\"},{\"heading\":false,\"text\":\"Su repulsión a toda forma de pornografía es bien conocida de cuantos le conocen. Y no sólo por las corrientes razones morales, sino porque estima que la preocupación libidinosa es lo que más estraga la inteligencia. Los escritores pornográficos, o simplemente eróticos, le parecen los menos inteligentes, los más pobres de ingenio, los más tontos, en fin. Le he oído decir que de los tres vicios de la clásica terna de ellos: las mujeres, el juego y el vino, los dos primeros estropean más la mente que el tercero. Y conste que don Miguel no bebe más que agua. «A un borracho se le puede hablar—me decía una vez—y hasta dice cosas, pero ¿quién resiste la conversación de un jugador o un mujeriego? No hay por debajo de ella sino la de un aficionado a toros, colmo y copete de la estupidez.»\"},{\"heading\":false,\"text\":\"No me extraña a mí, por otra parte, este consorcio de lo erótico con lo metafísico, pues creo saber que nuestros pueblos empezaron siendo, como sus literaturas nos lo muestran, guerreros y religiosos para pasar más tarde a eróticos y metafísicos. El culto a la mujer coincidió con el culto a las sutilezas conceptistas. En el albor espiritual de nuestros pueblos, en efecto, en la Edad Media, la sociedad bárbara sentía la exaltación religiosa y aun mística y la guerrera—la espada lleva cruz en el puño—; pero la mujer ocupaba muy poco y muy secundario lugar en su imaginación y las ideas estrictamente filosóficas dormitaban, envueltas en teología, en los claustros conventuales. Lo erótico y lo metafísico se desarrollan a la par. La religión es guerrera; la metafísica es erótica o voluptuosa.\"},{\"heading\":false,\"text\":\"Es la religiosidad lo que le hace al hombre ser belicoso o combativo, o bien es la combatividad la que le hace religioso, y por otro lado es el instinto metafísico, la curiosidad de saber lo que no nos importa, el pecado original, en fin, lo que le hace sensual al hombre, o bien es la sensualidad la que, como a Eva, le despierta el instinto metafísico, el ansia de conocer la ciencia del bien y del mal. Y luego hay la mística, una metafísica de la religión que nace de la sensualidad de la combatividad.\"},{\"heading\":false,\"text\":\"Bien sabía esto aquella cortesana ateniense Teodota, de que Jenofonte nos cuenta en sus _Recuerdos_ la conversación que con Sócrates tuvo, y que proponía al filósofo, encantada de su modo de investigar, o más de partear la verdad, que se convirtiera en celestino de ella y le ayudase a cazar amigos. (_Synthérates_, con-cazador, dice el texto, según don Miguel, profesor de griego, que es a quien debo esta interesantísima y tan reveladora noticia.) Y en toda aquella interesantísima conversación entre Teodota, la cortesana, y Sócrates, el filósofo partero, se ve bien claro el íntimo parentesco que hay entre ambos oficios, y cómo la filosofía es en grande y buena parte lenocinio y el lenocinio es también filosofía.\"},{\"heading\":false,\"text\":\"Y si todo esto no es así como digo, no se me negará al menos que es ingenioso, y basta.\"},{\"heading\":false,\"text\":\"No se me oculta, por otra parte, que no estará conforme con esa mi distinción entre religión y belicosidad de un lado y filosofía y erótica de otro mi querido maestro don Fulgencio Entrambosmares del Aquilón, de quien don Miguel ha dado tan circunstanciada noticia en su novela o _nivola Amor y Pedagogía_. Presumo que el ilustre autor del _Ars magna combinatoria_ establecerá: una religión guerrera y una religión erótica, una metafísica guerrera y otra erótica, un erotismo religioso y un erotismo metafísico, un belicosismo metafísico y otro religioso, y, por otra parte, una religión metafísica y una metafísica religiosa, un erotismo guerrero y un belicosismo erótico; todo esto aparte de la religión religiosa, la metafísica metafísica, el erotismo erótico y el belicosismo belicoso. Lo que hace diez y seis combinaciones binarias. ¡Y no digo nada las ternarias del género, verbigracia, de una religión metafísico-erótica o de una metafísica guerrero-religiosa! Pero yo no tengo ni el inagotable ingenio combinatorio de don Fulgencio, ni menos el ímpetu confusionista e indefinicionista de don Miguel.\"},{\"heading\":false,\"text\":\"Mucho se me ocurre atañedero al inesperado final de este relato y a la versión que en él da don Miguel de la muerte de mi desgraciado amigo Augusto, versión que estimo errónea, pero no es cosa de que me ponga yo ahora aquí a discutir en este prólogo con mi prologado. Pero debo hacer constar en descargo de mi conciencia que estoy profundamente convencido de que Augusto Pérez, cumpliendo el propósito de suicidarse que me comunicó en la última entrevista que con él tuve, se suicidó realmente y de hecho, y no sólo idealmente y de deseo. Creo tener pruebas fehacientes en apoyo de mi opinión; tantas y tales pruebas, que deja de ser opinión para llegar a conocimiento.\"},{\"heading\":false,\"text\":\"Y con esto acabo.\"},{\"heading\":false,\"text\":\"VÍCTOR GOTI.\"}]},{\"title\":\"Post-prólogo\",\"blocks\":[{\"heading\":false,\"text\":\"De buena gana discutiría aquí alguna de las afirmaciones de mi prologuista, Víctor Goti, pero como estoy en el secreto de su existencia—la de Goti—, prefiero dejarle la entera responsabilidad de lo que en ese su prólogo dice. Además, como fuí yo quien le rogué que me lo escribiese, comprometiéndome de antemano—o sea _a priori_—a aceptarlo tal y como me lo diera, no es cosa ni de que lo rechace, ni siquiera de que me ponga a corregirlo y rectificarlo ahora a posmano—o sea _a posteriori_. Pero otra cosa es que deje pasar ciertas apreciaciones suyas sin alguna mía.\"},{\"heading\":false,\"text\":\"No sé hasta qué punto sea lícito hacer uso de confidencias vertidas en el seno de la más íntima amistad y llevar al público opiniones o apreciaciones que no las destinaba a él quien las profiriera. Y Goti ha cometido en su prólogo la indiscreción de publicar juicios míos que nunca tuve intención de que se hiciesen públicos. O por lo menos nunca quise que se publicaran con la crudeza con que en privado los exponía.\"},{\"heading\":false,\"text\":\"Y respecto a su afirmación de que el desgraciado... Aunque, desgraciado, ¿por qué? Bien; supongamos que lo hubiese sido. Su afirmación, digo, de que el desgraciado, o lo que fuese, Augusto Pérez se suicidó y no murió como yo cuento su muerte, es decir, por mi libérrimo albedrío y decisión, es cosa que me hace sonreír. Opiniones hay, en efecto, que no merecen sino una sonrisa. Y debe de andarse mi amigo y prologuista Goti con mucho tiento en discutir así mis decisiones, porque si me fastidia mucho acabaré por hacer con él lo que con su amigo Pérez hice, y es que le dejaré morir o le mataré a guisa de médico. Los cuales ya saben mis lectores que se mueven en este dilema: o dejan morir al enfermo por miedo a matarle, o le matan por miedo de que se les muera. Y así yo soy capaz de matar a Goti si veo que se me va a morir, o de dejarle morir si temo haber de matarle.\"},{\"heading\":false,\"text\":\"Y no quiero prolongar más este post-prólogo, que es lo bastante para darle la alternativa a mi amigo Víctor Goti, a quien agradezco su trabajo.\"},{\"heading\":false,\"text\":\"M. DE U.\"}]},{\"title\":\"Capítulo I\",\"blocks\":[{\"heading\":false,\"text\":\"Al aparecer Augusto a la puerta de su casa extendió el brazo derecho, con la mano palma abajo y abierta, y dirigiendo los ojos al cielo quedóse un momento parado en esta actitud estatuaria y augusta. No era que tomaba posesión del mundo exterior, sino era que observaba si llovía. Y al recibir en el dorso de la mano el frescor del lento orvallo frunció el sobrecejo. Y no era tampoco que le molestase la llovizna, sino el tener que abrir el paraguas. ¡Estaba tan elegante, tan esbelto, plegado y dentro de su funda! Un paraguas cerrado es tan elegante como es feo un paraguas abierto.\"},{\"heading\":false,\"text\":\"«Es una desgracia esto de tener que servirse uno de las cosas—pensó Augusto—; tener que usarlas. El uso estropea y hasta destruye toda belleza. La función más noble de los objetos es la de ser contemplados. ¡Qué bella es una naranja antes de comida! Esto cambiará en el cielo, cuando todo nuestro oficio se reduzca, o más bien se ensanche a contemplar a Dios y todas las cosas en Él. Aquí, en esta pobre vida, no nos cuidamos sino de servirnos de Dios; pretendemos abrirlo, como a un paraguas, para que nos proteja de toda suerte de males.»\"},{\"heading\":false,\"text\":\"Díjose así y se agachó a recojerse los pantalones. Abrió el paraguas por fin y se quedó un momento suspenso y pensando: «y ahora, ¿hacia dónde voy? ¿tiro a la derecha o a la izquierda?» Porque Augusto no era un caminante, sino un paseante de la vida. «Esperaré a que pase un perro—se dijo—y tomaré la dirección inicial que él tome.»\"},{\"heading\":false,\"text\":\"En esto pasó por la calle no un perro, sino una garrida moza, y tras de sus ojos se fué, como imantado y sin darse de ello cuenta, Augusto.\"},{\"heading\":false,\"text\":\"Y así una calle y otra y otra.\"},{\"heading\":false,\"text\":\"«Pero aquel chiquillo—iba diciéndose Augusto, que más bien que pensaba hablaba consigo mismo—, ¿qué hará allí, tirado de bruces en el suelo? ¡Contemplar a alguna hormiga, de seguro! ¡La hormiga, ¡bah!, uno de los animales más hipócritas! Apenas hace sino pasearse y hacernos creer que trabaja. Es como ese gandul que va ahí, a paso de carga, codeando a todos aquellos con quienes se cruza, y no me cabe duda de que no tiene nada que hacer. ¡Qué ha de tener que hacer, hombre, qué ha de tener que hacer! Es un vago, un vago como... ¡No, yo no soy un vago! Mi imaginación no descansa. Los vagos son ellos, los que dicen que trabajan y no hacen sino aturdirse y ahogar el pensamiento. Porque, vamos a ver, ese mamarracho de chocolatero que se pone ahí, detrás de esa vidriera, a darle al rollo majadero, para que le veamos, ese exhibicionista del trabajo, ¿qué es sino un vago? Y a nosotros ¿qué nos importa que trabaje o no? ¡El trabajo! ¡El trabajo! ¡Hipocresía! Para trabajo el de ese pobre paralítico que va ahí medio arrastrándose... Pero ¿y qué sé yo? ¡Perdone, hermano!—esto se lo dijo en voz alta.—¿Hermano? ¿Hermano en qué? ¡En parálisis! Dicen que todos somos hijos de Adán. Y éste, Joaquinito, ¿es también hijo de Adán? ¡Adiós, Joaquín! ¡Vaya, ya tenemos el inevitable automóvil, ruido y polvo! ¿Y qué se adelanta con suprimir así distancias? La manía de viajar viene de topofobía y no de filotopía; el que viaja mucho va huyendo de cada lugar que deja y no buscando cada lugar a que llega. Viajar... viajar... Qué chisme más molesto es el paraguas... Calla, ¿qué es esto?»\"},{\"heading\":false,\"text\":\"Y se detuvo a la puerta de una casa donde había entrado la garrida moza que le llevara imantado tras de sus ojos. Y entonces se dio cuenta Augusto de que la había venido siguiendo. La portera de la casa le miraba con ojillos maliciosos, y aquella mirada le sugirió a Augusto lo que entonces debía hacer. «Esta Cerbera aguarda—se dijo—que le pregunte por el nombre y circunstancias de esta señorita a que he venido siguiendo, y, ciertamente, esto es lo que procede ahora. Otra cosa sería dejar mi seguimiento sin coronación, y eso no, las obras deben acabarse. ¡Odio lo imperfecto!» Metió la mano al bolsillo y no encontró en él sino un duro. No era cosa de ir entonces a cambiarlo; se perdería tiempo y ocasión en ello.\"},{\"heading\":false,\"text\":\"—Dígame, buena mujer—interpeló a la portera sin sacar el índice y el pulgar del bolsillo—, ¿podría decirme aquí, en confianza y para _inter nos_, el nombre de esta señorita que acaba de entrar?\"},{\"heading\":false,\"text\":\"—Eso no es ningún secreto ni nada malo, caballero.\"},{\"heading\":false,\"text\":\"—Por lo mismo.\"},{\"heading\":false,\"text\":\"—Pues se llama doña Eugenia Domingo del Arco.\"},{\"heading\":false,\"text\":\"—¿Domingo? Será Dominga...\"},{\"heading\":false,\"text\":\"—No, señor, Domingo; Domingo es su primer apellido.\"},{\"heading\":false,\"text\":\"—Pues cuando se trata de mujeres, ese apellido debía cambiarse en Dominga. Y si no, ¿dónde está la concordancia?\"},{\"heading\":false,\"text\":\"—No la conozco, señor.\"},{\"heading\":false,\"text\":\"—Y dígame... dígame...—sin sacar los dedos del bolsillo—, ¿cómo es que sale así sola? ¿Es soltera o casada? ¿Tiene padres?\"},{\"heading\":false,\"text\":\"—Es soltera y huérfana. Vive con unos tíos...\"},{\"heading\":false,\"text\":\"—¿Paternos o maternos?\"},{\"heading\":false,\"text\":\"—Sólo sé que son tíos.\"},{\"heading\":false,\"text\":\"—Basta y aun sobra.\"},{\"heading\":false,\"text\":\"—Se dedica a dar lecciones de piano.\"},{\"heading\":false,\"text\":\"—¿Y le toca bien?\"},{\"heading\":false,\"text\":\"—Ya tanto no sé.\"},{\"heading\":false,\"text\":\"—Bueno, bien, basta; y tome por la molestia.\"},{\"heading\":false,\"text\":\"—Gracias, señor, gracias. ¿Se le ofrece más? ¿Puedo servirle en algo? ¿Desea le lleve algún mandado?\"},{\"heading\":false,\"text\":\"—Tal vez... tal vez... No por ahora... ¡Adiós!\"},{\"heading\":false,\"text\":\"—Disponga de mí, caballero, y cuente con una absoluta discreción.\"},{\"heading\":false,\"text\":\"«Pues señor—iba diciéndose Augusto al separarse de la portera—, ve aquí cómo he quedado comprometido con esta buena mujer. Porque ahora no puedo dignamente dejarlo así. Qué dirá si no de mí este dechado de porteras. ¿Conque... Eugenia Dominga, digo Domingo, del Arco? Muy bien, voy a apuntarlo, no sea que se me olvide. No hay más arte mnemotécnica que llevar un libro de memorias en el bolsillo. Ya lo decía mi inolvidable don Leoncio: ¡no metáis en la cabeza lo que os quepa en el bolsillo! A lo que habría que añadir por complemento: ¡no metáis en el bolsillo lo que os quepa en la cabeza! Y la portera, ¿cómo se llama la portera?»\"},{\"heading\":false,\"text\":\"Volvió unos pasos atrás.\"},{\"heading\":false,\"text\":\"—Dígame una cosa más, buena mujer...\"},{\"heading\":false,\"text\":\"—Usted mande...\"},{\"heading\":false,\"text\":\"—Y usted, ¿cómo se llama?\"},{\"heading\":false,\"text\":\"—¿Yo? Margarita.\"},{\"heading\":false,\"text\":\"—¡Muy bien, muy bien... gracias!\"},{\"heading\":false,\"text\":\"—No hay de qué.\"},{\"heading\":false,\"text\":\"Y volvió a marcharse Augusto, encontrándose al poco rato en el paseo de la Alameda.\"},{\"heading\":false,\"text\":\"Había cesado la llovizna. Cerró y plegó su paraguas y lo enfundó. Acercóse a un banco, y al palparlo se encontró con que estaba húmedo. Sacó un periódico, lo colocó sobre el banco y sentóse. Luego su cartera y blandió su pluma estilográfica. «He aquí un chisme utilísimo—se dijo—; de otro modo, tendría que apuntar con lápiz el nombre de esa señorita y podría borrarse. ¿Se borrará su imagen de mi memoria? Pero ¿cómo es? ¿Cómo es la dulce Eugenia? Sólo me acuerdo de unos ojos... Tengo la sensación del toque de unos ojos... Mientras yo divagaba líricamente, unos ojos tiraban dulcemente de mi corazón. ¡Veamos! Eugenia Domingo, sí, Domingo, del Arco. ¿Domingo? No me acostumbro a eso de que se llame Domingo... No; he de hacerle cambiar el apellido y que se llame Dominga. Pero, y nuestros hijos varones, ¿habrán de llevar por segundo apellido el de Dominga? Y como han de suprimir el mío, este impertinente Pérez, dejándolo en una P., ¿se ha de llamar nuestro primogénito Augusto P. Dominga? Pero... ¿adónde me llevas, loca fantasía?» Y apuntó en su cartera: Eugenia Domingo del Arco, Avenida de la Alameda, 58. Encima de esta apuntación había estos dos endecasílabos:\"},{\"heading\":false,\"text\":\"De la cuna nos viene la tristeza y también de la cuna la alegría...\"},{\"heading\":false,\"text\":\"«Vaya—se dijo Augusto—, esta Eugenita, la profesora de piano, me ha cortado un excelente principio de poesía lírica trascendental. Me queda interrumpida. ¿Interrumpida?... Sí, el hombre no hace sino buscar en los sucesos, en las vicisitudes de la suerte, alimento para su tristeza o su alegría nativas. Un mismo caso es triste o alegre según nuestra disposición innata. ¿Y Eugenia? Tengo que escribirle. Pero no desde aquí, sino desde casa. ¿Iré más bien al Casino? No, a casa, a casa. Estas cosas desde casa, desde el hogar. ¿Hogar? Mi casa no es hogar. Hogar... hogar... ¡Cenicero más bien! ¡Ay, mi Eugenia!»\"},{\"heading\":false,\"text\":\"Y se volvió Augusto a su casa.\"}]},{\"title\":\"Capítulo II\",\"blocks\":[{\"heading\":false,\"text\":\"Al abrirle el criado la puerta...\"},{\"heading\":false,\"text\":\"Augusto, que era rico y solo, pues su anciana madre había muerto no hacía sino seis meses antes de estos menudos sucedidos, vivía con un criado y una cocinera, sirvientes antiguos en la casa e hijos de otros que en ella misma habían servido. El criado y la cocinera estaban casados entre sí, pero no tenían hijos.\"},{\"heading\":false,\"text\":\"Al abrirle el criado la puerta le preguntó Augusto si en su ausencia había llegado alguien.\"},{\"heading\":false,\"text\":\"—Nadie, señorito.\"},{\"heading\":false,\"text\":\"Eran pregunta y respuesta sacramentales, pues apenas recibía visitas en casa Augusto.\"},{\"heading\":false,\"text\":\"Entró en su gabinete, tomó un sobre y escribió en él: «Señorita doña Eugenia Domingo del Arco. E. P. M.» Y enseguida, delante del blanco papel, apoyó la cabeza en ambas manos, los codos en el escritorio, y cerró los ojos. «Pensemos primero en ella»—se dijo. Y esforzóse por atrapar en la oscuridad el resplandor de aquellos otros ojos que le arrastraran al azar.\"},{\"heading\":false,\"text\":\"Estuvo así un rato sugiriéndose la figura de Eugenia, y como apenas si la había visto, tuvo que figurársela. Merced a esta labor de evocación fué surgiendo a su fantasía una figura vagarosa ceñida de ensueños. Y se quedó dormido. Se quedó dormido porque había pasado mala noche, de insomnio.\"},{\"heading\":false,\"text\":\"—¡Señorito!\"},{\"heading\":false,\"text\":\"—¿Eh?—exclamó despertándose.\"},{\"heading\":false,\"text\":\"—Está ya servido el almuerzo.\"},{\"heading\":false,\"text\":\"¿Fué la voz del criado, o fué el apetito, de que aquella voz no era sino un eco, lo que le despertó? ¡Misterios psicológicos! Así pensó Augusto, que se fué al comedor diciéndose: ¡oh, la psicología!\"},{\"heading\":false,\"text\":\"Almorzó con fruición su almuerzo de todos los días: un par de huevos fritos, un bisteque con patatas y un trozo de queso Gruyère. Tomó luego su café y se tendió en la mecedora. Encendió un habano, se lo llevó a la boca, y diciéndose: «¡Ay, mi Eugenia!» se dispuso a pensar en ella.\"},{\"heading\":false,\"text\":\"«¡Mi Eugenia, sí, la mía—iba diciéndose—, ésta que me estoy forjando a solas, y no la otra, no la de carne y hueso, no la que vi cruzar por la puerta de mi casa, aparición fortuita, no la de la portera! ¿Aparición fortuita? ¿Y qué aparición no lo es? ¿Cuál es la lógica de las apariciones? La de la sucesión de estas figuras que forman las nubes de humo del cigarro. ¡El azar! el azar es el íntimo ritmo del mundo, el azar es el alma de la poesía. ¡Ah, mi azarosa Eugenia! Esta mi vida mansa, rutinaria, humilde, es una oda pindárica tejida con las mil pequeñeces de lo cotidiano. ¡Lo cotidiano! ¡El pan nuestro de cada día, dánosle hoy! Dame, Señor, las mil menudencias de cada día. Los hombres no sucumbimos a las grandes penas ni a las grandes alegrías, y es porque esas penas y esas alegrías vienen embozadas en una inmensa niebla de pequeños incidentes. Y la vida es esto, la niebla. La vida es una nebulosa. Ahora surge de ella Eugenia. ¿Y quién es Eugenia? Ah, caigo en la cuenta de que hace tiempo la andaba buscando. Y mientras yo la buscaba ella me ha salido al paso. ¿No es esto acaso encontrar algo? Cuando uno descubre una aparición que buscaba, ¿no es que la aparición, compadecida de su busca, se le viene al encuentro? ¿No salió la América a buscar a Colón? ¿No ha venido Eugenia a buscarme a mí? ¡Eugenia! ¡Eugenia! ¡Eugenia!»\"},{\"heading\":false,\"text\":\"Y Augusto se encontró pronunciando en voz alta el nombre de Eugenia. Al oirle llamar, el criado, que acertaba a pasar junto al comedor, entró diciendo:\"},{\"heading\":false,\"text\":\"—¿Llamaba, señorito?\"},{\"heading\":false,\"text\":\"—¡No, a ti no! Pero, calla, ¿no te llamas tú Domingo?\"},{\"heading\":false,\"text\":\"—Sí, señorito—respondió Domingo sin extrañeza alguna por la pregunta que se le hacía.\"},{\"heading\":false,\"text\":\"—¿Y por qué te llamas Domingo?\"},{\"heading\":false,\"text\":\"—Porque así me llaman.\"},{\"heading\":false,\"text\":\"«Bien, muy bien—se dijo Augusto—; nos llamamos como nos llaman. En los tiempos homéricos tenían las personas y las cosas dos nombres, el que les daban los hombres y el que les daban los dioses. ¿Cómo me llamará Dios? ¿Y por qué no he de llamarme yo de otro modo que como los demás me llaman? ¿Por qué no he de dar a Eugenia otro nombre distinto del que le dan los demás, del que le da Margarita, la portera? ¿Cómo la llamaré?»\"},{\"heading\":false,\"text\":\"—Puedes irte—le dijo al criado.\"},{\"heading\":false,\"text\":\"Se levantó de la mecedora, fué al gabinete, tomó la pluma y se puso a escribir:\"},{\"heading\":false,\"text\":\"«Señorita: Esta misma mañana, bajo la dulce llovizna del cielo, cruzó usted, aparición fortuita, por delante de la puerta de la casa donde aún vivo y ya no tengo hogar. Cuando desperté fuí a la puerta de la suya, donde ignoro si tiene usted hogar o no le tiene. Me habían llevado allí sus ojos, sus ojos, que son refulgentes estrellas mellizas en la nebulosa de mi mundo. Perdóneme, Eugenia, y deje que le dé familiarmente este dulce nombre; perdóneme la lírica. Yo vivo en perpetua lírica infinitesimal.\"},{\"heading\":false,\"text\":\"No sé qué más decirle. Sí, sí sé. Pero es tanto, tanto lo que tengo que decirle, que estimo mejor aplazarlo para cuando nos veamos y nos hablemos. Pues es lo que ahora deseo, que nos veamos, que nos hablemos, que nos escribamos, que nos conozcamos. Después... Después, ¡Dios y nuestros corazones dirán!\"},{\"heading\":false,\"text\":\"¿Me dará usted, pues, Eugenia, dulce aparición de mi vida cotidiana, me dará usted oídos?\"},{\"heading\":false,\"text\":\"Sumido en la niebla de su vida espera su respuesta.\"},{\"heading\":false,\"text\":\"AUGUSTO PÉREZ.»\"},{\"heading\":false,\"text\":\"Y rubricó diciéndose: «Me gusta esta costumbre de la rúbrica por lo inútil».\"},{\"heading\":false,\"text\":\"Cerró la carta y volvió a echarse a la calle.\"},{\"heading\":false,\"text\":\"«¡Gracias a Dios—se decía camino de la Avenida de la Alameda—, gracias a Dios que sé adónde voy y que tengo adónde ir! Esta mi Eugenia es una bendición de Dios. Ya ha dado una finalidad, un hito de término a mis vagabundeos callejeros. Ya tengo casa que rondar; ya tengo una portera confidente...»\"},{\"heading\":false,\"text\":\"Mientras iba así hablando consigo mismo cruzó con Eugenia sin advertir siquiera el resplandor de sus ojos. La niebla espiritual era demasiado densa. Pero Eugenia, por su parte, sí se fijó en él, diciéndose: «¿quién será este joven? ¡no tiene mal porte y parece bien acomodado!» Y es que, sin darse clara cuenta de ello, adivinó a uno que por la mañana la había seguido. Las mujeres saben siempre cuándo se las mira, aun sin verlas, y cuándo se las ve sin mirarlas.\"},{\"heading\":false,\"text\":\"Y siguieron los dos, Augusto y Eugenia, en direcciones contrarias, cortando con sus almas la enmarañada telaraña espiritual de la calle. Porque la calle forma un tejido en que se entrecruzan miradas de deseo, de envidia, de desdén, de compasión, de amor, de odio, viejas palabras cuyo espíritu quedó cristalizado, pensamientos, anhelos, toda una tela misteriosa que envuelve las almas de los que pasan.\"},{\"heading\":false,\"text\":\"Por fin se encontró Augusto una vez más ante Margarita la portera, ante la sonrisa de Margarita. Lo primero que hizo ésta al ver a aquél fué sacar la mano del bolsillo del delantal.\"},{\"heading\":false,\"text\":\"—Buenas tardes, Margarita.\"},{\"heading\":false,\"text\":\"—Buenas tardes, señorito.\"},{\"heading\":false,\"text\":\"—Augusto, buena mujer, Augusto.\"},{\"heading\":false,\"text\":\"—Don Augusto—añadió ella.\"},{\"heading\":false,\"text\":\"—No a todos los nombres les cae el don—observó él—. Así como de Juan a don Juan hay un abismo, así le hay de Augusto a don Augusto. ¡Pero... sea! ¿Salió la señorita Eugenia?\"},{\"heading\":false,\"text\":\"—Sí, hace un momento.\"},{\"heading\":false,\"text\":\"—¿En qué dirección?\"},{\"heading\":false,\"text\":\"—Por ahí.\"},{\"heading\":false,\"text\":\"Y por ahí se dirigió Augusto. Pero al rato volvióse. Se le había olvidado la carta.\"},{\"heading\":false,\"text\":\"—¿Hará el favor, señora Margarita, de hacer llegar esta carta a las propias blancas manos de la señorita Eugenia?\"},{\"heading\":false,\"text\":\"—Con mucho gusto.\"},{\"heading\":false,\"text\":\"—Pero a sus propias blancas manos, ¿eh? A sus manos tan marfileñas como las teclas del piano a que acarician.\"},{\"heading\":false,\"text\":\"—Sí, ya, lo sé de otras veces.\"},{\"heading\":false,\"text\":\"—¿De otras veces? ¿Qué es eso de otras veces?\"},{\"heading\":false,\"text\":\"—Pero ¿es que cree el caballero que es ésta la primera carta de este género...?\"},{\"heading\":false,\"text\":\"—¿De este género? Pero ¿usted sabe el género de mi carta?\"},{\"heading\":false,\"text\":\"—Desde luego. Como las otras.\"},{\"heading\":false,\"text\":\"—¿Como las otras? ¿Como qué otras?\"},{\"heading\":false,\"text\":\"—¡Pues pocos pretendientes que ha tenido la señorita...!\"},{\"heading\":false,\"text\":\"—Ah, ¿pero ahora está vacante?\"},{\"heading\":false,\"text\":\"—¿Ahora? No, no, señor, tiene algo así como un novio... aunque creo que no es sino aspirante a novio... Acaso le tenga en prueba... puede ser que sea interino...\"},{\"heading\":false,\"text\":\"—¿Y cómo no me lo dijo?\"},{\"heading\":false,\"text\":\"—Como usted no me lo preguntó...\"},{\"heading\":false,\"text\":\"—Es cierto. Sin embargo, entréguele esta carta y en propias manos, ¿entiende? ¡Lucharemos! ¡Y vaya otro duro!\"},{\"heading\":false,\"text\":\"—Gracias, señor, gracias.\"},{\"heading\":false,\"text\":\"Con trabajo se separó de allí Augusto, pues la conversación nebulosa, cotidiana, de Margarita la portera empezaba a agradarle. ¿No era acaso un modo de matar el tiempo?\"},{\"heading\":false,\"text\":\"«¡Lucharemos!—iba diciéndose Augusto calle abajo—¡sí, lucharemos! ¿Conque tiene otro novio, otro aspirante a novio...? ¡Lucharemos! _Militia est vita hominis super terram_. Ya tiene mi vida una finalidad; ya tengo una conquista que llevar a cabo. ¡Oh, Eugenia, mi Eugenia, has de ser mía! ¡Por lo menos, mi Eugenia, ésta que me he forjado sobre la visión fugitiva de aquellos ojos, de aquella yunta de estrellas en mi nebulosa, esta Eugenia sí que ha de ser mía, sea la otra, la de la portera, de quien fuere! ¡Lucharemos! Lucharemos y venceré. Tengo el secreto de la victoria. ¡Ah, Eugenia, mi Eugenia!»\"},{\"heading\":false,\"text\":\"Y se encontró a la puerta del Casino, donde ya Víctor le esperaba para echar la cotidiana partida de ajedrez.\"}]},{\"title\":\"Capítulo III\",\"blocks\":[{\"heading\":false,\"text\":\"—Hoy te retrasaste un poco, chico—dijo Víctor a Augusto—, ¡tú, tan puntual siempre!\"},{\"heading\":false,\"text\":\"—Qué quieres... quehaceres...\"},{\"heading\":false,\"text\":\"—¿Quehaceres, tú?\"},{\"heading\":false,\"text\":\"—Pero ¿es que crees que sólo tienen quehaceres los agentes de bolsa? La vida es mucho más compleja de lo que tú te figuras.\"},{\"heading\":false,\"text\":\"—O yo más simple de lo que tú crees...\"},{\"heading\":false,\"text\":\"—Todo pudiera ser.\"},{\"heading\":false,\"text\":\"—¡Bien, sal!\"},{\"heading\":false,\"text\":\"Augusto avanzó dos casillas el peón del rey, y en vez de tararear como otras veces trozos de ópera, se quedó diciéndose: «¡Eugenia, Eugenia, Eugenia, mi Eugenia, finalidad de mi vida, dulce resplandor de estrellas mellizas en la niebla, lucharemos! Aquí sí que hay lógica, en esto del ajedrez, y, sin embargo, ¡qué nebuloso, qué fortuito después de todo! ¿No será la lógica también algo fortuito, algo azaroso? Y esa aparición de mi Eugenia, ¿no será algo lógico? ¿No obedecerá a un ajedrez divino?»\"},{\"heading\":false,\"text\":\"—Pero, hombre—le interrumpió Víctor—, ¿no quedamos en que no sirve volver atrás la jugada? ¡Pieza tocada, pieza jugada!\"},{\"heading\":false,\"text\":\"—En eso quedamos, sí.\"},{\"heading\":false,\"text\":\"—Pues si haces eso te como gratis ese alfil.\"},{\"heading\":false,\"text\":\"—Es verdad, es verdad; me había distraído.\"},{\"heading\":false,\"text\":\"—Pues no distraerse; que el que juega no asa castañas. Y ya lo sabes; pieza tocada, pieza jugada.\"},{\"heading\":false,\"text\":\"—¡Vamos, sí, lo irreparable!\"},{\"heading\":false,\"text\":\"—Así debe ser. Y en ello consiste lo educativo de este juego.\"},{\"heading\":false,\"text\":\"«¿Y por qué no ha de distraerse uno en el juego?—se decía Augusto—. ¿Es o no es un juego la vida? ¿Y por qué no ha de servir volver atrás las jugadas? ¡Esto es la lógica! Acaso esté ya la carta en manos de Eugenia. _Alea iacta est!_ A lo hecho, pecho. ¿Y mañana? ¡Mañana es de Dios! ¿Y ayer, de quién es? ¿De quién es ayer? ¡Oh, ayer, tesoro de los fuertes! ¡Santo ayer, sustancia de la niebla cotidiana!»\"},{\"heading\":false,\"text\":\"—¡Jaque!—volvió a interrumpirle Víctor.\"},{\"heading\":false,\"text\":\"—Es verdad, es verdad... veamos... Pero ¿cómo he dejado que las cosas lleguen a este punto?\"},{\"heading\":false,\"text\":\"—Distrayéndote, hombre, como de costumbre. Si no fueses tan distraído serías uno de nuestros primeros jugadores.\"},{\"heading\":false,\"text\":\"—Pero, dime, Víctor, ¿la vida es juego o es distracción?\"},{\"heading\":false,\"text\":\"—Es que el juego no es sino distracción.\"},{\"heading\":false,\"text\":\"—Entonces, ¿qué más da distraerse de un modo o de otro?\"},{\"heading\":false,\"text\":\"—Hombre, de jugar, jugar bien.\"},{\"heading\":false,\"text\":\"—¿Y por qué no jugar mal? ¿Y qué es jugar bien y qué jugar mal? ¿Por qué no hemos de mover estas piezas de otro modo que como las movemos?\"},{\"heading\":false,\"text\":\"—Esto es la tesis, Augusto amigo, según tú, filósofo conspicuo, me has enseñado.\"},{\"heading\":false,\"text\":\"—Bueno, pues voy a darte una gran noticia.\"},{\"heading\":false,\"text\":\"—¡Venga!\"},{\"heading\":false,\"text\":\"—Pero, asómbrate, chico.\"},{\"heading\":false,\"text\":\"—Yo no soy de los que se asombran _a priori_ o de antemano.\"},{\"heading\":false,\"text\":\"—Pues allá va: ¿sabes lo que me pasa?\"},{\"heading\":false,\"text\":\"—Que cada vez estás más distraído.\"},{\"heading\":false,\"text\":\"—Pues me pasa que me he enamorado.\"},{\"heading\":false,\"text\":\"—Bah, eso ya lo sabía yo.\"},{\"heading\":false,\"text\":\"—¿Cómo que lo sabías...?\"},{\"heading\":false,\"text\":\"—Naturalmente, tú estás enamorado _ab origine_, desde que naciste; tienes un amorío innato.\"},{\"heading\":false,\"text\":\"—Sí, el amor nace con nosotros cuando nacemos.\"},{\"heading\":false,\"text\":\"—No he dicho amor, sino amorío. Y ya sabía yo, sin que tuvieras que decírmelo, que estabas enamorado o más bien enamoriscado. Lo sabía mejor que tú mismo.\"},{\"heading\":false,\"text\":\"—Pero ¿de quién? Dime, ¿de quién?\"},{\"heading\":false,\"text\":\"—Eso no lo sabes tú más que yo.\"},{\"heading\":false,\"text\":\"—Pues, calla, mira, acaso tengas razón...\"},{\"heading\":false,\"text\":\"—¿No te lo dije? Y si no, dime, ¿es rubia o morena?\"},{\"heading\":false,\"text\":\"—Pues, la verdad, no lo sé. Aunque me figuro que debe de ser ni lo uno ni lo otro; vamos, así, pelicastaña.\"},{\"heading\":false,\"text\":\"—¿Es alta o baja?\"},{\"heading\":false,\"text\":\"—Tampoco me acuerdo bien. Pero debe de ser una cosa regular. Pero ¡qué ojos, chico, qué ojos tiene mi Eugenia!\"},{\"heading\":false,\"text\":\"—¿Eugenia?\"},{\"heading\":false,\"text\":\"—Sí, Eugenia Domingo del Arco, Avenida de la Alameda, 58.\"},{\"heading\":false,\"text\":\"—¿La profesora de piano?\"},{\"heading\":false,\"text\":\"—La misma. Pero...\"},{\"heading\":false,\"text\":\"—Sí, la conozco. Y ahora... ¡jaque otra vez!\"},{\"heading\":false,\"text\":\"—Pero...\"},{\"heading\":false,\"text\":\"—¡Jaque he dicho!\"},{\"heading\":false,\"text\":\"—Bueno...\"},{\"heading\":false,\"text\":\"Y Augusto cubrió el rey con un caballo. Y acabó perdiendo el juego.\"},{\"heading\":false,\"text\":\"Al despedirse, Víctor, poniéndose la diestra, a guisa de yugo, sobre el cerviguillo, le susurró al oído:\"},{\"heading\":false,\"text\":\"—Conque Eugenita la pianista, ¿eh? Bien, Augustito, bien; tú poseerás la tierra.\"},{\"heading\":false,\"text\":\"«¡Pero esos diminutivos—pensó Augusto, esos terribles diminutivos!» Y salió a la calle.\"}]},{\"title\":\"Capítulo IV\",\"blocks\":[{\"heading\":false,\"text\":\"«¿Por qué el diminutivo es señal de cariño?—iba diciéndose Augusto camino de su casa—. ¿Es acaso que el amor achica la cosa amada? ¡Enamorado yo! ¡Yo enamorado! ¡Quién había de decirlo...! Pero ¿tendrá razón Víctor? ¿Seré un enamorado _ab initio_? Tal vez mi amor ha precedido a su objeto. Es más, es este amor el que lo ha suscitado, el que lo ha extraído de la niebla de la creación. Pero si yo adelanto aquella torre no me da el mate, no me lo da. ¿Y qué es amor? ¿Quién definió el amor? Amor definido deja de serlo... Pero, Dios mío, ¿por qué permitirá el alcalde que empleen para los rótulos de los comercios tipos de letra tan feos como ése? Aquel alfil estuvo mal jugado. ¿Y cómo me he enamorado si en rigor no puedo decir que la conozco? Bah, el conocimiento vendrá después. El amor precede al conocimiento, y éste mata a aquél. _Nihil volitum quin praecognitum_ me enseñó el P. Zaramillo, pero yo he llegado a la conclusión contraria y es que _nihil cognitum quin praevolitum_. Conocer es perdonar, dicen. No, perdonar es conocer. Primero el amor, el conocimiento después. Pero ¿cómo no vi que me daba mate al descubierto? Y para amar algo, ¿qué basta? ¡Vislumbrarlo! El vislumbre; he aquí la intuición amorosa, el vislumbre en la niebla. Luego viene el precisarse, la visión perfecta, el resolverse la niebla en gotas de agua o en granizo, o en nieve, o en piedra. La ciencia es una pedrea. ¡No, no, niebla, niebla! ¡Quién fuera águila para pasearse por los senos de las nubes! Y ver al sol a través de ellas, como lumbre nebulosa también.\"},{\"heading\":false,\"text\":\"¡Oh, el águila! ¡Qué cosas se dirían el águila de Patmos, la que mira al sol cara a cara y no ve en la negrura de la noche, cuando escapándose de junto a San Juan se encontró con la lechuza de Minerva, la que ve en lo oscuro de la noche, pero no puede mirar al sol, y se había escapado del Olimpo!»\"},{\"heading\":false,\"text\":\"Al llegar a este punto cruzó Augusto con Eugenia y no reparó en ella.\"},{\"heading\":false,\"text\":\"«El conocimiento viene después...—siguió diciéndose—. Pero... ¿Qué ha sido eso? Juraría que han cruzado por mi órbita dos refulgentes y místicas estrellas gemelas... ¿Habrá sido ella? El corazón me dice... ¡Pero, calla, ya estoy en casa!»\"},{\"heading\":false,\"text\":\"Y entró.\"},{\"heading\":false,\"text\":\"Dirigióse a su cuarto, y al reparar en la cama se dijo: «¡Solo! ¡dormir solo! ¡soñar solo! Cuando se duerme en compañía, el sueño debe de ser común. Misteriosos efluvios han de unir los dos cerebros. ¿O no es acaso que a medida que los corazones más se unen, más se separan las cabezas? Tal vez. Tal vez están en posiciones mutuamente adversas. Si dos amantes piensan lo mismo, sienten en contrario uno del otro; si comulgan en el mismo sentimiento amoroso, cada cual piensa otra cosa que el otro, tal vez lo contrario. La mujer sólo ama a su hombre mientras no piense como ella, es decir, mientras piense. Veamos a este honrado matrimonio.»\"},{\"heading\":false,\"text\":\"Muchas noches, antes de acostarse, solía Augusto echar una partida de tute con su criado, Domingo, y mientras, la mujer de éste, la cocinera, contemplaba el juego.\"},{\"heading\":false,\"text\":\"Empezó la partida.\"},{\"heading\":false,\"text\":\"—¡Veinte en copas!—cantó Domingo.\"},{\"heading\":false,\"text\":\"—¡Decidme!—exclamó Augusto de pronto—. ¿Y si yo me casara?\"},{\"heading\":false,\"text\":\"—Muy bien hecho, señorito—dijo Domingo.\"},{\"heading\":false,\"text\":\"—Según y conforme—se atrevió a insinuar Liduvina, su mujer.\"},{\"heading\":false,\"text\":\"—Pues ¿no te casaste tú?—le interpeló Augusto.\"},{\"heading\":false,\"text\":\"—Según y conforme, señorito.\"},{\"heading\":false,\"text\":\"—¿Cómo según y conforme? Habla.\"},{\"heading\":false,\"text\":\"—Casarse es muy fácil; pero no es tan fácil ser casado.\"},{\"heading\":false,\"text\":\"—Eso pertenece a la sabiduría popular, fuente de...\"},{\"heading\":false,\"text\":\"—Y lo que es la que haya de ser mujer del señorito...—agrego Liduvina, temiendo que Augusto les espetara todo un monólogo.\"},{\"heading\":false,\"text\":\"—¿Qué? La que haya de ser mi mujer, ¿qué? Vamos, ¡dilo, dilo, mujer, dilo!\"},{\"heading\":false,\"text\":\"—Pues que como el señorito es tan bueno...\"},{\"heading\":false,\"text\":\"—Anda, dilo, mujer, dilo de una vez.\"},{\"heading\":false,\"text\":\"—Ya recuerda lo que decía la señora...\"},{\"heading\":false,\"text\":\"A la piadosa mención de su madre Augusto dejó las cartas sobre la mesa, y su espíritu quedó un momento en suspenso. Muchas veces su madre, aquella dulce señora, hija del infortunio, le había dicho: «Yo no puedo vivir ya mucho, hijo mío; tu padre me está llamando. Acaso le hago a él más falta que a ti. Así que yo me vaya de este mundo y te quedes solo en él tú, cásate, cásate cuanto antes. Trae a esta casa dueña y señora. Y no es que yo no tenga confianza en nuestros antiguos y fieles servidores, no. Pero trae ama a la casa. Y que sea ama de casa, hijo mío, que sea ama. Hazla dueña de tu corazón, de tu bolsa, de tu despensa, de tu cocina y de tus resoluciones. Busca una mujer de gobierno, que sepa querer... y gobernarte».\"},{\"heading\":false,\"text\":\"—Mi mujer tocará el piano—dijo Augusto sacudiendo sus recuerdos y añoranzas.\"},{\"heading\":false,\"text\":\"—¡El piano! Y eso ¿para qué sirve?—preguntó Liduvina.\"},{\"heading\":false,\"text\":\"—¿Para qué sirve? Pues ahí estriba su mayor encanto, en que no sirve para maldita de Dios la cosa, lo que se llama servir. Estoy harto de servicios...\"},{\"heading\":false,\"text\":\"—¿De los nuestros?\"},{\"heading\":false,\"text\":\"—¡No, de los vuestros, no! Y además el piano sirve, sí sirve... sirve para llenar de armonía los hogares y que no sean ceniceros.\"},{\"heading\":false,\"text\":\"—¡Armonía! Y eso ¿con qué se come?\"},{\"heading\":false,\"text\":\"—Liduvina... Liduvina...\"},{\"heading\":false,\"text\":\"La cocinera bajó la cabeza ante el dulce reproche. Era la costumbre de uno y de otra.\"},{\"heading\":false,\"text\":\"—Sí, tocará el piano, porque es profesora de piano.\"},{\"heading\":false,\"text\":\"—Entonces no lo tocará—añadió con firmeza Liduvina—. Y si no, ¿para qué se casa?\"},{\"heading\":false,\"text\":\"—Mi Eugenia...—empezó Augusto.\"},{\"heading\":false,\"text\":\"—¿Ah, pero se llama Eugenia y es maestra de piano?—preguntó la cocinera.\"},{\"heading\":false,\"text\":\"—Sí, ¿pues?\"},{\"heading\":false,\"text\":\"—¿La que vive con unos tíos en la Avenida de la Alameda, encima del comercio del señor Tiburcio?\"},{\"heading\":false,\"text\":\"—La misma. ¿Qué, la conoces?\"},{\"heading\":false,\"text\":\"—Sí... de vista...\"},{\"heading\":false,\"text\":\"—No, algo más, Liduvina, algo más. Vamos, habla; mira que se trata del porvenir y de la dicha de tu amo...\"},{\"heading\":false,\"text\":\"—Es buena muchacha, sí, buena muchacha...\"},{\"heading\":false,\"text\":\"—Vamos, habla, Liduvina... ¡por la memoria de mi madre!...\"},{\"heading\":false,\"text\":\"—Acuérdese de sus consejos, señorito. Pero ¿quién anda en la cocina? ¿A que es el gato?...\"},{\"heading\":false,\"text\":\"Y levantándose la criada, se salió.\"},{\"heading\":false,\"text\":\"—¿Y qué, acabamos?—preguntó Domingo.\"},{\"heading\":false,\"text\":\"—Es verdad, Domingo, no podemos dejar así la partida. ¿A quién le toca salir?\"},{\"heading\":false,\"text\":\"—A usted, señorito.\"},{\"heading\":false,\"text\":\"—Pues allá va.\"},{\"heading\":false,\"text\":\"Y perdió también la partida, por distraído.\"},{\"heading\":false,\"text\":\"«Pues, señor—se decía al retirarse a su cuarto—, todos la conocen; todos la conocen menos yo. He aquí la obra del amor. ¿Y mañana? ¿Qué haré mañana? ¡Bah! A cada día bástele su cuidado. Ahora, a la cama.»\"},{\"heading\":false,\"text\":\"Y se acostó.\"},{\"heading\":false,\"text\":\"Y ya en la cama siguió diciéndose: «Pues el caso es que he estado aburriéndome sin saberlo, y dos mortales años... desde que murió mi santa madre... Sí, sí, hay un aburrimiento inconsciente. Casi todos los hombres nos aburrimos inconscientemente. El aburrimiento es el fondo de la vida, y el aburrimiento es el que ha inventado los juegos, las distracciones, las novelas y el amor. La niebla de la vida rezuma un dulce aburrimiento, licor agridulce. Todos estos sucesos cotidianos, insignificantes; todas estas dulces conversaciones con que matamos el tiempo y alargamos la vida, ¿qué son sino dulcísimo aburrirse? ¡Oh, Eugenia, mi Eugenia, flor de mi aburrimiento vital e inconsciente, asísteme en mis sueños, sueña en mí y conmigo!»\"},{\"heading\":false,\"text\":\"Y quedóse dormido.\"}]},{\"title\":\"Capítulo V\",\"blocks\":[{\"heading\":false,\"text\":\"Cruzaba las nubes, águila refulgente, con las poderosas alas perladas de rocío, fijos los ojos de presa en la niebla solar, dormido el corazón en dulce aburrimiento al amparo del pecho forjado en tempestades; en derredor, el silencio que hacen los rumores remotos de la tierra, y allá en lo alto, en la cima del cielo, dos estrellas mellizas derramando bálsamo invisible. Desgarró el silencio un chillido estridente que decía: «_¡La Correspondencia...!_» Y vislumbró Augusto la luz de un nuevo día.\"},{\"heading\":false,\"text\":\"«¿Sueño o vivo?—se preguntó embozándose en la manta—. ¿Soy águila o soy hombre? ¿Qué dirá el papel ése? ¿Qué novedades me traerá el nuevo día consigo? ¿Se habrá tragado esta noche un terremoto a Corcubión? ¿Y por qué no a Leipzig? ¡Oh, la asociación lírica de ideas, el desorden pindárico! El mundo es un caleidoscopio. La lógica la pone el hombre. El supremo arte es el del azar. Durmamos, pues, un rato más.» Y diose media vuelta en la cama.\"},{\"heading\":false,\"text\":\"_¡La Correspondencia...!_ ¡El vinagrero! Y luego un coche, y después un automóvil, y unos chiquillos después.\"},{\"heading\":false,\"text\":\"«¡Imposible!—volvió a decirse Augusto—. Esto es la vida que vuelve. Y con ella el amor... ¿Y qué es el amor? ¿No es acaso la destilación de todo esto? ¿No es el jugo del aburrimiento? Pensemos en Eugenia; la hora es propicia.»\"},{\"heading\":false,\"text\":\"Y cerró los ojos con el propósito de pensar en Eugenia. ¿Pensar?\"},{\"heading\":false,\"text\":\"Pero este pensamiento se le fué diluyendo, derritiéndosele, y al poco rato no era sino una polca. Es que un piano de manubrio se había parado al pie de la ventana de su cuarto y estaba sonando. Y el alma de Augusto repercutía notas, no pensaba.\"},{\"heading\":false,\"text\":\"«La esencia del mundo es musical—se dijo Augusto cuando murió la última nota del organillo—. Y mi Eugenia, ¿no es musical también? Toda ley es una ley de ritmo, y el ritmo es el amor. He aquí que la divina mañana, virginidad del día, me trae un descubrimiento: el amor es el ritmo. La ciencia del ritmo son las matemáticas; la expresión sensible del amor es la música. La expresión, no su realización; entendámonos.»\"},{\"heading\":false,\"text\":\"Le interrumpió un golpecito a la puerta.\"},{\"heading\":false,\"text\":\"—¡Adelante!\"},{\"heading\":false,\"text\":\"—¿Llamaba, señorito?—dijo Domingo.\"},{\"heading\":false,\"text\":\"—¡Sí... el desayuno!\"},{\"heading\":false,\"text\":\"Había llamado, sin haberse dado de ello cuenta, lo menos hora y media antes que de costumbre, y una vez que hubo llamado tenía que pedir el desayuno, aunque no era hora.\"},{\"heading\":false,\"text\":\"«El amor aviva y anticipa el apetito—siguió diciéndose Augusto—. ¡Hay que vivir para amar! Sí, ¡y hay que amar para vivir!»\"},{\"heading\":false,\"text\":\"Se levantó a tomar el desayuno.\"},{\"heading\":false,\"text\":\"—¿Qué tal tiempo hace, Domingo?\"},{\"heading\":false,\"text\":\"—Como siempre, señorito.\"},{\"heading\":false,\"text\":\"—Vamos, sí, ni bueno ni malo.\"},{\"heading\":false,\"text\":\"—¡Eso!\"},{\"heading\":false,\"text\":\"Era la teoría del criado, quien también se las tenía.\"},{\"heading\":false,\"text\":\"Augusto se lavó, peinó, vistió y avió como quien tiene ya un objetivo en la vida, rebosando íntimo arregosto de vivir. Aunque melancólico.\"},{\"heading\":false,\"text\":\"Echóse a la calle, y muy pronto el corazón le tocó a rebato. «¡Calla—se dijo—, si yo la había visto, si yo la conocía hace mucho tiempo; sí, su imagen me es casi innata...! ¡Madre mía, ampárame!» Y al pasar junto a él, al cruzarse con él Eugenia, le saludó aún más con los ojos que con el sombrero.\"},{\"heading\":false,\"text\":\"Estuvo a punto de volverse para seguirla, pero venció el buen juicio y el deseo que tenía de charlar con la portera.\"},{\"heading\":false,\"text\":\"«Es ella, sí, es ella—siguió diciéndose—, es ella, es la misma, es la que yo buscaba hace años, aun sin saberlo; es la que me buscaba. Estábamos destinados uno a otro en armonía prestablecida; somos dos mónadas complementaria una de otra. La familia es la verdadera célula social. Y yo no soy más que una molécula. ¡Qué poética es la ciencia, Dios mío! ¡Madre, madre mía, aquí tienes a tu hijo; aconséjame desde el cielo! ¡Eugenia, mi Eugenia...!»\"},{\"heading\":false,\"text\":\"Miró a todas partes por si le miraban, pues se sorprendió abrazando al aire. Y se dijo: «El amor es un éxtasis; nos saca de nosotros mismos».\"},{\"heading\":false,\"text\":\"Le volvió a la realidad—¿a la realidad?—la sonrisa de Margarita.\"},{\"heading\":false,\"text\":\"—¿Y qué, no hay novedad?—le preguntó Augusto.\"},{\"heading\":false,\"text\":\"—Ninguna, señorito. Todavía es muy pronto.\"},{\"heading\":false,\"text\":\"—¿No le preguntó nada al entregársela?\"},{\"heading\":false,\"text\":\"—Nada.\"},{\"heading\":false,\"text\":\"—¿Y hoy?\"},{\"heading\":false,\"text\":\"—Hoy sí. Me preguntó por sus señas de usted, y si le conocía, y quién era. Me dijo que el señorito no se había acordado de poner la dirección de su casa. Y luego me dio un encargo...\"},{\"heading\":false,\"text\":\"—¿Un encargo? ¿Cuál? No vacile.\"},{\"heading\":false,\"text\":\"—Me dijo que si volvía por acá le dijese que estaba comprometida, que tiene novio.\"},{\"heading\":false,\"text\":\"—¿Que tiene novio?\"},{\"heading\":false,\"text\":\"—Ya se lo dije yo, señorito.\"},{\"heading\":false,\"text\":\"—No importa, ¡lucharemos!\"},{\"heading\":false,\"text\":\"—Bueno, lucharemos.\"},{\"heading\":false,\"text\":\"—¿Me promete usted su ayuda, Margarita?\"},{\"heading\":false,\"text\":\"—Claro que sí.\"},{\"heading\":false,\"text\":\"—¡Pues venceremos!\"},{\"heading\":false,\"text\":\"Y se retiró. Fuése a la Alameda a refrescar sus emociones en la visión de verdura, a oir cantar a los pájaros sus amores. Su corazón verdecía y dentro de él cantábanle también como ruiseñores recuerdos alados de la infancia.\"},{\"heading\":false,\"text\":\"Era, sobre todo, el cielo de recuerdos de su madre derramando una lumbre derretida y dulce sobre todas sus demás memorias.\"},{\"heading\":false,\"text\":\"De su padre apenas se acordaba; era una sombra mítica que se le perdía en lo más lejano; era una nube sangrienta de ocaso. Sangrienta, porque siendo aún pequeñito lo vio bañado en sangre, de un vómito, y cadavérico. Y repercutía en su corazón, a tan larga distancia, aquel ¡hijo! de su madre, que desgarró la casa; aquel ¡hijo! que no se sabía si dirigido al padre moribundo o a él, a Augusto, empedernido de incomprensión ante el misterio de la muerte.\"},{\"heading\":false,\"text\":\"Poco después su madre, temblorosa de congoja, le apechugaba a su seno, y con una letanía de ¡hijo mío! ¡hijo mío! ¡hijo mío! le bautizaba en lágrimas de fuego. Y él lloró también, apretándose a su madre, y sin atreverse a volver la cara ni a apartarla de la dulce oscuridad de aquel regazo palpitante, por miedo a encontrarse con los ojos devoradores del Coco.\"},{\"heading\":false,\"text\":\"Y así pasaron días de llanto y de negrura, hasta que las lágrimas fueron yéndose hacia dentro y la casa fué derritiendo los negrores.\"},{\"heading\":false,\"text\":\"Era una casa dulce y tibia. La luz entraba por entre las blancas flores bordadas en los visillos. Las butacas abrían, con intimidad de abuelos hechos niños por los años, sus brazos. Allí estaba siempre el cenicero con la ceniza del último puro que apuró su padre. Y allí, en la pared, el retrato de ambos, del padre y de la madre, la viuda ya, hecho el día mismo en que se casaron. Él, que era alto, sentado, con una pierna cruzada sobre la otra, enseñando la lengüeta de la bota, y ella, que era bajita, de pie a su lado y apoyando la mano, una mano fina que no parecía hecha para agarrar, sino para posarse como paloma, en el hombro de su marido.\"},{\"heading\":false,\"text\":\"Su madre iba y venía sin hacer ruido, como un pajarillo, siempre de negro, con una sonrisa, que era el poso de las lágrimas de los primeros días de viudez, siempre en la boca y en torno de los ojos escudriñadores. «Tengo que vivir para ti, para ti solo—le decía por las noches, antes de acostarse—, Augusto.» Y éste llevaba a sus sueños nocturnos un beso húmedo aún en lágrimas.\"},{\"heading\":false,\"text\":\"Como un sueño dulce se les iba la vida.\"},{\"heading\":false,\"text\":\"Por las noches le leía su madre algo, unas veces la vida del Santo, otras una novela de Julio Verne o algún cuento candoroso y sencillo. Y algunas veces hasta se reía, con una risa silenciosa y dulce que trascendía a lágrimas lejanas.\"},{\"heading\":false,\"text\":\"Luego entró al Instituto y por las noches era su madre quien le tomaba las lecciones. Y estudió para tomárselas. Estudió todos aquellos nombres raros de la historia universal, y solía decirle sonriendo: «Pero ¡cuántas barbaridades han podido hacer los hombres, Dios mío!» Estudió matemáticas, y en esto fué en lo que más sobresalió aquella dulce madre. «Si mi madre llega a dedicarse a las matemáticas...»—se decía Augusto. Y recordaba el interés con que seguía el desarrollo de una ecuación de segundo grado. Estudió psicología, y esto era lo que más se le resistía. «Pero ¡qué ganas de complicar las cosas!»—solía decir a esto. Estudió física y química e historia natural. De la historia natural lo que no le gustaba era aquellos motajos raros que se les da en ella a los animales y las plantas. La fisiología le causaba horror, y renunció a tomar sus lecciones a su hijo. Sólo con ver aquellas láminas que representaban el corazón o los pulmones al desnudo presentábasele la sanguinosa muerte de su marido. «Todo esto es muy feo, hijo mío—le decía—; no estudies médico. Lo mejor es no saber cómo se tiene las cosas de dentro.»\"},{\"heading\":false,\"text\":\"Cuando Augusto se hizo bachiller le tomó en brazos, le miró al bozo, y rompiendo en lágrimas exclamó: «¡Si viviese tu padre...!» Después le hizo sentarse sobre sus rodillas, de lo que él, un chicarrón ya, se sentía avergonzado, y así le tuvo, en silencio, mirando al cenicero de su difunto.\"},{\"heading\":false,\"text\":\"Y luego vino su carrera, sus amistades universitarias, y la melancolía de la pobre madre al ver que su hijo ensayaba las alas. «Yo para ti, yo para ti—solía decirle—, y tú, ¡quién sabe para qué otra!... Así es el mundo, hijo.» El día en que se recibió de licenciado en derecho, su madre, al llegar él a casa, le tomó y besó la mano de una manera cómicamente grave, y luego, abrazándole, díjole al oído: «¡Tu padre te bendiga, hijo mío!»\"},{\"heading\":false,\"text\":\"Su madre jamás se acostaba hasta que él lo hubiese hecho, y le dejaba con un beso en la cama. No pudo, pues, nunca trasnochar. Y era su madre lo primero que veía al despertarse. Y en la mesa, de lo que él no comía, tampoco ella.\"},{\"heading\":false,\"text\":\"Salían a menudo juntos de paseo y así iban, en silencio, bajo el cielo, pensando ella en su difunto y él pensando en lo que primero pasaba a sus ojos. Y ella le decía siempre las mismas cosas, cosas cotidianas, muy antiguas y siempre nuevas. Muchas de ellas empezaban así: «Cuando te cases...»\"},{\"heading\":false,\"text\":\"Siempre que cruzaba con ellos alguna muchacha hermosa, o siquiera linda, su madre miraba a Augusto con el rabillo del ojo.\"},{\"heading\":false,\"text\":\"Y vino la muerte, aquella muerte lenta, grave y dulce, indolorosa, que entró de puntillas y sin ruido, como un ave peregrina, y se la llevó a vuelo lento, en una tarde de otoño. Murió con su mano en la mano de su hijo, con sus ojos en los ojos de él. Sintió Augusto que la mano se enfriaba, sintió que los ojos se inmovilizaban. Soltó la mano después de haber dejado en su frialdad un beso cálido, y cerró los ojos. Se arrodilló junto al lecho y pasó sobre él la historia de aquellos años iguales.\"},{\"heading\":false,\"text\":\"Y ahora estaba aquí, en la Alameda, bajo el gorjear de los pájaros, pensando en Eugenia. Y Eugenia tenía novio. «Lo que temo, hijo mío—solía decirle su madre—, es cuando te encuentres con la primera espina en el camino de tu vida.» ¡Si estuviera aquí ella para hacer florecer en rosa a esta primera espina!\"},{\"heading\":false,\"text\":\"«Si viviera mi madre encontraría solución a esto—se dijo Augusto—, que no es, después de todo, más difícil que una ecuación de segundo grado. Y no es, en el fondo, más que una ecuación de segundo grado.»\"},{\"heading\":false,\"text\":\"Unos débiles quejidos, como de un pobre animal, interrumpieron su soliloquio. Escudriñó con los ojos y acabó por descubrir, entre la verdura de un matorral, un pobre cachorrillo de perro que parecía buscar camino en tierra. «¡Pobrecillo!—se dijo—. Lo han dejado recién nacido a que muera; les faltó valor para matarlo.» Y lo recojió.\"},{\"heading\":false,\"text\":\"El animalito buscaba el pecho de la madre. Augusto se levantó y volvióse a casa pensando: «Cuando lo sepa Eugenia, ¡mal golpe para mi rival! ¡Qué cariño le va a tomar al pobre animalito! Y es lindo, muy lindo. ¡Pobrecito, cómo me lame la mano...!»\"},{\"heading\":false,\"text\":\"—Trae leche, Domingo; pero tráela pronto—le dijo al criado no bien éste le hubo abierto la puerta.\"},{\"heading\":false,\"text\":\"—¿Pero ahora se le ocurre comprar perro, señorito?\"},{\"heading\":false,\"text\":\"—No lo he comprado, Domingo; este perro no es esclavo, sino que es libre; lo he encontrado.\"},{\"heading\":false,\"text\":\"—Vamos, sí, es expósito.\"},{\"heading\":false,\"text\":\"—Todos somos expósitos, Domingo. Trae leche.\"},{\"heading\":false,\"text\":\"Le trajo la leche y una pequeña esponja para facilitar la succión. Luego hizo Augusto que se le trajera un biberón para el cachorrillo, para Orfeo, que así le bautizó, no se sabe ni sabía él tampoco por qué.\"},{\"heading\":false,\"text\":\"Y Orfeo fué en adelante el confidente de sus soliloquios, el que recibió los secretos de su amor a Eugenia.\"},{\"heading\":false,\"text\":\"«Mira, Orfeo—le decía silenciosamente—, tenemos que luchar. ¿Qué me aconsejas que haga? Si te hubiese conocido mi madre... Pero ya verás, ya verás cuando duermas en el regazo de Eugenia, bajo su mano tibia y dulce. Y ahora, ¿qué vamos a hacer, Orfeo?»\"},{\"heading\":false,\"text\":\"Fué melancólico el almuerzo de aquel día, melancólico el paseo, la partida de ajedrez melancólica y melancólico el sueño de aquella noche.\"}]},{\"title\":\"Capítulo VI\",\"blocks\":[{\"heading\":false,\"text\":\"«Tengo que tomar alguna determinación—se decía Augusto paseándose frente a la casa número 58 de la Avenida de la Alameda—; esto no puede seguir así.»\"},{\"heading\":false,\"text\":\"En aquel momento se abrió uno de los balcones del piso segundo, en que vivía Eugenia, y apareció una señora enjuta y cana con una jaula en la mano. Iba a poner el canario al sol. Pero al ir a ponerlo faltó el clavo y la jaula se vino abajo. La señora lanzó un grito de desesperación: «¡Ay, mi Pichín!» Augusto se precipitó a recojer la jaula. El pobre canario revoloteaba dentro de ella despavorido.\"},{\"heading\":false,\"text\":\"Subió Augusto a la casa, con el canario agitándose en la jaula y el corazón en el pecho. La señora le esperaba.\"},{\"heading\":false,\"text\":\"—¡Oh, gracias, gracias, caballero!\"},{\"heading\":false,\"text\":\"—Las gracias a usted, señora.\"},{\"heading\":false,\"text\":\"—¡Pichín mío! ¡mi Pichincito! ¡Vamos, cálmate! ¿Gusta usted pasar, caballero?\"},{\"heading\":false,\"text\":\"—Con mucho gusto, señora.\"},{\"heading\":false,\"text\":\"Y entró Augusto.\"},{\"heading\":false,\"text\":\"Llevólo la señora a la sala, y diciéndole: «Aguarde un poco, que voy a dejar a mi Pichín», le dejó solo.\"},{\"heading\":false,\"text\":\"En este momento entró en la sala un caballero anciano, el tío de Eugenia sin duda. Llevaba anteojos ahumados y un fez en la cabeza. Acercóse a Augusto, y tomando asiento junto a él le dirigió estas palabras:\"},{\"heading\":false,\"text\":\"—(Aquí una frase en esperanto que quiere decir: ¿Y usted no cree conmigo que la paz universal llegará pronto merced al esperanto?)\"},{\"heading\":false,\"text\":\"Augusto pensó en la huída, pero el amor a Eugenia le contuvo. El otro prosiguió hablando, en esperanto también.\"},{\"heading\":false,\"text\":\"Augusto se decidió por fin.\"},{\"heading\":false,\"text\":\"—No le entiendo a usted una palabra, caballero.\"},{\"heading\":false,\"text\":\"—De seguro que le hablaba a usted en esa maldita jerga que llaman esperanto—dijo la tía, que a este punto entraba.—Y añadió dirigiéndose a su marido:—Fermín, este señor es el del canario.\"},{\"heading\":false,\"text\":\"—Pues no te entiendo más que tú cuando te hablo en esperanto—le contestó su marido.\"},{\"heading\":false,\"text\":\"—Este señor ha recojido a mi pobre Pichín, que cayó a la calle, y ha tenido la bondad de traérmelo. Y usted—añadió volviéndose a Augusto—¿quién es?\"},{\"heading\":false,\"text\":\"—Yo soy, señora, Augusto Pérez, hijo de la difunta viuda de Pérez Rovira, a quien usted acaso conocería.\"},{\"heading\":false,\"text\":\"—¿De doña Soledad?\"},{\"heading\":false,\"text\":\"—Exacto; de doña Soledad.\"},{\"heading\":false,\"text\":\"—Y mucho que conocí a la buena señora. Fué una viuda y una madre ejemplar. Le felicito a usted por ello.\"},{\"heading\":false,\"text\":\"—Y yo me felicito de deber al feliz accidente de la caída del canario el conocimiento de ustedes.\"},{\"heading\":false,\"text\":\"—¡Feliz! ¿Llama usted feliz a ese accidente?\"},{\"heading\":false,\"text\":\"—Para mí, sí.\"},{\"heading\":false,\"text\":\"—Gracias, caballero—dijo don Fermín, agregando:—Rigen a los hombres y a sus cosas enigmáticas leyes, que el hombre, sin embargo, puede vislumbrar. Yo, señor mío, tengo ideas particulares sobre casi todas las cosas...\"},{\"heading\":false,\"text\":\"—Cállate con tu estribillo, hombre—exclamó la tía—. ¿Y cómo es que pudo usted acudir tan pronto en socorro de mi Pichín?\"},{\"heading\":false,\"text\":\"—Seré franco con usted, señora; le abriré mi pecho. Es que rondaba la casa.\"},{\"heading\":false,\"text\":\"—¿Esta casa?\"},{\"heading\":false,\"text\":\"—Sí, señora. Tienen ustedes una sobrina encantadora.\"},{\"heading\":false,\"text\":\"—Acabáramos, caballero. Ya, ya veo el feliz accidente. Y veo que hay canarios providenciales.\"},{\"heading\":false,\"text\":\"—¿Quién conoce los caminos de la Providencia?—dijo don Fermín.\"},{\"heading\":false,\"text\":\"—Yo los conozco, hombre, yo—exclamó su señora—; y volviéndose a Augusto: Tiene usted abiertas las puertas de esta casa... Pues ¡no faltaba más! Al hijo de doña Soledad... Así como así, va usted a ayudarme a quitar a esa chiquilla un caprichito que se le ha metido en la cabeza...\"},{\"heading\":false,\"text\":\"—¿Y la libertad?—insinuó don Fermín.\"},{\"heading\":false,\"text\":\"—Cállate tú, hombre, y quédate con tu anarquismo.\"},{\"heading\":false,\"text\":\"—¿Anarquismo?—exclamó Augusto.\"},{\"heading\":false,\"text\":\"Irradió de gozo el rostro de don Fermín, y añadió con la más dulce de sus voces:\"},{\"heading\":false,\"text\":\"—Sí, señor mío, yo soy anarquista, anarquista místico, pero en teoría, entiéndase bien, en teoría. No tema usted, amigo—y al decir esto le puso amablemente la mano sobre la rodilla—, no echo bombas. Mi anarquismo es puramente espiritual. Porque yo, amigo mío, tengo ideas propias sobre casi todas las cosas...\"},{\"heading\":false,\"text\":\"—Y usted ¿no es anarquista también?—preguntó Augusto a la tía, por decir algo.\"},{\"heading\":false,\"text\":\"—¿Yo? Eso es un disparate, eso de que no mande nadie. Si no manda nadie, ¿quién va a obedecer? ¿No comprende usted que eso es imposible?\"},{\"heading\":false,\"text\":\"—Hombres de poca fe, que llamáis imposible...—empezó don Fermín.\"},{\"heading\":false,\"text\":\"Y la tía interrumpiéndole:\"},{\"heading\":false,\"text\":\"—Pues bien, mi señor don Augusto, pacto cerrado. Usted me parece un excelente sujeto, bien educado, de buena familia, con una renta más que regular... Nada, nada, desde hoy es usted mi candidato.\"},{\"heading\":false,\"text\":\"—Tanto honor, señora...\"},{\"heading\":false,\"text\":\"—Sí; hay que hacer entrar en razón a esta mozuela. Ella no es mala, sabe usted, pero caprichosa. Luego, ¡fué criada con tanto mimo!... Cuando sobrevino aquella terrible catástrofe de mi pobre hermano...\"},{\"heading\":false,\"text\":\"—¿Catástrofe?—preguntó Augusto.\"},{\"heading\":false,\"text\":\"—Sí, y como la cosa es pública no debo yo ocultársela a usted. El padre de Eugenia se suicidó después de una operación bursátil desgraciadísima y dejándola casi en la miseria. Le quedó una casa, pero gravada con una hipoteca que se lleva sus rentas todas. Y la pobre chica se ha empeñado en ir ahorrando de su trabajo hasta reunir con que levantar la hipoteca. Figúrese usted, ¡ni aunque se esté dando lecciones de piano sesenta años!\"},{\"heading\":false,\"text\":\"Augusto concibió al punto un propósito generoso y heroico.\"},{\"heading\":false,\"text\":\"—La chica no es mala—prosiguió la tía—, pero no hay modo de entenderla.\"},{\"heading\":false,\"text\":\"—Si aprendierais esperanto...—empezó don Fermín.\"},{\"heading\":false,\"text\":\"—Déjanos de lenguas universales. ¿Conque no nos entendemos en las nuestras y vas a traer otra?\"},{\"heading\":false,\"text\":\"—Pero ¿usted no cree, señora—le preguntó Augusto—, que sería bueno que no hubiese sino una sola lengua?\"},{\"heading\":false,\"text\":\"—¡Eso, eso!—exclamó alborozado don Fermín.\"},{\"heading\":false,\"text\":\"—Sí, señor—dijo con firmeza la tía—; una sola lengua: el castellano, y a lo sumo el bable para hablar con las criadas que no son racionales.\"},{\"heading\":false,\"text\":\"La tía de Eugenia era asturiana y tenía una criada, asturiana también, a la que reñía en bable.\"},{\"heading\":false,\"text\":\"—Ahora, si es en teoría—añadió—, no me parece mal que haya una sola lengua. Porque este mi marido, en teoría, es hasta enemigo del matrimonio...\"},{\"heading\":false,\"text\":\"—Señores—dijo Augusto levantándose—, estoy acaso molestando...\"},{\"heading\":false,\"text\":\"—Usted no molesta nunca, caballero—le respondió la tía—, y queda comprometido a volver por esta casa. Ya lo sabe usted, es usted mi candidato.\"},{\"heading\":false,\"text\":\"Al salir se le acercó un momento don Fermín y le dijo al oído: «¡No piense usted en eso!» «¿Y por qué no?»—le preguntó Augusto. «Hay presentimientos, caballero, hay presentimientos...»\"},{\"heading\":false,\"text\":\"Al despedirse, las últimas palabras de la tía fueron: «Ya lo sabe, es mi candidato».\"},{\"heading\":false,\"text\":\"Cuando Eugenia volvió a casa, las primeras palabras de su tía al verla fueron:\"},{\"heading\":false,\"text\":\"—¿Sabes, Eugenia, quién ha estado aquí? Don Augusto Pérez.\"},{\"heading\":false,\"text\":\"—Augusto Pérez... Augusto Pérez... ¡Ah, sí! Y ¿quién le ha traído?\"},{\"heading\":false,\"text\":\"—Pichín, mi canario.\"},{\"heading\":false,\"text\":\"—Y ¿a qué ha venido?\"},{\"heading\":false,\"text\":\"—¡Vaya una pregunta! Tras de ti.\"},{\"heading\":false,\"text\":\"—¿Tras de mí y traído por el canario? Pues no lo entiendo. Valiera más que hablases en esperanto, como tío Fermín.\"},{\"heading\":false,\"text\":\"—Él viene tras de ti y es un mozo joven, no feo, apuesto, bien educado, fino, y sobre todo rico, chica, sobre todo rico.\"},{\"heading\":false,\"text\":\"—Pues que se quede con su riqueza, que si yo trabajo no es para venderme.\"},{\"heading\":false,\"text\":\"—Y ¿quién te ha hablado de venderte, polvorilla?\"},{\"heading\":false,\"text\":\"—Bueno, bueno, tía, dejémonos de bromas.\"},{\"heading\":false,\"text\":\"—Tú le verás, chiquilla, tú le verás e irás cambiando de ideas.\"},{\"heading\":false,\"text\":\"—Lo que es eso...\"},{\"heading\":false,\"text\":\"—Nadie puede decir de esta agua no beberé.\"},{\"heading\":false,\"text\":\"—¡Son misteriosos los caminos de la Providencia!—exclamó don Fermín—. Dios...\"},{\"heading\":false,\"text\":\"—Pero, hombre—le arguyó su mujer—, ¿cómo se compadece eso de Dios con el anarquismo? Ya te lo he dicho mil veces. Si no debe mandar nadie, ¿qué es eso de Dios?\"},{\"heading\":false,\"text\":\"—Mi anarquismo, mujer, me lo has oído otras mil veces, es místico, es un anarquismo místico. Dios no manda como mandan los hombres. Dios es también anarquista, Dios no manda, sino...\"},{\"heading\":false,\"text\":\"—Obedece, ¿no es eso?\"},{\"heading\":false,\"text\":\"—Tú lo has dicho, mujer, tú lo has dicho. Dios mismo te ha iluminado. ¡Ven acá!\"},{\"heading\":false,\"text\":\"Cojió a su mujer, le miró en la frente, soplóle en ella, sobre unos rizos de blancos cabellos, y añadió:\"},{\"heading\":false,\"text\":\"—Te inspiró Él mismo. Sí, Dios obedece... obedece...\"},{\"heading\":false,\"text\":\"—Sí, en teoría, ¿no es eso? Y tú, Eugenita, déjate de bobadas, que se te presenta un gran partido.\"},{\"heading\":false,\"text\":\"—También yo soy anarquista, tía, pero no como tío Fermín, no mística.\"},{\"heading\":false,\"text\":\"—¡Bueno, se verá!—terminó la tía.\"}]},{\"title\":\"Capítulo VII\",\"blocks\":[{\"heading\":false,\"text\":\"«¡Ay, Orfeo!—decía ya en su casa Augusto, dándole la leche a aquél—. ¡Ay, Orfeo! Di el gran paso, el paso decisivo; entré en su hogar, entré en el santuario. ¿Sabes lo que es dar un paso decisivo? Los vientos de la fortuna nos empujan y nuestros pasos son decisivos todos. ¿Nuestros? ¿Son nuestros esos pasos? Caminamos, Orfeo mío, por una selva enmarañada y bravía, sin senderos. El sendero nos lo hacemos con los pies según caminamos a la ventura. Hay quien cree seguir una estrella; yo creo seguir una doble estrella, melliza. Y esa estrella no es sino la proyección misma del sendero al cielo, la proyección del azar.\"},{\"heading\":false,\"text\":\"»¡Un paso decisivo! Y dime, Orfeo, ¿qué necesidad hay de que haya ni Dios ni mundo ni nada? ¿Por qué ha de haber algo? ¿No te parece que esa idea de la necesidad no es sino la forma suprema que el azar toma en nuestra mente?\"},{\"heading\":false,\"text\":\"»¿De dónde ha brotado Eugenia? ¿Es ella una creación mía o soy creación suya yo? ¿o somos los dos creaciones mutuas, ella de mí y yo de ella? ¿No es acaso todo creación de cada cosa y cada cosa creación de todo? Y ¿qué es creación? ¿qué eres tú, Orfeo? ¿qué soy yo?\"},{\"heading\":false,\"text\":\"»Muchas veces se me ha ocurrido pensar, Orfeo, que yo no soy, e iba por la calle antojándoseme que los demás no me veían. Y otras veces he fantaseado que no me veían como me veía yo, y que mientras yo me creía ir formalmente, con toda compostura, estaba, sin saberlo, haciendo el payaso, y los demás riéndose y burlándose de mí. ¿No te ha ocurrido alguna vez a ti esto, Orfeo? Aunque no, porque tú eres joven todavía y no tienes experiencia de la vida. Y además eres perro.\"},{\"heading\":false,\"text\":\"»Pero, dime, Orfeo, ¿no se os ocurrirá alguna vez a los perros creeros hombres, así como ha habido hombres que se han creído perros?\"},{\"heading\":false,\"text\":\"»¡Qué vida ésta, Orfeo, qué vida, sobre todo desde que murió mi madre! Cada hora me llega empujada por las horas que le precedieron; no he conocido el porvenir. Y ahora que empiezo a vislumbrarlo me parece se me va a convertir en pasado. Eugenia es ya casi un recuerdo para mí. Estos días que pasan... este día, este eterno día que pasa... deslizándose en niebla de aburrimiento. Hoy como ayer, mañana como hoy. Mira, Orfeo, mira la ceniza que dejó mi padre en aquel cenicero...\"},{\"heading\":false,\"text\":\"»Esta es la revelación de la eternidad, Orfeo, de la terrible eternidad. Cuando el hombre se queda a solas y cierra los ojos al porvenir, al ensueño, se le revela el abismo pavoroso de la eternidad. La eternidad no es porvenir. Cuando morimos nos da la muerte media vuelta en nuestra órbita y emprendemos la marcha hacia atrás, hacia el pasado, hacia lo que fué. Y así, sin término, devanando la madeja de nuestro destino, deshaciendo todo el infinito que en una eternidad nos ha hecho, caminando a la nada, sin llegar nunca a ella, pues que ella nunca fué.\"},{\"heading\":false,\"text\":\"»Por debajo de esta corriente de nuestra existencia, por dentro de ella, hay otra corriente en sentido contrario; aquí vamos del ayer al mañana, allí se va del mañana al ayer. Se teje y se desteje a un tiempo. Y de vez en cuando nos llegan hálitos, vahos y hasta rumores misteriosos de ese otro mundo, de ese interior de nuestro mundo. Las entrañas de la historia son una contrahistoria, es un proceso inverso al que ella sigue. El río subterráneo va del mar a la fuente.\"},{\"heading\":false,\"text\":\"»Y ahora me brillan en el cielo de mi soledad los dos ojos de Eugenia. Me brillan con el resplandor de las lágrimas de mi madre. Y me hacen creer que existo, ¡dulce ilusión! _Amo, ergo sum!_ Este amor, Orfeo, es como lluvia bienhechora en que se deshace y concreta la niebla de la existencia. Gracias al amor siento al alma de bulto, la toco. Empieza a dolerme en su cogollo mismo el alma, gracias al amor, Orfeo. Y el alma misma ¿qué es sino amor, sino dolor encarnado?\"},{\"heading\":false,\"text\":\"»Vienen los días y van los días y el amor queda. Allá dentro, muy dentro, en las entrañas de las cosas se rozan y friegan la corriente de este mundo con la contraria corriente del otro, y de este roce y friega viene el más triste y el más dulce de los dolores: el de vivir.\"},{\"heading\":false,\"text\":\"»Mira, Orfeo, las lizas, mira la urdimbre, mira cómo la trama va y viene con la lanzadera, mira cómo juegan las primideras; pero, dime, ¿dónde está el enjullo a que se arrolla la tela de nuestra existencia, dónde?»\"},{\"heading\":false,\"text\":\"Como Orfeo no había visto nunca un telar, es muy difícil que entendiera a su amo. Pero mirándole a los ojos mientras hablaba adivinaba su sentir.\"}]},{\"title\":\"Capítulo VIII\",\"blocks\":[{\"heading\":false,\"text\":\"Augusto temblaba y sentíase como en un potro de suplicio en su asiento; entrábanle furiosas ganas de levantarse de él, pasearse por la sala aquella, dar manotadas al aire, gritar, hacer locuras de circo, olvidarse de que existía. Ni doña Ermelinda, la tía de Eugenia, ni don Fermín, su marido, el anarquista teórico y místico, lograban traerle a la realidad.\"},{\"heading\":false,\"text\":\"—Pues sí, yo creo—decía doña Ermelinda—, don Augusto, que esto es lo mejor, que usted se espere, pues ella no puede ya tardar en venir; la llamo, ustedes se ven y se conocen y éste es el primer paso. Todas las relaciones de este género tienen que empezar por conocerse, ¿no es así?\"},{\"heading\":false,\"text\":\"—En efecto, señora—dijo como quien habla desde otro mundo Augusto—, el primer paso es verse y conocerse...\"},{\"heading\":false,\"text\":\"—Y yo creo que así que ella le conozca a usted, pues... ¡la cosa es clara!\"},{\"heading\":false,\"text\":\"—No tan clara—arguyó don Fermín—. Los caminos de la Providencia son misteriosos siempre... Y en cuanto a eso de que para casarse sea preciso o siquiera conveniente conocerse antes, discrepo... discrepo... El único conocimiento eficaz es el conocimiento _post nuptias_. Ya me has oído, esposa mía, lo que en lenguaje bíblico significa conocer. Y, créemelo, no hay más conocimiento sustancial y esencial que ése, el conocimiento penetrante...\"},{\"heading\":false,\"text\":\"—Cállate, hombre, cállate, no desbarres.\"},{\"heading\":false,\"text\":\"—El conocimiento, Ermelinda,...\"},{\"heading\":false,\"text\":\"Sonó el timbre de la puerta.\"},{\"heading\":false,\"text\":\"—¡Ella!—exclamó con misteriosa voz el tío.\"},{\"heading\":false,\"text\":\"Augusto sintió una oleada de fuego subirle del suelo hasta perderse, pasando por su cabeza, en lo alto, encima de él. Y empezó el corazón a martillarle el pecho.\"},{\"heading\":false,\"text\":\"Se oyó abrir la puerta, y ruido de unos pasos rápidos e iguales, rítmicos. Y Augusto, sin saber cómo, sintió que la calma volvía a reinar en él.\"},{\"heading\":false,\"text\":\"—Voy a llamarla—dijo don Fermín haciendo conato de levantarse.\"},{\"heading\":false,\"text\":\"—¡No, de ningún modo!—exclamó doña Ermelinda, y llamó.\"},{\"heading\":false,\"text\":\"Y luego a la criada al presentarse:—¡Di a la señorita Eugenia que venga!\"},{\"heading\":false,\"text\":\"Se siguió un silencio. Los tres, como en complicidad, callaban. Y Augusto se decía: «¿Podré resistirlo? ¿no me pondré rojo como una amapola o blanco cual un lirio cuando sus ojos llenen el hueco de esa puerta? ¿no estallará mi corazón?»\"},{\"heading\":false,\"text\":\"Oyóse un lijero rumor, como de paloma que arranca en vuelo, un ¡ah! breve y seco, y los ojos de Eugenia, en un rostro todo frescor de vida y sobre un cuerpo que no parecía pesar sobre el suelo, dieron como una nueva y misteriosa luz espiritual a la escena. Y Augusto se sintió tranquilo, enormemente tranquilo, clavado a su asiento y como si fuese una planta nacida en él, como algo vegetal, olvidado de sí, absorto en la misteriosa luz espiritual que de aquellos ojos irradiaba. Y sólo al oir que doña Ermelinda empezaba a decir a su sobrina: «Aquí tienes a nuestro amigo don Augusto Pérez...», volvió en sí y se puso en pie procurando sonreír.\"},{\"heading\":false,\"text\":\"—Aquí tienes a nuestro amigo don Augusto Pérez, que desea conocerte...\"},{\"heading\":false,\"text\":\"—¿El del canario?—preguntó Eugenia.\"},{\"heading\":false,\"text\":\"—Sí, el del canario, señorita—contestó Augusto acercándose a ella y alargándole la mano. Y pensó: «¡Me va a quemar con la suya!»\"},{\"heading\":false,\"text\":\"Pero no fué así. Una mano blanca y fría, blanca como la nieve y como la nieve fría, tocó su mano. Y sintió Augusto que se derramaba por su ser todo como un fluido de serenidad.\"},{\"heading\":false,\"text\":\"Sentóse Eugenia.\"},{\"heading\":false,\"text\":\"—Y este caballero...—empezó la pianista.\"},{\"heading\":false,\"text\":\"«¡Este caballero... este caballero...—pensó Augusto rapidísimamente—este caballero! ¡Llamarme caballero! ¡Esto es de mal agüero!»\"},{\"heading\":false,\"text\":\"—Este caballero, hija mía, que ha hecho por una feliz casualidad...\"},{\"heading\":false,\"text\":\"—Sí, la del canario.\"},{\"heading\":false,\"text\":\"—¡Son misteriosos los caminos de la Providencia!—sentenció el anarquista.\"},{\"heading\":false,\"text\":\"—Este caballero, digo—agregó la tía—, que por una feliz casualidad ha hecho conocimiento con nosotros y resulta ser el hijo de una señora a quien conocí algo y respeté mucho; este caballero, puesto que es amigo ya de casa, ha deseado conocerte, Eugenia.\"},{\"heading\":false,\"text\":\"—¡Y admirarla!—añadió Augusto.\"},{\"heading\":false,\"text\":\"—¿Admirarme?—exclamó Eugenia.\"},{\"heading\":false,\"text\":\"—¡Sí, como pianista!\"},{\"heading\":false,\"text\":\"—¡Ah, vamos!\"},{\"heading\":false,\"text\":\"—Conozco, señorita, su gran amor al arte...\"},{\"heading\":false,\"text\":\"—¿Al arte? ¿A cuál, al de la música?\"},{\"heading\":false,\"text\":\"—¡Claro está!\"},{\"heading\":false,\"text\":\"—¡Pues le han engañado a usted, don Augusto!\"},{\"heading\":false,\"text\":\"«¡Don Augusto! ¡Don Augusto!—pensó éste—. ¡Don...! ¡De qué mal agüero es este don! ¡casi tan malo como aquel caballero!» Y luego, en voz alta:\"},{\"heading\":false,\"text\":\"—¿Es que no le gusta la música?\"},{\"heading\":false,\"text\":\"—Ni pizca, se lo aseguro.\"},{\"heading\":false,\"text\":\"«Liduvina tiene razón—pensó Augusto—; ésta después que se case, y si el marido la puede mantener, no vuelve a teclear un piano.» Y luego, en voz alta:\"},{\"heading\":false,\"text\":\"—Como es voz pública que es usted una excelente profesora...\"},{\"heading\":false,\"text\":\"—Procuro cumplir lo mejor posible con mi deber profesional, y ya que tengo que ganarme la vida...\"},{\"heading\":false,\"text\":\"—Eso de tener que ganarte la vida...—empezó a decir don Fermín.\"},{\"heading\":false,\"text\":\"—Bueno, basta—interrumpió la tía—; ya el señor don Augusto está informado de todo...\"},{\"heading\":false,\"text\":\"—¿De todo? ¿De qué?—preguntó con aspereza y con un lijerísimo ademán de ir a levantarse Eugenia.\"},{\"heading\":false,\"text\":\"—Sí, de lo de la hipoteca...\"},{\"heading\":false,\"text\":\"—¿Cómo?—exclamó la sobrina poniéndose en pie—. Pero ¿qué es esto, qué significa todo esto, a qué viene esta visita?\"},{\"heading\":false,\"text\":\"—Ya te he dicho, sobrina, que este señor deseaba conocerte... Y no te alteres así...\"},{\"heading\":false,\"text\":\"—Pero es que hay cosas...\"},{\"heading\":false,\"text\":\"—Dispense a su señora tía, señorita—suplicó también Augusto poniéndose a su vez en pie, y lo mismo hicieron los tíos—; pero no ha sido otra cosa... Y en cuanto a eso de la hipoteca y a su abnegación de usted y amor al trabajo, yo nada he hecho para arrancar de su señora tía tan interesantes noticias; yo...\"},{\"heading\":false,\"text\":\"—Sí, usted se ha limitado a traer el canario unos días después de haberme dirigido una carta...\"},{\"heading\":false,\"text\":\"—En efecto, no lo niego.\"},{\"heading\":false,\"text\":\"—Pues bien, caballero, la contestación a esa carta se la daré cuando mejor me plazca y sin que nadie me cohiba a ello. Y ahora vale más que me retire.\"},{\"heading\":false,\"text\":\"—¡Bien, muy bien!—exclamó don Fermín—. ¡Esto es entereza y libertad! ¡Esta es la mujer del porvenir! ¡Mujeres así hay que ganarlas a puño, amigo Pérez, a puño!\"},{\"heading\":false,\"text\":\"—¡Señorita...!—suplicó Augusto acercándose a ella.\"},{\"heading\":false,\"text\":\"—Tiene usted razón—dijo Eugenia, y le dio para despedida la mano, tan blanca y tan fría como antes y como la nieve.\"},{\"heading\":false,\"text\":\"Al dar la espalda para salir y desaparecer así los ojos aquéllos, fuentes de misteriosa luz espiritual, sintió Augusto que la ola de fuego le recorría el cuerpo, el corazón le martillaba el pecho y parecía querer estallarle la cabeza.\"},{\"heading\":false,\"text\":\"—¿Se siente usted malo?—le preguntó don Fermín.\"},{\"heading\":false,\"text\":\"—¡Qué chiquilla, Dios mío, qué chiquilla!—exclamaba doña Ermelinda.\"},{\"heading\":false,\"text\":\"—¡Admirable! ¡majestuosa! ¡heroica! ¡una mujer! ¡toda una mujer!—decía Augusto.\"},{\"heading\":false,\"text\":\"—Así creo yo—añadió el tío.\"},{\"heading\":false,\"text\":\"—Perdone, señor don Augusto—repetíale la tía—, perdone; esta chiquilla es un pequeño erizo; ¡quién lo había de pensar!...\"},{\"heading\":false,\"text\":\"—Pero ¡si estoy encantado, señora, encantado! ¡Si esta recia independencia de carácter, a mí, que no le tengo, es lo que más me entusiasma!; ¡si es ésta, ésta, ésta y no otra la mujer que yo necesito!\"},{\"heading\":false,\"text\":\"—¡Sí, señor Pérez, sí—declamó el anarquista—; ésta es la mujer del porvenir!\"},{\"heading\":false,\"text\":\"—¿Y yo?—arguyó doña Ermelinda.\"},{\"heading\":false,\"text\":\"—¡Tú, la del pasado! ¡Esta es, digo, la mujer del porvenir! ¡Claro, no en balde me ha estado oyendo disertar un día y otro sobre la sociedad futura y la mujer del porvenir; no en balde la he inculcado las emancipadoras doctrinas del anarquismo... sin bombas!\"},{\"heading\":false,\"text\":\"—¡Pues yo creo—dijo de mal humor la tía—que esta chicuela es capaz hasta de tirar bombas!\"},{\"heading\":false,\"text\":\"—Y aunque así fuera...—insinuó Augusto.\"},{\"heading\":false,\"text\":\"—¡Eso no! ¡eso no!—el tío.\"},{\"heading\":false,\"text\":\"—Y ¿qué más da?\"},{\"heading\":false,\"text\":\"—¡Don Augusto! ¡Don Augusto!\"},{\"heading\":false,\"text\":\"—Yo creo—añadió la tía—que no por esto que acaba de pasar debe usted ceder en sus pretensiones...\"},{\"heading\":false,\"text\":\"—¡Claro que no! Así tiene más mérito.\"},{\"heading\":false,\"text\":\"—¡A la conquista, pues! Y ya sabe usted que nos tiene de su parte y que puede venir a esta su casa cuantas veces guste, y quiéralo o no Eugenia.\"},{\"heading\":false,\"text\":\"—Pero, mujer, ¡si ella no ha manifestado que le disgusten las venidas acá de don Augusto!... ¡Hay que ganarla a puño, amigo, a puño! Ya irá usted conociéndola y verá de qué temple es. Esto es todo una mujer, don Augusto, y hay que ganarla a puño, a puño. ¿No quería usted conocerla?\"},{\"heading\":false,\"text\":\"—Sí, pero...\"},{\"heading\":false,\"text\":\"—Entendido, entendido. ¡A la lucha, pues, amigo mío!\"},{\"heading\":false,\"text\":\"—Cierto, cierto, y ahora ¡adiós!\"},{\"heading\":false,\"text\":\"Don Fermín llamó luego aparte a Augusto, para decirle:\"},{\"heading\":false,\"text\":\"—Se me había olvidado decirle que cuando escriba a Eugenia lo haga escribiendo su nombre con jota y no con ge, Eujenia, y del Arco con ka: Eujenia Domingo del Arko.\"},{\"heading\":false,\"text\":\"—Y ¿por qué?\"},{\"heading\":false,\"text\":\"—Porque hasta que no llegue el día feliz en que el esperanto sea la única lengua, ¡una sola para toda la humanidad!, hay que escribir el castellano con ortografía fonética. ¡Nada de ces! ¡guerra a la ce! Za, ze, zi, zo, zu con zeda, y ka, ke, ki, ko, ku con ka. ¡Y fuera las haches! ¡La hache es el absurdo, la reacción, la autoridad, la edad media, el retroceso! ¡Guerra a la hache!\"},{\"heading\":false,\"text\":\"—¿De modo que es usted foneticista también?\"},{\"heading\":false,\"text\":\"—¿También? ¿por qué también?\"},{\"heading\":false,\"text\":\"—Por lo de anarquista y esperantista...\"},{\"heading\":false,\"text\":\"—Todo es uno, señor, todo es uno. Anarquismo, esperantismo, espiritismo, vegetarianismo, foneticismo... ¡todo es uno! ¡Guerra a la autoridad! ¡guerra a la división de lenguas! ¡guerra a la vil materia y a la muerte! ¡guerra a la carne! ¡guerra a la hache! ¡Adiós!\"},{\"heading\":false,\"text\":\"Despidiéronse y Augusto salió a la calle como alijerado de un gran peso y hasta gozoso. Nunca hubiera presupuesto lo que le pasaba por dentro del espíritu. Aquella manera de habérsele presentado Eugenia la primera vez que se vieron de quieto y de cerca y que se hablaron, lejos de dolerle, encendíale más y le animaba. El mundo le parecía más grande, el aire más puro y más azul el cielo. Era como si respirase por vez primera. En lo más íntimo de sus oídos cantaba aquella palabra de su madre: ¡cásate! Casi todas las mujeres con que cruzaba por la calle parecíanle guapas, muchas hermosísimas y ninguna fea. Diríase que para él empezaba a estar el mundo iluminado por una nueva luz misteriosa desde dos grandes estrellas invisibles que refulgían más allá del azul del cielo, detrás de su aparente bóveda. Empezaba a conocer el mundo. Y sin saber cómo se puso a pensar en la profunda fuente de la confusión vulgar entre el pecado de la carne y la caída de nuestros primeros padres por haber probado del fruto del árbol de la ciencia del bien y del mal.\"},{\"heading\":false,\"text\":\"Y meditó en la doctrina de don Fermín sobre el origen del conocimiento.\"},{\"heading\":false,\"text\":\"Llegó a casa, y al salir Orfeo a recibirle lo cojió en sus brazos, le acarició y le dijo: «Hoy empezamos una nueva vida, Orfeo. ¿No sientes que el mundo es más grande, más puro el aire y más azul el cielo? ¡Ah, cuando la veas, Orfeo, cuando la conozcas...! ¡Entonces sentirás la congoja de no ser más que perro como yo siento la de no ser más que hombre! Y dime, Orfeo, ¿cómo podéis conocer si no pecáis, si vuestro conocimiento no es pecado? El conocimiento que no es pecado no es tal conocimiento, no es racional».\"},{\"heading\":false,\"text\":\"Al servirle la comida su fiel Liduvina se le quedó mirando.\"},{\"heading\":false,\"text\":\"—¿Qué miras?—preguntó Augusto.\"},{\"heading\":false,\"text\":\"—Me parece que hay mudanza.\"},{\"heading\":false,\"text\":\"—¿De dónde sacas eso?\"},{\"heading\":false,\"text\":\"—El señorito tiene otra cara.\"},{\"heading\":false,\"text\":\"—¿Lo crees?\"},{\"heading\":false,\"text\":\"—Naturalmente. ¿Y qué, se arregla lo de la pianista?\"},{\"heading\":false,\"text\":\"—¡Liduvina! ¡Liduvina!\"},{\"heading\":false,\"text\":\"—Tiene usted razón, señorito; pero ¡me interesa tanto su felicidad!\"},{\"heading\":false,\"text\":\"—¿Quién sabe qué es eso?...\"},{\"heading\":false,\"text\":\"—Es verdad.\"},{\"heading\":false,\"text\":\"Y los dos miraron al suelo, como si el secreto de la felicidad estuviese debajo de él.\"}]},{\"title\":\"Capítulo IX\",\"blocks\":[{\"heading\":false,\"text\":\"Al día siguiente de esto hablaba Eugenia en el reducido cuchitril de una portería con un joven, mientras la portera había salido discretamente a tomar el fresco a la puerta de la casa.\"},{\"heading\":false,\"text\":\"—Es menester que esto se acabe, Mauricio—decía Eugenia—; así no podemos seguir, y menos después de lo que te digo pasó ayer.\"},{\"heading\":false,\"text\":\"—Pero ¿no dices—dijo el llamado Mauricio—que ese pretendiente es un pobre panoli que vive en Babia?\"},{\"heading\":false,\"text\":\"—Sí, pero tiene dinero y mi tía no me va a dejar en paz. Y, la verdad, no me gusta hacer feos a nadie, y tampoco quiero que me estén dando la jaqueca.\"},{\"heading\":false,\"text\":\"—¡Despáchale!\"},{\"heading\":false,\"text\":\"—¿De dónde? ¿de casa de mis tíos? ¿Y si ellos no quieren?\"},{\"heading\":false,\"text\":\"—No le hagas caso.\"},{\"heading\":false,\"text\":\"—Ni le hago ni pienso hacerle, pero se me antoja que el pobrete va a dar en la flor de venir de visita a hora que esté yo. No es cosa, como comprendes, de que me encierre en mi cuarto y me niegue a que me vea, y sin solicitarme va a dedicarse a mártir silencioso.\"},{\"heading\":false,\"text\":\"—Déjale que se dedique.\"},{\"heading\":false,\"text\":\"—No, no puedo resistir a los mendigos de ninguna clase, y menos a esos que piden limosna con los ojos. ¡Y si vieras qué miradas me echa!\"},{\"heading\":false,\"text\":\"—¿Te conmueve?\"},{\"heading\":false,\"text\":\"—Me encocora. Y, la verdad, ¿por qué no he de decírtelo?, sí, me conmueve.\"},{\"heading\":false,\"text\":\"—¿Y temes?\"},{\"heading\":false,\"text\":\"—¡Hombre, no seas majadero! No temo nada. Para mí no hay más que tú.\"},{\"heading\":false,\"text\":\"—¡Ya lo sabía!—dijo lleno de convicción Mauricio, y poniendo una mano sobre una rodilla de Eugenia la dejó allí.\"},{\"heading\":false,\"text\":\"—Es preciso que te decidas, Mauricio.\"},{\"heading\":false,\"text\":\"—Pero ¿a qué, rica mía, a qué?\"},{\"heading\":false,\"text\":\"—¿A qué ha de ser, hombre, a qué ha de ser? ¡A que nos casemos de una vez!\"},{\"heading\":false,\"text\":\"—Y ¿de qué vamos a vivir?\"},{\"heading\":false,\"text\":\"—De mi trabajo hasta que tú lo encuentres.\"},{\"heading\":false,\"text\":\"—¿De tu trabajo?\"},{\"heading\":false,\"text\":\"—¡Sí, de la odiosa música!\"},{\"heading\":false,\"text\":\"—¿De su trabajo? ¡Eso sí que no!; ¡nunca! ¡nunca! ¡nunca!; ¡todo menos vivir yo de tu trabajo! Lo buscaré, seguiré buscándolo, y en tanto, esperaremos...\"},{\"heading\":false,\"text\":\"—Esperaremos... esperaremos... ¡y así se nos irán los años!—exclamó Eugenia taconeando en el suelo con el pie sobre que estaba la rodilla en que Mauricio dejó descansar su mano.\"},{\"heading\":false,\"text\":\"Y él, al sentir así sacudida su mano, la separó de donde la posaba, pero fué para echar el brazo sobre el cuello de ella y hacer juguetear entre sus dedos uno de los pendientes de su novia. Eugenia le dejaba hacer.\"},{\"heading\":false,\"text\":\"—Mira, Eugenia, para divertirte le puedes poner, si quieres, buena cara a ese panoli.\"},{\"heading\":false,\"text\":\"—¡Mauricio!\"},{\"heading\":false,\"text\":\"—¡Tienes razón, no te enfades, rica mía!—y contrayendo el brazo atrajo a su cabeza la de Eugenia, buscó con sus labios los de ella y los juntó, cerrando los ojos, en un beso húmedo, silencioso y largo.\"},{\"heading\":false,\"text\":\"—¡Mauricio!\"},{\"heading\":false,\"text\":\"Y luego le besó en los ojos.\"},{\"heading\":false,\"text\":\"—¡Esto no puede seguir así, Mauricio!\"},{\"heading\":false,\"text\":\"—¿Cómo? Pero ¿hay mejor que esto? ¿crees que lo pasaremos nunca mejor?\"},{\"heading\":false,\"text\":\"—Te digo, Mauricio, que esto no puede seguir así. Tienes que buscar trabajo. Odio la música.\"},{\"heading\":false,\"text\":\"Sentía la pobre oscuramente, sin darse de ello clara cuenta, que la música es preparación eterna, preparación a un advenimiento que nunca llega, eterna iniciación que no acaba cosa. Estaba harta de música.\"},{\"heading\":false,\"text\":\"—Buscaré trabajo, Eugenia, lo buscaré.\"},{\"heading\":false,\"text\":\"—Siempre dices lo mismo y siempre estamos lo mismo.\"},{\"heading\":false,\"text\":\"—Es que crees...\"},{\"heading\":false,\"text\":\"—Es que sé que en el fondo no eres más que un haragán y que va a ser preciso que sea yo la que busque trabajo para ti. Claro, ¡como a los hombres os cuesta menos esperar...!\"},{\"heading\":false,\"text\":\"—Eso creerás tú...\"},{\"heading\":false,\"text\":\"—Sí, sí, sé bien lo que me digo. Y ahora, te lo repito, no quiero ver los ojos suplicantes del señorito don Augusto como los de un perro hambriento...\"},{\"heading\":false,\"text\":\"—¡Qué cosas se te ocurren, chiquilla!\"},{\"heading\":false,\"text\":\"—Y ahora—añadió levantándose y apartándole con la mano suya—, quietecito y a tomar el fresco, ¡que buena falta te hace!\"},{\"heading\":false,\"text\":\"—¡Eugenia! ¡Eugenia!—le suspiró con voz seca, casi febril, al oído—, si tú quisieras...\"},{\"heading\":false,\"text\":\"—El que tiene que aprender a querer eres tú, Mauricio. Conque... ¡a ser hombre! Busca trabajo, decídete pronto; si no, trabajaré yo; pero decídete pronto. En otro caso...\"},{\"heading\":false,\"text\":\"—En otro caso, ¿qué?\"},{\"heading\":false,\"text\":\"—¡Nada! ¡Hay que acabar con esto!\"},{\"heading\":false,\"text\":\"Y sin dejarle replicar se salió del cuchitril de la portería. Al cruzar con la portera le dijo:\"},{\"heading\":false,\"text\":\"—Ahí queda su sobrino, señora Marta, y dígale que se resuelva de una vez.\"},{\"heading\":false,\"text\":\"Y salió Eugenia con la cabeza alta a la calle, donde en aquel momento un organillo de manubrio encentaba una rabiosa polca. «¡Horror! ¡horror! ¡horror!», se dijo la muchacha, y más que se fué huyó calle abajo.\"}]},{\"title\":\"Capítulo X\",\"blocks\":[{\"heading\":false,\"text\":\"Como Augusto necesitaba confidencia se dirigió al Casino, a ver a Víctor, su amigote, al día siguiente de aquella su visita a casa de Eugenia y a la misma hora en que ésta espoleaba la pachorra amorosa de su novio en la portería.\"},{\"heading\":false,\"text\":\"Sentíase otro Augusto y como si aquella visita y la revelación en ella de la mujer fuerte—fluía de sus ojos fortaleza—le hubiera arado las entrañas del alma, alumbrando en ellas un manantial hasta entonces oculto. Pisaba con más fuerza, respiraba con más libertad.\"},{\"heading\":false,\"text\":\"«Ya tengo un objetivo, una finalidad en esta vida—se decía—, y es conquistar a esta muchacha o que ella me conquiste. Y es lo mismo. En amor lo mismo da vencer que ser vencido. Aunque ¡no... no! Aquí ser vencido es que me deje por el otro. Por el otro, sí, porque aquí hay otro, no me cabe duda. ¿Otro? ¿otro qué? ¿Es que acaso yo soy uno? Yo soy un pretendiente, un solicitante, pero el otro... el otro se me antoja que no es ya pretendiente ni solicitante; que no pretende ni solicita porque ha obtenido. Claro que no más que el amor de la dulce Eugenia. ¿No más...?»\"},{\"heading\":false,\"text\":\"Un cuerpo de mujer irradiante de frescura, de salud y de alegría, que pasó a su vera, le interrumpió el soliloquio y le arrastró tras de sí. Púsose a seguir, casi maquinalmente, al cuerpo aquel, mientras proseguía soliloquizando:\"},{\"heading\":false,\"text\":\"«¡Y qué hermosa es! Ésta y aquélla, una y otra. Y el otro acaso en vez de pretender y solicitar es pretendido y solicitado; tal vez no le corresponde como ella se merece... Pero ¡qué alegría es esta chiquilla! ¡y con qué gracia saluda a aquel que va por allá! ¿De dónde habrá sacado esos ojos? ¡Son casi como los otros, como los de Eugenia! ¡Qué dulzura debe de ser olvidarse de la vida y de la muerte entre sus brazos! ¡dejarse brezar en ellos como en olas de carne! ¡El otro...! Pero el otro no es el novio de Eugenia, no es aquel a quien ella quiere; el otro soy yo. ¡Sí, yo soy el otro; yo soy otro!»\"},{\"heading\":false,\"text\":\"Al llegar a esta conclusión de que él era otro la moza a que seguía entró en una casa. Augusto se quedó parado, mirando a la casa. Y entonces se dio cuenta de que la había venido siguiendo. Recapacitó que había salido para ir al Casino y emprendió el camino de éste. Y proseguía:\"},{\"heading\":false,\"text\":\"«Pero ¡cuántas mujeres hermosas hay en este mundo, Dios mío! Casi todas. ¡Gracias, Señor, gracias; _gratias agimus tibi propter magnam gloriam tuam_! ¡tu gloria es la hermosura de la mujer, Señor! Pero ¡qué cabellera, Dios mío, qué cabellera!»\"},{\"heading\":false,\"text\":\"Era, en efecto, una gloriosa cabellera la de aquella criada de servicio, que con su cesta al brazo cruzaba en aquel momento con él. Y se volvió tras ella. La luz parecía anidar en el oro de aquellos cabellos, y como si éstos pugnaran por soltarse de su trenzado y esparcirse al aire fresco y claro. Y bajo la cabellera un rostro todo él sonrisa.\"},{\"heading\":false,\"text\":\"«Soy otro, soy el otro—prosiguió Augusto mientras seguía a la de la cesta—; pero ¿es que no hay otras? ¡Sí, hay otras para el otro! Pero como la una, como ella, como la única, ¡ninguna! ¡ninguna! Todas éstas no son sino remedos de ella, de la una, de la única, ¡de mi dulce Eugenia! ¿Mía? Sí; yo por el pensamiento, por el deseo la hago mía. Él, el otro, es decir, el uno, podrá llegar a poseerla materialmente; pero la misteriosa luz espiritual de aquellos ojos es mía, ¡mía, mía! Y ¿no reflejan también una misteriosa luz espiritual estos cabellos de oro? ¿Hay una sola Eugenia, o son dos, una la mía y otra la de su novio? Pues si es así, si hay dos, que se quede él con la suya, y con la mía me quedaré yo. Cuando la tristeza me visite, sobre todo de noche; cuando me entren ganas de llorar sin saber por qué, ¡oh, qué dulce habrá de ser cubrir mi cara, mi boca, mis ojos, con estos cabellos de oro y respirar el aire que a través de ellos se filtre y se perfume! Pero...»\"},{\"heading\":false,\"text\":\"Sintióse de pronto detenido. La de la cesta se había parado a hablar con otra compañera. Vaciló un momento Augusto, y diciéndose: «¡Bah, hay tantas mujeres hermosas desde que conocí a Eugenia...!», echó a andar, volviéndose camino del Casino.\"},{\"heading\":false,\"text\":\"«Si ella se empeña en preferir al otro, es decir, al uno, soy capaz de una resolución heroica, de algo que ha de espantar por lo magnánimo. Ante todo, quiérame o no me quiera, ¡eso de la hipoteca no puede quedar así!»\"},{\"heading\":false,\"text\":\"Arrancóle del soliloquio un estallido de goce que parecía brotar de la serenidad del cielo. Un par de muchachas reían junto a él, y era su risa como el gorjeo de dos pájaros en una enramada con flores. Clavó un momento sus ojos sedientos de hermosura en aquella pareja de mozas, y apareciéronsele como un solo cuerpo geminado. Iban cojidas de bracete. Y a él le entraron furiosas ganas de detenerlas, cojer a cada una de un brazo e irse así, en medio de ellas, mirando al cielo, adonde el viento de la vida los llevara.\"},{\"heading\":false,\"text\":\"«Pero ¡cuánta mujer hermosa hay desde que conocí a Eugenia!—se decía, siguiendo en tanto a aquella riente pareja—¡esto se ha convertido en un paraíso!; ¡qué ojos! ¡qué cabellera! ¡qué risa! La una es rubia y morena la otra; pero ¿cuál es la rubia? ¿cuál la morena? ¡Se me confunden una en otra!...»\"},{\"heading\":false,\"text\":\"—Pero, hombre, ¿vas despierto o dormido?\"},{\"heading\":false,\"text\":\"—Hola, Víctor.\"},{\"heading\":false,\"text\":\"—Te esperaba en el Casino, y como no venías...\"},{\"heading\":false,\"text\":\"—Allá iba...\"},{\"heading\":false,\"text\":\"—¿Allá? ¿y en esta dirección? ¿Estás loco?\"},{\"heading\":false,\"text\":\"—Sí, tienes razón; pero mira, voy a decirte la verdad. Creo que te hablé de Eugenia...\"},{\"heading\":false,\"text\":\"—¿De la pianista? Sí.\"},{\"heading\":false,\"text\":\"—Pues bien; estoy locamente enamorado de ella, como un...\"},{\"heading\":false,\"text\":\"—Sí, como un enamorado. Sigue.\"},{\"heading\":false,\"text\":\"—Loco, chico, loco. Ayer la vi en su casa, con pretexto de visitar a sus tíos; la vi...\"},{\"heading\":false,\"text\":\"—Y te miró, ¿no es eso? ¿y creíste en Dios?\"},{\"heading\":false,\"text\":\"—No, no es que me miró, es que me envolvió en su mirada; y no es que creí en Dios, sino que me creí un dios.\"},{\"heading\":false,\"text\":\"—Fuerte te entró, chico...\"},{\"heading\":false,\"text\":\"—¡Y eso que la moza estuvo brava! Pero no sé lo que desde entonces me pasa; casi todas las mujeres que veo me parecen hermosuras, y desde que he salido de casa, no hace aún media hora seguramente, me he enamorado ya de tres, digo, no, de cuatro: de una primero que era todo ojos, de otra después con una gloria de pelo, y hace poco de una pareja, una rubia y otra morena, que reían como los ángeles. Y las he seguido a las cuatro. ¿Qué es esto?\"},{\"heading\":false,\"text\":\"—Pues eso es, querido Augusto, que tu repuesto de amor dormía inerte en el fondo de tu alma, sin tener dónde meterse; llegó Eugenia, la pianista, te sacudió y remejió con sus ojos esa charca en que tu amor dormía; se despertó éste, brotó de ella, y como es tan grande se extiende a todas partes. Cuando uno como tú se enamora de veras de una mujer se enamora a la vez de todas las demás.\"},{\"heading\":false,\"text\":\"—Pues yo creí que sería todo lo contrario... Pero, entre paréntesis, ¡mira qué morena! ¡es la noche luminosa! ¡Bien dicen que lo negro es lo que más absorbe la luz! ¿No ves qué luz oculta se siente bajo su pelo, bajo el azabache de sus ojos? Vamos a seguirla...\"},{\"heading\":false,\"text\":\"—Como quieras...\"},{\"heading\":false,\"text\":\"—Pues sí, yo creí que sería todo lo contrario; que cuando uno se enamora de veras es que concentra su amor, antes desparramado entre todas, en una sola, y que todas las demás han de parecerle como si nada fuesen ni valiesen... Pero ¡mira! ¡mira ese golpe de sol en la negrura de su pelo!\"},{\"heading\":false,\"text\":\"—No; verás, verás si logro explicártelo. Tú estabas enamorado, sin saberlo por supuesto, de la mujer, del abstracto, no de ésta ni de aquélla; al ver a Eugenia, ese abstracto se concretó y la mujer se hizo una mujer y te enamoraste de ella, y ahora vas de ella, sin dejarla, a casi todas las mujeres, y te enamoras de la colectividad, del género. Has pasado, pues, de lo abstracto a lo concreto y de lo concreto a lo genérico, de la mujer a una mujer y de una mujer a las mujeres.\"},{\"heading\":false,\"text\":\"—¡Vaya una metafísica!\"},{\"heading\":false,\"text\":\"—Y ¿que es el amor sino metafísica?\"},{\"heading\":false,\"text\":\"—¡Hombre!\"},{\"heading\":false,\"text\":\"—Sobre todo en ti. Porque todo tu enamoramiento no es sino cerebral, o como suele decirse, de cabeza.\"},{\"heading\":false,\"text\":\"—Eso lo creerás tú...—exclamó Augusto un poco picado y de mal humor, pues aquello de que su enamoramiento no era sino de cabeza le había llegado, doliéndole, al fondo del alma.\"},{\"heading\":false,\"text\":\"—Y si me apuras mucho te digo que tú mismo no eres sino una pura idea, un ente de ficción...\"},{\"heading\":false,\"text\":\"—¿Es que no me crees capaz de enamorarme de veras, como los demás...?\"},{\"heading\":false,\"text\":\"—De veras estás enamorado, ya lo creo, pero de cabeza sólo. Crees que estás enamorado...\"},{\"heading\":false,\"text\":\"—Y ¿qué es estar uno enamorado sino creer que lo está?\"},{\"heading\":false,\"text\":\"—¡Ay, ay, ay, chico, eso es más complicado de lo que te figuras!...\"},{\"heading\":false,\"text\":\"—¿En qué se conoce, dime, que uno está enamorado y no solamente que cree estarlo?\"},{\"heading\":false,\"text\":\"—Mira, más vale que dejemos esto y hablemos de otras cosas.\"},{\"heading\":false,\"text\":\"Cuando luego volvió Augusto a su casa tomó en brazos a Orfeo y le dijo: «Vamos a ver, Orfeo mío, ¿en qué se diferencia estar uno enamorado de creer que lo está? ¿Es que estoy yo o no estoy enamorado de Eugenia? ¿es que cuando la veo no me late el corazón en el pecho y se me enciende la sangre? ¿es que yo no soy como los demás hombres? ¡Tengo que demostrarles, Orfeo, que soy tanto como ellos!»\"},{\"heading\":false,\"text\":\"Y a la hora de cenar, encarándose con Liduvina le preguntó:\"},{\"heading\":false,\"text\":\"—Di, Liduvina, ¿en qué se conoce que un hombre está de veras enamorado?\"},{\"heading\":false,\"text\":\"—Pero ¡qué cosas se le ocurren a usted señorito...!\"},{\"heading\":false,\"text\":\"—Vamos, di, ¿en qué se conoce?\"},{\"heading\":false,\"text\":\"—Pues se conoce... se conoce en que hace y dice muchas tonterías. Cuando un hombre se enamora de veras, se _chala_, vamos al decir, por una mujer, ya no es un hombre...\"},{\"heading\":false,\"text\":\"—Pues ¿qué es?\"},{\"heading\":false,\"text\":\"—Es... es... es... una cosa, un animalito... Una hace de él lo que quiere.\"},{\"heading\":false,\"text\":\"—Entonces, cuando una mujer se enamora de veras de un hombre, se _chala_, como dices, ¿hace de ella el hombre lo que quiere?\"},{\"heading\":false,\"text\":\"—El caso no es enteramente igual...\"},{\"heading\":false,\"text\":\"—¿Cómo, cómo?\"},{\"heading\":false,\"text\":\"—Eso es muy difícil de explicar, señorito. Pero ¿está usted de veras enamorado?\"},{\"heading\":false,\"text\":\"—Es lo que trato de averiguar. Pero tonterías, de las gordas, no he dicho ni hecho todavía ninguna... me parece...\"},{\"heading\":false,\"text\":\"Liduvina se calló, y Augusto se dijo: «¿Estaré de veras enamorado?»\"}]},{\"title\":\"Capítulo XI\",\"blocks\":[{\"heading\":false,\"text\":\"Cuando llamó aquel otro día Augusto a casa de don Fermín y doña Ermelinda, la criada le pasó a la sala diciéndole: «Ahora aviso». Quedóse un momento solo y como si estuviese en el vacío. Sentía una profunda opresión en el pecho. Ceñíale una angustiosa sensación de solemnidad. Sentóse para levantarse al punto y se entretuvo en mirar los cuadros que colgaban de las paredes, un retrato de Eugenia entre ellos. Entráronle ganas de echar a correr, de escaparse. De pronto, al oir unos pasos menudos, sintió un puñal de hielo atravesarle el pecho y como una bruma invadirle la cabeza. Abrióse la puerta de la sala y apareció Eugenia. El pobre se apoyó en el respaldo de una butaca. Ella, al verle lívido, palideció un momento y se quedó suspensa en medio de la sala, y luego, acercándose a él, le dijo con voz seca y baja:\"},{\"heading\":false,\"text\":\"—¿Qué le pasa a usted, don Augusto, se pone malo?\"},{\"heading\":false,\"text\":\"—No, no es nada; qué sé yo...\"},{\"heading\":false,\"text\":\"—¿Quiere algo? ¿necesita algo?\"},{\"heading\":false,\"text\":\"—Un vaso de agua.\"},{\"heading\":false,\"text\":\"Eugenia, como quien ve un agarradero, salió de la estancia para ir ella misma a buscar el vaso de agua, que se lo trajo al punto. El agua tembloteaba en el vaso; pero más tembló éste en manos de Augusto, que se lo bebió de un trago, atropelladamente, vertiéndosele agua por la barba, y sin quitar en tanto sus ojos de los ojos de Eugenia.\"},{\"heading\":false,\"text\":\"—Si quiere usted—dijo ella—, mandaré que le hagan una taza de té, o de manzanilla, o de tila... ¿Qué, se ha pasado?\"},{\"heading\":false,\"text\":\"—No, no, no fué nada; gracias, Eugenia, gracias—y se enjugaba el agua de la barba.\"},{\"heading\":false,\"text\":\"—Bueno, pues ahora siéntese usted—y cuando estuvieron sentados prosiguió ella—: Le esperaba cualquier día y di orden a la criada de que aunque no estuviesen mis tíos, como sucede algunas tardes, le hiciese a usted pasar y me avisara. Así como así, deseaba que hablásemos a solas.\"},{\"heading\":false,\"text\":\"—¡Oh, Eugenia, Eugenia!\"},{\"heading\":false,\"text\":\"—Bueno, las cosas más fríamente. Nunca me pude imaginar que le daría tan fuerte, porque me dio usted miedo cuando entré aquí; parecía un muerto.\"},{\"heading\":false,\"text\":\"—Y más muerto que vivo estaba, créamelo.\"},{\"heading\":false,\"text\":\"—Va a ser menester que nos expliquemos.\"},{\"heading\":false,\"text\":\"—¡Eugenia!—exclamó el pobre, y extendió una mano que recojió al punto.\"},{\"heading\":false,\"text\":\"—Todavía me parece que no está usted en disposición de que hablemos tranquilamente, como buenos amigos. ¡A ver!—y le cojió la mano para tomarle el pulso.\"},{\"heading\":false,\"text\":\"Y éste empezó a latir febril en el pobre Augusto; se puso rojo, ardíale la frente. Los ojos de Eugenia se le borraron de la vista y no vio ya nada sino una niebla, una niebla roja. Un momento creyó perder el sentido.\"},{\"heading\":false,\"text\":\"—¡Ten compasión, Eugenia, ten compasión de mí!\"},{\"heading\":false,\"text\":\"—¡Cálmese usted, don Augusto, cálmese!\"},{\"heading\":false,\"text\":\"—Don Augusto... don Augusto... don... don...\"},{\"heading\":false,\"text\":\"—Sí, mi bueno de don Augusto, cálmese usted y hablemos tranquilamente.\"},{\"heading\":false,\"text\":\"—Pero, permítame...—y le cojió entre sus dos manos la diestra aquella blanca y fría como la nieve, de ahusados dedos, hechos para acariciar las teclas del piano, para arrancarles dulces arpegios.\"},{\"heading\":false,\"text\":\"—Como usted quiera, don Augusto.\"},{\"heading\":false,\"text\":\"Este se la llevó a los labios y la cubrió de besos que apenas entibiaron la frialdad blanca.\"},{\"heading\":false,\"text\":\"—Cuando usted acabe, don Augusto, empezaremos a hablar.\"},{\"heading\":false,\"text\":\"—Pero mira, Eugenia, ven...\"},{\"heading\":false,\"text\":\"—No, no, no, ¡formalidad!—y desprendiendo su mano de las de él prosiguió: Yo no sé qué género de esperanzas le habrán hecho concebir mis tíos, o más bien mi tía, pero el caso es que me parece que usted está engañado.\"},{\"heading\":false,\"text\":\"—¿Cómo engañado?\"},{\"heading\":false,\"text\":\"—Sí, han debido decirle que tengo novio.\"},{\"heading\":false,\"text\":\"—Lo sé.\"},{\"heading\":false,\"text\":\"—¿Se lo han dicho ellos?\"},{\"heading\":false,\"text\":\"—No, no me lo ha dicho nadie, pero lo sé.\"},{\"heading\":false,\"text\":\"—Entonces...\"},{\"heading\":false,\"text\":\"—Pero es, Eugenia, que yo no pretendo nada, que no busco nada, que nada pido; es, Eugenia, que yo me contento con que se me deje venir de cuando en cuando a bañar mi espíritu en la mirada de esos ojos, a embriagarme en el vaho de su respiración...\"},{\"heading\":false,\"text\":\"—Bueno, don Augusto, esas son cosas que se leen en los libros; dejemos eso. Yo no me opongo a que usted venga cuantas veces se le antoje, a que me vea y me revea, a que hable conmigo y hasta... ya lo ha visto usted, hasta a que me bese la mano, pero yo tengo un novio, del cual estoy enamorada y con el cual pienso casarme.\"},{\"heading\":false,\"text\":\"—Pero ¿de veras está usted enamorada de él?\"},{\"heading\":false,\"text\":\"—¡Vaya una pregunta!\"},{\"heading\":false,\"text\":\"—Y ¿en qué conoce usted que está de él enamorada?\"},{\"heading\":false,\"text\":\"—Pero ¿es que se ha vuelto usted loco, don Augusto?\"},{\"heading\":false,\"text\":\"—No, no; lo digo porque mi amigo mejor me ha dicho que hay muchos que creen estar enamorados sin estarlo...\"},{\"heading\":false,\"text\":\"—Lo ha dicho por usted, ¿no es eso?\"},{\"heading\":false,\"text\":\"—Sí, por mí lo ha dicho; ¿pues?\"},{\"heading\":false,\"text\":\"—Porque en el caso de usted acaso sea verdad eso...\"},{\"heading\":false,\"text\":\"—Pero ¿es que cree usted, es que crees, Eugenia, que no estoy de veras enamorado de ti?\"},{\"heading\":false,\"text\":\"—No alce usted tanto la voz, don Augusto, que puede oirle la criada...\"},{\"heading\":false,\"text\":\"—¡Sí, sí—continuó exaltándose—, hay quien me cree incapaz de enamorarme de veras...!\"},{\"heading\":false,\"text\":\"—Dispense un momento—le interrumpió Eugenia, y se salió dejándole solo.\"},{\"heading\":false,\"text\":\"Volvió al poco rato y con la mayor tranquilidad le dijo:\"},{\"heading\":false,\"text\":\"—Y bien, don Augusto, ¿se ha calmado ya?\"},{\"heading\":false,\"text\":\"—¡Eugenia! ¡Eugenia!\"},{\"heading\":false,\"text\":\"En este momento se oyó llamar a la puerta y Eugenia dijo:—¡Mis tíos!—A los pocos momentos entraban éstos en la sala.\"},{\"heading\":false,\"text\":\"—Vino don Augusto a visitaros, salí yo misma a abrirle, quería irse, pero le dije que pasara, que no tardaríais en venir, ¡y aquí está!\"},{\"heading\":false,\"text\":\"—¡Vendrán tiempos—exclamó don Fermín—en que se disiparán los convencionalismos sociales todos! Estoy convencido de que las cercas y tapias de las propiedades privadas no son más que un incentivo para los que llamamos ladrones, cuando los ladrones son los otros, los propietarios. No hay propiedad más segura que la que está sin cercas ni tapias, al alcance de todo el mundo. El hombre nace bueno, es naturalmente bueno; la sociedad le malea y pervierte...\"},{\"heading\":false,\"text\":\"—¡Cállate, hombre—exclamó doña Ermelinda—, que no me dejas oir cantar al canario! ¿No le oye usted, don Augusto? ¡Es un encanto oirle! Y cuando ésta se ponía a aprender sus lecciones de piano había que oirle a un canario que entonces tuve: se excitaba, y cuanto más ésta daba a las teclas, más él a cantar y más cantar. Como que se murió de eso, reventado...\"},{\"heading\":false,\"text\":\"—¡Hasta los animales domésticos se contagian de nuestros vicios!—agregó el tío—. ¡Hasta a los animales que con nosotros conviven les hemos arrancado del santo estado de naturaleza! ¡Oh, humanidad, humanidad!\"},{\"heading\":false,\"text\":\"—Y ¿ha tenido usted que esperar mucho, don Augusto?—preguntó la tía.\"},{\"heading\":false,\"text\":\"—Oh, no, señora, no, nada, nada, un momentito, un relámpago... por lo menos así me lo pareció...\"},{\"heading\":false,\"text\":\"—¡Ah, vamos!\"},{\"heading\":false,\"text\":\"—Sí, tía, muy poco tiempo, pero lo bastante para que se haya repuesto de una lijera indisposición que trajo de la calle...\"},{\"heading\":false,\"text\":\"—¿Cómo?\"},{\"heading\":false,\"text\":\"—Oh, no fué nada, señora, nada...\"},{\"heading\":false,\"text\":\"—Ahora yo les dejo, tengo que hacer—dijo Eugenia, y dando la mano a Augusto se fué.\"},{\"heading\":false,\"text\":\"—Y ¿qué, cómo va eso?—le preguntó a Augusto la tía así que Eugenia hubo salido.\"},{\"heading\":false,\"text\":\"—Y ¿qué es eso?\"},{\"heading\":false,\"text\":\"—¡La conquista, naturalmente!\"},{\"heading\":false,\"text\":\"—¡Mal, muy mal! Me ha dicho que tiene novio y que se ha de casar con él.\"},{\"heading\":false,\"text\":\"—No te lo decía yo, Ermelinda, ¡no te lo decía!\"},{\"heading\":false,\"text\":\"—Pues ¡no, no y no!, no puede ser. Eso del novio es una locura, don Augusto, ¡una locura!\"},{\"heading\":false,\"text\":\"—Pero, señora, ¿y si está enamorada de él...?\"},{\"heading\":false,\"text\":\"—Eso digo yo—exclamó el tío—, eso digo yo. ¡La libertad, la santa libertad, la libertad de elección!\"},{\"heading\":false,\"text\":\"—Pues ¡no, no y no! ¿Acaso sabe esa chiquilla lo que se hace...? ¡Despreciarle a usted, don Augusto, a usted! ¡Eso no puede ser!\"},{\"heading\":false,\"text\":\"—Pero, señora, reflexione, fíjese... no se puede, no se debe violentar así la voluntad de una joven como Eugenia... Se trata de su felicidad, y no debemos todos preocuparnos sino de ella, y hasta sacrificarnos para que la consiga...\"},{\"heading\":false,\"text\":\"—¿Usted, don Augusto, usted?\"},{\"heading\":false,\"text\":\"—¡Yo, sí, yo, señora! ¡Estoy dispuesto a sacrificarme por la felicidad de Eugenia, de su sobrina, porque mi felicidad consiste en que ella sea feliz!\"},{\"heading\":false,\"text\":\"—¡Bravo!—exclamó el tío—¡bravo! ¡bravo! ¡He aquí un héroe! ¡he aquí un anarquista... místico!\"},{\"heading\":false,\"text\":\"—¿Anarquista?—dijo Augusto.\"},{\"heading\":false,\"text\":\"—Anarquista, sí. Porque mi anarquismo consiste en eso, en eso precisamente, en que cada cual se sacrifique por los demás, en que uno sea feliz haciendo felices a los otros, en que...\"},{\"heading\":false,\"text\":\"—¡Pues bueno te pones, Fermín, cuando un día cualquiera no se te sirve la sopa sino diez minutos después de las doce!\"},{\"heading\":false,\"text\":\"—Bueno, es que ya sabes, Ermelinda, que mi anarquismo es teórico... me esfuerzo por llegar a la perfección, pero...\"},{\"heading\":false,\"text\":\"—¡Y la felicidad también es teórica!—exclamó Augusto, compungido y como quien habla consigo mismo, y luego—: He decidido sacrificarme a la felicidad de Eugenia y he pensado en un acto heroico.\"},{\"heading\":false,\"text\":\"—¿Cuál?\"},{\"heading\":false,\"text\":\"—¿No me dijo usted una vez, señora, que la casa que a Eugenia dejó su desgraciado padre...\"},{\"heading\":false,\"text\":\"—Sí, mi pobre hermano.\"},{\"heading\":false,\"text\":\"—... está gravada con una hipoteca que se lleva sus rentas todas?\"},{\"heading\":false,\"text\":\"—Sí, señor.\"},{\"heading\":false,\"text\":\"—Pues bien; ¡yo sé lo que he de hacer!—y se dirigió a la puerta.\"},{\"heading\":false,\"text\":\"—Pero, don Augusto...\"},{\"heading\":false,\"text\":\"—Augusto se siente capaz de las más heroicas determinaciones, de los más grandes sacrificios. Y ahora se sabrá si está enamorado nada más que de cabeza o lo está también de corazón, si es que cree estar enamorado sin estarlo. Eugenia, señores, me ha despertado a la vida, a la verdadera vida, y, sea ella de quien fuere, yo le debo gratitud eterna. Y ahora, ¡adiós!\"},{\"heading\":false,\"text\":\"Y se salió solemnemente. Y no bien hubo salido gritó doña Ermelinda:\"},{\"heading\":false,\"text\":\"—¡Chiquilla!\"}]},{\"title\":\"Capítulo XII\",\"blocks\":[{\"heading\":false,\"text\":\"—Señorito—entró un día después a decir a Augusto Liduvina—, ahí está la del planchado.\"},{\"heading\":false,\"text\":\"—¿La del planchado? ¡Ah, sí, que pase!\"},{\"heading\":false,\"text\":\"Entró la muchacha llevando el cesto del planchado de Augusto. Quedáronse mirándose, y ella, la pobre, sintió que se le encendía el rostro, pues nunca cosa igual le ocurrió en aquella casa en tantas veces como allí entró. Parecía antes como si el señorito ni la hubiese visto siquiera, lo que a ella, que creía conocerse, habíala tenido inquieta y hasta mohína. ¡No fijarse en ella! ¡No mirarle como le miraban otros hombres! ¡No devorarle con los ojos, o más bien lamerle con ellos los de ella y la boca y la cara toda!\"},{\"heading\":false,\"text\":\"—¿Qué te pasa Rosario, porque creo que te llamas así, no?\"},{\"heading\":false,\"text\":\"—Sí, así me llamo.\"},{\"heading\":false,\"text\":\"—Y ¿qué te pasa?\"},{\"heading\":false,\"text\":\"—¿Por qué, señorito Augusto?\"},{\"heading\":false,\"text\":\"—Nunca te he visto ponerte así colorada. Y además me pareces otra.\"},{\"heading\":false,\"text\":\"—El que me parece que es otro es usted...\"},{\"heading\":false,\"text\":\"—Puede ser... puede ser... Pero ven, acércate.\"},{\"heading\":false,\"text\":\"—¡Vamos, déjese de bromas y despachemos!\"},{\"heading\":false,\"text\":\"—¿Bromas? Pero ¿tú crees que es broma?—le dijo con voz más seria—. Acércate, así, que te vea bien.\"},{\"heading\":false,\"text\":\"—Pero ¿es que no me ha visto otras veces?\"},{\"heading\":false,\"text\":\"—Sí, pero hasta ahora no me había dado cuenta de que fueses tan guapa como eres...\"},{\"heading\":false,\"text\":\"—Vamos, vamos, señorito, no se burle...—y le ardía la cara.\"},{\"heading\":false,\"text\":\"—Y ahora, con esos colores, talmente el sol...\"},{\"heading\":false,\"text\":\"—Vamos...\"},{\"heading\":false,\"text\":\"—Ven acá, ven. Tú dirás que el señorito Augusto se ha vuelto loco, ¿no es así? Pues no, no es eso, ¡no! Es que lo ha estado hasta ahora, o mejor dicho, es que he estado hasta ahora tonto, tonto del todo, perdido en una niebla, ciego... No hace sino muy poco tiempo que se me han abierto los ojos. Ya ves, tantas veces como has entrado en esta casa y te he mirado y no te había visto. Es, Rosario, como si no hubiese vivido, lo mismo que si no hubiese vivido... Estaba tonto, tonto... Pero ¿qué te pasa, chiquilla, qué es lo que te pasa?\"},{\"heading\":false,\"text\":\"Rosario, que se había tenido que sentar en una silla, ocultó la cara en las manos y rompió a llorar. Augusto se levantó, cerró la puerta, volvió a la mocita, y poniéndole una mano sobre el hombro le dijo con su voz más húmeda y más caliente, muy bajo:\"},{\"heading\":false,\"text\":\"—Pero ¿qué te pasa, chiquilla, qué es eso?\"},{\"heading\":false,\"text\":\"—Que con esas cosas me hace usted llorar, don Augusto...\"},{\"heading\":false,\"text\":\"—¡Ángel de Dios!\"},{\"heading\":false,\"text\":\"—No diga usted esas cosas, don Augusto.\"},{\"heading\":false,\"text\":\"—¡Cómo que no las diga! Sí, he vivido ciego, tonto, como si no viviera, hasta que llegó una mujer, ¿sabes?, otra, y me abrió los ojos y he visto el mundo, y sobre todo he aprendido a veros a vosotras, a las mujeres...\"},{\"heading\":false,\"text\":\"—Y esa mujer... sería alguna mala mujer...\"},{\"heading\":false,\"text\":\"—¿Mala? ¿mala dices? ¿Sabes lo que dices, Rosario, sabes lo que dices? ¿Sabes lo que es ser malo? ¿Qué es ser malo? No, no, no, esa mujer es, como tú, un ángel; pero esa mujer no me quiere... no me quiere... no me quiere...—y al decirlo se le quebró la voz y se le empañaron en lágrimas los ojos.\"},{\"heading\":false,\"text\":\"—¡Pobre don Augusto!\"},{\"heading\":false,\"text\":\"—¡Sí, tú lo has dicho, Rosario, tú lo has dicho! ¡pobre don Augusto! Pero mira, Rosario, quita el don y di: ¡pobre Augusto! Vamos, di: ¡pobre Augusto!\"},{\"heading\":false,\"text\":\"—Pero, señorito...\"},{\"heading\":false,\"text\":\"—Vamos, dilo: ¡pobre Augusto!\"},{\"heading\":false,\"text\":\"—Si usted se empeña... ¡pobre Augusto!\"},{\"heading\":false,\"text\":\"Augusto se sentó.\"},{\"heading\":false,\"text\":\"—¡Ven acá!—la dijo.\"},{\"heading\":false,\"text\":\"Levantóse ella cual movida por un resorte, como una hipnótica sugestionada, con la respiración anhelante. Cojióla él, la sentó sobre sus rodillas, la apretó fuertemente a su pecho, y teniendo su mejilla apretada contra la mejilla de la muchacha, que echaba fuego, estalló diciendo:\"},{\"heading\":false,\"text\":\"—¡Ay, Rosario, Rosario, yo no sé lo que me pasa, yo no sé lo que es de mí! Esa mujer que tú dices que es mala, sin conocerla, me ha vuelto ciego al darme la vista. Yo no vivía, y ahora vivo; pero ahora que vivo es cuando siento lo que es morir. Tengo que defenderme de esa mujer, tengo que defenderme de su mirada. ¿Me ayudarás tú, Rosario, me ayudarás a que de ella me defienda?\"},{\"heading\":false,\"text\":\"Un ¡sí! tenuísimo, con susurro que parecía venir de otro mundo, rozó el oído de Augusto.\"},{\"heading\":false,\"text\":\"—Yo ya no sé lo que me pasa, Rosario, ni lo que digo, ni lo que hago, ni lo que pienso; yo ya no sé si estoy o no enamorado de esa mujer, de esa mujer a la que llamas mala...\"},{\"heading\":false,\"text\":\"—Es que yo, don Augusto...\"},{\"heading\":false,\"text\":\"—Augusto, Augusto...\"},{\"heading\":false,\"text\":\"—Es que yo, Augusto...\"},{\"heading\":false,\"text\":\"—Bueno, cállate, basta—y cerraba él los ojos—, no digas nada, déjame hablar solo, conmigo mismo. Así he vivido desde que se murió mi madre, conmigo mismo, nada más que conmigo; es decir, dormido. Y no he sabido lo que es dormir juntamente, dormir dos un mismo sueño. ¡Dormir juntos! No estar juntos durmiendo cada cual su sueño, ¡no!, sino dormir juntos, ¡dormir juntos el mismo sueño! ¿Y si durmiéramos tú y yo, Rosario, el mismo sueño?\"},{\"heading\":false,\"text\":\"—Y esa mujer...—empezó la pobre chica, temblando entre los brazos de Augusto y con lágrimas en la voz.\"},{\"heading\":false,\"text\":\"—Esa mujer, Rosario, no me quiere... no me quiere... no me quiere... Pero ella me ha enseñado que hay otras mujeres, por ella he sabido que hay otras mujeres... y alguna podrá quererme... ¿Me querrás tú, Rosario, dime, me querrás tú?—y la apretaba como loco contra su pecho.\"},{\"heading\":false,\"text\":\"—Creo que sí... que le querré...\"},{\"heading\":false,\"text\":\"—¡Que te querré, Rosario, que te querré!\"},{\"heading\":false,\"text\":\"—Que te querré...\"},{\"heading\":false,\"text\":\"—¡Así, así, Rosario, así! ¡Eh!\"},{\"heading\":false,\"text\":\"En aquel momento se abrió la puerta, apareció Liduvina, y exclamando: ¡ah!, volvió a cerrarla. Augusto se turbó mucho más que Rosario, la cual, poniéndose rápidamente en pie, se atusó el pelo, se sacudió el cuerpo y con voz entrecortada dijo:\"},{\"heading\":false,\"text\":\"—Bueno, señorito, ¿hacemos la cuenta?\"},{\"heading\":false,\"text\":\"—Sí, tienes razón. Pero volverás, eh, volverás.\"},{\"heading\":false,\"text\":\"—Sí, volveré.\"},{\"heading\":false,\"text\":\"—¿Y me perdonas todo? ¿me lo perdonas?\"},{\"heading\":false,\"text\":\"—¿Perdonarle... qué?\"},{\"heading\":false,\"text\":\"—Esto, esto... Ha sido una locura. ¿Me lo perdonas?\"},{\"heading\":false,\"text\":\"—Yo no tengo nada que perdonarle, señorito. Y lo que debe hacer es no pensar en esa mujer.\"},{\"heading\":false,\"text\":\"—Y tú, ¿pensarás en mí?\"},{\"heading\":false,\"text\":\"—Vaya, que tengo que irme.\"},{\"heading\":false,\"text\":\"Arreglaron la cuenta y Rosario se fué. Y apenas se había ido entró Liduvina:\"},{\"heading\":false,\"text\":\"—¿No me preguntaba usted el otro día, señorito, en qué se conoce si un hombre está o no enamorado?\"},{\"heading\":false,\"text\":\"—En efecto.\"},{\"heading\":false,\"text\":\"—Y le dije en que hace o dice tonterías. Pues bien; ahora puedo asegurarle que usted está enamorado.\"},{\"heading\":false,\"text\":\"—Pero ¿de quién? ¿de Rosario?\"},{\"heading\":false,\"text\":\"—¿De Rosario...? ¡Quia! ¡De la otra!\"},{\"heading\":false,\"text\":\"—Y ¿de dónde sacas eso, Liduvina?\"},{\"heading\":false,\"text\":\"—¡Bah! Usted ha estado diciendo y haciendo a ésta lo que no pudo decir ni hacer a la otra.\"},{\"heading\":false,\"text\":\"—Pero ¿tú te crees...?\"},{\"heading\":false,\"text\":\"—No, no, si ya me supongo que no ha pasado a mayores; pero...\"},{\"heading\":false,\"text\":\"—¡Liduvina, Liduvina!\"},{\"heading\":false,\"text\":\"—Como usted quiera, señorito.\"},{\"heading\":false,\"text\":\"El pobre fué a acostarse ardiéndole la cabeza. Y al echarse en la cama, a cuyos pies dormía Orfeo, se decía: «¡Ay, Orfeo, Orfeo, esto de dormir solo, solo, solo, de dormir un solo sueño! El sueño de uno solo es la ilusión, la apariencia; el sueño de dos es ya la verdad, la realidad. ¿Qué es el mundo real sino el sueño que soñamos todos, el sueño común?»\"},{\"heading\":false,\"text\":\"Y cayó en el sueño.\"}]},{\"title\":\"Capítulo XIII\",\"blocks\":[{\"heading\":false,\"text\":\"Pocos días después de esto entró una mañana Liduvina en el cuarto de Augusto diciéndole que una señorita preguntaba por él.\"},{\"heading\":false,\"text\":\"—¿Una señorita?\"},{\"heading\":false,\"text\":\"—Sí, ella, la pianista.\"},{\"heading\":false,\"text\":\"—¿Eugenia?\"},{\"heading\":false,\"text\":\"—Eugenia, sí. Decididamente no es usted el único que se ha vuelto loco.\"},{\"heading\":false,\"text\":\"El pobre Augusto empezó a temblar. Y es que se sentía reo. Levantóse, lavóse de prisa, se vistió y fué dispuesto a todo.\"},{\"heading\":false,\"text\":\"—Ya sé, señor don Augusto—le dijo solemnemente Eugenia en cuanto le vio—, que ha comprado usted mi deuda a mi acreedor, que está en su poder la hipoteca de mi casa.\"},{\"heading\":false,\"text\":\"—No lo niego.\"},{\"heading\":false,\"text\":\"—Y ¿con qué derecho hizo eso?\"},{\"heading\":false,\"text\":\"—Con el derecho, señorita, que tiene todo ciudadano a comprar lo que bien le parezca si el poseedor quiera venderlo.\"},{\"heading\":false,\"text\":\"—No quiero decir eso, sino ¿para qué lo ha comprado usted?\"},{\"heading\":false,\"text\":\"—Pues porque me dolía verle depender así de un hombre a quien acaso usted sea indiferente y que sospecho no es más que un traficante sin entrañas.\"},{\"heading\":false,\"text\":\"—Es decir, que usted pretende que dependa yo de usted, ya que no le soy indiferente...\"},{\"heading\":false,\"text\":\"—¡Oh, eso nunca, nunca, nunca! ¡Nunca, Eugenia, nunca! Yo no busco que usted dependa de mí. Me ofende usted sólo con suponerlo. Verá usted—y dejándola sola se salió agitadísimo.\"},{\"heading\":false,\"text\":\"Volvió al poco rato trayendo unos papeles.\"},{\"heading\":false,\"text\":\"—He aquí, Eugenia, los documentos que acreditan su deuda. Tómelos usted y haga de ellos lo que quiera.\"},{\"heading\":false,\"text\":\"—¿Cómo?\"},{\"heading\":false,\"text\":\"—Sí, que renuncio a todo. Para eso lo compré.\"},{\"heading\":false,\"text\":\"—Lo sabía, y por eso le dije que usted no pretende sino hacer que dependa de usted. Me quiere usted ligar por la gratitud. ¡Quiere usted comprarme!\"},{\"heading\":false,\"text\":\"—¡Eugenia! ¡Eugenia!\"},{\"heading\":false,\"text\":\"—Sí, quiere usted comprarme, quiere usted comprarme; ¡quiere usted comprar... no mi amor, que ése no se compra, sino mi cuerpo!\"},{\"heading\":false,\"text\":\"—¡Eugenia! ¡Eugenia!\"},{\"heading\":false,\"text\":\"—Esto es, aunque usted no lo crea, una infamia, nada más que una infamia.\"},{\"heading\":false,\"text\":\"—¡Eugenia, por Dios, Eugenia!\"},{\"heading\":false,\"text\":\"—¡No se me acerque usted más, que no respondo de mí!\"},{\"heading\":false,\"text\":\"—Pues bien, sí, me acerco. ¡Pégame, Eugenia, pégame; insúltame, escúpeme, haz de mí lo que quieras!\"},{\"heading\":false,\"text\":\"—No merece usted nada—y Eugenia se levantó—; me voy, pero ¡cónstele que no acepto su limosna o su oferta! Trabajaré más que nunca; haré que trabaje mi novio, pronto mi marido, y viviremos. Y en cuanto a eso, quédese usted con mi casa.\"},{\"heading\":false,\"text\":\"—Pero ¡si yo no me opongo, Eugenia, a que usted se case con ese novio que dice!\"},{\"heading\":false,\"text\":\"—¿Cómo? ¿cómo? ¿A ver?\"},{\"heading\":false,\"text\":\"—¡Si yo no he hecho esto para que usted, ligada por gratitud, acceda a tomarme por marido!... ¡Si yo renuncio a mi propia felicidad, mejor dicho, si mi felicidad consiste en que usted sea feliz y nada más, en que sea usted feliz con el marido que libremente escoja!...\"},{\"heading\":false,\"text\":\"—¡Ah, ya, ya caigo; usted se reserva el papel de heroica víctima, de mártir! Quédese usted con la casa, le digo. Se la regalo.\"},{\"heading\":false,\"text\":\"—Pero, Eugenia, Eugenia...\"},{\"heading\":false,\"text\":\"—¡Basta!\"},{\"heading\":false,\"text\":\"Y sin más mirarle, aquellos dos ojos de fuego desaparecieron.\"},{\"heading\":false,\"text\":\"Quedóse Augusto un momento fuera de sí, sin darse cuenta de que existía, y cuando sacudió la niebla de confusión que le envolviera tomó el sombrero y se echó a la calle, a errar a la ventura. Al pasar junto a una iglesia, San Martín, entró en ella, casi sin darse cuenta de lo que hacía. No vio al entrar sino el mortecino resplandor de la lamparilla que frente al altar mayor ardía. Parecíale respirar oscuridad, olor a vejez, a tradición sahumada en incienso, a hogar de siglos, y andando casi a tientas fué a sentarse en un banco. Dejóse en él caer más que se sentó. Sentíase cansado, mortalmente cansado y como si toda aquella oscuridad, toda aquella vejez que respiraba le pesasen sobre el corazón. De un susurro que parecía venir de lejos, de muy lejos, emergía una tos contenida de cuando en cuando. Acordóse de su madre.\"},{\"heading\":false,\"text\":\"Cerró los ojos y volvió a soñar aquella casa dulce y tibia, en que la luz entraba por entre las blancas flores bordadas en los visillos. Volvió a ver a su madre, yendo y viniendo sin ruido, siempre de negro, con aquella su sonrisa que era poso de lágrimas. Y repasó su vida toda de hijo, cuando formaba parte de su madre y vivía a su amparo, y aquella muerte lenta, grave, dulce e indolorosa de la pobre señora, cuando se fué como un ave peregrina que emprende sin ruido el vuelo. Luego recordó o resoñó el encuentro de Orfeo, y al poco rato encontróse sumido en un estado de espíritu en que pasaban ante él, en cinematógrafo, las más extrañas visiones.\"},{\"heading\":false,\"text\":\"Junto a él un hombre susurraba rezos. El hombre se levantó para salir y él le siguió. A la salida de la iglesia el hombre aquél mojó los dedos índice y corazón de su diestra en el aguabenditera y ofreció agua bendita a Augusto, santiguándose luego. Encontráronse juntos en la cancela.\"},{\"heading\":false,\"text\":\"—¡Don Avito!—exclamó Augusto.\"},{\"heading\":false,\"text\":\"—¡El mismo, Augustito, el mismo!\"},{\"heading\":false,\"text\":\"—Pero ¿usted por aquí?\"},{\"heading\":false,\"text\":\"—Sí, yo por aquí; enseña mucho la vida, y más la muerte; enseñan más, mucho más que la ciencia.\"},{\"heading\":false,\"text\":\"—Pero ¿y el candidato a genio?\"},{\"heading\":false,\"text\":\"Don Avito Carrascal le contó la lamentable historia de su hijo[1]. Y concluyó diciendo: «Ya ves, Augustito, cómo he venido a esto...»\"},{\"heading\":false,\"text\":\"[1] Historia que he contado en mi novela _Amor y Pedagogía_.\"},{\"heading\":false,\"text\":\"Augusto callaba mirando al suelo. Iban por la alameda.\"},{\"heading\":false,\"text\":\"—Sí, Augusto, sí—prosiguió don Avito—; la vida es la única maestra de la vida; no hay pedagogía que valga. Sólo se aprende a vivir viviendo, y cada hombre tiene que recomenzar el aprendizaje de la vida de nuevo...\"},{\"heading\":false,\"text\":\"—¿Y la labor de las generaciones, don Avito, el legado de los siglos?\"},{\"heading\":false,\"text\":\"—No hay más que dos legados: el de las ilusiones y el de los desengaños, y ambos sólo se encuentran donde nos encontramos hace poco: en el templo. De seguro que te llevó allá o una gran ilusión o un gran desengaño.\"},{\"heading\":false,\"text\":\"—Las dos cosas.\"},{\"heading\":false,\"text\":\"—Sí, las dos cosas, sí. Porque la ilusión, la esperanza, engendra el desengaño, el recuerdo, y el desengaño, el recuerdo, engendra a su vez la ilusión, la esperanza. La ciencia es realidad, es presente, querido Augusto, y yo no puedo vivir ya de nada presente. Desde que mi pobre Apolodoro, mi víctima—y al decir esto le lloraba la voz—, murió, es decir, se mató, no hay ya presente posible, no hay ciencia ni realidad que valgan para mí; no puedo vivir sino recordándole o esperándole. Y he ido a parar a ese hogar de todas las ilusiones y todos los desengaños: ¡a la iglesia!\"},{\"heading\":false,\"text\":\"—¿De modo es que ahora cree usted?\"},{\"heading\":false,\"text\":\"—¡Qué sé yo...!\"},{\"heading\":false,\"text\":\"—Pero ¿no cree usted?\"},{\"heading\":false,\"text\":\"—No sé si creo o no creo; sé que rezo. Y no sé bien lo que rezo. Somos unos cuantos que al anochecer nos reunimos ahí a rezar el rosario. No sé quiénes son, ni ellos me conocen, pero nos sentimos solidarios, en íntima comunión unos con otros. Y ahora pienso que a la humanidad maldita la falta que le hacen los genios.\"},{\"heading\":false,\"text\":\"—¿Y su mujer, don Avito?\"},{\"heading\":false,\"text\":\"—¡Ah, mi mujer!—exclamó Carrascal, y una lágrima que se le había asomado a un ojo pareció irradiarle luz interna—. ¡Mi mujer! ¡la he descubierto! Hasta mi tremenda desgracia no he sabido lo que tenía en ella. Sólo he penetrado en el misterio de la vida cuando en las noches terribles que sucedieron al suicidio de mi Apolodoro reclinaba mi cabeza en el regazo de ella, de la madre, y lloraba, lloraba, lloraba. Y ella, pasándome dulcemente la mano por la cabeza, me decía: «¡Pobre hijo mío! ¡pobre hijo mío!» Nunca, nunca ha sido más madre que ahora. Jamás creí al hacerla madre, ¿y cómo?, nada más que para que me diese la materia prima del genio... jamás creí al hacerla madre que como tal la necesitaría para mí un día. Porque yo no conocí a mi madre, Augusto, no la conocí; yo no he tenido madre, no he sabido lo que es tenerla hasta que al perder mi mujer a mi hijo y suyo se ha sentido madre mía. Tú conociste a tu madre, Augusto, a la excelente doña Soledad, si no te aconsejaría que te casases.\"},{\"heading\":false,\"text\":\"—La conocí, don Avito, pero la perdí, y ahí, en la iglesia, estaba recordándola...\"},{\"heading\":false,\"text\":\"—Pues si quieres volver a tenerla, ¡cásate, Augusto, cásate!\"},{\"heading\":false,\"text\":\"—No, aquélla no, aquélla no la volveré a tener.\"},{\"heading\":false,\"text\":\"—Es verdad, pero ¡cásate!\"},{\"heading\":false,\"text\":\"—¿Y cómo?—añadió Augusto con una forzada sonrisa y recordando lo que había oído de una de las doctrinas de don Avito—¿cómo? ¿deductiva o inductivamente?\"},{\"heading\":false,\"text\":\"—¡Déjate ahora de esas cosas; por Dios, Augusto, no me recuerdes tragedias! Pero... en fin, si te he de seguir el humor, ¡cásate intuitivamente!\"},{\"heading\":false,\"text\":\"—¿Y si la mujer a quien quiero no me quiere?\"},{\"heading\":false,\"text\":\"—Cásate con la mujer que te quiera, aunque no la quieras tú. Es mejor casarse para que le conquisten a uno el amor que para conquistarlo. Busca una que te quiera.\"},{\"heading\":false,\"text\":\"Por la mente de Augusto pasó en rapidísima visión la imagen de la chica de la planchadora. Porque se había hecho la ilusión de que aquella pobrecita quedó enamorada de él.\"},{\"heading\":false,\"text\":\"Cuando al cabo Augusto se despidió de don Avito dirigióse al Casino. Quería despejar la niebla de su cabeza y la de su corazón echando una partida de ajedrez con Víctor.\"}]},{\"title\":\"Capítulo XIV\",\"blocks\":[{\"heading\":false,\"text\":\"Notó Augusto que algo insólito le ocurría a su amigo Víctor; no acertaba ninguna jugada, estaba displicente y silencioso.\"},{\"heading\":false,\"text\":\"—Víctor, algo te pasa...\"},{\"heading\":false,\"text\":\"—Sí, hombre, sí, me pasa una cosa grave. Y como necesito desahogo, vamos fuera; la noche está muy hermosa; te lo contaré.\"},{\"heading\":false,\"text\":\"Víctor, aunque el más íntimo amigo de Augusto, le llevaba cinco o seis años de edad y hacía más de doce que estaba casado, pues contrajo matrimonio siendo muy joven, por deber de conciencia, según decían. No tenía hijos.\"},{\"heading\":false,\"text\":\"Cuando estuvieron en la calle, Víctor comenzó:\"},{\"heading\":false,\"text\":\"—Ya sabes, Augusto, que me tuve que casar muy joven...\"},{\"heading\":false,\"text\":\"—¿Que te tuviste que casar?\"},{\"heading\":false,\"text\":\"—Sí, vamos, no te hagas el de nuevas, que la murmuración llega a todos. Nos casaron nuestros padres, los míos y los de mi Elena, cuando éramos unos chiquillos. Y el matrimonio fué para nosotros un juego. Jugábamos a marido y mujer. Pero aquello fué una falsa alarma...\"},{\"heading\":false,\"text\":\"—¿Qué es lo que fué una falsa alarma?\"},{\"heading\":false,\"text\":\"—Pues aquello por que nos casaron. Pudibundeces de nuestros sendos padres. Se enteraron de un desliz nuestro, que tuvo su cachito de escándalo, y sin esperar a ver qué consecuencias tenía, o si las tenía, nos casaron.\"},{\"heading\":false,\"text\":\"—Hicieron bien.\"},{\"heading\":false,\"text\":\"—No diré yo tanto. Mas el caso fué que ni tuvo consecuencias aquel desliz ni las tuvieron los consiguientes deslices de después de casados.\"},{\"heading\":false,\"text\":\"—¿Deslices?\"},{\"heading\":false,\"text\":\"—Sí, en nuestro caso no eran sino deslices. Nos deslizábamos. Ya te he dicho que jugábamos a marido y mujer...\"},{\"heading\":false,\"text\":\"—¡Hombre!\"},{\"heading\":false,\"text\":\"—No, no seas demasiado malicioso. Eramos y aún somos jóvenes para pervertirnos. Pero en lo que menos pensábamos era en constituir un hogar. Eramos dos mozuelos que vivían juntos haciendo eso que se llama vida marital. Pero pasó el año y al ver que no venía fruto empezamos a ponernos de morro, a mirarnos un poco de reojo, a incriminarnos mutuamente en silencio. Yo no me avenía a no ser padre. Era un hombre ya, tenía más de veintiún años, y, francamente, eso de que yo fuese menos que otros, menos que cualquier bárbaro que a los nueve meses justos de haberse casado, o antes, tiene su primer hijo... a esto no me resignaba.\"},{\"heading\":false,\"text\":\"—Pero, hombre, ¿qué culpa...?\"},{\"heading\":false,\"text\":\"—Y, es claro, yo, aun sin decírselo, le echaba la culpa a ella y me decía: «Esta mujer es estéril y te pone en ridículo». Y ella, por su parte, no me cabía duda, me culpaba a mí, y hasta suponía, qué sé yo...\"},{\"heading\":false,\"text\":\"—¿Qué?\"},{\"heading\":false,\"text\":\"—Nada, que cuando pasa un año y otro y otro y el matrimonio no tiene hijos, la mujer da en pensar que la culpa es del marido y que lo es porque no fué sano al matrimonio, porque llevó cualquier dolencia... El caso es que nos sentíamos enemigos el uno del otro; que el demonio se nos había metido en casa. Y al fin estalló el tal demonio y llegaron las reconvenciones mutuas y aquello de «tú no sirves» y «quien no sirve eres tú» y todo lo demás.\"},{\"heading\":false,\"text\":\"—¿Sería por eso que hubo una temporada, a los dos o tres años de haberte casado, que anduviste tan malo, tan preocupado, neurasténico? ¿cuando tuviste que ir solo a aquel sanatorio?\"},{\"heading\":false,\"text\":\"—No, no fué eso... fué algo peor.\"},{\"heading\":false,\"text\":\"Hubo un silencio. Víctor miraba al suelo.\"},{\"heading\":false,\"text\":\"—Bueno, bueno, guárdatelo; no quiero romper tus secretos.\"},{\"heading\":false,\"text\":\"—¡Pues sea, te lo diré! Fué que exacerbado por aquellas querellas intestinas con mi pobre mujer, llegué a imaginarme que la cuestión dependía no de la intensidad o de lo que sea, sino del número, ¿me entiendes?\"},{\"heading\":false,\"text\":\"—Sí, creo entenderte...\"},{\"heading\":false,\"text\":\"—Y di en dedicarme a comer como un bárbaro lo que creí más sustancioso y nutritivo y bien sazonado con todo género de especias, en especial las que pasan por más afrodisíacas, y a frecuentar lo más posible a mi mujer. Y, claro...\"},{\"heading\":false,\"text\":\"—Te pusiste enfermo.\"},{\"heading\":false,\"text\":\"—¡Natural! Y si no acudo a tiempo y entramos en razón me las lío al otro mundo. Pero curé de aquello en ambos sentidos, volví a mi mujer y nos calmamos y resignamos. Y poco a poco volvió a reinar en casa no ya la paz, sino hasta la dicha. Al principio de esta nueva vida, a los cuatro o cinco años de casados, lamentábamos alguna que otra vez nuestra soledad, pero muy pronto no sólo nos consolamos, sino que nos habituamos. Y acabamos no sólo por no echar de menos a los hijos, sino hasta por compadecer a los que los tienen. Nos habituamos uno a otro, nos hicimos el uno costumbre del otro. Tú no puedes entender esto...\"},{\"heading\":false,\"text\":\"—No, no lo entiendo.\"},{\"heading\":false,\"text\":\"—Pues bien; yo me hice una costumbre de mi mujer y Elena se hizo una costumbre mía. Todo estaba moderadamente regularizado en nuestra casa, todo, lo mismo que las comidas. A las doce en punto, ni minuto más ni minuto menos, la sopa en la mesa, y de tal modo, que comemos todos los días casi las mismas cosas, en el mismo orden y en la misma cantidad. Aborrezco el cambio y lo aborrece Elena. En mi casa se vive al reló.\"},{\"heading\":false,\"text\":\"—Vamos, sí, esto me recuerda lo que dice nuestro amigo Luis del matrimonio Romera, que suele decir que son marido y mujer solterones.\"},{\"heading\":false,\"text\":\"—En efecto, porque no hay solterón más solterón y recalcitrante que el casado sin hijos. Una vez, para suplir la falta de hijos, que al fin y al cabo ni en mí había muerto el sentimiento de la paternidad ni menos el de la maternidad en ella, adoptamos, o si quieres prohijamos, un perro; pero al verle un día morir a nuestra vista, porque se le atravesó un hueso en la garganta, y ver aquellos ojos húmedos que parecían suplicarnos vida, nos entró una pena y un horror tal que no quisimos más perros ni cosa viva. Y nos contentamos con unas muñecas, unas grandes peponas, que son las que has visto en casa, y que mi Elena viste y desnuda.\"},{\"heading\":false,\"text\":\"—Esas no se os morirán.\"},{\"heading\":false,\"text\":\"—En efecto. Y todo iba muy bien y nosotros contentísimos. Ni me turban el sueño llantos de niño, ni tenía que preocuparme de si será varón o hembra y qué he de hacer de él o de ella... Y, además, he tenido siempre mi mujer a mi disposición, cómodamente, sin estorbos de embarazos ni de lactancias; en fin, ¡un encanto de vida!\"},{\"heading\":false,\"text\":\"—¿Sabes que eso en poco o nada se diferencia...?\"},{\"heading\":false,\"text\":\"—¿De qué? ¿De un arrimo ilegal? Así lo creo. Un matrimonio sin hijos puede llegar a convertirse en una especie de concubinato legal, muy bien ordenado, muy higiénico, relativamente casto, pero, en fin, ¡lo dicho! Marido y mujer solterones, pero solterones arrimados, en efecto. Y así han transcurrido estos más de once años, van para doce... Pero ahora... ¿sabes lo que me pasa?\"},{\"heading\":false,\"text\":\"—Hombre, ¿cómo lo he de saber?\"},{\"heading\":false,\"text\":\"—Pero ¿no sabes lo que me pasa?\"},{\"heading\":false,\"text\":\"—Como no sea que has dejado encinta a tu mujer...\"},{\"heading\":false,\"text\":\"—Eso, hombre, eso. ¡Figúrate qué desgracia!\"},{\"heading\":false,\"text\":\"—¿Desgracia? ¿Pues no lo deseasteis tanto...?\"},{\"heading\":false,\"text\":\"—Sí, al principio, los dos o tres primeros años, poco más. Pero ahora, ahora... Ha vuelto el demonio a casa, han vuelto las disensiones. Y ahora como antaño cada uno de nosotros culpaba al otro de la esterilidad del lazo, ahora cada uno culpa al otro de esto que se nos viene. Y ya empezamos a llamarle... no, no te lo digo...\"},{\"heading\":false,\"text\":\"—Pues no me lo digas si no quieres.\"},{\"heading\":false,\"text\":\"—Empezamos a llamarle ¡el intruso! Y yo he soñado que se nos moría una mañana con un hueso atravesado en la garganta...\"},{\"heading\":false,\"text\":\"—¡Qué barbaridad!\"},{\"heading\":false,\"text\":\"—Sí, tienes razón, una barbaridad. Y ¡adiós regularidad, adiós comodidad, adiós costumbres! Todavía ayer estaba Elena de vómitos; parece que es una de las molestias anejas al estado que llaman... ¡interesante! ¡Interesante! ¡Interesante! ¡Vaya un interés! ¡De vómito! ¿Has visto nada más indecoroso, nada más sucio?\"},{\"heading\":false,\"text\":\"—Pero ¿ella estará gozosísima al sentirse madre?\"},{\"heading\":false,\"text\":\"—¿Ella? ¡Como yo! Esto es una mala jugada de la Providencia, de la Naturaleza o de quien sea, una burla. Si hubiera venido... el nene o nena, lo que fuere... si hubiera venido cuando, inocentes tórtolos llenos, más que de amor paternal, de vanidad, le esperábamos; si hubiera venido cuando creíamos que el no tener hijos era ser menos que otros; si hubiera venido entonces, ¡santo y muy bueno!, pero ¿ahora, ahora? Te digo que esto es una burla. Si no fuera por...\"},{\"heading\":false,\"text\":\"—¿Qué, hombre, qué?\"},{\"heading\":false,\"text\":\"—Te lo regalaba, para que hiciese compañía a Orfeo.\"},{\"heading\":false,\"text\":\"—Hombre, cálmate y no digas disparates...\"},{\"heading\":false,\"text\":\"—Tienes razón, disparato. Perdóname. Pero ¿te parece bien, al cabo de cerca de doce años, cuando nos iba tan ricamente, cuando estábamos curados de la ridícula vanidad de los recién casados, venirnos esto? Es claro, ¡vivíamos tan tranquilos, tan seguros, tan confiados...!\"},{\"heading\":false,\"text\":\"—¡Hombre, hombre!\"},{\"heading\":false,\"text\":\"—Tienes razón, sí, tienes razón. Y lo más terrible es, ¿a que no te figuras?, que mi pobre Elena no puede defenderse del sentimiento del ridículo que la asalta. ¡Se siente en ridículo!\"},{\"heading\":false,\"text\":\"—Pues no veo...\"},{\"heading\":false,\"text\":\"—No, tampoco yo lo veo, pero así es; se siente en ridículo. Y hace tales cosas que temo por el... intruso... o intrusa.\"},{\"heading\":false,\"text\":\"—¡Hombre!—exclamó Augusto alarmado.\"},{\"heading\":false,\"text\":\"—¡No, no, Augusto, no, no! No hemos perdido el sentido moral, y Elena, que es como sabes profundamente religiosa, acata, aunque a regañadientes, los designios de la Providencia y se resigna a ser madre. Y será buena madre, no me cabe de ello duda, muy buena madre. Pero es tal el sentimiento del ridículo en ella, que para ocultar su estado, para encubrir su embarazo, la creo capaz de cosas que... En fin, no quiero pensar en ello. Por de pronto, hace ya una semana que no sale de casa; dice que le da vergüenza, que se le figura que van a quedársela todos mirándola en la calle. Y ya habla de que nos vayamos, de que si ella ha de salir a tomar el aire y el sol cuando esté ya en meses mayores, no ha de hacerlo donde haya gentes que la conozcan y que acaso vayan a felicitarle por ello.\"},{\"heading\":false,\"text\":\"Callaron los dos amigos un rato, y después que el breve silencio selló el relato dijo Víctor.\"},{\"heading\":false,\"text\":\"—Conque ¡anda, Augusto, anda y cásate, para que acaso te suceda algo por el estilo; anda y cásate con la pianista!\"},{\"heading\":false,\"text\":\"—Y ¡quién sabe...!—dijo Augusto como quien habla consigo mismo—¡quién sabe...! Acaso casándome volveré a tener madre...\"},{\"heading\":false,\"text\":\"—Madre, sí—añadió Víctor—, ¡de tus hijos! Si los tienes...\"},{\"heading\":false,\"text\":\"—¡Y madre mía! Acaso ahora, Víctor, empieces a tener en tu mujer una madre, una madre tuya.\"},{\"heading\":false,\"text\":\"—Lo que voy a empezar ahora es a perder noches...\"},{\"heading\":false,\"text\":\"—O a ganarlas, Víctor, o a ganarlas.\"},{\"heading\":false,\"text\":\"—En fin, que no sé lo que me pasa, ni lo que nos pasa. Y yo por mí creo que llegaría a resignarme; pero mi Elena, mi pobre Elena... ¡Pobrecita!\"},{\"heading\":false,\"text\":\"—¿Ves? Ya empiezas a compadecerla.\"},{\"heading\":false,\"text\":\"—En fin, Augusto, ¡que pienses mucho antes de casarte!\"},{\"heading\":false,\"text\":\"Y se separaron.\"},{\"heading\":false,\"text\":\"Augusto entró en su casa llena la cabeza de cuanto había oído a don Avito y a Víctor. Apenas se acordaba ya ni de Eugenia ni de la hipoteca liberada, ni de la mozuela de la planchadora.\"},{\"heading\":false,\"text\":\"Cuando al entrar en casa salió saltando a recibirle Orfeo, le cojió, le tentó bien el gaznate, y apretándole al seno le dijo: «Cuidado con los huesos, Orfeo, mucho cuidadito con ellos, ¿eh? No quiero que te atragantes con uno; no quiero verte morir a mis ojos suplicándome vida. Ya ves, Orfeo, don Avito, el pedagogo, se ha convertido a la religión de sus abuelos... ¡es la herencia! Y Víctor no se resigna a ser padre. Aquél no se consuela de haber perdido a su hijo y éste no se consuela de ir a tenerlo. Y ¡qué ojos, Orfeo, qué ojos! ¡Cómo le fulguraban cuando me dijo: “¡Quiere usted comprarme! ¡quiere usted comprar no mi amor, que ése no se compra, sino mi cuerpo! ¡Quédese con mi casa!” ¡Comprar yo su cuerpo... su cuerpo...! ¡Si me sobra el mío, Orfeo, me sobra el mío! Lo que yo necesito es alma, alma, alma. Y una alma de fuego, como la que irradia de los ojos de ella, de Eugenia. ¡Su cuerpo... su cuerpo... sí, su cuerpo es magnífico, espléndido, divino; pero es que su cuerpo es alma, alma pura, todo él vida, todo él significación, todo él idea! A mí me sobra el cuerpo, Orfeo, me sobra el cuerpo porque me falta alma. O ¿no es más bien que me falta alma porque me sobra cuerpo? Yo me toco el cuerpo, Orfeo, me lo palpo, me lo veo, pero ¿el alma?, ¿dónde está mi alma? ¿es que la tengo? Sólo la sentí resollar un poco cuando tuve aquí abrazada, sobre mis rodillas, a Rosario, a la pobre Rosarito; cuando ella lloraba y lloraba yo. Aquellas lágrimas no podían salir de mi cuerpo; salían de mi alma. El alma es un manantial que sólo se revela en lágrimas. Hasta que se llora de veras no se sabe si se tiene o no alma. Y ahora vamos a dormir, Orfeo, si es que nos dejan.»\"}]},{\"title\":\"Capítulo XV\",\"blocks\":[{\"heading\":false,\"text\":\"—Pero ¿qué has hecho, chiquilla?—preguntaba doña Ermelinda a su sobrina.\"},{\"heading\":false,\"text\":\"—¿Qué he hecho? Lo que usted, si es que tiene vergüenza, habría hecho en mi caso; estoy de ello segura. ¡Querer comprarme! ¡querer comprarme a mí!\"},{\"heading\":false,\"text\":\"—Mira, chiquilla, es siempre mucho mejor que quieran comprarla a una que no es el que quieran venderla, no lo dudes.\"},{\"heading\":false,\"text\":\"—¡Querer comprarme! ¡querer comprarme a mí!\"},{\"heading\":false,\"text\":\"—Pero si no es eso, Eugenia, si no es eso. Lo ha hecho por generosidad, por heroísmo...\"},{\"heading\":false,\"text\":\"—No quiero héroes. Es decir, los que procuran serlo. Cuando el heroísmo viene por sí, naturalmente, ¡bueno!; pero ¿por cálculo? ¡Querer comprarme! ¡querer comprarme a mí, a mí! Le digo a usted, tía, que me la ha de pagar. Me la ha de pagar ese...\"},{\"heading\":false,\"text\":\"—¿Ese... qué? ¡Vamos, acaba!\"},{\"heading\":false,\"text\":\"—Ese... panoli desaborido. Y para mí como si no existiera. ¡Como que no existe!\"},{\"heading\":false,\"text\":\"—Pero qué tonterías estás diciendo...\"},{\"heading\":false,\"text\":\"—¿Es que cree usted, tía, que ese tío...?\"},{\"heading\":false,\"text\":\"—¿Quién, Fermín?\"},{\"heading\":false,\"text\":\"—No, ése... ese del canario, ¿tiene algo dentro?\"},{\"heading\":false,\"text\":\"—Tendrá por lo menos sus entrañas...\"},{\"heading\":false,\"text\":\"—Pero ¿usted cree que tiene entrañas? ¡Quia! ¡Si es hueco, como si lo viera, hueco!\"},{\"heading\":false,\"text\":\"—Pero ven acá, chiquilla, hablemos fríamente y no digas ni hagas tonterías. Olvida eso. Yo creo que debes aceptarle...\"},{\"heading\":false,\"text\":\"—Pero si no le quiero, tía...\"},{\"heading\":false,\"text\":\"—Y tú ¿qué sabes lo que es querer? Careces de experiencia. Tú sabrás lo que es una fusa o una corchea, pero lo que es querer...\"},{\"heading\":false,\"text\":\"—Me parece, tía, que está usted hablando por hablar...\"},{\"heading\":false,\"text\":\"—¿Qué sabes tú lo que es querer, chiquilla?\"},{\"heading\":false,\"text\":\"—Pero si quiero a otro...\"},{\"heading\":false,\"text\":\"—¿A otro? ¿A ese gandul de Mauricio, a quien se le pasea el alma por el cuerpo? ¿A eso le llamas querer? ¿a eso le llamas otro? Augusto es tu salvación y sólo Augusto. ¡Tan fino, tan rico, tan bueno...!\"},{\"heading\":false,\"text\":\"—Pues por eso no le quiero, porque es tan bueno como usted dice. No me gustan los hombres buenos.\"},{\"heading\":false,\"text\":\"—Ni a mí, hija, ni a mí, pero...\"},{\"heading\":false,\"text\":\"—¿Pero qué?\"},{\"heading\":false,\"text\":\"—Que hay que casarse con ellos. Para eso han nacido y son buenos, para maridos.\"},{\"heading\":false,\"text\":\"—Pero si no le quiero, ¿cómo he de casarme con él?\"},{\"heading\":false,\"text\":\"—¿Cómo? ¡casándote! ¿No me casé yo con tu tío...?\"},{\"heading\":false,\"text\":\"—Pero, tía...\"},{\"heading\":false,\"text\":\"—Sí, ahora creo que sí, me parece que sí; pero cuando me casé no sé si le quería. Mira, eso del amor es una cosa de libros, algo que se ha inventado no más que para hablar y escribir de ello. Tonterías de poetas. Lo positivo es el matrimonio. El Código civil no habla del amor y sí del matrimonio. Todo eso del amor no es más que música...\"},{\"heading\":false,\"text\":\"—¿Música?\"},{\"heading\":false,\"text\":\"—Música, sí. Y ya sabes que la música apenas sirve sino para vivir de enseñarla, y que si no te aprovechas de una ocasión como esta que se te presenta vas a tardar en salir de tu purgatorio...\"},{\"heading\":false,\"text\":\"—Y ¿qué? ¿Les pido yo a ustedes algo? ¿No me gano por mí mi vida? ¿Les soy gravosa?\"},{\"heading\":false,\"text\":\"—No te sulfures así, polvorilla, ni digas esas cosas, porque vamos a reñir de veras. Nadie te habla de eso. Y todo lo que te digo y aconsejo es por tu bien.\"},{\"heading\":false,\"text\":\"—Sí, por mi bien... por mi bien... Por mi bien ha hecho el señor don Augusto Pérez esa hombrada, por mi bien... ¡Una hombrada, sí, una hombrada! ¡Quererme comprar...! ¡Quererme comprar a mí... a mí! ¡Una hombrada, lo dicho, una hombrada... una cosa de hombre! Los hombres, tía, ya lo voy viendo, son unos groseros, unos brutos, carecen de delicadeza. No saben hacer ni un favor sin ofender...\"},{\"heading\":false,\"text\":\"—¿Todos?\"},{\"heading\":false,\"text\":\"—¡Todos, sí, todos! Los que son de veras hombres se entiende.\"},{\"heading\":false,\"text\":\"—¡Ah!\"},{\"heading\":false,\"text\":\"—Sí, porque los otros, los que no son groseros y brutos y egoístas, no son hombres.\"},{\"heading\":false,\"text\":\"—Pues ¿qué son?\"},{\"heading\":false,\"text\":\"—¡Qué sé yo... maricas!\"},{\"heading\":false,\"text\":\"—¡Vaya unas teorías, chiquilla!\"},{\"heading\":false,\"text\":\"—En esta casa hay que contagiarse.\"},{\"heading\":false,\"text\":\"—Pero eso no se lo has oído nunca a tu tío.\"},{\"heading\":false,\"text\":\"—No, se me ha ocurrido a mí observando a los hombres.\"},{\"heading\":false,\"text\":\"—¿También a tu tío?\"},{\"heading\":false,\"text\":\"—Mi tío no es un hombre... de esos.\"},{\"heading\":false,\"text\":\"—Entonces es un marica, ¿eh?, un marica. ¡Vamos, habla!\"},{\"heading\":false,\"text\":\"—No, no, no, tampoco. Mi tío es... vamos... mi tío... No me acostumbro del todo a que sea algo así... vamos... de carne y hueso.\"},{\"heading\":false,\"text\":\"—Pues ¿qué, qué crees de tu tío?\"},{\"heading\":false,\"text\":\"—Que no es más que... no sé como decirlo... que no es más que mi tío. Vamos, así como si no existiese de verdad.\"},{\"heading\":false,\"text\":\"—Eso te creerás tú, chiquilla. Pero yo te digo que tu tío existe, ¡vaya si existe!\"},{\"heading\":false,\"text\":\"—Brutos, todos brutos, brutos todos. ¿No sabe usted lo que ese bárbaro de Martín Rubio le dijo al pobre don Emeterio a los pocos días de quedarse éste viudo?\"},{\"heading\":false,\"text\":\"—No lo he oído, creo.\"},{\"heading\":false,\"text\":\"—Pues verá usted; fué cuando la epidemia aquella, ya sabe usted. Todo el mundo estaba alarmadísimo, a mí no me dejaron ustedes salir de casa en una porción de días y hasta tomaba el agua hervida. Todos huían los unos de los otros, y si se veía a alguien de luto reciente era como si estuviese apestado. Pues bien; a los cinco o seis días de haber enviudado el pobre don Emeterio tuvo que salir de casa, de luto por supuesto, y se encontró de manos a boca con ese bárbaro de Martín. Este, al verle de luto, se mantuvo a cierta prudente distancia de él, como temiendo el contagio, y le dijo: «Pero, hombre, ¿qué es eso? ¿alguna desgracia en tu casa?» «Sí—le contestó el pobre don Emeterio—, acabo de perder a mi pobre mujer...» «¡Lástima! Y ¿cómo, cómo ha sido eso?» «De sobreparto»—le dijo don Emeterio. «¡Ah, menos mal!»—le contestó el bárbaro de Martín, y entonces se le acercó a darle la mano. ¡Habráse visto caballería mayor...! ¡Una hombrada! Le digo a usted que son unos brutos, nada más que unos brutos.\"},{\"heading\":false,\"text\":\"—Y es mejor que sean unos brutos que no unos holgazanes como, por ejemplo, ese zanguango de Mauricio, que te tiene, yo no sé por qué, sorbido el seso... Porque según mis informes, y son de buena tinta, te lo aseguro, maldito si el muy bausán está de veras enamorado de ti...\"},{\"heading\":false,\"text\":\"—¡Pero lo estoy yo de él y basta!\"},{\"heading\":false,\"text\":\"—Y ¿te parece que ése... tu novio quiero decir... es de veras hombre? Si fuese hombre, hace tiempo que habría buscado salida y trabajo.\"},{\"heading\":false,\"text\":\"—Pues si no es hombre, quiero yo hacerle tal. Es verdad, tiene el defecto que usted dice, tía, pero acaso es por eso por lo que le quiero. Y ahora, después de la hombrada de don Augusto... ¡quererme comprar a mí, a mí!... después de eso estoy decidida a jugarme el todo por el todo casándome con Mauricio.\"},{\"heading\":false,\"text\":\"—Y ¿de qué vais a vivir, desgraciada?\"},{\"heading\":false,\"text\":\"—¡De lo que yo gane! Trabajaré, y más que ahora. Aceptaré lecciones que he rechazado. Así como así, he renunciado ya a esa casa, se la he regalado a don Augusto. Era un capricho, nada más que un capricho. Es la casa en que nací. Y ahora, libre ya de esa pesadilla de la casa y de su hipoteca, me pondré a trabajar con más ahinco. Y Mauricio, viéndome trabajar para los dos, no tendrá más remedio que buscar trabajo y trabajar él. Es decir, si tiene vergüenza...\"},{\"heading\":false,\"text\":\"—¿Y si no la tiene?\"},{\"heading\":false,\"text\":\"—Pues si no la tiene... ¡dependerá de mí!\"},{\"heading\":false,\"text\":\"—Sí, ¡el marido de la pianista!\"},{\"heading\":false,\"text\":\"—Y aunque así sea. Será mío, mío, y cuanto más de mí dependa, más mío.\"},{\"heading\":false,\"text\":\"—Sí, tuyo... pero como puede serlo un perro. Y eso se llama comprar un hombre.\"},{\"heading\":false,\"text\":\"—¿No ha querido un hombre, con su capital, comprarme? Pues ¿qué de extraño tiene que yo, una mujer, quiera, con mi trabajo, comprar un hombre?\"},{\"heading\":false,\"text\":\"—Todo esto que estás diciendo, chiquilla, se parece mucho a eso que tu tío llama feminismo.\"},{\"heading\":false,\"text\":\"—No sé, ni me importa saberlo. Pero le digo a usted, tía, que todavía no ha nacido el hombre que me pueda comprar a mí. ¿A mí? ¿a mí? ¿comprarme a mí?\"},{\"heading\":false,\"text\":\"En este punto de la conversación entró la criada a anunciar que don Augusto esperaba a la señora.\"},{\"heading\":false,\"text\":\"—¿Él? ¡vete! Yo no quiero verle. Dile que le he dicho ya mi última palabra.\"},{\"heading\":false,\"text\":\"—Reflexiona un poco, chiquilla, cálmate; no lo tomes así. Tú no has sabido interpretar las intenciones de don Augusto.\"},{\"heading\":false,\"text\":\"Cuando Augusto se encontró ante doña Ermelinda empezó a darle sus excusas. Estaba, según decía, profundamente afectado; Eugenia no había sabido interpretar sus verdaderas intenciones. Él, por su parte, había cancelado formalmente la hipoteca de la casa y ésta aparecía legalmente libre de semejante carga y en poder de su dueña. Y si ella se obstinaba en no recibir las rentas, él, por su parte, tampoco podía hacerlo; de manera que aquello se perdería sin provecho para nadie, o mejor dicho, iría depositándose a nombre de su dueña. Además, él renunciaba a sus pretensiones a la mano de Eugenia y sólo quería que ésta fuese feliz; hasta se hallaba dispuesto a buscar una buena colocación a Mauricio para que no tuviese que vivir de las rentas de su mujer.\"},{\"heading\":false,\"text\":\"—¡Tiene usted un corazón de oro!—exclamó doña Ermelinda.\"},{\"heading\":false,\"text\":\"—Ahora sólo falta, señora, que convenza a su sobrina de cuáles han sido mis verdaderas intenciones, y que si lo de deshipotecar la casa fué una impertinencia me la perdone. Pero me parece que no es cosa ya de volver atrás. Si ella quiere seré yo padrino de la boda. Y luego emprenderé un largo y lejano viaje.\"},{\"heading\":false,\"text\":\"Doña Ermelinda llamó a la criada, a la que dijo que llamase a Eugenia, pues don Augusto deseaba hablar con ella. «La señorita acaba de salir», contestó la criada.\"}]},{\"title\":\"Capítulo XVI\",\"blocks\":[{\"heading\":false,\"text\":\"—Eres imposible, Mauricio—le decía Eugenia a su novio, en el cuchitril aquel de la portería—, completamente imposible, y si sigues así, si no sacudes esa pachorra, si no haces algo para buscarte una colocación y que podamos casarnos, soy capaz de cualquier disparate.\"},{\"heading\":false,\"text\":\"—¿De qué disparate? Vamos, di, rica—y le acariciaba el cuello ensortijándose en uno de sus dedos un rizo de la nuca de la muchacha.\"},{\"heading\":false,\"text\":\"—Mira, si quieres, nos casamos así y yo seguiré trabajando... para los dos.\"},{\"heading\":false,\"text\":\"—Pero ¿y qué dirán de mí, mujer, si acepto semejante cosa?\"},{\"heading\":false,\"text\":\"—¿Y a mí qué me importa lo que de ti digan?\"},{\"heading\":false,\"text\":\"—¡Hombre, hombre, eso es grave!\"},{\"heading\":false,\"text\":\"—Sí, a mí no me importa eso; lo que yo quiero es que esto se acabe cuanto antes...\"},{\"heading\":false,\"text\":\"—¿Tan mal nos va?\"},{\"heading\":false,\"text\":\"—Sí, nos va mal, muy mal. Y si no te decides soy capaz de...\"},{\"heading\":false,\"text\":\"—¿De qué, vamos?\"},{\"heading\":false,\"text\":\"—De aceptar el sacrificio de don Augusto.\"},{\"heading\":false,\"text\":\"—¿De casarte con él?\"},{\"heading\":false,\"text\":\"—¡No, eso nunca! De recobrar mi finca.\"},{\"heading\":false,\"text\":\"—Pues ¡hazlo, rica, hazlo! Si ésa es la solución y no otra...\"},{\"heading\":false,\"text\":\"—Y te atreves...\"},{\"heading\":false,\"text\":\"—¡Pues no he de atreverme! Ese pobre don Augusto me parece a mí que no anda bien de la cabeza, y pues ha tenido ese capricho, no creo que debemos molestarle...\"},{\"heading\":false,\"text\":\"—De modo que tú...\"},{\"heading\":false,\"text\":\"—Pues ¡claro está, rica, claro está!\"},{\"heading\":false,\"text\":\"—Hombre al fin y al cabo.\"},{\"heading\":false,\"text\":\"—No tanto como tú quisieras, según te explicas. Pero ven acá...\"},{\"heading\":false,\"text\":\"—Vamos, déjame, Mauricio; ya te he dicho cien veces que no seas...\"},{\"heading\":false,\"text\":\"—Que no sea cariñoso...\"},{\"heading\":false,\"text\":\"—¡No, que no seas... bruto! Estate quieto. Y si quieres más confianzas sacude esa pereza, busca de veras trabajo, y lo demás ya lo sabes. Conque, a ver si tienes juicio, ¿eh? Mira que ya otra vez te di una bofetada.\"},{\"heading\":false,\"text\":\"—¡Y bien que me supo! ¡Anda, rica, dame otra! Mira, aquí tienes mi cara...\"},{\"heading\":false,\"text\":\"—No lo digas mucho...\"},{\"heading\":false,\"text\":\"—¡Anda, vamos!\"},{\"heading\":false,\"text\":\"—No, no quiero darte ese gusto.\"},{\"heading\":false,\"text\":\"—¿Ni otro?\"},{\"heading\":false,\"text\":\"—Te he dicho que no seas bruto. Y te repito que si no te das prisa a buscar trabajo soy capaz de aceptar eso.\"},{\"heading\":false,\"text\":\"—Pues bien, Eugenia, ¿quieres que te hable con el corazón en la mano, la verdad, toda la verdad?\"},{\"heading\":false,\"text\":\"—¡Habla!\"},{\"heading\":false,\"text\":\"—Yo te quiero mucho, pero mucho, estoy completamente chalado por ti, pero eso del matrimonio me asusta, me da un miedo atroz. Yo nací haragán por temperamento, no te lo niego; lo que más me molesta es tener que trabajar, y preveo que si nos casamos, y como supongo que tú querrás que tengamos hijos...\"},{\"heading\":false,\"text\":\"—¡Pues no faltaba más!\"},{\"heading\":false,\"text\":\"—Voy a tener que trabajar, y de firme, porque la vida es cara. Y eso de aceptar el que seas tú la que trabaje, ¡eso, nunca, nunca, nunca! Mauricio Blanco Clará no puede vivir del trabajo de una mujer. Pero hay acaso una solución que sin tener yo que trabajar ni tú se arregle todo...\"},{\"heading\":false,\"text\":\"—A ver, a ver...\"},{\"heading\":false,\"text\":\"—Pues... ¿me prometes, chiquilla, no incomodarte?\"},{\"heading\":false,\"text\":\"—¡Anda, habla!\"},{\"heading\":false,\"text\":\"—Por todo lo que yo sé y lo que te he oído, ese pobre don Augusto es un panoli, un pobre diablo; vamos, un...\"},{\"heading\":false,\"text\":\"—¡Anda, sigue!\"},{\"heading\":false,\"text\":\"—Pero no te me incomodarás.\"},{\"heading\":false,\"text\":\"—¡Que sigas te he dicho!\"},{\"heading\":false,\"text\":\"—Es, pues, como venía diciéndote, un... predestinado. Y acaso lo mejor sea no sólo que aceptes eso de tu casa, sino que...\"},{\"heading\":false,\"text\":\"—Vamos, ¿qué?\"},{\"heading\":false,\"text\":\"—Que le aceptes a él por marido.\"},{\"heading\":false,\"text\":\"—¿Eh?—y se puso ella en pie.\"},{\"heading\":false,\"text\":\"—Le aceptas, y como es un pobre hombre, pues... todo se arregla...\"},{\"heading\":false,\"text\":\"—¿Cómo que se arregla todo?\"},{\"heading\":false,\"text\":\"—Sí, él paga, y nosotros...\"},{\"heading\":false,\"text\":\"—Nosotros... ¿qué?\"},{\"heading\":false,\"text\":\"—Pues nosotros...\"},{\"heading\":false,\"text\":\"—¡Basta!\"},{\"heading\":false,\"text\":\"Y se salió Eugenia, con los ojos hechos un incendio y diciéndose: «Pero ¡qué brutos, qué brutos! Jamás lo hubiera creído... ¡Qué brutos!» Y al llegar a su casa se encerró en su cuarto y rompió a llorar. Y tuvo que acostarse presa de una fiebre.\"},{\"heading\":false,\"text\":\"Mauricio se quedó un breve rato como suspenso; mas pronto se repuso, encendió un cigarrillo, salió a la calle y le echó un piropo a la primera moza de garbo que pasó a su lado. Y aquella noche hablaba, con un amigo, de Don Juan Tenorio.\"},{\"heading\":false,\"text\":\"—A mí ese tío no acaba de convencerme—decía Mauricio—; eso no es más que teatro.\"},{\"heading\":false,\"text\":\"—¡Y que lo digas tú, Mauricio, que pasas por un Tenorio, por un seductor!\"},{\"heading\":false,\"text\":\"—¿Seductor? ¿seductor yo? ¡Qué cosas se inventan, Rogelio!\"},{\"heading\":false,\"text\":\"—¿Y lo de la pianista?\"},{\"heading\":false,\"text\":\"—¡Bah! ¿Quieres que te diga la verdad, Rogelio?\"},{\"heading\":false,\"text\":\"—¡Venga!\"},{\"heading\":false,\"text\":\"—Pues bien; de cada cien líos, más o menos honrados, y ese a que aludías es honradísimo, ¡eh!, de cada cien líos entre hombre y mujer, en más de noventa la seductora es ella y el seducido es él.\"},{\"heading\":false,\"text\":\"—Pues qué, ¿me negarás que has conquistado a la pianista, a la Eugenia?\"},{\"heading\":false,\"text\":\"—Sí, te lo niego; no soy yo quien la ha conquistado, sino ella quien me ha conquistado a mí.\"},{\"heading\":false,\"text\":\"—¡Seductor!\"},{\"heading\":false,\"text\":\"—Como quieras... Es ella, ella. No supe resistirme.\"},{\"heading\":false,\"text\":\"—Para el caso es igual...\"},{\"heading\":false,\"text\":\"—Pero me parece que eso se va a acabar y voy a encontrarme otra vez libre. Libre de ella, claro, porque no respondo de que me conquiste otra. ¡Soy tan débil! Si yo hubiera nacido mujer...\"},{\"heading\":false,\"text\":\"—Bueno, ¿y cómo se va a acabar?\"},{\"heading\":false,\"text\":\"—Porque... pues, ¡porque he metido la pata! Quise que siguiéramos, es decir, que empezáramos las relaciones, ¿entiendes?, sin compromiso ni consecuencias... y, ¡claro!, me parece que me va a dar soleta. Esa mujer quería absorberme.\"},{\"heading\":false,\"text\":\"—¡Y te absorberá!\"},{\"heading\":false,\"text\":\"—¡Quién sabe!... ¡Soy tan débil! Yo nací para que una mujer me mantenga, pero con dignidad, ¿sabes?, y si no, ¡nada!\"},{\"heading\":false,\"text\":\"—Y ¿a qué llamas dignidad? ¿puede saberse?\"},{\"heading\":false,\"text\":\"—¡Hombre, eso no se pregunta! Hay cosas que no pueden definirse.\"},{\"heading\":false,\"text\":\"—¡Es verdad!—contestó con profunda convicción Rogelio, añadiendo: Y si la pianista te deja, ¿qué vas a hacer?\"},{\"heading\":false,\"text\":\"—Pues quedar vacante. Y a ver si alguna otra me conquista. ¡He sido ya conquistado tantas veces...! Pero ésta, con eso de no ceder, de mantenerse siempre a honesta distancia, de ser honrada, en fin, porque como honrada lo es hasta donde la que más, con todo eso me tenía chaladito, pero del todo chaladito. Habría acabado por hacer de mí lo que hubiese querido. Y ahora, si me deja, lo sentiré, y mucho, pero me veré libre.\"},{\"heading\":false,\"text\":\"—¿Libre?\"},{\"heading\":false,\"text\":\"—Libre, sí, para otra.\"},{\"heading\":false,\"text\":\"—Yo creo que haréis las paces...\"},{\"heading\":false,\"text\":\"—¡Quién sabe!... Pero lo dudo, porque tiene un geniecito... Y hoy la ofendí, la verdad, la ofendí.\"}]},{\"title\":\"Capítulo XVII\",\"blocks\":[{\"heading\":false,\"text\":\"—¿Te acuerdas, Augusto—le decía Víctor—, de aquel don Eloíno Rodríguez de Alburquerque y Álvarez de Castro?\"},{\"heading\":false,\"text\":\"—¿Aquel empleado de Hacienda tan aficionado a correrla, sobre todo de lo baratito?\"},{\"heading\":false,\"text\":\"—El mismo. Pues bien... ¡se ha casado!\"},{\"heading\":false,\"text\":\"—¡Valiente carcamal se lleva la que haya cargado con él!\"},{\"heading\":false,\"text\":\"—Pero lo estupendo es su manera de casarse. Entérate y ve tomando notas. Ya sabrás que don Eloíno Rodríguez de Alburquerque y Álvarez de Castro, a pesar de sus apellidos, apenas si tiene sobre qué caerse muerto ni más que su sueldo en Hacienda, y que está, además, completamente averiado de salud.\"},{\"heading\":false,\"text\":\"—Tal vida ha llevado.\"},{\"heading\":false,\"text\":\"—Pues el pobre padece una afección cardíaca de la que no puede recobrarse. Sus días están contados. Acaba de salir de un achuchón gravísimo, que le ha puesto a las puertas de la muerte y le ha llevado al matrimonio, pero a otro... revienta. Es el caso que el pobre hombre andaba de casa en casa de huéspedes y de todas partes tenía que salir, porque por cuatro pesetas no pueden pedirse gollerías ni canguingos en mojo de gato y él era muy exigente. Y no del todo limpio. Y así rodando de casa en casa fué a dar a la de una venerable patrona, ya entrada en años, mayor que él, que, como sabes, más cerca anda de los sesenta que de los cincuenta, y viuda dos veces: la primera, de un carpintero que se suicidó tirándose de un andamio a la calle, y a quien recuerda a menudo como _su_ Rogelio, y la segunda, de un sargento de carabineros que le dejó al morir un capitalito que le da una peseta al día. Y hete aquí que hallándose en casa de esta señora viuda mi don Eloíno en ponerse malo, muy malo, tan malo que la cosa parecía sin remedio y que se moría. Llamaron primero a que le viera don José, y luego a don Valentín. Y el hombre, ¡a morir! Y su enfermedad pedía tantos y tales cuidados, y a las veces no del todo aseados, que monopolizaba a la patrona, y los otros huéspedes empezaban ya a amenazar con marcharse. Y don Eloíno que no podía pagar mucho más, y la doble viuda diciéndole que no podía tenerle más en su casa, pues le estaba perjudicando el negocio. «Pero ¡por Dios, señora, por caridad!—parece que le decía él—. ¿Adónde voy yo en este estado, en qué otra casa van a recibirme? Si usted me echa tendré que ir a morirme al hospital... ¡Por Dios, por caridad! ¡para los días que he de vivir...!» Porque él estaba convencido de que se moría y muy pronto. Pero ella, por su parte, lo que es natural, que su casa no era hospital, que vivía de su negocio y que se estaba ya perjudicando. Cuando en esto a uno de los compañeros de oficina de don Eloíno se le ocurre una idea salvadora y fué que le dijo: «Usted no tiene, don Eloíno, sino un medio de que esta buena señora se avenga a tenerle en su casa mientras viva». «¿Cuál?», preguntó él. «Primero—le dijo el amigo—sepamos lo que usted se cree de su enfermedad.» «Ah, pues yo, de que he de durar poco, muy poco; acaso no lleguen a verme con vida mis hermanos.» «¿Tan mal se cree usted?» «Me siento morir...» «Pues si así es, le queda un medio de conseguir que esta buena mujer no le ponga de patitas en la calle, obligándole a irse al Hospital.» «Y ¿cuál es?» «Casarse con ella.» «¿Casarme con ella? ¿con la patrona? ¿Quién, yo? ¡Un Rodríguez de Alburquerque y Álvarez de Castro! ¡Hombre, no estoy para bromas!» Y parece que la ocurrencia le hizo un efecto tal que a poco se queda en ella.\"},{\"heading\":false,\"text\":\"—Y no es para menos.\"},{\"heading\":false,\"text\":\"—Pero el amigo, así que él se repuso de la primera sorpresa, le hizo ver que casándose con la patrona le dejaba trece duros mensuales de viudedad, que de otro modo no aprovecharía nadie y se irían al Estado. Ya ves tú...\"},{\"heading\":false,\"text\":\"—Sí, sé de más de uno, amigo Víctor, que se ha casado nada más que para que el Estado no se ahorrase una viudedad. ¡Eso es civismo!\"},{\"heading\":false,\"text\":\"—Pero si don Eloíno rechazó indignado tal proposición, figúrate lo que diría la patrona: «¿Yo? ¿Casarme yo, a mis años, y por tercera vez, con ese carcamal? ¡Qué asco!» Pero se informó del médico, le aseguraron que no le quedaban a don Eloíno sino muy pocos días de vida, y diciendo: «La verdad es que trece duros al mes me arreglan», acabó aceptándolo. Y entonces se le llamó al párroco, al bueno de don Matías, varón apostólico, como sabes, para que acabase de convencer al desahuciado. «Sí, sí, sí—dijo don Matías—; sí, ¡pobrecito! ¡pobrecito!» Y le convenció. Llamó luego don Eloíno a Correíta y dicen que le dijo que quería reconciliarse con él—estaban reñidos—, y que fuese testigo de su boda. «Pero ¿se casa usted, don Eloíno?» «Sí, Correíta, sí, ¡me caso con la patrona! ¡con doña Sinfo!; ¡yo, un Rodríguez de Alburquerque y Álvarez de Castro, figúrate! Yo por que me cuide los pocos días de vida que me quedan... no sé si llegarán mis hermanos a tiempo de verme vivo... y ella por los trece duros de viudedad que le dejo.» Y cuentan que cuando Correíta se fué a su casa y se lo contó todo, como es natural, a su mujer, a Emilia, ésta exclamó: «Pero ¡tú eres un majadero, Pepe! ¿Por que no le dijiste que se casase con Encarna—Encarnación es una criada, ni joven ni guapa, que llevó Emilia como de dote a su matrimonio—, que le habría cuidado por los trece duros de viudedad tan bien como esa tía?» Y es fama que la Encarna añadió: «Tiene usted razón, señorita; también yo me hubiera casado con él y le habría cuidado lo que viviese, que no será mucho, por trece duros».\"},{\"heading\":false,\"text\":\"—Pero todo eso, Víctor, parece inventado.\"},{\"heading\":false,\"text\":\"—Pues no lo es. Hay cosas que no se inventan. Y aún falta lo mejor. Y me contaba don Valentín, que es después de don José quien ha estado tratando a don Eloíno, que al ir un día a verle y encontrarse con don Matías revestido, creyó que era para darle la Extremaunción al enfermo, y le dicen que estaba casándole. Y al volver más tarde le acompañó hasta la puerta la recién casada patrona, ¡por tercera vez!, y con voz compungida y ansiosa le preguntaba: «Pero, diga usted, don Valentín, ¿vivirá? ¿vivirá todavía?» «No, señora, no; es cuestión de días...» «Se morirá pronto, ¿eh?» «Sí, muy pronto.» «Pero ¿de verás, se morirá?»\"},{\"heading\":false,\"text\":\"—¡Qué enormidad!\"},{\"heading\":false,\"text\":\"—Y no es todo. Don Valentín ordenó que no se le diese al enfermo más que leche, y de ésta poquita de cada vez, pero doña Sinfo decía a otro huésped: «¡Quia! ¡yo le doy de todo lo que me pida! ¡A qué quitarle sus gustos si ha de vivir tan poco...!» Y luego ordenó que le diese unas ayudas, y ella decía: «¿Unas ayudas? ¡Uf, qué asco! ¿A este tío carcamal? ¡Yo no, yo no! ¡Si hubiese sido a alguno de los otros dos, a los que quería, con los que me casé por mi gusto! Pero ¿a éste? ¿unas ayudas? ¿Yo? ¡Como no...!»\"},{\"heading\":false,\"text\":\"—¡Todo esto es fantástico!\"},{\"heading\":false,\"text\":\"—No, es histórico. Y llegaron unos hermanos de don Eloíno, hermano y hermana, y él decía abrumado por la desgracia: «¡Casarse mi hermano, mi hermano, un Rodríguez de Alburquerque y Álvarez de Castro, con la patrona de la calle de Pellejeros! ¡mi hermano, hijo de un presidente que fué de la Audiencia de Zaragoza, de Za-ra-go-za, con una... doña Sinfo!» Estaba aterrado. Y la viuda del suicida y recién casada con el desahuciado se decía: «Y ahora verá usted, como si lo viera, ¡con esto de que somos cuñados se irán sin pagarme el pupilaje, cuando yo vivo de esto!» Y parece que le pagaron, sí, el pupilaje, y se lo pagó el marido, pero se llevaron un bastón de puño de oro que él tenía.\"},{\"heading\":false,\"text\":\"—¿Y murió?\"},{\"heading\":false,\"text\":\"—Sí, bastante después. Mejoró, mejoró bastante. Y ella, la patrona, decía: «De esto tiene la culpa ese don Valentín, que le ha entendido la enfermedad... Mejor era el otro, don José, que no se la entendía. Si sólo le hubiese tratado él, ya estaría muerto, y no que ahora me va a fastidiar». Ella, doña Sinfo, tiene, además de los hijos del primer marido, una hija del segundo, del carabinero, y a poco de haberse casado le decía don Eloíno: «Ven, ven acá; ven, ven que te dé un beso, que ya soy tu padre, eres hija mía...» «Hija, no—decía la madre—, ¡ahijada!» «¡Hijastra, señora, hijastra! Ven acá... os dejo bien...» Y es fama que la madre refunfuñaba: «¡Y el sinvergüenza no lo hacía más que para sobarla...! ¡Habráse visto...!» Y luego vino, como es natural, la ruptura. «Esto fué un engaño, nada más que un engaño, don Eloíno, porque si me casé con usted fué porque me aseguraron que usted se moría y muy pronto, que si no... ¡pa chasco! Me han engañado, me han engañado.» «También a mí me han engañado, señora. Y ¿qué quería usted que hubiese yo hecho? ¿Morirme por darle gusto?» «Eso era lo convenido.» «Ya me moriré, señora, ya me moriré... y antes que quisiera... ¡Un Rodríguez de Alburquerque y Álvarez de Castro!»\"},{\"heading\":false,\"text\":\"Y riñeron por cuestión de unos cuartos más o menos de pupilaje, y acabó ella por echarle de casa. «¡Adiós, don Eloíno, que le vaya a usted bien!» «Quede usted con Dios, doña Sinfo.» Y al fin se ha muerto el tercer marido de esta señora dejándola 2,15 pesetas diarias, y además le han dado 500 para lutos. Por supuesto, que no las ha empleado en tales lutos. A lo más le ha sacado un par de misas, por remordimiento y por gratitud a los trece duros de viudedad.\"},{\"heading\":false,\"text\":\"—Pero ¡qué cosas, Dios mío!\"},{\"heading\":false,\"text\":\"—Cosas que no se inventan, que no es posible inventar. Ahora estoy recojiendo más datos de esta tragicomedia, de esta farsa fúnebre. Pensé primero hacer de ello un sainete; pero considerándolo mejor he decidido meterlo de cualquier manera, como Cervantes metió en su _Quijote_ aquellas novelas que en él figuran, en una novela que estoy escribiendo para desquitarme de los quebraderos de cabeza que me da el embarazo de mi mujer.\"},{\"heading\":false,\"text\":\"—Pero ¿te has metido a escribir una novela?\"},{\"heading\":false,\"text\":\"—¿Y qué quieres que hiciese?\"},{\"heading\":false,\"text\":\"—¿Y cuál es su argumento, si se puede saber?\"},{\"heading\":false,\"text\":\"—Mi novela no tiene argumento, o mejor dicho, será el que vaya saliendo. El argumento se hace él solo.\"},{\"heading\":false,\"text\":\"—¿Y cómo es eso?\"},{\"heading\":false,\"text\":\"—Pues mira, un día de éstos que no sabía bien qué hacer, pero sentía ansia de hacer algo, una comezón muy íntima, un escarabajeo de la fantasía, me dije: voy a escribir una novela, pero voy a escribirla como se vive, sin saber lo que vendrá. Me senté, cojí unas cuartillas y empecé lo primero que se me ocurrió, sin saber lo que seguiría, sin plan alguno. Mis personajes se irán haciendo según obren y hablen, sobre todo según hablen; su carácter se irá formando poco a poco. Y a las veces su carácter será el de no tenerlo.\"},{\"heading\":false,\"text\":\"—Sí, como el mío.\"},{\"heading\":false,\"text\":\"—No sé. Ello irá saliendo. Yo me dejo llevar.\"},{\"heading\":false,\"text\":\"—¿Y hay psicología? ¿descripciones?\"},{\"heading\":false,\"text\":\"—Lo que hay es diálogo; sobre todo diálogo. La cosa es que los personajes hablen, que hablen mucho, aunque no digan nada.\"},{\"heading\":false,\"text\":\"—Eso te lo habrá insinuado Elena, ¿eh?\"},{\"heading\":false,\"text\":\"—¿Por qué?\"},{\"heading\":false,\"text\":\"—Porque una vez que me pidió una novela para matar el tiempo, recuerdo que me dijo que tuviese mucho diálogo y muy cortado.\"},{\"heading\":false,\"text\":\"—Sí, cuando en una que lee se encuentra con largas descripciones, sermones o relatos, los salta diciendo: ¡paja! ¡paja! ¡paja! Para ella sólo el diálogo no es paja. Y ya ves tú, puede muy bien repartirse un sermón en un diálogo...\"},{\"heading\":false,\"text\":\"—¿Y por qué será eso?...\"},{\"heading\":false,\"text\":\"—Pues porque a la gente le gusta la conversación por la conversación misma, aunque no diga nada. Hay quien no resiste un discurso de media hora y se está tres horas charlando en un café. Es el encanto de la conversación, de hablar por hablar, del hablar roto e interrumpido.\"},{\"heading\":false,\"text\":\"—También a mí el tono de discurso me carga...\"},{\"heading\":false,\"text\":\"—Sí, es la complacencia del hombre en el habla, y en el habla viva... Y sobre todo que parezca que el autor no dice las cosas por sí, no nos molesta con su personalidad, con su yo satánico. Aunque, por supuesto, todo lo que digan mis personajes lo digo yo...\"},{\"heading\":false,\"text\":\"—Eso hasta cierto punto...\"},{\"heading\":false,\"text\":\"—¿Cómo hasta cierto punto?\"},{\"heading\":false,\"text\":\"—Sí, que empezarás creyendo que los llevas tú, de tu mano, y es fácil que acabes convenciéndote de que son ellos los que te llevan. Es muy frecuente que un autor acabe por ser juguete de sus ficciones...\"},{\"heading\":false,\"text\":\"—Tal vez, pero el caso es que en esa novela pienso meter todo lo que se me ocurra, sea como fuere.\"},{\"heading\":false,\"text\":\"—Pues acabará no siendo novela.\"},{\"heading\":false,\"text\":\"—No, será... será... _nivola_.\"},{\"heading\":false,\"text\":\"—Y ¿qué es eso, qué es _nivola_?\"},{\"heading\":false,\"text\":\"—Pues le he oído contar a Manuel Machado, el poeta, el hermano de Antonio, que una vez le llevó a don Eduardo Benot, para leérselo, un soneto que estaba en alejandrinos o en no sé qué otra forma heterodoxa. Se lo leyó y don Eduardo le dijo: «Pero ¡eso no es soneto!...» «No, señor—le contestó Machado—, no es soneto, es... _sonite_.» Pues así con mi novela, no va a ser novela, sino... ¿cómo dije?, _navilo_... _nebulo_... no, no, _nivola_, eso es, _¡nivola!_ Así nadie tendrá derecho a decir que deroga las leyes de su género... Invento el género, e inventar un género no es más que darle un nombre nuevo, y le doy las leyes que me place. ¡Y mucho diálogo!\"},{\"heading\":false,\"text\":\"—¿Y cuándo un personaje se queda solo?\"},{\"heading\":false,\"text\":\"—Entonces... un monólogo. Y para que parezca algo así como diálogo invento un perro a quien el personaje se dirige.\"},{\"heading\":false,\"text\":\"—Sabes, Víctor, que se me antoja que me están inventando...\"},{\"heading\":false,\"text\":\"—¡Puede ser!\"},{\"heading\":false,\"text\":\"Al separarse uno de otro, Víctor y Augusto, iba diciéndose éste: «Y esta mi vida, ¿es novela, es nivola o qué es? Todo esto que me pasa y que les pasa a los que me rodean, ¿es realidad o es ficción? ¿No es acaso todo esto un sueño de Dios o de quien sea, que se desvanecerá en cuanto Él despierte, y por eso le rezamos y elevamos a Él cánticos e himnos, para adormecerle, para cunar su sueño? ¿No es acaso la liturgia toda de todas las religiones un modo de brezar el sueño de Dios y que no despierte y deje de soñarnos? ¡Ay, mi Eugenia! ¡mi Eugenia! Y mi Rosarito...»\"},{\"heading\":false,\"text\":\"—¡Hola, Orfeo!\"},{\"heading\":false,\"text\":\"Orfeo le había salido al encuentro, brincaba, le quería trepar piernas arriba. Cojióle y el animalito empezó a lamerle la mano.\"},{\"heading\":false,\"text\":\"—Señorito—le dijo Liduvina—, ahí le aguarda Rosarito con la plancha.\"},{\"heading\":false,\"text\":\"—¿Y cómo no la despachaste tú?\"},{\"heading\":false,\"text\":\"—Qué sé yo... Le dije que el señorito no podía tardar, que si quería aguardarse...\"},{\"heading\":false,\"text\":\"—Pero podías haberle despachado como otras veces...\"},{\"heading\":false,\"text\":\"—Sí, pero... en fin, usted me entiende...\"},{\"heading\":false,\"text\":\"—¡Liduvina! ¡Liduvina!\"},{\"heading\":false,\"text\":\"—Es mejor que la despache usted mismo.\"},{\"heading\":false,\"text\":\"—Voy allá.\"}]},{\"title\":\"Capítulo XVIII\",\"blocks\":[{\"heading\":false,\"text\":\"—¡Hola, Rosarito!—exclamó Augusto apenas la vio.\"},{\"heading\":false,\"text\":\"—Buenas tardes, don Augusto—y la voz de la muchacha era serena y clara y no menos clara y serena su mirada.\"},{\"heading\":false,\"text\":\"—¿Cómo no has despachado con Liduvina como otras veces en que yo no estoy en casa cuando llegas?\"},{\"heading\":false,\"text\":\"—¡No sé! Me dijo que me esperase. Creí que querría usted decirme algo...\"},{\"heading\":false,\"text\":\"«Pero ¿esto es ingenuidad o qué es?», pensó Augusto y se quedó un momento suspenso. Hubo un instante embarazoso, preñado de un inquieto silencio.\"},{\"heading\":false,\"text\":\"—Lo que quiero, Rosario, es que olvides lo del otro día, que no vuelvas a acordarte de ello, ¿entiendes?\"},{\"heading\":false,\"text\":\"—Bueno, como usted quiera...\"},{\"heading\":false,\"text\":\"—Sí, aquello fué una locura... una locura... no sabía bien lo que me hacía ni lo que decía... como no lo sé ahora...—e iba acercándose a la chica.\"},{\"heading\":false,\"text\":\"Esta le esperaba tranquilamente y como resignada. Augusto se sentó en un sofá, la llamó: ¡ven acá!, la dijo que se sentara, como la otra vez, sobre sus rodillas, y la estuvo un buen rato mirando a los ojos. Ella resistió tranquilamente aquella mirada, pero temblaba toda ella como la hoja de un chopo.\"},{\"heading\":false,\"text\":\"—¿Tiemblas, chiquilla...?\"},{\"heading\":false,\"text\":\"—¿Yo? Yo no. Me parece que es usted...\"},{\"heading\":false,\"text\":\"—No tiembles, cálmate.\"},{\"heading\":false,\"text\":\"—No vuelva a hacerme llorar...\"},{\"heading\":false,\"text\":\"—Vamos, sí, que quieres que te vuelva a hacer llorar. Di, ¿tienes novio?\"},{\"heading\":false,\"text\":\"—Pero qué preguntas...\"},{\"heading\":false,\"text\":\"—Dímelo, ¿le tienes?\"},{\"heading\":false,\"text\":\"—¡Novio... así, novio... no!\"},{\"heading\":false,\"text\":\"—Pero ¿es que no se te ha dirigido todavía ningún mozo de tu edad?\"},{\"heading\":false,\"text\":\"—Ya ve usted, don Augusto...\"},{\"heading\":false,\"text\":\"—¿Y qué le has dicho?\"},{\"heading\":false,\"text\":\"—Hay cosas que no se dicen...\"},{\"heading\":false,\"text\":\"—Es verdad. Y vamos, di, ¿os queréis?\"},{\"heading\":false,\"text\":\"—Pero ¡por Dios, don Augusto...!\"},{\"heading\":false,\"text\":\"—Mira, si es que vas a llorar te dejo.\"},{\"heading\":false,\"text\":\"La chica apoyó la cabeza en el pecho de Augusto, ocultándolo en él, y rompió a llorar procurando ahogar sus sollozos. «Esta chiquilla se me va a desmayar», pensó él mientras le acariciaba la cabellera.\"},{\"heading\":false,\"text\":\"—¡Cálmate! ¡cálmate!\"},{\"heading\":false,\"text\":\"—¿Y aquella mujer...?—preguntó Rosarito sin levantar la cabeza y tragándose sus sollozos.\"},{\"heading\":false,\"text\":\"—Ah, ¿te acuerdas? Pues aquella mujer ha acabado por rechazarme del todo. Nunca la gané, pero ahora la he perdido del todo, ¡del todo!\"},{\"heading\":false,\"text\":\"La chica levantó la frente y le miró cara a cara, como para ver si decía la verdad.\"},{\"heading\":false,\"text\":\"—Es que me quiere engañar...—susurró.\"},{\"heading\":false,\"text\":\"—¿Cómo que te quiero engañar? Ah, ya, ya. Conque esas tenemos, ¿eh? Pues ¿no dices que tenías novio?\"},{\"heading\":false,\"text\":\"—Yo no he dicho nada...\"},{\"heading\":false,\"text\":\"—¡Calma! ¡calma!—y poniéndola junto a sí en el sofá se levantó él y empezó a pasearse por la estancia.\"},{\"heading\":false,\"text\":\"Pero al volver la vista a ella vio que la pobre muchacha estaba demudada y temblorosa. Comprendió que se encontraba sin amparo, que así, sola frente a él, a cierta distancia, sentada en aquel sofá como un reo ante el fiscal, sentíase desfallecer.\"},{\"heading\":false,\"text\":\"—¡Es verdad!—exclamó—; estamos más protegidos cuanto más cerca.\"},{\"heading\":false,\"text\":\"Volvió a sentarse, volvió a sentarla sobre sí, la ciñó con sus brazos y la apretó a su pecho. La pobrecilla le echó un brazo sobre el hombro, como para apoyarse en él, y volvió a ocultar su cara en el seno de Augusto. Y allí, como oyese el martilleo del corazón de éste, se alarmó.\"},{\"heading\":false,\"text\":\"—¿Está usted malo, don Augusto?\"},{\"heading\":false,\"text\":\"—¿Y quién está bueno?\"},{\"heading\":false,\"text\":\"—¿Quiere usted que llame para que le traigan algo?\"},{\"heading\":false,\"text\":\"—No, no, déjalo. Yo sé cuál es mi enfermedad. Y lo que me hace falta es emprender un viaje.—Y después de un silencio: ¿Me acompañarás en él?\"},{\"heading\":false,\"text\":\"—¡Don Augusto!\"},{\"heading\":false,\"text\":\"—¡Deja el don! ¿Me acompañarás?\"},{\"heading\":false,\"text\":\"—Como usted quiera...\"},{\"heading\":false,\"text\":\"Una niebla invadió la mente de Augusto; la sangre empezó a latirle en las sienes, sintió una opresión en el pecho. Y para libertarse de ello empezó a besar a Rosarito en los ojos, que los tenía que cerrar. De pronto se levantó y dijo dejándola:\"},{\"heading\":false,\"text\":\"—¡Déjame! ¡déjame! ¡tengo miedo!\"},{\"heading\":false,\"text\":\"—¿Miedo de qué?\"},{\"heading\":false,\"text\":\"La repentina serenidad de la mozuela le asustó más aún.\"},{\"heading\":false,\"text\":\"—Tengo miedo, no sé de quién, de ti, de mí; ¡de lo que sea! ¡de Liduvina! Mira, vete, vete, pero volverás, ¿no es eso? ¿volverás?\"},{\"heading\":false,\"text\":\"—Cuando usted quiera.\"},{\"heading\":false,\"text\":\"—Y me acompañarás en mi viaje, ¿no es así?\"},{\"heading\":false,\"text\":\"—Como usted mande...\"},{\"heading\":false,\"text\":\"—¡Vete, vete ahora!\"},{\"heading\":false,\"text\":\"—Y aquella mujer...\"},{\"heading\":false,\"text\":\"Abalanzóse Augusto a la chica, que se había ya puesto en pie, la cojió, la apretó contra su pecho, juntó sus labios secos a los labios de ella y así, sin besarla, se estuvo un rato apretando boca a boca mientras sacudía su cabeza. Y luego soltándola: ¡anda, vete!\"},{\"heading\":false,\"text\":\"Rosario se salió. Y apenas se había salido fué Augusto, y cansado como si acabase de recorrer a pie leguas por entre montañas se echó sobre su cama, apagó la luz, y se quedó monologando:\"},{\"heading\":false,\"text\":\"«La he estado mintiendo y he estado mintiéndome. ¡Siempre es así! Todo es fantasía y no hay más que fantasía. El hombre en cuanto habla miente, y en cuanto se habla a sí mismo, es decir, en cuanto piensa sabiendo que piensa, se miente. No hay más verdad que la vida fisiológica. La palabra, este producto social, se ha hecho para mentir. Le he oído a nuestro filósofo que la verdad es, como la palabra, un producto social, lo que creen todos, y creyéndolo se entienden. Lo que es producto social es la mentira...»\"},{\"heading\":false,\"text\":\"Al sentir unos lametones en la mano exclamó: «Ah, ¿ya estás aquí, Orfeo? Tú como no hablas no mientes, y hasta creo que no te equivocas, que no te mientes. Aunque, como animal doméstico que eres, algo se te habrá pegado del hombre... No hacemos más que mentir y darnos importancia. La palabra se hizo para exagerar nuestras sensaciones e impresiones todas... acaso para creerlas. La palabra y todo género de expresión convencional, como el beso y el abrazo... No hacemos sino representar cada uno su papel. ¡Todos personas, todos caretas, todos cómicos! Nadie sufre ni goza lo que dice y expresa y acaso cree que goza y sufre; si no, no se podría vivir. En el fondo estamos tan tranquilos. Como yo ahora aquí, representando a solas mi comedia, hecho actor y espectador a la vez. No mata más que el dolor físico. La única verdad es el hombre fisiológico, el que no habla, el que no miente...»\"},{\"heading\":false,\"text\":\"Oyó un golpecito a la puerta.\"},{\"heading\":false,\"text\":\"—¿Qué hay?\"},{\"heading\":false,\"text\":\"—¿Es que no va usted a cenar hoy?—preguntó Liduvina.\"},{\"heading\":false,\"text\":\"—Es verdad; espera, que allá voy.\"},{\"heading\":false,\"text\":\"«Y luego dormiré hoy, como los otros días, y dormirá ella. ¿Dormirá Rosarito? ¿No habré turbado la tranquilidad de su espíritu? Y esa naturalidad suya, ¿es inocencia o es malicia? Pero acaso no hay nada más malicioso que la inocencia, o bien, más inocente que la malicia. Sí, sí, ya me suponía yo que en el fondo no hay nada más... más... ¿cómo lo diré?... más cínico que la inocencia. Sí, esa tranquilidad con que se me entregaba, eso que hizo me entrara miedo, miedo no sé bien de qué, eso no era sino inocencia. Y lo de: «¿Y aquélla mujer?», celos, ¿eh? ¿celos? Probablemente no nace el amor sino al nacer los celos; son los celos los que nos revelan el amor. Por muy enamorada que esté una mujer de un hombre, o un hombre de una mujer, no se dan cuenta de que lo están, no se dicen a sí mismos que lo están, es decir, no se enamoran de veras sino cuando él ve que ella mira a otro hombre o ella le ve a él mirar a otra mujer. Si no hubiese más que un solo hombre y una sola mujer en el mundo, sin más sociedad, sería imposible que se enamorasen uno de otro. Además de que hace siempre falta la tercera, la Celestina, y la Celestina es la sociedad. ¡El Gran Galeoto! ¡Y qué bien está eso! ¡Sí, el Gran Galeoto! Aunque sólo fuese por el lenguaje. Y por esto es todo eso del amor una mentira más. ¿Y el fisiológico? ¡Bah, eso fisiológico no es amor ni cosa que lo valga! ¡Por eso es verdad! Pero... vamos, Orfeo, vamos a cenar. ¡Esto sí que es verdad!»\"}]},{\"title\":\"Capítulo XIX\",\"blocks\":[{\"heading\":false,\"text\":\"A los dos días de esto anunciáronle a Augusto que una señora deseaba verle y hablarle. Salió a recibirla y se encontró con doña Ermelinda, que al: «¿usted por aquí?» de Augusto, contestó con un: «¡como no ha querido volver a vernos...!»\"},{\"heading\":false,\"text\":\"—Usted comprende, señora—contestó Augusto—, que después de lo que me ha pasado en su casa las dos últimas veces que he ido, la una con Eugenia a solas y la otra cuando no quiso verme, no debía volver. Yo me atengo en lo hecho y lo dicho, pero no puedo volver por allí...\"},{\"heading\":false,\"text\":\"—Pues traigo una misión para usted de parte de Eugenia...\"},{\"heading\":false,\"text\":\"—¿De ella?\"},{\"heading\":false,\"text\":\"—Sí, de ella. Yo no sé qué ha podido ocurrirle con el novio, pero no quiere oir hablar de él, está contra él furiosa, y el otro día, al volver a casa, se encerró en su cuarto y se negó a cenar. Tenía los ojos encendidos de haber llorado, pero con esas lágrimas que escaldan, ¿sabe usted?, las de rabia...\"},{\"heading\":false,\"text\":\"—¡Ah!, pero ¿es que hay diferentes clases de lágrimas?\"},{\"heading\":false,\"text\":\"—Naturalmente; hay lágrimas que refrescan y desahogan y lágrimas que encienden y sofocan más. Había llorado y no quiso cenar. Y me estuvo repitiendo su estribillo de que los hombres son ustedes todos unos brutos y nada más que unos brutos. Y ha estado estos días de morro, con un humor de todos los diablos. Hasta que ayer me llamó, me dijo que estaba arrepentida de cuanto le había dicho a usted, que se excedió y fué con usted injusta, que reconoce la rectitud y nobleza de las intenciones de usted y que quiere no ya que usted le perdone aquello que le dijo de que la quería comprar, sino que no cree semejante cosa. Es en esto en lo que hizo más hincapié. Dice que ante todo quiere que usted la crea que si dijo aquello fué por excitación, por despecho, pero que no lo cree...\"},{\"heading\":false,\"text\":\"—Y creo que no lo crea.\"},{\"heading\":false,\"text\":\"—Después... después me encargó que averiguase yo de usted con diplomacia...\"},{\"heading\":false,\"text\":\"—Y la mejor diplomacia, señora, es no tenerla, y sobre todo conmigo...\"},{\"heading\":false,\"text\":\"—Después me rogó que averiguase si le molestaría a usted el que ella aceptase, sin compromiso alguno, el regalo que usted le ha hecho de su propia casa...\"},{\"heading\":false,\"text\":\"—¿Cómo sin compromiso?\"},{\"heading\":false,\"text\":\"—Vamos, sí, el que acepte el regalo como tal regalo.\"},{\"heading\":false,\"text\":\"—Si como tal se lo doy, ¿cómo ha de aceptarlo?\"},{\"heading\":false,\"text\":\"—Porque dice que sí, que está dispuesta, para demostrarle su buena voluntad y lo sincero de su arrepentimiento por lo que le dijo, a aceptar su generosa donación, pero sin que eso implique...\"},{\"heading\":false,\"text\":\"—¡Basta, señora, basta! Ahora parece que sin darse cuenta vuelven a ofenderme...\"},{\"heading\":false,\"text\":\"—Será sin intención...\"},{\"heading\":false,\"text\":\"—Hay ocasiones en que las peores ofensas son esas que se infligen sin intención, según se dice.\"},{\"heading\":false,\"text\":\"—Pues no lo entiendo...\"},{\"heading\":false,\"text\":\"—Y es, sin embargo, cosa muy clara. Una vez entré en una reunión y uno que allí había y me conocía ni me saludó siquiera. Al salir me quejé de ello a un amigo y éste me dijo: «No le extrañe a usted, no lo ha hecho a posta; es que no se ha percatado siquiera de la presencia de usted». Y le contesté: «Pues ahí está la grosería mayor; no en que no me haya saludado, sino en que no se haya dado cuenta de mi presencia». «Eso es en él involuntario; es un distraído...», me replicó. Y yo a mi vez: «Las mayores groserías son las llamadas involuntarias, y la grosería de las groserías distraerse delante de personas. Es, señora, como eso que llaman neciamente olvidos involuntarios, como si cupiese olvidarse voluntariamente de algo. El olvido involuntario suele ser una grosería».\"},{\"heading\":false,\"text\":\"—Y a qué viene esto...\"},{\"heading\":false,\"text\":\"—Esto viene, señora doña Ermelinda, a que después de haberme pedido perdón por aquella especie ofensiva de que con mi donativo buscaba comprarla forzando su agradecimiento, no sé bien a qué viene aceptarlo pero haciendo constar que sin compromiso. ¿Qué compromiso, vamos, qué compromiso?\"},{\"heading\":false,\"text\":\"—¡No se exalte usted así, don Augusto...!\"},{\"heading\":false,\"text\":\"—¡Pues no he de exaltarme, señora, pues no he de exaltarme! ¿Es que esa... muchacha se va a burlar de mí y va a querer jugar conmigo?—y al decir esto se acordaba de Rosarito.\"},{\"heading\":false,\"text\":\"—¡Por Dios, don Augusto, por Dios...!\"},{\"heading\":false,\"text\":\"—Ya tengo dicho que la hipoteca se deshizo, que la he cancelado, y que si ella no se hace cargo de su casa yo nada tengo que ver con ella. ¡Y que me lo agradezca o no, ya no me importa!\"},{\"heading\":false,\"text\":\"—Pero, don Augusto, ¡no se ponga así! ¡Si lo que ella quiere es hacer las paces con usted, que vuelvan a ser amigos...!\"},{\"heading\":false,\"text\":\"—Sí, ahora que ha roto la guerra con el otro, ¿no es eso? Antes era yo el otro; ahora soy el uno, ¿no es eso? Ahora se trata de pescarme, ¿eh?\"},{\"heading\":false,\"text\":\"—Pero ¡si no he dicho tal cosa...!\"},{\"heading\":false,\"text\":\"—No, pero lo adivino.\"},{\"heading\":false,\"text\":\"—Pues se equivoca usted de medio a medio. Porque precisamente después de haberme mi sobrina dicho todo lo que acabo de repetirle a usted, al insinuarle yo y aconsejarle que pues ha reñido con el gandul de su novio procurase ganar a usted como tal, vamos, usted me entiende...\"},{\"heading\":false,\"text\":\"—Sí, que me reconquistase...\"},{\"heading\":false,\"text\":\"—¡Eso! Pues bien, al aconsejarle esto, me dijo una y cien veces que eso no y que no y que no; que le estimaba y apreciaba a usted para amigo y como tal, pero que no le gustaba como marido, que no quería casarse sino con un hombre de quien estuviese enamorada...\"},{\"heading\":false,\"text\":\"—Y que de mí no podrá llegar a estarlo, ¿no es eso?\"},{\"heading\":false,\"text\":\"—No, tanto como eso no dijo...\"},{\"heading\":false,\"text\":\"—Vamos, sí, que esto también es diplomacia...\"},{\"heading\":false,\"text\":\"—¿Cómo?\"},{\"heading\":false,\"text\":\"—Sí, que viene usted no sólo a que yo perdone a esa... muchacha, sino a ver si accedo a pretenderla para mujer, ¿no es eso? Cosa convenida, ¿eh?, y ella se resignará...\"},{\"heading\":false,\"text\":\"—Le juro a usted, don Augusto, le juro por la santa memoria de mi santa madre que esté en gloria, le juro...\"},{\"heading\":false,\"text\":\"—El segundo, no jurar...\"},{\"heading\":false,\"text\":\"—Pues le juro que es usted el que ahora se olvida, involuntariamente por supuesto, de quién soy yo, de quién es Ermelinda Ruiz y Ruiz.\"},{\"heading\":false,\"text\":\"—Si así fuese...\"},{\"heading\":false,\"text\":\"—Sí, así es, así—y pronunció estas palabras con tal acento que no dejaba lugar a duda.\"},{\"heading\":false,\"text\":\"—Pues entonces... entonces... diga a su sobrina que acepto sus explicaciones, que se las agradezco profundamente, que seguiré siendo su amigo, un amigo leal y noble, pero sólo amigo, ¿eh?, nada más que amigo, sólo amigo... Y no le diga que yo no soy un piano en que se puede tocar a todo antojo, que no soy un hombre de hoy te dejo y luego te tomo, que no soy sustituto ni vicenovio, que no soy plato de segunda mesa...\"},{\"heading\":false,\"text\":\"—¡No se exalte usted así!\"},{\"heading\":false,\"text\":\"—¡No, si no me exalto! Pues bien, que sigo siendo su amigo...\"},{\"heading\":false,\"text\":\"—¿E irá usted pronto a vernos?\"},{\"heading\":false,\"text\":\"—Eso...\"},{\"heading\":false,\"text\":\"—Mire que si no la pobrecilla no me va creer, va a sentirlo...\"},{\"heading\":false,\"text\":\"—Es que pienso emprender un viaje largo y lejano...\"},{\"heading\":false,\"text\":\"—Antes, de despedida...\"},{\"heading\":false,\"text\":\"—Bueno, veremos...\"},{\"heading\":false,\"text\":\"Separáronse. Cuando doña Ermelinda llegó a casa y contó a su sobrina la conversación con Augusto, Eugenia se dijo: «Aquí hay otra, no me cabe duda; ahora sí que le reconquisto».\"},{\"heading\":false,\"text\":\"Augusto, por su parte, al quedarse solo púsose a pasearse por la estancia diciéndose: «Quiere jugar conmigo, como si yo fuese un piano... me deja, me toma, me volverá a dejar... Yo estaba de reserva... Diga lo que quiera, anda buscando que yo vuelva a solicitarla, acaso para vengarse, tal vez para dar celos al otro y volverle al retortero... Como si yo fuese un muñeco, un ente, un don nadie... ¡Y yo tengo mi carácter, vaya si le tengo, yo soy yo! Sí, ¡yo soy yo! ¡yo soy yo! Le debo a ella, a Eugenia, ¿cómo negarlo?, el que haya despertado mi facultad amorosa; pero una vez que me la despertó y suscitó no necesito ya de ella; lo que sobran son mujeres.\"},{\"heading\":false,\"text\":\"Al llegar a esto no pudo por menos que sonreírse, y es que se acordó de aquella frase de Víctor cuando anunciándoles Gervasio, recién casado, que se iba con su mujer a pasar una temporadita en París, le dijo: «¿A París y con mujer? ¡Eso es como ir con un bacalao a Escocia!» Lo que le hizo muchísima gracia a Augusto.\"},{\"heading\":false,\"text\":\"Y siguió diciéndose: «Lo que sobran son mujeres. ¡Y qué encanto la inocencia maliciosa, la malicia inocente de Rosarito, esta nueva edición de la eterna Eva! ¡qué encanto de chiquilla! Ella, Eugenia, me ha bajado del abstracto al concreto, pero ella me llevó al genérico, y hay tantas mujeres apetitosas, tantas... ¡tantas Eugenias! ¡tantas Rosarios! No, no, con mí no juega nadie, y menos una mujer. ¡Yo soy yo! ¡Mi alma será pequeña, pero es mía!» Y sintiendo en esta exaltación de su yo, como si éste se le fuera hinchando, hinchando y la casa le viniera estrecha, salió a la calle para darle espacio y desahogo.\"},{\"heading\":false,\"text\":\"Apenas pisó la calle y se encontró con el cielo sobre la cabeza y las gentes que iban y venían, cada cual a su negocio o a su gusto y que no se fijaban en él, involuntariamente por supuesto, ni le hacían caso, por no conocerle sin duda, sintió que su yo, aquel yo del «¡yo soy yo!» se le iba achicando, achicando y se le replegaba en el cuerpo y aun dentro de éste buscaba un rinconcito en que acurrucarse y que no se le viera. La calle era un cinematógrafo y él sentíase cinematográfico, una sombra, un fantasma. Y es que siempre un baño en muchedumbre humana, un perderse en la masa de hombres que iban y venían sin conocerle ni percatarse de él, le produjo el efecto mismo de un baño en naturaleza abierta a cielo abierto, y a la rosa de los vientos.\"},{\"heading\":false,\"text\":\"Sólo a solas se sentía él: sólo a solas podía decirse a sí mismo, tal vez para convencerse, «¡yo soy yo!»; ante los demás, metido en la muchedumbre atareada o distraída, no se sentía a sí mismo.\"},{\"heading\":false,\"text\":\"Así llegó a aquel recatado jardinillo que había en la solitaria plaza del retirado barrio en que vivía. Era la plaza un remanso de quietud donde siempre jugaban algunos niños, pues no circulaban por allí tranvías ni apenas coches, e iban algunos ancianos a tomar el sol en las tardecitas dulces del otoño, cuando las hojas de la docena de castaños de Indias que allí vivían recluidos, después de haber temblado al cierzo, rodaban por el enlosado o cubrían los asientos de aquellos bancos de madera siempre pintada de verde, del color de la hoja fresca. Aquellos árboles domésticos, urbanos, en correcta formación, que recibían riego a horas fijas, cuando no llovía, por una reguera y que extendían sus raíces bajo el enlosado de la plaza; aquellos árboles presos que esperaban ver salir y ponerse el sol sobre los tejados de las casas; aquellos árboles enjaulados, que tal vez añoraban la remota selva, atraíanle con un misterioso tiro. En sus copas cantaban algunos pájaros urbanos también, de esos que aprenden a huir de los niños y alguna vez a acercarse a los ancianos que les ofrecen unas migas de pan.\"},{\"heading\":false,\"text\":\"¡Cuántas veces sentado solo y solitario en uno de los bancos verdes de aquella plazuela vio el incendio del ocaso sobre un tejado y alguna vez destacarse sobre el oro en fuego del espléndido arrebol el contorno de un gato negro sobre la chimenea de una casa! Y en tanto, en otoño, llovían hojas amarillas, anchas hojas como de vid, a modo de manos momificadas, laminadas, sobre los jardincillos del centro con sus arriates y sus macetas de flores. Y jugaban los niños entre las hojas secas, jugaban acaso a recojerlas, sin darse cuenta del encendido ocaso.\"},{\"heading\":false,\"text\":\"Cuando llegó aquel día a la tranquila plaza y se sentó en el banco, no sin antes haber despejado su asiento de las hojas secas que lo cubrían—pues era otoño—, jugaban allí cerca, como de ordinario, unos chiquillos. Y uno de ellos, poniéndole a otro junto al tronco de uno de los castaños de Indias, bien arrimadito a él, le decía: «Tú estabas ahí preso, te tenían unos ladrones...» «Es que yo...»—empezó malhumorado el otro, y el primero le replicó: «No, tú no eras tú...» Augusto no quiso oir más; levantóse y se fué a otro banco. Y se dijo: «Así jugamos también los mayores; ¡tú no eres tú! ¡yo no soy yo! Y estos pobres árboles, ¿son ellos? Se les cae la hoja antes, mucho antes que a sus hermanos del monte, y se quedan en esqueleto, y estos esqueletos proyectan su recortada sombra sobre los empedrados al resplandor de los reverberos de luz eléctrica. ¡Un árbol iluminado por la luz eléctrica! ¡Qué extraña, qué fantástica apariencia la de su copa en primavera cuando el arco voltaico ese le da aquella apariencia metálica! ¡Y aquí que las brisas no los mecen...! ¡Pobres árboles que no pueden gozar de una de esas negras noches del campo, de esas noches sin luna, con su manto de estrellas palpitantes! Parece que al plantar a cada uno de estos árboles en este sitio les ha dicho el hombre: “¡Tú no eres tú!”, y para que no lo olviden le han dado esa iluminación nocturna por luz eléctrica... para que no se duerman... ¡Pobres árboles trasnochadores! ¡No, no, conmigo no se juega como con vosotros!»\"},{\"heading\":false,\"text\":\"Levantóse y empezó a recorrer calles como un sonámbulo.\"}]},{\"title\":\"Capítulo XX\",\"blocks\":[{\"heading\":false,\"text\":\"Emprendería el viaje, ¿sí o no? Ya lo había anunciado, primero a Rosarito, sin saber bien lo que se decía, por decir algo, o más bien como un pretexto para preguntarle si le acompañaría en él, y luego a doña Ermelinda, para probarle... ¿qué? ¿qué es lo que pretendió probarle con aquello de que iba a emprender un viaje? ¡Lo que fuese! Mas era el caso que había soltado por dos veces prenda, que había dicho que iba a emprender un viaje largo y lejano y él era hombre de carácter, él era él; ¿tenía que ser hombre de palabra?\"},{\"heading\":false,\"text\":\"Los hombres de palabra primero dicen una cosa y después la piensan, y por último la hacen, resulte bien o mal luego de pensada; los hombres de palabra no se rectifican ni se vuelven atrás de lo que una vez han dicho. Y él dijo que iba a emprender un viaje largo y lejano.\"},{\"heading\":false,\"text\":\"¡Un viaje largo y lejano! ¿Por qué? ¿para qué? ¿cómo? ¿adónde?\"},{\"heading\":false,\"text\":\"Anunciáronle que una señorita deseaba verle. «¿Una señorita?» «Sí—dijo Liduvina—, me parece que es... ¡la pianista!» «¡Eugenia!» «La misma.» Quedóse suspenso. Como un relámpago de mareo pasóle por la mente la idea de despacharla, de que la dijeran que no estaba en casa. «Viene a conquistarme, a jugar conmigo como con un muñeco—se dijo—, a que la haga el juego, a que sustituya al otro...» Luego lo pensó mejor. «¡No, hay que mostrarse fuerte!»\"},{\"heading\":false,\"text\":\"—Dile que ahora voy.\"},{\"heading\":false,\"text\":\"Le tenía absorto la intrepidez de aquella mujer. «Hay que confesar que es toda una mujer, que es todo un carácter, ¡vaya un arrojo! ¡vaya una resolución! ¡vaya unos ojos!; pero ¡no, no, no, no me doblega! ¡no me conquista!»\"},{\"heading\":false,\"text\":\"Cuando entró Augusto en la sala Eugenia estaba de pie. Hízole una seña de que se sentara, mas ella, antes de hacerlo, exclamó: «¡A usted, don Augusto, le han engañado lo mismo que me han engañado a mí!» Con lo que se sintió el pobre hombre desarmado y sin saber qué decir. Sentáronse los dos, y se siguió un brevísimo silencio.\"},{\"heading\":false,\"text\":\"—Pues sí, lo dicho, don Augusto, a usted le han engañado respecto a mí y a mí me han engañado respecto a usted; esto es todo.\"},{\"heading\":false,\"text\":\"—Pero ¡si hemos hablado uno con otro, Eugenia!\"},{\"heading\":false,\"text\":\"—No haga usted caso de lo que le dije. ¡Lo pasado, pasado!\"},{\"heading\":false,\"text\":\"—Sí, siempre es lo pasado pasado, ni puede ser de otra manera.\"},{\"heading\":false,\"text\":\"—Usted me entiende. Y yo quiero que no dé a mi aceptación de su generoso donativo otro sentido que el que tiene.\"},{\"heading\":false,\"text\":\"—Como yo deseo, señorita, que no dé a mi donativo otra significación que la que tiene.\"},{\"heading\":false,\"text\":\"—Así, lealtad por lealtad. Y ahora, como debemos de hablar claro, he de decirle que después de todo lo pasado y de cuanto le dije, no podría yo, aunque quisiera, pretender pagarle esa generosa donación de otra manera que con mi más puro agradecimiento. Así como usted por su parte, creo...\"},{\"heading\":false,\"text\":\"—En efecto, señorita, por mi parte yo, después de lo pasado, de lo que usted me dijo en nuestra última entrevista, de lo que me contó su señora tía y de lo que adivino no podría, aunque lo deseara, pretender cotizar mi generosidad...\"},{\"heading\":false,\"text\":\"—¿Estamos, pues, de acuerdo?\"},{\"heading\":false,\"text\":\"—De perfecto acuerdo, señorita.\"},{\"heading\":false,\"text\":\"—Y así, ¿podremos volver a ser amigos, buenos amigos, verdaderos amigos?\"},{\"heading\":false,\"text\":\"—Podremos.\"},{\"heading\":false,\"text\":\"Le tendió a Eugenia su fina mano, blanca y fría como la nieve, de ahusados dedos hechos a dominar teclados, y la estrechó en la suya, que en aquel momento temblaba.\"},{\"heading\":false,\"text\":\"—Seremos, pues, amigo don Augusto, buenos amigos, aunque esta amistad a mí...\"},{\"heading\":false,\"text\":\"—¿Qué?\"},{\"heading\":false,\"text\":\"—Acaso ante el público...\"},{\"heading\":false,\"text\":\"—¿Qué? ¡Hable! ¡hable!\"},{\"heading\":false,\"text\":\"—Pero, en fin, después de dolorosas experiencias recientes he renunciado ya a ciertas cosas...\"},{\"heading\":false,\"text\":\"—Explíquese usted más claro, señorita. No vale decir las cosas a medias.\"},{\"heading\":false,\"text\":\"—Pues bien, don Augusto, las cosas claras, muy claras. ¿Cree usted que es fácil que después de lo pasado y sabiendo, como ya se sabe entre nuestros conocimientos, que usted ha deshipotecado mi patrimonio regalándomelo así, es fácil que haya quien se dirija a mí con ciertas pretensiones?\"},{\"heading\":false,\"text\":\"«¡Esta mujer es diabólica!», pensó Augusto y bajó la cabeza mirando al suelo sin saber qué contestar. Cuando, al instante, la levantó vio que Eugenia se enjugaba una furtiva lágrima.\"},{\"heading\":false,\"text\":\"—¡Eugenia!—exclamó, y le temblaba la voz.\"},{\"heading\":false,\"text\":\"—¡Augusto!—susurró rendidamente ella.\"},{\"heading\":false,\"text\":\"—Pero ¿y qué quieres que hagamos?\"},{\"heading\":false,\"text\":\"—Oh, no, es la fatalidad, no es más que la fatalidad; somos juguete de ella. ¡Es una desgracia!\"},{\"heading\":false,\"text\":\"Augusto fué dejando su butaca, a sentarse en el sofá, al lado de Eugenia.\"},{\"heading\":false,\"text\":\"—¡Mira, Eugenia, por Dios, que no juegues así conmigo! La fatalidad eres tú; aquí no hay más fatalidad que tú. Eres tú que me traes y me llevas y me haces dar vueltas como un argandillo; eres tú que me vuelves loco; eres tú que me haces quebrantar mis más firmes propósitos; eres tú que haces que yo no sea yo...\"},{\"heading\":false,\"text\":\"Y le echó el brazo al cuello, la atrajo a sí y la apretó contra su seno. Y ella tranquilamente se quitó el sombrero.\"},{\"heading\":false,\"text\":\"—Sí, Augusto, es la fatalidad la que nos ha traído a esto. Ni... ni tú ni yo podemos ser infieles, desleales a nosotros mismos; ni tú puedes aparecer queriéndome comprar como yo en un momento de ofuscación te dije, ni yo puedo aparecer haciendo de ti un sustituto, un vice, un plato de segunda mesa, como a mi tía le dijiste, y queriendo no más que premiar tu generosidad...\"},{\"heading\":false,\"text\":\"—Pero ¿y qué nos importa, Eugenia mía, el aparecer de un modo o de otro? ¿a qué ojos?\"},{\"heading\":false,\"text\":\"—¡A los mismos nuestros!\"},{\"heading\":false,\"text\":\"—Y qué, Eugenia mía...\"},{\"heading\":false,\"text\":\"Volvió a apretarla a sí y empezó a llenarle de besos la frente y los ojos. Se oía la respiración de ambos.\"},{\"heading\":false,\"text\":\"—¡Déjame! ¡déjame!—dijo ella, mientras se arreglaba y componía el pelo.\"},{\"heading\":false,\"text\":\"—No, tú... tú... tú... Eugenia... tú...\"},{\"heading\":false,\"text\":\"—No, yo no, no puede ser...\"},{\"heading\":false,\"text\":\"—¿Es que no me quieres?\"},{\"heading\":false,\"text\":\"—Eso de querer... ¿quién sabe lo que es querer? No sé... no sé... no estoy segura de ello...\"},{\"heading\":false,\"text\":\"—¿Y esto entonces?\"},{\"heading\":false,\"text\":\"—¡Esto es una... una fatalidad del momento! producto de arrepentimiento... qué sé yo... estas cosas hay que ponerlas a prueba... Y además, ¿no habíamos quedado, Augusto, en que seríamos amigos, buenos amigos, pero nada más que amigos?\"},{\"heading\":false,\"text\":\"—Sí, pero... ¿Y aquello de tu sacrificio? ¿Aquello de que por haber aceptado mi dádiva, por ser amiga, nada más que amiga mía, no va ya a haber quien te pretenda?\"},{\"heading\":false,\"text\":\"—¡Ah, eso no importa; tengo tomada mi resolución!\"},{\"heading\":false,\"text\":\"—¿Acaso después de aquella ruptura...?\"},{\"heading\":false,\"text\":\"—Acaso...\"},{\"heading\":false,\"text\":\"—¡Eugenia! ¡Eugenia!\"},{\"heading\":false,\"text\":\"En este momento se oyó llamar a la puerta, y Augusto, tembloroso, encendido de rostro, exclamó con voz seca: ¿qué hay?\"},{\"heading\":false,\"text\":\"—¡La Rosario que espera!—dijo la voz de Liduvina.\"},{\"heading\":false,\"text\":\"Augusto cambió de color poniéndose lívido.\"},{\"heading\":false,\"text\":\"—¡Ah!—exclamó Eugenia—, aquí estorbo ya. Es la... Rosario que le espera a usted. ¿Ve usted cómo no podemos ser más que amigos, buenos amigos, muy buenos amigos?\"},{\"heading\":false,\"text\":\"—Pero Eugenia...\"},{\"heading\":false,\"text\":\"—Que espera la Rosario...\"},{\"heading\":false,\"text\":\"—Y si me rechazaste, Eugenia, como me rechazaste, diciéndome que te quería comprar y en rigor porque tenías otro, ¿qué iba a hacer yo luego que al verte aprendí a querer? ¿No sabes acaso lo que es el despecho, lo que es el cariño desnidado?\"},{\"heading\":false,\"text\":\"—Vaya, Augusto, venga esa mano; volveremos a vernos, pero conste que lo pasado, pasado.\"},{\"heading\":false,\"text\":\"—No, no, lo pasado pasado ¡no! ¡no! ¡no!\"},{\"heading\":false,\"text\":\"—Bien, bien, que espera la Rosario...\"},{\"heading\":false,\"text\":\"—Por Dios, Eugenia...\"},{\"heading\":false,\"text\":\"—No, si nada de extraño tiene; también a mí me esperaba en un tiempo el... Mauricio. Volveremos a vernos. Y seamos serios y leales a nosotros mismos.\"},{\"heading\":false,\"text\":\"Púsose el sombrero, tendió su mano a Augusto que, cojiéndosela se la llevó a los labios y la cubrió de besos, y salió, acompañándole él hasta la puerta. La miró un rato bajar las escaleras garbosa y con pie firme. Desde un descansillo de abajo alzó ella sus ojos y le saludó con la mirada y con la mano. Volvióse Augusto, entró al gabinete, y al ver a Rosario allí de pie, con la cesta de la plancha, le dijo bruscamente:\"},{\"heading\":false,\"text\":\"—¿Qué hay?\"},{\"heading\":false,\"text\":\"—Me parece, don Augusto, que esa mujer le está engañando a usted...\"},{\"heading\":false,\"text\":\"—Y a ti, ¿qué te importa?\"},{\"heading\":false,\"text\":\"—Me importa todo lo de usted.\"},{\"heading\":false,\"text\":\"—Lo que quieres decir es que te estoy engañando...\"},{\"heading\":false,\"text\":\"—Eso es lo que no me importa.\"},{\"heading\":false,\"text\":\"—¿Me vas a hacer creer que después de las esperanzas que te he hecho concebir no estás celosa?\"},{\"heading\":false,\"text\":\"—Si usted supiera, don Augusto, cómo me he criado y en qué familia, comprendería que aunque soy una chiquilla estoy ya fuera de esas cosas de celos. Nosotras, las de mi posición...\"},{\"heading\":false,\"text\":\"—¡Cállate!\"},{\"heading\":false,\"text\":\"—Como usted quiera. Pero le repito que esa mujer le está a usted engañando. Si no fuera así y si usted la quiere y es ese su gusto, ¿qué más quisiera yo sino que usted se casase con ella?\"},{\"heading\":false,\"text\":\"—Pero ¿dices todo eso de verdad?\"},{\"heading\":false,\"text\":\"—De verdad.\"},{\"heading\":false,\"text\":\"—¿Cuántos años tienes?\"},{\"heading\":false,\"text\":\"—Diez y nueve.\"},{\"heading\":false,\"text\":\"—Ven acá—y cojiéndola con sus dos manos de los sendos hombros la puso cara a cara consigo y se le quedó mirando a los ojos.\"},{\"heading\":false,\"text\":\"Y fué Augusto quien se demudó de color, no ella.\"},{\"heading\":false,\"text\":\"—La verdad es, chiquilla, que no te entiendo.\"},{\"heading\":false,\"text\":\"—Lo creo.\"},{\"heading\":false,\"text\":\"—Yo no sé qué es esto, si inocencia, malicia, burla, precoz perversidad...\"},{\"heading\":false,\"text\":\"—Esto no es más que cariño.\"},{\"heading\":false,\"text\":\"—¿Cariño? ¿y por qué?\"},{\"heading\":false,\"text\":\"—¿Quiere usted saber por qué? ¿no se ofenderá si se lo digo? ¿me promete no ofenderse?\"},{\"heading\":false,\"text\":\"—Anda, dímelo.\"},{\"heading\":false,\"text\":\"—Pues bien, por... por... porque es usted un infeliz, un pobre hombre...\"},{\"heading\":false,\"text\":\"—¿También tú?\"},{\"heading\":false,\"text\":\"—Como usted quiera. Pero fíese de esta chiquilla; fíese de... la Rosario. Más leal a usted... ¡ni Orfeo!\"},{\"heading\":false,\"text\":\"—¿Siempre?\"},{\"heading\":false,\"text\":\"—¡Siempre!\"},{\"heading\":false,\"text\":\"—¿Pase lo que pase?\"},{\"heading\":false,\"text\":\"—Sí, pase lo que pase.\"},{\"heading\":false,\"text\":\"—Tú, tú eres la verdadera...—y fué a cojerla.\"},{\"heading\":false,\"text\":\"—No, ahora no, cuando esté usted más tranquilo. Y cuando no...\"},{\"heading\":false,\"text\":\"—Basta, te entiendo.\"},{\"heading\":false,\"text\":\"Y se despidieron.\"},{\"heading\":false,\"text\":\"Y al quedarse solo se decía Augusto: «entre una y otra me van a volver loco de atar... yo ya no soy yo...»\"},{\"heading\":false,\"text\":\"—Me parece que el señorito debía dedicarse a la política o a algo así por el estilo—le dijo Liduvina mientras le servía la comida—; eso le distraería.\"},{\"heading\":false,\"text\":\"—¿Y como se te ha ocurrido eso, mujer de Dios?\"},{\"heading\":false,\"text\":\"—Porque es mejor que se distraiga uno a no que le distraigan y... ¡ya ve usted!\"},{\"heading\":false,\"text\":\"—Bueno, pues llama ahora a tu marido, a Domingo, en cuanto acabe de comer, y dile que quiero echar con él una partida de tute... que me distraiga.\"},{\"heading\":false,\"text\":\"Y cuando la estaba jugando dejó de pronto Augusto la baraja sobre la mesa y preguntó:\"},{\"heading\":false,\"text\":\"—Di, Domingo, cuando un hombre está enamorado de dos o más mujeres a la vez, ¿qué debe hacer?\"},{\"heading\":false,\"text\":\"—¡Según y conforme!\"},{\"heading\":false,\"text\":\"—¿Cómo según y conforme?\"},{\"heading\":false,\"text\":\"—¡Sí! Si tiene mucho dinero y muchas agallas casarse con todas ellas, y si no, no casarse con ninguna.\"},{\"heading\":false,\"text\":\"—Pero ¡hombre, eso primero no es posible!\"},{\"heading\":false,\"text\":\"—¡En teniendo mucho dinero todo es posible!\"},{\"heading\":false,\"text\":\"—¿Y si ellas se enteran?\"},{\"heading\":false,\"text\":\"—Eso a ellas no les importa.\"},{\"heading\":false,\"text\":\"—¿Pues no ha de importarle, hombre, a una mujer el que otra le quite parte del cariño de su marido?\"},{\"heading\":false,\"text\":\"—Se contenta con su parte, señorito, si no se le pone tasa al dinero que gasta. Lo que le molesta a una mujer es que su hombre le ponga a ración de comer, de vestir, de todo lo demás así, del lujo; pero si le deja gastar lo que quiera... Ahora, si tiene hijos de él...\"},{\"heading\":false,\"text\":\"—Si tiene hijos, ¿qué?\"},{\"heading\":false,\"text\":\"—Que los verdaderos celos vienen de ahí, señorito, de los hijos. Es una madre que no tolera otra madre o que puede serlo, es una madre que no tolera que se les merme a sus hijos para otros hijos o para otra mujer. Pero si no tiene hijos y no le tasan el comedero y el vestidero, y la pompa y la fanfarria, ¡bah!, hasta le ahorran así molestias... Si uno tiene además de una mujer que le cueste otra que no le cueste nada, aquella que le cuesta apenas si siente celos de esta otra que no le cuesta, y si además de no costarle nada le produce encima... si lleva a una mujer dinero que de otra saca, entonces...\"},{\"heading\":false,\"text\":\"—Entonces, ¿qué?\"},{\"heading\":false,\"text\":\"—Que todo marcha a pedir de boca. Créame usted, señorito, no hay Otelas...\"},{\"heading\":false,\"text\":\"—Ni Desdémonos.\"},{\"heading\":false,\"text\":\"—¡Puede ser...!\"},{\"heading\":false,\"text\":\"—Pero qué cosas dices...\"},{\"heading\":false,\"text\":\"—Es que antes de haberme casado con Liduvina y venir a servir a casa del señorito había servido yo en muchas casas de señorones... me han salido los dientes en ellas...\"},{\"heading\":false,\"text\":\"—¿Y en vuestra clase?\"},{\"heading\":false,\"text\":\"—¿En nuestra clase? ¡bah!, nosotros no nos permitimos ciertos lujos...\"},{\"heading\":false,\"text\":\"—¿Y a qué llamas lujos?\"},{\"heading\":false,\"text\":\"—A esas cosas que se ve en los teatros y se lee en las novelas...\"},{\"heading\":false,\"text\":\"—¡Pues, hombre, pocos crímenes de esos que llaman pasionales, por celos, se ven en vuestra clase...!\"},{\"heading\":false,\"text\":\"—¡Bah!, eso es porque esos... chulos van al teatro y leen novelas, que si no.\"},{\"heading\":false,\"text\":\"—Si no, ¿qué?\"},{\"heading\":false,\"text\":\"—Que a todos nos gusta, señorito, hacer papel y nadie es el que es, sino el que le hacen los demás.\"},{\"heading\":false,\"text\":\"—Filósofo estás...\"},{\"heading\":false,\"text\":\"—Así me llamaba el último amo que tuve antes. Pero yo creo lo que le ha dicho mi Liduvina, que usted debe dedicarse a la política.\"}]},{\"title\":\"Capítulo XXI\",\"blocks\":[{\"heading\":false,\"text\":\"—Sí, tiene usted razón—le decía don Antonio a Augusto aquella tarde, en el Casino, hablando a solas, en un rinconcito—, tiene usted razón, hay un misterio doloroso, dolorosísimo en mi vida. Usted ha adivinado algo. Pocas veces ha visitado usted mi pobre hogar... ¿hogar?, pero habrá notado...\"},{\"heading\":false,\"text\":\"—Sí, algo extraño, yo no sé qué tristeza flotante que me atraía a él...\"},{\"heading\":false,\"text\":\"—A pesar de mis hijos, de mis pobres hijos, usted le habrá parecido un hogar sin hijos, acaso sin esposos...\"},{\"heading\":false,\"text\":\"—No sé... no sé...\"},{\"heading\":false,\"text\":\"—Vinimos de lejos, de muy lejos, huyendo, pero hay cosas que van siempre con uno, que le rodean y envuelven como un ámbito misterioso. Mi pobre mujer...\"},{\"heading\":false,\"text\":\"—Sí, en el rostro de su señora se adivina toda una vida de...\"},{\"heading\":false,\"text\":\"—De martirio, dígalo usted. Pues bien, amigo don Augusto, usted ha sido, no sé bien por qué, por una cierta oculta simpatía, quien mayor afecto, más compasión acaso nos ha mostrado, y yo, para figurarme una vez más que me libro de un peso, voy a confiarle mis desdichas. Esa mujer, la madre de mis hijos, no es mi mujer.\"},{\"heading\":false,\"text\":\"—Me lo suponía; pero si es ella la madre de sus hijos, si con usted vive como su mujer, lo es.\"},{\"heading\":false,\"text\":\"—No, yo tengo otra mujer... legítima, según se la llama. Estoy casado, pero no con la que usted conoce. Y ésta, la madre de mis hijos, está casada también, pero no conmigo.\"},{\"heading\":false,\"text\":\"—Ah, un doble...\"},{\"heading\":false,\"text\":\"—No, un cuádruple, como va usted a verlo. Yo me casé loco, pero enteramente loco de amor, con una mujercita reservada y callandrona, que hablaba poco y parecía querer decir siempre mucho más de lo que decía, con unos ojos garzos dulces, dulces, dulces, que parecían dormidos y sólo se despertaban de tarde en tarde, pero era entonces para chispear fuego. Y ella era toda así. Su corazón, su alma toda, todo su cuerpo, que parecían de ordinario dormidos, despertaban de pronto como en sobresalto, pero era para volver a dormirse muy pronto, pasado el relámpago de vida, ¡y de qué vida!, y luego como si nada hubiese sido, como si se hubiese olvidado de todo lo que pasó. Era como si estuviésemos siempre recomenzando la vida, como si la estuviese reconquistando de continuo. Me admitió de novio como en un ataque epiléptico y creo que en otro ataque me dio el sí ante el altar. Y nunca pude conseguir que me dijese si me quería o no. Cuantas veces se lo pregunté, antes y después de casarnos, siempre me contestó: eso no se pregunta; es una tontería. Otras veces decía que el verbo amar ya no se usa sino en el teatro y los libros, y que si yo le hubiese escrito: ¡te amo!, me habría despedido al punto. Vivimos más de dos años de casados de una extraña manera, reanudando yo cada día la conquista de aquella esfinge. No tuvimos hijos. Un día faltó a casa por la noche, me puse como loco, la anduve buscando por todas partes, y al siguiente día supe por una carta muy seca y muy breve que se había ido lejos, muy lejos, con otro hombre...\"},{\"heading\":false,\"text\":\"—Y no sospechó usted nada antes, no lo barruntó...\"},{\"heading\":false,\"text\":\"—¡Nada! Mi mujer salía sola de casa con bastante frecuencia, a casa de su madre, de unas amigas, y su misma extraña frialdad la defendía ante mí de toda sospecha. ¡Y nada adiviné nunca en aquella esfinge! El hombre con quien huyó era un hombre casado, que no sólo dejó a su mujer y a una pequeña niña para irse con la mía, sino que se llevó la fortuna toda de la suya, que era regular, después de haberla manejado a su antojo. Es decir, que no sólo abandonó a su esposa, sino que la arruinó robándole lo suyo. Y en aquella seca y breve y fría carta que recibí se hacía alusión al estado en que la pobre mujer del raptor de la mía se quedaba. ¡Raptor o raptado... no lo sé! En unos días ni dormí, ni comí, ni descansé; no hacía sino pasear por los más apartados barrios de mi ciudad. Y estuve a punto de dar en los vicios más bajos y más viles. Y cuando empezó a asentárseme el dolor, a convertírseme en pensamiento, me acordé de aquella otra pobre víctima, de aquella mujer que se quedaba sin amparo, robada de su cariño y de su fortuna. Creí un caso de conciencia, pues que mi mujer era la causa de su desgracia, ir a ofrecerla mi ayuda pecuniaria, ya que Dios me dio fortuna.\"},{\"heading\":false,\"text\":\"—Adivino el resto, don Antonio.\"},{\"heading\":false,\"text\":\"—No importa. La fuí a ver. Figúrese usted aquella nuestra primera entrevista. Lloramos nuestras sendas desgracias, que eran una desgracia común. Yo me decía: «¿y es por mi mujer por la que ha dejado a ésta ese hombre?», y sentía, ¿por qué no he de confesarle la verdad?, una cierta íntima satisfacción, algo inexplicable, como si yo hubiese sabido escojer mejor que él y él lo reconociese. Y ella, su mujer, se hacía una reflexión análoga, aunque invertida, según después me ha declarado. Le ofrecí mi ayuda pecuniaria, lo que de mi fortuna necesitase, y empezó rechazándomelo. «Trabajaré para vivir y mantener a mi hija», me dijo. Pero insistí y tanto insistí que acabó aceptándomelo. La ofrecí hacerla mi ama de llaves, que se viniese a vivir conmigo, claro que viniéndonos muy lejos de nuestra patria, y después de mucho pensarlo lo aceptó también.\"},{\"heading\":false,\"text\":\"—Y es claro, al irse a vivir juntos...\"},{\"heading\":false,\"text\":\"—No, eso tardó, tardó algo. Fué cosa de la convivencia, de un cierto sentimiento de venganza, de despecho, de qué sé yo... Me prendé no ya de ella, sino de su hija, de la desdichada hija del amante de mi mujer; la cobré un amor de padre, un violento amor de padre, como el que hoy se lo tengo, pues la quiero tanto, tanto, sí, cuando no más, que a mis propios hijos. La cojía en mis brazos, la apretaba a mi pecho, la envolvía en besos, y lloraba, lloraba sobre ella. Y la pobre niña me decía: «¿por qué lloras, papá?», pues le hacía que me llamase así y por tal me tuviera. Y su pobre madre al verme llorar así lloraba también y alguna vez mezclamos nuestras lágrimas sobre la rubia cabecita de la hija del amante de mi mujer, del ladrón de mi dicha.\"},{\"heading\":false,\"text\":\"Un día supe—prosiguió—que mi mujer había tenido un hijo de su amante y aquel día todas mis entrañas se sublevaron, sufrí como nunca había sufrido y creí volverme loco y quitarme la vida. Los celos, lo más brutal de los celos, no lo sentí hasta entonces. La herida de mi alma, que parecía cicatrizada, se abrió y sangraba... ¡sangraba fuego! Más de dos años había vivido con mi mujer, con mi propia mujer, y ¡nada! ¡y ahora aquel ladrón...! Me imaginé que mi mujer habría despertado del todo y que vivía en pura brasa. La otra, la que vivía conmigo, conoció algo y me preguntó: «¿qué te pasa?» Habíamos convenido en tutearnos, por la niña. «¡Déjame!», le contesté. Pero acabé confesándoselo todo, y ella al oírmelo temblaba. Y creo que le contagié de mis furiosos celos...\"},{\"heading\":false,\"text\":\"—Y claro, después de eso...\"},{\"heading\":false,\"text\":\"—No, vino algo después y por otro camino. Y fué que un día estando los dos con la niña, la tenía yo sobre mis rodillas y estaba contándola cuentos y besándola y diciéndole bobadas, se acercó su madre y empezó a acariciarla también. Y entonces ella, ¡pobrecilla!, me puso una de sus manitas sobre el hombro y la otra sobre el de su madre, y nos dijo: «papaíto... mamaíta... ¿por qué no me traéis un hermanito para que juegue conmigo, como le tienen otras niñas, y no que estoy sola...?» Nos pusimos lívidos, nos miramos a los ojos con una de esas miradas que desnudan las almas, nos vimos éstas al desnudo, y luego, para no avergonzarnos, nos pusimos a besuquear a la niña, y alguno de estos besos cambió de rumbo. Aquella noche, entre lágrimas y furores de celos, engendramos al primer hermanito de la hija del ladrón de mi dicha.\"},{\"heading\":false,\"text\":\"—¡Extraña historia!\"},{\"heading\":false,\"text\":\"—Y fueron nuestros amores, si es que así quiere usted llamarlos, unos amores secos y mudos, hechos de fuego y rabia, sin ternezas de palabra. Mi mujer, la madre de mis hijos quiero decir, porque ésta y no otra es mi mujer, mi mujer es, como usted habrá visto, una mujer agraciada, tal vez hermosa, pero a mí nunca me inspiró ardor de deseos, y esto a pesar de la convivencia. Y aun después que acabamos en lo que le digo me figuré no estar en exceso enamorado de ella, hasta que pude convencerme de lo contrario. Y es que una vez, después de uno de sus partos, después del nacimiento del cuarto de nuestros hijos, se me puso tan mal, tan mal, que creí que se me moría. Perdió la más de la sangre de sus venas, se quedó como la cera de blanca, se le cerraban los párpados... Creí perderla. Y me puse como loco, blanco yo también como la cera, la sangre se me helaba. Y fuí a un rincón de la casa, donde nadie me viese y me arrodillé y pedí a Dios que me matara antes que dejase morir a aquella santa mujer. Y lloré y me pellizqué y me arañé el pecho hasta sacarme sangre. Y comprendí con cuán fuerte atadura estaba mi corazón atado al corazón de la madre de mis hijos. Y cuando ésta se repuso algo y recobró conocimiento y salió de peligro, acerqué mi boca a su oído, según ella sonreía a la vida renaciente tendida en la cama, y le dije lo que nunca le había dicho y nunca la he vuelto, de la misma manera, a decir. Y allí sonreía, sonreía, sonreía mirando al techo. Y puse mi boca sobre su boca, y me enlacé con sus desnudos brazos el cuello, y acabé llorando de mis ojos sobre sus ojos. Y me dijo: «gracias, Antonio, gracias, por mí, por nuestros hijos, por nuestros hijos todos... todos... todos... por ella, por Rita...» Rita es nuestra hija mayor, la hija del ladrón... no, no, nuestra hija, mi hija. La del ladrón es la otra, es la de que se llamó mi mujer en un tiempo. ¿Lo comprende usted ahora todo?\"},{\"heading\":false,\"text\":\"—Sí, y mucho más, don Antonio.\"},{\"heading\":false,\"text\":\"—¿Mucho más?\"},{\"heading\":false,\"text\":\"—¡Más, sí! De modo que usted tiene dos mujeres, don Antonio.\"},{\"heading\":false,\"text\":\"—No, no, no tengo más que una, una sola, la madre de mis hijos. La otra no es mi mujer, no sé si lo es del padre de su hija.\"},{\"heading\":false,\"text\":\"—Y esa tristeza...\"},{\"heading\":false,\"text\":\"—La ley es siempre triste, don Augusto. Y es más triste un amor que nace y se cría sobre la tumba de otro y como una planta que se alimenta, como de mantillo, de la podredumbre de otra planta. Crímenes, sí, crímenes ajenos nos han juntado, ¿y es nuestra unión acaso crimen? Ellos rompieron lo que no debe romperse, ¿por qué no habíamos nosotros de anudar los cabos sueltos?\"},{\"heading\":false,\"text\":\"—Y no han vuelto a saber...\"},{\"heading\":false,\"text\":\"—No hemos querido volver a saber. Y luego nuestra Rita es una mujercita ya; el mejor día se nos casa... Con mi nombre, por supuesto, con mi nombre, y haga luego la ley lo que quiera. Es mi hija y no del ladrón; yo la he criado.\"}]},{\"title\":\"Capítulo XXII\",\"blocks\":[{\"heading\":false,\"text\":\"—Y bien, ¿qué?—le preguntaba Augusto a Víctor—¿cómo habéis recibido al intruso?\"},{\"heading\":false,\"text\":\"—¡Ah, nunca lo hubiese creído, nunca! Todavía la víspera de nacer nuestra irritación era grandísima. Y mientras estaba pugnando por venir al mundo no sabes bien los insultos que me lanzaba mi Elena. «¡Tú, tú tienes la culpa, tú!», me decía. Y otras veces: «¡quítate de delante, quítate de mi vista! ¿no te da vergüenza de estar aquí? Si me muero, tuya será la culpa». Y otras veces: «¡ésta y no más, ésta y no más!» Pero nació y todo ha cambiado. Parece como si hubiésemos despertado de un sueño y como si acabáramos de casarnos. Yo me he quedado ciego, talmente ciego; ese chiquillo me ha cegado. Tan ciego estoy, que todos dicen que mi Elena ha quedado con la preñez y el parto desfiguradísima, que está hecha un esqueleto y que ha envejecido lo menos diez años, y a mí me parece más fresca, más lozana, más joven y hasta más metida en carnes que nunca.\"},{\"heading\":false,\"text\":\"—Eso me recuerda, Víctor, la leyenda del _fogueteiro_ que tengo oída en Portugal.\"},{\"heading\":false,\"text\":\"—Venga.\"},{\"heading\":false,\"text\":\"—Tú sabes que en Portugal eso de los fuegos artificiales, de la pirotecnia, es una verdadera bella arte. El que no ha visto fuegos artificiales en Portugal no sabe todo lo que se puede hacer con eso. ¡Y qué nomenclatura, Dios mío!\"},{\"heading\":false,\"text\":\"—Pero venga la leyenda.\"},{\"heading\":false,\"text\":\"—Allá voy. Pues el caso es que había en un pueblo portugués un pirotécnico o _fogueteiro_ que tenía una mujer hermosísima, que era su consuelo, su encanto y su orgullo. Estaba locamente enamorado de ella, pero aún más era orgullo. Complacíase en dar dentera, por así decirlo, a los demás mortales, y la paseaba consigo como diciéndoles: ¿veis esta mujer? ¿os gusta? ¿sí, eh?, ¡pues es la mía, mía sola! ¡y fastidiarse!\"},{\"heading\":false,\"text\":\"No hacía sino ponderar las excelencias de la hermosura de su mujer y hasta pretendía que era la inspiradora de sus más bellas producciones pirotécnicas, la musa de sus fuegos artificiales. Y hete que una vez preparando unos de éstos, mientras estaba, como de costumbre, su hermosa mujer a su lado para inspirarle, se le prende fuego la pólvora, hay una explosión y tienen que sacar a marido y mujer desvanecidos y con gravísimas quemaduras. A la mujer se le quemó buena parte de la cara y del busto, de tal manera que se quedó horriblemente desfigurada, pero él, el _fogueteiro_, tuvo la fortuna de quedarse ciego y no ver el desfiguramiento de su mujer. Y después de esto seguía orgulloso de la hermosura de su mujer y ponderándola a todos y caminando al lado de ella, convertida ahora en su lazarilla, con el mismo aire y talle de arrogante desafío que antes. «¿Han visto ustedes mujer más hermosa?», preguntaba, y todos, sabedores de su historia, se compadecían del pobre _fogueteiro_ y le ponderaban la hermosura de su mujer.\"},{\"heading\":false,\"text\":\"—Y bien, ¿no seguía siendo hermosa para él?\"},{\"heading\":false,\"text\":\"—Acaso más que antes, como para ti tu mujer después que te ha dado al intruso.\"},{\"heading\":false,\"text\":\"—¡No le llames así!\"},{\"heading\":false,\"text\":\"—Fué cosa tuya.\"},{\"heading\":false,\"text\":\"—Sí, pero no quiero oírsela a otro.\"},{\"heading\":false,\"text\":\"—Eso pasa mucho; el mote mismo que damos a alguien nos suena muy de otro modo cuando se lo oímos a otro.\"},{\"heading\":false,\"text\":\"—Sí, dicen que nadie conoce su voz...\"},{\"heading\":false,\"text\":\"—Ni su cara. Yo por lo menos sé de mí decirte que una de las cosas que me da más pavor es quedarme mirándome al espejo, a solas, cuando nadie me ve. Acabo por dudar de mi propia existencia e imaginarme, viéndome como otro, que soy un sueño, un ente de ficción...\"},{\"heading\":false,\"text\":\"—Pues no te mires así...\"},{\"heading\":false,\"text\":\"—No puedo remediarlo. Tengo la manía de la introspección.\"},{\"heading\":false,\"text\":\"—Pues acabarás como los faquires, que dicen se contemplan el propio ombligo.\"},{\"heading\":false,\"text\":\"—Y creo que si uno no conoce su voz ni su cara, tampoco conoce nada que sea suyo, muy suyo, como si fuera parte de él...\"},{\"heading\":false,\"text\":\"—Su mujer, por ejemplo.\"},{\"heading\":false,\"text\":\"—En efecto; se me antoja que debe de ser imposible conocer a aquella mujer con quien se convive y que acaba de formar parte nuestra. ¿No has oído aquello que decía uno de nuestros más grandes poetas, Campoamor?\"},{\"heading\":false,\"text\":\"—No; ¿qué es ello?\"},{\"heading\":false,\"text\":\"—Pues decía que cuando uno se casa, si lo hace enamorado de veras, al principio no puede tocar al cuerpo de su mujer sin emberrenchinarse y encenderse en deseo carnal, pero que pasa tiempo, se acostumbra, y llega un día en que lo mismo le es tocar con la mano al muslo desnudo de su mujer que al propio muslo suyo, pero también entonces, si tuvieran que cortarle a su mujer el muslo, le dolería como si le cortasen el propio.\"},{\"heading\":false,\"text\":\"—Y así es, en verdad. ¡No sabes cómo sufrí en el parto!\"},{\"heading\":false,\"text\":\"—Ella más.\"},{\"heading\":false,\"text\":\"—¡Quién sabe...! Y ahora como es ya algo mío, parte de mi ser, me he dado tan poco cuenta de eso que dicen de que se ha desfigurado y afeado, como no se da uno cuenta de que se desfigure, se envejece y se afea.\"},{\"heading\":false,\"text\":\"—Pero ¿crees de veras que uno no se da cuenta de que se envejece y afea?\"},{\"heading\":false,\"text\":\"—No, aunque lo diga. Si la cosa es continua y lenta. Ahora, si de repente le ocurre a uno algo... Pero eso de que se sienta uno envejecer, ¡quia!; lo que siente uno es que envejecen las cosas en derredor de él o que rejuvenecen. Y eso es lo único que siento ahora al tener un hijo. Porque ya sabes lo que suelen decir los padres señalando a sus hijos: «¡Estos, éstos son los que nos hacen viejos!» Ver crecer al hijo es lo más dulce y lo más terrible creo. No te cases, pues, Augusto, no te cases, si quieres gozar de la ilusión de una juventud eterna.\"},{\"heading\":false,\"text\":\"—Y ¿qué voy a hacer si no me caso? ¿en qué voy a pasar el tiempo?\"},{\"heading\":false,\"text\":\"—Dedícate a filósofo.\"},{\"heading\":false,\"text\":\"—Y ¿no es acaso el matrimonio la mejor, tal vez la única escuela de filosofía?\"},{\"heading\":false,\"text\":\"—¡No, hombre, no! Pues ¿no has visto cuántos y cuán grandes filósofos ha habido solteros? Que ahora recuerde, aparte de los que han sido frailes, tienes a Descartes, a Pascal, a Spinoza, a Kant...\"},{\"heading\":false,\"text\":\"—¡No me hables de los filósofos solteros!\"},{\"heading\":false,\"text\":\"—Y de Sócrates, ¿no recuerdas cómo despachó de su lado a su mujer Jantipa, el día en que había de morirse, para que no le perturbase?\"},{\"heading\":false,\"text\":\"—No me hables tampoco de eso. No me resuelvo a creer sino que eso que nos cuenta Platón no es sino una novela...\"},{\"heading\":false,\"text\":\"—O una _nivola_...\"},{\"heading\":false,\"text\":\"—Como quieras.\"},{\"heading\":false,\"text\":\"Y rompiendo bruscamente la voluptuosidad de la conversación se salió.\"},{\"heading\":false,\"text\":\"En la calle acercósele un mendigo diciéndole: «¡Una limosna, por Dios, señorito, que tengo siete hijos...!» «¡No haberlos hecho!»—le contestó malhumorado Augusto. «Ya quisiera yo haberle visto a usted en mi caso—replicó el mendigo, añadiendo: y ¿qué quiere usted que hagamos los pobres si no hacemos hijos... para los ricos?» «Tienes razón—replicó Augusto—, y por filósofo, ¡ahí va, toma!», y le dio una peseta, que el buen hombre se fué al punto a gastar a la taberna próxima.\"}]},{\"title\":\"Capítulo XXIII\",\"blocks\":[{\"heading\":false,\"text\":\"El pobre Augusto estaba consternado. No era sólo que se encontrase, como el asno de Buridán, entre Eugenia y Rosario; era que aquello de enamorarse de casi todas las que veía, en vez de amenguársele, íbale en medro. Y llegó a descubrir cosas fatales.\"},{\"heading\":false,\"text\":\"—¡Vete, vete, Liduvina, por Dios! ¡vete, déjame solo! ¡Anda, vete!—le decía una vez a su criada.\"},{\"heading\":false,\"text\":\"Y apenas ella se fué, apoyó los codos sobre la mesa, la cabeza en las palmas de las manos, y se dijo: «¡Esto es terrible, verdaderamente terrible! ¡Me parece que sin darme cuenta de ello me voy enamorando... hasta de Liduvina! ¡Pobre Domingo! Sin duda. Ella, a pesar de sus cincuenta años, aún está de buen ver, y sobre todo bien metida en carnes; y cuando alguna vez sale de la cocina con los brazos remangados y tan redondos... ¡vamos, que esto es una locura! ¡Y esa doble barbilla y esos pliegues que se le hacen en el cuello...! Esto es terrible, terrible, terrible...»\"},{\"heading\":false,\"text\":\"«Ven acá, Orfeo—prosiguió, cojiendo al perro—, ¿qué crees tú que debo yo hacer? ¿Cómo voy a defenderme de esto hasta, que al fin me decida y me case? ¡Ah, ya! ¡una idea, una idea luminosa, Orfeo! Convirtamos a la mujer, que así se me persigue, en materia de estudio. ¿Qué te parece de que me dedique a la psicología femenina? Sí, sí, y haré dos monografías, pues ahora se lleva mucho las monografías; una se titulará: _Eugenia_ y la otra: _Rosario_, añadiendo: _estudio de mujer_. ¿Qué te parece de mi idea, Orfeo?»\"},{\"heading\":false,\"text\":\"Y decidió ir a consultarlo con Antolín S. —o sea Sánchez— Paparrigópulos, que por entonces se dedicaba a estudios de mujeres, aunque más en los libros que no en la vida.\"},{\"heading\":false,\"text\":\"Antolín S. Paparrigópulos era lo que se dice un erudito, un joven que había de dar a la patria días de gloria dilucidando sus más ignoradas glorias. Y si el nombre de S. Paparrigópulos no sonaba aún entre los de aquella juventud bulliciosa que a fuerza de ruido quería atraer sobre sí la atención pública, era porque poseía la verdadera cualidad íntima de la fuerza: la paciencia, y porque era tal su respeto al público y a sí mismo que dilataba la hora de su presentación hasta que, suficientemente preparado, se sintiera seguro en el suelo que pisaba.\"},{\"heading\":false,\"text\":\"Muy lejos de buscar con cualquier novedad arlequinesca un efímero renombre de relumbrón cimentado sobre la ignorancia ajena, aspiraba en cuantos trabajos literarios tenía en proyecto a la perfección que en lo humano cabe y a no salirse, sobre todo, de los linderos de la sensatez y del buen gusto. No quería desafinar para hacerse oir, sino reforzar con su voz, debidamente disciplinada, la hermosa sinfonía genuinamente nacional y castiza.\"},{\"heading\":false,\"text\":\"La inteligencia de S. Paparrigópulos era clara, sobre todo clara, de una transparencia maravillosa, sin nebulosidades ni embolismos de ninguna especie. Pensaba en castellano neto, sin asomo alguno de hórridas brumas septentrionales ni dejos de decadentismos de bulevar parisiense, en limpio castellano, y así era cómo pensaba sólido y hondo, porque lo hacía con el alma del pueblo que lo sustentaba y a que debía su espíritu. Las nieblas hiperbóreas le parecían bien entre los bebedores de cerveza encabezada, pero no en esta clarísima España de esplendente cielo y de sano Valdepeñas enyesado. Su filosofía era la del malogrado Becerro de Bengoa, que después de llamar tío raro a Schopenhauer aseguraba que no se le habrían ocurrido a éste las cosas que se le ocurrieron, ni habría sido pesimista, de haber bebido Valdepeñas en vez de cerveza, y que decía también que la neurastenia proviene de meterse uno en lo que no le importa y que se cura con ensalada de burro.\"},{\"heading\":false,\"text\":\"Convencido S. Paparrigópulos de que en última instancia todo es forma, forma más o menos interior, el universo mismo un caleidoscopio de formas enchufadas las unas en las otras y de que por la forma viven cuantas grandes obras salvan los siglos, trabajaba con el esmero de los maravillosos artífices del Renacimiento el lenguaje que había de revestir a sus futuros trabajos.\"},{\"heading\":false,\"text\":\"Había tenido la virtuosa fortaleza de resistir a todas las corrientes de sentimentalismo neo-romántico y a esa moda asoladora por las cuestiones llamadas sociales. Convencido de que la cuestión social es insoluble aquí abajo, de que habrá siempre pobres y ricos y de que no puede esperarse más alivio que el que aporten la caridad de éstos y la resignación de aquéllos, apartaba su espíritu de disputas que a nada útil conducen y refugiábase en la purísima región del arte inmaculado, adonde no alcanza la broza de las pasiones y donde halla el hombre consolador refugio para las desilusiones de la vida. Abominaba, además, del estéril cosmopolitismo, que no hace sino sumir a los espíritus en ensueños de impotencia y en utopías enervadoras, y amaba a esta su idolatrada España, tan calumniada cuanto desconocida de no pocos de sus hijos; a esta España que le había de dar la materia prima de los trabajos sobre que fundaría su futura fama.\"},{\"heading\":false,\"text\":\"Dedicaba Paparrigópulos las poderosas energías de su espíritu a investigar la íntima vida pasada de nuestro pueblo, y era su labor tan abnegada como sólida. Aspiraba nada menos que a resucitar a los ojos de sus compatriotas nuestro pasado—es decir, el presente de sus bisabuelos—, y conocedor del engaño de cuantos lo intentaban a pura fantasía, buscaba y rebuscaba en todo género de viejas memorias para levantar sobre inconmovibles sillares el edificio de su erudita ciencia histórica. No había suceso pasado, por insignificante que pareciese, que no tuviera a sus ojos un precio inestimable.\"},{\"heading\":false,\"text\":\"Sabía que hay que aprender a ver el universo en una gota de agua, que con un hueso constituye el paleontólogo el animal entero y con un asa de puchero toda una vieja civilización el arqueólogo, sin desconocer tampoco que no debe mirarse a las estrellas con microscopio y con telescopio a un infusorio, como los humoristas acostumbran hacer para ver turbio. Mas aunque sabía que un asa de puchero bastaba al arqueólogo genial para reconstruir un arte enterrado en los limbos del olvido, como en su modestia no se tenía por genio, prefería dos asas a una asa sola—cuantas más asas mejor—y prefería el puchero todo al asa sola.\"},{\"heading\":false,\"text\":\"«Todo lo que en extensión parece ganarse, piérdese en intensidad»; tal era su lema. Sabía Paparrigópulos que en un trabajo el más especificado, en la más concreta monografía puede verterse una filosofía entera, y creía, sobre todo, en las maravillas de la diferenciación del trabajo y en el enorme progreso aportado a las ciencias por la abnegada legión de los pincha-ranas, caza-vocablos, barrunta-fechas y cuenta-gotas de toda laya.\"},{\"heading\":false,\"text\":\"Tentaban en especial su atención los más arduos y enrevesados problemas de nuestra historia literaria, tales como el de la patria de Prudencio, aunque últimamente, a consecuencia decíase de unas calabazas, se dedicaba al estudio de mujeres españolas de los pasados siglos.\"},{\"heading\":false,\"text\":\"En trabajos de índole al parecer insignificante era donde había que ver y admirar la agudeza, la sensatez, la perspicacia, la maravillosa intuición histórica y la penetración crítica de S. Paparrigópulos. Había que ver sus cualidades así, aplicadas y en concreto, sobre lo vivo, y no en abstracta y pura teoría; había que verle en la suerte. Cada disertación de aquéllas era todo un curso de lógica inductiva, un monumento tan maravilloso como la obra de Lionnet acerca de la oruga del sauce, y una muestra, sobre todo, de lo que es el austero amor a la santa Verdad. Huía de la ingeniosidad como de la peste y creía que sólo acostumbrándonos a respetar a la divina Verdad, aun en lo más pequeño, podremos rendirla el debido culto en lo grande.\"},{\"heading\":false,\"text\":\"Preparaba una edición popular de los apólogos de Calila y Dimna con una introducción acerca de la influencia de la literatura índica en la Edad Media española, y ojalá hubiese llegado a publicarla, porque su lectura habría apartado, de seguro, al pueblo de la taberna y de perniciosas doctrinas de imposibles redenciones económicas. Pero las dos obras magnas que proyectaba Paparrigópulos eran una historia de los escritores oscuros españoles, es decir, de aquellos que no figuran en las historias literarias corrientes o figuran sólo en rápida mención por la supuesta insignificancia de sus obras, corrijiendo así la injusticia de los tiempos, injusticia que tanto deploraba y aun temía, y era otra su obra acerca de aquellos cuyas obras se han perdido sin que nos quede más que la mención de sus nombres y a lo sumo la de los títulos de las que escribieron. Y estaba a punto de acometer la historia de aquellos otros que habiendo pensado escribir no llegaron a hacerlo.\"},{\"heading\":false,\"text\":\"Para el mejor logro de sus empresas, una vez nutrido del sustancioso meollo de nuestra literatura nacional, se había bañado en las extranjeras, y como esto se le hacía penoso, pues era torpe para lenguas extranjeras y su aprendizaje exige tiempo que para más altos estudios necesitaba, recurrió a un notable expediente, aprendido de su ilustre maestro. Y era que leía las principales obras de crítica e historia literaria que en el extranjero se publicaran, siempre que las hallase en francés, y una vez que había cojido la opinión media de los críticos más reputados, respecto a este o aquel autor, hojeábale en un periquete para cumplir con su conciencia y quedar libre para rehacer juicios ajenos sin mengua de su escrupulosa integridad de crítico.\"},{\"heading\":false,\"text\":\"Vese, pues, que no era S. Paparrigópulos uno de esos jóvenes espíritus vagabundos y erráticos que se pasean sin rumbo fijo por los dominios del pensamiento y de la fantasía, lanzando acaso acá y allá tal cual fugitivo chispazo, ¡no! Sus tendencias eran rigurosa y sólidamente itinerarias; era de los que van a alguna parte. Si en sus estudios no habría de aparecer nada saliente deberíase a que en ellos todo era cima, siendo a modo de mesetas, trasunto fiel de las vastas y soleadas llanuras castellanas donde ondea la mies dorada y sustanciosa.\"},{\"heading\":false,\"text\":\"¡Así diera la Providencia a España muchos Antolines Sánchez Paparrigópulos! Con ellos, haciéndonos todos dueños de nuestro tradicional peculio, podríamos sacarle pingües rendimientos. Paparrigópulos aspiraba—y aspira, pues aún vive y sigue preparando sus trabajos—a introducir la reja de su arado crítico, aunque solo sea un centímetro más que los aradores que le habían precedido en su campo, para que la mies crezca, merced a nuevos jugos, más lozana y granen mejor las espigas y la harina sea más rica y comamos los españoles mejor pan espiritual y más barato.\"},{\"heading\":false,\"text\":\"Hemos dicho que Paparrigópulos sigue trabajando y preparando sus trabajos para darlos a luz. Y así es. Augusto había tenido noticia de los estudios de mujeres a que se dedicaba por comunes amigos de uno y de otro, pero no había publicado nada ni lo ha publicado todavía.\"},{\"heading\":false,\"text\":\"No faltan otros eruditos que con la característica caridad de la especie, habiendo vislumbrado a Paparrigópulos y envidiosos de antemano de la fama que preven le espera, tratan de empequeñecerle. Tal hay que dice de Paparrigópulos que, como el zorro, borra con el jopo sus propias huellas, dando luego vueltas y más vueltas por otros derroteros para despistar al cazador y que no se sepa por dónde fué a atrapar la gallina, cuando si de algo peca es de dejar en pie los andamios, una vez acabada la torre, impidiendo así que se admire y vea bien ésta. Otro le llama desdeñosamente concinador, como si el de concinar no fuese arte supremo. El de más allá le acusa, ya de traducir, ya de arreglar ideas tomadas del extranjero, olvidando que al revestirlas Paparrigópulos en tan neto, castizo y transparente castellano como es el suyo, las hace castellanas y por ende propias no de otro modo que hizo el P. Isla propio el _Gil Blas_ de Lesage. Alguno le moteja de que su principal apoyo es su honda fe en la ignorancia ambiente, desconociendo el que así le juzga que la fe es transportadora de montañas. Pero la suprema injusticia de estos y otros rencorosos juicios de gentes a quienes Paparrigópulos ningún mal ha hecho, su injusticia notoria, se verá bien clara con sólo tener en cuenta que todavía no ha dado Paparrigópulos nada a luz y que todos los que le muerden los zancajos hablan de oídas y por no callar.\"},{\"heading\":false,\"text\":\"No se puede, en fin, escribir de este erudito singular sino con reposada serenidad y sin efectismos _nivolescos_ de ninguna clase.\"},{\"heading\":false,\"text\":\"En este hombre, quiero decir, en este erudito, pues, pensó Augusto, sabedor de que se dedicaba a estudios de mujeres, claro está que en los libros, que es tratándose de ellas lo menos expuesto, y de mujeres de pasados siglos, que son también mucho menos expuestas para quien las estudia que las mujeres de hoy.\"},{\"heading\":false,\"text\":\"A este Antolín, erudito solitario que por timidez de dirigirse a las mujeres en la vida y para vengarse de esa timidez las estudiaba en los libros, fué a quien acudió a ver Augusto para de él aconsejarse.\"},{\"heading\":false,\"text\":\"No bien le hubo expuesto su propósito prorrumpió el erudito:\"},{\"heading\":false,\"text\":\"—¡Ay, pobre señor Pérez, cómo le compadezco a usted! ¿Quiere estudiar a la mujer? Tarea le mando...\"},{\"heading\":false,\"text\":\"—Como usted la estudia...\"},{\"heading\":false,\"text\":\"—Hay que sacrificarse. El estudio, y el estudio oscuro, paciente, silencioso, es mi razón de ser en la vida. Pero yo, ya lo sabe usted, soy un modesto, modestísimo obrero del pensamiento, que acopio y ordeno materiales para que otros que vengan detrás de mí sepan aprovecharlos. La obra humana es colectiva; nada que no sea colectivo es ni sólido ni durable...\"},{\"heading\":false,\"text\":\"—¿Y las obras de los grandes genios? _La Divina Comedia_, la _Eneida_, una tragedia de Shakespeare, un cuadro de Velázquez...\"},{\"heading\":false,\"text\":\"—Todo eso es colectivo, mucho más colectivo de lo que se cree. _La Divina Comedia_, por ejemplo, fué preparada por toda una serie...\"},{\"heading\":false,\"text\":\"—Sí, ya sé eso.\"},{\"heading\":false,\"text\":\"—Y respecto a Velázquez... a propósito, ¿conoce usted el libro de Justi sobre él?\"},{\"heading\":false,\"text\":\"Para Antolín, el principal, casi el único valor de las grandes obras maestras del ingenio humano, consiste en haber provocado un libro de crítica o de comentario; los grandes artistas, poetas, pintores, músicos, historiadores, filósofos, han nacido para que un erudito haga su biografía y un crítico comente sus obras, y una frase cualquiera de un gran escritor directo no adquiere valor hasta que un erudito no la repite y cita la obra, la edición y la página en que la expuso. Y todo aquello de la solidaridad del trabajo colectivo no era más que envidia e impotencia. Pertenecía a la clase de esos comentadores de Homero que si Homero mismo redivivo entrase en su oficina cantando le echarían a empellones porque les estorbaba el trabajar sobre los textos muertos de sus obras y buscar un _apax_ cualquiera en ellas.\"},{\"heading\":false,\"text\":\"—Pero, bien, ¿qué opina usted de la psicología femenina?—le preguntó Augusto.\"},{\"heading\":false,\"text\":\"—Una pregunta así, tan vaga, tan genérica, tan en abstracto, no tiene sentido preciso para un modesto investigador como yo, amigo Pérez, para un hombre que no siendo genio, ni deseando serlo...\"},{\"heading\":false,\"text\":\"—¿Ni deseando?\"},{\"heading\":false,\"text\":\"—Sí, ni deseando. Es mal oficio. Pues bien, esa pregunta carece de sentido preciso para mí. El contestarla exigiría...\"},{\"heading\":false,\"text\":\"—Sí, vamos, como aquel otro cofrade de usted que escribió un libro sobre psicología del pueblo español y siendo, al parecer, español él y viviendo entre españoles, no se le ocurrió sino decir que éste dice esto y aquél aquello otro y hacer una bibliografía.\"},{\"heading\":false,\"text\":\"—¡Ah, la bibliografía! Sí, ya sé...\"},{\"heading\":false,\"text\":\"—No, no siga usted, amigo Paparrigópulos, y dígame lo más concretamente que sepa y pueda, qué le parece de la psicología femenina.\"},{\"heading\":false,\"text\":\"—Habría que empezar por plantear una primera cuestión y es la de si la mujer tiene alma.\"},{\"heading\":false,\"text\":\"—¡Hombre!\"},{\"heading\":false,\"text\":\"—Ah, no sirve desecharla así, tan en absoluto...\"},{\"heading\":false,\"text\":\"«¿La tendrá él?», pensó Augusto, y luego:\"},{\"heading\":false,\"text\":\"—Bueno, pues de lo que en las mujeres hace las veces de alma... ¿qué cree usted?\"},{\"heading\":false,\"text\":\"—¿Me promete usted, amigo Pérez, guardarme el secreto de lo que le voy a decir?... Aunque, no, no, usted no es erudito.\"},{\"heading\":false,\"text\":\"—¿Qué quiere usted decir con eso?\"},{\"heading\":false,\"text\":\"—Que usted no es uno de esos que están a robarle a uno lo último que le hayan oído y darlo como suyo...\"},{\"heading\":false,\"text\":\"—Pero ¿ésas tenemos...?\"},{\"heading\":false,\"text\":\"—Ay, amigo Pérez, el erudito es por naturaleza un ladronzuelo; se lo digo a usted yo, yo, yo que lo soy. Los eruditos andamos a quitarnos unos a otros las pequeñas cositas que averiguamos y a impedir que otro se nos adelante.\"},{\"heading\":false,\"text\":\"—Se comprende: el que tiene almacén guarda su género con más celo que el que tiene fábrica; hay que guardar el agua del pozo, no la del manantial.\"},{\"heading\":false,\"text\":\"—Puede ser. Pues bien, si usted, que no es erudito, me promete guardarme el secreto hasta que yo lo revele, le diré que he encontrado en un oscuro y casi desconocido escritor holandés del siglo XVII una interesantísima teoría respecto al alma de la mujer...\"},{\"heading\":false,\"text\":\"—Veámosla.\"},{\"heading\":false,\"text\":\"—Dice ese escritor, y lo dice en latín, que así como cada hombre tiene su alma, las mujeres todas no tienen sino una sola y misma alma, un alma colectiva, algo así como el entendimiento agente de Averroes, repartida entre todas ellas. Y añade que las diferencias que se observan en el modo de sentir, pensar y querer de cada mujer provienen no más que de las diferencias del cuerpo, debidas a raza, clima, alimentación, etc., y que por eso son tan insignificantes. Las mujeres, dice ese escritor, se parecen entre sí mucho más que los hombres y es porque todas son una sola y misma mujer...\"},{\"heading\":false,\"text\":\"—Ve ahí por qué, amigo Paparrigópulos, así que me enamoré de una me sentí enseguida enamorado de todas las demás.\"},{\"heading\":false,\"text\":\"—¡Claro está! Y añade ese interesantísimo y casi desconocido ginecólogo que la mujer tiene mucha más individualidad, pero mucha menos personalidad, que el hombre; cada una de ellas se siente más ella, más individual, que cada hombre, pero con menos contenido.\"},{\"heading\":false,\"text\":\"—Sí, sí, creo entrever lo que sea.\"},{\"heading\":false,\"text\":\"—Y por eso, amigo Pérez, lo mismo da que estudie usted a una mujer o a varias. La cuestión es ahondar en aquella a cuyo estudio usted se dedique.\"},{\"heading\":false,\"text\":\"—Y ¿no sería mejor tomar dos o más para poder hacer el estudio comparativo? Porque ya sabe usted que ahora se lleva mucho esto de lo comparativo...\"},{\"heading\":false,\"text\":\"—En efecto, la ciencia es comparación; mas en punto a mujeres no es menester comparar. Quien conozca una, una sola bien, las conoce todas, conoce a la Mujer. Además, ya sabe usted que todo lo que se gana en extensión se pierde en intensidad.\"},{\"heading\":false,\"text\":\"—En efecto, y yo deseo dedicarme al cultivo intensivo y no al extensivo de la mujer. Pero dos por lo menos... por lo menos dos...\"},{\"heading\":false,\"text\":\"—¡No, dos no! ¡de ninguna manera! De no contentarse con una, que yo creo es lo mejor y es bastante tarea, por lo menos tres. La dualidad no cierra.\"},{\"heading\":false,\"text\":\"—¿Cómo que no cierra la dualidad?\"},{\"heading\":false,\"text\":\"—Claro está. Con dos líneas no se cierra espacio. El más sencillo polígono es el triángulo. Por lo menos tres.\"},{\"heading\":false,\"text\":\"—Pero el triángulo carece de profundidad. El más sencillo poliedro es el tetraedro; de modo que por lo menos cuatro.\"},{\"heading\":false,\"text\":\"—Pero dos no, ¡nunca! De pasar de una, por lo menos tres. Pero ahonde usted en una.\"},{\"heading\":false,\"text\":\"—Tal es mi propósito.\"}]},{\"title\":\"Capítulo XXIV\",\"blocks\":[{\"heading\":false,\"text\":\"Cuando salió Augusto de su entrevista con Paparrigópulos íbase diciendo: «De modo que tengo que renunciar a una de las dos o buscar una tercera. Aunque para esto del estudio psicológico bien me puede servir de tercer término, de término puramente ideal de comparación, Liduvina. Tengo, pues, tres: Eugenia, que me habla a la imaginación, a la cabeza; Rosario, que me habla al corazón, y Liduvina, mi cocinera, que me habla al estómago. Y cabeza, corazón y estómago son las tres facultades del alma que otros llaman inteligencia, sentimiento y voluntad. Se piensa con la cabeza, se siente con el corazón y se quiere con el estómago. ¡Esto es evidente! Y ahora...»\"},{\"heading\":false,\"text\":\"«Ahora—prosiguió pensando—, ¡una idea luminosa, luminosísima! Voy a fingir que quiero pretender de nuevo a Eugenia, voy a solicitarla de nuevo, a ver si me admite de novio, de futuro marido, claro que no más que para probarla, como un experimento psicológico y seguro como estoy de que ella me rechazará... ¡pues no faltaba más! Tiene que rechazarme. Después de lo pasado, después de lo que en nuestra última entrevista me dijo, no es posible ya que me admita. Es una mujer de palabra, creo. Mas... ¿es que las mujeres tienen palabra? ¿es que la mujer, la Mujer, así, con letra mayúscula, la única, la que se reparte entre millones de cuerpos femeninos y más o menos hermosos—más bien más que menos—; es que la Mujer está obligada a guardar su palabra? Eso de guardar su palabra, ¿no es acaso masculino? Pero ¡no, no! Eugenia no puede admitirme; no me quiere. No me quiere y aceptó ya mi dádiva. Y si aceptó mi dádiva y la disfruta, ¿para qué va a quererme?»\"},{\"heading\":false,\"text\":\"«Pero... ¿Y si, volviéndose atrás de lo que me dijo—pensó luego—, me dice que sí y me acepta como novio, como futuro marido? Porque hay que ponerse en todo. ¿Y si me acepta?, digo. ¡Me fastidia! ¡Me pesca con mi propio anzuelo! ¡Eso sí que sería el pescador pescado! Pero ¡no, no! ¡no puede ser! ¿Y si es? ¡Ah! Entonces no queda sino resignarse. ¿Resignarse? Sí, resignarse. Hay que saber resignarse a la buena fortuna. Y acaso la resignación a la dicha es la ciencia más difícil. ¿No nos dice Píndaro que las desgracias todas de Tántalo le provinieron de no haber podido digerir su felicidad? ¡Hay que digerir la felicidad! Y si Eugenia me dice que sí, si me acepta, entonces... ¡venció la psicología! ¡Viva la psicología! Pero ¡no, no, no! No me aceptará, no puede aceptarme, aunque sólo sea por salirse con la suya. Una mujer como Eugenia no da su brazo a torcer; la Mujer, cuando se pone frente al Hombre a ver cuál es de más tesón y constancia en sus propósitos, es capaz de todo... ¡No, no me aceptará!»\"},{\"heading\":false,\"text\":\"—Rosarito le espera.\"},{\"heading\":false,\"text\":\"Con estas tres palabras, preñadas de sentimientos, interrumpió Liduvina el curso de las reflexiones de su amo.\"},{\"heading\":false,\"text\":\"—Di, Liduvina, ¿crees tú que las mujeres sois fieles a lo que una vez hayáis dicho? ¿sabéis guardar vuestra palabra?\"},{\"heading\":false,\"text\":\"—Según y conforme.\"},{\"heading\":false,\"text\":\"—Sí, el estribillo de tu marido. Pero contesta derechamente y no como acostumbráis hacer las mujeres, que rara vez contestáis a lo que se os pregunta, sino a lo que se os figuraba que se os iba a preguntar.\"},{\"heading\":false,\"text\":\"—Y ¿qué es lo que usted quiso preguntarme?\"},{\"heading\":false,\"text\":\"—Que si vosotras las mujeres guardáis una palabra que hubiéseis dado.\"},{\"heading\":false,\"text\":\"—Según la palabra.\"},{\"heading\":false,\"text\":\"—¿Cómo según la palabra?\"},{\"heading\":false,\"text\":\"—Pues claro está. Unas palabras se dan para guardarlas y otras para no guardarlas. Ya nadie se engaña, porque es valor entendido...\"},{\"heading\":false,\"text\":\"—Bueno, bueno, di a Rosario que entre.\"},{\"heading\":false,\"text\":\"Y cuando Rosario entró preguntóle Augusto:\"},{\"heading\":false,\"text\":\"—Di, Rosario, ¿qué crees tú, que una mujer debe guardar la palabra que dio o que no debe guardarla?\"},{\"heading\":false,\"text\":\"—No recuerdo haberle dado a usted palabra alguna...\"},{\"heading\":false,\"text\":\"—No se trata de eso, sino de si debe o no una mujer guardar la palabra que dio...\"},{\"heading\":false,\"text\":\"—Ah, sí, lo dice usted por la otra... por esa mujer...\"},{\"heading\":false,\"text\":\"—Por lo que lo diga; ¿qué crees tú?\"},{\"heading\":false,\"text\":\"—Pues yo no entiendo de esas cosas...\"},{\"heading\":false,\"text\":\"—¡No importa!\"},{\"heading\":false,\"text\":\"—Bueno, ya que usted se empeña, le diré que lo mejor es no dar palabra alguna.\"},{\"heading\":false,\"text\":\"—¿Y si se ha dado?\"},{\"heading\":false,\"text\":\"—No haberlo hecho.\"},{\"heading\":false,\"text\":\"«Está visto—se dijo Augusto—que a esta mozuela no la saco de ahí. Pero ya que está aquí, voy a poner en juego la psicología, a llevar a cabo un experimento.»\"},{\"heading\":false,\"text\":\"—¡Ven acá, siéntate aquí!—y le ofreció sus rodillas.\"},{\"heading\":false,\"text\":\"La muchacha obedeció tranquilamente y sin inmutarse, como a cosa acordada y prevista. Augusto en cambio quedóse confuso y sin saber por dónde empezar su experiencia psicológica. Y como no sabía qué decir, pues... hacía. Apretaba a Rosario contra su pecho anhelante y le cubría la cara de besos, diciéndose entre tanto: «Me parece que voy a perder la sangre fría necesaria para la investigación psicológica». Hasta que de pronto se detuvo, pareció calmarse, apartó a Rosario algo de sí y la dijo de repente:\"},{\"heading\":false,\"text\":\"—Pero ¿no sabes que quiero a otra mujer?\"},{\"heading\":false,\"text\":\"Rosario se calló, mirándole fijamente y encojiéndose de hombros.\"},{\"heading\":false,\"text\":\"—Pero ¿no lo sabes?—repitió él.\"},{\"heading\":false,\"text\":\"—¿Y a mí qué me importa eso ahora...?\"},{\"heading\":false,\"text\":\"—¿Cómo que no te importa?\"},{\"heading\":false,\"text\":\"—¡Ahora, no! Ahora me quiere usted a mí, me parece.\"},{\"heading\":false,\"text\":\"—Y a mí también me parece, pero...\"},{\"heading\":false,\"text\":\"Y entonces ocurrió algo insólito, algo que no entraba en las previsiones de Augusto, en su programa de experiencias psicológicas sobre la Mujer, y es que Rosario, bruscamente, le enlazó los brazos al cuello y empezó a besarle. Apenas si el pobre hombre tuvo tiempo para pensar: «Ahora soy yo el experimentado; esta mozuela está haciendo estudios de psicología masculina». Y sin darse cuenta de lo que hacía sorprendióse acariciando con las temblorosas manos las pantorrillas de Rosario.\"},{\"heading\":false,\"text\":\"Levantóse de pronto Augusto, levantó luego en vilo a Rosario y la echó en el sofá. Ella se dejaba hacer, con el rostro encendido. Y él, teniéndola sujeta de los brazos con sus dos manos, se le quedó mirando a los ojos.\"},{\"heading\":false,\"text\":\"—¡No los cierres, Rosario, no los cierres, por Dios! Ábrelos. Así, así, cada vez más. Déjame que me vea en ellos, tan chiquitito...\"},{\"heading\":false,\"text\":\"Y al verse a sí mismo en aquellos ojos como en un espejo vivo, sintió que la primera exaltación se le iba templando.\"},{\"heading\":false,\"text\":\"—Déjame que me vea en ellos como en un espejo, que me vea tan chiquitito... Sólo así llegaré a conocerme... viéndome en ojos de mujer...\"},{\"heading\":false,\"text\":\"Y el espejo le miraba de un modo extraño. Rosario pensaba: «Este hombre no me parece como los demás; debe de estar loco».\"},{\"heading\":false,\"text\":\"Apartóse de pronto de ella Augusto, se miró a sí mismo, y luego se palpó, exclamando al cabo:\"},{\"heading\":false,\"text\":\"—Y ahora, Rosario, perdóname.\"},{\"heading\":false,\"text\":\"—¿Perdonarle? ¿por qué?\"},{\"heading\":false,\"text\":\"Y había en la voz de la pobre Rosario más miedo que otro sentimiento alguno. Sentía deseos de huir, porque ella se decía: «Cuando uno empieza a decir o hacer incongruencias no sé adónde va a parar. Este hombre sería capaz de matarme en un arrebato de locura». Y le brotaron unas lágrimas.\"},{\"heading\":false,\"text\":\"—¿Lo ves?—le dijo Augusto—¿lo ves? Sí, perdóname, Rosarito, perdóname; no sabía lo que me hacía.\"},{\"heading\":false,\"text\":\"Y ella pensó: «Lo que no sabe es lo que no se hace».\"},{\"heading\":false,\"text\":\"—Y ahora, ¡vete, vete!\"},{\"heading\":false,\"text\":\"—¿Me echa usted?\"},{\"heading\":false,\"text\":\"—No, me defiendo. ¡No te echo, no! ¡Dios me libre! Si quieres me iré yo y te quedas aquí tú, para que veas que no te echo.\"},{\"heading\":false,\"text\":\"«Decididamente, no está bueno», pensó ella y sintió lástima de él.\"},{\"heading\":false,\"text\":\"—Vete, vete, y no me olvides, ¿eh?—le cojió de la barbilla, acariciándosela—. No me olvides; no olvides al pobre Augusto.\"},{\"heading\":false,\"text\":\"La abrazó y la dio un largo y apretado beso en la boca. Al salir la muchacha le dirigió una mirada llena de un misterioso miedo. Y apenas ella salió, pensó para sí Augusto: «Me desprecia, indudablemente me desprecia; he estado ridículo, ridículo, ridículo... Pero ¿qué sabe ella, pobrecita, de estas cosas? ¿Qué sabe ella de psicología?»\"},{\"heading\":false,\"text\":\"Si el pobre Augusto hubiese podido entonces leer en el espíritu de Rosario habríase desesperado más. Porque la ingenua mozuela iba pensando: «Cualquier día vuelvo a darme yo un rato así a beneficio de la otra prójima...»\"},{\"heading\":false,\"text\":\"Íbale volviendo la exaltación a Augusto. Sentía que el tiempo perdido no vuelve trayendo las ocasiones que se desperdiciaron. Entróle una rabia contra sí mismo. Sin saber qué hacía y por ocupar el tiempo llamó a Liduvina. Y al verla ante sí, tan serena, tan rolliza, sonriéndose maliciosamente, fué tal y tan insólito el sentimiento que le invadió, que diciéndole: «¡vete, vete, vete!», se salió a la calle. Es que temió un momento no poder contenerse y asaltar a Liduvina.\"},{\"heading\":false,\"text\":\"Al salir a la calle se encalmó. La muchedumbre es como un bosque; le pone a uno en su lugar, le reencaja.\"},{\"heading\":false,\"text\":\"«¿Estaré bien de la cabeza?», iba pensando Augusto. «¿No será acaso que mientras yo creo ir formalmente por la calle, como las personas normales—¿y qué es una persona normal?—, vaya haciendo gestos, contorsiones y pantomimas, y que la gente que yo creo pasa sin mirarme o que me mira indiferentemente no sea así, sino que están todos fijos en mí y riéndose o compadeciéndome...? Y esta ocurrencia, ¿no es acaso locura? ¿Estaré de veras loco? Y en último caso, aunque lo esté, ¿qué? Un hombre de corazón, sensible, bueno, si no se vuelve loco es por ser un perfecto majadero. El que no está loco es o tonto o pillo. Lo que no quiere decir, claro está, que los pillos y los tontos no enloquezcan.»\"},{\"heading\":false,\"text\":\"«Lo que he hecho con Rosarito—prosiguió pensando—ha sido ridículo, sencillamente ridículo. ¿Qué habrá pensado de mí? Y ¿qué me importa lo que de mí piense una mozuela así?... ¡pobrecilla! Pero... ¡con qué ingenuidad se dejaba hacer! Es un ser fisiológico, perfectamente fisiológico, nada más que fisiológico, sin psicología alguna. Es inútil, pues, tomarla de conejilla de Indias o de ranita para experimentos psicológicos. A lo sumo fisiológicos... Pero ¿es que la psicología, y sobre todo la femenina, es algo más que fisiología, o si se quiere psicología fisiológica? ¿Tiene la mujer alma? Y a mí para meterme en experimentos psicofisiológicos me falta preparación técnica. Nunca asistí a ningún laboratorio... carezco, además, de aparatos. Y la psicofisiología exige aparatos. ¿Estaré, pues, loco?»\"},{\"heading\":false,\"text\":\"Después de haberse desahogado con estas meditaciones callejeras, por en medio de la atareada muchedumbre indiferente a sus cuitas, sintióse ya tranquilo y se volvió a casa.\"}]},{\"title\":\"Capítulo XXV\",\"blocks\":[{\"heading\":false,\"text\":\"Fué Augusto a ver a Víctor, a acariciar al tardío hijo de éste, a recrearse en la contemplación de la nueva felicidad de aquel hogar, y de paso a consultar con él sobre el estado de su espíritu. Y al encontrarse con su amigo a solas, le dijo:\"},{\"heading\":false,\"text\":\"—¿Y de aquella novela o... ¿cómo era?... ¡ah, sí, _nivola!_... que estabas escribiendo? ¿supongo que ahora, con lo del hijo, la habrás abandonado?\"},{\"heading\":false,\"text\":\"—Pues supones mal. Precisamente por eso, por ser ya padre, he vuelto a ella. Y en ella desahogo el buen humor que me llena.\"},{\"heading\":false,\"text\":\"—¿Querrías leerme algo de ella?\"},{\"heading\":false,\"text\":\"Sacó Víctor las cuartillas y empezó a leer por aquí y por allá a su amigo.\"},{\"heading\":false,\"text\":\"—Pero, hombre, ¡te me han cambiado!—exclamó Augusto.\"},{\"heading\":false,\"text\":\"—¿Por qué?\"},{\"heading\":false,\"text\":\"—Porque ahí hay cosas que rayan en lo pornográfico y hasta a las veces pasan de ello...\"},{\"heading\":false,\"text\":\"—¿Pornográfico? ¡De ninguna manera! Lo que hay aquí son crudezas, pero no pornografía. Alguna vez algún desnudo, pero nunca un desvestido. Lo que hay es realismo...\"},{\"heading\":false,\"text\":\"—Realismo, sí, y además...\"},{\"heading\":false,\"text\":\"—Cinismo, ¿no es eso?\"},{\"heading\":false,\"text\":\"—¡Cinismo, sí!\"},{\"heading\":false,\"text\":\"—Pero el cinismo no es pornografía. Estas crudezas son un modo de excitar la imaginación para conducirla a un examen más penetrante de la realidad de las cosas; estas crudezas son crudezas... pedagógicas. ¡Lo dicho, pedagógicas!\"},{\"heading\":false,\"text\":\"—Y algo grotescas...\"},{\"heading\":false,\"text\":\"—En efecto, no te lo niego. Gusto de la bufonería.\"},{\"heading\":false,\"text\":\"—Que es siempre en el fondo tétrica.\"},{\"heading\":false,\"text\":\"—Por lo mismo. No me agradan sino los chistes lúgubres, las gracias funerarias. La risa por la risa misma me da grima, y hasta miedo. La risa no es sino la preparación para la tragedia.\"},{\"heading\":false,\"text\":\"—Pues a mí esas bufonadas crudas me producen un detestable efecto.\"},{\"heading\":false,\"text\":\"—Porque eres un solitario, Augusto, un solitario, entiéndemelo bien, un solitario... Y yo las escribo para curar... No, no, no las escribo para nada, sino porque me divierte escribirlas, y si divierten a los que las lean me doy por pagado. Pero si a la vez logro con ellas poner en camino de curación a algún solitario como tú, de doble soledad...\"},{\"heading\":false,\"text\":\"—¿Doble?\"},{\"heading\":false,\"text\":\"—Sí, soledad de cuerpo y soledad de alma.\"},{\"heading\":false,\"text\":\"—A propósito, Víctor.\"},{\"heading\":false,\"text\":\"—Sí, ya sé lo que vas a decirme. Venías a consultarme sobre tu estado, que desde hace algún tiempo es alarmante, verdaderamente alarmante, ¿no es eso?\"},{\"heading\":false,\"text\":\"—Sí, eso es.\"},{\"heading\":false,\"text\":\"—Lo adiviné. Pues bien, Augusto, cásate y cásate cuanto antes.\"},{\"heading\":false,\"text\":\"—Pero ¿con cuál?\"},{\"heading\":false,\"text\":\"—¡Ah!, pero ¿hay más de una?\"},{\"heading\":false,\"text\":\"—Y ¿cómo has adivinado también esto?\"},{\"heading\":false,\"text\":\"—Muy sencillo. Si hubieses preguntado: pero ¿con quién?, no habría supuesto que hay más de una ni que esa una haya; mas al preguntar: pero ¿con cuál?, se entiende con cuál de las dos, o tres, o diez, o ene.\"},{\"heading\":false,\"text\":\"—Es verdad.\"},{\"heading\":false,\"text\":\"—Cásate, pues, cásate, con una cualquiera de las ene de que estás enamorado, con la que tengas más a mano. Y sin pensarlo demasiado. Ya ves, yo me casé sin pensarlo; nos tuvieron que casar.\"},{\"heading\":false,\"text\":\"—Es que ahora me ha dado por dedicarme a las experiencias de psicología femenina.\"},{\"heading\":false,\"text\":\"—La única experiencia psicológica sobre la Mujer es el matrimonio. El que no se casa, jamás podrá experimentar psicológicamente el alma de la Mujer. El único laboratorio de psicología femenina o de ginepsicología es el matrimonio.\"},{\"heading\":false,\"text\":\"—Pero ¡eso no tiene remedio!\"},{\"heading\":false,\"text\":\"—Ninguna experimentación de verdad le tiene. Todo el que se mete a querer experimentar algo, pero guardando la retirada, no quemando las naves, nunca sabe nada de cierto. Jamás te fíes de otro cirujano que de aquel que se haya amputado a sí mismo algún propio miembro, ni te entregues a alienista que no esté loco. Cásate, pues, si quieres saber psicología.\"},{\"heading\":false,\"text\":\"—De modo que los solteros...\"},{\"heading\":false,\"text\":\"—La de los solteros no es psicología; no es más que metafísica, es decir, más allá de la física, más allá de lo natural.\"},{\"heading\":false,\"text\":\"—Y ¿qué es eso?\"},{\"heading\":false,\"text\":\"—Poco menos que en lo que estás tú.\"},{\"heading\":false,\"text\":\"—¿Yo estoy en la metafísica? Pero ¡si yo, querido Víctor, no estoy más allá de lo natural, sino más acá de ello!\"},{\"heading\":false,\"text\":\"—Es igual.\"},{\"heading\":false,\"text\":\"—¿Cómo que es igual?\"},{\"heading\":false,\"text\":\"—Sí, más acá de lo natural es lo mismo que más allá, como más allá del espacio es lo mismo que más acá de él. ¿Ves esta línea?—y trazó una línea en un papel. Prolóngala por uno y otro extremo al infinito y los extremos se encontrarán, cerrarán en el infinito, donde se encuentra todo y todo se lía. Toda recta es curva de una circunferencia de radio infinito y en el infinito cierra. Luego lo mismo da lo de más acá de lo natural que lo de más allá. ¿No está claro?\"},{\"heading\":false,\"text\":\"—No, está oscurísimo, muy oscuro.\"},{\"heading\":false,\"text\":\"—Pues porque está tan oscuro, cásate.\"},{\"heading\":false,\"text\":\"—Sí, pero... ¡me asaltan tantas dudas!\"},{\"heading\":false,\"text\":\"—Mejor, pequeño Hamlet, mejor. ¿Dudas?, luego piensas; ¿piensas?, luego eres.\"},{\"heading\":false,\"text\":\"—Sí, dudar es pensar.\"},{\"heading\":false,\"text\":\"—Y pensar es dudar y nada más que dudar. Se cree, se sabe, se imagina sin dudar; ni la fe, ni el conocimiento, ni la imaginación suponen duda y hasta la duda las destruye, pero no se piensa sin dudar. Y es la duda lo que de la fe y del conocimiento, que son algo estático, quieto, muerto, hace pensamiento, que es dinámico, inquieto, vivo.\"},{\"heading\":false,\"text\":\"—¿Y la imaginación?\"},{\"heading\":false,\"text\":\"—Sí, ahí cabe alguna duda. Suelo dudar lo que les he de hacer decir o hacer a los personajes de mi _nivola_, y aun después de que les he hecho decir o hacer algo dudo de si estuvo bien y si es lo que en verdad les corresponde. Pero... ¡paso por todo! Sí, sí, cabe duda en el imaginar, que es un pensar...\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"_Mientras Augusto y Víctor sostenían esta conversación_ nivolesca, _yo, el autor de esta_ nivola, _que tienes, lector, en la mano y estás leyendo, me sonreía enigmáticamente al ver que mis_ nivolescos _personajes estaban abogando por mí y justificando mis procedimientos, y me decía a mí mismo: «¡cuán lejos estarán estos infelices de pensar que no están haciendo otra cosa que tratar de justificar lo que yo estoy haciendo con ellos! Así cuando uno busca razones para justificarse no hace en rigor otra cosa que justificar a Dios. Y yo soy el Dios de estos dos pobres diablos_ nivolescos.»\"}]},{\"title\":\"Capítulo XXVI\",\"blocks\":[{\"heading\":false,\"text\":\"Augusto se dirigió a casa de Eugenia dispuesto a tentar la última experiencia psicológica, la definitiva, aunque temiendo que ella le rechazase. Y encontróse con ella en la escalera, que bajaba para salir cuando él subía para entrar.\"},{\"heading\":false,\"text\":\"—¿Usted por aquí, don Augusto?\"},{\"heading\":false,\"text\":\"—Sí, yo; mas puesto que tiene usted que salir, lo dejaré para otro día; me vuelvo.\"},{\"heading\":false,\"text\":\"—No, está arriba mi tío.\"},{\"heading\":false,\"text\":\"—No es con su tío, es con usted, Eugenia, con quien tenía que hablar. Dejémoslo para otro día.\"},{\"heading\":false,\"text\":\"—No, no, volvamos. Las cosas en caliente.\"},{\"heading\":false,\"text\":\"—Es que si está su tío...\"},{\"heading\":false,\"text\":\"—¡Bah! ¡es anarquista! No le llamaremos.\"},{\"heading\":false,\"text\":\"Y obligó a Augusto a que subiese con ella. El pobre hombre, que había ido con aires de experimentador, sentíase ahora rana.\"},{\"heading\":false,\"text\":\"Cuando estuvieron solos en la sala, Eugenia, sin quitarse el sombrero, con el traje de calle con que había entrado, le dijo: Bien, sepamos qué es lo que tenía que decirme.\"},{\"heading\":false,\"text\":\"—Pues... pues...—y el pobre Augusto balbuceaba—pues... pues...\"},{\"heading\":false,\"text\":\"—Bien; pues ¿qué?\"},{\"heading\":false,\"text\":\"—Que no puedo descansar, Eugenia; que les he dado mil vueltas en el magín a las cosas que nos dijimos la última vez que hablamos, y que a pesar de todo no puedo resignarme, ¡no, no puedo resignarme, no lo puedo!\"},{\"heading\":false,\"text\":\"—Y ¿a qué es a lo que no puede usted resignarse?\"},{\"heading\":false,\"text\":\"—Pues ¡a esto, Eugenia, a esto!\"},{\"heading\":false,\"text\":\"—Y ¿qué es esto?\"},{\"heading\":false,\"text\":\"—A esto, a que no seamos más que amigos...\"},{\"heading\":false,\"text\":\"—¡Más que amigos...! ¿Le parece a usted poco, señor don Augusto? ¿o es que quiere usted que seamos menos que amigos?\"},{\"heading\":false,\"text\":\"—No. Eugenia, no, no es eso.\"},{\"heading\":false,\"text\":\"—Pues ¿qué es?\"},{\"heading\":false,\"text\":\"—Por Dios, no me haga sufrir...\"},{\"heading\":false,\"text\":\"—El que se hace sufrir es usted mismo.\"},{\"heading\":false,\"text\":\"—¡No puedo resignarme, no!\"},{\"heading\":false,\"text\":\"—Pues ¿qué quiere usted?\"},{\"heading\":false,\"text\":\"—¡Que seamos... marido y mujer!\"},{\"heading\":false,\"text\":\"—¡Acabáramos!\"},{\"heading\":false,\"text\":\"—Para acabar hay que empezar.\"},{\"heading\":false,\"text\":\"—¿Y aquella palabra que me dio usted?\"},{\"heading\":false,\"text\":\"—No sabía lo que me decía...\"},{\"heading\":false,\"text\":\"—Y la Rosario aquella...\"},{\"heading\":false,\"text\":\"—¡Oh, por Dios, Eugenia, no me recuerdes eso! ¡No pienses en la Rosario!\"},{\"heading\":false,\"text\":\"Eugenia entonces se quitó el sombrero, lo dejó sobre una mesilla, volvió a sentarse y luego pausadamente y con solemnidad dijo:\"},{\"heading\":false,\"text\":\"—Pues bien, Augusto, ya que tú, que eres al fin y al cabo un hombre, no te crees obligado a guardar la palabra, yo que no soy nada más que una mujer tampoco debo guardarla. Además, quiero librarte de la Rosario y de las demás Rosarios o Petras que puedan envolverte. Lo que no hizo la gratitud por tu desprendimiento ni hizo el despecho de lo que con Mauricio me pasó—ya ves si te soy franca—hace la compasión. ¡Sí, Augusto, me das pena, mucha pena!—y al decir esto le dio dos leves palmaditas con la diestra en una rodilla.\"},{\"heading\":false,\"text\":\"—¡Eugenia!—y le tendió los brazos como para cojerla.\"},{\"heading\":false,\"text\":\"—¡Eh, cuidadito!—exclamó ella apartándoselos y hurtándose de ellos—¡cuidadito!\"},{\"heading\":false,\"text\":\"—Pues la otra vez... la última vez...\"},{\"heading\":false,\"text\":\"—¡Sí, pero entonces era diferente!\"},{\"heading\":false,\"text\":\"«Estoy haciendo de rana»—pensó el psicólogo experimental.\"},{\"heading\":false,\"text\":\"—¡Sí—prosiguió Eugenia—, a un amigo, nada más que amigo, pueden permitírsele ciertas pequeñas libertades que no se debe otorgar al... vamos, al... novio!\"},{\"heading\":false,\"text\":\"—Pues no lo comprendo...\"},{\"heading\":false,\"text\":\"—Cuando nos hayamos casado, Augusto, te lo explicaré. Y ahora, quietecito, ¿eh?\"},{\"heading\":false,\"text\":\"«Esto es hecho»—pensó Augusto, que se sintió ya completa y perfectamente rana.\"},{\"heading\":false,\"text\":\"—Y ahora—agregó Eugenia levantándose—voy a llamar a mi tío.\"},{\"heading\":false,\"text\":\"—¿Para qué?\"},{\"heading\":false,\"text\":\"—¡Toma, para darle parte!\"},{\"heading\":false,\"text\":\"—¡Es verdad!—exclamó Augusto consternado.\"},{\"heading\":false,\"text\":\"Al momento llegó don Fermín.\"},{\"heading\":false,\"text\":\"—Mire usted, tío—le dijo Eugenia—, aquí tiene usted a don Augusto Pérez que ha venido a pedirme la mano. Y yo se la he concedido.\"},{\"heading\":false,\"text\":\"—¡Admirable!, ¡admirable!—exclamó don Fermín—, ¡admirable! Ven acá, hija mía, ven acá que te abrace; ¡admirable!\"},{\"heading\":false,\"text\":\"—¿Tanto le admira a usted que vayamos a casarnos, tío?\"},{\"heading\":false,\"text\":\"—No, lo que me admira, lo que me arrebata, lo que me subyuga es la manera de haber resuelto este asunto, los dos solos, sin medianeros... ¡viva la anarquía! Y es lástima, es lástima que para llevar a cabo vuestro propósito tengáis que acudir a la autoridad... Por supuesto sin acatarla en el fuero interno de vuestra conciencia, ¿eh?, _pro formula_, nada más que _pro formula_. Porque yo sé que os consideráis ya marido y mujer. ¡Y en todo caso yo, yo solo, en nombre del Dios anárquico, os caso! Y esto basta. ¡Admirable! ¡admirable! Don Augusto, desde hoy esta casa es su casa.\"},{\"heading\":false,\"text\":\"—¿Desde hoy?\"},{\"heading\":false,\"text\":\"—Tiene usted razón, sí, lo fué siempre. Mi casa... ¿mía? Esta casa que habito fué siempre de usted, fué siempre de todos mis hermanos. Pero desde hoy... usted me entiende.\"},{\"heading\":false,\"text\":\"—Sí, le entiende a usted, tío.\"},{\"heading\":false,\"text\":\"En aquel momento llamaron a la puerta y Eugenia dijo: ¡La tía! Y al entrar ésta en la sala y ver aquello, exclamó:—Ya, ¡enterada! ¿Conque es cosa hecha? Esto ya me lo sabía yo.\"},{\"heading\":false,\"text\":\"Augusto pensaba: «¡rana, rana completa! Y me han pescado entre todos».\"},{\"heading\":false,\"text\":\"—Se quedará usted hoy a comer con nosotros, por supuesto, para celebrarlo...—dijo doña Ermelinda.\"},{\"heading\":false,\"text\":\"—¡Y qué remedio!—se le escapó al pobre rana.\"}]},{\"title\":\"Capítulo XXVII\",\"blocks\":[{\"heading\":false,\"text\":\"Empezó entonces para Augusto una nueva vida. Casi todo el día se lo pasaba en casa de su novia y estudiando no psicología, sino estética.\"},{\"heading\":false,\"text\":\"¿Y Rosario? Rosario no volvió por su casa. La siguiente vez que le llevaron la ropa planchada fué otra la que se la llevó, una mujer cualquiera. Y apenas se atrevió a preguntar por qué no venía ya Rosario. ¿Para qué, si lo adivinaba? Y este desprecio, porque no era sino desprecio, bien lo conocía y, lejos de dolerle, casi le hizo gracia. Bien. Bien se desquitaría él en Eugenia. Que, por supuesto, seguía con lo de: «¡Eh, cuidadito y manos quedas!» ¡Buena era ella para otra cosa!\"},{\"heading\":false,\"text\":\"Eugenia le tenía a ración de vista y no más que de vista, encendiéndole el apetito. Una vez le dijo él:—«¡Me entran unas ganas de hacer unos versos a tus ojos!», y ella le contestó:—«¡Hazlos!»\"},{\"heading\":false,\"text\":\"—Mas para ello—agregó él—sería conveniente que tocases un poco el piano. Oyéndote en él, en tu instrumento profesional, me inspiraría.\"},{\"heading\":false,\"text\":\"—Pero ya sabes, Augusto, que desde que, gracias a tu generosidad, he podido ir dejando mis lecciones no he vuelto a tocar el piano y que lo aborrezco. ¡Me ha costado tantas molestias!\"},{\"heading\":false,\"text\":\"—No importa, tócalo, Eugenia, tócalo para que yo escriba mis versos.\"},{\"heading\":false,\"text\":\"—¡Sea, pero por única vez!\"},{\"heading\":false,\"text\":\"Sentóse Eugenia a tocar el piano y mientras lo tocaba escribió Augusto esto:\"},{\"heading\":false,\"text\":\"Mi alma vagaba lejos de mi cuerpo en las brumas perdida de la idea, perdida allá en las notas de la música que según dicen cantan las esferas; y yacía mi cuerpo solitario sin alma y triste errando por la tierra. Nacidos para arar juntos la vida no vivían; porque él era materia tan sólo y ella nada más que espíritu buscando completarse, ¡dulce Eugenia! Mas brotaron tus ojos como fuentes de viva luz encima de mi senda y prendieron a mi alma y la trajeron del vago cielo a la dudosa tierra, metiéronla en mi cuerpo, y desde entonces y ¡sólo desde entonces vivo, Eugenia! Son tus ojos cual clavos encendidos que mi cuerpo a mi espíritu sujetan, que hacen que sueñe en mí febril la sangre y que en carne convierten mis ideas. ¡Si esa luz de mi vida se apagara, desuncidos espíritu y materia, perderíame en brumas celestiales y del profundo en la voraz tiniebla!\"},{\"heading\":false,\"text\":\"—¿Qué te parecen?—le preguntó Augusto luego que se los hubo leído.\"},{\"heading\":false,\"text\":\"—Como mi piano, poco o nada musicales. Y eso de «según dicen...»\"},{\"heading\":false,\"text\":\"—Sí, es para darle familiaridad...\"},{\"heading\":false,\"text\":\"—Y lo de «dulce Eugenia» me parece un ripio.\"},{\"heading\":false,\"text\":\"—¿Qué? ¿que eres un ripio tú?\"},{\"heading\":false,\"text\":\"—¡Ahí, en esos versos, sí! Y luego todo eso me parece muy... muy...\"},{\"heading\":false,\"text\":\"—Vamos, sí, muy _nivolesco_.\"},{\"heading\":false,\"text\":\"—¿Qué es eso?\"},{\"heading\":false,\"text\":\"—Nada, un timo que nos traemos entre Víctor y yo.\"},{\"heading\":false,\"text\":\"—Pues mira, Augusto, yo no quiero timos en mi casa luego que nos casemos, ¿sabes? Ni timos ni perros. Conque ya puedes ir pensando lo que has de hacer de Orfeo...\"},{\"heading\":false,\"text\":\"—Pero ¡Eugenia, por Dios! ¡si ya sabes cómo le encontré, pobrecillo! ¡si es además mi confidente...! ¡si es a quien dirijo mis monólogos todos...!\"},{\"heading\":false,\"text\":\"—Es que cuando nos casemos no ha de haber monólogos en mi casa. ¡Está de más el perro!\"},{\"heading\":false,\"text\":\"—Por Dios, Eugenia, siquiera hasta que tengamos un hijo...\"},{\"heading\":false,\"text\":\"—Si lo tenemos...\"},{\"heading\":false,\"text\":\"—Claro, si lo tenemos. Y si no, ¿por qué no el perro? ¿por qué no el perro, del que se ha dicho con tanta justicia que sería el mejor amigo del hombre si tuviese dinero...?\"},{\"heading\":false,\"text\":\"—No, si tuviese dinero el perro no sería amigo del hombre, estoy segura de ello. Porque no lo tiene es su amigo.\"},{\"heading\":false,\"text\":\"Otro día le dijo Eugenia a Augusto:\"},{\"heading\":false,\"text\":\"—Mira, Augusto, tengo que hablarte de una cosa grave, muy grave, y te ruego que me perdones de antemano si lo que voy a decirte...\"},{\"heading\":false,\"text\":\"—¡Por Dios, Eugenia, habla!\"},{\"heading\":false,\"text\":\"—Tú sabes aquel novio que tuve...\"},{\"heading\":false,\"text\":\"—Sí, Mauricio.\"},{\"heading\":false,\"text\":\"—Pero no sabes por qué le tuve que despachar al muy sinvergüenza...\"},{\"heading\":false,\"text\":\"—Ni quiero saberlo.\"},{\"heading\":false,\"text\":\"—Eso te honra. Pues bien; le tuve que despachar al haragán y sinvergüenza aquel, pero...\"},{\"heading\":false,\"text\":\"—¿Qué, te persigue todavía?\"},{\"heading\":false,\"text\":\"—¡Todavía!\"},{\"heading\":false,\"text\":\"—¡Ah, como yo le coja...!\"},{\"heading\":false,\"text\":\"—No, no es eso. Me persigue, pero no ya con las intenciones que tú crees, sino con otras.\"},{\"heading\":false,\"text\":\"—¡A ver! ¡a ver!\"},{\"heading\":false,\"text\":\"—No te alarmes. Augusto, no te alarmes. El pobre Mauricio no muerde, ladra.\"},{\"heading\":false,\"text\":\"—Ah, pues haz lo que dice el refrán árabe: «Si vas a detenerte con cada perro que te salga a ladrar al camino, nunca llegarás al fin de él». No sirve tirarles piedras. No le hagas caso.\"},{\"heading\":false,\"text\":\"—Creo que hay otro medio mejor.\"},{\"heading\":false,\"text\":\"—¿Cuál?\"},{\"heading\":false,\"text\":\"—Llevar a prevención mendrugos de pan en el bolsillo e irlos tirando a los perros que salen a ladrarnos, porque ladran por hambre.\"},{\"heading\":false,\"text\":\"—¿Qué quieres decir?\"},{\"heading\":false,\"text\":\"—Que ahora Mauricio no pretende sino que le busque una colocación cualquiera o un modo de vivir y dice que me dejará en paz, y si no...\"},{\"heading\":false,\"text\":\"—Si no...\"},{\"heading\":false,\"text\":\"—Amenaza con perseguirme para comprometerme...\"},{\"heading\":false,\"text\":\"—¡Desvergonzado! ¡Bandido!\"},{\"heading\":false,\"text\":\"—No te exaltes. Y creo que lo mejor es quitárnosle de en medio buscándole una colocación cualquiera que le dé para vivir y que sea lo más lejos posible. Es, además, de mi parte algo de compasión porque el pobrecillo es como es, y...\"},{\"heading\":false,\"text\":\"—Acaso tengas razón, Eugenia. Y mira, creo que podré arreglarlo todo. Mañana mismo hablaré a un amigo mío y me parece que le buscaremos ese empleo.\"},{\"heading\":false,\"text\":\"Y, en efecto, pudo encontrarle el empleo y conseguir que le destinasen bastante lejos.\"}]},{\"title\":\"Capítulo XXVIII\",\"blocks\":[{\"heading\":false,\"text\":\"Torció el gesto Augusto cuando una mañana le anunció Liduvina que un joven le esperaba y se encontró luego con que era Mauricio. Estuvo por despedirlo sin oirle, pero le atraía aquel hombre que fué en un tiempo novio de Eugenia, a la que ésta quiso y acaso seguía queriendo en algún modo; aquel hombre que tal vez sabía de la que iba a ser mujer de él, de Augusto, intimidades que éste ignoraba; de aquel hombre que... Había algo que les unía.\"},{\"heading\":false,\"text\":\"—Vengo, señor—empezó sumisamente Mauricio—, a darle las gracias por el favor insigne que merced a la mediación de Eugenia usted se ha dignado otorgarme...\"},{\"heading\":false,\"text\":\"—No tiene usted de qué darme las gracias, señor mío, y espero que en adelante dejará usted en paz a la que va a ser mi mujer.\"},{\"heading\":false,\"text\":\"—Pero ¡si yo no la he molestado lo más mínimo!\"},{\"heading\":false,\"text\":\"—Sé a qué atenerme.\"},{\"heading\":false,\"text\":\"—Desde que me despidió, e hizo bien en despedirme porque no soy yo el que a ella corresponde, he procurado consolarme como mejor he podido de esa desgracia y respetar, por supuesto, sus determinaciones. Y si ella le ha dicho a usted otra cosa...\"},{\"heading\":false,\"text\":\"—Le ruego que no vuelva a mentar a la que va a ser mi mujer, y mucho menos que insinúe siquiera el que haya faltado lo más mínimo a la verdad. Consuélese como pueda y déjenos en paz.\"},{\"heading\":false,\"text\":\"—Es verdad. Y vuelvo a darles a ustedes dos las gracias por el favor que me han hecho proporcionándome ese empleíto. Iré a servirlo y me consolaré como pueda. Por cierto que pienso llevarme conmigo a una muchachita...\"},{\"heading\":false,\"text\":\"—Y ¿a mí qué me importa eso, caballero?\"},{\"heading\":false,\"text\":\"—Es que me parece que usted debe de conocerla...\"},{\"heading\":false,\"text\":\"—¿Cómo? ¿cómo? ¿quiere usted burlarse...?\"},{\"heading\":false,\"text\":\"—No... no... Es una tal Rosario, que está en un taller de planchado y que me parece le solía llevar a usted la plancha...\"},{\"heading\":false,\"text\":\"Augusto palideció. «¿Sabrá éste todo?», se dijo, y esto le azaró aún más que su anterior sospecha de que aquel hombre supiese de Eugenia lo que él no sabía. Pero repúsose al pronto y exclamó:\"},{\"heading\":false,\"text\":\"—Y ¿a qué me viene usted ahora con eso?\"},{\"heading\":false,\"text\":\"—Me parece—prosiguió Mauricio, como si no hubiese oído nada—que a los despreciados se nos debe dejar el que nos consolemos los unos con los otros.\"},{\"heading\":false,\"text\":\"—Pero ¿qué quiere usted decir, hombre, qué quiere usted decir?—y pensó Augusto si allí, en aquel que fué escenario de su última aventura con Rosario, estrangularía o no a aquel hombre.\"},{\"heading\":false,\"text\":\"—¡No se exalte así, don Augusto, no se exalte así! No quiero decir sino lo que he dicho. Ella... la que usted no quiere que yo miente, me despreció, me despachó, y yo me he encontrado con esa pobre chicuela, a la que otro despreció, y...\"},{\"heading\":false,\"text\":\"Augusto no pudo ya contenerse; palideció primero, se encendió después, levantóse, cojió a Mauricio por los dos brazos, lo levantó en vilo y le arrojó en el sofá sin darse clara cuenta de lo que hacía, como para estrangularlo. Y entonces, al verse Mauricio en el sofá, dijo con la mayor frialdad:\"},{\"heading\":false,\"text\":\"—Mírese usted ahora, don Augusto, en mis pupilas y verá qué chiquitito se ve...\"},{\"heading\":false,\"text\":\"El pobre Augusto creyó derretirse. Por lo menos se le derritió la fuerza toda de los brazos, empezó la estancia a convertirse en niebla a sus ojos, pensó: «¿estaré soñando?», y se encontró con que Mauricio, de pie ya y frente a él, le miraba con una socarrona sonrisa:\"},{\"heading\":false,\"text\":\"—¡Oh, no ha sido nada, don Augusto, no ha sido nada! Perdóneme usted, un arrebato... ni sé siquiera lo que me hice... ni me di cuenta... Y ¡gracias, gracias, otra vez gracias! ¡gracias a usted y a... ella! ¡Adiós!\"},{\"heading\":false,\"text\":\"Apenas había salido Mauricio, llamó Augusto a Liduvina.\"},{\"heading\":false,\"text\":\"—Di, Liduvina, ¿quién ha estado aquí conmigo?\"},{\"heading\":false,\"text\":\"—Un joven.\"},{\"heading\":false,\"text\":\"—¿De qué señas?\"},{\"heading\":false,\"text\":\"—Pero ¿necesita usted que se lo diga?\"},{\"heading\":false,\"text\":\"—¿De veras, ha estado aquí alguien conmigo?\"},{\"heading\":false,\"text\":\"—¡Señorito!\"},{\"heading\":false,\"text\":\"—No... no... júrame que ha estado aquí conmigo un joven y de las señas que me digas... alto, rubio, ¿no es eso?, de bigote, más bien grueso que flaco, de nariz aguileña... ¿ha estado?\"},{\"heading\":false,\"text\":\"—Pero ¿está usted bueno, don Augusto?\"},{\"heading\":false,\"text\":\"—¿No ha sido un sueño...?\"},{\"heading\":false,\"text\":\"—Como no lo hayamos soñado los dos...\"},{\"heading\":false,\"text\":\"—No, no pueden soñar dos al mismo tiempo la misma cosa. Y precisamente se conoce que algo no es sueño en que no es de uno solo...\"},{\"heading\":false,\"text\":\"—Pues ¡sí, estese tranquilo, sí! Estuvo ese joven que dice.\"},{\"heading\":false,\"text\":\"—Y ¿qué dijo al salir?\"},{\"heading\":false,\"text\":\"—Al salir no habló conmigo... ni le vi...\"},{\"heading\":false,\"text\":\"—Y tú ¿sabes quién es, Liduvina?\"},{\"heading\":false,\"text\":\"—Sí, sé quién es. El que fué novio de...\"},{\"heading\":false,\"text\":\"—Sí, basta. Y ahora, ¿de quién lo es?\"},{\"heading\":false,\"text\":\"—Eso ya sería saber demasiado.\"},{\"heading\":false,\"text\":\"—Como las mujeres sabéis tantas cosas que no os enseñan...\"},{\"heading\":false,\"text\":\"—Sí, y en cambio no logramos aprender las que quieren enseñarnos.\"},{\"heading\":false,\"text\":\"—Pues bueno, di la verdad, Liduvina: ¿no sabes con quién anda ahora ese... prójimo?\"},{\"heading\":false,\"text\":\"—No, pero me lo figuro.\"},{\"heading\":false,\"text\":\"—¿Por qué?\"},{\"heading\":false,\"text\":\"—Por lo que está usted diciendo.\"},{\"heading\":false,\"text\":\"—Bueno, llama ahora a Domingo.\"},{\"heading\":false,\"text\":\"—¿Para qué?\"},{\"heading\":false,\"text\":\"—Para saber si estoy también todavía soñando o no, y si tú eres de verdad Liduvina, su mujer, o si...\"},{\"heading\":false,\"text\":\"—¿O si Domingo está soñando también? Pero creo que hay otra cosa mejor.\"},{\"heading\":false,\"text\":\"—¿Cuál?\"},{\"heading\":false,\"text\":\"—Que venga Orfeo.\"},{\"heading\":false,\"text\":\"—Tienes razón; ¡ése no sueña!\"},{\"heading\":false,\"text\":\"Al poco rato, habiendo ya salido Liduvina, entraba el perro.\"},{\"heading\":false,\"text\":\"«¡Ven acá, Orfeo—le dijo su amo—, ven acá! ¡Pobrecito! ¡qué pocos días te quedan ya de vivir conmigo! No te quiere ella en casa. Y ¿adónde voy a echarte? ¿qué voy a hacer de ti? ¿qué será de ti sin mí? Eres capaz de morirte, ¡lo sé! Sólo un perro es capaz de morirse al verse sin amo. Y yo he sido más que tu amo, ¡tu padre, tu dios! ¡No te quiere en casa; te echa de mi lado! ¿Es que tú, el símbolo de la fidelidad, le estorbas en casa? ¡Quién lo sabe...! Acaso un perro sorprende los más secretos pensamientos de las personas con quienes vive, y aunque se calle... ¡Y tengo que casarme, no tengo más remedio que casarme... si no, jamás voy a salir del sueño! Tengo que despertar.»\"},{\"heading\":false,\"text\":\"«Pero ¿por qué me miras así, Orfeo? ¡Si parece que lloras sin lágrimas...! ¿Es que me quieres decir algo? Te veo sufrir por no tener palabra. ¡Qué pronto aseguré que tú no sueñas! ¡Tú sí que me estás soñando, Orfeo! ¿Por qué somos hombres los hombres sino porque hay perros y gatos y caballos y bueyes y ovejas y animales de toda clase, sobre todo domésticos? ¿Es que a falta de animales domésticos en que descargar el peso de la animalidad de la vida habría el hombre llegado a su humanidad? ¿Es que a no haber domesticado el hombre al caballo no andaría la mitad de nuestro linaje llevando a cuestas a la otra mitad? Sí, a vosotros se os debe la civilización. Y a las mujeres. Pero ¿no es acaso la mujer otro animal doméstico? Y de no haber mujeres, ¿serían hombres los hombres? ¡Ay, Orfeo, viene de fuera quien de casa te echa!»\"},{\"heading\":false,\"text\":\"Y le apretó contra su seno, y el perro, que parecía en efecto llorar, le lamía la barba.\"}]},{\"title\":\"Capítulo XXIX\",\"blocks\":[{\"heading\":false,\"text\":\"Todo estaba dispuesto ya para la boda. Augusto la quería recojida y modesta, pero ella, su mujer futura, parecía preferir que se le diese más boato y resonancia.\"},{\"heading\":false,\"text\":\"A medida que se acercaba aquel plazo, el novio ardía por tomarse ciertas pequeñas libertades y confianzas, y ella, Eugenia, se mantenía más en reserva.\"},{\"heading\":false,\"text\":\"—Pero ¡si dentro de unos días vamos a ser el uno del otro, Eugenia!\"},{\"heading\":false,\"text\":\"—Pues por lo mismo. Es menester que empecemos ya a respetarnos.\"},{\"heading\":false,\"text\":\"—Respeto... respeto... El respeto excluye el cariño.\"},{\"heading\":false,\"text\":\"—Eso creerás tú... ¡Hombre al fin!\"},{\"heading\":false,\"text\":\"Y Augusto notaba en ella algo extraño, algo forzado. Alguna vez parecióle que trataba de esquivar sus miradas. Y se acordó de su madre, de su pobre madre, y del anhelo que sintió siempre por que su hijo se casara bien. Y ahora, próximo a casarse con Eugenia, le atormentaba más lo que Mauricio le dijera de llevarse a Rosario. Sentía celos, unos celos furiosos, y rabia por haber dejado pasar una ocasión, por el ridículo en que quedó ante la mozuela. «Ahora estarán riéndose los dos de mí—se decía—, y él doblemente, porque ha dejado a Eugenia encajándomela y porque se me lleva a Rosario.» Y alguna vez le entraron furiosas ganas de romper su compromiso y de ir a la conquista de Rosario, a arrebatársela a Mauricio.\"},{\"heading\":false,\"text\":\"—Y de aquella mocita, de aquella Rosario, ¿qué se ha hecho?—le preguntó Eugenia unos días antes de el de la boda.\"},{\"heading\":false,\"text\":\"—Y ¿a qué viene recordarme ahora eso?\"},{\"heading\":false,\"text\":\"—¡Ah, si no te gusta el recuerdo, lo dejaré!\"},{\"heading\":false,\"text\":\"—No... no... pero...\"},{\"heading\":false,\"text\":\"—Sí, como una vez interrumpió ella una entrevista nuestra... ¿No has vuelto a saber de ella?—y le miró con mirada de las que atraviesan.\"},{\"heading\":false,\"text\":\"—No, no he vuelto a saber de ella.\"},{\"heading\":false,\"text\":\"—¿Quién la estará conquistando o quién la habrá conquistado a estas horas...?—y apartando su mirada de Augusto la fijó en el vacío, más allá de lo que miraba.\"},{\"heading\":false,\"text\":\"Por la mente del novio pasaron, en tropel, extraños agüeros. «Esta parece saber algo», se dijo, y luego en voz alta:\"},{\"heading\":false,\"text\":\"—¿Es que sabes algo?\"},{\"heading\":false,\"text\":\"—¿Yo?—contestó ella fingiendo indiferencia y volvió a mirarle.\"},{\"heading\":false,\"text\":\"Entre los dos flotaba sombra de misterio.\"},{\"heading\":false,\"text\":\"—Supongo que la habrás olvidado...\"},{\"heading\":false,\"text\":\"—Pero ¿a qué esta insistencia en hablarme de esa... chiquilla?\"},{\"heading\":false,\"text\":\"—¡Qué sé yo!... Porque, hablando de otra cosa, ¿qué le pasará a un hombre cuando otro le quita la mujer a que pretendía y se la lleva?\"},{\"heading\":false,\"text\":\"A Augusto le subió una oleada de sangre a la cabeza al oir esto. Entráronle ganas de salir, correr en busca de Rosario, ganarla y volver con ella a Eugenia para decir a ésta: «¡Aquí la tienes, es mía, y no de... _tu_ Mauricio!»\"},{\"heading\":false,\"text\":\"Faltaban tres días para el de la boda. Augusto salió de casa de su novia pensativo. Apenas pudo dormir aquella noche.\"},{\"heading\":false,\"text\":\"A la mañana siguiente, apenas despertó, entró Liduvina en su cuarto.\"},{\"heading\":false,\"text\":\"—Aquí hay una carta para el señorito; acaban de traerla. Me parece que es de la señorita Eugenia...\"},{\"heading\":false,\"text\":\"—¿Carta? ¿de ella? ¿de ella carta? ¡Déjala ahí y vete!\"},{\"heading\":false,\"text\":\"Salió Liduvina. Augusto empezó a temblar. Un extraño desasosiego le agitaba el corazón. Se acordó de Rosario, luego de Mauricio. Pero no quiso tocar la carta. Miró con terror al sobre. Se levantó, se lavó, se vistió, pidió el desayuno, devorándolo luego. «No, no quiero leerla aquí», se dijo. Salió de casa, fuese a la iglesia más próxima, y allí, entre unos cuantos devotos que oían misa, abrió la carta. «Aquí tendré que contenerme—se dijo—, porque yo no sé qué cosas me dice el corazón.» Y decía la carta:\"},{\"heading\":false,\"text\":\"«Apreciable Augusto: Cuando leas estas líneas yo estaré con Mauricio camino del pueblo adonde éste va destinado gracias a tu bondad, a la que debo también poder disfrutar de mis rentas, que con el sueldo de él nos permitirá vivir juntos con algún desahogo. No te pido que me perdones, porque después de esto creo que te convencerás de que ni yo te hubiera hecho feliz ni tú mucho menos a mí. Cuando se te pase la primera impresión volveré a escribirte para explicarte por qué doy este paso ahora y de esta manera. Mauricio quería que nos hubiéramos escapado el día mismo de la boda, después de salir de la iglesia; pero su plan era muy complicado y me pareció, además, una crueldad inútil. Y como te dije en otra ocasión, creo quedaremos amigos. Tu amiga\"},{\"heading\":false,\"text\":\"_Eugenia Domingo del Arco_.\"},{\"heading\":false,\"text\":\"P. S. No viene con nosotros Rosario. Te queda ahí y puedes con ella consolarte.»\"},{\"heading\":false,\"text\":\"Augusto se dejó caer en un banco, anonadado. Al poco rato se arrodilló y rezaba.\"},{\"heading\":false,\"text\":\"Al salir de la iglesia parecíale que iba tranquilo, mas era una terrible tranquilidad de bochorno. Se dirigió a casa de Eugenia, donde encontró a los pobres tíos consternados. La sobrina les había comunicado por carta su determinación y no remaneció en toda la noche. Había tomado la pareja un tren que salió al anochecer, muy poco después de la última entrevista de Augusto con su novia.\"},{\"heading\":false,\"text\":\"—Y ¿qué hacemos ahora?—dijo doña Ermelinda.\"},{\"heading\":false,\"text\":\"—¡Qué hemos de hacer, señora—contestó Augusto—, sino aguantarnos!\"},{\"heading\":false,\"text\":\"—¡Esto es una indignidad—exclamó don Fermín—; estas cosas no debían quedar sin un ejemplar castigo!\"},{\"heading\":false,\"text\":\"—Y ¿es usted, don Fermín, usted, el anarquista...?\"},{\"heading\":false,\"text\":\"—Y ¿qué tiene que ver? Estas cosas no se hacen así. ¡No se engaña así a un hombre!\"},{\"heading\":false,\"text\":\"—¡Al otro no le ha engañado!—dijo fríamente Augusto, y después de haberlo dicho se aterró de la frialdad con que lo dijera.\"},{\"heading\":false,\"text\":\"—Pero le engañará... le engañará... ¡no lo dude usted!\"},{\"heading\":false,\"text\":\"Augusto sintió un placer diabólico al pensar que Eugenia engañaría al cabo a Mauricio, «Pero no ya conmigo», se dijo muy bajito, de modo que apenas si se oyese a sí mismo.\"},{\"heading\":false,\"text\":\"—Bueno, señores, lamento lo sucedido, y más que nada por su sobrina, pero debo retirarme.\"},{\"heading\":false,\"text\":\"—Usted comprenderá, don Augusto, que nosotros...—empezó doña Ermelinda.\"},{\"heading\":false,\"text\":\"—¡Claro! ¡claro! Pero...\"},{\"heading\":false,\"text\":\"Aquello no podía prolongarse. Augusto, después de breves palabras más, se salió.\"},{\"heading\":false,\"text\":\"Iba aterrado de sí mismo y de lo que le pasaba, o mejor aún, de lo que no le pasaba. Aquella frialdad, al menos aparente, con que recibió el golpe de la burla suprema, aquella calma le hacía que hasta dudase de su propia existencia. «Si yo fuese un hombre como los demás—se decía—, con corazón; si fuese siquiera un hombre; si existiese de verdad, ¿cómo podía haber recibido esto con la relativa tranquilidad con que lo recibo?» Y empezó, sin darse de ello cuenta, a palparse, y hasta se pellizcó para ver si lo sentía.\"},{\"heading\":false,\"text\":\"De pronto sintió que alguien le tiraba de una pierna. Era Orfeo, que le había salido al encuentro, para consolarlo. Al ver a Orfeo sintió, ¡cosa extraña!, una gran alegría, lo tomó en brazos y le dijo: «¡Alégrate, Orfeo mío, alégrate! ¡alegrémonos los dos! ¡Ya no te echan de casa; ya no te separan de mí; ya no nos separan al uno del otro! Viviremos juntos en la vida y en la muerte. No hay mal que por bien no venga, por grande que el mal sea y por pequeño que sea el bien, o al revés. ¡Tú, tú eres fiel, Orfeo mío, tú eres fiel! Yo ya supongo que algunas veces buscarás tu perra, pero no por eso huyes de casa, no por eso me abandonas; tú eres fiel, tú. Y mira, para que no tengas nunca que marcharte, traeré una perra a casa, sí, te la traeré. Porque ahora, ¿es que has salido a mi encuentro para consolar la pena que debía tener o es que me encuentras al volver de una visita a tu perra? De todos modos, tú eres fiel, tú, y ya nadie te echará de mi casa, nadie nos separará».\"},{\"heading\":false,\"text\":\"Entró en su casa, y no bien se volvió a ver en ella, solo, se le desencadenó en el alma la tempestad que parecía calma. Le invadió un sentimiento en que se daban confundidos tristeza, amarga tristeza, celos, rabia, miedo, odio, amor, compasión, desprecio, y sobre todo vergüenza, una enorme vergüenza, y la terrible conciencia del ridículo en que quedaba.\"},{\"heading\":false,\"text\":\"—¡Me ha matado!—le dijo a Liduvina.\"},{\"heading\":false,\"text\":\"—¿Quién?\"},{\"heading\":false,\"text\":\"—Ella.\"},{\"heading\":false,\"text\":\"Y se encerró en su cuarto. Y a la vez que las imágenes de Eugenia y de Mauricio presentábase a su espíritu la de Rosario, que también se burlaba de él. Y recordaba a su madre. Se echó sobre la cama, mordió la almohada, no acertaba a decirse nada concreto, se le enmudeció el monólogo, sintió como si se le acorchase el alma y rompió a llorar. Y lloró, lloró, lloró. Y en el llanto silencioso se le derretía el pensamiento.\"}]},{\"title\":\"Capítulo XXX\",\"blocks\":[{\"heading\":false,\"text\":\"Víctor encontró a Augusto hundido en un rincón de un sofá, mirando más abajo del suelo.\"},{\"heading\":false,\"text\":\"—¿Qué es eso?—le preguntó poniéndole una mano sobre el hombro.\"},{\"heading\":false,\"text\":\"—Y ¿me preguntas qué es esto? ¿No sabes lo que me ha pasado?\"},{\"heading\":false,\"text\":\"—Sí, sé lo que te ha pasado por fuera, es decir, lo que ha hecho ella; lo que no sé es lo que te pasa por dentro, es decir, no sé por qué estás así...\"},{\"heading\":false,\"text\":\"—¡Parece imposible!\"},{\"heading\":false,\"text\":\"—Se te ha ido un amor, el de a; ¿no te queda el de b, o el de c, o el de x, o el de otra cualquiera de las n?\"},{\"heading\":false,\"text\":\"—No es la ocasión para bromas, creo.\"},{\"heading\":false,\"text\":\"—Al contrario, ésta es la ocasión de bromas.\"},{\"heading\":false,\"text\":\"—Es que no me duele en el amor; ¡es la burla, la burla, la burla! Se han burlado de mí, me han escarnecido, me han puesto en ridículo; han querido demostrarme... ¿qué sé yo?... que no existo.\"},{\"heading\":false,\"text\":\"—¡Qué felicidad!\"},{\"heading\":false,\"text\":\"—No te burles, Víctor.\"},{\"heading\":false,\"text\":\"—Y ¿por qué no me he de burlar? Tú, querido Augusto, fuiste de experimentador y has sido experimentado; la quisiste tomar de rana y es ella la que te ha tomado de rana a ti. ¡Chapúzate, pues, en la charca y a croar y a vivir!\"},{\"heading\":false,\"text\":\"—Te ruego otra vez...\"},{\"heading\":false,\"text\":\"—Que no bromee, ¿eh? Pues bromearé. Para estas ocasiones se ha hecho la burla.\"},{\"heading\":false,\"text\":\"—Es que eso es corrosivo.\"},{\"heading\":false,\"text\":\"—Y hay que corroer. Y hay que confundir. Confundir sobre todo, confundirlo todo. Confundir el sueño con la vela, la ficción con la realidad, lo verdadero con lo falso; confundirlo todo en una sola niebla. La broma que no es corrosiva y confundente no sirve para nada. El niño se ríe en la tragedia; el viejo llora en la comedia. Quisiste hacerla rana, te ha hecho rana; acéptalo, pues, y sé para ti mismo rana.\"},{\"heading\":false,\"text\":\"—¿Qué quieres decir con eso?\"},{\"heading\":false,\"text\":\"—Experimenta en ti mismo.\"},{\"heading\":false,\"text\":\"—Sí, que me suicide.\"},{\"heading\":false,\"text\":\"—No digo ni que sí ni que no. Sería una solución como otra, pero no la mejor.\"},{\"heading\":false,\"text\":\"—Entonces, que les busque y les mate.\"},{\"heading\":false,\"text\":\"—Matar por matar es un desatino. A lo sumo para librarse del odio, que no hace sino corromper al alma. Porque más de un rencoroso se curó del rencor y sintió piedad, y hasta amor a su víctima, una vez que satisfizo su odio en ella. El acto malo libera del mal sentimiento. Y es porque la ley hace el pecado.\"},{\"heading\":false,\"text\":\"—Y ¿qué voy a hacer?\"},{\"heading\":false,\"text\":\"—Habrás oído que en este mundo no hay sino devorar o ser devorado...\"},{\"heading\":false,\"text\":\"—Sí, burlarse de otros o ser burlado.\"},{\"heading\":false,\"text\":\"—No; cabe otro término tercero y es devorarse uno a sí mismo, burlarse de sí mismo uno. ¡Devórate! El que devora goza, pero no se harta de recordar el acabamiento de sus goces y se hace pesimista; el que es devorado sufre, y no se harta de esperar la liberación de sus penas y se hace optimista. Devórate a ti mismo, y como el placer de devorarte se confundirá y neutralizará con el dolor de ser devorado, llegarás a la perfecta ecuanimidad de espíritu, a la ataraxia; no serás sino un mero espectáculo para ti mismo.\"},{\"heading\":false,\"text\":\"—Y ¿eres tú, tú, Víctor, tú el que me vienes con esas cosas?\"},{\"heading\":false,\"text\":\"—¡Sí, yo, Augusto, yo, soy yo!\"},{\"heading\":false,\"text\":\"—Pues en un tiempo no pensabas de esa manera tan... corrosiva.\"},{\"heading\":false,\"text\":\"—Es que entonces no era padre.\"},{\"heading\":false,\"text\":\"—Y ¿el ser padre...?\"},{\"heading\":false,\"text\":\"—El ser padre, al que no está loco o es un mentecato, le despierta lo más terrible que hay en el hombre: ¡el sentido de la responsabilidad! Yo entrego a mi hijo el legado perenne de la humanidad. Con meditar en el misterio de la paternidad hay para volverse loco. Y si los más de los padres no se vuelven locos es porque son tontos... o no son padres. Regocíjate, pues, Augusto, que con eso de habérsete escapado te evitó acaso el que fueses padre. Y yo te dije que te casaras, pero no que te hicieses padre. El matrimonio es un experimento... psicológico; la paternidad lo es... patológico.\"},{\"heading\":false,\"text\":\"—¡Es que me ha hecho padre, Víctor!\"},{\"heading\":false,\"text\":\"—¿Cómo? ¿que te ha hecho padre?\"},{\"heading\":false,\"text\":\"—¡Sí, de mí mismo! Con esto creo haber nacido de veras. Y para sufrir, para morir.\"},{\"heading\":false,\"text\":\"—Sí, el segundo nacimiento, el verdadero, es nacer por el dolor a la conciencia de la muerte incesante, de que estamos siempre muriendo. Pero si te has hecho padre de ti mismo es que te has hecho hijo de ti mismo también.\"},{\"heading\":false,\"text\":\"—Parece imposible, Víctor, parece imposible que pasándome lo que me pasa, después de lo que ha hecho conmigo... ¡ella!, pueda todavía oir con calma estas sutilezas, estos juegos de concepto, estas humoradas macabras, y hasta algo peor...\"},{\"heading\":false,\"text\":\"—¿Qué?\"},{\"heading\":false,\"text\":\"—Que me distraigan. ¡Me irrito contra mí mismo!\"},{\"heading\":false,\"text\":\"—Es la comedia, Augusto, es la comedia que representamos ante nosotros mismos, en lo que se llama el foro interno, en el tablado de la conciencia, haciendo a la vez de cómicos y de espectadores. Y en la escena del dolor representamos el dolor y nos parece un desentono el que de repente nos entre ganas de reír entonces. Y es cuando más ganas nos da de ello. ¡Comedia, comedia el dolor!\"},{\"heading\":false,\"text\":\"—¿Y si la comedia del dolor le lleva a uno a suicidarse?\"},{\"heading\":false,\"text\":\"—¡Comedia de suicidio!\"},{\"heading\":false,\"text\":\"—¡Es que se muere de veras!\"},{\"heading\":false,\"text\":\"—¡Comedia también!\"},{\"heading\":false,\"text\":\"—Pues ¿qué es lo real, lo verdadero, lo sentido?\"},{\"heading\":false,\"text\":\"—Y ¿quién te ha dicho que la comedia no es real y verdadera y sentida?\"},{\"heading\":false,\"text\":\"—¿Entonces?\"},{\"heading\":false,\"text\":\"—Que todo es uno y lo mismo; que hay que confundir, Augusto, hay que confundir. Y el que no confunde se confunde.\"},{\"heading\":false,\"text\":\"—Y el que confunde también.\"},{\"heading\":false,\"text\":\"—Acaso.\"},{\"heading\":false,\"text\":\"—¿Entonces?\"},{\"heading\":false,\"text\":\"—Pues esto, charlar, sutilizar, jugar con las palabras y los vocablos... ¡pasar el rato!\"},{\"heading\":false,\"text\":\"—¡Ellos sí que lo estarán pasando!\"},{\"heading\":false,\"text\":\"—¡Y tú también! ¿Te has encontrado nunca a tus propios ojos más interesante que ahora? ¿Cómo sabe uno que tiene un miembro si no le duele?\"},{\"heading\":false,\"text\":\"—Bueno, y ¿qué voy a hacer yo ahora?\"},{\"heading\":false,\"text\":\"—¡Hacer... hacer... hacer! ¡Bah, ya te estás sintiendo personaje de drama o de novela! ¡Contentémonos con serlo de... _nivola!_ ¡Hacer... hacer... hacer! ¿Te parece que hacemos poco con estar así hablando? Es la manía de la acción, es decir, de la pantomima. Dicen que pasan muchas cosas en un drama cuando los actores pueden hacer muchos gestos y dar grandes pasos y fingir duelos y saltar y... ¡pantomima! ¡pantomima! ¡Hablan demasiado!, dicen otras veces. Como si el hablar no fuese hacer. En el principio fué la Palabra y por la Palabra se hizo todo. Si ahora, por ejemplo, algún... _nivolista_ oculto ahí, tras ese armario, tomase nota taquigráfica de cuanto estamos aquí diciendo y lo reprodujese, es fácil que dijeran los lectores que no pasa nada, y sin embargo...\"},{\"heading\":false,\"text\":\"—¡Oh, si pudiesen verme por dentro, Víctor, te aseguro que no dirían tal cosa!\"},{\"heading\":false,\"text\":\"—¿Por dentro? ¿por dentro de quién? ¿de ti? ¿de mí? Nosotros no tenemos dentro. Cuando no dirían que aquí no pasa nada es cuando pudiesen verse por dentro de sí mismos, de ellos, de los que leen. El alma de un personaje de drama, de novela o de _nivola_ no tiene más interior que el que le da...\"},{\"heading\":false,\"text\":\"—Sí, su autor.\"},{\"heading\":false,\"text\":\"—No, el lector.\"},{\"heading\":false,\"text\":\"—Pues yo te aseguro, Víctor...\"},{\"heading\":false,\"text\":\"—No asegures nada y devórate. Es lo seguro.\"},{\"heading\":false,\"text\":\"—Y me devoro, me devoro. Empecé, Víctor, como una sombra, como una ficción; durante años he vagado como un fantasma, como un muñeco de niebla, sin creer en mi propia existencia, imaginándome ser un personaje fantástico que un oculto genio inventó para solazarse o desahogarse; pero ahora, después de lo que me ha hecho, después de lo que me han hecho, después de esta burla, de esta ferocidad de burla, ¡ahora sí!, ¡ahora me siento, ahora me palpo, ahora no dudo de mi existencia real!\"},{\"heading\":false,\"text\":\"—¡Comedia! ¡comedia! ¡comedia!\"},{\"heading\":false,\"text\":\"—¿Cómo?\"},{\"heading\":false,\"text\":\"—Sí, en la comedia entra el que se crea rey el que lo representa.\"},{\"heading\":false,\"text\":\"—Pero ¿qué te propones con todo esto?\"},{\"heading\":false,\"text\":\"—Distraerte. Y además que si, como te decía, un _nivolista_ oculto que nos esté oyendo toma nota de nuestras palabras para reproducirlas un día, el lector de la _nivola_ llegue a dudar, siquiera fuese un fugitivo momento, de su propia realidad de bulto y se crea a su vez no más que un personaje _nivolesco_, como nosotros.\"},{\"heading\":false,\"text\":\"—Y eso ¿para qué?\"},{\"heading\":false,\"text\":\"—Para redimirle.\"},{\"heading\":false,\"text\":\"—Sí, ya he oído decir que lo más liberador del arte es que le hace a uno olvidar que exista. Hay quien se hunde en la lectura de novelas para distraerse de sí mismo, para olvidar sus penas...\"},{\"heading\":false,\"text\":\"—No, lo más liberador del arte es que le hace a uno dudar de que exista.\"},{\"heading\":false,\"text\":\"—Y ¿qué es existir?\"},{\"heading\":false,\"text\":\"—¿Ves? Ya te vas curando; ya empiezas a devorarte. Lo prueba esa pregunta. _¡Ser o no ser...!_, que dijo Hamlet, uno de los que inventaron a Shakespeare.\"},{\"heading\":false,\"text\":\"—Pues a mí, Víctor, eso de _ser o no ser_ me ha parecido siempre una solemne vaciedad.\"},{\"heading\":false,\"text\":\"—Las frases, cuanto más profundas, son más vacías. No hay profundidad mayor que la de un pozo sin fondo. ¿Qué te parece lo más verdadero de todo?\"},{\"heading\":false,\"text\":\"—Pues... pues... lo de Descartes: «Pienso, luego soy».\"},{\"heading\":false,\"text\":\"—No, sino esto: A = A.\"},{\"heading\":false,\"text\":\"—Pero ¡eso no es nada!\"},{\"heading\":false,\"text\":\"—Y por lo mismo es lo más verdadero, porque no es nada. Pero esa otra vaciedad de Descartes, ¿la crees tan incontrovertible?\"},{\"heading\":false,\"text\":\"—¡Y tanto...!\"},{\"heading\":false,\"text\":\"—Pues bien; ¿dijo eso Descartes?\"},{\"heading\":false,\"text\":\"—¡Sí!\"},{\"heading\":false,\"text\":\"—Y no era verdad. Porque como Descartes no ha sido más que un ente ficticio, una invención de la historia, pues... ¡ni existió... ni pensó!\"},{\"heading\":false,\"text\":\"—Y ¿quién dijo eso?\"},{\"heading\":false,\"text\":\"—Eso no lo dijo nadie; eso se dijo ello mismo.\"},{\"heading\":false,\"text\":\"—Entonces, ¿el que era y pensaba era el pensamiento ese?\"},{\"heading\":false,\"text\":\"—¡Claro! Y, figúrate, eso equivale a decir que ser es pensar y lo que no piensa no es.\"},{\"heading\":false,\"text\":\"—¡Claro está!\"},{\"heading\":false,\"text\":\"—Pues no pienses, Augusto, no pienses. Y si te empeñas en pensar...\"},{\"heading\":false,\"text\":\"—¿Qué?\"},{\"heading\":false,\"text\":\"—¡Devórate!\"},{\"heading\":false,\"text\":\"—Es decir, ¿que me suicide...?\"},{\"heading\":false,\"text\":\"—En eso ya no me quiero meter. ¡Adiós!\"},{\"heading\":false,\"text\":\"Y se salió Víctor, dejando a Augusto perdido y confundido en sus cavilaciones.\"}]},{\"title\":\"Capítulo XXXI\",\"blocks\":[{\"heading\":false,\"text\":\"Aquella tempestad del alma de Augusto terminó, como en terrible calma, en decisión de suicidarse. Quería acabar consigo mismo, que era la fuente de sus desdichas propias. Mas antes de llevar a cabo su propósito, como el náufrago que se agarra a una débil tabla, ocurriósele consultarlo conmigo, con el autor de todo este relato. Por entonces había leído Augusto un ensayo mío en que, aunque de pasada, hablaba del suicidio, y tal impresión pareció hacerle, así como otras cosas que de mí había leído, que no quiso dejar este mundo sin haberme conocido y platicado un rato conmigo. Emprendió, pues, un viaje acá, a Salamanca, donde hace más de veinte años vivo, para visitarme.\"},{\"heading\":false,\"text\":\"Cuando me anunciaron su visita sonreí enigmáticamente y le mandé pasar a mi despacho-librería. Entró en él como un fantasma, miró a un retrato mío al óleo que allí preside a los libros de mi librería, y a una seña mía se sentó, frente a mí.\"},{\"heading\":false,\"text\":\"Empezó hablándome de mis trabajos literarios y más o menos filosóficos, demostrando conocerlos bastante bien, lo que no dejó, ¡claro está!, de halagarme, y enseguida empezó a contarme su vida y sus desdichas. Le atajé diciéndole que se ahorrase aquel trabajo, pues de las vicisitudes de su vida sabía yo tanto como él, y se lo demostré citándole los más íntimos pormenores y los que él creía más secretos. Me miró con ojos de verdadero terror y como quien mira a un ser increíble; creí notar que se le alteraba el color y traza del semblante y que hasta temblaba. Le tenía yo fascinado.\"},{\"heading\":false,\"text\":\"—¡Parece mentira!—repetía—¡parece mentira! A no verlo no lo creería... No sé si estoy despierto o soñando...\"},{\"heading\":false,\"text\":\"—Ni despierto ni soñando—le contesté.\"},{\"heading\":false,\"text\":\"—No me lo explico... no me lo explico—añadió—; mas puesto que usted parece saber sobre mí tanto como sé yo mismo, acaso adivine mi propósito...\"},{\"heading\":false,\"text\":\"—Sí—le dije—, tú—y recalqué este _tú_ con un tono autoritario—, tú, abrumado por tus desgracias, has concebido la diabólica idea de suicidarte, y antes de hacerlo, movido por algo que has leído en uno de mis últimos ensayos, vienes a consultármelo.\"},{\"heading\":false,\"text\":\"El pobre hombre temblaba como un azogado, mirándome como un poseído miraría. Intentó levantarse, acaso para huir de mí; no podía. No disponía de sus fuerzas.\"},{\"heading\":false,\"text\":\"—¡No, no te muevas!—le ordené.\"},{\"heading\":false,\"text\":\"—Es que... es que...—balbuceó.\"},{\"heading\":false,\"text\":\"—Es que tú no puedes suicidarte, aunque lo quieras.\"},{\"heading\":false,\"text\":\"—¿Cómo?—exclamó al verse de tal modo negado y contradicho.\"},{\"heading\":false,\"text\":\"—Sí. Para que uno se pueda matar a sí mismo, ¿qué es menester?—le pregunté.\"},{\"heading\":false,\"text\":\"—Que tenga valor para hacerlo—me contestó.\"},{\"heading\":false,\"text\":\"—No—le dije—, ¡que esté vivo!\"},{\"heading\":false,\"text\":\"—¡Desde luego!\"},{\"heading\":false,\"text\":\"—¡Y tú no estás vivo!\"},{\"heading\":false,\"text\":\"—¿Cómo que no estoy vivo? ¿es que me he muerto?—y empezó, sin darse clara cuenta de lo que hacía, a palparse a sí mismo.\"},{\"heading\":false,\"text\":\"—¡No, hombre, no!—le repliqué—. Te dije antes que no estabas ni despierto ni dormido, y ahora te digo que no estás ni muerto ni vivo.\"},{\"heading\":false,\"text\":\"—¡Acabe usted de explicarse de una vez, por Dios! ¡acabe de explicarse!—me suplicó consternado—, porque son tales las cosas que estoy viendo y oyendo esta tarde, que temo volverme loco.\"},{\"heading\":false,\"text\":\"—Pues bien; la verdad es, querido Augusto—le dije con la más dulce de mis voces—, que no puedes matarte porque no estás vivo, y que no estás vivo, ni tampoco muerto, porque no existes...\"},{\"heading\":false,\"text\":\"—¿Cómo que no existo?—exclamó.\"},{\"heading\":false,\"text\":\"—No, no existes más que como ente de ficción; no eres, pobre Augusto, más que un producto de mi fantasía y de las de aquellos de mis lectores que lean el relato que de tus fingidas venturas y malandanzas he escrito yo; tú no eres más que un personaje de novela, o de _nivola_, o como quieras llamarle. Ya sabes, pues, tu secreto.\"},{\"heading\":false,\"text\":\"Al oir esto quedóse el pobre hombre mirándome un rato con una de esas miradas perforadoras que parecen atravesar la mira e ir más allá, miró luego un momento a mi retrato al óleo que preside a mis libros, le volvió el color y el aliento, fué recobrándose, se hizo dueño de sí, apoyó los codos en mi camilla, a que estaba arrimado frente a mí, y la cara en las palmas de las manos, y mirándome con una sonrisa en los ojos me dijo lentamente:\"},{\"heading\":false,\"text\":\"—Mire usted bien, don Miguel... no sea que esté usted equivocado y que ocurra precisamente todo lo contrario de lo que usted se cree y me dice.\"},{\"heading\":false,\"text\":\"—Y ¿qué es lo contrario?—le pregunté alarmado de verle recobrar vida propia.\"},{\"heading\":false,\"text\":\"—No sea, mi querido don Miguel—añadió—, que sea usted y no yo el ente de ficción, el que no existe en realidad, ni vivo, ni muerto... No sea que usted no pase de ser un pretexto para que mi historia llegue al mundo...\"},{\"heading\":false,\"text\":\"—¡Eso más faltaba!—exclamé algo molesto.\"},{\"heading\":false,\"text\":\"—No se exalte usted así, señor de Unamuno—me replicó—, tenga calma. Usted ha manifestado dudas sobre mi existencia...\"},{\"heading\":false,\"text\":\"—Dudas no—le interrumpí—; certeza absoluta de que tú no existes fuera de mi producción novelesca.\"},{\"heading\":false,\"text\":\"—Bueno, pues no se incomode tanto si yo a mi vez dudo de la existencia de usted y no de la mía propia. Vamos a cuentas: ¿no ha sido usted el que no una sino varias veces ha dicho que Don Quijote y Sancho son no ya tan reales, sino más reales que Cervantes?\"},{\"heading\":false,\"text\":\"—No puedo negarlo, pero mi sentido al decir eso era...\"},{\"heading\":false,\"text\":\"—Bueno, dejémonos de esos sentires y vamos a otra cosa. Cuando un hombre dormido e inerte en la cama sueña algo, ¿qué es lo que más existe, él como conciencia que sueña o su sueño?\"},{\"heading\":false,\"text\":\"—¿Y si sueña que existe él mismo, el soñador?—le repliqué a mi vez.\"},{\"heading\":false,\"text\":\"—En ese caso, amigo don Miguel, le pregunté yo a mi vez, ¿de qué manera existe él, como soñador que se sueña, o como soñado por sí mismo? Y fíjese, además, en que al admitir esta discusión conmigo me reconoce ya existencia independiente de sí.\"},{\"heading\":false,\"text\":\"—¡No, eso no! ¡eso no!—le dije vivamente—. Yo necesito discutir, sin discusión no vivo y sin contradicción, y cuando no hay fuera de mí quien me discuta y contradiga invento dentro de mí quien lo haga. Mis monólogos son diálogos.\"},{\"heading\":false,\"text\":\"—Y acaso los diálogos que usted forje no sean más que monólogos...\"},{\"heading\":false,\"text\":\"—Puede ser. Pero te digo y repito que tú no existes fuera de mí...\"},{\"heading\":false,\"text\":\"—Y yo vuelvo a insinuarle a usted la idea de que es usted el que no existe fuera de mí y de los demás personajes a quienes usted cree haber inventado. Seguro estoy de que serían de mi opinión don Avito Carrascal y el gran don Fulgencio...\"},{\"heading\":false,\"text\":\"—No mientes a ese...\"},{\"heading\":false,\"text\":\"—Bueno, basta, no le moteje usted. Y vamos a ver, ¿qué opina usted de mi suicidio?\"},{\"heading\":false,\"text\":\"—Pues opino que como tú no existes más que en mi fantasía, te lo repito, y como no debes ni puedes hacer sino lo que a mí me dé la gana, y como no me da la real gana de que te suicides, no te suicidarás. ¡Lo dicho!\"},{\"heading\":false,\"text\":\"—Eso de no me da la real gana, señor de Unamuno, es muy español, pero es muy feo. Y además, aun suponiendo su peregrina teoría de que yo no existo de veras y usted sí, de que yo no soy más que un ente de ficción, producto de la fantasía novelesca o _nivolesca_ de usted, aun en ese caso yo no debo estar sometido a lo que llama usted su real gana, a su capricho. Hasta los llamados entes de ficción tienen su lógica interna...\"},{\"heading\":false,\"text\":\"—Sí, conozco esa cantata.\"},{\"heading\":false,\"text\":\"—En efecto; un novelista, un dramaturgo, no pueden hacer en absoluto lo que se les antoje de un personaje que creen; un ente de ficción novelesca no puede hacer, en buena ley de arte, lo que ningún lector esperaría que hiciese...\"},{\"heading\":false,\"text\":\"—Un ser novelesco tal vez...\"},{\"heading\":false,\"text\":\"—¿Entonces?\"},{\"heading\":false,\"text\":\"—Pero un ser _nivolesco_...\"},{\"heading\":false,\"text\":\"—Dejemos esas bufonadas que me ofenden y me hieren en lo más vivo. Yo, sea por mí mismo, según creo, sea porque usted me lo ha dado, según supone usted, tengo mi carácter, mi modo de ser, mi lógica interior, y esta lógica me pide que me suicide...\"},{\"heading\":false,\"text\":\"—¡Eso te creerás tú, pero te equivocas!\"},{\"heading\":false,\"text\":\"—A ver, ¿por qué me equivoco? ¿en qué me equivoco? Muéstreme usted en qué está mi equivocación. Como la ciencia más difícil que hay es la de conocerse uno a sí mismo, fácil es que esté yo equivocado y que no sea el suicidio la solución más lógica de mis desventuras, pero demuéstremelo usted. Porque si es difícil, amigo don Miguel, ese conocimiento propio o de sí mismo, hay otro conocimiento que me parece no menos difícil que él...\"},{\"heading\":false,\"text\":\"—¿Cuál es?—le pregunté.\"},{\"heading\":false,\"text\":\"Me miró con una enigmática y socarrona sonrisa y lentamente me dijo:\"},{\"heading\":false,\"text\":\"—Pues más difícil aún que el que uno se conozca a sí mismo es el que un novelista o un autor dramático conozca bien a los personajes que finge o cree fingir...\"},{\"heading\":false,\"text\":\"Empezaba yo a estar inquieto con estas salidas de Augusto, y a perder mi paciencia.\"},{\"heading\":false,\"text\":\"—E insisto—añadió—en que aun concedido que usted me haya dado el ser y un ser ficticio, no puede usted, así como así y porque sí, porque le dé la real gana, como dice, impedirme que me suicide.\"},{\"heading\":false,\"text\":\"—¡Bueno, basta!, ¡basta!—exclamé dando un puñetazo en la camilla—¡cállate! ¡no quiero oir más impertinencias...! ¡Y de una criatura mía! Y como ya me tienes harto y además no sé ya qué hacer de ti, decido ahora mismo no ya que no te suicides, sino matarte yo. ¡Vas a morir, pues, pero pronto! ¡muy pronto!\"},{\"heading\":false,\"text\":\"—¿Cómo?—exclamó Augusto sobresaltado—¿que me va usted a dejar morir, a hacerme morir, a matarme?\"},{\"heading\":false,\"text\":\"—¡Sí, voy a hacer que mueras!\"},{\"heading\":false,\"text\":\"—¡Ah, eso nunca! ¡nunca! ¡nunca!—gritó.\"},{\"heading\":false,\"text\":\"—¡Ah!—le dije mirándole con lástima y rabia—¿conque estabas dispuesto a matarte y no quieres que yo te mate? ¿Conque ibas a quitarte la vida y te resistes a que te la quite yo?\"},{\"heading\":false,\"text\":\"—Sí, no es lo mismo...\"},{\"heading\":false,\"text\":\"—En efecto, he oído contar casos análogos. He oído de uno que salió una noche armado de un revólver y dispuesto a quitarse la vida, salieron unos ladrones a robarle, le atacaron, se defendió, mató a uno de ellos, huyeron los demás, y al ver que había comprado su vida por la de otro renunció a su propósito.\"},{\"heading\":false,\"text\":\"—Se comprende—observó Augusto—; la cosa era quitar a alguien la vida, matar un hombre, y ya que mató a otro, ¿a qué había de matarse? Los más de los suicidas son homicidas frustrados; se matan a sí mismos por falta de valor para matar a otros...\"},{\"heading\":false,\"text\":\"—Ah, ya, te entiendo, Augusto, te entiendo. Tú quieres decir que si tuvieses valor para matar a Eugenia o a Mauricio o a los dos no pensarías en matarte a ti mismo, ¿eh?\"},{\"heading\":false,\"text\":\"—¡Mire usted, precisamente a esos... no!\"},{\"heading\":false,\"text\":\"—¿A quién, pues?\"},{\"heading\":false,\"text\":\"—¡A usted!—y me miró a los ojos.\"},{\"heading\":false,\"text\":\"—¿Cómo?—exclamé poniéndome en pie—¿cómo? Pero ¿se te ha pasado por la imaginación matarme? ¿tú? ¿y a mí?\"},{\"heading\":false,\"text\":\"—Siéntese y tenga calma. ¿O es que cree usted, amigo don Miguel, que sería el primer caso en que un ente de ficción, como usted me llama, matara a aquel a quien creyó darle el ser... ficticio?\"},{\"heading\":false,\"text\":\"—¡Esto ya es demasiado—decía yo paseándome por mi despacho—, esto pasa de la raya! Esto no sucede más que...\"},{\"heading\":false,\"text\":\"—Más que en las _nivolas_—concluyó él con sorna.\"},{\"heading\":false,\"text\":\"—¡Bueno, basta!, ¡basta!, ¡basta! ¡Esto no se puede tolerar! Vienes a consultarme, a mí, y tú empiezas por discutirme mi propia existencia, después el derecho que tengo a hacer de ti lo que me dé la real gana, sí, así como suena, lo que me dé la real gana, lo que me salga de...\"},{\"heading\":false,\"text\":\"—No sea usted tan español, don Miguel...\"},{\"heading\":false,\"text\":\"—¡Y eso más, mentecato! ¡Pues sí, soy español!, español de nacimiento, de educación, de cuerpo, de espíritu, de lengua y hasta de profesión y oficio; español sobre todo y ante todo y el españolismo es mi religión, y el cielo en que quiero creer es una España celestial y eterna y mi Dios un Dios español, el de Nuestro Señor Don Quijote, un Dios que piensa en español y en español dijo: ¡sea luz!, y su verbo fué verbo español...\"},{\"heading\":false,\"text\":\"—Bien, ¿y qué?—me interrumpió, volviéndome a la realidad.\"},{\"heading\":false,\"text\":\"—Y luego has insinuado la idea de matarme. ¿Matarme? ¿a mí? ¿tú? ¡Morir yo a manos de una de mis criaturas! No tolero más. Y para castigar tu osadía y esas doctrinas disolventes, extravagantes, anárquicas, con que te me has venido, resuelvo y fallo que te mueras. En cuanto llegues a tu casa te morirás. ¡Te morirás, te lo digo, te morirás!\"},{\"heading\":false,\"text\":\"—Pero ¡por Dios...!—exclamó Augusto, ya suplicante y de miedo tembloroso y pálido.\"},{\"heading\":false,\"text\":\"—No hay Dios que valga. ¡Te morirás!\"},{\"heading\":false,\"text\":\"—Es que yo quiero vivir, don Miguel, quiero vivir, quiero vivir...\"},{\"heading\":false,\"text\":\"—¿No pensabas matarte?\"},{\"heading\":false,\"text\":\"—Oh, si es por eso, yo le juro, señor de Unamuno, que no me mataré, que no me quitaré esta vida que Dios o usted me han dado; se lo juro... Ahora que usted quiere matarme quiero yo vivir, vivir, vivir...\"},{\"heading\":false,\"text\":\"—¡Vaya una vida!—exclamé.\"},{\"heading\":false,\"text\":\"—Sí, la que sea. Quiero vivir, aunque vuelva a ser burlado, aunque otra Eugenia y otro Mauricio me desgarren el corazón. Quiero vivir, vivir, vivir...\"},{\"heading\":false,\"text\":\"—No puede ser ya... no puede ser...\"},{\"heading\":false,\"text\":\"—Quiero vivir, vivir... y ser yo, yo, yo...\"},{\"heading\":false,\"text\":\"—Pero si tú no eres sino lo que yo quiera...\"},{\"heading\":false,\"text\":\"—¡Quiero ser yo, ser yo! ¡quiero vivir!—y le lloraba la voz.\"},{\"heading\":false,\"text\":\"—No puede ser... no puede ser...\"},{\"heading\":false,\"text\":\"—Mire usted, don Miguel, por sus hijos, por su mujer, por lo que más quiera... Mire que usted no será usted... que se morirá...\"},{\"heading\":false,\"text\":\"Cayó a mis pies de hinojos, suplicante y exclamando:\"},{\"heading\":false,\"text\":\"—¡Don Miguel, por Dios, quiero vivir, quiero ser yo!\"},{\"heading\":false,\"text\":\"—¡No puede ser, pobre Augusto—le dije cojiéndole de una mano y levantándole—, no puede ser! Lo tengo ya escrito y es irrevocable; no puedes vivir más. No sé qué hacer ya de ti. Dios, cuando no sabe qué hacer de nosotros, nos mata. Y no se me olvida que pasó por tu mente la idea de matarme...\"},{\"heading\":false,\"text\":\"—Pero si yo, don Miguel...\"},{\"heading\":false,\"text\":\"—No importa; sé lo que me digo. Y me temo que, en efecto, si no te mato pronto acabes por matarme tú.\"},{\"heading\":false,\"text\":\"—Pero ¿no quedamos en que...?\"},{\"heading\":false,\"text\":\"—No puede ser, Augusto, no puede ser. Ha llegado tu hora. Está ya escrito y no puedo volverme atrás. Te morirás. Para lo que ha de valerte ya la vida...\"},{\"heading\":false,\"text\":\"—Pero... por Dios...\"},{\"heading\":false,\"text\":\"—No hay pero ni Dios que valgan. ¡Vete!\"},{\"heading\":false,\"text\":\"—¿Conque no, eh?—me dijo—¿conque no? No quiere usted dejarme ser yo, salir de la niebla, vivir, vivir, vivir, verme, oírme, tocarme, sentirme, dolerme, serme; ¿conque no lo quiere? ¿conque he de morir ente de ficción? Pues bien, mi señor creador don Miguel, ¡también usted se morirá, también usted, y se volverá a la nada de que salió...! ¡Dios dejará de soñarle! ¡Se morirá usted, sí, se morirá, aunque no lo quiera; se morirá usted y se morirán todos los que lean mi historia, todos, todos, todos, sin quedar uno! ¡Entes de ficción como yo; lo mismo que yo! Se morirán todos, todos, todos. Os lo digo yo, Augusto Pérez, ente ficticio como vosotros, _nivolesco_ lo mismo que vosotros. Porque usted, mi creador, mi don Miguel, no es usted más que otro ente _nivolesco_, y entes _nivolescos_ sus lectores, lo mismo que yo, que Augusto Pérez, que su víctima...\"},{\"heading\":false,\"text\":\"—¿Víctima?—exclamé.\"},{\"heading\":false,\"text\":\"—¡Víctima, sí! ¡Crearme para dejarme morir! ¡Usted también se morirá! El que crea se crea y el que se crea se muere. ¡Morirá usted, don Miguel, morirá usted, y morirán todos los que me piensen! ¡A morir, pues!\"},{\"heading\":false,\"text\":\"Este supremo esfuerzo de pasión de vida, de ansia de inmortalidad, le dejó extenuado al pobre Augusto.\"},{\"heading\":false,\"text\":\"Y le empujé a la puerta, por la que salió cabizbajo. Luego se tanteó como si dudase ya de su propia existencia. Yo me enjugué una lágrima furtiva.\"}]},{\"title\":\"Capítulo XXXII\",\"blocks\":[{\"heading\":false,\"text\":\"Aquella misma noche se partió Augusto de esta ciudad de Salamanca adonde vino a verme. Fuése con la sentencia de muerte sobre el corazón y convencido de que no le sería ya hacedero, aunque lo intentara, suicidarse. El pobrecillo, recordando mi sentencia, procuraba alargar lo más posible su vuelta a su casa, pero una misteriosa atracción, un impulso íntimo le arrastraba a ella. Su viaje fué lamentable. Iba en el tren contando los minutos, pero contándolos al pie de la letra: uno, dos, tres, cuatro... Todas sus desventuras, todo el triste ensueño de sus amores con Eugenia y con Rosario, toda la historia tragicómica de su frustrado casamiento habíanse borrado de su memoria o habíanse más bien fundido en una niebla. Apenas si sentía el contacto del asiento sobre que descansaba ni el peso de su propio cuerpo. «¿Será verdad que no existo realmente?—se decía—¿tendrá razón este hombre al decir que no soy más que un producto de su fantasía, un puro ente de ficción?»\"},{\"heading\":false,\"text\":\"Tristísima, dolorosísima había sido últimamente su vida, pero le era mucho más triste, le era más doloroso pensar que todo ello no hubiese sido sino sueño, y no sueño de él, sino sueño mío. La nada le parecía más pavorosa que el dolor. ¡Soñar uno que vive... pase, pero que le sueñe otro...!\"},{\"heading\":false,\"text\":\"«Y ¿por qué no he de existir yo?—se decía—¿por qué? Supongamos que es verdad que ese hombre me ha fingido, me ha soñado, me ha producido en su imaginación; pero ¿no vivo ya en las de otros, en las de aquellos que lean el relato de mi vida? Y si vivo así en las fantasías de varios, ¿no es acaso real lo que es de varios y no de uno solo? Y ¿por qué surgiendo de las páginas del libro en que se deposite el relato de mi ficticia vida, o más bien de las mentes de aquellos que la lean—de vosotros, los que ahora la leéis—, por qué no he de existir como un alma eterna y eternamente dolorosa? ¿por qué?»\"},{\"heading\":false,\"text\":\"El pobre no podía descansar. Pasaban a su vista los páramos castellanos, ya los encinares, ya los pinares; contemplaba las cimas nevadas de las sierras, y viendo hacia atrás, detrás de su cabeza, envueltas en bruma las figuras de los compañeros y compañeras de su vida, sentíase arrastrado a la muerte.\"},{\"heading\":false,\"text\":\"Llegó a su casa, llamó, y Liduvina, que salió a abrirle, palideció al verle.\"},{\"heading\":false,\"text\":\"—¿Qué es eso, Liduvina, de qué te asustas?\"},{\"heading\":false,\"text\":\"—¡Jesús! ¡Jesús! El señorito parece más muerto que vivo... Trae cara de ser del otro mundo...\"},{\"heading\":false,\"text\":\"—Del otro mundo vengo, Liduvina, y al otro mundo voy. Y no estoy ni muerto ni vivo.\"},{\"heading\":false,\"text\":\"—Pero ¿es que se ha vuelto loco? ¡Domingo! ¡Domingo!\"},{\"heading\":false,\"text\":\"—No llames a tu marido, Liduvina. Y no estoy loco, ¡no! Ni estoy, te repito, muerto, aunque me moriré muy pronto, ni tampoco vivo.\"},{\"heading\":false,\"text\":\"—Pero ¿qué dice usted?\"},{\"heading\":false,\"text\":\"—Que no existo, Liduvina, que no existo; que soy un ente de ficción, como un personaje de novela...\"},{\"heading\":false,\"text\":\"—¡Bah, cosas de libros! Tome algo fortificante, acuéstese, arrópese y no haga caso de esas fantasías...\"},{\"heading\":false,\"text\":\"—Pero ¿tú crees, Liduvina, que yo existo?\"},{\"heading\":false,\"text\":\"—¡Vamos, vamos, déjese de esas andróminas, señorito; a cenar y a la cama! ¡Y mañana será otro día!\"},{\"heading\":false,\"text\":\"«Pienso, luego soy—se decía Augusto, añadiéndose—: Todo lo que piensa es y todo lo que es piensa. Sí, todo lo que es piensa. Soy, luego pienso.»\"},{\"heading\":false,\"text\":\"Al pronto no sentía ganas ningunas de cenar y no más que por hábito y por acceder a los ruegos de sus fieles sirvientes pidió le sirviesen un par de huevos pasados por agua, y nada más, una cosa lijerita. Mas a medida que iba comiéndoselos abríasele un extraño apetito, una rabia de comer más y más. Y pidió otros dos huevos, y después un bisteque.\"},{\"heading\":false,\"text\":\"—Así, así—le decía Liduvina—; coma usted; eso debe de ser debilidad y no más. El que no come se muere.\"},{\"heading\":false,\"text\":\"—Y el que come también, Liduvina—observó tristemente Augusto.\"},{\"heading\":false,\"text\":\"—Sí, pero no de hambre.\"},{\"heading\":false,\"text\":\"—¿Y qué más da morirse de hambre que de otra enfermedad cualquiera?\"},{\"heading\":false,\"text\":\"Y luego pensó: «Pero ¡no, no! ¡yo no puedo morirme; sólo se muere el que está vivo, el que existe, y yo, como no existo, no puedo morirme... soy inmortal! No hay inmortalidad como la de aquello que, cual yo, no ha nacido y no existe. Un ente de ficción es una idea, y una idea es siempre inmortal...»\"},{\"heading\":false,\"text\":\"—¡Soy inmortal! ¡soy inmortal!—exclamó Augusto.\"},{\"heading\":false,\"text\":\"—¿Qué dice usted?—acudió Liduvina.\"},{\"heading\":false,\"text\":\"—Que me traigas ahora... ¡qué sé yo!... jamón en dulce, fiambres, _foie gras_, lo que haya... ¡Siento un apetito voraz!\"},{\"heading\":false,\"text\":\"—Así me gusta verle, señorito, así. ¡Coma, coma, que el que tiene apetito es que está sano y el que está sano vive!\"},{\"heading\":false,\"text\":\"—Pero, Liduvina, ¡yo no vivo!\"},{\"heading\":false,\"text\":\"—Pero ¿qué dice?\"},{\"heading\":false,\"text\":\"—Claro, yo no vivo. Los inmortales no vivimos, y yo no vivo, sobrevivo; ¡yo soy idea! ¡soy idea!\"},{\"heading\":false,\"text\":\"Empezó a devorar el jamón en dulce. «Pero si como—se decía—, ¿como es que no vivo? ¡Como, luego existo! No cabe duda alguna. _Edo, ergo sum!_ ¿A qué se deberá este voraz apetito?» Y entonces recordó haber leído varias veces que los condenados a muerte en las horas que pasan en capilla se dedican a comer. «¡Es cosa—pensaba—de que nunca he podido darme cuenta...! Aquello otro que nos cuenta Renan en su _Abadesa de Jouarre_ se comprende... Se comprende que una pareja de condenados a muerte, antes de morir sientan el instinto de sobrevivirse reproduciéndose, pero ¡comer...! Aunque sí, sí, es el cuerpo que se defiende. El alma, al enterarse de que va a morir, se entristece o se exalta, pero el cuerpo, si es un cuerpo sano, entra en apetito furioso. Porque también el cuerpo se entera. Sí, es mi cuerpo, mi cuerpo el que se defiende. ¡Como vorazmente, luego voy a morir!»\"},{\"heading\":false,\"text\":\"—Liduvina, tráeme queso y pastas... y fruta...\"},{\"heading\":false,\"text\":\"—Esto ya me parece excesivo, señorito; es demasiado. ¡Le va a hacer daño!\"},{\"heading\":false,\"text\":\"—¿Pues no decías que el que come vive?\"},{\"heading\":false,\"text\":\"—Sí, pero no así, como está usted comiendo ahora... Y ya sabe mi señorito aquello de «más mató la cena, que sanó Avicena».\"},{\"heading\":false,\"text\":\"—A mí no puede matarme la cena.\"},{\"heading\":false,\"text\":\"—¿Por qué?\"},{\"heading\":false,\"text\":\"—Porque no vivo, no existo, ya te lo he dicho.\"},{\"heading\":false,\"text\":\"Liduvina fué a llamar a su marido, a quien dijo:\"},{\"heading\":false,\"text\":\"—Domingo, me parece que el señorito se ha vuelto loco... Dice unas cosas muy raras... cosas de libros... que no existe... qué sé yo...\"},{\"heading\":false,\"text\":\"—¿Qué es eso, señorito—le dijo Domingo entrando—, qué le pasa?\"},{\"heading\":false,\"text\":\"—Ay, Domingo—contestó Augusto con voz de fantasma—, no lo puedo remediar; siento un terror loco a acostarme...\"},{\"heading\":false,\"text\":\"—Pues no se acueste.\"},{\"heading\":false,\"text\":\"—No, no, es preciso; no puedo tenerme en pie.\"},{\"heading\":false,\"text\":\"—Yo creo que el señorito debe pasear la cena. Ha cenado en demasía.\"},{\"heading\":false,\"text\":\"Intentó ponerse en pie Augusto.\"},{\"heading\":false,\"text\":\"—¿Lo ves, Domingo, lo ves? No puedo tenerme en pie.\"},{\"heading\":false,\"text\":\"—Claro, con tanto embutir en el estómago...\"},{\"heading\":false,\"text\":\"—Al contrario, con lastre se tiene uno mejor en pie. Es que no existo. Mira, ahora poco, al cenar me parecía como si todo eso me fuese cayendo desde la boca en un tonel sin fondo. El que come vive, tiene razón Liduvina, pero el que come como he comido yo esta noche, por desesperación, es que no existe. Yo no existo...\"},{\"heading\":false,\"text\":\"—Vaya, vaya, déjese de bobadas; tome su café y su copa, para empujar todo eso y asentarlo, y vamos a dar un paseo. Le acompañaré yo.\"},{\"heading\":false,\"text\":\"—No, no puedo tenerme en pie, ¿lo ves?\"},{\"heading\":false,\"text\":\"—Es verdad.\"},{\"heading\":false,\"text\":\"—Ven que me apoye en ti. Quiero que esta noche duermas en mi cuarto, en un colchón que pondremos para ti, que me veles...\"},{\"heading\":false,\"text\":\"—Mejor será, señorito, que yo no me acueste, sino que me quede allí, en una butaca...\"},{\"heading\":false,\"text\":\"—No, no, quiero que te acuestes y que te duermas; quiero sentirte dormir, oírte roncar mejor...\"},{\"heading\":false,\"text\":\"—Como usted quiera...\"},{\"heading\":false,\"text\":\"—Y ahora, mira, tráeme un pliego de papel. Voy a poner un telegrama que enviarás a su destino así que yo me muera...\"},{\"heading\":false,\"text\":\"—Pero ¡señorito...!\"},{\"heading\":false,\"text\":\"—¡Haz lo que te digo!\"},{\"heading\":false,\"text\":\"Domingo obedeció, llevóle el papel y el tintero y Augusto escribió:\"},{\"heading\":false,\"text\":\"«Salamanca.\"},{\"heading\":false,\"text\":\"Unamuno.\"},{\"heading\":false,\"text\":\"Se salió usted con la suya. He muerto.\"},{\"heading\":false,\"text\":\"Augusto Pérez.»\"},{\"heading\":false,\"text\":\"—En cuanto me muera lo envías, ¿eh?\"},{\"heading\":false,\"text\":\"—Como usted quiera—contestó el criado por no discutir más con el amo.\"},{\"heading\":false,\"text\":\"Fueron los dos al cuarto. El pobre Augusto temblaba de tal modo al ir a desnudarse que no podía ni aun cojerse las ropas para quitárselas.\"},{\"heading\":false,\"text\":\"—¡Desnúdame tú!—le dijo a Domingo.\"},{\"heading\":false,\"text\":\"—Pero ¿qué le pasa a usted, señorito? ¡Si parece que le ha visto al diablo! Está usted blanco y frío como la nieve. ¿Quiere que se le llame al médico?\"},{\"heading\":false,\"text\":\"—No, no, es inútil.\"},{\"heading\":false,\"text\":\"—Le calentaremos la cama...\"},{\"heading\":false,\"text\":\"—¿Para qué? ¡Déjalo! Y desnúdame del todo, del todo; déjame como mi madre me parió, como nací... ¡si es que nací!\"},{\"heading\":false,\"text\":\"—¡No diga usted esas cosas, señorito!\"},{\"heading\":false,\"text\":\"—Ahora échame, échame tú mismo a la cama, que no me puedo mover.\"},{\"heading\":false,\"text\":\"El pobre Domingo, aterrado a su vez, acostó a su pobre amo.\"},{\"heading\":false,\"text\":\"—Y ahora, Domingo, ve diciéndome al oído, despacito, el padre nuestro, el ave maría y la salve. Así... así... poco a poco... poco a poco...—y después que los hubo repetido mentalmente: ahora, mira, cójeme la mano derecha, sácamela, me parece que no es mía, como si la hubiese perdido... y ayúdame a que me persigne... así... así... Este brazo debe de estar muerto... Mira a ver si tengo pulso... Ahora déjame, déjame a ver si duermo un poco... pero tápame, tápame bien...\"},{\"heading\":false,\"text\":\"—Sí, mejor es que duerma—le dijo Domingo mientras le subía el embozo de las mantas—; esto se le pasará durmiendo...\"},{\"heading\":false,\"text\":\"—Sí, durmiendo se me pasará... Pero, di, ¿es que no he hecho nunca más que dormir? ¿más que soñar? ¿Todo eso ha sido más que una niebla?\"},{\"heading\":false,\"text\":\"—Bueno, bueno, déjese de esas cosas. Todo eso no son sino cosas de libros, como dice mi Liduvina.\"},{\"heading\":false,\"text\":\"—Cosas de libros... cosas de libros... ¿Y qué no es cosa de libros, Domingo? ¿Es que antes de haber libros, en una u otra forma, antes de haber relatos, de haber palabra, de haber pensamiento, había algo? ¿Y es que después de acabarse el pensamiento quedará algo? ¡Cosas de libros! ¿Y quién no es cosa de libros? ¿Conoces a don Miguel de Unamuno, Domingo?\"},{\"heading\":false,\"text\":\"—Sí, algo he leído de él en los papeles. Dicen que es un señor un poco raro que se dedica a decir verdades que no hacen al caso...\"},{\"heading\":false,\"text\":\"—Pero ¿le conoces?\"},{\"heading\":false,\"text\":\"—¿Yo? ¿para qué?\"},{\"heading\":false,\"text\":\"—Pues también Unamuno es cosa de libros... Todos lo somos... ¡Y él se morirá, sí, se morirá, se morirá también, aunque no lo quiera... se morirá! Y esa será mi venganza. ¿No quiere dejarme vivir? ¡Pues se morirá, se morirá, se morirá!\"},{\"heading\":false,\"text\":\"—¡Bueno, déjele en paz a ese señor, que se muera cuando Dios lo haga, y usted a dormirse!\"},{\"heading\":false,\"text\":\"—A dormir... a dormir... a soñar... ¡Morir... dormir... dormir... soñar acaso...! Pienso, luego soy; soy, luego pienso... ¡No existo, no! ¡no existo... madre mía! Eugenia... Rosario... Unamuno...—y se quedó dormido.\"},{\"heading\":false,\"text\":\"Al poco rato se incorporó en la cama lívido, anhelante, con los ojos todo negros y despavoridos, mirando más allá de las tinieblas, y gritando: «¡Eugenia, Eugenia!» Domingo acudió a él. Dejó caer la cabeza sobre el pecho y se quedó muerto.\"},{\"heading\":false,\"text\":\"Cuando llegó el médico se imaginó al pronto que aún vivía, habló de sangrarle, de ponerle sinapismos, pero pronto pudo convencerse de la triste verdad.\"},{\"heading\":false,\"text\":\"—Ha sido cosa del corazón... un ataque de asistolia—dijo el médico.\"},{\"heading\":false,\"text\":\"—No, señor—contestó Domingo—, ha sido un asiento. Cenó horriblemente, como no acostumbra, de una manera desusada en él, como si quisiera...\"},{\"heading\":false,\"text\":\"—Sí, desquitarse de lo que no habría de comer en adelante, ¿no es eso? Acaso el corazón presintió su muerte.\"},{\"heading\":false,\"text\":\"—Pues yo—dijo Liduvina—creo que ha sido de la cabeza. Es verdad que cenó de un modo disparatado, pero como sin darse cuenta de lo que hacía y diciendo disparates...\"},{\"heading\":false,\"text\":\"—¿Qué disparates?—preguntó el médico.\"},{\"heading\":false,\"text\":\"—Que él no existía y otras cosas así...\"},{\"heading\":false,\"text\":\"—¿Disparates?—añadió el médico entre dientes y cual hablando consigo mismo—¿quién sabe si existía o no y menos él mismo...? Uno mismo es quien menos sabe de su existencia... No se existe sino para los demás...\"},{\"heading\":false,\"text\":\"Y luego en voz alta agregó:\"},{\"heading\":false,\"text\":\"—El corazón, el estómago y la cabeza son los tres una sola y misma cosa.\"},{\"heading\":false,\"text\":\"—Sí, forman parte del cuerpo—dijo Domingo.\"},{\"heading\":false,\"text\":\"—Y el cuerpo es una sola y misma cosa.\"},{\"heading\":false,\"text\":\"—¡Sin duda!\"},{\"heading\":false,\"text\":\"—Pero más que usted lo cree...\"},{\"heading\":false,\"text\":\"—¿Y usted sabe, señor mío, cuánto lo creo yo?\"},{\"heading\":false,\"text\":\"—También es cierto y veo que no es usted torpe.\"},{\"heading\":false,\"text\":\"—No me tengo por tal, señor médico, y no comprendo a esas gentes que a cualquier persona con quien tropiezan parecen estimarla tonta mientras no pruebe lo contrario.\"},{\"heading\":false,\"text\":\"—Bueno, pues, como iba diciendo—siguió el médico—, el estómago elabora los jugos que hacen la sangre, el corazón riega con ellos a la cabeza y al estómago para que funcione, y la cabeza rige los movimientos del estómago y del corazón. Y por lo tanto este señor don Augusto ha muerto de las tres cosas, de todo el cuerpo, por síntesis.\"},{\"heading\":false,\"text\":\"—Pues yo creo—intervino Liduvina—que a mi señorito se le había metido en la cabeza morirse y, ¡claro!, el que se empeña en morir, al fin se muere.\"},{\"heading\":false,\"text\":\"—¡Es claro!—dijo el médico—. Si uno no creyese morirse, ni aun hallándose en la agonía, acaso no moriría. Pero así que le entre la menor duda de que no puede menos de morir, está perdido.\"},{\"heading\":false,\"text\":\"—Lo de mi señorito ha sido un suicidio y nada más que un suicidio. Ponerse a cenar como cenó viniendo como venía es un suicidio y nada más que un suicidio. ¡Se salió con la suya!\"},{\"heading\":false,\"text\":\"—Disgustos acaso...\"},{\"heading\":false,\"text\":\"—Y grandes, ¡muy grandes! ¡mujeres!\"},{\"heading\":false,\"text\":\"—¡Ya, ya! Pero, en fin, la cosa no tiene ya otro remedio que preparar el entierro.\"},{\"heading\":false,\"text\":\"Domingo lloraba.\"}]},{\"title\":\"Capítulo XXXIII\",\"blocks\":[{\"heading\":false,\"text\":\"Cuando recibí el telegrama comunicándome la muerte del pobre Augusto, y supe luego las circunstancias todas de ella, me quedé pensando en si hice o no bien en decirle lo que le dije la tarde aquella en que vino a visitarme y consultar conmigo su propósito de suicidarse. Y hasta me arrepentí de haberle matado. Llegué a pensar que tenía él razón y que debí haberle dejado salirse con la suya suicidándose. Y se me ocurrió si le resucitaría.\"},{\"heading\":false,\"text\":\"«Sí—me dije—, voy a resucitarle y que haga luego lo que se le antoje, que se suicide si es así su capricho.» Y con esta idea de resucitarle me quedé dormido.\"},{\"heading\":false,\"text\":\"A poco de haberme dormido se me apareció Augusto en sueños. Estaba blanco, con la blancura de una nube, y sus contornos iluminados como por un sol poniente. Me miró fijamente y me dijo:\"},{\"heading\":false,\"text\":\"—¡Aquí estoy otra vez!\"},{\"heading\":false,\"text\":\"—¿A qué vienes?—le dije.\"},{\"heading\":false,\"text\":\"—A despedirme de usted, don Miguel, a despedirme de usted hasta la eternidad y a mandarle, así, a mandarle, no a rogarle, a mandarle que escriba usted la _nivola_ de mis aventuras...\"},{\"heading\":false,\"text\":\"—¡Está ya escrita!\"},{\"heading\":false,\"text\":\"—Lo sé, todo está escrito. Y vengo también a decirle que eso que usted ha pensado de resucitarme para que luego me quite yo a mí mismo mi vida es un disparate, más aún, es una imposibilidad...\"},{\"heading\":false,\"text\":\"—¿Imposibilidad?—le dije yo; por supuesto, todo esto en sueños.\"},{\"heading\":false,\"text\":\"—¡Sí, una imposibilidad! Aquella tarde en que nos vimos y hablamos en el despacho de usted, ¿recuerda?, estando usted despierto y no como ahora dormido y soñando, le dije a usted que nosotros, los entes de ficción según usted, tenemos nuestra lógica y que no sirve que quien nos finge pretenda hacer de nosotros lo que le dé la gana, ¿recuerda?\"},{\"heading\":false,\"text\":\"—Sí, que lo recuerdo.\"},{\"heading\":false,\"text\":\"—Y ahora de seguro que, aunque tan español, no tendrá usted real gana de nada, ¿verdad, don Miguel?\"},{\"heading\":false,\"text\":\"—No, no siento gana de nada.\"},{\"heading\":false,\"text\":\"—No, el que duerme y sueña no tiene reales ganas de nada. Y usted y sus compatriotas duermen y sueñan, y sueñan que tienen ganas, pero no las tienen de veras.\"},{\"heading\":false,\"text\":\"—Da gracias a que estoy durmiendo—le dije—, que si no...\"},{\"heading\":false,\"text\":\"—Es igual. Y respecto a eso de resucitarme he de decirle que no le es hacedero, que no lo puede aunque lo quiera o aunque sueñe que lo quiere...\"},{\"heading\":false,\"text\":\"—Pero ¡hombre!\"},{\"heading\":false,\"text\":\"—Sí, a un ente de ficción como a uno de carne y hueso, a lo que llama usted hombre de carne y hueso y no de ficción de carne ni de ficción de hueso, puede uno engendrarlo y lo puede matar, pero una vez que lo mató no puede, ¡no!, no puede resucitarlo. Hacer un hombre mortal y carnal, de carne y hueso, que respire aire, es cosa fácil, muy fácil, demasiado fácil por desgracia... matar a un hombre mortal y carnal, de carne y hueso, que respire aire, es cosa fácil, muy fácil, demasiado fácil por desgracia... pero ¿resucitarlo? ¡resucitarlo es imposible!\"},{\"heading\":false,\"text\":\"—¡En efecto—le dije—, es imposible!\"},{\"heading\":false,\"text\":\"—Pues lo mismo—me contestó—, exactamente lo mismo sucede con eso que usted llama entes de ficción; es fácil darnos ser, acaso demasiado fácil, y es fácil, facilísimo, matarnos, acaso demasiadamente demasiado fácil, pero ¿resucitarnos?, no hay quien haya resucitado de veras a un ente de ficción que de veras se hubiese muerto. ¿Cree usted posible resucitar a Don Quijote?—me preguntó.\"},{\"heading\":false,\"text\":\"—¡Imposible!—contesté.\"},{\"heading\":false,\"text\":\"—Pues en el mismo caso estamos todos los demás entes de ficción.\"},{\"heading\":false,\"text\":\"—¿Y si te vuelvo a soñar?\"},{\"heading\":false,\"text\":\"—No se sueña dos veces el mismo sueño. Ese que usted vuelva a soñar y crea soy yo será otro. Y ahora, ahora que está usted dormido y soñando y que reconoce usted estarlo y que yo soy un sueño y reconozco serlo, ahora vuelvo a decirle a usted lo que tanto le excitó cuando la otra vez se lo dije: mire: usted, mi querido don Miguel, no vaya a ser que sea usted el ente de ficción, el que no existe en realidad, ni vivo ni muerto... no vaya a ser que no pase usted de un pretexto para que mi historia, y otras historias como la mía, corran por el mundo. Y luego, cuando usted se muera del todo, llevemos su alma nosotros. No, no, no se altere usted, que aunque dormido y soñando aún vive. ¡Y ahora, adiós!\"},{\"heading\":false,\"text\":\"Y se disipó en la niebla negra.\"},{\"heading\":false,\"text\":\"Yo soñé luego que me moría, y en el momento mismo en que soñaba dar el último respiro me desperté con cierta opresión en el pecho.\"},{\"heading\":false,\"text\":\"Y aquí está la historia de Augusto Pérez.\"},{\"heading\":false,\"text\":\"ORACIÓN FÚNEBRE\"},{\"heading\":false,\"text\":\"POR MODO DE EPÍLOGO\"},{\"heading\":false,\"text\":\"Suele ser costumbre al final de las novelas y luego que muere o se casa el héroe o protagonista dar noticia de la suerte que corrieron los demás personajes. No la vamos a seguir aquí ni a dar por consiguiente noticia alguna de cómo les fué a Eugenia y Mauricio, a Rosario, a Liduvina y Domingo, a don Fermín y doña Edelmira, a Víctor y su mujer y a todos los demás que en torno a Augusto se nos han presentado, ni vamos siquiera a decir lo que de la singular muerte de éste sintieron y pensaron. Sólo haremos una excepción y es en favor del que más honda y más sinceramente sintió la muerte de Augusto, que fué su perro, Orfeo.\"},{\"heading\":false,\"text\":\"Orfeo, en efecto, encontróse huérfano. Cuando saltando en la cama olió a su amo muerto, olió la muerte de su amo, envolvió a su espíritu perruno una densa nube negra. Tenía experiencia de otras muertes, había olido y visto perros y gatos muertos, había matado algún ratón, había olido muertes de hombres, pero a su amo le creía inmortal. Porque su amo era para él como un dios. Y al sentirle ahora muerto sintió que se desmoronaban en su espíritu los fundamentos todos de su fe en la vida y en el mundo, y una inmensa desolación llenó su pecho.\"},{\"heading\":false,\"text\":\"Y acurrucado a los pies de su amo muerto pensó así:\"},{\"heading\":false,\"text\":\"«¡Pobre amo mío! ¡pobre amo mío! ¡Se ha muerto; se me ha muerto! ¡Se muere todo, todo, todo; todo se me muere! Y es peor que se me muera todo a que me muera para todo yo. ¡Pobre amo mío! ¡pobre amo mío! Esto que aquí yace, blanco, frío, con olor a próxima podredumbre, a carne de ser comida, esto ya no es mi amo. No, no lo es. ¿Dónde se fué mi amo? ¿dónde el que me acariciaba, el que me hablaba?\"},{\"heading\":false,\"text\":\"»¡Qué extraño animal es el hombre! Nunca está en lo que tiene delante. Nos acaricia sin que sepamos por qué y no cuando le acariciamos más, y cuando más a él nos rendimos nos rechaza o nos castiga. No hay modo de saber lo que quiere, si es que lo sabe él mismo. Siempre parece estar en otra cosa que en lo que está y ni mira a lo que mira. Es como si hubiese otro mundo para él. Y es claro, si hay otro mundo, no hay éste.\"},{\"heading\":false,\"text\":\"»Y luego habla, o ladra de un modo complicado. Nosotros aullábamos y por imitarle aprendimos a ladrar, y ni aun así nos entendemos con él. Sólo le entendemos de veras cuando él también aúlla. Cuando el hombre aúlla o grita o amenaza le entendemos muy bien los demás animales. ¡Como que entonces no está distraído en otro mundo...! Pero ladra a su manera, habla, y eso le ha servido para inventar lo que no hay y no fijarse en lo que hay. En cuanto le ha puesto un nombre a algo, ya no ve este algo; no hace sino oir el nombre que le puso o verlo escrito. La lengua le sirve para mentir, inventar lo que no hay y confundirse. Y todo es en él pretextos para hablar con los demás o consigo mismo. ¡Y hasta nos ha contagiado a los perros!\"},{\"heading\":false,\"text\":\"»Es un animal enfermo, no cabe duda. ¡Siempre está enfermo! ¡Sólo parece gozar de alguna salud cuando duerme, y no siempre, porque a las veces hasta durmiendo habla! Y esto también nos ha contagiado. ¡Nos ha contagiado tantas cosas!\"},{\"heading\":false,\"text\":\"»¡Y luego nos insulta! Llama cinismo, esto es perrismo o perrería, a la imprudencia o sinvergüencería, él, el animal hipócrita por excelencia. El lenguaje le ha hecho hipócrita. Como que la hipocresía debería llamarse antropismo si es que a la impudencia se le llama cinismo. ¡Y ha querido hacernos hipócritas, es decir, cómicos, farsantes, a nosotros, a los perros! A los perros, que no fuimos sometidos y domesticados por el hombre como el toro o el caballo, a la fuerza, sino que nos unimos a él libremente, en pacto sinalagmático, para explotar la caza. Nosotros le descubríamos la pieza, él la cazaba y nos daba nuestra parte. Y así, en contrato social, nació nuestro consorcio.\"},{\"heading\":false,\"text\":\"»Y nos lo ha pagado prostituyéndonos e insultándonos. ¡Y queriendo hacernos farsantes, monos y perros sabios! ¡Perros sabios llaman a unos perros a los que les enseñan a representar farsas, para lo cual les visten y les adiestran a andar indecorosamente sobre las patas traseras, en pie! ¡Perros sabios! ¡A eso le llaman los hombres sabiduría, a representar farsas y a andar sobre dos pies!\"},{\"heading\":false,\"text\":\"»¡Y es claro, el perro que se pone en dos pies va enseñando impúdica, cínicamente, sus vergüenzas, de cara! Así hizo el hombre al ponerse de pie, al convertirse en un mamífero vertical, y sintió al punto vergüenza y la necesidad moral de taparse las vergüenzas que enseñaba. Y por eso dice su Biblia, según les he oído, que el primer hombre, es decir, el primero de ellos que se puso a andar en dos pies, sintió vergüenza de presentarse desnudo ante su Dios. Y para eso inventaron el vestido, para cubrirse el sexo. Pero como empezaron vistiéndose lo mismo ellos y ellas, no se distinguían entre sí, no se conocían siempre y bien el sexo, y de aquí mil atrocidades... humanas, que ellos se empeñan en llamar perrunas o cínicas. Ellos, los hombres, que son quienes nos han pervertido a los perros, quienes nos han hecho perrunos, cínicos, que es nuestra hipocresía. Porque el cinismo es en el perro hipocresía, así como en el hombre la hipocresía es cinismo. Nos hemos contagiado unos a otros.\"},{\"heading\":false,\"text\":\"»Se vistió el hombre, primero con el mismo traje ellos y ellas, mas como se confundían, tuvieron que inventar diferencia de trajes y llevar el sexo al vestido. Esos pantalones no son sino una consecuencia de haberse el hombre puesto en dos pies.\"},{\"heading\":false,\"text\":\"»¡Qué extraño animal es el hombre! ¡No está nunca en donde debe estar, que es a lo que está, y habla para mentir y se viste!\"},{\"heading\":false,\"text\":\"«¡Pobre amo! Dentro de poco le enterrarán en un sitio que para eso tienen destinado. ¡Los hombres guardan o almacenan sus muertos, sin dejar que perros o cuervos los devoren! Y que quede lo único que todo animal, empezando por el hombre, deja en el mundo: unos huesos. ¡Almacenan sus muertos! ¡Un animal que habla, que se viste y que almacena sus muertos! ¡Pobre hombre!\"},{\"heading\":false,\"text\":\"«¡Pobre amo mío! ¡pobre amo mío! ¡Fué un hombre, sí, no fué más que un hombre, fué sólo un hombre! ¡Pero fué mi amo! ¡Y cuánto, sin él creerlo ni pensarlo, me debía...! ¡cuánto! Cuánto le enseñé con mis silencios, con mis lametones, mientras él me hablaba, me hablaba, me hablaba. «¿Me entenderás?»—me decía. Y sí, yo le entendía, le entendía mientras él me hablaba hablándose y hablaba, hablaba, hablaba. Él, al hablarme así hablándose, hablaba al perro que había en él. Yo mantuve despierto su cinismo.\"},{\"heading\":false,\"text\":\"»¡Perra vida la que ha llevado, muy perra! ¡Y grandísima perrería, o mejor, grandísima hombrada la que le han hecho esos dos! ¡Hombrada la que Mauricio le ha hecho: mujerada la que le ha hecho Eugenia! ¡Pobre amo mío!\"},{\"heading\":false,\"text\":\"»Y ahora aquí, frío y blanco, inmóvil, vestido, sí, pero sin habla ni por fuera ni por dentro. Ya nada tienes que decir a tu Orfeo. Tampoco tiene ya nada que decirte Orfeo con su silencio.\"},{\"heading\":false,\"text\":\"»¡Pobre amo mío! ¿Qué será ahora de él? ¿Dónde estará aquello que en él hablaba y soñaba? Tal vez allá arriba, en el mundo puro, en la alta meseta de la tierra, en la tierra pura toda ella de colores puros, como la vio Platón, al que los hombres llaman divino; en aquella sobrehaz terrestre de que caen las piedras preciosas, donde están los hombres puros y los purificados bebiendo aire y respirando éter. Allí están también los perros puros, los de San Humberto el cazador, el de Santo Domingo de Guzmán con su antorcha en la boca, el de San Roque, de quien decía un predicador señalando a su imagen: ¡Ahí le tenéis a San Roque, con su perrito y todo! Allí, en el mundo puro platónico, en el de las ideas encarnadas, está el perro puro, el perro de veras cínico. ¡Y allí está mi amo!\"},{\"heading\":false,\"text\":\"»Siento que mi espíritu se purifica al contacto de esta muerte, de esta purificación de mi amo, y que aspira hacia la niebla en que él al fin se deshizo, a la niebla de que brotó y a que revertió. Orfeo siente venir la niebla tenebrosa... Y va hacia su amo saltando y agitando el rabo. ¡Amo mío! ¡Amo mío! ¡Pobre hombre!»\"},{\"heading\":false,\"text\":\"Domingo y Liduvina recojieron luego al pobre perro muerto a los pies de su amo, depurado como éste y como él envuelto en la nube tenebrosa. Y el pobre Domingo al ver aquello se enterneció y lloró, no se sabe bien si por la muerte de su amo o por la del perro, aunque lo más creíble es que lloró al ver aquel maravilloso ejemplo de lealtad y fidelidad. Y dijo:\"},{\"heading\":false,\"text\":\"—¡Y luego dirán que no matan las penas!\"},{\"heading\":false,\"text\":\"ÍNDICE\"},{\"heading\":false,\"text\":\"PRÓLOGO 6 POST-PRÓLOGO 19 I 21 II 29 III 37 IV 41 V 49 VI 61 VII 69 VIII 73 IX 83 X 87 XI 97 XII 107 XIII 115 XIV 123 XV 135 XVI 143 XVII 149 XVIII 161 XIX 169 XX 181 XXI 193 XXII 203 XXIII 209 XXIV 225 XXV 235 XXVI 241 XXVII 247 XXVIII 253 XXIX 259 XXX 267 XXXI 277 XXXII 291 XXXIII 303 EPÍLOGO 307\"}]}]', 'es', 'https://www.gutenberg.org/ebooks/49836', '{}');
INSERT INTO libros (id, titulo, autor, genero, cover, secciones, idioma, fuente, introducciones) VALUES (52597, 'Insolación y Morriña', 'Emilia Pardo Bazán', 'romance', 'https://www.gutenberg.org/cache/epub/52597/pg52597.cover.medium.jpg', '[{\"title\":\"Insolación — capítulo I\",\"blocks\":[{\"heading\":false,\"text\":\"La primer señal por donde Asís Taboada se hizo cargo de que había salido de los limbos del sueño, fué un dolor como si la barrenasen las sienes de parte á parte con un barreno finísimo; luego le pareció que las raíces del pelo se convertían en millares de puntas de aguja y se le clavaban en el cráneo. También notó que la boca estaba pegajosita, amarga y seca; la lengua, hecha un pedazo de esparto; las mejillas ardían; latían desaforadamente las arterias, y el cuerpo declaraba á gritos que, si era ya hora muy razonable de saltar de la cama, no estaba él para valentías tales.\"},{\"heading\":false,\"text\":\"Suspiró la señora; dió una vuelta, convenciéndose de que tenía molidísimos los huesos; alcanzó el cordón de la campanilla, y tiró con garbo. Entró la doncella, pisando quedo, y entreabrió las maderas del cuarto-tocador. Una flecha de luz se coló en la alcoba, y Asís exclamó con voz ronca y debilitada:\"},{\"heading\":false,\"text\":\"--Menos abierto... Muy poco... Así.\"},{\"heading\":false,\"text\":\"--¿Cómo le va, señorita?--preguntó muy solícita la Angela (por mal nombre _Diabla_).--¿Se encuentra algo más aliviada ahora?\"},{\"heading\":false,\"text\":\"--Sí, hija..., pero se me abre la cabeza en dos.\"},{\"heading\":false,\"text\":\"--¡Ay! ¿Tenemos la maldita de la jaquecona?\"},{\"heading\":false,\"text\":\"--Clavada... A ver si me traes una taza de tila...\"},{\"heading\":false,\"text\":\"--¿Muy cargada, señorita?\"},{\"heading\":false,\"text\":\"--Regular...\"},{\"heading\":false,\"text\":\"--Voy volando.\"},{\"heading\":false,\"text\":\"Un cuarto de hora duró el vuelo de la Diabla. Su ama, vuelta de cara á la pared, subía las sábanas hasta cubrirse la cara con ellas, sin más objeto que sentir el fresco de la batista en aquellas mejillas y frente que estaban echando lumbre.\"},{\"heading\":false,\"text\":\"De tiempo en tiempo exhalaba un gemido sordo.\"},{\"heading\":false,\"text\":\"En la mollera suya funcionaba, de seguro, toda la maquinaria de la Casa de la Moneda, pues no recordaba aturdimiento como el presente, sino el que había experimentado al visitar la fábrica de dinero y salir medio loca de las salas de acuñación.\"},{\"heading\":false,\"text\":\"Entonces, lo mismo que ahora, se le figuraba que una legión de enemigos se divertía en pegarla tenazazos en los sesos y devanarla con argadillos candentes la masa encefálica.\"},{\"heading\":false,\"text\":\"Además, notaba cierta trepidación allá dentro, igual que si la cama fuese una hamaca, y á cada balance se le amontonase el estómago y le metiesen en prensa el corazón.\"},{\"heading\":false,\"text\":\"La tila. Calentita, muy bien hecha. Asís se incorporó, sujetando la cabeza y apretándose las sienes con los dedos. Al acercar la cucharilla á los labios, náuseas reales y efectivas.\"},{\"heading\":false,\"text\":\"--Hija... está hirviendo... Abrasa. ¡Ay! Sosténme un poco, por los hombros. ¡Así!\"},{\"heading\":false,\"text\":\"Era la Diabla una chica despabilada, lista como una pimienta: una luguesa que no le cedía el paso á la andaluza más ladina. Miró á su ama guiñando un poco los ojos, y dijo compungidísima al parecer:\"},{\"heading\":false,\"text\":\"--Señorita... Vaya por Dios. ¿Se encuentra peor? Lo que tiene no es sino eso que le dicen allá en nuestra tierra un _soleado_... Ayer se caían los pájaros de calor, y V. fuera todo el santo día...\"},{\"heading\":false,\"text\":\"--Eso será...,--afirmó la dama.\"},{\"heading\":false,\"text\":\"--¿Quiere que vaya enseguidita á avisar al señor de Sánchez del Abrojo?\"},{\"heading\":false,\"text\":\"--No seas tonta... No es cosa para andar fastidiando al médico. Un meneo á la taza. Múdala á ese vaso...\"},{\"heading\":false,\"text\":\"Con un par de trasegaduras de vaso á taza y viceversa, quedó potable la tila. Asís se la embocó, y al punto se volvió hacia la pared.\"},{\"heading\":false,\"text\":\"--Quiero dormir... No almuerzo... Almorzad vosotros... Si vienen visitas, que he salido... Atenderás por si llamo.\"},{\"heading\":false,\"text\":\"Hablaba la dama sorda y opacamente, de mal talante, como aquel que no está para bromas y tiene igualmente desazonados el cuerpo y el espíritu.\"},{\"heading\":false,\"text\":\"Se retiró por fin la doncella, y al verse sola, Asís suspiró más profundo y alzó otra vez las sábanas, quedándose acurrucada en una concha de tela. Se arregló los pliegues del camisón, procurando que la cubriese hasta los piés; echó atrás la madeja del pelo revuelto, empapado en sudor y áspero de polvo, y luego permaneció quietecita, con síntomas de alivio y aun de bienestar físico producido por la infusión calmante.\"},{\"heading\":false,\"text\":\"La jaqueca, que ya se sabe cómo es de caprichosa y maniática, se había marchado por la posta desde que llegara al estómago la taza de tila; la calentura cedía, y las bascas iban aplacándose... Sí, lo que es el cuerpo se encontraba mejor, infinitamente mejor; pero, ¿y el alma? ¿Qué procesión le andaba por dentro á la señora?\"},{\"heading\":false,\"text\":\"No cabe duda: si hay una hora del día en que la conciencia goza todos sus fueros, es la del despertar. Se distingue muy bien de colores después del descanso nocturno y el paréntesis del sueño. Ambiciones y deseos, afectos y rencores se han desvanecido entre una especie de niebla; faltan las excitaciones de la vida exterior; y así como después de un largo viaje parece que la ciudad de donde salimos hace tiempo no existe realmente, al despertar suele figurársenos que las fiebres y cuidados de la víspera se han ido en humo y ya no volverán á acosarnos nunca. Es la cama una especie de celda donde se medita y hace examen de conciencia, tanto mejor cuanto que se está muy á gusto, y ni la luz ni el ruido distraen. Grandes dolores de corazón y propósitos de la enmienda suelen quedarse entre las mantas.\"},{\"heading\":false,\"text\":\"Unas miajas de todo esto sentía la señora; sólo que á sus demás impresiones sobrepujaba la del asombro.--«¿Pero es de veras? ¿Pero me ha pasado _eso_? Señor Dios de los ejércitos, ¿lo he soñado ó no? Sácame de esta duda.»--Y aunque Dios no se tomaba el trabajo de responder negando ó afirmando, _aquello_ que reside en algún rincón de nuestro ser moral y nos habla tan categóricamente como pudiera hacerlo una voz divina, contestaba:--«Grandísima hipócrita, bien sabes tú como fué: no me preguntes, que te diré algo que te escueza.»\"},{\"heading\":false,\"text\":\"--Tiene razón la Diabla: ayer atrapé un _soleado_ y para mí, el sol... matarme. ¡Este chicharrero de Madrid! ¡El veranito y su alma! Bien empleado, por meterme en avisperos. A estas horas debía yo andar por mi tierra...\"},{\"heading\":false,\"text\":\"Doña Francisca Taboada se quedó un poquitín más tranquila desde que pudo echarle la culpa al sol. A buen seguro que el astro-rey dijese esta boca es mía protestando, pues aunque está menos acostumbrado á las acusaciones de galeotismo que la luna, es de presumir que las acoja con igual impasibilidad é indiferencia.\"},{\"heading\":false,\"text\":\"--De todos modos--arguyó la voz inflexible,--confiesa, Asís, que si no hubieses tomado más que sol... Vamos, á mí no me vengas tú con historias, que ya sabes que nos conocemos... ¡como que andamos juntos hace la friolera de treinta y dos abriles! Nada, aquí no valen subterfugios... Y tampoco sirve alegar que si fué inesperado, que si parece mentira, que si patatín, que si patatán... Hija de mi corazón, lo que no sucede en un año sucede en un día. No hay que darle vueltas. Tú has sido hasta la presente una señora intachable; bien; una perfecta viuda; conformes; te has llevado en peso tus dos añitos de luto (cosa tanto más meritoria cuanto que, seamos francos, últimamente ya necesitabas alguna virtud para querer á tu tío, esposo y señor natural, el insigne marqués de Andrade, con sus bigotes pintados y sus achaques, fístulas ó lo que fuesen); á pesar de tu genio animado y tu afición á las diversiones, en veinticuatro meses no se te ha visto el pelo sino en la iglesia ó en casa de tus amigas íntimas; convenido; has consagrado largas horas al cuidado de tu niña y eres madre cariñosa; nadie lo niega; te has propuesto siempre portarte como una señora, disfrutar de tu posición y tu independencia, no meterte en líos ni hacer contrabando; lo reconozco; pero... ¿qué quieres, mujer? te descuidaste un minuto, incurriste en una chiquillada (porque fué una chiquillada, pero chiquillada del género atroz, convéncete de ello) y por cuanto viene el demonio y la enreda y te encuentras de patitas en la gran trapisonda... No andemos con sol por aquí y calor por allá. Disculpas de mal pagador. Te falta hasta la excusa vulgar, la del cariñito y la pasioncilla... Nada, chica, nada. Un pecado gordo en frío, sin circunstancias atenuantes y con ribetes de desliz chabacano. ¡Te luciste!\"},{\"heading\":false,\"text\":\"Ante estos argumentos irrefutables cedía la acción bienhechora de la tila, y Asís iba experimentando otra vez terrible desasosiego y sofoco. El barreno que antes le taladraba la sien, se había vuelto sacacorchos, y haciendo hincapié en el occipucio, parecía que enganchaba los sesos á fin de arrancarlos igual que el tapón de una botella. Ardía la cama y también el cuerpo de la culpable, que, como un San Lorenzo en sus parrillas, daba vueltas y más vueltas en busca de rincones frescos, al borde del colchón. Convencida de que todo abrasaba igualmente, Asís brincó de la cama abajo, y blanca y silenciosa como un fantasma entre la penumbra de la alcoba, se dirigió al lavabo, torció el grifo del depósito, y con las yemas de los dedos empapadas en agua, se humedeció frente, mejillas y nariz; luego se refrescó la boca, y por último se bañó los párpados largamente, con fruición; hecho lo cual, creyó sentir que se le despejaban las ideas y que la punta del barreno se retiraba poquito á poco de los sesos. ¡Ay, qué alivio tan rico! A la cama, á la cama otra vez, á cerrar los ojos, estarse quietecita y callada y sin pensar en cosa ninguna...\"},{\"heading\":false,\"text\":\"Sí, á buena parte. ¿No pensar dijiste? Cuanto más se aquietaban los zumbidos y los latidos, y la jaqueca y la calentura, más nítidos y agudos eran los recuerdos, más activas y endiabladas las cavilaciones.\"},{\"heading\":false,\"text\":\"--Si yo pudiese rezar--discurrió Asís.--No hay para esto de conciliar el sueño como repetir una misma oración de carretilla.\"},{\"heading\":false,\"text\":\"Intentólo en efecto; mas si por un lado era soporífera la operación, por otro agravaba las inquietudes y resquemores íntimos de la señora. Bonito se pondría el Padre Urdax cuando tocasen á confesarse de aquella cosa inaudita y estupenda. ¡Él, que tanto se atufaba por menudencias de escotes, infracciones de ayuno, asistencia á saraos en cuaresma, mermas de misa y otros pecadillos que trae consigo la vida mundana en la corte! ¿Qué circunloquios serían más adecuados para atenuar la primer impresión de espanto y la primer filípica? Sí, sí ¡circunloquios al Padre Urdax! ¡Él, que lo preguntaba todo derecho y claro, sin pararse en vergüenzas ni en reticencias! ¡Con aquel geniazo de pólvora y aquella manga estrechita que gastaba! Si al menos permitiese explicar la cosa desde un principio, bien explicada, con todas las aclaraciones y notas precisas para que se viese la fatalidad, la serie de circunstancias que... Pero, ¿quién se atreve á hacer mérito de ciertas disculpas ante un jesuíta tan duro de pelar y tan largo de entendederas? Esos señores quieren que todo sea virtud á raja tabla, y no entienden de componendas ni de excusas. Antes parece que se les tachaba de tolerantísimos: no, pues lo que es ahora...\"},{\"heading\":false,\"text\":\"No obstante el triste convencimiento de que con el Padre Urdax sería perder tiempo y derrochar saliva todo lo que no fuese decir _acúsome_, _acúsome_, Asís, en la penumbra del dormitorio, entre el silencio, componía mentalmente el relato que sigue, donde claro está que no había de colocarse en el peor lugar, sino paliar el caso: aunque, señores, ello admitía bien pocos paliativos.\"}]},{\"title\":\"Insolación — capítulo II\",\"blocks\":[{\"heading\":false,\"text\":\"Hay que tomarlo desde algo atrás y contar lo que pasó, ó por mejor decir, lo que se charló anteayer en la tertulia semanal de la duquesa de Sahagún, á la cual soy asidua concurrente. También la frecuenta mi paisano el comandante de artillería Don Gabriel Pardo de la Lage, cumplido caballero, aunque un poquillo inocentón, y sobre todo muy estrafalario y bastante pernicioso en sus ideas, que á veces sostiene con gran calor y terquedad, si bien las más noches le da por acoquinarse y callar ó jugar al tresillo, sin importársele de lo que pasa en nuestro corro. No obstante, desde que yo soy obligada todos los miércoles, notan que Don Gabriel se acerca más al círculo de las señoras y gusta de armar pendencia conmigo y con la dueña de la casa; por lo cual hay quien asegura que no le parezco saco de paja á mi paisano, aun cuando otros afirman que está enamorado de una prima ó sobrina suya, acerca de quien se refieren no sé que historias raras. En fin, el caso es que disputando y peleándonos siempre, no hacemos malas migas el comandante y yo. ¡Qué malas migas! A cada polémica que armamos, parece aumentar nuestra simpatía, como si sus mismas genialidades morales (no sé darles otro nombre) me fuesen cayendo en gracia y pareciéndome indicio de cierta bondad interior... Ello va mal expresado..., pero yo me entiendo.\"},{\"heading\":false,\"text\":\"Pues anteayer (para venir al asunto) estuvo el comandante desde los primeros momentos muy decidor y muy alborotado, haciéndonos reir con sus manías. Le sopló la ventolera de sostener una vulgaridad: que España es un país tan salvaje como el Africa central, que todos tenemos sangre africana, beduina, árabe ó qué sé yo, y que todas esas músicas de ferrocarriles, telégrafos, fábricas, escuelas, ateneos, libertad política y periódicos, son en nosotros postizas y como pegadas con goma, por lo cual están siempre despegándose, mientras lo verdaderamente nacional y genuino, la barbarie subsiste, prometiendo durar por los siglos de los siglos. Sobre esto se levantó el caramillo que es de suponer. Lo primero que le repliqué fué compararlo á los franceses, que creen que sólo servimos para bailar el bolero y repicar las castañuelas; y añadí que la gente bien educada era igual, idéntica, en todos los países del mundo.\"},{\"heading\":false,\"text\":\"--Pues mire V., eso empiezo por negarlo--saltó Pardo con grandísima fogosidad.--De los Pirineos acá, todos, sin excepción, somos salvajes, lo mismo las personas finas que los tíos; lo que pasa es que nosotros lo disimulamos un poquillo más, por vergüenza, por convención social, por conveniencia propia; pero que nos pongan el plano inclinado, y ya resbalaremos. El primer rayito de sol de España--este sol con que tanto nos muelen los extranjeros y que casi nunca está en casa, porque aquí llueve lo propio que en París, que ese es el chiste...\"},{\"heading\":false,\"text\":\"Le interrumpí:\"},{\"heading\":false,\"text\":\"--Hombre, sólo falta que también niegue V. el sol.\"},{\"heading\":false,\"text\":\"--No lo niego, ¡qué he de negarlo! Por lo mismo que suele embozarse bien en invierno, de miedo á las pulmonías, en verano lo tienen Vds. convirtiendo á Madrid en sartén ó caldera infernal, donde nos achicharramos todos... Y claro, no bien asoma, produce una fiebre y una excitación endiabladas... Se nos sube á la cabeza, y entonces es cuando se nivelan las clases ante la ordinariez y la ferocidad general.\"},{\"heading\":false,\"text\":\"--Vamos, ya pareció aquello. V. lo dice por las corridas de toros.\"},{\"heading\":false,\"text\":\"En efecto, á Pardo le da muy fuerte eso de las corridas. Es uno de sus principales y frecuentes asuntos de sermón. En tomando la ampolleta sobre los toros, hay que oirle poner como digan dueñas á los partidarios de tal espectáculo, que él considera tan pecaminoso como el Padre Urdax, los bailes de Piñata y las representaciones del _Demi-monde_ y _Divorciémonos_. Sale á relucir aquello de las tres fieras, toro, torero y público; la primera, que se deja matar porque no tiene más remedio; la segunda, que cobra por matar; la tercera, que paga para que maten, de modo que viene á resultar la más feroz de las tres; y también aquello de la suerte de pica, y de las tripas colgando, y de las excomuniones del Papa contra los católicos que asisten á corridas, y de los perjuicios á la agricultura... Lo que es la cuenta de perjuicios la saca de un modo imponente. Hasta viene á resultar que por culpa de los toros hay déficit en la Hacienda y hemos tenido las dos guerras civiles... (Verdad que esto lo soltó en un instante de acaloramiento, y como vió la greguería y la chacota que armamos, medio se desdijo.) Por todo lo cual, yo pensé que al nombrar ferocidad y barbarie vendrían los toros detrás. No era eso. Pardo contestó:\"},{\"heading\":false,\"text\":\"--Dejemos á un lado los toros, aunque bien revelan el influjo barbarizante ó barbarizador (como Vds. gusten) del sol, ya que es axiomático que sin sol no hay corrida _buena_. Pero prescindamos de ellos; no quiero que digan Vds. que ya es manía en mí la de sacar á relucir la gente cornúpeta. Tomemos cualquier otra manifestación bien genuina de la vida nacional... algo muy español y muy característico... ¿No estamos en tiempo de ferias? ¿No es mañana San Isidro Labrador? ¿No va la gente estos días á solazarse por la pradera y el cerro?\"},{\"heading\":false,\"text\":\"--Bueno; ¿y qué? ¿También criticará V. las ferias y el Santo? Este señor no perdona ni á la corte celestial.\"},{\"heading\":false,\"text\":\"--Bonito está el Santo, y valiente saturnal asquerosa la que sus devotos le ofrecen. Si San Isidro la ve, él que era un honrado y pacífico agricultor, convierte en piedras los garbanzos tostados y desde el cielo descalabra á sus admiradores. Aquello es un aquelarre, una zahurda de Plutón. Los instintos españoles más típicos corren allí desbocados, luciendo su belleza. Borracheras, pendencias, navajazos, gula, libertinaje grosero, blasfemias, robos, desacatos y bestialidades de toda calaña... Gracioso _tableau_, señoras mías... Eso es el pueblo español cuando le dan suelta. Lo mismito que los potros al salir á la dehesa, que su felicidad consiste en hartarse de relinchos y coces.\"},{\"heading\":false,\"text\":\"--Si me habla V. de la gente ordinaria...\"},{\"heading\":false,\"text\":\"--No, es que insisto: todos iguales en siendo españoles; el instinto vive allá en el fondo del alma; el problema es de ocasión y lugar, de poder ó no sacudir ciertos miramientos que la educación impone: cosa externa, cáscara y nada más.\"},{\"heading\":false,\"text\":\"--¡Qué teorías, Dios misericordioso! ¿Ni siquiera admite V. excepciones á favor de las señoras? ¿Somos salvajes también?\"},{\"heading\":false,\"text\":\"--También, y acaso más que los hombres, que al fin Vds. se educan menos y peor... No se dé V. por resentida, amiga Asís. Concederé que V. sea la menor cantidad de salvaje posible, porque al fin nuestra tierra es la porción más apacible y sensata de España.\"},{\"heading\":false,\"text\":\"Aquí la Duquesa volvió la cabeza con sobresalto. Desde el principio de la disputa estaba entretenida dando conversación á un tertuliano nuevo, muchacho andaluz, de buena presencia, hijo de un antiguo amigo del Duque, el cual, según me dijeron, era un rico hacendado residente en Cádiz. La Duquesa no admite presentados, y sólo por circunstancias así pueden encontrarse caras desconocidas en su tertulia. En cambio, á las relaciones ya antiguas las agasaja muchísimo, y es tan consecuente y cariñosa en el trato, que todos se hacen lenguas alabando su perseverancia; virtud que, según he notado, abunda en la corte más de lo que se cree. Advertía yo que, sin dejar de atender al forastero, la Duquesa aplicaba el oído á nuestra disputa y rabiaba por mezclarse en ella; la proporción le vino rodada para hacerlo, metiendo en danza al gaditano.\"},{\"heading\":false,\"text\":\"--Muchas gracias, señor de Pardo, por la parte que nos toca á los andaluces. Estos galleguitos siempre arriman el ascua á su sardina. ¡Más aprovechados son! De salvajes nos ha puesto, así como quien no quiere la cosa.\"},{\"heading\":false,\"text\":\"--¡Oh Duquesa, Duquesa, Duquesa!--respondió Pardo con mucha guasa.--¡Darse por aludida V., V. que es una señora tan inteligente, protectora de las bellas artes! ¡Usted que entiende de pucheros mudéjares y barreñones asirios! ¡Usted que posee colecciones mineralógicas que dejan con la boca abierta al embajador de Alemania! ¡Usted, señora, que sabe lo que significa _fósil_! ¡Pues si hasta miedo le han cobrado á V. ciertos pedantes que yo conozco!\"},{\"heading\":false,\"text\":\"--Haga V. el favor de no quedarse conmigo suavemente. No parece sino que soy alguna literata ó alguna marisabidilla... Porque le guste á uno un cuadro ó una porcelana... Si cree V. que así vamos á correr un velo sobre aquello del salvajismo... ¿Qué opina V. de eso, Pacheco? Según este caballero, que ha nacido en Galicia, es salvaje toda España y más los andaluces. Asís, el señor Don Diego Pacheco... Pacheco, la señora Marquesa viuda de Andrade... el señor Don Gabriel Pardo...\"},{\"heading\":false,\"text\":\"El gaditano, sin pronunciar palabra, se levantó y vino á apretarme la mano haciendo una cortesía; yo murmuré entre dientes eso que se murmura en casos análogos. Llena la fórmula, nos miramos con la curiosidad fría del primer momento, sin fijarnos en detalles. Pacheco, que llevaba con soltura el frac, me pareció distinguido, y aunque andaluz, le encontré más bien trazas inglesas: se me figuró serio y no muy locuaz ni disputador. Haciéndose cargo de la indicación de la Duquesa, dijo con acento cerrado y frase perezosa:\"},{\"heading\":false,\"text\":\"--A cada país le cae bien lo suyo... Nuestra tierra no ha dado pruebas de ser nada ruda; tenemos allá de too; poetas, pintores, escritores... Cabalmente en Andalucía la gente pobre es mu fina y mu despabilaa. Protesto contra lo que se refiere á las señoras. Este cabayero convendrá en que toítas son unos ángeles del cielo.\"},{\"heading\":false,\"text\":\"--Si me llama V. al terreno de la galantería--respondió Pardo--convendré en lo que V. guste... Sólo que esas generalidades no prueban nada. En las unidades nacionales no veo hombres ni mujeres; veo una raza, que se determina históricamente en esta ó en aquella dirección...\"},{\"heading\":false,\"text\":\"--¡Ay, Pardo!--suplicó la Duquesa con mucha gracia.--Nada de palabras retorcidas, ni de filosofías intrincadas. Hable V. clarito y en cristiano. Mire V. que no hemos llegado á sabios, y que nos vamos á quedar en ayunas.\"},{\"heading\":false,\"text\":\"--Bueno; pues hablando en cristiano, digo que ellos y ellas son de la misma pasta, porque no hay más remedio, y que en España (allá va, Vds. se empeñan en que ponga los puntos sobre las _íes_) también las señoras pagan tributo á la barbarie--lo cual puede no advertirse á primera vista porque su sexo las obliga á adoptar formas menos toscas, y las condena al papel de ángeles, como las ha llamado este caballero.--Aquí está nuestra amiga Asís, que á pesar de haber nacido en el Noroeste, donde las mujeres son reposadas, dulces y cariñosas, sería capaz, al darle un rayo de sol en la mollera, de las mismas atrocidades que cualquier hija del barrio de Triana ó del Avapiés...\"},{\"heading\":false,\"text\":\"--¡Ay, paisano! Ya digo que está V. tocado, incurable. Con el sol tiene la tema. ¿Qué le hizo á V. el sol, para que así lo traiga al retortero?\"},{\"heading\":false,\"text\":\"--Serán aprensiones, pero yo creo que lo llevamos disuelto en la sangre y que á lo mejor nos trastorna.\"},{\"heading\":false,\"text\":\"--No lo dirá V. por nuestra tierra. Allá no le vemos la cara sino unos cuantos días del año.\"},{\"heading\":false,\"text\":\"--Pues no lo achaquemos al sol; será el aire ibérico; el caso es que los gallegos, en ese punto, sólo aparentemente nos distinguimos del resto de la Península. ¿Ha visto V. qué bien nos acostumbramos á las corridas de toros? En Marineda ya se llena la plaza y se calientan los cascos igual que en Sevilla ó Córdoba. Los cafés flamencos hacen furor; las cantaoras traen revuelto al sexo masculino; se han comprado cientos de navajas, y lo peor es que se hace uso de ellas; hasta los chicos de la calle se han aprendido de memoria el tecnicismo taurómaco; la manzanilla corre á mares en los tabernáculos marinedinos; hay sus cañitas y todo; una parodia ridícula, corriente; pero parodia que sería imposible donde no hubiese materia dispuesta para semejantes aficiones. Convénzanse Vds.: aquí en España, desde la Restauración, maldito si hacemos otra cosa más que jalearnos á nosotros mismos. Empezó la broma por todas aquellas demostraciones contra Don Amadeo; lo de las peinetas y mantillas, los trajecitos á medio paso y los caireles; siguió con las barbianerías del difunto rey, que le había dado por lo chulo, y claro, la gente elegante le imitó, y ahora es ya una epidemia, y entre patriotismo y flamenquería, guitarreo y cante jondo, panderetas con madroños colorados y amarillos, y abanicos con las hazañas y los retratos de Frascuelo y Mazzantini, hemos hecho una Españita bufa, de tapiz de Goya ó sainete de Don Ramón de la Cruz. Nada, es moda y á seguirla. Aquí tiene V. á nuestra amiga la Duquesa, con su cultura y su finura, y sus mil dotes de dama; ¿pues no se pone tan contenta cuando la dicen que es la chula más salada de Madrid?\"},{\"heading\":false,\"text\":\"--Hombre, si fuese verdad, ¡ya se ve que me pondría!--exclamó la Duquesa con la viveza donosa que la distingue.--¡A mucha honra! Más vale una chula que treinta gringas. Lo gringo me apesta. Soy yo muy españolaza, ¿se entera V.? Se me figura que más vale ser como Dios nos hizo, que no que andemos imitando todo lo de extranjis... Estas manías de vivir á la inglesa, á la francesa... ¿Habrá ridiculez mayor? De Francia los perifollos; bueno; no ha de salir uno por ahí espantando á la gente, vestido como en el año de la nanita... De Inglaterra los asados... y se acabó. Y diga V., muy señor mío de mi mayor aprecio, ¿cómo es eso de que somos salvajes los españoles y no lo es el resto del género humano? En primer lugar, ¿se puede saber á qué llama V. salvajadas? En segundo, ¿qué hace nuestro pueblo, pobre infeliz, que no hagan también los demás de Europa? Conteste.\"},{\"heading\":false,\"text\":\"--¡Ay!... ¡si me aplasta V.!... ¡si ya no sé por donde ando! _Pietá_, _Signor._ Vamos, Duquesa, insisto en el ejemplo de antes: ¿ha visto V. la romería de San Isidro?\"},{\"heading\":false,\"text\":\"--Vaya si la he visto. Por cierto que es de lo más entretenido y pintoresco. Tipos se encuentran allí, que... Tipos de oro. ¿Y los columpios? ¿Y los tíos vivos? ¿Y aquella animación, aquel hormigueo de la gente? Le digo á V. que, para mí, hay poco tan salado como esas fiestas populares. ¿Que abundan borracheras y broncas? Pues eso pasa aquí y en Flandes: ¿ó se ha creído V. que allá, por la _Ingalaterra_, la gente no se pone nunca á medios pelos, ni se arma quimera, ni se hace barbaridad ninguna?\"},{\"heading\":false,\"text\":\"--Señora...--exclamó Pardo desalentado--V. es para mi un enigma. Gustos tan refinados en ciertas cosas, y tal indulgencia para lo brutal y lo feroz en otras, no me lo explico sino considerando que con un corazón y un ingenio de primera, pertenece V. á una generación bizantina y decadente, que ha perdido los ideales... Y no digo más, porque se reirá V. de mí.\"},{\"heading\":false,\"text\":\"--Es muy saludable ese temor; así no me hablará V. de cosazas filosóficas que yo no entiendo--respondió la Duquesa soltando una de sus carcajadas argentinas, aunque reprimidas siempre.--No haga V. caso de este hombre, Marquesa--murmuró volviéndose á mí.--Si se guía V. por él, la convertirá en una cuákera. Vaya V. al Santo, y verá cómo tengo razón y aquello es muy original y muy famoso. Este señor ha descubierto que sólo se achispan los españoles: lo que es los ingleses, ¡angelitos de mi vida! ¡qué habían de ajumarse nunca!\"},{\"heading\":false,\"text\":\"--Señora--replicó el comandante riendo, pero sofocado ya--los ingleses se achispan; conformes: pero se achispan con _sherry_, con cerveza ó con esos alcoholes endiablados que ellos usan; no como nosotros, con el aire, el agua, el ruido, la música y la luz del cielo; ellos se volverán unos cepos así que trincan, pero nosotros nos volvemos fieras; nos entra en el cuerpo un espíritu maligno de bravata y fanfarronería, y por gusto nos ponemos á cometer las mayores ordinarieces, empeñándonos en imitar al populacho. Y esto lo mismo las damas que los caballeros, si á mano viene, como dicen en mi país. Transijamos con todo, excepto con la ordinariez, Duquesa.\"},{\"heading\":false,\"text\":\"--Hasta la presente--declaró con gentil confusión la dama--no hemos salido ni la marquesa de Andrade ni yo á trastear ningún novillo.\"},{\"heading\":false,\"text\":\"--Pues todo se andará, señoras mías, si les dan paño--respondió el comandante.\"},{\"heading\":false,\"text\":\"--A este señor le arañamos nosotras--afirmó la Duquesa fingiendo con chiste un enfado descomunal.\"},{\"heading\":false,\"text\":\"--¿Y el Sr. Pacheco, que no nos ayuda?--murmuré volviéndome hacia el silencioso gaditano. Este tenía los ojos fijos en mí, y sin apartarlos, disculpó su neutralidad declarando que ya nos defendíamos muy bien y maldita la falta que nos hacían auxilios ajenos: al poco rato miró el reloj, se levantó, despidióse con igual laconismo, y fuése. Su marcha varió por completo el giro de la conversación. Se habló de él, claro está: la Sahagún refirió que lo había tenido á su mesa, por ser hijo de persona á quien estimaba mucho, y añadió que ahí donde lo veíamos, hecho un moro por la indolencia y un inglés por la sosería, no era sino un calaverón de tomo y lomo, decente y caballero, sí, pero aventurero y gracioso como nadie, muy gastador y muy tronera, de quien su padre no podía hacer bueno, ni traerle al camino de la formalidad y del sentido práctico, pues lo único para que hasta la fecha servía era para trastornar la cabeza á las mujeres. Y entonces el comandante (he notado que á todos los hombres les molesta un poquillo que delante de ellos se diga de otros que nos trastornan la cabeza) murmuró como hablando consigo mismo:\"},{\"heading\":false,\"text\":\"--Buen ejemplar de raza española.\"}]},{\"title\":\"Insolación — capítulo III\",\"blocks\":[{\"heading\":false,\"text\":\"Bien sabe Dios que cuando al siguiente día, de mañana, salí á oir misa á San Pascual, por ser la festividad del Patrón de Madrid, iba yo con mi eucologio y mi mantillita hecha una santa, sin pensar en nada inesperado y novelesco, y á quien me profetizase lo que sucedió después, creo que le llevo á los tribunales por embustero é insolente. Antes de entrar en la iglesia, como era temprano, me deslicé á dar un borde por la calle de Alcalá, y recuerdo que, pasando frente al Suizo, dos ó tres de esos chulos de pantalón estrecho y chaquetilla corta que se están siempre plantados allí en la acera, me echaron una sarta de requiebros de lo más desatinado; verbigracia:--Ole, ¡viva la purificación de la canela! Uyuyuy, ¡vaya unos ojos que se trae V., hermosa! Soniche, ¡viva hasta el cura que bautiza á estas hembras con mansanilla é lo fino!--Trabajo me costó contener la risa al entreoir estos disparates; pero logré mantenerme seria y apreté el paso á fin de perder de vista á los ociosos.\"},{\"heading\":false,\"text\":\"Cerca de la Cibeles me fijé en la hermosura del día. Nunca he visto aire más ligero, ni cielo más claro; la flor de las acacias del paseo de Recoletos olía á gloria, y los árboles parecía que estrenaban vestido nuevo de tafetán verde. Ganas me entraron de correr y brincar como á los quince, y hasta se me figuraba que en mis tiempos de chiquilla no había sentido nunca tal exceso de vitalidad, tales impulsos de hacer extravagancias, de arrancar ramas de árbol y de chapuzarme en el pilón presidido por aquella buena señora de los leones... Nada menos que estas tonterías me estaba pidiendo el cuerpo á mí.\"},{\"heading\":false,\"text\":\"Seguí bajando hacia las Pascualas, con la devoción de la misa medio evaporada y distraído el espíritu. Poco distaba ya de la iglesia, cuando distinguí á un caballero, que parado al pié de corpulento plátano, arrojaba á los jardines un puro enterito, y se dirigía luego á saludarme. Y oí una voz simpática y ceceosa, que me decía:\"},{\"heading\":false,\"text\":\"--A los piés... ¿A dónde bueno tan de mañana y tan sola?\"},{\"heading\":false,\"text\":\"--Calle... Pacheco... ¿Y V.? V. sí que de fijo no viene á misa.\"},{\"heading\":false,\"text\":\"--¿Y V. qué sabe? ¿Por qué no he de venir á misa yo?\"},{\"heading\":false,\"text\":\"Trocamos estas palabras con las manos cogidas y una familiaridad muy extraña, dado lo ceremonioso y somero de nuestro conocimiento la víspera. Era sin duda que influía en ambos la transparencia y alegría de la atmósfera, haciendo comunicativa nuestra satisfacción y dando carácter expansivo á nuestra voz y actitudes. Ya que estoy dialogando con mi alma y nada ha de ocultarse, la verdad es que en lo cordial de mi saludo entró por mucho la favorable impresión que me causaron las prendas personales del andaluz. Señor, ¿por qué no han de tener las mujeres derecho para encontrar guapos á los hombres que lo sean, y por qué ha de mirarse mal que lo manifiesten (aunque para manifestarlo dijesen tantas majaderías como los chulos del café Suizo)? Si no lo decimos lo pensamos, y no hay nada más peligroso que lo reprimido y oculto, lo que se queda dentro. En suma. Pacheco, que vestía un elegante terno gris claro, me pareció galán de veras; pero con igual sinceridad añadiré que esta idea no me preocupó arriba de dos segundos, pues yo no me pago solamente del exterior. Buena prueba di de ello casándome á los veinte con mi tío, que tenía lo menos cincuenta, y lo que es de gallardo...\"},{\"heading\":false,\"text\":\"Adelante. El señor de Pacheco, sin reparar que ya tocaban á misa, pegó la hebra, y seguimos de palique, guareciéndonos á la sombra del plátano, porque el sol nos hacía guiñar los ojos más de lo justo.\"},{\"heading\":false,\"text\":\"--¡Pero qué madrugadora!\"},{\"heading\":false,\"text\":\"--¿Madrugadora porque oigo misa á las diez?\"},{\"heading\":false,\"text\":\"--Sí señor: todo lo que no sea levantarse para almorsá...\"},{\"heading\":false,\"text\":\"--Pues V. hoy madrugó otro tanto.\"},{\"heading\":false,\"text\":\"--Tuve corasonada. Esta tarde estarán buenos los toros: ¿No va V.?\"},{\"heading\":false,\"text\":\"--No: hoy no irá la Sahagún, y yo generalmente voy con ella.\"},{\"heading\":false,\"text\":\"--¿Y á las carreras de caballos?\"},{\"heading\":false,\"text\":\"--Menos; me cansan mucho: una revista de trapos y moños: una insulsez. Ni entiendo aquel tejemaneje de apuestas. Lo único divertido e el desfile.\"},{\"heading\":false,\"text\":\"--Y entonces, ¿porqué no va á San Isidro?\"},{\"heading\":false,\"text\":\"--¡A San Isidro! ¡Después de lo que nos predicó ayer mi paisano!\"},{\"heading\":false,\"text\":\"--Buen caso hase V. de su paisano.\"},{\"heading\":false,\"text\":\"--Y ¿creerá V. que con tantos años como llevo de vivir en Madrid, ni siquiera he visto la ermita?\"},{\"heading\":false,\"text\":\"--¿Que no? Pues hay que verla; se distraerá V. muchísimo; ya sabe lo que opina la Duquesa, que esa fiesta merece el viaje. Yo no la conozco tampoco; verdá que soy forastero.\"},{\"heading\":false,\"text\":\"--Y... ¿y los borrachos, y los navajazos y todo aquello de que habló D. Gabriel? ¿Será exageración suya?\"},{\"heading\":false,\"text\":\"--¡Yo qué sé! ¡Qué más da!\"},{\"heading\":false,\"text\":\"--Me hace gracia... ¿Dice V. que no importa? ¿Y si luego paso un susto?\"},{\"heading\":false,\"text\":\"--¡Un susto yendo conmigo!\"},{\"heading\":false,\"text\":\"--¿Con V.?--y solté la risa.\"},{\"heading\":false,\"text\":\"--¡Conmigo, ya se sabe! No tiene V. por qué reirse, que soy mu buen compañero.\"},{\"heading\":false,\"text\":\"Me reí con más ganas, no sólo de la suposición de que Pacheco me acompañase, sino de su acento andaluz, que era cerrado y sandunguero, sin tocar en ordinario, como el de ciertos señoritos que parecen asistentes.\"},{\"heading\":false,\"text\":\"Pacheco me dejó acabar de reir, y sin perder su seriedad, con mucha calma, me explicó lo fácil y divertido que sería darse una vueltecita por la feria á primera hora, regresando á Madrid sobre las doce ó la una. ¡Si me hubiese tapado con cera los oídos entonces, cuántos males me evitaría! La proposición, de repente, empezó á tentarme, recordando el dicho de la Sahagún:--«Vaya V. al Santo, que aquello es muy original y muy famoso.»--Y realmente, ¿qué mal había en satisfacer mi curiosidad?, pensaba yo. Lo mismo se oía misa en la ermita del Santo que en las Pascualas; nada desagradable podía ocurrirme llevando conmigo á Pacheco; y si alguien me veía con él, tampoco sospecharía cosa mala de mí á tales horas y en sitio tan público. Ni era probable que anduviese por allí la sombra de una persona decente ¡en día de carreras y toros!, ¡á las diez de la mañana! La escapatoria no ofrecía riesgo... ¡y el tiempo convidaba tanto! En fin, que si Pacheco porfiaba algo más, lo que es yo...\"},{\"heading\":false,\"text\":\"Porfió sin impertinencia, y tácitamente, sonriendo, me declaré vencida. ¡Solemne ligereza! Aún no había articulado el _sí_, y ya discutíamos los medios de locomoción. Pacheco propuso, como más popular y típico, el tranvía; pero yo, á fin de que la cosa no tuviese el menor aspecto de informalidad, preferí mi coche. La cochera no estaba lejos: calle del Caballero de Gracia. Pacheco avisaría, mandaría que enganchasen é iría á recogerme á mi casa, por donde yo necesitaba pasar antes de la excursión. Tenía que tomar el abanico, dejar el devocionario, cambiar mantilla por sombrero... En casa le esperaría. Al punto que concertamos estos detalles, Pacheco me apretó la mano y se apartó corriendo de mí. A la distancia de diez pasos se paró y preguntó otra vez.\"},{\"heading\":false,\"text\":\"--¿Dice V. que el coche cierra en el Caballero de Gracia?\"},{\"heading\":false,\"text\":\"--Sí, á la izquierda... un gran portalón...\"},{\"heading\":false,\"text\":\"Y tomé aprisita el camino de mi vivienda, porque la verdad es que necesitaba hacer muchas más cosas de las que le había confesado á Pacheco; pero, ¡vaya V. á enterar á un hombre!... Arreglarme el pelo, darme velutina, buscar un pañolito fino, escoger unas botas nuevas que me calzan muy bien, ponerme guantes frescos y echarme en el bolsillo un _sachet_ de raso que huele á _iris_ (el único perfume que no me levanta dolor de cabeza). Porque al fin, aparte de todo, Pacheco era para mí persona de cumplido; íbamos á pasar algunas horas juntos y observándonos muy de cerca, y no me gustaría que algún rasgo de mi ropa ó mi persona le produjese efecto desagradable. A cualquier señora, en mi caso, le sucedería lo propio.\"},{\"heading\":false,\"text\":\"Llegué al portal sofocada y anhelosa, subí á escape, llamé con furia y me arrojé en el tocador, desprendiéndome la mantilla antes de situarme frente al espejo.--«Angela, el sombrero negro de paja con cinta escocesa... Angela, el antuca á cuadritos... las botas bronceadas...»\"},{\"heading\":false,\"text\":\"Vi que la Diabla se moría de curiosidad... «¿Sí? Pues con las ganas de saber te quedas, hija... La curiosidad es muy buena para la ropa blanca.» Pero no se le coció á la chica el pan en el cuerpo, y me soltó la píldora.\"},{\"heading\":false,\"text\":\"--¿La señorita almuerza en casa?\"},{\"heading\":false,\"text\":\"Para desorientarla respondí:\"},{\"heading\":false,\"text\":\"--Hija, no sé... Por si acaso, tenerme el almuerzo listo de doce y media á una... Si á la una no vengo, almorzad vosotros... pero reservándome siempre una chuleta y una taza de caldo... y mi té con leche, y mis tostadas.\"},{\"heading\":false,\"text\":\"Cuando estaba arreglando los rizos de la frente bajo el ala del sombrero, reparé en un precioso cacharro azul, lleno de heliotropos, gardenias y claveles, que estaba sobre la chimenea.\"},{\"heading\":false,\"text\":\"--¿Quién ha mandado eso?\"},{\"heading\":false,\"text\":\"--El señor comandante Pardo... el señorito Gabriel.\"},{\"heading\":false,\"text\":\"--¿Por qué no me lo enseñabas?\"},{\"heading\":false,\"text\":\"--Vino la señorita tan aprisa... Ni me dió tiempo.\"},{\"heading\":false,\"text\":\"No era la primera vez que mi paisano me obsequiaba con flores. Escogí una gardenia y un clavel rojo, y prendí el grupo en el pecho. Sujeté el velo con un alfiler, tomé un casaquín ligero de paño, mandé á Angela que me estirase la enagua y volante, y me asomé á ver si por milagro había llegado el coche. Aún no, porque era imposible; pero á los diez minutos desembocaba á la entrada de la calle. Entonces salí á la antesala, andando despacio, para que la Diabla no acabase de escamarse; me contuve hasta cruzar la puerta; y ya en la escalera, me precipité, llegando al portal cuando se paraba la berlina y saltaba en la acera Pacheco.\"},{\"heading\":false,\"text\":\"--¡Qué listo anduvo el cochero!--le dije.\"},{\"heading\":false,\"text\":\"--El cochero y un servidor de V., señora--contestó el gaditano, teniendo la portezuela para que yo subiese.--Con estas manos he ayudao á echar las guarniciones, y hasta se me figura que á lavar las ruedas.\"},{\"heading\":false,\"text\":\"Salté en la berlina, quedándome á la derecha, y Pacheco entró por la portezuela contraria, á fin de no molestarme y con ademán de profundo respeto... ¡Valiente hipócrita está él! Nos miramos indecisos por espacio de una fracción de segundo, y mi acompañante me preguntó en voz sumisa:\"},{\"heading\":false,\"text\":\"--¿Doy orden de ir camino de la pradera?\"},{\"heading\":false,\"text\":\"--Sí, sí... Dígaselo V. por el vidrio.\"},{\"heading\":false,\"text\":\"Sacó fuera la cabeza y gritó:--«¡Al Santo!»--La berlina arrancó inmediatamente, y entre el primer retemblido de los cristales exclamó Pacheco:\"},{\"heading\":false,\"text\":\"--Veo que se ha prevenío V. contra el calor y el sol... Todo hace falta.\"},{\"heading\":false,\"text\":\"Sonreí sin responder, porque me encontraba (y no tiene nada de sorprendente) algo cohibida por la novedad de la situación. No se desalentó el gaditano.\"},{\"heading\":false,\"text\":\"--Lleva V. ahí unas flores preciosas... ¿No sobraba para mí ninguna? ¿Ni siquiera una rosita de á ochavo? ¿Ni un palito de albahaca?\"},{\"heading\":false,\"text\":\"--Vamos--murmuré--que no es V. poco pedigüeño... Tome V., para que se calle.\"},{\"heading\":false,\"text\":\"Desprendí la gardenia y se la ofrecí. Entonces hizo mil remilgos y zalemas.\"},{\"heading\":false,\"text\":\"--Si yo no pretendía tanto... Con el rabillo me contentaba, ó con media hoja que V. le arrancase... ¡Una gardenia para mí solo! No sé cómo lucirla... No se me va á sujetar en el ojal... A ver si V. consigue, con esos deditos...\"},{\"heading\":false,\"text\":\"--Vamos, que V. no pedía tanto, pero quiere que se la prenda ¿eh? Vuélvase V. un poco, voy á afianzársela.\"},{\"heading\":false,\"text\":\"Introduje el rabo postizo de la flor en el ojal de Pacheco, y tomando de mi corpiño un alfiler sujeté la gardenia, cuyo olor á pomada me subía al cerebro, mezclado con otro perfume fino, procedente, sin duda, del pelo de mi acompañante. Sentí un calor extraordinario en el rostro, y al levantarlo, mis ojos se tropezaron con los del meridional, que en vez de darme las gracias, me contempló de un modo expresivo é interrogador. En aquel momento casi me arrepentí de la humorada de ir á la feria; pero ya...\"},{\"heading\":false,\"text\":\"Torcí el cuello y miré por la ventanilla. Bajábamos de la plazuela de la Cebada á la calle de Toledo. Una marea de gente, que también descendía hacia la pradera, rodeaba el coche y le impedía á veces rodar. Entre la multitud dominguera se destacaban los vistosos colorines de algún bordado pañolón de Manila, con su fleco de una tercia de ancho. Las chulas se volvían y registraban con franca curiosidad el interior de la berlina. Pacheco sacó la cabeza y le dijo á una no sé qué.\"},{\"heading\":false,\"text\":\"--Nos toman por novios--advirtió dirigiéndose á mí.--No se ponga V. más colorada: es lo que le faltaba para acabar de estar linda--añadió medio entre dientes.\"},{\"heading\":false,\"text\":\"Hice como si no oyese el piropo y desvié la conversación, hablando del pintoresco aspecto de la calle de Toledo, con sus mil tabernillas, sus puestos ambulantes de quincalla, sus anticuadas tiendas y sus paradores que se conservan lo mismito que en tiempo de Carlos IV. Noté que Pacheco se fijaba poco en tales menudencias, y en vez de observar las curiosidades de la calle más típica que tiene Madrid, llevaba los ojos puestos en mí con disimulo, pero con pertinacia, como el que estudia una fisonomía desconocida para leer en ella los pensamientos de la dueña. Yo también, á hurtadillas, procuraba enterarme de los más mínimos ápices de la cara de Pacheco. No dejaba de llamarme la atención la mezcla de razas que creía ver en ella. Con un pelo negrísimo y una tez quemada del sol, casaban mal aquel bigote dorado y aquellos ojos azules.\"},{\"heading\":false,\"text\":\"--¿Es V. hijo de inglesa?--le pregunté al fin.--Me han contado que en la costa del Mediterráneo hay muchas bodas entre ingleses y españolas, y al revés.\"},{\"heading\":false,\"text\":\"--Es cierto que hay muchísimas, en Málaga sobre todo; pero yo soy español de pura sangre.\"},{\"heading\":false,\"text\":\"Le volví á mirar y comprendí lo tonto de mi pregunta. Ya recordaba haber oído á algún sabio de los que suele convidar á comer la Sahagún cuando no tiene otra cosa en que entretenerse, que es una vulgaridad figurarse que los españoles no pueden ser rubios, y que al contrario el tipo rubio abunda en España, sólo que no se confunde con el rubio sajón, porque es mucho más fino, más enjuto, así al modo de los caballos árabes. En efecto, los ingleses que yo conozco son por lo regular unos montones de carne sanguínea, que al parecer se escapa sola á la parrilla del rosbif; tienen cada cogote y cada pescuezo como ruedas de remolacha; las bocas de ellos dan asco de puro coloradotas, y las frentes, de tan blancas, fastidian ya, porque eso de la _frente pura_ está bueno para las señoritas, no para los hombres. ¿Cuándo se verá en ningún inglés un corte de labios sutil, y una sien hundida, y un cuello delgado y airoso como el de Pacheco? Pero al grano: ¿pues no me entretengo recreándome en las perfecciones de ese pillo?\"},{\"heading\":false,\"text\":\"¡Qué hermoso y alegre estaba el puente de Toledo! Lo recuerdo como se recuerda una decoración del teatro Real. Hervía la gente, y mirando hacia abajo, por la pradera y por todas las orillas de Manzanares no se veían más que grupos, procesiones, corrillos, escenas animadísimas de esas que se pintan en las panderetas. A mí ciertos monumentos, por ejemplo las catedrales, casi me parecen más bonitas solitarias; pero el puente de Toledo, con sus retablazos, ó nichos, ó lo que sean aquellos fantasmones barrocos que le guarnecen á ambos lados, no está bien sin el rebullicio y la algazara de la gentuza, los chulapos y los tíos, los carniceros y los carreteros, que parece que acaban de bajarse de un lienzo de Goya. Ahora que se han puesto tan de moda los casacones, el puente tiene un encanto especial. Nuestro coche dió vuelta para tomar el camino de la pradera, y allí, en el mismo recodo, vi una tienda rara, una botería, en cuya fachada se ostentaban botas de todos los tamaños, desde la que mide treinta azumbres de vino, hasta la que cabe en el bolsillo del pantalón. Pacheco me propuso que, para adoptar el tono de la fiesta, comprásemos una botita muy cuca que colgaba sobre el escaparate y la llenásemos de Valdepeñas: proposición que rechacé horrorizada.\"},{\"heading\":false,\"text\":\"No sé quién fué el primero que llamó feas y áridas á las orillas del Manzanares, ni por qué los periódicos han de estar siempre soltándole pullitas al pobre río, ni cómo no prendieron á aquel farsante de escritor francés (Alejandro Dumas, si no me engaño) que le ofreció de limosna un vaso de agua. Convengo en que no es muy caudaloso, ni tan frescachón como nuestro Miño ó nuestro Sil; pero vamos, que no falta en sus orillas algún rinconcito ameno, verde y simpático. Hay árboles que convidan á descansar á la sombra, y unos puentes rústicos por entre los lavaderos, que son bonitos en cualquier parte. La verdad es que acaso influía en esta opinión que formé entonces, el que se me iba quitando el susto y me rebosaba el contento por haber realizado la escapatoria. Varios motivos se reunían para completar mi satisfacción. Mi traje de _céfiro_ gris, sembrado de anclitas rojas, era de buen gusto en una excursión matinal como aquella; mi sombrero negro de paja me sentaba bien, según comprobé en el vidrio delantero de la berlina; el calor aún no molestaba mucho; mi acompañante me agradaba, y la calaverada, que antes me ponía miedo, iba pareciéndome lo más inofensivo del mundo, pues no se veía por allí ni rastro de persona regular que pudiese conocerme. Nada me aguaría tanto la fiesta como tropezarme con algún tertuliano de la Sahagún, ó vecina de butacas en el Real, que fuese luego á permitirse comentarios absurdos. Sobran personas maldicientes y deslenguadas que interpretan y traducen siniestramente las cosas más sencillas, y de poco le sirve á una mujer pasarse la vida muy sobre aviso, si se descuida una hora... (Sí, y lo que es á mí, en la actualidad, me caen muy bien estas reflexiones. En fin, prosigamos.) El caso es que la pradera ofrecía aspecto tranquilizador. Pueblo aquí, pueblo allí, pueblo en todas direcciones; y si algún hombre vestía americana, en vez de chaquetón ó chaquetilla, debía de ser criado de servicio, escribiente temporero, hortera, estudiante pobre, lacayo sin colocación, que se tomaba un día de asueto y holgorio. Por eso, cuando á la subida del cerro, donde ya no pueden pasar los carruajes, Pacheco y yo nos bajamos de la berlina, parecíamos, por el contraste, pareja de archiduques que tentados de la curiosidad se van á recorrer una fiesta populachera, deseosos de guardar el incógnito, y delatados por sus elegantes trazas.\"},{\"heading\":false,\"text\":\"En fuerza de su novedad me hacía gracia el espectáculo. Aquella romería no tiene nada que ver con las de mi país, que suelen celebrarse en sitios frescos, sombreados por castaños ó nogales, con una fuente ó riachuelo cerquita y el santuario en el monte próximo... El campo de San Isidro es una serie de cerros pelados, un desierto de polvo, invadido por un tropel de gente entre la cual no se ve un solo campesino, sino soldados, mujerzuelas, chisperos, ralea apicarada y soez; y en lugar de vegetación, miles de tinglados y puestos donde se venden cachivaches que, pasado el día del Santo, no vuelven á verse en parte alguna: pitos adornados con hojas de papel de plata y rosas estupendas; vírgenes pintorreadas de esmeralda, cobalto y bermellón; medallas y escapularios igualmente rabiosos; loza y cacharros; figuritas groseras de toreros y picadores; botijos de hechuras raras; monigotes y fantoches con la cabeza de Martos, Sagasta ó Castelar; ministros á _dos reales_; esculturas de los _ratas_ de _La Gran Vía_, y al lado de la efigie del bienaventurado San Isidro, unas figuras que... ¡Válgame Dios! Hagamos como si no las viésemos.\"},{\"heading\":false,\"text\":\"Aparte del sol que le derrite á uno la sesera y del polvo que se masca, bastan para marear tantos colorines vivos y metálicos. Si sigo mirando van á dolerme los ojos. Las naranjas apiñadas parecen de fuego; los dátiles relucen como granates obscuros; como pepitas de oro los garbanzos tostados y los cacahuetes; en los puestos de flores no se ven sino claveles amarillos, sangre de toro, ó de un rosa tan encendido como las nubes á la puesta del sol: las emanaciones de toda esta clavelería no consiguen vencer el olor á aceite frito de los buñuelos, que se pega á la garganta y produce un cosquilleo inaguantable. Lo dicho, aquí no hay color que no sea desesperado: el uniforme de los militares, los mantones de las chulas, el azul del cielo, el amarillento de la tierra, los tíos vivos con listas coloradas y los columpios dados de almagre con rayas de añil... Y luego la música, el rasgueo de las guitarras, el tecleo insufrible de los pianos mecánicos que nos aporrean los oídos con el paso doble de _Cádiz_, repitiendo desde treinta sitios de la romería:--_¡Vi-va España!_\"},{\"heading\":false,\"text\":\"Nadie imagine maliciosamente que se me había pasado lo de oir misa. Tratamos de romper por entre el gentío y de deslizarnos en la ermita, abierta de par en par á los devotos; pero éstos eran tantos, y tan apiñados, y tan groseros, y tan mal olientes, que si porfío en llegar á la nave, me sacan de allí desmayada ó difunta. Pacheco jugaba los brazos y los puños, según podía, para defenderme; sólo lograba que nos apretasen más y que oyésemos juramentos y blasfemias atroces. Le tiré de la manga.\"},{\"heading\":false,\"text\":\"--Vámonos, vámonos de aquí... Renuncio... No se puede.\"},{\"heading\":false,\"text\":\"Cuando ya salimos á atmósfera respirable, suspiré muy compungida.\"},{\"heading\":false,\"text\":\"--¡Ay, Dios mío!... Sin misa hoy...\"},{\"heading\":false,\"text\":\"--No se apure--me contestó mi acompañante--que yo oiré por V. aunque sea todas las gregorianas... Ya ajustaremos esa cuenta.\"},{\"heading\":false,\"text\":\"--A mí sí que me la ajustará el Padre Urdax tan pronto me eche la vista encima--pensaba para mis adentros mientras me tentaba el hombro, donde había recibido un codazo feroz de uno de aquellos cafres.\"}]},{\"title\":\"Insolación — capítulo IV\",\"blocks\":[{\"heading\":false,\"text\":\"Don Diego, que en el coche se me figuraba reservado y tristón, se volvió muy dicharachero desde que andábamos por San Isidro, justificando su fama de buena sombra. Sujetando bien mi brazo para que las mareas de gente no nos separasen, él no perdía ripio, y cada pormenor de los tinglados famosos le daba pretexto para un chiste, que muchas veces no era tal sino en virtud del tono y acento con que lo decía, porque es indudable que si se escribiesen las ocurrencias de los andaluces, no resultarían tan graciosas, ni la mitad, de lo que parecen en sus labios; al sonsonete, al ceceíllo y á la prontitud en responder, se debe la mayor parte del salero.\"},{\"heading\":false,\"text\":\"Lo peor fué que como allí no había más personas regulares que nosotros, y Pacheco se metía con todo el mundo y á todo el mundo daba cuerda, nos rodeó la canalla de mendigos, fenómenos, chiquillos harapientos, gitanas, buñoleras y vendedoras. El impulso de mi acompañante era comprar cuanto veía, desde los escapularios hasta los botijos, pero me cuadré.\"},{\"heading\":false,\"text\":\"--Si compra V. más, me enfado.\"},{\"heading\":false,\"text\":\"--¡Soniche! San acabao las compras. ¡Que san acabao digo! Al que no me deje en paz, le doy en igual de dinero, cañaso. ¿Tiene V. más que mandar?\"},{\"heading\":false,\"text\":\"--Mire V., pagaría por estar á la sombra un ratito.\"},{\"heading\":false,\"text\":\"--¿En la cárcel por comprometeora? Llamaremos á la pareja y verasté que pronto.\"},{\"heading\":false,\"text\":\"Ahora que reflexiono á sangre fría, caigo en la cuenta de que era bastante raro y muy inconveniente que á los tres cuartos de hora de pasearnos juntos por San Isidro, nos hablásemos don Diego y yo con tanta broma y llaneza. Es posible, bien mirado, que mi paisano tenga razón; que aquel sol, aquel barullo y aquella atmósfera popular obren sobre el cuerpo y el alma como un licor ó vino de los que más se suben á la cabeza, y rompan desde el primer momento la valla de reserva que trabajosamente levantamos las señoras un día y otro contra peligrosas osadías. De cualquier índole que fuese, yo sentía ya un principio de mareo cuando exclamé:\"},{\"heading\":false,\"text\":\"--En la cárcel estaría á gusto con tal que no hiciese sol... Me encuentro así... no sé cómo... parece que me desvanezco.\"},{\"heading\":false,\"text\":\"--Pero ¿se siente V. mala? ¿mala?--preguntó Pacheco seriamente, con vivo interés.\"},{\"heading\":false,\"text\":\"--Lo que se dice mala, no: es una fatiga, una sofocación... Se me nubla la vista.\"},{\"heading\":false,\"text\":\"Echóse Pacheco á reir y me dijo casi al oído:\"},{\"heading\":false,\"text\":\"--Lo que V. tiene ya lo adivino yo, sin necesidad de ser sahorí... V. tiene ni más ni menos que... gasusa.\"},{\"heading\":false,\"text\":\"--¿Eh?\"},{\"heading\":false,\"text\":\"--Debilidad, hablando pronto... ¡Y no es V. sola!.. yo hace rato que doy las boqueás de hambre. ¡Si debe de ser mediodía!\"},{\"heading\":false,\"text\":\"--Puede, puede que no se equivoque V. mucho. A estas horas suelen pasearse los ratoncitos por el estómago... Ya hemos visto el Santo; volvámonos á Madrid y podrá V. almorzar, si gusta acompañarme...\"},{\"heading\":false,\"text\":\"--No, señora... Si eso que V. discurre es un pueblo. Si lo que vamos á haser es almorsá en una fondita de aquí. ¡Que las hay...!\"},{\"heading\":false,\"text\":\"Se llevó los dedos apiñados á la boca y arrojó un beso al aire, para expresar la excelencia de las fondas de San Isidro.\"},{\"heading\":false,\"text\":\"Aturdida y todo como me encontraba, la idea me asustó; me pareció indecorosa y vi de una ojeada sus dificultades y riesgos. Pero al mismo tiempo, allá en lo íntimo del alma, aquellos escollos me la hacían deliciosa, apetecible, como es siempre lo vedado y lo desconocido. ¿Era Pacheco algún atrevido, capaz de faltarme si yo no le daba pié? No por cierto; y el no darle pié quedaba de mi cuenta. ¡Qué buen rato me perdía rehusando! ¿Qué diría Pardo de esta aventura si la supiese? Con no contársela... Mientras discurría así, en voz alta me negaba terminantemente... Nada, á Madrid de seguida.\"},{\"heading\":false,\"text\":\"Pacheco no cejó, y en vez de formalizarse, echó á broma mi negativa. Con mil zalamerías y agudezas, ceceando más que nunca, afirmó que espicharía de necesidad si tardase en almorzar arriba de veinte minutos.\"},{\"heading\":false,\"text\":\"--Que me pongo de rodillas aquí mismo...--exclamaba el muy truhán.--Ea, un sí de esa boquita... ¡Usted verá el gran almuerso del siglo! Fuera escrúpulos... ¿Se ha pensao V. que mañana voy yo á contárselo á la señá duquesa de Sahagún? A este probetico..., ¡una limosna de armuerso!.\"},{\"heading\":false,\"text\":\"Acabó por entrarme risa y tuve la flaqueza de decir:\"},{\"heading\":false,\"text\":\"--Pero... ¿y el coche que está aguardando allá abajo?\"},{\"heading\":false,\"text\":\"--En un minuto se le avisa... Que se procure cochera aquí... Y si no, que se vuelva á Madrid hasta la puesta del sol... Espere V., buscaré alguno que lleve el recao... No la he de dejar aquí solita pa que se la coma un lobo; eso sí que no.\"},{\"heading\":false,\"text\":\"Debió de oirlo un guindilla que andaba por allí ejerciendo sus funciones, y en tono tan reverente y servicial como bronco lo usaba para intimar á la gentuza que se _desapartase_, nos dijo con afable sonrisa:\"},{\"heading\":false,\"text\":\"--Yo aviso, si justan... ¿Dónde está ó coche? ¿Cómo le llaman al cochero?\"},{\"heading\":false,\"text\":\"--Este no es de mi tierra, ni nada. ¿De qué parte de Galicia?--pregunté al agente.\"},{\"heading\":false,\"text\":\"--Desviado de Lujo tres légoas, á la banda de Sarria, para servir á vusté--explicó él, y los ojos le brillaron de alegría al encontrarse con una paisana.--«¿Si éste me conocerá por conducto de la Diabla?»--pensé yo recelosa; pero mi temor sería infundado, pues el agente no añadió nada más. Para despacharle pronto, le expliqué:\"},{\"heading\":false,\"text\":\"--¿Ve aquella berlina con ruedas encarnadas..., cochero mozo, con patillas, librea verde? Allá abajo... Es la octava en la fila.\"},{\"heading\":false,\"text\":\"--Bien veo, bien.\"},{\"heading\":false,\"text\":\"--Pues va V.--ordenó Pacheco--y le dice que se largue á Madrí con viento fresco, y que por la tardesita vuerva y se plantifique en el mismo lugar. ¿Estamos, compadre?\"},{\"heading\":false,\"text\":\"Noté que mi acompañante extendía la mano y estrechaba con gran efusión la del guindilla; pero no sería esta distinción lo que tanto le alegró la cara á mi conterráneo, pues le vi cerrar la diestra deslizándola en el bolsillo del pantalón, y entreoí la fórmula gallega clásica:\"},{\"heading\":false,\"text\":\"--De hoy en cien años.\"},{\"heading\":false,\"text\":\"Libre ya del apéndice del carruaje, por instinto me apoyé más fuerte en el brazo de Don Diego, y él á su vez estrechó el mío como ratificando un contrato.\"},{\"heading\":false,\"text\":\"--Vamos poquito á poco subiendo al cerro... Animo y cogerse bien.\"},{\"heading\":false,\"text\":\"El sol campeaba en mitad del cielo, y vertía llamas y echaba chiribitas. El aire faltaba por completo; no se respiraba sino polvo arcilloso. Yo registraba el horizonte tratando de descubrir la prometida fonda, que siempre sería un techo, preservativo contra aquel calor del Senegal. Mas no se veía rastro de edificio grande en toda la extensión del cerro, ni antes ni después. Las únicas murallas blancas que distinguí á mi derecha eran las tapias de la Sacramental, á cuyo amparo descansaban los muertos sin enterarse de las locuras que del otro lado cometíamos los vivos. Amenacé á Pacheco con el palo de la sombrilla:\"},{\"heading\":false,\"text\":\"--¿Y esa fonda? ¿Se puede saber hasta qué hora vamos á andar buscándola?\"},{\"heading\":false,\"text\":\"--¿Fonda?--saltó Pacheco como si le sorprendiese mucho mi pregunta.--¿Dijo V. fonda? El caso es... Mardito si sé á qué lado cae.\"},{\"heading\":false,\"text\":\"--¡Hombre..., pues de veras que tiene gracia! ¿No aseguraba V. que había fondas preciosas, magníficas? ¡Y me trae V. con tanta flema á asarme por estos vericuetos! Al menos entérese... Pregunte á cualquiera, ¡al primero que pase!\"},{\"heading\":false,\"text\":\"--¡Oigasté... cristiano!\"},{\"heading\":false,\"text\":\"Volvióse un chulo de pelo alisado en peteneras, manos en los bolsillos de la chaquetilla, hocico puntiagudo, gorra alta de seda, estrecho pantalón y viciosa y pálida faz; el tipo perfecto del rata, de esos mocitos que se echa uno á temblar al verlos, recelando que hasta el modo de andar le timen.\"},{\"heading\":false,\"text\":\"--¿Hay por aquí alguna fonda, compañero?--interrogó Pacheco alargándole un buen puro.\"},{\"heading\":false,\"text\":\"--Se estima... Como haber fondas, hay fondas: misté por ahí too alredor, que fondas son; pero tocante á fonda, vamos, según se ice, de comías finas, pala gente é aquel, me pienso que no hallarán ustés conveniencia; digo, esto me lo pienso yo; ustés verán.\"},{\"heading\":false,\"text\":\"--No hay más que merenderos, está visto--pronunció Pacheco bajo y con acento pesaroso.\"},{\"heading\":false,\"text\":\"Al ver que él se mostraba disgustado, yo, por ese instinto de contradicción humorística que en situaciones tales se nos desarrolla á las mujeres, me manifesté satisfecha. Además, en el fondo, no me desagradaba comer en un merendero. Tenía más _carácter_. Era más nuevo é imprevisto, y hasta menos clandestino y peligroso. ¿Qué riesgo hay en comer en un barracón abierto por todos lados donde está entrando y saliendo la gente? Es tan inocente como tomar un vaso de cerveza en un café al aire libre.\"}]},{\"title\":\"Insolación — capítulo V\",\"blocks\":[{\"heading\":false,\"text\":\"Convencidos ya de que no existía fonda ni sombra de ella, ó de que nosotros no acertábamos á descubrirla, miramos á nuestro alrededor, eligiendo el merendero menos indecente y de mejor trapío. Casi en lo alto del cerro campeaba uno bastante grande y aseado; no ostentaba ningún rótulo extravagante, como los que se leían en otros merenderos próximos, verbigracia:--«Refrescos de los que usava el Santo.»--«La mar en vevidas y comidas.»--«La Brillantez: callos y caracoles.»--A la entrada (que puerta no la tenía) hallábase de pié una chica joven, de fisonomía afable, con un puñal de níquel atravesado en el moño: y no había otra alma viviente en el merendero, cuyas seis mesas vacías me parecieron muy limpias y fregoteadas. Pudiera compararse el barracón á una inmensa tienda de campaña: las paredes de lona: el techo de unas esteras tendidas sobre palos: dividíase en tres partes desiguales, la menor ocultando la hornilla y el fogón donde guisaban, la grande que formaba el comedor, la mediana que venía á ser una trastienda donde se lavaban platos y cubiertos; pero estos misterios convinimos en que sería mejor no profundizarlos mucho, si habíamos de almorzar. El piso del merendero era de greda amarilla, la misma greda de todo el árido cerro: y una vieja, sucia y horrible, que frotaba con un estropajo las mesas, no necesitaba sino bajarse para encontrar la materia primera de aquel limpión inverosímil.\"},{\"heading\":false,\"text\":\"Tomamos posesión de la mesa del fondo, sentándonos en un banco de madera que tenía por respaldo la pared de lona del barracón. La muchacha, con su perrera pegada á la frente por grandes churretazos de goma y su puñal de níquel en el moño, acudió solícita á ver qué mandábamos: olfateaba parroquianos gordos, y acaso adivinaba ó presentía otra cosa, pues nos dirigió unas sonrisitas de inteligencia que me pusieron colorada. Decía á gritos la cara de la chica:--«Buen par están estos dos... ¿Qué manía les habrá dado de venir á arrullarse en el Santo? Para eso más les valía quedarse en su nido... que no les faltará, de seguro».--Yo, que leía semejantes pensamientos en los ojos de la muy entremetida, adopté una actitud reservada y digna, hablando á Pacheco como se habla á un amigo íntimo, pero _amigo_ á secas; precaución que lejos de desorientar á la maliciosa muchacha, creo que sólo sirvió para abrirle más los ojos. Nos dirigió la consabida pregunta:\"},{\"heading\":false,\"text\":\"--¿Qué van á tomar?\"},{\"heading\":false,\"text\":\"--¿Qué nos puede V. dar?--contestó Pacheco.--Diga V. lo que hay, resalada..., y la señora irá escogiendo.\"},{\"heading\":false,\"text\":\"--Como haber..., hay de todo. ¿Quieren almorzar formalmente?\"},{\"heading\":false,\"text\":\"--Con toa formaliá.\"},{\"heading\":false,\"text\":\"--Pues de primer plato... una tortillita... ó huevos revueltos.\"},{\"heading\":false,\"text\":\"--Vaya por los huevos revueltos. ¿Y hay magras?\"},{\"heading\":false,\"text\":\"--¿Unas magritas de jamón? Sí.\"},{\"heading\":false,\"text\":\"--¿Y chuletas?\"},{\"heading\":false,\"text\":\"--De ternera, muy ricas.\"},{\"heading\":false,\"text\":\"--¿Pescado?\"},{\"heading\":false,\"text\":\"--Pescado no... Si quieren latas... tenemos escabeche de besugo, sardinas...\"},{\"heading\":false,\"text\":\"--¿Ostras no?\"},{\"heading\":false,\"text\":\"--Como ostras..., no señora. Aquí pocas cosas finas se pueden despachar. Lo general que piden... callos y caracoles, Valdepeñas, chuletas...\"},{\"heading\":false,\"text\":\"--V. resolverá--indiqué volviéndome á Pacheco.\"},{\"heading\":false,\"text\":\"--¿He de ser yo? Pues tráiganos de too eso que hemos dicho, niña bonita..., huevos, magras, ternera, lata de sardinas... ¡Ay! y lo primero de too se va V. á traer por los aires una boteya e mansaniya y unas cañitas... Y aseitunas.\"},{\"heading\":false,\"text\":\"--Y después... ¿qué es lo que les he de servir? ¿Las chuletas antes de nada?\"},{\"heading\":false,\"text\":\"--No: misté, azucena: nos sirve V. los huevos, luego el jamón, las sardinas, las chuletitas... De postre, si hay algún queso...\"},{\"heading\":false,\"text\":\"--¡Ya lo creo que sí! De Flandes y de Villalón... Y pasas, y almendras, y rosquillas, y avellanas tostás...\"},{\"heading\":false,\"text\":\"--Pues vamos á armorsá mejor que el Nuncio.\"},{\"heading\":false,\"text\":\"Esto mismo que exclamó Pacheco frotándose las manos, lo pensaba yo. Aquellas ordinarieces, como diría mi paisano el filósofo, me abrían el apetito de par en par. Y aumentaba mi buena disposición de ánimo el encontrarme á cubierto del terrible sol.\"},{\"heading\":false,\"text\":\"Verdad que estaba á cubierto lo mismo que el que sale al campo á las doce del día bajo un paraguas. El sol, si no podía ensañarse con nuestros cráneos, se filtraba por todas partes y nos envolvía en un baño abrasador. Por entre las esteras mal juntas del techo, al través de la lona, y sobre todo, por el abierto frente de la tienda, entraban á oleadas, á torrentes, no sólo la luz y el calor del astro, sino el ruido, el oleaje del humano mar, los gritos, las disputas, las canciones, las risotadas, los rasgueos y punteos de guitarra y vihuela, el infernal paso doble, el _¡Viva España!_ de los duros pianos mecánicos.\"},{\"heading\":false,\"text\":\"Casi al mismo punto en que la chica del puñal de níquel depositaba en la mesa una botella rotulada _Manzanilla superior_, dos cañas del vidrio más basto y dos conchas con rajas de salchichón y aceitunas _aliñás_, se coló por la abertura una mujer desgreñada, cetrina, con ojos como carbones, saya de percal con almidonados faralaes y pañuelo de crespón de lana desteñido y viejo, que al cruzarse sobre el pecho dejaba asomar la cabeza de una criatura. La mujer se nos plantó delante, fija la mano izquierda en la cadera y accionando con la derecha: de qué modo se sostenía el chiquillo, es lo que no entiendo.\"},{\"heading\":false,\"text\":\"--En er nombre e Dios, Pare, Jijo y Epíritu Zanto, que donde va er nombre e Dios no va cosa mala. Una palabrita les voy á icir que lase á ostés mucha farta saberla...\"},{\"heading\":false,\"text\":\"--¡Calle!--grité yo contentísima. ¡Una gitana que nos va á decir la buenaventura!\"},{\"heading\":false,\"text\":\"--¿La mando que se largue? ¿La incomoda á V.?\"},{\"heading\":false,\"text\":\"--¡Al contrario! Si me divierte lo que no es imaginable. Verá V. cuántos enredos va á echar por esa boca. Ea, la buenaventura pronto, que tengo una curiosidad inmensa de oirla.\"},{\"heading\":false,\"text\":\"--Pué diñe osté la mano erecha, jermosa, y una moneíta de plata pa jaser la crú.\"},{\"heading\":false,\"text\":\"Pacheco le alargó una peseta, y al mismo tiempo, habiendo descorchado la manzanilla y pedido otra caña, se la tendió llena de vino á la egipcia. Con este motivo armaron los dos un tiroteo de agudezas y bromas; bien se conocía que eran hijos de la misma tierra, y que ni á uno ni á otro se les atascaban las palabras en el gaznate, ni se les agotaba la labia aunque la derramasen á torrentes. Al fin la gitana se embocó el contenido de la cañita, y yo la imité, porque, con la sed, tentaba aquel vinillo claro. ¡Manzanilla superior! ¡A cualquier cosa llaman _superior_ aquí! La manzanilla dichosa sabía á esparto, á piedra alumbre y á demonios coronados; pero como al fin era un líquido, y yo con el calor estaba para beberme el Manzanares entero, no resistí cuando Pacheco me escanció otra caña. Sólo que en vez de refrescarme, se me figuró que un rayo de sol, disuelto en polvo, se me introducía en las venas y me salía en chispas por los ojos y en arreboles por la faz. Miré á Pacheco muy risueña, y luego me volví confusa, porque él me pagó la mirada con otra más larga de lo debido.\"},{\"heading\":false,\"text\":\"--¡Qué bonitos ojos azules tiene este perdis!--pensaba yo para mí.\"},{\"heading\":false,\"text\":\"El gaditano estaba sin sombrero; vestía un traje ceniza, elegante, de paño rico y flexible; de vez en cuando se enjugaba la frente sudorosa con un pañuelo fino, y á cada movimiento se le descomponía el pelo, bastante crecido, negro y sedoso; al reir, le iluminaba la cara la blancura de sus dientes, que son de los mejor puestos y más sanos que he visto nunca, y aun parecía doblemente morena su tez, ó mejor dicho, doblemente tostada, porque hacia la parte que ya cubre el cuello de la camisa se entreveía un cutis claro.\"},{\"heading\":false,\"text\":\"--La mano, jermosa,--repitió la gitana.\"},{\"heading\":false,\"text\":\"Se la alargué, y ella la agarró haciéndomela tener abierta. Pacheco contemplaba las dos manos unidas.\"},{\"heading\":false,\"text\":\"--¡Qué contraste!--murmuró en voz baja, no como el que dice una galantería á una señora, sino como el que hace una reflexión entre sí.\"},{\"heading\":false,\"text\":\"En efecto, sin vanidad, tengo que reconocer que la mano de la gitana, al lado de la mía, parecía un pedazo de cecina feísimo: la tumbaga de plata, donde resplandecía una esmeralda falsa espantosa, contribuía á que resaltase el color cobrizo de la garra aquella, y claro está que mi diestra, que es algo chica, pulida y blanca, con anillos de perlas, zafiros y brillantes, contrastaba extrañamente. La buena de la bohemia empezó á hacer sus rayas y ensalmos, endilgándonos una retahila de esas que no comprometen, pues son de doble sentido y se aplican á cualquier circunstancia, como las respuestas de los oráculos. Todo muy recalcado con los ojos y el ademán.\"},{\"heading\":false,\"text\":\"--Una cosa diquelo yo en esta manica, que hae suseder mu pronto, y nadie saspera que susea... Un viaje me vasté á jaser, y no ae ser para má, que ae ser pa sastisfasión e toos. Una carta me vasté á resibir, y lae alegrá lo que viene escribío en eya... Unas presonas me tiene usté que la quieren má, y están toas perdías por jaserle daño; pero der revé les ae salir la perra intensión... Una presoniya está chalaíta por usté--(al llegar aquí la bruja clavó en Pacheco las ascuas encendidas de sus ojos)--y un convite le ae dar quien bien la quiere... Amorosica de genio me es usté; pero cuando se atufa, una leona brava de los montes se me güerve... Que no la enriten a usté y que le yeven toiticas las cosas ar pelo de la suavidá, que por la buena, corasón tiene usté pa tirarse en metá e la bahía e Cadis... Con mieles y no con hieles me la han de engatusar á usté... Un cariñiyo me vasté á tener mu guardadico en su pechito y no lo ae sabé ni la tierra, que secretica me es usté como la piedra e la sepultura... También una cosa le igo y es que usté mesma no me sabe lo que en ese corasonsiyo está guardao... Un cachito e gloria le va a caer der sielo y pasmáa se quedará usté; que á la presente me está usté como los pajariyos, que no saben el árbol onde han de ponerse...\"},{\"heading\":false,\"text\":\"Si la dejamos, creo que aún sigue ahora ensartando tonterías. A mí su parla me entretenía mucho, pues ya se sabe que en esta clase de vaticinios tan confusos y tan latos, siempre hay algo que responde á nuestras ideas, esperanzas y aspiraciones ocultas. Es lo mismo que cuando, al tiempo de jugar á los naipes, vamos corriéndolos para descubrir sólo la pinta, y adivinamos ó presentimos de un modo vago la carta que va á salir. Pacheco me miraba atentamente, aguardando á que me cansase de gitanerías para despedir á la profetisa. Viendo que ya la chica del puñal en el moño acudía con la fuente de huevos revueltos, solté la mano, y mi acompañante despachó á la gitana, que antes de poner piés en polvorosa aún pidió no sé qué para _er churumbeliyo_.\"},{\"heading\":false,\"text\":\"Empezábamos á servirnos del apetitoso comistrajo y á descorchar una botella de jerez, cuando otro cuerpo asomó en la abertura de la tienda, se adelantó hacia la mesa y recitó la consabida jaculatoria:\"},{\"heading\":false,\"text\":\"--En er nombre e Dió Pare, Jijo y Epíritu Zanto, que onde va er nombre é Dió...\"},{\"heading\":false,\"text\":\"--¡Estamos frescos!--gritó Pacheco.--¡Gitana nueva!\"},{\"heading\":false,\"text\":\"--Claro--murmuró con aristocrático desdén la chica del merendero.--Como á la otra le han dado cuartos y vino, se ha corrido la voz... Y tendrán aquí á todas las de la romería.\"},{\"heading\":false,\"text\":\"Pacheco alargó á la recién venida unas monedas y un vaso de jerez.\"},{\"heading\":false,\"text\":\"--Bébase usté eso á mi salú..., y andar con Dios, y najensia.\"},{\"heading\":false,\"text\":\"--E que les igo yo lo buenaventura e barde... por el aqué de la sal der mundo que van ustés derramando.\"},{\"heading\":false,\"text\":\"--No, no...,--exclamé yo casi al oído de Pacheco.--Nos va á encajar lo mismo que la otra; con una vez basta. Espántela V.... sin reñirla.\"},{\"heading\":false,\"text\":\"--Bébase usté el jerés, prenda... y najarse he dicho--ordenó el gaditano sin enojo alguno, con campechana franqueza.\"},{\"heading\":false,\"text\":\"La gitana, convencida de que no sacaba más raja ya, después de echarse al coleto el Jerez y limpiarse la boca con el dorso de la mano, se largó con su indispensable _churumbeliyo_, que lo traía también escondido en el mantón como gusano en queso.\"},{\"heading\":false,\"text\":\"--¿Tienen todas su chiquitín?--pregunté á la muchacha.\"},{\"heading\":false,\"text\":\"--Todas, pues ya se ve--explicó ella con tono de persona desengañada y experta.--Valientes maulas están. Los chiquillos son tan suyos como de una servidora de Vds. Infelices, los alquilan por ahí á otras bribonas, y sabe Dios el trato que les dan. Y está la romería plagada de estas tunantas, embusteronas. ¡Lástima de Abanico!\"},{\"heading\":false,\"text\":\"--¿Vds. duermen aquí?--la dije por tirarla de la lengua.--¿No tienen miedo á que de noche les roben las ganancias del día ó la comida del siguiente?\"},{\"heading\":false,\"text\":\"--Ya se ve que dormimos con un ojo cerrado y otro abierto... Porque no se crea V.: nosotros tenemos un café á la salida de la Plaza Mayor y venimos aquí no más á poner el ambigú.\"},{\"heading\":false,\"text\":\"Comprendí que la chica se daba importancia, deseando probarme que era, socialmente, muy superior á aquella gentecilla de poco más ó menos que andaba por los demás figones. A todo esto íbamos despachando la ración de huevos revueltos y nos disponíamos á emprenderla con las magras. Interceptó la claridad de la abertura otra sombra. Esta era una chula de mantón terciado, peina de bolas, brazos desnudos, que traía en un jarro de loza un inmenso haz de rosas y claveles, murmurando con voz entre zalamera y dolorida:--«¡Señoritico! ¡Cómpreme usté flores pa osequiar á esa buena moza!»--Al mismo tiempo que la florera, entraron en el merendero cuatro soldados, cuatro húsares jóvenes y muy bulliciosos, que tomaron posesión de una mesa pidiendo cerveza y gaseosa, metiendo ruido con los sables y regocijando la vista con su uniforme amarillo y azul. ¡Válgame Dios, y qué virtud tan rara poseen la manzanilla y el jerez, sobre todo cuando están encabezados y compuestos! Si en otra ocasión me veo yo almorzando así, entre soldados, creo que me da un soponcio; pero empezaba á tener subvertidas las nociones de la corrección y de la jerarquía social, y hasta me hizo gracia semejante compañía y la celebré con la risa más alegre del mundo! Pacheco, al observar mi buen humor, se levantó y fué á ofrecer á los húsares jerez y otros obsequios; de suerte que no sólo comíamos con ellos en el mismo bodegón, sino que fraternizábamos.\"},{\"heading\":false,\"text\":\"Cuando está uno de buen temple, ninguna cosa le disgusta. Alabé la comida; de la chula de los claveles dije que parecía un boceto de Sala; y entonces Pacheco sacó de la jarra las flores y me las echó en el regazo, diciendo:--«Póngaselas V. todas.»--Así lo ejecuté, y quedó mi pecho convertido en búcaro. Luego me hizo reir con toda mi alma una desvergonzada riña que se oyó por detrás de la pared de lona, y las ocurrencias de Pacheco que se lió con los húsares no recuerdo con qué motivo. Volvió á nublarse el sol que entraba por la abertura y apareció un pordiosero de lo más remendado y haraposo. No contento con aflojar buena limosna, Pacheco le dió palique largo, y el mendigo nos contó aventuras de su vida: una sarta de embustes, por supuesto. Oyóle el gaditano muy atentamente, y luego empezó á exigirle que trajese un guitarrillo y se cantase por lo más jondo. El pobre juraba y perjuraba que no sabía sino unas coplillas, pero sin música, y al fin le soltamos, bajo palabra de que nos traería un buen cantaor y tocaor de bandurria para que nos echase polos y peteneras hasta morir. Por fortuna hizo la del humo.\"},{\"heading\":false,\"text\":\"Yo, á todo esto, más divertida que en un sainete, y dispuesta á entenderme con las chuletas y el champagne. Comprendía, sí, que mis pupilas destellaban lumbre y en mis mejillas se podía encender un fósforo; pero lejos de percibir el atolondramiento que suponía precursor de la embriaguez, sólo experimentaba una animación agradabilísima, con la lengua suelta, los sentidos excitados, el espíritu en volandas y gozoso el corazón. Lo que más me probaba que _aquello_ no era cosa alarmante, era que comprendía la necesidad de guardar en mis dichos y modales cierta reserva de buen gusto; y en efecto, la guardaba, evitando toda palabra ó movimiento que siendo inocente pudiese parecer equívoco, sin dejar por eso de reir, de elogiar los guisos, de mostrarme jovial, en armonía con la situación... Porque allí, vamos, convengan Vds. en ello, también sería muy raro estar como si me hubiese tragado el molinillo.\"}]},{\"title\":\"Insolación — capítulo VI\",\"blocks\":[{\"heading\":false,\"text\":\"Pacheco, por su parte, me llevaba la corriente; cuidaba de que nunca estuviesen vacíos mi vaso ni mi plato, y ajustaba su humor al mío con tal esmero, cual si fuese un director de escena encargado de entretener y hacer pasar el mejor rato posible á un príncipe. ¡Ay! Porque eso sí: tengo que rendirle justicia al grandísimo socarrón, y una vez que me encuentro á solas con mi conciencia, reconocer que, animado, oportuno, bromista y (admitamos la terrible palabra) en _juerga_ redonda conmigo, como se encontraba al fin y al cabo Pacheco, ni un dicho libre, ni una acción descompuesta ó siquiera familiar llegó á permitirse. En ocasión tan singular y crítica, hubiera sido descortesía y atrevimiento lo que en otra mero galanteo ó _flirtación_ (como dicen los ingleses). Esto lo entendía yo muy bien, aun entonces, y á la verdad, temía cualquiera de esas insinuaciones impertinentes que dejan á una mujer volada y le estropean el mejor rato. Sin la caballerosa delicadeza de Pacheco, aquella situación en que impremeditadamente me había colocado pudo ser muy ridícula para mí. Pero la verdad por delante: su miramiento fué tal, que no me echó ni una flor, mientras hartaba de lindas, simpáticas y retrecheras á las gitanas, á la chica del puñal de níquel y hasta á la fregona del estropajo. Cierto que á veces sorprendí sus ojos azules que me devoraban á hurtadillas; sólo que apenas notaba que yo había caído en la cuenta, los desviaba á escape. Su acento era respetuoso, sus frases serias y sencillas al dirigirse sólo á mi. Ahora se me figura que tantas exquisiteces fueron calculadas, para inspirarme confianza é interés: ¡ah malvado! Y bien que me iba comprando con aquel porte fino.\"},{\"heading\":false,\"text\":\"Surgió de repente ante nosotros, sin que supiésemos por donde había entrado, una figurilla color de yesca, una gitanuela de algunos trece años, típica, de encargo para modelo de un pintor: el pelo azulado de puro negro, muy aceitoso, recogido en castaña, con su peina de cuerno y su clavel sangre de toro; los dientes y los ojos brillantes, por contraste con lo atezado de la cara; la frente chata como la de una víbora, y los brazos desnudos, verdosos y flacos lo mismo que dos reptiles. Y con el propio tonillo desgarrado de las demás, empezó la retahila consabida:\"},{\"heading\":false,\"text\":\"--En er nombre de Dió Pare, Jijo...\"},{\"heading\":false,\"text\":\"De esta vez, la chica del merendero montó en cólera, y dando al diablo sus pujos de señorita, se convirtió en chula de las más boquifrescas.\"},{\"heading\":false,\"text\":\"--¿Hase visto hato de pindongas? ¿No dejarán comer en paz á las personas decentes? ¿Conque las barre uno por un lado y se cuelan por otro? ¿Y cómo habrá entrado aquí semejante calamidá, digo yo? Pues si no te largas más pronto que la luz, bofetá como la que te arrimo no la has visto tú en tu vía. Te doy un recorrío al cuerpo, que no te queda lengua pa contarlo.\"},{\"heading\":false,\"text\":\"La chiquilla huyó más lista que un cohete; pero no habrían transcurrido dos segundos, cuando vimos entreabrirse la lona que nos protegía las espaldas, y por la rendija del lienzo asomó una geta que parecía la del mismo enemigo, unos dientes que rechinaban, un puño cerrado, negro como una bola de bronce, y la gitanilla becerreó:\"},{\"heading\":false,\"text\":\"--Arrastrá, condená, tía cochina, que malos retortijones te arranquen las tripas, y malos mengues te jagan picaíllo e los jígados, y malas culebras te piquen, y remardita tiña te pegue con er moño pa que te quedes pelá como tu ifunta agüela...\"},{\"heading\":false,\"text\":\"Llegaba aquí de su rosario de maldiciones, cuando la del puñal, que así se vió tratada, empuñó el rabo de una cacerola y se arrojó como una fiera á descalabrar á la egipcia: al hacerlo, dió con el codo a una botella de jerez, que se derramó entera por el mantel. Este incidente hizo que la chica, olvidando el enojo, se echase á reir exclamando:--¡Alegría, alegría! Vino en el mantel... ¡boda segura!--y, por supuesto, la gitana tuvo tiempo de afufarse más pronta que un pájaro.\"},{\"heading\":false,\"text\":\"No ocurrió durante el almuerzo ninguna otra cosa que recordarse merezca, y lo bien que hago memoria de todo cuanto pasó en él, me prueba que estaba muy despejada y muy sobre mí. Apuramos el último sorbo de champagne y un empecatado café; saldó Pacheco la cuenta, gratificando como Dios manda, y nos levantamos con ánimo de recorrer la romería. Notaba yo cierta ligereza insólita en piernas y piés; me figuraba que se había suprimido el peso de mi cuerpo, y, en vez de andar, creía deslizarme sobre la tierra.\"},{\"heading\":false,\"text\":\"Al salir, me deslumbró el sol: ya no estaba en el cenit ni mucho menos; pero era la hora en que sus rayos, aunque oblicuos, queman más: debían de ser las tres y media ó cuatro de la tarde, y el suelo se rajaba de calor. Gente, triple que por la mañana, y veinte veces más bullanguera y estrepitosa. Al punto que nos metimos entre aquel bureo, se me puso cabeza que me había caído en el mar: mar caliente, que hervía á borbotones, y en el cual flotaba yo dentro de un botecillo chico como una cáscara de nuez: golpe va y golpe viene, ola arriba y ola abajo. ¡Sí, era el mar; no cabía duda! ¡El mar, con toda la angustia y desconsuelo del mareo que empieza!\"},{\"heading\":false,\"text\":\"Lejos de disiparse esta aprensión, se aumentaba mientras iba internándome en la romería apoyada en el brazo del gaditano. Nada, señores, que estaba en mitad del golfo. Los innumerables ruidos de voces, disputas, coplas, pregones, juramentos, vihuelas, organillos, pianos, se confundían en un rumor nada más: el mugido sordo con que el Océano se estrella en los arrecifes: y allá á lo lejos, los columpios, lanzados al aire con vuelo vertiginoso, me representaban lanchas y falúas balanceadas por el oleaje. ¡Ay Dios mío, y qué desvanecimiento me entró al convencerme de que en efecto me encontraba en alta mar! Me agarré al brazo de Pacheco como me agarro en la temporada de baños al cuello del bañero robusto, para que no me lleve el agua... Sentía un pánico atroz y no me atrevía á confesarlo, porque tal vez mi acompañante se reiría de mí, por fuera ó por dentro, si le dijese que me mareaba, que me mareaba á toda prisa.\"},{\"heading\":false,\"text\":\"Una peripecia nos detuvo breves instantes. Fué una pelea de mujerotas. Pelea muy rara: por lo regular, estas riñas van acompañadas de vociferaciones, de chillidos, de injurias, y aquí no hubo nada de eso. Eran dos mozas: una que tostaba garbanzos en una sartén puesta sobre una hornilla: otra que pasó y con las sayas derribó el artilugio. Jamás he visto en rostro humano expresión de ferocidad como adquirió el de la tostadora. Más pronta que el rayo, recogió del suelo la sartén, y echándose á manera de irritada tigre sobre la autora del desaguisado, le dió con el filo en mitad de la cara. La agredida se volvió sin exhalar un ay, corriéndole de la ceja á la mejilla un hilo de sangre; y trincando á su enemiga por el moño, del primer arrechucho le arrancó un buen mechón, mientras le clavaba en el pescuezo las uñas de la mano izquierda: cayeron á tierra las dos amazonas, rodando entre trébedes, hornillas y cazos; se formó alrededor corro de mirones, sin que nadie pensase en separarlas, y ellas seguían luchando, calladas y pálidas como muertas, una con la oreja rasgada ya, otra con la sien toda ensangrentada y un ojo medio saltado de un puñetazo. Los soldados se reían á carcajadas y les decían requiebros indecentes, en tanto que se despedazaban las infelices. Advertí por un instante que se me quitaba el mareo, á fuerza de repugnancia y lástima: me acordé de mi paisano Pardo, y de aquello del salvajismo y la barbarie española. Pero duró poco esta idea, porque en seguidita se me ocurrió otra muy singular: que las dos combatientes eran dos pescados grandes, así como golfines ó tiburones, y que á coletazos y mordiscos, sin chistar, estaban haciéndose trizas. Y este pensamiento me renovó la fatiga del mareo de tal modo, que arrastré á Pacheco.\"},{\"heading\":false,\"text\":\"--Vámonos de aquí... No me gusta ver esto... Se matan.\"},{\"heading\":false,\"text\":\"Preguntóme Don Diego si me sentía mal, en cuyo caso no visitaríamos los barracones donde enseñan panoramas y fenómenos. Respondí muy picada que me encontraba perfectamente y capaz de examinar todas las curiosidades de la romería. Entramos en varias barracas y vimos un enano, un ternero de dos cabezas, y por último, la mujer de cuatro piernas, muy pizpireta, muy escotada, muy vestida de seda azul con puntillas de algodón, y que enseñaba sonriendo--la risa del conejo--sus dobles muñones al extremo de cada rodilla. En esta pícara barraca se apoderó de mí, con más fuerza que nunca, la convicción de que me hallaba en alta mar, entregada á los vaivenes del Océano. En el lado izquierdo del barracón había una serie de agujeritos redondos por donde se veía un cosmorama: y yo empeñada en que eran las portas del buque, sin que me sacase de mi error el que al través de las susodichas portas se divisase, en vez del mar, la plaza del Carrousel... el Arco de la Estrella... el Coliseo de Roma... y otros monumentos análogos. Las perspectivas arquitectónicas me parecían desdibujadas y confusas, con gran temblequeteo y vaguedad de contornos, lo mismo que si las cubriese el trémulo velo de las olas. Al volverme y fijarme en el costado opuesto de la barraca, los grandes espejos de _rigolada_, de lunas cóncavas ó convexas, que reflejaban mi figura con líneas grotescamente deformes, me parecieron también charcos de agua de mar... ¡Ay, ay, ay, qué malo se pone esto! Un terror espantoso cruzó por mi mente: ¿apostemos á que todas estas chifladuras marítimas y náuticas son pura y simplemente una... vamos, una _filoxerita_, como ahora dicen? ¡Pero si he bebido poco! ¡Si en la mesa me encontraba tan bien!\"},{\"heading\":false,\"text\":\"--Hay que disimular--pensé.--Que Pacheco no se entere... ¡Virgen, y qué vergüenza si lo nota!... Volver á Madrid corriendo... ¡Quiá! El movimiento del coche me pierde, me acaba, de seguro... Aire, aire... ¡Si hubiese un rincón donde librarse de este gentío!\"},{\"heading\":false,\"text\":\"O Pacheco leyó en mis pensamientos, ó coincidió conmigo en sensaciones, pues se inclinó y en el tono más cariñoso y deferente murmuró á mi oído:\"},{\"heading\":false,\"text\":\"--Hace aquí un calor intolerable... ¿Verdad que sí? ¿Quiere V. que salgamos? Daremos una vueltecita por la pradera y la alameda; estará más despejado y más fresco.\"},{\"heading\":false,\"text\":\"--Vamos--respondí fingiendo indiferencia, aunque veía el cielo abierto con la proposición.\"}]},{\"title\":\"Insolación — capítulo VII\",\"blocks\":[{\"heading\":false,\"text\":\"Salimos de la barraca y bajamos del cerro á la alameda, siempre empujados y azotados por la ola del gentío, cuyas aguas eran más densas según iba acercándose la noche. Llegó un momento en que nos encontramos presos en remolino tal, que Pacheco me apretó fuertemente el brazo y tiró de mí para sacarme á flote. Me latían las sienes, se me encogía el corazón y se me nublaban los ojos: no sabía lo que me pasaba: un sudor frío bañaba mi frente. Forcejeábamos deseando romper por entre el grupo, cuando nos paró en firme una cosa tremenda que se apareció allí, enteramente á nuestro lado: un par de navajas desnudas, de esas _lenguas de vaca_ con su letrero de _si esta víbora te pica no hay remedio en la botica_, volando por los aires en busca de las tripas de algún prójimo. También relucían machetes de soldados, y se enarbolaban garrotes, y se oían palabras soeces, blasfemias de las más horribles... Me arrimé despavorida al gaditano, el cual me dijo á media voz:\"},{\"heading\":false,\"text\":\"--Por aquí... No pase V. cuidado... Vengo prevenido.\"},{\"heading\":false,\"text\":\"Le vi meter la mano en el bolsillo derecho del chaleco y asomarse á él la culata de un revólver: vista que redobló mi susto y mis esfuerzos para desviarme. No nos fué difícil, porque todo el mundo se arremolinaba en sentido contrario, hacia el lugar de la pendencia. Pronto retrocedimos hasta la alameda, sitio relativamente despejado. Allí y todo continuaban mis ilusiones marítimas dándome guerra. Los carruajes, los carros de violín, los ómnibus, las galeras, cuantos vehículos estaban en espera de sus dueños, me parecían á mí embarcaciones fondeadas en alguna bahía ó varadas en la playa, paquetes de vapor con sus ruedas, quechemarines con su arboladura. Hasta olor á carbón de piedra y á brea notaba yo. Que sí, que me había dado por la náutica.\"},{\"heading\":false,\"text\":\"--¿Vámonos á la orilla... allí, donde haya silencio?--supliqué á Pacheco.--¿Donde corra fresquito y no se vea un alma? Porque la gente me mar...\"},{\"heading\":false,\"text\":\"Un resto de cautela me contuvo á tiempo, y rectifiqué:\"},{\"heading\":false,\"text\":\"--Me fatiga.\"},{\"heading\":false,\"text\":\"--¿Sin gente? Dificilillo va á ser hoy... Mire V.--Y Pacheco señaló, extendiendo la mano.\"},{\"heading\":false,\"text\":\"Por la praderita verde, por las alturas peladas del cerro, por cuanta extensión de tierra registrábamos desde allí, bullía el mismo hormigueo de personas, igual confusión de colorines, balanceo de columpios, girar de tíos vivos y corros de baile.\"},{\"heading\":false,\"text\":\"--Hacia allá--murmuré--parece que hay un espacio libre...\"},{\"heading\":false,\"text\":\"Para llegar adonde yo indicaba, era preciso saltar un vallado, bastante alto por más señas. Pacheco lo salvó, y desde el lado opuesto me tendió los brazos. ¡Cosa más particular! Pegué el brinco con agilidad sorprendente. Ni notaba el peso de mi cuerpo; se había derogado para mí la ley de gravedad: creo que podría hacer volatines. Eso sí, la firmeza no estaba en proporción con la agilidad, porque si me empujan con un dedo, me caigo y boto como una pelota.\"},{\"heading\":false,\"text\":\"Atravesamos un barbecho, que fué una serie de saltos de surco á surco, y por senderos realmente solitarios fuimos á parar á la puerta de una casuca que se bañaba los piés en el Manzanares. ¡Ay, qué descanso! Verse uno allí casi solo, sin oir apenas el estrépito de la romería, con un fresquito delicioso venido de la superficie del agua, y con la media obscuridad ó al menos la luz tibia del sol que iba poniéndose... ¡Alabado sea Dios! Allá queda el tempestuoso Océano con sus olas bramadoras, sus espumarajos y sus arrecifes, y héteme al borde de una pacífica ensenada, donde el agua sólo tiene un rizado de onditas muy mansas que vienen á morir en la arena sin meterse con nadie...\"},{\"heading\":false,\"text\":\"¡Dale con el mar! ¡Mire V. que es fuerte cosa! ¿Si continuará aquello? ¿Si...?\"},{\"heading\":false,\"text\":\"A la puerta de la casuca asomó una mujer pobremente vestida y dos chiquillos harapientos, que muy obsequiosos me sacaron una silla. Sentóse Pacheco á mi lado sobre unos troncos. Noté bienestar inexplicable, y me puse á mirar cómo se acostaba el sol, todo ardoroso y sofocado, destellando sus últimos resplandores en el Manzanares. Es decir, en el Manzanares no: aquello se parecía extraordinariamente á la bahía viguesa. La casa también se había vuelto una lancha muy airosa que se mecía con movimiento insensible: Pacheco, sentado en la popa, oprimía contra el pecho la caña del timón, y yo, muellemente reclinada á su lado, apoyaba un codo en su rodilla, recostaba la cabeza en su hombro, cerraba los ojos para mejor gozar del soplo de la brisa marina que me abanicaba el semblante... ¡Ay madre mía, qué bien se va así!... De aquí al cielo...\"},{\"heading\":false,\"text\":\"Abrí los párpados... ¡Jesús, qué atrocidad! Estaba en la misma postura que he descrito, y Pacheco me sostenía en silencio y con exquisito cuidado, como á una criatura enferma, mientras me hacía aire, muy despacio, con mi propio pericón...\"},{\"heading\":false,\"text\":\"No tuve tiempo de reflexionar en situación tan rara. No me lo permitió el afán, la fatiga inexplicable que me entró de súbito. Era como si me tirasen del estómago y de las entrañas hacia afuera con un garfio para arrancármelas por la boca. Llevé las manos á la garganta y al pecho, y gemí:\"},{\"heading\":false,\"text\":\"--¡A tierra, á tierra! ¡Que se pare el vapor... me mareo, me mareo! ¡Que me muero!... ¡Por la Virgen, á tierra!\"},{\"heading\":false,\"text\":\"Cesé de ver la bahía, el mar verde y espumoso, las crespas olitas; cesé de sentir el soplo del Nordeste y el olor del alquitrán... Percibí, como entre sueños, que me levantaban en vilo y me trasladaban... ¿Estaríamos desembarcando? Entreoí frases que para mí entonces carecían de sentido.--«Probetica, sa puesto mala.--Por aquí, señorito...--Sí que hay cama y lo que se nesecite...--Mandar...»--Sin duda ya me habían depositado en tierra firme, pues noté un consuelo grandísimo, y luego una sensación inexplicable de desahogo, como si alguna manaza gigantesca rompiese un aro de hierro que me estaba comprimiendo las costillas y dificultando la respiración. Di un suspiro y abrí los ojos...\"},{\"heading\":false,\"text\":\"Fué un intervalo lúcido, de esos que se tienen aun en medio del síncope ó del acceso de locura, y en que comprendí claramente todo cuanto me sucedía. No había mar, ni barco, ni tales carneros, sino turca de padre y muy señor mío: la tierra firme era el camastro de la tabernera, el aro de hierro el corsé que acababan de aflojarme; y no me quedé muerta de sonrojo allí mismo, porque no vi en el cuarto á Pacheco. Sólo la mujer morena y alta, muy afable, se deshacía en cuidados, me ofrecía toda clase de socorros...\"},{\"heading\":false,\"text\":\"--No, gracias... Silencio, y estar á obscuras... Es lo único... Bien, sí, llamaré si ocurre. Ya, ya me siento mejor... Silencio y dormir; no necesito más.\"},{\"heading\":false,\"text\":\"La mujer entornó el ventanuco por donde entraba en el chiribitil la luz del sol poniente, y se marchó en puntillas. Me quedé sola: me dominaba una modorra invencible: no podía mover brazo ni pierna; sin embargo, la cabeza y el corazón se me iban sosegando por efecto de la penumbra y la soledad. Cierto que andaba otra vez á vueltas con la manía náutica, pues pensaba para mis adentros:--¡Qué bien me encuentro así... en este camarote... en esta litera!... ¡Y qué serena debe de estar la mar!... ¡Ni chispa de balance! ¡El barco no se mueve!\"},{\"heading\":false,\"text\":\"Yo había oído asegurar muchas veces que si tenemos los ojos cerrados y alguna persona se pone á mirarnos fijamente, una fuerza inexplicable nos obliga á abrirlos. Digo que es verdad, y lo digo por experiencia. En medio de mi sopor empecé á sentir cierta comezón de alzar los párpados y una inquietud especial, que me indicaba la presencia de _alguien_ en el tugurio... Entreabrí los ojos, y con gran sorpresa vi el agua del mar; pero no la verde y plomiza del Cantábrico, sino la del Mediterráneo, azul y tranquila... Las pupilas de Pacheco, como Vds. se habrán imaginado. Estaba de pié, y cuando clavé en él la mirada, se inclinó y me arregló delicadamente la falda del vestido para que me cubriese los piés.\"},{\"heading\":false,\"text\":\"--¿Cómo vamos? ¿Hay ánimos para levantarse?--murmuró: es decir, sería algo por el estilo, pues no me atrevo á jurar que dijese esto. Lo que afirmo es que le tendí las dos manos con un cariñazo repentino y descomunal, porque se me había puesto en el moño que me encontraba allí abandonadita en medio de un golfo profundo, y que iba á ahogarme si no acierta á venir en mi auxilio Pacheco. El tomó las manos que yo ofrecía, las apretó muy afectuoso, me tentó los pulsos y apoyó su derecha en mis sienes y frente, ¡Cuánto bien me hacía aquella presioncita cuidadosa y firme! Como si me volviese á encajar los goznes del cerebro en su verdadero sitio, dándoles aceite para que girasen mejor. Le estreché la mano izquierda... ¡Qué pegajoso, qué majadero se vuelve uno en estas situaciones... anormales! Yo me estaba muriendo por mimos, igual que una niña pequeña... ¡Quería que me tuviesen lástima!... Es sabido que á mucha gente le dan las turcas por el lado tierno. Ganas me venían de echarme á llorar, por el gusto de que me consolasen.\"},{\"heading\":false,\"text\":\"Había á la cabecera de la cama una mugrienta silla de Vitoria, y el gaditano tomó asiento en ella acercando su cara á la dura almohada donde reclinaba la mía. No sé qué me fué diciendo por lo bajo: sí que eran cositas muy dulces y zalameras, y que yo seguía estrujándole la mano izquierda con fuerza convulsiva, sonriendo y entornando los párpados, porque me parecía que de nuevo bogábamos en el esquife, y las olas hacían un _¡clap! ¡clap!_ armonioso contra el costado. Sentí en la mejilla un soplo caliente, y luego un contacto parecido al revoloteo de una mariposa. Sonaron pasos fuertes, abrí los ojos, y vi á la mujer alta y morena, figonera, tabernera ó lo que fuese.\"},{\"heading\":false,\"text\":\"--¿La traigo una tacita de té, señorita? Lo tengo mu bueno, no se piensen ustés que no... Se le pué echar unas gotas de ron, si les parece...\"},{\"heading\":false,\"text\":\"--¡No, ron no!--articulé muy quejumbrosa, como si pidiese que no me mataran.\"},{\"heading\":false,\"text\":\"--¡Sin ron... y calentito!--mandó Pacheco.\"},{\"heading\":false,\"text\":\"La mujer salió. Cerré otra vez los ojos. Me zumbaban los sesos: ni que tuviese en ellos un enjambre de abejas. Pacheco seguía apretándome las sienes, lo cual me aliviaba mucho. También noté que me esponjaba la almohada, que me alisaba el pelo. Todo de una manera tan insensible, como si una brisa marina muy mansa me jugase con los rizos. Volvieron á oirse los pasos y el duro taconeo.\"},{\"heading\":false,\"text\":\"--El té, señorito... ¿Se lo quié usté dar ó se lo doy yo?\"},{\"heading\":false,\"text\":\"--Venga--exclamó el meridional.\"},{\"heading\":false,\"text\":\"Le sentí revolver con la cucharilla y que me la introducía entre los labios. Al primer sorbo me fatigó el esfuerzo y dije _que no_ con la cabeza; al segundo me incorporé de golpe, tropecé con la taza, y ¡zas! el contenido se derramó por el chaleco y pantalón de mi enfermero. El cual, con la insolencia más grande que cabe en persona humana, me preguntó:\"},{\"heading\":false,\"text\":\"--¿No lo quieres ya? ¿O te pido otra tacita?\"},{\"heading\":false,\"text\":\"Y yo... ¡Dios de bondad! ¡De esto sí que estoy segura! le contesté empleando el mismo tuteo y muy mansa y babosa:\"},{\"heading\":false,\"text\":\"--No, no pidas más... Se hace noche... Hay que salir de aquí... Veremos si puedo levantarme. ¡Qué mareo, Señor, qué mareo!\"},{\"heading\":false,\"text\":\"Tendí los brazos confiadamente: el malvado me recibió en los suyos, y agarrada á su cuello, probé á saltar del camastro. Con el mayor recato y comedimiento, Pacheco me ayudó á abrocharme, estiró las guarniciones de mi saya de surá, me presentó el imperdible, el sombrero, el velito, el agujón, el abanico y los guantes. No se veía casi nada, y yo lo atribuía á la mezquindad del cuchitril; pero así que, sostenida por Pacheco y andando muy despacio, salí á la puerta del figón, pude convencerme de que la noche había cerrado del todo. Allá á lo lejos, detrás del muro que cercaba el campo, hormigueaba confusamente la romería, salpicada de lucecillas bailadoras, innumerables...\"},{\"heading\":false,\"text\":\"La calma de la noche y el aire exterior me produjeron el efecto de una ducha de agua fría. Sentí que la cabeza se me despejaba y que así como se va la espuma por el cuello de la botella de champagne, se escapaban de mi mollera en burbujas el sol abrasador y los espíritus alcohólicos del endiablado vino compuesto. Eso sí: en lugar de meollo me parecía que me quedaba un sitio hueco, vacío, barrido con escoba... Encontrábame aniquilada, en el más completo idiotismo.\"},{\"heading\":false,\"text\":\"Pacheco me guiaba sin decir oxte ni moxte. Derechos como una flecha fuimos adonde mi coche aguardaba ya. Sus dos faroles lucían á la entrada de la alameda, en el mismo sitio en que por la mañana le mandáramos esperar. Entré y me dejé caer en el asiento, medio exánime. Pacheco me siguió, dió una orden, y la berlina empezó á rodar poco á poco.\"},{\"heading\":false,\"text\":\"¡Ay Dios de mi vida! ¿Quién soñó que se habían acabado ya los barcos, el oleaje, mis fantasías marítimas todas? ¡Pues si ahora es cuando navegábamos de veras, encerrados en el camarote de un trasatlántico, y á cada tres segundos cuchareaba el buque ó cabeceaba bajando á los abismos del mar y arrastrándome consigo! La voz de Pacheco no era tal voz, sino el ruido del viento en las jarcias... ¡Nada, nada, que hoy naufrago!\"},{\"heading\":false,\"text\":\"--¡Vas disgustá conmigo?--gemía á mi oído el sudoeste. No vayas. Mira, bien callé y bien prudente fuí... Hasta que me apretaste la mano... Perdón, sielo, me da una pena verte afligía... Es una rareza en mí, pero estoy así como aturdido de pensar si te enfadarás por lo que te dije... Pobrecita, no sabes lo guapa que estabas mareá... Los ojos tuyos echaban lumbre... ¡Vaya unos ojos que tienes tú! Anda, descansa así, en el hombro mío. Duerme, niñita, duerme...\"},{\"heading\":false,\"text\":\"Tal vez equivoque yo las palabras, porque resultaban un murmullo y no más... Lo que sí recuerdo con absoluta exactitud es esta frase, que sin duda cayó en el intervalo de una ola á otra:\"},{\"heading\":false,\"text\":\"--¿Sabes qué decían en aquel figón? Pues que debíamos de ser recién casados..., «porque él la trata con mucho cariño y no sabe qué hacer para cuidarla.»\"},{\"heading\":false,\"text\":\"Y puedo jurar que no me acuerdo de ninguna cosa más; de ninguna. Sí..., pero muy vagamente: que el coche se detuvo á mi puerta, y que por las escaleras me ayudó á subir Pacheco, y que desfallecida y atónita como me encontraba, le rogué que no entrase, sin duda obedeciendo á un instinto de precaución. No sé lo que me dijo al despedirse; sé que la despedida fué rápida y sosa. A la Diabla, que al abrir me incrustó en la cara su curioso mirar, le expliqué tartamudeando que me había hecho daño el sol, que deseaba acostarme. Claro que se habrá comido la partida... Sí, que se mama ella el dedo... ¡Buenas cosas pensará á estas horas de mí!\"},{\"heading\":false,\"text\":\"Me precipité á mi cuarto, me eché en la cama, me puse de cara á la pared, y aunque al pronto volví á amodorrarme, hacia las tres de la madrugada empezó la función y se renovó mi padecimiento. No quise llamar á Angela... ¡Para que se escamase tres veces más! ¡Ay qué noche... noche de perros! ¡Qué bascas, qué calentura, qué pesadillas, que aturdimiento, qué jaqueca al despertar!\"},{\"heading\":false,\"text\":\"Y sobre todo, ¡qué compromiso, qué lance, qué parchazo! ¡Qué lío tan espantoso!... ¡Qué resbalón! (ya es preciso convenir en ello).\"}]},{\"title\":\"Insolación — capítulo VIII\",\"blocks\":[{\"heading\":false,\"text\":\"Convengamos; pero también en que Pacheco, habiéndose portado tan correctamente al principio, no debió luego echarla á perder. Si yo, por culpa de las circunstancias--eso es, de las circunstancias inesperadísimas en que me he visto,--pude darle algún pié, á la verdad, ningún caballero se aprovecha de ocasiones semejantes; al contrario, en ellas debe manifestar su educación, si la tiene. Yo me trastorné completamente, por lo mismo que nunca anduve en pasos como éstos; yo no estaba en mi cabal juicio, no señor; yo no tenía responsabilidad, y él, el grandísimo pillo, tan sereno como si le acabasen de enfriar en el pozo... Lo dicho: ¡fué una osadía, una serranada incalificable!\"},{\"heading\":false,\"text\":\"Cuanto más lo pienso... ¡Un hombre que hace veinticuatro horas no había cruzado conmigo media docena de palabras; un hombre que ni siquiera es visita mía! Cierta heroína de novela, de las que yo leía siendo muchacha, en un caso así recuerdo que empezó á devanarse los sesos preguntándose á sí propia: «¿Le amo?» ¡Valiente tontería la de aquella simple! ¡Qué amor ni qué!... Caso de preguntar, yo me preguntaría: «¿Le conozco á este caballero?» Porque maldito si sé hasta ni cómo se llama de segundo apellido... Lo que sé es que le detesto y le juzgo un pillastre. Motivos tengo sobrados. ¡Que se ponga en mi caso cualquiera!\"},{\"heading\":false,\"text\":\"Y ahora... Supongamos que, naturalmente, cuando él aporte por aquí, me cierro á la banda y doy orden terminante á los criados: que he salido. Se pondrá furioso, y lo menos que hará, con el despecho, irse alabando en casa de Sahagún... Porque de fijo es uno de esos tipos que pegan carteles en las esquinas... ¡Como si lo viera! Y resistir que se me presente tan fresco... vamos, es de lo que no pasa. Una, que me daría un sofoco de primera; otra, que en estas cosas, si no se empieza cortando por lo sano... Me parece lo más natural. Me niego... y se acabó. Escribirá... Bien, no contesto. Y dentro de unos días, como ya salgo de Madrid... Sí, todo se arregla.\"},{\"heading\":false,\"text\":\"Y... á sangre fría, Asís... ¿Es ese descarado quien tiene la culpa toda? Vamos, hija, que tú... ¿Quién te mandaba satisfacer el caprichito de ir al Santo y de acompañarte con una persona casi desconocida, y de almorzar allí en un merendero churri, como si fueses una salchichera de los barrios bajos? ¿Por qué probaste del vino aquel, que está encabezado con el _amílico_ más venenoso? ¿No sabías que, aun sin vino, á ti el sol te marea?\"},{\"heading\":false,\"text\":\"Te dejaste embarcar por la Sahagún... Pero la Sahagún... Para ciertas personas no rigen las ordenanzas sociales. La Sahagún, no sólo es muy experta, y muy despabilada, y discretísima, y una de esas mujeres á quienes nadie se les atreve no queriendo ellas, sino que con su alta posición convierte en excentricidad graciosa é inofensiva lo que en las demás se toma por desvergüenza y liviandad. Hay gentes que tienen permiso para todo, y se imponen, y les caen bien hasta las barrabasadas. Pero yo, que soy una señora como todas, una de tantas, debo respetar el orden establecido y no meterme en honduras. Era visto que Pacheco se había de figurar desde el primer instante... No, no es justo acusarle á él solo.\"},{\"heading\":false,\"text\":\"Bien dice mi paisano. Somos ordinarios y populacheros; nos pule la educación treinta años seguidos, y renace la corteza... Una persona decente, en ciertos sitios obra lo mismo que obraría un mayoral. Aquí estoy yo, que me he portado como una chula.\"},{\"heading\":false,\"text\":\"Es decir... más bien obré como una tonta. Caí de inocente. No supe precaver, pero no hubo en mí mala intención. Ello ocurrió... porque sí. Me pesa, Señor. En toda mi vida me ha sucedido ni ha de volver á sucederme cosa semejante... De eso respondo, y ahora, á remediar el daño. Puerta cerrada, esquinazo, mutis. No me vuelve á ver el pelo el señorito ese. En tomando el tren de Galicia... Y sin tanto. Declaro la casa en estado de sitio... Aquí no entra una mosca. Ya verá si es tan fácil marear á una mujer cuando ella sabe lo que se hace.\"}]},{\"title\":\"Insolación — capítulo IX\",\"blocks\":[{\"heading\":false,\"text\":\"Así, punto más, punto menos, hubiese redactado su declaración la dama, si confiase al papel lo que la bullía en el magín. No afirmamos que, aun dialogando con su conciencia propia, fuese la marquesa viuda de Andrade perfectamente sincera, y no omitiese algún detalle que agravara su tanto de culpa en el terreno de la imprevisión, la ligereza ó la coquetería. Todo es posible, y no conviene salir fiador de nadie en este género de confesiones, que nunca se hacen sin pelos en la lengua y restricciones en la mente.\"},{\"heading\":false,\"text\":\"Sin embargo, no puede negarse que la señora había referido con bastante franqueza el terrible episodio, tanto más terrible para ella, cuanto que hasta dar este mal paso caminara con pié firme y alegre espíritu por la senda de la honestidad. Mérito suyo, más que fruto de la educación paterna, no muy rígida, ni excesivamente vigilante. A Asís se le habían cumplido cuantos caprichos puede tener en un pueblo como Vigo una niña rica, huérfana de madre, y única. A los veinte años de edad, asistiendo á todos los bailes del Casino, á todos los paseos en la Alameda, á todas las verbenas y romerías de Cristos y Pastoras, visitando todos los buques de todas las escuadras que fondeaban en el puerto, Asís no había hecho cosa esencialmente mala, pues no hay severidad que baste á condenar de un modo riguroso el carteo con un teniente de navío, á quien veía be higos á brevas--cuando la _Villa de Bilbao_ andaba por aquellas aguas.--Entonces le entró al papá de Asís, acaudalado negociante, la ventolera de las contratas, acompañada, naturalmente, de la necesidad de meterse en política; tuvo distrito, y contrata va y legislatura viene, comenzó á llevarse á su hija á Madrid todos los inviernos, á dar una vueltecita--la frase sacramental.--Hospedábanse en casa de un primo de la difunta mamá de Asís, el marqués de Andrade, consejero de Estado, porque Asís era fruto de una de esas alianzas entre blasones y talegas, que en Galicia y en todas partes se ven tan á menudo, sin que tuerza el gesto ningún venerable retrato de familia, ni ningún abuelo se estremezca en su tumba. El consejero de Estado se encontraba viudo y sin descendencia; conservaba un cerquillo de pelo alrededor de una lucia calva; poseía buenos modales, carácter ameno (en la corte no existen viejos avinagrados) y la suficiente mundología para saber cómo ha de insinuarse un cincuentón con una muchacha. Asís empezó por enseñarle á su tío, bromeando, las cartas del marino, y acabó por escribir á éste una significándole que sus relaciones «quedaban cortadas para siempre». Y así fué, y la esbelta sombra con gorrilla blanca y levita azul y anclas de oro no se apareció jamás al pié del tálamo de los marqueses de Andrade.\"},{\"heading\":false,\"text\":\"El Marqués tuvo el talento de no ser celoso y hacerle grata á su mujer la vida conyugal. Hasta se separó de otra hermana suya--con la cual vivía desde su primer matrimonio--porque era devota, maniática, opuesta á la sociedad y á las distracciones, y no podía congeniar con la joven esposa; y no se mostró remiso en aflojar dinero para modistas, ni en gastar tiempo en teatros, saraos y tertulias. También supo evitar el delirio de los extremos amorosos, impropios de su edad y la de Asís combinadas; dejó dormir lo que no era para despertado, y así logró siete años de tranquila ventura y una chiquilla algo enclenque, que únicamente revivía con los aires marinos y agrestes de la tierra galaica. Un derrame seroso cortó el curso de los días del buen consejero de Estado, y Asís quedó libre, rica, moza, bien mirada y con el alma serena.\"},{\"heading\":false,\"text\":\"Pasaba en Madrid los inviernos, teniendo á su niña de medio interna en un atildado colegio francés; los veranos se iba á Vigo, al lado de su papá; á veces (como sucedía ahora), el viaje de la chiquilla se adelantaba un poco, porque el abuelo, al cerrarse las Cortes, se la llevaba consigo á desencanijarse en la aldea... Asís la dejaba marchar de buen grado. El amor maternal era en ella lo que había sido el cariño conyugal: sentimiento apacible, exento de esas divinas locuras que abrasan el alma y dan á la existencia sentido nuevo. La marquesa de Andrade vivía contenta, algo envanecida de haber soltado la cáscara provinciana, y satisfecha también de conservar su honradez como la conservan allá en Vigo las señoras muy visibles, que no dan un paso sin que el vecindario sepa si fué con el pié izquierdo ó el derecho. Entretenía sus ocios pensando, por ejemplo, que el último vestido que le había mandado su modista era tan gracioso y menos caro que el de Worth de la Sahagún; que estaba á bien con el Padre Urdax, merced á haber entrado en una asociación benéfica muy recomendada por los jesuítas; que ella era una dama formal, intachable, y que, sin embargo, no dejaban de citarla con elogio en las revistas de salones alguna que otra vez; que podía vivirse en el mundo sin abrir paso al demonio, y que ni el mundo ni Dios tenían por qué volverle la espalda.\"},{\"heading\":false,\"text\":\"Y ahora...\"}]},{\"title\":\"Insolación — capítulo X\",\"blocks\":[{\"heading\":false,\"text\":\"Oyendo un nuevo repiqueteo de campanilla, acudió Angela despavorida, á ver _qué era_. Su ama estaba medio incorporada sobre un codo.\"},{\"heading\":false,\"text\":\"--Venga quien venga, ¿entiendes?, venga quien venga..., que he salido.\"},{\"heading\":false,\"text\":\"--A todo el mundo, vamos; que ha salido la señorita.\"},{\"heading\":false,\"text\":\"--A todo el mundo: sin excepción. Cuidadito como me dejas entrar á nadie.\"},{\"heading\":false,\"text\":\"--¡Jesús, señorita! Ni el aire entrará.\"},{\"heading\":false,\"text\":\"--Y prepárame el baño.\"},{\"heading\":false,\"text\":\"--¿El baño? ¿No le sentará mal á la señorita?\"},{\"heading\":false,\"text\":\"--No--contestó Asís secamente.--(¡Manía de meterse en todo tienen estas doncellas!)\"},{\"heading\":false,\"text\":\"--¿Y la orden del coche, señorita? Ya dos veces ha venido Roque á preguntarla.\"},{\"heading\":false,\"text\":\"Al nombre del cochero, sintió Asís que le _subía un pavo_ atroz, como si el cochero representase para ella la sociedad, el deber, todas las conveniencias pisoteadas y atropelladas la víspera. ¡El cochero si que debía maliciarse!...\"},{\"heading\":false,\"text\":\"--Dile..., dile que... venga dentro de un par de horas..., á las cuatro y media... No, á las cinco y cuarto. Para paseo... Las cinco y media más bien.\"},{\"heading\":false,\"text\":\"Saltó de la cama, se puso la bata, y se calzó las chinelas. ¡Sentía un abatimiento grande, agujetas, cansancio, y al mismo tiempo una excitación, unas ganas de echar á andar, de huir de sí misma, de no verse ni oirse! No se podía sufrir.\"},{\"heading\":false,\"text\":\"--¡Qué vida tan incómoda la de las señoras que anden siempre en estos enredos! No les arriendo la ganancia... ¡Ay! Aborrezco los tapujos y las ilegalidades... He nacido para vivir con orden y con decoro, está visto. ¿Le dará á ese tunante por venir?\"},{\"heading\":false,\"text\":\"Mientras no estaba dispuesto el baño, practicó Asís las operaciones de aseo que deben precederle: limpiarse y limarse las uñas, lavar y cepillar esmeradamente la dentadura, desenredar el pelo y pasarse repetidas veces el peine menudo, registrarse cuidadosamente las orejas con la esponjita y la cucharita de marfil, frotarse el pescuezo con el guante de crín suavizado con pasta de almendra y miel. A cada higiénica operación y á cada parte de su cuerpo que quedaba como una patena, Asís creía ver desaparecer la marca de las irregularidades del día anterior, y confundiendo involuntariamente lo físico y lo moral, al asearse, juzgaba regenerarse.\"},{\"heading\":false,\"text\":\"Avisó la Diabla que estaba listo el baño. Asís pasó á un cuartuco obscuro, que alumbraba un quinqué de petróleo (las habitaciones de baño fantásticas que se describen en las novelas no suelen existir sino en algún palacio, nunca en las casas de alquiler), y se metió en una bañadera de zinc con capa de porcelana--idéntica á las cacerolas.--¡Qué placer! En el agua clara iban á quedarse la vergüenza, la sofoquina y las inconveniencias de la aventura... ¡Allí estaban escritas con letras de polvo! ¡Polvo doblemente vil, el polvo de la innoble feria! ¡Y cuidado que era pegajoso y espeso! ¡Si había penetrado al través de las medias, de la ropa interior, y en toda su piel lo veía depositado la dama! Agua clara y tibia--pensaba Asís--lava, lava tanta grosería, tanto flamenquismo, tanta barbaridad: lava la osadía, lava el desacato, lava el aturdimiento, lava el... Jabón y más jabón. Ahora agua de Colonia... Así.\"},{\"heading\":false,\"text\":\"Esta manía de que con agua de Colonia y jabón fino se le quitaban las manchas á la honra, se apoderó de la señora en grado tal, que á poco se arranca el cutis, de la rabia y el encarnizamiento con que lo frotaba. Cuando su doncella le dió la bata de tela turca para enjugarse, Asís continuó sus fricciones mitad morales, mitad higiénicas, hasta que ya rendida se dejó envolver en la ropa limpia, suspirando como el que echa de sí un enorme peso de cuidados.\"},{\"heading\":false,\"text\":\"Llegó el coche algún tiempo después de terminada la faena, no sólo del baño, sino del tocado y vestido: Asís llevaba un traje serio, de señora que aspira á no llamar la atención. Ya tenía la Diabla la mano en el pestillo para abrir la puerta á su ama, cuando se la ocurrió preguntar:\"},{\"heading\":false,\"text\":\"--¿Vendrá á comer, señorita?\"},{\"heading\":false,\"text\":\"--No.--Y añadió como el que da explicaciones para que no se piense mal de él.--Estoy convidada á comer en casa de las tías de Cardeñosa.\"},{\"heading\":false,\"text\":\"Al sentarse en su berlinita, respiró anchamente. Ya no había que temer la aparición del pillo. ¡Bah! Ni era probable que él se acordase de ella; estos troneras, así que pueden jactarse..., si te he visto no me acuerdo. Mejor que mejor. Qué ganga, si la historia se resolviese de una manera tan sencilla... Y la voz de Asís adquirió cierta sonoridad al decir al cochero:\"},{\"heading\":false,\"text\":\"--Castellana... Y luego á casa de las tías...\"},{\"heading\":false,\"text\":\"Aquella vibración orgullosa de su acento parece que quería significar:\"},{\"heading\":false,\"text\":\"--Ya lo ves, Roque... No se va uno todos los días de picos pardos... De hoy más vuelvo á mi inflexible línea de conducta...\"},{\"heading\":false,\"text\":\"Rodó el coche al trote hasta la Castellana y allí se metió en fila. Era tal el número y la apretura de carruajes, que á veces tenían que pararse todos por imposibilidad de avanzar ni retroceder. En estos momentos de forzosa quietud sucedían cosas chuscas: dos señoras que se conocían y se saludaban, pero no teniendo la intimidad suficiente para emprender conversación, permanecían con la sonrisa estereotipada, observándose con el rabillo del ojo, desmenuzándose el atavío y deseando que un leve sacudimiento del maremagnum de carruajes pusiese fin á una situación tan pesadita. Otras veces le acontecía á Asís quedarse parada tocando con una _manuela_, en cuyo asiento trasero, dejando la bigotera libre, se apiñaban tres mozos de buen humor, horteras ó empleadillos de ministerio, que la soltaban una andanada de dicharachos y majaderías; y nada: aguantarlos á quema ropa, sin saber qué era menos desairado, sonreirse ó ponerse muy seria ó hacerse la sorda. También era fastidioso encontrarse en contacto íntimo con el fogoso tronco de un _milord_, que sacudía la espuma del hocico dentro de la ventanilla, salpicando el haz de lilas blancas sujeto en el tarjetero, que perfumaba el interior del coche. Incidentes que distraían por un instante á la marquesa de Andrade de la dulce quietud y del bienhechor reposo producido por la frescura del aire impregnado de aroma de lilas y flor de acacia, por la animación distinguida y silenciosa del paseo, por el grato reclinatorio que hacía á su cabeza y espalda el rehenchido del coche, forrado de paño gris.\"},{\"heading\":false,\"text\":\"--¡Calle! Allí va Casilda Sahagún empingorotada en el campanario de su _break_. ¿De dónde vendrá, señor? ¡Toma! Ya caigo; de la novillada que armaron los muchachos finos, Juanito Albares, Perico Gonzalvo, Paco Gironellas, Fernandín Hurtado...--En un minuto recordó Asís la organización de la fiesta taurina: se habían repartido programas impresos en raso lacre, redactados con muy buena sombra; no había nada más salado que leer, por ejemplo:--Banderilleros: Fernando Alfonso Hurtado de Mendoza (a) Pajarillas.--José María Aguilar y Austria (a) el Chaval.--¡Pues poca broma que hubo en casa de Sahagún la noche que se arregló el plan de la corrida! Y Asís estaba convidada también. Se le había pasado: ¡qué lástima! La Duquesa, tan sandunguera como de costumbre, hecha un cartón de Goya con su mantilla negra y su grupo de claveles; los muchachos, ufanísimos, en carretela descubierta, envueltos en sus capotes morados y carmesíes con galón de oro. Lo que es torear habrían toreado de echarles patatas; pero ahora nadie les ganaba á darse pisto luciendo los trajes. Revolvían el paseo de la Castellana: eran el acontecimiento de la tarde. Asís sintió un descanso mayor aún después de ver pasar la comitiva taurómaca: comprendió, guiada por el buen sentido, que á nadie, en aquel conjunto de personas siempre entretenidas por algún suceso gordo del orden político, ó del orden divertido, ó del orden escandaloso con platillos y timbales, se le ocurriría sospechar su aventurilla del _Santo_. A buen seguro que por un par de días nadie pensaba más que en la becerrada aristocrática.\"},{\"heading\":false,\"text\":\"Este convencimiento de que su escapatoria no estaba llamada á trascender al público, se robusteció en casa de las tías de Cardeñosa. Las Cardeñosas eran dos buenas señoritas, solteronas, de muy afable condición, rasas de pecho, tristes de mirar, sumamente anticuadas en el vestir, tímidas y dulces, no emancipadas, á pesar de sus cincuenta y pico, de la eterna infancia femenina: hablaban mucho de novenas, y comentaban detenidamente los acontecimientos culminantes, pero exteriores, ocurridos en la familia de Andrade y en las demás que componían el círculo de sus relaciones; para las bodas tenían aparejada una sonrisa golosa y tierna, como si paladeasen el licor que no habían probado nunca; para las enfermedades, calaveradas de chicos y fallecimientos de viejos, un melancólico arqueo de cejas, unos ademanes de resignación con los hombros y unas frases de compasión, que por ser siempre las mismas, sonaban á indiferencia. Religiosas de verdad, nunca murmuraban de nadie ni juzgaban duramente la ajena conducta, y para ellas la vida humana no tenía más que un lado, el anverso, el que cada cual deja ver á las gentes. Gozaban con todo esto las Cardeñosas fama de trato distinguidísimo, y su tarjeta _hacía bien_ en cualquier bandeja de porcelana de esas donde se amontona, en forma de pedazos de cartulina, la consideración social.\"},{\"heading\":false,\"text\":\"Para Asís, la insulsa comida de las tías de Cardeñosa y la anodina velada que la siguió, fueron al principio un bálsamo. Se la disiparon las últimas vibraciones de la jaqueca y las postreras angustias del estómago, y su espíritu se aquietó, viendo que aquellas señoras respetadísimas y excelentes la trataban con el acostumbrado afecto y comprendiendo que ni por las mientes se les pasaba imaginar de ella nada censurable.\"},{\"heading\":false,\"text\":\"El cuerpo y el alma se sosegaban á la par, y gracias á tan saludable reacción, _aquello_ se le figuraba á Asís una especie de pesadilla, un cuento fantástico.\"},{\"heading\":false,\"text\":\"Pero obtenido este estado de calma tan necesario á sus nervios, empezó la dama á notar, hacia eso de las diez, que se aburría ferozmente, por todo lo alto, y que le entraban ya unas ganas de dormir, ya unos impulsos de tomar el aire, que se revelaban en prolongados bostezos y en revolverse en la butaca como si estuviese tapizada de alfileres punta arriba. Tanto, que las Cardeñosas lo percibieron, y con su inalterable bondad comenzaron á ofrecerla otro sillón de distinta forma, el rincón del sofá, una silla de rejilla, un taburetito para los piés, un cojín para la espalda.\"},{\"heading\":false,\"text\":\"--No os incomodéis... Mil gracias... Pero si estoy perfectamente.\"},{\"heading\":false,\"text\":\"Y no atreviéndose á mirar el suyo, echaba un ojo al reloj de sobremesa, un Apolo de bronce dorado, de cuya clásica desnudez ni se habían enterado siquiera las Cardeñosas, en cuarenta años que llevaba el dios de estarse sobre la consola del salón en postura académica, con la lira muy empuñada. El reloj... por supuesto, se había parado desde el primer día, como todos los de su especie. Asís quería disimular, pero se le abría la boca y se le llenaban de lágrimas los ojos; abanicábase estrepitosamente, contestando por máquina á las interrogaciones de las tías acerca de la salud de su niña y los proyectos de veraneo, inminentes ya. Las horas corrían, sin embargo, derramando en el espíritu de Asís el opio del fastidio... Cada rodar de coches por la retirada calle en que habitaban las Cardeñosas, le producía una sacudida eléctrica. Al fin hubo uno que paró delante de la casa misma... ¡Bendito sea Dios! Por encanto recobró la dama su alegría y su amabilidad de costumbre, y cuando la criada vino á decir:--«Está el coche de la señora Marquesa»,--tuvo el heroismo de responder con indiferencia fingida:\"},{\"heading\":false,\"text\":\"--Gracias, que se aguarde.\"},{\"heading\":false,\"text\":\"A los dos minutos, alegando que había madrugado un poco, arrimaba las mejillas al pálido pergamino de la de sus tías, daba un glacial beso al aire y bajaba la escalera repitiendo:\"},{\"heading\":false,\"text\":\"--Sí..., cualquier día de estos... ¡Qué! Si he pasado un rato buenísimo... ¿Mañana sin falta... eh? las papeletas de los Asilos. Mil cosas al Padre Urdax.\"},{\"heading\":false,\"text\":\"Al tirar de la campanilla en su casa, tuvo una corazonada rarísima. Las hay, las hay, y el que lo niegue es un miope del corazón, que rehusa á los demás la acuidad del sentido porque á él le falta. Asís, mientras sonata el campanillazo, sintió un hormigueo y un temblor en el pulso, como si semejante tirón fuese algún acto muy importante y decisivo en su existencia. Y no experimentó ninguna sorpresa, aunque sí una violenta emoción que por poco la hace caerse redonda al suelo, cuando en vez de la Diabla ó del criado vió que le abría la puerta aquel pillo, aquel grandiosísimo truhán.\"}]},{\"title\":\"Insolación — capítulo XI\",\"blocks\":[{\"heading\":false,\"text\":\"Lo bueno fué que la dama, lejos de mostrar extrañeza, saludó á Pacheco como si el encontrarle allí á tales horas le pareciese la cosa más natural del mundo, y, recíprocamente, Pacheco empleó también con ella todas las fórmulas de cortesía acostumbradas cuando un caballero se dirige á una señora de cumplido, respetable, ya que no por sus años, por su carácter y condición. Se hizo atrás para dejarla pasar, y al seguirla al saloncito de confianza, donde ardía sobre la mesa de tijera la gran lámpara con pantalla rosa velada de encaje, se quedó próximo á la puerta y en pié, como el que espera una orden de despedida.\"},{\"heading\":false,\"text\":\"--Siéntese V., Pacheco...--tartamudeó la señora, bastante aturrullada aún.\"},{\"heading\":false,\"text\":\"El gaditano no se sentó, pero adelantó despacio, como receloso; parecía, por su continente, algún hombre poco avezado á sociedad: pero este aspecto, que Asís atribuyó á hipocresía refinada, contrastaba de un modo encantador con la soltura de su cuerpo y modales, la elegancia no estudiada de su vestir, la finura de su chaleco blanquísimo, su tipo de persona principal. Viéndole tan contrito, Asís se rehizo y cobró ánimos.--«Gran ocasión de leerle la cartilla al señorito éste: ¿conque muy manso y fingiéndose arrepentido, eh? Ahora lo verás...»--Porque la dama, en su inexperiencia, se había figurado que su compañero de romería iba á entrar hecho un sargento, y á las primeras de cambio la iba á soltar un abrazo furibundo ó cualquier gansada semejante... Pero ya que gracias á Dios se manifestaba tan comedido, bien podía la señora acusarle las cuarenta. Y Asís abrió la boca y exclamó:\"},{\"heading\":false,\"text\":\"--Conque V. aquí... Yo quisiera... yo...\"},{\"heading\":false,\"text\":\"El gaditano se acercó todavía más, hasta ponerse al lado de la dama, que seguía en pié junto á la mesa. La miró fijamente y luego pronunció como el que dice la cosa más patética del mundo:\"},{\"heading\":false,\"text\":\"--A mi va V. á regañarme too lo que guste... A los criados, ni chispa... La culpa es mía toa. Un cuarto de hora de conversación con la chica me ha costao el entrar. Hasta requiebros la he soltao. Y na, ni por esas. Al fin la dije... que vamos, que ya sabía V. que yo vendría y que para recibirme á mí se quería V. negar á los demás. Ríñame V., que lo meresco too.\"},{\"heading\":false,\"text\":\"Estas enormidades las murmuró con tono quejumbroso y lánguido, con los ojos mortecinos y un aire de melancolía que daba compasión. Asís, así al pronto se quedó de una pieza, después se la deshizo el nudo de la garganta y las palabras le salieron á borbotones. Ea..., ahí va... Ahora sí que me desato...\"},{\"heading\":false,\"text\":\"--Sí señor, que merece V.... Pues hombre... me pone V. en berlina con mis criados... ¡Por eso se escondieron cuando yo entraba... y le dejan á V. que abra la puerta! ¡Gandules de profesión! A la Angelita yo le diré cuántas son cinco... Y lo que es á Perfecto... Alguno podrá ser que no duerma en casa esta noche... Los enemigos domésticos... Aguarde V., aguarde V.... Estas jugadas no me las hacen ellos á mí... ¡Habrase visto! ¡Para esto los trata uno del modo que los trata! ¡Para que le vendan á las primeras de cambio!\"},{\"heading\":false,\"text\":\"Comprendía la misma señora que se ponía algo ordinaria chillando y manoteando así, y lo peor de todo, que era predicar en desierto, pues ni siquiera podían oirla desde la cocina; además, Pacheco, en vez de asustarse con tan caliente reprimenda, pareció que recobraba los espíritus, se llegó más, y bajando la cabeza, acarició las sienes de la enojada. Esta se echó atrás, no tan pronto que ya no la sujetase blandamente por la cintura un brazo del gaditano y que éste no balbuciese á su oído:\"},{\"heading\":false,\"text\":\"--¿A qué te enfadas con los criados, chiquilla? ¿No te he dicho que no tienen culpa? Mira, esa chica que te sirve, vale un Perú. Te quiere bien. La daba dinero y no lo admitió ni hecha peazos. Dijo que con tal que tú no la riñeses... Ahora si gritas se armará un escándalo... Pero me iré cuando tú lo mandes. Que sí me iré, nena...\"},{\"heading\":false,\"text\":\"Al anunciar que se iba, se sentó en el sofá-diván, obligando á la señora á sentarse también. Esta notaba una turbación que ya no se parecía á la pseudo-cólera de antes, y por lo bajo, murmuraba:\"},{\"heading\":false,\"text\":\"--Pues váyase V... Hágame el favor de irse. Por Dios...\"},{\"heading\":false,\"text\":\"--¿Ni un minuto hay para mí? Estoy enfermo... ¡Si vieses! En toda la noche no he dormido, no he pegado los ojos.\"},{\"heading\":false,\"text\":\"Asís iba á preguntar: «¿por qué?» pero calló, pareciéndole inconveniente y necia la pregunta.\"},{\"heading\":false,\"text\":\"--Necesitaba saber de ti... Si estabas ya buena, si habías descansado... Si me querías mal, ó si me mirabas con alguna indulgencia. ¿Dura el mal humor? ¿Y esa cabecita? ¿A ver?\"},{\"heading\":false,\"text\":\"Se la recostó sobre el hombro, sujetándola con la palma de la mano derecha. Asís, esforzándose en romper el lazo, notaba disminuidas sus fuerzas por dos sentimientos: el primero, que viendo tan sumiso y moderado al gran pillo, le habían entrado unas miajas de lástima; el segundo..., el sentimiento eterno, la maldita curiosidad, la que perdió en el Paraíso á la primera mujer, la que pierde á todas, y tal vez no sólo á ellas sino al género humano... ¿A ver? ¿Cómo sería? ¿Qué diría Pacheco ahora?\"},{\"heading\":false,\"text\":\"Pacheco, en un rato, no dijo nada; ni chistó. Su palma fina, sus dedos enjutos y nerviosos oprimían suavemente la cabeza y sienes de Asís, lo mismo que si á ésta le durase aún el mareo de la víspera y necesitase la medicina de tan sencillo halago. En la sala parecía que la varita de algún mágico invisible derramaba silencio apacible y amoroso, y la luz de la lámpara, al través de su celosía de encaje, alumbraba con poética suavidad el recinto. La sala estaba amueblada con esas pretensiones artísticas que hoy ostenta todo bicho viviente, sepa ó no sepa lo que es arte, y con ese aspecto de prendería, que resulta de aglomerar el mayor número posible de cosas inconexas. Sitiales, butacas bajas y coquetonas, mesillas forradas de felpa imitando un corazón ó una hoja de trébol, columnas que sostienen quinqués, divancitos cambiados donde la gente puede gozar del placer de darse la espalda y coger un torticolis, alguna drácena en jardineras de zinc, un perro de porcelana haciendo centinela junto á la chimenea, y dos hermosos vargueños patrimoniales restaurados y dorados de nuevo... Todo revuelto, colocado de la manera que más dificultase el paso á la gente, haciendo un archipiélago donde no se podía navegar sin práctico. ¿Y las paredes? Si el suelo estaba intransitable, en las paredes no quedaba sitio libre para un clavo, pues el buen marqués de Andrade, incapaz de distinguir un Ticiano de un Ribera, la había dado algún tiempo de protector de jóvenes artistas, llenando la casa de acuarelas con chulas, matones del Renacimiento ó damas de Luis XV; de _manchas_, apuntes y bocetos hechos á punta de cuchillo, ó á yema de dedo, tan _libres_ y tan _francos_, que ni el mismo demonio adivinaría lo que representaban; de tablitas lamidas y microscópicas, encerradas en marcos cinco veces mayores; de fotografías con retumbantes dedicatorias, migajas de arte, en suma, que al menos cubren la vulgaridad del empapelado y distraen gratamente la vista. Y en hora semejante, en medio de la amable paz que flotaba en la atmósfera, y con la luz discreta transparentada por el encaje, los cachivaches se armonizaban, se fundían en una dulce intimidad, en una complicidad silenciosa; la misma horrible carátula japonesa colgada encima de un vargueño y de uno de cuyos ojos se descolgaba una procesión de monitos de felpa, tenía gesto menos infernal; el pañolón de Manila que cubría el piano abría alegremente todas sus flores; las begonias, próximas á la entreabierta ventana, se estremecían como si las acariciase el vientecillo nocturno... Sólo el _bull-dog_ de porcelana, sentado como una esfinge, miraba con alarmante persistencia al grupo del sofá, ostentando una actitud digna y enérgica, como si fuese celoso guardián puesto allí por el espíritu del respetable Marqués difunto... Casi parecía natural que abriese las fauces, soltase un ladrido de alarma, y se abalanzase dispuesto á morder...\"},{\"heading\":false,\"text\":\"Pacheco decía bajito, con el ceceo mimoso y triste de su pronunciación:\"},{\"heading\":false,\"text\":\"--¿Te sospechabas tú lo de ayer, chiquilla? ¿A que sí? Mira, no me digas no, que las mujeres estáis siempre de vuelta en esas cosas... ¡A ver si se calla V. y no me replica! Tú veías muy bien, picarona, que yo estaba muerto, lo que se dise muerto... Sólo que creiste poder dejarme en blanco... Pero sospechar... ¡Quiá! ¡Si lo calaste desde el mismo momento que tiré el puro en los jardines! ¿Y tú te gosabas en verme á mí sufrir, no es eso? ¡Somos más malos! Toma en castigo... ¡Y qué bonita estabas, gitana salá! ¿Te ha dicho á ti algún hombre bonita? ¿No? ¡Pues ahora te lo digo yo, vamos! y valgo más que toos... Oye, en el coche te hubiese yo requebrado seis dosenas de veses..., te hubiese llamao mona, serrana, matadora de hombres... Sólo que no me atrevía, ¿sabes tú? Que si me atrevo, te suelto toas las flores de la primavera en un ramiyetico.\"},{\"heading\":false,\"text\":\"Aquí Asís, sin saber por qué, recobró el uso de la palabra, y fué para gritar:\"},{\"heading\":false,\"text\":\"--Sí..., como á la chica del merendero..., y á mi criada..., y á todas cuantas se ofrece... Lo que es por palabrería no queda.\"},{\"heading\":false,\"text\":\"La interrumpió un enérgico tapabocas.\"},{\"heading\":false,\"text\":\"--No compares, chiquiya, no compares... Tonterías que se disen por pasá el rato, pa que se encandilen las mujeres... Contigo... ¡Virgen Santa! tengo yo una ilusionasa..., ¡una ilusión de volverme loco! Has de saber que yo mismo estoy pasmao de lo que me sucede. Nunca me quedé triste después de una cosa así sino contigo. Hasta me falta resolución pa hablarte. Estoy así... medio orgulloso y medio pesaroso. Más quisiera que nos hubiésemos vuelto ayer antes de almorsá. ¿No lo crees? ¿Ah, no lo crees? Por estas...\"},{\"heading\":false,\"text\":\"El meridional puso los dedos en cruz y los besó con ademán popular. Asís se echó á reir mal de su grado. Ya no había posibilidad de enfadarse; la risa desarma al más furioso. Y ahora, ¿qué hacer? pensaba la dama, llamando en su auxilio toda su presencia de ánimo, toda su habilidad femenil. Nada, muy sencillo... No negarle la cita que pedía para el día siguiente por la tarde, porque si se le negaba, era capaz de hacer cualquier desatino. No, no..., contemporizar..., otorgar la cita, y á la hora señalada... ¡busca! estar en cualquier sitio menos donde Pacheco esperase... Y ahora, procurar _por bien_ que se largase cuanto más pronto... ¡Que diría el servicio! ¡En esa cocina estaría la Diabla haciendo unos calendarios!\"}]},{\"title\":\"Insolación — capítulo XII\",\"blocks\":[{\"heading\":false,\"text\":\"Doloroso es tener que reconocer y consignar ciertas cosas; sin embargo, la sinceridad obliga á no eliminarlas de la narración. Queda, eso sí, el recurso de presentarlas en forma indirecta, procurando con maña que no lastimen tanto como si apareciesen de frente, insolentonas y descaradas, metiéndose por los ojos. Así la implícita desaprobación del novelista se disfraza de habilidad.\"},{\"heading\":false,\"text\":\"Tocante á la cita que la marquesa viuda de Andrade pensaba conceder en falso, con resolución firmísima de hacer la del humo, la novela puede guardar un discreto mutismo; y no faltará á su elevada misión, con tal que refiera lo que ocurría á la puerta de la dama: indicación sobria y á la vez sumamente expresiva.\"},{\"heading\":false,\"text\":\"La berlina de la señora, enganchada desde las cinco, esperaba allí. El cochero, inmóvil, bien afianzado en su cuña, había permanecido algún tiempo en la actitud reglamentaria, enarbolada la fusta, recogidas las riendas, ladeado graciosamente el sombrero y muy juntas las punteras de las botas; pero transcurrido un cuarto de hora, el recalmón de la tardecita y el aburrimiento de la espera le derramaron en los párpados grato beleño y fué dejando caer la cabeza sobre el pecho, aflojando las manos, exhalando una especie de silbido y á veces un ronquido súbito, que le asustaba á él mismo, despertándole... También el caballo, durante los primeros momentos de quietud, se mantuvo engallado, airoso, dispuesto á beberse la distancia; pero al convencerse de que teníamos plantón, desplomó el cuerpo sobre las patas, sacudió el freno regándolo con espuma, entornó los ojos y se dispuso á la siesta. Hasta la misma berlina pareció afianzarse en las ruedas con ánimo de descansar.\"},{\"heading\":false,\"text\":\"Y fué poniéndose el sol, subiendo de piso en piso á despedirse de los cristales, refugiándose en la copa de las acacias de Recoletos cuando ya las envolvía la azul y vaporosa bruma del anochecer; y el calor disminuyó un tantico, y el farolero corrió encendiendo hilos de luz á lo largo de las calles... Berlina, caballo y cochero dormían, resignados con su suerte, sin que se les ocurriese que para semejante viaje no se necesitaban alforjas y que mejor se encontrarían la una metida en su funda, el otro despachando su ración de pienso, el último en su taberna favorita ó viendo la novillada de aquella tarde...\"},{\"heading\":false,\"text\":\"Cerca de las siete serían cuando salió de la casa un hombre. Era apuesto y andaba aprisa, recatándose de la portera. Atravesó la calle y en la acera de enfrente se detuvo, mirando hacia las ventanas del cuarto de Asís. Ni rastro de persona asomada en ellas. El hombre siguió su camino hacia Recoletos.\"}]},{\"title\":\"Insolación — capítulo XIII\",\"blocks\":[{\"heading\":false,\"text\":\"Solía el comandante Pardo ir alguna que otra noche á casa de su paisana y amiga La marquesa de Andrade. Charlaban de mil cosas, disputando, acalorándose, y en suma, pasando la velada solos, contentos y entretenidos. De galanteo propiamente dicho, ni sombra, aun cuando la gente murmuraba (de la tertulia de la Sahagún saldría el chisme) que Don Gabriel hacía tiro al decente caudal y á la agradable persona de Asís; si bien otros opinaban, con trazas y tono de mejor informados, que ni á Pardo le importaba el dinero, por ser desinteresadísimo, ni las mujeres, por hallarse mal curada todavía la herida de un gran desengaño amoroso que en Galicia sufriera: una historia romántica y algo obscura con una sobrina, que por huir de él se había metido monja en un convento de Santiago.\"},{\"heading\":false,\"text\":\"Ello es que Pardo resolvió consagrar á la dama la noche del día en que la berlina echó la siesta famosa. Serían las nueve cuando llamó á la puerta. Generalmente los criados le hacían entrar con un apresuramiento que delataba el gusto de la señora en recibir semejantes visitas. Pero aquella noche, así Perfecto (el mozo de comedor á quien Asís llamaba _Imperfecto_ por sus _gedeonadas_) como la Diabla, se miraron y respondieron á la pregunta usual del comandante, titubeando é indecisos.\"},{\"heading\":false,\"text\":\"--¿Qué pasa? ¿Ha salido la señorita? Los martes no acostumbra.\"},{\"heading\":false,\"text\":\"--Salir..., como salir...,--balbució Imperfecto.\"},{\"heading\":false,\"text\":\"--No, salir no--acudió la Diabla viéndole en apuro.--Pero está un poco...\"},{\"heading\":false,\"text\":\"--Un poco _dilicada_--declaró el criado con tono diplomático.\"},{\"heading\":false,\"text\":\"--¿Cómo delicada?--exclamó el comandante alzando la voz.--¿Desde cuándo se encuentra enferma? ¿Y qué tiene? ¿Guarda cama?\"},{\"heading\":false,\"text\":\"--No señor, guardar cama no... Unas _miagas_ de jaqueca...\"},{\"heading\":false,\"text\":\"--¡Ah! bien: díganla Vds. que volveré mañana á saber... y que la deseo alivio. ¿Eh? ¡No se olviden!\"},{\"heading\":false,\"text\":\"Acabar de decir esto el comandante y aparecer en la antesala Asís en bata y arrastrando chinelas finas, fué todo uno.\"},{\"heading\":false,\"text\":\"--Pero que siempre han de entender al revés cuanto se les manda... Estoy, Pardo, estoy visible... Entre V.... Qué tienen que ver las órdenes que se dan así, en general, para la gente de cumplido... Haga V. el favor de pasar aquí...\"},{\"heading\":false,\"text\":\"Gabriel entró. La sala estaba tan simpática, tan tentadora, tan fresca como la víspera; la pantalla de encaje filtraba la misma luz rosada y ensoñadora; en un talavera _de botica_ se marchitaba un ramo de lilas y rosas blancas. Tropezó el pié del comandante, al ir á sentarse en su butaca de costumbre, con un objeto medio oculto en las arrugas del tapiz turco arrojado ante el diván. Se bajó y recogió del suelo el estorbo, maquinalmente. Asís extendió la mano, y á pesar de lo muy distraído y sonámbulo que era Gabriel, no pudo menos de observar la agitación de la dama al recobrar la prenda, uno de esos tarjeteros sin cierre, de cuero inglés, con dos iniciales de plata enlazadas, prenda evidentemente masculina. Por un instinto de discreción y respeto, Gabriel se hizo el tonto y entregó su hallazgo sin intentar ver la cifra.\"},{\"heading\":false,\"text\":\"--Pues me habían dado un susto ese Imperfecto y esa Diabla...--murmuró tratando de disimular mejor la sorpresa.--Están en Belén... ¿Se había V. negado, sí ó no?\"},{\"heading\":false,\"text\":\"--Le diré á V.... Di una orden... Claro que con V. no rezaba; bien ha visto V. que le llamé...--alegó la señora con acento contrito, cual si se disculpase de alguna falta gorda, y muy inmutada, aunque esforzándose también en no descubrirlo.\"},{\"heading\":false,\"text\":\"--¿Y qué es ello? ¿Jaqueca?\"},{\"heading\":false,\"text\":\"--Sí..., bastante incómoda. (Asís se llevó la mano á la sien.)\"},{\"heading\":false,\"text\":\"--Entonces le voy á dar V. la noche si me quedo. La dejaré á V. descansar... En durmiendo se pasa.\"},{\"heading\":false,\"text\":\"--No, no, qué disparate... No se va V. Al contrario...\"},{\"heading\":false,\"text\":\"--¿Cómo que _al contrario_? Ruego que se expliquen esas palabras--exclamó el comandante, aprovechando la ocasión de bromear para que se le quitase á Asís el sobresalto.\"},{\"heading\":false,\"text\":\"--Se explicarán... Significan que va V. á acompañarme por ahí fuera un ratito... A dar una vuelta á pié. Me conviene esparcirme, tomar el aire...\"},{\"heading\":false,\"text\":\"--Iremos á un teatrillo... ¿Quiere V.? Dicen que es muy gracioso _El padrón municipal_, en Lara.\"},{\"heading\":false,\"text\":\"--Teatrillo..., ¿calor, luces, gente? V. pretende asesinarme. No: si lo que me pide el cuerpo es ejercicio. Así, conforme estoy, sin vestirme... Me planto un abrigo y un velo... Me calzo... y jala.\"},{\"heading\":false,\"text\":\"--A sus órdenes.\"},{\"heading\":false,\"text\":\"Cuando salieron á la calle, Asís suspiró, aliviada, y con el impulso de su andar señaló la dirección del paseo.\"},{\"heading\":false,\"text\":\"El barrio de Salamanca, á trechos, causa la ilusión gratísima de estar en el campo: masas de árboles, ambiente oxigenado y oloroso, espacio libre, y una bóveda de firmamento que parece más elevada que en el resto de Madrid.\"},{\"heading\":false,\"text\":\"La noche era espléndida, y al levantar Asís la cabeza para contemplar el centelleo de los astros, se le ocurrió, por decir alguna cosa, compararlos á las joyas que solía admirar en los bailes.\"},{\"heading\":false,\"text\":\"--Aquellas cuatro estrellitas seguidas parecen el imperdible de la marquesa de Riachuelo... cuatro brillantazos que le dejan á uno bizco. Esa constelación... ¡allí, hombre, allí! hace el mismo efecto que la joya que le trajo de París su marido á la Torres-Nobles... Hasta tiene en medio una estrellita amarillenta, que será el brillante brasileño del centro. Aquel lucero tan bonito, que está solo...\"},{\"heading\":false,\"text\":\"--Es Venus... Tiene algo de emblemático eso de que Venus sea tan guapa.\"},{\"heading\":false,\"text\":\"--V. siempre confundiendo lo humano y lo divino...\"},{\"heading\":false,\"text\":\"--No, si la mezcolanza fué V. quien la armó comparando los astros á las joyas de sus amiguitas. ¡Qué hermoso es el cielo de Madrid!--añadió después de breve silencio.--En esto tenemos que rendir el pabellón, paisana. Nuestro suelo es más fresco, más bonito; pero la limpieza de esta atmósfera... Allá hay que mirar hacia abajo, aquí hacia arriba.\"},{\"heading\":false,\"text\":\"Callaron un ratito.\"},{\"heading\":false,\"text\":\"En aquel dosel azul sembrado de flores de pedrería, Asís y el comandante veían la misma cosa, un tarjetero de piel inglesa, y como por magnética virtud, sentían al través de sus brazos, que se tocaban, el mutuo pensamiento.\"},{\"heading\":false,\"text\":\"Hallábanse al final del Prado, enteramente desierto á tales horas, con sus sillas recogidas y vueltas. Se escuchaba el murmurio monótono de la Cibeles, y allá en el fondo del jardincillo, tras las irregulares masas de las coníferas, destacaba el Museo su elegante silueta de palacio italiano. No pasaba un alma, y la plazuela de las Cortes, á la luz de sus faroles de gas, parecía tan solitaria como el Prado mismo.\"},{\"heading\":false,\"text\":\"--¿Subimos hacia la Carrera?--interrogó Pardo.\"},{\"heading\":false,\"text\":\"--No, paisano... ¡Ay Jesús! A los dos pasos nos encontrábamos algún conocido, y mañana..., chi, chi, chi..., cuentecito en casa de Sahagún ó donde se les antojase. Bajemos hacia Atocha.\"},{\"heading\":false,\"text\":\"--Y V. ¿por qué da á _eso_ tanta importancia? ¿Qué tiene de particular que salga V. á tomar el fresco en compañía de un amigo formal? Cuidado que son majaderas las fórmulas sociales. Yo puedo ir á su casa de V. y estarme allí las horas muertas sin que nadie se entere ni se ocupe, y luego, si salimos reunidos á la calle media hora... cataplum.\"},{\"heading\":false,\"text\":\"--Qué manía tiene V. de ir contra la corriente... Nosotros no vamos á volver el mundo patas arriba. Dejarlo que ruede. Todo tiene sus por qués, y en algo se fundan esas precauciones ó fórmulas, como V. les llama. ¡Ay! ¡Qué fresquito tan hermoso corre!\"},{\"heading\":false,\"text\":\"--¿Está V. mejor?\"},{\"heading\":false,\"text\":\"--Un poco. Me da la vida este aire.\"},{\"heading\":false,\"text\":\"--¿Quiere V. sentarse un rato? El sitio convida.\"},{\"heading\":false,\"text\":\"Sí que convidaba el sitio, á la vez acompañado y solo: unos anchos asientos de piedra que hay delante del Museo, á la entrada de la calle de Trajineros, la cual si por su gran proximidad á la plazuela de las Cortes resulta céntrica y decorosa, á semejante hora compite en lo desierta con el despoblado más formidable de Castilla. Las acacias prodigaban su rica esencia, y si el comandante tuviese propósito de declarar á la señora algún atrevido pensamiento, nunca mejor. No sería así, porque después de tomar asiento se quedaron mudos ella y él; Asís, además de muda, estaba cabizbaja y absorta.\"},{\"heading\":false,\"text\":\"No es posible que esta clase de pausas se establezcan en una entrevista á solas de hombre y mujer, en tales sitios y horas, sin producirles á los dos un estado de ánimo singular, á la vez atractivo y embarazoso. El comandante limpió sus quevedos, operación que verificaba muy á menudo, volvió á calárselos, y salió por la puerta ó por la ventana, juzgando que la señora desearía explayarse.\"},{\"heading\":false,\"text\":\"--A mí no me la pega V. con jaquecas, Paquita... V. tiene algo... alguna cosa que la preocupa en gordo... No se me alarme V.: ya sabe que somos amigos viejos.\"},{\"heading\":false,\"text\":\"--Pero si no tengo nada... ¡Qué ocurrencia!\"},{\"heading\":false,\"text\":\"--Mejor, señora, mejor, celebro que sea así,--dijo Don Gabriel retrocediendo discretamente.--Yo, en cambio, le podría confiar á V. penas muy grandes..., cosas raras.\"},{\"heading\":false,\"text\":\"--¿Lo de la sobrina?--preguntó Asís con curiosidad, pues ya dos ó tres veces en conversación familiar habían aludido de rechazo á ese misterio de la vida de Don Gabriel.\"},{\"heading\":false,\"text\":\"--Sí; al menos la parte mía..., lo que me toca..., eso puedo contárselo á V. Sabe Dios cómo lo glosa la gente.--(Pardo se alzó el sombrero, porque tenía las sienes húmedas de sudor.)--Creo que se dice que la pobrecilla me detestaba y que por librarse de mi entró en un convento de novicia... Falso. No me detestaba, y es más: me hubiese querido con toda su alma á la vuelta de poco tiempo... Sólo que ella misma no acertó á descifrarlo. Cuando me conoció, estaba comprometida con otro hombre... cuya clase... no... En fin, que no podía aspirar á ser su marido. Y al convencerse de esto, la infeliz muchacha pensó que se acababa el mundo para ella y que no tenía más refugio que el convento, ¡Ay, Paquita! ¡Si supiese V. qué ratos... qué tragedia! Es asombroso que después de ciertos acontecimientos pueda uno volver á vivir como antes..., y vaya á tertulias y se chancee, y mire otra vez á las mujeres, y le agraden, sí..., como me agrada V., por ejemplo..., y no lo eche V. á mala parte, que no soy pretendiente importuno, sino amigo de verdad. Ya sabe V. cómo digo yo las cosas.\"},{\"heading\":false,\"text\":\"Oía la dama la voz del artillero y al par otra interior que zumbaba confusamente:\"},{\"heading\":false,\"text\":\"--Confíale algo..., al menos indícale tu situación... Ideas estrafalarias las tiene, y á veces es poco práctico, pero es leal... No corres peligro, no... Así te desahogarás... Tal vez te aconseje bien. Anda, boba... ¿No hace él confianza de ti? Además... no creas que callando le engañas... ¡Quítale ya la escama del tarjetero!\"},{\"heading\":false,\"text\":\"A pesar de las excitaciones de la voz indiscreta, la señora, en alto, decía tan sólo:\"},{\"heading\":false,\"text\":\"--¿Con que la chica le quería á V. algo? ¿Sin saberlo? ¡Eso es muy particular! ¿Y cómo lo explica V.?\"},{\"heading\":false,\"text\":\"--¡Ay, Paquita! He renunciado á explicar cosa alguna... No hay explicación que valga para los fenómenos del corazón. Cuanto más se quieren entender, más se obscurecen. Hay en nosotros anomalías tan raras, contradicciones tan absurdas... Y á la vez cierta lógica fatal. En esto de la simpatía sexual, ó del amor, ó como V. guste llamarle, es en lo que se ven mayores extravagancias. Luego, á los caprichos y las desviaciones y los brincos de esta víscera que tenemos aquí, sume V. la maraña de ideas con que la sociedad complica los problemitas psicológicos. La sociedad...\"},{\"heading\":false,\"text\":\"--Contigo tengo la tema, morena...--interrumpió Asís festivamente.--V. le echa á la sociedad todas las culpas. Ahí que no duele. Ya no sé como tiene espaldas la infeliz.\"},{\"heading\":false,\"text\":\"--Pues, figúrese V., paisana. Como que de mi tragedia únicamente es responsable la sociedad. Por atribuir exagerada importancia á lo que tiene mucha menos ante las leyes naturales. Por hacer lo principal de lo accesorio. En fin, punto en boca. No quiero escandalizarla á V.\"},{\"heading\":false,\"text\":\"--Paisano... Pero si me da mucha curiosidad eso que iba Vd. diciendo... No me deje á media miel... Todas las cosas pueden decirse, según como se digan. No me escandalizaré, vamos.\"},{\"heading\":false,\"text\":\"--Bien, siendo así... Pero ya no sé en que estábamos... ¿V. se acuerda?\"},{\"heading\":false,\"text\":\"--Decía V. que lo principal y lo accesorio... Eso será alguna herejía tremenda, cuando no quiso V. pasar de ahí.\"},{\"heading\":false,\"text\":\"--Sí, señora... Verá V. la herejía... Yo llamo accesorio á lo que en estas cuestiones suele llamarse principal... ¿Se hace V. cargo?\"},{\"heading\":false,\"text\":\"Asís no respondió, porque pasaba un mozalbete silbando un aire de zarzuela y mirando de reojo y con malicia al sospechoso grupo. Cuando se perdió de vista, pronunció la dama:\"},{\"heading\":false,\"text\":\"--¿Y si me equivoco?\"},{\"heading\":false,\"text\":\"--¿No se asusta V. si lo expreso claramente?\"},{\"heading\":false,\"text\":\"La verdad, desde cierta distancia aquello parecía un diálogo amoroso. Acaso la valla que existía para que ni pudiese serlo ni llegase á serlo jamás, era un delgado y breve trozo de piel inglesa--la cubierta de un tarjetero.\"},{\"heading\":false,\"text\":\"--No, no me asusto... Vamos á hablar como dos amigos... francamente.\"},{\"heading\":false,\"text\":\"--¿Quedamos en eso? ¡Magnífico! Pues conste que ya no tiene V. derecho para reñirme si se me va la lengua... Procuraré, sin embargo... En fin, entiendo por accesorio... aquello que Vds. juzgan irreparable. ¿Lo pongo más claro aún?\"},{\"heading\":false,\"text\":\"--No, ¡basta!--gritó la señora.--Pero entonces, ¿qué es lo principal según V.?\"},{\"heading\":false,\"text\":\"--Una cosa que abunda menos..., y en cambio vale más... La realidad de un cariño muy grande entre dos... ¿Qué le parece á V.?\"},{\"heading\":false,\"text\":\"--¡Caramba!--exclamó la señora, meditabunda.\"},{\"heading\":false,\"text\":\"--Le voy á proponer á V. una demostración de mi teoría... Ejemplo; como dicen los predicadores. Imagínese que en vez de estar en el Prado, estamos en Tierra de Campos, á dos leguas de un poblachón; que yo soy un bárbaro; que me prevalgo de la ocasión, y abuso de la fuerza, y la falto á V. al respeto debido... ¿Hay entre nosotros, dos minutos después, algún vínculo que no existía dos minutos antes? No señora. Lo mismo que si ahora se trompica V. con una esquina..., se hace daño..., procura apartarse y andar con más cuidado otra vez... y acabóse.\"},{\"heading\":false,\"text\":\"--Pintado el lance así..., lo que habría, que V. me parecería atroz de antipático y de bruto.\"},{\"heading\":false,\"text\":\"--Eso sí... pero vamos á perfeccionar el ejemplo, y pido á V. perdón de antemano por una conversación tan _shocking_. Pues no señora: suponga V. que yo no abuso de la fuerza ni ese es el camino. Lo que hago es explotar con maña la situación y despertar en V. ese germen que existe en todo ser humano... Nada de violencia: si acaso, en el terreno puramente moral... Yo soy hábil y provoco en V. un momento de flaqueza...\"},{\"heading\":false,\"text\":\"Fortuna que era de noche y estaba lejos el farol, que si no, el sofoco y el azoramiento de la dama se le meterían por los ojos al comandante.--Lo sabe, lo sabe--calculaba para sí, toda trémula, y en voz alterada y suplicante, exclamó interrumpiendo:\"},{\"heading\":false,\"text\":\"--¡Qué horror! ¡Don Gabriel!\"},{\"heading\":false,\"text\":\"--¿Qué horror? ¡Mire V. lo que va de Vds. á nosotros! Ese horror, Paquita del alma, no les parece horrible á los caballeros que V. trata y estima: al marqués de Huelva, con su severidad de principios y su encomienda de Calatrava, que no se quita ni para bañarse... al papá de V., tan amable y francote... á mí... al otro... á toditos. Es valor entendido, y á nadie le extraña ni le importa un bledo. Tratándose de Vds., es cuando por lo más insignificante se arma una batahola de mil diablos, que no parece sino que arde por los cuatro costados Madrid. La infeliz de Vds. que resbala, si olfateamos el resbalón, nos arrojamos á ella como sabuesos, y, ó se salva casándose con el _seductor_, ó la matriculamos en el gremio de las mujeres galantes hasta la hora de la muerte. Ya puede, después de su falta, llevar vida más ejemplar que la de una monja: la hemos fallado... no nos la pega más. O bodas, ó es V. una corrida, una perdida de profesión... ¡Bonita lógica! V., niña inocente, que cae víctima de la poca edad, la inexperiencia y la tiranía de los afectos y las inclinaciones naturales, púdrase en un convento, que ya no tiene V. más camino... Amiga Asís... ¡Tonterías!\"},{\"heading\":false,\"text\":\"Mientras hablaba el comandante, su fantasía, en vez de los plátanos del jardincillo, le representaba otras masas sombrías de follaje, robles y castaños; y el olor fragante de las flores de acacia le parecía el de las silvestres mentas que crecen al borde de los linderos en el valle de Ulloa. La dama que tenía á su lado, por el mismo fenómeno de óptica interior, veía el rebullicio de una feria, una casita al borde del Manzanares, un cuartuco estrecho, un camastro, una taza de té volcada...\"},{\"heading\":false,\"text\":\"--Tonterías--prosiguió Don Gabriel, sin fijarse en la gran emoción de Asís--pero que se pagan caras á veces... Sucede que se nos imponen, y que por obedecerlas, una mujer de instintos nobles se juzga manchada, vilipendiada, infamada por toda su vida á consecuencia de un minuto de extravío, y, de no poder casarse con aquel á quien se cree ligada para siempre jamás, se anula, se entierra, se despide de la felicidad por los siglos de los siglos amén... Es monja sin vocación, ó es esposa sin cariño... Ahí tiene V. dónde paran ciertas cosas.\"},{\"heading\":false,\"text\":\"Al murmurar con amargura estas palabras, el comandante, en lugar de la silueta gentil del Museo, veía las verdosas tapias del convento santiagués, las negras rejas de trágicos recuerdos, y tras de aquellas rejas, comidas de orín, una cara pálida, con obscuros ojos, muy semejante á la de cierta hermana suya, que había sido el cariño más profundo de su vida.\"}]},{\"title\":\"Insolación — capítulo XIV\",\"blocks\":[{\"heading\":false,\"text\":\"Vaya, Pardo... Es V. terrible. ¿Me quiere V. igualar la moral de los hombres con la de las mujeres?\"},{\"heading\":false,\"text\":\"--Paquita... dejémonos de _clichés_.--(Pardo usaba muy á menudo esta palabrilla para condenar las frases ó ideas vulgares.)--Tanto jabón llevan Vds. en las suelas del calzado como nosotros. Es una hipocresía detestable eso de acusarlas é infamarlas á Vds. con tal rigor por lo que en nosotros nada significa.\"},{\"heading\":false,\"text\":\"--¿Y la conciencia, señor mío? ¿Y Dios?\"},{\"heading\":false,\"text\":\"La dama argüía con cierta afectada solemnidad y severidad, bajo la cual velaba una satisfacción inmensa. Iban pareciéndole muy bonitos y sensatos los detestables sofismas del comandante, que así pervierte la pasión el entendimiento.\"},{\"heading\":false,\"text\":\"--¡La conciencia! ¡Dios!--exclamó él, remedando el tono enfático de la señora.--Otro registro. Bueno: toquémoslo también. ¿Se trata de pecadores creyentes? ¿Católicos, apostólicos, romanos?\"},{\"heading\":false,\"text\":\"--Por supuesto. ¿Ha de ser todo el mundo hereje como V.?\"},{\"heading\":false,\"text\":\"--Pues si tratamos de creyentes, la cuestión de conciencia es independiente de la de sexo. Aunque me llama V. hereje, todavía no he olvidado la doctrina; puedo decirle á V. de corrido los diez mandamientos... y se me figura que rezan igual con nosotros que con Vds. Y también sé que el confesor las absuelve y perdona á Vds. igualito que á nosotros. Lo que pide á la penitente el ministro de Dios es arrepentimiento, propósito de la enmienda. El mundo, más severo que Dios, pide la perfección absoluta, y si no... O todo ó nada.\"},{\"heading\":false,\"text\":\"--No, no; mire V. que también el confesor nos aprieta más las clavijas. Para Vds. la manga se ensancha un poquito...--repuso Asís, paladeando el deleite de aducir malas razones para saborear el gusto de verlas refutadas.\"},{\"heading\":false,\"text\":\"--Hija, si eso hacen, es por prudencia, para que no desertemos del confesonario si nos da por frecuentarlo... En el fondo, ningún confesor le dirá á V, que hay un pecado más para las hembras. Es decir, que la cosa queda reducida á las consecuencias positivas, exteriores..., al criterio social. En salvando éste, en no sabiéndose nada, el asunto no tiene más trascendencia en Vds. que en nosotros... Y en nosotros... ¡ayúdeme V. á sentir! (Al argüir así, el comandante castañeteaba los dedos.) Ahora, si V. me ataca por otro lado...\"},{\"heading\":false,\"text\":\"--Yo...--balbució la señora, sin pizca de ganas de atacar.\"},{\"heading\":false,\"text\":\"--Si me sale V. con el respeto y la estimación propia... con lo que cada cual se debe á sí mismo...\"},{\"heading\":false,\"text\":\"--Eso... lo que cada cual se debe á sí mismo--articuló Asís hecha una amapola.\"},{\"heading\":false,\"text\":\"--Convendré en que eso siempre realza á una mujer; pero, en gran parte, depende del criterio social. La mujer se cree infamada, después de una de esas caídas, ante su propia conciencia, porque le han hecho concebir desde niña que lo más malo, lo más infamante, lo irreparable, es eso; que es como el infierno, donde no sale el que entra. A nosotros nos enseñan lo contrario; que es vergonzoso para el hombre no tener aventuras, y que hasta queda humillado si las rehuye... De modo, que lo mismo que á nosotros nos pone muy huecos, á Vds. las envilece. Preocupaciones hereditarias emocionales, como diría Spencer. Y vaya unos terminachos que la suelto á V.\"},{\"heading\":false,\"text\":\"--No, si yo con su trato ya me voy haciendo una sabia. Todos los días me aporrea V. los oídos con cada palabrota...\"},{\"heading\":false,\"text\":\"--¿Y si yo le dijese á V.--prosiguió Pardo echándose á disertar--que _eso_ que llamé accesorio en las aventurillas, me parece á mí que en el cariño verdadero, cuando están unidas así, así, como si las pegasen con argamasa, las voluntades, llega á ser más accesorio aún? Es el complemento de otra cosa mucho más grande, que dura siempre, y que comprende eso y todo lo demás... Lo estoy embrollando, paisana. V. se ríe de mí: á callar.\"},{\"heading\":false,\"text\":\"Asís oía, oía con toda su alma, pareciéndole que nunca había tenido su paisano momentos tan felices como aquella noche, ni hablado tan discreta y profundamente. Los dichos del comandante, que al pronto lastimaban sus convicciones adquiridas, entraban, sin embargo, como bien disparadas saetas hasta el fondo de su entendimiento y encendían en él una especie de hoguera incendiaria, á cuya destructora luz veía tambalearse infinitas ideas de las que había creído más sólidas y firmes hasta entonces. Era como si le arrancasen del espíritu una muela dañada: dolor y susto al sentir el frío del instrumento y el tirón; pero después, un alivio, una sensación tan grata viéndose libre de aquel cuerpo muerto... Anestesia de la conciencia, con cloroformo de malas doctrinas, podría llamarse aquella operación quirúrgico-moral.\"},{\"heading\":false,\"text\":\"--Es un extravagante este hombre--pensaba la operada.--Decir, me está diciendo cosas estupendas... Pero se me figura que le sobra la razón por encima de los pelos. Habla por su boca la justicia. ¿Va una á creerse criminal por unos instantes de error? Siempre estoy á tiempo de pararme y no reincidir... ¡Claro que si por sistema!... Ni él tampoco dice eso, no... Su teoría es que ciertas cosas que suceden así... qué sé yo cómo, sin iniciativa ni premeditación por parte de uno, no han de mirarse como manchas de esas que ya nunca se limpian... El mismo Padre Urdax de fijo que no es tan severo en eso como la sociedad hipocritona... ¡Ay Dios mío! Ya estoy como mi paisano, echándole á la sociedad la culpa de todo.\"},{\"heading\":false,\"text\":\"Al llegar aquí de sus reflexiones la dama, la molestó un cosquilleo, primero entre las cejas, luego en la membrana de la nariz... ¡Aaach! Estornudó con ruido, estremeciéndose.\"},{\"heading\":false,\"text\":\"--¡Adiós! Ya se me ha resfriado V.--exclamó su amigo.--No está V. acostumbrada á estas vagancias al sereno... Levántese V. y paseemos.\"},{\"heading\":false,\"text\":\"--No, si no es el rocío lo que me acatarra á mí... He tomado sol.\"},{\"heading\":false,\"text\":\"--¿Sol? ¿Cuándo?\"},{\"heading\":false,\"text\":\"--Ayer..., digo, anteayer..., yendo..., sí, yendo á misa á las Pascualas. No crea V.: desde entonces ando yo regular, nada más que regularcita. Cuándo jaquecas, cuándo mareos...\"},{\"heading\":false,\"text\":\"--De todos modos... guíese V. por mí: caminemos, ¿eh? Si sobre la insolación le viene á V. un pasmo... ó coge V. unas intermitentes de estas de primavera en Madrid...\"},{\"heading\":false,\"text\":\"--No me asuste V.... Tengo poco de aprensiva--contestó la dama levantándose y envolviéndose mejor en el abrigo.\"},{\"heading\":false,\"text\":\"--¿A su casa de V.?\"},{\"heading\":false,\"text\":\"--Bien..., sí, vamos hacia allá despacio.\"},{\"heading\":false,\"text\":\"No siguió el comandante explanando sus disolventes opiniones hasta la misma puerta de la señora. Al abrirla Imperfecto, Asís convidó á su amigo á que descansase un rato; él se negó; necesitaba darse una vuelta por el Círculo Militar, leer los periódicos extranjeros y hablar con un par de amigos, á última hora, en Fornos. Deseó respetuosamente las buenas noches á la señora y bajó las escaleras á paso redoblado. Con el mismo echó calle abajo aquel gran despreocupado, nihilista de la moral: y nos consta que iba haciendo éste ó parecido soliloquio, idéntico al que, en igualdad de circunstancias, haría otra persona que pensase según todos los _clichés_ admitidos:\"},{\"heading\":false,\"text\":\"--Me ha engañado la viuda... Yo que la creía una señora impecable. Un apabullo como otro cualquiera. No he mirado las iniciales del tarjetero: serían... ¡vaya V. á saber! Porque en realidad, ni nadie murmura de ella, ni veo á su alrededor persona que... En fin, cosas que suceden en la vida; chascos que uno se lleva. Cuando pienso que á veces se me pasaba por la cabeza decirle algo formal... No, esto no es un _caballo muerto_, ¡qué disparate! es sólo un tropiezo del caballo... No he llegado á caerme... ¡Así fuesen los desengaños todos!...\"},{\"heading\":false,\"text\":\"Siguió caminando sin ver los árboles del Retiro, que se agrupaban en misteriosas masas á su derecha. Ni percibía el olor de las acacias. Pero él seguía oliendo, no á los cortesanos y pulidos vegetales de los paseos públicos, sino á otros árboles rurales, bravíos y libres: los que producen la morena castaña que se asa en los magostos de Noviembre, en el valle de los Pazos.\"}]},{\"title\":\"Insolación — capítulo XV\",\"blocks\":[{\"heading\":false,\"text\":\"La tarde del día siguiente la dedicó Asís á pagar visitas. Tarea maquinal y enfadosa, deber de los más irritantes que el pacto social impone. Raro es que nadie se someta á él sin murmurar, por fuera ó por dentro, del mundo y sus farsas. Menos mal cuando las visitas se hacen, como las hacía la dama, en piés ajenos. Entonces lo arduo de la faena empieza en las porterías. ¡Si todas las casas fuesen como la de Sahagún ó la de Torres-Nobles, por ejemplo! Allí, antes de llegar, ya llevaba Asís en la mano la tarjeta con el pico dobladito, y al sentir rodar el coche, ya estaba asomándose al ancho vano del portón el portero imponente, patilludo, correcto, amabilísimo, que recogía la tarjeta preguntando:--¿A dónde desea ir la señora?--para transmitir la orden al cochero. Los Torres-Nobles, los Sahagún, los Pinogrande y otras familias así, de muy alto copete, no recibían sino de noche alguna vez, y el llegarse á su casa para dejar la tarjeta representaba una fórmula de cortesía facilísima de cumplir al bajar al paseo ó al volver de las tiendas. Pero si entre las relaciones de Asís las había tan granadas, otras eran de muchísimo menos fuste, y algunas, procedentes de Vigo, rayaban en modestas. Y allí era el entrar en portales angostos, el parlamentar con porteras gruñonas, la desconsoladora respuesta:--Sí, señora, me paece que no ha salió en to el día de casa... Tercero con entresuelo, primero y principal... á mano izquierda.--Y la ascensión interminable, el sobrealiento, el tedio de subir por aquel caracol obscuro, con olores á cocina y á todas las oficinas caseras, y la cerril alcarreña que abre, y la acogida embarazosa, las empalagosas preguntitas, los chiquillos sucios y desgreñados, los relatos de enfermedades, la chismografía viguesa agigantada por la óptica de la distancia... Vamos, que era para renegar, y Asís renegaba en su interior, consultando, sin embargo, la lista de la cartera y diciendo con un suspiro profundo:--¡Ay! Aún falta la viuda de Pardiñas... la madre del médico de Celas..., y Rita, la hermana de Gabriel Pardo... Y esa si que es urgente... Ha tenido al chiquillo con difteria...\"},{\"heading\":false,\"text\":\"Por lo mismo que el ajetreo de las visitas había sido tan cargante, que á la mayor parte se las encontrara en casa y que no le sacaron sino conversaciones capaces de aburrir á una estatua de yeso, la dama regresaba á su vivienda con el espíritu muy sosegado. A semejanza de los devotos que si les hurga la conciencia se imponen la obligación de rezar tres rosarios seguidos y una serie considerable de padre nuestros, Asís, sintiéndose reo de perturbación social, ó al menos de amago de este delito, se consagraba á cumplir minuciosamente los ritos de desagravio, y como le habían producido tan soberano fastidio, juzgaba saldada más de la mitad de su cuenta. Por otra parte, encontrábase decidida--más que nunca--á cortar las irregularidades de su conducta presente. Tenía razón el comandante: la falta, bien mirado, no era tan inaudita; pero si trascendía al público, ¡ah! ¡entonces! Evitar el escándalo y la reincidencia, precaver lo venidero..., y se acabó. Cortar de raíz, eso sí, (la dama veía entonces la virtud en forma de grandes y afiladísimas tijeras, como las que usan los sastres). Y bien podía hacerlo, porque la verdad ante todo, su corazón no estaba interesado...--Vamos á ver--argüía para sí la señora.--Supongamos que ahora viniesen á decirme: Diego Pacheco se ha largado esta mañana á su tierra, donde parece que se casa con una muchacha preciosa... Nada: yo tan fresca, sin echar ni una lágrima. Hasta puede que diese gracias á Dios, viéndome libre de este grave compromiso. Pues la cosa es bien sencilla: ¿se había de ir él? Soy yo quien se larga. Así como así, días arriba ó abajo, ya estaba cerca el de irse á veranear... Pues adelanto el veraneo un poquillo... y corrientes.--¡Qué descanso tomar el tren! Se concluían aquellos recelos incesantes, aquel volver el rostro cuando la Diabla le preguntaba alguna cosa, aquella tartamudez, aquella vergüenza, vergüenza tonta en una viuda, que al fin y al cabo era libre y no tenía que dar á nadie cuenta de sus actos...\"},{\"heading\":false,\"text\":\"Pensaba en estas cosas cuando se apeó y empezó á subir la escalera de su casa. Aún no estaba encendida la luz, caso frecuente en las tardes veraniegas. Al segundo tramo... ¡Dios nos asista! Un hombre que se destaca del obscuro rincón... ¡Pacheco!\"},{\"heading\":false,\"text\":\"Reprimió el chillido. El meridional la cogía ambas manos con violencia.\"},{\"heading\":false,\"text\":\"--¿Cómo está mi niña? Tres veces he venido y siempre te negaron... Lo que es una de ellas juro que estabas en casa... Si no quieres verme, dímelo á mí, que no vendré... Te miraré de lejitos en el paseo ó en el teatro... Pero no me despidas con una criada, que se ríe de mí al darme con la puerta en las narices.\"},{\"heading\":false,\"text\":\"--No... pero si yo...--contestaba aturdida la señora.\"},{\"heading\":false,\"text\":\"--¿No se había negado la nena para mí?\"},{\"heading\":false,\"text\":\"--No, para ti no...--afirmó rápidamente Asís con acento de sinceridad: tan espontáneo é inevitable suele ser en ciertas ocasiones el engaño.\"},{\"heading\":false,\"text\":\"--Pues, entonces, vengo esta noche. ¿Sí? Esta noche á las nueve.\"},{\"heading\":false,\"text\":\"Hizo la dama un expresivo movimiento.\"},{\"heading\":false,\"text\":\"--¿No quieres? ¿Tienes compromiso de salir, de ir á alguna parte? La verdad, chiquilla. Me largaré como aquel á quien le han dado cañaso, pero no porfiaré. Me sabe mal porfiar. Por mí no has de tener tú media hora de disgusto.\"},{\"heading\":false,\"text\":\"Asís titubeaba. Cosa rara y sin embargo explicable dentro de cierto misterioso ilogismo que impone á la conducta femenina la difícil situación de la mujer: lo que decidió su respuesta afirmativa fué cabalmente la resolución de poner tierra en medio que acababa de adoptar en el coche.\"},{\"heading\":false,\"text\":\"--Bueno, á las nueve... (Pacheco la apretó contra sí.) ¿Pero... te irás á las diez?\"},{\"heading\":false,\"text\":\"--¿A las diez? Es tanto como no venir... Tú tienes que hacer hoy: dímelo así, clarito.\"},{\"heading\":false,\"text\":\"--Que hacer no... Por los criados. No me gusta dar espectáculo á esa gente.\"},{\"heading\":false,\"text\":\"--El chico no importa, es un bausán... La chica es más avispada. Mándala con un recado fuera... Hasta pronto.\"},{\"heading\":false,\"text\":\"Y Pacheco ocultó la cara en el pelo de la señora, descomponiéndolo y echándola el sombrero hacia atrás. Ella se lo arregló antes de llamar, lo cual hizo con pulso trémulo.\"},{\"heading\":false,\"text\":\"Iba muy preocupada, mucho. Se desnudó distraídamente, dejando una prenda aquí y otra acullá; la Diabla las recogía y colgaba, no sin haberlas sacudido y examinado con un detenimiento que á Asís le pareció importuno. ¿Por qué no rehusar firmemente la dichosa cita?... Sí, sería mejor; pero al fin, para el tiempo que faltaba... Volvióse hacia la doncella.\"},{\"heading\":false,\"text\":\"--Mira, revisarás el mundo grande...: creo que tiene descompuestas las bisagras. Acuérdate mañana de ir á casa de Madama Armandina...; puede que ya estén los sombreros listos... Si no están, la das prisa. Que quiero marcharme pronto, pronto.\"},{\"heading\":false,\"text\":\"--¿A Vigo, señorita?--preguntó la Diabla con hipócrita suavidad.\"},{\"heading\":false,\"text\":\"--¿Pues á dónde? También te darás una vuelta por el zapatero... y á ver si en la plazuela del Angel tienen compuesto el abanico.\"},{\"heading\":false,\"text\":\"Dictando estas órdenes se calmaba. No, el rehusar no era factible. Si le hubiese despedido esta noche, él querría volver mañana. Disimulo, transigir... y, como decía él..., _najencia_.\"},{\"heading\":false,\"text\":\"Comió poco; sentía esa constricción en el diafragma, inseparable compañera de las ansiedades y zozobras del espíritu. Miraba frecuentemente para la esfera del reloj, el cual no señalaba más que las ocho al levantarse la señora de la mesa.\"},{\"heading\":false,\"text\":\"--Oye, Angela...\"},{\"heading\":false,\"text\":\"Faltábale saliva en la boca; la lengua se le pegaba al velo del paladar.\"},{\"heading\":false,\"text\":\"--Oye, hija... ¿Quieres... irte á pasar esta noche con tu hermana, la casada con el guardia civil? ¿Eh?\"},{\"heading\":false,\"text\":\"--¡Ay señorita!... Yo, con mil amores... Pero vive tan lejos: el cuartel lo tienen allá en las Peñuelas... Mientras se va y se viene...\"},{\"heading\":false,\"text\":\"--Es lo de menos... Te pago el tranvía... ó un simón. Lo que te haga falta... Y aunque vuelvas después de... media noche, ¿eh? no dejarán de abrirte. Come á escape... Mira, ¿no tiene tu hermana una niña de seis años?\"},{\"heading\":false,\"text\":\"--De ocho, señorita, de ocho... Y un muñeco de trece meses que anda con la dentición.\"},{\"heading\":false,\"text\":\"--Bien: á la niña podrá servirle, arreglándola... Le llevas aquella ropa de Marujita que hemos apartado el otro día...\"},{\"heading\":false,\"text\":\"--Dios se lo pague... ¿También el sombrero de castor blanco, con el pájaro?\"},{\"heading\":false,\"text\":\"--También... Anda ya.\"},{\"heading\":false,\"text\":\"El sombrero de castor produjo excelente efecto. Imaginaba siempre la señora que, de algunos días á esta parte, su doncella se atrevía á mirarla y hablarla ya con indefinible acento severo, ya con disimulada entonación irónica; pero después de tan espléndida donación, por más que aguzó la malicia, no pudo advertir en el gracioso semblante de la criada sino júbilo y gratitud. Comió la Diabla en tres minutos: ni visto ni oído: y á poco se presentó á su ama muy maja y pizpireta, con traje dominguero, el pelo rizado á tenacilla, botas que cantaban.\"},{\"heading\":false,\"text\":\"--Vete, hija, ya debe de ser tarde... Las nueve menos cuarto...\"},{\"heading\":false,\"text\":\"--No, señorita... Las ocho y veinticinco por el comedor... ¿Tiene algo que mandar? ¿Quiere alguna cosa?...\"},{\"heading\":false,\"text\":\"--Nada, nada... Que lo pases bien... ¡Qué elegante te has puesto!... ¿Allí habrá gente, eh? ¿Guardias civiles? ¿Jóvenes?\"},{\"heading\":false,\"text\":\"--Algunos... Hay uno de nuestra tierra... de la provincia de Pontevedra, de Marín..., alto él, con bigote negro.\"},{\"heading\":false,\"text\":\"--Bien, hija... Pues lo que es por mí, ya puedes marcharte.\"},{\"heading\":false,\"text\":\"¿Qué haría aquella maldita Diabla, que un cuarto de hora después de recibidas semejantes despachaderas aún no había tomado el portante? Con el oído pegado á la puertecilla falsa de su dormitorio, que caía al pasillo, Asís espiaba la salida de su doncella, mordiéndose los labios de impaciencia nerviosa. Al fin sintió pasitos, taconeo de calzado flamante, oyó una risotada, un _¡divertirse y gastar poco!_ que venía de la cocina... La puerta se abrió, hizo ¡puum! al cerrarse... ¡Ay, gracias á Dios!\"},{\"heading\":false,\"text\":\"Así que se fué la condenada chica, parecióle á la señora que todo el piso se había quedado en un silencio religioso, en un recogimiento inexplicable. Hasta la lámpara del saloncito alumbraba, si cabe, con luz más velada, más dulce que otras noches. Eran las nueve menos cuarto: Pacheco aun tardaría cosa de veinte minutos... Se oyó un campanillazo sentimental, tímido, como si la campanilla recelase pecar de indiscreta...\"}]},{\"title\":\"Insolación — capítulo XVI\",\"blocks\":[{\"heading\":false,\"text\":\"Era Pacheco, envuelto en su capa de embozos grana, impropia de la estación, y de hongo. Detúvose en la puerta como irresoluto, y Asís tuvo que animarle:\"},{\"heading\":false,\"text\":\"--Pase V...\"},{\"heading\":false,\"text\":\"Entonces el galán se desembozó resueltamente y se informó de cómo andaba la salud de Asís.\"},{\"heading\":false,\"text\":\"En los primeros momentos de sus entrevistas, siempre se hablaban así, empleando fórmulas corteses y preguntando cosas insignificantes; su saludo era el saludo de ordenanza en sociedad: estrecharse la mano. Ni ellos mismos podrían explicar la razón de este procedimiento extraño, que acaso fuese la cortedad debida á lo reciente é impensado de su trato amoroso. No obstante, algo especial y distinto de otras veces notaría el andaluz en la señora, que al sentarse en el diván á su lado, murmuró después de una embarazosa pausa:\"},{\"heading\":false,\"text\":\"--¡Qué fría me recibes! ¿Qué tienes?\"},{\"heading\":false,\"text\":\"--¡Qué disparate! ¿Qué voy á tener?\"},{\"heading\":false,\"text\":\"--¡Ay prenda, prenda! A mí no se me engaña... Soy perro viejo en materia de mujeres. Estorbo. Tú tenías algún plan esta noche.\"},{\"heading\":false,\"text\":\"--Ninguno, ninguno--afirmó calurosamente Asís.\"},{\"heading\":false,\"text\":\"--Bien, lo creo. Eso sí que lo has dicho como se dicen las verdaes. Pero, en plata: que no te pinchaban á ti las ganas de verme. Hoy me querías tú á cien leguas.\"},{\"heading\":false,\"text\":\"Aseveró esto metiendo sus dedos largos, de pulcras uñas, entre el pelo de la señora, y complaciéndose en alborotar el peinado sobrio, sin postizos ni rellenos, que Asís trataba de imitar del de la Pinogrande, maestra en los toques de la elegancia.\"},{\"heading\":false,\"text\":\"--Si no quisiese recibirte, con decírtelo...\"},{\"heading\":false,\"text\":\"--Así debiera ser... el corasonsillo en la mano... Pero á veces se le figura á uno que está comprometido á pintar afecto, ¿sabes tú?, por caridad ó qué sé yo por qué... Si yo lo he hecho á cada rato con un ciento de novias y de querías... Harto de ellas por cima de los pelos... y empeñado en aparentar otra cosa... porque es fuerte eso de estamparle á un hombre ó á una hembra en su propia cara:--Ya me tiene V. hasta aquí... no me hace V. ni tanto de ilusión.\"},{\"heading\":false,\"text\":\"--¿Quién sabe si eso te estará pasando á ti conmigo?--exclamó Asís festivamente, echándolas de modesta.\"},{\"heading\":false,\"text\":\"No contestó el meridional sino con un abrazo vehemente, apretado, repentino, y un--_¡ojalá!_--salido del alma, tan ronco y tan dramático, que la dama sintió rara conmoción, semejante á la del que, poniendo la mano sobre un aparato eléctrico, nota la sacudida de la corriente.\"},{\"heading\":false,\"text\":\"--¿Por qué dices _ojalá_?--preguntó, imitando el tono del andaluz.\"},{\"heading\":false,\"text\":\"--Porque esto es de más; porque nunca me vi como me veo; porque tú me has dado á beber zumo de hierbas desde que te he conocío, chiquilla... Porque estoy mareado, chiflado, loco, por tus pedasos de almíbar... ¿Te enteras? Porque tú vas á ser causa de la perdición de un hombre, lo mismo que Dios está en el sielo y nos oye y nos ve... Terroncito de sal, ¿qué tienes en esta boca, y en estos ojos, y en toda tu persona, para que yo me ponga así? A ver, dímelo, gloria, veneno, sirena del mar.\"},{\"heading\":false,\"text\":\"La señora callaba, aturdida, no sabiendo qué contestar á tan apasionadas protestas; pero vino á sacarla del apuro un estruendo inesperado y desapacible, el alboroto de una de esas músicas ratoneras antes llamadas _murgas_, y que en la actualidad, por la manía reinante de elevarlo todo, adoptan el nombre de _bandas populares_.\"},{\"heading\":false,\"text\":\"--¡Oiga! ¿Nos dan cencerrada ya los vecinos del barrio?--gritó Pacheco, levantándose del sofá y entreabriendo las vidrieras.--¡Y cómo desafinan los malditos!... Ven á oir, chiquilla, ven á oir. Verás cómo te rompen el tímpano.\"},{\"heading\":false,\"text\":\"En el meridional no era sorprendente este salto desde las ternezas más moriscas al más prosaico de los incidentes callejeros: estaba en su modo de ser la transición brusca, la rápida exteriorización de las impresiones.\"},{\"heading\":false,\"text\":\"--Mira, ven--continuó.--Te pongo aquí una butaca y nos recreamos. ¿A quién le dispararán la serenata?\"},{\"heading\":false,\"text\":\"--A un almacén de ultramarinos que se ha estrenado hoy--contestó Asís recordando casualmente chismografías de la Diabla.--En la otra acera, pocas casas más allá de la de enfrente. Aquella puerta... allí. ¡Ya tenemos música para rato!\"},{\"heading\":false,\"text\":\"Pacheco arrastró un sillón hacia la ventana y se sentó en él.\"},{\"heading\":false,\"text\":\"--¡Desatento!--exclamó riendo la señora.--¿Pues no decías que era para mí?\"},{\"heading\":false,\"text\":\"--Para ti es--respondió el amante cogiéndola por la cintura y obligándola quieras ó no quieras á que se acomodase en sus rodillas. Se resistió algo la dama, y al fin tuvo que acceder. Pacheco la mecía como se mece á las criaturas, sin permitirse ningún agasajo distinto de los que pueden prodigarse á un niño inocente. Por forzosa exigencia de la postura, Asís le echó un brazo al cuello, y después de los primeros minutos, reposó la cabeza en el hombro del andaluz. Un airecillo delgado, en que flotaban perfumes de acacia y ese peculiar olor de humo y ladrillo recaliente de la atmósfera madrileña en estío, entraba por las vidrieras, intentaba en balde mover las cortinas, y traía fragmentos de la música chillona, tolerable á favor de la distancia y de la noche, hora que tiene virtud para suavizar y concertar los más discordantes sonidos. Y la proximidad de los dos cuerpos ocupando un solo sillón, estrechaba también, sin duda, los espíritus, pues por vez primera en el curso de aquella historia entablóse entre Pacheco y la dama un cuchicheo íntimo, cariñoso, confidencial.\"},{\"heading\":false,\"text\":\"No hablaban de amor: versaba el coloquio sobre esas cosas que parecen muy insignificantes escritas y que en la vida real no se tratan casi nunca sino en ocasiones semejantes á aquella, en minutos de imprevista efusión. Asís menudeaba preguntas, exigiendo detalles biográficos: ¿Qué hacía Pacheco? ¿Por dónde andaba? ¿Cómo era su familia? ¿La vida anterior? ¿Los gustos? ¿Las amistades? ¿La edad justa, justa, por meses, días y no sé si horas?\"},{\"heading\":false,\"text\":\"--Pues yo soy más vieja que tú--murmuró pensativa, así que el gaditano hubo declarado su fe de bautismo.\"},{\"heading\":false,\"text\":\"--¡Gran cosa! Será un añito, ó medio.\"},{\"heading\":false,\"text\":\"--No, no, dos lo menos. Dos, dos.\"},{\"heading\":false,\"text\":\"--Corriente, sí, pero el hombre siempre es más viejo, cachito de gloria, porque nosotros vivimos; ¿te enteras? y vosotras no. Yo, en particular, he vivido por una docena. No imaginarás diablura que yo no haya catado. Soy maestro en el arte de hacer desatinos. ¡Si tú supieses algunas cosas mías!\"},{\"heading\":false,\"text\":\"Asís sintió una curiosidad punzante unida á un enojo sin motivo.\"},{\"heading\":false,\"text\":\"--Por lo visto eres todo un perdis, buena alhaja.\"},{\"heading\":false,\"text\":\"--¡Quiá!... ¿Perdis yo? Di que no, nena mía. Yo galanteé á trescientas mil mujeres, y ahora me parece que no quise á ninguna. Yo hice cuanto disparate se puede hacer, y al mismo tiempo no tengo vicios. ¿Dirás que cómo es ese milagro? Siendo... ahí verás tú. Los vicios no prenden en mí. Ninguno arraiga, ni arraigará jamás. Aún te declaro otra cosa; que no sólo no se me puede llamar vicioso, sino que si me descuido acabo por santo. Es según los lados á que me arrimo. ¿Me ponen en circunstancias de ser perdío? No me quedo atrás. ¿Que tocan á ser bueno? Nadie me gana. Si doy con gente arrastrada, ¿qué quieres tú?\"},{\"heading\":false,\"text\":\"--¿Hasta en lo tocante á la honra te dejarías llevar?--preguntó algo asustada Asís.\"},{\"heading\":false,\"text\":\"El gaditano se echó atrás como si le hubiese picado una sierpe.\"},{\"heading\":false,\"text\":\"--¡Hija! Vaya unas cosillas que me preguntas. ¿Me has tomado por algún secuestrador? Yo no secuestro más que á las hembras de tu facha. Pero ya sabes que en mi tierra, las pendencias no se cuentan por delitos... He _enfriado_ á un infeliz... que más quisiera no haberle tocado al pelo de la ropa. Dejémoslo, que importa un pito. Fuera de esas trifulcas, no ha tenío el diablo por donde cogerme: he jugado, perdiendo y ganando un dinerillo... regular; he bebío... vamos, que no me falta á mí saque; de novias y otros enredos... De esto estaría muy feo que te contase ná. Chitito. ¿Un cariño á tu rorro?\"},{\"heading\":false,\"text\":\"--Vamos, que eres la gran persona--protestó escandalizada Asís, desviándose en vez de acercarse como Pacheco pretendía.\"},{\"heading\":false,\"text\":\"--No lo sabes bien. Eso es como el Evangelio. Yo quisiera averiguar pa qué me ha echado Dios á este mundo. Porque soy, además de tronerilla, un haragán y un zángano de primera, niña del alma... No hago cosa de provecho, ni ganas de hacerla. ¿A qué? Mi padre, empeñao el buen señor en que me luzca y en que sirva al país, y dale con la chifladura de que me meta en política, y tumba con que salga diputao, y vaya á hacer el bu al Congreso... ¡En el Congreso yo! A mí, lo que es asustarme, ni el Congreso ni veinte Congresos me asustan. La farsa aquella no me pone miedo. Te aviso que en todo cuanto me propongo salir avante, salgo y sin grandes fatigas: ¡qué! Pero á decir verdad, no me he tomado nunca trabajos así enormes, como no fuese por alguna mujer guapa. No soy memo ni lerdo, y si quisiese ir allí á pintar la mona como Albareda, la pintaría, figúrate. ¿Que se me ha muerto mi abuelita? ¡Si es la pura verdad! Sólo que too eso porque tanto se descuaja la gente, no vale los sudores que cuesta. En cambio... ¡una mujer como tú!...\"},{\"heading\":false,\"text\":\"Díjolo al oído de la dama, á quien estrechó más contra sí.\"},{\"heading\":false,\"text\":\"--Sólo esto, terrón de azúcar, sólo esto sabe bien en el mundo amargo... Tener así á una mujer adorándola... Así, apretadica, metida en el corasón... Lo demás... pamplina.\"},{\"heading\":false,\"text\":\"--Pero eso es atroz--protestó severamente Asís, cuya formalidad cantábrica se despertaba entonces con gran brío.--¿De modo que no te avergüenzas de ser un hombre inútil, un mequetrefe, un cero á la izquierda?\"},{\"heading\":false,\"text\":\"--¿Y á ti qué te importa, lucerito? ¿Soy inútil pa quererte? ¿Has resuelto no enamorarte sino de tipos que mangoneen y anden agarraos á la casaca de algún ministro? Mira... Si te empeñas en hacer de mí un personaje, una notabilidad... como soy Diego que te sales con la tuya. Daré días de gloria á la patria; ¿no se dice así? Aguarda, aguarda..., verás qué registros saco. Proponte que me vuelva un Castelar ó un Cánovas del Castillo, y me vuelvo... ¡Ole que sí! ¿Te creías tú que alguno de esos panolis vale más que este nene? (Sólo que ellos largaron todo el trapo y yo recogí velas.). Por no deslucirlos. Modestia pura.\"},{\"heading\":false,\"text\":\"No había más remedio que reirse de los dislates de aquel tarambana, y Asís lo hizo; al reirse hubo de toser un poco.\"},{\"heading\":false,\"text\":\"--¡Ea! ya te me acatarraste--exclamó el gaditano consternadísimo.--Hágame V. el obsequio de ponerse algo en la cabeza... Así, tan desabrigada... ¡Loca!\"},{\"heading\":false,\"text\":\"--Pero si nunca me pongo nada, ni... No soy enclenque.\"},{\"heading\":false,\"text\":\"--Pues hoy te pondrás, porque yo lo mando. Si aciertas á enfermar, me suicido.\"},{\"heading\":false,\"text\":\"Saltó Asís de brazos de su adorador, muerta de risa, y al saltar perdió una de sus bonitas chinelas, que por ser sin talón, á cada rato se le escurrían del pié. Recogióla Pacheco, calzándosela con mil extremos y zalamerías. La dama entró en su alcoba, y abriendo el armario de luna empezó á buscar á tientas una toquilla de encaje para ponérsela y que no la marease aquel pesado. Vuelta estaba de espaldas á la poca luz que venía del saloncito, cuando sintió que dos brazos la ceñían el cuerpo. En medio de la lluvia de caricias delirantes que acompañó á demostración tan atrevida, Asís entreoyó una voz alterada, que repetía con acento serio y trágico:\"},{\"heading\":false,\"text\":\"--¡Te adoro... Me muero, me muero por ti!\"},{\"heading\":false,\"text\":\"Parecía la voz de otro hombre; hasta tenía ese _trémolo_ penoso que da al acento humano el rugir de las emociones extraordinarias comprimido en la garganta por la voluntad. Impresionada, Asís se volvió soltando la toquilla.\"},{\"heading\":false,\"text\":\"--Diego...--tartamudeó llamando así á Pacheco por primera vez.\"},{\"heading\":false,\"text\":\"--¿Por qué no dices _Diego mío, Diego del alma_?--exclamó con fuego el andaluz deshaciéndola entre sus brazos.\"},{\"heading\":false,\"text\":\"--Qué sé yo... Cuando uno habla así... me parece cosa de novela ó de comedia. Es una ridiculez.\"},{\"heading\":false,\"text\":\"--¡Prueba... prueba... ¡Ay! ¡Cómo lo has dicho! _¡Diego mío!_--prorrumpió él remedando á la señora, al mismo tiempo que la soltaba casi con igual violencia que la había cogido.--¡Pedazo de hielo! ¡Vaya unas hembras que se gastan en tu país!... ¡Marusiñas! ¡Reniego de ellas todas! ¡Que las echen al carro de la basura!\"},{\"heading\":false,\"text\":\"--Mira--dijo la dama tomándolo otra vez á risa--eres un cómico y un orate... No hay modo de ponerse seria con un tipo como tú. A ver: aquí está un señorito que ha tenido cuatrocientas novias y dos mil líos gordos, y ahora se ha prendado de mí como el Petrarca de la señora Laura... De mí nada más: privilegio exclusivo, patente del Gobierno.\"},{\"heading\":false,\"text\":\"--Tómalo á guasa... Pues es tan verdad como que ahora te agarro la mano. Yo tuve un millón de devaneos, conformes; pero en ninguno me pasó lo que ahora. ¡Por éstas, que son cruces! Quebraeros de cabesa míos, novias y demás, me las encuentro en la calle y no las conozco. A ti... te dibujaría, si fuese pintor, á obscuras. Tan clavadita te tengo. De aquí á cincuenta años, cayéndote de vieja, te conocería entre mil viejas más. Otras historias las seguí por vanidad, por capricho, por golosina, por terquedad, por matar el tiempo... Me quedaba un rincón aquí, donde no ha puesto el pié nadie, y tenía yo guardaa la llave de oro para ti, prenda morena... ¿Qué, lo dudas? Mira, haz un ensayo... Por gusto.\"},{\"heading\":false,\"text\":\"Arrastró á la dama hacia el salón y se recostó en el diván; tomó la mano de Asís y la colocó extendida sobre el lado izquierdo de su chaleco. Asís sintió un leve y acompasado vaivén, como de péndulo de reloj. Pacheco tenía los ojos cerrados.\"},{\"heading\":false,\"text\":\"--Estoy pensando en otras mujeres, chiquilla... Quieta..., atención, observa bien.\"},{\"heading\":false,\"text\":\"--No late nada fuerte--afirmó la señora.\"},{\"heading\":false,\"text\":\"--Déjate un rato así... Pienso en mi última novia, una rubia que tenía un talle de lo más fino que se encuentra en el mundo... ¿Ves qué quietecillo está el pájaro? Ahora... dime tú... ¡si puedes! alguna cosa tierna... Mas que no sea verdá.\"},{\"heading\":false,\"text\":\"Asís discurría una gran terneza y buscaba la inflexión de voz para pronunciarla. Y al fin salió con esta eterna vulgaridad:\"},{\"heading\":false,\"text\":\"--¡Vida mía!\"},{\"heading\":false,\"text\":\"Bajo la palma de la señora, el corazón de Pacheco, como espíritu foleto que obedece á un conjuro, rompió en el más agitado baile que puede ejecutar semejante víscera. Eran saltos de ave azorada que embiste contra los hierros de su cárcel... El meridional entreabrió las azules pupilas; su tez tostada había palidecido algún tanto; con extraña prisa se levantó del sofá y fué derecho al balcón, donde se apoyó como para beber aire y rehacerse de algún trastorno físico y moral. Asís, inquieta, le siguió y le tocó en el brazo.\"},{\"heading\":false,\"text\":\"--Ya ves qué majadero soy...--murmuró él volviéndose.\"},{\"heading\":false,\"text\":\"--¿Pero te pasa algo?\"},{\"heading\":false,\"text\":\"--Ná...--El gaditano se apartó del balcón, y viniendo á sentarse en un _puf_ bajito, y rogando á Asís con la mirada que ocupase el sillón, apoyó la cabeza, en el regazo de la dama.--Con sólo dos palabritas que tú me dijiste... Haz favor de no reirte, mona, porque donde me ves tengo mal genio... y puede que soltase un desatino. Desde que me he entontecido por ti, estoy echando peor carácter. Calladita la niní... Deje dormir á su rorro.\"},{\"heading\":false,\"text\":\"Pacheco cruzó el umbral de aquella casa antes de sonar la media noche. La Diabla no había regresado aún. Cuando el gaditano, según costumbre hasta entonces infructuosa, se volvió desde la esquina de la calle mirando hacia los balcones de Asís, pudo distinguir en ellos un bulto blanco. La señora exponía sus sofocadísimas mejillas al aire fresco de la noche, y la embriaguez de sus sentidos y el embargo de sus potencias empezaban á disiparse. Como náufrago arrojado á la costa, que volviendo en si toca con placer el cinto de oro que tuvo la precaución de ceñirse al sentir que se hundía el buque, Asís se felicitaba por haber conservado el átomo de razón indispensable para no acceder á cierta súplica insensata.\"},{\"heading\":false,\"text\":\"--¡Buena la hacíamos! Mañana estaban enterados vecinos, servicio, portero, sereno, el diablo y su madre. ¡Ay Dios mío!... ¡Me sigue, me sigue el mareo aquel de la verbena... y lo que es ahora no hay álcali que me lo quite!... ¡Qué mareo ni qué!... Mareo, alcohol, insolación... ¡Pretextos, tonterías!... Lo que pasa es que me gusta, que me va gustando cada día un poco más, que me trastorna con su palabrería..., y punto redondo. Dice que yo le he dado bebedizos y hierbas... El sí que me va dando á comer sesos de borrico... y nada, que no me desenredo. Cuando se va, reflexiono y caigo en la cuenta; pero en viéndole... acabóse, me perdí.\"},{\"heading\":false,\"text\":\"Llegada á este capítulo, la dama se dedicó á recordar mil pormenores, que reunidos formaban lindo mosaico de gracias y méritos de su adorador. La pasión con que requebraba; el donaire con que pedía; la gentileza de su persona; su buen porte, tan libre del menor conato de gomosería impertinente como de encogimiento provinciano; su rara mezcla de espontaneidad popular y cortesía hidalga; sus rasgos calaverescos y humorísticos unidos á cierta hermosa tristeza romántica (conjunto, dicho sea de paso, que forma el hechizo peculiar de los _polos_, _soleares_ y demás canciones andaluzas), eran otros tantos motivos que la dama se alegaba á sí propia para excusar su debilidad y aquella afición avasalladora que sentía apoderarse de su alma. Pero al mismo tiempo, considerando otras cosas, se increpaba ásperamente.\"},{\"heading\":false,\"text\":\"--No darle vueltas: aquí no hay nada superior, ni siquiera bueno: hay un truhán, un vago, un perdis... Todo eso que me dice de que sólo á mí... Ardides, trapacerías, costumbre de engañar, mañitas de calavera. En volviendo la esquina... (Pacheco acababa de verificar, hacía pocos minutos, tan sencillo movimiento), ya ni se acuerda de lo que me declama. Estos andaluces nacen actores... Juicio, Asís... juicio. Para estas tercianas, hija mía, píldoras de camino de hierro... y extracto de Vigo, mañana y tarde, durante cuatro meses. ¡Bahía de Vigo, cuándo te veré!\"},{\"heading\":false,\"text\":\"El airecillo de la noche, burlándose de la buena señora, compuso con sus susurros delicados estas palabras:\"},{\"heading\":false,\"text\":\"--Terronsito e asúcar..., gitana salá.\"}]},{\"title\":\"Insolación — capítulo XVII\",\"blocks\":[{\"heading\":false,\"text\":\"MUY atareadas estaban la marquesa viuda de Andrade y su doncella en revisar los mundos, sacos y maletillas, operación necesaria cuando se va á emprender un viaje. Y mire V. que parece cosa del mismo enemigo. Siempre en los últimos momentos han de faltar las llaves de los baúles. Por mucho que uno las coloque en sitio determinado, diciendo para sí:--En este cajón se queda la llavecita; no olvidar que aquí la puse; le ato á un estambre colorado, para acordarme mejor; no sea que el día de la marcha salgamos con que se ha obscurecido,--viene el instante crítico, la busca uno, y... ¡echarle un galgo! Nada, no parece: venga el cerrajero, tiznado, sucio, preguntón, insufrible; haga una nueva, y lléveselo todo la trampa.\"},{\"heading\":false,\"text\":\"Nerviosa y displicente, daba Asís á la Angela estas quejas. El ajetreo del viaje la ponía de mal humor: ¡son tan cargantes los preparativos! ¡Qué babel, qué trastorno! Nunca sabe uno lo que conviene llevar y lo que debe dejarse; cree no necesitar ropa de abrigo, porque al fin se viene encima la canícula, pero ¡fíese V. de aquel clima gallego, tan inconstante, tan húmedo, tan lluvioso, que tiene seis temperaturas diferentísimas en cada veinticuatro horas! Se quedan aquí las prendas en el ropero, muertas de risa, y allá tirita uno ó tiene que envolverse en mantones como las viejas... Luego, las fiestecitas, los bailes dichosos de la Pastora, que obligan á ir provisto de trajes de sociedad, porque si uno se presenta sencillo, de seda cruda, les choca y se ofenden y critican... Nada, que la última hora es para volverse loco. ¿A que no se había acordado Angela de pasarse por casa de la Armandina, á ver si tiene lista la pamela de la niña y el pajazón? ¿Apostemos á que el impermeable aún está con los mismos botones, que lastiman y en todo se prenden? ¿Y el alcanfor para poner en el abrigo de nutria? ¿Y la pimienta para que no se apolillase el tapiz de la sala?\"},{\"heading\":false,\"text\":\"Atarugada y dando vueltas de aquí para allí, la Diabla contestaba lo mejor posible al chaparrón de advertencias, reconvenciones y preguntas de su señora. La hábil muchacha, después de los primeros pases, conocía una estocada certera para su ama: si los preparativos de viaje andaban algo retrasados, era que la señorita aquel año había dispuesto la marcha un mes antes que de costumbre, por lo menos; también á ella (la Diabla) se le quedaba sin alistar un vestido de percal, y calzado, y varias menudencias; ella creía que hasta mediados de Junio, hacia el día de San Antonio... ¿Cómo se le había de ocurrir que se largaban tan de prisa y corriendo? La señora contestaba con reprimido suspiro, callaba dos minutos, y luego, redoblando su gruñir, corría del cuarto-ropero al dormitorio, de la leonera ó cuarto de los baúles al saloncito, y aun se determinaba á entrar en la cocina y el comedor, para regañar á Imperfecto que no le había traído á su gusto papel de seda, bramante, puntas de París, algodón en rama... Imperfecto, con la boca abierta y la fisonomía estúpida, subía y bajaba cien veces la escalera haciendo recados: las puntas eran gordas, se precisaban otras más chiquitas; el algodón no convenía blanco, sino gris: era para rellenar huecos en ciertos cajones y que no se estropease lo que iba dentro... En una de estas idas y venidas del criado, la señora cruzaba el pasillo, cuando repicó la campanilla. Impremeditadamente fué á abrir--cosa que no hacía nunca--y se encontró cara á cara con su Diego.\"},{\"heading\":false,\"text\":\"El primer movimiento fué de despecho y contrariedad mal encubierta. ¿Quién contaba con Pacheco á tales horas? (las diez y media de la mañana). No estaba Asís lo que se llama hecha un pingo, con traje roto y zapatos viejos, porque ni en una isla desierta se pondría ella en semejante facha; pero su bata de chiné blanco tenía manchas y visos obscuros, y aun no sé si alguna telaraña, indicio de la lidia con los baúles de la leonera; su peinado, revuelto sin arte, con rabos y mechones, saliendo por aquí y por acullá, parecía obra de peluquería gatuna; y en la superficie del pelo y del rostro se había depositado un sutil viso polvoriento, que la señora percibía vagamente al pestañear y al pasarse la lengua por los labios, y que la impacientaba lo indecible. Y en cambio, el galán venía todo soplado, con una camisa y un chaleco como el ampo de la nieve, el ojal guarnecido de fresquísimo clavel, guantes de piel de perro flamantitos, y, en suma, todas las señales de haberse acicalado mucho. En la mano traía el pretexto de la visita madrugadora: dos libros medianamente gruesos.\"},{\"heading\":false,\"text\":\"--Las novelas francesas que le prometí...--dijo en voz alta, después del cambio de saludos, porque la dama le había hecho seña con el mirar de que había moros en la costa.--Si está V. ocupada, me retiro... Si no, entraré diez minutos...\"},{\"heading\":false,\"text\":\"--Con mucho gusto... A la sala: el resto de la casa está imposible... no quiero que se asuste V. del estado en que se encuentra.\"},{\"heading\":false,\"text\":\"Entró Pacheco en la sala; pero por aprisa que Angela cerrase las puertas de las habitaciones interiores, el gaditano pudo ver baúles abiertos, con las bandejas fuera, ropa desparramada, cajas, sacos...\"},{\"heading\":false,\"text\":\"--¿Está V. de mudanza... ó de viaje?--preguntó, quedándose de pié en medio del saloncito, con voz opaca, pero sin emplear tono de reconvención ni de queja.\"},{\"heading\":false,\"text\":\"--No...--tartamudeó Asís--tanto como de viaje precisamente... no. Es que estoy guardando la ropa de invierno, poniéndole alcanfor... Si uno se descuida, la polilla hace destrozos...\"},{\"heading\":false,\"text\":\"Pacheco se acercó á la dama, y bajando el diapasón, con las inflexiones dolientes y melancólicas que solía adoptar á veces, dijo:\"},{\"heading\":false,\"text\":\"--A mi no se me engaña, te lo repito. Antes de venir sabía que te ibas. Tú no me conoces; tú te has creído que me la puedes dar. Aún no pasaron las ideas por esa cabecita, y ya las he olfateado yo. Siento que gastes conmigo tapujos. Al fin no te valen, hija mía.\"},{\"heading\":false,\"text\":\"La señora, no acertando á responder nada que valiese la pena, bajó los ojos, frunció la boca é hizo un mohín de disgusto.\"},{\"heading\":false,\"text\":\"--No amoscarse. Si no me enfado tampoco. La nena mía es muy dueña de irse adonde quiera. Pero mientras está aquí, ¿por qué me huye? Ayer me dijiste que no podíamos vernos, por estar tú convidada á comer...\"},{\"heading\":false,\"text\":\"Movidos por el mismo impulso, Asís y Don Diego miraron en derredor. Las puertas, cerradas; al través de la que comunicaba con los cuartos interiores, pasaba amortiguado el ruido del ir y venir de la Diabla. Y sin concertarse, á un mismo tiempo se acercaron para cruzar mejor esas explicaciones que el corazón adivina antes de pronunciadas.\"},{\"heading\":false,\"text\":\"--Hazte cargo... Los criados... Es una atrocidad... Yo nunca tuve de estas... vamos... de estas historias... No sé lo que me pasa. Por favor te pido...\"},{\"heading\":false,\"text\":\"--¡Bendita sea tu madre, niña!... Si ya lo sé... ¿Te crees que no me informo yo de los pasos en que anduvo mi reina? Estoy enterao de que nadie consiguió de ti ni esto. Yo el primerito... ¡Ay! Te deshago... Rica, gitana... ¡Cielo!\"},{\"heading\":false,\"text\":\"--Chist... La chica... Si pesca... Es más curiosa...\"},{\"heading\":false,\"text\":\"--Un favor te pido no más. Vente á almorsá conmigo. Que te vienes.\"},{\"heading\":false,\"text\":\"--Estás tocado... Quita... Chist...\"},{\"heading\":false,\"text\":\"--Que te vienes. Palabra, no lo sabrá ni la tierra. Se arreglará... verás tú.\"},{\"heading\":false,\"text\":\"--¿Pero cómo? ¿Dónde?\"},{\"heading\":false,\"text\":\"--En el campo. Te vienes, te vienes. ¡Ya pronto te quedas libre de mí!... La despedía. Al reo de muerte se le da, mujer.\"},{\"heading\":false,\"text\":\"¿Cómo cedió y balbució _que sí_, prometiendo, si no por la Estigia, por algún otro juramento formidable? ¡Ah! Aunque la observación ya no resulte nueva, cedió obedeciendo á los dos móviles que, desde la memorable insolación de San Isidro, guiaban, sin que ella misma lo notase, su voluntad: dos resortes que podemos llamar de goma el uno y de acero el otro: el resorte de goma era la debilidad que aplaza, que remite toda gran resolución hasta que la ampare el recurso de la fuga; el resorte de acero, todavía chiquitín, menudo como pieza de reloj, era el sentimiento que así, á la chita callando, aspiraba nada menos que á tomar plenísima posesión de sus dominios, á engranar en la máquina del espíritu, para ser su regulador absoluto y dirigir su marcha con soberano imperio.\"},{\"heading\":false,\"text\":\"Fiado en la palabra solemne de la señora, Pacheco se marchó, pues no convenía, por ningún estilo, que los viesen salir juntos. Asís entró en su cuarto á componerse. La Diabla la miraba con su acostumbrada curiosidad fisgona y aun le disparó tres ó cuatro preguntas pérfidas referentes á la interrumpida tarea del equipaje.\"},{\"heading\":false,\"text\":\"--¿Se cierra el mundo? ¿Se clavan los cajones? ¿La señorita quiere que avise á la Central para mañana?\"},{\"heading\":false,\"text\":\"¿Cómo había de responder la señora á interrogaciones tan impertinentes? Claro que con alguna sequedad y no poco enfado secreto. Además, otros incidentes concurrían á exasperarla: por culpa del revoluto del equipaje, ni había cosa con cosa, ni parecía lo más indispensable de vestir: para dar con unos guantes nuevos tuvo que desbaratar el baúl más chico: para sacar un sombrero, desclavó dos cajones. Más peripecias: la hebilla del zapato inglés, descosida: al abrochar el cuerpo del traje, salta un herrete; al cepillarse los dientes, se rompe el frasco del elíxir contra el mármol del lavabo...\"},{\"heading\":false,\"text\":\"--¿Almuerza fuera la señorita?--preguntó la incorregible Diabla.\"},{\"heading\":false,\"text\":\"--Sí... En casa de Inzula.\"},{\"heading\":false,\"text\":\"--¿Ha de venir á buscarla Roque?\"},{\"heading\":false,\"text\":\"--No... Pero le mandas que esté con la berlina allí, á las siete...\"},{\"heading\":false,\"text\":\"--¿De la tarde?\"},{\"heading\":false,\"text\":\"--¿Había de ser de la mañana? ¡Tienes cosas!...\"},{\"heading\":false,\"text\":\"La Diabla sonrió á espaldas de su señora y se bajó para estirarla los volantes del vestido y ahuecarla el polisón. Asís piafaba, pegando taconacitos de impaciencia. ¿El pericón? ¿El gabán gris, por si refresca? ¿Pañuelo? ¿Dónde se habrá metido el velo de tul? Estos pinguitos parece que se evaporan... Nunca están en ninguna parte... ¡Ah! Por fin... Loado sea Dios...\"}]},{\"title\":\"Insolación — capítulo XVIII\",\"blocks\":[{\"heading\":false,\"text\":\"Salvó la escalera como pájaro á quien abren el postigo de su penitenciaría, y con el mismo paso vivo, echó calle abajo hasta Recoletos. La cita era en aquel sitio señalado donde Pacheco había tirado el puro: casi frente á la Cibeles. Asís avanzaba protegida por su antucá, pero bañada y animada por el sol, el sol instigador y cómplice de todo aquel enredo sin antecedentes, sin finalidad y sin excusa. La dama registró con los ojos las arboledas, los jardincillos, la entrada de la Carrera y las perspectivas del Museo, y no vió á nadie. ¿Se habría cansado Diego de esperar? ¡Capaz sería!... De pronto, á sus espaldas, una voz cuchicheó afanosa:\"},{\"heading\":false,\"text\":\"--Allí... entre aquellos árboles... El simón.\"},{\"heading\":false,\"text\":\"Sin que ella respondiese, el gaditano la guió hacia el destartalado carricoche. Era uno de esos clarens inmundos, con forro de gutapercha resquebrajado y mal oliente, vidrios embazados y conductor medio beodo, que zarandean por Madrid adelante la prisa de los negocios ó la clandestinidad del amor. Asís se metió en él con escrúpulo, pensando que bien pudiera su galán traerle otro simón menos derrotado. Pacheco, á fin de no molestarla pasando á la izquierda, subió por la portezuela contraria, y al subir arrojó al regazo de la dama un objeto... ¡Qué placer! ¡Un ramillete de rosas, ó mejor dicho un mazo, casi desatado, mojado aún! El recinto se inundó de frescura.\"},{\"heading\":false,\"text\":\"--¡Huelen tan mal estos condenaos coches!--exclamó el meridional como excusándose de su galantería. Pero Asís le flechó una ojeada de gratitud. El indecente vehículo comenzaba á rodar; ya debía de tener órdenes.\"},{\"heading\":false,\"text\":\"--¿Se puede saber á dónde vamos, ó es un secreto?\"},{\"heading\":false,\"text\":\"--A las Ventas del Espíritu Santo.\"},{\"heading\":false,\"text\":\"--¡Las Ventas!--clamó Asís alarmada.--¡Pero si es un sitio de los más públicos! ¿Vuelta á las andadas? ¿Otro San Isidro tenemos?\"},{\"heading\":false,\"text\":\"--Es sitio público los domingos; los días sueltos está bastante solitario. Que te calles. ¿Te iba yo á llevar adonde te encontrases en un bochorno? Antes de convidarte, chiquilla, me he enterado yo de toas las maneras de almorsá en Madrid... Se puede almorsá en un buen _restaurant_ ó en cafés finos; pero eso es echar un pregón pa que te vean. Se puede ir á un colmado de los barrios ó á una pastelería decente y escondía, pero no hay cuartos aparte; tendrías que almorsá en pública subasta, á la vera de alguna chulapa ó de algún torero. Fondas, ya supondrás... No quedaban sino las Ventas ó el puente de Vallecas. Creo que las Ventas es más bonito.\"},{\"heading\":false,\"text\":\"¡Bonito! Asís miró el camino en que entraban. Dejándose atrás las frondosidades del Retiro y las construcciones coquetonas de Recoletos, el coche se metía, lento y remolón, por una comarca la más escuálida, seca y triste que puede imaginarse, á no ser que la comparemos al cerro de San Isidro. Era tal la diferencia entre la zona del Retiro y aquel arrabal de Madrid, y se advertía tan de golpe, que mejor que transición parecía sorpresa escenográfica. Cual mastín que guarda las puertas del limbo, allí estaba la estatua de Espartero, tan mezquina como el mismo personaje, y la torre mudéjar de una escuela parecía sostener con ella competencia de mal gusto. Luego, en primer término, escombros y solares marcados con empalizadas; y allá en el horizonte, parodia de algún grandioso y feroz anfiteatro romano, la plaza de toros. En aquel rincón semidesierto--á dos pasos del corazón de la vida elegante--se habían refugiado edificios heterogéneos, bien como en ciertas habitaciones de las casas se arrinconan juntas la silla inservible, la máquina de limpiar cuchillos y las colgaduras para el día de Corpus; así, después del circo taurino y la escuela, venía una fábrica de galletas y bizcochos y en pos un barracón con este rótulo: _Acreditado merendero de la Alegría_.\"},{\"heading\":false,\"text\":\"Las lontananzas, una desolación. El fielato parecía viva imagen del estorbo y la importunidad. A su puerta estaba detenido un borrico cargado de liebres y conejos, y un tío de gorra peluda buscaba en su cinto los cuartos de la alcabala. Más adelante, en un descampado amarillento, jugaban á la barra varios de esos salvajes que rodean á la corte lo mismo que los galos á Roma sitiada. Y seguían los edificios fantásticos: un castillo de la Edad Media hecho, al parecer, de cartón y cercado de tapias por donde las francesillas sacaban sus brazos floridos; un parador, tan desmantelado como teológico (dedicado al Espíritu Santo nada menos); un merendero que se honraba con la divisa _tanto monta_, y por último una franja rojiza, inflamada bajo la reverberación del sol: los hornos de ladrillo. En los términos más remotos que la vista podía alcanzar, erguía el Guadarrama sus picos coronados de eternas nieves.\"},{\"heading\":false,\"text\":\"Lo que sorprendió gratamente á Asís fué la ausencia total de carruajes de lujo en la carretera. Tenía razón Pacheco, por lo visto. Sólo encontraron un domador que arrastraban dos preciosas tarbesas; un carromato tirado por innumerable serie de mulas; el tranvía, que cruzó muy bullanguero y jacarandoso, con sus bancos atestados de gente; otro simón con tapadillo, de retorno, y un asistente, caballero en el alazán de su amo. ¡Ah! Un entierro de angelito, una caja blanca y azul que, tambaleándose sobre el ridículo catafalco del carro, se dirigía hacia la sacramental sin acompañamiento alguno, inundado de luz solar, como deben de ir los querubines camino del Empíreo...\"},{\"heading\":false,\"text\":\"Poco hablaron durante el trayecto los amantes. Llevaban las manos cogidas; Asís respiraba frecuentemente el manojo de rosas y miraba y remiraba hacia fuera, porque así creía disminuir la gravedad de aquel contrabando, que en su fuero interno--cosa decidida--llamaba _el último_, y por lo mismo le causaba tristeza, sabiéndole á confite que jamás, jamás había de gustar otra vez.\"},{\"heading\":false,\"text\":\"Llegaron al puente, y detúvose el simón ante el pintoresco racimo de merenderos, hotelitos y jardines que constituye la parte nueva de las Ventas.\"},{\"heading\":false,\"text\":\"--¿Qué sitio prefieres? ¿Nos apeamos aquí?--preguntó Pacheco.\"},{\"heading\":false,\"text\":\"--Aquí... Ese merendero... Tiene trazas de alegre y limpio--indicó la dama, señalando á uno, cuya entrada por el puente era una escalera de palo pintada de verde rabioso.\"},{\"heading\":false,\"text\":\"Sobre el frontis del establecimiento podía leerse este rótulo, en letras descomunales imitando las de imprenta y sin gazapos ortográficos:--_Fonda de la Confianza._--_Vinos y comidas._--_Aseo y equidad._--El aspecto era original y curioso. Si no cabía llamar á aquello los jardines aéreos de Babilonia, cuando menos tenían que ser los merenderos colgantes. ¡Ingenioso sistema para aprovechar terreno! Abajo una serie de jardines, mejor dicho, de plantaciones entecas y marchitas, víctimas de la aridez del suburbio matritense; y encima, sostenidas en armadijos de postes, las salas de baile, los comedores, las alcobas con pasillos rodeados de una especie de barandas que comunicaban entre sí las viviendas. Todo ello--justo es añadirlo para evitar el descrédito de esta Citerea suspendida--muy enjalbegado, alegre, clarito, flamante, como ropa blanca recién lavada y tendida á secar al sol, como nido de jilguero colgado en rama de arbusto.\"},{\"heading\":false,\"text\":\"Un mozo, frisando en los cincuenta, de mandil pero en mangas de camisa, con cara de mico, muequera, arrugadilla y sardónica, se adelantó apresurado al divisar á la pareja.\"},{\"heading\":false,\"text\":\"--Almorsá--dijo Pacheco lacónicamente.\"},{\"heading\":false,\"text\":\"--¿Dónde desean los señoritos que se les ponga el almuerzo?\"},{\"heading\":false,\"text\":\"El gaditano giró la vista alrededor y luego la convirtió hacia su compañera: ésta había vuelto la cara. Con la agudeza de la gente de su oficio el mozo comprendió y les sacó del apuro.\"},{\"heading\":false,\"text\":\"--Vengan los señoritos... Les daré un sitio bueno.\"},{\"heading\":false,\"text\":\"Y torciendo á la izquierda, guió por una escalera angosta que sombreaba un grupo de acacias y castaños de Indias, llevándoles á una especie de antesala descubierta, que formaba parte de los consabidos corredores aéreos. Abriendo una puertecilla, hízose á un lado y murmuró con unción:\"},{\"heading\":false,\"text\":\"--Pasen, señoritos, pasen.\"},{\"heading\":false,\"text\":\"La dama experimentó mucho bienestar al encontrarse en aquella salita. Era pequeña, recogida, misteriosa, con ventanas muy chicas que cerraban gruesos postigos, y enteramente blanqueada; los muebles vestían también blanquísimas fundas de calicó. La mesa, en el centro, lucía un mantel como el armiño; y lo más amable de tanta blancura era que al través de ella se percibía, se filtraba, por decirlo así, el sol, prestándole un reflejo dorado y quitándole el aspecto sepulcral de las cosas blancas cuando hace frío y hay nubes en el cielo. Mientras salía el mozo, el gaditano miró risueño á la señora.\"},{\"heading\":false,\"text\":\"--Nos han traído al palomar--dijo entre dientes.\"},{\"heading\":false,\"text\":\"Y levantado una cortina nívea que se veía en el fondo de la reducida estancia, descubrió un recinto más chico aún, ocupado por un solo mueble, blanco también, más blanco que una azucena...\"},{\"heading\":false,\"text\":\"--Mira el nido--añadió tomando á Asís de la mano y obligándola á que se asomase.--Gente precavida... Bien se ve que están en todo. No me sorprende que vivan y se sostengan tantos establecimientos de esta índole. Aquí la gente no viene un día del año como á San Isidro; pero digo yo que habrá abonos á turno. ¿Nos abonamos, cacho de gloria?\"},{\"heading\":false,\"text\":\"No sé cómo acentuó Pacheco esta broma, que en rigor, dada la situación, no afrentaba; lo cierto es que la señora sintió una sofoquina... vamos, una sofoquina de esas que están á dos deditos de la llorera y la congoja. Parecíale que le habían arañado el corazón. La mujer es un péndulo continuo que oscila entre el instinto natural y la aprendida vergüenza, y el varón más delicado no acertará á no lastimar alguna vez su invencible pudor.\"}]},{\"title\":\"Insolación — capítulo XIX\",\"blocks\":[{\"heading\":false,\"text\":\"Al colarse en el palomar los dos tórtolos, no lo hicieron sin ser vistos y atentamente examinados por una taifa de gente humilde, que á la puerta de la cocina del merendero fronterizo se dedicaba á aderezar un guisote de carnero, puesto, en monumental cazuela, sobre una hornilla. Es de saber que ambos enseres domésticos los alquilaba el dueño del _restaurant_ por módica suma en que iba comprendido también el carbón: en cuanto al carnero y al arroz de añadidura, lo habían traído en sus delantales las muchachas, que por lo que pueda importar, diremos que eran operarias de la Fábrica de tabacos.\"},{\"heading\":false,\"text\":\"Capitaneaba la tribu una vieja pitillera, morena, lista, alegre, más sabidora que Merlín; y dos niñas de ocho y seis años traveseaban alrededor de la hornilla, empeñadas en que les dejasen cuidar el guisado, para lo cual se reconocían con superiores aptitudes. Toda esta gentuza, al pasar la marquesa viuda de Andrade y su cortejo, se comunicó impresiones con mucho parpadeo y meneo de cabeza, y susurrando á media voz dichos sentenciosos. Hablaban con el seco y recalcado acento de la plebe madrileña, que tiene alguna analogía con lo que pudo ser la parla de Demóstenes, si se le ocurriese escupir á cada frase una de las guijas que llevaba en la boca.\"},{\"heading\":false,\"text\":\"--Ay... Pus van así como asustaos... Ella es guapetona, colorá y blanca.\"},{\"heading\":false,\"text\":\"--Valiente perdía será.\"},{\"heading\":false,\"text\":\"--Se ve caa cosa... Hijas, la mar son estos señorones de rango.\"},{\"heading\":false,\"text\":\"--Puee que sea arguna del Circo. Tié pinta de franchuta.\"},{\"heading\":false,\"text\":\"--Que no, que este es un belén gordo, de gente de calidá. Mujer de algún menistro lo menos. ¿Qué vus pensáis? Pus una conocí yo, casaa con un presonaje de los más superfarolícos... de mucho coche, una casa como el Palacio Rial... y andaba como caa cuala, con su apaño. ¡Qué líos, Virgen!\"},{\"heading\":false,\"text\":\"--No, pus muy amartelaos no van.\"},{\"heading\":false,\"text\":\"--¿Te quies callar? Ya samartelarán dentro. Verás tú las ventanas y las puertas atrancás, como en los pantiones... Pa que el sol no los queme el cutis.\"},{\"heading\":false,\"text\":\"Desmintiendo las profecías de la experta matrona, los postigos y vidrieras del palomar se abrieron, y asomó la cabeza de la dama, sin sombrero ya, mirando atentamente hacia el merendero.\"},{\"heading\":false,\"text\":\"--Miala, miala..., la gusta el baile.\"},{\"heading\":false,\"text\":\"En efecto, el corredor aéreo de enfrente ofrecía curiosa escena coreográfica. Un piano mecánico soltaba, con la regularidad que hace tan odiosos á estos instrumentos, el duro chorro de sus martilleadoras tocatas: _Cádiz_ hacía el gasto: paso doble de _Cádiz_, tango de _Cádiz_, coro de majas de _Cádiz_... y hasta una veintena de cigarreras, de chiquillas, de fregonas muy repeinadas y con ropa de domingo, saltaba y brincaba al compás de la música, haciendo á cada zapateta temblar el merendero... Asís veía pasar y repasar las caras sofocadas, las toquillas azul y rosa; y aquel brincoteo, aquel tripudio suspendido en el aire, sin hombres, sin fiesta que lo justificara, parecía efecto teatral, coro de zarzuela bufa. Asís se imaginó que las muchachas cobraban de los fondistas algún sueldo por animar el cuadro.\"},{\"heading\":false,\"text\":\"--¡Calla!--secreteó minutos después el grupo dedicado á vigilar la cazuela del guisote.--¡Pus si también han abierto la puerta! Chicas... quien que se entere too el mundo.\"},{\"heading\":false,\"text\":\"--Estas tunantas ponen carteles.\"},{\"heading\":false,\"text\":\"El mozo subía y bajaba, atareado.\"},{\"heading\":false,\"text\":\"--Mia lo que los llevan. Tortilla... Jamón... Están abriendo latas de perdices... ¡Aire!\"},{\"heading\":false,\"text\":\"--No se las cambio por mi rico carnero. A gloria huele.\"},{\"heading\":false,\"text\":\"--¡Chist!--mandó el mozo imponiéndose á aquellas cotorras.--Cuidadito... Si oyen... Son gente... ¡uf!\"},{\"heading\":false,\"text\":\"Al expresar la calidad de los huéspedes, el mozo hizo una mueca indescriptible, mezcla de truhanería y respeto profundo á la propina que ya olfateaba. La vieja cigarrera, de repente, adoptó cierta diplomática gravedad.\"},{\"heading\":false,\"text\":\"--Y pué que sean gente tan honrá como Dios Padre. No sé pa qué ha de condenar una su arma echando malos pensamientos. Serán argunos novios recién casaos, ú dos hermanos, ú tío y sobrina. Vayasté á saber. Oigasté, mozo...\"},{\"heading\":false,\"text\":\"Se apartó y secreteó con el mozo un ratito. De esta conferencia salió un proyecto habilísimo, madurado en breves minutos en el ardiente y optimista magín de la señá Donata, que así se llamaba la pitillera, si no mienten las crónicas. Arriba, dama y galán empezaban á despachar los apetitosos entremeses, las incitantes aceitunas y las sardinillas con su ajustada túnica de plata. Aunque Pacheco había pedido vinos de lo mejor, la dama rehusaba hasta probar el _Tío Pepe_ y el amontillado, porque con sólo ver las botellas, le parecía ya hallarse en la cámara de un trasatlántico, en los angustiosos minutos que preceden al mareo total. Como la señora exigía que puertas y ventanas permaneciesen abiertas, el almuerzo no revelaba más que la cordialidad propia de una luna de miel ya próxima á su cuarto menguante. Pacheco había perdido por completo su labia meridional, y manifestaba un abatimiento que, al quedar mediada la botella de _Tío Pepe_, se convirtió en la tristeza humorística tan frecuente en él.\"},{\"heading\":false,\"text\":\"--¿Te aburres?--preguntaba la dama á cada vuelta del mozo.\"},{\"heading\":false,\"text\":\"--Ajogo las peniyas, gitana,--respondía el meridional apurando otro vaso de jerez, más auténtico que la famosa manzanilla del Santo.\"},{\"heading\":false,\"text\":\"Acababa el mozo de dejar sobre la mesa las perdices en escabeche, cuando en el marco de la puerta asomó una carita infantil, colorada, regordeta, boquiabierta, guarnecida de un matorral de rizos negrísimos. ¡Qué monada de chiquilla! Y estaba allí hecha un pasmarote, si entro si no entro. Asís la hizo seña con la mano; el pájaro se coló en el nido sin esperar á que se lo dijesen dos veces. Y las preguntas y los halagos de cajón:--Eres muy guapa... ¿Cómo te llamas? ¿Vas á la escuela?... Toma pasas... Cómete esta aceitunita por mí... Prueba el jerez... ¡Huy qué gesto más salado le pone al vino!... Arriba con él... ¡Borrachilla! ¿Dónde está tu mamá? ¿En qué trabaja tu padre?\"},{\"heading\":false,\"text\":\"De respuesta, ni sombra. El pajarito abría dos ojos como dos espuertas, bajaba la cabeza adelantando la frente como hacen los niños cuando tienen cortedad y al par se encuentran mimados, picaba golosinas y daba con el talón del pié izquierdo en el empeine del derecho. A los tres minutos de haberse colado el primer gorrión migajero en el palomar, apareció otro. El primero representaba cinco años; el segundo, más formal pero no menos asustadizo, tendría ya ocho lo menos.\"},{\"heading\":false,\"text\":\"--¡Hola! Ahí viene la hermanita...--dijo Asís.--Y se parecen como dos gotas... La pequeña es más saladilla... pero vaya con los ojos de la mayor... Señorita, pase V. Esta nos enterará de cómo se llama su padre, porque á la chiquita le comieron la lengua los ratones.\"},{\"heading\":false,\"text\":\"Permanecía la mayor incrustada en la puerta, seria y recelosa, como aquel que antes de lanzarse á alguna empresa erizada de dificultades, vacila y teme. Sus ojazos, que eran realmente árabes por el tamaño, el fuego y la precoz gravedad, iban de Asís á Diego y á su hermanita: la chiquilla meditaba, se recogía, buscaba una fórmula, y no daba con ella, porque había en su corazón cierta salvaje repugnancia á pedir favores, y en su carácter una indómita fiereza muy en armonía con sus pupilas africanas. Y como se prolongase la vacilación, acudióle un refuerzo, en figura de la señá Donata, que con la solicitud y el enojo peor fingidos del mundo, se entró muy resuelta en el gabinete refunfuñando:\"},{\"heading\":false,\"text\":\"--¡Eh! niñas, corderas, largo, que estáis dando la gran jaqueca á estos señores... A ver si vus salís afuera, ú sino...\"},{\"heading\":false,\"text\":\"--No molestan...--declaró Asís.--Son más formalcitas... A esa no hay quien la haga pasar, y la chiquitilla ni abre la boca.\"},{\"heading\":false,\"text\":\"--Pa comer ya la abren las tunantas...\"},{\"heading\":false,\"text\":\"Pacheco se levantó cortésmente y ofreció silla á la vieja. El gaditano, que entre gente de su misma esfera social pecaba de reservado y aun de altanero, se volvía sumamente campechano al acercarse al pueblo.\"},{\"heading\":false,\"text\":\"--Tome V. asiento... Se va V. á bebé una copita de jerés á la salú de toos.\"},{\"heading\":false,\"text\":\"¡Oídos que tal oyeron! ¡Señá Donata, fuera temor, al ataque, ya que te presentan la brecha franca y expedito el rumbo! Y tan expedito, que Pacheco, desde que la vieja sentó allí el pié, pareció sacudir sus penosas cavilaciones y recobrar su cháchara, diciendo los mayores desatinos del mundo. Como que se puso muy formal á solicitar á la honrada matrona, proponiéndola un paseíto á solas por los tejares. Oía la muy lagarta de la vieja, y celebraba con carcajadas pueriles, luciendo una dentadura sana y sin mella; pero al replicar, iba encajando mañosamente aquella misión diplomática que bullía en su mente fecunda desde media hora antes. Tratábase de que ella, ¿se hacen ustés cargo? trabajaba en la Frábica de Madrí... y tenía cuatro nietecicas, de una hija que se murió de la tifusidea, y el padre de gomitar sangre, así, á golpás..., en dos meses se lo llevó la tierra, ¡señores! que si se cuenta, mentira parece. Las dos nietecicas mayores, colocaas ya en los talleres; pero si la suerte la deparase una presona de suposición pa meter un empeño..., porque en este pícaro mundo, ya es sabío, too va por las amistaes y las enfluencias de unos y otros...--Llegada á este punto, la voz de la señá Donata adquiría inflexiones patéticas.--«¡Ay Virgen de la Paloma! No premita el Señor que ustés sepan lo que es comer y vestir y calzar cinco enfelices mujeres con tristes ocho ú nueve riales ganaos á trompicones... Si la señorita, que tenía cara de ser tan complaciente y tan cabal, conociese por casualidad al Menistro... ó al Menistraor de la Frábica..., ó al Contaor..., ó algún presonaje de estos que too lo regüerven..., pa que la chiquilla mayor, Lolilla, entrase de aprendiza también... ¡Sería una caridá de las grandes, de las mayores! Dos letricas, un cacho de papel...»\"},{\"heading\":false,\"text\":\"Pacheco respondía á la arenga con mucha guasa, sacando la cartera, apuntando las señas de al pitillera detenidamente, y asegurándola que hablaría al Presidente del Consejo, á la infanta Isabel (íntima amiga suya), al Obispo, al Nuncio... Enredados se hallaban en esta broma, cuando tras la abuela pedigüeña y las nietecillas mudas, se metieron en el gabinete las dos chicas mayores.\"},{\"heading\":false,\"text\":\"--Miren mis otras huerfanicas enfelices,--indicó la señá Donata.\"},{\"heading\":false,\"text\":\"Imposible imaginarse cosa más distinta de la clásica orfandad enlutada y extenuada que representan pintores y dibujantes al cultivar el sentimentalismo artístico. Dos mozallonas frescas, sudorosas porque acababan de bailar, echando alegría y salud á chorros, y saliéndoles la juventud en rosas á los carrillos y á los labios; para más, alborotadas y retozonas dándose codazos y pellizcándose para hacerse reir mutuamente. Viendo á semejantes ninfas, Pacheco abandonó á la señá Donata, y con el mayor rendimiento se consagró á ellas, encandilado y camelador como hijo legitimo de Andalucía. Todas las penas _ajogadas_ por el _Tío Pepe_ se fueron á paseo, y el gaditano, entornando los ojos, derramando sales por la boca y ceceando como nunca, aseguró á aquellas principesas del Virginia que desde el punto y hora en que habían entrado, no tenía él sosiego ni más gusto que comérselas con los ojos.\"},{\"heading\":false,\"text\":\"--¿Vienen ustés de bailar?--les preguntó risueño.\"},{\"heading\":false,\"text\":\"--Pus ya se ve,--contestaron ellas con chulesco desgarro.\"},{\"heading\":false,\"text\":\"--¿Sin hombres? ¿Sin pareja?\"},{\"heading\":false,\"text\":\"--Ni mardita la falta.\"},{\"heading\":false,\"text\":\"--Pan con pan... Eso es más soso que una calabasa, prendas. Si me hubiesen ustés llamao...\"},{\"heading\":false,\"text\":\"--¿Que iba usté á venir? Somos poca cosa pa usté.\"},{\"heading\":false,\"text\":\"--¿Poca cosa? Son ustés... dos peasitos del tersiopelo de que está forraa la bóveda seleste. ¡Ea! ¿echamos ó no ese baile? Ahora me empeñé yo... ¡A bailar!\"},{\"heading\":false,\"text\":\"Salió como una exhalación; dió la vuelta al pasillo aéreo; cruzó el puente que á los dos merenderos unía, y en breve, al compás del horrible piano mecánico, Pacheco bailaba ágilmente con las cigarreras.\"}]},{\"title\":\"Insolación — capítulo XX\",\"blocks\":[{\"heading\":false,\"text\":\"Entre las condiciones de carácter de la marquesa viuda de Andrade, y de los gallegos en general, se cuenta cierto don de encerrar bajo llave toda impresión fuerte. Esto se llama _guardarse_ las cosas, y si tiene la ventaja de evitar choques, tiene la desventaja de que esas impresiones archivadas y ocultas se pudren dentro. Cuando el andaluz regresó después de haber pegado cuatro saltos, enjugándose la frente con su pañuelo y abanicándose con el hongo, halló á la señora aparentemente tranquila y afable, ocupada en obsequiar con queso, bizcochos y pasas á las dos gorrioncillas, y muy atenta á la charla de la vejezuela, que refería por tercera vez las _golpás_ de sangre causa de la defunción de su yerno. Pero el camarero, que era más fino que el oro y más largo que la cuaresma, se dió cuenta con rápida intuición de que _aquello_ no iba por el camino natural de almuerzos semejantes, y adoptando el aire imponente de un bedel que despeja una cátedra, intimó á toda la bandada la orden de expulsión.\"},{\"heading\":false,\"text\":\"--¡Ea! bastante han molestado Vds. á los señores. Me parece regular que se larguen.\"},{\"heading\":false,\"text\":\"--Oigasté... ¡El tío este! Si yo he entrao aquí, fué porque los señores me lo premitieron, ¿estamos? Yo soy así, muy franca de mi natural..., y me arrimo aonde veo naturalidá, y señoritos llanos y buenos mozos, sin despreciar á nadie.\"},{\"heading\":false,\"text\":\"--¡Ole las mujeres principales!--contestó con la mayor formalidad Pacheco, pagando el requiebro de la señá Donata. La cual no soltó el sitio hasta que Don Diego y la señora prometieron unánimes acordarse de su empeño y procurar que Lolilla entrase en los talleres. Las gorrionas se dejaron besar y se llevaron las manos atestadas de postres, pero ni con tenazas se les pudo sacar palabra alguna. No piaron hasta que fueron á posarse en el salón de baile.\"},{\"heading\":false,\"text\":\"El camarero también salió anunciando que «dentro de un ratito» traería café y licores. Al marcharse encajó bien la puerta, é inmediatamente los ojos de Pacheco buscaron los de su amiga. La vió de pié, mirando á las paredes. ¿Qué quería la niña? ¿Eh?\"},{\"heading\":false,\"text\":\"--Un espejo.\"},{\"heading\":false,\"text\":\"--¿Pa qué? Aquí no hay. Los que vienen aquí no se miran á si mismos. ¿Espejo? Mírate en mí. ¿Pero cómo? ¿Vas á ponerte el sombrero, chiquilla? ¿Qué te pasa?\"},{\"heading\":false,\"text\":\"--Es por ganar tiempo... Al fin, en tomando el café hemos de irnos...\"},{\"heading\":false,\"text\":\"El meridional se acercó á Asís, y la contempló cara á cara, largo rato... La señora esquivaba el examen, poniendo, por decirlo así, sordina á sus ojos y un velo impalpable de serenidad á sus facciones. La tomó Pacheco la cintura, y sentándose en el sofá la atrajo hacia sí. Hablaba y reía y la acariciaba tiernamente.\"},{\"heading\":false,\"text\":\"--¡Ay, ay, ay!... ¿Esas tenemos? Mi niña está celosa. ¡Celosita, celosita! ¡Celosita de mí la reina del mundo!\"},{\"heading\":false,\"text\":\"Asís se enderezó en el sofá, rechazando á Pacheco.\"},{\"heading\":false,\"text\":\"--Tienes la necedad de que todo lo conviertes en substancia. La vanidad te parte, hijo mío. Yo no estoy celosa, y si me apuras, te diré...\"},{\"heading\":false,\"text\":\"--¿Qué? ¿Que me dirás?--prorrumpió Pacheco algo inmutado y descolorido.\"},{\"heading\":false,\"text\":\"--Que... es algo imposible eso de estar celoso, cuando...\"},{\"heading\":false,\"text\":\"--¡Ah!--interrumpió el meridional, más que pálido, lívido, con voz que salía á _golpás_, según diría la señá Donata.--No necesitas ponerlo más claro... Enterado, mujer, enterado: si yo adivino antes que hables. Pa miserables tres horas ó cuatro que nos faltan de estar juntos, y probablemente serán las últimas que nos hemos de ver en este mundo perro, ya pudiste callarte y procurar engañarme como hasta aquí... Poco favor te haces, si viniste aquí no queriéndome algo. Tú te habrás creído que yo me tragaba... ¡Y me llamas necio! Yo seré un vago, un hombre que no sirve para ná, un tronera, un perdido, lo que gustes; ¡pero necio! Necio yo... ¡y en cuestiones de faldas! ¡Mire V. que es grande! Pero, ¿qué importa? Llámame lo que quieras... y óyeme sólo esto, que te voy á decir una verdá que ni tú la sabes, niña. No me has querío hasta hoy, corriente... Hoy, mas que digas por tema lo que te dé la gana, me quieres, me requieres, estás enamoraa de mí... Poquito á poco te ha ido entrando... y así que yo te falte, se te va á acabar el mundo. Esta es la fija... Ya lo verás, ya lo verás. Y por amor propio y por soberbia sales con la pata e gallo... ¡Te desdeñas de tener celos de mí! Bien hecho... Así como así no hay de qué. Boba serías si tuvieses celos. Algún ratito ha de pasar antes de que yo me pierda por otras mujeres... ¡Maldita sea hasta la hora en que te vi!... Dispensa, ¡dispensa! No quiero ofenderte, ¿sabes? ahora ni nunca. No sé lo que me digo... Pero digo verdad.\"},{\"heading\":false,\"text\":\"Soltaba esta andanada paseando por el pequeño recinto, como las fieras en sus jaulas de hierro; unas veces sepultaba las manos en los bolsillos del pantalón, y otras las desenfundaba para accionar con violencia. Su rostro, descompuesto por la cólera, perdiendo su expresión indolente, mejoraba infinito: se acentuaban sus enjutas facciones, temblaba el bigote dorado, resplandecían los blancos dientes, y los azules ojos se obscurecían como el agua del Mediterráneo cuando amaga tempestad. El piso retemblaba bajo sus pasos; diríase que el aéreo nido iba á saltar hecho trizas. Aquella tormenta de verano, aquella cólera meridional, no cabía en el cuartuco.\"},{\"heading\":false,\"text\":\"Al encajar la puerta el mozo, los amantes se habían olvidado de que el nido tenía otro boquete, la ventana, abierta por Asís y dejada en la misma situación durante todo el almuerzo. Y la ventana justamente miraba al salón de baile, ocupado por parte de la bandada de gorrionas, entretenidísimas á la sazón en atisbar la riña amorosa, mientras abajo Lolilla se consagraba al carnero y al arroz.\"},{\"heading\":false,\"text\":\"--Anda..., ella está de morros con él... Está amoscá.\"},{\"heading\":false,\"text\":\"--Porque bailó con nusotras... Me lo malicié, hijas.\"},{\"heading\":false,\"text\":\"--¡Jesús! Pus no se ha resquemao poco... ¡Qué gesto!\"},{\"heading\":false,\"text\":\"--¡Ay! ¡Miales! El la está haciendo cucamonas pa que se le pase... ¡Ole!... Hombre, no nos ponga usté el gorro... Siquiera pa repichonear podían tener la ventana cerrá.\"},{\"heading\":false,\"text\":\"--¿Quién os manda mirar?\"},{\"heading\":false,\"text\":\"--Pa eso tiene una los ojos... ¡Calle!... Pues ella, en sus trece... Que nones... Las orejas le calienta ahora.\"},{\"heading\":false,\"text\":\"--¡Virgen! ¿Qué cosas le habrá icho, pa que él se enfade así? Mueve los brazos que paecen aspas de molino... ¿A que le pega?\"},{\"heading\":false,\"text\":\"--¿Que la e pegar, mujer, que la e pegar? Eso á las probres. A estas pindongas de señoronas, los hombres les rinden el pabellón. Y eso que cualisquiera de nosotros les pue vender honradez y dicencia. Digo, me paece...\"},{\"heading\":false,\"text\":\"--No, pus enfadao ya está.\"},{\"heading\":false,\"text\":\"--¿Va que acaba pidiendo perdón como los chiquillos? ¿No lo ije? Miale... más manso que un cordero... Ella na, espetá, secatona... vuelta á la manía de ponerse el abrigo... Se quie largar... ¡Madre e Dios, lo que saben estas tunantas! Me lo maneja como á un fantoche... ¡Qué compungió que está!... ¿A que se pone de rodillas, pa que le echen la solución? ¡Ay, qué mujer, paece la leona del Retiro! Empeñá en que me voy... Y se sale con la suya... Mia... ¡Se largan!\"},{\"heading\":false,\"text\":\"La turba se precipitó por la escalera del merendero. Verdad: Asís se largaba, se largaba. Salía tranquilamente, sin prisa ni enojo; hasta sonrió á Lolilla, que armada del soplador de mimbres avivaba el fuego. Con voz serena explicó al mozo, atónito de semejante deserción, que se les hacía tarde, que no podían aguardar ni un minuto más; que avisase al cochero, el cual probablemente estaría con el simón por allí, en alguna sombra. Mientras Pacheco, demudado, con pulso trémulo, buscaba en el portamonedas un billete, Asís trazaba en el piso rayas con la sombrilla, hasta dibujar una celosía complicada y menuda. Al terminarla extendió la mano; cogió una ramita florida de la acacia que sombreaba el merendero y se la sujetó en el pecho con el imperdible. Acercóse obsequiosa la señá Donata, ofreciendo á sus huérfanas, sus nietecicas, «pa juntar un ramo de cacias y de mapolas, si á la señorita le gustan...» Dió Asís las gracias rehusando, porque se marchaba acto continuo, y acercándose disimuladamente á la vieja le deslizó algo en la mano, recia y curtida cual la piel del arenque. Acercóse el simón; sin duda el cochero se había atizado un par de tragos, porque su nariz echaba lumbre, reluciendo al sol como la película roja que viste á los pimientos riojanos. La señora tomó por la escalerilla que bajaba desde el puente; Pacheco la siguió...\"},{\"heading\":false,\"text\":\"--En el coche harán las paces--piaron las gorrionas mayores.--¿A que sí?\"},{\"heading\":false,\"text\":\"--La fija. En entrando...\"},{\"heading\":false,\"text\":\"Grande fué el asombro de aquellas aves, más parleras que canoras, viendo que, tras un corto debate al pié de la portezuela, la señora tendió la mano á Pacheco, éste llevó la suya al sombrero saludando, y el simón arrancó á paso de tortuga, bamboleándose sobre la polvorosa carretera.\"},{\"heading\":false,\"text\":\"--Pus ella vence... Me lo deja plantadito.\"},{\"heading\":false,\"text\":\"--¿A que él se nos vuelve aquí?--indicó la gorriona primogénita, alisando con la palma las grandes peteneras de su peinado, untadas de bandolina.\"},{\"heading\":false,\"text\":\"No volvió el muy... Ni siquiera torció la cabeza para hacerlas un saludo ó enviarlas una sonrisa de despedida. ¡Fantasioso! Estuvo pendiente del simón mientras éste no traspuso los hornos de ladrillo; luego, cabizbajo, echó á andar á pié.\"}]},{\"title\":\"Insolación — capítulo XXI\",\"blocks\":[{\"heading\":false,\"text\":\"La buena fe, que debe servir de norma á los historiadores, así de hechos memorables como de sucesos ínfimos, obliga á declarar que la marquesa viuda de Andrade se dedicó asiduamente--desde las dos de la tarde, hora en que llegó á su casa, hasta cerca de las nueve de la noche--á la faena del arreglo definitivo de su equipaje, resolviendo la marcha para el siguiente día, sin prórroga. El trajín fué gordo, y aumentó sus fatigas el desasosiego moral de la señora. Anduvo hecha un zarandillo; removió hasta el último trasto de la casa; mareó á la Diabla; aturrulló á los demás criados; y al agitarse así la impulsaban sus nervios, tirantes como cuerdas de guitarra, al par que sentía una especie de punzada continua en el corazón, un calor extraño en el epigastrio, un saborete amargo en la boca. Después de haber comido--por fórmula y sin ganas--pidióle Angela licencia, ya que era el último día, para decir adiós á su hermana. La negó en un arranque de cólera; la otorgó dos minutos después. Y así que la chica batió la puerta, la señora, rendida de cuerpo, más encapotada que nunca de espíritu, se retiró á su dormitorio... Tenía que poner el S. D. á un sinnúmero de tarjetas; pero ¡estaba tan molida! ¡de humor tan perro! Además, la punzadita aquella del corazón se iba convirtiendo en dolor fijo, intolerable... ¿Se aplacaría un poco recostándose en la cama? A ver...\"},{\"heading\":false,\"text\":\"Cerró los ojos, mascando unas hieles que tenía entre la lengua y el paladar. ¿A qué venían las hieles dichosas? Ella había obrado bien, mostrándose digna y entera. En realidad, ningún desenlace mejor para la historia. De un modo ó de otro ello iba á acabarse; era inevitable, inminente; mejor que se acabase así... Porque si aquella última entrevista fuese muy tierna, qué tristeza y qué... Nada; mejor así, mejor cien veces. Ella había tenido razón sobrada: una cosa son los celos, otra el amor propio y el decoro de que nunca está bien prescindir. Y á quién se le ocurre, allí, en su propia cara, ponerse á bailar con... Veía el salón de baile aéreo, el brincoteo de las gorrionas, los incidentes del almuerzo... y las hieles se volvían más amarguitas aún. Cierto que ella fué quien abrió puertas y ventanas; de todos modos, el proceder de Pacheco... Sí... buen tipo estaba Pacheco. En viendo una escoba con faldas... ¡Ay infeliz de la mujer que se fiase de sus exageraciones y sus locuras! ¡Requebrar á las cigarreras así, delante de...! ¡Y qué fatuo! ¡Pues no había querido convencerla de que estaba enamorada de él! ¿Enamorada? No, no señor, gracias á Dios... Conservaría, sí, un recuerdo... un recuerdo de esos que... Allí tenía, en el medallón de oro, junto al pelo de Maruja, una florecita de la acacia blanca... ¡Qué tontera! Lo probable es que á Pacheco no volviese á verle nunca más... Y esta punzada del corazón, ¿qué será? Será enfermedad, ó... Parece que lo aprieta un aro de hierro... ¡Jesús, qué cavilaciones más insensatas!\"},{\"heading\":false,\"text\":\"Bregando con la imaginación y la memoria, se quedó traspuesta. No era dormir profundo, sino una especie de somnambulismo, en que las percepciones de la vida exterior se amalgamaban con el delirio de la fantasía. No era la pesadilla que causa la ocupación de estómago, en que tan pronto caemos de altísima torre como volamos por dilatadas zonas celestes, ni menos el ensueño provocado por la acción del calor del lecho sobre los lóbulos cerebrales, donde, sin permiso de la honrada voluntad, se representan imágenes repulsivas... Lo que veía Asís, adormecida ó mal despierta, puede explicarse en la forma siguiente, aunque en realidad fuese harto más vago y borroso.\"},{\"heading\":false,\"text\":\"Encontrábase ya en el vagón, con la Diabla enfrente, la maletita y el lío de mantas en la rejilla, el velo de gasa inglesa bien ceñido sobre la toca de paja, calzados los guantes de camino, abrochado hasta el cuello el guardapolvo. El tren adelantaba, unas veces bufando y pitando, otras con perezoso cuneo, al través de las eternas estepas amarillas, caldeadas por un sol del trópico. ¡Oh Castilla la fea, la árida, la polvorosa, la de monótonos aspectos, la de escuetas lontananzas! ¡Oh sombría mole, región desconsolada del Escorial, qué felicidad perderte de vista! ¡Oh calor, calor del infierno, cuando acabarás! Asís sentía que el sol, al través de las cortinas corridas que teñían con viso azul el departamento, se le empapaba en los sesos como el agua en una esponja, y que en sus venas la sangre se volvía alquitrán, y la punta de cada filete nervioso una aguja candente, y que los ojos se le salían de las órbitas, igual que á los gatos cuando los escaldan... El polvillo de carbón, unido al de los páramos castellanos, entraba en remolinos ó en ráfagas violentas, cegando, desvaneciendo, asfixiando. No valía manejar desesperadamente el abanico: como toda la atmósfera era polvo, polvo levantaba al agitar el aire, y polvo absorbían los sedientos pulmones.--¡Agua! ¡Agua! ¡Agua por Dios! Angela, va una botella llena ahí en el cesto...--Revolvía la Diabla el fondo de la canastilla..., nada: sin duda el agua se había olvidado. ¡Ah! una botella... El vaso plano... Asís bebía. ¡No es agua, no es agua! Es manzanilla, jerez, brasa líquida, esas ponzoñas que roban el juicio á las gentes... Venga un río, un río de mi tierra, para agotarlo de un sorbo... Mientras la señora gemía, el inmenso foco del sol ardía más implacable, como si estuviesen echándole carbón, convertidos en fogoneros, los arcángeles y los serafines. Y así atravesaban la pedregosa tierra de Avila, con sus escuadrones de enormes cantos, y las llanuras de Palencia, y los severos desiertos de León, y la vieja comarca de la Maragatería. ¡Que me abraso!... ¡Que me abraso!... ¡Que me muero!... ¡Socorro!...\"},{\"heading\":false,\"text\":\"¡Aah! ¿Qué ocurre? Salimos del país llano... ¡Montes queridos! Cada túnel es una inmersión en la noche, un baño en un pozo; al volver á la claridad, montañas y más montañas, revestidas de frondosos castañares, y por cuyas laderas... ¡oh deleite! se despeñan saltando manantiales, cascaditas, riachuelos, mientras allá abajo, caudaloso y profundo, corre el Sil... Las mismas rocas sudan humedad; de la bóveda de los túneles rezuman gotas gordas; el suelo se encharca. Al principio, Asís revive como el pez restituido á su elemento: su corazón se dilata, calmase el hervor de su sangre, se aplaca la horrible sed. Pero los riachuelos van engrosando; los túneles menudean, lóbregos, pantanosos; al término se divisa un cielo color de panza de burro, muy bajo, en el cual se acumulan nubes preñadas de agua, que al fin, abriendo su seno, dejan caer, primero en delgados hilos, luego en cerrada cortina, la lluvia, la eterna lluvia del Noroeste, plomo derretido y glacial, que solloza escurriendo por los vidrios. Y aquella lluvia, Asís la siente sobre el corazón, que se lo infiltra, que se lo reblandece, que se lo ensopa, hasta no poder admitir más líquido, hasta que, anegado de tristeza, el corazón empieza también á chorrear agua, primero gota á gota, luego á borbotones, con fúnebre ruido de botella que se vacía...\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Pan, pan. Dos golpes en la puerta de la alcoba...--¡Jesús!... ¿Quién? ¿Pero dormía ó soñaba ó qué es esto?--Y la señora palpaba la almohada.--Húmeda, sí... Los ojos... También los ojos... ¡Lágrimas! ¿Quién está?... ¿Quién?\"},{\"heading\":false,\"text\":\"--Yo, amiga Asís... Gabriel Pardo... ¿He venido á molestar? Por Dios, siga V. con sus preparativos... Me he encontrado á la chica; me dijo que mañana sin falta salía V. para nuestra tierra... Cuánto sentiré incomodarla... Me retiro, me retiro.\"},{\"heading\":false,\"text\":\"--Por Dios... De ningún modo... Tome V. asiento... Salgo en seguida... Estaba lavándome las manos.\"},{\"heading\":false,\"text\":\"Y en efecto, se oía ruido de chapuzón, de lavaroteo. Pero nos consta que lo que lavaba la señora eran los párpados. Luego se dió polvos, se compuso el pelo, se arregló los encajes de la gola. Apareció muy presentable. Pardo había tomado un periódico, creo que _La Epoca_, y leía distraído, sin entender: «La dispersión veraniega ha comenzado. Parten hoy para Biarritz en el expreso, el duque de Albares, las lindas señoritas de Amézaga...»\"},{\"heading\":false,\"text\":\"Apenas habrían tenido tiempo los dos paisanos para trocar unas cuantas frases de excusa, cuando se oyó sonar la campanilla y en el corredor retumbaron pasos fuertes, varoniles. De sofocada, la señora se volvió pálida: una sonrisa involuntaria y una luz vivísima cruzaron por sus labios y sus ojos. Pacheco entró, y al verle el comandante Pardo, reprimió el impulso de pegarse un cachete en el hueso frontal.\"},{\"heading\":false,\"text\":\"--¡Ya pareció aquello! ¡Se despejó la incógnita! ¡Y decir que no hará dos semanas que se conocieron en casa de Sahagún! ¡Mujeres!!!\"},{\"heading\":false,\"text\":\"El gaditano,--lo mismo que si se propusiese evidenciar lo que Pardo adivinaba,--apenas se hubo sentado, sacó del bolsillo un tarjetero de piel inglesa, con monograma de plata, y se lo entregó á Asís, murmurando cortésmente:\"},{\"heading\":false,\"text\":\"--Marquesa... las señas que V. me pidió que le trajese. Las señas de la pitillera... ¿no recuerda V.? Puede V. copiarlas, ó quedarse con el tarjetero, si gusta... Viéndolo, se acuerda V. más del empeñillo.\"},{\"heading\":false,\"text\":\"¡Ay! Asís trasudaba. Era para volarse. ¡Vaya un pretexto que daba á su visita nocturna el bueno del gaditano! Si lo quería más claro Don Gabriel...\"},{\"heading\":false,\"text\":\"Miró al comandante, que se hacía el sueco, tratando de no ver el tarjetero dichoso. No hay posición más desairada que la de tercero en concordia, y Don Gabriel, notando la ojeada expresiva que trocaron Pacheco y Asís, creía estar sentado sobre brasas, tanto le apretaban las ganas de quitarse de en medio. Pero convenía hacerlo con habilidad y educación. Un cuarto de hora tardó en preparar la retirada honrosa, echándole el muerto al Círculo Militar, donde aquella noche había una conferencia muy notable. Los círculos, ateneos y clubs, serán siempre instituciones benéficas, por lo que se prestan á encubrir toda escapatoria masculina,--así la del que va en busca de la propia felicidad, como la del que evita el espectáculo de la ajena,--verbigracia Pardo.\"},{\"heading\":false,\"text\":\"Retrasó el paso al llegar á la esquina de la calle y se puso á reflexionar acerca del impensado descubrimiento. Raro es que el amigo de una dama, en caso semejante, no desapruebe la elección.--¡Cómo escogen las mujeres! En dándoles el puntapié el demonio... Indulgencia, Gabriel; no hay mujeres, hay humanidad, y la humanidad es _así_... Esta desazón, además, se parece un poquito á la envidia y al des... No, hijo, eso sí que no: despechado no estás: lo que pasa es que ves claro, mientras tu pobre amiga se ha quedado ciega... ¡Cómo se transformó su fisonomía al entrar el individuo! La verdad: no la creí capaz de echarse un amante... y menos ese. O mucho me equivoco ó le ha caído que hacer á la infeliz. Ese andaluz es uno de los tipos que mejor patentizan la decadencia de la raza española. ¡Qué provincias las del Mediodía, señor Dios de los ejércitos! ¡Qué hombre el tal Pachequito! Perezoso, ignorante, sensual, sin energía ni vigor, juguete de las pasiones, incapaz de trabajar y de servir á su patria, mujeriego, pendenciero, escéptico á fuerza de indolencia y egoismo, inútil para fundar una familia, célula ociosa en el organismo social... ¡Hay tantos así! Y sin embargo, á veces medran, con una apariencia de talento y la viveza propia del meridional; no tienen fondo, no tienen seriedad, no tienen palabra, no tienen fe, son malos padres, esposos traidores, ciudadanos zánganos, y los ve V. encumbrarse y hacer carrera... Así anda ello. Y á las mujeres... qué diablo, estos hombres les caen en gracia... ¡Eh! dejémonos de clichés... Asís, que es de otra raza muy distinta, necesita formalidad y constancia; la compadezco... Bueno es que no se casará; no, casarse no lo creo posible. De esa madera no se hacen maridos. Como aventura, tendrá sus encantos... ¡Qué casualidad! Y dirán que no hay coincidencias... ¡Tarjetero, tarjetero!...\"},{\"heading\":false,\"text\":\"Así meditaba el comandante. ¿Era injusto ó sagaz? ¿Obedecía á su costumbre de analizarlo todo, ó á una puntita de berrinche? Se caló los lentes y se retorció la barba, ¿A dónde iría?\"},{\"heading\":false,\"text\":\"--Al Círculo Militar, ya que me sirvió de pretexto para escurrir el bulto. ¡Poco gusto que les habrá dado cuando yo tomé la puerta!...\"},{\"heading\":false,\"text\":\"Tras esta ingrata reflexión apretó á andar. La obscuridad de la noche le exaltaba, y ese enlazado grupo, que ve con la fantasía todo el que sale huyendo de hacer mala obra á dos enamorados, se empeñaba en flotar, vaporoso é irónico, ante Don Gabriel. Fortuna que este género de visiones no suele resistir á los efectos anodinos de una conferencia sobre «Ventajas é inconvenientes del escalafón en los cuerpos facultativos.»\"}]},{\"title\":\"Insolación — capítulo XXII\",\"blocks\":[{\"heading\":false,\"text\":\"EPÍLOGO\"},{\"heading\":false,\"text\":\"No entremos en el saloncito de Asís mientras dure el tiroteo de explicaciones (¡cosa más empalagosa!) sino cuando la pareja liba la primera miel de las paces (empalagosísima también, pero paciencia). Ni Pacheco pregunta ya nada acerca de Don Gabriel Pardo y su amistad, ni Asís se acuerda del baile en el merendero. El gaditano habla al oído de la señora.\"},{\"heading\":false,\"text\":\"--¿Pero tú te creíste que yo no sabía que mañana te vas? A Diego Pacheco no se la ha pegado ninguna hembra... ¡Niña boba! Esta mañana ya habías dispuesto la marcha, claro que sí, y si te viniste á almorsá conmigo, fué que te dí un poquillo de lástima... Decías tú allá en tus adentros: sólo faltan horas; vamos á complacer á éste, que tiempo habrá de que estalle la bomba y dejarlo plantao... ¡Y ahora también piensas en cosas así, muy tristes; en que ya no nos vemos, en que se acaba el cariñito y las fatigas y el verme y el hablarme!... ¡Ay, chiquilla! Me quieres tú mucho más de lo que te figuras. No te has tomado el trabajo de echar la sonda ahí en ese pechito... ¡Tonta! ¡Cómo te acordarás de estos ratos, allá en tu país, entre aquella gente sosaina! Aquí se queda un hombre que te quería también un poquitillo... ¡Pobrecita, la nena!\"},{\"heading\":false,\"text\":\"No estaban los amantes abrazados, ni siquiera muy juntos, pues Pacheco ocupaba el sillón, y el diván Asís. Sólo sus manos, encendidas por la misma fiebre, se buscaban, y habiéndose encontrado, se entrelazaban y fundían. Callaron entonces y fué el instante más hermoso. Por el mudo diálogo de los ojos y por el contacto eléctrico de las palmas, se enviaban el espíritu en arrobo inefable. Con la nueva y victoriosa dulzura de semejante comunicación, Asís sentía que se mezclaba un asombro muy grande. Miraba á Pacheco y creía no haberle visto nunca: descubría en su apostura, en su cara, en sus ojos, algo sublime, que realmente no existía, pero era positivo entonces para la señora, pues así sucede en toda revelación, para que resplandezca su orígen superior á la materia inerte y al ciego acaso... y á Asís se le revelaba entonces el amor. Poco á poco, sin conciencia de sus actos, acercaba la mano de Diego á su pecho, ansiosa de apretarla contra el corazón y de calmar así el ahogo suave que le oprimía... Sus pupilas se humedecieron, su respiración se apresuró, y corrió por sus vértebras misterioso escalofrío, corriente de aire agitado por las alas del Ideal.\"},{\"heading\":false,\"text\":\"--No estés tan tristón--tartamudeó con blandura mimosa.\"},{\"heading\":false,\"text\":\"--Sí que estoy triste, prenda. Y es por ti. Estoy de remate. Estoy hasta enfermo. No sé por dónde ando. Parece que me han dao cañaso. Es un mal que se me entra por el alma arriba. Si sigo así, guardaré cama. Después que te vayas la guardaré... Es cosa rara, chiquilla. ¡Válgame Dios, á lo que llega un hombre!\"},{\"heading\":false,\"text\":\"--Te pones tan lejos... Aquí, cerquita--murmuró la señora con el tono con que se habla á los niños.\"},{\"heading\":false,\"text\":\"--No..., déjame aquí... Estoy bien. Mira tú que cosas más raras hace la guilladura cuando entra de verdad. Ni ganas tengo de acercarme; la manita me basta...\"},{\"heading\":false,\"text\":\"--¿No te gusto?\"},{\"heading\":false,\"text\":\"--No como me gustarían otras. ¡Ah! Ya sabes si tengo ilusión por ti... Y así y todo..., ahora prefiero callar y no acercarme, gloria... ¡Ay!... ¿Pero qué es eso? ¿Llora mi niña?\"},{\"heading\":false,\"text\":\"Puede que llorase, en efecto. No debía de ser el reflejo de la lámpara lo que tanto relucía en su mejilla izquierda... Pacheco exhaló un suspiro y se puso en pié, desenclavijando su mano de la de Asís.\"},{\"heading\":false,\"text\":\"--Me voy--pronunció con voz alteradísima ronca, resuelta.\"},{\"heading\":false,\"text\":\"De un brinco se levantó Asís, echándole los brazos al cuello y sujetándole.\"},{\"heading\":false,\"text\":\"--No, Diego, que no... ¡Vaya una ocurrencia! ¡Irte ya! ¡Pues si apenas llegaste! ¿Cómo irte? ¿Tienes que hacer? No, irte no quiero.\"},{\"heading\":false,\"text\":\"--Niña... El mal camino andarlo pronto. No tengo ánimos para más. Estoy que con una seda me ahogan. ¿A qué aprovechar unos minutos? Es la despedida. Yéndome ahora me ahorro alguna pena. Adiós, querida... Cree que más vale así.\"},{\"heading\":false,\"text\":\"--No, no, no te vas... Por lo mismo que ya es la última noche... Diego, por Dios, mi vida... Tú quieres sacarme de quicio. No puede ser.\"},{\"heading\":false,\"text\":\"Pacheco sujetó los brazos de la señora, y mirándola de hito en hito exclamó con firmeza:\"},{\"heading\":false,\"text\":\"--Piénsalo bien. Si me quedo ahora no me voy en toda la noche. Reflexiona. No digas después que te pongo en berlina. Te conviene soltarme. Tú decidirás.\"},{\"heading\":false,\"text\":\"Asís dudó un minuto. Allá dentro percibía, á manera de inundación que todo lo arrolla, un torrente de pasión desatado. Principios salvadores, eternos, mal llamados por el comandante _clichés_; que regís las horas normales, ¿por qué no resistís mejor el embate de este formidable torrente? Asís articuló, oyendo su propia voz resonar como la de una persona extraña:\"},{\"heading\":false,\"text\":\"--Quédate.\"},{\"heading\":false,\"text\":\"El plan era absurdo, y sin embargo los medios de realizarlo se presentaban entonces asequibles, rodados. La Diabla, fuera de casa, por casualidad feliz; la cocinera lo mismo; cuestión de engañar á Imperfecto, que era la quinta esencia de la bobería, y á la portera, que siempre estaba dormitando á tales horas. Para conseguir el apetecido resultado, combinóse un atrevido plan de entradas y salidas, de pases y repases, que hizo reir á los dos delincuentes... Y á las doce de la noche las puertas de la casa se hallaban cerradas, y dentro de ella el contraventor de las pragmáticas sociales y de las leyes divinas.\"},{\"heading\":false,\"text\":\"Si la cosa no hubiese pasado de aquí, creo sinceramente, lector amigo, que no merecía la pena, no ya de narrarla, sino hasta de mencionarla en estos libros de memorias y exámenes de conciencia de la humanidad, que se llaman novelas. Porque aun siendo el caso tan desatinado y enorme; aun constituyendo una atrevida infracción de todo lo que no debe, ni puede infringirse, bien cabe suponer que en las fiebres pasionales tiene algo de necesario y fatídico, cual en las otras fiebres, la calentura. Pero lo que me parece verdaderamente digno de tomarse en cuenta, como dato singular y curioso; lo que quizás convendría analizar sutilmente--si no es preferible dejarlo sugerido á la imaginación del lector para que lo deduzca y reconstruya á su modo--es la causa, la génesis y el rápido desarrollo de aquella _idea_ inesperadísima, que desenlazó precipitada y honrosamente la historia empezada por tan liviano y censurable modo en la romería del Santo...\"},{\"heading\":false,\"text\":\"¿A cuál de los dos amantes, ó mejor dicho, aunque la distinción parezca especiosa, de los dos enamorados, se le ocurrió primero la _idea_? ¿Fué á él, como único paliativo, heroico, pero infalible, de su extraña guilladura? ¿Fué á ella, como medio de conciliar el honor con la pasión, el instinto de rectitud y el respeto al deber que siempre guardara, con la flaqueza de su voluntad, ya rendida? ¿Fué que esa _idea_, profundamente lógica (y en el caso presente tal vez expiatoria), se presenta á la vuelta del amor, tan fatalmente como sigue á la aurora el mediodía, al crepúsculo la noche y á la vida la muerte?\"},{\"heading\":false,\"text\":\"Que cada cual lo arregle á su gusto y rastree y discurra qué caminos siguieron aquellos espíritus para no reparar en inconvenientes, no recelar de lo futuro, cerrar los ojos á problemas del porvenir y mandar á paseo las sabias advertencias de la razón, que tiembla de espanto ante lo irreparable, lo indisoluble, lo que lleva escrito el letrero medroso:--Para siempre--y avisa que de malos principios rara vez se sacan buenos fines.--Y reconstruya también á su modo los diálogos en que la _idea_ se abrió paso, tímida primero, luego clara, imperiosa y terminante, después triunfadora, agasajada por el amor que, coronado de rosas, empuñando á guisa de cetro la más aguda y emponzoñada de sus flechas, velaba á la puerta del aposento, cerrando el paso á profanos disectores.\"},{\"heading\":false,\"text\":\"Por eso, y porque no gusto de hacer mala obra, líbreme Dios de entrar hasta que el sol alumbra con dorada claridad el saloncito, colándose por la ventana que Asís, despeinada, alegre, más fresca que el amanecer, abre de par en par, sin recelo ó más bien con orgullo. ¡Ah! Ahora ya se puede subir. Pacheco está allí también, y los dos se asoman, juntos, casi enlazados, como si quisiesen quitar todo sabor clandestino á la entrevista, dar á su amor un baño de claridad solar, y á la vecindad entera parte de boda... Diríase que los futuros esposos deseaban cantar un himno á su numen tutelar, el sol, y ofrecerle la primer plegaria matutina.\"},{\"heading\":false,\"text\":\"--Está el gran día, chichi...--exclamaba Pacheco.--Vas á tener un viaje...\"},{\"heading\":false,\"text\":\"--¿Y para el tuyo? ¿Hará buen tiempo?\"},{\"heading\":false,\"text\":\"--Lo mismo que ahora. Verás.\"},{\"heading\":false,\"text\":\"--¿Despacharás en ocho ó diez días la ida á Cádiz?\"},{\"heading\":false,\"text\":\"--No que no. Y la aprobación del papá y too. Muerto está él porque me case y siente la cabeza. Le diré que después de la boda me presento diputao por Vigo con la ayuda del papá suegro. Verás tú. Para despabilar un asunto me pinto solo... cuando el asunto me importa, ¿sabes?\"},{\"heading\":false,\"text\":\"--¿Escribirás las veces que prometiste?\"},{\"heading\":false,\"text\":\"--Boba.\"},{\"heading\":false,\"text\":\"--Simplón, monigote, feo.\"},{\"heading\":false,\"text\":\"--Reina de España.\"},{\"heading\":false,\"text\":\"--En Vigo..., ya sabes... formalidad.\"},{\"heading\":false,\"text\":\"--Hasta que el cura...--(Pacheco hizo con la mano derecha un ademán litúrgico muy significativo.)--Entretanto... me dedicaré á tu chiquilla. ¿Eh? A los dos días... te la he conquistao. Puede que te deje plantaíta á ti pa casarme con ella.\"},{\"heading\":false,\"text\":\"Siguieron algunas bromas y ternezas más, que ni hacen al caso, ni deben figurar aquí en modo alguno. De repente, Diego tomó la mano derecha de la señora, preguntando:\"},{\"heading\":false,\"text\":\"--¿Te acuerdas tú de una buenaventura que te echaron en la feria?\"},{\"heading\":false,\"text\":\"E imitando el acento y modales de la gitana, añadió:\"},{\"heading\":false,\"text\":\"--Una cosa diquelo yo en esta manica, que ha e suseder mu pronto y nadie saspera que susea... Un viaje me vasté á jaser, y no ae ser para má, que ae ser pa satisfasión e toos... Una presonilla está chalaíta por usté...\"},{\"heading\":false,\"text\":\"El gaditano, siempre presumido, agregó:\"},{\"heading\":false,\"text\":\"--Y usté por ella.\"},{\"heading\":false,\"text\":\"FIN\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"}]},{\"title\":\"Morriña — capítulo I\",\"blocks\":[{\"heading\":false,\"text\":\"Si el entresuelo que habitan en Madrid doña Aurora Nogueira de Pardiñas y su hijo único Rogelio no es ni de los menos obscuros ni de los más espaciosos, tiene en desquite la ventaja inestimable de encontrarse sito en la calle Ancha de San Bernardo, tan frontero á la Universidad Central, que, hablando en plata, aquello es vivir en la Universidad misma. Encajada la señora dentro de su butaca de gutapercha, en el rincón de la ventana, mientras _crece_ y _mengua_ su labor de calceta sin mirarla una sola vez, sigue los pasos al adorado chiquillo, y en cierto modo, salvando la distancia de la calle y calando el espesor de las paredes, le acompaña hasta el aula misma. Le ve entrar; al salir observa si se detiene en algún grupo, y con quién charla, y cómo se ríe; conoce á todos los camaradas, á los amigotes, á los antipáticos, á los estudiosos, á los holgazanes, á los asiduos, á los que hacen rabona casi siempre. También está familiarizada con las caras de los profesores, y estudia su continente y su modo de responder al saludo de los discípulos, sacando de los signos exteriores importantes consecuencias psicológicas, relacionadas con el problema de los exámenes.--«¡Ay! Allí viene ya el viejiño Contreras, el de Procedimientos. ¡Qué afable!... ¡Qué cara de santo! Anda despacito el pobre... bien se nota que padece reuma articular, como yo. ¡Malpecado! Me es simpático por eso. No, y sobre todo, porque sé que es blando y que le ha de dar á Rogelio un aprobado como una casa. Ahora sale Ruiz del Monte, tan almidonado y tan engreído. Parece todo él hecho de una pieza. ¡Pobres de nos! Con éste no valen empeños, ni influencias, ni... Arre que le han de saber los chicos la asignatura tan bien como él. Pues para eso, que les deje á ellos la cátedra... y la paga. ¡Ay! Ahí tenemos al señor de Lastra. Jorobadito es un poco. ¡Qué gracia, las caricaturas que los muchachos le sacan en clase! Y se pasa de campechano. Ahí está pegándole palmadas en el hombro á Benito Díaz, el amigacho de Rogelio. Me parece uno de esos señores que dejan rodar el mundo. Bendito él sea. No sé qué se saca de disgustar á las familias y crucificar á los pobres rapaces.»\"},{\"heading\":false,\"text\":\"Suspendiendo el soliloquio, la señora se hincaba en el moño entrecano la aguja de calceta, rascándose los cascos ligeramente. De pronto la piel floja y rancia de sus mejillas se teñía de rosa vivo, como si una brisa de juventud le orease las facciones.\"},{\"heading\":false,\"text\":\"--¡Ay! Rogelio.\"},{\"heading\":false,\"text\":\"Salía el estudiante, envuelto en su capa de embozos de felpa carmesí, con el hongo un tantico ladeado y la mirada fija, desde el primer momento, en la ventana aquella. Por lo común sonreía; pero á veces, poniéndose muy formal, llevaba tres dedos al hongo, y estirando el brazo con movimiento de marioneta, remedaba el saludo de los gomosos en el Retiro. Contestaba la madre amenazándole con la mano abierta y descuajándose de risa, cual si fuese nueva una gracia consuetudinaria ya. Después, el muchacho platicaba tres ó cuatro minutos con algunos condiscípulos; de refilón se metía con el fosforero, la billetera, el naranjero de la esquina y los dependientes de la tienda más próxima, acabando por echar un requiebro á las criadas que charloteaban á la puerta; y al fin subía á su domicilio, esperándole en el recibimiento doña Aurora. Las primeras frases solían ser por este estilo:\"},{\"heading\":false,\"text\":\"--_Mater amabilis_... brinda el corporal sustento al fruto de tu vientre. Traigo un hambre que no la merezco. ¡Aaam! Si no llega pronto el bisteque, se producirán repugnantes escenas de canibalismo.\"},{\"heading\":false,\"text\":\"--Sí--decía risueña la señora;--ya vendrá todo á parar en que te comerás dos aceitunas y una hebra de carne. Anda, pistraco, señorito de la media almendra.\"},{\"heading\":false,\"text\":\"La habitación predilecta de la casa no era ni la sala, siempre abandonada y desierta, ni el despacho de Rogelio, ni el gabinete de la señora: era el comedor, muy próximo á la antesalita. Allí estaba el reloj de pared, que consultaba para las horas de clase Rogelio, perezoso en dar cuerda á su remontuar; allí la mesilla, donde el cesto de la labor y la media empezada desaparecían bajo números del _Madrid Cómico_, de _Los Madriles_ y de todas las _Ilustraciones_ habidas y por haber; allí el sofá bajo, ancho y cómodo y las vastas poltronas; allí, sobre el aparador, el reparito del estómago, botella de jerez y bizcochos, ó, en verano, frutas que el chico gulusmeaba; allí, en una copa, el ramo de lilas frescas, ó los claveles que se ponía en el ojal; allí el botijón trasudando agua, y el azucarero, y el frasco del jarabe ferruginoso, y el abanico japonés, y la novela empezada, con la plegadera entre las hojas, y algún libro de texto, maltratado, mucho más que por el uso, por el mal humor y displicencia con que lo cogían y soltaban. Allí, en fin, la chimeneíta, la que funcionaba tan bien, la que consolaba de las cátedras glaciales y los desmantelados patios y pasillos del templo de Minerva. ¡Con qué gusto se ponía Rogelio, al llegar de clase, al canto de la lumbre, sin desembozarse, extendiendo las palmas hechas dos carámbanos! El calor desentumecía sus tejidos, activaba su empobrecida sangre, y le daba fuerzas para pedir, entre chistosos regaños y súplicas mimosas, el almuerzo, sintiendo casi la puntualidad con que se lo servían, porque se le acababa el tema de sus humoradas y bromas. Aún no había él cruzado la puerta y ya estaba doña Aurora gritando:\"},{\"heading\":false,\"text\":\"--Fausta... Pepa... Que llega el señorito... Almorzar por el aire... Niño, el jirope de hierro... ¿Te cuento las gotas amargas?\"},{\"heading\":false,\"text\":\"--¿Qué mayores amarguras que las de la muerte por inanición? Usted, fámula encargada del ramo culinario, ¿se puede saber con qué deleitosos manjares piensa V. calmar hoy el hambre que me roe las entrañas? ¿Me ha destilado V. ambrosía celestial, néctar extraído del cáliz de las flores... ó callos y caracoles del _Petit Fornos_? ¡Sacadme de esta cruel incertidumbre!\"},{\"heading\":false,\"text\":\"Risas sofocadas en la cocina.\"},{\"heading\":false,\"text\":\"--¡Dénmele de comer á este loco, para que calle!\"},{\"heading\":false,\"text\":\"Sentados ya madre é hijo, contadas las gotas y tragadas también, venía el sopicaldo humeante, el par de huevos estrellados, abuñoladitos, y el bisteque, el cual precisamente había de traerse del café cercano. Sólo así lo comía Rogelio. Por mucho que se esmerase Fausta, la vizcaína, no conseguía desbancar al cocinero del cafetín. Llegaba el rico pedazo de vianda medio cruda, encerrado entre dos platos, con sus patatas sopladas, tierno, jugoso, apetecible. Mientras Rogelio trinchaba preparándose á despachar las tajaditas, su madre le observaba con inquietud y avidez, lo mismo que si nunca hubiese visto aquel tipo delicaducho, tan diferente del ideal de las madres gallegas. Veinte años espigados; palidez mate; ojos negros y alegres, pero de caído párpado y cárdenas ojeras; boca de espiritual dibujo y arqueada con finura, un poco amoratada de labios, con una dedada de bozo; nariz enjuta; pelo lacio y suave, del que suele llamarse _de ratón_; cabeza estrecha de sienes, garganta delgada, nuca con canal, muñecas planas y talle cimbrador, componían una figura no salida aún de la adolescencia y como detenida en su desarrollo por la clorosis que produce la vida de invernáculo, donde la planta necesitada de aire bravo y libre se ahila ó se seca. Así doña Aurora no podía disfrutar momento de tranquilidad con aquel hijo, si no precisamente enteco, al menos de complexión flaca y nerviosa, según revelaba su carácter, en que á la alegría propiamente infantil sucedían sin transición ratos de inexplicable abatimiento. Por eso le miraba comer, tan ansiosa como si cada buen bocado le cayese á ella en el estómago después de dos días de ayuno. Con el pensamiento le decía á la substanciosa carne: «Anda, fortaléceme á ese niño. Dale fibra, dale sangre, dale huesos. Házmele robustote, varonil, patrón. Que se vuelva un torito... aunque fuese así, á modo de un bárbaro... no importa, mejor, ¡ojalá! Mira que no me queda á mi otro cariño en el mundo sino este rapaz tan poca cosa.» Y agregaba en alta voz:\"},{\"heading\":false,\"text\":\"--Come, hijiño, come, que la carne, carne cría.\"}]},{\"title\":\"Morriña — capítulo II\",\"blocks\":[{\"heading\":false,\"text\":\"Doña Aurora tenía su tertulia, y vespertina--nada menos que un _five o’clock_, como diría algún revistero--sólo que sin _tea_, ni ganas de él; porque caso de ofrecer algo á los tertulianos, la señora de Pardiñas, muy chapada á la antigua, optaría por unas buenas magras de jamón, ó cosa análoga. Como los amigos de la señora sabían que no acostumbraba salir á la calle sino por la mañana, de manto y arrebujada en su rotonda de pieles, á visitas de confianza ó á compras, y que las tardes se las pasaba haciendo media en la ventana del comedor, acudían fielmente, atraídos por la chimenea, las poltronas, la intimidad y el hábito.\"},{\"heading\":false,\"text\":\"El mayor núcleo de relaciones de doña Aurora lo formaban compañeros de su difunto marido, magistrados, ó como ella decía en lenguaje profesional, «señores». Algunos, jubilados ya, eran los más constantes en acudir. Ciertos muebles del comedor teníalos vinculados determinada persona; la butaca de respaldo ancho se le reservaba á Don Nicanor Candás, el fiscal, aficionado á arrellanarse; la de gutapercha de asiento blando, á Don Prudencio Rojas; la de cretona rameada, á la vera de la chimenea, que nadie se la disputase al patriarca Don Gaspar Febrero; este venerable sujeto era el alma de la tertulia, el más vivo, rozagante y animoso de los concurrentes, á pesar de sus ochenta y pico de navidades y su pata coja, quebrada al saltar de un tranvía. El primer cuarto de hora de conversación solía consagrarse al estado atmosférico y á la salud; ninguno de los respetables señores estaba sin alifafes y goteras; algunos eran ya una pura ruina; y el lamentar achaques y discutir métodos curativos resultaba siempre de actualidad. Allí se llevaba el alta y baja de los catarros crónicos, de los dolores artríticos, de los flatos y las acedías de cada quisque, y se deliberaba, tan solemnemente como en otro tiempo sobre una sentencia, sobre las ventajas del salicilato y las pastillas pectorales.\"},{\"heading\":false,\"text\":\"Agotada la cuestión sanitaria--todo se agota--pasaban, casi siempre por iniciativa del señor de Febrero, á tratar otros asuntos más agradables. No podía sufrir el amable ochentón que se hablase tanto de botica, recetas y potingues.--«No parece sino que está uno con un pié en el sepulcro»--decía sonriendo y luciendo su brillante dentadura postiza. La conversación variaba de rumbo, pero casi nunca versaba sobre temas contemporáneos. Como gavota ejecutada por una abuela sobre viejo clavicordio, sonaba allí el anticuado ritornelo de las memorias y de las reminiscencias. Los diálogos solían empezar así.\"},{\"heading\":false,\"text\":\"--¿Se acuerda V.? Cuando me destinaron á la Gran Canaria, mandando Narváez...\"},{\"heading\":false,\"text\":\"O de este otro modo:\"},{\"heading\":false,\"text\":\"--¡Que tiempos! Lo menos diez años antes que se sustanciase la célebre causa Fontanelas... Aún no había nacido mi hijo mayor...\"},{\"heading\":false,\"text\":\"El señor de Febrero les iba á la mano también en esto de contar tristemente los lustros ya corridos, exclamando con juvenil viveza:\"},{\"heading\":false,\"text\":\"--Qué, si eso pasó ayer, como quien dice. En la vida de una nación, nada significan miserables veinticinco ó treinta años.\"},{\"heading\":false,\"text\":\"--Sí; pero en la de un hombre...\"},{\"heading\":false,\"text\":\"--Tampoco en la de un hombre, si Vds. me apuran. A los cuarenta, á los cincuenta llamo yo la flor de la edad.\"},{\"heading\":false,\"text\":\"--Hable V. por sí... Usted ha descubierto el elíxir de larga vida. Más fresquito que una lechuga. En cambio, los demás parecemos zapatillas, y estamos para que nos saquen en un carro al sol.\"},{\"heading\":false,\"text\":\"Con su muleta entre las piernas, Don Gaspar se reía, y como sacudiese la cabeza, relucían al reflejo del fuego los rizos argentados de su peluquín. Sentimos tener que pagar tributo á la exactitud descriptiva, consignando que llevaba peluca y dientes postizos el señor de Febrero: mas importa añadir que era tanta la verdad de su mentira, que eclipsaba á lo real, y engañaba al más lince. Revelando exquisito gusto y consumado arte, el anciano había encargado su peluca del color de la nieve, y la diadema de ligeros rizos canos que coronaba su frente de marfil era como majestuosa aureola, bien distinta de la tupida pelambrera con que los viejos verdes se obstinan en reparar el irreparable ultraje de los años. Asimismo la dentadura, hábilmente contrahecha, algo desigual y gastada, con una mellita en el lado izquierdo, se la pegaba á cualquiera. Con aquel pelo tan decorativo; con el rostro escrupulosamente afeitado, de facciones correctas, muy expresivas aún; con la pulcritud y dignidad afable de su persona, Don Gaspar recordaba las mejores cabezas del siglo XVIII, tal como nos las ha conservado la miniatura. Daba pena que no vistiese chupa de raso bordado. El traje de paño no le caía. Hasta la muleta de ébano, con almohadón de terciopelo azul, realzaba y completaba la autoridad de su presencia. A fuer de hombre de otras épocas que ya fenecieron, Don Gaspar, en cuanto veía mujeres, se encandilaba, y le chorreaban azúcar y miel los labios: hasta con la misma señora de Pardiñas, enteramente fuera de combate, no prescindía de sus formas, más que corteses, galantes y rendidas.\"},{\"heading\":false,\"text\":\"A aquel viejo que llevaba tan serena y elegantemente la vejez, le cosquilleaba en la vanidad de un modo grato oir á los contertulios, todos cascados, todos asmáticos y catarrosos, todos ostensiblemente calvos, que le decían en tono de envidia:\"},{\"heading\":false,\"text\":\"--Este Don Gaspar... es mucho cuento. Nos entierra á cuantos venimos aquí.\"},{\"heading\":false,\"text\":\"Otra satisfacción de amor propio muy grande era la de probarles la frescura y nitidez de su memoria: y la disfrutaba á menudo, porque en la tertulia de la señora de Pardiñas se hilaba continuamente el copo de los recuerdos, del cual salía una hebra de oro, pero oro amortiguado ya, como el de las antiguas casullas. Era la memoria de Don Gaspar una especie de armario de cedro, donde se guardaban perfumados, empaquetados, clasificados, íntegros, los sucesos, los nombres, las fechas y hasta las palabras.--«Este señor de Febrero es una cartilla vieja»,--solía decir doña Aurora. Cuando se discutía algo, apelábase al arbitraje de Don Gaspar.--«¿Verdad, señor de Febrero, que la causa Zaldívar, de Sevilla, se elevó á plenario en el invierno del 56?»--«No, señor, el 57: y por cierto que ocurrió eso hacia el 15 de Diciembre... digo mal, el 16, cumpleaños del amigo Don Nicanor Candás.»\"},{\"heading\":false,\"text\":\"--¡Pero, hombre!--exclamaba el aludido cuando llegaba á enterarse.--¡Reniego hasta de quien hizo su memorión de V.! ¡Pues no va este maldito gallego á acordarse de la fecha de mi cumpleaños, que yo mismo no me acuerdo nunca! Los años nadie me los ha de robar, con que no veo la necesidad de llevarlos por cuenta exacta.\"},{\"heading\":false,\"text\":\"Don Nicanor Candás, fiscal jubilado, asturiano, malicioso y presumido á fuer de buen ovetense; listo como una pimienta y más atravesado que una espina, daba mucho que reir á la tertulia metiéndose con el señor de Febrero, á quien llevaba la contraria por sistema, sin respetar sus fueros patriarcales y su decanato glorioso. Para mejor marear á su contrincante, adoptaba Candás un método raro, que no carecía de chiste. Fingíase sordo como una pared, y llevaba siempre en el bolsillo del gabán una trompetilla de plata que se introducía en el oído cuando le convenía responder acorde y rebatir al contrario, y que decía haber olvidado en casa cuando le daba la gana de contestar yéndose por los cerros sin atender á razones ajenas. Tal estratagema era de resultado seguro, y conseguía ponerle á salvo de todos los riesgos de la disputa. En su lenguaje, el señor de Candás era crudo y ordinario, tanto como Don Gaspar atildado, atento y melifluo, y por semejante modo de hablar desentonaba en la reunión. Ni era sólo por esto, sino también porque era el único que prefería las noticias de actualidad á los recuerdos, el único que vivía con un pié en lo presente, el único que traía á aquel enmohecido senado una corriente de aire callejero y de vida real. Don Gaspar, en tono agridulce, le llamaba «nuestro reporter».\"},{\"heading\":false,\"text\":\"La portentosa memoria del ochentón se confundía y embrollaba al tratarse de sucesos recientes, y Candás, aprovechándose de esta deficiencia en las admirables facultades del patriarca, siempre estaba tomándola con él.--«A ver,--decía,--cómo se iba á componer nuestro Don Gasparín para probar una coartada. Muy fuerte en todo lo que se refiere al ministerio Calomarde ó á la regencia de Espartero, y no sabe por dónde anduvo esta mañana misma.» Y remedando la voz de Don Gaspar, añadía: «¿Qué hice yo ayer tarde? Espérense Vds.. ¿Fuí á casa de Rojas? Me parece que sí... Digo, no, no. Estuve paseando en Recoletos. Con todo, no se lo juraría á Vds.»\"},{\"heading\":false,\"text\":\"Esta observación cómica relativa al patriarca, podía hasta cierto punto aplicarse á los demás tertulianos. Diríase que para ellos no existía lo actual, y sólo lo pretérito tenía vida y realce. Las noticias del reporter Don Nicanor las comentaban tres minutos, con esa tendencia pesimista que aflige á la edad senil; después volvían á subir corriente arriba, engolfándose muy á gusto entre las nieblas de los años desvanecidos. Quizá en esto influyese, además de la vejez, el carácter que imprime la magistratura, profesión cuya base son nociones científicas estratificadas ya, un derecho puramente histórico, en que el espíritu de innovación es una herejía, y en que se resuelven problemas jurídicos de hoy con el criterio de la ley romana ó del fuero visigodo. Así es que cabía comparar la reunión de casa de Pardiñas á una peña inmóvil en medio del mar de la existencia. No veían los excelentes «señores» que también en la polilla de los legajos palpitan gérmenes y late el ímpetu renovador: apegados á fórmulas vanas, creían custodiar un licor sagrado, cuando en sus manos no quedaba ya sino la ampolla vacía; y, al tratarse de novedades, en el mismo grado de heterodoxia ponían el uso de la barba, las audiencias de perro chico, el Jurado y la revisión de códigos.\"}]},{\"title\":\"Morriña — capítulo III\",\"blocks\":[{\"heading\":false,\"text\":\"Aquella asamblea de sonámbulos se despertaba y alborozaba al entrar Rogelio, quien, por las tardes, antes de salir á pié ó en coche, acostumbraba dejarse ver en la tertulia, riendo mucho de lo que ocurría en ella, pero sin malicia, con travesura de chico mimado. Habíale puesto de mote _Inútil Club_; á Candás, por su calva amarilla y enorme, le llamaba _Laín Calvo_; y al afeitado y galante señor de Febrero, _Nuño Rasura_. Las criadas repetían por lo bajo estos apodos. La misma señora de Pardiñas se reía en secreto, aunque aparentaba enfado diciendo al chico:\"},{\"heading\":false,\"text\":\"--Está muy mal que te burles... ¡Tanto como los pobres señores te quieren!\"},{\"heading\":false,\"text\":\"Sí que le querían. Al aparecer Rogelio, era como si algún rayo de sol dorado y caliente se deslizase en una de esas habitaciones cerradas, donde muebles, cortinas, papel y cuadros, han adquirido el desmayado matiz del polvo y la humedad. Todos los viejos amaban entrañablemente al chico: el uno le había visto en mantillas; el otro había asistido á su primera comunión; éste le traía juguetes cuando pasó la escarlatina; aquél, compañero de Sala é íntimo amigo de su padre, chocheaba recordando los dulces del bautizo... Si se dejasen llevar del primer impulso, á pesar de la orla negra que realzaba el arqueado labio superior de Rogelio, serían capaces de besuquearle los carrillos y traerle caramelos y cacahuetes. Para ellos era siempre el pequeño, el _rapaz_: cierto que, por un fenómeno natural de óptica, los excelentes tertulianos de la señora de Pardiñas propendían á seguir considerando como niños á los jóvenes, y como jóvenes á los machuchos. Se les oía decir, verbigracia: «¿Conque se murió Valdivieso? ¡Hombre, pues si estaba en lo mejor de la edad, si era un chico!» Y necesitaba intervenir el maligno asturiano, haciendo de la diestra embudo acústico, ó metiéndose la trompetilla: «¡Caray, caray con los chicos que sueñan Vds.! Valdivieso no cumplía ya los cincuenta.» «No tanto, no tanto.» «¿Que no tanto? Y los que mamó y anduvo á gatas.»\"},{\"heading\":false,\"text\":\"Al tratarse de Rogelio, extremaban la manía de no advertir que el tiempo pasa y hacerse los distraídos cuando suena el reloj. Cada año que ganaba en la carrera de Derecho, era para ellos un asombro: no le concebían abogado: quisiéranle deletreando todavía en la escuela. Lo cual no dejaba de amoscar al estudiante. Al regresar de una excursión de veraneo á San Sebastián, sucedió que le preguntase con la mejor fe del mundo el señor de Rojas:\"},{\"heading\":false,\"text\":\"--¿Cómo te habrás divertido, eh? ¡Todo el día corriendo y jugando por la playa!\"},{\"heading\":false,\"text\":\"Y el chico respondió, sin descubrir el amostazamiento sino con un mohín de pillería truhanesca:\"},{\"heading\":false,\"text\":\"--¡Vaya! Muchísimo. Hice agujeritos y chocitas con la arena. ¡Gocé más!\"},{\"heading\":false,\"text\":\"En el fondo, el buen corazón del chico se había apegado á la colección de honrados vejestorios que frecuentaba su casa. Aquel mismo señor de Rojas (por ejemplo), le infundía un respeto cariñoso, por su justificación y rectitud intachable. Si Temis descendiese á este bajo mundo, se hospedaría en casa del señor de Rojas, y encontraría allí altar y simulacro (de madera, según Candás). Estricto celador del sentido literal de la ley, Rojas marchaba por el angosto camino que veía, sin titubear, alta la frente y tranquila la conciencia. Persuadido de la altísima dignidad de su cargo, cubría las exigencias del decoro social á costa de una economía y una modestia inverosímiles de puertas adentro, comprendido y secundado en esta obra heroica por su mujer. No conocía influencias políticas, ni amistosas, ni de ninguna especie. Pasaron por sus manos asuntos en que se atravesaban millones, y la codicia, que no es sino instinto de conservación en forma de adquisividad, ni resolló siquiera. Por eso el severo nombre de Prudencio Rojas era pronunciado, ya con veneración, ya con la solapada y disolvente ironía que adopta el vicio para desacatar á la virtud. El cáustico Don Nicanor llamaba á Rojas _fantoche del Derecho_. Decía que todo en él era de palo, la inteligencia y el carácter; sin ver ó sin querer ver que esta clase de hombres, cuando las leyes fuesen perfectas dentro de lo humano, podrían, con su firmeza é integridad en aplicarlas, hacer reinar la edad de oro.\"},{\"heading\":false,\"text\":\"Muchas tardes, especialmente si hacía frío riguroso ó llovía ó nevaba, Rogelio, en vez de salir, se acurrucaba en el rincón del ancho sofá, y atendía á las soñolientas conversaciones de los viejos. Cuando podía, trataba de dirigirlas hacia un punto para él muy interesante: nunca se cansaba de oir hablar de su tierra, Galicia, de donde había salido muy pequeño. Casi todos los tertulios, ó eran de allí, ó allí habían pasado largas temporadas desempeñando puestos en la Audiencia de Marineda; y hacíanse lenguas de la benignidad y salubridad del clima, lo barato y sabroso de los alimentos, lo tratable y afectuoso de la gente, y la hermosura extraordinaria del país.\"},{\"heading\":false,\"text\":\"--No sé cómo nuestra amable amiga doña Aurora no lleva allá á este pollo para que conozca su cuna--decía el señor de Febrero sobando el cojín de la muleta.\"},{\"heading\":false,\"text\":\"--Si siempre estoy proyectándolo--contestaba la señora--y es de esos planes que tienen desgracia. La verdad, ustedes comprenden que hasta el día todo se me ha vuelto dificultades y tropiezos.\"},{\"heading\":false,\"text\":\"--Di que eres muy remoloncita, _mater admirabilis_--objetaba el hijo.--Por tu gusto serías árbol, para echar raíces donde te plantasen.\"},{\"heading\":false,\"text\":\"--Lo mismo que te llevo á San Sebastián, á Galicia te hubiese llevado, niño; pero no fué posible. ¿Crees tú que no me llama á mí la tierra? Los que allá nacimos... es tontería; no tenemos más ganas que de volver, ni perdemos nunca la querencia.\"},{\"heading\":false,\"text\":\"--Y los que no nacimos lo mismo--intervino Don Nicanor Candás, armado de trompetilla.--Ahora daba yo el dedo meñique por pasarme un año en Marineda; mejor me voy allá que á Oviedo ó á Gijón.\"},{\"heading\":false,\"text\":\"--Pero á mí--prosiguió la señora--siempre se me descomponía el plan, como si anduviesen en ello las brujas. ¿Tienes gana de volver á tu país antes de cerrar el ojo? Pues fastídiate, y aguarda hasta que te caigas de vieja. Verán Vds.:--y contaba por los dedos.--Primero: que la incompatibilidad. Deje V. su familia, su casa, sus bienes, y váyase V. á rodar de zeca en meca, con un niño pequeñito y que siempre fué delicado, de Oviedo á Zaragoza, luego, con lo de la Regencia, á Barcelona, luego al Supremo aquí... Mi matanza toda era decirle á Pardiñas: jubílate, hombre, jubílate, y volvámonos á la terriña, á no dejar por ahí nuestros huesos. Para vivir nos sobra con lo nuestro, y los hijos no son tantos que nos agobien. Pero... como ya saben Vds. lo que era mi pobre marido, que no es que yo lo diga...\"},{\"heading\":false,\"text\":\"Rumor de simpatía en la asamblea.\"},{\"heading\":false,\"text\":\"--Creía que en seguir la carrera hasta el fin consistía su obligación... ¡En nombrando al deber! En fin, tenía aquella idea y era preciso respetarla. Y después, como se puso ya tan malito...\"},{\"heading\":false,\"text\":\"Aquí la voz de la señora se enronquecía algo; llevaba la mano al bolsillo, y se sonaba, aplicando luego el pañuelo á los ojos.\"},{\"heading\":false,\"text\":\"--De manera--repetía suspirando y encogiéndose de hombros--que cuando llega la hora... Después, ya saben Vds. cómo me vi con mis cuñadas, y la de pleitos y de embrollas que me armaron. Creí que nunca me desenredaba. De allá me escribían los amigos antiguos: «Que vengas, que vengas, que en un día haces más desde aquí que desde ahí en un año.» ¿Qué quieren Vds.? Me daba miedo la diligencia. Con este reuma, pensar en embutirme en aquellos carricoches, que á lo mejor no tenían un cristal para un remedio... Así que se transigieron bien que mal las cuestiones y se devanó el ovillo de la testamentaría, cate V. que ponen el tren directo hasta Marineda... Pero ya se me había enfriado el alma, porque volver allá para encontrarse de esquina con toda la parentela...\"},{\"heading\":false,\"text\":\"--Mamá, con toda no. Muchos parientes, según tus mismas noticias, están de nuestra parte.\"},{\"heading\":false,\"text\":\"--Bah... Yo qué sé. En nuestra tierra, rapaz, es difícil saber quién está por uno y quién en contra. En ese particular he recibido desengaños atroces. A lo mejor te venden amistad mientras te clavan el cuchillo hasta el mango. La verdad se ha de decir: por allá no somos así... francotes y reales, como los castellanos viejos.\"},{\"heading\":false,\"text\":\"--Habla V. como un libro--asentía el señor de Candás, no desperdiciando la ocasión de sacar las uñas.--El gallego reunirá los méritos que V. guste; pero á retorcido y escurridizo y falso no le gana nadie. No contrate V. con él de palabra sólo, carapuche, que no tienen fe, ó si la tienen es púnica. Cómo será el gallego, que los gitanos no se atreven á colarse nunca por allí, temerosos de salir engañados.\"},{\"heading\":false,\"text\":\"--¡Cuidadito con insultar á la tierra!--decía festivamente Rogelio.\"},{\"heading\":false,\"text\":\"--Sí es cosa averiguada. A Galicia no va un gitano. Más chalanes y más socarrones son ellos que toda la gitanería junta. ¿Y en litigar? ¡Santo Cristo de mi pueblo! Nacieron pleiteantes. Le envuelven á V., home; el aldeano más rudo le da á V. cien vueltas.\"},{\"heading\":false,\"text\":\"--Eso prueba,--alegaba el señor de Febrero--que somos gente despabilada; no me lo negará V.\"},{\"heading\":false,\"text\":\"El señor de Candás, quitándose del oído el cañuto de plata á fin de no hacer caso de la observación y despacharse á su gusto, proseguía:\"},{\"heading\":false,\"text\":\"--Y hay tontines que llaman á los gallegos listos; yo lo que digo es que son maulas: si fuesen listos no andarían siempre hechos unos pobretes, comidos de miseria, roídos de envidia, sin salir nunca de pobres y de quejumbrosos. Son la casta de gente más llorona que he conocido. Todo se les vuelve pucherines y lamentos.\"},{\"heading\":false,\"text\":\"La tez de marfil del señor de Febrero se encendía un poco, porque le era imposible habituarse á las malignas descortesías de _Laín Calvo_.\"},{\"heading\":false,\"text\":\"--Eso es algo fuerte, señor Don Nicanor; repare V. que aquí estamos en mayoría los gallegos. ¿Le gustaría á V. que yo le repitiese ahora aquella vulgaridad de «asturiano, loco, vano, mal cristiano?»\"},{\"heading\":false,\"text\":\"--Hay--proseguía el fiscal imperturbable--una tanda de memos en polvo que se alborotan cuando oyen decir esto; pero ello es ya tan sabido, que de puro sabido se calla. El gallego tiene alguna penetración, corriente, sobre todo cuando se trata de discurrir maneras de jeringar al prójimo; y, sin embargo, ni sabe cultivar la industria, ni salir de aquella escasez en que vive. Le ve V. resignado con su mendrugo de pan de maíz, hecho un pelele, sin ropa, sin comer carne, sin beber vino una vez en el año... Le ve V. que con su fama de avispado, á veces parece más alma de cántaro que los mismos aragoneses. Es tacaño y ahorrará un _ochavitu_ aunque se lo saque del pellejo con una raspa; pero no tenga V. miedo que discurra para agenciarse ese ochavo, ni que se anime á trabajar de veras por el aliciente de un duro. Nada: con tal que no le perturben en su rutina y en su haraganería... Así ve V. que ahora tienen esa red de ferrocarriles, ¿y para qué les sirve? No moverán el dedo para atraer á los veraneantes. ¡Aquel agrado, aquella limpieza de la gente donostiarra!\"},{\"heading\":false,\"text\":\"--A este Don Nicanor hay que matarle ó dejarle--objetaba furioso Nuño Rasura.--Como no atiende á razones... ¿Dónde está esa red ferrocarrilera de que habla? ¡Bonita red! Llena de agujeros. ¿Quiere que todo se haga en un día? Milagros sólo Dios. Todo se andará, con paciencia y tiempo. Mire ya mi Don Nicanor la importancia que va adquiriendo la bellísima Vigo. Aquel clima tan fresco, aquellas costas y aquellas rías son la admiración de la prensa. ¡Y aquellas mujeres... mejorando siempre lo que tenemos delante, pero mi buena amiga también es de allá! ¿Y aquel pescado tan especial? ¿Qué me dice V. de él?... Amiga queridísima doña Aurora, yo no he vuelto á comer sardina ni lenguados desde que me vine. Antes de la caída de O’Donnell, recuerdo que estábamos tomando baños en Marín, y nos trajeron á la puerta un rodaballo...\"},{\"heading\":false,\"text\":\"Aquí volvía el ochentón á hilar el copo de los recuerdos, y Rogelio, con el codo en el sofá y en la palma la mejilla, escuchaba embelesado. Parecíale que estaban contando alguna tradición de familia. El aposento y la tertulia adquirían aspecto de cariñosa intimidad: la atmósfera moral y material era templada: el mundo era mullido y acolchado como el almohadón donde reclinaba su cuerpo. Cada tertuliano era para él, si no un padre, por lo menos un tío carnal. En derredor suyo reinaba la más dulce seguridad; y así como en ciertas moradas lujosas se traslucen el ahogo y la escasez, en aquel comedor modestísimo se transparentaba el bienestar casero, la más dorada mediocridad que pudo soñar ningún poeta ni apetecer ningún filósofo. La armonía y la moderación son siempre hermosas, y Rogelio, sin definir esta belleza que le rodeaba, la sentía y se envolvía en ella como el pájaro en el plumón de su nido. Y mientras en la chimenea chisporroteaba la leña ardiendo, y de la cocina venía amortiguado el repique del almirez, y discutían los viejos y la madre activaba las agujas de su media, el muchacho, sumido en vaga contemplación, fantaseaba cómo sería aquel país bonito, aquella Galicia verde, llena de agua, de flores y de muchachas mimosas.\"}]},{\"title\":\"Morriña — capítulo IV\",\"blocks\":[{\"heading\":false,\"text\":\"La calle enterita, tiendas, puestos ambulantes, criadas y vecindad, conocía á Rogelio: como suele decirse, todo el mundo le debía un cuarto. Eranle familiares los establecimientos, ó, mejor dicho, humildes tenduchos de loza, ultramarinos, novedades, cordelería y periódicos, que se incrustan entre las viejas é imponentes casas solariegas de la calle Ancha, animada por la concurrencia de los estudiantes y por el ascenso y descenso de los tranvías.\"},{\"heading\":false,\"text\":\"Pero con quien la emprendía Rogelio más á menudo, era con los cocheros simones, de los cuales existe un puesto en la plazuela de Santo Domingo. Rara vez salía de casa doña Aurora que el reuma ó el frío ó el calor no la determinasen á enviar por uno de aquellos vehículos tan destartalados y feos, pero tan cómodos y accesibles; ella les llamaba enfáticamente «sus trenes», y aseguraba riendo que siempre tenía el coche enganchado y á la puerta, con un cochero tan puntual, que no se hacía esperar una vez sola. Rogelio, á fuer de hijo único y rico, se permitía otros lujos, y su madre le pagaba la pensión de dos caballitos moscas y el alquiler de un milor flamante en casa del alquilador Agustín Cuero, para que los días festivos bajase al Retiro ó adonde le diese la gana (no consintiéndole caballo de silla por temor á un lance peligroso). Pero á la señora primero la matarían que usar de aquel tronco juguete: que la dejasen con sus pacíficos simones; á no ser algún día, por decoro y para hacer visitas, maldito lo que le importaba la farsa de que el coche estuviese más barnizado y el cochero llevase guantes y unas zaleas de carnero por los hombros. Con el uso frecuente y las razonables propinas, todo el personal cocheril de la plaza estaba á devoción de doña Aurora, y muy prendado de la buena sombra del señorito. Este no les dejaba vivir, máxime á sus paisanos, los gallegos, con quienes la tenía siempre armada. Decíales mil disparates acerca de su tierra; les tarareaba la muiñeira; les hablaba con la _u_, á guisa de sirviente de comedia de Ayala; y si por milagro llegaban á amoscarse, les decía:\"},{\"heading\":false,\"text\":\"--Auriga veloz, yo también soy galleguiño, maruso, de pralá.\"},{\"heading\":false,\"text\":\"A lo cual solían ellos responder:\"},{\"heading\":false,\"text\":\"--¡Qué señorito tan _pavero_!\"},{\"heading\":false,\"text\":\"Cuando venía á comprometer á alguno porque lo necesitaba su madre, desde una legua que le viesen ya estaban riéndose y bajando la alquila. Y él solía entrar en escena dirigiéndoles retahilas semejantes:\"},{\"heading\":false,\"text\":\"--Automedonte alígero, vapulea á tu fogoso corcel para que se beba la distancia hasta mi encantado palacio. Ya el generoso bridón tasca impaciente el dorado freno. ¿No ves cual le rocía de cándida espuma? Buloniu, ¿en qué estabas pensando que no me veías de venir?\"},{\"heading\":false,\"text\":\"--Señorito... estaba á leer _La Correspondencia_.\"},{\"heading\":false,\"text\":\"--_¡La Correspondencia!_ ¿Qué profieren tus sacrílegos labios? _¡La Correspondencia!_ ¡Rabo de Satanás! ¡Una hoja revolucionaria, anárquica y nihilista! Arroja pronto ese veneno, antes de apropincuarte á la mansión honrada de los pacíficos ciudadanos. ¡Acude, corre, vuela, simón! ¡Hurra, cosacos del desierto! ¡Anda, burrachu, demagogo!\"},{\"heading\":false,\"text\":\"Cuanto mayores extravagancias ensartase, más se reían los cocheros.\"},{\"heading\":false,\"text\":\"Una mañana salió Rogelio, ya embozado en su capita hasta los ojos, pues las postrimerías de Octubre tenían la atmósfera en punto de sorbete, aunque el alegre sol madrileño brillase en todo su esplendor. Tratábase como siempre de buscar un cochecillo para doña Aurora. Al llegar á la esquina de la plazuela, divisó á uno de sus trenes predilectos: una berlina algo menos indecente, con forro de sagrén avellana no tan mugriento y sobado como el de la mayor parte de estos vehículos. El cochero, rubio, gordo, coloradote, atendía por Martín y era gallego. Rogelio venía llamándole con señas y gritos:\"},{\"heading\":false,\"text\":\"--¡Martín, el de la capa! ¡Ah de la imperial carroza!\"},{\"heading\":false,\"text\":\"Hablaba el simón con una mujer cuyo rostro no podía ver el estudiante; pero á la voz de éste se volvió, y Rogelio hubo de notar que era moza, no mal parecida, de aspecto humilde y vestida de luto.\"},{\"heading\":false,\"text\":\"--¡Señorito, qué cuaselidá!--exclamó Martín al conocer á Rogelio.--Esta joven (el cochero pronunciaba _joven_ con _g_) viene en busca de la casa del señorito, y me preguntaba el camino ahora. Es paisana nuestra. Trae una carta...\"},{\"heading\":false,\"text\":\"--¿Quiere V. dejarme ver el sobre?--indicó el estudiante, que al dirigirse á la muchacha varió enteramente de modales y de tono.\"},{\"heading\":false,\"text\":\"La muchacha alargó el billete, que lo era, y bien chico.\"},{\"heading\":false,\"text\":\"--¡Calle! Es para mamá. Véngase V. conmigo; yo le enseñaré la casa. Tú, simón, sigue nuestra resplandeciente estela con tu carroza imperial, tirada por ese lánguido cisne.\"},{\"heading\":false,\"text\":\"--Dios se lo pague, señorito--dijo la muchacha con voz bien timbrada y dulce, y acento cantarín, como suelen tenerlo las gallegas ribereñas.--No necesita molestarse. Ya veo desde aquí el portal de la casa, que el cochero me lo señaló.\"},{\"heading\":false,\"text\":\"--Si yo también llevo ese camino. Ningún trabajo me cuesta.\"},{\"heading\":false,\"text\":\"Sin otra discusión, la muchacha rompió á andar, y Rogelio, por instinto, se colocó á su izquierda, como haría con una dama. A los diez pasos le pesaba ya de su galantería. En primer lugar, menuda chacota le arrimarían sus compañeros si acertaban á encontrarle acompañando tan cortés á una individua de pañuelo á la cabeza y saya lisa de merino. En segundo, Rogelio atravesaba esa edad en que un chico criado algo falderamente, en la casta atmósfera maternal, no puede evitar una impresión de cortedad penosa cuando trata con mujeres desconocidas aún. Cierto que las de condición inferior no le atarugaban tanto: las señoritas eran su muerte: siempre creía que se burlaban de él, que cuanto le decían era pura matraca, que no hacían sino tomarle el pelo, gozarse en su confusión y comentarla luego á solas, con maliciosa y despiadada ironía; pero ahora, al lado de la muchacha vestida de luto, experimentaba la misma turbación, porque, á pesar de su pobre traje, no tenía pinta de lo que se entiende por mujer ordinaria. «¿La diré algo? ¿Se reirá de mí? Más se reirá si me quedo mudo. No, la palabra hay que dirigírsela». Entonces se le ocurrió preguntar con suma formalidad:\"},{\"heading\":false,\"text\":\"--¿Quién le envía á mamá esa carta? ¿Lo sabe V.?\"},{\"heading\":false,\"text\":\"--Sé; sí, señor. ¿No he de saber? Las señoritas del general Romera. ¿No las conoce?\"},{\"heading\":false,\"text\":\"--¡Vaya si las conozco! El general Romera fué amigo de papá. Hace tiempo que no las vemos.\"},{\"heading\":false,\"text\":\"--Estuvo malita doña Pascuala, la mayor. Tuvo una cosa que le dicen _enginas inflamadas_. ¡Ay! Muy mala estuvo.\"},{\"heading\":false,\"text\":\"--Y ahora, ¿sigue mejor?--interrogó Rogelio por seguir hablando, aunque las anginas de doña Pascuala no le quitaban el sueño.\"},{\"heading\":false,\"text\":\"--Ya sanó de todo. Pues si no sanase, tampoco me marchaba yo de _junta_ ella.\"},{\"heading\":false,\"text\":\"--¿Estaba V.... allí?--(Rogelio no se atrevió á decir _sirviendo_.)\"},{\"heading\":false,\"text\":\"--Sí, señor, desde que vine de _allá_.\"},{\"heading\":false,\"text\":\"--¿Conque galleguita?\"},{\"heading\":false,\"text\":\"--No tengo por qué negarlo.\"},{\"heading\":false,\"text\":\"--Ni yo tampoco, caramba.\"},{\"heading\":false,\"text\":\"--No, señor, por cierto. Es una tierra muy buena, mejor que la de Madrí y la de todo el mundo.\"},{\"heading\":false,\"text\":\"Rogelio sonrió, agradado del patriotismo de la muchacha, y comenzando á sentirse bien con ella, porque le parecía incapaz de burlarse de nadie. Estaban próximos á la casa: Martín, que se había adelantado, paraba su jamelgo, operación más fácil que la de obligarle á salir al trote, y, desde el portal, doña Aurora hacía señas á su hijo.\"}]},{\"title\":\"Morriña — capítulo V\",\"blocks\":[{\"heading\":false,\"text\":\"--Mamá, aquí te traen una amorosa epístola.\"},{\"heading\":false,\"text\":\"--¿Esta chica?\"},{\"heading\":false,\"text\":\"--Sí, señora... De las señoritas de Romera.\"},{\"heading\":false,\"text\":\"--A ver, venga. Puede que sea cosa de despachar acto continuo.\"},{\"heading\":false,\"text\":\"Pero apenas hubo roto el sobre, la señora se echó á reir.\"},{\"heading\":false,\"text\":\"--¡Qué chiflada estoy! Sin mis gafas... Rapaz, lee tú.\"},{\"heading\":false,\"text\":\"Desplegó Rogelio la misiva, y ahuecando la voz, comenzó así:\"},{\"heading\":false,\"text\":\"--«Alta y poderosa y sobajada señora; si la vuestra fermosura...»\"},{\"heading\":false,\"text\":\"--Mira, niño, lee formal, que aquí corre un frío de los diablos y con el reuma mis caderas no están para músicas.\"},{\"heading\":false,\"text\":\"En tono natural leyó Rogelio:\"},{\"heading\":false,\"text\":\"«Nuestra más distinguida amiga: La dadora, Esclavitud Lamas, manifestará á V. el favor que pide. Nosotras sólo podemos atestiguar que todo el tiempo que estuvo en esta casa, observó ejemplar conducta, sin faltar nunca á su obligación; tanto, que su marcha nos deja muy disgustadas, por no tener queja ninguna de ella, al contrario.\"},{\"heading\":false,\"text\":\"«Quedan de V. afectísimas sus antiguas amigas,\"},{\"heading\":false,\"text\":\"«PASCUALA Y MERCEDES ROMERA.»\"},{\"heading\":false,\"text\":\"--¿No dice más, hijo?\"},{\"heading\":false,\"text\":\"--Trae una posdata tonta. No la leo, ea.\"},{\"heading\":false,\"text\":\"--¿Una posdata tonta?\"},{\"heading\":false,\"text\":\"--Sí; que por qué no me dejo ver, que ya estaré hecho un buen mozo... Las bobadas de cajón.\"},{\"heading\":false,\"text\":\"--Te lo estoy diciendo siempre, rapaz,--exclamó la madre con viveza.--Nunca subes diez minutos á casa de esas pobres señoras que te quieren tantísimo. Como que te han conocido así, hecho un muñeco. Pensarán que es culpa mía. Pues bastantes veces te hablo de ellas. ¡Pascuala y Mercedes! Si tú no vas iré yo.\"},{\"heading\":false,\"text\":\"--¡Pero, _mater terribilis_, si en cuanto piso aquella antesala me entra un sueño... y no hago sino bostezar!\"},{\"heading\":false,\"text\":\"--Pues son unas santas.\"},{\"heading\":false,\"text\":\"--¡Amén; yo no les quito su santidad; sólo digo que son tan pesaditas, tan patosas! Hablan á dúo como los alemanes de _La Diva_, «Rogelito, ¿qué tal la mamá? ¿Y los estudios?»--Al decir, así imitaba la voz cascada y el acento malagueño de las solteronas.\"},{\"heading\":false,\"text\":\"--Valiente pinturero estás tú,--murmuró la señora reprimiendo la risa.--No sé por qué te han de dar sueño Pascuala y Mercedes.\"},{\"heading\":false,\"text\":\"--Insondables enigmas del corazón humano. Arcanos profundos. En aquella _dimora casta è pura_ flota en la atmósfera un beleño letal.\"},{\"heading\":false,\"text\":\"--¡Farsante!\"},{\"heading\":false,\"text\":\"Mientras duraba esta escaramuza entre la madre y el hijo, la muchacha esperaba inmóvil, sin levantar los ojos del suelo. Doña Aurora se hizo cargo y se encaró con ella.\"},{\"heading\":false,\"text\":\"--Hija, dispense V. Aquí dice que V. me explicará el objeto de su venida. ¿Quiere subir?\"},{\"heading\":false,\"text\":\"--No, señora... Por mí no se moleste. Aquí mismo...\"},{\"heading\":false,\"text\":\"--A ver, no tenga V. reparo. ¿Alguna recomendación?\"},{\"heading\":false,\"text\":\"--Recomendación, no, señora. Es que yo quiero entrar á servir en casa de V.... ó de otra familia gallega,--añadió después de una pausa.\"},{\"heading\":false,\"text\":\"Doña Aurora miró fijamente á la postulante, y creyó advertir que se ruborizaba un poco.\"},{\"heading\":false,\"text\":\"--¿Usted... no estaba contenta con las señoritas de Romera, según eso?\"},{\"heading\":false,\"text\":\"--Sí, señora; por contenta sí... y me parece que ellas también conmigo; ya lo ve por la carta que me dieron. Por lo que es de las señoritas, estaría yo en la santa gloria, que son muy buenísimas, no despreciando: Dios las florezca. Sólo que á las veces... hay personas buenas y no se hace uno con ellas. Esas señoritas son de allá de Málaga, en tierra de Andalucía, y tienen unas costumbres y unas comidas que yo no las entiendo. Hasta el habla suya es atravesada para mí. Cuando me mandan hacer una cosa y no comprendo, me quedo como si me leyesen la sentencia de muerte. Y luego, señora, la verdad por delante: el no estar entre gente de su tierra, ni oir mentarla nunca, le pone á uno el corazón muy negro. Por la metá de soldada y con doble de trabajo, quiero servir á una persona del país.\"},{\"heading\":false,\"text\":\"Lo dijo con tal persuasión, que se aumentó la benevolencia de doña Aurora, prendada ya del porte decente y honesto de la muchacha, tan distinto del desgarro que gastan las _Menegildas_ madrileñas. Sólo que no veía claro aún en la historia: allí debía de haber algún intríngulis. Delante de la puerta, el simón chupaba su papelito, mientras el jamelgo bajaba la cabeza y estiraba los belfos, soñando con pienso abundante y prados deleitosos.\"},{\"heading\":false,\"text\":\"--Hija--advirtió la señora--yo voy á sentarme en el coche. Como no tengo sus años, me pesa el cuerpo y las piernas me bailan. De no subir, el coche sea conmigo.\"},{\"heading\":false,\"text\":\"La galleguita la ayudó á colocarse, y desde dentro, doña Aurora preguntó:\"},{\"heading\":false,\"text\":\"--Diga... Y estando V. tan pegada á la tierra, ¿cómo se vino de allá?\"},{\"heading\":false,\"text\":\"¡Ah! de esta vez no cabía duda: fué rubor, y rubor encendidísimo, el que tiñó los pómulos de la sirviente. Y al contestar--se necesitaba ser sordo, y sordo verdadero, para no percibirlo--tartamudeaba, sobre todo en las primeras frases.\"},{\"heading\":false,\"text\":\"--A las veces... tiene uno... que hacer aquello que menos le está pidiendo el corazón, señora... Somos hijos de la suerte. A mí me criara mi tío, el cura de Vimieiro. Dispuso el Señor de llevárselo; quedé sin arrimo. Para comer pan hay que trabajar. Era reina en mi casa; ahora sirvo. Alabado sea Dios, y nunca nos falten las manos y la salud.\"},{\"heading\":false,\"text\":\"--¿Cómo no entró V. á servir allá?--insistió la señora, que sobre una pista era más fina que el mejor sabueso. Y que la pista existía, no pudo dudarlo al ver que ya no era rubor, sino llamaradas de fuego, lo que pasó por el rostro de Esclavitud.\"},{\"heading\":false,\"text\":\"--No... no se me proporcionó--respondió con acento ahogado.--Luego, como allí todos me conocían, me daba vergüenza.\"},{\"heading\":false,\"text\":\"Doña Aurora Pardiñas recapacitó cosa de dos minutos, y endulzando el tono para suavizar lo áspero de la idea.\"},{\"heading\":false,\"text\":\"--Vamos á ver... Quien la recomienda á V. son las señoritas de Romera, que... que la conocen sólo del tiempo que estuvo en su casa. ¿No es eso? Pues sería conveniente... V. se hará cargo de ello... que tuviese aquí otras personas de allá, del país, para responder.\"},{\"heading\":false,\"text\":\"La muchacha titubeó un instante, y resolviéndose al fin, contestó:\"},{\"heading\":false,\"text\":\"--Me conocen el señorito Gabriel Pardo de la Lage y también la hermana.\"},{\"heading\":false,\"text\":\"--¿Rita Pardo? ¿La casada con el ingeniero? Pues si la trato mucho. ¿Y dice V. que la conoce?\"},{\"heading\":false,\"text\":\"No contestó la chica sino alzando la mano y el hombro como para expresar: «¡Bah! Desde que nací.»\"},{\"heading\":false,\"text\":\"--Bien...--murmuró la señora.--Francamente, hija, siento que deje V. á las de Romera. Mejor casa y mejores señoritas...\"},{\"heading\":false,\"text\":\"--No niego eso--replicó Esclavitud con mayor energía si cabe;--solamente que ya le he contado la verdad, señora, como si estuviese hablando con mi difunta madre ó con el confesor. Pegó conmigo la morriña, y si no salgo creo que se me revuelve la cabeza ó me voy derecha á la sepultura. Yo no comía. Yo me metía á cavilar por los rincones. Yo me fuí quedando morena, morena, y tan flaca, que la ropa se me cae. Yo de noche tenía unos aflictos como si me atasen una soga al pescuezo tirando mucho. Con esto y con todo me daba empacho descubrirme á mis señoritas. Lo conocieron ellas, y fueron las primeras en aconsejarme que, de no volverme á la tierra, que me metiese en alguna casa de gente de allá. «Hija, estás tan desmejorá que pareces otra». Mismo así me dijeron.\"},{\"heading\":false,\"text\":\"Al hacer esta narración, la barbilla de Esclavitud temblaba como la de los niños cuando reprimen la emoción que precede al llanto. Los ojos no se veían, porque los bajaba, según costumbre.\"},{\"heading\":false,\"text\":\"--Serénese--ordenó afectuosamente la señora. Iba entrándole una simpatía irresistible por aquella muchacha, de porte tan modesto y de corazón al parecer tan sensible. ¡Qué poco se parecía á las descocadas de Madrid, á las charranas de los barrios, chulapas sin pudor que no pueden estar en una casa decente! Justamente no hacía hora y media que la Pepa, la doncella, por un quítame allá ese polvo, se había desvergonzado poniéndose como una verdulera. Esta galleguita podría haber tenido... qué sé yo... cualquier desliz... porque lo de la escapatoria de su tierra no resultaba claro; pero el tipo era tan... vamos, tan de mujer de bien... Sabe Dios lo que le habría sucedido á la pobrecilla.\"},{\"heading\":false,\"text\":\"--Mire--declaró adelantando la cabeza por la portezuela--lo que es ahora mismo no le puedo contestar fijamente si la tomo ó no. Dése V. una vuelta mañana á estas mismas horas, y llame en el entresuelo. Me alegraría de que... pero hay que pensarlo. Si yo no pudiese, haré por descubrir alguna casa gallega... Dígame V. las condiciones, por si otra persona quisiese saber...\"},{\"heading\":false,\"text\":\"Esclavitud arrollaba entre las yemas del pulgar y el índice un pico del pañuelo de seda negra.\"},{\"heading\":false,\"text\":\"--Dios se lo pague. Por la soldada tanto me da un duro más como un duro menos. Al trabajo no le pongo mala cara. De cocinera no voy porque no sé estos guisos finos que se estilan ahora; sé las comidas de la tierra, así, sencillas. En lo demás me parece que daré gusto, lo mismo en limpiar, que en el repaso, que en la plancha. Lo que le pido es que en la casa que me busque, no haya... vamos... hombres que...\"},{\"heading\":false,\"text\":\"--¡Ya, ya!...--atajó doña Aurora. Y añadió bromeando:--Pero y entonces ¿cómo pretende V. mi casa? ¿No ha visto V. que en ella hay un hombre?\"},{\"heading\":false,\"text\":\"Señaló á Rogelio, que repuesto de su cortedad con la presencia de su madre, consideraba á la chica, reclinado en la portezuela del simón. Esclavitud siguió la dirección de la mano de la señora; por primera vez sus ojos, verdes, cambiantes, de mirada cándida, se fijaron en el estudiante: luego pronunció risueña:\"},{\"heading\":false,\"text\":\"--¿Este señorito es su hijo? Por muchos años... Dios se lo conserve. Este no es de los hombres que yo decía. Por ahora es un rapaz.\"},{\"heading\":false,\"text\":\"Demudóse Rogelio como si le hubiesen dirigido el más atroz insulto. Para disimular quiso reir, y la risa se le atascó en la garganta. Preciso es consignarlo: hasta sintió como el ardor de una lágrima en los ojos. Fué uno de esos instantes de rabia insensata y profunda, que alguna vez ha de sufrir el varón cuya infancia se prolonga más de lo justo; instantes en los cuales se apetece, como el mayor bien, poseer el amargo tesoro de la experiencia: dolores, desengaños, tribulaciones, luchas, enfermedades, canas, arrugas en el rostro, fracasos, traiciones de la amistad y del amor... todo, todo á trueque de oir la palabra reveladora, de gustar el fruto del bien y del mal, la eterna manzana dorada por un lado y sangrienta por otro. Todo por llenar el destino humano; todo por recorrer el ciclo de la vida.\"}]},{\"title\":\"Morriña — capítulo VI\",\"blocks\":[{\"heading\":false,\"text\":\"Cuando arrancó á andar el simón, la señora gritó á su hijo, que iba en el pescante: «Da las señas de Rita Pardo.» Rogelio obedeció, pero así que llegaron á la fea calle del Pez, donde vivía la señora del ingeniero, saltó á abrir la portezuela y dijo:\"},{\"heading\":false,\"text\":\"--No subo. Para esos informes que vas á tomar no me necesitas.\"},{\"heading\":false,\"text\":\"--¿Y á dónde te vas ahora?\"},{\"heading\":false,\"text\":\"--Por ahí,--respondió no sin alguna sequedad el estudiante, echando á andar y haciendo á su madre con la mano esa señal de despedida del hombre que se emancipa, algo semejante al nervioso aleteo del pájaro cuando le abren la jaula. Sin dar otra explicación, y embozándose más ceñido, desapareció en la revuelta de la primer esquina. La madre le siguió con los ojos mientras pudo: después suspiró y sonrió á medias.\"},{\"heading\":false,\"text\":\"--Algún día ha de ser...,--pensaba.--Está en una edad en que no se puede tirar de la cuerda mucho. Por supuesto que á mí no me la pega el pobriño: esto es un puro alarde de independencia: mirará cuatro escaparates, comprará seis ú ocho periódicos, dará unas vueltas con algún amigo que encuentre... y á su farmacia en seguida. Yo, si le viese fuerte, robusto, hecho un brutazo... otros á su edad tienen cada espalda y cada barbota negra que parece un tojal... El es así, tan finito, tan poquita cosa... Sácamele adelante, Virgen de los Remedios.\"},{\"heading\":false,\"text\":\"Las inquietudes maternales se apaciguaron cuando la señora, soltando el pasamano de la escalera, agarró el cordón de la campanilla para llamar en el tercer piso efectivo, con honores de principal, de Rita Pardo. Salió á abrir una niña como de once ó doce años, pálida, ojinegra, mal atusada y peor vestida, que en cuanto vió visita se escapó corriendo y gritando:\"},{\"heading\":false,\"text\":\"--¡Mamá! ¡mamá! La señora de Pardiñas.\"},{\"heading\":false,\"text\":\"--Que pase á la sala... voy inmediatamente...--respondió desde alguna oficina interior, cocina ó despensa, una voz de mujer. Doña Aurora, sin esperar el permiso, se dirigía ya al salón, modelo cumplido de la cursilería mesocrática, rebosando pretensiones y sin un solo mueble sólido ni artístico. Había dos ó tres sillas de felpa de colores variados, una _étagère_ con estatuitas de fundición, cacharros vulgares, y algún objeto de plata, sin ningún mérito, que sólo por ser de plata estaba allí; una alfombra de moqueta mal barrida; dos retratos al óleo del señor y de la señora, en óvalo, con traje dominguero, y otras ridiculeces semejantes. Conocíase que la sala se ventilaba y aseaba poco, y la alfombra daba evidentes indicios de haber en la casa criaturas menores.\"},{\"heading\":false,\"text\":\"Al cabo de diez minutos, apareció la señora del ingeniero, Rita Pardo. Venía acabando de abrocharse una bata demasiado lujosa, de raso azul pálido con encajes crema, por encima de la ropa interior, sucia del trajín casero: acababa de pasarse la borla de polvos, y le sonaban los brazaletes. Aunque ajamonada y algo desbaratada de cuerpo, ni la maternidad ni la madurez habían podido eclipsar su picante hermosura; pero la coqueta á quien conocimos poniendo el plano inclinado á su primo el marqués de Ulloa, se había transformado en matrona circunspecta y barnizada de una espesa capa de decoro, bajo la cual sólo el ojo lince del observador podía descubrir á la mujer verdadera, invariable, porque las almas se tiñen, se disfrazan, pero no se renuevan. Saludó cordialmente á la señora de Pardiñas, con aquello de «Tanto bueno, Aurora... ¡Jesús! En esta vida de Madrid, se van los meses y ni sabe uno de los amigos... Me coge V. hecha una visión... Las mañanas son terribles: las pierde uno en atender á chinchorrerías y á recaditos... Cuánto va á sentir Eugenio...»\"},{\"heading\":false,\"text\":\"Apenas dejó doña Aurora entrever el objeto de su visita, Rita Pardo suspendió la charla, y atendió con una curiosidad evidente, pintada en sus voluptuosos ojos negros y en su boca dura y fresca. Prolongada serie de gestos ambiguos y de risitas sospechosas fué preludio al siguiente comentario.\"},{\"heading\":false,\"text\":\"--¡Qué me dice V., qué me dice V.! ¡Esclavitud Lamas, Esclavitud Lamas! ¡La del abad de Vimieiro! ¡Ta, ta, ta, ta, ta! ¿Y cómo ha ido á batir con V. Esclavitud Lamas? ¿No es una chica rubia?\"},{\"heading\":false,\"text\":\"--No sé si es rubia. Lleva pañuelo negro que le tapa la cabeza. Viste de luto riguroso, muy aseada. La traza excelente.\"},{\"heading\":false,\"text\":\"--¡Vaya, vaya! ¡Conque Esclavitud Lamas, señor! ¡Mire V., mire V.! Sí, es, como decimos allá, muy moinita, muy modosa: habla tan pacato y tan suave que á veces no se la oye. Huele desde cien leguas á sacristía y á incienso. ¡Una santita mocarda!\"},{\"heading\":false,\"text\":\"Doña Aurora iba escamándose más de lo justo con este prefacio: resolvió, no obstante, disimular y apurar la verdad, toda la verdad, siquiera el descubrirla doliese á su corazón, interesado por la chica.\"},{\"heading\":false,\"text\":\"--¿Conque V. la conoce mucho?\"},{\"heading\":false,\"text\":\"--¡Jesús! Como á los dedos de las manos. ¡Si la conozco! Ese cura Lamas Tarrío era muy amigote de casa, ya antes de que papá le presentase para Vimieiro, cuando servía el otro curato en la montaña. Siempre le teníamos de huésped, y muy aficionado á hacer regalos: que manteca, que quesos, que huevos en Pascua, que en Navidad capones... Papá le apreciaba, porque en la montaña corrió bastante tiempo con la cobranza de las rentas. En fin, él era todo nuestro. A papá le debió también favores... favores gordos, doña Aurora.\"},{\"heading\":false,\"text\":\"--Bien: lo que yo deseo saber es lo referente á la muchacha. Si no tiene ningún mal antecedente, si puedo admitirla en mi casa... para mí será una satisfacción. No estoy contenta con la Pepa, y esta chica me ha entrado.\"},{\"heading\":false,\"text\":\"Rita Pardo sonreía con malignidad, al paso que estiraba los encajes de su manga izquierda, un poco abarquillados por el uso. Enarcó las cejas é hizo un mohín de difícil interpretación.\"},{\"heading\":false,\"text\":\"--¡Pst! Buenos antecedentes, es un término muy elástico, como V. comprenderá. Los buenos para unos son... medianitos para otros. En eso, hay quien hila más ó menos delgado. Si á V. le gusta tanto la chica...\"},{\"heading\":false,\"text\":\"--¡No, poco á poco!--exclamó alarmada ya la señora.--Para mí los buenos antecedentes son... los antecedentes buenos, sin más acá ni más allá. Sea V. franca y dígame todo lo que sepa, que á eso he venido; y ya con la espina que V. me clava, no tomo yo la chica, ni coronada de gloria, sin que V. me explique...\"},{\"heading\":false,\"text\":\"Volvió Rita á dar tormento á los encajes, y suspiró como quien se ve en aprieto.\"},{\"heading\":false,\"text\":\"--Aurora... hay cosas de esas que... que por muy públicas que sean, no puede uno tomar sobre su conciencia el descubrirlas. ¿V. no está en autos, eh? pues sería muy feo que yo la pusiese. ¿Que no llegó á oídos de V.? Mejor; ventaja para Esclavitud. Y puede V. tomarla, que á mí se me figura que resultará una excelente doncella.\"},{\"heading\":false,\"text\":\"--V. se guasea, Rita,--dijo la señora dando vado á su impaciencia creciente.--Me envuelve V. el asunto en el misterio, me hace V. de él una montaña, y luego me sale con que puedo recibir á Esclavitud. No, hija; en mi casa no se recibe á la gente así, sin más ni más. Aclare V. el enigma, y entonces...\"},{\"heading\":false,\"text\":\"Al llegar la entrevista á este terreno, adoptó Rita una actitud que hasta rayaba en desatenta. Se hinchó de nariz y de pecho, se hizo atrás y empezó á negarse, con el acento de la dignidad ofendida y del pudor lastimado.\"},{\"heading\":false,\"text\":\"Cuando después de agotar los razonamientos, doña Aurora obtuvo por seca respuesta un «Lo siento mucho, pero es imposible», la señora hubo de levantarse, no cuidándose de reprimir el mal humor que le producían aquellos impertinentes tapujos. Ya murmuraba con cólera: «V. perdonará que haya venido á molestar», cuando, después de un fuerte repique de campanilla y algunos gritos infantiles en el recibimiento, entró en la sala la niña mayor,--la zangolotina de doce años,--saltando de júbilo y exclamando:\"},{\"heading\":false,\"text\":\"--Mamá, mamá, tío Gabriel.\"},{\"heading\":false,\"text\":\"Entonces la viuda de Pardiñas, con repentina inspiración, se afirmó en el suelo calculando:\"},{\"heading\":false,\"text\":\"--Esta es la mía. Ahora verás, gata hipócrita, maulona, farsanta.\"}]},{\"title\":\"Morriña — capítulo VII\",\"blocks\":[{\"heading\":false,\"text\":\"Entró el comandante, vestido de paisano, metiendo bulla con la sobrinita, que era su ojo derecho, y trayéndola cogida de la cintura, como si fuesen á bailar un vals. En cambio, en el saludo que hizo á su hermana pudo notar doña Aurora esa sequedad muy parecida al desvío, que á veces consigue disimularse respecto de los indiferentes, pero nunca en familia. Después de las fórmulas y cumplimientos de rigor, la señora de Pardiñas, que no desmentía su raza en punto á diplomacia y tenacidad, insinuó como aquel que no quiere la cosa:\"},{\"heading\":false,\"text\":\"--Vaya, les dejo á Vds. Al fin no consigo saber lo que deseaba, y para eso... Su hermana de V. es reservadísima, señor de Pardo.\"},{\"heading\":false,\"text\":\"--A fe que no lo creí,--contestó redonda y duramente el artillero.\"},{\"heading\":false,\"text\":\"--Pues mire V., cada uno habla de la feria según le va en ella. Conmigo ha mostrado una prudencia... atroz.--Y, sin atender al gesto y la mirada de Rita, continuó impávida:--Un cuarto de hora hace que le pido informes de una chica paisana nuestra, Esclavitud Lamas, la sobrina del abad de Vimieiro...\"},{\"heading\":false,\"text\":\"Pardo prestó oído, como el que escucha algo que le despierta memorias confusas.\"},{\"heading\":false,\"text\":\"--Aguarde V., aguarde V... Vimieiro... Lamas... Lamas Tarrío... Ese cura era íntimo de papá. Rita sabrá cuanto á él se refiere; lo sabrá al dedillo. ¿Qué reparo has tenido en decirle á doña Aurora?...\"},{\"heading\":false,\"text\":\"Un caricaturista que quisiese representar la dignidad burguesa en su más enfática expresión, debiera copiar el rostro y la flexión de cejas de Rita, que señalando á su hija mayor, casi sentada en las rodillas del comandante, exclamó con acento profundo:\"},{\"heading\":false,\"text\":\"--¡¡La niña!!\"},{\"heading\":false,\"text\":\"--¡¡Y qué, la niña!!--respondió Don Gabriel remedando el tono dramático de su hermana.--¿Tenemos alguna de esas cosas terribles que no puede oir la inocencia; que ha parido la gata, pongo por caso?\"},{\"heading\":false,\"text\":\"--Gabriel, eres tremendo, hijo,--gimió Rita, alzando al cielo sus bellos ojos meridionales.--Una matándose por hacer de tus sobrinas lo que deben ser en sociedad, y tú empeñado... Manías de las personas; con eso no se puede.\"},{\"heading\":false,\"text\":\"--Ea, señores,--insistió la pesada de doña Aurora,--yo estoy á mi pleito. Rita, no diga V.; lo que es por la niña no dejó V. de darme esos informes. La niña no estaba delante; y sobre todo, con enviarla á otra habitación...\"},{\"heading\":false,\"text\":\"--Que es lo que voy á hacer ahora mismo. Eugenia, vete, hija, á estudiar el método de Concone.\"},{\"heading\":false,\"text\":\"La chiquilla salió á contrapelo, no sin obsequiar á su tío con dos ó tres carantoñas de despedida; pero ninguna escala ni ningún estudio reveló que se hubiese encerrado en el potro musical donde diariamente se descoyuntan las manos nuestras señoritas, dignas de mejor suerte.\"},{\"heading\":false,\"text\":\"--Verá V.,--recalcó doña Aurora,--ahora que podemos hablar libremente. Se trataba de que esa chica, Esclavitud Lamas, quiere entrar en mi casa á servir; y á mi sus tracitas me gustan mucho. Pero no sé sus antecedentes, ni el motivo por qué se vino de su tierra. Me huele á alguna historia rara todo ello. Su hermana de V. sabe la historia, y ni por Dios ni por los santos me la quiere contar. Ahí tiene V. nuestra batalla. Ya nos estábamos formalizando cuando V. llegó.\"},{\"heading\":false,\"text\":\"--La historia...,--dijo Gabriel limpiando nerviosamente sus lentes de oro y calándoselos con ahinco.--Aguarde V., señora, que si mi memoria de gallo no me juega alguna trastada... ¿Tú, Rita, ese cura Lamas Tarrío no es el que recogió una niña pobre? Dime la verdad, que si no, escribo hoy mismo á Galicia preguntando.\"},{\"heading\":false,\"text\":\"--¡Jesús, hijo, pero qué cosas tienes! Eres incapaz, y cada día que pasa... ¿No iba yo á decirte la verdad? Sí, ese Lamas fué, y ya que se te antoja abrir su sepultura y sacarle á la vergüenza pública, sácale tú, que yo no quiero semejante cargo de conciencia.\"},{\"heading\":false,\"text\":\"--Más cargo de conciencia es,--replicó Gabriel con vehemencia,--que la chica pierda su colocación por delitos ajenos. Doña Aurora, ahora le puedo yo contar á V. la historia enterita: por un cabo ha salido toda la madeja; en esto de historias sucede lo que con las tonadas antiguas, que si recuerda uno el primer compás, ya puede cantarlas enteras sin equivocarse. ¡Y le aseguro á V. que es una novela... vamos, una novela!\"},{\"heading\":false,\"text\":\"--Allá tú,--articuló Rita venenosamente emprendiéndola con los encajes otra vez.--Yo, ciertas cosas... Lavo mis manos.\"},{\"heading\":false,\"text\":\"Disimuló doña Aurora el gozo del triunfo; pero hembra al fin, miró á Rita de soslayo y pensó:\"},{\"heading\":false,\"text\":\"--Fastídiate, pinturera...\"},{\"heading\":false,\"text\":\"--Verá V.,--empezó el comandante.--Ese cura Lamas fué un infeliz, ignorantón como lo era entonces todo el clero rural, que hoy se ha civilizado mucho, y bastante zoquete; pero cumplía sus deberes parroquiales, y si tenía deslices los encubría bien: no puedes ser casto, sé cauto, como dicen ellos. Por cuanto una noche llega á la rectoral una chiquilla, de diez años poco más ó menos, que había quedado huérfana y vagaba pidiendo limosna: en una casa le daban un mendrugo de pan de maíz, en otra un poco de hoja del mismo maíz para tumbarse y dormir; aquí un pañuelo roto, allí unos zuecos viejos... Así vivía la desdichada. El cura se compadeció, y le dijo: «Pues quédate aquí; aprenderás las labores caseras..., tendrás vestido, cama y caldo caliente.» Dicho y hecho; la chiquilla se quedó...\"},{\"heading\":false,\"text\":\"--¿Y era Esclavitud?\"},{\"heading\":false,\"text\":\"--No, señora; no, señora... Aguarde V. Salió la chica habilidosa y despabilada: echó, como dicen allá, la morriña fuera..., y hasta se puso lozana y guapetona. Y,--aquí la voz del comandante adquirió tonos irónicos,--al desabrochar la flor de la nubilidad...\"},{\"heading\":false,\"text\":\"--¡Ay, Gabriel!...--respingó Rita.--Ciertas cosas se pueden contar de otro modo. No se necesita entrar en detalles que...\"},{\"heading\":false,\"text\":\"--¡Bah!--dijo doña Aurora.--Todos somos casados, y yo vieja. Ya estamos al cabo y curados de espantos, amiga. Siga V. ¿Qué vino después?\"},{\"heading\":false,\"text\":\"--Después vino Esclavitud.\"},{\"heading\":false,\"text\":\"Aunque la señora afirmaba _estar al cabo_, la noticia, dicha así de pronto, casi la hizo saltar en la silla.\"},{\"heading\":false,\"text\":\"--¡Aah!--pronunció, quedándose muy meditabunda.--Por eso la pobre... Bueno: ¿y después?\"},{\"heading\":false,\"text\":\"--¿Después?--recalcó fogosamente Rita, incapaz de contenerse, metiendo al fin cucharada.--Después mi papá se vió negro para amansar al Cardenal Arzobispo, el señor Cuesta, que estaba hecho un león. Como era tan virtuoso, aquel señor apretaba las clavijas y no permitía desmanes. Pues si no es lo que papá machacó en Su Eminencia, y hoy una súplica y mañana otra, sin licencias se queda Lamas Tarrío, y se pudre en la cárcel eclesiástica. Porque una cosa es que á un sacerdote se le escurra el pié y cometa gatuperios allá donde nadie lo sabe, y otra que esté escandalizando á los feligreses, y que críe la chiquilla en su casa á ciencia y paciencia de todo el mundo, y la traiga en brazos, y...\"},{\"heading\":false,\"text\":\"--Mi padre,--advirtió Gabriel interrumpiendo á su hermana,--con una mano machacaba en el Arzobispo, y con la otra martillaba en el culpable. A fuerza de exhortaciones pudo conseguir que la sirena saliese de la rectoral; pero Lamas seguía viéndola. Al fin papá se cuadró, le echó al cura unas pláticas que me río yo de las del capuchino más barbado, y pudo conseguir que enviase á la madre á Montevideo, á condición de que le dejasen la chiquilla.\"},{\"heading\":false,\"text\":\"--Sí,--volvió á entrometerse Rita,--bonito remedio fué: peor que la enfermedad. El hombre quedó más rabioso y más relajado de lo que estaba. Se pasaba las noches en vela llorando y gritando; le dieron unos arrebatos de sangre,--en casa por cierto,--que fué preciso aplicarle un golpe de más de cuarenta sanguijuelas; y la sangre salía negra como la pez. Creímos que se volvía loco: andaba por los corredores arrancándose los pelos, llamando á la individua, y diciéndole cosas babosas...\"},{\"heading\":false,\"text\":\"Cuando esto soltaba Rita, su hermano observó que las cortinas del gabinete contiguo se agitaban como movidas por un céfiro de curiosidad retozona, y casi se dibujaba en ellas el relieve de un hociquito atento.\"},{\"heading\":false,\"text\":\"--Mira,--advirtió,--ahora eres tú la que te metes en honduras. Todo eso no viene al caso. Despachemos pronto la historia, y deja que yo la acabe. El pobre Lamas se puso tan mal, que le dió lástima al mismo Arzobispo, el cual le llamó para animarle é infundirle deseos de penitencia. Y, en efecto, con el curso del tiempo, fué sosegándose, y hasta se portó bastante bien en lo sucesivo. Unicamente se le podía tachar de que criaba á la niña con mimos extremados; pero como el sentimiento de la paternidad, aun cuando atropelle toda ley divina y humana, tiene mucho de sagrado, la gente transigió. El presentaba á la chica diciendo que era sobrina suya. Como los hijos sacrílegos no heredan, el cura ahorró dinero, onza tras onza, para entregárselo en mano propia á Esclavitud; pero la chica, que ha salido muy remirada y muy devota y muy desinteresada además, al morir Lamas entregó todo ese dinero, en oro como lo había recibido, para misas y sufragios por el alma del pecador. Este solo rasgo le pinta á V. el carácter de la muchacha: pocas harían otro tanto, aunque hubiesen nacido en mejores pañales y más... ortodoxamente.\"},{\"heading\":false,\"text\":\"--Mi hermano, como tiene así la imaginación, pinta muy románticas las cosas.\"},{\"heading\":false,\"text\":\"--Señora de Pardiñas, palabra de caballero que ni quito ni pongo. Esa chica, según entiendo, sería capaz de irse á cualquier parte en peregrinación, descalza, para sacar del purgatorio el alma del cura de Vimieiro.\"},{\"heading\":false,\"text\":\"--Falta le haría,--advirtió Rita,--y también para la de su madre, que allá en América parece que se dió á la vita bona.\"},{\"heading\":false,\"text\":\"--¡Válgame el cielo, y qué inquisidores os volvéis los que nunca habéis carecido de consideración ni de pan!--exclamó Pardo, ya indignado seriamente.--Yo no peco de filántropo; pero ciertas cosas no me las explico en gente que alardea de cristiana, y va á misa, y reza. Buenos rezos son esos, buenos. ¿Así entiendes tú la caridad? Pues hija, afirmo que esa Esclavitud vale más que...\"},{\"heading\":false,\"text\":\"Se contuvo por fortuna, y añadió:\"},{\"heading\":false,\"text\":\"--Que otras personas. ¿Qué culpa tiene ella de las faltas de sus padres, diga V.? Y las está expiando como si las hubiese cometido. Hasta se expatrió, según veo, y juraría que es por vergüenza, por no estar donde la gente _sepa_ y _recuerde_ y _diga_...\"},{\"heading\":false,\"text\":\"--También juraría lo mismo--asintió con calor doña Aurora.--Ahora entiendo por qué se sofoca tanto cuando le hacen ciertas preguntas. Yo opino como V., Pardo, como V., que es buena; que tiene sentimientos nobles... y que esos rasgos la honran mucho.\"},{\"heading\":false,\"text\":\"--Sí, guíese V. por mi hermano. Admítala en su casa,--exclamó Rita con una carcajada impertinente, que salía de lo más dañado de sus hígados.--Tocante á dar consejos, Gabriel es una especialidad. Le tiemblo cuando pega la hebra con mi esposo. Si Eugenio se guiase por él, estaríamos pidiendo limosna. Cargue V. con esa chica, ya verá cómo sale con las manos en la cabeza. Entonces dirá V.: «Bien me lo avisó Rita Pardo.»\"},{\"heading\":false,\"text\":\"La señora pensaba para su rotonda de pieles:\"},{\"heading\":false,\"text\":\"--Aunque sólo fuera para hacerte tragar quina; falsa, maulona... Ya te he calado, ya.\"},{\"heading\":false,\"text\":\"Al salir Gabriel, esperábale en la antesala su sobrina mayor. La cogió por el talle, y subiéndola á la altura de su boca, entre risas de la chiquilla, le deslizó al oído:\"},{\"heading\":false,\"text\":\"--Las niñas buenas, para que tití Gabriel las quiera mucho, no atisban, no husmean, no se esconden detrás del portier... Obedecen á su mamá, porque es su mamá, y no les ha de mandar cosa mala... ¡Cuidadito con morder, lagartija! Las niñas buenas... son buenas. ¡Ay! ¡Mi corbataaá!\"},{\"heading\":false,\"text\":\"--¿Tití Gabriel, me llevas contigo?--arrullaba la zangolotina.--Contigo sí, contigo no..., contigo sí me iría yo. ¡Llévame, anda!\"},{\"heading\":false,\"text\":\"--A Leganés te llevaré... ¡Juicio! ¡Estudie V. la lección de francés! ¡Péinese V. ese felpudo! ¡Dé V. una vueltecita por la cocina, á ver qué hace la pobre chica esa! ¡A papá le gusta el rosbif muy poco hecho! ¡Cuide V. el rosbif de papá!\"},{\"heading\":false,\"text\":\"Al cruzar la puerta, el comandante le echó á la niña un beso volado, y ella pagó en seguida el envío.\"}]},{\"title\":\"Morriña — capítulo VIII\",\"blocks\":[{\"heading\":false,\"text\":\"Doña Aurora acostumbraba llevarle á su hijo el chocolate á la cama, porque, chapada á la antigua en muchas cosas, estábalo también en madrugar. Era un momento delicioso para la mamá chocha aquel del chocolate.\"},{\"heading\":false,\"text\":\"El rapaz, como ella le llamaba, tenía al despertarse ese regocijo sin causa, propio de los años primaverales, en que parece que cada día nuevo sale de manos del tiempo dorado y lindo, esmaltado de dichas, y en que el peso de recuerdos dolorosos no sujeta aún las alas vibradoras de la esperanza. Rogelio, que por las tardes padecía á veces un abatimiento nervioso, por las mañanas era un pájaro en lo vivo y juguetón. Hasta su charla se parecía al gorjeo de las aves cuando amanece y de los niños cuando abren los ojos. Sentada su madre á la cabecera, después de haber apartado las prendas de ropa esparcidas y los libros desparramados aquí y acullá, sostenía la bandeja para que no se volcase la jícara, donde el muchacho mojaba los rubios buñuelos, mientras esperaba turno un vaso de purísima leche. ¡Y qué de sudores y fatigas le costaba á doña Aurora el tal vasito! Ya podía ella dar quince y raya á todos los químicos del gabinete municipal: sin análisis, ni instrumentos, ni pamplinas, á simple vista, por el color y el olor, conocía los grados y cualidades de la leche toda que se expende en Madrid. ¡Como que sus esperanzas de ver engordar á Rogelio las cifraba en aquel vasito de leche bebido antes de clase, y en el bisteque engullido al salir de ella!\"},{\"heading\":false,\"text\":\"A la hora del chocolate era cuando se comentaban todos los sucesos de la víspera, las graciosas reyertas de Nuño Rasura y Laín Calvo, los chistes estudiantiles, el último crimen, el fuego de anoche, junto con los menudísimos acontecimientos de aquel hogar realmente tranquilo (como lo son tantos en la corte, á despecho de la superstición provinciana que considera á Madrid un torbellino ó vértigo perenne). Lo primerito que hizo Rogelio, la mañana que siguió al día en que vino á pretender la gallega, fué preguntar á su madre, con mal disfrazado interés:\"},{\"heading\":false,\"text\":\"--¿Qué tal? ¿Qué te han dicho sobre la cándida doncella... de labor?\"},{\"heading\":false,\"text\":\"Nada tenía la pregunta de importuna ni de extraña; sin embargo doña Aurora se quedó algo cohibida, fluctuando entre referir puntualmente lo averiguado ó callárselo. No; lo más prudente sería esto último. Se trataba de cosas graves, y si Rogelio no guardaba toda la discreción necesaria... Era preciso irse con tiento.\"},{\"heading\":false,\"text\":\"--Mira, ratiño, en primer lugar tengo que advertirte que he despachado á la Pepa.\"},{\"heading\":false,\"text\":\"--¿Hola? ¿Caen aquí los ministerios sin que me entere yo?\"},{\"heading\":false,\"text\":\"--Verás. Andaba muy engreída, muy respondona. Le planté la cuenta en la mano. Todo les aguanto menos que repliquen. Supongo que había novio por medio, que si no... La verdad: estoy harta de estas criadas de Madrid tan remontadas y tan insufribles con ese salero y ese desgarro. Prefiero una chica humilde, bien mandadita. Con una buena palabra me compran; no lo puedo remediar. Si vieses la tal Pepa, qué modos y qué remangos. Hecha un conejo de monte. ¡Ay! me parece mentira que se fué.\"},{\"heading\":false,\"text\":\"--_Mater_, basta ya de prolegónemos--exclamó el chico ensopando en la leche la lengüeta de un bizcocho.--Todo esto viene á parar en que tomas á la misteriosa enlutada. Te entró por el ojito derecho, y caá uno tiene sus debilidaes.\"},{\"heading\":false,\"text\":\"--No seas bobo. Lo que quiero es que el servicio ande corriente. Esa muchacha merece interés. Cuando yo lo digo...\"},{\"heading\":false,\"text\":\"¡Ay! propósitos de reserva, programas de discreción, temedle como al fuego á estas reticencias involuntarias, que abren de par en par la puerta á las confidencias absolutas. La señora quería callar: pero ¿quién calla después de soltar prenda? Ni la hubiese dejado vivir Rogelio. Además, doña Aurora, en el fondo, también deseaba relatar su triunfo, decir cómo había vencido á aquella pinturera farsantona de Rita Pardo. Tan dulce desahogo era el precio de la victoria. Hay un placer, cuyo origen no se define, pero á cuyo atractivo cede casi todo el mundo, en referir esos dramas hondos de la vida humana, que de rechazo nos tocan á todos, que tienen el don de interesarnos porque despiertan nuestros sentimientos de compasión y justicia, y al par nos ponen frente á graves problemas, sin obligarnos á resolverlos, sino sólo á considerarlos como consideramos en el teatro el argumento de una tragedia engendradora de terror y piedad. Rogelio, con el codo puesto en la almohada y los ojos muy abiertos, atendía afanosamente á la narración novelesca de su madre.\"},{\"heading\":false,\"text\":\"--Ya ves--advirtió ésta al concluir su historia--que á la pobre hay que tratarla con ciertos miramientos. Ella, dada su situación, no ha podido portarse mejor. Desinteresada como pocas, y aparte de eso religiosa y formal. Por lo que he sacado en limpio, ella se cree una hija de maldición, que anda cargada con los pecados de sus padres, y se abochorna de que allá la vean y recuerden lo ocurrido. Hay que proceder con mucho tino en como se le habla. Del padre no se puede ni indicar tanto así... Pues de la madre, aun menos... porque la muy picarona vive aún, y anda por esos mundos de Dios corriéndola...\"},{\"heading\":false,\"text\":\"--Vamos...--respondió Rogelio recobrando su buen humor--resulta que á la niña la miraremos como si fuese un hongo. Si alguna vez se trata de papás y de mamás, la diré: «Ya sé que V. no los tuvo nunca». ¿Te parece bien?\"},{\"heading\":false,\"text\":\"--¡Chiquillo, no me seas rematado! Cómete ese bizcochito más. Lo que quiero decir es que no le des bromas pesadas. Esas personas así, que sufrieron grandes desgracias, son más sentidas; se sobresaltan por cualquier cosa. ¡Yo desearía tenerla contenta!... En este Madrid y en el servicio que ofrece, coger una chica virtuosa y de tan buen avío, créeme que es una ganga. ¡Hay cada sargentona y cada lercha!\"},{\"heading\":false,\"text\":\"--¿Te parece que compre un ramito de flores para ofrecérselo galantemente cuando penetre en nuestra mansión?--preguntó el estudiante. Su madre le descargó un bofetoncito muy tierno, agregando:\"},{\"heading\":false,\"text\":\"--Lo que voy á comprar yo es un aguamanil y otras cosillas, porque aquella desencuadernada de Pepa me dejó el cuarto hecho una leonera, y esta muchacha tan aseada no va á encontrar ni donde lavarse las manos. Aguamanil, jabón, una mesita de noche... y un ruedo limpio para que con ese frío no salte de la cama sobre las baldosas, que están como la pura nieve. Mejor que un ruedo será un pedazo de alfombrita de moqueta: ¡la hay tan barata! Le voy á comprar también paño gordo para una chaquetita: me parece que no tiene abrigo: á cuerpo venía ayer... No sé cómo estará de ropa blanca. Siento haberle dado á la Pepa, no hará quince días, tres camisas preciosas.\"},{\"heading\":false,\"text\":\"--¡Bah! Con encargarle á París un _trusó_ como el de la señora de Cánovas, por ejemplo... Diez docenas de elegantes peinadores y cuatro mil pares de medias de seda... ¿Bastará?\"},{\"heading\":false,\"text\":\"Doña Aurora salió temprano y volvió antes de las doce con sus adquisiciones hechas. Se complació en ver barridito el cuarto y colocados en su sitio el palanganero y la alfombra. Puso toallas limpias y sacó una colcha blanca de muletón, á fin de que la cama de hierro pareciese más cuca. Dió una vuelta, y al entrar de nuevo en el cuartucho no pudo menos de reirse á carcajadas. En un vaso de cristal azul lucía un ramillete de á dos cuartos: Rogelio, escondido detrás de la puerta, acechaba el efecto.\"},{\"heading\":false,\"text\":\"--¿Qué tal este timo? ¿Eh? ¡Ya tenemos _buqué_, caray, carapuche! como dice Laín Calvo. Es de gardenias: me cuesta diez duros. ¿Voy por alguna begonia? Haría muy bien un macizo al lado del aguamanil. Escribiremos la crónica después: «La alcoba se había transformado, al toque de la varilla de un hada, en frondoso jardín de invierno...»\"},{\"heading\":false,\"text\":\"Esclavitud fué recibida tan pronto como se presentó, á eso de la una: pero quiso ir á despedirse de las señoritas de Romera. No se instaló en su nueva casa hasta por la tarde, trayendo consigo un mozo de cordel, portador de uno de esos baúles gallegos forrados de piel de buey, que tienen cantoneras de hojadelata. Pesaba tan poco, que al llegar al pié de la escalera la muchacha se lo cargó á hombros y lo subió ella misma. En aquel baúl casi vacío traía todo lo que le tocara por herencia del abad de Vimieiro.\"}]},{\"title\":\"Morriña — capítulo IX\",\"blocks\":[{\"heading\":false,\"text\":\"Los primeros días estuvo como gallina en corral ajeno. Realmente, fuese debido á sus antecedentes históricos ó á la extraña enfermedad nostálgica que padecía desde su llegada á Madrid, la chica aparecía desmejorada y en un estado de caimiento que, si no la impedía trabajar con asiduidad y hasta con ardor, la quitaba esa valentía que hace insensible el trabajo. Su demacración era evidente, y aunque por las esbeltas proporciones del talle y por ciertos rasgos de su cara se revelaba muy joven, por el carácter, el estado de ánimo, la severidad de su continente, cualquiera podía calcularle la edad en veintiocho ó treinta.\"},{\"heading\":false,\"text\":\"Es de advertir que esta especie de murria y desaliento no le impedía cumplir estrictamente su obligación. Al contrario, Esclavitud realizaba el tipo de la criada modelo. Levantábase muy temprano, casi con estrellas, y antes de que la cocinera hubiese soñado en encender la lumbre, ya estaba ella arreglando todas las menudencias concernientes al desayuno de los amos. Desde el primer día se reservó la preparación de chocolates, y los hacía con esmero clerical. El secreto, que ya va perdiéndose, del tiempo, hervores y batiduras indispensables para que una solución de cacao salga aromática, ligada y substanciosa, lo poseía tan á fondo Esclavitud, que doña Aurora juraba no haber probado en su vida chocolate por el estilo. En barrer tampoco se quedaba atrás. Con el pañuelo atado á la curra y las sayas recogidas, pero sin gran alboroto ni mucho trasteo de muebles, barriendo manso, por decirlo así, nadie sería capaz de descubrir un átomo de polvo en los lugares por donde había pasado aquella inteligente escoba. El no sacudir con exceso, ni aporrear demasiado con los zorros, molestando á todo bicho viviente so pretexto de limpiar, era un mérito más á los ojos de doña Aurora, enemiga de la gente arrebatada y brusca. Pero donde la fámula nueva descollaba era en el repaso. Veíase que estaba menos acostumbrada á trabajos de fogón y á trajines caseros que á la labor sedentaria, en silla baja, junto á una ventanita. En dos horas despabilaba el canasto de ropa, y eran de admirar sus invisibles zurcidos, sus mañosas piezas, sus indestructibles presillas y sus firmes botones. Doña Aurora decía á las amigas:\"},{\"heading\":false,\"text\":\"--Hoy no recelo yo echar á diario la ropa buena. Con esta Esclavitud, ni una puntilla descosida, ni un bordado roto. Es una delicia verla con la aguja en la mano.\"},{\"heading\":false,\"text\":\"Pero al mismo tiempo, el carácter expansivo de doña Aurora no podía sufrir aquella reservada melancolía de la muchacha. Mientras más contenta estaba de su servicio, más desearía verla andar con ese aire ligero que revela alegre conformidad con la suerte que nos toca y la ocupación que desempeñamos. ¡Tantas consideraciones con la dichosa chica, y ella siempre enfurruñada y cavilosa! La señora de Pardiñas tenía en su bondad un elemento de egoismo, retoño natural de aquella bondad propia: al hacer un beneficio, deseaba cobrarse en el espectáculo de la felicidad ajena; y este gusto la dominaba tanto, que para vivir tranquila y satisfecha, necesitaba persuadirse de que lo estaban todos á su alrededor. En su determinación de admitir á Esclavitud, habían influido dos móviles: primero, llevar la contraria á aquella antipática de Rita Pardo: segundo, contentar á una chica de tan agradable aspecto como Esclavitud, desempeñando en cierto modo papel de Providencia y reconciliándola con el destino, para ella funesto é implacable desde la hora de nacer. Y este segundo generoso propósito se le malograba, porque la chica no quería levantar cabeza ni abrir el alma á la buena suerte.\"},{\"heading\":false,\"text\":\"Un día hasta notó doña Aurora que su doncella apenas probaba alimento, obstinándose al mismo tiempo en continuar el trabajo y en responder que «no tenía nada». La señora poseía un carácter franco, impetuoso y directo, de los que no abundan en el país galaico: daba salida inmediata á sus impresiones, y si no pudiese hacerlo, creería tener una pera de ahogo encajada en el gaznate. Sin detenerse más, acorraló á la muchacha junto á una ventana, sitio claro donde la sombra del pañuelo de seda negra no podía encubrir el estado de los ojos y el movimiento de la fisonomía.\"},{\"heading\":false,\"text\":\"--Hija, ¿qué te pasa?--la preguntó maternalmente á boca de jarro.--¿Tienes algún disgusto? ¿Estás enferma? ¿No te sienta la comida? ¿Te falta alguna cosa?\"},{\"heading\":false,\"text\":\"La muchacha se encendió, cosa que le sucedía en toda clase de emociones, y respondió bajito:\"},{\"heading\":false,\"text\":\"--No, señora, ¿qué me ha de faltar? Dios se lo pague.\"},{\"heading\":false,\"text\":\"--Pero vamos á ver, ¿es que tampoco aquí estás contenta? ¿Te tratamos mal? ¿La compañera no se porta como debe? ¿Necesitas más ropa de abrigo?\"},{\"heading\":false,\"text\":\"Como la muchacha guardase silencio, diciendo que _no_ con la cabeza, dulce y obstinadamente, insistió la señora:\"},{\"heading\":false,\"text\":\"--Harás muy mal, te lo aviso, si te quedas con el embuchado dentro. Peor para ti si eres mema. Pudiendo estar á gusto no entiendo á qué vienen estos silencios y estas tonterías. A mí me agrada ver alrededor caras de Pascua. El gesto compungido, y más cuando no hay motivo ninguno, se me sienta en la boca del estómago.\"},{\"heading\":false,\"text\":\"Esto lo articuló ya con enfado, viendo el tenaz mutismo de Esclavitud. Al mismo tiempo discurría para sí: «La muchacha tiene las buenas cualidades de nuestro país, pero no le faltan los defectos. Es humilde, modosa y callada, pero también es algo zorrita, y no hay modo de saber lo que piensa ni lo que le pasa. Las chulapas de por aquí son unas caridelanteras y unas raídas, pero al menos son toros claros: al pan, pan, y al vino, vino; esto sí, esto no. Para un genio como el mío...»\"},{\"heading\":false,\"text\":\"En estos pensamientos estaba, cuando sonó la campanilla, y se oyó en el recibimiento la voz de Rogelio que volvía de clase. Instantáneamente las mejillas de Esclavitud se encendieron todavía más é hizo un movimiento instintivo, como intentando huir y esconderse.--«¡Ta, ta!»--discurrió la señora, iluminada por un rayo de sagacidad repentina.--«Ya había yo notado que el rapaz tenía con esta chica no sé qué. La habla tan secamente, cosa rara en él... ¡Vamos! la pobre está así amohinada, porque conoce que no le ha caído en gracia al chiquillo. Es preciso que yo arregle este cotarro; se ve que Esclavitud peca de susceptible, y cuando imagina que la miran mal...»--Insistió entonces en alta voz.--«Hija, pues mira que si estás á disgusto...»\"},{\"heading\":false,\"text\":\"--Yo no estoy á disgusto, no, señora--contestó Esclavitud con respeto y no sin firmeza.--Como los demás no estén á disgusto conmigo... Yo estoy perfectamente, lástima fuera. Pero otros...\"},{\"heading\":false,\"text\":\"--¿De dónde sacas eso?--replicó la señora mirándola fijamente.--¿Te he regañado desde que entraste?\"},{\"heading\":false,\"text\":\"--No, señora. V. es muy buena. Si yo no me quejo de nadie--repuso la chica.--Sólo tengo recelo, así, vamos... de no dar gusto. No dando gusto más quiero no estar. Para no dar gusto aún vale más meterse... en el infierno que sea, señora.\"},{\"heading\":false,\"text\":\"--Calla, calla, boba--gruñó su ama.--Ya se ve que das gusto. A tu repaso. Como me vuelvas á salir con pasmarotadas..., verás.\"},{\"heading\":false,\"text\":\"En cuanto pudo hacerlo todo lo sigilosamente que el caso requería, doña Aurora llamó á capítulo á su hijo.--«Te aseguro que el intringulis de esas murrias de Esclavitud es la cara que tú le pones... A Fausta le hablas de distinto modo... no lo notas tú mismo...; pero con Fausta armas siempre gresca y broma, y la otra, como te ve serio, claro, imagina que estás torcido con ella, y que no te da gusto, como ella dice... Te aseguro que la infeliz anda decaidísima, y que es capaz de enfermarse muy de veras. Son una tecla estas muchachas nerviosas. Y aparte de eso, como median los antecedentes de su... del cura, ¿eh? cada vez está la chica más sensible... Palabra, que me da lástima. Yo que tú le hablaría... así... con más afecto.»\"},{\"heading\":false,\"text\":\"El estudiante oía las palabras de su mamá, pero con el rostro vuelto hacia un cuadro, que parecía llamarle mucho la atención. Cuando tuvo que responder lo metió á barullo.--«Nada, que de esta noche no pasa...: compro una mandolina y le doy serenata á esa madamisela. Le voy á traer más flores y me pondré á ver si le hago unos versos del género de los de mi amigo Anastasio Cardona, con cada ripio así. La llamaré ninfa acuática y vago ensueño del poeta. Ya verás, ya verás... Ajustaremos paces la ilustre fregona y yo.»\"},{\"heading\":false,\"text\":\"En el fondo del corazón, Rogelio se sentía extraordinariamente envanecido y halagado por la queja de Esclavitud. Cuando tan á lo vivo la llegaran su secura y despego, era que la muchacha no le tenía por chiquillo, ó como ella decía, por rapaz. ¿Se apura ni se formaliza nadie por lo que dice ó hace un niño? Indudablemente le juzgaba todo un hombre, y hombre de cuyas acciones dependía el estado de su espíritu: tan á pecho las tomaba, que se resentían de ellas su humor y hasta su salud. En este pensamiento se deleitó Rogelio largo rato. Con todo, durante el almuerzo, á pesar de dos ó tres señas de su madre, no cambió de actitud respecto á la doncella. Sin saber por qué, le causaba empacho realizar la mutación delante de doña Aurora. Lo que hizo fué observar á hurtadillas á Esclavitud, la cual--sin duda por efecto de la excitación de su fantasía--le pareció muy demacrada, muy descolorida y más lánguida que un sauce. Al convencerse de esto, su noble alma juvenil se inundó de piedad; pero su orgullo, juvenil también, se estremeció dulcemente. «Pues por mí está de ese modo. Casi parece que me tiene miedo, según la precaución respetuosa con que me sirve...»\"},{\"heading\":false,\"text\":\"Acababa de retirarse á su aposento el estudiante para lavarse las manos, cuando tocaron ligeramente á la puerta, y á la voz de «pasen» entró Esclavitud, llevando en una batea de mimbres hasta media docena de camisas planchadas. Por efecto de la carga, que la obligaba á levantar los brazos, la muchacha lucía su fino talle y su andar compasado y armonioso. Iba á dejar sobre la cama las camisas y retirarse silenciosamente, á tiempo que Rogelio, llegándose á ella y amenazándola con la mano, exclamó:\"},{\"heading\":false,\"text\":\"--Vamos á ver como están de planchaditos esos puños. ¡Si les encuentro un solo candil!\"},{\"heading\":false,\"text\":\"Al oir la voz del señorito, Esclavitud se había sobresaltado, figurándose en el primer instante que la regañaban de veras; pero al levantar los ojos y fijarlos en la cara de Rogelio, comprendió que se trataba de una broma. Radió en su mirada tan sincera alegría; se dilató tan visiblemente su pecho; se esponjó de tal modo, en fin, que las excelentes entrañas del estudiante se conmovieron otra vez gratamente, y para disimular aquella emoción recargó la broma.\"},{\"heading\":false,\"text\":\"--¿Es justo que ande yo hecho un cesante, y que mis camisas parezcan la cara del apreciable señor Don Prudencio Rojas, alias _Fantoche del Derecho_? A ver: alce V. ese níveo cendal y enséñeme esas íntimas prendas de vestir. Si mis togas pretextas descubren las rayas de la senectud..., huya V. adonde no la alcance mi cólera vengadora.\"},{\"heading\":false,\"text\":\"En el rostro de Esclavitud, cada vez más regocijado, brillaba, al levantar el paño, cierta cariñosa malicia.\"},{\"heading\":false,\"text\":\"--A ver, señorito, á ver qué chata tiene que ponerles á estas pecheras. Ni el Rey las gasta más ricas.\"},{\"heading\":false,\"text\":\"--El Rey lo que gasta son baberos: no confundamos. ¡Enséñeme ese prodigio!\"},{\"heading\":false,\"text\":\"En efecto, estaban primorosamente planchadas, tan bruñidas y tersas, que fuera gollería pedir más.\"},{\"heading\":false,\"text\":\"--Bien; por esta vez le perdono á V. la vida. ¡Pero guay si acierta V. á descuidarse en el cumplimiento de tan sagrado deber!\"},{\"heading\":false,\"text\":\"--No señor, no señor. Vendrán cada día más blancas. Lo mismo que palomas.\"},{\"heading\":false,\"text\":\"--Dígnese V. decírmelo en gallego. Voy á dedicarme al estudio de ese idioma, porque en el griego y en el sanscrito ya estoy tan fuerte que les echo la pata á los profesores. ¿Cómo se dice _paloma_ en gallego?\"},{\"heading\":false,\"text\":\"--¿Y es de allá y no lo sabe? ¡Vaya qué ser! Se dice _pomba_ y también se dice _suriña_.\"},{\"heading\":false,\"text\":\"--¡Ay! ¡Eso de _suriña_, qué bonito es! Desde mañana lección de idiomas clásicos: V. será mi maestra. «Mademoiselle Suriña, profesora á domicilio». Pondremos un cartelito en el balcón y un anuncio en _El Imparcial_. Suriña, quite V. de ahí las camisas, que estorban. Guárdelas V. en el armario. ¡Eso!\"},{\"heading\":false,\"text\":\"--¡Ay, señorito, qué revuelto tiene el armario!--exclamó la muchacha apenas lo abrió.\"},{\"heading\":false,\"text\":\"--Pues á arreglarlo, Suriña. El arreglo de armarios forma parte de la lección de idiomas.\"}]},{\"title\":\"Morriña — capítulo X\",\"blocks\":[{\"heading\":false,\"text\":\"Ello sería... ó no sería; pero no se puede negar que, después de firmadas las paces con Rogelio, el aspecto exterior de Esclavitud empezó á modificarse completamente. Sus ojos se reanimaron, sus mejillas florecieron, su voz perdió aquel tono dolorido, su conversación fué más expansiva; y sin alterar en nada sus ocupaciones, varió tanto su manera de desempeñarlas, que si antes parecía víctima resignada del deber, y su silueta tenía algo de aflictivo al proyectarse sobre las paredes de la casa, ahora su ir y venir, su resuelta actividad, la llenaban y regocijaban toda.\"},{\"heading\":false,\"text\":\"Doña Aurora no cesaba de felicitarse por este cambio. «¡Alabado sea Dios! Así me gustan á mí las caras, así. No puedo tragar á la gente que anda tristota y rostrituerta sin por qué ni para qué. ¿Lo ves, rapaz? Pues era por causa tuya, ni más ni menos. Ahora que la tratas campechanamente, mira cómo es otra.»\"},{\"heading\":false,\"text\":\"Y tanto como era otra. Hasta su físico había sufrido halagüeña metamorfosis. En señal de contento ó por otra causa que ignoramos, habíase quitado el pañuelo negro de la cabeza, dejándolo caer negligentemente sobre el cuello, cuya blancura extraordinaria realzaba el contraste con la negra seda. Su cutis era ahora el cutis de las gallegas jóvenes, una tez fresca que parece conservar el brillo de la humedad del suelo nativo, y afrenta, con las nacaradas tintas de las mejillas, la enfermiza palidez de las hijas de Madrid. Sus interesantes ojos verdes, con reflejos amarillentos, acentuaban el carácter primaveral y tierno de la hermosura de Esclavitud, asemejando su faz á un valle regado por dos cristalinos arroyos. Pero el adorno que verdaderamente agraciaba á la muchacha era su cabellera rubia, de un rubio algo tostado, con reflejos de oro que rielaban en lo más saliente de las simétricas ondulaciones ó conchas que fluían á uno y otro lado de la raya, como orla magnífica de la estrecha frente y la delicada sien. La rica mata colgaba partida en dos trenzas, ó se retorcía en rodete copioso; y si por la mañana aparecía lisa y hasta charolada por la mucha agua, único afeite de tocador que usaba Esclavitud, al ir corriendo el día y el trajín doméstico, se rebelaba, y fosca y suave á la vez, formaba al rostro un nimbo, parecido al de las santas de los retablos viejos. Y es que el tipo de Esclavitud, con aquel peinado sencillo y aldeano, recordaba las creaciones de la iconografía mística, ya en las tablas flamencas, ya en las primitivas pinturas italianas, á lo cual contribuía su aire modesto, sus ojos bajos, aquel olor á incienso y á sacristía que notaba Rita Pardo en ella. Cuando miraba de frente, sonriendo, se notaba la fisonomía de la campesina bajo el anguloso diseño de la virgen.\"},{\"heading\":false,\"text\":\"Todas estas perfecciones y gracias, con otras más cuyo inventario suprimo, las avizoró al través de sus espejuelos, y las reconoció y comentó y puso en las nubes el discreto ochentón á quien Rogelio llamaba _Nuño Rasura_, y nosotros con más respeto nombramos Don Gaspar. Ni aguardó para entonar el panegírico á que se verificase la transformación de la muchacha, sino que desde el primer día que ésta le abrió la puerta, empezó el gallardo viejo á babarse y amartelarse, dando jaqueca á los contertulios con sus elogios inmoderados, sus involuntarios madrigales, sus niñerías, y, para decirlo en frase del Fiscal, «sus golpes de archimemo».\"},{\"heading\":false,\"text\":\"--Vea V., vea V.--repetía el señor de Febrero levantando la hermosa testa orleánica, atusándose delicadamente los rizos de la peluca ó sobando el cojín de terciopelo de su muleta,--qué buen tino ha demostrado mi excelente amiguita doña Aurora, al elegir esta sirviente única dentro de su clase. En primer lugar, tan útil, tan precavida, tan laboriosa como parece. En segundo, con ese aire de honestidad y de recato. ¡Ah! Para mí, mérito grandísimo, ahora que se han perdido los buenos modales, y en la sociedad pululan las sargentonas y los marimachos. Allá en otros tiempos ¿se acuerda el amigo Candás? eran todas así: nada de estos descaros de hoy día.\"},{\"heading\":false,\"text\":\"--Sí, sí; por fuera mucho compás...--respondía el empecatado Don Nicanor, requiriendo la trompetilla.--Unas santinas de alfeñique. Y por dentro..., vamos, que ya se desquitaban. ¡Carapuche si se desquitaban! Como ya se me cayeron los segundos dientes..., no me fío de carinas de Virgen.\"},{\"heading\":false,\"text\":\"--¡Ay, que el amigo Candás se nos va por los cerros de la malicia! Eso sera allá en Asturias, en su tierra de V. Por la nuestra, no: ¿verdad, doña Aurora? Y confesémoslo, señores: en la mujer, así como el descoco y la tunantería repelen, este modo tan decente de presentarse, este aire tan modesto, abren más el apetito.\"},{\"heading\":false,\"text\":\"Aquí la señora de Pardiñas estuvo á punto de soltar el trapo á reir, porque Rogelio, desde su rincón, oyendo hablar de apetito, hizo una morisqueta y un guiño de pilluelo para subrayar aquellas lozanías del decano.\"},{\"heading\":false,\"text\":\"A los pocos días, la benévola admiración del señor de Febrero se convirtió en desatada curiosidad, comezón invencible de saber todo lo concerniente á «nuestra paisanita».\"},{\"heading\":false,\"text\":\"--¿De dónde la ha sacado V., vamos á ver?--preguntaba á la señora de Pardiñas, más con el centellear de los entornados y expresivos ojos tras los vidrios de los espejuelos, que con la voz.\"},{\"heading\":false,\"text\":\"--Me la recomendaron las de Romera, á quien V. debe de conocer.\"},{\"heading\":false,\"text\":\"--¡Aaaaah! ¡Mucho, mucho! ¡Romera, Romera! Sí, Romera.--Y ajustó los vidrios sobre la correctísima nariz.--Pero las amiguitas Romera--prosiguió con la insistencia del juez que abre una información y la machaquería del viejo que quiere enterarse--¿la han traído de Galicia? Porque, si no me engaño, no estuvieron allá nunca. ¿La familia de esta chica es gallega?\"},{\"heading\":false,\"text\":\"--Gallega, sí, señor--afirmó evasivamente doña Aurora.\"},{\"heading\":false,\"text\":\"--Será una familia decentita, ¿eh?--prosiguió el impertérrito _Nuño Rasura_.--Porque á eso me huele..., y yo tengo de aquí--añadió señalando á aquella escultural facción de su cara.--Ella, hablar, habla bien: sólo algún modismo... El aire es fino, adamado. ¿Conque familia decente?\"},{\"heading\":false,\"text\":\"--Decente, sí tal--tuvo que responder la señora, de dientes afuera.\"},{\"heading\":false,\"text\":\"--¿Pero artesanos? ¿Propietarios? ¿Empleaditos?\"},{\"heading\":false,\"text\":\"--No señor... Sobrina... (la voz de doña Aurora se atascó unas miajas) de un cura de aldea.\"},{\"heading\":false,\"text\":\"--¡Toma, toma, toma!...--articuló el decano enfáticamente.--¡Ya decía yo! ¡Sobrinita de un sacerdote! _Boccato di cardinale_: son unas muchachas muy religiosas, divinamente criadas... y de un orden á toda prueba. ¡Toma, toma!\"},{\"heading\":false,\"text\":\"La señora intentó echar la conversación por otro lado; pero nada es comparable al antojo de un niño, sino el capricho de un viejo. Don Gaspar acariciaba su muleta dándole vueltas, y al fin, sin poder reprimirse, indicó:\"},{\"heading\":false,\"text\":\"--¿Sabe V., amiguita Aurora, que, si así puede decirse, no le he visto bien la cara á esa muchacha? La antesala está un poco obscura. Y tengo curiosidad de convencerme de si en efecto se parece á una señorita de Vivero, preciosa por más señas, á quien le llamábamos los muchachos la Magdalenita..., allá el año de 34 ó 35. Si V. la mandase traer un vaso de agua... ó cosa así... con disimulo.\"},{\"heading\":false,\"text\":\"El guiño malicioso que trocaban madre é hijo fué interceptado al vuelo por Laín Calvo, quien exclamó haciendo cómicos aspavientos y renunciando momentáneamente al ejercicio de la sordera:\"},{\"heading\":false,\"text\":\"--¡Caray, doña Aurorina del alma! No llame á esa ninfa, no, que será V. responsable de la pérdida del amigo señor Febrero. En la edad de Don Gaspar, las pasiones hacen estragos, Prudencia, Don Gasparín, mire que hay cielo. ¿Refregarles por los hocicos las niñas bonitas á los calaveras? Es un pecado, home.\"},{\"heading\":false,\"text\":\"Cuando entró Esclavitud llamada con un pretexto cualquiera, nadie podía contener la risa, lo cual azoró un tanto á la muchacha, que no sabiendo de qué se trataba allí, se puso muy sofocada y por consiguiente más linda, con aquel encanto especial suyo, que procedía de un aire casto y humilde, bajo el cual se traslucía una firmeza rayando en apasionada obstinación. El señor de Febrero se la comía con los ojos. ¡Viejecito más chiflado! Tan pronto como Esclavitud pudo escurrirse, Laín Calvo secreteó á la señora de Pardiñas:\"},{\"heading\":false,\"text\":\"--Ay, ay...: la niñina será un tesoro..., pero á mí...--y se tocaba la nuez--aquí se me pone y de aquí no me pasa. Estas que todas se arrebatan cuando las mira uno, me escaman muchísimo. ¡Doña Aurora, ojo..., cuidado!\"},{\"heading\":false,\"text\":\"--No sé de dónde saca V. eso, señor de Candás--protestó la señora con enojo, herida en su gran simpatía por la muchacha.\"},{\"heading\":false,\"text\":\"--Estas así, que parece que no rompen un plato, son de la misma rabadilla de Lucifer--alegó el maligno asturiano.--Venden modestia, y dan terquedad; venden inocencia, y dan más truchimanería que el que la inventó. No se fíe, amiguina. Estas son de aquellas que dicen: «¡Ay Jesús! No me pidas el brazo que me escandalizo. Pero si te lo tomas... ¿cómo ha de ser? tendremos paciencia.»\"},{\"heading\":false,\"text\":\"--Señor Candás, hay ciertas indicaciones que se pueden calificar de viperinas--protestó frenético Nuño Rasura, pegando con la muleta en el suelo.--Cuando está en juego la honra del sexo hermoso, toda cautela es poca, y conviene ver por dónde se anda y lo que se dice y á quién se toma en boca, señores.\"},{\"heading\":false,\"text\":\"--Ya, ya--replicó el Fiscal, agarrándose á la sordera.--Ya entiendo que á V. también le dan en qué pensar estos tipos así. No en balde hemos vivido añitos, y se nos ha caído la segunda dentición y los pelos de la cabeza. Doña Aurora: diga, y ¿por qué vino á dar aquí esta princesa errante? ¿Algún Eneas de allá que la plantó? Huéleme á historia.\"},{\"heading\":false,\"text\":\"--No señor--declaró la señora de Pardiñas.--No se eche V. á pensar mal, que no acertará. Por muerte de... de su tío, tuvo que ponerse á servir...\"},{\"heading\":false,\"text\":\"--¿Desde cuándo?\"},{\"heading\":false,\"text\":\"--Pues hará medio año... poco más ó menos.\"},{\"heading\":false,\"text\":\"--¿Y ya ha corrido dos casas? ¡Malorum... malorum!\"},{\"heading\":false,\"text\":\"--¡Qué malorum! Nada de eso. La yerra V., Don Nicanor. Le entró á la infeliz una especie de nostalgia, de esa que suele atacarnos á los gallegos cuando salimos por primera vez de nuestra tierra..., y, al menos, quiso servir con gente de allá. Como Vds. los asturianos son unos descastados, no comprenden esto. Pregúntele V. á las de Romera si tienen queja de la muchacha; que de allí se vino para esta casa muy de Vds.\"},{\"heading\":false,\"text\":\"--¡Uy, uy! ¿eh? ¡Con que nostalgia! Romanticismos y dengues, ¡carapuche! Ahora sí que digo yo que á esta princesina la tendrá V. que llevar tila para los nervios todas las mañanas. No se le ocurre ni al diaño. En estando bien comida y bien tratada, no sé qué caray le importaba la nacionalidad de los amos con quien servía, home.\"},{\"heading\":false,\"text\":\"--Está V. equivocado--contestó airadamente el señor de Febrero.--Esta enfermedad, que se conoce por _morriña_ ó mal del país, es terrible en mis paisanos, señor de Candás, y alguno conocí á quien le llevó á la hoya. No se ría V., que esto lo saben allá hasta los gatos; y si V. no lo sabe, apréndalo. A veces, con evocar un recuerdo del país, se cura. ¿Ignora V. lo que ocurrió con el quinto, enfermo en el Hospital de la Habana? Pues estaba el pobre hombre á punto de liárselas, y ¿con qué dirá V. que sanó, pero en seguidita? Pues con tocarle la muiñeira en la gaita de su país. Así, así; con la muiñeira.\"},{\"heading\":false,\"text\":\"--Home..., no fastidie, por el Santísimo Cristo se lo imploro. Estaría ese quinto más borracho que un templo. Jumera pura. Ya le curaría yo con solfa de varas de avellano.\"},{\"heading\":false,\"text\":\"--Mi Don Nicanor, con V. no se puede. Niega V. lo que los demás hemos visto... Más vale hacerse como V., el sordo. Doña Aurora, si la paisanita esa no le conviene á V..., yo, por una servidora así...\"},{\"heading\":false,\"text\":\"--¡Aquí de Dios! Que este home quiere robar á la bella Elena que V. ha descubierto. Atentado contra la moral pública. Diga que no, doña Aurora; mire que es cosa grave.\"},{\"heading\":false,\"text\":\"--Ya se ve que diré que no. Por la cuenta que me tiene. Estoy muy bien servida con Esclavitud para deshacerme de ella.\"},{\"heading\":false,\"text\":\"Rogelio había oído en silencio la discusión de Nuño Rasura y Laín Calvo. El se inclinaba hacia las indulgentes apreciaciones de su madre y del ex-presidente de sala: con todo, á veces le entraban impulsos de creer que el maldito asturiano calaba más y conocía mejor la vida. Por una ilusión frecuente en los que carecen de experiencia, la malignidad y el pesimismo le parecían la última palabra del saber humano. Aquella disposición suya á pensar bien, debía, en su concepto, originarse de lo poco que había vivido. «A mí cualquiera me mete el dedo en la boca»--deducía.--«Soy un chiquillo, y no me da la gana de seguir siéndolo.»\"}]},{\"title\":\"Morriña — capítulo XI\",\"blocks\":[{\"heading\":false,\"text\":\"Cruzaba Esclavitud el pasillo, y oyó la voz de su señorito llamándola.\"},{\"heading\":false,\"text\":\"--¡Esclavita!\"},{\"heading\":false,\"text\":\"--Voy.\"},{\"heading\":false,\"text\":\"--Acude pronto... Tu intervención habrá de resolver un pavoroso conflicto.\"},{\"heading\":false,\"text\":\"La muchacha entró, y vió al estudiante de pié, en mangas de camisa, con el chaleco en una mano, y la otra muy apretada, lo mismo que si encerrase en ella algún tesoro.\"},{\"heading\":false,\"text\":\"--Ahora mismo, con la velocidad del rayo, acaba de saltarse de mi cuello este botón de precioso nácar... ¿Puedes adherirlo otra vez á su base sin atravesar mi garganta con el frío acero?\"},{\"heading\":false,\"text\":\"Sonrió Esclavitud, y registrándose el bolsillo, sacó alfiletero, carrete, dedal: este último era perforado por arriba y abajo, como los de las aldeanas. Se lo calzó rápidamente, y con igual presteza enhebró la aguja, dió el nudo, y cogió entre el pulgar y el índice la rodajilla de nácar. Arrancó el hilo que colgaba señalando el lugar del desperfecto; aplicó el botón, é introdujo la aguja... Aquí dieron principio las dificultades de la empresa. No era posible sacar la aguja airosamente, sin pincharle al señorito la barba, todavía rasa y monda cual la de una mujer. El fingía ayudar, y torcía la geta con mil festivos remangos y mucho de «¡ay! ¡socorro..., que me parten la carótida..., que me atraviesan la yugular..., que me practican la arriesgada operación de la traqueotomía sin tener garrotillo!» y la muchacha, risueña, pero sin perder el aplomo, sólo decía:--«Aparte un poco..., cuidadito ahora..., vuélvase..., pronto acabo...» Por fin, con ademán triunfante, dió alrededor del botón un sinnúmero de vueltas con el hilo, formando el pié; remató...\"},{\"heading\":false,\"text\":\"--¡Hurra! Victoria. Abróchamelo.\"},{\"heading\":false,\"text\":\"Los deditos menudos, picados de la aguja, recorrieron la garganta del estudiante, el cual despidió nuevos chillidos.\"},{\"heading\":false,\"text\":\"--¡Ay, ay, ay... Que me pelliiizcan!\"},{\"heading\":false,\"text\":\"Pero apenas estuvo abrochado el botón, murmuró como el que ruega para obtener una cosa muy importante y ardua:\"},{\"heading\":false,\"text\":\"--Esclava... Dígnate ceñir á mi cuello este dogal.\"},{\"heading\":false,\"text\":\"La muchacha tomó la chalina de seda, y al rodearla al cuello del señorito, se tropezaron las miradas de los dos. Mientras duraban las otras operaciones no había sucedido semejante cosa, porque Rogelio volvía la cabeza todo cuanto se lo permitían los accesos de risa que le entraban: ahora sí tenía que suceder, pues Esclavitud levantaba el rostro, y Rogelio, más alto, veía por fuerza, tan cerca que le mareaban, las dos pupilas verdes sembradas de puntitos de oro, y la raya del pelo, derecha, angosta y limpia, como surco que parte un campo de madura mies, y la cóncava frente, tersa y suave, y las venitas azules de las sienes y párpados. El aliento puro de la muchacha subía hasta la boca del estudiante, causándole un principio de embriaguez, como si hubiesen destapado una botella de oxígeno.\"},{\"heading\":false,\"text\":\"Fué asunto de un instante, pero instante en que por la intensidad de la sensación, Rogelio creyó vivir un año. La infancia, con su ligereza de mariposa, sus vagos horizontes de plata y azul, se quedó atrás; y la golosa juventud, la de insaciables labios, surgió tendiéndolos con afán á la copa eterna. La sangre de Rogelio, hasta entonces lenta, enfriada por la clorosis, saltó en las venas con impetuoso hervor, y refluyendo al corazón de golpe, volvió á derramarse encendida por el organismo. Un velo rojo, el que nubla las pupilas del criminal en el momento decisivo, cubrió también los ojos del estudiante, mientras le asaltaba la tentación brutal y furiosa de cerrar los brazos, comerse á besos la linda cabeza y deshacer á achuchones el cuerpo... La misma violencia del deseo paralizó su acción, y como Esclavitud había terminado el arreglo de la corbata, cuando Rogelio iba á ceder á la sugestión culpable, la muchacha se desviaba ya, colocándose á distancia conveniente para juzgar del efecto del lazo.\"},{\"heading\":false,\"text\":\"Fué como si se interrumpiese la comunicación del alambre con la pila. Rogelio volvió en sí, tan sobrecogido de terror considerando lo que había estado á punto de hacer, que sintió enfriársele las manos. «¡Qué atrocidad, Dios mío!... ¡qué disgustazo para mi madre!»\"},{\"heading\":false,\"text\":\"La noción moral, que á otros se les inculca como necesidad racional y deber ineludible, ó como religioso precepto, habíala recibido Rogelio por el conducto del sentimiento, en su educación faldera y mimosa de hijo único. Todas las ideas de decoro, de bondad, de rectitud, le llegaban por ese camino indirecto, pero dulce. «¡Ay, qué pena tendría yo, rapaz, si tú hicieses tal ó cual cosa! ¡Jesús, qué bochorno para mí si cayeses en esta ó en aquella falta!» Así es que, sin darse cuenta de ello, lo primero que Rogelio veía en sus actos era el efecto que podían producir en el corazón de su madre; y ésta fué también su primer idea, al disiparse el vértigo que le obscureciera la razón mientras tuvo tan cerca á la muchacha. Cuando Esclavitud hubo salido del aposento, el mismo recelo fué base de una honradísima resolución, la de evitar nuevas ocasiones y peligros más inminentes todavía. Tales propósitos son difíciles de sostener cuando se tiene el peligro en casa. A cada momento Rogelio sentía renacer su antojo primerizo, y como bocanadas de aire caliente, subírsele al cerebro los mismos vapores. En la mesa; al encontrar á Esclavitud en el pasillo; cuando le traía á su cuarto luz, recados ó ropa, no podía menos de devorarla con los ojos, detallando la perfección de su talle gentil, el misterio de su cerrado y honesto corpiño, la gracia de su ligero andar. Cuanto mayor y más vivo era su anhelo, más atado se sentía en presencia de la muchacha. Delante de ella le parecía imposible resolverse nunca á decirle nada que tuviese color de requiebro formal; y en cambio, de noche, á solas, desvelado, dando vueltas en la estrecha camita, juzgaba fáciles todas las empresas y razonables todos los despropósitos, y hasta--¡extraña forma del capricho apasionado!--creía tener una obligación, una especie de deber estricto de realizar lo que por el día consideraba un atentado y un acto de locura. «Después sí,--pensaba,--que nadie podrá llamarme chiquillo; y yo mismo me convenceré plenamente de que no lo soy.» Esta disparatada idea se desvanecía por la mañana, al traerle su madre el chocolate según vieja y afectuosa costumbre. Al ver entrar á doña Aurora con su bata de tartán y la bandeja en las manos; al saborear el primer bizcocho, el chico mimado sentía todo el influjo de la ley moral imponiéndose con fuerza apodíctica, y los principios desconocidos ó negados minutos antes, se le presentaban claros, demostrativos, evidentes. «Darle una pesadumbre á mamá, allá por fuera de casa, ya sería terrible, ya se me ponen los pelos de punta con solo imaginarlo... Pero, en fin, siempre resultaría más disculpable y más llevadero. Aquí mismo..., vaya..., es cosa inaudita. Aunque ella no lo pescase, á mí se me figuraría que me lo estaba leyendo en los ojos y hasta en el modo de respirar. Y lo pescaría, lo pescaría; ¿pues quién lo duda? Es muy pilla mamá, así con esas tracitas de bonachona. El dedo en la boca no se lo mete nadie. Me conoce tan bien, que aún no he acabado yo de decir las cosas y ya las ha guipado ella. Como que no le importa ni se ocupa de nada sino de mí. Dios quiera que no tenga escama ya...»\"},{\"heading\":false,\"text\":\"Así, aquel culpable de pensamiento estudiaba con atención el rostro de doña Aurora, temeroso de que alguna de sus miradas á Esclavitud le delatase. A veces se comprometía por dar en el extremo opuesto, afectando no mirar á la muchacha, evitando hasta el roce de su manga cuando le servía á la mesa. Verdad que este mero roce le sacaba de quicio, llegando á causarle una impresión dolorosa por lo intensa. Era el suyo deseo exaltado de la primera edad, que no sabe aún ni reprimirse ni abrirse camino hasta su objeto. Después de dos ó tres días de huir de la Esclavitud, ideaba un pretexto para ir á sorprenderla en el cuchitril donde planchaba y tenía las cestas del repaso; y una vez allí, no se le ocurría más que sentarse en una silleta, y engañar su violento capricho contemplando á la chica que, encendida y sudorosa, encorvado el brazo derecho en arco rígido, hincaba con esfuerzo la plancha en las pecheras ó los puños de las camisas. Cuando el ímpetu de abrazarla le acudía muy fuerte, Rogelio se levantaba y refugiábase en su despachito. Allí estaban, sobre el barnizado escritorio, los antipáticos libros de texto, impresos en papel de estraza, con tipos gastados y turbios, y despidiendo de sus mustias hojas y de su parda cubierta toda la secura de la aridez, todo el humo del hastío. Nunca le habían caído en gracia á Rogelio los tales librotes; pero ahora... Apenas intentaba abrirlos para repasar una conferencia, una niebla de aburrimiento pertinaz se le subía á la cabeza, y una especie de disolución moral se verificaba en su espíritu, en el cual cierta voz rebelde murmuraba vagamente herejías así: «Anda, hijo, déjate de pamplinas, reniega de esa ciencia oficial, manida, huera, sin jugo. La realidad y la vida son otra cosa. Eso con que pretenden alimentarte es un conjunto de vejeces, la cáscara de un limón exprimido ya por la mano diez y nueve veces secular de la Historia. Ha caducado cuanto estudias. Te quieren llenar el cerebro de restos momificados, de trapos polvorientos y de antiguas telarañas. Te quieren meter en la cabeza la vieja balumba jurídica, y que de un salto te encuentres en la edad de tus tertulianos, Laín Calvo, Nuño Rasura y el honrado _Fantoche_. Quieren que seas de palo como él. No, eres de carne y hueso; eres hombre; la vida te llama, y la vida á tu edad, á falta de un estudio que desarrolle la armonía de tus facultades, es... Esclavitud».\"},{\"heading\":false,\"text\":\"A estas indeterminadas reflexiones aquí traducidas en lenguaje claro y vulgar, el estudiante asentía bostezando, levantándose nerviosamente de la silla, cogiendo del estantito una novela ó el último número del _Madrid Cómico_, tumbándose sobre la cama, y tratando de distraer con una lectura hambrienta sus febriles ansias.\"},{\"heading\":false,\"text\":\"No tenía el recurso del cigarro, porque pertenecía á esta generación reciente que no fuma, y que llegará, si Dios no lo remedia, á desmayarse con el olor del habano, ni más ni menos que las damas británicas. Faltábale ese gran engañador de la impaciencia, ese gran consejero en las horas malas, ese poderoso sedante, esa distracción la más espiritual de cuantas puede ofrecer la materia. Un día pensó en ella mucho. «¿Qué me sucedería si fumase? Por de pronto, marearme. Quién sabe si echar los bofes... de fijo que sí. Luego, mamá conocería por el olor... No, peor es el remedio que la enfermedad.»\"},{\"heading\":false,\"text\":\"Esta idea del cigarro, que le halagaba porque tenía algo de calaverada varonil, trajo como de la mano otro expediente más fecundo en resultados y hasta de realización gratísima y fácil. ¡No habérsele ocurrido antes, cuando era tan sencillo, tan sencillo, y hasta tan natural y justo, y sobre todo tan útil para alivio del malestar presente! «Pues si lo raro es que yo no tenga ya una novia, señor. La tiene cada quisque: Benito Díaz, una preciosa; Cardona otra por quien bebe los vientos... Siempre me están diciendo que á qué aguardo para echarme la mía correspondiente. Pues les sobra razón. Así se me quitarán estas chifladuras y estos alborotos. Tomaremos novia, sí señor que la tomaremos. El tener novia no es cosa mala, ni aunque mamá lo averigüe se va por eso á disgustar. Un clavo saca otro clavo. Será la gran distracción...»\"},{\"heading\":false,\"text\":\"Creada ya la plaza, faltaba saber en quién recaería la provisión del empleo. Rogelio pasó revista con la memoria á todas las señoritas conocidas suyas. Unas eran feas, otras tenían ya su arreglito; ésta frisaba en los treinta; aquélla no salía de casa jamás; unas se burlarían de él; otras le pedirían cosas muy difíciles en prueba de cariño... Recordó que por una callejuela que desembocaba en la Ancha de San Bernardo, vivían frente á su casa tres ó cuatro chicas, descendencia de un empleado en el Ministerio de Ultramar. No eran malejas, en especial la menor, una rubita pálida que, cara, pelo y ojos, todo lo tenía de un color mismo, lo cual la favorecía, dándole cierto parecido con la infanta Eulalia. Rogelio la miraba á veces, recibiendo pago puntual de todas sus ojeadas sin que le quedasen debiendo ni una sola. «La rubita me conviene....», pensó el estudiante. «Ni necesito moverme del comedor...» En efecto: el mismo día que lo discurrió, á la hora del almuerzo, apostóse detrás de los cristales, con las vidrieras á cuchillo, y miró hacia los balcones del tercer piso de enfrente. Allí estaba la rubia, vistiendo una mañanita de percal de lunares, toda sucia y ajada; sobre la barandilla del balcón flotaban varias prendas de ropa íntima, en más que mediano uso, puestas á secar, y encima de una cómoda se veían frascos cubiertos de polvo, la jaula vacía de un jilguero, trapos, una bota inservible.--Al fijarse en aquel interior nada holandés, el plan de tomar novia que viviese allí se le frustró á Rogelio. Permaneció apabullado diez minutos. «Buscaremos por otra parte. Lo que es sin novia no me quedo yo; sólo faltaba...»\"}]},{\"title\":\"Morriña — capítulo XII\",\"blocks\":[{\"heading\":false,\"text\":\"La mañana de un domingo despertó á su hijo la señora de Pardiñas con la intimación siguiente: «Hoy haremos visitas. No hay más remedio: estamos en descubierto con todo el mundo. Es un escándalo. Ya he pedido el landó al taller de Agustín: dice que á las dos en punto lo tendremos á la puerta. ¡Ah!... ¿No sabes? Voy á ir, que si me miro al espejo, no me conozco. La modista me trajo ayer el vestido de terciopelo negro arreglado con pasamanería de azabache y puntillas; el sombrero igual está listo. Con que tocan á sacar el fondo del baúl. Te pasarás por la peluquería antes de almorzar: tienes el pelito muy largo».\"},{\"heading\":false,\"text\":\"Rogelio gruñó bastante, alegó dos ó tres ocupaciones indispensables aquel día, pero todo en broma, porque bien veía á la señora de Pardiñas resuelta á no acostarse sin haber ofrecido un gran holocausto en el altar de la sociedad. A los dos menos cuarto, Rogelio estaba acabando de abrocharse la primer fila de botones de su levita inglesa, delante del armario de espejo. Por fortuna era domingo, y, en tal día, frente á la Universidad es donde se puede estar seguro de no encontrar un estudiante para un remedio; que si no, menuda sofoquina le esperaba cuando los compañeros le viesen con aquel empaque, vestido de _caballero_, con guantes y chisterómetro. Acostumbrado á la pañosa y al hongo, le parecía en los primeros momentos, que ir de levita era así cómo salir de máscara. Allí estaba la chistera, reluciente, flamante, sobre la mesa del despacho, y los guantes también, y el junquillo, y el tarjetero de piel de Rusia, y el pañuelo con rica inicial bordada. De todos estos objetos se hizo cargo; ladeó el sombrero al colocarlo sobre la bien aliñada cabeza, y empezaba á calzarse los guantes, con el mal humor inherente á esta operación siempre enfadosa, cuando su madre entró.\"},{\"heading\":false,\"text\":\"--¡Jesús, máter admirábilis! Vienes hecha un brazo de mar. ¡Ole por las buenas mozas, las mujeres principales y el trapío!\"},{\"heading\":false,\"text\":\"Lo que venía doña Aurora era muy atarugada con las galas que sólo en ocasiones solemnísimas se determinaba á lucir. Que no la quitasen á ella de su mantito arrebujado, de su traje de merino y de su gran abrigo de pieles. Tanto embeleco era para condenarse. El peso del sombrero, con sus lazos empingorotados, la obligaba á bajar la cabeza; los aceros de la falda la ataban los muslos; en fin, ello no había más camino que someterse á semejantes impertinencias, por lo menos dos veces al año. Llevaba tarjetero, como su hijo, y además una lista de las casas donde se creía obligada á ir. También lucía, asomando por el manguito de marta, un hermoso pañuelo de encaje, perfumado con no sé qué extracto fino, y en las orejas dos buenos solitarios; el lujo modesto de una señora que no pretende sino guardar el decoro de su clase. Y, sin embargo, tal es el poder de la composición y del adorno en la mujer, que doña Aurora, con sus cincuenta y pico, parecía haberse dejado diez en la puerta del cuarto tocador, ostentando en la tez una animación agradable, y en el andar cierta majestad insólita.\"},{\"heading\":false,\"text\":\"Esclavitud venía detrás, trayendo un abrigo, que por si acaso enfriaba la tarde iría en el coche; y mostrando esa admiración solícita de los criados adictos en los días de gala con uniforme para sus amos, se puso á arreglarla el _polisón_ y las aldetas del corpiño, y á sacudir imperceptibles motas de polvo en la parte inferior del volante. De pronto alzó los ojos, y exclamó cándidamente mirando á Rogelio:\"},{\"heading\":false,\"text\":\"--Virgen de las Ermitas... ¡El señorito qué majo!\"},{\"heading\":false,\"text\":\"--¿Verdad que está hecho un figurín? Rogeliño, vuélvete, vuélvete..., así. La levita te la han sacado pintada.\"},{\"heading\":false,\"text\":\"--¡Mamá!...--protestó Rogelio. Pero fué preciso dejarse mirar y remirar por Esclavitud, y aun consentir una mano de cepilladura en el cuello de la levita. Las pupilas de la muchacha le decían con inocente lenguaje que estaba _bien_. Le arregló los puños, y cuando bajaba la escalera todavía le gritó:\"},{\"heading\":false,\"text\":\"--¡Qué lástima! Lleva en la pierna derecha un poco de pelusa de la alfombra.\"},{\"heading\":false,\"text\":\"La primer visita fué á casa de Don Gaspar Febrero, porque la hija del respetable decano, casada con un comandante de Estado Mayor, se marcharía pronto á Filipinas, en compañía de su marido, destinado á Manila. Se habló de la navegación, del clima, de los baguíos, de la carestía de la vida allá, y del señor mayor que se quedaba solo aquí. Por fortuna, nunca había estado más tieso, más animoso, ni más rufo: aun ahora mismo acababa de salir á pié, agarradito á su muleta, ávido de tomar sol. Con estas buenas nuevas se despidieron de la morada de Nuño Rasura y pasaron á hacer otras visitas casi todas análogas, algunas de tarjetazo, las más agradables para Rogelio, que al acercarse á cada portal repetía entre dientes la consabida jaculatoria:\"},{\"heading\":false,\"text\":\"--Animas benditas, ¡que no estén en casa las visitas!\"},{\"heading\":false,\"text\":\"Pero ¡ay! Pegó el gran respingo al anunciarle su madre que ahora irían «un minuto» á casa de las señoritas de Romera, Pascuala y Mercedes.\"},{\"heading\":false,\"text\":\"--Madre mía, si es posible, pase de mí ese cáliz. Pero, ¡carapuche! como dice el sordo de conveniencia, ¿no ves que necesitaré pellizcarme así, para no dormirme?\"},{\"heading\":false,\"text\":\"--¿Tan curro como estás y no quieres lucirte con las buenas mozas? Anda, anda, da la orden: calle del Barquillo...\"},{\"heading\":false,\"text\":\"Reservaba la casa de las solteronas una sorpresa al estudiante, en figura de la despabilada chiquilla que salió á recibir á los visitadores, y les convidó á pasar á la sala, anunciando que las tías «vendrían inmediatamente». Para decirlo hizo mil monerías con la cara y los ojos, que los tenía negros, chiquitos, vivarachos, muy parleros. Vestía la sobrinita de las de Romera un traje bastante rabicorto, indicio de que aún no había ascendido á la dignidad de la mantilla, y un mandil de peto, bordado de colorines alrededor: un lazo de cinta azul ataba la coleta de su trenza corta; y sus zapatitos usados, desflorados por la punta, indicaban la viveza de movimientos del pié menudo y arqueado que prendían. A poco rato salió Pascuala, la mayor de las solteronas, toda mocosa y acatarrada, declarando que su hermana no podía moverse del gabinete, por estar pasando un resfriado mayor aún, que requería evitar cambios de temperatura. «Mire V.: poner á mi hermana entre puertas, es como darle una puñalá». Luego presentó á su sobrina igual que hubiese presentado á un perrillo revoltoso, que alterase la soñolienta quietud de aquella morada. «Aquí tiene V. á mi ahijada Inocencia, la niña segunda de mi hermano Sebastián, el que vive en Loja... Nos la ha dejado el pobre aquí porque necesita arreglarse la boca; le ha nacío un diente montado sobre otro, y habrá que arrancárselo... Es muy ardilla; no puede estarse fija en un sitio; no hay calzado que le baste; por eso la ven Vds. tan mal de botitas...» Hechas estas aclaraciones, vino á cuento hablar de Esclavitud, y en atención á que no se podía tratar el asunto delante de «una criatura» y á que Mercedes deseaba disfrutar de la presencia de doña Aurora, las dos damas pasaron al gabinete, dejando solos á Rogelio é Inocencia. «Enséñale los álbumes y las vistas de Granada, niña», fué la orden que recibió la chiquilla al salir su tía de la sala.\"},{\"heading\":false,\"text\":\"Inocencia obedeció,--no sin hacer varias morisquetas á pretexto de llegarse á la mesa,--exclamando atropelladamente y con mucho ceceo:\"},{\"heading\":false,\"text\":\"--Venga V., venga V. á ver las estampas que dice tía Pascua. ¡Son más preciosas!\"},{\"heading\":false,\"text\":\"Aunque lo de ponerse á mirar estampitas le sabía mal al «caballero» de levita y chistera, por vergüenza de protestar se resignó, y ocupó una silla al lado de la chicuela, que, al abrir el álbum, le lanzó una ojeada inequívoca, incendiaria, con todo el descaro de los catorce años mal cumplidos. Ya al quedarse solo con la niña, le había ocurrido al estudiante que no pudiera deparársele ocasión más rodada y cómoda de echarse novia que la presente. Mortificábale un poco en su amor propio el que fuese tan chiquilla, porque una señorita de diez y ocho á veinte honraba más, y aquello olía á noviazgo de juego; pero al verla de cerca, con todos los indicios de la precocidad meridional, con su cuerpecito ya enteramente formado y su labio superior grueso y un poco remangado por el diente defectuoso, parecióle una mujer en miniatura, y dijo para sí:\"},{\"heading\":false,\"text\":\"--Me declaro.\"},{\"heading\":false,\"text\":\"Declaróse en efecto, sin más preámbulos ni ceremonias, con frases muy retumbantes aprendidas en zarzuelas y comedias, en periódicos y bromas de estudiantes. La chiquilla, sin mostrar la menor sorpresa, fingía seriedad, enrollando un pico del lazo de su trenza, traída adelante con afectación de lucir el pelo, haciendo á la vez mil mohines y dengues de coqueta de oficio. Como el estudiante alzase un poco la voz, la niña murmuró:\"},{\"heading\":false,\"text\":\"--¡Chisss... Que están ahí, en el gabinete!\"},{\"heading\":false,\"text\":\"Rogelio bajó el diapasón y apretó la súplica, aunque empezaban á cosquillearle unos fuertes impulsos de reir á carcajadas: y después de tres ó cuatro gestos negativos, la niña, sin más ni más, de golpe, dijo que _sí_.\"},{\"heading\":false,\"text\":\"--¿Me da V. una prueba de amor?--imploró Rogelio: y sin aguardar respuesta, se inclinó y la besó en el carrillo, figurándose que besaba el de una pintada muñeca, terso, rosado, insensible. Ninguna emoción, ni de placer ni de bochorno, reveló Inocencia al recibir el beso: antes cogiendo al estudiante por la solapa, indicó con mucha fe:\"},{\"heading\":false,\"text\":\"--Me parece que debemos tutearnos. Los novios de mis amigas se tutean con ellas.\"},{\"heading\":false,\"text\":\"--Bien, pues te tutearé... Ya te estoy tuteando.\"},{\"heading\":false,\"text\":\"Ella recalcó con el mismo empeño y apresuramiento:\"},{\"heading\":false,\"text\":\"--También debemos escribirnos todos los días: todos, sin faltar uno. El novio de mi hermana Lucía le escribe unas cartas así..., una por la mañana, otra por la tarde, que aún es más.\"},{\"heading\":false,\"text\":\"--Corriente. Nos escribiremos. Me entenderé con la criada para que traiga y lleve la correspondencia.\"},{\"heading\":false,\"text\":\"--Y me darás un retrato tuyo. ¿No tienes fotografías? A mí no han querido papás dejármela sacar, hasta que me arranquen el diente; pero puedo darte pelo para un medallón. ¿Me lo corto ya?--añadió jugueteando con las puntitas rizadas de la coleta.\"},{\"heading\":false,\"text\":\"--No... Cuando yo te dé el retrato.\"},{\"heading\":false,\"text\":\"La chiquilla se levantó rápidamente, y andando de puntillas, fué á la puerta del gabinete donde charlaban las señoras mayores. Regresó, con las mismas precauciones, gozosa.\"},{\"heading\":false,\"text\":\"--Creí que venía madrina. Pero no. Están de mucho palique.\"},{\"heading\":false,\"text\":\"Dicho esto volvió á ocupar su sitio al lado del estudiante, y transcurrieron dos ó tres minutos sin que se dijesen palabra. La chiquilla esperaba, sorprendida de que no se le ocurriese nada á su novio; y al muchacho, por más que discurría, no se le venía ni esto á la boca. Sólo continuaba teniendo ganas de reir, unas ganas disparatadas, y para no estallar se cubría los labios y la nariz con el rico pañuelo de bordada inicial. La _novia_ reparó en el pañuelo, y observó vivamente:\"},{\"heading\":false,\"text\":\"--¿Qué letra es esa?\"},{\"heading\":false,\"text\":\"--Erre. Me llamo Rogelio.\"},{\"heading\":false,\"text\":\"--Ya te lo iba yo á preguntar. Siendo mi novio necesito saber cómo te llamas. ¿Qué pongo en los sobres de las cartas? Señor Don Rogelio...\"},{\"heading\":false,\"text\":\"--Pardiñas.\"},{\"heading\":false,\"text\":\"--Pardiñas, Pardiñas, Pardiñas...--Repitiólo muchas veces la muchacha, como si temiese olvidarlo; y después, encarándose con el estudiante, le interrogó con tono solemne:\"},{\"heading\":false,\"text\":\"--¿Nos hemos de casar?\"},{\"heading\":false,\"text\":\"Aquí ya Rogelio no pudo aguantar el acceso de risa nerviosa, y la dejó salir por la boca, por los ojos, por el cuerpo mismo, cogiéndose la cintura, que le dolía con la fuerza de las carcajadas. Y sollozaba, echado atrás en el sillón:\"},{\"heading\":false,\"text\":\"--¡Ay... ay... me muero, me muerooó!\"},{\"heading\":false,\"text\":\"--¿De qué te ríes?--preguntó algo picada la niña.--Pareces tonto. Dime si nos hemos de casar, ea.\"},{\"heading\":false,\"text\":\"--Por supuesto que sí. Es que soy muy tentado de la risa. Déjame reir, que si no me pongo malo.\"},{\"heading\":false,\"text\":\"Así que hubo desahogado, Inocencia le cuchicheó al oido:\"},{\"heading\":false,\"text\":\"--¿Pasarás mañana á las nueve de la mañana por esta calle? Yo estaré al balcón. A esas horas me asomo siempre á ver pasar la batería montada. Es muy bonita. ¿Tú qué carrera sigues?...\"},{\"heading\":false,\"text\":\"--Abogado.\"},{\"heading\":false,\"text\":\"--¡Lástima! No tienes uniforme.\"}]},{\"title\":\"Morriña — capítulo XIII\",\"blocks\":[{\"heading\":false,\"text\":\"A Rogelio, cuando iban terminando de bajar la escalera, le duraba aún la impresión burlesca del noviazgo, por lo cual no se cuidó de ofrecer el brazo, según acostumbraba, á doña Aurora. Un grito y un estruendo inesperados le helaron la sangre en las venas, al ver á la señora resbalar y precipitarse desde el último tramo yendo á caer sobre las baldosas del portal. Los grandes sentimientos tienen revelaciones supremas en las ocasiones supremas también; Rogelio ignoraba que hubiese cuerdas en su laringe y acentos en su voz para decir de un modo tan desgarrador y patético:\"},{\"heading\":false,\"text\":\"--¡¡Madre del alma!!\"},{\"heading\":false,\"text\":\"Saltó á brincos lo que su madre había rodado, y en un abrir y cerrar de ojos la puso de pié, la reclinó en sus brazos y la apretó contra el corazón, palpándola con delirio, para cerciorarse de que no estaba muerta ni tenía ningún miembro fracturado. De repente lanzó una exclamación de horrible susto.\"},{\"heading\":false,\"text\":\"--¡Sangre, mamá!... Hay sangre... ¿Por dónde sangras? Aquí... ¡Jesús, sangre!\"},{\"heading\":false,\"text\":\"En efecto, la cabeza había dado contra el filo de un peldaño, y asomaban unas gotas de sangre por la descalabradura. Aturdida como estaba la señora por la fuerza del porrazo, la angustiosa voz de su hijo la reanimó, y pudo decir con desmayado acento:\"},{\"heading\":false,\"text\":\"--No te asustes, rapaz. No fué nada... puedes creerme que no fué nada. Ya estoy así..., mejor.\"},{\"heading\":false,\"text\":\"--En esta portería no hay nadie... Voy á subir, á pedir vinagre, agua...\"},{\"heading\":false,\"text\":\"--No, hijo, no, por la Virgen... No llames, no alborotes. Llévame al coche poquito á poco. Para males y cosas así, cada uno en su casa.\"},{\"heading\":false,\"text\":\"Temblando y trasudando frío, Rogelio condujo á su madre, casi en vilo, al coche, y á pulso la subió, recostándola en la esquina, mientras le hacía aire con el pañuelo, pensando con terror: «¿Habrá habido conmoción cerebral?»\"},{\"heading\":false,\"text\":\"--A casa, despacito--ordenó al cochero que se inclinaba lleno de curiosidad para ver qué sucedía. Y sin poder reprimirse, Rogelio abrazó á la señora, formulando la pregunta de todas las caídas:\"},{\"heading\":false,\"text\":\"--¿Pero mamá, cómo hiciste?\"},{\"heading\":false,\"text\":\"--No sé, hombriño... el pié se me escapó; sería culpa de los tacones de las botinas nuevas... ó me prendería en el volante del traje.\"},{\"heading\":false,\"text\":\"--Culpa mía, que no te di el brazo. Soy un bruto. ¿Dónde te duele? ¿Qué tienes ahora, mamá?\"},{\"heading\":false,\"text\":\"--No sé... Parece que me entra un síncope--respondió con voz débil la señora.\"},{\"heading\":false,\"text\":\"De síncope eran las trazas, según el color mortal y el enfriamiento repentino. Rogelio estuvo á punto de gritar al cochero: «A una botica»; pero en esta incertidumbre y congoja, la señora volvió un poco en sí, hizo señas de encontrarse mejor, y el coche se fué acercando á la puerta de la casa. Al bajar Rogelio á su madre, ayudado del lacayo, la señora lanzó una queja.\"},{\"heading\":false,\"text\":\"--¿Qué te duele?\"},{\"heading\":false,\"text\":\"--Esta pierna... No, si no vale nada, no te apures.\"},{\"heading\":false,\"text\":\"Enterada al vuelo de lo ocurrido, Esclavitud, sin inútiles aspavientos, con actividad y destreza, se dió prisa en aflojar á la señora, aplicarle vinagre á las sienes, desnudarla después y acostarla en su cama bien mullida. Doña Aurora se quejaba de arcadas, de angustia, de opresión, de náuseas continuas, y deseaba arrojar; por lo cual el estudiante pensó aterrado: «¡Adiós! conmoción cerebral tenemos». Llamó aparte á Esclavitud y la dijo atropelladamente: «Ten cuidado. Yo voy por Sánchez del Abrojo, y no me vengo sin él».\"},{\"heading\":false,\"text\":\"Le trajo, en efecto, al cabo de dos horas; y el insigne médico, después de examinar detenidamente á la enferma y verificar un minucioso y hábil interrogatorio, tuvo que convenir en que había habido un poquito, nada más que un poquito, de conmoción cerebral... Unica terapéutica: quietud en la cama, silencio, dieta mientras no se aplacase el estómago. Las demás lesiones eran de escasa monta: la descalabradura de la frente no había pasado de la epidermis: la contusión en la pierna izquierda se reduciría á un cardenal más ó menos respetable. En suma, todo no valía nada. Quietud, y se acabó.\"},{\"heading\":false,\"text\":\"Para cumplir el programa del facultativo, realizóse en casa de Pardiñas esa mutación de costumbres y ese cambio de aspecto que introduce siempre la enfermedad. La vida se reconcentró en el estrecho espacio de la alcoba y gabinete de la enferma. Rogelio y Esclavitud se declararon allí en sesión permanente, él recibiendo visitas de amigos, ella mudando paños de árnica, trayendo tazas de tila, quemando espliego y haciéndose cargo de órdenes dadas en voz baja y llaves confiadas con misterio sumo. «Que no le falte nada al niño... Su sopicaldo, su jerez... Cuidado con calentarle la cama...» A estas advertencias, que Esclavitud oía religiosamente, seguían gemidos ahogados. «Ay, la maldita pierna, como me escuece... Se me parte la cabeza de dolor».\"},{\"heading\":false,\"text\":\"Ejercía Esclavitud sus funciones de enfermera con aquella asiduidad reconcentrada y muda que solía demostrar en todos los actos de la vida de relación. Salía y entraba sin que se percibiese el menor ruido de pisadas, ni crujido ó roce de ropa. Estaba en todo, y si faltaba de la alcoba, era á fin de manipular algún potingue en la cocina. Hasta se las arregló para tener tiempo de servir la comida á Rogelio sin desatender á la señora; pero de ella misma, no se averiguó jamás á qué hora había tomado algún sustento en aquel día memorable.\"},{\"heading\":false,\"text\":\"Adelantada ya la noche, y recogida la casa, preparó cuidadosamente una lamparilla y la colocó en el suelo, de modo que su luz no ofendiese la vista de la enferma: después tomó una silla baja, que colocó cerca de la cabecera y en la cual se instaló. Como Rogelio permaneciese en la butaca del gabinete, acercóse á él y le suplicó en voz muy queda: «Acuéstese, señorito; no esté así». La enferma, que había empezado á aletargarse un poco, entreoyó la súplica, y la esforzó más. «Rapaz, á ver si te acuestas... No estás acostumbrado á velar, te va á hacer mucho daño... No seas loco, acuéstate... Me cuida divinamente Esclavitud». Mas no hubo forma de convencer á Rogelio, y el pleito se transigió resolviendo que se le pondría en el suelo una cama volante. La galleguita acarreó con extraño vigor dos colchones; batió silenciosamente las almohadas, y con igual silencio hizo la cama en toda regla. Rogelio no se desnudó más que de la americana y el chaleco; así, á medio vestir, se deslizó entre las sábanas, notando entonces el quebrantamiento corporal que sigue á los grandes sobresaltos y á las emociones profundas. Al mismo tiempo un recuerdo bufo cruzó por su memoria:\"},{\"heading\":false,\"text\":\"--¡Calle! ¿Y mi novia? ¿Se asomará mañana para verme?\"}]},{\"title\":\"Morriña — capítulo XIV\",\"blocks\":[{\"heading\":false,\"text\":\"Aunque rendido por las fuertes impresiones de la jornada, y casi tranquilo porque veía á su madre en estado bastante satisfactorio, Rogelio tardó mucho en conciliar un sueñecillo, y dió no pocas vueltas antes de quedarse traspuesto. Ni consiguió adormecimiento profundo y reparador, sino un dormir agitado, lleno de pesadillas, soñando siempre que se caía; caídas rápidas, infinitas, interminables, con la angustia de no llegar jamás al suelo, y de ver desde arriba el punto crítico en que iba á estrellarse. En uno de esos esfuerzos dolorosos é involuntarios que se hacen durante el sueño mismo ó para terminar la pesadilla ó para cambiarla, despertó atónito, y no recordando al pronto cómo podía ser que se encontrase allí, á aquellas horas, acostado en la alcoba de su madre, miró á su alrededor.\"},{\"heading\":false,\"text\":\"Silencio absoluto. El cuarto estaba medio á obscuras, alumbrado por la lamparilla; la señora debía de dormir, porque se la oía respirar fuerte, roncar casi; y á su cabecera, el estudiante divisó á Esclavitud sentada, inmóvil, con los ojos abiertos y clavados en él, grandes y fijos. Un impulso irresistible le movió á llamarla, con voz de niño que, á causa de algún miedo nocturno, implora compañía.\"},{\"heading\":false,\"text\":\"--¡Esclavita! ¡Ps! ¡Esclavita!--cuchicheó.--Aquí.\"},{\"heading\":false,\"text\":\"Se acercó la muchacha, deslizándose como una sombra, y se inclinó hacia Rogelio.\"},{\"heading\":false,\"text\":\"--¿Duerme mamá?\"},{\"heading\":false,\"text\":\"--Y bien que duerme.\"},{\"heading\":false,\"text\":\"--Pues yo ahora estoy despabilado. Dame conversación..., así, bajito, para que no la despertemos.\"},{\"heading\":false,\"text\":\"--¡Ay, señorito! ¿Y si vamos á molestarla?\"},{\"heading\":false,\"text\":\"--Que no. Habla bien despacito... y de cerca.\"},{\"heading\":false,\"text\":\"--¿No le era mejor dormir?\"},{\"heading\":false,\"text\":\"--¡Quiá! ¡Si supieras qué cosas tan tristes soñaba! No, más quiero velar ahora. Ponte aquí.\"},{\"heading\":false,\"text\":\"--¿Dónde?\"},{\"heading\":false,\"text\":\"--Sentada aquí, en el suelo. Si no no podemos hablar bajo... y despertaremos á mamá.\"},{\"heading\":false,\"text\":\"Esclavitud aceptó la proposición incontinenti, y se tendió casi boca á boca con Rogelio, pero sin perder su aire púdico y reservado, manifestando bien en esto haber nacido en el país donde se ejecutan las acciones libres con más aire de decencia, y donde las mozas unen á la naturalidad bucólica el exterior honesto. El aliento virginal y fresco de la muchacha se mezcló por segunda vez con el del estudiante; pero le produjo una impresión muy diferente de la primera. Sea que el sustazo de la caída de su madre hubiese transformado todas sus sensaciones juveniles en sentimiento, sea que el lugar en que se encontraba no permitiese malas tentaciones, ello es que al tener tan próxima á Esclavitud y tan fácil cualquier desmán, ni se le pasó por las mientes intentarlo, y sólo notó una especie de efusión rara y cariñosa, un movimiento de ternura inexplicable, mientras sus ojos se llenaban de lágrimas. Alargando la mano y apretando con violencia la de la chica, murmuró:\"},{\"heading\":false,\"text\":\"--Esclava, ¡por poco se muere hoy mamá!\"},{\"heading\":false,\"text\":\"--¡Gracias á Dios que no fué nada, señorito!--contestó la muchacha correspondiendo á la presión.\"},{\"heading\":false,\"text\":\"--¿Y si muriese, qué hacía yo, di?\"},{\"heading\":false,\"text\":\"No respondió Esclavitud, y obró sabiamente, porque el problema planteado era de los que no se resuelven con palabras. Estrechó aún más la mano nerviosa y febril, y sus ojos contestaron, en la penumbra, con larga mirada elocuentísima.\"},{\"heading\":false,\"text\":\"--Si muriese--prosiguió Rogelio dejándose arrastrar por aquel movimiento de sensibilidad involuntaria--ahí tienes; no me quedaba nadie en el mundo más que tú, nadie.\"},{\"heading\":false,\"text\":\"--¡Yo!...--balbució la muchacha, cuya diestra se estremeció en la del estudiante.\"},{\"heading\":false,\"text\":\"--Pues tú, y nada más que tú. Familia no la tengo; digo, allá en Galicia unas tías, con quienes estamos como el perro y el gato. Ya ves qué arrimo, chica. ¡Pues amigos...! ¡bah! dos ó tres... ahí en la Universidad... Amigotes que de poco sirven. Luego los viejos de la tertulia de mamá. Gran cosa. Todos van chocheando. Nada, Suriña..., tú y sólo tú.\"},{\"heading\":false,\"text\":\"Hablaba así Rogelio medio incorporado, para mejor dejarse oir de la muchacha; y la necesidad de bajar mucho la voz, hacía parecer más persuasivo su acento, dándole el tono apasionado y reprimido de una confesión. Persuadido él, persuadía al auditorio. No se encontraba en estado de medir la trascendencia y el efecto de sus palabras, ni menos sospechaba que la sensibilidad y la bondad pueden ser en determinadas ocasiones más funestas que la cólera y el odio. En su emoción había mucho de nervioso, y las frases salían de sus labios provocadas por una reacción del susto de la mañana, como sale el gemido al golpe del dolor, que ni sabemos medirlo, ni de qué manera lo hemos articulado. Lo mucho que tenía aún de niño rebosaba en aquel desahogo cariñoso, y ni él aspiraba á más, ni más podía prever, dado que en momentos tales quepa ejercitar previsión.\"},{\"heading\":false,\"text\":\"--Tú, Suriña--repetía entregándose á las manos que con vigor casi convulsivo oprimían la suya.--¿Verdad que tú me quieres, y que me quieres mucho?\"},{\"heading\":false,\"text\":\"Incapaz de responder con la boca, la muchacha afirmó enérgicamente con la cabeza.\"},{\"heading\":false,\"text\":\"--Ya lo sé. Si eso lo había adivinado yo; por eso te decía que no me quedaba nadie más que tú, y que á ti me arrimaba, ¿sabes? Aunque me dijeses que no, no te lo creería. Me quieres... y á mamá también.\"},{\"heading\":false,\"text\":\"--Pues es verdad--pronunció al cabo la chica recobrando el habla y apartándose un poco del estudiante.--Yo no sé qué me ha pasado á mí en esta casa, que le cogí así á modo de un cariño... un cariño muy grandísimo desde que entré por la puerta. Vamos, se me figuraba que estaba en la tierra otra vez. Como son personas de allá... En fin..., estas cosas me parece á mí que cuanto más quiere uno explicarlas, peor las explica. Lo que sé es que si me quedo con aquellas otras señoras, doy cabo de mí muy pronto.\"},{\"heading\":false,\"text\":\"--¿Y por qué estabas tan triste aquí los primeros días, Esclava?\"},{\"heading\":false,\"text\":\"--Verá... Porque pensé que V. me tenía tema.\"},{\"heading\":false,\"text\":\"--¡Yo tema!\"},{\"heading\":false,\"text\":\"--Sí señor. Cavilando en eso me vinieron unas melancolías muy hondas. Se me metió en la cabeza el _verme_...\"},{\"heading\":false,\"text\":\"--¿El _verme_?\"},{\"heading\":false,\"text\":\"--Le decimos allí así á uno... como un bicho, vamos, un gusano, una cavilación, para hablar verdad. Toda la santa noche pasaba á devanar la madeja... «¿Qué haré para que me pierda la tema el señorito? ¿Cómo me valdré para darle gusto?» Y lo más chocante de todo..., puede creerme, es tan verdad como que Dios está en el cielo..., que así tan negra como tenía el alma... no era como en la otra casa, no. De ésta no me querría ir ni hecha cuartos, más que de ella me echasen.\"},{\"heading\":false,\"text\":\"--Porque sabías que yo te quería, Sura.\"},{\"heading\":false,\"text\":\"--No señor, no; no lo sabía: á fe que pensé que aborrecida era. De la rabia que tomé me daban ganas de morirme.\"},{\"heading\":false,\"text\":\"--Yo sí que me muero de gusto con oírtelo. Ahí estás muy mal, chica. Pon la cabecita en mi almohada. Ahí va. Te la saco fuera para que te alcance.\"},{\"heading\":false,\"text\":\"Esclavitud apoyó la cabeza en la almohada sin desconfianza ni esquivez, y los dos permanecieron un instante silenciosos, saboreando el momento. La endeble luz de la lamparilla señalaba en realce las facciones de Esclavitud, marcando los claros con pálida blancura, los obscuros con un matiz uniforme, entre gris y rosa. Parecía un fino grabado, y Rogelio expresó su admiración así:\"},{\"heading\":false,\"text\":\"--Suriña, eres preciosa.\"},{\"heading\":false,\"text\":\"En esto doña Aurora suspiró hondo, y ambos se estremecieron, aunque su coloquio no pudiese en ningún modo graduarse de ilícito. La enfermera se puso de pié para enterarse de lo que ocurría. A los dos segundos estaba de vuelta.\"},{\"heading\":false,\"text\":\"--Duerme como una santa.\"},{\"heading\":false,\"text\":\"--Colócate bien otra vez. Quiero preguntarte una cosa. La mano. ¿Por qué te daba tan fuerte la manía de si me tendrías contento ó descontento?\"},{\"heading\":false,\"text\":\"--¡Ay! ¡No sé! Desde el primer día dije yo entre mí: si aquí no te quieren, Esclava, es que estás de sobra en el mundo. Ya viniste á él contra la voluntad de Nuestro Señor... Ya Dios te miró siempre con malos ojos... ¿No lo sabe, señorito?\"},{\"heading\":false,\"text\":\"--Sí que lo sé, Suriña... Pero eso es una atrocidad. ¿Cómo va á mirarte Dios con malos ojos?\"},{\"heading\":false,\"text\":\"La muchacha medio se incorporó de un salto, con los suyos muy abiertos, espantada de ver que ya sabían lo mismo que ella se disponía á confesar.\"},{\"heading\":false,\"text\":\"--No seas boba--murmuró generosamente Rogelio.--Tú qué culpa tienes, mujer. Eso me puede suceder á mí, á cualquiera. El nacimiento no lo escogemos. ¡Simple!\"},{\"heading\":false,\"text\":\"--¡Si viese cómo me trabaja _eso_ allá dentro!...--articuló con vehemencia la muchacha, abriendo el corazón como si, próxima á desmayarse, desabrochase el corpiño para respirar.--Siempre estoy imaginando: «Esclava, á ti Dios no te puede querer bien. Nunca buena suerte has de tener, nunca. Ya desde que naciste estás en poder del enemigo, y buena gana tiene el enemigo de soltar lo que agarra. Por mucho que te empeñes en ser un ángel, estarás eternamente en pecado mortal. Ya lo tienes de obligación. Para ti no hay padre, ni madre, ni nada más que vergüenza cuando te pregunten por ellos. Y así, todo lo que hagas te tiene que salir del revés, y si te encariñas con una persona, peor, que Dios te ha de quitar aquel cariño.»\"},{\"heading\":false,\"text\":\"--Pues conmigo no te pasará nada de eso, Suriña blanca. Yo te quiero como si fueses hija del rey... Mamá también te quiere mucho; le entraste desde el primer día, ¿no sabes?\"},{\"heading\":false,\"text\":\"Esclavitud, al oir este aserto, levantó la cabeza, clavando la vista en el lecho de la señora. Su mirada y su sonrisa querían decir varias cosas importantes; pero Rogelio no estaba en disposición de prestarse á entenderlas. El estado de su ánimo no era á propósito para razonamientos, sino para dejarse mecer dulcemente por el afecto que necesitaba como sedación y medicina. Viendo que no le producía Esclavitud las malas tentaciones de otras veces, pensaba que su cariño se había depurado, y que aquel juego anómalo era lo más inocente del mundo. O para decir toda verdad: estaba en una crisis de sentimiento, y ni pesaba ni medía sus promesas y sus afirmaciones. Era para él uno de esos minutos de la vida en que se obedece á la naturaleza íntima, al egoismo secreto, y se cede al gusto de sentirse querido y de hacerse querer más aún: quien está triste busca el consuelo, y el hambriento la comida.\"},{\"heading\":false,\"text\":\"--Mamá te quiere mucho--repitió.--¿Parece que no lo crees? ¡Boba! Pues si ella misma fué quien me riñó porque te trataba así, un poco fríamente... al principio. Ella me dijo que estabas disgustada por eso.\"},{\"heading\":false,\"text\":\"Esclavitud bajó los ojos, sin duda para que delatasen sus pensamientos é intuiciones adivinatorias del porvenir.\"},{\"heading\":false,\"text\":\"--Mira--murmuró Rogelio--si vieses qué bien me encuentro así contigo. Hasta parece que me vuelven á entrar ganas de dormir, y ahora no habrá malos sueños ni boberías. Se me figura que dormiré lo mismo que un patriarca; pero hace falta que tú tengas la cachacita de estarte ahí al pié mío. Si te vas, me despavilo otra vez.\"},{\"heading\":false,\"text\":\"--No me muevo--respondió con firmeza la muchacha.--Así me quisiesen arrancar con tenazas, aquí me estoy.\"},{\"heading\":false,\"text\":\"--Bien, pues... me quedo dormidito. ¡Ay qué bueno!\"},{\"heading\":false,\"text\":\"Paladeando la primera y dulce cucharada de beleño que nos da el reposo cuando sigue á un gran sacudimiento moral ó físico, Rogelio preguntó todavía:\"},{\"heading\":false,\"text\":\"--¿Suriña?\"},{\"heading\":false,\"text\":\"--¿Qué?\"},{\"heading\":false,\"text\":\"--¿Me quieres mucho?\"},{\"heading\":false,\"text\":\"La respuesta la entreoyó nada más: por eso nunca estuvo bien seguro de que hubiese sido ésta, tan romántica é impropia de una aldeanita:\"},{\"heading\":false,\"text\":\"--Hasta la hora de morir.\"}]},{\"title\":\"Morriña — capítulo XV\",\"blocks\":[{\"heading\":false,\"text\":\"No obstante la explícita promesa, cuando Rogelio abrió los párpados después de un sueño tranquilo y bienhechor, vió á Esclavitud á la cabecera de su madre, sirviéndola una tacita de caldo. La señora, aliviada de la jaqueca, se quejaba mucho de la contusión en la espinilla. Poco después vino Sánchez del Abrojo, y le dió la razón asegurando que, según las trazas, aquella magulladura iba á presentar una degeneración erisipelatosa, por lo cual, para evitar los perniciosos efectos del frío sobre los tejidos, convenía la cama.--«Tampoco estaba yo capaz de levantarme aunque me diesen permiso», advirtió la señora. «Me encuentro como si me hubiesen manteado y pegado después una tunda con sacos de arena. No tengo hueso que bien me quiera. Ahora es cuando noto yo las resultas del batacazo.»\"},{\"heading\":false,\"text\":\"Rogelio tomó chocolate al pié de la cama de su madre, y manifestaba pocas ganas de moverse de allí; pero doña Aurora cayó en la cuenta en seguida. «¡Ay, ay, rapaz! A clase volando. Ya sabes que esos señores, y en particular Ruiz del Monte, no tragan las faltas de asistencia. Después llega el tiempo de los exámenes, y tenemos aquello de quién lo diría.»\"},{\"heading\":false,\"text\":\"Fué necesario, pues, sacudir la pereza, ir al cuarto, chapuzarse con agua glacial, embozarse bien y salir á la condenada _fábrica de chocolate_, como llamaba Rogelio á la Universidad, fundándose en que en ningún sitio muelen tanto. Al dejar la atmósfera templada de su casa, despejado por las abluciones matutinas, y sentir el frío de la mañanita en los ojos y en los labios, notó Rogelio como si se rasgase un velo de niebla, y los recuerdos del día anterior se definieron y se aclararon del todo. A tales horas, su novia, la chiquilla del sobrediente, estaría colgándose del balcón para ver pasar primero á la batería montada y luego á él. Una oleada de risa estremeció el pecho de Rogelio al acordarse de tal episodio. «¡Qué pava, como dicen los simones! ¡Vaya un modo que tuve de echarme novia!» Después acudieron las reminiscencias nocturnas. «Yo no sé cómo estaba: la caída de mamá me puso turulato. Le dije á Esclava unas cosas estupendas. Aquello sí que parecía verdadera declaración amorosa, por todo lo alto. Aquello sí. Y que me puse conmovido, y que si me descuido, me echo á llorar. No, pues ella también estaba en punto de caramelo. Pero, bien mirado..., nada de lo que nos dijimos compromete á ninguno de los dos. Son cosas que las suelta uno... así... porque hay momentos... Si me pusiesen ahora en el apuro de explicar cómo se las dije, no podría. Me salían de dentro. Quizá esto sea _querer_; lo que es lo otro... es pura guasa. Bien; al menos _esto_ de ahora, caso que mamá lo averiguase, no le daría tanto disgusto como _aquello_ que se me ocurría al principio. En lo de anoche no veo ningún mal». Y al cruzar un saludo á la puerta de la Universidad con el soñoliento bedel, sus pensamientos mudaron de dirección, y se le ocurrió: «Me luzco si hoy me preguntan la conferencia.»\"},{\"heading\":false,\"text\":\"Por la tarde se llenó la casa de amigos, que habían sabido el percance y venían «á ofrecerse». Hubo hasta dos ó tres señoras, á las cuales se permitió entrar en la alcoba y dar conversación á la paciente, porque en la cabeza no tenía nada ya, y en consecuencia no la molestaba el ruido. Ni faltaron los tertulianos de costumbre, que se quedaron en el gabinete, haciendo compañía al _hijo de la víctima_, como se llamaba á sí mismo Rogelio bromeando. Se habló de las consecuencias que pudo tener el golpe: se dedicó media hora larga á inquirir lo que sucedería si la señora, en vez de poner el tacón así, lo pone asado. Sólo Laín Calvo, representante, al par que de la malignidad, del buen sentido en aquella reunión senil, hacíase más que nunca el sordo, limitándose á atizar la lumbre y á mirar las láminas y caricaturas de los periódicos ilustrados. Dos ó tres veces sacó su trompetilla del bolsillo, é hizo ademán de limpiarla é introducirla en el conducto; y otras tantas la volvió á guardar, sin más consecuencias. Pero la prueba evidente de que oía á las mil maravillas, fué que á pretexto de enseñarle no sé qué dibujos de _La Ilustración Ibérica_, se inclinó hacia el estudiante y le dijo con una mueca más de granuja que de sesentón:\"},{\"heading\":false,\"text\":\"--Niñín, no sé cuándo acaban estos estafermos de darte la lata. Cuidado que están hoy más memos que de costumbre. ¿A qué vendrá andar discurriendo lo que pudo suceder si pasase lo que no pasó? Ahora cuadra bien aquello de «Si como le dió en el pié le da en la pata... la mata.»\"},{\"heading\":false,\"text\":\"Después se suscitó otra conversación, siempre relacionada con el magno suceso de la caída: y fué discutir si haría falta que alguna amiga se quedase á asistir á la enferma, porque para Rogelio no servían ciertos trajines; al fin no tenía experiencia, y era hombre. Pero aquí saltó Don Gaspar Febrero, llegando hasta robustecer sus aseveraciones con golpecitos del regatón de la muleta sobre el guardafuego de la chimenea.\"},{\"heading\":false,\"text\":\"--¡Pues si tiene la mejor enfermera que se habrá visto! ¡Señores! ¡Que no estará la amiguita doña Aurora bien cuidada con la simpática Esclavitud! De fijo que parecerá una Hermana de la Caridad. No se compadezcan de Aurora: compadézcanse de los pobres que no tendremos una Esclavitud á la cabecera si nos llega la de cerrar el ojo...\"},{\"heading\":false,\"text\":\"La tertulia en masa protestó, excepto Laín Calvo, el cual parecía muy entretenido en ajustarse la trompetilla.\"},{\"heading\":false,\"text\":\"--V., don Gaspar... ¡Pues si V. nos enterrará á todos! ¡Digo: apenas si está fuerte el hombre! Igual que un muchacho.\"},{\"heading\":false,\"text\":\"Meneó la cabeza Don Gaspar, pero con aire tan sereno y olímpico, con tanta vida en las correctas facciones, que más parecía un semidiós de la Grecia afirmando su inmortalidad, que un viejo de nuestra angustiada época anunciando la caducidad de la vida.\"},{\"heading\":false,\"text\":\"--La verdad es--intervino Laín Calvo--que todos estamos hechos unos pellejos podres, y que ya, si nos tocan, nos reducimos á polvillo como las momias del Perú. ¿No decía eso, Don Gaspar?\"},{\"heading\":false,\"text\":\"--Decía--le gritó Rojas--que para cuidar de sus males quiere á Esclavitud, la doncella de doña Aurora.\"},{\"heading\":false,\"text\":\"--¡Aire!--exclamó el sordo.--No, pues con los cuidados de una rapacina así, pronto se va un viejo á la sepultura, aunque esté hecho un roble, caray. A no ser que sea como el rey David...--Y añadió encarándose con Rogelio.--¿Qué dice á esto el rapacín de la casa? ¿Quiere cederles la niña guapa á los vejetes? ¿No protesta?\"},{\"heading\":false,\"text\":\"Ya por el modo como lo dijo, ó ya porque la conciencia de Rogelio tenía alguna razón para sobresaltarse, ó porque su inexperiencia y poca edad no le permitían aún el aplomo que se requiere en tales casos, Rogelio se puso como la grana (lo cual se notaba más en él por su morena palidez habitual), y contestó tartamudeando:\"},{\"heading\":false,\"text\":\"--No, yo... Yo... al señor de Febrero...--Y para su coleto decía:--«¡Sordo del diablo! Oyes tú más... Hasta oyes crecer la hierba.»\"},{\"heading\":false,\"text\":\"Los preparativos para la noche no se diferenciaron de los de la precedente, sin otra variación sino que, á fin de no viciar el aire, la cama de Rogelio se colocó en el gabinete, pero comunicada con la alcoba por medio de la puerta abierta. La enferma tardaba en coger el sueño, quejándose de dolores, de inflamación en la pierna dichosa, y de un molimiento inexplicable: Rogelio, al apoyarle la mano sobre la frente, notó algún calorcillo, observación que tuvo desvelado al estudiante, sin que dejase de alterarle también la idea de si Esclavitud iría ó no á darle un rato de palique, lo cual temía y deseaba. En esta zozobra se adormeció por fin; y medio entre sueños, hacia eso del amanecer, vió acercarse á la muchacha, que se inclinó y le dijo rápidamente: «No puedo apartarme de allí. Pide mucho de beber. Se queja que le duele aquí y que le duele acullá: es el mismo retumbo del golpe.» Y Rogelio, desalentado, murmuró: «Bien, Suriña.» Pero con aquellas malas nuevas ya no pudo volver á prender en un sueño seguido. ¿Habría peligro? ¿Sería principio de una fiebre? El médico, que vino temprano, le quitó la aprensión. «Todo esto es la repercusión de la caída. La calentura, insignificante. La inflamación la vamos á combatir... Deme V. papel. Esta tarde ya se notará la mejoría.» Por la tarde, en vez de la mejoría anunciada, se advirtió algún recargo, pero al anochecer se indicó el alivio, y á las diez la señora cenó con mucho apetito un ala de gallina. «¡Ay... alabado sea Dios!--decía.--Parece que se me han sosegado mis huesos. Sentía allá dentro una opresión... Rapaz, me parece que ya tenemos mujer.» A este alegre vaticinio siguió una calma profunda, y á cosa de la media noche doña Aurora gozaba de un descanso de convaleciente, tan profundo y apacible, que casi no se le notaba la respiración.\"},{\"heading\":false,\"text\":\"--Hoy sí que viene volando--pensó Rogelio, decidido á no adormecerse y sintiendo, á pesar de sus sofismas para no dar á _aquello_ importancia ninguna, un rebullicio en el sistema nervioso, y en el corazón un desordenado latir.\"}]},{\"title\":\"Morriña — capítulo XVI\",\"blocks\":[{\"heading\":false,\"text\":\"Vino en puntillas, mostrando viveza y júbilo que contrastaban con su acostumbrada reserva, y se acurrucó en el piso como gata favorita al pié de la cama de su dueño. Este, sin embargo, no le dedicó sus primeras palabras, sino que instintivamente las consagró al verdadero amor de su vida, á la mujer que le había llevado en su seno y que reposaba allí á dos pasos.\"},{\"heading\":false,\"text\":\"--¡Pero ves qué gusto, Esclava! Mamá se ha puesto casi bien del todo. Parece mentira. Me ha dado un susto de órdago. Esta mañana, cuando me dijiste que estaba así... no pude dormir ya más.\"},{\"heading\":false,\"text\":\"Esclavitud, antes de contestar, miró al estudiante de un modo raro por lo penetrante y profundo.\"},{\"heading\":false,\"text\":\"--Bien que le recé á mi patrona la Virgen de la Esclavitud para que la señora se aliviase. Le ofrecí también una misa. Ya ve cómo la Virgen me ha hecho caso, señorito.\"},{\"heading\":false,\"text\":\"--¡Ya se ve! Tú debes de tener vara alta en el cielo.\"},{\"heading\":false,\"text\":\"--Sí, señor...--murmuró la muchacha.--La tengo. Para conseguir todo lo que es contra mí.\"},{\"heading\":false,\"text\":\"--¡Contra ti!--articuló Rogelio asombrado y un tanto receloso.--¿Y es contra ti el que mi madre sane?\"},{\"heading\":false,\"text\":\"--Como sanar...--balbuceó Esclavitud--como sanar... no, señor, y quiera Dios llevarme á mí antes que á ella. Pero en acabándose el mal, se acaba la vela, y en acabándose la vela... se acaban estos ratos.\"},{\"heading\":false,\"text\":\"La explicación halagó la vanidad de Rogelio, afirmándole una vez más que era querido, y no á la manera de los niños, sino del modo que quiere al hombre la mujer, punto en que consistía toda la gracia de tan singular comercio, que no se atrevía á llamar, ni aun en sus adentros, amoroso. Aquellas palabras, dulces por el mismo acento hosco y dolorido con que la muchacha las pronunció, impulsaron á Rogelio á alargar el brazo, y cogiendo la bonita cabeza de su amiga, la arrimó á su pecho y la estrechó con ternura. Esclavitud respiraba tan anhelosamente, que Rogelio la dijo en tono afectuoso:\"},{\"heading\":false,\"text\":\"--Ya te suelto... No quiero hacerte daño, ni sofocarte.\"},{\"heading\":false,\"text\":\"--Daño, no--murmuró la muchacha.--Daño, no.\"},{\"heading\":false,\"text\":\"Rogelio no volvió á estrecharla. Ninguna violencia tenía que imponerse para respetar á Esclavitud, allí, al borde de la cama de su madre, y en aquellas efusiones de carácter más fraternal que apasionado, cuyo verdadero sentido y objeto ni él mismo acertaba á definir. Sólo se deslizó á pasar la mano repetidas veces por el pelo rubio, revuelto y abundante. A la vista parecía más sedoso el pelo de Esclavitud; pero de todos modos, era muy agradable acariciar la madeja ondeada y tibia.\"},{\"heading\":false,\"text\":\"--¿No quieres dormir un poquito?--le propuso.--Llevas dos noches en vela y debes de estar molida. Si mamá rebulle te despierto. Yo al fin he de estar despabilado...\"},{\"heading\":false,\"text\":\"Negóse Esclavitud. ¡Velar tres noches! Gran cosa. Cuarenta días sin desnudarse había pasado á la cabecera del cura, en su última enfermedad, sin tomar otro descanso sino recostarse á ratos, en una silla vieja, á descabezar una siesta de cinco minutos... ¡Velar tres noches! Velaría ella un trimestre.\"},{\"heading\":false,\"text\":\"--Pues si no has de dormir, entretenme. Cuéntame algo.\"},{\"heading\":false,\"text\":\"--¡Ay, señorito... pues buena persona ha ido á buscar para contarle!... Quien no sabe nada...\"},{\"heading\":false,\"text\":\"--¡No has de saber, boba!... Háblame de allá, de la tierra nuestra. Tengo unas ganas atroces de que me cuenten de allí. Cuando salí era un tapón. Casi no me acuerdo.\"},{\"heading\":false,\"text\":\"Al oir nombrar la tierra, los ojos verdes de Esclava fulguraron en la obscuridad, como los de los gatos.\"},{\"heading\":false,\"text\":\"--¿No se acuerda nada, señorito?\"},{\"heading\":false,\"text\":\"--Te diré... Apurando la memoria, me parece que veo, así..., muchos campos verdes, y el mar muy alborotado y muy verde también... Ello es que si me acuerdo, es de un modo confuso. ¿Sabes lo que tengo más presente? Un marinero que me cogía en brazos para bañarme; á ese parece que le estoy viendo ahora mismo, más negro que la brea, y apestando á sardina.\"},{\"heading\":false,\"text\":\"--¿Y por qué no va allá á ver otra vez todo aquello?\"},{\"heading\":false,\"text\":\"--Este año, ó poco he de poder, ó he de convencer á mamá de que vaya. Pasaremos por Marineda y Compostela. Veremos la provincia de Pontevedra y la de Orense. Nos atracaremos de ostras y de langosta fresca. ¡Allí sí que sabrá á gloria! Te llevaremos. Ya verás.\"},{\"heading\":false,\"text\":\"--¿A mí?--articuló la muchacha meneando la cabeza.--A mí, ya verá como no.\"},{\"heading\":false,\"text\":\"--¿Por qué, tonta?\"},{\"heading\":false,\"text\":\"--Cuando se me pone una cosa en el corazón, acierto siempre; y se me ha puesto que ver no veo más la tierra.\"},{\"heading\":false,\"text\":\"--¡Anda, pájaro de mal agüero! Déjame salir del aprieto de los exámenes... y después... ¿Conque la tierra es muy bonita? Cuenta, cuenta. ¿Cómo es? Aseguran que es la más linda de todas las de España.\"},{\"heading\":false,\"text\":\"--Y de las del mundo todo, ya se lo dije--contestó con gran persuasión Esclavitud.--Si viese las rías de Pontevedra... quedaba lelo. ¡Si viese echar el cedazo de la sardina!\"},{\"heading\":false,\"text\":\"--Será precioso. Ya me estás abriendo el apetito. ¿Y las romerías, con su tamboril y su gaita?\"},{\"heading\":false,\"text\":\"--Vale más una fiesta de aquellas--aseguró muy formal la chica--que todas las diversiones de Madrid. Yo allá era bien alegre, y todos los domingos bailaba: aquí parece que se me ha caído la paletilla.\"},{\"heading\":false,\"text\":\"--¿Y qué es eso de la paletilla? Sepamos.\"},{\"heading\":false,\"text\":\"--Un hueso que tenemos en semejante parte--respondió señalando al pecho--que cuando se cae es como si le cayese á uno el alma: se va uno quedando mustio, mustio... vamos, así, muy triste, y amarillo, y sin voluntad de comer, hasta que después de algún tiempo, si no se la levantan á uno, se muere.\"},{\"heading\":false,\"text\":\"--¿Tú crees en eso, chica?\"},{\"heading\":false,\"text\":\"--Si es la verdad. Algunas personas dicen que todo lo de la paletilla es una brujería; pero yo he visto ya dos ó tres que se fueron al otro mundo, por no querer que se la levantasen.\"},{\"heading\":false,\"text\":\"--Pues Suriña, á veces parece que también se me ha caído á mí la paletilla dichosa, porque paso esplines y se me quitan las ganas de probar bocado. Tengo metido en la cabeza que así que vaya á la terriña me pondré magnífico, hecho un animal de gordo..., así.--Al decirlo inflaba los carrillos, para demostrar cómo pensaba ponerse.--Aquí siempre seré un fideo. Esta vida no es para echar buen pelo, no. Cuenta, anda, cuéntame de allá.\"},{\"heading\":false,\"text\":\"Esclavitud obedeció y empezó á contar sin orden ni genio descriptivo alguno, pormenores que, mejor que á la tierra, se referían á su biografía propia. «Siendo yo chiquilla, ocurrió esto y aquello... Una tarde que salí yo en Marín á la pesca de las xardas... Cuando yo aprendía á hacer encajes con los palillos... Un día que cocíamos la hornada en nuestro horno...» Esta misma personalidad de la narración le prestaba singular encanto para Rogelio. Al hablar la muchacha, parecióle que sus desvanecidos recuerdos infantiles tomaban cuerpo, se destacaban, y se le aparecían claros y distintos. El cuarto se llenaba de olores de campo, á menta, á anís, á hierba recién segada. La ilusión fué tan fuerte que arrimó á sí la cabeza de Esclava y la olió.--«Hueles no sé á qué... así como á flores, á aldea». Mientras la chica hablaba, se le ponía á él entre ceja y ceja, más fuerte que nunca, el capricho de ir _allá_. «Si no voy allá, no soy nunca hombre. Es lo primerito que he de pedirle á mamá cuando se levante. Es una rareza no haber ido ya á veranear allí, en vez de aquel San Sebastián, tan apestoso y con tanto gentío. En sentando los piés en la terriña, doblo y me pongo lo mismo que un becerro bravo.»\"},{\"heading\":false,\"text\":\"--¡Ay señorito!--murmuraba la voz de Esclavitud--¡qué fea y qué seca me pareció toda esa tierra que se pasa para venir aquí! ¡Jesús, María! Ni un triste árbol, ni un regato, ni una mata verde... ¿Cómo viven los labradores ahí?\"},{\"heading\":false,\"text\":\"--Mejor que allá, infeliz. Esta es la tierra que da el pan y el vino, mujer.\"},{\"heading\":false,\"text\":\"--¡Mi madre querida! En esa secura parece increíble que contenta esté la gente. Luego ¡faltarles la vista del mar! Cuando uno ve el mar, mismamente parece que ve la grandeza de Dios. ¿No es cierto que sólo Dios podía hacer aquella cosa tan grandísima? ¡Y lo que sale de él! ¡Aquellas conchitas tan monas; tantísimas clases de pescados; la sardina, que es el mantenimiento de los pobres!\"},{\"heading\":false,\"text\":\"--Hablas como un libro, Esclavita. No me extraña que diga tu apasionado Nuño Rasura...\"},{\"heading\":false,\"text\":\"--¿Quién?\"},{\"heading\":false,\"text\":\"--El señor de Febrero, mujer...\"},{\"heading\":false,\"text\":\"--¿El ancianito de la muleta?\"},{\"heading\":false,\"text\":\"--Ese... Pues dice que tú eres un tesoro. Has de saber que está muerto por ti.\"},{\"heading\":false,\"text\":\"--¡Bah!... No haga burla.\"},{\"heading\":false,\"text\":\"--De veras. Como que quiere llevarte consigo á su casa. Se cree que acabará por ofrecerte su blanca mano y su pata coja. Ha concebido por ti una insensata pasión, que le arrastrará al sepulcro en la flor de sus años, en la risueña edad de las ilusiones, á los ochenta y seis abriles no cumplidos.\"},{\"heading\":false,\"text\":\"--Bueno, bueno... Malpocado de señor, ni con sus piernas puede.\"},{\"heading\":false,\"text\":\"--Calla, ingrata mujer, ó mejor dicho, hipócrita. Nada conseguirás con disimular la profunda impresión que han hecho en ti sus rizados cabellos...\"},{\"heading\":false,\"text\":\"--Sí, de difunto--observó humorísticamente la muchacha.\"},{\"heading\":false,\"text\":\"--Las perlas de su dentadura, y la esbeltez de su talle. Pero no te compongas, infiel, que yo no te permitiré seguir á ese Tenorio. No harás traición á tus deberes, ó morirás á mis manos. Te arrancaré el corazón si me vendes.\"},{\"heading\":false,\"text\":\"Le deshizo cariñosamente las conchas del pelo, y murmuró bajito:\"},{\"heading\":false,\"text\":\"--Suriña no se va con el viejo. Suriña es para mí. ¿Quién se la quería llevar? Que se limpien, que se limpien. Suriña es mía.\"}]},{\"title\":\"Morriña — capítulo XVII\",\"blocks\":[{\"heading\":false,\"text\":\"Doña Aurora se encontró tan aliviada el día siguiente, que ya pudo levantarse un par de horas, y á la noche insistió y porfió en que su hijo no se quedase en el cuarto. «No me conviene», advirtió. «Te acuestas ni desnudo ni vestido; tardas en dormir; te entra el aburrimiento; te pones de palique con Esclavitud, que bien os oí anoche entre sueños, y luego amaneces desemblantado y desganado». Cuando la señora hablaba así, andaba la muchacha por el cuarto arreglando no sé qué cosas, y se volvió de espaldas precipitadamente, sin duda para recoger mejor la abrazadera caída de una cortina, operación en que se entretuvo bastante tiempo. En cuanto al estudiante, clavó en su madre los ojos, sobrecogido; pero aquella querida fisonomía, tan poco avezada á disimular sus impresiones y tan conocida para él en sus menores repliegues, no expresaba nada más que lo que en voz alta habían proferido los labios, y el estudiante, respirando mejor, accedió á retirarse á su cuarto aquella noche. No dejaba su madre de llevar razón asegurando que le faltaba sueño. En la edad del pleno desarrollo, no robustecido aún después de una niñez si no precisamente enfermiza, al menos delicada, su fina organización se resentía de cualquier cosa, y las tres noches de media vela le traían ya algo lacio. Sin embargo, al recogerse á su alcobita, experimentó una impresión de pena y de soledad. Acostumbrado á una atmósfera de ternura y de mimos, á andar envuelto en algodón en rama, era codicioso de cariño, y bastáranle dos días para contraer el hábito de aquellos tiernos y extraños coloquios, á deshora, con una mujer que le ofrecía tal cantidad de afecto y de adhesión, que ni su propia madre, al parecer, derramaba más profusamente el amor sobre su cabeza. Si Rogelio pudiese analizar al microscopio sus sentimientos, vería que buena parte del encanto de Esclavitud consistía en que allí él era quien mandaba, y que la mujer de veinticinco años que al pronto le tuvo por un chiquilicuatro, un _rapaz_, ahora estaba á sus órdenes, sumisa, como _esclava_ verdadera. Con la madre, por más amante y tierna que fuese, Rogelio siempre se reconocía súbdito: la costumbre de respetar y obedecer se le imponía, manteniéndole en perpetua infancia. Con la doncella, podía en cambio satisfacer su pueril vanidad y á la vez su oculto y mal definido anhelo de vestir la toga viril, atributo de la dignidad humana.\"},{\"heading\":false,\"text\":\"Por eso le causó gran disgusto la interrupción de veladas tan sabrosas. A punto estuvo de escurrirse de puntillas á eso de la una, y sorprender á _Suriña_, para alegrarle aquella cara que se le había puesto de una legua. Pero ¿y si los cogía su madre? Creería todas las cosas malas; tendría una desazón horrible; recaería; acaso despacharía á Esclavitud... El instinto de cautela, que en los movimientos pasionales se despierta como contrapeso á la fiebre de las determinaciones radicales y de los insensatos extremos, le aconsejó cierto tino; y al otro día, como viese á Esclavitud descolorida y con las facciones afiladas, la acorraló en un rincón del pasillo, y la dijo entre bromas y veras: «Suriña, no me pongas esa cara de viernes. Esta noche me acordé mucho de ti, y de nuestra charla. Se me pasaban ganas de ir, pero no me atreví. Cuidadito, por causa de la pobre mamá. Anda, Esclava, sonríe á tu señor.»\"},{\"heading\":false,\"text\":\"Bastó esta pequeña satisfacción para que la muchacha apareciese con mejor semblante, y aun se manifestase en apariencia contenta y segura. Rogelio había hecho su composición de lugar, mitad por instinto de prudencia, mitad por filial respeto: «Ahora, que sane mamá del todo: que se reponga: á eso estamos. Mientras no se consiga verla fuerte y buena, que Esclavitud la cuide, y se acabó. Pero mamá se encuentra muy aliviada, y va á entrar en convalecencia: dentro de ocho ó diez días no quedará rastro del percance. Entonces tenemos tiempo de echar todos los paliques que se nos antoje. Porque mamá sale á la calle, ó se entretiene con su tertulia, y... perfectamente. Se lo he de decir á Sura para que se ponga más alegre todavía.»\"},{\"heading\":false,\"text\":\"Atisbó la ocasión propicia de comunicarle este agradable proyecto. Sujeta incesantemente en el cuarto de la enferma, Esclavitud aquellos días no pisaba el del estudiante: era preciso tomar por centro de operaciones el pasillo, y Rogelio se propuso esperar á la chica en él por la tarde, pues la mañana se le iba entre almuerzo y cátedras. Hacia eso de las cuatro, el entrar y salir de los amigos en la tertulia introducía en la casa cierta animación y desorden favorables al intento de Rogelio. Y la tertulia aquellas tardes se encontraba muy concurrida, porque el género de enfermedad de la señora, no incompatible con la charla y la bulla, imponía á sus amigos el deber de acompañarla. No sólo venían los «señores» sino también el personal femenino, compuesto casi todo de modestas amas de casa, que por carecer de la desahogada fortuna de doña Aurora, sólo de tarde en tarde podían permitirse el lujo de hacer visitas, no sin meditarlo antes á fin de darse á luz con la decencia conveniente en la familia de un magistrado. Aquella tarde vinieron dos señoras que acostumbraban dejarse ver muy poco: la del presidente de Sala D. Prudencio Rojas, y la del ex-Fiscal D. Nicanor Candás, por mal nombre Laín Calvo. Si un pintor quisiese simbolizar la Dignidad envuelta en los cendales de la Modestia, bastábale copiar fielmente el porte y rasgos de la señora de Rojas. Para quien no tuviese el alma dañada y torcida, ó embotada la sensibilidad, había algo en aquella mujer sencilla, socialmente insignificante, que obligaba con categórico mandato á inclinarse y descubrirse. En su abriguito de terciopelo negro ya raído, escrupulosamente limpio, trabajosamente puesto al aire de la moda después de ocho ó diez arreglos quizá; en su capota cuyos encajes descubrían el brillo de la plancha casera; en sus guantes nuevos, comprados para la circunstancia, de dos botones no más, de color sufrido y obscuro; en sus aretes antiguos,--una roseta de minúsculos diamantes;--en sus blancos cabellos, alisados y pegados á las sienes con el supremo decoro de una reina viuda que ha renunciado á agradar, se revelaba más valor, más sufrimiento, más secreto heroismo que en los harapos de ningún pordiosero, ni en el uniforme de ningún inválido, ni en el sayal de ninguna monja. El viviente comentario y tal vez la mejor clave de la rígida integridad del marido, era la aureola de paciencia doméstica y de serena aceptación del sacrificio cotidiano que resplandecía en la esposa. Lo que tenía Rojas de duro y leñoso en su modo de entender y rendir estrictamente la justicia, lo suavizaba la dulzura de su mujer, á quien Roma hubiese conferido el cargo de sacerdotisa de la piedad doméstica. Aquella matrona no había preguntado jamás, ni aun á sí misma, la razón de que su vida conyugal fuese un continuado acto de abnegación que duraba ya treinta y tantos años: sabía que en su casa se adoraba el inflexible simulacro del Deber poniendo en el mismo altar la estatua sobredorada de la Decencia, y sin una protesta se había consagrado al culto de ambos númenes.\"},{\"heading\":false,\"text\":\"No cabía mayor contraste que el de la señora de Rojas y la de Candás. Como en la magistratura se tienen muy en cuenta los antecedentes de familia, no es posible dudar que una esposa tan cursi, que según malas lenguas había sido posadera en Gijón, influía bastante en ciertas sombras que un tiempo empañaron el buen nombre del Fiscal, y era motivo para que sus compañeros, molestados por tener que seguir trato con ella, mirasen á su esposo con una prevención que crecía al fijarse en la incorregible mordacidad, burlón escepticismo y sordera intermitente del asturiano. La señora de Candás, gordinflona, con una lupia al margen del ojo izquierdo, muy empavesada, luciendo siempre vestidos llenos de faralaes y capotas que parecían garitas ó peroles, hablando medio en bable, llamando á su marido _este_, y contando delante de cualquiera indisposiciones propias para sepultadas en el silencio más profundo, era el tipo perfecto de la ordinariez incurable, enquistada, que resiste al buen ejemplo, al aire de la corte, al cáustico de la burla y al roce de la corriente del tiempo, que desgasta y pule, como la del mar, las piedras más toscas. Si Don Nicanor probó alguna vez á civilizar á su costilla, seguramente había renunciado á ello muchos años hace; y además, los compañeros aseguraban que para desasnar á Pachita tenía que empezar Don Nicanor por darse una mano de barniz á sí propio, y suprimir las crudezas de su conversación, el desentono de sus modales y el mal gusto de sus opiniones,--porque hasta las opiniones eran de mal gusto en el Fiscal, ó al menos lo parecían por la forma de expresarlas.\"},{\"heading\":false,\"text\":\"Lo evidente es que, encontrárase ó no al nivel de su Pachita,--y acaso sólo le llevaba de ventaja la agudeza del ingenio y la superioridad de la instrucción masculina,--Don Nicanor se mostraba á veces como avergonzado de su mitad. Quien se apostase aquel día en casa de doña Aurora y viese entrar primero al señor de Rojas y luego al señor de Candás en compañía de sus respectivas mujeres, podría, sólo con aquella observación, deducir la vida psíquica de ambas parejas y ambos hogares. Rojas había ofrecido á su mujer el brazo por la escalera, adelantándose á tirar de la campanilla; y, al cruzar la puerta, se hizo atrás cortésmente, no sin llegar después á tiempo de alzar el portier del comedor (donde ya había vuelto á instalarse la tertulia). En el modo de colocarse á su lado, en el de asociarse á sus protestas de interés por la salud de la madre de Rogelio, rebosaba la misma consideración, el mismo delicado sentimiento de reverencia familiar, si así puede decirse; y el magistrado, respetando á su compañera, mostraba respetarse á sí mismo. El señor de Candás, al contrario, entró con el sanfasón de todos los días, y por poco suelta á su mujer en el mismo rincón en que había colocado el paraguas. Parecía como si Pachita y su esposo se hubiesen encontrado por casualidad en la escalera, sin conocerse, ni haber sido presentados. Pero hubo más. Mientras el señor de Rojas, conversando en igual tono deferente con su mujer que con doña Aurora, no se movió del asiento hasta que la señora de Rojas hizo la clásica indicación, «cuando quieras, Prudencio, nos iremos hacia casa», el señor de Candás, de repente y cortando una arenga de Pacha sobre lo rancio y caro que era en Madrid el _tocín_, dijo con el peor estilo del mundo:\"},{\"heading\":false,\"text\":\"--Ea, Pacha, cállate y larguémonos, que es hora.\"},{\"heading\":false,\"text\":\"Salía el señor de Candás, sin duda para enseñar el camino á su mujer, que aún quedaba empantanada en los cumplimientos de despedida, á tiempo de espantar un grupo de dos personas que hacia el fondo del recibimiento se secreteaban con calor. Nadie ganaba al socarrón del astur en el arte de hacerse el sueco; pero ver... ¡carapuche si vió! Tanto, que al salir de la casa aún retozaba una risilla en las arrugas de su volteriana faz.\"},{\"heading\":false,\"text\":\"Lo que Rogelio le decía con tanto entusiasmo á la muchacha era esto:\"},{\"heading\":false,\"text\":\"--Suriña, la gran noticia. Este verano iremos allá... todos. Ya mamá me lo tiene ofrecido.\"}]},{\"title\":\"Morriña — capítulo XVIII\",\"blocks\":[{\"heading\":false,\"text\":\"Encontrábase la señora de Pardiñas completamente dada de alta y se discutía la oportunidad de una salida á pié, cuando cierta mañana, á la hora en que Rogelio tenía su clase de economía política, que para tales visitas era deshora, llegó Don Nicanor muy bien humorado y cordialísimo. Se hizo el sorprendido de no encontrar allí á ninguno de los acostumbrados tertulianos; á lo cual doña Aurora, que se consagraba á la fabricación de unas medias de abrigo, respondió muy cuerdamente que faltaban dos horas lo menos para la de la tertulia, y por consiguiente no tenía nada de extraño que la gente no hubiese llegado. Pero Laín Calvo no debió de oir esta observación, porque conservaba en el bolsillo la trompetilla, limitándose á formar con la mano un embudo acústico.\"},{\"heading\":false,\"text\":\"--¿Diga, Aurora, no ha notado una cosa?--preguntó después de repantigarse en la butaca, sobre cuyo ancho respaldo estaba ya señalada la forma de sus lomos.\"},{\"heading\":false,\"text\":\"Doña Aurora levantó las pupilas como el que dice:--«No; es decir, ¿yo qué sé? Haga V. él favor de explicarse».\"},{\"heading\":false,\"text\":\"--¿No se ha fijado el otro día... cuando vinimos de visita Pacha y yo...\"},{\"heading\":false,\"text\":\"--Sí, sí; ya... el viernes.\"},{\"heading\":false,\"text\":\"--¿La mujer de Rojas, qué abatida estaba?\"},{\"heading\":false,\"text\":\"--¡La pobre! No es muy animada nunca; pero tampoco se la ve displicente. ¡Mujer de más mérito! Vale un Perú.\"},{\"heading\":false,\"text\":\"--No, ella bien se esforzaba en hacer de tripas corazón: ¡pero se le conocía! Sobre todo, los que estábamos en autos.\"},{\"heading\":false,\"text\":\"--¿Pues qué ha pasado? ¿Tienen algún disgusto serio?--preguntó ya consternada la señora de Pardiñas, que estimaba y quería muy de verdad á la de Rojas.\"},{\"heading\":false,\"text\":\"--El Joaquín... el hijo, el juez... me le han vuelto á trasladar desde un extremo á otro de España, á los dos meses de la primera traslación, y estando su señora para dar á luz. Así se convencerán de que aquí no se puede hacer el quijote, ¡carapuche! ¡Mire que un rapaz que empieza la carrera, y para estreno se le ocurre tenérselas tiesas con un alto cacique de las agallas de Colmenar, á quien le guarda las espaldas el ministro del ramo! Ya verá, ya verá que no se pueden gastar bromitas con esos nenes. Y ya comprenderá lo que importan aquí legalidades. ¿Que no se puede trasladar á los jueces más que á instancia suya? Pues se pone en la Real orden: «A instancia suya», y tan guapamente. Ya hubo alguno á quien le encajaron la cesantía «á instancia suya». Y cuando protestó le salieron con «¿V. desacata al ministro?»\"},{\"heading\":false,\"text\":\"--Pero señor Don Nicanor, eso honra mucho á la familia de Rojas, y al muchacho, que por lo visto es de la escuela de su padre. Gente íntegra así, se ve ya muy poca. Yo nada entiendo; pero recuerdo que aquí se hizo conversación del asunto, y se dijo que querían que Joaquín Rojas se prestase á una picardía tremenda, á un despojo que importaba...\"},{\"heading\":false,\"text\":\"--¡Mire V.--añadió Laín Calvo prosiguiendo en su sordera--que ir un mequetrefe como él á cuadrarse delante del Ministro! Los Rojas tienen vena. _Talis pater_... Farol el padre, farol el hijo... Es decir, el hijo todavía más farol, aunque parezca mentira. Porque el padre al menos no se mete en camisa de once varas: al texto de la ley y se acabó. ¿Que el Código dice blanco? Pues blanco. ¿Que dice negro? Negro. Rojas es una máquina de aplicar la ley. Si la ley hoy trajese azotes, y cortar las orejas, andaría Rojas desorejando y vapuleando á la gente. ¡Pero el chiquillo!... Porque se ha leído unas chapucerías alemanas é italianas, traducidas en gringo, se las echa de sabiondo y de fi-ló-so-fo. ¡Fi-ló-so-fo un xuez! ¡Home, qué farolería!\"},{\"heading\":false,\"text\":\"--Pues á mí,--arguyó doña Aurora sin alzar la voz, porque sabía á qué atenerse respecto á la sordera del Fiscal,--me parece que en todas las profesiones puede un hombre portarse con dignidad y con decencia. Les tengo á los Rojas, por eso, una simpatía grandísima.\"},{\"heading\":false,\"text\":\"--Y claro,--siguió Laín,--ahora lo de cuartos anda mal. En aquella casa ni se enciende estufa, ni se come principio, ni se hace café. No le llega el sueldo para traslaciones; se ha casado con una chica que no tiene un ochavo, y así que la cosa apremie, ya bajará el gallo el señorito. La necesidad enseña más que las Universidades. Ya le domarán. Como un guante estará dentro de un año.\"},{\"heading\":false,\"text\":\"Persuadida de que no conseguía nada con protestar, doña Aurora continuaba menguando el talón de su media, limitándose á hacer gestos negativos, porque su genio vivaracho no le consentía asentir á las atrocidades del maligno sordo.\"},{\"heading\":false,\"text\":\"--Todos allá cuando rapaces empezamos por echárnoslas de plancheta... ¡y luego amainamos, vaya si amainamos! O si no, es querer pasar una vida miserable. Ya verá V. como el ramalazo que ha cogido á Joaquín le alcanzará también á su padre. Se la están armando con queso. No pasa el año sin que le jueguen alguna de puño: gorda. ¿No pueden trasladarle? le jubilarán. Yo no soy antiguallero como Don Gaspar y los otros; pero tengo que reconocer que en mis tiempos la magistratura dependía menos que ahora de la política. Las cosas vienen así, y hay que tomarlas como vienen. Estos señores están siempre en Belén, carapuche. ¡Memos en polvo! A bien que la camada nueva la entiende mejor. Aquí soy yo el único de la tertulia que vive en el mundo. Si no fuese la arrenegada sordera...\"},{\"heading\":false,\"text\":\"--A mí no me venga V. con sorderas,--protestó la señora.--Dios me libre de sordos así. Oye V. más que quiere. A mí déjeme V. de cuentos ¿eh? No nací en el año de los tontos.\"},{\"heading\":false,\"text\":\"--Y el que está más chiflado de todos,--advirtió Laín haciéndose el desentendido,--es el bueno de Don Gaspar. Ese ya, guillati por completo. Ha vuelto á la infancia. Tendremos que ponerle ama de cría, ó al menos niñera. Eso quiere y por eso suspira; y anda buscando robarle á V. la que V. escogió para su chico. Hablo formal; tan cierto como me llamo Nicanor, que le tenemos vuelto tarumba por su doncella de V., por la Esclava ó como se llame. Ningún rapaz de veinte se enamoraría tan fuerte de ella; estoy seguro de que á Rogelín no le entró así, home.\"},{\"heading\":false,\"text\":\"Al nombre de Rogelio, y sobre todo al percibir el tono en que lo pronunciaba Candás, la madre se estremeció, dejando caer en el regazo la calceta.\"},{\"heading\":false,\"text\":\"--Lo de Rogelín,--continuó con la misma bonachonería el sordo,--es tan natural en un rapaz, que sería para hacerse cruces si no sucediese. Claro: una mujer agraciada de veinticinco, y mimosina; un rapaz de veinte... ¿qué había de pasar, señores? Que hoy te miro, que mañana te toco... que el cariñín en el pasillo, que el retozo en la antesala... Rapazadas que se caen de suyo.\"},{\"heading\":false,\"text\":\"La señora saltaba en el asiento lo mismo que un muñeco de resorte.\"},{\"heading\":false,\"text\":\"--¿V. sabe lo que está diciendo?--exclamaba.--¿Le parece á V. bien lanzar esas cosas tan serias _porque sí_, sin prueba ni fundamento ninguno? ¿No hay más que echar la lengua á paseo y caiga el que caiga? Rogelio... ¡infeliz criatura! ¡que no es capaz de semejantes trastadas en casa de su madre!...\"},{\"heading\":false,\"text\":\"--Bueno, si yo comprendo que V. le dé poca importancia y lo meta á risa, porque son demoniuras que la edad las trae consigo...; y por eso, cuando el otro día los pillé en la antesala muy entretenidos, hechos un caramelo, díjeles para mi saco: «Eso, niñines, á divertirse, que es ley de Dios.» Pero si pienso en el otro estafermo, con sus ochenta del pico, todo derretido en babas...: home, le bajaría los calzones y le daría una mano de azotes en el tafanario, por archimemo.\"},{\"heading\":false,\"text\":\"¡A doña Aurora sí que se le pasaban ganas vivísimas de ejecutar la misma operación con el empecatado sordo! ¡Contar aquellas enormidades, y contarlas de aquel modo traidor, que ni daba lugar á rectificaciones, porque con la farsa de la sordera podía decir cuanto se le antojase, sin atender á las razones en contra, ni aun á los mentís! Era para envenenarse la sangre de rabia... Era una burla supina, descarada, insufrible. ¿Y ella había de aguantarla? Eso sí que no. La bilis de la señora de Pardiñas se alborotaba: la sangre le hervía en las venas. «Sordo infame, sordo de mentirijillas, revoltoso y chismoso de verdad, raposa malvada y astuta, ahora te lo diré de misas.» Levantóse del sillón, y acercándose rápidamente á Laín Calvo, le metió la mano, con la destreza de un tomador de oficio, en el bolsillo del gabán, sacando el estuche que contenía la trompetilla. Y antes que el sorprendido Fiscal pudiese evitar el ataque, doña Aurora había sacado el cañuto de plata encajándolo en el conducto auditivo del asturiano, acercado la boca y gritado con toda su fuerza:\"},{\"heading\":false,\"text\":\"--Para mí póngase V. siempre la trompetilla, ó si no determínese á oir lo que le contesto. Eso de Rogelio y Esclava lo inventa V. con su maliciota condenada, ¿oye? Mi niño no seduce á las criadas de la casa de su madre, ¿oye? La gente no anda tan suelta ni tan descarada como V. la pinta, ¿oye, oye? Y las personas decentes se diferencian ¿oye? de los pillos. Y yo no soy tan borrica ¿oye bien? que si semejantes cosazas me pasasen por delante de las narices las fuese á consentir. Y á mí me gusta poco la gente maligna ¿oye? porque siempre echo la cuenta ¿oye? «Piensa el ladrón que todos lo son.»\"},{\"heading\":false,\"text\":\"Acabada la filípica, la señora se dejó caer toda sofocada y nerviosa en el sofá: y el astur, llevándose ambas manos á su amarillenta calva, exclamó con acento dolorido:\"},{\"heading\":false,\"text\":\"--Carapuche, Aurorina... Me ha roto el tímpano... Con otra como ésta me deja sordo.\"}]},{\"title\":\"Morriña — capítulo XIX\",\"blocks\":[{\"heading\":false,\"text\":\"Pero apenas el truhán de Laín Calvo se hubo ido, y calmádose un poco la indignación y la cólera dando lugar á la reflexión, doña Aurora, ejecutando su movimiento favorito de rascarse el moño con una aguja de la calceta, llegó á formular categóricamente el indefectible «¿por qué no?» de todas las desconfianzas. Sin necesidad de gran perspicacia, sin poseer la aguda malicia del Fiscal, con sólo las nociones más elementales del sentido común, bien podía venirse á la memoria é imponerse al entendimiento todo aquello de «el fuego junto á la estopa...», con lo otro de «entre santa y santo...», etcétera. Y por una serie natural de razonamientos, propios de su buen sentido, llegó la señora á caer en el extremo contrario á su primer impulso, acusándose de confiada en demasía, de necia y simple, porque ni una sola vez se le había ocurrido la posibilidad y aun la probabilidad de cosa tan obvia, hasta que se la indicara una persona maliciosa y extraña, cuando ella tenía obligación de precaverla á tiempo. «Las mamás padecemos esta pícara manía, de pensar que los niños siempre han de ser niños... y los años vuelan, y ellos llegan á hombres, y el bigote no nos pide permiso para crecer... Cuando no creemos que siguen siendo chiquillos, damos en figurarnos que ya son viejos y formales como nosotros..., otro imposible, otra bobada... La edad pide lo suyo, y es una majadería no sospecharlo siquiera... Lo malo aquí es que tenemos al enemigo en la plaza. ¡Y lo he metido yo misma! Nada, le abrí la puerta y le dije:--Pase V. Sobre que la situación es poco decente, desairadísima para mí, he duplicado el peligro y la gravedad de todas las consecuencias que pueden sobrevenir... ¡y tanto como pueden! Ello es que yo no esperé nunca que Rogelio fuese toda, toda la vida un santo; pero esto... así, á domicilio...»\"},{\"heading\":false,\"text\":\"Otra rascadura en el moño le sugería el contrapeso lógico de tales reflexiones. «Es muy creíble que el tiñoso del viejo haya calumniado, por el gusto de calumniar, á mi nene y á la pobre Esclava. Yo no tengo tan mal ojo para conocer á las pájaras de cuenta, y Esclava me gustó, me llenó precisamente por su tipo formal y modesto. Verdad que los antecedentes de familia no la abonan, y que tiene mala sangre por los cuatro costados; pero eso... en eso se lleva uno chascos grandísimos: la gente no es como los pimientos, que salen gordos ó ruines según la semilla. Nada, aquí no tenemos sino un caminito que seguir. Observar, no dormirnos y procurar que el muchacho se distraiga por ahí fuera. Según lo que vaya pescando, así haré. Yo no voy á cometer la barbaridad de echar á la chica de buenas á primeras. Si todo ello resultase paparrucha de Don Nicanor, sería un cargo de alma. Y si es verdad, podía alborotárseme el chico... y tendríamos una... Estas primeras chifladuras y tonterías de los rapaces les entran muy fuerte. Andarse con tiento. Aurora, figúrate que eres de policía y que te mandan seguir la pista de un crimen... Ojo alerta, calma y mala intención.»\"},{\"heading\":false,\"text\":\"Ningún programa se cumplió más al pié de la letra. Dedicóse la señora desde aquel mismo instante á reparar el tiempo perdido: tan confiada y noblota como fué antes de concebir recelo alguno, tan suspicaz y escamona se volvió desde que la sospecha vino á hacerle cosquillas con sus dedos rápidos y fríos. Espiaba con destreza y con un sosiego perfecto, sin dejar salir al exterior las preocupaciones del ánimo. En toda mujer, en la más sencilla y franca, hay un polizonte en germen; los hábitos de disimulo contraídos desde la niñez les hacen fácil el oficio.\"},{\"heading\":false,\"text\":\"Para no alarmar ni poner sobre aviso, discurrió doña Aurora no vigilar á los dos presuntos culpables, sino á uno solo: porque si éste comunicaba al otro sus temores respecto al espionaje, el otro los disiparía asegurando no haber notado cosa alguna que alarmar debiese. Y en efecto, en el presente caso no puede negarse que, vigilada Esclavitud, sobraba atisbar á Rogelio. Así se practicó. La señora, usando de un derecho indiscutible, estudió minuto por minuto las acciones, pasos y movimientos de su criada. Supo á qué hora se despertaba; qué hacía después de levantarse; cuántas veces y con qué fin entraba en el cuarto de Rogelio; en qué empleaba la tarde; á qué se dedicaba mientras duraba la tertulia; cuándo se recogía y en qué momento soplaba la luz. Y,--preciso es confesarlo,--al pronto el resultado de estas averiguaciones fué completamente negativo. Esclavitud, no bien salía de su cuarto, se consagraba como siempre á los chocolates, y después á su aseo personal, sin acicalarse ni hacerse esos moños de figura de sorbete, único lujo de las domésticas madrileñas. Para arreglar y asear las habitaciones de Rogelio, despachito y alcoba, escogía las horas que el estudiante pasaba en clase, ó en paseo: nunca iba estando él. Esclavitud no salía los domingos sino á misa; por consiguiente, tampoco veía á Rogelio fuera de casa. Durante la tertulia, Rogelio no se movía de su rincón del sofá, ni la muchacha abandonaba su cesta de repaso, excepto para abrir la puerta. Y las noches, en que á no venir algún estudiante amigote de Rogelio, éste leía periódicos ó salía á los teatrillos á ver una pieza, Esclavitud se las pasaba en su cuarto, cosiéndose su propia ropa, ó dedicándose á faenas análogas. Nada se descubría que pudiese dar pábulo á ciertos recelos, y la señora se dormiría tranquilamente, si sus condiciones de observadora fuesen más vulgares.\"},{\"heading\":false,\"text\":\"Pero no era ella mujer á quien se le pasasen por alto varias cosillas insignificantes en apariencia, y en realidad muy significativas y aun escamativas para una mamá avispada; cabos sueltos tras los cuales suele salir toda una madeja larga y enredadísima. Estos indicios, señales ó guiones para las pesquisas de la celosa madre, eran del género siguiente. A la hora de almorzar, al traer Esclava las píldoras ó el jarabe ferruginoso, al presentar á Rogelio sus manjares preferidos, establecíase alguna vez (y que no se lo negasen á doña Aurora, que ella bien lo había guipado) un trueque de miradas lánguidas de _carnero á medio morir_, ó encendidas y chispeantes. Al llamar el estudiante á la campanilla y levantarse Esclavitud para abrir la puerta, la muchacha mostraba un apresuramiento que estaba muy lejos de manifestar cuando tiraban del cordón los vejestorios tertulianos; es evidente que conocía al señorito en el modo de llamar y hasta de subir las escaleras. Si Esclavitud planchaba ropa de Rogelio, hacíalo con primor y esmero muy especiales; y este mismo síntoma podía advertirse en el arreglo de la habitación y en el servicio de la mesa. Algunas noches, al salir de casa Rogelio, la muchacha le esperaba en el pasillo, y trocaban breves frases, pero en voz tan baja que no podía oirse el diálogo: esto mismo ocurría por la mañana al regresar de clase, y siempre que no estuviese en la antesala doña Aurora. Por último, y este indicio era de los más elocuentes, Rogelio se había resistido dos ó tres veces á acompañar á su madre para salir, y aunque por fin cedía, iba asaz mohino y con las orejas gachas.\"},{\"heading\":false,\"text\":\"Ni más ni menos que esto percibió la señora: ello bastaba y aun sobraba quizá para tenerla en ascuas ó inspirarla deseos de resolver del mejor modo posible aquella ambigua situación y desenredar la madejita, que amenazaba ser con el tiempo un enredo de dos mil diablos. No se atrevía á moverse de casa por no facilitar ocasiones peligrosas; pero esto puede hacerse un día, dos, tres; no prolongarse todo un invierno, á menos de criar moho. Rogelio había manifestado ya repetidas veces gran extrañeza viendo suprimidas las correrías matinales en simón. «Máter, estamos abocados á presenciar graves trastornos si continúa tu retraimiento y sigues desdeñando á las áureas carrozas que al pié de los muros de nuestro palacio esperan que te recuestes muellemente en sus recamadas alcatifas para dedicarte á tus matutinos quehaceres. Prepárase imponente manifestación en que tomarán parte diez mil Faetontes de punto; pronunciáranse discursos en la dulce lengua del trovador Macías y en la jerga elocuente del duque Pelayo. Tienen pedida la palabra Martín el Buloniu y José el Cabaleiro. El Gobierno ha adoptado precauciones, y el duelo se despedirá en la taberna.»\"},{\"heading\":false,\"text\":\"Los tertulianos, informados del retraimiento de la señora, también se creían obligados á soltar su discurso de higiene. «Amiga doña Aurora, no hay que apoltronarse. Cuidadito con criar humores, que después dan que sentir. Míreme V. á mí: la salud de que gozo y la buena disposición en que me encuentro, las debo á mi costumbre de que no pase día sin salir y sin andar á pié regulares distancias. Menos de una legüecita, no se esparce la sangre. Yo, desde que me rompí el hueso, ando más.» Estos consejos eran del excelente Nuño Rasura. «Muy conveniente considero el ejercicio», añadía el señor de Rojas, con su sentenciosa formalidad de costumbre, «para el cuerpo, y si Vds. me apuran, para el alma. Andando, se distrae... vamos, el espíritu. No hay como un paseíto, y si uno se aburre, lo mejor que puede hacer es contar las piedras, los árboles ó los números de las casas.» A doña Aurora, tales advertencias acababan por sacarla de tino. «Es monomanía la que tiene todo el mundo de aconsejar y de cuidarle á uno, sin saber ni lo que le conviene ni dónde le aprieta á uno el zapato. Estos señores parece que se empeñan en que aquí suceda... lo que no debe suceder. Vaya, con razón dice aquel truchimán de Don Nicanor que están en Babia todos ellos.»\"},{\"heading\":false,\"text\":\"No obstante, doña Aurora iba persuadiéndose de que la encerrona era insostenible, y la irritaba pensar que tal vez se tomaba un trabajo excusado, porque la inclinación de los muchachos no llegaba á extremo que justificase tantas precauciones; y de llegar, el impedirles que se viesen á solas era como poner puertas al campo. Ocurriósele entonces un expediente para salir de dudas y medir la magnitud del riesgo. Mandó fabricar secretamente un llavín para la puerta de su piso; y ya provista de él, salió á la calle de mañana en uno de sus trenes, el de Martín por más señas; y despidiéndolo al poco rato, volvió á su casa á pié, abrió sin hacer ruido, y se dirigió, pisando blandamente, al cuarto-leonera, donde supuso que debía encontrarse Esclavitud. Así era. La halló haciendo labor, como de costumbre, tranquila, con el aire reconcentrado y pensativo que la caracterizaba.\"},{\"heading\":false,\"text\":\"--¿Dónde está el señorito?--preguntó doña Aurora de súbito, sin dar tiempo para que la Esclava adoptase precaución alguna.\"},{\"heading\":false,\"text\":\"Y la criada, alzando el rostro sereno, ó más bien melancólico, respondió:\"},{\"heading\":false,\"text\":\"--Me parece que estudiando en su cuarto ¿Cómo entró, señora? No he sentido la campanilla.\"},{\"heading\":false,\"text\":\"--Es que salía Fausta--explicó doña Aurora atropelladamente, cogida en el garlito lo mismo que si fuese ella la culpable. Hasta sintió encendérsele los carrillos. ¡Aquello era lo que se llama un parchazo! ¡Tantos misterios y tantos preparativos de llavín, para encontrarse con que en casa no sucedía nada de particular, y que cuando pensó sorprender un pecaminoso coloquio, sólo encontraba la calma y el orden! Y sin embargo, no se convencía, no señor: que se convenciese el diablo. «¿Será esta chica más lagarta de lo que me figuro? ¿Me estará envolviendo sin yo pensarlo? ¿Se reirán de mí los dos? Porque las miraditas y los coloquios al entrar y salir, y las pocas ganas que tiene mi niño de echarse á la calle... eso no me lo quita nadie de aquí; lo he visto, y lo que veo... nada, que lo veo, y ya pueden predicarme después frailes descalzos. Con salirme fallida esta emboscada, en vez de sosegarme creo me voy sobresaltando muchísimo más. No, pues yo no me dejo meter el dedo en la boca. Para defender á mi hijo, todos los medios humanos he de apurar; á mí no me cogen desprevenida: por si ó por no... Me da miedo esta muchacha. La veo yo así..., no sé cómo, pero no me gusta. Tiene un carácter muy de allá, que todo se lo guarda, y no hay nunca seguridad con ella, porque no se descubre. Pues á pillo, pillo y medio. Deja, deja, que yo te buscaré la salida; y ha de ser salida decorosa, sin que te puedas quejar; al contrario, has de tener que darte por satisfecha. Y ahora..., un clavo saca otro clavo, los rapaces son rapaces... Voy á proporcionarle entretenimiento á Rogeliño. Voy á darte una rival... y bien bonita. Espérate, rapaza...: contra treta, retreta; ya encontré quien ha de desbancarte.»\"}]},{\"title\":\"Morriña — capítulo XX\",\"blocks\":[{\"heading\":false,\"text\":\"Y en efecto, ni veinticuatro horas tardó la madre en arreglarle á su hijo una entrevista con la rival de Esclavitud. El punto de cita fué en la propia morada de la susodicha rival, morada obscura y que olía medianamente, como suelen oler todas las habitaciones de gente de su laya; por lo cual, para que Rogelio se enterase bien del talle y porte de su nuevo quebradero de cabeza, hubo que sacarle al patio sin ningún artificio de coquetería, y aun pudiéramos decir que en estado de casi total desnudez, pues no cubría sus esbeltas formas sino una manta vieja que el dueño del taller de coches, Agustín Cuero, se apresuró á levantar á fin de que nada velase sus encantos.\"},{\"heading\":false,\"text\":\"Era una monada de jaca andaluza, alazana con cabes negros, de cabeza chica y enjuta, de nerviosos remos, de lucio y acopado casco, de pelo irisado á fuerza de estar brillante, de entreabiertas fosas nasales más suaves que la seda, de ojo lleno de fuego y dulzura; joven, leal, gallarda, animosa; un animal de esos que honran á la raza caballar española con la hermosura de su estampa y la inteligente generosidad de su carácter. Agustín Cuero no le escaseó elogios hiperbólicos, fingiendo que se enternecía al desprenderse de tan rica pieza.\"},{\"heading\":false,\"text\":\"--Le aseguro á la señora que otra más bonita no se pasea hoy por la Castellana. No tiene una maca siquiera. Y es una santa, es una seda, la maneja un niño de pecho. Con toda la sangre que le sobra, no es capaz de una mala partida. Así es que un hombre le toma ley, vamos, y parece que cuando uno la vende es como si se le llevasen á alguien, es un decir, de la familia.\"},{\"heading\":false,\"text\":\"--Sí--respondió la señora metiéndose á chalana--pero también no me negará V. que esta clase de caballos no está ahora de moda. Los elegantes tienen una legua de pescuezo y son de figura de mondadientes.\"},{\"heading\":false,\"text\":\"--Bueno, los ingleses...; una moda _redícula_, como muchas que hay; y esos son para ciertos señoritos y con ciertas circunstancias... pues. Para el Hipódromo y esas farsas. Una jaca como la que está viendo la señora siempre tendrá partido. Bien emperrado que anda el _Baraterín_ en comprármela; en pleito estamos porque no quiere llegar al precio que yo le pongo. Ahí el señorito podrá decirlo.\"},{\"heading\":false,\"text\":\"--Es verdad, mamá--afirmó Rogelio mientras halagaba el anca de raso del simpático animal.--Soy testigo. Agustín le pidió lo mismo que á ti, y el torero la dejó quedar por diferencia de dos onzas, y está chalado por ella. La anda rondando; ¡le hace más visitas!\"},{\"heading\":false,\"text\":\"--Pues que no la ronde, que es tuya--exclamó la mamá decisivamente, recreándose en ver el rostro extático de su hijo, que al oir esta palabra divina, con un impulso de esos que no se calculan, echó los brazos al cuello de la jaca, y le plantó un achuchón completo en el hocico negro y suave.\"},{\"heading\":false,\"text\":\"Convenido ya el precio y la hora de cobrarlo, doña Aurora indicó algo sobre el cuidado de la jaca, proponiendo á Agustín dejársela en pupilaje; pero Rogelio, excitado, casi convulso de felicidad, no permitía hablar á nadie, ni tomar resolución alguna. «Tú no sabes, mamá... Yo me encargo de eso, déjame á mí... Sí que he de pasarme yo un día solo sin enterarme de cómo anda la jaquita mía... Todas las mañanas y todas las tardes la he de ver á la señora jaca... Te digo que lo dejes de mi cuenta...» Acabó doña Aurora por acceder y otorgarle plenas facultades. «Bien, pues allá tú...» Cuando se trató de poner nombre á la jaca, el muchacho, sonriendo, murmuró: «La llamaré Suriña».\"},{\"heading\":false,\"text\":\"Los afectos cardinales del alma humana dictan á veces rasgos de maravillosa inspiración: la señora había comprendido, iluminada por el amor maternal, que tratándose de un hombre de veinte años, y menor aún que su misma edad, no hay rival mejor contra una hembra que un caballo bonito. El caballo no es solamente distracción de un par de horas al día, sino ocu pación y preocupación constante, desde que amanece hasta que anochece. Enterarse de lo que come, y de si le roban ó no la cebada; ver si está limpio y se han practicado con él todas las operaciones de tocador--y el tocador de un caballo fino lleva casi tanto tiempo como el de una mujer primorosa; luego, esa comunicación afectiva que se establece entre el jinete que por vez primera disfruta el goce de un caballo, y el animal; esa ternura que nace de la posesión; ese trueque de monerías, el azúcar robado al almuerzo para ir á dárselo, el pan fresco escondido en el bolsillo del chaleco, la dicha que produce el relincho de júbilo del animal cuando su penetrante olfato y su delicada percepción le dicen que el amo se acerca con la golosina... Después, las inquietudes por la salud--un caballo ocasiona tantas como un niño chico.--«Señorito, esta jaca no sé qué tiene... hoy no ha comido el pienso. Le noto los ojos tristes.--Señorito, hoy la jaca no ha...» ¡Quién lleva lista de los innumerables achaquillos que puede padecer una jaca! Después de tan múltiples cuidados, aun queda otro orden de ellos, relacionados con lo que podemos llamar las galas de boda de la equitación: el galápago de la mejor piel de cerdo, crujiente, diminuto, mono; el sudadero de rico fieltro con cifras inglesas; los acerados estribos; la sutil cabezada, que deja lucir toda la gracia de la gentil cabeza; y para el jinete, el látigo de puño de plata cincelado; los guantes del Tirol; el ajustado calzón de punto; las botas muelles; la corbata con herraduras blancas sobre fondo gris... Todo distracción, todo embeleso en la encantadora luna de miel del muchacho con su jaca. ¡Y qué emoción al sacarla! ¡Qué vanidad al lucirla con los amigos! ¡Qué inexplicable deleite al pasearla en las frondosas arboledas de la Moncloa, al ver acercarse un carruaje en cuyo fondo se reclina una bella enlutada, y bajo la fascinación del mirar de la gentil desconocida, ostentar la montura, hacer piernas, caracolear y lucir su gallardía cubriéndola de espuma y sudor! ¡Qué placer ir variando de aires, ya el rítmico paso, ya el animado trote, ya el ardiente galope; y al halagar con cariñosa palmada el cuello del obediente bruto, sentirle resoplar de placer, estremeciéndose todos sus sensibles nervios y su vigorosa y enjuta musculatura, como talle de jovencilla al rodearlo el brazo de ágil pareja y disponerse al vals!\"},{\"heading\":false,\"text\":\"Indudablemente, lo de la jaca sí que había sido gran recurso é idea feliz, hija al fin de la experiencia, y muy superior á aquel ardid vulgar de echarse novia, que se ofreciera al candor de Rogelio como arbitrio soberano para curar su incipiente enfermedad amorosa. Ahora no necesitaba su madre pedirle que saliese, ni inventar pretextos con que echarle á la calle. Espontáneamente no hacía el chico más que ir y venir de su casa á la cuadra de la favorita. El invierno cejaba ya; los últimos días de Marzo eran, á pesar de la mala fama de este mes versátil, claros, templados y hermosos; y todas las tardes, desde las tres, salía Rogelio á gozar de los primeros soplos primaverales, ya solo, ya con amigos, ya con el picador, volviendo al anochecer dominado por una sana fatiga física, embriagado de aire puro, libre de molicies y malas sugestiones, penetrado de la alegría del paseo. Entre esta veta de actividad que su madre había descubierto, y el estudio, indispensable porque la época de los exámenes se acercaba amenazadora, ¿cuándo ni cómo había de encontrar tiempo de atender á la Esclava?\"},{\"heading\":false,\"text\":\"No por eso se dormía la madre, ni abandonaba el bien concebido plan de defensa. Un día, Don Gaspar Febrero, habiendo madrugado algo más que los otros tertulios, vino á quedarse á solas con la señora de Pardiñas, y según costumbre, trajo la conversación hacia Esclavitud, elogiándola de tan desatinada manera, que la señora sintió cierta desazón en los nervios.\"},{\"heading\":false,\"text\":\"--Pecisamente--dijo doña Aurora cuando el anciano la permitió meter baza:--tenía que indicarle á V., á propósito de esa chica... Pero prométame que me responderá con franqueza absoluta, como amigos viejos que somos ya.\"},{\"heading\":false,\"text\":\"--¡Pues no faltaba más! Mi simpática Aurora, ¿cuándo no?... ¿En qué puedo servirla?\"},{\"heading\":false,\"text\":\"--Verá V.... Una cosa que se me ha ocurrido aquí por la mañanas cuando estoy sin gente y el rapaz en clase... Como V. se va á quedar muy mal, creo yo... así que Felisa emprenda su gran viajata á Filipinas..., yo..., en mi deseo de que no eche V. tan de menos esos cuidados á que está acostumbrado ya... ¿no le parece á V.?\"},{\"heading\":false,\"text\":\"--Veamos, veamos. Siendo de V. la idea... V. discurre siempre muy juiciosamente, amiguita...\"},{\"heading\":false,\"text\":\"--Como me ha dicho V. tantas veces que le agrada el modo de servir de Esclavitud...\"},{\"heading\":false,\"text\":\"El gallardo anciano hizo un brioso movimiento de halagüeña sorpresa, afianzó sus espejuelos, se apoyó en la muleta, inclinándose hacia adelante; y desatentado, trémulo, sin acertar á formar los períodos, exclamó:\"},{\"heading\":false,\"text\":\"--Amiga, amiga, amiga... ¿Qué me dice V., qué me dice V....? ¿Ha reflexionado antes de hablar? ¡Desprenderse V. de ese tesoro! ¡de ese tesoro! Me llena V. de agradecimiento, sí, señor... pero en conciencia... no, no puedo consentir... ¡A dónde llega la amistad! Ahora lo veo, Aurora... No, pero yo no soy un egoista... No, V. no habrá meditado... ¿lo dice V. formal, formal?\"},{\"heading\":false,\"text\":\"Sintió la señora el aguijón del remordimiento ante esta gratitud extemporánea, y se dió prisa á añadir:\"},{\"heading\":false,\"text\":\"--Mire V., si sería conveniente para mí también; hasta para mí. Hay su parte de egoismo, Don Gaspar; no es todo virtud. Como este año proyecto llevar á Rogelio á que conozca nuestra tierra...\"},{\"heading\":false,\"text\":\"--Razón de más, amiguita, razón de más. No puede V. prescindir de una servidora semejante viajando. Están muy malos los tiempos... Ahora, con las Higinias que corren, ¿quién suelta una Esclavitud.... ¡ah! una Esclavita de esa marca! ¿V., V. lo ha pensado, lo que se dice pensar?\"},{\"heading\":false,\"text\":\"Al hablar así, Nuño Rasura pegaba saltos en su butaca, y hacía con la muleta el molinete. Sus ojos brillaban; su cuerpo se erguía como de un muchacho, y afanoso sobrealiento agitaba su esternón. «Dios nos asista» pensó doña Aurora: «á este señor le voy á tener que recoger del suelo con cucharilla.» Y como guardaba silencio aparentando hallarse conmovida por los argumentos del buen señor, éste añadió de pronto, con energía, á manera de niño que se deja convencer para tomar un juguete:\"},{\"heading\":false,\"text\":\"--Pero es decir... ya comprendo que la amiguita lo ha meditado bien, en el mero hecho de proponérmelo á mí. Conozco que tiene fundamento lo que V. alega: mucho, mucho, Aurora... viajando, se va mejor solo: el hijo con la mamá... claro, perfectamente. Pues por mí... basta que sea indicación de V.: acepto, acepto... ¿oye la amiguita? acepto.\"},{\"heading\":false,\"text\":\"Doña Aurora discurría: «Cierto que á veces irrita un trucha como Don Nicanor, que tiene la malicia por arrobas y es capaz de pensar mal de su propia madre; pero también estos inocentones, que nunca se enteran... vamos, hay días en que le ponen á uno los nervios como cuerdas de guitarra».\"},{\"heading\":false,\"text\":\"Vencidos ya los escrúpulos de Don Gaspar, él mismo combinó y desarrolló el plan de campaña: al ausentarse la hija, Esclavitud entraría á servir al padre en concepto de ama de llaves. El ochentón añadió, estregándose repetidas veces las manos:\"},{\"heading\":false,\"text\":\"--Que no se entere Candás... No quiero bromas inconvenientes.\"}]},{\"title\":\"Morriña — capítulo XXI\",\"blocks\":[{\"heading\":false,\"text\":\"Nada transpiró de esta conjuración doméstica. Guardó silencio doña Aurora, porque las mujeres saben callar muy bien si se lo proponen y si están en juego intereses de su corazón; y Don Gaspar se cosió los labios, porque temía más que al cólera á las cuchufletas é insinuaciones del Fiscal, y otro tanto--revelemos estas interioridades--á la fiereza de su hija Felisa. La cual, suspicaz como una esposa, alarmada por los instintos de elegancia, sociabilidad y galantería del anciano, se había dedicado á buscarle lo más feo, zafio é intratable del ramo de maritornes, porque siempre veía perfilarse en el horizonte la fatídica silueta de una madrastra. Hasta que Felisa emprendiese su viaje hacia la quinta parte del mundo, no se atrevía el viejo ni siquiera á indicar el propósito de llevarse consigo á tan dulce y linda sirviente. Costábale mucho trabajo reprimirse y esperar, porque su senectud era niñez antojadiza é impaciente, y cuando tardaba en cumplírsele un deseo, á dejarse llevar de sus impulsos, hubiera pateado. El desahogo que tomaba era cogerle las vueltas á los tertulianos para encontrar sola á doña Aurora, y hablarle difusamente, como hablan los viejos, de sus planes, de lo bien que iba á estar con él Esclavitud, de todas las atenciones que le prodigaría, de lo fácil que es servir un nombre _pelado_, con otras cosas del mismo jaez. Y cuando por haber gente delante no podía explayarse el buen señor, dirigía á su «amiguita respetable» miradas y guiños de inteligencia, le sonreía sin motivo y en fin buscaba salida á aquella plenitud de espíritu digna de otra más ardiente edad. «Dios nos conserve el juicio», reflexionaba la señora. «No sé por qué nos pasmamos de que se chiflen los rapaces, cuando los señores mayores se ponen así. Aun á los rapaces mismos no les da tan fuerte. Voy á comprar unos pañuelos tamaños como la Sábana Santa, para limpiarle las babas á este bendito señor. El diablo me lleve si no está rabiando porque la hija tome las de Villadiego para recoger á Esclavitud más corriendito. Si yo no supiese que por otra parte es una persona buenísima, y que la muchacha tampoco me parece capaz de una mala partida con él, tendría algún reconcomio. Porque nadie es capaz de saber á dónde llegan estas cosas, y si le da por casorio ó una barbaridad semejante...» La idea era tan bufa, Don Gaspar casado con una muchacha de veinticinco, que la señora de Pardiñas se rió sola, y el monólogo acabó por una rascadura de aguja de calceta en el moño, y este corolario: «Yo no tengo culpa si llega á suceder algún caso estupendo. Proporcionarle una buena colocación á una buena criada, no es delito. Lo que siento es que esa empalagosa de Felisa Febrero nunca acaba de tomar el tole para Filipinas.»\"},{\"heading\":false,\"text\":\"Era verdad que se daba una calma en emprender el camino, hecha para freir la sangre á quien tuviese genio menos pronto que doña Aurora. Lo que la impacientaba y desesperaba era que ya iba acercándose la época de exámenes, después de los cuales tenía determinado salir á Galicia; y ni dejar á Esclavitud ni llevársela le parecía factible. Don Gaspar traía noticias del éxodo de su hija, con cara más alegre cuanto más se acercaba el plazo. «Ya está arreglando baúles... Se ha enterado de salidas de vapores... El jueves, ó á todo tirar el sábado, andando para Cádiz...» Por fin, un día llegó con el exterior más radiante, más olímpico que nunca, bajo la aureola de sus hermosos rizos blancos. «Amiguita doña Aurora, esta tarde se nos va...» Convínose en que por respetos humanos se dejarían transcurrir dos ó tres días sin hacerle la primera intimación á la sucia y tosca extremeña que asistía á Don Gaspar, y en significar á Esclavitud el cambio de su destino. «La amiga doña Aurora se encarga de eso...», indicó el ochentón. Pero aunque dejando su espíritu encomendado en manos de la señora de Pardiñas, como al día siguiente, en ocasión de dar el higiénico paseo cotidiano á la pata coja, cruzase la Puerta del Sol y pasase por delante de la confitería de _La Pajarita_, no pudo reprimirse, entró, é hizo pesar medio kilo de caramelos y bombones. Los guardó furtivamente en el bolsillo interior del gabán, y al llamar en casa de Pardiñas y abrirle Esclavitud la puerta, miró alrededor, echó mano á la faltriquera, y sacando el alcartaz, se lo pasó á la muchacha como podría pasarle un billete amoroso. «Fresquitos», fué lo único que en su grata turbación acertó á decir entregando la dádiva.\"},{\"heading\":false,\"text\":\"Contrariedad y esfuerzo y tragadura de saliva costó á doña Aurora desempeñar la ingrata tarea de _soltársela_ á Esclavitud. Hubiese preferido tener que darle la nueva de una gran desdicha, como muerte de un ser querido ó revés de fortuna: porque al cabo, en semejantes males no le correspondería á la señora parte de responsabilidad ni tanto de culpa, mientras en esta mera traslación de domicilio y cambio de amos, la señora, con su rectitud natural que sólo podría torcer la corriente del sentimiento, adivinaba algo de crueldad y dureza que era obra suya, aunque procediese de móviles justos, de los que no desoye ninguna madre prudente. «Es hasta cuestión de conciencia para mí», pensaba, á fin de cobrar ánimos. «Fuí inadvertida trayéndole á Rogelio la tentación al alcance de la mano: Felisa Febrero, en esto, ha mostrado tener más mundo, pues ni siquiera á los ochenta y pico de su padre les arrima la mecha. Demasiado bueno es el niño, cuando ya no se me ha emberrenchinado atrozmente. No, no, mejor es ponerse una vez colorado que ciento amarillo. Hoy se la suelto. Así que Rogelio salga á clase...»\"},{\"heading\":false,\"text\":\"Encierra el tono de la voz humana misteriosos avisos, que en situaciones dadas revelan todo lo que oculta el alma, antes que las palabras lo digan. La sencilla frase «Esclavitud, ven», que tantas veces al día oye una criada de su ama, resonó esta vez de un modo particular en el corazón de la gallega. Toda su sangre afluyó al centro de la vida orgánica, y cuando entró en la habitación donde la esperaba su señora, el fondo y la esencia de lo que iba á oir le eran ya conocidos intuitivamente.\"},{\"heading\":false,\"text\":\"No estaba doña Aurora en el comedor, sino en el despacho de su hijo, al cual solía ir en ausencia de éste para escribir alguna carta ó sacar alguna cuenta, si ocurría, y quizá por satisfacer ese instinto de curiosidad inquieta propio de los afectos exclusivos que llegan al grado de pasión. Hizo sentar á Esclavitud en una silla próxima, y empezó á hablar sin mirarla á la cara, jugando con una cajita de plumas, de donde las iba sacando para alinearlas sobre la mesa. «Todo el mundo tiene que amoldarse á las circunstancias. Con el viaje á Galicia, no había medio... Moverse tres personas no es como moverse dos, claro está. La casa del señor de Febrero era la mejor colocación que una muchacha como ella podía desear; una ganga... No sería doncella, sino ama de llaves... Se le guardarían toda especie de consideraciones... El trabajo de servir á una persona sola no había de matarla; complaciendo un poco al señor aquel tan excelente, estaría como en la gloria, casi lo mismo que si hubiese encontrado una familia. Por último, Don Gaspar también era de la tierra: no tenía Esclavitud por qué pasar malos ratos, como en la otra casa...»\"},{\"heading\":false,\"text\":\"Así que hubo alegado todas estas razones, sintió un alivio interior, y sin dejar de prestar en apariencia gran atención á las hileras de plumas, miró con el rabillo del ojo á la muchacha. Esclavitud permanecía inmóvil en su asiento, con las manos cruzadas sobre el regazo, los piés juntos y bajos los ojos: tampoco ella entregaba fácilmente aquel espejo de los movimientos del alma á disposición de la curiosidad.\"},{\"heading\":false,\"text\":\"--Bien, ¿qué dices?--articuló al fin la señora que comenzaba á impacientarse, como siempre que encontraba resistencia pasiva.\"},{\"heading\":false,\"text\":\"--¿Yo qué quiere que diga?--respondió Esclavitud con voz sorda, pero tranquila al parecer.\"},{\"heading\":false,\"text\":\"--Sí ó no; si te gusta la casa que te ofrezco, ó si quieres tú buscar otra á tu modo y á tu idea.\"},{\"heading\":false,\"text\":\"Hubo una pausa, y, por último, la muchacha respondió con acento incoloro á fuerza de ser contenido:\"},{\"heading\":false,\"text\":\"--Si no corre mucha prisa, daré la contestación mañana ó pasado.\"},{\"heading\":false,\"text\":\"«Te veo», pensó la señora. «Tú quieres hablar antes con el niño. Bien, aquí estamos todos para lo que pueda ocurrir. En guardia me tienes, y de centinela. Por de pronto yo procuraré que no le cojas á tergo. Andaremos, como quien dice, barba sobre el hombro.» Sin embargo, aquella tarde no tuvo más recurso que salir,--contra su costumbre,--á despedir en la estación del Mediodía á Felisa Febrero, de esas pejigueras de sociedad que no se pueden rehuir y siempre caen en el momento más inoportuno. Rogelio también había salido á caballo; pero quizá por la necesidad de repasar las lecciones, más apremiante á medida que los exámenes se venían encima, hizo corto el paseo; y al entrar en su casa, aun animado de la correría, abanicándose con el hongo gris, y girando el látigo, fué cuando Esclavitud le agarró de la manga y le empujó casi hasta su despacho, acorralándole contra la mesa misma en que doña Aurora había ordenado por la mañana los ejércitos de plumas.\"},{\"heading\":false,\"text\":\"--¿Qué pasa, Suriña? ¿Qué tienes?\"},{\"heading\":false,\"text\":\"--¿No le decía yo que no iba á Galicia este año, ni en jamás? Su mamá me despide... Me deja en casa del señor de Febrero.\"},{\"heading\":false,\"text\":\"--Pero, ¿qué estás diciendo? A ver, á ver, cuenta...\"},{\"heading\":false,\"text\":\"La muchacha refirió lo que sabía. Sus ojos estaban secos, y sólo algo temblorosas su boca y barba. Su seno anhelaba precipitadamente, y en su modo de narrar y de explicarse, en aquella desesperada demanda de auxilio que hacía como náufrago que saca la cabeza por encima de las olas, había una vehemencia y un desorden que contrastaban con su habitual compostura, y que trastornarían á cualquiera aunque no tuviese los pocos años y la inexperiencia de Rogelio. Mientras balbucía «no, no puede ser, tú no te irás, qué tontería...», sus brazos ceñían involuntariamente el talle gentil de la muchacha, y el estremecimiento interior de deseo de hacía cuatro ó cinco meses renacía más brioso, infundiendo á su alma vigor para rebelarse, protestar y defender á la Esclavita como se defiende lo que nos pertenece y forma la substancia de nuestro vivir. «Pero vamos á ver, no entiendo cómo le ha entrado ese arrechucho á mamá... Por fuerza le han ido con algún chisme... ¿Y por qué, y de qué...? Nosotros ¿qué motivo hemos dado, Suriña? Si desde la enfermedad de mamá no nos hablamos casi: si tú ni pones aquí los piés... Es una cosa rarísima, y no ha de quedar así... Yo lo arreglaré; ¡qué habías de irte! No, hermosa...» Alentada y resucitada por estas promesas, Esclavitud se apretaba contra el corazón de su amigo, queriendo incrustarse en aquel refugio para que nadie la arrancase de allí; y Rogelio, con transporte juvenil é irresistible, la cubría de caricias, tratando de alzarle la cabeza para buscar sus labios. Tocaron á la campanilla, y la primera vez no oyó el repique ninguno de los dos. Al segundo, enérgico y airado, Esclavitud se estremeció, y, con movimiento simultáneo y brusco, se desunió la pareja. La muchacha se arregló el pelo, se ajustó temblando el pañuelo de seda que le rodeaba la garganta.\"},{\"heading\":false,\"text\":\"--Voy á abrir, que es la señora.\"}]},{\"title\":\"Morriña — capítulo XXII\",\"blocks\":[{\"heading\":false,\"text\":\"Viendo á su hijo aquella noche, á la hora de comer, distraído, pálido y hasta un poco seco al hablar, la señora pensó al punto: «La tenemos armada. Ya se lo ha encajado aquella buena alhajita». También pescó al vuelo miradillas furtivas, azoradas y elocuentes; pero se aguantó, discurriendo para sí: «Según Don Nicanor, en este mundo hay que hacerse el tonto un cuarto de hora todos los días; ahora á mí me han doblado la ración, y tendré que hacerme la tonta algunos meses.» Hízose, pues, la tonta, como si no advirtiese el estado de su hijo, á quien preguntó con muchísimo interés noticias de la jaca y de la cochera, y de los habituales compañeros de _sport_. Así que se alzaron los manteles, sacó otra conversación muy socorrida y de palpitante actualidad, á saber: los exámenes. «Rapaz, allá para el miércoles ó jueves, me parece que te tocará el turno, de manera que esta semana me espera á mí un ajetreo regular... Porque la verdad es que con esos señores no sabe uno á qué carta quedarse. ¡Si todos fuesen como Contreras! Ese sabe ponerse en la razón. Sólo que este año todavía no te cae por banda Contreras. Con los demás es un lío; si se oye á unos y á otros, hay para marearse. Lastra quiere que le bajen la cabeza, que le rindan el tributo de la recomendación, y que todo el mundo tenga que agradecerle. Ruiz del Monte parece que es al contrario: si le hablan por un chico, le toma tirria, y le aprieta hasta reventarlo. Tú sabrás si es cierto; á mí me lo contó tu amigachillo Díaz, el que escribe romances... De Albirán se susurra otra cosa: que no desatiende recomendaciones, pero con su cuenta y razón, según de quien procedan... Lo más seguro será que repases, niño.»\"},{\"heading\":false,\"text\":\"--Ya repaso, mamá--contestó lacónicamente el estudiante.\"},{\"heading\":false,\"text\":\"Corrió la noche sin que se le pudiese sacar otra palabra. Revolvía las revistas ilustradas, los periódicos del día; los tomaba y los dejaba, cambiaba de asiento pasando del sillón al sofá y del sofá al sillón; suspiraba hondo, y, en fin, daba todas las señales de desazón posibles, sin cuidarse de que se viese, ó más bien pareciendo que deseaba lo advirtiese su mamá. Al fin, cuando ésta le dijo «¿no sales hoy á un actito á Lara?» exclamó con tono duro y resuelto:\"},{\"heading\":false,\"text\":\"--No; voy á acostarme. Me duele un poco la cabeza.\"},{\"heading\":false,\"text\":\"La señora le oyó taconear en el corredor y batir la puerta de su despacho.\"},{\"heading\":false,\"text\":\"--Lo dicho; la tenemos. Yo he cometido una falta grave. Debí no resolver este cotarro hasta pasados los exámenes, un par de días antes de la marcha... Ha sido una borricada mía. Ya se ve; el deseo de salir del atolladero prontito... Pues no; hay cosas que vale más llevarlas por sus pasos contados. Veremos si la puedo enmendar y dar tiempo al tiempo. Si no, voy á tener al rapaz desquiciado cuando más necesita la cabeza firme. Una prórroga... A ver si consigo encajárselo en la cabeza á Don Gaspar. Es fácil que sea más arduo hacer entrar en razón al viejo que al niño. ¡Qué complicaciones! Aquella falsona de Rita Pardo decía bien... Conviene mirar mucho á quién mete uno en su casa.\"},{\"heading\":false,\"text\":\"Hubo entonces en el pequeño drama doméstico, intimo, que ya tocaba á su desenlace, uno de esos entreactos, como treguas momentáneas, durante las cuales los actores, aparentando dedicarse á otros intereses ó distraídos efectivamente por ellos, no pierden de vista, sin embargo, el asunto capital, y viven, por decirlo así, en perpetua representación, guardando silencio acerca de lo que más ocupa su alma, sin que este silencio engañe á nadie. La señora atendía sólo á ganar días, calmando la impaciencia pueril de Don Gaspar Febrero con moratorias que justificaba la proximidad de los exámenes y la imposibilidad de quedarse en aquel momento sin doncella; Esclavitud aguardaba, ocultando en lo más profundo del pecho una esperanza tenaz, basada en las palabras y ofrecimientos de su amigo; y Rogelio, preocupado, agitado, acechaba inútilmente la ocasión de decir algo, ¡algo muy formal y en tono muy firme!, á su madre. La verdad ante todo; si la señora le facilitase esta ocasión, el estudiante se vería perdido para aprovecharla. A medida que pasaba tiempo, la dosis de valor atesorada en el primer instante iba disipándose como un frasco de esencia cuando queda destapado. Es indecible el pecho que necesita un buen hijo para ponerse frente á frente de una buena madre, y realizar un acto que en cierto modo le manumite, pero que le desgarra las fibras más íntimas del corazón. Tanto se unen y confunden el deber natural, la costumbre y hasta aquel disculpable egoísmo que nos aconseja entregarnos sin reserva en manos de quien más que á sí mismo nos ama, que el romper ese lazo constituye un acto de supremo vigor, uno de esos esfuerzos que quebrantan una voluntad si no es de acero bien templado. Contra un padre severo hay siempre energía; sus propios rigores entonan; pero una madre como la de Rogelio, que no había tenido más pensamiento que su hijo, que le había rodeado de tal solicitud, ahorrándole hasta el trabajo de discurrir y el esfuerzo de desear; una madre viuda, delicada de salud, y que había ejercitado el arte de adelantarse á los gustos de su hijo, consiguiendo así que la voluntad de éste no adquiriese nunca el temple recio que dan las privaciones y las luchas, era un adversario con quien Rogelio no tenía fuerzas para medirse. «Si ella misma sacase la conversación...», pensaba el estudiante. Pero ¡quiá! La verdad es que si ella la sacase... sería lo mismo. Lo único á que se atrevía era á la protesta muda, á hacerse unas veces el triste y otras el malhumorado y fosco. «Mamá, por no verme así, es capaz de cualquier cosa...», calculaba con su lógica de niño mimado. Sólo que mamá sabía distinguir de juguetes.\"},{\"heading\":false,\"text\":\"El incidente de los exámenes contribuyó á enflaquecer más todavía su resolución. Entre el repaso, los temores del mal éxito y las idas y venidas de los amigos que le traían, por decirlo así, relación del estado barométrico de las notas, Rogelio se encontró fuera del círculo mágico con que nos rodea la idea fija amorosa, y á no ser por un par de ojos verdes que de vez en cuando se fijaban en los suyos, hasta hubiese olvidado _aquéllo_, que, por raro fenómeno de óptica, le parecía todos los días menos inminente--siendo así que lo era más, pues la salida á Galicia estaba irremisiblemente señalada para después de los exámenes.\"},{\"heading\":false,\"text\":\"Y éstos llegaron, y se encontró Rogelio con dos asignaturas aprobadas; pero en una--la más ingrata y antipática para él--le cayó como una ducha fría un _suspenso_. «De estas calabazas ya sé yo quién tiene la culpa...», pensaba la madre, mirando al través de la puerta entornada á Esclavitud, que pasaba un plumero á los cuadros del saloncito. «En esto paran las guilladuras; pero, ¿qué le vamos á hacer? cada edad trae lo suyo. En Septiembre ganará lo que pierde ahora; bien joven es; con tal que esté sano... Y seamos justos; la jaca también me lo levantó de cascos en esta temporada última. Verdad que más vale así. De la primavera acá no me quejo. Bien se ha portado la jaquita... Merece una libra de azúcar.»\"}]},{\"title\":\"Morriña — capítulo XXIII\",\"blocks\":[{\"heading\":false,\"text\":\"La última noche que la familia Pardiñas pasó en Madrid antes de marchar á su tierra, vino mucha gente á decirles adiós, y se formó una pequeña tertulia animada y sin etiqueta. A fines ya de Junio, el momento más hermoso para salir y buscar sociedad era realmente entre diez y once de la noche, cuando corre un sano aire fresco hasta por las abrasadas callejuelas del Madrid antiguo, del que ni tiene arbolado ni casi goza los beneficios del riego municipal. Bajaron las vecinas del segundo, sobrinas de un brigadier de ingenieros, y acudió también la marquesa viuda de Andrade, paisana de doña Aurora, señora guapetona y maja, bastante conocida en los círculos aristocráticos, y acostumbrada por consiguiente á recogerse tarde. La señora de Pardiñas, al encontrarse rodeada de visitas, se dedicó á agasajarlas lo mejor que pudo y supo, dejando girar libremente la conversación, que versaba sobre cosas del país donde iba á volver después de tantos años. La Marquesa, alegre y rozagante, habló de irse pronto á Vigo, y enseñó un brazalete nuevo, con zafiros y brillantes, dando á entender que había en él cierto misterio. «Esta anda otra vez con intenciones de maridar--pensó doña Aurora.--¿Quién será el galán? Dios se la depare buena.»\"},{\"heading\":false,\"text\":\"Rogelio había abandonado la reunión impensadamente, sin decir oxte ni moxte. La retirada no se le pasó por alto á su madre, pero sobre que no podía evitarla, descubrió otros motivos de resignarse: «Pocas son las malas fadas; al fin mañana nos vamos...» Esclavitud aún se le figuraba un peligro y un compromiso, pero ya muy remoto. «Mañana á estas horas estaremos cerca de Avila... ¡Cuándo oiré el silbato del tren!»\"},{\"heading\":false,\"text\":\"Se recogía Rogelio á su cuarto, impulsado por vagas esperanzas de ver á la chica, explicarle su actitud de aquellos días, y la imposibilidad de proceder de distinto modo, de evitar la marcha y de sublevarse. Presentía que Esclavitud, no desperdiciando la ocasión, vendría pronto; y á fin de que comprendiese que estaba allí, encendió luz con mucho derroche de fósforos y taconeo, abrió cajones é hizo chirriar dos ó tres veces la puerta. A llamarla no se atrevía por temor al fino oído de su madre, pues, según su frase paradójica é hiperbólica, «oía mejor que el sordo Candás».\"},{\"heading\":false,\"text\":\"No aguardó largo trecho. A los diez minutos tocaron á la puerta, y antes que dijese «adelante» entraba Esclavitud. La claridad del quinqué puesto sobre la mesa del despachillo que precedía á la alcoba y cuarto tocador del estudiante cayó sobre el rostro de la muchacha, y Rogelio observó mejor que nunca cómo en una quincena había empalidecido y se había demacrado, afinando y espiritualizando su tipo, que ahora podría servir de modelo para esas imágenes labradas en cera, donde se encierran los huesos de alguna mártir desconocida.\"},{\"heading\":false,\"text\":\"Rogelio se llegó á Esclava y le tomó la mano: ardía de calentura.\"},{\"heading\":false,\"text\":\"Sin decirse palabra, con unánime impulso, miraron alrededor, buscando un mueble en que sentarse reunidos. No lo había en el despachito, alhajado con un sitial y media docena de sillas; y sin reflexionar se refugiaron en la alcoda, donde Rogelio, cogiendo á la muchacha por el talle, la obligó á sentarse en la cama. Tampoco entonces hablaron hasta transcurrir un tiempo que no bajaría de cinco minutos. Rogelio apretaba y acariciaba aquella manecita algo endurecida por el trabajo y muy picada de la aguja, como queriendo comunicarle la frescura de sus palmas y quitarle el ardor de la fiebre. Pero no se le ocurría nada, sino las vulgaridades consoladoras de todas las despedidas; y al fin, pareciéndole raro callar más, se resolvió á emplear tan mala moneda.\"},{\"heading\":false,\"text\":\"--Suriña, tontiña, mujer, no me estés así... Mira, he reflexionado mucho; he cavilado más que tú. No se conseguiría nada con llevarle á mamá la contraria ahora. Le daríamos un disgusto muy grande; acaso se nos pondría enferma, pero no mudaría de resolución. Ten paciencia. Dentro de tres meses, ó menos aún, estamos de vuelta aquí, y nos veremos, porque en casa del señor de Febrero andarás mucho más libre que en ésta. Ya sabes que yo te he de querer siempre, boba. No me la pegues con el tierno Nuño Rasura. Anda, tontiña, paloma, no me estés así. Mira que me vas á poner muy triste.\"},{\"heading\":false,\"text\":\"Esclavitud no contestaba sino moviendo la cabeza negativamente, con obstinada melancolía. Luego respondió, en voz bastante entera:\"},{\"heading\":false,\"text\":\"--Alegre no puedo estar. Pero tampoco estoy triste. No se apure. Sólo que tengo la cabeza... así... como si me anduviese por dentro de ella una cosa mala.\"},{\"heading\":false,\"text\":\"--Mujer, ¡Suriña!\"},{\"heading\":false,\"text\":\"--Sí, señor. Yo estoy aquí, ¿eh? ¿Le estoy oyendo? ¿Le respondo? Pues estoy como si oyese á una persona... de allá, del otro mundo, que me habla.\"},{\"heading\":false,\"text\":\"--¡Válgame Dios!--exclamó el estudiante estremeciéndose.--Más quisiera que llorases. Si llorases no estarías tan maniática, Sura. Llora y desespérate, pero no digas esas cosazas.\"},{\"heading\":false,\"text\":\"--Yo lloro por dentro. Por fuera no. Ni una lágrima puedo echar. Ya estuve lo mismo otra vez, cuando murió mi padre--repuso apaciblemente la muchacha, sin que ni ella ni Rogelio subrayasen aquel nombre de _padre_ que acaso por primera vez articulaba Esclavitud sin rebozo ni perífrasis.\"},{\"heading\":false,\"text\":\"--Hija, te encuentro algo enferma. ¡Ay, ay, ay! Tienes calentura. Las manos tuyas abrasan. Dame palabra de que mañana vas á ver á Sánchez del Abrojo.\"},{\"heading\":false,\"text\":\"--No, señor, no es enfermedad. Más buena no estuve nunca. Son _avisos_.\"},{\"heading\":false,\"text\":\"--Mujer, calla por Dios. Estás diciendo unos disparates...\"},{\"heading\":false,\"text\":\"Arrimó el rostro al de la muchacha y la besó tiernamente en las heladas mejillas, sin que ella hiciese movimiento de resistencia. Al contrario, pareció más conforme y adoptó un tono casi confidencial y franco para decir á su amigo las extravagancias siguientes:\"},{\"heading\":false,\"text\":\"--Rogelio, hay cosas que avisan los difuntos á los vivos; no le quepa duda. Tres días antes de morir mi padre, vi un pájaro grande, negro, al pié de mi cama. Ayer vi otra vez el pájaro: iba tan de prisa que no sé por dónde se escapó; pero lo vi, tan cierto como que aquí estamos. Yo no vuelvo nunca más á la tierra: nunca más. Ya se verá; y entonces ha de convencerse y dirá: «Esclavitud bien me lo avisaba». Si tuviese tan seguro un millón de onzas, ya estaría discurriendo dónde las iba á guardar para que no me las llevasen los ladrones. Esta noche...\"},{\"heading\":false,\"text\":\"Bajó mucho más la voz, y al oído de Rogelio murmuró:\"},{\"heading\":false,\"text\":\"--Un perro, en una casa de ahí al lado, estuvo hasta que amaneció _ventando_ la muerte.\"},{\"heading\":false,\"text\":\"--¡Jesús, mujer!--exclamó Rogelio por segunda vez, ya fatalmente impresionado con aquella conversación extraña.--Tú estás loca ¿No ves, Suriña, que en Madrid se mueren ó agonizan cada noche infinitas personas? Figúrate: si los perros anunciasen todo eso, trabajo les mando. Se convertirían en cuarta plana de _La Correspondencia_. Lo que tienes, Sura, es que estás afectada porque nosotros nos vamos y tú te quedas. También yo ando hace muchos días disgustado con el viajecito. He pasado ratos feroces. Después he reflexionado... y... me parece que es mejor conformarse con esto de ahora, porque si alborotamos la enredaremos más. Suriña, tres meses. Dentro de noventa días (y aun puede que no tanto), me tienes aquí. Mi primer visita es para doña Sura. Anda, no estés así. Te quiero mucho, hermosa. Ya convenceremos á mamá. Todavía no me has dicho hoy que me querías. ¡Anda!...\"},{\"heading\":false,\"text\":\"Con el movimiento de un niño que pide halagos, acercó su mejilla á la boca de Esclavitud, y ésta, sin protesta alguna, como el que ejecuta una acción hija de la costumbre, puso en ella los labios. Estaban como las palmas, secos y ardientes, y á Rogelio le pareció que le arrancaban la piel, con sensación más bien dolorosa que placentera. Sólo que las caricias eran un recurso para que aquella última y penosa entrevista fuese algo menos intolerable, y el estudiante, á falta de razones que consolasen á la pobre abandonada, acudió á los halagos, sin que en el primer momento le animase otra intención menos limpia y noble. Corrió bastante tiempo--y él mismo no acertaría á explicar el por qué de esta tardanza, anómala si se examina bien lo incitante de la hora y sitio y la ceguera de los pocos años--antes que se le despertase una sed criminal y ardiente. Cuando la embriaguez le ofuscó, saltó de la cama y fué á dar vuelta á la llave de la lámpara, sin conseguir por eso obscuridad completa, pues un rayo de luna primaveral, entrando por la vidriera del despacho, lo bañaba en luz fantástica, azulada y soñadora. Al recobrar, entre la pálida penumbra, los labios donde la fuerza de la ilusión juvenil le movía á creer que se dejaba presa el alma á cada aspiración del aliento, ya no los soltó, ni acaso los soltaría aunque viese allí á su madre, que representaba para él el Deber, y el Deber amado, el único que se impone á las almas tiernas. Pero el recuerdo y la conciencia de ese Deber fué lo primero que acudió á su mente al despertarse, y corriendo á la puerta, escuchó, volvió azorado, y exclamó en tono suplicante:\"},{\"heading\":false,\"text\":\"--Suriña, Suriña, se me figura que oigo despedirse en el pasillo á la Marquesa... Si esa se va, es que no queda nadie... Mamá se cuela aquí derechamente, de fijo... A ver, á ver si puedes escurrirte con maña. Adiós, vé despacito, que no te sientan... ¿eh?\"},{\"heading\":false,\"text\":\"La muchacha obedeció pasiva, como en todo, sin reclamar, en la premura de su aquiescencia, ni el último abrazo. Rogelio volvió á encender la lámpara, cuya mecha igualó cuidadosamente. Corrió también la vidriera de la alcoba, y de pié ante el gran armario de luna, se atusó y se sacó la raya con un peinecillo. Después metió las manos en los bolsillos del pantalón y se miró un rato, atentamente, estudiando con curiosidad irreflexiva su propia cara; hablando con sus ojos en el espejo, como para convencerse de que, disipado aquel vértigo, la individualidad persistía, y no quedaba para siempre en su persona no sé qué de otra, una huella que no se podía borrar y que iba á delatarle. Luego, la imagen de su madre volvió á oprimirle el corazón; pero disipó instantáneamente sus recelos un arrebato de alegría nerviosa; y el neófito, corriendo á la ventana, la abrió, se dejó bañar por la pura atmósfera nocturna, y agarrado á los hierros de la ventana, respiró con avidez.\"},{\"heading\":false,\"text\":\"EPILOGO\"},{\"heading\":false,\"text\":\"Antes faltaría el sol en los cielos, que Don Gaspar á las cuatro de la tarde con un cochecillo, para llevarse á casa su futura ama de llaves. Se le dijo que Esclavitud había salido ya en la misma dirección, y el viejo, con esta noticia, se metió otra vez en la berlina destartalada, mandando al cochero «que arrease bien.» La impaciencia no le permitía ir andando con su pata coja.\"},{\"heading\":false,\"text\":\"En los últimos momentos llamara doña Aurora á Esclavitud, poniéndole en las manos, amén de su salario, una buena propina, á cuyo obsequio añadió el de unos aretes con turquesas. «No quiero que se vaya descontenta. Cuidado que la noto desemblantada á la infeliz. Me parece que estaba encariñada de veras con el niño, por lo cual es cada vez más conveniente mi resolución. Me da lástima, y conozco que es una tontería que me la dé: ¡qué arrimo como el que encuentra! Le hago un favor grandísimo: lo que me tranquiliza es eso. Lleva una canonjía...»\"},{\"heading\":false,\"text\":\"Así y todo, la señora no podía reprimir cierta desazón, cierta amargura íntima, una lástima inmensa, que después tradujo por doloroso presentimiento. «Mire V. que compadecerla cuando estoy tan segura de que le he proporcionado lo que más podría desear una muchacha de su clase...» Y así lo creía en efecto la señora de Pardiñas. Como les sucede á muchas personas bondadosas incapaces de odiar y hacer daño, no quería reconocer que miraba ante todo á la conveniencia de su hijo, por más justo que le pareciese y en efecto fuese este móvil, y trataba de atribuir su conducta al interés de la misma Esclavitud.\"},{\"heading\":false,\"text\":\"La tranquilizó un poquillo oir en la cocina á Fausta que embromaba á Esclavitud cantándole _sotto voce_ aquello de «Y hoy sirvo á un abuelo... que está chocho y lelo... y yo soy el ama...»\"},{\"heading\":false,\"text\":\"--Tiene razón Fausta. El ama será en casa del señor de Febrero. Como no lo sea de más...\"},{\"heading\":false,\"text\":\"Salía el tren de Galicia á las siete y treinta y cinco, y á esa hora tan bonita, precursora del anochecer, en el andén de la estación del Norte no cabía la multitud afanosa y regocijada de viajeros y de amigos que los despedían, envidiando éstos á los que se marchaban á ver tierras hermosas, respirar aire salino, gozar el fresco, vivir mejor, en clima templado y salubre, algunos meses. No había escenas tristes: no era el adiós del marinero, ni la partida del soldado, ni la nostálgica despedida del emigrante: los que se iban, excitados y gozosos; risueños en su dentera los que se quedaban... Sólo hacia el extremo del tren, á la portezuela de un coche de primera, se divisaba un grupo de cinco personas que trocaban abrazos prolongados; componíase de dos hombres, mozo el uno y el otro viejo ya, cabizbajos, pero erguidos de cuerpo, y tres señoras, dos jóvenes y una de pelo blanco, que aplicaban frecuentemente el pañuelo á los ojos enrojecidos. Dentro del vagón estaba un ama con niño de pecho. Laín Calvo se acercó á doña Aurora y le dijo señalando al grupo:\"},{\"heading\":false,\"text\":\"--¿Ve allí á los Rojas? Faroles hasta el fin, hasta la muerte. Al hijo me lo han vuelto á trasladar á Marineda por aquella historia consabida de farolerías con el ministro, y mas que sepa perecer de necesidad, viajará en primera por el decoro de su cargo. Tiene á la mujer otra vez embarazada... y bien adelantadita en meses. A otra traslación dice que dimitirá... Y á Rojas ya me lo pillaron, ¿no sabía? Recibió la jubilación hace una semana.\"},{\"heading\":false,\"text\":\"--¡Qué me dice V.!--exclamó con pena sincerísima la señora.--¡Válgame Dios! ¡Pobrecitos! Esa infeliz de Matilde Rojas, cuándo encontrará un hombre de bien que la quiera sin un cuarto de dote! Le digo á V. que todo el camino iré pensando en esta familia. ¡Qué mundo, Don Nicanor!\"},{\"heading\":false,\"text\":\"Doña Aurora intentó dirigirse al grupo y estrechar la mano de las señoras de Rojas: pero ya no era hacedero, porque sonaba la campana de aviso, bufaba la máquina, y corrían de un lado á otro las carretillas con equipajes facturados para cargarlos. Rogelio, desde el vagón, alargó la mano á su madre, que subió despacio, riendo porque se le había enganchado un volante en el estribo; y entre la primer arrancada del tren se perdió la voz de Laín Calvo que gritaba:\"},{\"heading\":false,\"text\":\"--¡Cuidado con las niñas de Vigo, Rogelín que son de rechupete, home!\"},{\"heading\":false,\"text\":\"El tren, oscilando con suavidad, activaba su marcha. Caía la tarde con serena magnificencia, y Rogelio, asomado á la ventanilla, creía divisar ya los frescos valles galaicos, los castaños frondosos, el azul festón de las rías orlando la tierra más bonita del mundo.\"},{\"heading\":false,\"text\":\"En cambio no vió, del otro lado del andén, á Esclavitud, que seguía con los ojos el tren hasta que se alejó grandioso y raudo. Cuando ya no fué posible columbrar ni un copo del penachillo de humo negro, la muchacha, estremeciéndose como si tuviese frío, retrocedió lentamente hacia la ciudad, bien resuelta á que el sol, que se ponía en aquel instante, no volviese á levantarse para ella nunca, nunca.\"},{\"heading\":false,\"text\":\"Dejemos á la infeliz, porque al cabo no podríamos quitárselo de la cabeza. Si consultamos sobre este drama á Don Gabriel Pardo, que es amigo de generalidades pedantescas y se paga de malas razones por el afán de pretender explicarlo todo, nos dirá que el extravío mental que conduce á la muerte voluntaria, es muy propio del sombrío humor de la raza céltica, esa gran vencida de la Historia: como si cada día y en cada provincia de España no trajese la prensa suicidios así.\"},{\"heading\":false,\"text\":\"FIN\"}]}]', 'es', 'https://www.gutenberg.org/ebooks/52597', '{}');
INSERT INTO libros (id, titulo, autor, genero, cover, secciones, idioma, fuente, introducciones) VALUES (55514, 'Cuentos de amor', 'Emilia Pardo Bazán', 'cuentos', 'https://www.gutenberg.org/cache/epub/55514/pg55514.cover.medium.jpg', '[{\"title\":\"Prefacio\",\"blocks\":[{\"heading\":false,\"text\":\"Tranquilízate, lector: no se trata de un prólogo grave pegado á un libro de entretenimiento, lastre de plomo de algo tan leve como el ala de la mariposa: sólo encontrarás aquí unas cuantas advertencias, por otra parte innecesarias si para mí no rigiesen distintas leyes que para los demás autores, y si en mí no se calificase de delito lo que en ellos es acción indiferente, cuando no gracia merecedora de aplauso.\"},{\"heading\":false,\"text\":\"No ignorarás que he escrito á estas fechas gran número de cuentos, pero acaso te sorprenda si digo que pasan de cuatrocientos, y á todo correr se acercan á quinientos ya. No pocos, antes de ser recogidos en volumen, andan vertidos á varias lenguas en tierras muy lejanas, á pesar del descuido de una autora que no por indiferencia ni por desdén, sino por falta de tiempo, suele no contestar á las amables cartas de sus bondadosos traductores.\"},{\"heading\":false,\"text\":\"De estos cuatrocientos y pico de cuentos hay tres ó cuatro de los cuales se murmuró; para decir más verdad, de quien se murmuró no fué de ellos, sino de mí, negándome la propiedad del asunto. Ninguno de los incluídos en el presente volumen ha sido discutido, que yo sepa, en concepto tal; pero me adelanto, lector, á advertirte que tres de los que aquí te ofrezco no son míos por el asunto, y cinco ó seis tampoco son patrimonio de mi inventiva, sino narraciones de casos auténticos y reales--lo que Fernán Caballero llamaba _sucedidos_.--Yo los vestí y arreglé á mi manera, unas veces por gusto y capricho, otras, sobre todo cuando se trata de sucesos recientes, por respetos á la vida privada ajena.\"},{\"heading\":false,\"text\":\"Al ver la luz en _El Imparcial_ el cuento titulado _La sirena_, consigné en nota que su asunto estaba tomado de un lindo y breve apólogo de Leopoldo Trenor, _La gata blanca_. Después hubo quien me aseguró que el apólogo, á su vez, se funda en una poesía alemana. No he podido comprobar la aserción, y queda rectificada de antemano, si fuese inexacta y si el señor Trenor, en vez de hacer como yo hice, hubiese concebido la idea primera del apólogo.\"},{\"heading\":false,\"text\":\"_La cabellera de Laura_ es libre glosa de un _ejemplo_ que refiere el franciscano Padre Juan Laguna en sus _Casos raros de vicios y virtudes para escarmiento de pecadores_.--_Mi suicidio_ y _Cuento soñado_, son pensamientos que me sugirió platicando el ilustre y venerable Campoamor; y aunque él, á fuer de opulento, no reclamaría nunca esas dos perlitas, me complazco en agradecerle el donativo y en pedirle excusas por el engarce.\"},{\"heading\":false,\"text\":\"Y pues se trata de perlas, vamos á _La perla rosa_. Verdaderamente me asombra, lector entendido, que mis vigilantes aduaneros y agentes del resguardo no hayan gritado _¡matute!_ cuando inserté ese cuento en _El Liberal_. Me denuncio, ya que ellos se duermen. A los pocos meses de aparecer en _El Liberal La perla rosa_, ví en el mismo diario un _cuento ajeno_, firmado por _León de Tinseau_, y titulado _La perla negra_, que, además de la semejanza del título, ofrecía coincidencias de asunto. En ambos cuentos, la pérdida de una perla descubre la falta de una mujer. Leído el cuento de Tinseau, tuve esperanzas de que fuese posterior en fecha al mío, y escribí á Miguel Moya rogándole me dijese dónde lo había encontrado. Al saber que en un libro que lleva por epígrafe _Mon oncle Alcide_, lo encargué á Francia, y ví que estaba impreso hacía tres ó cuatro años. Por lo tanto, á la letra, yo soy quien ha aprovechado una idea de Tinseau. Los que no den crédito á mi afirmación de que ni sospechaba la existencia de _La perla negra_ cuando escribí _La perla rosa_, dueños son de afirmar á su vez que ésta es hija de aquélla. Sin falsa modestia, debo añadir que _La perla rosa_ tiene mejor oriente.\"},{\"heading\":false,\"text\":\"Con igual sinceridad declaro que si el cuento de Tinseau resultase escrito después que el mío, no por eso creería yo á ojos cerrados que era imitación ó copia. Algún celebrado escritor español podría atestiguar que no padezco la obsesión de tomar las coincidencias fortuitas por atentados contra mi propiedad; algún francés podría dar fe de lo mismo. Ideas análogas se les ocurren á escritores contemporáneos sujetos á influencias similares, y no lo dudará nadie que conozca la historia literaria. No insisto, porque he prometido no cansarte, lector, al menos á sabiendas.\"},{\"heading\":false,\"text\":\"Supongo que no necesita apología el hecho de que varios cuentos míos se funden en sucesos reales. Las corrientes vienen y van; hace veinte años, tal vez incurriría en censura de los doctores de la iglesia crítica, no por basar en la realidad ciertos cuentos, sino por inventar de pies á cabeza la inmensa mayoría de los que escribo. Ambos procedimientos, á mi entender, son igualmente lícitos, como lo es el refundir asuntos ya tratados, ó el buscarlos en la tradición y la sabiduría popular ó _folklore_. No hay género más amplio y libre que el cuento; no hay, entre los más insignes, cuentista algo fecundo que no explote todas las canteras y filones, empezando por el de su propia fantasía y siguiendo por los variadísimos que le ofrecen las literaturas antiguas y modernas, escritas y orales. De chascarrillos que corrían de boca en boca se hizo recientemente un libro, redactado por ilustres escritores, y en el Prólogo que lo encabeza, una pluma famosísima consignó el principio de que al cuentista le basta la propiedad de la forma de que sabe revestir el cuento más resobado, trillado y vulgar. El principio estaba ya sancionado por la práctica, y no era necesario el nuevo ejemplo para legitimar lo que de tiempo inmemorial venía practicándose.\"},{\"heading\":false,\"text\":\"Por otra parte, quizás nunca como ahora ha sobreabundado la invención en los cuentistas. Antaño era usual apoderarse de una colección de apólogos ó fábulas orientales--persas ó chinas, árabes ó indianas--y, sin más ceremonias, traduciéndolas y adaptándolas en lenguaje castizo, se graduaba un escritor de cuentista y de moralista. El cuento literario original es relativamente novísimo en las literaturas occidentales: procede de la transformación de la poesía épico-lírica, y tiene precedentes, no sólo en los _fabliaux_ y en los ejemplos de los libros devotos (aun hoy mina inagotable para el cuentista) sino en ciertas composiciones poéticas con argumento; verbi-gracia, las _Cantigas_ de Alfonso el Sabio y las baladas alemanas. Noto particular analogía entre la concepción del cuento y la de la poesía lírica: una y otra son rápidas como un chispazo, y muy intensas--porque á ello obliga la brevedad, condición precisa del _cuento_.--Cuento original que no se concibe de súbito, no cuaja nunca. Días hay--dispensa, lector, estas confidencias íntimas y personales--en que no se me ocurre ni un mal asunto de cuento, y horas en que á docenas se presentan á mi imaginación asuntos posibles, y al par siento impaciencia de trasladarlos al papel. Paseando ó leyendo; en el teatro ó en ferrocarril; al chisporroteo de la llama en invierno y al blando rumor del mar en verano, saltan ideas de cuentos con sus líneas y colores, como las estrofas en la mente del poeta lírico, que suele concebir de una vez el pensamiento y su forma métrica. De las ideas que en tropel me acuden, no aprovecho la mitad; desecho infinitas, no sólo por creerlas desde el primer instante indignas de vivir, sino porque algunas me parecen atrevidas, peligrosas y capaces de horripilarte, ¡oh lector no siempre benévolo! Si esto pasa con las ideas de cosecha propia, en mayor proporción quizás acontece con las que me sugieren los libros viejos, y sobre todo, las que se fundan en datos de la vida real. Por fuerte y viva que supongamos la fantasía de un escritor, jamás llega al límite de la realidad posible. Cuanto pudiésemos fingir, queda muy por bajo de lo verdadero. Llamamos inverosímil á lo inusitado; pero no hay acaecimiento extraño, monstruoso, espeluznante y peregrino que no conozcamos por la realidad. Lo saben los de mi profesión: nunca se puede incorporar á la literatura toda la verdad observada, so pena de ser tildado de extravagante, de escritor descabellado y de bárbaro sin gusto ni delicadeza; y sin embargo, las mayores osadías y crudezas de la pluma, aunque sea de hierro y la mojemos en ácido sulfúrico, son blandenguerías para lo que escribe en caracteres de fuego la realidad tremenda.\"},{\"heading\":false,\"text\":\"He observado el estremecimiento del público ante ciertos cuentos verdaderos. Ahí están, para ejemplo en el presente tomo, _Los buenos tiempos_ y _Sor Aparición_. De _Sor Aparición_ se espantó mucha gente. Releo el cuento despacio y no puedo explicarme tal horror, sino por la crueldad de lo real que palpita en él. La narración pienso que está hecha en términos bien honestos, con el mayor recato y decoro posible; además, he modificado la historia, y presentado á la infeliz enamorada del burlador Camargo cuando ejercita la más rigurosa y ejemplar penitencia. Tantos años de mortificación y de lágrimas la impuse, que deben bastar para sosiego del más asombradizo. La verdad estricta es que ignoro el paradero de la víctima de esa broma infame, dada por uno de nuestros mayores poetas románticos. No sé si entró en un convento, si se entregó á la disipación, ó si vegetó en la indiferencia; pero me ha parecido que, dentro de la concepción ideal del cuento, tenía que expiar su yerro para ennoblecer su desventura. Y cátate que, así y todo, bastante gente se persignó, como se persignó al leer _Los buenos tiempos_, historia trágica de la cual se conservan testimonios y recuerdos todavía. Acaso el público sea hoy mas nervioso é impresionable que en otras épocas; sólo así se comprende que de libros de devoción clásicos y venerables no se pueda extraer un cuento sin que se alborote el cotarro y se desquicie la bóveda celeste. De esto volveremos á hablar, oh lector, cuando publique mis _Cuentos sacro-profanos_.\"},{\"heading\":false,\"text\":\"EMILIA PARDO BAZÁN.\"}]},{\"title\":\"El amor asesinado\",\"blocks\":[{\"heading\":false,\"text\":\"Nunca podrá decirse que la infeliz Eva omitió ningún medio lícito de zafarse de aquel tunantuelo de Amor, que la perseguía sin dejarla punto de reposo.\"},{\"heading\":false,\"text\":\"Empezó poniendo tierra en medio, viajando para romper el hechizo que sujeta al alma á los lugares donde por primera vez se nos aparece el Amor. Precaución inútil, tiempo perdido; pues el pícaro rapaz se subió á la zaga del coche, se agazapó bajo los asientos del tren, más adelante se deslizó en el saquillo de mano, y por último, en los bolsillos de la viajera. En cada punto donde Eva se detenía, sacaba el Amor su cabecita maliciosa y la decía con sonrisa picaresca y confidencial: «No me separo de ti. Vamos juntos».\"},{\"heading\":false,\"text\":\"Entonces Eva, que no se dormía, mandó construir altísima torre bien resguardada con cubos, bastiones, fosos y contrafosos, defendida por guardias veteranos, y con rastrillos y macizas puertas chapeadas y claveteadas de hierro, cerradas día y noche. Pero al abrir la ventana, un anochecer que se asomó agobiada de tedio á mirar el campo y á gozar la apacible y melancólica luz de la luna saliente, el rapaz se coló en la estancia; y si bien le expulsó de ella y colocó rejas dobles, con agudos pinchos, y se encarceló voluntariamente,--sólo consiguió Eva que el Amor entrase por las hendiduras de la pared, por los canalones del tejado ó por el agujero de la llave.\"},{\"heading\":false,\"text\":\"Furiosa, hizo tomar las grietas y calafatear los intersticios, creyéndose á salvo de atrevimientos y demasías: mas no contaba con lo ducho que es en tretas y picardigüelas el Amor. El muy maldito se disolvió en los átomos del aire, y envuelto en ellos se le metió en boca y pulmones, de modo que Eva se pasó el día respirándole, exaltada, loca, con una fiebre muy semejante á la que causa la atmósfera sobresaturada de oxígeno.\"},{\"heading\":false,\"text\":\"Ya fuera de tino, desesperando de poder tener á raya al malvado Amor, Eva comenzó á pensar en la manera de librarse de él definitivamente, á toda costa, sin reparar en medios ni detenerse en escrúpulos. Entre el Amor y Eva, la lucha era á muerte, y no importaba el cómo se vencía, sino sólo obtener la victoria.\"},{\"heading\":false,\"text\":\"Eva se conocía bien, no porque fuese muy reflexiva, sino porque poseía instinto sagaz y certero; y conociéndose, sabía que era capaz de engatusar con maulas y zalamerías al mismo diablo, que no al Amor, de suyo inflamable y fácil de seducir. Propúsose, pues, chasquear al Amor, y desembarazarse de él sobre seguro y traicioneramente, asesinándole.\"},{\"heading\":false,\"text\":\"Preparó sus redes y anzuelos, y poniendo en ellos cebo de flores y de miel dulcísima, atrajo al Amor haciéndole graciosos guiños y dirigiéndole sonrisas de embriagadora ternura y palabras entre graves y mimosas, en voz velada por la emoción, de notas más melodiosas que las del agua cuando se destrenza sobre guijas ó cae suspirando en morisca fuente.\"},{\"heading\":false,\"text\":\"Y el Amor acudió volando, alegre, gentil, feliz, aturdido y confiado como niño, impetuoso y engreído como mancebo, plácido y sereno como varón vigoroso.\"},{\"heading\":false,\"text\":\"Eva le acogió en su regazo; acaricióle con felina blandura; sirvióle golosinas; le arrulló para que se adormeciese tranquilo, y así que le vió calmarse recostando en su pecho la cabeza, se preparó á extrangularle, apretándole la garganta con rabia y brío.\"},{\"heading\":false,\"text\":\"Un sentimiento de pena y lástima la contuvo, sin embargo, breves instantes. ¡Estaba tan lindo, tan divinamente hermoso el condenado Amor aquél! Sobre sus mejillas de nácar, palidecidas por la felicidad, caía una lluvia de rizos de oro, finos como las mismas hebras de la luz; y de su boca purpúrea, risueña aún, de entre la doble sarta de piñones mondados de sus dientes, salía un soplo aromático, igual y puro. Sus azules pupilas, entreabiertas, húmedas, conservaban la languidez dichosa de los últimos instantes; y plegadas sobre su cuerpo de helénicas proporciones, sus alas color de rosa parecían pétalos arrancados. Eva notó ganas de llorar...\"},{\"heading\":false,\"text\":\"No había remedio; tenía que asesinarle si quería vivir digna, respetada, libre... Y cerrando los ojos por no ver al muchacho, apretó las manos enérgicamente, largo, largo tiempo, horrorizada del estertor que oía, del quejido sordo y lúgubre exhalado por el Amor agonizante.\"},{\"heading\":false,\"text\":\"Al fin Eva soltó á su víctima y la contempló... El Amor ni respiraba ni se rebullía: estaba muerto,--tan muerto como mi abuela.\"},{\"heading\":false,\"text\":\"Al punto mismo que se cercioraba de esto, la criminal percibió un dolor terrible, extraño, inexplicable, algo como una ola de sangre que ascendía á su cerebro, y como un aro de hierro que oprimía gradualmente su pecho, asfixiándola. Comprendió lo que sucedía...\"},{\"heading\":false,\"text\":\"El Amor, á quien creía tener en brazos, estaba más adentro, en su mismo corazón, y Eva, al asesinarle, se había suicidado.\"}]},{\"title\":\"El viajero\",\"blocks\":[{\"heading\":false,\"text\":\"Fría, glacial era la noche. El viento silbaba medroso y airado, la lluvia caía tenaz, ya en ráfagas, ya en fuertes chaparrones; y las dos ó tres veces que Marta se había atrevido á acercarse á su ventana por ver si aplacaba la tempestad, la deslumbró la cárdena luz de un relámpago y la horrorizó el rimbombar del trueno, tan encima de su cabeza, que parecía echar abajo la casa.\"},{\"heading\":false,\"text\":\"Al punto en que con más furia se desencadenaban los elementos, oyó Marta distintamente que llamaban á su puerta, y percibió un acento plañidero y apremiante que la instaba á abrir. Sin duda que la prudencia aconsejaba á Marta desoirlo, pues en noche tan espantosa, cuando ningún vecino honrado se atreve á echarse á la calle, sólo los malhechores y los perdidos libertinos son capaces de arrostrar viento y lluvia en busca de aventuras y presa. Marta debió haber reflexionado que el que posee un hogar, fuego en él, y á su lado una madre, una hermana, una esposa que le consuele, no sale en el mes de Enero y con una tormenta desatada, ni llama á puertas ajenas, ni turba la tranquilidad de las doncellas honestas y recogidas. Mas la reflexión, persona dignísima y muy señora mía, tiene el maldito vicio de llegar retrasada, por lo cual sólo sirve para amargar gustos y adobar remordimientos. La reflexión de Marta se había quedado zaguera según costumbre, y el impulso de la piedad, el primero que salta en el corazón de la mujer, hizo que la doncella, al través del postigo, preguntase compadecida: «¿Quién llama?» Voz de tenor dulce y vibrante respondió en tono persuasivo: «Un viajero.» Y la bienaventurada de Marta, sin meterse en más averiguaciones, quitó la tranca, descorrió el cerrojo y dió vuelta á la llave, movida por el encanto de aquella voz tan vibrante y tan dulce.\"},{\"heading\":false,\"text\":\"Entró el viajero, saludando cortesmente; y quitándose con gentil desembarazo el chambergo, cuyas plumas goteaban, y desembozándose la capa, empapada por la lluvia, agradeció la hospitalidad y tomó asiento cerca de la lumbre, bien encendida por Marta. Esta apenas se atrevía á mirarle, porque en aquel punto la consabida tardía reflexión empezaba á hacer de las suyas, y Marta comprendía que dar asilo al primero que llama, es ligereza notoria. Con todo, aun sin decidirse á levantar los ojos, vió de soslayo que su huésped era mozo y de buen talle, descolorido, rubio, cara linda y triste, aire de señor acostumbrado al mando y á ocupar alto puesto. Sintióse Marta encogida y llena de confusión, aunque el viajero se mostraba reconocido y la decía cosas halagüeñas, que por el hechizo de la voz lo parecían más; y á fin de disimular su turbación, se dió prisa á servir la cena y ofrecer al viajero el mejor cuarto de la casa, donde se recogiese á dormir.\"},{\"heading\":false,\"text\":\"Asustada de su propia indiscreta conducta, Marta no pudo conciliar el sueño en toda la noche, esperando con impaciencia que rayase el alba para que se ausentase el huésped. Y sucedió que éste, cuando bajó, ya descansado y sonriente, á tomar el desayuno, nada habló de marcharse, ni tampoco á la hora de comer, ni menos por la tarde; y Marta, entretenida y embelesada con su labia y sus paliques, no tuvo valor para decirle que ella no era mesonera de oficio.\"},{\"heading\":false,\"text\":\"Corrieron semanas, pasaron meses, y en casa de Marta no había más dueño ni más amo que aquel viajero á quien en una noche tempestuosa tuvo la imprevisión de acoger. El mandaba, y Marta obedecía sumisa, muda, veloz como el pensamiento.\"},{\"heading\":false,\"text\":\"No creáis por eso que Marta era propiamente feliz. Al contrario, vivía en continua zozobra y pena. He calificado de amo al viajero, y tirano debí llamarle, pues sus caprichos despóticos y su inconstante humor traían á Marta medio loca. Al principio el viajero parecía obediente, afectuoso, zalamero, humilde; pero fué creciéndose y tomando fueros, hasta no haber quien le soportase. Lo peor de todo era que nunca podía Marta adivinarle el deseo ni precaverle la desazón: sin motivo ni causa, cuando menos debía temerse ó esperarse, estaba frenético ó contentísimo, pasando, en menos que se dice, del enojo al halago y de la risa á la rabia. Padecía arrebatos de furor y berrinches injustos é insensatos, que á los dos minutos se convertían en transportes de cariño y en placideces angelicales; ya se emperraba como un chico, ya se desesperaba como un hombre; ya hartaba á Marta de improperios, ya la prodigaba los nombres más dulces y las ternezas más rendidas.\"},{\"heading\":false,\"text\":\"Sus extravagancias eran á veces tan insufribles, que Marta, con los nervios de punta, el alma de través y el corazón á dos dedos de la boca, maldecía el fatal momento en que dió acogida á su terrible huésped. Lo malo es que cuando justamente Marta, apurada la paciencia, iba á saltar y á sacudir el yugo, no parece sino que él lo adivinaba, y pedía perdón con una sinceridad y una gracia de chiquillo, por lo cual Marta no sólo olvidaba instantáneamente sus agravios, sino que, por el exquisito goce de perdonar, sufriría tres veces las pasadas desazones.\"},{\"heading\":false,\"text\":\"¡Qué en olvido las tenía puestas,... cuando el huésped, á medias palabras y con precauciones y rodeos, anunció que _ya_ había llegado la ocasión de su partida! Marta se quedó de mármol, y las lágrimas lentas que la arrancó la desesperación cayeron sobre las manos del viajero, que sonreía tristemente y murmuraba en voz baja frasecitas consoladoras, promesas de escribir, de volver, de recordar. Y como Marta, en su amargura, balbucía reproches, el huésped, con aquella voz de tenor dulce y vibrante, alegó por vía de disculpa: «Bien te dije, niña, que soy un viajero. Me detengo, pero no me estaciono; me poso, no me fijo.» Y habéis de saber que sólo al oir esta declaración franca, sólo al sentir que se desgarraban las fibras más íntimas de su ser, conoció la inocentona de Marta que aquel fatal viajero era el Amor, y que había abierto la puerta, sin pensarlo, al dictador cruelísimo del orbe.\"},{\"heading\":false,\"text\":\"Sin hacer caso del llanto de Marta (¡para atender á lagrimitas está él!), sin cuidarse del rastro de pena inextinguible que dejaba en pos de sí, el Amor se fué, embozado en su capa, ladeado el chambergo--cuyas plumas, secas ya, se rizaban y flotaban al viento bizarramente--en busca de nuevos horizontes, á llamar á otras puertas mejor trancadas y defendidas. Y Marta quedó tranquila, dueña de su hogar, libre de sustos, de temores, de alarmas, y entregada á la compañía de la grave y excelente reflexión, que tan bien aconseja, aunque un poquillo tarde. No sabemos lo que habrán platicado; sólo tenemos noticias ciertas de que las noches de tempestad furiosa, cuando el viento silba y la lluvia se estrella contra los vidrios, Marta, apoyando la mano sobre su corazón, que la duele á fuerza de latir apresurado, no cesa de prestar oído, por si llama á la puerta el huésped.\"}]},{\"title\":\"El corazón perdido\",\"blocks\":[{\"heading\":false,\"text\":\"Yendo una tardecita de paseo por las calles de la ciudad, vi en el suelo un objeto rojo: me bajé: era un sangriento y vivo corazón que recogí cuidadosamente. Debe de habérsele perdido á alguna mujer--pensé al observar la blandura y delicadeza de la tierna víscera que, al contacto de mis dedos, palpitaba como si estuviese todavía dentro del pecho de su dueña.--Lo envolví con esmero en un blanco paño, lo abrigué, lo escondí bajo mi ropa, y me dediqué á averiguar quien era la mujer que había perdido el corazón en la calle. Para indagar mejor, adquirí unos maravillosos anteojos, que permitían ver, al través del corpiño, de la ropa interior, de la carne y de las costillas--como por esos relicarios que son el busto de una santa y tienen en el pecho una ventanita de cristal--el lugar que ocupa el corazón.\"},{\"heading\":false,\"text\":\"Apenas me hube calado mis anteojos mágicos, miré ansiosamente á la primera mujer que pasaba, y ¡oh asombro! la mujer no tenía corazón. Ella debía de ser, sin duda, la propietaria de mi hallazgo. Lo raro fué que, al decirla yo cómo había encontrado su corazón y lo conservaba á sus órdenes por si gustaba recogerlo, la mujer indignada juró y perjuró que no había perdido cosa alguna; que su corazón estaba donde solía y que lo sentía perfectamente pulsar, recibir y expeler la sangre. En vista de la terquedad de la mujer, la dejé y me volví hacia otra, joven, linda, seductora, alegre. ¡Dios santo! En su blanco pecho vi la misma oquedad, el mismo agujero rosado, sin nada allá dentro, nada, nada. ¡Tampoco ésta tenía corazón! Y cuando la ofrecí respetuosamente el que yo llevaba guardadito, menos aún lo quiso admitir, alegando que era ofenderla de un modo grave suponer que ó la faltaba el corazón, ó era tan descuidada que había podido perderlo así en la vía pública sin que lo advirtiese.\"},{\"heading\":false,\"text\":\"Y pasaron centenares de mujeres, viejas y mozas, lindas y feas, morenas y pelirrubias, melancólicas y vivarachas; y á todas las eché los anteojos y en todas noté que del corazón sólo tenían el sitio, pero que el órgano, ó no había existido nunca, ó se había perdido tiempos atrás. Y todas, todas sin excepción alguna, al querer yo devolverles el corazón de que carecían, negábanse á aceptarlo, ya porque creían tenerlo, ya porque sin él se encontraban divinamente, ya porque se juzgaban injuriadas por la oferta, ya porque no se atrevían á arrostrar el peligro de poseer un corazón.--Iba desesperando de restituir á un pecho de mujer el pobre corazón abandonado, cuando por casualidad, con ayuda de mis prodigiosos lentes, acerté á ver que pasaba por la calle una niña pálida, y en su pecho ¡por fin! distinguí un corazón, un verdadero corazón de carne, que saltaba, latía y sentía. No sé por qué--pues reconozco que era un absurdo brindar corazón á quien lo tenía tan vivo y tan despierto--se me ocurrió hacer la prueba de presentarla el que habían desechado todas; y he aquí que la niña, en vez de rechazarme como las demás, abrió el seno y recibió el corazón que yo, en mi fatiga, iba á dejar otra vez caído sobre los guijarros.\"},{\"heading\":false,\"text\":\"Enriquecida con dos corazones, la niña pálida se puso mucho más pálida aún: las emociones, por insignificantes que fuesen, la estremecían hasta la médula; los afectos vibraban en ella con cruel intensidad; la amistad, la compasión, la tristeza, la alegría, el amor, los celos, todo era en ella profundo y terrible; y la muy necia, en vez de resolverse á suprimir uno de sus dos corazones, ó los dos á un tiempo, diríase que se complacía en vivir doble vida espiritual queriendo, gozando y sufriendo por duplicado, sumando impresiones de esas que bastan para extinguir la vida. La criatura era como vela encendida por los dos cabos, que se consume en breves instantes. Y, en efecto, se consumió. Tendida en su lecho de muerte, lívida y tan demacrada y delgada que parecía un pajarillo, vinieron los médicos y aseguraron que, lo que la arrebataba de este mundo era la ruptura de un aneurisma. Ninguno (¡son tan torpes!) supo adivinar la verdad: ninguno comprendió que la niña se había muerto por cometer la imprudencia de dar asilo en su pecho á un corazón perdido en la calle.\"}]},{\"title\":\"Mi suicidio\",\"blocks\":[{\"heading\":false,\"text\":\"A Campoamor.\"},{\"heading\":false,\"text\":\"Muerta _ella_; tendida, inerte, en el horrible ataúd de barnizada caoba que aun me parecía ver con sus doradas molduras de antipático brillo, ¿qué me restaba en el mundo ya? En ella cifraba yo mi luz, mi regocijo, mi ilusión, mi delicia toda... y desaparecer así, de súbito, arrebatada en la flor de su juventud y de su seductora belleza, era tanto como decirme con melodiosa voz--la voz mágica, la voz que vibraba en mi interior produciendo acordes divinos: «Pues me amas, sígueme.»\"},{\"heading\":false,\"text\":\"¡Seguirla! Sí; era la única resolución digna de mi cariño, á la altura de mi dolor, y el remedio para el eterno abandono á que me condenaba la adorada criatura huyendo á lejanas regiones. Seguirla, reunirme con ella, sorprenderla en la otra orilla del río fúnebre... y estrecharla delirante, exclamando: «Aquí estoy. ¿Creías que viviría sin tí? Mira como he sabido buscarte y encontrarte y evitar que de hoy más nos separe poder alguno de la tierra ni del cielo.»\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"Determinado á realizar mi propósito, quise verificarlo en aquel mismo aposento donde se deslizaron insensiblemente tantas horas de ventura, medidas por el suave ritmo de nuestros corazones... Al entrar olvidé la desgracia, y pareciome que _ella_, viva y sonriente, acudía como otras veces á mi encuentro, levantando la cortina para verme más pronto, y dejando irradiar en sus pupilas la bienvenida, y en sus mejillas el arrebol de la felicidad.--Allí estaba el amplio sofá donde nos sentábamos tan juntos como si fuese estrechísimo; allí la chimenea hacia cuya llama tendía los piececitos, y á la cual yo, envidioso, los disputaba abrigándolos con mis manos, donde cabían holgadamente; allí la butaca donde se aislaba, en los cortos instantes de enfado pueril que duplicaban el precio de las reconciliaciones; allí la gorgona de irisado vidrio de Salviati, con las últimas flores, ya secas y pálidas, que su mano había dispuesto artísticamente para festejar mi presencia... Y allí, por último, como maravillosa resurrección del pasado, inmortalizando su adorable forma, ella, ella misma... es decir, su retrato, su gran retrato de cuerpo entero, obra maestra de célebre artista, que la representaba sentada, vistiendo uno de mis trajes preferidos, la sencilla y cándida bata de blanca seda que la envolvía en una nube de espuma. Y era su actitud familiar, y eran sus ojos verdes y lumínicos que me fascinaban, y era su boca entreabierta, como para exclamar, entre halago y reprensión, el «¡qué tarde vienes!» de la impaciencia cariñosa; y eran sus brazos redondos, que se ceñían á mi cuello como la ola al tronco del náufrago, y era, en suma, el fidelísimo trasunto de los rasgos y colores, al través de los cuales me había cautivado un alma; imagen encantadora que significaba para mí lo mejor de la existencia... Allí, ante todo cuanto me hablaba de ella y me recordaba nuestra unión; allí, al pie del querido retrato, arrodillándome en el sofá, debía yo apretar el gatillo de la pistola inglesa de dos cañones--que lleva en su seno el remedio de todos los males y el pasaje para arribar al puerto donde _ella_ me aguardaba...--Así no se borraría de mis ojos ni un segundo su efigie: los cerraría mirándola, y volvería á abrirlos, viéndola no ya en pintura, sino en espíritu...\"},{\"heading\":false,\"text\":\"La tarde caía; y como deseaba contemplar á mi sabor el retrato al apoyar en la sien el cañón de la pistola, encendí la lámpara y todas las bujías de los candelabros. Uno de tres brazos había sobre el _secreter_ de palo de rosa con incrustaciones, y al acercar al pábilo el fósforo, se me ocurrió que allí dentro estarían mis cartas, mi retrato, los recuerdos de nuestra dilatada é íntima historia. Un vivaz deseo de releer aquellas páginas me impulsó á abrir el mueble.\"},{\"heading\":false,\"text\":\"Es de advertir que yo no poseía cartas de ella: las que recibía devolvíalas una vez leídas, por precaución, por respeto, por caballerosidad. Pensé que acaso ella no había tenido valor para destruirlas, y que de los cajoncitos del secreter volvería á alzarse su voz insinuante y adorada, repitiendo las dulces frases que no habían tenido tiempo de grabarse en mi memoria. No vacilé--¿vacila el que va á morir?--en descerrajar con violencia el primoroso mueblecillo. Saltó en astillas la cubierta, y metí la mano febrilmente en los cajoncitos, revolviéndolos ansioso.\"},{\"heading\":false,\"text\":\"Sólo en uno había cartas.--Los demás los llenaban cintas, joyas, dijecillos, abanicos y pañuelos perfumados.--El paquete, envuelto en un trozo de rica seda brochada, lo tomé muy despacio, lo palpé como se palpa la cabeza del ser querido antes de depositar en ella un beso, y acercándome á la luz, me dispuse á leer. Era letra de ella: eran sus queridas cartas. Y mi corazón agradecía á la muerta el delicado refinamiento de haberlas guardado allí, como testimonio de su pasión, como codicilo en que me legaba su ternura.\"},{\"heading\":false,\"text\":\"Desaté, desdoblé, empecé á deletrear... Al pronto creía recordar las candentes frases, las apasionadas protestas y hasta las alusiones á detalles íntimos, de esos que sólo pueden conocer des personas en el mundo. Sin embargo, á la segunda carilla, un indefinible malestar, un terror vago, cruzaron por mi imaginación, como cruza la bala por el aire antes de herir. Rechacé la idea; la maldije; pero volvió, volvió... y volvió apoyada en los párrafos de la carilla tercera, donde ya hormigueaban rasgos y pormenores imposibles de referir á mi persona y á la historia de mi amor... A la cuarta carilla, ni sombra de duda pudo quedarme: la carta se había escrito á otro, y recordaba otros días, otras horas, otros sucesos, para mí desconocidos...\"},{\"heading\":false,\"text\":\"Repasé el resto del paquete; recorrí las cartas una por una, pues todavía la esperanza terca me convidaba á asirme de un clavo ardiendo... Quizá las demás cartas eran las mías, y sólo aquella se había deslizado en el grupo como aislado memento de una historia vieja y relegada al olvido... Pero al examinar los papeles; al descifrar, frotándome los ojos, un párrafo aquí y otro acullá, hube de convencerme: ninguna de las epístolas que contenía el paquete había sido dirigida á mí... Las que yo recibí y restituí con religiosidad, probablemente se encontraban incorporadas á la ceniza de la chimenea; y las que, como un tesoro, _ella_ había conservado siempre, en el oculto rincón del secreter, en el aposento testigo de nuestra ventura... señalaban, tan exactamente como la brújula señala el norte, la dirección verdadera del corazón que yo juzgara orientado hacia el mío... ¡Más dolor, más infamia! De los terribles párrafos, de las páginas surcadas por rengloncitos de una letra que yo hubiese reconocido entre todas las del mundo saqué en limpio que _tal vez_... al _mismo tiempo_ ó _muy poco antes_... Y una voz irónica gritábame al oído: «Ahora sí... ahora sí que debes suicidarte, desdichado!»\"},{\"heading\":false,\"text\":\"Lágrimas de rabia escaldaron mis pupilas; me coloqué, según había resuelto, frente al retrato; empuñé la pistola, alcé el cañón... y apuntando fríamente, sin prisa, sin que me temblase el pulso... con los dos tiros... reventé los dos verdes y lumínicos ojos, que me fascinaban.\"}]},{\"title\":\"La última ilusión de Don Juan\",\"blocks\":[{\"heading\":false,\"text\":\"Las gentes superficiales, que nunca se han tomado el trabajo de observar al microscopio la complicada mecánica del corazón, suponen buenamente que á don Juan, el precoz libertino, el burlador sempiterno, le bastan para su satisfacción los sentidos y á lo sumo la fantasía, y que no necesita ni gasta el inútil lujo del sentimiento, ni abre nunca el dorado ajimez donde se asoma el espíritu para mirar al cielo cuando el peso de la tierra le oprime. Y yo os digo en verdad que eses gentes superficiales se equivocan de medio á medio y son injustas con el pobre don Juan, á quien sólo hemos comprendido los poetas, los que tenemos el alma inundada de caridad y somos perspicaces... cabalmente porque, cándidos en apariencia, creemos en muchas cosas.\"},{\"heading\":false,\"text\":\"A fin de poner la verdad en su punto, os contaré la historia de cómo alimentó y sostuvo don Juan su última ilusión... y cómo vino á perderla.\"},{\"heading\":false,\"text\":\"Entre la numerosa parentela de don Juan--que dicho sea de paso, es hidalgo como el Rey--se cuentan unas primitas provincianas muy celebradas de hermosas. La más joven, Estrella, se distinguía de sus hermanas por la dulzura del carácter, la exaltación de la virtud y el fervor de la religiosidad, por lo cual en su casa la llamaban _la beatita_. Su rostro angelical no desmentía las cualidades del alma: parecíase á una Virgen de Murillo, de las que respiran honestidad y pureza (porque algunas, como la morena _de la servilleta_, llamada _Refitolera_, sólo respiran juventud y vigor). Siempre que el humor vagabundo de don Juan le impulsaba á darse una vuelta por la región donde vivían sus primas, iba á verlas, frecuentaba su trato, y pasaba con Estrella pláticas interminables. Si me preguntáis qué imán atraía al perdido hacia la santa, y más aún á la santa hacia el perdido, os diré que era quizás el mismo contraste de sus temperamentos... y después de esta explicación, nos quedaremos tan enterados como antes.\"},{\"heading\":false,\"text\":\"Lo cierto es que mientras don Juan galanteaba por sistema á todas las mujeres, con Estrella hablaba en serio, sin permitirse la más mínima insinuación atrevida; y que mientras Estrella rehuía el trato de todos los hombres, veníase á la mano de don Juan como la mansa paloma, confiada, segura de no mancharse el plumaje blanco. Las conversaciones de los primos podía oirlas el mundo entero: después de horas de charla inofensiva, reposada y dulce, levantábanse tan dueños de sí mismos, tan tranquilos, tan venturosos, y Estrella volaba á la cocina ó á la despensa á preparar con esmero algún plato de los que sabía que agradaban á don Juan. Saboreaba éste, más que las golosinas, el mimo con que se las presentaban, y la frescura de su sangre y la anestesia de sus sentidos le hacían bien, como un refrigerante baño al que caminó largo tiempo por abrasados arenales.\"},{\"heading\":false,\"text\":\"Cuando don Juan levantaba el vuelo, yéndose á las grandes ciudades en que la vida es fiebre y locura, Estrella le escribía difusas cartas, y él contestaba en pocos renglones,--pero siempre.--Al retirarse á su casa al amanecer, tambaleándose, aturdido por la bacanal ó vibrantes aún sus nervios de las violentas emociones de la profana cita; al encerrarse para mascar, entre risa irónica, la hiel de un desengaño--porque también don Juan los cosecha;--al prepararse al lance de honor templando la voluntad para arrostrar impávido la muerte; al reir, al blasfemar, al derrochar su mocedad y su salud cual pródigo insensato de los mejores bienes que nos ofrece el cielo, don Juan reservaba y apartaba, como se aparta el dinero para una ofrenda á Nuestra Señora, diez minutos que dedicar á Estrella. En su ambición de cariño, aquella casta consagración de un ser tan delicado y noble representaba el sorbo de agua que se bebe en medio del combate y restituye al combatiente fuerzas para seguir lidiando. Traiciones, falsías, perfidias y vilezas de otras mujeres podían llevarse en paciencia, mientras en un rincón del mundo alentase el leal afecto de Estrella la beatita. A cada carta ingenua y encantadora que recibía don Juan, soñaba el mismo sueño; se veía caminando difícilmente por entre tinieblas muy densas, muy frías, casi palpables, que rasgaban por intervalos la luz sulfurosa del relámpago y el culebreo del rayo; pero allá lejos, muy lejos, donde ya el cielo se esclarecía un poco, divisaba don Juan blanca figura velada, una mujer con los ojos bajos, sosteniendo en la diestra una lamparita encendida y protegiéndola con la izquierda. Aquella luz no se apagaba jamás.\"},{\"heading\":false,\"text\":\"En efecto, corrían años; don Juan se precipitaba más, despeñado por la pendiente de su delirio, y las cartas continuaban con regularidad inalterable, impregnadas de igual ternura latente y serena. Eran tan gratas á don Juan estas cartas, que había determinado no volver á ver á su prima nunca, temeroso de encontrarla desmejorada y cambiada por el tiempo, y no tener luego ilusión bastante para sostener la correspondencia. A toda costa deseaba eternizar su ensueño, ver siempre á Estrella con rostro murillesco, de santita virgen de veinte años. Las epístolas de don Juan, á la verdad, expresaban vivo deseo de hacer á su prima una visita, de renovar la charla sabrosa; pero como nadie le impedía á don Juan realizar este propósito, hay que creer, pues no lo realizaba, que no debía de apretarle mucho.\"},{\"heading\":false,\"text\":\"Eran pasados dos lustros, cuando un día recibió don Juan, en vez del ancho pliego acostumbrado, escrito por las cuatro carillas y cruzado después, una esquelita sin cruzar, grave y reservada en su estilo, y en que hasta la letra carecía del abandono que imprime la efusión del espíritu guiando la mano y haciéndola acariciar, por decirlo así, el papel. ¡Oh mujer, oh agua corriente, oh llama fugaz, oh soplo de aire! Estrella pedía á don Juan que ni se sorprendiese ni se enojase, y le confesaba que iba á casarse muy pronto... Se había presentado un novio á pedir de boca, un caballero excelente, rico, honrado, á quien el padre de Estrella debía atenciones sin cuento; y los consejos y exhortaciones de _todos_ habían decidido á la santita,--que esperaba, con la ayuda de Dios, ser dichosa en su nuevo estado y ganar el cielo.\"},{\"heading\":false,\"text\":\"Quedó don Juan absorto breves instantes; luego arrugó el papel y lo lanzó con desprecio á la encendida chimenea. ¡Pensar que si alguien le hubiese dicho dos horas antes que podía casarse Estrella, al tal le hubiese tratado de bellaca calumniador! ¡Y se lo participaba ella misma, sin rubor, como el que cuenta la cosa más natural y lícita del mundo!\"},{\"heading\":false,\"text\":\"Desde aquel día don Juan, el alegre libertino, ha perdido su última ilusión; su alma va peregrinando entre sombras, sin ver jamás el resplandorcito de la lámpara suave que una virgen protege con la mano; y el que aún tenía algo de hombre, es solo fiera, con dientes para morder y garras para destrozar sin misericordia. Su profesión de fe es una carcajada cínica, su amor un latigazo que quema y arranca la piel haciendo brotar la sangre...\"},{\"heading\":false,\"text\":\"Me diréis que la santita tenía derecho á buscar felicidades reales y goces siempre más puros que los que libaba sin tregua su desenfrenado ídolo. Y acaso diréis muy bien, según el vulgar sentido común y la enana razoncilla práctica. ¡Que esa enteca razón os aproveche! En el sentir de los poetas, menos malo es ser galeote, del vicio que desertor del ideal. La santita pecó contra la poesía y contra los sueños divinos del amor irrealizable.--Don Juan, creyendo en su abnegación eterna, era, de los dos, el verdadero soñador.\"}]},{\"title\":\"Desquite\",\"blocks\":[{\"heading\":false,\"text\":\"Trifón Liliosa nació raquítico y contrahecho, y tuvo la malaventura de no morirse en la niñez. Con los años creció más que su cuerpo su fealdad, y se desarrolló su imaginación combustible, su exaltado amor propio y su nervioso temperamento de artista y de ambicioso. A los quince, Trifón, huérfano de madre desde la cuna, no había escuchado una palabra cariñosa; en cambio había aguantado innumerables torniscones, sufrido continuas burlas y desprecios, y recibido el apodo de _Fenómeno_; á los diez y siete se escapaba de su casa, y, aprovechando lo poco que sabía de música, se contrataba en una murga, en una orquesta después. Sus rápidos adelantos le entreabrieron el paraíso: esperó llegar á ser un compositor genial, un Weber, un Listz. Adivinaba en toda su plenitud la magnificencia de la gloria, y ya se veía festejado, aplaudido, olvidada su deformidad, disimulada y cubierta por un haz de balsámicos laureles. La edad viril--¿pueden llamarse así los treinta años de un escuerzo?--disipó estas quimeras de la juventud. Trifón Liliosa hubo de convencerse de que era uno de los muchos llamados y no escogidos; de los que ven cercana la tierra de promisión, pero no llegan nunca á pisar sus floridos valles. La pérdida de ilusiones tales deja el alma muy negra, muy ulcerada, muy venenosa. Cuando Trifón se resignó á no pasar nunca de maestro de música á domicilio, tuvo un ataque de ictericia tan cruel, que la bilis le rebosaba hasta por los amarillentos ojos.\"},{\"heading\":false,\"text\":\"Lecciones le salían á docenas, no sólo porque era en realidad un excelente profesor, sino porque tranquilizaba á los padres su ridícula facha y su corcova. ¿Qué señorita, ni la más impresionable, iba á correr peligro con aquel macaco, cuyo talle era un jarrón, cuyas manos desproporcionadas parecían, al vagar sobre las teclas, arañas pálidas á medio despachurrar? Y se lo espetó en su misma cara, sin reparo alguno--al llamarle para enseñar á su hija canto y piano,--la madre de la linda María Vega. Sólo á un sujeto «así como él», le permitiría acercarse á niña tan candorosa y tan sentimental. ¡Mientras mayor inocencia en las criaturas, más prudencia y precaución en las madres!\"},{\"heading\":false,\"text\":\"Con todo, no era prudente, y menos aún delicada y caritativa la franqueza de la señora. Nadie debe ser la gota de agua que hace desbordar el vaso de amargura, y por muy convencido que esté de su miseria el miserable, recia cosa es arrojársela al rostro. Pensó sin duda la inconsiderada señora que Trifón, habiéndose mirado al espejo, sabría de sobra que era un monstruo; y ciertamente, Trifón se había mirado y conocía su triste catadura; y así y todo le hirió, como hiere el insulto cobarde, la frase que le excluía del número de los hombres; y aquella noche misma, revolviéndose en su frío lecho, mordiendo de rabia las sábanas, decidió entre sí: «Esta pagará por todas: ésta será mi desquite. ¡La necia de la madre, que sólo ha mirado mi cuerpo, no sabe que con el espíritu se puede seducir á las mujeres que tienen espíritu también!»\"},{\"heading\":false,\"text\":\"Al día siguiente empezaron las lecciones de María, que era en efecto una niña celestial, fina y lánguida como una rosa blanca, de esas que para marchitarlas basta un soplo de aire. Acostumbrado Trifón á que sus discípulas sofocasen la carcajada cuando le veían por primera vez, notó que María, al contrario, le miraba con lástima infinita, y la piedad de la niña, en vez de conmoverle, ahincó su resolución implacable. Bien fácil le fué observar que la nueva discípula poseía un alma delicada, una exquisita sensibilidad, y la música producía en ella impresión profunda, humedeciéndose sus azules ojos en las páginas melancólicas, mientras las melodías apasionadas apresuraban su aliento. La soledad y retiro en que vivía hasta que se vistiese de largo y recogiese en abultado moño su hermosa mata de pelo de un rubio de miel, la hacían más propensa á exaltarse y á soñar. Por experiencia conocía Trifón esta manera de ser, y cuanto predispone á la credulidad y á las aspiraciones novelescas. Cautamente, á modo de criminal reflexivo que prepara el atentado, observaba los hábitos de María, las horas á que bajaba al jardín, los sitios donde prefería sentarse, los tiestos que cuidaba ella sola; y prolongando la lección sin extrañeza ni recelo de los padres, eligiendo la música mas perturbadora, cultivaba el ensueño enfermizo á que María iba á entregarse.\"},{\"heading\":false,\"text\":\"Dos ó tres meses hacía que la niña estudiaba música, cuando una mañana, al pie de cierta maceta que regaba todos los días, encontró un billetito doblado. Sorprendida, abrió y leyó. Más que declaración amorosa, era un suave preludio de ella: no tenía firma, y el autor anunciaba que no quería ser conocido, ni pedía respuesta alguna: se contentaba con expresar sus sentimientos, muy apacibles y de una pureza ideal. María, pensativa, rompió el billete; pero al otro día, al regar la maceta, su corazón quería salirse del pecho y temblaba su mano, salpicando de menudas gotas de agua su traje. Corrida una semana, nuevo billete,--tierno, dulce, poético, devoto;--pasada otra más, dos pliegos rendidos, pero ya insinuantes y abrasadores. La niña no se apartaba del jardín, y á cada ruido del viento en las hojas pensaba ver aparecerse al desconocido, bizarro, galán, diciendo de perlas lo que de oro escribía. Mas el autor de los billetes no se mostraba, y los billetes continuaban, elocuentes, incendiarios, colocados allí por invisible mano, solicitando respuestas y esperanzas. Después de no pocas vacilaciones, y con harta vergüenza, acabó la niña por trazar unos renglones, que depositó en la maceta, besándola;--eran la ingenua confesión de su amor virginal.--Varió entonces el tono de las cartas: de respetuosas se hicieron arrogantes y triunfales; parecían un himno; pero el incógnito no quería presentarse; temía perder lo conquistado; ¿á qué ver la envoltura física de un alma? ¿qué le importaba á María el barro en que se agitaba un corazón? Y María, entregado ya completamente el albedrío á su enamorado misterioso, ansiaba contemplarle, comerle con los ojos, segura de que sería un dechado de perfecciones, el sér más bello de cuantos pisan la tierra. Ni cabía menos en quien de tan expresiva manera y con tal calor se explicaba, que María, sólo con releer los billetes, se sentía morir de turbación y gozo. Por fin, después de muchas y muy regaladas ternezas que se cruzaron entre el invisible y la reclusa, María recibió una epístola, que decía en substancia: «Quiero que vengas á mí»; y después de una noche de desvelo, zozobra, llanto y remordimiento, la niña ponía en la maceta la contestación terrible: «Iré cuando y como quieras.»\"},{\"heading\":false,\"text\":\"¡Oh! ¡Qué temblor de alegría maldita asaltó á Trifón, el monstruo, el ridículo _Fenómeno_, al punto en que, dentro del carruaje sin faroles donde la esperaba, recibió á María con los brazos! La completa obscuridad de la noche--escogida, de boca de lobo--no permitía á la pobre enamorada ni entrever siquiera las facciones del seductor... Pero, balbuciente, desfallecida, con explosión de cariño sublime, entre aquellas tinieblas, María pronunció bajo, al oído del ser deforme y contrahecho, las palabras que éste no había escuchado nunca, las rotas frases divinas que arranca á la mujer de lo más secreto de su pecho la vencedora pasión... y una gota de humedad deliciosa, refrigerante como el manantial que surte bajo las palmeras y refresca la arena del Sahara, mojó la mejilla demacrada del corcovado... El efecto de aquellas palabras, de aquella sagrada lágrima infantil, fué que Trifón, sacando la cabeza por la ventanilla, dió en voz ronca una orden, y el coche retrocedió, y pocos minutos después María, atónita, volvía á entrar en su domicilio por la misma puerta del jardín que había favorecido la fuga.\"},{\"heading\":false,\"text\":\"Gran sorpresa la de los padres de María cuando se enteraron de que Trifón no quería dar más lecciones en aquella casa; pero mayor la incredulidad de los contados amigos que Trifón posee, cuando le oyen decir alguna vez, torvo, suspirando y agachando la cabeza:\"},{\"heading\":false,\"text\":\"--También á mí me ha querido, ¡y mucho! ¡y desinteresadamente!, una mujer preciosa...\"}]},{\"title\":\"El dominó verde\",\"blocks\":[{\"heading\":false,\"text\":\"Increíble me pareció que me dejase en paz aquella mujer, que ya no intentase verme, que no me escribiese carta sobre carta, que no apelase á todos los medios imaginables para acercarse á mí. Al romper la cadena de su agobiador cariño, respiré cual si me hubiese quitado de encima un odio jurado y mortal.\"},{\"heading\":false,\"text\":\"Quien no haya estudiado las complicaciones de nuestro espíritu, tendrá por inverosímil que tanto deseemos desatar lazos que nadie nos obligó á atar, y hasta deplorará que mientras las fieras y los animales brutos agradecen á su modo el apego que se les demuestra, el hombre, más duro é insensible, se irrite porque le halagan, y aborrezca á veces á la mujer que le brinda amor. Mas no es culpa nuestra si de este barro nos amasaron, si el sentimiento que no compartimos nos molesta y acaso nos repugna, si las señales de la pasión que no halla eco en nosotros nos incitan á la mofa y al desprecio, y si nos gozamos en pisotear un corazón, por lo mismo que sabemos que ha de palpitar y verter sangre bajo nuestros crueles pies.\"},{\"heading\":false,\"text\":\"Lo cierto es que yo, cuando ví que por fin guardaba silencio María, cuando transcurrió un mes sin recibir recados ni epístolas delirantes y húmedas de lágrimas, me sentí tan bien, tan alegre, que me lancé al mundo con el ímpetu de un colegial en vacaciones, con ese deseo é instinto de renovación íntima que parece que da nuevo y grato sabor á la existencia. Acudí á los paseos, frecuenté los teatros, admití convites, concurrí á saraos y tertulias, y hasta busqué diversiones de vuelo bajo, á manera de hambriento que no distingue de comidas. En suma, me desaté, movido por un instinto miserable, de humorística venganza, que se tradujo en el deseo de regalar á cualquier mujer, á la primera que tropezase casualmente, los momentos de fugaz embriaguez que negaba á María--á María triste y pálida, á María medio loca por mi abandono, á María enferma, desesperada, herida en lo más íntimo por mi implacable desdén.\"},{\"heading\":false,\"text\":\"Es la casualidad tan antojadiza en esto de proporcionar aventuras, que si á veces presenta ocasiones en ramillete, otras no brinda una por un ojo de la cara. En muchos días de disipación y bureo, de rodar por distintas esferas sociales pidiendo guerra, no encontré nada que me tentase; y ya mi capricho se exaltaba, cuando el domingo de Carnestolendas, aburrido y por matar el tiempo, entré en el insípido baile de máscaras del Teatro Real.\"},{\"heading\":false,\"text\":\"Transcurrida más de una hora, sentí que empezaba á hastiarme, y reflexionaba sobre la conveniencia de tomar la puerta y refugiarme entre sábanas cortando las hojas de un libro nuevo de favorito autor, á tiempo que cruzó entre el remolino del abigarrado tropel una máscara envuelta en amplio dominó de rica seda verde. Era la máscara de fino porte y trazas señoriles, cosa ya de suyo extraña en aquel baile, y noté que con singular insistencia clavaba en mí los ojos como si desease acercarse y no se atreviese, á pesar de las franquicias del antifaz. La chispa de las pupilas ardientes de la máscara determinó en mí un repentino interés, una especie de emoción de la cual me reí por dentro, pero que me impulsó á hendir la multitud y aproximarme á la encubierta. Al ir consiguiéndolo, me convencí más y más de que la del verde dominó era dama, y dama muy principal, y que sólo la curiosidad ó algún empeño más hondo, debía de haberla arrastrado á un baile de tan mal género. «Grande será el interés que la trajo aquí--pensé--y muy visible su posición en la sociedad, para que se venga así, sin la compañía de una amiga, sin el brazo protector de un hombre. A toda costa quiere que se ignore el lance; que nadie la pueda delatar.» Y al advertir que seguía mirándome, que sus ojos me buscaban enmedio del gentío, ocurrióseme que aquel interés decisivo podía ser yo.\"},{\"heading\":false,\"text\":\"Con tal suposición dió un vuelco mi sangre, y jugando los codos y las rodillas lo mejor que supe, pugné por alcanzar á la gentil encapuchada. La multitud, desgraciadamente, se arremolinaba compacta y densa, formando viva muralla que me era imposible romper. De lejos veía asomar la cabeza del dominó y flotar los lazos complicados de la capucha, que disimulaba la forma, sin duda hechicera, de la testa juvenil; pero insensiblemente deslizábase hasta perderse, y el miedo de que se escabullese me espoleaba. Iba yo ganando terreno, mas la enmascarada me llevaba gran ventaja sin duda, y empecé á recelar que huía de mí, y que después de derramar en mi alma el veneno de sus fogosos ojos, ahora me evitaba, se escurría, se volvía duende para evaporarse como una visión... Este temor que sentí fué ardoroso incentivo del deseo de reunirme á la máscara. Con sobrehumano esfuerzo rompí la valla que me oprimía, y aprovechando un resquicio, me hallé poco distante del dominó verde. Sólo que este, á su vez, apretó el paso y desapareció por una de las puertas del salón.\"},{\"heading\":false,\"text\":\"Una persecución en toda regla emprendí entonces: persecución franca, ardorosa, caza más bien. Anhelante, acongojado, como si realmente la mujer que trataba de evadirse fuese algo que me importase mucho, recorrí velozmente los pasadizos, las escaleras, las galerías, el _foyer_, buscando donde quiera á la incitante máscara. Sin duda ella había adivinado con sagacidad mi violento antojo, pues parecía complacerse en desesperarme, y si teniéndome lejos se dejaba envolver por algún grupo de hombres ó se paraba en actitud negligente, apenas comprendía que me acercaba, levantaba el vuelo con ligereza de sílfide y me desorientaba por medio de impensada maniobra. De improviso alegraba un palco el fresco color verde del dominó; yo me precipitaba, y cuando llegaba jadeante á la puerta del palco, la desconocida no estaba ya en él, sino en otro de más arriba, para subir al cual había que invertir cinco minutos, tiempo suficiente á que la máscara se enhebrase por un pasillo, saliendo enfrente de mí á buena distancia. Desalado, loco, con la imaginación caldeada y secas las fauces por el afán, me apresuraba, bajaba, subía, ponía en tensión todas las fuerzas de mi cuerpo y de mi espíritu sin dar alcance á la misteriosa hermosura que (ya era evidente) se complacía en burlarme.\"},{\"heading\":false,\"text\":\"La astucia me sirvió mejor que la agilidad en este caso. Comprendiendo que tan aristocrático dominó no querría permanecer en el baile pasadas las primeras horas de la noche, y evitaría el momento de las cenas y de las cabezas calientes; seguro de que sólo había venido allí para marearme, y logrado este objeto desaparecería, adiviné que toda su estrategia era batirse en retirada hacia la puerta, y cortándole la salida la atrapaba de fijo. También supuse que saldría por el punto más solitario, por la puerta menos alumbrada, por la calle donde es más fácil saltar furtivamente dentro de un coche que espera y huir sin dejar rastro. Mis cálculos resultaron exactísimos. Me situé en acecho con tal fortuna, que al cuarto de hora de espera ví asomar á la encapuchada del verde dominó, la cual, mirando á uno y otro lado, como recelosa, exploraba el terreno. Me arrojé á cerrarla el paso, y á mis primeras palabras suplicantes y rendidas contestó con el chillón falsete habitual en las máscaras, rogándome, por Dios, que la dejase, que no me opusiese á su marcha y que no insistiese en acosarla así.\"},{\"heading\":false,\"text\":\"La creí sincera, pero cuanto más demostraba ansia de evitarme, más crecía en mí la voluntad de detenerla, de que me escuchase, de que me mirase otra vez, de que me amase sobre todo. La vehemencia de aquel súbito antojo era tal, que si no fuese porque pasaba gente, creo que me dejo caer de rodillas á los pies del dominó. Hasta me sentí elocuente é inspirado, y noté que las frases acudían á mis labios incendiarias y dominadoras, con el acento y la expresión que presta un sentimiento real, aunque sólo dure minutos.\"},{\"heading\":false,\"text\":\"--Si querías huir de mí--dije á la máscara estrechándola de cerca--¿por qué me miraste con esos ojos que me inflamaron el corazón? ¿Por qué me clavaste la saeta, dí, si habías de negarte á curar mi herida? ¿No estás viendo cómo has removido, con esa mirada sola, todo mi ser? ¿No oyes mi voz alterada por la emoción, no observas el trastorno de mis sentidos, no me ves hecho un loco? ¿No conoces que tengo fiebre? ¿No sabes que yo te presentía, que adivinaba tu aparición, que vine á este baile en la seguridad de que tu presencia lo llenaría de luz y de encanto? ¿Y crees que voy á dejarte escapar así, que lo consentiré, que no te seguiré hasta el infierno? Si no podrás irte. En tu mirada se delató el amor, y sigue delatándose en tu actitud, en tu agitación, máscara mía.\"},{\"heading\":false,\"text\":\"Era verdad. La máscara, como fascinada, se reclinaba en la pared. Su cuerpo se estremecía, su seno se alzaba y bajaba precipitadamente, y al través de los reducidos agujeros del antifaz, ví temblar sobre el negro terciopelo de sus pupilas dos ardientes lágrimas. Con voz que apenas se oía, y en la cual también se quebraban los sollozos, murmuró lentamente, cual si desease grabar sus palabras para siempre en mi memoria:\"},{\"heading\":false,\"text\":\"--Es cierto: sólo por acercarme á ti, por gozar de tu vista, he adoptado este disfraz, he cometido la locura de venir al baile. Y mira qué extraño caso: queriéndote así, lloro... á causa de que me dices palabras de amor. Por oirlas con la cara descubierta daría mi sangre. Pero tú, que acabas de jurar que me adoras, ahora que me ves envuelta en este trapo verde, tú... huirías de mí si me presentase sin careta. Me has perseguido, me has dado caza, sólo porque no veías mi rostro. Y ni soy vieja ni fea... ¡No es eso! ¡Mírame y comprenderás! ¡Mírame y después... ya no tendrás que volver á mirarme nunca!\"},{\"heading\":false,\"text\":\"Y alzándose el antifaz, el dominó verde me enseñó la cara de mi abandonada, de mi rechazada, de mi desdeñada María... Aprovechando mi estupor, corrió, saltó al coche que la aguardaba, y al quererme precipitar detrás de ella, oí el estrépito de las ruedas sobre el empedrado.\"},{\"heading\":false,\"text\":\"Desde tan triste episodio carnavalesco sé que lo único que nos trastorna es un trapo verde--la Esperanza, la máscara eterna, la encubierta que siempre huye, la que todo lo promete...--la que bajo su risueño disfraz oculta el descolorido rostro del viejo Desengaño.\"}]},{\"title\":\"La aventura del Angel\",\"blocks\":[{\"heading\":false,\"text\":\"Por falta menos grave que la de Luzbel, que no alcanzó proporciones de _caída_, un ángel fué condenado á pena de destierro en el mundo. Tenía que cumplirla por espacio de un año, lo cual supone una inmensa suma de perdida felicidad: un año de beatitud es un infinito de goces y bienes, que no pueden vislumbrar ni remotamente nuestros sentidos groseros y nuestra mezquina imaginación. Sin embargo, el ángel, sumiso y pesaroso de su yerro, no chistó: bajó los ojos, abrió las alas, y con vuelo pausado y seguro descendió á nuestro planeta.\"},{\"heading\":false,\"text\":\"Lo primero que sintió al poner en él los pies, fue dolorosa impresión de soledad y aislamiento. A nadie conocía, y nadie le conocía á él tampoco bajo la forma humana que se había visto precisado á adoptar. Y se le hacía pesado é intolerable, pues los ángeles ni son hoscos ni huraños, sino sociables en grado sumo, como que rara vez andan solos, y se juntan y acompañan y amigan para cantar himnos de gloria á Dios, para agruparse al pie de su trono, y hasta para recorrer las amenidades del Paraíso: además, están organizados en milicias y los une la estrecha solidaridad de los hermanos de armas.\"},{\"heading\":false,\"text\":\"Aburrido de ver pasar caras desconocidas y gente indiferente, el ángel, la tarde del primer día de su castigo, salió de una gran ciudad, se sentó á la orilla del camino, sobre una piedra miliaria, y alzó los ojos hacia el firmamento que le ocultaba su patria, y que estaba á la sazón teñido de un verde luminoso, ligeramente franjeado de naranja á la parte del Poniente. El desterrado gimió, pensando cómo podría volver á la deleitosa morada de sus hermanos: pero sabía que una orden divina no se revoca fácilmente, y entre la melancolía del crepúsculo apoyó en las manos la cabeza, y lloró hermosas lágrimas de contrición, pues aparte del dolor del castigo, pesábale de haber ofendido á Dios por ser quien es, y por lo mucho que le amaba. Ya he cuidado de advertir, que, á pesar de su desliz, este ángel era un ángel bastante bueno.\"},{\"heading\":false,\"text\":\"Apenas se calmó su aflicción, ocurrióle mirar hacia el suelo, y vió que donde habían caído las gotas de su llanto, nacían y crecían y abrían sus cálices con increíble celeridad muchas flores blancas, de las que llaman margaritas, pero que tenían los pétalos de finas perlas y el corazoncito de oro. El ángel se inclinó, recogió una por una las maravillosas flores, y las guardó cuidadosamente en un pliegue de su manto. Al bajarse para la recolección, distinguió en el suelo un objeto blanco,--un pedazo de papel, un trozo de periódico.--Lo tomó también y empezó á leerlo, porque el ángel de mi cuento no era ningún ignorante á quien le estorbase lo negro sobre lo blanco; y con gozo profundo, vió que ocupaban una columna del periódico ciertos desiguales renglones, bajo este epígrafe:\"},{\"heading\":false,\"text\":\"Á UN ÁNGEL\"},{\"heading\":false,\"text\":\"¡A un ángel! ¡Qué coincidencia!--Leyó afanosamente, y, por el contexto de la poesía, dedujo que el ángel vivía en la tierra y habitaba una casa en la ciudad, cuyas señas daba minuciosamente el poeta, describiendo la reja de la ventana tapizada de jazmín, la tapia del jardín de donde se desbordaban las enredaderas y los rosales, y hasta el recodo de la calle, con la torre de la iglesia á la vuelta. «Alguno de mis hermanos--pensó el desterrado--ha cometido, sin duda, otro delito igual al mío, y le han aplicado la misma pena que á mí. ¡Qué consuelo tan grande recibirá su alma cuando me vea! ¡Qué felicidad la suya, y también la mía, al encontrar un compañero! Y no puedo dudar que lo es. La poesía lo dice bien claro: que ha bajado del cielo, que está aquí, en el mundo, por casualidad, y teme el poeta que se vuelva el día menos pensado á su patria... ¡Oh ventura! A buscarle inmediatamente.»\"},{\"heading\":false,\"text\":\"Dicho y hecho. El ángel se dirigió hacia la ciudad. No sabía en qué barrio podría vivir su hermano, pero estaba seguro de acertar pronto. Hasta suponía que de la casa habitada por el ángel se exhalaría un perfume peculiar que delatase su celestial presencia. Empezó, pues, a recorrer calles y callejuelas. La luna brillaba, y á su luz clarísima el ángel podía examinar las rejas y las tapias, y ver por cuál de ellas se enramaba el jazmín y se desbordaban las rosas.\"},{\"heading\":false,\"text\":\"Al fin, en una calle muy solitaria, un aroma que traía la brisa hizo latir fuertemente el corazón del ángel; no olía á gloria, pero sí olía á jazmín; y el perfume era embriagador y sutil como un pensamiento amoroso. A la vez que percibía el perfume, divisó tras los hierros de una reja una cara muy bonita, muy bonita, rodeada de una aureola de pelo obscuro... No cabía duda; aquel era el otro ángel desterrado, el que debía aliviarle la pena de la soledad. Se acercó á la reja trémulo de emoción.\"},{\"heading\":false,\"text\":\"No archivan las historias el traslado fiel de lo que platicaron al través de los hierros el ángel verdadero y el supuesto ángel, que escondía su faz entre el follaje menudo y las pálidas flores del fragante jazmín. Sin duda desde el primer momento, sin más explicaciones, se convino en que, efectivamente, era un ángel la criatura resguardada por la reja; habituada á oírselo llamar en verso, no extrañó que una vez más se le atribuyese en prosa naturaleza angélica.--Así es como los ripios falsean el juicio, y los poetas chirles hacen más daño que la langosta.\"},{\"heading\":false,\"text\":\"Lo que también comprendió el ángel desterrado, fué que el otro ángel era doblemente desdichado que él, pues se quejaba de no poder salir de allí, de que le guardaban y vigilaban mucho, de que le tenían sujeto entre cuatro paredes, y de que su único desahogo era asomarse á aquella reja á respirar el aire nocturno y á echar un ratito de parrafeo. El desterrado prometió acudir fielmente todas las noches á dar este consuelo al recluso, y tan á gusto cumplió su promesa, que desde entonces lo único que le pareció largo fué el día, mientras no llegaba la grata hora del coloquio.\"},{\"heading\":false,\"text\":\"Cada noche se prolongaba más, y por último, sólo cuando blanqueaba el alba y se apagaban las dulces estrellas, se retiraba de la reja el ángel, tan dichoso y anegado en bienestar sin límites, como si nadase todavía en la luz del Empíreo, y le asistiese la perfecta bienaventuranza. Sin embargo, el recluso iba mostrándose descontento y exigente. Sacando los dedos por la reja y cogiendo los de su amigo, preguntábale, con asomos de mal humor, cuándo pensaba libertarle de aquel cautiverio.\"},{\"heading\":false,\"text\":\"El ángel, para entretenerle, fué regalándole las margaritas de corazón de oro y pétalos de perlas; hasta que, muy estrechado ya, hubo de decir que sin duda el encierro era disposición de Dios, y que no se debían contrariar sus decretos santos. Una carcajada burlona fué la respuesta del encerrado, y á la otra noche, al acudir á la reja, el ángel vió con sorpresa que por la puertecilla del jardín salía una figura velada y tapada, que un brazo se cogía de su brazo, y una voz dulce, apasionada y melodiosa le decía al oído: «Ya somos libres... Llévame contigo... escapemos pronto, no sea que me echen de menos.»\"},{\"heading\":false,\"text\":\"El ángel, sobrecogido, no acertó á responder: apretó el paso y huyeron, no sólo de la calle, sino de la ciudad, refugiándose en el monte. La noche era deliciosa, del mes de Mayo: acogiéronse al pie de un árbol frondoso, él saboreando plácidamente, como ángel que era, la dicha de estar juntos; ella--porque ya habrán sospechado los lectores que se trataba de una mujer--nerviosa, sardónica, soltando lagrimitas y haciendo desplantes.\"},{\"heading\":false,\"text\":\"No podía explicarse--ahora que ya no se interponía entre ellos la reja--cómo su compañero de escapatoria no se mostraba más vehemente, cómo no formaba planes de vida; cómo no hablaba de matrimonio y otros temas de indiscutible actualidad. Nada: allí se mantenía tan sereno, tan contento al parecer, extasiado, sonriendo, abrigándola con su manto de anchos pliegues, y mirando al cielo, lo mismo que si de la luna fuese á caerle en la boca algún bollo. La mujer, que empezó por extrañarse, acabó por indignarse y enfurecerse; alejóse algunos pasos, y como el ángel preguntase afectuosamente la causa del desvío, alzó la mano de súbito y descargó en la hermosa mejilla angélica solemne y estruendoso bofetón... después de lo cual rompió á correr como una loca en dirección de la ciudad. Y el abandonado, sin sentir el dolor ni la afrenta, murmuraba tristemente:\"},{\"heading\":false,\"text\":\"--¡El poeta mentía! ¡No era un ángel! ¡No era un ángel!\"},{\"heading\":false,\"text\":\"Al decir esto vió abrirse las nubes y bajar una legión de ángeles, pero de ángeles reales y efectivos, que le rodearon gozosos. Estaba perdonado: había vencido la mayor tentación, que es la de la mujer, y Dios le alzaba el destierro. Mezclándose al coro luminoso, ascendió el ángel al cielo, entre resplandores de gloria; pero al ascender, volvía la cabeza atrás para mirar á la tierra á hurtadillas, y un suspiro hinchaba y oprimía su corazón. Allí se le quedaba un sueño... ¡Y olía tan bien el jazmín de la reja!\"}]},{\"title\":\"El fantasma\",\"blocks\":[{\"heading\":false,\"text\":\"Cuando estudiaba carrera mayor en Madrid, todos los jueves comía en casa de mis parientes lejanos los señores de Cardona, que desde el primer día me acogieron y trataron con afecto sumo. Marido y mujer formaban marcadísimo contraste: él era robusto, sanguíneo, franco, alegre, partidario de las soluciones prácticas; ella pálida, nerviosa, romántica, perseguidora del ideal. El se llamada Ramón; ella llevaba el anticuado nombre de Leonor. Para mi imaginación juvenil, representaban aquellos dos seres la prosa y la poesía.\"},{\"heading\":false,\"text\":\"Esmerábase Leonor en presentarme los platos que me agradaban, mis golosinas predilectas, y con sus propias manos me preparaba, en bruñida cafetera rusa, el café más fuerte y aromático que un aficionado puede apetecer. Sus dedos largos y finos me ofrecían la taza de porcelana _cáscara de huevo_, y mientras yo paladeaba la deliciosa infusión, los ojos de Leonor, del mismo tono obscuro y caliente á la vez que el café, se fijaban en mí de un modo magnético. Parecía que deseaban ponerse en estrecho contacto con mi alma.\"},{\"heading\":false,\"text\":\"Los señores de Cardona eran ricos y estimados. Nada les faltaba de cuanto contribuye á proporcionar la suma de ventura posible en este mundo. Sin embargo, yo dí en cavilar que aquel matrimonio entre personas de tan distinta complexión moral y física, no podía ser dichoso.\"},{\"heading\":false,\"text\":\"Aunque todos afirmaban que á Don Ramón Cardona le rebosaba la bondad y á su mujer el decoro, para mí existía en su hogar un misterio. ¿Me lo revelarían las pupilas color café?\"},{\"heading\":false,\"text\":\"Poco á poco, jueves tras jueves, fui tomándome un interés egoísta en la solución del problema. No es fácil á los veinte años permanecer insensible ante ojos tan expresivos, y ya mi tranquilidad empezaba á turbarse y á flaquear mi voluntad. Después de la comida, el señor de Cardona salía; iba al casino ó á alguna tertulia, pues era sociable, y nos quedábamos Leonor y yo de sobremesa, tocando el piano, comentando lecturas, jugando al ajedrez ó conversando. A veces, las vecinas del segundo bajaban á pasar un ratito; otras estábamos solos hasta las once, hora en que acostumbraba á retirarme, antes de que cerrasen la puerta. Y, con fatuidad de muchacho, pensaba que era bien ridículo que no tuviese D. Ramón Cardona celos de mí.\"},{\"heading\":false,\"text\":\"Una de las noches en que no bajaron las vecinas,--noche de Mayo, tibia y estrellada,--estando el balcón abierto y entrando el perfume de las acacias á embriagarme el corazón, me tentó el diablo más fuerte, y resolví declararme. Ya balbuceaba entrecortadas palabras, no precisamente de pasión, pero de adhesión, rendimiento y ternura, cuando Leonor me atajó diciéndome que estaba tan cierta de mi leal amistad, que deseaba confiarme algo muy grave, el terrible secreto de su vida. Suspendí mis confesiones para oir las de la dama, y me fué poco grato escuchar de sus labios, trémulos de vergüenza, la narración de un episodio amoroso. «Mi único remordimiento, mi único yerro--murmuró acongojada doña Leonor--se llama el marqués de Cazalla. Es, como todos saben, un perdido y un espadachín. Tiene en su poder mis cartas, escritas en momentos de delirio. Por recogerlas, no sé qué daría.» Y vi, á la luz de los brilladores astros, que se deslizaba de las pupilas obscuras una lágrima lenta...\"},{\"heading\":false,\"text\":\"Al separarme de Leonor, llevaba formado propósito de ver al marqués de Cazalla al día siguiente. Mi petulancia juvenil me dictaba tal resolución. El Marqués, á quien hice pasar mi tarjeta, me recibió al punto en artístico _fumoir_, y á las primeras palabras relativas al asunto que motivaba mi visita, se encogió de hombros y pronunció afablemente:\"},{\"heading\":false,\"text\":\"--No me sorprende el paso que usted da, pero le ruego que me crea, y le empeño palabra de honor de que es la pura verdad cuanto voy á decirle. Considero el caso de la señora de Cardona el más raro que en mi vida me ha sucedido. No sólo no poseo ni he poseído jamás los documentos á que esa señora se refiere, sino que no he tenido nunca el gusto...--porque gusto sería--de tratarla... ¡Repito que lo afirmo bajo palabra de honor!\"},{\"heading\":false,\"text\":\"Era tan inverosímil la respuesta, que no obstante el tono de sinceridad absoluta del Marqués, yo puse cara escéptica, quizás hasta insolente.\"},{\"heading\":false,\"text\":\"--Veo que no me cree usted--añadió el Marqués entonces.--No me doy por ofendido. Lo descontaba. Podrá usted dudar de mi palabra, pero ni usted ni nadie tiene derecho á suponer que soy hombre que rehuye, por medio de subterfugios, un lance personal. Si lo que busca usted es pendencia, me tiene á su disposición. Sólo le suplico que antes de resolver esta cuestión de un modo ó de otro, consulte... al señor de Cardona. He dicho _al señor_. No me mire usted con esos ojos espantados... Oigame hasta que termine. Doña Leonor Cardona, que según opinión general es una señora honradísima, ha debido de padecer una pesadilla y soñar que teníamos relaciones, que nos veíamos, que me había escrito, etc. Bajo el influjo de ilusorios remordimientos, le ha contado á su marido _todo_... es decir, _nada_... pero _todo_ para ella; y el marido ha venido aquí, como usted, sólo que más enojado, naturalmente, á pedirme cuentas, á querer beber mi sangre. Si yo no la tuviese bastante fría, á estas horas pesa sobre mi conciencia el asesinato de Cardona..., ó él me habría matado á mí (no digo que no pudiese suceder). Por fortuna no me aturdí, y preguntando á Cardona las épocas en que su esposa afirmaba que habían tenido lugar nuestras entrevistas criminales, pude demostrarle de un modo fehaciente que á la sazón me encontraba yo en París, en Sevilla ó en Londres. Con igual facilidad le probé la inexactitud de otros datos aducidos por doña Leonor. Así es que el señor Cardona, muy confuso y asombrado, tuvo que retirarse pidiéndome excusas. Si usted me pregunta cómo me explico suceso tan extraordinario, le diré que creo que esa señora, á quien después he procurado conocer (por la memoria de mi madre le juro á usted que antes, ni de vista...!), sufre alguna enfermedad moral..., y ha tenido una visión...; vamos, que se le ha aparecido un espectro de amor..., y ese espectro ¡vaya usted á saber por qué! ha tomado mi forma. Y no hay más... No se admire usted tanto. Dentro de diez años, si trata usted algunas mujeres, se habituará á no admirarse casi de nada.\"},{\"heading\":false,\"text\":\"Salí de casa del marqués en un estado de ánimo indefinible. No había medio de desmentirle, y al mismo tiempo la incredulidad persistía. Impresionado, no obstante, por las firmes y categóricas declaraciones del _dandy_, me dediqué desde aquel punto, no á cortejar á Leonor, sino á observar á Cardona. Procuré hablarle mucho, hacerle hablar, y fuí sacando, hilo por hilo, conversaciones referentes á la fidelidad conyugal, á los lances que pueden originar un error, á las alucinaciones que á veces sufrimos, á los estragos que causa la fantasía... Por fin, un día, como al descuido, dejé deslizar en el diálogo el nombre del marqués de Cazalla y una alusión á sus conquistas... Y entonces Cardona, mirándome cara á cara, con gesto entre burlón y grave, preguntó:\"},{\"heading\":false,\"text\":\"--¿Qué? ¿Ya te han enviado allá á ti también? ¡Pobrecilla Leonor, está visto que no tiene cura!\"},{\"heading\":false,\"text\":\"No necesité más para confesar de plano mis gestiones, y Cardona, sonriendo, aunque algo alterada su sonora voz, me dijo:\"},{\"heading\":false,\"text\":\"--Has de saber que cuando fuí á casa del marqués de Cazalla, ya llevaba yo ciertos barruntos y sospechas de la alucinación de Leonor, de la cual me convencí plenamente después. Si bien no parezco celoso, y hasta se diría que me pierdo por confiado, he vigilado á Leonor siempre, porque la quiero mucho, y en ninguna época hubiese podido ella cometer, sin que yo me enterase, los delitos de que se acusaba. Comprendí que se trataba de una fantasmagoría, de un sueño, y me resigné á la hipótesis de una falta imaginaria... ¡Quién sabe si ese fantasma de pasión y arrepentimiento la sirve de escudo contra la realidad! Lo que te aseguro es que Leonor, viviendo yo, nunca saldrá de la región de los fantasmas... ¡Y no volvamos á hablar de esto en la vida!\"},{\"heading\":false,\"text\":\"Aproveché el aviso, y de allí en adelante evité quedarme á solas con Leonor, y hasta fijar la mirada en sus obscuros ojos, nublados por la quimera.\"}]},{\"title\":\"La perla rosa\",\"blocks\":[{\"heading\":false,\"text\":\"Sólo el hombre que de día se encierra y vela muchas horas de la noche para ganar con qué satisfacer los caprichos de una mujer querida (díjome en quebrantada voz mi infeliz amigo) comprenderá el placer de juntar á escondidas una regular suma, y así que la redondea, salir á invertirla en el más quimérico, en el más extravagante é inútil de los antojos de esa mujer. Lo que ella contempló á distancia como irrealizable sueño, lo que apenas hirió su imaginación con la punzada de un deseo loco, es lo que mi iniciativa, mi laboriosidad y mi cariño van á darla dentro de un instante... y ya creo ver la admiración en sus ojos, y ya me parece que siento sus brazos ceñidos á mi cuello, para estrecharme con delirio de gratitud.\"},{\"heading\":false,\"text\":\"Mi único temor, al echarme á la calle con la cartera bien lastrada y el alma inundada de júbilo, era que el joyero hubiese despachado ya las dos encantadoras perlas color de rosa que tanto entusiasmaron á Lucila la tarde que se detuvo, colgada de mi brazo, á golosinear con los ojos el escaparate. Es tan difícil reunir dos perlas de ese raro y peregrino matiz, de ese hermoso oriente, de esa perfecta forma globulosa, de esa igualdad absoluta, que juzgué imposible que alguna señora antojadiza como mi mujer, y más rica, no las encerrase ya en su guardajoyas. Y me dolería tanto que así hubiese sucedido, que hasta me latió el corazón cuando vi sobre el limpio cristal, entre un collar magnífico y una cascada de brazaletes de oro, el fino estuche de terciopelo blanco donde lucían misteriosamente las dos perlas rosa orladas de brillantes.\"},{\"heading\":false,\"text\":\"Aunque iba preparado á que me hiciesen pagar el capricho, me desconcertó el alto precio en que el joyero tasaba las perlas. Todas mis economías, y un pico, iban á invertirse en aquel par de botoncitos, no más gruesos que un garbanzo chiquitín. Me asaltó la duda--¡soy tan poco experto en compras de lujo!--de si el joyero pretendería explotar mi ignorancia pidiéndome, sólo por pedir, un disparate, creyendo tal vez que mi pelaje no era el de un hombre capaz de adquirir dos perlas rosa. A tiempo que pensaba así, observé, al través del alto y diáfano vidrio de la tienda, que pasaba por la acera mi antiguo condiscípulo y mejor amigo Gonzaga Llorente. Ver su apuesta figura y salir á llamarle fué todo uno. ¿Quién mejor para ilustrarme y aconsejarme que el elegante Gonzaga, tan al corriente de la moda, tan lanzado al mundo, tan bien relacionado, que cada visita que hacía á nuestra modesta y burguesa casa--y hacía bastantes desde algún tiempo acá--yo la estimaba como especialísima prueba de afecto?\"},{\"heading\":false,\"text\":\"Manifestando cordial sorpresa, Gonzaga se volvió y entró conmigo en la joyería, enterándose del asunto. Inmediatamente se declaró admirador de las perlas rosa, y añadió que sabía que andaban bebiendo los vientos por adquirirlas ciertas empingorotadas señoras, entre las cuales citó á dos ó tres de altisonantes títulos. En un discreto aparte me aseguró que el precio que exigía el joyero no tenía nada de excesivo, en atención á la singularidad de las perlas. Y como yo recelase aún, molestado por el piquillo que en aquel momento no me era posible abonar, Gonzaga, con su simpática franqueza, abrió la cartera y me entregó varios billetes, bromeando y jurando que si yo no admitiese tan pequeño servicio, en todos los días de su vida volvería á mirarme á la cara. ¡Qué miserables somos! No debí aceptar el préstamo; no debí llevar á mi casa sino lo que pudiese pagar al contado... pero la pasión me dominaba, y hubiese besado de rodillas la mano que me ofrecía medio de satisfacerla. Convinimos en que Gonzaga almorzaría con nosotros al día siguiente, en celebración del estreno de las perlas rosa, y con el estuche en el bolsillo me dirigí á mi casa disparado; quisiera tener alas.\"},{\"heading\":false,\"text\":\"Lucila trasteaba cuando yo entré, y al verme plantado delante de ella, diciéndola con cara de beatitud «Regístrame», comprendió y murmuró «Regalo tenemos». Viva y traviesa (¡su manera de ser!) revolvió mis bolsillos haciéndome cosquillas deliciosas, hasta acertar con el estuche. El grito que exhaló al ver las perlas, es de eso que no se olvida jamás. En la efusión de su agradecimiento, me sobó la cara y hasta me besó... ¡Puede que en aquel instante me quisiese un poco! No acertaba á creer que joya tan codiciada y espléndida fuese suya; no podía convencerse de que iba á ostentarla. Y yo mismo, desabrochando los sencillos aretes de oro que Lucila llevaba puestos, enganché las perlas rosa en las orejitas pequeñas, encendidas de placer. Me hace mucho daño acordarme estas tonterías, pero me acuerdo siempre.\"},{\"heading\":false,\"text\":\"Al otro día, que era domingo, almorzó en casa Gonzaga y estuvimos todos bulliciosos y decidores. Lucila se había puesto el vestido de seda gris, que la sentaba muy bien, y una rosa en el pecho,--una rosa del mismo color de las perlas.--Gonzaga nos convidó al teatro y nos llevó á Apolo, á una función alegre, en que sin tregua nos reimos. Al otro día volví con afán á mis quehaceres, pues deseaba saldar cuanto antes el pico, resto de las perlas. Regresé á mi casa á la hora de costumbre, y al sentarme á la mesa, mi primera mirada fué para las orejas de Lucila. Dí un salto y lancé una interjección al ver que faltaba del diminuto cerco de brillantes una de las perlas rosa.\"},{\"heading\":false,\"text\":\"--¡Has perdido una perla!--exclamé.\"},{\"heading\":false,\"text\":\"--¿Cómo una perla?--tartamudeó mi mujer echando mano á sus orejas y palpando los aretes.--Al ver que era cierto, quedóse tan aterrada, que me alarmé, no ya por la perla, sino por el susto de Lucila.\"},{\"heading\":false,\"text\":\"--Calma--la dije.--Busquemos, que parecerá.\"},{\"heading\":false,\"text\":\"Excuso decir que empezamos á mirar y registrar por todas partes, recorriendo la alfombra, sacudiendo las cortinas, alzando los muebles, escudriñando hasta cajones que Lucila afirmaba no haber abierto desde un mes antes. A cada pesquisa inútil, los ojos de Lucila se arrasaban de lágrimas. Mientras revolvíamos, se me ocurrió preguntarla:\"},{\"heading\":false,\"text\":\"--¿Has salido esta tarde?\"},{\"heading\":false,\"text\":\"--Sí... creo que sí...--respondió titubeando.\"},{\"heading\":false,\"text\":\"--¿A dónde?\"},{\"heading\":false,\"text\":\"--A varios sitios... es decir... Fuí... por ahí... á compras...\"},{\"heading\":false,\"text\":\"--Pero... ¿á qué tiendas?\"},{\"heading\":false,\"text\":\"--¡Qué sé yo! A la calle de Postas... á la plazuela del Angel... á la Carrera...\"},{\"heading\":false,\"text\":\"--¿A pie ó en coche?\"},{\"heading\":false,\"text\":\"--A pie... Luego tomé un cochecillo.\"},{\"heading\":false,\"text\":\"--¿No recuerdas el punto... el número?\"},{\"heading\":false,\"text\":\"--¿Cómo quieres que lo recuerde? ¡Válgame Dios! Si era un coche que pasaba--objetó nerviosamente Lucila, que rompió á sollozar con amargura.\"},{\"heading\":false,\"text\":\"--Pero las tiendas sí las recordarás... Dímelas, que iré una por una, á ver si en el suelo ó en el mostrador... Pondremos anuncios...\"},{\"heading\":false,\"text\":\"--¡Si no me acuerdo! ¡Por Dios, déjame en paz!--exclamó tan afligida, que no me atreví á insistir, y preferí aguardar á que se calmase.\"},{\"heading\":false,\"text\":\"Pasamos una noche de inquietud y desvelo; oí á Lucila suspirar y dar vueltas en la cama, como si no consiguiese dormir. Yo, entretanto, discurría modos de recuperar la perla rosa. Levantéme temprano, me vestí, y á las ocho llamaba á la puerta de Gonzaga Llorente. Había oído decir que la policía, en casos especiales, averigua fácilmente el paradero de los objetos perdidos ó robados, y esperaba que Gonzaga, con su influencia y sus altas relaciones, me ayudaría á emplear este supremo recurso.\"},{\"heading\":false,\"text\":\"--El señorito está durmiendo, pero pase usted al gabinete, que dentro de diez minutos le entraré el chocolate y preguntaré si puede usted verle--dijo el criado, al notar mi insistencia y mi premura.\"},{\"heading\":false,\"text\":\"Me avine á esperar. El criado abrió las maderas del gabinete, en cuyo ambiente flotaban esencias y olor de cigarro. ¡Cuando pienso en lo distinta que sería mi suerte si aquel criado me hace pasar inmediatamente á la alcoba...!\"},{\"heading\":false,\"text\":\"Lo cierto es... que al primer alegre rayo de sol que cruzó las vidrieras, y antes de que el criado me dijese «tome usted asiento», yo había visto brillar sobre el ribete de paño azul de la piel de oso blanco, tendida al pie del muelle diván turco, ¡la perla, la perla rosa!\"},{\"heading\":false,\"text\":\"Si esto que me sucedió le sucede á usted, y usted me pregunta qué debe hacerse en tales circunstancias, yo respondo de seguro con gran energía: «Coger una espada de la panoplia que supera el diván, y atravesársela por el pecho al que duerme ahí al lado, para que nunca más despierte.»\"},{\"heading\":false,\"text\":\"¿Sabe usted lo que hice? Me bajé; recogí la perla; la guardé en el bolsillo; salí de aquella casa; subí á la mía; encontré á mi mujer levantada y muy desencajada; la miré, y no la ahogué; con voz tranquila la ordené que se pusiese los pendientes; saqué la perla del bolsillo... y cogiéndola entre dos dedos, la dije: «Aquí está lo que perdiste. ¿Qué tal, lo encontré pronto?»\"},{\"heading\":false,\"text\":\"Es cierto que al acabar me dió no sé qué arrechucho ó qué vértigo de locura; eché mano á aquellas orejas diminutas, arranqué de ellas los pendientes, y todo lo pisoteé. Por fortuna, pude dominarme en el acto... y bajar la escalera y refugiarme en el café más próximo, donde pedí _cognac_...\"},{\"heading\":false,\"text\":\"¿Que si he vuelto á ver á Lucila?... Una vez... Iba del brazo de _otro_, que ya no era Gonzaga. Por cierto que me fijé en que el lóbulo de la oreja izquierda lo tiene partido. Sin duda se lo rasgué yo... involuntariamente.\"}]},{\"title\":\"Un parecido\",\"blocks\":[{\"heading\":false,\"text\":\"No hay discusión más baldía que la de la hermosura. Mil veces la entablamos, en aquella especie de senadillo de gentes al par desengañadas y curiosas, donde se agitaban tantos problemas á un tiempo atractivos é insolubles; y siempre,--aunque no escaseaban las disertaciones,--quedábamos en mayor confusión. Uno sostenía que la belleza era la corrección de líneas; otro, que la armonía del color; éste, que la fusión de ambos elementos; aquél, que la juventud; el de más allá, que la salud y robustez, ó el donaire, chiste y garabato, ó el arte del tocador, ó la melodía de la voz, y hasta hubo alguno que identificó la belleza con la bondad y con la inteligencia... Y el original de Donato Abreu, que solía escuchar callando, al fin se descolgó con la sentencia siguiente:--La belleza no es nada.\"},{\"heading\":false,\"text\":\"Acostumbrados á sus salidas, callamos para ver cómo se desenredaba, y fué así:\"},{\"heading\":false,\"text\":\"--No es nada, nada absolutamente. Si nos ataca á los presentes una oftalmía, se acabaron líneas, colores, aire de salud, juventud, adorno... Todo eso estaba en nuestra retina... y en ninguna parte más.\"},{\"heading\":false,\"text\":\"--¡Vaya una gracia!--exclamamos.--Si empieza usted por dejarnos ciegos...\"},{\"heading\":false,\"text\":\"--Es que lo están ustedes ya cuando tienen por realidad lo que no existe fuera de nosotros. ¡Déjenme continuar! Yo aduciré ejemplos. Ante todo, ¿supongo que se trata de la belleza femenil?\"},{\"heading\":false,\"text\":\"--¡Ah, pícaro!--protestó el escultor.--¡Se refugia usted ahí... porque es donde menos refutación tienen sus herejías! A los escultores no vale cegarnos: acuérdese usted de aquel que privado de la vista admiraba con las yemas de los dedos el torso de una estatua griega...\"},{\"heading\":false,\"text\":\"--¡Bah! Tampoco ustedes reconocen ley fija, tipo inalterable... La _Venus dormida en su concha_, que presentó usted hace dos años y se llevó la medalla, no se asemeja á la Venus clásica, y no por eso deja de ser hermosa... es decir, de parecerlo... Pero no nos salgamos del terreno general, porque el arte es patrimonio de pocos. ¿Hablábamos de mujeres, sí ó no?\"},{\"heading\":false,\"text\":\"--¿De mujeres? ¡Siempre!--afirmó el vizconde de Tresmes, el cual, según malas lenguas, tenía un pasado asaz borrascoso.--¿Qué otra cosa merece la pena de discutirse en este mundo?\"},{\"heading\":false,\"text\":\"--Entonces, pleito ganado--insistió Donato recalcándose en la butaca.--¿Sostienen ustedes que la hermosura de determinada mujer es la causa de los sentimientos especiales que esa mujer nos inspira?\"},{\"heading\":false,\"text\":\"--¿Pues qué había de ser?--repuso Tresmes.--¿Su fealdad? O es hermosa, ó hermosa la creemos, y de esa belleza nos enamoramos... más ó menos... ¡que en eso cabe una escala infinita de grados y matices!\"},{\"heading\":false,\"text\":\"--Oigan--suplicó Donato--no mis razones, sino la historia muy verdadera de un amigo mío que se ha muerto en el extranjero, porque no logrando aliviarse de un delirio amoroso, se dedicó á viajar, y en Roma una fiebre palúdica--lo que allí conocen por _malaria_--le curó de la enfermedad de vivir...\"},{\"heading\":false,\"text\":\"Mi amigo era el hijo de segundas nupcias de un señor bastante rico; los otros, fruto del primer tálamo, le adoraban, y le ampararon como padres, cuando todos quedaron huérfanos. Casóse el mayor de sus hermanos con una señorita llamada Jacinta, y mi amigo--Marcelo le diremos, por no divulgar su verdadero nombre--fué á vivir á Madrid con el nuevo matrimonio, para terminar la carrera de arquitecto. Era _muy bella_ la cuñadita Jacinta--ya ven ustedes que me sirvo del lenguaje usual--y Marcelo, un día tras otro, confianza va y halago viene, se prendó de Jacinta con la pasión más tirana. Cuando comprendió su estado, cuando interpretó su afán, se horrorizó de una inclinación tan culpable y se propuso esconderla, como se esconde la mancha y la vergüenza, y no dejar asomar por ningún resquicio ni reflejos de la hoguera que le consumía la médula de los huesos. Y hubiese cumplido su propósito, á no suceder cosa más terrible aún: que la señora, objeto de tan reprobable afición--ó porque la adivinó ó porque se contagió con ella sin adivinarla--al cabo dió en padecer del mismo achaque, y, menos cauta, lo descubrió con indicios tan claros, que Marcelo, sintiéndose débil y vencido antes de pelear, apeló á poner tierra en medio... Dijo á su hermano que se encontraba enfermo--y esto no era sino relativa mentira--y que necesitaba respirar, por receta del médico, aires puros, aires de campo; y el hermano, solícito y compadecido, le envió á un cortijo que había heredado de su suegro, y que por encontrarse en lo más florido y frondoso de la serranía de Córdoba y ser entonces el mes de Abril, debía de estar convertido en vergel delicioso.\"},{\"heading\":false,\"text\":\"--Habrá comodidad suficiente para ti--advirtió--porque el padre de mi Jacinta tenía cariño á ese sitio y lo visitaba de vez en cuando, aunque Jacinta nunca ha puesto allí los pies, ni yo tampoco. He oído susurrar no sé qué de la mujer del capataz...; ¡pero si se creyese cuanto se oye! En fin, lo esencial es que no te faltarán ropas ni muebles... Y si algo te falta, pídelo en seguida.\"},{\"heading\":false,\"text\":\"Marchó Marcelo asaz desesperado á su Tebaida, y el capataz le recibió con agasajo, encargando á su hija, mocita como de veinte años de edad, que sirviese y atendiese al forastero. ¡Imagínense la conmoción que sufriría éste, cuando, al fijar los ojos en el rostro de la hija del capataz, vió en él una copia perfectísima, un acabado trasunto del de Jacinta! Era semejanza, no sólo de facciones, sino de expresión, modales y gesto, y--lo que más turbó á Marcelo--hasta de metal de voz, con un ceceo andaluz que hacía encantador el de Manuelita la cortijera.--Reconoció el enamorado los negros ojos que llevaba clavados en el corazón, el talle cuyas ondulaciones le causaban vértigos, el color quebrado de la suave tez, que le enloquecía, y acordándose de las indicaciones de su hermano acerca de la mujer del capataz, no se asombró de encontrar una nueva Jacinta en la sierra. Al pasar días fue notando que la serrana poseía mil cualidades preciosas: limpia, fina á su modo, viva y lista como nadie; ya alegre, ya melancólica; oportuna en replicar, aguda en comprender, sensible á ratos y arisca á tiempo, sabía además rasguear la guitarra y entonar el polo con un salero que quitaba el sentido. Marcelo, embelesado, pensó que la misma Providencia le deparaba tan sabroso remedio á sus enfermedades morales, y se dedicó á la serrana, galanteándola y persiguiéndola sin tregua, á favor de aquella libertad que da el campo y de las rodadas ocasiones que brinda el vivir bajo un techo mismo. Manuelita se defendió; pero al cabo fue ablandándose, y consintió en acudir á una reja baja, donde sin peligro para su recato podía conversar largamente con Marcelo. Mas lo que suele costar trabajo en estas lides es el primer triunfo, que los restantes vienen fatalmente á su hora, y Manuelita, aunque se hizo muy de rogar, acabó por conceder á Marcelo que una noche, en vez de hablarse por la reja, se hablasen dentro del aposento que la reja defendía...\"},{\"heading\":false,\"text\":\"El narrador se detuvo un instante, como preparando el efecto de lo que le faltaba por contar.\"},{\"heading\":false,\"text\":\"--Marcelo entró en aquel cuarto temblando de gozo, paladeando con la imaginación el bien que esperaba. No se había atrevido Manuelita á encender luz, pero la de la luna entraba á oleadas por la reja--en la cual se apoyaba la muchacha ruborizada y acaso medio arrepentida ya--y alumbraba de lleno su rostro, haciéndolo parecer más descolorido, del tono de los jazmines que lucía apiñados en el negro rodete. Marcelo se adelantó como el que camina en sueños, y al aproximarse á Manuelita, al rodear con los brazos el talle curvo que se doblegaba, al respirar con los labios el perfume de las blancas flores tan próximas á la mejilla fresca y á la garganta tornátil, su boca exhaló, entre hondo suspiro, un nombre... ¡el nombre de _Jacinta_! Y al oirse, al repetir involuntariamente tal nombre, espantado, como si viese á una sierpe, se desprendió, retrocedió, se tambaleó y al fin huyó, subiendo la escalera á tientas y encerrándose en su dormitorio... donde pasó la noche entre remordimientos y lágrimas, para salir á la madrugada camino de Córdoba, y desde Córdoba á París...--¿Comprenden ustedes el motivo de la conducta de Marcelo?\"},{\"heading\":false,\"text\":\"--Que para él sólo existía Jacinta; Manuelita no había existido nunca, sino por la pasajera realidad que le comunicó su parecido con _la otra_...--respondimos algo impresionados, reflexionando á pesar nuestro.\"},{\"heading\":false,\"text\":\"--Exactamente... Veo que son ustedes perspicaces... Al pensar Marcelo que se libertaba de su criminal pasión, lo que hacía era recaer en ella de plano, satisfacerla, entregarse... ¿Y la belleza? Tan guapa era Manuela la cortijerita, como Jacinta la dama. ¡Acaso más!\"},{\"heading\":false,\"text\":\"--Marcelo se me figura demasiado idealista--indicó Tresmes en tono desdeñoso.\"},{\"heading\":false,\"text\":\"--Todos lo somos...--declaró Donato.--Y la belleza, una idea, unas gotas de ilusión, para _uso interno_...\"}]},{\"title\":\"Memento\",\"blocks\":[{\"heading\":false,\"text\":\"El recuerdo más vivaz de mis tiempos estudiantiles--dijo el doctor sonriendo á la evocación--no es el de varios amorcillos y lances parecidos á los que puede contar todo el mundo, ni el de ciertas mejillas bonitas cuyas rosas embalsamaron mis sueños. Lo que no olvido, lo que á cada paso veo con mayor relieve, es... la tertulia de mi tía Gabriela, doncella machucha, á quien acompañaban todas las tardes otras tres viejas apolilladas, igualmente aspirantes á la palma sobre el ataud.\"},{\"heading\":false,\"text\":\"Reuníanse las cuatro, según he dicho, por la tarde--pues de noche las cohibían miedos, achaques y devociones--en el gabinetito, desde cuyas ventanas se divisaban los ricos ajimeces góticos y los altos muros de la Catedral; y yo solía abandonar el paseo--á tal hora lleno de muchachas deseosas de escuchar piropos--para encerrarme entre aquellas cuatro paredes vestidas de un papel rameado que fué verde y ya era blancuzco, sentarme en la butaca de fatigados muelles, anchota y blandufa, al cabo también anciana, y recibir de una mano diminuta, seca, cubierta por la rejilla de un mitón negro, palmadita suave en el hombro, mientras una cascada voz murmuraba: «Hola, ¿ya viniste, calamidad? Hoy se muere de gozo Candidita».\"},{\"heading\":false,\"text\":\"De las solteronas, Candidita era la más joven, pues no había cumplido los sesenta y tres. Según las crónicas de los remotos días en que Candidita lozaneaba, jamás descolló por su belleza. Siempre tuvo el ojo izquierdo algo caído y las espaldas encorvadas en demasía. Lo que en ella pudo agradar fué su seráfica condición. Poseía Candidita, en relación con su nombre de pila, alta dosis de credulidad y buena fe. Cuanta paparrucha inverosímil se me antojase inventar, la tragaba Candidita sin esfuerzo; en cambio no había quien la convenciese de la realidad de picardía ninguna. Su alma rechazaba la maledicencia como se rechaza un elemento extraño, de imposible asimilación. Yo me divertía infinito disputando con Candidita cuando se negaba á dar crédito á maldades notorias... y al hacerlo, sentía germinar en mi corazón una especie de ternura, un misterioso respeto por la inocente, que sin quitarse su traje de merino negro y sus zapatos de oreja, subiría al cielo al momento menos pensado.\"},{\"heading\":false,\"text\":\"Mi tía Gabriela, en cambio, era sagaz, lista como una pimienta. Su vida retirada, en una soñolienta ciudad de provincia, la impedía conocer á fondo el mundo, y quizás exageraba las trastadas y gatuperios que en él se cometen, pero acercándose á la realidad y juzgando mil veces con maligno acierto. Preciada de su linaje, con pergaminos y sin talegas, la tía Gabriela era una señora á la vez modesta é imponente, chapada á la antigua, de alma más enhiesta que un lanzón; las otras tres solteronas parecían sus damas de honor, antes que sus amigas.\"},{\"heading\":false,\"text\":\"Doña Aparición era la curiosidad de aquel museo arqueológico. Hermosa y mundana en sus verdores, conservaba, á los setenta y seis, golpes de coquetería y manías de adorno que hacían fruncir los labios á mi tía Gabriela, tan majestuosa con su liso hábito del Carmen. El peluquín de doña Aparición, con bucles y sortijillas de un rubio angelical; su calzado estrecho; sus guantes claros de ocho botones; sus trajes de seda á rayas verde y rosa; sus abanicos de gasa azul, y el grupo de flores artificiales que prendía graciosamente su mantilla, nos daban harto que reir.\"},{\"heading\":false,\"text\":\"Como estaba semiciega y casi sorda y la vestía su fámula, á lo mejor traía la peluca del revés, ó en la nariz el toque de carmín de las mejillas, ó los guantes uno lila y otro pajizo; y como padecía de gota, el cepo de las botitas prietas llegaba á mortificarla tanto, que mi tía la prestaba unas holgadas pantuflas. En caso tal exclamaba infaliblemente doña Aparición: «¡Jesús! Nunca me pasó cosa igual. Un pliegue de la media me desolló el talón... Es un fastidio tener tan fino el cutis.»\"},{\"heading\":false,\"text\":\"No sería doña Peregrina, la cuarta solterona, la que se impusiese torturas para presumir de pie. Al contrario: se declaraba _sans façon_. Reducida á mezquina orfandad, compraba en los ropavejeros sus manteletas color de ala de mosca. Por lo demás, era mujer de empuje y brío, alta, gruesa, de una frescura rancia--si es lícito expresarse así--viva de ojos y arrebatada de color, amiga de la broma, pero gazmoña á ratos, siempre dentro de la nota del buen humor y la marcialidad.\"},{\"heading\":false,\"text\":\"¡Cómo me festejaban aquellas cuatro señoras! Hay sitios adonde vamos atraídos, no por nuestro gusto, sino por el que damos á los demás. Diez años haría tal vez que las solteronas no veían de cerca un semblante juvenil. Mi presencia y mi asiduidad eran un rasgo de galantería de incalculable precio, que halagaba la nunca extinguida vanidad sentimental de la mujer. El mozo que quiera ganar buen nombre, sea amable con las viejecitas, con las desechadas, con las retiradas del juego. Las muchachas nada agradecen. Aquellas cuatro inválidas, con su manso charloteo, me crearon una reputación fabulosa de discreto, de galán, de simpático, de estudioso. A su manera, me allanaban el camino de una lucida posición y de una boda brillante. En los exámenes yo podía contestar mal ó bien, que segura tenía la nota: tal labor subterránea hacían mis solteronas con los catedráticos. En mi salud no cesaban de pensar. «Vienes descolorido, Gabriel... ¿Qué tienes? ¡Ojo con las bribonas!» Y me enviaban remedios caseros, y piperetes, y vinos cordiales, y reliquias milagrosas, y hasta sábanas, por si las de la posada no eran «de confianza» y «bien lavaditas».\"},{\"heading\":false,\"text\":\"A fin de animar la tertulia, se me ocurrió leer en alto versos y novelas románticas. Auditorio semejante no lo ha soñado ningún lector. Diríase que, para escuchar, hasta la respiración suspendían. Según avanzaba la lectura, crecía el interés. Una indignación, cómica á fuerza de ser ingenua, contra los traidores; un terror vivísimo cuando los buenos iban á caer en las emboscadas de los malos; un gozo pueril cuando la virtud salía triunfante... Las exclamaciones me interrumpían. «¿Ese pillo se equivoca y toma el veneno? ¡Castigo de Dios!» «¡Ay, que si Gontrán entra en el bosque encuentra al otro con el puñal! ¡Que no entre, que no entre!» «¡Jesús, al fin le da la puñalada!» «¡Infame!» «Ve usted cómo el niño que robó el titiritero era hijo de la princesa?» etc.--En los episodios vehementes, cuando los amantes se dicen ternezas al claror de la luna, las solteronas se deshacían. Un leve sonrosado animaba las mejillas amarillentas; se humedecían los áridos ojos; los encogidos pechos anhelaban; aparecíase el bello fantasma de la lejana juventud, y un aura dulce y tibia agitaba un momento aquellos espíritus resignados, como el aire primaveral agita el polvo de una tierra seca y estéril.\"},{\"heading\":false,\"text\":\"Llegó el plazo en que yo tenía que emprender mi viaje á la corte, para cursar el doctorado. Dí la noticia á mis solteronas, y aunque no podía sorprenderlas, no fué menor el efecto que produjo. Mi tía Gabriela, sin perder el compás de la dignidad, se puso temblona, y me advirtió, en frases que revelaban verdadera ternura, que era preciso excusar á los viejos si se afectaban en las despedidas, porque no estaban seguros de volver á ver á los que partían. Doña Peregrina manoteó, protestó, bufó, me insultó, y al fin se echó á llorar como una fuente. Doña Aparición suspiró, alzó la vista al cielo y dijo haciendo monerías: «Un joven de estas prendas... naturalmente, ¡va á lucir en la corte! Mañana recibirá usted un alfiler de esmeraldas... que fué de mi papá». Por su parte, Candidita guardó silencio, y á poco se levantó, asegurando que tenía que hacer una visita urgente. Aproveché el pretexto para abreviar la escena; salí con ella, la ayudé á ponerse el mantón, y la ofrecí el brazo por la escalera de peldaños carcomidos.\"},{\"heading\":false,\"text\":\"De repente, en el primer descanso, escuché un ahogado sollozo; unos brazos endebles me rodearon el cuello, y una cara fría como la nieve se pegó á mis barbas. Comprendí de súbito... y, créanlo ustedes, ¡me quedé más volado y más compadecido que si viese á mi propia madre de rodillas ante mí! Noté que Candidita pesaba como pesan los cuerpos inertes; la supuse desmayada y la arrimé al balaustre, tartamudeando lleno de piedad: «Adiós, adiós, ya sabe que se la quiere». Mas como no me soltaba, me encontré ridículo y la rechacé... Al hacerlo, me pareció que estaba degollando á una ovejuela enferma, y la lástima me obligó á volver atrás y corresponder al abrazo de Candidita con una caricia rápida y violenta, filial y santa en la intención. Después eché á correr, y salí á la calle resuelto á no volver por la tertulia. ¡Ah, eso sí! La caridad tiene sus límites...--Y ahora, que también soy viejo yo, suelo acordarme de Candidita... ¡Pobre mujer!\"}]},{\"title\":\"La caja de oro\",\"blocks\":[{\"heading\":false,\"text\":\"Siempre la había visto sobre su mesa, al alcance de su mano bonita, que á veces se entretenía en acariciar la tapa suavemente; pero no me era posible averiguar lo que encerraba aquella caja de filigrana de oro con esmaltes finísimos, porque apenas intentaba apoderarme del juguete, su dueña lo escondía precipitada y nerviosamente en los bolsillos de la bata, ó en lugares todavía más recónditos, dentro del seno, haciéndola así inaccesible.\"},{\"heading\":false,\"text\":\"Y cuanto más la ocultaba su dueña, mayor era mi afán por enterarme de lo que la caja contenía. ¡Misterio irritante y tentador! ¿Qué guardaba el artístico chirimbolo? ¿Bombones? ¿Polvos de arroz? ¿Esencias? Si encerraba alguna de estas cosas tan inofensivas, ¿á qué venía la ocultación? ¿Encubría un retrato, una flor seca, pelo? Imposible: tales prendas, ó se llevan mucho más cerca ó se custodian mucho más lejos: ó descansan sobre el corazón, ó se archivan en un secreter bien cerrado, bien seguro... No eran despojos de amorosa historia los que dormían en la cajita de oro, esmaltada de azules quimeras, fantásticas rosas y volutas de verde ojiacanto.\"},{\"heading\":false,\"text\":\"Califiquen como gusten mi conducta los incapaces de seguir la pista á una historia, tal vez á una novela. Llámenme enhorabuena indiscreto, antojadizo, y por contera, entrometido y fisgón impertinente. Lo cierto es que la cajita me volvía tarumba, y agotados los medios legales, puse en juego los ilícitos y heroicos... Mostréme perdidamente enamorado de la dueña, cuando sólo lo estaba de la cajita de oro; cortejé en apariencia á una mujer, cuando sólo cortejaba á un secreto; hice como si persiguiese la dicha... cuando sólo perseguía la satisfacción de la curiosidad. Y la suerte, que acaso me negaría la victoria si la victoria realmente me importase, me la concedió... por lo mismo que al concedérmela me echaba encima un remordimiento.\"},{\"heading\":false,\"text\":\"No obstante, después de mi triunfo, la que ya me entregaba cuanto entrega la voluntad rendida, defendía aún, con invencible obstinación, el misterio de la cajita de oro. Desplegando zalameras coqueterías ó repentinas y melancólicas reservas; discutiendo ó bromeando; apurando los ardides de la ternura ó las amenazas del desamor, suplicante ó enojado, nada obtuve; la dueña de la caja persistió en negarse á que me enterase de su contenido, como si dentro del lindo objeto existiese la prueba de algún crimen.\"},{\"heading\":false,\"text\":\"Repugnábame emplear la fuerza y proceder como procedería un patán, y además, exaltado ya mi amor propio (á falta de otra exaltación más dulce y profunda), quise deber al cariño y sólo al cariño de la hermosa la clave del enigma. Insistí, me sobrepujé á mí mismo, desplegué todos los recursos, y como el artista que cultiva por medio de las reglas la inspiración, llegué á tal grado de maestría en la comedia del sentimiento, que logré arrebatar al auditorio. Un día en que algunas fingidas lágrimas acreditaron mis celos, mi persuasión de que la cajita encerraba la imagen de un rival, de alguien que aún me disputaba el alma de aquella mujer, la vi demudarse, temblar, palidecer, echarme al cuello los brazos, y exclamar, por fin, con sinceridad que me avergonzó:\"},{\"heading\":false,\"text\":\"--¡Qué no haría yo por ti! Lo has querido... pues sea. Ahora mismo verás lo que hay en la caja.\"},{\"heading\":false,\"text\":\"Apretó un resorte; la tapa de la caja se alzó, y divisé en el fondo unas cuantas bolitas tamañas como guisantes, blanquecinas, secas. Miré sin comprender, y ella, reprimiendo un gemido, dijo solemnemente:\"},{\"heading\":false,\"text\":\"--Esas píldoras me las vendió un curandero que realizaba curas casi milagrosas en la gente de mi aldea. Se las pagué muy caras, y me aseguró que, tomando una al sentirme enferma, tengo asegurada la vida. Sólo me advirtió que si las apartaba de mí ó las enseñaba á alguien, perdían su virtud. Será superstición ó lo que quieras; lo cierto es que he seguido la prescripción del curandero, y no sólo se me quitaron achaques que padecía (pues soy muy débil), sino que he gozado salud envidiable. Te empeñaste en averiguar... Lo conseguiste... Para mí vales tú más que la salud y que la vida. Ya no tengo panacea, ya mi remedio ha perdido su eficacia: sírveme de remedio tú; quiéreme mucho, y viviré.\"},{\"heading\":false,\"text\":\"Quédeme frío. Logrado mi empeño, no encontraba dentro de la cajita sino el desencanto de una superchería y el cargo de conciencia del daño causado á la persona que al fin me amaba. Mi curiosidad, como todas las curiosidades, desde la fatal del Paraíso hasta la no menos funesta de la ciencia contemporánea, llevaba en sí misma su castigo y su maldición. Daría entonces algo bueno por no haber puesto en la cajita los ojos. Y tan arrepentido que me creí enamorado; cayendo de rodillas á los pies de la mujer que sollozaba, tartamudeé:\"},{\"heading\":false,\"text\":\"--No tengas miedo... Todo eso es una farsa, un indigno embuste... El curandero mintió... Vivirás, vivirás mil años... Y aunque hubiesen perdido su virtud las píldoras, ¿qué? Nos vamos á la aldea y compramos otras... Todo mi capital le doy al curandero por ellas.\"},{\"heading\":false,\"text\":\"Me estrechó, y sonriendo en medio de su angustia, balbuceó á mi oído:\"},{\"heading\":false,\"text\":\"--El curandero ha muerto.\"},{\"heading\":false,\"text\":\"Desde entonces la dueña de la cajita--que ya no la ocultaba ni la miraba siquiera, dejándola cubrirse de polvo en un rincón de la estantería forrada de felpa azul--empezó á decaer, á consumirse, presentando todos los síntomas de una enfermedad de languidez, refractaria á los remedios. Cualquiera que no me tenga por un monstruo supondrá que me instalé á su cabecera y la cuidé con caridad y abnegación. Caridad y abnegación digo, porque otra cosa no había en mí para aquella criatura de quien había sido verdugo involuntario. Ella se moría, quizás de pasión de ánimo, quizás de aprensión, pero por mi culpa; y yo no podía ofrecerla, en desquite de la vida que le había robado, lo que todo lo compensa: el don de mí mismo, incondicional, absoluto. Intenté engañarla santamente para hacerla dichosa, y ella, con tardía lucidez, adivinó mi indiferencia y mi disimulado tedio, y cada vez se inclinó más hacia el sepulcro.\"},{\"heading\":false,\"text\":\"Y al fin cayó en él, sin que ni los recursos de la ciencia ni mis cuidados consiguiesen salvarla. De cuantas memorias quiso legarme su afecto, sólo recogí la caja de oro. Aún contenía las famosas píldoras, y cierto día se me ocurrió que las analizase un químico amigo mío, pues todavía no se daba por satisfecha mi maldita curiosidad. Al preguntar el resultado del análisis, el químico se echó á reir.\"},{\"heading\":false,\"text\":\"--Ya podía usted figurarse--dijo--que las píldoras eran de miga de pan. El curandero (¡si sería listo!) mandó que no las viese nadie... para que á nadie se le ocurriese analizarlas. ¡El maldito análisis lo seca todo!\"}]},{\"title\":\"La sirena\",\"blocks\":[{\"heading\":false,\"text\":\"No es posible pintar el cuidado y desvelo con que la ratona madre atendió á su camada de ratoncillos. Gordos y lucios los crió, y alegres y vivarachos y con un pelaje ceniciento tan brillante que daba gozo: y no queriendo dejar lo divino por lo humano, prodigó á sus vástagos avisos morales sabios y rectos, y les puso en guardia contra las asechanzas y peligros del pícaro mundo. «Serán unos ratones de seso y buen juicio», decía para sí la ratona, al ver cuán atentamente la oían, y cómo fruncían plácidamente el hociquito en señal de gustosa aprobación.\"},{\"heading\":false,\"text\":\"Mas yo os contaré aquí, muy en secreto, que los ratoncillos se mostraban tan formales, porque aún no habían asomado la cabeza fuera del agujero donde los agasajaba su mamá. Practicada en el tronco de un árbol la madriguera, les cobijaba á maravilla, y era abrigada en invierno y fresca en verano, mullida siempre, y tan oculta, que los chiquillos de la escuela ni sospechaban que allí habitase una familia ratonil.\"},{\"heading\":false,\"text\":\"Sin embargo, de los tres de la nidada, uno ya empezaba á desear sacar el hocico, á soñar con retozos, deportes y correteos por el verde prado, que al pie del árbol se extendía alegre é incitante, esmaltado de varias flores y bullente de insectos, mariposas y reptiles. «Me gustaría por los gustares bajar ahí», pensaba el joven ratón, sin atreverse á decirlo en voz alta, de puro miedo á su madre. Un día que se le escapó alguna señal de su deseo, la madre exclamó trémula de espanto: «Ni en broma lo digas, criatura. Si no quieres que me disguste mucho, no vuelvas á hablar de salir al prado.»\"},{\"heading\":false,\"text\":\"¿Creeréis que la prohibición le quitó al ratoncillo las ganas? ¡Bah! Ya sabéis que las prohibiciones son espuela del antojo.--No atreviéndose á bajar aún el antojadizo, se pasaba las horas muertas mirando al prado deleitable. ¡Qué bueno sería trotar por entre aquella hierba suave y perfumada! ¡Qué simpático remojarse en el limpio arroyuelo que bañaba de aljófar las raíces de sauces y mimbreras! ¡Qué divertido dar caza á los viboreznos y lagartijas que se deslizaban estremeciendo el follaje y haciendo relumbrar al sol los tonos metálicos de su elegante cuerpo! ¿Por qué, vamos á ver, por qué prohibía tan inocentes recreos la madre ratona?\"},{\"heading\":false,\"text\":\"Un día que la mamá había salido, según costumbre, en busca de sustento para su prole, el hijo se asomó al agujero, echando más de la mitad del tronco fuera. De pronto sintió como un choque eléctrico y vió cruzar por el prado un ser encantador. Era ni más ni menos que una gatita blanca como la nieve, que fijaba en el ratoncillo sus anchas pupilas de esmeralda.\"},{\"heading\":false,\"text\":\"Quedóse el ratón fascinado, absorto. Nunca había visto cosa más linda que la tal gata blanca. ¡Qué gracia y gentileza en sus movimientos, qué soltura en su flexible andar, qué monería en su cara picaresca, y qué virginal candor en su ropaje de armiño! ¡Y qué decir de aquellos ojos verdes con reflejos áureos, aquellos ojos cuyo mirar derretía, incendiaba el corazón!\"},{\"heading\":false,\"text\":\"A no estar tan próxima la hora en que solía regresar á la guarida la madre, el ratón se hubiese arrojado sin vacilar de su nido para acercarse á la preciosa gata. Le contuvieron el temor y el hábito de obedecer, que siempre reprimen un tanto, al principio, los ímpetus rebeldes; pero lo que no acertó á sujetar fué su lengua, y loco de entusiasmo, refirió á la mamá cómo le tenía fuera de sí la aparición de la gata celeste.\"},{\"heading\":false,\"text\":\"--Qué, ¿has visto á ese monstruo?--exclamó la madre.\"},{\"heading\":false,\"text\":\"--¡Monstruo una criatura tan encantadora!--suspiró el ratoncillo.\"},{\"heading\":false,\"text\":\"--Monstruo horrible, el más funesto, el más sanguinario, el más atroz que, por tu negra suerte, pudiste encontrar. Huye de él, hijo mío, como del fuego: mira que en huir te va la vida; mira que tu padre pereció en las garras de esa maldita fiera, y que todas mis lágrimas son obra suya.\"},{\"heading\":false,\"text\":\"--Madre--repuso atónito el ratoncillo--apenas puedo creer lo que me aseguras. El agua que corre limpia y clara entre las flores del prado no tiene los matices de aquellos cándidos ojos ya verdes, ya azulados, siempre dulces, donde siempre juega misteriosamente la luz. Los pétalos de las azucenas y de los lirios del valle ceden en blancura á su nevada piel, que debe de ser más suave que el terciopelo y más flexible que la seda. ¿Cómo quieres que vea un monstruo sanguinario y horrible en la gata? ¡Ay, madre! desde que la contemplé, sólo en ella pienso. Cuanto no es ella, me parece indigno de existir. Antes me gustaban el prado y el cielo y los árboles. Ahora todo me cansa y todo lo desprecio. Madre, cúrame de este mal, porque me siento tan triste, que creo que se me va á acabar la vida.\"},{\"heading\":false,\"text\":\"Ya supondréis que la pobre ratona haría cuanto cabe para distraer y aliviar á su retoño. A fin de cambiar sus pensamientos en otros más lícitos, llevóle al agujero de unas ratas algo parientas suyas, jóvenes, ricas y honradas, que vivían royendo el trigo de repleto granero; pero el ratón se aburría de muerte entre los montones de grano, en la obscuridad de la troj, y echaba de menos el prado, que iluminaba, antes que el sol, la presencia de la gata blanca. Porque ya varias veces la había visto pasar juguetona y ligera, fijando sus radiantes pupilas en las inaccesibles alturas del árbol, y siempre que la gata aparecía, el ratón sentía ensanchársele la vida y escapársele el alma--sí, el alma, porque el amor hasta en las bestias la infunde--detrás de aquella maga de los verdes ojos.\"},{\"heading\":false,\"text\":\"No hubiese querido la ratona en tan críticas circunstancias separarse un minuto de su hijo, pero era forzoso salir á cazar, á procurar subsistencia para la familia, y llegó una mañana en que habiendo madrugado la ratona á dejar el nido antes de que amaneciese, el joven ratón, pensativo y melancólico, se asomó al agujero para ver nacer el día. Recta faja dorada franjeó el horizonte; poco á poco la bruma se rasgó y fué absorbiéndose en la clara pureza del cielo, por donde el sol ascendía como una rosa de oro pálido; los pajaritos saludaron su gloriosa luz con un himno de alegría alborozado y triunfal, y sobre la hierba, aljofarada aún de rocío, como sobre una red de diamantes, mostróse pasando con aristocrática delicadeza y remilgada precaución, la hermosa gata blanca.\"},{\"heading\":false,\"text\":\"Exhaló el ratón un chillido de júbilo; la gata le miraba, parecía llamarle, invitarle á que descendiese.--¿Quieres jugar conmigo?--preguntóla él, sin reflexionar, sin acordarse para nada de las maternales advertencias.--Baja--pareció contestar con sus ojos misteriosos la gatita. Y el ratón bajó aprisa, disparado, ebrio de felicidad, y el juego dió principio, con muchos saltos y carreras. Fingía huir la gata; escondíase entre sauces y mimbres, y cuando el ratón se cansaba de perseguirla, ella se dejaba caer sobre la muelle alfombra del prado, y escondiendo las uñas recibía con las patitas de terciopelo al ratón, y ya le despedía, en broma, ya le estrechaba, retozando, en deleitosa mezcla é indescifrable confusión de tratamientos ásperos y dulces.\"},{\"heading\":false,\"text\":\"Nunca sabía el ratón, en aquel juego de veleidades, si iba á ser acogido con demostración tierna y mimosa ó con fiero y desdeñoso zarpazo; y en los amados ojos de la esfinge tan pronto veía piélagos de voluptuosidad y relámpagos de risa, como destellos de ferocidad y chispazos sombríos y crueles. Más de una vez creyó notar que las patitas blandas y muertas se crispaban de súbito, y que bajo lo afelpado de la piel surgían uñas de acero. Y ¡cosa rara! no bien pensaba advertir síntomas tan alarmantes, el ratón cerraba los párpados y volvía gozoso y tembloroso á solazarse con la gata blanca.\"},{\"heading\":false,\"text\":\"Duraba aún el juego, cuando por la tarde regresó la ratona y vió de lejos la escena y á su hijo mano á mano con el monstruo. Llorando y desesperada gritóle desde lejos:--Hijo mío, que te pierdes.--El ratón, por supuesto, no la hizo maldito caso. ¡Sí, para oir consejos estaba él! Subido al quinto cielo, nunca el juego le había encantado más. La gata, por el contrario, empezaba á fatigarse y á sospechar que había perdido bastante tiempo con un ratoncillo de mala muerte; y al notar que iba á ponerse el sol, que se hacía tarde--sin modificar apenas su actitud, siempre graciosa y juguetona, como el que no hace nada--torció la cabeza, aseguró con la boca al ratoncillo, hincó los agudos dientes... y le lanzó al aire palpitante y moribundo, para recibirle en las uñas, tendidas con violencia feroz...\"},{\"heading\":false,\"text\":\"A punto que una nube de sangre cubría ya los ojos del desdichado, y el delirio de la agonía ofuscaba sus sentidos, todavía pudo oirse cómo murmuraba débilmente:--¿Quieres jugar conmigo, gatita blanca?\"},{\"heading\":false,\"text\":\"Por eso su madre hizo mal en llorar amargamente al incauto ratón. ¡El espiró tan satisfecho, tan á gusto!\"}]},{\"title\":\"Así y todo\",\"blocks\":[{\"heading\":false,\"text\":\"La sanción penal para la mujer--dijo en voz incisiva Carmona, aficionado á referir casos de esos que dan escalofríos--es no encontrar hombre dispuesto á ofrecerla mano de esposo. Una imperceptible sombra, un pecadillo de coquetería ó de ligereza, cualquier genialidad, la más leve impremeditación, bastan para empañar el buen nombre de una doncella, que podrá ser honestísima, pero que, cargada con el sambenito, ya se queda soltera hasta la consumación de los siglos, sin remedio humano. Sucediendo así, ¿cómo se explica que infinitas mujeres notoriamente infames, y con razón difamadas, si cien veces enviudan, otras ciento hallan quien las lleve al altar? Para probarles este curioso fenómeno, les contaré un suceso presenciado allá en mis mocedades, que me produjo impresión tan indeleble, que jamás en toda mi vida me ocurrió la idea de casarme. Sí; por culpa de aquella historia moriré solero,--y no me pesa, bien lo sabe Dios.\"},{\"heading\":false,\"text\":\"El lance pasó en M***, donde estaba de guarnición uno de los regimientos más lucidos del ejército español, que por su arrojo y decisión en atacar había merecido el glorioso sobrenombre de _El Adelantado_. Era yo entrañable amigo del teniente Ramiro Quesada, mozo de arrogante figura y ardorosa cabeza, uno de esos atolondrados simpáticos, á quienes queremos como se quiere á los niños. No salía Ramiro sin mí; juntos íbamos al teatro, á los saraos, á las juergas--que ya existían entonces aunque las llamásemos de otro modo;--juntos dábamos largos paseos á caballo, y juntos hacíamos corvetear á nuestras monturas ante las floridas rejas. Nos confiábamos nuestros amoríos, nuestros apurillos de dinero, nuestras ganancias al juego, nuestros sueños y nuestras esperanzas de los veinticinco años. No éramos él ni yo precisamente unos anacoretas, pero tampoco unos perdidos: muchachos alegres, y nada más.\"},{\"heading\":false,\"text\":\"De repente noté que Ramiro se volvía huraño, y retrayéndose de mi trato y compañía se daba á andar solo, como si tuviese algo que le importase encubrir. Vano intento, porque en M*** no caben tapujos. Poco tardamos en averiguar la razón del cambio de carácter del teniente. La clave del enigma no era sino la esposa del capitán Ortiz, una de esas hembras que no calificaré de muy hermosas, pero peores que si lo fuesen: morena, menuda, salerosa al andar, descolorida, de ojos que parecían candelas del infierno y una cintura redonda de las que se pueden rodear con una liga. Ortiz, al parecer (y con motivo, pero sin fruto), era extremadamente celoso, y Ramiro, para avistarse con su tormento, necesitaba emplear ardides de prisionero ó de salvaje. El día en que se le frustraba una cita ó se le malograba furtivo coloquio en la reja que abría sobre una callejuela obscura y solitaria, estaba el pobre muchacho como demente: ni contestaba si le hablábamos. Aunque yo no alardease de moralista, ni tuviese autoridad para aconsejar, y menos en tales materias, declaro que las relaciones ilícitas de mi amigo me desazonaban mucho, y un presentimiento--le llamo así, porque no sé cómo definir el disgusto y la inquietud que sentía--me anunciaba que algo grave, algo penoso debían acarrearle á Ramiro aquellos malos pasos. Con todo, lejos estaba--á mil leguas de suponer la tragedia que aconteció.\"},{\"heading\":false,\"text\":\"Cierta mañana esparcióse por M*** la nueva de que el capitán Ortiz había sido encontrado muerto, con un balazo en el pecho y otro en la cabeza, casi á las puertas de su domicilio, cerca de la esquina donde se abría la callejuela lóbrega. En los primeros momentos no me asaltó la terrible sospecha: creía á Ramiro noble y leal, y sólo cuando el rumor público le señaló, comprendí que únicamente él, poseído del demonio, podía haber realizado la obra de tinieblas...\"},{\"heading\":false,\"text\":\"A las pocas horas de descubrirse el cadáver, Ramiro fué preso. Reunióse el Consejo de guerra, y la causa marchó con la fulminante rapidez que caracteriza á la justicia militar, estimulada por la voluntad expresa del Capitán General, que deseaba se cumpliesen á rajatabla las prescripciones legales y se enterrasen á la vez la víctima y el asesino. Al pronto Ramiro intentó negar; pero dos ó tres frases de indignación del Fiscal provocaron en él un arranque de altiva franqueza, y confesó de plano que á traición había disparado dos pistoletazos, la noche anterior, al capitán Ortiz. En cuanto á los móviles del crimen, juró y perjuró que no eran otros sino ofensas de jefe á subalterno, rencores por cuestiones de servicio. Llamada á declarar la esposa de Ortiz, compareció de negro, impávida, y aseguró que apenas conocía al asesino de vista. Este, sin pestañear, confirmó la declaración de la señora; y hallándose el reo convicto y confeso, y no habiendo tiempo ni necesidad de más averiguaciones, se pronunció la sentencia de muerte, y Ramiro entró en capilla á las tres de la tarde, para ser arcabuceado al rayar el siguiente día, á las veinticuatro horas justas del crimen.\"},{\"heading\":false,\"text\":\"No necesito decir que en la capilla me constituí al lado de mi amigo, que demostraba estoica entereza. Sabiendo cuánto alivia una confidencia, un desahogo, le dirigí preguntas afectuosas, llenas de interés; pero el reo se encerró en un silencio sombrío, y noté que tenía los ojos tenazmente fijos en la puerta de la capilla como en espera de que diese paso á _alguien_... ¡Lo que esperaba el sin ventura--no necesité para adivinarlo gran perspicacia--era la llegada de la mujer por quien iba á beber el amargo trago! Sin duda que _ella_ no podía faltar; no podía negarle el supremo consuelo de la despedida; sin duda, el sordo ruido de pasos que resonaba en la antecámara era el de los suyos, que hacían vacilantes el miedo y el dolor... Pero corrió la tarde, empezaron á transcurrir lentas y solemnes las horas de la última noche, y la esperanza abandonó al sentenciado. El sacerdote que le exhortaba y había de absolverle y darle la sagrada comunión antes que el sol asomase en el horizonte, se retiró un momento á descansar, y solo yo con Ramiro, comprendí que por fin se abrían sus lívidos labios.\"},{\"heading\":false,\"text\":\"--Hace un momento sentía que _ella_ no viniese--murmuró cogiéndome las manos entre las suyas abrasadoras.--Ahora me alegro. Ya que me cuesta la vida, que no me cueste también el alma. ¿Que cómo hice la atrocidad, el cobarde asesinato de Ortiz? Mira, casi no lo sé. Me parece que quien cometió esa acción villana no fué Ramiro Quesada, sino otra persona, un hombre distinto de mí, que se me entró en el cuerpo. ¿Te acuerdas de lo alegre, de lo franco que era yo? Desde que me acerqué á... esa mujer... me volví otro. Estaba embrujado... Su marido, á quien ofendíamos, me parecía mi enemigo personal, el obstáculo á nuestra felicidad; le odiaba... creo que más de lo que la amaba á ella. Así que ella lo notó... ¡guárdame siempre el secreto! ¡no lo digas ni á tu madre! empezó á insinuarme, con medias palabras, la posibilidad del crimen. No hablábamos claro de ese asunto, pero nos entendíamos perfectamente; formábamos planes de retirarnos al campo _después_, y hasta--mira qué detalle--ella se compró un traje negro nuevo, diciendo que _eso siempre sirve_. Como un tornillo se fijó en mi cerebro el propósito del crimen. Y así que ella me vió resuelto, se franqueó, me exaltó más, me ofreció que compartiría mi destino, fuese el que fuese...\"},{\"heading\":false,\"text\":\"Aquí se detuvo Ramiro, y vi que se alteraba más profundamente su rostro. Con voz húmeda murmuró:\"},{\"heading\":false,\"text\":\"--Yo no quería tanto... ¡Compartir mi destino! Ya ves que ante el Consejo he logrado salvarla... Prefiero morir solo... Pero verla aquí, un momento... antes de... Al fin, si fuí asesino, lo fuí por ella, sólo por ella... ¡Maldita sea mi suerte! Si no conozco á esa mujer, soy siempre honrado y tal vez me matan defendiendo á la Patria. ¡El sino del hombre!\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"--¿Y le fusilaron?--preguntamos ansiosos.\"},{\"heading\":false,\"text\":\"--¡Pues no! Según deseaba el General, á un tiempo se cavó la hoya del marido y la del amante. Yo, después del horrible día, me marché de M***, donde me consumía el tedio. Al volver, pasados cinco años, tuve curiosidad de saber qué había sido de la esposa del capitán Ortiz... y aquí de lo que decíamos: supe que vivía tranquila, casada en segundas nupcias con un acaudalado caballero. Sin embargo, en M*** era pública la causa del triste fin de Ramiro...\"},{\"heading\":false,\"text\":\"Acabó así su relato Carmona, y vimos que inclinaba la cabeza, abrumado por memorias crueles.\"}]},{\"title\":\"La cabellera de Laura\",\"blocks\":[{\"heading\":false,\"text\":\"Madre é hija vivían, si vivir se llama aquello, en húmedo zaquizamí, al cual se bajaba por los raídos peldaños de una escalera abierta en la tierra misma: la claridad entraba á duras penas, macilenta y recelosa, al través de un ventanillo enrejado; y la única habitación les servía de cocina, dormitorio y cámara.\"},{\"heading\":false,\"text\":\"Encerrada allí pasaba Laura los días, trabajando afanosamente en sus randas y picos de encaje, sin salir nunca ni ver la luz del sol, cuidando á su madre achacosa, y consolándola siempre que renegaba de la adversa fortuna. ¡Hallarse reducidas á tal extremidad dos damas de rancio abolengo, antaño poseedoras de haciendas, dehesas y joyas á porrillo! ¡Acostarse á la luz de un candil ellas, á quienes habían alumbrado pajes con velas de cera en candelabros de plata! No lo podía sufrir la hoy menesterosa señora, y cuando su hija, con el acento tranquilo de la resignación, la aconsejaba someterse á la divina voluntad, sus labios exhalaban murmullos de impaciencia y coléricas maldiciones.\"},{\"heading\":false,\"text\":\"Como siempre los males pueden crecer, llegó un invierno de los más rigurosos, y faltó á Laura el trabajo con que ganaba el sustento. A la decente pobreza sustituyó la negra miseria; á la escasez, el hambre de cóncavas mejillas y dientes amarillos y largos.\"},{\"heading\":false,\"text\":\"Entonces, con acerba ironía, la madre se mofó de Laura, que pensaba, la muy ñoña y la muy necia, asegurar el pan por medio de la labor y las constantes vigilias. ¡Valiente pan comería así que se quedase ciega! Saldría con un perrito á pedir limosna... ¡Ah, si no fuese tan boba y tan mala hija--teniendo aquel talle, aquel rostro y aquella mata de pelo como oro cendrado, que llegaba hasta los pies--no dejaría que su madre se desmayase por falta de alimento! Al oir estas insinuaciones, Laura se estremeció de vergüenza y quiso responder enojada; pero recordando que su madre estaba en ayunas desde hacía muchas horas, se cubrió el rostro con las manos y rompió á sollozar. De pronto, como quien adopta una resolución súbita y firme, púsose en pie, se envolvió en un ancho capuchón de lana obscura, y salió á la calle, que raras veces pisaba, convencida de que el retiro es la salvaguardia del recato. Sin titubear fué en dirección de un tenducho que había entrevisto y donde creía poder feriar el solo tesoro de que estaba secretamente envanecida y orgullosa. Era dueña del baratillo la astuta vieja Brasilda,--gran componedora de voluntades con ribetes de hechicera,--y, muy encubierto el rostro, entró Laura en la equívoca mansión.\"},{\"heading\":false,\"text\":\"Como Brasilda preguntase maliciosamente qué traía á vender la tapada y gallarda moza, Laura, sin dejar de esconder el semblante en los pliegues del capuz, se volvió de espaldas y mostró tendida la espléndida cabellera rubia, brillante y suave más que la seda, y que, con magnífico alarde, rebosando de la orla de la saya, barría el suelo. «Esto vendo en diez escudos--exclamó--y córtese ahora mismo.» Convenía la proposición á la vieja, porque la mata de pelo daba para muchas pelucas y postizos, y asiendo unas tijeras segó y tonsuró la copiosa melena. Al observar que la moza seguía encubriendo el rostro, y creyendo advertir que lloraba muy bajo, silbó á su oído: «Si eres doncella y tan hermosa como promete tu cabello, aquí te esperan, no diez escudos, sino cien ó doscientos, cuando te venga en voluntad.»\"},{\"heading\":false,\"text\":\"Recogió Laura el dinero y alejóse sin responder palabra; en la puerta se cruzó con un caballero, de buen talle y porte, que no reparó en ella: Laura sí le miró á hurtadillas y sin querer le encontró galán. El caballero que penetraba en la mansión de la bruja era don Luis de Meneses, el mozo más rico, libre y desenfrenado de toda la ciudad, el cual no visitaba á humo de pajas á la madre Brasilda, sino que acudía allí como el cazador á que se le señalen do está la caza, y que se la ojeen y acorralen para asegurarla y matarla á gusto.\"},{\"heading\":false,\"text\":\"Después de un rato de conversación, don Luis divisó la soberana cabellera rubia, que sobre un paño blanco había extendido la vieja, y en la cual los destellos del velón, siempre encendido en las obscuridades del tenducho, rielaban como en lago de oro. «¿De qué mujer es ese pelo?»--preguntó sorprendido el galán.--«A fe que no lo sé, hijo»--contestó la vieja.--«Una moza acaba de estar aquí, muy airosa de cuerpo, pero tapadísima de cara, que no logré vérsela; vendióme esa mata, cobró y con extraño misterio se fué un minuto antes que entrases...»\"},{\"heading\":false,\"text\":\"--«¿Por qué no la seguiste, buena pieza?»--«Porque sin duda ella está más pobre que las arañas, y volverá á ganar los cien escudos que la ofrecí...»--«¡Bruja condenada! Ese pelo es mío, y la mujer también, si parece.» Y don Luis aflojó la bolsa, cogió delicadamente el paño y el tesoro que contenía, y ocultándolo bajo el capotillo, se volvió á su casa.\"},{\"heading\":false,\"text\":\"Desde aquel día realizóse en don Luis un cambio sorprendente. Renunciando á sus galanteos y aventuras, olvidando el juego, las burlas y los desafíos, pareció otro hombre. Se le veía, eso sí, en la calle, en el paseo, en la iglesia; sus ojos ávidos registraban y escudriñaban sin cesar, buscando algo que le importaba mucho; pero al anochecer se recogía, y en vida honesta y arreglada no tenían que reprenderle los devotos viejos, de grave apostura y rosario gordo. No faltó quien dijese que el mozo, tocado de la gracia, andaba en meterse capuchino; y es que ni sabían, ni podían sospechar que don Luis estaba enamorado, ciegamente enamorado, de la cabellera rubia.\"},{\"heading\":false,\"text\":\"Habiéndola colocado respetuosamente sobre un cojín de tisú de plata, se pasaba ante ella las horas muertas, ya besándola en ideal éxtasis de devoción, como á venerada reliquia, ya estrujándola con frenesí de amante que quisiera despedazar y morder lo mismo que adora. Exaltada la imaginación de don Luis por la vista de aquella cascada de oro, de aquella crin en que Febo parecía haber dejado presos sus rayos juguetones, y de la cual se desprendía un aroma vivo, un olor de juventud y de pureza, fantaseaba el tronco á que tal follaje correspondía y adivinaba la mata larguísima, caudalosa, perfumada, cayendo en crenchas y vedijas sobre unas espaldas de nieve, sobre unas formas virginales de rosa y nácar, ó rodeando, como nimbo de santa imagen, un rostro de angelical expresión en que se abrían las flores azules de los luminosos ojos. Había ideas y recelos que enloquecían al soñador amante. ¿Quién sabe si la infeliz hermosa, después de vender su cabello por conservar la honestidad, había tenido que perder la honestidad por conservar la vida?\"},{\"heading\":false,\"text\":\"Con la fatiga de tal pensamiento, don Luis aborrecía el comer, se consumía de rabia y se abrasaba en extraños celos. Hecho un azotacalles, no cesaba de inquirir, pretendiendo ver al través de todos los postigos y calar todas las rejas y celosías. ¡Trabajo perdido! Ninguna cabeza juvenil cubierta de sortijas doradas y cortas de aquel matiz único, incomparable, se ofrecía á sus ojos. Don Luis adelgazaba, se desmejoraba, estaba á pique de desvariar, cada vez que la vieja hechicera Brasilda, aturdida y desconsolada, repetía alzando las manos secas:\"},{\"heading\":false,\"text\":\"--Bruja será también la del cabello de oro, y habráse untado y volado por la chimenea... No parece, hijo, no parece por más que me descuajo buscándola...\"},{\"heading\":false,\"text\":\"Perdido ya de amores don Luis, como hombre á quien le han dado extraño bebedizo, llegó al caso de temer morirse de pasión y furia celosa, y apretando al corazón la cabellera, cuyas roscas le acariciaban las manos febriles, hizo un voto.--«Que encuentre á tu dueña, y sea rica ó pobre, buena ó mala, noble ó de plebeya estirpe, con ella me casaré. Pongo por testigo á este Crucifijo que me escucha.»--Después del voto, lleno de esperanza y de ilusión salió don Luis á la calle, y al obscurecer, como fuese muy embozado, le paró cerca de su puerta una pobre, envuelta y cubierta con un viejísimo capuz de lana.\"},{\"heading\":false,\"text\":\"--Señor caballero--decía en voz lastimera y humilde,--¿necesitan por casa de su merced una labrandera buena y diligente? No hay donde trabajar, y mi madre no tiene qué comer.\"},{\"heading\":false,\"text\":\"--Esa es mi casa--respondió distraidamente don Luis, que pensaba en sus fantásticos amores;--ven mañana, que tendrás harta labor... Toma á cuenta,--y dejó en la mano tendida un escudo.\"},{\"heading\":false,\"text\":\"Al otro día, Laura, sentada en el hueco de una reja de la casa de don Luis, con una canastilla de ropa blanca delante, cosía en silencio, sin tomar parte en la charla de las dueñas; sufría al dejar su morada, su enferma, su retiro; la fatiga encendía sus mejillas antes pálidas. Entraban por la reja los dardos del sol, y se prendían en los anillos, cortos y sedosos como plumón de pajarito nuevo, de la cabeza descubierta, que no velaba el capuz. Y, casualmente, pasó don Luis tan absorto, que ni miró á la joven labrandera. Pero ella, reconociendo en don Luis al caballero galán de quien no había cesado de acordarse,--el que vió cuando salía de vender su cabellera en casa de la bruja,--exhaló un grito involuntario... Al oirlo, volvióse don Luis, y cruzando las manos, creyó que alguna aparición del cielo le visitaba, pues reconoció el matiz único de la melena rubia en la ensortijada testa que bañaba el sol... Y dirigiéndose á las dueñas y á las mozas de servicio con imperio y ufanía, dijo solemnemente:\"},{\"heading\":false,\"text\":\"--No labréis más; hoy es día de fiesta; saludad á vuestra señora...\"}]},{\"title\":\"Delincuente honrado\",\"blocks\":[{\"heading\":false,\"text\":\"De todos los reos de muerte que he asistido en sus últimos instantes--nos dijo el Padre Téllez, que aquel día estaba animado y verboso--el que me infundió mayor lástima fué un zapatero de viejo, asesino de su hija única. El crimen era horrible. El tal zapatero, después de haber tenido á la pobre muchacha rigurosamente encerrada entre cuatro paredes; después de reprenderla por asomarse á la ventana; después de maltratarla, pegándola por leves descuidos, acabó llegándose una noche á su cama, y clavándola en la garganta el cuchillo de cortar suela. La pobrecilla parece que no tuvo tiempo ni de dar un grito, porque el golpe segó la carótida. Esos cuchillos son un arma atroz, y al padre no le tembló la mano; de modo que la muchacha pasó, sin transición, del sueño á la eternidad.\"},{\"heading\":false,\"text\":\"La indignación de las comadres del barrio y de cuantos vieron el cadáver de una criatura preciosa de diez y siete años, tan alevosamente sacrificada, pesó sobre el Jurado; y como el asesino no se defendía y parecía medio estúpido, le condenaron á la última pena. Cuando tuve que ejercer con él mi sagrado ministerio, á la verdad, temí encontrar, detrás de un rostro de fiera, un corazón de corcho, ó unos sentimientos monstruosos y salvajes. Lo que ví fué un anciano de blanquísimos cabellos, cara demacrada y ojos enrojecidos, merced al continuo fluir de las lágrimas, que poco á poco se deslizaban por las mejillas consumidas, y á veces paraban en los labios temblones, donde el criminal, sin querer, las bebía y saboreaba su amargor.\"},{\"heading\":false,\"text\":\"Lejos de hallarle rebelde á la divina palabra, apenas entré en su celda se abrazó á mis rodillas y me pidió que le escuchase en confesión, rogándome también que, después de cumplir el fallo de la justicia, hiciese públicas sus revelaciones en los periódicos, para que rehabilitasen su memoria y quedase su decoro como correspondía. No juzgué procedente acceder en este particular á sus deseos: pero hoy los invoco, y me autorizan para contarles á ustedes la historia. Procuraré recordar el mismo lenguaje de que él se sirvió, y no omitiré las repeticiones, que prueban el trastorno de su mísera cabeza:\"},{\"heading\":false,\"text\":\"»--Padre confesor--empezó por decir,--ante todo sepa usted que yo soy un hombre decente, todo un caballero. Esa niña... que maté... nació... al año de haberme casado. Era bonita, y su madre también... ¡ya lo creo! preciosa, que daba gloria el mirarla! Yo tenía ya algunos añitos... y ella, una moza de rumbo, más fresca que las mismas rosas. Digo la madre, señor; digo su madre, porque por la madre tenemos que principiar. Los hijos, así como heredan los dineros del que los tiene... heredan otras cosas... Usted, que sabrá mucho, me entenderá. Yo no sé nada, pero... á caballero no me ha ganado nadie!\"},{\"heading\":false,\"text\":\"La madre... yo me miraba en sus ojos, porque la quería de alma, según corresponde á un marido bueno. Le hacía regalos; trabajaba día y noche para que tuviese su ropa maja y su mantón y sus aretes, y sobre todo... ¡porque eso es antes! á diario su puchero sano, y cuando parió, su cuartillo de vino y su gallina... No me remuerde la conciencia de haberla escatimado un real. Ella era alegre y cantaba como una calandria, y á mí se me quitaban las penas de oirla. Lo malo fué que como la celebraron la voz y las coplas, y empezaron á remolinarse para escucharla, y el uno que llega y el otro que se pega, y éste que encaja una pulla, y aquél que suelta un requiebro... en fin, ví que se ponía aquello muy mal, y la dije lo que venía al caso. ¿Sabe usted lo que me contestó? Que no lo podía remediar, que la gustaba el gentío y oir cómo la jaleaban, que cada cual es según su natural y que no le rompiese la cabeza con sermones... De allí á un mes--no se me olvida la fecha, el día de la Candelaria--desapareció de casa, sin dar siquiera un beso á la niña... que tenía sus cinco añitos y era como un sol.»\"},{\"heading\":false,\"text\":\"--Aquí--intercaló el Padre Téllez--tuvo una crisis de sollozos, y por poco me enternezco yo también, á pesar de que la costumbre de asistir á los reos endurece y curte. Le consolé cuanto era posible, le di á beber un trago de anís, y el desdichado prosiguió.\"},{\"heading\":false,\"text\":\"«Supe luego que andaba por los coros de los teatros, y sabe Dios cómo... y lo que más me barajaba los sesos--¡porque la honra trabaja mucho!--era que me decían los amigos, al pasar delante de mi obrador:--No tienes vergüenza... Yo que tú, la mato.--De tanto oirlo, se me pegó el estribillo, y mientras batía suela, ¡tan, tan, catán! repetía en alto:--No tengo vergüenza... ¡Había que matarla!--Sólo que ni la encontré en jamás, ni tuve ánimos para echarme en su busca. Y así que pasaron tres años, nadie me venía con que la matase, porque ella rodaba por Andalucía, hasta que se la llevaron á América... ¡qué sé yo adonde! ¡Si vive y lee los diarios y ve como murió su hija...!» El reo tuvo un ataque de risa convulsiva, y le sosegué otra vez á fuerza de exhortaciones y consejos.\"},{\"heading\":false,\"text\":\"«Así que se me quitó de la imaginación la madre, empecé á cuidar de la niña. No tenía otra cosa para qué mirar en el mundo. Me propuse que no había de perderse, ni arrimarme otro tiznón, y no la dejé salir ni al portal. Aunque me dijese, es un verbigracia:--«Padre, tengo ganas de correr» ó--«Padre, me pide el cuerpo ir á la plazuela»--nada, yo sujetándola, que se divirtiese con su canario, ó con los pliegos de aleluyas, ó con la maceta de albahaca, ¡pero sin sacar un dedo fuera! Y así que fué espigando, y me hice cargo de que era muy bonita, tan bonita como su madre, y parecida á ella como una gota á otra gota... y con una voz de ángel también, se me abrieron los ojos de á cuarta, y dije:--No, lo que es tú... no has de echarme el borrón.--Y me convertí en espía, y la velé hasta el sueño, y no contento con guardarla dentro de casa, me paseaba por la callejuela debajo de su ventana, á ver si andaba por allí algún zángano; tanto que la castañera de la esquina me dijo así:--Abuelo, está usted chiflado. ¿A quién se le ocurre rondar á su propia hija? ¡Qué viejos mas escamones!--Pero no lo podía remediar. Toda cuanta candidez y buena fe había tenido con la madre, ahora se me volvía desconfianza; se me había clavado aquí, entre las cejas, que mi hija se perdería, que era infalible que se perdiese, sobre todo si daba en cantar; y me eché de rodillas delante de ella, y la obligué á que me jurase que no cantaría nunca, así se hundiese el mundo. Y me lo juró: sólo que, como ya no era yo aquel de antes, de allí á pocas mañanas, acechando desde la esquina, la veo que abre la ventana, que se pone á regar las macetas, y que al mismo tiempo, á competencia con el canario, rompe á cantar... Me dió la sangre una vuelta redonda y se me quedaron las manos frías. Volví á casa, entré en el cuarto de la muchacha, la cogí por el pelo y debí de pegarla bastante, porque gritó y estuvo más de una semana con una venda. ¿Creerá usted, Padre, que se enmendó? A los quince días vuelvo á rondar y vuelve á asomarse, y otra vez el canticio, y enfrente un grupo de mozalbetes que se para y la dice muchos olés... Callé; no entré á castigarla; y por la tarde, mientras batía mi suela, me parecía que una voz rara, como de algún chulo que se reía de mí, me decía lo mismo que doce años antes:--No tienes vergüenza... Había que matarla.--Cené muy triste, y después de que me acosté, la misma voz, erre que erre: Matarla, matarla...--Entonces me levanté despacio, cogí la herramienta, fuí en puntillas, me acerqué á la cama, y de un solo golpe... Ahora hagan de mí lo que quieran, que ya tengo mi honra desempeñada.»\"},{\"heading\":false,\"text\":\"--¿Creerán ustedes,--añadió el Padre Téllez, que no le pude quitar la tema de la honra? Se arrepentía... pero á los dos minutos volvía á porfiar que era un caballero, y su conducta, más que culpable, ejemplar... En este terreno casi murió impenitente...\"},{\"heading\":false,\"text\":\"--Estaría loco--dijimos, á fin de consolar al sacerdote, que se había quedado muy abatido al terminar su relato.\"}]},{\"title\":\"Primer amor\",\"blocks\":[{\"heading\":false,\"text\":\"¿Qué edad contaría yo á la sazón? ¿Once ó doce años? Más bien serían trece, porque antes es demasiado temprano para enamorarse tan de veras; pero no me atrevo á asegurar nada, considerando que en los países meridionales madruga mucho el corazón, dado que esta víscera tenga la culpa de semejantes trastornos.\"},{\"heading\":false,\"text\":\"Si no recuerdo bien el _cuándo_, por lo menos puedo decir con completa exactitud el _cómo_ empezó mi pasión á revelarse. Gustábame mucho--después de que mi tía se largaba á la iglesia á hacer sus devociones vespertinas--colarme en su dormitorio y revolverle los cajones de la cómoda, que los tenía en un orden admirable. Aquellos cajones eran para mí un museo: siempre tropezaba en ellos con alguna cosa rara, antigua, que exhalaba un olorcillo arcáico y discreto, el aroma de los abanicos de sándalo que andaban por allí perfumando la ropa blanca. Acericos de raso descolorido ya; mitones de malla, muy doblados entre papel de seda; estampitas de santos; enseres de costura; un _ridículo_ de terciopelo azul bordado de canutillo; un rosario de ámbar y plata, fueron apareciendo por los rincones: yo los curioseaba y los volvía á su sitio. Pero un día--me acuerdo lo mismo que si fuese hoy--en la esquina del cajón superior y al través de unos cuellos de rancio encaje, ví brillar un objeto dorado.... Metí las manos, arrugué sin querer las puntillas, y saqué un retrato, una miniatura sobre marfil, que mediría tres pulgadas de alto, con marco de oro.\"},{\"heading\":false,\"text\":\"Me quedé como embelesado al mirarla. Un rayo de sol se filtraba por la vidriera y hería la seductora imagen, que parecía querer desprenderse del fondo obscuro y venir hacia mí. Era una criatura hermosísima, como yo no la había visto jamás sino en mis sueños de adolescente, cuando los primeros estremecimientos de la pubertad me causaban, al caer la tarde, vagas tristezas y anhelos indefinibles. Podría la dama del retrato frisar en los veinte y pico; no era una virgencita cándida, capullo á medio abrir, sino una mujer en quien ya resplandecía todo el fulgor de la belleza. Tenía la cara oval, pero no muy prolongada; los labios carnosos, entreabiertos y risueños; los ojos lánguidamente entornados, y un hoyuelo en la barba, que parecía abierto por la yema del dedo juguetón de Cupido. Su peinado era extraño y gracioso: un grupo compacto, á manera de piña de bucles al lado de las sienes y un cesto de trenzas en lo alto de la cabeza. Este peinado antiguo, que remangaba en la nuca, descubría toda la morbidez de la fresca garganta, donde el hoyo de la barbilla se repetía más delicado y suave. En cuanto al vestido..... Yo no acierto á resolver si nuestras abuelas eran de suyo menos recatadas de lo que son nuestras esposas, ó si los confesores de antaño gastaban manga más ancha que los de hogaño; y me inclino á creer esto último, porque hará unos sesenta años las hembras se preciaban de cristianas y devotas, y no desobedecerían á su director de conciencia en cosa tan grave y patente. Lo indudable es que si en el día se presenta alguna señora con el traje de la dama del retrato, ocasiona un motín; pues desde el talle (que nacía casi en el sobaco) sólo la velaban leves ondas de gasa diáfana, señalando, mejor que cubriendo, dos escándalos de nieve, por entre los cuales serpeaba un hilo de perlas, no sin descansar antes en la tersa superficie del satinado escote. Con el propio impudor se ostentaban los brazos redondos, dignos de Juno, rematados por manos esculturales..... Al decir _manos_ no soy exacto, porque en rigor, sólo una mano se veía, y esa apretaba un pañuelo rico.\"},{\"heading\":false,\"text\":\"Aún hoy me asombro del fulminante efecto que la contemplación de aquella miniatura me produjo, y de cómo me quedé arrobado, suspensa la respiración, comiéndome el retrato con los ojos. Ya había yo visto aquí y acullá estampas que representaban mujeres bellas; frecuentemente, en las _Ilustraciones_, en los grabados mitológicos del comedor, en los escaparates de las tiendas, sucedía que una línea gallarda, un contorno armonioso y elegante, cautivaba mis miradas precozmente artísticas; pero la miniatura encontrada en el cajón de mi tía, aparte de su gran gentileza, se me figuraba como animada de sutil aura vital; advertíase en ella que no era el capricho de un pintor, sino imagen de persona real, efectiva, de carne y hueso. El rico y jugoso tono del empaste, hacía adivinar, bajo la nacarada epidermis, la sangre tibia; los labios se desviaban para lucir el esmalte de los dientes; y, completando la ilusión, corría alrededor del marco una orla de cabellos naturales, castaños, ondeados y sedosos, que habían crecido en las sienes del original. Lo dicho: aquello, más que copia, era reflejo de persona viva, de la cual sólo me separaba un muro de vidrio..... Puse la mano en él, lo calenté con mi aliento, y se me ocurrió que el calor de la misteriosa deidad se comunicaba á mis labios y circulaba por mis venas. Estando en esto, sentí pisadas en el corredor. Era mi tía que regresaba de sus rezos. Oí su tos asmática y el arrastrar de sus pies gotosos. Tuve tiempo no más que de dejar la miniatura en el cajón, cerrarlo, y arrimarme á la vidriera, adoptando una actitud indiferente y nada sospechosa.\"},{\"heading\":false,\"text\":\"Entró mi tía sonándose recio, porque el frío de la iglesia le había encrudecido el catarro ya crónico. Al verme se animaron sus ribeteados ojillos, y, dándome un amistoso bofetoncito con la seca palma, me preguntó si le había revuelto los cajones, según costumbre.\"},{\"heading\":false,\"text\":\"Después, sonriéndose con picardía:\"},{\"heading\":false,\"text\":\"--Aguarda, aguarda--añadió--voy á darte algo, que te chuparás los dedos.\"},{\"heading\":false,\"text\":\"Y sacó de su vasta faltriquera un cucurucho, y del cucurucho tres ó cuatro bolitas de goma adheridas entre sí, como aplastadas, que me infundieron asco.\"},{\"heading\":false,\"text\":\"La estampa de mi tía no convidaba á que uno abriese la boca y se zampase el confite: muchos años, la dentadura traspillada, los ojos enternecidos más de lo justo, unos asomos de bigote ó cerdas sobre la hundida boca, la raya de tres dedos de ancho, unas canas sucias revoloteando sobre las sienes amarillas, un pescuezo flácido y lívido como el moco del pavo cuando está de buen humor... Vamos, que yo no tomaba las bolitas, ¡ea! Un sentimiento de indignación: una protesta varonil se alzó en mí, y declaré con energía:\"},{\"heading\":false,\"text\":\"--No quiero, no quiero.\"},{\"heading\":false,\"text\":\"--¿No quieres? ¡Gran milagro! ¡Tú que eres más goloso que la gata!\"},{\"heading\":false,\"text\":\"--Ya no soy ningún chiquillo--exclamé creciéndome, empinándome en la punta de los pies--y no quiero dulces.\"},{\"heading\":false,\"text\":\"La tía me miró entre bondadosa é irónica, y al fin, cediendo á la gracia que le hice, soltó el trapo, con lo cual se desfiguró y puso patente la espantable anatomía de sus quijadas. Reíase de tan buena gana, que se besaban barba y nariz, ocultando los labios, y se le señalaban dos arrugas, ó mejor, dos zanjas hondas, y más de una docena de pliegues en mejillas y párpados; al mismo tiempo, la cabeza y el vientre se le columpiaban con las sacudidas de la risa, hasta que al fin vino la tos á interrumpir las carcajadas, y entre risas y tos, involuntariamente, la vieja me regó la cara con un rocío de saliva... Humillado y lleno de repugnancia, huí á escape y no paré hasta el cuarto de mi madre, donde me lavé con agua y jabón, y me dí á pensar en la dama del retrato.\"},{\"heading\":false,\"text\":\"Y desde aquel punto y hora ya no acerté á separar mi pensamiento de ella. Salir la tía y escurrirme yo hacia su aposento, entreabrir el cajón, sacar la miniatura y embobarme contemplándola, todo era uno. A fuerza de mirarla, figurábaseme que sus ojos entornados, al través de la voluptuosa penumbra de las pestañas, se fijaban en los míos, y que su blanco pecho respiraba afanosamente. Me llegó á dar vergüenza besarla, imaginando que se enojaba de mi osadía, y sólo la apretaba contra el corazón, ó arrimaba á ella el rostro. Todas mis acciones y pensamientos se referían á la dama; tenía con ella extraños refinamientos y delicadezas nimias. Antes de entrar en el cuarto de mi tía y abrir el codiciado cajón, me lavaba, me peinaba, me componía, como ví después que suele hacerse para acudir á las citas amorosas.\"},{\"heading\":false,\"text\":\"Me sucedía á menudo encontrar en la calle á otros niños de mi edad, muy armados ya de su cacho de novia, que ufanos me enseñaban cartitas, retratos y flores, preguntándome si yo no escogería también _mi niña_ con quien cartearme. Un sentimiento de pudor inexplicable me ataba la lengua, y sólo les contestaba con enigmática y orgullosa sonrisa. Cuando me pedían parecer acerca de la belleza de sus damiselillas, me encogía de hombros y las calificaba desdeñosamente de _feas_ y _fachas_. Ocurrió cierto domingo que fuí á jugar á casa de unas primitas mías, muy graciosas en verdad, y que la mayor no llegaba á los quince. Estábamos muy entretenidos en ver un estereóscopo, y de pronto una de las chiquillas, la menor, doce primaveras á lo sumo, disimuladamente me cogió la mano, y conmovidísima, colorada como una brasa, me dijo al oído:\"},{\"heading\":false,\"text\":\"--Toma.\"},{\"heading\":false,\"text\":\"Al propio tiempo sentí en la palma de la mano una cosa blanda y fresca, y ví que era un capullo de rosa, con su verde follaje. La chiquilla se apartaba sonriendo y echándome una mirada de soslayo; pero yo, con un puritanismo digno del casto José, grité á mi vez:\"},{\"heading\":false,\"text\":\"--¡Toma!\"},{\"heading\":false,\"text\":\"Y le arrojé el capullo á la nariz, desaire que la tuvo toda la tarde llorosa y de monos conmigo, y que aún á estas fechas, que se ha casado y tiene tres hijos, no me ha perdonado probablemente.\"},{\"heading\":false,\"text\":\"Siéndome cortas para admirar el mágico retrato las dos ó tres horas que entre mañana y tarde se pasaba mi tía en la iglesia, me resolví por fin á guardarme la miniatura en el bolsillo, y anduve todo el día escondiéndome de la gente lo mismo que si hubiese cometido un crimen. Se me antojaba que el retrato, desde el fondo de su cárcel de tela, veía todas mis acciones, y llegué al ridículo extremo de que si quería rascarme una pulga, atarme un calcetín ó cualquiera otra cosa menos conforme con el idealismo de mi amor purísimo, sacaba primero la miniatura, la depositaba en sitio seguro y después me juzgaba libre de hacer lo que más me conviniese. En fin, desde que hube consumado el robo, no cabía en mí; de noche lo escondía bajo la almohada y me dormía en actitud de defenderlo; el retrato quedaba vuelto hacia la pared, yo hacia la parte de afuera, y despertaba mil veces con temor de que viniesen á arrebatarme mi tesoro. Por fin lo saqué de debajo de la almohada y lo deslicé entre la camisa y la carne, sobre la tetilla izquierda, donde al día siguiente se podían ver impresos los cincelados adornos del marco.\"},{\"heading\":false,\"text\":\"El contacto de la cara miniatura me produjo sueños deliciosos. La dama del retrato, no en efigie, sino en su natural tamaño y proporciones, viva, airosa, afable, gallarda, venía hacia mí para conducirme á su palacio, en un carruaje de blandos almohadones. Con dulce autoridad me hacía sentar á sus pies en un cojín, y me pasaba la torneada mano por la cabeza, acariciándome la frente, los ojos y el revuelto pelo. Yo le leía en un gran misal, ó tocaba el laúd, y ella se dignaba sonreirse, agradeciéndome el placer que la causaban mis canciones y lecturas. En fin, las reminiscencias románticas me bullían en el cerebro, y ya era paje, ya trovador.\"},{\"heading\":false,\"text\":\"Con todas estas imaginaciones, el caso es que fuí adelgazando de un modo notable, y lo observaron con gran inquietud mis padres y mi tía.\"},{\"heading\":false,\"text\":\"--En esa difícil y crítica edad del desarrollo, todo es alarmante--dijo mi padre, que solía leer libros de medicina y estudiaba con recelo las ojeras obscuras, los ojos apagados, la boca contraída y pálida, y sobre todo, la completa falta de apetito que se apoderaba de mí.\"},{\"heading\":false,\"text\":\"--Juega, chiquillo; come, chiquillo--solían decirme.\"},{\"heading\":false,\"text\":\"Y yo les contestaba con abatimiento:\"},{\"heading\":false,\"text\":\"--No tengo ganas.\"},{\"heading\":false,\"text\":\"Empezaron á discurrirme distracciones; me ofrecieron llevarme al teatro; me suspendieron los estudios, y diéronme á beber leche recién ordeñada y espumosa. Después me echaron por el cogote y la espalda duchas de agua fría, para fortificar mis nervios; y noté que mi padre, en la mesa ó por las mañanas cuando iba á su alcoba á darle los buenos días, me miraba fijamente un rato y á veces sus manos se escurrían por mi espinazo abajo, palpando y tentando mis vértebras. Yo bajaba hipócritamente los ojos, resuelto á dejarme morir antes que confesar el delito. En librándome de la cariñosa fiscalización de la familia, ya estaba con mi dama del retrato. Por fin, para mejor acercarme á ella, acordé suprimir el frío cristal: vacilé al ir á ponerlo en obra; al cabo pudo más el amor que el vago miedo que semejante profanación me inspiraba, y con gran destreza logré arrancar el vidrio y dejar patente la plancha de marfil.\"},{\"heading\":false,\"text\":\"Al apoyar en la pintura mis labios y percibir la tenue fragancia de la orla de cabellos, se me figuró con más evidencia que era persona viviente la que estrechaban mis manos trémulas. Un desvanecimiento se apoderó de mí, y quedé en el sofá como privado de sentido, apretando la miniatura.\"},{\"heading\":false,\"text\":\"Cuando recobré el conocimiento ví á mi padre, á mi madre, á mi tía, todos inclinados hacia mí con sumo interés; leí en sus caras el asombro y el susto; mi padre me pulsaba, meneaba la cabeza y murmuraba:\"},{\"heading\":false,\"text\":\"--Este pulso parece un hilito, una cosa que se va.\"},{\"heading\":false,\"text\":\"Mi tía, con sus dedos ganchudos, se esforzaba en quitarme el retrato, y yo, maquinalmente, lo escondía y aseguraba mejor.\"},{\"heading\":false,\"text\":\"--Pero chiquillo... ¡suelta, que lo echas á perder!--exclamaba ella. ¿No ves que lo estás borrando? Si no te riño, hombre... yo te lo enseñaré cuantas veces quieras; pero no lo estropees; suelta, que le haces daño.\"},{\"heading\":false,\"text\":\"--Déjaselo--suplicaba mi madre--el niño está malito.\"},{\"heading\":false,\"text\":\"--¡Pues no faltaba más!--contestó la solterona.--¡Dejarlo! ¿Y quién hace otro como ese... ni quién me vuelve á mí á los tiempos aquéllos? ¡Hoy en día nadie pinta miniaturas... eso se acabó... y yo también me acabé y no soy lo que ahí aparece!\"},{\"heading\":false,\"text\":\"Mis ojos se dilataban de horror; mis manos aflojaban la pintura. No sé cómo pude articular:\"},{\"heading\":false,\"text\":\"--Usted... el retrato... es usted...\"},{\"heading\":false,\"text\":\"--¿No te parezco tan guapa, chiquillo? ¡Bah! veintitrés años son más bonitos que... que... que no sé cuántos, porque no llevo la cuenta; nadie ha de robármelos!\"},{\"heading\":false,\"text\":\"Doblé la cabeza, y acaso me desmayaría otra vez; lo cierto es que mi padre me llevó en brazos á la cama, y me hizo tragar unas cucharadas de Oporto.\"},{\"heading\":false,\"text\":\"Convalecí presto y no quise entrar más en el cuarto de mi tía.\"}]},{\"title\":\"La inspiración\",\"blocks\":[{\"heading\":false,\"text\":\"Temporada fatal estaba pasando el ilustre Fausto, el gran poeta. Por una serie de circunstancias engranadas con persistencia increíble, todo le salía mal, todo fallido, raquítico, como si en torno suyo se secasen los gérmenes y la tierra se esterilizase. Sin ser viejo de cuerpo, envejecía rápidamente su alma, deshojándose en triste otoñada sus amarillentas ilusiones. Lo que le abrumaba no era dolor, sino atonía de su ardorosa sensibilidad y de su imaginación fecunda.\"},{\"heading\":false,\"text\":\"Acababa de romper relaciones con una mujer á quien no amaba; aquello principió por una comedia sentimental, y duró entre una eternidad de tedio, el cansancio insufrible del actor que representa un papel antipático, que ya va olvidando de puro sabido, en un drama sin interés y sin literatura. Y, no obstante, cuando la mujer mirada con tanta indiferencia le suplantó descaradamente y le hizo blanco de acerbas pullas que se repetían en los salones, Fausto sintió una de esas amarguras secas, irritantes, que ulceran el alma, y quedó, sin querérselo confesar, descontento de sí, rebajado á sus propios ojos, saturado de un escepticismo vulgar y prosaico, embebido de la ingrata convicción de que su mente ya no volvería á crear obra de arte, ni su corazón á destilar sentimiento.\"},{\"heading\":false,\"text\":\"Sí; Fausto se imaginaba que no era poeta ya. Así como los místicos tienen horas en que la frialdad que advierten les induce á dudar de su propia fe, los artistas desfallecen en momentos dados, creyéndose impotentes, paralíticos, muertos. Recluído en su gabinete, Fausto llamaba á la musa; pero en vano brillaba la lámpara, ardía la chimenea, exhalaban perfume los jacintos y las violetas, susurraba la seda del cortinaje: la infiel no acudía á la cita, y Fausto, con la frente calenturienta apoyada en la palma de la mano--actitud familiar para todos los que han luchado á solas con el ángel rebelde--no sentía fluir ni una gota del manantial delicioso: solo veía rocas negras, áridos arenales caldeados por el sol del desierto.\"},{\"heading\":false,\"text\":\"En aquellos momentos de agonía, su conciencia le acusaba, diciéndole que la decadencia del artista procedía del indiferentismo del hombre; que la poesía no acude á los páramos, sino á los oasis, y que si no podía volver á amar, tampoco podría volver á aparear versos--como quien unce parejas de corzas blancas al mismo carro de oro.--Las mujeres que le habían burlado y abandonado eran, sin duda, indignas de su amor; pero tampoco él--Fausto, el poeta, el soñador, el ave--se había tomado el trabajo de quererlo inspirar, ni menos de sentirlo. El desierto no era el alma ajena, era su alma; quien sólo ofrece llanuras candentes y peñascales yermos, no extrañe que el viajero cansado no se siente á reposar, ni quiera dormir larga y dulce siesta, como la que se duerme á la sombra de las palmeras verdes, al lado del fresco pozo...\"},{\"heading\":false,\"text\":\"Paseábase Fausto una tarde de Septiembre, á pie y sin objeto, por una de las solitarias rondas madrileñas, y al borde de un solar cercado de tablas divisó grupos de gente que examinaba con muestras de vivísimo interés, algo caído en el suelo. Las cabezas se inclinaban, y del corro salían exclamaciones de lástima y admiración. Fausto iba á pasar sin hacer caso; pero una sensación indefinible de curiosidad cruel le empujó al remolino. Pensó que la realidad es madre de la poesía, y que á veces del incidente más vulgar salta la chispa generadora. No sin algún trabajo consiguió abrirse camino, y ya en primera fila, pudo ver lo que causaba el asombro de aquel gentío humilde.\"},{\"heading\":false,\"text\":\"Sobre la hierba enteca y mísera que á duras penas brotaba del terreno arcilloso, yacía tendida una mujer joven, de sorprendente belleza. La palidez de la muerte, y esa especie de misteriosa dignidad y calma que imprime á las facciones, la hacían semejante á perfectísimo busto de mármol, y el ligero vidriado de los árabes ojos no amenguaba su dulzura. El pelo, suelto, rodeaba como un cojín de terciopelo mate la faz, y la boca, entreabierta, dejaba ver los dientes de nácar entre los descoloridos y puros labios. No se distinguía herida alguna en el cuerpo de la joven, y sus ropas conservaban decente compostura. Estaba echada de lado. Una faja de lana unía su cintura á la de un mocetón feo y tosco, muerto también, de un balazo que, entrando por el oído, había roto el cráneo. Sin duda en la agonía de los dos enamorados la faja debió de aflojarse, pues la mujer aparecía algo vuelta hacia la derecha, y el mozo á la izquierda, como desviándose de su compañera en el morir.\"},{\"heading\":false,\"text\":\"Con mezcla de piedad y de enojo, los albañiles, las lavanderas y los guardias de orden público comentaban el trágico suceso.--Tratábase de un doble suicidio, concertado de antemano, y hasta anunciado por el bruto del mozo, en una taberna, la noche anterior.--La oposición de los padres de ella, las malas costumbres de él, y el haber caído soldado, eran la causa. Ella no podía resignarse á la separación: ella misma, la mujer apasionada, había lanzado la terrible idea, acogida con fruición estúpida por el hombre celoso y feroz: morir, irse abrazados á donde Dios dispusiese; no apartarse ya nunca; pese á quien pese, desposarse en el ataúd... Sin dilación adquirió el revólver, y después de una mañana que pasaron juntos almorzando en un ventorro, los dos amantes se habían recogido al extraviado solar, donde, arrollando primero la faja del mozo alrededor de ambas cinturas, ella había tendido con sublime confianza el seno izquierdo, sin que, ni al sentir sobre el corazón el cañón del arma, se borrase de sus labios aquella sonrisa que aún conservaba fija en la boca, ¡aquella sonrisa que lucía los dientes de nácar entre los descoloridos y puros labios!\"},{\"heading\":false,\"text\":\"Por la noche, al retirarse Fausto á su casa, percibió una fiebre singular que conocía de antemano, pues solía experimentarla cada vez que se renovaba su ser con afectos nunca sentidos. Semejante excitación nerviosa señalaba, como la manecilla del reloj, las etapas sucesivas de su vida moral. La alegría extremada, la pena vehemente é inconsolable se anunciaban igualmente para Fausto con un desasosiego raro, una inquietud del corazón, que ya acelera sus latidos, ya se aquieta y desmaya hasta el síncope. Las horas nocturnas las contó desvelado en la cama: no podía apartar del pensamiento la imagen de la muchacha muerta; y mientras volvía á ver el solar, el corro de curiosos, el grupo trágico de los amantes que abrazados emprenden el viaje sin regreso, un bullir confuso de rimas, un surgir de estrofas incompletas, un rodar oceánico de versos sonoros ascendía de su corazón palpitante á su cerebro, y bajaba después, á manera de corriente impetuosa, á su mano impaciente ya de asir la pluma...\"},{\"heading\":false,\"text\":\"Lo más raro de todo era que Fausto, con la fantasía, enmendaba la plana al ciego Destino. La hermosa niña que había recibido en el seno izquierdo la bala, no estaba enamorada del bárbaro y plebeyo borrachín, del perdulario soez que descansaba á su lado, y que la amarró con la faja antes de darle muerte. No: el predilecto de aquella mujer que sabía querer y morir; el que antes de asesinarla había aspirado el aliento de su boca de virgen, era Fausto, el poeta; Fausto, que por fin encontraba su ideal, y que al encontrarlo prefería dejar la tierra, sellando con el sello de lo irreparable tan magnífica pasión.\"},{\"heading\":false,\"text\":\"¿Quién duda que sólo Fausto, capaz de comprender el valor de la acción sublime, merecía haberla inspirado? Corrigiendo la inepcia de los hechos, despreciando la vana apariencia de lo real, Fausto recogía para sí la ardiente flor amorosa, la flor de sangre sembrada en el erial de la ronda madrileña. Él era el compañero de aquella muerta que sonreía; él era quien había apoyado el revólver sobre el impávido seno de la heroina, no sólo tranquila ante la muerte, sino prendada de la muerte que une eternamente, sin separación posible, á los que se quisieron con delirio... Y la sugestión fue tan fuerte, que Fausto arrojó las sábanas, encendió luz y empezó á emborronar papel...\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"Tal fué el origen del poema _Juntos_, el mejor timbre de gloria de Fausto, lo que consagrará ante la posteridad su nombre, porque _Juntos_ es (lo afirma la crítica) una maravilla de sentimiento verdadero, y se comprende que está escrito con lágrimas vivas del poeta, que corresponde á penas y goces no fingidos,--á algo que no se inventa, porque no puede inventarse.\"}]},{\"title\":\"Champagne\",\"blocks\":[{\"heading\":false,\"text\":\"Al destaparse la botella de dorado casco, se obscurecieron los ojos de la compañera momentánea de Raimundo Valdés, y aquella sombra de dolor ó de recuerdo despertó la curiosidad del joven, que se propuso inquirir por qué una hembra que hacía profesión de jovialidad se permitía demostrar sentimientos tristes, lujo reservado solamente á las mujeres honradas, dueñas y señoras de su espíritu y de su corazón.\"},{\"heading\":false,\"text\":\"Solicitó una confidencia y, sin duda, la _prógima_ se encontraba en uno de esos instantes en que se necesita expansión, y se le dice al primero que llega lo que más hondamente puede afectarnos, pues sin dificultades ni remilgos contestó, pasándose las manos por los ojos:\"},{\"heading\":false,\"text\":\"--Me conmueve siempre ver abrir una botella de Champagne, porque ese vino me costó muy caro... el día de mi boda.\"},{\"heading\":false,\"text\":\"--¿Pero tú te has casado alguna vez... ante un cura?--preguntó Raimundo con festiva insolencia.\"},{\"heading\":false,\"text\":\"--Ojalá no--repuso ella con el acento de la verdad, con franqueza impetuosa.--Por haberme casado ando como me veo.\"},{\"heading\":false,\"text\":\"--Vamos, ¿tu marido será algún tramposo, algún perdis?\"},{\"heading\":false,\"text\":\"--Nada de eso. Administra muy bien lo que tiene, y posee miles de duros... miles, sí, ó cientos de miles.\"},{\"heading\":false,\"text\":\"--Chica, ¡cuántos duros! En ese caso... ¿te daba mala vida? ¿Tenía líos? ¿Te pegaba?\"},{\"heading\":false,\"text\":\"--Ni me dió mala vida, ni me pegó, ni tuvo líos, que yo sepa... ¡Después sí que me han pegado! Lo que hay es que le faltó tiempo para darme vida mala ni buena, porque estuvimos juntos, ya casados, un par de horas nada más.\"},{\"heading\":false,\"text\":\"--¡Ah!--murmuró Valdés, presintiendo una aventura interesante.\"},{\"heading\":false,\"text\":\"--Verás lo que pasó, prenda. Mis padres fueron personas muy regulares, pero sin un céntimo. Papá tenía un empleíllo, y con el angustiado sueldo se las arreglaban. Murió mi madre; á mi padre le quitaron el destino... y como no podía mantenernos el pico á mi hermano y á mí, y era bastante guapo, se dejó camelar por una jamona muy rica, y se casó con ella en segundas. Al principio mi madrastra se portó... vamos, bien: no nos miraba á los hijastros con malos ojos. Pero así que yo fuí creciendo y haciéndome mujer, y que los hombres, dieron en decirme cosas en la calle, comprendí que en casa me cobraban ojeriza. Todo cuanto yo hacía era mal hecho, y tenía siempre detrás al juez y al alguacil... la madrastra. Mi padre se puso muy pensativo, y comprendí que le llegaba al alma que se me tratase mal. Y lo que resultó de estas trifulcas, fué que se echaron á buscarme marido para zafarse de mí. Por casualidad lo encontraron pronto, sujeto acomodado, cuarentón, formal, recomendable, seriote... En fin, mi mismo padre se dió por contento y convino en que era una excelente proporción la que se me presentaba. Así es que ellos en confianza trataron y arreglaron la boda, y un día, encontrándome yo bien descuidada... ¡á casarse! y no vale replicar.\"},{\"heading\":false,\"text\":\"--¿Y qué efecto te hizo la noticia? ¿Malo, eh?\"},{\"heading\":false,\"text\":\"--Malísimo... porque yo tenía la tontuna de estar enamorada hasta los tuétanos, como se enamora una chiquilla, pero chiquilla forrada de mujer... de _uno_ de infantería, un teniente pobre como las ratas... y se me había metido en la cabeza que aquel había de ser mi marido apenas saliese á capitán. Las súplicas de mi padre; los consejos de las amigas; las órdenes y hasta los pescozones de mi madrastra--que no me dejaba respirar--me aturdieron de tal manera, que no me atreví á resistir. Y vengan regalos, y desclávense cajones de vestidos enviados de Madrid, y cuélguese usted los faralaes blancos, y préndase el embelequito de la corona de azahar, y á la iglesia, y ahí te suelto la bendición, y en seguida gran comilona, los amigos de la familia y la parentela del novio que brindan y me ponen la cabeza como un bombo, á mí que más ganas tenía de lloriquear que de probar bocado...\"},{\"heading\":false,\"text\":\"--Hija, por ahora no encuentro mucho de particular en tu historia. Casarse así, rabiando y por máquina, es bastante frecuente.\"},{\"heading\":false,\"text\":\"--Aguarda, aguarda--advirtió amenazándome con la mano.--Ahora entra lo ridículo, la peripecia... Pues señor, yo en mi vida había probado el tal Champagne... Me sirvieron la primera copa para que contestase á los brindis, y después de vaciarla me pareció que me sentía con más ánimos, que se me aliviaban el malestar y la negra tristeza. Bebí la segunda, y el buen efecto aumentó. La alegría se me derramaba por el cuerpo... Entonces me deslicé á tomar tres, cuatro, cinco, quizás media docena...\"},{\"heading\":false,\"text\":\"Los convidados bromeaban celebrando la gracia de que bebiese así, y yo bebía buscando en la especie de vértigo que causa el Champagne un olvido completo de lo que había de suceder y de lo que me estaba sucediendo ya. Sin embargo, me contuve antes de llegar á trastornarme por completo, y sólo podían notar en la mesa que reía muy alto, que me relucían los ojos, y que estaba sofocadísima.\"},{\"heading\":false,\"text\":\"Nos esperaba un coche á mi marido y á mí, coche que nos había de llevar á una casa de campo de él, á pasar la primer semana después de la boda.--Chiquillo, no sé si fué el movimiento del coche ó si fué el aire libre, ó buenamente que estaba yo como una uva,--pero lo cierto es que apenas me ví sola con el tal hombre y él pretendió hacerme garatusas cariñosas, se me desató la lengua, se me arrebató la sangre, y le solté de pe á pa lo del teniente, y que sólo al teniente quería, y teniente va y teniente viene, y dale con si me han casado contra mi gusto, y toma conque ya me desquitaría y le mataría á palos... Barbaridades, cosas que inspira el vino á los que no acostumbran... Y mi esposo, más pálido que un muerto, mandó que volviese atrás el coche, y en el acto me devolvió á mi casa.--Es decir, esto me lo dijeron luego, porque yo, de puro borrachina... de nada me enteré.\"},{\"heading\":false,\"text\":\"--¿Y nunca más te quiso recibir tu marido?\"},{\"heading\":false,\"text\":\"--Nunca más. Parece que le espeté atrocidades tremendas. Ya ves; quien hablaba por mi boca era el maldito espumoso...\"},{\"heading\":false,\"text\":\"--¿Y... en tu casa? ¿Te admitieron contentos?\"},{\"heading\":false,\"text\":\"--¡Quiá! Mi madrastra me insultaba horriblemente, y mi padre lloraba por los rincones... Preferí tomar la puerta, ¡qué caramba!\"},{\"heading\":false,\"text\":\"--¿Y... el teniente?\"},{\"heading\":false,\"text\":\"--¡Sí, busca teniente! Al saber mi boda se había echado otra novia, y se casó con ella poco después.\"},{\"heading\":false,\"text\":\"--¿Sabes que has tenido mala sombra?\"},{\"heading\":false,\"text\":\"--Mala por cierto... Pero creo que si todas las mujeres hablasen lo que piensan, como hice yo por culpa del Champagne, más de cuatro y más de ocho se verían peor que esta individua.\"},{\"heading\":false,\"text\":\"--¿Y no te da tu marido alimentos? La ley le obliga.\"},{\"heading\":false,\"text\":\"--¡Bah! Eso ya me lo avisó un abogadito que tuve... ¡El diablo que se meta á pleitear! ¿Voy á pedirle que me mantenga á ese, después del desengaño que le costé? Anda, ponme más Champagne... Ahora ya puedo beber lo que quiera. No se me escapará ningún secreto.\"}]},{\"title\":\"Sor Aparición\",\"blocks\":[{\"heading\":false,\"text\":\"En el convento de las Clarisas de S..., al través de la doble reja baja, ví á una monja postrada, adorando. Estaba de frente al altar mayor, pero tenía el rostro pegado al suelo, los brazos extendidos en cruz, y guardaba inmovilidad absoluta. No parecía más viva que los yacentes bultos de una reina y una infanta, cuyos mausoleos de alabastro adornaban el coro. De pronto la monja prosternada se incorporó, sin duda para respirar, y pude distinguir sus facciones. Se notaba que había debido de ser muy hermosa en sus juventudes, como se conoce que unos paredones derruídos fueron palacios espléndidos. Lo mismo podría contar la monja ochenta años que noventa: su cara, de una amarillez sepulcral, su temblorosa cabeza, su boca consumida, sus cejas blancas, revelaban ese grado sumo de la senectud en que hasta es insensible el paso del tiempo.\"},{\"heading\":false,\"text\":\"Lo singular de aquella cara espectral, que ya pertenecía al otro mundo, eran los ojos. Desafiando á la edad, conservaban, por caso extraño, su fuego, su intenso negror, y una violenta expresión apasionada y dramática. La mirada de tales ojos no podía olvidarse nunca. Semejantes ojos volcánicos serían inexplicables en monja que hubiese ingresado en el claustro ofreciendo á Dios un corazón inocente; delataban un pasado borrascoso; despedían la luz siniestra de algún terrible recuerdo. Sentí ardiente curiosidad, sin esperar que la suerte me deparase á alguien conocedor del secreto de la religiosa.\"},{\"heading\":false,\"text\":\"Sirvióme la casualidad á medida del deseo. La misma noche, en la mesa redonda de la posada, trabé conversación con un caballero machucho, muy comunicativo y más que medianamente perspicaz, de esos que gozan cuando enteran á un forastero. Halagado por mi interés, me abrió de par en par el archivo de su feliz memoria. Apenas nombré el convento de las Claras é indiqué la especial impresión que me causaba el mirar de la monja, mi guía exclamó:\"},{\"heading\":false,\"text\":\"--¡Ah! ¡Sor Aparición! Ya lo creo, ya lo creo... Tiene un _no sé qué_ en los ojos... Lleva escrita allí su historia. Donde usted la ve, los dos surcos de las mejillas, que de cerca parecen canales, se los han abierto las lágrimas. ¡Llorar más de cuarenta años! Ya corre agua salada en tantos días... El caso es que el agua no le ha apagado las brasas de la mirada... ¡Pobre Sor Aparición! Le puedo descubrir á usted el _quid_ de su vida mejor que nadie, porque mi padre la conoció moza, y hasta creo que la hizo unas miajas el amor... ¡Es que era una deidad!\"},{\"heading\":false,\"text\":\"Sor Aparición se llamó en el siglo Irene. Sus padres eran gente hidalga, ricachos de pueblo; tuvieron varios retoños, pero los perdieron, y concentraron en Irene el cariño y el mimo de hija única. El pueblo donde nació se llama A... Y el destino, que con las sábanas de la cuna empieza á tejer la cuerda que ha de ahorcarnos, hizo que en ese mismo pueblo viese la luz, algunos años antes que Irene, el famoso poeta...\"},{\"heading\":false,\"text\":\"Lancé una exclamación y pronuncié, adelantándome al narrador, el glorioso nombre del autor del _Arcángel maldito_,--tal vez el más genuino representante de la fiebre romántica;--nombre que lleva en sus sílabas un eco de arrogancia desdeñosa, de mofador desdén, de acerba ironía y de nostalgia desesperada y blasfemadora. Aquel nombre y el mirar de la religiosa se confundieron en mi imaginación, sin que todavía el uno me diese la clave del otro, pero anunciando ya, al aparecer unidos, un drama del corazón de esos que chorrean viva sangre.\"},{\"heading\":false,\"text\":\"--El mismo--repitió mi interlocutor--el célebre Juan de Camargo, orgullo del pueblecito de A..., que ni tiene aguas minerales, ni santo milagroso, ni catedral, ni lápidas romanas, ni nada notable que enseñar á los que lo visitan, pero repite envanecido: «En esta casa de la plaza nació Camargo.»\"},{\"heading\":false,\"text\":\"--Vamos--interrumpí--ya comprendo; Sor Aparición... digo, Irene, se enamoró de Camargo, él la desdeñó, y ella, para olvidar, entró en el claustro...\"},{\"heading\":false,\"text\":\"--¡Chsss!--exclamó el narrador sonriendo;--¡espere usted, espere usted, que si no fuese más! De eso se ve todos los días; ni valdría la pena de contarlo. No; el caso de Sor Aparición tiene miga. Paciencia, que ya llegaremos al fin.\"},{\"heading\":false,\"text\":\"De niña, Irene había visto mil veces á Juan de Camargo, sin hablarle nunca, porque él era ya mozo y muy huraño y retraído: ni con los demás chicos del pueblo se juntaba. Al romper Irene su capullo, Camargo, huérfano, ya estudiaba leyes en Salamanca, y sólo venía á casa de su tutor durante las vacaciones. Un verano, al entrar en A..., el estudiante levantó por casualidad los ojos hacia la ventana de Irene y reparó en la muchacha, que fijaba en él los suyos... unos ojos de date preso, dos soles negros, porque ya ve usted lo que son todavía ahora. Refrenó Camargo el caballejo de alquiler, para recrearse en aquella soberana hermosura; Irene era un asombro de guapa. Pero la muchacha, encendida como una amapola, se quitó de la ventana cerrándola de golpe. Aquella misma noche, Camargo, que ya empezaba á publicar versos en periodiquillos, escribió unos, preciosos, pintando el efecto que le había producido la vista de Irene en el momento de llegar á su pueblo... Y envolviendo en los versos una piedra, al anochecer la disparó contra la ventana de Irene. Rompióse el vidrio, y la muchacha recogió el papel y leyó los versos, no una vez, ciento, mil: los bebió, se empapó en ellos. Sin embargo, aquellos versos, que no figuran en la colección de las poesías de Camargo, no eran declaraciones amorosas, sino algo raro, mezcla de queja é imprecación. El poeta se dolía de que la pureza y la hermosura de la niña de la ventana no se hubiesen hecho para él, que era un réprobo. Si él se acercase, marchitaría aquella azucena... Después del episodio de los versos, Camargo no dió señales de acordarse de que existía Irene en el mundo, y en Octubre se dirigió á Madrid. Empezaba el período agitado de su vida, las aventuras políticas y la actividad literaria.\"},{\"heading\":false,\"text\":\"Desde que Camargo se marchó, Irene se puso triste, llegando á enfermar de pasión de ánimo. Sus padres intentaron distraerla; la llevaron algún tiempo á Badajoz, la hicieron conocer jóvenes, asistir á bailes; tuvo adoradores, oyó lisonjas... pero no mejoró de humor ni de salud.\"},{\"heading\":false,\"text\":\"No podía pensar sino en Camargo, á quien era aplicable lo que dice Byron de _Lara_: que los que le veían no le veían en vano; que su recuerdo acudía siempre á la memoria, pues hombres tales lanzan un reto al desdén y al olvido. No creía la misma Irene hallarse enamorada; juzgábase sólo víctima de un maleficio, emanado de aquellos versos tan sombríos, tan extraños. Lo cierto es que Irene tenía eso que ahora llaman obsesión, y á todas horas veía _aparecerse_ á Camargo, pálido, serio, el rizado pelo sombreando la pensativa frente... Los padres de Irene, al observar que su hija se moría minada por un padecimiento misterioso, decidieron llevarla á la corte, donde hay grandes médicos para consultar y también grandes distracciones.\"},{\"heading\":false,\"text\":\"Cuando Irene llegó á Madrid, era célebre Camargo. Sus versos fogosos, altaneros, de sentimiento fuerte y nervioso, hacían escuela; sus aventuras y genialidades se comentaban. Asociada con él una pandilla de perdidos, de bohemios desenfadados é ingeniosos, cada noche inventaban nuevas diabluras, y ya turbaban el sueño de los honrados vecinos, ya realizaban las orgiásticas proezas á que aluden ciertas poesías blasfemas y obscenas, que algunos críticos aseguran que no son de Camargo en realidad. Con las borracheras y el libertinaje alternaban las sesiones en las logias masónicas y en los comités; Camargo se preparaba ya la senda de la emigración. No estaba enterada de todo esto la provinciana y cándida familia de Irene; y como se encontrasen en la calle al poeta, le saludaron alegres, que al fin era _de allá_.\"},{\"heading\":false,\"text\":\"Camargo, sorprendido otra vez de la hermosura de la joven; notando que al verle se teñían de púrpura las descoloridas mejillas de una niña tan preciosa, les acompañó, y prometió visitar á sus convecinos. Quedaron lisonjeados los pobres lugareños, y creció su satisfacción al notar que de allí á pocos días, habiendo cumplido Camargo su promesa, Irene revivía. Desconocedores de la crónica, les parecía Camargo un yerno posible, y consintieron que menudease las visitas.\"},{\"heading\":false,\"text\":\"Veo en su cara de usted que cree adivinar el desenlace... ¡No lo adivina! Irene, fascinada, trastornada como si hubiese bebido zumo de yerbas, tardó sin embargo seis meses en acceder á una entrevista á solas, en la misma casa de Camargo. La honesta resistencia de la niña fué causa de que los perdidos amigotes del poeta se burlasen de él, y el orgullo, que es la raíz venenosa de ciertos romanticismos, como el de Byron y el de Camargo, inspiró á éste una apuesta, un desquite satánico, infernal. Pidió, rogó, se alejó, volvió, dió celos, fingió planes de suicidio, é hizo tanto, que Irene, atropellando por todo, consintió en acudir á la peligrosa cita. Gracias á un milagro de valor y decoro, salió de ella pura y sin mancha, y Camargo sufrió una chacota que le enloqueció de despecho.\"},{\"heading\":false,\"text\":\"A la segunda cita, se agotaron las fuerzas de Irene, se obscureció su razón y fué vencida. Y cuando, confusa y trémula, yacía, cerrando los párpados, en brazos del infame, éste exhaló una estrepitosa carcajada, descorrió unas cortinas, é Irene vió que la devoraban los impuros ojos de ocho ó diez hombres jóvenes, que también reían y palmoteaban irónicamente...\"},{\"heading\":false,\"text\":\"Irene se incorporó, dió un salto, y sin cubrirse, con el pelo suelto y los hombros desnudos, se lanzó á la escalera y á la calle. Llegó á su morada seguida de una turba de pilluelos que la arrojaban barro y piedras. Jamás consintió decir de dónde venía, ni qué le había sucedido.--Mi padre lo averiguó, porque, casualmente, era amigo de uno de los de la apuesta de Camargo.--Irene sufrió una fiebre de septenarios en que estuvo desahuciada; así que convaleció, entró en este convento--lo más lejos posible de A...--Su penitencia ha espantado á las monjas: ayunos increíbles; mezclar el pan con ceniza; pasarse tres días sin beber; las noches de invierno descalza y de rodillas, en oración: disciplinarse, llevar una argolla al cuello, una corona de espinas bajo la toca, un rallo á la cintura...\"},{\"heading\":false,\"text\":\"Lo que más edificó á sus compañeras, que la tienen por santa, fué el continuo llorar. Cuentan--pero serán consejas--que una vez llenó de llanto la escudilla del agua. ¡Y quién le dice á usted que de repente se le quedan los ojos secos, sin una lágrima, y brillando de ese modo que ha notado usted!--Esto aconteció más de veinte años hace; las gentes piadosas creen que fué la señal del perdón de Dios. No obstante, Sor Aparición, sin duda, no se cree perdonada, porque, hecha una momia, sigue ayunando y postrándose y usando el cilicio de cerda...\"},{\"heading\":false,\"text\":\"--Es que hará penitencia por dos--respondí, admirada de que en este punto fallase la penetración de mi cronista.--¿Piensa usted que Sor Aparición no se acuerda del alma infeliz de Camargo?\"}]},{\"title\":\"¿Justicia?\",\"blocks\":[{\"heading\":false,\"text\":\"Sin ser filósofo ni sabio; con sólo la viveza del natural discurso, Pablo Roldán había llegado á formarse en muchas cuestiones un criterio extraño é independiente; no digo que superior, porque no pienso que lo sea,--pero al menos distinto del de la generalidad de los mortales.--En todo tiempo habrán existido estas divergencias entre el modo de pensar colectivo y el de algunos individuos innovadores ó retrógrados con exceso, pues tanto nos separamos de nuestra época por adelantarnos como por rezagarnos.\"},{\"heading\":false,\"text\":\"Uno de los problemas que Pablo Roldán consideraba de modo original y hasta chocante, era el de la infidelidad de la esposa. Es de advertir que Pablo Roldán estaba casado, y con dama tan principal, moza, hermosa y elegante, que se llevaba los ojos y quizás el corazón de cuantos la veían. Un tesoro así debiera hacer vigilante á su guardador; pero Pablo Roldán no sólo alardeaba de confianza ciega, rayana en descuido, sinó que declaraba que la vigilancia le parecía inútil, porque no juzgándose _propietario_ de su bella mitad, no se creía en el caso de guardarla como se guarda una viña, un huerto ó una caja de valores. Una mujer--decía sonriendo Pablo--se diferencia de una fruta y de un rollo de billetes de Banco, en que tiene conciencia y lengua. A nadie se le ha ocurrido hacer responsable á la pavía si un ratero la hurta y se la come. La mujer es capaz y responsable--y vean cómo realmente, pareciendo tan bonachón, soy más rígido que ustedes los celosos extremeños.--La mujer es responsable, culpable... entendámonos: cuando engaña. Claro que la mía, moralmente, no conseguirá nunca engañarme, porque yo sería la flor de los imbéciles si al acercarme á ella no comprendiese la impresión que la produzco; si me ama, ó la soy indiferente, ó no me puede sufrir. Del estado de su alma no necesitará mi esposa darme cuenta: yo adivinaré... ¡No faltaría más! Y al adivinar--tan cierto como me llamo Pablo Roldán y me tengo por hombre de honor--consideraré roto el lazo que la sujeta á mí, y no haré al autor de las almas la ofensa de violentar un alma esencialmente igual á la mía... Desde el día en que no me quiera, mi mujer será _interiormente_ libre como el aire. Sin embargo--pues el nudo legal es indisoluble y la equivocación mutua,--le advertiré que queda obligada á salvar las apariencias, á tener muy en cuenta la exterioridad, á no hacerme blanco de la burla; y yo, por mi parte, me creeré en el deber de seguir amparándola, de escudarla contra el menosprecio. ¡Bah! Amigo mío, esto es hablar por hablar; Felicia parece que aun no me ha perdido el cariño... Son teorías, y ya sabe usted que, llegado el caso práctico, raro es el hombre que las aplica rigurosamente.\"},{\"heading\":false,\"text\":\"No platicaba así Roldán sino con los pocos que tenía por verdaderos amigos y hombres de corazón y de entendimiento; con los demás creía él que no se debían conferir puntos tan delicados. Al parecer, el sistema amplio y generoso de Pablo daba resultados excelentes: el matrimonio vivía unido, respetado, contento. No obstante, yo que lo observaba sin cesar, atraído por aquel experimento curioso, empecé á notar, transcurridos algunos años--poco después de que la mujer de Pablo entró en el período de esplendor de la belleza femenina, los treinta--ciertos síntomas que me inquietaron un poco. Pablo andaba á veces triste y meditabundo; tenía días de murria, momentos de distracción y ausencia, aunque se rehacía luego y volvía á su acostumbrada ecuanimidad. En cambio, su mujer demostraba una alegría y animación exageradas y febriles, y se entregaba más que nunca al mundo y á las fiestas. Seguían yendo siempre juntos; las buenas costumbres conyugales no se habían alterado en lo más mínimo; pero yo, que tampoco soy la flor de los imbéciles, no podía dudar que existía en aquella pareja antes venturosa algún desajuste, alguna grieta oculta, algo que alteraba su contextura íntima. Para la gente, el matrimonio Roldán se mantenía inalterable; para mí, el matrimonio Roldán se había disuelto.\"},{\"heading\":false,\"text\":\"Por aquel entonces se anunció la boda de cierta opulenta señorita, y los padres convidaron á sus relaciones á examinar las _vistas_ y ricos regalos que formaban la canastilla de la novia. Encontrábame entretenido en admirar un largo hilo de perlas, obsequio del novio, cuando ví entrar á Pablo Roldán y á su mujer. Acercáronse á la mesa cargada de preseas magníficas, y la gente agolpada les abrió paso difícilmente. La señora de Roldán se extasió con el hilo de perlas: ¡qué iguales! ¡qué gruesas! ¡qué oriente tan nacarado y tan puro! Mientras expresaba su admiración hacia la joya, noté...--¿quién explicaría el por qué me fijaba ansiosamente en los movimientos de la mujer de Pablo?--noté, digo, que se deslizaba hacia ella, como para compartir su admiración, Dámaso Vargas Padilla, mozo más conocido por calaveradas y despilfarros que por obras de caridad, y hube de ver que sobre el color avellana del guante de Suecia de la dama relucía un objetito blanco, inmediatamente trasladado á los dominios de un guante rojizo del Tirol... Y sentí el mismo estremecimiento que si de cosa propia se tratase, al cerciorarme de que Pablo Roldán, demudado y con el rostro color de muerto, había visto como yo, y sorprendido, como yo, el paso del billete de manos de su mujer á manos de Vargas...\"},{\"heading\":false,\"text\":\"Temí que se arrojase sobre los que así le escarnecían en público. No se arrojó; no dió la más leve muestra de cólera ó pesadumbre. Al contrario, siguió curioseando y alabando las galas bonitas, revolviendo y mezclando los objetos colocados más cerca, deteniéndose y obligando á su mujer á que se detuviese y reparase el mérito de cada uno. Tan despacio procedió á este examen, que la gente fué retirándose poco á poco, y ya no quedamos en el gabinete sino media docena de personas. Y cuando me disponía á cruzar la puerta, en una ojeada que lancé al descuido, volví á ver algo que me hizo el efecto de la espantable cabeza de Medusa, paralizándome de horror, dejándome sin voz, sin discurso, sin aliento... Pablo Roldán había deslizado rápidamente en el bolsillo de su chaleco el hilo de perlas, y salía tranquilo, alta la frente, bromeando con su esposa, elogiando un cuadro, en el cual logró concentrar toda la atención de los circunstantes.\"},{\"heading\":false,\"text\":\"Desde el día siguiente empezó á murmurarse sobre el tema del robo, primero en voz baja, después con escandalosa publicidad. Hubo periódicos que lo insinuaron; el _tole tole_ fué horrible. Las muchas personas distinguidas que habían admirado las galas de la novia clamaban al cielo y mostraban, naturalmente, deseo furioso de que se descubriese al ladrón. Se calumnió á varios inocentes, y el rencor buscó medios de herir, devolviendo la flecha. Todos respiraron por fin al saber que el juez, avisado por una delación anónima, acababa de registrar la casa de Pablo, encontrando el hilo de perlas en un armario del tocador de la señora de Roldán...\"},{\"heading\":false,\"text\":\"Sólo yo comprendí la tremenda venganza. Sólo yo logré penetrar el siniestro enigma, sin clave para la propia señora, que no anda lejos de expiar con años de presidio el delito que no cometió. Y un día que encontré á Pablo y le abrí mi alma y le confesé mis perplejidades, mis dudas respecto á si debía ó no revelar la verdad, puesto que la conocía, Pablo me respondió con lágrimas de rabia al borde de los lagrimales:\"},{\"heading\":false,\"text\":\"--No intervengas; ¡paso á la justicia, paso!... Dejó de amarme, y no me creí con derecho ni á la queja; quiso á otro, y únicamente la rogué que no me entregase á la risa del mundo... ¡Ya sabes cómo atendió á mi ruego... ya lo sabes! Antes que consiguiese ridiculizarme, la infamé... ¡Los medios fueron malos, pero... se lo tenía advertido! Si tú eres de los que creen que la venganza pertenece á Dios, apártate de mí, porque no nos entendemos. Amor, odio y venganza... ¿dónde habrá nada más humano?\"},{\"heading\":false,\"text\":\"Me desvié de Pablo Roldán y no quiero volver á verle. No sé juzgarle; tan pronto le compadezco, como me inspira horror.\"}]},{\"title\":\"Más allá\",\"blocks\":[{\"heading\":false,\"text\":\"Era un balneario elegante; pero no de esos en que la gente rica, antojadiza y maniática cuida imaginarias dolencias, sino de los que reciben todos los años, desde principios de Junio, retahilas de verdaderos enfermos pálidos y débiles, y donde, á la hora de la consulta, se ven á la puerta del consultorio gestos ansiosos, enrojecidos párpados, y señoras de pelo gris, que dan el brazo y sostienen á señoritas demacradas, de trabajoso andar. Para decirlo pronto: aquellas aguas convenían á los tísicos.\"},{\"heading\":false,\"text\":\"Pared por medio estaban los dos. _Ella_, la niña apasionada y romántica, la interesante enfermita que--indiferente á la muerte como aniquilamiento del ser físico--no la aceptaba como abdicación de la gracia y la belleza; que, á su paso por los salones, cuando los cruzaba con porte airoso de ninfa joven, solía levantar un rumor halagüeño, un murmurio pérfido de mar que acaricia y devora; y defendiendo hasta el último instante su corona de encantos, que iba á marchitarse en el sepulcro, se rodeaba de flores y perfumes, sonreía dulcemente, envolvía su cuerpo enflaquecido en finos crespones de China y delicados encajes, y calzaba su pie menudo de blanco tafilete, con igual coquetería que si fuese á dirigir alegre y raudo cotillón.--_El_, el mozo galán que había derrochado sus fuerzas vitales con prodigalidad regia, despreciando las advertencias de la tierna é inquieta madre y la indicación hereditaria de los dos tíos maternos arrebatados en lo mejor de la edad--hasta que un día sintió á su vez el golpe sordo que le hería el pecho y le disolvía lentamente el pulmón, avivando, en vez de extinguirlo, el incendio que siempre había consumido su alma.\"},{\"heading\":false,\"text\":\"Pared por medio estaban los dos, sin conocerse ni saber que existían, y sin embargo, el mal que los llevaba á la tumba tenía idéntico origen; el mismo anhelo insaciable había atacado en ellos las fuentes de la vida. Ella y él, fascinados por el propio sueño, hicieron de la pasión único ideal de la existencia, y aspiraron á un amor grande, profundamente estético, ardiente y resuelto como si fuese criminal, noble y altivo como si fuese legítimo, puro á fuerza de intensidad, abrasador á fuerza de pureza. Y como quien busca ave fénix ó talismán poderoso, habían buscado ambos la encantada isla de sus ensueños, ella entre los sosos incidentes del diario _flirt_, él entre los episodios no menos vulgares de la calvatronería orgiástica; hasta que una serie de decepciones tristes, cómicas ó indignas les arruinó la salud, dejando intacto el tesoro de ilusiones y aspiraciones nunca satisfechas, la sed de amar inextinta, más bien exacerbada por la calentura y el alta tensión nerviosa, fruto del padecimiento.\"},{\"heading\":false,\"text\":\"¡Quién les dijera que allí, detrás del tabique en cuyo papel de caprichosos dibujos hallaban maquinal entretenimiento los aburridos ojos, se encontraba lo que habían buscado en balde tanto tiempo, lo que necesitaban para asirse otra vez á la existencia!\"},{\"heading\":false,\"text\":\"Porque ya ni él ni ella podían salir del cuarto, ni bajar las escaleras, ni comer en el comedor. Postrados y exánimes, les traían el agua mineral en un vaso puesto boca abajo sobre un platillo; últimamente, hasta no se atrevieron á beber, y el médico, presintiendo fatal desenlace, advirtió que convendría atender al alma, señal casi siempre funestísima para el pobre del cuerpo.\"},{\"heading\":false,\"text\":\"El y ella se prepararon á recibir á Jesucristo con todo el agasajo que tal visita merece. No hubo fuerzas humanas que les impidiesen vestirse y engalanarse como para un sarao. Ella se lavó con esencias fragantes y jabones exquisitos, hizo peinar esmeradamente la negra mata de pelo, se puso traje de blanco gró, y con sonriente coquetería prendió en la mantilla sus agujas de turquesas; él atusó la bien recortada barba, eligió la camisa más bruñida y tersa, el chaleco de mejor caída, y de frac y corbata blanca, esperó á su Dios. Y él y ella, al sentir en los labios la sagrada partícula, gozaron un momento de emoción deliciosa: les pareció que la efusión esperada en vano, el supremo arrobamiento del éxtasis, vendría después de despojada la vestidura carnal, cuando el alma, libre y dichosa, volase al seno de su Creador...\"},{\"heading\":false,\"text\":\"Así fué que tuvieron unas últimas horas edificantes, ejemplares, de un ardor místico sublime, que hacía derramar lágrimas á los que rodeaban el lecho. Sus palabras de esperanza sonaban conmovedoras y misteriosas, dichas desde el borde de la huesa. Hablaban del cielo, y diríase que al nombrarlo lo veían ya; de tal suerte se iluminaban sus ojos y resplandecía en sus rostros la beatitud y la fe que transfigura.\"},{\"heading\":false,\"text\":\"A la misma hora fallecieron, y sus espíritus se encontraron en el camino del otro mundo, antes de tomar rumbos distintos, pues él se encaminaba al purgatorio en forma de llama rojiza, y ella al cielo, convertida en ligero fueguecillo azul. Entonces se vieron por primera vez, y sorprendidos, detuviéronse á contemplarse. Como á aquellas alturas todo se adivina, inmediatamente adivinaron de qué habían muerto y la semejanza de sus destinos durante la vida terrenal. Y así como comprendieron claramente que los dos habían muerto de plétora de pasión no satisfecha ni entendida, advirtieron también con asombro que él era el alma nacida para ella, y ella el corazón capaz de encerrar aquel amor infinito de que él se sentía minado y consumido, como el árbol que todo se derrite en gomas. Y lo mismo fué advertirlo, que juntarse impetuosamente los dos espíritus, mezclándose la llama rojiza con el fueguecillo azul tan estrechamente, que se hicieron una luz sola.\"},{\"heading\":false,\"text\":\"Y sucedió que, unidos ya, él no pudo entrar en el purgatorio por la parte que llevaba de cielo, y ella tampoco pudo ingresar en el cielo por la parte que llevaba de purgatorio. El, generoso, la propuso que se apartasen, yéndose ella á disfrutar las dichas del Empíreo; mas ella prefirió seguir unida á él, aun á costa de la eterna bienandanza; y desde entonces la luz anda errante, y los dos espíritus no hallan otro nido para sus amores póstumos, sino la extremidad del palo de algún buque, donde los marinos los confunden con el fuego de San Telmo.\"}]},{\"title\":\"La culpable\",\"blocks\":[{\"heading\":false,\"text\":\"Elisa fué una mujer desgraciadísima durante toda su vida conyugal, y murió, joven aún, minada por las penas. Es verdad que había cometido una falta muy grave, tan grave que para ella no hay perdón: escaparse con su marido antes de que éste lo fuese y pasar en su compañía veinticuatro horas de tren... Después, sucedió lo de costumbre: la recogió la autoridad, la depositaron en un convento, y á los quince días se casó, sin que sus padres asistiesen á la boda; actitud muy digna, en opinión de las personas sensatas.\"},{\"heading\":false,\"text\":\"Ellos no se habían opuesto de frente á las relaciones de Elisa con Adolfo: mas como quiera que no les agradaba pizca el aspirante, y creían conocerle y presentían su condición moral, suscitaron mil dificultades menudas y consiguieron dar largas al asunto y entretenerlo por espacio de cinco años. Consintieron, eso sí, que Adolfo _entrase en casa_, porque tenía poco de seductor y era hasta antipático, y esperaron que Elisa perdiese toda ilusión al verle de cerca. Sucedió lo contrario; en los interminables coloquios junto á la chimenea; en el diario tortoleo, el amante corazón de Elisa se dejó cautivar para siempre, y Adolfo aseguró la presa de la acaudalada muchacha. Después de meditadas y estratégicas maniobras por parte del novio, llegó el instante de la fuga, preliminar del casamiento.\"},{\"heading\":false,\"text\":\"La familia de Elisa tomó muy á pechos el escándalo, por lo mismo que eran gente conocida, bien relacionada, preciada de correcta, intransigente en cuestiones de moralidad exterior. Hubo en la casa uno de esos períodos de disgusto, cerrados, serios, hondos, en que hasta los criados andan mohinos; períodos que á las personas entradas en edad les cavan una cuarta de sepultura. Las dos hermanas de la fugitiva se avergonzaron y corrieron de suerte que en muchos meses no se atrevieron á salir á la calle. Una, en especial, se afectó tanto, que fué preciso sacarla de Madrid para que no se alterase su salud. La madre jamás pronunció el nombre de Elisa sin suspirar, como cuando se nombra á los que fallecieron. El padre extremó el procedimiento: cerróse á la banda y no nombró á Elisa ya nunca. Si le preguntaban cuántas hijas tenía, contestaba que dos. «La otra la perdí», añadía crispando los labios.\"},{\"heading\":false,\"text\":\"Unida ya Elisa con el que había elegido, se propuso ser intachable y perfecta en todo para rescatar la falta. No hubo esposa más tierna y solícita que Elisa, ni casa mejor gobernada que la suya, ni señora que con mayor abnegación prescindiese de sí propia y se eclipsase más modestamente en la sombra del hogar. Como al fin tenía pocos años y á veces la sangre hervía en sus venas con ímpetu juvenil, cuando veía á otras casadas adornarse, cubrirse de joyas, ir á bailes y fiestas y sonreir al espejo, y ella se quedaba recluída y en bata casera, decía para sí: «Bueno; pero esas no se escaparon con su marido antes de la boda.» Y aunque supiese que se escapaban después... ó cosa parecida... con otros,--siempre persistía en tenerlas por de mejor condición.\"},{\"heading\":false,\"text\":\"Hasta tal punto se consideró obligada á prestar fianza de su conducta, que nunca salió sola, ni consintió recibir una visita estando ausente su marido. A los hombres, fuesen jóvenes ó viejos, les hablaba fría y desabridamente, cortando en seguida la conversación. Su traje era obscuro, subido hasta las orejas, y su peinado estudiadamente sencillo y sin coquetería. Aficionada á las esencias y aguas de tocador, las suprimió por completo desde que oyó decir que «la mujer de bien, ni ha de oler mal, ni ha de oler bien». Ser tenida en concepto de mujer de bien, fué su ambición y su sueño; pero desconfiaba de conseguirlo nunca, por _aquello_ de la escapatoria...\"},{\"heading\":false,\"text\":\"Pasada la corta luna de miel, Adolfo comenzó á distraerse, y so color de política, se acostumbró á retirarse tarde, á pasarse los días fuera, sin venir ni á comer. Elisa lloró en silencio: lloró mucho, porque le quería, le quería con toda su alma, y no podía vivir dichosa sino con él y por él, á quien todo lo había sacrificado.\"},{\"heading\":false,\"text\":\"Un día, registrando el ropero de su marido para limpiar y arreglar la ropa, encontró traspapelada en un chaqué de verano una carta inequívoca... El dolor fue tan agudo, que Elisa se metió en la cama y estuvo varios días sin querer comer y con gran deseo de morirse. Así que cobró algún ánimo, se levantó y siguió viviendo. No profirió una queja: ¿con qué derecho? ¡La podían tapar la boca á las primeras palabras! ¡Y si salía á relucir lo de la fuga!.\"},{\"heading\":false,\"text\":\"Vinieron hijos, un niño y una niña; pero Elisa, que sufrió todo el peso de la crianza, no intervino en la educación, ni ejerció jamás esa autoridad de la madre digna y altiva, que lleva la maternidad como una corona. Sus hijos se habituaron á que «no mandaba mamá».\"},{\"heading\":false,\"text\":\"En cuanto á la hacienda, ya se infiere que la regía única y exclusivamente Adolfo, y Elisa no se hubiese arrojado á gastar cincuenta pesetas en nada extraordinario, sin la vénia necesaria. Muerto el padre de Elisa y recogida la legítima, todavía pingüe, aunque mermada por el enojo paternal, Adolfo se hizo cargo de todo y dedicó la mayor parte á sus goces, no sin que muchas veces oyese Elisa reconvenciones duras y alusiones amargas, fundadas en que su padre la había desheredado ó punto menos.\"},{\"heading\":false,\"text\":\"La salud de Elisa se resintió: los médicos hablaron de lesiones al corazón, que degeneraban en hidropesía. Como la enferma se agravase, pidió confesor, y por centésima vez se acusó de su delito, la escapatoria fatal. El confesor la mandó que se acusase de pecados de la vida presente, porque Dios no acostumbra recontar los ya perdonados y absueltos. Mas la absolución del cielo no bastaba á Elisa: ya se sabe que Dios es muy bueno; pero, en cambio, los hombres jamás olvidan ciertas cosas, y la mancha de vergüenza allí está sobre la frente hasta la última hora de vivir!\"},{\"heading\":false,\"text\":\"Con los ojos vidriados de lágrimas, Elisa pidió que viniese Adolfo, y así que le vió á su cabecera, echándole los brazos al cuello, murmuró á su oído: «Alma mía, mi bien, ya sé que no tengo derecho ninguno á pedirte que... que no te vuelvas á casar... ¡pero al menos... mira, en esta hora solemne... perdóname de veras _aquello_... y no me olvides así... tan pronto... tan pronto!»\"},{\"heading\":false,\"text\":\"Adolfo no contestó; no obstante, le pareció natural inclinarse y besarla. Y la culpable, dejando caer la cabeza sobre la almohada, espiró contenta.\"}]},{\"title\":\"La novia fiel\",\"blocks\":[{\"heading\":false,\"text\":\"Fué sorpresa muy grande para todo Marineda el que se rompiesen las relaciones entre Germán Riaza y Amelia Sirvián. Ni la separación de un matrimonio da margen á tantos comentarios. La gente se había acostumbrado á creer que Germán y Amelia no podían menos de casarse. Nadie se explicó el suceso, ni siquiera el mismo novio. Sólo el confesor de Amelia tuvo la clave del enigma.\"},{\"heading\":false,\"text\":\"Lo cierto es que aquellas relaciones contaban ya tan larga fecha, que casi habían ascendido á institución. Diez años de noviazgo no son grano de anís. Amelia era novia de Germán desde el primer baile á que asistió cuando la pusieron de largo.\"},{\"heading\":false,\"text\":\"¡Qué linda estaba en el tal baile! Vestida de blanco crespón, escotada apenas, lo suficiente para enseñar el arranque de los virginales hombros y del seno que latía de emoción y placer, empolvado el rubio pelo, donde se marchitaban capullos de rosa, Amelia era, según se decía en algún grupo de señoras, ya machuchas, «un cromo», «un grabado de _La Ilustración_». Germán la sacó á bailar, y cuando estrechó aquel talle que se cimbreaba, y sintió la frescura de aquel hálito infantil, perdió la chaveta, y en voz temblorosa, trastornado, sin elegir frases, hizo una declaración sincerísima, y recogió un _sí_ espontáneo, medio involuntario, doblemente delicioso. Se escribieron desde el día siguiente, y vino esa época de ventaneo y seguimiento en la calle, que es como la alborada de semejantes amoríos. Ni los padres de Amelia, modestos propietarios, ni los de Germán, comerciantes de regular caudal, pero de numerosa prole, se opusieron á la inclinación de los muchachos, dando por supuesto desde el primer instante que aquello pararía en justas nupcias, así que Germán acabase la carrera de Derecho y pudiese sostener la carga de una familia.\"},{\"heading\":false,\"text\":\"Los seis primeros años fueron encantadores. Germán pasaba los inviernos en Compostela, cursando en la Universidad y escribiendo largas y tiernas epístolas; entre leerlas, releerlas, contestarlas y ansiar que llegasen las vacaciones, el tiempo se deslizaba insensible para Amelia. Las vacaciones eran grato paréntesis, y todo el tiempo que durasen ya sabía Amelia que se lo dedicaría íntegro su novio. Este no entraba aún en la casa, pero acompañaba á Amelia en el paseo, y de noche se hablaban, á la luz de la luna, por una galería con vistas al mar. La ausencia, interrumpida por frecuentes regresos, era casi un aliciente, un encanto más, un interés continuo, algo que llenaba la existencia de Amelia, sin dejar cabida á la tristeza ni al tedio.\"},{\"heading\":false,\"text\":\"Así que Germán tuvo en el bolsillo su título de licenciado en Derecho, resolvió pasar á Madrid á cursar las asignaturas del doctorado. ¡Año de prueba para la novia! Germán apenas escribía: billetes garrapateados al vuelo, quizás sobre la mesa de un café, concisos, insulsos, sin jugo de ternura. Y las amiguitas caritativas, que veían á Amelia ojerosa, preocupada, alejada de las distracciones, la decían con perfidia burlona:--Anda, tonta, diviértete... ¡Sabe Dios lo que él estará haciendo por allá! ¡Bien inocente serías si creyeses que no te la pega...! A mí me escribe mi primo Lorenzo que vió á Germán muy animado en el teatro con _unas_....\"},{\"heading\":false,\"text\":\"El gozo de la vuelta de Germán compensó estos sinsabores. A los dos días ya no se acordaba Amelia de lo sufrido, de sus dudas, de sus sospechas. Autorizado para frecuentar la casa de su novia, Germán asistía todas las noches á la tertulia familiar, y en la penumbra del rincón del piano, lejos del quinqué velado por sedosa pantalla, los novios sostenían interminable diálogo, buscándose de tiempo en tiempo las manos para trocar una furtiva presión, y siempre los ojos para beberse la mirada hasta el fondo de las pupilas.\"},{\"heading\":false,\"text\":\"Nunca había sido tan feliz Amelia. ¿Qué podía desear? Germán estaba allí, y la boda era asunto concertado, resuelto, aplazado sólo por la necesidad de que Germán encontrase una posicioncita, una base para establecerse; una fiscalía, por ejemplo. Como transcurriese un año más y la posición no se hubiese encontrado aún, Germán decidió abrir bufete y mezclarse en la politiquilla local, á ver si así iba adquiriendo favor y conseguía el ansiado puesto. Los nuevos quehaceres le obligaron á no ver á Amelia ni tanto tiempo ni tan á menudo. Cuando la muchacha se lamentaba de esto, Germán se vindicaba plenamente; había que pensar en el porvenir; ya sabía Amelia que un día ú otro se casarían, y no debía fijarse en menudencias, en remilgos propios de los que empiezan á quererse. En efecto, Germán continuaba con el firme propósito de casarse así que se lo permitiesen las circunstancias.\"},{\"heading\":false,\"text\":\"Al noveno año de relaciones notaron los padres de Amelia (y acabó por notarlo todo el mundo), que el carácter de la muchacha parecía completamente variado. En vez de la sana alegría y la igualdad de humor que la adornaban, mostrábase llena de rarezas y caprichos, ya riendo á carcajadas, ya encerrada en hosco silencio. Su salud se alteró también: advertía desgana invencible, insomnios crueles, que la obligaban á pasarse las noches levantada, porque decía que la cama, con el desvelo, le parecía su sepulcro; además, sufría aflicciones al corazón y ataques nerviosos. Cuando la preguntaban en qué consistía su mal, contestaba lacónicamente: «No lo sé.» Y era cierto; pero al fin lo supo, y el saberlo la hizo mayor daño.\"},{\"heading\":false,\"text\":\"¿Qué mínimos indicios; qué insensibles pero eslabonados hechos; qué inexplicables revelaciones emanadas de cuanto nos rodea, hacen que sin averiguar nada nuevo ni concreto, sin que nadie la entere con precisión impúdica, la ayer ignorante doncella entienda de pronto y se rasgue ante sus ojos el velo de Isis? Amelia, súbitamente, comprendió. Su mal no era sino deseo, ansia, prisa, necesidad de casarse. ¡Qué vergüenza, qué sonrojo, qué dolor y qué desilusión si Germán llegaba á sospecharlo siquiera! ¡Ah! Primero morir. ¡Disimular, disimular á toda costa, y que ni el novio, ni los padres, ni la tierra, lo supiesen!\"},{\"heading\":false,\"text\":\"Al ver á Germán tan pacífico, tan aplomado, tan armado de paciencia; engruesando, mientras ella se consumía; chancero mientras ella empapaba la almohada en lágrimas, Amelia se acusaba á sí propia, admirando la serenidad, la cordura, la virtud de su novio. Y para contenerse y no echarse sollozando en sus brazos; para no cometer la locura indigna de salir una tarde sola é irse á casa de Germán, necesitó Amelia todo su valor, todo su recato, todo el freno de las nociones de honor y honestidad que la inculcaron desde la niñez.\"},{\"heading\":false,\"text\":\"Un día... sin saber cómo: sin que ningún suceso extraordinario, ninguna conversación sorprendida la ilustrase, acabaron de rasgarse los últimos cendales del velo... Amelia veía la luz; en su alma relampagueaba la terrible noción de la realidad; y al acordarse de que poco antes admiraba la resignación de Germán y envidiaba su paciencia, y al explicarse ahora la verdadera causa de esa paciencia y esa resignación incomparable, una carcajada sardónica crispó sus labios, mientras en su garganta creía sentir un nudo corredizo, que se apretaba poco á poco y la extrangulaba. La convulsión fué horrible, larga, tenaz; y aún no bien Amelia, destrozada, pudo formar frases, rogó á sus consternados padres que advirtiesen á Germán que las relaciones quedaban rotas. Cartas del novio, súplicas, paternales consejos, todo fué en vano: Amelia se aferró á su resolución, y en ella persistió, sin dar razones ni excusas.\"},{\"heading\":false,\"text\":\"--Hija, en mi entender, hizo usted muy mal--la decía el Padre Incienso, viéndola bañada en lágrimas al pie del confesionario.--Un chico formal, laborioso, dispuesto á casarse, no se encuentra por ahí fácilmente. Hasta el aguardar á tener posición para fundar familia, lo encuentro loable en él. En cuanto á lo demás... á esas figuraciones de usted... Los hombres... por desgracia... Mientras está soltero, habrá tenido esos entretenimientos... Pero usted...\"},{\"heading\":false,\"text\":\"--¡Padre--exclamó la joven--créame usted, pues aquí hablo con Dios! ¡Le quería... le quiero... y por lo mismo... por lo mismo, padre! ¡Si no le dejo... le imito! ¡Yo tambien...!\"}]},{\"title\":\"Afra\",\"blocks\":[{\"heading\":false,\"text\":\"La primera vez que asistí al teatro de Marineda--cuando me destinaron con mi regimiento á la guarnición de esta bonita capital de provincia--recuerdo que asesté los gemelos á la triple hilera de palcos, para enterarme bien del mujerío y las esperanzas que en él podía cifrar un muchacho de veinticinco años no cabales.\"},{\"heading\":false,\"text\":\"Gozan las marinedinas fama de hermosas, y vi que no usurpada. Observé también que su belleza consiste principalmente en el color. Blancas (por obra de naturaleza, no del perfumista), de bermejos labios, de floridas mejillas y mórbidas carnes, las marinedinas me parecieron una guirnalda de rosas tendida sobre un barandal de terciopelo obscuro. De pronto, en el cristal de los anteojos que yo paseaba lentamente por la susodicha guirnalda, se encuadró un rostro que me fijó los gemelos en la dirección que entonces tenían. Y no es que aquel rostro sobrepujase en hermosura á los demás, sino que se diferenciaba de todos por la expresión y el carácter.\"},{\"heading\":false,\"text\":\"En vez de una fresca encarnadura y un plácido y picaresco gesto, vi un rostro descolorido, de líneas enérgicas, de ojos verdes, coronados por cejas negrísimas, casi juntas, que les prestaban una severidad singular; de nariz delicada y bien diseñada, pero de alas movibles, reveladoras de la pasión vehemente; una cara de corte severo, casi viril, que coronaba un casco de trenzas de un negro de tinta; pesada cabellera que debía de absorber los jugos vitales y causar daño á su poseedora... Aquella fisonomía, sin dejar de atraer, alarmaba, pues era de las que dicen á las claras desde el primer momento á quien las contempla: «Soy una voluntad. Puedo torcerme, pero no quebrantarme. Debajo del elegante maniquí femenino, escondo el acerado resorte de un alma.»\"},{\"heading\":false,\"text\":\"He dicho que mis gemelos se detuvieron, posándose ávidamente en la señorita pálida del pelo abundoso. Aprovechando los movimientos que hacía para conversar con unas señoras que la acompañaban, detallé su perfil, su acentuada barbilla, su cuello delgado y largo, que parecía doblarse al peso del voluminoso rodete, su oreja menuda y apretada, como para no perder sonido. Cuando hube permanecido así un buen rato, llamando sin duda la atención por mi insistencia en considerar á aquella mujer, sentí que me daban un golpecito en el hombro, y oí que me decía mi compañero de armas Alberto Castro:\"},{\"heading\":false,\"text\":\"--¡Cuidadito!\"},{\"heading\":false,\"text\":\"--Cuidadito ¿por qué?--respondí bajando los anteojos.\"},{\"heading\":false,\"text\":\"--Porque te veo en peligro de enamorarte de Afra Reyes, y si está de Dios que ha de suceder, al menos no será sin que yo te avise y te entere de su historia. Es un servicio que los hijos de Marineda debemos á los forasteros.\"},{\"heading\":false,\"text\":\"--¿Pero tiene historia?--murmuré haciendo un movimiento de repugnancia; porque, aún sin amar á una mujer, me gusta su pureza, como agrada el aseo de casas donde no pensamos vivir nunca.\"},{\"heading\":false,\"text\":\"--En el sentido que se suele dar á la palabra historia, Afra no la tiene... Al contrario, es de las muchachas más formales y menos coquetas que se encuentran por ahí. Nadie se puede alabar de que Afra le devuelva una miradita, ó le diga una palabra de esas que dan ánimos. Y si no, haz la prueba: dedícate á ella; mírala más; ni siquiera se dignará volver la cabeza. Te aseguro que he visto á muchos que anduvieron locos y no pudieron conseguir ni una ojeada de Afra Reyes.\"},{\"heading\":false,\"text\":\"--Pues entonces... ¿qué?... ¿Tiene algo... en secreto? ¿Algo que manche su honra?\"},{\"heading\":false,\"text\":\"--Su honra, ó si se quiere, su pureza... repito que ni tiene ni tuvo. Afra, en cuanto á eso... como el cristal. Lo que hay te lo diré... pero no aquí; cuando se acabe el teatro saldremos juntos, y allá por el Espolón, donde nadie se entere... Porque se trata de cosas graves... de mayor cuantía.\"},{\"heading\":false,\"text\":\"Esperé con la menor impaciencia posible á que terminasen de cantar _La bruja_, y así que cayó el telón, Alberto y yo nos dirigimos de bracero hacia los muelles. La soledad era completa, á pesar de que la noche tibia convidaba á pasear, y la luna plateaba las aguas de la bahía, tranquila á la sazón como una balsa de aceite, y misteriosamente blanca á lo lejos.\"},{\"heading\":false,\"text\":\"--No creas--dijo Alberto--que te he traído aquí sólo para que no me oyese nadie contarte la historia de Afra. También es que me pareció bonito referirla en el mismo escenario del drama que esta historia encierra. ¿Ves este mar tan apacible, tan dormido, que produce ese rumor blando y sedoso contra la pared del malecón? ¡Pues sólo este mar... y Dios, que lo ha hecho, pueden alabarse de conocer la verdad entera respecto á la mujer que te ha llamado la atención en el teatro! Los demás la juzgamos por meras conjeturas... ¡y tal vez calumniamos al conjeturar! Pero hay tan fatales coincidencias; hay apariencias tan acusadoras en el mundo... que no podría disiparlas sino la voz del mismo Dios que ve los corazones y sabe distinguir al inocente del culpado.\"},{\"heading\":false,\"text\":\"«Afra Reyes es hija de un acaudalado comerciante; se educó algún tiempo en un colegio inglés, pero su padre tuvo quiebras, y por disminuir gastos recogió á la chica, interrumpiendo su educación. Con todo, el barniz de Inglaterra se le conocía: traía ciertos gustos de independencia y mucha afición á los ejercicios corporales. Cuando llegó la época de los baños no se habló en el pueblo sino de su destreza y vigor para nadar; una cosa sorprendente.\"},{\"heading\":false,\"text\":\"»Afra era amiga íntima, inseparable, de otra señorita de aquí, Flora Castillo; la intimidad de las dos muchachas continuaba la de sus familias. Se pasaban el día juntas; no salía la una si no la acompañaba la otra; vestían igual y se enseñaban, riendo, las cartas amorosas que las escribían. No tenían novio, ni siquiera demostraban predilección por nadie. Vino del Departamento cierto marino muy simpático, de hermosa presencia, primo de Flora, y empezó á decirse que el marino hacía la corte á Afra, y que Afra le correspondía con entusiasmo. Y lo notamos todos: los ojos de Afra no se apartaban del galán, y al hablarle, la emoción profunda se conocía hasta en el anhelo de la respiración y en lo velado de la voz. Cuando á los pocos meses se supo que el consabido marino realmente venía á casarse con Flora, se armó un caramillo de murmuraciones y chismes y se presumió que las dos amigas reñirían para siempre. No fue así; aunque desmejorada y triste, Afra parecía resignada, y acompañaba á Flora de tienda en tienda á escoger ropas y galas para la boda. Esto sucedía en Agosto.\"},{\"heading\":false,\"text\":\"»En Septiembre, poco antes de la fecha señalada para el enlace, las dos amigas fueron, como de costumbre, á bañarse juntas allí... ¿no ves? en la playita de San Wintila, donde suele haber mar brava. Generalmente las acompañaba el novio, pero aquel día sin duda tenía que hacer, pues no las acompañó.\"},{\"heading\":false,\"text\":\"»Amagaba tormenta; la mar estaba picadísima; las gaviotas chillaban lúgubremente, y la criada que custodiaba las ropas y ayudaba á vestirse á las señoritas, refirió después que Flora, la rubia y tímida Flora, sintió miedo al ver el aspecto amenazador de las grandes olas verdes que rompían contra el arenal. Pero Afra, intrépida, ceñido ya su traje marinero, de sarga azul obscura, animó con chanzas á su amiga. Metiéronse mar adentro cogidas de la mano, y pronto se las vió nadar, agarradas también, envueltas en la espuma del oleaje.\"},{\"heading\":false,\"text\":\"»Poco más de un cuarto de hora después salió á la playa Afra sola, desgreñada, ronca, lívida, gritando, pidiendo socorro, sollozando que á Flora la había arrastrado el mar...\"},{\"heading\":false,\"text\":\"»Y tan de verdad la había arrastrado, que de la linda rubia sólo reapareció, al otro día, un cadáver desfigurado, herido en la frente... El relato que de la desgracia hizo Afra entre gemidos y desmayos, fué que Flora, rendida de nadar y sin fuerzas, gritó «me ahogo»; que ella, Afra, al oirlo, se lanzó á sostenerla y salvarla; que Flora, al forcejear para no irse á fondo, se llevaba á Afra al abismo; pero que, aun así, hubiesen logrado quizá salir á tierra, si la fatalidad no las empuja hacia un trasatlántico fondeado en bahía desde por la mañana. Al chocar con la quilla, Flora se hizo la herida horrible, y Afra recibió también los arañazos y magulladuras que se notaban en sus manos y rostro...\"},{\"heading\":false,\"text\":\"»¿Que si creo que Afra...?\"},{\"heading\":false,\"text\":\"»Sólo añadiré que al marino, novio de Flora, no volvió á versele por aquí; y Afra, desde entonces, no ha sonreído nunca...\"},{\"heading\":false,\"text\":\"»Por lo demás, acuérdate de lo que dice la Sabiduría: el corazón del hombre... selva obscura. ¡Figúrate el de la mujer!»\"}]},{\"title\":\"Cuento soñado\",\"blocks\":[{\"heading\":false,\"text\":\"Había una princesa á quien su padre, un rey muy fosco, caviloso y cejijunto, obligaba á vivir reclusa en sombría fortaleza, sin permitirla salir del más alto torreón, á cuyo pie vigilaban noche y día centinelas armados de punta en blanco y dispuestos á ensartar en sus lanzones ó traspasar con sus venablos agudos á quien osase aproximarse. La princesa era muy linda; tenía la tez color de luz de luna, el pelo de hebras de oro, los ojos como las ondas del mar sereno, y su silueta prolongada y grácil recordaba la de los lirios blancos cuando la frescura del agua los enhiesta. En la comarca no se hablaba sino de la princesa cautiva y de su rara beldad, y de lo muchísimo que se aburriría entre las cuatro recias paredes de la torre, sin ver desde las ventanas alma viviente, más que á los guardias inmóviles, semejantes á estatuas de hierro.\"},{\"heading\":false,\"text\":\"Los campesinos se santiguaban de terror si casualmente tenían que cruzar ante la torre, aunque fuese á muy respetuosa distancia. En la centenaria selva que rodeaba la fortaleza, ni los cazadores se resolvían á internarse, temerosos de ser cazados. Silencio y soledad alrededor de la torre, silencio y soledad dentro de ella: tal era la suerte de la pobre doncellita, condenada á la eterna contemplación del cielo y del bosque, y del río caudaloso que serpenteaba lamiendo los muros del recinto.\"},{\"heading\":false,\"text\":\"De pechos sobre el avance del angosto ventanil, la princesa solía entregarse á vagos ensueños, aspirando á venturas que no conocía, de las cuales formaba idea por referencias de sus damas y por conversaciones entreoídas, sorprendidas--pues estaba vedado tratar delante de la princesa del mundo y sus goces.--Así y todo, reuniendo datos dispersos y concordándolos con ayuda de la fantasía, la secuestrada suponía fiestas magníficas, iluminaciones mágicas suspendidas entre el follaje de arbustos cuajados de flor y que exhalaban embriagadores aromas; oía los acordes de los instrumentos músicos, aladas melodías que volaban como cisnes sobre la superficie de los lagos, y veía las parejas que, cogidas de la cintura, luciendo sedas, encajes y joyas, danzaban con incansable ardor, deslizando los galanes palabras de miel al oído de las damiselas, rojas de pudor y felicidad, sueltos los rizos y anhelante el seno. Mientras la princesa se representaba estos cuadros, las nubes se teñían de carmín hacia el Poniente, un murmullo grave y hondo ascendía del río y del bosque, y la cautiva, oprimida de afán de libertad, murmuraba para sí: «¿Cómo será el amor?»\"},{\"heading\":false,\"text\":\"Allá donde la montaña escueta dominaba el río y el bosque, una cabañita muy miserable, de techo de bálago, servía de vivienda á cierto pastorcillo, que por costumbre bajaba á apacentar diez ó doce ovejas blancas en la misma linde de la selva. Más resuelto que los otros villanos, el mozalbete no recelaba aproximarse al castillo y deslizarse por entre la maleza con agilidad y disimulo, para mirar hacia la torre. Después de encontrar un senderito borrado casi, que moría en el cauce del río, logró el pastor descubrir también que al final del sendero abríase una boca de cueva; y metiéndose por ella intrépidamente, pudo cerciorarse de que, pasando bajo el río, la cueva tenía otra salida que conducía al interior del recinto fortificado. El descubrimiento hizo latir el corazón del pastorcillo, porque estaba enamorado de la princesa (aunque no la había visto nunca). Supuso que aprovechando el paso por la cueva lograría verla á su sabor, sin que se lo estorbasen los armados, los cuales, bien ajenos á que nadie pudiera introducirse en el recinto, casi al pie de la torre, no vigilaban sino la orilla opuesta y el río. Es cierto que entre la torre de la cautiva y el pastor, se interponían extensos patios, anchos fosos y recios baluartes; con todo eso, el muchacho se creía feliz: estaba dentro de la fortaleza, y pronto vería á su amada.\"},{\"heading\":false,\"text\":\"Poco tardó en conseguir tanta ventura. La princesa se asomó, y el pastorcillo quedó deslumbrado por aquella tez color de luna y aquel pelo de siderales hebras. No sabía como expresar su admiración y enviar un saludo á la damisela encantadora; se le ocurrió cantar, tocar su caramillo... pero le oirían; juntar y lanzar un ramillete de acianos, margaritas y amapolas... pero era inaccesible el alto y calado ventanil. Entonces tuvo una idea extraordinaria. Procuróse un pedazo de cristal, y así que pudo volver á deslizarse en el recinto por la cueva, enfocó el cristal de suerte que, recogiendo en él un rayo de sol, supo dirigirlo hacia la princesa. Esta, maravillada, cerró los ojos, y al volver á abrirlos para ver quién enviaba un rayo de sol á su camarín, divisó al pastorcillo que la contemplaba extático. La cautiva sonrió, el enamorado comprendió que aceptaban su obsequio... y desde entonces, todos los días, á la misma hora, el centelleo del arco iris despedido por un pedazo de vidrio alegró la soledad de la princesita y la cantó un amoroso himno, que se confundía con la voz profunda de la selva allá en lontananza...\"},{\"heading\":false,\"text\":\"De pronto sobrevino un cambio radical en la vida de la princesa. Murieron en una batalla su padre y su hermano, y recayó en ella la sucesión del trono. Brillante comitiva de señores, guerreros, obispos, pajes y damas, vino á buscarla solemnemente y á escoltarla hasta la capital de sus Estados. Y la que pocos días antes sólo conversaba con los pájaros, y sólo esperaba el rayo de sol del pastorcillo, se halló aclamada por millares de voces, aturdida por el bullicio de espléndidos festejos, y admiró las iluminaciones entre el follaje, y oyó las músicas ocultas en el jardín, y giró con las parejas que danzaban, y supo lo que es la gloria, la riqueza, el placer, la pasión delirante y la alegría loca...\"},{\"heading\":false,\"text\":\"Habían pasado muchos, muchos años, cuando la princesa, reina ya,--y casi vieja ya,--tuvo el capricho de visitar aquella torre donde su padre, por precaución y por tiránica desconfianza, la mantuvo emparedada durante los momentos más bellos de la juventud. Al entrar en el camarín, una nostalgia dolorosa, una especie de romántica melancolía se apoderó de la reina y la obligó á reclinarse en el ajimez, sintiendo preñados de lágrimas los ojos. La tarde caía inflamando el horizonte; el bosque exhalaba su melodioso y hondo susurro... y la reina, tapándose la cara con las manos, sentía que las gotas de llanto escurrían pausadamente al través de los dedos entreabiertos. ¿Lloraba acaso al recordar lo sufrido en el torreón; el largo cautiverio, la soledad, el aislamiento, el fastidio? ¡Mal conocéis el corazón de las mujeres los que á eso atribuís el llanto de tan alta señora!\"},{\"heading\":false,\"text\":\"Sabed que, desde el momento en que pisó la torre, la reina echaba de menos el rayo de sol, que todos los días, á la misma hora, la enviaba el pastorcillo enamorado por medio de un trozo de vidrio. Por aquel trozo de vidrio daría ahora la soberana los más ricos diamantes de su corona real. Sólo aquel rayo podía iluminar su corazón, fatigado, lastimado, quebrantado, marchito. Y al dejar escurrir las lágrimas, sin cuidarse de reprimirlas ni de secarlas con el blasonado pañuelo, lloraba la juventud, la ilusión, la misteriosa energía vital de los años primaverales... Nunca volvería el pastorcillo á enviarla el divino rayo.\"}]},{\"title\":\"Los buenos tiempos\",\"blocks\":[{\"heading\":false,\"text\":\"Siempre que entrábamos en el despacho del Conde de Lobeira, atraía mis miradas--antes que las armas auténticas, las lozas hispano-moriscas y los retazos de cuero estampado que recubrían la pared--un retrato de mujer, de muy buena mano, que por el traje indicaba tener, próximamente, un siglo de fecha.--«Es mi bisabuela, doña Magdalena Varela de Tobar, vigésima segunda Condesa de Lobeira»--había dicho el Conde, respondiendo á mi curiosa interrogación en el tono del que no quiere explicarse más ó no sabe otra cosa. Y por entonces hube de contentarme, acudiendo á mi fantasía para desenvolver las ideas inspiradas por el retrato.\"},{\"heading\":false,\"text\":\"Este representaba á una señora como de treinta y cinco años, de rostro prolongado y macilento, de líneas austeras, que indicaban la existencia sencilla y pura, consagrada al cumplimiento de nobles deberes y al trabajo doméstico, ley de la fuerte matrona de las edades pasadas. La modestia del vestir, en tan encumbrada señora, parecíame ejemplar; aquel corpiño justo de alepín negro, aquel pañolito blanco sujeto á la garganta por un escudo de los Dolores, aquel peinado liso y recogido detrás de la oreja, eran indicaciones inestimables para delinear la fisonomía moral de la aristocrática dama. No cabía duda: doña Magdalena había encarnado el tipo de la esposa leal, casta y sumisa, fiel guardadora del fuego de los lares; de la madre digna y venerada, ante quien sus hijos se inclinan como ante una reina; del ama de casa infatigable, vigilante y próvida, cuya presencia impone respeto y cuya mano derrama la abundancia y el bienestar. Así es que me sorprendió en extremo que un día, preguntándole al Conde en qué época habían sido enajenadas las mejores fincas, los pingües estados de su casa, me contestase sombríamente, señalando al retrato consabido.\"},{\"heading\":false,\"text\":\"--En tiempo de doña Magdalena.\"},{\"heading\":false,\"text\":\"El dato inesperado acrecentó mi interés. A fuerza de fijarme en el retrato observé que aquella pintura ofrecía una particularidad rara y siempre sugestiva: en cualquier punto de la habitación que me colocase para mirarla, me seguían los ojos de doña Magdalena con expresión imperiosa y ardiente. Casual acierto del pincel, ó alarde de destreza del pintor, las pupilas del retrato estaban tocadas por tal arte que pagaban con avidez y energía la mirada del que las contemplase desde lejos. Algunas veces, sin querer, levantaba yo la vista como si me atrajese tal singularidad y los ojos me llamasen. La severidad del fondo obscuro en que se destacaba la cabeza, la única nota clara del rostro y del pañolito, aumentaban la fuerza del extraño mirar.\"},{\"heading\":false,\"text\":\"Aunque el Conde de Lobeira es de carácter reservado y frío, hay instantes en que el corazón más tapiado se abre y deja salir el opresor secreto. Uno de esos momentos, siempre transitorios en ciertas organizaciones, llegó para el Conde el día en que, incitada por mi imaginación, traidora cuanto fecunda, me arrojé á trazar la silueta de doña Magdalena, modelo de cristianas virtudes, emblema de otros tiempos y otras edades en que el hogar olía á incienso como el sagrario, y la familia tenía la sólida estructura del granito.\"},{\"heading\":false,\"text\":\"--¡Por Dios, no siga usted!--exclamó mi interlocutor, dejando de atizar la chimenea y volviéndose hacia el retrato como nos volvemos hacia un enemigo.--El error más craso de cuantos pueden cometerse es juzgar del pasado por la impresión que nos causan sus reliquias. Cáscara vacía, huella de fósil en la piedra, ¿qué verdad ha de contarnos un retrato, un mueble ó un edificio ruinoso? Los soñadores como usted son los que han falseado la historia, poetizado lo más prosaico y embellecido lo más horrible. En ninguna época fué la humanidad mejor de lo que es ahora; pero las iniquidades pasadas se olvidan y un lienzo embadurnado y lleno de grietas basta para que nos abrume el descontento de lo presente. Ya que también usted cae en esa vulgarísima y temible preocupación de que se nos han perdido grandes virtudes, merece usted que para desilusionarla le cuente la historia de doña Magdalena, tal como la he entresacado de nuestro archivo y de otros documentos... ¡que obran en archivos judiciales!\"},{\"heading\":false,\"text\":\"Esa señora que está usted viendo, retratada con su jubón de alepín y su honesto pañolito, al casarse con mi bisabuelo, llevándole rica dote y el condado de Lobeira, se mostró apasionada hasta un grado increíble, despótico y furioso. Mi bisabuelo pasaba por el mozo más gallardo de toda la provincia, y doña Magdalena por una señorita fanáticamente devota: se susurraba que usaba cilicio y que se disciplinaba todas las noches. Fuese ó no verdad, lo que es á su marido cilicio le puso doña Magdalena, y hasta grillos, para que de ella no se apartase ni un minuto. Poco después de la boda, los que vieron al Conde pálido, demacrado y abatido, esparcieron el rumor absurdo de que su esposa le daba hierbas y filtros para subyugarle y para que ardiese más viva la tea del amor conyugal.\"},{\"heading\":false,\"text\":\"Duró esta situación, sin que la modificase el nacimiento de varios hijos. No obstante, á los diez ó doce años de matrimonio, observóse que el Conde, habiéndose aficionado á cazar y haciendo frecuentes excursiones por la montaña--pues pasaban largas temporadas en el campo, en el palacio solariego de Lobeira, según costumbre de los señores de entonces--recobraba cierta alegría y parecía rejuvenecido.\"},{\"heading\":false,\"text\":\"Como yo no estoy graduando el interés de mi historia, sino que se la cuento á usted descarnada y sin galas--advirtió al llegar aquí el narrador--diré inmediatamente lo que produjo la mejoría del Conde. Fué que, algún tanto aplacada aquella pasión de vampiro de su mujer, pudo respirar y vivir como las demás personas. Usted objetará que todo el delito de doña Magdalena consistía en amar excesivamente á su esposo, y que eso merece disculpa y hasta alabanza. Si yo discutiese tan delicado punto, temería ofender sus oídos de usted con algún concepto malsonante. Indicaré que hay cien maneras de amar, y que el santo nombre de amor cubre á veces nuestros bárbaros egoismos ó nuestras morbosas aberraciones. Y basta, que al buen entendedor... Ya continúo.\"},{\"heading\":false,\"text\":\"Como á veces se guardan bien los secretos en las aldeas, doña Magdalena tardó bastante en enterarse de que su marido, al volver de la caza, solía descansar en la choza de cierto labriego que tenía una hija preciosa. En efecto era así: el Conde de Lobeira prefería á los suculentos manjares de su cocina señorial, la _brona_ y la leche fresca servidas por la gentil rapaza, que, con la inocencia en los ojos y la risa en los labios, acudía solícita á festejarle. Doña Magdalena, ya informada, no pensó ni un minuto que allí existiese un puro idilio; vió desde el primer instante el pecado y la injuria. Y acaso acertase: no pretendo excusar á mi bisabuelo, aunque las crónicas afirman que era honesta y sencilla su afición á la hija del colono.\"},{\"heading\":false,\"text\":\"Lo histórico es que, en una noche de invierno muy obscura y muy larga, la puerta del Pazo se abrió sin ruido para dejar entrar á un hombre robusto, recio, vestido con el clásico traje del país, que hoy está casi en desuso. La Condesa le esperaba en el zaguán: tomóle de la mano, y por un pasadizo obscuro le llevó á una habitación interior, que alumbraba una vela de cera puesta en candelabro de maciza plata.--Era el oratorio.--Detrás de las colgaduras de damasco carmesí que lo vestían, y que replegó la dama, el hombre vió abierto un boquete, á manera de cueva; un agujero sombrío. Repito lo de antes: no busco _efectos_; pero aunque los buscase, creo que ninguno tan terrible como decir sin más circunloquios que el hombre--un _casero_, en las costumbres de entonces casi un ciervo de la Condesa--era el mismo padre de la zagala á quien el Conde solía visitar; y que doña Magdalena, enseñándole el negro hueco, advirtió al labrador que allí ocultarían el cadáver del Conde. En seguida le entregó un hacha nueva, afilada y cortante.\"},{\"heading\":false,\"text\":\"¿Temió aquel hombre por la vida de su hija y por la suya propia? ¿Impulsóle la cobardía ó el respeto tradicional á la casa de Lobeira? ¿Fué la sugestión que ejerce sobre un cerebro inculto y una voluntad irresoluta y débil, la hembra resuelta, de arrebatadas pasiones? ¿Fué codicia, tentación de onzas y de ricos joyeles que la esposa ultrajada le ofrecía en precio de la sangre? El caso es, que si hubo resistencia por parte del labriego, duró bien poco. Según su declaración, hizo la señal de la cruz (¡atroz detalle!) descalzóse, empuñó el hacha y siguió á la Condesa hasta el aposento en que el Conde dormía. Y mientras la señora alumbraba con la vela de cera del oratorio, el labriego descargó un golpe, otro, diez, en la frente, la cara, el pecho... El dormido no chistó: parece que al primer hachazo abrió unos ojos muy espantados... y luego, nada. Sábanas, colchones, el hacha y el muerto, todo fué arrojado al escondrijo; la Condesa lavó las manchas del suelo, cerró la trampa, y atestando de oro la faltriquera del asesino, le despachó con orden de cruzar el Miño y meterse en Portugal.\"},{\"heading\":false,\"text\":\"Un rumor, vago al principio y después muy insistente, se alzó con motivo de la desaparición del Conde de Lobeira. Su esposa hablaba de viajes motivados por un pleito; y en el oratorio, bajo cuyo piso yacía mi bisabuelo asesinado, celebrábase diariamente el santo sacrificio de la misa, asistiendo á él doña Magdalena, lo mismo que la ve usted retratada ahí: pálida, grave, modesta, rodeada de sus hijos, que la besaban la mano cariñosos. En aquel tiempo no había prensa que escudriñase misterios, y la coincidencia de la desaparición del Conde y la del casero y su hija la linda moza, dió pie á que se sospechase que el esposo de doña Magdalena vivía muy á gusto en algún rincón de esos que saben buscar los enamorados. No faltó quien compadeciese á la abandonada señora, en torno de la cual el respeto ascendió, como asciende la marea. Al verla pasar, derecha, macilenta, siempre de negro, la gente se descubría.\"},{\"heading\":false,\"text\":\"Y así corrió un año entero.\"},{\"heading\":false,\"text\":\"Al cumplirse, día por día, á corta distancia del Pazo de Lobeira apareció un hombre profundamente dormido; era el casero de la Condesa; y los demás labriegos, que le rodeaban esperando á que despertase, quedaron atónitos cuando al volver en sí, á gritos confesó el crimen, á gritos se denunció y á gritos pidió que le llevasen ante la justicia. Hay fenómenos morales que no explica satisfactoriamente ningún raciocinio: la mitad de nuestra alma está sumergida en sombras, y nadie es capaz de presentir qué alimañas saldrían de esa caverna, si nos empeñásemos en registrarla. El aldeano, cuando le preguntaron el móvil de su conducta, afirmó con rústicas razones que no lo sabía; que una gana irresistible--un _volunto_, como dicen ahora--le obligó á salir de Portugal y á ver de nuevo el Pazo; y que al avistarlo, le acometió un sueño letárgico, invencible también, y ya despierto, un ímpetu de confesar, de decir la verdad, de ser castigado--porque sin duda, calculo yo, su endeble alma no podía con el peso del secreto, que impenetrable y tranquila guardaba el alma varonil de doña Magdalena.\"},{\"heading\":false,\"text\":\"La prendieron, claro está, y aún se enseña en la cárcel marinedina el negro calabozo donde la Condesa de Lobeira se pudrió muchos meses... El casero fue ahorcado; y para librar á mi bisabuela del patíbulo, empeñóse la hacienda de mi casa. La justicia se comió con apetito tan sabrosa breva, y nuestra decadencia viene de ahí.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"Alcé los ojos y busqué los del retrato. La mirada de doña Magdalena se me figuró más tenaz, más intensa, más dolorosa. El biznieto callaba y suspiraba, como si le oprimiese el corazón el drama ancestral, como si percibiese la humedad de las lágrimas evaporadas hace un siglo.\"}]},{\"title\":\"Sara y Agar\",\"blocks\":[{\"heading\":false,\"text\":\"Explíqueme usted,--dije al señor de Bernárdez,--una cosa que siempre me infundió curiosidad. ¿Por qué en su sala tiene usted, bajo marcos gemelos, los retratos de su difunta esposa y de un niño desconocido, que según usted asegura, ni es hijo, ni sobrino, ni nada de ella? ¿De quién es otra fotografía de mujer, colocada enfrente, sobre el piano...? ¿no sabe usted? ¿una mujer joven, agraciada, con flecos de ricillos á la frente?\"},{\"heading\":false,\"text\":\"El sexagenario parpadeó, se detuvo, y un matiz rosa cruzó por sus mustias mejillas. Como íbamos subiendo un repecho de la carretera, lo atribuí á cansancio y le ofrecí el brazo, animándole á continuar el paseo, tan conveniente para su salud; como que, si no paseaba, solía acostarse sin cenar y dormir mal y poco. Hizo seña con la mano de que podía seguir la caminata, y anduvimos unos cien pasos más, en silencio. Al llegar al pie de la iglesia, un banco, tibio aún del sol y bien situado para dominar el paisaje, nos tentó, y á un mismo tiempo nos dirigimos hacia él. Apenas hubo reposado y respirado un poco Bernárdez, se hizo cargo de mi pregunta.\"},{\"heading\":false,\"text\":\"--Me extraña que no sepa usted la historia de esos retratos: ¡en poblaciones como Goyán, cada quisque mete la nariz en la vida del vecino, y glosa lo que ocurre y lo que no ocurre, y lo que no averigua lo inventa!\"},{\"heading\":false,\"text\":\"Comprendí que al buen señor debían de haberle molestado mucho antaño las curiosidades y chismografías del lugar, y callé, haciendo un movimiento de aprobación con la cabeza. Dos minutos después pude convencerme de que, como casi todos los que han tenido alegrías y penas de cierta índole, Bernárdez disfrutaba puerilmente en referirlas; porque no son numerosas las almas altaneras que prefieren ser para sí propios á la par Cristo y Cirineo y echarse á cuestas su historia.--He aquí la de Bernárdez, tal cual me la refirió mientras el sol se ponía detrás del verde monte en que se asienta Goyán.\"},{\"heading\":false,\"text\":\"«Mi mujer y yo nos casamos muy jovencitos: dos nenes, con la leche en los labios. Ella tenía quince años, yo diez y ocho. Una muchachada, quién lo duda. Lo que pasó con tanto madrugar fué, que queriéndonos y llevándonos como dos ángeles, de puro bien avenidos que estábamos, al entrar yo en los treinta y cinco, mi mujer empezó á parecerme así... vamos, como mi hermana. La profesaba una ternura sin límites; no hacía nada sin consultarla, no daba un paso que ella no me aconsejase, no veía sino por sus ojos... pero todo fraternal, todo muy tranquilo.\"},{\"heading\":false,\"text\":\"»No teníamos sucesión, y no la echábamos de menos. Jamás hicimos rogativa ni oferta á ningún santo para que nos enviase tal dolor de cabeza. La casa marchaba lo mismo que un cronómetro: mi notaría prosperaba; tomaba incremento nuestra hacienda; adquiríamos tierras; gozábamos de mil comodidades; no cruzábamos una palabra más alta que otra, y veíamos juntos aproximarse la vejez sin desazón ni sobresalto, como el marino que se acerca al término de un viaje feliz, emprendido por iniciativa propia, por gusto y por deber.\"},{\"heading\":false,\"text\":\"»Cierto día, mi mujer me trajo la noticia de que había muerto la inquilina de una casucha de nuestra pertenencia. Era esta inquilina una pobretona, viuda de un guardia civil, y quedaba sola en el mundo la huérfana, criatura de cinco años.--Podíamos recogerla, Hipólito--añadió Romana.--Parte el alma verla así. La enseñaríamos á planchar, á coser, á guisar, y tendríamos, cuando sea mayor, una criadita fiel y humilde.--Dí que haríamos una obra de misericordia y que tú tienes el corazón de manteca.--Esto fué lo que respondí, bromeando. ¡Ay! ¡Si el hombre pudiese prever dónde salta su destino!\"},{\"heading\":false,\"text\":\"»Recogimos, pues, la criatura, que se llamaba Mercedes, y así que la lavamos y la adecentamos, amaneció una divinidad, con un pelo ensortijado como virutas de oro, y unos ojos que parecían dos violetas, y una gracia y una zalamería... Desde que la vimos... ¡adiós planes de enseñarla á planchar y á poner el puchero! Empezamos á educarla del modo que se educan las señoritas... según educaríamos á una hija, si la tuviésemos. Claro que en Goyán no la podíamos afinar mucho, pero se hizo todo lo que permite el rincón este. Y lo que es mimarla... ¡Señor! ¡En especial Romana... un desastre! Figúrese usted que la pobre Romana, tan modesta para sí que jamás la ví encaprichada con un perifollo... encargaba los trajes y los abriguitos de Mercedes á la mejor modista de Marineda. ¿Qué tal?\"},{\"heading\":false,\"text\":\"»Cuando llegó la chiquilla á presumir de mujer, empezaron también á requebrarla y á rondarla los señoritos en los días de ferias y fiestas, y yo á rabiar cuando notaba que la hacían cocos. Ella se reía y me decía siempre, mirándome mucho á la cara:--Padrino (me llamaba así), vamos á burlarnos de estos tontos; á usted le quiero más que á ninguno.--Me complacía tanto que me lo dijese (¡cosas del demonio!) que la reñía sólo por oirla repetir:--Le quiero más á usted...--Hasta que una vez, muy bajito, al oído:--¡Le quiero más, y me gusta más... y no me casaré, nunca, padrino!--¡Por éstas, que así habló la rapaza!\"},{\"heading\":false,\"text\":\"»Se me trastornó el sentido. Hice mal, muy mal, y sin embargo, no sé, en mi pellejo, lo que harían más de cien santones. En fin, repito que me puse como lunático, y sin intención, sin premeditar las consecuencias (porque repito que perdí la chaveta completamente), yo, que había vivido más de veinte años como hombre de bien y marido leal, lo eché á rodar todo en un día... en un cuarto de hora...\"},{\"heading\":false,\"text\":\"»Todo á rodar, no; porque tan cierto como que Dios nos oye, yo seguía consagrando un cariño profundo, inalterable, á mi mujer, y si me proponen que la deje y me vaya con Mercedes por esos mundos--se lo confesé á Mercedes misma, no crea usted, y lloró á mares,--antes me aparto de cien Mercedes que de mi esposa. Después de tantos años de vida común, se me figuraba que Romana y yo habíamos nacido al mismo tiempo, y que reunidos y cogidos de las manos debíamos morir. Sólo que Mercedes me sorbía el seso, y cuando la sentía acercarse á mí, la sangre me daba una sola vuelta de arriba abajo, y se me abrasaba el paladar, y en los oídos me parecía que resonaba galope de caballos, un estrépito que me aturdía.»\"},{\"heading\":false,\"text\":\"--¿Es de Mercedes el retrato que está sobre el piano?--pregunté al viejo.\"},{\"heading\":false,\"text\":\"--De Mercedes es. Pues verá usted: Romana se malició algo, y los chismosos intrigantes se encargaron de lo demás. Entonces, por evitar disgustos, conté una historia: dije que unos señores de Marineda, que iban á pasar larga temporada en Madrid, querían llevarse á Mercedes, y lo que hice fué amueblar en Marineda un piso, donde Mercedes se estableció decorosamente, con una criadita. A pretexto de asuntos, yo veía á la muchacha una vez por semana lo menos. Así, la situación fué mejor... vamos, más tolerable que si estuviesen las dos bajo un mismo techo, y yo entre ellas.\"},{\"heading\":false,\"text\":\"»Romana callaba,--era muy prudente,--pero andaba inquieta, pensativa, alterada; y decía yo: ¿por dónde estallará la bomba? Y estalló... ¿por dónde creerá usted? Una tarde que volví de Marineda, mi mujer, sin darme tiempo á soltar la capa, se encerró conmigo en su cuarto y me dijo que no ignoraba el estado de Mercedes... ¡Ya supondrá usted cuál sería el estado de Mercedes!... y que, pues había sufrido tanto y con tal paciencia, lo que naciese, para ella, para Romana, tenía que ser en toda propiedad..... como si lo hubiese parido Romana misma.\"},{\"heading\":false,\"text\":\"»Me quedé tonto. Y el caso es que mi mujer se expresaba de tal manera, ¡con un tono y unas palabras!, y tenía además tanta razón y tal sobra de motivos para mandar y exigir, que apenas nació el niño y lo ví empañado, lo envolví en un chal de calceta que me dió Romana para ese fin, y en el coche de Marineda á Goyán hizo su primer viaje de este mundo.»\"},{\"heading\":false,\"text\":\"--¿Ese niño es el que está retratado al lado de su esposa de usted, dentro de los marcos gemelos?\"},{\"heading\":false,\"text\":\"--Ajajá. Precisamente. ¡Mire usted: dificulto que ningún chiquillo, ni Alfonso XIII, se haya visto mejor cuidado y más estimado! Romana, desde que se apoderó del pequeño, no hizo caso de mí, ni de nadie, sino de él. El niño dormía en su cuarto; ella le vestía, ella le desnudaba, ella le tenía en el regazo, ella le enseñaba á juntar las letras y ella le hacía rezar. Hasta formó resolución de testar en favor del niño... Sólo que él falleció antes que Romana; como que al rapaz le dieron las viruelas el 20 de Marzo, y una semana después voló á la gloria... y Romana, el 7 de Abril fué cuando la desahució el médico, y la perdí á la madrugada siguiente.»\"},{\"heading\":false,\"text\":\"--¿Se la pegaron las viruelas?--pregunté al señor de Bernárdez, que se aplicaba el pañuelo sin desdoblar á los ribeteados y mortecinos ojos.\"},{\"heading\":false,\"text\":\"--¡Naturalmente... Si no se apartó del niño!\"},{\"heading\":false,\"text\":\"--¿Y usted, cómo no se casó con Mercedes?\"},{\"heading\":false,\"text\":\"--Porque malo soy, pero no tanto como eso--contestó en voz temblona, mientras una aguadilla que no se redondeó en lágrima asomaba á sus áridos lagrimales.\"}]},{\"title\":\"Maldición de gitana\",\"blocks\":[{\"heading\":false,\"text\":\"Siempre que se trata, entre gente con pretensiones de instruída, de agorerías y supersticiones, no hay nadie que no se declare exento de miedos pueriles, y punto menos desenfadado que don Juan frente á las estatuas de sus víctimas. No obstante, transcurridos los diez minutos consagrados á alardear de espíritu fuerte, cada cual sabe alguna historia rara, algún sucedido inexplicable, una «coincidencia». (Las coincidencias hacen el gasto.)\"},{\"heading\":false,\"text\":\"La ocasión más frecuente de hablar de supersticiones la ofrecen los convites. De los catorce ó quince invitados se excusan uno ó dos: al sentarse á la mesa, alguien nota que son trece los comensales,--y al punto decae la animación, óyense forzadas risas y chanzas poco sinceras, y los amos de la casa se ven precisados á buscar, aunque sea en los infiernos, un número catorce. Conjurado ya el mal sino, renace el contento; las risitas de las señoras tienen un sonido franco; se ve que los pulmones respiran á gusto. ¿Quién no ha asistido á un episodio de esta índole?\"},{\"heading\":false,\"text\":\"En el último que presencié pude observar que Gustavo Lizana, mozo asaz despreocupado, era el más carilargo al contar trece, y el que más desfrunció el gesto cuando fuímos catorce. No hacía yo tan supersticioso á aquel infatigable cazador y _sportsman_, y extrañándome verle hasta demudado en los primeros momentos, á la hora del café le llevé hacia un ángulo del saloncillo japonés, y le interrogué directamente.\"},{\"heading\":false,\"text\":\"--Una coincidencia--respondió, como era de presumir; y al ver que yo sonreía, me ofreció con un ademán el sofá bordado, en cuyos cogines una bandada de grullas blancas con patitas rosa volaba sobre un cañaveral de oro, nacido en fantástica laguna: se sentó él en una silla de bambú, y rápidamente, entrecortando la narración con agitados movimientos, me refirió su _coincidencia_ del número fatídico.\"},{\"heading\":false,\"text\":\"--Mis dos amigos íntimos--los de corazón--eran los dos chicos de Mayoral, de una familia extremeña antigua y pudiente. Habíamos estado juntos en el colegio de los jesuítas, y cuando salimos al mundo, la amistad se estrechó. Llamábanse el mayor Leoncio y el otro Santiago; y habrá usted visto pocas figuras más hermosas, pocos muchachos más simpáticos y pocos hermanos que tan entrañablemente se quisiesen. Huérfanos de padre y madre, y dueños de su hacienda, no conocían tuyo ni mío: bolsa común, confianza entera, y á pesar de la diferencia de caracteres--Leoncio nervioso y vehemente hasta lo sumo, y Santiago de un genio igual y pacífico--inalterable armonía. A mí me llamaban, en broma, su otro hermano, y la gente, á fuerza de vernos unidos, había llegado á pensar que éramos, cuando menos, próximos parientes los Mayoral y yo.\"},{\"heading\":false,\"text\":\"Apasionados cazadores los tres, nos íbamos semanas enteras á las dehesas y cotos que los Mayoral poseían en la Mancha y Extremadura, donde hay de cuanta alimaña Dios crió, desde perdices y conejos hasta corzos, venados, jabalís, ginetas y gatos monteses.\"},{\"heading\":false,\"text\":\"Con buen refuerzo de escopetas negras y una jauría de excelentes podencos, hacíamos cada ojeo y cada batida, que eran el asombro de la comarca. De estas excursiones resolvimos una cierto día de San Leoncio; no cabe olvidar la fecha. Nos había convidado juntos una tía de los de Mayoral, señora discretísima y madre de una muchacha encantadora, por quien Santiago bebía los vientos: sutilizando mucho, creo que esta pasión de Santiago tuvo su parte de culpa en la desgracia que sucedió: ya diré por qué.\"},{\"heading\":false,\"text\":\"Ello es que nos reunimos en la casa, donde, con motivo de la fiesta, había otros varios convidados: amiguitas de la niña, señores formales, íntimos de la mamá... Y yo, que jamás contaba entonces los comensales, al pasar al comedor, involuntariamente, me fijo en los platos... ¡Eramos trece, trece justos!\"},{\"heading\":false,\"text\":\"Ni se me ocurrió chistar: por otra parte, no sentía aprensión. Estaríamos á la mitad de la comida, cuando lo advirtió el ama de la casa, y dijo riéndose:--«¡Hola! ¡Pues con el resfriado de Julia, que la impidió venir, nos hemos quedado en la docena del fraile! No asustarse, señores; que aquí nadie ha cumplido los sesenta más que yo, y en todo caso seré la escogida.»--¿Qué habíamos de hacer? Lo echamos á broma también, y brindamos alegremente por que se desmintiese el augurio. Y había allí un señor que, presumiendo de gracioso, dijo con sorna:--«Es muy malo comer trece... cuando sólo hay comida para doce».\"},{\"heading\":false,\"text\":\"A la madrugada siguiente tomamos el tren y salimos hacia el cazadero. La expedición se presentaba magnífica; la temperatura era, como de mediados de Septiembre, templada y deliciosa; cada tarde los zurrones volvían atestados de piezas, y para mayor satisfacción, nos habían anunciado que andaban reses por el monte, y que el primer ojeo nos prometía rico botín. Decidimos que este ojeo principiase un miércoles por la mañana, y apenas despachadas las migas y el chocolate, salimos á cabalgar nuestros jacos, que nos esperaban á la puerta, entre el tropel de las escopetas negras y la gresca y alborozo de los perros. Como tengo tan presentes las menores circunstancias de aquel día, recuerdo que me extrañó mucho la furia con que los animales ladraban, y al asomarme fuera, ví, apoyada en uno de los postes del emparrado que sombreaba la puerta, á una gitana atezada, escuálida, andrajosa.\"},{\"heading\":false,\"text\":\"Podría tener sus veinte años, y si la suciedad, la descalcez y las greñas no la afeasen, no carecería de cierto salvaje atractivo, porque los ojos brillaban en su faz cetrina como negros diamantes, los dientes eran piñones mondados y el talle un junco airoso. Los pingajos de su falda apenas cubrían sus desnudos y delgados tobillos, y al cuello tenía una sarta de vidrio, mezclada con no sé qué amuletos. Dije que sus ojos brillaban, y era cierto; brillaban de un modo raro, que no supe definir; los tenía clavados en Santiago--que, lo repito, era un muchacho arrogante, rubio y blanco, y en aquel instante, subido al poyo de montar y con un pie en el estribo, con su sombrero de alas anchas, su bizarro capote hecho de una manta zamorana, de vuelto cuello de terciopelo verde, y sus altos zajones de caza, que marcaban la derechura de la pierna, aún parecía más apuesto y gallardo.--Y á Santiago fué á quien dirigió sus letanías la egipcia, soltándole esos requiebros raros que gastan ellas, y ofreciéndose á decirle la buenaventura. En aquel momento, Santiago, de seguro, pensaba en el dulce rostro de su novia, y el contraste con el de la gitana debió de causarle una impresión de repugnancia hacia ésta; porque era galante con todas las mujeres, y sin embargo, soltó una frase dura y hasta cruel, una frase fatal... yo así lo creo...\"},{\"heading\":false,\"text\":\"--¿Qué buenaventura vas á darme tú?--exclamó Santiago.--¡Para ti la quisieras! ¡Si tuvieses ventura, no serías tan fea y tan negra, chiquilla!\"},{\"heading\":false,\"text\":\"La gitana no se inmutó en apariencia, pero yo noté en sus ojos algo que parecía la sombra de un abismo; y fijándolos de nuevo en Santiago, que estaba á caballo ya, articuló despacio, con indiferencia atroz y en voz ronca:\"},{\"heading\":false,\"text\":\"--¿No quieres buenaventuras, jermoso? Pues toma mardisiones... Premita Dios... Premita Dios... ¡que vayas montao y vuelvas tendío!\"},{\"heading\":false,\"text\":\"Yo no sé con qué tono pudo decirlo la malvada, que nos quedamos de hielo. Leoncio, en especial, como adoraba en su hermano, se demudó un poco y avanzó hacia la gitana en actitud amenazadora; los perros, que conocen tan perfectamente las intenciones de sus amos, se abalanzaron ladrando con furia; uno de ellos hincó los dientes en la pierna desnuda de la mujer, que dió un chillido. Esto bastó para que Leoncio y yo, y todos, incluso Santiago, nos distrajésemos de la maldición y pensásemos únicamente en salvar á la bruja moza, en riesgo inminente de ser destrozada por la jauría. Contenidos los perros, cuando volvimos la cabeza, la gitana ya no parecía por allí; sin duda se había puesto en cobro, aunque nadie supo por donde.\"},{\"heading\":false,\"text\":\"Al llegar aquí de su narración Gustavo, me hirió de súbito un recuerdo.\"},{\"heading\":false,\"text\":\"--Espere usted, espere usted...--murmuré recapacitando.--Creo que conozco el final de la historia... Cuando usted nombró á los Mayoral, empezó á trabajar mi cabeza... El nombre _me sonaba_... Tengo idea de que conozco á los dos hermanos, y ya voy reconstruyendo su figura... Leoncio, vivo, moreno, delgado; Santiago, rubio y algo más grueso... ¿Fué en esa cacería donde?...\"},{\"heading\":false,\"text\":\"--Donde Leoncio, creyendo disparar á un corzo, mató á Santiago de un balazo en la cabeza--respondió lentamente Gustavo, cruzando las manos con involuntaria angustia.--Santiago _volvió tendido_... Perdí á la vez mis dos amigos; porque el matador, si no enloqueció de repente, como pasa en las novelas y en las comedias, quedó en un estado de perturbación y de alelamiento que fué creciendo cada día; y quizás por olvidar cortos instantes la horrible escena, se entregó--él que era tan formalillo que hasta le embromábamos--á mil excesos, acabando así de idiotizarse. ¿Después de saber esta _coincidencia_, extrañará usted que me agrade poco sentarme á una mesa de trece? Por más que quiero dominarme, se me conoce el miedo... ¡El miedo, sí; hay que llamar á las cosas por su nombre!\"},{\"heading\":false,\"text\":\"--¿Y volvió á parecer la gitana?--pregunté con curiosidad.\"},{\"heading\":false,\"text\":\"--¡La gitana! ¡Quién sabe adónde vuelan esas cornejas agoreras!--exclamó Gustavo sombríamente.--Los de esa casta no tienen poso ni paradero... Como dice Cervantes, á su ligereza no la impiden grillos, ni la detienen barrancos, ni la contrastan paredes... Cuando velábamos al pobre Santiago, y tratábamos de impedir que se suicidase el desesperado Leoncio, ya la bruja debía de estar entre breñas, camino de Huelva ó de Portugal.\"}]},{\"title\":\"La bicha\",\"blocks\":[{\"heading\":false,\"text\":\"Han leído ustedes á Selgas?--preguntó la discreta viuda, cerrando su abanico antiguo de _vernis Martín_, una de esas joyas que para todo sirven, excepto para abanicarse.--¿Han leído á Selgas?\"},{\"heading\":false,\"text\":\"Los que formábamos _peñita_ en la estufa, huyendo de los sofocados y atestados salones, movimos la cabeza. ¿Selgas? Un autor á quien, como suele decirse, «le ha pasado el sol por la puerta»... Nombre casi borrado ya...\"},{\"heading\":false,\"text\":\"--Pues era ingenioso--declaró la viudita--y á mí me divertía muchísimo... En no sé qué libro suyo--las citas exactas allá para los sabiondos--sienta una teoría sustanciosa, no crean ustedes. A propósito del sistema parlamentario, que le fastidiaba mucho, dice que mientras nadie se queja de lo que no escoge, todo el mundo rabia con lo que escogió; que rara vez nos mostramos descontentos de nuestros padres ni de nuestros hijos, pero que de los cónyuges y de los criados siempre hay algo malo que contar. ¿Verdad que es gracioso? Sólo que en ese capítulo de la elección conyugal, le faltó distinguir... Se le olvidó decir que sólo los hombres eligen, mientras las mujeres toman lo que se presenta... Y el caso es que la elección conyugal confirma la teoría de Selgas: los hombres, que escogen amplia y libremente, son los que escogen peor.\"},{\"heading\":false,\"text\":\"Esta afirmación de la viuda levantó un turbión de humorísticas protestas entre el elemento masculino de la peñita.\"},{\"heading\":false,\"text\":\"--No hay que amontonarse--exclamó la señora intrépidamente.--Los hombres que aciertan, aciertan como _el consabido_ de la fábula... Y si no... á la prueba. Todos los jueves que nos reunamos aquí--en este rincón, á la sombra de estos pandanos tan colosales, cerca de esta fuente tan bonita con la luz eléctrica--me ofrezco á contarles á ustedes una historia de elección conyugal masculina... que les parecerá increíble. Empezaremos ahora mismo... Ahí va la de hoy.\"},{\"heading\":false,\"text\":\"Cuando perdí á mi marido, tuve que vivir varios años en una capital de provincia, desenredando asuntos de mucho interés para mí y para mis hijos. Ya saben ustedes que no soy huraña, y pasado el luto, aproveché las contadas ocasiones de ver gente que se ofrecían allí. Había una Sociedad de recreo que daba en Carnaval dos ó tres bailes de máscaras, y me gustaba ir á sentarme en un palco, acompañada de varias amigas y amigos de los que solían hacerme tertulia, y divertirme en remirar los disfraces caprichosos, la animación y las bromas que se corrían abajo, en el hervidero de la sala. Eran bailes en que se mezclaban el señorío y la mesocracia con bastantes familias artesanas, sin que se conociesen mucho las diferencias entre estas clases sociales--porque las artesanas de M*** se visten, peinan y prenden con gusto, son guapas y tienen aire fino.--La Junta directiva sólo excluía rigurosamente á las mujeres notoriamente indignas; y figúrense ustedes el espanto de la concurrencia cuando, la noche del lunes de Carnaval, empezó á esparcirse la voz de que estaba en el baile, enmascarada y del brazo de un socio, la célebre Natalia, por otro nombre _La Bicha_ (la _Culebra_); la daban este apodo por su fama de mala y engañadora, ó, según otros, porque tenía la cabeza pequeñita, la tez morena aceitunada y el pelo casi azulado de puro negro; señas de cuya exactitud pudimos cerciorarnos todos, como verán ustedes.\"},{\"heading\":false,\"text\":\"Al saberse la noticia, justamente se hallaba en mi palco el presidente de la Sociedad, señor viudo, acaudalado y respetable, padre de una niña preciosa que yo me llevaba á casa por las tardes á jugar con la chiquilla mía. Sobrecogido y turbado, el presidente se agitaba en el asiento, haciendo coraje, como suele decirse, para bajar á cumplir su deber de expulsar á la intrusa. Comprenderán ustedes que no existe deber más penoso: ir á darle en público un bofetón á una mujer... ¡sea quien sea! Todos seguíamos con los ojos á la máscara sospechosa, y la indignación fermentaba. Abandonada desde el primer run-run por el socio que la introdujo y que se dió prisa á desaparecer; asaltada por unos cuantos mozalbetes, que la asaetaban con insolentes pullas y dicharachos; aislada á la vez en un espacio libre--porque todas las demás mujeres se apartaban--la _Culebra_, apretando contra el rostro su antifaz, recogiendo los pliegues de su manto de _beata_, como para ocultarse, permanecía apoyada en una columna de las que sostienen los palcos, en actitud de fiera á quien acosan. Por fin, el presidente se decidió, y, tomando precipitadamente el sombrero, salió al pasillo; pronto le vimos aparecer en el salón y dirigirse á donde estaba la _Culebra_. A las frases secas y rápidas, cual latigazos, del presidente, los mozalbetes se desviaron, dejando sola á la mujer; y ésta, con un movimiento de soberbia que remedaba la dignidad, revolviéndose bajo el ultraje, se arrancó de súbito la careta de raso negro, echó atrás el manto, y descubierta la cabeza, erguido el cuello, rechispeantes los ojos, miró, retó, fulminó al presidente primero, después, circularmente, á todo el concurso, á las señoras, á las señoritas, que volvían la cara ruborizándose, á los hombres que cuchicheaban y se reían... Y despacio, sin bajar la frente, pasó por entre la multitud apiñada que se estremecía á su contacto, y todavía, desde la puerta, volviéndose, disparó el venablo de sus pupilas (¡qué mirada aquella, Dios mío!) al presidente, que accionaba entre un círculo de individuos de la Directiva y de señores que le felicitaban por su acción... Minutos después, muy exaltado, volvía al palco el buen señor, y al acompañarme, á la salida, todavía hablaba del descoco de la pájara, refiriéndonos, con el recato posible, su vida y milagros, capaces, ciertamente, de poner colorada á una estatua de piedra.\"},{\"heading\":false,\"text\":\"A la vuelta de cinco meses; cuando á las frioleras diversiones del Carnaval reemplazan los idílicos goces de las giras y de las campestres romerías,--empezó á susurrarse en M*** que el presidente de la Sociedad _Centro de Amigos_, el honrado y formal don Mariano Subleiras, con sus cincuenta del pico, su viudez y su niña encantadora, pasaba á segundas nupcias... ¿Ya han adivinado ustedes con quién?... ¡Con la propia Natalia, la _Bicha_, la prójima echada del baile!--Al oirlo, sepan ustedes que no lo puse en duda ni un momento. Dirán ustedes que soy pesimista... Digan lo que quieran, ¡El caso es que yo, en seguida, creí firmemente que era gran verdad eso que á todos les parecía el colmo de lo absurdo!--¿Pero no se acuerda usted?--me objetaban.--Pero si fué él mismo quien la puso de patitas...--Pues por eso, cabalmente por eso--contestaba yo, dejándoles con la boca de un palmo. Al fin, tanto me calentaron la cabeza con la boda dichosa, que entre el deseo de complacer y la lástima que me infundía la pequeña, aquella rubita monísima, amenazada de madrastra semejante, me decidí á meterme donde no me llamaban y á hacer á don Mariano el siempre inoportuno regalo del buen consejo... Le llamé á capítulo, le prediqué un sermón que ni un padre capuchino; estuve elocuente, les aseguro que sí... Y me puse muy hueca cuando al terminar mi plática, don Mariano, al parecer conmovido, murmuró aplicando el pico del pañuelo á los ojos:--Prometo á usted que no me casaré con la Natalia...\"},{\"heading\":false,\"text\":\"--¿Y al poco tiempo se casó?--interrogaron con malicia los de la peña.\"},{\"heading\":false,\"text\":\"--No, señores... No se casó al poco tiempo... ¡Cuando me empeñaba una palabra inquebrantable... estaba ya casado... secretamente!\"},{\"heading\":false,\"text\":\"Hubo en el grupo exclamaciones, risas, comentarios, y Ramiro Nozales, que la echaba de observador, pronunció con énfasis:\"},{\"heading\":false,\"text\":\"--¡Qué humano es eso!\"},{\"heading\":false,\"text\":\"--Lo que á mí me preocupó mucho entonces--prosiguió la señora--fué averiguar cómo se las había compuesto la lagarta para hacer presa en don Mariano. Su móvil era patente: una venganza que eriza el pelo... Pero, ¿de qué medios se había valido? Cuando fué expulsada del baile, don Mariano sólo la conocía de vista y por su lamentable reputación... Excitada mi curiosidad, en que entraba tanto interés por la pobre niña, pude averiguar algo... ¡Algo que también va usted á decir que es _muy humano_, amigo Nozales, porque conozco su escuela de usted!... Parece que la _Bicha_ se presentó en casa de don Mariano días después de la expulsión, y bañada en lágrimas, y con hartos desmayos y suspiros, le pidió reparación del ultraje; reparación... ¿cómo diré yo?, una reparación privada, una palabra benévola, una excusa, algo que la consolase, porque desde aquel episodio se sentía enferma, abatida y á punto de muerte... «De otra persona, mire usted, no me hubiese importado; pero de usted... vamos, de usted... un señor tan digno, un señor tan virtuoso...», dicen que silbaba la _Culebra_, empezando insensiblemente á enroscarse... De aquí al vasito de agua, á contar una larga historia, á ser escuchada y compadecida, visitada después, á enlazar con el primer anillo, á deslizarse, á abrazar ya con las roscas flexibles el pecho, la cabeza y el cuerpo todo... el camino ni es largo ni difícil, y en cuatro meses y medio lo anduvo la _Bicha_... hasta llegar á la iglesia.--Al año siguiente, la noche del lunes de Carnaval, don Mariano y su señora ocupaban el palco fronterizo al mío... Fué la primera vez que aparecieron juntos en público. Después, ya nunca vimos solo á don Mariano; á ella, sí. Contaban que su mujer le mandaba de tal suerte, que, al salir de casa, le dejaba encerrado...\"},{\"heading\":false,\"text\":\"--¿Y la niña?--preguntó Nozales con afán triste.\"},{\"heading\":false,\"text\":\"--¡Ah!--suspiró la señora.--La niña... me han escrito de allá que murió tísica!...\"}]},{\"title\":\"Sangre del brazo\",\"blocks\":[{\"heading\":false,\"text\":\"El lunes de Pascua de Resurrección, con un sol esplendente y un aire tibio y perfumado, que provocaba impaciencias y fervorines primaverales en los retoños frescos de los árboles y en los senderos que deseaban florecer y donde á las últimas violetas descoloridas hacían competencia las primeras campánulas blancas y las margaritas de rosado cerco,--unieron sus destinos en la capilla del restaurado castillo señorial la linda heredera de la noble casa y estados de Abencerraje, con el apuesto y galán marquesito de Alcalá de los Hidalgos.\"},{\"heading\":false,\"text\":\"Todo sonreía en aquella boda, lo mismo la naturaleza que el porvenir de los desposados. Al cuadro de su juventud, del amor del novio, que revelaban mil finezas y extremos, y á la cándida belleza de la novia, servían de marco de oro y rosas la cuantiosa hacienda, la ilustre cuna, el respeto y cariño de la buena gente campesina, y hasta la venturosa circunstancia de verse enlazadas por ella, ante el cielo y ante el mundo, las dos casas más ricas y nobles de la provincia, las que la representaban en la historia nacional.\"},{\"heading\":false,\"text\":\"A la puerta de la capilla aguardaba el coche familiar que había de conducir á los esposos á la estación del camino de hierro. Iban á emprender uno de esos viajes que son la realidad de un sueño divino: Italia y sus ciudades-museos; Suiza y sus lagos, trozos de la bóveda azul del firmamento caídos sobre la nieve; Alemania con sus ríos, en que las ondinas nadan al rayo de la luna; después el Oriente, Grecia, Constantinopla, y, por último, el invierno en París, entre los prestigios del lujo y la magia de la refinadísima civilización; París con sus fiestas y sus elegancias exquisitas, sus nidos de coquetería y de molicie para la dicha renovada... La perspectiva de tantos días risueños y venturosos; más que todo la del amor puro, noble, legítimo, constante regocijo y secreta y dulce efusión del alma, hacía latir de gozo el corazón de la novia, de la rubia y tierna María de las Azucenas, cuando el coche arrancó al trote largo de los cuatro fogosos caballos que lo arrastraban, llevándosela á ella, al que ya era su dueño, y á la doncella, Luisilla, aldeana viva y fiel, elegida y designada para, acompañar y servir á María durante el viaje...\"},{\"heading\":false,\"text\":\"Por espacio de algunos meses fueron llegando al castillo faustas nuevas de los novios. Aun cuando la escondida aldea de Abencerraje distaba tanto de esas lejanas tierras por donde ellos paseaban la ufanía de su felicidad, por mil no sospechados conductos--cartas, sueltos de periódicos, referencias de otros viajeros, de cónsules, de amigos, de desconocidos quizás--en Abencerraje se sabía confusamente que el viaje era feliz, alegre, fecundo en incidentes gratos, y que marido y mujer disfrutaban de salud y contento. Corrió así el verano, pasóse el otoño, y se averiguó que, cumpliendo estrictamente el programa, se encontraban ya en la capital de la república francesa los marqueses, divertidos, festejados, girando en el torbellino del placer. Hacia Febrero ó Marzo se habló de que la recién casada sufría una grave enfermedad, pero casi se supo al mismo tiempo el mal y la mejoría. Y pocas semanas después, el lunes de Pascua de Resurrección, á la caída de una tarde admirable por lo serena, cuando las últimas violetas descoloridas exhalaban su delicado aroma y los árboles desabrochaban su flor de primavera, el país vió asombrado que el coche familiar regresaba de la estación con mucho repique de cascabeles, y las gentes, que se asomaban curiosas á las puertas de las cabañas, no divisaron dentro del coche más que á María de las Azucenas, tan descolorida como las últimas violetas de los senderos, y á Luisilla, sentada á su lado, también desmejorada y amarillenta, sosteniendo en el hombro la fatigada cabeza de su señora; ambas mudas, ambas tristes, ambas con la huella del padecimiento en el rostro.--Y ni aquel día, ni los siguientes, ni nunca más, asomó el Marqués de Alcalá en el castillo de su mujer, ni por la comarca siquiera, y María y Luisilla vivieron solas, siempre juntas, más que como ama y criada, como hermanas amantísimas é inseparables.\"},{\"heading\":false,\"text\":\"Repicaron las lenguas, y se fantasearon historias de ilícitas pasiones y desvaríos del Marqués, tragedias horribles, duelos, conatos de envenenamiento, y otras mil invenciones novelescas que prueban la ardorosa imaginación de los naturales de Abencerraje. La verdad no se supo hasta que corrieron algunos años, cuando el Marqués de Alcalá comisionó á un sacerdote para lograr de su esposa que le perdonase y consintiese en vivir á su lado. Habiendo fracasado por completo la diplomacia del sacerdote, en los primeros momentos de contrariedad éste se espontaneó con el párroco de Abencerraje, éste con el boticario, éste con el médico, el notario, el Alcalde... y así llegó á conocer la comarca la siguiente aventura.\"},{\"heading\":false,\"text\":\"Después de un viaje que fué un idilio, llegaron á París los enamorados esposos en busca de alguna quietud, pues la reclamaba el estado interesante de María, expuesta á percances en fondas y trenes. A pesar del cuidado y del método que observó la Marquesa, hacia el sexto mes del embarazo cayó en cama, con síntomas de parto prematuro. Acaeció la temida desgracia, y fué lo peor que una hemorragia violenta puso en peligro inminente la vida de la señora. «Se desangra, se nos va», había dicho el médico, un español ilustre, después de ensayar los recursos de su ciencia, luchando denodadamente con la muerte que se aproximaba silenciosa. Y entonces el marido, que veía á su esposa desfallecer en síncope mortal, blanca como la almohada donde apoyaba su frente de cera, preguntó al doctor:\"},{\"heading\":false,\"text\":\"--¿Pero no hay algún medio de salvarla? ¿No hay alguno?\"},{\"heading\":false,\"text\":\"--Hay uno todavía--respondió el médico.--Si se encuentra una persona sana, robusta, joven y que quiera lo bastante á esta señora para dar sangre de las venas de su brazo... verificaremos la transfusión y verá usted á la enferma resucitar.\"},{\"heading\":false,\"text\":\"Al hablar así, el doctor miraba afanosamente al Marqués, clavándole en el rostro, y mejor aún en el espíritu, sus ojos interrogadores y desengañados de hombre que ha presenciado en este pícaro mundo muchas miserias; y al notar que el Marqués no contestaba y se volvía tan pálido como si ya le estuviesen extrayendo de las venas la sangre que le pedía de limosna el amor, el médico se encogió de hombros murmurando vagamente:\"},{\"heading\":false,\"text\":\"--Pero es difícil... muy difícil. Hay que renunciar á esa esperanza.\"},{\"heading\":false,\"text\":\"En aquel punto mismo se levantó una mujer que permanecía acurrucada á los pies del lecho de la moribunda, y sencillamente, presentando su brazo izquierdo desnudo, blanco, grueso, surcado de venas azules, exclamó:\"},{\"heading\":false,\"text\":\"--Ahí tiene, señor... ahí tiene... Sangre no me falta, y sana estoy como las propias manzanas en el árbol... Ahí tiene, y ojalá que la sangre de una pobre aldeana sirva para resucitar á la señora.\"},{\"heading\":false,\"text\":\"Ni un minuto tardó el doctor en aceptar la oferta de Luisilla. Aplicando la cánula, sangró copiosamente el recio brazo, pues se necesitaba mucha, mucha sangre, setecientos gramos, para reparar las pérdidas sufridas. La muchacha, sonriente, no pestañeaba, repitiendo á cada paso:\"},{\"heading\":false,\"text\":\"--Saque, señor; tengo yo la mar de sangre buena que ofrecer á mi ama.\"},{\"heading\":false,\"text\":\"El Marqués había huído de la habitación. Cuando la sutil jeringuilla empezó á inyectar el precioso licor en el cuerpo de la agonizante, y ésta á notar el calor delicioso que de las venas pasaba al corazón reanimándolo; cuando su rostro de mármol se coloreó y sus ojos se abrieron lentamente, lo primero que buscaron fué al amado, á la mitad de su ser, pues había comprendido al revivir que alguien la daba su sangre en compensación de la que había perdido, y creía que sólo podía ser él, el esposo, el compañero, el adorado, el ídolo de su alma. Y al no encontrarle; al ver á Luisa, á quien vendaban y á quien hacían beber, para reanimarla del desfallecimiento, café puro, la esposa comprendió, y volvió á cerrar los ojos, como si aspirase al desmayo del cual solo se despierta en los brazos de la muerte...\"},{\"heading\":false,\"text\":\"Apenas pudo ponerse en camino, María partió sin más compañera que la aldeanita, cuya humilde sangre llevaba en las venas y á quien debía el existir. Todas las gestiones del Marqués de Alcalá se estrellaron contra la invencible repugnancia, ó más bien el horror de su mujer. Demasiado altiva para buscar consuelo de aquel desengaño, vivió con Luisilla, haciendo caridades y llorando á solas muchas veces,--sobre todo en Pascua de Resurrección, cuando la implacable naturaleza reflorecía.\"}]},{\"title\":\"Consuelo\",\"blocks\":[{\"heading\":false,\"text\":\"Teodoro iba á casarse perdidamente enamorado. Su novia y él aprovechaban hasta los segundos para tortolear y apurar esa dulce comunicación que exalta el amor por medio de la esperanza próxima á realizarse. La boda sería en Mayo, si no se atravesaba ningún obstáculo en el camino de la felicidad de los novios. Pero al acercarse la concertada fecha se atravesó uno terrible: Teodoro entró en sorteo de oficiales, y la suerte le fué adversa: le reclamaba la patria.\"},{\"heading\":false,\"text\":\"Ya se sabe lo que ocurre en semejantes ocasiones. La novia sufrió síncopes y ataques de nervios; derramó lágrimas que corrían por sus mejillas frescas, pálidas como hojas de magnolia, ó empapaban el pañolito de encaje; y en los últimos días que Teodoro pudo pasar al lado de su amada, trocáronse juramentos de constancia y se aplazó la dicha para el regreso. Tales fueron los extremos de la novia, que Teodoro marchó con el alma menos triste, regocijado casi por momentos, pues era animoso y no rehuía, ni aun de pensamiento, la aceptación del deber.\"},{\"heading\":false,\"text\":\"Escribió siempre que pudo, y no le faltaron cartas amantes y fervorosas, en contestación á las suyas algo lacónicas, redactadas después de una jornada de horrible fatiga, robando tiempo al descanso, y evitando referir las molestias y las privaciones de la cruel campaña, por no angustiar á la niña ausente. Un amigo á prueba, comisionado para espiar á la novia de Teodoro--no hay hombre que no caiga en estas puerilidades, si se va muy lejos y ama de veras--mandaba noticias de que la muchacha vivía en retraimiento, como una viuda. Al saberlo, Teodoro sentía un gozo que le hacía olvidarse de la ardiente sed, del sol que abrasa, de la fiebre que flota en el aire y de las espinas que desgarran las epidermis.\"},{\"heading\":false,\"text\":\"Cierto día, de espeso matorral salieron algunos disparos al paso de la columna que Teodoro mandaba. Teodoro cerró los ojos y osciló sobre el caballo: le recogieron y trataron de curarle, mientras huía cobardemente el invisible enemigo. Trasladado el herido al hospital, se vió que tenía destrozado el hueso de la pierna,--fractura complicada, gravísima.--El médico dió su fallo: para salvar la vida había que practicar urgentemente la amputación por más arriba de la rótula, advirtiendo que consideraba peligroso dar cloroformo al paciente. Teodoro resistió la operación con los ojos abiertos, y vió cómo el bisturí incindía su piel y resecaba sus músculos, cómo la sierra mordía en el hueso hasta llegar al tuétano, y cómo su pierna derecha, ensangrentada, muerta ya, era llevada á que la enterrasen... Y no exhaló un grito ni un gemido: tan sólo, en el paroxismo del dolor, tronzó con los dientes el cigarro que chupaba.\"},{\"heading\":false,\"text\":\"Según el cirujano, la operación había salido divinamente. No hubo inflamación ni gangrena; cicatrizó bien y pronto, y Teodoro no tardó en ensayar su pierna de palo, una pata vulgar, mientras no podía encargar á Alemania otra, hecha con arreglo á los últimos adelantos...\"},{\"heading\":false,\"text\":\"Al escribir á su novia desde el hospital sólo había hablado de herida, y herida leve. No quería afligirla ni espantarla. Así y todo, lo de la herida alarmó á la muchacha tanto, que sus cartas eran gritos de terror y efusiones de cariño. ¿Por qué no estaba ella allí para asistirle, y acompañarle y endulzar sus torturas? ¿Cómo iba á resistir hasta la carta siguiente, donde él participase su mejoría?\"},{\"heading\":false,\"text\":\"Aquellas páginas tiernas y sencillas, que debían consolar á Teodoro, le causaron, por el contrario, una inquietud profunda. Pensaba á cada instante que iba á regresar, á ver á su adorada, y que ella le vería también... ¡pero cómo! ¡Qué diferencial Ya no era el gallardo oficial de esbelta silueta y andar resuelto y brioso. Era un inválido, un pobrecito inválido, un infeliz inútil. Adiós las marchas, adiós los fogosos caballos, adiós el vals que embriaga, adiós la esgrima que fortalece: tendría que vivir sentado, que pudrirse en la inacción, y que recibir una limosna de amor ó de lástima, otorgada por caridad á su desventura. Y Teodoro, al dar sus primeros pasos apoyado en la muleta, presentía la impresión de su novia cuando él llegase así, cojo y mutilado,--él, el apuesto novio que antes envidiaban las amigas.--Ver la luz de la compasión en unos ojos adorados... ¡qué triste sería, qué triste! Miróse al espejo y comprobó en su rostro las huellas del sufrimiento, y pensó en el ruido seco de la pata de palo sobre las escaleras de la casa de su futura... Con el revés de la mano se arrancó una lágrima de rabia que surgía al canto del lagrimal: pidió papel y pluma, y escribió una breve carta de rompimiento y despedida eterna.\"},{\"heading\":false,\"text\":\"Dos años pasaron. Teodoro había vuelto á la Península, aunque no á la ciudad donde amó y esperó. Por necesidad tuvo que ir á ella pocos días, y aunque evitaba salir á la calle, una tarde encontró de improviso á la que fué su novia y,--sofocado, tembloroso,--se detuvo y la dejó pasar. Iba ella del brazo de un hombre--su marido.--El amputado, repuesto, firme ya sobre su pata hábilmente fabricada en Berlín, maravilla de ortopedia, que disimulaba la cojera y terminaba en brillante bota, notó que el esposo de su amada era ridículamente conformado, muy patituerto, de rodillas huesudas é innoble pie... y una sonrisa de melancólica burla jugó en su semblante grave y varonil.\"}]},{\"title\":\"La novela de Raimundo\",\"blocks\":[{\"heading\":false,\"text\":\"¿Suponéis que no hay en mis recuerdos nada dramático, nada que despierte interés, una novela tremenda?--nos dijo casi ofendido el apacible Raimundo Ariza, á quien considerábamos el muchacho más formal de cuantos remojábamos la persona en aquella tranquila playa y nos reuníamos por las tardes á jugar á tanto módico en el Casino.--No pudimos menos de mirar á Raimundo con sorpresa y algo de incredulidad. Sin embargo, Raimundo no era feo: tenía estatura proporcionada, correctas facciones, ojos garzos y dulces, sonrisa simpática y blanca tez; pero su bonita figura destilaba sosería; no había nacido fascinador; parecía formado por la naturaleza para ser á los cuarenta buen padre de familia, y Alcalde de su pueblo.\"},{\"heading\":false,\"text\":\"--Dudamos de tu novela romántica--exclamó al cabo uno de nosotros.\"},{\"heading\":false,\"text\":\"--Pues es de las de patente...--replicó Raimundo.--Hay dos clases de novelas, señores escépticos: las voluntarias y las involuntarias. Las primeras, las buscan por la mano sus héroes. Las otras... se vienen á las manos. De estas fué la mía. A ciertas personas suele decirse que «_les sucede todo_;» y es porque ellas andan á caza de sucesos... A fe que si se estuviesen quietecitos, las mujeres no se precipitarían á echarles memoriales.\"},{\"heading\":false,\"text\":\"En mi pueblo, como sabéis, no suele haber grandes emociones, y cualquier cosa se vuelve acontecimiento. Todo constituye distracción, rompiendo la monotonía de aquel vivir.--Hará cosa de tres años, en primavera, nos alborotó la llegada de una tribu errante de gitanos ó zíngaros. Plantaron sus negruzcas tiendas y amarraron sus trasijadas monturas en cierto campillo árido, cercano á uno de los barrios en construcción, y formamos costumbre de ir por las tardes á curiosear las fisonomías y los hábitos de tan extraña gente.\"},{\"heading\":false,\"text\":\"Nos gustaba ver cómo remendaban y estañaban calderos y componían jáquimas y pretales, todo al sol y con la cabeza descubierta, porque dentro de las tiendas no se rebullían. Comentábase mucho la noticia de que el jefe de una taifa tan sórdida y desarrapada hubiese depositado en el Banco, el día de su arribo, bastantes miles de duros en ricas onzas españolas, de las que ya no se encuentran por ninguna parte. Viajaban con su caudal, y por no ser desbalijados, al sentar sus reales lo aseguraban así. Se decía también que poseían á docenas soberbias cadenas de oro y joyeles bárbaros de pedrería; pero es la verdad que, al exterior, sólo mostraban miserias, andrajos y densa capa de mugre, no teniendo poco de asombroso que tan mala capa no bastase á encubrir ni á degradar la noble hermosura y pintoresca originalidad de los bohemios que admirábamos.\"},{\"heading\":false,\"text\":\"Resaltaba esta belleza en todos los individuos jóvenes de la tribu; pero, como es natural, yo prefería observarla en las mujeres, y solía acercarme á la tienda donde habitaba una gitanilla del más puro tipo oriental que pueda soñarse. Esbelta, de tez finísima y aceitunada; de ojos de gacela, tristes, almendrados é inmensos; de cabellera azulada á fuerza de negror y repartida en dos trenzas de esterilla á ambos lados del rostro, la gitana estaba reclamando un pintor que se inspirase en su figura. Aunque era, según supe después, esposa del jefe de la tribu, su vestimenta se componía de una falda muy vieja y un casaquín desgarrado, por cuyas roturas salía el seno, y en lugar de los fantásticos joyeles del misterioso tesoro, adornaba su cuello una sarta de corales falsos. Su tierna juventud y su singular beldad resplandecían iluminando los harapos y el interior de la tienda, por otra parte semejante á un capricho de Goya, donde humeaba un pote sobre unas trébedes y un fuego de brasa, atizado por una gitana vieja, tan caracterizada de bruja, que pensé que iba á salir volando á horcajadas sobre una escoba.\"},{\"heading\":false,\"text\":\"Así que me vió la gitanilla, con voz muy melodiosa y con gutural pronunciación extranjera me pidió la mano para echarme la buenaventura. Se la tendí, con dos pesetas para señalar, y después de oídas las profecías que dicen siempre las gitanas, dejé gustoso las dos pesetas en su poder. La mujer hablaba aprisa, porque un chiquillo desnudo, de cobriza tez, arrastrándose por el suelo, lloriqueaba; así que su madre le tomó en brazos, calló agarrando el seno. De súbito la gitana exhaló un chillido de dolor: el crío acababa de morderla cruelmente, y ella, casi en broma, aplicó dos azotes ligeros á la criatura. No sé que fué más pronto, si romper el chico en llanto desconsolador ó entrar en la tienda el jefe de la tribu, un arrogante bohemio de enérgicas facciones y pelo rizado en largos bucles; y sin encomendarse á Dios ni al diablo, profiriendo imprecaciones en su jerigonza, soltarle á su mujer un feroz puntapié que la echó á tierra.\"},{\"heading\":false,\"text\":\"Indignado por tal brutalidad, me precipité á levantarla; se alzó pálida y temblando; sus ojos oblongos, tan dulces poco antes, fulguraban con un brillo sombrío, que me pareció de odio y furor, pero al fijarse en mí destellaron agradecimiento. No lo pude remediar; aunque por sistema con nadie ni en nada me meto, aquella escena me había trastornado: apostrofé é increpé al gitano, y hasta le amenacé, si maltrataba de tal suerte á una criatura indefensa, con denunciarle á la autoridad, que le aplicaría condigno castigo. No sé qué pasaría por dentro del alma del bohemio: sé que me escuchó muy grave, que chapurreó excusas, y al mismo tiempo, á guisa de amo de casa que hace cortesía, me acompañó, sacándome fuera de su domicilio, á pretexto de enseñarme los caballos y los carricoches; en términos que, al despedirme de aquel hombre, me creí en el deber de aflojar otras monedas... que aceptó sin perder la dignidad.\"},{\"heading\":false,\"text\":\"Al día siguiente, y los demás, volví al campamento y fuí derecho á la tienda de la gitana... ¡No arméis alboroto ni me déis broma! Yo no sentía nada parecido á lo que suele llamarse, no ya amor, sino sólo interés ó capricho por una mujer. Quizás por obra de la suciedad salvaje en que vivía envuelta la gitana, ó por el carácter exótico de su hermosura de dieciséis abriles, lo que me inspiraba era una especie de lástima cariñosa unida á un desvío raro: yo no concebía, con tal mujer, sino la contemplación desinteresada y remota que despiertan un cuadro ó un cachivache de museo. A veces me creía inferior á ella, que procedía de raza más pura y noble, de aquel Oriente en que la humanidad tuvo su cuna; otras, por el contrario, se me figuraba un animal bravío, un ser de instinto y de pasión á quien yo dominaba por la inteligencia. Y encontraba gusto en ir á verla, únicamente porque ella, al aparecer yo, mostraba una alegría pueril, una exaltación inexplicable, sonriendo con labios muy rojos y dientes muy blancos, diciéndome palabras zalameras, contándome sus correrías, sus fatigas y sus deseos de regresar á una patria donde el firmamento no tuviese nubes, ni llorase agua jamás. «Feo cuando llueve», repetía. A esto se redujo nuestro idilio... No tengo nada de héroe, y así que noté que el arrogante gitano fruncía las negrísimas y correctas cejas al encontrarme en sus dominios, espacié mis visitas, y ni siquiera me despedí de mi amiga--pues los bohemios levantaron el campo de improviso una mañana, y desaparecieron, sin dejar más huellas de su paso que varios montones de carbón y ceniza en el real, y dos ó tres hurtos de poca monta que se les atribuyeron, quizás falsamente.\"},{\"heading\":false,\"text\":\"Hasta aquí la historia es bien sencilla... Lo novelesco empieza ahora... y consiste en un solo hecho, que ustedes explicarán como gusten... pues yo me lo explico á mi modo, y acaso esté en un error! Al mes de alejarse de mi ciudad la tribu zíngara, se supo por la prensa que en las asperezas de la sierra de los Castros habían descubierto unos pastores el cuerpo de una mujer muy joven, cuyas señas inequívocas coincidían con las de mi gitanilla. El cuerpo había sido enterrado á bastante profundidad, pero venteado por los perros y desenterrado prontamente, dió á la justicia indicios de que se hallaba sobre la pista de un horrendo crimen. Se inició el procedimiento sin resultado alguno, porque los de la errante tribu estuvieron conformes en declarar que la gitanilla había huído separándose de ellos, y que ellos no se habían acercado ni á veinte leguas de la sierra de los Castros. La muerte de la gitanilla fué un negro misterio más, de tantos como no desentraña la justicia nunca. Sólo yo creí ver claro en el lance... Acordéme de las palabras que Cervantes pone en boca del gitano viejo: «Libres y exentos vivimos de la amarga pestilencia de los celos; nosotros somos los jueces y verdugos de nuestras esposas y amigas; con la misma facilidad las matamos y las enterramos por las montañas y desiertos, como si fuesen animales nocivos; no hay pariente que las vengue, ni padres que nos pidan su muerte...»\"}]},{\"title\":\"El encaje roto\",\"blocks\":[{\"heading\":false,\"text\":\"Convidada á la boda de Micaelita Aránguiz con Bernardo de Meneses, y no habiendo podido asistir, grande fué mi sorpresa cuando supe al día siguiente--la ceremonia debía verificarse á las diez de la noche en casa de la novia--que ésta, al pie del mismo altar, al preguntarle el Obispo de San Juan de Acre si recibía á Bernardo por esposo, soltó un _no_ claro y enérgico; y como reiterada con extrañeza la pregunta se repitiese la negativa, el novio, después de arrostrar un cuarto de hora la situación más ridícula del mundo, tuvo que retirarse, deshaciéndose la reunión y el enlace á la vez.\"},{\"heading\":false,\"text\":\"No son inauditos casos tales, y solemos leerlos en los periódicos; pero ocurren entre gente de clase humilde, de muy modesto estado, en esferas donde las conveniencias sociales no embarazan la manifestación franca y espontánea del sentimiento y de la voluntad.\"},{\"heading\":false,\"text\":\"Lo peculiar de la escena provocada por Micaelita, era el medio ambiente en que se desarrolló. Parecíame ver el cuadro, y no podía consolarme de no haberlo contemplado por mis propios ojos. Figurábame el salón atestado, la escogida concurrencia, las señoras vestidas de seda y terciopelo, con collares de pedrería, al brazo la mantilla blanca para tocársela en el momento de la ceremonia; los hombres con resplandecientes placas ó luciendo veneras de Ordenes militares en el delantero del frac; la madre de la novia, ricamente prendida, atareada, solícita, de grupo en grupo, recibiendo felicitaciones; las hermanitas, conmovidas, muy monas, de rosa la mayor, de azul la menor, ostentando los brazaletes de turquesas, regalo del cuñado futuro; el Obispo que ha de bendecir la boda, alternando grave y afablemente, sonriendo, dignándose soltar chanzas urbanas ó discretos elogios, mientras allá en el fondo se adivina el misterio del oratorio revestido de flores, una inundación de rosas blancas, desde el suelo hasta la cupulilla, donde convergen radios de rosas y de lilas como la nieve, sobre rama verde, artísticamente dispuesta; y en el altar, la efigie de la Virgen protectora de la aristocrática mansión, semioculta por una cortina de azahar, el contenido de un departamento lleno de azahar que envió de Valencia el riquísimo propietario Aránguiz, tío y padrino de la novia, que no vino en persona por viejo y achacoso--detalles que corren de boca en boca, calculándose la magnífica herencia que corresponderá á Micaelita, una esperanza más de ventura para el matrimonio, el cual irá á Valencia á pasar su luna de miel.--En un grupo de hombres me representaba al novio, algo nervioso, ligeramente pálido, mordiéndose el bigote sin querer, inclinando la cabeza para contestar á las delicadas bromas y á las frases halagüeñas que le dirigen...\"},{\"heading\":false,\"text\":\"Y por último, veía aparecer en el marco de la puerta que da á las habitaciones interiores una especie de aparición, la novia, cuyas facciones apenas se divisan bajo la nubecilla del tul, y que pasa haciendo crujir la seda de su traje, mientras en su pelo brilla como sembrado de rocío la roca antigua del aderezo nupcial... Y ya la ceremonia se organiza, la pareja avanza conducida por los padrinos, la cándida figura se arrodilla al lado de la esbelta y airosa del novio... Apíñase en primer término la familia, buscando buen sitio para ver amigos y curiosos, y entre el silencio y la respetuosa atención de los circunstantes... el Obispo formula una interrogación, á la cual responde un _no_ seco como un disparo, rotundo como una bala. Y--siempre con la imaginación--notaba el movimiento del novio, que se revuelve herido; el ímpetu de la madre, que se lanza para proteger y amparar á su hija, la insistencia del Obispo, forma de su asombro, el estremecimiento del concurso, el ansia de la pregunta transmitida en un segundo: «¿Qué pasa? ¿Qué hay? ¿La novia se ha puesto mala? ¿Que dice _no_? Imposible... ¿Pero es seguro? ¡Qué episodio!...»\"},{\"heading\":false,\"text\":\"Todo esto, dentro de la vida social, constituye un terrible drama. Y en el caso de Micaelita, al par que drama, fué logogrifo. Nunca llegó á saberse de cierto la causa de la súbita negativa.\"},{\"heading\":false,\"text\":\"Micaelita se limitaba á decir que había cambiado de opinión y que era bien libre y dueña de volverse atrás, aunque fuese al pie del ara, mientras el _sí_ no partiese de sus labios. Los íntimos de la casa se devanaban los sesos, emitiendo suposiciones inverosímiles. Lo indudable era que todos vieron, hasta el momento fatal, a los novios satisfechos y amarteladísimos; y las amiguitas que entraron á admirar á la novia engalanada, minutos antes del escándalo, referían que estaba loca de contento, y tan ilusionada y satisfecha que no se cambiaría por nadie. Datos eran estos para obscurecer más el extraño enigma que por largo tiempo dió pábulo á la murmuración, irritada con el misterio y dispuesta á explicarlo desfavorablemente.\"},{\"heading\":false,\"text\":\"A los tres años,--cuando ya casi nadie iba acordándose del sucedido de las bodas de Micaelita, me la encontré en un balneario de moda donde su madre tomaba las aguas. No hay cosa que facilite las relaciones como la vida de balneario, y la señorita de Aránguiz se hizo tan íntima mía, que una tarde, paseando hacia la iglesia, me reveló su secreto, afirmando que me permite divulgarlo, en la seguridad de que explicación tan sencilla no será creída por nadie.\"},{\"heading\":false,\"text\":\"--Fué la cosa más tonta... De puro tonta no quise decirla; la gente siempre atribuye los sucesos á causas profundas y trascendentales, sin reparar de que á veces nuestro destino lo fijan las niñerías, las _pequeñeces_ más pequeñas... Pero son pequeñeces que significan algo, y para ciertas personas significan demasiado. Verá usted lo que pasó; y no concibo que no se enterase nadie, porque el caso ocurrió allí mismo, delante de todos; sólo que no se fijaron, porque fué, realmente, un decir Jesús.\"},{\"heading\":false,\"text\":\"Ya sabe usted que mi boda con Bernardo de Meneses parecía reunir todas las condiciones y garantías de felicidad. Además, confieso que mi novio me gustaba mucho, más que ningún hombre de los que conocía y conozco; creo que estaba enamorada de él. Lo único que sentía era no poder estudiar su carácter: algunas personas le juzgaban violento; pero yo le veía siempre cortés, deferente, blando como un guante, y recelaba que adoptase apariencias destinadas á engañarme y á encubrir una fiera y avinagrada condición. Maldecía yo mil veces la sujeción de la mujer soltera, para la cual es un imposible seguir los pasos á su novio, ahondar la realidad y obtener informes leales, sinceros hasta la crudeza--los únicos que me tranquilizarían. Intenté someter á varias pruebas á Bernardo, y salió bien de ellas; su conducta fué tan correcta, que llegué á creer que podía fiarle sin temor alguno mi porvenir y mi dicha.\"},{\"heading\":false,\"text\":\"Llegó el día de la boda. A pesar de la natural emoción, al vestirme el traje blanco reparé una vez más en el soberbio volante de encaje que lo adornaba, y era regalo de mi novio. Había pertenecido á su familia aquel viejo Alenzón auténtico, de una tercia de ancho--una maravilla--de un dibujo exquisito, perfectamente conservado, digno del escaparate de un museo. Bernardo me lo había regalado, encareciendo su valor, lo cual llegó á impacientarme, pues por mucho que el encaje valiese, mi futuro debía suponer que era poco para mí.\"},{\"heading\":false,\"text\":\"En aquel momento solemne, al verlo realzado por el denso raso del vestido, me pareció que la delicadísima labor significaba una promesa de ventura, y que su tejido tan frágil y á la vez tan resistente prendía en sutiles mallas dos corazones. Este sueño me fascinaba cuando eché á andar hacia el salón, en cuya puerta me esperaba mi novio. Al precipitarme para saludarle llena de alegría, por última vez antes de pertenecerle en alma y cuerpo, el encaje se enganchó en un hierro de la puerta, con tan mala suerte, que al quererme soltar oí el ruido peculiar del desgarrón, y pude ver que un girón del magnífico adorno colgaba sobre la falda. Sólo que también vi otra cosa: la cara de Bernardo, contraída y desfigurada por el enojo más vivo; sus pupilas chispeantes, su boca entreabierta ya para proferir la reconvención y la injuria... No llegó á tanto, porque se encontró rodeado de gente; pero en aquel instante fugaz se alzó un telón y detrás apareció desnuda un alma.\"},{\"heading\":false,\"text\":\"Debí de inmutarme; por fortuna, el tul de mi velo me cubría el rostro. En mi interior algo crujía y se despedazaba, y el júbilo con que atravesé el umbral del salón se cambió en horror profundo. Bernardo se me aparecía siempre con aquella expresión de ira, dureza y menosprecio que acababa de sorprender en su rostro; esta convicción se apoderó de mí, y con ella vino otra: la de que no podía, la de que no quería entregarme á tal hombre, ni entonces, ni jamás... Y, sin embargo, fui acercándome al altar, me arrodillé, escuché las exhortaciones del Obispo... Pero cuando me preguntaron, la verdad me saltó á los labios, impetuosa, terrible...\"},{\"heading\":false,\"text\":\"Aquel _no_ brotaba sin proponérmelo; me lo decía á mí propia... ¡para que lo oyesen todos!\"},{\"heading\":false,\"text\":\"--¿Y por qué no declaró usted el verdadero motivo, cuando tantos comentarios se hicieron?\"},{\"heading\":false,\"text\":\"--Lo repito: por su misma sencillez... No se hubiesen convencido jamás. Preferí dejar creer que había razones de esas que llaman serias...\"}]},{\"title\":\"Martina\",\"blocks\":[{\"heading\":false,\"text\":\"Hija única de cariñosos padres que la habían criado con blandura, sin un regaño ni un castigo, Martina fué la alegría del honrado hogar donde nació y creció. Cuando se puso de largo, la gente empezó á decir que era bonita, y la madre, llena de inocente vanidad, se esmeró en componerla y adornarla para que resaltase su hermosura virginal y fresca. En el teatro, en los bailes, en el paseo de las tardes de invierno y de las veraniegas noches, Martina, vestida al pico de la moda y con atavíos siempre finos y graciosos, gustaba y rayaba en primera línea entre las señoritas de Marineda. Se alababa también su juicio, su viveza, su agrado, que no era coquetismo, y su alegría, tan natural como el canto en las aves. Una atmósfera de simpatía dulcificaba su vivir. Creía que todos eran buenos, porque todos le hablaban con benevolencia en los ojos y mieles en la boca. Se sentía feliz, pero se prometía para lo futuro dichas mayores, más ricas y profundas, que debían empezar el día en que se enamorase. Ninguno de los caballeretes que revoloteaban en torno de Martina atraídos por la juventud y la buena cara, unidas á no despreciable hacienda, mereció que la muchacha fijase en él las grandes y rientes pupilas arriba de un minuto. Y en ese minuto, más que las prendas y seducciones del caballerete, solía ver Martina sus defectillos, chanceándose luego acerca de ellos con las amigas. Chanzas inofensivas, en que las vírgenes, con malicioso candor, hacen la anatomía de sus pretendientes, obedeciendo á ese instinto de hostilidad burlona que caracteriza el primer período de la juventud.\"},{\"heading\":false,\"text\":\"Así pasaron tres ó cuatro inviernos; en Marineda empezó á susurrarse que Martina era delicada de gusto, que picaba alto y que encontrar su media naranja le sería difícil.\"},{\"heading\":false,\"text\":\"Sin embargo, al aparecer en la ciudad el capitán de artillería Lorenzo Mendoza, conocióse que Martina había recibido plomo en el ala. Lorenzo Mendoza venía de Madrid: era apuesto, cortés, reservado, serio, más bien un poco triste, aunque en sociedad se esforzaba por aparecer ameno y expansivo; su vestir y modales revelaban el hábito de un trato escogido y de un respeto á sí mismo que no degeneraba en fatuidad ni en afectación; sin que presumiese de buen mozo, era en extremo simpática su cara morena, de obscura barba y facciones expresivas. Con todo esto, hay más de lo necesario para sorber el seso á una niña provinciana, hasta sin pretenderlo, como en efecto no lo pretendía Mendoza al principio. Las bromas de los compañeros, la fama de _picar alto_ de Martina y también sus atractivos y gracias, su belleza en plena florescencia entonces, impulsaron á Mendoza á acercársele, á preferir su conversación y, poco á poco, á cortejarla.\"},{\"heading\":false,\"text\":\"El pintor que quisiese trazar una personificación de la dicha pudo tomar á Martina por modelo en aquella época deliciosa en que creía sentir que su sangre circulaba como río de néctar y su corazón se iluminaba como ardiente rubí en la perpetua fiesta de sus esperanzas divinas.\"},{\"heading\":false,\"text\":\"Al ocupar Lorenzo la silla libre al lado de la muchacha, ésta se ponía alternativamente roja y pálida: sus oídos zumbaban, brillaban sus ojos, enfriábanse sus manos de emoción; y á las primeras palabras del capitán, un gozo embriagador fijaba en la boca de Martina una sonrisa como de éxtasis.\"},{\"heading\":false,\"text\":\"Rara vez dejan de provocar envidia estas felicidades, y más cuando no se ocultan, como no ocultaba la suya Martina, que no veía razón para esconder un sentimiento puro y legítimo. Si no fué la envidia, fué la curiosidad la que escudriñó el pasado de Mendoza, como se registra una casa para encontrar un arma oculta y herir con ella. Y averiguóse sin gran esfuerzo--porque casi todo se sabe, aunque se sepa truncado y sin ilación lógica,--que Mendoza, al venirse, había cortado una de esas historias pasionales, borrascosas, largas, complicadas, un imposible adorado y funesto, de esos lazos que obligan á huir á los confines del mundo y que, elásticos á medida de la ausencia, no siempre se rompen por mucho que se estiren. Con la falta de penetración que caracteriza al vulgo, opinaban los curiosos de Marineda que Mendoza habría olvidado inmediatamente á su tirana, la cual, sobre costarle desazones y amarguras sin cuento, ni era niña ni hermosa. Al lado de aquel capullo, de aquella Martina cándida y radiante como un amanecer y que llevaba en sus lindas manos un caudal, ¿qué podía echar de menos el bizarro capitán de artillería?\"},{\"heading\":false,\"text\":\"Así y todo, almas caritativas se deleitaron en enterar de la historia vieja al padre de Martina, seguros de que él, solícito é inquieto, á su hija se lo había de contar. No se equivocaban: una noche, en el paseo del terraplén, á la hora en que la salitrosa brisa del mar refresca el rostro y vigoriza el ánimo, y en que la música militar, sonora y vibrante, cubre la voz y sólo permite el cuchicheo íntimo y dulce de los enamorados, Martina preguntó lealmente, y Lorenzo contestó turbado y sombrío... ¿Quién se lo había dicho?... Tonterías. Eran cosas pasadas, bien pasadas; muertas y bien muertas. Mendoza no comprendía ni por qué las recordaba nadie ni á santo de qué las sacaba á relucir Martina... Y ella, alzando los ojos llenos de lágrimas y relucientes de pasión, sonriendo de aquel modo extático, olvidando el lugar donde se encontraba, murmuró hondamente: «No me he de casar con otro sino contigo, y me parece justo saber si hay algo que lo estorbe». Conmovido, sin darse cuenta de lo que hacía, Mendoza se inclinó, y buscando disimuladamente la mano de la muchacha, y estrechándola con apretón furtivo entre el remolino de los paseantes, que encubre tales expansiones, la murmuró al oído:\"},{\"heading\":false,\"text\":\"--Pues no hay nada... y por mí que sea prontito... ¡Te quiero!\"},{\"heading\":false,\"text\":\"Al acabar la frase Mendoza, Martina se volvió hacia su padre, que venía detrás, exclamando:\"},{\"heading\":false,\"text\":\"--No estoy bien... Llévame á sentarme... ¡El brazo!\"},{\"heading\":false,\"text\":\"Pronto se repuso, porque la alegría puede trastornar, pero hace daño rara vez: y de allí á dos semanas, la boda de Martina y de Mendoza era noticia oficial, y se sabía el encargo del equipo y galas, y se discutía el mobiliario y alojamiento de los novios.\"},{\"heading\":false,\"text\":\"Se fijó la ceremonia para fines de Septiembre. ¿Qué falta hacía esperar? El amor que está en sazón debe cogerse, como la fruta madura. Iban llegando cajones con ropa blanca, trajes de seda, capotitas, estuches de joyas: en la sala de los padres de Martina servía de escaparate ancha mesa; amigas y amigos venían, contemplaban, aprobaban, censuraban y salían contentos, displicentes ó taciturnos, según su carácter más ó menos generoso. Martina, todas las mañanas, arrancaba triunfalmente una hoja del calendario, cortado ya por la fecha de la boda. ¡Qué pocas hojas faltan! ¡Diez... ocho... una semanita no más! Este domingo es el último de soltera... Cuatro días... Mañana... Sí, mañana á las ocho; ahí están el vestido blanco, los guantes blancos, el abanico, el azahar que llegó de Valencia y que embalsama el ambiente. Lorenzo venía por las noches á hacer tertulia á su novia y se mostraba galán, aunque siempre grave.\"},{\"heading\":false,\"text\":\"La víspera de la boda, Martina le esperaba, como de costumbre, en el gabinetillo. La madre, que vigilaba sus coloquios, no creyó que aquella noche fuese preciso hacer centinela: ocupada en quehaceres múltiples, dejó sola á su hija. Y Martina, en vez de alegrarse, sintió de pronto una pena agobiadora, inmensa, una desolación sin límites, un miedo horrible á algo que no se explicaba, ni se fundaba en nada racional. Tardaba ya Mendoza. Sonó la campanilla, y por instinto Martina se lanzó á la escalera. El criado la presentó una carta que acababa de traer «el asistente del señorito». ¡Una carta! Las piernas de Martina parecían de algodón: creyó que nunca podría andar el trecho que separaba la antesala del gabinete. Se acercó á la lámpara, rompió el sobre, leyó... Antes que sus ojos la había leído su corazón, fiel zahorí.\"},{\"heading\":false,\"text\":\"Aquellas excusas, aquellas forzadas frases de cariño, aquellas mentiras con que se pretendía paliar la infame deserción, las presentía Martina desde una hora antes. Y los motivos de la repentina marcha, bien sabía Martina que no eran los que fingía la carta, sino otros, que no podían decirse, pero que explicaban á la vez el viaje y la continua tristeza, invencible, misteriosa, de su futuro... Llamábale otra vez el abismo; resucitaba lo que sin duda no había muerto. Martina cayó desplomada en el sofá: no lloraba: gemía bajito, como quien reprime la queja de mortal dolor. Sin embargo, la misma violencia del golpe; la indignación,--mil sentimientos confusos,--la impulsaron á levantarse, tomar un fósforo, pegar fuego á la carta, abrir la ventana y echar á volar las cenizas, cual si temiera que la delatasen. Buscando luego á sus padres, les declaró con voz firme y serena que había renunciado, por su gusto y deliberadamente, á casarse con Lorenzo Mendoza, al cual no volverían á ver más, porque salía aquella noche en el tren correo hacia Madrid.\"},{\"heading\":false,\"text\":\"Poseían los padres de Martina una casa de campo no muy distante de la ciudad, y en ella se ocultaron con su hija, para dejar disiparse la primer polvareda de la deshecha boda. Allí pasaron el invierno; Martina parecía contenta. La hablaron de viajes á la corte, al extranjero: rechazó la idea con disgusto. Vino la primavera y ya no pensaron en dejar la residencia campestre. Al acercarse el otro invierno preguntaron á Martina, y pidió, por favor, encarecidamente, un año más de soledad. La misma escena se repitió al siguiente; los padres empezaban á impacientarse: les parecía que ya era hora de que su hija volviese al mundo y se le buscase otro novio formal y auténtico, que borrase de su memoria lo pasado. Mas en esto aconteció que enfermaron los viejos, y con distancia de pocos días sé los llevó al sepulcro, al padre una fiebre reumática, y á la madre un inveterado padecimiento del corazón. Martina, sola ya, de luto riguroso, negóse á recibir pésames, á admitir consuelos de amigas, y se encerró más que nunca entre las paredes de su tapia, y entre los árboles de su solitaria finca. Corrió algún tiempo. En Marineda ya apenas se hablaba de Martina. Los más la creían maniática. No la trataba nadie.\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"Una tarde golpeó el aldabón de la portalada un jinete, que regía un caballejo castaño. El hortelano salió á abrir, y contestó la frase sacramental: la señora no estaba, y además no acostumbraba admitir visitas.\"},{\"heading\":false,\"text\":\"--Dígale usted--objetó el jinete apeándose--¡que es D. Lorenzo Mendoza!... Puede ser que entonces...\"},{\"heading\":false,\"text\":\"A los diez minutos volvía el hortelano con respuesta negativa, terminante. Mendoza bajó la cabeza é hizo ademán de volver á montar. De pronto, como si variase de parecer y obedeciese á una inspiración súbita, arrollando al hortelano, cruzó la puerta, se metió patio adentro, subió una escalera exterior tapizada de madreselvas, que daba acceso á la casa, y entró en una sala obscura, de vidrieras entornadas, silenciosa. Oyó un grito de mujer; fué derecho á donde sonaba y estrechó á Martina en los brazos. No hubo palabras: todo se expresó con halagos, inarticulados sones, caricias insensatas por parte de él, primero rechazadas débilmente y pagadas luego. Después vinieron las excusas, los ruegos, las explicaciones que Mendoza dió casi de rodillas, y ella oyó trémula, desfallecida, reclinada la cabeza en el hombro del suplicante. Y siguieron las promesas, los juramentos, las protestas de enmienda y lealtad, los plazos de ventura que Mendoza desarrollaba risueño, enclavijando sus dedos en los de Martina, que no oponían resistencia. La noche caía; la luna llena se alzaba blanca y apacible; las madreselvas exhalaban su balsámico aroma. Los antiguos novios eran ya amantes; la primavera se trocaba en estío; y el enajenado Mendoza no echó de ver que Martina, en medio de su delirio, á veces gemía muy bajo, como quien reprime la queja de mortal dolor--como había gemido años antes al recibir la carta de despedida.\"},{\"heading\":false,\"text\":\"A la mañana siguiente, cuando despertó Mendoza, no vió á Martina: la llamó á voces, y no contestó nadie. Por fin acudieron los criados; sabían que su ama se había marchado tempranito, pero ignoraban adonde...\"},{\"heading\":false,\"text\":\"En Marineda se supo sin asombro, á la semana siguiente, que Martina vivía reclusa, como _señora de piso_, en un convento de Compostela. Lo que nunca se divulgó fué que hubiese adoptado tal resolución por evitar el sonrojo de sentirse morir de felicidad cerca de _aquél_ que un día la engañó y vendió.\"}]},{\"title\":\"Apólogo\",\"blocks\":[{\"heading\":false,\"text\":\"Habíase enamorado Vicente de Laura oyéndola cantar una opereta en que desempeñaba, con donaire delicioso, un papel entre cómico y patético. La natural hermosura de la cantante parecía mayor, realzada por atavío caprichoso y original, al reflejo de las candilejas, que jugueteaba en la tostada venturina de sus ondeantes y sueltos cabellos, flotantes hasta más abajo de la rodilla. Hallábase Laura en esos primeros años felices de la profesión en que un nombre, después de hacerse conocido, llega á ser célebre; esos años en que la chispita de luz se convierte en astro, y los homenajes, las contratas, los ramilletes, las joyas, los retratos en publicaciones ilustradas, los artículos elogiosos, caldeados por el entusiasmo, llueven sobre la artista lírica, halagando su vanidad, exaltando su amor propio y haciéndola soñar con la gloria. ¿Por qué entre el enjambre de adoradores que zumbaba á su alrededor Laura distinguió á Vicente, escogió á Vicente, oficial que no poseía más que su espada y un apellido, eso sí, muy ilustre: el sonoro apellido hispano-árabe de Alcántara Zegrí?.\"},{\"heading\":false,\"text\":\"Lo cierto es que la elección de Laura fué muy perjudicial á su tranquilidad y dicha. Vicente Zegrí, como le llamaban sus amigos, por atavismo y tradiciones de raza llevaba en la sangre el virus corrosivo de los celos; y si esta enfermedad moral hace estragos donde quiera que aparece, no pueden calcularse sus consecuencias en hombre que ama á mujer de profesión artística, cuyas gracias, en cierto modo, tiene derecho el publico á usufructuar. Antes anduvo Vicente rabioso que gozoso; tragó la hiel cuando aún no gustara la miel, y nunca recibió el divino premio de los halagos de la amada, sin que se lo amargasen con amargor de muerte negras sospechas, infames imaginaciones y desesperados recelos. Tanto pudo con él esta fatiga y desazón celosa, que un día--ó, para no faltar á la verdad, una noche en que á la salida del teatro había acompañado á Laura--ya no acertó á reprimirse, y abrió su corazón, mostrando lo profundo de la llaga.\"},{\"heading\":false,\"text\":\"--Mi sufrimiento es tal--declaró estrujando las manos de su amiga, en aquel momento heladas de terror--que necesito echar por la calle de en medio, realizar una acción decisiva: á seguir así, me volvería loco, y haga lo que haga, quiero hacerlo estando cuerdo, poseyendo la conciencia de mis actos. Cuando te aplauden, siento impulsos de prender fuego al teatro; cuanto se te llena de necios y de osados el _camerino_, se me ocurre sacar la espada y entrar pegando tajos á diestro y siniestro. La tentación es tan fuerte, que por no ceder á ella suelo marcharme á mi casa; pero como me conozco y sé que tarde ó temprano cedería, prefiero consultarte, confesarme contigo, á ver si entre los dos discurrimos modo de salvarnos.\"},{\"heading\":false,\"text\":\"Laura miraba fijamente al oficial, notando con profundo estremecimiento el brillo siniestro de sus pupilas, el temblor involuntario de sus labios cárdenos, lo fruncido de sus cejas, la crispación de sus dedos, la alteración de su voz; y con dulce sonrisa y acento que chorreaba ternura, le preguntó, entre un intento de caricia que rehuyó el celoso:\"},{\"heading\":false,\"text\":\"--¿Y qué has pensado hacer, Vicente mío? Ya que discutimos amigablemente, dímelo sin reparo y te contestaré con franqueza.\"},{\"heading\":false,\"text\":\"--¡He pensado que nos casemos, que seas mi esposa!--declaró Zegrí.\"},{\"heading\":false,\"text\":\"--¿Y que yo... renuncie al arte?\"},{\"heading\":false,\"text\":\"--¡Pues si no renunciases, bonito negocio!--exclamó el enamorado con exaltada vehemencia.--¿Te habrás figurado otra cosa, eh? Desde el momento en que Vicente Zegrí se llame tu marido, á tu marido pertenecerás, y él y sólo él podrá contemplar tus hechizos, oir tu canto y ver desatada esta cabellera.--Al hablar así agarró la profusa mata de pelo, sacudiéndola con furor apasionado.\"},{\"heading\":false,\"text\":\"Púsose Laura más blanca que los encajes de su bata de seda; el tirón había dolido; pero ni la sonrisa se apartó de sus labios, ni un punto cambió la lánguida y acariciadora expresión de sus ojos. Dirigiéndose á Vicente con reposo y dulzura, le interrogó:\"},{\"heading\":false,\"text\":\"--¿Me permites que te cuente un cuento oriental? Me lo refirieron allá en Rusia, donde he cantado hace dos inviernos, y donde tienen muchas ganas de que vuelva una temporadita.\"},{\"heading\":false,\"text\":\"Pasándose la mano por la frente como para espantar una pesadilla, Vicente hizo con la cabeza señal de que estaba dispuesto á oir.\"},{\"heading\":false,\"text\":\"--Parece--empezó Laura--que hubo en Rusia, no sé en qué siglo, un Rey muy malo y feroz, á quien le pusieron por sus desafueros y tiranías el sobrenombre de _Iván el Terrible_. Aunque con Dios no debía de estar muy á bien, el caso es que se le ocurrió construir una catedral magnífica, dedicada á un santo que allí le llaman _Vassili Blagennoi_, lo cual significa _el Bienaventurado Basilio_...\"},{\"heading\":false,\"text\":\"--¿Y qué tiene que ver...?--murmuró Vicente, no sin impaciencia.\"},{\"heading\":false,\"text\":\"--¡Aguarda, aguarda...! El Rey buscó mucho tiempo arquitecto capaz de comprender toda la suntuosidad y grandeza que él deseaba para la catedral, hasta que por fin se presentó uno con un plano asombroso, que dejó al Rey encantado. Elevóse el templo, y fué pasmo y admiración de todos; y el Rey, contentísimo, colmó de regalos y de honores y distinciones al arquitecto.--Un día, terminadas las obras, le llamó á palacio y le preguntó si se creía capaz de erigir otro templo tan magnífico y sorprendente como aquél. El arquitecto, lisonjeado, respondió que sí, y que hasta esperaba idear nuevo edificio que superase al primero en belleza y esplendor. Entonces el bárbaro del Rey, sirviéndose del agudo chuzo de hierro que llevaba siempre á la cintura, le vació al pobre arquitecto los dos ojos uno tras otro, á fin de que jamás pudiese construir para nadie un templo...\"},{\"heading\":false,\"text\":\"Laura calló, y Vicente Zegrí, que acababa de comprender la moraleja del apólogo, la miró con una especie de estravío. Ligera espuma asomó al canto de su boca, y por sus venas serpeó el frío sutil del aura epiléptica, que incita al crimen. Dominándose con esfuerzo supremo se incorporó, dispuesto á marcharse, y articuló pausadamente mientras recogía su airosa capa española:\"},{\"heading\":false,\"text\":\"--Ese Rey hizo mal. Sacar los ojos es acción propia de un verdugo. Si quería inutilizar al arquitecto, debió matarle.\"},{\"heading\":false,\"text\":\"Diciendo así, con súbito impulso se acercó Vicente á Laura, la rodeó con los brazos, y tan violentamente la apretó, de tan insensato modo, incrustándole tan reciamente los dedos en las costillas, que la artista exhaló un grito de miedo, un chillido que salía del fondo de su ser, de esos que sólo dicta el instinto de conservación, el horror á la nada y al sepulcro. Al oir el grito, Vicente la soltó, embozóse en su capa y salió tropezando con las paredes.\"},{\"heading\":false,\"text\":\"Pasóse lo que faltaba hasta el amanecer vagando por las calles, en un estado tan horrible, que dos ó tres veces se recostó en una puerta para llorar. El día que siguió á aquella noche no fue menos cruel. Escribió á Laura cien cartas, que desgarraba después con furia; adoptó y desechó mil planes contradictorios; pensó en echarse de rodillas, en suicidarse, en abrasar el barrio, en secuestrar á su amada á viva fuerza, y, por último, la idea de la muerte fué la que se esculpió en su espíritu con relieve poderoso. Su alma pedía sangre, hierro y fuego, violencia, destrozo y aniquilamiento; el instinto anárquico que tantas veces acompaña al amor, se alzaba rugiente y desatado como racha de huracán. Ya ni siquiera intentaba Vicente recobrar la razón, la cordura y el aplomo: las imágenes suscitadas por los celos, Laura atrayendo á sí los ojos de tantos hombres, que se recreaban en sus gracias y picardías, que bebían su voz, que la admiraban con el cabello suelto, eran flechas de llama que le desatinaban, como al toro la ardiente banderilla. Ni aun creía amar á Laura: la consideraba una enemiga mortal. Figurábase por momentos que la odiaba con toda su voluntad iracunda, y este odio clamaba por saciarse y gozarse en la destrucción.\"},{\"heading\":false,\"text\":\"Llegada la hora de ir al teatro, donde cantaba Laura una de las operetas en que estaba más linda y recogía más aplausos, Vicente, resuelto, algo aliviado por la decisión fiera, concreta, irrevocable, se echó al bolsillo el revólver. Si sufría demasiado... allí tenía el remedio. Ya habían alzado el telón, pero no aparecía Laura; y Vicente, abstraído en su frenesí, hubo de notar por fin que la gente profería exclamaciones de descontento y que la función no era la anunciada, la que Laura debía representar. Alarmado, antes de terminarse el acto dejó su asiento, corrió á informarse entre bastidores... Aquella mañana misma, la cantante había rescindido su contrata perdiendo lo que quiso el empresario, y partido en dirección á San Petersburgo.\"}]},{\"title\":\"A secreto agravio\",\"blocks\":[{\"heading\":false,\"text\":\"Aquella tienda de ultramarinos de la calle Mayor regocijaba los ojos y era orgullo de los moradores de la ciudad, quienes, después de mostrar á los forasteros sus dos o tres monumentos románicos y sus Docks, no dejaban de añadir: «Fíjese usted en el establecimiento de Riopardo, que compite con los mejores del extranjero.»\"},{\"heading\":false,\"text\":\"Y competía. Los amplios vidrios; los escaparates de blanco mármol; las relucientes balanzas; los grifos de dorado latón; el artesonado techo; las banquetas forradas de rico terciopelo verde de Utrecht; las brillantes latas de conservas formando pirámides; las piñas y plátanos maduros en trofeo; las baterías de botellas de licor, de formas raras y charoladas etiquetas, todo alumbrado por racimos de bombillas eléctricas, hacían del establecimiento un suntuoso palacio de la golosina. Así como en Madrid salen las señoras á revolver trapos, en la apacible capital de provincia salían «á ver qué tiene Riopardo de nuevo.» Riopardo sustituía al teatro y á otros goces de la civilización; y los turrones y los quesos y los higos de Esmirna eran el pecadillo dulce de las pacíficas amas de casa y sus sedentarios maridos, por lo cual no faltaban censores mal humorados y flatulentos que acusasen á Riopardo de haber corrompido las costumbres y trocado la patriarcal sencillez de las comidas en fausto babilónico...\"},{\"heading\":false,\"text\":\"Entretanto, el establecimiento medraba, y Riopardo, moreno, afeitado, lucio, adquiría ese aplomo que acompaña á la prosperidad. Los negocios iban como una seda, y esperaba morir capitalista, á semejanza de otros negociantes de la misma plaza que habían tenido comienzos más humildes aún... Hoy convenía trabajar, aprovechando el vigor de los treinta años y la salud férrea. De día, desde las seis de la mañana, al pie del cañón, haciendo limpiar y asear, pesando, despachando, cobrando; de noche, compulsando registros, copiando facturas, contestando cartas... y así, sin descanso ni más intervalo que el de algún corto viaje á Barcelona y Madrid.\"},{\"heading\":false,\"text\":\"De uno de éstos volvió casado Riopardo; su mujer, linda muchacha, hija de un perfumista, apareció en la tienda desde el primer día, ayudando en el despacho á su marido y al dependiente. La cara juvenil y la fina habla castellana de María fueron otro aliciente más para la clientela. Sin ser activa ni laboriosa como su esposo, María era zalamera y solícita y daba gozo verla, bien ceñida de corsé, muy fosca de peinado, cortar con su blanca manecita de afilados dedos una rebanada de Gruyère ó una serie de rajas de salchichón, sutiles como hostias, pesarlas pulcramente y envolverlas en papeles de seda atados con cinta azul. La tienda sonreía, animada por el revuelo de unas faldas ligeras, y nadie como María para aplacar á una parroquiana descontenta, para halagar á un parroquiano exigente, para regalar un cromo á un niño ó deslizar un puñado de dátiles en el delantal de una cocinera gruñona...\"},{\"heading\":false,\"text\":\"El ejemplo de María, su atractivo, su complacencia, habían influído en el dependiente Germán. Mientras estuvo solo con Riopardo, Germán era hosco, indiferente y torpe; no se mudaba, no se rasuraba. María le arregló el cuarto--porque Germán vivía con sus patrones en el piso principal--le surtió de buen lavabo, de toallas; le repasó la ropa blanca y le compró cuellos y puños, con lo cual el dependiente sacó á luz su figura adamada, su rubio pelo rizado con gracia sobre la sien, y las criadas y las mismas señoras compraron de mejor gana en el establecimiento, que al fin las cosas de comer gusta recibirlas de gente aseada, moza y no fea... «También se come con la vista», solían decir.\"},{\"heading\":false,\"text\":\"Una tarde, casi anochecido, Riopardo, volviendo de arreglar asuntos urgentes en la Aduana, prefirió entrar en su casa por la puerta trasera, que caía á la Marina, ahorrándose así diez minutos de callejeo inútil, pues era, á fuer de hombre de acción, avaro de tiempo. Tenía en el bolsillo el llavín: abrió, salvó un pasadizo, y empujó la puerta del almacén, que cedió sin rechinar. El almacén, atestado de latas de petróleo, bocoyes de aguardiente y aceite, y sacas de arroz y harina, estaba á obscuras, y allá á su extremidad, Riopardo creyó percibir un cuchicheo ahogado y suave. Se detuvo, resguardado por una gran barrica, y miró. Al pronto no se ve nada, viniendo de fuera, cuando la luz es poca; pero á los tres minutos, la vista se acostumbra, y algo se percibe. Riopardo logró distinguir dos personas. De pronto, una de ellas, Germán, dijo en alta voz: «Está alguien en la tienda.» Y el modo de separarse, brusco, azorado, fué más inequívoco aún que la proximidad de los dos bultos...\"},{\"heading\":false,\"text\":\"Retrocedió Riopardo: salió por donde había entrado, y sin cuidarse ya de economizar tiempo penetró por la tienda en su casa. Cerróse ésta á la hora habitual; cenaron los tres, marido, mujer y dependiente, y se recogieron en paz á sus respectivos dormitorios los dos últimos. Riopardo volvió á bajar: era el momento de repasar cuentas y manejar libros. Llevaba su linterna sorda que le servía para registrar el almacén, en previsión de un incendio; y ya dentro del vasto recinto, empezó por atrancar la puerta que daba al pasadizo, y probar los cerrojos de la que con la tienda comunicaba.\"},{\"heading\":false,\"text\":\"Después, entregóse á una faena extraña: abrió un centenar de latas de petróleo y las inclinó para que el mineral corriese por el suelo; en seguida, ensopando una gran escoba en los charcos que se formaban, barnizó bien un punto determinado del techo, rociándolo de continuo con hisopazos fuertes. De un rincón trajo brazados de paja, papeles y astillas--residuos de los embalajes de las botellas--y los hacinó hasta formar una pirámide, que con ayuda de una escalera subió á la altura de las vigas del techo, en el mismo punto en que las había untado de petróleo. Hecho esto, siguió destapando latas y dió la vuelta al grifo de un inmenso barril de alcohol. El trajín había sido largo; Riopardo sentía que un sudor helado brotaba de sus cabellos. Descansó un instante y miró el reloj: era la una menos cuarto. Entonces se descalzó, abrió la puerta exterior dejándola arrimada, subió furtivamente la escalera y no paró hasta su alcoba. María dormía ó aparentaba dormir serenamente. La alcoba no tenía ventana. Riopardo, con maravilloso silencio, colocó delante de la vidriera sillas, butacas, ropas, un cofre, cuantos objetos pudo trasladar sin hacer ruido.\"},{\"heading\":false,\"text\":\"Retiróse, y al salir echó por fuera cerrojo y llave á la puerta del gabinete que comunicaba con la alcoba. Descendió otra vez á la tienda, metióse en el almacén, raspó un fósforo, encendió una mecha corta y la aplicó al suelo encharcado de aceite mineral. La llamarada súbita que se alzó le chamuscó pestañas y cabello. Sólo tuvo tiempo de huir á la tienda. El almacén no tardaría tres minutos en ser un brasero enorme.\"},{\"heading\":false,\"text\":\"El marido, con flema, se calzó, se limpió las manos y subió pisando recio. Golpeó á la puerta del dormitorio de Germán, que salió medio desnudo, despavorido. «Creo que hay fuego... Huele á humo... Baje usted... ¡No, antes de pedir socorro hay que cerciorarse!» Germán se precipitó sin más ropa que unos pantalones vestidos á escape y babuchas. Mal despierto aún del primer sueño de los veinte años, casi no comprendía lo que pasaba. Le precedía, Riopardo con la indispensable linterna.\"},{\"heading\":false,\"text\":\"Tienda y portal estaban ya llenos de un humo acre, asfixiante. «Pase usted, mire á ver dónde es...» Titubeaba el dependiente, ciego y atónito; Riopardo le empujó, le precipitó, ya sin disimular, dentro del horno, y aún tuvo fuerzas para correr los cerrojos y huir, saliendo al portal y á la calle. En ella respiró con delicia, cerciorándose de que por allí no andaba el sereno, ni pasaba nadie, y probablemente sucedería lo mismo durante el cuarto de hora necesario...\"},{\"heading\":false,\"text\":\"Sin embargo, á los diez minutos el humo era tal que, temeroso de ver abrirse ventanas y oir voces de socorro, el mismo Riopardo gritó. Al llegar los primeros auxilios, la casa, sobre todo el bajo y principal, no formaban más que una hoguera. Se atendió á aislar las casas vecinas y á salvar con escalas á los inquilinos del segundo y tercero. La fatalidad--observaron las gentes--quiso que el fuego se iniciase en la parte del almacén que correspondía con el dormitorio de la esposa de Riopardo, la cual, asfixiada por el humo, ni pudo levantarse á pedir socorro. Apareció carbonizada, lo mismo que el dependiente, presunto reo de imprudencia temeraria por fumar en el almacén.\"},{\"heading\":false,\"text\":\"No estando aseguradas las existencias del establecimiento, sobre el dueño no recayeron sospechas, sino gran lástima. Arruinado completamente, no faltó quien, estimando sus cualidades mercantiles, su laboriosidad, le adelantase dinero para abrir otra lonja; pero Riopardo dice tristemente á su antigua y fiel clientela:\"},{\"heading\":false,\"text\":\"--Ya no tengo ilusión... ¡Una esposa y un dependiente como los que perdí, no he de encontrarlos nunca!\"}]},{\"title\":\"La religión de Gonzalo\",\"blocks\":[{\"heading\":false,\"text\":\"¿Y qué tal tu marido?--preguntó Rosalía á su amiga de la niñez Beatriz Córdoba, aprovechando el momento de intimidad y confianza que crea entre dos personas la atmósfera común, tibia de alientos y saturada de ligeros perfumes, de una berlina bien cerrada, bien acolchada, rodando por las desiertas calles del Retiro á las once de una espléndida y glacial mañana de Diciembre.\"},{\"heading\":false,\"text\":\"--¿Mi marido?--contestó Beatriz marcando sorpresa, porque creía que su completa felicidad debía leerse en la cara.--¿Mi marido? ¿No me ves? ¡Otro así...! Por la de nadie cambiaría yo mi suerte...\"},{\"heading\":false,\"text\":\"Rosalía hizo un gestecillo, el mohín de instinto malévolo con que los mejores amigos acogen la exhibición de la ajena dicha, y murmuró impaciente:\"},{\"heading\":false,\"text\":\"--Mira, yo no te pregunto de interioridades. No soy tan indiscreta... Me refería á las ideas religiosas... ¿No te acuerdas?... ¡Gonzalo era... así... de la cáscara amarga, vamos!\"},{\"heading\":false,\"text\":\"Beatriz guardó silencio algunos instantes; y después, como si se resolviese á completas revelaciones, de esas que hacemos más por oirnos á nosotros mismos que porque un amigo las escuche, se volvió hacia su compañera de encierro, y alzando el velito á la altura de la nariz para emitir libremente la voz, habló aprisa:\"},{\"heading\":false,\"text\":\"--¡La irreligiosidad de Gonzalo! ¿Y si te dijese que por ella estuvimos á punto de no casarnos nunca? La pura verdad. Tú ya sabes que Gonzalo es mi primo, y mi familia y la suya siempre soñaron con hacer la boda, hasta que la mala reputación de Gonzalo en materias religiosas desbarató por completo el proyecto. Bien conociste á la pobre mamá, y no extrañarás si te digo que llegó al extremo de cerrarle la puerta á Gonzalo á piedra y lodo; vino diez veces lo menos, ¡y siempre habíamos salido! «Reconozco--decía mamá--que mi sobrino es muy simpático, que ha recibido una educación escogida, que posee una ilustración más que mediana; no puedo negar su hermosa figura, ni su clara inteligencia, ni su caballerosidad; tiene mi sangre, no le faltan bienes de fortuna... pero me horroriza pensar que no cree en nada, y ni se toma el trabajo de disimularlo. Malo es padecer desvaríos del alma y peor no ocultarlos siquiera.» Al escuchar estas cosas, yo salía á la defensa de Gonzalo; no me era posible dejar de quererle... un poco... es decir ¡mucho! Francamente, le seguía queriendo, incapaz de olvidar los tiempos en que le consideraba mi novio. Mamá notó de qué pie cojeaba su hija, y, para desimpresionarme, arregló mis bodas con Leoncio Díaz Saravia, el que ahora es subsecretario de Gobernación; era muchacho de valía, y se le presentaba un porvenir brillante; pero así y todo, yo no estaba entusiasmada: á lo sumo me resignaba, sin frío ni calor, al casamiento. ¡Somos tan raros! Lo único que me prestaba cierta tranquilidad, lo que me daba fuerzas cuando sentía sobre mí el peso abrumador de una tristeza involuntaria, era la voz que corría de que Gonzalo no quería amores, de que había resuelto no casarse jamás. «Eso lo hace por mí, por mi recuerdo», pensaba yo; y me consolaba al pensarlo.\"},{\"heading\":false,\"text\":\"--El que no se consuela...--murmuró sonriendo Rosalía, mientras alisaba con repetidos pases la blanda y densa piel de su manguito.\"},{\"heading\":false,\"text\":\"--Un día... no, una noche, porque estábamos en el teatro cuando nos enteramos... cundió la noticia de que Gonzalo, en un café, la había emprendido á bofetadas con un sujeto, y que se encontraban desafiados; lance serio, en condiciones de las que ya no se estilan, á quedar uno sobre el terreno... ¿Causa del conflicto? Voz unánime: «Una mujer.» El mismo Gonzalo lo confesaba, según decían los bien informados: tratábase de una señora, insultada delante de Gonzalo, y cuya defensa había tomado éste hiriendo el rostro del villano ofensor... ¡Lo que yo sentí! ¡En qué estado volví á casa! ¡Qué noche pasé, querida Rosalía! Es lo que no puede pintarse... Aparte del terror de que matasen á Gonzalo, otra cosa me encendía la sangre y me atirantaba los nervios...\"},{\"heading\":false,\"text\":\"--¿Los celos?--preguntó Rosalía con malicia gozosa.\"},{\"heading\":false,\"text\":\"--¿Quién lo duda?--Figúrate que se venían á tierra todas mis ilusiones. Que Gonzalo no me quisiese, pase, y era mucho pasar; pero que quisiese á otra tanto, hasta abofetear á la gente, hasta jugarse la vida... Yo había estado soñando por lo visto... ¡soñando como una necia! Mi novio de los primeros años, mi oculto anhelo de siempre, ni se ocupaba de mí; por otra iba á cruzar la espada, por otra á quien secretamente también prefería... ¿Quién era aquella mujer? ¿De qué sílabas se componían su nombre y su apellido? ¿Soltera? ¿Casada? Casada de seguro, cuando tal misterio la envolvía, que Gonzalo se negaba á nombrarla... Y yo daba vueltas en la cama, y la almohada se impregnaba de lágrimas calientes... Entonces me parecía estúpida mi resignación, inconcebible, absurda mi obediencia, absurda mi boda; y apenas amaneció, me fuí derecha al dormitorio de mi madre, y me abracé á ella en tal estado de aflicción y de trastorno, que la pobrecilla (bien recordarás lo extremosa que era en quererme) me dijo así: «Pequeña, serénate... Voy á ver qué le ha sucedido al talabarte de mi sobrino... Si está herido, te prometo cuidarle como su propia madre le cuidaría...»\"},{\"heading\":false,\"text\":\"Herido estaba en efecto, pero no de gravedad; su adversario sí que se llevó una buena estocada, ¡que á no resbalar en una costilla...! Así que Gonzalo pudo salir--y fué muy pronto--vino apresurado á dar las gracias á mamá. ¡Ay, Rosalía! ¡Qué impresión! Noté que me miraba... vamos... como otras veces... y á las primeras palabritas que deslizó, estando los dos en el hueco de una ventana que daba al jardín... no lo pude remediar... solté la pregunta difícil...\"},{\"heading\":false,\"text\":\"--¿Esa mujer por quien te has batido...?\"},{\"heading\":false,\"text\":\"Se puso encarnadísimo, lo cual me pareció mala señal, y contestó muy confuso y medio riendo:\"},{\"heading\":false,\"text\":\"--¡Mujer!... Sí, ¡una mujer ha sido la causa!...\"},{\"heading\":false,\"text\":\"Hice un movimiento para separarme, para huir (estaba furiosa, le hubiese pegado), y entonces él, con ese modo que tiene de decir las cosas, que no hay remedio sino creerle, exclamó:\"},{\"heading\":false,\"text\":\"--Beatriz, no caviles... A mí no me ha dado en qué pensar, en cierto terreno y por cierto estilo, ninguna mujer sino una... ¡que tú conoces mucho...! Ea, no te alteres, no pongas esa cara... Si no te burlas, te enteraré... El bárbaro á quien di una lección estaba injuriando...\"},{\"heading\":false,\"text\":\"--¿A quién?--pregunté con afán al ver que Gonzalo se paraba.\"},{\"heading\":false,\"text\":\"--A... ¡á la Virgen María!...\"},{\"heading\":false,\"text\":\"--¡A la Virgen María!--repetí yo atónita.\"},{\"heading\":false,\"text\":\"--Justamente... Por mi honor que es verdad... Ya conozco que te parecerá raro... Por eso no permití que se divulgase; más vale que se figuren otra cosa; así al menos no se reirán de mí... no me llamarán Quijote...\"},{\"heading\":false,\"text\":\"--Pero tú... Gonzalo... tú... Entonces, mamá, que dice que tú... que tus creencias... tartamudeé, temiendo asfixiarme de alegría.\"},{\"heading\":false,\"text\":\"--¿Qué tienen que ver las creencias?--me replicó él casi con dureza.--La Virgen es una mujer... y delante de quien tenga vergüenza y manos, á una mujer no se la ofende...\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"Rosalía callaba sorprendida; Beatriz, conmovida, afectaba mirar hacia fuera, á los árboles despojados de hoja, finos como arborizaciones de ágata sobre el cielo puro.\"},{\"heading\":false,\"text\":\"--¿Y después, sin más, os casásteis?--interrogó la amiga con picardía y sorna.\"},{\"heading\":false,\"text\":\"--Sin más--respondió con energía Beatriz.--Mamá dijo que Gonzalo, á su manera, tenía religión, tenía una fe... el honor, ¿sabes? y que la Virgen haría lo que faltaba... Y lo hizo, Rosalía. Mi marido, cuando yo voy á misa... no se queda ya á la puerta!\"}]},{\"title\":\"El panorama de la Princesa\",\"blocks\":[{\"heading\":false,\"text\":\"El palacio del Rey de Magna estaba triste, muy triste, desde que un padecimiento extraño, incomprensible para los médicos, obligaba á la Princesa Rosamor á no salir de sus habitaciones. Silencio glacial se extendía, como neblina gris, por las vastas galerías de arrogantes arcadas y los salones revestidos de tapices, con altos techos de grandiosas pinturas; y el paso apresurado y solícito de los servidores, el andar respetuoso y contenido de los cortesanos, el golpe mate del cuento de las alabardas sobre las alfombras, las conversaciones en voz baja, susurrantes apenas, producían impresión peculiar de antecámara de enfermo grave. ¡Tenía el Rey una cara tan severa, un gesto tan desalentado é indiferente para los áulicos, hasta para los que antaño eran sus amigos y favoritos! ¿A qué luchar? ¡La Princesa se moría de languidez... Nadie acertaba á salvarla, y la ciencia declaraba agotados sus recursos!\"},{\"heading\":false,\"text\":\"Una mañana llegó á la puerta del palacio cierto viejo de luenga barba y raida hopalanda color avellana seca, precedido de un borriquillo cuyos lomos agobiaba enorme caja de madera ennegrecida. Intentaron los guardias desviar con aspereza al viejo y á su borriquillo, pero titubearon al oir decir que en aquella caja tosca venían la salud y la vida de la Princesa Rosamor. Y mientras se consultaban, irresolutos, dominados á pesar suyo por el aplomo y seguridad con que hablaba el viejo, un gallardo caballero desconocido, mozo y de buen talante, cuya toca de plumas rizaba el viento, cuya melena obscura caía densa y sedosa sobre un cuello moreno y erguido, se acercó á los guardias, y, con la superioridad que prestan el rico traje y la bizarra apostura, les ordenó que dejasen pasar al anciano, si no querían ser responsables ante el Rey de la muerte de su hija; y los guardias, aterrados, se hicieron atrás, el anciano pasó, y el jumentillo hirió con sus cascos las sonoras losas de mármol del gran patio donde esperaban en fila las carrozas de los poderosos. En pos del viejo y el borriquillo, entró el mozo también.\"},{\"heading\":false,\"text\":\"Avisado el Rey de que abajo esperaba un hombre que aseguraba traer en un cajón la salud de la Princesa, mandó que subiese al punto; porque los desesperados de un clavo ardiendo se agarran, y no se sabe nunca de qué lado lloverá la Providencia. Hubo entre los cortesanos cuchicheos y alguna sonrisa reprimida pronto, al ver subir á dos porteros abrumados bajo el peso de la enorme caja de madera, y detrás de ellos al viejo de la hopalanda avellana y al lindo hidalgo de suntuoso traje á quien nadie conocía; pero la curiosidad, más aguda que el sarcasmo, les devoraba el alma con sus dientecillos de ratón, y no tuvieron reposo hasta que el primer Ministro, también algo alarmado por la novedad, les enteró de que la famosa caja del viejo sólo contenía un panorama, y que con enseñarle las vistas á la Princesa aquel singular curandero respondía de su alivio. En cuanto al mozo, era el ayudante encargado de colocarse detrás de una cortina sin ser visto, y hacer desfilar los cuadros por medio de un mecanismo original. Inútil me parece añadir que al saber en qué consistía el remedio, los cortesanos, sin perder el compás de la veneración monárquica, se burlaron suavemente y soltaron muy donosas pullas.\"},{\"heading\":false,\"text\":\"Entre tanto, instalábase el panorama en la cámara de la Princesa, la cual, desde el mismo sillón donde yacía recostada sobre pilas de almohadones, podía recrearse en aquellas vistas que, según el viejo continuaba afirmando terminantemente, habían de sanarla. Oculto é invisible, el galán hizo girar un manubrio, y empezaron á aparecer, sobre el fondo del inmenso paño extendido que cubría todo un lado de la cámara, y al través de amplio cristal, cuadros interesantísimos. Con una verdad y un relieve sorprendentes, desfilaron ante los ojos de la Princesa las ciudades más magníficas, los monumentos más grandiosos y los paisajes más admirables de todo el mundo. En voz cascada, pero con suma elocuencia, explicaba el viejo los esplendores, verbigracia, de Roma, el Coliseo, las Termas, el Vaticano, el Foro; y tan pronto mostraba á la Princesa una naumaquia, con sus luchas de monstruos marinos y sus combates navales entre galeras incrustadas de marfil, como la hacía descender á las sombrías Catacumbas y presenciar el entierro de un mártir, depuesto en paz con su ampolla llena de sangre al lado. Desde los famosos pensiles de Semíramis y las colosales construcciones de Nabucodonosor, hasta los risueños valles de la Arcadia, donde en el fondo de un sagrado bosque centenario danzan las blancas ninfas en corro alrededor de un busto de Pan que enrama frondosa mata de hiedra; desde las nevadas cumbres de los Alpes hasta las voluptuosas ensenadas del golfo partenópeo, cuyas aguas penetran vueltas líquido zafiro bajo las bóvedas celestes de la gruta de Azur, no hubo aspecto sublime de la historia, asombro de la naturaleza ni obra estupenda de la actividad humana que no se presentase ante los ojos de la Princesa Rosamor--aquellos ojos grandes y soñadores, cercados de una mancha de livor sombrío, que delataba los estragos de la enfermedad.--Pero los ojos no se reanimaban; las mejillas no perdían su palidez de transparente cera; los labios seguían contraídos, olvidados de las sonrisas; las encías marchitas y blanquecinas hacían parecer amarilla la dentadura, y las manos afiladas continuaban ardiendo de fiebre ó congeladas por el hielo mortal. Y el Rey, furioso al ver defraudada una última esperanza, más viva cuanto más quimérica, juró enojadísimo que ahorcaría de muy alto al impostor del viejo, y ordenó que subiese el verdugo, provisto de ensebada soga, á la torre más eminente del palacio, para colgar de una almena, á vista de todos, al que le había engañado. Pero el viejo, tranquilo y hasta desdeñoso, pidió al Rey un plazo breve: faltábale por enseñar á la Princesa una vista, una sola, de su panorama, y si después de contemplarla no se sentía mejor, que le ahorcasen enhorabuena, por torpe é ignorante. Condescendió el Rey, no queriendo espantar aún la vana esperanza postrera, y se salió de la cámara, por no asistir al desengaño. Al cuarto de hora, no pudiendo contener la impaciencia, entró, y notó con transporte una singular variación en el aspecto de la enferma; sus ojos relucían; un ligero sonrosado teñía sus mejillas flacas; sus labios palpitaban enrojecidos y su talle se enderezaba airoso como un junco. Parecía aquello un milagro, y el Rey, en su enajenación, se arrancó del cuello una cadena de oro y la alargó al viejo, que rehusó el presente. La única recompensa que pedía era que le dejasen continuar la cura de la Princesa, sin condiciones ni obstáculos, ofreciendo terminarla en un mes. Y, loco de gozo, el Rey se avino á todo, hasta á respetar el misterio de aquella vista prodigiosa que había empezado á devolver á su hija la salud.\"},{\"heading\":false,\"text\":\"No obstante--transcurrida una semana y confirmada la mejoría de la enferma, mejoría tan acentuada que ya la Princesa había dejado su sillón, y, esbelta como un lirio, se paseaba por el aposento y las galerías próximas, ansiosa de respirar el aire, animada y sonriente,--anheló el Rey saber qué octava maravilla del orbe, qué portentoso cuadro era aquel cuya contemplación había resucitado á Rosamor moribunda. Y como la Princesa, cubierta de rubor, se arrojase á sus pies suplicándole que no indagara su secreto, el Rey, cada vez más lleno de curiosidad, mandó que sin dilación se le hiciese contemplar la milagrosa última vista del panorama. ¡Oh sorpresa inaudita! Lo que se apareció sobre el fondo del inmenso paño negro, al través del claro cristal, no fué ni más ni menos que el rostro de un hombre, joven y guapo, eso sí, pero que nada tenía de extraordinario ni de portentoso. El rostro sonreía con dulzura y pasión á la Princesa, y ella pagaba la sonrisa con otra no menos tierna y extática... El Rey reconoció al supuesto ayudante del médico, aquel mozo gallardo, y comprendió que, en vez de enseñar las vistas de su panorama, se enseñaba á sí propio, y sólo con este remedio había sanado el enfermo corazón y el espíritu contristado y abatido de la niña; y si alguna duda le quedase acerca de este punto, se la quitaría la misma Rosamor, al decirle confusa, temblorosa y en voz baja, como quien pide anticipadamente perdón y aquiescencia:\"},{\"heading\":false,\"text\":\"--Padre, todos los monumentos y todas las bellezas del mundo no equivalen á la vista de un rostro amado...\"}]},{\"title\":\"Remordimiento\",\"blocks\":[{\"heading\":false,\"text\":\"Conocí en su vejez á un famoso calaverón que vivía solitario, y al parecer tranquilo, en una soberbia casa, cuidándose mucho y con un criado para cada dedo, porque la fortuna--caprichosa á fuer de mujer, diría algún escritor de esos que están tan seguros del sexo de la fortuna como yo del mosquito que me crucificó esta noche--había dispuesto (sigo refiriéndome á la fortuna) que aquel perdulario derrochase primero su legítima, después las de sus hermanos, que murieron jóvenes, luego la de una tía solterona, y al cabo la de un tutor opulento y chocho por su pupilo. Y, por último, volvieron á ponerle á flote el juego ú otras granjerías que se ignoran, cuando ya había penetrado en su cabeza la noción de que es bueno conservar algo para los años tristes. Desde que mi calvatrueno (llamábase el vizconde de Tresmes) llegó á persuadirse de que interesaba á su felicidad no morirse en el hospital, cuidó de su hacienda con la perseverancia del egoismo, y no hubo capital mejor regido y conservado. Por eso, al tiempo que yo conocí al vizconde--poco antes de que un reuma al corazón le llevase al otro barrio--era un viejo rico, y su casa--desmintiendo la opinión del vulgo respecto á las viviendas de los solteros--modelo de pulcritud y orden elegante.\"},{\"heading\":false,\"text\":\"Miraba yo al vizconde con interés curioso, buscando en su fisonomía la historia íntima del terrible traga-corazones, por quien habitaba un manicomio una duquesa, y una infanta de España había estado á punto de echar á rodar el infantazgo y cuanto echar á rodar se puede.--Si no supiese que veía al más refinado epicúreo, creería estar mirando los restos de un poeta, de un artista, de uno de esos hombres que fascinan porque su acción dominadora no se limita á la materia, sino que subyuga la imaginación. Las nobles facciones de su rostro recordaban las de Volfango Goethe, no en su gloriosa ancianidad, sino más bien en la época del famoso viaje á Italia; es decir, lo que serían si Goethe, al envejecer, conservase las líneas de la juventud. Aquella finura de trazo; aquella boca un tanto carnosa; aquella nariz de vara delgada, de griega pureza en su hechura; aquellas cejas negrísimas, sutiles, de arco gentil, que acentúan la expresión de los vivos y profundos ojos; aquellas mejillas pálidas, duras, de grandes planos, como talladas en mármol, mejillas viriles--pues las redondas son de mujer ó niño;--aquel cuello largo, que destaca de los bien derribados hombros la altiva cabeza... todo esto, aunque en ruinas ya, subsistía aún, y á la vez el cuerpo delataba en sus proporciones justas, en su musculosa esbeltez, algo recogida, como de gimnasta, la robustez de acero del hombre á quien los excesos ni rinden ni consumen. Verdad que estas singulares condiciones del vizconde las adivinaba yo por la aptitud que tengo para restar los estragos de la vejez y reconstruir á las personas tal cual fueron en sus mejores años.\"},{\"heading\":false,\"text\":\"Gustaba el vizconde de charlar conmigo, y á veces me refería lances de su azarosa vida, que no serían para contados, si él no supiese salvar los detalles escabrosos con exquisito aticismo, y cubrir la inverecundia del fondo con lo escogido de la forma. No obstante, en las narraciones del vizconde había algo que me sublevaba, y era la absoluta carencia de sentido moral, el cinismo frío, visible bajo la delicada corteza del lenguaje. Punzábame una curiosidad, y pensaba entre mí: «¿Será posible que este hombre, que para sus semejantes ha sido no sólo inútil, sino dañino; que ha libado el jugo de todas las flores sacando miel para embriagarse de ella, aunque la destilase con sangre y lágrimas; este corsario, este negrero del amor, repito, será posible que no haya conservado nada vivo y sano bajo los tejidos marchitos por el libertinaje? ¿No tendrá un remordimiento, no habrá realizado un acto de abnegación, una obra de caridad?»\"},{\"heading\":false,\"text\":\"Un día me resolví á preguntárselo directamente.\"},{\"heading\":false,\"text\":\"--Porque al fin--le dije--en las batallas que usted solía ganar hay muertos y heridos; sólo que, como en las heridas de florete, la hemorragia es interna, pues el honor manda callar y sucumbir en silencio. ¡Cuántos maridos, cuántos hermanos, cuántos padres (sin hablar de las propias víctimas) habrán ardido por culpa de usted en un infierno de vergüenza!\"},{\"heading\":false,\"text\":\"--¡Bah! No lo crea usted--respondía el don Juan sin alterarse en lo más mínimo.--En estas cuestiones, los expertos somos un poquillo fatalistas. ¡Lo escrito se cumple! Y lo que yo, por escrúpulos más ó menos justificados, desperdiciase, otro lo recogería, quizá con menos arte, tino y miramiento que yo. La pavía madura cuelga de la rama y va por instantes á desprenderse del tallo. El que pasa y la coge suavemente, le ahorra el sonrojo de caer al suelo, de mancharse, de ser pisada...\"},{\"heading\":false,\"text\":\"Al ver que su extraño razonamiento me dejaba algo perplejo, el vizconde añadió:\"},{\"heading\":false,\"text\":\"--A pesar de todo, confieso que hice un acto de abnegación y que tengo un remordimiento...\"},{\"heading\":false,\"text\":\"Esperé, y el viejo, apoyando la barba en dos dedos de la mano izquierda, habló con lentitud y en tono menos irónico que de costumbre:\"},{\"heading\":false,\"text\":\"--Ha de saber usted que tuve una hermana que se casó y se murió casi en seguida (en mi casa todos murieron jóvenes y tísicos, excepto yo, que absorbí la fuerza que debía repartirse entre los demás). Mi cuñado, poco después, se cayó de un caballo y no sobrevivió á la caída. Quedó una niña, bonita como un serafín. Yo era su tutor, y aunque cuidé bien de su educación y de sus intereses, la veía poco, porque no me gustan los chiquillos. Vino la pubertad, y entonces la criatura tomó formas menos seráficas y más apetecibles para los humanos. Y, cosa rara, si de chiquilla, al verme, se deshacía en fiestas y se volvía loca de gozo, ya de mujercita no parecía sino que la afligía mi presencia, y me acuerdo que hasta sufrió un síncope porque la dí un beso paternal... Paternal (se lo afirmo á usted bajo palabra de honor), porque tenemos la tontería de figurarnos que los que conocimos niños no llegan nunca á personas mayores...\"},{\"heading\":false,\"text\":\"Con todo, ciertos errores pronto se disipan, y como los síntomas iban acentuándose, no tardé en conocer la índole de la enfermedad... La muchacha repito que era una hermosura. Le enseñaré á usted su retrato, y me dirá si exagero. Aparte de esto de la belleza, nunca ví mujer que más traspasada se mostrase. Rendida ya, vencida por fuerza superior á su albedrío, lejos de huirme, me seguía y buscaba incesantemente, y se leía en sus ojos, en su voz y en sus menores acciones, que era tan mía, tan mía que podía yo marcarla en la frente la S y el clavo. Mi edad era entonces la de las pasiones violentas: tenía treinta y ocho años... pero ¡así y todo!...\"},{\"heading\":false,\"text\":\"--¿No se resolvió usted á coger la pavía?\"},{\"heading\":false,\"text\":\"--No era pavía, como usted verá--respondió el calaverón frunciendo las cejas.--Lo que puedo decir á usted es que al comprender la realidad, huí de mi sobrina, viajé, estuve ausente más de un año, y al ver á mi regreso á la niña enferma de pasión y amartelada como nunca, la hablé lo mismo que un padre, la pinté mi vida y mi condición y hasta mis vicios...\"},{\"heading\":false,\"text\":\"--Leña al fuego--interrumpí.\"},{\"heading\":false,\"text\":\"--¡Leña al fuego, sí, tal vez!... En fin, la dije redondamente que estaba resuelto á no casarme nunca; que no me casaría ni con Eugenia de Montijo, emperatriz de Francia...\"},{\"heading\":false,\"text\":\"--¿Y ella?...\"},{\"heading\":false,\"text\":\"--Ella... Ella... después de llorar y de ponerse más pálida y más roja y más temblorosa que una sentenciada... acabó por decirme que... soltero ó casado, malo ó bueno, rico ó pobre...\"},{\"heading\":false,\"text\":\"--¡Comprendo!...\"},{\"heading\":false,\"text\":\"--Bien, pues yo... no sólo rehusé, desvié, contuve, sino que busqué marido, joven, guapo, bueno... y con todo mi ascendiente, con mi mandato, lo hice aceptar...\"},{\"heading\":false,\"text\":\"--¡Ya me parecía!--exclamé entusiasmada.--¡Una acción generosa, bonita! ¡Si no podía menos!\"},{\"heading\":false,\"text\":\"--Una acción detestable--repuso el vizconde, cuyos labios temblaron ligeramente.--Así que se casó mi sobrina, se me cayeron á mí las escamas de los ojos, y me hice cargo de que me estaba muriendo por ella... Y la busqué, y la perseguí, y la asedié, y agoté los recursos, y sólo encontré repulsa, glacial desdén, rigor tan sistemático y tan perseverante, que me dí por vencido, y me salieron las primeras canas...\"},{\"heading\":false,\"text\":\"--Vamos, la sobrinita se encontraba bien con el marido que usted eligió...\"},{\"heading\":false,\"text\":\"--Tan bien--añadió el don Juan sombríamente--que a los seis meses mi sobrina enfermó de pasión de ánimo; y á los diez, en la agonía, me llamó para despedirse de mí y decirme al oído que... ¡como siempre!\"},{\"heading\":false,\"text\":\"Tresmes bajó la cabeza y me pareció ver que una nube cruzaba por su frente olímpica.\"},{\"heading\":false,\"text\":\"--Ahí tiene usted--murmuró después de una pausa,--mi remordimiento. Nadie debe salirse de su vocación, y la mía no era conducir á nadie al sendero del deber y la virtud.\"}]},{\"title\":\"Temprano y con sol\",\"blocks\":[{\"heading\":false,\"text\":\"EL empleado que despachaba los billetes en la taquilla de la estación del Norte no pudo reprimir un movimiento de sorpresa cuando la infantil vocecica pronunció, en tono imperativo:\"},{\"heading\":false,\"text\":\"--¡Dos de primera... á Paris!...\"},{\"heading\":false,\"text\":\"Acercando la cabeza cuanto lo permite el agujero del ventano, miró á su interlocutora, y vió que era una morena de once á doce años, de ojos como tinteros, de tupida melena negra, vestida con rico y bien cortado ropón de franela inglesa roja, y luciendo un sombrerillo jockey de terciopelo granate que la sentaba a las mil maravillas. Agarrado de la mano traía la señorita á un caballerete que representaba la misma edad sobre poco más ó menos, y también tenía trazas en su semblante y atavío de pertenecer á muy distinguida clase y á muy acomodada familia. El chico parecía azorado: la niña, alegre, con nerviosa alegría. El empleado sonrió á la gentil pareja, y murmuró como quien da algún paternal aviso:\"},{\"heading\":false,\"text\":\"--¿Directo ó á la frontera? A la frontera... son ciento cincuenta pesetas, y...\"},{\"heading\":false,\"text\":\"--Ahí va dinero--contestó la intrépida señorita, alargando un abierto portamonedas. El empleado volvió á sonreir, ya con marcada extrañeza y compasión, y advirtió:\"},{\"heading\":false,\"text\":\"--Aquí no tenemos bastante...\"},{\"heading\":false,\"text\":\"--¡Hay quince duros y tres pesetas!--exclamó la viajerilla.\"},{\"heading\":false,\"text\":\"--Pues no alcanza... Y para convencerse, pregunten ustedes á sus papas.\"},{\"heading\":false,\"text\":\"Al decir esto el empleado, vivo carmín tiñó hasta las orejas del galán, cuya mano no había soltado la damisela, y ésta, dando impaciente patada en el suelo, gritó:\"},{\"heading\":false,\"text\":\"--¡Bien... pues entonces... un billete más barato!\"},{\"heading\":false,\"text\":\"--¿Cómo más barato? ¿De segunda? ¿De tercera? ¿A una estación más próxima? ¿Escorial, Avila...?\"},{\"heading\":false,\"text\":\"--¡Avila, sí... Avila... justamente, Avila...!--respondió con energía la del rojo balandrán. Dudó el empleado un momento; al fin se encogió de hombros como el que dice: «¿A mí qué? ya se desenredará este lío;» y tendió los dos billetes, devolviendo muy aligerado el portamonedas...\"},{\"heading\":false,\"text\":\"Sonó la campana de aviso; salieron los chicos disparados al andén; metiéronse en el primer vagón que vieron, sin pensar en buscar un departamento donde fuesen solos; y con gran asombro del turista británico que acomodaba en un rincón de la red su balija de cuero, al verse dentro del coche se agarraron de la cintura y rompieron á brincar...\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"¿Cómo principió aquella pasión devoradora, frenética, incendiaria? ¡Ah! Los orígenes primeros de lo grave y trascendental en nuestra vida, son insignificantes menudencias, pequeñeces míseras, átomos morales que se asocian en un torbellinito molecular, y á fuerza de dar vueltas y más vueltas sobre sí mismo, el torbellino se redondea, se solidifica, adquiere forma, toma la consistencia del diamante... No desconfiéis nunca en la vida de las cosas grandes, que se presentan con imponente aparato; esas ya avisan, y hay medio de precaverse: temed á las tentaciones menudas, á los peligros sutiles é insidiosos. Toda la teoría de los microbios, hoy admitida, ¿qué es sino demostración de la importancia capital de lo infinitamente pequeño?\"},{\"heading\":false,\"text\":\"La pasión empezó, pues, del modo más sencillo, más inocente y más bobo... Empezó por una manía... Ambos eran coleccionistas.--¿De qué? Ya lo podéis presumir, vosotros los que frisais en la edad de mis héroes. La afición á coleccionar suele desarrollarse entre los cuarenta y los sesenta: apenas he visto un bibliómano joven, y las tiendas de los chamarileros son más frecuentadas por señores respetables que por alegres mozos. Hay, sin embargo, una excepción á esta regla general, y es la chifladura por reunir sellos de correos. Sin que yo niegue que pueden padecerla muy graves personajes, la verdad es que el período en que suele hacer estragos es la etapa comprendida entre los diez y los quince. Y en ese lustro auroral que separa la edad del trompo y la cuerda de la edad del pavo, vivían mis dos enamorados fugitivos del tren.\"},{\"heading\":false,\"text\":\"Ya se ha dicho que su galeoto, el libro de Lanzarote y Ginebra donde bebieron la ponzoña amorosa, fué el coleccionismo, la manía de la filatelia, común á entrambos. El papá de Serafina, vulgo Finita, y la mamá de Francisco, vulgo Currín, se trataban poco; ni siquiera se visitaban, á pesar de vivir en la misma opulenta casa del barrio de Salamanca: en el principal el papá de Finita, y en el segundo la mamá de Currín. Currín y Finita, en cambio, se encontraban muy á menudo en la escalera, cuando él iba á clase y ella salía para su colegio; pero valga la verdad: ni habrían reparado el uno en el otro, si no fuera porque cierta mañana, al bajar las escaleras, Currín notó que Finita llevaba bajo el brazo un objeto, un libro encuadernado en tafilete rojo... ¡libro tantas veces codiciado y soñado por él! «¡Me debía haber comprado mamá uno así, carambita! En cuanto me examine y saque nota, ya me lo está comprando. ¡No faltaba más! El mío es una porquería...» De esto á rogar á Finita que le enseñase el magnífico album de sellos, mediaba un paso. Finita, en el mismo descanso de la escalera, accedió á los ruegos de Currín: pusieron el álbum sobre la repisa de la ventana, y se dieron á hojearlo con vivacidad.--«Esta página es del Perú... Mira los de las islas Hawai... Tengo la colección completa...»\"},{\"heading\":false,\"text\":\"Y desfilaban los minúsculos y artísticos grabaditos con que cada nación marca y autoriza su correspondencia; los aristocráticos perfiles de las dinastías sajonas, que se desdeñan de mirarnos á la cara, y las burguesas y honradas fisonomías de los presidentes de Estados americanos, siempre de frente; la república francesa, con sus dos airosas figuras que se dan la mano, y el reyecillo español, con su redonda cabeza de bebé; los sellos chinos y su dragón, los turcos y su cimitarra; Don Carlos, recuerdo de nuestras vicisitudes políticas, y Don Amadeo, efímera memoria de la misma agitada época; los preciosos sellos de Terranova, con la testa entonces ideal del príncipe de Gales, y los fastuosos sellos de las colonias británicas, en que la abuelita Victoria aparece oficiando de emperatriz... Currín se embelesaba y chillaba de vez en cuando dando brincos: «¡Ay! ¡Ay! ¡Caracoles, qué bonito! Este no lo tengo yo...» Por fin, al llegar á uno muy raro, el de la república de Liberia, no pudo contenerse: «¿Me lo das?»--«Toma»;--respondió con expansión Finita.--«Gracias, hermosa»,--contestó el galán;--y como Finita, al oir el requiebro, se pusiese del color de la cubierta de su album, Currín reparó en que Finita era muy mona, sobre todo así, colorada de placer y con los negros ojos brillantes, rebosando alegría. «¿Sabes que te he de decir una cosa?»--murmuró el chico.--«Anda, dímela.»--«Hoy no.»--La doncella francesa que acompañaba á Finita al colegio, había mostrado hasta aquel instante risueña tolerancia con la digresión filatélica; pero parecióle que se prolongaba mucho, y pronunció un «Mademoiselle, s’il vous plaît», que significaba: «Hay que ir al colegio rabiando ó cantando, conque... una buena resolución.»\"},{\"heading\":false,\"text\":\"Currín se quedó admirando su sello... y pensando en Finita. Era Currín un chico dulce de carácter, no muy travieso, aficionado á los dramas tristes, á las novelas de aventuras extraordinarias, y á leer versos y aprendérselos de memoria. Siempre estaba pensando que le había de suceder algo raro y maravilloso; de noche soñaba mucho, y con cosas del otro mundo ó con algo procedente de sus lecturas. Desde que coleccionaba sellos, soñaba también con viajes de circunnavegación y países desconocidos, á lo cual contribuía mucho el ser decidido admirador de Julio Verne... Aquella noche realizó dormido una excursioncita breve... á Terranova, al país de los sellos hermosos. Mejor dicho, no era excursión, sino instantánea traslación; y en una playa orlada de monolitos de hielo, que alumbraba una aurora boreal, Finita y él se paseaban muy serios, cogidos del brazo...\"},{\"heading\":false,\"text\":\"Al otro día, nuevo encuentro en la escalera. Currín llevaba duplicados de sellos para obsequiar á Finita. En cuanto la dama vió al galán, sonrió y se acercó con misterio. «Aquí te traigo esto...»--balbuceó él...--Finita puso un dedo sobre los labios, como para indicar al chico que se recatase de la francesa; pero constándole á Currín que no había en el obsequio de los sellos malicia alguna, fué muy resuelto á entregarlos. Finita se quedó, al parecer, algo chafada; sin duda esperaba otra cosa; y llegándose vivamente á Currín, le dijo entre dientes:\"},{\"heading\":false,\"text\":\"--¿Y... y aquello?\"},{\"heading\":false,\"text\":\"--¿Aquello..?\"},{\"heading\":false,\"text\":\"--Lo que me ibas á decir ayer...\"},{\"heading\":false,\"text\":\"Currín suspiró, se miró á las botas, y salió con esta pata de gallo:\"},{\"heading\":false,\"text\":\"--Si no era nada...\"},{\"heading\":false,\"text\":\"--¡Cómo nada!--articuló Finita furiosa.--¡Pareces memo de la cabeza! Nada, ¿eh?\"},{\"heading\":false,\"text\":\"Y el muchacho, dando tormento al rey Leopoldo de Bélgica que apretaba entre sus dedos, se puso muy cerquita del oído de la niña, y murmuró suavemente: «Sí, era algo... Quería decirte que eres... ¡más guapita!» Y espantado de su osadía, echó á correr escalera abajo, y del portal salió en volandas á la calle.\"},{\"heading\":false,\"text\":\"Al otro día, Currín escribió unos versos (poseo el original) en que decía á su tormento:\"},{\"heading\":false,\"text\":\"Nace el amor de la nada; de una mirada tranquila; al girar de una pupila se halla un alma enamorada...\"},{\"heading\":false,\"text\":\"Endeblillos y todo, graves autores aseguran que Currín los sacó de un libro que le prestó un compañero... Mas ¿qué importa? El caso es que Currín se sentía como lo pintaban los versos: enamorado, atrozmente enamorado... No pensaba más que en Finita; se sacaba la raya esmeradamente, se compró una corbata nueva, y suspiraba á solas.\"},{\"heading\":false,\"text\":\"Al fin de la semana eran novios en regla. La doncella francesa cerraba los ojos... ó no veía, creyendo buenamente que de sellos se hablaba allí, y aprovechaba el ratito charlando también de lo que le parecía con su compatriota el cocinero...\"},{\"heading\":false,\"text\":\"Cierta tarde creyó el portero que soñaba, y se frotó los ojos. ¿No era aquella la señorita Serafina, que pasaba sola, con un saquillo de piel al brazo? ¿Y no era aquel que iba detrás el señorito Currín? ¿Y no se subían los dos á un coche de punto, que salía echando diablos? ¡Jesús, María y José! ¡Pero cómo están los tiempos y las costumbres! ¿Y á dónde irán? ¿Aviso ó no aviso á los padres? ¿Qué hace en este apuro un hombre de bien? ¿Me recibirán con cajas destempladas... ó caerá una propinaza de las gordas?\"},{\"heading\":false,\"text\":\"* * * * *\"},{\"heading\":false,\"text\":\"--Oye tú--decía Finita á Currín apenas el tren se puso en marcha--Avila, ¿cómo es? ¿Muy grande? ¿Bonita lo mismo que París?\"},{\"heading\":false,\"text\":\"--No...--respondió Currín con cierto escepticismo amargo.--Debe de ser un pueblo de pesca.\"},{\"heading\":false,\"text\":\"--Pues entonces... no conviene quedarse allí. Hay que seguir á París. Yo quiero ver París á todo trance; y también quiero ver las Pirámides de Egipto.\"},{\"heading\":false,\"text\":\"--Sí...--murmuró Currín, por cuya boca hablaban el buen sentido y la realidad--pero... ¿y los monises?\"},{\"heading\":false,\"text\":\"--¿Los monises?--contestó remedándole Finita--Eres más bobo que el que asó la manteca. ¡Se pide prestado!\"},{\"heading\":false,\"text\":\"--¿Y á quién?\"},{\"heading\":false,\"text\":\"--¡A cualquiera!\"},{\"heading\":false,\"text\":\"--¿Y si no nos lo quieren dar?\"},{\"heading\":false,\"text\":\"--¿Y por qué, melón de arroba? Yo tengo reloj que empeñar. Tú también. Empeño además el abrigo nuevo: me va asando de calor. No sirves para nada... ¡Escribimos á papás que nos envíen... un.. un bono... no, una letra! Papá las está mandando cada día á París y á todas partes.\"},{\"heading\":false,\"text\":\"--Tu papá estará echando chispas... Nos mandará un demontre!... Como mi mamá... ¡La hicimos, Finita!... No sé qué será de nosotros.\"},{\"heading\":false,\"text\":\"--Pues se empeña el reloj, y en paz... ¡Ay! ¡Lo que nos divertiremos en Avila! Me llevarás al café... y al teatro... y al paseo...\"},{\"heading\":false,\"text\":\"Cuando oyeron cantar «¡Avila! ¡Veinticinco minutos!...» saltaron del tren, pero al sentar el pie en el andén, se quedaron indecisos, aturrullados. La gente salía, se atropellaba hacia la fonda, y los enamorados no sabían qué hacer. «¿Por dónde se va á Avila?»--preguntó Currín á un _faquino_, que viendo á dos niños sin equipaje, se encogió de hombros y se alejó. Por instinto se encaminaron á una puerta, entregaron sus billetes, y asediados por un solícito mozo de fonda, se metieron en el coche, que los llevó á la del Inglés...\"},{\"heading\":false,\"text\":\"Acababa de recibir el señor gobernador de Avila telegrama de Madrid, «interesando la captura,» de la apasionada pareja. Era urgentísimo el aviso, y delataba la situación moral de una familia sumida en la angustia y la desesperación,--mejor dicho, dos familias debían de ser las desesperadas.--La captura se verificó en toda regla, no sin risa por un lado y declamaciones sobre lo que «cunde la inmoralidad», por otro. Los fugitivos fueron llevados á Madrid, y, acto continuo, Finita quedó internada en las _Dames anglaises_, y Currín en un colegio de donde no se le permitió salir en un año, ni aun los domingos. Con motivo del trágico suceso, el papá de Finita y la mamá de Currín se relacionaron, y conferenciaron largo y tendido, quedando acordes en que era preciso «echar tierra», «desorientar la opinión...» «hacer la conspiración del silencio». Con tal motivo, el papá de Finita reparó en lo bien conservada que estaba la mamá de Currín, y ésta notó en el banquero excelentes condiciones de hombre práctico en los negocios y de caballero galán con las damas. Su amistad se consolidó, y hay quien cree que se visitan á menudo. No se presume, sin embargo, que jamás se hayan escapado juntos... ¿Para qué?\"}]},{\"title\":\"Sí, señor\",\"blocks\":[{\"heading\":false,\"text\":\"Lo que voy á contar no lo he inventado. Si lo hubiese inventado alguien, si no fuese la exacta verdad, digo que bien inventado estaría; pero también me corresponde declarar que lo he oído referir... Lo cual disminuye muchísimo el mérito de este relato, y obliga á suponer que mi fantasía no es tan fecunda como se ha solido suponer, en momentos de benevolencia.\"},{\"heading\":false,\"text\":\"¿Eres tímido, oh tú que me lees? Porque la timidez es uno de los martirios ridículos; nos pone en berlina, nos amarra á banco duro. La timidez es un dogal á la garganta, una piedra al pescuezo, una camisa de plomo sobre los hombros, una cadena á las muñecas, unos grillos á los pies... Y el peor género de timidez no es el que procede de modestia, de recelo por insuficiencia de facultades. Hay otro más terrible: la timidez por exceso de emoción; la timidez del enamorado ante su amada, del fanático ante su ídolo.\"},{\"heading\":false,\"text\":\"De un enamorado se trata en este cuento, y tan enamorado, que no sé si nunca Romeo el veronés, Marsilla el turolense, ó Macías el galaico, lo estuvieron con mayor vehemencia. No envidiéis nunca á esta clase de locos. A los que mucho amaron se les podrá perdonar; pero envidiarles, sería no conocer la vida. Son más desventurados que el mendigo que pide limosna; más que el sentenciado que en su cárcel cuenta las horas que le quedan de vida horrible... Son desventurados porque tienen dislocada el alma, y les duele á cada movimiento... Doble su desdicha si la acompaña el suplicio de la timidez. Y la timidez, en bastantes casos, se cura con la confianza; pero la hay crónica é invencible; la hay en maridos que llevan veinte años de unión conyugal y no se han acostumbrado á tener franqueza con sus mujeres; en mujeres que, viviendo con un hombre en la mayor intimidad, no se acercan á él sin temor y temblor... Generalmente, sin embargo, se presenta el fenómeno durante ese período en que el amor, sin fueros y sin gallardías se estremece ante un gesto ó una palabra... Y éste era el caso de Agustín Oriol, perdidamente esclavo de la coquetuela y encantadora Condesa viuda de Dolfos.\"},{\"heading\":false,\"text\":\"Dícese que una viuda es más fácil de galantear que una soltera; pero en estas cuestiones tan peliagudas, yo digo que no hay reglas ni axiomas; cada persona difiere ó por su carácter ó por el mismo exceso de su apasionamiento. Agustín sentía, al acercarse á la Condesa, todos los síntomas de la timidez enfermiza, y mientras á solas preparaba declaraciones abrasadoras, discursos perfectamente hilados y tan persuasivos que ablandarían las piedras, lo cierto es que en presencia de su diosa no sabía despegar los labios; su garganta no formaba sonidos, ni su pensamiento coordinaba ideas... Todos reconocerán que este estado tiene poco de agradable, y que Agustín no era dichoso, ni mucho menos.\"},{\"heading\":false,\"text\":\"Vanamente apelaba á su razón para vencer aquella timidez estúpida... Su razón le decía que él, Agustín Oriol de Lopardo, caballero por los cuatro costados, joven, con hacienda, inteligencia y aptitudes para abrirse camino, era un excelente candidato á la mano de cualquiera mujer, por bonita y encopetada que se la suponga... ¿Por qué no había de quererle la Condesa? ¿Por qué, vamos á ver, por qué? El debía acercarse á ella ufano, arrogante, seguro de su victoria. Y todas las noches, al retirarse á su casa, se lo proponía...., y al día siguiente procedía lo mismo que el anterior. Se insultaba a sí mismo; se trataba de menguado, de necio, pero no podía vencerse... No podía, y no podía.\"},{\"heading\":false,\"text\":\"De modo que, al año próximamente de un enamoramiento tan intenso que le ocasionaba trastornos cardíacos, violentos hasta el síncope, Agustín no había cruzado aún palabra, lo que se dice palabra, con su idolatrada viuda. Iba á todas partes donde podía encontrarse con ella, pasaba muchas veces por debajo de sus balcones, se trasladaba á San Sebastián el mismo día que ella y en el mismo tren..., y aun ignoraría el sonido de su voz si no hubiese prestado ansioso oído á las conversaciones que ella sostenía con otras personas...\"},{\"heading\":false,\"text\":\"Por fin, un día--precisamente en San Sebastián--presentóse rodada la ocasión de romper el hielo. Fue en la terraza del Casino, á la hora en que una muchedumbre elegantemente ataviada respira el aire y escucha, ó, por mejor decir, no escucha la música, sino las infinitas charlas, que hacen otro rumor más contenido y más suave, como de colmena. Agustín estaba muy próximo á su amada, y devoraba con los ojos el perfil fino, asomando bajo el sombrero todo empenachado de plumas. Ella le observaba de reojo; y viéndole tan cerca, de pronto sintió impulsos de dirigirla la palabra. No era correcto, no era serio, no era propio de una señora... Bueno. Por encima de las fórmulas sociales están las circunstancias, y hay de estas irregularidades que todo el mundo comete, cuando á ello le empuja un fuerte estímulo... La viudita no podía menos de haber notado aquella adoración profunda, continua, que la rodeaba como el cuerpo astral al cuerpo visible, y sentía una curiosidad femenil, ardorosa, el afán de saber qué diría aquel adorador mudo, que la bebía y la respiraba. Resuelta, con sonriente afabilidad, con un alarde infantil que disimulaba lo aturdido del procedimiento, exclamó:\"},{\"heading\":false,\"text\":\"--¡Qué noche tan hermosa! ¿Verdad que es una delicia?\"},{\"heading\":false,\"text\":\"Agustín sintió como si campanas doblasen en su cerebro, no sabía si á muerte ó si á gloria; su sangre giró de súbito, sus oídos zumbaron..., y con tartajosa lengua, con voz imposible de reconocer, con un acento ronco y balbuciente, soltó esta frase:\"},{\"heading\":false,\"text\":\"--Sí... señor! ¡Sí... señor!\"},{\"heading\":false,\"text\":\"Fué como si otro hubiese hablado... Un individuo zumbón, dentro de Agustín, se reía sardónico, se mofaba de la extravagante respuesta... ¡Acababa de llamar «señor» á la única mujer que para él existía en el mundo! ¡No se le había ocurrido sino tal inepcia! Y ahora, con la lengua seca y el corazón inundado de bochorno, tampoco se le ocurría más. ¡Qué había de ocurrírsele! La terraza daba vueltas, el suelo huía bajo sus pies... Exhaló un gemido ronco, se llevó las manos á la cabeza, y levantándose, tambaleándose, huyó sin volver la vista atrás. Aquella noche pensó varias veces en el suicidio.\"},{\"heading\":false,\"text\":\"A la mañana siguiente, sintiéndose incapaz de presentarse de nuevo ante la que ya debía despreciarle, salió para Francia en el primer tren. Estuvo ausente muchos años; en ellos no volvió á saber de su adorada. Un día leyó en un periódico que se había casado. Todavía la noticia le causó grave pena. Después, lentamente, fue olvidando, nunca del todo.\"},{\"heading\":false,\"text\":\"Habían corrido cerca de cuatro lustros; las canas rafagueaban el negro cabello de Agustín, cuando en uno de sus viajes entró una señora, con dos señoritas, en el mismo departamento. Agustín la reconoció..., y aun su corazón, del cual padecía, le avisó de que era ella,--muy cambiada, muy envejecida,--pero ella. ¿Fue reconocido Agustín? No se sabe. Lo cierto es que se trabó conversación entre ambos viajeros, y que esta vez, no habiendo el estorbo de un amor tan insensato, Agustín charló sin recelo, y las horas corrieron sin sentir. La viajera habló de su juventud, y murmuró confidencialmente:\"},{\"heading\":false,\"text\":\"--De cuantos homenajes han podido tributarme, el que más agradecí, porque era el más sincero, consistió en que un joven que me seguía como mi sombra, me contestase, al dirigirle yo por primera vez la palabra: «Sí, señor...» ¿Comprende usted? Era tal su aturdimiento, que no acertó á decir otra cosa... Los requiebros más entusiastas no pueden halagar tanto á una mujer como una turbación, que parece señal de pasión verdadera...\"},{\"heading\":false,\"text\":\"--¿De modo... que usted no se rió de aquel hombre?--preguntó Agustín.\"},{\"heading\":false,\"text\":\"--Al contrario...--respondió la señora, con acento en que parecía temblar una lágrima.\"}]}]', 'es', 'https://www.gutenberg.org/ebooks/55514', '{}');
INSERT INTO libros (id, titulo, autor, genero, cover, secciones, idioma, fuente, introducciones) VALUES (57303, 'La Divina Comedia', 'Dante Alighieri', 'poesia', 'https://www.gutenberg.org/cache/epub/57303/pg57303.cover.medium.jpg', '[{\"title\":\"Infierno — canto primero\",\"blocks\":[{\"heading\":false,\"text\":\"A la mitad del viaje de nuestra vida me encontré en una selva obscura, por haberme apartado del camino recto. ¡Ah! Cuán penoso me sería decir lo salvaje, áspera y espesa que era esta selva, cuyo recuerdo renueva mi pavor, pavor tan amargo, que la muerte no lo es tanto. Pero antes de hablar del bien que allí encontré, revelaré las demás cosas que he visto. No sé decir fijamente cómo entré allí; tan adormecido estaba cuando abandoné el verdadero camino. Pero al llegar al pie de una cuesta, donde terminaba el valle que me había llenado de miedo el corazón, miré hacia arriba, y vi su cima revestida ya de los rayos del planeta que nos guía con seguridad por todos los senderos. Entonces se calmó algún tanto el miedo que había permanecido en el lago de mi corazón durante la noche que pasé con tanta angustia; y del mismo modo que aquel que, saliendo anhelante fuera del piélago, al llegar a la playa, se vuelve hacia las ondas peligrosas y las contempla, así mi espíritu, fugitivo aún, se volvió hacia atrás para mirar el lugar de que no salió nunca nadie vivo. Después de haber dado algún reposo a mi fatigado cuerpo, continué subiendo por la solitaria playa, procurando afirmar siempre aquel de mis pies que estuviera más bajo. Al principio de la cuesta, aparecióseme una pantera ágil, de rápidos movimientos y cubierta de manchada piel. No se separaba de mi vista, sino que interceptaba de tal modo mi camino, que me volví muchas veces para retroceder. Era a tiempo que apuntaba el día, y el sol subía rodeado de aquellas estrellas que estaban con él cuando el amor divino imprimió el primer movimiento a todas las cosas bellas. Hora y estación tan dulces me daban motivo para augurar bien de aquella fiera de pintada piel. Pero no tanto que no me infundiera terror el aspecto de un león que a su vez se me apareció: figuróseme que venía contra mí, con la cabeza alta y con un hambre tan rabiosa, que hasta el aire parecía temerle. Siguió a éste una loba que, en medio de su demacración, parecía cargada de deseos; loba que ha obligado a vivir miserable a mucha gente. El fuego que despedían sus ojos me causó tal turbación, que perdí la esperanza de llegar a la cima. Y así como el que gustoso atesora y se entristece y llora con todos sus pensamientos cuando llega el momento en que sufre una pérdida, así me hizo padecer aquella inquieta fiera, que, viniendo a mi encuentro, poco a poco me repelía hacia donde el sol se calla. Mientras yo retrocedía hacia el valle, se presentó a mi vista uno, que por su prolongado silencio parecía mudo. Cuando le vi en aquel gran desierto:\"},{\"heading\":false,\"text\":\"--Piedad de mí--le grité--quienquiera que seas, sombra u hombre verdadero.\"},{\"heading\":false,\"text\":\"Respondióme:\"},{\"heading\":false,\"text\":\"No soy ya hombre, pero lo he sido; mis padres fueron lombardos y ambos tuvieron a Mantua por patria. Nací \\\"sub Julio,\\\" aunque algo tarde, y vi a Roma bajo el mando del buen Augusto en tiempo de los dioses falsos y engañosos. Poeta fuí, y canté a aquel justo hijo de Anquises, que volvió de Troya después del incendio de la soberbia Ilión. Pero, ¿por qué te entregas de nuevo a tu aflicción? ¿Por qué no asciendes al delicioso monte, que es causa y principio de todo goce?\"},{\"heading\":false,\"text\":\"--¡Oh! ¿Eres tú aquel Virgilio, aquella fuente que derrama tan ancho raudal de elocuencia?--le respondí ruboroso. ¡Ah!, ¡honor y antorcha de los demás poetas! Válganme para contigo el prolongado estudio y el grande amor con que he leído y meditado tu obra. Tú eres mi maestro y mi autor predilecto; tú solo eres aquél de quien he imitado el bello estilo que me ha dado tanto honor. Mira esa fiera debido a la cual retrocedía; líbrame de ella, famoso sabio, porque a su aspecto se estremecen mis venas y late con precipitación mi pulso.\"},{\"heading\":false,\"text\":\"--Te conviene seguir otra ruta--respondió al verme llorar--, si quieres huír de este sitio salvaje; porque esa fiera que te hace prorrumpir en tales lamentaciones no deja pasar a nadie por su camino, sino que se opone a ello matando al que a tanto se atreve. Su instinto es tan malvado y cruel, que nunca ve satisfechos sus ambiciosos deseos, y después de comer tiene más hambre que antes. Muchos son los animales a quienes se une, y serán aun muchos más hasta que venga el Lebrel[1] y la haga morir entre dolores. Este no se alimentará de tierra ni de peltre, sino de sabiduría, de amor y de virtud, y su patria estará entre Feltro y Feltro. Será la salvación de esta humilde Italia, por quien murieron de sus heridas la virgen Camila, Euríalo y Turno y Niso. Perseguirá a la loba de ciudad en ciudad hasta que la haya arrojado en el infierno, de donde en otro tiempo la hizo salir la envidia. Ahora, por tu bien, pienso y veo claramente que debes seguirme: yo seré tu guía, y te sacaré de aquí para llevarte a un lugar eterno, donde oirás aullidos desesperados; verás los espíritus dolientes de los antiguos condenados, que llaman a gritos a la segunda muerte; verás también a los que están contentos entre las llamas, porque esperan, cuando llegue la ocasión, tener un puesto entre los bienaventurados. Si quieres, en seguida, subir hasta ellos, te acompañará en este viaje un alma más digna que yo, te dejaré con ella cuando yo parta; pues el Emperador que reina en las alturas no quiere que por mediación mía se entre en su ciudad, porque fuí rebelde a su ley. El impera en todas partes y reina arriba; arriba está su ciudad y su alto solio: ¡Oh! ¡Feliz el elegido para su reino!\"},{\"heading\":false,\"text\":\"[1] Can Grande della Scala, señor de Verona y bienhechor de Dante.\"},{\"heading\":false,\"text\":\"Y yo le contesté:\"},{\"heading\":false,\"text\":\"--Poeta, te requiero por ese Dios a quien no has conocido, que me hagas huír de este mal y de otro peor; condúceme adonde has dicho, para que yo vea la puerta de San Pedro y a los que, según dices, están tan desolados.\"},{\"heading\":false,\"text\":\"Entonces se puso en marcha, y yo seguí tras él.\"}]},{\"title\":\"Infierno — canto segundo\",\"blocks\":[{\"heading\":false,\"text\":\"El día terminaba; la atmósfera obscura de la noche invitaba a descansar de sus fatigas a los seres animados que existen sobre la tierra, y yo solo me preparaba a sostener los combates del camino y de las cosas dignas de compasión, que mi memoria trazará sin equivocarse. ¡Oh Musas!, ¡oh alto ingenio!, venid en mi ayuda: ¡oh mente, que escribiste lo que ví!, ahora aparecerá tu nobleza.\"},{\"heading\":false,\"text\":\"Yo comencé:\"},{\"heading\":false,\"text\":\"--Poeta, que me guías, mira si mi virtud es bastante fuerte antes de aventurarme en tan profundo viaje. Tú dices que el padre de Silvio, aun corruptible, pasó al siglo inmortal y pasó sensiblemente. Si el adversario de todo mal le fué favorable, debióse a los grandes efectos que de él debían sobrevenir; y el por qué no parece injusto a un hombre de talento; pues en el Empíreo fué elegido para ser el padre de la fecunda Roma y de su imperio: el uno y la otra, a decir verdad, fueron establecidos en favor del sitio santo en donde reside el sucesor del gran Pedro. Durante este viaje, por el que le elogias, oyó cosas que presagiaron su victoria y el manto papal. Después el Vaso de elección fué transportado hasta el cielo para dar más firmeza a la fe, que es el principio del camino de la salvación. Pero yo ¿por qué he de ir?, ¿quién me lo permite? Yo no soy Eneas, ni San Pablo: ante nadie, ni ante mí mismo, me creo digno de tal honor. Porque si me lanzo a tal empresa, temo por mi loco empeño. Puesto que eres sabio, comprenderás las razones que me callo.\"},{\"heading\":false,\"text\":\"Y como aquel que no quiere ya lo que quería, y asaltado de una nueva idea, cambia de parecer, de suerte que abandona todo lo que había comenzado, así me sucedía en aquella obscura cuesta; porque, a fuerza de pensar, abandoné la empresa que había empezado con tanto ardor.\"},{\"heading\":false,\"text\":\"--Si he comprendido bien tus palabras--respondió aquella sombra magnánima--, tu alma está traspasada de espanto, el cual se apodera frecuentemente del hombre, y tanto, que le retrae de una empresa honrosa, como una vana sombra hace a veces retroceder a una fiera, cuando se introduce en la obscuridad. Para librarte de ese temor, te diré por qué he venido, y lo que vi en el primer momento en que me moviste a compasión. Yo estaba entre los que se hallan en suspenso, y me llamó una dama tan bienaventurada y tan bella, que le rogué me diera sus órdenes. Brillaban sus ojos más que la estrella, y empezó a decirme con voz angelical, en su lengua: \\\"¡Oh alma cortés Mantuana, cuya fama dura aún en el mundo y durará mientras su movimiento se prolongue! Mi amigo, que no lo es de la ventura, se ve tan embarazado en la playa desierta, que en medio del camino el miedo le ha hecho retroceder; y temo (por lo que he oído de él en el Cielo) que se haya extraviado ya, y que yo haya acudido tarde en su socorro. Vé, pues, y con tus elocuentes palabras, y con lo que se necesita para sacarle de su apuro, auxíliale tan bien, que yo quede consolada. Yo soy Beatriz, la que te hace marchar; vengo de un sitio adonde deseo volver: amor me impele, y es el que me hace hablar. Cuando vuelva a estar delante de mi Señor, le hablaré de ti bien y con frecuencia.\\\" Calló entonces, y yo repuse: \\\"¡Oh mujer de virtud única, por quien la especie humana excede en dignidad a todos los seres contenidos bajo aquel Cielo que tiene los círculos más pequeños! Tanto me place tu orden, que si ya te hubiera obedecido, creería haber tardado: no tienes necesidad de expresarme más tus deseos. Mas dime: ¿por qué causa no temes descender al fondo de este centro desde lo alto de esos inmensos lugares, adonde ardes en deseos de volver?\\\" \\\"Puesto que tanto quieres saber, te diré brevemente, respondióme, por qué no temo venir a este abismo. Sólo deben temerse las cosas que pueden redundar en perjuicio de otros; pero no aquellas que no inspiran este temor. Por la merced de Dios, estoy hecha de tal suerte, que no me alcanzan vuestras miserias, ni puede prender en mí la llama de este incendio. Hay en el Cielo una dama gentil,[2] que se conduele del obstáculo opuesto al que te envío, y que mitiga el duro juicio de la justicia divina. Ella se ha dirigido a Lucía[3] con sus ruegos, y le ha dicho: \\\"Tu fiel amigo tiene necesidad de ti, y te lo recomiendo.\\\" Lucía, enemiga de todo corazón cruel, se ha conmovido e ido al lugar donde yo me encontraba, sentada al lado de la antigua Raquel. Y me ha dicho: \\\"Beatriz, verdadera alabanza de Dios, ¿no socorres a aquél que te amó tanto, y que por ti salió de la vulgar esfera? ¿No oyes su queja conmovedora? ¿No ves la muerte contra quien combate sobre ese río, más formidable que el mismo mar?\\\" En el mundo no ha habido jamás una persona más pronta en correr hacia un beneficio ni en huír de un peligro, que yo, en cuanto oí tales palabras. Descendí desde mi dichoso puesto, fiándome en esa elocuente palabra que te honra, y que honra a cuantos la han oído.\\\" Después de haberme hablado de este modo, volvió llorando hacia mí sus ojos brillantes, con lo que me hizo partir más presuroso. Y me he dirigido a ti tal como ha sido su voluntad, y te he preservado de aquella fiera que te cerraba el camino más corto de la hermosa montaña. Pero ¿qué tienes?, ¿por qué te suspendes?, ¿por qué abrigas tanta cobardía en tu corazón?, ¿por qué no tienes atrevimiento ni valor, cuando tres mujeres benditas cuidan de ti en la corte celestial, y mis palabras te prometen tanto bien?\"},{\"heading\":false,\"text\":\"[2] La clemencia divina.\"},{\"heading\":false,\"text\":\"[3] La gracia divina, o más bien, la gracia que ilumina.\"},{\"heading\":false,\"text\":\"Y así como las florecillas, inclinadas y cerradas por la escarcha, se abren erguidas en cuanto el Sol las ilumina, así creció mi abatido ánimo, e inundó tal aliento mi corazón, que exclamé como un hombre decidido:\"},{\"heading\":false,\"text\":\"--¡Oh! ¡Cuán piadosa es la que me ha socorrido! ¡Y tú, alma bienhechora, que has obedecido con tal prontitud las palabras de verdad que ella te ha dicho! Con las tuyas has preparado mi corazón de tal suerte, y le has comunicado tanto deseo de emprender el gran viaje, que vuelvo a abrigar mi primer propósito. Vé, pues; que una sola voluntad nos dirija: tú eres mi guía, mi señor, mi maestro.\"},{\"heading\":false,\"text\":\"Así le dije, y en cuanto echó a andar, entré por el camino profundo y salvaje.\"}]},{\"title\":\"Infierno — canto tercero\",\"blocks\":[{\"heading\":false,\"text\":\"\\\"Por mí se va a la ciudad del llanto; por mí se va al eterno dolor; por mi se va hacia la raza condenada: la justicia animó a mi sublime arquitecto; me hizo la divina potestad, la suprema sabiduría y el primer amor. Antes que yo no hubo nada creado, a excepción de lo eterno, y yo duro eternamente. ¡Oh vosotros los que entráis, abandonad toda esperanza!\\\"\"},{\"heading\":false,\"text\":\"Vi escritas estas palabras con caracteres negros en el dintel de una puerta, por lo cual exclamé:\"},{\"heading\":false,\"text\":\"--Maestro, el sentido de estas palabras me causa pena.\"},{\"heading\":false,\"text\":\"Y él, como hombre lleno de prudencia, me contestó:\"},{\"heading\":false,\"text\":\"--Conviene abandonar aquí todo temor; conviene que aquí termine toda cobardía. Hemos llegado al lugar donde te he dicho que verías a la dolorida gente, que ha perdido el bien de la inteligencia.\"},{\"heading\":false,\"text\":\"Y después de haber puesto su mano en la mía con rostro alegre, que me reanimó, me introdujo en medio de las cosas secretas. Allí, bajo un cielo sin estrellas, resonaban suspiros, quejas y profundos gemidos, de suerte que al escucharlos comencé a llorar. Diversas lenguas, horribles blasfemias, palabras de dolor, acentos de ira, voces altas y roncas, acompañadas de palmadas, producían un tumulto que va rodando siempre por aquel espacio eternamente obscuro, como la arena impelida por un torbellino. Yo, que estaba horrorizado, dije:\"},{\"heading\":false,\"text\":\"--Maestro, ¿qué es lo que oigo, y qué gente es ésa, que parece doblegada por el dolor?\"},{\"heading\":false,\"text\":\"Me respondió:\"},{\"heading\":false,\"text\":\"--Esta miserable suerte está reservada a las tristes almas de aquellos que vivieron sin merecer alabanzas ni vituperio: están confundidas entre el perverso coro de los ángeles que no fueron rebeldes ni fieles a Dios, sino que sólo vivieron para sí. El Cielo los lanzó de su seno por no ser menos hermoso; pero el profundo Infierno no quiere recibirlos por la gloria que con ello podrían reportar los demás culpables.\"},{\"heading\":false,\"text\":\"Y yo repuse:\"},{\"heading\":false,\"text\":\"--Maestro, ¿qué cruel dolor les hace lamentarse tanto?\"},{\"heading\":false,\"text\":\"A lo que me contestó:\"},{\"heading\":false,\"text\":\"--Te lo diré brevemente. Estos no esperan morir; y su ceguedad es tanta, que se muestran envidiosos de cualquier otra suerte. El mundo no conserva ningún recuerdo suyo; la misericordia y la justicia los desdeñan: no hablemos más de ellos, míralos y pasa adelante.\"},{\"heading\":false,\"text\":\"Y yo, fijándome más, vi una bandera que iba ondeando tan de prisa, que parecía desdeñosa del menor reposo: tras ella venía tanta muchedumbre, que no hubiera creído que la muerte destruyera tan gran número. Después de haber reconocido a algunos, miré más fijamente, y vi la sombra de aquel que por cobardía hizo la gran renuncia[4]. Comprendí inmediatamente y adquirí la certeza de que aquella turba era la de los ruines que se hicieron desagradables a los ojos de Dios y a los de sus enemigos. Aquellos desgraciados, que no vivieron nunca, estaban desnudos, y eran molestados sin tregua por las picaduras de las moscas y de las avispas que allí había; las cuales hacían correr por su rostro la sangre, que mezclada con sus lágrimas, era recogida a sus pies por asquerosos gusanos.\"},{\"heading\":false,\"text\":\"[4] Según algunos comentadores, éste debe ser Esaú, que renunció a su derecho de primogenitura; según otros, Diocleciano, que abdicó el imperio; según Venturini, el papa Celestino V, y otros creen que el que hizo la gran renuncia es Pilatos.\"},{\"heading\":false,\"text\":\"Habiendo dirigido mis miradas a otra parte, vi nuevas almas a la orilla de un gran río, por lo cual, dije:\"},{\"heading\":false,\"text\":\"--Maestro, dígnate manifestarme quiénes son y por qué ley parecen ésos tan prontos a atravesar el río, según puedo ver a favor de esta débil claridad.\"},{\"heading\":false,\"text\":\"Y él me respondió:\"},{\"heading\":false,\"text\":\"--Te lo diré cuando pongamos nuestros pies sobre la triste orilla del Aqueronte.\"},{\"heading\":false,\"text\":\"Entonces, avergonzado y con los ojos bajos, temiendo que le disgustasen mis preguntas, me abstuve de hablar hasta que llegamos al río. En aquel momento vimos un anciano cubierto de canas, que se dirigía hacia nosotros en una barquichuela, gritando: \\\"¡Ay de vosotras, almas perversas! No esperéis ver nunca el Cielo. Vengo para conduciros a la otra orilla, donde reinan eternas tinieblas, en medio del calor y del frío. Y tú, alma viva, que estás aquí, aléjate de entre esas que están muertas.\\\" Pero cuando vió que yo no me movía, dijo: \\\"Llegarás a la playa por otra orilla, por otro puerto, mas no por aquí: para llevarte se necesita una barca más ligera.\\\"\"},{\"heading\":false,\"text\":\"Y mi guía le dijo:\"},{\"heading\":false,\"text\":\"--Carón, no te irrites. Así se ha dispuesto allí donde se puede todo lo que se quiere; y no preguntes más.\"},{\"heading\":false,\"text\":\"Entonces se aquietaron las velludas mejillas del barquero de las lívidas lagunas, que tenía círculos de llamas alrededor de sus ojos. Pero aquellas almas, que estaban desnudas y fatigadas, no bien oyeron tan terribles palabras, cambiaron de color, rechinando los dientes, blasfemando de Dios, de sus padres, de la especie humana, del sitio y del día de su nacimiento, de la prole de su prole y de su descendencia: después se retiraron todas juntas, llorando fuertemente, hacia la orilla maldita en donde se espera a todo aquel que no teme a Dios. El demonio Carón, con ojos de ascuas, haciendo una señal, las fué reuniendo, golpeando con su remo a las que se rezagaban; y así como en otoño van cayendo las hojas una tras otra, hasta que las ramas han devuelto a la tierra todos sus despojos, del mismo modo los malvados hijos de Adán se lanzaban uno a uno desde la orilla, a aquella señal, como pájaros que acuden al reclamo. De esta suerte se fueron alejando por las negras ondas; pero antes de que hubieran saltado en la orilla opuesta, se reunió otra nueva muchedumbre en la que aquéllas habían dejado.\"},{\"heading\":false,\"text\":\"--Hijo mío--me dijo el cortés Maestro--, los que mueren en la cólera de Dios acuden aquí de todos los países, y se apresuran a atravesar el río, espoleados de tal suerte por la justicia divina, que su temor se convierte en deseo. Por aquí no pasa nunca un alma pura; por lo cual, si Carón se irrita contra ti, ya conoces ahora el motivo de sus desdeñosas palabras.\"},{\"heading\":false,\"text\":\"Apenas hubo terminado, tembló tan fuertemente la sombría campiña, que el recuerdo del espanto que sentí aún me inunda la frente de sudor. De aquella tierra de lágrimas salió un viento que produjo rojizos relámpagos, haciéndome perder el sentido y caer como un hombre sorprendido por el sueño.\"}]},{\"title\":\"Infierno — canto cuarto\",\"blocks\":[{\"heading\":false,\"text\":\"Interrumpió mi profundo sueño un trueno tan fuerte, que me estremecí como hombre a quien se despierta a la fuerza: me levanté, y dirigiendo una mirada en derredor mío, fijé la vista para reconocer el lugar donde me hallaba. Vime junto al borde del triste valle, abismo de dolor, en que resuenan infinitos ayes, semejantes a truenos. El abismo era tan profundo, obscuro y nebuloso, que en vano fijaba mis ojos en su fondo, pues no distinguía cosa alguna.\"},{\"heading\":false,\"text\":\"--Ahora descendamos allá abajo, al tenebroso mundo--me dijo el poeta muy pálido--: yo iré el primero; tú el segundo.\"},{\"heading\":false,\"text\":\"Yo, que había advertido su palidez, le respondí:\"},{\"heading\":false,\"text\":\"--¿Cómo he de ir yo, si tú, que sueles desvanecer mis incertidumbres, te atemorizas?\"},{\"heading\":false,\"text\":\"Y él repuso:\"},{\"heading\":false,\"text\":\"--La angustia de los desgraciados que están ahí bajo, refleja en mi rostro una piedad que tú tomas por terror. Vamos, pues; que la longitud del camino exige que nos apresuremos.\"},{\"heading\":false,\"text\":\"Y sin decir más, penetró y me hizo entrar en el primer círculo que rodea el abismo. Allí, según pude advertir, no se oían quejas, sino sólo suspiros, que hacían temblar la eterna bóveda, y que procedían de la pena sin tormento de una inmensa multitud de hombres, mujeres y niños. El buen Maestro me dijo:\"},{\"heading\":false,\"text\":\"--¿No me preguntas qué espíritus son los que estamos viendo? Quiero, pues, que sepas, antes de seguir adelante, que éstos no pecaron; y si contrajeron en su vida algunos méritos, no es bastante, pues no recibieron el agua del bautismo, que es la puerta de la Fe que forma tu creencia. Y si vivieron antes del cristianismo, no adoraron a Dios como debían: yo también soy uno de ellos. Por tal falta, y no por otra culpa, estamos condenados, consistiendo nuestra pena en vivir con el deseo sin esperanza.\"},{\"heading\":false,\"text\":\"Un gran dolor afligió mi corazón cuando oí esto, porque conocí personas de mucho valor que estaban suspensas en el Limbo.\"},{\"heading\":false,\"text\":\"--Dime, Maestro y señor mío--le pregunté para afirmarme más en esta Fe que triunfa de todo error;--¿alguna de esas almas ha podido, bien por sus méritos o por los de otros, salir del Limbo y alcanzar la bienaventuranza?\"},{\"heading\":false,\"text\":\"Y él, que comprendió mis palabras encubiertas y obscuras, repuso:\"},{\"heading\":false,\"text\":\"--Yo era recién llegado a este sitio, cuando vi venir a un Sér poderoso, coronado con la señal de la victoria. Hizo salir de aquí el alma del primer padre, y la de Abel su hijo, y la de Noé; la del legislador Moisés, tan obediente; la del patriarca Abraham, y la del rey David; a Israel, con su padre y con sus hijos, y a Raquel por quien aquél hizo tanto,[5] y a otros muchos, a quienes otorgó la bienaventuranza; pues debes saber que, antes de ellos, no se salvaban las almas humanas.\"},{\"heading\":false,\"text\":\"[5] Se refiere a Jacobo o Israel, que por casarse con Raquel sirvió al padre de ella catorce años.\"},{\"heading\":false,\"text\":\"Mientras así hablaba, no dejábamos de andar; pero seguíamos atravesando siempre la selva, esto es, la selva que formaban los espíritus apiñados. Aun no estábamos muy lejos de la entrada del abismo, cuando vi un resplandor que triunfaba del hemisferio de las tinieblas: nos encontrábamos todavía a bastante distancia, pero no a tanta que no pudiera yo distinguir que aquel sitio estaba ocupado por personas dignas.\"},{\"heading\":false,\"text\":\"--Oh tú, que honras toda ciencia y todo arte, ¿quiénes son ésos, cuyo valimiento debe ser tanto, que así están separados de los demás?\"},{\"heading\":false,\"text\":\"Y él a mí:\"},{\"heading\":false,\"text\":\"--La hermosa fama que aún se conserva de ellos en el mundo que habitas, les hace acreedores a esta gracia del cielo, que de tal suerte los distingue.\"},{\"heading\":false,\"text\":\"Entonces oí una voz que decía: \\\"¡Honrad al sublime poeta; regresa su sombra, que se había separado de nosotros!\\\" Cuando calló la voz, vi venir a nuestro encuentro cuatro grandes sombras, cuyo rostro no manifestaba tristeza ni alegría. El buen maestro empezó a decirme:\"},{\"heading\":false,\"text\":\"--Mira aquel que tiene una espada en la mano, y viene a la cabeza de los tres como su señor. Ese es Homero, poeta soberano: el otro es el satírico Horacio, Ovidio es el tercero y el último Lucano. Cada cual merece, como yo, el nombre que antes pronunciaron unánimes; me honran y hacen bien.\"},{\"heading\":false,\"text\":\"De este modo vi reunida la hermosa escuela de aquel príncipe del sublime cántico, que vuela como el águila sobre todos los demás.\"},{\"heading\":false,\"text\":\"Después de haber estado conversando entre sí un rato, se volvieron hacia mí dirigiéndome un amistoso saludo, que hizo sonreír a mi Maestro; y me honraron aún más, puesto que me admitieron en su compañía, de suerte que fuí el sexto entre aquellos grandes genios. Así seguimos hasta donde estaba la luz, hablando de cosas que es bueno callar, como bueno era hablar de ellas en el sitio en que nos encontrábamos. Llegamos al pie de un noble castillo, rodeado siete veces de altas murallas, y defendido alrededor por un bello riachuelo. Pasamos sobre éste como sobre tierra firme; y atravesando siete puertas con aquellos sabios, llegamos a un prado de fresca verdura. Allí había personajes de mirada tranquila y grave, cuyo semblante revelaba una grande autoridad: hablaban poco y con voz suave. Nos retiramos luego hacia un extremo de la pradera; a un sitio despejado, alto y luminoso, desde donde podían verse todas aquellas almas. Allí, en pie sobre el verde esmalte, me fueron señalados los grandes espíritus, cuya contemplación me hizo estremecer de alegría. Allí vi a Electra con muchos de sus compañeros, entre los que conocí a Héctor y a Eneas; después a César, armado, con sus ojos de ave de rapiña. Vi en otra parte a Camila y a Pentesilea, y vi al Rey Latino, que estaba sentado al lado de su hija Lavinia; vi a aquel Bruto, que arrojó a Tarquino de Roma; a Lucrecia también, a Julia, a Marcia y a Cornelia, y a Saladino, que estaba solo y separado de los demás. Habiendo levantado después la vista, vi al maestro de los que saben,[6] sentado entre su filosófica familia. Todos le admiran, todos le honran: vi además a Sócrates y Platón, que estaban más próximos a aquél que los demás; a Demócrito, que pretende que el mundo ha tenido por origen la casualidad; a Diógenes, a Anaxágoras y a Tales, a Empédocles, a Heráclito y a Zenón: vi al buen observador de la cualidad, es decir, a Dioscórides, y vi a Orfeo, a Tulio y a Lino, y al moralista Séneca; al geómetra Euclides, a Tolomeo, Hipócrates, Avicena y Galeno, y a Averroes, que hizo el gran comentario. No me es posible mencionarlos a todos, porque me arrastra el largo tema que he de seguir y muchas veces las palabras son breves para el asunto. Bien pronto la compañía de seis queda reducida a dos: mi sabio guía me conduce por otro camino fuera de aquella inmovilidad hacia una aura temblorosa, y llego a un punto privado totalmente de luz.\"},{\"heading\":false,\"text\":\"[6] El filósofo Aristóteles.\"}]},{\"title\":\"Infierno — canto quinto\",\"blocks\":[{\"heading\":false,\"text\":\"Así descendí del primer círculo al segundo, que contiene menos espacio, pero mucho más dolor, y dolor punzante, que origina desgarradores gritos. Allí estaba el horrible Minos que, rechinando los dientes, examina las culpas de los que entran; juzga y da a comprender sus órdenes por medio de las vueltas de su cola. Es decir, que cuando se presenta ante él un alma pecadora, y le confiesa todas sus culpas, aquel gran conocedor de los pecados ve qué lugar del infierno debe ocupar y se lo designa, ciñéndose al cuerpo la cola tantas veces cuantas sea el número del círculo a que debe ser enviada. Ante él están siempre muchas almas, acudiendo por turno para ser juzgadas; hablan y escuchan, y después son arrojadas al abismo.\"},{\"heading\":false,\"text\":\"--¡Oh, tú, que vienes a la mansión del dolor!--me gritó Minos cuando me vió, suspendiendo sus terribles funciones--; mira cómo entras y de quién te fías: no te alucine lo anchuroso de la entrada.\"},{\"heading\":false,\"text\":\"Entonces mi guía le preguntó:\"},{\"heading\":false,\"text\":\"--¿Por qué gritas? No te opongas a su viaje ordenado por el destino: así lo han dispuesto allí donde se puede lo que se quiere; y no preguntes más.\"},{\"heading\":false,\"text\":\"Empezaron a dejarse oír voces plañideras: y llegué a un sitio donde hirieron mis oídos grandes lamentos. Entrábamos en un lugar que carecía de luz, y que rugía como el mar tempestuoso cuando está combatido por vientos contrarios. La tromba infernal, que no se detiene nunca, envuelve en su torbellino a los espíritus; les hace dar vueltas continuamente, y les agita y les molesta: cuando se encuentran ante la ruinosa valla que los encierra, allí son los gritos, los llantos y los lamentos, y las blasfemias contra la virtud divina. Supe que estaban condenados a semejante tormento los pecadores carnales que sometieron la razón a sus lascivos apetitos; y así como los estorninos vuelan en grandes y compactas bandadas en la estación de los fríos, así aquel torbellino arrastra a los espíritus malvados llevándolos de acá para allá, de arriba abajo, sin que abriguen nunca la esperanza de tener un momento de reposo, ni de que su pena se aminore. Y del mismo modo que las grullas van lanzando sus tristes acentos, formando todas una prolongada hilera en el aire, así también vi venir, exhalando gemidos, a las sombras arrastradas por aquella tromba. Por lo cual pregunté:\"},{\"heading\":false,\"text\":\"--Maestro, ¿qué almas son ésas a quienes de tal suerte castiga ese aire negro?\"},{\"heading\":false,\"text\":\"--La primera de ésas, de quienes deseas noticias--me dijo entonces--, fué emperatriz de una multitud de pueblos donde se hablaban diferentes lenguas, y tan dada al vicio de la lujuria, que permitió en sus leyes todo lo que excitaba el placer, para ocultar de este modo la abyección en que vivía. Es Semíramis, de quien se lee que sucedió a Nino y fué su esposa y reinó en la tierra en donde impera el Sultán. La otra es la que se mató por amor y quebrantó la fe prometida a las cenizas de Siqueo. Después sigue la lasciva Cleopatra. Ve también a Helena, que dió lugar a tan funestos tiempos; y ve al gran Aquiles, que al fin tuvo que combatir por el amor. Ve a París y a Tristán....\"},{\"heading\":false,\"text\":\"Y a más de mil sombras me fué enseñando y designando con el dedo, a quienes Amor había hecho salir de esta vida. Cuando oí a mi sabio nombrar las antiguas damas y los caballeros, me sentí dominado por la piedad y quedé como aturdido. Empecé a decir:\"},{\"heading\":false,\"text\":\"--Poeta, quisiera hablar a aquellas dos almas que van juntas y parecen más ligeras que las otras impelidas por el viento.\"},{\"heading\":false,\"text\":\"Y él me contestó:\"},{\"heading\":false,\"text\":\"--Espera que estén más cerca de nosotros: y entonces ruégales, por el amor que las conduce, que se dirijan hacia ti.\"},{\"heading\":false,\"text\":\"Tan pronto como el viento las impulsó hacia nosotros, alcé la voz diciendo:\"},{\"heading\":false,\"text\":\"--¡Oh almas atormentadas!, venid a hablarnos, si otro no se opone a ello.\"},{\"heading\":false,\"text\":\"Así como dos palomas, excitadas por sus deseos, se dirigen con las alas abiertas y firmes hacia el dulce nido, llevadas en el aire por una misma voluntad, así salieron aquellas dos almas de entre la multitud donde estaba Dido, dirigiéndose hacia nosotros a través del aire malsano, atraídas por mi eficaz y afectuoso llamamiento.\"},{\"heading\":false,\"text\":\"--¡Oh sér gracioso y benigno, que vienes a visitar enmedio de este aire negruzco a los que hemos teñido el mundo de sangre! Si fuéramos amados por el Rey del universo, le rogaríamos por tu tranquilidad, ya que te compadeces de nuestro acerbo dolor. Todo lo que te agrade oír y decir, te lo diremos y escucharemos con gusto mientras que siga el viento tan tranquilo como ahora. La tierra donde nací está situada en la costa donde desemboca el Po con todos sus afluentes para descansar en el mar. Amor, que se apodera pronto de un corazón gentil, hizo que éste se prendara de aquel hermoso cuerpo que me fué arrebatado de un modo que aún me atormenta. Amor, que no dispensa de amar al que es amado, hizo que me entregara vivamente al placer de que se embriagaba éste, que, como ves, no me abandona nunca. Amor nos condujo a la misma muerte. Caína[7] espera al que nos arrancó la vida.\"},{\"heading\":false,\"text\":\"[7] La primera de las cuatro divisiones concéntricas del último círculo del Infierno, en donde son castigados los traidores y los matadores de sus propios consanguíneos. Véase el canto trigésimo segundo.\"},{\"heading\":false,\"text\":\"Tales fueron las palabras de las dos sombras. Al oír a aquellas almas atormentadas, bajé la cabeza y la tuve inclinada tanto tiempo, que el poeta me dijo:\"},{\"heading\":false,\"text\":\"--¿En qué piensas?\"},{\"heading\":false,\"text\":\"--¡Ah!--exclamé al contestarle--; ¡cuán dulces pensamientos, cuántos deseos les han conducido a doloroso tránsito!\"},{\"heading\":false,\"text\":\"Después me dirigí hacia ellos, diciéndoles:\"},{\"heading\":false,\"text\":\"--Francisca, tus desgracias me hacen derramar tristes y compasivas lágrimas. Pero dime: en tiempo de los dulces suspiros ¿cómo os permitió Amor conocer vuestros secretos deseos?\"},{\"heading\":false,\"text\":\"Ella me contestó:\"},{\"heading\":false,\"text\":\"--No hay mayor dolor que acordarse del tiempo feliz en la miseria; y eso lo sabe bien tu Maestro. Pero si tienes tanto deseo de conocer cuál fué el principal origen de nuestro amor, haré como el que habla y llora a la vez. Leíamos un día por pasatiempo las aventuras de Lancelote, y de qué modo cayó en las redes del Amor: estábamos solos y sin abrigar sospecha alguna. Aquella lectura hizo que nuestros ojos se buscaran muchas veces y que palideciera nuestro semblante; mas un solo pasaje fué el que decidió de nosotros. Cuando leímos que la deseada sonrisa de la amada fué interrumpida por el beso del amante, éste, que jamás se ha de separar de mí, me besó tembloroso en la boca: el libro y quien lo escribió fué para nosotros otro Galeoto; aquel día ya no leímos más.\"},{\"heading\":false,\"text\":\"Mientras que un alma decía esto, la otra lloraba de tal modo, que, movido de compasión, desfallecí como si me muriera, y caí como cae un cuerpo inanimado.\"}]},{\"title\":\"Infierno — canto sexto\",\"blocks\":[{\"heading\":false,\"text\":\"Al recobrar los sentidos, que perdí por la tristeza y la compasión que me causó la suerte de los dos cuñados, vi en derredor mío nuevos tormentos y nuevas almas atormentadas doquier iba y doquier me volvía o miraba. Me encuentro en el tercer círculo; en el de la lluvia eterna, maldita, fría y densa, que cae siempre igualmente copiosa y con la misma fuerza. Espesos granizos, agua negruzca y nieve descienden en turbión a través de las tinieblas; la tierra, al recibirlos, exhala un olor pestífero. Cerbero, fiera cruel y monstruosa, ladra con sus tres fauces de perro contra los condenados que están allí sumergidos. Tiene los ojos rojos, los pelos negros y cerdosos, el vientre ancho y las patas guarnecidas de uñas que clava en los espíritus, les desgarra la piel y les descuartiza. La lluvia les hace aullar como perros; los miserables condenados forman entre sí una muralla con sus costados y se revuelven sin cesar. Cuando nos descubrió Cerbero, el gran gusano abrió las bocas enseñándonos sus colmillos; todos sus miembros estaban agitados. Entonces mi guía extendió las manos, cogió tierra, y la arrojó a puñados en las fauces ávidas de la fiera. Y del mismo modo que un perro se deshace ladrando al tener hambre, y se apacigua cuando muerde su presa, ocupado tan sólo en devorarla, así también el demonio Cerbero cerró sus impuras bocas, cuyos ladridos causaban tal aturdimiento a las almas que quisieran quedarse sordas. Pasamos por encima de las sombras derribadas por la incesante lluvia, poniendo nuestros pies sobre sus fantasmas, que parecían cuerpos humanos. Todas yacían por el suelo, excepto una que se levantó con presteza para sentarse, cuando nos vió pasar ante ella.\"},{\"heading\":false,\"text\":\"--¡Oh, tú, que has venido a este Infierno!--me dijo--; reconóceme si puedes. Tú fuiste hecho, antes que yo deshecho.\"},{\"heading\":false,\"text\":\"Yo le contesté:\"},{\"heading\":false,\"text\":\"--La angustia que te atormenta es quizá causa de que no me acuerde de ti; me parece que no te he visto nunca. Pero dime, ¿quién eres tú, que a tan triste lugar has sido conducido, y condenado a un suplicio, que si hay otro mayor, no será por cierto tan desagradable?\"},{\"heading\":false,\"text\":\"Contestóme:\"},{\"heading\":false,\"text\":\"--Tu ciudad, tan llena hoy de envidia, que ya colma la medida, me vió en su seno en vida más serena. Vosotros, los habitantes de esa ciudad, me llamasteis Ciacco. Por el reprensible pecado de la gula, me veo, como ves, sufriendo esta lluvia. Yo no soy aquí la única alma triste; todas las demás están condenadas a igual pena por la misma causa.\"},{\"heading\":false,\"text\":\"Y no pronunció una palabra más. Yo le respondí:\"},{\"heading\":false,\"text\":\"--Ciacco, tu martirio me conmueve tanto, que me hace verter lágrimas; pero dime, si es que lo sabes: ¿en qué pararán los habitantes de esa ciudad tan dividida en facciones? ¿Hay algún justo entre ellos? Dime por qué razón se ha introducido en ella la discordia.\"},{\"heading\":false,\"text\":\"Me contestó:\"},{\"heading\":false,\"text\":\"--Después de grandes debates, llegarán a verter su sangre, y el partido salvaje arrojará al otro partido causándole grandes pérdidas. Luego será preciso que el partido vencedor sucumba al cabo de tres años, y que el vencido se eleve, merced a la ayuda de aquel que ahora es neutral. Esta facción llevará la frente erguida por mucho tiempo, teniendo bajo su férreo yugo a la otra, por más que ésta se lamente y avergüence. Aun hay dos justos, pero nadie les escucha: la soberbia, la envidia y la avaricia son las tres chispas que han inflamado los corazones.\"},{\"heading\":false,\"text\":\"Aquí dió Ciacco fin a su lamentable discurso, y yo le dije:\"},{\"heading\":false,\"text\":\"--Todavía quiero que me informes, y me concedas algunas palabras. Dime dónde están, y dame a conocer a Farinata y al Tegghiaio, que fueron tan dignos, a Jacobo Rusticucci, Arigo y Mosca, y a otros que a hacer bien consagraron su ingenio, pues siento un gran deseo de saber si están entre las dulzuras del Cielo o entre las amarguras del Infierno.\"},{\"heading\":false,\"text\":\"A lo que me contestó:\"},{\"heading\":false,\"text\":\"--Están entre almas más perversas; otros pecados los han arrojado a un círculo más profundo: si bajas hasta allí, podrás verlos. Pero cuando vuelvas al dulce mundo, te ruego que hagas porque en él se renueve mi recuerdo: y no te digo ni te respondo más.\"},{\"heading\":false,\"text\":\"Entonces torció los ojos que había tenido fijos; miróme un momento, y luego inclinó la cabeza, y volvió a caer entre los demás ciegos. Mi guía me dijo:\"},{\"heading\":false,\"text\":\"--Ya no volverá a levantarse hasta que se oiga el sonido de la angélica trompeta; cuando venga la potestad enemiga del pecado. Cada cual encontrará entonces su triste tumba; recobrará sus carnes y su figura; y oirá el juicio que debe resonar por toda una eternidad.\"},{\"heading\":false,\"text\":\"Así fuimos atravesando aquella impura mezcla de sombras y de lluvia, con paso lento, razonando un poco sobre la vida futura. Por lo cual dije:\"},{\"heading\":false,\"text\":\"--Maestro, ¿estos tormentos serán mayores después de la gran sentencia, o bien menores, o seguirán siendo tan dolorosos?\"},{\"heading\":false,\"text\":\"Y él a mí:\"},{\"heading\":false,\"text\":\"--Acuérdate de tu ciencia, que pretende que cuanto más perfecta es una cosa, tanto mayor bien o dolor experimenta. Aunque esta raza maldita no debe jamás llegar a la verdadera perfección, espera ser después del juicio más perfecta que ahora.\"},{\"heading\":false,\"text\":\"Caminando por la vía que gira alrededor del círculo, continuamos hablando de otras cosas que no refiero, y llegamos al sitio donde se desciende: allí encontramos a Plutón, el gran enemigo.\"}]},{\"title\":\"Infierno — canto septimo\",\"blocks\":[{\"heading\":false,\"text\":\"\\\"Pape satán, pape satán aleppe\\\"[8] comenzó a gritar Plutón con ronca voz. Y aquel sabio gentil, que lo supo todo, para animarme, dijo:\"},{\"heading\":false,\"text\":\"[8] Pape, interjección griega y latina, que significa sorpresa; aleppe, lo mismo que aleph (o Ioseph), voz hebraica, equivalente a jefe, príncipe, etc. La frase, truncada por reticencia, quiere decir: \\\"¡Cómo, Satanás; cómo, Satanás, príncipe del Infierno!... ¿Un audaz mortal se atreve a entrar aquí?\\\"--Fraticelli.\"},{\"heading\":false,\"text\":\"--No te inquiete el temor; pues a pesar de su poder, no te impedirá que desciendas a este círculo.\"},{\"heading\":false,\"text\":\"Después, volviéndose hacia aquel rostro hinchado de ira, le dijo:\"},{\"heading\":false,\"text\":\"--Calla, lobo maldito: consúmete interiormente con tu propia rabia. No sin razón venimos al profundo infierno; pues así lo han dispuesto allá arriba, donde Miguel castigó la soberbia rebelión.\"},{\"heading\":false,\"text\":\"Como las velas, hinchadas por el viento, caen derribadas cuando el mástil se rompe, del mismo modo cayó al suelo aquella fiera cruel. Así bajamos a la cuarta cavidad, aproximándonos más a la dolorosa orilla que encierra en sí todo el mal del universo. ¡Ah, justicia de Dios!, ¿quién, si no tú, puede amontonar tantas penas y trabajos como allí vi? ¿Por qué nos desgarran así nuestras propias faltas? Como una ola se estrella contra otra ola en el escollo de Caribdis, así chocan uno contra otro los condenados. Allí vi más condenados que en ninguna otra parte, los cuales formados en dos filas, se lanzaban de la una a la otra enormes pesos con todo el esfuerzo de su pecho, gritando fuertemente: dábanse grandes golpes, y después se volvían cada cual hacia atrás, exclamando: \\\"¿Por qué guardas? ¿Por qué derrochas?\\\" De esta suerte iban girando por aquel tétrico círculo, yendo desde un extremo a su opuesto, y repitiendo a gritos su injurioso estribillo. Después, cuando cada cual había llegado al centro de su círculo, se volvían todos a la vez para empezar de nuevo otra pelea.\"},{\"heading\":false,\"text\":\"Yo, que tenía el corazón conmovido de lástima, dije:\"},{\"heading\":false,\"text\":\"--Maestro mío, indícame qué gente es ésta. Todos esos tonsurados que vemos a nuestra izquierda ¿han sido clérigos?\"},{\"heading\":false,\"text\":\"Y él me respondió:\"},{\"heading\":false,\"text\":\"--Erró la mente de todos en la primera vida, y no supieron gastar razonablemente: así lo manifiestan claramente sus aullidos cuando llegan a los dos puntos del círculo que los separa de los que siguieron camino opuesto. Esos que no tienen cabellos que cubran su cabeza, fueron clérigos, papas y cardenales, a quienes subyugó la avaricia.\"},{\"heading\":false,\"text\":\"Y yo:\"},{\"heading\":false,\"text\":\"--Maestro, entre todos ésos, bien deberá haber algunos a quienes yo conozca y a quienes tan inmundos hizo este vicio.\"},{\"heading\":false,\"text\":\"Y él a mí:\"},{\"heading\":false,\"text\":\"--En vano esforzarás tu imaginación: la vida sórdida que los hizo deformes, hace que hoy sean obscuros y desconocidos. Continuarán chocando entre sí eternamente; y saldrán éstos del sepulcro con los puños cerrados, y aquéllos con el cabello rapado. Por haber gastado mal y guardado mal, han perdido el Paraíso, y se ven condenados a ese eterno combate, que no necesito pintarte con palabras escogidas. Ahí podrás ver, hijo mío, cuán rápidamente pasa el soplo de los bienes de la Fortuna, por los que la raza humana se enorgullece y querella. Todo el oro que existe bajo la Luna, y todo lo que ha existido, no puede dar un momento de reposo a una sola de esas almas fatigadas.\"},{\"heading\":false,\"text\":\"--Maestro--le dije entonces--, enséñame cuál es esa Fortuna de que me hablas, y que así tiene entre sus manos los bienes del mundo.\"},{\"heading\":false,\"text\":\"Y él a mí:\"},{\"heading\":false,\"text\":\"--¡Oh necias criaturas! ¡Cuán grande es la ignorancia que os extravía! Quiero que te alimentes con mis lecciones. Aquél, cuya sabiduría es superior a todo, hizo los cielos y les dió un guía, de modo que toda parte brilla para toda parte, distribuyendo la luz por igual; con el esplendor del mundo hizo lo mismo, y le dió una guía, que administrándolo todo, hiciera pasar de tiempo en tiempo las vanas riquezas de una a otra familia, de una a otra nación, a pesar de los obstáculos que crean la prudencia y previsión humanas. He aquí por qué, mientras una nación impera, otra languidece, según el juicio de Aquél que está oculto, como la serpiente en la hierba. Vuestro saber no puedo contrastarla; porque provee, juzga y prosigue su reinado, como el suyo cada una de las otras deidades. Sus transformaciones no tienen tregua; la necesidad la obliga a ser rápida; por eso se cambia todo en el mundo con tanta frecuencia. Tal es esa a quien tan a menudo vituperan los mismos que deberían ensalzarla, y de quien blasfeman y maldicen sin razón. Pero ella es feliz, y no oye esas maldiciones: contenta entre las primeras criaturas, prosigue su obra y goza en su beatitud. Bajemos ahora donde existen mayores y más lamentables males: ya descienden todas las estrellas que salían cuando me puse en marcha, y nos está prohibido retrasarnos mucho.\"},{\"heading\":false,\"text\":\"Atravesamos el círculo hasta la otra orilla, sobre un hirviente manantial, que vierte sus aguas en un arroyo que le debe su origen y cuyas aguas son más bien obscuras que azuladas; y bajamos por un camino distinto, siguiendo el curso de tan tenebrosas ondas. Cuando aquel arroyo ha llegado al pie de la playa gris e infecta, forma una laguna llamada Estigia; y yo, que miraba atentamente, vi algunas almas encenagadas en aquel pantano, completamente desnudas y de irritado semblante. Se golpeaban no sólo con las manos, sino con la cabeza, con el pecho, con los pies, arrancándose la carne a pedazos con los dientes. Díjome el buen Maestro:\"},{\"heading\":false,\"text\":\"--Hijo, contempla las almas de los que han sido dominados por la ira: quiero además que sepas que bajo esta agua hay una raza condenada que suspira, y la hace hervir en la superficie, como te lo indican tus miradas en cuantos sitios se fijan. Metidos en el lodo, dicen: \\\"Estuvimos siempre tristes bajo aquel aire dulce que alegra el Sol, llevando en nuestro interior una tétrica humareda: ahora nos entristecemos también en medio de este negro cieno.\\\" Estas palabras salen del fondo de su garganta, como si formaran gárgaras, no pudiendo pronunciar una sola íntegra.\"},{\"heading\":false,\"text\":\"Así fuimos describiendo un gran arco alrededor del fétido pantano, entre la playa seca y el agua, vueltos los ojos hacia los que se atragantaban con el fango, hasta que al fin llegamos al pie de una torre.\"}]},{\"title\":\"Infierno — canto octavo\",\"blocks\":[{\"heading\":false,\"text\":\"Digo, continuando, que mucho antes de llegar al pie de la elevada torre, nuestros ojos se fijaron en su parte más alta, a causa de dos lucecitas que allí vimos, y otra que correspondía a estas dos, pero desde tan lejos, que apenas podía distinguirse. Entonces, dirigiéndome hacia el mar de toda ciencia, dije:\"},{\"heading\":false,\"text\":\"--¿Qué significan esas llamas? ¿Qué responde aquella otra, y quiénes son los que hacen esas señales?\"},{\"heading\":false,\"text\":\"Respondióme:\"},{\"heading\":false,\"text\":\"--Sobre esas aguas fangosas puedes ver lo que ha de venir, si es que no te lo ocultan los vapores del pantano.\"},{\"heading\":false,\"text\":\"Jamás cuerda alguna despidió una flecha que corriese por el aire con tanta velocidad, como una navecilla que vi surcando las aguas en nuestra dirección, gobernada por un solo remero que gritaba: \\\"¿Has llegado ya, alma vil?\\\"\"},{\"heading\":false,\"text\":\"--Flegias, Flegias, gritas en vano esta vez--dijo mi Señor--; no nos tendrás en tu poder más tiempo que el necesario para pasar la laguna.\"},{\"heading\":false,\"text\":\"Flegias, conteniendo su cólera, hizo lo que un hombre a quien descubren que ha sido víctima de un engaño, ocasionándole esto un dolor profundo. Mi guía saltó a la barca y me hizo entrar en ella tras él; pero aquélla no pareció ir cargada hasta que recibió mi peso. En cuanto ambos estuvimos dentro, la antigua proa partió trazando en el agua una estela más profunda de lo que solía cuando llevaba otros pasajeros. Mientras recorríamos aquel canal de agua estancada, se me presentó una sombra llena de lodo, y me preguntó:\"},{\"heading\":false,\"text\":\"--¿Quién eres tú, que vienes antes de tiempo?\"},{\"heading\":false,\"text\":\"A lo que contesté:\"},{\"heading\":false,\"text\":\"--Si he venido, no es para permanecer aquí; mas dime ¿quién eres tú, que tan sucio estás?\"},{\"heading\":false,\"text\":\"Respondióme:\"},{\"heading\":false,\"text\":\"--Ya ves que soy uno de los que lloran.\"},{\"heading\":false,\"text\":\"Y yo a él:\"},{\"heading\":false,\"text\":\"--¡Permanece, pues, entre el llanto y la desolación, espíritu maldito! Te conozco aunque estés tan enlodado.\"},{\"heading\":false,\"text\":\"Entonces extendió sus manos hacia la barca, pero mi prudente Maestro le rechazó diciendo:\"},{\"heading\":false,\"text\":\"--Véte de aquí con los otros perros.\"},{\"heading\":false,\"text\":\"En seguida rodeó mi cuello con sus brazos, me besó en el rostro y me dijo:\"},{\"heading\":false,\"text\":\"--Alma desdeñosa, ¡bendita aquella que te llevó en su seno! Ese que ves fué en el mundo una persona soberbia; ninguna virtud ha honrado su memoria, por lo que su sombra está siempre furiosa. ¡Cuántos se tienen allá arriba por grandes reyes, que se verán sumidos como cerdos en este pantano, sin dejar en pos de sí más que horribles desprecios!\"},{\"heading\":false,\"text\":\"Y yo:\"},{\"heading\":false,\"text\":\"--Maestro, antes de salir de este lago, desearía en gran manera ver a ese pecador sumergido en el fango.\"},{\"heading\":false,\"text\":\"Y él a mí:\"},{\"heading\":false,\"text\":\"--Antes de que veas la orilla, quedarás satisfecho: convendrá que goces de ese deseo.\"},{\"heading\":false,\"text\":\"Poco después, le vi acometido de tal modo por las demás sombras cenagosas, que aún alabo a Dios y le doy gracias por ello. Todas gritaban: \\\"¡A Felipe Argenti!\\\" Este florentino, espíritu orgulloso, se revolvía contra sí mismo, destrozándose con sus dientes. Dejémosle allí, pues no pienso ocuparme más de él. Después vino a herir mis oídos un lamento doloroso, por lo cual miré con más atención en torno mío. El buen Maestro me dijo:\"},{\"heading\":false,\"text\":\"--Hijo mío, ya estamos cerca de la ciudad que se llama Dite; sus habitantes pecaron gravemente y son muy numerosos.\"},{\"heading\":false,\"text\":\"Y yo le respondí:\"},{\"heading\":false,\"text\":\"--Ya distingo en el fondo del valle sus torres bermejas, como si salieran de entre llamas.\"},{\"heading\":false,\"text\":\"A lo cual me contestó:\"},{\"heading\":false,\"text\":\"--El fuego eterno que interiormente las abrasa, les comunica el rojo color que ves en ese bajo infierno.\"},{\"heading\":false,\"text\":\"Al fin entramos en los profundos fosos que ciñen aquella desolada tierra: las murallas me parecían de hierro. Llegamos, no sin haber dado antes un gran rodeo, a un sitio en que el barquero nos dijo en alta voz: \\\"Salid, he aquí la entrada.\\\" Vi sobre las puertas más de mil espíritus, caídos del cielo como una lluvia, que decían con ira: \\\"¿Quién es ése que sin haber muerto anda por el reino de los muertos?\\\" Mi sabio Maestro hizo un ademán expresando que quería hablarles en secreto. Entonces contuvieron un poco su cólera y respondieron: \\\"Ven tú solo, y que se vaya aquel que tan audazmente entró en este reino. Que se vuelva solo por el camino que ha emprendido locamente: que lo intente, si sabe; porque tú, que le has guiado por esta obscura comarca, te has de quedar aquí.\\\"\"},{\"heading\":false,\"text\":\"Juzga, lector, si estaría yo tranquilo al oír aquellas palabras malditas: no creí volver nunca a la tierra.\"},{\"heading\":false,\"text\":\"--¡Oh, mi guía querido!, tú que más de siete veces me has devuelto la tranquilidad y librado de los grandes peligros con que he tropezado, no me dejes, le dije, tan abatido: si nos está prohibido avanzar más, volvamos inmediatamente sobre nuestros pasos.\"},{\"heading\":false,\"text\":\"Y aquel señor que allí me había llevado me dijo:\"},{\"heading\":false,\"text\":\"--No temas, pues nadie puede cerrarnos el paso que Dios nos ha abierto. Aguárdame aquí: reanima tu abatido espíritu y alimenta una grata esperanza, que yo no te dejaré en este bajo mundo.\"},{\"heading\":false,\"text\":\"En seguida se fué el dulce Padre, y me dejó solo. Permanecí en una gran incertidumbre, agitándose el sí y el no en mi cabeza.\"},{\"heading\":false,\"text\":\"No pude oír lo que les propuso; pero habló poco tiempo con ellos, y todos a una corrieron hacia la ciudad. Nuestros enemigos dieron con las puertas en el rostro a mi Señor, que se quedó fuera, y se dirigió lentamente hacia donde yo estaba. Tenía los ojos inclinados, sin dar señales de atrevimiento, y decía entre suspiros: \\\"¿Quién me ha impedido la entrada en la mansión de los dolores?\\\" Y dirigiéndose a mí:\"},{\"heading\":false,\"text\":\"--Si estoy irritado--me dijo--, no te inquietes; yo saldré victorioso de esta prueba, cualesquiera que sean los que se opongan a nuestra entrada. Su temeridad no es nueva: ya la demostraron ante una puerta menos secreta, que se encuentra todavía sin cerradura. Ya has visto sobre ella la inscripción de muerte. Pero más acá de esa puerta, descendiendo la montaña y pasando por los círculos sin necesidad de guía, viene uno que nos abrirá la ciudad.\"}]},{\"title\":\"Infierno — canto nono\",\"blocks\":[{\"heading\":false,\"text\":\"Aquel color que el miedo pintó en mi rostro cuando vi a mi guía retroceder, hizo que en el suyo se desvaneciera más pronto la palidez insólita, púsose atento, como un hombre que escucha, porque las miradas no podían penetrar a través del denso aire y de la espesa niebla.\"},{\"heading\":false,\"text\":\"--Sin embargo, debemos vencer en esta lucha--empezó a decir--; ¡si no!... pero se nos ha prometido... ¡Oh!, ¡cuánto tarda el otro en llegar![9]\"},{\"heading\":false,\"text\":\"[9] Si no... Esta reticencia expresa el temor y la duda, que inmediatamente desecha Virgilio por respeto al Sér Supremo. Quiere decir: \\\"¡Si no... viniese ayuda del cielo!... Pero, ¿qué digo? Se me ha prometido... y no puede faltar.\\\" Se refiere a la llegada del ángel.\"},{\"heading\":false,\"text\":\"Yo vi bien que ocultaba lo que había comenzado a decir bajo otra idea que le asaltó después, y que estas últimas palabras eran diferentes de las primeras: sin embargo, su discurso me causó espanto, porque me parecía descubrir en sus entrecortadas frases un sentido peor del que en realidad tenían.\"},{\"heading\":false,\"text\":\"--¿Ha bajado alguna vez al fondo de este triste abismo algún espíritu del primer círculo, cuya sola pena es la de perder la esperanza?--le pregunté.\"},{\"heading\":false,\"text\":\"A lo que me respondió:\"},{\"heading\":false,\"text\":\"--Rara vez sucede que alguno recorra el camino por donde yo voy. Es cierto que tuve que bajar aquí otra vez a causa de los conjuros de la cruel Erictón, que llamaba las almas a sus cuerpos, hacía poco tiempo que mi carne estaba despojada de su alma, cuando me hizo traspasar esas murallas para sacar un espíritu del círculo de Judas. Este círculo es el más profundo, el más obscuro y el más lejano del Cielo que lo mueve todo. Conozco bien el camino; por lo cual debes estar tranquilo. Esta laguna, que exhala tan gran fetidez, ciñe en torno la ciudad del dolor, donde ya no podremos entrar sin justa indignación.\"},{\"heading\":false,\"text\":\"Dijo además otras cosas, que no he podido retener en mi memoria, porque me hallaba absorto, mirando la alta torre de ardiente cúspide, donde vi de improviso aparecer rápidamente tres furias infernales, tintas en sangre, las cuales tenían movimientos y miembros femeniles. Estaban ceñidas de hidras verdosas, y tenían por cabellos pequeñas serpientes y cerastas, que ceñían sus horribles sienes. Y aquél que conocía muy bien a las siervas de la Reina del dolor eterno:\"},{\"heading\":false,\"text\":\"--Mira--me dijo--, las feroces Erinnias. La de la izquierda es Megera; la que llora a la derecha es Alecton, y la del centro es Tisifona.\"},{\"heading\":false,\"text\":\"Después calló. Las furias se desgarraban el pecho con sus uñas; se golpeaban con las manos, y daban tan fuertes gritos, que por temor me acerqué más al poeta. \\\"Venga Medusa, y le convertiremos en piedra, decían todas mirando hacia abajo: mal hemos vengado la entrada del audaz Teseo.\\\"\"},{\"heading\":false,\"text\":\"--Vuélvete y cúbrete los ojos con las manos, porque si apareciese la Gorgona, y la vieses, no podrías jamás volver arriba.\"},{\"heading\":false,\"text\":\"Así me dijo el Maestro, volviéndome él mismo; y no fiándose de mis manos, me tapó los ojos con las suyas. ¡Oh vosotros, que gozáis de sano entendimiento; descubrid la doctrina que se oculta bajo el velo de tan extraños versos!\"},{\"heading\":false,\"text\":\"Oíase a través de las turbias ondas un gran ruido, lleno de horror, que hacía retemblar las dos orillas, asemejándose a un viento impetuoso, impelido por contrarios ardores, que se ensaña en las selvas, y sin tregua las ramas rompe y desgaja, y las arroja fuera; y marchando polvoroso y soberbio, hace huír a las fieras y a los pastores. Me descubrió los ojos, y me dijo:\"},{\"heading\":false,\"text\":\"--Ahora dirige el nervio de tu vista sobre esa antigua espuma, hacia el sitio en que el humo es más maligno.\"},{\"heading\":false,\"text\":\"Como las ranas, que, al ver la culebra enemiga, desaparecen a través del agua, hasta que se han reunido todas en el cieno, del mismo modo vi más de mil almas condenadas, huyendo de uno que atravesaba la Estigia a pie enjuto. Alejaba de su rostro el aire denso, extendiendo con frecuencia la siniestra mano hacia delante, y sólo este trabajo parecía cansarle. Bien comprendí que era un mensajero del Cielo, y volvíme hacia el Maestro; pero éste me indicó que permaneciese quieto y me inclinara. ¡Ah!, ¡cuán desdeñoso me pareció aquel enviado celeste! Llegó a la puerta, y la abrió con una varita sin encontrar obstáculo.\"},{\"heading\":false,\"text\":\"--¡Oh demonios arrojados del Cielo, raza despreciable!--empezó a decir en el horrible umbral--; ¿cómo habéis podido conservar vuestra arrogancia? ¿Por qué os resistís contra esa voluntad, que no deja nunca de conseguir su intento, y que ha aumentado tantas veces vuestros dolores? ¿De qué os sirve luchar contra el destino? Vuestro Cerbero, si bien lo recordáis, tiene aún el cuello y el hocico pelados.\"},{\"heading\":false,\"text\":\"Entonces se volvió hacia el cenagoso camino sin dirigirnos la palabra, semejante a un hombre a quien preocupan y apremian otros cuidados, que no se relacionan con la gente que tiene delante. Y nosotros, confiados en las palabras santas, dirigimos nuestros pasos hacia la ciudad de Dite. Entramos en ella sin ninguna resistencia; y como yo deseaba conocer la suerte de los que estaban encerrados en aquella fortaleza, luego que estuve dentro, empecé a dirigir escudriñadoras miradas en torno mío, y vi por todos lados un gran campo lleno de dolor y de crueles tormentos. Como en los alrededores de Arlés, donde se estanca el Ródano, o como en Pola, cerca del Quarnero, que encierra a Italia y baña sus fronteras, vense antiguos sepulcros, que hacen montuoso el terreno, así también aquí se elevaban sepulcros por todas partes; con la diferencia de que su aspecto era más terrible, por estar envueltos entre un mar de llamas, que los encendían enteramente, más que lo fué nunca el hierro en ningún arte. Todas sus losas estaban levantadas, y del interior de aquéllos salían tristes lamentos, parecidos a los de los míseros ajusticiados. Entonces le pregunté a mi Maestro:\"},{\"heading\":false,\"text\":\"--¿Qué clase de gente es ésa, que sepultada en aquellas arcas, se da a conocer por sus dolientes suspiros?\"},{\"heading\":false,\"text\":\"A lo que me respondió:\"},{\"heading\":false,\"text\":\"--Son los heresiarcas, con sus secuaces de todas sectas: esas tumbas están mucho más llenas de lo que puedes figurarte. Ahí está sepultado cada cual con su semejante, y las tumbas arden más o menos.\"},{\"heading\":false,\"text\":\"Después, dirigiéndose hacia la derecha, pasamos por entre los sepulcros y las altas murallas.\"}]},{\"title\":\"Infierno — canto decimo\",\"blocks\":[{\"heading\":false,\"text\":\"Mi maestro avanzó por un estrecho sendero, entre los muros de la ciudad y las tumbas de los condenados, y yo seguí tras él.\"},{\"heading\":false,\"text\":\"--¡Oh suma virtud--exclamé--que me conduces a tu placer por los círculos impíos! Háblame y satisface mis deseos. ¿Podré ver la gente que yace en esos sepulcros? Todas las losas están levantadas, y no hay nadie que vigile.\"},{\"heading\":false,\"text\":\"Respondióme:\"},{\"heading\":false,\"text\":\"--Todos quedarán cerrados, cuando hayan vuelto de Josafat las almas con los cuerpos que han dejado allá arriba. Epicuro y todos sus sectarios, que pretenden que el alma muere con el cuerpo, tienen su cementerio hacia esta parte. Así, que pronto contestarán aquí dentro a la pregunta que me haces, y al deseo que me ocultas.\"},{\"heading\":false,\"text\":\"Yo le repliqué:\"},{\"heading\":false,\"text\":\"--Buen Guía, si acaso te oculto mi corazón, es por hablar poco, a lo cual no es la primera vez que me has predispuesto con tus advertencias.\"},{\"heading\":false,\"text\":\"--¡Oh Toscano, que vas por la ciudad del fuego hablando modestamente!, dígnate detenerte en este sitio. Tu modo de hablar revela claramente el noble país al que quizá fuí yo funesto.\"},{\"heading\":false,\"text\":\"Tales palabras salieron súbitamente de una de aquellas arcas, haciendo que me aproximara con temor a mi Guía. Este me dijo:\"},{\"heading\":false,\"text\":\"--Vuélvete: ¿qué haces? Mira a Farinata, que se ha levantado en su tumba, y a quien puedes contemplar desde la cintura a la cabeza.\"},{\"heading\":false,\"text\":\"Yo tenía ya mis miradas fijas en las suyas: él erguía su pecho y su cabeza en ademán de despreciar al Infierno. Entonces mi Guía, con mano animosa y pronta, me impelió hacia él a través de los sepulcros, diciéndome: \\\"Háblale con claridad.\\\"\"},{\"heading\":false,\"text\":\"En cuanto estuve al pie de su tumba, examinóme un momento; y después, con acento un tanto desdeñoso, me preguntó:\"},{\"heading\":false,\"text\":\"--¿Quiénes fueron tus antepasados?\"},{\"heading\":false,\"text\":\"Yo, que deseaba obedecer, no le oculté nada, sino que se lo descubrí todo; por lo cual arqueó un poco las cejas, y dijo:\"},{\"heading\":false,\"text\":\"--Fueron terribles contrarios míos, de mis parientes y de mi partido; por eso los desterré dos veces.\"},{\"heading\":false,\"text\":\"--Si estuvieron desterrados--le contesté--, volvieron de todas partes una y otra vez, arte que los vuestros no han aprendido.\"},{\"heading\":false,\"text\":\"Entonces, al lado de aquél, apareció a mi vista una sombra, que sólo descubría hasta la barba, lo que me hace creer que estaba de rodillas. Miró en torno mío, como deseando ver si estaba alguien conmigo; y apenas se desvanecieron sus sospechas, me dijo llorando:\"},{\"heading\":false,\"text\":\"--Si la fuerza de tu genio es la que te ha abierto esta obscura prisión, ¿dónde está mi hijo y por qué no se encuentra a tu lado?\"},{\"heading\":false,\"text\":\"Respondíle:\"},{\"heading\":false,\"text\":\"--No he venido por mí mismo: el que me espera allí me guía por estos lugares: quizá vuestro Guido \\\"tuvo\\\" hacia él demasiado desdén.\"},{\"heading\":false,\"text\":\"Sus palabras y la clase de su suplicio me habían revelado ya el nombre de aquella sombra: así es que mi respuesta fué precisa. Irguiéndose repentinamente exclamó:\"},{\"heading\":false,\"text\":\"--¿Cómo dijiste \\\"tuvo\\\"? Pues qué, ¿no vive aún? ¿No hiere ya sus ojos la dulce luz del día?\"},{\"heading\":false,\"text\":\"Cuando observó que yo tardaba en responderle, cayó de espaldas en su tumba, y no volvió a aparecer fuera de ella. Pero aquel otro magnánimo, por quien yo estaba allí, no cambió de color, ni movió el cuello, ni inclinó el cuerpo.\"},{\"heading\":false,\"text\":\"--El que no hayan aprendido bien ese arte--me dijo continuando la conversación empezada--, me atormenta más que este lecho. Mas la deidad que reina aquí no mostrará cincuenta veces su faz iluminada, sin que tú conozcas lo difícil que es ese arte. Pero dime, así puedas volver al dulce mundo, ¿por qué causa es ese pueblo tan desapiadado con los míos en todas sus leyes?\"},{\"heading\":false,\"text\":\"A lo cual le contesté:\"},{\"heading\":false,\"text\":\"--El destrozo y la gran matanza que enrojeció el Arbia excita tales discursos en nuestro templo.\"},{\"heading\":false,\"text\":\"Entonces movió la cabeza suspirando, y después dijo:\"},{\"heading\":false,\"text\":\"--No estaba yo allí solo; y en verdad, no sin razón me encontré en aquel sitio con los demás; pero sí fuí el único que, cuando se trató de destruir a Florencia, la defendí resueltamente.\"},{\"heading\":false,\"text\":\"--¡Ah!--le contesté--; ¡ojalá vuestra descendencia tenga paz y reposo! Pero os ruego que deshagáis el nudo que ha enmarañado mi pensamiento. Me parece, por lo que he oído, que prevéis lo que el tiempo ha de traer, a pesar de que os suceda lo contrario con respecto a lo presente.\"},{\"heading\":false,\"text\":\"--Nosotros--dijo--somos como los que tienen la vista cansada, que vemos las cosas distantes, gracias a una luz con que nos ilumina el Guía soberano. Cuando las cosas están próximas o existen, nuestra inteligencia es vana, y si otro no nos lo cuenta, nada sabemos de los sucesos humanos; por lo cual puedes comprender que toda nuestra inteligencia morirá el día en que se cierre la puerta del porvenir.\"},{\"heading\":false,\"text\":\"--Decid a ese que acaba de caer, que su hijo está aún entre los vivos. Si antes no le respondí, hacedle saber que lo hice porque estaba distraído con la duda que habéis aclarado.\"},{\"heading\":false,\"text\":\"Mi Maestro me llamaba ya, por cuya razón rogué más solícitamente al espíritu que me dijera quién estaba con él.\"},{\"heading\":false,\"text\":\"--Estoy tendido entre más de mil--me respondió--; ahí dentro están el segundo Federico y el Cardenal.[10] En cuanto a los demás, me callo.\"},{\"heading\":false,\"text\":\"[10] El emperador Federico II, siempre en guerra con los Papas, contra los cuales escribió versos, fué excomulgado por Gregorio IX e Inocencio IV, y murió en 1250.--Octaviano degli Ubaldini, de Florencia y del partido gibelino, a pesar de ser Cardenal, dijo una vez, que, si acaso tuviera alma, la perdería por los gibelinos. Por esta razón los coloca Dante entre los herejes.\"},{\"heading\":false,\"text\":\"Se ocultó después de decir esto, y yo dirigí mis pasos hacia el antiguo poeta, pensando en aquellas palabras que me parecían amenazadoras. Se puso en marcha, y mientras caminábamos, me dijo:\"},{\"heading\":false,\"text\":\"--¿Por qué estás tan turbado?\"},{\"heading\":false,\"text\":\"Y cuando satisfice su pregunta:\"},{\"heading\":false,\"text\":\"--Conserva en tu memoria lo que has oído contra ti--me ordenó aquel sabio--; y ahora estáme atento.\"},{\"heading\":false,\"text\":\"Y levantando el dedo, prosiguió:\"},{\"heading\":false,\"text\":\"--Cuando estés ante la dulce mirada de aquella cuyos bellos ojos lo ven todo, conocerás el porvenir que te espera.\"},{\"heading\":false,\"text\":\"En seguida se dirigió hacia la izquierda. Dejamos las murallas y fuimos hacia el centro de la ciudad, por un sendero que conduce a un valle, el cual exhalaba un hedor insoportable.\"}]},{\"title\":\"Infierno — canto undecimo\",\"blocks\":[{\"heading\":false,\"text\":\"A la extremidad de un alto promontorio, formado por grandes piedras rotas y acumuladas en círculo, llegamos hasta un montón de espíritus más cruelmente atormentados. Allí, para preservarnos de las horribles emanaciones y de la fetidez que despedía el profundo abismo, nos pusimos al abrigo de la losa de un gran sepulcro, donde vi una inscripción que decía: \\\"Encierro al papa Anastasio, a quien Fotino arrastró lejos del camino recto.\\\"\"},{\"heading\":false,\"text\":\"--Es preciso que descendamos por aquí lentamente, a fin de acostumbrar de antemano nuestros sentidos a este triste hedor, y después no tendremos necesidad de precavernos de él.\"},{\"heading\":false,\"text\":\"Así habló mi Maestro, y yo le dije:\"},{\"heading\":false,\"text\":\"--Busca algún recurso para que no perdamos el tiempo inútilmente.\"},{\"heading\":false,\"text\":\"A lo que me respondió:\"},{\"heading\":false,\"text\":\"--Ya ves que en ello pienso. Hijo mío--continuó--, en medio de estas rocas hay tres círculos, que se estrechan gradualmente como los que has dejado: todos están llenos de espíritus malditos; mas para que después te baste con sólo verlos, oye cómo y por qué están aquí encerrados. La injuria es el fin de toda maldad que se atrae el odio del cielo, y se llega a este fin, que redunda en perjuicio de otros, bien por medio de la violencia, o bien por medio del fraude. Pero como el fraude es una maldad propia del hombre, por eso es más desagradable a los ojos de Dios, y por esta razón los fraudulentos están debajo, entregados a un dolor más vivo. Todo el primer círculo lo ocupan los violentos, círculo que está además construído y dividido en tres recintos; porque puede cometerse violencia contra tres clases de seres: contra Dios, contra sí mismo y contra el prójimo; y no sólo contra sus personas, sino también contra sus bienes, como lo comprenderás por estas claras razones. Se comete violencia contra el prójimo dándole la muerte o causándole heridas dolorosas; y contra sus bienes, por medio de la ruina, del incendio o de los latrocinios. De aquí resulta que los homicidas, los que causan heridas, los incendiarios y los ladrones están atormentados sucesivamente en el primer recinto. Un hombre puede haber dirigido su mano violenta contra sí mismo o contra sus bienes: justo es, pues, que purgue su culpa en el segundo recinto, sin esperar tampoco mejor suerte aquel que por su propia voluntad se priva de vuestro mundo, juega, disipa sus bienes o llora donde debía haber estado alegre y gozoso. Puede cometer violencia contra la Divinidad el que reniega de ella y blasfema con el corazón, y el que desprecia la Naturaleza y sus bondades. He aquí por qué el recinto más pequeño marca con su fuego a Sodoma y a Cahors, y a todo el que, despreciando a Dios, le injuria sin hablar, desde el fondo de su corazón. El hombre puede emplear el fraude que produce remordimientos en todas las conciencias, ya con el que de él se fía, ya también con el que desconfía de él. Este último modo de usar del fraude parece que sólo quebranta los vínculos de amor, que forma la Naturaleza; por esta causa están encadenados en el segundo recinto los hipócritas, los aduladores, los hechiceros, los falsarios, los ladrones, los simoníacos, los rufianes, los barateros y todos los que se han manchado con semejantes e inmundos vicios. Por el primer fraude no sólo se olvida el amor que establece la Naturaleza, sino también el sentimiento que le sigue, y de donde nace la confianza: he aquí por qué, en el círculo menor, donde está el centro de la Tierra y donde se halla el asiento de Dite, yace eternamente atormentado todo aquel que ha cometido traición.\"},{\"heading\":false,\"text\":\"Le dije entonces:\"},{\"heading\":false,\"text\":\"--Maestro, tus razones son muy claras, y bien me dan a conocer, por medio de tales divisiones, ese abismo y la muchedumbre que le habita; pero dime: los que están arrojados en aquella laguna cenagosa, los que agita el viento sin cesar, los que azota la lluvia, y los que chocan entre sí lanzando tan estridentes gritos, ¿por qué no son castigados en la ciudad del fuego, si se han atraído la cólera de Dios? Y si no se la han atraído, ¿por qué se ven atormentados de tal suerte?\"},{\"heading\":false,\"text\":\"Me contestó:\"},{\"heading\":false,\"text\":\"--¿Por qué tu ingenio, contra su costumbre, delira tanto ahora?, ¿o es que tienes el pensamiento en otra parte? ¿No te acuerdas de aquellas palabras de la Etica, que has estudiado, en las que se trata de las tres inclinaciones que el Cielo reprueba: la incontinencia, la malicia y la loca bestialidad, y de qué modo la incontinencia ofende menos a Dios y produce menor censura? Si examinas bien esta sentencia, acordándote de los que sufren su castigo fuera de aquí, conocerás por qué están separados de esos felones, y por qué los atormenta la justicia divina, a pesar de demostrarse con ellos menos ofendida.\"},{\"heading\":false,\"text\":\"--¡Oh Sol, que sanas toda vista conturbada!--exclamé--: tal contento me das cuando desarrollas tus ideas, que sólo por eso me es tan grato dudar como saber. Vuelve atrás un momento, y explícame de qué modo ofende la usura a la bondad divina: desvanece esta duda.\"},{\"heading\":false,\"text\":\"--La filosofía--me contestó--enseña en más de un punto al que la estudia, que la Naturaleza tiene su origen en la Inteligencia divina y en su arte; y si consultas bien tu Física, encontrarás, sin necesidad de hojear muchas páginas, que el arte humano sigue cuanto puede a la Naturaleza, como el discípulo a su maestro; de modo que aquél es casi nieto de Dios. Partiendo, pues, de estos principios, sabrás si recuerdas bien el Génesis, que es conveniente sacar de la vida la mayor utilidad, y multiplicar el género humano. El usurero sigue otra vía; desprecia a la naturaleza y a su secuaz, y coloca su esperanza en otra parte. Ahora sígueme; que me place avanzar. Los peces suben ya por el horizonte; el carro se ve hacia aquel punto donde expira Coro, y lejos de aquí el alto promontorio parece que desciende.\"}]},{\"title\":\"Infierno — canto duodecimo\",\"blocks\":[{\"heading\":false,\"text\":\"El sitio por donde empezamos a bajar era un paraje alpestre y, a causa del que allí se hallaba, todas las miradas se apartarían de él con horror. Como aquellas ruinas, cuyo flanco azota el río Adigio, más acá de Trento, producidas por un terremoto o por falta de base, que desde la cima del monte de donde cayeron hasta la llanura, presentan la roca tan hendida, que ningún paso hallaría el que estuviese sobre ellas, así era la bajada de aquel precipicio; y en el borde de la entreabierta sima estaba tendido el monstruo, oprobio de Creta, que fué concebido por una falsa vaca. Cuando nos vió, se mordió a sí mismo, como aquel a quien abrasa la ira. Gritóle entonces mi Sabio:\"},{\"heading\":false,\"text\":\"--¿Por ventura crees que esté aquí el rey de Atenas, que allá arriba, en el mundo, te dió la muerte? Aléjate, monstruo; que éste no viene amaestrado por tu hermana, sino con el objeto de contemplar vuestras penas.\"},{\"heading\":false,\"text\":\"Como el toro que rompe las ligaduras en el momento de recibir el golpe mortal, que huír no puede, pero salta de un lado a otro, lo mismo hizo el Minotauro; y mi prudente Maestro me gritó:\"},{\"heading\":false,\"text\":\"--Corre hacia el borde; mientras esté furioso, bueno es que desciendas.\"},{\"heading\":false,\"text\":\"Nos encaminamos por aquel derrumbamiento de piedras, que oscilaban por primera vez bajo el peso de mi cuerpo. Iba yo pensativo; por lo cual me dijo:\"},{\"heading\":false,\"text\":\"--Acaso piensas en estas ruinas, defendidas por aquella ira bestial, que he disipado. Quiero, pues, que sepas que la otra vez que bajé al profundo Infierno aun no se habían desprendido estas piedras; pero un poco antes (si no estoy equivocado) de que viniese aquél que arrebató a Dite la gran presa del primer círculo, retembló el impuro valle tan profundamente por todos sus ámbitos, que creí ver al universo sintiendo aquel amor, por el cual otros creyeron que el mundo ha vuelto más de una vez a sumirse en el caos; y entonces fué cuando esa antigua roca se destrozó por tan diversas partes. Pero fija tus miradas en el valle; pues ya estamos cerca del río de sangre, en el cual hierve todo el que por medio de la violencia ha hecho daño a los demás.\"},{\"heading\":false,\"text\":\"¡Oh ciegos deseos! ¡Oh ira desatentada, que nos aguijonea de tal modo en nuestra corta vida, y así nos sumerge en sangre hirviente por toda una eternidad! Vi un ancho foso en forma circular, como la montaña que rodea toda la llanura, según me había dicho mi Guía, y entre el pie de la roca y este foso corrían en fila muchos centauros armados de saetas, del mismo modo que solían ir a cazar por el mundo. Al vernos descender, se detuvieron, y tres de ellos se separaron de la banda, preparando sus arcos y escogiendo antes sus flechas. Uno de ellos gritó desde lejos:\"},{\"heading\":false,\"text\":\"--¿Qué tormento os está reservado a vosotros los que bajáis por esa cuesta? Decidlo desde donde estáis, porque si no, disparo mi arco.\"},{\"heading\":false,\"text\":\"Mi Maestro respondió:\"},{\"heading\":false,\"text\":\"--Contestaremos a Quirón, cuando estemos cerca. Tus deseos fueron siempre por desgracia muy impetuosos.\"},{\"heading\":false,\"text\":\"Después me tocó y me dijo:\"},{\"heading\":false,\"text\":\"--Ese es Neso, el que murió por la hermosa Deyanira, y vengó por sí mismo su muerte; el de enmedio, que inclina la cabeza sobre el pecho, es el gran Quirón, que educó a Aquiles; el otro es el irascible Foló. Alrededor del foso van a millares, atravesando con sus flechas a toda alma que sale de la sangre más de lo que le permiten sus culpas.\"},{\"heading\":false,\"text\":\"Nos fuimos aproximando a aquellos ágiles monstruos: Quirón cogió una flecha, y con el regatón apartó las barbas hacia detrás de sus quijadas. Cuando se descubrió la enorme boca, dijo a sus compañeros:\"},{\"heading\":false,\"text\":\"--¿Habéis observado que el de detrás mueve cuanto toca? Los pies de los muertos no suelen hacer eso.\"},{\"heading\":false,\"text\":\"Y mi buen Maestro, que estaba ya junto a él, y le llegaba al pecho, donde las dos naturalezas se unen, repuso:\"},{\"heading\":false,\"text\":\"--Está en efecto vivo, y yo sólo debo enseñarle el sombrío valle: viene a él por necesidad, y no por distracción. La que me ha encomendado este nuevo oficio, ha cesado por un momento de cantar \\\"aleluya.\\\" No es él un ladrón, ni yo un alma criminal. Pero por aquella virtud que dirige mis pasos en un camino tan salvaje, cédeme uno de los tuyos para que nos acompañe, que nos indique un punto vadeable y lleve a éste sobre sus ancas, pues no es espíritu que vaya por el aire.\"},{\"heading\":false,\"text\":\"Quirón se volvió hacia la derecha, y dijo a Neso:\"},{\"heading\":false,\"text\":\"--Vé, guíales; y si tropiezan con algún grupo de los nuestros, haz que les abran paso.\"},{\"heading\":false,\"text\":\"Nos pusimos en marcha, tan fielmente escoltados, hacia lo largo de las orillas de aquella roja espuma, donde lanzaban horribles gritos los ahogados. Los vi sumergidos hasta las cejas, por lo que el gran Centauro dijo:\"},{\"heading\":false,\"text\":\"--Esos son los tiranos, que vivieron de sangre y de rapiña. Aquí se lloran las desapiadadas culpas: aquí está Alejandro, y el feroz Dionisio, que tantos años de dolor hizo sufrir a la Sicilia. Aquella frente que tiene el cabello tan negro es la de Azzolino, y la otra que lo tiene rubio es la de Obezzo de Este, que verdaderamente fué asesinado en el mundo por su hijastro.\"},{\"heading\":false,\"text\":\"Entonces me volví hacia el Poeta, el cual me dijo:\"},{\"heading\":false,\"text\":\"--Sea éste ahora tu primer guía; yo seré el segundo.\"},{\"heading\":false,\"text\":\"Algo más lejos se detuvo el Centauro sobre unos condenados, que parecían sacar fuera de aquel hervidero su cabeza hasta la garganta, y nos mostró una sombra que estaba separada de las demás, diciendo:\"},{\"heading\":false,\"text\":\"Aquél hirió, en recinto sagrado, a un corazón, que aún se ve honrado en las orillas del Támesis.[11]\"},{\"heading\":false,\"text\":\"[11] Guido de Montfort. Para vengar la muerte de Simón, su padre, muerto en Inglaterra por Eduardo, asesinó en 1271, en una iglesia de Viterbo, a Enrique, hermano de aquél, mientras el sacerdote elevaba la hostia. El corazón del asesinado fué llevado en una copa a Londres, y colocado sobre una columna en el puente del Támesis, para recordar a los ingleses la ofensa que se les había hecho.\"},{\"heading\":false,\"text\":\"Después vi otras sombras que sacaban la cabeza fuera del río, y algunas todo el pecho, y reconocí a muchos de ellos. Como la sangre iba disminuyendo poco a poco, hasta no cubrir más que el pie, vadeamos el foso.\"},{\"heading\":false,\"text\":\"--Quiero que creas--me dijo el Centauro--que así como ves disminuir la corriente por esta parte, por la otra es su fondo cada vez mayor, hasta que llega a reunirse en aquel punto donde la tiranía está condenada a gemir. Allí es donde la justicia divina ha arrojado a Atila, que fué su azote en la tierra; a Pirro, a Sexto, y eternamente arranca lágrimas, con el hervor de esa sangre, a Renato de Corneto y a Renato Pazzo, que tanto daño causaron en los caminos.\"},{\"heading\":false,\"text\":\"Dicho esto, se volvió y repasó el vado.\"}]},{\"title\":\"Infierno — canto decimotercio\",\"blocks\":[{\"heading\":false,\"text\":\"No había llegado aún Neso a la otra parte, cuando penetramos en un bosque, que no estaba surcado por ningún sendero. El follaje no era verde, sino de un color obscuro; las ramas no eran rectas, sino nudosas y entrelazadas; no había frutas, sino espinas venenosas. No son tan ásperas y espesas las selvas donde moran las fieras, que aborrecen los sitios cultivados entre el Cecina y Corneto. Allí anidan las brutales Arpías, que arrojaron a los Troyanos de las Estrofades con el triste presagio de un mal futuro. Tienen alas anchas, cuellos y rostros humanos, pies con garras, y el vientre cubierto de plumas: subidas en los árboles, lanzan extraños lamentos.\"},{\"heading\":false,\"text\":\"Mi buen Maestro empezó a decirme:\"},{\"heading\":false,\"text\":\"--Antes de avanzar más, debes saber que te encuentras en el segundo recinto, por el cual continuarás hasta que llegues a los terribles arenales. Por tanto, mira con atención; y de este modo verás cosas, que darán testimonio de mis palabras.\"},{\"heading\":false,\"text\":\"Por todas partes oía yo gemidos, sin ver a nadie que los exhalara; por eso me detuve todo atemorizado. Creo que él creyó que yo creía que aquellas voces eran de gente que se ocultaba de nosotros entre la espesura; y así me dijo mi Maestro:\"},{\"heading\":false,\"text\":\"--Si rompes cualquier ramita de una de esas plantas, verás trocarse tus pensamientos.\"},{\"heading\":false,\"text\":\"Entonces extendí la mano hacia delante, cogí una ramita de un gran endrino, y su tronco exclamó:\"},{\"heading\":false,\"text\":\"--¿Por qué me tronchas?\"},{\"heading\":false,\"text\":\"Inmediatamente se tiñó de sangre, y volvió a exclamar:\"},{\"heading\":false,\"text\":\"--¿Por qué me desgarras? ¿No tienes ningún sentimiento de piedad? Hombres fuimos, y ahora estamos convertidos en troncos: tu mano debería haber sido más piadosa, aunque fuéramos almas de serpientes.\"},{\"heading\":false,\"text\":\"Cual de verde tizón que, encendido por uno de sus extremos, gotea y chilla por el otro, a causa del aire que le atraviesa, así salían de aquel tronco palabras y sangre juntamente; lo que me hizo dejar caer la rama, y detenerme como hombre acobardado.\"},{\"heading\":false,\"text\":\"--Alma herida--respondió mi Sabio--; si él hubiera podido creer, desde luego, que era verdad lo que ha leído en mis versos, no habría extendido su mano hacia ti: el ser una cosa tan increíble me ha obligado a aconsejarle que hiciese lo que ahora me está pesando. Pero dile quién fuiste, a fin de que, en compensación, renueve tu fama en el mundo, donde le es lícito volver.\"},{\"heading\":false,\"text\":\"El tronco respondió:\"},{\"heading\":false,\"text\":\"--Me halagas tanto con tus dulces palabras, que no puedo callar: no llevéis a mal que me entretenga un poco hablando con vosotros. Yo soy aquél[12] que tuvo las dos llaves del corazón de Federico, manejándolas tan suavemente para cerrar y abrir, que a casi todos aparté de su confianza, habiéndome dedicado con tanta fe a aquel glorioso cargo, que perdí el sueño y la vida. La cortesana que no ha separado nunca del palacio de César sus impúdicos ojos, peste común y vicio de las cortes, inflamó contra mí todos los ánimos, y los inflamados inflamaron a su vez y de tal modo a Augusto, que mis dichosos honores se trocaron en triste duelo. Mi alma, en un arranque de indignación, creyendo librarse del oprobio por medio de la muerte, me hizo injusto contra mí mismo, siendo justo. Os juro, por las tiernas raíces de este leño, que jamás fuí desleal a mi señor, tan digno de ser honrado. Y si uno de vosotros vuelve al mundo, restaure en él mi memoria, que yace aún bajo el golpe que le asestó la envidia.\"},{\"heading\":false,\"text\":\"[12] Pedro Desvignes, o Pedro della Vigna, jurisconsulto de Capua; gozó por mucho tiempo el favor del emperador Federico II, de quien era canciller y a quien inclinaba lo mismo a la clemencia que a la severidad. Acusado de traición por envidiosos cortesanos, le sacaron los ojos en 1246. Su desesperación fué tal que se estrelló la cabeza contra los muros de su calabozo.\"},{\"heading\":false,\"text\":\"El poeta esperó un momento, y después me dijo:\"},{\"heading\":false,\"text\":\"--Pues que calla, no pierdas el tiempo: habla y pregúntale, si quieres saber más.\"},{\"heading\":false,\"text\":\"Yo le contesté:\"},{\"heading\":false,\"text\":\"--Interrógale tú mismo lo que creas que me interese, pues yo no podría: tanto es lo que me aflige la compasión.\"},{\"heading\":false,\"text\":\"Por lo cual volvió él a empezar de este modo:\"},{\"heading\":false,\"text\":\"--A fin de que este hombre haga generosamente lo que tu súplica reclama, espíritu encarcelado, dígnate aún decirnos cómo se encierra el alma en esos nudosos troncos, y dime además, si puedes, si hay alguna que se desprenda de tales miembros.\"},{\"heading\":false,\"text\":\"Entonces el tronco suspiró, y aquel resoplido se convirtió en esta voz:\"},{\"heading\":false,\"text\":\"--Os contestaré brevemente: cuando el alma feroz sale del cuerpo de donde se ha arrancado ella misma, Minos la envía al séptimo círculo. Cae en la selva, sin que tenga designado sitio fijo, y allí donde la lanza la fortuna, germina cual grano de espelta. Brota primero como un retoño, y luego se convierte en planta silvestre: las Arpías, al devorar sus hojas, le causan dolor, y abren paso por donde ese dolor se exhale. Como las demás almas, iremos a recoger nuestros despojos; pero sin que ninguna de nosotras pueda revestirse con ellos, porque no sería justo volver a tener lo que uno se ha quitado voluntariamente. Los arrastraremos hasta aquí; y en este lúgubre bosque estará cada uno de nuestros cuerpos suspendido en el mismo endrino donde sufre tal tormento su alma.\"},{\"heading\":false,\"text\":\"Prestábamos aún atención a aquel tronco, creyendo que añadiría algo más, cuando fuimos sorprendidos por un rumor, a la manera del que siente venir el jabalí y los perros hacia el sitio donde está apostado, que juntamente oye el ruido de las fieras y el fragor del ramaje. Y he aquí que aparecen a nuestra izquierda dos infelices, desnudos y lacerados, huyendo tan precipitadamente, que rompían todas las ramas de la selva. El de delante: \\\"¡Acude, acude, muerte!,\\\" decía; y el otro, que no corría tanto: \\\"Lano, tus piernas no eran tan ágiles en el combate del Toppo.\\\" Y sin duda, faltándole el aliento, hizo un grupo de sí y de un arbusto.\"},{\"heading\":false,\"text\":\"Detrás de ellos estaba la selva llena de perras negras, ávidas y corriendo cual lebreles a quienes quitan su cadena. Empezaron a dar terribles dentelladas a aquél que se ocultó, y después de despedazarle, se llevaron sus miembros palpitantes. Mi Guía me tomó entonces de la mano, y llevóme hacia el arbusto, que en vano se quejaba por sus sangrientas heridas:\"},{\"heading\":false,\"text\":\"--¡Oh, Jacobo de San Andrés!--decía--. ¿De qué te ha servido tomarme por refugio? ¿Tengo yo la culpa de tu vida criminal?\"},{\"heading\":false,\"text\":\"Cuando mi Maestro se detuvo delante de aquel arbusto, dijo:\"},{\"heading\":false,\"text\":\"--¿Quién fuiste tú que por tantas ramas rotas exhalas con tu sangre tan quejumbrosas palabras?\"},{\"heading\":false,\"text\":\"A lo que contestó:\"},{\"heading\":false,\"text\":\"--¡Oh, almas, que habéis venido a contemplar el lamentable estrago que me ha separado así de mis hojas!, recogedlas al pie del triste arbusto. Yo fuí de la ciudad que cambió su primer patrón por San Juan Bautista;[13] por cuya razón aquél la contristará siempre con su terrible arte: y a no ser porque en el puente del Arno se conserva todavía alguna imagen suya, fuera en vano todo el trabajo de aquellos ciudadanos que la reedificaron sobre las cenizas que de ella dejó Atila. Yo de mi casa hice mi propia horca.\"},{\"heading\":false,\"text\":\"[13] Florencia, cuyo antiguo patrón era el dios Marte. Su estatua ecuestre se conservaba aún en 1337 en el Ponte-Vecchio, de donde la arrancó, juntamente con un trozo del puente, una avenida del Arno.\"}]},{\"title\":\"Infierno — canto decimocuarto\",\"blocks\":[{\"heading\":false,\"text\":\"Enternecido por el amor patrio, reuní las hojas dispersas, y las devolví a aquel que ya se había callado. Desde allí nos dirigimos al punto en que se divide el segundo recinto del tercero, y donde se ve el terrible poder de la justicia divina. Para explicar mejor las cosas nuevas que allí vi, diré que llegamos a un arenal, que rechaza toda planta de su superficie. La dolorosa selva lo rodeaba cual guirnalda, así como el sangriento foso circundaba a aquélla. Nuestros pies quedaron fijos en el mismo lindero de la selva y la llanura. El espacio estaba cubierto de una arena tan árida y espesa, como la que oprimieron los pies de Catón en otro tiempo. ¡Oh venganza de Dios! ¡Cuánto debe temerte todo aquél que lea lo que se presentó a mis ojos! Vi numerosos grupos de almas desnudas, que lloraban miserablemente, y parecían cumplir sentencias diversas. Unas yacían de espaldas sobre el suelo; otras estaban sentadas en confuso montón; otras andaban continuamente. Las que daban la vuelta al círculo eran más numerosas, y en menor número las que yacían para sufrir algún tormento; pero éstas tenían la lengua más suelta para quejarse. Llovían lentamente en el arenal grandes copos de fuego, semejantes a los de nieve que en los Alpes caen cuando no sopla el viento. Así como Alejandro vió en las ardientes comarcas de la India caer sobre sus soldados llamas, que quedaban en el suelo sin extinguirse, lo que le obligó a ordenar a las tropas que las pisaran, porque el incendio se apagaba mejor cuanto más aislado estaba, así descendía el fuego eterno, abrasando la arena, como abrasa a la yesca el pedernal, para redoblar el dolor de las almas. Sus míseras manos se agitaban sin reposo, apartando a uno y otro lado las brasas continuamente renovadas. Yo empecé a decir:\"},{\"heading\":false,\"text\":\"--Maestro, tú que has vencido todos los obstáculos, a excepción del que nos opusieron los demonios inflexibles a la puerta de la ciudad, dime, ¿quién es aquella gran sombra, que no parece cuidarse del incendio, y yace tan feroz y altanera, como si no la martirizara esa lluvia?\"},{\"heading\":false,\"text\":\"Y la sombra, observando que yo hablaba de ella a mi Guía, gritó:\"},{\"heading\":false,\"text\":\"--Tal cual fuí en vida, soy después de muerto. Aun cuando Júpiter cansara a su herrero, de quien tomó en su cólera el agudo rayo que me hirió el último día de mi vida; aun cuando fatigara uno tras otro a todos los negros obreros del Mongibelo, gritando: \\\"Ayúdame, ayúdame, buen Vulcano,\\\" según hizo en el combate de Flegra, y me asaeteara con todas sus fuerzas, no lograría vengarse de mí cumplidamente.\"},{\"heading\":false,\"text\":\"Entonces mi Guía habló con tanta vehemencia, que nunca yo lo había oído expresarse de aquel modo:\"},{\"heading\":false,\"text\":\"--¡Oh! Capaneo, si no se modera tu orgullo, él será tu mayor castigo. No hay martirio comparable al dolor que te hace sufrir tu rabia.\"},{\"heading\":false,\"text\":\"Después se dirigió a mí, diciendo con acento más apacible:\"},{\"heading\":false,\"text\":\"--Ese fué uno de los siete reyes que sitiaron a Tebas; despreció a Dios, y aun parece seguir despreciándole, sin que se note que le ruegue; pero, como le he dicho, su mismo despecho es el más digno premio debido a su corazón. Ahora, sígueme, y cuida de no poner tus pies sobre la abrasada arena; camina siempre arrimado al bosque.\"},{\"heading\":false,\"text\":\"Llegamos en silencio al sitio donde desemboca fuera de la selva un riachuelo, cuyo rojo color aún me horripila. Cual sale del Bulicame[14] el arroyo, cuyas aguas se reparten las pecadoras, así corría aquel riachuelo por la arena. Las orillas y el fondo estaban petrificados, por lo que pensé que por ellas debía andar.\"},{\"heading\":false,\"text\":\"[14] Manantial de aguas minerales calientes, a dos millas de Viterbo. De él salía un riachuelo con el cual se formaba un baño, al que acudían toda clase de enfermos, y más abajo tomaban y se repartían sus aguas le peccatrici, las mujeres públicas.\"},{\"heading\":false,\"text\":\"--Entre todas las cosas que te he enseñado, desde que entramos por la puerta en cuyo umbral puede detenerse cualquiera, tus ojos no han visto otra tan notable como esa corriente, que amortigua todas las llamas.\"},{\"heading\":false,\"text\":\"Tales fueron las palabras de mi Guía; por lo que le supliqué se explicase más claramente, ya que había excitado mi curiosidad.\"},{\"heading\":false,\"text\":\"--En medio del mar existe un país arruinado--me dijo entonces--, que se llama Creta, y tuvo un rey, bajo cuyo imperio el mundo fué virtuoso: en él hay un monte, llamado Ida, que en otro tiempo fué delicioso por sus aguas y su frondosidad, y hoy está desierto, como todas las cosas antiguas. Rea lo escogió por cuna segura de su hijo; y para ocultarlo mejor, cuando lloraba, hacía que se produjesen grandes ruidos. En el interior del monte se mantiene en pie un gran anciano, que está de espaldas hacia Damieta, con la mirada fija en Roma como en un espejo. Su cabeza es formada de oro fino, y de plata pura son los brazos y el pecho; después es de bronce hasta la entrepierna, y de allí para abajo, es todo de hierro escogido, excepto el pie derecho, que es de barro cocido, y se afirma sobre éste más que sobre el otro. Cada parte, menos la formada de oro, está surcada por una hendedura que mana lágrimas, las cuales, reunidas, agujeran aquel monte. Su curso se dirige hacia este valle, de roca en roca, formando el Aqueronte, la Estigia y el Flegetón; después descienden por este estrecho conducto, hasta el punto donde no se puede bajar más, y allí forman el Cocito: ya verás lo que es este lago; por eso no te lo describo ahora.\"},{\"heading\":false,\"text\":\"Yo le contesté:\"},{\"heading\":false,\"text\":\"--Si ese riachuelo se deriva así de nuestro mundo, ¿por qué se deja ver únicamente al margen de este bosque?\"},{\"heading\":false,\"text\":\"Y él a mí:\"},{\"heading\":false,\"text\":\"--Tú sabes que este lugar es redondo, y aunque hayas andado mucho, descendiendo siempre al fondo por la izquierda, no has dado aún la vuelta a todo el círculo; por lo cual, si se te aparece alguna cosa nueva, no debe pintarse la admiración en tu rostro.\"},{\"heading\":false,\"text\":\"Le repliqué:\"},{\"heading\":false,\"text\":\"--Maestro, ¿dónde están el Flegetón y el Leteo? Del uno no dices nada, y del otro sólo me dices que lo origina esa lluvia de lágrimas.\"},{\"heading\":false,\"text\":\"--Me agradan todas tus preguntas--contestó--: pero el hervor de esa agua roja debiera haberte servido de contestación a una de ellas. Verás el Leteo; pero fuera de este abismo, allá donde van las almas a lavarse, cuando, arrepentidas de sus culpas, les son perdonadas.\"},{\"heading\":false,\"text\":\"Después añadió:\"},{\"heading\":false,\"text\":\"--Ya es tiempo de que nos apartemos de este bosque; procura venir detrás de mí: sus márgenes nos ofrecen un camino; pues no son ardientes, y sobre ellas se extinguen todas las brasas.\"}]},{\"title\":\"Infierno — canto decimoquinto\",\"blocks\":[{\"heading\":false,\"text\":\"Nos pusimos en marcha siguiendo una de aquellas orillas petrificadas: el vapor del arroyuelo formaba sobre él una niebla, que preservaba del fuego las ondas y los ribazos. Así como los flamencos que habitan entre Gante y Brujas, temiendo al mar que avanza hacia ellos, levantan diques para contenerle; o como los Paduanos lo hacen a lo largo del Brenta para defender sus ciudades y castillos, antes que el Chiarentana sienta el calor, de un modo semejante eran formados aquellos ribazos; pero su constructor, quienquiera que fuese, no los había hecho tan altos ni tan gruesos.\"},{\"heading\":false,\"text\":\"Nos hallábamos ya tan lejos de la selva, que no me habría sido posible descubrirla, por más que volviese atrás la vista, cuando encontramos una legión de almas, que venía a lo largo del ribazo: cada cual de ellas me miraba, como de noche suelen mirarse unos a otros los humanos a la escasa luz de la luna nueva, y aguzaban hacia nosotros las pestañas, como hace un sastre viejo para enfilar la aguja.\"},{\"heading\":false,\"text\":\"Examinado de este modo por aquellas almas, fuí conocido por una de ellas, que me cogió el vestido, exclamando:\"},{\"heading\":false,\"text\":\"--¡Qué maravilla!\"},{\"heading\":false,\"text\":\"Y yo, mientras me tendía los brazos, miré atentamente su abrasado rostro, de tal modo que, a pesar de estar desfigurado, no me fué imposible conocerle a mi vez; e inclinando hacia su faz la mía contesté:\"},{\"heading\":false,\"text\":\"--¿Vos aquí, \\\"ser\\\" Brunetto?\"},{\"heading\":false,\"text\":\"Y él repuso:\"},{\"heading\":false,\"text\":\"--¡Oh hijo mío!, no te enojes si Brunetto Latini vuelve un poco atrás contigo, y deja que se adelanten las demás almas.\"},{\"heading\":false,\"text\":\"Yo le dije:\"},{\"heading\":false,\"text\":\"--Os lo ruego cuanto me es posible; y si queréis que nos sentemos, lo haré, si así le place a éste con quien voy.\"},{\"heading\":false,\"text\":\"--¡Oh hijo mío!--replicó--; cualquiera de nosotros que se detenga un momento, queda después cien años sufriendo esta lluvia, sin poder esquivar el fuego que le abrasa. Así, pues, sigue adelante; yo caminaré a tu lado, y luego me reuniré a mi mesnada, que va llorando sus eternos tormentos.\"},{\"heading\":false,\"text\":\"No me atreví a bajar del ribazo por donde iba para nivelarme con él; pero tenía la cabeza inclinada, en actitud respetuosa. Empezó de este modo:\"},{\"heading\":false,\"text\":\"--¿Cuál es la suerte o el destino que te trae aquí abajo antes de tu última hora? ¿Y quién es ése que te enseña el camino?\"},{\"heading\":false,\"text\":\"--Allá arriba, en la vida serena--le respondí--, me extravié en un valle antes de haberse llenado mi edad. Pero ayer de mañana le volví la espalda; y cuando retrocedía otra vez hacia él, se me apareció ése, y me volvió al verdadero camino por esta vía.\"},{\"heading\":false,\"text\":\"A lo que me contestó:\"},{\"heading\":false,\"text\":\"--Si sigues tu estrella, no puedes menos de llegar a glorioso puerto, dado que yo en el mundo predijera bien tu destino. Y a no haber muerto tan pronto, viendo que el cielo te era tan favorable, te habría dado alientos para proseguir tu obra. Pero aquel pueblo ingrato y malo, que en otro tiempo descendió de Fiésole, y que aun conserva algo de la aspereza de sus montañas y de sus rocas, será tu enemigo, por lo mismo que prodigarás el bien; lo cual es natural, pues no conviene que madure el dulce higo entre ásperos serbales. Una antigua fama les da en el mundo el nombre de ciegos; raza avara, envidiosa y soberbia: ¡que sus malas costumbres no te manchen nunca! La fortuna te reserva tanto honor, que los dos partidos anhelarán poseerte; pero la hierba estará lejos del pico. Hagan las bestias fiesolanas forraje de sus mismos cuerpos, y no puedan tocar a la planta, si es que todavía sale alguna de entre su estiércol, en la que reviva la santa semilla de aquellos romanos que quedaron después de construído aquel nido de perversidad.\"},{\"heading\":false,\"text\":\"--Si todos mis deseos se hubiesen realizado--le respondí--, no estaríais vos fuera de la humana naturaleza; porque tengo siempre fija en mi mente, y ahora me contrista verla así, vuestra querida, buena y paternal imagen, cuando me enseñabais en el mundo cómo el hombre se inmortaliza: me creo, pues, en el deber, mientras viva, de patentizar con mis palabras el agradecimiento que os profeso. Conservo grabado en la memoria cuanto me referís acerca de mi destino, para hacerlo explicar con otro texto por una Dama que lo sabrá hacer, si consigo llegar hasta ella. Solamente deseo manifestaros que estoy dispuesto a correr todos los azares de la Fortuna con tal que mi conciencia no me remuerda nada. No es la vez primera que he oído semejante predicción; y así, mueva su rueda la Fortuna como le plazca, y el campesino su azada.\"},{\"heading\":false,\"text\":\"Entonces mi Maestro se volvió hacia la derecha, me miró, y después me dijo:\"},{\"heading\":false,\"text\":\"--Bien escucha quien bien retiene.\"},{\"heading\":false,\"text\":\"No por eso dejé de seguir hablando con \\\"ser\\\" Brunetto; y preguntándole quiénes eran sus más notables y eminentes compañeros, me contestó:\"},{\"heading\":false,\"text\":\"--Bueno es que conozcan los nombres de algunos de ellos: con respecto a los otros, vale más callar; que para tanta conversación el tiempo es corto. Sabe, pues, que todos ellos fueron clérigos y literatos de gran fama, y el mismo pecado los contaminó a todos en el mundo. Con aquella turba desolada va Prisciano, como también Francisco de Accorso; y si desearas conocer a tan inmunda caterva, podrías ver a aquel que por el Siervo de los siervos de Dios fué trasladado del Arno al Bacchiglione,[15] donde dejó sus mal extendidos miembros. Más te diría; pero no puedo avanzar ni hablar más, porque ya veo salir nuevo humo de la arena. Vienen almas con las cuales no debo estar. Te recomiendo mi \\\"Tesoro,\\\"[16] en el que aún vive mi memoria, y no pido nada más.\"},{\"heading\":false,\"text\":\"[15] Andrés de Mozzi, que fué desposeído del obispado de Florencia a causa de sus vicios, y trasladado después al de Vicenza, por donde pasa el Bacchiglione.\"},{\"heading\":false,\"text\":\"[16] Título de la obra principal de Brunetto Latini, escrita en francés. El \\\"Tesoro\\\" fué publicado en su lengua original por Chabaille (París, 1863), y traducido al italiano por Bono Giamboni (Bolonia, 1878-83, 4 vols.).\"},{\"heading\":false,\"text\":\"Después se volvió con los otros, del mismo modo que los que, en la campiña de Verona, disputan a la carrera el palio verde, pareciéndose en el correr a los que vencen y no a los vencidos.\"}]},{\"title\":\"Infierno — canto decimosexto\",\"blocks\":[{\"heading\":false,\"text\":\"Encontrábame ya en un sitio donde se oía el rimbombar del agua que caía en el otro recinto, rumor semejante al zumbido que producen las abejas en sus colmenas, cuando a un tiempo y corriendo se separaron tres sombras de entre una multitud que pasaba sobre la lluvia del áspero martirio. Vinieron hacia nosotros, gritando cada cual: \\\"Detente, tú, que, a juzgar por tus vestidos, eres hijo de nuestra depravada tierra.\\\" ¡Ah!, ¡qué de llagas antiguas y recientes vi en sus miembros, producidas por las llamas! Su recuerdo me contrista todavía. A sus gritos se detuvo mi Maestro; volvió el rostro hacia mí, y me dijo:\"},{\"heading\":false,\"text\":\"--Espera aquí si quieres ser cortés con esos; aunque si no fuese por el fuego que lanza sus rayos sobre este lugar, te diría que, mejor que a ellos la prisa de venir, te estaría a ti la de correr a su encuentro.\"},{\"heading\":false,\"text\":\"Las sombras volvieron de nuevo a sus exclamaciones luego que nos detuvimos, y cuando llegaron adonde estábamos, empezaron las tres a dar vueltas formando un círculo. Y como solían hacer los gladiadores desnudos y untados de aceite, que antes de venir a las manos buscaba cada cual la oportunidad de lanzarse con ventaja sobre su contrario, del mismo modo cada una de aquellas sombras dirigía su rostro hacia mí, girando sin cesar, de suerte que tenían vuelto el cuello en distinta dirección de la que seguían sus pies.\"},{\"heading\":false,\"text\":\"--Aunque la miseria de este suelo movedizo y nuestro llagado y sucio aspecto haga que nosotros y nuestros ruegos seamos despreciables, comenzó a decir una de ellas, nuestra fama debe incitar a tu corazón a decirnos quién eres tú, que sientas con tal seguridad los pies vivos en el Infierno. Este que ves tan desnudo y destrozado, y cuyas huellas voy siguiendo, fué de un rango mucho más elevado de lo que te figuras. Nieto fué de la púdica Gualdrata,[17] se llamó Guido Guerra, y durante su vida hizo tanto con su talento, como con su espada: el otro, que tras de mí oprime la arena, es Tegghiaio Aldobrandi, cuya voz debería ser agradecida en el mundo; y yo, que sufro el mismo tormento que ellos, fuí Jacobo Rusticucci, y por cierto que nadie me causó más daño que mi fiera mujer.\"},{\"heading\":false,\"text\":\"[17] Bellísima y honesta doncella, hija de Bellicion Berti, la cual, al mostrarse el emperador Otón IV deseoso de besarla, se volvió hacia su padre diciendo: \\\"Nadie me ha da besar, excepto aquel a quien dé la mano de esposa.\\\" Se casó con el conde Guido, de familia germánica, del cual descendieron los condes Guidi, señores de Casentino. De este matrimonio nació Marcovaldo, que fué padre de Guido Guerra, valiente caballero y hombre de gran prudencia y talento, a quien se debió la victoria en la batalla de Benavento.\"},{\"heading\":false,\"text\":\"Si hubiese podido estar al abrigo del fuego, me habría lanzado hacia los de abajo, y creo que mi Maestro lo hubiera tolerado; pero como estaba expuesto a abrasarme y cocerme, el miedo venció la buena intención que me impelía a abrazarlos. Así les dije:\"},{\"heading\":false,\"text\":\"--Vuestra situación no me ha inspirado desprecio, sino un dolor que tardará en desaparecer; esto es lo que he sentido desde el momento que mi Señor me dijo algunas palabras, por las cuales comprendí que era gente de vuestra calidad la que hacia nosotros venía. De vuestra tierra soy; y siempre he retenido y escuchado con gusto vuestros actos y vuestros honrados nombres. Dejo las amarguras, y voy en busca de los sabrosos frutos que me ha prometido mi sincero Guía; pero antes me es preciso bajar hasta el centro.\"},{\"heading\":false,\"text\":\"--Así tu alma permanezca unida a tus miembros por mucho tiempo--repuso aquél--, y así también resplandezca tu fama después de la muerte, ruégote nos digas si la gentileza y el valor habitan aún en nuestra ciudad, como solían, o si se han desterrado por completo; porque Guillermo Borsiere, que gime hace poco tiempo entre nosotros, y va allí con los demás compañeros, nos atormenta con sus relatos.\"},{\"heading\":false,\"text\":\"--¡Los advenedizos y las rápidas fortunas han engendrado en ti, Florencia, tanto orgullo e inmoderación, que tú misma te lamentas ya por esa causa!\"},{\"heading\":false,\"text\":\"Así exclamé con el rostro levantado; y las tres sombras, oyendo esta respuesta, se miraron mutuamente, como cuando se oyen cosas que se tienen por verdaderas.\"},{\"heading\":false,\"text\":\"--¡Si tan poco te cuesta en otras ocasiones satisfacer las preguntas de cualquiera--respondieron todos--, dichoso tú que dices lo que sientes! Mas, si sales de estos lugares, obscuros, y vuelves a ver las hermosas estrellas, cuando te plazca decir: \\\"Estuve allí,\\\" haz que los hombres hablen de nosotros.\"},{\"heading\":false,\"text\":\"En seguida rompieron el círculo, y huyeron tan de prisa, que sus piernas parecían alas. No podría decirse \\\"amén\\\" tan pronto como ellos desaparecieron: por lo cual mi Maestro determinó que nos fuésemos. Yo le seguía, y a los pocos pasos advertí que el ruido del agua estaba tan próximo, que aun hablando alto apenas nos hubieran oído. Como aquel río que sigue su propio curso desde el monte Veso hacia levante por la izquierda del Apenino, el cual se llama Acquacheta antes de precipitarse en un lecho más bajo, y perdiendo este nombre en Forli, y formando después una cascada, ruge sobre San Benedetto en los Alpes, donde un millar de hombres debiera hallar su retiro, así en la parte inferior de una roca escarpada, oímos resonar tan fuertemente aquella agua teñida de sangre, que me habría hecho ensordecer en poco tiempo. Tenía yo una cuerda ceñida al cuerpo, con la cual había esperado apoderarme de la pantera de pintada piel: cuando me la desaté, según me lo había ordenado mi Guía, se la presenté arrollada y replegada: entonces se volvió hacia la derecha, y desde una distancia considerable de la orilla, la arrojó en aquel abismo profundo. \\\"Preciso es, decía yo entre mí, que alguna novedad responda a esa nueva señal, cuyo efecto espera con tanta atención mi Maestro.\\\" ¡Oh!; ¡qué circunspectos deberían ser los hombres ante los que, no solamente ven sus actos, sino que, con la inteligencia, leen en el fondo de su pensamiento! Mi Guía me dijo:\"},{\"heading\":false,\"text\":\"--Pronto vendrá de arriba lo que espero, y pronto también es preciso que descubran tus ojos lo que tu pensamiento no ve con claridad.\"},{\"heading\":false,\"text\":\"El hombre debe, siempre que pueda, cerrar sus labios antes de decir una verdad, que tenga visos de mentira; porque se expone a avergonzarse sin tener culpa. Pero ahora no puedo callarme, y te juro, ¡oh lector!, por los versos de esta comedia, a la que deseo la mayor aceptación, que vi venir nadando por el aire denso y obscuro una figura, que causaría espanto al corazón más entero; la cual se asemejaba al buzo que vuelve del fondo adonde bajó acaso a desprender el ancla que está afianzada a un escollo, u otro cualquier objeto escondido en el mar, y que extiende hacia arriba los brazos, al mismo tiempo que encoge sus piernas.\"}]},{\"title\":\"Infierno — canto decimoseptimo\",\"blocks\":[{\"heading\":false,\"text\":\"He ahí la fiera de aguzada cola, que traspasa las montañas, y rompe los muros y las armas: he ahí la que corrompe al mundo entero.\"},{\"heading\":false,\"text\":\"Así empezó a hablarme mi Maestro, e hizo a aquélla una seña, indicándole que se dirigiera hacia la margen de piedra donde nos encontrábamos. Y aquella inmunda imagen del fraude, llegó a nosotros, y adelantó la cabeza y el cuerpo, pero no puso la cola sobre la orilla. Su rostro era el de un varón justo, tan bondadosa era su apariencia exterior, y el resto del cuerpo el de una serpiente. Tenía dos garras llenas de vello hasta los sobacos, y la espalda, el pecho y los costados salpicados de tal modo de lazos y escudos, que no ha habido tela turca ni tártara tan rica en colores, no pudiendo compararse tampoco a aquéllos los de las telas de Aracnea. Como se ven muchas veces las barcas en la orilla, mitad en el agua y mitad en tierra, o como en el país de los glotones tudescos el castor se prepara a hacer la guerra a los peces, así la detestable fiera se mantenía sobre el cerco de piedra que circunda la arenosa llanura, agitando su cola en el vacío, y levantando el venenoso dardo de que tenía armada su extremidad, como la de un escorpión. Mi Guía me dijo:\"},{\"heading\":false,\"text\":\"--Ahora conviene que dirijamos nuestros pasos hacia la perversa fiera que allí está tendida.\"},{\"heading\":false,\"text\":\"Por lo cual descendimos por la derecha, y dimos diez pasos sobre la extremidad del margen, procurando evitar la arena abrasada y las llamas: cuando llegamos donde la fiera se encontraba, vi a corta distancia sobre la arena mucha gente sentada al borde del abismo. Allí me dijo mi Maestro:\"},{\"heading\":false,\"text\":\"--A fin de que adquieras una completa experiencia de lo que es este recinto, anda y examina la condición de aquellas almas, pero que sea corta tu conferencia. Mientras vuelves, hablaré con esta fiera, para que nos preste sus fuertes espaldas.\"},{\"heading\":false,\"text\":\"Continué, pues, andando solo hasta el extremo del séptimo círculo, donde gemían aquellos desgraciados. El dolor brotaba de sus ojos, mientras acá y allá se defendían con las manos, ya de las pavesas, ya de la candente arena, como los perros, en el estío, rechazan con las patas o con el hocico las pulgas, moscas o tábanos, que les molestan. Mirando atentamente el rostro de muchos de aquellos a quienes azota el doloroso fuego, no conocí a ninguno; pero observé que del cuello de cada cual pendía una bolsa de cierto color, marcada con un signo, en cuya contemplación parecían deleitarse sus miradas. Aproximándome más para examinar mejor, vi en una bolsa amarilla una figura azul, que tenía toda la apariencia de un león. Después, prosiguiendo el curso de mis observaciones, vi otra, roja como la sangre, que ostentaba una oca más blanca que la leche. Uno de ellos, en cuya bolsa blanca figuraba una puerca preñada, de color azul, me dijo:\"},{\"heading\":false,\"text\":\"--¿Qué haces en esta fosa? Véte; y puesto que aún vives, sabe que mi vecino Vitaliano debe sentarse aquí a mi izquierda. Yo soy paduano, en medio de estos florentinos, que muchas veces me atruenan los oídos gritando: \\\"Venga el caballero soberano, que llevará la bolsa con los tres picos.\\\"\"},{\"heading\":false,\"text\":\"Después torció la boca, y sacó la lengua como el buey que se lame las narices. Y yo, temiendo que mi tardanza incomodase a aquél que me había encargado que estuviera allí poco tiempo, volví la espalda a tan miserables almas. Encontré a mi Guía, que había saltado ya sobre la grupa del feroz animal, y me dijo:\"},{\"heading\":false,\"text\":\"--Ahora sé fuerte y atrevido. Por aquí no se baja sino por escaleras de esta clase: monta delante; quiero quedarme entre ti y la cola, a fin de que ésta no pueda hacerte daño alguno.\"},{\"heading\":false,\"text\":\"Al oír estas palabras, me quedé como aquel que, presintiendo el frío de la cuartana, tiene ya las uñas pálidas, y tiembla con todo su cuerpo tan sólo al mirar la sombra; pero su sentido amenazador me produjo la vergüenza que da ánimo a un servidor delante de un buen amo. Me coloqué sobre las anchas espaldas de la fiera, y quise decir: \\\"Ten cuidado de sostenerme;\\\" pero, contra lo que esperaba, me faltó la voz; si bien él, que ya anteriormente me había socorrido en todos los peligros, apenas monté, me estrechó y me sostuvo entre sus brazos. Después dijo:\"},{\"heading\":false,\"text\":\"--Gerión, ponte ya en marcha, trazando anchos círculos y descendiendo lentamente: piensa en la nueva carga que llevas.\"},{\"heading\":false,\"text\":\"Aquel animal fué retrocediendo como la barca que se aleja de la orilla, y cuando sintió todos sus movimientos en libertad, revolvió la cola hacia donde antes tenía el pecho, y extendiéndola, la agitó como una anguila, atrayéndose el aire con las garras. No creo que Faetón tuviera tanto miedo, cuando abandonó las riendas, por lo cual se abrasó el cielo, como se puede ver todavía; ni el desgraciado Icaro, cuando, derritiéndose la cera, sintió que las alas se desprendían de su cintura, al mismo tiempo que su padre le gritaba: \\\"Mal camino llevas,\\\" como el que yo sentí, al verme en el aire por toda partes, y alejado de mi vista todo, excepto la fiera. Esta empezó a marchar, nadando lentamente, girando y descendiendo; pero yo no podía apercibirme más que del viento que sentía en mi rostro y en la parte inferior de mi cuerpo. Empecé a oír hacia la derecha el horrible estrépito que producían las aguas en el abismo; por lo cual incliné la cabeza y dirigí mis miradas hacia abajo, causándome un gran miedo aquel precipicio; porque vi llamas y percibí lamentos, que me obligaron a encogerme tembloroso. Entonces observé, pues no lo había reparado antes, que descendíamos dando vueltas, como me lo hizo notar la proximidad de los grandes dolores, amontonados por doquier en torno nuestro. Como el halcón, que ha permanecido volando largo tiempo sin ver reclamo ni pájaro alguno, hace exclamar al halconero: \\\"¡Eh! ¿Ya bajas?,\\\" y efectivamente desciende cansado de las alturas donde trazaba cien rápidos círculos, posándose lejos del que lo amaestró, desdeñoso e iracundo, así nos dejó Gerión en el fondo del abismo, al pie de una desmoronada roca; y libre de nuestras personas, se alejó como la saeta despedida por la cuerda.\"}]},{\"title\":\"Infierno — canto decimooctavo\",\"blocks\":[{\"heading\":false,\"text\":\"Hay un lugar en el Infierno, llamado Malebolge,[18] construído todo de piedra y de color ferruginoso, como la cerca que lo rodea. En el centro mismo de aquella funesta planicie se abre un pozo bastante ancho y profundo, de cuya estructura me ocuparé en su lugar. El espacio que queda entre el pozo y el pie de la dura cerca es redondo, y está dividido en diez valles, o recintos cerrados, semejantes a los numerosos fosos que rodean a un castillo para defensa de las murallas; y así como estos fosos tienen puentes que van desde el umbral de la puerta a su otro extremo, del mismo modo aquí avanzaban desde la base de la montaña algunas rocas, que atravesando las márgenes y los fosos, llegaban hasta el pozo central, y allí se reunían quedando truncadas. Tal era el sitio donde nos encontramos cuando descendimos de la grupa de Gerión: el Poeta echó a andar hacia la izquierda, y yo seguí tras él. A mi derecha vi nuevas causas de conmiseración, nuevos tormentos y nuevos burladores, que llenaban la primera fosa. En el fondo estaban desnudos los pecadores; los del centro acá venían de frente a nosotros; y los de esta parte afuera seguían nuestra misma dirección, pero con paso más veloz. Como en el año del Jubileo, a causa de la afluencia de gente que atraviesa el puente de San Angelo, los romanos han determinado que todos los que se dirijan al castillo y vayan hacia San Pedro pasen por un lado, y por el otro los que van hacia el monte, así vi, por uno y otro lado de la negra roca, cornudos demonios con grandes látigos, que azotaban cruelmente las espaldas de los condenados. ¡Oh! ¡Cómo les hacían mover las piernas al primer golpe! Ninguno aguardaba el segundo ni el tercero. Mientras yo andaba, mis ojos se encontraron con los de un pecador, y dije en seguida: \\\"No es la primera vez que veo a ése.\\\" Por lo que me detuve a observarlo mejor: mi dulce Guía se detuvo al mismo tiempo, y aun me permitió retroceder un tanto. El azotado creyó ocultarse bajando la cabeza; mas le sirvió de poco, pues le dije:\"},{\"heading\":false,\"text\":\"[18] \\\"Malebolge,\\\" fosas malditas. Vocablo dantesco compuesto de \\\"bolge,\\\" bolsas, alforjas, y \\\"male\\\" malditas.\"},{\"heading\":false,\"text\":\"--Tú, que fijas los ojos en el suelo, si no son falsas las facciones que llevas, eres Venedico Caccianimico. Pero ¿qué es lo que te ha traído a tan picantes salsas?\"},{\"heading\":false,\"text\":\"A lo que me contestó:\"},{\"heading\":false,\"text\":\"--Lo digo con repugnancia; pero cedo a tu claro lenguaje, que me hace recordar el mundo de otro tiempo. Yo fuí aquel que obligó a la bella Ghisola a satisfacer los deseos del Marqués, cuéntese como se quiera la tal historia. Y no soy el único boloñés que llora aquí; antes bien este sitio está tan lleno de ellos, que no hay en el día entre el Savena y el Reno tantas lenguas que digan \\\"sipa,\\\"[19] como en esta fosa; y si quieres una prueba de lo que te digo, recuerda nuestra codicia notoria.\"},{\"heading\":false,\"text\":\"[19] En la provincia de Bolonia, situada entre los ríos Savena y Reno, para decir sia o sí, decían sipa o sipó. En el día pronuncian: se pó, que viene a ser el c\'est bon de los franceses.\"},{\"heading\":false,\"text\":\"Mientras así hablaba, un demonio le pegó un latigazo, diciéndole: \\\"Anda, rufián; que aquí no hay mujeres que se vendan.\\\"\"},{\"heading\":false,\"text\":\"Me reuní a mi Guía; y a los pocos pasos llegamos a un punto de donde salía una roca de la montaña. Subimos por ella ligeramente, y volviendo a la derecha sobre su áspero dorso, salimos de aquel eterno recinto. Luego que llegamos al sitio en que aquel peñasco se ahueca por debajo a modo de puente, para dar paso a los condenados, mi Guía me dijo:\"},{\"heading\":false,\"text\":\"--Detente, y haz que en ti se fijen las miradas de esos otros malnacidos, cuyos rostros no has visto aún, porque han caminado hasta ahora en nuestra misma dirección.\"},{\"heading\":false,\"text\":\"Desde el vetusto puente contemplamos la larga fila que hacia nosotros venía por la otra parte, y que era igualmente castigada por el látigo. El buen Maestro me dijo, sin que yo le preguntara nada:\"},{\"heading\":false,\"text\":\"--Mira esa gran sombra que se acerca, y que, a pesar de su dolor, no parece derramar ninguna lágrima. ¡Qué aspecto tan majestuoso conserva aún! Ese es Jasón, que con su valor y su destreza robó en Cólquide el vellocino de oro. Pasó por la isla de Lemnos, después que las audaces y crueles mujeres de aquella isla dieron muerte a todos los habitantes varones; y allí, con sus artificios y sus halagüeñas palabras, engañó a la joven Hisipila, que antes había engañado a todas sus compañeras, y la dejó encinta y abandonada; por tal culpa está condenado a tal martirio, que es también la venganza de Medea. Con él van todos los que han cometido igual clase de engaños: bástete, pues, saber esto de la primera fosa, y de los que en ella son atormentados.\"},{\"heading\":false,\"text\":\"Nos encontrábamos ya en el punto donde el estrecho sendero se cruza con el segundo margen, que sirve de apoyo para otro arco. Allí vimos a los que se anidan en una nueva fosa, dando resoplidos con sus narices y golpeándose con sus propias manos. Las orillas estaban incrustadas de moho, producido por las emanaciones de abajo, que allí se condensan, ofendiendo a la vista y al olfato. La fosa es tan profunda, que no se puede ver el fondo, sino mirando desde la parte más alta del arco, que lo domina perpendicularmente. Allí nos pusimos, y desde aquel punto vimos en el foso unas gentes sumergidas en un estiércol, que parecía salir de las letrinas humanas; y mientras tenía la vista fija allí dentro, vi uno con la cabeza tan sucia de excremento, que no podía saber si era clérigo o seglar. Aquella cabeza me dijo:\"},{\"heading\":false,\"text\":\"--¿Por qué te muestras tan ávido de mirarme a mí, con preferencia a los otros que están tan sucios como yo?\"},{\"heading\":false,\"text\":\"Le respondí:\"},{\"heading\":false,\"text\":\"--Porque, si mal no recuerdo, te he visto otra vez con los cabellos enjutos, y tú eres Alejo Interminelli de Luca; por eso te miro más que a todos los otros.\"},{\"heading\":false,\"text\":\"Entonces, él, golpeándose la calabaza, exclamó:\"},{\"heading\":false,\"text\":\"--Aquí me han sumergido las lisonjas que no se cansó de prodigar mi lengua.\"},{\"heading\":false,\"text\":\"Después de esto, mi Guía me dijo:\"},{\"heading\":false,\"text\":\"--Procura adelantar un poco la cabeza, a fin de que tus miradas alcancen las facciones de aquella sucia esclava desmelenada, que se desgarra las carnes con sus uñas llenas de inmundicia, y que tan pronto se encoge como se estira. Esa es Thais, la prostituta, que cuando su amante le preguntó: \\\"¿Tengo grandes méritos a tus ojos?,\\\" ella le contestó: \\\"Sí, maravillosos.\\\" Y con esto queden saciadas nuestras miradas.\"}]},{\"title\":\"Infierno — canto decimonono\",\"blocks\":[{\"heading\":false,\"text\":\"¡Oh Simón el mago! ¡Oh miserables sectarios suyos, almas rapaces, que prostituís a cambio de oro y plata las cosas de Dios, que deben ser las esposas de la virtud! Ahora resonará la trompa para vosotros, puesto que os encontráis en la tercera fosa.\"},{\"heading\":false,\"text\":\"Estábamos ya junto a ésta, subidos en aquella parte del escollo que cae justamente sobre su centro. ¡Oh suma Sabiduría! ¡Cuán grande es el arte que demuestras en el cielo, en la tierra y en el mundo maldito, y con cuánta equidad se reparte tu virtud! Vi en los lados y en el fondo la piedra lívida llena de pozuelos, todos redondos y de igual tamaño, los cuales me parecieron ni más ni menos anchos que los que hay en mi hermoso San Juan para servir de pilas bautismales; uno de éstos rompí yo no ha muchos años, por salvar a un niño que dentro de él se ahogaba; y baste lo que digo, para desengañar a todos.[20] Fuera de la boca de cada uno de aquellos pozuelos salían los pies y las piernas de un pecador, hasta el muslo, quedando dentro el resto del cuerpo. Ambos pies estaban encendidos, por cuya razón se agitaban tan fuertemente sus coyunturas, que hubieran roto sogas y cuerdas. Del mismo modo que la llama suele recorrer la superficie de los objetos untados de grasa, así el fuego flameaba desde el talón a la punta en los pies de los condenados.\"},{\"heading\":false,\"text\":\"[20] Habiendo roto Dante una de las pilas bautismales de la iglesia de San Juan en Florencia, para salvar a un niño que se ahogaba, fué acusado de sacrilegio. Por esto hace constar aquí que no lo hizo por desprecio a las cosas sagradas, sino por amor a la humanidad.\"},{\"heading\":false,\"text\":\"--¿Quién es aquél, Maestro, que furioso agita los pies más que sus otros compañeros--dije entonces--, y a quien corroe y deseca una llama mucho más roja?\"},{\"heading\":false,\"text\":\"A lo cual me contestó:\"},{\"heading\":false,\"text\":\"--Si quieres que te conduzca por aquella parte de la escarpa que está más cercana al fondo, él mismo te dirá quién es y cuáles son sus crímenes.\"},{\"heading\":false,\"text\":\"Le respondí:\"},{\"heading\":false,\"text\":\"--Me parece bien todo lo que a ti te agrada: tú eres el dueño y sabes que yo no me separo de tu voluntad, así como también conoces lo que me callo.\"},{\"heading\":false,\"text\":\"Subimos entonces al cuarto margen; después volvimos y bajamos por la izquierda hacia la estrecha y perforada fosa, sin que el buen Maestro me hiciera separar de su lado, hasta haberme conducido junto al hoyo de aquel que daba tantas señales de dolor con los movimientos de sus piernas.\"},{\"heading\":false,\"text\":\"--¡Oh! Quienquiera que seas, tú, que tienes enterrada la parte superior de tu cuerpo; alma triste, plantada como una estaca--empecé a decir--, habla, si puedes.\"},{\"heading\":false,\"text\":\"Yo estaba como el fraile que confiesa al pérfido asesino, que, metido en la tierra, le llama para que cese su muerte. Y él gritó:\"},{\"heading\":false,\"text\":\"--¿Estás ya aquí derecho, estás ya aquí derecho, Bonifacio?[21] Me ha engañado en algunos años lo que está escrito. ¿Tan pronto te has saciado de aquellos bienes, por los cuales no temiste apoderarte con embustes de la hermosa Dama,[22] y gobernarla después indignamente?\"},{\"heading\":false,\"text\":\"[21] Esta sombra es la del papa Nicolás III, de la familia de los Orsini de Roma, electo en 1277. Cree que quien le interroga es el alma de Bonifacio VIII; y por eso dice: \\\"¿Estás ya aquí, Bonifacio?\\\" Y añade en seguida: \\\"Me ha engañado en algunos años lo escrito.\\\" Es decir: El libro profético, en que nosotros los condenados leemos lo futuro, me ha engañado; porque, según él, tú debías morir en 1303, y no en 1300.\"},{\"heading\":false,\"text\":\"[22] Según la Historia, esta opinión de Dante es exagerada. Sin embargo, Celestino V dijo de Bonifacio VIII, que este papa entró a reinar como un zorro, gobernó como un león y murió como un perro.\"},{\"heading\":false,\"text\":\"Quedéme, al oír esto, como aquellos que, casi avergonzados de no haber comprendido lo que se les ha dicho, no saben qué contestar. Entonces Virgilio dijo:\"},{\"heading\":false,\"text\":\"--Respóndele pronto: \\\"yo no soy, yo no soy el que tú crees.\\\"\"},{\"heading\":false,\"text\":\"Y yo contesté como se me ordenó. Por lo cual el espíritu retorció sus pies; y luego, suspirando y con llorosa voz, me dijo:\"},{\"heading\":false,\"text\":\"--¿Pues qué es lo que me preguntas? Si te urge conocer quién soy, hasta el punto de haber descendido para ello por todos estos peñascos, sabrás que estuve investido del gran manto, y fuí verdadero hijo de la Osa, tan codicioso, que, por aumentar la riqueza de los oseznos, embolsé arriba todo el dinero que pude, y aquí mi alma. Bajo mi cabeza están sepultados los demás papas, que antes de mí cometieron simonía, y se hallan comprimidos a lo largo de este angosto agujero. Yo me hundiré también luego que venga aquel que creí fueses tú, cuando te dirigí mi súbita pregunta. Pero desde que mis pies se abrasan, y me encuentro colocado al revés, ha transcurrido más tiempo del que él permanecerá en este mismo sitio con los pies quemados; porque en pos de él vendrá de poniente un pastor sin ley, por causa más repugnante, y ése deberá cubrirnos a entrambos. Será un nuevo Jasón, parecido al de que se habla en el libro de los Macabeos; y así como el rey de éste fué débil para con él, así con el otro lo será el que rige la Francia.\"},{\"heading\":false,\"text\":\"No sé si en tal momento fué demasiada audacia la mía; pues le respondí en estos términos:\"},{\"heading\":false,\"text\":\"--¡Eh!, dime: ¿cuánto dinero exigió Nuestro Señor de San Pedro, antes de poner las llaves en su poder? En verdad que no le pidió más sino que le siguiera. Ni Pedro ni los otros pidieron a Matías oro ni plata cuando por suerte fué elegido en reemplazo del que perdió su alma traidora. Permanece, pues, ahí, porque has sido castigado justamente, y guarda bien la mal adquirida riqueza, que tan atrevido te hizo contra Carlos. Y si no fuese porque aun me contiene el respeto a las llaves soberanas, que poseíste en tu alegre vida, emplearía palabras mucho más severas; porque vuestra avaricia contrista al mundo, pisoteando a los buenos, y ensalzando a los malos. Pastores, a vosotros se refería el Evangelista, cuando vió prostituída ante los reyes a la que se sienta sobre las aguas; a la que nació con siete cabezas, y obtuvo autoridad por sus diez cuernos, mientras la virtud agradó a su marido.[23] Os habéis construído dioses de oro y plata: ¿qué diferencia, pues, existe entre vosotros y los idólatras, sino la de que ellos adoran a uno y vosotros adoráis a ciento? ¡Ah, Constantino! ¡A cuántos males dió origen, no tu conversión al cristianismo, sino la donación que de ti recibió el primer papa que fué rico!\"},{\"heading\":false,\"text\":\"[23] Dante alude aquí a Roma, edificada sobre siete colinas, a la que rendían obediencia muchos pueblos y naciones, y permaneció constituída en gran poder y autoridad, mientras (su marido) sus jefes fueron virtuosos: pero decayó en la opinión, que por tanto tiempo había merecido y gozado, cuando la corte romana prefirió a la virtud el oro y la plata, prostituyéndose a los reyes de la tierra.\"},{\"heading\":false,\"text\":\"Mientras yo le hablaba con esta claridad, él, ya fuese a impulsos de la ira, o porque le remordiese la conciencia, respingaba fuertemente con ambas piernas. Creo que complací a mi Guía; porque escuchó siempre con rostro satisfecho el sonido de mis palabras, expresadas con sinceridad. Entonces me cogió con los dos brazos, y teniéndome en alto bien afianzado sobre su pecho, volvió a subir por el camino por donde habíamos descendido, sin dejar de estrecharme contra sí, hasta llegar a la parte superior del puente que va de la cuarta a la quinta calzada. Allí, depositó suavemente su querido fardo sobre el áspero y pelado escollo, que hasta para las cabras sería un difícil sendero, desde donde descubrí una nueva fosa.\"}]},{\"title\":\"Infierno — canto vigesimo\",\"blocks\":[{\"heading\":false,\"text\":\"Mis versos deben relatar un nuevo suplicio, el cual servirá de asunto al vigésimo canto del primer cántico, que trata de los sumergidos en el Infierno. Me hallaba ya dispuesto a contemplar el descubierto fondo, que está bañado de lágrimas de angustia, cuando vi venir por la fosa circular gentes que, llorando en silencio, caminaban con aquel paso lento que llevan las letanías en el mundo. Cuando incliné más hacia ellos mi mirada, me pareció que cada uno de aquellos condenados estaba retorcido de un modo extraño desde la barba al principio del pecho; pues tenían el rostro vuelto hacia las espaldas, y les era preciso andar hacia atrás, porque habían perdido la facultad de ver por delante. Quizá, por la fuerza de la perlesía, se encuentre un hombre de tal manera contrahecho; pero yo no lo he visto ni creo que pueda suceder. Ahora bien, lector, ¡así Dios te permita sacar fruto de esta lectura! Considera por ti mismo si mis ojos podrían permanecer secos, cuando vi de cerca nuestra humana figura tan torcida, que las lágrimas le caían por la espina dorsal. Yo lloraba en verdad, apoyado contra una de las rocas de la dura montaña, de suerte que mi Guía me dijo:\"},{\"heading\":false,\"text\":\"--¿Tú también eres de los insensatos? Aquí vive la piedad cuando está bien muerta. ¿Quién es más criminal que el que se apasiona contemplando la justicia divina? Levanta la cabeza, levántala y mira a aquel por quién se abrió la tierra en presencia de los tebanos, que exclamaban: \\\"¿Adónde caes, Anfiarao? ¿Por qué abandonas la guerra?\\\" Y no cesó de caer en el Infierno hasta llegar a Minos, que se apodera de cada culpable. Mira cómo ha convertido sus espaldas en pecho: por haber querido ver demasiado hacia adelante, ahora mira hacia atrás, y sigue un camino retrógrado. Mira a Tiresias, que mudó de aspecto cuando de varón se convirtió en hembra, cambiando también todos su miembros, y hubo de abatir con su vara las dos serpientes unidas, antes que recobrara su pelo viril. El que acerca sus espaldas al vientre de aquél es Aronte, que tuvo por morada una gruta de blancos mármoles en las montañas de Luni, cultivadas por el carrarés que habita en su falda, y desde allí no había nada que limitara su vista, cuando contemplaba el mar o las estrellas. Aquella que, con los destrenzados cabellos, cubre sus pechos, por lo cual se ocultan a tus miradas, y tiene en ese lado de su cuerpo todas las partes velludas, fué Manto, que recorrió muchas comarcas, hasta que se detuvo en el sitio donde yo nací; por lo cual deseo que me prestes un poco de atención. Luego que su padre salió de la vida, y fué esclavizada la ciudad de Baco,[24] Manto anduvo errante por el mundo durante mucho tiempo. Allá arriba, en la bella Italia, existe un lago al pie de los Alpes que ciñen la Alemania por la parte superior del Tirol, el cual se llama Benaco. Mil corrientes, y aun más, según creo, vienen a aumentar, entre Garda, Val-Camonica y el Apenino, el agua que se estanca en dicho lago. En medio de éste hay un sitio, donde el Pastor de Trento, y los de Verona y Brescia, podrían dar su bendición si siguiesen aquel camino. En el punto donde es más baja la orilla que le circunda, está situada Peschiera, bello y fuerte castillo, a propósito para hacer frente a los de Brescia y a los de Bérgamo. Allí afluye necesariamente toda el agua que no puede estar contenida en el lago de Benaco, formando un río que corre entre verdes praderas. En cuanto aquella agua sigue un curso propio, ya no se llama Benaco, sino Mincio, hasta que llega a Governolo, donde desemboca en el Po. No corre mucho sin que encuentre una hondonada, en la cual se extiende y se estanca, y suele ser malsana en el estío. Pasando, pues, por allí la feroz doncella, vió en medio del pantano una tierra inculta y deshabitada. Se detuvo en ella con sus esclavas, para huír de todo consorcio humano, y para ejercer su arte mágica, y allí vivió y dejó sus restos mortales. Entonces los hombres, que estaban dispersos por los alrededores, se reunieron en aquel sitio, que era fuerte a causa del pantano que le circundaba: edificaron una ciudad sobre los huesos de la difunta, y del nombre de la primera que había elegido aquel sitio, la llamaron Mantua, sin consultar para ello al Destino. En otro tiempo fueron sus habitantes más numerosos, antes de que Casalodi se dejara engañar neciamente por Pinamonte. Te lo advierto a fin de que, si oyes atribuir otro origen a mi patria, ninguna mentira pueda obscurecer la verdad.\"},{\"heading\":false,\"text\":\"[24] Tebas, ciudad consagrada a Baco.\"},{\"heading\":false,\"text\":\"Le respondí:\"},{\"heading\":false,\"text\":\"--Maestro, tus razonamientos son para mí tan verídicos, y me obligan a prestarles tanta fe, que cualesquiera otros me parecerían carbones apagados. Pero dime si entre la gente que va pasando hay alguno digno de notarse, pues eso solo ocupa mi alma.\"},{\"heading\":false,\"text\":\"Entonces me dijo:\"},{\"heading\":false,\"text\":\"--Aquél, cuya barba se extiende desde el rostro a sus morenas espaldas, fué augur cuando la Grecia se quedó tan exhausta de varones, que apenas los había en las cunas, y junto con Calcas dió la señal en Aulide para cortar el primer cable. Se llamó Euripilo, y así lo nombra en algún punto mi alta tragedia. Aquel otro que ves tan demacrado fué Miguel Scott, que conoció perfectamente las imposturas del arte mágica. Mira a Guido Bonatti, y ve allí a Asdente, que ahora desearía no haber dejado su cuero y su bramante; pero se arrepiente demasiado tarde: contempla las tristes que abandonaron la aguja, la lanzadera y el huso para convertirse en adivinas, y para hacer maleficios con hierbas y con figuras. Pero ven ahora, porque ya el astro en que se ve a Caín con las espinas ocupa el confín de los dos hemisferios, y toca el mar más abajo de Sevilla. La luna era ya redonda en la noche anterior; debes recordar bien que no te molestó a veces por la selva umbría.\"},{\"heading\":false,\"text\":\"Así me hablaba y entre tanto íbamos caminando.\"}]},{\"title\":\"Infierno — canto vigesimoprimero\",\"blocks\":[{\"heading\":false,\"text\":\"Así, de un puente a otro, y hablando de cosas que mi comedia no se cuida de referir, fuimos avanzando y llegamos a lo alto del quinto, donde nos detuvimos para ver la otra hondonada de Malebolge y otras vanas lágrimas, y la vi maravillosamente obscura. Así como en el arsenal de los venecianos hierve en el invierno la pez tenaz, destinada a reparar los buques averiados que no pueden navegar, y al mismo tiempo que uno construye su embarcación, otro calafatea los costados de la que ha hecho ya muchos viajes; otro recorre la proa, otro la popa; quién hace remos; quién retuerce las cuerdas; quiénes, por fin, reparan el palo de mesana y el mayor; de igual suerte, y no por medio del fuego, sino por la voluntad divina, hervía allá abajo una resina espesa, que se pegaba a la orilla por todas partes. Yo la veía, pero sin percibir en ella más que las burbujas que producía el hervor, hinchándose toda y volviendo a caer desplomada. Mientras la contemplaba fijamente, mi Guía me atrajo hacia sí desde el sitio en que me encontraba, diciéndome: \\\"Ten cuidado, ten cuidado.\\\" Entonces me volví como el hombre que ansía ver aquello de que le conviene huír, y a quien asalta un temor tan grande y repentino, que ni para mirar detiene su fuga; y vi detrás de nosotros un negro diablo, que venía corriendo por el puente. ¡Oh! ¡Cuán feroz era su aspecto, y qué amenazador me parecía con sus alas abiertas y sus ligeros pies! Sobre sus hombros, altos y angulosos, llevaba a cuestas un pecador, a quien tenía agarrado por ambos jarretes. Desde nuestro puente dijo:\"},{\"heading\":false,\"text\":\"--¡Oh! Malebranche, ved aquí uno de los ancianos de Santa Zita: ponedle debajo; que yo me vuelvo otra vez a aquella tierra, que está tan bien provista de ellos. Allí todos son bribones, excepto Bonturo; y por dinero, de un \\\"no\\\" hacen un \\\"ita.\\\"[25]\"},{\"heading\":false,\"text\":\"[25] Solíase antiguamente, en los testimonios públicos, escribir el ita de los latinos por signo de afirmación, y el no por signo de negación.\"},{\"heading\":false,\"text\":\"Le arrojó abajo, y se volvió por la dura roca tan de prisa, que jamás ha habido mastín suelto que haya perseguido a un ladrón con tanta ligereza. El pecador se hundió y volvió a subir hecho un arco; pero los demonios, que estaban resguardados por el puente, gritaban:\"},{\"heading\":false,\"text\":\"--Aquí no está el Santo Rostro; aquí se nada de diferente modo que en el Serchio. Si no quieres probar nuestros garfios, no salgas de la pez.\"},{\"heading\":false,\"text\":\"Después le pincharon con más de cien harpones, diciéndole:\"},{\"heading\":false,\"text\":\"--Es forzoso que bailes aquí a cubierto, de modo que, si puedes, prevariques ocultamente.\"},{\"heading\":false,\"text\":\"No de otra suerte hacen los cocineros que sus marmitones sumerjan en la caldera las viandas por medio de grandes tenedores, para que no sobrenaden.\"},{\"heading\":false,\"text\":\"--A fin de que no adviertan que estás aquí--me dijo el buen Maestro--, ocúltate detrás de una roca, que te sirva de abrigo; y aunque se me haga alguna ofensa, no temas nada; pues ya conozco estas cosas por haber estado otra vez entre estas almas venales.\"},{\"heading\":false,\"text\":\"En seguida pasó al otro lado del puente, y cuando llegó a la sexta orilla, tuvo necesidad de mostrar su intrepidez. Con el furor y el ímpetu con que salen los perros tras el pobre que de pronto pide limosna donde se detiene, así salieron los demonios de debajo del puente, volviendo todos contra él sus harpones; pero les gritó:\"},{\"heading\":false,\"text\":\"--Que ninguno de vosotros se atreva. Antes que me punce vuestra orquilla, adelántese uno que me oiga, y después medite si debe perdonarme.\"},{\"heading\":false,\"text\":\"Todos gritaron:\"},{\"heading\":false,\"text\":\"--Vé, Malacoda.\"},{\"heading\":false,\"text\":\"Por lo cual uno de ellos se puso en marcha, mientras los otros permanecían quietos, y se adelantó diciendo:\"},{\"heading\":false,\"text\":\"--¿Qué te podrá salvar de nuestras garras?\"},{\"heading\":false,\"text\":\"--¿Crees tú, Malacoda, que a no ser por la voluntad divina y por tener el destino propicio--dijo mi Maestro--, me hubieras visto llegar aquí, sano y salvo, a pesar de todas vuestras armas? Déjame pasar, porque en el cielo quieren que enseñe a otro este camino salvaje.\"},{\"heading\":false,\"text\":\"Entonces quedó tan abatido el orgullo del demonio, que dejó caer el harpón a sus plantas, y dijo a los otros:\"},{\"heading\":false,\"text\":\"--Que no se le haga daño.\"},{\"heading\":false,\"text\":\"Y mi guía a mí:\"},{\"heading\":false,\"text\":\"--¡Oh tú, que estás agazapado tras de las rocas del puente! Ya puedes llegar a mí con toda seguridad.\"},{\"heading\":false,\"text\":\"Entonces eché a andar, y me acerqué a él con prontitud; pero los diablos avanzaron, de modo que yo temí que no observaran lo pactado: así vi temblar en otro tiempo a los que por capitulación salían de Caprona, viéndose entre tantos enemigos. Me acerqué cuanto pude a mi Guía, y no separaba mis ojos del rostro de aquéllos, que no era nada bueno. Bajaban ellos sus garfios, y: \\\"¿Quiéres que le pinche en la rabadilla?,\\\" decía uno de ellos a los otros. Y respondían: \\\"Sí, sí clávale.\\\" Pero aquel demonio, que estaba conversando con mi Guía, se volvió de repente, y gritó: \\\"Quieto, quieto, Scarmiglione.\\\" Después nos dijo:\"},{\"heading\":false,\"text\":\"--Por este escollo no podréis ir más lejos, pues el sexto arco yace destrozado en el fondo. Si os place ir más adelante, seguid esta costa escarpada: cerca veréis otro escollo por el que podréis pasar. Ayer, cinco horas más tarde que en este momento, se cumplieron mil doscientos sesenta y seis años desde que se rompió aquí el camino.[26] Voy a enviar hacia allá varios de los míos para que observen si algún condenado procura sacar la cabeza al aire: id con ellos, que no os harán daño.\"},{\"heading\":false,\"text\":\"[26] Ayer, Viernes, a las tres de la tarde, quiere decir el diablo (pues se supone que habla a las diez de la mañana del Sábado Santo), se cumplieron 1266 años desde que se rompió este puente, a consecuencia de un terremoto, en el momento de la muerte de Jesucristo.\"},{\"heading\":false,\"text\":\"--Adelante, Alichino y Calcabrina--empezó a decir--; y tú también, Cagnazzo; Barbariccia guiará a los diez. Vengan además Libicocco, y Draghignazzo; Ciriatto, el de los grandes colmillos, y Graffiacane, y Farfarello, y el loco de Rubicantondad en torno de la pez hirviente: éstos deben llegar salvos hasta el otro escollo, que atraviesa enteramente sobre la fosa.[27]\"},{\"heading\":false,\"text\":\"[27] He aquí traducidos los nombres de los doce diablos que Dante menciona en este canto: Malebranche, malas garras.--Malacoda, cola maldita.--Scarmiglione, que arranca los cabellos.--Alichino, que hace inclinar a los otros.--Calcabrina, que pisa el rocío.--Cagnazzo, perro malo.--Barbariccia, el de la barba erizada.--Libicocco, deseo ardiente.--Draghignazzo, veneno de dragón.--Ciriatto-Sannuto, colmillo de jabalí.--Graffiaccane, perro que araña.--Rubicante, inflamado. Todas estas versiones son de Landino.\"},{\"heading\":false,\"text\":\"--¡Oh Maestro! ¿Qué es lo que veo?--dije--; si conoces el camino, vamos sin escolta; yo, por mí, no la solicito. Si eres tan prudente como de costumbre, ¿no ves que rechinan los dientes, y se hacen guiños que nos amenazan algún mal?\"},{\"heading\":false,\"text\":\"--No quiero que te espantes--me contestó--; deja que rechinen los dientes a su gusto. Si lo hacen, es por los desgraciados que están hirviendo.\"},{\"heading\":false,\"text\":\"Se pusieron en camino por la margen izquierda; pero cada uno de aquéllos de antemano se habían mordido la lengua en señal de inteligencia con su jefe, y éste se sirvió de su ano a guisa de trompeta.\"}]},{\"title\":\"Infierno — canto vegisimosegundo\",\"blocks\":[{\"heading\":false,\"text\":\"He visto alguna vez a la caballería levantar el campo, empezar el combate, pasar revista, y a veces batirse en retirada; he visto ¡oh, aretinos! hacer excursiones por vuestra tierra y saquearla; he visto luchar en los torneos y correr en las justas, ya al sonido de las trompetas, ya al de las campanas, al ruido de los tambores, con las señales de los castillos, y con todo el aparato nacional y extranjero; pero lo que no he visto nunca es que tan extraño instrumento de viento haya indicado la marcha a jinetes ni peones; jamás, ni en la tierra, ni en los cielos, guió semejante faro a ningún buque. Marchábamos juntamente con los diez demonios (¡oh terrible compañía!); pero en la iglesia con los santos, y en la taberna con los borrachos. Sin embargo, mi atención estaba concentrada en la pez para distinguir todo lo que contenía la fosa y los que se abrasaban dentro de ella. Así como saltan los delfines fuera del agua, indicando a los marinos que precavan la nave de la tempestad, así también algunos condenados, para aliviar su tormento, sacaban la espalda y la volvían a esconder más rápidos que el relámpago; y lo mismo que en un charco las ranas sacan la cabeza a flor de agua, aunque teniendo dentro de ella sus patas y el resto del cuerpo, así estaban por todas partes los pecadores; pero en cuanto Barbariccia se aproximaba, volvían a sumergirse en aquel hervidero. Yo vi, y aun se estremece por ello mi corazón, a uno de aquellos que había tardado más tiempo en hundirse, como sucede con las ranas, que una queda fuera del agua, mientras otra se zambulle; y Graffiacane, que estaba más cerca de él, le enganchó por los cabellos enviscados de pez, y lo sacó fuera como si fuese una nutria. Yo sabía el nombre de todos aquellos demonios, por haberme hecho cargo de ellos cuando los eligió Malacoda. \\\"Rubicante, plántale encima tu garfio y desuéllalo,\\\" gritaban a un tiempo todos aquellos malditos. Yo dije:\"},{\"heading\":false,\"text\":\"--Maestro mío, si puedes, procura saber quién es ese desgraciado que ha caído en manos de sus adversarios.\"},{\"heading\":false,\"text\":\"Mi Guía se le acercó, y le preguntó de dónde era, a lo que respondió:\"},{\"heading\":false,\"text\":\"--Yo nací en el reino de Navarra. Mi madre me puso al servicio de un señor: ella me había engendrado de un pródigo, que se destruyó a sí mismo y disipó su fortuna. Después fuí favorito del buen rey Tebaldo, y me lancé a comerciar con sus favores; crimen de que doy cuenta en este horno.\"},{\"heading\":false,\"text\":\"Y Ciriatto, a quien salía de cada lado de la boca un colmillo como el de un jabalí, le hizo sentir lo bien que uno de ellos hería. Entre malos gatos había caído aquel ratón; porque Barbariccia lo sujetó entre sus brazos, diciendo: \\\"Quedaos ahí mientras que yo le ensarto.\\\" Y volviendo el rostro hacia mi Maestro, añadió: \\\"Pregúntale aún si deseas saber más, antes que otros lo destrocen.\\\"\"},{\"heading\":false,\"text\":\"Mi Guía preguntó:\"},{\"heading\":false,\"text\":\"--Dime, pues, si entre los otros culpables que están sumergidos en esa pez, conoces algunos que sean latinos.\"},{\"heading\":false,\"text\":\"A lo que contestó:\"},{\"heading\":false,\"text\":\"--Acabo de separarme de uno que fué de allí cerca. ¡Así estuviera, como él, bajo la pez; no temería ahora ni las garras ni los garfios!\"},{\"heading\":false,\"text\":\"Y Libicocco: \\\"Ya hemos tenido demasiada paciencia,\\\" dijo; y le enganchó por el brazo con su harpón, arrancándole de un golpe todo el antebrazo. Draghignazzo quiso también cogerle por las piernas; pero su Decurión se volvió hacia todos ellos lanzando una mirada furiosa. Cuando se hubieron calmado un poco, mi Guía no tardó en preguntar a aquel que estaba contemplando su herida:\"},{\"heading\":false,\"text\":\"--¿Quién es ése de quien dices que te has separado, por tu desgracia, para salir a flote?\"},{\"heading\":false,\"text\":\"Y le respondió:\"},{\"heading\":false,\"text\":\"--Es el hermano Gomita, aquel de Gallura, vaso de iniquidad, que tuvo en su poder a los enemigos de su señor, e hizo de modo que todos le alabasen. Aceptó su oro y los dejó libres, según él mismo dice; y con respecto a los empleos, no fué un pequeño, sino un soberano prevaricador. Con él conversa a menudo don Miguel Zanche de Logodoro, y sus lenguas no se cansan nunca de hablar de las cosas de Cerdeña. ¡Ay de mí! Ved a ese otro cómo aprieta los dientes. Aun hablaría más, pero temo que se prepare a rascarme la tiña.\"},{\"heading\":false,\"text\":\"El gran jefe de los demonios se dirigió a Farfarelo, que movía sus ojos en todas direcciones buscando donde herir, y le dijo: \\\"Quítate de ahí, pájaro malvado.\\\"\"},{\"heading\":false,\"text\":\"--Si queréis ver u oír a toscanos y lombardos--empezó a decir en seguida el desgraciado pecador--, haré que vengan. Pero que esas malditas garras se mantengan un poco apartadas, a fin de que ellos no teman sus venganzas: yo, sentándome en este mismo sitio, por uno que soy haré venir siete, silbando como acostumbramos cuando uno de nosotros saca la cabeza fuera de la pez.\"},{\"heading\":false,\"text\":\"Al oír estas palabras, Gagnazzo levantó el hocico meneando la cabeza, y dijo: \\\"¡Oigan el medio malicioso de que se ha valido para volver a sumergirse!\\\" A lo cual contestó aquél, que tenía abundancia de estratagemas: \\\"¡En verdad que soy muy malicioso, cuando expongo a los míos a mayores tormentos!\\\" No pudo contenerse Alichino, y en contra de lo dicho por los otros, respondió: \\\"Si te arrojas en la pez, no correré al galope detrás de ti, sino que emplearé mis alas para ello. Te damos de ventaja la escarpa, y el ribazo por defensa, y veamos si tú solo vales más que todos nosotros.\\\"\"},{\"heading\":false,\"text\":\"¡Oh tú, que lees esto, ahora verás un nuevo juego! Todos los demonios se volvieron hacia la pendiente opuesta, y el primero de ellos, el que se había mostrado más renitente. El navarro aprovechó bien el tiempo; fijó sus pies en el suelo, y precipitándose de un solo salto, se puso al abrigo de los malos propósitos de aquéllos. Contristados se quedaron los demonios ante esta treta, pero mucho más el que tuvo la culpa de ella; por lo cual se lanzó tras de él gritando: \\\"Ya te tengo.\\\" Pero de poco le valió, porque sus alas no pudieron igualar en velocidad al espanto de Ciampolo: éste se lanzó en la pez, y aquél cambió la dirección de su vuelo, llevando el pecho hacia arriba.\"},{\"heading\":false,\"text\":\"No de otro modo se sumerge instantáneamente el pato cuando el halcón se aproxima, y éste se remonta furioso y fatigado. Calcabrina, irritado contra Lichino por aquel engaño, echó a volar tras él, deseoso de que el pecador se escapara para tener un motivo de querella. Y cuando hubo desaparecido el prevaricador, volvió sus garras contra su compañero, y se aferró con él sobre el mismo estanque. Pero éste, gavilán adiestrado, hizo uso también de las suyas, y los dos cayeron en medio de la pez hirviente. El calor los separó bien pronto; pero todo su esfuerzo para remontarse era en vano, porque sus alas estaban enviscadas. Barbariccia, descontento como los demás, hizo volar a cuatro desde la otra parte con todos sus harpones, y bajando rápidamente hacia el sitio designado, tendieron sus garfios a los dos demonios, que estaban medio cocidos en la superficie de aquella fosa. Nosotros los dejamos allí enredados de aquella manera.\"}]},{\"title\":\"Infierno — canto vigesimotercero\",\"blocks\":[{\"heading\":false,\"text\":\"Solos, en silencio y sin escolta, íbamos uno tras otro, como acostumbran ir los frailes menores. La riña que acabábamos de presenciar me trajo a la memoria la fábula de Esopo, en que habló de la rana y del topo; pues las partículas \\\"mo\\\" e \\\"issa\\\"[28] no son tan semejantes como estos dos hechos, si atentamente se consideran el principio y el fin de entrambos. Y como un pensamiento procede rápidamente de otro, de éste nació uno nuevo, que redobló mi primitivo espanto. Yo pensaba así: \\\"Esos demonios han sido engañados por nuestra causa, y con tanto daño y escarnio, que les creo muy ofendidos. Si a la malevolencia se añade la ira, nos van a perseguir con más crueldad que el perro que sujeta a la liebre por el cuello.\\\" Ya sentía que se erizaban mis cabellos a causa del temor, y miraba hacia atrás atentamente, por lo que dije:\"},{\"heading\":false,\"text\":\"--Maestro, si no nos ocultas a los dos prontamente, temo a los demonios que vienen detrás de nosotros; y tan así me lo imagino, que ya me parece que los oigo.\"},{\"heading\":false,\"text\":\"[28] Mo e issa, voces que significan ahora en lombardo. Mo, del latín modo, que es ahora; issa, elipsis del latín hac, ipsa hora, es también ahora.\"},{\"heading\":false,\"text\":\"A lo que él contestó:\"},{\"heading\":false,\"text\":\"--Si yo fuera un espejo, no verías en mí tu imagen tan pronto como veo en tu interior. En este momento se cruzaban tus pensamientos con los míos bajo la misma faz y aspecto, de suerte que he deducido de ambos un solo consejo. Si es cierto que la cuesta que hay a nuestra derecha está tan inclinada, que nos permita bajar a la sexta fosa, huiremos de la caza que imaginamos.\"},{\"heading\":false,\"text\":\"Apenas había concluído de decirme su parecer, cuando vi venir a los demonios con las alas extendidas y muy cerca de nosotros, queriendo cogernos. Mi Guía me agarró súbitamente, como una madre que, despertada por el ruido y viendo brillar las llamas cerca de ella, coge a su hijo y huye, y teniendo más cuidado de él que de sí misma, no se detiene ni aun a ponerse una camisa. Desde lo alto de la calzada, se deslizó de espaldas por la pendiente roca, uno de cuyos lados divide la quinta de la sexta fosa. Jamás corrió tan rápida el agua por la canal de un molino, cuando más se acerca a las paletas de la rueda, como descendió por aquel declive mi Maestro, llevándome sobre su pecho, cual si fuese hijo suyo y no su compañero. Apenas tocaron sus pies al suelo del profundo abismo, cuando los demonios aparecieron en la roca sobre nuestras cabezas: pero ya no nos inspiraban temor; porque la alta Providencia que los había designado para ministros de la quinta fosa, les quitó la facultad de separarse de allí. Abajo encontramos unas gentes pintadas, que giraban en torno con bastante lentitud, llorosas y con los semblantes fatigados y abatidos. Llevaban capas con capuchas echadas sobre los ojos, por el estilo de las que llevan los monjes de Colonia.[29] Aquellas capas eran doradas por de fuera, de modo que deslumbraban; pero por dentro eran todas de plomo, y tan pesadas, que las de Federico a su lado parecían de paja.[30] ¡Oh manto fatigoso por toda la eternidad! Nos volvimos aún hacia la izquierda, y anduvimos con aquellas almas, escuchando sus tristes lamentos. Pero las sombras, rendidas por el peso, caminaban tan despacio, que a cada paso que dábamos cambiábamos de compañero. Yo dije a mi Guía:\"},{\"heading\":false,\"text\":\"--Procura encontrar a alguno que sea conocido por su nombre o por sus hechos; y mira al efecto en derredor tuyo mientras andas.\"},{\"heading\":false,\"text\":\"[29] Cuéntase que hubo en Colonia un abad tan ambicioso e insolente, que pidió permiso al Papa para que sus monjes pudieran usar capas de escarlata, cintos, espuelas y estribos de plata sobredorada. Esta petición desagradó tanto al Pontífice, que dispuso que en adelante el abad y sus monjes usaran capas negras y mal hechas, y cintos y estribos de madera.\"},{\"heading\":false,\"text\":\"[30] El emperador Federico II encerraba a los culpables de lesa majestad en capas de plomo, y luego los arrojaba al fuego.\"},{\"heading\":false,\"text\":\"Y uno de ellos, que entendió el idioma toscano, exclamó detrás de nosotros:\"},{\"heading\":false,\"text\":\"Detened vuestros pasos, vosotros que tanto corréis a través del aire sombrío: quizá podrás obtener de mí lo que solicitas.\"},{\"heading\":false,\"text\":\"En seguida mi Guía se volvió y me dijo:\"},{\"heading\":false,\"text\":\"--Espera, y modera tu paso hasta igualar al suyo.\"},{\"heading\":false,\"text\":\"Me detuve, y vi dos de aquéllos, que en sus miradas demostraban gran deseo de estar conmigo; pero su carga y lo estrecho del camino les hacían tardar. Cuando se me hubieron reunido, me miraron con torvos ojos y sin hablarme: después se volvieron uno a otros diciéndose: \\\"Ese parece vivo, a juzgar por el movimiento de su garganta; pero si están muertos, ¿por qué privilegio no llevan nuestra pesada capa?\\\" Después me dijeron:\"},{\"heading\":false,\"text\":\"--¡Oh toscano, que has venido a la mansión de los tristes hipócritas!, dígnate decirnos quién eres.\"},{\"heading\":false,\"text\":\"Les contesté:\"},{\"heading\":false,\"text\":\"--Nací y crecí junto a la orilla del hermoso Arno, en la gran ciudad, y conservo el cuerpo que he tenido siempre. Pero vosotros, a quienes, según veo, cae tan doloroso llanto gota a gota por las mejillas, ¿quiénes sois, y qué pena padecéis que tanto se hace ver?\"},{\"heading\":false,\"text\":\"Uno de ellos me respondió:\"},{\"heading\":false,\"text\":\"--¡Ay de mí! Estas doradas capas son de plomo, y tan gruesas, que su peso nos hace gemir como cargadas balanzas. Fuimos hermanos Gozosos[31] y boloñeses. Yo me llamé Catalano y éste Loderingo. Tu ciudad nos nombró magistrados, como suele elegirse a un hombre neutral para conservar la paz; y la conservamos tan bien como puede verse aún cerca del Gardingo.\"},{\"heading\":false,\"text\":\"[31] Hermanos de una orden de caballería instituída para combatir contra los infieles y los que violaran la justicia. Se les llamó Gaudenti (gozosos) por la vida licenciosa que llevaron.\"},{\"heading\":false,\"text\":\"Yo repuse: \\\"¡Oh hermanos! Vuestros males...\\\" Pero no pude continuar; porque vi en el suelo a uno crucificado en tres palos. En cuanto me vió, se retorció, haciendo agitar su barba con la fuerza de los suspiros; y el hermano Catalano, que lo advirtió, me dijo:\"},{\"heading\":false,\"text\":\"--Ese que estás mirando crucificado aconsejó a los fariseos que era necesario hacer sufrir a un hombre el martirio por el pueblo. Está atravesado y desnudo sobre el camino, como ves; y es preciso que sienta lo que pesa cada uno de los que pasan. Su suegro está condenado a igual suplicio en esta fosa, así como los demás del Consejo que fué para los judíos origen de tantas desgracias.\"},{\"heading\":false,\"text\":\"Entonces vi a Virgilio que contemplaba con asombro a aquel que estaba tan vilmente crucificado en el eterno destierro. Luego se dirigió al fraile en estos términos:\"},{\"heading\":false,\"text\":\"--¿Queríais decirnos si hacia la derecha hay alguna abertura por donde podamos salir los dos, sin obligar a los ángeles negros a que nos saquen de este abismo?\"},{\"heading\":false,\"text\":\"Aquel respondió:\"},{\"heading\":false,\"text\":\"--Más cerca de aquí de lo que esperas, se levanta una peña que parte del gran círculo y atraviesa todas las terribles fosas; pero está cortada en ésta y no continúa sobre ella. Podréis subir por las ruinas que existen en el declive de su falda y cubren el fondo.\"},{\"heading\":false,\"text\":\"Mi Guía permaneció un momento con la cabeza inclinada, y después dijo:\"},{\"heading\":false,\"text\":\"--¡Cómo nos ha engañado aquel que ensarta con su garfio a los pecadores!\"},{\"heading\":false,\"text\":\"Y el fraile repuso:\"},{\"heading\":false,\"text\":\"--He oído referir en Bolonia los numerosos vicios del demonio, entre los cuales no era el menor el de ser falso y padre de la mentira.\"},{\"heading\":false,\"text\":\"Entonces mi Guía se alejó precipitadamente con el rostro inmutado por la cólera; y en consecuencia, me alejé también de aquellas almas que soportaban tanto peso, y seguí las huellas de los pies queridos.\"}]},{\"title\":\"Infierno — canto vigesimocuarto\",\"blocks\":[{\"heading\":false,\"text\":\"En la época del año nuevo en que templa el sol su cabellera bajo el Acuario, y en que ya las noches van igualándose con los días; cuando la escarcha imita en la tierra, aunque por poco tiempo, el color de su blanca hermana, el campesino que carece de forraje, se levanta, mira, y al ver blanco el campo se golpea el muslo, vuelve a su casa, y se lamenta continuamente como el desgraciado que no sabe qué hacer; pero torna luego a mirar, y recobra la esperanza, viendo que la tierra ha cambiado de aspecto en pocas horas, y entonces coge su cayado y sale a apacentar sus ovejas: así mi Maestro me llenó de inquietud cuando vi tan turbado su rostro, y así también aplicó pronto remedio a mi mal; porque al llegar al derruído puente, se volvió hacia mí con aquel amable aspecto que tenía cuando le vi al pie del monte. Después de haber pensado la determinación que había de tomar, contemplando antes con cuidado las ruinas, abrió sus brazos, cogióme por detrás, y como aquel que trabaja, pensando siempre en la labor que emprenderá en seguida, del mismo modo, elevándome sobre la cima de una roca, contemplaba otra diciendo:\"},{\"heading\":false,\"text\":\"--Agárrate bien a ésa, pero tantea primero si tal cual es podrá sostenerte.\"},{\"heading\":false,\"text\":\"Aquel no era un camino a propósito para los que iban con capa; pues apenas podíamos, Virgilio tan ágil, y yo sostenido por él, trepar de piedra en piedra. Y a no ser porque en aquel recinto era más corto el camino que en otro alguno, no sé lo que a él le habría sucedido, pero a mí me hubiera vencido el cansancio. Mas como Malebolge va siempre en declive hasta la boca del profundísimo pozo, cada fosa que se recorre presenta un margen que se eleva y otro que desciende. Llegamos por fin al extremo en que se destaca la última piedra. Cuando estuve sobre ella, de tal modo me faltaba el aliento, que no podía más; así es que me senté en cuanto nos detuvimos.\"},{\"heading\":false,\"text\":\"--Ahora es preciso que sacudas tu pereza--me dijo el Maestro--; que no se alcanza la fama reclinado en blanda pluma, ni al abrigo de colchas: y el que sin gloria consume su vida, deja en pos de sí el mismo vestigio que el humo en el aire o la espuma en el agua. Ea, pues, levántate; domina la fatiga con el alma, que vence todos los obstáculos, mientras no se envilece con la pesadez del cuerpo. Tenemos que subir todavía una escala mucho más larga; pues no basta haber atravesado por entre los espíritus infernales. Si me entiendes, deben reanimarte mis palabras.\"},{\"heading\":false,\"text\":\"Levantéme entonces, demostrando más resolución de la que verdaderamente sentía en mi interior, y dije:\"},{\"heading\":false,\"text\":\"--Vamos, ya me siento fuerte y atrevido.\"},{\"heading\":false,\"text\":\"Echamos a andar por el escollo, que era áspero, estrecho y escabroso, y más pendiente que el anterior. Iba hablando para disimular mi flaqueza, cuando oí una voz que salía de la otra fosa, articulando palabras ininteligibles. No sé lo que dijo, a pesar de encontrarme en la cima del arco que por allí pasa; mas el que hablaba parecía conmovido por la ira. Yo me había inclinado; pero los ojos de un vivo no podían distinguir el fondo a través de aquella obscuridad; por lo cual dije:\"},{\"heading\":false,\"text\":\"--Maestro, haz por llegar al otro recinto, y descendamos este muro, porque desde aquí oigo y no comprendo nada; miro hacia abajo y nada veo.\"},{\"heading\":false,\"text\":\"--Te responderé--me dijo--haciendo lo que deseas; que las peticiones justas deben satisfacerse en silencio.\"},{\"heading\":false,\"text\":\"Bajamos por el puente desde lo alto hasta donde se une con el octavo margen; y entonces descubrí la fosa, y vi una espantosa masa de serpientes, de tan diferentes especies, que su recuerdo me hiela todavía la sangre. Deje la Libia de envanecerse con sus arenas; que si produce quelidras, yáculos y faras, cencros y anfisbenas, ni en ella, ni en toda la Etiopía con el país que está sobre el mar Rojo, existieron jamás tantas ni tan nocivas pestilencias como en este lugar. A través de aquella espantosa y cruel multitud de reptiles corrían gentes desnudas y aterrorizadas, sin esperanza de encontrar refugio ni heliotropo.[32] Tenían las manos atadas a la espalda con sierpes, las cuales, formando nudos por encima, les hincaban la cola y la cabeza en los riñones. Y he aquí que uno de aquellos desgraciados, que estaba cerca de nosotros, fué mordido por una serpiente en el punto en que el cuello se une a los hombros; y en el breve tiempo que se necesita para escribir una O y una I, se incendió, ardió y cayó reducido a cenizas. Pero apenas quedó consumido en el suelo, reuniéronse aquéllas por sí mismas, y súbitamente se rehizo aquel espíritu como estaba antes. Así dicen los grandes sabios que muere el Fénix, y renace cuando está cercano a su quinto siglo: no se alimenta de hierba ni de trigo durante su vida, sino de amomo y lágrimas de incienso, y su último nido está formado con nardo y mirra. Y como aquel que cae y no sabe cómo, a impulsos del demonio que lo arroja en el suelo o de algún accidente producido por su temperamento enfermizo, cuando se levanta, se queda asombrado de la cruel angustia que ha sufrido y suspira al mirar en torno suyo, así se levantó el pecador ante nosotros. ¡Oh, cuán severa es la justicia de Dios, que hace estallar su cólera por medio de tales golpes! Mi Guía le preguntó después quién era, y él le contestó:\"},{\"heading\":false,\"text\":\"--Yo caí hace poco tiempo desde Toscana en este horrible abismo. La vida salvaje me agradó más que la humana; fuí lo mismo que un mulo: soy Vanni Fucci, el bestia, y Pistoya fué mi digno cubil.\"},{\"heading\":false,\"text\":\"[32] Agata de color verde obscuro con manchas rojizas, a la que se atribuían virtudes milagrosas contra toda clase de veneno y especialmente contra las mordeduras de las serpientes, y que tenía además la de hacer invisible al que la llevaba.\"},{\"heading\":false,\"text\":\"Entonces dije a mi Guía:\"},{\"heading\":false,\"text\":\"--Dile que no huya, y pregúntale qué delito le ha precipitado aquí; pues yo le conocí ya hombre colérico y sanguinario.\"},{\"heading\":false,\"text\":\"El pecador, que me oyó, no se ocultó, sino que dirigió hacia mí atentamente su mirada, y se cubrió el rostro de triste vergüenza. Después dijo:\"},{\"heading\":false,\"text\":\"--Siento más que me hayas encontrado en la miseria en que me ves, de lo que sentí verme privado de la vida; pero no puedo negarme a satisfacer tus preguntas. Estoy sumido aquí, porque robé en la sacristía los hermosos ornamentos, de cuyo delito fué otro acusado falsamente. Mas para que no te goces en mi desgracia, si acaso llegas a salir de estos lugares sombríos, abre tus oídos a mi anuncio, y escucha: primeramente, Pistoya quedará despoblada de Negros; después Florencia renovará sus habitantes y su forma de gobierno; Marte hará salir del valle de Magra un vapor, que envuelto en sombrías nieblas y en tempestad impetuosa y terrible, se desencadenará sobre el campo Piceno; y allí, desgarrándose de repente la nube, aniquilará todos los Blancos. Te he dicho esto para que te cause dolor.\"}]},{\"title\":\"Infierno — canto vigesimoquinto\",\"blocks\":[{\"heading\":false,\"text\":\"Al terminar estas palabras, el ladrón alzó ambas manos haciendo un gesto indecente y exclamando: \\\"Toma, Dios, esto es para tí.\\\" Desde entonces fuí amigo de las serpientes; porque una de ellas se le enroscó en el cuello como diciendo: \\\"No quiero que hables más:\\\" y otra se agarró a sus brazos, sujetándolos de tal modo, que no le era posible al condenado hacer ningún movimiento. ¡Ah, Pistoya, Pistoya! ¿Cómo no decides reducirte tú misma a cenizas, y dejar de existir, pues que tus hijos son peores que sus antepasados? En todos los círculos del obscuro Infierno no he visto espíritu tan soberbio ante Dios, a no ser aquel que cayó desde los muros de Tebas. El ladrón huyó sin decir una palabra más. Entonces vi un Centauro lleno de ira, que acudía gritando: \\\"¿Dónde está, dónde está el soberbio?\\\" No creo que contengan las Marismas tanto reptil como llevaba el Centauro sobre su grupa hasta el sitio en que empezaba la forma humana: sobre sus espaldas, detrás de la nuca, descansaba un dragón con las alas abiertas, el cual abrasaba cuanto salía a su encuentro. Mi Maestro dijo:\"},{\"heading\":false,\"text\":\"--Ese monstruo es Caco, el que al pie de las rocas del monte Aventino formó más de una vez un lago de sangre. No va por el mismo camino que sus hermanos, porque robó fraudulentamente el gran rebaño que pacía en las inmediaciones del sitio que había escogido por vivienda: pero sus inicuos hechos acabaron por fin bajo la clava de Hércules, que si le dió cien golpes con ella, aquél no llegó a sentir el décimo.\"},{\"heading\":false,\"text\":\"Mientras así hablaba Virgilio, Caco desapareció, al mismo tiempo que se acercaban tres espíritus por debajo del margen donde estábamos, lo cual no advertimos ni mi Guía ni yo, hasta que les oímos gritar: \\\"¿Quiénes sois?\\\" Cesó entonces nuestra conversación, y nos fijamos solamente en ellos. Yo no les conocía; pero sucedió, como suele acontecer algunas veces, que el uno tuvo necesidad de llamar al otro, diciéndole: \\\"Cianfa, ¿dónde te has metido?\\\" Y yo, a fin de que estuviese atento mi Guía, me puse el dedo desde la nariz a la barba. Ahora, lector, si se te hace difícil creer lo que te voy a decir, no será extraño, porque yo que lo vi, apenas lo creo. Mientras estaba contemplando a aquellos espíritus, se lanzó una serpiente con seis patas sobre uno de ellos, agarrándosele enteramente. Con las patas de enmedio le oprimió el vientre; con las de delante le sujetó los brazos, y después le mordió en ambas mejillas. Extendiendo en seguida las patas de detrás sobre sus muslos, le pasó la cola por entre los dos, y se la mantuvo apretada contra los riñones. Nunca se agarró tan fuertemente la hiedra al árbol, como la horrible fiera adaptó sus miembros a los del culpable: después una y otro se confundieron, como si fuesen de blanda cera, y mezclaron tan bien sus colores, que ninguno de ambos parecía ya lo que antes había sido. Así con el ardor del fuego se extiende sobre el papel un color obscuro, que no es negro, y sin embargo deja de ser blanco. Los otros dos condenados le miraban, exclamando cada cual: \\\"¡Ay, Angel,[33] cómo cambias! No eres ya uno ni dos.\\\" Las dos cabezas se habían convertido en una, y aparecían dos figuras mezcladas en una sola faz, quedando en ella confundidas entrambas. De los cuatro brazos se hicieron dos: los muslos y las piernas, el vientre y el tronco se convirtieron en miembros nunca vistos. Quedó borrado todo su primitivo aspecto: aquella imagen transformada parecía dos y ninguna de las anteriores; y en tal estado se alejaba a pasos lentos.\"},{\"heading\":false,\"text\":\"[33] Agnolo Bruneleschi, florentino.\"},{\"heading\":false,\"text\":\"Como el lagarto, que bajo el ardor de los días caniculares, cuando cambia de maleza, parece un rayo al atravesar el camino, tal parecía, dirigiéndose hacia el vientre de los otros dos espíritus, una pequeña serpiente irritada, lívida y negra como grano de pimienta. Picó a uno de ellos en aquella parte del cuerpo por donde nos alimentamos antes de nacer, y después cayó a sus pies quedando tendida. El herido la miró sin decir nada; y permaneció inmóvil, en pie y bostezando, como si le hubiera sorprendido el sueño o la fiebre. El y la serpiente se miraban, y el uno por la herida y la otra por la boca, lanzaban un denso humo que llegaba a confundirse. Calle Lucano al referir las miserias de Sabello y de Nasidio, y escuche atentamente lo que describo aquí: calle Ovidio al ocuparse de Cadmo y Aretusa; que si, en su poema, convirtió a aquél en serpiente y a éste en fuente, no le envidio. Ovidio no transformó jamás dos naturalezas frente a frente, de tal modo que sus formas cambiaran también de materia. El hombre y la serpiente se correspondieron de tal suerte, que cuando ésta abrió su cola en forma de horquilla, el herido juntó sus dos pies. Las piernas y los muslos de éste se estrecharon tanto, que en poco tiempo no quedaron vestigios de su natural separación. La cola hendida de la serpiente tomaba la figura que desaparecía en el hombre, y su piel se hacía blanda al paso que dura la de aquél. Vi entrar los brazos del condenado en los sobacos; y las dos patas de la fiera, que eran cortas, se alargaban tanto cuanto aquéllos se encogían. Las patas de detrás de aquélla, retorciéndose, formaban el miembro que el hombre oculta, y el del miserable dividióse en dos patas. Mientras que el humo daba el color de la serpiente al hombre y viceversa, y hacía salir en aquélla el pelo que quitaba a éste, el uno, es decir, la fiera transformada en hombre, se levantó, y cayó el otro; pero sin dejar de lanzarse miradas feroces, ante las cuales cada uno de ellos cambiaba de rostro. El que estaba en pie lo encogió hacia las sienes, y de la carne excedente se le formaron las orejas en sus lisos carrillos. La parte del hocico de la serpiente que no se replegó en la cabeza quedó fuera formando la nariz del rostro humano, y abultó al propio tiempo convenientemente los labios. El que estaba en el suelo extendió su boca hacia delante, e hizo entrar sus orejas en la cabeza, como el caracol hace con sus cuernos; y la lengua, que estaba antes unida y dispuesta a hablar, se hendió, al paso que se unía la lengua hendida del reptil, dejando de lanzar humo. El alma que se había convertido en serpiente huyó silbando por la fosa; y el otro, hablando detrás de ella, le escupía. Volvióle después sus recién formadas espaldas, y dijo al otro condenado: \\\"Quiero que Buoso se arrastre por este camino como yo lo he hecho.\\\" De tal suerte vi yo, en la séptima fosa, cambiarse y metamorfosearse dos naturalezas; y si mi lenguaje no es florido, sírvame de excusa la novedad del caso.\"},{\"heading\":false,\"text\":\"Aunque mis ojos estuviesen turbados y mi espíritu aturdido, no pudieron huír las otras dos sombras tan ocultamente, que yo no conociese a Puccio Sciancato, el único de los tres espíritus de los llegados anteriormente que no había cambiado de forma: el otro era aquel que tú lloras, ¡oh Gaville![34]\"},{\"heading\":false,\"text\":\"[34] Para mayor claridad, nótese bien que Dante ve primero tres espíritus: Agnolo Brunelleschi, Buoso Donati y Puccio Sciancato. Luego viene Cianfa en forma de serpiente con seis patas, se arroja sobre Brunelleschi, y los dos se convierten en un solo monstruo, que se va con pasos lentos. Llega después, en forma de serpiente lívida y negra, Guercio Cavalcante: pica a Buoso, le transforma en serpiente y él se vuelve hombre: Buoso huye silbando. Quedan solos en escena Puccio Sciancato, que no ha sufrido transformación, y \\\"aquel a quien llora Gaville;\\\" es decir, Guercio Cavalcante.\"}]},{\"title\":\"Infierno — canto vigesimosexto\",\"blocks\":[{\"heading\":false,\"text\":\"Alégrate, Florencia, pues eres tan grande, que tu nombre vuela por mar y tierra, y es famoso en todo el infierno. Entre los ladrones he encontrado cinco de tus nobles ciudadanos; lo cual me avergüenza, y a tí no te honra mucho. Pero, si es verdad lo que se sueña cerca del amanecer, dentro de poco tiempo conocerás lo que contra ti desean, no ya otros pueblos, sino Prato: y si este mal se hubiese ya cumplido, no sería prematuro. ¡Así viniese hoy lo que ha de suceder, pues tanto más me contristará, cuanto más viejo me vuelva!\"},{\"heading\":false,\"text\":\"Partimos; y por los mismos escalones de las rocas que nos habían servido para bajar, subió mi Guía, tirando de mí. Prosiguiendo la ruta solitaria a través de los picos y rocas del escollo, no era posible mover un pie sin el auxilio de la mano. Entonces me afligí, como me aflijo ahora, cuando pienso en lo que vi; y refreno mi espíritu más de lo que acostumbro, para que no aventure tanto que deje de guiarlo la virtud; porque, si mi buena estrella u otra influencia mejor me ha dado algún ingenio, no quiero yo mismo envidiármelo. Así como en la estación en que aquel que ilumina al mundo nos oculta menos su faz, el campesino que reposa en la colina a la hora en que el mosquito reemplaza a la mosca, ve por el valle las luciérnagas que corren por el sitio donde vendimia y ara, así también vi resplandecer infinitas llamas en la octava fosa, en cuanto estuve en el punto desde donde se distinguía su fondo. Y como aquel a quien los osos ayudaron en su venganza[35] vió partir el carro de Elías, cuando los caballos subían erguidos al cielo, de tal modo que no pudiendo sus ojos seguirle, sólo distinguían una ligera llama elevándose como débil nubecilla, así también noté que se agitaban aquéllas en la abertura de la fosa, encerrando cada una un pecador, pero sin manifestar lo que ocultaban. Yo estaba sobre el puente, tan absorto en la contemplación de aquel espectáculo, que, a no haberme agarrado a un trozo de roca, hubiera caído sin ser empujado. Mi Guía, que me vió tan atento, me dijo:\"},{\"heading\":false,\"text\":\"--Dentro del fuego están los espíritus, cada uno revestido de la llama que le abrasa.\"},{\"heading\":false,\"text\":\"[35] Colocados en una misma pira los cadáveres de los hermanos Eteocles y Polinyces, que se habían dado muerte el uno al otro, la llama descubría, bifurcándose, que se odiaban aun después de muertos.\"},{\"heading\":false,\"text\":\"--¡Oh, Maestro!--respondí;--tus palabras han hecho que me cerciore de lo que veo; pero ya lo había pensado así y quería decírtelo. Mas dime: ¿quién está en aquella llama que se divide en su parte superior, y parece salir de la pira donde fueron puestos Eteocles y su hermano?\"},{\"heading\":false,\"text\":\"Me contestó:\"},{\"heading\":false,\"text\":\"--Allí dentro están torturados Ulises y Diomedes: juntos sufren aquí un mismo castigo, como juntos se entregaron a la ira. En esa llama se llora también el engaño del caballo de madera, que fué la puerta por donde salió la noble estirpe de los romanos. Llórase también el artificio por el que Deidamia, aun después de muerta, se lamenta de Aquiles, y se sufre además el castigo por el robo del Paladión.\"},{\"heading\":false,\"text\":\"--Si es que pueden hablar en medio de las llamas--dije yo--, Maestro, te pido y te suplico, y así mi súplica valga por mil, que me permitas esperar que esa llama dividida llegue hasta aquí: mira cómo, arrastrado por mi deseo, me abalanzo hacia ella.\"},{\"heading\":false,\"text\":\"A lo que me contestó:\"},{\"heading\":false,\"text\":\"Tu súplica es digna de alabanza, y yo la acojo; pero haz que tu lengua se reprima, y déjame a mí hablar; pues comprendo lo que quieres, y quizás ellos, siendo griegos, se desdeñarían de contestarte.\"},{\"heading\":false,\"text\":\"Cuando la llama estuvo cerca de nosotros, y mi Guía juzgó el lugar y el momento favorables, le oí expresarse en estos términos:\"},{\"heading\":false,\"text\":\"--¡Oh vosotros, que sois dos en un mismo fuego! Si he merecido vuestra gracia durante mi vida, si he merecido de vosotros poco o mucho, cuando escribí mi gran poema en el mundo, no os alejéis; antes bien dígame uno de vosotros dónde fué a morir, llevado de su valor.\"},{\"heading\":false,\"text\":\"La punta más elevada de la antigua llama empezó a oscilar murmurando como la que agita el viento; después, dirigiendo a uno y otro lado su extremidad, empezó a lanzar algunos sonidos, como si fuera una lengua que hablara, y dijo:\"},{\"heading\":false,\"text\":\"--Cuando me separé de Circe, que me tuvo oculto más de un año en Gaeta, antes de que Eneas le diera este nombre, ni las dulzuras paternales, ni la piedad debida a un padre anciano, ni el amor mutuo que debía hacer dichosa a Penélope, pudieron vencer el ardiente deseo que yo tuve de conocer el mundo, los vicios y las virtudes de los humanos, sino que me lancé por el abierto mar sólo con un navío, y con los pocos compañeros que nunca me abandonaron. Vi entrambas costas, por un lado hasta España, por otro hasta Marruecos, y la isla de los Sardos y las demás que baña en torno aquel mar. Mis compañeros y yo nos habíamos vuelto viejos y pesados cuando llegamos a la estrecha garganta donde plantó Hércules las dos columnas para que ningún hombre pasase más adelante. Dejé a Sevilla a mi derecha, como había dejado ya a Ceuta a mi izquierda. \\\"¡Oh hermanos, dije, que habéis llegado al Occidente a través de cien mil peligros!, ya que tan poco os resta de vida, no os neguéis a conocer el mundo sin habitantes, que se encuentra siguiendo al Sol. Pensad en vuestro origen; vosotros no habéis nacido para vivir como brutos, sino para alcanzar la virtud y la ciencia.\\\" Con esta corta arenga infundí en mis compañeros tal deseo de continuar el viaje, que apenas los hubiera podido detener después. Y volviendo la popa hacia el Oriente, de nuestros remos hicimos alas para seguir tan desatentado viaje, inclinándonos siempre hacia la izquierda. La noche veía ya brillar todas las estrellas del otro polo, y estaba el nuestro tan bajo que apenas parecía salir fuera de la superficie de las aguas. Cinco veces se había encendido y otras tantas apagado la luz de la luna desde que entramos en aquel gran mar, cuando apareció una montaña obscurecida por la distancia, la cual me pareció la más alta de cuantas había visto hasta entonces. Nos causó alegría, pero nuestro gozo se trocó bien pronto en llanto; pues de aquella tierra se levantó un torbellino que chocó contra la proa de nuestro buque: tres veces lo hizo girar juntamente con las encrespadas ondas, y a la cuarta levantó la popa y sumergió la proa como plugo al Otro, hasta que el mar volvió a unirse sobre nosotros.\"}]},{\"title\":\"Infierno — canto vigesimoseptimo\",\"blocks\":[{\"heading\":false,\"text\":\"Habíase quedado derecha e inmóvil la llama para no decir nada más, y ya se iba alejando de nosotros, con permiso del dulce poeta, cuando otra que seguía detrás nos hizo volver la vista hacia su punta, a causa del confuso rumor que salía de ella. Como el toro de Sicilia que, lanzando por primer mugido el llanto del que lo había trabajado con su lima (lo cual fué justo), bramaba con las voces de los torturados en él de tal suerte, que a pesar de estar construído de bronce, parecía realmente traspasado de dolor, así también las palabras lastimeras del espíritu contenido en la llama, no encontrando en toda la extensión de ella ninguna abertura por donde salir, se convertían en el lenguaje del fuego; pero cuando consiguieron llegar a su punta, comunicándole a ésta el movimiento que la lengua les había dado al pasar, oímos decir:\"},{\"heading\":false,\"text\":\"--¡Oh tú, a quien me dirijo, y que hace poco hablabas en lombardo, diciendo: \\\"Véte ya, no te detengo más!\\\" Aun cuando yo haya llegado tarde, no te pese permanecer hablando conmigo; pues a mí no me pesa, no obstante que estoy ardiendo.[36] Si acabas de caer en este mundo lóbrego desde la dulce tierra latina, donde he cometido todas mis faltas, dime si los romañolos están en paz o en guerra; pues fuí de las montañas que se elevan entre Urbino y el yugo de que el Tíber se desata.\"},{\"heading\":false,\"text\":\"[36] Este espíritu es el conde Guido de Montefeltro.\"},{\"heading\":false,\"text\":\"Yo escuchaba aún atento e inclinado, cuando mi Guía me tocó, diciendo:\"},{\"heading\":false,\"text\":\"--Habla tú, ese es latino.\"},{\"heading\":false,\"text\":\"Y yo, que tenía la respuesta preparada, empecé a hablarle así sin tardanza:\"},{\"heading\":false,\"text\":\"--¡Oh alma, que te escondes ahí debajo! Tu Romanía no está ni estuvo nunca sin guerra en el corazón de sus tiranos; pero al venir no he dejado guerra manifiesta: Ravena está como hace muchos años: el águila de Polenta anida allí, y cubre aún a Cervia con sus alas. La tierra que sostuvo tan larga prueba, y contiene sangrientos montones de cadáveres franceses, se encuentra en poder de las garras verdes; y el mastín viejo y el joven de Verrucchio, que tanto daño hicieron a Montagna, siguen ensangrentando sus dientes donde acostumbran. La ciudad del Lamone y la del Santerno están dirigidas por el leoncillo de blanco cubil, que del verano al invierno cambia de partido; y aquella que está bañada por el Savio, vive entre la tiranía y la libertad, así como se asienta entre la llanura y la montaña. Ahora te ruego que me digas quién eres: no seas más duro de lo que lo han sido otros; así pueda tu nombre durar eternamente en el mundo.\"},{\"heading\":false,\"text\":\"Cuando el fuego hubo producido su acostumbrado rumor, movió de una parte a otra su aguda punta, y después habló así:\"},{\"heading\":false,\"text\":\"Si yo creyera que dirijo mi respuesta a una persona que debe volver al mundo, esta llama dejaría de agitarse; pero como ninguno pudo salir jamás de esta profundidad, si es cierto lo que he oído, te responderé sin temor a la infamia. Yo fuí hombre de guerra y luego franciscano, creyendo que con este hábito expiaría mis faltas; y mi creencia hubiera tenido ciertamente efecto, si el gran Sacerdote, a quien deseo todo mal, no me hubiese hecho incurrir en mis primeras faltas. Quiero que tú sepas cómo y por qué. Mientras conservé la forma de carne y hueso que mi madre me dió, mis acciones no fueron de león, sino de zorra. Yo conocí toda clase de astucias, todas las asechanzas, y las practiqué tan bien, que su fama resonó hasta en el último confín del mundo. Cuando me ví cercano a la edad en que cada cual debería cargar las velas y recoger las cuerdas, lo que antes me agradaba me disgustó entonces; y arrepentido, confesé mis culpas, retirándome al claustro. Entonces ¡ay, infeliz de mí! pude haberme salvado: pero el príncipe de los nuevos fariseos estaba en guerra cerca de Letrán (y no con los sarracenos ni con los judíos, pues todos sus enemigos eran cristianos, y ninguno de ellos había ido a conquistar a Acre, ni a comerciar en la tierra del Sultán): no tuvo en cuenta su dignidad suprema ni las sagradas órdenes de que estaba investido, ni vió en mí aquel cordón que solía enflaquecer a los que lo llevaban; sino que, así como Constantino llamó a Silvestre en el monte Soracto, para que le curase la lepra, así también me llamó aquél para que le curara su orgullosa fiebre: pidióme consejo, y yo me callé, porque sus palabras me parecieron las de un hombre ebrio. Después añadió: \\\"No abrigue tu corazón temor alguno: te absuelvo de antemano; pero me has de decir cómo podré echar por tierra los muros de Preneste. Yo puedo abrir y cerrar el cielo, como sabes; porque son dos las llaves a que no tuvo mucho apego mi antecesor.\\\" Estos graves argumentos me impresionaron, y pensando que sería peor callar que hablar, dije: \\\"Padre, puesto que tú me lavas del pecado en que voy a incurrir, para triunfar en tu alto solio, debes prometer mucho y cumplir poco de lo que prometas.\\\" Cuando ocurrió mi muerte, fué Francisco a buscarme; pero uno de los negros querubines le dijo: \\\"No puedes llevártelo; no me prives de lo que es mío: éste debe bajar a lo profundo entre mis condenados, por haber aconsejado el fraude, desde cuya falta le tengo cogido por los cabellos. No es posible absolver al que no se arrepiente, como tampoco es posible arrepentirse y querer el pecado al mismo tiempo, pues la contradicción no lo consiente.\\\" ¡Ay de mí, desdichado! ¡Cómo me aterré cuando me agarró, diciendo: \\\"¡Acaso no creerías que fuera yo tan lógico!\\\" Me condujo ante Minos, el cual se ciñó ocho veces la cola en derredor de su duro cuerpo, y mordiéndosela con gran rabia, dijo: \\\"Ese debe estar entre los culpables que esconde el fuego.\\\" He aquí por qué estoy sepultado donde me ves, y por qué gimo al llevar este vestido.\"},{\"heading\":false,\"text\":\"Cuando hubo acabado de hablar, se alejó la plañidora llama, torciendo y agitando su aguda punta. Mi Guía y yo seguimos adelante, a través del escollo, hasta llegar al otro arco que cubre el foso donde se castiga a los que cargaron su conciencia introduciendo la discordia.\"}]},{\"title\":\"Infierno — canto vigesimoctavo\",\"blocks\":[{\"heading\":false,\"text\":\"¿Quién podría jamás, ni aún con palabras sin medida, por más que lo intentase muchas veces, describir toda la sangre y las heridas que vi entonces? No existe ciertamente lengua alguna que pueda expresar, ni entendimiento que retenga, lo que apenas cabe en la imaginación. Si pudiera reunirse toda la gente que derramó su sangre en la infortunada tierra de la Pulla, cuando combatieron los romanos durante aquella prolongada guerra en que se recogió tan gran botín de anillos, como refiere Tito Livio y no se equivoca, con la que sufrió tan rudos golpes por contrastar a Roberto Guiscardo, y con aquella cuyos huesos se recogen aún, tanto en Ceperano, donde cada habitante fué un traidor, como en Tagliacozzo, donde el viejo Allard venció sin armas, y fuera posible que todos los combatientes mencionados enseñaran sus miembros rotos y traspasados, ni aun así tendría una idea del aspecto horrible que presentaba la novena fosa. Una cuba que haya perdido las duelas del fondo no se vacía tanto como un espíritu que ví hendido desde la barba hasta la parte inferior del vientre; sus intestinos le colgaban por las piernas: se veía el corazón en movimiento y el triste saco donde se convierte en excremento todo cuanto se come. Mientras le estaba contemplando atentamente, me miró, y con las manos se abrió el pecho, diciendo:\"},{\"heading\":false,\"text\":\"--Mira cómo me desgarro: mira cuán estropeado está Mahoma. Allí va delante de mí llorando, con la cabeza abierta desde el cráneo hasta la barba, y todos los que aquí ves, vivieron; mas por haber diseminado el escándalo y el cisma en la tierra, están hendidos del mismo modo. En pos de nosotros viene un diablo que nos hiere cruelmente, dando tajos con su afilada espada a cuantos alcanza entre esta multitud de pecadores, luego que hemos dado una vuelta por esta lamentable fosa; porque nuestras heridas se cierran antes de volvernos a encontrar con aquel demonio. Pero tú, que estás husmeando desde lo alto del escollo, quizá para demorar tu marcha hacia el suplicio que te haya sido impuesto por tus culpas, ¿quién eres?\"},{\"heading\":false,\"text\":\"--Ni la muerte le alcanzó aún, ni le traen aquí sus culpas para que sea atormentado--contestó mi Maestro--, sino que ha venido para conocer todos los suplicios. Yo, que estoy muerto, debo guiarle por cada uno de los círculos del profundo Infierno, y esto es tan cierto como que te estoy hablando.\"},{\"heading\":false,\"text\":\"Al oír estas palabras, más de cien condenados se detuvieron en la fosa para contemplarme, haciéndoles olvidar la sorpresa su martirio.\"},{\"heading\":false,\"text\":\"--Pues bien, tú que tal vez dentro de poco volverás a ver el sol, di a fray Dolcino que, si no quiere reunirse conmigo aquí muy pronto, debe proveerse de víveres y no dejarse rodear por la nieve; pues sin el hambre y la nieve, difícil le será al novarés vencerle.\"},{\"heading\":false,\"text\":\"Mahoma me dijo estas palabras después de haber levantado un pie para alejarse; cuando cesó de hablar, lo fijó en el suelo y partió.\"},{\"heading\":false,\"text\":\"Otro, que tenía la garganta atravesada, la nariz cortada hasta las cejas, y una oreja solamente, se quedó mirándome asombrado con los demás espíritus, y abriendo antes que ellos su boca, exteriormente rodeada de sangre por todas partes, dijo:\"},{\"heading\":false,\"text\":\"--¡Oh, tú a quien no condena culpa alguna, y a quien ya vi allá arriba, en la tierra latina, si es que no me engaña una gran semejanza!, acuérdate de Pedro de Medicina, si logras ver de nuevo la hermosa llanura que declina desde Vercelli a Marcabó; y haz saber a los dos mejores de Fano, a messer Guido y Angiolello, que si la previsión no es aquí vana, serán arrojados fuera de su bajel, y ahogados cerca de la Católica por la traición de un tirano desleal. Desde la isla de Chipre a la de Mallorca no habrá visto jamás Neptuno una felonía tan grande, llevada a cabo por piratas, ni por corsarios griegos. Aquel traidor, que ve solamente con un ojo, y que gobierna el país que no quisiera haber visto uno que está aquí conmigo, les invitará a parlamentar con él, y después hará de modo que no necesiten conjurar con sus votos y oraciones el viento de Focara.\"},{\"heading\":false,\"text\":\"Yo le dije:\"},{\"heading\":false,\"text\":\"--Si quieres que lleve noticias tuyas allá arriba, muéstrame y declara quién es ése que deplora haber visto aquel país.\"},{\"heading\":false,\"text\":\"Entonces puso su mano sobre la mandíbula de uno de sus compañeros, y le abrió la boca exclamando:\"},{\"heading\":false,\"text\":\"--Héle aquí; pero no habla.\"},{\"heading\":false,\"text\":\"Era aquel que, desterrado de Roma, ahogó la duda en el corazón de César, afirmando que el que está preparado, se perjudica en aplazar la realización de una empresa. ¡Oh! ¡Cuán acorbardado me parecía con su lengua cortada en la garganta aquel Curión, que tan audaz fué para hablar!\"},{\"heading\":false,\"text\":\"Otro, que tenía las manos cortadas, levantando sus muñones al aire sombrío, de tal modo que se inundaba la cara de sangre, gritó:\"},{\"heading\":false,\"text\":\"--Acuérdate también de Mosca, que dijo, ¡desventurado!: \\\"Cosa hecha está concluída.\\\" Palabras que fueron el origen de las discordias civiles de los toscanos.\"},{\"heading\":false,\"text\":\"--¡Y de la muerte de tu raza!--exclamé yo.\"},{\"heading\":false,\"text\":\"Entonces él, acumulando dolor sobre dolor, se alejó como una persona triste y demente.\"},{\"heading\":false,\"text\":\"Continué examinando la banda infernal, y vi cosas que no me atrevería a referir sin otra prueba, si no fuese por la seguridad de mi conciencia; esa buena compañera, que confiada en su pureza, fortifica tanto el corazón del hombre: vi, en efecto, y aun me parece que lo estoy viendo, un cuerpo sin cabeza, andando como los demás que formaban aquella triste grey: asida por los cabellos, y pendiente a guisa de linterna, llevaba en una mano su cabeza cortada, la cual nos miraba exclamando: \\\"¡Ay de mí!\\\" Servíase de sí mismo como de una lámpara, y eran dos en uno y uno en dos: cómo puede ser esto, sólo lo sabe Aquél que nos gobierna. Cuando llegó al pie del puente, levantó en alto su brazo con la cabeza para acercarnos más sus palabras, que fueron éstas:\"},{\"heading\":false,\"text\":\"--Mira mi tormento cruel, tú que, aunque estás vivo, vas contemplando los muertos: ve si puede haber alguno tan grande como éste. Y para que puedas dar noticias mías, sabe que yo soy Bertrán de Born, aquel que dió tan malos consejos al rey joven. Yo armé al padre y al hijo uno contra otro: no hizo más Aquitofel con sus perversas instigaciones a David y Absalón. Por haber dividido a personas tan unidas, llevo ¡ay de mí! mi cabeza separada de su principio, que queda encerrado en este tronco: así se observa conmigo la pena del talión.\"}]},{\"title\":\"Infierno — canto vigesimonono\",\"blocks\":[{\"heading\":false,\"text\":\"El espectáculo de aquella multitud de precitos y de sus diversas heridas, de tal modo henchía de lágrimas mis ojos, que hubiera deseado detenerme para llorar. Pero Virgilio me dijo:\"},{\"heading\":false,\"text\":\"--¿Qué miras ahora? ¿Por qué tu vista se obstina en contemplar ahí abajo esas sombras tristes y mutiladas? Tú no has hecho eso en las otras fosas: si crees poder contar esas almas, piensa que la fosa tiene veintidós millas de circunferencia. La luna está ya debajo de nosotros: el tiempo que se nos ha concedido es muy corto, y aún nos queda por ver más de lo que has visto.\"},{\"heading\":false,\"text\":\"--Si hubieses considerado atentamente--le respondí--la causa que me obligaba a mirar, quizá hubieras permitido que me detuviera aquí un poco.\"},{\"heading\":false,\"text\":\"Mi Guía se alejaba ya, mientras yo iba tras de él contestándole y añadiendo:\"},{\"heading\":false,\"text\":\"--Dentro de aquella cueva donde tenía los ojos tan fijos, creo que había un espíritu de mi familia llorando el delito que se castiga ahí con tan graves penas.\"},{\"heading\":false,\"text\":\"Entonces me contestó el Maestro:\"},{\"heading\":false,\"text\":\"--No se ocupe ya más tu pensamiento en la suerte de ese espíritu; piensa en otra cosa, y quédese él donde está. Le he visto al pie del puente señalarte y amenazarte airadamente con el dedo, y oí que le llamaban Geri del Bello; pero tú estabas tan distraído con el que gobernó a Altaforte, que como no miraste hacia donde él estaba, se marchó.\"},{\"heading\":false,\"text\":\"--¡Oh, mi Guía!--dije yo--Su violenta muerte, que no ha sido aún vengada por ninguno de nosotros, partícipes de la ofensa, le ha indignado: he aquí por qué, según presumo, se ha ido sin hablarme; y esto es causa de que me inspire más compasión.\"},{\"heading\":false,\"text\":\"Así continuamos hablando hasta el primer punto del peñasco, desde donde se distinguiría la otra fosa hasta el fondo, si hubiera en ella más claridad. Cuando estuvimos colocados sobre el último recinto de Malebolge, de manera que los transfigurados que contenía pudieran aparecer a nuestra vista, hirieron mis oídos diversos lamentos que cual agudas flechas me traspasaron el corazón; por lo cual tuve que cubrirme las orejas con ambas manos. Si entre los meses de julio y septiembre los hospitales de la Valdichiana y los enfermos de las Marismas y de Cerdeña estuvieran reunidos en una sola fosa, esta acumulación formaría un espectáculo tan doloroso como el que ví en aquella, de la cual se exhalaba la misma pestilencia que la que despiden los miembros gangrenados. Descendimos hacia la izquierda por la última orilla del largo peñasco, y entonces pude distinguir mejor la profundidad de aquel abismo, donde la infalible Justicia, ministro del Altísimo, castiga a los falsarios que apunta en su registro.\"},{\"heading\":false,\"text\":\"No creo que causara mayor tristeza ver enfermo el pueblo entero de Egina, cuando se inficionó tanto el aire, que perecieron todos los animales hasta el miserable gusano, habiendo salido después los habitantes de aquella isla de la raza de las hormigas, según aseguran los poetas, como causaba el ver a los espíritus languidecer en tristes montones por aquel obscuro valle. Cuál yacía tendido sobre el vientre, cuál sobre las espaldas unos de otros; y alguno andaba a rastras por el triste camino.\"},{\"heading\":false,\"text\":\"Ibamos caminando paso a paso sin decir una palabra, mirando y escuchando a los enfermos, que no podían sostener sus cuerpos. Vi dos de ellos sentados y apoyados el uno contra el otro, como se apoyan las tejas para cocerlas, y llenos de pústulas desde la cabeza hasta los pies. Nunca he visto criado alguno, a quien espera su amo o que vela a pesar suyo, tan diligente en remover la almohaza, como lo era cada uno de aquellos condenados para rascarse con frecuencia y calmar así la terrible rabia de su comezón, que no tenía otro remedio. Se arrancaban con las uñas las pústulas, como el cuchillo arranca las escamas del escaro o de otro pescado que las tenga más grandes.\"},{\"heading\":false,\"text\":\"--¡Oh tú, que con los dedos te desarmas--dijo mi Guía a uno de ellos--, y que los empleas como si fueran tenazas! Dime si hay algún latino entre los que están aquí, y ¡ojalá puedan tus uñas bastarte eternamente para ese trabajo!\"},{\"heading\":false,\"text\":\"--Latinos somos los dos a quienes ves tan deformes--respondió uno de ellos llorando--; pero ¿quién eres tú, que preguntas por nosotros?\"},{\"heading\":false,\"text\":\"Y el Guía repuso:\"},{\"heading\":false,\"text\":\"--Soy un espíritu que he descendido con este sér viviente de grado en grado, y tengo el encargo de enseñarle el Infierno.\"},{\"heading\":false,\"text\":\"Las dos sombras cesaron entonces de prestarse mutuo apoyo, y cada una de ellas se volvió temblando hacia mí, juntamente con otras que lo oyeron, aunque no se dirigía a ellas la contestación. El buen Maestro se me acercó diciendo: \\\"Diles lo que quieras.\\\" Y ya que él lo permitía, empecé de este modo:\"},{\"heading\":false,\"text\":\"--Así vuestra memoria no se borre de las mentes humanas en el primer mundo, y antes bien dure por muchos años; decidme quiénes sois y de qué nación: no tengáis reparo en franquearos conmigo, sin que os lo impida vuestro insoportable y vergonzoso suplicio.\"},{\"heading\":false,\"text\":\"--Yo fuí de Arezzo--respondió uno--, y Alberto de Siena me condenó a las llamas; pero la causa de mi muerte no es la que me ha traído al Infierno.[37] Es cierto que le dije chanceándome: \\\"Yo sabría elevarme por el aire volando;\\\" y él, que era curioso y de cortos alcances, quiso que yo le enseñase aquel arte: y tan sólo porque no le convertí en Dédalo, me hizo quemar por mandato de uno que le tenía por hijo; pero Minos, que no puede equivocarse, me condenó a la última de las diez fosas por haberme dedicado a la alquimia en el mundo.\"},{\"heading\":false,\"text\":\"[37] Dícese que éste fué cierto Griffolino, alquimista, que alabándose de conocer el arte de volar, prometió enseñárselo a un sienés llamado Alberto, el cual al principio le creyó; pero habiendo advertido después el engaño, le acusó ante el obispo de Siena como reo de nigromancia, y Griffolino fué condenado por dicho obispo a ser quemado vivo, como nigromante.\"},{\"heading\":false,\"text\":\"Yo dije al Poeta:\"},{\"heading\":false,\"text\":\"--¿Hubo jamás un pueblo tan vano como el sienés? Seguramente no lo es tanto, ni con mucho, el pueblo francés.\"},{\"heading\":false,\"text\":\"Entonces el otro leproso, que me oyó, contestó a mis palabras:\"},{\"heading\":false,\"text\":\"--Exceptúa a Stricca, que supo hacer tan moderados gastos; y a Niccolo, que fué el primero que descubrió la rica usanza del clavo de especia, en la ciudad donde hoy es tan común su uso. Exceptúa también la sociedad en que malgastó Caccia de Asciano sus viñas y sus bosques, y en la que Abbagliato demostró hasta donde llegaba su juicio. Mas para que sepas quién es el que de este modo te secunda contra los sieneses, fija en mí tus ojos a fin de que mi rostro corresponda al deseo que tienes de conocerme, y podrás ver que soy la sombra de Capocchio, el que falsificó los metales por medio de la alquimia: y debes recordar, si eres efectivamente el que pienso, que fuí por naturaleza un buen imitador.\"}]},{\"title\":\"Infierno — canto trigesimo\",\"blocks\":[{\"heading\":false,\"text\":\"En aquel tiempo en que Juno, por causa de Semele, estaba irritada contra la sangre tebana, como lo demostró más de una vez, Atamas se volvió tan insensato que, al ver acercarse a su mujer, llevando de la mano a sus dos hijos, exclamó: \\\"Tendamos las redes de modo que yo coja a su paso la leona con sus cachorros;\\\" y extendiendo después las desapiadadas manos, agarró a uno de ellos, que se llamaba Learco, le hizo dar vueltas en el aire y lo estrelló contra una roca: la madre se ahogó con el hijo restante. Cuando la fortuna abatió la grandeza de los troyanos, que a todo se atrevían, hasta que el reino fué destruído juntamente con el rey, la triste Hécuba, miserable y cautiva, después de haber visto a Polixena muerta, y el cuerpo de su Polidoro tendido en la orilla del mar quedó con el corazón tan desgarrado, que, fuera de sí, empezó a ladrar como un perro; de tal modo la había trastornado el dolor. Pero ni los tebanos ni los troyanos furiosos demostraron tanta crueldad, no ya en torturar cuerpos humanos, sino ni siquiera animales, como la que vi en dos sombras desnudas y pálidas, que corrían mordiéndose, como el cerdo cuando se escapa de su pocilga. Una de ellas alcanzó a Capocchio, y se le afianzó a la nuca de tal modo, que tirando de él, le hizo arañar con su vientre el duro suelo. El aretino, que quedó temblando, me dijo:\"},{\"heading\":false,\"text\":\"--Ese loco es Gianni Schicchi, que va rabioso maltratando a los demás.\"},{\"heading\":false,\"text\":\"--¡Oh!--le dije yo--: no temas decirme quién es la otra sombra que va con él, antes que desaparezca, y ojalá no venga a hincarte los dientes en el cuerpo.\"},{\"heading\":false,\"text\":\"Me contestó:\"},{\"heading\":false,\"text\":\"--Es el alma antigua de la perversa Mirra, que fué amante de su padre contra las leyes del amor honesto: para cometer tal pecado se disfrazó bajo la forma de otra; como aquel que ya se va tuvo empeño en fingirse Buoso Donati, a fin de ganar la \\\"Donna della Torma,\\\" testando en su lugar, y dictando las cláusulas del testamento.[38]\"},{\"heading\":false,\"text\":\"[38] Gianni Schicchi acometió la empresa de suplantar la persona de Buoso Donati, muerto sin testar; para lo cual se metió en la cama de éste, y fingiendo que estaba cercano a la muerte, testó e instituyó por heredero a Simón Donati, hijo de Buoso, y como legado, dejó a Gianni Schicchi, es decir, a sí mismo, la mejor yegua de las caballerizas de Buoso, llamada Madona Tonina. Dante dice: della Torma por desprecio.\"},{\"heading\":false,\"text\":\"Cuando hubieron pasado aquellas dos almas furiosas, sobre las cuales había tenido fija mi vista, me volví para mirar las sombras de los otros mal nacidos. Vi uno, que pareciera un laúd, si hubiese tenido el cuerpo cortado en el sitio donde el hombre se bifurca. La pesada hidropesía, que, a causa de los humores convertidos en maligna sustancia, hace los miembros tan desproporcionados, que el rostro no corresponde al vientre, le obligaba a tener la boca abierta, pareciéndose al hético que, cuando está sediento, dirige uno de sus labios hacia la barba y otro hacia la nariz.\"},{\"heading\":false,\"text\":\"--¡Oh vosotros, que no sufrís pena alguna (y no sé por qué) en este mundo miserable!--nos dijo--: mirad y estad atentos al infortunio de maese Adam: yo tuve en abundancia, mientras viví, todo cuanto deseé; y ahora, ¡ay de mí!, sólo deseo una gota de agua.\"},{\"heading\":false,\"text\":\"Los arroyuelos que desde las verdes colinas del Casentino descienden hasta el Arno, trazando frescos y apacibles cauces, continuamente están ante mi vista, y no en vano; pues su imagen me reseca más que el mal que descarna mi rostro. La rígida justicia que me castiga se sirve del mismo lugar donde he pecado para hacerme exhalar más suspiros. Allí está Romena, donde falsifiqué la moneda acuñada con el busto del Bautista, por lo cual dejé en la tierra mi cuerpo quemado. Pero si yo viese aquí el alma criminal de Guido, o la de Alejandro, o la de su hermano, no cambiaría el placer de mirarlos a mi lado ni aun por la fuente Branda. Una de ellas está ya aquí dentro, si es cierto lo que dicen las coléricas sombras de los que giran por estos sitios; pero ¿qué me importa, si tengo encadenados mis miembros? Si a lo menos fuese yo tan ágil que en cien años pudiera andar una pulgada, ya me habría internado por el sendero, buscándola entre esa gente deforme, a pesar de que la fosa tiene once millas de circunferencia y no menos de media milla de diámetro. Por su causa me veo entre estos condenados: ellos me indujeron a acuñar los florines, que bien tenían tres quilates de liga.\"},{\"heading\":false,\"text\":\"A mi vez lo dije:\"},{\"heading\":false,\"text\":\"--¿Quiénes son esos dos espíritus infelices, que despiden vaho, como en el invierno una mano mojada, y que tan unidas yacen a tu derecha?\"},{\"heading\":false,\"text\":\"--Aquí los encontré--respondióme--, cuando bajé a este abismo; y desde entonces, ni se han movido, ni creo que eternamente se muevan. El uno es la falsa que acusó a José; el otro es el falso Sinón, griego de Troya: por efecto de su ardiente fiebre, lanzan ese vapor fétido.\"},{\"heading\":false,\"text\":\"Uno de ellos, indignado quizá porque se le daba aquel nombre infame, le golpeó con el puño en su endurecido vientre, haciéndoselo resonar como un tambor. Maese Adam le dió a su vez en el rostro con su puño, que no parecía menos duro, diciéndole:\"},{\"heading\":false,\"text\":\"--Aunque me vea privado de moverme a causa de la pesadez de algunos de mis miembros, tengo el brazo suelto para semejante tarea.\"},{\"heading\":false,\"text\":\"A lo que aquél replicó:\"},{\"heading\":false,\"text\":\"--Cuando marchabas hacia la hoguera no lo tenías tan suelto; pero lo tenías mucho más cuando acuñabas moneda.\"},{\"heading\":false,\"text\":\"El hidrópico repuso:\"},{\"heading\":false,\"text\":\"--Eres verídico en eso; mas no lo fuiste tanto cuando en Troya te incitaron a que dijeses la verdad.\"},{\"heading\":false,\"text\":\"--Si allí dije una falsedad, en cambio tú falsificaste el cuño--dijo Sinón--; y si yo estoy aquí por una falta, tú lo estás por muchas más que ninguno otro demonio.\"},{\"heading\":false,\"text\":\"--Acuérdate, perjuro, del caballo--replicó aquel que tenía el vientre hinchado--; y sírvate de castigo el que el mundo entero conoce tu delito.\"},{\"heading\":false,\"text\":\"--Sírvate a ti también de castigo la sed que tiene agrietada tu lengua--contestó el Griego--, y el agua podrida que eleva tu vientre como una barrera ante tus ojos.\"},{\"heading\":false,\"text\":\"Entonces el monedero replicó:\"},{\"heading\":false,\"text\":\"--También tu boca se rasga por hablar mal, como acostumbra: si yo tengo sed, y si el humor me hincha, tú tienes fiebre y te duele la cabeza; no te harías mucho de rogar para lamer el espejo de Narciso.\"},{\"heading\":false,\"text\":\"Yo estaba escuchándoles atentamente, cuando me dijo mi Maestro:\"},{\"heading\":false,\"text\":\"--Sigue, sigue contemplándolos aún; que poco me falta para reírme de ti.\"},{\"heading\":false,\"text\":\"Cuando le oí hablarme con ira, me volví hacia él tan abochornado, que aún conservo vivo el recuerdo en mi memoria: y como quien sueña en su desgracia, que aun soñando desea soñar, y anhela ardientemente que sea sueño lo que ya lo es, así estaba yo, sin poder proferir una palabra, por más que quisiera excusarme; y a pesar de que con el silencio me excusaba, no creía hacerlo así.\"},{\"heading\":false,\"text\":\"--Con menos vergüenza habría bastante para borrar una falta mayor que la tuya--me dijo el Maestro--: consuélate; y si acaso vuelve a suceder que te reunas con gente entregada a semejantes debates, piensa en que estoy siempre a tu lado; porque querer oír eso es querer una bajeza.\"}]},{\"title\":\"Infierno — canto trigesimoprimero\",\"blocks\":[{\"heading\":false,\"text\":\"La misma lengua que antes me hirió, tiñendo de rubor mis mejillas, me aplicó en seguida el remedio: Así he oído contar que la lanza de Aquiles y de su padre solía ocasionar primero un disfavor, y luego un buen regalo. Volvimos la espalda a aquel desventurado valle, andando, sin decir una palabra, por encima del margen que lo rodea. Allí no era de día ni de noche, de modo que mi vista alcanzaba poco delante de mí: pero oí resonar una gran trompa, tan fuertemente, que habría impuesto silencio a cualquier trueno; por lo cual mis ojos, siguiendo la dirección que aquel ruido traía, se fijaron totalmente en un solo punto. No hizo sonar tan terriblemente su trompa Orlando, después de la dolorosa derrota en que Carlo Magno perdió el fruto de su santa empresa. A poco de haber vuelto hacia aquel lado la cabeza, me pareció ver muchas torres elevadas, por lo que dije:\"},{\"heading\":false,\"text\":\"--Maestro, ¿qué tierra es ésta?\"},{\"heading\":false,\"text\":\"Me respondió:\"},{\"heading\":false,\"text\":\"--Como miras a lo lejos a través de las tinieblas, te equivocas en lo que te imaginas. Ya verás, cuando hayas llegado allí, cuánto engaña a la vista la distancia: así pues, aprieta el paso.\"},{\"heading\":false,\"text\":\"Después me cogió afectuosamente de la mano, y me dijo:\"},{\"heading\":false,\"text\":\"--Antes que pasemos más adelante, y a fin de que el caso no te cause tanta extrañeza, sabe que eso no son torres, sino gigantes; todos los cuales están metidos hasta el ombligo en el pozo alrededor de sus muros.\"},{\"heading\":false,\"text\":\"Así como la vista, cuando se disipa la niebla, reconoce poco a poco las cosas ocultas por el vapor en que estaba envuelto el aire, de igual modo, y a medida que la mía atravesaba aquella atmósfera densa y obscura, conforme nos íbamos acercando hacia el borde del pozo, mi error se disipaba y crecía mi miedo. Lo mismo que Montereggione corona de torres su recinto amurallado, así, por el borde que rodea el pozo, se elevaban como torres y hasta la mitad del cuerpo los horribles gigantes, a quienes amenaza todavía Júpiter desde el cielo, cuando truena. Yo podía distinguir ya el rostro, los hombros y el pecho de uno de ellos, y gran parte de su vientre, y sus dos brazos a lo largo de los costados. En verdad que hizo bien la Naturaleza cuando abandonó el arte de crear semejantes animales, para quitar pronto a Marte tales ejecutores; y si ella no se arrepiente de producir elefantes y ballenas, quien lo repare sutilmente, verá en esto mismo su justicia y su discreción; porque donde la fuerza del ingenio se une a la malevolencia y al vigor, no hay resistencia posible para los hombres.\"},{\"heading\":false,\"text\":\"Su cabeza me parecía tan larga y gruesa como la piña de San Pedro en Roma[39], guardando la misma proporción los demás huesos; de suerte que, aun cuando el ribazo le ocultaba de medio cuerpo abajo, se veía lo bastante para que tres frisones no hubieran podido alabarse de alcanzar a su cabellera; porque yo calculaba que tendría treinta grandes palmos desde el borde del pozo hasta el sitio donde el hombre se abrocha la capa.\"},{\"heading\":false,\"text\":\"[39] Piña de bronce que primero estuvo sobre la Mole Adriana; en tiempo de Dante estaba en la plaza de la antigua basílica de San Pedro en el Vaticano, y ahora en la sala del gran nicho de Bramante en el jardín que rodean los Museos, llamado por esto \\\"giardin della pigna.\\\" Su altura actualmente es de diez palmos, pero en tiempo de Dante, antes de truncada su parte superior, medía unos quince.\"},{\"heading\":false,\"text\":\"\\\"Raphel mai amech isabi almi\\\"[40], empezó a gritar la fiera boca, en la cual no estarían bien otras voces más suaves; y mi Guía le dijo:\"},{\"heading\":false,\"text\":\"--Alma insensata, sigue entreteniéndote con la trompa, y desahógate con ella, cuando te agite la cólera u otra pasión. Busca por tu cuello y encontrarás la soga que la sujeta, ¡oh alma turbada!; mírala cómo ciñe tu enorme pecho.\"},{\"heading\":false,\"text\":\"[40] Según Fraticelli, cada una de estas cinco extrañas palabras pertenece a diferente lengua; la primera al hebreo, y las otras a cuatro de los principales dialectos derivados de aquélla. Esta opinión parece confirmarla Dante, cuando dice más abajo: \\\"El mismo se acusa: este es Nemrod, etc.;\\\" el que por haber querido construir la torre de Babel, produjo la confusión e hizo que en el mundo no se hable una sola lengua. En tal supuesto, y admitiendo la versión del abate José Venturi (aunque éste dice que las palabras son siriacas), significarían ¡Poder de Dios! ¿Por qué estoy en esta profundidad? Vuelve atrás: escóndete: pero perteneciendo a varias lenguas, sería como si traducidas en español, latín, alemán, francés e italiano, dijésemos: ¡Pardiez!--cur ego--hier--Va-t-en:--fascondi.\"},{\"heading\":false,\"text\":\"Después me dijo:\"},{\"heading\":false,\"text\":\"El mismo se acusa: ese es Nemrod, por cuyo audaz pensamiento se ve obligado el mundo a usar más de una lengua. Dejémosle estar, y no lancemos nuestras palabras al viento; pues ni él comprende el lenguaje de los demás, ni nadie conoce el suyo.\"},{\"heading\":false,\"text\":\"Continuamos, pues, nuestro viaje, siguiendo hacia la izquierda; y a un tiro de ballesta de aquel punto encontramos otro gigante mucho más grande y fiero. No podré decir quién fué capaz de sujetarle; pero sí que tenía ligado el brazo izquierdo por delante y el otro por detrás con una cadena, la cual le rodeaba del cuello abajo, dándole cinco vueltas en la parte del cuerpo que salía fuera del pozo.\"},{\"heading\":false,\"text\":\"--Ese soberbio quiso ensayar su poder contra el sumo Júpiter--dijo mi Guía--, por lo cual tiene la pena que ha merecido. Llámase Efialto, y dió muestras de audacia cuando los gigantes causaron miedo a los Dioses: los brazos que tanto movió entonces, no los moverá ya jamás.\"},{\"heading\":false,\"text\":\"Y yo le dije:\"},{\"heading\":false,\"text\":\"--Si fuese posible, quisiera que mis ojos tuviesen una idea de lo que es el desmesurado Briareo.\"},{\"heading\":false,\"text\":\"A lo que contestó:\"},{\"heading\":false,\"text\":\"--Verás cerca de aquí a Anteo, que habla y anda suelto, el cual nos conducirá al fondo del Infierno. El que tú quieres ver está atado mucho más lejos, y es lo mismo que éste, sólo que su rostro parece más feroz.\"},{\"heading\":false,\"text\":\"El más impetuoso terremoto no sacudió nunca una torre con tal violencia como se agitó repentinamente Efialto. Entonces temí la muerte más que nunca, y a no haber visto que el gigante estaba bien atado, bastara para ello el miedo que me poseía. Seguimos avanzando, y llegamos adonde estaba Anteo, que, sin contar la cabeza, salía fuera del abismo lo menos cinco alas.[41]\"},{\"heading\":false,\"text\":\"[41] Antigua medida inglesa, equivalente a un metro ciento sesenta y ocho milímetros. Cinco alas equivalen, pues, a unos treinta palmos.\"},{\"heading\":false,\"text\":\"--¡Oh tú, que en el afortunado valle donde Escipión heredó tanta gloria, cuando Aníbal y los suyos volvieron las espaldas, recogiste mil leones por presa, y que, si hubieras asistido a la gran guerra de tus hermanos, aún hay quien crea que habrías asegurado la victoria a los hijos de la Tierra! Si no lo llevas a mal, condúcenos al fondo en donde el frío endurece al Cocito. No hagas que me dirija a Ticio ni a Tifeo: este que ves puede dar lo que aquí se desea: por tanto, inclínate y no tuerzas la boca. Todavía puede renovar tu fama en el mundo; pues vive, y espera gozar aún de larga vida, si la gracia no lo llama a sí antes de tiempo.\"},{\"heading\":false,\"text\":\"Así le dijo el Maestro; y el gigante, apresurándose a extender aquellas manos que tan rudamente oprimieron a Hércules, cogió a mi Guía. Cuando Virgilio se sintió agarrar, me dijo: \\\"Acércate para que yo te tome.\\\" Y en seguida me abrazó de modo, que los dos juntos formábamos un solo fardo.\"},{\"heading\":false,\"text\":\"Como al mirar la Carisenda[42] por el lado a que está inclinada, cuando pasa una nube por encima de ella en sentido contrario, parece próxima a derrumbarse, tal me pareció Anteo cuando le vi inclinarse; y fué para mí tan terrible aquel momento, que habría querido ir por otro camino. Pero él nos condujo suavemente al fondo del abismo que devora a Lucifer y a Judas; y sin demora cesó su inclinación, volviendo a erguirse como el mástil de un navío.\"},{\"heading\":false,\"text\":\"[42] Torre inclinada de Bolonia, llamada así del nombre de sus constructores, Felipe y Odón de Garisendi (año de 1110), y que hoy se llama la Torre Mozza por haberla mandado truncar en 1355 el tirano Juan Visconti de Oleggio. Tiene 130 pies de elevación. Al que se coloca al pie de ella en el lado a que se inclina, mirando arriba cuando pasa una nube en sentido contrario a su inclinación, le parece que la torre va a caerse.\"}]},{\"title\":\"Infierno — canto trigesimosegundo\",\"blocks\":[{\"heading\":false,\"text\":\"Si poseyese un estilo áspero y ronco, cual conviene para describir el sombrío pozo, sobre el que se apoyan todas las otras rocas, expresaría mucho mejor la esencia de mi pensamiento; pero como no lo tengo, me decido a ello con temor; pues no es empresa que pueda tomarse como juego, ni para ser acometida por una lengua balbuciente, la de describir el fondo de todo el universo. Pero vengan en auxilio de mis versos aquellas Mujeres que ayudaron a Anfión a fundar a Tebas, para que el estilo no desdiga de la naturaleza del asunto. ¡Oh gentes malditas sobre todas las demás, que estáis en el sitio del que me es tan duro hablar; más os valiera haber sido aquí convertidas en ovejas o cabras!\"},{\"heading\":false,\"text\":\"Cuando llegamos al fondo del obscuro pozo, mucho más abajo de donde tenía los pies el gigante, como yo estuviese aún mirando el alto muro, oí que me decían: \\\"Cuidado cómo andas: procura no pisar las cabezas de nuestros infelices y torturados hermanos.\\\" Volvíme al oír esto, y vi delante de mí y a mis pies un lago, que por estar helado, parecía de vidrio y no de agua. Ni el Danubio en Austria durante el invierno, ni el Tanais allá, bajo el frío cielo, cubren su curso de un velo tan denso como el de aquel lago, en el cual, aunque hubieran caído el Tabernick o el Pietrapana, no habrían causado el menor estallido. Y a la manera de las ranas cuando gritan con la cabeza fuera del agua, en la estación en que la villana sueña que espiga, así estaban aquellas sombras llorosas y lívidas, sumergidas en el hielo hasta el sitio donde aparece la vergüenza, produciendo con sus dientes el mismo sonido que la cigüeña con su pico. Tenían todas el rostro vuelto hacia abajo: su boca daba muestras del frío que sentían, y sus ojos las daban de la tristeza de su corazón. Cuando hube examinado algún tiempo en torno mío, miré a mis pies, y vi dos sombras tan estrechamente unidas, que sus cabellos se mezclaban.\"},{\"heading\":false,\"text\":\"--Decidme quiénes sois, vosotros, que tanto unís vuestros pechos--dije yo.\"},{\"heading\":false,\"text\":\"Levantaron la cabeza, y después de haberme mirado, sus ojos, que estaban preñados de lágrimas, se derramaron en los párpados; pero el frío congeló en ellos aquellas lágrimas, volviéndolos a cerrar. Ninguna grapa unió jamás tan fuertemente dos trozos de madera; por lo cual ambos condenados se entrechocaron como dos carneros: tanta fué la ira que los dominó. Y otro, a quien el frío había hecho perder las orejas, me dijo, sin levantar la cabeza:\"},{\"heading\":false,\"text\":\"--¿Por qué nos miras tanto? Si quieres saber quiénes son estos dos, te diré que el valle por donde corre el Bisenzio fué de su padre Alberto y de ellos. Ambos salieron de un mismo cuerpo; y aunque recorras toda la Caína, no encontrarás una sombra más digna de estar sumergida en el hielo, ni aun la de aquel a quien la mano de Arturo rompió de un golpe el pecho y la sombra, ni la de Focaccia, ni la de éste que me impide con su cabeza ver más lejos, y que se llamó Sassolo Mascheroni: si eres toscano, bien sabrás quién es. Y para que no me hagas hablar más, sabe que yo soy Camiccione de Pazzi, y que espero a Carlino, cuyas culpas harán aparecer menos graves las mías.\"},{\"heading\":false,\"text\":\"Después vi otros mil rostros amoratados por el frío, tanto que desde entonces tengo horror, y lo tendré siempre a los estanques helados. Y mientras nos dirigíamos hacia el centro, donde converge toda la gravedad de la Tierra, yo temblaba en la lobreguez eterna; y no sé si lo dispuso Dios, el Destino o la Fortuna; pero al pasar por entre aquellas cabezas, dí un fuerte golpe con el pie en el rostro de una de ellas, que me dijo llorando:\"},{\"heading\":false,\"text\":\"--¿Por qué me pisas? Si no vienes a aumentar la venganza de Monteaperto, ¿por qué me molestas?\"},{\"heading\":false,\"text\":\"Entonces dije yo:\"},{\"heading\":false,\"text\":\"--Maestro mío, espérame aquí, a fin de que éste me esclarezca una duda: en seguida me daré cuanta prisa quieras.\"},{\"heading\":false,\"text\":\"El Guía se detuvo, y yo dije a aquel que aún estaba blasfemando:\"},{\"heading\":false,\"text\":\"--¿Quien eres tú, que así reprendes a los demás?\"},{\"heading\":false,\"text\":\"Me contestó:\"},{\"heading\":false,\"text\":\"--Y tú, que vas por el recinto de Antenor, golpeando a los demás en el rostro, de modo que, si estuvieras vivo, aún serían tus golpes demasiado fuertes, ¿quién eres?\"},{\"heading\":false,\"text\":\"--Yo estoy vivo--fué mi respuesta--; y puede serte grato, si fama deseas, que ponga tu nombre entre los otros que conservo en la memoria.\"},{\"heading\":false,\"text\":\"A lo que repuso:\"},{\"heading\":false,\"text\":\"--Deseo todo lo contrario: véte de aquí, y no me causes más molestia, pues suenan mal tus lisonjas en esta caverna.\"},{\"heading\":false,\"text\":\"Entonces le cogí por los pelos del cogote, y le dije:\"},{\"heading\":false,\"text\":\"--Es preciso que digas tu nombre, o no te quedará ni un solo cabello.\"},{\"heading\":false,\"text\":\"Pero él me replicó:\"},{\"heading\":false,\"text\":\"--Aunque me repeles, ni te diré quien soy, ni verás mi rostro, por más que me golpees mil veces en la cabeza.\"},{\"heading\":false,\"text\":\"Yo tenía ya sus cabellos enroscados en mi mano, y le había arrancado más de un puñado de ellos, mientras él aullaba con los ojos fijos en el hielo, cuando otro condenado gritó: \\\"¿Qué tienes, Bocca? ¿No te basta castañetear los dientes, sino que también ladras? ¿Qué demonio te atormenta?\\\"\"},{\"heading\":false,\"text\":\"--Ahora--dije--ya no quiero que hables, traidor maldito; que para tu eterna vergüenza, llevaré al mundo noticias ciertas de ti.\"},{\"heading\":false,\"text\":\"--Véte pronto--repuso--, y cuenta lo que quieras; pero si sales de aquí, no dejes de hablar de ese que ha tenido la lengua tan suelta, y que está llorando el dinero que recibió de los franceses: \\\"Yo vi, podrás decir, a Buoso de Duera, allí donde los pecadores están helados.\\\" Si te preguntan por los demás que están aquí, a tu lado tienes al de Becchería, cuya garganta segó Florencia. Creo que más allá está Gianni de Soldanieri con Ganelón y Tebaldello, el que entregó a Faenza cuando sus habitantes dormían.\"},{\"heading\":false,\"text\":\"Estábamos ya lejos de aquél, cuando vi a otros dos helados en una misma fosa, colocados de tal modo, que la cabeza del uno parecía ser el sombrero del otro. Y como el hambriento en el pan, así el de encima clavó sus dientes al de debajo en el sitio donde el cerebro se une con la nuca. No mordió con más furor Tideo las sienes de Menalipo, que aquél roía el cráneo de su enemigo y las demás cosas inherentes al mismo.\"},{\"heading\":false,\"text\":\"--¡Oh tú, que demuestras, por medio de tan brutal acción, el odio que tienes al que estás devorando! Dime qué es lo que te induce a ello--le pregunté--bajo el pacto de que, si te quejas con razón de él, sabiendo yo qué crimen es el suyo y quiénes sois, te vengaré en el mundo, si mi lengua no llega antes a secarse.\"}]},{\"title\":\"Infierno — canto trigesimotercio\",\"blocks\":[{\"heading\":false,\"text\":\"Aquel pecador apartó su boca de tan horrible alimento, limpiándosela en los pelos de la cabeza cuya parte posterior acababa de roer; y luego empezó a hablar de esta manera:\"},{\"heading\":false,\"text\":\"--Tú quieres que renueve el desesperado dolor que oprime mi corazón, sólo al pensar en él, y aun antes de hablar. Pero si mis palabras deben ser un germen de infamia para el traidor a quien devoro, me verás llorar y hablar a un mismo tiempo. No sé quién eres, ni de qué medios te has valido para llegar hasta aquí; pero al oírte, me pareces efectivamente florentino. Has de saber que yo fuí el conde Ugolino, y éste el arzobispo Ruggieri: ahora te diré por qué lo trato así. No es necesario manifestarte que por efecto de sus malos pensamientos, y fiándome de él, fuí preso y muerto después. Pero te contaré lo que no puedes haber sabido; esto es, lo cruel que fué mi muerte, y comprenderás cuánto me ha ofendido. Un pequeño agujero abierto en la torre, que por mi mal se llama hoy del Hambre, y en la que todavía serán encerrados otros, me había permitido ver por su hendedura ya muchas lunas, cuando tuve el mal sueño que descorrió para mí el velo del porvenir. Ruggieri se me aparecía como señor y caudillo, cazando el lobo y los lobeznos en el monte que impide a los pisanos ver la ciudad de Luca. Se había hecho preceder de los Gualandi, de los Sismondi y los Lanfranchi, que iban a la cabeza con perros hambrientos, diligentes y amaestrados. El padre y sus hijuelos me parecieron rendidos después de una corta carrera, y creí ver que aquéllos les desgarraban los costados con sus agudas presas. Cuando desperté antes de la aurora, oí llorar entre sueños a mis hijos, que estaban conmigo, y pedían pan. Bien cruel eres, si no te contristas pensando en lo que aquello anunciaba a mi corazón; y si ahora no lloras, no sé lo que puede excitar tus lágrimas. Estábamos ya despiertos, y se acercaba la hora en que solían traernos nuestro alimento; pero todos dudábamos, porque cada cual había tenido un sueño semejante. Oí que clavaban la puerta de la horrible torre, por lo cual miré al rostro de mis hijos sin decir palabra: yo no podía llorar, porque el dolor me tenía como petrificado: lloraban ellos, y mi Anselmito dijo: \\\"¿Qué tienes, padre, que así nos miras?\\\" Sin embargo, no lloré ni respondí una palabra en todo aquel día, ni en la noche siguiente, hasta que el otro Sol alumbró el mundo. Cuando entró en la dolorosa prisión uno de sus débiles rayos, y consideré en aquellos cuatro rostros el aspecto que debía tener el mío, empecé a morderme las manos desesperado; y ellos, creyendo que yo lo hacía obligado por el hambre, se levantaron con presteza y dijeron: \\\"Padre, nuestro dolor será mucho menor, si nos comes a nosotros: tú nos diste estas miserables carnes; despójanos, pues, de ellas.\\\" Entonces me calmé para no entristecerlos más; y aquel día y el siguiente permanecimos mudos. ¡Ay, dura tierra! ¿Por qué no te abriste? Cuando llegamos al cuarto día, Gaddo se tendió a mis pies, diciendo: \\\"Padre mío, ¿por qué no me auxilias?\\\" Allí murió; y lo mismo que me estás viendo, vi yo caer los tres, uno a uno, entre el quinto y el sexto día. Ciego ya, fuí a tientas buscando a cada cual, llamándolos durante tres días después de estar muertos; hasta que, al fin, pudo en mí más la inedia que el dolor.\"},{\"heading\":false,\"text\":\"Cuando hubo pronunciado estas palabras, torciendo los ojos, volvió a coger el miserable cráneo con los dientes, que royeron el hueso como los de un perro. ¡Ah, Pisa, vituperio de las gentes del hermoso país donde el \\\"si\\\" suena! Ya que tus vecinos son tan morosos en castigarte, muévanse la Capraja y la Gorgona, y formen un dique a la embocadura del Arno, para que sepulte en sus aguas a todos tus habitantes; pues si el conde Ugolino fué acusado de haber vendido tus castillos, no debiste someter a sus hijos a tal suplicio. Su tierna edad patentizaba, ¡oh nueva Tebas!, la inocencia de Ugucción y del Brigata, y la de los otros dos que ya he nombrado.\"},{\"heading\":false,\"text\":\"Seguimos luego más allá, donde el hielo oprime duramente a otros condenados, que no están con el rostro hacia abajo, sino vueltos hacia arriba. Su mismo llanto no les deja llorar; pues las lágrimas, que al salir encuentran otras condensadas, se vuelven adentro, aumentando la angustia; porque las primeras lágrimas forman un dique, y como una visera de cristal, llenan debajo de los párpados toda la cavidad del ojo. Y aunque mi rostro, a causa del gran frío, había perdido toda sensibilidad, como si estuviera encallecido, me pareció qué sentía algún viento, por lo cual dije:\"},{\"heading\":false,\"text\":\"--Maestro, ¿qué causa mueve este viento? ¿No está extinguido aquí todo vapor?\"},{\"heading\":false,\"text\":\"A lo cual me contestó:\"},{\"heading\":false,\"text\":\"--Pronto llegarás a un sitio donde tus ojos te darán la respuesta, viendo la causa de ese viento.\"},{\"heading\":false,\"text\":\"Y uno de los desgraciados de la helada charca nos gritó:\"},{\"heading\":false,\"text\":\"--¡Oh almas tan culpables que habéis sido destinadas al último recinto! Arrancadme de los ojos este duro velo, a fin de que pueda desahogar el dolor que me hincha el corazón, antes que mis lágrimas se hielen de nuevo.\"},{\"heading\":false,\"text\":\"Al oír tales palabras, le dije:\"},{\"heading\":false,\"text\":\"--Si quieres que te alivie, dime quién fuiste; y si no te presto ese consuelo, véame sumergido en el fondo de ese hielo.\"},{\"heading\":false,\"text\":\"Entonces me contestó:\"},{\"heading\":false,\"text\":\"--Yo soy fray Alberigo[43]: soy aquel, cuyo huerto ha producido tan mala fruta, que aquí recibo un dátil por un higo.\"},{\"heading\":false,\"text\":\"[43] Alberigo de Manfredi, señor de Faenza, que ingresó en la orden de los hermanos Gozosos, se había enemistado con sus parientes. Un día, fingiendo reconciliarse con ellos, les invitó a un gran banquete, y en el momento de servirse los postres, les hizo asesinar. De aquí tuvo origen el proverbio italiano: \\\"Ese ha probado la fruta de Alberigo.\\\"\"},{\"heading\":false,\"text\":\"--¡Oh!--le dije--; ¿también tú has muerto?\"},{\"heading\":false,\"text\":\"--No sé cómo estará mi cuerpo allá arriba--repuso--; esta Ptolomea tiene el privilegio de que las almas caigan con frecuencia en ella antes de que Atropos mueva los dedos; y para que de mejor grado me arranques las congeladas lágrimas del rostro, sabe que en cuanto un alma comete alguna traición como la que yo cometí, se apodera de su cuerpo un demonio, que después dirige todas sus acciones, hasta que llega el término de su vida. En cuanto al alma, cae en esta cisterna; y por eso tal vez aparezca todavía en el mundo el cuerpo de esa sombra que está detrás de mí en este hielo. Debes conocerle, si es que acabas de llegar al Infierno: es \\\"ser\\\" Branca d\'Oria, el cual hace ya muchos años que fué encerrado aquí.\"},{\"heading\":false,\"text\":\"--Yo creo--le dije--que me engañas; porque Branca d\'Oria no ha muerto aún, y come, y bebe, y duerme, y va vestido.\"},{\"heading\":false,\"text\":\"--Aun no había caído Miguel Zanche--repuso aquél--en la fosa de Malebranche, allí donde hierve continuamente la pez, cuando Branca d\'Oria ya dejaba un diablo haciendo sus veces en su cuerpo y en el de uno de sus parientes, que fué cómplice de su traición. Extiende ahora la mano y ábreme los ojos.\"},{\"heading\":false,\"text\":\"Yo no se los abrí, y creo que fué una lealtad el ser con él desleal.\"},{\"heading\":false,\"text\":\"¡Ah, genoveses!, ¡hombres diversos de los demás en costumbres, y llenos de toda iniquidad!, ¿por qué no sois desterrados del mundo? Junto con el peor espíritu de la Romanía he encontrado uno de vosotros, que, por sus acciones, tiene el alma sumergida en el Cocito, mientras que su cuerpo aparece aún vivo en el mundo.\"}]},{\"title\":\"Infierno — canto trigesimocuarto\",\"blocks\":[{\"heading\":false,\"text\":\"\\\"Vexilla regis prodeunt inferni\\\"[44] hacia nosotros. Mira adelante--dijo mi Maestro,--a ver si lo distingues.\"},{\"heading\":false,\"text\":\"[44] \\\"Los estandartes del rey de los Infiernos avanzan.\\\"--Imitación del primer verso del himno que entona la Iglesia ante el estandarte de la Cruz, y que aquí aplica irónicamente Virgilio hablando de Lucifer.\"},{\"heading\":false,\"text\":\"Como aparece a lo lejos un molino, cuyas aspas hace girar el viento, cuando éste arrastra una espesa niebla, o cuando anochece en nuestro hemisferio, así me pareció ver a gran distancia un artificio semejante; y luego, para resguardarme del viento, a falta de otro abrigo, me encogí detrás de mi Guía. Estaba ya (con pavor lo digo en mis versos) en el sitio donde las sombras se hallaban completamente cubiertas de hielo, y se transparentaban como paja en vidrio. Unas estaban tendidas, otras derechas; aquéllas con la cabeza, éstas con los pies hacia abajo, y otras por fin con la cabeza tocando a los pies como un arco. Cuando mi Guía creyó que habíamos avanzado lo suficiente para enseñarme la criatura que tuvo el más hermoso rostro, me dejó libre el paso, e hizo que me detuviera.\"},{\"heading\":false,\"text\":\"--He ahí a Dite--me dijo--, y he aquí el lugar donde es preciso que te armes de fortaleza.\"},{\"heading\":false,\"text\":\"No me preguntes, lector, si me quedaría entonces helado y yerto; no quiero escribirlo, porque cuanto dijera sería poco. No quedé muerto ni vivo: piensa por ti, si tienes alguna imaginación, lo que me sucedería viéndome así privado de la vida sin estar muerto. El emperador del doloroso reino salía fuera del hielo desde la mitad del pecho: mi estatura era más proporcionada a la de un gigante, que la de uno de éstos a la longitud de los brazos de Lucifer: juzga, pues, cuál deba ser el todo que a semejante parte corresponda. Si fué tan bello como deforme es hoy, y osó levantar sus ojos contra su Creador, de él debe proceder sin duda todo mal. ¡Oh! ¡Cuánto asombro me causó, al ver que su cabeza tenía tres rostros! Uno por delante, que era de color bermejo: los otros dos se unían a éste sobre el medio de los hombros, y se juntaban por detrás en lo alto de la coronilla, siendo el de la derecha entre blanco y amarillo, según me pareció; el de la izquierda tenía el aspecto de los oriundos del valle del Nilo.[45] Debajo de cada rostro salían dos grandes alas, proporcionadas a la magnitud de tal pájaro; y no he visto jamás velas de buque comparables a ellas: no tenían plumas, pues eran por el estilo de las del murciélago; y se agitaban de manera que producían tres vientos, con los cuales se helaba todo el Cocito. Con seis ojos lloraba Lucifer, y por las tres barbas corrían sus lágrimas, mezcladas de baba sanguinolenta. Con los dientes de cada boca, a modo de agramadera, trituraba un pecador, de suerte que hacía tres desgraciados a un tiempo. Los mordiscos que sufría el de adelante no eran nada en comparación de los rasguños que le causaban las garras de Lucifer, dejándole a veces las espaldas enteramente desolladas.\"},{\"heading\":false,\"text\":\"[45] Los tres rostros de diversos colores significan las tres partes del mundo entonces conocidas. El rojo o bermejo, los europeos; el entre blanco y amarillo, los asiáticos; el negro, los africanos.--Los tres vientos de que habla luego simbolizan tal vez los tres vicios generadores de todo mal, a saber: la soberbia, la envidia y la avaricia.\"},{\"heading\":false,\"text\":\"--El alma que está sufriendo la mayor pena allá arriba--dijo el Maestro--es la de Judas Iscariote, que tiene la cabeza dentro de la boca de Lucifer y agita fuera de ella las piernas. De las otras dos, que tienen la cabeza hacia abajo, la que pende de la boca negra es Bruto; mira cómo se retuerce sin decir una palabra: el otro, que tan membrudo parece, es Casio. Pero se acerca la noche, y es hora ya de partir, pues todo lo hemos visto.\"},{\"heading\":false,\"text\":\"Según le plugo, me abracé a su cuello; aprovechó el momento y el lugar favorable, y cuando las alas estuvieron bien abiertas, agarróse a las velludas costillas de Lucifer, y de pelo en pelo descendió por entre el hirsuto costado y las heladas costras. Cuando llegamos al sitio en que el muslo se desarrolla justamente sobre el grueso de las caderas, mi Guía, con fatiga y con angustia, volvió su cabeza hacia donde aquél tenía las zancas, y se agarró al pelo como un hombre que sube, de modo que creí que volvíamos al Infierno.\"},{\"heading\":false,\"text\":\"--Sosténte bien--me dijo jadeando como un hombre cansado--; que por esta escalera es preciso partir de la mansión del dolor.\"},{\"heading\":false,\"text\":\"Después salió fuera por la hendedura de una roca, y me sentó sobre el borde de la misma, poniendo junto a mí su pie prudente. Yo levanté mis ojos, creyendo ver a Lucifer como le había dejado; pero vi que tenía las piernas en alto. Si debí quedar asombrado, júzguelo el vulgo, que no sabe qué punto es aquel por donde yo había pasado.\"},{\"heading\":false,\"text\":\"--Levántate--me dijo el Maestro--; la ruta es larga, el camino malo, y ya el Sol se acerca a la mitad de tercia.\"},{\"heading\":false,\"text\":\"El sitio donde nos encontrábamos no era como la galería de un palacio, sino una caverna de mal piso y escasa de luz.\"},{\"heading\":false,\"text\":\"--Antes que yo salga de este abismo, Maestro mío,--le dije al ponerme en pie--, dime algo que me saque de confusiones. ¿Dónde está el hielo, y cómo es que Lucifer está de ese modo invertido? ¿Cómo es que, en tan pocas horas, ha recorrido el Sol su carrera desde la noche a la mañana?\"},{\"heading\":false,\"text\":\"Me contestó:\"},{\"heading\":false,\"text\":\"--¿Te imaginas sin duda que estás aún al otro lado del centro, donde me cogí al pelo de ese miserable gusano que atraviesa el mundo? Allá te encontrabas mientras descendíamos; cuando me volví, pasaste el punto hacia el que converge toda la gravedad de la Tierra; y ahora estás bajo el hemisferio opuesto a aquel que cubre el árido desierto, y bajo cuyo más alto punto fué muerto el Hombre que nació y vivió sin pecado. Tienes los pies sobre una pequeña esfera, que por el otro lado mira a la Judesca. Aquí amanece, cuando allí anochece; y éste de cuyo pelo nos hemos servido como de una escala, permanece aún fijo del mismo modo que antes. Por esta parte cayó del cielo; y la tierra, que antes se mostraba en este lado, aterrorizada al verle, se hizo del mar un velo, y se retiró hacia nuestro hemisferio; y quizá también huyendo de él, dejó aquí este vacío la que aparece por acá formando un elevado monte.\"},{\"heading\":false,\"text\":\"Hay allá abajo una cavidad que se aleja tanto de Lucifer cuanta es la extensión de su tumba; cavidad que no puede reconocerse por la vista, sino por el rumor de un arroyuelo, que desciende por el cauce de un peñasco que ha perforado con su curso sinuoso y poco pendiente. Mi Guía y yo entramos en aquel camino oculto, para volver al mundo luminoso; y sin concedernos el menor descanso, subimos, él delante y yo detrás, hasta que pude ver por una abertura redonda las bellezas que contiene el Cielo, y por allí salimos para volver a ver las estrellas.\"},{\"heading\":false,\"text\":\"_PURGATORIO_\"}]},{\"title\":\"Purgatorio — canto primero\",\"blocks\":[{\"heading\":false,\"text\":\"Ahora la navecilla de mi ingenio, que deja en pos de sí un mar tan cruel, desplegará las velas para navegar por mejores aguas; y cantaré aquel segundo reino, donde se purifica el espíritu humano, y se hace digno de subir al Cielo. Resucite aquí, pues, la muerta poseía, ¡oh santas Musas!, pues que soy vuestro; y realce Calíope mi\"},{\"heading\":false,\"text\":\"desgraciadas Urracas, que desesperaron de alcanzar su perdón.[46]\"},{\"heading\":false,\"text\":\"[46] Las nueve hijas de Piero, rey de Pella en Macedonia, que habiendo desafiado a las Musas, fueron vencidas y transformadas en urracas. Las mismas Musas son llamadas Piérides.\"},{\"heading\":false,\"text\":\"Un suave color de zafiro oriental, contenido en el sereno aspecto del aire puro hasta el primer cielo, reapareció delicioso a mi vista en cuanto salí de la atmósfera muerta, que me había contristado los ojos y el corazón. El bello planeta que convida a amar hacía sonreír todo el Oriente, desvaneciendo al signo de Piscis, que seguía en pos de él. Me volví a la derecha, y dirigiendo mi espíritu hacia el otro polo, distinguí cuatro estrellas únicamente vistas por los primeros humanos. El cielo parecía gozar con sus resplandores. ¡Oh Septentrión, sitio verdaderamente viudo, pues que te ves privado de admirarlas! Cuando cesé en su contemplación, volvíme un tanto hacia el otro polo, de donde el Carro había desaparecido, y vi cerca de mí un anciano solo, y digno, por su aspecto, de tanta veneración, que un padre no puede inspirarla mayor a su hijo. Llevaba una larga barba, canosa como sus cabellos, que le caía hasta el pecho, dividida en dos mechones. Los rayos de las cuatro luces santas rodeaban de tal resplandor su rostro, que lo veía como si hubiese tenido el Sol ante mis ojos.\"},{\"heading\":false,\"text\":\"--¿Quiénes sois vosotros que, contra el curso del tenebroso río, habéis huído de la prisión eterna?--dijo el anciano, agitando su barba venerable--. ¿Quién os ha guiado, o quién os ha servido de antorcha para salir de la profunda noche, que hace sea continuamente negro el valle infernal? ¿Así se han quebrantado las leyes del abismo? ¿O se ha dado quizás en el Cielo un nuevo decreto, que os permite, a pesar de estar condenados, venir a mis grutas?\"},{\"heading\":false,\"text\":\"Entonces mi Guía me indicó, por medio de sus palabras, de sus gestos y sus miradas, que debía mostrarme respetuoso, doblar la rodilla e inclinar la vista. Después le respondió:\"},{\"heading\":false,\"text\":\"--No vine por mi deliberación, sino porque una mujer, descendida del cielo, me ha rogado que acompañe y ayude a éste. Pero ya que es tu voluntad que te expliquemos más ampliamente cuál sea nuestra verdadera condición, la mía no puede rehusarte nada. Este no ha visto aún su última noche; pero por su locura estuvo tan cerca de ello, que le quedaba poquísimo tiempo de vida. Así es que, según he dicho, fuí enviado a su encuentro para salvarle, y no había otro camino más que este, por el cual me he aventurado. Hele dado a conocer todos los réprobos, y ahora pretendo mostrarle aquellos espíritus que se purifican bajo tu jurisdicción. Sería largo de referir el modo como le he traído hasta aquí: de lo alto baja la virtud que me ayuda a conducirle para verte y oírte. Dígnate, pues, acoger su llegada benignamente: va buscando la libertad, que es tan amada, como lo sabe el que por ella desprecia la vida. Bien lo sabes tú, que por ella no te pareció amarga la muerte en Utica, donde dejaste tu cuerpo, que tanto brillará en el gran día. No han sido revocados por nosotros los eternos decretos; pues éste vive, y Minos no me tiene en su poder, sino que pertenezco al círculo donde están los castos ojos de tu Marcia, que parece rogarte aún, ¡oh santo corazón!, que la tengas por compañera y por tuya. En nombre, pues, de su amor, accede a nuestra súplica, y déjanos ir por tus siete reinos: le manifestaré mi agradecimiento hacia ti si permites que allá abajo se pronuncie tu nombre.\"},{\"heading\":false,\"text\":\"--Marcia fué tan agradable a mis ojos mientras pertenecí a la Tierra--dijo él entonces--, que obtuvo de mí cuantas gracias quiso; ahora que habita a la otra parte del mal río, no puedo ya conmoverme a causa de la ley que se me impuso cuando salí fuera de mi cuerpo. Pero si una mujer del cielo te anima y te dirige, según dices, no tienes necesidad de tan laudatorios ruegos; me basta conque me supliques en su nombre. Vé, pues, y haz que ése se ciña con un junco sin hojas, y lávale el rostro de modo que quede borrada en él toda mancha; porque no conviene que se presente con la vista ofuscada ante el primer ministro, que es de los del Paraíso. Esa pequeña isla que ves allá abajo produce, en torno suyo y por donde la combaten las olas, juncos en su tierra blanda y limosa. Ninguna clase de plantas que eche hojas o que se endurezca puede existir ahí, porque le sería imposible doblegarse a los embates de las olas. Después no volváis por esta parte; el sol naciente os indicará el modo de encontrar la más fácil subida del monte.\"},{\"heading\":false,\"text\":\"Al decir esto desapareció. Me levanté sin hablar, me coloqué junto a mi Guía, y fijé en él los ojos. Entonces empezó a hablarme de este modo:\"},{\"heading\":false,\"text\":\"--Hijo mío, sigue mis pasos: volvamos atrás; porque esta llanura va descendiendo siempre hasta su último límite.\"},{\"heading\":false,\"text\":\"El alba vencía ya al aura matutina, que huía delante de ella, y desde lejos pude distinguir las ondulaciones del mar. Ibamos por la llanura solitaria, como el que busca la senda perdida, y cree caminar en vano hasta que logra encontrarla. Cuando llegamos a un sitio en que el rocío resiste al calor del sol, y protegido por la sombra, se desvanece poco a poco, puso mi Maestro suavemente sus dos manos abiertas sobre la fresca hierba; y yo, comprendiendo su intento, le presenté mis mejillas cubiertas aún de lágrimas, y en las que por su mediación apareció de nuevo el color de que las privó el Infierno.\"},{\"heading\":false,\"text\":\"Llegamos después a la playa desierta, que no vió nunca navegar por sus aguas a hombre alguno capaz de salir de ellas. Allí me hizo un cinturón, según la voluntad del otro; y, ¡oh maravilla!, cuando arrancó la humilde planta, volvió otra a renacer súbitamente en el mismo sitio de donde había arrancado aquélla.\"}]},{\"title\":\"Purgatorio — canto segundo\",\"blocks\":[{\"heading\":false,\"text\":\"Ya estaba el Sol tocando al horizonte, cuyo círculo meridiano cubre a Jerusalén con su punto más elevado; y ya la noche, formando un arco en oposición a él, salía fuera del Ganges con las Balanzas que se le caen de las manos cuando supera en extensión al día; de modo que allí, donde yo me encontraba, las blancas y sonrosadas mejillas de la bella Aurora, según iba creciendo, se tornaban de color de oro. Estábamos aún en la orilla del mar, como quien piensa en el camino que debe seguir, y anda con el deseo, sin que el cuerpo se mueva. Cuando he aquí que, así como, al amanecer, por efecto de los densos vapores, se ve a Marte enrojecido hacia Poniente sobre las aguas marinas, de igual modo me apareció--¡ojalá pudiese verla otra vez!--una luz, la cual venía tan rápidamente por el mar, que ningún vuelo sería comparable a su celeridad. Un solo momento aparté de ella la vista para interrogar a mi Guía, y al punto volví a verla mucho más voluminosa y brillante; distinguiendo luego a cada lado de la misma una cosa blanca, sin saber lo que era, debajo de la cual se descubría poco a poco otro objeto igualmente blanco. Aun no había pronunciado una palabra mi Maestro, cuando se vió que las primeras formas blancas eran alas; y entonces, habiendo conocido bien al gondolero, exclamó:\"},{\"heading\":false,\"text\":\"--Dobla, dobla pronto la rodilla: he aquí el ángel de Dios; une las manos: nunca verás semejantes ministros del Señor. Mira cómo desdeña los medios humanos, pues no necesita remo, ni otras velas que sus alas, entre tan apartadas orillas. Mira cómo las tiene elevadas hacia el cielo, agitando el aire con las eternas plumas, que no se mudan como el cabello de los mortales.\"},{\"heading\":false,\"text\":\"Cuanto más se acercaba a nosotros el ave divina, más brillante aparecía: por lo cual, no pudiendo resistir su resplandor mis ojos, los incliné; y aquél se dirigió hacia la orilla en un esquife airoso y ligero, que apenas se sumergía un poco en el agua. El celestial barquero estaba en la popa, y la bienaventuranza parecía estar escrita en su semblante. Más de cien espíritus, sentados en la barquilla, cantaban a coro: \\\"In exitu Israel de Ægipto\\\" y todo lo demás que sigue de este salmo. El ángel les hizo la señal de la santa cruz, a cuya señal se arrojaron todos a la playa, y él se alejó con la misma velocidad con que había venido. La turba que dejó allí parecía llena de estupor en tal sitio, mirando y remirando en torno suyo, como el que descubre cosas que no ha visto nunca. El Sol, que había arrojado con sus brillante saetas al signo de Capricornio del centro del cielo, irradiaba por todas partes el día, cuando los recién llegados alzaron la frente hacia nosotros, diciéndonos:\"},{\"heading\":false,\"text\":\"--Si lo sabéis, indicadnos el camino que conduce a la montaña.\"},{\"heading\":false,\"text\":\"Virgilio respondió:\"},{\"heading\":false,\"text\":\"--¿Por ventura creéis que conocemos este sitio? Somos aquí tan nuevos como vosotros, y hemos llegado a él poco antes por otro camino tan rudo y áspero, que el subir esta montaña será para nosotros ahora cosa de juego.\"},{\"heading\":false,\"text\":\"Las almas, que advirtieron, por mi respiración, que yo estaba aún vivo, palidecieron de asombro; y así como se agolpa la gente en derredor del mensajero coronado de olivo para oír sus noticias, sin temor de empujarse y pisarse unos a otros, así se agolparon en torno mío todas aquellas almas afortunadas, olvidando casi su deseo de ir a embellecerse. Vi una de ellas, que se adelantó para abrazarme con tales muestras de afecto, que me movió a hacer lo mismo con ella; pero, ¡oh sombras vanas, excepto para la vista! Tres veces quise rodearla con mis brazos, y otras tantas volvieron éstos a caer solos sobre mi pecho. Creo que la admiración debió pintarse en mi rostro; porque la sombra sonrió y se retiró; y yo, siguiéndola, continué avanzando. Me dijo con voz suave que me detuviese; conocí entonces quién era, y habiéndole rogado que se parase un momento para hablarme, respondióme:\"},{\"heading\":false,\"text\":\"--Lo mismo que te amaba con mi cuerpo mortal, te amo también desprendido de él; por eso me detengo; pero tú ¿por qué vienes aquí?\"},{\"heading\":false,\"text\":\"--Casella mío, hago este viaje para volver al mundo de los vivos, donde permanezco aún; pero a ti, ¿cómo es que se te ha negado por tanto tiempo el venir a este sitio?\"},{\"heading\":false,\"text\":\"Me respondió:\"},{\"heading\":false,\"text\":\"--Si aquel que conduce a quien y cómo le place me ha negado muchas veces este pasaje, no se ha cometido conmigo ninguna injusticia; porque es justa la voluntad a quien obedece. En verdad, de tres meses a esta parte ha recogido sin oposición a cuantos han querido entrar en su nave: así es que yo, que me encontraba en la playa donde el Tíber se mezcla con las saladas ondas del mar, fuí acogido benignamente por él. A la embocadura de aquel río dirige ahora su vuelo; pues allí se reúnen siempre los que no descienden hacia el Aqueronte.\"},{\"heading\":false,\"text\":\"Y yo dije:\"},{\"heading\":false,\"text\":\"--Si alguna nueva ley no te quita la memoria o el uso de aquellos cantos amorosos, que solían calmar todos mis deseos, dígnate consolar un poco mi alma, que viniendo aquí con su cuerpo, se ha angustiado tanto.\"},{\"heading\":false,\"text\":\"\\\"Amor, que dentro de mi mente habla,\\\"[47] empezó él a cantar tan dulcemente, que su dulzura aún resuena en mi corazón. Mi Maestro, y yo, y las sombras que allí estaban, parecíamos tan contentos, como si no tuviéramos otra cosa en que pensar. Estábamos absortos y atentos a sus notas, cuando apareció el venerable anciano exclamando:\"},{\"heading\":false,\"text\":\"--¿Qué es esto, espíritus perezosos? ¿Qué negligencia, qué demora es ésta? Corred al monte a purificaros de vuestros pecados, que no permiten que Dios se os manifieste.\"},{\"heading\":false,\"text\":\"[47] \\\"Amor, che nella mente mi ragiona\\\"... Así empieza la canción de Dante señalada con el número XV en \\\"Il Canzionere\\\" anotado por Pedro Fraticelli (Florencia, 1911).\"},{\"heading\":false,\"text\":\"Del mismo modo que las palomas, cuando están reunidas en torno a su alimento, cogiendo el grano y quietas, sin hacer oír sus acostumbrados arrullos, si acontece algo que las asuste, abandonan súbitamente la comida, porque las asalta un cuidado mayor, así vi yo aquellas almas recién llegadas abandonar el canto y desbandarse por la costa, como quien corre sin saber adónde va; y no menos rápidamente huimos también nosotros.\"}]},{\"title\":\"Purgatorio — canto tercero\",\"blocks\":[{\"heading\":false,\"text\":\"Mientras la repentina fuga dispersaba por la campiña aquellas almas, que se volvían hacia la montaña donde la razón divina las aguija, me acerqué a mi fiel compañero; porque, ¿cómo hubiera podido sin él seguir mi viaje?, ¿quién me habría sostenido al subir por la montaña? Me pareció que mi Guía estaba por sí mismo arrepentido de su flaqueza. ¡Oh conciencia digna y pura!, ¡qué amargo roedor es para ti la más pequeña falta! Cuando sus pies cesaron de caminar con aquella precipitación que se aviene mal con la majestad de la persona, mi mente, desechando el pensamiento que la inquietaba, concentró su atención, como deseosa de recibir las nuevas impresiones; y me puse a contemplar el monte más alto de cuantos hacia el Cielo se elevan sobre las aguas. El Sol, que a mis espaldas despedía su rubicunda luz, quedaba interceptado por mi cuerpo, en el que se apoyaban sus rayos; y cuando vi que sólo delante de mí se obscurecía la tierra, volvíme de lado, temeroso de haber sido abandonado. Mi Protector entonces empezó a decirme, vuelto hacia mí:\"},{\"heading\":false,\"text\":\"--¿Por qué desconfías aún? ¿Crees que no estoy contigo, y que ya no te guío? Ahora es ya por la tarde allá donde está sepultado el cuerpo, dentro del cual hacía yo sombra. Nápoles lo posee, porque lo han quitado de Brindis. Si, pues, ninguna sombra se proyecta delante de mí, no debes admirarte de ello más que de ver cómo los cielos no interceptan unos a otros el paso de sus luces. La Virtud divina hace que semejantes cuerpos sean aptos para sufrir tormentos, calor y frío; mas no ha querido revelarnos cómo opera tal maravilla. Insensato es el que espera que nuestra razón pueda recorrer las infinitas vías de que dispone el que es una substancia en tres personas. Seres humanos, contentaos con el \\\"quia;\\\"[48] pues si os fuera dable verlo todo, no habría sido necesario que pariese María; y habéis visto desearlo en vano a tales hombres, que, a ser posible, hubieran satisfecho ese deseo, el cual forma su eterno suplicio: hablo de Aristóteles, de Platón y otros muchos.\"},{\"heading\":false,\"text\":\"[48] Según Aristóteles, la demostración es de dos clases: una llamada propter quod, que es cuando los efectos se deducen de las causas, y otra llamada quia, y es cuando las causas se deducen de los efectos por lo cual este período debe interpretarse del modo siguiente: Contentaos, ¡oh humanos!, con las demostraciones que se pueden deducir de los efectos, por los cuales se viene en conocimiento de sus causas, y no pretendáis conocer más de lo que los hechos os demuestran: que en las cosas que son superiores a la inteligencia humana y a la fuerza de la razón, se ejercita la fe.\"},{\"heading\":false,\"text\":\"En este punto, inclinó la frente sin decir nada más, y quedó como turbado. Llegamos en tanto al pie del monte, cuyas rocas encontramos tan escarpadas, que las piernas más ágiles nos hubieran sido inútiles. El camino más desierto, el más áspero entre Lerici y Turbía, es, comparado con aquél, una rampa suave y anchurosa.\"},{\"heading\":false,\"text\":\"--¿Quién sabe ahora--dijo mi Maestro deteniendo sus pasos--hacia qué mano es accesible la costa, de modo que pueda subir el que no tiene alas?\"},{\"heading\":false,\"text\":\"Y mientras él tenía los ojos bajos, meditando qué camino seguiríamos, y yo miraba hacia arriba alrededor de las rocas, apareció por la izquierda una multitud de almas, que se dirigían hacia nosotros, aunque no lo parecía; tanta era la lentitud con que caminaban.\"},{\"heading\":false,\"text\":\"--Levanta los ojos--dije a mi Maestro--; he aquí quien nos podrá aconsejar, si es que no puedes aconsejarte a ti mismo.\"},{\"heading\":false,\"text\":\"Miróme entonces, y con rostro franco respondió:\"},{\"heading\":false,\"text\":\"--Vamos allá, pues ellos vienen muy despacio; y tú no pierdas la esperanza, hijo querido.\"},{\"heading\":false,\"text\":\"Habríamos andado mil pasos, y aun distaba de nosotros aquella muchedumbre tanto espacio cuanto podría recorrer una piedra lanzada por un buen hondero, cuando se arrimaron todos a los duros peñascos de la escarpada orilla, y permanecieron firmes y apretados entre sí, como se detiene a mirar aquel que duda.\"},{\"heading\":false,\"text\":\"--¡Oh muertos en la gracia de Dios, espíritus ya elegidos!--empezó a decir Virgilio--; por aquella paz que, según creo, esperáis todos vosotros, decidme por qué parte declina esta montaña, de modo que sea posible ascender a ella; pues al que mejor conoce el valor del tiempo, le es más desagradable perderlo.\"},{\"heading\":false,\"text\":\"Como las ovejas que salen de su redil una a una, dos a dos y tres y tres, mientras las otras se detienen tímidamente, inclinando hacia la tierra sus ojos y su hocico, y lo mismo que hace la primera hacen las demás, deteniéndose a su lado si se detiene, sencillas y tranquilas, y sin darse cuenta de por qué lo hacen, así vi yo moverse para venir hacia nosotros las primeras almas de aquella temerosa y afortunada grey, de rostro púdico y de honesto continente. Cuando vieron que la luz se interrumpía en el suelo a mi mano derecha, de modo que se proyectaba la sombra desde mí a la gruta, se detuvieron y aun retrocedieron algún tanto, y todos los que venían detrás, sin saber por qué, hicieron lo mismo.\"},{\"heading\":false,\"text\":\"--Sin que me lo preguntéis, os confieso que este que aquí veis es un cuerpo humano; por cuya causa la luz del Sol aparece cortada en el suelo. No os asombréis; pero creed que si pretende trepar esta escarpada costa, lo hace inducido por virtud celestial.\"},{\"heading\":false,\"text\":\"Así habló mi Maestro; y aquella noble multitud nos dijo:\"},{\"heading\":false,\"text\":\"--Pues volveos atrás y caminad delante de nosotros.\"},{\"heading\":false,\"text\":\"Y al mismo tiempo nos hacían señas con el dorso de las manos. Uno de ellos exclamó:\"},{\"heading\":false,\"text\":\"--Quienquiera que seas, andando como vas, vuelve el rostro hacia mí, y procura recordar si me has visto en el mundo alguna vez.\"},{\"heading\":false,\"text\":\"Yo me volví hacia él, y le miré fijamente: era rubio, hermoso y de gentil aspecto; pero tenía la ceja partida de un golpe. Cuando le manifesté humildemente que no le había visto nunca, me dijo:\"},{\"heading\":false,\"text\":\"--¡Mira, pues!\"},{\"heading\":false,\"text\":\"Y enseñóme una herida en la parte superior de su pecho. Después añadió sonriendo:\"},{\"heading\":false,\"text\":\"--Yo soy Manfredo, nieto de la emperatriz Constanza: por lo cual te ruego, que cuando vuelvas a la Tierra, vayas a visitar a mi graciosa hija, madre del honor de Sicilia y de Aragón, y le digas la verdad, si es que se ha dicho lo contrario. Después de tener atravesado mi cuerpo por dos heridas mortales, me volví llorando hacia Aquél, que voluntariamente perdona. Mis pecados fueron horribles; pero la bondad infinita tiene tan largos los brazos, que recibe a todo el que se vuelve hacia ella. Si el Pastor de Cosenza, que fué enviado por Clemente para darme caza, hubiese leído bien en aquella página de Dios, mis huesos estarían aún en la cabeza del puente, cerca de Benevento, bajo la salvaguardia de las pesadas piedras. Ahora los moja la lluvia; el viento los impele fuera del reino, casi a la orilla del Verde, donde los hizo transportar con cirios apagados. Pero por su maldición no se pierde el amor de Dios de tal modo, que no vuelva nunca, mientras reverdezca la flor de la esperanza. Es verdad que el que muere contumaz para con la santa Iglesia, por más que al fin se arrepienta, debe estar en la parte exterior de esta montaña un espacio de tiempo treinta veces mayor del que vivió en contumacia, a menos que no se abrevie la duración de este decreto merced a eficaces oraciones. Calcula, pues, lo dichoso que puedes hacerme, revelando a mi buena Constanza cómo me has visto, y la prohibición que pesa sobre mí, que puede alzarse por los ruegos de los que existen allá arriba.\"}]},{\"title\":\"Purgatorio — canto cuarto\",\"blocks\":[{\"heading\":false,\"text\":\"Cuando por efecto del placer o del dolor de que se siente afectada alguna de nuestras facultades, el alma entera se concentra en esa facultad, parece que no atienda a ninguna otra; y esto demuestra el error de los que creen que en nosotros arde un alma sobre otra alma. Por eso mismo, cuando se oye o ve alguna cosa que absorbe fuertemente el alma en su contemplación, el tiempo se desliza sin que el hombre se aperciba de ello; porque una es la facultad que escucha, y otra la que cautiva por completo el alma: ésta está como atada; aquella es libre. Yo adquirí una prueba de esta verdad oyendo y admirando a aquel espíritu; pues había el Sol ascendido cincuenta grados sobre el horizonte, sin que yo lo echase de ver, cuando llegamos a un punto en que las almas exclamaron a una voz: \\\"Aquí está el objeto de vuestra demanda.\\\"\"},{\"heading\":false,\"text\":\"Cualquier portillo de los que suele tapar el aldeano con un manojo de espinos, cuando maduran las uvas, es mayor que el sendero por donde subimos solos mi Maestro y yo, cuando la multitud de almas se separó de nosotros. Bastan los pies para ir a San Leo, para bajar a Noli, para ascender hasta la elevada cumbre de Bismantua; pero aquí es preciso que el hombre vuele: quiero decir, como volaba yo, conducido por las ligeras alas y por las plumas de un gran deseo, detrás de Aquel que reanimaba mi esperanza y me iluminaba. Ibamos subiendo por el sendero excavado en el peñasco, cuyas quebradas rocas nos estrechaban por ambos lados, y el suelo que pisábamos nos obligaba a ayudarnos con pies y manos. Cuando llegamos a sitio descubierto, sobre el rellano de la alta base del monte, dije:\"},{\"heading\":false,\"text\":\"--Maestro mío, ¿qué camino seguiremos?\"},{\"heading\":false,\"text\":\"Y él me contestó:\"},{\"heading\":false,\"text\":\"--No des ningún paso hacia abajo: prosigue subiendo detrás de mí hacia la cima de este monte, hasta que se nos aparezca algún experto guía.\"},{\"heading\":false,\"text\":\"La cima era tan alta, que no podía alcanzarla la vista, y la subida mucho más empinada que la línea que divide en dos partes el cuadrante. Yo estaba ya cansado, y entonces exclamé:\"},{\"heading\":false,\"text\":\"--¡Oh amado Padre! Vuélvete, y mira que me quedo aquí solo, si no te detienes.\"},{\"heading\":false,\"text\":\"--Hijo mío, haz por llegar hasta aquel punto--respondió mostrándome una prominencia que rodeaba por aquel lado toda la montaña.\"},{\"heading\":false,\"text\":\"Sus palabras me aguijonearon de tal modo, que me esforcé cuanto pude trepando hasta donde él estaba, tanto que puse mis plantas sobre aquella especie de cornisa. Nos sentamos allí ambos, vueltos hacia Levante, por cuyo lado habíamos subido; pues suele agradar la contemplación del camino que uno ha hecho. Primeramente dirigí los ojos al fondo, después los levanté hacia el Sol, y me admiraba de que éste nos iluminase por la izquierda.\"},{\"heading\":false,\"text\":\"El Poeta observó que me quedaba estupefacto, mirando el carro de la luz que iba a pasar entre nosotros y el Aquilón; por lo cual me dijo:\"},{\"heading\":false,\"text\":\"--Si Cástor y Pólux estuvieran en compañía de aquel espejo, que ilumina al mundo tanto por arriba como por abajo, verías al Zodíaco refulgente girar más próximo aún a las Osas, a no ser que saliese fuera de su antiguo camino. Y si quieres comprender cómo puede suceder esto, reconcentra tu pensamiento, y considera que el monte Sion está situado sobre la Tierra, relativamente a éste, de modo que ambos tienen un mismo horizonte y diferentes hemisferios; por lo cual, si tu inteligencia te permite discernir con claridad, verás cómo el camino que por su mal no supo recorrer Faetón, debe ir necesariamente por un lado de este monte, al paso que va por el opuesto lado de aquel otro.\"},{\"heading\":false,\"text\":\"--En verdad. Maestro mío--le contesté--, nunca había visto tan claramente como ahora distingo estas cosas, para cuya comprensión no me parecía bastante apto mi ingenio. Por las razones que me has dado entiendo que el círculo intermedio del primer móvil, llamado Ecuador en alguna ciencia, y que permanece siempre entre el Sol y el invierno, dista de aquí tanto hacia el Septentrión, cuanto los Hebreos lo veían hacia la parte cálida. Pero, si te place, quisiera saber cuanto hemos de andar aún; pues el monte se eleva más de lo que puede alcanzar mi vista.\"},{\"heading\":false,\"text\":\"--Esta montaña es tal--me respondió--, que siempre cuesta trabajo empezar a subirla, y cuanto más va para arriba es menos fatigoso. Cuando te parezca tan suave, que subas ligeramente por ella como van por el agua las naves, entonces habrás llegado al fin de este sendero: espera, pues, a conseguirlo para descansar de tu fatiga. Y no respondo más, pues sólo esto tengo por cierto.\"},{\"heading\":false,\"text\":\"Cuando hubo terminado de decir estas palabras, resonó cerca de nosotros una voz que decía: \\\"Quizá te veas precisado antes a sentarte.\\\" Al sonido de aquella voz, volvímonos, y vimos a la izquierda un gran peñasco, en el que no habíamos reparado antes ninguno de los dos. Nos dirigimos hacia allí, donde estaban algunos espíritus reposando a la sombra detrás del peñasco, como quien lo hace por indolencia. Uno de ellos, que me parecía cansado, estaba sentado con las rodillas abrazadas, reposando sobre ellas su cabeza.\"},{\"heading\":false,\"text\":\"--¡Oh amado Señor mío!--dije entonces--: contempla a ése, que se muestra más negligente que si fuese hermano de la pereza.\"},{\"heading\":false,\"text\":\"Entonces se volvió hacia nosotros, y nos examinó, dirigiendo su mirada por encima de los muslos, y diciendo:\"},{\"heading\":false,\"text\":\"--Vé, pues, allá arriba, tú que eres tan valiente.\"},{\"heading\":false,\"text\":\"Conocí entonces quién era; y aquella fatiga que agitaba todavía un poco mi respiración, no me impidió acercarme a él. Cuando estuve a su lado, alzó apenas la cabeza, diciendo:\"},{\"heading\":false,\"text\":\"--¿Has comprendido bien por qué el Sol dirige su carro por tu izquierda?\"},{\"heading\":false,\"text\":\"Sus perezosos movimientos y sus lacónicas palabras hicieron asomar una sonrisa a mis labios; después dije:\"},{\"heading\":false,\"text\":\"--Belacqua, ahora ya no me conduelo de ti: pero dime, ¿por qué estás aquí sentado? ¿Esperas algún guía, o es que has vuelto a tus antiguas costumbres?\"},{\"heading\":false,\"text\":\"Contestóme:\"},{\"heading\":false,\"text\":\"--¡Oh, hermano! ¿Para qué he de ir arriba, si no ha de permitirme llegar al sitio de la expiación el Angel de Dios, que está sentado a su puerta? Antes que yo entre por ella, es necesario que el cielo dé tantas vueltas en torno mío, cuantas dió en el transcurso de mi vida, por haber aplazado los buenos suspiros hasta la hora de mi muerte; a no ser que me auxilie una plegaria, que se eleve de un corazón que viva en la gracia. ¿De qué sirven las demás, si no han de ser oídas en el cielo?\"},{\"heading\":false,\"text\":\"Ya el Poeta subía delante de mí diciendo:\"},{\"heading\":false,\"text\":\"--No te detengas más: mira que el Sol toca al Meridiano, y la Noche cubre ya con su pie la costa de Marruecos.\"}]},{\"title\":\"Purgatorio — canto quinto\",\"blocks\":[{\"heading\":false,\"text\":\"Me había alejado ya de aquellas sombras, y seguía las huellas de mi Guía, cuando detrás de mí, y señalándome con el dedo, gritó una de ellas:\"},{\"heading\":false,\"text\":\"--Mirad; no se nota que el Sol brille a la izquierda de aquel de más abajo, que marcha al parecer como un vivo.\"},{\"heading\":false,\"text\":\"Al oír estas palabras, volví la cabeza, y vi que las sombras miraban con admiración, no solamente a mí, sino también a la luz interceptada por mi cuerpo.\"},{\"heading\":false,\"text\":\"--¿Por qué se turba tanto tu ánimo--dijo el Maestro--, que así acortas el paso? ¿Qué te importa lo que allí murmuran? Sígueme, y deja que hable esa gente. Sé firme como una torre, cuya cúspide no se doblega jamás al embate de los vientos: el hombre en quien bulle pensamiento sobre pensamiento, siempre aleja de sí el fin que se propone; porque el uno debilita la actividad del otro.\"},{\"heading\":false,\"text\":\"¿Qué otra cosa podría yo contestarle sino: \\\"Ya voy?\\\" Así lo hice, cubierto algún tanto de aquel color que hace a veces al hombre digno de perdón. En tanto, de través por la cuesta venían hacia nosotros algunas almas entonando, versículo a versículo, el \\\"Miserere.\\\" Cuando observaron que yo no daba paso al través de mi cuerpo a los rayos solares, cambiaron su canto en un \\\"¡Oh!\\\" ronco y prolongado: y dos de ellas, a guisa de mensajeros, corrieron a nuestro encuentro, diciendo:\"},{\"heading\":false,\"text\":\"--Hacednos sabedores de vuestra condición.\"},{\"heading\":false,\"text\":\"Mi Maestro contestó:\"},{\"heading\":false,\"text\":\"--Podéis iros y referir a los que os han enviado, que el cuerpo de éste es de verdadera carne. Si se han detenido, según me figuro, por ver su sombra, bastante tienen con tal respuesta: hónrenle, porque podrá serles grato.\"},{\"heading\":false,\"text\":\"Jamás he visto a prima noche los vapores encendidos, ni a puesta del Sol las exhalaciones de Agosto, hendir el Cielo sereno tan rápidamente como corrieron aquellas almas hacia sus compañeras; y una vez allí, regresaron adonde estábamos, juntas con las demás, como escuadrón que corre a rienda suelta.\"},{\"heading\":false,\"text\":\"--Esa gente que se agolpa hacia nosotros es numerosa--dijo el Poeta--, y vienen a dirigirte alguna súplica: tú, sin embargo, sigue adelante, y escucha mientras andas.\"},{\"heading\":false,\"text\":\"--¡Oh alma, que, para llegar a la felicidad, vas con los miembros con que naciste!--venían gritando--: modera un poco tu paso. Repara si has conocido a alguno de nosotros, de quien puedas llevar allá noticias. ¡Ah! ¿Por qué te vas? ¿Por qué no te detienes? Todos hemos terminado nuestros días por muerte violenta, y fuimos pecadores hasta la última hora: entonces la luz del Cielo iluminó nuestra razón tan bien, que, arrepentidos y perdonados, abandonamos la vida en la gracia de Dios, que nos abrasa por el gran deseo que tenemos de verle.\"},{\"heading\":false,\"text\":\"Yo les contesté:\"},{\"heading\":false,\"text\":\"--Aun cuando no reconozco las desfiguradas facciones de ninguno de vosotros, no obstante, si deseáis de mí algo que me sea posible, espíritus bien nacidos, yo lo haré por aquella paz que se me hace buscar de mundo en mundo, siguiendo los pasos de este Guía.\"},{\"heading\":false,\"text\":\"Uno de ellos empezó diciendo:\"},{\"heading\":false,\"text\":\"--Todos confiamos en tu benevolencia sin necesidad de que lo jures, a no ser que la impotencia destruya tu buena voluntad. Yo, que hablo solo antes que los demás, te ruego que si ves alguna vez aquel país que se extiende entre la Romanía y el de Carlos,[49] me concedas en Fano el dón de tus preces, a fin de que los buenos rueguen allí por mí, de modo que yo pueda purgar mis graves pecados. De allí fuí yo: pero las profundas heridas por donde salió la sangre en la que me asentaba, me fueron hechas en el territorio de los Antenóridas,[50] donde creía encontrarme más seguro. El de Este lo ordenó, porque me odiaba mucho más de lo que le permitía la justicia; pero si yo hubiese huído hacia la Mira, cuando llegué a Oriaco, aún estaría allá donde se respira: corrí al pantano, donde las cañas y el lodo me embarazaron tanto, que caí, y vi formarse en tierra un lago con la sangre de mis venas.\"},{\"heading\":false,\"text\":\"[49] La Marca de Ancona, gobernada por Carlos de Anjou.\"},{\"heading\":false,\"text\":\"[50] Padua, fundada por Antenor.\"},{\"heading\":false,\"text\":\"Después me dijo otro:\"},{\"heading\":false,\"text\":\"--¡Ay! Así se cumpla el deseo que te conduce a esta elevada montaña, dígnate auxiliar al mío con obras de piedad. Yo fuí de Montefeltro, y soy Buonconte. Ni Juana ni los otros se cuidan de mí; por lo cual voy entre éstos con la cabeza baja.\"},{\"heading\":false,\"text\":\"Le pregunté:\"},{\"heading\":false,\"text\":\"--¿Qué violencia o qué aventura te sacó fuera de Campaldino, que no se supo nunca donde está tu sepultura?\"},{\"heading\":false,\"text\":\"--¡Oh!--me respondió--; al pie del Casentino corre un río llamado Archiano, que nace en el Apenino encima del Ermo. Allí donde pierde su nombre, llegué yo con el cuello atravesado, huyendo a pie y ensangrentando la llanura. Allí perdí la vista, y mi última palabra fué el nombre de María; allí caí, y no quedó más que mi carne. Te diré la verdad, y tú la referirás entre los vivos: el ángel de Dios me cogió, y el del Infierno gritaba: \\\"¡Oh tú, venido del Cielo! ¿Por qué me lo quitas? Te llevas la parte eterna de éste por una pequeña lágrima que me le arrebata; pero yo trataré de diferente modo la otra parte.\\\" Tú sabes bien cómo se condensa en el aire ese húmedo vapor, que se convierte en lluvia en cuanto sube hasta donde le sorprende el frío: pues bien, el demonio, juntando a su entendimiento aquella malevolencia que sólo procura hacer daño, con el poder inherente a su naturaleza, agitó el vapor y el viento. En cuanto se extinguió el día, cubrió de nieblas el valle desde Pratomagno hasta el Apenino, e hizo tan denso aquel cielo, que el espeso aire se convirtió en agua: cayó la lluvia, y el agua que la tierra no pudo absorber fué a parar a los barrancos, y uniéndose a la de los torrentes, se precipitó hacia el río real con tal rapidez, que nada podía contenerla. El Archiano furioso encontró mi cuerpo helado en su embocadura, lo arrastró hacia el Arno, y separó mis brazos que había puesto en cruz sobre el pecho cuando me venció el dolor. Después de haberme volteado por sus orillas y su fondo, me cubrió y rodeó con la arena que había hecho desprenderse de los campos.\"},{\"heading\":false,\"text\":\"--¡Ah!, cuando vuelvas al mundo, y hayas descansado de tu largo viaje--continuó un tercer espíritu, luego que hubo acabado de hablar el segundo--, acuérdate de mí, que soy la Pía.[51] Siena me hizo, y las Marismas me deshicieron: bien lo sabe aquel que, siendo ya viuda, me puso en el dedo su anillo enriquecido de piedras preciosas.\"},{\"heading\":false,\"text\":\"[51]Pía de Tolomei, natural de Siena, casó con Nello o Paganello Pannocchieschi, señor del castillo della Pietra, en la Marisma Toscana, el cual, creyéndola infiel, le dió muerte, en 1295, mandando, según refiere algún comentarista, arrojarla por una ventana.\"}]},{\"title\":\"Purgatorio — canto sexto\",\"blocks\":[{\"heading\":false,\"text\":\"Cuando, acabado el juego de la zara, se desparten los jugadores, el que pierde se queda triste, pensando en las jugadas, y aprendiendo entonces con sentimiento el modo de que debió haberse valido para ganar: con el ganancioso se van los circunstantes; y uno por delante, otro por detrás y otro por el lado procuran hacerse presentes al afortunado; éste no se detiene aunque los escucha a todos, hasta que tiende a uno su mano, que por ello deja de atosigarle, librándose así de los empujones de la multitud. Así estaba yo en medio de aquella compacta muchedumbre de almas, volviendo a uno y otro lado el rostro, hasta que, merced a mis promesas, pude desprenderme de ellas. Allí estaban el Aretino que recibió la muerte de los brazos crueles de Ghin di Tacco, y el otro que se ahogó al darle caza sus enemigos. Allí oraba, con los brazos extendidos, Federico Novello, y aquel de Pisa, que dió ocasión de demostrar la grandeza de su alma al buen Marzucco. Vi al conde Orso, y a aquella alma separada de su cuerpo por hastío y por envidia, como ella misma decía, y no por sus culpas; a Pedro de la Broccia, digo: y bien es menester que provea en ello la princesa de Brabante, mientras esté por acá, si no quiere verse colocada entre peores compañeros.\"},{\"heading\":false,\"text\":\"Cuando me vi libre de todas aquellas sombras, que rogaban para que otros rogasen por ellas, a fin de abreviar el tiempo de su purificación, empecé a decir:\"},{\"heading\":false,\"text\":\"--Parece que me niegas expresamente en algún texto, ¡oh luz que desvaneces mis dudas!, que la oración aplaca los decretos del cielo; y sin embargo, esta gente ruega para conseguirlo. ¿Será, pues, vana su esperanza? ¿O es que no he comprendido bien el sentido de tus palabras?\"},{\"heading\":false,\"text\":\"A lo que me contestó:\"},{\"heading\":false,\"text\":\"--Lo que escribí es muy claro, y la esperanza de ésos no se verá fallida, si se examina con recto sentido. No se menoscaba el alto juicio divino, porque el fuego amoroso de la caridad cumpla en un instante lo que deben satisfacer los que aquí están relegados; y allí, donde senté tal máxima, la oración no tenía la virtud de borrar las faltas, porque el objeto de aquélla estaba alejado de Dios. No te detenga, sin embargo, tan profunda duda, hasta que te la desvanezca aquélla que ha de iluminar tu entendimiento, mostrándole la verdad. No sé si me entiendes: hablo de Beatriz, a quien verás risueña y feliz sobre la cumbre de este monte.\"},{\"heading\":false,\"text\":\"Yo repuse:\"},{\"heading\":false,\"text\":\"--Mi buen Guía, caminemos más de prisa: pues ya no me canso tanto como antes, y la montaña proyecta su sombra hacia este lado.\"},{\"heading\":false,\"text\":\"--Avanzaremos hoy tanto como podamos--me respondió--; pero el camino es muy diferente de lo que te figuras. Antes que lleguemos arriba, verás volver a aquel que ahora se oculta tras de la cuesta, y cuyos rayos no quiebras en este momento. Pero ve allí un alma que, inmóvil y completamente sola, dirige hacia nosotros sus miradas: ella nos enseñará el camino más corto.\"},{\"heading\":false,\"text\":\"Llegamos junto a ella. ¡Oh alma lombarda, cuán altanera y desdeñosa estabas, y cuán noble y grave era el movimiento de tus ojos! Ella no nos decía nada; pero dejaba que nos aproximásemos, mirando únicamente como el león cuando reposa. Virgilio se le acercó, rogándole que nos enseñase la subida más fácil; pero ella, sin contestar a su pregunta, quiso informarse acerca de nuestro país y de nuestra vida; y al empezar mi Guía a decir. \\\"Mantua...,\\\" la sombra, que antes estaba como concentrada en sí misma, corrió hacia él desde el sitio en que se encontraba, diciendo: \\\"¡Oh, mantuano!, yo soy Sordello, de tu tierra.\\\" Y se abrazaron mutuamente.\"},{\"heading\":false,\"text\":\"¡Ah Italia esclava, albergue de dolor, nave sin timonel en medio de una gran tempestad, no ya señora de provincias, sino de burdeles! Al dulce nombre de su país natal, aquel alma gentil se apresuró a festejar a su conciudadano; al paso que tus vivos no saben estar sin guerra, y se destrozan entre sí aquellos a quienes guarda una misma muralla y un mismo foso. Busca, desgraciada, en derredor de tus costas, y después contempla en tu seno si alguna parte de ti misma goza de paz. ¿Qué vale que Justiniano te enfrenara, si la silla está vacía? Tu vergüenza sería menor sin ese mismo freno. ¡Ah, gentes que debierais ser devotas, y dejar al César en su trono, si comprendierais bien lo que Dios ha prescrito! Mirad cuán arisca se ha vuelto esa Italia, por no haber sido castigada a tiempo con las espuelas, desde que os apoderasteis de sus riendas. ¡Oh alemán Alberto, que la abandonas, al verla tan indómita y salvaje, cuando debiste oprimir sus ijares! Caiga sobre tu sangre el justo castigo del Cielo, y sea éste tan nuevo y evidente, que sirva también de temeroso escarmiento a tu sucesor, ya que tú y tu padre, alejados de aquí por ambición, habéis tolerado que quede desierto el jardín del imperio. Hombre indolente, ven a ver a los Montecchi y a los Cappelletti, a los Monaldi y Filippeschi, aquéllos ya tristes, y éstos poseídos de amargos recelos. Ven, cruel, ven; y mira la opresión de tus nobles, y remedia sus males, y verás cuán segura está Santaflora. Ven a ver a tu Roma, que llora, viuda y sola, exclamando día y noche: \\\"¡César mío! ¿Por qué no estás en mi compañía?\\\" Ven y contempla cuán grande es el mutuo amor de la gente; y si nada te mueve a compasión de nosotros, ven a avergonzarte de tu fama. Y, séame lícito preguntarte, ¡oh sumo Jove, que fuiste crucificado por nosotros en la tierra! ¿Están vueltos hacia otra parte tus justos ojos? ¿O es que nos vas preparando de ese modo, en lo profundo de tus pensamientos, para recibir algún gran bien que no puede prever nuestra inteligencia? Porque la tierra de Italia está llena de tiranos; y el hombre más ruin, al ingresar en un partido, se convierte en un Marcelo.\"},{\"heading\":false,\"text\":\"Florencia mía, bien puedes estar satisfecha de esta digresión, que no habla contigo, merced a tu pueblo que tanto se ingenia. Hay muchos que tienen la justicia en el corazón, pero son tardíos en aplicarla, porque temen disparar el arco imprudentemente; mas tu pueblo la tiene en la punta de sus labios. Muchos rehusan los cargos públicos; pero tu pueblo responde solícito, sin que le llamen, y grita: \\\"Yo los acepto.\\\" Alégrate, pues, que motivo tienes para ello. Eres rica, disfrutas tranquilidad, tienes prudencia. Si digo la verdad, claramente lo demuestran los hechos. Atenas y Lacedemonia, que hicieron las antiguas leyes y fueron tan civilizadas, dieron un débil ejemplo de vivir bien, comparadas contigo; pues dictas tan sutiles decretos, que los que expides en Octubre no llegan a mediados de Noviembre. ¿Cuántas veces, en el tiempo a que alcanza la memoria, has cambiado de leyes, de monedas, de oficios y de costumbres, y renovado tus habitantes? Y si quieres recordarlo y ver la luz, conocerás que eres semejante a aquella enferma, que no encuentra posición que le cuadre sobre la pluma, y procura hacer más llevadero su dolor dando continuas vueltas.\"}]},{\"title\":\"Purgatorio — canto septimo\",\"blocks\":[{\"heading\":false,\"text\":\"Después de haber cambiado entre sí tres o cuatro veces corteses y halagüeños saludos, Sordello se hizo un poco atrás, y dijo:\"},{\"heading\":false,\"text\":\"--¿Quiénes sois?\"},{\"heading\":false,\"text\":\"--Mis huesos fueron sepultados por mandato de Octavio, antes que se hubiesen dirigido hacia esta montaña las almas dignas de subir hasta Dios. Yo soy Virgilio, que perdí el cielo por no tener fe, y no por otra culpa.\"},{\"heading\":false,\"text\":\"Así respondió mi Guía. Como el que de improviso ve una cosa que le asombra, y a la que no sabe si dar o no crédito, diciendo: \\\"es, no es,\\\" así se quedó aquél: después bajó los ojos, se adelantó humildemente hacia él, y le abrazó en el sitio del cuerpo donde alcanza el pequeño.\"},{\"heading\":false,\"text\":\"--¡Oh gloria de los latinos--dijo--, por quién nuestra lengua demostró cuánto podía! ¡Honor eterno del lugar donde nací! ¿Qué mérito o qué gracia permite que yo te vea? Si es que soy digno de oír tus palabras, dime si vienes del Infierno, y de qué recinto.\"},{\"heading\":false,\"text\":\"--He llegado hasta aquí pasando por todos los círculos del reino del llanto--respondióle--; la virtud del cielo me guía, y con ella vengo. No por lo que he hecho, sino por lo que no he hecho, he perdido la facultad de contemplar el alto Sol que tú deseas, y que conocí demasiado tarde. Allá abajo hay un lugar triste, no por los martirios, sino por las tinieblas, donde en vez de lamentos como gritos, sólo resuenan suspiros. Allí estoy yo con los inocentes párvulos, mordidos por los dientes de la muerte antes de que fueran lavados del pecado original. Allí estoy yo con aquellos que no se cubrieron con las tres virtudes santas, aunque, exentos de vicios, conocieron y observaron las demás. Pero danos algún indicio, si es que puedes y sabes, a fin de que lleguemos más pronto al sitio donde tiene verdadero principio el Purgatorio.\"},{\"heading\":false,\"text\":\"Sordello respondió:\"},{\"heading\":false,\"text\":\"--Aquí no tenemos designado un punto fijo, y a mí me es lícito subir andando alrededor por la montaña: te serviré de guía por todos los parajes hasta donde puedo llegar. Pero advierte que ya declina el día; y no siendo posible ir arriba de noche, convendrá que pensemos en buscar un buen abrigo. Algo lejos de aquí, a la derecha, hay algunas almas: si quieres, te conduciré adonde están, seguro de que te agradará conocerlas.\"},{\"heading\":false,\"text\":\"--¿Cómo es eso?--le contestó--. Quien quisiera subir de noche, ¿se vería detenido por alguien? ¿O es acaso que no podría subir?\"},{\"heading\":false,\"text\":\"El buen Sordello pasó su dedo por el suelo, diciendo:\"},{\"heading\":false,\"text\":\"--¿Ves esta sola línea? Pues no la atravesarás después de haberse ocultado el Sol; no por otra causa, sino porque te lo impedirán las tinieblas nocturnas; las cuales, con la impotencia que originan, contrarrestan la voluntad. Con ellas, podríase muy bien volver abajo y recorrer la cuesta vagando en torno, mientras el día esté bajo el horizonte.\"},{\"heading\":false,\"text\":\"Entonces mi Señor, como asombrado, repuso:\"},{\"heading\":false,\"text\":\"--Condúcenos adonde dices que puede ser agradable permanecer.\"},{\"heading\":false,\"text\":\"Nos habíamos alejado un poco de allí, cuando eché de ver que el monte estaba hendido como los valles que hay en nuestro hemisferio.\"},{\"heading\":false,\"text\":\"--Iremos--dijo aquella sombra--allá donde la cuesta forma una cavidad, y esperaremos en ella el nuevo día.\"},{\"heading\":false,\"text\":\"Un sendero tortuoso, entre pendiente y llano, nos condujo a un lado de aquella cavidad, en donde las orillas que la circundan descienden más de la mitad de su altura. El oro y la plata fina, la púrpura, el albayalde, el añil azul y brillante, y las esmeraldas recientemente talladas en el momento en que se desprenden sus trozos, serían vencidos en brillantez por las hierbas y las flores de aquella cavidad, como lo menor es vencido por lo mayor. La naturaleza no había ostentado solamente allí sus adornos, sino que con la suavidad de mil aromas había formado un olor indistinto y desconocido para nosotros. Allí vi sentadas sobre la verdura y entre las flores algunas almas, que desde fuera no podían distinguirse, por ocultarlas las laderas del valle, las cuales estaban cantando el \\\"Salve Regina.\\\" El Mantuano, que nos había conducido por el tortuoso sendero, nos dijo:\"},{\"heading\":false,\"text\":\"--No pretendáis que os guíe hasta donde están ésos, antes de que se oculte el poco Sol que queda. Desde esta altura veréis las acciones y los rostros de todos, mejor que si estuvierais entre ellos en el mismo valle. Aquel que está sentado en el puesto más alto, que en su actitud parece haberse descuidado de hacer lo que debía, y cuya boca no se mueve para cantar con los demás, fué el emperador Rodolfo, que pudo curar las heridas que han dado muerte a Italia, de tal modo, que tarde le vendrá de otro el remedio. El que con su presencia conforta al primero, gobernó la tierra donde nace el agua que el Moltava conduce al Elba, y el Elba al mar. Llamóse Ottokar, y ya en la infancia fué mucho mejor príncipe que su hijo Wenceslao cuando barbado, a quien enervaron el ocio y la lujuria. Y aquel romo, que parece consultar con tanta intimidad al otro de benigno aspecto, murió huyendo y marchitando la flor de lis: mirad cómo se golpea el pecho; y ved cómo el otro, suspirando, apoya su mejilla en la palma de la mano. Padre y suegro son del mal de Francia: saben que su vida es grosera y viciosa, y de ahí proviene el dolor que les aflige. Aquel que parece tan corpulento,[52] y que canta acorde con el narigudo,[53] llevó ceñida la cuerda de toda virtud; y si después de él hubiera reinado más tiempo el jovencito que a su espalda se sienta,[54] bien habría pasado el valor de padre a hijo; lo cual no se puede decir de sus otros herederos Jaime y Fadrique conservan los reinos; pero ninguno de ellos posee la mejor herencia. Raras veces renace por las ramas la humana probidad; pues así lo quiere Aquél que nos la da, para que se la pidamos. No menos se dirigen mis palabras al narigudo, que al otro, a Pedro, que canta con él; pues de su descendencia se lamentan ya la Pulla y la Provenza. La planta es inferior a su semilla tanto, cuanto más que Beatriz y Margarita se gloria Constanza aún de su marido. Ved ahí al rey de sencilla vida, sentado aparte y solo, a Enrique de Inglaterra: éste ha producido mejores vástagos. Aquel que está en el suelo más abajo que los otros, mirando hacia arriba, es el marqués Guillermo, por quien Alejandría y sus guerreros hacen llorar hoy al Monferrato y al Canavés.\"},{\"heading\":false,\"text\":\"[52] Pedro III de Aragón.\"},{\"heading\":false,\"text\":\"[53] Carlos I, conde de Provenza y rey de Pulla.\"},{\"heading\":false,\"text\":\"[54] Alfonso III, primogénito de Pedro el Grande, que sucedió a su padre, y sólo reinó seis años, muriendo en 1291.\"}]},{\"title\":\"Purgatorio — canto octavo\",\"blocks\":[{\"heading\":false,\"text\":\"Era ya la hora en que se enternece el corazón de los navegantes, y renace su deseo de abrazar a los caros amigos, de quienes el mismo día se han despedido, y en que el novel viajero se compunge de amor, si oye a lo lejos alguna campana, que parezca plañir al moribundo día; cuando dejé de oír, y comencé a mirar a una de aquellas almas, que, puesta en pie, hacía señas con la mano en ademán de que las otras la escuchasen. Unió y levantó ambas palmas, dirigiendo sus ojos hacia Oriente, como si dijese a Dios: \\\"Sólo en ti pienso;\\\" y salió de su boca tan devotamente y con tan dulces notas el \\\"Te lucis ante,\\\" que el placer me hizo salir fuera de mí. Aguza bien aquí la vista, ¡oh lector!, para descubrir la verdad; porque el velo es ahora tan sutil, que te será en efecto sumamente fácil atravesarlo.\"},{\"heading\":false,\"text\":\"Vi luego a aquel ejército gentil, pálido y humilde, que en silencio contempla el cielo, como esperando algo; y vi salir de las alturas y descender al valle dos ángeles con dos espadas flamígeras, truncadas y privadas de sus puntas. Verdes como las tiernas hojas que acaban de brotar eran sus vestiduras, y agitadas por las plumas de sus alas, verdes también, flotaban por detrás a merced del viento. El uno se posó algo más arriba de donde estábamos; el otro descendió hacia el lado opuesto; de suerte que las almas quedaron entre ellos. Se distinguía perfectamente su blonda cabellera; pero al querer mirar sus facciones, se ofuscaba la vista, como se ofusca toda facultad, por la excesiva fuerza de las impresiones.\"},{\"heading\":false,\"text\":\"--Ambos vienen del seno de María--dijo Sordello--para guardar el valle contra la serpiente, que acudirá a él en breve.\"},{\"heading\":false,\"text\":\"Y yo, que no sabía por qué sitio había de venir, miré en torno mío, y helado de terror, me arrimé cuanto pude a las fieles espaldas. Sordello continuó:\"},{\"heading\":false,\"text\":\"--Ahora descendamos hacia donde están esas grandes sombras, y hablaremos con ellas: les será muy grato veros.\"},{\"heading\":false,\"text\":\"Sólo había descendido tres pasos, según creo, cuando ya me encontré abajo, y vi uno que me miraba como si hubiera querido conocerme. El aire iba ya obscureciéndose, pero no tanto que entre sus ojos y los míos no permitiese ver lo que antes por la distancia se ocultaba. Vino hacia mí, y yo me adelanté hacia él. ¡Noble juez! ¡Oh, Nino! ¡Con cuánto placer vi que no estabas entre los condenados! No hubo amistoso saludo que no nos dirigiésemos; después me preguntó:\"},{\"heading\":false,\"text\":\"--¿Cuánto tiempo hace que has llegado al pie de este monte a través de las lejanas aguas?\"},{\"heading\":false,\"text\":\"--¡Ah!--le dije--; esta mañana he llegado pasando por tristes lugares, y estoy aún en la primera vida; aunque al hacer este viaje, voy preparándome para la otra.\"},{\"heading\":false,\"text\":\"Apenas oyeron mi respuesta, cuando Sordello y él retrocedieron como hombres poseídos de un repentino espanto. El primero se volvió hacia Virgilio, y el otro hacia uno que estaba sentado, gritando: \\\"Ven, Conrado, ven a ver lo que Dios por su gracia permite.\\\" Después, dirigiéndose a mí, exclamó:\"},{\"heading\":false,\"text\":\"--Por la singular gratitud que debes a Aquél que oculta de tal modo su primitivo origen, que no es posible penetrarlo, cuando estés más allá de las anchurosas aguas, di a mi Juana, que pida por mí allí donde se oyen los ruegos de los inocentes. No creo que su madre me ame ya, pues ha dejado las blancas tocas, que la desventurada echará de menos algún día. Por ella se comprende fácilmente cuánto dura en una mujer el fuego del amor, si la vista o el íntimo trato no lo alimenta. La víbora que campea en las armas del Milanés no le proporcionará tan hermosa sepultura como se la hubiera dado el gallo de Gallura.[55]\"},{\"heading\":false,\"text\":\"[55] No será tan honrosa su sepultura cuando muera enlazada a la casa de los Visconti de Milán, como lo sería si hubiera guardado fidelidad a la de los Visconti de Gallura. Los primeros tenían una víbora en su escudo; los segundos un gallo.\"},{\"heading\":false,\"text\":\"Así decía, y en todo su aspecto se veía impreso el sello de aquel recto celo que arde con mesura en el corazón. Entretanto, mis ojos se dirigían ávidos hacia la parte del cielo donde es más lento el curso de las estrellas, como sucede en los puntos de una rueda más próximos al eje. Mi Guía me preguntó:\"},{\"heading\":false,\"text\":\"--Hijo mío, ¿qué miras allá arriba?\"},{\"heading\":false,\"text\":\"Y yo le contesté:\"},{\"heading\":false,\"text\":\"--Aquellas tres antorchas[56], en cuya luz arde todo el polo hacia esta parte.\"},{\"heading\":false,\"text\":\"[56] Las constelaciones del Eridano, de la Nave y del Pez de oro.--Alegóricamente son las tres virtudes teologales.\"},{\"heading\":false,\"text\":\"Y él repuso:\"},{\"heading\":false,\"text\":\"--Las cuatro estrellas brillantes que viste esta mañana, han descendido por aquel lado, y éstas han subido donde estaban aquéllas.\"},{\"heading\":false,\"text\":\"Mientras él hablaba, Sordello se le acercó, diciendo: \\\"He ahí a nuestro adversario;\\\" y extendió el dedo para que mirásemos hacia el sitio que indicaba. En la parte donde queda indefenso el pequeño valle, había una serpiente, que quizá era la que dió a Eva el amargo manjar. Se adelantaba el maligno reptil por entre la hierba y las flores, volviendo de vez en cuando la cabeza, y lamiéndose el lomo como un animal que se alisa la piel. No puedo decir cómo se movieron los azores celestiales, pues no me fué posible distinguirlo; pero sí vi a entreambos en movimiento. Sintiendo que sus verdes alas hendían el aire, huyó la serpiente, y los ángeles se volvieron a su puesto con vuelo igual. La sombra que se acercó al juez, cuando éste la llamó, no dejó un momento de mirarme durante todo aquel asalto.\"},{\"heading\":false,\"text\":\"--Que la antorcha que te conduce hacia arriba encuentre en tu voluntad tanta cera cuanta se necesita para llegar al sumo esmalte--empezó a decir--; si sabes alguna noticia positiva del Val di Magra o de su tierra circunvecina, dímela, pues yo era señor en aquel país: fuí llamado Conrado Malaspina, no el antiguo, sino descendiente suyo, y tuve para con los míos un amor que aquí se purifica.\"},{\"heading\":false,\"text\":\"--¡Oh!--le contesté--; no estuve nunca en vuestro país; pero ¿a qué parte de Europa no habrá llegado su fama? La gloria que honra vuestra casa da tal renombre a sus señores y a la comarca entera, que tiene noticia de ella aun aquel que no la ha visitado. Y os juro, así pueda llegar a lo alto de este monte, que vuestra honrosa estirpe no pierde la prez que le han conquistado su bolsa y su espada. Sus buenas costumbres y excelente carácter la colocan en tan privilegiado puesto, que aunque el perverso jefe aparte al mundo del verdadero camino, ella va por el recto sendero despreciando el torcido.\"},{\"heading\":false,\"text\":\"El replicó:\"},{\"heading\":false,\"text\":\"--Ve, pues; que antes de que el Sol entre siete veces en el espacio que Aries con sus cuatro patas cubre y abarca, esa opinión cortés te será clavada en medio de la cabeza con clavos mayores que lo pueden ser las palabras de otro, si no se cambia el curso de lo dispuesto por la Providencia.\"}]},{\"title\":\"Purgatorio — canto nono\",\"blocks\":[{\"heading\":false,\"text\":\"La concubina del viejo Titón, desprendida de los brazos de su dulce amigo, alboreaba ya en los linderos orientales, reluciendo su frente de rica pedrería colocada en la forma del frío animal que sacude a la gente con la cola;[57] y ya por el lugar donde nos hallábamos había dado la Noche dos de los pasos con que asciende, y el tercero inclinaba hacia abajo su vuelo, cuando yo, que tenía conmigo la flaqueza de Adán, vencido del sueño, me tendí en la hierba sobre que estábamos sentados los cinco.\"},{\"heading\":false,\"text\":\"A la hora del amanecer, cuando la golondrina empieza sus tristes endechas, quizá en memoria de sus primeros ayes, y cuando nuestro espíritu, más libre de los lazos de la carne y menos asediado de pensamientos, es casi divino en sus visiones, parecióme ver entre sueños un águila con plumas de oro suspendida del cielo, con las alas abiertas y preparada a bajar, y creía estar allí donde Ganimedes abandonó a los suyos, cuando fué arrebatado a la celestial asamblea. Yo pensaba entre mí: \\\"Quizá esta águila tenga la costumbre de cazar aquí solamente, y puede ser que en otro sitio se desdeñe de levantar en alto la presa con sus garras.\\\" Después me pareció que, dando algunas vueltas, bajaba terrible como un rayo, y me arrebataba hasta la esfera del fuego, donde parecía que ardiésemos los dos; y de tal modo me quemaba aquel incendio imaginario, que se interrumpió súbitamente mi sueño. No de otra suerte se sobresaltó Aquiles revolviendo en torno suyo sus ojos desvelados y sin saber donde se encontraba, cuando su madre, robándolo a Quirón, le transportó dormido en sus brazos a la isla de Scyros, de donde le sacaron después los griegos, como me sobresalté yo, apenas huyó el sueño de mi rostro; y me puse pálido como el hombre a quien hiela el espanto. A mi lado estaba únicamente mi Protector; el Sol había salido hacía ya más de dos horas, y yo me hallaba con la cara vuelta hacia el mar.\"},{\"heading\":false,\"text\":\"[57] La esposa de Titón es la Aurora, y su frente aparecía coronada en las estrellas que forman el signo de Piscis.\"},{\"heading\":false,\"text\":\"--No temas--dijo mi Señor--; tranquilízate, que estamos en buen lugar. Da rienda suelta a tu vigor, lejos de reprimirlo, pues has llegado ya junto al Purgatorio; mira allí el muro que le cerca en derredor; y mira la entrada en aquel sitio donde parece estar roto. Durante el alba que precede al día, cuando tu alma dormía dentro del cuerpo sobre las flores que allá abajo adornan el suelo, vino una dama y dijo: \\\"Yo soy Lucía: déjame coger a ese que duerme, y haré que recorra más ágilmente su camino.\\\" Sordello se quedó con las otras nobles sombras; ella te cogió, y cuando fué de día, se vino hacia arriba y yo seguí sus huellas: aquí te dejó, habiéndome antes designado con sus bellos ojos aquella entrada abierta; y después, ella y tu sueño desaparecieron al mismo tiempo.\"},{\"heading\":false,\"text\":\"Me quedé como el hombre que ve sus dudas convertidas en certidumbre, y cuyo miedo se trueca en fortaleza, cuando le han descubierto la verdad; y viéndome tranquilo mi Guía, empezó a subir por la calzada, y yo seguí tras él hacia lo alto.\"},{\"heading\":false,\"text\":\"Lector: bien ves cómo ensalzo el objeto de mis cantos: no te admire, pues, si procuro sostenerlo cada vez con más arte. Nos aproximamos hasta llegar al sitio que antes me había parecido ser una rotura, semejante a la brecha que divide un muro; y vi una puerta a la cual se subía por tres gradas de diferentes colores, y un portero que aún no había proferido ninguna palabra. Y como yo abriese cada vez más los ojos, le vi sentado sobre la grada superior, con tan luminoso rostro, que no podía fijar en él mi vista. Tenía en la mano una espada desnuda, que reflejaba sus rayos hacia nosotros de tal modo, que en vano intentó fijar en ella mis miradas.\"},{\"heading\":false,\"text\":\"--Decidme desde ahí: ¿qué queréis?--empezó a decir.--¿Dónde está el que os acompaña? Cuidad que vuestra llegada no os sea funesta.\"},{\"heading\":false,\"text\":\"--Una dama del Cielo, enterada de estas cosas--le respondió mi Maestro--, nos ha dicho hace poco: \\\"Id allí: aquella es la puerta.\\\"\"},{\"heading\":false,\"text\":\"--Ella guía felizmente vuestros pasos--replicó el cortés portero--. Llegad, pues, y subid nuestras gradas.\"},{\"heading\":false,\"text\":\"Nos adelantamos: el primer escalón era de mármol blanco, tan bruñido y terso, que me reflejé en él tal como soy: el segundo, más obscuro que el color turquí, era de una piedra calcinada y áspera, resquebrajada a lo largo y de través: el tercero, que gravita sobre los demás, me parecía de un pórfido tan rojo como la sangre que brota de las venas. Sobre este último tenía ambas plantas el Angel de Dios, el cual estaba sentado en el umbral, que me pareció formado de diamante. Mi Guía me condujo de buen grado por los tres escalones, diciendo:\"},{\"heading\":false,\"text\":\"--Pide humildemente que se abra la cerradura.\"},{\"heading\":false,\"text\":\"Me postré devotamente a los pies santos: le pedí por misericordia que abriese, pero antes me dí tres golpes en el pecho. Con la punta de su espada me trazó siete veces en la frente la letra P[58], y dijo:\"},{\"heading\":false,\"text\":\"--Procura lavar estas manchas cuando estés dentro.\"},{\"heading\":false,\"text\":\"[58] Símbolo de los siete pecados capitales.\"},{\"heading\":false,\"text\":\"En seguida sacó de debajo de sus vestiduras, que eran del color de la ceniza o de la tierra seca, dos llaves, una de las cuales era de oro y la otra de plata: primero con la blanca, y luego con la amarilla, hizo en la puerta lo que yo deseaba.\"},{\"heading\":false,\"text\":\"--Cuando una de estas llaves falsea, y no gira con regularidad por la cerradura--nos dijo--, esta entrada no se abre. Una de ellas es más preciosa; pero la otra requiere más arte e inteligencia antes de abrir, porque es la que mueve el resorte. Pedro me las dió, previniéndome que más bien me equivocara en abrir la puerta, que en tenerla cerrada, siempre que los pecadores se prosternen a mis pies.\"},{\"heading\":false,\"text\":\"Después empujó la puerta hacia el sagrado recinto, diciendo:\"},{\"heading\":false,\"text\":\"--Entrad; mas debo advertiros que quien mira hacia atrás vuelve a salir.\"},{\"heading\":false,\"text\":\"Entonces giraron en sus quicios los espigones de la sacra puerta, que son de metal, macizos y sonoros; y no produjo tanto fragor, ni se mostró tan resistente la de la roca Tarpeya, cuando fué arrojado de ésta el buen Metelo, por el cual quedó luego vacía. Yo me volví atento al primer ruido, y me pareció oír voces que cantaban al son de dulces acordes: \\\"Te Deum laudamus.\\\" Tal impresión hizo en mí aquello que oía, como la que ordinariamente se recibe cuando se oye el canto acompañado del órgano, que tan pronto se perciben como dejan de percibirse las palabras.\"}]},{\"title\":\"Purgatorio — canto decimo\",\"blocks\":[{\"heading\":false,\"text\":\"Cuando hubimos traspasado el umbral de la puerta que se abre pocas veces, porque la mala inclinación de las pasiones lo impide, haciendo aparecer recta la vía tortuosa, conocí por el ruido que acababa de cerrarse; y si yo hubiese vuelto mis ojos hacia ella, ¿qué excusa hubiera sido digna de tal falta? Subíamos por la hendedura de una roca, la cual ondulaba tortuosamente, semejante a la ola que va y viene.\"},{\"heading\":false,\"text\":\"--Aquí--dijo mi Guía--, es preciso que tengamos alguna precaución, acercándonos, ya por un lado, o por otro, a las ondulaciones de esta hendedura.\"},{\"heading\":false,\"text\":\"Y este cuidado hizo tan lentos nuestros pasos, que la Luna llegó a su lecho para acurrucarse, antes que nosotros saliésemos de aquel angosto camino. Mas cuando estuvimos arriba, libres y al descubierto, en el paraje donde se interna el monte, nos encontramos, yo fatigado, y ambos inciertos de la dirección que debíamos seguir, en un rellano más solitario que sendero a través del desierto. Desde el borde exterior hasta el pie del alto tajo que se alza en la parte interior, aquel rellano sólo tendría de anchura tres veces un cuerpo humano; y hasta donde mis ojos alcanzaban, tanto por la izquierda como por la derecha, parecíame siempre igual esta especie de cornisa. Aún no habíamos dado un paso por aquella vía, cuando observé que el tajo interior y escueto, por el cual no se podía subir, era de mármol blanco, y adornado de tan preciosas entalladuras, que no ya Policleto, sino la Naturaleza en presencia de ellas habría sido superada y vencida. El ángel que bajó a la Tierra con el decreto de la paz por tantos años suspirada, y abrió las puertas del cielo después de su prolongada clausura, se ofreció a nuestra vista con tanta verdad, y en tan dulce actitud esculpido, que no parecía una figura silenciosa. Hubiérase jurado que hablaba diciendo: \\\"Ave;\\\" porque también estaba allí representada la que dió vuelta a la llave para abrir al Amor supremo. En su actitud se veían impresas estas palabras: \\\"Ecce ancilla Dei,\\\" tan propiamente como aparece una figura sellada en la cera.\"},{\"heading\":false,\"text\":\"--No fijes tu atención en un solo punto--me dijo el querido Maestro--, que me tenía cerca de sí en el lado que los hombres tienen el corazón.\"},{\"heading\":false,\"text\":\"Volví el rostro, y hacia la parte donde se encontraba el que movía mis pasos, vi después de María otra historia esculpida en la roca; y para examinarla mejor, pasé al otro lado de Virgilio, y me aproximé a ella. Estaban tallados en el mismo mármol el carro y los bueyes conduciendo el Arca santa, por la cual es temible desempeñar un cargo que Dios no ha confiado. Delante de ella veíase alguna gente, dividida en siete coros, que a dos de mis sentidos hacía decir: a uno, \\\"sí canta,\\\" y a otro, \\\"no canta.\\\" En igual discordancia ponía a mi vista y a mi olfato el humo del incienso que estaba allí representado. El humilde Salmista, danzando y saltando, precedía al vaso bendito; y en aquella ocasión era más y menos que rey. Desde lo alto de un gran palacio que había enfrente, Micol lo contemplaba como mujer despechada y mohina. Moví mis pies más allá del sitio en que me encontraba, para examinar de cerca otra historia que resaltaba después de Micol. Allí estaba escrita en piedra la alta gloria del príncipe romano, cuya insigne virtud movió a Gregorio para alcanzar su gran victoria: hablo del emperador Trajano. Asida al freno de su caballo se veía a una viuda, penetrada de dolor y deshecha en lágrimas: en torno suyo aparecía una considerable multitud de caballeros, sobre cuyas cabezas se movían al viento las águilas de oro. La desventurada, metida entre todos ellos, parecía decir: \\\"Señor, véngame de la muerte de mi hijo, que me ha traspasado el corazón;\\\" y él responderle: \\\"Espérate a que yo vuelva;\\\" y ella replicar, como persona a quien impacienta su mismo dolor: \\\"Señor mío, ¿y si no vuelves?\\\" Y él: \\\"Quien ocupe mi lugar te vengará.\\\" Y ella: \\\"¿Qué te importa el bien que pueda hacer otro, si te olvidas del que puedes hacer tú?\\\" Y él por último: \\\"Tranquilízate; preciso es que cumpla con mi deber antes de ponerme en marcha: la justicia lo quiere, y la piedad me detiene.\\\" Aquel que no vió jamás cosa nueva produjo este hablar visible, nuevo para nosotros, porque no se encuentra en la Tierra nada parecido. Mientras yo me deleitaba contemplando aquellas imágenes de tanta humildad, más que por su belleza, gratas a la vista, por ser quien era su Artífice, el poeta murmuraba:\"},{\"heading\":false,\"text\":\"--Mira cuántas almas se dirigen hacia acá con paso lento: ellas nos conducirán a las gradas superiores.\"},{\"heading\":false,\"text\":\"Mis ojos atentos a mirar para ver las novedades de que se mostraban tan ávidos, no fueron tardos en volverse hacia él. No quiero, ¡oh lector!, que te apartes de tus buenas disposiciones, oyendo cómo Dios quiere que se paguen las deudas. No presten atención a la forma de estas penas, sino a lo que en pos de ellas vendrá: piensa que, en el último y peor resultado, no pueden prolongarse más allá de la gran sentencia. Yo empecé a decir:\"},{\"heading\":false,\"text\":\"--Maestro, lo que veo dirigirse hacia nosotros no me parecen personas, ni sé lo que es; pues se desvanece a mi vista.\"},{\"heading\":false,\"text\":\"Me contestó:\"},{\"heading\":false,\"text\":\"--La abrumadora condición de sus tormentos les hace inclinarse de tal modo hacia el suelo, que aun mis ojos dudaron al principio; pero mira allí fijamente, descubre con tu vista lo que viene debajo de aquellas peñas, y podrás juzgar cuál es el tormento de cada uno de ellos.\"},{\"heading\":false,\"text\":\"¡Oh cristianos soberbios, miserables y débiles, que enfermos de la vista del entendimiento, os fiáis en vuestros pasos retrógrados! ¿No observáis que somos gusanos nacidos para formar la angelical mariposa, que dirige su vuelo sin impedimento hacia la justicia de Dios? ¿Por qué se engríe soberbio vuestro ánimo, cuando sólo sois defectuosos insectos, como crisálidas que no llegan a desarrollarse? Así como, para sostener un piso o un techo, se ve a veces por ménsula una figura cuyas rodillas se doblan hasta el pecho, la cual, con ser fingido su esfuerzo, produce verdadera aflicción en quien la mira, del mismo modo vi yo a aquellas almas cuando las examiné con cuidado. Es cierto que estaban más o menos contraídas, según era mayor o menor el peso que soportaban; pero aun la que más paciente y aliviada se mostraba en sus movimientos parecía decir llorando: \\\"No puedo más.\\\"\"}]},{\"title\":\"Purgatorio — canto undecimo\",\"blocks\":[{\"heading\":false,\"text\":\"\\\"¡Oh padre nuestro, que estás en los cielos, aunque no circunscrito a ellos, sino por el mayor amor que arriba sientes hacia los primeros efectos! Alabados sean tu nombre y tu poder por las criaturas, así como se deben dar gracias a las dulces emanaciones de tu bondad. Venga a nos la paz de tu reino, a la que no podemos llegar por nosotros mismos, a pesar de toda nuestra inteligencia, si ella no se dirige hacia nosotros. Así como los ángeles te sacrifican su voluntad entonando Hosanna, deben sacrificarte la suya los hombres. Danos hoy el pan cuotidiano, sin el cual retrocede por este áspero desierto aquel que más se afana por avanzar. Y así como nosotros perdonamos a cada cual el mal que nos ha hecho padecer, perdónanos tú benigno, sin mirar a nuestros méritos. No pongas a prueba nuestra virtud, que tan fácilmente se abate, contra el antiguo adversario, sino líbranos de él, que la instiga de tantos modos. No hacemos, ¡oh Señor amado!, esta última súplica por nosotros, pues ya no tenemos necesidad de ella, sino por los que tras de nosotros quedan.\\\"\"},{\"heading\":false,\"text\":\"De esta suerte, pidiendo para ellas y para nosotros un feliz viaje, iban aquellas almas soportando su carga, semejante a la que a veces cree uno llevar cuando sueña. Desigualmente cargadas y desfallecidas caminaban alrededor del primer círculo, a fin de purificarse de las vanidades del mundo. Si desde allí siempre se ruega por nosotros, ¿qué no podrán decir y hacer por ellas desde aquí los que a su voluntad reúnen la gracia divina? Es preciso ayudarles a lavarse las manchas que del mundo llevaron, para que puedan llegar, limpias y ágiles, hasta las estrelladas esferas.\"},{\"heading\":false,\"text\":\"--¡Ah! Que la justicia y la piedad os alivien pronto de vuestro peso, de modo que podáis desplegar las alas y elevaros según vuestro deseo: mostradnos por qué lado se va más pronto hacia la escala; y si hay más de un camino, enseñadnos cuál es el menos pendiente, pues este que viene conmigo es muy tardo en subir, a causa de la carne de Adán de que va revestido.\"},{\"heading\":false,\"text\":\"No pudimos averiguar de quién procedían las palabras que respondieron a éstas que había proferido aquel a quien yo seguía; pero contestaron:\"},{\"heading\":false,\"text\":\"--Venid con nosotros, a mano derecha, por la orilla, y encontraréis un sendero por donde puede subir una persona viva. Y si no me lo impidiera este peñasco, que doma mi soberbia cerviz, y me obliga a llevar la cabeza baja, miraría a ese que vive aún y no se nombra, para ver si le conozco, y para excitar su piedad por mi suplicio. Yo fuí latino e hijo de un gran toscano: mi padre fué Guillermo Aldobrandeschi; no sé si habréis oído alguna vez su nombre. La antigua nobleza y las brillantes acciones de mis antepasados me hicieron tan arrogante, que no pensando en nuestra madre común, tuve tanto desprecio hacia los demás hombres, que este desprecio causó mi muerte, como saben los sieneses, y como sabe en Campagnatico todo el que habla. Yo soy Umberto; y no es a mí solo a quien ha perjudicado el orgullo, sino que también ha acarreado la desgracia de todos mis parientes. Por mis pecados me veo en la precisión de soportar aquí este peso, hasta dejar a Dios satisfecho: ya que no lo hice entre los vivos, debo hacerlo entre los muertos.\"},{\"heading\":false,\"text\":\"Al oirle, bajé la cabeza; y uno de ellos, que no era el que hablaba, se volvió bajo el peso que lo agobiaba: me vió, conocióme, y me llamó, teniendo los ojos fijos con gran trabajo en mí, que caminaba inclinado junto a ellos.\"},{\"heading\":false,\"text\":\"--¡Oh!--le dije--; ¿no eres tú Oderisi, honor de Agobbio y de aquel arte que llaman de iluminar en París?\"},{\"heading\":false,\"text\":\"--Hermano--me dijo--: más agradan los dibujos que ilumina Francisco Bolognese: ahora todo el honor es suyo, si bien yo participo de él. No hubiera yo sido en vida tan generoso, a causa del gran deseo de sobresalir en mi arte que dominaba mi corazón. De tal soberbia aquí se paga la pena; y estoy aquí, gracias a que, cuando aún podía pecar, volví mi alma a Dios. ¡Oh vanagloria del ingenio humano! ¡Cuán poco dura tu lozano verdor, cuando no alcanza épocas de ignorancia! Creía Cimabue ser árbitro en el campo de la pintura, y ahora es Giotto al que se aclama, de modo que ha quedado obscurecida la fama de aquél: de igual suerte un Guido ha despojado a otro de la gloria de la lengua[59], y acaso ha nacido ya quien arroje a los dos de su nido. El rumor del mundo no es más que un soplo, que tan pronto viene de un lado, como de otro, y cambia de nombres por lo mismo que cambia de sitios. ¡Qué mayor fama será la tuya de aquí a mil años, separando de ti tu cuerpo envejecido, que si hubieses muerto antes de dejar el \\\"pappo\\\" y el \\\"dindi\\\"[60]? Ese espacio de tiempo, comparado con la eternidad, es mucho más corto que un abrir y cerrar de ojos respecto al círculo que más lentamente se mueva en el cielo. En toda la Toscana resonó el nombre del que camina paso a paso delante de mí; y ahora apenas se le menciona en Siena, de donde era Señor cuando fué destruída la ira florentina, que en aquel tiempo era tan altanera, como prostituta es ahora. Vuestra fama es semejante al color de la hierba, que viene y va; y el que la decolora es el mismo que hace brotar sus tiernos tallos.\"},{\"heading\":false,\"text\":\"[59] Guido Guinicelli, poeta de Bolonia, y Guido Cavalcanti, otro célebre poeta florentino, hijo de Cavalcante: éste hizo olvidar la fama del primero; murió en 1301.\"},{\"heading\":false,\"text\":\"[60] Voces con las que designaban los niños al pan y al dinero. Quiere decir: Al cabo de mil años, que son nada comparados con la eternidad, tu fama no será mayor si mueres viejo, que si hubieses muerto en la infancia.\"},{\"heading\":false,\"text\":\"Le contesté:\"},{\"heading\":false,\"text\":\"--Tus verídicas palabras infunden en mi corazón una buena humildad, y abaten mi hinchazón; pero ¿quién es ese del cual hablabas ahora?\"},{\"heading\":false,\"text\":\"--Es--me respondió--Provenzano Salvani--; está aquí, porque tuvo la presunción de reunir en su mano todo el gobierno de Siena. Ha marchado y continúa marchando sin reposo desde que murió; pues en tal moneda paga quien allá se ha mostrado demasiado audaz.\"},{\"heading\":false,\"text\":\"Le repliqué:\"},{\"heading\":false,\"text\":\"--Si un espíritu que, para arrepentirse, aguarda llegar al límite de la vida, permanece en la parte inferior de la montaña, y a no ser que le ayude una ferviente oración, no sube a este sitio hasta haber transcurrido un espacio de tiempo igual al que vivió, ¿cómo es que se le ha permitido a ése venir aquí?\"},{\"heading\":false,\"text\":\"--Cuando vivía en medio de su mayor gloria--dijo--, se presentó en la plaza de Siena deponiendo toda vanidad, y allí, para librar a un amigo suyo[61] del cautiverio que sufría en la prisión de Carlos, se portó de modo que temblaban todas sus venas. No te diré más: sé que te hablo en términos obscuros; pero no transcurrirá mucho tiempo sin que tus conciudadanos obren de modo que te permitirán penetrar el sentido de mis palabras. Esta acción le ha valido traspasar los límites del Purgatorio.\"},{\"heading\":false,\"text\":\"[61] Para librar a un amigo suyo, un tal Vigna, que sólo mediante la suma de diez mil florines de oro podía salir de la cárcel, donde lo tenía Carlos I, rey de Pulla, se presentó en la plaza de Siena a pedir limosna, tembloroso y angustiado.\"}]},{\"title\":\"Purgatorio — canto duodecimo\",\"blocks\":[{\"heading\":false,\"text\":\"Unidos, como bueyes bajo el yugo, íbamos aquella alma cargada y yo, mientras lo permitió mi amado pedagogo; pero cuando dijo: \\\"Déjale, y sigue, que aquí conviene que cada cual dé cuanto impulso pueda a su barca con la vela y con los remos,\\\" erguí mi cuerpo como debe andar el hombre, por más que mis pensamientos continuaran siendo humildes y sencillos. Ya estaba yo en marcha, siguiendo gustoso los pasos de mi Maestro, y ambos hacíamos alarde de nuestra agilidad, cuando él me dijo:\"},{\"heading\":false,\"text\":\"--Mira hacia abajo; pues para que sea menos penoso el camino, te convendrá ver el suelo en que se asientan tus plantas.\"},{\"heading\":false,\"text\":\"Del modo que las sepulturas tienen esculpido en signos emblemáticos lo que fueron los muertos enterrados en ellas, para perpetuar su memoria, por lo cual muchas veces arranca lágrimas allí el aguijón del recuerdo, que sólo punza a las almas piadosas, de igual suerte, pero con más propiedad y perfecto artificio, vi yo cubierto de figuras todo el plano de aquella vía que avanza fuera del monte. Veía, por una parte, a aquel que fué creado más noble que las demás criaturas, cayendo desde el cielo como un rayo[62]. Veía en otro lado a Briareo, herido por el dardo celestial, yaciendo en el suelo y oprimiéndolo con el peso de su helado cuerpo. Veía a Timbreo[63], a Palas y a Marte, armados aún y en derredor de su padre, contemplando los esparcidos miembros de los Gigantes. Veía a Nemrod al pie de su gran obra, mirando con ojos extraviados a los que fueron en Senaar soberbios como él. ¡Oh Níobe, con cuán desolados ojos te veía representada en el camino entre tus siete y siete hijos exánimes! ¡Oh Saúl, cómo te me aparecías allí, atravesado con tu propia espada y muerto en Gelboé, que desde entonces no volvió a recibir la lluvia ni el rocío! Con igual evidencia te veía, ¡oh loca Aracnea!, ya medio convertida en araña, y triste sobre los rotos pedazos de la obra que labraste por desgracia tuya. ¡Oh Roboam! Allí no estabas ya representado con aspecto amenazador, sino lleno de espanto y conducido en un carro, huyendo antes que otros te expulsasen de tu reino. Mostrábase además en aquel duro pavimento de qué modo Alcmeón hizo pagar caro a su madre el desastroso adorno; cómo los hijos de Sennaquerib se arrojaron sobre su padre dentro del templo, dejándole allí muerto; la destrucción y el cruel estrago que hizo Tamiris, cuando dijo a Ciro: \\\"Tuviste sed de sangre; pues bien, yo te harto de ella;\\\" y la derrota de los asirios, después de la muerte de Holofernes, y el destrozo de sus restos fugitivos. Veíase a Troya convertida en cenizas y en ruinas. ¡Oh Ilión!, ¡cuán abatida y despreciable te representaba la escultura que allí se distinguía! ¿Quién fué el maestro, cuyo pincel o buril trazó tales sombras y actitudes, que causarían admiración al más agudo ingenio? Allí los muertos parecían muertos, y los vivos realmente vivos. El que presenció los hechos no vió mejor que yo la verdad de cuanto fuí pisando mientras anduve inclinado. Así, pues, hijos de Eva, ensoberbeceos; marchad con la mirada altiva, y no inclinéis el rostro de modo que podáis ver el mal sendero.\"},{\"heading\":false,\"text\":\"[62] Luzbel.\"},{\"heading\":false,\"text\":\"[63] Apolo.\"},{\"heading\":false,\"text\":\"Habíamos dado ya una gran vuelta por el monte, y el Sol estaba mucho más adelantado en su camino de lo que nuestro absorto espíritu creyera, cuando aquel que siempre andaba cuidadoso, empezó a decir:\"},{\"heading\":false,\"text\":\"--Levanta la cabeza: no es tiempo de ir tan pensativo. He allí un ángel, que se prepara a venir hacia nosotros, y ve también que se retira del servicio del día la sexta esclava. Reviste de reverencia tu rostro y tu actitud, a fin de que le plazca conducirnos más arriba: piensa en que este día no volverá jamás a lucir.\"},{\"heading\":false,\"text\":\"Estaba yo tan acostumbrado por sus amonestaciones a no desperdiciar el tiempo, que su lenguaje, con respecto a este punto, no podía parecerme obscuro. La hermosa criatura venía en nuestra dirección, vestida de blanco, y centelleando su rostro como la estrella matutina. Abrió los brazos y después las alas, diciendo:\"},{\"heading\":false,\"text\":\"--Venid; cerca de aquí están las gradas, y puede subirse fácilmente por ellas. ¡Qué pocos acuden a esta invitación! ¡Oh raza humana, nacida para remontar el vuelo!, ¿por qué el menor soplo de viento te hace caer?\"},{\"heading\":false,\"text\":\"Nos condujo hacia donde la roca estaba cortada; y allí agitó sus alas sobre mi frente, permitiéndome luego seguir con seguridad mi camino. Así como, para subir al monte donde está la iglesia que, a mano derecha y más arriba del Rubaconte, domina a la bien gobernada ciudad[64], se modera la rápida pendiente por medio de las escaleras hechas en otro tiempo, cuando estaban seguros los registros y las marcas oficiales, así también aquí, de un modo semejante, se templa la aspereza de la escarpada cuesta que desciende casi a plomo desde el otro círculo; pero es preciso pasar rasando por ambos lados con las altas rocas. Mientras nos internábamos en aquella angostura, oímos voces que cantaban \\\"Beati pauperes spiritu,\\\" de tal manera, que no podía expresarse con palabras. ¡Ah! ¡Cuán diferentes de los del Infierno son estos desfiladeros! Aquí se entra oyendo cánticos, y allá horribles lamentos. Subíamos ya por la escalera santa, y me parecía ir más ligero por ella, que antes iba por el camino llano; lo que me obligó a exclamar:\"},{\"heading\":false,\"text\":\"--Maestro, dime: ¿de qué peso me han aliviado, pues ando sin sentir apenas cansancio alguno?\"},{\"heading\":false,\"text\":\"[64] Florencia.\"},{\"heading\":false,\"text\":\"Respondióme:\"},{\"heading\":false,\"text\":\"--Cuando las P, que aún quedan en tu frente casi borradas, hayan desaparecido enteramente, como una de ellas, tus pies obedecerán tan sumisos a tu voluntad, que lejos de sentir el menor cansancio, tendrán un placer en moverse.\"},{\"heading\":false,\"text\":\"Al oír esto, hice como los que llevan algo en la cabeza y no lo saben, pero lo sospechan por los ademanes de otros; que procuran acertarlo con ayuda de la mano, la cual busca y encuentra, y desempeña el oficio que no es posible encomendar a la vista: extendiendo los dedos de la mano derecha, sólo encontré seis de las letras que el Angel de las llaves había grabado en mi frente; y al ver lo que yo hacía, se sonrió mi Maestro.\"}]},{\"title\":\"Purgatorio — canto decimo tercio\",\"blocks\":[{\"heading\":false,\"text\":\"Habíamos llegado a lo alto de la escala, donde por segunda vez se adelgaza la montaña destinada a la purificación de los que suben por ella. También allí la ciñe en derredor un rellano como el primero, sólo que el arco de su circunferencia se repliega más pronto: en él no hay esculturas ni nada parecido, y así el ribazo interior, como el camino presentan al desnudo el color lívido de la piedra.\"},{\"heading\":false,\"text\":\"--Si esperamos aquí a alguien para preguntarle hacia qué lado hemos de seguir--decía el Poeta--, temo que tardaremos mucho en decidirnos.\"},{\"heading\":false,\"text\":\"Dirigió luego la vista fijamente hacia el Sol; afirmó en el pie derecho el centro de rotación, e hizo girar su costado izquierdo.\"},{\"heading\":false,\"text\":\"--¡Oh dulce luz, en quien confío al entrar por el nuevo camino! Condúcenos--decía--como conviene ser conducido por este lugar. Tú das calor al mundo, tú le iluminas: tus rayos, pues, deben servir siempre de guía, a menos que otra razón disponga lo contrario.\"},{\"heading\":false,\"text\":\"Ya habíamos recorrido en poco tiempo y merced a nuestra activa voluntad, un trayecto como el que acá se cuenta por una milla, cuando sentimos volar hacia nosotros, pero sin verlos, algunos espíritus que, hablando, invitaban cortésmente a tomar asiento en la mesa de amor. La primera voz que pasó volando decía distintamente: \\\"Vinum non habent!\\\" y se alejó, repitiéndolo por detrás de nosotros. Antes que dejara de percibirse enteramente a causa de la distancia, pasó otra gritando: \\\"Yo soy Orestes;\\\" y tampoco se detuvo.\"},{\"heading\":false,\"text\":\"--¡Oh Padre!--dije yo--; ¿qué voces son esas?\"},{\"heading\":false,\"text\":\"Y mientras esto preguntaba, oímos una tercera que decía: \\\"Amad a los que os han hecho daño.\\\" El buen Maestro me contestó:\"},{\"heading\":false,\"text\":\"--En este círculo se castiga la culpa de la envidia; pero las cuerdas del azote son movidas por el amor. El freno de ese pecado debe producir diferente sonido; y creo que lo oirás, según me parece, antes de que llegues al paso del perdón. Pero fija bien tus miradas a través del aire, y verás algunas almas sentadas delante de nosotros, apoyándose todas a lo largo de la roca.\"},{\"heading\":false,\"text\":\"Entonces abrí los ojos más que antes; miré hacia delante, y vi sombras con mantos, cuyo color no era diferente del de la piedra. Y luego que hubimos avanzado algo más, oí exclamar: \\\"¡María, ruega por nosotros!\\\" \\\"¡Miguel, y Pedro, y todos los santos, rogad!\\\" No creo que hoy exista en la Tierra un hombre tan duro, que no se sintiese movido de compasión hacia lo que vi en seguida; pues cuando llegué junto a las almas, y pude observar sus actos claramente, brotó de mis ojos un gran dolor. Me parecían cubiertas de vil cilicio; cada cual sostenía a otra con la espalda, y todas lo estaban a su vez por la roca, como los ciegos, a quienes falta la subsistencia, se colocan en los Perdones, y solicitan el socorro de sus necesidades, apoyando cada uno su cabeza sobre la del otro, para excitar más pronto la compasión, no por medio de sus palabras, sino con su aspecto que no contrista menos. Y del mismo modo que el sol no llega hasta los ciegos, así también la luz del Cielo no quiere mostrarse a las sombras de que hablo; pues todas tienen sus párpados atravesados y cosidos por un alambre, como se hace con los gavilanes salvajes para domesticarlos.\"},{\"heading\":false,\"text\":\"Mientras iba andando, me parecía inferir una ofensa, viendo a otros sin ser visto de ellos; por lo cual me volví hacia mi prudente Consejero. Bien sabía él lo que quería significar mi silencio; así es que no esperó mi pregunta, sino que me dijo:\"},{\"heading\":false,\"text\":\"--Habla, y sé breve y sensato.\"},{\"heading\":false,\"text\":\"Virgilio caminaba a mi lado por aquella parte de la calzada desde donde se podía caer, pues no estaba resguardada por ningún pretil: hacia mi otro lado estaban las devotas sombras, las cuales lanzaban con tanta fuerza las lágrimas a través de su horrible costura, que bañaban con ellas sus mejillas. Me dirigí a ellas y les dije:\"},{\"heading\":false,\"text\":\"--¡Oh gente segura de ver la más alta luz del cielo, único fin a que aspira vuestro deseo! Así la gracia disipe pronto las impurezas de vuestra conciencia, de tal suerte que descienda por ella puro y claro el río de vuestra mente, decidme (que me será muy dulce y grato) si entre vosotras hay algún alma que sea latina, a quien quizá podrá serle útil que yo la conozca.\"},{\"heading\":false,\"text\":\"--¡Oh hermano mío!, todas nosotras somos ciudadanas de una verdadera ciudad; pero tú querrás decir si hay alguna que haya peregrinado en vida por Italia.\"},{\"heading\":false,\"text\":\"Estas palabras creí percibir en respuesta a las mías, algo más adelante del sitio en que me encontraba; por lo cual me hice oír de nuevo más allá. Entre las demás sombras vi una que parecía estar a la expectativa; y si alguien pregunta cómo podía insinuarse, le diré que levantando en alto la barba, como hacen los ciegos.\"},{\"heading\":false,\"text\":\"--Espíritu--le dije--, que te abates para subir, si eres aquel que me ha respondido, dame cuenta de tu país y de tu nombre.\"},{\"heading\":false,\"text\":\"--Yo fuí sienesa--respondió--, y estoy aquí con estos otros purificando mi vida culpable, y suplicando con lágrimas a Aquél que debe concedérsenos. No fuí sabia, por más que me llamaran \\\"Sapía,\\\" y me alegraron más los males ajenos que mis propias venturas. Y porque no creas que te engaño, oye si fuí tan necia como te digo. Descendía ya por la pendiente de mis años, cuando mis conciudadanos se encontraron cerca de Colle a la vista de sus adversarios, y yo rogaba a Dios lo mismo que El quería. Fueron destrozados, y reducidos en aquel sitio al paso amargo de la fuga; y al ver aquella caza, tuve tal contento, que ningún otro puede igualársele. Mientras tanto elevaba al cielo mi atrevida faz gritando a Dios: \\\"Ahora ya no te temo,\\\" como hizo el mirlo engañado en invierno por algunos días apacibles. Hacia el fin de mi vida quise reconciliarme con Dios; y aún no habría comenzado a pagar mi deuda por medio de la penitencia, si no fuera porque me tuvo presente en sus santas oraciones Pedro Pettinagno, que se apiadó de mí, movido de su caridad. Pero ¿quién eres tú, que vas informándote de esa suerte de nuestra condición, con los ojos libres, según creo, y que hablas respirando?\"},{\"heading\":false,\"text\":\"--También estarán mis ojos cosidos aquí--le dije--, pero por poco tiempo; pues el delito que cometí mirando con ellos envidiosamente ha sido pequeño. Mucho más miedo infunde a mi alma el castigo de abajo; pues ya siento gravitar sobre mí el peso de que van cargados los que allí están.\"},{\"heading\":false,\"text\":\"Ella me preguntó:\"},{\"heading\":false,\"text\":\"--¿Quién te ha conducido, pues, aquí arriba entre nosotros, si crees volver abajo?\"},{\"heading\":false,\"text\":\"Contestéle:\"},{\"heading\":false,\"text\":\"--Ese que está conmigo y no pronuncia una palabra. Vivo estoy; por lo cual dime, espíritu elegido, si quieres que allá mueva en tu favor aún los pies mortales.\"},{\"heading\":false,\"text\":\"--¡Oh!, eso sí que es una cosa nunca oída--repuso--, y una gran señal de que Dios te ama: ruégote, por tanto, que me auxilies con tus oraciones; y te suplico por aquello que más desees, que si vuelves a pisar la tierra de Toscana, me pongas en buen lugar con mis parientes. Los verás entre aquella gente vana, que confía en Talamone; y esa esperanza, más descabellada que la de encontrar la Diana, los perderá; pero los almirantes perderán más aún.\"}]},{\"title\":\"Purgatorio — canto decimocuarto\",\"blocks\":[{\"heading\":false,\"text\":\"¿Quién es ese que gira en torno de nuestro monte, antes de que la muerte le haya hecho emprender su vuelo, y abre y cierra los ojos según su voluntad?\"},{\"heading\":false,\"text\":\"--Ignoro quién sea; pero sé que no va solo: pregúntale tú que estás más próximo a él, y acógele con dulzura, de modo que le hagas hablar.\"},{\"heading\":false,\"text\":\"Así razonaban a mi derecha dos espíritus, apoyado uno contra otro: después levantaron la cabeza para dirigirme la palabra, y dijo uno de ellos:\"},{\"heading\":false,\"text\":\"--¡Oh alma que, encerrada aún en tu cuerpo, te encaminas hacia el Cielo! Consuélanos por caridad, y dinos de dónde vienes y quién eres; pues la gracia que de Dios has recibido nos causa el asombro que produce una cosa que no ha existido jamás.\"},{\"heading\":false,\"text\":\"Yo les contesté:\"},{\"heading\":false,\"text\":\"--Por en medio de la Toscana serpentea un riachuelo, que nace en Falterona, y al que no le bastan cien millas de curso: a orillas de este río he recibido mi persona: deciros quién soy yo, sería hablar en vano, porque mi nombre aún no es muy conocido.\"},{\"heading\":false,\"text\":\"--Si he penetrado bien tu entendimiento con el mío--me respondió el que me había preguntado--, hablas del Arno.\"},{\"heading\":false,\"text\":\"Y el otro le dijo:\"},{\"heading\":false,\"text\":\"--¿Por qué oculta el nombre de aquel río, como se hace con una cosa horrible?\"},{\"heading\":false,\"text\":\"Y la sombra a quien le preguntaban esto respondió como debía:\"},{\"heading\":false,\"text\":\"--No lo sé; pero es muy digno de desaparecer el nombre de tal valle; porque desde su origen (donde la alpestre cordillera de que está desprendido el Peloro es tan copiosa de aguas, que en pocos sitios lo será más) hasta el punto en que restituye lo que el cielo ha sacado del mar, a quien deben los ríos el caudal que va con ellos, todos sus pobladores, enemistados con la virtud, la persiguen como a una serpiente, ya sea por desventura del país, o ya por una mala costumbre que los arrastra; por lo cual tienen los habitantes de aquel mísero valle tan pervertida su naturaleza, que parece que Circe los haya apacentado. Aquel río lleva primero su débil curso por entre sucios puercos, más dignos de bellotas que de otro alimento condimentado para uso de los hombres. Llegando abajo, encuentra viles gozquecillos, más rabiosos de lo que permite su fuerza, y a quienes tuerce con desdén el hocico. Va descendiendo, y cuanto más acrecienta su caudal, tanto más encuentra los perros convertidos en lobos la maldecida y desdichada fosa: bajando luego por entre profundas gargantas, tropieza con las engañosas zorras, que no temen lazo que pueda cogerlas. No he de dejar de decirlo, aunque haya quien me oiga; y le convendrá a ése, con tal que se acuerde de lo que un espíritu de verdad me revela. Veo a tu sobrino, que se convierte en cazador cruel de aquellos lobos sobre la orilla del feroz río, y a todos los atemoriza. Vende por dinero su carne, aun estando viva: después los mata como si fuesen bueyes viejos, y quita a muchos la vida y a sí mismo el honor. Ensangrentado sale de la triste selva, dejándola de tal modo, que de aquí a mil años no volverá a su estado primitivo[65].\"},{\"heading\":false,\"text\":\"[65] En los puercos, perros, lobos y zorras de que habla en este párrafo ha simbolizado Dante respectivamente a los casentinos, aretinos, güelfos florentinos y pisanos. El cazador a que se alude es Fulcieri da Calboli, que, siendo en 1302 potestad de Florencia, fué inducido por los Negros a perseguir a los Blancos, a muchos de los cuales puso por dinero en manos de sus enemigos.\"},{\"heading\":false,\"text\":\"Como al anuncio de futuros males se turba el rostro del que lo escucha, venga de donde quiera el peligro que le amenace, así vi yo turbarse y entristecerse a la otra alma, que estaba vuelta escuchando, apenas hubo recapacitado aquellas palabras. El lenguaje de la una y el rostro de la otra excitaban en mí el deseo de saber sus nombres: híceles entre ruegos esta pregunta; por lo cual, el espíritu que antes me había hablado repuso:\"},{\"heading\":false,\"text\":\"--Quieres que yo condescienda en hacer por ti lo que tú no quieres hacer por mí; pero pues Dios permite que se trasluzca tanto su gracia en ti, no dejaré de satisfacer tus deseos. Sabe, pues, que yo soy Guido del Duca: de tal modo abrasó la envidia mi sangre, que cuando veía un hombre feliz, hubieras podido contemplar la lividez de mi rostro. Por eso ahora siego la mies de mi simiente.--¡Oh raza humana!, ¿por qué pones tu corazón en lo que requiere una posesión exclusiva? Este es Rinieri, honra y prez de la casa de Calboli, la cual no ha tenido después ningún heredero de sus virtudes. Y no es sólo su descendencia la que, entre el Po y los montes, el mar y el Reno, se encuentra hoy despojada de los bienes que entrañan la verdad y subliman el ánimo; pues dentro de esos límites todo el terreno está cubierto de plantas venenosas, de tal modo que tarde podrá volvérsele a meter en cultivo. ¿Dónde está el buen Licio y Enrique Manardi, Pedro Traversaro y Guido de Carpigna? ¡Oh, romañoles, raza bastardeada! ¿Cuándo nacerá en Bolonia un nuevo Fabbro? ¿Cuándo en Faenza echará raíces otro Bernardino de Fosco, hermoso tronco salido de una insignificante semilla? No te asombres, Toscano, si ves que lloro al recordar a Guido de Prata, y a Ugolino de Azzo, que vivió entre nosotros; a Federico Tignoso y a todos los suyos; a la familia Traversara y los Anastagi, casas ambas que están hoy desheredadas de la virtud de sus mayores: no te asombre mi duelo al recordar las damas y los caballeros, los afanes y agasajos que inspiraban amor y cortesía, allí donde han llegado a ser tan depravados los corazones. ¡Oh Brettinoro! ¿por qué no desapareciste cuando tu antigua familia y muchos de tus habitantes huyeron por no ser culpables? Bien hace Bagnacaval en no reproducirse; y por el contrario, hace mal Castrocaro y peor Conio, que se empeña en procrear tales condes. Los Pagani se portarán bien cuando huya el Demonio; pero no tanto que consigan dejar de sí un recuerdo puro. ¡Oh Ugolino de Fantoli!, tu nombre está bien seguro; pues no es de esperar que haya quien, degenerando, pueda obscurecerlo. Pero déjame, ¡oh Toscano!; que ahora me son más gratas las lágrimas que las palabras: tanto es lo que me ha oprimido la mente nuestra conversación.\"},{\"heading\":false,\"text\":\"Sabíamos que aquellas almas queridas nos oían andar; y pues que callaban, debíamos estar seguros del camino que seguíamos. Luego que andando nos encontramos solos, llegó directamente a nosotros una voz, que hendió el aire como un rayo, diciendo: \\\"El que me encuentre debe darme la muerte;\\\" y huyó como el trueno que se aleja, cuando de pronto se desgarra la nube. Apenas cesamos de oirla, percibimos otra, la cual retumbó con gran estrépito, semejante al trueno que sigue inmediatamente al relámpago: \\\"Yo soy Aglauro, que me convertí en piedra.\\\" Entonces, para unirme más al Poeta, dí un paso hacia atrás y no hacia adelante. Ya se había calmado el aire por todas partes, cuando él me dijo:\"},{\"heading\":false,\"text\":\"--Aquel fué el duro freno que debería contener al hombre en sus límites; pero mordéis tan fácilmente el cebo, que os atrae con su anzuelo el antiguo adversario, sirviendoos de poco el freno o el reclamo. El cielo os llama y gira en torno vuestro mostrándoos sus eternas bellezas, y sin embargo, vuestras miradas se dirijen hacia la Tierra; por lo cual os castiga Aquél que lo ve todo.\"}]},{\"title\":\"Purgatorio — canto decimoquinto\",\"blocks\":[{\"heading\":false,\"text\":\"Caminando ya el Sol hacia la noche, parecía quedarle por recorrer tanto espacio como el que media entre el principio del día y el punto donde aquel señala el término de la hora de tercia en la esfera, que, cual niño inquieto, se mueve continuamente: allí era ya la tarde, y aquí media noche. Los rayos solares nos herían de lleno en el rostro, porque habíamos dado tal vuelta en derredor de la montaña, que íbamos directamente hacia el Ocaso; cuando sentí que el resplandor deslumbraba mis ojos mucho más que antes; y siéndome desconocida la causa, me quedé estupefacto: levanté las manos, y me formé con ellas una sombrilla encima de las cejas, que es el preservativo contra el exceso de luz. Como cuando en el agua o en un espejo rebota el rayo luminoso, elevándose al lado opuesto de idéntica manera que desciende, y desviándose por ambas partes a igual distancia de la caída de la piedra, según demuestran la experiencia y el arte, así me pareció ser herido por una luz que delante de mí se reflejaba; por lo cual aparté de ella presurosamente los ojos.\"},{\"heading\":false,\"text\":\"--¿Qué es aquello, amado Padre, de que no puedo, por más que haga, resguardar mi vista--dije--, y que parece venir hacia nosotros?\"},{\"heading\":false,\"text\":\"--No te asombres si la familia del Cielo te deslumbra todavía--me respondió--: es un mensajero que viene a invitar a un hombre a que suba. En breve, no sólo podrás contemplar estas cosas sin molestia, sino que te serán tanto más deleitables, cuanto más dispuesta se halle tu naturaleza a sentirlas.\"},{\"heading\":false,\"text\":\"Luego que llegamos cerca del Angel bendito, con agradable voz nos dijo: \\\"Entrad por aquí a una escalera, que es menos empinada que las otras.\\\" Subíamos ya, dejando en pos de nosotros aquel círculo, cuando oímos cantar a nuestra espalda: \\\"Beati misericordes\\\" y \\\"Regocíjate tú que vences.\\\" Mi maestro y yo ascendíamos solos, y yo pensaba entretanto sacar provecho de sus palabras; por lo que, dirigiéndome a él, le pregunté:\"},{\"heading\":false,\"text\":\"--¿Qué quiso decir el espíritu de la Romanía al hablar de lo que requiere una posesión exclusiva?\"},{\"heading\":false,\"text\":\"Respondióme:\"},{\"heading\":false,\"text\":\"--Ahora conoce el daño que causa su principal pecado: así, pues, no debes admirarte si le condena, a fin de que haya menos que llorar por él; porque si vuestros deseos se cifran en bienes que puedan disminuirse dando a otros participación en ellos, la envidia excita vuestros pulmones a suspirar; pero si el amor de la suprema esfera dirigiese hacia el Cielo vuestros deseos, no abrigaríais tal temor en vuestro corazón; pues cuanto más se dice allí \\\"lo nuestro,\\\" tanto mayor es el bien que posee cada cual, y mayor caridad arde en aquel recinto.\"},{\"heading\":false,\"text\":\"--Menos contento estoy que si me hubiese callado--dije--; y ahora ofuscan más dudas mi mente. ¿Cómo puede ser que un bien distribuído entre muchos haga más ricos a sus poseedores, que poseyéndolo unos pocos?\"},{\"heading\":false,\"text\":\"A lo que me contestó:\"},{\"heading\":false,\"text\":\"--Por fijar siempre tu pensamiento en las cosas terrenales deduces obscuridad y error de las claras verdades que te demuestro. Aquel bien infinito e inefable que está arriba, se lanza hacia el amor, como un rayo de luz a un cuerpo fúlgido, comunicándose tanto más cuanto mayor es el ardor que encuentra; de modo que la eterna virtud crece sobre la caridad a medida que ésta se aumenta; por lo cual, cuanto mayor número de almas se dirigen a él, tanto más amor hay allá arriba, y más allí se ama, reflejándose este amor de una a otra alma como la luz entre dos espejos. Si no te satisfacen mis razones, ya verás a Beatriz, y ella acallará por completo ese deseo y cualquier otro que tengas. Avanza, pues, para que pronto desaparezcan, como ya han desaparecido dos, esas cinco señales, que sólo se borran por medio de lágrimas.\"},{\"heading\":false,\"text\":\"Cuando iba a decir: \\\"Me has dejado satisfecho,\\\" observé que habíamos llegado al otro círculo; por lo cual, ocupado en pasear por él mis anhelantes miradas, guardé silencio. Allí me pareció que era súbitamente arrebatado en éxtasis, y que veía un templo con muchas personas, y una mujer a la entrada exclamando, en la dulce actitud de una madre: \\\"Hijo mío, ¿por qué has obrado así con nosotros? Tu Padre y yo te buscábamos angustiados.\\\" Cuando se calló, desapareció lo que antes se me había aparecido. Después se ofreció a mi vista otra, por cuyas mejillas se deslizaba aquel agua que destila el dolor, cuando procede de un gran despecho contra otro; ésta decía: \\\"Si eres señor de la ciudad cuyo nombre originó tanta contienda entre los dioses, y en la que toda ciencia destella[66], véngate de los atrevidos brazos que abrazaron a nuestra hija, ¡oh Pisístrato!\\\" Y este señor bondadoso y clemente le respondía con rostro sereno: \\\"¿Qué haremos con el que nos quiere mal, si condenamos al que nos ama?\\\" Después vi a varios hombres abrasados por la ira, matando a pedradas a un joven[67], y diciéndose a grandes gritos unos a otros: \\\"¡Martirízale, martirízale!\\\" Y le contemplaba encorvado hacia el suelo bajo el peso de la muerte que ya le derribaba; pero haciendo de sus ojos puertas para llegar al cielo, y rogando al Señor en medio de tal martirio y con aquel aspecto que excita a la piedad, que perdonase a sus perseguidores. Cuando mi alma volvió de fuera a las cosas que fuera de ella son verdaderas, reconocí mis errores que, sin embargo, no eran falsos. Mi Guía, que me veía hacer lo que un hombre que sale de un sueño, me dijo:\"},{\"heading\":false,\"text\":\"--¿Qué tienes, que no puedes sostenerte? Has andado más de media legua con los ojos cerrados y con paso vacilante, como el que está dominado por el vino o por el sueño.\"},{\"heading\":false,\"text\":\"[66] El protomártir San Esteban.\"},{\"heading\":false,\"text\":\"[67] Atenas, por cuyo nombre trabaron gran contienda Neptuno y Minerva.\"},{\"heading\":false,\"text\":\"--¡Oh amado Padre mío!--dije yo--; si me prestas atención, te diré lo que se me ha aparecido cuando mis piernas vacilaban.\"},{\"heading\":false,\"text\":\"Y él a su vez:\"},{\"heading\":false,\"text\":\"--Aunque tuvieras cien máscaras que ocultaran tu rostro, adivinaría yo hasta tus menores pensamientos. Lo que has visto te ha sido revelado para que no te excuses de abrir el corazón al agua de la paz, que mana de la fuente eterna. Te he preguntado \\\"¿qué tienes?,\\\" no porque me dijeras lo que hace el que tiene los ojos entornados cuando se ha apoderado algún sopor de su cuerpo, sino para que tus pies recobrasen fuerzas: es preciso estimular así a los perezosos, demasiado lentos en emplear el tiempo de sus vigilias, cuando, una vez despiertos, recobran el imperio de su voluntad.\"},{\"heading\":false,\"text\":\"Seguíamos nuestro camino, cuando ya obscurecía, mirando atentamente lo más allá que podían nuestros ojos por entre los luminosos rayos vespertinos, cuando vimos adelantarse poco a poco hacia nosotros una humareda obscura como la noche, sin que hubiese por allí un sitio donde guarecerse de ella, y que nos privó del uso de la vista y del aire puro.\"}]},{\"title\":\"Purgatorio — canto decimosexto\",\"blocks\":[{\"heading\":false,\"text\":\"La obscuridad del Infierno, y la de la noche privada de todo planeta bajo un mezquino cielo, entenebrecido por las nubes hasta lo sumo, no echarían sobre mi vista un velo tan denso como aquel humo que allí nos envolvió; siendo tal la sensación de su punzante aspereza, que no podían los ojos permanecer abiertos; por lo cual, mi sabio y fiel Acompañante se acercó a mí, ofreciéndome su hombro. Como va el ciego detrás de su lazarillo para no extraviarse, ni tropezar en algo que le ofenda o acaso le origine la muerte, así caminaba yo a través de aquel aire fosco y acre, atento a la voz de mi Guía, que únicamente iba diciendo: \\\"Cuida de no separarte de mí.\\\" Oía yo voces, cada una de las cuales parecía rogar a fin de obtener paz y misericordia del Cordero de Dios, que quita los pecados. El principio de su oración era solamente \\\"Agnus Dei;\\\" todos pronunciaban estas palabras a un mismo tiempo y con tan igual tono, que parecía existir entre ellos una perfecta concordia.\"},{\"heading\":false,\"text\":\"--Maestro--dije--; ¿son espíritus esos que oigo?\"},{\"heading\":false,\"text\":\"--Lo has acertado--contestó--; van desatando el nudo de la ira.\"},{\"heading\":false,\"text\":\"--¿Quién eres tú, que hiendes nuestro humo, y hablas de nosotros como si contaras aún el tiempo por calendas?\"},{\"heading\":false,\"text\":\"De esta suerte habló una voz; por lo cual el Maestro me dijo:\"},{\"heading\":false,\"text\":\"Responde, y pregúntale si por aquí se va arriba.\"},{\"heading\":false,\"text\":\"Entonces dije yo:\"},{\"heading\":false,\"text\":\"--¡Oh criatura, que te purificas para volver a presentarte hermosa ante Aquél que te hizo! Oirás cosas maravillosas si quieres seguirme.\"},{\"heading\":false,\"text\":\"--Te seguiré cuanto me está permitido--me contestó--; y si el humo impide que nos veamos, el oído nos aproximará a falta de la vista.\"},{\"heading\":false,\"text\":\"Empecé, pues, de esta manera:\"},{\"heading\":false,\"text\":\"--Me dirijo hacia arriba con la forma que la muerte desvanece, y he llegado hasta aquí a través de las penas del Infierno. Y si Dios me ha acogido en su gracia de tal modo, que quiere que yo vea su corte por un medio tan distinto de lo usual, no me ocultes quién fuiste antes de morir, sino dímelo: dime también si voy bien por aquí hacia la subida, y tus palabras nos servirán de guía.\"},{\"heading\":false,\"text\":\"--Fuí lombardo, y me llamé Marco: conocí el mundo; y amé aquella virtud hacia la cual nadie dirige hoy su mira. Para llegar a lo alto, sigue en derechura por donde vas.\"},{\"heading\":false,\"text\":\"Así respondió, añadiendo después:\"},{\"heading\":false,\"text\":\"--Te suplico que ruegues por mí cuando estés arriba.\"},{\"heading\":false,\"text\":\"A lo que le contesté:\"},{\"heading\":false,\"text\":\"--Por mi fe te prometo que haré lo que me pides; pero me veo envuelto en una duda, que no me es dado aclarar. Primeramente era sencilla, más ahora se ha duplicado con tus palabras, que unidas a las que he oído en otra parte, me certifican un mismo hecho. El mundo está, pues, exhausto de toda virtud, como me indicas, y sembrado y cubierto de maldad; pero te ruego que me digas la causa, de modo que yo pueda verla y mostrarla a los demás; pues unos la hacen depender del cielo, y otros de aquí abajo.\"},{\"heading\":false,\"text\":\"Antes de contestar exhaló un profundo suspiro, que terminó en un ¡ay! doloroso, y después dijo:\"},{\"heading\":false,\"text\":\"--Hermano, el mundo es ciego, y se conoce que tú vienes de él. Vosotros los vivos hacéis estribar toda causa en el cielo, como si él imprimiera por necesidad su movimiento a todas las cosas. Si así fuese, quedaría destruído en vosotros el libre albedrío, y no sería justo que se retribuyera el bien con goces y alegrías, y el mal con llanto y luto. El cielo inicia vuestros movimientos: no quiero decir todos; pero, aunque así lo dijese, os ha dado luz para distinguir el bien y el mal. Os ha dado también el libre albedrío, que aun cuando se fatigue luchando en los primeros combates con el cielo, después lo vence todo, si persevera en el buen propósito. A mayor fuerza y a naturaleza mejor estáis sometidos, sin dejar de ser libres; y ella crea vuestro espíritu, que no está bajo el dominio del cielo. Así pues, si el mundo se aparta del verdadero camino, vuestra es la culpa; que en vosotros debe buscarse, y ahora te lo probaré con toda veracidad. Sale el alma de manos de su Creador, que la acaricia antes de que exista, semejante al niño que entre el llanto y la risa balbucea; y es entonces una simplecilla, que nada sabe, y solamente movida por el instinto de la felicidad, se inclina gustosa hacia lo que la contenta y regocija. Desde luego siente placer en los bienes más mezquinos; pero en esto se engaña, y corre tras ellos, si no tiene guía o freno que tuerza su inclinación. Por eso es necesario establecer leyes que sirvan de freno, y tener un rey que sepa discernir al menos la torre de la verdadera ciudad. Las leyes existen; pero ¿quién se cuida de su cumplimiento? Nadie; porque el pastor que precede a las almas puede rumiar, pero no tiene la pezuña hendida; por lo cual, viendo todo el rebaño a su pastor cebarse únicamente en aquellos bienes de que él es tan codicioso, se apacienta de lo mismo y no pide más. Bien puedes ver, por esto, que en el mal gobierno estriba la causa de que el mundo sea culpable, y no en que vuestra naturaleza esté corrompida. Roma, que hizo bueno al mundo, solía tener dos soles, que hacían ver uno y otro camino, el del mundo y el de Dios. Uno de los dos soles ha obscurecido al otro, y la espada se ha unido al báculo pastoral: así juntos, por fuerza deben ir las cosas de mala manera; porque estando unidos, no se temen mutuamente. Si no me prestas crédito, pon mientes en la espiga; pues toda hierba se conoce por su semilla. En el país que bañan el Po y el Adigio solía encontrase valor y cortesía, antes de que Federico tuviese contiendas. Hoy, todo aquel que dejara de acercarse a aquellas provincias por vergüenza de hablar con hombres probos, puede pasar por ellas, seguro de que no hallará ninguno. Bien es verdad que aun existen allí tres ancianos, en quienes la edad antigua reprende a la moderna, y les parece que Dios tarda en llamarlos a mejor vida: son éstos Conrado de Palazzo, el buen Gerardo, y Guido de Castel, a quien mejor le llaman al estilo francés el lombardo sencillo. En el día la Iglesia de Roma, para confundir en sí dos gobiernos, cae en el lodo ensuciándose a sí misma y a su carga.\"},{\"heading\":false,\"text\":\"--¡Oh Marco mío!--dije yo--; razonas bien: y ahora comprendo por qué fueron excluídos de heredar los hijos de Leví. Pero ¿qué Gerardo es ése a quien tienes por un sabio, ese resto de una raza extinguida, que es un reproche para este siglo salvaje?\"},{\"heading\":false,\"text\":\"--O tus palabras me engañan, o me tientan--respondióme--; porque, a pesar de hablarme en toscano, parece que no sepas nada del buen Gerardo. Yo no le conozco ningún sobrenombre, a no ser que lo tome de su hija Gaya. Dios sea con vosotros, que no puedo seguiros más. Mira el albor que ya clarea, brillando a través del humo: me es preciso partir antes de que aparezca el Angel que está allí.\"},{\"heading\":false,\"text\":\"Así dijo, y no quiso escuchar más.\"}]},{\"title\":\"Purgatorio — canto decimoseptimo\",\"blocks\":[{\"heading\":false,\"text\":\"Lector, si alguna vez te ha sorprendido la niebla en los Alpes, de modo que no vieses a través de ella sino como el topo a través de la membrana que cubre sus ojos, recuerda cuán débilmente penetra el globo solar por entre los húmedos y densos vapores, cuando éstos empiezan a enrarecerse, y tu imaginación podrá fácilmente figurarse cómo volví yo a ver el Sol, que estaba ya próximo a su ocaso. Así pues, caminando al igual de mi fiel Maestro, salimos fuera de la nube de humo a los rayos luminosos, que ya se habían extinguido en la falda de la montaña.\"},{\"heading\":false,\"text\":\"¡Oh fantasía, que de tal modo nos arrebatas a veces fuera de nosotros mismos, que nada siente el hombre aunque suenen mil trompetas en torno suyo! ¿Quién te anima cuando no recibes impresión alguna de los sentidos? sin duda te anima una luz que se forma en el cielo, y que desciende por sí misma, o por la voluntad divina que nos la envía. En mi imaginación aparecieron las huellas de la impiedad de aquélla, que se transformó en el pájaro que más se deleita cantando. Entonces mi espíritu se reconcentró tanto en sí mismo, que no llegaba hasta él ninguna cosa exterior. Después descendió a mi exaltada fantasía la imagen desdeñosa y fiera de un crucificado, a quien veía morir de aquel modo. Junto a él estaban el grande Asuero, Esther su esposa, y el justo Mardoqueo, que fué tan recto en sus obras y en sus palabras. Cuando se desvaneció por sí misma aquella visión, como una burbuja a la que falta el agua de que estaba formada, surgió a mi imaginación una doncella que, llorando desconsolada, decía: \\\"¡Oh Reina!, ¿por qué tu cólera te redujo a la nada? Te has dado muerte por no perder a Lavinia: sin embargo, me has perdido; y yo soy la que lloro, madre, tu pérdida antes que la de otro.\\\"\"},{\"heading\":false,\"text\":\"Así como se interrumpe el sueño, cuando una nueva luz hiere de improviso nuestros ojos cerrados, y aunque interrumpido se agita antes de morir enteramente, así terminaron mis visiones tan pronto como me dió en el rostro una claridad mucho mayor de la que estamos acostumbrados a ver. Me volví a uno y otro lado para examinar el sitio en que me encontraba, cuando oí una voz que decía: \\\"Por aquí se sube.\\\" Aquella voz hizo que me olvidase de todo, y despertó en mí tan vivo deseo de mirar quién era el que hablaba, que no habría descansado hasta averiguarlo; pero me faltó allí la facultad de ver, como sucede cuando el Sol nos deslumbra y se vela a nuestros ojos con el esplendor de sus rayos.\"},{\"heading\":false,\"text\":\"--Este--me dijo mi Maestro--es un espíritu divino, que se oculta en su propia luz, y que nos indica la vía para ir arriba, sin que se lo roguemos. Hace con nosotros lo que el hombre consigo mismo; pues el que ve una necesidad, y aguarda que le supliquen, ya se prepara malignamente a rehusar todo socorro. Ahora nuestros pies deben aprestarse a obedecer tan cortés invitación: apresurémonos, pues, a subir antes que obscurezca, porque después no podríamos hacerlo hasta la nueva aurora.\"},{\"heading\":false,\"text\":\"Así dijo mi Guía, y ambos dirigimos nuestros pasos hacia una escalera: en cuanto estuve en la primera grada, sentí junto a mí como un movimiento de alas, que aventaba mi rostro, y oí decir: \\\"Beati pacifici,\\\" que carecen de pecaminosa ira. Estaban ya tan elevados sobre nosotros los últimos rayos a quienes sigue la noche, que las estrellas aparecían por muchas partes. \\\"¡Oh valor mío!, ¿por qué así me abandonas?,\\\" decía yo entre mí, sintiendo que me flaqueaban las piernas. Nos encontrábamos donde concluía la escalera, y estábamos parados, como la nave que llega a la playa: escuché un momento por si oía algo en el nuevo círculo; y después, dirigiéndome hacia mi Maestro, le dije:\"},{\"heading\":false,\"text\":\"--Dulce Padre mío, ¿qué ofensa se purifica en el círculo en que estamos? Ya que se detienen nuestros pies, no detengas tus palabras.\"},{\"heading\":false,\"text\":\"Me contestó:\"},{\"heading\":false,\"text\":\"--El amor del bien, que no ha cumplido su deber, aquí se reintegra: aquí se castiga al tardo remero. Para que lo entiendas más claramente, dirige tu pensamiento hacia mí, y recogerás algún buen fruto de nuestra detención. Hijo mío--empezó a decir--, ni el Creador, ni criatura alguna carecieron jamás de amor, bien sea natural o racional, según te consta. El natural no se equivocó nunca: el otro puede errar, por dirigirse a un mal objeto, por exceso o por falta de fervor. Mientras se dirige a los principales bienes, y se modera en su afecto a los secundarios, no puede ser causa de censurable deleite; pero cuando se inclina al mal, o se lanza al bien con mayor o menor solicitud de la que debe, entonces la criatura se vuelve contra su Creador. De aquí puedes deducir que el amor es en vosotros la semilla de toda virtud, y de toda acción que merezca castigo. Ahora bien, como el amor no puede nunca renunciar a la dicha del sujeto en quien reside, todas las cosas están preservadas de su propio odio; y como no se concibe que ningún ser creado pueda existir por sí solo, ni separado del Sér primero, es imposible todo sentimiento que tienda a odiar a éste. Resulta, pues, si mi deducción es lógica, que el mal que se desea es contra el prójimo; y este amor nace de tres modos en vuestro frágil barro. Hay quien espera elevarse sobre la ruina de su vecino, y sólo por esto desea que se derrumbe desde la altura de su grandeza; hay quien teme perder mando, gracia, honor y fama ante la elevación de otro, y esto le causa tal disgusto, que anhela lo contrario; y en fin, hay quien, por haber recibido alguna injuria, se irrita de tal suerte, que arde en sed de venganza, y únicamente piensa en hacer daño a su contrario. Este triforme amor es el que hemos visto llorar en los círculos inferiores. Ahora quiero que conozcas el otro amor que corre al bien sin orden ni medida. Cada cual concibe confusamente y desea un bien en el que se recrea el alma; y por eso se esfuerzan todos para alcanzarlo. Si vuestro amor es lento en dirigirse o en adquirir aquel bien, este círculo os da el debido castigo, aun después de vuestro arrepentimiento en vida. Existe otro bien que no hace al hombre dichoso: no es la felicidad, no es la buena esencia, el fruto y la raíz de todo bien. El amor que se entrega demasiado a ese bien, se castiga en los tres círculos superiores a éste; pero no te diré el modo cómo está hecha esta división, a fin de que tú lo averigües.\"}]},{\"title\":\"Purgatorio — canto decimoctavo\",\"blocks\":[{\"heading\":false,\"text\":\"El gran doctor había terminado su razonamiento, y miraba atentamente a mi ojos para ver si me dejaba satisfecho; y yo, que me sentía excitado por una nueva sed, callaba exteriormente, pero decía en mi interior: \\\"Quizá le cansen mis numerosas preguntas.\\\" Mas aquel Padre veraz, que adivinó el tímido deseo que no me atrevía a descubrir, hablando, me dió aliento para hablar; por lo que le dije:\"},{\"heading\":false,\"text\":\"--Maestro, mi vista se aviva de tal modo con tu luz, que discierne claramente cuanto tu razón abarca o describe: por eso te ruego, dulce y querido Padre, que me definas el Amor al que atribuyes toda buena y mala acción.\"},{\"heading\":false,\"text\":\"--Dirige hacia mí--me dijo--las penetrantes miradas de tu inteligencia y te será manifiesto el error de los ciegos que se convierten en guías. El alma, que ha sido creada con predisposición al amor, se lanza hacia todo lo agradable, tan pronto como es incitada por el placer a ponerse en acción. Vuestra facultad aprehensiva recibe la imagen o la especie de un objeto exterior, y la desenvuelve dentro de vosotros, de tal modo que induce a vuestro ánimo a dirigirse hacia dicho objeto; y si al hacerlo se abandona a él, ese abandono es amor, y ese amor es la naturaleza que de nuevo se une a vosotros, por efecto del placer. Después, así como el fuego se dirige hacia lo alto, a causa de su forma, que ha sido hecha para subir allá donde más se conserva en su materia primitiva, así también el alma apasionada se entrega al deseo, que es el movimiento espiritual, y no sosiega hasta que goza de la cosa amada. Por lo dicho puedes comprender cuánto se oculta la verdad a los que afirman que todo amor tiene en sí algo de laudable, quizá porque creen que su materia es siempre buena; pero no todos los sellos estampados en cera son buenos, por más que la cera lo sea.\"},{\"heading\":false,\"text\":\"--Tus palabras y mi inteligencia que las ha seguido--le respondí--, me han descubierto lo que es el amor: pero eso mismo me ha llenado de nuevas dudas; porque si el amor nace en nosotros por efecto de las cosas exteriores, sin que el alma proceda de otro modo, ésta no tendrá ningún mérito en seguir un camino recto o tortuoso.\"},{\"heading\":false,\"text\":\"Respondióme:\"},{\"heading\":false,\"text\":\"--Puedo decirte todo cuanto en ello ve nuestra razón: respecto a lo demás, espera llegar hasta Beatriz, porque esto es materia de fe. Toda forma substancial, que es distinta de la materia, y que sin embargo está unida a ella, contiene una virtud que le es particular; la cual, sin las obras, no se siente, ni se demuestra sino por los efectos, como la vida de la planta por su verde follaje. El hombre ignora de dónde proceden el conocimiento de las ideas primarias y el afecto a las cosas que primeramente apetece, los cuales existen en vosotros como en las abejas la inclinación a fabricar miel: en estos primeros deseos no cabe alabanza ni censura. Mas por cuanto a ellos se agregan todos los demás deseos, es innata en vosotros la virtud que aconseja, y que debe custodiar los umbrales del consentimiento. Ella es el principio de donde sacáis la ocasión de contraer méritos, según que acoge o rechaza los buenos o los malos amores. Los que razonando llegaron al fondo de las cosas, han reconocido esa libertad innata, y han dejado al mundo doctrinas morales. Supongamos, pues, que nazca por fuerza necesaria todo amor que se enciende en vosotros; siempre tenéis la potestad de contenerlo. Esa noble virtud es lo que Beatriz entiende por libre albedrío; y debes procurar tenerlo presente, si acaso te habla de ello.\"},{\"heading\":false,\"text\":\"La Luna, que salió tarde y casi a media noche, hacía que nos parecieran más escasas las estrellas: semejante a un caldero encendido, corría contra el cielo por aquel camino que inflama el Sol cuando el habitante de Roma le ve caer entre Córcega y Cerdeña; y la Sombra gentil, por quien Piétola goza de más fama que la ciudad de Mantua, se hallaba descargada del peso de mis preguntas: por lo cual yo, que había recibido claras y sólidas razones con respecto a todas ellas, estaba como el hombre que sorprendido por el sueño no piensa en nada. Pero esta soñolencia me fué desvanecida de improviso por mucha gente que avanzaba ya detrás de nosotros; y así como en otro tiempo el Ismeno y el Asopo vieron correr de noche por sus orillas una muchedumbre furiosa de tebanos para tener propicio a Baco, así avanzaban por aquel círculo, según pude ver, los que eran estimulados por una buena voluntad y un justo amor. En breve llegaron hasta nosotros; porque toda aquella gran turba venía corriendo, y los dos de delante gritaban llorando: \\\"María se dirigió con suma celeridad a la montaña; y César, por subyugar a Ilerda, voló a Marsella, y después pasó a España.\\\" \\\"Pronto, pronto, exclamaban otros en pos de ellos; que el tiempo no se pierda por poco amor, a fin de que el anhelo de las buenas obras haga reverdecer la gracia.\\\"\"},{\"heading\":false,\"text\":\"--¡Oh almas, en quienes un fervor ardiente compensa ahora quizá la negligencia y la tardanza, que por tibieza empleasteis para el bien! Este, que vive aún (y no os engaño), quiere ir allá arriba en cuanto el Sol brille de nuevo: decidnos, pues, dónde está la subida.\"},{\"heading\":false,\"text\":\"Tales fueron las palabras de mi Guía; y uno de aquellos espíritus dijo:\"},{\"heading\":false,\"text\":\"--Ven tras de nosotros, y la encontrarás. Estamos tan deseosos de avanzar, que no podemos detenernos: perdona, pues, si lo que hacemos por justo castigo te parece una descortesía. Yo fuí abad en San Zenón de Verona, durante el imperio del buen Barbarroja, de quien todavía se lamenta Milán. Hay quien tiene ya un pie en la fosa, que pronto llorará por aquel monasterio, entristeciéndole el poder que allí tuvo; porque en lugar de su verdadero pastor, ha puesto en él a un hijo suyo, malo de cuerpo, peor aún del espíritu, y nacido de mal consorcio.\"},{\"heading\":false,\"text\":\"No sé si dijo más, o si se calló; tan lejos se encontraba ya de nosotros; pero esto es lo que oí, y me pareció bien retenerlo en la memoria. Y aquél que era el socorro de todas mis necesidades dijo:\"},{\"heading\":false,\"text\":\"--Vuélvete hacia aquí; mira dos que vienen mordiendo a la Pereza.\"},{\"heading\":false,\"text\":\"Estos iban diciendo detrás de todos: \\\"La nación por quien se abrió el mar, murió antes de que sus descendientes viesen el Jordán;[68] y aquella gente que no quiso compartir hasta el fin las fatigas del hijo de Anquises, se ofreció por sí misma a una vida sin gloria.\\\"[69]\"},{\"heading\":false,\"text\":\"[68] El pueblo hebreo.\"},{\"heading\":false,\"text\":\"[69] Los troyanos.\"},{\"heading\":false,\"text\":\"En seguida, cuando aquellas sombras se alejaron tanto de nosotros, que ya no podíamos verlas, me asaltó una nueva idea, de la que nacieron otras varias; y mi imaginación empezó a divagar de tal modo de una a otra, que por alucinación cerré los ojos, y mi pensamiento se trocó pronto en sueño.\"}]},{\"title\":\"Purgatorio — canto decimonono\",\"blocks\":[{\"heading\":false,\"text\":\"A la hora en que el calor del día, vencido por la tierra y por Saturno acaso, no puede ya templar el frío de la Luna; cuando los geománticos ven, antes del alba, elevarse en Oriente \\\"su mayor fortuna\\\"[70] por aquel camino que para ella permanece poco tiempo obscuro, se me apareció en sueños una mujer tartamuda, bizca, con los pies torcidos, manca y de amarillento color. Yo la miraba; y así como el Sol reanima los miembros entorpecidos por el frío de la noche, de igual suerte mi mirada hacía expedita su lengua, y erguía su cuerpo en poco tiempo, colorándole el marchito rostro, como requiere el amor. Cuando tuvo la lengua suelta, empezó a cantar de tal modo, que con trabajo hubiera podido separar mi atención de ella. \\\"Yo soy, cantaba, yo soy dulce Sirena, que distraigo a los marineros en medio del mar; tanto es el placer que hago sentir. Con mi canto aparté a Ulises de su camino inseguro; y el que conmigo se aviene, rara vez se va; de tal modo le fascino.\\\" Aun no se había cerrado su boca, cuando apareció a mi lado una mujer santa, pronta a confundirla: \\\"¡Oh Virgilio, Virgilio! ¿Quién es ésa?,\\\" decía con altivez; y él se acercaba con los ojos fijos solamente en aquella honesta mujer. Cogió a la otra, y desgarrando sus vestiduras, la descubrió por delante y me mostró su vientre. La pestilencia que de él salía me despertó. Volví los ojos y el buen Virgilio me dijo:\"},{\"heading\":false,\"text\":\"Lo menos te he llamado tres veces: levántate y ven; busquemos la abertura por donde has de entrar.\"},{\"heading\":false,\"text\":\"[70] Los geománticos solían trazar figuras de puntos hechos a la ventura, y cuando resultaba una parecida a la de las estrellas que forman lo último del signo Acuario y el principio del de Piscis, la llamaban su mayor fortuna.\"},{\"heading\":false,\"text\":\"Me levanté: todos los círculos del sagrado monte estaban ya inundados por la luz del día, y continuamos caminando teniendo el Sol a nuestra espalda. Mientras le seguía, llevaba yo la frente como aquel a quien abruman los pensamientos, que de sí mismo hace un arco de puente, cuando oí decir: \\\"Venid, por aquí se pasa.\\\" Estas palabras fueron pronunciadas con un tono suave y benigno, como no se oye en esta región mortal. Con las alas abiertas, que parecían de cisne, el que nos había hablado así nos dirigió hacia arriba por entre las dos laderas del áspero peñasco. Movió después sus plumas, y aventó mi frente, afirmando que son bienaventurados \\\"qui lugent,\\\" porque sus almas serán ricas de consuelo.\"},{\"heading\":false,\"text\":\"--¿Qué tienes, que sólo miras hacia el suelo?--me preguntó mi Guía, cuando estuvimos poco más arriba del Angel.\"},{\"heading\":false,\"text\":\"Y yo le contesté:\"},{\"heading\":false,\"text\":\"--Me hace ir de este modo, suspenso y caviloso, una visión reciente, la cual me atrae hacia sí, de suerte que no puedo eximirme de pensar en ella.\"},{\"heading\":false,\"text\":\"--¿Has visto--me dijo--la antigua hechicera, causante única del llanto que más arriba de donde estamos se vierte? ¿Has visto cómo el hombre puede desprenderse de ella? Bástete, pues, eso, y apresura el paso; vuelve tus ojos al reclamo de las magníficas esferas, que hace girar el Rey eterno.\"},{\"heading\":false,\"text\":\"Como el halcón, que, mirando primero a sus pies, acude al grito del cazador y tiende el vuelo, atraído por el deseo de la presa, lo mismo hice yo, recorriendo la hendedura de la roca destinada a dar paso a los que suben, sin detenerme hasta llegar al punto donde se camina en redondo. Cuando hube salido al quinto círculo, vi algunas almas, que lloraban tendidas en el suelo boca abajo; y las oí exclamar con tan fuertes suspiros, que apenas se entendían las palabras: \\\"Adhæsit pavimento anima mea.\\\"[71]\"},{\"heading\":false,\"text\":\"[71] Palabras del salmo CXVIII, con las que aquellas almas expresan el apego que tuvieron a los cosas terrenas.\"},{\"heading\":false,\"text\":\"--¡Oh elegidos de Dios, cuyos padecimientos son suavizados por la resignación y la esperanza! Dirigidnos hacia las altas gradas.\"},{\"heading\":false,\"text\":\"--Si venís libres de yacer aquí con nosotros, y queréis encontrar más pronto la subida, caminad siempre llevando vuestra derecha hacia fuera del círculo.\"},{\"heading\":false,\"text\":\"Tal fué la súplica del Poeta, y tal la contestación que le dieron algo más adelante de nosotros; pudiendo yo conocer por el sonido de las palabras cuál era el que había hablado: volví entonces los ojos hacia mi Señor, quien con un gesto complaciente consintió en lo que pedía la expresión de mi deseo. Cuando pude obrar a mi gusto, me acerqué a aquella criatura, que había llamado mi atención con sus palabras, diciéndole:\"},{\"heading\":false,\"text\":\"--Espíritu, en quien el llanto madura la expiación, sin la cual no se puede llegar hasta Dios, suspende un momento por mí tu mayor cuidado. Dime quién fuiste, y por qué tenéis todos la espalda vuelta hacia arriba, y si quieres que pida por ti alguna cosa en el mundo de donde salí vivo.\"},{\"heading\":false,\"text\":\"Me respondió:\"},{\"heading\":false,\"text\":\"--Sabrás por qué ordena el Cielo que tengamos la espalda vuelta hacia él; pero antes \\\"scias quod ego fui successor Petri.\\\"[72] Entre Sesti y Chiavari se interna un hermoso río, de cuyo nombre toma origen el título de mi sangre. Un mes y poco más pude experimentar cuán pesado es el gran manto al que lo preserva del lodo; pues cualquier otra carga parece una pluma. Mi conversión ¡ay de mí! fué tardía; pero cuando fuí elegido Pastor romano, conocí lo engañosa que es la vida. Vi que ni aun allí reposaba el corazón, no siendo posible subir a más altura en aquella vida mortal: así es que me inflamó el amor de la eterna. Hasta entonces fuí una alma miserable, alejada de Dios, y completamente avara, por lo cual sufro el castigo que ves. Lo que hace la avaricia, se manifiesta aquí con la pena que sufren las almas echadas boca abajo; pena mas amarga que ninguna otra. Así como nuestros ojos, fijos en las cosas terrenales, no miraron nunca hacia arriba, del mismo modo la justicia los sumerge aquí en el suelo. Así como la avaricia extinguió en nosotros el amor hacia todo verdadero bien, por lo cual fueron vanas nuestras obras, así también la justicia nos tiene aquí oprimidos, atados de pies y manos, e inmóviles y extendidos mientras plazca al justo Señor.\"},{\"heading\":false,\"text\":\"[72] \\\"Sabe que yo fuí sucesor de Pedro.\\\" Este es Ottobon de Fieschi, conde de Lavagna, pontífice con el nombre de Adriano V, que reinó un mes y nueve días: murió en 1276.\"},{\"heading\":false,\"text\":\"Yo me había arrodillado, y quise hablar; pero cuando empezaba, el espíritu advirtió, con sólo escuchar, este acto de reverencia, y me dijo:\"},{\"heading\":false,\"text\":\"--¿Por qué te inclinas al suelo de ese modo?\"},{\"heading\":false,\"text\":\"Le contesté:\"},{\"heading\":false,\"text\":\"--Mi recta conciencia me obliga a respetar vuestra dignidad.\"},{\"heading\":false,\"text\":\"--Endereza tus piernas, y levántate, hermano--repuso--; no te engañes: como tú y los demás, soy servidor de la misma potestad. Si has podido comprender aquellas palabras evangélicas que dicen \\\"neque nubent,\\\" bien puedes ver por qué hablo así. Véte ya: no quiero que te detengas por más tiempo; que tu permanencia aquí da treguas a mi llanto, con el que acelero lo que tú has dicho antes. Tengo allá abajo una sobrina, que se llama Alagia, naturalmente buena, a no ser que nuestra casa la haya pervertido con su ejemplo. Ella sola me queda ya en el mundo.\"}]},{\"title\":\"Purgatorio — canto vigesimo\",\"blocks\":[{\"heading\":false,\"text\":\"Mal resiste un deseo contra otro mejor: por esto, para complacer a aquel espíritu, retiré del agua, contra mi gusto, la esponja de la curiosidad no saturada. Púseme en marcha, y mi Guía se encaminó por los únicos parajes que había expeditos a lo largo de la escarpa del monte, andando como quien va por una muralla pegado a los merlones; porque aquellas almas que vierten gota a gota por sus ojos el mal que se apodera del mundo entero, se acercan demasiado de la otra parte hacia fuera. ¡Maldita seas, antigua loba, que con tu hambre profunda e insaciable haces más presas que todas las demás fieras! ¡Oh Cielo, en cuyas revoluciones ven algunos la causa de los cambios que sufren las cosas y las condiciones humanas!, ¿cuándo vendrá el que haga huír a esa loba?\"},{\"heading\":false,\"text\":\"Ibamos caminando con pasos lentos y contados, y yo ponía toda mi atención en las sombras, escuchándolas piadosamente llorar y lamentarse; cuando por ventura oí exclamar con dolorida voz, semejante a la de una mujer próxima a su alumbramiento: \\\"¡Dulce María!\\\" Y en seguida: \\\"Fuiste tan pobre como se puede ver por aquel establo donde depusiste tu santo fruto.\\\" A continuación oí: \\\"¡Oh buen Fabricio!, preferiste ser pobre y virtuoso, antes que poseer grandes riquezas cayendo en el vicio.\\\" Estas palabras me eran tan agradables, que me adelanté para conocer el espíritu de quien al parecer procedían. Este seguía hablando de los donativos que hizo Nicolás a las doncellas para conducir su juventud por la senda del honor.[73]\"},{\"heading\":false,\"text\":\"[73] San Nicolás, obispo de Mira, dotó a tres doncellas que a causa de su pobreza se veían en peligro de llevar una vida deshonesta.\"},{\"heading\":false,\"text\":\"--¡Oh alma, que recuerdas tan benéficas acciones! Dime quién fuiste--le pregunté--, y por qué eres la única que reitera esas dignas alabanzas. Tus palabras no quedarán sin recompensa, si vuelvo al mundo para concluir el corto camino de aquella vida que vuela a su término.\"},{\"heading\":false,\"text\":\"--Te lo diré--me contestó--, no porque espere consuelo alguno que proceda de allá, sino porque brilla en ti tanta gracia antes de haber muerto. Yo fuí raíz de la mala planta que arroja hoy sobre toda la tierra cristiana tan nociva sombra que apenas se coge en ella ningún fruto bueno. Pero si Douay, Gante, Lilla, y Brujas pudieran, pronto tomarían venganza; y yo se la pido a Aquél que lo juzga todo. En el mundo me llamé Hugo Capeto: de mí descienden los Felipes y los Luises, que en estos últimos tiempos rigen la Francia. Hijo fuí de un carnicero de París. Cuando faltaron los antiguos reyes, salvo uno que se revistió de paños grises, empuñé las riendas del gobierno del reino, y en mi nueva posición adquirí tal poder y tantos amigos, que la corona vacante fué colocada en la cabeza de mi hijo, en quien comienza la estirpe consagrada de los nuevos reyes. Mientras la gran adquisición de los Estados provenzales no quitó la vergüenza a mi familia, ésta valió poco, mas en cambio no hizo daño; pero allí dió principio a sus rapiñas, empleando la fuerza y la mentira: luego, para enmendarse, usurpó el Ponthieu, la Normandía y la Gascuña. Carlos fué a Italia, y para enmendarse, hizo una víctima de Conradino, y después envió al Cielo a Tomás, también para enmendarse. Veo un tiempo, no muy lejano, en que saldrá de Francia otro Carlos, para darse a conocer mejor a sí mismo y a los suyos.[74] Sale de ella sin armas, y sólo con la lanza con que luchó Judas; y la maneja de modo que abre con ella y vacía el vientre de Florencia. En esta ocasión no adquirirá comarcas, sino pecados y oprobio, tanto más gravosos para él, cuanto más leve le parezca semejante daño. Veo al otro que ya salió, y cayó prisionero en un bajel, vender a su hija regateando el precio, como hacen los corsarios con sus esclavas. ¡Oh avaricia! ¿Qué más puedes hacer, cuando te has apoderado de mi estirpe, tanto que no se cuida de su propia carne? Y a fin de que parezca menor el mal futuro y el pasado, veo a la flor de Lis entrar en Alagna, y a Cristo prisionero en la persona de su vicario, véole otra vez entregado al ludibrio, veo renovar la hiel y vinagre, y le veo morir entre otros dos ladrones. Veo tan cruel al nuevo Pilatos, que no le basta eso, y sin dictar sentencia, lleva hasta el templo sus codiciosos deseos. ¡Oh Señor mío! ¿Cuándo tendré la dicha de contemplar la venganza que, oculta en tus arcanos, te hace agradable tu ira? En cuanto a lo que yo decía de la única Esposa del Espíritu Santo, lo cual hizo que te volvieses hacia mí para obtener alguna explicación, te diré que esto forma parte de nuestras oraciones durante el día; mas luego que anochece, recitamos en su lugar ejemplos contrarios. Entonces recordamos a Pigmalión, a quien su pasión por el oro hizo traidor, ladrón y parricida; y la miseria del avaro Midas, consecuencia de su petición desmesurada, que será siempre motivo de burla. Recuérdese también al insensato Acham, y cómo robó los despojos del enemigo, de suerte que aun aquí parece que le persiga la ira de Josué. Después acusamos a Safira y a su marido; alabamos los pies que pisotearon a Eliodoro, y por todo el monte circula infamado el nombre de Polinéstor, que mató a Polidoro. Por último, gritamos: \\\"¡Oh Craso! Dinos, pues no lo ignoras, qué sabor tiene el oro.\\\" A veces hablamos unos en alta voz, otros en voz baja, según la afección que a ello nos estimula con más o menos fuerza. Por lo demás, no era yo sólo quien antes recordaba los buenos ejemplos de que nos ocupamos durante el día; pero no había cerca de aquí otro que levantara la voz.\"},{\"heading\":false,\"text\":\"[74] Carlos de Valois. El destierro de Dante provino principalmente de la ida de este príncipe a Florencia, enviado por el papa Bonifacio VIII en calidad de mediador entre los dos partidos en que estaba dividida la ciudad.\"},{\"heading\":false,\"text\":\"Nos habíamos separado ya de aquel espíritu, y procurábamos avanzar por el camino cuanto nos era posible, cuando sentí retemblar el monte como si se hundiera; por lo cual me sobrecogió un frío, sólo comparable al que siente aquel que va a morir. No se estremeció en verdad tan fuertemente Delos, antes que Latona anidase en ella para dar a luz los dos ojos del Cielo.[75] Después resonó por todos los ámbitos de la montaña tal grito, que el Maestro se acercó a mí diciendo:\"},{\"heading\":false,\"text\":\"--No vaciles, mientras yo te guíe.\"},{\"heading\":false,\"text\":\"[75] Cuéntase que la isla de Delos, en el Archipiélago, temblaba y se movía, hasta que Latona, refugiándose en ella, dió a luz a Apolo y Diana, representados por la Mitología en el Sol y la Luna, que Dante llama aquí los dos ojos del Cielo.\"},{\"heading\":false,\"text\":\"\\\"Gloria in excelsis Deo,\\\" decían todos, según comprendí por las voces que salían de los puntos cercanos, desde donde era posible oirlas. Nos quedamos inmóviles y suspensos, como los pastores que por primera vez oyeron aquel canto, hasta que cesó el temblor, y acabó el himno. Emprendimos nuevamente nuestro santo camino, mirando las sombras que yacían por el suelo vueltas boca abajo y exhalando su acostumbrado llanto. Si la memoria no me es infiel, jamás la ignorancia de una cosa incitó con tanto empeño mi deseo de saber, como entonces, pensando en lo ocurrido: y como, por la premura de nuestra marcha, no me atreví a preguntar, ni por mí mismo podía comprender nada, caminaba tímido y pensativo.\"}]},{\"title\":\"Purgatorio — canto vigesimoprimero\",\"blocks\":[{\"heading\":false,\"text\":\"Me atormentaba la sed natural, que no se sacia nunca sino con aquella agua que pidió como gracia la joven samaritana; excitábame la prisa de seguir a mi jefe por el obstruído sendero, y me afligía el espectáculo del justo castigo. En esto, según refiere Lucas que se apareció Cristo a dos hombres en el camino, después de haber salido del sepulcro, así se nos apareció una sombra, que venía en pos de nosotros mirando a sus plantas las almas tendidas: aun no habíamos reparado en ella, cuando nos dirigió la palabra diciéndonos:\"},{\"heading\":false,\"text\":\"--Hermanos míos, la paz de Dios sea con vosotros.\"},{\"heading\":false,\"text\":\"Nos volvimos presurosamente, y Virgilio le hizo la demostración que convenía a aquel saludo. Después le dijo:\"},{\"heading\":false,\"text\":\"--¡Que en el concilio bienaventurado te admita en paz el tribunal de verdad que me relega a un destierro perpetuo!\"},{\"heading\":false,\"text\":\"--¡Cómo!--exclamó el espíritu--; ¿pues por qué vais tan de prisa, si sois sombras que Dios no se digna admitir allá arriba? ¿Quien os ha guiado hasta aquí por su escala?\"},{\"heading\":false,\"text\":\"Mi Doctor contestó:\"},{\"heading\":false,\"text\":\"--Si miras las señales que lleva éste y trazas al Angel, podrás ver que tiene el derecho de reinar con los buenos; pero como aquella que hila de noche y de día no había terminado aún la husada que le corresponde, y que Cloto prepara e impone a cada uno de nosotros, su alma, que es hermana tuya y mía, viniendo aquí, no podía venir sola, porque no puede ver como nosotros. Por esta razón fuí yo sacado de la vasta garganta del Infierno para enseñarle el camino, y se lo enseñaré hasta donde mi ciencia pueda guiarle. Pero dime, si es que lo sabes, ¿por qué dió antes el monte tales sacudidas, y por qué hasta en sus húmedos fundamentos parecían gritar a la vez todas las almas?\"},{\"heading\":false,\"text\":\"Haciendo esta pregunta, Virgilio acertó como en una aguja con el ojo de mi deseo, de tal suerte, que bastó la esperanza para mitigar mi sed de saber. Aquél empezó de esta manera:\"},{\"heading\":false,\"text\":\"--Nada sucede en la religiosa montaña, que esté fuera del orden o del uso establecido. Este sitio está libre de toda conmoción; y la que habéis sentido sólo puede proceder de aquello que el Cielo recibe digno de sí mismo, y no de otra causa. Porque no llueve, ni graniza, ni nieva, ni cae escarcha ni rocío más acá de la puerta de las tres pequeñas gradas. No aparecen nubes densas ni enrarecidas, ni se ven relámpagos, ni a la hija de Taumante, que allá abajo cambia con frecuencia de sitio. No hay seco vapor, que se eleve a mayor altura de la de aquellas tres gradas de que he hablado, donde tiene sus plantas el vicario de Pedro. Quizá temblará el monte poco o mucho más abajo de allí; pero por más viento que se esconda en la tierra, no sé en qué consiste que aquí no ha temblado nunca. Unicamente se estremece cuando algún alma, sintiéndose purificada, se levanta o se mueve para subir, acompañándola aquel cántico. La prueba de la purificación es la voluntad que excita al alma, libre ya, a mudar de sitio, ayudándole en su mismo deseo. No por eso deja de sentir antes de tiempo el anhelo ineficaz de subir al cielo, pero sin que tampoco la abandone el de satisfacer a la justicia divina, pues ésta le impone por el castigo el mismo afán que tuvo por el pecado. Yo, que he yacido en esta mansión de dolor más de quinientos años, no he tenido hasta este momento la libre voluntad de pasar a otra mejor: por eso has sentido el terremoto, y a los piadosos espíritus alabando por la montaña a aquel Señor, que los admitirá pronto en su seno.\"},{\"heading\":false,\"text\":\"Así habló; y como el hombre goza tanto más en beber, cuanta mayor sed tiene, no sabré decir el contento que me dió. Mi sabio Guía le dijo:\"},{\"heading\":false,\"text\":\"--Ahora veo la red en que estáis prendidos, y de qué manera os libráis de ella; la causa del temblor del monte y la de que os congratuléis. Hazme saber ahora, si lo tienes a bien, quién fuiste, y por qué has estado tendido durante tantos siglos: permíteme que lo deduzca de tus palabras.\"},{\"heading\":false,\"text\":\"--En aquel tiempo en que el buen Tito, con la ayuda del supremo Rey, vengó las heridas por donde salió la sangre que había vendido Judas--respondió aquel espíritu--, estaba yo allá abajo llevando el nombre que más dura y honra más, bastante famoso, pero todavía sin fe. Fué tan dulce mi canto, que, a pesar de ser tolosano, me atrajo a sí Roma, donde merecí que coronaran de mirto mis sienes. Aun me llama Estacio la gente que allí vive: canté a Tebas, y después al gran Aquiles; pero caí en el camino llevando mi segunda carga. Encendieron mi ardor las chispas de la divina llama que han inflamado a más de mil. Hablo de la \\\"Eneida,\\\" la cual fué mi madre y mi nodriza en poesía: nada escribí sin ella que tuviera el menor peso; y pasaría gustoso un año más en este destierro, con tal de haber vivido en el mundo cuando vivió Virgilio.\"},{\"heading\":false,\"text\":\"Estas palabras hicieron que Virgilio se volviera hacia mí, con un ademán, que tácitamente decía: \\\"Cállate;\\\" pero la voluntad no lo puede todo; porque la risa y el llanto siguen de tal modo a la pasión de que proceden, que en los hombres más sinceros se manifiestan sin querer: así es que yo me sonreí, como quien muestra estar en inteligencia con otro; por lo cual la sombra se calló, y me miró a los ojos, que es donde más se refleja el pensamiento.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡Ojalá puedas llevar a buen término tu grande obra!--dijo--; más ¿por qué tu rostro me ha mostrado ahora ese relámpago de sonrisa?\"},{\"heading\":false,\"text\":\"Vime entonces apurado entre ambos: el uno me obligaba a callar, el otro me pedía que hablase; por lo cual suspiré, y fuí comprendido.\"},{\"heading\":false,\"text\":\"--Puedes hablar sin temor--me dijo mi Maestro--; habla y dile lo que pregunta con tanto empeño.\"},{\"heading\":false,\"text\":\"Contesté, pues:\"},{\"heading\":false,\"text\":\"--Quizá te asombres, antiguo espíritu, de mi sonrisa; pero quiero causarte mayor admiración. Este, que guía mis ojos hacia arriba, es aquel Virgilio, de quien aprendiste a cantar en sublimes versos los actos de los hombres y de los dioses. Si creíste que mi sonrisa tenía otra causa, deséchala como errónea, que sólo procedía de las palabras que pronunciaste con respecto a él.\"},{\"heading\":false,\"text\":\"Estacio se inclinaba ya para abrazar las rodillas de mi Señor; pero éste le dijo:\"},{\"heading\":false,\"text\":\"--Hermano, no lo hagas; que tú eres sombra, y ves ante ti a otra sombra.\"},{\"heading\":false,\"text\":\"Y él, levantándose, contestó:\"},{\"heading\":false,\"text\":\"--Tú puedes comprender ahora la magnitud del amor que por ti me inflama, cuando olvido nuestra vanidad, tratando a una sombra como a un cuerpo sólido.\"}]},{\"title\":\"Purgatorio — canto vigesimosegundo\",\"blocks\":[{\"heading\":false,\"text\":\"Ya el ángel se había quedado detrás de nosotros; el ángel que nos dirigió hacia el sexto círculo, después de haber borrado una de las manchas de mi frente; y nos había dicho que son bienaventurados los que cifran sus deseos en la justicia, pero su voz expresó esta sentencia con la palabra \\\"sitiunt\\\" sin pronunciar la otra. Yo andaba por allí más ligero que por las otras aberturas, de modo que sin ningún trabajo seguía hacia arriba a los veloces espíritus. Entonces Virgilio empezó a decir:\"},{\"heading\":false,\"text\":\"--El amor que nace de la virtud inflama siempre otros amores, con tal que su llama se dé a conocer. Desde la hora en que Juvenal bajó entre nosotros al Limbo del Infierno, y me manifestó tu afecto hacia mí, mi benevolencia para contigo fué la mayor que sentirse puede por una persona a quien no se ha visto nunca: así es que ahora me parecen cortas estas escaleras. Pero dime, y, como amigo, perdona si la demasiada confianza afloja el freno de mi lengua, en el concepto de que también deseo que como amigo me hables: ¿cómo pudo encontrar la avaricia un lugar en tu corazón, a pesar del recto sentido que con tu diligencia y estudio llegaste a poseer en tanto grado?\"},{\"heading\":false,\"text\":\"Estas palabras hicieron sonreír desde luego a Estacio; después respondió:\"},{\"heading\":false,\"text\":\"--Todo cuanto me digas es para mí una prueba de cariño. Muchas veces, en efecto, aparecen las cosas de manera, que dan motivo a falsas presunciones, porque las verdaderas causas están ocultas. Tú crees, según me prueba tu pregunta, que yo fuí avaro en la otra vida, quizá por haberme visto en el círculo en que me encontraba. Sabe, pues, que la avaricia estuvo muy lejos de mí, y que mis excesos en contrario han sido castigados por millares de lunas. Y si no hubiera sido porque me apliqué el oportuno remedio, cuando medité los versos en que exclamas, casi irritado contra la humana naturaleza: \\\"¡Oh execrable hambre del oro!, ¿adónde no conduces al insaciable apetito de los mortales?,\\\" me vería dando vueltas por el círculo donde se lanzan pesos. Entonces calculé que, por abrir demasiado las alas, podían llegar a gastarse mis manos, y me arrepentí tanto de aquél como de los otros males. ¡Cuántos resucitarán con los cabellos rapados, por la ignorancia en que están de que la prodigalidad sea un pecado, y que les impide arrepentirse, ya durante su vida, ya en el término de ella! Y sabe que la culpa diametralmente opuesta a cada pecado se expía aquí juntamente con el mismo pecado: así es que si he permanecido purificándome entre los que lloran su avaricia, ha sido precisamente por el vicio contrario.\"},{\"heading\":false,\"text\":\"El Cantor de las \\\"Bucólicas\\\" dijo entonces:\"},{\"heading\":false,\"text\":\"--Cuando cantaste las crueles contiendas de la doble tristeza de Yocasta, no creo, a juzgar por los acentos en que Clío te hizo prorrumpir, que te contase entre los suyos la Fe, sin la cual no basta obrar bien. Si así es, ¿qué sol o qué luz ha disipado tus tinieblas de tal modo, que te permitiera elevar tus velas hacia el Pescador?\"},{\"heading\":false,\"text\":\"Y el otro contestó:\"},{\"heading\":false,\"text\":\"--Tú me enviaste primero a beber en las grutas del Parnaso, y luego me iluminaste para que conociese al verdadero Dios. Hiciste como el que camina de noche llevando tras de sí una luz, que a él no le sirve, pero alumbra a las personas que le siguen, cuando dijiste: \\\"El siglo se renueva, vuelve la justicia con los primeros tiempos del género humano, y una nueva progenie desciende del cielo.\\\" Por ti fuí poeta, por ti cristiano; mas para que veas mejor lo que te pinto, extenderé las manos a fin de darle más colorido. Ya estaba el mundo lleno de la verdadera creencia, sembrada por los mensajeros del eterno reino, y tus palabras, antes citadas, concordaban con la doctrina de los nuevos apóstoles; por lo cual yo me acostumbré a visitarlos: después me parecieron rodeados de tal santidad, que cuando Domiciano los persiguió, corrieron mis lágrimas mezcladas con las suyas. Mientras viví, les socorrí; sus rectas costumbres me hicieron despreciar todas las otras sectas, y antes que, en mi poema, condujese a los griegos ante los ríos de Tebas, había recibido el bautismo; pero por miedo fuí cristiano en secreto, y durante largo tiempo me mostré pagano. Esta timidez me ha hecho recorrer el cuarto círculo durante más de cuatro siglos. Y ahora, pues tenemos más tiempo del que necesitamos para subir por nuestro camino, dime tú, que has descorrido el velo que me ocultaba el soberano bien, dónde están nuestro antiguo Terencio, Cecilio, Plauto y Varrón, si es que lo sabes. Dime si están condenados y en qué círculo.\"},{\"heading\":false,\"text\":\"--Todos esos, y Persio, y yo, y otros muchos--respondió mi Guía--, estamos en el primer círculo de la ciega prisión con aquel Griego[76] a quien lactaron las Musas más que a otro alguno: muchas veces hablamos del monte donde se encuentran siempre nuestras nodrizas. Allí están con nosotros Eurípides, Anacreonte, Simónides, Agatón, y otros muchos griegos que vieron ya sus frentes coronadas de laurel. De los que tú cantaste, se ve allí a Antígona, a Deifila, Argía e Ismene, tan triste como antes. Está también la que enseñó la Langía, la hija de Tiresias, y Tetis, y Deidamia con sus hermanas.\"},{\"heading\":false,\"text\":\"[76] Homero.\"},{\"heading\":false,\"text\":\"Los dos poetas habían guardado silencio, mirando de nuevo con atención en torno suyo, por haber terminado la escala y sus paredes: ya las cuatro esclavas del día habían quedado atrás, y la quinta estaba en el timón del carro solar, dirigiendo hacia arriba su luminosa punta, cuando mi Guía dijo:\"},{\"heading\":false,\"text\":\"--Creo conveniente que volvamos nuestro hombro derecho hacia la orilla del círculo, para dar la vuelta a la montaña, según acostumbramos hacer.\"},{\"heading\":false,\"text\":\"Esta costumbre fué nuestra guía, y emprendimos el camino sin titubear, una vez que a ello asintió la otra alma virtuosa. Ellos iban delante y yo detrás, solo, escuchando sus palabras, que me comunicaban la inteligencia de la poesía. Pero pronto interrumpió tan dulce coloquio la vista de un árbol, que encontramos en medio del camino, cargado de manzanas olorosas; y así como el abeto, elevándose hacia el cielo, va disminuyendo de rama en rama, aquél iba disminuyendo por su parte inferior, con objeto, según creo, de que nadie suba a él. Por el lado en que estaba cerrado nuestro camino, caía de la alta roca un agua cristalina, que se esparcía por las hojas superiores.\"},{\"heading\":false,\"text\":\"Los dos Poetas se acercaron al árbol, cuando exclamó una voz entre el follaje: \\\"Os puede costar caro tocar este manjar.\\\" Después dijo: \\\"María pensaba más en que las bodas fuesen honrosas y cumplidas, que en su boca que ahora intercede por vosotros. Las antiguas romanas se contentaron con el agua por toda bebida, y Daniel despreció los manjares y adquirió la ciencia. El primer siglo fué tan bello como el oro; el hambre hacía más sabrosas las bellotas, y la sed convertía en néctar cualquier arroyuelo. En miel y langostas consistió el alimento del Bautista en el Desierto: esto le da más gloria, y le hace tan grande como lo patentiza el Evangelio.\\\"\"}]},{\"title\":\"Purgatorio — canto vigesimotercero\",\"blocks\":[{\"heading\":false,\"text\":\"Mientras tenía mi vista fija en el verde follaje, como suele hacer quien pierde el tiempo detrás de un pájaro, el que era para mí más que un padre, decía:\"},{\"heading\":false,\"text\":\"--Hijo mío, ven ahora, porque el tiempo que se nos concede debe emplearse más útilmente.\"},{\"heading\":false,\"text\":\"Volví el rostro con ligereza y con no menos mis pasos hacia los Sabios, los cuales hablaban tan bien, que escuchándolos no sentía en el andar cansancio alguno; cuando se oyó cantar llorando: \\\"Labia mea, Dómine,\\\" de un modo que hizo nacer en mí placer y dolor.\"},{\"heading\":false,\"text\":\"--¡Oh dulce Padre!, ¿qué es lo que oigo?--empecé a decir.\"},{\"heading\":false,\"text\":\"Y él dijo:\"},{\"heading\":false,\"text\":\"--Son las sombras, que van quizá deshaciendo el nudo de sus deudas.\"},{\"heading\":false,\"text\":\"Cual peregrinos pensativos, que al encontrar en su camino gente a quien no conocen, se vuelven hacia ella sin detenerse, así venía tras de nosotros, pero con paso más rápido, una turba de espíritus, callados y piadosos, que pasaban adelante mirándonos. Todos ellos tenían los ojos hundidos y apagados, la faz pálida, y tan demacrada, que a través de la piel se notaba la forma de los huesos. No creo que Erisictón se viese reducido a una piel tan seca cuando más tuvo que temer el hambre. Yo decía, pensando entre mí: \\\"He aquí cómo debía estar la nación que perdió a Jerusalén, cuando María llegó a devorar a su propio hijo.\\\" Sus ojos parecían anillos sin piedras; los que en el rostro del hombre leen Homo, hubieran conocido allí con facilidad la M[77]. ¿Quién creería, ignorando la causa, que el olor de una fruta y aquel salto de agua, excitando su deseo, pudiera reducirlos a tal extremo? Yo estaba asombrado al verles tan hambrientos, porque aun no conocía la causa de su demacración y de su triste aridez; cuando desde la profunda cavidad de su cabeza dirigió hacia mí sus ojos una sombra, y me miró fijamente; después de lo cual exclamó en alta voz:\"},{\"heading\":false,\"text\":\"--¿Qué gracia es ésta que se me concede?\"},{\"heading\":false,\"text\":\"[77] Algunos teólogos y predicadores místicos de la Edad Media pretendían que Dios había escrito de propio puño las palabras Homo Dei en el rostro humano. Como a causa de su flacura, quiere decir Dante, sus ojos (las oes) estaban tan hundidos en la cabeza, claramente podía verse la M, formada por la nariz, las cejas y las mejillas.\"},{\"heading\":false,\"text\":\"Nunca le hubiera conocido por su rostro; pero su voz me recordó todo lo que sus facciones habían absorbido en sí mismas; esta chispa encendió en mí el completo conocimiento de aquel rostro cambiado, y reconocí el de Forese.\"},{\"heading\":false,\"text\":\"--¡Ah!--me dijo--; no fijes tu atención en esta lepra árida, que me decolora la piel, ni en la carne que me falta. Pero dime la verdad con respecto a ti, y dime quiénes son esas dos almas que te guían: no pararé hasta que me lo digas.\"},{\"heading\":false,\"text\":\"--Tu rostro, que ya muerto me hizo llorar, excita ahora en mí nuevos deseos de llanto--le respondí viéndole tan desfigurado--; pero dime, por Dios, qué es lo que os demacra tanto; y no me hagas hablar de otra cosa mientras dura mi asombro, porque mal puede hablar el que está poseído de otro deseo.\"},{\"heading\":false,\"text\":\"Me contestó:\"},{\"heading\":false,\"text\":\"--Desde el eterno tribunal desciende una virtud sobre el agua y la planta que hemos dejado más atrás; virtud que me extenúa de esta suerte. Todos esos que cantan llorando por haberse entregado desenfrenadamente al vicio de la gula, deben santificarse aquí por medio del hambre y de la sed. El olor que se exhala de la fruta y el agua que se extiende sobre ese follaje, excitan en nosotros el deseo de comer y beber, y más de una vez se repite nuestra pena mientras damos la vuelta a este círculo: he dicho pena, debiendo decir consuelo; porque el deseo que nos conduce hacia ese árbol es el mismo que condujo a Jesucristo a decir lleno de gozo: \\\"Eli,\\\" cuando nos redimió con la sangre de sus venas.\"},{\"heading\":false,\"text\":\"--Forese--repliqué--, desde aquel día en que dejaste el mundo por mejor vida, no han transcurrido aún cinco años. Si la facultad de pecar concluyó en ti antes de que sobreviniera la hora del saludable dolor que nos reconcilia con Dios, ¿cómo es que has venido aquí arriba? Creía encontrarte abajo, donde el tiempo con el tiempo se repara.\"},{\"heading\":false,\"text\":\"Respondióme:\"},{\"heading\":false,\"text\":\"--Mi Nella es la que, con sus ruegos asiduos, me ha conducido a beber el dulce ajenjo del dolor. Con sus devotas oraciones y sus suspiros me ha sacado del lugar donde se espera, y me ha librado de los otros círculos. Mi viudita, a quien amé mucho, es tanto más querida y agradable a Dios, cuanto más sola es en obrar bien; pues la Barbagia de Cerdeña tiene mujeres mucho más púdicas que la Barbagia donde la he dejado. ¡Oh caro hermano!, ¿qué quieres que te diga? Ante mi vista se presenta un tiempo futuro, del que no dista mucho el presente, en el cual se prohibirá desde el púlpito a las descaradas florentinas ir enseñando los pechos, ¿Qué mujeres bárbaras ni sarracenas ha habido jamás, contra las que se debiera apelar a penas espirituales o a otras restricciones para obligarlas a ir cubiertas? Pero si las impúdicas estuvieran seguras de lo que el cielo les prepara pronto, tendría ya la boca abierta para aullar; porque si mi previsión no me engaña, serán entristecidas antes de que salga el bozo al niño que ahora se consuela con la \\\"nana.\\\" ¡Ah, hermano!, no te me ocultes más: estás viendo que, no sólo yo, sino todas esas almas, miran el sitio donde interceptas la luz del Sol.\"},{\"heading\":false,\"text\":\"Entonces le dije:\"},{\"heading\":false,\"text\":\"--Si recuerdas lo que tú y yo fuimos, aun el mencionarlo ahora deberá serte doloroso. De aquella vida me sacó el otro día ese que va delante de mí, cuando se ostentaba redonda la hermana de aquel (y le designé el Sol). Ese sabio me ha guiado a través de la profunda noche por entre los verdaderos muertos, y con mi verdadera carne que le sigue. Su auxilio me ha sostenido hasta aquí en las cuestas y recodos del monte, que hace que seáis rectos vosotros a quienes tan torcidos hizo el mundo. Me ha dicho que me acompañaría hasta dejarme donde está Beatriz: allí es preciso que me quede sin él. Virgilio es ese que me habló así (y se lo indiqué con el dedo); el otro es aquella sombra por quien hubo hace poco tales sacudimientos en todos los ámbitos de vuestro monte, que de sí la despide.\"}]},{\"title\":\"Purgatorio — canto vigesimocuarto\",\"blocks\":[{\"heading\":false,\"text\":\"Ni la conversación detenía nuestra marcha, ni ésta a aquélla, sino que, a pesar de ir hablando, caminábamos de prisa, como la nave impelida por un viento favorable. Las sombras, que parecían cosas doblemente muertas, noticiosas de que yo estaba vivo, mostraban su admiración por las hondas cavidades de sus ojos. Continuando yo mi discurso, dije:\"},{\"heading\":false,\"text\":\"--Esa sombra, quizá por causa del otro, se dirige arriba más lentamente de lo que lo haría. Pero dime, si acaso lo sabes, dónde está Piccarda, y si entre esta gente que así me mira veo alguna persona digna de llamar mi atención.\"},{\"heading\":false,\"text\":\"--Mi hermana, que no sé lo que fué más, si hermosa o buena, ostenta ya su triunfal corona en el alto Olimpo.\"},{\"heading\":false,\"text\":\"Esto dijo primero, y luego añadió:\"},{\"heading\":false,\"text\":\"--Aquí no está prohibido nombrar a nadie, atendida la prontitud con que es alterado nuestro semblante por la dieta. Ese (y lo señaló con el dedo) es Buonaggiunta, Buonaggiunta el de Luca; y aquel de más allá, más apergaminado que los otros, tuvo en sus brazos la Santa Iglesia: fué natural de Tours, y ahora expía con el ayuno las anguilas del Bolsena y la garnacha[78].\"},{\"heading\":false,\"text\":\"[78] El papa Martín IV, natural de Tours. Fué hombre de bien, y muy amigo de la casa de Francia. Dado a la gula, hacía morir las anguilas del lago de Bolsena, ahogándolas en vino blanco generoso y dulce (garnacha), y después de bien guisadas, las comía con afán.\"},{\"heading\":false,\"text\":\"Otros muchos me fué citando uno a uno, y todos parecían contentos de que se les nombrase; pues no reparé en ellos ningún gesto de desagrado. Vi mover las mandíbulas, mascando en vacío por efecto del hambre, a Ubaldino de la Pila, y a Bonifacio, que apacentó a muchos revestido con el roquete[79]. Vi a meser Marchese, que habiendo tenido tiempo para beber en Forli con menos sed, fué tal que nunca se sintió saciado. Pero, como aquel que mira, y después simpatiza más con uno que con otro, así me pasó con el de Luca, que parecía querer decirme algo. Murmuraba entre dientes; y yo le oía no sé qué de Gentucca donde él sentía el castigo que tanto le devoraba.\"},{\"heading\":false,\"text\":\"[79] Bonifacio de Fieschi, conde de Lavagna y arzobispo de Ravena.\"},{\"heading\":false,\"text\":\"--¡Oh alma, le dije, que tan deseosa pareces de hablar conmigo! Haz de modo que yo te entienda, y satisfácenos a los dos con tu conversación.\"},{\"heading\":false,\"text\":\"El empezó a decir:\"},{\"heading\":false,\"text\":\"--Existe una mujer que no lleva el velo todavía, la cual hará que te agrade mi ciudad, aunque alguno hable mal de ella. Tú irás allá con esta predicción, y si acaso no has entendido bien lo que murmuro, ya te lo pondrá en claro la realidad de los hechos. Pero dime: ¿no estoy viendo al que ha dado a luz las nuevas rimas, que comienzan así: \\\"Donne, ch\'avete intelleto d\'Amore\\\"[80]\"},{\"heading\":false,\"text\":\"[80] Así empieza una bellísima canción de Dante, que puede verse en La Vida Nueva.\"},{\"heading\":false,\"text\":\"Le contesté:\"},{\"heading\":false,\"text\":\"--Yo soy uno que voy notando lo que Amor inspira, y luego lo expreso tal como él me dicta dentro del alma.\"},{\"heading\":false,\"text\":\"--¡Oh hermano!--exclamó.--Ahora veo el nudo que al Notario, a Guittone[81] y a mí nos impidió llegar al dulce y nuevo estilo que oigo. Bien veo que vuestras plumas siguen fielmente al que les dicta, lo cual no han hecho en verdad las nuestras; y que quien se propone remontarse a mayor altura, no ve la diferencia del uno al otro estilo.\"},{\"heading\":false,\"text\":\"[81] Jacobo de Lentino, llamado el Notario, y Guittone de Arezzo, poetas mediocres.\"},{\"heading\":false,\"text\":\"Dichas estas palabras, se calló como si estuviese satisfecho.\"},{\"heading\":false,\"text\":\"Así como las grullas que pasan el invierno a orillas del Nilo forman a veces una bandada en el aire, y luego vuelan rápidamente marchando en hilera, de igual suerte todas las almas que allí estaban, volviendo el rostro, aceleraron el paso, ligeras por su demacración y por su deseo: y al modo que un hombre cansado de correr deja ir delante a sus compañeros, y sigue lentamente hasta que cesa la agitación de su pecho, así Forese dejó pasar a la grey santa, y continuó conmigo su camino diciéndome:\"},{\"heading\":false,\"text\":\"--¿Cuándo te volveré a ver?\"},{\"heading\":false,\"text\":\"--No sé cuánto he de vivir--le respondí--; pero no será tan pronto mi regreso, que antes no llegue yo con el deseo a la orilla; porque el sitio donde fuí colocado para vivir se despoja de día en día y cada vez más del bien, y parece destinado a una triste ruina.\"},{\"heading\":false,\"text\":\"--Vé, pues--repuso--; que ya estoy viendo al que tiene la mayor culpa de esa ruina, arrastrado a la cola de un animal hacia el valle donde nadie se excusa de sus faltas[82]. El animal a cada paso va más rápido, aumentando siempre su celeridad, hasta que lo arroja, y abandona el cuerpo vilmente destrozado. Esas esferas no darán muchas vueltas (y dirigió sus ojos al cielo) sin que sea claro para ti lo que mis palabras no pueden ampliar más. Ahora te dejo; porque el tiempo es caro en este reino, y yo pierdo mucho caminando a tu lado.\"},{\"heading\":false,\"text\":\"[82] Corso Donati, hermano del mismo Forese, jefe de los Negros, y principal causante de los males de Florencia. Forese no nombra a Corso, porque es su hermano.\"},{\"heading\":false,\"text\":\"Cual jinete que se adelanta al galope de entre el escuadrón que avanza, a fin de alcanzar el honor del primer choque, del mismo modo y con mayores pasos se apartó de nosotros aquel espíritu, y yo quedé en el camino con aquellos dos que fueron tan grandes generales del mundo. Cuando estuvo tan retirado de nosotros, que mis ojos no podían seguirle, así como tampoco podía mi mente alcanzar el sentido de sus palabras, observé no muy lejos las ramas frescas y cargadas de frutas de otro manzano, por haberme vuelto entonces hacia aquel lado. Y vi debajo de él muchas almas que alzaban las manos y gritaban no sé qué en dirección del follaje, como los niños que, codiciando impotentes alguna cosa, la piden sin que aquel a quien ruegan les responda, y antes al contrario, para excitar más sus deseos, tiene elevado y sin ocultar lo que causa su anhelo. Después se marcharon como desengañadas, y nosotros nos acercamos entonces al gran árbol, que rechaza tantos ruegos y tantas lágrimas.\"},{\"heading\":false,\"text\":\"\\\"Pasad adelante sin aproximaros: más arriba existe otro árbol, cuyo fruto fué mordido por Eva, y éste es un retoño de aquél.\\\" Así decía no sé quién entre las ramas; por lo cual Virgilio, Estacio y yo seguimos adelante, estrechándonos cuanto pudimos hacia el lado en que se eleva el monte. \\\"Acordaos, decía la voz, de los malditos formados en las nubes, que, repletos, combatieron a Teseo con sus dobles pechos[83]. Acordaos de los hebreos, que mostraron al beber su molicie, por lo que Gedeón no los quiso por compañeros cuando descendió de las colinas cerca de Madián.\\\" De este modo, arrimados a una de las orillas, pasamos adelante, oyendo diferentes ejemplos del pecado de la gula, seguidos de las miserables consecuencias de aquel vicio. Después, entrando nuevamente en medio del camino desierto, nos adelantamos mil pasos y aun más, reflexionando cada cual y sin hablar. \\\"¿Qué vais pensando vosotros tres solos?\\\", dijo de improviso una voz, que me hizo estremecer, como sucede a los animales tímidos y asustadizos. Levanté la cabeza para ver quién fuese, y jamás se vieron en un horno vidrios o metales tan luminosos y rojos como lo estaba uno que decía: \\\"Si queréis llegar hasta arriba, es preciso que deis aquí la vuelta: por aquí va el que quiere ir en paz.\\\" Su aspecto me había deslumbrado la vista; por lo cual me volví, siguiendo a mis Doctores a la manera de quien se guía por lo que escucha. Y sentí que me daba en medio de la frente un viento, como sopla y embalsama el ambiente la brisa de Mayo, mensajera del alba, impregnada con el aroma de las plantas y flores; y bien sentí moverse la pluma, que me hizo percibir el perfume de la ambrosía, oyendo decir: \\\"Bienaventurados aquellos a quienes ilumina tanta gracia, que la inclinación a comer no enciende en sus corazones desmesurados deseos, y sólo tienen el hambre que es razonable.\\\"\"},{\"heading\":false,\"text\":\"[83] Los Centauros, engendrados por el consorcio de Ixion con una nube, llenos de vino, intentaron robar la esposa de Piritóo en medio del convite nupcial, por lo cual Teseo los mató. Combatieron con sus dobles pechos, de hombre y de caballo.\"}]},{\"title\":\"Purgatorio — canto vigesimoquinto\",\"blocks\":[{\"heading\":false,\"text\":\"Era la hora en que no debía demorarse nuestra subida, pues el sol había dejado el círculo meridional al Tauro, y la noche al Escorpión: por lo cual, así como el hombre a quien estimula el aguijón de la necesidad, no se detiene por nada que encuentre, sino que sigue su camino, de igual suerte entramos nosotros por la abertura del peñasco, uno delante de otro, tomando la escalera, que por su angostura obliga a separarse a los que la suben. Y como la joven cigüeña que extiende sus alas deseosa de volar, y no atreviéndose a abandonar el nido, las pliega nuevamente, lo mismo hacía yo llevado de un ardiente deseo de preguntar, que se inflamaba y se extinguía, hasta que llegué a hacer el ademán del que se prepara a hablar. A pesar de lo rápido de nuestra marcha, mi amado Padre no dejó de decirme:\"},{\"heading\":false,\"text\":\"--Dispara el arco de la palabra, que tienes tirante hasta el hierro.\"},{\"heading\":false,\"text\":\"Entonces abrí la boca con seguridad, y empecé a decir:\"},{\"heading\":false,\"text\":\"--¿Cómo es posible enflaquecer donde no hay necesidad de alimentarse?\"},{\"heading\":false,\"text\":\"--Si te acordaras de cómo se consumió Meleagre al consumirse un tizón--respondió--, no te sería ahora tan difícil comprender esto; y si considerases cómo, al moveros, se mueve vuestra imagen dentro del espejo, te parecería blando lo que te parece duro. Mas para que tu deseo quede satisfecho, aquí tienes a Estacio, a quien pido y suplico que sea el médico de tus heridas.\"},{\"heading\":false,\"text\":\"--Si estando tú presente, le descubro los arcanos de la eterna justicia--respondió Estacio--, sírvame de disculpa el no poder negarte nada.\"},{\"heading\":false,\"text\":\"Luego empezó diciendo:\"},{\"heading\":false,\"text\":\"--Hijo, si tu mente recibe y guarda mis palabras, ellas te darán luz sobre el punto de que hablas. La sangre más pura, que nunca es absorbida por las sedientas venas y que sobra, como el resto de los alimentos que se retiran de la mesa, adquiere en el corazón una virtud tan apta para formar todos los miembros humanos, como la que tiene para transformarse en ellos la que va por las venas. Todavía más depurada, desciende a un punto que es mejor callar que nombrar, de donde se destila después sobre la sangre de otro ser en vaso natural. Aquí se mezclan las dos, la una dispuesta a recibir la impresión, la otra a producirla por efecto de la perfección del lugar de que procede; y apenas están juntas, la sangre viril empieza desde luego a operar, coagulando primero, y vivificando en seguida lo que ha hecho unírsele como materia propia. Convertida la virtud activa en alma, como la de una planta, pero con la diferencia de que aquélla está en vías de formación, mientras que la otra ha llegado ya a su término, continúa obrando de tal modo, que luego se mueve y siente como la esponja marina, y en seguida emprende la organización de las potencias, de la cual es el germen. Hijo mío, la virtud que procede del corazón del padre, y desde la cual atiende la naturaleza a todos los miembros, ora se ensancha, y ora se prolonga; mas no ves todavía cómo el feto, de animal pasa a ser racional: este punto es tal, que uno más sabio que tú incurrió con su doctrina en el error de separar del alma el intelecto posible, porque no vió que éste tuviese ningún órgano especial adecuado a sus funciones. Abre tu corazón a la verdad que te presento, y sabe que, en cuanto está concluído el organismo del cerebro del feto, el Primer Motor se dirige placentero hacia aquella obra maestra de la naturaleza, y le infunde un nuevo espíritu, lleno de virtud, que atrae a su substancia lo que allí encuentra de activo, y se convierte en un alma sola, que vive, y siente, y se refleja sobre sí misma: a fin de que te causen menos admiración mis palabras, considera el calor del Sol, que se transforma en vino, uniéndose al humor que sale de la vid. Cuando Laquesis no tiene ya lino, el alma se separa del cuerpo, llevándose virtualmente consigo sus potencias divinas y humanas: todas las facultades sensitivas quedan como mudas; pero la memoria, el entendimiento y la voluntad son en su acción mucho más sutiles que antes. Sin detenerse, el alma llega maravillosamente por sí misma a una de las orillas, donde conoce el camino que le está reservado. En cuanto se encuentra circunscrita en él, la virtud informativa irradia en torno, del mismo modo que cuando vivía en sus miembros; y así como el aire, cuando el tiempo está lluvioso, se presenta adornado de distintos colores por los rayos del Sol que en él se reflejan, de igual suerte el aire de alrededor toma la forma que le imprime virtualmente el alma que está allí detenida; y semejante después a la llama que sigue en todos sus movimientos al fuego, la nueva forma va siguiendo al espíritu. Por fin, como el alma toma de esto su apariencia, se le llama sombra, y en esa forma organiza luego cada uno de sus sentidos, hasta el de la vista. En virtud de este cuerpo aéreo hablamos, reímos, derramamos lágrimas y suspiramos, como habrás podido observar por el monte. Según como los deseos y los demás afectos nos impresionan, la sombra toma diferentes figuras: tal es la causa de lo que te admira.\"},{\"heading\":false,\"text\":\"Habíamos llegado ya al círculo de la última tortura, y nos dirigíamos hacia la derecha, cuando llamó nuestra atención otro cuidado. Allí la ladera de la montaña lanza llamas con ímpetu hacia el exterior, y la orilla opuesta del camino da paso a un viento que, dirigiéndose hacia arriba, la rechaza y aleja de sí. Por esta razón nos era preciso caminar de uno en uno por el lado descubierto del camino, de modo que si, por una parte, me causaba temor el fuego, por otra temía despeñarme. Mi Jefe decía:\"},{\"heading\":false,\"text\":\"--En este sitio es preciso refrenar bien los ojos, porque muy poco bastaría para dar un mal paso.\"},{\"heading\":false,\"text\":\"Entonces oí cantar en el seno de aquel gran ardor: \\\"Summæ Deus clementiæ\\\"[84]; lo cual excitó en mí un deseo no menos ardiente de volverme, y vi a varios espíritus andando por la llama: yo les miraba, pero fijando alternativamente la vista, ya en sus pasos, ya en los míos. Después de la última estrofa de aquel himno, gritaron en voz alta: \\\"Virum non cognosco\\\"[85]; y en seguida volvieron a entonarlo en voz baja. Terminado el himno, gritaron aún: \\\"Diana corrió al bosque, y arrojó de él a Hélice, que había gustado el veneno de Venus.\\\" Repetían su canto, y citaban después ejemplos de mujeres y maridos que fueron castos, como lo exigen la virtud y el matrimonio. Y de este modo, según creo, continuarán durante todo el tiempo que los abrase el fuego; pues con tal remedio y tales ejercicios ha de cicatrizarse la última llaga.\"},{\"heading\":false,\"text\":\"[84] Principio del himno que la Iglesia recita en los maitines del Sábado, y que cantan las almas que se purifican del vicio de la lujuria, porque en él se pide a Dios la pureza.\"},{\"heading\":false,\"text\":\"[85] Palabras dichas por María al arcángel San Gabriel. Dante continúa haciendo citar a las almas ejemplos contrarios a los vicios de que se purifican. Enumeran los ejemplos en alta voz, porque con ellos las almas se reprenden a sí mismas: el himno lo cantan en voz baja, como una oración que dirigen a Dios.\"}]},{\"title\":\"Purgatorio — canto vigesimosexto\",\"blocks\":[{\"heading\":false,\"text\":\"Mientras que uno tras otro íbamos por el borde del camino, el buen Maestro decía muchas veces: \\\"Mira, y ten cuidado, pues ya estás advertido.\\\" Daba en mi hombro derecho el Sol, que irradiando por todo el Occidente, cambiaba en blanco su color azulado. Con mi sombra hacía parecer más roja la llama, y aquí también vi muchas almas que, andando, fijaban su atención en tal indicio. Con este motivo se pusieron a hablar de mí, y empezaron a decir: \\\"Parece que éste no tenga un cuerpo ficticio.\\\" Después se cercioraron, aproximándose a mí cuanto podían, pero siempre con el cuidado de no salir adonde no ardieran.\"},{\"heading\":false,\"text\":\"--¡Oh tú, que vas en pos de los otros, no por ser el más lento, sino quizá por respeto!, respóndeme a mí, a quien abrasan la sed y el fuego. No soy yo el único que necesita tu respuesta, pues todos éstos tienen mayor sed, que deseo de agua fresca el Indio y el Etíope. Dinos: ¿cómo es que formas con tu cuerpo un muro que se antepone al Sol, cual si no hubieras caído aún en las redes de la muerte?\"},{\"heading\":false,\"text\":\"Así me hablaba una de aquellas sombras, y yo me habría explicado en el acto, si no hubiese atraído mi atención otra novedad que apareció entonces. Por el centro del camino inflamado venía una multitud de almas con el rostro vuelto hacia las primeras, lo cual me hizo contemplarlas asombrado. Por ambas partes vi apresurarse todas las sombras, y besarse unas a otras, sin detenerse, y contentándose con tan breve agasajo; semejantes a las hormigas, que en medio de sus pardas hileras, van a encontrarse cara a cara, quizá para darse noticias de su viaje o de su botín. Una vez terminado el amistoso saludo, y antes de dar el primer paso, cada una de ellas se ponía a gritar con todas sus fuerzas, las recién llegadas: \\\"Sodoma y Gomorra,\\\" y las otras: \\\"En la vaca entró Pasifae, para que el toro acudiera a su lujuria.\\\" Después, como grullas que dirigiesen su vuelo, parte hacia los montes Rifeos, y parte hacia las ardientes arenas, huyendo éstas del hielo, y aquéllas del Sol, así unas almas se iban y otras venían, volviendo a entonar entre lágrimas sus primeros cantos, y a decir a gritos lo que más necesitaban. Como anteriormente, se acercaron a mí las mismas almas que me habían preguntado, atentas y prontas a escucharme. Yo, que dos veces había visto su deseo, empecé a decir:\"},{\"heading\":false,\"text\":\"--¡Oh almas seguras de llegar algún día al estado de paz! Mis miembros no han quedado allá verdes ni maduros, sino que están aquí conmigo, con su sangre y con sus coyunturas. De este modo voy arriba, a fin de no ser ciego nunca más: sobre nosotros existe una mujer, que alcanza para mí esta gracia por la cual llevo por vuestra mundo mi cuerpo mortal. Pero decidme, ¡así se logre en breve vuestro mayor deseo, y os acoja el cielo que está más lleno de amor y por más ancho espacio se dilata! Decidme, a fin de que yo pueda ponerlo por escrito, ¿quiénes sois, y quién es aquella turba que se va en dirección contraria a la vuestra?\"},{\"heading\":false,\"text\":\"No de otra suerte se turba estupefacto el montañés, y enmudece absorto, cuando, rudo y salvaje, entra en una ciudad, de como pareció turbarse cada una de aquellas sombras: pero repuestas de su estupor, el cual se calma pronto en los corazones elevados, empezó a decirme la que anteriormente me había preguntado:\"},{\"heading\":false,\"text\":\"--¡Dichoso tú, que sacas de nuestra actual mansión experiencia para vivir mejor! Las almas que no vienen con nosotros cometieron el pecado por el que César, en medio de su triunfo, oyó que se burlaban de él y le llamaban reina. Por esto se alejan gritando \\\"Sodoma;\\\" y reprendiéndose a sí mismos, como has oído, añaden al fuego que les abrasa el que les produce su vergüenza. Nuestro pecado fué hermafrodita; pero no habiendo observado la ley humana, y sí seguido nuestro apetito al modo de las bestias, por eso, al separarnos de los otros, gritamos para oprobio nuestro el nombre de aquélla, que se bestializó en una envoltura bestial. Ya conoces nuestras acciones y el delito que cometimos: si por nuestros nombres quieres conocer quiénes somos, ni sabré decírtelos, ni tengo tiempo para ello. Satisfaré, sin embargo, tu deseo diciéndote el mío: soy Guido Guinicelli, que me purifico ya por haberme arrepentido antes de mi última hora.\"},{\"heading\":false,\"text\":\"Como corrieron hacia su madre los dos hijos al encontrarla bajo las tristes iras de Licurgo, así me lancé yo, pero sin atreverme a tanto, cuando escuché nombrarse a sí mismo a mi padre, y al mejor de todos los míos que jamás hicieron rimas de amor dulces y floridas; y sin oír hablar, anduve pensativo largo trecho, contemplándolo, aunque sin poder acercarme más a causa del fuego. Cuando me harté de mirarle, me ofrecí de todo corazón a su servicio con aquellos juramentos que hacen creer en las promesas. Me contestó:\"},{\"heading\":false,\"text\":\"--Dejas en mí, por lo que oigo, una huella tan profunda y clara, que el Leteo no puede borrarla ni obscurecerla: pero si tus palabras han jurado la verdad, dime, ¿cuál es la causa del cariño que me demuestras en tus frases y en tus miradas?\"},{\"heading\":false,\"text\":\"Le contesté:\"},{\"heading\":false,\"text\":\"--Vuestras dulces rimas, que harán preciosos los manuscritos que las contienen, tanto como dure el lenguaje moderno.\"},{\"heading\":false,\"text\":\"--¡Oh hermano!--replicó--; éste que te señalo con el dedo[86] (e indicó un espíritu que iba delante de él), fué mejor obrero en su lengua materna. Sobrepujó a todos en sus versos amorosos y en la prosa de sus novelas; y deja hablar a los necios, que creen que el Lemosín[87] es mejor que él; prestan más atención al ruido que a la verdad, y así forman su juicio antes de dar oídos al arte o la razón. Lo mismo hicieron muchos de los antiguos con respecto a Guittone, colocándole, merced a sus gritos, en el primer lugar, hasta que lo ha vencido la verdad con los méritos adquiridos por otras personas. Ahora, si tienes el alto privilegio de poder penetrar en el claustro donde Cristo es abad del colegio, díle por mí del \\\"Padre nuestro\\\" todo lo que necesitamos nosotros los habitantes de este mundo, en el que ya no tenemos el poder de pecar.\"},{\"heading\":false,\"text\":\"[86] Arnaldo Daniel, célebre poeta provenzal del siglo XII, celebrado por Petrarca como gran maestro de amor y como el primer poeta en lengua vulgar. Escribió novelas caballerescas en prosa.\"},{\"heading\":false,\"text\":\"[87] Gerardo Borneil, poeta de Limoges.\"},{\"heading\":false,\"text\":\"Luego, tal vez para hacer sitio a otro que venía en pos de él, desapareció entre el fuego, como desaparece el pez en el fondo del agua. Yo me adelanté un poco hacia el que me había designado, y le dije que mi deseo preparaba a su nombre una grata acogida: él empezó a decir donosamente:\"},{\"heading\":false,\"text\":\"--Me complace tanto vuestra cortés pregunta, que ni puedo ni quiero ocultarme a vos: yo soy Arnaldo, que lloro y voy cantando: veo, triste, mis pasadas locuras, y veo, contento, el día que en adelante me espera. Ahora os ruego, por esa virtud que os conduce a lo más alto de la escala, que os acordéis de endulzar mi dolor.\"},{\"heading\":false,\"text\":\"Después se ocultó en el fuego que les purifica.\"}]},{\"title\":\"Purgatorio — canto vigesimoseptimo\",\"blocks\":[{\"heading\":false,\"text\":\"El Sol estaba ya en aquel punto desde donde lanza sus primeros rayos sobre la ciudad en que se derramó la sangre de su Hacedor: el Ebro caía bajo el alto signo de Libra, y las ondas del Ganges eran caldeadas al empezar la hora de nona; de modo que donde estábamos terminaba el día, cuando nos divisó placentero el Angel de Dios, que apartado de la llama se puso en la orilla a cantar: \\\"Beati mundo corde,\\\" en voz bastante más viva que la nuestra. Después dijo:\"},{\"heading\":false,\"text\":\"--No se sigue adelante, almas santas, si el fuego no os muerde antes: entrad en él, y no os hagáis sordas al cántico que llegará hasta vosotras.\"},{\"heading\":false,\"text\":\"Así habló cuando estuvimos cerca de él, por lo que me quedé al oirle como aquel que es metido en la fosa. Elevé mis manos entrelazadas mirando al fuego, y se representaron vivamente en mi imaginación los cuerpos humanos que había visto arder. Mis buenos Guías se volvieron hacia mí, y Virgilio me dijo:\"},{\"heading\":false,\"text\":\"--Hijo mío, aquí puedes encontrar un tormento; pero no la muerte. Acuérdate, acuérdate... y si te guié sano y salvo sobre Gerión, ¿qué no haré ahora que estoy más cerca de Dios? Ten por cierto que, aunque estuvieras mil años en medio de esa llama, no perderías un solo cabello; y si acaso crees que te engaño, ponte cerca de ella, y como prueba, aproxima con tus manos al fuego la orla de tu ropaje. Depón, pues, depón todo temor; vuélvete hacia aquí, y pasa adelante con seguridad.\"},{\"heading\":false,\"text\":\"Yo, sin embargo, permanecí inmóvil aun en contra de mi conciencia. Cuando vió que me estaba quieto y reacio, repuso algo turbado:\"},{\"heading\":false,\"text\":\"--Hijo mío, repara en que entre Beatriz y tú sólo existe ese obstáculo.\"},{\"heading\":false,\"text\":\"Así como al oír el nombre de Tisbe, Piramo, cercano a la muerte, abrió los ojos y la contempló bajo la morera, que desde entonces echó frutos rojos, así yo, vencida mi obstinación, me dirigí hacia mi sabio Guía, al oír el nombre que siempre está en mi mente. Entonces él, moviendo la cabeza, dijo:\"},{\"heading\":false,\"text\":\"--¡Cómo! ¿Queremos permanecer aquí?\"},{\"heading\":false,\"text\":\"Y se sonrió, como se sonríe al niño a quien se conquista con una fruta. Después se metió en el fuego el primero, rogando a Estacio, que durante todo el camino se había interpuesto entre ambos, que viniese detrás de mí. Cuando estuve dentro, habríame arrojado, para refrescarme, en medio del vidrio hirviendo; tan desmesurado era el ardor que allí se sentía. Mi dulce Padre, para animarme, continuaba hablando de Beatriz y diciendo: \\\"Ya me parece ver sus ojos.\\\" Nos guiaba una voz que cantaba al otro lado; y nosotros, atentos solamente a ella, salimos del fuego por el sitio donde está la subida.\"},{\"heading\":false,\"text\":\"--\\\"Venite, benedicti patris mei\\\"--se oyó en medio de una luz que allí había, tan resplandeciente que me ofuscó y no la pude mirar.--El Sol se va--añadió--, y viene la noche; no os detengáis, sino acelerad el paso antes que el horizonte se obscurezca.\"},{\"heading\":false,\"text\":\"El sendero subía recto a través de la peña hacia el Oriente, y yo interrumpía delante de mí los rayos del Sol, que ya estaba muy bajo. Habíamos subido pocos escalones, cuando mis sabios Guías y yo, por mi sombra que se desvanecía, observamos que tras de nosotros se ocultaba el Sol; y antes de que en toda su inmensa extensión tomara el horizonte el mismo aspecto, y de que la noche se esparciera por todas partes, cada uno de nosotros hizo de un escalón su lecho; porque la naturaleza del monte, más bien que nuestro deseo, nos impedía subir. Como las cabras que antes de haber satisfecho su apetito van veloces y atrevidas por los picos de los montes, y una vez saciado éste, se quedan rumiando tranquilas a la sombra, mientras el Sol quema, guardadas por el pastor, que, apoyado en su cayado, cuida de ellas; y como el pastor que se queda fuera y pernocta cerca de su rebaño, para preservarlo de que lo disperse alguna bestia feroz, así estábamos entonces nosotros tres, yo como cabra, y ellos como pastores, estrechados por los dos lados de aquella abertura. Poco alcanzaba nuestra vista de las cosas que había fuera de allí; pero por aquel reducido espacio veía yo las estrellas más claras y mayores de lo acostumbrado. Rumiando de esta suerte y contemplándolas me sorprendió el sueño; el sueño que muchas veces predice lo que ha de sobrevenir. En la hora, según creo, en que Citerea, que parece siempre abrasada por el fuego del amor, lanzaba desde Oriente sus primeros rayos sobre la montaña, me parecía ver entre sueños una mujer joven y bella, que iba cogiendo flores por una pradera, y decía cantando: \\\"Sepa todo aquel que preguntó mi nombre, que yo soy Lía, y voy extendiendo en torno mis bellas manos para formarme una guirnalda. Para agradarme delante del espejo, me adorno aquí; pero mi hermana Raquel no se separa jamás del suyo, y permanece todo el día sentada ante él. A ella le gusta contemplar sus hermosos ojos, como a mí adornarme con mis propias manos: ella se satisface con mirar, yo con obrar.\\\" Ya, ante los esplendores que preceden al día, tanto más gratos a los peregrinos, cuanto más cerca de su patria se albergan al volver a ella, huían por todas partes las tinieblas, y con ellas mi sueño; por lo cual me levanté, y vi a mis grandes Maestros levantados también.\"},{\"heading\":false,\"text\":\"La dulce fruta que por tantas ramas va buscando la solicitud de los mortales, hoy calmará tu hambre.\"},{\"heading\":false,\"text\":\"Tales fueron las palabras que me dirigió Virgilio; palabras que me causaron un placer como no lo ha causado jamás regalo alguno. Acrecentóse tanto en mí el deseo de llegar a la cima del monte, que a cada paso que daba sentía crecer alas para mi vuelo. Cuando, recorrida toda la escalera, estuvimos en la última grada, Virgilio fijó en mí sus ojos y dijo:\"},{\"heading\":false,\"text\":\"--Has visto el fuego temporal y el eterno, hijo mío, y has llegado a un sitio donde no puedo ver nada más por mí mismo. Con ingenio y con arte te he conducido hasta aquí: en adelante sírvate de guía tu voluntad; fuera estás de los caminos escarpados y de las estrechuras; mira el Sol que brilla en tu frente; mira la hierba, las flores, los arbustos, que se producen solamente en esta tierra. Mientras no vengan radiantes de alegría los hermosos ojos que, entre lágrimas, me hicieron acudir en tu socorro, puedes sentarte, y puedes pasear entre esas flores. No esperes ya mis palabras, ni mis consejos: tu albedrío es ya libre, recto y sano, y sería una falta no obrar según lo que él te dicte. Así, pues, ensalzándote sobre ti mismo, te corono y te mitro.[88]\"},{\"heading\":false,\"text\":\"[88] Tu albedrío es ya libre; recto y sano, por el esclarecimiento de tu razón y el dominio de tus pasiones: por lo tanto te hago señor de ti mismo, en lo tocante a la dirección civil (corona), y a la espiritual (mitra).\"}]},{\"title\":\"Purgatorio — canto vigesimoctavo\",\"blocks\":[{\"heading\":false,\"text\":\"Deseoso ya de observar en su interior y en sus contornos la divina floresta espesa y viva, que amortiguaba la luz del nuevo día, dejé sin esperar más el borde del monte y marché lentamente a través del campo, cuyo suelo por todas partes despedía gratos aromas. Un aura blanda e invariable me oreaba la frente con no mayor fuerza que la de un viento suave: a su impulso, todas las verdes frondas se inclinaban trémulas hacia el lado a que proyecta su primera sombra el sagrado monte; pero sin separarse tanto de su derechura, que las avecillas dejaran por esta causa de ejercitar su arte sobre las copas de los árboles, pues antes bien, llenas de alegría, saludaban a las primeras auras, cantando entre las hojas, que acompañaban a sus ritmos haciendo el bajo, con un susurro semejante al que de rama en rama va creciendo en los pinares del llano de Chiassi, cuando Eolo deja escapar el Sirocco.\"},{\"heading\":false,\"text\":\"Ya me habían transportado mis lentos pasos tan adentro de la antigua selva, que no podía distinguir el sitio por donde había entrado, cuando vi interceptado mi camino por un riachuelo, que corriendo hacia la izquierda, doblegaba bajo el peso de pequeñas linfas las hierbas que brotaban en sus orillas. Las aguas que en la tierra se tienen por más puras, parecerían turbias comparadas con aquellas, que no ocultan nada, aunque corran obscurecidas bajo una perpetua sombra, que no da paso nunca a los rayos del Sol ni de la Luna. Detuve mis pasos, y atravesé con la vista aquel riachuelo, para admirar la gran variedad de sus frescas arboledas, cuando se me apareció, como aparece súbitamente una cosa maravillosa que desvía de nuestra mente todo otro pensamiento, una mujer sola, que iba cantando y cogiendo flores de las muchas de que estaba esmaltado todo su camino.\"},{\"heading\":false,\"text\":\"--¡Ah!, hermosa Dama, que te abrasas en los rayos de Amor, si he de dar crédito al semblante que suele ser testimonio del corazón; dígnate adelantarte--le dije--hacia este riachuelo, lo bastante para que pueda comprender qué es lo que cantas. Tú traes a mi memoria el sitio donde estaba Proserpina, y cómo era cuando la perdió su madre, y ella perdió sus lozanas flores.\"},{\"heading\":false,\"text\":\"Así como bailando se vuelve una mujer, con los pies juntos y arrimados al suelo, poniendo apenas uno delante de otro, de igual suerte se volvió aquélla hacia mí sobre las florecillas rojas y amarillas, semejante a una virgen que inclina sus modestos ojos, y satisfizo mis súplicas aproximándose tanto, que llegaba hasta mí la dulce armonía de su canto, y sus palabras claras y distintas. Luego que se detuvo en el sitio donde las hierbas son bañadas por las ondas del lindo riachuelo, me concedió el favor de levantar sus ojos. No creo que saliera tal resplandor bajo las cejas de Venus, cuando su hijo la hirió inconsideradamente. Ella se sonreía desde la orilla derecha, cogiendo mientras tanto las flores que aquella elevada tierra produce sin necesidad de simiente. El río nos separaba a la distancia de tres pasos; pero el Helesponto por donde pasó Jerjes, cuyo ejemplo sirve aún de freno a todo orgullo humano, no fué tan odioso a Leandro, por el impetuoso movimiento de sus aguas entre Sestos y Abydos, como lo era aquél para mí por no abrirme paso.\"},{\"heading\":false,\"text\":\"--Sois recién llegados--dijo ella--; y quizá porque me sonrío en este sitio escogido para nido de la humana naturaleza, os causo asombro y hasta alguna sospecha; pero el salmo \\\"Delectasti\\\" esparce una luz que puede disipar las nubes de vuestro entendimiento. Y tú, que vas delante y me has rogado que hable, dime si quieres oír otra cosa, que yo responderé con presteza a todas tus preguntas hasta dejarte satisfecho.\"},{\"heading\":false,\"text\":\"--El agua--le dije--y el rumor de la floresta impugnan en mi interior una nueva creencia sobre una cosa que he oído y que es contraria a esta.\"},{\"heading\":false,\"text\":\"A lo que ella contestó:\"},{\"heading\":false,\"text\":\"--Te diré cómo procede de su causa eso que te admira, y disiparé la nube que te ciega. El Sumo Bien, que se complace sólo en sí mismo, hizo al hombre bueno y apto para el bien, y le dió este sitio como arras en señal de eterna paz. El hombre, por sus culpas, permaneció aquí poco tiempo: por sus culpas cambió su honesta risa y su dulce pasatiempo en llanto y en tristeza. A fin de que todas las conmociones producidas más abajo por las exhalaciones del agua y de la tierra, que se dirigen cuanto pueden tras del calor, no molestasen al hombre, se elevó este monte hacia el cielo tanto como has visto, y está libre de todas ellas desde el punto donde se cierra su puerta. Ahora bien, como el aire gira en torno de la tierra con la primera bóveda movible del cielo, si el círculo no es interrumpido por algún punto, un movimiento semejante viene a repercutir en esta altura, que está libre de toda perturbación en medio del aire puro, produciendo este ruido en la selva, porque es espesa; y la planta sacudida comunica su propia virtud generativa al aire, el cual girando en torno deposita dicha virtud en el suelo; y la otra tierra, según que es apta por sí misma o por su cielo, concibe y produce diversos árboles de diferentes especies. Una vez oído esto, no te parecerá ya maravilloso que haya plantas que broten sin semillas aparentes. Debes saber, además, que la santa campiña en que te encuentras está llena de toda clase de semillas, y encierra frutos que allá abajo no se cogen. El agua que ves no brota de ninguna vena que sea renovada por los vapores que el frío del cielo convierte en lluvia, como un río que adquiere o pierde caudal, sino que sale de una fuente invariable y segura, que recibe de la voluntad de Dios cuanto derrama por dos partes. Por esta desciende con una virtud que borra la memoria del pecado; por la otra renueva la de toda buena acción. Aquí se llama Leteo; en el otro lado, Eunoe; y no produce sus efectos si no se bebe aquí primero que allí: su sabor supera a todos los demás. Aunque tu sed esté ya bastante mitigada sin necesidad de más explicaciones mías, por una gracia especial, aún te daré un corolario; y no creo que mis palabras te sean menos gratas, si por ti exceden a mis promesas. Los que antiguamente fingieron la edad de oro y su estado feliz, quizá soñaron en el Parnaso este sitio. Aquí fué inocente el origen de la raza humana; aquí la primavera y los frutos son eternos: este es el verdadero néctar de que todos hablan.\"},{\"heading\":false,\"text\":\"Entonces me volví completamente hacia mis Poetas y vi que habían acogido con una sonrisa esta última explicación: después dirigí de nuevo mis ojos hacia la bella Dama.\"}]},{\"title\":\"Purgatorio — canto vigesimonono\",\"blocks\":[{\"heading\":false,\"text\":\"Después de aquellas últimas palabras, continuó cantando cual mujer enamorada: \\\"Beati, quorum tecta sunt peccata\\\"[89]: y a la manera de las ninfas, que andaban solas por las umbrías selvas, complaciéndose unas en huír del Sol, y otras en verle, púsose a caminar por la orilla contra la corriente del río; y yo al igual de ella, seguí sus cortos pasos con los míos. Entre los dos no habíamos aún adelantado ciento, cuando las dos riberas equidistantes presentaron una curva, de tal modo que me encontré vuelto hacia Oriente. A poco de andar así, volvióse la Dama enteramente a mí, diciendo: \\\"Hermano mío, mira y escucha.\\\" Y he aquí que por todas partes iluminó la selva un resplandor tan súbito, que dudé si había sido un relámpago; mas como éste desaparece en cuanto brilla, y aquél duraba cada vez más resplandeciente, decía yo entre mí: \\\"¿Qué será esto?\\\" Circulaba por el luminoso aire una dulce melodía, por lo cual mi buen celo me hizo censurar el atrevimiento de Eva; pues que allí, donde obedecían la tierra y el cielo, una mujer sola y apenas formada, no pudo sufrir el permanecer bajo ningún velo; cuando si hubiera permanecido resignado bajo él, habría yo gozado más pronto, y luego eternamente aquellas inefables delicias.\"},{\"heading\":false,\"text\":\"[89] Beati, quorum remissae sunt iniquitates, et quorum tecta sunt peccata: palabras del segundo Salmo penitencial, con las cuales la Dama congratula a Dante por verle limpio de las manchas de los siete pecados. Esta Dama representa, según algunos comentadores, la Iglesia católica.\"},{\"heading\":false,\"text\":\"Mientras iba yo enteramente absorto en la contemplación de tantas primicias del placer eterno, y deseoso todavía de más dichas, el aire, semejante a un gran fuego, apareció ante nosotros inflamado bajo las verdes ramas, y la dulce armonía que habíamos percibido se convirtió en un canto claro y distinto. ¡Oh sacrosantas Vírgenes! Si alguna vez he soportado por vosotras el hambre, el frío y las vigilias, prestadme en cambio la ayuda, que la necesidad me obliga a demandaros. Es preciso que Helicón derrame para mí sus aguas, y que el coro de Urania me ayude a poner en versos cosas apenas concebibles.\"},{\"heading\":false,\"text\":\"Parecióme ver algo más allá siete árboles de oro[90], engañado por la gran distancia que todavía mediaba entre nosotros y ellos; mas cuando me hube aproximado tanto, que la semejanza engañadora del sentido no perdía ya por la distancia ninguno de sus rasgos distintivos, la facultad que prepara materia al raciocinio me hizo conocer que eran candelabros, y que las voces cantaban \\\"Hosanna.\\\" Los hermosos muebles llameaban en su parte superior despidiendo una luz mucho más clara que la Luna a media noche y a la mitad de su mes. Me volví lleno de admiración al buen Virgilio, y él me respondió con una mirada no menos llena de asombro. Después fijé de nuevo mi atención en los altos candelabros, los cuales avanzaban en nuestra dirección tan lentamente que una recién desposada los habría vencido en celeridad. La Dama me gritó:\"},{\"heading\":false,\"text\":\"--¿Por qué contemplas con tanto ardor esas vívidas luces, y no reparas en lo que viene tras de ellas?\"},{\"heading\":false,\"text\":\"[90] Según unos comentadores, los siete dones del Espíritu Santo; según otros, los siete sacramentos.\"},{\"heading\":false,\"text\":\"Entonces vi venir detrás de las luces, y como guiadas por éstas, muchos personajes[91], vestidos de un blanco tan puro como no ha brillado jamás en el mundo. A la izquierda resplandecía el agua, y reflejaba la parte izquierda de mi cuerpo; así es que me miraba en ella como en un espejo. Cuando desde mi orilla llegué a un punto en que únicamente el río me separaba de aquéllos, me detuve para mirar mejor, y vi las llamas caminando hacia adelante, dejando tras de sí pintado el aire con rasgos semejantes a banderolas extendidas; de modo que sobre ellas se veían claramente siete listas formadas de los colores de que el Sol hace su arco y Delia su cinturón. Aquellas listas se extendían por el cielo más allá de lo que alcanzaba mi vista, y según me pareció, las de los extremos distaban entre sí diez pasos una de otra[92]. Bajo el hermoso cielo que describo, se adelantaban de dos en dos veinticuatro ancianos coronados de azucenas[93]. Todos cantaban: \\\"Bendita tú eres entre las hijas de Adán, y benditas sean eternamente tus bellezas.\\\" Después que las flores y las frescas hierbecillas que había en la otra ribera frente a mí se vieron libres de aquellos espíritus elegidos, así como en el cielo siguen unas a otras las estrellas, en pos de los ancianos vinieron cuatro animales, con ellos coronados de verdes hojas[94]. Cada uno tenía seis alas, con las plumas llenas de ojos, como serían los de Argos si viviese[95]. Lector, no empleo mis rimas en describir las formas de estos animales, pues me contiene tanto el gasto futuro, que no puedo ser ahora pródigo; pero puedes leer a Ezequiel, que los pinta tales como los vió acudir de las frías regiones, con el viento, con las nubes y con el fuego; y del mismo modo que los encontrarás en sus libros, así se presentaban aquí si se exceptúa que, en cuanto a las alas, Juan está conmigo y se separa de él. El espacio que quedaba entre los cuatro lo ocupaba un carro triunfal sobre dos ruedas, que iba tirado por un grifo. Este extendía sus alas ante la lista de en medio y las tres de ambos lados, sin que interceptara ninguna de ellas al hender el espacio entre las mismas comprendido. Se elevaban tanto, que se las perdía de vista: la parte de su cuerpo que era ave tenía los miembros de oro, y los de la otra parte eran blancos manchados de rojo. Ni Escipión el Africano, ni aun Augusto, hicieron jamás recrearse a Roma en la contemplación de un carro tan bello, y aun comparado con él, sería pobre aquel carro del Sol, que desviándose de su camino, fué abrasado, por los ruegos de la Tierra suplicante, cuando Júpiter fué misteriosamente justo.\"},{\"heading\":false,\"text\":\"[91] Los patriarcas, profetas y otros santos varones, que creyeron en la venida de Jesucristo.\"},{\"heading\":false,\"text\":\"[92] Estos diez pasos figuran, según todos los comentadores, los diez mandamientos.\"},{\"heading\":false,\"text\":\"[93] Símbolos de los libros del Antiguo Testamento.\"},{\"heading\":false,\"text\":\"[94] Símbolos de los cuatro Evangelistas.\"},{\"heading\":false,\"text\":\"[95] Las alas son símbolo de la prontitud con que el Evangelio recorrió el mundo. Los ojos, semejantes a los de Argos, lo son de la vigilancia que es necesaria para mantener pura la verdad evangélica contra los sofismas de que se valen las pasiones.\"},{\"heading\":false,\"text\":\"Tres mujeres venían danzando en redondo al lado de la rueda derecha; una de ellas tan roja, que apenas se la hubiera distinguido dentro del fuego: la otra era como si su carne y sus huesos fuesen de esmeralda: la tercera parecía nieve recién caída[96]. Tan pronto iba a la cabeza la blanca, como la roja; y según el canto de ésta, así las demás ajustaban el paso, avanzando lentas o rápidas. Hacia la izquierda del carro venían gozosas otras cuatro vestidas de púrpura asustando sus movimientos al de una de ellas, que tenía tres ojos en la cabeza.[97] En pos de estos grupos de que acabo de hablar, vi dos ancianos con diferentes vestiduras; pero iguales en su actitud, venerable y reposada. Uno de ellos parecía ser de los discípulos de aquel gran Hipócrates, a quien hizo la naturaleza en favor de los seres animados que le son más queridos;[98] el otro demostraba un cuidado contrario, con una espada tan reluciente y aguda, que a través del río me causó miedo.[99] Después vi otros cuatro de humilde apariencia;[100] y detrás de todos venía un anciano solo y durmiendo, pero con la faz inspirada.[101] Estos siete estaban vestidos como los veinticuatro primeros; pero no iban coronados de azucenas, sino de rosas y de otras flores coloradas; quien los hubiese visto desde algo lejos, habría jurado que ardía una llama sobre sus sienes. Cuando el carro estuvo frente a mí, se oyó un trueno; y aquellos dignos personajes, como si se les hubiera prohibido seguir adelante, se detuvieron allí al mismo tiempo que los candelabros.\"},{\"heading\":false,\"text\":\"[96] Las tres virtudes teologales: la Fe, color de nieve; la Esperanza, color de esmeralda, y la Caridad, color de fuego.\"},{\"heading\":false,\"text\":\"[97] Las cuatro Virtudes cardinales: Prudencia, Justicia, Fortaleza y Templanza. Se suponen tres ojos a la Prudencia: con uno mira al pasado, para sacar un recuerdo provechoso; con el otro al presente, para no equivocarse al tomar una determinación; y con el otro al porvenir, para evitar a tiempo el mal y prepararse al bien.\"},{\"heading\":false,\"text\":\"[98] San Lucas.\"},{\"heading\":false,\"text\":\"[99] San Pablo.\"},{\"heading\":false,\"text\":\"[100] Los apóstoles Santiago, Pedro, Juan y Judas, escritores de las Epístolas canónicas; y dice de humilde apariencia, porque sus escritos son breves.\"},{\"heading\":false,\"text\":\"[101] S. Juan Apóstol, que cuando escribió el Apocalipsis, estaba cercano a los noventa años.\"}]},{\"title\":\"Purgatorio — canto trigesimo\",\"blocks\":[{\"heading\":false,\"text\":\"Cuando se detuvo el septentrión del primer Cielo, que no conoció nunca orto ni ocaso, ni más niebla que el velo que sobre él corrió el pecado, y que allí enseñaba a cada cual su deber, como el septentrión más bajo lo enseña al que dirige el timón para llegar al puerto, los veraces personajes que iban entre el Grifo y los siete candelabros se volvieron hacia el carro, como hacia el fin de sus deseos; y uno de ellos como enviado del Cielo, exclamó tres veces cantando: \\\"Veni, sponsa, de Libano,\\\" y todos los demás cantaron lo mismo después de él. Así como los bienaventurados, cuando llegue la hora del juicio final, se levantarán con presteza de sus tumbas, cantando \\\"Aleluya\\\" con su voz recobrada por fin, del mismo modo se elevaron sobre el carro divino, \\\"ad vocem tanti senis,\\\" cien ministros y mensajeros de la vida eterna. Todos decían: \\\"Benedictus qui venis,\\\" y después, esparciendo flores por encima y alrededor, añadían: \\\"Manibus o date lilia plenis.\\\"\"},{\"heading\":false,\"text\":\"Yo he visto, al romper el día, la parte oriental enteramente sonrosada, el resto del cielo adornado de una hermosa serenidad, y la faz del Sol naciente cubierta de sombras, de suerte que a través de los vapores que amortiguaban su resplandor, podía contemplarla el ojo por largo tiempo: del mismo modo, a través de una nube de flores que salía de manos angelicales y caía sobre el carro y en torno suyo, se me apareció una dama coronada de oliva sobre un velo blanco, cubierta de un verde manto, y vestida del color de una vívida llama.[102] Mi espíritu, que hacía largo tiempo no había quedado abatido, temblando de estupor en su presencia, sin que mis ojos la reconocieran, sintió no obstante el gran poder del antiguo amor, a causa de la oculta influencia que de ella emanaba. En cuanto hirió mis ojos la alta virtud que me había avasallado antes de que yo saliera de la infancia, me volví hacia la izquierda, con el mismo respeto con que corre el niño hacia su madre, cuando tiene miedo, o cuando está afligido, para decir a Virgilio: \\\"No ha quedado en mi cuerpo una sola gota de sangre que no tiemble; reconozco las señales de mi antigua llama.\\\" Pero Virgilio nos había privado de sí; Virgilio, el dulcísimo padre, Virgilio, que me había sido enviado por aquélla para mi salvación. Ni aun todo lo que perdió la antigua madre pudo impedir que mis mejillas enjutas se bañaran en triste llanto.\"},{\"heading\":false,\"text\":\"[102] El velo blanco, el manto verde y el vestido color de fuego, que adornan a Beatriz, simbolizan las tres Virtudes teologales: la corona de oliva indica la Sabiduría.\"},{\"heading\":false,\"text\":\"--¡Dante, no llores todavía; no llores todavía porque Virgilio se vaya, pues es preciso que llores por otra herida!\"},{\"heading\":false,\"text\":\"Como el almirante que va de popa a proa examinando la gente que monta los otros buques, y la anima a portarse bien, del mismo modo sobre el borde izquierdo del carro, vi yo, cuando me volví al oír mi nombre, que aquí se consigna por necesidad, a la Dama que se me apareció anteriormente velada por los halagos angelicales, dirigiendo sus ojos hacia mí de la parte acá del río. Aunque el velo que descendía de su cabeza, rodeado de las hojas de Minerva, no permitiese que se distinguieran sus facciones, con su actitud regia y altiva continuó de esta suerte, como aquel que al hablar reserva las palabras más calurosas para lo último:\"},{\"heading\":false,\"text\":\"--Mírame bien, soy yo; soy en efecto Beatriz, ¿Cómo te has dignado subir a este monte? ¿No sabías que el hombre es aquí dichoso?\"},{\"heading\":false,\"text\":\"Mis ojos se inclinaron hacia las limpias ondas; pero viéndome reflejado en ellas, los dirigí hacia la hierba: tanta fué la vergüenza que abatió mi frente. Parecióme Beatriz tan terrible como una madre irritada a su hijo, porque amarga el sabor de la piedad acerba. Ella guardó silencio, y los ángeles cantaron de improviso: \\\"In te Domine speravi;\\\" pero no pasaron de \\\"pedes meos.\\\" Así como la nieve se congela y endurece al soplo de los vientos de Esclavonia, entre los árboles que crecen sobre el dorso de Italia; y luego se licúa por sí misma, en cuanto la tierra que pierde la sombra envía su aliento, semejante al fuego que derrite una vela; así me quedé sin lágrimas ni suspiros antes que cantasen aquéllos cuyas notas responden siempre a la armonía de las esferas celestiales: mas cuando comprendí por sus dulces palabras que se compadecían de mí más que si hubiesen dicho: \\\"Mujer, ¿por qué así le maltratas?,\\\" el hielo que oprimía mi corazón se deshizo en suspiros y agua, y junto con mi angustia, salió del pecho por la boca y por los ojos. Estando Ella, sin embargo, inmóvil sobre el costado izquierdo del carro, dirigió de este modo sus palabras a las compasivas substancias:\"},{\"heading\":false,\"text\":\"--Vosotros veláis en el eterno día, de modo que ni la noche ni el sueño os roban ninguno de los pasos que da el siglo en su camino: así pues, responderé con más cuidado, a fin de que me comprenda el que allí llora, y sienta un dolor proporcionado a su falta. No solamente por influencia de las grandes esferas que dirigen cada semilla hacia algún fin, según la virtud de la estrella que la acompaña, sino también por la abundancia de la gracia divina (cuya lluvia desciende de tan altos vapores, que no puede alcanzarlos nuestra vista), fué tal ése en su edad temprana por natural disposición, que todos los buenos hábitos habrían producido en él admirables efectos; pero el terreno mal sembrado e inculto se hace tanto más maligno y salvaje, cuanto mayor vigor terrestre hay en él. Por algún tiempo le sostuve con mi presencia: mostrándole mis ojos juveniles, le llevaba conmigo en dirección del camino recto; pero tan pronto como estuve en el umbral de la segunda edad, y cambié de vida, ése se separó de mí y se entregó a otros amores. Cuando subí desde la carne al espíritu, y hube crecido en belleza y virtud, fuí para él menos querida y menos agradable. Encaminó sus pasos por una vía falsa, siguiendo tras engañosas imágenes del bien, que no cumplen totalmente ninguna promesa: ni siquiera me ha valido impetrar para él inspiraciones, por medio de las cuales le llamaba en sueños o de otros modos, según el poco caso que de ellas ha hecho. Tan abajo cayó, que todos mis medios eran ya insuficientes para salvarle, si no le mostraba las razas condenadas. Por él he visitado el umbral de los muertos, y dirigí mis ruegos y mis lágrimas al que le ha conducido hasta aquí. Se hubiera violado el alto decreto de Dios, si pasara el Leteo y gustara tales manjares sin haber pagado alguna parte de la penitencia que hace verter lágrimas.\"}]},{\"title\":\"Purgatorio — canto trigesimoprimero\",\"blocks\":[{\"heading\":false,\"text\":\"¡Oh tú, que estás a la otra parte del sagrado río!--Empezó de nuevo a decir, continuando sin demora, y dirigiéndome de punta sus palabras, que aun de filo me habían parecido tan acerbas--; di, di si esto es verdad--; a tal acusación es preciso que tu confesión corresponda.\"},{\"heading\":false,\"text\":\"Estaba yo tan confuso, que mi voz conmovida se extinguió antes de salir de sus órganos. Ella esperó un momento, y después dijo:\"},{\"heading\":false,\"text\":\"--¿En qué piensas? Respóndeme, pues todavía las aguas del Leteo no han borrado tus tristes recuerdos.\"},{\"heading\":false,\"text\":\"La confusión y el miedo reunidos me arrancaron de la boca un \\\"sí\\\" tan débil, que fué menester el auxilio de la vista para entenderlo. Así como se rompe una ballesta por estar demasiado tirantes la cuerda y el arco, de modo que la flecha da con menos fuerza en el blanco, así yo, quebrantado bajo el peso de tan grave cargo, prorrumpí en lágrimas y suspiros, y la voz enflaquecida vino a expirar entre mis labios. Entonces Ella me dijo:\"},{\"heading\":false,\"text\":\"--En medio de los saludables deseos procedentes de mí, que te impulsaban a amar el bien, más allá del cual no hay nada a que aspirar, ¿qué fosos insuperables o qué cadenas has encontrado para perder de tal modo la esperanza de pasar adelante? ¿Y qué ventajas o atractivos descubriste en el aspecto de los otros bienes, para que debieras rondar en torno de ellos?\"},{\"heading\":false,\"text\":\"Después de haber exhalado un amargo suspiro, apenas tuve bastante voz para responder; voz que mis labios formaron con trabajo. Llorando dije:\"},{\"heading\":false,\"text\":\"--Las cosas presentes con sus falsos placeres desviaron mis pasos, apenas se me ocultó vuestro rostro.\"},{\"heading\":false,\"text\":\"Ella me respondió:\"},{\"heading\":false,\"text\":\"--Aunque callases o negases lo mismo que ahora confiesas, no por eso tu falta sería menos conocida: ¡tal es el Juez que la sabe! Pero cuando la confesión del pecado sale de la propia boca del pecador, la rueda se vuelve en nuestro tribunal contra el filo de la espada. Sin embargo, para que más te aproveche la vergüenza de tu error, y para que otra vez seas más fuerte al oír las sirenas, depón la causa de tu llanto y escucha: de este modo sabrás que mi carne sepultada debía encaminarte en una dirección totalmente contraria. El arte o la naturaleza no te presentaron jamás una cosa tan agradable como los bellos miembros en que estuve contenida, miembros que ahora son polvo de la tierra. Y si el sumo placer de verme te faltó por mi muerte, ¿qué cosa mortal debía excitar después tus deseos? A la primera herida que te causaron las cosas falaces del mundo, debiste elevar tus ojos al cielo, siguiéndome a mí, que no era ya como ellas. No debían abatirse tus alas para esperar allí nuevos golpes, o bien alguna doncellita u otra cualquiera vanidad de tan corta duración. El tierno pajarillo cae en dos o tres asechanzas; pero ante los ojos de los ya cubiertos de pluma en vano se despliegan las redes, en vano se lanzan flechas.\"},{\"heading\":false,\"text\":\"Yo estaba como los niños que, mudos de vergüenza y con los ojos fijos en el suelo, escuchan en pie, reconociendo sus faltas, y arrepentidos. Ella continuó:\"},{\"heading\":false,\"text\":\"--Ya que te muestras tan contrito por lo que has oído, alza la barba, y sentirás más dolor mirándome.\"},{\"heading\":false,\"text\":\"Con menos resistencia se desarraiga la robusta encina, bien al embate de los vientos boreales, o bien al de aquel que viene del país de Jarba, de la que, al oír su orden, opuse yo para levantar la cabeza; y cuando dió el nombre de barba a mi rostro, bien conocí el veneno que encerraban sus palabras. Por fin, cuando alcé la faz, advertí que las primeras criaturas habían cesado de esparcir flores, y mis miradas, poco seguras aún, vieron a Beatriz vuelta hacia la fiera que es una sola persona con dos naturalezas. Cubierta con su velo, y al otro lado de la verde orilla, parecióme que se vencía a sí misma en su primitiva belleza, mucho más de lo que vencía a las demás mujeres cuando vivía en el mundo. La ortiga del arrepentimiento me punzó tanto, que de todas las cosas mortales la que más me desvió de su amor me fué la más odiosa: el remordimiento me oprimió el corazón de tal modo, que caí desmayado. Lo que me sucedió entonces lo sabe aquélla que fué la causa de ello. Cuando el corazón me restituyó la facultad de percibir las cosas exteriores, vi por encima de mí a la Dama que antes había encontrado sola, y la oí decir:\"},{\"heading\":false,\"text\":\"--¡Agárrate, agárrate a mí!\"},{\"heading\":false,\"text\":\"Habíame sumergido en el río hasta la garganta, e impeliéndome tras ella, iba caminando sobre el agua con la ligereza de una lanzadera. Cuando estuve cerca de la dichosa orilla, oí tan dulcemente \\\"Asperges me,\\\" que no sabría recordarlo, cuanto menos escribirlo. La hermosa Dama abrió sus brazos, rodeó con ellos mi cabeza, y me sumergió de modo que hube de beber el agua. Después me sacó fuera, y mojado como estaba me presentó a las cuatro bellas bailarinas, cada una de las cuales extendió sobre mí su brazo.\"},{\"heading\":false,\"text\":\"--Aquí somos ninfas, y en el Cielo estrellas: antes de que Beatriz descendiese al mundo fuimos designadas como siervas suyas. Te conduciremos ante sus ojos; pero las tres del otro lado, que ven más a fondo, aguzarán los tuyos para que percibas la plácida luz que hay dentro de ellos.\"},{\"heading\":false,\"text\":\"Así me dijeron cantando; y después me llevaron hacia el pecho del Grifo, donde estaba Beatriz vuelta hacia nosotros. En seguida añadieron:\"},{\"heading\":false,\"text\":\"--No economices tus miradas: te hemos puesto delante de las esmeraldas, desde donde Amor te lanzó un día sus dardos.\"},{\"heading\":false,\"text\":\"Mil deseos más ardorosos que la llama atrajeron mis ojos hacia aquellos ojos brillantes, que aún estaban fijos en el Grifo. Como el Sol en un espejo, la doble fiera se reflejaba en ellos, ya de un modo, ya de otro. Piensa, lector, si yo estaría maravillado al ver tal objeto permanecer inalterable en sí mismo, y transformándose en su imagen reflejada. Mientras que, llena de estupor y gozosa, mi alma gustaba de aquel alimento que, satisfaciéndola, la hacía más deseosa de él, aquellas tres, que demostraban en su actitud ser de una jerarquía más elevada, se adelantaron danzando al compás de sus angélicos cantares.\"},{\"heading\":false,\"text\":\"--Vuelve, Beatriz, vuelve tus ojos santos (tal era su canción) hacia tu fiel amigo, que ha dado tantos pasos para verte. Por gracia, haznos la gracia de descubrirle tu faz, de modo que contemple la nueva belleza que le ocultas.\"},{\"heading\":false,\"text\":\"¡Oh esplendor de viva luz eterna! ¿Quién es el que habiendo palidecido a la sombra del Parnaso, o bebido en su fuente, no tendría la mente ofuscada, al intentar representarte tal cual apareciste allí donde el cielo te circundaba, resonando con su acostumbrada armonía, cuando al aire libre te descubriste?\"}]},{\"title\":\"Purgatorio — canto trigesimosegundo\",\"blocks\":[{\"heading\":false,\"text\":\"Estaban mis ojos tan fijos y atentos para calmar su sed de diez años, que tenía embotados los otros sentidos, encontrando además aquéllos por todas partes obstáculos que no les permitían cuidarse de ninguna otra cosa; así es que la santa sonrisa los atraía con sus antiguas redes. Pero por fuerza me obligaron aquellas diosas a volver la cabeza hacia la izquierda, porque les oía decir: \\\"Mira demasiado fijamente;\\\" y la disposición en que se encuentran los ojos cuando acaban de ser heridos por los rayos del Sol, me dejó por algún tiempo sin vista; mas cuando se repusieron los míos ante otro pequeño resplandor (y digo pequeño, comparándolo con la gran luz de que me había separado forzosamente), vi que el glorioso ejército se había vuelto hacia la derecha, recibiendo en el rostro los rayos del Sol y los de las siete llamas. Así como para salvarse una cohorte, se retira cobijada bajo los escudos, y se vuelve con su estandarte antes de que haya terminado por completo su evolución, así la milicia del reino celestial que precedía al carro desfiló toda antes de que éste hubiera vuelto su lanza. En seguida las mujeres se volvieron a colocar cerca de las ruedas, y el Grifo puso en movimiento el carro bendito, de tal modo que no se agitó ninguna de sus plumas. La hermosa Dama que me hizo vadear el río, Estacio y yo seguíamos a la rueda que describió al girar el arco menor. Caminando de esta suerte a través de la alta selva deshabitada por culpa de aquella que creyó a la serpiente, ajustaba mis pasos al cántico de los ángeles. Una flecha despedida del arco recorre quizá en tres veces el espacio que habíamos avanzado, cuando bajó Beatriz. Oí que todos murmuraban: \\\"¡Adán!\\\" En seguida rodearon un árbol enteramente despojado de hojas y flores en todas sus ramas. Su copa, que se extendía a medida que el árbol se elevaba, sería, a causa de su altura, admirada por los indios en sus selvas.\"},{\"heading\":false,\"text\":\"--¡Bendito seas, oh Grifo, que con tu pico no arrancaste nada de este tronco dulce al gusto, después que, por haberlo probado, se inclinó al mal el apetito humano!\"},{\"heading\":false,\"text\":\"Así exclamaron todos en derredor del árbol robusto; y el animal de doble naturaleza respondió:\"},{\"heading\":false,\"text\":\"--De ese modo se conserva la semilla de toda justicia.\"},{\"heading\":false,\"text\":\"Y volviéndose al timón de que había tirado, lo condujo al pie de la planta viuda de sus hojas, y dejó atado a ella el carro que era de ella. Así como nuestras plantas se ponen turgentes cuando la gran luz desciende mezclada con aquella que irradia detrás de los celestes Peces, y luego se reviste cada una con su propio color antes que el Sol guíe sus caballos bajo otra estrella, de igual modo se renovó el árbol cuyas ramas estaban antes tan desnudas, adquiriendo colores menos vivos que los de la rosa, pero más que los de la violeta. Yo no pude entender, ni aquí abajo se canta, el himno que aquella gente entonó entonces, ni tampoco pude oír todo el canto hasta el fin. Si me fuera posible describir cómo se adormecieron aquellos desapiadados ojos que tan cara pagaron su excesiva vigilancia, oyendo las aventuras de Siringa, representaría, como un pintor que copia un modelo, el modo como me dormí; pero hágalo quienquiera que sepa figurar bien el sueño.\"},{\"heading\":false,\"text\":\"Paso, pues, al momento en que me desperté, y digo que un resplandor desgarró el velo de mi sueño, al mismo tiempo que me gritaba una voz: \\\"Levántate; ¿qué haces?\\\" Como Pedro, Juan y Jacobo, conducidos a ver las florecitas del manzano, que hace a los ángeles codiciosos de su fruta y perpetuas las bodas en el cielo; y aterrados por el esplendor divino, volvieron en sí al oír la palabra que ha interrumpido sueños mayores, y vieron su compañía mermada por la ausencia de Moisés y Elías, y cambiada la túnica de su Maestro, así desperté yo, viendo inclinada sobre mí a aquella compasiva mujer que había guiado anteriormente mis pasos por el río; lleno de inquietud dije:\"},{\"heading\":false,\"text\":\"--¿Dónde está Beatriz?\"},{\"heading\":false,\"text\":\"A lo que me contestó:\"},{\"heading\":false,\"text\":\"--Mírala sentada sobre las raíces y bajo el nuevo follaje de ese árbol. Mira la compañía que la rodea: los otros se van hacia arriba tras el Grifo, entonando cánticos más dulces y más profundos.\"},{\"heading\":false,\"text\":\"Ignoro si fué más difusa su respuesta; porque se hallaba otra vez ante mis ojos aquella que me impedía fijar la atención en ninguna otra cosa. Estaba sentada ella sola en la tierra verdadera, como dejada allí para custodiar el carro que vi atar a la biforme fiera. En torno suyo formaban un círculo las siete Ninfas, teniendo en las manos aquellas luces que no puede apagar el Aquilón ni el Austro.\"},{\"heading\":false,\"text\":\"--Poco tiempo habitarás esta selva, y serás eternamente conmigo ciudadano de aquella Roma donde Cristo es romano. Por lo tanto, fija tus ojos en este carro para bien del mundo que vive mal, y cuando vuelvas a él, escribe lo que has visto.\"},{\"heading\":false,\"text\":\"Así habló Beatriz; y yo, enteramente sumiso a sus órdenes, puse mi mente y mis ojos donde ella quiso. Nunca tan velozmente partió el rayo de condensada nube, cuando cae del más remoto confín del aire, como vi yo al ave de Júpiter precipitarse y bajar por el árbol, rompiendo su corteza, ya que no las flores y hojas nuevas: y con toda su fuerza hirió al carro, y le hizo vacilar, como nave combatida por la tempestad, que las olas derriban, ora a babor, ora a estribor. Vi luego introducirse en el carro triunfal una zorra, que parecía no haber tomado jamás ningún buen alimento: pero reprendiéndole mi Dama sus feas culpas, la obligó a huír tan precipitadamente como lo permitieron sus descarnados huesos. En seguida, por donde mismo había venido antes, vi al águila descender a la caja del carro, y dejarla cubierta de sus plumas: y semejante a la voz que sale de un corazón contristado, salió del cielo una voz que dijo: \\\"¡Ay, navecilla mía, cuán mal cargada estás!\\\" Después me pareció que se abría la tierra entre las dos ruedas, y vi salir un dragón que hincó su maligna cola en el carro, y retirándola luego como la avispa su aguijón, se llevó consigo una parte del fondo, y se alejó muy contento. Lo que quedó del carro, como la tierra fértil que se cubre de grama, se cubrió de la pluma ofrecida por el águila quizá con intención casta y benigna; y de ella se cubrieron una y otra rueda y la lanza en menos tiempo del que mantiene un suspiro la boca abierta. Transformado de esta suerte el edificio santo, salieron de sus diversas partes varias cabezas, tres de ellas sobre la lanza, y las restantes una en cada ángulo. Las primeras tenían cuernos como los bueyes; pero las otras sólo tenían un cuerno por frente: jamás se han visto semejantes monstruos.\"},{\"heading\":false,\"text\":\"Tan segura como una fortaleza sobre una alta montaña, vi sentada en el carro a una prostituta desenvuelta, paseando sus miradas en torno suyo. Y como para impedir que se la quitaran, vi un gigante colocado en pie junto a ella, y ambos se besaban de vez en cuando; más habiendo ella vuelto hacia mí sus ojos codiciosos y errantes, el feroz amante la azotó desde la cabeza a los pies. Después, lleno de suspicacia y de cruel ira, desató el monstruoso carro, y lo arrastró tan lejos por la selva, que tras de ella se ocultaron a mi vista la prostituta y la nueva fiera.\"}]},{\"title\":\"Purgatorio — canto trigesimotercio\",\"blocks\":[{\"heading\":false,\"text\":\"Las mujeres comenzaron llorosas una dulce salmodia, cantando alternativamente, ya las tres, ya las cuatro: \\\"Deus, venerunt gentes.\\\"[103] Y Beatriz, suspirando compasiva, las escuchaba tan abatida, que poco más lo estuvo María al pie de la Cruz. Pero cuando las otras vírgenes le dieron ocasión de hablar, poniéndose en pie, respondió encendida como el fuego:\"},{\"heading\":false,\"text\":\"--\\\"Modicum, et non videbitis me; et iterum,\\\" mis queridas hermanas, \\\"modicum, et vos videbitis me.\\\"[104]\"},{\"heading\":false,\"text\":\"[103] Cantan, alternando, los versículos del salmo LXXVIII, que el poeta aplica en este lugar a las desventuras de la Iglesia cristiana.\"},{\"heading\":false,\"text\":\"[104] \\\"Dentro de poco no me veréis: pero dentro de otro poco me veréis.\\\" Palabras de Jesús, en el Evangelio de San Juan, prediciendo su próxima muerte y su resurrección.\"},{\"heading\":false,\"text\":\"Después reunió ante sí a todas siete, y con sólo un ademán, nos hizo marchar tras ellas a mí, a la Dama, y al sabio que quedó en nuestra compañía. Así se alejaba, y no creo que hubiese dado diez pasos, cuando hirió mis ojos con sus ojos, y con aspecto tranquilo me dijo:\"},{\"heading\":false,\"text\":\"--Ven más de prisa, de modo que si hablo contigo, estés dispuesto a escucharme.\"},{\"heading\":false,\"text\":\"Cuando estuve cerca de ella, como debía, añadió:\"},{\"heading\":false,\"text\":\"--Hermano, ¿por qué, viniendo conmigo, no te atreves a preguntarme algo?\"},{\"heading\":false,\"text\":\"Me sucedió lo que a aquellos que, por excesiva reverencia, al hablar con sus superiores, no pueden hacer salir con viveza las palabras de entre sus dientes, y contesté balbuceando:\"},{\"heading\":false,\"text\":\"--Señora, vos conocéis mis necesidades y lo que les conviene.\"},{\"heading\":false,\"text\":\"Contestóme:\"},{\"heading\":false,\"text\":\"--Quiero que en adelante te despojes de ese temor y esa vergüenza, para que no hables como hombre que sueña. Sabe que el vaso que rompió la serpiente fué y no es; pero crea el culpable que la venganza de Dios no se vence con sortilegios. El águila que dejó sus plumas en el carro, convirtiéndolo en un monstruo y después en una presa, no estará siempre sin herederos; pues veo ciertamente, y por eso lo refiero, algunas estrellas ya cercanas a un tiempo seguro de todo obstáculo y de todo impedimento, en el cual un quinientos diez y cinco,[105] enviado por Dios, destruirá a la ramera, y a aquel gigante que con ella delinque. Y quizá mi predicción obscura, como los oráculos de Temis y de la Esfinge, no te persuade, porque, como ellos, ofusca el entendimiento; pero en breve los hechos serán las Náyades que resuelvan este difícil enigma, sin temor por los ganados y los trigos. Anota estas palabras, y tales como salen de mis labios enséñaselas a los que viven con aquella vida que no es más que una rápida carrera hacia la muerte: acuérdate además, cuando las escribas, de no ocultar cómo has visto la planta, que ha sido robada dos veces. Quien la despoja o la rompe ofende con una blasfemia de hecho a Dios, que la hizo santa sólo para su uso. Por haber mordido su fruto, la primera alma aguardó en el dolor y en el deseo durante cinco mil años y más al que en sí mismo castigó aquel bocado. Tu espíritu está adormecido, si no comprende que sólo por una causa singular es aquel árbol tan alto, y tan anchurosa su copa: y si los vanos pensamientos no hubiesen sido alrededor de tu mente como las aguas del Elsa, y el placer que te causaron no la hubiera manchado como Píramo manchó la mora, sólo por tantas circunstancias reconocerías moralmente la justicia de Dios en la prohibición de tocar aquel árbol. Mas como veo tu inteligencia petrificada y tan obscurecida por el pecado, que te deslumbra el brillo de mis palabras, quiero que te las lleves, si no escritas, al menos estampadas en ti mismo, por aquel motivo que el peregrino lleva el bordón rodeado de palmas.\"},{\"heading\":false,\"text\":\"[105] Esto es, un DXV, letras que transportadas equivalen a un DVX, o Capitán, o, como otros quieren, iniciales abreviativas de Dante Xristi Vertagus, Domini Xristi Vicarius, Dominus Xristi Victor o Vitor, etc.\"},{\"heading\":false,\"text\":\"Le contesté:\"},{\"heading\":false,\"text\":\"--Así como la cera conserva inalterable la imagen que en ella imprime el sello, del mismo modo la vuestra ha quedado grabada en mi cerebro. Pero ¿por qué vuestra deseada palabra se eleva tanto sobre mi entendimiento, que cuanto más procura comprenderla menos lo consigue?\"},{\"heading\":false,\"text\":\"--Para que conozcas--dijo--aquella escuela que has seguido, y cómo ha de poder su doctrina seguir a mis palabras; y veas que vuestro camino se separa tanto del divino, cuanto de la Tierra dista el cielo que gira más velozmente a la mayor altura.\"},{\"heading\":false,\"text\":\"Entonces le respondí:\"},{\"heading\":false,\"text\":\"--No recuerdo haberme alejado jamás de vos, ni me remuerde por ello la conciencia.\"},{\"heading\":false,\"text\":\"--Es que tú no puedes recordarlo--me dijo sonriéndose--; acuérdate de que has bebido las aguas del Leteo; y si del humo se deduce el fuego, de ese olvido se infiere claramente que tu voluntad, ocupada en otras cosas, era culpable. Pero en adelante serán mis palabras tan desnudas cuanto es preciso descubrirlas a tu rudo entendimiento.\"},{\"heading\":false,\"text\":\"El Sol, más resplandeciente y con pasos más lentos, atravesaba el círculo del Meridiano, que cambia de posición según de donde se mira, cuando al extremo de una opaca umbría, semejante a las que se ven bajo las verdes hojas y las negruzcas ramas por donde llevan los Alpes sus fríos riachuelos, se detuvieron las siete mujeres, como se detiene la tropa que va de avanzada, si encuentra alguna novedad en su camino. Ante ellas me pareció ver salir el Tigris y el Eufrates de un mismo manantial, y como amigos separarse lentamente.\"},{\"heading\":false,\"text\":\"--¡Oh luz!, ¡oh gloria de la raza humana! ¿Qué agua es esta que mana de una misma fuente, y dividida, se aleja una de otra?\"},{\"heading\":false,\"text\":\"A tal pregunta se me contestó:\"},{\"heading\":false,\"text\":\"--Ruega a Matilde que te lo diga.\"},{\"heading\":false,\"text\":\"Y la hermosa Dama respondió como aquel que se disculpa:\"},{\"heading\":false,\"text\":\"--Ya le he dicho esta y otras varias cosas; y estoy segura de que el agua del Leteo no se las ha hecho olvidar.\"},{\"heading\":false,\"text\":\"Beatriz añadió:\"},{\"heading\":false,\"text\":\"--Quizá un interés mayor, de esos que muchas veces quitan la memoria, ha obscurecido su mente con respecto a los demás objetos. Pero mira el Eunoe, que por allí se desliza; condúcele hacia él, y según acostumbras, reanima su amortecida virtud.\"},{\"heading\":false,\"text\":\"Como una alma gentil que de nada se excusa, sino que adapta su voluntad a la de los otros en cuanto se la dan a conocer por medio de alguna seña, de igual suerte se puso en marcha la bella Dama en cuanto estuve a su lado, y dijo a Estacio con su gracia femenil:\"},{\"heading\":false,\"text\":\"--Ven con él.\"},{\"heading\":false,\"text\":\"Lector, si dispusiera de mayor espacio para escribir, cantaría en parte la dulzura de las aguas de que no me habría saciado nunca; pero como están ya llenos todos los papeles dispuestos para este segundo cántico, el freno del arte no me deja ir más allá.\"},{\"heading\":false,\"text\":\"Volví de aquellas sacrosantas ondas tan reanimado como las plantas nuevas, renovadas con nuevas hojas, purificado y dispuesto para subir a las estrellas.\"},{\"heading\":false,\"text\":\"_PARAISO_\"}]},{\"title\":\"Paraíso — canto primero\",\"blocks\":[{\"heading\":false,\"text\":\"La gloria de Aquél que todo lo mueve se difunde por el universo, y resplandece en unas partes más y en otras menos. Yo estuve en el cielo que recibe mayor suma de su luz, y vi tales cosas, que ni sabe ni puede referirlas el que desciende de allá arriba; porque nuestra inteligencia, al acercarse al fin de sus deseos, profundiza tanto, que la memoria no puede volver atrás. Sin embargo, todo cuanto mi mente haya podido atesorar de lo concerniente al reino santo, será en lo sucesivo objeto de mi cántico.\"},{\"heading\":false,\"text\":\"¡Oh buen Apolo! Haz de mí para este último trabajo un vaso lleno de tu valor, tal como lo exiges para conceder tu laurel amado; pues si hasta aquí tuve bastante con una cima del Parnaso, ahora necesito las dos para entrar en el resto de mi carrera. Entra en mi seno, e inspírame el aliento de que estabas poseído cuando sacaste los miembros de Marsias fuera de su piel.\"},{\"heading\":false,\"text\":\"¡Oh divina virtud! Si te prestas a mí, de modo que yo pueda poner de manifiesto la sombra del reino bienaventurado estampada en mi cabeza, me verás acudir a tu árbol querido y coronarme entonces de aquellas hojas; pues el asunto de mi canto y tu favor me harán digno de ello.\"},{\"heading\":false,\"text\":\"Tan pocas veces, ¡oh Padre!, se recoge el lauro del triunfo, ya como César, ya como poeta (por culpa y vergüenza de la humana voluntad), que cuando alguno arde en deseos de alcanzarlo, el follaje penéico debería difundir la alegría en la feliz deidad délfica. A una pequeña chispa sigue una gran llama: quizá después de mí habrá quien ruegue con mejor voz para que responda Cirra.\"},{\"heading\":false,\"text\":\"La lámpara del mundo se presenta a los mortales por diferentes aberturas; pero cuando se deja ver por aquella en que se unen cuatro círculos formando tres cruces, entonces sale con mejor curso y con mejor estrella, y modela y sella más a su modo la cera de nuestro mundo. Por aquella abertura se había hecho allí de día, y aquí de noche: casi todo aquel hemisferio estaba ya blanco, y la otra parte negra, cuando vi a Beatriz vuelta hacia el lado izquierdo, mirando al Sol; jamás lo ha mirado un águila con tanta fijeza. Y así como un segundo rayo sale del primero, y se remonta a lo alto, semejante al peregrino que quiere volverse, así la acción de Beatriz, penetrando por mis ojos en mi imaginación, originó la mía, y fijé los ojos en el Sol contra nuestra costumbre. Muchas cosas son allí permitidas a nuestras facultades, que no lo son aquí, por ser aquel lugar creado para residencia propia de la especie humana. Me fué imposible mirar por mucho tiempo al Sol; pero no tan poco, que no le viera centellear en torno suyo, como el hierro que sale candente del fuego; y de pronto me pareció que un nuevo día se unía al día, como si Aquél que puede hubiese adornado el Cielo con otro Sol.\"},{\"heading\":false,\"text\":\"Beatriz miraba fijamente las eternas esferas, y yo fijé mis ojos en ella, desviándolos de allá arriba: contemplándola, me transformé interiormente, como Glauco al gustar la hierba que le hizo en el mar compañero de los otros Dioses. No es posible significar con palabras el acto de pasar a un grado superior la naturaleza humana; pero baste el citado ejemplo a quien la gracia divina reserve tal experiencia.\"},{\"heading\":false,\"text\":\"¡Oh Amor, que gobiernas el cielo! Tú, que me elevaste con tu luz, sabes si yo era entonces solamente aquella parte de mí que primero creaste. Cuando la rotación de los cielos, que eternizas por el deseo que estos tienen de poseerte, atrajo mi atención con su armonía, que regularizas y distribuyes, me pareció que entonces se encendía con la llama del Sol tanto espacio del cielo, que ni las lluvias ni los ríos han ocasionado jamás tan extenso lago. La novedad de los sonidos y tan gran resplandor me abrasaron de tal modo en el deseo de conocer su causa, que jamás he sentido tan punzante aguijón. Así es que Ella, que veía mi interior como yo mismo, abrió su boca para calmar mi excitado ánimo, antes que yo la abriera para preguntarle, y empezó a decir:\"},{\"heading\":false,\"text\":\"--Tú mismo te atontas con tus falsas ideas, de tal modo que no ves lo que verías si las hubieras desechado. No estás ya en la Tierra, según te figuras: el rayo, huyendo de la región donde se forma, no corre tan velozmente como tú asciendes hacia ella.\"},{\"heading\":false,\"text\":\"Si vi desvanecida mi primera duda, gracias a sus palabras sonrientes y breves, me vi en cambio más envuelto en otra nueva, y dije:\"},{\"heading\":false,\"text\":\"--Ya me contemplo con placer libre de mi primitiva admiración; mas ahora me asombra cómo es que puedo atravesar por entre estos cuerpos leves.\"},{\"heading\":false,\"text\":\"Por lo cual Beatriz, lanzando un piadoso suspiro, dirigió hacia mí sus ojos con aquel aspecto de que se reviste la madre al oír un desvarío de su hijo, y repuso:\"},{\"heading\":false,\"text\":\"--Todas las cosas guardan un orden entre sí; y este orden es la forma, que hace al universo semejante a Dios. Aquí ven las altas criaturas el signo de la eterna sabiduría, que es el fin para que se ha creado el orden antedicho. En el de que hablo, todas las naturalezas propenden y, según su diversa esencia, se aproximan más o menos a su principio. Así es que se dirigen a diferentes puertos por el gran mar del sér, y cada una con el instinto que se le concedió para que la lleve al suyo. Este instinto es el que conduce al fuego hacia la Luna; el que promueve los primeros movimientos del corazón de los mortales, y el que concentra y hace compacta a la Tierra. Y este arco se dispara, no tan sólo contra las criaturas desprovistas de inteligencia, sino contra las que tienen inteligencia y amor. La Providencia, que todo lo ordena, hace con su luz que esté tranquilo el cielo en el que gira aquél que tiene mayo velocidad: allí es donde ahora, como a sitio designado, nos lleva la virtud de la cuerda de aquel arco que dirige todo cuanto despide hacia un objeto agradable. Bien es verdad que, así como la forma no guarda muchas veces armonía con las intenciones del arte, porque la materia es sorda para contestar, así de esta dirección se desvía tal vez la criatura, que tiene el poder de inclinarse hacia otro lado, por más que esté impulsada de aquel modo, y cae (como se puede ver caer el fuego desde una nube), si su primer impulso la tuerce hacia la Tierra por un falso placer. No debes, pues, a lo que pienso, admirarte más de tu ascensión, que de ver a un río descender desde lo alto de una montaña hasta su base. Lo maravilloso en ti sería que, libre de todo obstáculo, te hubieras sentado abajo, como lo sería el que la viva llama permaneciese quieta y apegada a la Tierra.\"},{\"heading\":false,\"text\":\"Dicho esto, elevó sus ojos al Cielo.\"}]},{\"title\":\"Paraíso — canto segundo\",\"blocks\":[{\"heading\":false,\"text\":\"¡Oh vosotros, que, deseosos de escucharme, habéis seguido en una pequeña barca tras de mi bajel que navega cantando, virad para ver de nuevo vuestras playas! No os internéis en el piélago, porque quizá, perdiéndome yo, quedaríais perdidos. El agua por donde sigo no fué jamás recorrida; Minerva sopla en mi vela, Apolo me conduce y las nueve Musas me enseñan las Osas. Y vosotros los que, en corto número, levantasteis ha tiempo las miradas hacia el pan de los ángeles, del cual se vivo aquí pero sin que nadie quede harto, bien podéis dirigir vuestra nave por el alta mar, siguiendo mi estela sobre el agua que se reúne en breve. Aquellos gloriosos héroes que pasaron a Colcos no se admiraron cuando vieron a Jasón convertido en boyero, como os admiraréis ahora vosotros. La innata y perpetua sed del deiforme reino nos hacía ir tan veloces como veloz veis al mismo cielo. Beatriz miraba hacia arriba, y yo la miraba a ella; y quizá en menos tiempo del en que se coloca un dardo, y se despide del arco y vuela, me vi llegado a un punto donde una cosa admirable atrajo mis miradas: por lo cual, Aquélla para quien no podían estar ocultos mis sentimientos, vuelta hacia mí tan agradable como bella, me dijo:\"},{\"heading\":false,\"text\":\"--Eleva tu agradecida mente hacia Dios, que nos ha transportado a la primera estrella.\"},{\"heading\":false,\"text\":\"Parecíame que se extendiese sobre nosotros una nube lúcida, densa, sólida y bruñida, como un diamante herido por los rayos del Sol. La eterna margarita nos recibió dentro de sí, como el agua que, permaneciendo unida, recibe un rayo de luz. Si yo era cuerpo, y si en la Tierra no se concibe cómo una dimensión pueda admitir a otra, según debe suceder si un cuerpo penetra en otro, debería abrasarnos mucho más el deseo de contemplar aquella esencia, en que se ve cómo Dios y nuestra naturaleza se unieron. Allí se verá esto que creemos por la fe; pero sin demostración alguna, pues será conocido por sí mismo, como la primera verdad en que el hombre cree. Yo respondí:\"},{\"heading\":false,\"text\":\"--Señora, con tanto reconocimiento como cabe en mí, doy gracias a Aquél que me ha alejado del mundo mortal. Pero decidme: ¿qué son las obscuras señales de este cuerpo, que allá abajo en la Tierra dan ocasión a algunos para inventar patrañas sobre Caín?[106]\"},{\"heading\":false,\"text\":\"[106] Las manchas de la Luna, que, según el vulgo, eran Caín con un haz de leña.\"},{\"heading\":false,\"text\":\"Sonrióse un poco, y después me dijo:\"},{\"heading\":false,\"text\":\"--Si la opinión de los mortales se extravía donde la llave de los sentidos no puede abrir, no deberían en verdad punzarte desde ahora las flechas de la admiración; pues ves que, si la razón sigue a los sentidos, debe tener muy cortas las alas; pero dime qué es lo que tú piensas con respecto a esto.\"},{\"heading\":false,\"text\":\"Le contesté:\"},{\"heading\":false,\"text\":\"--Lo que aquí arriba me parece de diferente forma, creo que debe ser producido por cuerpos enrarecidos y por cuerpos densos.\"},{\"heading\":false,\"text\":\"Ella repuso:\"},{\"heading\":false,\"text\":\"--Verás de un modo cierto que tu creencia está basada en una idea falsa, si escuchas bien el argumento que voy a oponerte. La octava esfera os muestra muchas luces, las cuales puede verse que presentan aspectos diferentes así en calidad como en cantidad. Si esto fuera efecto solamente del enrarecimiento y la densidad, en todas ellas habría una sola e idéntica virtud, aunque distribuida en más o menos abundancia y proporcionalmente a sus respectivas masas. Siendo diversas las virtudes, necesariamente han de ser fruto de principios formales; y éstos, menos uno, quedarían destruídos por tu raciocinio. Además, si el enrarecimiento fuese la causa de aquellas manchas acerca de las cuales me preguntas, entonces o el planeta estaría en algunos puntos privado de su materia de parte a parte, o bien del modo que en un cuerpo alternan lo graso y magro, así el volumen de éste se compondría de hojas diferentes. Si fuese cierto lo primero, se manifestaría en los eclipses de Sol, porque la luz de éste pasaría a través de la Luna, como atraviesa por cualquier cuerpo enrarecido. Esto no es así: por lo tanto hemos de examinar el otro supuesto; y si llego también a anularlo, verás demostrado lo falso de tu opinión. Si ese cuerpo enrarecido no llega de un lado a otro de la Luna, es preciso que termine en algún punto donde su contrario no deje pasar la luz, y que el otro rayo reverbere desde allí, como el color se refleja en un cristal que está forrado de estaño. Pero tú dirás que el rayo aparece aquí más obscuro que en otras partes, porque se refracta desde mayor profundidad. De esta réplica puede librarte la experiencia, si haces uso de ella alguna vez, por ser la fuente de donde manan los arroyos de vuestras artes. Toma tres espejos: coloca dos de ellos delante de ti a igual distancia, y el otro un poco más lejos: después fija tus ojos entre los dos primeros. Vuelto así hacia ellos, dispon que a tu espalda se eleve una luz que ilumine los tres espejos, y vuelva a ti reflejada por todos: entonces, aun cuando la luz reflejada sea menos intensa en el más distante, verás que resplandece igualmente en los tres. Desvanecido ya el primer error de tu entendimiento, como a impulso de los cálidos rayos se desvanecen el color y el frío primitivos de la nieve, quiero mostrarte ahora una luz tan viva, que apenas aparezca sentirás sus destellos. Dentro del Cielo de la divina paz se mueve un cuerpo, en cuya virtud reside el ser de todo su contenido. El Cielo siguiente, que tiene tantas estrellas, distribuye aquel sér entre diversas esencias, distintas de él y que en él están contenidas. Los demás cielos, por varios y diferentes modos, disponen para sus fines aquellas cosas distintas que hay en cada uno, y sus influencias. Estos órganos del mundo van así descendiendo de grado en grado, como ahora ves, de suerte que adquieren del superior la virtud que comunican al inferior. Repara bien cómo voy por este camino hacia la verdad que deseas, a fin de que después sepas por ti solo vencer toda dificultad. El movimiento y la virtud de las sagradas esferas deben proceder de los bienaventurados motores, como del artífice procede la obra del martillo. Aquel cielo, al que tantas luces hermosean, recibe forma y virtud de la inteligencia profunda que lo mueve, y se transforma en su sello. Y así como el alma dentro de vuestro polvo se extiende a los diferentes miembros, aptos para distintas facultades, así la inteligencia despliega por las estrellas su bondad multiplicada, girando sobre su unidad. Cada virtud se une de distinto modo con el precioso cuerpo a quien vivifica, y en el cual se infunde como en vosotros la vida. Por la plácida naturaleza de donde se deriva, esa virtud mezclada a los cuerpos celestes brilla en ellos, como la alegría en una pupila ardiente. De ella procede la diferencia que se observa de luz a luz, y no de los cuerpos densos y enrarecidos; ella es el principio formal que produce lo obscuro y lo claro, según su bondad.\"}]},{\"title\":\"Paraíso — canto tercero\",\"blocks\":[{\"heading\":false,\"text\":\"Aquel Sol que primeramente abrasó de amor mi corazón[107] me había descubierto, con sus pruebas y refutaciones, el dulce aspecto de una hermosa verdad; y yo, para confesarme desengañado y persuadido, levanté la cabeza, tanto como era necesario a fin de declararlo resueltamente. Pero apareció una visión, la cual haciéndose perceptible me atrajo de tal modo hacia sí, que ya no me acordé de mi confesión. Así como a través de cristales tersos y transparentes o de aguas nítidas y tranquilas, aunque no tan profundas que se obscurezca el fondo, llegan a nuestra vista las imágenes tan debilitadas, que una perla en una frente blanca no la distinguirían más débilmente nuestros ojos, así vi yo muchos rostros prontos a hablarme; por lo cual caí en el error contrario a aquel que inflamó el amor entre un hombre y una fuente.[108] En cuanto las distinguí, creyendo que fuesen imágenes reflejadas en un espejo, volví los ojos para ver los cuerpos a que correspondían; y como nada vi, los dirigí de nuevo hacia delante, fijándolos en mi dulce Guía, que sonriéndose despedía vívidos destellos de sus santos ojos.\"},{\"heading\":false,\"text\":\"[107] Beatriz.\"},{\"heading\":false,\"text\":\"[108] Alude a la fábula de Narciso.\"},{\"heading\":false,\"text\":\"--No te asombres porque me sonría de tu pueril pensamiento--me dijo--; pues no se apoya todavía tu pie sobre la verdad, y como de costumbre, te inclina a las ilusiones. Esas que ves son verdaderas substancias, relegadas aquí por haber faltado a su votos. Por consiguiente, habla con ellas, y oye y cree lo que te digan; pues la verdadera luz que las regocija no permite que se tuerzan sus pasos.\"},{\"heading\":false,\"text\":\"Y yo me dirigí a la sombra que parecía más dispuesta a hablar, y empecé a decirle, como hombre a quien su mismo deseo le quita el valor.\"},{\"heading\":false,\"text\":\"--¡Oh espíritu bien creado, que bajo los rayos de la vida eterna sientes la dulzura que no se comprende nunca si no se ha gustado! Me será muy grato que te dignes decirme tu nombre y cuál es vuestra suerte.\"},{\"heading\":false,\"text\":\"A lo que contestó pronta y con risueños ojos:\"},{\"heading\":false,\"text\":\"--Nuestra caridad nunca cierra sus puertas a un deseo justo, siendo como aquella que quiere que se le asemeje toda su corte. Yo fuí en el mundo una virgen religiosa; y si tu mente me contempla bien, no me ocultará a tus recuerdos el ser hoy la más bella, sino que reconocerás que yo soy Piccarda: colocada aquí con estos otros bienaventurados, soy como ellos bienaventurada en la esfera más lenta. Nuestros afectos a quienes sólo inflama el amor del Espíritu Santo, se regocijan en el orden designado por él, y nos ha cabido en suerte este sitio que parece tan bajo, porque descuidamos nuestros votos, y en parte no fueron observados.\"},{\"heading\":false,\"text\":\"A lo que le contesté:\"},{\"heading\":false,\"text\":\"--En vuestros admirables rostros resplandece no sé qué de divino, que cambia el primer aspecto que de vosotras se ha conservado. Por eso no fuí más presto en recordar; pero ahora viene en mi ayuda lo que tú me dices, de suerte que me es más fácil reconocerte. Mas dime: vosotras que sois aquí felices ¿deseáis estar en otro lugar más elevado para ver más o para haceros más amigas?\"},{\"heading\":false,\"text\":\"Sonrióse un poco mirando a las otras sombras, y en seguida me respondió tan placentera, que parecía arder en el primer fuego del amor:\"},{\"heading\":false,\"text\":\"--Hermano, la virtud de la caridad calma nuestra voluntad, y esa virtud nos hace querer solamente lo que tenemos, y no apetecer nada más. Si deseáramos estar más elevadas, nuestro anhelo estaría en desacuerdo con la voluntad de Aquél que nos reúne aquí; desacuerdo que no admiten las esferas celestiales, como verás si consideras bien que aquí es condición necesaria estar unidas a Dios por medio de la caridad, y la naturaleza de esta misma caridad. También es esencial a nuestra existencia bienaventurada uniformar la propia voluntad a la de Dios, de modo que nuestras mismas voluntades se refundan en una. Así es que al estar como estamos distribuídas de grado en grado por este reino, place a todo él, porque place al Rey cuya voluntad forma la nuestra. En su voluntad está nuestra paz; ella es el mar adonde va a parar todo lo que ha creado, o lo que hace la naturaleza.\"},{\"heading\":false,\"text\":\"Entonces comprendí claramente por qué en el Cielo todo es Paraíso, por más que la gracia del Supremo Bien no llueva en todas partes por igual. Pero, así como suele suceder que un manjar nos sacie, y que sintamos aún apetito por otro, de suerte que pedimos éste y rechazamos aquél, así hice yo con el gesto y la palabra para saber por ella cuál fué el tejido cuya lanzadera no continuó manejando hasta el fin.\"},{\"heading\":false,\"text\":\"--Una virtud perfecta, un mérito eminente colocan en un cielo más alto a una mujer[109]--me dijo--, según cuya regla se lleva allá abajo en vuestro mundo el hábito y el velo monacal, a fin de que hasta la muerte se viva noche y día con aquel esposo, a quien es grato todo voto que la caridad hace conforme a su deseo. Por seguirla, huí del mundo jovencita aún, y me encerré en su hábito, y prometí observar la regla de su orden. Posteriormente, algunos hombres, más habituados al mal que al bien, me arrebataron de la dulce clausura. ¡Dios sabe cuál fué después mi vida!... Lo que digo de mí, entiende que lo digo asimismo de esta otra alma esplendente que te se muestra a mi derecha, y en quien brilla toda la luz de nuestra esfera: monja fué, y también le arrebataron de la cabeza la sombra de las sagradas tocas; pero cuando volvió al mundo, contra su gusto y contra ley, no se despojó jamás del velo de su corazón. Esa es la luz de la gran Constanza, que del segundo príncipe poderoso de la casa de Suabia engendró al tercero, última potencia de esta raza.\"},{\"heading\":false,\"text\":\"[109] Santa Clara, a cuya orden pertenecía Piccarda.\"},{\"heading\":false,\"text\":\"Así me habló y empezó después a cantar \\\"Ave María,\\\" y cantando desapareció, como una cosa pesada a través del agua profunda. Mi vista, que la siguió tanto cuanto le fué posible, después que la perdió, se volvió hacia el objeto de su mayor deseo, y se fijó enteramente en Beatriz; pero ésta lanzó tales fulgores sobre mi mirada, que no los pude sufrir en el primer momento, por cuya causa tardé más en preguntarle.\"}]},{\"title\":\"Paraíso — canto cuarto\",\"blocks\":[{\"heading\":false,\"text\":\"Un hombre libre de elegir entre dos manjares igualmente distantes de él y que exciten del mismo modo su apetito, moriría de hambre antes de llevarse a la boca uno de ambos. De igual suerte permanecería inmóvil un cordero entre dos hambrientos lobos, temiéndoles igualmente, o un perro entre dos gamos. Por esta razón no me culpo ni me alabo de haber callado, teniéndome en suspenso igualmente dos dudas; pues mi silencio era necesario. Yo callaba; pero tenía pintado en el rostro mi deseo, y en él aparecía más clara mi pregunta que si la hubiera expresado por medio de palabras. Beatriz hizo lo que Daniel al librar a Nabucodonosor de aquella cólera que le había hecho cruel injustamente, y me dijo:\"},{\"heading\":false,\"text\":\"--Bien veo cómo te atrae uno y otro deseo, de modo que tu curiosidad se liga a sí misma de tal suerte, que no se manifiesta con palabras. Tú raciocinas así: si la buena voluntad persevera, ¿por qué razón la violencia ajena ha de disminuir la medida de mi mérito? También te ofrece motivo de duda el que las almas al parecer vuelvan a las estrellas, según la sentencia de Platón. Tales son las cuestiones que pesan igualmente sobre tu voluntad; pero antes me ocuparé en lo que tiene más hiel. El serafín que más goce de Dios, Moisés, Samuel, cualquiera de los dos Juanes que quieras escoger, María misma, no tienen su asiento en un cielo distinto de aquel donde moran esos espíritus que aquí te han aparecido, ni su estado de beatitud tiene fijada más ni menos duración, sino que todos embellecen el primer círculo, y gozan de una vida diferentemente feliz, según que sienten más o menos el Espíritu eterno. Aquí se te aparecieron, no porque les haya tocado en suerte esta esfera, sino para significar que ocupan en la celestial la parte menos elevada. Así es preciso hablar a vuestro espíritu, porque sólo comprende por medio de los sentidos lo que hace después digno de la inteligencia. Por eso la Escritura, atemperándose a vuestras facultades, atribuye a Dios pies y manos, mientras que ella lo ve de otro modo; y la Santa Iglesia os representa bajo formas humanas a Gabriel y a Miguel y al que sanó a Tobías. Lo que Timeo dice acerca de las almas no es figurado, como aquí se ve, pues parece que siente lo que afirma. Dice que el alma vuelve a su estrella, creyendo que se desprendió de ella cuando la naturaleza la unió a su forma. Tal vez su opinión sea diferente de lo que expresan sus palabras, y es posible que la intención de éstas no sea irrisoria. Si quiere decir que la influencia operada por las estrellas se convierte en honor o en vituperio de las mismas, quizá haya dado su flecha en el blanco de una verdad. Este principio, mal comprendido, extravió a casi todo el mundo, haciendo que corriese a invocar a Júpiter, a Mercurio y a Marte. La otra duda que te agita tiene menos veneno, porque su malignidad no te podría alejar de mí. Que nuestra justicia parezca injusta a los ojos de los mortales, es un argumento de fe y no de herética malicia; pero como puede vuestro discernimiento penetrar bien esta verdad, te dejaré satisfecho según deseas. Si hay verdadera violencia cuando el que la sufre no se adhiere en nada a aquel que la comete, aquellas almas no pueden servirse de ella como excusa; porque la voluntad, si no quiere, no se aquieta, sino que hace lo que naturalmente hace el fuego, aunque la tuerzan mil veces con violencia. Por lo cual, si la voluntad se doblega poco o mucho, sigue a la fuerza; y así hicieron aquéllas, pues pudieron haber vuelto al sagrado lugar. Si su voluntad hubiera sido firme, como lo fué la de Lorenzo sobre las parrillas, y como la de Mucio al ser tan severo con su mano, ella misma las habría vuelto al camino de donde las habían separado, en cuanto se vieron libres; pero una voluntad tan sólida es muy rara. Por estas palabras, si es que las has recogido como debes, queda destruído el argumento que te hubiera importunado aún muchas veces. Pero se atraviesa otra dificultad ante tus ojos, y tal que por ti mismo no sabrías salir de ella; antes bien te rendirías fatigado. He dado como cierto a tu mente que el alma bienaventurada no podía mentir, porque está siempre próxima a la primera Verdad; y luego habrás podido oír por Piccarda, que Constanza había guardado su inclinación al velo, de manera que parece contradecirme. Muchas veces, hermano, sucede que por huír de un peligro, se hace con repugnancia aquello que no debería hacerse; como Alcmeón, que, a instancias de su padre, mató a su propia madre, y por no faltar a la piedad, se hizo desapiadado. Con respecto a este punto, quiero que sepas que, si la fuerza y la voluntad obran de acuerdo, resulta que no pueden excusarse las faltas. La voluntad en absoluto no consiente el daño; pero lo consiente en cuanto teme caer en mayor pena oponiéndose a él. Cuando Piccarda, pues, se expresa como lo ha hecho, entiende que habla de la voluntad absoluta, y yo de la otra; de suerte que ambas decíamos la verdad.\"},{\"heading\":false,\"text\":\"Tales fueron las ondulaciones del santo arroyo que salía de la fuente de donde fluye toda verdad, y que aquietaron todos mis deseos.\"},{\"heading\":false,\"text\":\"--¡Oh amada del primer Amante!, ¡oh divina--dije en seguida--, cuyas palabras me inundan comunicándome tal calor que me reaniman cada vez más! No es tan profunda mi afección, que baste a devolveros gracia por gracia; pero que responda por mí Aquél que todo lo ve y lo puede. Bien veo que nuestra inteligencia no queda nunca satisfecha, si no la ilumina aquella Verdad, fuera de la cual no se difunde ninguna otra. En cuanto ha podido alcanzarla, descansa en ella como la fiera en su cubil; y puedo indudablemente conseguirla; de lo contrario, todos nuestros deseos serían vanos. De este deseo de saber nace, como un retoño, la duda al pie de la verdad; siendo esto un impulso de la naturaleza que guía de grado en grado nuestra inteligencia al conocimiento de Dios. Esto mismo me invita, esto mismo me anima, Señora, a pediros reverentemente que me aclaréis otra verdad que encuentro obscura. Quiero saber si el hombre puede satisfaceros, con respecto a los votos quebrantados, por medio de otras buenas acciones que no sean pocas en vuestra balanza.\"},{\"heading\":false,\"text\":\"Beatriz me miró con los ojos llenos de amorosos destellos, y tan divinos, que sintiendo mi fuerza vencida, me volví y quedé como anonadado con los ojos bajos.\"}]},{\"title\":\"Paraíso — canto quinto\",\"blocks\":[{\"heading\":false,\"text\":\"Si te parezco más radiante en el fuego de este amor de lo que suele verse en la tierra, hasta el punto de superar la fuerza de tus ojos, no debes asombrarte, porque esto procede de una vista perfecta, que, distinguiendo bien los objetos, se dirige con más rapidez hacia el bien. Veo claramente cómo resplandece ya en tu inteligencia la eterna luz, que contemplada una sola vez enciende un perpetuo amor. Y si otra cosa seduce el vuestro, sólo es un vestigio mal conocido del resplandor que aquí brilla. Tú quieres saber si con otras buenas acciones puede satisfacerse el voto no cumplido, de modo que el alma esté segura de todo debate con la justicia divina.\"},{\"heading\":false,\"text\":\"Así empezó Beatriz este canto, y como hombre que no interrumpe su razonamiento, continuó de este modo su santa enseñanza:\"},{\"heading\":false,\"text\":\"--El mayor dón que Dios, en su liberalidad, nos hizo al crearnos, como más conforme a su bondad, y el que más aprecia, fué el del libre albedrío de que estuvieron y están dotadas únicamente las criaturas inteligentes. Ahora conocerás, si raciocinas según este principio, el alto valor del voto, si éste es tal que Dios consienta cuando tú consientes; porque al cerrarse el pacto entre Dios y el hombre, se le sacrifica ese tesoro de que hablo, y se le sacrifica por su propio acto. Así, pues, ¿qué se podrá dar en cambio de esto? Si crees que puedes hacer buen uso de lo que ya has ofrecido, es como si quisieras hacer una buena obra con una cosa mal adquirida. Ya conoces, pues, la importancia del punto principal: pero como la Santa Iglesia da sobre esto sus dispensas, lo cual parece contrario a la verdad que te he descubierto, es preciso que continúes sentado un poco a la mesa, porque el pesado alimento que has tomado requiere alguna ayuda para ser digerido. Abre el espíritu a lo que te presento y enciérralo en ti mismo, pues no proporciona ciencia alguna el oír sin retener. Dos cosas son necesarias en la esencia de este sacrificio: una es la materia del voto, y otra el pacto que se forma con Dios. Este último no se borra jamás, si no es observado, y acerca de ello te he hablado antes en términos precisos. Por esta causa fué necesario que los Hebreos continuasen ofreciendo, aunque alguna de sus ofrendas fuese permutada, como debes saber. Respecto a la que te he dado a conocer como materia del voto, puede ser tal que no se cometa yerro alguno al cambiarla en otra materia: pero que ninguno por su propia autoridad mude el fardo de su espalda, sin la vuelta de la llave blanca y de la llave amarilla: crea que todo cambio es insensato, si la cosa abandonada no se contiene en la elegida, como el cuatro está contenido en el seis. Todo lo que pese tanto por su valor, que incline hacia su lado la balanza, no puede reemplazarse con otra cosa. Que los mortales no tomen a broma el voto. Sed fieles, y al comprometeros no seáis ciegos como lo fué Jephté en su primera ofrenda, porque más le valiera haber dicho: \\\"Hice mal,\\\" que hacer otra cosa peor al cumplir su voto: tan insensato como a él puedes suponer al gran jefe de los Griegos,[110] quien obligó a Ifigenia a llorar su hermoso rostro, e hizo llorar por ella a sabios e ignorantes, cuando oyeron hablar de tal sacrificio. Cristianos, sed más pausados en vuestras acciones; no seáis como la pluma a todo viento, ni creáis que toda agua pueda lavaros. Tenéis el Antiguo y el Nuevo Testamento, y el Pastor de la Iglesia que os guía: baste esto para vuestra salvación. Si os dice otra cosa el espíritu del mal, sed hombres, y no locas ovejas, de suerte que el judío no se ría de vosotros entre vosotros. No hagáis como el cordero, que deja la leche de su madre, y sencillo y alegre, combate a su placer consigo mismo.\"},{\"heading\":false,\"text\":\"[110] Agamenón.\"},{\"heading\":false,\"text\":\"Así me habló Beatriz, según lo escribo: después se volvió anhelante hacia aquella parte donde el mundo es más vivo. Su silencio y la mudanza de su semblante impusieron silencio a mi ávido espíritu, que tenía ya preparadas nuevas preguntas. Y como la saeta que da en el blanco antes de que haya quedado en reposo la cuerda, así corríamos hacia el segundo reino[111]. Allí vi yo tan contenta a mi Dama cuando penetró en la luz de aquel cielo, que el planeta se volvió más resplandeciente. Y si la estrella se transformó y rió, ¿cuánto más alegre estaría yo, que por mi naturaleza soy en todos sentidos transmutable? Así como en un vivero, que está tranquilo y puro, acuden solícitos los peces al objeto procedente del exterior, por creerlo su pasto, así vi yo más de mil almas esplendorosas acudir hacia nosotros, y a cada cual de ellas se oía exclamar: \\\"¡He ahí quien acrecentará nuestros amores!\\\" Y tan pronto como cada una se nos acercaba, conocíase su júbilo por el claro fulgor que de ella salía. Piensa, lector, cuál sería tu impaciente anhelo de saber, si lo que aquí empieza no siguiese adelante, y por ti comprenderás cuánto sería mi deseo de conocer la condición de estas almas, en cuanto se presentaron a mi vista.\"},{\"heading\":false,\"text\":\"[111] Al cielo de Mercurio.\"},{\"heading\":false,\"text\":\"--¡Oh bien nacido, a quien está concedida la gracia de ver los tronos del triunfo eterno, antes de haber abandonado la milicia de los vivos! Nosotros nos abrasamos en el fuego que se extiende por todo el cielo: así, pues, si deseas que te iluminemos acerca de nuestra suerte, puedes saciarte según tu deseo.\"},{\"heading\":false,\"text\":\"Así me dijo uno de aquellos espíritus piadosos, y Beatriz añadió:\"},{\"heading\":false,\"text\":\"--Di, di con toda confianza, y créeles como a Dioses.\"},{\"heading\":false,\"text\":\"--Veo bien cómo anidas en tu propia luz, y que la despides por tus ojos, para que resplandezcan cuando ríes; pero no sé quién eres, ni por qué ocupas, ¡oh alma digna!, el grado de la esfera que se oculta a los mortales con los rayos de otro.\"},{\"heading\":false,\"text\":\"Esto dije dirigiéndome al alma resplandeciente que me había hablado; por lo cual se volvió más luminosa de lo que antes era. Lo mismo que el Sol, que a sí mismo se oculta por su excesiva luz, cuando el calor ha destruído los densos vapores que la amortiguaban, así aquella santa figura se ocultó a causa de su alegría en su mismo fulgor, y encerrada de aquel modo me contestó como se verá en el canto siguiente.\"}]},{\"title\":\"Paraíso — canto sexto\",\"blocks\":[{\"heading\":false,\"text\":\"Después que Constantino volvió el águila contra el curso del Cielo que antes siguiera tras el antiguo esposo de Lavinia, cien y cien años y más permaneció el ave de Dios en el extremo de Europa, próxima a los montes de que primitivamente había salido; y bajo la sombra de las sagradas plumas gobernó allí el mundo pasando de mano en mano, hasta que en estos cambios llegó a las mías. César fuí; soy Justiniano, que por voluntad del primer Amor, de que ahora disfruto en el cielo, suprimí de las leyes lo superfluo y lo inútil: antes de haberme dedicado a esta obra, creí que había en Cristo una sola naturaleza y no más, y estaba contento con tal creencia; pero el bendito Agapito, que fué Sumo Pastor, me encaminó con sus palabras a la verdadera fe; yo le creí, y ahora veo claramente cuanto él me decía, así como tú ves en toda contradicción una parte falsa y otra verdadera. En cuanto caminé al par de la Iglesia, plugo a Dios por su gracia inspirarme la grande obra, y me dediqué completamente a ella: confié las armas a mi Belisario, a quien se unió de tal modo la diestra del cielo, que ésta fué para mí una señal de que debía descansar en él. Aquí termina, pues, mi respuesta a tu primera pregunta; pero su condición me obliga a añadir algunas explicaciones. Para que veas con cuán poca razón se levantan contra la sacrosanta enseña los que se la apropian y los que se le oponen, considera cuántas virtudes la han hecho digna de reverencia, desde el día en que Palanto murió para darle el imperio. Tú sabes que aquel signo fijó su mansión en Alba por más de trescientos años, hasta el día en que por él combatieron tres contra tres[112]. Sabes lo que hizo bajo siete reyes, desde el robo de las Sabinas hasta el dolor de Lucrecia, conquistando los países circunvecinos. Sabes lo que hizo llevado por los egregios romanos contra Breno, contra Pirro, contra otros príncipes solos y coligados, por lo cual Torcuato, y Quintio que recibió un sobrenombre por su descuidada cabellera[113], los Decios y los Fabios, conquistaron un renombre que me complazco en admirar. El abatió el orgullo de los árabes que tras de Aníbal pasaron las rocas alpestres de donde tú, Po, te desprendes. A su sombra triunfaron, siendo aún muy jóvenes, Escipión y Pompeyo; y su dominio pareció amargo a aquella colina bajo la cual naciste[114]. Después, cerca del tiempo en que todo el cielo quiso reducir el mundo al estado sereno de que es modelo, César tomó aquel signo por la voluntad del pueblo romano; y lo que hizo desde el Var hasta el Rhin, lo vieron el Isere y el Loira, y lo vió el Sena, y todos los ríos que afluyen al Ródano. Lo que hizo cuando César salió de Ravena y pasó el Rubicón fué con tan levantado vuelo, que no lo podrían seguir la lengua ni la pluma. Hacia España dirigió sus tropas, después hacia Durazzo, y a Farsalia hirió de tal modo, que hasta en las cálidas orillas del Nilo se sintió el dolor. Volvió a ver a Antandro y al Simois de donde había salido, y el sitio donde reposa Héctor; después se alejó de nuevo, con detrimento de Tolomeo. Desde allí cayó como un rayo sobre Juba, y luego se dirigió hacia vuestro Occidente, donde oía la trompa pompeyana. Lo que aquel signo hizo en manos del que lo llevó en seguida lo ladran Bruto y Casio en el Infierno; y de ello se lamentan Módena y Perusa. También llora la triste Cleopatra, que, huyendo ante él, recibió de un áspid muerte cruel y súbita. Con él corrió en seguida al mar Rojo; con él estableció en el mundo paz tan grande que se cerró el templo de Jano. Pero lo que el signo de que hablo había hecho antes, y lo que debía hacer después por el reino mortal que le está sometido, es en la apariencia poco y obscuro, si con mirada clara y con afecto puro se le considera después en manos del tercer César; porque la viva justicia que me inspira le concedió, puesto en manos de aquel a quien me refiero, la gloria de vengar la cólera divina[115]. Admírate, pues, ante lo que voy a repetirte. Con Tito corrió en seguida a tomar venganza de la venganza del pecado antiguo. Cuando el diente lombardo mordió a la Santa Iglesia, venciendo Carlo-Magno bajo sus alas, acudió a socorrerla. En adelante puedes juzgar a los que he acusado más arriba y sus faltas, que son la causa de todos vuestros males. El uno opone a la enseña común las amarillas lises, y el otro se la apropia, no pensando más que en su partido, de suerte que es difícil comprender cuál comete mayor falta. Lleven los gibelinos, lleven a cabo sus empresas bajo otra enseña; que mal sigue ésta a los que ponen un obstáculo entre ella y la justicia; y que este nuevo Carlos no la abata con sus güelfos, pues debe temer las garras que a más feroces leones arrancaron la piel. Muchas veces han tenido que llorar los hijos las faltas de los padres; y no se crea que Dios cambie sus armas por las lises. Esta pequeña estrella está poblada de buenos espíritus, que fueron activos en la Tierra, para dejar en ella memoria de su honor y su fama; y cuando los deseos se elevan hacia tales objetos desviándose del Cielo, es preciso que los rayos del verdadero amor se eleven también con menos viveza; pero nuestra beatitud consiste en la medida de las recompensas con nuestros méritos, porque no la vemos mayor ni menor que éstos. La viva justicia endulza, pues, de tal modo en nosotros el deseo, que nunca puede dirigirse éste a ninguna malicia. Diversas voces despiden dulce armonía; así también los diversos grados de gloria de nuestra vida producen una dulce armonía entre estas esferas. Dentro de la presente margarita fulgura la luz de Romeo[116], cuya hermosa y grande obra fué tan mal agradecida. Pero los Provenzales que se declararon en contra suya no se han reído por mucho tiempo; porque mal camina quien convierte en desgracia propia los beneficios que ha recibido de otro. Raimundo Berenguer tuvo cuatro hijas; todas fueron reinas, y esto lo hizo Romeo, persona humilde y errante peregrino; pero después algunas palabras envidiosas movieron a aquél a pedir cuentas a este justo, que le dió siete y cinco por diez, por lo cual partió pobre y anciano; y si el mundo hubiera sabido cuál era su corazón al mendigar pedazo a pedazo su vida, le ensalzaría más de lo que ahora le ensalza.\"},{\"heading\":false,\"text\":\"[112] Alude al combate de los Horacios y los Curiacios, en que éstos fueron vencidos por aquéllos, quedando Alba sujeta al dominio romano.\"},{\"heading\":false,\"text\":\"[113] Cincinato.\"},{\"heading\":false,\"text\":\"[114] Alude a la destrucción de Fiésole, ocasionada por haber dado asilo esta ciudad a Catilina. En su lugar fué edificada Florencia, donde nació Dante.\"},{\"heading\":false,\"text\":\"[115] El emperador Tiberio.\"},{\"heading\":false,\"text\":\"[116] Hombre de obscuro nacimiento, que al volver de su peregrinación a Santiago de Galicia, llegó a Provenza y se acomodó en casa del conde Raimundo Berenguer. Administrando los bienes de éste, los acrecentó de tal modo que lo que valía diez valió después doce, lo que fué causa de que cuatro hijas del Conde se casaran con cuatro reyes. Romeo, malquistado con Raimundo por algunos barones envidiosos, se separó de él, y fué mendigando su vida.\"}]},{\"title\":\"Paraíso — canto septimo\",\"blocks\":[{\"heading\":false,\"text\":\"\\\"Gloria a ti, Santo Dios de los Ejércitos, que esparces tu claridad sobre los felices fuegos, esto es, sobre las almas dichosas de este reino.\\\" Así oí que cantaba, volviéndose hacia su esfera, aquella substancia, sobre la cual resplandece un doble fulgor. Ella y las otras emprendieron su danza, y cual centellas velocísimas se me ocultaron con su repentino alejamiento. Yo dudaba y decía entre mí: \\\"Dile, dile a mi Dama que calme mi sed con sus dulces palabras.\\\" Pero aquel respeto que se apodera completamente de mí tan sólo al oír B o ICE,[117] me hacía inclinar la cabeza como un hombre que dormita. Beatriz no consintió que yo estuviese así mucho tiempo; e irradiando sobre mí una sonrisa que haría feliz a un hombre en el fuego, empezó a decirme:\"},{\"heading\":false,\"text\":\"[117] Bice, diminutivo de Beatriz. Significa que la reverencia que le causaba sólo el oír pronunciar una sílaba de aquel nombre, le tenía con la cabeza baja y sin atreverse a hablar.\"},{\"heading\":false,\"text\":\"--Según mi parecer infalible, estás pensando cómo fué justamente castigada la justa venganza; pero yo despejaré en breve tu espíritu: escucha, pues, que mis palabras te ofrecerán el dón de una gran verdad. Por no haber soportado un útil freno a su voluntad aquel hombre que no nació[118], al condenarse, condenó a toda su descendencia; por lo cual la especie humana yació enferma por muchos siglos en medio de un grande error, hasta que el Verbo de Dios se dignó descender adonde, por un sólo acto de su eterno amor, unió a sí en persona la naturaleza, que se había alejado de su Hacedor. Ahora mira atentamente lo que digo: Esta naturaleza unida a su Hacedor, tal cual fué creada, era sincera y buena; pero por sí misma fué desterrada del Paraíso, porque se salió del camino de la verdad y de su vida. La pena, pues, que la Cruz hizo sufrir a la naturaleza humana de Jesucristo, si se mide por esa misma naturaleza, fué más justa que otra cualquiera; pero tampoco hubo otra tan injusta, si se atiende a la Persona divina que la sufrió, y a la que estaba unida aquella naturaleza. Por lo tanto, aquel hecho produjo efectos diferentes; porque la misma muerte fué grata a Dios y a los Judíos; por ella tembló la Tierra, y por ella se abrió el Cielo. No te debe ya parecer tan incomprensible cuando te digan que un tribunal justo ha castigado una justa venganza. Mas ahora veo tu mente comprimida, de idea en idea, en un nudo, del que espera con ansia verse libre. Tú dices: \\\"Comprendo bien lo que oigo; pero no veo bien por qué Dios quisiera valerse de este medio para nuestra redención.\\\" Este decreto, hermano, está velado a los ojos de todo aquel cuyo espíritu no haya crecido en la llama de la caridad. Y en efecto, como se examina mucho este punto, y se le comprende poco, te diré por qué fué elegido aquel medio como el más digno. La divina bondad, que rechaza de sí todo rencor, ardiendo en sí misma centellea de tal modo, que hace brotar las bellezas eternas. Lo que procede inmediatamente de ella sin otra cooperación no tiene fin; porque nada hace cambiar su sello una vez impreso. Lo que sin cooperación procede de ella es completamente libre, porque no está sujeto a la influencia de las cosas secundarias; y cuanto más se le asemeja, más le place, pues el amor divino que irradia sobre todo, se manifiesta con mayor brillo en lo que se le parece más. La criatura humana disfruta la ventaja de todos estos dones; pero si le falta uno solo, es preciso que decaiga su nobleza. Sólo el pecado es el que le arrebata su libertad y su semejanza con el Sumo Bien; por lo cual refleja muy poco su luz, y no vuelve a adquirir su dignidad, si no llena de nuevo el vacío que dejó la culpa, expiando sus malos placeres por medio de justas penas. Cuando vuestra naturaleza entera pecó en su germen, se vió despojada de estas dignidades y lanzada del Paraíso, y no hubiera podido recobrarlas (si lo examinas sutilmente) por ningún camino, sin pasar por uno de estos vados: o porque Dios, en su bondad, perdonara el pecado, o porque el hombre por sí mismo redimiera su falta. Fija ahora tus miradas en el abismo del Consejo eterno, y está tan atento como puedas a mis palabras. El hombre no podía jamás, en sus límites naturales, dar satisfacción, por no poder después humillarse con su obediencia tanto cuanto pretendió elevarse con su desobediencia; y esta es la causa porque el hombre fué exceptuado de poder dar satisfacción por sí mismo. Era preciso, pues, que Dios condujera al hombre a la vida sempiterna por sus propias vías, bien por una, o bien por ambas. Pero, como la obra es tanto más grata al obrero, cuanto más representa la bondad del corazón de donde ha salido, la divina bondad, que imprime al mundo su imagen, se regocijó de proceder por todas sus vías para elevaros hasta ella. Entro el primer día y la última noche no hubo ni habrá jamás un procedimiento tan sublime y magnífico, de cualquier modo que se le considere; porque al entregarse Dios a sí mismo, haciendo al hombre apto para levantarse de su caída, fué más liberal que si le hubiese perdonado por su clemencia; y todos los demás medios eran insuficientes ante la justicia, si el Hijo de Dios no se hubiera humillado hasta encarnarse. Ahora, para colmar bien todos tus deseos, vuelvo atrás, a fin de aclararte algún punto de modo que lo veas como yo. Tú dices: \\\"Yo veo el aire, veo el fuego, el agua, la tierra y todas sus mezclas llegar a corromperse y durar poco; y estas cosas, sin embargo, fueron creadas: ahora bien, si lo que has dicho es cierto, deberían estar al abrigo de la corrupción.\\\" Los ángeles, hermano, y el país libre y puro en que estás, pueden decirse creados tales como son, en su eterno sér; pero los elementos que has nombrado, y aquellas cosas que de ellos se componen, tienen su forma de una potencia creada. Creada fué la materia de que están hechos: creada fué la virtud generatriz de las formas en estas estrellas que giran en torno suyo. El rayo y el movimiento de las santas luces sacan de la complexión potencial el alma de todos los brutos y plantas; pero vuestra vida aspira directamente la divina bondad, la cual la enamora de sí de modo que siempre la desea. De aquí puedes deducir aún vuestra resurrección, si reflexionas cómo fué creada la carne humana, cuando fueron creados los primeros padres.\"},{\"heading\":false,\"text\":\"[118] Adán.\"}]},{\"title\":\"Paraíso — canto octavo\",\"blocks\":[{\"heading\":false,\"text\":\"Solía creer el mundo en su peligro, que de los rayos de la bella Ciprina, que gira en el tercer epiciclo, emanaba el loco amor: por esto las naciones antiguas, en su antiguo error, no solamente la honraban por medio de sacrificios y de ruegos votivos, sino que también honraban a Dione y a Cupido, a aquélla como madre, y a éste como hijo suyo, de quien decían que estaba sentado en el regazo de Dido. Y de ésta que he citado al empezar mi canto dieron nombre a la estrella que el Sol mira placentero, ya contemplando sus pestañas, ya su cabellera[119].\"},{\"heading\":false,\"text\":\"[119] Ya cuando va tras de él y se llama Espero, ya cuando va delante y se llama Lucífero, de cuya palabra hemos hecho los españoles lucero.\"},{\"heading\":false,\"text\":\"Yo no advertí mi ascensión a ella; pero me cercioré de que estaba en su interior, cuando vi a mi Dama adquirir más hermosura. Y así como se ve la chispa en la llama, y se distinguen dos voces entre sí, cuando la una sostiene una nota y la otra ejecuta varias modulaciones, del mismo modo vi en aquella luz otros resplandores que se movían en círculo más o menos ágiles, con arreglo, según creo, a sus dichosas visiones eternas. De fría nube no salieron jamás, visibles o invisibles, vientos tan veloces, que no parecieran entorpecidos y lentos a quien hubiese visto llegar hasta nosotros aquellos divinos fulgores, dejando la órbita comenzada antes en el Cielo de los serafines. Y dentro de los que se nos aparecieron delante resonaba \\\"Hosanna,\\\" tan dulce que nunca me ha abandonado el deseo de volverlo a oír. Entonces se acercó uno de ellos a nosotros, y empezó a decir solo:\"},{\"heading\":false,\"text\":\"--Todos estamos prontos en tu obsequio, para que te regocijes en nosotros. Todos giramos con los príncipes celestiales dentro de la misma órbita, con el mismo movimiento circular y con idéntico deseo que aquellos de quienes has dicho ya en el mundo: \\\"Vosotros que movéis el tercer cielo con vuestra inteligencia\\\"[120], y estamos tan llenos de amor, que por agradarte, no nos será menos dulce un momento de reposo.\"},{\"heading\":false,\"text\":\"[120] Así comienza una canción de Dante en el Convito.\"},{\"heading\":false,\"text\":\"Después que mis ojos se fijaron reverentes en mi Dama, y que ella les dió la seguridad de su contentamiento, los volví hacia la resplandeciente alma que tanto se me había ofrecido, y:\"},{\"heading\":false,\"text\":\"--Di, ¿quién fuiste?--fué mi respuesta, impregnada del mayor afecto.\"},{\"heading\":false,\"text\":\"¡Oh, cuánto más brillante y bella se volvió cuando le hablé, a causa del nuevo gozo que acrecentó sus alegrías! Embellecida de este modo, me dijo:\"},{\"heading\":false,\"text\":\"--Poco tiempo me tuvo allá abajo el mundo[121]: si yo hubiera permanecido más en él, no habrían sucedido muchos de los males que allí suceden. La alegría que despide en torno mío estos fulgores, me cubre como al gusano su capullo, y me oculta a tus ojos. Tú me has amado mucho, y tuviste motivo para ello; porque si yo hubiera estado allá abajo más tiempo, te habría dado en prueba de mi amor algo más que las hojas. Aquella ribera izquierda, que baña el Ródano después de haberse unido con el Sorgues, me esperaba, andando el tiempo, para recibirme por su señor; así como también aquella punta de la Ausonia que comprende los pueblos de Bari, Gaeta y Crotona, desde donde el Tronto y el Verde desembocan en el mar. Brillaba ya en mi frente la corona de aquella tierra que riega el Danubio después de abandonar las riberas tudescas; y la bella Trinacria, que entre los promontorios Pachino y Peloro, sobre el golfo que el Euro azota con más violencia, se cubre de humo caliginoso, no a causa de Tifeo, sino por el azufre que se exhala de su suelo, habría esperado aún sus reyes nacidos por mí de Carlos y de Rodolfo, si el mal gobierno que rebela siempre a los pueblos sumisos, no hubiese excitado a Palermo a gritar: \\\"¡Muera! ¡muera!\\\" Y si mi hermano hubiera previsto esto, huiría ya la avara pobreza de Cataluña para no ofender a aquellos pueblos. Necesita, en verdad, proveer por sí mismo o por otros, a fin de que su barca no tenga más carga de la que pueda soportar. Su índole, que de liberal se ha hecho avara, necesitaría ministros que no se cuidasen sólo de llenar sus arcas.\"},{\"heading\":false,\"text\":\"[121] Esta es el alma de Carlos Martel, muerto en 1295, hijo de Carlos II.\"},{\"heading\":false,\"text\":\"--El gran contento que me infunden tus palabras, ¡oh señor mío!, me es mucho más grato al considerar que aquí, donde está el principio y el fin de todo bien, lo ves como yo lo veo; y también gozo pensando que en presencia de Dios conoces mi felicidad. Ya que me has dado esta alegría, aclárame (pues hablando me has hecho dudar) cómo de una semilla dulce puede salir un fruto amargo.\"},{\"heading\":false,\"text\":\"Esto le dije, y él me contestó:\"},{\"heading\":false,\"text\":\"--Si puedo demostrarte una verdad, volverás el rostro a lo que preguntas, como ahora le vuelves la espalda. El Bien que da movimiento y alegría a todo el reino por donde asciendes, hace que su providencia sea virtud influyente de estos grandes cuerpos; y en la Mente perfecta por sí misma, no sólo se ha provisto a la naturaleza de cada cosa, sino también a la conservación y estabilidad de todas juntas: por lo cual, todo cuanto desciende disparando de este arco, va dispuesto hacia un fin determinado, como la flecha se dirige al blanco. Si esto no fuese así, el cielo sobre que caminas produciría sus efectos de tal modo, que no serían obras de arte, sino ruinas; y eso no puede ser, a no admitir que son defectuosas las inteligencias que mueven estos astros, y defectuoso también el Sér primero, que no las hizo perfectas. ¿Quieres que te aclare más esta verdad?\"},{\"heading\":false,\"text\":\"--No es menester--contesté--; pues considero imposible que la naturaleza llegue a faltar en aquello que es necesario.\"},{\"heading\":false,\"text\":\"El Alma continuó:\"},{\"heading\":false,\"text\":\"--Dime, pues: ¿sería peor la existencia del hombre en la Tierra, si no viviera en sociedad?\"},{\"heading\":false,\"text\":\"--Sí--repuse--; y no pregunto la razón de eso.\"},{\"heading\":false,\"text\":\"--¿Y puede ser tal cosa, si allá abajo no vive cada cual de diferente modo por la diversidad de oficios? No puede ser, si vuestro maestro escribió la verdad.\"},{\"heading\":false,\"text\":\"Así, procediendo de una en otra deducción, llegó a ésta; y después concluyó:\"},{\"heading\":false,\"text\":\"--Luego es preciso que sean diversas las raíces de vuestras aptitudes; por lo cual uno nace Solón y otro Jerjes, uno Melquisedec y otro aquel que perdió a su hijo, al volar éste por el aire.[122] La influencia de los círculos celestes, que imprime su sello a la cera mortal, hace bien su oficio; pero no distingue una morada de otra. De aquí proviene que Esaú se aparte de Jacob desde el vientre materno, y que Quirino descienda de un padre tan vil, que se atribuye su origen a Marte. La naturaleza engendrada sería siempre semejante a la naturaleza que engendra, si la Providencia divina no predominase. Ahora tienes ya delante lo que antes detrás; mas para que sepas que me complazco en instruirte, quiero proveerte aún de un corolario. La naturaleza es siempre estéril, si la fortuna le es contraria, como toda simiente esparcida fuera del clima que le conviene. Y si el mundo allá abajo se apoyara en los cimientos que pone la naturaleza, habría por cierto mejores habitantes en él; pero vosotros destináis para el templo al que nació para ceñir la espada, y hacéis rey al que debía ser predicador: así es que vuestros pasos se separan siempre del camino recto.\"},{\"heading\":false,\"text\":\"[122] Uno nace, como Solón, a propósito para dar leyes a los pueblos; otro, como Jerjes, para regir imperios; otro, como Melquisedec, para el sacerdocio, y otro, como Dédalo, para la industria.--Estas diferentes aptitudes con que nacen los hombres las infunden los influjos celestes, según el poeta, pero sin distinguir de clases ni de jerarquías.\"}]},{\"title\":\"Paraíso — canto nono\",\"blocks\":[{\"heading\":false,\"text\":\"Cuando tu Carlos, hermosa Clemencia, hubo aclarado mis dudas, me refirió los fraudes de que había de ser víctima su descendencia, pero añadió: \\\"Calla, y deja transcurrir los años.\\\" Así es que yo no puedo decir más, sino que tras de vuestros daños vendrá el llanto originado por un justo castigo.\"},{\"heading\":false,\"text\":\"La santa y viva luz se había vuelto ya hacia el Sol que la inunda, como hacia el bien que a todo alcanza. ¡Oh almas engañadas, locas e impías, que apartáis vuestros corazones de semejante bien, dirigiendo hacia la vanidad vuestros pensamientos! He aquí que otro de aquellos esplendores se dirigió hacia mí, expresando, con la claridad que esparcía, su deseo de complacerme. Los ojos de Beatriz, que estaban fijos en mí, como antes, me aseguraron del dulce asentimiento que daba a mi deseo.\"},{\"heading\":false,\"text\":\"--¡Oh espíritu bienaventurado!--dije--; satisface cuanto antes mi anhelo, y pruébame que lo que pienso puede reflejarse en ti.\"},{\"heading\":false,\"text\":\"Entonces la luz, a quien aún no conocía, desde su interior donde antes cantaba, respondió a mis palabras como quien se complace en ser cortés con otro:\"},{\"heading\":false,\"text\":\"--En aquella parte de la depravada tierra de Italia que está situada entre Rialto y las fuentes del Brenta y del Piava, se eleva una colina no muy alta, de donde descendió una llamarada que causó un gran desastre en toda la comarca. Ella y yo salimos de la misma raíz: Cunizza fué llamada; y aquí brillo, porque me venció la luz de esta estrella; pero con alegría me perdono a mí misma la causa de mi muerte, y no me pesa, lo cual quizá parecerá difícil de comprender a vuestro vulgo. Esta alma próxima a mí, que es una espléndida y preciosa joya de nuestro cielo, dejó en la Tierra una gran fama; y antes que su gloria se pierda, este centésimo año se quintuplicará. Ya ves si el hombre debe hacerse ilustre a fin de que su primera vida deje sobre la tierra una segunda. Esto es lo que no piensa la turba presente que habita entre el Tagliamento y el Adigio, sin que le sirvan de escarmiento los males de que es víctima. Pero pronto sucederá que Padua y sus habitantes, por ser obstinados contra el deber, enrojecerán el agua de la laguna que baña a Vicenza, y allí donde el Sile y el Cagnano se unen hay quien domina y va con la cabeza erguida,[123] cuando ya se componen las redes que han de cogerle. También llorará Feltro la felonía de su impío pastor, que será tal, que ninguno por otra semejante ha sido encerrado en Malta. Será necesario un recipiente muy ancho para recibir la sangre ferraresa, y cansado quedará el que quiera pesar onza a onza la que derramará tan cortés sacerdote por mostrarse hombre de partido, siendo por otra parte tales dones conformes a las costumbres de tal país. Allá arriba hay unos espejos, que vosotros llamáis Tronos, de donde se reflejan hasta nosotros los juicios de Dios; así es que tenemos por buenas y verídicas nuestras palabras.\"},{\"heading\":false,\"text\":\"[123] Ricardo de Cammino, que fué muerto por instigación de Altiniero del Calzoni.\"},{\"heading\":false,\"text\":\"Al llegar aquí, el alma guardó silencio, y habiéndose vuelto a colocar en la órbita como estaba anteriormente, me dió a conocer que no pensaba ya en mí. La otra alma dichosa, a quien ya conocía, se me presentó tan resplandeciente como una piedra preciosa herida por los rayos del Sol. Allá arriba la alegría produce un vivo esplendor, como entre nosotros produce la risa; pero en el Infierno la sombra de los condenados se obscurece cada vez más, a medida que se entristece su espíritu.\"},{\"heading\":false,\"text\":\"--Dios lo ve todo, y tu vista se identifica en El--exclamé--, ¡oh feliz espíritu!, de suerte que ningún deseo puede ocultarse a ti. Así, pues, ¿por qué tu voz, que deleita siempre al Cielo con el canto de aquellas llamas piadosas que se forman una ancha vestidura con sus seis alas, no satisface mis deseos? No esperaría yo por cierto tus preguntas, si viera en tu interior como tú ves en el mío.\"},{\"heading\":false,\"text\":\"Entonces contestó con estas palabras:\"},{\"heading\":false,\"text\":\"--El mayor valle en que se vierten las aguas, después de aquel mar que circunda la Tierra, se aleja tanto contra el curso del Sol entre las desacordes playas, que aquel círculo que antes era su horizonte se convierte en meridiano. Yo fuí uno de los ribereños de aquel valle, entre el Ebro y el Macra, que por un corto trecho separa el genovés del toscano. Casi a la misma distancia a Oriente y Occidente se asienta Bugia y la tierra de donde fuí, en cuyo puerto se vertió un día la sangre de sus habitantes.[124] Folco me llamó aquella gente, que conocía mi nombre, y este cielo recibe mi luz, como recibí yo su influjo amoroso; pues en tanto que me lo permitió la edad, no ardieron cual yo en aquel fuego la hija de Belo, causando enojos a Siqueo y a Creusa; ni aquella Rodopea que fué abandonada por Demofón, ni Alcides cuando tuvo a Iole encerrada en su pecho. Aquí empero no hay arrepentimiento, sino regocijo; no de las culpas, que jamás vuelven a la memoria, sino de la sabiduría que ordenó este cielo y provee sus influjos. Aquí se contempla el arte que adorna y embellece tantas cosas creadas, y se descubre el bien por el cual el mundo de arriba obra directamente sobre el de abajo. Mas a fin de que queden satisfechos todos los deseos que te han nacido en esta esfera, es preciso que lleve más adelante mis instrucciones. Tú quieres saber quién está en esa luz que centellea cerca de mí, como un rayo de Sol en el agua pura y cristalina. Sabe, pues, que en su interior es dichosa Rahab, y unida a nuestro coro, brilla en él con el esplendor más eminente. Ascendió a este cielo, en el que termina la sombra que proyecta vuestro mundo, antes que ninguna otra alma se viese libre por el triunfo de Cristo. Era justo dejarla en algún cielo como trofeo de la alta victoria que El alcanzó con ambas palmas; porque aquella mujer favoreció las primeras hazañas de Josué en la Tierra Santa, que tan poco excita la memoria del Papa. Tu ciudad, que debió su origen a aquel que fué el primero en volver las espaldas a su Hacedor y cuya envidia ocasionó tantas lágrimas, produce y esparce las malditas flores, que han descarriado a las ovejas y los corderos, porque han convertido en lobo al pastor. Por eso están abandonados el Evangelio y los grandes doctores, y tan sólo se estudian las Decretales, según lo indica lo usado de sus márgenes. A eso se dedican el Papa y los cardenales: sus pensamientos no llegan a Nazareth, allí donde Gabriel abrió las alas; pero el Vaticano y demás sitios elegidos de Roma, que han sido el cementerio de la milicia que siguió a Pedro, pronto se verán libres del adulterio.\"},{\"heading\":false,\"text\":\"[124] Se refiere al sitio de Marsella por Julio César.\"}]},{\"title\":\"Paraíso — canto decimo\",\"blocks\":[{\"heading\":false,\"text\":\"El inefable poder primero, juntamente con su hijo y con el amor que de uno y otro eternamente procede, hizo con tanto orden todo cuanto concibe la inteligencia y ven los ojos, que no es posible a nadie contemplarlo sin gustar de sus bellezas. Eleva, pues, lector, conmigo tus ojos hacia las altas esferas, por aquella parte en que un movimiento se encuentra con otro, y empieza a recrearte en la obra de aquel Maestro, que la ama tanto en su interior, que jamás separa de ella sus miradas. Observa cómo desde allí se desvía el círculo oblicuo, conductor de los planetas, para satisfacer al mundo que le llama. Y si el camino de aquéllos no fuese inclinado, más de una influencia en el cielo sería vana, y como muerta aquí abajo toda potencia. Y si al girar se alejaran más o menos de la línea recta, dejaría mucho que desear arriba y abajo el orden del mundo. Ahora, lector, permanece tranquilo en tu asiento, meditando acerca de estas cosas que aquí sólo se bosquejan, si quieres que te causen mayor deleite antes que tedio. Te he puesto delante el alimento; tómalo ya por ti mismo, porque el asunto de que escribo reclama para sí todos mis cuidados.\"},{\"heading\":false,\"text\":\"El mayor ministro de la naturaleza, que imprime en el mundo la virtud del Cielo y mide el tiempo con su luz, giraba, juntamente con aquella parte de que te he hablado antes, por las espirales en que cada día se nos presenta más temprano. Yo estaba en él, sin haber notado mi ascensión, sino como nota el hombre una idea después que se le ocurre. ¡Oh Beatriz! ¡Cuán esplendorosa no debía de estar por sí misma, ella que de tal modo me hacía pasar de bien a mejor tan súbitamente, que su acción no se sujetaba al transcurso del tiempo! Lo que por dentro era el Sol, donde yo entraba, y lo que aparecía, no por medio de colores, sino de luz, jamás pudiera imaginarse, aun cuando para explicarlo llamase en mi auxilio el ingenio, el arte y todos sus recursos; pero puede creérseme, y debe desearse verlo. Y si nuestra fantasía no alcanza a tanta altura, no es maravilla; pues nadie ha visto un resplandor que supere al del Sol. Como él era allí la cuarta familia[125] del Padre Supremo, que siempre sacia sus deseos, mostrándole cómo engendra al Hijo, y cómo procede el Espíritu. Y Beatriz exclamó:\"},{\"heading\":false,\"text\":\"--Da gracias, da gracias al Sol de los ángeles, que por su bondad te ha elevado a este Sol sensible.\"},{\"heading\":false,\"text\":\"[125] Brillantes como el Sol eran los bienaventurados que allí estaban. Los llama cuarta familia, porque se le aparecen en el cuarto cielo. Estos son las almas de los doctores de la Iglesia.\"},{\"heading\":false,\"text\":\"Jamás ha habido un corazón humano tan dispuesto a la devoción y a entregarse a Dios tan vivamente con todo su agradecimiento, como el mío al oír aquellas palabras; y puse en El de tal modo todo mi amor, que Beatriz se eclipsó en el olvido. No le desagradó; antes por el contrario, se sonrió; y el esplendor de sus ojos sonrientes dividió en muchos mi pensamiento absorto en uno solo. Vi muchos espíritus vivos y triunfantes, más gratos aún por su voz que relucientes a la vista, los cuales, tomándonos por centro, nos formaron una corona de sí mismos. No de otro modo vemos a veces a la hija de Latona rodeada de un cerco, cuando el aire, impregnado de vapores, retiene las substancias de que aquél se compone. En la corte del cielo, de donde vuelvo, se encuentran muchas joyas, tan raras y bellas, que no es posible hallarlas fuera de aquel reino; y una de estas joyas era el encanto de aquellos fulgores: el que no se provea de alas para volar hasta allí, espere tener noticias de aquel canto como si las preguntase a un mudo.\"},{\"heading\":false,\"text\":\"Después que, cantando de esta suerte, aquellos ardientes soles dieron tres vueltas en derredor nuestro, como las estrellas próximas a los fijos polos, me parecieron semejantes a las mujeres, que, sin dejar el baile, se detienen escuchando con atención, hasta que han conocido cuáles son las nuevas notas. Y oí que del interior de una de aquellas luces salían estas palabras:\"},{\"heading\":false,\"text\":\"--Ya que el rayo de la gracia, en que se enciende el verdadero amor, y que después crece amando, resplandece en ti tan multiplicado, que te conduce hacia arriba por aquella escala de donde nadie desciende sin volver a subir de nuevo, el que negase a tu sed el vino de su redoma se vería en el mismo estado de violencia en que está el agua impedida de correr hasta el mar. Tú quieres saber de qué flores se compone esta guirnalda, que acaricia en torno a la hermosa Dama que te da ánimo para subir al cielo. Yo fuí uno de los corderos del santo rebaño que condujo Domingo por el camino en que el alma se fortifica si no se extravía. Este, que está el más próximo a mi derecha, fué mi maestro y mi hermano; es Alberto de Colonia, y yo Tomás de Aquino. Si quieres saber quiénes son los demás, sigue mis palabras con tus miradas, dando la vuelta a la bienaventurada corona. Aquel otro esplendor brota de la sonrisa de Graciano, tan útil por sus escritos a uno y otro fuero, que mereció el Paraíso. El otro que le sigue fué Pedro,[126] que, como la pobre viuda, ofreció su tesoro a la Santa Iglesia. La quinta luz,[127] que es la más bella entre nosotros, se abrasa en tal amor, que todo el mundo tiene abajo sed de sus noticias. Dentro de ella está el alto espíritu, donde se albergó tan profunda sabiduría, que si la verdad es verdad, ninguno otro ascendió a tanto saber. Después contempla la luz de aquel cirio, que ha sido el que en vida vió mejor la naturaleza y el ministerio de los ángeles.[128] En aquella diminuta luz sonríe el abogado de los tiempos cristianos, cuya doctrina aprovechó Agustín.[129] Si diriges ahora la mirada de tu entendimiento de luz en luz, siguiendo mis elogios, debes ya tener sed de conocer la octava. Dentro de ella se recrea en la vista del soberano Bien el alma santa que pone de manifiesto las falacias del mundo a quien atentamente escucha sus doctrinas. El cuerpo de donde fué separada yace en Cieldauro,[130] y desde el martirio y el destierro ha venido a disfrutar de esta paz celestial. Ve más allá fulgurar el ardiente espíritu de Isidoro, el de Beda y el de Ricardo,[131] que en sus contemplaciones fué más que hombre. Esa, de quien se separa tu mirada para fijarse en mí, es la luz de un espíritu que, considerando tranquilamente la vanidad del mundo, deseó morir. Es la luz eterna de Sigieri,[132] que ejerciendo el profesorado en la calle de la Paja, excitó la envidia por sus verdaderos silogismos.\"},{\"heading\":false,\"text\":\"[126] Pedro Lombardo, llamado el =Maestro de las sentencias=. En el proemio de su obra dice modestamente que con ella hacía un pequeño dón a la Iglesia, como la viuda de que habla San Lucas, cap. XXI.\"},{\"heading\":false,\"text\":\"[127] El rey Salomón.\"},{\"heading\":false,\"text\":\"[128] San Dionisio Areopagita, autor de un libro titulado: =De coelesti hierarchia=.\"},{\"heading\":false,\"text\":\"[129] Paulo Orosio, que escribió contra los idólatras siete libros de historia, y los dedicó a San Agustín.\"},{\"heading\":false,\"text\":\"[130] Boecio, a quien hizo morir Teodorico, rey de los godos, y que está sepultado en la iglesia de San Pedro llamada Cielo de oro, en Pavía.\"},{\"heading\":false,\"text\":\"[131] Canónigo regular de San Víctor, escocés.\"},{\"heading\":false,\"text\":\"[132] Seguier, profesor de Filosofía y Ciencias, que enseñaba en la rue du Fouarre, de París, donde estaban las escuelas.\"},{\"heading\":false,\"text\":\"En seguida, como el reloj que nos llama a la hora en que la Esposa de Dios principia a cantar maitines a su Esposo, a fin de que la ame, y cuyas ruedas mueven unas a otras, y apresuran a la que va delante hasta que ese oye \\\"tin tin\\\" con notas tan dulces, que el espíritu felizmente dispuesto se inflama de amor; así vi yo en la gloriosa esfera moverse y responder las voces a las voces con una armonía tan llena de dulzura, que sólo puede conocerse allá donde la dicha se eterniza.\"}]},{\"title\":\"Paraíso — canto undecimo\",\"blocks\":[{\"heading\":false,\"text\":\"¡Oh insensatos afanes de los mortales!, ¡cuán débiles son las razones que os inducen a bajar el vuelo y a rozar la Tierra con vuestras alas! Mientras unos se dedicaban al foro, y otros se entregaban a los aforismos de la medicina; y éstos seguían el sacerdocio, y aquéllos se esforzaban en reinar por la fuerza de las armas, haciendo creer en su derecho por medio de sofismas; y algunos rodaban, y otros se consagraban a los negocios civiles; y muchos se enervaban en los placeres de la carne, y bastantes por fin se daban a la ociosidad, yo, libre de todas estas cosas, había subido con Beatriz hasta el cielo, donde tan gloriosamente fuí acogido. Después que cada uno de aquellos espíritus hubo vuelto al punto del círculo en que antes estaba, tan inmóvil como la bujía de un candelero, la luz[133] que me había hablado anteriormente se hizo más esplendorosa y risueña, y dentro de ella oí una voz que comenzó a decir de esta manera:\"},{\"heading\":false,\"text\":\"[133] Santo Tomás de Aquino.\"},{\"heading\":false,\"text\":\"--Así como yo me enciendo a los rayos de la luz eterna, del mismo modo, mirándola, conozco la causa de donde proceden tus pensamientos. Tú dudas, y quieres que mi boca emplee palabras tan claras y ostensibles, que pongan al alcance de tu inteligencia las que pronuncié antes cuando dije: \\\"Camino en que el alma se fortifica;\\\" y las otras: \\\"Ningún otro ascendió.\\\" En cuanto a éstas, es preciso hacer una distinción. La Providencia, que gobierna al mundo con el consejo en que se abisma la mirada de todo sér creado antes de penetrar en el fondo, a fin de que la Esposa de Aquél, que con su bendita sangre se unió a ella en altas voces, corriese hacia su amado segura de sí misma y siéndole más fiel, envió en su ayuda dos príncipes, que para entrambos objetos le sirvieran de guías. El uno fué todo seráfico en su ardor; el otro, por su sabiduría, resplandeció en la Tierra con la luz de los querubines.[134] Hablaré de uno solo; pues elogiando a cualquiera de ellos indistintamente, se habla de los dos, porque sus obras tendieron a un mismo fin. Entre el Tupino y el agua que desciende del collado elegido por el beato Ubaldo, baja un fértil declive de un alto monte, del cual Perusa siente venir el calor y el frío por la parte de Porta Sole, y tras de cuyo monte lloran oprimidas Nocera y Gualdo. En el sitio donde aquella pendiente es menos rápida, vino al mundo un Sol, resplandeciendo como éste a veces cuando asoma sobre las márgenes del Ganges. Quien hable de ese lugar, no le llame Asís, pues diría muy poco: si quiere hablar con propiedad, llámele Oriente. Aun no distaba mucho de su nacimiento, cuando aquel Sol comenzó a hacer que la Tierra sintiese algún consuelo con su gran virtud; pues siendo todavía muy joven, incurrió en la cólera de su padre por inclinarse a una dama,[135] a quien, como a la muerte, nadie acoge con gusto; y ante la corte espiritual \\\"et coram patre\\\" se unió a ella, amándola después más y más cada día. Ella, privada de su primer marido,[136] permaneció despreciada y obscura mil cien años y más, sin que nadie lo solicitase hasta que vino éste. De nada le valió que se oyera decir cómo aquel que hizo temer a todo el mundo la encontró alegre con Amiclates, cuando llamó a su puerta: ni le valió haber sido constante y animosa hasta el punto de ser crucificada con Cristo, mientras María estaba al pie de la Cruz. Mas, para no continuar en un estilo demasiado obscuro, reconoce en mis difusas palabras que estos dos amantes son Francisco y la Pobreza. Su concordia y sus placenteros semblantes, su amor maravilloso y sus dulces miradas inspiraban santos pensamientos a otros; de tal modo que el venerable Bernardo fué el primero que se descalzó para correr en pos de tanta paz, y aun corriendo le parecía llegar tarde. ¡Oh riqueza ignorada! ¡Oh verdadero bien! Egidio se descalza, se descalza también Silvestre por seguir al Esposo; tanto es lo que les agrada la Esposa. Desde allí partió aquel padre y maestro con su mujer y con aquella familia, ceñida ya del humilde cordón; y sin que una vil cobardía le hiciese bajar la frente por ser hijo de Pedro Bernardone, ni por su apariencia asombrosamente despreciable, manifestó con gran dignidad sus rígidas intenciones a Inocencio, de quien recibió la primera aprobación de su orden. Luego que fué aumentado en torno suyo la pobre gente, cuya admirable vida se cantaría mejor entre las glorias del Cielo, el Eterno Espíritu, valiéndose de Honorio, coronó de nuevo el santo propósito de aquel archimandrita; y cuando éste, sediento del martirio, predicó en presencia del soberbio Soldán la doctrina de Cristo y de los que le siguieron, encontrando aquella gente poco dispuesta a la conversión, para no permanecer inactivo, volvió a recoger el fruto de las plantas de Italia. Sobre un áspero monte, entre el Tíber y el Arno, recibió de Cristo el último sello, que sus miembros llevaron durante dos años. Cuando plugo a Aquél que le había elegido para tan gran tarea elevarle a la recompensa que mereció por haberse humillado, recomendó a sus hermanos, como a herederos legítimos, el cuidado de su más querida Esposa, y que la amaran con fe: y en el seno de ella quiso el alma preclara desprenderse para volver a su reino, sin permitir que a su cuerpo se le diese otra sepultura. Piensa ahora cuál fué el digno colega de Francisco, encargado de mantener la barca de Pedro en alta mar y dirigirla hacia su objeto: ese fué, pues, nuestro patriarca; por lo cual, el que le sigue, según él manda, puede decir que adquiere buena mercancía. Pero su rebaño se ha vuelto tan codicioso de nuevo alimento, que no puede menos de esparcirse por distintos prados; y cuanto más lejos de él van sus vagabundas ovejas, más exhaustas de leche vuelven al redil. Algunas de ellas, temiendo el peligro, se agrupan junto al pastor; pero son tan pocas, que no se necesita mucho paño para sus capas. Así pues, si mis palabras no son obscuras, si me has escuchado con atención, y si tu mente recuerda lo que te he dicho, tu deseo debe estar en parte satisfecho; porque habrás visto la causa de que la planta se desgaje, y comprenderás la distinción que hice al decir: \\\"Donde el alma se fortifica, si no se extravía.\\\"\"},{\"heading\":false,\"text\":\"[134] Los dos grandes jefes que debían guiar a la Iglesia, el uno hacia la caridad por el espíritu de pobreza, el otro a la mayor fidelidad por medio de la predicación, son, respectivamente, San Francisco de Asís, modelo de amor seráfico, y Santo Domingo, dotado de esplendor querúbico por su sabiduría.\"},{\"heading\":false,\"text\":\"[135] La Pobreza.\"},{\"heading\":false,\"text\":\"[136] Jesucristo.\"}]},{\"title\":\"Paraíso — canto duodecimo\",\"blocks\":[{\"heading\":false,\"text\":\"En cuanto la bendita llama hubo dicho su última palabra, empezó a girar la santa rueda, y aún no había dado una vuelta entera, cuando otra la encerró en un círculo, uniendo movimiento a movimiento y canto a canto: y eran éstos tales que, articulados por los dulces órganos de aquellos espíritus, sobrepujaban a los de nuestras Musas y nuestras Sirenas, tanto como la luz directa supera a sus reflejos. Cual se ve a dos arcos paralelos y del mismo color encorvarse sobre una ligera nube, cuando Juno envía a su mensajera (naciendo el de fuera del de dentro, al modo de la voz de aquella ninfa[137] que consumió el amor, como el Sol consume los vapores), y cuyos arcos son un presagio para los hombres, a causa del pacto que Dios hizo con Noé, de que el mundo no volverá a sufrir otro diluvio, de igual suerte aquellas dos guirnaldas de sempiternas rosas daban vueltas en torno de nosotros, correspondiendo en todo la guirnalda exterior a la interior. Cuando cesaron simultánea y unánimemente las danzas y los fulgurantes y mutuos destellos de aquellas luces gozosas y placenteras, semejantes a los ojos que se abren y se cierran al mismo tiempo, dóciles a la voluntad del que los mueve, del seno de una de las nuevas luces salió una voz,[138] la cual hizo que me volviese hacia donde estaba, como la aguja hacia el polo: aquella voz empezó a decir:\"},{\"heading\":false,\"text\":\"[137] La ninfa Eco, que enamorada de Narciso, se consumió, quedando únicamente su voz. Entiéndase: naciendo el arco exterior de la reflexión de los rayos del arco menor concéntrico, lo mismo que el eco nace de la reflexión de la voz.\"},{\"heading\":false,\"text\":\"[138] San Buenaventura.\"},{\"heading\":false,\"text\":\"--El amor que me embellece me obliga a tratar del otro jefe por quien se habla tan bien del mío.[139] Es justo que donde se hace mención del uno, se haga también del otro; pues habiendo militado ambos por una misma causa, debe brillar su gloria juntamente. El ejército de Cristo, al que tan caro costó armar de nuevo, seguía su enseña lento, receloso y escaso, cuando el Emperador que siempre reina acudió en ayuda de su milicia, que se hallaba en peligro, no porque ésta fuera digna de ello, sino por un efecto de su gracia; y según se ha dicho, socorrió a su Esposa con dos campeones, ante cuyas obras y palabras se reunió el descarriado pueblo. En aquella parte donde el dulce céfiro acude a hacer germinar las nuevas plantas de que se reviste Europa,[140] no muy lejos de los embates de las olas, tras de las cuales, por su larga extensión, el Sol se oculta a veces a todos los hombres, se asienta la afortunada Calahorra, bajo la protección del grande escudo, en que el león está subyugado y subyuga a su vez. En ella nació el apasionado amante de la fe cristiana, el santo atleta, benigno para los suyos, y cruel para sus enemigos. Apenas fué creada, su alma se llenó de virtud tan viva, que en el seno mismo de su madre inspiró a ésta el dón de profecía. Cuando se celebraron los esponsales entre él y la fe en la sagrada pila, donde se dotaron de mutua salud, la mujer que dió por él su asentimiento vió en sueños el admirable fruto que debía salir de él y de sus herederos; y para que fuese más visible lo que ya era, descendió del cielo un espíritu, y le dió el nombre de Aquél que le poseía por completo. Domingo se llamó; y habló de él como del labrador que Cristo escogió para que le ayudase a cultivar su huerto. Pareció en efecto enviado y familiar de Cristo; porque el primer deseo que se manifestó en él fué el de seguir el primer consejo de Cristo. Muchas veces su nodriza lo encontró despierto y arrodillado en el suelo, como diciendo: \\\"He venido para esto.\\\" ¡Oh padre verdaderamente Feliz!, ¡oh madre verdaderamente Juana!, si la interpretación de sus nombres es la que se les da. En poco tiempo llegó a ser un gran doctor, no por esa vanidad mundana por la que se afanan hoy todos tras del Ostiense y de Tadeo, sino por amor hacia el verdadero maná; entonces se puso a custodiar la viña que pierde en breve su verdura, si el viñador es malo; y habiendo acudido a la Sede, que en otro tiempo fué más benigna de lo que es ahora para los pobres justos, no por culpa suya, sino del que en ella se sienta y la mancilla, no pidió la facultad de dispensar dos o tres por seis; no pidió el primer beneficio vacante; \\\"non decimas, quæ sunt pauperum Dei;\\\" sino que pidió licencia para combatir los errores del mundo, y en defensa de la semilla de que nacieron las veinticuatro plantas que te rodean. Después, con su doctrina y su voluntad juntamente, corrió a desempeñar su misión apostólica, cual torrente que se desprende de un elevado origen; y su ímpetu atacó con más vigor los retoños de la herejía allí donde era mayor la resistencia. De él salieron en breve varios arroyos, con los que se regó el jardín católico, de modo que sus arbustos adquirieron más vida. Si tal fué una de las ruedas del carro en que se defendió la Santa Iglesia, venciendo en el campo las discordias civiles, bastante debes conocer ya la excelencia de la otra rueda de que te ha hablado Tomás con tantos elogios antes de mi llegada. Pero el carril trazado por la parte superior de la circunferencia de esta última rueda está abandonado, de suerte que ahora se halla el mal donde antes el bien. La familia que seguía fielmente las huellas de Francisco ha cambiado tanto su marcha, que pone la punta del pie donde él ponía los talones: pero pronto verá la cosecha que ha producido tan mal cultivo, cuando la cizaña se queje de que no se la lleve al granero. Convengo en que quien examinase hoja por hoja nuestro libro aún encontraría una página en que leería: \\\"Yo soy el que acostumbro;\\\" pero no procederá de Casale ni Acquasparta, de donde vienen algunos que, o huyen el rigor de la regla, o aumentan desmesuradamente su austeridad. Yo soy el alma de Buenaventura de Bagnoregio, que en mis grandes cargos pospuse siempre los cuidados temporales a los espirituales. Iluminato y Agustín están aquí: éstos fueron de los primeros pobres descalzos que, llevando el cordón, se hicieron amigos de Dios. Con ellos están Hugo de San Víctor, y Pedro Mangiadore, y Pedro Hispano, el cual brilló allá abajo por sus doce libros; el profeta Natán, y el metropolitano Crisóstomo, y Anselmo, y aquel Donato que se dignó poner su mano en la primera de las artes.[141] Aquí está también Rabano, y a mi lado brilla Joaquín, abad de Calabria, que estuvo dotado de espíritu profético. He debido alabar a aquel gran paladín de la Iglesia, por moverme a ello la ardiente simpatía y las discretas palabras de fray Tomás, que, así como a mí, han conmovido a todas estas almas.\"},{\"heading\":false,\"text\":\"[139] Me obliga a ocuparme en Santo Domingo, por quien Santo Tomás habló tan bien de mi jefe San Francisco.\"},{\"heading\":false,\"text\":\"[140] En España.\"},{\"heading\":false,\"text\":\"[141] La Gramática.\"}]},{\"title\":\"Paraíso — canto decimotercio\",\"blocks\":[{\"heading\":false,\"text\":\"Quien deseare conocer bien lo que yo vi ahora, imagínese (y, mientras hablo, retenga la imagen como si fuese esculpida en fuerte roca) las quince estrellas, que en diversas regiones iluminan el cielo con tanta viveza, que vencen toda la densidad del aire: imagínese aquel Carro, al cual le basta el espacio de nuestro cielo para girar de noche y día, sin desaparecer nunca de aquella bocina, que comienza en la punta del eje en torno del cual se mueve la primera esfera; y piense que estas estrellas forman juntas en el cielo dos signos semejantes al que formó la hija de Minos cuando sintió el frío de la muerte:[142] figúrese uno de ellos despidiendo sus resplandores dentro del otro, y ambos a dos girando de manera que vayan en sentido inverso; y así tendrá como una sombra de la verdadera constelación y de la doble danza que circulaba en el sitio donde yo me encontraba; pues lo que vi es tan superior a lo que acostumbramos a ver, como el lento curso del Chiana es inferior al movimiento del más alto y veloz de los cielos. Allí se cantaba, no a Baco ni Peán, sino a tres Personas en una Naturaleza Divina, y ésta y la humana en una sola Persona. Tan luego como en las danzas y los cantos invirtieron el debido tiempo, aquellas santas luces se fijaron en nosotros, felicitándose de pasar de uno a otro cuidado. Después rompió el silencio de los espíritus acordes la luz que me había referido la admirable vida del Pobre de Dios, y dijo:\"},{\"heading\":false,\"text\":\"[142] Imagine que estas veinticuatro estrellas formen en el cielo dos constelaciones dispuestas en círculo, como aquella corona en que al morir Ariadna, hija de Minos, hizo que se convirtiera la guirnalda de flores que adornaba su cabeza.\"},{\"heading\":false,\"text\":\"--Estando ya trillada una parte del trigo y guardado el grano, el dulce amor que te profeso me invita a trillar la otra parte. Tú crees que en el pecho de donde fué sacada la costilla para formar la hermosa boca cuyo paladar costó caro a todo el mundo, y en aquel otro que, atravesado de una lanzada, satisfizo tanto, que venció el peso de toda culpa cometida antes y después, el gran poder creador de uno y otro infundió cuanta ciencia es asequible a la naturaleza humana: por esto te admiras de lo que dije antes, al manifestar que el bienaventurado que está contenido en la quinta luz[143] fué sin segundo. Abre, pues, los ojos de la inteligencia a lo que voy a exponerte, y verás cómo tu creencia y mis palabras son con respecto a la verdad como el centro es respecto de todos los puntos del círculo. Lo que no muere, y lo que puede morir, no es más que un destello de la idea que nuestro Señor engendra por efecto de su bondad; porque aquella viva luz que sale del radiante Padre, y no se separa de él ni del Amor que se interpone entre ambos, por un efecto de su bondad, comunica su irradiación a nueve cielos, como transmitida de espejo en espejo, pero permaneciendo una eternamente. De allí desciende hasta las últimas potencias, disminuyendo de tal modo su fuerza por grados, que últimamente sólo produce breves contingencias. Por estas contingencias entiendo las cosas engendradas, que el Cielo en su movimiento produce con germen o sin él. La materia de éstas, y la mano que le da forma, no causan siempre los mismos efectos; por lo cual dichas cosas, que llevan el sello de la idea divina, aparecen más o menos perfectas. De aquí se sigue que una misma especie de árboles dé frutos buenos o malos, y que vosotros nazcáis con diferente ingenio. Si la materia fuese enteramente perfecta, y el Cielo estuviese también en su virtud suprema, la luz de la idea divina se mostraría en todo su esplendor. Pero la naturaleza da siempre una forma imperfecta, semejante en sus obras al artista que domina prácticamente su arte, y cuya mano tiembla. Si, pues, el ferviente amor dispone la materia, e imprime en ella la clara luz del ideal divino, entonces las cosas contingentes alcanzan la perfección. Así es como fué hecha la tierra digna de toda perfección animal, y así es cómo concibió la Virgen. Por lo tanto, apruebo tu opinión, porque la humana naturaleza no fué ni será jamás lo que ha sido en esas dos personas. Pero si yo no siguiese ahora adelante, empezarías por exclamar: \\\"¿Cómo es, pues, que aquél no tuvo igual?\\\" Para que aparezca bien lo que ahora no aparece, piensa quién era, y la razón que tuvo para pedir cuando se le dijo: \\\"Pide.\\\" No he hablado de modo que no hayas podido comprender que aquél fué un rey, que pidió la sabiduría, a fin de ser un verdadero rey, y no por saber cuál es el número de los motores celestiales; o si lo necesario con lo contingente produce lo necesario; o bien \\\"si est dare primum motum esse,\\\" ni si en un semicírculo puede colocarse un triángulo que no tenga un ángulo recto: así pues, si has comprendido bien lo que he dicho y lo que digo, conocerás que la sabiduría real era la ciencia sin par en que se clavaba la flecha de mi intención. Si claramente miras, verás que la palabra \\\"Ascendió\\\" sólo hacía referencia a los reyes, que son muchos, pero pocos los buenos. Acoge mis palabras con esta distinción; y así podrás conservar tu creencia sobre el primer padre y nuestro Amado. Esto debe hacerte andar siempre con pies de plomo, para que, cual hombre cansado, los muevas lentamente hacia el sí y el no que no distingues con claridad; pues necio es entre los necios el que sin distinción afirma o niega, ya en uno, ya en otro caso; porque acontece a menudo que una opinión precipitada se extravía, y después el amor propio ofusca nuestro entendimiento. El que va en busca de la verdad, sin conocer el arte de encontrarla, hace el viaje peor que en vano, porque no vuelve tal como fué; de lo cual son en el mundo pruebas ostensibles Parménides, Meliso, Briso y otros muchos que marchaban y no sabían adónde. Así hicieron Sabelio y Arrio, y aquellos necios que fueron como espadas para las Escrituras, torciendo el recto sentido de sus palabras. Los hombres no deben aventurarse a juzgar, como hace el que aprecia las mieses en el campo sin estar granadas; porque he visto primero el zarzal áspero y punzante durante todo el invierno, y luego cubrirse de rosas en su cima; y he visto a la nave surcar el mar recta y veloz durante su viaje, y perecer a la entrada del puerto. No crean doña Berta y seor Martino,[144] por haber visto a uno robando, y a otro haciendo ofrendas, verlos del mismo modo en la mente de Dios, porque aquél puede elevarse y éste caer.\"},{\"heading\":false,\"text\":\"[143] El rey Salomón.\"},{\"heading\":false,\"text\":\"[144] Nombres usados antiguamente para significar gentes de poco cacúmen.\"}]},{\"title\":\"Paraíso — canto decimocuarto\",\"blocks\":[{\"heading\":false,\"text\":\"El agua contenida en un vaso redondo se mueve del centro a la circunferencia o de ésta al centro, según que la agiten por dentro o por fuera. Ocurrióseme de pronto esto que digo en cuanto calló el alma gloriosa de Santo Tomás, por la semejanza que nacía de sus palabras y de las de Beatriz, a quien plugo decir, después de aquél:\"},{\"heading\":false,\"text\":\"--Este necesita, aunque no os lo indique ni con la voz ni con el pensamiento, llegar a la raíz de otra verdad. Decidle si la luz con que se adorna vuestra substancia permanecerá con vosotros eternamente tal como es ahora; y si así es, decidle cómo podrá suceder que no os ofenda la vista cuando os rehagáis visiblemente.\"},{\"heading\":false,\"text\":\"Así como en un arranque de alegría los que dan vueltas danzando elevan la voz y manifiestan en sus gestos su regocijo, del mismo modo, ante aquel ruego piadoso y expresivo, los santos círculos demostraron nuevo gozo en su danza y en su admirable canto. El que se lamenta de que haya de morir aquí abajo para vivir después en el cielo, no ha visto el placer que la lluvia eterna de la sacrosanta luz produce en los bienaventurados. Aquel uno y dos y tres que vive siempre, y siempre reina en tres y dos y uno, no circunscrito y circunscribiéndolo todo, era cantado tres veces por cada uno de aquellos espíritus con tal melodía, que oírlos sería justa recompensa para todo mérito. Yo oí en la luz más resplandeciente del menor círculo una voz modesta,[145] quizá como la del Angel al dirigirse a María que respondió:\"},{\"heading\":false,\"text\":\"[145] La voz de Salomón, modesta como lo es la verdadera sabiduría.\"},{\"heading\":false,\"text\":\"--Mientras dure la fiesta del Paraíso, otro tanto tiempo irradiará nuestro amor en torno de nuestra vestidura. Su claridad corresponde al ardor que nos inflama; el ardor, a nuestras celestiales visiones; y éstas son tanto más claras, cuanto mayor es la gracia que cada uno tiene según su valor. Cuando nos revistamos de la carne gloriosa y santa, nuestra persona será mucho más grata a Dios y a nosotros, porque estará completa: entonces se aumentará lo que de su gratuita luz nos da el Sumo Bien, luz que nos permite contemplarle; y entonces deberá aumentarse también nuestra santa visión, el ardor que ésta produce y el rayo que del ardor desciende; pero así como el carbón que origina la llama la sobrepuja en deslumbrante blancura, de tal modo que aparece en medio de ella, de igual suerte este fulgor que ya nos rodea, será vencido en apariencia por la carne, que todavía está cubierta por la tierra; y un esplendor tan grande no podrá ofendernos, porque los órganos del cuerpo serán bastante fuertes para todo lo que pueda deleitarnos.\"},{\"heading\":false,\"text\":\"Uno y otro coro me parecieron tan prontos y unánimes en decir \\\"Amén,\\\" que manifestaron bien claramente el deseo de revestir sus cuerpos mortales; no por ellos quizá, sino por sus madres, por sus padres, y por los demás seres que les fueron queridos antes de convertirse en sempiternas llamas. Y he aquí que en derredor de tales claridades nació una nueva luz sobre la que allí había, semejante a un horizonte luminoso; y así como al anochecer empiezan a entreverse en el Cielo nuevas apariciones, que parecen ser y no ser, así me pareció empezar a ver allí nuevas substancias. ¡Oh verdadero centelleo del Espíritu Santo! ¡Cuán brillante se presentó de improviso a mis ojos que, vencidos, no pudieron soportarlo! Pero se me mostró Beatriz tan bella y sonriente, que a su aspecto hubo de quedar esta visión entre las demás que no he podido retener en la memoria: entonces mis ojos recobraron fuerzas para alzarse de nuevo, y me vi transportado a mayor gloria sólo con mi Dama. Por el ígneo fulgor de la estrella, que me parecía más rojo que de costumbre, eché de ver que había subido a un punto más elevado; y con el lenguaje que es común a todos, de todo corazón ofrecí a Dios el holocausto debido por esta nueva gracia. No se había extinguido aún en mi pecho el ardor del sacrificio, cuando conocí que éste había sido felizmente bien aceptado; pues se me aparecieron unos resplandores tan deslumbrantes y rojos dentro de dos rayos luminosos, que exclamé: \\\"¡Oh Helios, cuánto los embelleces!\\\"\"},{\"heading\":false,\"text\":\"Salpicados de grandes y pequeños luminares, lo mismo de Galaxia, cuya blancura extendida entre los polos del mundo hace dudar a los más sabios, aquellos rayos formaban en el fondo de Marte el venerable signo que produce la intersección de los cuadrantes en un círculo. Aquí el ingenio es inferior a mi memoria; en aquella cruz resplandecía Cristo de suerte, que no puedo encontrar una comparación digna; pero el que toma su cruz y sigue a Cristo me perdonará una vez más lo que omito, cuando vea centellear a Cristo en aquel albor. De uno a otro extremo de los brazos de la cruz y de arriba abajo se agitaban luces, que lanzaban vívidos destellos cada vez que se unían o pasaban más allá, tal como se ven en la Tierra los átomos agitándose en línea recta o curva, ágiles o lentos, cambiando sin cesar de aspecto, en el rayo de luz que corta la sombra que el hombre, por medio de su inteligencia y de su arte, se procura contra el Sol; y así como el laúd o el arpa forman con sus numerosas cuerdas una dulce armonía, aun para el que no distingue cada nota, del mismo modo aquellas luces que allí se me aparecieron produjeron alrededor de la cruz una melodía, que me arrebataba a pesar de no comprender el himno. Bien conocí que encerraba altas alabanzas, porque llegaron hasta mí estas palabras: \\\"Resucita y vence,\\\" pero como el que oye sin entender. Y aquella melodía me arrobaba tanto, que hasta entonces no hubo cosa alguna que me ligara con tan dulces vínculos. Quizá parezcan demasiado atrevidas mis palabras, creyendo que pospongo a otras delicias el placer de los bellos ojos, en cuya contemplación se calman todos mis deseos; pero quien sepa que las vivas marcas de toda belleza la imprimen mayor a medida que están más elevadas, y considere que allí no me había vuelto aun hacia ellos, podrá excusarme de lo que me acuso para excusarme, y conocerá que digo la verdad; pues el santo placer de aquella mirada no está excluído aquí, supuesto que se hace más puro a medida que nos elevamos.\"}]},{\"title\":\"Paraíso — canto decimoquinto\",\"blocks\":[{\"heading\":false,\"text\":\"La benigna voluntad, en la que se manifiesta siempre el amor cuyas aspiraciones son rectas, como la codicia se manifiesta en la voluntad inicua, impuso silencio a aquella dulce armonía e hizo reposar las santas cuerdas que por la diestra de Dios están templadas. ¿Cómo se habían de hacer sordas a súplicas justas aquellas substancias, que, para infundirme el deseo de dirigirles alguna pregunta, estuvieron acordes en callarse? Justo es que se lamente sin tregua el que, por amor a cosas que no pueden durar eternamente, se desprende de aquel amor. Como en noche serena discurre acá o allá por el cielo tranquilo y puro un repentino fuego, atrayendo las miradas hasta entonces indiferentes, y parecido a una estrella que cambia de sitio, sólo que ninguna desaparece de la parte donde aquél se enciende y dura poco, así desde el extremo del brazo derecho al pie de la cruz se corrió un astro de la constelación que aquí resplandece;[146] pero el diamante no se separó de su ángulo, sino que siguió la faja luminosa, asemejándose a una luz que pasa por detrás del alabastro. No menos afectuosa que aquel espíritu se mostró la sombra de Anquises cuando reconoció a su hijo en los Campos Elíseos, si hemos de dar crédito a nuestro mayor Poeta.\"},{\"heading\":false,\"text\":\"[146] El alma de Caociaguida, tatarabuelo del Poeta.\"},{\"heading\":false,\"text\":\"--¡Oh sangre mía!, ¡oh superabundante gracia de Dios! ¿Quién, como tú, ha visto abiertas dos veces ante sí las puertas del Cielo?\"},{\"heading\":false,\"text\":\"Así dijo aquella luz; por lo cual fijé en ella toda mi atención: después volví el rostro hacia mi Dama, y por una y otra parte quedé asombrado; pues en sus ojos brillaba tal sonrisa, que creí llegar con los míos al fondo de mi gracia y de mi Paraíso. Luego aquel espíritu, al que era tan grato ver y oír, añadió a sus primeras palabras cosas que no comprendí; tan profundos fueron sus conceptos: no porque fuese su intento el ocultármelos, sino por necesidad a causa de ser éstos superiores a la inteligencia de los mortales. Cuando el arco de su ardiente afecto estuvo menos tirante para que sus palabras descendiesen hasta el límite concedido a nuestra inteligencia, la primera cosa que oí fué:\"},{\"heading\":false,\"text\":\"--Bendito seas Tú, trino y uno, que tan propicio eres a mi descendencia.\"},{\"heading\":false,\"text\":\"Y continuó diciendo:\"},{\"heading\":false,\"text\":\"--Hijo mío: gracias a ésa que te ha revestido de plumas para emprender tan alto vuelo, has satisfecho dentro de esta luz en que te hablo un plácido y largo deseo de verte, originado en mí de haber leído tu venida en el gran libro donde no se cambia jamás lo blanco en negro, ni lo negro en blanco. Tú crees que tu pensamiento ha llegado hasta mí por medio de aquel que es el primero, así como de la unidad, de todos conocida, se forman el cinco y el seis; y por eso ni me preguntas quién soy, ni por qué te parezco más gozoso que otro alguno de esta alegre cohorte. Crees la verdad; porque, en esta vida, los espíritus que disfrutan, así de mayor como de menor gloria, miran en el espejo en que aparece el pensamiento antes de nacer. Pero a fin de que el sagrado amor que observo con perpetua atención, y que excita en mí un dulce deseo, se satisfaga mejor, manifiesta con voz segura, franca y placentera, cuál es tu voluntad, cuál tu deseo, pues mi respuesta está ya preparada.\"},{\"heading\":false,\"text\":\"Yo me volví hacia Beatriz; y ella, que me había oído antes de que yo hablara, se sonrió de un modo que hizo crecer las alas de mi deseo. Después empecé de este modo:\"},{\"heading\":false,\"text\":\"--Desde que se os patentizó la Igualdad primera, el afecto y la inteligencia tienen un peso igual en cada uno de vosotros; porque en ese Sol, que os ilumina y abrasa con su luz y su calor, son tan iguales ambas virtudes, que toda semejanza es poca. Pero el entendimiento y la voluntad de los mortales, por la razón que os es ya manifiesta, vuelan con diferentes alas. Así es que yo, que soy mortal, me veo en esta desigualdad, y únicamente puedo dar gracias con el corazón a tan paternal acogida. Te suplico, pues, encarecidamente, ¡oh vivo topacio, que enriqueces esa preciosa joya!, que me hagas sabedor de tu nombre.\"},{\"heading\":false,\"text\":\"--¡Oh vástago mío, en quien me complacía mientras te esperaba! Yo fuí tu raíz.\"},{\"heading\":false,\"text\":\"De esta suerte dió principio a su respuesta. Después añadió:\"},{\"heading\":false,\"text\":\"--Aquel de quien ha tomado su nombre tu prosapia, y que por espacio de ciento y más años ha estado girando por el primer círculo del monte, fué mi hijo y tu bisabuelo: bien necesita que con tus obras disminuyas su prolongada fatiga. Florencia, dentro del antiguo recinto donde oye sonar aún tercia y nona, estaba en paz, sobria y púdica. No tenía gargantillas, ni coronas, ni mujeres ostentosamente calzadas, ni cinturones más llamativos a la vista que la persona que los lleva. Al nacer, no causaba miedo la hija al padre, porque la época del matrimonio y el dote no habían salido aún de los límites regulares. No estaban entonces las casas vacías de moradores; no había llegado aún Sardanápalo a enseñar lo que se puede hacer en una cámara. Montemalo no era aún vencido por Uccellatoio, el cual, así como le excede en la subida, le excederá en la bajada. Yo he visto a Bellincion Berti con cinturón de cuero y hebilla de hueso, y a su mujer separarse del espejo sin colorete en el rostro: he visto a los de Nerli y a los del Vecchio contentarse con ir cubiertos de una simple piel, y a sus mujeres dedicadas a la rueca y al huso. ¡Oh afortunadas! Cada una de ellas conocía el lugar donde había de ser sepultada, y ninguna se había visto abandonada en el lecho por causa de Francia. La una velaba su cuna, y para consolar a su hijo usaba el idioma que constituye la primera alegría de los padres y de las madres: la otra, tirando de la blanca cabellera de su rueca, charlaba con su familia de los troyanos, y de Fiésole y de Roma. En aquellos tiempos se habría mirado como una maravilla a una Cianghella y a un Lapo Salterello, como hoy causarían asombro un Cincinato y una Cornelia. En medio de tanta calma, y de tan hermosa vida por parte de todos y entre tan fieles conciudadanos, me hizo nacer la Virgen María, llamada a grandes gritos, y en vuestro antiguo Baptisterio fuí a un tiempo cristiano y Cacciaguida. Moronto y Eliseo fueron mis hermanos; mi esposa procedía del valle del Po, y de ella viene tu apellido. Después seguí al emperador Conrado, que me concedió el título de caballero; tanto fué lo que le agradé por mis buenas acciones. Tras él fuí contra la maldad de aquella ley, cuyo pueblo usurpa vuestro dominio, por culpa del Pastor. Allí aquella torpe raza me libró del mundo falaz, cuyo amor envilece tantas almas, y desde el martirio llegué a esta paz.\"}]},{\"title\":\"Paraíso — canto decimosexto\",\"blocks\":[{\"heading\":false,\"text\":\"¡Oh nobleza de la sangre! Aunque seas muy poca cosa, nunca me admiraré de que hagas vanagloriarse de ti a la gente aquí abajo, donde nuestros afectos languidecen; pues yo mismo, allá donde el apetito no se tuerce, quiero decir, en el cielo, me vanaglorié de poseerte. A la verdad, eres como un manto que se acorta en breve, de modo que si cada día no se le añade algún pedazo, el tiempo lo va recortando en torno con sus tijeras. Con el \\\"vos,\\\" al que Roma fué la primera en someterse y en cuyo empleo no han perseverado tanto sus descendientes, empezaron esta vez mis palabras: por lo cual, Beatriz, que estaba algún tanto apartada, sonrióse, pareciéndose a la que tosió cuando Ginebra cometió la primera falta de que habla la crónica.[147] Yo empecé a decir:\"},{\"heading\":false,\"text\":\"[147] Según cuenta la crónica de la Tabla redonda, la camarera de la reina Ginebra tosió al notar el primer mal paso dado por su señora, llevada del amor a Lanzarote.\"},{\"heading\":false,\"text\":\"--Vos sois mi padre; vos me infundís aliento para hablar; vos me enaltecéis de modo, que soy más que yo mismo. Por tantos arroyos se inunda de alegría mi mente, que se goza en sí misma al considerar que puede contener tanta sin que la abrume. Decidme, pues, ¡oh mi querido antepasado!, quiénes fueron vuestros predecesores, y cuáles los años en que comenzó vuestra infancia. Decidme lo que era entonces el rebaño de San Juan, y cuáles las personas más dignas de elevados puestos.\"},{\"heading\":false,\"text\":\"Como se aviva la llama del carbón al soplo del viento, así vi yo resplandecer aquella luz ante mis afectuosas palabras; y si pareció más bella a mis ojos, más dulce y suave fué también su acento cuando me dijo, aunque no en nuestro moderno lenguaje:\"},{\"heading\":false,\"text\":\"--Desde el día en que se dijo \\\"Ave,\\\" hasta el parto en que mi madre, que hoy es santa, se libró de mi peso, este Planeta fué a inflamarse quinientas cincuenta y tres veces a los pies del León. Mis antepasados y yo nacimos en aquel sitio donde primero encuentra el último distrito el que corre en vuestros juegos anuales. Bástete saber esto con respecto a mis mayores; lo que fueron o de dónde vinieron, es más cuerdo callarlo que decirlo. Todos los que se encontraban entonces en estado de llevar las armas, entre la estatua de Marte y el Baptisterio, formaban la quinta parte de los que ahora viven allí; pero la población, que es al presente una mezcla de gente de Campi, de Certaldo y de Fighine, se veía pura hasta en el último artesano. ¡Oh!, ¡cuánto mejor fuera tener por vecinas a aquellas gentes, y vuestras fronteras en Galluzo y Trespiano, que no tenerlas dentro de vuestros muros, y soportar la fetidez del villano de Aguglión y del de Signa, que tiene ya los ojos muy abiertos para traficar! Si la gente que está más degenerada en el mundo no hubiera sido una madrastra para César, sino benigna como una madre para con su hijo, más de uno que se ha hecho florentino, y cambia y trafica, se habría vuelto a Semifonti, donde andaba su abuelo pordioseando: los Conti estarían aún en Montemurlo; los Cerchi en la jurisdicción de Ancona, y quizá aun en Valdigrieve los Buondelmonti. La confusión de las personas fué siempre el principio de las desgracias de las ciudades, como la mescolanza de los alimentos lo es de las del cuerpo; pues un toro ciego cae más pronto que un cordero ciego; y muchas veces corta más y mejor una espada que cinco. Si consideras cómo han desaparecido Luni y Urbisaglia, y cómo siguen sus huellas Chiusi y Sinigaglia, no te parecerá una cosa difícil de creer el oír cómo se deshacen las familias, puesto que las ciudades mismas tienen un término. Todas vuestras cosas mueren como vosotros; pero se os oculta la muerte de algunas que duran mucho, porque vuestra vida es muy corta; y así como los giros del cielo de la Luna cubren y descubren sin tregua las orillas del mar, lo mismo hace con Florencia la Fortuna: por lo cual no debe asombrarte lo que voy a decir con respecto a los primeros florentinos, cuya fama está envuelta en la obscuridad de los tiempos. He visto ya en decadencia los Ughi, los Catellini, Filippi, Greci, Ormanni y Alberichi, todos ilustres caballeros; he visto también con los de la Sannella a los del Arca y a los Soldanieri, los Ardinghi y los Bostichi, tan grandes como antiguos. Sobre la puerta, cargada al presente con una felonía de tan gran peso, que en breve hará zozobrar vuestra barca, estaban los Ravignani, de quienes descienden el conde Guido, y los que han tomado después el nombre del gran Bellincion. El primogénito de la familia de la Pressa conocía el arte de gobernar bien, y en casa de Galigaio se veían ya los distintivos de la nobleza, que consistían en usar dorados la guarnición y el pomo de la espada. Grande era ya la columna de la Comadreja, e ilustres los Cacchetti, Giuochi, Fifanti, Baruci y Galli, y los que se avergüenzan al recuerdo de la medida. El tronco de que nacieron los Calfucci era ya grande, y ya habían sido promovidos a las sillas curules los Sizii y los Arrigucci. ¡Oh! ¡cuán fuertes he visto a aquéllos, que han sido destruídos por su soberbia! Y sin embargo, las bolas de oro[148] con sus altos hechos hacían florecer a Florencia; así como también los padres de aquellos que siempre que está vacante vuestra iglesia engordan mientras se hallan reunidos en consistorio. La presuntuosa familia[149] que persigue como un dragón al que huye, y se humilla como un cordero ante el que le enseña los dientes o la bolsa, venía ya engrandeciéndose; pero su origen era bajo: por esto no agradó a Ubertino Donato que su suegro le hiciera emparentar con ella. Los Caponsacco habían descendido ya de Fiésole, y habitaban en el Mercado, y ya Giuda e Infangato eran buenos ciudadanos. Voy a decirte una cosa increíble y verdadera: en el pequeño círculo que formaba la ciudad, se entraba por una puerta que debía su nombre a la familia de la Pera. Todos los que llevan las bellas insignias del gran Barón, cuyo nombre y cuya gloria se renuevan en la fiesta de Santo Tomás, recibieron de él sus títulos de caballero y sus privilegios; si bien hoy se ha colocado en el partido del pueblo aquel que rodea sus insignias de un círculo de oro. Ya los Gualterotti y los Importuni vivían tranquilos en el Borgo, y más lo habrían estado sin nuevos vecinos. La casa de que ha nacido vuestro llanto, por el justo rencor que os ha destruído y dado fin a vuestra agradable vida, era honrada con todos los suyos. ¡Oh Buondelmonte!, ¡cuán mal hiciste en no aliarte con ella por medio del matrimonio para consuelo de los demás! Muchos de los que hoy están tristes estarían alegres, si Dios te hubiese entregado a Ema la primera vez que viniste a la ciudad. Pero era preciso que ante aquella piedra rota que guarda el puente sacrificara Florencia una víctima en sus últimos días de paz. Con tales familias y con otras muchas he visto a Florencia en medio de tan gran reposo, que no tenía motivo para llorar. Con estas familias he visto a su pueblo tan glorioso y justo, que jamás el lirio fué llevado al revés en la lanza, ni se había vuelto aún rojo a causa de las discordias.\"},{\"heading\":false,\"text\":\"[148] Los Umberti y los Lamberti, que en sus armas tenían bolas de oro.\"},{\"heading\":false,\"text\":\"[149] Los Adimari, uno de los cuales perjudicó mucho a Dante.\"}]},{\"title\":\"Paraíso — canto decimoseptimo\",\"blocks\":[{\"heading\":false,\"text\":\"Estaba yo afanoso como aquel cuyo ejemplo hace que los padres sean un poco condescendientes con sus hijos, cuando acudió a Climene para cerciorarse de lo que acerca de él había oído; y bien lo conocían Beatriz y aquella luz que por mí había cambiado antes de sitio; por lo cual me dijo mi Dama:\"},{\"heading\":false,\"text\":\"--Exhala el ardor de tu deseo de tal modo que salga bien expresado con la fuerza que lo sientes; no para que nosotros lo conozcamos mejor por tus palabras, sino para que te atrevas a manifestar tu sed, a fin de que otros te den de beber.\"},{\"heading\":false,\"text\":\"--¡Oh mi querida planta, que te elevas tanto, que mirando al punto a quien todos los tiempos son presentes, ves las cosas contingentes antes de que sean en sí, como ven las inteligencias terrestres que dos ángulos obtusos no pueden caber en un triángulo! Mientras acompañado de Virgilio subía yo por el monte donde se curan las almas, y cuando bajaba por el mundo de los muertos, se me dijeron palabras graves acerca de mi vida futura; y aunque me considere como un tetrágono ante los golpes de la desgracia, quisiera saber cuál es la suerte que me está reservada; pues el dardo previsto hiere con menos fuerza.\"},{\"heading\":false,\"text\":\"Así dije a la misma luz que me había hablado antes, manifestando mi deseo como lo quiso Beatriz. Aquel amoroso progenitor mío, encerrado y patente a un mismo tiempo en su esplendor risueño, me contestó, no en los términos ambiguos con que eran engañados los necios gentiles antes de que fuese inmolado el Cordero de Dios que redimió los pecados, sino con palabras claras y en latín correcto:\"},{\"heading\":false,\"text\":\"--Las contingencias a cuyo conocimiento no alcanzan los límites de vuestra materia, están todas presentes a la vista de Dios. De aquí no se infiere, sin embargo, su necesidad, sino como es preciso que se pinte en los ojos de quien la mira, la nave que desciende por una corriente. Desde la mente divina llega a mi vista, como a los oídos la dulce armonía del órgano, el tiempo que para ti se prepara. Del mismo modo que Hipólito partió de Atenas por la crueldad y perfidia de su madrastra, tendrás que salir de Florencia. Esto es lo que se quiere, y lo que se busca y pronto será hecho por los que lo meditan allá donde diariamente se vende a Cristo. Las culpas caerán sobre los vencidos, como es costumbre; pero el castigo dará testimonio de la verdad, que lo envía al que lo merece. Tú abandonarás todas las cosas que más entrañablemente amas, y este es el primer dardo que arroja el arco del destierro. Tú probarás cuán amargo es el pan ajeno, y cuán duro camino el que conduce a subir y bajar las escaleras de otros. Y lo que más gravará tus espaldas será la compañía estúpida y malvada con la cual caerás en este valle; porque ingrata, loca e impía, se revolverá contra tí; si bien poco después, ella y no tú, verá destrozada su frente. Su conducta probará su bestialidad, de suerte que para ti será más laudable haberte separado completamente de ella. Tu primer refugio y tu primer albergue serán la cortesía del Gran Lombardo, que sobre la escala lleva el ave santa,[150] el cual te mirará tan benignamente, que entre ambos el dar precederá al pedir, al contrario de lo que sucede entre los demás. Sí, verás a aquel que al nacer fué tan inspirado por esta fuerte estrella, que sus hechos serán siempre admirados. Los pueblos no han reparado en él aún a causa de su corta edad, pues sólo hace nueve años que giran en derredor suyo estas esferas. Pero antes de que el Gascón engañe al gran Enrique,[151] aparecerán los destellos de su virtud en su desprecio al dinero y a las fatigas. Sus magnificencias serán tan conocidas, que ni aun sus mismos enemigos podrán dejar de referirlas. Espera en él y en sus beneficios; por él muchos hombres serán transformados, y los ricos y los pobres cambiarán de condición. Lleva grabado en tu mente cuanto te predigo acerca de él; pero no lo manifiestes a nadie.\"},{\"heading\":false,\"text\":\"[150] Can el Grande, señor de Verona.\"},{\"heading\":false,\"text\":\"[151] El papa Clemente V, de Gascuña, después de haber promovido al imperio a Enrique VII, favoreció a sus enemigos.\"},{\"heading\":false,\"text\":\"Y me refirió después cosas, que parecerán increíbles aun a aquellos que las presencien. Después añadió:\"},{\"heading\":false,\"text\":\"--Hijo mío, tales son las interpretaciones de lo que se te ha dicho; tales las asechanzas que se te ocultarán por pocos años. No quiero, sin embargo, que odies a tus conciudadanos; pues tu vida se prolongará más aún de lo que tarde el castigo de su perfidia.\"},{\"heading\":false,\"text\":\"Cuando, por su silencio, demostró el alma santa que había concluído de poner la trama en la tela que le presenté urdida, empecé a decir, como el que en sus dudas desea el consejo de una persona entendida, recta y amante:\"},{\"heading\":false,\"text\":\"--Bien veo, padre mío, cómo corre el tiempo hacia mí para darme uno de esos golpes, tanto más graves, cuanto más desprevenido se vive; por lo cual es bueno que me arme de previsión, a fin de que, si se me priva del lugar que más quiero, no pierda los demás por causa de mis versos. Allá abajo, en el mundo eternamente amargo, y en el monte desde cuya hermosa cumbre me elevaron los ojos de mi Dama, y después en el cielo, de luz en luz, he oído cosas, que si las repitiera, serían para muchos de un sabor desagradable; y si soy cobarde amigo de la verdad, temo perder la fama entre los que llamarán a este tiempo el tiempo antiguo.\"},{\"heading\":false,\"text\":\"La luz en que sonreía el tesoro que yo había encontrado allí, empezó por brillar como un espejo de oro a los rayos del Sol, y después respondió:\"},{\"heading\":false,\"text\":\"--Sólo una conciencia manchada por su propia vergüenza o por la ajena encontrará aspereza en tus palabras: no obstante esto, aparte de ti toda mentira manifiesta por completo tu visión, y deja que se rasque el que tenga sarna; pues si tu voz es desagradable al gustarla por primera vez, dejará un alimento vivificante cuando sea digerida. Tu grito hará lo que el viento, que azota más las más elevadas cumbres, lo cual no será una pequeña prueba de honor. Por eso tan sólo se te han mostrado en estas esferas, en el monte y en el doloroso valle las almas que han gozado de cierto renombre; porque el ánimo del que escucha no fija su atención ni presta fe a ejemplos sacados de una raíz oculta y desconocida, ni a otras cosas que no se manifiesten claramente.\"}]},{\"title\":\"Paraíso — canto decimoctavo\",\"blocks\":[{\"heading\":false,\"text\":\"Aquel espíritu bienaventurado se recreaba ya en sus reflexiones, y yo saboreaba las mías, atemperando lo amargo con lo dulce, cuando la Dama que me conducía hasta Dios me dijo:\"},{\"heading\":false,\"text\":\"--Cambia de ideas; piensa que yo estoy al lado de Aquél que alivia todas las contrariedades.\"},{\"heading\":false,\"text\":\"Yo me volví hacia la voz amorosa de mi consuelo, y desisto de expresar cuál fué el amor que vi entonces en sus santos ojos; no sólo porque desconfíe de mis palabras, sino porque la mente no puede repetir lo que es superior a ella, si otro poder no le ayuda. Sólo puedo decir con respecto a este punto que, contemplándola, mi ánimo se vió libre de todo otro deseo: pues el placer eterno, que irradiaba directamente sobre Beatriz, me hacía dichoso al verlo reflejado en su hermoso rostro. Pero ella, desviándome de esta contemplación con la luz de una sonrisa, me dijo:\"},{\"heading\":false,\"text\":\"--Vuélvete y escucha; que no está solamente en mis ojos el paraíso.\"},{\"heading\":false,\"text\":\"Así como algunas veces se ve la pasión en la fisonomía, si aquélla es tanta que el alma entera le está sometida, del mismo modo en los destellos del fulgor santo, hacia el cual me volví, conocí el deseo de continuar nuestra plática. Y en efecto, empezó diciendo:\"},{\"heading\":false,\"text\":\"--En esta quinta rama del árbol que recibe la vida por la copa, y fructifica siempre y nunca pierde sus hojas, son bienaventurados los espíritus que allá abajo, antes de venir al cielo, alcanzaron tan gran renombre, que toda musa se enriquecería con sus acciones: mira los brazos de la cruz, y los que te iré nombrando harán en ellos lo que el relámpago en la nube.\"},{\"heading\":false,\"text\":\"Apenas nombró a Josué, vi pasar un fulgor por la cruz, y el oír pronunciar aquel nombre y ver deslizarse su resplandor fué todo uno. Al nombre del Gran Macabeo, vi moverse otra luz dando vueltas a causa de su alegría. Del mismo modo, a los nombres de Carlo-Magno y de Orlando, mi atenta mirada siguió a dos luces, como sigue la vista el vuelo del halcón. Después pasaron ante mis ojos por aquella cruz Guillermo y Rinoardo, el duque Godofredo y Roberto Guiscardo. En seguida, el alma que me había hablado se movió del mismo modo y se reunió a los anteriores, demostrándome lo artista que era entre los cantores del cielo.\"},{\"heading\":false,\"text\":\"Volvíme hacia la derecha para conocer en Beatriz lo que debía hacer, bien por sus palabras o por sus ademanes; y vi sus ojos tan serenos, tan gozosos, que su rostro sobrepujaba a todos los otros, y hasta a su anterior aspecto. Y así como el hombre que obra bien, por el mayor placer que siente, advierte de día en día el aumento de su virtud, así yo, viendo más resplandeciente aquel milagro de belleza, reparé que se había hecho más extenso el círculo de mi rotación juntamente con el cielo; y en breve espacio de tiempo que muda de color el rostro de una doncella cuando depone el peso de la vergüenza, presentóse a mis ojos, al volverme, una transmutación semejante, por efecto de la blancura de la sexta y templada estrella, que me había recibido en su interior. Yo vi en aquella antorcha de Jove los destellos del amor que en ella existía, representando a mis ojos nuestro alfabeto; y así como las aves que se elevan sobre un río, regocijándose al llegar al sitio donde encuentran su alimento, forman a veces una hilera circular, y otras veces la prolongan, de igual suerte revoloteaban cantando las santas criaturas dentro de aquellas luces, y describiendo D, I o L con sus movimientos.[152] Primeramente ajustaban su baile al canto; después, representando uno de aquellos caracteres, se detenían un momento y guardaban silencio.\"},{\"heading\":false,\"text\":\"[152] Son las tres primeras letras de la palabra Diligite de la frase: Diligite justitiam qui judicatis terram; que se lee en la Sagrada Escritura.\"},{\"heading\":false,\"text\":\"¡Oh divina Pegásea,[153] que glorificas y prolongas la vida de los ingenios, haciendo que perpetúen la memoria de las ciudades y de los reinos! Ilumíname a fin de que describa sus figuras tales cuales las he visto, y de que aparezca tu poder en estos cortos versos.\"},{\"heading\":false,\"text\":\"[153] La musa Calíope.\"},{\"heading\":false,\"text\":\"Las luces formaron, pues, cinco veces siete vocales y consonantes, y yo observé aquellas figuras conforme me fueron apareciendo. \\\"Diligite justitiam\\\" fué el primer verbo y el primer nombre que representaron; \\\"qui judicatis terram\\\" fueron las últimas palabras. Después, en la M del quinto vocablo se quedaron formadas de modo que la estrella de Júpiter en aquel punto parecía de plata moteada de oro. Entonces vi descender otras luces sobre la parte superior de la M y detenerse allí cantando, según creo, el bien que hacia sí las atrae. Después, así como del choque de dos tizones ardientes salen innumerables chispas, de donde los necios deducen augurios, parecióme que se elevaban más de mil luces, remontándose unas más y otras menos, según las distribuye el Sol que las enciende; y cuando cada cual quedó fijo en su puesto, vi que aquellas luces formaban distintamente la cabeza y el cuello de un águila. Aquel que pinta esto no tiene quien le guíe, antes bien él guía todas las cosas, y de él procede esa virtud que mueve a los animales a dar una forma apropiada a sus nidos. Los demás bienaventurados, que anteriormente parecían contentarse con formar sobre la M una corona de lises, por medio de un pequeño movimiento concluyeron la figura del águila.\"},{\"heading\":false,\"text\":\"--¡Oh dulce estrella!, ¡cuántas y qué resplandecientes almas me demostraron allí que nuestra justicia es un efecto del cielo que tú adornas! Por eso suplico a la Mente, principio de tu movimiento y de tu fuerza, que repare de dónde sale el humo que obscurece tus rayos, a fin de que se irrite otra vez contra los compradores y vendedores del templo que se fortificó con los milagros y la sangre de los mártires. ¡Oh milicia celestial a quien contemplo! Ruega por los que existen en la Tierra extraviados por el mal ejemplo. Era ya antigua costumbre hacer la guerra con la espada; hoy se hace arrebatando por doquiera el pan que a nadie niega nuestro piadoso Padre. Pero tú, que escribes solamente para borrar, piensa que aún están vivos Pedro y Pablo, los cuales murieron por la viña que de tal modo echas a perder. Con razón puedes decir: \\\"Tengo tan fijos mis deseos en aquél que quiso vivir solo, y que a consecuencia de un baile fué arrastrado al martirio,[154] que no conozco al Pescador ni a Pablo.\\\"\"},{\"heading\":false,\"text\":\"[154] San Juan Bautista.\"}]},{\"title\":\"Paraíso — canto decimonono\",\"blocks\":[{\"heading\":false,\"text\":\"Ante mi aparecía, con las alas abiertas, la bella imagen que en su dulce fruición hacía dichosas a las almas reunidas. Cada una de éstas parecía un pequeño rubí, en el que brillaba tan encendido un rayo de Sol, que reflejaba a mis ojos la imagen del mismo Sol. Y lo que necesito describir ahora no lo anunció la voz jamás, ni lo escribió la tinta, ni lo concibió la imaginación. Porque vi, y aun oí hablar al pico del águila y decir con su voz \\\"Yo\\\" y \\\"Mio,\\\" cuando su intención era decir: \\\"Nos\\\" y \\\"Nuestro.\\\" Y empezó así:\"},{\"heading\":false,\"text\":\"--Por haber sido justo y piadoso estoy aquí exaltado hasta esta gloria, que no se deja vencer por el deseo; y en la Tierra dejé tal memoria de mí, que los hombres más perversos la recomiendan, pero no siguen su ejemplo.\"},{\"heading\":false,\"text\":\"Así como de muchas brasas sale un solo calor, así también de aquella imagen, formada por muchos amores, salía una sola voz. Entonces respondí:\"},{\"heading\":false,\"text\":\"--¡Oh perpetuas flores de la dicha eterna, que como un solo perfume me hacéis sentir todos vuestros aromas! Poned fin con vuestras palabras al gran ayuno que me ha tenido hambriento durante largo tiempo, por no encontrar en la Tierra alimento alguno. Bien sé que, si la justicia divina se refleja en otras esferas como en un espejo, en la vuestra no se ve a través de un velo. Sabéis cuán atento me preparo a escucharos; sabéis también cuál es aquella duda que para mí se convierte en tan antiguo ayuno.\"},{\"heading\":false,\"text\":\"Así como el halcón a quien quitan la caperuza mueve la cabeza, y bate las alas en señal de contento, demostrando sus deseos e irguiéndose con gallardía, lo mismo ví hacer al águila que estaba formada de alabanzas de la divina Gracia, las cuales cantaban como sabe cantar el que se deleita allá arriba. Después comenzó de esta suerte:\"},{\"heading\":false,\"text\":\"--Aquel que abarcó con su compás hasta las extremidades del mundo, y encerró en su abertura tantas cosas ocultas y manifiestas, no pudo dejar sobre todo el universo una huella tan profunda de su poder, que su entendimiento no fuese infinitamente superior al de todos los entendimientos creados, como lo prueba el que el primer soberbio, que era la criatura más excelente, por no esperar la luz de la gracia divina, cayó del Cielo antes de ser confirmado en ella. De aquí resulta que las criaturas menos perfectas que aquélla son pequeños receptáculos para contener aquel bien sin fin, único que puede medirse a sí mismo. Aun nuestra vista, que es casi un rayo de la mente divina de que están llenas todas las cosas, no puede, por su naturaleza, ser tan penetrante que discierna su principio sino bajo una apariencia muy lejana de la verdad. La vista que recibe vuestro mundo sólo penetra en la justicia sempiterna como el ojo se interna en el mar; que aunque vea el fondo cerca de la orilla, no lo ve en el inmenso piélago; y sin embargo, el fondo existe, pero su profundidad misma lo oculta. No existe luz si no procede del Sér tranquilo que no se turba nunca; fuera de él no hay más que tinieblas, o sombras de la carne o su veneno. Bastante he descorrido el velo que te ocultaba la viva justicia, sobre la que hacías tan frecuentes preguntas, pues tú decías: \\\"Un hombre nace en la orilla del Indo, y allí no hay quien hable de Cristo, ni quien lea o escriba con respecto a él; todas sus acciones y deseos son buenos, y en cuanto puede ver la razón humana, no ha pecado ni en obras ni en palabras: si muere sin bautismo y sin fe, ¿dónde está la justicia que le condena? ¿Dónde su falta, si no cree?\\\" Ahora bien: ¿quién eres tú, que quieres tomar asiento en el tribunal para juzgar a mil millas de distancia con un palmo de vista? En verdad que quien hablando conmigo sutiliza por ver los rayos de la justicia divina, tendría razón para dudar de su rectitud, si no estuviese sobre vosotros la Escritura. ¡Oh animales terrestres!, ¡oh inteligencias burdas! La primera voluntad, que es buena por sí misma, que es el Sumo Bien, no se ha separado jamás de sí misma. Solamente es justo lo que a ella se conforma; ningún bien creado la atrae; pero ella produce este bien con sus rayos.\"},{\"heading\":false,\"text\":\"Cual cigüeña que se revuelve sobre el nido, después de haber alimentado a sus hijos, y así como uno de éstos, ya alimentado, la mira, del mismo modo empezó la bella imagen a agitarse sobre mí, e igualmente elevé mis ojos hacia ella, que movía sus alas, impelidas por tantos espíritus. Al dar vueltas, cantaba y decía: \\\"Mis notas son tan incomprensibles para tí, como el juicio eterno para vosotros los mortales.\\\" Luego que aquellos refulgentes ardores del Espíritu Santo se detuvieron, sin dejar de formar el signo que hizo a los Romanos temibles en el mundo,[155] el mismo signo continuó diciendo:\"},{\"heading\":false,\"text\":\"[155] El águila.\"},{\"heading\":false,\"text\":\"--A este reino no ha subido jamás quien no creyó en Cristo, ni antes ni después de que éste fuera enclavado en el santo leño: pero mira; muchos que exclaman \\\"Cristo, Cristo,\\\" estarán menos próximos a él en el día del juicio, que algunos de los que no han conocido a Cristo; y a tales cristianos causará vergüenza el Etíope, cuando se dividan los dos colegios, uno enteramente rico, y otro miserable. ¿Qué no podrán decir los Persas a vuestros reyes, cuando vean abierto aquel volumen en el que se escriben todos sus desprecios? Allí se verá, entre las obras de Alberto, la que en breve agitará la pluma, y por la cual quedará desierto el reino de Praga. Allí se verá el daño que ocasiona junto al Sena, falsificando la moneda, el que morirá herido por un jabalí.[156] Allí se verá la insaciable soberbia que enloquece del tal modo al escocés y al inglés, que no pueden sufrir el verse contenidos en los límites de sus Estados.[157] Se verá la lujuria y la molicie del de España, y del de Bohemia, que jamás conoció ni quiso conocer el valor.[158] Allí se verá también marcada con una I la bondad del Cojo de Jerusalén,[159] mientras que lo contrario a ella tendrá por marca una M. Se verá la avaricia y la vileza de aquel que guarda la isla del fuego, donde terminaron los prolongados días de Anquises;[160] y para demostrar su mezquindad, se emplearán muchas abreviaturas en su escrito, a fin de que en poco espacio se contengan muchas palabras. Y a la vista de todos aparecerán las vergonzosas obras del tío y del hermano,[161] que han envilecido tan egregia estirpe y dos coronas. Allí serán conocidos el de Portugal y el de Noruega,[162] y el de Rascia, que alteró los cuños de Venecia.[163] ¡Oh Hungría feliz, si no se deja guiar mal! ¡Oh dichosa Navarra, si se defendiese con el monte que la rodea! Todos deben creer que ya, en presagio de esto, Nicosia y Famagusta se lamentan y claman contra su bestia, que no discrepa de las otras.\"},{\"heading\":false,\"text\":\"[156] Felipe el Hermoso.\"},{\"heading\":false,\"text\":\"[157] Los reyes Roberto de Escocia y Eduardo I de Inglaterra.\"},{\"heading\":false,\"text\":\"[158] Alfonso, rey de España. Wenceslao, rey de Bohemia.\"},{\"heading\":false,\"text\":\"[159] La bondad de Carlos el Cojo, rey de Pulla y Jerusalén, estará marcada con una I (uno): es decir, que será igual a uno, mientras que sus maldades llevarán por marca una M (mil), serán iguales a mil.\"},{\"heading\":false,\"text\":\"[160] Fadrique, hijo de Pedro de Aragón, que gobierna la isla de Sicilia, donde está el fuego del Etna.--Dice la vileza, porque Fadrique, después de la muerte de Enrique VII, abandonó vilmente la causa de los gibelinos.\"},{\"heading\":false,\"text\":\"[161] Jaime, rey de Mallorca, y Menorca, y Jaime de Aragón, tío aquél y hermano éste de dicho Fadrique.\"},{\"heading\":false,\"text\":\"[162] Dionisio el Agrícola, rey de Portugal. Noruega, en tiempo de Dante, tenía su rey propio.\"},{\"heading\":false,\"text\":\"[163] Rascia, Raugia, Ragusa, ciudad y territorio de la antigua Dalmacia, sobre el Adriático, cuyo rey falsificó los ducados de Venecia.\"}]},{\"title\":\"Paraíso — canto vigesimo\",\"blocks\":[{\"heading\":false,\"text\":\"Cuando Aquél que ilumina el mundo entero desciende de nuestro hemisferio, de tal modo que el día se extingue en todas partes, el cielo encendido antes por él solo, aparece súbitamente sembrado de luces, en las cuales se refleja una sola. Y aquel estado del cielo me vino a la imaginación, cuando la enseña del mundo y de sus jefes cerró su bendito pico; porque brillando mucho más todos aquellos vivos resplandores, entonaron suaves cantos, que han desaparecido de mi memoria. ¡Oh dulce amor, que bajo aquella riente luz te ocultas! ¡Cuán ardiente me parecías en medio de aquellos efluvios sonoros, que sólo respiran santos pensamientos!\"},{\"heading\":false,\"text\":\"Después que las preciosas y brillantes joyas de que vi adornada la sexta estrella cesaron en sus cantos angélicos, me pareció oír el murmullo de un río que límpido desciende de roca en roca, mostrando la fecundidad de su elevado manantial. Y así como el sonido adquiere su forma en el cuello de la cítara, y en los orificios de la zampoña el soplo del que la toca, así también subió de improviso aquel murmullo por el cuello del Aguila, como si éste estuviese perforado. Prodújose allí una voz, que salió por su pico en forma de palabras, según las esperaba mi corazón, donde las escribí:\"},{\"heading\":false,\"text\":\"--Debes ahora mirar fijamente--empezó a decir--aquella parte de mí misma que en las águilas mortales contempla y soporta la luz del Sol; porque entre los fuegos que componen mi figura, los que hacen centellear el ojo de mi cabeza tienen un grado de luz mayor que todos los demás. Aquel que, haciendo las veces de pupila, luce en medio, fué el cantor del Espíritu Santo, que transportó el arca de ciudad en ciudad: ahora conoce el mérito de su canto en la parte que fué obra de su propia voluntad, por la remuneración que proporcionalmente ha recibido. De los cinco que forman el arco de mi ceja, el que está más próximo al pico consoló a la viuda de la pérdida de su hijo;[164] ahora conoce cuán caro cuesta no seguir a Cristo, por la experiencia que tiene de esta dulce vida y de la opuesta. El que le sigue en la parte superior de la circunferencia de que hablo, dilató su muerte para hacer verdadera penitencia:[165] ahora conoce que los eternos juicios de Dios son invariables, aunque una ferviente oración consiga allá abajo que suceda mañana lo que debería suceder hoy. El otro que sigue se hizo griego conmigo y con las leyes para ceder su puesto al Pastor, guiado por una buena intención que produjo malos frutos:[166] ahora conoce que el mal resultado de su buena acción no le es nocivo, por más que haya sido causa de la destrucción del mundo. Aquel que ves en el declive del arco fué Guillermo, a quien llora la Tierra que se lamenta de Carlos y Federico vivos:[167] ahora conoce el amor del cielo hacia un rey justo, y así lo manifiesta por el resplandor de que está rodeado. ¿Quién creería en el mundo lleno de errores, que el troyano Rifeo fuera en este arco la quinta de las luces santas? Aunque su vista no penetre hasta el fondo de la divina gracia, demasiado conoce ahora lo que en ella no puede ver el mundo.\"},{\"heading\":false,\"text\":\"[164] El emperador Trajano. (Véase el canto X del Purgatorio.)\"},{\"heading\":false,\"text\":\"[165] Ezequías, rey de Judá, a quien Dios, escuchando sus ruegos, concedió quince años más de vida para arrepentirse de sus culpas.\"},{\"heading\":false,\"text\":\"[166] El emperador Constantino, que se hizo griego, esto es, trasladó de Roma a Bizancio la capital del Imperio romano, con las leyes romanas y con el Aguila imperial, por ceder al Papa la ciudad eterna.\"},{\"heading\":false,\"text\":\"[167] Guillermo II, llamado el Bueno, de cuya pérdida se lamenta Sicilia, así como de ver vivos a Carlos el Cojo y Fadrique de Aragón.\"},{\"heading\":false,\"text\":\"Como la alondra que en el aire se cierne cantando, y después calla, contenta de la última melodía que la satisface, tal me pareció la imagen, satisfecha del eterno placer, por cuya voluntad todas las cosas son lo que son: y aun cuando yo hiciese allí visibles mis dudas como el vidrio manifiesta por su transparencia el color de que se ha revestido su superficie, esas mismas dudas no me permitieron esperar la respuesta callando, sino que con su fuerza hicieron salir de mi boca estas palabras: \\\"¿Qué cosas son esas?\\\": por lo cual conocí en los nuevos destellos que despedían aquellas almas dichosas la alegría que les causaba responder a mis preguntas. Después, con el ojo más inflamado, me respondió el bendito signo, para no tenerme por más tiempo entregado a mi asombro:\"},{\"heading\":false,\"text\":\"--Veo que crees estas cosas, porque yo las digo; pero no comprendes cómo pueden ser: de suerte que, aunque creídas, no por eso están menos ocultas. Tú haces como aquel que aprende a conocer las cosas por su nombre, pero que no puede ver su esencia, si otro no se la manifiesta. \\\"Regnum coelorum\\\" cede a la violencia del ardiente deseo y de la viva esperanza, cuyos afectos vencen a la divina voluntad; pero no a la manera que el hombre prevalece sobre el hombre, sino que la vencen porque quiere ser vencida; y vencida, vence con su benignidad. Te causan asombro la primera y la quinta almas que forman el arco de la ceja, porque ves adornada con ellas la región de los Angeles. No salieron paganas de sus cuerpos, como crees, sino cristianas, teniendo fe viva, la una en los pies que debían ser crucificados, y la otra en los que ya lo habían sido. Una de ellas, saliendo del Infierno donde nadie se convierte a Dios con buen deseo, volvió a habitar su cuerpo en recompensa de una viva esperanza; de una viva esperanza, que rogó fervientemente a Dios para resucitarla, a fin de que su voluntad pudiera ser movida. El alma gloriosa de que se habla, vuelta a su carne en que permaneció poco tiempo, creyó en Aquél que podía ayudarla; y al creer, se abrasó de tal modo en el fuego de un verdadero amor, que después de su segunda muerte fué digna de venir a participar de estos goces. La otra, merced a una gracia que mana de una fuente tan profunda, que no ha habido criatura cuya mirada pudiera penetrar hasta su manantial, cifró allá abajo todo su amor en la justicia; por lo cual de gracia en gracia Dios abrió sus ojos a nuestra redención futura, y creyendo en ella, no soportó por más tiempo la fetidez del paganismo, reprendiendo por su causa a las gentes pervertidas. Aquellas tres mujeres que viste junto a la rueda derecha del carro, le bautizaron más de mil años antes de que se instituyera el bautismo. ¡Oh predestinación!, ¡cuán remota está tu raíz de la vista de aquellos que no ven toda la causa primera! Y vosotros, mortales, sed circunspectos en vuestros juicios; pues nosotros, que vemos a Dios, no conocemos aún todos sus elegidos: y sin embargo, no es grata semejante ignorancia; porque nuestra beatitud se perfecciona con este bien, y queremos lo que Dios quiere.\"},{\"heading\":false,\"text\":\"Tal fué el suave remedio que me dió aquella imagen divina para aclarar mi vista. Y así como un buen tocador de cítara hace acompañamiento a un buen cantor con la vibración de las cuerdas, adquiriendo de este modo mayor atractivo el canto, así mientras hablaba, recuerdo que vi a los benditos resplandores agitar sus llamas al compás de las palabras, como los párpados que se mueven acordes y al mismo tiempo.\"}]},{\"title\":\"Paraíso — canto vigesimoprimero\",\"blocks\":[{\"heading\":false,\"text\":\"Mis ojos se habían fijado de nuevo en el rostro de mi Dama, y el ánimo con ellos se había separado de todo otro objeto. Ella no sonreía:\"},{\"heading\":false,\"text\":\"--Pero si yo riese--empezó a decirme--, te quedarías como Semele, cuando fué reducida a cenizas; pues mi belleza, que, según has visto, brilla más cuanto más asciende por las gradas del eterno palacio, si no se moderase, resplandecería tanto, que tu fuerza mortal perecería ante su fulgor como la rama destrozada por el rayo. Nos hemos elevado al séptimo esplendor[168] que, colocado bajo el pecho del ardiente León, difunde ahora sobre la Tierra sus rayos mezclados con el fuerte influjo de aquél. Fija la mente en pos de tus miradas, y haz de tus ojos un espejo para la imagen que se te aparecerá en este espejo.\"},{\"heading\":false,\"text\":\"[168] Al cielo de Saturno.\"},{\"heading\":false,\"text\":\"Quien supiese cuán dulcemente se recreaba mi vista en el semblante dichoso de Beatriz, cuando invitado por ella la dirigí hacia otro objeto, conocería lo grato que me sería obedecer a mi Guía celestial, considerando que el placer de obedecerla contrabalanceaba al que yo sentía contemplándola. Dentro del cristal que, rodeando al mundo, lleva el nombre de su querido señor, bajo cuyo imperio permaneció muerto todo mal, vi una escala del color del oro en que se refleja un rayo de Sol, y tan elevada, que mis ojos no podían seguirla. Vi además bajar por sus escalones tantos resplandores, que pensé que todas las luces que brillaban en el cielo estaban esparcidas allí. Y así, como, por una costumbre natural, las cornejas se agitan reunidas al romper el día para dar calor a sus ateridas alas, y mientras se alejan algunas sin volver, otras regresan al punto de donde se remontaban, y otras revolotean sobre él, lo mismo me pareció que hacían aquellos fulgores que habían ido descendiendo hasta que se detuvieron en un escalón determinado. El que se quedó más cerca de nosotros empezó a resplandecer tanto, que yo decía entre mí: \\\"Conozco el amor que me anuncias.\\\" Pero Aquélla, de quien espero la orden para hablar o callar, permaneció inmóvil: así es que, a pesar mío, hice bien en no preguntar nada. Por lo cual, ella, que leía en la vista de Aquél que lo ve todo el deseo que yo ocultaba, me dijo:\"},{\"heading\":false,\"text\":\"--Puedes manifestar tu ardiente anhelo.\"},{\"heading\":false,\"text\":\"Entonces empecé de esta suerte:\"},{\"heading\":false,\"text\":\"--Mis méritos no me hacen digno de tu respuesta; pero en nombre de aquella que me permite interrogarte, alma bienaventurada, que te ocultas en tu alegría, dame a conocer la causa que tanto te aproxima a mí, y dime por qué no se oye en esta esfera la dulce sinfonía del Paraíso, que tan devotamente resuena en las de abajo.\"},{\"heading\":false,\"text\":\"--Tu oído es tan débil como tu vista--me contestó--; aquí no se canta por la misma razón que Beatriz no sonríe. He descendido tanto por las gradas de la escala santa, sólo para recrearte con mis palabras y con la luz de que estoy revestida. No es un mayor afecto lo que me ha hecho más solícita; pues en toda esta escala hay un amor tan ferviente y más que el mío, según te lo manifiestan los destellos de esas almas; pero la alta caridad, que nos convierte en siervas atentas a la voluntad que rige al mundo, nos designa el sitio en que, según puedes ver, estamos colocadas.\"},{\"heading\":false,\"text\":\"--Bien veo--dije yo--, ¡oh sagrada lámpara!, que un amor libre basta en esta corte para hacer lo que quiere la eterna Providencia; mas lo que me parece sumamente difícil de comprender es por qué fuiste tú entre todas tus compañeras la destinada a este cargo.\"},{\"heading\":false,\"text\":\"Aun no había pronunciado la última palabra, cuando la luz, haciendo un eje de su centro, giró con la rapidez de una rueda. Después me respondió la amorosa alma que estaba dentro de ella:\"},{\"heading\":false,\"text\":\"--La luz divina se fija en mí penetrando en la que me envuelve, y su virtud, unida a mi vista, me eleva tanto sobre mí misma, que veo la suma esencia de que aquélla emana. De aquí proviene la alegría con que brillo; porque a la claridad de mi visión junto la de la luz que me rodea. Pero el alma que más brilla en el cielo, el serafín que tiene más fijos los ojos en Dios no podrá satisfacer tus preguntas; porque lo que deseas saber penetra tan profundamente en el abismo del decreto eterno, que está muy apartado de toda vista creada; y cuando vuelvas al mundo mortal, refiere lo que te digo, a fin de que nadie presuma llegar al fondo de tal arcano. La mente, que aquí es luz, en la Tierra es humo; considera, pues, cómo podrá comprender allá abajo lo que aquí no comprende, por más que el cielo la enaltezca.\"},{\"heading\":false,\"text\":\"Sus palabras me contuvieron de tal modo, que abandoné la cuestión, y me limité a rogarle humildemente que me dijese quién era.\"},{\"heading\":false,\"text\":\"--Entre las dos costas de Italia, y no muy lejos de tu patria, se elevan unos peñascos, tanto que los truenos retumban a mucha menos altura. Aquellos peñascos forman una eminencia que se llama Catria, al pie de la cual hay un yermo consagrado únicamente al culto del verdadero Dios.\"},{\"heading\":false,\"text\":\"Así empezó a hablar por tercera vez; y continuando luego, añadió:\"},{\"heading\":false,\"text\":\"--De tal modo me dediqué allí al servicio de Dios, que sólo con legumbres y zumo de olivas pasaba fácilmente fríos y calores, satisfecho con mis ideas contemplativas. Aquel claustro producía fértilmente para esta parte de los cielos, y ahora está tan vacío, que será preciso que en breve lo sepa el mundo. En aquel sitio estuve yo, Pedro Damián; y Pedro el Pecador en la casa de Nuestra Señora, a orillas del Adriático. Escasa era ya mi vida mortal, cuando fuí llamado y obligado a recibir aquel capelo que sólo se transmite de malo a peor. Vinieron en otro tiempo Cefas y el Vaso de elección del Espíritu Santo,[169] flacos y descalzos, aceptando su alimento de cualquier mano. Ahora los modernos pastores quieren que de uno y otro lado los apoyen, ¡tan pesados son!, y que les lleven en litera, y que vaya detrás quien les sostenga la cola. Cubren con sus mantos sus cabalgaduras, de suerte que van dos bestias bajo una sola piel. ¡Oh paciencia de Dios, que tanto soportas!\"},{\"heading\":false,\"text\":\"[169] San Pedro y San Pablo.\"},{\"heading\":false,\"text\":\"Al sonido de estas palabras, vi muchas llamas que bajaban girando de escalón en escalón, y a cada vuelta se hacían más bellas. Vinieron a detenerse alrededor de aquella luz, y prorrumpieron en un clamor tan alto, que nada en el mundo puede asemejársele: su estruendo me ensordeció de tal modo, que no comprendí lo que dijeron.\"}]},{\"title\":\"Paraíso — canto vegesimosegundo\",\"blocks\":[{\"heading\":false,\"text\":\"Mudo de estupor me volví hacia mi Guía, como un niño que se acoge siempre a quien le inspira más confianza: y aquélla, como la madre que socorre prontamente al hijo azorado y pálido con su voz consoladora, me dijo:\"},{\"heading\":false,\"text\":\"--¿No sabes que estás en el cielo? ¿No sabes que todo el cielo es santo, y que lo que en él se hace procede de un buen celo? Si el grito que acabas de oír te ha conmovido tanto, ahora puedes pensar cómo te habría perturbado aquel suave cántico unido a mi sonrisa. Y si hubieras comprendido lo que se rogó al exhalar ese grito, conocerías la venganza que verás antes de tu muerte. La espada de aquí arriba no hiere nunca demasiado pronto, ni demasiado tarde, como suele parecerles a los que la esperan con temor o con deseo. Pero ahora vuélvete hacia otro lado, y verás muchos espíritus ilustres, si diriges tus miradas según te indico.\"},{\"heading\":false,\"text\":\"Volví los ojos como ella quiso, y vi cien pequeñas esferas, que se embellecían unas a otras con sus mutuos rayos. Yo estaba como aquel que reprime en sí el agudo estímulo del deseo, y no se aventura a preguntar, temiendo excederse, cuando la mayor y más brillante de aquellas perlas se adelantó para contentar mi curiosidad: después oí en su interior:\"},{\"heading\":false,\"text\":\"--Si vieses, como yo, la caridad que arde entre nosotros, habrías expresado ya tus deseos; pero a fin de que, por demasiado esperar, no tardes en llegar al alto fin de tu viaje, contestaré al pensamiento que no te atreves a proferir. La cumbre de aquel monte en cuya falda está Casino fué frecuentada en otro tiempo por gentes engañadas y mal dispuestas. Yo soy el que llevó allí el nombre de Aquél que enseñó en la Tierra la verdad que tanto nos enaltece;[170] y lució sobre mí tanta gracia, que aparté a las ciudades circunvecinas del impío culto que sedujo al mundo. Esos otros fuegos fueron todos hombres contemplativos, abrasados en aquel ardor que hace nacer las flores y los frutos santos. Aquí están Macario y Romualdo; aquí están mis hermanos, que se encerraron en el claustro y conservaron un corazón perseverante.\"},{\"heading\":false,\"text\":\"[170] San Benito abad, que dió a conocer allí la religión cristiana.\"},{\"heading\":false,\"text\":\"Lo contesté:\"},{\"heading\":false,\"text\":\"--El afecto que demuestras hablando conmigo, y la benevolencia que veo y observo en todas vuestras luces, me inspiran la misma confianza que inspira el Sol a la rosa cuando se abre tanto cuanto le es posible. Por eso te ruego, padre, que si soy digno de tal merced, me concedas la gracia de ver tu imagen descubierta.\"},{\"heading\":false,\"text\":\"--Hermano--me respondió--: tu elevado deseo se realizará en la última esfera, donde se realizan todos los otros y los míos, y donde todos son perfectos, maduros y enteros: en aquella sola esfera, todas sus partes permanecen inmóviles, porque no está en un sitio, ni gira entre dos polos, y nuestra escala llega hasta ella, lo que hace que la pierdas de vista. El patriarca Jacob la vió prolongarse hasta arriba, cuando se le apareció tan llena de ángeles; pero ahora no retira nadie sus pies de la tierra para subirla, y mi regla sólo sirve abajo para gastar papel. Los muros que eran una abadía se han convertido en cavernas; y las cogullas en sacos de mala harina. La más sórdida usura no es tan contraria a la voluntad de Dios, como lo es el fruto de esas riquezas que tanto enloquecen el corazón de los monjes, porque todo lo que la Iglesia guarda pertenece a aquellos que piden por Dios, y no a los parientes o a otros más indignos. La carne de los mortales es tan flexible, que las buenas obras no duran el tiempo que transcurre desde el nacimiento de la encina hasta la formación de la bellota. Pedro empezó su fecunda tarea sin oro ni plata; yo con oraciones y con ayunos; Francisco basó su orden en la humildad: y si atiendes al principio de cada orden, y consideras después adonde han llegado, verás lo blanco cambiado en negro. Más admiración causó en verdad ver al Jordán retrocediendo y al mar huír cuando Dios quiso, que la causará ver remediados estos males.\"},{\"heading\":false,\"text\":\"Así me dijo, y después se reunió a sus demás compañeros, que a su vez se reconcentraron, y como un torbellino se elevaron a lo alto. La dulce Dama con un solo ademán me impulsó a subir tras ellos por aquella escala: tanto fué lo que su virtud venció mi grave naturaleza: y jamás aquí abajo, donde se sube y desciende naturalmente, hubo un movimiento tan rápido que pudiera igualar a mi vuelo. Así pueda volver, ¡oh lector!, a aquel piadoso reino triunfante, por el que lloro con frecuencia mis pecados golpeándome el pecho, como es cierto que vi el signo que sigue al Tauro,[171] y me encontré en él en menos tiempo del que necesitarías para meter y sacar un dedo del fuego. ¡Oh gloriosas estrellas!, ¡oh luz llena de gran virtud, en la que reconozco todo mi ingenio, cualquiera que ésta sea! Con vosotras nacía, y se ocultaba con vosotras aquel que es padre de toda vida mortal,[172] cuando sentí por vez primera el aire toscano; y cuando más tarde se me concedió la gracia de entrar en la alta rueda que os hace girar, me fué también permitido pasar por la región en donde estáis. A vosotras dirige ahora devotamente mi alma sus suspiros, para alcanzar la virtud necesaria en la difícil empresa que la atrae.\"},{\"heading\":false,\"text\":\"[171] La constelación de Géminis.\"},{\"heading\":false,\"text\":\"[172] El Sol.\"},{\"heading\":false,\"text\":\"--Estás tan cerca de la última salvación--empezó a decirme Beatriz--, que debes tener los ojos claros y penetrantes; así pues, antes de que llegues a ella, mira hacia abajo y contempla cuántos mundos he puesto bajo tus pies, a fin de que tu corazón se presente tan gozoso como pueda ante la triunfante multitud que alegre acude por esta bóveda etérea.\"},{\"heading\":false,\"text\":\"Recorrí con la vista todas las siete esferas, y ví a nuestro globo tan pequeño, que me reí de su vil aspecto: así es que apruebo como mejor parecer el de quien le tiene en poca estima; pudiendo llamarse verdaderamente probo el que sólo piensa en el otro mundo.\"},{\"heading\":false,\"text\":\"Vi a la hija de Latona inflamada, sin aquella sombra que fué causa de que yo la creyera enrarecida y densa. Allí, ¡oh Hiperión!, pudieron soportar mis ojos la luz de tu hijo, y vi cómo se mueven próximas a él y en derredor suyo Maya y Dione. Allí me apareció Júpiter atemperando a su padre y a su hijo;[173] allí distinguí con claridad sus frecuentes cambios de lugar, y todos los siete planetas me manifestaron su magnitud, su velocidad, y la distancia a que respectivamente se encuentran colocados. Aquel pequeño punto que nos hace tan orgullosos se me apareció por completo desde las montañas a los mares, mientras que yo giraba con los eternos Gemelos. Después fijé mis ojos en los hermosos ojos.\"},{\"heading\":false,\"text\":\"[173] Saturno y Marte.\"}]},{\"title\":\"Paraíso — canto vigesimotercero\",\"blocks\":[{\"heading\":false,\"text\":\"Como el ave que, habiendo reposado entre la predilecta enramada junto al nido de sus dulces hijuelos, durante la noche ocultadora de las cosas, y deseando ver tan caros objetos y hallar el sustento para nutrirlos, cuyo penoso trabajo soporta placentera, se adelanta al día, y antes de rayar el alba sube a la cima del abierto follaje, y fijamente mira, esperando con ardoroso anhelo la salida del Sol, así estaba mi Dama, en pie y atenta, vuelto el rostro hacia la región del cielo bajo la cual se muestra el Sol menos presuroso; y en tanto yo, viéndola suspensa y ansiosa, permanecí como el que anhelante querría otra cosa, pero se calma con la esperanza de obtenerla. Poco intervalo medió entre ambos momentos, es decir, entre el de mi expectativa y el de ver de un instante a otro iluminarse más el cielo. Y Beatriz dijo:\"},{\"heading\":false,\"text\":\"--He ahí la legión del triunfo de Cristo, y todo el fruto recogido de la rotación de estas esferas.\"},{\"heading\":false,\"text\":\"Me pareció que ardía todo su semblante; y tenía los ojos tan llenos de alegría, que debo seguir adelante sin más explicación. Cual en los plenilunios serenos Trivia ríe entre las ninfas eternas, que iluminan el cielo por todas partes, así vi yo sobre millares de luces un Sol, que las encendía todas, como hace el nuestro con las que vemos sobre nosotros; y a través de su viva luz aparecía tan clara a mis ojos la divina substancia, que no podían soportarla.\"},{\"heading\":false,\"text\":\"--¡Oh Beatriz--exclamé--, Guía dulce y querida!\"},{\"heading\":false,\"text\":\"Ella me dijo:\"},{\"heading\":false,\"text\":\"--Lo que te abisma es una virtud a la que nada resiste. Allí están la Sabiduría y el Poder que abrieron entre el Cielo y la Tierra las vías por tanto tiempo deseadas.\"},{\"heading\":false,\"text\":\"Así como el fuego de la nube, dilatándose de modo que ésta no puede contenerlo, se escapa de ella, y, contra su naturaleza, se precipita hacia abajo, de igual suerte mi mente, engrandeciéndose más entre aquellas delicias, salió de sí misma, y no sabe recordar lo que fué de ella.\"},{\"heading\":false,\"text\":\"--Abre los ojos y mírame cual soy; has visto cosas que te han dado fuerza suficiente para sostener mi sonrisa.\"},{\"heading\":false,\"text\":\"Yo estaba como aquel que conserva cierta reminiscencia de una visión olvidada, y que se esfuerza en vano por renovarla en su imaginación, cuando oí proferir estas palabras tan dignas de gratitud, que no se borrarán jamás del libro donde se consigna lo pasado. Si ahora resonasen todas aquellas lenguas que Polimnia y sus hermanas hicieron más pingües con su dulcísima leche para venir en mi ayuda, no expresarían la milésima parte de la verdad, al pretender cantar tan santa sonrisa, y el resplandor que comunicaba a aquel santo rostro: por lo mismo, al describir yo el Paraíso, es forzoso que mi sagrado poema salte como un hombre que encuentra cortado su camino. Quien considere el peso del asunto y el hombro mortal que soporta la carga, no censurará el que éste tiemble bajo su gravedad. El derrotero que hiende mi atrevida proa no es a propósito para una pequeña embarcación, ni para el nauta que quiera ahorrarse la fatiga.\"},{\"heading\":false,\"text\":\"--¿Por qué te enamora mi faz de tal suerte, que no te vuelves hacia el hermoso jardín que florece bajo los rayos de Cristo? Allí está la Rosa[174] en que el Verbo divino encarnó; y allí están los lirios[175] por cuyo aroma se descubre el buen camino.\"},{\"heading\":false,\"text\":\"[174] La Virgen María, llamada por la Iglesia Rosa Mística.\"},{\"heading\":false,\"text\":\"[175] Los bienaventurados.\"},{\"heading\":false,\"text\":\"Así dijo Beatriz, y yo, que estaba siempre pronto a seguir sus consejos, me lancé nuevamente a la batalla de mis débiles párpados. Y así como mis ojos, al abrigo de la sombra, han visto alguna vez un prado de flores iluminado por un rayo de Sol que atravesaba por entre desgarrada nube, del mismo modo distinguí entonces una multitud de esplendores, iluminados desde arriba por ardientes rayos, sin ver el origen de donde estos fulgores procedían.\"},{\"heading\":false,\"text\":\"¡Oh benigna virtud que así los iluminas! Sin duda te elevaste por dejar campo libre a mis ojos, que eran demasiado débiles para contemplarte. El nombre de la hermosa flor que invoco siempre, por mañana y tarde, concentró todo mi espíritu en la contemplación del mayor fuego; y cuando mis dos ojos me representaron la belleza y la extensión de la fulgente estrella que vence arriba, como venció abajo, desde el interior del cielo descendió una llamarada, que tenía la forma de un círculo como una corona,[176] y rodeó a la estrella girando en torno suyo. La melodía que más dulcemente se deje oír en la Tierra, y que más atraiga el ánimo, parecería una nube que desgarrada truena, comparada con el sonido de aquella lira de que estaba coronado el bello zafiro con que se engalana el más claro cielo.\"},{\"heading\":false,\"text\":\"[176] El arcángel San Gabriel.\"},{\"heading\":false,\"text\":\"--Yo soy el amor angélico, que giro difundiendo la sublime dicha, nacida del vientre que fué morada de nuestro deseo; y giraré, Señora del Cielo, mientras acompañas a tu Hijo, y hagas resplandeciente la suprema esfera en donde habitas.\"},{\"heading\":false,\"text\":\"Así se dejaba oír la circular melodía, y todas las demás luces hacían resonar el nombre de María. El manto real de todas las esferas del mundo, que más se inflama y anima bajo el hálito y las perfecciones de Dios, tenía sobre nosotros tan distante la faz interna, que no me era posible distinguir su aspecto desde el sitio en que me encontraba; por lo cual no tuvieron mis ojos la fuerza necesaria para seguir a la llama coronada, que se elevó en pos de su divina primogenitura. Y semejantes al niño que tiende los brazos hacia su madre después de haberse alimentado con su leche, movido del afecto que aun exteriormente se inflama, cada uno de aquellos fulgores se prolongó hacia arriba, patentizándome así el amor que profesaban a María. Después permanecieron ante mi vista cantando \\\"Regina coeli\\\" tan dulcemente, que jamás ha huído de mí el placer que me causaron.\"},{\"heading\":false,\"text\":\"¡Oh cuánta es la abundancia que se encierra en aquellas arcas riquísimas por haber esparcido en la Tierra buenas semillas! Allí viven y gozan del eterno tesoro que conquistaron en el destierro de Babilonia, donde hicieron dejación del oro. Allí triunfa de su victoria bajo el alto Hijo de Dios y de María, y juntamente con el antiguo y el nuevo concilio, el que tiene las llaves de tal gloria.\"}]},{\"title\":\"Paraíso — canto vigesimocuarto\",\"blocks\":[{\"heading\":false,\"text\":\"¡Oh compañía escogida para la gran cena del cordero bendito, el cual os alimenta de tal modo, que vuestro apetito está siempre satisfecho! Ya que por la gracia de Dios éste prueba prematuramente lo que cae de vuestra mesa, antes de que la muerte ponga fin a sus días, pensad en su deseo inmenso, y refrescadlo algún tanto: vosotros bebéis siempre en la fuente de donde procede lo que él piensa.\"},{\"heading\":false,\"text\":\"Esto dijo Beatriz: y aquellas almas gozosas se convirtieron en esferas sobre polos fijos, resplandeciendo vivamente a guisa de cometas. Y como las ruedas en el mecanismo de un reloj se mueven de tal suerte, que a quien las observa le parece que la primera está quieta y la última vuela, así también aquellos glóbulos, danzando diferentemente, me hacían estimar su velocidad o lentitud por el grado de sus resplandores. De aquel conjunto de bellas luces vi salir un fulgor tan alegre y esplendente, que superaba a todos los demás. Tres veces giró en torno de Beatriz, cantando de un modo tan divino, que mi fantasía no ha podido retener su encanto; por lo cual mi pluma pasa adelante sin describirlo, pues para pintar tales pliegues carece de matices, no ya la lengua, sino la misma imaginación.\"},{\"heading\":false,\"text\":\"--¡Oh mi santa hermana, que tan devotamente ruegas, movida de tu ardiente afecto, que me separas de aquella hermosa esfera!\"},{\"heading\":false,\"text\":\"De este modo, luego que se detuvo aquel fuego bendito,[177] dirigió su aliento hacia mi Dama, y le habló como he dicho. Y ella contestó:\"},{\"heading\":false,\"text\":\"[177] San Pedro.\"},{\"heading\":false,\"text\":\"--¡Oh luz eterna del gran Barón a quien nuestro Señor dejó las llaves que llevó abajo desde este goce maravilloso! Examina a éste como te plazca con respecto a los puntos fáciles y difíciles de la Fe, que te hizo andar sobre el mar. A ti no se te oculta si él ama bien, y espera bien y cree; porque tienes la vista fija donde todo está patente; pero ya que este reino ha conseguido ciudadanos por medio de la Fe veraz, es bueno que para glorificarla le toque a él hablar de ella.\"},{\"heading\":false,\"text\":\"Así como el bachiller se prepara, y no habla hasta que el maestro propone la cuestión que debe aprobar, pero no resolver, del mismo modo preparaba yo todas mis razones, mientras ella hablaba, para estar pronto a contestar a tal examinador y a tal profesión.\"},{\"heading\":false,\"text\":\"--Dí buen cristiano, explícate: ¿Qué es la Fe?\"},{\"heading\":false,\"text\":\"Al oír esto alcé la frente hacia aquella luz de donde salían tales palabras; después me volví hacia Beatriz, y ella me hizo un rápido ademán para que dejara brotar el agua de mi fuente interior.\"},{\"heading\":false,\"text\":\"La gracia divina que me permite confesarme con tan alto primipilo--exclamé,--haga claros y expresivos mis conceptos.\"},{\"heading\":false,\"text\":\"Después continué:\"},{\"heading\":false,\"text\":\"--Según lo ha escrito, padre, la verídica pluma de tu querido hermano,[178] que contigo hizo entrar a Roma por el buen camino, la Fe es la substancia de las cosas que se esperan, y el argumento de las que no aparecen a nuestra mente: tal me parece su esencia.\"},{\"heading\":false,\"text\":\"[178] San Pablo.\"},{\"heading\":false,\"text\":\"Entonces oí:\"},{\"heading\":false,\"text\":\"--Piensas rectamente, si comprendes bien por qué la colocó entre las substancias, y no entre los argumentos.\"},{\"heading\":false,\"text\":\"A lo cual contesté:\"},{\"heading\":false,\"text\":\"--Las profundas cosas que aquí se me manifiestan claras y patentes están tan ocultas a los ojos del mundo, que sólo existen en la creencia sobre que se funda la alta esperanza; por eso toma el nombre de substancia. Con respecto a esta creencia es preciso argumentar sin otra luz; por eso toma el nombre de argumento.\"},{\"heading\":false,\"text\":\"Entonces oí:\"},{\"heading\":false,\"text\":\"--Si todo lo que en la Tierra se aprende por vía de enseñanza, se entendiera de ese modo, la sutileza del sofisma sería en vano.\"},{\"heading\":false,\"text\":\"Tales fueron las palabras que exhaló aquel ardiente amor; y después añadió:\"},{\"heading\":false,\"text\":\"--Ha salido bien la prueba de la liga y el peso de esta moneda; pero dime si la tienes en tu bolsa.\"},{\"heading\":false,\"text\":\"Le respondí:\"},{\"heading\":false,\"text\":\"--Sí, la tengo tan brillante y tan redonda, que no cabe duda sobre su cuño.\"},{\"heading\":false,\"text\":\"En seguida salieron estas palabras de la profunda luz que allí resplandecía:\"},{\"heading\":false,\"text\":\"--Esa querida joya, en la que se funda toda otra virtud, ¿de dónde te proviene?\"},{\"heading\":false,\"text\":\"--La abundante lluvia del Espíritu Santo--le contesté--, que está esparcida sobre las antiguas y las nuevas páginas, es el silogismo que me la ha demostrado tan sutilmente, que comparada con ella me parece obtusa toda otra demostración.\"},{\"heading\":false,\"text\":\"Después oí:\"},{\"heading\":false,\"text\":\"--¿Por qué tienes por palabra divina a la antigua y la nueva proposición, que así te han convencido?\"},{\"heading\":false,\"text\":\"Respondí:\"},{\"heading\":false,\"text\":\"--La prueba que me descubre la verdad consiste en las obras subsiguientes, para las cuales la naturaleza no calentó nunca el hierro ni dió golpes en el yunque.\"},{\"heading\":false,\"text\":\"Se me contestó:\"},{\"heading\":false,\"text\":\"--Dí, ¿quién te asegura que aquellas obras hayan existido? ¿Acaso te lo asegura aquello mismo que se quiere probar con ellas? ¿No tienes otro testimonio?\"},{\"heading\":false,\"text\":\"--Si el mundo se convirtió al cristianismo sin necesidad de milagros--dije yo--esto sólo es un milagro tan grande, que los otros no son la centésima parte de él; porque tú entraste pobre y famélico en el campo a sembrar la buena planta que en otro tiempo fué vid y ahora se ha convertido en zarza.\"},{\"heading\":false,\"text\":\"Terminadas estas palabras, resonó en las esferas de la sublime y elevada corte un \\\"Alabemos a Dios\\\" con la melodía que se canta allá arriba. Y aquel Barón que examinándome así me había llevado de rama en rama hasta acercarnos a las últimas hojas, volvió a empezar de esta manera:\"},{\"heading\":false,\"text\":\"--La gracia que enamora a tu mente hate abierto la boca hasta este punto, como abrirse debía: por tanto apruebo cuanto ha salido de ella; mas ahora es preciso que expliques lo que crees y el origen de tu creencia.\"},{\"heading\":false,\"text\":\"--¡Oh Santo Padre!, ¡oh Espíritu, que ves lo que creíste con tal firmeza, que dirigiéndote hacia el sepulcro venciste a pies más jóvenes!--empecé a decir--: quieres que te manifieste el orden de las cosas en que creo, y además me preguntas el motivo de mi creencia. Pues bien, yo te respondo: Creo en un solo y eterno Dios, que sin ser movido, mueve todo el Cielo con amor y con deseo; y en apoyo de tal creencia, no sólo tengo pruebas físicas y metafísicas, sino que también me las suministra la verdad que de aquí llueve por medio de Moisés, por los profetas, por los salmos, por el Evangelio, y por lo que vosotros escribistéis después de haberos iluminado el ardiente Espíritu. Creo en tres Personas eternas, y las creo una esencia tan trina y una, que admiten a la vez \\\"son\\\" y \\\"es.\\\" La profunda naturaleza divina de que ahora trato se ha grabado en mi mente muchas veces por la doctrina evangélica. Tal es el principio, tal la chispa que se dilata hasta convertirse en viva llama, y que brilla en mi interior como estrella en el cielo.\"},{\"heading\":false,\"text\":\"Cual señor que oye lo que lo agrada, y por ello abraza a su siervo, congratulándose por la noticia en cuanto éste se calla, de igual suerte me bendijo cantando y giró tres veces en derredor de mi frente, luego que me callé, aquel apostólico fulgor, por cuyo mandato había yo hablado: tanto fué lo que mis palabras le agradaron.\"}]},{\"title\":\"Paraíso — canto vigesimoquinto\",\"blocks\":[{\"heading\":false,\"text\":\"Si alguna vez sucede que el poema sagrado en que han puesto sus manos el Cielo y la Tierra, y que me ha hecho enflaquecer por espacio de muchos años, triunfe de la crueldad que me tiene alejado del bello redil, donde dormí corderillo enemigo de los lobos que le hacen la guerra; entonces volveré como poeta, con otra voz y otros cabellos, y tomaré la corona de laurel sobre mis fuentes bautismales: porque allí entré en la fe que hace las almas familiares a Dios, y por ella me rodeó Pedro de aquel modo la frente. Después se adelantó hacia nosotros un resplandor desde aquella legión de que salió el primero de los vicarios que Cristo dejó en la Tierra; y mi Dama, llena de alegría, me dijo:\"},{\"heading\":false,\"text\":\"--Mira, mira, he ahí el Barón por quien allá abajo visitan a Galicia.[179]\"},{\"heading\":false,\"text\":\"[179] El apóstol Santiago.\"},{\"heading\":false,\"text\":\"Cual dos palomas que, al reunirse, se demuestran su amor dando vueltas y arrullándose, así vi yo aquellos grandes y gloriosos príncipes acogerse mutuamente, alabando el alimento de que allá arriba se nutren. Mas, cuando hubieron dado fin a sus gratulaciones, ambos se detuvieron silenciosos \\\"coram me,\\\" tan encendidos que humillaban mi rostro. Beatriz dijo entonces riendo:\"},{\"heading\":false,\"text\":\"--¡Oh alma ilustre, que has escrito acerca de la liberalidad de nuestra basílica! Haz resonar la Esperanza en esta altura. Tú sabes que la has simbolizado tantas veces cuantas Jesucristo se os manifestó a los tres en todo su esplendor.\"},{\"heading\":false,\"text\":\"--Levanta la cabeza, y tranquilízate; porque es preciso que lo que llega aquí arriba desde el mundo mortal se madure a nuestros rayos.\"},{\"heading\":false,\"text\":\"Tan consoladoras palabras me fueron dirigidas por el segundo resplandor: entonces elevé los ojos hacia aquellos montes que antes los habían inclinado con su excesivo peso.\"},{\"heading\":false,\"text\":\"--Ya que nuestro Emperador te dispensa la merced de que te encuentres, antes de tu muerte, en la estancia más secreta de su palacio con sus condes, a fin de que habiendo visto la verdad de esta corte, os anime por eso a ti y a los otros la Esperanza que tanto enamora allá abajo, dime en qué consiste ésta; dime cómo florece en tu mente, y de dónde te proviene.\"},{\"heading\":false,\"text\":\"Así habló el segundo resplandor. Y aquella piadosa Dama que guió las plumas de mis alas hacia tan elevado vuelo, respondió antes que yo de esta suerte:\"},{\"heading\":false,\"text\":\"--La Iglesia militante no tiene entre sus hijos otro más provisto de esperanza, como está escrito en el Sol que irradia sobre nuestra multitud: por eso se le ha concedido que desde Egipto venga a ver a Jerusalén, antes de terminar sus combates. Los otros dos puntos sobre que han versado tus preguntas, no por deseo de saber, sino para que él refiera lo grata que te es esta virtud, los dejo a su cargo; que no le serán de difícil resolución, ni le servirán de jactancia: responda, pues, y que la gracia de Dios se lo conceda.\"},{\"heading\":false,\"text\":\"Cual discípulo que responde a su maestro con gusto y prontitud en aquello en que es experto, a fin de revelar su mérito, así respondí yo:\"},{\"heading\":false,\"text\":\"--La Esperanza es una expectación cierta de la vida futura, producida por la gracia divina y los méritos anteriores. Muchas son las estrellas que me comunican esta luz; pero quien primero la derramó en mi corazón fué el supremo cantor[180] del Supremo Señor, \\\"Que esperen en ti los que conocen tu nombre,\\\" dice en sus sublimes cánticos; y ¿quién no lo conoce teniendo mi fe? Tú me has inundado después con su oleada en tu Epístola; de modo que ya estoy lleno, y derramo sobre otros vuestra lluvia.\"},{\"heading\":false,\"text\":\"[180] David.\"},{\"heading\":false,\"text\":\"Mientras yo hablaba, en el seno de aquel incendio fulguraba una llama rápida y frecuente como un relámpago. Después me dijo:\"},{\"heading\":false,\"text\":\"--El amor en que me abraso todavía por la virtud que me siguió hasta la palma y hasta mi salida del campo, quiero que te hable, a ti que con ella te deleitas; siéndome por lo mismo grato que me digas lo que la Esperanza te promete.\"},{\"heading\":false,\"text\":\"Yo le contesté:\"},{\"heading\":false,\"text\":\"--Las nuevas y las antiguas Escrituras prefijan el término a que deben aspirar las almas a quienes Dios ha concedido su amistad, y ese término lo veo ahora tal cual es. Isaías dice que cada una de ellas vestirá en su patria un doble ropaje, y su patria es esta dulce vida. Y tu hermano[181] nos manifiesta más claramente esta revelación, allí donde trata de las blancas vestiduras.\"},{\"heading\":false,\"text\":\"[181] San Juan en el Apocalipsis.\"},{\"heading\":false,\"text\":\"Inmediatamente después de pronunciadas estas palabras, se oyó primeramente sobre nosotros: \\\"Sperent in te;\\\" a lo cual respondieron todos los círculos de almas. Luego resplandeció entre ellas una luz tan viva, que si Cáncer tuviera semejante claridad, el invierno tendría un mes de un solo día. Y como la doncella placentera, que se levanta, y va y toma parte en la danza, sólo por festejar a la recién venida, y no por vanidad u otra flaqueza, así vi al esclarecido esplendor acercarse a los otros dos, que seguían dando vueltas cual era necesario a su ardiente amor. Púsose a cantar con ellos las mismas palabras con la misma melodía; y mi Dama fijó en él sus miradas como esposa inmóvil y silenciosa.\"},{\"heading\":false,\"text\":\"--Ese es aquél que descansó sobre el pecho de nuestro Pelícano; es el que fué elegido desde la cruz para el gran cargo.\"},{\"heading\":false,\"text\":\"Así dijo mi Dama; y sus miradas no dejaron de estar más atentas después que antes de pronunciar estas palabras. Como a quien fija los ojos en el Sol esperando verlo eclipsarse un poco, que a fuerza de mirar, concluye por no ver, así me sucedió con aquel último fuego, hasta que me fué dicho:\"},{\"heading\":false,\"text\":\"--¿Por qué te deslumbras para ver una cosa que aquí no existe? Mi cuerpo es tierra en la Tierra, y allí permanecerá con los otros cuerpos hasta tanto que nuestro número se iguale con el eterno propósito. Las dos luces que se elevaron antes son las únicas que existen en este bienaventurado claustro con sus dos vestiduras; y así lo debes repetir en tu mundo.\"},{\"heading\":false,\"text\":\"Dichas estas palabras, cesó el girar del círculo inflamado juntamente con el dulce concierto que formaba la armonía del triple canto; así como, para descansar o huír de un peligro, se detienen al sonido de un silbo los remos que venían azotando el agua.\"},{\"heading\":false,\"text\":\"¡Ah! ¡Cuánta fué la turbación de mi mente cuando me volví para ver a Beatriz, y no pude lograrlo, a pesar de encontrarme cerca de ella y en el dichoso mundo!\"}]},{\"title\":\"Paraíso — canto vigesimosexto\",\"blocks\":[{\"heading\":false,\"text\":\"Mientras yo permanecía indeciso a causa de mi deslumbrada vista, salió la fúlgida llama que la deslumbró una voz, que llamó mi atención diciendo:\"},{\"heading\":false,\"text\":\"--En tanto que recobras la vista que has perdido mirándome, bueno es que hablando conmigo compenses su pérdida. Empieza, pues, y dime adónde se dirige tu alma, y persuádete de que tu vista sólo está ofuscada, pero no destruída; pues la Dama que te conduce por esta región luminosa tiene en su mirada la virtud que tuvo la mano de Ananías.\"},{\"heading\":false,\"text\":\"Yo dije:\"},{\"heading\":false,\"text\":\"--Venga tarde o temprano, según su voluntad, el remedio a mis ojos, que fueron las puertas por donde ella entró con el fuego en que me abraso. El bien que esparce la alegría en esta corte es el \\\"alfa\\\" y el \\\"omega\\\" de cuanto el amor escribe en mí, ya sea leve o fuertemente.\"},{\"heading\":false,\"text\":\"Aquella misma voz que había desvanecido el miedo causado por mi súbito deslumbramiento, excitó nuevamente en mí el deseo de hablar, diciendo:\"},{\"heading\":false,\"text\":\"--Es preciso que te limpies en una criba más fina: es preciso que digas quién dirigió tu arco hacia tal blanco.\"},{\"heading\":false,\"text\":\"--Los argumentos filosóficos--contesté--, y la autoridad que desciende de aquí, han debido infundirme tal amor; porque el bien, por sí mismo, apenas es conocido, enciende tanto más el amor, cuanta mayor bondad encierra. Así pues, la mente de todo el que conoce la verdad en que se funda esta prueba, debe inclinarse a amar con preferencia a ninguna otra cosa aquella esencia,[182] en la cual hay tanta ventaja, que los demás bienes existentes fuera de ella no son más que un rayo de su luz. Esa verdad la ha declarado a mi inteligencia aquel que me demuestra el primer amor de todas las substancias eternas. Me la declaran también las palabras del veraz Hacedor, que dijo a Moisés hablando de sí mismo: \\\"Yo te mostraré reunidas en mí todas las perfecciones.\\\" Tú también me la declaras en el principio de tu sublime anuncio, que publica en la Tierra el arcano de arriba más altamente que ningún otro.\"},{\"heading\":false,\"text\":\"[182] Dios.\"},{\"heading\":false,\"text\":\"Y yo oí:\"},{\"heading\":false,\"text\":\"--Por cuanto te dice la inteligencia humana, de acuerdo con la autoridad divina, reserva para Dios el mayor de tus amores. Pero dime todavía si te sientes atraído hacia él por otras cuerdas, y dime con cuantos dientes te muerde este amor.\"},{\"heading\":false,\"text\":\"No se me ocultó la santa intención del águila de Cristo; pues comprendí hasta dónde quería llevar mi confesión: por eso empecé a decir:\"},{\"heading\":false,\"text\":\"--Todos los estímulos que pueden obligar al corazón a volverse hacia Dios concurren en mi caridad; porque la existencia del mundo y mi existencia, la muerte que El sufrió para que yo viva, y lo que espera todo fiel como yo, juntamente con el conocimiento antedicho, me han sacado del piélago de los amores tortuosos, y me han puesto en la playa del recto amor. Amo las hojas que adornan todo el huerto del Hortelano eterno en la misma proporción del bien que aquél les comunica.\"},{\"heading\":false,\"text\":\"Apenas guardé silencio, resonó por el Cielo un dulcísimo canto; y mi Dama decía con los demás: \\\"¡Santo, Santo, Santo!\\\" Y así como la aparición de una luz penetrante desvanece el sueño, excitando el sentido de la vista, el cual acude a la claridad que atraviesa las membranas; y el despertado la rehuye, aturdido en su repentino desvelo, mientras no le ayuda la facultad estimativa, de igual suerte ahuyentó Beatriz todo entorpecimiento de mis ojos con el rayo de los suyos, que brillaba a más de mil millas: entonces vi mejor que antes, y casi estupefacto pregunté quién era un cuarto resplandor que distinguí con nosotros. Mi Dama me dijo:\"},{\"heading\":false,\"text\":\"--Dentro de esos rayos contempla amorosa a su Hacedor la primera alma creada por la Virtud primera.[183]\"},{\"heading\":false,\"text\":\"[183] Adán.\"},{\"heading\":false,\"text\":\"Como el follaje que doblega su copa al paso del viento, y después se levanta por la propia virtud que la endereza, tal hice yo, maravillado mientras ella hablaba, e irguiéndome después a impulsos del deseo de preguntar que me abrasaba; por lo que empecé de esta suerte:\"},{\"heading\":false,\"text\":\"--¡Oh fruto, que fuiste producido ya maduro! ¡Oh padre antiguo, de quien toda esposa es hija y nuera! Tan devotamente como puedo te suplico que me hables; tú ves mis deseos, los cuales no te manifiesto por oír más pronto tus palabras.\"},{\"heading\":false,\"text\":\"A veces un animal encubertado se agita de modo que manifiesta por los movimientos de su envoltura aquello que desea: del mismo modo la primer alma me daba a conocer por la luz de que estaba revestida la alegría que le causaba complacerme. Después dijo:\"},{\"heading\":false,\"text\":\"--Sin que me lo hayas expresado, conozco tu deseo mejor que tú aquello de que estés más cierto; porque lo veo en el veraz espejo cuyo parhelio son las demás cosas, y que no es parhelio de ninguna. Quieres oír cuánto tiempo ha que Dios me colocó en el excelso jardín en donde ésa te preparó a subir tan larga escala; por cuánto tiempo deleitó mis ojos; la verdadera causa de la gran ira, y el idioma inventado por mí de que hice uso. Sabe, pues, hijo mío, que el haber probado la fruta del árbol no fué la causa de tan largo destierro, sino solamente el haber infringido la orden. En aquel lugar de donde tu Dama hizo partir a Virgilio, estuve deseando esta compañía por espacio de cuatro mil trescientas dos revoluciones del Sol; y mientras permanecí en la Tierra, le vi volver a todas las luces de su carrera novecientas treinta veces. La lengua que hablé se extinguió completamente antes que las gentes de Nemrod se dedicaran a la obra interminable; porque ningún efecto racional fué jamás duradero, a causa de la voluntad humana, que se renueva según la posición y la influencia de los astros. Es cosa muy natural que el hombre hable; pero la naturaleza deja a vuestra discreción que lo hagáis de este o del otro modo. Antes que yo descendiese a las angustias infernales, se daba en la Tierra el nombre de I[184] al Sumo Bien de quien procede la alegría que me circunda; ELI se le llamó después y así debía ser; porque el uso de los mortales es como la hoja de una rama, que desaparece para ceder su puesto a otra nueva. En el monte que se eleva más sobre las ondas estuve yo, con vida pura y deshonesta, desde la primera hora hasta la que es segunda después de la hora sexta, cuando el Sol pasa de uno a otro cuadrante.\"},{\"heading\":false,\"text\":\"[184] Otros escriben un (único), El, por Eli, o J, principio del nombre de Jehová, y sobre cada una de estas opiniones se ha discutido mucho.\"}]},{\"title\":\"Paraíso — canto vigesimoseptimo\",\"blocks\":[{\"heading\":false,\"text\":\"\\\"Gloria al Padre, gloria al Hijo, gloria al Espíritu Santo,\\\" entonó todo el Paraíso con tan dulce canto, que me embriagaba. Lo que veía me parecía una sonrisa del Universo, pues mi embriaguez penetraba por el oído y por la vista. ¡Oh gozo!, ¡oh inefable alegría!, ¡oh vida entera de amor y de paz!, ¡oh riqueza segura y sin deseo! Ante mis ojos estaban encendidas las cuatro antorchas, y aquella que había venido primero empezó a lanzar más vivos destellos, transformándose su aspecto cual aparecería el de Júpiter, si éste y Marte fueran aves y trocasen su plumaje. La Providencia, que distribuye aquí a su placer los oficios de cada uno, había impuesto silencio a todo el coro de los bienaventurados, cuando oí estas palabras:\"},{\"heading\":false,\"text\":\"--No te admires al ver que mi semblante se demuda; pues verás demudarse el de todos éstos mientras hablo. Aquel que usurpa en la Tierra mi puesto, mi puesto, mi puesto, que está vacante a los ojos del Hijo de Dios, ha hecho de mi cementerio una sentina de sangre y podredumbre, que al perverso caído desde aquí[185] sirve allá abajo de complacencia.\"},{\"heading\":false,\"text\":\"[185] Lucifer.\"},{\"heading\":false,\"text\":\"Entonces vi cubrirse todo el cielo de aquel color que comunica el Sol por mañana y tarde a las nubes opuestas a él; y cual mujer honesta que, segura de sí misma, se ruboriza tan sólo al escuchar las faltas ajenas, así vi yo a Beatriz cambiar de aspecto: un eclipse semejante creo que hubo en el cielo cuando la pasión del Poder Supremo. Después, con voz tan alterada, que no fué mayor la alteración de su semblante, continuó en estos términos:\"},{\"heading\":false,\"text\":\"--Mi sangre, así como la de Lino y la de Cleto,[186] no alimentó a la Esposa de Cristo para acostumbrarla a adquirir oro, sino para que adquiriese aquella vida virtuosa por la que Sixto y Pío, Calixto y Urbano derramaron su sangre después de muchas lágrimas. No fué nuestra intención que una parte del pueblo cristiano estuviese sentada a la derecha y otra a la izquierda de nuestro sucesor, ni que las llaves que me fueron concedidas se convirtieran en una enseña de guerra para combatir contra los bautizados, ni que estuviese representada mi imagen en un sello para servir a privilegios vendidos y falsos, de que con frecuencia me avergüenzo e irrito. En todos los prados se ven allá abajo lobos rapaces disfrazados de pastores. ¡Oh justicia de Dios!, ¿por qué duermes? Los de Cahors y los de Gascuña se preparan a beber nuestra sangre. ¡Oh buen principio, en que fin tan vil has de venir a parar! Pero la alta Providencia, que por medio de Escipión defendió en Roma la gloria del mundo, lo socorrerá en breve según imagino. Y tú, hijo, que todavía has de volver abajo, llevado por el peso de tu cuerpo mortal, abre allí la boca y no ocultes lo que yo no oculto.\"},{\"heading\":false,\"text\":\"[186] Papas y mártires, sucesores de San Pedro.\"},{\"heading\":false,\"text\":\"Así como nuestro aire despide hacia la Tierra copos de helados vapores, cuando el cuerno de la Cabra del cielo toca al Sol,[187] de igual modo vi elevarse aquel éter puro, y despedir hacia lo alto los vapores triunfantes que allí se habían detenido con nosotros. Mi vista seguía sus semblantes, y los siguió hasta que la mucha distancia me impidió ir más adelante: por lo cual mi Dama, reparando que había cesado de mirar hacia arriba, me dijo:\"},{\"heading\":false,\"text\":\"--Baja la vista y advierte cuánto has girado.\"},{\"heading\":false,\"text\":\"[187] Cuando el Sol está en Capricornio, o sea en diciembre y enero.\"},{\"heading\":false,\"text\":\"Entonces vi que, desde la hora en que miré por primera vez a la Tierra, había yo recorrido todo el arco formado por el primer clima desde la mitad hasta el fin; de modo que veía más allá de Cádiz el insensato paso de Ulises, y a esta parte casi divisaba la playa donde Europa se convirtió en dulce carga:[188] y aun habría descubierto mayor espacio de este globulillo, a no ser porque el Sol me precedía bajo mis pies un signo y algo más. El amoroso espíritu con que adoro siempre a mi Dama ardía más que nunca en deseos de volver nuevamente hacia ella los ojos; y las bellezas que la naturaleza o el arte han producido para cautivar la vista y atraer los espíritus, ya en cuerpos humanos, ya en pinturas, todas juntas serían nada en comparación del placer divino que me iluminó cuando me volví hacia su faz riente: la fuerza que me infundió su mirada me apartó del bello nido de Leda,[189] y me transportó al cielo más veloz.[190] Sus partes vivísimas y excelsas son tan uniformes, que no sabré decir cuál de ellas escogió Beatriz para mi entrada en él; pero ella, que veía mi deseo, empezó a decirme, sonriéndose tan placentera, que parecía regocijarse Dios en su semblante:\"},{\"heading\":false,\"text\":\"[188] Las playas fenicias, donde Júpiter, transformado en toro, robó a Europa.\"},{\"heading\":false,\"text\":\"[189] Del signo de Géminis.\"},{\"heading\":false,\"text\":\"[190] Al cielo llamado Primer móvil.\"},{\"heading\":false,\"text\":\"--En esta esfera empieza, como en su meta, el movimiento, que naturalmente cesa en el centro, mientras todo lo demás gira en torno suyo; y este cielo no tiene otro sitio donde adquirir movimiento más que la mente divina, en la cual se enciende el amor que le impulsa y la influencia que vierte sobre las demás cosas. La luz y el amor la circundan, así como él circunda a los otros cielos inferiores; y ese círculo de luz y de amor lo dirige y lo comprende tan sólo Aquél que rodea con él a este cielo. Su movimiento no está determinado por otro alguno; pero los demás están medidos por éste, lo mismo que diez por la mitad y el quinto. Ahora puedes comprender cómo el tiempo tiene sus raíces en este tiesto, y en los otros las hojas. ¡Oh concupiscencia, que de tal modo sumerges en ti a los mortales, que a ninguno le es posible sacar los ojos fuera de tus ondas! Mucho florece la voluntad en los hombres; pero la continua lluvia convierte las verdaderas ciruelas en endrinas. La fe y la inocencia sólo se encuentran en los niños; y después cada una de ellas huye antes de que el vello cubra sus mejillas. Hay quien ayuna balbuceando todavía, y luego que tiene la lengua suelta, devora cualquier alimento en cualquier época; y también hay quien, balbuciente aún, ama y escucha a su madre, y cuando llega a hablar claramente, desea verla sepultada. No de otro modo la piel de la bella hija del que os trae la mañana y os deja la noche, siendo blanca al principio, se ennegrece después.[191] Y a fin de que no te maravilles, sabe que en la Tierra no hay quien gobierne; por lo cual va tan descarriada la raza humana. Pero antes de que el mes de enero deje de pertenecer al invierno, a causa del centésimo de que allá abajo no hacen caso, estos círculos superiores rugirán de tal suerte, que la borrasca, por tanto tiempo esperada, volverá las popas donde ahora están las proas, haciendo que la flota navegue directamente, y que el verdadero fruto venga en pos de la flor.\"},{\"heading\":false,\"text\":\"[191] La Naturaleza humana.\"}]},{\"title\":\"Paraíso — canto vigesimoctavo\",\"blocks\":[{\"heading\":false,\"text\":\"Después que aquella que eleva mi alma al Paraíso me manifestó la verdad contrapuesta a la vida actual de los míseros mortales, recuerda mi memoria que, así como el que ve en un espejo la llama de una antorcha encendida detrás de él, antes de haberla visto o pensado en ella, se vuelve para cerciorarse de si el cristal le dice la verdad, y ve que los dos están acordes, como la nota musical con el compás, así hice yo al contemplar los hermosos ojos en donde tejió amor la cuerda que me sujetó: y cuando me volví, y se vieron heridos los míos por lo que aparece en aquel cielo toda vez que se observe con atención su movimiento, distinguí un punto que despedía tan penetrante luz, que es preciso cerrar los ojos iluminados por ella, a causa de su aguda intensidad. La estrella que más pequeña parece desde la Tierra, colocada a su lado, como una estrella cerca de otra, parecería una luna. Casi tanto como el cerco de un astro parece distar de la luz que le traza, cuando el vapor que lo forma es más denso, distaba del centro de aquel punto un círculo de fuego, girando tan rápidamente, que hubiera vencido en celeridad al movimiento de aquel Cielo que más velozmente gira ciñendo al mundo. Este círculo estaba rodeado por otro, y éste por un tercero, y el tercero por el cuarto, por el quinto el cuarto, y después por el sexto el quinto; sobre éstos seguía el séptimo, de tan gran extensión, que la mensajera de Juno[192] sería demasiado estrecha para contenerlo por completo. Lo mismo sucedía con el octavo y el noveno,[193] y cada cual de ellos se movía con más lentitud según su mayor distancia del Uno, teniendo la llama más clara el que menos distaba de la luz purísima; porque, según creo, participa más de su verdad. Mi Dama, que me veía presa de una viva curiosidad, me dijo:\"},{\"heading\":false,\"text\":\"[192] Iris.\"},{\"heading\":false,\"text\":\"[193] Estos nueve círculos luminosos son formados por los nueve órdenes angélicos, y su punto céntrico es Dios.\"},{\"heading\":false,\"text\":\"--De aquel punto depende el Cielo y toda la naturaleza. Mira aquel círculo que está más próximo a él, y sabe que su movimiento es tan rápido a causa del ardiente amor que le impulsa.\"},{\"heading\":false,\"text\":\"Le contesté:\"},{\"heading\":false,\"text\":\"--Si el mundo estuviera dispuesto en el orden en que veo esas ruedas, tu explicación me hubiera satisfecho; pero en el mundo sensible se pueden ver las cosas tanto más rápidas cuanto más apartadas están de su centro: así es que, si mi deseo debe tener fin en este maravilloso y angélico templo, cuyos únicos confines son el amor y la luz, necesito todavía oír cómo es que el modelo y la copia no van del mismo modo; porque yo en vano reflexiono en ello.\"},{\"heading\":false,\"text\":\"--Si tus dedos no bastan para deshacer ese nudo, no es maravilla: ¡tan sólido se ha hecho por no haber sido tocado!\"},{\"heading\":false,\"text\":\"Así dijo mi Dama; después añadió:\"},{\"heading\":false,\"text\":\"--Medita lo que voy a decirte, si quieres quedar satisfecho, y aguza sobre ello el ingenio. Los círculos corpóreos son anchos y estrechos, según la mayor o menor virtud que se difunde por todas partes. Cuanto mayor es su bondad, más saludables son los efectos que produce; y el cuerpo mayor contiene mayor bondad, con tal que sean todas sus partes igualmente perfectas. Ahora bien, este círculo en que estamos, que arrastra consigo todo el alto universo, corresponde al que más ama y más sabe; por lo cual, si te fijas en la virtud y no en la extensión de las substancias que te aparecen dispuestas en círculos, verás una relación admirable y gradual entre cada Cielo y su inteligencia.\"},{\"heading\":false,\"text\":\"Puro y sereno, como queda el hemisferio del aire cuando Bóreas sopla con la menos impetuosa de sus mejillas, limpiando y disolviendo la niebla que antes lo obscurecía todo, y haciendo que el cielo ostente las bellezas de toda su comitiva, quedé yo cuando mi Dama me satisfizo con sus claras respuestas, viendo entonces la verdad tan brillante como las estrellas en el cielo. Cuando hubo terminado sus palabras, empezaron a chispear los círculos, como chispea el hierro candente; y aquel centelleo, que parecía un incendio, era imitado por cada chispa de por sí, siendo éstas tantas, que su número se multiplicaba mil veces más que el producido por la multiplicación de las casillas de un tablero de ajedrez.[194] Yo oía cantar \\\"Hosanna,\\\" de coro en coro, en alabanza del punto fijo, que los tiene y siempre los tendrá en el lugar donde siempre han estado: y aquella que veía las dudas de mi mente dijo:\"},{\"heading\":false,\"text\":\"[194] La multiplicación duplicada de las casillas del tablero de ajedrez produce una cantidad asombrosa, en esta forma: 1.ª casilla, 1; 2.ª, 2; 3.ª, 4; 4.ª, 8; 5.ª, 16; 6.ª, 32; hasta la casilla 64, que arroja veinte cifras, o sean decenas de trillón. Cuéntase que el inventor del ajedrez fué un indiano, el cual presentó el nuevo juego a un rey de Persia; y habiéndole ofrecido éste darle lo que pidiese, pidió un cuartillo de grano, duplicado y tantas veces multiplicado cuantas eran las casillas del tablero. El rey se lo concedió riéndose; pero no pudo pagarle, porque no hubo en todo el reino bastante grano para ello.\"},{\"heading\":false,\"text\":\"--Los primeros círculos te han mostrado los Serafines y los Querubines. Siguen con tal velocidad su amorosa cadena para asemejarse al punto cuanto pueden, y pueden tanto más, cuanto más altos están para verle. Aquellos otros amores, que van en torno de ellos, se llaman Tronos de la presencia divina, en los cuales termina el primer ternario; y debes saber que es tanto mayor su gozo, cuanto más penetra su vista en la Verdad, en que se calma toda inteligencia. Aquí puede conocerse que la beatitud se funda en el acto de ver, y no en el de amar a Dios, lo cual viene después; y siendo las obras meritorias engendradas por la gracia y la buena voluntad, la medida de la contemplación procede así de grado en grado. El otro ternario, que germina en esta primavera eterna de modo que no le despoja el Aries nocturno, canta perpetuamente \\\"Hosanna\\\" con tres melodías, que resuenan en los tres órdenes de alegría de que se compone. En esa jerarquía están las tres diosas: primera, Dominaciones; segunda, Virtudes, y el tercer orden es el de las Potestades. Después, en los dos penúltimos círculos giran los Principados y los Arcángeles: el último se compone todo de angélicos festejos. Todos estos órdenes tienen sus miradas fijas arriba, y ejercen abajo tal influencia, que así como ellos son atraídos por Dios, atraen lo que está debajo de ellos. Con tal ardor se puso Dionisio[195] a contemplar esos órdenes, que los nombró y distinguió como yo. Pero Gregorio[196] se separó de él después; así es que en cuanto abrió los ojos en este cielo, se ha reído de sí mismo. Y si un mortal ha revelado en la Tierra una verdad tan secreta, no quiero que te admires; porque el que la vió aquí arriba[197] se la descubrió, con otras muchas cosas referentes a las verdades de estos círculos.\"},{\"heading\":false,\"text\":\"[195] San Dionisio Areopagita, en su libro =De coelesti hierarchia=.\"},{\"heading\":false,\"text\":\"[196] San Gregorio el Grande, que modificó el orden de los ángeles seguido por San Dionisio.\"},{\"heading\":false,\"text\":\"[197] San Pablo, que fué transportado al cielo, e instruyó a San Dionisio.\"}]},{\"title\":\"Paraíso — canto vigesimonono\",\"blocks\":[{\"heading\":false,\"text\":\"Silenciosa y con el rostro risueño permaneció Beatriz, mirando fijamente al punto que me había deslumbrado, tanto espacio de tiempo como el que media desde el momento en que el cenit mantiene en equilibrio a los dos hijos de Latona, cuando éstos, cobijados respectivamente por Aries y Libra, se forman una misma zona del horizonte, hasta que uno y otro rompen aquel cinto cambiando de hemisferio.[198] Después empezó así:\"},{\"heading\":false,\"text\":\"[198] Quiere decir que Beatriz guardó silencio, mirando fijamente a Dios sólo un instante. Los hijos de Latona son el Sol y la Luna: cuando ambos se hallan en el mismo horizonte, uno en frente de otro, en Aries y Libra, como tenidos en balanza por una mano invisible, inmediatamente rompen ese equilibrio aparente, ascendiendo el uno a nuestro hemisferio, y pasando el otro al hemisferio opuesto.\"},{\"heading\":false,\"text\":\"--Yo te diré sin preguntar lo que deseas oír, porque lo he visto desde allí donde converge todo \\\"ubi\\\" y todo \\\"quando.\\\" No con objeto de adquirir para sí ningún bien (que esto no puede ser), sino a fin de que su esplendor, reflejándose en las criaturas, pudiera decir: \\\"Existo,\\\" el Eterno Amor, en su eternidad, antes que el tiempo fuese, y de un modo incomprensible a toda otra inteligencia, se difundió según le plugo, creando nuevos amores. No es decir que antes permaneciera ocioso y como inerte; pues el proceder del espíritu de Dios sobre estas aguas no tuvo antes ni después. La forma y la materia pura salieron juntamente con una existencia sin defecto, como salen tres flechas de un arco de tres cuerdas; y así como la luz brilla en el vidrio, en el ámbar o en el cristal, de manera que entre el llegar y el ser toda no media intervalo alguno, así también aquel triforme efecto irradió a la vez de su Señor, sin distinción entre su principio y su existencia perfecta. Simultáneamente fué también creado y establecido el orden de las substancias; y aquellas en que se produjo el acto puro fueron colocadas en la cima del mundo. A la parte inferior fué destinada la potencia pura; y en el medio unió a la potencia y a la acción un vínculo que nunca se desata. Jerónimo escribió que los ángeles fueron creados muchos siglos antes de que fuera hecho el otro mundo; pero esta verdad está escrita en varios pasajes de los escritores del Espíritu Santo, y la podrás observar si bien la examinas, como que hasta la misma razón la ve en parte; pues no podría comprender que los motores permanecieran tanto tiempo sin su perfección. Ahora sabes ya dónde, cómo y cuándo fueron creados estos amores; de modo que están extinguidos tres ardores de tu deseo. No contarías de uno a veinte con la prontitud con que una parte de los ángeles turbó el mundo de vuestros elementos. La otra parte quedó aquí, y empezó la obra que contemplas, con tanto placer que nunca cesa de girar. La causa de la caída fué el maldito orgullo de aquel que viste en el centro de la Tierra, pesando sobre él toda la gravedad del mundo. Esos que ves aquí fueron modestos, reconociendo la bondad que los había hecho dispuestos a tan altas miras; por lo cual sus inteligencias fueron de tal modo exaltadas por la gracia que ilumina y por su mérito, que poseen una plena y firme voluntad. Y no quiero que dudes, sino que tengas completa certidumbre de que es meritorio recibir la gracia en proporción del amor con que se la pide y acoge. En adelante, puedes contemplar a tu placer y sin otra ayuda este consistorio, si has entendido mis palabras: pero como en la Tierra y en vuestras escuelas se lee que la naturaleza angélica es tal que entiende, recuerda y quiere, te diré más todavía para que veas en toda su pureza la verdad que abajo se confunde, equivocando semejante doctrina. Estas substancias, después de haberse recreado en el rostro de Dios, no separaron su mirada de éste para quien nada hay oculto; así es que su vista no está interceptada por ningún nuevo objeto, y en consecuencia, no necesitan la memoria para recordar un concepto separado de su pensamiento. Allá abajo, pues, se sueña sin dormir, creyendo unos y no creyendo otros decir la verdad; pero en éstos hay más falta y más vergüenza. Los que allá abajo os dedicáis a filosofar, no vais por un mismo sendero; tanto es lo que os arrastra el afán de parecer sabios e ingeniosos: y aun esto se tolera aquí con menos rigor que el desprecio de la Sagrada Escritura o su torcida interpretación. No pensáis en la sangre que cuesta sembrarla por el mundo, y lo grato que es a Dios el que uniforma humildemente sus ideas a las de aquélla. Sólo por parecer docto, cada cual se ingenia y se esfuerza en invenciones, que sirven de texto a los predicadores, mientras que el Evangelio se calla. Uno dice que la Luna retrocedió cuando la pasión de Cristo, y se interpuso a fin de que la luz del Sol no pudiera bajar a la Tierra; otros que la luz se ocultó por sí misma, razón por la cual este eclipse fué tan sensible para los Españoles y los Indios, como para los Judíos. No tiene Florencia tantos Lapi y Bindi[199] como fábulas se pronuncian durante un año y por todas partes en el púlpito; así es que las ovejas ignorantes vuelven del pasto repletas de viento, sin que les sirva de excusa no haber visto el daño. Cristo no dijo a su primer convento: \\\"Andad y predicad patrañas al mundo,\\\" sino que les dió por base la verdad: y ésta sonó en sus bocas de tal modo, que al combatir para encender la Fe, solamente se valieron del Evangelio como de escudo y lanza. Ahora, para predicar, se abusa de las argucias y bufonadas; con tal de excitar la hilaridad, la cogulla se hincha y no se desea otra cosa. Pero en la punta de esa cogulla anida tal pájaro,[200] que si el vulgo lo viese, no admitiría las indulgencias de aquellos en quienes confía; por las cuales ha crecido tanto la necedad en la Tierra, que sin pedir pruebas de su autenticidad, se agolparía la gente a cualquier promesa de ellas. Con esto engorda el puerco de San Antonio, y engordan otros muchos que son peores que puercos, pagando en moneda sin cuño. Mas, poniendo fin a esta larga digresión, vuelve ya tus ojos hacia la vía recta, de modo que el camino y el tiempo se abrevien. La naturaleza de los ángeles aumenta tanto su número de grado en grado, que no hay palabra ni inteligencia mortal que pueda llegar a significar ese número; y si examinas bien lo que reveló Daniel, verás que en sus millares no se manifiesta un número determinado. La primera luz que ilumina toda la naturaleza angélica penetra en ella de tantos modos cuantos son los esplendores a que se une. Así pues, como el afecto es proporcionado a la intensidad de la visión beatífica, la dulzura del amor es en los ángeles diversamente fervorosa o tibia. Contempla en adelante la altura y la extensión del Poder Eterno; pues ha formado para sí tantos espejos en los que se reparte, quedando siempre uno e indivisible como antes de haberlos creado.\"},{\"heading\":false,\"text\":\"[199] Nombres muy comunes en Florencia.\"},{\"heading\":false,\"text\":\"[200] El demonio.\"}]},{\"title\":\"Paraíso — canto trigesimo\",\"blocks\":[{\"heading\":false,\"text\":\"Acaso arde la hora sexta distante seis mil millas de nosotros, y este mundo inclina ya su sombra casi horizontalmente, cuando el centro del cielo que vemos más profundo empieza a ponerse de modo, que algunas estrellas van perdiéndose de vista desde la Tierra; y a medida que viene adelantando la clarísima sierva del Sol, el cielo apaga de una en una sus luces hasta la más bella. No de otra suerte desapareció poco a poco a mi vista el triunfo de los coros angélicos, que siempre festeja en torno de aquel punto que me deslumbró, pareciéndome contenido en lo mismo que él contiene; por lo cual, no viendo ya nada, esto unido al amor me obligó a volver los ojos hacia Beatriz. Si todo cuanto hasta aquí se ha dicho acerca de ella estuviera reunido en una sola alabanza, sería poco para llenar el objeto. La belleza que en ella vi no sólo está fuera del alcance de nuestra inteligencia, sino que creo con certeza que su Hacedor es el único que la comprende toda. Me confieso vencido por este pasaje de mi poema más de lo que con respecto a otro punto lo fué jamás autor trágico o cómico; porque así como el Sol ofusca la vista más trémula, del mismo modo el recuerdo de la dulce sonrisa paraliza mi mente. Desde el primer día que vi su rostro en esta vida, hasta mi actual contemplación, no se ha interrumpido la continuación de mi canto; pero ahora es preciso que mi poema desista de seguir cantando la belleza de mi Dama, como hace todo artista que llega al último esfuerzo en su arte. Tal cual la dejo para que la anuncie una trompa de mayor sonido que la mía, que conduce al término su difícil tarea, Beatriz repuso con el gesto y la voz de una guía solícita:\"},{\"heading\":false,\"text\":\"--Hemos salido fuera del mayor de los cuerpos celestes, para subir al cielo que es pura luz;[201] luz intelectual, llena de amor, amor de verdadero bien, lleno de gozo; gozo superior a toda dulzura. Aquí verás una y otra milicia del Paraíso, y una de ellas bajo aquel aspecto con que la contemplarás en el juicio final.\"},{\"heading\":false,\"text\":\"[201] Del Primer móvil al Empíreo.\"},{\"heading\":false,\"text\":\"Como súbito relámpago que disipa las potencias visivas, privando al ojo de la facultad de distinguir los mayores objetos, así me circundó una luz resplandeciente, dejándome velado de tal suerte con su fulgor, que nada descubría.\"},{\"heading\":false,\"text\":\"--El Amor que tranquiliza este cielo, acoge siempre con semejante saludo al que entra en él, a fin de disponer al cirio para recibir su llama.\"},{\"heading\":false,\"text\":\"No bien hube oído estas palabras, cuando me sentí elevar de un modo superior a mis fuerzas, y adquirí una nueva vista de tal vigor, que no hay luz alguna tan brillante que no pudieran soportarla mis ojos. Y vi en forma de río una luz áurea, que despedía espléndidos fulgores entre dos orillas adornadas de admirable primavera. De este río salían vivas centellas, que por todas partes llovían sobre las flores, pareciendo rubíes engastados en oro. Después, como embriagadas con aquellos aromas, volvían a sumergirse en el maravilloso raudal; pero si una entraba en él, otra salía.\"},{\"heading\":false,\"text\":\"--El alto deseo que ahora te inflama y estimula para comprender lo que estás viendo, me place tanto más cuanto es más vehemente; pero es preciso que bebas de esa agua antes que sacies tanta sed.\"},{\"heading\":false,\"text\":\"Así me dijo el Sol de mis ojos. Luego añadió:\"},{\"heading\":false,\"text\":\"--El río y los topacios, que entran y salen, y la sonrisa de las hierbas son nada más que sombras y prefacios de la verdad: no es decir que estas cosas sean en sí de difícil comprensión; pues el defecto está en ti, que no tienes aún la vista bastante elevada.\"},{\"heading\":false,\"text\":\"Ningún niño se tira de cabeza tan presuroso al pecho de su madre cuando despierta más tarde de lo acostumbrado, como yo, para mejorar los espejos de mis ojos, me incliné sobre la onda luminosa, que corre a fin de que se perfeccione la vista; y apenas se bañó en ella la extremidad de mis párpados, me pareció que la larga corriente se había vuelto redonda. Después, así como la gente enmascarada parece otra cosa muy distinta en cuanto se despoja de la falsa apariencia bajo la cual se ocultaba, así me pareció que adquirían mayor alegría las flores y las centellas; de modo que vi distintamente las dos cortes del cielo. ¡Oh esplendor de Dios, merced al cual vi el gran triunfo del reino de la verdad! Dame fuerzas para decir cómo lo vi.\"},{\"heading\":false,\"text\":\"Hay allá arriba una luz, que hace visible el Creador a toda criatura que sólo funda su paz en contemplarle; y se extiende en forma circular por tanto espacio, que su circunferencia sería para el Sol un cinturón demasiado anchuroso. Toda su apariencia procede de un rayo reflejado sobre la cumbre del Primer Móvil, que de él adquiere movimiento y potencia; y así como una colina se contempla en el agua que baña su base, cual si quisiera mirarse adornada cuando es más rica de verdor y flores, así, suspendidas en torno, en torno de la luz, vi reflejarse en más de mil gradas todas las almas que desde nuestro mundo han vuelto allá arriba. Y si la última grada concentra en sí tanta luz, ¡cuál no será el esplendor de esta rosa en sus últimas hojas! Mi vista no se perdía en la anchura ni en la elevación de esta rosa, sino que abarcaba toda la cantidad y la calidad de aquella alegría. Allí, el estar cerca o lejos, no da ni quita; porque donde Dios gobierna sin interposición de causas secundarias, no ejerce ninguna acción la ley natural. Hacia el centro de la rosa sempiterna, que se dilata, se eleva gradualmente y exhala un perfume de alabanzas al Sol que allí produce una eterna primavera, me atrajo Beatriz como el que calla al mismo tiempo que quiere hablar, y dijo:\"},{\"heading\":false,\"text\":\"--¡Mira cuán grande es la reunión de blancas estolas! ¡Mira qué gran circuito tiene nuestra ciudad! ¡Mira nuestros escaños tan llenos, que ya son pocos los llamados a ocuparlos! En aquel gran asiento donde tienes los ojos fijos a causa de la corona que está colocada sobre él, antes que tú cenes en estas bodas se sentará el alma de gran Enrique, que será augusta en la Tierra,[202] el cual irá a reformar la Italia antes que se halle preparada para ello. La ciega codicia que os enferma, os ha hecho semejantes al niño que muere de hambre y rechaza a su nodriza. Entonces será prefecto en el foro divino un hombre,[203] que abierta y ocultamente no irá por el mismo camino que aquél; pero poco tiempo le tolerará Dios en su santo cargo; porque será arrojado donde está Simón Mago por sus merecimientos, y hará que el de Alagna[204] se hunda más.\"},{\"heading\":false,\"text\":\"[202] Aquí Dante finge predecir en 1300 la coronación del emperador Enrique VII de Luxemburgo, que tuvo efecto en 1308.\"},{\"heading\":false,\"text\":\"[203] El papa Clemente V.\"},{\"heading\":false,\"text\":\"[204] El papa Bonifacio VIII. (Véase el Infierno, canto XIX.)\"}]},{\"title\":\"Paraíso — canto trigesimoprimero\",\"blocks\":[{\"heading\":false,\"text\":\"En forma, pues, de blanca rosa se ofrecía a mi vista la milicia santa que Cristo con su sangre hizo su esposa; pero la otra, que volando ve y canta la gloria de aquel que la enamora y la bondad que tan excelsa la ha hecho, como un enjambre de abejas, que ora se posa sobre las flores, ora vuelve al sitio donde su trabajo se convierte en dulce miel, descendía a la gran flor que se adorna de tantas hojas, y desde allí se lanzaba de nuevo hacia el punto donde siempre permanece su Amor. Todas estas almas tenían el rostro de llama viva, las alas de oro, y lo restante de tal blancura, que no hay nieve que pueda comparársele. Cuando descendían por la flor de grada en grada, comunicaban a las otras almas la paz y el ardor que ellas adquirían volando; y por más que aquella familia alada se interpusiera entre lo alto y la flor, no impedía la vista ni el esplendor, porque la luz divina penetra en el universo según que éste es digno de ello, de manera que nada puede servirle de obstáculo.\"},{\"heading\":false,\"text\":\"Este reino tranquilo y gozoso, poblado de gente antigua y moderna, tenía todo él la vista y el amor dirigidos hacia un solo punto. ¡Oh trina luz, que centelleando en una sola estrella, regocijas de tal modo la vista de esos espíritus!, mira cuál es aquí abajo nuestra tormenta. Si los bárbaros, procedentes de la región que cubre Hélice diariamente girando con su hijo a quien mira con amor,[205] se quedaban estupefactos al ver a Roma y sus magníficos monumentos, cuando Letrán superaba a todas las obras salidas de manos de los hombres, yo, que acababa de pasar de lo humano a lo divino, del tiempo limitado a lo eterno, y de Florencia a un pueblo justo y santo, ¿de qué estupor no estaría lleno? En verdad que, entregado a tal estupor y a mi gozo, me complacía el no oír ni decir nada. Y como el peregrino que se recrea contemplando el templo que había hecho voto de visitar, y espera, al volver a su país, referir cómo estaba construído, así yo, contemplando la viva luz, paseaba mis miradas por todas las gradas, ya hacia arriba, ya hacia abajo, ya en derredor, y veía rostros que excitaban a la caridad, embellecidos por otras luces y por su sonrisa, y en actitudes adornadas de toda clase de gracia. Mi vista había abarcado por completo la forma general del Paraíso, pero no se había fijado en parte alguna: entonces, poseído de un nuevo deseo, me volví hacia mi Dama para preguntarle sobre algunos puntos que tenían en suspenso mi mente; pero cuando esperaba una cosa, me sucedió otra: creía ver a Beatriz, y vi un anciano[206] vestido como la familia gloriosa. En sus ojos y en sus mejillas estaba esparcida una benigna alegría, y su aspecto era tan dulce como el de un tierno padre.\"},{\"heading\":false,\"text\":\"[205] El Norte, sobre el cual gira constantemente la Osa mayor, junto con su hijo Bootes o Arturo.\"},{\"heading\":false,\"text\":\"[206] Beatriz ha cumplido ya su misión, y desaparece del lado de Dante, sustituyéndole San Bernardo, símbolo de la contemplación y del amor a María, de quien impetra luego que alcance para el Poeta la gracia de ver a Dios; tal vez porque para esto no basta la ciencia teológica, y se necesita de la Gracia.\"},{\"heading\":false,\"text\":\"--Y ella ¿dónde está?--dije al momento.\"},{\"heading\":false,\"text\":\"A lo cual contestó él:\"},{\"heading\":false,\"text\":\"--Beatriz me ha enviado desde mi asiento para poner fin a tu deseo; y si miras el tercer círculo a partir de la grada superior, la verás ocupar el trono en que la han colocado sus méritos.\"},{\"heading\":false,\"text\":\"Sin responder levanté los ojos, y la vi formándose una corona de los eternos rayos que de sí reflejaba. El ojo del que estuviese en lo profundo del mar no distaría tanto de la región más elevada donde truena, como distaban de Beatriz los míos; pero nada importaba, porque su imagen descendía hasta mí sin interposición de otro cuerpo.\"},{\"heading\":false,\"text\":\"--¡Oh mujer, en quien vive mi esperanza, y que consentiste, por mi salvación, en dejar tus huellas en el Infierno! Si he visto tantas cosas, a tu bondad y a tu poder debo esta gracia y la fuerza que me ha sido necesaria. Tú, desde la esclavitud, me has conducido a la libertad por todas las vías y por todos los medios que para hacerlo han estado a tu alcance. Consérvame tus magníficos dones, a fin de que mi alma, que sanaste, se separe de su cuerpo siendo agradable a tus ojos.\"},{\"heading\":false,\"text\":\"Así oré; y aquella que tan lejana parecía, se sonrió y me miró, volviéndose después hacia la eterna fuente.[207] El santo Anciano me dijo:\"},{\"heading\":false,\"text\":\"[207] Dios, eterna fuente de bien.\"},{\"heading\":false,\"text\":\"--A fin de que lleves a feliz término tu viaje, para lo cual me han movido el ruego y el amor santo, vuela con los ojos por este jardín; pues mirándolo se avivará más tu vista para subir hasta el rayo divino. Y la Reina del Cielo, por quien ardo enteramente en amor, nos concederá todas las gracias, porque yo soy su fiel Bernardo.\"},{\"heading\":false,\"text\":\"Como aquel que acaso viene de Croacia para ver nuestra Verónica, y no se cansa de contemplarla a causa de su antigua fama, antes bien dice para sí mientras se la enseñan: \\\"Señor mío Jesucristo, Dios verdadero, ¿era tal vuestro rostro?,\\\" lo mismo estaba yo mirando la viva caridad de aquél, que entregado a la contemplación, gustó en el mundo las delicias de que ahora goza.\"},{\"heading\":false,\"text\":\"--Hijo de la gracia--empezó a decirme--, no podrás conocer esta existencia dichosa, mientras fijes los ojos solamente aquí abajo. Ve mirando los círculos hasta el más remoto, a fin de que veas el trono de la Reina a quien está sometido y consagrado este reino.\"},{\"heading\":false,\"text\":\"Levanté los ojos; y así como por la mañana la parte oriental del horizonte excede en claridad a aquella por donde el Sol se pone, del mismo modo, y dirigiendo la vista como el que va del fondo de un valle a la cumbre de un monte, vi en el más elevado círculo una parte del mismo que sobrepujaba en claridad a todas las otras; y así como allí donde se espera el carro que tan mal guió Faetón,[208] más se inflama el cielo y fuera de aquel punto va perdiendo la luz su viveza, de igual suerte aquella pacífica oriflama[209] brillaba más en su centro, disminuyéndose gradualmente el resplandor en todas las demás partes. En aquel centro vi más de mil ángeles que la festejaban con las alas desplegadas, diferente cada cual en su esplendor y en su actitud. Ante sus juegos y sus cantos vi sonreír una beldad, que infundía el contento en los ojos de los demás santos. Aun cuando tuviera tantos recursos para decir como para imaginar, no me atrevería a expresar la mínima parte de sus delicias.\"},{\"heading\":false,\"text\":\"[208] El carro del Sol.\"},{\"heading\":false,\"text\":\"[209] La Virgen María.\"},{\"heading\":false,\"text\":\"Cuando Bernardo vió mis ojos atentos y fijos en el objeto de su ferviente amor, volvió los suyos hacia él con tanto afecto, que infundió en los míos más ardor para contemplarlo.\"}]},{\"title\":\"Paraíso — canto trigesimosegundo\",\"blocks\":[{\"heading\":false,\"text\":\"Atento a su dicha, aquel contemplador asumió espontáneamente en sí el cargo de maestro y empezó por estas santas palabras:\"},{\"heading\":false,\"text\":\"--La herida que María restañó y curó fué abierta y enconada por aquella mujer tan hermosa que está a sus pies.[210] Debajo de ésta, en el orden que forman los terceros puestos, se sientan, como ves, Raquel y Beatriz.[211] Sara, Rebeca, Judith, y la bisabuela[212] del Cantor que en medio del dolor producido por su falta dijo \\\"Miserere mei,\\\" puedes verlas sucederse de grado en grado, descendiendo, a medida que en la rosa te las voy nombrando de hoja en hoja. Y desde la séptima grada para abajo, como desde la más alta a la misma grada, se suceden las Hebreas, dividiendo todas las hojas de la flor; porque aquéllas son como un recto muro, que comparte los sagrados escalones, según como se fijó en Cristo la mirada de la fe. En esa parte, en que la flor está provista de todas sus hojas, se sientan los que creyeron en la venida de Jesucristo; y en la otra, en que los semicírculos se ven interrumpidos por algunos huecos, se sientan los que creyeron en El después de haber venido; y así como en esa parte el glorioso trono de la Señora del cielo y los otros escaños inferiores forman tan gran separación, así en la opuesta está el trono del gran Juan que, siempre santo, sufrió la soledad y el martirio, y el Infierno después durante dos años;[213] y así también debajo de él, formando a propósito igual separación, está el de Francisco; bajo éste el de Benito, bajo Benito Agustín y otros varios, descendiendo de igual modo hasta aquí de círculo en círculo. Admira, pues, la elevada Providencia divina; porque uno y otro aspecto de la Fe llenarán por igual este jardín. Y sabe que desde la grada que corta por mitad ambas filas hasta abajo, nadie se sienta por su propio mérito, sino por el que contrajo otro, y con ciertas condiciones; porque todos ellos son espíritus desprendidos de la Tierra antes que estuviesen dotados de criterio para elegir la verdad. Fácil te será cerciorarte de ello por sus rostros y también por sus voces infantiles, si los miras y los escuchas bien. Ahora dudas, y dudando guardas silencio; pero yo soltaré las fuertes ligaduras con que te estrechan tus sutiles pensamientos. En toda la extensión de este reino no puede tener cabida un asiento dado por casualidad, como tampoco caben la tristeza, la sed, ni el hambre; pues todo cuanto ves se halla establecido por eterna ley, de modo que aquí cada cosa viene justa como anillo al dedo. Por lo tanto, estas almas apresuradas a la verdadera vida no son aquí \\\"sine causa\\\" más o menos excelentes entre sí. El Rey por quien este reino reposa en tanto amor y deleite, que ninguna voluntad se atreve a desear más, creando todas las almas bajo su dichoso aspecto, las dota según quiere de más o menos gracia: en cuanto a esto baste conocer el efecto; lo cual se demuestra expresa y claramente por la Sagrada Escritura en aquellos gemelos a quienes agitó la ira en el vientre de su madre.[214] Por lo tanto, es preciso que la altísima luz corone de su gloria a los espíritus según sea el color de los cabellos de tal gracia. Así pues, sin consideración al mérito de sus obras, se hallan ésos colocados en diferentes grados, distinguiéndose tan sólo por su penetración primitiva. En los primeros siglos bastaba ciertamente para salvarse tener, junto con la inocencia, la fe de los padres. Transcurridas las primeras edades, fué menester que los varones todavía inocentes adquiriesen la virtud por medio de la circuncisión; pero cuando llegó el tiempo de la Gracia, toda aquella inocencia debió permanecer en el Limbo, si no había recibido el perfecto bautismo de Cristo. Contempla ahora la faz que más se asemeja a la de Cristo, pues sólo su resplandor podrá disponerte a ver a Cristo.\"},{\"heading\":false,\"text\":\"[210] Eva.\"},{\"heading\":false,\"text\":\"[211] Beatriz es la imagen de la Teología, y Raquel de la vida contemplativa.\"},{\"heading\":false,\"text\":\"[212] Ruth, bisabuela de David.\"},{\"heading\":false,\"text\":\"[213] San Juan Bautista estuvo en el Limbo casi dos años, porque murió antes que Jesucristo.\"},{\"heading\":false,\"text\":\"[214] Esaú y Jacob.\"},{\"heading\":false,\"text\":\"Vi llover sobre ella tanta alegría, llevada por los santos espíritus, creados para volar por aquella altura, que todo cuanto antes había visto no me había causado tal admiración, ni me había mostrado mayor semejanza con Dios. Y aquel amor[215] que fué el primero en descender cantando \\\"Ave, María, gratia plena,\\\" extendió sus alas delante de ella. A tan divina cantinela respondió por todas partes la corte bienaventurada, de tal modo que cada espíritu pareció más radiante.\"},{\"heading\":false,\"text\":\"[215] El arcángel San Gabriel.\"},{\"heading\":false,\"text\":\"--¡Oh Santo Padre, que por mí te dignas estar aquí abajo, dejando el dulce sitio donde te sientas por toda una eternidad! ¿Qué ángel es ese, que con tanto gozo mira los ojos de nuestra Reina, y tan enamorado está que parece de fuego?\"},{\"heading\":false,\"text\":\"Con estas palabras recurrí nuevamente a la enseñanza de aquel que se embellecía con las bellezas de María, como a los rayos del Sol se embellece la estrella matutina. Y él me respondió:\"},{\"heading\":false,\"text\":\"--Toda la confianza y la gracia que pueden caber en un ángel y en un alma, se encuentran en él, y así queremos que sea; porque es el que llevó la palma a María, cuando el Hijo de Dios quiso cargar con nuestro peso. Pero sigue ahora con la vista según yo vaya hablando, y fija la atención en los grandes patricios de este imperio justísimo y piadoso. Aquellos dos que ves sentados allá arriba, más felices por estar sumamente próximos a la Augusta Señora, son casi dos raíces de esta rosa. El que está a la izquierda es el padre, cuyo atrevido paladar fué causa de que la especie humana probara tanta amargura.[216] Contempla a la derecha al anciano padre de la santa Iglesia, a quien Cristo confió las llaves de esta encantadora flor:[217] a su lado se sienta aquel que vió, antes de morir, todos los tiempos calamitosos que debía atravesar la bella esposa que fué conquistada con la lanza y los clavos;[218] y próximo al otro, aquel Jefe bajo cuyas órdenes vivió de maná la nación ingrata, voluble y obstinada.[219] Mira sentada a Ana frente a Pedro, contemplando a su hija con tal arrobamiento, que ni aun al cantar \\\"Hosanna\\\" separa de ella los ojos: y frente al mayor Padre de familia se sienta Lucía, que envió a tu Dama en tu socorro, cuando cerraste los párpados al borde del abismo. Mas, puesto que huye el tiempo que te adormece, haremos punto aquí, como un buen sastre, que según el paño con que cuenta, así hace el traje y elevaremos los ojos hacia el primer Amor, de modo que, mirándole, penetres en su fulgor cuanto te sea posible. Sin embargo, a fin de que al mover tus alas no retrocedas acaso creyendo adelantar, es preciso pedir con ruegos la gracia que necesitas, e impetrarla de aquella que puede ayudarte: sígueme, pues, con el afecto, de modo que tu corazón acompañe a mis palabras.\"},{\"heading\":false,\"text\":\"[216] Adán, cabeza del Antiguo Testamento.\"},{\"heading\":false,\"text\":\"[217] San Pedro, cabeza del Nuevo Testamento.\"},{\"heading\":false,\"text\":\"[218] San Juan Evangelista.\"},{\"heading\":false,\"text\":\"[219] Moisés, que está cerca de Adán.\"},{\"heading\":false,\"text\":\"Y comenzó a decir esta santa oración:\"}]},{\"title\":\"Paraíso — canto trigesimotercio\",\"blocks\":[{\"heading\":false,\"text\":\"\\\"Virgen madre, hija de tu hijo, la más humilde al par que la más alta de todas las criaturas, término fijo de la voluntad eterna, tú eres la que has ennoblecido de tal suerte la humana naturaleza, que su Hacedor no se desdeñó de convertirse en su propia obra. En tu seno se inflamó el amor cuyo calor ha hecho germinar esta flor en la paz eterna. Eres aquí para nosotros meridiano Sol de caridad, y abajo para los mortales vivo manantial de esperanza. Eres tan grande, señora, y tanto vales, que todo el que desea alcanzar alguna gracia y no recurre a ti, quiere que su deseo vuele sin alas. Tu benignidad no sólo socorre al que te implora, sino que muchas veces se anticipa espontáneamente a la súplica. En ti se reúnen la misericordia, la piedad, la magnificencia, y todo cuanto bueno existe en la criatura. Este, pues, que desde la más profunda laguna del universo hasta aquí ha visto una a una todas las existencias espirituales, te suplica le concedas la gracia de adquirir tal virtud, que pueda elevarse con los ojos hasta la salud suprema. Y yo, que nunca he deseado ver más de lo que deseo que él vea, te dirijo todos mis ruegos, y te suplico que no sean vanos, a fin de que disipes con los tuyos todas las nieblas procedentes de su condición mortal, de suerte que pueda contemplar abiertamente el sumo placer. Te ruego además, ¡oh Reina, que puedes cuanto quieres!, que conserves puros sus afectos después de tanto ver; que tu custodia triunfe de los impulsos de las pasiones humanas: mira a Beatriz cómo junta sus manos con todos los bienaventurados para unir sus plegarias a las mías.\\\"\"},{\"heading\":false,\"text\":\"Los ojos que Dios ama y venera,[220] fijos en el que por mí oraba, me demostraron cuán gratos le son los devotos ruegos. Después se elevaron hacia la Luz eterna en la cual no es creíble que la mirada de criatura alguna pueda fijarse tan abiertamente. Y yo, que me acercaba al fin de todo anhelo, puse término en mí, como debía, al ardor del deseo. Bernardo sonriéndose me indicaba que mirase hacia arriba; pero yo había hecho ya por mí mismo lo que él quería: porque mi vista, adquiriendo más y más pureza y claridad, penetraba gradualmente en la alta luz que tiene en sí misma la verdad de su existencia. Desde aquel instante, lo que vi excede a todo humano lenguaje, que es impotente para expresar tal visión, y la memoria se rinde a tanta grandeza. Como el que ve soñando, y después del sueño conserva impresa la sensación que ha recibido, sin que le quede otra cosa en la mente, así estoy yo ahora; pues casi ha cesado del todo mi visión, y aun destila en mi pecho la dulzura que nació de ella. Del mismo modo ante el Sol pierde su forma la nieve, y así también se dispersaban al viento en las ligeras hojas las sentencias de la Sibila.\"},{\"heading\":false,\"text\":\"[220] Los ojos de la Virgen María.\"},{\"heading\":false,\"text\":\"¡Oh luz suprema que te elevas tanto sobre los pensamientos de los mortales! Presta a mi mente algo de lo que parecías, y haz que mi lengua sea tan potente, que pueda dejar a lo menos un destello de tu gloria a las generaciones venideras; pues si se muestra algún tanto a mi memoria y resuena lo mínimo en mis versos, se podrá concebir más tu victoria.\"},{\"heading\":false,\"text\":\"Por la intensidad del vivo rayo que soporté sin cegar, creo que me habría perdido, si hubiera separado de él mis ojos; y recuerdo que por esto fuí tan osado para sostenerlo, que uní mi mirada con el Poder infinito. ¡Oh gracia abundante, por la cual tuve atrevimiento para fijar mis ojos en la Luz eterna hasta tanto que consumí toda mi fuerza visiva! En su profundidad vi que se contiene ligado con vínculos de amor en un volumen todo cuanto hay esparcido por el universo: substancias, accidentes y sus cualidades, unido todo de tal manera, que cuanto digo no es más que una pálida luz. Creo que vi la forma universal de este nudo, porque, recordando estas cosas, me siento poseído de mayor alegría. Un solo punto me causa mayor olvido, que el que han causado veinticinco siglos transcurridos desde la empresa que hizo a Neptuno admirarse de la sombra de Argos. Así es que mi mente en suspenso miraba fija, inmóvil y atenta, y continuaba mirando con ardor creciente. El efecto de esta luz es tal, que no es posible consentir jamás en separarse de ella para contemplar otra cosa; porque el bien, que es objeto de la voluntad, se encierra todo en ella, y fuera de ella es defectuoso lo que allí perfecto. Desde este punto, a causa de lo poco que recuerdo, mis palabras serán más breves que las de un niño cuya lengua se baña todavía en la leche materna. No porque hubiese más de un simple aspecto en la viva luz que yo miraba, pues siempre es tal como antes era, sino porque mi vista se avaloraba contemplándola, su apariencia única se me representaba en otra forma según iba alterándose mi aptitud visiva. En la profunda y clara substancia de la alta luz se me aparecieron tres círculos de tres colores y de una sola dimensión:[221] el uno parecía reflejado por otro como Iris por Iris, y el tercero parecía un fuego procedente de ambos por igual. ¡Ah!, ¡cuán escasa y débil es la lengua para decir mi concepto! Y éste lo es tanto, comparado a lo que vi, que la palabra \\\"poco\\\" no basta para expresar su pequeñez.\"},{\"heading\":false,\"text\":\"[221] La Santísima Trinidad.\"},{\"heading\":false,\"text\":\"¡Oh Luz eterna, que en ti solamente resides, que sola te comprendes, y que siendo por ti a la vez inteligente y entendida, te amas y te complaces en ti misma! Aquel de tus círculos, que parecía proceder de ti como el rayo reflejado procede del rayo directo, cuando mis ojos lo contemplaron en torno, parecióme que dentro de sí con su propio color representaba nuestra efigie, por lo cual mi vista estaba fija atentamente en él. Como el geómetra que se dedica con todo empeño a medir el círculo, y por más que piensa no encuentra el principio que necesita, lo mismo estaba yo ante aquella nueva imagen. Yo quería ver cómo correspondía la efigie al círculo, y cómo a él estaba unida; pero no alcanzaban a tanto mis propias alas, si no hubiera sido iluminada mi mente por un resplandor, merced al cual fué satisfecho su deseo.\"},{\"heading\":false,\"text\":\"Aquí faltó la fuerza a mi elevada fantasía; pero ya eran movidos mi deseo y mi voluntad, como rueda cuyas partes giran todas igualmente, por el Amor que mueve el Sol y las demás estrellas.\"}]}]', 'es', 'https://www.gutenberg.org/ebooks/57303', '{}');
INSERT INTO libros (id, titulo, autor, genero, cover, secciones, idioma, fuente, introducciones) VALUES (60198, 'Fuente Ovejuna', 'Lope de Vega', 'teatro', 'https://www.gutenberg.org/cache/epub/60198/pg60198.cover.medium.jpg', '[{\"title\":\"Acto Primero\",\"blocks\":[{\"heading\":false,\"text\":\"(_Salen el_ COMENDADOR, FLORES _y_ ORTUÑO, _criados._)\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¿Sabe el maestre que estoy en la villa?\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Ya lo sabe.\"},{\"heading\":false,\"text\":\"ORTUÑO\"},{\"heading\":false,\"text\":\"Está, con la edad, más grave.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Y ¿sabe también que soy Fernán Gómez de Guzmán?\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Es muchacho, no te asombre.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Cuando no sepa mi nombre, ¿no le sabrá el que me dan de comendador mayor?\"},{\"heading\":false,\"text\":\"ORTUÑO\"},{\"heading\":false,\"text\":\"No falta quien le aconseje que de ser cortés se aleje.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Conquistará poco amor. Es llave la cortesía para abrir la voluntad; y para la enemistad la necia descortesía.\"},{\"heading\":false,\"text\":\"ORTUÑO\"},{\"heading\":false,\"text\":\"Si supiese un descortés cómo lo aborrecen todos --y querrían de mil modos poner la boca a sus pies--, antes que serlo ninguno, se dejaría morir.\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"¡Qué cansado es de sufrir! ¡Qué áspero y qué importuno! Llaman la descortesía necedad en los iguales, porque es entre desiguales linaje de tiranía. Aquí no te toca nada: que un muchacho aun no ha llegado a saber qué es ser amado.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"La obligación de la espada que se ciñó, el mismo día que la cruz de Calatrava le cubrió el pecho, bastaba para aprender cortesía.\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Si te han puesto mal con él, presto le conocerás.\"},{\"heading\":false,\"text\":\"ORTUÑO\"},{\"heading\":false,\"text\":\"Vuélvete, si en duda estás.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Quiero ver lo que hay en él.\"},{\"heading\":false,\"text\":\"(_Sale el_ MAESTRE DE CALATRAVA _y acompañamiento._)\"},{\"heading\":false,\"text\":\"MAESTRE\"},{\"heading\":false,\"text\":\"Perdonad, por vida mía, Fernán Gómez de Guzmán; que agora nueva me dan que en la villa estáis.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Tenía muy justa queja de vos; que el amor y la crianza me daban más confianza, por ser, cual somos los dos, vos maestre en Calatrava, yo vuestro comendador y muy vuestro servidor.\"},{\"heading\":false,\"text\":\"MAESTRE\"},{\"heading\":false,\"text\":\"Seguro[1], Fernando, estaba de vuestra buena venida. Quiero volveros a dar los brazos.\"},{\"heading\":false,\"text\":\"[1] _Seguro_, descuidado, ajeno.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Debéisme honrar; que he puesto por vos la vida entre diferencias tantas, hasta suplir vuestra edad el pontífice.\"},{\"heading\":false,\"text\":\"MAESTRE\"},{\"heading\":false,\"text\":\"Es verdad. Y por las señales santas que a los dos cruzan el pecho, que os lo pago en estimaros, y como a mi padre honraros.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"De vos estoy satisfecho.\"},{\"heading\":false,\"text\":\"MAESTRE\"},{\"heading\":false,\"text\":\"¿Qué hay de guerra por allá?\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Estad atento, y sabréis, la obligación que tenéis.\"},{\"heading\":false,\"text\":\"MAESTRE\"},{\"heading\":false,\"text\":\"Decid que ya lo estoy, ya.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Gran maestre don Rodrigo Téllez Girón, que a tan alto lugar os trajo el valor de aquel vuestro padre claro, que, de ocho años, en vos renunció su maestrazgo, que después por más seguro juraron y confirmaron reyes y comendadores, dando el pontífice santo Pío segundo sus bulas, y después las suyas Paulo para que don Juan Pacheco, gran maestre de Santiago, fuese vuestro coadjutor: ya que es muerto, y que os han dado el gobierno sólo a vos, aunque de tan pocos años, advertid que es honra vuestra seguir en aqueste caso la parte de vuestros deudos; porque muerto Enrique cuarto, quieren que al rey don Alonso de Portugal, que ha heredado, por su mujer, a Castilla, obedezcan sus vasallos; que aunque pretende[2] lo mismo, por Isabel, don Fernando, gran príncipe de Aragón, no con derecho tan claro a vuestros deudos; que, en fin, no presumen que hay engaño en la sucesión de Juana[3], a quien vuestro primo hermano tiene agora en su poder. Y así vengo a aconsejaros que juntéis los caballeros de Calatrava en Almagro, y a Ciudad Real toméis, que divide como paso a Andalucía y Castilla, para mirarlas a entrambas[4]. Poca gente es menester, porque tienen por soldados solamente sus vecinos y algunos pocos hidalgos, que defienden a Isabel y llaman rey a Fernando. Será bien que deis asombro, Rodrigo, aunque niño, a cuantos dicen que es grande esa cruz para vuestros hombros flacos. Mirad los condes de Urueña, de quien venís, que mostrando os están desde la fama los laureles que ganaron; los marqueses de Villena, y otros capitanes, tantos, que las alas de la fama apenas pueden llevarlos. Sacad esa blanca espada, que habéis de hacer, peleando, tan roja como la cruz; porque no podré llamaros maestre de la cruz roja que tenéis al pecho, en tanto que tenéis la blanca espada; que una al pecho y otra al lado, entrambas han de ser rojas; y vos, Girón soberano, capa del templo inmortal de vuestros claros pasados.\"},{\"heading\":false,\"text\":\"[2] _El original_, pretenden.\"},{\"heading\":false,\"text\":\"[3] Juana la Beltraneja, hija, según se supuso, de D. Beltrán de la Cueva, privado del rey Enrique IV y amante de la reina.\"},{\"heading\":false,\"text\":\"[4] _El original_, entrambos.\"},{\"heading\":false,\"text\":\"MAESTRE\"},{\"heading\":false,\"text\":\"Fernán Gómez, estad cierto que en esta parcialidad, porque veo que es verdad, con mis deudos me concierto. Y si importa, como paso, a Ciudad Real mi intento, veréis que como violento rayo sus muros abraso. No porque es muerto mi tío, piensen de mis pocos años los propios y los extraños que murió con él mi brío. Sacaré la blanca espada, para que quede su luz de la color de la cruz, de roja sangre bañada. Vos, ¿adónde residís? ¿Tenéis algunos soldados?\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Poco, pero mis criados; que si dellos os servís, pelearán como leones. Ya veis que en Fuente Ovejuna hay gente humilde, y alguna no enseñada en escuadrones, sino en campos y labranzas.\"},{\"heading\":false,\"text\":\"MAESTRE\"},{\"heading\":false,\"text\":\"¿Allí residís?\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Allí de mi encomienda escogí casa entre aquestas mudanzas. Vuestra gente se registre; que no quedará vasallo.\"},{\"heading\":false,\"text\":\"MAESTRE\"},{\"heading\":false,\"text\":\"Hoy me veréis a caballo, poner la lanza en el ristre.\"},{\"heading\":false,\"text\":\"(_Vanse, y salen_ PASCUALA _y_ LAURENCIA.)\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¡Mas que nunca acá volviera!\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Pues a la he que pensé que cuando te lo conté, más pesadumbre te diera.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¡Plega al cielo que jamás le vea en Fuente Ovejuna!\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Yo, Laurencia, he visto alguna tan brava, y pienso que más; y tenía el corazón brando como una manteca.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Pues ¿hay encina tan seca como esta mi condición?\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Anda ya; que nadie diga: de esta agua no beberé.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¡Voto al sol que lo diré, aunque el mundo me desdiga! ¿A qué efeto fuera bueno querer a Fernando yo? ¿Casarme con él?\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"No.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Luego la infamia condeno. ¡Cuántas mozas en la villa, del comendador fiadas, andan ya descalabradas!\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Tendré yo por maravilla que te escapes de su mano.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Pues en vano es lo que ves, porque ha que me sigue un mes, y todo, Pascuala, en vano. Aquel Flores, su alcahuete, y Ortuño, aquel socarrón, me mostraron un jubón, una sarta y un copete. Dijéronme tantas cosas de Fernando, su señor, que me pusieron temor; mas no serán poderosas para contrastar mi pecho.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"¿Dónde te hablaron?\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Allá en el arroyo, y habrá seis días.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Y yo sospecho que te han de engañar, Laurencia.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¿A mí?\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Que no, sino al cura.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Soy, aunque polla, muy dura yo para su reverencia. Pardiez, más precio poner, Pascuala de madrugada, un pedazo de lunada[5] al huego para comer, con tanto zalacatón[6] de una rosca que yo amaso, y hurtar a mi madre un vaso del pegado canjilón[7]; y más precio al mediodía ver la vaca entre las coles, haciendo mil caracoles con espumosa armonía; y concertar, si el camino me ha llegado a causar pena, casar una berenjena con otro tanto tocino; y después un pasa-tarde, mientras la cena se aliña, de una cuerda de mi viña, que Dios de pedrisco guarde; y cenar un salpicón con su aceite y su pimienta, y irme a la cama contenta, y al «inducas tentación» rezalle mis devociones, que cuantas raposerías, con su amor y sus porfías, tienen estos bellacones; porque todo su cuidado, después de darnos disgusto, es anochecer con gusto y amanecer con enfado.\"},{\"heading\":false,\"text\":\"[5] _Lunada_, pernil.\"},{\"heading\":false,\"text\":\"[6] _Zalacatón_, trozo de pan.\"},{\"heading\":false,\"text\":\"[7] Vasija untada de pez.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Tienes, Laurencia, razón; que en dejando de querer, más ingratos suelen ser que al villano el gorrión. En el invierno, que el frío tiene los campos helados, decienden de los tejados, diciéndole «tío, tío», hasta llegar a comer las migajas de la mesa; mas luego que el frío cesa, y el campo ven florecer, no bajan diciendo «tío», del beneficio olvidados, mas saltando en los tejados, dicen: «judío, judío». Pues tales los hombres son: cuando nos han menester somos su vida, su ser, su alma, su corazón; pero pasadas las ascuas, las tías somos judías, y en vez de llamarnos tías, anda el nombre de las pascuas[8].\"},{\"heading\":false,\"text\":\"[8] _Nombre de las pascuas_, «putas, bellacas, alcahuetas». (Correas, _Vocabulario._)\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"No fiarse de ninguno.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Lo mismo digo, Laurencia.\"},{\"heading\":false,\"text\":\"(_Salen_ MENGO _y_ BARRILDO _y_ FRONDOSO.)\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"En aquesta diferencia andas, Barrildo, importuno.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"A lo menos aquí está quien nos dirá lo más cierto.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Pues hagamos un concierto antes que lleguéis allá, y es, que si juzgan por mí, me dé cada cual la prenda, precio de aquesta contienda.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Desde aquí digo que sí. Mas si pierdes, ¿qué darás?\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Daré mi rabel de boj, que vale más que una troj, porque yo le estimo en más.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Soy contento.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Pues lleguemos. Dios os guarde, hermosas damas.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¿Damas, Frondoso, nos llamas?\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Andar al uso queremos: al bachiller, licenciado; al ciego, tuerto; al bisojo, bizco; resentido, al cojo, y buen hombre al descuidado. Al ignorante, sesudo; al mal galán, soldadesca; a la boca grande, fresca, y al ojo pequeño, agudo. Al pleitista, diligente; gracioso, al entremetido[9]; al hablador, entendido, y al insufrible, valiente. Al cobarde, para poco; al atrevido, bizarro; compañero, al que es un jarro, y desenfadado, al loco. Gravedad, al descontento; a la calva, autoridad; donaire, a la necedad, y al pie grande, buen cimiento. Al buboso, resfriado; comedido, al arrogante; al ingenioso, constante; al corcovado, cargado. Esto [al] llamaros imito, damas, sin pasar de aquí; porque fuera hablar así proceder en infinito.\"},{\"heading\":false,\"text\":\"[9] _El original_, al gracioso, entremetido.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Allá en la ciudad, Frondoso, llámase por cortesía de esa suerte; y a fe mía, que hay otro más riguroso y peor vocabulario en las lenguas descorteses.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Querría que lo dijeses.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Es todo a esotro contrario: al hombre grave, enfadoso; venturoso, al descompuesto[10]; melancólico, al compuesto, y al que reprehende, odioso. Importuno al que aconseja; al liberal, moscatel[11]; al justiciero, cruel, y al que es piadoso, madeja[12]. Al que es constante, villano; al que es cortés, lisonjero; hipócrita, al limosnero, y pretendiente, al cristiano. Al justo mérito, dicha; a la verdad, imprudencia; cobardía, a la paciencia, y culpa, a lo que es desdicha. Necia, a la mujer honesta; mal hecha, a la hermosa y casta, y a la honrada... Pero basta; que esto basta por respuesta.\"},{\"heading\":false,\"text\":\"[10] _Descompuesto_, audaz, atrevido.\"},{\"heading\":false,\"text\":\"[11] _Moscatel_, hombre pesado e importuno. _El original_, liberal, al moscatel.\"},{\"heading\":false,\"text\":\"[12] _Madeja_, hombre flojo y dejado.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Digo que eres el dimuño.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Soncas[13] que lo dice mal.\"},{\"heading\":false,\"text\":\"[13] _Soncas_, a fe, en verdad.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Apostaré que la sal la echó el cura con el puño.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¿Qué contienda os ha traído si no es que mal lo entendí?\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Oye, por tu vida.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Di.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Préstame, Laurencia, oído.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Como prestado, y aun dado. Desde agora os doy el mío.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"En tu discreción confío.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¿Qué es lo que habéis apostado?\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Yo y Barrildo contra Mengo.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¿Qué dice Mengo?\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Una cosa que, siendo cierta y forzosa, la niega.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"A negarla vengo, porque yo sé que es verdad.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¿Qué dice?\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Que no hay amor.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Generalmente, es rigor.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Es rigor y es necedad. Sin amor, no se pudiera ni aun el mundo conservar.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Yo no sé filosofar; leer, ¡ojalá supiera! Pero si los elementos en discordia eterna viven, y de los mismos reciben nuestros cuerpos alimentos, cólera y melancolía, flema y sangre, claro está.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"El mundo de acá y de allá, Mengo, todo es armonía. Armonía es puro amor, porque el amor es concierto.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Del natural, os advierto que yo no niego el valor. Amor hay, y el que entre sí gobierna todas las cosas, correspondencias forzosas de cuanto se mira aquí; y yo jamás he negado que cada cual tiene amor correspondiente a su humor, que le conserva en su estado. Mi mano al golpe que viene mi cara defenderá; mi pie, huyendo, estorbará el daño que el cuerpo tiene. Cerraránse mis pestañas si al ojo le viene mal, porque es amor natural.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Pues ¿de qué nos desengañas?\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"De que nadie tiene amor mas que a su misma persona.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Tú mientes, Mengo, y perdona; porque ¿es [mentira][14] el rigor con que un hombre a una mujer, o un animal quiere y ama su semejante?\"},{\"heading\":false,\"text\":\"[14] _El original_, materia.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Eso llama amor propio, y no querer. ¿Qué es amor?\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Es un deseo de hermosura.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Esa hermosura ¿por qué el amor la procura?\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Para gozarla.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Eso creo. Pues ese gusto que intenta, ¿no es para él mismo?\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Es así.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Luego, ¿por quererse a sí busca el bien que le contenta?\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Es verdad.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Pues de ese modo no hay amor, sino el que digo, que por mi gusto le sigo, y quiero dármele en todo.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Dijo el cura del lugar cierto día en el sermón que había cierto Platón que nos enseñaba a amar; que éste amaba el alma sola y la virtud de lo amado.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"En materia habéis entrado que, por ventura, acrisola los caletres de los sabios en sus academias y escuelas.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Muy bien dice, y no te muelas, en persuadir sus agravios. Da gracias, Mengo, a los cielos, que te hicieron sin amor.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"¿Amas tú?\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Mi propio honor.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Dios te castigue con celos.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"¿Quién gana?\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Con la quistión podéis ir al sacristán, porque él o el cura os darán bastante satisfación. Laurencia no quiere bien, yo tengo poca experiencia. ¿Cómo daremos sentencia?\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"¿Qué mayor que ese desdén?\"},{\"heading\":false,\"text\":\"(_Sale_ FLORES.)\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Dios guarde a la buena gente.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Este es del comendador criado.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¡Gentil azor! ¿De adónde bueno, pariente?\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"¿No me veis a lo soldado?\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¿Viene don Fernando acá?\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"La guerra se acaba ya, puesto que[15] nos ha costado alguna sangre y amigos.\"},{\"heading\":false,\"text\":\"[15] _Puesto que_, aunque.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Contadnos cómo pasó.\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"¿Quién lo dirá como yo, siendo mis ojos testigos? Para emprender la jornada de esta ciudad, que ya tiene nombre de Ciudad-Real, juntó el gallardo maestre dos mil lucidos infantes de sus vasallos valientes y trecientos de a caballo de seglares y de freiles; porque la cruz roja obliga cuantos al pecho la tienen, aunque sean de orden sacro; mas contra moros, se entiende. Salió el muchacho bizarro con una casaca verde, bordada de cifras de oro, que sólo los brazaletes por las mangas descubrían, que seis alamares prenden. Un corpulento bridón, rucio rodado, que al Betis bebió el agua, y en su orilla despuntó la grama fértil; el codón labrado en cintas de ante, y el rizo copete cogido en blancas lazadas, que con las moscas de nieve que bañan la blanca piel iguales labores teje. A su lado Fernán Gómez, vuestro señor, en un fuerte melado, de negros cabos, puesto que con blanco bebe[16]. Sobre turca jacerina, peto y espaldar luciente, con naranjada las saca (?), que de oro y perlas guarnece. El morrión, que coronado con blancas plumas, parece que del color naranjado aquellos azares vierte; ceñida al brazo una liga roja y blanca, con que mueve un fresno entero por lanza, que hasta en Granada le temen. La ciudad se puso en arma; dicen que salir no quieren de la corona real, y el patrimonio defienden. Entróla bien resistida, y el maestre a los rebeldes y a los que entonces trataron su honor injuriosamente mandó cortar las cabezas, y a los de la baja plebe, con mordazas en la boca, azotar públicamente. Queda en ella tan temido y tan amado, que creen que quien en tan pocos años pelea, castiga y vence, ha de ser en otra edad rayo del Africa fértil, que tantas lunas azules a su roja cruz sujete. Al comendador y a todos ha hecho tantas mercedes, que el saco de la ciudad el de su hacienda parece. Mas ya la música suena: recebilde alegremente, que al triunfo, las voluntades son los mejores laureles.\"},{\"heading\":false,\"text\":\"[16] «Frase que se entiende de los caballos, para dar a entender que tienen alguna señal blanca en el hocico, de la cual se infiere que serán buenos y leales.» (_Diccionario de Autoridades_, de 1726.)\"},{\"heading\":false,\"text\":\"(_Salen el_ COMENDADOR _y_ ORTUÑO; MÚSICOS; JUAN ROJO _y_ ESTEBAN, ALONSO, _alcaldes._)\"},{\"heading\":false,\"text\":\"(_Cantan._)\"},{\"heading\":false,\"text\":\"_Sea bien venido el comendadore de rendir las tierras y matar los hombres. ¡Vivan los Guzmanes! ¡Vivan los Girones! Si en las paces blando, dulce en las razones. Venciendo moricos, fuertes como un roble, de Ciudad-Reale viene vencedore; que a Fuente Ovejuna trae los sus pendones. ¡Viva muchos años, viva Fernán Gómez!_\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Villa, yo os agradezco justamente el amor que me habéis aquí mostrado.\"},{\"heading\":false,\"text\":\"ALONSO\"},{\"heading\":false,\"text\":\"Aun no muestra una parte del que siente. Pero, ¿qué mucho que seáis amado, mereciéndolo vos?\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Fuente Ovejuna y el regimiento[17] que hoy habéis honrado, que recibáis os ruega y importuna un pequeño presente, que esos carros traen, señor, no sin vergüenza alguna, de voluntades y árboles bizarros, más que de ricos dones. Lo primero traen dos cestas de polidos barros; de gansos viene un ganadillo entero, que sacan por las redes las cabezas, para cantar vueso valor guerrero. Diez cebones en sal, valientes piezas, sin otras menudencias y cecinas; y más que guantes de ámbar, sus cortezas. Cien pares de capones y gallinas, que han dejado viudos a sus gallos en las aldeas que miráis vecinas. Acá no tienen armas ni caballos, no jaeces bordados de oro puro, si no es oro el amor de los vasallos. Y porque digo puro, os aseguro que vienen doce cueros, que aun en cueros por enero podéis guardar un muro, si de ellos aforráis vuestros guerreros, mejor que de las armas aceradas; que el vino suele dar lindos aceros. De quesos y otras cosas no excusadas no quiero daros cuenta: justo pecho de voluntades que tenéis ganadas; y a vos y a vuestra casa, buen provecho.\"},{\"heading\":false,\"text\":\"[17] _Regimiento_, el concejo municipal.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Estoy muy agradecido. Id, regimiento, en buen hora.\"},{\"heading\":false,\"text\":\"ALONSO\"},{\"heading\":false,\"text\":\"Descansad, señor, agora, y seáis muy bien venido; que esta espadaña que veis y juncia a vuestros umbrales, fueran perlas orientales, y mucho más merecéis, a ser posible a la villa.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Así lo creo, señores. Id con Dios.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Ea, cantores, vaya otra vez la letrilla.\"},{\"heading\":false,\"text\":\"(_Cantan._)\"},{\"heading\":false,\"text\":\"_Sea bien venido el comendadore de rendir las tierras y matar los hombres._\"},{\"heading\":false,\"text\":\"(_Vanse._)\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Esperad vosotras dos.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¿Qué manda su señoría?\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¡Desdenes el otro día, pues, conmigo! ¡Bien por Dios!\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¿Habla contigo, Pascuala?\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Conmigo no, tirte ahuera[18].\"},{\"heading\":false,\"text\":\"[18] _Tirte ahuera_, ¡anda allá!\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Con vos hablo, hermosa fiera, y con esotra zagala. ¿Mías no sois?\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Sí, señor; mas no para casos tales.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Entrad, pasad los umbrales; hombres hay, no hayáis temor.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Si los alcaldes entraran (que de uno soy hija yo), bien huera entrar; mas si no...\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Flores...\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Señor...\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¿Qué reparan en no hacer lo que les digo?\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Entra, pues.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"No nos agarre.\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Entrad; que sois necias.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Arre; que echaréis luego el postigo.\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Entrad; que os quiere enseñar lo que trae de la guerra.\"},{\"heading\":false,\"text\":\"COMENDADOR [_Aparte a_ ORTUÑO.]\"},{\"heading\":false,\"text\":\"Si entraron. Ortuño, cierra.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Flores, dejadnos pasar.\"},{\"heading\":false,\"text\":\"ORTUÑO\"},{\"heading\":false,\"text\":\"¿También venís presentadas con lo demás?\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"¡Bien a fe! Desvíese, no le dé...\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Basta; que son extremadas.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¿No basta a vueso señor tanta carne presentada?\"},{\"heading\":false,\"text\":\"ORTUÑO\"},{\"heading\":false,\"text\":\"La vuestra es la que le agrada.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Reviente de mal dolor.\"},{\"heading\":false,\"text\":\"(_Vanse._)\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"¡Muy buen recado llevamos! No se ha de poder sufrir lo que nos ha de decir cuando sin ellas nos vamos.\"},{\"heading\":false,\"text\":\"ORTUÑO\"},{\"heading\":false,\"text\":\"Quien sirve se obliga a esto. Si en algo desea medrar, o con paciencia ha de estar, o ha despedirse de presto.\"},{\"heading\":false,\"text\":\"(_Vanse los dos y salgan el_ REY DON FERNANDO, _la_ REINA DOÑA ISABEL, MANRIQUE _y acompañamiento._)\"},{\"heading\":false,\"text\":\"ISABEL\"},{\"heading\":false,\"text\":\"Digo, señor, que conviene el no haber descuido en esto, por ver a Alfonso en tal puesto, y su ejército previene. Y es bien ganar por la mano antes que el daño veamos; que si no lo remediamos, el ser muy cierto está llano.\"},{\"heading\":false,\"text\":\"REY\"},{\"heading\":false,\"text\":\"De Navarra y de Aragón está el socorro seguro, y de Castilla procuro hacer la reformación de modo, que el buen suceso con la prevención se vea.\"},{\"heading\":false,\"text\":\"ISABEL\"},{\"heading\":false,\"text\":\"Pues vuestra majestad crea que el buen fin consiste en esto.\"},{\"heading\":false,\"text\":\"MANRIQUE\"},{\"heading\":false,\"text\":\"Aguardando tu licencia dos regidores están de Ciudad Real: ¿entrarán?\"},{\"heading\":false,\"text\":\"REY\"},{\"heading\":false,\"text\":\"No les nieguen mi presencia.\"},{\"heading\":false,\"text\":\"(_Salen dos_ REGIDORES _de Ciudad Real._)\"},{\"heading\":false,\"text\":\"REGIDOR 1.º\"},{\"heading\":false,\"text\":\"Católico rey Fernando, a quien ha enviado el cielo, desde Aragón a Castilla, para bien y amparo nuestro: en nombre de Ciudad Real a vuestro valor supremo humildes nos presentamos, el real amparo pidiendo. A mucha dicha tuvimos tener título de vuestros; pero pudo derribarnos deste honor el hado adverso. El famoso don Rodrigo Téllez Girón, cuyo esfuerzo es en valor extremado, aunque es en la edad tan tierno, maestre de Calatrava, él, ensanchar pretendiendo el honor de la encomienda, nos puso apretado cerco. Con valor nos prevenimos, a su fuerza resistiendo, tanto, que arroyos corrían de la sangre de los muertos. Tomó posesión, en fin; pero no llegara a hacerlo, a no le dar Fernán Gómez orden, ayuda y consejo. El queda en la posesión, y sus vasallos seremos, suyos, a nuestro pesar, a no remediarlo presto.\"},{\"heading\":false,\"text\":\"REY\"},{\"heading\":false,\"text\":\"¿Dónde queda Fernán Gómez?\"},{\"heading\":false,\"text\":\"REGIDOR 1.º\"},{\"heading\":false,\"text\":\"En Fuente Ovejuna creo, por ser su villa, y tener en ella casa y asiento. Allí, con más libertad de la que decir podemos, tiene a los súbditos suyos de todo contento ajenos.\"},{\"heading\":false,\"text\":\"REY\"},{\"heading\":false,\"text\":\"¿Tenéis algún capitán?\"},{\"heading\":false,\"text\":\"REGIDOR 2.°\"},{\"heading\":false,\"text\":\"Señor, el no haberle es cierto, pues no escapó ningún noble de preso, herido o de muerto.\"},{\"heading\":false,\"text\":\"ISABEL\"},{\"heading\":false,\"text\":\"Ese caso no requiere ser despacio remediado; que es dar al contrario osado el mismo valor que adquiere; y puede el de Portugal, hallando puerta segura, entrar por Extremadura y causamos mucho mal.\"},{\"heading\":false,\"text\":\"REY\"},{\"heading\":false,\"text\":\"Don Manrique, partid luego, llevando dos compañías; remediad sus demasías, sin darles ningún sosiego. El conde de Cabra ir puede con vos; que es Córdoba osado, a quien nombre de soldado todo el mundo le concede; que éste es el medio mejor que la ocasión nos ofrece.\"},{\"heading\":false,\"text\":\"MANRIQUE\"},{\"heading\":false,\"text\":\"El acuerdo me parece como de tan gran valor. Pondré límite a su exceso, si el vivir en mí no cesa.\"},{\"heading\":false,\"text\":\"ISABEL\"},{\"heading\":false,\"text\":\"Partiendo vos a la empresa, seguro está el buen suceso.\"},{\"heading\":false,\"text\":\"(_Vanse todos y salen_ LAURENCIA _y_ FRONDOSO.)\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"A medio torcer los paños, quise, atrevido Frondoso, para no dar que decir, desviarme del arroyo; decir a tus demasías que murmura el pueblo todo, que me miras y te miro, y todos nos traen sobre ojo. Y como tú eres zagal, de los que huellan, brioso, y excediendo a los demás, vistes bizarro y costoso, en todo el lugar no hay moza, o mozo en el prado o soto, que no se afirme diciendo que ya para en uno somos; y esperan todos el día que el sacristán Juan Chamorro nos eche de la tribuna, en dejando los piporros[19]. Y mejor sus trojes vean de rubio trigo en agosto atestadas y colmadas, y sus tinajas de mosto, que tal imaginación me ha llegado a dar enojo: ni me desvela ni aflige, ni en ella el cuidado pongo.\"},{\"heading\":false,\"text\":\"[19] Instrumento de música, llamado también _bajón_.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Tal me tienen tus desdenes, bella Laurencia, que tomo, en el peligro de verte, la vida, cuando te oigo. Si sabes que es mi intención el desear ser tu esposo, mal premio das a mi fe.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Es que yo no sé dar otro.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"¿Posible es que no te duelas de verme tan cuidadoso, y que imaginando en ti, ni bebo, duermo ni como? ¿Posible es tanto rigor en ese angélico rostro? ¡Viven los cielos que rabio!\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Pues salúdate[20], Frondoso.\"},{\"heading\":false,\"text\":\"[20] _Saludar_, usar de ciertas fórmulas (hacer cruces con saliva, etcétera), pretendiendo curar la rabia y otros males.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Ya te pido yo salud, y que ambos, como palomos, estemos, juntos los picos, con arrullos sonorosos, después de damos la Iglesia...\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Dilo a mi tío Juan Rojo; que aunque no te quiero bien, ya tengo algunos asomos.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"¡Ay de mí! El señor es éste.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Tirando viene a algún corzo. Escóndete en esas ramas.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Y ¡con qué celos me escondo!\"},{\"heading\":false,\"text\":\"(_Sale el_ COMENDADOR.)\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"No es malo venir siguiendo un corcillo temeroso, y topar tan bella gama.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Aquí descansaba un poco de haber lavado unos paños; y así, al arroyo me tomo, si manda su señoría.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Aquesos desdenes toscos afrentan, bella Laurencia, las gracias que el poderoso cielo te dió, de tal suerte, que vienes a ser un monstruo. Mas si otras veces pudiste huir mi ruego amoroso, agora no quiere el campo, amigo secreto y solo; que tú sola no has de ser tan soberbia, que tu rostro huyas al señor que tienes, teniéndome a mí en tan poco. ¿No se rindió Sebastiana, mujer de Pedro Redondo, con ser casadas entrambas, y la de Martín del Pozo, habiendo apenas pasado dos días del desposorio?\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Esas, señor, ya tenían, de haber andado con otros, el camino de agradaros; porque también muchos mozos merecieron sus favores. Id con Dios, tras vueso corzo; que a no veros con la cruz, os tuviera por demonio, pues tanto me perseguís.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¡Qué estilo tan enfadoso! Pongo la ballesta en tierra, ...[21] y a la práctica de manos reduzgo melindres.\"},{\"heading\":false,\"text\":\"[21] Falta un verso para el romance, pero no para el sentido.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¡Cómo! ¿Eso hacéis? ¿Estáis en vos?\"},{\"heading\":false,\"text\":\"(_Sale_ FRONDOSO _y toma la ballesta._)\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"No te defiendas.\"},{\"heading\":false,\"text\":\"FRONDOSO [_Aparte._]\"},{\"heading\":false,\"text\":\"Si tomo la ballesta, ¡vive el cielo que no la ponga en el hombro!\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Acaba, ríndete.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¡Cielos, ayudadme agora!\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Solos estamos; no tengas miedo.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Comendador generoso, dejad la moza, o creed que de mi agravio y enojo será blanco vuestro pecho, aunque la cruz me da asombro.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¡Perro, villano!...\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"No hay perro. Huye, Laurencia.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Frondoso, mira lo que haces.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Vete.\"},{\"heading\":false,\"text\":\"(_Vase._)\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¡Oh, mal haya el hombre loco, que se desciñe la espada! Que, de no espantar medroso la caza, me la quité.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Pues, pardiez, señor, si toco la nuez[22], que os he de apiolar.\"},{\"heading\":false,\"text\":\"[22] Botón con que se disparaba la ballesta.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Ya es ida. Infame, alevoso, suelta la ballesta luego. Suéltala, villano.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"¿Cómo? Que me quitaréis la vida. Y advertid que amor es sordo, y que no escucha palabras el día que está en su trono.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Pues ¿la espa[l]da ha de volver un hombre tan valeroso a un villano? Tira, infame, tira, y guárdate; que rompo las leyes de caballero.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Eso no. Yo me conformo con mi estado, y pues me es guardar la vida forzoso, con la ballesta me voy.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¡Peligro extraño y notorio! Mas yo tomaré venganza del agravio y del estorbo. ¡Que no cerrara con él! ¡Vive el cielo, que me corro!\"}]},{\"title\":\"Acto Segundo\",\"blocks\":[{\"heading\":false,\"text\":\"ACTO SEGUNDO DE FUENTE OVEJUNA\"},{\"heading\":false,\"text\":\"(_Salen_ ESTEBAN _y_ REGIDOR 1.°)\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Así tenga salud, como parece, que no se saque más agora el pósito. El año apunta mal, y el tiempo crece, y es mejor que el sustento esté en depósito, aunque lo contradicen más de trece.\"},{\"heading\":false,\"text\":\"REGIDOR 1.°\"},{\"heading\":false,\"text\":\"Yo siempre he sido, al fin, de este propósito, en gobernar en paz esta república.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Hagamos de ello a Fernán Gómez súplica. No se puede sufrir que estos astrólogos, en las cosas futuras ignorantes[23], nos quieran persuadir con largos prólogos los secretos a Dios sólo importantes. ¡Bueno es que, presumiendo de teólogos, hagan un tiempo el que[24] después y antes! Y pidiendo el presente lo importante, al más sabio veréis más ignorante. ¿Tienen ellos las nubes en su casa y el proceder de las celestes lumbres? ¿Por dónde ven lo que en el cielo pasa, para damos con ello pesadumbres? Ellos en [el] sembrar nos ponen tasa: daca el trigo, cebada y las legumbres, calabazas, pepinos y mostazas... Ellos son, a la fe, las calabazas. Luego cuentan que muere una cabeza, y después viene a ser en Transilvania; que el vino será poco, y la cerveza sobrará por las partes de Alemania; que se helará en Gascuña la cereza, y que habrá muchos tigres en Hircania. Y al cabo, al cabo, se siembre o no se siembre, el año se remata por diciembre.\"},{\"heading\":false,\"text\":\"[23] _El original_, y ignorantes.\"},{\"heading\":false,\"text\":\"[24] El que será después y fué antes.\"},{\"heading\":false,\"text\":\"(_Salen el licenciado_ LEONELO _y_ BARRILDO.)\"},{\"heading\":false,\"text\":\"LEONELO\"},{\"heading\":false,\"text\":\"A fe que no ganéis la palmatoria[25], porque ya está ocupado el mentidero.\"},{\"heading\":false,\"text\":\"[25] Al muchacho que llegaba primero a la escuela le daban la palmeta para que aplicase los castigos.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"¿Cómo os fué en Salamanca?\"},{\"heading\":false,\"text\":\"LEONELO\"},{\"heading\":false,\"text\":\"Es larga historia.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Un Bártulo seréis.\"},{\"heading\":false,\"text\":\"LEONELO\"},{\"heading\":false,\"text\":\"Ni aun un barbero. Es, como digo, cosa muy notoria en esta facultad lo que os refiero.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Sin duda que venís buen estudiante.\"},{\"heading\":false,\"text\":\"LEONELO\"},{\"heading\":false,\"text\":\"Saber he procurado lo importante.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Después que vemos tanto libro impreso, no hay nadie que de sabio no presuma.\"},{\"heading\":false,\"text\":\"LEONELO\"},{\"heading\":false,\"text\":\"Antes que ignoran más siento por eso, por no se reducir a breve suma; porque la confusión, con el exceso, los intentos resuelve en vana espuma; y aquel que de leer tiene más uso, de ver letreros sólo está confuso. No niego yo que de[26] imprimir el arte mil ingenios sacó de entre la jerga, y que parece que en sagrada parte sus obras guarda y contra el tiempo alberga; éste las distribuye y las reparte. Débese esta invención a Gutemberga, un famoso tudesco de Maguncia, en quien la fama su valor renuncia. Mas muchos que opinión tuvieron grave, por imprimir sus obras la perdieron; tras esto, con el nombre del que sabe, muchos sus ignorancias imprimieron. Otros, en quien la baja envidia cabe, sus locos desatinos escribieron, y con nombre de aquel que aborrecían, impresos por el mundo los envían.\"},{\"heading\":false,\"text\":\"[26] _El original_, del.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"No soy de esa opinión.\"},{\"heading\":false,\"text\":\"LEONELO\"},{\"heading\":false,\"text\":\"El ignorante es justo que se vengue del letrado.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Leonelo, la impresión es importante.\"},{\"heading\":false,\"text\":\"LEONELO\"},{\"heading\":false,\"text\":\"Sin ella muchos siglos se han pasado, y no vemos que en éste se levante un Jerónimo santo, un Agustino. ...[27].\"},{\"heading\":false,\"text\":\"[27] Falta un verso para la octava.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Dejadlo y asentaos, que estáis mohino.\"},{\"heading\":false,\"text\":\"(_Salen_ JUAN ROJO _y otro labrador._)\"},{\"heading\":false,\"text\":\"JUAN ROJO\"},{\"heading\":false,\"text\":\"No hay en cuatro haciendas para un dote, si es que las vistas han de ser al uso; que el hombre que es curioso es bien que note que en esto el barrio y vulgo anda confuso.\"},{\"heading\":false,\"text\":\"LABRADOR\"},{\"heading\":false,\"text\":\"¿Qué hay del comendador? No os alborote.\"},{\"heading\":false,\"text\":\"JUAN ROJO\"},{\"heading\":false,\"text\":\"¡Cuál a Laurencia en ese campo puso!\"},{\"heading\":false,\"text\":\"LABRADOR\"},{\"heading\":false,\"text\":\"¿Quién fué cual él tan bárbaro y lascivo? Colgado le vea yo del aquel olivo.\"},{\"heading\":false,\"text\":\"(_Salen el_ COMENDADOR, ORTUÑO _y_ FLORES.)\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Dios guarde la buena gente.\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"¡Oh, señor!\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Por vida mía, que se estén.\"},{\"heading\":false,\"text\":\"[ESTEBAN] ALCALDE\"},{\"heading\":false,\"text\":\"Vusiñoría, adonde suele se siente, que en pie estaremos muy bien.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Digo que se han de sentar.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"De los buenos es honrar, que no es posible que den honra los que no la tienen.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Siéntense; hablaremos algo.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"¿Vió vusiñoría el galgo?\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Alcalde, espantados vienen esos criados de ver tan notable ligereza.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Es una extremada pieza. Pardiez, que puede correr [al][28] lado de un delincuente o de un cobarde en quistión[29].\"},{\"heading\":false,\"text\":\"[28] _El original_, a un.\"},{\"heading\":false,\"text\":\"[29] _Quistión_, cuestión, tormento.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Quisiera en esta ocasión que le hiciérades pariente[30] a una liebre que por pies por momentos se me va.\"},{\"heading\":false,\"text\":\"[30] _Hacer pariente_, juntar, reunir.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Sí haré, par Dios. ¿Dónde está?\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Allá vuestra hija es.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"¡Mi hija!\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Sí.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Pues ¿es buena para alcanzada de vos?\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Reñilda, alcalde, por Dios.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"¿Cómo?\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Ha dado en darme pena. Mujer hay, y principal, de alguno que está en la plaza, que dió, a la primera traza, traza de verme.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Hizo mal; y vos, señor, no andáis bien en hablar tan libremente.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¡Oh, qué villano elocuente! ¡Ah, Flores!, haz que le den la _Política_, en que lea de Aristóteles.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Señor, debajo de vuestro honor vivir el pueblo desea. Mirad que en Fuente Ovejuna hay gente muy principal.\"},{\"heading\":false,\"text\":\"LEONELO\"},{\"heading\":false,\"text\":\"¿Vióse desvergüenza igual?\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Pues ¿he dicho cosa alguna de que os pese, regidor?\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"Lo que decís es injusto; no lo digáis, que no es justo que nos quitéis el honor.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¿Vosotros honor tenéis? ¡Qué freiles de Calatrava!\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"Alguno acaso se alaba de la cruz que le ponéis, que no es de sangre tan limpia.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Y ¿ensucióla yo juntando la mía a la vuestra?\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"Cuando que el mal más tiñe que alimpia.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"De cualquier suerte que sea, vuestras mujeres se honran.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Esas palabras deshonran[31]; las o[t]ras[32], no hay quien las crea.\"},{\"heading\":false,\"text\":\"[31] _El original_, les honran.\"},{\"heading\":false,\"text\":\"[32] _El original_, obras.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¡Qué cansado villanaje! ¡Ah! Bien hayan las ciudades; que a hombres de calidades no hay quien sus gustos ataje; allá se precian casados que visiten sus mujeres.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"No harán; que con esto quieres que vivamos descuidados. En las ciudades hay Dios, y más presto quien castiga.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Levantaos de aquí.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"¿Que diga lo que escucháis por los dos?\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Salí de la plaza luego; no quede ninguno aquí.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Ya nos vamos.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Pues no ansí.\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Que te reportes te ruego.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Querrían hacer corrillo los villanos en mi ausencia.\"},{\"heading\":false,\"text\":\"ORTUÑO\"},{\"heading\":false,\"text\":\"Ten un poco de paciencia.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"De tanta me maravillo. Cada uno de por sí se vayan hasta sus casas.\"},{\"heading\":false,\"text\":\"LEONELO\"},{\"heading\":false,\"text\":\"¡Cielo! ¿Que por esto pasas?\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Ya yo me voy por aquí.\"},{\"heading\":false,\"text\":\"(_Vanse._)\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¿Qué os parece de esta gente?\"},{\"heading\":false,\"text\":\"ORTUÑO\"},{\"heading\":false,\"text\":\"No sabes disimular que no quiere[s][33] escuchar el disgusto que se siente.\"},{\"heading\":false,\"text\":\"[33] _El original_, quieren.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Estos ¿se igualan conmigo?\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Que no es aqueso igualarse.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Y el villano ¿ha de quedarse con ballesta y sin castigo?\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Anoche pensé que estaba a la puerta de Laurencia, y a otro, que su presencia y su capilla imitaba, de oreja a oreja le di un beneficio famoso.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¿Dónde estará aquel Frondoso?\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Dicen que anda por ahí.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¡Por ahí se atreve a andar hombre que matarme quiso!\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Como el ave sin aviso, o como el pez, viene a dar al reclamo o al anzuelo.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¡Que a un capitán cuya espada tiemblan Córdoba y Granada, un labrador, un mozuelo ponga una ballesta al pecho! El mundo se acaba, Flores.\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Como eso pueden amores.\"},{\"heading\":false,\"text\":\"ORTUÑO\"},{\"heading\":false,\"text\":\"Y pues que vive, sospecho que grande amistad le debes.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Yo he disimulado, Ortuño; que si no, de punta a puño, antes de dos horas breves, pasara todo el lugar; que hasta que llegue ocasión al freno de la razón hago la venganza estar.-- ¿Qué hay de Pascuala?\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Responde que anda agora por casarse.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¿Hasta allá quiere fiarse?...\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"En fin, te remite donde te pagarán de contado.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¿Qué hay de Olalla?\"},{\"heading\":false,\"text\":\"ORTUÑO\"},{\"heading\":false,\"text\":\"Una graciosa respuesta.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Es moza briosa. ¿Cómo?\"},{\"heading\":false,\"text\":\"ORTUÑO Que su desposado anda tras ella estos días celoso de mis recados, y de que con tus criados a visitalla venías; pero que si se descuida, entrarás como primero.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¡Bueno, a fe de caballero! Pero el villanejo cuida...\"},{\"heading\":false,\"text\":\"ORTUÑO\"},{\"heading\":false,\"text\":\"Cuida, y anda por los aires.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¿Qué hay de Inés?\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"¿Cuál?\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"La de Antón.\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Para cualquier ocasión ya ha ofrecido sus donaires.\"},{\"heading\":false,\"text\":\"Háblela por el corral, por donde has de entrar si quieres.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"A las fáciles mujeres quiero bien y pago mal. Si éstas supiesen, ¡oh, Flores!, estimarse en lo que valen...\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"No hay disgustos que se igualen a contrastar sus favores. Rendirse presto desdice de la esperanza del bien; mas hay mujeres también, porque el filósofo dice que apetecen a los hombres como la forma desea la materia; y que esto sea así, no hay de que te asombre.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Un hombre de amores loco huélgase que a su accidente se le rindan fácilmente, mas después las tiene en poco, y el camino de olvidar al hombre más obligado es haber poco costado lo que pudo desear.\"},{\"heading\":false,\"text\":\"(_Sale_ CIMBRANOS, _soldado._)\"},{\"heading\":false,\"text\":\"[CIMBRANOS], SOLDADO\"},{\"heading\":false,\"text\":\"¿Está aquí el comendador?\"},{\"heading\":false,\"text\":\"ORTUÑO\"},{\"heading\":false,\"text\":\"¿No le ves en tu presencia?\"},{\"heading\":false,\"text\":\"[CIMBRANOS], SOLDADO\"},{\"heading\":false,\"text\":\"¡Oh, gallardo Fernán Gómez! Trueca la verde montera en el blanco morrión y el gabán en armas nuevas, que el maestre de Santiago, y el conde de Cabra cercan a don Rodrigo Girón, por la castellana reina, en Ciudad Real; de suerte que no es mucho que se pierda lo que en Calatrava sabes que tanta sangre le cuesta. Ya divisan con las luces, desde las altas almenas, los castillos y leones y barras aragonesas. Y aunque el rey de Portugal honrar a Girón quisiera, no hará poco en que el maestre a Almagro con vida vuelva. Ponte a caballo, señor; que sólo con que te vean, se volverán a Castilla.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"No prosigas; tente, espera.-- Haz, Ortuño, que en la plaza toquen luego una trompeta. ¿Qué soldados tengo aquí?\"},{\"heading\":false,\"text\":\"ORTUÑO\"},{\"heading\":false,\"text\":\"Pienso que tienes cincuenta.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Pónganse a caballo todos.\"},{\"heading\":false,\"text\":\"[CIMBRANOS], SOLDADO\"},{\"heading\":false,\"text\":\"Si no caminas apriesa, Ciudad Real es del rey.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"No hayas miedo que lo sea.\"},{\"heading\":false,\"text\":\"[_Vanse._]\"},{\"heading\":false,\"text\":\"(_Salen_ MENGO _y_ LAURENCIA _y_ PASCUALA, _huyendo._)\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"No te apartes de nosotras.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Pues ¿a qué tenéis temor?\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Mengo, a la villa es mejor que vamos unas con otras (pues que no hay hombre ninguno), por que no demos con él.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"¡Que este demonio cruel nos sea tan importuno!\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"No nos deja a sol ni a sombra.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"¡Oh! Rayo del cielo baje, que sus locuras ataje.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Sangrienta fiera le nombra; arsénico y pestilencia del lugar.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Hanme contado que Frondoso, aquí en el prado, para librarte, Laurencia, le puso al pecho una jara.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Los hombres aborrecía, Mengo; mas desde aquel día los miro con otra cara. ¡Gran valor tuvo Frondoso! Pienso que le ha de costar la vida.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Que del lugar se vaya, será forzoso.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Aunque ya le quiero bien, eso mismo le aconsejo; mas recibe mi consejo con ira, rabia y desdén; y jura el comendador que le ha de colgar de un pie.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"¡Mal garrotillo le dé!\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Mala pedrada es mejor. ¡Voto al sol, si le tirara con la que llevo al apero, que al sonar el crujidero, al casco se la encajara! No fué Sábalo, el romano, tan vicioso por jamás.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Heliogábalo dirás, más que una fiera inhumano.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Pero Galván, o quién fué, que yo no entiendo de historia; mas su cativa memoria vencida de éste se ve. ¿Hay hombre en naturaleza como Fernán Gómez?\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"No; que parece que le dió de una tigre la aspereza.\"},{\"heading\":false,\"text\":\"(_Sale_ JACINTA.)\"},{\"heading\":false,\"text\":\"JACINTA\"},{\"heading\":false,\"text\":\"Dadme socorro, por Dios, si la amistad os obliga.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¿Qué es esto, Jacinta amiga?\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Tuyas lo somos las dos.\"},{\"heading\":false,\"text\":\"JACINTA\"},{\"heading\":false,\"text\":\"Del comendador criados, que van a Ciudad Real, más de infamia natural que de noble acero armados, me quieren llevar a él.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Pues Jacinta, Dios te libre; que cuando contigo es libre, conmigo será cruel. (_Vase._)\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Jacinta, yo no soy hombre que te puedo defender. (_Vase._)\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Yo sí lo tengo de ser, porque tengo el ser y el nombre. Llégate, Jacinta, a mí.\"},{\"heading\":false,\"text\":\"JACINTA\"},{\"heading\":false,\"text\":\"¿Tienes armas?\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Las primeras del mundo.\"},{\"heading\":false,\"text\":\"JACINTA\"},{\"heading\":false,\"text\":\"¡Oh, si las tuvieras!\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Piedras hay, Jacinta, aquí.\"},{\"heading\":false,\"text\":\"(_Salen_ FLORES _y_ ORTUÑO.)\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"¿Por los pies pensabas irte?\"},{\"heading\":false,\"text\":\"JACINTA\"},{\"heading\":false,\"text\":\"Mengo, ¡muerta soy!\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Señores... ¡A estos pobres labradores!...\"},{\"heading\":false,\"text\":\"ORTUÑO\"},{\"heading\":false,\"text\":\"Pues ¿tú quieres persuadirte a defender la mujer?\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Con los ruegos la defiendo; que soy su deudo y pretendo guardalla, si puede ser.\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Quitalde luego la vida.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"¡Voto al sol, si me emberrincho, y el cáñamo me descincho, que la llevéis bien vendida!\"},{\"heading\":false,\"text\":\"(_Salen el_ COMENDADOR _y_ CIMBRANOS.)\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¿Qué es eso? ¡A cosas tan viles me habéis de hacer apear!\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Gente de este vil lugar (que ya es razón que aniquiles, pues en nada te da gusto) a nuestras armas se atreve.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Señor, si piedad os mueve de suceso tan injusto, castigad estos soldados, que con vuestro nombre agora roban una labradora [a] esposo y padres honrados; y dadme licencia a mí que se la pueda llevar.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Licencia les quiero dar... para vengarse de ti. Suelta la honda.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"¡Señor!...\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Flores, Ortuño, Cimbranos, con ella le atad las manos.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"¿Así volvéis por su honor?\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¿Qué piensan Fuente Ovejuna y sus villanos de mí?\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Señor, ¿en qué os ofendí, ni el pueblo en cosa ninguna?\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"¿Ha de morir?\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"No ensuciéis las armas, que habéis de honrar en otro mejor lugar.\"},{\"heading\":false,\"text\":\"ORTUÑO\"},{\"heading\":false,\"text\":\"¿Qué mandas?\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Que lo azotéis. Llevadle, y en ese roble le atad y le desnudad, y con las riendas...\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"¡Piedad! ¡Piedad, pues sois hombre noble!\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Azotalde hasta que salten los hierros de las correas.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"¡Cielos! ¿A hazañas tan feas queréis que castigos falten?\"},{\"heading\":false,\"text\":\"(_Vanse._)\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Tú, villana, ¿por qué huyes? ¿Es mejor un labrador que un hombre de mi valor?\"},{\"heading\":false,\"text\":\"JACINTA\"},{\"heading\":false,\"text\":\"¡Harto bien me restituyes el honor que me han quitado en llevarme para ti!\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¿En quererte llevar?\"},{\"heading\":false,\"text\":\"JACINTA\"},{\"heading\":false,\"text\":\"Sí; porque tengo un padre honrado, que si en alto nacimiento no te iguala, en las costumbres te vence.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Las pesadumbres y el villano atrevimiento no tiemplan bien un airado. Tira por ahí.\"},{\"heading\":false,\"text\":\"JACINTA\"},{\"heading\":false,\"text\":\"¿Con quién?\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Conmigo.\"},{\"heading\":false,\"text\":\"JACINTA\"},{\"heading\":false,\"text\":\"Míralo bien.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Para tu mal lo he mirado. Ya no mía, del bagaje del ejército has de ser.\"},{\"heading\":false,\"text\":\"JACINTA\"},{\"heading\":false,\"text\":\"No tiene el mundo poder para hacerme, viva, ultraje.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Ea, villana, camina.\"},{\"heading\":false,\"text\":\"JACINTA\"},{\"heading\":false,\"text\":\"¡Piedad, señor!\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"No hay piedad.\"},{\"heading\":false,\"text\":\"JACINTA\"},{\"heading\":false,\"text\":\"Apelo de tu crueldad a la justicia divina.\"},{\"heading\":false,\"text\":\"(_Llévanla y vanse, y salen_ LAURENCIA _y_ FRONDOSO.)\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¿Cómo así a venir te atreves, sin temer tu daño?\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Ha sido dar testimonio cumplido de la afición que me debes. Desde aquel recuesto vi salir al comendador, y fiado en tu valor, todo mi temor perdí. Vaya donde no le vean volver.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Tente en maldecir, porque suele más vivir al que la muerte desean.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Si es eso, viva mil años, y así se hará todo bien, pues deseándole bien estarán ciertos sus daños. Laurencia, deseo saber si vive en ti mi cuidado, y si mi lealtad ha hallado el puerto de merecer. Mira que toda la villa ya para en uno nos tiene; y de cómo a ser no viene, la villa se maravilla. Los desdeñosos extremos deja, y responde no o sí.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Pues a la villa y a ti respondo que lo seremos.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Deja que tus plantas bese por la merced recibida, pues el cobrar nueva vida por ella es bien que confiese.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"De cumplimientos acorta; y para que mejor cuadre, habla, Frondoso, a mi padre, pues es lo que más importa, que allí viene con mi tío; y fía que ha de tener ser, Frondoso, tu mujer, buen suceso.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"En Dios confío.\"},{\"heading\":false,\"text\":\"(_Escóndese._)\"},{\"heading\":false,\"text\":\"(_Salen_ ESTEBAN, _alcalde_, _y el_ REGIDOR.)\"},{\"heading\":false,\"text\":\"[ESTEBAN], ALCALDE\"},{\"heading\":false,\"text\":\"Fué su término de modo, que la plaza alborotó: en efeto, procedió muy descomedido en todo. No hay a quien admiración sus demasías no den; la pobre Jacinta es quien pierde por su sinrazón.\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"Ya [a] los Católicos Reyes, que este nombre les dan ya, presto España les dará la obediencia de sus leyes. Ya sobre Ciudad Real, contra el Girón que la tiene, Santiago a caballo viene por capitán general. Pésame; que era Jacinta doncella de buena pro.\"},{\"heading\":false,\"text\":\"[ESTEBAN], ALCALDE\"},{\"heading\":false,\"text\":\"Luego a Mengo le azotó.\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"No hay negra bayeta o tinta como sus carnes están.\"},{\"heading\":false,\"text\":\"[ESTEBAN], ALCALDE\"},{\"heading\":false,\"text\":\"Callad; que me siento arder, viendo su mal proceder, y el mal nombre que le dan. Yo ¿para qué traigo aquí este palo sin provecho?\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"Si sus criados lo han hecho, ¿de qué os afligís ansí?\"},{\"heading\":false,\"text\":\"[ESTEBAN], ALCALDE\"},{\"heading\":false,\"text\":\"¿Queréis más, que me contaron que a la de Pedro Redondo un día, que en lo más hondo de este valle la encontraron, después de sus insolencias, a sus criados la dió?\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"Aquí hay gente: ¿quién es?\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Yo, que espero vuestras licencias.\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"Para mi casa, Frondoso, licencia no es menester; debes a tu padre el ser, y a mí otro ser amoroso. Hete criado, y te quiero como a hijo.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Pues señor, fiado en aquese amor, de ti una merced espero. Ya sabes de quién soy hijo.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"¿Hate agraviado ese loco de Fernán Gómez?\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"No poco.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"El corazón me lo dijo.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Pues señor, con el seguro del amor que habéis mostrado, de Laurencia enamorado, el ser su esposo procuro. Perdona si en el pedir mi lengua se ha adelantado; que he sido en decirlo osado, como otro lo ha de decir.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Vienes, Frondoso, a ocasión que me alargarás la vida por la cosa más temida que siente mi corazón. Agradezco, hijo, al cielo que así vuelvas por mi honor, y agradézcole a tu amor la limpieza de tu celo. Mas como es justo, es razón dar cuenta a tu padre de esto; sólo digo que estoy presto, en sabiendo su intención; que yo dichoso me hallo en que aqueso llegue a ser.\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"De la moza el parecer tomad antes de acetallo.\"},{\"heading\":false,\"text\":\"[ESTEBAN], ALCALDE\"},{\"heading\":false,\"text\":\"No tengáis de eso cuidado, que ya el caso está dispuesto: antes de venir a esto, entre ellos se ha concertado. --En el dote, si advertís, se puede agora tratar; que por bien os pienso dar algunos maravedís.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Yo dote no he menester; de eso no hay que entristeceros\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"Pues que no la pide en cueros lo podéis agradecer.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Tomaré el parecer de ella; si os parece, será bien.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Justo es; que no hace bien quien los gustos atropella.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"¡Hija! ¡Laurencia!...\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Señor...\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Mirad si digo bien yo. ¡Ved qué presto respondió!-- Hija Laurencia, mi amor, a preguntarte ha venido (apártate aquí) si es bien que a Gila, tu amiga, den a Frondoso por marido, que es un honrado zagal, si le hay en Fuente Ovejuna...\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¿Gila se casa?\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Y si alguna le merece y es su igual.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Yo digo, señor, que sí.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Sí; mas yo digo que es fea y que harto mejor se emplea Frondoso, Laurencia, en ti.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¿Aun no se te han olvidado los donaires con la edad?\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"¿Quiéresle tú?\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Voluntad le he tenido y le he cobrado, pero por lo que tú sabes...\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"¿Quieres tú que diga sí?\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Dilo tú, señor, por mí.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"¿Yo? Pues tengo yo las llaves, hecho está.--Ven, buscaremos a mi compadre en la plaza.\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"Vamos.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Hijo, y en la traza del dote, ¿qué le diremos? Que yo bien te puedo dar cuatro mil maravedís.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Señor, ¿eso me decís? Mi honor queréis agraviar.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Anda, hijo; que eso es cosa que pasa en un día: que si no hay dote, a fe mía que se echa menos después.\"},{\"heading\":false,\"text\":\"(_Vanse, y quedan_ FRONDOSO _y_ LAURENCIA.)\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Di, Frondoso, ¿estás contento?\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"¡Cómo si lo estoy! ¡Es poco, pues que no me vuelvo loco de gozo, del bien que siento! Risa vierte el corazón por los ojos de alegría, viéndote, Laurencia mía, en tal dulce posesión.\"},{\"heading\":false,\"text\":\"[_Vanse._]\"},{\"heading\":false,\"text\":\"(_Salen el_ MAESTRE, _el_ COMENDADOR, FLORES _y_ ORTUÑO.)\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Huye, señor, que no hay otro remedio.\"},{\"heading\":false,\"text\":\"MAESTRE\"},{\"heading\":false,\"text\":\"La flaqueza del muro lo ha causado, y el poderoso ejército enemigo.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Sangre les cuesta y infinitas vidas.\"},{\"heading\":false,\"text\":\"MAESTRE\"},{\"heading\":false,\"text\":\"Y no se alabarán que en sus despojos pondrán nuestro pendón de Calatrava, que a honrar su empresa y los demás bastaba.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Tus desinios, Girón, quedan perdidos.\"},{\"heading\":false,\"text\":\"MAESTRE\"},{\"heading\":false,\"text\":\"¿Qué puedo hacer, si la fortuna, ciega, a quien hoy levantó mañana humilla?\"},{\"heading\":false,\"text\":\"(_Dentro._)\"},{\"heading\":false,\"text\":\"¡Vitoria por los reyes de Castilla!\"},{\"heading\":false,\"text\":\"MAESTRE\"},{\"heading\":false,\"text\":\"Ya coronan de luces las almenas, y las ventanas de las torres altas entoldan con pendones vitoriosos.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Bien pudieran, de sangre que les cuesta. A fe que es más tragedia que no fiesta.\"},{\"heading\":false,\"text\":\"MAESTRE\"},{\"heading\":false,\"text\":\"Yo vuelvo a Calatrava, Fernán Gómez.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Y yo a Fuente Ovejuna, mientras tratas o seguir esta parte de tus deudos, o reducir la tuya al Rey Católico.\"},{\"heading\":false,\"text\":\"MAESTRE\"},{\"heading\":false,\"text\":\"Yo te diré por cartas lo que intento.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"El tiempo ha de enseñarte.\"},{\"heading\":false,\"text\":\"MAESTRE\"},{\"heading\":false,\"text\":\"¡Ah, pocos años, sujetos al rigor de sus engaños!\"},{\"heading\":false,\"text\":\"(_Sale la boda._ MÚSICOS, MENGO, FRONDOSO, LAURENCIA, PASCUALA, BARRILDO, ESTEBAN _y_ ALCALDE [JUAN ROJO].)\"},{\"heading\":false,\"text\":\"MÚSICOS\"},{\"heading\":false,\"text\":\"_¡Vivan muchos años los desposados! ¡Vivan muchos años!_\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"A fe, que no os ha costado mucho trabajo el cantar.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Supiéraslo tú trovar mejor que él está trovado.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Mejor entiende de azotes Mengo que de versos ya.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Alguno en el valle está, para que no te alborotes, a quien el comendador...\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"No lo digas, por tu vida; que este bárbaro homicida a todos quita el honor.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Que me azotasen a mí cien soldados aquel día... sola una honda tenía; ...[34] pero que le hayan echado una melecina[35] a un hombre, que, aunque no diré su nombre, todos saben que es honrado, llena de tinta y de chinas, ¿cómo se puede sufrir?\"},{\"heading\":false,\"text\":\"[34] Falta un verso.\"},{\"heading\":false,\"text\":\"[35] _Melecina_, lavativa.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Haríalo por reír.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"No hay risa con melecinas; que aunque es cosa saludable... yo me quiero morir luego.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Vaya la copla, te ruego, si es la copla razonable.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Vivan muchos años juntos los novios, ruego a los cielos, y por envidia ni celos ni riñan ni anden en puntos. Lleven a entrambos difuntos, de puro vivir cansados. ¡Vivan muchos años!\"},{\"heading\":false,\"text\":\"[FRONDOSO][36]\"},{\"heading\":false,\"text\":\"¡Maldiga el cielo el poeta, que tal coplón arrojó!\"},{\"heading\":false,\"text\":\"[36] _El original_, Mengo.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Fué muy presto...\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Pienso yo una cosa de esta seta[37]. ¿No habéis visto un buñolero, en el aceite abrasando pedazos de masa echando hasta llenarse el caldero? ¿Que unos le salen hinchados, otros tuertos y mal hechos, ya zurdos y ya derechos, ya fritos y ya quemados? Pues así imagino yo un poeta componiendo, la materia previniendo que es quien la masa le dió. Va arrojando verso aprisa al caldero del papel, confiado en que la miel cubrirá la burla y risa. Mas poniéndolo en el pecho, apenas hay quien los tome; tanto que sólo los come el mismo que los ha hecho.\"},{\"heading\":false,\"text\":\"[37] _Seta_, secta.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Déjate ya de locuras; deja los novios hablar.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Las manos nos da a besar.\"},{\"heading\":false,\"text\":\"JUAN [ROJO]\"},{\"heading\":false,\"text\":\"Hija, ¿mi mano procuras? Pídela a tu padre luego para ti y para Frondoso.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Rojo, a ella y a su esposo que se la dé el cielo ruego, con su larga bendición.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Los dos a los dos la echad.\"},{\"heading\":false,\"text\":\"JUAN [ROJO]\"},{\"heading\":false,\"text\":\"Ea, tañed y cantad, pues que para en uno son.\"},{\"heading\":false,\"text\":\"MÚSICOS\"},{\"heading\":false,\"text\":\"_Al val de Fuente Ovejuna la niña en cabellos baja; el caballero la sigue de la Cruz de Calatrava. Entre las ramas se esconde, de vergonzosa y turbada; fingiendo que no le ha visto, pone delante las ramas. «¿Para qué te ascondes, niña gallarda? Que mis linces deseos paredes pasan.» Acercóse él caballero, y ella, confusa y turbada, hacer quiso celosías de las intrincadas ramas; mas como quien tiene amor los mares y las montañas atraviesa fácilmente, la dice tales palabras: «¿Para qué te ascondes, niña gallarda? Que mis linces deseos paredes pasan.»_\"},{\"heading\":false,\"text\":\"(_Salen el_ COMENDADOR, FLORES, ORTUÑO _y_ CIMBRANOS.)\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Estése la boda queda, y no se alborote nadie.\"},{\"heading\":false,\"text\":\"JUAN [ROJO]\"},{\"heading\":false,\"text\":\"No es juego aqueste, señor, y basta que tú lo mandes. ¿Quieres lugar? ¿Cómo vienes con tu belicoso alarde? ¿Venciste? Mas ¿qué pregunto?\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"¡Muerto soy! ¡Cielos, libradme!\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Huye por aquí, Frondoso.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Eso no; prendelde, atalde.\"},{\"heading\":false,\"text\":\"JUAN [ROJO]\"},{\"heading\":false,\"text\":\"Date, muchacho, a prisión.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Pues ¿quieres tú que me maten?\"},{\"heading\":false,\"text\":\"JUAN [ROJO]\"},{\"heading\":false,\"text\":\"¿Por qué?\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"No soy hombre yo que mato sin culpa a nadie; que si lo fuera, le hubieran pasado de parte a parte esos soldados que traigo. Llevarle mando a la cárcel, donde la culpa que tiene sentencie su mismo padre.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Señor, mirad que se casa.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¿Qué me obliga a que se case? ¿No hay otra gente en el pueblo?\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Si os ofendió perdonadle, por ser vos quien sois.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"No es cosa, Pascuala, en que yo soy parte. Es esto contra el maestre Téllez Girón, que Dios guarde; es contra toda su orden, es su honor, y es importante para el ejemplo, el castigo; que habrá otro día quien trate de alzar pendón contra él, pues ya sabéis que una tarde al comendador mayor (¡qué vasallos tan leales!) puso una ballesta al pecho.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Supuesto que el disculparle ya puede tocar a un suegro, no es mucho que en causas tales se descomponga con vos un hombre, en efecto, amante; porque si vos pretendéis su propia mujer quitarle, ¿qué mucho que la defienda?\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Majadero sois, alcalde.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Por vuestra virtud, señor.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Nunca yo quise quitarle su mujer, pues no lo era.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Si quisistes...--Y esto baste; que reyes hay en Castilla que nuevas órdenes hacen con que desórdenes quitan. Y harán mal cuando descansen de las guerras, en sufrir en sus villas y lugares a hombres tan poderosos por traer cruces tan grandes; póngasela el rey al pecho, que para pechos reales es esa insignia y no más.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¡Hola! La vara quitalde.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Tomad, señor, norabuena.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Pues con ella quiero dalle, como a caballo brioso.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Por señor os sufro. Dadme.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"¡A un viejo de palos das!\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Si le das porque es mi padre, ¿qué vengas en él de mí?\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Llevalda, y haced que guarden su persona diez soldados.\"},{\"heading\":false,\"text\":\"(_Vase él y los suyos._)\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Justicia del cielo baje. (_Vase._)\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Volvióse en luto la boda. (_Vase._)\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"¿No hay aquí un hombre que hable?\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Yo tengo ya mis azotes, que aun se ven los cardenales sin que un hombre vaya a Roma. Prueben otros a enojarle.\"},{\"heading\":false,\"text\":\"JUAN [ROJO]\"},{\"heading\":false,\"text\":\"Hablemos todos.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Señores, aquí todo el mundo calle. Como ruedas de salmón me puso los atabales.\"}]},{\"title\":\"Acto Tercero\",\"blocks\":[{\"heading\":false,\"text\":\"ACTO TERCERO DE FUENTE OVEJUNA\"},{\"heading\":false,\"text\":\"(_Salen_ ESTEBAN, ALONSO _y_ BARRILDO.)\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"¿No han venido a la junta?\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"No han venido.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Pues más apriesa nuestro daño corre.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Ya está lo más del pueblo prevenido.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Frondoso con prisiones en la torre, y mi hija Laurencia en tanto aprieto, si la piedad de Dios no los socorre...\"},{\"heading\":false,\"text\":\"(_Salen_ JUAN ROJO _y el_ REGIDOR.)\"},{\"heading\":false,\"text\":\"JUAN\"},{\"heading\":false,\"text\":\"¿De qué dais voces, cuando importa tanto a nuestro bien, Esteban, el secreto?\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Que doy tan pocas es mayor espanto.\"},{\"heading\":false,\"text\":\"(_Sale_ MENGO.)\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"También vengo yo a hallarme en esta junta.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Un hombre cuyas canas baña el llanto, labradores honrados, os pregunta qué obsequias[38] debe hacer toda esa gente a su patria sin honra, ya perdida. Y si se llaman honras justamente, ¿cómo se harán, si no hay entre nosotros hombre a quien este bárbaro no afrente? Respondedme: ¿hay alguno de vosotros que no esté lastimado en honra y vida? ¿No os lamentáis los unos de los otros? Pues si ya la tenéis todos perdida, ¿a qué aguardáis? ¿Qué desventura es ésta?\"},{\"heading\":false,\"text\":\"[38] _Obsequias_, funerales.\"},{\"heading\":false,\"text\":\"JUAN\"},{\"heading\":false,\"text\":\"La mayor que en el mundo fué sufrida. Mas pues ya se publica y manifiesta que en paz tienen los reyes a Castilla y su venida a Córdoba se apresta, vayan dos regidores a la villa, y echándose a sus pies pidan remedio.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"En tanto que Fernando, aquel que humilla a tantos enemigos, otro medio será mejor[39], pues no podrá, ocupado, hacemos bien, con tanta guerra en medio.\"},{\"heading\":false,\"text\":\"[39] La frase está construída como si hubiese escrito el autor: «En tanto que Fernando humilla a tantos enemigos.»\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"Si mi voto de vos fuera escuchado, desamparar la villa doy por voto.\"},{\"heading\":false,\"text\":\"JUAN\"},{\"heading\":false,\"text\":\"¿Cómo es posible en tiempo limitado?\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"A la fe, que si entiendo el alboroto, que ha de costar la junta alguna vida.\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"Ya, todo el árbol de paciencia roto, corre la nave de temor perdida. La hija quitan con tan gran fiereza a un hombre honrado, de quien es regida la patria en que vivís, y en la cabeza la vara quiebran tan injustamente. ¿Qué esclavo se trató con más bajeza?\"},{\"heading\":false,\"text\":\"JUAN\"},{\"heading\":false,\"text\":\"¿Qué es lo que quieres tú que el pueblo intente?\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"Morir, o dar la muerte a los tiranos, pues somos muchos, y ellos poca gente.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"¡Contra el señor las armas en las manos!\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"El rey solo es señor después del cielo, y no bárbaros hombres inhumanos. Si Dios ayuda nuestro justo celo, ¿qué nos ha de costar?\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Mirad, señores que vais en estas cosas con recelo. Puesto que[40] por los simples labradores estoy aquí, que más injurias pasan, más cuerdo represento sus temores.\"},{\"heading\":false,\"text\":\"[40] Aunque.\"},{\"heading\":false,\"text\":\"JUAN\"},{\"heading\":false,\"text\":\"Si nuestras desventuras se compasan, para perder las vidas, qué aguardamos Las casas y las viñas nos abrasan: tiranos son; a la venganza vamos.\"},{\"heading\":false,\"text\":\"(_Sale_ LAURENCIA, _desmelenada._)\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Dejadme entrar, que bien puedo en consejo de los hombres; que bien puede una mujer, si no a dar voto a dar voces. ¿Conocéisme?\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"¡Santo cielo! ¿No es mi hija?\"},{\"heading\":false,\"text\":\"JUAN\"},{\"heading\":false,\"text\":\"¿No conoces A Laurencia?\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Vengo tal, que mi diferencia os pone en contingencia quién soy.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"¡Hija mía!\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"No me nombres tu hija.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"¿Por qué, mis ojos? ¿Por qué?\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Por muchas razones, y sean las principales, porque dejas que me roben tiranos sin que me vengues, traidores sin que me cobres. Aun no era yo de Frondoso, para que digas que tome, como marido, venganza; que aquí por tu cuenta corre; que en tanto que de las bodas no haya llegado la noche, del padre, y no del marido, la obligación presupone; que en tanto que no me entregan una joya, aunque la compren, no ha de correr por mi cuenta las guardas ni los ladrones. Llevóme de vuestros ojos a su casa Fernán Gómez: la oveja al lobo dejáis, como cobardes pastores. ¿Qué dagas no vi en mi pecho? ¡Qué desatinos enormes, qué palabras, qué amenazas, y qué delitos atroces, por rendir mi castidad a sus apetitos torpes! Mis cabellos, ¿no lo dicen? ¿No se ven aquí los golpes, de la sangre y las señales? ¿Vosotros sois hombres nobles? ¿Vosotros padres y deudos? ¿Vosotros, que no se os rompen las entrañas de dolor, de verme en tantos dolores? Ovejas sois, bien lo dice de Fuente Ovejuna el nombre. Dadme unas armas a mí, pues sois piedras, pues sois bronces, pues sois jaspes, pues sois tigres... --Tigres no, porque feroces siguen quien roba sus hijos, matando los cazadores antes que entren por el mar y por sus ondas se arrojen. Liebres cobardes nacistes; bárbaros sois, no españoles. Gallinas, ¡vuestras mujeres sufrís que otros hombres gocen! Poneos ruecas en la cinta. ¿Para qué os ceñís estoques? ¡Vive Dios, que he de trazar que solas mujeres cobren la honra de estos tiranos, la sangre de estos traidores, y que os han de tirar piedras, hilanderas, maricones, amujerados, cobardes, y que mañana os adornen nuestras tocas y basquiñas, solimanes y colores! A Frondoso quiere ya, sin sentencia, sin pregones, colgar el comendador del almena de una torre; de todos hará lo mismo; y yo me huelgo, medio-hombres, por que quede sin mujeres esta villa honrada, y torne aquel siglo de amazonas, eterno espanto del orbe.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Yo, hija, no soy de aquellos que permiten que los nombres con esos títulos viles. Iré solo, si se pone todo el mundo contra mí.\"},{\"heading\":false,\"text\":\"JUAN\"},{\"heading\":false,\"text\":\"Y yo, por más que me asombre la grandeza del contrario.\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"Muramos todos.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Descoge un lienzo al viento en un palo, y mueran estos inormes[41].\"},{\"heading\":false,\"text\":\"[41] _Inorme_, forma anticuada de «enorme».\"},{\"heading\":false,\"text\":\"JUAN\"},{\"heading\":false,\"text\":\"¿Qué orden pensáis tener?\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Ir a matarle sin orden. Juntad el pueblo a una voz; que todos están conformes en que los tiranos mueran.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Tomad espadas, lanzones, ballestas, chuzos y palos.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"¡Los reyes nuestros señores vivan!\"},{\"heading\":false,\"text\":\"TODOS\"},{\"heading\":false,\"text\":\"¡Vivan muchos años!\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"¡Mueran tiranos traidores!\"},{\"heading\":false,\"text\":\"TODOS\"},{\"heading\":false,\"text\":\"¡Traidores tiranos mueran!\"},{\"heading\":false,\"text\":\"(_Vanse todos._)\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Caminad, que el cielo os oye. --¡Ah mujeres de la villa! ¡Acudid, por que se cobre vuestro honor, acudid todas!\"},{\"heading\":false,\"text\":\"(_Salen_ PASCUALA, JACINTA _y otras mujeres_)\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"¿Qué es esto? ¿De qué das voces?\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¿No veis cómo todos van a matar a Fernán Gómez, y hombres, mozos y muchachos, furiosos, al hecho corren? ¿Será bien que solos ellos de esta hazaña el honor gocen, pues no son de las mujeres sus agravios los menores?\"},{\"heading\":false,\"text\":\"JACINTA\"},{\"heading\":false,\"text\":\"Di, pues, ¿qué es lo que pretendes?\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Que puestas todas en orden, acometamos a un hecho que dé espanto a todo el orbe. Jacinta, tu grande agravio, que sea cabo[42]; responde de una escuadra de mujeres.\"},{\"heading\":false,\"text\":\"[42] _Cabo_, el jefe.\"},{\"heading\":false,\"text\":\"JACINTA\"},{\"heading\":false,\"text\":\"No son los tuyos menores.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Pascuala, alférez serás.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Pues déjame que enarbole en un asta la bandera: verás si merezco el nombre.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"No hay espacio para eso, pues la dicha nos socorre: bien nos basta que llevemos nuestras tocas por pendones.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Nombremos un capitán.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Eso no.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"¿Por qué?\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Que adonde asiste mi gran valor, no hay Cides ni Rodamontes.\"},{\"heading\":false,\"text\":\"(_Vanse._)\"},{\"heading\":false,\"text\":\"(_Sale_ FRONDOSO, _atadas las manos_; FLORES, ORTUÑO, CIMBRANOS _y el_ COMENDADOR.)\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"De ese cordel que de las manos sobra quiero que le colguéis, por mayor pena.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"¡Qué nombre, gran señor, tu sangre cobra!\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Colgadle luego en la primera almena.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Nunca fué mi intención poner por obra tu muerte entonces.\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Grande ruido suena.\"},{\"heading\":false,\"text\":\"(_Ruido suene._)\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¿Ruido?\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Y de manera que interrumpen tu justicia, señor.\"},{\"heading\":false,\"text\":\"ORTUÑO\"},{\"heading\":false,\"text\":\"Las puertas rompen.\"},{\"heading\":false,\"text\":\"(_Ruido._)\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¡La puerta de mi casa, y siendo casa de la encomienda!\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"El pueblo junto viene.\"},{\"heading\":false,\"text\":\"JUAN (_Dentro._)\"},{\"heading\":false,\"text\":\"Rompe, derriba, hunde, quema, abrasa.\"},{\"heading\":false,\"text\":\"ORTUÑO\"},{\"heading\":false,\"text\":\"Un popular motín mal se detiene.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¡El pueblo contra mí!\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"La furia pasa tan adelante, que las puertas tiene echadas por la tierra.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Desatalde. Templa, Frondoso, ese villano alcalde.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Yo voy, señor; que amor les ha movido.\"},{\"heading\":false,\"text\":\"(_Vase._)\"},{\"heading\":false,\"text\":\"MENGO (_Dentro._)\"},{\"heading\":false,\"text\":\"¡Vivan Fernando y Isabel, y mueran los traidores!\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Señor, por Dios te pido que no te hallen aquí.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Si perseveran, este aposento es fuerte y defendido. Ellos se volverán.\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Cuando se alteran los pueblos agraviados, y resuelven, nunca sin sangre o sin venganza vuelven.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"En esta puerta, así como rastrillo, su furor con las armas defendamos.\"},{\"heading\":false,\"text\":\"FRONDOSO (_Dentro._)\"},{\"heading\":false,\"text\":\"¡Viva Fuente Ovejuna!\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¡Qué caudillo! Estoy porque a su furia acometamos.\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"De la tuya, señor, me maravillo.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Ya el tirano y los cómplices miramos. ¡Fuente Ovejuna, y los tiranos mueran!\"},{\"heading\":false,\"text\":\"(_Salen todos._)\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Pueblo, esperad.\"},{\"heading\":false,\"text\":\"TODOS\"},{\"heading\":false,\"text\":\"Agravios nunca esperan.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Decídmelos a mí, que iré pagando a fe de caballero esos errores.\"},{\"heading\":false,\"text\":\"TODOS\"},{\"heading\":false,\"text\":\"¡Fuente Ovejuna! ¡Viva el rey Fernando! ¡Mueran malos cristianos y traidores!\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"¿No me queréis oír? Yo estoy hablando; yo soy vuestro señor.\"},{\"heading\":false,\"text\":\"TODOS\"},{\"heading\":false,\"text\":\"Nuestros señores son los Reyes Católicos.\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Espera.\"},{\"heading\":false,\"text\":\"TODOS\"},{\"heading\":false,\"text\":\"¡Fuente Ovejuna, y Fernán Gómez muera!\"},{\"heading\":false,\"text\":\"(_Vanse, y salen las mujeres armadas._)\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Parad en este puesto de esperanzas soldados atrevidos, no mujeres.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"¿Lo[s] que mujeres son en las venganzas, en él beban su sangre es bien que esperes?\"},{\"heading\":false,\"text\":\"JACINTA\"},{\"heading\":false,\"text\":\"Su cuerpo recojamos en las lanzas.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Todas son de esos mismos pareceres.\"},{\"heading\":false,\"text\":\"ESTEBAN (_Dentro._)\"},{\"heading\":false,\"text\":\"¡Muere, traidor comendador!\"},{\"heading\":false,\"text\":\"COMENDADOR\"},{\"heading\":false,\"text\":\"Ya muero. ¡Piedad, Señor, que en tu clemencia espero!\"},{\"heading\":false,\"text\":\"BARRILDO (_Dentro._)\"},{\"heading\":false,\"text\":\"Aquí está Flores.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Dale a ese bellaco; que ese fué el que me dió dos mil azotes.\"},{\"heading\":false,\"text\":\"FRONDOSO (_Dentro._)\"},{\"heading\":false,\"text\":\"No me vengo si el alma no le saco.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"No excusamos entrar.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"No te alborotes. Bien es guardar la puerta.\"},{\"heading\":false,\"text\":\"BARRILDO (_Dentro._)\"},{\"heading\":false,\"text\":\"No me aplaco. ¡Con lágrimas agora, marquesotes!\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Pascuala, yo entro dentro; que la espada no ha de estar tan sujeta ni envainada.\"},{\"heading\":false,\"text\":\"(_Vase._)\"},{\"heading\":false,\"text\":\"BARRILDO [_Dentro._]\"},{\"heading\":false,\"text\":\"Aquí está Ortuño.\"},{\"heading\":false,\"text\":\"FRONDOSO [_Dentro._]\"},{\"heading\":false,\"text\":\"Córtale la cara.\"},{\"heading\":false,\"text\":\"(_Sale_ FLORES _huyendo_, _y_ MENGO _tras él._)\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"¡Mengo, piedad!, que no soy yo el culpado.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Cuando ser alcahuete no bastara, bastaba haberme el pícaro azotado.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Dánoslo a las mujeres, Mengo, para... Acaba por tu vida.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Ya está dado; que no le quiero yo mayor castigo.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Vengaré tus azotes.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Eso digo.\"},{\"heading\":false,\"text\":\"JACINTA\"},{\"heading\":false,\"text\":\"¡Ea, muera el traidor!\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"¡Entre mujeres!\"},{\"heading\":false,\"text\":\"JACINTA\"},{\"heading\":false,\"text\":\"¿No le viene muy ancho?\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"¿Aqueso lloras?\"},{\"heading\":false,\"text\":\"JACINTA\"},{\"heading\":false,\"text\":\"Muere, concertador de sus placeres.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"¡Ea, muera el traidor!\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"¡Piedad, señoras!\"},{\"heading\":false,\"text\":\"(_Sale_ ORTUÑO _huyendo de_ LAURENCIA.)\"},{\"heading\":false,\"text\":\"ORTUÑO\"},{\"heading\":false,\"text\":\"Mira que no soy yo...\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Ya sé quién eres.-- Entrad, teñid las armas vencedoras en estos viles.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Moriré matando.\"},{\"heading\":false,\"text\":\"TODAS\"},{\"heading\":false,\"text\":\"¡Fuente Ovejuna, y viva el rey Fernando!\"},{\"heading\":false,\"text\":\"(_Vanse, y salen el_ REY DON FERNANDO _y la_ REINA DOÑA ISABEL, _y_ DON MANRIQUE, _maestre._)\"},{\"heading\":false,\"text\":\"MANRIQUE\"},{\"heading\":false,\"text\":\"De modo la prevención fué, que el efeto esperado llegamos a ver logrado con poca contradición. Hubo poca resistencia; y supuesto que la hubiera, sin duda ninguna fuera de poca o ninguna esencia. Queda el de Cabra ocupado en conservación del puesto, por si volviere dispuesto a él el contrario osado.\"},{\"heading\":false,\"text\":\"REY\"},{\"heading\":false,\"text\":\"Discreto el acuerdo fué, y que asista es conveniente, y reformando la gente, el paso tomado esté. Que con eso se asegura no podernos hacer mal Alfonso, que en Portugal tomar la fuerza procura. Y el de Cabra es bien que esté en ese sitio asistente, y como tan diligente, muestras de su valor dé; porque con esto asegura el daño que nos recela, y como fiel centinela, el bien del reino procura.\"},{\"heading\":false,\"text\":\"(_Sale_ FLORES, _herido._)\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Católico rey Fernando, a quien el cielo concede la corona de Castilla, como a varón excelente; oye la mayor crueldad que se ha visto entre las gentes desde donde nace el sol hasta donde se oscurece.\"},{\"heading\":false,\"text\":\"REY\"},{\"heading\":false,\"text\":\"Repórtate.\"},{\"heading\":false,\"text\":\"FLORES\"},{\"heading\":false,\"text\":\"Rey supremo, mis heridas no consienten dilatar el triste caso, por ser mi vida tan breve. De Fuente Ovejuna vengo, donde, con pecho inclemente, los vecinos de la villa a su señor dieron muerte. Muerto Fernán Gómez queda por sus súbditos aleves; que vasallos indignados con leve causa se atreven. El título de tirano le acumula todo el plebe, y a la fuerza de esta voz el hecho fiero acometen; y quebrantando su casa, no atendiendo a que se ofrece por la fe de caballero a que pagará a quien debe, no sólo no le escucharon, pero con furia impaciente rompen el cruzado pecho con mil heridas crueles, y por las altas ventanas le hacen que al suelo vuele, adonde en picas y espadas le recogen las mujeres. Llévanle a una casa muerto, y, a porfía, quien más puede mesa su barba y cabello y apriesa su rostro hieren. En efeto fué la furia tan grande que en ellos crece, que las mayores tajadas las orejas a ser vienen. Sus armas borran con picas y a voces dicen que quieren tus reales armas fijar, porque aquéllas les ofenden. Saqueáronle la casa, cual si de enemigos fuese, y gozosos entre todos han repartido sus bienes. Lo dicho he visto escondido, porque mi infelice suerte en tal trance no permite que mi vida se perdiese; y así estuve todo el día hasta que la noche viene, y salir pude escondido para que cuenta te diese. Haz, señor, pues eres justo, que la justa pena lleven de tan riguroso caso los bárbaros delincuentes: mira que su sangre a voces pide que tu rigor prueben.\"},{\"heading\":false,\"text\":\"REY\"},{\"heading\":false,\"text\":\"Estar puedes confiado que sin castigo no queden. El triste suceso ha sido tal, que admirado me tiene, y que vaya luego un juez que lo averigüe conviene, y castigue a los culpados para ejemplo de las gentes. Vaya un capitán con él, por que seguridad lleve; que tan grande atrevimiento castigo ejemplar requiere; y curad a este soldado de las heridas que tiene.\"},{\"heading\":false,\"text\":\"(_Vanse, y salen los labradores y labradoras, con la cabeza de Fernán Gómez en una lanza._)\"},{\"heading\":false,\"text\":\"MÚSICOS\"},{\"heading\":false,\"text\":\"_¡Muchos años vivan Isabel y Fernando, y mueran los tiranos!_\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Diga su copla Frondoso.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Ya va mi copla a la fe; si le faltare algún pie, enmiéndelo el más curioso. «¡Vivan la bella Isabel, pues que para en uno son, él con ella, ella con él! A los cielos San Miguel lleve a los dos de las manos. ¡Vivan muchos años, y mueran los tiranos!»\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Diga Barrildo.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Ya va; que a fe que la he pensado.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Si la dices con cuidado, buena y rebuena será.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"«¡Vivan los reyes famosos muchos años, pues que tienen la vitoria, y a ser vienen nuestros dueños venturosos! Salgan siempre vitoriosos de gigantes y de enanos, y ¡mueran los tiranos!»\"},{\"heading\":false,\"text\":\"MÚSICOS\"},{\"heading\":false,\"text\":\"_¡Muchos años vivan!_, etc.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Diga Mengo.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Mengo diga.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Yo soy poeta donado.\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Mejor dirás lastimado el envés de la barriga.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"«Una mañana en domingo me mandó azotar aquél, de manera que el rabel daba espantoso respingo; pero agora que los pringo, ¡vivan los reyes cristiánigos, y mueran los tiránigos!»\"},{\"heading\":false,\"text\":\"MÚSICA\"},{\"heading\":false,\"text\":\"_¡Vivan muchos años!_\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Quita la cabeza allá.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Cara tiene de ahorcado.\"},{\"heading\":false,\"text\":\"(_Saca un escudo_ JUAN ROJO _con las armas [reales]_)\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"Ya las armas han llegado.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Mostrá las armas acá.\"},{\"heading\":false,\"text\":\"JUAN\"},{\"heading\":false,\"text\":\"¿Adónde se han de poner?\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"Aquí, en el ayuntamiento.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"¡Bravo escudo!\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"¡Qué contento!\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Ya comienza a amanecer, con este sol, nuestro día.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"¡Vivan Castilla y León, y las barras de Aragón, y muera la tiranía! Advertid, Fuente Ovejuna, a las palabras de un viejo; que el admitir su consejo no ha dañado vez ninguna. Los reyes han de querer averiguar este caso, y más tan cerca del paso y jornada que han de hacer. Concertaos todos a una en lo que habéis de decir.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"¿Qué es tu consejo?\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Morir diciendo _Fuente Ovejuna_, y a nadie saquen de aquí.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Es el camino derecho. Fuente Ovejuna lo ha hecho.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"¿Queréis responder así?\"},{\"heading\":false,\"text\":\"TODOS\"},{\"heading\":false,\"text\":\"Sí.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Ahora[43], pues; yo quiero ser agora el pesquisidor, para ensayarnos mejor en lo que habemos de hacer. Sea Mengo el que esté puesto en el tormento.\"},{\"heading\":false,\"text\":\"[43] _El original_, agora.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"¿No hallaste otro más flaco?\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"¿Pensaste que era de veras?\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Di presto.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"¿Quién mató al comendador?\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Fuente Ovejuna lo hizo.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Perro, ¿si te martirizo?\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Aunque me matéis, señor.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Confiesa, ladrón.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Confieso.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Pues ¿quién fué?\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Fuente Ovejuna.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Dadle otra vuelta.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Es ninguna.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Cagajón para el proceso.\"},{\"heading\":false,\"text\":\"(_Sale el_ REGIDOR.)\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"¿Qué hacéis de esta suerte aquí?\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"¿Qué ha sucedido, Cuadrado?\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"Pesquisidor ha llegado.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Echá todos por ahí.\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"Con él viene un capitán.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Venga el diablo: ya sabéis lo que responder tenéis.\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"El pueblo prendiendo van, sin dejar alma ninguna.\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Que no hay que tener temor. ¿Quién mató al comendador, Mengo?\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"¿Quién? Fuente Ovejuna.\"},{\"heading\":false,\"text\":\"(_Vanse, y salen el_ MAESTRE _y_ UN SOLDADO.)\"},{\"heading\":false,\"text\":\"MAESTRE\"},{\"heading\":false,\"text\":\"¡Que tal caso ha sucedido! Infelice fué su suerte. Estoy por darte la muerte por la nueva que has traído.\"},{\"heading\":false,\"text\":\"SOLDADO\"},{\"heading\":false,\"text\":\"Yo, señor, soy mensajero, y enojarte no es mi intento.\"},{\"heading\":false,\"text\":\"MAESTRE\"},{\"heading\":false,\"text\":\"¡Que a tal tuvo atrevimiento un pueblo enojado y fiero! Iré con quinientos hombres, y la villa he de asolar; en ella no ha de quedar ni aun memoria de los hombres.\"},{\"heading\":false,\"text\":\"SOLDADO\"},{\"heading\":false,\"text\":\"Señor, tu enojo reporta; porque ellos al rey se han dado, y no tener enojado al rey es lo que te importa.\"},{\"heading\":false,\"text\":\"MAESTRE\"},{\"heading\":false,\"text\":\"¿Cómo al rey se pueden dar, si de la encomienda son?\"},{\"heading\":false,\"text\":\"SOLDADO\"},{\"heading\":false,\"text\":\"Con él sobre esa razón podrás luego pleitear.\"},{\"heading\":false,\"text\":\"MAESTRE\"},{\"heading\":false,\"text\":\"Por pleito ¿cuándo salió lo que él[44] le entregó en sus manos? Son señores soberanos, y tal reconozco yo. Por saber que al rey se han dado me reportará mi enojo, y ver su presencia escojo por lo más bien acertado; que puesto que tenga culpa en casos de gravedad, en todo mi poca edad viene a ser quien me disculpa. Con vergüenza voy; mas es honor quien puede obligarme, y importa no descuidarme en tan honrado interés.\"},{\"heading\":false,\"text\":\"[44] El pueblo.\"},{\"heading\":false,\"text\":\"(_Vanse; sale_ LAURENCIA _sola._)\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Amando, recelar daño en lo amado, nueva pena de amor se considera; que quien en lo que ama daño espera aumenta en el temor nuevo cuidado. El firme pensamiento desvelado, si le aflige el temor, fácil se altera; que no es a firme fe pena ligera ver llevar el temor el bien robado. Mi esposo adoro; la ocasión que veo al temor de su daño me condena, si no le ayuda la felice suerte. Al bien suyo se inclina mi deseo: si está presente, está cierta mi pena; si está en ausencia, está cierta mi muerte.\"},{\"heading\":false,\"text\":\"(_Sale_ FRONDOSO.)\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"¡Mi Laurencia!\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¡Esposo amado! ¿Cómo a estar aquí te atreves?\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"¿Esas resistencias debes a mi amoroso cuidado?\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Mi bien, procura guardarte, porque tu daño recelo.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"No quiera, Laurencia, el cielo que tal llegue a disgustarte.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¿No temes ver el rigor que por los demás sucede, y el furor con que procede aqueste pesquisidor? Procura guardar la vida. Huye, tu daño no esperes.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"¿Cómo que procure quieres cosa tan mal recibida? ¿Es bien que los demás deje en el peligro presente y de tu vista me ausente? No me mandes que me aleje; porque no es puesto en razón que, por evitar mi daño, sea con mi sangre extraño en tan terrible ocasión.\"},{\"heading\":false,\"text\":\"(_Voces dentro._)\"},{\"heading\":false,\"text\":\"Voces parece que he oído, y son, si yo mal no siento, de alguno que dan tormento. Oye con atento oído.\"},{\"heading\":false,\"text\":\"(_Dice dentro el_ JUEZ, _y responden._)\"},{\"heading\":false,\"text\":\"JUEZ\"},{\"heading\":false,\"text\":\"Decid la verdad, buen viejo.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Un viejo, Laurencia mía, atormentan.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¡Qué porfía!\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Déjenme un poco.\"},{\"heading\":false,\"text\":\"JUEZ\"},{\"heading\":false,\"text\":\"Ya os dejo. Decid, ¿quién mató a Fernando?\"},{\"heading\":false,\"text\":\"ESTEBAN\"},{\"heading\":false,\"text\":\"Fuente Ovejuna lo hizo.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Tu nombre, padre, eternizo[45]. ...\"},{\"heading\":false,\"text\":\"[45] Falta un verso para la redondilla, pero no para el sentido.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"¡Bravo caso!\"},{\"heading\":false,\"text\":\"JUEZ\"},{\"heading\":false,\"text\":\"Ese muchacho aprieta. Perro, yo sé que lo sabes. Di quién fué. ¿Callas? Aprieta, borracho.\"},{\"heading\":false,\"text\":\"NIÑO\"},{\"heading\":false,\"text\":\"Fuente Ovejuna, señor.\"},{\"heading\":false,\"text\":\"JUEZ\"},{\"heading\":false,\"text\":\"¡Por vida del rey, villanos, que os ahorque con mis manos! ¿Quién mató al comendador?\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"¡Que a un niño le den tormento y niegue de aquesta suerte!\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¡Bravo pueblo!\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Bravo y fuerte.\"},{\"heading\":false,\"text\":\"JUEZ\"},{\"heading\":false,\"text\":\"Esa mujer al momento en ese potro tened. Dale esa mancuerda luego.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Ya está de cólera ciego.\"},{\"heading\":false,\"text\":\"JUEZ\"},{\"heading\":false,\"text\":\"Que os he de matar, creed, en este potro, villanos. ¿Quién mató al comendador?\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Fuente Ovejuna, señor.\"},{\"heading\":false,\"text\":\"JUEZ\"},{\"heading\":false,\"text\":\"¡Dale!\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Pensamientos vanos.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Pascuala niega, Frondoso.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Niegan niños: ¿qué te espantas?\"},{\"heading\":false,\"text\":\"JUEZ\"},{\"heading\":false,\"text\":\"Parece que los encantas. ¡Aprieta!\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"¡Ay cielo piadoso!\"},{\"heading\":false,\"text\":\"JUEZ\"},{\"heading\":false,\"text\":\"¡Aprieta, infame! ¿Estás sordo?\"},{\"heading\":false,\"text\":\"PASCUALA\"},{\"heading\":false,\"text\":\"Fuente Ovejuna lo hizo.\"},{\"heading\":false,\"text\":\"JUEZ\"},{\"heading\":false,\"text\":\"Traedme aquél más rollizo; ese desnudo, ese gordo.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¡Pobre Mengo! El es sin duda.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Temo que ha de confesar.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"¡Ay, ay!\"},{\"heading\":false,\"text\":\"JUEZ\"},{\"heading\":false,\"text\":\"Comienza a apretar.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"¡Ay!\"},{\"heading\":false,\"text\":\"JUEZ\"},{\"heading\":false,\"text\":\"¿Es menester ayuda?\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"¡Ay, ay!\"},{\"heading\":false,\"text\":\"JUEZ\"},{\"heading\":false,\"text\":\"¿Quién mató, villano, al señor comendador?\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"¡Ay, yo lo diré, señor!\"},{\"heading\":false,\"text\":\"JUEZ\"},{\"heading\":false,\"text\":\"Afloja un poco la mano.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"El confiesa.\"},{\"heading\":false,\"text\":\"JUEZ\"},{\"heading\":false,\"text\":\"Al palo aplica la espalda.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Quedo; que yo lo diré.\"},{\"heading\":false,\"text\":\"JUEZ\"},{\"heading\":false,\"text\":\"¿Quién lo mató?\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Señor, Fuente Ovejunica.\"},{\"heading\":false,\"text\":\"JUEZ\"},{\"heading\":false,\"text\":\"¿Hay tan gran bellaquería? Del dolor se están burlando. En quien estaba esperando, niega con mayor porfía. Dejaldos; que estoy cansado.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"¡Oh, Mengo, bien te haga Dios! Temor que tuve de dos, el tuyo me le ha quitado.\"},{\"heading\":false,\"text\":\"(_Salen con_ MENGO, BARRILDO _y el_ REGIDOR.)\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"¡Vítor, Mengo!\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"Y con razón.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"¡Mengo, vítor!\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Eso digo.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"¡Ay, ay!\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Toma, bebe, amigo. Come.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"¡Ay, ay! ¿Qué es?\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Diacitrón.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"¡Ay, ay!\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Echa de beber.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"...Ya va[46].\"},{\"heading\":false,\"text\":\"[46] Falta el principio del verso.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Bien lo cuela. Bueno está.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Dale otra vez a comer.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"¡Ay, ay!\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Esta va por mí.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Solemnemente lo embebe.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"El que bien niega bien bebe.\"},{\"heading\":false,\"text\":\"REGIDOR\"},{\"heading\":false,\"text\":\"¿Quieres otra?\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"¡Ay, ay! Sí, sí.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Bebe, que bien lo mereces.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"A vez por vuelta las cuela.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Arrópale, que se hiela.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"¿Quieres más?\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Sí, otras tres veces. ¡Ay, ay!\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Si hay vino pregunta.\"},{\"heading\":false,\"text\":\"BARRILDO\"},{\"heading\":false,\"text\":\"Sí hay: bebe a tu placer; que quien niega ha de beber. ¿Qué tiene?\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Una cierta punta[47]. Vamos; que me arromadizo.\"},{\"heading\":false,\"text\":\"[47] _Punta_, sabor agrio del vino. Mengo ha debido hacer antes un gesto de desagrado.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Que [beba][48], que éste es mejor. ¿Quién mató al comendador?\"},{\"heading\":false,\"text\":\"[48] _El original_, lea.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"Fuente Ovejunica lo hizo.\"},{\"heading\":false,\"text\":\"(_Vanse._)\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Justo es que honores le den. Pero decidme, mi amor, ¿quién mató al comendador?\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Fuente Ovejuna, mi bien.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"¿Quién le mató?\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Dasme espanto. Pues Fuente Ovejuna fué.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Y yo ¿con qué te maté?\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¿Con qué? Con quererte tanto.\"},{\"heading\":false,\"text\":\"(_Vanse, y salen el_ REY _y la_ REINA _y_ MANRIQUE [_luego_].)\"},{\"heading\":false,\"text\":\"ISABEL\"},{\"heading\":false,\"text\":\"No entendí, señor, hallaros aquí, y es buena mi suerte.\"},{\"heading\":false,\"text\":\"REY\"},{\"heading\":false,\"text\":\"En nueva gloria convierte mi vista el bien de miraros. Iba a Portugal de paso, y llegar aquí fué fuerza.\"},{\"heading\":false,\"text\":\"ISABEL\"},{\"heading\":false,\"text\":\"Vuestra majestad le tuerza, siendo conveniente el caso.\"},{\"heading\":false,\"text\":\"REY\"},{\"heading\":false,\"text\":\"¿Cómo dejáis a Castilla?\"},{\"heading\":false,\"text\":\"ISABEL\"},{\"heading\":false,\"text\":\"En paz queda, quieta y llana.\"},{\"heading\":false,\"text\":\"REY\"},{\"heading\":false,\"text\":\"Siendo vos la que la allana no lo tengo a maravilla.\"},{\"heading\":false,\"text\":\"(_Sale_ DON MANRIQUE.)\"},{\"heading\":false,\"text\":\"MANRIQUE\"},{\"heading\":false,\"text\":\"Para ver vuestra presencia el maestre de Calatrava, que aquí de llegar acaba, pide que le deis licencia.\"},{\"heading\":false,\"text\":\"ISABEL\"},{\"heading\":false,\"text\":\"Verle tenía deseado.\"},{\"heading\":false,\"text\":\"MANRIQUE\"},{\"heading\":false,\"text\":\"Mi fe, señora, os empeño, que, aunque es en edad pequeño, es valeroso soldado.\"},{\"heading\":false,\"text\":\"([_Vase, y_] _sale el_ MAESTRE.)\"},{\"heading\":false,\"text\":\"MAESTRE\"},{\"heading\":false,\"text\":\"Rodrigo Téllez Girón, que de loaros no acaba, maestre de Calatrava, os pide, humilde, perdón. Confieso que fuí engañado, y que excedí de lo justo en cosas de vuestro gusto, como mal aconsejado. El consejo de Fernando y el interés me engañó, injusto fiel; y ansí, yo perdón, humilde, os demando. Y si recebir merezco esta merced que suplico, desde aquí me certifico en que a serviros me ofrezco, y que en aquesta jornada de Granada, adonde vais, os prometo que veáis el valor que hay en mi espada; donde sacándola apenas, dándoles fieras congojas, plantaré mis cruces rojas sobre sus altas almenas; y más quinientos soldados en serviros emplearé, junto con la firma y fe de en mi vida disgustaros.\"},{\"heading\":false,\"text\":\"REY\"},{\"heading\":false,\"text\":\"Alzad, maestre, del suelo; que siempre que hayáis venido seréis muy bien recibido.\"},{\"heading\":false,\"text\":\"MAESTRE\"},{\"heading\":false,\"text\":\"Sois de afligidos consuelo.\"},{\"heading\":false,\"text\":\"ISABEL\"},{\"heading\":false,\"text\":\"Vos, con valor peregrino, sabéis bien decir y hacer.\"},{\"heading\":false,\"text\":\"MAESTRE\"},{\"heading\":false,\"text\":\"Vos sois una bella Ester, y vos un Jerjes divino.\"},{\"heading\":false,\"text\":\"(_Sale_ MANRIQUE.)\"},{\"heading\":false,\"text\":\"MANRIQUE\"},{\"heading\":false,\"text\":\"Señor, el pesquisidor que a Fuente Ovejuna ha ido, con el despacho ha venido a verse ante tu valor.\"},{\"heading\":false,\"text\":\"REY\"},{\"heading\":false,\"text\":\"Sed juez de estos agresores.\"},{\"heading\":false,\"text\":\"MAESTRE\"},{\"heading\":false,\"text\":\"Si a vos, señor, no mirara, sin duda les enseñara a matar comendadores.\"},{\"heading\":false,\"text\":\"REY\"},{\"heading\":false,\"text\":\"Eso ya no os toca a vos.\"},{\"heading\":false,\"text\":\"ISABEL\"},{\"heading\":false,\"text\":\"Yo confieso que he de ver el cargo en vuestro poder, si me lo concede Dios.\"},{\"heading\":false,\"text\":\"(_Sale el_ JUEZ.)\"},{\"heading\":false,\"text\":\"JUEZ\"},{\"heading\":false,\"text\":\"A Fuente Ovejuna fuí de la suerte que has mandado, y con especial cuidado y diligencia asistí. Haciendo averiguación del cometido delito, una hoja no se ha escrito que sea en comprobación; porque conformes a una, con un valeroso pecho, en pidiendo quién lo ha hecho, responden: «Fuente Ovejuna». Trecientos he atormentado con no pequeño rigor, y te prometo, señor, que más que esto no he sacado. Hasta niños de diez años al potro arrimé, y no ha sido posible haberlo inquirido ni por halagos ni engaños. Y pues tan mal se acomoda el poderlo averiguar, o los has de perdonar, o matar la villa toda. Todos vienen ante ti para más certificarte: de ellos podrás informarte.\"},{\"heading\":false,\"text\":\"REY\"},{\"heading\":false,\"text\":\"Que entren, pues vienen, les di.\"},{\"heading\":false,\"text\":\"(_Salen los dos_ ALCALDES, FRONDOSO, _las mujeres y los villanos que quisieren._)\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"¿Aquestos los reyes son?\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Y en Castilla poderosos.\"},{\"heading\":false,\"text\":\"LAURENCIA\"},{\"heading\":false,\"text\":\"Por mi fe, que son hermosos: ¡bendígalos San Antón!\"},{\"heading\":false,\"text\":\"ISABEL\"},{\"heading\":false,\"text\":\"¿Los agresores son éstos?\"},{\"heading\":false,\"text\":\"ALCALDE ESTEBAN\"},{\"heading\":false,\"text\":\"Fuente Ovejuna, señora, que humildes llegan agora para serviros dispuestos. La sobrada tiranía y el insufrible rigor del muerto comendador, que mil insultos hacía, fué el autor de tanto daño. Las haciendas nos robaba y las doncellas forzaba, siendo de piedad extraño.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Tanto, que aquesta zagala, que el cielo me ha concedido, en que tan dichoso he sido que nadie en dicha me iguala, cuando conmigo casó, aquella noche primera, mejor que si suya fuera, a su casa la llevó; y a no saberse guardar ella, que en virtud florece, ya manifiesto parece lo que pudiera pasar.\"},{\"heading\":false,\"text\":\"MENGO\"},{\"heading\":false,\"text\":\"¿No es ya tiempo que hable yo? Si me dais licencia, entiendo que os admiraréis, sabiendo del modo que me trató. Porque quise defender una moza de su gente, que con término insolente fuerza la querían hacer, aquel perverso Nerón, de manera me ha tratado, que el reverso me ha dejado como rueda de salmón. Tocaron mis atabales tres hombres con tal porfía, que aun pienso que todavía me duran los cardenales. Gasté en este mal prolijo, por que el cuero se me curta, polvos de arrayán y murta más que vale mi cortijo.\"},{\"heading\":false,\"text\":\"ALCALDE ESTEBAN\"},{\"heading\":false,\"text\":\"Señor, tuyos ser queremos. Rey nuestro eres natural, y con título de tal ya tus armas puesto habemos. Esperamos tu clemencia, y que veas, esperamos, que en este caso te damos por abono la inocencia.\"},{\"heading\":false,\"text\":\"REY\"},{\"heading\":false,\"text\":\"Pues no puede averiguarse el suceso por escrito, aunque fué grave el delito, por fuerza ha de perdonarse. Y la villa es bien se quede en mí, pues de mí se vale, hasta ver si acaso sale comendador que la herede.\"},{\"heading\":false,\"text\":\"FRONDOSO\"},{\"heading\":false,\"text\":\"Su majestad habla, en fin, como quien tanto ha acertado. Y aquí, discreto senado, FUENTE OVEJUNA da fin.\"}]}]', 'es', 'https://www.gutenberg.org/ebooks/60198', '{}');
INSERT INTO libros (id, titulo, autor, genero, cover, secciones, idioma, fuente, introducciones) VALUES (61851, 'El crimen y el castigo', 'Fíodor Dostoyevski', 'misterio', 'https://www.gutenberg.org/cache/epub/61851/pg61851.cover.medium.jpg', '[{\"title\":\"primera parte — capítulo I\",\"blocks\":[{\"heading\":false,\"text\":\"Una tarde muy calurosa de principios de julio, salió del cuartito que ocupaba, junto al techo de una gran casa de cinco pisos, un joven, que, lentamente y con aire irresoluto, se dirigió hacia el puente de K***.\"},{\"heading\":false,\"text\":\"Tuvo suerte, al bajar la escalera, de no encontrarse a su patrona que habitaba en el piso cuarto, y cuya cocina, que tenía la puerta constantemente sin cerrar, daba a la escalera. Cuando salía el joven, había de pasar forzosamente bajo el fuego del enemigo, y cada vez que esto ocurría experimentaba aquél una molesta sensación de temor que, humillándole, le hacía fruncir el entrecejo. Tenía una deuda no pequeña con su patrona y le daba vergüenza el encontrarla.\"},{\"heading\":false,\"text\":\"No quiere esto decir que la desgracia le intimidase o abatiese; nada de eso; pero la verdad era que, desde hacía algún tiempo, se hallaba en cierto estado de irritación nerviosa, rayano con la hipocondría. A fuerza de aislarse y de encerrarse en sí mismo, acabó por huir, no solamente de su patrona, sino de toda relación con sus semejantes.\"},{\"heading\":false,\"text\":\"La pobreza le aniquilaba y, sin embargo, dejó de ser sensible a sus efectos. Había renunciado completamente a sus ocupaciones cotidianas y, en el fondo, se burlaba de su patrona y de las medidas que ésta pudiera tomar en contra suya. Pero el verse detenido por ella en la escalera, el oír las tonterías que pudiera dirigirle, el sufrir reclamaciones, amenazas, lamentos y verse obligado a responder con pretextos y mentiras, eran para él cosas insoportables. No; era preferible no ser visto de nadie, y deslizarse como un felino por la escalera.\"},{\"heading\":false,\"text\":\"Esta vez él mismo se asombró, cuando estuvo en la calle, del temor de encontrar a su acreedora.\"},{\"heading\":false,\"text\":\"«¿Debo asustarme de semejantes simplezas cuando proyecto un golpe tan atrevido?--se decía, riendo de un modo extraño--. Sí... el hombre lo tiene todo entre las manos y lo deja que se le escape en sus propias narices tan sólo a causa de su holgazanería... Es un axioma... Me gustaría saber qué es lo que le da más miedo a la gente... Creo que temen, sobre todo, lo que les saca de sus costumbres habituales... Pero hablo demasiado... Tal vez por el hábito adquirido de monologar con exceso no hago nada... Verdad es que con la misma razón podría decir que es a causa de no hacer nada por lo que hablo tanto. Un mes completo hace que he tomado la costumbre de monologar acurrucado durante días enteros en un rincón, con el espíritu ocupado con mil quimeras. Veamos: ¿por qué me doy esta carrera? ¿Soy capaz de _eso_? ¿Es serio _eso_? No, de ningún modo; patrañas que entretienen mi imaginación, puras fantasías.»\"},{\"heading\":false,\"text\":\"Hacía en la calle un calor sofocante. La multitud, la vista de la cal, de los ladrillos, de los andamios y esta fetidez especial, tan conocida de los habitantes de San Petersburgo que no pueden alquilar una casa de campo durante el verano, todo contribuía a irritar cada vez más los nervios del joven. El insoportable olor de las tabernas y figones, muy numerosos en aquellas partes de la ciudad, y los borrachos que a cada paso se encontraba, aunque aquel era día laborable, acabaron por dar al cuadro un repugnante colorido.\"},{\"heading\":false,\"text\":\"Hubo un momento en que los finos rasgos de la fisonomía de nuestro héroe expresaron amargo disgusto. Digamos con este motivo que no carecía de ventajas físicas; era alto, enjuto y bien formado; tenía el cabello castaño y hermosos ojos de color azul obscuro. Poco después cayó en profunda abstracción o más bien en una especie de sopor intelectual. Andaba sin reparar en los objetos que encontraba al paso y sin querer reparar en ellos. De vez en cuando murmuraba algunas palabras; porque, como él reconocía poco antes, tenía por costumbre el monologar. En aquel momento echó de ver que se embrollaban sus ideas, y que estaba muy débil: puede decirse que había pasado dos días sin comer.\"},{\"heading\":false,\"text\":\"Iba tan miserablemente vestido, que otro que no hubiera sido él habría tenido escrúpulos para salir en pleno día con semejantes andrajos. A decir verdad, en aquel barrio se podía ir de cualquier modo. En los alrededores del Mercado del Heno, en esas calles del centro de San Petersburgo habitadas en su mayoría por obreros, a nadie asombra la más rara indumentaria. Pero tan arrogante desdén existía en el alma del joven, que, a pesar de su vergüenza, algunas veces cándida, no le daba ninguna de ostentar en la calle sus harapos.\"},{\"heading\":false,\"text\":\"Otra cosa hubiera sido de tropezar alguno de sus amigos o antiguos camaradas, de cuyo encuentro huía siempre... Sin embargo, se detuvo de pronto al notar, merced a esas palabras pronunciadas con voz burlona, que atraía la atención de los paseantes: «¡Ah, eh! un sombrero alemán». El que acababa de lanzar esta exclamación era un borracho a quien conducían, no sabemos dónde ni por qué, en una gran carreta.\"},{\"heading\":false,\"text\":\"Con un movimiento convulsivo, el aludido se quitó el sombrero y se puso a examinarlo. Era el tal sombrero de copa alta, comprado en casa de Zimmerman, pero ya muy estropeado, raído, agujereado, cubierto de abolladuras y de manchas, sin alas: en una palabra, horrible. A pesar de todo, lejos de mostrarse herido en su amor propio, el poseedor de aquella especie de gorro experimentó más inquietud que humillación.\"},{\"heading\":false,\"text\":\"--¡Ya me lo figuraba yo!--murmuró en su turbación--; ¡lo había presentido! Pero lo peor es que en una miseria como la mía, una tontería insignificante puede echar a perder el negocio. Sí; este sombrero produce demasiado efecto, y el efecto nace precisamente de que es ridículo. Para llevar estos harapos es indispensable usar gorra. Mejor que este mamarracho será una boina vieja. No hay quien lleve semejantes sombreros; de seguro que éste llama la atención a una versta[1] de distancia. Después lo recordarían y podría ser un indicio; lo importante es no llamar la atención de nadie... Las cosas pequeñas tienen siempre importancia; por ellas suele ser por las que uno se pierde.\"},{\"heading\":false,\"text\":\"[1] Es la milla rusa, que equivale poco más o menos a un kilómetro.\"},{\"heading\":false,\"text\":\"No tenía que ir muy lejos; sabía la distancia exacta que separaba su casa del sitio adonde se dirigía; setecientos pasos justos. Los había contado cuando su proyecto no era más que un vago sueño. En aquella época no creía que llegase el día en que se trocara lo imaginado en acción; se limitaba a acariciar en su mente una idea espantosa y seductora a la vez; pero desde aquel tiempo, un mes hacía, comenzaba a considerar las cosas de otro modo. Aunque en todos sus soliloquios se reprochase su falta de energía y su irresolución, habíase ido, sin embargo, habituando poco a poco e involuntariamente, en cierto modo, a mirar como posible la realización de su sueño, no obstante continuar dudando de sí mismo. En aquel momento iba a hacer el _ensayo general_ de su empresa, y a cada paso aumentaba su agitación.\"},{\"heading\":false,\"text\":\"Con el corazón desfallecido y el cuerpo agitado por nervioso temblor, se aproximó a una inmensa casa que daba de un lado al canal y del otro a la calle... Este edificio, dividido en multitud de cuartitos de alquiler, tenía por inquilinos industriales de todas las clases, sastres, cerrajeros, cocineras, alemanes de diferentes categorías, mujeres públicas y humildes empleados, etc. Un continuo hormiguero entraba y salía por las dos puertas. Tres o cuatro _dvorniks_[2] prestaban sus servicios en esta casa. Con gran satisfacción suya, el joven no encontró a nadie. Después de haber pasado el umbral sin ser notado, tomó por la escalera de la derecha.\"},{\"heading\":false,\"text\":\"[2] Porteros.\"},{\"heading\":false,\"text\":\"Conocía ya esta escalera angosta y tenebrosa cuya obscuridad no le desagradaba, pues así no eran de temer las miradas curiosas. «Si ahora tiemblo, ¿qué será cuando venga en serio?», no pudo menos de pensar cuando llegaba al cuarto piso. Allí le cerraron el paso antiguos soldados convertidos en mozos de cuerda; mudaban los muebles de uno de los cuartos, ocupado, el joven lo sabía, por un funcionario alemán y su familia.\"},{\"heading\":false,\"text\":\"--Gracias a la marcha del alemán, no habrá durante algún tiempo en ese rellano otro inquilino que la vieja. Esto es bueno saberlo... por lo que pueda suceder.\"},{\"heading\":false,\"text\":\"Así pensó, y tiró del llamador de la casa de la vieja. Débilmente sonó la campanilla, como si fuese de hojalata y no de cobre. Tales son en esas casas las campanillas de todos los pisos.\"},{\"heading\":false,\"text\":\"Sin duda había olvidado este detalle; aquel sonido particular debió de traerle repentinamente a la memoria algún recuerdo, porque el joven se estremeció y se alteraron sus nervios. Al cabo de un instante se entreabrió la puerta, y, por la estrecha abertura, la dueña de la casa examinó al recién venido con manifiesta desconfianza; brillaban sus ojillos como dos puntos luminosos en la obscuridad, pero al advertir que había gente en el descansillo se tranquilizó y abrió por completo la puerta. El joven entró en un sombrío recibimiento, dividido en dos por un tabique, tras del cual estaba la cocina. En pie delante del joven, la vieja callaba interrogándole con la vista. Era una mujer de sesenta años, pequeñuela y delgada, de nariz puntiaguda y de mirada maliciosa.\"},{\"heading\":false,\"text\":\"Tenía la cabeza descubierta, y los cabellos, que comenzaban a encanecer, relucían untados de aceite. Llevaba puesto al cuello, que era largo y delgado como la pata de una gallina, una tira de franela, y, a pesar del calor, habíase echado sobre los hombros un abrigo apolillado y amarillento. La vieja tosía a menudo. Debió de mirarla el joven de un modo singular, porque los ojos de la anciana recobraron bruscamente su expresión de desconfianza.\"},{\"heading\":false,\"text\":\"--Raskolnikoff, estudiante. Estuve aquí, en esta casa, hace un mes--se apresuró a decir el joven, medio inclinándose, porque había pensado que lo mejor era mostrarse afable.\"},{\"heading\":false,\"text\":\"--Sí, lo recuerdo, lo recuerdo--respondió la vieja, que no cesaba de mirarle con recelo.\"},{\"heading\":false,\"text\":\"--Pues bien... Vengo otra vez por un asuntillo del mismo género--continuó Raskolnikoff algo desconcertado y sorprendido de la desconfianza que inspiraba.\"},{\"heading\":false,\"text\":\"«Quizá esta mujer ha sido siempre lo mismo; pero la otra vez no lo eché de ver»--pensó el joven desagradablemente impresionado.\"},{\"heading\":false,\"text\":\"La vieja permaneció algún tiempo silenciosa como si reflexionase. Luego señaló la puerta de la sala a su visitante, y le dijo haciéndose a un lado para dejarle pasar delante de ella.\"},{\"heading\":false,\"text\":\"--Entre usted.\"},{\"heading\":false,\"text\":\"La salita en la cual fué introducido el joven, tenía tapizadas las paredes de color amarillo; en las ventanas, con cortinas de muselina, había tiestos de geranios; el sol poniente arrojaba sobre aquello viva claridad. «¡Sin embargo, _entonces_ brillaba el sol de la misma manera!»--dijo Raskolnikoff para su coleto y dirigió rápidamente una mirada en torno suyo, para darse cuenta de todos los objetos y grabarlos en la memoria. En la habitación no había nada de particular. Los muebles, de madera amarilla, eran muy viejos: un sofá con gran respaldo vuelto, una mesa de forma oval frente a frente del sofá, un lavabo y un espejo entre las dos ventanas, sillas a lo largo de las paredes, dos o tres grabados, sin valor, que representaban señoritas alemanas con pájaros en las manos; a esto se reducía el mobiliario.\"},{\"heading\":false,\"text\":\"En un rincón, delante de una pequeña imagen, ardía una lámpara; tanto los muebles como el suelo relucían de puro limpios.\"},{\"heading\":false,\"text\":\"«Es Isabel la que arregla todo esto»--pensó el joven.\"},{\"heading\":false,\"text\":\"En toda la habitación no se veía un grano de polvo.\"},{\"heading\":false,\"text\":\"«Es preciso venir a las casas de estas malas viejas viudas para ver tanta limpieza»--continuó monologando Raskolnikoff, y miró con curiosidad la cortina de indiana que ocultaba la puerta correspondiente a otra salita; en esta última, en la que jamás había entrado, estaban la cama y la cómoda de la vieja.\"},{\"heading\":false,\"text\":\"--¿Qué quiere usted?--preguntó secamente la dueña de la casa, que, habiendo seguido a su visitante, se colocó frente a él para examinarle de cerca.\"},{\"heading\":false,\"text\":\"--He venido a empeñar una cosa. Véala usted.\"},{\"heading\":false,\"text\":\"Y sacó del bolsillo un reloj de plata viejo y aplastado, que tenía grabado en la tapa un globo. La cadena era de acero.\"},{\"heading\":false,\"text\":\"--Aun no me ha devuelto usted la cantidad que le tengo prestada; anteayer cumplió el plazo.\"},{\"heading\":false,\"text\":\"--Le pagaré aún el interés del otro mes; tenga un poco de paciencia.\"},{\"heading\":false,\"text\":\"--Conste, amiguito, que puedo esperar, si quiero, o vender el objeto empeñado, si se me antoja...\"},{\"heading\":false,\"text\":\"--¿Qué me da por este reloj, Alena Ivanovna?\"},{\"heading\":false,\"text\":\"--Lo que trae aquí es una miseria; esto no vale nada. La otra vez le di a usted dos billetes pequeños por un anillo que se puede comprar nuevo en la joyería por rublo y medio.\"},{\"heading\":false,\"text\":\"--Déme usted cuatro rublos y lo desempeñaré. Perteneció a mi padre. Pronto recibiré dinero.\"},{\"heading\":false,\"text\":\"--Rublo y medio, y he de cobrar el interés por adelantado.\"},{\"heading\":false,\"text\":\"--¡Rublo y medio!--exclamó el joven.\"},{\"heading\":false,\"text\":\"--Acepta usted, ¿sí o no?\"},{\"heading\":false,\"text\":\"Y dicho esto, la mujer alargó el reloj al visitante. Este lo tomó e iba a retirarse, irritado, cuando reflexionó que la prestamista era su último recurso; además, había ido allí para otra cosa.\"},{\"heading\":false,\"text\":\"--¡Venga el dinero!--dijo con tono brutal.\"},{\"heading\":false,\"text\":\"La vieja buscó las llaves en el bolsillo y entró en la habitación contigua. Cuando el joven se quedó solo en la sala, se puso a escuchar, entregándose a diversos cálculos. A poco oyó cómo la usurera abría la cómoda.\"},{\"heading\":false,\"text\":\"«Debe ser el cajón de arriba--supuso Raskolnikoff--; ahora sé que lleva las llaves en el bolsillo derecho, y que están todas reunidas en una anilla de acero... Una de ellas es tres veces más gruesa que las otras, y tiene las guardas dentadas; esa llave no es de la cómoda, seguramente. Por lo tanto, debe haber alguna caja o alguna arca de hierro... Es curioso. Las llaves de las arcas de hierro son generalmente de esa forma... ¡Pero qué innoble es todo esto!...»\"},{\"heading\":false,\"text\":\"Volvió a entrar la vieja.\"},{\"heading\":false,\"text\":\"--Mire usted: como cobro una grivna[3] al mes por cada rublo, y empeña usted el reloj en rublo y medio le desquito 15 kopeks y queda satisfecho el interés por adelantado. Además, como usted me suplica que espere otro mes para devolverme los dos rublos que le tengo prestados, me debe usted por este concepto 20 kopeks, que, unidos a los 15 que le desquito, componen 35. Tengo, pues, que darle a usted un rublo y 15 kopeks. Aquí están.\"},{\"heading\":false,\"text\":\"[3] Moneda de diez kopeks equivalente a cuatro céntimos de franco. El rublo, que vale unos cuatro francos, se divide en diez kopeks.\"},{\"heading\":false,\"text\":\"--¡Cómo! ¿De modo que no me da usted ahora más que un rublo y 15 kopeks?\"},{\"heading\":false,\"text\":\"--Nada más tengo que darle a usted.\"},{\"heading\":false,\"text\":\"Tomó el joven el dinero sin discutir. Miraba a la vieja sin darse prisa a marcharse. Parecía tener intención de hacer algo; pero no sabía con precisión lo que deseaba...\"},{\"heading\":false,\"text\":\"--Es posible, Alena Ivanovna, que venga pronto con otra cosa... Una cigarrera... de plata... muy bonita... en cuanto me la devuelva un amigo a quien se la he prestado.\"},{\"heading\":false,\"text\":\"Dijo estas palabras con manifiesto embarazo.\"},{\"heading\":false,\"text\":\"--Pues bien, entonces hablaremos.\"},{\"heading\":false,\"text\":\"--Adiós... ¿Sigue usted viviendo sola, sin que su hermana le haga compañía?--preguntó con el tono más indiferente que le fué posible en el momento en que entraba en la antesala.\"},{\"heading\":false,\"text\":\"--¿Y qué le importa a usted mi hermana?\"},{\"heading\":false,\"text\":\"--Es verdad, se lo preguntaba a usted por decir algo... Adiós, Alena Ivanovna.\"},{\"heading\":false,\"text\":\"Raskolnikoff salió muy alterado; al bajar la escalera se detuvo muchas veces como rendido por sus emociones.\"},{\"heading\":false,\"text\":\"«¡Dios mío, cómo subleva el corazón todo esto!--exclamó cuando llegó a la calle--. ¡Es posible, es posible que yo...!\"},{\"heading\":false,\"text\":\"No, es una tontería, un absurdo--añadió resueltamente--. ¿Y ha podido ocurrírseme tan espantosa idea? ¿He de ser yo capaz de tal infamia? ¡Esto es odioso, innoble, repugnante!... ¿Y por espacio de un mes entero yo...?»\"},{\"heading\":false,\"text\":\"Para expresar la agitación que sentía, eran impotentes las exclamaciones y palabras. La sensación de inmenso disgusto que comenzó a oprimirle poco antes cuando se encaminaba a casa de la vieja, alcanzaba ahora intensidad tan grande que el joven no sabía cómo substraerse a semejante suplicio... Caminaba por la acera como un borracho, sin reparar en los transeuntes y tropezándose con ellos. En la calle siguiente volvió a recobrar ánimos y, mirando en torno suyo, advirtió que estaba cerca de una taberna; una escalera situada al nivel de la acera daba entrada a la cueva del establecimiento. Raskolnikoff vió salir en aquel instante a dos borrachos que se apoyaban el uno en el otro, injuriándose recíprocamente.\"},{\"heading\":false,\"text\":\"Vaciló el joven un instante, y después bajó la escalera. Nunca había entrado en una taberna; pero en aquel momento sentía vahídos, le atormentaba ardiente sed. Tenía ganas de beber cerveza fresca, y atribuía su debilidad a lo vacío del estómago. Después de sentarse en un rincón, sombrío y sucio, ante una mesita mugrienta, pidió cerveza y bebió el primer vaso con avidez.\"},{\"heading\":false,\"text\":\"Al punto sintió un gran alivio y se esclarecieron sus ideas.\"},{\"heading\":false,\"text\":\"«Todo esto es absurdo--se dijo ya confortado--. No había motivo para turbarse. ¡Es sencillamente efecto de un mal físico; con un vaso de cerveza y un bizcocho habría recobrado la fuerza de mi inteligencia, la precisión de mis ideas, el vigor de mis resoluciones! ¡Oh, qué insignificante es todo ello!»\"},{\"heading\":false,\"text\":\"A pesar de tan desdeñosa conclusión, estaba contento, como si se viese libre de un peso enorme, y dirigía miradas amistosas a las personas presentes. Pero al mismo tiempo sospechó que fuese ficticio aquel retorno a la energía.\"},{\"heading\":false,\"text\":\"Quedaba muy poca gente en la taberna; después de los dos borrachos, salió una banda de cinco músicos, y el establecimiento quedó silencioso; no había en él más que tres personas: un individuo algo ebrio, cuyo exterior indicaba un hombre de la clase media, estaba sentado delante de una botella de cerveza. Cerca de él, tendido en el banco, dormitaba un sujeto alto y grueso, de barba blanca, vestido con un largo levitón, y en completo estado de embriaguez.\"},{\"heading\":false,\"text\":\"De cuando en cuando parecía despertarse bruscamente; se ponía a hacer sonar los dedos, apartando los brazos y moviendo rápidamente el busto, sin levantarse del banco sobre el cual estaba echado. Tales gestos y ademanes servían de acompañamiento a una canción necia, de la que el hombre se esforzaba para recordar los versos:\"},{\"heading\":false,\"text\":\"Durante un año entero yo he acariciado. Du-ran-te un a-ño en-te-ro yo he a-ca-ri-cia-do a mi mujer.\"},{\"heading\":false,\"text\":\"O esta otra:\"},{\"heading\":false,\"text\":\"En la Podiatcheshaïa. He encontrado a mi vieja...\"},{\"heading\":false,\"text\":\"Nadie hacía caso de la alegría de aquel melómano. Su mismo compañero escuchaba todos aquellos gorjeos en silencio y haciendo muecas de disgusto. El tercer consumidor parecía un antiguo funcionario. Sentado aparte se llevaba de vez en cuando el vaso a los labios, mirando en derredor suyo; parecía que también él era presa de cierta agitación.\"}]},{\"title\":\"primera parte — capítulo II\",\"blocks\":[{\"heading\":false,\"text\":\"Raskolnikoff no estaba habituado a la multitud, y, conforme hemos dicho, desde hacía algún tiempo evitaba las compañías de sus semejantes; pero de repente se sintió atraído hacia los hombres. Cualquiera hubiera dicho que se operaba en él una especie de revolución y que el instinto de sociabilidad recobraba sus derechos. Entregado durante un mes completo a los sueños morbosos que la soledad engendra, tan fatigado estaba nuestro héroe de su aislamiento, que deseaba encontrarse, aunque no fuese más que un minuto, en un ambiente humano. Así, pues, por innoble que fuese aquella taberna, se sentó ante una de las mesas con verdadero placer.\"},{\"heading\":false,\"text\":\"El dueño del establecimiento estaba en otra habitación; pero salía y entraba frecuentemente en la sala. Desde el umbral, sus hermosas botas de altas y rojas vueltas atraían inmediatamente las miradas; llevaba un _paddiovka_ y un chaleco de raso negro horriblemente manchado de grasa y no tenía corbata; la cara parecía untada de aceite. Tras el mostrador se hallaba un mozo de catorce años, y otro más joven servía a los parroquianos. Expuestas en el aparador había varias vituallas, trozos de cohombro, galleta negra y bacalao cortado en pedazos; todo exhalaba olor a rancio. El calor era tan insoportable y la atmósfera estaba tan cargada de vapores alcohólicos, que parecía imposible pasar en aquella sala cinco minutos sin emborracharse.\"},{\"heading\":false,\"text\":\"Ocurre a veces que nos encontramos con desconocidos que nos interesan por completo a primera vista, antes de cruzar una palabra con ellos. Esto fué lo que sucedió a Raskolnikoff respecto al individuo que tenía el aspecto de un antiguo funcionario. Más tarde, al acordarse de esta primera impresión, el joven la atribuyó a un presentimiento. No quitaba los ojos del desconocido, sin duda porque este último no dejaba tampoco de mirarle, y parecía muy deseoso de trabar conversación con él. A los demás consumidores, y aun al mismo tabernero, los miraba con aire impertinente y altanero; eran, evidentemente, personas que estaban por debajo de él en condición social y en educación para que se dignase dirigirles la palabra.\"},{\"heading\":false,\"text\":\"Aquel hombre, que había pasado ya de los cincuenta años, era de mediana estatura y de complexión robusta. La cabeza, en gran parte calva, no conservaba más que algunos cabellos grises. El rostro largo, amarillo o casi verde, denunciaba hábitos de incontinencia; bajo los gruesos párpados brillaban unos ojillos rojizos, muy vivaces. Lo que más impresionaba en su fisonomía era la mirada en que la llama de la inteligencia y del entusiasmo se alternaba con no sé qué expresión de locura. Este personaje llevaba sobretodo negro, viejo, todo desgarrado, y no gustándole, sin duda, llevarle abierto, lo abrochaba correctamente con el único botón que el sobretodo tenía. El chaleco, de _nanquin_, dejaba ver la pechera de la camisa rota y llena de manchas. La ausencia de barba denunciaba en él al funcionario; pero debía haberse afeitado en una época bastante remota, porque le azuleaban las mejillas con un pelo muy espeso. Notábase en sus maneras cierta gravedad burocrática; pero, en aquel momento, parecía conmovido. Se revolvía los cabellos, y, de tiempo en tiempo, apoyaba los codos en la mesa pringosa, sin temor a mancharse las mangas agujereadas, y reclinaba la cabeza en las dos manos. Por último, comenzó a decir en voz alta y firme, mirando a Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¿Será una indiscreción por mi parte, señor, hablar con usted? Porque es lo cierto que, a pesar de la sencillez de su traje, mi experiencia distingue en usted un hombre muy bien educado y no un asiduo parroquiano de taberna. Siempre he dado mucha importancia a la educación, unida, por supuesto, a las cualidades del corazón. Pertenezco al _Tchin_[4]. Permítame usted que me presente: Simón Ivanovitch Marmeladoff, consejero titular. ¿Me es lícito preguntarle si ha pertenecido usted a la administración?\"},{\"heading\":false,\"text\":\"[4] Así llaman en Rusia a todos los que pertenecen de una manera u otra a la administración pública y constituyen como una casta especial.\"},{\"heading\":false,\"text\":\"--No, yo soy estudiante--respondió el joven sorprendido de aquel cortés lenguaje, y, sin embargo, molesto al ver que un desconocido le dirigía la palabra a quema ropa.\"},{\"heading\":false,\"text\":\"Aunque se hallaba en su cuarto de hora de sociabilidad, sintió en aquel momento que se le despertara el mal humor que solía experimentar cuando un extraño trataba de ponerse en relaciones con él.\"},{\"heading\":false,\"text\":\"--¿De modo que es usted estudiante, o lo sigue siendo?--repuso vivamente el funcionario--; es precisamente lo que yo pensaba. ¡Tengo olfato, señor, un olfato muy fino, gracias a mi larga experiencia!\"},{\"heading\":false,\"text\":\"Se llevó el dedo a la frente, indicando con este gesto la opinión que tenía de su capacidad cerebral.\"},{\"heading\":false,\"text\":\"--Pero, dispénseme... ¿no ha terminado usted realmente sus estudios?\"},{\"heading\":false,\"text\":\"Se levantó, tomó su vaso y fué a sentarse al lado del joven. A pesar de estar ebrio, hablaba distintamente y sin gran incoherencia. Al verle arrojarse sobre Raskolnikoff como sobre una presa, se hubiera podido suponer que él también, desde hacía un mes, no había despegado los labios ni para decir esta boca es mía.\"},{\"heading\":false,\"text\":\"--Señor--declaró con cierta solemnidad--, la pobreza no es un vicio, seguramente, de la misma manera que la embriaguez no es una virtud. Pero la indigencia, señor, la indigencia es un vicio de los peores. En la pobreza conserva uno el orgullo nativo de sus sentimientos; en la indigencia no se conserva nada, ni siquiera se le echa a uno a palos de la sociedad humana, sino a escobazos, que son más humillantes. Y hacen bien, porque el indigente está dispuesto a envilecerse y esto es lo que explica la taberna. Señor, hace un mes que Lebeziatnikoff pegó a mi mujer. Y dígame, ¿pegar a mi mujer no es herirme a mí en el punto más sensible? ¿Me comprende usted? Permítame que le haga otra pregunta, ¡oh! por simple curiosidad: ¿Ha pasado usted alguna noche en el Neva en los barcos de heno?\"},{\"heading\":false,\"text\":\"--No, jamás--contestó Raskolnikoff--; ¿por qué me lo pregunta usted?\"},{\"heading\":false,\"text\":\"--Pues bien, para mí será hoy la quinta vez que dormiré allí.\"},{\"heading\":false,\"text\":\"Llenó el vaso, lo apuró y se quedó pensativo. En efecto, en su traje y en sus cabellos se veían algunas briznas de heno. A juzgar por las apariencias, lo menos hacía cinco días que no se había desnudado ni lavado la cara. Sus gruesas y rojas manos, con las uñas de luto, estaban también extremadamente sucias.\"},{\"heading\":false,\"text\":\"La sala entera le escuchaba, aunque, a decir verdad, con bastante despreocupación. Los mozos se reían detrás del mostrador. El tabernero había bajado también, sin duda para oír a aquel hombre original. Sentado a cierta distancia bostezaba con aire importante. Evidentemente Marmeladoff era conocido desde hacía algún tiempo en la casa. Según todas las probabilidades, debía su notoriedad a la costumbre de hablar en la taberna con todos los parroquianos que se ponían a su alcance. Tal costumbre se convierte en una necesidad para ciertos borrachos, principalmente para aquellos que son tratados con dureza por esposas poco tolerantes; tratan de adquirir en la taberna con sus compañeros de orgía la consideración que no encuentran en sus hogares.\"},{\"heading\":false,\"text\":\"--¡Por vida de...!--dijo en voz fuerte el tabernero--. ¿Por qué no trabajas, por qué no vas a la oficina, puesto que eres empleado?\"},{\"heading\":false,\"text\":\"--¿Por qué no trabajo, señor?--siguió diciendo Marmeladoff, encarándose exclusivamente con Raskolnikoff, como si éste le hubiera dirigido la pregunta--. ¿Por qué no trabajo? ¿Cree usted que mi inutilidad no me disgusta? Cuando, hace un mes, Lebeziatnikoff maltrató a mi mujer con sus propias manos, mientras yo asistía, ebrio y medio muerto, a tal escena, ¿cree usted que yo no sufría? Permítame usted, joven; ¿le ha ocurrido a usted... ¡hum!... le ha ocurrido solicitar un préstamo sin esperanza?\"},{\"heading\":false,\"text\":\"--Sí... Es decir, ¿qué entiende usted por eso de sin esperanza?\"},{\"heading\":false,\"text\":\"--Quiero decir, sabiendo perfectamente de antemano que no le darán a usted nada. Por ejemplo, usted tiene la certidumbre de que tal hombre, tal ciudadano bien intencionado, no le prestaría un kopek; porque, dígame usted, ¿a qué santo había de prestárselo, sabiendo que usted no ha de devolvérselo? ¿Por piedad? Ese Lebeziatnikoff es partidario de las nuevas ideas y aseguraba el otro día que la compasión, en nuestra época, está prohibida hasta por la ciencia, y que tal es la doctrina reinante en Inglaterra, en donde florece la economía política. ¿Cómo, repito, ese hombre habrá de prestarle a usted dinero? Está usted seguro de que no se lo prestará, y, sin embargo, se dirige usted a...\"},{\"heading\":false,\"text\":\"--¿Para qué ir en ese caso?--interrumpió Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Pues porque es preciso ir a alguna parte; porque no hay otra salida y llega un tiempo en que el hombre se decide, de buena o mala gana, a tomar cualquier senda. Cuando mi hija única se fué a inscribir en la policía tuve que ir también con ella (porque mi hija tiene cartilla)--añadió entre paréntesis, mirando al joven con expresión de inquietud--. Le advierto a usted que esto me tiene sin cuidado--se apresuró a decir con aparente flema, en tanto que los mozos, detrás del mostrador, y hasta el mismo tabernero sonreían--. ¡Poco me importa! No me inquietan los movimientos de cabeza, porque estas cosas son conocidas de todo el mundo y no hay secreto que no se descubra; no es con desprecio sino con resignación, como yo acepto mi suerte. ¡Sea! _¡Ecce Homo!_ Permítame, joven, que le pregunte si puede usted, o, mejor dicho, si se atrevería usted, fijando los ojos en mí, a afirmar que no soy un cerdo.\"},{\"heading\":false,\"text\":\"El joven no respondió.\"},{\"heading\":false,\"text\":\"El orador esperó con aire digno a que terminasen las risas provocadas por sus últimas palabras. Después añadió:\"},{\"heading\":false,\"text\":\"--Es verdad; yo soy un cerdo; pero ella es una señora. ¡Llevo impreso el sello de la bestia! Pero Catalina Ivanovna, mi esposa, es una persona bien educada, hija de un oficial superior. Concedo que soy un bufón empedernido; pero mi mujer tiene un gran corazón, sentimientos elevados, instrucción... y, sin embargo... ¡Oh! ¡Si tuviese piedad de mí! ¡Señores, señores, todos los hombres tienen necesidad de encontrar piedad en alguna parte! Pero Catalina Ivanovna, a pesar de su grandeza de alma, es injusta... Pues bien, con tal de que yo llegue a comprender que cuando me tira de los cabellos, lo hace, en rigor, por interés hacia mí... (No me avergüenzo de confesarlo: me tira de los cabellos, joven)--insistió, creciendo en dignidad al oír nuevas carcajadas--. Sin embargo, Dios mío, aunque no fuese más que una vez... pero no, no; dejemos esto; es inútil hablar de ello... Ni una sola vez he obtenido lo que deseaba; ni una sola vez se ha tenido compasión de mí... pero tal es mi carácter; soy un verdadero bruto...\"},{\"heading\":false,\"text\":\"--Lo creo--dijo bostezando el tabernero.\"},{\"heading\":false,\"text\":\"Marmeladoff dió un puñetazo en la mesa.\"},{\"heading\":false,\"text\":\"--Tal es mi carácter; ¿querrá usted creer, querrá usted creer, señor, que me he bebido hasta sus medias? No digo sus zapatos, porque esto se comprendería, hasta cierto punto; pero son sus medias, sus medias, las que yo me he bebido. ¡Sus medias! me he bebido también su pañoleta de pelo de cabra, un regalo que le habían hecho; un objeto que poseía antes de casarse conmigo y que era de su propiedad y no de la mía. Habitamos en un cuarto muy frío; este invierno mi mujer ha pescado un catarro y tose y escupe sangre. Tenemos tres hijos pequeños, y Catalina Ivanovna trabaja de la noche a la mañana. Hace colada y limpia la casa, porque desde muy joven está acostumbrada a la limpieza. Por desgracia, tiene el pecho delicado, cierta predisposición a la tisis que me preocupa. ¿No lo siento, por ventura? Cuando más bebo, más lo siento. Es para sentir y sufrir más por lo que me entrego a la bebida; ¡bebo porque quiero sufrir doblemente!\"},{\"heading\":false,\"text\":\"E inclinó la cabeza sobre la mesa con aire de desesperación.\"},{\"heading\":false,\"text\":\"--Joven--continuó en seguida incorporándose--, me parece leer en su semblante cierto disgusto. Desde que entró usted me ha parecido advertirlo, y por eso le he dirigido inmediatamente la palabra. Si le cuento la historia de mi vida no es para ofrecerme a la burla de esos ociosos, que, por otra parte, están enterados de todo, no; es porque busco la simpatía de un hombre bien educado. Sepa usted, pues, que mi mujer ha sido educada en una pensión aristocrática de provincia, y que a su salida del establecimiento bailó en chal delante del gobernador y de los otros personajes oficiales; tan contenta estaba por haber obtenido una medalla de oro y un diploma. La medalla... la hemos vendido hace ya mucho tiempo, ¡hum!... En cuanto al diploma, lo conserva mi esposa en un cofre y últimamente aun lo mostraba al ama de nuestra casa. Aunque esté a matar con ella, a mi mujer le gusta ostentar ante los ojos de cualquiera sus éxitos pasados. No se lo echo en cara, porque su única alegría ahora es acordarse de los hermosos días de otro tiempo. ¡Todo lo demás se ha desvanecido! Sí, sí; tiene un alma ardiente, orgullosa, intratable. Ella friega el suelo, come pan negro; pero no permite que se le escatimen ciertas consideraciones. Así es, que no ha tolerado la grosería de Lebeziatnikoff, y cuando, para vengarse de haber sido despedido, este último le puso la mano encima, mi mujer tuvo que guardar cama, sintiendo más el insulto hecho a su dignidad que el dolor de los golpes recibidos.\"},{\"heading\":false,\"text\":\"»Cuando me casé con ella era viuda, con tres niños pequeños. Había estado casada en primeras nupcias con un oficial de infantería, con quien huyó de casa de sus padres; amaba extremadamente a su marido; pero éste se dió al juego, tuvo que entendérselas con la justicia, y murió. En los últimos tiempos pegaba a su mujer. Sé de buena tinta que no era cariñosa con él, lo que no le impide ahora llorar por el difunto y establecer continuamente comparaciones entre él y mi persona, comparaciones poco lisonjeras para mi amor propio. Pero no me quejo; más bien me complace que se imagine haber sido feliz en otro tiempo.\"},{\"heading\":false,\"text\":\"»Después de la muerte de su marido se encontró sola con tres hijos pequeños, en un distrito lejano y salvaje, donde la encontré yo. Su miseria era tal, que yo, que de eso he visto tanto, no me siento con fuerzas para describirla. Todos sus parientes la habían abandonado; por otra parte, su orgullo le hubiera impedido siempre implorar la piedad de aquellas personas. Entonces, señor, entonces, yo, que era viudo también, y que tenía de mi matrimonio una hija de catorce años, ofrecí mi mano a aquella pobre mujer; tanta pena me daba verla sufrir.\"},{\"heading\":false,\"text\":\"»Instruída, bien educada, de buena familia, consintió, sin embargo, en casarse conmigo. Esto puede dar a usted una idea de la miseria en que la pobre viviría. Acogió mi proposición llorando, sollozando y retorciéndose las manos, pero la acogió, porque no tenía dónde ir.\"},{\"heading\":false,\"text\":\"»¿Comprende usted, comprende usted lo que significan estas palabras: «No tener ya adónde ir»? ¡Usted no lo comprende todavía!\"},{\"heading\":false,\"text\":\"»Durante un año entero cumplí mi deber honrada y santamente, y sin probar una gota de esto (señaló con el dedo la media botella que tenía delante); porque no carezco de sentimientos. Pero nada adelanté. A poco perdía mi empleo y no por falta mía; reformas administrativas determinaban la supresión del que desempeñaba, y entonces fué cuando me di a la bebida... Ahora ocupamos una habitación en casa de Amalia Ludvigovna Lippevechzel; pero ignoro con qué le pagamos y de qué vivimos. Hay allí muchos inquilinos además de nosotros; es una ratonera aquella casa... ¡hum!... Sí... Durante este tiempo, creció la hija que yo tenía de mi primera mujer. No quiero hablar de lo que su madrastra la ha hecho sufrir.\"},{\"heading\":false,\"text\":\"»Aunque de sentimientos nobilísimos, Catalina Ivanovna es una mujer irascible e incapaz de contenerse en los arrebatos de su cólera... Sí, ¡vamos, es inútil hablar de esto! Como puede usted comprender, Sonia no ha recibido una gran instrucción. Hace cuatro años traté de enseñarle Geografía e Historia Universal; pero como yo no he estado nunca fuerte en estas materias, y como además no tenía a mi disposición un buen manual, no hizo grandes progresos en sus estudios: nos detuvimos en Ciro, rey de Persia. Más tarde, cuando llegó a la edad adulta, leyó algunas novelas. Lebeziatnikoff le prestó hace poco la _Fisiología de Ludwig_. ¿Conoce usted esa obra? Mi hija la ha encontrado muy interesante y aun nos ha leído muchos pasajes en alta voz. A eso se limita toda su cultura.\"},{\"heading\":false,\"text\":\"»Ahora, señor, apelo a su sinceridad. ¿Cree usted en conciencia que una joven pobre, pero honrada, pueda vivir de su trabajo? Como no tenga una habilidad especial, ganará 15 kopeks al día, y para llegar a esa cifra tendrá necesidad de no perder un solo minuto. ¡Pero qué digo! Sonia hizo media docena de camisas de holanda, para el consejero de Estado Ivan Ivanovitch Klopstok; usted habrá oído hablar de él; pues bien, no sólo está esperando aún que se le paguen, sino que la pusieron a la puerta llenándola de injurias, so pretexto de que no había tomado bien la medida del cuello.\"},{\"heading\":false,\"text\":\"»En tanto los niños se mueren de hambre, Catalina Ivanovna se pasea por la habitación retorciéndose las manos, mientras en sus mejillas aparecen las manchas rojizas, propias de su enfermedad. «Holgazana--decía a mi hija--, ¿no te da vergüenza de vivir sin hacer nada? Bebes, comes, tienes lumbre.» Y yo pregunto ahora: ¿Qué es lo que la pobre muchacha podría beber y comer cuando en tres días los niños no habían visto siquiera un mendrugo de pan? Yo estaba en aquel momento acostado... Vamos, hay que decirlo todo, borracho; pero oí que mi Sonia respondía tímidamente con su voz dulce (la pobrecita es rubia, con una carita siempre pálida y resignada): «Pero, Catalina Ivanovna, ¿por qué me dice usted esas cosas?»\"},{\"heading\":false,\"text\":\"»Tengo que añadir que ya por tres veces Daría Frantzovna, una mala mujer muy conocida de la policía, le había hecho insinuaciones en nombre del propietario de la casa. «Vaya--dijo irónicamente Catalina Ivanovna--, vaya un tesoro para guardarlo con tanto cuidado.» Pero no la acuse usted. No tenía conciencia de lo que decía; estaba agitada, enferma, veía llorar a sus hijos hambrientos, y lo que decía era más bien para molestar a Sonia que para excitarla a que se entregara al vicio... Catalina Ivanovna es así; cuando oye llorar a sus hijos les pega, aunque sabe que lloran de hambre. Eran entonces las cinco y oí que Sonia se levantaba, se ponía el chal y salía del cuarto.\"},{\"heading\":false,\"text\":\"»A las ocho volvió. Al llegar, se fué derecha a Catalina Ivanovna, y, silenciosamente, sin proferir palabra, depositó treinta rublos de plata delante de mi mujer. Hecho eso, tomó nuestro gran pañuelo verde (un pañuelo que sirve para toda la familia), se envolvió la cabeza y se echó en la cama con la cara vuelta hacia la pared; un continuo temblor agitaba sus hombros y su cuerpo... yo continuaba en el mismo estado... En aquel momento, joven, vi a Catalina Ivanovna que, también silenciosamente, se arrodillaba junto al lecho de Sonia.\"},{\"heading\":false,\"text\":\"»Pasó toda la noche de rodillas, besando los pies de mi hija y rehusando levantarse. Después, las dos se durmieron juntas en los brazos una de la otra... ¡las dos!... ¡las dos!... sí; y yo continuaba lo mismo, sumido en la embriaguez.\"},{\"heading\":false,\"text\":\"Se calló Marmeladoff, como si la voz le hubiera faltado; luego llenó la copa, la vació y siguió, después de un corto silencio:\"},{\"heading\":false,\"text\":\"--Desde entonces, señor, a consecuencia de una circunstancia desgraciada, y con motivo de cierta denuncia de personas perversas (Daría Frantzovna tuvo parte principal en este negocio porque quería vengarse de una supuesta falta de respeto), desde entonces mi hija Sonia[5] Semenovna fué inscrita en el registro de policía y se vió obligada a dejarnos. Amalia Ludvigovna se ha mostrado inflexible en este punto, sin tener en cuenta que ella misma, en cierto modo, había favorecido las intrigas de Daría Frantzovna.\"},{\"heading\":false,\"text\":\"[5] Sonia es la fórmula familiar de Sofía, y Sonetchka diminuto cariñoso del mismo nombre.\"},{\"heading\":false,\"text\":\"»Lebeziatnikoff se ha unido a ella... ¡hum! y con motivo de lo de Sonia fué la cuestión que Catalina Ivanovna tuvo con él. En un principio estuvo muy solícito con Sonetchka; pero de repente se sintió herido en su amor propio. «¿Cómo un hombre de corazón--dijo--ha de habitar en la misma casa que semejante desdichada?» Catalina Ivanovna tomó partido por Sonia, y la disputa acabó en golpes... En la actualidad mi hija viene a menudo a vernos a la caída de la tarde, y ayuda con lo que puede a mi mujer. Vive en casa de Kapernumoff, un sastre cojo y tartamudo. Sus hijos, que son varios, tartamudean como él, y hasta su mujer tiene no sé qué defecto en la lengua... Todos comen y duermen en la misma sala; pero a Sonia le han cedido una habitación, separada de la de sus huéspedes por un tabique... ¡hum! sí... Son personas muy pobres y tartamudas... Bueno... Una mañana me levanté, me puse mis harapos, elevé las manos al cielo y me fuí a ver a Su Excelencia Ivan Afanasievitch. ¿Le conoce usted? ¿No? Pues entonces no conoce a un santo varón... Es una vela... pero una vela que arde delante del altar del Señor. Mi historia, que Su Excelencia se dignó oír hasta el fin, le hizo saltar las lágrimas. «Vamos, Simón Ivanovitch--me dijo--, has defraudado una vez mis esperanzas, pero vuelvo a tomarte, bajo mi exclusiva responsabilidad personal.» Así se expresó, añadiendo: «Procura acordarte de lo pasado, para no reincidir, y retírate.» Besé el polvo de sus botas, mentalmente, por supuesto, porque Su Excelencia no hubiera permitido que se las besase de veras; es un hombre muy penetrado de las ideas modernas y no le gustan semejantes homenajes. ¡Pero, Dios mío, cómo se me festejó cuando anuncié en casa que tenía un destino!\"},{\"heading\":false,\"text\":\"De nuevo la emoción obligó a Marmeladoff a detenerse. En aquel momento invadió la taberna un grupo de individuos ya a medios pelos. A la puerta del establecimiento sonaba un organillo, y la voz débil de un chiquillo cantaba la _Petite Ferme_.\"},{\"heading\":false,\"text\":\"La atmósfera de la sala era pesadísima. El tabernero y los mozos se apresuraban a servir a los recién llegados. Sin reparar en este incidente, Marmeladoff continuó su relato; el funcionario era cada vez más expansivo a causa de los progresos de su borrachera. El recuerdo de su reciente reposición iluminaba como un rayo de alegría su semblante. Raskolnikoff no perdía ni una sílaba de sus palabras.\"},{\"heading\":false,\"text\":\"--Han transcurrido cinco semanas, señor, desde que Catalina Ivanovna y Sonetchka supieron la grata noticia. Le aseguro a usted que me encontraba como transportado al paraíso. Antes no hacía más que abrumarme con palabrotas como estas: «¡Acuéstate, bruto!» Mas desde aquel momento andaba de puntillas y hacía callar a los pequeños, diciéndoles: «¡Chis! ¡Papá viene cansado del trabajo!» Antes de ir a la oficina me daban café con crema, pero no crea, crema verdadera, ¿eh? No sé de dónde pudieron sacar el dinero, 11 rublos y 50 kopeks, a fin de arreglarme la ropa. Lo cierto es que ellas me pulieron de pies a cabeza; tuve botas, chaleco de magnífico hilo y uniforme, todo en muy buen uso: les costó 11 rublos y medio. Seis días ha, cuando entregué íntegros mis honorarios, 23 rublos y 40 kopeks, mi mujer me acarició en la mejilla, diciéndome: «¡vaya un pez que estás hecho!» Naturalmente, esto ocurrió cuando estábamos solos. Dígame usted si no es encantador...\"},{\"heading\":false,\"text\":\"Marmeladoff se interrumpió, trató de sonreír; pero súbito temblor agitó su barba. Dominó, sin embargo, en seguida, su emoción. Raskolnikoff no sabía qué pensar de aquel borracho, que vagaba al azar desde hacía cinco días, durmiendo en los barcos de pesca, y, a pesar de todo, sintiendo por su familia profundo cariño. El joven le escuchaba con la mayor atención, pero experimentando cierta sensación de malestar. Estaba enojado consigo mismo por haber entrado en la taberna.\"},{\"heading\":false,\"text\":\"--¡Señor, señor!--dijo el funcionario disculpándose--, quizá halle usted, como los demás, risible todo lo que le cuento; acaso le estoy fastidiando refiriéndole estos tontos y miserables pormenores de mi existencia doméstica; mas para mí no crea usted que son divertidos, porque le aseguro que siento todas estas cosas... Durante aquel día maldito hice proyectos encantadores; pensé en el medio de organizar nuestra vida, de vestir a los niños, de procurar reposo a mi mujer, de sacar del fango a mi hija única. ¡Oh, cuántos planes formaba! Pues bien, señor (Marmeladoff empezó a temblar de repente; levantó la cabeza y miró a la cara a su interlocutor), el mismo día, cinco hace hoy, después de haber acariciado todos estos sueños, robé, como un ladrón nocturno, la llave a mi mujer y tomé del baúl todo lo que quedaba del dinero que yo había llevado. ¿Cuánto había? No lo recuerdo. Mírenme todos: hace cinco días que abandoné mi casa; no se sabe en ella qué es de mí; he perdido mi empleo, he dejado mi uniforme en una taberna y me han dado este traje en su lugar... Todo, todo ha acabado...\"},{\"heading\":false,\"text\":\"Marmeladoff se dió un puñetazo en la frente, rechinó los dientes y cerrando los ojos se puso de codos en la mesa... Al cabo de un momento cambió bruscamente la expresión de su rostro, miró a Raskolnikoff con afectado cinismo y dijo riéndose:\"},{\"heading\":false,\"text\":\"--¡He estado hoy en casa de Sonia; he ido a pedirle dinero para beber! ¡Je, je, je!\"},{\"heading\":false,\"text\":\"--¡Y te lo ha dado!--gritó, riéndose, uno de los parroquianos que formaba parte del grupo recién llegado a la taberna.\"},{\"heading\":false,\"text\":\"--Con su dinero he pagado esta media botella--repuso Marmeladoff dirigiéndose exclusivamente a nuestro joven--. Sonia fué a buscar treinta kopeks y me los entregó; era cuanto tenía; lo he visto con mis propios ojos. No me dijo nada; se limitó a mirarme en silencio, una mirada que no pertenece a la tierra, una mirada como deben tener los ángeles que lloran sobre los pecados de los hombres pero no los condenan. ¡Qué triste es que no le reprendan a uno! Treinta kopeks, sí, que de seguro necesitaba. ¿Qué me dice usted, querido señor? Ahora tiene ella que ir bien arreglada. La elegancia y los afeites, indispensables en su oficio, cuestan dinero; lo comprenderá usted; hay que tener pomada, enaguas almidonadas, lindas botitas que hagan bonito el pie para lucirlo al saltar los charcos. ¿Comprende usted, comprende usted la importancia de esta limpieza y elegancia? Pues bien, yo, su padre, según la Naturaleza, ha ido a pedirle esos treinta kopeks para bebérmelos. ¡Y me los bebo! Ya están bebidos... vamos, ¿quién ha de tener compasión de un hombre como yo? Ahora, señor, ¿puede usted compadecerme? Hable usted, señor: ¿tiene usted piedad de mí? ¿Sí o no? ¡Je, je, je!\"},{\"heading\":false,\"text\":\"Iba a servirse nuevamente, pero echó de ver que la media botella estaba vacía.\"},{\"heading\":false,\"text\":\"--¿Por qué se ha de tener lástima de ti?--gritó el tabernero.\"},{\"heading\":false,\"text\":\"Estallaron risas mezcladas con injurias. Los que no habían oído las palabras del ex funcionario, formaban coro con los otros, solamente al ver su catadura.\"},{\"heading\":false,\"text\":\"Marmeladoff, como si no hubiese esperado otra cosa que la interpelación del tabernero, para soltar el torrente de su elocuencia, se levantó vivamente y, con el brazo extendido hacia delante, replicó con exaltación:\"},{\"heading\":false,\"text\":\"--¡Por qué tener compasión de mí! ¡Por qué tener compasión de mí! ¡Es verdad, no se me debe compadecer! ¡Hay que crucificarme, ponerme en la cruz, no tenerme lástima! ¡Crucifícame, juez, pero, al hacerlo, ten piedad de mí! Así iré yo mismo al suplicio, porque no tengo sed de alegría, sino de dolor y de lágrimas. ¿Piensas tú, tendero, que tu media botella me ha proporcionado placer? Buscaba la tristeza, tristeza y lágrimas en el fondo de este frasco, y la he encontrado y saboreado. Pero Aquel que ha tenido piedad de todos los hombres, Aquel que todo lo comprende, tendrá piedad de nosotros; El es el único juez, El vendrá el último día y preguntará: «¿Dónde está la hija que has sacrificado por una madrastra odiosa y tísica y por niños que no eran sus hermanos? ¿Dónde está la joven que ha tenido piedad terrestre y no ha vuelto con horror las espaldas a este crapuloso borracho?» Y El dirá entonces: «Ven, yo te he perdonado una vez... yo te he perdonado ya una vez... ahora, todos tus pecados te son perdonados, porque has amado mucho...» Y El perdonará a mi Sonia, la perdonará, yo lo sé, lo he sentido en mi corazón cuando estaba en su casa.... Todos serán juzgados por El y El perdonará a todos, a los buenos y a los malos, a los sabios y a los pacíficos... y cuando haya acabado con ellos, nos tocará la vez a nosotros. «Acercaos también, nos dirá El; acercaos vosotros los borrachos, acercaos los cobardes, acercaos los impúdicos», y nos aproximaremos todos sin temor y El nos dirá: «¡Sois unos cochinos! ¡Tenéis sobre vosotros la marca de la bestia, pero venid también!» Y los sabios, los inteligentes dirán: «Señor, ¿por qué recibes Tú a éstos?» Y El responderá: «Yo los recibo ¡oh sabios! porque ninguno de ellos se ha creído digno de este favor...» Y El nos abrirá los brazos y nosotros nos precipitaremos en ellos... y nos desharemos en lágrimas... y comprenderemos... sí, entonces todo será comprendido por todo el mundo, y Catalina Ivanovna también comprenderá... Señor, vénganos el tu reino.\"},{\"heading\":false,\"text\":\"Falto de fuerzas, se dejó caer en el banco sin mirar a nadie, como si desde largo rato se hubiese olvidado del lugar en que se hallaba y de las personas que le rodeaban, y quedó absorto en la visión de fantasmas de ultratumba. Sus palabras produjeron cierta impresión; durante un momento cesó el barullo; pero bien pronto volvieron a estallar las risas, mezcladas con invectivas:\"},{\"heading\":false,\"text\":\"--¡Muy bien hablado!\"},{\"heading\":false,\"text\":\"--¡Gruñón!\"},{\"heading\":false,\"text\":\"--¡Charlatán!\"},{\"heading\":false,\"text\":\"--¡Burócrata!\"},{\"heading\":false,\"text\":\"--Vámonos, señor--dijo bruscamente Marmeladoff, levantando la cabeza y dirigiéndose a Raskolnikoff--; condúzcame usted al patio de la casa Kozel... Ya es tiempo de que vuelva al lado de mi mujer.\"},{\"heading\":false,\"text\":\"Rato hacía ya que el joven deseaba irse y se le había ocurrido ofrecer el apoyo de su brazo a Marmeladoff. Este último tenía las piernas aun menos firmes que la voz; de modo que iba casi colgado del brazo de su compañero. La distancia que tenían que recorrer era de doscientos o trescientos pasos. A medida que el borracho se acercaba a su domicilio, parecía más inquieto y preocupado.\"},{\"heading\":false,\"text\":\"--No es precisamente de Catalina Ivanovna de quien tengo yo ahora miedo--balbuceaba conmovido--. Ya sé que empezará por tirarme de los cabellos; pero, ¿qué me importa? Me alegro que me tire de ellos. No, no es eso lo que me espanta; lo que yo temo son sus ojos, sí, sus ojos... Temo también las manchas rojas de sus mejillas, y me da miedo además su respiración. ¿Has notado cómo respiran los que padecen esa enfermedad... cuando experimentan una emoción violenta? Temo las lágrimas de los chicos... porque si Sonia no les ha llevado algo de comer, no sé cómo se las habrán arreglado... no lo sé. A los golpes no les tengo miedo... sabe, en efecto, que, lejos de hacerme sufrir, esos golpes son un gozo para mí... Casi no puedo pasar sin ello... Sí, es mejor que me pegue, que alivie de ese modo el corazón... más vale así; pero he ahí la casa Kozel. El propietario es un cerrajero alemán, hombre rico... ¡Acompáñeme!...\"},{\"heading\":false,\"text\":\"Después de haber atravesado el patio se pusieron a subir al cuarto piso. Eran cerca de las once, y, aunque propiamente hablando no había aún anochecido en San Petersburgo, a medida que subían más obscura encontraban la escalera; en lo alto la obscuridad era completa.\"},{\"heading\":false,\"text\":\"La puertecilla ahumada que daba al descansillo estaba abierta; un cabo de vela alumbraba una pobrísima pieza de diez pasos de largo. Esta pieza, que desde el umbral se veía por completo, estaba en el mayor desorden. Había por todos lados ropas de niños. Una sábana agujereada, extendida de manera conveniente, ocultaba uno de los rincones, el más distante de la puerta; detrás de este biombo improvisado, había, probablemente, una cama. Todo el mobiliario consistía en dos sillas y un sofá de gutapercha, que tenía delante una mesa vieja, de madera de pino, sin barnizar y sin tapete. Encima de la mesa, en un candelero de hierro se consumía el cabo de vela que medio alumbraba la pieza. Marmeladoff dormía en el pasillo. La puerta que comunicaba con los otros cuartos alquilados de Amalia Ludvigovna estaba entreabierta, y se oía ruido de voces; sin duda, en aquel momento jugaban a cartas y tomaban te los inquilinos. Se percibían más de lo necesario sus gritos, sus carcajadas y sus palabras, por extremo libres y atrevidas.\"},{\"heading\":false,\"text\":\"Raskolnikoff reconoció en seguida a Catalina Ivanovna. Era una mujer flaca, bastante alta y bien formada, pero de aspecto muy enfermizo. Conservaba aún hermosos cabellos de color castaño y, como había dicho Marmeladoff, sus mejillas tenían manchas rojizas. Con los labios secos, oprimíase el pecho con ambas manos, y se paseaba de un lado a otro de la misérrima habitación. Su respiración era corta y desigual; los ojos le brillaban febrilmente y tenía la mirada dura e inmóvil. Iluminada por la luz moribunda del cabo de vela, su rostro de tísica producía penosa impresión. A Raskolnikoff le pareció que Catalina Ivanovna no debía tener arriba de treinta años; era, en efecto, mucho más joven que su marido... No advirtió la llegada de los dos hombres; parecía que no conservaba la facultad de ver ni la de oír.\"},{\"heading\":false,\"text\":\"Hacía en la habitación un calor sofocante, y subían de la escalera emanaciones infectas; sin embargo, a Catalina Ivanovna no se le había ocurrido abrir la ventana, ni cerrar la puerta. La del interior, solamente entornada, dejaba paso a una espesa humareda de tabaco, que hacía toser a la enferma; pero ella no se cuidaba de tal cosa.\"},{\"heading\":false,\"text\":\"La niña más pequeña, de seis años, dormía en el suelo con la cabeza apoyada en el sofá; el varoncito, un año mayor que la pequeñuela, temblaba llorando en un rincón; probablemente acababan de pegarle. La mayor, una muchachilla de nueve años, delgada y crecidita, llevaba una camisa toda rota, y echado sobre los hombros desnudos un viejo _burnus_ señoril que se le debía haber hecho dos años antes, porque al presente no le llegaba más que hasta las rodillas.\"},{\"heading\":false,\"text\":\"En pie, en un rincón al lado de su hermanito, había pasado el brazo, largo y delgado como una cerilla, alrededor del cuello del niño y le hablaba muy quedo, sin duda para hacerle callar. Sus grandes ojos, obscuros, abiertos por el terror, parecían aún mayores en aquella carita descarnada. Marmeladoff, en vez de entrar en el aposento, se arrodilló en la puerta; pero invitó a pasar a Raskolnikoff. La mujer, al ver un desconocido, se detuvo distraídamente ante él, tratando de explicarse su presencia. «¿Qué se le ha perdido aquí a ese hombre?»--se preguntaba. Pero en seguida supuso que el desconocido se dirigía a casa de algún otro inquilino, puesto que el cuarto de Marmeladoff era un sitio de paso. Así, pues, desentendiéndose de aquel extraño, se preparaba a abrir la puerta de comunicación, cuando de repente lanzó un grito: acababa de ver a su marido de rodillas en el umbral.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿Al fin vuelves?--dijo, con voz en que vibrara la cólera--. ¡Infame! ¡Monstruo! A ver, ¿qué dinero llevas en los bolsillos? ¿Qué traje es éste? ¿Qué has hecho del tuyo? ¿Qué es del dinero? ¡Habla!\"},{\"heading\":false,\"text\":\"Se apresuró a registrarle. Lejos de oponer resistencia, Marmeladoff apartó ambos brazos para facilitar el registro de los bolsillos. No llevaba encima ni un solo kopek.\"},{\"heading\":false,\"text\":\"--¿Dónde está el dinero?--gritaba su esposa--. ¡Oh Dios mío! ¿Es posible que se lo haya bebido todo? ¡Doce rublos que había en el cofre!...\"},{\"heading\":false,\"text\":\"Acometida de un acceso de rabia agarró a su marido por los cabellos y lo arrastró violentamente a la sala. No se desmintió la paciencia de Marmeladoff: el hombre siguió dócilmente a su mujer arrastrándose de rodillas tras de ella.\"},{\"heading\":false,\"text\":\"--¡Si me da gusto, si no es un dolor para mí!--gritaba, dirigiéndose a su acompañante, mientras Catalina Ivanovna le zarandeaba con fuerza la cabeza; una de las veces le hizo dar con la frente un porrazo en el suelo.\"},{\"heading\":false,\"text\":\"La niña, que dormía, se despertó, y se echó a llorar. El muchacho, de pie en uno de los ángulos de la habitación, no pudo soportar este espectáculo, empezó a temblar y a dar gritos y se lanzó hacia su hermana; el espanto casi le produjo convulsiones. La niña mayor temblaba como la hoja en el árbol.\"},{\"heading\":false,\"text\":\"--¡Se lo ha bebido todo; se lo ha bebido todo!--vociferaba Catalina Ivanovna en el colmo de la desesperación--. ¡Ni siquiera conserva el traje!... ¡Y tienen hambre, tienen hambre!--repetía retorciéndose las manos y señalando a los niños--. ¡Oh vida tres veces maldita! ¿Y a usted cómo no le da vergüenza de venir aquí al salir de la taberna?--añadió volviéndose bruscamente hacia Raskolnikoff--. Has estado allí bebiendo con él, ¿no es eso? ¿Has estado allí bebiendo con él?... ¡Vete, vete!...\"},{\"heading\":false,\"text\":\"El joven no esperó a que se lo repitiesen, y se retiraba sin decir una palabra, en el momento que la puerta interior se abría de par en par y aparecían en el umbral muchos curiosos de mirada desvergonzada y burlona. Llevaban todos el gorro y fumaban unos en pipa y otros cigarrillos. Vestían los unos trajes de dormir, e iban otros tan ligeros de ropa que rayaba en la indecencia; algunos no habían dejado los naipes para salir. Lo que más les divertía era oír a Marmeladoff, arrastrado por los cabellos, gritar que aquello le daba gusto.\"},{\"heading\":false,\"text\":\"Empezaban ya los inquilinos a invadir la habitación, cuando de repente se oyó una voz irritada; era Amalia Ludvigovna en persona que, abriéndose paso a través del grupo, venía para restablecer el orden a su manera. Por centésima vez manifestó a la pobre mujer que tenía que dejar el cuarto al día siguiente.\"},{\"heading\":false,\"text\":\"Como es de suponer, esta despedida fué dada en términos insultantes. Raskolnikoff llevaba encima el resto del rublo que había cambiado en la taberna. Antes de salir tomó del bolsillo un puñado de cobres y, sin ser visto, puso las monedas en la repisa de la ventana; pero antes de bajar la escalera se arrepintió de su generosidad, y poco faltó para que subiese de nuevo a casa de Marmeladoff.\"},{\"heading\":false,\"text\":\"--¡Valiente tontería he hecho!--pensaba--. Ellos cuentan con Sonia, pero yo no cuento con nadie--. Reflexionó, sin embargo, que no podía recobrar su dinero y que aunque pudiese, no lo haría. Después de esta reflexión prosiguió su camino--. Le hace falta pomada a Sonia--continuó diciéndose con burlona sonrisa, andando ya por la calle--. La elegancia cuesta dinero... ¡Hum! Según se ve Sonia no ha sido muy afortunada hoy. La caza del hombre es como la caza de los animales silvestres; se corre el peligro de volverse uno a casa de vacío. De seguro que mañana lo pasarían mal sin mi dinero... ¡Ah! ¡Sí, Sonia! ¡La verdad es que han encontrado en ella buena vaca de leche!... Y se aprovechan bien. Esto no les preocupaba nada; se han acostumbrado ya a ello. Al principio lloriquearon un poco; después se han habituado. ¡El hombre es cobarde y se hace a todo!\"},{\"heading\":false,\"text\":\"Raskolnikoff se quedó pensativo.\"},{\"heading\":false,\"text\":\"--¡Pues bien; si he mentido--exclamó--, si el hombre no es necesariamente un cobarde, debe atropellar todos los temores y todos los prejuicios que le detienen!\"}]},{\"title\":\"primera parte — capítulo III\",\"blocks\":[{\"heading\":false,\"text\":\"Tarde era cuando al día siguiente se despertó tras de un sueño agitado que no le devolvió las fuerzas y aumentó, de consiguiente, su mal humor. Paseó su mirada por el aposento con ojos irritados. Aquel cuartito, de seis pies de largo, ofrecía un aspecto muy lastimoso con el empapelado amarillento lleno de polvo y destrozado; además era tan bajo, que un hombre de elevada estatura corría peligro de chocar con el techo. El mobiliario estaba en armonía con el local; tres sillas viejas más o menos desvencijadas; en un rincón, una mesa de madera pintada, en la cual había libros y cuadernos cubiertos de polvo, prueba evidente de que no se había puesto mano en ellos durante mucho tiempo, y en fin, un grande y feísimo sofá, cuya tela estaba hecha pedazos.\"},{\"heading\":false,\"text\":\"Este sofá, que ocupaba casi la mitad de la habitación, servía de lecho a Raskolnikoff. El joven se acostaba a menudo allí vestido y sin mantas; se echaba encima, a guisa de colcha, su viejo capote de estudiante, y convertía en almohada un cojín pequeño, bajo el cual ponía, para levantarlo, toda su ropa, limpia o sucia. Delante del sofá había una mesita.\"},{\"heading\":false,\"text\":\"La misantropía de Raskolnikoff armonizaba muy bien con el desaseo de su tugurio. Sentía tal aversión a todo rostro humano, que solamente el ver la criada encargada de asear el cuarto la exasperaba. Suele ocurrir esto a algunos monómanos preocupados por una idea fija.\"},{\"heading\":false,\"text\":\"Quince días hacía que la patrona había cortado los víveres a su pupilo y a éste no se le había ocurrido tener una explicación con ella.\"},{\"heading\":false,\"text\":\"En cuanto a Anastasia, cocinera y única sirvienta de la casa, no le molestaba ver al pupilo en aquella disposición de ánimo, puesto que así éste daba menos que hacer; había cesado por completo de arreglar el cuarto de Raskolnikoff y de sacudir el polvo. A lo sumo, venía una vez cada ocho días a dar una escobada. En el momento de entrar la criada el joven despertó.\"},{\"heading\":false,\"text\":\"--Levántate. ¿Qué te pasa para dormir así? Son las nueve; te traigo te, ¿quieres una taza? ¡Huy qué cara! ¡Pareces un cadáver!\"},{\"heading\":false,\"text\":\"El inquilino abrió los ojos, se desperezó y, reconociendo a Anastasia, le preguntó, haciendo un penoso esfuerzo para levantarse.\"},{\"heading\":false,\"text\":\"--¿Me lo envía la patrona?\"},{\"heading\":false,\"text\":\"--No hay cuidado que se le ocurra semejante cosa.\"},{\"heading\":false,\"text\":\"La sirvienta colocó delante del joven su propia tetera y puso en la mesa dos terroncitos de azúcar morena.\"},{\"heading\":false,\"text\":\"--Anastasia, toma este dinero--dijo Raskolnikoff sacando del bolsillo unas monedas de cobre (también se había acostado vestido)--, y haz el favor de ir a buscarme un panecillo blanco. Pásate por la salchichería y tráete un poco de embutido barato.\"},{\"heading\":false,\"text\":\"--En seguida te traeré el panecillo; pero en lugar de salchicha, ¿no sería mejor que tomases un poco de _chatchi_? Se hizo ayer y está muy rico. Te guardé un poco... pero como te retiraste tan tarde... Está muy bueno.\"},{\"heading\":false,\"text\":\"Fué a buscar el _chatchi_, y cuando Raskolnikoff se puso a comer, la sirvienta se sentó a su lado, en el sofá, y empezó a charlar como lo que era, como una campesina.\"},{\"heading\":false,\"text\":\"--Praskovia Pavlona quiere dar parte a la policía.\"},{\"heading\":false,\"text\":\"El rostro del joven se alteró.\"},{\"heading\":false,\"text\":\"--¡A la policía! ¿Por qué?\"},{\"heading\":false,\"text\":\"--Porque no le pagas ni quieres irte. Ahí tienes el por qué.\"},{\"heading\":false,\"text\":\"--¡Demonio, no me faltaba más que esto!--dijo entre dientes--. No podría hacerlo en peor hora para mí... Esa mujer es tonta--añadió en alta voz--. Iré a verla y le hablaré.\"},{\"heading\":false,\"text\":\"--Como tonta, lo es ella y lo soy yo. Pero tú, que eres inteligente, ¿por qué te estás así tendido como un asno? ¿Cómo es que no tienes nunca dinero? Según he oído decir, antes dabas lecciones. ¿Por qué ahora no haces nada?\"},{\"heading\":false,\"text\":\"--Sí que hago--respondió secamente y como a pesar suyo Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¿Qué es lo que haces?\"},{\"heading\":false,\"text\":\"--Cierto trabajo...\"},{\"heading\":false,\"text\":\"--¿Qué trabajo?\"},{\"heading\":false,\"text\":\"--Medito--respondió seriamente después de una pausa.\"},{\"heading\":false,\"text\":\"Anastasia se echó a reír.\"},{\"heading\":false,\"text\":\"Tenía el carácter alegre; pero cuando se reía, era con risa estrepitosa que sacudía todo su cuerpo y acababa por hacerle daño.\"},{\"heading\":false,\"text\":\"--¿Y el pensar te proporciona mucho dinero?--preguntó cuando pudo hablar.\"},{\"heading\":false,\"text\":\"--No se puede ir a dar lecciones cuando no tiene uno botas que ponerse. Además, desprecio ese dinero.\"},{\"heading\":false,\"text\":\"--Quizás algún día te pese.\"},{\"heading\":false,\"text\":\"--Para lo que se gana dando lecciones... ¿Qué se puede hacer con unos cuantos kopeks?--siguió diciendo con tono agrio y dirigiéndose más bien a sí mismo que a su interlocutora.\"},{\"heading\":false,\"text\":\"--¿De modo que deseas adquirir de golpe la fortuna?\"},{\"heading\":false,\"text\":\"Raskolnikoff la miró con aire extraño, y guardó silencio durante algunos momentos.\"},{\"heading\":false,\"text\":\"--Sí, una fortuna--dijo luego con energía.\"},{\"heading\":false,\"text\":\"--¿Sabes que me das miedo? ¡Eres terrible! ¿Voy a buscarte el panecillo?\"},{\"heading\":false,\"text\":\"--Como quieras.\"},{\"heading\":false,\"text\":\"--¡Oh, se me olvidaba! Han traído una carta para ti.\"},{\"heading\":false,\"text\":\"--¡Una carta para mí! ¿De quién?\"},{\"heading\":false,\"text\":\"--No sé de quien; le he dado al cartero tres kopeks de mi bolsillo. He hecho bien, ¿no es cierto?\"},{\"heading\":false,\"text\":\"--¡Tráela, por amor de Dios, tráela!--exclamó Raskolnikoff muy agitado--. ¡Señor!\"},{\"heading\":false,\"text\":\"Un minuto después la carta estaba en sus manos.\"},{\"heading\":false,\"text\":\"No se había engañado; era de su madre, y traía el sello del gobierno de R... Al recibirla, no pudo menos de palidecer; hacía largo tiempo que no tenía noticias de los suyos; otra cosa, además, le oprimía violentamente el corazón en aquel momento.\"},{\"heading\":false,\"text\":\"--Anastasia, haz el favor de irte; ahí tienes tus tres kopeks; pero, ¡por amor de Dios!, vete en seguida.\"},{\"heading\":false,\"text\":\"La carta temblaba en sus manos; no quería abrirla en presencia de Anastasia, y esperó, para comenzar la lectura, a que la criada se marchase. Cuando se quedó solo, llevó vivamente el papel a sus labios y lo besó. Después se puso a contemplar atentamente la dirección reconociendo los caracteres trazados por una mano querida: era la letra fina e inclinada de su madre, la cual habíale enseñado a leer y escribir. Vacilaba como si experimentase cierto temor. Al fin rompió el sobre, la carta era muy larga: dos hojas de papel comercial escritas por ambos lados.\"},{\"heading\":false,\"text\":\"«Mi querido Rodia--decíale su madre--. Dos meses ha que no te escribo, y esto me hace sufrir hasta el punto de quitarme el sueño. Pero, ¿verdad que tú me perdonas mi silencio involuntario? Tú sabes cuánto te quiero. Dunia y yo no tenemos a nadie más que a ti en el mundo; tú lo eres todo para nosotras, nuestra esperanza, nuestra felicidad en el porvenir. No puedes imaginarte lo que he sufrido al saber que, al cabo de muchos meses, has tenido que dejar la Universidad, por carecer de medios de existencia, y que no tenías ni lecciones, ni recursos de ninguna especie.\"},{\"heading\":false,\"text\":\"»¡Cómo ayudarte con mis ciento veinte rublos de pensión al año! Los quince rublos que te mandé hace cuatro meses, se los pedí prestados, como sabes, a un comerciante de nuestra ciudad, a Anastasio Ivanovitch Vakrutchin. Es un hombre excelente y un amigo de tu padre. Pero habiéndole dado poderes para cobrar mi pensión a mi nombre, no podía mandarte nada más antes de que se reembolsara de lo que me había prestado.\"},{\"heading\":false,\"text\":\"»Ahora, gracias a Dios, creo que podré enviarte algún dinero; por lo demás, me apresuro a decirte que estamos en el caso de felicitarnos por nuestra fortuna. En primer lugar, una cosa que de seguro te sorprenderá: tu hermana vive conmigo desde hace seis semanas y ya no se separará de mi lado. ¡Pobre hija mía! al fin acabaron sus tormentos; pero procedamos con orden, pues quiero que sepas cómo ha pasado todo y lo que hasta aquí te habíamos ocultado.\"},{\"heading\":false,\"text\":\"»Hace dos meses me escribías que habías oído hablar de la triste situación en que se hallaba Dunia respecto a la familia Svidrigailoff y me pedías noticias sobre este asunto. ¿Qué podía responderte yo? Si te hubiese puesto al corriente de los hechos, lo habrías dejado todo para venir aquí, aunque hubiera sido a pie, porque con tu carácter y tus sentimientos no habrías dejado que insultasen a tu hermana. Yo estaba desesperada; ¿pero qué hacer? Tampoco conocía entonces toda la verdad. Lo malo era que Dunetchka[6], que entró el año último como institutriz en esta casa, había recibido adelantados cien rublos, que había de pagar por medio de un descuento mensual sobre sus honorarios; por esta razón ha tenido que desempeñar su cargo hasta la extinción de la deuda.\"},{\"heading\":false,\"text\":\"[6] Diminutivo cariñoso de Dunia.\"},{\"heading\":false,\"text\":\"»Esta cantidad (ahora puedo ya decírtelo, querido Rodia) se había pedido para enviarte los sesenta rublos que tanto necesitabas, y que recibiste el año pasado. Te engañamos entonces escribiéndote que aquel dinero provenía de antiguas economías reunidas por Dunetchka. No era verdad; ahora te lo confieso; porque Dios ha permitido que las cosas tomen repentinamente mejor rumbo y también para que sepas lo mucho que te quiere Dunia y el hermoso corazón que tiene.\"},{\"heading\":false,\"text\":\"»El hecho es que el señor Svidrigailoff comenzó por mostrarse grosero con ella; en la mesa no cesaba de molestarla con descortesías y sarcasmos... mas, ¿para qué extenderme en penosos pormenores, que no servirían más que para irritarte inútilmente, puesto que todo ello ha pasado ya? En suma, aunque tratada con muchos miramientos y bondad por Marfa Petrovna, la mujer de Svidrigailoff, y por las otras personas de la casa, Dunetchka sufría mucho, sobre todo cuando Svidrigailoff, que ha adquirido en el regimiento la costumbre de beber, estaba bajo la influencia de Baco. Menos mal si todo se hubiera limitado a esto... Pero figúrate tú que, bajo apariencias de desprecio hacia tu hermana, este insensato ocultaba una verdadera pasión por Dunia.\"},{\"heading\":false,\"text\":\"»Al fin se quitó la máscara; quiero decir, que hizo a Dunetchka proposiciones deshonrosas: trató de seducirla con diversas promesas declarándole que estaba dispuesto a abandonar su familia e irse a vivir con Dunia en otra ciudad o en el extranjero. ¡Figúrate los sufrimientos de tu pobre hermana! No solamente la cuestión pecuniaria, de la cual te he hablado, le impedía dejar inmediatamente el empleo, sino que además temía, procediendo de este modo, despertar las sospechas de Marfa Petrovna e introducir la discordia en la familia.\"},{\"heading\":false,\"text\":\"»El desenlace llegó de improviso. Marfa Petrovna sorprendió inopinadamente a su marido en el jardín, en el momento en que aquél, con sus instancias, asediaba a Dunia, y entendiendo mal la situación, atribuyó todo lo que sucedía a la pobre muchacha. Hubo entre ellos una escena terrible. La señora Svidrigailoff no quiso avenirse a razones; estuvo gritando durante una hora contra su supuesta rival; se olvidó de sí misma, hasta pegarla, y, finalmente, la envió a mi casa en la carreta de un campesino, sin dejarle tiempo aun para hacer la maleta.\"},{\"heading\":false,\"text\":\"»Todos los objetos de Dunia, ropa blanca, vestidos, etc., fueron metidos revueltos en la telega[7]. Llovía a cántaros, y, después de haber sufrido aquellos insultos, tuvo Dunia que caminar diez y siete verstas en compañía de un _mujik_[8], en un carro sin toldo. Considera ahora qué había de escribirte, en contestación a la carta tuya de hace dos meses. Estaba desesperada; no me atrevía a decirte la verdad, porque te habría causado una pena hondísima e irritado sobremanera. Además, Dunia me lo había prohibido. Escribirte para llenar mi carta de futesas, te aseguro que era cosa que no me sentía capaz de hacer, teniendo como tenía el corazón angustiado. A continuación de este suceso, fuimos durante un mes largo la comidilla del pueblo, hasta el extremo de que Dunia y yo no podíamos ir a la iglesia sin oír lo que, al pasar nosotras, murmuraba la gente con aire despreciativo.\"},{\"heading\":false,\"text\":\"[7] Carreta de aldeano.\"},{\"heading\":false,\"text\":\"[8] Campesino siervo.\"},{\"heading\":false,\"text\":\"»Todo ello por culpa de Marfa Petrovna, la cual había ido difamando a Dunia por todas partes. Conocía a mucha gente en el pueblo, y durante ese mes venía aquí diariamente. Como además es un poco charlatana y le gusta tanto hablar mal de su marido, pronto propaló la historia, no sólo por el pueblo, sino por todo el distrito. Mi salud no resistió; pero Dunetchka se mostró más fuerte: lejos de abatirse ante la calumnia, ella era quien me consolaba esforzándose en darme valor. ¡Si la hubieses visto! ¡Es un ángel!\"},{\"heading\":false,\"text\":\"»La misericordia divina ha puesto fin a nuestros infortunios. El señor Svidrigailoff reflexionó, sin duda, y compadecido de la joven a quien hubo antes de comprometer, puso ante los ojos de Marfa Petrovna pruebas convincentes de la inocencia de Dunia. Svidrigailoff conservaba una carta que, antes de la escena del jardín, mi hija se vió obligada a escribirle, rehusándole una cita que él le había pedido. En esta carta Dunia le echaba en cara la indignidad de su conducta respecto a su mujer, le recordaba sus deberes de padre y esposo y, por último, le hacía ver la vileza de perseguir a una joven desgraciada y sin defensa.\"},{\"heading\":false,\"text\":\"»Con esto no le quedó duda alguna a Marfa Petrovna de la inocencia de Dunetchka. Al día siguiente, que era domingo, vino a nuestra casa, y después de contárselo todo, abrazó a Dunia y le pidió perdón llorando. Después recorrió el pueblo, casa por casa, y en todas partes rindió espléndido homenaje a la honradez de Dunetchka y a la nobleza de sus sentimientos y conducta. No contentándose con esto, enseñaba a todo el mundo y leía en alta voz la carta autógrafa de Dunia a Svidrigailoff; hizo además sacar de ella muchas copias (lo que ya me parece excesivo). Como ves, ha rehabilitado por completo a Dunetchka, mientras el marido de Marfa Petrovna sale de esta aventura cubierto de imborrable deshonor. No puedo menos de compadecer a ese loco, tan severamente castigado.\"},{\"heading\":false,\"text\":\"»Has de saber, Rodia, que se ha presentado para tu hermana un partido, y que ella ha dado su consentimiento, cosa que me apresuro a comunicarte. Tú nos perdonarás a Dunia y a mí el haber tomado esta resolución sin consultarte, cuando sepas que el asunto no admitía dilaciones y que era imposible esperar, para responder, a que tú nos contestaras. Por otra parte, no estando aquí, no podías juzgar con conocimiento de causa.\"},{\"heading\":false,\"text\":\"»Te diré cómo ha pasado todo. El novio, Pedro Petrovitch Ludjin, un consejero de la Corte de Apelación, es pariente lejano de Marfa Petrovna, la cual se ha tomado mucho interés por nosotros en esta ocasión. Ella fué quien le presentó en nuestra casa. Le recibimos convenientemente, tomó café con nosotras, y al otro día nos escribió una carta muy cortés pidiéndonos la mano de tu hermana y solicitando una respuesta pronta y categórica. Es un hombre muy atareado; está en vísperas de regresar a San Petersburgo, de manera que no puede perder tiempo.\"},{\"heading\":false,\"text\":\"»Naturalmente, nos quedamos asombradas, puesto que no esperábamos un cambio tan brusco en nuestra situación. Un día entero hemos estado examinando el caso tu hermana y yo. Pedro Petrovitch está en buena posición; desempeña dos cargos y posee ya una considerable fortuna. Tiene, es cierto, cuarenta y cinco años; pero su aspecto es agradable y puede gustar a las mujeres. Es un hombre muy bueno; a mí me parece un poco frío y altanero. Sin embargo, estas apariencias pueden ser engañosas.\"},{\"heading\":false,\"text\":\"»Ya estás advertido, querido Rodia; cuando le veas en San Petersburgo, lo que sucederá pronto, no le juzgues con demasiada ligereza, ni le condenes, sin apelación, como tienes por costumbre, si por acaso a primera vista te inspira poca simpatía. Te digo esto por decírtelo, porque, en rigor, estoy persuadida de que te producirá buena impresión. Además, por regla general, para conocer a cualquiera es menester haberle tratado largo tiempo y observádole con cuidado; de lo contrario se incurre en errores que luego se rectifican difícilmente.\"},{\"heading\":false,\"text\":\"»Pero en lo tocante a Pedro Petrovitch, todo hace creer que es una persona muy respetable; ya en su primera visita nos ha manifestado que está por lo «positivo». Sin embargo, ha dicho, son sus propias palabras: «Participo en gran parte de las ideas de las generaciones modernas y soy enemigo de todos los prejuicios». Habló mucho más porque, según parece, es un tanto vanidoso y le enamoran sus frases; pero esto, en realidad, no constituye un grave defecto.\"},{\"heading\":false,\"text\":\"»Yo, es claro, no he comprendido gran cosa de lo que ha hablado, por lo cual me limitaré a comunicarte la opinión de Dunia: «Aunque de escasa instrucción--me ha dicho--, es inteligente, y parece bueno». Conoces el carácter de tu hermana, Rodia; es una joven valerosa, sensata, paciente y magnánima, aunque su corazón sea muy apasionado como he podido comprobar. De seguro que no se trata ni por parte de él ni de ella de un matrimonio por amor: pero Dunia no es tan sólo una muchacha inteligente, su alma es de nobleza angelical, su marido procurará hacerla feliz, y ella considerará como un deber el corresponderle.\"},{\"heading\":false,\"text\":\"»Hombre de buen entendimiento Pedro Petrovitch, debe comprender que la felicidad de su esposa será la mejor garantía de la suya. Por ejemplo, me ha parecido un poco seco; pero esto, sin duda, depende de su franqueza. En su segunda visita, cuando ya habíamos admitido su demanda, nos ha dicho que, aun antes de conocer a Dunia, estaba resuelto a no casarse más que con una joven honrada pero sin dote, y que supiese qué es la pobreza. Según él, el hombre no debe sentirse obligado a su esposa; vale más que ella vea en su marido un bienhechor.\"},{\"heading\":false,\"text\":\"»No son estas precisamente sus palabras; reconozco que se ha explicado en términos más delicados; pero yo sólo recuerdo el sentido de sus frases. Por lo demás, ha hablado sin premeditación; evidentemente la frase, se le ha escapado sin intención, y aun ha tratado de atenuar su crudeza. Sin embargo, he encontrado un poco dura su manera de expresarse, y así se lo he dicho a Dunia. Pero ella me ha contestado, con algo de mal humor, que las palabras no son más que palabras, y que, en último término, lo que él opina es justo. Durante la noche que ha precedido a su determinación, Dunetchka no ha podido conciliar el sueño. Creyéndome dormida se levantó de la cama para pasearse arriba y abajo de la alcoba. Por último, se puso de rodillas y, después de una larga y ferviente plegaria ante la imagen, me declaró al día siguiente por la mañana que había tomado su resolución.\"},{\"heading\":false,\"text\":\"»Te he dicho ya que Pedro Petrovitch debía regresar inmediatamente a San Petersburgo, donde le llamaban graves intereses y donde quiere abrir su estudio de abogado. Desde hace tiempo se ocupa en asuntos de abogacía; acaba de ganar una causa importante, y su viaje a San Petersburgo es motivado por un negocio de interés que se debe tratar en el Senado. En estas condiciones, hijo mío, está en camino de servirte mucho, y Dunia y yo hemos pensado que podrás, bajo sus auspicios, comenzar tu futura carrera. ¡Ah, si esto se realizase!\"},{\"heading\":false,\"text\":\"»Tan ventajoso sería para ti, que habría que atribuirlo a un favor especial de la divina Providencia.\"},{\"heading\":false,\"text\":\"»Dunia no piensa en otra cosa. Hemos hecho ya alguna indicación a Pedro Petrovitch, que se ha expresado con cierta reserva: «Sin duda, ha dicho, como yo tengo necesidad de un secretario, mejor le confiaría este puesto a un pariente que a un extraño, con tal de que sea capaz de desempeñarlo.» ¡Figúrate si serás tú capaz! A mí me ha parecido que teme que tus estudios universitarios te impidan ocuparte en su bufete. Por esta vez la conversación no ha pasado adelante; pero Dunia no tiene otra cosa en la cabeza; su imaginación, ya exaltada, te ve trabajando bajo la dirección de Pedro Petrovitch, y hasta asociado a sus negocios, tanto más, cuanto que sigues la misma carrera suya; yo pienso lo mismo que ella, y sus proyectos para tu porvenir me parecen muy realizables.\"},{\"heading\":false,\"text\":\"»A pesar de la respuesta evasiva de Pedro Petrovitch, la cual se comprende perfectamente, puesto que no te conoce, Dunia cuenta con su legítima influencia de esposa para arreglarlo todo en armonía con nuestros comunes deseos. Huelga decir que hemos procurado dar a entender a Pedro Petrovitch que tú podrías ser, andando el tiempo, su socio. Es un hombre positivo, y acaso no hubiese mirado con buenos ojos lo que hasta ahora sólo le habrá parecido un sueño.\"},{\"heading\":false,\"text\":\"»Quiero también decirte una cosa, querido Rodia. Por ciertas razones, que nada tienen que ver con Pedro Petrovitch, y que quizá no sean más que rarezas de vieja, creo que después de la boda debo seguir en mi casa, en vez de irme a vivir con ellos. No dudo que Pedro Petrovitch será bastante atento y delicado para instarme a que no me separe de mi hija; si hasta ahora no me lo ha insinuado, es sin duda porque cree que no se ha de hablar de una cosa que cae por su peso; pero yo tengo intención de rehusar.\"},{\"heading\":false,\"text\":\"»Si es posible, me estableceré cerca de vosotros, porque te advierto, querido Rodia, que he guardado lo mejor para el final. Has de saber, hijo mío, que de aquí a poco tiempo nos veremos, y podremos abrazarnos después de tres años de separación. Está decidido que Dunia y yo vayamos a San Petersburgo. ¿Cuándo? No lo sé a punto fijo; pero será bien pronto, quizá dentro de ocho días. Todo depende de Pedro Petrovitch, que nos enviará sus instrucciones cuando haya arreglado sus asuntos en ésa y apresurado la boda. A ser posible desea que el matrimonio se efectúe el carnaval, o a más tardar, después de la cuaresma de la Asunción. ¡Oh, con qué alegría te estrecharé entre mis brazos!\"},{\"heading\":false,\"text\":\"»Dunia está enajenada de júbilo ante la idea de volver a verte; y me ha dicho una vez bromeando que, aunque no fuese más que por esto, se casaría de buena gana con Pedro Petrovitch. ¡Es un ángel! No añade nada a esta carta, porque tendría, según ella, demasiadas cosas que contarte, y, siendo esto así, no vale la pena de escribirte unas cuantas líneas. Me encarga que te envíe cariñosísimos recuerdos de su parte. Aunque estamos en vísperas de reunirnos, pienso, sin embargo, remitirte todo el dinero que pueda. En cuanto se ha sabido que Dunetchka iba a casarse con Pedro Petrovitch, nuestro crédito ha aumentado de un modo considerable, y sé, a ciencia cierta, que Anastasio Ivanovitch está dispuesto a adelantarme sobre mi pensión hasta 70 rublos.\"},{\"heading\":false,\"text\":\"»Te mandaré, pues, dentro de unos días 25 o 30 rublos. Te mandaría de buena gana mayor cantidad si no temiese que llegara a faltarme dinero para el viaje. Es verdad que Pedro Petrovitch tiene la bondad de encargarse de una parte de nuestros gastos de viaje; a sus expensas nos van a proporcionar un gran cajón para empaquetar nuestros efectos; pero nosotros tenemos que pagar nuestros billetes, hasta San Petersburgo, y no es cosa de que lleguemos a esa capital sin ningún kopek.\"},{\"heading\":false,\"text\":\"»Dunia y yo lo hemos calculado todo; el viaje no nos saldrá muy caro. Desde nuestra casa al tren no hay más que noventa verstas, y hemos ajustado con un campesino, conocido nuestro, que nos lleve en su carro a la estación; en seguida nos meteremos muy satisfechas en un coche de tercera. En resumen: después de echar mis cuentas, son 30 rublos, y no 25, los que voy a tener el placer de remitirte.\"},{\"heading\":false,\"text\":\"»Ahora, mi querido Rodia, te abrazo, esperando nuestra próxima entrevista, y te envío mi bendición maternal. Quiere mucho a Dunia, a tu hermana. ¡Oh Rodia!, sabe que te quiere infinitamente más que a sí misma; págala con el mismo afecto. Ella es un ángel, y tú lo eres todo para nosotras, toda nuestra esperanza, toda nuestra futura felicidad. Con tal que tú seas dichoso, lo seremos nosotras.\"},{\"heading\":false,\"text\":\"»Adiós, o más bien, hasta la vista. Te beso mil veces.\"},{\"heading\":false,\"text\":\"»Tuya hasta la muerte.\"},{\"heading\":false,\"text\":\"Durante la lectura de esta carta se le saltaron varias veces las lágrimas al joven; pero cuando la hubo terminado se dibujó en su rostro, pálido y convulsivo, una amarga sonrisa. Apoyando la cabeza sobre su nauseabundo cojín, permaneció pensativo durante largo tiempo. Latíale el corazón con fuerza y sus ideas se confundían. Por último, se sintió como sofocado en aquel cuartucho amarillento que parecía un armario o un baúl. Su ser físico y moral tenía necesidad de espacio.\"},{\"heading\":false,\"text\":\"Tomó el sombrero y salió, sin temor esta vez a encontrar a nadie en la escalera. No pensaba en la patrona. Se dirigió hacia la plaza de Basilio Ostroff por la perspectiva V***. Andaba rápidamente como el que tiene que atender a muchos negocios importantes a la vez; pero, según costumbre, no se fijaba en nadie, murmuraba para sí y aun _monologueaba_ en alta voz, lo que asombraba a los paseantes. Algunos lo creían borracho.\"}]},{\"title\":\"primera parte — capítulo IV\",\"blocks\":[{\"heading\":false,\"text\":\"La carta de su madre le había impresionado extraordinariamente; pero el asunto principal de ella no le hizo vacilar ni un momento. Desde el primer instante, aun antes de acabar de leerla, tenía tomada ya su resolución.\"},{\"heading\":false,\"text\":\"«En tanto que yo viva no se celebrará este matrimonio; que se vaya al diablo el señor Ludjin.\"},{\"heading\":false,\"text\":\"»¡La cosa está bien clara!--murmuraba sonriendo, con aire de triunfo como si tuviese la clave de lo sucedido--. ¡No, madre; no, Dunia! ¡no lograréis engañarme!... ¡Y todavía se disculpan de no haberme pedido mi opinión, y por haber resuelto el asunto sin mí! ¡Ya lo creo, suponen que no es posible romper la unión proyectada! ¡Eso ya lo veremos! ¿Y qué razón es la que alegan? «Pedro Petrovitch es un hombre tan ocupado, que sólo puede casarse a toda prisa.»\"},{\"heading\":false,\"text\":\"»No, Dunetchka, no; lo adivino todo. Sé lo que querías comunicarme, sé también lo que pensabas durante toda la noche que has pasado paseándote por tu habitación o rezando a Nuestra Señora de Kazán, cuya imagen está en la alcoba de nuestra madre. ¡Qué penosa es la subida del Gólgota!... ¡Oh!... Está bien combinado; te casas con un hombre de negocios, muy práctico y que posee ya un capital (lo cual es de tenerse muy en cuenta), que tiene dos empleos y que participa, según mamá, de las ideas de las modernas generaciones. Dunetchka misma observa que le «parece» bueno; ¡ese _parece_ es muy significativo! Bajo la fe de una apariencia, Dunetchka va a casarse con él... ¡Admirable!... ¡Admirable!...\"},{\"heading\":false,\"text\":\"»Me gustaría saber por qué mi madre ha hablado en su carta de las «generaciones modernas». ¿Es sencillamente para caracterizar el personaje, o ha sido con objeto de captar mis simpatías para el señor Ludjin? ¡Vaya una estratagema! Hay una circunstancia que desearía esclarecer. ¿Hasta qué punto han sido francas, durante el día y la noche que precedieron a la resolución de Dunetchka? ¿Hubo entre ellas una explicación formal, o se comprendieron mutuamente sin tener casi necesidad de cambiar sus ideas? A juzgar por la carta, me inclinaría más bien hacia esta última suposición: mi madre le ha encontrado un poco seco, y en su candidez, ha comunicado su observación a Dunia. Pero ésta, naturalmente, se ha enfadado y respondió de _mal humor_.\"},{\"heading\":false,\"text\":\"»¡Lo comprendo! desde el momento en que la decisión estaba tomada, no había que volver sobre ella; la advertencia de mi madre era, por lo menos, inútil. ¿Y por qué me escribe diciéndome: «quiere a Dunia, ¡oh Rodia!, porque ella te quiere más que a sí misma»? ¿Le remordería la conciencia por haber sacrificado su hija a su hijo? «Tú eres nuestra felicidad en el porvenir, tú lo eres todo para nosotras.» ¡Oh madre mía!...\"},{\"heading\":false,\"text\":\"Por instantes aumentaba la indignación de Raskolnikoff, y si entonces hubiera encontrado al señor Ludjin, probablemente le habría matado.\"},{\"heading\":false,\"text\":\"--Es verdad--continuó, siguiendo el vuelo de los pensamientos que le hervían en la cabeza--; «es verdad que, para conocer a cualquiera, es preciso haberle tratado largamente y observádole con cuidado.» ¡Pero el señor Ludjin no es difícil de descifrar! Ante todo, es un hombre de negocios y _parece_ bueno. Aquello de «quiero proporcionaros un gran cajón» es verdaderamente chusco. ¿Cómo dudar, en vista de este rasgo tan rumboso, de su bondad? Su futura y su suegra van a ponerse en camino en el carro de un campesino sin más defensa contra la lluvia que un mal toldo... ¡Qué importa! el trayecto hasta la estación no es más que de noventa verstas; «en seguida entraremos en un coche de tercera», para recorrer mil verstas; tiene razón; es preciso cortar el traje según la tela; pero usted, señor Ludjin, ¿en qué piensa usted? Vamos a ver, ¿no se trata de su futura esposa? ¿Y cómo puede usted ignorar que para emprender semejante viaje tiene la madre que tomar un préstamo sobre su pensión? Sin duda, con el espíritu mercantil que usted posee, ha considerado que esta boda es un negocio a medias, y que, por consiguiente, cada asociado debe suministrar la parte que le corresponde; pero usted ha arrimado demasiado el ascua a su sardina; no hay paridad entre lo que cuesta un cajón y lo que cuesta el viaje.\"},{\"heading\":false,\"text\":\"»¿Es que no se hacen cargo de estas cosas, o que fingen no verlo? Lo cierto es que parecen contentas. Sin embargo, ¿qué frutos pueden esperarse de tales flores? Lo que me irrita en ese extraño sujeto, es más la tacañería que su proceder: el amante da señal de lo que será el marido. Y mamá, que tira el dinero por la ventana, ¿con qué llegará a San Petersburgo? Con tres rublos o tres billetitos, como decía aquella vieja... ¡Hum! ¿Con qué recursos cuenta para vivir aquí? Por ciertos indicios, ha comprendido que después del matrimonio no podrá vivir con Dunia. Alguna palabra se le ha _escapado_ a ese amable señor, que ha sido sin duda un rayo de luz para mi madre, aunque ella se esfuerce en cerrar los ojos a la evidencia.\"},{\"heading\":false,\"text\":\"«Tengo intención de rehusar»--me dice--; pero entonces, ¿con qué medios de existencia cuenta? ¿Con los 120 rublos de pensión, de los cuales será preciso descontar la suma prestada por Anastasio Ivanovitch? Allá en nuestro pueblo, mi pobre madre se quema los ojos haciendo toquillas de punto de lana y bordando mangas. Pero este trabajo no le da más que 20 rublos al año. Luego, a pesar de todo, pone su esperanza en los sentimientos generosos del señor Ludjin. «Me instará a que no me separe de mi hija.» ¡Sí, fíate!\"},{\"heading\":false,\"text\":\"»Pase por mamá; ella es así; es su modo de ser; pero, ¿y Dunia?\"},{\"heading\":false,\"text\":\"»Es posible que no comprenda a ese hombre. ¡Y consiente en casarse con él! Yo sé que ama mil veces más la libertad de su alma que el bienestar material. Antes que renunciar a ella, comería pan negro con un sorbo de agua; no la daría por todo el Slesvig-Holstein, cuanto más por el señor Ludjin. No, la Dunia que yo conozco no es capaz de eso, y de seguro no ha cambiado. ¿Qué quiere decir entonces? Penoso es vivir en casa de los Svidrigailoff, andar rondando de provincia en provincia, pasar toda la vida dando lecciones que producen al año 200 rublos; eso es muy duro, ciertamente; sin embargo, yo sé que mi hermana iría a trabajar a casa de un plantador de América o a la de un alemán de Lituania, antes que envilecerse, encadenando por puro interés personal su existencia a la de un hombre a quien no estima y con quien no tiene nada de común. Cargado de oro puro y de diamantes podría estar el señor Ludjin, y mi hermana no consentiría en ser la manceba legítima de ese hombre. Y siendo esto así, ¿por qué se ha resuelto a casarse? ¿Cuál es la clave de este enigma? La cosa es bastante clara; para procurarse a sí misma una posición, ni siquiera para librarse de la muerte, no se vendería jamás; pero lo hace por un ser querido, adorado. Esta es la explicación de todo el misterio: se vende por su madre, se vende por su hermano. ¡Y lo vende todo! Eso es, violentemos nuestro sentimiento moral, pongamos en público mercado nuestra libertad, nuestro reposo, nuestra misma conciencia, todo, todo... ¡Perezca nuestra vida, con tal de que los seres queridos sean felices! Hagamos más todavía, imitemos la casuística sutil de los jesuítas, transijamos con nuestros escrúpulos y persuadámonos de que es preciso proceder de este modo, que la excelencia del fin justifica los medios. Ved aquí cómo somos... esto es claro como la luz. Es evidente que en el primer término se encuentra Rodión Romanovitch Raskolnikoff. Hay que asegurarle la felicidad, suministrarle medios para terminar sus estudios universitarios, que llegue a ser el socio de Ludjin, que alcance, si es posible, la fortuna, el renombre y la gloria. ¿Y la madre? Ella no ve más que a su hijo, a su primogénito. ¿Cómo no ha de sacrificar su hija a este hijo, objeto de sus predilecciones? ¡Corazones tiernos, pero injustos!\"},{\"heading\":false,\"text\":\"»¡Oh! es la suerte de Sonetchka la que aceptáis... Sonetchka Marmeladoff, la eterna Sonetchka, que durará tanto como el mundo. ¿Habéis medido bien las dos la extensión de vuestro sacrificio? ¿Sabes tú, Dunetchka, hermana mía, que vivir con el señor Ludjin es ponerse al nivel de Sonetchka? «En este matrimonio no puede haber amor», escribe mi madre. Pues bien, si no puede haber amor ni estimación, sino, por el contrario, disgusto, repulsión y alejamiento, ¿en qué se diferencia este enlace del concubinato o de la prostitución? Más disculpable sería aún Sonetchka, puesto que ella se ha vendido no para procurarse el bienestar, sino porque veía la miseria y el hambre, el hambre verdadera llamar a la puerta de su casa.\"},{\"heading\":false,\"text\":\"»Y si llega el momento de que el peso sea superior a vuestras fuerzas, si os arrepentís de lo que habéis hecho, ¡qué dolores, qué de maldiciones, qué de lágrimas secretamente vertidas, porque vosotras no sois como Marfa Petrovna! ¿Qué sería de vuestra madre cuando viese ciertas cosas que yo preveo? Ahora está inquieta, atormentada, pero, ¿qué será cuando vea las cosas tal como son en realidad? ¿Y yo? ¿Por qué habéis pensado en mí? Yo no acepto tu sacrificio, Dunetchka, no lo acepto. Mientras yo viva, no se celebrará esa boda.»\"},{\"heading\":false,\"text\":\"Se detuvo, quedándose como ensimismado.\"},{\"heading\":false,\"text\":\"--¡Que no se celebrará! ¿Qué puedes hacer tú para impedirlo? ¿Oponer tu _veto_? ¿Con qué derecho podrías hacerlo? ¿Qué podrías ofrecer por tu parte? ¿Les prometerías consagrarles toda tu vida, todo tu porvenir, _cuando hayas terminado tus estudios_ y encontrado una colocación? Eso es lo futuro, y aquí se trata de hacer algo por el presente. ¿Y qué es lo que ahora haces? ¡Arruinarlas! ¡Obligas a una a pedir prestado sobre una pensión y a la otra a solicitar un anticipo, sobre su sueldo, a los Svidrigailoff! So pretexto de que puedes llegar a ser millonario, pretendes disponer despóticamente de su suerte; pero, ¿puedes, en la actualidad, atender a sus necesidades? Tal vez podrás hacerlo cuando hayan transcurrido diez años; pero entonces tu madre habráse quedado ciega a fuerza de trabajar y llorar, y las privaciones habrán destruído su salud. ¿Y tu hermana? Vamos, Rodión, recapacita sobre los peligros que las amenazan durante estos diez años.\"},{\"heading\":false,\"text\":\"Experimentaba cierto punzante placer al hacerse estas dolorosas preguntas que, en rigor, no eran nuevas para él. Desde hacía tiempo le atormentaban incesantemente exigiéndole con imperio respuestas que él no encontraba. La carta de su madre acababa de herirle como un rayo. Comprendía que era pasado ya el tiempo de las lamentaciones estériles, que no trataba ya de razonar sino de hacer algo inmediatamente, costase lo que costase; era preciso tomar una resolución cualquiera.\"},{\"heading\":false,\"text\":\"--¡O renunciar a la vida--exclamó--aceptando el destino tal cual es, sofocando en mi alma todas mis aspiraciones, abdicando definitivamente mi derecho a ser, a vivir, a amar!\"},{\"heading\":false,\"text\":\"Rodión se acordó de repente de las palabras dichas el día antes por Marmeladoff: «¿Comprende usted, comprende usted, señor, lo que significa esta frase: No tener ya adónde ir?»\"},{\"heading\":false,\"text\":\"Acababa de presentarse ante su espíritu un pensamiento que también se le había ocurrido la víspera, y se estremeció. No era el retorno de este pensamiento lo que le hacía temblar, pues ya sabía que había de volver y lo esperaba, sino que esta idea no era exactamente igual a la de la víspera y consistía la diferencia en lo siguiente: lo que un mes antes, y aun el día antes, no era más que un sueño, surgía entonces bajo una nueva forma espantosa, desconocida. El joven tenía conciencia de este cambio... Sentía como un zumbido en el cerebro y una nube le cubría los ojos.\"},{\"heading\":false,\"text\":\"Se apresuró a mirar en torno suyo, como si buscase algo. Sentía ganas de sentarse, y lo que buscaba era un banco. Se encontraba entonces en la avenida de K***. A cien pasos de distancia, en efecto, había un banco. Apresuró el paso cuanto pudo, pero durante el breve trayecto le ocurrió un incidente, que durante algunos momentos, ocupó por completo su atención. En tanto que miraba hacia el banco, reparó en una mujer que caminaba a veinte pasos de él. Al pronto no puso más atención en ella que en los diferentes objetos que encontró al paso. Le ocurría muchas veces volver a su casa sin acordarse del camino recorrido. Andaba de ordinario sin ver nada. Pero en aquella mujer se notaba algo tan extraño a primera vista, que Raskolnikoff no pudo menos de advertirlo.\"},{\"heading\":false,\"text\":\"Poco a poco, a la sorpresa sucedió una curiosidad, contra la cual trató al pronto de luchar, pero que acabó por ser más fuerte que su voluntad. Le entró de repente el deseo de saber qué era lo que había de extraño en la mujer aquella. Según todas las apariencias, debía ser muy joven. A pesar del calor, iba sin nada en la cabeza, sin sombrilla y sin guantes, moviendo los brazos de una manera ridícula. Llevaba al cuello un pañolito pequeño y un vestido ligero, de seda, puesto de una manera singular, mal abrochado y desgarrado por detrás, cerca de la cintura. Un pedazo flotaba a derecha e izquierda. Para colmo de rareza, la joven, muy poco firme, andaba haciendo eses. Este recuerdo acabó de excitar toda la curiosidad de Raskolnikoff, el cual se reunió con la joven en el momento que ésta llegaba al banco. La muchacha se tendió más bien que se sentó, puso la cabeza en el respaldo y cerró los ojos como una persona quebrantada por la fatiga. Al examinarla, comprendió Raskolnikoff que estaba embriagada, y la cosa le pareció tan extraña, que no podía dar crédito a sus propios ojos. Tenía ante él una carita casi infantil que apenas representaba diez y seis años, quizá solamente quince. Aquella cara, rodeada de cabellos rubios, era muy linda pero estaba como arrebatada y un poco hinchada. Parecía que la joven no tenía conciencia de sus actos. Estaba con las piernas cruzadas una sobre la otra en actitud muy poco decorosa, y todos los indicios hacían suponer que no se daba cuenta del lugar donde se hallaba.\"},{\"heading\":false,\"text\":\"Raskolnikoff no se sentaba ni quería irse, y permanecía en pie frente a ella, sin saber qué resolver. Era más de la una y hacía un calor insoportable; así es que la avenida, que a otras horas suele estar muy concurrida, estaba casi desierta. Sin embargo, a quince pasos de distancia se mantenía apartado, en la cuneta del paseo, un señor que evidentemente deseaba aproximarse a la joven con ciertas intenciones. También, sin duda, la había visto de lejos y puéstose a seguirla; pero la presencia de Raskolnikoff le embarazaba. Echaba, disimuladamente, es verdad, miradas irritadas a este último y esperaba con impaciencia el momento en que aquel «descamisado» le cediese el puesto. Nada más claro. El tal caballero, vestido muy elegantemente, era de unos treinta años, grueso, fuerte, de tez rojiza, de labios rosados y fino bigote. Raskolnikoff, invadido de violenta cólera, y deseoso de insultarle, se apartó un instante de la joven y se aproximó al señor.\"},{\"heading\":false,\"text\":\"--¡Eh, Svidrigailoff!--exclamó el joven apretando los puños y riendo sardónicamente, lo que hacía que los labios se le cubriesen de espuma.\"},{\"heading\":false,\"text\":\"El elegante frunció las cejas, y su fisonomía tomó un aspecto de altanero estupor.\"},{\"heading\":false,\"text\":\"--¿Qué significa esto?--continuó con un tono despreciativo.\"},{\"heading\":false,\"text\":\"--Esto significa que es preciso que se vaya con la música a otra parte.\"},{\"heading\":false,\"text\":\"--¿Cómo te atreves, canalla...?\"},{\"heading\":false,\"text\":\"Y levantó el bastón; pero Raskolnikoff, con los puños cerrados, se lanzó sobre el grueso señor, sin pensar que éste habría dado fácilmente cuenta de dos adversarios como él. Mas en aquel momento alguien asió por detrás a Raskolnikoff: era un guardia que acertó a pasar casualmente junto a ellos.\"},{\"heading\":false,\"text\":\"--¡Calma, señores; no se peguen ustedes en la vía pública! ¿Qué le pasa a usted? ¿Quién es usted?--preguntó severamente a Raskolnikoff, fijándose en su miserable aspecto.\"},{\"heading\":false,\"text\":\"Raskolnikoff miró con atención a quien le hablaba. El guardia, con sus bigotes blancos, tenía cara de soldado veterano; parecía, además, inteligente.\"},{\"heading\":false,\"text\":\"--De usted precisamente tenía necesidad--dijo el joven, y agarró por el brazo al guardia--. Soy un antiguo estudiante; me llamo Raskolnikoff. Usted puede también oírlo--añadió, dirigiéndose al caballero--; venga usted conmigo--y, sin soltar al guardia, le llevó hasta el banco--. Mire usted, esa joven se halla en completo estado de embriaguez; hace un momento se paseaba por la avenida; es difícil averiguar su posición social; pero no parece mujer de vida alegre. Lo más probable es que la hayan emborrachado, y abusado de ella después... ¿Comprende usted?... Luego, ebria como estaba, la han echado a la calle. Vea usted los jirones que tiene el traje; repare usted cómo lo lleva puesto; esta joven no se ha vestido por sí misma, la han vestido manos inexpertas, seguramente manos de hombre. Fíjese usted. Este buen señor, con quien quería agarrarme hace un momento, a quien no conozco, a quien veo por primera vez, advirtiendo que esta muchacha está ebria y que no tiene conciencia de nada, ha querido aprovecharse de su estado para llevarla Dios sabe adónde. Esté usted seguro de que no le engaño; he visto cómo la miraba y la seguía; pero como mi presencia le estropeaba la combinación esperaba que me marchase... Vea usted cómo se ha separado de nosotros, y con qué aire de importancia hace un cigarrillo... ¿Cómo libraremos a esta joven de sus insidias? ¿De qué modo hacer que se vuelva a su casa? Piense usted un poco en esto...\"},{\"heading\":false,\"text\":\"El guardia se hizo cargo inmediatamente de la situación y se puso a reflexionar. No había duda respecto a las intenciones del caballero, pero quedaba la muchacha. El soldado se inclinó hacia ella para examinarla de cerca, y en su semblante se dibujó verdadera compasión.\"},{\"heading\":false,\"text\":\"--¡Ah, qué desgracia!--dijo moviendo la cabeza--. Es todavía una niña. De seguro se la ha tendido un lazo. Escuche, señorita; ¿dónde vive usted?\"},{\"heading\":false,\"text\":\"La joven levantó pesadamente los párpados y miró a los dos hombres con expresión imbécil e hizo un gesto como para rechazarlos.\"},{\"heading\":false,\"text\":\"Raskolnikoff sacó del bolsillo veinte kopeks.\"},{\"heading\":false,\"text\":\"--Tome usted--dijo al guardia--: tome usted un coche y llévela a su casa. Sólo falta que nos dé su dirección.\"},{\"heading\":false,\"text\":\"--¡Señorita, eh, señorita!--dijo de nuevo el guardia, después de tomar el dinero--. Voy a buscar un coche, y yo mismo la conduciré a usted a su casa. ¿Adónde hay que llevarla? ¿Dónde vive usted?\"},{\"heading\":false,\"text\":\"--¡Oh Dios mío!... ¡Me prenden!--murmuró la joven con el mismo movimiento de antes.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡Qué ignominia! ¡Qué infamia!--dijo el soldado, sintiendo a la vez piedad e indignación--. ¡Vaya un apuro!--añadió dirigiéndose a Raskolnikoff, a quien miró de nuevo de pies a cabeza.\"},{\"heading\":false,\"text\":\"Aquel desharrapado tan dispuesto a dar dinero, le parecía enigmático.\"},{\"heading\":false,\"text\":\"--¿La ha encontrado usted muy lejos de aquí?--preguntó.\"},{\"heading\":false,\"text\":\"--Ya le he dicho que iba delante de mí, por la avenida, tambaleándose. Apenas llegó a este banco, se dejó caer en él.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡Qué infamias se cometen en el mundo, señor! ¡Tan joven... y borracha! ¡La han engañado, de seguro! ¡Tiene la ropa desgarrada!... ¡Oh, cuánto vicio hay en el día!... Quizá sean sus padres nobles arruinados. ¡Hay tantos ahora! Parece una señorita de buena familia.\"},{\"heading\":false,\"text\":\"Acaso el guardia era padre de hijas bien educadas, a las cuales pidiera tomarse por muchachas de buena familia.\"},{\"heading\":false,\"text\":\"--Lo esencial--dijo Raskolnikoff--es impedir que caiga en las manos de ese hombre. De fijo que el bribón no ha desistido de su propósito. ¡Allí sigue!\"},{\"heading\":false,\"text\":\"Al decir estas palabras, el joven levantó la voz e indicó con un ademán al caballero. Este, al oír lo que de él se decía, hizo ademán de enfadarse; pero después, pensándolo mejor, se limitó a lanzar a su enemigo una mirada despreciativa y se alejó otros diez pasos, deteniéndose de nuevo.\"},{\"heading\":false,\"text\":\"--No, no se saldrá con la suya ese señor--respondió con aire pensativo el guardia--; si dijese dónde vive... pero no sabiéndolo... Señorita, ¡eh! señorita--añadió dirigiéndose otra vez a la joven.\"},{\"heading\":false,\"text\":\"De repente, la muchacha abrió los ojos y miró atentamente, como si un rayo de luz iluminase su espíritu. Se levantó y echó a andar en dirección opuesta a la que había llevado.\"},{\"heading\":false,\"text\":\"--¡Vaya con los sinvergüenzas! ¡qué manera de asediar a una!--dijo extendiendo de nuevo el brazo como para apartar a alguien.\"},{\"heading\":false,\"text\":\"Iba de prisa; pero con paso siempre poco seguro. El elegante se puso a seguirla, aunque por el otro lado del paseo, sin perderla de vista.\"},{\"heading\":false,\"text\":\"--Esté usted tranquilo; repito que no se saldrá con la suya--dijo resueltamente el guardia, y partió en seguimiento de la joven--. ¡Ah! ¡cuánto vicio hay ahora!--repitió, exhalando un suspiro.\"},{\"heading\":false,\"text\":\"En aquel momento debió operarse un cambio tan completo como repentino en el ánimo de Raskolnikoff, porque dirigiéndose al guardia gritó:\"},{\"heading\":false,\"text\":\"--Escuche usted.\"},{\"heading\":false,\"text\":\"El interpelado se volvió.\"},{\"heading\":false,\"text\":\"--¡Déjela usted! ¿Por qué se ha de mezclar usted en esto? ¡que se divierta (y señalaba al elegante) si quiere! A usted, ¿qué más le da?\"},{\"heading\":false,\"text\":\"El soldado no comprendió este lenguaje, y miró asombrado a Raskolnikoff, que se echó a reír.\"},{\"heading\":false,\"text\":\"--¡Ea!--dijo el guardia agitando el brazo.\"},{\"heading\":false,\"text\":\"Después se alejó detrás del señor elegante y de la muchacha. Probablemente habría tomado a Raskolnikoff por un loco o por algo peor.\"},{\"heading\":false,\"text\":\"--Se me ha llevado mis veinte kopeks--dijo éste con cólera cuando se quedó solo--. Luego el otro le dará también dinero, le abandonará la muchacha y asunto concluído... ¡Qué idea me ha dado a mí de echármelas de bienhechor! ¿Puedo yo acaso ayudar a nadie? ¿Tengo derecho a ello? Que las gentes se devoren unas a otras, ¿qué debe importarme? ¿Y por qué me he permitido regalarle los veinte kopeks? ¿Acaso eran míos?\"},{\"heading\":false,\"text\":\"A pesar de sus extrañas palabras, tenía el corazón angustiado. Se sentó como anonadado en el banco. Sus pensamientos eran incoherentes. Le molestaba en aquel momento pensar en nada. Hubiera querido dormirse profundamente, olvidarlo todo, despertarse después y comenzar una nueva vida.\"},{\"heading\":false,\"text\":\"--¡Pobrecilla!--dijo contemplando el sitio donde poco antes había estado sentada la joven--. Cuando vuelva en sí llorará; su madre sabrá su aventura. Primero la zarandeará; después la dará latigazos para añadir la humillación a su dolor, y quizá la echará de casa... Y aun cuando no la eche, cualquier Daría Frantzovna husmeará la casa y la pobre muchacha irá rodando de una parte a otra hasta que entre en el hospital, lo que no tardará en suceder (siempre pasa lo mismo a las muchachas que hacen a escondidas esa vida, porque tienen madres muy honradas). Una vez curada, volverá a las andadas; después otra vez al hospital... las tabernas... y otra vez al hospital... Al cabo de dos o tres años de esta vida, a los diez y ocho o a los diez y nueve años, será un andrajo. ¡A cuántas que han comenzado como ésta, he visto acabar del mismo modo! Pero, ¡bah! Es necesario, se dice, que así suceda; es un tanto por ciento anual, una prima de seguro público que debe ser pagada... para garantizar el reposo de las otras. ¡Un tanto por ciento! ¡Qué lindas frases! ¡encierran algo científico que tranquiliza! Cuando se dice «tanto por ciento», no hay más que hablar; ya no hay para qué preocuparse. Con otro nombre la cosa nos preocuparía más... ¿Quién sabe si Dunetchka no está comprendida en el «tanto por ciento» del año próximo, o quizás en el de este mismo año?\"},{\"heading\":false,\"text\":\"»Pero, ¿a dónde me proponía ir?--pensó de repente--. Es extraño. Al salir de casa tenía un propósito. Al acabar de leer la carta salí...\"},{\"heading\":false,\"text\":\"»¡Ah, sí! Ya me acuerdo. Iba a la plaza de Basilio Ostroff, a casa de Razumikin. Mas, ¿para qué? ¿Cómo se me ha ocurrido la idea de visitar a Razumikin?»\"},{\"heading\":false,\"text\":\"No se comprendía él mismo. Razumikin era un condiscípulo suyo de Universidad. Es de advertir que, cuando Raskolnikoff asistía a las clases de Derecho vivía muy aislado; no iba a casa de ninguno de sus condiscípulos, ni recibía sus visitas. Estos, por su parte, le correspondían del mismo modo. Jamás tomaba parte ni en las reuniones ni en las bromas de los estudiantes. Se le estimaba por su ejemplar aplicación; era muy pobre, muy orgulloso y muy reservado; sus compañeros creían que Raskolnikoff los miraba desdeñosamente como si fueran chiquillos, o por lo menos seres muy inferiores a él en conocimientos, en ideas y en desarrollo intelectual.\"},{\"heading\":false,\"text\":\"No obstante, intimó bastante con Razumikin, o mejor dicho, se mostró con él de carácter menos cerrado que con los otros. Verdad es que el genio franco e irreflexivo de Razumikin inspiraba irresistible confianza. Era este joven en extremo alegre, expansivo y bueno hasta la candidez, lo que no impedía que tuviese otras cualidades serias. Sus compañeros más inteligentes reconocían su mérito y todos le apreciaban. No tenía pelo de tonto, aunque pareciese imbécil. A primera vista, llamaba su atención por sus cabellos negros, su rostro siempre mal afeitado, su alta estatura y su excesiva delgadez.\"},{\"heading\":false,\"text\":\"Calavera en ocasiones, se le tenía por un Hércules. Una noche que recorría las calles de San Petersburgo en compañía de algunos amigos, echó a rodar de un solo puñetazo a un guardia municipal que tenía dos archines y doce vechoks[9]. Podía hacer los mayores excesos de bebida, y observaba, cuando se lo proponía, la más estricta sobriedad. Si a veces cometía inexcusables locuras, procedía otras con cordura ejemplar. Lo más notable del carácter de Razumikin era que jamás se descorazonaba ni se dejaba abatir por las contrariedades. Vivía en una guardilla, soportando los horrores del frío y del hambre, sin que por ello perdiera un momento su buen humor. Muy pobre, reducido a procurarse lo necesario para su subsistencia, encontraba medio de ganarse, bien o mal, la vida, porque era sobradamente despreocupado y conocía una porción de sitios en que le era posible encontrar dinero, por supuesto, trabajando.\"},{\"heading\":false,\"text\":\"[9] Aproximadamente 1,88 metros.\"},{\"heading\":false,\"text\":\"Pasó todo un invierno sin fuego; aseguraba que éste le agradaba sobremanera porque se duerme mejor cuando se tiene frío. Ultimamente había tenido que dejar la Universidad por falta de recursos; pero confiaba en reanudar en breve sus estudios y tampoco se descuidaba en mejorar su situación pecuniaria.\"},{\"heading\":false,\"text\":\"Raskolnikoff no había estado en su casa desde hacía cuatro meses, y Razumikin ignoraba dónde vivía su amigo. Se habían cruzado en la calle dos meses antes; pero Raskolnikoff se pasó a la otra acera para no ser visto por Razumikin. Este reconoció a Raskolnikoff; pero, no queriendo molestarle, fingió que no le veía.\"}]},{\"title\":\"primera parte — capítulo V\",\"blocks\":[{\"heading\":false,\"text\":\"--En efecto, no hace mucho que me proponía ir a casa de Razumikin a fin de suplicarle que me proporcionase algunas lecciones o cualquier otro trabajo...--se decía Raskolnikoff--. Pero ahora, ¿de qué ha de servirme? supongamos que puede proporcionarme alguna lección; hasta quiero suponer también que hallándose en fondos se quede sin un kopek siquiera para facilitarme medios con que comprar unas botas y el traje decente que necesita un pasante... Bueno, ¿y después? ¿Qué hago yo con unas cuantas piataks[10]? ¿Qué resuelvo con ellos? ¡Bah! sería una necedad ir a casa de Razumikin.\"},{\"heading\":false,\"text\":\"[10] La piatak es una moneda de cinco kopeks, equivalente a unos cuatro centavos.\"},{\"heading\":false,\"text\":\"La razón de saber por qué se dirigía entonces a casa de su amigo le causaba tormento mayor de lo que a sí mismo se confesaba; ansiaba dar algún sentido siniestro a esta marcha, en apariencia la más sencilla del mundo.\"},{\"heading\":false,\"text\":\"--¿Es posible que en mi situación haya puesto mis esperanzas todas en Razumikin? ¿Esperaba yo realmente de él remedio?--se preguntaba con estupor.\"},{\"heading\":false,\"text\":\"Reflexionaba, se frotaba la frente, y de repente, después de haber puesto algún tiempo su espíritu en tortura, brotó en su cerebro una extraña idea:\"},{\"heading\":false,\"text\":\"--Sí, iré a casa de Razumikin; pero no ahora; iré a verle al día siguiente, cuando _aquello_ esté hecho y mis negocios tengan otro aspecto...\"},{\"heading\":false,\"text\":\"Apenas hubo pronunciado aquellas palabras, experimentó una brusca conmoción.\"},{\"heading\":false,\"text\":\"--¡Cuando _aquello_ esté hecho!--exclamó con un sobresalto que le hizo levantarse del banco en que estaba sentado--. ¿Sucederá _eso_? ¿Será posible?\"},{\"heading\":false,\"text\":\"Dejó el banco y se alejó con apresurado paso. Su primer movimiento fué el de dirigirse a su domicilio; mas, ¿para qué? ¡Volver a aquel aposento en que acababa de pasar más de un mes premeditando todo _aquello_! Al saltarle este pensamiento, se sintió disgustado y se puso a marchar a la ventura. Su temblor nervioso tomó un carácter febril. Se estremeció convulsivamente y, a pesar de la elevación de la temperatura, tenía frío. Casi a su pesar, cediendo a una especie de necesidad interior, se esforzaba en fijar su atención en los diversos objetos que encontraba, para librarse de la obsesión de una idea que le trastornaba. En vano trataba de distraerse; a cada instante caía en su preocupación. Cuando levantaba la cabeza dirigía sus miradas en torno suyo, y olvidaba durante un minuto lo que venía pensando y aun el lugar donde se encontraba. De este modo fué como atravesó toda la plaza de Basilio Ostroff, desembocó en el pequeño Neva, pasó el puente y llegó a las islas. El verdor y la frescura regocijaron sus ojos, acostumbrados al polvo, a la cal, a los montones de arena y de escombros. Allí nada de ahogo, de exhalaciones metíficas, ni de tabernas.\"},{\"heading\":false,\"text\":\"Pero pronto perdieron estas sensaciones nuevas su encanto y dieron lugar a una gran inquietud. A veces el joven se detenía delante de alguna quinta que surgía coquetonamente en medio de una vegetación riente, miraba por la verja y veía en las terrazas y balcones mujeres elegantemente vestidas o niños que correteaban por los jardines. Se fijaba principalmente en las flores; era lo que atraía más sus miradas. De tiempo en tiempo pasaban al lado de él caballeros y amazonas y soberbios carruajes; los seguía con los ojos curiosos y los olvidaba antes de que lo hubiese perdido de vista.\"},{\"heading\":false,\"text\":\"Se detuvo para contar el dinero que llevaba en el bolsillo, y se encontró dueño, aproximadamente, de treinta kopeks. «He dado veinte al guardia y tres a Anastasia por la carta--pensó--; por consiguiente, son cuarenta y tres o cincuenta kopeks los que dejé ayer en casa de Marmeladoff.»\"},{\"heading\":false,\"text\":\"Había tenido motivo para comprobar el estado de su hacienda; pero un instante después ya no se acordaba de la razón por la cual sacó el dinero del bolsillo. A poco rato se acordó de comer, al pasar delante de un figón: su estómago se lo recordaba.\"},{\"heading\":false,\"text\":\"Entró en la taberna, se echó al cuerpo una copa de aguardiente y tomó un bocado. El poco de aguardiente que acababa de tomar le hizo inmediatamente efecto; le pesaban las piernas y le dió sueño. Quiso volverse a su casa, pero al llegar a Petrovsky Ostroff comprendió que no podía dar un paso más. Dejó, pues, el camino, penetró en el soto y se echó en la hierba, durmiéndose en seguida.\"},{\"heading\":false,\"text\":\"Cuando se está algo enfermo, los sueños suelen distinguirse por su relieve extraordinario y por su asombrosa semejanza con la realidad. El cuadro es a veces monstruoso; pero la _mise en scéne_ y todo lo que pertenece a la _representación_, son, sin embargo, tan verosímiles, los detalles tan minuciosos, y ofrecen por lo imprevisto una combinación tan ingeniosa, que el soñador, aunque sea un artista como Pushkin o Turgueneff, sería incapaz, despierto, de inventarlos tan bien. Estos sueños morbosos dejan siempre un gran recuerdo, y afectan profundamente el organismo, ya quebrantado, del individuo.\"},{\"heading\":false,\"text\":\"Raskolnikoff tuvo un sueño horrible. Se veía niño en la pequeña ciudad en que vivía entonces con su familia. Era un día festivo, y al anochecer, se paseaba _extramuros_ acompañado de su padre. El tiempo era gris, la atmósfera pesada; los lugares exactamente tales como su memoria los recordaba; en su sueño advirtió más de un detalle de que despierto no se acordaba. Veía todo el pueblo; en los alrededores ni un solo sauce blanco; allá, muy lejos, en el confín del horizonte, un bosquecillo formaba una mancha negra. A algunos pasos del último jardín del pueblo había una gran taberna, delante de la cual no podía pasar con su padre ni una sola vez sin experimentar una desagradable impresión y un sentimiento de miedo. Siempre estaba llena de multitud de personas que charlaban, reían, se injuriaban, se pegaban o cantaban con voz ronca cosas repugnantes; por los alrededores siempre se veían hombres borrachos. Al aproximarse Rodión se arrimaba a su padre y temblaba de pies a cabeza. El camino que conducía a la taberna estaba lleno de polvo negro. A trescientos pasos de allí, este camino formaba un recodo y daba vuelta al cementerio de la ciudad. En medio del cementerio se alzaba una iglesia de piedra, cubierta de una cúpula verde, adonde iba el niño dos veces al año a oír misa con su padre y su madre cuando se celebraba el funeral por el eterno descanso de su abuela, muerta hacía mucho tiempo, y a quien no había conocido. Llevaban un pastel de arroz con una cruz encima hecha con pasas. El niño amaba esta iglesia, con sus viejas imágenes, en su mayor parte desprovistas de adornos, y su anciano capellán de cabeza temblona. Al lado de la piedra que marcaba el sitio donde reposaban los restos de la anciana, había una tumba pequeña, la del hermano mayor de Rodión, muerto a los seis meses. Tampoco le había conocido, pero se le había dicho que había tenido un hermanito; así es que cada vez que visitaba el cementerio, hacía piadosamente la señal de la cruz encima de la tumba pequeña, e inclinándose con respeto la besaba.\"},{\"heading\":false,\"text\":\"He aquí ahora su sueño: va con su padre por el camino del campo santo; pasan delante de la taberna; él va asido de la mano de su padre y dirige miradas tenebrosas a la odiosa casa, donde reina mayor animación que de costumbre. Hay allí muchedumbre de campesinas y de mujeres de la clase media, vestidas con sus trajes domingueros, acompañadas de sus maridos y de la hez del pueblo. Todos están ebrios y todos cantan. Delante de la puerta de la taberna hay una de esas enormes carretas que se emplean de ordinario para el transporte de mercancías y toneles de vino, a las que se suelen enganchar vigorosos caballos de gruesas patas y largas crines. A Raskolnikoff le divertía contemplar aquellos robustos animales que arrastraban pesos enormes sin la menor fatiga. Pero ahora a esa pesada carreta estaba enganchado un caballejo flaquísimo, uno de esos escuálidos rocines que los _mujiks_ acostumbran enganchar a grandes carros de madera o de heno y a los que muelen a palos, llegando hasta pegarles en los ojos y en los befos cuando las pobres bestias hacen esfuerzos para arrastrar el vehículo atascado. Este espectáculo, visto varias veces por Raskolnikoff, le llenaba los ojos de lágrimas, y su madre, en tales casos, le apartaba siempre de la ventana. De repente se promueve un gran alboroto; de la taberna salen gritando, cantando y tocando la guitarra varios _mujiks_ completamente ebrios; llevan blusas rojas y azules, y los capottes echados negligentemente sobre los hombros.\"},{\"heading\":false,\"text\":\"--¡Subid, subid todos!--grita todavía un hombre, de robusto cuello y de rostro carnoso, color de zanahoria--. ¡Os llevo a todos, subid!\"},{\"heading\":false,\"text\":\"Estas palabras provocan risas y exclamaciones.\"},{\"heading\":false,\"text\":\"¡Hacer el camino con semejante penco!\"},{\"heading\":false,\"text\":\"--Has perdido el juicio, Mikolka; ¿a quién se le ocurre enganchar ese jamelgo a semejante carro?\"},{\"heading\":false,\"text\":\"--De seguro que este rocín tiene más de veinte años.\"},{\"heading\":false,\"text\":\"--Subid, os llevo a todos--grita de nuevo Mikolka, subiendo al primer carro, y, poniéndose de pie en el pescante del vehículo, aferra las riendas--. El caballo bayo se lo llevó Madviei y este animalucho, amigos míos, es una condenación para mí, debería matarlo: no gana lo que come. Os digo que subáis, ya veréis cómo lo hago galopar. ¡Vaya si galopará!\"},{\"heading\":false,\"text\":\"Y al decir esto, toma el látigo, gozoso con la idea de fustigar al pobre jaco.\"},{\"heading\":false,\"text\":\"--¡Ea, subamos, puesto que dice que vamos a ir al galope!--dijeron, burlándose, los del grupo.\"},{\"heading\":false,\"text\":\"--Apuesto a que hace diez años que no galopa.\"},{\"heading\":false,\"text\":\"--¡Buena marcha llevará!\"},{\"heading\":false,\"text\":\"--No tengáis miedo, amigos míos; tomad cada uno una vara, ¡y duro!\"},{\"heading\":false,\"text\":\"--¡Eso, eso, se le arreará!\"},{\"heading\":false,\"text\":\"Trepan todos al carro de Mikolka riendo y burlándose. Han subido ya seis hombres y queda sitio todavía. Con los que han montado va una gruesa campesina, de rostro rubicundo, vestida con un traje de algodón rojo, en la cabeza una especie de gorro adornado con abalorios y va partiendo avellanas y se ríe de tiempo en tiempo. También se ríe la gente que rodea el carro, y en efecto, ¿cómo no reírse ante la idea de que semejante penco lleve al galope a tantas personas? Dos de los que están en el carro toman látigos para ayudar a Mikolka.\"},{\"heading\":false,\"text\":\"--¡Andando!--grita este último.\"},{\"heading\":false,\"text\":\"El caballo tira con todas sus fuerzas; pero, lejos de galopar, apenas si puede avanzar un paso: patalea, gime y encoge los lomos bajo los golpes copiosos como el granizo que los tres látigos le descargan. Redoblan las risas en el carro y en el grupo; pero Mikolka se incomoda y golpea al jaco con más fuerza como si, en efecto, esperase hacerle galopar.\"},{\"heading\":false,\"text\":\"--Dejadme subir a mí también, amigos míos--grita entre los espectadores un joven que arde en deseos de mezclarse con la alegre pandilla.\"},{\"heading\":false,\"text\":\"--Sube--respondió Mikolka--. Subid todos, que yo le haré correr.\"},{\"heading\":false,\"text\":\"Y sigue, sigue golpeando, y en su furor no sabe ya con qué pegarle al animal.\"},{\"heading\":false,\"text\":\"--Papá, papá--dice el niño a su padre--, ¿qué están haciendo? ¡Pegan al pobre caballejo!\"},{\"heading\":false,\"text\":\"--Vamos, vamos--dice el padre--; son borrachos que se divierten a su modo. ¡Imbéciles! No les hagas caso.\"},{\"heading\":false,\"text\":\"Quiere llevárselo; pero Rodión se desprende de las manos paternales, y sin hacer caso de nada se acerca corriendo al caballo. El desgraciado cuadrúpedo no puede ya más. Resuella fatigosamente, trata de tirar, y poco falta para que no se caiga.\"},{\"heading\":false,\"text\":\"--¡Pegadle, pegadle hasta que reviente!--aúlla Mikolka--. Eso es lo que hay que hacer. Yo os ayudaré.\"},{\"heading\":false,\"text\":\"--¡Tú no eres cristiano, sino lobo!--grita un viejo del grupo.\"},{\"heading\":false,\"text\":\"--¿A quién se le ocurre que un animalejo tan pequeño pueda arrastrar un armatoste como éste?--grita otro.\"},{\"heading\":false,\"text\":\"--¡Bribón!--vocifera un tercero.\"},{\"heading\":false,\"text\":\"--No es tuyo, es mío; hago lo que quiero. ¡Subid aún! ¡Es preciso que galope!\"},{\"heading\":false,\"text\":\"De repente la voz de Mikolka queda ahogada por las carcajadas de la gente; el animal, atormentado por los palos, acaba por perder la paciencia, y a pesar de su debilidad, empieza a tirar coces. Hasta el mismo viejo se echa a reír. Y había, en efecto, motivos de risa: ¡un caballo que no puede sostenerse en pie y que, sin embargo, cocea!\"},{\"heading\":false,\"text\":\"Dos campesinos se destacan del grupo, y armados de látigos la emprenden a palos con el animal. Uno por la derecha y otro por la izquierda.\"},{\"heading\":false,\"text\":\"--¡Dadle en los morros, en los ojos, sí, en los ojos!--vociferaba Mikolka.\"},{\"heading\":false,\"text\":\"--¡Una canción, amigos!--grita uno del corro, e inmediatamente toda la pandilla entona una canción soez al son de una pandereta.\"},{\"heading\":false,\"text\":\"La campesina sigue partiendo avellanas y se ríe.\"},{\"heading\":false,\"text\":\"Rodión se acerca al caballo y ve que le pegan en los ojos, ¡sí, en los ojos! El niño llora; se le subleva el corazón y corren sus lágrimas. Uno de los verdugos le toca el rostro con el látigo, pero él no lo siente. Se retuerce las manos y grita. Después se dirige al viejo de la barba y cabellos blancos, que mueve la cabeza y condena aquellas demasías.\"},{\"heading\":false,\"text\":\"Una mujer toma al niño de la mano y quiere apartarlo de esta escena; pero él se escapa y corre otra vez hacia el caballo. Este, ya casi sin fuerzas, intenta aún cocear.\"},{\"heading\":false,\"text\":\"--¡Ah, maldito!--exclama Mikolka, deja el látigo, se baja, toma del fondo del carro un largo y pesado garrote y lo blande con fuerza con las dos manos sobre el pobre caballo.\"},{\"heading\":false,\"text\":\"--¡Lo va a matar!--gritaban en derredor suyo.\"},{\"heading\":false,\"text\":\"--¡Lo matará!\"},{\"heading\":false,\"text\":\"--¡Es mío!--grita Mikolka, y el garrote, manejado por dos brazos vigorosos, cae con estrépito sobre el lomo del animal.\"},{\"heading\":false,\"text\":\"--¡Fustígalo! ¿Por qué te detienes?--gritan varias voces en el grupo.\"},{\"heading\":false,\"text\":\"De nuevo el garrote se levanta y cae sobre el espinazo de la pobre bestia. Bajo la violencia del golpe, el caballejo está a punto de caerse. Sin embargo, hace un supremo esfuerzo con todas las fuerzas que le quedan; tira, tira en diversos sentidos para escapar de aquel suplicio, mas por todas partes encuentra los seis látigos de sus perseguidores. Mikolka una vez y otra vez golpea a su víctima con el garrote. Está furioso por no poder matarlo de un solo golpe.\"},{\"heading\":false,\"text\":\"--¡No quiere morir!--gritan los del grupo.\"},{\"heading\":false,\"text\":\"--¡No le queda mucho de vida!--observa uno de los que contemplan regocijados el bárbaro espectáculo--. Se acerca su último momento.\"},{\"heading\":false,\"text\":\"--Dale con un hacha; es el medio de acabar con él--apunta un tercero.\"},{\"heading\":false,\"text\":\"--Dejadme--dice Mikolka, y suelta el garrote; busca de nuevo en el carro, y toma una barra de hierro--. ¡Fuera!--grita, y asesta un violento golpe al pobre caballo.\"},{\"heading\":false,\"text\":\"El penco se tambalea; quiere aún tirar, pero un segundo golpe con la barra le tiende en el suelo, como si le hubiesen cortado instantáneamente los cuatro miembros.\"},{\"heading\":false,\"text\":\"--¡Acabemos!--aúlla Mikolka, que, fuera de sí, salta del carro.\"},{\"heading\":false,\"text\":\"Algunos mocetones, rojos y avinados, agarran cada cual lo que tienen más a mano, látigos, palos, el garrote, y corren al caballo expirante. Mikolka, en pie, al lado de la bestia, la golpea sin cesar con la barra de hierro. El caballo extiende la cabeza y muere.\"},{\"heading\":false,\"text\":\"--¡Ha muerto!--gritan en el grupo.\"},{\"heading\":false,\"text\":\"--¿Por qué no quería galopar?\"},{\"heading\":false,\"text\":\"--¡Era mío!--gritó Mikolka, teniendo siempre en la mano la barra.\"},{\"heading\":false,\"text\":\"Tenía los ojos inyectados de sangre. Parecía enfurecido porque la muerte le hubiese quitado su víctima.\"},{\"heading\":false,\"text\":\"--¡La verdad! ¡Tú no eres cristiano!--gritan indignados algunos asistentes.\"},{\"heading\":false,\"text\":\"El pobre niño está fuera de sí. Dando voces se abre paso por entre el grupo que rodea al caballo, levanta la cabeza ensangrentada del cadáver, le besa en el hocico y en los ojos... Después, en un repentino arrebato de cólera, cierra los puños y se arroja sobre Mikolka. En aquel momento su padre, que desde hace un rato le buscaba, lo encuentra al fin y le aparta de la gente.\"},{\"heading\":false,\"text\":\"--¡Vámonos, vámonos!--le dijo--. Volvamos a casa.\"},{\"heading\":false,\"text\":\"--¡Papá! ¿por qué han matado al pobre caballo?--solloza el niño; pero le falta la respiración; de su garganta salen roncos sonidos.\"},{\"heading\":false,\"text\":\"--¡Son barbaridades de gente ebria! ¡Nada tenemos que ver con ellos!--dice el padre.\"},{\"heading\":false,\"text\":\"Rodión le oprime entre sus brazos; pero siente tal fatiga... quiere respirar, grita, y se despierta.\"},{\"heading\":false,\"text\":\"Raskolnikoff se despertó jadeando, con el cuerpo húmedo y los cabellos empapados de sudor; se sentó bajo un árbol y respiró con fuerza.\"},{\"heading\":false,\"text\":\"--¡Gracias a Dios, no ha sido más que un sueño!--dijo--. ¡Cómo! ¿Iré a tener fiebre? No sería extraño, después de un sueño tan horroroso.\"},{\"heading\":false,\"text\":\"Tenía quebrantados los miembros, y el alma llena de obscuridad y de confusión. Apoyó los codos en las rodillas y dejó caer la cabeza entre las manos.\"},{\"heading\":false,\"text\":\"--¡Dios mío!--exclamó--. ¿Será posible, en efecto, que yo tome un hacha y parta el cráneo de aquella mujer?... ¿Será posible que yo ande por encima de sangre tibia y viscosa, que fuerce la cerradura, robe y me oculte, temblando, ensangrentado, con el hacha?... ¡Señor! ¿Será posible?\"},{\"heading\":false,\"text\":\"Al decir esto temblaba como la hoja en el árbol.\"},{\"heading\":false,\"text\":\"--Pero, ¿por qué pienso en esas cosas?--continuó con profunda sorpresa--. Veamos; sé muy bien que no soy capaz de ello; ¿por qué, pues, me atormenta esa idea? Ayer, ayer ya, cuando fuí a hacer el _ensayo_, comprendí perfectamente que _aquello_ era superior a mis fuerzas. ¿De dónde procede que siga dando vueltas a la misma idea? Ayer, al bajar la escalera, iba diciendo que era innoble, odioso, repugnante... Solamente pensar en tal cosa me aterraba.\"},{\"heading\":false,\"text\":\"»No, no me atreveré; esto es superior a mis fuerzas. Aunque todos mis razonamientos no dejasen lugar a duda, aunque todas las conclusiones a que he llegado durante un mes fuesen claras como el día, exactas como la Aritmética, no podría decidirme a dar este paso. ¡No soy capaz! ¿Por qué pues, por qué ahora...?\"},{\"heading\":false,\"text\":\"Se levantó, miró en torno suyo, como si se sorprendiese de estar allí, y se encaminó hacia el puente T***. Estaba pálido y le brillaban los ojos. Todo su ser mostraba decaimiento; pero comenzaba a respirar con más libertad. Se sentía ya libre del horrible peso que durante largo tiempo le había oprimido, y su alma recobraba la paz.\"},{\"heading\":false,\"text\":\"--¡Señor!--exclamó--; ¡muéstrame mi camino y renunciaré a este designio maldito!\"},{\"heading\":false,\"text\":\"Al atravesar el puente miró tranquilamente el río, y contempló la resplandeciente puesta de sol. A pesar de su debilidad, no se sentía cansado. Se hubiera dicho que acababa de recobrar repentinamente la salud de su espíritu. Ahora es libre. Estaba roto el encanto. Había cesado de influir sobre él el horrible maleficio.\"},{\"heading\":false,\"text\":\"Más tarde, Raskolnikoff se acordó, minuto por minuto, del empleo de su tiempo durante aquellos días de crisis; entre otras circunstancias, venía a menudo a su pensamiento una que, aun cuando en rigor no tenía nada de extraordinario, le preocupaba como una especie de terror supersticioso, a causa de la acción decisiva que había ejercido sobre su destino.\"},{\"heading\":false,\"text\":\"He aquí el hecho que constituía para él siempre un enigma. ¿Por qué cuando cansado, exhausto, hubiera debido, como era natural, volver a su casa por el camino más corto y más directo, se le había ocurrido pasar por el Mercado de Heno en donde nada, absolutamente nada le llamaba? Verdad era que este rodeo no alargaba mucho su camino; pero resultaba completamente inútil. Se le había ocurrido mil veces volverse a su casa sin fijarse en el itinerario recorrido.\"},{\"heading\":false,\"text\":\"--¿Pero por qué, pues--se preguntaba siempre--, por qué aquel encuentro tan importante, tan decisivo para mí, al mismo tiempo tan fortuito, que tuve en el Mercado del Heno (adonde no tenía para qué ir), se verificó en el momento mismo en que, dadas las disposiciones en que me encontraba, había de tener para mí las más graves y terribles consecuencias?\"},{\"heading\":false,\"text\":\"Tentado estaba de ver en esta fatal coincidencia el efecto de una predestinación.\"},{\"heading\":false,\"text\":\"Cerca eran de las nueve cuando el joven llegó al Mercado del Heno. Los tenderos cerraban sus establecimientos; los vendedores ambulantes se preparaban, lo mismo que los tratantes, a volver a su casa. Obreros y desharrapados de toda especie bullían en los alrededores de los bodegones y tabernas que en el Mercado del Heno ocupaban el piso bajo de la mayor parte de los edificios. Esta plaza y los _pereuloks_[11] de sus inmediaciones eran los lugares que Raskolnikoff frecuentaba de mejor gana cuando salía sin saber adónde ir. Allá, en efecto, sus harapos no llamaban la atención a nadie y podía, él como cualquiera, pasearse vestido como tuviera por conveniente. En la esquina del _pereulok_ de K***, un mercader que, como los demás, se disponía a volver a su casa, hablaba con su mujer y con una conocida que acababa de aproximarse a ellos. Esta última era Isabel Ivanovna, hermana de Alena Ivanovna, la usurera en cuya casa Raskolnikoff había entrado la víspera a empeñar su reloj y a hacer el _ensayo_.\"},{\"heading\":false,\"text\":\"[11] Pasaje.\"},{\"heading\":false,\"text\":\"De tiempo atrás sabía algo acerca de esta Isabel; ella también le conocía. Era alta y desgarbada solterona de treinta y cinco años, tímida, dulce y casi idiota. Temblaba ante su hermana, que la trataba como esclava, la hacía trabajar día y noche y hasta le pegaba.\"},{\"heading\":false,\"text\":\"En aquel momento su fisonomía expresaba indecisión, en tanto que en pie, con un paquete en la mano, escuchaba atentamente lo que le decían el vendedor y su mujer.\"},{\"heading\":false,\"text\":\"Estos hablaban de algo importante, a juzgar por el calor que ponían en sus palabras.\"},{\"heading\":false,\"text\":\"Cuando Raskolnikoff vió de repente a Isabel, experimentó una sensación extraña parecida a profunda sorpresa, aunque este encuentro no tuviese nada de asombroso.\"},{\"heading\":false,\"text\":\"--Es preciso que esté usted aquí para tratar del negocio, Isabel Ivanovna--dijo con fuerza el vendedor--. Venga usted mañana de seis a siete. También vendrán los otros.\"},{\"heading\":false,\"text\":\"--¿Mañana?--dijo vacilante Isabel, que parecía temerosa de decidirse.\"},{\"heading\":false,\"text\":\"--¿Tiene usted miedo a Alena Ivanovna?--dijo vivamente la vendedora, que era una mujerona enérgica--. No la perderé de vista, porque usted es como una niña. ¿Será posible que se deje usted dominar hasta ese punto por una persona que no es, después de todo, más que su hermanastra?\"},{\"heading\":false,\"text\":\"--No diga usted ahora nada a Alena Ivanovna--dijo el marido--. Se lo aconsejo; venga usted a casa sin consultarla. Se trata de un negocio ventajoso; su hermana se convencerá de ello en seguida.\"},{\"heading\":false,\"text\":\"--¿De modo que tengo que venir?\"},{\"heading\":false,\"text\":\"--Mañana entre seis y siete vendrán también los demás; es preciso que esté usted presente para decidir el asunto.\"},{\"heading\":false,\"text\":\"--Le ofreceremos una taza de te--añadió la vendedora.\"},{\"heading\":false,\"text\":\"--Está bien, vendré--respondió Isabel pensativa, y se dispuso a marcharse.\"},{\"heading\":false,\"text\":\"Raskolnikoff había pasado ya del grupo formado por las tres personas y no oyó más. Había prudentemente acortado el paso, esforzándose por no perder palabra de la conversación. A la sorpresa del primer momento había sucedido en él un vivo terror. Una casualidad imprevista le acababa de dar a conocer que al día siguiente, a las siete de la tarde, Isabel, la hermana, la única compañera de la vieja, estaría fuera, y que, por lo tanto, al día siguiente, a las siete en punto, la vieja _se encontraría sola en su casa_.\"},{\"heading\":false,\"text\":\"El joven estaba a algunos pasos de su domicilio. Entró en su casa como si lo hubiesen condenado a muerte. No pensó en nada, ni estaba en disposición de pensar; sintió súbitamente en todo su ser que no tenía ni voluntad, ni libre albedrío, y que todo estaba definitivamente resuelto. Ciertamente, hubiera podido esperar años enteros sin una ocasión favorable, aun tratando de hacerla nacer como aquella que acababa de ofrecérsele. En todo caso le habría sido difícil saber la víspera a ciencia cierta y sin correr el menor riesgo, sin comprometerse con preguntas imprudentes, que mañana a tal hora, tal vieja, a quien él quería matar, estaría sola en su casa.\"}]},{\"title\":\"primera parte — capítulo VI\",\"blocks\":[{\"heading\":false,\"text\":\"Raskolnikoff supo después por qué el vendedor y su mujer habían invitado a Isabel a venir a su casa. La cosa era sencillísima: una familia extranjera que, encontrándose muy apurada, quería deshacerse de algunos efectos, que consistían en vestidos y en ropa interior usada de mujer. Estas personas deseaban ponerse en relación con la vendedora. Isabel ejercía este oficio, y tenía una numerosa clientela, porque era muy formal y decía siempre el último precio. Con ella no había regateo; en general hablaba poco, y, como hemos dicho, era muy tímida.\"},{\"heading\":false,\"text\":\"Desde hacía algún tiempo Raskolnikoff se había hecho supersticioso y, por consiguiente, cuando reflexionaba, sobre todo este asunto, se inclinaba siempre a ver en él la acción de causas extrañas y misteriosas. El invierno último, un estudiante conocido suyo, Pokorieff, a punto de volverse a Kharkoff, le había dado, al despedirse, la dirección de la vieja Alena Ivanovna, para caso de que tuviera necesidad de algún préstamo sobre prendas. Pasó mucho tiempo sin ir a casa de la vieja, porque el producto de sus lecciones le permitía ir viviendo. Seis semanas antes de los acontecimientos que vamos refiriendo, se acordó de las señas; poseía dos objetos por los cuales podía prestársele algo: un reloj de plata que conservaba de su padre, y un anillo pequeño de oro con tres piedrecitas rojas, que su hermana le había dado como recuerdo en el momento de separarse.\"},{\"heading\":false,\"text\":\"Raskolnikoff se decidió a llevar la sortija a casa de Alena Ivanovna. Desde el primer momento, y antes de que él supiera nada de particular acerca de ella, la vieja le inspiró una violenta aversión. Después de haber recibido el dinero entró en un mal _taklir_[12] que encontró al paso. Allí pidió te, se sentó y púsose a reflexionar. Una idea extraña, todavía en estado embrionario en su espíritu, le ocupaba por completo.\"},{\"heading\":false,\"text\":\"[12] Cafetucho.\"},{\"heading\":false,\"text\":\"Ante una mesa vecina a la suya, un estudiante, a quien no se acordaba de haber visto jamás, estaba sentado con un oficial.\"},{\"heading\":false,\"text\":\"Los dos jóvenes acababan de jugar al billar y se disponían ahora a tomar el te. De repente, Raskolnikoff oyó al estudiante que daba al oficial la dirección de Alena Ivanovna, viuda de un secretario de colegio y prestamista sobre prendas.\"},{\"heading\":false,\"text\":\"Esto sólo pareció ya un poco extraño a nuestro héroe: se hablaba de una persona de cuya casa acababa él de salir. Sin duda, todo ello era pura casualidad; pero en aquel momento hallábase bajo una impresión que no podía dominar, y he aquí que, precisamente en aquel momento, alguien venía a fortificar en él esta impresión. El estudiante comunicaba, en efecto, a su amigo, diversos pormenores acerca de Alena Ivanovna.\"},{\"heading\":false,\"text\":\"--Es un famoso recurso--decía--; siempre hay medio de procurarse dinero en su casa. Rica como un judío, puede prestar cinco mil rublos de una vez, y, sin embargo, acepta objetos que no valen más que un rublo. Es una providencia para muchos de nosotros. Pero, ¡qué horrible arpía!\"},{\"heading\":false,\"text\":\"Se puso a contar que era mala, caprichosa; que no concedía siquiera veinticuatro horas de prórroga, y que toda prenda no retirada en el día fijo, era irrevocablemente perdida por el deudor; prestaba sobre un objeto la cuarta parte de su valor y cobraba el cinco y el seis por ciento de interés mensual, etc. El estudiante, que estaba en vena de hablar hasta por los codos, añadió que esta horrible vieja era pequeñuela, lo que no le impedía pegar a menudo y tener en completa dependencia a su hermana Isabel, que medía, por lo menos, dos archines y ocho verchoks de estatura.\"},{\"heading\":false,\"text\":\"--¡Es un fenómeno!--exclamó, y se echó a reír.\"},{\"heading\":false,\"text\":\"La conversación recayó en seguida sobre Isabel.\"},{\"heading\":false,\"text\":\"El estudiante hablaba de ella con marcado placer y siempre sonriendo. El oficial escuchaba a su amigo con mucho interés y le suplicó que le enviase a aquella Isabel para que le repasase la ropa.\"},{\"heading\":false,\"text\":\"Raskolnikoff no perdió una palabra de esta conversación y supo de esta suerte una multitud de cosas. Más joven que Alena Ivanovna, de la cual no era más que media hermana, Isabel tenía treinta y cinco años y trabajaba día y noche para la vieja. Además de los quehaceres de la cocina, era lavandera, hacía labores de costura, que luego vendía, iba a fregar los suelos a las casas, y todo lo que ganaba se lo entregaba a su hermanastra. No se atrevía a aceptar ningún encargo ni trabajo sin consultar a la usurera, la cual, como Isabel sabía muy bien, había otorgado ya testamento en el cual no dejaba a su hermana más que el mobiliario. Deseosa de tener a perpetuidad sufragios por el eterno descanso de su alma, dejaba toda su fortuna a un monasterio. Isabel pertenecía a la clase media y no al _tchin_. Era una estantigua, con pies muy grandes y calzados siempre con anchos zapatos; pero, por otra parte, iba limpia como una patena. Lo que particularmente asombraba y hacía reír al estudiante, era que Isabel estaba siempre en cinta.\"},{\"heading\":false,\"text\":\"--¿Pero no dices que es un monstruo?--preguntóle el oficial.\"},{\"heading\":false,\"text\":\"--Realmente, es demasiado trigueña; parece un soldado vestido de mujer; pero de eso a que sea un monstruo, hay mucha diferencia. Su fisonomía revela tanta bondad y tienen sus ojos una expresión tan simpática que... La prueba es que ella agrada a muchas personas. Es tan tranquila, tan dulce, tan paciente, tiene un carácter tan bueno y, además, su sonrisa es tan bondadosa...\"},{\"heading\":false,\"text\":\"--¿Estás enamorado de ella?--interrogóle, sonriendo, el oficial.\"},{\"heading\":false,\"text\":\"--Hombre, tanto como eso, no; pero me gusta, precisamente por lo rara que es. En cambio, a esa maldita vieja te aseguro que la mataría y la despojaría de todo lo que posee sin escrúpulo de conciencia--añadió vivamente el estudiante.\"},{\"heading\":false,\"text\":\"El oficial lanzó una carcajada; pero Raskolnikoff se estremeció. Las palabras que oía encontraban extraño eco en sus propios pensamientos.\"},{\"heading\":false,\"text\":\"--Vamos a ver--prosiguió el estudiante--. Hace un momento me burlaba, pero ahora hablo en serio. Fíjate: de un lado una vieja enfermiza, necia, un ser que no es útil a nadie, y que, por el contrario, perjudica a muchos, que no sabe ella misma por qué vive y que morirá mañana de muerte natural. ¿Comprendes?\"},{\"heading\":false,\"text\":\"--Comprendo--repuso el oficial mirando atentamente a su interlocutor.\"},{\"heading\":false,\"text\":\"--Prosigo. Del otro lado, fuerzas jóvenes, frescas, que se quebrantan, se pierden, faltas de sostén, y esto a millares, por todas partes. Cien mil obras útiles se podrían acometer o mejorar con el dinero legado por esa vieja a un monasterio; centenares de existencias, millones quizá, puestas en el buen camino; docenas de familias salvadas de la miseria, de la disolución, de la ruina, del vicio, de los hospitales... y todo ello con el dinero de esa mujer. Si se la matase y se destinase su fortuna al bien de la humanidad, ¿crees tú que el crimen, si eso fuese un crimen, no estaría largamente compensado por millares de buenas acciones? Por una sola vida, millares de vidas arrancadas a la perdición; por una persona suprimida, cien personas devueltas a la existencia. Se trata de una cuestión aritmética. ¿Qué pesa en las balanzas sociales la vida de una vieja necia y mala? Poco más que la vida de una hormiga o de un escarabajo; me atrevo a decir que menos, porque esta vieja es una criatura perversa. Hace poco, en un acceso de rabia, mordió un dedo a Isabel, y en poco estuvo que no se lo cortase con los dientes.\"},{\"heading\":false,\"text\":\"--Cierto que es indigna de vivir--respondió el oficial--; ¿pero qué quieres? la Naturaleza...\"},{\"heading\":false,\"text\":\"--Amigo mío, a la Naturaleza se la corrige, se la endereza; de lo contrario, viviríamos enterrados en prejuicios, no habría un solo grande hombre. Se habla del deber, de la conciencia. No quiero decir que esté mal, pero, ¿qué sentido damos a estas palabras? Escucha, voy a plantearte otra cuestión.\"},{\"heading\":false,\"text\":\"--No, chico, ahora me toca a mí. Te voy a preguntar una cosa.\"},{\"heading\":false,\"text\":\"--Conforme.\"},{\"heading\":false,\"text\":\"--Verás: tú estás ahora perorando con gran elocuencia; pero, dime: ¿Matarías tú, con tus propias manos, a esa vieja?\"},{\"heading\":false,\"text\":\"--¡Claro que no! pero yo considero esto desde el punto de vista de la justicia... No se trata de mí...\"},{\"heading\":false,\"text\":\"--Pues bien, amigo mío, ¿quieres saber mi opinión? Vas a oírlo: Puesto que no te decidirías a matarla, opino que la cosa no es justa. Vamos a echar otra partida.\"},{\"heading\":false,\"text\":\"Raskolnikoff era presa de una agitación extraordinaria. En rigor, esta conversación no tenía nada de asombroso. Muchas veces había oído a los jóvenes cambiar entre sí análogas ideas; lo único que difería era el tema; mas, ¿por qué el estudiante expresaba precisamente los mismos pensamientos que en aquel instante bullían en el cerebro de Raskolnikoff? ¿Y por qué casualidad éste, al salir de la casa de la vieja, oía hablar de ella? Tal coincidencia le pareció extraña: estaba escrito que esta insignificante conversación de café tuviese en su destino decisiva influencia.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Al volver a su domicilio, se dejó caer en el sofá y permaneció sentado en él, sin moverse, durante una hora entera. La obscuridad era completa; en la habitación no había ni vela, ni Raskolnikoff pensó que era necesaria. No hubiera podido precisar si en esta hora había pensado algo. Por último, le entraron escalofríos febriles, y pensó con satisfacción que podía echarse del todo en el sofá... No tardó en caer en pesado y profundo sueño.\"},{\"heading\":false,\"text\":\"Durmió mucho más tiempo que de costumbre y sin soñar. A Anastasia, que entró en su habitación al día siguiente a las diez, le costó gran trabajo despertarle. La criada le traía pan, y, como la víspera, algo del te que ella acostumbraba a tomar.\"},{\"heading\":false,\"text\":\"--¡Aun no se ha levantado!--exclamó indignada--. ¿Es posible dormir así?\"},{\"heading\":false,\"text\":\"Raskolnikoff se incorporó con dificultad. Le dolía la cabeza. Se puso en pie, dió una vuelta por la habitación y después se dejó caer de nuevo en el sofá.\"},{\"heading\":false,\"text\":\"--¡Otra vez!--gritó Anastasia--. ¿Estás malo?\"},{\"heading\":false,\"text\":\"El joven no respondió.\"},{\"heading\":false,\"text\":\"--¿Quieres tomar te?\"},{\"heading\":false,\"text\":\"--Más tarde--contestó penosamente, y luego cerró los ojos y se volvió del lado de la pared.\"},{\"heading\":false,\"text\":\"Anastasia, en pie, cerca de él, le contempló durante algún tiempo.\"},{\"heading\":false,\"text\":\"--Indudablemente está enfermo--dijo antes de retirarse.\"},{\"heading\":false,\"text\":\"A las dos volvió con la sopa. Encontró a Raskolnikoff acostado aún en el sofá. No había probado el te. La criada se incomodó y se puso a sacudir con fuerza al joven.\"},{\"heading\":false,\"text\":\"--¿Qué te pasa para dormir tanto?--gruñó, mirándole con desprecio.\"},{\"heading\":false,\"text\":\"Raskolnikoff se incorporó, pero no respondió una palabra ni levantó los ojos del suelo.\"},{\"heading\":false,\"text\":\"--¿Estás malo o no lo estás?\"},{\"heading\":false,\"text\":\"Esta pregunta no obtuvo más respuesta que la primera.\"},{\"heading\":false,\"text\":\"--Deberías salir--dijo ella después de una pausa--. El aire libre te sentaría bien. Vas a comer, ¿no es verdad?\"},{\"heading\":false,\"text\":\"--Más tarde--respondió con voz débil--; ¡vete!--y la despidió con un ademán.\"},{\"heading\":false,\"text\":\"La criada se detuvo un momento, miró compasivamente al joven y se marchó.\"},{\"heading\":false,\"text\":\"Al cabo de algunos minutos, Raskolnikoff levantó los ojos, examinó detenidamente el te y la sopa, y se puso a comer.\"},{\"heading\":false,\"text\":\"Tomó tres o cuatro cucharadas sin apetito, casi maquinalmente. El dolor de cabeza se le había calmado algo, y cuando hubo terminado su frugal comida se echó de nuevo en el sofá; pero, aunque no pudo dormir, permaneció inmóvil, con la cara hundida en la almohada. La imaginación le presentaba, sucediéndose sin cesar, los cuadros más extraños. Figurábase a veces estar en Africa; formaba parte de una caravana detenida en un oasis; altas palmeras rodeaban el campamento; los camellos reposaban de sus fatigas; los viajeros se disponían a comer. El, por su parte, apagaba la sed en el chorro de una cristalina fuente; el agua azulada y deliciosamente fresca dejaba ver en el fondo del riachuelo piedrezuelas de diversos colores y arenas de dorados reflejos.\"},{\"heading\":false,\"text\":\"De repente hirió sus oídos el sonido de la campana de un reloj; aquel ruido le hizo temblar, y, adquiriendo nuevamente el sentimiento de la realidad, se levantó de un salto, después de mirar a la ventana y calcular la hora que podría ser. Anduvo en seguida de puntillas, se aproximó a la puerta, la abrió suavemente y se puso a escuchar.\"},{\"heading\":false,\"text\":\"El corazón le latía con violencia. La escalera estaba silenciosa, parecía que todo dormía en la casa.\"},{\"heading\":false,\"text\":\"--¿Cómo me he dejado vencer en el momento decisivo? ¿Cómo desde ayer no he hecho nada, ni preparado nada?--se preguntaba a sí mismo, no comprendiendo su negligencia; y, sin embargo, eran quizá las seis las que acababan de dar.\"},{\"heading\":false,\"text\":\"A su inercia y entorpecimiento siguió bruscamente febril y extraordinaria actividad. Por otra parte, los preparativos no exigían mucho tiempo. Hacía esfuerzos para pensar en todo y no olvidarse de nada, y su corazón latía con tal fuerza que dificultaba la respiración. Primero tenía que hacer un nudo corredizo, y adaptarlo a su gabán; aquello era cosa de un minuto; buscó en la ropa que tenía debajo de la almohada una camisa vieja, sucia e inservible. Después, con trozos arrancados a esta camisa, hizo una especie de trenza de un verchot de ancha y ocho de larga. La dobló en dos partes, se quitó el gabán de verano, que era de una espesa y fuerte tela de algodón (único sobretodo que poseía), y se puso a coser interiormente, bajo el sobaco izquierdo, los dos extremos de la trenza. Al ejecutar este trabajo, le temblaban las manos; pero le quedó tan bien, que cuando volvió a ponerse el gabán no se veía el cosido por la parte de afuera. Se había proporcionado mucho tiempo antes la aguja y el hilo, y no tuvo más que sacar ambas cosas del cajón de su mesa.\"},{\"heading\":false,\"text\":\"En cuanto al nudo corredizo para colgar el hacha, se le había ocurrido un medio muy ingenioso, ya ideado quince días antes. Ir por la calle con un hacha en la mano, era imposible; por otra parte, ocultar el arma bajo el gabán, le obligaba a llevar continuamente la mano debajo, y esto podría llamar la atención, en tanto que con el nudo corredizo le bastaba poner en él el hierro del hacha, y quedaba suspendida bajo el sobaco todo el tiempo de la marcha, sin peligro de que cayera. Podía también impedir que se moviese sin más que oprimir la extremidad del mango con la mano metida en el bolsillo del gabán. Este era muy ancho, un verdadero saco, y la maniobra no podría ser advertida.\"},{\"heading\":false,\"text\":\"Hecho esto, Raskolnikoff metió el brazo bajo la otomana e introduciendo los dedos en una hendidura del suelo, sacó de aquel escondrijo el objeto empeñable de que había tenido cuidado de proveerse con anticipación. Este objeto no era más que una tableta de madera acepillada, del tamaño que suelen tener las cigarreras de plata. En uno de sus paseos el joven había encontrado por casualidad este trozo de madera en el corral de un taller de carpintería. Tomó, además, una plaquita de hierro delgada y pulimentada, pero de menos dimensiones, que había encontrado también en la calle, y después de juntar una cosa con la otra (la tabla y la placa), las ató fuertemente con un hilo, y lo envolvió todo en un trozo de papel blanco.\"},{\"heading\":false,\"text\":\"Este paquetito, al cual el joven había tratado de dar un aspecto todo lo elegante que le fué posible, quedó atado de manera que era muy difícil desatarlo.\"},{\"heading\":false,\"text\":\"Por tal medio se ocuparía momentáneamente la atención de la vieja; mientras ésta estuviese procurando deshacer el nudo, Raskolnikoff podría elegir el momento oportuno. Había juntado con la tabla la placa de hierro para que el supuesto objeto de empeño pesase más, a fin de que en el primer momento, por lo menos, la usurera no sospechase que se le pedía dinero a cambio de un pedazo de madera. Apenas Raskolnikoff acababa de guardarse el hacha en el bolsillo, cuando oyó una voz que le decía en la escalera:\"},{\"heading\":false,\"text\":\"--Ya hace mucho que han dado las seis.\"},{\"heading\":false,\"text\":\"--¡Dios mío! ¿Mucho?\"},{\"heading\":false,\"text\":\"Se dirigió a la puerta, aplicó el oído y se puso a bajar los treinta escalones sin hacer más ruido que un gato. Quedaba lo más importante: ir a la cocina a recoger el hacha con que se había determinado a cometer el crimen. Ya hacía tiempo que tenía pensado valerse de un hacha. Había en su casa una especie de hoz, pero este instrumento no le inspiraba confianza, y además desconfiaba de su destreza para manejarla; así fué que se decidió definitivamente por el hacha. Advirtamos a propósito de esto una particularidad singular; a medida que sus resoluciones tomaban un carácter determinado, más absurdas y horribles le parecían al joven. A pesar de la lucha desesperada que se libraba en su interior, no llegaba a admitir ni por un solo instante que acabaría por no poner en ejecución su sanguinario proyecto.\"},{\"heading\":false,\"text\":\"Si todos los obstáculos hubieran sido vencidos, todas las dudas disipadas, todas las dificultades allanadas, probablemente habría renunciado a su designio por absurdo, monstruoso e imposible. Pero le quedaba todavía multitud de puntos que esclarecer y de problemas que resolver. Lo de hacerse con el hacha no inquietaba en modo alguno a Raskolnikoff, porque esto era muy fácil. Anastasia no estaba casi nunca por la tarde en casa; acostumbraba salir para chismorrear con sus amigas o en las tiendas, y éste solía ser el motivo de las reprimendas de su ama.\"},{\"heading\":false,\"text\":\"No había más que entrar cautelosamente en la cocina cuando llegase el momento oportuno, tomar el hacha y ponerla en el mismo sitio una hora después cuando todo hubiese terminado.\"},{\"heading\":false,\"text\":\"Dudaba, empero, que saliese todo a medida de sus deseos.\"},{\"heading\":false,\"text\":\"--Supongamos--pensaba el joven--que dentro de una hora, cuando yo vuelva a dejar el hacha, haya regresado Anastasia. Naturalmente, en tal caso tendré que aguardar para entrar en la cocina a que salga la criada; ¿pero y si durante este tiempo echa de menos el hacha y se pone a buscarla? Si no la encuentra refunfuñará, y ¡quién sabe! armará un alboroto en la casa. Esto sería una circunstancia que podría ser funesta.\"},{\"heading\":false,\"text\":\"Sin embargo, no quería pensar en tales pormenores; además, no tenía tiempo para ello. Se preocupaba de lo más importante, decidido a desdeñar lo accesorio hasta que hubiese tomado una determinación sobre lo esencial. Esto último, empero, le parecía irrealizable. No podía imaginar que en un momento dado cesaría de pensar, se levantaría e iría allí derechamente... Aun en su reciente _ensayo_ (es decir, en la visita que había hecho para tantear el terreno), había faltado poco para que el joven hubiese ensayado seriamente. Actor sin convicción, no pudo sostener su papel y huyó indignado contra sí mismo.\"},{\"heading\":false,\"text\":\"No obstante, desde el punto de vista moral, la cuestión estaba resuelta. La casuística del joven, afilada como una navaja de afeitar, había cortado todas las objeciones; pero no encontrándolas en su mente se esforzaba en buscarlas fuera. Hubiérase dicho que, arrastrado por una potencia ciega, irresistible, sobrehumana, trataba desesperadamente de encontrar un punto fijo a que agarrarse. Los imprevistos accidentes de la víspera influían sobre él de una manera automática del mismo modo que el hombre a quien el engranaje de la rueda de una máquina le agarra una parte de su traje acaba por ser despedazado por la misma máquina.\"},{\"heading\":false,\"text\":\"La primera cuestión que le preocupaba sobremanera y en la cual había pensado muchas veces, era esta: ¿por qué se descubren tan fácilmente todos los crímenes y por qué se encuentran con tanta facilidad las huellas de casi todos los culpables?\"},{\"heading\":false,\"text\":\"Poco a poco llegó a diversas conclusiones muy curiosas. Según él la principal razón del hecho consistía menos en la imposibilidad material de ocultar el crimen que en la personalidad misma del criminal. Este último experimentaba en el momento de cometer el delito una diminución de la voluntad y de la inteligencia; por esta razón solía proceder con aturdimiento infantil, con ligereza fenomenal, precisamente cuando la circunspección y la prudencia le eran más necesarias.\"},{\"heading\":false,\"text\":\"Raskolnikoff comparaba este eclipse del juicio y este desfallecimiento de la voluntad, a una afección morbosa que se desarrolla por grados, que llega al máximum de intensidad poco antes de la perpetración del crimen, que subsistía en la misma forma durante la comisión de él y aun algunos momentos después (más o menos tiempo según los individuos) para cesar luego como cesan todas las enfermedades. Un punto no esclarecido era el de saber si la enfermedad determina el crimen o si el crimen, por su naturaleza propia, va acompañado siempre de algún fenómeno morboso; pero el joven no se sentía capaz de resolver esta cuestión.\"},{\"heading\":false,\"text\":\"Razonando de esta manera llegó a persuadirse de que él personalmente estaba al abrigo de semejantes trastornos morales, y de que conservaría la plenitud de su inteligencia y de su voluntad, durante la empresa, sencillamente porque «su empresa no era un crimen...» No referiremos la serie de argumentos que le habían conducido a esta última conclusión. Nos limitamos a decir que en sus preocupaciones, al lado práctico, las dificultades puramente materiales de ejecución, quedaban en el segundo término. «Que conserve yo mi presencia de espíritu, mi fuerza de voluntad, y cuando llegue el momento triunfaré de todos los obstáculos...» Pero no ponía manos a la obra. Menos que nunca creía en la persistencia final de sus resoluciones, y al sonar la hora se despertó como de un sueño.\"},{\"heading\":false,\"text\":\"No estaba aún al pie de la escalera cuando una circunstancia insignificante vino a desconcertarle. Llegado al descansillo en que estaba el cuarto de su patrona, encontró, como siempre, abierta de par en par la puerta de la cocina, y miró discretamente: estando ausente Anastasia, ¿no era posible que estuviese allí la patrona? Y aunque no se hallase en la cocina, ¿tendría bien cerrada la puerta de su habitación? ¿No podría verle cuando entrase por el hacha? Era necesario cerciorarse. Pero, ¡cuál no sería su estupor al ver que Anastasia, contra su costumbre, estaba en la cocina! Más todavía: que andaba muy atareada, sacando ropa del cesto y tendiéndola en unas cuerdas. Al aparecer el joven, la criada, interrumpiendo su trabajo, se volvió hacia él y no dejó de mirarle hasta que se hubo alejado.\"},{\"heading\":false,\"text\":\"Raskolnikoff volvió los ojos y pasó como si no se hubiera fijado en nada; pero aquélla era cosa concluída: no tenía hacha. Esta circunstancia fué para él un golpe terrible.\"},{\"heading\":false,\"text\":\"--¿De dónde había sacado yo--pensaba al bajar los últimos peldaños de la escalera--que precisamente en este momento había salido Anastasia? ¿Por qué se me habrá metido tal cosa en la cabeza?\"},{\"heading\":false,\"text\":\"Sentíase como aplastado, como anonadado. Su despecho le impulsaba a burlarse de sí mismo. Hervía en todo su ser una cólera salvaje.\"},{\"heading\":false,\"text\":\"Se detuvo indeciso en la puerta cochera; vagar por las calles, salir sin objeto, no le apetecía; pero aun le era más desagradable volver a subir. «¡Y pensar que he perdido para siempre tan buena ocasión!», murmuró enfrente del cuarto del _dvornik_, cuarto que estaba también abierto.\"},{\"heading\":false,\"text\":\"De repente se echó a temblar. En la garita del portero, a dos pasos de Raskolnikoff, debajo del banco, brillaba un hacha... El joven miró en derredor suyo. Nadie. Se aproximó suavemente al chiribitil, bajó dos escaloncitos y llamó con voz débil al _dvornik_: «Vamos, no está en su casa; pero no debe de andar lejos, porque no ha cerrado la puerta.» De pronto, como un rayo, se lanzó hacia el hacha y la sacó de debajo del banco donde estaba entre dos troncos. En seguida pasó el arma por el nudo corredizo, se metió las manos en los bolsillos y salió. Nadie le vió. «No es la inteligencia la que me ayuda, es el diablo», pensó, sonriéndose de un modo extraño. Aquella casualidad contribuyó poderosamente a darle valor.\"},{\"heading\":false,\"text\":\"Caminaba lenta, gravemente, temeroso de despertar sospechas. Apenas miraba a los transeuntes a fin de atraer lo menos posible la atención. De repente pensó en su sombrero. «¡Dios mío! ¡Anteayer tenía dinero y hubiera podido comprarme una gorra!» Del fondo de su alma brotó una imprecación. Una ojeada que por casualidad dirigió a una tienda donde había un reloj colgado de la pared, le hizo saber que eran ya las siete y diez. Urgía el tiempo, y, sin embargo, tenía que dar un rodeo para que no se le viese llegar de aquel lado a la casa.\"},{\"heading\":false,\"text\":\"Entretanto se verificaba en él un extraño fenómeno; en contra de lo que se figuraba, no sentía miedo alguno; así, en vez de preocuparse por el crimen que se disponía a cometer, otros sentimientos ajenos a su empresa ocupaban su espíritu. Al pasar por delante del jardín de Jussupoff pensaba que sería conveniente establecer en todas las plazas públicas fuentes monumentales que refrescasen la atmósfera. Luego, por una serie de transiciones insensibles, comenzó a fantasear que si al jardín de Verano se le diese toda la extensión del campo de Marte y se le añadiese el jardín del palacio Miguel, San Petersburgo ganaría con ello higiénica y artísticamente considerado.\"},{\"heading\":false,\"text\":\"«Del mismo modo, sin duda, las personas que son conducidas al suplicio se fijan en todos los objetos que encuentran en el camino.» Se le ocurrió esta idea; pero se apresuró a desecharla. En tanto se aproximó: vió la casa, vió la puerta. De repente oyó que un reloj daba una sola campanada. «¡Cómo! ¿Serán ya las siete y media? ¡Imposible! Ese reloj adelanta.»\"},{\"heading\":false,\"text\":\"También esta vez la casualidad sirvió a Raskolnikoff. Como si lo hubiera hecho a propósito, en el momento mismo en que llegaba frente a la casa, entraba por la puerta cochera una enorme carreta cargada de heno. El joven pudo franquear el umbral sin ser visto, deslizándose por el espacio que quedaba entre la carreta y la pared. Cuando estuvo en el patio, tomó rápidamente por la derecha. Del otro lado de la carreta disputaban algunos hombres. Raskolnikoff les oía gritar pero ninguno se fijó en él ni él por su parte encontró a nadie. Muchas de las ventanas que daban a aquel inmenso patio cuadrado estaban abiertas: sin embargo, no levantó la cabeza. Su primer movimiento fué ganar la escalera de la vieja que era la de la derecha.\"},{\"heading\":false,\"text\":\"Conteniendo la respiración y con la mano apoyada en el corazón para comprimir sus latidos, se puso a subir los peldaños, cerciorándose antes de que el hacha estaba bien sujeta por el nudo corredizo. A cada minuto se paraba a escuchar; pero la escalera estaba completamente desierta y todas las puertas cerradas. En el segundo piso había un cuarto desalquilado, que estaba abierto, y en donde trabajaban algunos pintores; pero éstos no vieron a Raskolnikoff, que se detuvo un instante para reflexionar, y luego continuó subiendo. «Mejor hubiera sido que no estuviesen; pero por encima de ellos, hay todavía dos pisos.»\"},{\"heading\":false,\"text\":\"Llegó al cuarto piso sin encontrarse con nadie, y se halló ante la puerta de Alena Ivanovna, donde volvió a detenerse para reflexionar. El cuarto de enfrente estaba desocupado. En el tercero, la habitación situada precisamente por debajo de la de la vieja, se hallaba también vacía, según todas las apariencias: la tarjeta que antes había en la puerta, no estaba: los inquilinos se habían ido... Raskolnikoff se ahogaba. Vaciló un momento. «¿No sería mejor que me fuera?» Pero sin responder a esa pregunta, se puso a escuchar; no oyó ningún ruido en casa de la vieja; en la escalera el mismo silencio. Después de haber estado escuchando largo rato, el joven echó una mirada en torno suyo y tentó nuevamente su hacha. «¿No estaré demasiado pálido?--pensó--. ¿No se notará mi agitación? Esa mujer es muy desconfiada. Debiera esperar a que se calmase mi emoción.»\"},{\"heading\":false,\"text\":\"Pero, lejos de calmarse, eran cada vez más violentas las pulsaciones del corazón del joven. No pudo contenerse más, y extendiendo lentamente la mano hacia el cordón de la campanilla, tiró de él. Al cabo de medio minuto llamó de nuevo, con más fuerza. Ninguna respuesta; llamar violentamente hubiera sido inútil y hasta imprudente. La vieja de seguro estaba en su casa; pero como era desconfiada, debía serlo más en este momento en que se encontraba sola. Raskolnikoff conocía en parte las costumbres de Alena Ivanovna. De nuevo aplicó el oído a la puerta. Su excitación desarrollaba en él una agudeza particular de sensaciones (lo que en general es difícil de admitir), o en rigor el ruido era fácilmente perceptible.\"},{\"heading\":false,\"text\":\"Sea como fuere, le pareció oír que una mano se apoyaba con precaución en la cerradura, escuchaba, esforzándose por disimular su presencia. No queriendo parecer que se ocultaba, el joven llamó por tercera vez pero suavemente para no denunciar su impaciencia. Aquel instante dejó a Raskolnikoff un recuerdo imborrable. Cuando después pensaba en ello, no acertaba a explicarse cómo había podido desplegar tanta astucia precisamente en el momento en que su emoción era tal que le quitaba el uso de sus facultades intelectuales y físicas. Al cabo de un instante oyó que descorrían el cerrojo.\"}]},{\"title\":\"primera parte — capítulo VII\",\"blocks\":[{\"heading\":false,\"text\":\"Lo mismo que en su visita anterior, Raskolnikoff vió entreabrirse la puerta lentamente y por la estrecha abertura dos ojos muy brillantes que se fijaban en él con expresión de desconfianza. Entonces le abandonó su sangre fría y cometió una falta que hubiera podido dar al traste con todo.\"},{\"heading\":false,\"text\":\"Temiendo que Alena Ivanovna tuviese miedo de encontrarse sola con un visitante de aspecto poco tranquilizador, tiró de la puerta con violencia hacia sí para que la vieja no procurase cerrarla. La usurera no intentó siquiera hacerlo, pero no quitó la mano de la cerradura, de manera que faltó poco para que cayera de bruces en el descansillo, hacia donde se abría la puerta. Como Alena Ivanovna permanecía de pie en el umbral para no dejar el paso libre, el joven avanzó hacia ella. Aterrada la vieja dió un salto hacia atrás; pero no pudo pronunciar una palabra y miró a Raskolnikoff abriendo los ojos desmesuradamente.\"},{\"heading\":false,\"text\":\"--Buenas tardes, Alena Ivanovna--dijo él con el tono más natural que pudo; pero en vano trataba de fingir; su voz era entrecortada y temblorosa--; traigo un objeto, pero entremos: para examinarlo hay que verlo a la luz...\"},{\"heading\":false,\"text\":\"Y sin esperar a que se le dijera que pasase, penetró en la habitación. La vieja se le acercó vivamente; ya se le había desanudado la lengua.\"},{\"heading\":false,\"text\":\"--¡Señor!... ¿Qué quiere usted, quién es usted, qué se le ofrece?\"},{\"heading\":false,\"text\":\"--¡Vamos, Alena Ivanovna!; usted me conoce muy bien... Raskolnikoff; tenga usted paciencia. Vengo a empeñar esta alhaja de la que le hablé el otro día--y le alargó el paquete.\"},{\"heading\":false,\"text\":\"Alena Ivanovna iba a examinarlo, cuando de repente cambió de idea, y levantando los ojos dirigió una mirada penetrante, irritada y desconfiada sobre aquel importuno que se le metía en casa con tan poca ceremonia. Raskolnikoff hasta creyó advertir cierta especie de burla en los ojos de la vieja, como si ésta lo hubiese adivinado todo. Se daba cuenta el joven de que perdía la serenidad, de que tenía casi miedo, de que si aquella muda investigación se prolongaba medio minuto, iba, sin duda, a echar a correr.\"},{\"heading\":false,\"text\":\"--¿Por qué me mira usted de ese modo, como si no me conociese?--dijo irritándose a su vez--. Si usted quiere eso, lo toma, si no, lo deja; iré a otra parte con ello; es inútil que me haga usted perder el tiempo.\"},{\"heading\":false,\"text\":\"Se le escaparon estas palabras sin que las hubiera premeditado.\"},{\"heading\":false,\"text\":\"El lenguaje resuelto del visitante tranquilizó a la usurera.\"},{\"heading\":false,\"text\":\"--¿Qué prisa hay, _batuchka_? ¿Qué es eso?--preguntó mirando el paquete.\"},{\"heading\":false,\"text\":\"--Una cigarrera de plata; ya se lo dije a usted la otra tarde.\"},{\"heading\":false,\"text\":\"La vieja extendió la mano.\"},{\"heading\":false,\"text\":\"--¡Qué pálido está usted! ¿Está usted malo, _batuchka_?\"},{\"heading\":false,\"text\":\"--Tengo fiebre--respondió con voz brusca--. ¿Cómo no he de estar pálido?... Cuando uno no tiene que comer...--acabó de decir, no sin esfuerzo--, le abandonan las fuerzas de nuevo.\"},{\"heading\":false,\"text\":\"La respuesta parecía verosímil; la vieja tomó el paquete.\"},{\"heading\":false,\"text\":\"--¿Qué es esto?--preguntó por segunda vez, y tanteando el peso de la prenda, miró fijamente a su interlocutor.\"},{\"heading\":false,\"text\":\"--Una petaca de plata... mírela usted.\"},{\"heading\":false,\"text\":\"--Cualquiera diría que no es plata... ¡Oh, cómo la han atado!\"},{\"heading\":false,\"text\":\"En tanto que Alena Ivanovna hacía esfuerzos por desatar el hilo, se había aproximado a la luz. (Todas las ventanas estaban cerradas, a pesar del calor sofocante que hacía.) En esta posición daba la espalda a Raskolnikoff, y durante algunos segundos no se ocupó en él. El joven se desabrochó el gabán y separó el hacha del nudo corredizo; pero sin sacarla todavía, se limitó a tenerla con la mano derecha debajo del sobretodo. Sentía una terrible debilidad en todos sus miembros. Comprendía que cada instante que pasaba su debilidad iba en aumento; temía que se le escapase el hacha de la mano, y le parecía que todo le daba vueltas en su derredor.\"},{\"heading\":false,\"text\":\"--¿Pero qué hay aquí dentro?--gritó coléricamente Alena Ivanovna, e hizo un movimiento en dirección a Raskolnikoff.\"},{\"heading\":false,\"text\":\"No había tiempo que perder. Sacó el joven el hacha de debajo del gabán, la levantó con las dos manos casi maquinalmente, porque no tenía fuerzas, y la dejó caer sobre la cabeza de la vieja. De repente, en cuanto hubo dado el golpe, sintió Raskolnikoff que recobraba toda su energía física.\"},{\"heading\":false,\"text\":\"Alena Ivanovna, como de costumbre, no llevaba nada en la cabeza. Sus cabellos, grises y escasos, y, como siempre, untados de aceite, recogíalos, formando trenzas en la nuca con un trozo de peineta de cuerno. El golpe dió precisamente en la coronilla, a lo cual contribuyó la escasa estatura de la víctima. La usurera lanzó un grito débil y cayó desplomada teniendo, sin embargo, todavía fuerzas para llevarse los brazos a la cabeza. En una de las manos conservaba la «prenda». Entonces Raskolnikoff que, como hemos dicho, había recobrado todo su vigor, asestó dos nuevos hachazos en el occipucio de la vieja. La sangre brotó a chorros y el cuerpo quedó exánime. El joven se echó hacia atrás y en cuanto vió a la anciana sin movimiento se inclinó para mirarla: estaba muerta; los ojos, desmesuradamente abiertos, parecían salirse de las órbitas, y las convulsiones de la agonía daban a su rostro la expresión de una horrible mueca.\"},{\"heading\":false,\"text\":\"El asesino dejó el hacha en el suelo e inmediatamente se puso a registrar el cadáver, tomando todo género de precauciones para no mancharse de sangre. Se acordaba de haber visto la última vez a Alena Ivanovna buscar las llaves en el bolsillo derecho de su vestido. Se hallaba en plena posesión de su inteligencia. No experimentaba ni aturdimiento ni vértigos; pero seguían temblándole las manos. Más tarde recordó que había sido muy prudente, y que había puesto mucho cuidado en no mancharse. No tardó en encontrar las llaves. Como el día anterior, estaban todas reunidas en una anilla de acero.\"},{\"heading\":false,\"text\":\"Después de haberse apoderado de ellas, Raskolnikoff entró en la alcoba. Era ésta muy pequeña, y había en ella un estante lleno de imágenes piadosa; en el otro lado una gran cama muy limpia con una colcha de seda almohadillada y hecha de pedazos cosidos. En la otra pared una cómoda. Cosa extraña; apenas hubo comenzado el joven a servirse de las llaves para abrir este mueble, le recorrió todo el cuerpo un escalofrío. Estuvo tentado de renunciar a todo y marcharse; pero esta idea duró sólo un momento; era demasiado tarde para retroceder.\"},{\"heading\":false,\"text\":\"Hasta llegó a sonreírse de haber podido pensarlo, cuando, de repente, sintió una terrible inquietud: ¿Si por acaso la vieja no estuviera muerta y recobrase el sentido? Dejando las llaves en la cómoda, acudió vivamente cerca del cuerpo, tomó el hacha y se dispuso a dar otro golpe a su víctima; pero el arma, ya levantada, no cayó; no había duda de que Alena Ivanovna estaba muerta. Inclinándose de nuevo sobre ella para examinarla más de cerca, Raskolnikoff se convenció de que la mujer tenía el cráneo partido. En el sucio se había formado un lago de sangre. Viendo de improviso que la vieja tenía un cordón al cuello, el joven tiró de él violentamente; pero el cordón ensangrentado era recio y no se rompió.\"},{\"heading\":false,\"text\":\"El asesino trató entonces de quitárselo, haciendo que se deslizase a lo largo del cuerpo; pero no fué más afortunado en esta segunda tentativa; el cordón encontró un obstáculo y no pasaba. Impaciente Raskolnikoff, blandió el hacha, pronto a descargarla sobre el cadáver para cortar con el mismo golpe aquel maldito cordón. Sin embargo, no pudo resolverse a proceder con aquella brutalidad. Al cabo, después de dos minutos de esfuerzos que le pusieron rojas las manos, logró cortar el cordón con el filo del hacha, sin herir el cuerpo de la muerta. Como había supuesto, lo que la vieja llevaba al cuello era una bolsa. También estaban sujetas al cordón una medallita esmaltada y dos cruces, la una de madera de ciprés, la otra de cobre. La bolsa, grasienta (un saquito de piel de camello), estaba completamente llena. Raskolnikoff se la metió en el bolsillo sin mirar lo que contenía; arrojó las cruces sobre el pecho de la vieja, y tomando el hacha volvió a entrar con ella apresuradamente en la alcoba.\"},{\"heading\":false,\"text\":\"La impaciencia le devoraba, y puso mano a la obra de desvalijamiento; pero sus tentativas para abrir la cómoda eran infructuosas, no tanto por el temblor de las manos, como por sus continuas torpezas. Veía, por ejemplo, que tal llave no era de la cerradura y se obstinaba, sin embargo, en hacerla entrar.\"},{\"heading\":false,\"text\":\"De pronto se acordó de una conjetura que había hecho en su anterior visita: aquella gruesa llave que estaba con las otras pequeñas en la anilla de acero, debía de ser no de la cómoda, sino de alguna caja en que acaso la vieja tenía encerrados todos sus valores. Sin ocuparse más en la cómoda, miró bajo la cama, sabiendo que los viejos tienen la costumbre de ocultar en ese sitio sus tesoros. En efecto, había allí un cofre de poco más de una archina de largo y cubierto de cuero rojo. La llave dentellada entraba perfectamente en la cerradura. Cuando Raskolnikoff levantó la tapa, vió colocados sobre un trapo blanco un abrigo forrado de piel de liebre con guarnición roja, debajo del abrigo una falda de seda y después un chal; el fondo parecía contener solamente trapos. El joven comenzó por secarse las manos ensangrentadas en la guarnición roja. «Sobre lo rojo, la sangre se conocerá menos.» De pronto pareció como que volvía en sí: «¡Señor! ¿Me habré vuelto loco?», murmuró con terror.\"},{\"heading\":false,\"text\":\"Pero apenas empezó a registrar aquellas ropas, cuando de debajo de la piel se deslizó un reloj de oro. En vista de esto, revolvió de arriba abajo el contenido del cofre. Entre los vestidos se hallaban objetos de oro, sin duda depositados como empeños, en manos de la usurera, brazaletes, cadenas, pendientes, alfileres de corbata, etc.; los unos encerrados en sus estuches, los otros anudados con una cinta en un pedazo de periódico doblado en dos partes.\"},{\"heading\":false,\"text\":\"Raskolnikoff no vaciló; metió mano a todas estas alhajas y se llenó los bolsillos del pantalón y del gabán sin abrir los estuches ni deshacer los paquetes; pero de pronto fué interrumpido en esta maniobra. En la habitación donde estaba la vieja sonaron pasos. Se detuvo helado de terror. Pero el ruido había cesado, el joven empezaba a creer que había sido engañado por una alucinación de su oído, cuando de súbito percibió, distintamente, un ligero grito o más bien un gemido débil y entrecortado. Al cabo de uno o dos minutos, todo volvió a quedar en un silencio de muerte. Raskolnikoff, sentado en el suelo cerca del cofre, esperaba respirando apenas. De repente dió un salto, tomó el hacha y se lanzó fuera de la alcoba.\"},{\"heading\":false,\"text\":\"En medio de la sala, Isabel, con un gran bulto en las manos, contemplaba aterrorizada el cadáver de su hermana, y, pálida como la cera, parecía no tener fuerzas para gritar ante la brusca aparición del asesino. Comenzó a temblar, trató de levantar el brazo, de abrir la boca; pero no pudo dar ni un grito, y andando hacia atrás lentamente con la mirada fija en Raskolnikoff, fué a refugiarse en un rincón de la sala. La pobre mujer hizo esto sin gritar, como si le faltase el aliento. El asesino se lanzó sobre ella con el hacha levantada; los labios de la infeliz tomaron la expresión lastimera que suelen tomar los de los niños pequeños cuando están espantados.\"},{\"heading\":false,\"text\":\"Tal horror sentía la desdichada, que aunque vió que el hacha se levantaba sobre ella, no pensó ni aun en defender la cara, llevándose las manos a la cabeza con un movimiento maquinal que sugiere en semejantes casos el instinto de conservación. Apenas si levantó el brazo izquierdo extendiéndolo lentamente en dirección del agresor, que descargó sobre Isabel un golpe terrible. El hierro del hacha penetró en el cráneo, hendió toda la parte superior de la frente y llegó casi hasta el occipucio: Isabel cayó rígida, muerta. Sin saber lo que hacía, Raskolnikoff tomó el paquete que la víctima tenía en la mano; después lo tiró y salió al recibimiento.\"},{\"heading\":false,\"text\":\"Estaba aterrado a causa de aquel nuevo asesinato que no había sido premeditado por él. Quería desaparecer cuanto antes. «Si hubiese podido darse mejor cuenta de las cosas; si hubiese calculado todas las dificultades de su posición, si la hubiera previsto tan desesperada, tan horrible, tan absurda, como era; si hubiera comprendido bien los obstáculos que quedaban por vencer, quizá los crímenes que tendría que perpetrar para huir de aquella casa y entrar en la suya... probablemente habría renunciado a la lucha para correr a denunciarse, y no por cobardía, sino por horror de lo que había hecho.» Esta impresión le iba dominando. Por nada del mundo se habría aproximado a la caja ni entrado en la alcoba.\"},{\"heading\":false,\"text\":\"Poco a poco, sin embargo, comenzaron a surgir en su espíritu otros pensamientos, y cayó en una especie de delirio. Por momentos el asesino parecía olvidarse de sí mismo, o más bien, de olvidar lo principal, para fijarse en lo insignificante. Una mirada dirigida a la cocina le hizo descubrir un cubo medio lleno de agua, y se le ocurrió lavarse las manos y limpiar el hacha. A causa de la sangre tenía pegajosas las manos. Después de haber metido el hierro del arma en el agua, tomó un pedazo de jabón que había en el poyo de la ventana y comenzó a refregarse las manos. Cuando se las hubo lavado, enjugó el hierro del hacha y en seguida empleó tres minutos en jabonar el mango, para hacer desaparecer las salpicaduras de sangre. Después lo secó todo con un paño de cocina que estaba colgado en una cuerda. Hecho esto, se aproximó a la ventana, con objeto de examinar atenta y detenidamente el hacha. Las huellas acusadoras habían desaparecido; pero el mango estaba húmedo. Raskolnikoff ocultó cuidadosamente el arma bajo su gabán, colocándola en el nudo corredizo; después hizo una inspección minuciosa de sus vestidos con todo el cuidado que le permitía la débil luz que iluminaba la cocina. A primera vista el pantalón y el gabán no tenían nada de sospechoso; pero en los zapatos observó algunas manchas. El joven las limpió con un trapo humedecido en agua.\"},{\"heading\":false,\"text\":\"No obstante, estas precauciones no le tranquilizaban más que a medias, porque veía mal y comprendía que podían pasarse inadvertidas algunas manchas. Permaneció irresoluto en medio de la sala bajo la influencia de un pensamiento sombrío y angustioso: el pensamiento de que se volvía loco, de que en aquel momento era incapaz de tomar una determinación ni de velar por su seguridad y de que su manera de proceder no era la que convenía en las circunstancias presentes...\"},{\"heading\":false,\"text\":\"--¡Dios mío, debo irme; irme en seguida!--murmuró y se lanzó al recibimiento, en donde le esperaba un susto mayor de los que hasta entonces había experimentado. Se quedó inmóvil, no atreviéndose a dar crédito a sus ojos: la puerta del cuarto, la puerta exterior que daba al descansillo, la misma en que él había llamado hacía poco, por la cual había entrado, estaba abierta: hasta este momento había permanecido entreabierta: acaso por precaución, la vieja, ni había dado vuelta a la llave ni echado el cerrojo. ¡Pero Dios mío! el joven había visto en seguida a Isabel. ¿Cómo no se le ocurrió que la vendedora había entrado por la puerta? No había podido penetrar en el cuarto a través de la pared.\"},{\"heading\":false,\"text\":\"Cerró la puerta y echó el cerrojo.\"},{\"heading\":false,\"text\":\"--Pero no; no es eso lo que debo hacer. Es menester partir, huir inmediatamente.\"},{\"heading\":false,\"text\":\"Descorrió el cerrojo, y después de haber abierto la puerta, se puso a escuchar largo rato en la escalera. Abajo, probablemente en la puerta cochera, dos voces ruidosas se insultaban. Esperó pacientemente. Por último, callaron las voces; los dos alborotadores se habían ido cada cual por su lado. Iba ya el joven a salir cuando en el piso inferior se abrió con estrépito una puerta y alguien empezó a bajar tarareando una canción. ¿Qué les pasaba a esta gente para armar tanto ruido? Cerró de nuevo la puerta, esperando otra vez dentro del cuarto. Finalmente se restableció el silencio; pero en el instante en que Raskolnikoff se disponía a bajar, percibió un nuevo rumor.\"},{\"heading\":false,\"text\":\"Eran pasos todavía distantes, que resonaban en los primeros peldaños de la escalera; sin embargo, en cuanto empezó a oírlos, adivinó la verdad--: Vienen _aquí_, al cuarto piso, a casa de la vieja.\"},{\"heading\":false,\"text\":\"¿De dónde provenía aquel presentimiento? ¿Qué tenía de significativo el ruido de aquellos pasos? Eran pesados, regulares, y más bien lentos que ligeros...\"},{\"heading\":false,\"text\":\"--Ya _él_ ha llegado al primer piso... se le oye cada vez mejor... resuella como un asmático... ya llega al tercer piso... ¡aquí!\"},{\"heading\":false,\"text\":\"Y Raskolnikoff experimentó súbitamente una parálisis general, como ocurre en una pesadilla cuando uno se cree perseguido por varios enemigos: están a punto de alcanzaros, os van a matar y os quedáis como clavados en el suelo imposibilitados de moveros.\"},{\"heading\":false,\"text\":\"El desconocido comenzaba a subir el tramo del cuarto piso.\"},{\"heading\":false,\"text\":\"Raskolnikoff, a quien el espanto había tenido inmóvil en el descansillo, pudo, por último, sacudir su estupor y entrando apresuradamente en el cuarto cerró la puerta y corrió el cerrojo, teniendo cuidado de hacer el menor ruido posible. El instinto, más bien que el razonamiento, le guió en estas circunstancias.\"},{\"heading\":false,\"text\":\"Armóse después del hacha, se arrimó a la puerta y se puso a escuchar, sin atreverse a esperar siquiera. Ya el visitante estaba en el descansillo.\"},{\"heading\":false,\"text\":\"No había entre los dos hombres más que el espesor de una tabla. El desconocido se encontraba frente a frente de Raskolnikoff en la situación en que éste se había encontrado respecto de la vieja.\"},{\"heading\":false,\"text\":\"El visitante respiró varias veces con fatiga.\"},{\"heading\":false,\"text\":\"«Debe ser grueso y alto», pensó el joven, apretando con la mano el mango del hacha. Todo aquello parecía un sueño. Al cabo de un momento, el visitante dió un fuerte campanillazo. Creyó percibir cierto ruido en la sala. Durante algunos segundos escuchó atentamente; llamó después de nuevo, esperó todavía un poco, y de pronto, perdida la paciencia, se puso a sacudir la puerta con todas sus fuerzas. Raskolnikoff contemplaba con terror el cerrojo que temblaba en su ajuste; temía verlo saltar de un momento a otro. Pensó sujetar el cerrojo con la mano; pero el hombre hubiera podido desconfiar. La cabeza comenzaba a írsele de nuevo. «¡Estoy perdido!», se dijo; sin embargo, recobró súbitamente ánimos, cuando el desconocido rompió el silencio.\"},{\"heading\":false,\"text\":\"--¿Estarán durmiendo o las habrán estrangulado? ¡Malditas mujeres!--murmuraba en voz baja el visitante--. ¡Eh, Alena Ivanovna, vieja bruja! ¡Isabel Ivanovna, belleza indescriptible! ¡Abrid!\"},{\"heading\":false,\"text\":\"Exasperado, llamó diez veces seguidas todo lo más fuerte que pudo. Sin duda aquel hombre tenía confianza en la casa y dictaba en ella la ley.\"},{\"heading\":false,\"text\":\"Así pensaba Raskolnikoff cuando, de improviso, sonaron en la escalera pasos ligeros y rápidos. Era, sin duda, otro que subía al cuarto piso. El joven no se enteró al pronto de la llegada del recién venido.\"},{\"heading\":false,\"text\":\"--¿Es posible que no haya nadie?--dijo una voz sonora y alegre, dirigiéndose al primer visitante, que continuaba tirando de la campanilla--. ¡Buenas tardes, Koch!\"},{\"heading\":false,\"text\":\"Por el timbre de la voz comprendió Raskolnikoff que era un jovenzuelo.\"},{\"heading\":false,\"text\":\"--¡El demonio lo sabe; poco ha faltado para que haya saltado la cerradura!--respondió Koch--; ¿pero usted, cómo me conoce?\"},{\"heading\":false,\"text\":\"--¡Vaya una pregunta! ¿No le gané a usted anteayer en el café Gambrinus tres partidas seguidas de billar?\"},{\"heading\":false,\"text\":\"--¡Ah!\"},{\"heading\":false,\"text\":\"--¿De modo que no están? Es extraño, y además estúpido. ¿A dónde habrá ido la vieja? Tenía que hablarle.\"},{\"heading\":false,\"text\":\"--Yo también.\"},{\"heading\":false,\"text\":\"--¿De modo que no hay más remedio que marcharse? ¿Qué hacer? ¡Y yo que venía a pedirle dinero prestado!--exclamó el joven.\"},{\"heading\":false,\"text\":\"--En efecto; no hay más remedio que marcharse. Pero no comprendo por qué no está la bruja en casa habiéndome dado una cita. ¡Pues hay una buena caminata de aquí a mi casa! ¿Y a dónde demonios habrá ido? Esta bruja no se mueve en todo el año, puede decirse que echa raíces en su casa, tiene malas las piernas... ¡y de repente se va de parranda!\"},{\"heading\":false,\"text\":\"--Podíamos preguntarle al portero.\"},{\"heading\":false,\"text\":\"--¿Para qué?\"},{\"heading\":false,\"text\":\"--¡Toma! para saber a dónde ha ido y cuándo volverá.\"},{\"heading\":false,\"text\":\"--¡Hum... preguntar!... ¡pero si no sale nunca!--y tiró del cordón de la campanilla--. ¡Vaya, es inútil, hay que marcharse!\"},{\"heading\":false,\"text\":\"--¡Espere usted!--gritó de repente el joven--. Fíjese, vea usted cómo resiste la puerta cuando se tira de ella.\"},{\"heading\":false,\"text\":\"--¿Y qué?\"},{\"heading\":false,\"text\":\"--Esto prueba que no está cerrada con llave, sino con cerrojo. ¡Mire usted, mire usted cómo suena!\"},{\"heading\":false,\"text\":\"--¿Y qué?\"},{\"heading\":false,\"text\":\"--¿Pero no comprende usted todavía? Eso prueba que una, por lo menos, está en casa. Si las dos hubieran salido, habrían cerrado la puerta por fuera con llave, y claro es que no hubieran podido echar el cerrojo por dentro. Repare usted el ruido que hace. Es evidente que para pasar el cerrojo tiene que estar en casa. ¿Comprende usted? De modo, que están dentro y no quieren abrir.\"},{\"heading\":false,\"text\":\"--¡Pues es verdad!--exclamó Koch asombrado--. ¿De manera que están ahí?\"},{\"heading\":false,\"text\":\"Y se puso a sacudir furiosamente la puerta.\"},{\"heading\":false,\"text\":\"--No siga usted--dijo el joven--; aquí pasa algo extraordinario... Usted ha llamado... ha sacudido la puerta con todas sus fuerzas y ellas no abren; luego, o están desmayadas o..\"},{\"heading\":false,\"text\":\"--¿Qué?\"},{\"heading\":false,\"text\":\"--Hay que llamar al _dvornik_ para que las despierte.\"},{\"heading\":false,\"text\":\"--¡Buena idea!\"},{\"heading\":false,\"text\":\"Los dos empezaron a bajar.\"},{\"heading\":false,\"text\":\"--Espere usted, quédese aquí; iré yo a buscar al _dvornik_.\"},{\"heading\":false,\"text\":\"--¿Para qué me he de quedar?\"},{\"heading\":false,\"text\":\"--¡Oh! ¿Quién sabe lo que puede ocurrir?\"},{\"heading\":false,\"text\":\"--Está bien.\"},{\"heading\":false,\"text\":\"--Verá usted; yo me dispongo a ser juez de instrucción. Aquí hay algo que no está claro; esto es evidente, evidentísimo.\"},{\"heading\":false,\"text\":\"Y así diciendo el joven bajó de cuatro en cuatro los peldaños de la escalera.\"},{\"heading\":false,\"text\":\"Cuando se quedó solo, Koch llamó otra vez, pero suavemente; después se puso con aire distraído a empujar el botón de la cerradura para cerciorarse de que la puerta estaba cerrada nada más que con cerrojo. Luego, resoplando como un fuelle, se bajó para mirar por el ojo de la llave, pero ésta estaba puesta por dentro, de modo que no pudo ver nada.\"},{\"heading\":false,\"text\":\"En pie, del otro lado de la puerta, estaba Raskolnikoff con el hacha en la mano y dispuesto a deshacer el cráneo al primero que osara asomar la cabeza. Más de una vez, oyendo a los dos curiosos hurgar en la puerta y concertarse entre sí, estuvo a punto de acabar de una vez y de interpelarlos, pero sin abrir. Por momentos sentía deseos de injuriarlos, de insultarlos, de abrir la puerta para hacerles entrar y matarlos a ambos. «Mejor será que acabe cuanto antes»--pensaba.\"},{\"heading\":false,\"text\":\"--¡Qué diablo! ¡No sube nadie!--se dijo Koch, comenzando a perder la paciencia--. ¡Qué diablo!--volvió a decir, y fastidiado de esperar abandonó su puesto para bajar en busca del joven.\"},{\"heading\":false,\"text\":\"Poco a poco dejó de oírse el ruido de sus botas, que resonaban pesadamente en la escalera.\"},{\"heading\":false,\"text\":\"--¿Qué hacer, Dios mío, qué hacer?\"},{\"heading\":false,\"text\":\"Raskolnikoff descorrió el cerrojo y entreabrió la puerta. Tranquilizado por el silencio que reinaba en la casa, y, por otra parte, incapaz de reflexionar en aquel momento, salió, cerró detrás de sí lo mejor que pudo, y empezó a bajar la escalera.\"},{\"heading\":false,\"text\":\"Había descendido ya muchos escalones, cuando se produjo abajo un gran estrépito. ¿Dónde ocultarse? No había medio de esconderse en ninguna parte, y volvió a subir apresuradamente.\"},{\"heading\":false,\"text\":\"--¡Eh, pardiez, espera, aguarda!\"},{\"heading\":false,\"text\":\"El que lanzaba estas voces acababa de salir de un cuarto situado en los pisos inferiores y bajaba a saltos gritando:\"},{\"heading\":false,\"text\":\"--¡Mitka! ¡Mitka! ¡Mitka! ¡El demonio se lleve a ese loco!\"},{\"heading\":false,\"text\":\"La distancia no permitió oír más. El hombre que profería aquellas exclamaciones estaba ya lejos de la casa. El silencio se restableció; pero apenas había cesado esta alarma cuando le sucedió otra. Varios individuos que hablaban entre sí en voz alta subían tumultuosamente la escalera. Eran tres o cuatro. Raskolnikoff reconoció la voz chillona del joven estudiante.\"},{\"heading\":false,\"text\":\"--Son ellos--se dijo, y sin procurar ya escapar, se fué derechamente a su encuentro--. Ocurra lo que quiera--añadió. Si me detienen, todo ha terminado; y si me dejan escapar, también, porque se acordarán de haberme visto en la escalera.\"},{\"heading\":false,\"text\":\"Iba ya a reunirse con ellos, pues sólo les separaba un piso, cuando de repente vió la salvación. A pocos escalones delante de él, a la derecha, había un cuarto desalquilado, completamente abierto, el mismo donde trabajaban los pintores; pero, como si lo hubieran hecho adrede, éstos acababan de dejarlo.\"},{\"heading\":false,\"text\":\"Eran, sin duda, los que un momento antes habían salido vociferando. Se veía que la pintura estaba todavía fresca; en medio de la sala habían dejado los obreros sus útiles, una cubeta, un cacharro con color y una brocha. En un abrir y cerrar de ojos Raskolnikoff se escurrió en el cuarto desalquilado y se arrimó cuanto pudo a la pared. Ya era tiempo: sus perseguidores llegaban al descansillo; pero, sin detenerse, subieron al cuarto piso, hablando ruidosamente. Después de cerciorarse de que se habían alejado un poco, el asesino salió de puntillas y descendió precipitadamente. Nadie en la escalera, nadie en el patio. Atravesó rápidamente el umbral, y una vez en la calle dobló la esquina de la izquierda.\"},{\"heading\":false,\"text\":\"Comprendía perfectamente que los que le buscaban habían llegado en aquel momento a la puerta del cuarto de la vieja, quedándose estupefactos al verla abierta.\"},{\"heading\":false,\"text\":\"--Indudablemente están examinando los cadáveres--se decía--; sin duda les bastará un minuto para adivinar que el asesino ha logrado escapar; sospecharán, quizá, que se ha escondido en el cuarto desalquilado del segundo piso cuando ellos subían al de la usurera.\"},{\"heading\":false,\"text\":\"Pero, a pesar de hacerse estas reflexiones, no se atrevía a apresurar el paso, aunque estaba aún lejos de la primera esquina.\"},{\"heading\":false,\"text\":\"--¿Si me deslizara en un portal, en alguna calle extraviada y esperase allí un momento? No, malo. ¿Si fuese a arrojar el hacha a cualquier parte? ¿si tomara un coche? ¡Malo, malo!\"},{\"heading\":false,\"text\":\"Al cabo se ofreció ante sus ojos un _pereulok_ y se metió en él más muerto que vivo. Allí estaba casi en salvo; así lo comprendió. Era difícil que las sospechas recayeran sobre él. Por otra parte, era fácil no llamar la atención en medio de los paseantes; pero de tal manera aquellas angustias le habían debilitado, que apenas podía sostenerse en pie. Por la cara le corrían gruesas gotas de sudor y tenía empapado el cuello.\"},{\"heading\":false,\"text\":\"--¡Buena la has tomado!--le gritó, al desembocar el canal, uno que le creyó borracho.\"},{\"heading\":false,\"text\":\"No se daba cuenta de nada; cuanto más andaba, más se obscurecían sus ideas. No obstante, cuando llegó al muelle del Neva, se asustó de ver tan poca gente, y temiendo que reparasen en él en un lugar tan solitario, se volvió otra vez al _pereulok_; y aunque apenas tenía fuerzas para andar, dió un largo rodeo para volver a su domicilio.\"},{\"heading\":false,\"text\":\"Al franquear el umbral no había recobrado aún su presencia de espíritu; a lo menos, hasta que llegó a mitad de la escalera no se acordó de que llevaba todavía el hacha. La cuestión que tenía que resolver era muy grave: se trataba de dejar el hacha donde la había tomado, sin llamar en lo más mínimo la atención. Si hubiera estado más tranquilo habría comprendido, de seguro, que en vez de dejar el arma en su antiguo puesto, hubiera sido mucho mejor deshacerse de ella arrojándola en cualquier corral. Sin embargo, todo le resultó a maravilla: la puerta del _dvornik_ estaba cerrada, pero sin llave, lo cual hacía suponer que el portero no se había ausentado; pero Raskolnikoff, incapaz en aquel instante de discurrir ni de combinar un plan, se fué derecho a la puerta y la abrió. Si el portero le hubiese preguntado: «¿Qué quiere usted?», quizá el joven le habría entregado sencillamente el hacha; pero esta vez, como la anterior, el _dvornik_ había salido, lo que dió facilidad a Raskolnikoff para colocar el hacha debajo del banco, en el sitio donde la había encontrado. En seguida subió la escalera y llegó a su habitación sin tropezarse con nadie: la puerta del cuarto de la patrona estaba cerrada. Cuando entró en su aposento se echó vestido en el diván, y aunque no se durmió, quedó en estado inconsciente. Si hubiese entrado alguien en su habitación, habríase levantado bruscamente gritando despavorido. Mil ideas distintas le hormigueaban en el cerebro.\"},{\"heading\":false,\"text\":\"SEGUNDA PARTE\"}]},{\"title\":\"segunda parte — capítulo I\",\"blocks\":[{\"heading\":false,\"text\":\"Raskolnikoff estuvo mucho tiempo acostado. A veces salía de su somnolencia y observaba que la noche estaba muy avanzada; pero no se le ocurría la idea de levantarse. Luego notó que empezaba a amanecer. Echado boca arriba en el sofá, no había podido recobrarse de la especie de letargo en que se hallaba sumido. De pronto oyó gritos terribles y desesperados que sonaban en la calle: eran las mismas voces que daba todas las noches a las dos, bajo sus ventanas, la gente que salía de las tabernas.\"},{\"heading\":false,\"text\":\"Aquel ruido le despertó.\"},{\"heading\":false,\"text\":\"--¡Ah, son borrachos!--pensó--. Las dos--y sintió un brusco sobresalto, como si le hubiesen levantado con violencia del sofá--. ¡Cómo! ¡Las dos ya!--Se sentó en el diván y lo recordó todo.\"},{\"heading\":false,\"text\":\"En el primer momento creyó que se volvía loco. Sentía mucho frío, que procedía, sin duda, de la fiebre que le había asaltado durante el sueño. Ahora tiritaba de tal modo que le castañeteaban los dientes. Abrió la puerta y se puso a escuchar; todo dormía en la casa. Echó una mirada sobre su persona y en derredor suyo. ¿Cómo, el día antes, al entrar en su habitación, se le olvidó de cerrar la puerta con el pestillo? ¿Por qué se había echado en el sofá, no solamente sin desnudarse, sino hasta con el sombrero puesto? Este había rodado por el suelo. «Si alguno entrase aquí, qué pensaría? De seguro me creería borracho; pero...»\"},{\"heading\":false,\"text\":\"Se acercó a la ventana. Era ya día claro. El joven se examinó de pies a cabeza para ver si tenía alguna mancha en la ropa; pero no se podía fiar de una inspección hecha de aquel modo; siempre temblando, se desnudó y miró de nuevo su ropa con el mayor cuidado. Por exceso de precaución repitió este examen tres veces seguidas. No descubrió nada, excepto algunas gotas de sangre coagulada en la parte baja del pantalón, cuyos bordes estaban rotos y deshilachados. Tomó un cuchillo, y doblando los bordes de aquella prenda hizo dos tiras. De repente se acordó de que la bolsa y los objetos que había tomado del cofre de la vieja seguían en sus bolsillos. No había pensado en sacarlos ni en ocultarlos en cualquier parte. No se le ocurrió tampoco momentos antes cuando examinaba su ropa. «¡Si parece imposible!»\"},{\"heading\":false,\"text\":\"En un abrir y cerrar de ojos se vació los bolsillos y puso su contenido sobre la mesa. Después de haberlos registrado bien, a fin de asegurarse de que no quedaba nada en ellos, lo llevó todo a un rincón del cuarto. En aquel sitio, la tapicería destrozada se destacaba de la pared, y allí fué, bajo el papel, donde metió las alhajas y la bolsa.\"},{\"heading\":false,\"text\":\"--Así, ni visto ni conocido--pensó con alegría, medio incorporándose; y, mirando como atontado el ángulo en que la tapicería estaba desgarrada, bostezaba más aún.\"},{\"heading\":false,\"text\":\"De pronto, el terror agitó sus miembros.\"},{\"heading\":false,\"text\":\"--¡Dios mío!--murmuró con desesperación--. ¿Qué es lo que me pasa? ¿Está eso bien oculto? ¿Es así como se esconden estas cosas?\"},{\"heading\":false,\"text\":\"A la verdad, no era aquél el botín de que había esperado apoderarse; su intento era apropiarse del dinero de la vieja; así es que la necesidad de ocultar las alhajas le pillaba desprevenido.\"},{\"heading\":false,\"text\":\"--¿Pero ahora tengo yo motivos para alegrarme?--se decía--. ¿Es éste el modo de ocultar lo robado? Creo que me abandona la razón.\"},{\"heading\":false,\"text\":\"Falto de fuerzas, extenuado, se sentó en el diván, acometido de fuerte temblor.\"},{\"heading\":false,\"text\":\"Maquinalmente tomó un gabán viejo de invierno hecho jirones, que se encontraba en una silla, y se tapó con él; le invadió inmediatamente un sueño mezclado de delirio y perdió la conciencia de sí mismo.\"},{\"heading\":false,\"text\":\"Cinco minutos después se despertó sobresaltado, y su primer movimiento fué examinar de nuevo sus vestidos.\"},{\"heading\":false,\"text\":\"--¿Cómo he podido volver a dormirme sin haber hecho nada?; el nudo corredizo está en el sitio en que yo lo cosí. ¡Y no haber pensado en ello! ¡Semejante pieza de convicción!\"},{\"heading\":false,\"text\":\"Arrancó la venda de tela, la redujo a trozos pequeños y los confundió con la ropa que tenía debajo de la almohada.\"},{\"heading\":false,\"text\":\"--Me parece que estos trapos no pueden en caso ninguno despertar sospechas; por lo menos así lo creo--repetía en pie, en medio de la sala, con una atención que el esfuerzo hacía dolorosa, y miraba en derredor suyo para cerciorarse de que no había olvidado nada.\"},{\"heading\":false,\"text\":\"Le atormentaba cruelmente el convencimiento de que todo, la razón, hasta la más elemental prudencia, le abandonaba.\"},{\"heading\":false,\"text\":\"--¡Cómo! ¿Comienza ya el castigo? Sí, sí... así es, en efecto.\"},{\"heading\":false,\"text\":\"Los hilachos que había cortado del pantalón estaban en el suelo en medio de la sala, expuestos a la vista del primero que llegase.\"},{\"heading\":false,\"text\":\"--¿Pero dónde tengo yo la cabeza?--exclamó como anonadado.\"},{\"heading\":false,\"text\":\"Entonces le asaltó una idea extraña; pensó que su traje estaba todo ensangrentado, y que, a causa de la debilidad de sus facultades, no se había enterado de las manchas.\"},{\"heading\":false,\"text\":\"De repente se acordó de que la bolsa estaba también manchada de sangre.\"},{\"heading\":false,\"text\":\"Debe de haberse manchado el bolsillo, porque la bolsa estaba húmeda cuando la guardé.\"},{\"heading\":false,\"text\":\"En seguida dió la vuelta al bolsillo, y en efecto, encontró manchas en el forro.\"},{\"heading\":false,\"text\":\"--La razón no me ha abandonado por completo; soy capaz todavía de reflexionar, puesto que he podido hacer esta observación--pensó gozoso, lanzando un suspiro de satisfacción--; todo ello ha sido un instante de fiebre que me ha privado momentáneamente del juicio.\"},{\"heading\":false,\"text\":\"Arrancó inmediatamente todo el forro del bolsillo izquierdo del pantalón. En aquel momento un rayo de sol fué a dar en la punta de la bota izquierda: al joven le pareció que había allí indicios reveladores. Se descalzó.\"},{\"heading\":false,\"text\":\"--¡En efecto, son indicios! Toda la punta de la bota está llena de sangre. Sin duda puse imprudentemente el pie en aquel charco... ¿Pero qué hacer ahora de tales cosas? ¿Cómo deshacerme de esta bota, de estos trapajos y del forro del bolsillo?\"},{\"heading\":false,\"text\":\"Estaba en pie en medio de la sala, teniendo en la mano aquellos objetos que le denunciaban y le comprometían.\"},{\"heading\":false,\"text\":\"--Si los echase en la chimenea... Pero precisamente donde registrarán primero será en la chimenea. Si los quemase... ¿pero con qué? No tengo ni cerillas. Es mejor tirarlo todo en cualquier parte. Sí, lo mejor será tirarlo--repetía sentándose nuevamente en el diván--; pero en seguida, sin pérdida de tiempo.\"},{\"heading\":false,\"text\":\"Mas en vez de ejecutar esta resolución dejó caer la cabeza en las manos; empezó de nuevo el temblor, pero transido de frío se envolvió en su gabán de invierno. Durante muchas horas, esta misma idea estuvo presente en su espíritu: «Es preciso arrojar esto cuanto antes en cualquier parte». Varias veces se agitó bajo el gabán, quiso levantarse y no pudo conseguirlo. Al cabo de un rato, varios golpes violentos dados a la puerta le sacaron de su abstracción. Era Anastasia quien llamaba.\"},{\"heading\":false,\"text\":\"--¡Abre si no te has muerto!--gritó la criada--. ¡Se pasa la vida durmiendo, tendido como un perro! ¡Sí, como un perro! ¡Abreme, te digo; son ya las diez dadas!\"},{\"heading\":false,\"text\":\"--Puede que no esté--dijo una voz de hombre.\"},{\"heading\":false,\"text\":\"--Es la voz del _dvornik_...--se dijo Raskolnikoff, y temblando se sentó en el sofá.\"},{\"heading\":false,\"text\":\"Le latía el corazón hasta hacerle daño.\"},{\"heading\":false,\"text\":\"--¿Por qué habrá cerrado la puerta con el pestillo?--dijo Anastasia--. Se cree, sin duda, un bicho raro y teme acaso que alguien se lo lleve. Abre, despiértate...\"},{\"heading\":false,\"text\":\"--¿Qué querrán? ¿Por qué habrá subido el _dvornik_? Todo se ha descubierto. ¿Debo resistir o abrir desde luego? ¡Malditos sean!\"},{\"heading\":false,\"text\":\"Se medio incorporó, inclinóse hacia adelante y quitó el picaporte. La habitación era tan pequeña, que el joven podía abrir la puerta sin levantarse del sofá. Anastasia y el _dvornik_ aparecieron en el umbral. La criada contempló a Raskolnikoff con extrañeza. Por su parte el joven miró con audacia desesperada al portero, que silenciosamente le alargó un papel ceniciento plegado en dos partes y sellado con cera basta.\"},{\"heading\":false,\"text\":\"--Es una citación. Procede de la comisaría--dijo el _dvornik_.\"},{\"heading\":false,\"text\":\"--¿De qué comisaría?\"},{\"heading\":false,\"text\":\"--¡De cuál ha de ser! De la de policía.\"},{\"heading\":false,\"text\":\"--¿Se me llama ante la policía?... ¿Por qué?\"},{\"heading\":false,\"text\":\"--¿Cómo he de saberlo yo? Se le llama a usted, pues obedezca y punto en boca.\"},{\"heading\":false,\"text\":\"El portero examinó atentamente al inquilino, después miró en derredor suyo y se dispuso a retirarse.\"},{\"heading\":false,\"text\":\"--Parece que estás peor--observó Anastasia, que no separaba los ojos de Raskolnikoff.\"},{\"heading\":false,\"text\":\"El _dvornik_ volvió la cabeza.\"},{\"heading\":false,\"text\":\"--Desde ayer tiene fiebre--añadió la criada.\"},{\"heading\":false,\"text\":\"El joven no respondió, seguía con el pliego en la mano sin abrirlo.\"},{\"heading\":false,\"text\":\"--Quédate acostado--prosiguió la sirvienta compadecida de él al ver que se disponía a levantarse--. Estás enfermo, no vayas. No es cosa urgente. ¿Qué tienes en las manos?\"},{\"heading\":false,\"text\":\"El joven miró: tenía en la derecha las tiras del pantalón, la bota, y el forro de bolsillo. Se había dormido con aquellos objetos. Más tarde, tratando de explicarse el hecho, se acordó de que medio despierto, en un acceso febril, apretó fuertemente todo aquello contra su pecho quedándose luego dormido sin aflojar los dedos.\"},{\"heading\":false,\"text\":\"--¡Ha tomado esos andrajos y se duerme con ellos como si fueran un tesoro!...\"},{\"heading\":false,\"text\":\"Al decir estas palabras, Anastasia se retorcía con la risa nerviosa que le era habitual.\"},{\"heading\":false,\"text\":\"Raskolnikoff ocultó rápidamente bajo su abrigo todo lo que tenía en las manos y fijó una penetrante mirada en la criada. Aunque no se encontraba en estado de reflexionar, comprendía que no se busca así a un hombre cuando se intenta prenderle. «¿Pero la policía?»\"},{\"heading\":false,\"text\":\"--¿Tomarás te?, ¿quieres que te lo traiga? Queda algo...\"},{\"heading\":false,\"text\":\"--No, voy allá, voy en seguida--balbuceó.\"},{\"heading\":false,\"text\":\"--¿Pero podrás bajar la escalera?\"},{\"heading\":false,\"text\":\"--Quiero ir.\"},{\"heading\":false,\"text\":\"--Allá tú.\"},{\"heading\":false,\"text\":\"Anastasia salió detrás del _dvornik_. Raskolnikoff se puso en seguida a examinar a la luz la bota y las tiras. «Hay manchas, pero no son muy visibles; el barro y el roce han hecho desaparecer el color. El que no sospeche no advertirá nada; por consiguiente, Anastasia, desde el sitio donde estaba, no ha podido notar nada, ¡gracias a Dios!»\"},{\"heading\":false,\"text\":\"Después, con mano temblorosa, abrió el pliego y comenzó a leer; pero tuvo que leerlo varias veces antes de darse cuenta del contenido. Era una citación redactada en la forma ordinaria. El comisario de policía del distrito invitaba a Raskolnikoff a presentarse en su oficina a las nueve y media de aquel mismo día.\"},{\"heading\":false,\"text\":\"--¿Para qué se me cita? Yo no tengo que ver nada con la policía... ¡Y hoy precisamente!--se dijo, presa de la más viva ansiedad--. ¡Señor, haced que esto acabe lo más pronto posible!\"},{\"heading\":false,\"text\":\"En el momento en que iba a arrodillarse para rezar, se echó a reír, no de la oración, sino de sí mismo, y empezó a vestirse rápidamente.\"},{\"heading\":false,\"text\":\"--Voy yo mismo a meterme en la boca del lobo... Pues bien, tanto peor, me es igual... me pondré esta bota... La verdad es que, gracias al polvo de la calle, se advertirán menos las manchas.\"},{\"heading\":false,\"text\":\"Pero apenas se la hubo calzado se la quitó de repente con temor y disgusto. Después reflexionó que no tenía otra y se la volvió a poner riéndose otra vez.\"},{\"heading\":false,\"text\":\"--Todo esto es circunstancial, todo relativo; lo único que puede haber son conjeturas, suposiciones y nada más.\"},{\"heading\":false,\"text\":\"Esta idea, a la cual se aferraba con convicción, no le impedía temblar.\"},{\"heading\":false,\"text\":\"--¡Vamos! Ya estoy calzado; he acabado por hacerlo.\"},{\"heading\":false,\"text\":\"Al abatimiento siga la hilaridad.\"},{\"heading\":false,\"text\":\"--No, esto es superior a mis fuerzas... las piernas se me doblan... ¡Esto es miedo!\"},{\"heading\":false,\"text\":\"Le dolía la cabeza a causa del calor.\"},{\"heading\":false,\"text\":\"--Es un lazo que se me tiende, lo sé. Se valen de la astucia para atraerme, y cuando esté allí descubrirán de repente sus baterías--continuaba diciéndose al tiempo que se aproximaba a la escalera--. Lo peor es que estoy como loco y puedo cometer alguna tontería.\"},{\"heading\":false,\"text\":\"Ya en la escalera pensó que los objetos robados en casa de la usurera estaban mal ocultos en el sitio que los había puesto.\"},{\"heading\":false,\"text\":\"--Quizá me llamen con objeto de hacer un registro durante mi ausencia.\"},{\"heading\":false,\"text\":\"Pero tan desesperado estaba, aceptaba su perdición, por decir así, con tal cinismo, que esta preocupación le detuvo apenas un minuto.\"},{\"heading\":false,\"text\":\"--¡Con tal de que se acabe pronto!\"},{\"heading\":false,\"text\":\"Al llegar a la esquina de la calle que había doblado la víspera, dirigió furtivamente una mirada inquieta a _la casa_; pero al punto volvió la vista.\"},{\"heading\":false,\"text\":\"--Si me interrogan quizá confiese--pensaba al aproximarse a la oficina.\"},{\"heading\":false,\"text\":\"Desde poco tiempo antes, estaba instalada la comisaría en el cuarto piso de una casa situada a corta distancia de la de Raskolnikoff. Antes de que la policía se hubiese trasladado a este nuevo local, el joven había sido llamado por ella; pero entonces se trataba de una cosa sin importancia, y de esto había transcurrido ya mucho tiempo. Al entrar en el patio vió a un _mujick_ con un libro en la mano, que bajaba una escalera situada a la derecha.\"},{\"heading\":false,\"text\":\"--Debe de ser un _dvornik_; por consiguiente, es aquí donde se encuentra la oficina.\"},{\"heading\":false,\"text\":\"Subió al azar; no quería preguntar a nadie.\"},{\"heading\":false,\"text\":\"--Entraré, me pondré de rodillas y lo confesaré todo--pensaba mientras subía al cuarto piso.\"},{\"heading\":false,\"text\":\"La escalera era estrecha, empinada y rezumaba por todas partes agua sucia. En los cuatro pisos las cocinas de todos los cuartos daban a la escalera y estaban abiertas de par en par casi todo el día, lo cual hacía que el calor fuera sofocante. Subían y bajaban los _dvorniks_ con sus cuadernos debajo del brazo, varios agentes de policía e individuos de uno u otro sexo, que sin duda tenían asuntos en la oficina. La puerta de la comisaría estaba también abierta de par en par.\"},{\"heading\":false,\"text\":\"Raskolnikoff entró y se detuvo en la antesala donde esperaban algunos _mujicks_. Allí, como en la escalera, el calor era asfixiante. Además, el local, recientemente pintado, exhalaba un olor a aceite de linaza que daba náuseas. Después de una corta espera decidióse a entrar en el departamento contiguo, compuesto de una serie de habitaciones pequeñas y bajas. El joven estaba cada vez más impaciente por saber a qué atenerse. Nadie hacía caso de él. En la segunda habitación trabajaban varios escribientes, vestidos poco más o menos como él estaba. Todos tenían extraño aspecto. Raskolnikoff se dirigió a uno de ellos.\"},{\"heading\":false,\"text\":\"--¿Qué se le ofrece?\"},{\"heading\":false,\"text\":\"El joven mostró la citación enviada por la comisaría.\"},{\"heading\":false,\"text\":\"--¿Es usted estudiante?--preguntó el escribiente después de haber ojeado el papel.\"},{\"heading\":false,\"text\":\"--Sí, antiguo estudiante.\"},{\"heading\":false,\"text\":\"El empleado examinó a su interlocutor sin ninguna curiosidad. Era un hombre de cabellos rizados que parecía dominado por una idea fija.\"},{\"heading\":false,\"text\":\"--De éste nada he de saber, porque todo le es igual--pensó Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Diríjase usted al jefe de la Cancillería--añadió el escribiente señalando con la mano la última dependencia.\"},{\"heading\":false,\"text\":\"Raskolnikoff entró en ella. Aquel despacho, el cuarto, era estrecho y estaba lleno de gente que vestía algo mejor que las otras personas que acababa de ver. Entre ellas había dos señoras. Una, vestida de luto, denotaba pobreza. Sentada delante del jefe de la Cancillería escribía lo que este funcionario le dictaba.\"},{\"heading\":false,\"text\":\"La otra señora tenía formas exuberantes, la cara roja, un tocado elegante y llevaba en el pecho un broche de dimensiones extraordinarias. Permanecía en pie, un poco separada, en actitud expectante.\"},{\"heading\":false,\"text\":\"Raskolnikoff entregó el papel al jefe de la Cancillería, el cual echó sobre él una rápida ojeada y dijo:\"},{\"heading\":false,\"text\":\"--Espere usted un poco--y siguió dictando a la señora de luto.\"},{\"heading\":false,\"text\":\"El joven respiró con más libertad.\"},{\"heading\":false,\"text\":\"--Indudablemente no se me llama para _aquello_. Poco a poco recobraba valor; por lo menos hacía todo lo posible para recobrarlo.\"},{\"heading\":false,\"text\":\"--La menor tontería, la más pequeña imprudencia, puede perderme... es un mal que no haya aire aquí--añadió--; se ahoga uno y mi razón vacila...\"},{\"heading\":false,\"text\":\"Sentía un malestar indefinible en todo su ser, y temía que le faltara la serenidad en presencia de aquel funcionario. Trataba de buscar algún objeto en que fijar su atención, pero no podía conseguirlo. Toda su atención estaba concentrada en el jefe de la Cancillería; hacía esfuerzos para descifrar la fisonomía de este empleado. Era un joven de veintidós años, cuyo rostro, moreno y móvil, representaba más edad; vestía con la elegancia peculiar del lechuguino y llevaba el pelo partido con una raya artísticamente hecha. Ostentaba en las manos, muy cuidadas, muchas sortijas y le serpenteaba por el chaleco una cadena de oro. Dijo a un extranjero que se encontraba allí dos palabrejas en francés y se quedó tan satisfecho.\"},{\"heading\":false,\"text\":\"--Tome usted asiento, Luisa Ivanovna--dijo a la señora lujosa, que permanecía en pie, sin atreverse a sentarse, aunque tenía una silla al lado.\"},{\"heading\":false,\"text\":\"--_Itch danke_--respondió la señora sentándose y ahuecando con un ligero roce sus faldas impregnadas de perfume.\"},{\"heading\":false,\"text\":\"Desplegado en derredor de la silla su traje de seda azul claro, guarnecido de encajes blancos, ocupaba más de la mitad del despacho; pero a la señora parecía que le daba vergüenza oler tan bien y ocupar tanto sitio. Sonreía de una manera a la vez temblorosa y descarada; sin embargo, era visible su inquietud. Una vez terminado su asunto, la señora de luto se levantó. En aquel momento entró haciendo ruido un oficial de modales muy desenvueltos, que puso sobre la mesa su gorra galoneada y se sentó en una butaca.\"},{\"heading\":false,\"text\":\"Al verle, la señora lujosamente vestida se levantó con prontitud e inclinóse con mucho respeto ante el oficial, pero éste no hizo el menor caso de ella y la mujer no se atrevió a volver a sentarse.\"},{\"heading\":false,\"text\":\"Era este personaje el ayudante del comisario de policía; tenía largos bigotes rojizos y retorcidos y facciones extremadamente finas, pero no expresivas y que denotaban cierta impudencia. Miró a Raskolnikoff de reojo y con algo de indignación; porque aunque era muy modesto el aspecto de nuestro héroe, su actitud contrastaba con la pobreza de su traje. Olvidando toda prudencia, el joven sostuvo tan atrevidamente la mirada del oficial, que éste se ofendió.\"},{\"heading\":false,\"text\":\"--¿Qué se te ofrece?--dijo, asombrado, sin duda, al ver que semejante desharrapado no bajaba los ojos ante su centelleante mirada.\"},{\"heading\":false,\"text\":\"--Se me ha hecho venir... He sido citado--balbució Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Es el estudiante a quien se le reclama el pago de una deuda--se apresuró a decir el jefe de la Cancillería, dejando por un momento sus papelotes--. Entérese usted--y presentó un cuaderno a Raskolnikoff señalándole una parte de lo escrito--. Lea usted.\"},{\"heading\":false,\"text\":\"--¿Dinero? ¿Qué dinero?--pensó el joven sorprendido y alegre al mismo tiempo--. ¿De modo que no es por aquello por lo que me han hecho venir aquí?\"},{\"heading\":false,\"text\":\"Experimentaba un alivio inmenso, inexpresable...\"},{\"heading\":false,\"text\":\"--¿A qué hora, señor mío, se le ha mandado a usted venir?--le preguntó el ayudante, cuyo mal humor iba en aumento--. Se le cita a usted a las nueve y son más de las once.\"},{\"heading\":false,\"text\":\"--Me han entregado ese papel hace un cuarto de hora--replicó vivamente Raskolnikoff, invadido también de repentina cólera, a la cual se abandonaba con placer--; estoy enfermo, tengo fiebre, y sin embargo, aquí me tienen ustedes.\"},{\"heading\":false,\"text\":\"--¡No grite usted!\"},{\"heading\":false,\"text\":\"--No grito, hablo con naturalidad; usted es quien levanta la voz. Soy estudiante y no permito que se me hable de este modo.\"},{\"heading\":false,\"text\":\"Esta respuesta irritó de tal manera al oficial, que en el primer momento no pudo articular ni una sola frase, dejando en cambio escapar de sus labios sonidos inarticulados. De repente dió un salto en su asiento y dijo:\"},{\"heading\":false,\"text\":\"--¡Cállese usted! ¡Está usted en la sala de audiencia! ¡no sea usted insolente!\"},{\"heading\":false,\"text\":\"--También lo está usted--replicó Raskolnikoff con violencia--, y no contento con gritar, está usted fumando; por consiguiente, nos falta usted a todos al respeto.\"},{\"heading\":false,\"text\":\"Pronunció estas palabras con indecible satisfacción.\"},{\"heading\":false,\"text\":\"El jefe de la Cancillería miraba sonriendo a los dos interlocutores. El fogoso ayudante se quedó con la boca abierta.\"},{\"heading\":false,\"text\":\"--Eso no le importa a usted--respondió levantando aún más la voz a fin de ocultar su cortedad--; preste la declaración que se le pide. Dígaselo usted, Alejandro Grigorievitch. Hay queja contra usted, porque no paga sus deudas. ¡He aquí un viejo zorro!\"},{\"heading\":false,\"text\":\"Raskolnikoff no le escuchaba; había tomado vivamente el papel, impaciente para descubrir la clave de este enigma. Lo leyó, una, dos veces, sin comprender nada.\"},{\"heading\":false,\"text\":\"--¿Qué es esto?--preguntó al jefe de la Cancillería.\"},{\"heading\":false,\"text\":\"--Es un documento en que se le reclama el pago de una deuda: tiene usted que saldarlo con todas las costas, o declarar por escrito en qué fecha podrá usted pagar. Es preciso, al mismo tiempo, que se comprometa usted a no abandonar la capital y a no vender ni ocultar lo que usted posea, hasta que haya liquidado su deuda. En cuanto al acreedor, es libre de vender los bienes de usted y tratarle según el rigor de las leyes.\"},{\"heading\":false,\"text\":\"--¡Si no debo nada a nadie!\"},{\"heading\":false,\"text\":\"--Eso no es cuenta nuestra. Se nos presenta una letra de cambio, protestada, de ciento quince rublos, que usted firmó hace nueve meses a la señora Zarnitzin, viuda de un asesor de colegio, letra que la viuda Zarnitzin ha traspasado al consejero Tchebaroff, y hemos llamado a usted para tomarle declaración.\"},{\"heading\":false,\"text\":\"--Pero desde el momento que se trata de mi patrona...\"},{\"heading\":false,\"text\":\"--¿Qué importa que sea la patrona de usted?\"},{\"heading\":false,\"text\":\"El jefe de la Cancillería contemplaba con cierta sonrisa de indulgente piedad, y al mismo tiempo de triunfo, a aquel novato que iba a aprender a sus expensas el procedimiento que suele emplearse con los deudores. ¿Pero qué le importa ahora a Raskolnikoff la letra de cambio? La reclamación de su patrona le tenía sin cuidado. ¿Valía aquello la pena de inquietarse ni de fijar siquiera la atención en semejantes futesas? Estaba allí leyendo, escuchando, respondiendo algunas veces, pero todo ello lo hacía maquinalmente. La felicidad de sentirse a salvo, la satisfacción de haber escapado a un peligro inminente, llenaba en aquel momento todo su ser.\"},{\"heading\":false,\"text\":\"En aquel instante habíanse desvanecido todas sus preocupaciones y cuidados; fué para Raskolnikoff un momento de alegría absoluta, inmediata, puramente instintiva.\"},{\"heading\":false,\"text\":\"De improviso estalló una tempestad en el despacho de la comisaría. El ayudante, que no había podido digerir aún la afrenta hecha a su prestigio y a su amor propio, buscaba evidentemente el desquite; así es que se puso a apostrofar rudamente a la lujosa señora que, desde la entrada del oficial, no cesaba de mirarle, sonriendo con estúpida sonrisa.\"},{\"heading\":false,\"text\":\"--Y di tú, bribona--gritó el ayudante (la señora de luto se había retirado ya)--, ¿qué es lo que ha sucedido en tu casa la noche pasada? ¡Otra vez escandalizando al barrio! ¡Siempre riñas y borracheras! ¡Estás empeñada en dar con tus huesos en la cárcel! Te he advertido ya diez veces, y a la undécima va la vencida. ¡Eres incorregible y se me agota la paciencia!\"},{\"heading\":false,\"text\":\"El mismo Raskolnikoff dejó caer el papel que tenía en las manos y miró con asombro a la elegante señora que era tratada con tan poca consideración. No tardó, empero, en comprender de lo que se trataba, y prestó atención a aquella escena que le divertía hasta el punto que tenía que hacer sobrehumanos esfuerzos para no soltar el trapo a reír.\"},{\"heading\":false,\"text\":\"--Ilia Petrovitch--comenzó a decir el jefe de la Cancillería; pero comprendiendo en seguida que su intervención en aquel momento sería inoportuna, se detuvo.\"},{\"heading\":false,\"text\":\"Sabía por experiencia que cuando el fogoso oficial se disparaba nada podía contenerlo.\"},{\"heading\":false,\"text\":\"En cuanto a la señora, la tempestad que se había desencadenado sobre su cabeza le hizo temblar en el primer momento; pero, cosa extraña, a medida que aumentaban los insultos a ella dirigidos, tomaba una expresión más amable y ponía más seducción en las sonrisas y en las miradas en que envolvía al terrible ayudante. Hacía continuas reverencias y esperaba que se la dejase hablar.\"},{\"heading\":false,\"text\":\"--En mi casa no hay escándalos ni riñas, ni borracheras, señor capitán--se apresuró a decir en cuanto le permitieron meter baza (se expresaba en ruso pero con marcado acento alemán)--. No, señor, no hubo ningún escándalo. Aquel hombre entró en mi casa ebrio, pidió tres botellas y en seguida se puso a tocar el piano con los pies, cosa que, como usted comprende, no se había de permitir en una casa como la mía. No contento con esto, rompió las cuerdas. Le hice observar que no era aquel el modo conveniente de conducirse; pero él, sin hacer caso, tomó una botella y comenzó a pegar a todos. Llamé a Carlos, el _dvornick_, y pegó a Carlos una bofetada; lo mismo hizo con Enriqueta, y tampoco yo escapé a sus bofetones. Es innoble portarse de esa manera en una casa respetable, señor capitán. Pido socorro, y el hombre se acerca a la ventana que da al canal y se pone a gritar como un loco. ¿No es eso vergonzoso? ¿Le parece a usted que está bien asomarse a la ventana y ponerse a imitar el gruñido del cerdo? Carlos tiró de él por detrás para quitarle de la ventana, y a fuerza de tirar, es verdad, le desgarró el gabán, y ahora reclama quince rublos en indemnización del daño causado a su ropa. Le entregué de mi propio bolsillo cinco rublos, señor capitán. Ese visitante mal educado, señor capitán, es el que ha armado todo el escándalo.\"},{\"heading\":false,\"text\":\"--¡Ea, basta! Te tengo dicho y vuelvo a repetir...\"},{\"heading\":false,\"text\":\"--¡Ilia Petrovitch!--volvió a decir en tono significativo el jefe de la Cancillería.\"},{\"heading\":false,\"text\":\"El oficial echó sobre él una rápida mirada y le vió mover ligeramente la cabeza.\"},{\"heading\":false,\"text\":\"--Pues bien, en lo que a ti se refiere, escucha mi última palabra, respetable Luisa Ivanovna: si en lo sucesivo vuelve a armarse otro escándalo en tu respetable casa, te meto en chirona, como se dice en estilo elevado. ¿Me entiendes? Ahora, lárgate cuanto antes, y no olvides que te tengo echada la vista. ¡Mucho ojo!\"},{\"heading\":false,\"text\":\"Con exagerada amabilidad, Luisa Ivanovna saludó a un lado y otro; pero en tanto que se dirigía a la puerta andando hacia atrás haciendo reverencias, dió un golpe con la espalda a un apuesto oficial de rostro fresco y abierto y de magníficas patillas rubias muy espesas y bien cuidadas. Era el comisario de policía Nikodim Fomitch en persona. Luisa Ivanovna se apresuró a inclinarse hasta el suelo y salió del despacho dando saltitos.\"},{\"heading\":false,\"text\":\"--¡Siempre el trueno, la tempestad, el rayo, los relámpagos, la tromba, el huracán!--dijo, en tono amistoso, el recién llegado, dirigiéndose a su ayudante--. Se te ha alborotado la bilis y, como de costumbre, te has disparado. Te he oído desde la escalera.\"},{\"heading\":false,\"text\":\"--¿Y quién no se sulfura con lo que pasa?--repuso negligentemente Ilia Petrovitch, trasladándose con sus papeles a otra mesa--. Ese caballerito, ese estudiante, o, mejor dicho, ex estudiante, que no paga sus deudas, que firma letras de cambio y rehusa dejar su habitación, es citado ante el comisario y se escandaliza porque enciendo un cigarro en su presencia. Antes de advertir que se le falta al respeto, debería respetarse más a sí mismo. Ahí le tiene usted, mírele. A la vista está. ¿Le parece a usted que su aspecto puede inspirar consideración alguna?\"},{\"heading\":false,\"text\":\"--Pobreza no es vicio, amigo mío--replicó Nikodim Fomitch--. Sabemos perfectamente que la pólvora se inflama con facilidad. Sin duda le habrá chocado a usted algo de su manera de ser y usted tampoco ha podido contenerse--prosiguió, volviéndose hacia Raskolnikoff--; pero se ha equivocado usted: el señor oficial es un hombre excelente, se lo aseguro; tiene un carácter arrebatado, se excita, se exalta, pero en cuanto se le pasa el mal humor es un corazón de oro. En el regimiento le llamábamos «el oficial pólvora...»\"},{\"heading\":false,\"text\":\"--¡Qué regimiento aquél!--exclamó Ilia Fomitch lisonjeado por las delicadas adulaciones de su superior, pero todavía enfurruñado.\"},{\"heading\":false,\"text\":\"Raskolnikoff quiso súbitamente decir algo muy agradable para todos.\"},{\"heading\":false,\"text\":\"--Perdóneme usted, capitán--comenzó a decir en tono melifluo, dirigiéndose a Nikodim Fomitch--. Póngase usted en mi lugar. Estoy pronto a darle mis excusas a este señor, si es que por mi parte he cometido alguna falta. Soy un estudiante enfermo, pobre, agobiado por la miseria; he tenido que dejar la Universidad, porque carezco de medios de subsistencia, pero voy a recibir dinero... Mi madre y mi hermana viven en la provincia de***. Me envían fondos, y pagaré. Mi patrona es una buena mujer; pero como desde hace cuatro meses no doy lecciones, no le pago y se incomoda y hasta rehusa darme de comer. La verdad es que no comprendo... Ahora exige que yo le pague esa letra de cambio; ¿pero cómo podré hacerlo? Juzgue usted por sí mismo.\"},{\"heading\":false,\"text\":\"--Eso no es de mi incumbencia--observó de nuevo el jefe de la Cancillería.\"},{\"heading\":false,\"text\":\"--Es verdad; pero permítanme ustedes que les explique--...replicó Raskolnikoff, dirigiéndose siempre a Nikodim Fomitch y no a su interruptor, procurando atraer también la atención de Ilia Petrovitch, aunque éste afectase desdeñosamente no escucharle, como si estuviera absorto en sus papeles--. Permítanme ustedes que les diga que vivo en casa de esa mujer desde que vine de mi país, y que entonces... ¿por qué no he de decirlo?... me comprometí a casarme con su hija; hice mi promesa verbalmente... Era una muchacha joven, me gustaba, aunque no estuviese enamorado de ella... En una palabra: soy joven, mi patrona me abrió crédito... Hice una vida... Vamos, he sido algo ligero.\"},{\"heading\":false,\"text\":\"--No se le pide a usted que entre en esos pormenores íntimos, que no tenemos tiempo de escuchar--interrumpió groseramente Ilia Petrovitch; pero Raskolnikoff prosiguió con calor, aunque le costaba mucho trabajo hablar.\"},{\"heading\":false,\"text\":\"--Permítanme ustedes, sin embargo, que les cuente cómo han pasado las cosas, aunque comprenda que es completamente inútil que lo refiera a ustedes. Hace un año, la señorita de que he hablado, murió del tifus; yo seguía a pupilo en casa de la señora Zarnitzin, y cuando mi patrona se trasladó a la casa en que hoy vive, me dijo amistosamente que tenía confianza en mí; pero que, sin embargo, deseaba que le firmase un pagaré de ciento quince rublos, cantidad en que calculaba el importe de mi deuda. Me aseguró que, una vez en posesión de ese documento, continuaría concediéndome tanto crédito como me fuese necesario, y que jamás, jamás (tales fueron sus propias palabras), sacaría a relucir ese documento. ¡Y ahora que he perdido mis lecciones, ahora que no tengo un pedazo de pan que llevarme a la boca, me exige el pago de esa suma! ¿Qué les parece a ustedes?\"},{\"heading\":false,\"text\":\"--Todos esos pormenores patéticos no nos interesan--replicó con insolencia Ilia Petrovitch--. Tiene usted que prestar la declaración y firmar el compromiso que se le pide. En cuanto a la historia de sus amores y a todos esos trágicos lugares comunes, nada tenemos que ver con ellos.\"},{\"heading\":false,\"text\":\"--¡Oh, qué cruel eres!--murmuró Nikodim Fomitch, que se había sentado delante de su escritorio y se ocupaba en firmar papelotes. Parecía avergonzado.\"},{\"heading\":false,\"text\":\"--Escriba usted--dijo a Raskolnikoff el jefe de la Cancillería.\"},{\"heading\":false,\"text\":\"--¿Qué es lo que tengo que escribir?--preguntó el joven brutalmente.\"},{\"heading\":false,\"text\":\"--Lo que yo le dicte.\"},{\"heading\":false,\"text\":\"Raskolnikoff creyó advertir, que, después de su confesión, el jefe de la Cancillería le trataba con mayor desprecio; pero, ¡cosa extraña! se sentía indiferente a la opinión que podía tenerse de él, cambio que se había apoderado en su espíritu instantáneamente.\"},{\"heading\":false,\"text\":\"Si hubiese podido reflexionar un poco, habríase asombrado de que un minuto antes hubiera podido hablar de aquel modo con los funcionarios de policía y aun obligarles a oír sus confidencias. Ahora, por el contrario, si en lugar de estar lleno de agentes el despacho se hubiese ocupado de repente con sus más queridos amigos, no habría encontrado probablemente una sola palabra cortés que decirles; de tal manera se había vaciado su corazón.\"},{\"heading\":false,\"text\":\"Experimentaba la dolorosa impresión de un inmenso aislamiento; no era la confusión de haber hecho a Ilia Petrovitch testigo de sus expansiones, ni tampoco era la insolencia del oficial lo que había producido tal revolución en su alma. ¡Oh! ¿Qué le importaba su propia bajeza? ¿Qué le importaban las altanerías de los oficiales, los pagarés, los despachos de policía, etc., etc.? Si en aquel momento lo hubiesen condenado a ser quemado vivo, ni siquiera hubiese pestañeado. Apenas habría oído su sentencia hasta el fin.\"},{\"heading\":false,\"text\":\"Se realizaba en él un fenómeno completamente nuevo, sin precedentes hasta entonces. Comprendía, o más bien, cosa cien veces peor, sentía que en lo sucesivo estaría separado para siempre de la comunión humana, que toda expansión sentimental como la que había tenido un momento antes, más todavía, que toda la conversación le estaba prohibida, no sólo con los empleados de la comisaría, sino hasta con los parientes más próximos. Jamás había experimentado sensación tan cruel.\"},{\"heading\":false,\"text\":\"El jefe de la Cancillería comenzó a dictarle la fórmula de la declaración acostumbrada en tales casos: «No puedo pagar, liquidaré mi deuda en tal fecha, no saldré de la ciudad, ni haré cesión de lo que poseo, etc.»\"},{\"heading\":false,\"text\":\"--No puede usted escribir, le tiembla la mano--dijo el jefe de la Cancillería mirando con curiosidad a Raskolnikoff--. ¿Está usted enfermo?\"},{\"heading\":false,\"text\":\"--Sí; se me va la cabeza. Siga usted.\"},{\"heading\":false,\"text\":\"--Ya está todo; firme usted.\"},{\"heading\":false,\"text\":\"El jefe de la Cancillería tomó el papel y se dirigió a otros visitantes.\"},{\"heading\":false,\"text\":\"Raskolnikoff dejó la pluma, pero en lugar de irse se puso de codos en la mesa y apoyó la cabeza en las manos. Parecíale que le hincaban un clavo en el cerebro. En aquel momento recordó los dos asesinatos que había cometido y se le ocurrió la extraña idea de acercarse a Nikodim Fomitch, y contarle el crimen hasta en sus ínfimos detalles y llevarle en seguida a su casa y mostrarle los objetos ocultos en el agujero de la tapicería. De tal modo se apoderó esta idea de su espíritu, que hasta llegó a levantarse para ponerlo en práctica.\"},{\"heading\":false,\"text\":\"--¿No sería mejor reflexionar un instante?--pensó--. No, más vale dejarse llevar de la inspiración, sacudir lo más pronto posible esta carga.\"},{\"heading\":false,\"text\":\"Pero, de repente, se quedó como clavado en su sitio: entre Nikodim Fomitch e Ilia Petrovitch, se acababa de entablar una conversación animada que llegaba hasta los oídos de Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¡No es posible! soltarán a los dos por falta de pruebas. Si hubiesen cometido ellos el delito, ¿habrían llamado al _dvornick_ para denunciarse a sí mismos? ¿Se puede considerar esto como un ardid? No, eso hubiera sido demasiada astucia. Además, los dos _dvorniks_ y una vecina vieron al estudiante Pestriakoff cerca de la puerta cochera en el momento en que éste iba a entrar en la casa. Le acompañaban tres amigos que le dejaron en la puerta, y éstos, antes de alejarse le oyeron preguntar a los _dvorniks_ dónde vivía la vieja. ¿Hubiera hecho tal pregunta de haber ido con el propósito de cometer un doble asesinato? Kosch, por su parte, estuvo durante media hora en casa del platero del piso bajo antes de subir a casa de la pobre vieja Alena Ivanovna; eran justamente las ocho menos cuarto cuando subió a las habitaciones de las víctimas. Además, se ha de tener en cuenta...\"},{\"heading\":false,\"text\":\"--Perdone usted; hay en sus declaraciones algo que no se explica. Afirman que llamaron y que la puerta estaba cerrada; tres minutos después, cuando volvieron con el _dvornik_, estaba abierta.\"},{\"heading\":false,\"text\":\"--Ahí está el _busilis_; es indudable que el asesino se encontraba en el cuarto de la vieja cuando ellos llegaron; y que había echado el cerrojo: de seguro que no se habría escapado a no cometer Kosch la simpleza de bajar en busca del _dvornik_. Sin duda el asesino aprovechó ese momento para deslizarse por la escalera dejándolos con un palmo de narices. Kosch no cesa de santiguarse diciendo: «¡Si llego a quedarme allí, de fijo sale de repente el criminal y me mata de un hachazo!» Quiere mandar que canten un _Te Deum_. ¡Je, je, je!\"},{\"heading\":false,\"text\":\"--¿Y nadie vió al asesino?\"},{\"heading\":false,\"text\":\"--¿Cómo habían de verle si aquella casa es el arca de Noé?--dijo el jefe de la Cancillería, que escuchaba desde su puesto la conversación.\"},{\"heading\":false,\"text\":\"--La cosa es clara, la cosa es clara--repitió vivamente Nikodim Fomitch.\"},{\"heading\":false,\"text\":\"--Antes digo yo que es muy obscura--repitió Ilia Petrovitch.\"},{\"heading\":false,\"text\":\"Raskolnikoff tomó su sombrero y se dirigió a la puerta; pero al llegar a ella cayó desvanecido. Cuando recobró el sentido, estaba sentado en una silla. Uno le sostenía por la derecha; otro, por la izquierda, le ofrecía un vaso amarillo, lleno de un licor también amarillo. Nikodim Fomitch, en pie, delante del joven, le miraba atentamente. Raskolnikoff se levantó.\"},{\"heading\":false,\"text\":\"--¿Está usted enfermo?--le preguntó con tono bastante seco el comisario de policía.\"},{\"heading\":false,\"text\":\"--Hace poco, cuando extendió su declaración, apenas podía sostener la pluma--dijo el jefe de la Cancillería volviendo a sentarse delante de su escritorio y poniéndose de nuevo a examinar sus papelotes.\"},{\"heading\":false,\"text\":\"--¿Hace mucho tiempo que está usted malo?--dijo desde su sitio Ilia Petrovitch.\"},{\"heading\":false,\"text\":\"--Desde ayer--balbució el joven.\"},{\"heading\":false,\"text\":\"--¿Ayer salió usted de casa?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿A qué hora?\"},{\"heading\":false,\"text\":\"--Entre siete y ocho de la tarde.\"},{\"heading\":false,\"text\":\"--¿Y a dónde fué usted?\"},{\"heading\":false,\"text\":\"--A la calle.\"},{\"heading\":false,\"text\":\"Breve y compendioso, pálido como la cera, Raskolnikoff dió nerviosamente las anteriores respuestas, sin bajar sus inflamados ojos ante la mirada del oficial.\"},{\"heading\":false,\"text\":\"--Puede apenas tenerse en pie, y tú...--empezó a decir Nikodim Fomitch.\"},{\"heading\":false,\"text\":\"--No importa--respondió enigmáticamente Ilia Petrovitch.\"},{\"heading\":false,\"text\":\"El comisario de policía quiso replicar algo; pero al dirigir los ojos al jefe de la Cancillería, encontró la mirada del funcionario fija en él y guardó silencio.\"},{\"heading\":false,\"text\":\"--Está bien--dijo Ilia Petrovitch--; puede usted retirarse.\"},{\"heading\":false,\"text\":\"Raskolnikoff salió, pero aun no estaba en la sala inmediata cuando ya habían reanudado su conversación los dos funcionarios de policía con mayor animación y viveza. Por encima de todas las otras voces se elevaba la de Nikodim Fomitch como preguntando...\"},{\"heading\":false,\"text\":\"En la calle, el joven recobró todos sus ánimos.\"},{\"heading\":false,\"text\":\"--Sin duda van a hacer una indagatoria, una indagatoria sin pérdida de tiempo--repetía, dirigiéndose a buen paso hacia su casa--. ¡Los bribones! ¡Sospechan!\"},{\"heading\":false,\"text\":\"Volvió a asaltarle el terror.\"}]},{\"title\":\"segunda parte — capítulo II\",\"blocks\":[{\"heading\":false,\"text\":\"--¿Y si hubiesen empezado ya la indagatoria? ¿Si al entrar los encontrase en mi casa? He aquí mi habitación. Todo está en orden, nadie ha venido. Anastasia tampoco ha tocado nada. Pero, Señor, ¿cómo he podido dejar todos aquellos objetos en semejante escondite?\"},{\"heading\":false,\"text\":\"Corrió al rincón, e introduciendo la mano bajo la tapicería, sacó las alhajas, que en junto eran ocho.\"},{\"heading\":false,\"text\":\"Dos estuches contenían pendientes o algo parecido, no sabía qué; había además cuatro estuches pequeños de piel. Envuelta en un trozo de periódico una cadena de reloj; en otro papel un objeto que debía de ser una condecoración. Raskolnikoff se metió todo aquello en los bolsillos procurando que no hiciese mucho bulto; tomó también la bolsa y salió, dejando la puerta abierta de par en par.\"},{\"heading\":false,\"text\":\"Andaba con paso rápido y firme, y aunque se sentía quebrantado, no le faltó la serenidad. Temía que se le persiguiese, y que antes de media hora, de quince minutos quizá, se abriese un sumario contra él; por consiguiente era preciso que desaparecieran en seguida las piezas de convicción. Debía despachar cuanto antes, aprovechando la poca fuerza y sangre fría que le quedaba... ¿Pero a dónde ir?\"},{\"heading\":false,\"text\":\"Esta cuestión estaba ya resuelta tiempo hacía. «Lo tiraré todo al canal, y con ello irá también mi secreto al agua.» Así lo había decidido la noche precedente en los momentos de delirio, durante los cuales muchas veces sintió impulsos de levantarse y de ir a arrojarlo todo en seguida. Mas no era de fácil ejecución este proyecto.\"},{\"heading\":false,\"text\":\"Durante media hora, o acaso más, anduvo vagando a lo largo del canal Catalina, examinando, a medida que llegaba a ellas, las diversas escaleras que terminaban al borde del agua. Desgraciadamente, siempre se oponía algún obstáculo a la realización de su proyecto; aquí un barco de lavanderas, allí lanchas amarradas a la orilla. Por otra parte, el muelle estaba lleno de paseantes, que no hubieran podido menos de notar un hecho tan insólito; no era posible, sin infundir sospechas, descender expresamente hasta el nivel de la corriente para arrojar un objeto al canal. ¿Y si, como era de suponer, los estuches sobrenadaban en vez de desaparecer bajo el agua? Cualquiera de los paseantes los vería. Aun sin que esto ocurriese, Raskolnikoff creía que era objeto de la atención general; le parecía que todo el mundo se ocupaba en él.\"},{\"heading\":false,\"text\":\"Por último, el joven pensó que quizá sería lo mejor tirar todos aquellos objetos al Neva: en sus orillas era menos numerosa la concurrencia, menor el peligro de llamar la atención, y, consideración importante, estaría más lejos de su barrio.\"},{\"heading\":false,\"text\":\"--¿En qué consiste--se preguntó, con asombro Raskolnikoff--, que desde hace media hora vago ansiosamente por lugares peligrosos para mí? Estas objeciones que ahora me hago, ¿no pude hacérmelas antes? Si he perdido media hora en un proyecto tan sensato, es sin duda porque tomé mi resolución en un momento de delirio.\"},{\"heading\":false,\"text\":\"Sentíase singularmente distraído y olvidadizo. Decididamente era preciso apresurarse.\"},{\"heading\":false,\"text\":\"Se dirigió al Neva por la perspectiva de V***; pero, conforme iba andando, se le ocurrió otra idea.\"},{\"heading\":false,\"text\":\"--¿Para qué ir al Neva? ¿Por qué arrojar estos objetos al agua? ¿No sería mejor ir a cualquier parte, muy lejos, a una isla, por ejemplo? Buscaría un paraje solitario, un bosque, y enterraría las joyas al pie de un árbol, teniendo cuidado de señalarlo bien, a fin de poder reconocerlo más tarde.\"},{\"heading\":false,\"text\":\"Aunque comprendía que no se encontraba en estado de tomar una determinación juiciosa, le pareció práctica su última idea, y resolvió llevarla a cabo.\"},{\"heading\":false,\"text\":\"Pero la casualidad lo dispuso de otro modo. Al desembocar, por la perspectiva V***, en la plaza, Raskolnikoff advirtió a la izquierda la entrada de un corral rodeado por todas partes de altas paredes y cuyo suelo estaba cubierto de polvo negro. En el fondo había un cobertizo que pertenecía, sin duda, a un taller cualquiera.\"},{\"heading\":false,\"text\":\"No viendo a nadie en el corral, Raskolnikoff franqueó el umbral, y después de haber mirado atentamente en derredor suyo, pensó que ningún otro lugar ofrecería más facilidades para la realización de su plan. Precisamente, al pie del muro, o más bien de la valla de madera que lindaba con la calle, había adosada una piedra enorme, sin labrar, que lo menos pesaría sesenta libras.\"},{\"heading\":false,\"text\":\"Del otro lado de la cerca estaba la acera y el joven oía las voces de los transeuntes, siempre bastante numerosos en este sitio; pero desde fuera nadie podía verle; para ello hubiera sido necesario penetrar en el corral, cosa que, a la verdad, nada tenía de imposible. Por consiguiente, le convenía apresurarse.\"},{\"heading\":false,\"text\":\"Se inclinó sobre la piedra; la aferró con ambas manos por arriba, y, reuniendo todas sus fuerzas, consiguió darle vuelta. El suelo ocupado por el sillar estaba algo hundido; echó en el agujero todo lo que llevaba en los bolsillos, y colocó la bolsa encima de las alhajas; sin embargo, el agujero no quedó completamente lleno. En seguida levantó la piedra y consiguió colocarla en el mismo sitio en que estaba antes; lo más que podía advertirse, fijándose mucho, era que estaba un poco removida; pero apisonó con el pie la tierra alrededor de los bordes y nada podía notarse.\"},{\"heading\":false,\"text\":\"Hecho esto, se dirigió a la plaza. Como poco antes en el despacho de policía, se apoderó de él por un momento una alegría intensa, casi imposible de soportar.\"},{\"heading\":false,\"text\":\"--Las piezas de convicción están enterradas. ¿A quién se le podría ocurrir la idea de ir a buscarlas bajo aquella piedra? Está, sin duda, ahí desde que se construyó la casa inmediata y Dios sabe cuándo la quitarán. Y aun cuando alguien las encontrase, ¿quién podría sospechar que soy yo el que las ha ocultado? ¡Todo acabó! ¡No hay pruebas!\"},{\"heading\":false,\"text\":\"Y se echó a reír. Sí, se acordó más tarde que había atravesado la plaza riendo con risa nerviosa, muda y prolongada. Pero cuando llegó a la avenida de K*** su hilaridad cesó súbitamente.\"},{\"heading\":false,\"text\":\"Todos sus pensamientos giraban alrededor de otro principal, de cuya importancia se daba él exacta cuenta. Comprendía que por la primera vez, después de dos meses, se encontraba en presencia de esta cuestión.\"},{\"heading\":false,\"text\":\"--¡Vaya al diablo todo ello!--se dijo en un repentino acceso de cólera--. ¡Ea, el baile ha comenzado y es preciso danzar! ¡Malhaya sea la nueva vida! ¡Qué tonto es todo esto, Señor!... ¡Cuánto he mentido y cuántas bajezas he tenido que cometer hoy! ¡Cuántas vergonzosas tonterías para captarme poco ha la benevolencia de ese estúpido Ilia Petrovitch! ¿Pero qué me importa? ¡Me burlo de todos ellos y de mis simplezas! ¡No se trata de esto! ¡No, en modo alguno!\"},{\"heading\":false,\"text\":\"Se detuvo de repente, despistado, absorbido por una nueva cuestión hasta entonces inesperada y excesivamente simple.\"},{\"heading\":false,\"text\":\"--Si realmente has obrado en este asunto como hombre inteligente y no como un imbécil; si tenías trazado un fin y lo has perseguido derechamente, ¿cómo se explica que no hayas mirado siquiera lo que contenía la bolsa? ¿Cómo ignoras todavía lo que te ha aprovechado un acto, por el cual no has temido arrostrar peligros e infamias? ¿No querías, hace un momento, arrojar al agua esas alhajas y esa bolsa, a las cuales apenas si has echado una ojeada? ¿Qué significa esto?\"},{\"heading\":false,\"text\":\"Al llegar al muelle del pequeño Neva, en la plaza de Basilio Ostroff, se detuvo cerca del puente.\"},{\"heading\":false,\"text\":\"--¿Qué es esto? No parece sino que las piernas me han conducido por sí mismas al alojamiento de Razumikin. ¡La misma historia que el otro día! ¡Es curioso!... Marchaba sin objeto, y el azar me conduce aquí. No importa. ¿No decía yo anteayer que iría a verle al día siguiente del golpe? Pues bien, voy a verle. ¿No podré hacer ahora yo ni una visita?\"},{\"heading\":false,\"text\":\"Y subió al quinto piso en que vivía su amigo.\"},{\"heading\":false,\"text\":\"Estaba éste en una habitación muy reducida y se disponía a escribir; él mismo abrió la puerta; los dos jóvenes no se habían visto desde hacía cuatro meses. Envuelto en una bata toda desgarrada y mugrienta, en zapatillas y sin calcetines, con los cabellos enmarañados, Razumikin estaba sin afeitar y sin lavar. En su rostro se pintó el más vivo estupor.\"},{\"heading\":false,\"text\":\"--¡Caramba! ¿Tú por aquí?--exclamó, mirándole de pies a cabeza, e interrumpiéndose empezó a silbar--. ¿Es posible que tan mal vayan los negocios? La verdad es que aventajas en elegancia a este servidor--continuó después de haber echado una ojeada sobre los harapos de su compañero--. Vamos, siéntate, pues observo que estás cansado.\"},{\"heading\":false,\"text\":\"Cuando Raskolnikoff se hubo dejado caer en un diván más estropeado que el suyo, Razumikin se hizo cargo de la tristeza de su amigo.\"},{\"heading\":false,\"text\":\"--¿Sabes que estás enfermo de verdad?\"},{\"heading\":false,\"text\":\"Quiso tomarle el pulso, pero Raskolnikoff apartó vivamente la mano.\"},{\"heading\":false,\"text\":\"--Es inútil--dijo--. He venido porque... no tengo lecciones... y quisiera... ¿Pero qué necesidad tengo yo de lecciones?\"},{\"heading\":false,\"text\":\"--¿Sabes una cosa? Que estás disparatando--observó Razumikin mirando atentamente a su amigo.\"},{\"heading\":false,\"text\":\"--No, no disparato--repuso levantándose Raskolnikoff.\"},{\"heading\":false,\"text\":\"Cuando subía a casa de Razumikin no había pensado en que iba a encontrarse frente a frente con su compañero. Una entrevista, con quienquiera que fuese, le repugnaba, y rebosando de hiel, estaba a punto de estallar de cólera contra sí mismo desde que hubo franqueado el umbral de Razumikin.\"},{\"heading\":false,\"text\":\"--¡Adiós!--dijo bruscamente, y se dirigió hacia la puerta.\"},{\"heading\":false,\"text\":\"--¡Pero, ven acá, hombre! ¡Cuidado que eres raro!\"},{\"heading\":false,\"text\":\"--Es inútil--replicó el otro, retirando la mano que su amigo le había tomado.\"},{\"heading\":false,\"text\":\"--Entonces, ¿por qué has venido? ¿Has perdido la cabeza? Esto es casi una ofensa y no te dejaré marchar.\"},{\"heading\":false,\"text\":\"--Pues bien, escucha. He venido a tu casa porque no conozco a nadie más que a ti que pueda ayudarme a comenzar... Pero ahora veo que no me hace falta nada, ¿entiendes?, absolutamente nada... No tengo necesidad de los servicios ni de las simpatías de nadie; me basto a mí mismo. ¡Que me dejen en paz es lo que deseo!\"},{\"heading\":false,\"text\":\"--¡Pero ven acá, loco de atar! Tendrás que escucharme mal que te pese. Tampoco yo tengo lecciones, ni las quiero; pero en cambio he descubierto un editor, Kheruvimoff, que, en su género, es toda una lección. No lo cambiaría por cinco lecciones en casas de comerciantes. Publica libritos sobre ciencias naturales, que se pelea la gente por comprarlos. El toque está en encontrar los títulos. Tú solías decir que yo era tonto; pues ahí tienes, hay quien es más tonto que yo. Mi editor, que no conoce siquiera el silabario, se ha puesto al tono del día. Por supuesto que yo le animo... Aquí tienes estas dos hojas y media de una revista alemana; me parecen de la charlatanería más necia que puedas imaginarte. El autor estudia la cuestión de averiguar si la mujer es un hombre, y claro está, se decide por la afirmación y la demuestra de una manera incontestable. Estoy traduciendo este folleto para Kheruvimoff, que lo juzga de actualidad ahora que tan en boga está la cuestión feminista. Publicaremos seis hojas con las dos hojas y media del original alemán, le pondremos un título rimbombante que ocupará media página, y lo venderemos a cincuenta kopeks. ¡Será un éxito! La traducción se me paga a razón de seis rublos por hoja, lo que hace un total de quince rublos; he cobrado seis por adelantado. Vamos a ver, ¿quieres traducir la segunda hoja? Si quieres, toma el original, pluma y papel, todo ello corre de cuenta del Estado, y permíteme que te ofrezca tres rublos. Como yo he recibido seis, por la primera y segunda hoja, te corresponden tres, y cobrarás otros tantos cuando hayas terminado la traducción. No me lo agradezcas. En cuanto te he visto he pensado en utilizarte. En primer lugar, yo no estoy muy fuerte en ortografía y además conozco muy superficialmente el alemán; de modo que a menudo todo lo que escribo es de mi cosecha. Me consuelo con la idea de que de ese modo añado bellezas al texto; pero, ¿quién sabe? quizá me hago ilusiones. Vamos a ver, ¿aceptas?\"},{\"heading\":false,\"text\":\"Raskolnikoff tomó en silencio las hojas del folleto alemán y los tres rublos y salió sin decir palabra. Razumikin le siguió con una mirada de asombro; pero apenas Raskolnikoff hubo llegado a la primera esquina, volvió sobre sus pasos, subió a casa de su amigo, depositó en la mesa las páginas del folleto y los tres rublos y salió de nuevo sin despegar los labios.\"},{\"heading\":false,\"text\":\"--¡Tú estás loco!--vociferó Razumikin, ya colérico--. ¿Qué comedia estás representando? ¡Me haces salir de mis casillas! ¿A qué demonios has venido?\"},{\"heading\":false,\"text\":\"--No tengo necesidad de traducciones--murmuró Raskolnikoff empezando ya a bajar la escalera.\"},{\"heading\":false,\"text\":\"--Entonces, ¿de qué tienes necesidad?--le gritó Razumikin desde el rellano de su puerta.\"},{\"heading\":false,\"text\":\"El otro, callado, siguió bajando.\"},{\"heading\":false,\"text\":\"--Dime siquiera dónde vives.\"},{\"heading\":false,\"text\":\"Tampoco esta pregunta obtuvo respuesta.\"},{\"heading\":false,\"text\":\"--¡Ea! ¡vete a freír espárragos!\"},{\"heading\":false,\"text\":\"Raskolnikoff estaba ya en la calle.\"},{\"heading\":false,\"text\":\"El joven llegó a su casa al anochecer, sin que pudiera recordar por dónde había ido. Temblando como un caballo fatigado se desnudó, se echó en el diván y después de haberse cubierto con el sobretodo se quedó dormido...\"},{\"heading\":false,\"text\":\"Era ya completa la obscuridad cuando le despertó un estrépito horrible. ¡Qué escena tan espantosa debía desarrollarse cerca de él! Eran gritos, gemidos, rechinar de dientes, lágrimas, golpes, injurias como nunca había oído. Asustado, se sentó en el lecho; su terror crecía por momentos, porque a cada instante el ruido de los porrazos, las quejas, los insultos, llegaban más distintamente a sus oídos. Con extraordinaria sorpresa reconoció la voz de su patrona.\"},{\"heading\":false,\"text\":\"La pobre mujer gemía, suplicaba con tono doliente. ¡Imposible comprender lo que decía, pero sin duda suplicaba que no le pegasen más! La estaban maltratando implacablemente en la escalera. El hombre brutal que le pegaba gritaba de tal modo, con voz sibilante entrecortada por la cólera, que sus palabras eran ininteligibles. De repente, Raskolnikoff empezó a temblar como la hoja en el árbol; acababa de reconocer aquella voz; era la de Ilia Petrovitch.\"},{\"heading\":false,\"text\":\"--¡Ilia Petrovitch ha venido y está pegando a la patrona! ¡Le da puntapiés y coscorrones contra los peldaños de la escalera! Es seguro, no me engaño; el ruido de los golpes, los gritos de la víctima lo indican bien a las claras, dicen lo que está pasando; pero, ¿por qué? El mundo está revuelto.\"},{\"heading\":false,\"text\":\"De todos los pisos acudían a la escalera; se oían voces y exclamaciones. La gente subía, las puertas se abrían violentamente o se cerraban con estrépito.\"},{\"heading\":false,\"text\":\"--Pero, ¿qué pasa? ¿Cómo es posible...?--decía creyendo seriamente que la locura tomaba posesión de su cerebro.\"},{\"heading\":false,\"text\":\"Mas no, percibía distintamente aquellos ruidos...\"},{\"heading\":false,\"text\":\"--Si es así, van a venir a mi casa, porque todo ello seguramente es por lo de ayer... ¡Oh Señor!\"},{\"heading\":false,\"text\":\"Intentó echar el picaporte, pero no tuvo fuerzas para levantar el brazo; por otra parte, comprendía que de nada le serviría cerrar la puerta; el terror le helaba el alma...\"},{\"heading\":false,\"text\":\"Al cabo de diez minutos cesó poco a poco el estrépito: la patrona gemía, Ilia Petrovitch continuaba vomitando injurias y amenazas. Finalmente, se calló también y no se oyó más.\"},{\"heading\":false,\"text\":\"--¿Se había marchado? Sí. También se va la patrona; todavía llora, pero la puerta de su habitación se cierra violentamente... Los inquilinos dejan la escalera para retirarse a sus respectivos cuartos; lanzan exclamaciones; se llaman unos a otros; tan pronto gritan como hablan en voz baja. Debían de ser muchos... Han tenido que acudir todos los vecinos. Pero, Dios mío, ¿es todo esto posible? ¿Por qué, por qué ha venido aquí ese hombre?\"},{\"heading\":false,\"text\":\"Raskolnikoff se dejó caer sin fuerzas en el diván, pero ya no pudo dormir; durante media hora se sintió acometido de un espanto como nunca lo había sentido. De pronto, viva luz iluminó su estancia. Anastasia entraba con una bujía y un plato de sopa. La criada le miró atentamente, y convencida de que no dormía, colocó la luz sobre la mesa y fué poniendo en ésta, pan, sal, un plato y una cuchara.\"},{\"heading\":false,\"text\":\"--Creo que no has comido desde ayer. Andas vagando por esas calles de Dios a pesar de la fiebre...\"},{\"heading\":false,\"text\":\"--Anastasia, ¿por qué han pegado a la patrona?\"},{\"heading\":false,\"text\":\"La criada le miró fijamente.\"},{\"heading\":false,\"text\":\"--¿Que han pegado a la patrona?\"},{\"heading\":false,\"text\":\"--Hace poco... cosa de media hora. Ilia Petrovitch, el ayudante del comisario de policía le ha pegado, en la escalera... ¿Por qué la ha maltratado de este modo? ¿Por qué ha venido?\"},{\"heading\":false,\"text\":\"Anastasia frunció el entrecejo, y sin decir palabra contempló durante largo rato al pupilo. Ante aquella mirada inquisitiva el joven se quedó turbado.\"},{\"heading\":false,\"text\":\"--Anastasia, ¿por qué no me contestas?--preguntó tímida y débilmente.\"},{\"heading\":false,\"text\":\"--Es la sangre--murmuró la sirvienta como hablando consigo misma.\"},{\"heading\":false,\"text\":\"--¡La sangre!... ¿Qué sangre?--balbució Raskolnikoff poniéndose más pálido aún de lo que estaba y andando hacia atrás hasta la pared.\"},{\"heading\":false,\"text\":\"Anastasia continuaba observándole sin despegar los labios.\"},{\"heading\":false,\"text\":\"--Nadie ha pegado a la patrona--dijo, al fin, con sequedad.\"},{\"heading\":false,\"text\":\"El joven la miró, respirando apenas.\"},{\"heading\":false,\"text\":\"--Si lo he oído... Si no dormía... Estaba sentado en el diván--repuso con voz más temblorosa aún--. He escuchado durante largo rato... Ha venido el ayudante de policía. Ha salido la gente de todos los cuartos a la escalera...\"},{\"heading\":false,\"text\":\"--Nadie ha venido. Es la sangre la que grita en ti. Cuando no tiene salida se cuaja y uno delira, tiene alucinaciones... ¿Vas a comer?\"},{\"heading\":false,\"text\":\"El joven no respondió, y Anastasia, sin salir de la habitación, le miraba con ojos furiosos.\"},{\"heading\":false,\"text\":\"--Dame agua.\"},{\"heading\":false,\"text\":\"La sirvienta bajó, y dos minutos después volvía a subir con un jarro lleno de agua. A partir de este momento se interrumpieron los recuerdos de Raskolnikoff. Se acordaba únicamente de que había bebido un buche de agua fría desmayándose en seguida.\"}]},{\"title\":\"segunda parte — capítulo III\",\"blocks\":[{\"heading\":false,\"text\":\"Sin embargo, todo el tiempo que duró su enfermedad, nunca estuvo privado por completo del sentido: hallábase en un estado febril semi-inconsciente y solía delirar. Más tarde se acordó de muchas cosas: ora le parecía que varios individuos estaban reunidos en torno suyo; querían apoderarse de él y llevarle a alguna parte, y con este motivo disputaban vivamente; ora se veía de repente solo en su habitación; todo el mundo se había marchado, tenían miedo de él. De vez en cuando la puerta se abría, y le miraban disimuladamente, le amenazaban, reían y se consultaban, y él se ponía colérico, se daba cuenta a menudo de la presencia de Anastasia a su cabecera; veía también a un hombre que debía de serle muy conocido, pero, ¿quién era? Jamás conseguía dar un nombre a aquella figura, y esto le entristecía hasta el punto de arrancarle lágrimas. A veces se figuraba que estaba en cama hacía un mes; en otros momentos le parecía que todos los incidentes de su enfermedad habían ocurrido en un solo día; pero _aquello_, _aquello_ lo había olvidado por completo. Cierto que a cada instante pensaba que se había olvidado de algo de que hubiera debido acordarse, y se atormentaba, hacía penosos esfuerzos de memoria, gemía, se ponía furioso o sentía un terror invencible. Entonces se incorporaba en su lecho, quería huir, pero alguien le retenía a la fuerza. Estas crisis le debilitaban y terminaban en un desvanecimiento. Al fin recobró por completo el uso de sus sentidos.\"},{\"heading\":false,\"text\":\"Eran las diez de la mañana. Cuando hacía buen tiempo, el sol entraba en la habitación a esa hora, proyectando una ancha faja de luz por el muro de la derecha alumbrando el rincón próximo a la puerta. Anastasia se hallaba delante del lecho del enfermo, acompañada de un individuo a quien él no conocía, y que le observaba con mucha curiosidad. Era un joven de barba naciente, vestido con un caftán, y que parecía ser un _artelchtchit_[13].\"},{\"heading\":false,\"text\":\"[13] Miembro de una sociedad de obreros o de empleados.\"},{\"heading\":false,\"text\":\"Por la puerta entreabierta miraba la patrona. Raskolnikoff se incorporó un poco.\"},{\"heading\":false,\"text\":\"--¿Quién es, Anastasia?--preguntó, señalando al joven.\"},{\"heading\":false,\"text\":\"--¡Ha vuelto en sí!--dijo la criada.\"},{\"heading\":false,\"text\":\"--¡Ha vuelto en sí!--repitió el _artelchtchit_.\"},{\"heading\":false,\"text\":\"Al oír estas palabras, la patrona cerró la puerta y desapareció. A causa de su timidez, evitaba siempre entrevistas y explicaciones. Aquella mujer, que contaba ya cuarenta años, tenía cejas y ojos negros, curvas muy pronunciadas, y el conjunto de su persona resultaba bastante agradable. Buena como suelen ser las personas gruesas y perezosas, era, además, excesivamente pudorosa.\"},{\"heading\":false,\"text\":\"--¿Quién es usted?--preguntó Raskolnikoff dirigiéndose al _artelchtchit_.\"},{\"heading\":false,\"text\":\"En aquel momento se abrió la puerta, dando paso a Razumikin, que penetró en la habitación, inclinándose un poco a causa de su alta estatura.\"},{\"heading\":false,\"text\":\"--¡Vaya un camarote de barco!--exclamó al entrar--. Siempre doy con la cabeza en el techo. ¡Y a esto se llama una habitación! ¡Vamos, amigo mío, has recobrado ya el sentido, según me acaban de decir!\"},{\"heading\":false,\"text\":\"--Sí, ha recobrado el sentido--repitió como un eco el dependiente, sonriéndose.\"},{\"heading\":false,\"text\":\"--¿Quién es usted?--interrogó bruscamente Razumikin--. Yo me llamo Razumikin, soy estudiante, hijo de noble familia; el señor es amigo mío. ¡Vamos, ahora dígame usted quién es!\"},{\"heading\":false,\"text\":\"--Estoy empleado en casa del comerciante Chelopaief, y vengo aquí para cierto asunto...\"},{\"heading\":false,\"text\":\"--Siéntese usted en esta silla--dijo Razumikin ocupando él otra al lado opuesto de la mesa--. Has hecho muy bien en recobrar el conocimiento--añadió, volviéndose hacia Raskolnikoff--. Cuatro días hace, puede decirse, que no has comido ni bebido nada; apenas tomabas un poco de te, que te daban a cucharaditas. He traído aquí dos veces a Zosimoff. ¿Te acuerdas de Zosimoff? Te ha examinado muy atentamente, y ha dicho que no tenías nada. Afirma que tu enfermedad es una simple debilidad nerviosa, resultado de la mala alimentación, pero no reviste gravedad ninguna.\"},{\"heading\":false,\"text\":\"--¡Es famoso ese Zosimoff! ¡Hace curas asombrosas! Pero no quiero abusar de su tiempo--añadió Razumikin, dirigiéndose de nuevo al empleado--. ¿Quiere usted decirnos el motivo de su visita? Advierte, Rodia, que es la segunda vez que vienen ya de esa casa; pero no fué el señor el que vino. ¿Quién es el que estuvo el otro día?\"},{\"heading\":false,\"text\":\"--El que vino anteayer fué Alejo Semenovitch, también empleado de la casa.\"},{\"heading\":false,\"text\":\"--Tiene la lengua más expedita que usted, ¿verdad?\"},{\"heading\":false,\"text\":\"--Sí. Es un hombre de más capacidad.\"},{\"heading\":false,\"text\":\"--¡Modestia digna de elogio! Vamos, siga usted.\"},{\"heading\":false,\"text\":\"--Pues bien; por orden de la madre de usted, Anastasio Ivanovitch Vakruchin, de quien, sin duda, habrá oído hablar más de una vez, envía a usted dinero que nuestra casa tiene el encargo de entregarle--dijo el empleado encarándose ya directamente con Raskolnikoff--. Si posee usted la cédula de reconocimiento, hágase usted cargo de estos treinta y cinco rublos que Semenovitch ha recibido para usted de Anastasio Ivanovitch, por orden de su madre. Ha debido usted tener aviso del envío de esa cantidad.\"},{\"heading\":false,\"text\":\"--Sí; me acuerdo... Vakruchin...--dijo Raskolnikoff, procurando hacer memoria.\"},{\"heading\":false,\"text\":\"--¿Quiere usted firmarme el recibo?\"},{\"heading\":false,\"text\":\"--Sí, va a firmar. ¿Tiene usted ahí su libro?--dijo Razumikin.\"},{\"heading\":false,\"text\":\"--Sí, aquí está.\"},{\"heading\":false,\"text\":\"--Démelo usted. Vamos, Rodia; un esfuerzo, trata de incorporarte. Yo te sostendré; toma la pluma, y pon aquí tu nombre; en nuestros tiempos, el dinero es la miel de la humanidad.\"},{\"heading\":false,\"text\":\"--Yo no tengo necesidad de dinero--dijo Raskolnikoff, rechazando la pluma.\"},{\"heading\":false,\"text\":\"--¡Cómo! ¿Que no tienes necesidad de dinero?\"},{\"heading\":false,\"text\":\"--No firmo.\"},{\"heading\":false,\"text\":\"--¡Pero si tienes que dar un recibo!\"},{\"heading\":false,\"text\":\"--No tengo necesidad de dinero.\"},{\"heading\":false,\"text\":\"--¿No tienes necesidad de dinero?--repitió Razumikin--. Amigo mío, faltas a la verdad, doy fe. No se impaciente usted, se lo ruego; no sabe lo que dice... Está todavía en el país de los sueños... Cierto es, sin embargo, que suele ocurrirle lo mismo cuando está despierto... Usted es un hombre de buen sentido; le llevaremos la mano y firmará. Vamos, ayúdeme usted.\"},{\"heading\":false,\"text\":\"--No; puedo volver otra vez.\"},{\"heading\":false,\"text\":\"--De ningún modo. ¿Por qué se ha de molestar? Usted es un hombre razonable... Ea, Raskolnikoff, no detengas por más tiempo a este señor... ya ves que te espera.\"},{\"heading\":false,\"text\":\"Y Razumikin se dispuso a llevar la mano a Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Deja; lo haré yo solo--dijo éste.\"},{\"heading\":false,\"text\":\"Tomó la pluma, y firmó en el libro. El dependiente entregó el dinero y se marchó.\"},{\"heading\":false,\"text\":\"--¡Bravo! Y ahora, amigo mío, ¿quieres comer?\"},{\"heading\":false,\"text\":\"--Sí--respondió Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¿Hay sopa?\"},{\"heading\":false,\"text\":\"--Algo queda de ayer--respondió Anastasia que no había salido de la habitación durante toda esta escena.\"},{\"heading\":false,\"text\":\"--¿Sopa de arroz con patatas?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--Estaba seguro de ello. Ve a buscar la sopa, y danos también te.\"},{\"heading\":false,\"text\":\"--Bueno.\"},{\"heading\":false,\"text\":\"Raskolnikoff miraba a su amigo con profunda sorpresa y terror estúpido. Resolvió callarse y esperar.\"},{\"heading\":false,\"text\":\"--Me parece que no deliro--pensaba--; todo esto es muy real.\"},{\"heading\":false,\"text\":\"Al cabo de diez minutos Anastasia volvía con la sopa y anunció que serviría después el te. Trajo también dos cucharas, dos platos y el servicio correspondiente de mesa: sal, mostaza para tomarla con la carne, etc.; nunca había estado tan bien puesta la mesa desde hacía largo tiempo; hasta el mantel era limpio.\"},{\"heading\":false,\"text\":\"--Anastasia--dijo Razumikin--, Praskovia Pavlovna no haría mal en enviarnos un par de botellas de cerveza. Asegúrale que no quedará ni gota.\"},{\"heading\":false,\"text\":\"--De nada te privas--murmuró la criada y fué a hacer el encargo.\"},{\"heading\":false,\"text\":\"El enfermo continuaba observándolo todo con inquieta atención. Razumikin se sentó a su lado en el diván. Con la gracia de un oso sostenía, apoyada en el brazo izquierdo, la cabeza de Raskolnikoff, que no tenía ninguna necesidad de este auxilio, y con la mano derecha le llevaba a la boca cucharadas de sopa, después de soplarlas muchas veces para que su amigo no se quemase al tragarlas, a pesar de que la sopa estaba bastante fría. Raskolnikoff tomó con avidez tres cucharadas; pero Razumikin suspendió bruscamente la comida de su amigo, declarando que para tomarla era preciso consultar con Zosimoff.\"},{\"heading\":false,\"text\":\"En aquel momento entró Anastasia llevando las dos botellas de cerveza.\"},{\"heading\":false,\"text\":\"--¿Quieres te?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--Ve en seguida a buscar te, Anastasia, porque en lo tocante a esta infusión, opino que no hace falta el permiso de la Facultad. Aquí está la cerveza.\"},{\"heading\":false,\"text\":\"Se volvió a sentar en su silla, se acercó la sopera y la carne y se puso a devorar con tanto apetito como si no hubiese comido en tres días.\"},{\"heading\":false,\"text\":\"--Ahora, amigo Rodia, como todos los días en esta casa--murmuró con la boca llena--. Praskovia, tu amable patrona, me trata a cuerpo de rey; me tiene mucha consideración, y, es claro, yo me dejo querer. ¿Para qué protestar? Aquí está Anastasia con el te. Es lista esta muchacha. Anastasia, ¿quieres cerveza?\"},{\"heading\":false,\"text\":\"--¿Te burlas de mí?\"},{\"heading\":false,\"text\":\"--¿Pero un poco de te sí tomarás?\"},{\"heading\":false,\"text\":\"--Eso sí.\"},{\"heading\":false,\"text\":\"--Sírvete, o más bien, no, espera; yo te serviré. Siéntate a la mesa.\"},{\"heading\":false,\"text\":\"Haciendo de anfitrión, llenó sucesivamente dos tazas, después dejó su almuerzo y fué a sentarse otra vez en el sofá. Lo mismo que cuando la sopa, Razumikin empleó todo género de atenciones delicadas para que Raskolnikoff tomara el te. Este último se dejaba mimar sin decir palabra, aunque se sentía en estado de permanecer sentado en el diván sin el auxilio de nadie, de tener en la mano la taza y la cuchara y hasta de andar; pero con cierto maquiavelismo extraño y casi instintivo, se había decidido súbitamente a fingirse débil y simular cierta imbecilidad, teniendo, sin embargo, los ojos y los oídos en acecho. Al cabo, su disgusto fué más fuerte que su resolución; después de haber tomado diez cucharadas de te, el enfermo apartó la cabeza con un brusco movimiento, rechazó caprichosamente la cuchara y se dejó caer sobre la almohada. Esta palabra no era ya una metáfora. Raskolnikoff tenía ahora bajo la cabeza una buena almohada de plumas, con una funda muy limpia. Este detalle habíalo advertido el joven y no dejaba de preocuparle.\"},{\"heading\":false,\"text\":\"--Es preciso que Praskovia nos envíe conserva de frambuesa para preparar la bebida a Raskolnikoff--dijo Razumikin volviendo a sentarse en su sitio y reanudando su interrumpido almuerzo.\"},{\"heading\":false,\"text\":\"--¿Y dónde va a buscar la frambuesa?--preguntó Anastasia que, teniendo el platillo entre sus dedos separados, tomaba sorbos de te «al través del azúcar».\"},{\"heading\":false,\"text\":\"--Querida, tu ama la comprará en una tienda. Tú no sabes, Rodia: ha pasado aquí toda una historia. Cuando te escapaste de mi casa como un ladrón sin decirme dónde vivías, me incomodé tanto, que resolví encontrarte para tomar de ti una venganza ejemplar. Aquel mismo día me puse en campaña. ¡Lo que tuve que correr y preguntar! Se me habían olvidado tus nuevas señas, por la sencilla razón de que no las había sabido nunca. En cuanto a tu antiguo alojamiento, sólo me acordaba de que habitabas en los Cinco Rincones, en casa de Kharlamoff. Me lancé sobre esta pista, descubrí la casa de Kharlamoff, que no es la casa de Kharlamoff sino la de Bukh. Y ahí tienes cómo se embrolla uno con los nombres propios. Estaba furioso; al día siguiente, fuí a la oficina de Direcciones, sin confiar nada en el resultado de esta diligencia. Pues bien, figúrate mi asombro cuando en dos minutos me dieron la indicación de tu domicilio. Estás inscrito allí.\"},{\"heading\":false,\"text\":\"--¿Que estoy inscrito?\"},{\"heading\":false,\"text\":\"--¡Ya lo creo! Y, sin embargo, no pudieron dar las señas del general Kobeleff a uno que las pedía. Apenas llegué aquí cuando me enteré de todos tus asuntos, sí, amigo mío, de todos. Lo sé todo; Anastasia te lo dirá: he trabado conocimiento con Nikodim Fomitch; he sido presentado a Ilia Petrovitch, he entrado en relaciones con el _dvornik_, con Alejandro Grigorievitch Zametoff, jefe de la Cancillería, y, en fin, con la misma Pashenka; ése ha sido el golpe final. Pregúntaselo a Anastasia.\"},{\"heading\":false,\"text\":\"--Por fuerza la has embrujado--murmuró la criada con una sonrisa maliciosa.\"},{\"heading\":false,\"text\":\"--Fué una lástima, querido amigo, que desde el principio no te entendieses con ella. No debías haber procedido de este modo con Pashenka. Tiene un carácter muy extraño... pero ya hablaremos otro día de su carácter. Dime, ¿qué hiciste para que te cortase los víveres? ¿y eso del pagaré? Por fuerza estabas loco cuando lo firmaste. ¡Y el proyecto de matrimonio cuando vivía su hija Natalia Egorovna!... Estoy al corriente de todo. Pero veo que toco una cuerda muy delicada y que soy un burro. Perdóname. Mas, a propósito de tonterías, ¿no te parece que Praskovia Pavlovna es menos tonta de lo que a primera vista parece?\"},{\"heading\":false,\"text\":\"--Sí--balbuceó, mirándole de reojo, Raskolnikoff.\"},{\"heading\":false,\"text\":\"No comprendía que hubiera sido mejor seguir la conversación.\"},{\"heading\":false,\"text\":\"--¿Verdad que sí?--exclamó Razumikin--. ¿No es una mujer muy inteligente? Es un tipo muy original. Te aseguro, querido Rodia, que no la entiendo. Ha entrado ya en los cuarenta y no confiesa más que treinta y seis... Cosa que puede hacer sin temor a que la desmientan. Te aseguro que sólo puedo juzgarla desde el punto de vista intelectual, porque nuestras relaciones son las más singulares que puedes imaginarte. Repito que no la entiendo. Volviendo a nuestro asunto, ha sabido que dejaste de ir a la Universidad y que estás sin lecciones ni vestidos. Además, desde la muerte de su hija no había motivo para que te considerase como de su familia; en tales condiciones le ha asaltado cierta inquietud. Tú, por tu parte, en lugar de conservar con ella las relaciones de otro tiempo, vivías retirado en tu rincón, y, naturalmente, quería que te marchases. Pensaba desde hacía tiempo en eso; pero como le habías firmado un pagaré, asegurándole, además, que tu madre pagaría...\"},{\"heading\":false,\"text\":\"--He cometido una bajeza al decirle tal cosa... Mi madre está en la miseria. Yo mentía para que me siguiesen dando hospedaje y comida--dijo Raskolnikoff con voz entrecortada y vibrante.\"},{\"heading\":false,\"text\":\"--Tenías razón al hablar como hablaste; pero la intervención de Tchebaroff, curial y hombre de negocios, lo ha echado todo a rodar. Si no hubiera sido por éste, Pashenka no hubiera emprendido nada contra ti. Es demasiado tímida para hacer eso. En cambio, el hombre de negocios no es tímido y en seguida ha entablado la demanda. ¿El firmante de la letra es persona solvente? Respuesta: sí, porque su madre, aunque no posee más que una pensión de ciento veinticinco rublos, se quedaría sin comer con tal de sacar a Rodión de semejante apuro, y tiene además una hermana que se vendería como esclava por su hermano. El señor Tchebaroff se ha fundado en este cálculo. ¿Por qué te agitas? Adivino, amigo mío, lo que estás pensando; no tenías inconveniente en refugiarte en el seno de Pashenka cuando podía ver en ti un futuro yerno; pero, ¡ay!, en tanto que el hombre honrado y sensible se abandona a las confidencias, el hombre de negocios las recoge y hace su agosto. En suma; le entregó la letra a ese Tchebaroff, que no se ha andado por las ramas. Cuando lo supe, quise, para la tranquilidad de mi conciencia, tratar también al hombre de negocios por la electricidad; pero, entretanto, se ha establecido perfecta armonía entre Pashenka y yo, y he suspendido el procedimiento respondiendo de tu deuda. ¿Te enteras, amigo mío? He salido fiador por ti. He hecho venir a Tchebaroff, se le ha tapado la boca con diez rublos y ha devuelto el papel que tengo el honor de presentarte. Ahora, no eres más que un deudor bajo tu palabra. Tómalo.\"},{\"heading\":false,\"text\":\"--¿Eres tú a quien no conocía cuando deliraba?--preguntó Raskolnikoff, después de una pausa.\"},{\"heading\":false,\"text\":\"--Sí, y aun mi presencia te ha ocasionado alguna crisis violenta, sobre todo cuando he venido con Zametoff.\"},{\"heading\":false,\"text\":\"--¡Zametoff! ¿El jefe de la Cancillería?... ¿Por qué lo has traído?...\"},{\"heading\":false,\"text\":\"Al pronunciar estas palabras, Raskolnikoff cambiaba de posición y fijó los ojos en Razumikin.\"},{\"heading\":false,\"text\":\"--¿Qué te pasa? ¿Por qué te alteras? Deseaba conocerte y quiso venir porque habíamos hablado mucho de ti. ¿Cómo, de otra manera, hubiera sabido yo tantas cosas acerca de ti? Es un buen muchacho, amigo mío; maravilloso, claro que en su género; ahora somos amigos; nos vemos todos los días porque acabo de transportar mis penates a ese barrio. ¿Aun no lo sabías? Me he mudado recientemente. He ido dos veces con él a casa de Luisa. ¿Te acuerdas de Luisa? Luisa Ivanovna...\"},{\"heading\":false,\"text\":\"--¿He disparatado mucho durante mi delirio?\"},{\"heading\":false,\"text\":\"--Ya lo creo. No te lo puedes imaginar.\"},{\"heading\":false,\"text\":\"--¿Qué es lo que decía?\"},{\"heading\":false,\"text\":\"--¿Que qué decías? Ya se sabe lo que puede decir un hombre que no está en sus cabales... Pero no estamos aquí para perder el tiempo, sino para ocuparnos en nuestros asuntos.\"},{\"heading\":false,\"text\":\"Y así diciendo se levantó tomando su gorra.\"},{\"heading\":false,\"text\":\"--¿Qué es lo que decía?\"},{\"heading\":false,\"text\":\"--¿Quieres que te lo cuente? ¿Temes haber dejado escapar algún secreto? tranquilízate; de tus labios no ha salido ninguna palabra acerca de la cuestión, pero has hablado mucho de un _bulldog_, de pendientes, de cadenas de reloj, de la isla de Krestovsky, de un _dvornik_... ¡qué sé yo! Nikodim Fomitch e Ilia Petrovitch, el ayudante, salían a relucir en tu delirio. Además hablabas mucho de una de tus botas, no cesabas de decir llorando: ¡dámela! Zametoff la estuvo buscando por todos los rincones, y cuando encontró esa alhaja, no tuvo inconveniente en tomarla con sus blancas manos cubiertas de sortijas y tan perfumadas... Entonces fué cuando te calmaste, no soltándola durante veinticuatro horas. Imposible quitártela. Aun debe estar ahí, debajo de la colcha. También pedías las tiras del pantalón, ¡y con qué lágrimas! Hubiéramos deseado saber qué interés tenían para ti esas tiras; pero no entendíamos ni una sola de tus palabras. Ahora vamos a nuestro asunto. Aquí tienes treinta y cinco rublos; tomo diez y dentro de dos horas volveré y te daré cuenta del empleo que habré hecho de ellos. De paso entraré en casa de Zosimoff; ya debería estar aquí, porque son las once dadas. Durante mi ausencia, cuida tú, Anastasia, de que a éste no le falte nada y procura prepararle algo para beber... Ahora voy a dar por mí mismo instrucciones a Pashenka. Hasta la vista.\"},{\"heading\":false,\"text\":\"--¡La llama Pashenka! ¿Habráse visto un bribón como ése?--dijo la sirvienta cuando el joven, girando sobre sus talones, abandonó el cuarto, y saliendo también ella, se puso a escuchar detrás de la puerta; pero al cabo de un instante no pudo permanecer allí y descendió muy apresuradamente, deseosa de saber qué hablaba Razumikin con la patrona. Era evidente que Anastasia sentía verdadera admiración por el estudiante.\"},{\"heading\":false,\"text\":\"Apenas la criada había cerrado la puerta, el enfermo, echando a un lado la colcha, saltó del lecho como loco. Había esperado con impaciencia febril para poner mano a la obra. ¿A qué obra? Era el caso que, en aquel instante, no se acordaba de nada. «¡Señor! ¡Dime solamente una cosa! ¿Lo saben todo, o aun lo ignoran? Quizá ya estén enterados, pero fingen ignorarlo, porque me ven enfermo. Esperarán a que esté restablecido para quitarse la máscara: me dirán entonces que lo sabían todo desde hace largo tiempo... Pero, ¿qué es lo que tengo que hacer ahora? Si era una cosa urgente... la he olvidado y pensaba en ella hace un minuto.»\"},{\"heading\":false,\"text\":\"Estaba en pie en medio de la habitación, presa de dolorosa perplejidad. Se acercó a la puerta, la abrió y aplicó el oído; mas, ¿para qué? De repente pareció que recobraba la memoria; acudió al rincón en que la tapicería estaba desgarrada, introdujo la mano en el agujero y lo escudriñó. Mas no era tampoco aquello de lo que quería acordarse; abrió la estufa y estuvo escarbando las cenizas; los bordes cortados del pantalón y el forro del bolsillo se encontraban allí, conforme los echó antes el joven; de modo que nadie había hurgado en la estufa. Se acordó entonces de la bota, de la que le había hablado Razumikin. La bota estaba en el sofá, bajo la colcha, pero, desde el crimen había sufrido tantos frotamientos y manchádose con tanto lodo, que sin duda Zametoff no había podido notar nada.\"},{\"heading\":false,\"text\":\"--¡Bah!... ¡Zametoff!... ¡La oficina de policía! Pero, ¿por qué se me cita a esa oficina? ¿Dónde está la citación?... ¡Ah, sí, estoy confundido! Fué el otro día cuando se me hizo ir; examiné entonces también la bota; pero ahora, ahora he estado enfermo. Mas, ¿por qué ha venido aquí Zametoff? ¿Por qué lo ha traído Razumikin?--murmuraba Raskolnikoff, sentándose fatigado en el sofá--. ¿Qué pasa? ¿Estoy delirando, o veo las cosas como son? Me parece que no sueño. ¡Oh! ahora recuerdo... Es preciso partir, partir en seguida; no hay más remedio que alejarse. Pero ¿a dónde ir? ¿Y dónde está mi ropa? No tengo botas. Se las han llevado o las han escondido. ¡Ah! Comprendo. Aquí está mi gabán. No se han fijado en él. ¡Dinero aquí, sobre la mesa! ¡Gracias a Dios! La letra de cambio aquí también... Voy a tomarlo y a salir. Alquilaré otro cuarto y no me encontrarán... Pero, ¿y la oficina de Direcciones? Acabarán por descubrirme... Sí... Razumikin sabrá dar conmigo. Mejor será expatriarme, irme lejos, a América: allí me reiré de ellos. Tengo que llevarme la letra de cambio... Me servirá. ¿Que más necesito? Me creen enfermo, piensan que no me encuentro en estado de andar, ¡ja, ja! He leído en sus ojos que lo saben todo. No tengo más que bajar la escalera. Pero, ¿y si la casa estuviese vigilada, si abajo me encontrase con los agentes de policía?... ¿Qué es esto?... ¿Te...? También ha quedado algo de cerveza. Esto me refrescará.\"},{\"heading\":false,\"text\":\"Tomó la botella que aun contenía lo bastante para llenar un gran vaso y lo vació de un trago con verdadero placer, porque tenía ardiendo el estómago. Pero un minuto después prodújole la cerveza zumbidos en las sienes y un ligero escalofrío no del todo desagradable en la espina dorsal. Se acostó y tapó con la colcha. Sus ideas vagas e incoherentes se embrollaban cada vez más. Bien pronto sintió gran pesadez en los párpados, apoyó con placer la cabeza en la almohada, se tapó muy bien con la blanca colcha que había reemplazado y su harapiento gabán y se quedó profundamente dormido.\"},{\"heading\":false,\"text\":\"Se despertó al oír ruido de pasos y vió a Razumikin que acababa de abrir la puerta, pero que dudaba si penetrar o no en la habitación y permanecía de pie en el umbral.\"},{\"heading\":false,\"text\":\"Raskolnikoff se levantó vivamente y miró a su amigo con la expresión de un hombre que trata de recordar algo.\"},{\"heading\":false,\"text\":\"--Puesto que no duermes, aquí me tienes. Anastasia, sube el paquete--gritó Razumikin a la criada que estaba abajo--; voy a darte mis cuentas.\"},{\"heading\":false,\"text\":\"--¿Qué hora es?--preguntó el enfermo, dirigiendo en torno suyo una mirada inquieta.\"},{\"heading\":false,\"text\":\"--¡Buena siesta, amigo mío! Van a dar las seis y eran las doce cuando te dormiste. Así, tu sueño ha durado seis horas.\"},{\"heading\":false,\"text\":\"--¡Señor! ¡Cómo he podido dormir tanto rato!\"},{\"heading\":false,\"text\":\"--¿De qué te quejas? Este sueño te sentará bien. ¿Tenías algún negocio urgente? ¿Una cita quizás? Ahora todo el tiempo nos pertenece. Tres horas hace que esperaba a que te despertases. Dos veces he entrado y tú duerme que duerme. Otras dos veces he estado en casa de Zametoff; había salido; pero no importa, vendrá. Además he tenido que ocuparme en mis asuntos. He cambiado hoy de domicilio y he mudado todos mis trastos, incluso mi tío, porque te advierto que tengo al presente a un tío en mi casa... Pero basta, volvamos a nuestro asunto. Trae acá el paquete, Anastasia. Vamos en seguida a... Ante todo, ¿cómo estás?\"},{\"heading\":false,\"text\":\"--Me siento bien, ya no estoy enfermo. ¿Hace mucho tiempo que estás aquí, Razumikin?\"},{\"heading\":false,\"text\":\"--Acabo de decirte que he estado tres horas esperando a que te despertases.\"},{\"heading\":false,\"text\":\"--No hablo de ahora sino de antes.\"},{\"heading\":false,\"text\":\"--¿Cómo de antes?\"},{\"heading\":false,\"text\":\"--¿Desde cuándo vienes a esta casa?\"},{\"heading\":false,\"text\":\"--Ya te lo dije otra vez. ¿No te acuerdas?\"},{\"heading\":false,\"text\":\"Raskolnikoff hizo un llamamiento a su memoria. Se le presentaban los incidentes de aquel día como si los hubiera soñado, y viendo que en vano pretendía recordar, interrogó con una mirada a Razumikin.\"},{\"heading\":false,\"text\":\"--¡Hum!--dijo éste--; lo has olvidado. Ya me hacía yo cargo de que, la otra vez, no estabas en tu juicio. Ahora el sueño te ha sentado bien. Tienes mucho mejor cara. Ya recobrarás la memoria. Ahora, mira, querido amigo--y se puso a deshacer el paquete, que era evidentemente el objeto de todas sus preocupaciones--. Esto, amigo mío, es lo que más me interesaba. Hay que hacer de ti un hombre. ¡Vamos a ver! Comencemos por arriba. ¿Ves esta gorra?--dijo, sacando del envoltorio una muy decente, aunque ordinaria y de poco valor--. ¿Me dejas que te la pruebe?\"},{\"heading\":false,\"text\":\"--No, ahora no, más tarde--contestó Raskolnikoff rechazando a su amigo con un gesto de impaciencia.\"},{\"heading\":false,\"text\":\"--Tiene que ser ahora mismo, amigo Rodia; tú déjame a mí. Después sería demasiado tarde. Además, la inquietud me tendría en vela toda la noche, porque he comprado estas prendas al buen tun tun, sin tener la medida. ¡Te está perfectamente!--exclamó con aire de triunfo después de haberle probado la gorra--. Cualquiera diría que te la han hecho a la medida. ¿A que no aciertas, Nastachiuska, lo que me ha costado?--dijo encarándose con la criada, viendo que su amigo guardaba silencio.\"},{\"heading\":false,\"text\":\"--¿Dos grivnas?--respondió Anastasia.\"},{\"heading\":false,\"text\":\"--¡Dos grivnas! ¿Estás loca?--gritó Razumikin--. Ahora por dos grivnas no se podría comprar siquiera tu personita. ¡Ocho grivnas y eso porque está usada! Vamos a ver ahora el pantalón; te advierto que estoy orgulloso de él--y presentó a Raskolnikoff un pantalón de color ceniza de ligera tela de verano--. Ni un agujero, ni una mancha, y todavía muy llevable, aunque esté ya usado. El chaleco es del mismo color que el pantalón, como lo exige la moda. Por lo demás, estas prendas son mejores que nuevas, porque con el uso han adquirido suavidad, son más flexibles. Soy de parecer, amigo Rodia, de que para andar por el mundo es preciso arreglarse según la estación: las personas razonables no comen espárragos en el mes de enero; en mis compras, he seguido ese principio... Como estamos en verano, he comprado un vestido de verano. Que viene el otoño, te harán falta vestidos de más abrigo y abandonarás éstos... con tanta más razón, cuanto que de aquí allá habrán tenido tiempo de estropearse... Bueno, a ver si aciertas lo que han costado. ¿Cuánto te parece? Dos rublos y veinticinco kopeks. Ahora hablemos de las botas. ¿Qué tal? se ve que están usadas, es verdad, pero desempeñarán muy bien su papel durante dos meses; han sido hechas en el extranjero; eran de un secretario de la embajada británica que las vendió la semana pasada y que no las ha llevado más que seis días; sin duda andaría mal de dinero. Precio: un rublo y cincuenta kopeks: son de balde.\"},{\"heading\":false,\"text\":\"--Pero acaso no le vengan--observó Anastasia.\"},{\"heading\":false,\"text\":\"--¿Que no le vendrán? ¿Para qué sirve esto, entonces?--replicó Razumikin, sacando del bolsillo una bota vieja de Raskolnikoff, sucia y agujereada--. Había tomado mis precauciones. Todo ello se ha hecho muy concienzudamente. En cuanto a la ropa blanca ha habido mucho regateo con la revendedora; en fin, aquí tienes tres camisas con la pechera de moda. Y ahora recapitulemos: gorra, ocho grivnas; pantalón y chaleco, dos rublos y veinticinco kopeks; ropa blanca, cinco rublos; botas, un rublo cincuenta kopeks. Tengo que devolverte cuarenta y cinco kopeks. Toma, guárdalos; de esta suerte cátate ya emperifollado, porque, según mi juicio, tu paletó, no solamente puede servir aún, sino que conserva mucha distinción: se ve que ha sido hecho en casa de Charmer; en cuanto a los calcetines, etc... te dejo el cuidado de que los compres tú. Nos quedan veinticinco rublos y no tienes que inquietarte, ni de Pashenka ni del pago de inquilinato. Ya te lo he dicho: se te ha abierto un crédito ilimitado, y ahora es necesario que te mudes de ropa blanca, porque tu enfermedad está en tu camisa...\"},{\"heading\":false,\"text\":\"--Déjame, no quiero--respondió rechazándole Raskolnikoff, cuyo rostro había permanecido triste durante el festivo relato de Razumikin.\"},{\"heading\":false,\"text\":\"--Es preciso, amigo mío; ¿por qué me he destalonado yo por esas calles? Natachiuska, no te la eches de vergonzosa, ayúdame--y a pesar de la resistencia de Raskolnikoff, logró mudarle de ropa interior.\"},{\"heading\":false,\"text\":\"El enfermo se dejó caer sobre la almohada y no dijo una palabra durante dos minutos.\"},{\"heading\":false,\"text\":\"--¿No me dejarán tranquilo?--pensaba--. ¿Y con qué dinero se ha comprado todo esto?--preguntó en seguida, mirando a la pared.\"},{\"heading\":false,\"text\":\"--¡Vaya una pregunta! ¿Con qué dinero ha de haber sido? Con el tuyo. Tu madre te ha enviado por medio de Vakruchin treinta y cinco rublos que te trajeron hace poco. ¿Lo has olvidado, quizá?\"},{\"heading\":false,\"text\":\"--Sí, ya me acuerdo--dijo Raskolnikoff después de haberse quedado pensativo y sombrío.\"},{\"heading\":false,\"text\":\"Razumikin, fruncidas las cejas, le miraba con inquietud. Se abrió la puerta y entró en la habitación un hombre de alta estatura. Su manera de presentarse indicaba la costumbre de visitar la casa de Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¡Zosimoff! ¡Por fin!--gritó alegremente Razumikin.\"}]},{\"title\":\"segunda parte — capítulo IV\",\"blocks\":[{\"heading\":false,\"text\":\"El recién venido era un mocetón de veintisiete años, alto y grueso, de rostro un poco abotargado, pálido y afeitado cuidadosamente. Tenía el cabello de color rubio, casi blanco y cortado en forma de cepillo. Usaba lentes y en el índice de su carnosa mano brillaba un grueso anillo de oro. Se comprendía que le gustaba usar cómodos vestidos que no carecían de cierta elegancia. Llevaba un ancho gabán de verano y pantalón claro. La pechera, los puños y cuello eran irreprochables, y brillaba sobre su chaleco pesada cadena de oro. Sus modales tenían algo de lentos y de flemáticos, aunque hacía esfuerzos para darse aire de desenvuelto. Por lo demás, a despecho de su cuidado, se advertía en sus maneras algo de afectación. Cuantos le conocían le encontraban insoportable; pero le tenían en grande estima como médico.\"},{\"heading\":false,\"text\":\"He estado dos veces en tu casa... ¿Lo estás viendo? Ha recobrado ya los sentidos.\"},{\"heading\":false,\"text\":\"--Ya veo, ya veo; ¿cómo nos sentimos hoy?--preguntó Zosimoff a Raskolnikoff, mirándole atentamente.\"},{\"heading\":false,\"text\":\"Y al mismo tiempo se sentaba en el extremo del sofá, a los pies del enfermo, esforzándose por encontrar un sitio para su enorme persona.\"},{\"heading\":false,\"text\":\"--¡Siempre hipocondríaco!--continuó Razumikin--; hace poco, cuando le hemos mudado de ropa interior, casi se ha echado a llorar.\"},{\"heading\":false,\"text\":\"--Se comprende, lo mismo hubiera sido mudarle luego; no era necesario contrariarle... El pulso es excelente, seguimos con un poco de dolor de cabeza, ¿no es verdad?\"},{\"heading\":false,\"text\":\"--Estoy perfectamente--dijo Raskolnikoff irritado.\"},{\"heading\":false,\"text\":\"Y al pronunciar estas palabras se incorporó de repente en el sofá y brillaron sus ojos. Pero un instante después se dejó caer sobre la almohada, volviéndose del lado de la pared. Zosimoff le miraba atentamente.\"},{\"heading\":false,\"text\":\"--¡Muy bien! Nada de particular--dijo con cierta indiferencia--. ¿Has tomado algo?\"},{\"heading\":false,\"text\":\"Se le dijo lo que había comido el enfermo y se le preguntó qué podía dársele.\"},{\"heading\":false,\"text\":\"--Puede tomar lo que quiera, sopa, te... Claro es que quedan prohibidos los cohombros y las setas; no conviene tampoco que coma carne... aunque esta advertencia es ociosa.\"},{\"heading\":false,\"text\":\"Cambió una mirada con Razumikin y prosiguió:\"},{\"heading\":false,\"text\":\"--Nada de pociones ni medicamentos; mañana veremos... Hoy se hubiera podido... de todos modos está bien.\"},{\"heading\":false,\"text\":\"--Mañana por la tarde le sacaré a dar un paseo--dijo Razumikin--, iremos juntos al jardín Yusupoff y después al Palacio de Cristal.\"},{\"heading\":false,\"text\":\"--Mañana sería demasiado pronto; pero un paseíto corto... En fin, mañana veremos.\"},{\"heading\":false,\"text\":\"--Lo que siento es que precisamente hoy inauguro mi nueva vivienda, que está a dos pasos de aquí, y desearía que fuese uno de los nuestros, aunque tuviese que estar tendido en un sofá. ¿Vendrás tú?--preguntó Razumikin al doctor--; lo has prometido, no faltes a tu palabra.\"},{\"heading\":false,\"text\":\"--Bueno, no podré ir hasta bastante tarde. ¿Das un convite?\"},{\"heading\":false,\"text\":\"--¡Nada de convite! Te, aguardiente, arenques y pastas... Una reunión de amigos.\"},{\"heading\":false,\"text\":\"--¿Y quiénes son tus huéspedes?\"},{\"heading\":false,\"text\":\"--Compañeros jóvenes y mi tío, un viejo que ha venido a no sé qué negocios a San Petersburgo; llegó ayer. Sólo nos vemos una vez cada cinco años.\"},{\"heading\":false,\"text\":\"--¿En qué se ocupa?\"},{\"heading\":false,\"text\":\"--En vegetar en un distrito. Es maestro de postas, cobra una pensioncilla y tiene sesenta y cinco años. No hablemos más de él, aunque le quiero. Estará también Porfirio Petrovitch, juez de instrucción del distrito... un notable jurisconsulto. Tú le conoces.\"},{\"heading\":false,\"text\":\"--¿Es también pariente tuyo?\"},{\"heading\":false,\"text\":\"--Muy lejano. Mas, ¿por qué arrugas el entrecejo? ¿Crees que porque un día tuvisteis no sé qué disputa estás en el caso de no venir?\"},{\"heading\":false,\"text\":\"--¡Oh! ¡Me río de él!\"},{\"heading\":false,\"text\":\"--Es lo más cuerdo que puedes hacer. Habrá también estudiantes, un profesor, un empleado, un músico y un oficial, Zametoff.\"},{\"heading\":false,\"text\":\"--Dime, te lo ruego, lo que tú o éste--Zosimoff señaló con un movimiento de cabeza a Raskolnikoff--tenéis de común con ese Zametoff.\"},{\"heading\":false,\"text\":\"--Pues bien, ya que quieres que te lo diga, entre Zametoff y yo hay algo común; traemos cierto negocio entre manos.\"},{\"heading\":false,\"text\":\"--Me gustaría saber qué negocio es ése.\"},{\"heading\":false,\"text\":\"--A propósito del pintor decorador. Trabajamos porque se le ponga en libertad. Creo que lo conseguiremos. El asunto es perfectamente claro; nuestra intervención tiene por único objeto apresurar el desenlace.\"},{\"heading\":false,\"text\":\"--¿A qué pintor te refieres?\"},{\"heading\":false,\"text\":\"--¿No te he hablado ya de él? ¡Ah! es verdad. No te he contado más que el principio... Se trata del asesinato de la vieja prestamista sobre prendas. Pues bien, el pintor fué detenido como autor del doble crimen.\"},{\"heading\":false,\"text\":\"--Sí, antes que me contaras todo eso ya había oído yo hablar de esos asesinatos, y, a decir verdad, la cosa me interesa hasta cierto punto... He leído algo en los periódicos.\"},{\"heading\":false,\"text\":\"--También mataron a Isabel--dijo, de pronto Anastasia, dirigiéndose a Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¡Isabel!--murmuró el enfermo con voz casi ininteligible.\"},{\"heading\":false,\"text\":\"--Sí, Isabel, la revendedora. ¿No la conocías? Venía a casa de la patrona. Por cierto que te hizo una camisa.\"},{\"heading\":false,\"text\":\"Raskolnikoff se volvió del lado de la pared y se puso a contemplar con gran atención una de las florecillas blancas de que estaba sembrado el papel que tapizaba su habitación. Sentía que se le entumecían los miembros, pero no se atrevía a moverse y continuaba con la mirada fija en la florecilla de papel.\"},{\"heading\":false,\"text\":\"--¿Luego resultan cargos contra ese pintor?--preguntó Zosimoff interrumpiendo con manifiesto enojo a la criada, que suspiró y guardó silencio.\"},{\"heading\":false,\"text\":\"--Sí; pero esos cargos, en rigor, no son tales, y eso es precisamente lo que se trata de demostrar. La policía sigue una pista falsa, como la siguió al principio cuando sospechó de Koch y Pestriakoff. Por poco interés que se tenga en la cuestión, se siente uno indignado al ver una sumaria tan neciamente conducida. Pestriakoff vendrá probablemente esta noche a mi casa; y, a propósito, Rodia, tú tienes noticia de ese crimen; ocurrió el día antes que cayeras enfermo, la víspera de tu desmayo en la oficina de policía, precisamente cuando se estaba hablando de él.\"},{\"heading\":false,\"text\":\"El médico miró curiosamente a Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Será preciso que yo no te quite el ojo de encima, Razumikin--le dijo--; te interesas demasiado por un asunto que no te va ni te viene.\"},{\"heading\":false,\"text\":\"--Es posible, pero no importa. Arrancaremos a ese desgraciado de las garras de la justicia--exclamó Razumikin, descargando un puñetazo sobre la mesa--. Mas no son los errores de esa gente lo que me irritan; cualquiera se equivoca. Además, el error es cosa excusable, puesto que por medio de él se llega a la verdad; no, lo que me molesta es que estando engañados continúan creyéndose infalibles. Yo estimo a Porfirio; pero... ¿Sabes lo que en un principio los ha despistado? La puerta estaba cerrada; y cuando Koch y Pestriakoff subieron con el portero estaba abierta: luego Koch y Pestriakoff son los asesinos. ¡Vaya una lógica que me gastan!\"},{\"heading\":false,\"text\":\"--No te acalores. Los han detenido porque no tenían más remedio que detenerlos. Y a propósito, he visto de nuevo a Koch; creo que estaba en relaciones de negocios con la vieja. ¿Le compraba los objetos empeñados después del vencimiento?\"},{\"heading\":false,\"text\":\"--Sí, es un camastrón. Negocia también letras de cambio. El mal rato que ha pasado no me importa un comino. Pero me sublevo contra los sistemas estúpidos de un procedimiento anticuado... Tiempo es ya de emprender un nuevo camino y de renunciar a viejas rutinas. Unicamente los datos psicológicos pueden arrojar luz en estos procesos. «Tenemos hechos», dicen; pero los hechos no son todo; la manera de interpretarlos contribuye por lo menos en una mitad al éxito de un sumario.\"},{\"heading\":false,\"text\":\"--¿Sabes tú interpretar los hechos?\"},{\"heading\":false,\"text\":\"--Mira, es imposible callarse cuando se siente, cuando se tiene la íntima convicción de que se puede contribuir al descubrimiento de la verdad... ¿Conoces los pormenores de ese asunto?\"},{\"heading\":false,\"text\":\"--Me habías hablado no sé qué de un pintor decorador, pero no me has contado el suceso.\"},{\"heading\":false,\"text\":\"--Pues bien, oye. Dos días después de cometido el asesinato, por la mañana, en tanto que la policía procedía contra Koch y Pestriakoff, a pesar de las explicaciones perfectamente categóricas dadas por ellos, surgió un incidente completamente inesperado. Cierto Dutchkin, campesino que tiene una taberna enfrente de la casa del crimen, llevó a la comisaría un estuche que encerraba unos pendientes de oro, y con tal motivo contó su historia: «Anteayer tarde, poco después de las ocho (fíjate en esta coincidencia), Mikolai, un obrero pintor, parroquiano de mi establecimiento, fué a suplicarme que le prestase dos rublos por los pendientes que contenía el estuche. A mi pregunta: «¿Dónde has encontrado esto?», me respondió que en la calle. No le pregunté más (es Dutchkin quien habla), y le di un billetito, es decir, un rublo, porque dije para mis adentros: si no tomo este objeto lo tomará otro, y mejor es que esté en mis manos; si lo reclaman y sé que ha sido robado, iré a entregarlo a la policía.» Bien mirado, al hablar de este modo--prosiguió Razumikin--, mentía descaradamente; conozco a ese Dutchkin, es un encubridor, y cuando tomó de Mikolai una alhaja que valía treinta rublos, no tenía intención de entregarla a la policía. Se decidió a ello bajo la influencia del miedo. Pero dejemos a Dutchkin continuar su relato: «Desde niño conozco a ese campesino que se llama Mikolai Dementieff; es, como yo, del gobierno de Riazan y del distrito de Zaraisk. Sin ser un borracho, bebe algunas veces demasiado. Sabíamos que estaban trabajando con Mitrey, que es de su país. Después de haber recibido el billetito, Mikolai apuró dos copas, cambió su rublo para pagar y se marchó, llevándose el cambio de la moneda. No vi a Mitrey con él. Al día siguiente, oímos decir que habían matado a hachazos a Alena Ivanovna y a su hermana Isabel Ivanovna. Nosotros las conocíamos y entonces nacieron nuestras sospechas a propósito de los pendientes, porque sabíamos que la vieja prestaba dinero sobre alhajas. Para aclarar mis dudas, me dirigí a casa de las interfectas haciéndome el ignorante, y lo primero que hice fué averiguar si estaba allí Mikolai. Mitrey me dijo que su camarada andaba de picos pardos, Mikolai entró borracho en su casa por la mañana temprano y diez minutos después salió de ella. Desde entonces Mitrey no le había vuelto a ver, y, como es consiguiente, trabajaba solo. La escalera que conduce a la habitación de las víctimas, es también la del cuarto en que trabajan los dos obreros; este cuarto está situado en el segundo piso. Habiendo sabido esto, no dije palabra a nadie (es Dutchkin el que habla); pero recogí muchas noticias acerca del asesinato y me volví a mi casa preocupado siempre con la misma duda. Esta mañana, a las ocho (es decir, a las dos horas del crimen, ¿comprendes?), he visto a Mikolai entrar en mi establecimiento. Estaba algo bebido, pero no del todo borracho, de modo que podía comprender lo que se le dijera. El hombre se sentó silenciosamente en un banco. Cuando llegó Mikolai no había en la taberna más que un parroquiano que dormía en otro banco; sin contar, por supuesto, los dos mozos. «¿Has visto a Mitrey?», pregunté a Mikolai. «No, dijo, no le he visto.» «¿Y no has ido a trabajar?» «No he ido desde anteayer», respondióme. «¿En dónde has dormido esta noche?» «En las Arenas, en casa de los Kolomensky.» «¿Y de dónde has sacado los pendientes que me trajiste el otro día?» «Los encontré en la acera», dijo con aire sospechoso, evitando mirarme. «¿Has oído decir que esa misma tarde y a la misma hora ha ocurrido algo en el edificio en que trabajas?» «No, me contestó, nada sé.» Le cuento todo el suceso, y él me escucha abriendo desmesuradamente los ojos. De repente, se pone más blanco que la pared, toma la gorra y se levanta. Traté entonces de detenerle. «Espera un poco, Mitchka, le digo. Echa otra copa». Al mismo tiempo hago señas a uno de los mozos para que se ponga delante de la puerta, mientras yo me aparto del mostrador. Pero adivinando, sin duda, mis intenciones, se lanza fuera de la casa, echa a correr y desaparece por una bocacalle. Desde aquel momento no tengo la menor duda de que es el culpable.\"},{\"heading\":false,\"text\":\"--¡Ya lo creo!--dijo Zosimoff.\"},{\"heading\":false,\"text\":\"--Espera. Escucha hasta el fin. Naturalmente, la policía se puso a buscar por todas partes a Mikolai. Detuvo a Dutchkin y Mitrey e hizo varios registros en sus casas; pero hasta anteayer no se ha logrado capturar a Mitka, a quien se encontró en una posada del arrabal de***, en circunstancias bastante raras. Una vez en esa posada, se quitó su cruz que era de plata, la entregó al posadero y pidió un _shkalik_[14] de aguardiente. Minutos después, una campesina que acababa de ordeñar las vacas, mirando por la rendija del establo, vió al pobre hombre haciendo preparativos para ahorcarse. Tenía hecho un nudo corredizo a su cinturón, lo había atado a una viga del techo; y, subido en una pila de madera, trataba de echarse al cuello la lazada. A los gritos de la mujer acudió la gente: «¡Vaya un entretenimiento el tuyo!» «Conducidme, dijo, a la oficina de policía; lo confesaré todo.» Se accedió a su demanda, y con todos los honores debidos a su clase, se le condujo a la comisaría de nuestro barrio, donde se le sometió a un detenido interrogatorio. «¿Quién eres tú? ¿Qué edad tienes?» «Veintidós años, etc.» Pregunta: «Mientras estabas trabajando con Mitrey, ¿no vieron ustedes a nadie en la escalera entre tal y cual hora?» Respuesta: «Quizá pasó alguien, pero no reparamos.» «¿Y no oyeron ustedes nada?» «Nada.» «¿Y tú, Mikolai, no supiste que aquel día y a tal hora habían asesinado y robado a la vieja y a su hermana?» «Nada absolutamente sabía de eso; tuve la primera noticia anteayer, en la taberna; me la dió Atanasio Papritch.» «¿Y en dónde encontraste los pendientes?» «En la calle.» «¿Por qué al día siguiente no fuiste a trabajar con Mitrey?» «Porque quise holgar.» «¿En dónde estuviste?» «En diferentes sitios.» «¿Por qué escapaste de casa de Dutchkin?» «Porque tenía miedo.» «¿De que tenías miedo?» «De la justicia.» «¿Y por qué tenías miedo de la justicia no siendo culpable de nada?»\"},{\"heading\":false,\"text\":\"[14] Medida de capacidad equivalente a unos 30 centilitros.\"},{\"heading\":false,\"text\":\"»Pues bien, tú lo creerás o no lo creerás, Zosimoff; pero la cuestión se ha planteado literalmente en los términos que te he dicho, lo sé de cierto porque se me ha repetido palabra por palabra el interrogatorio. ¿Eh? ¿qué tal? ¿Qué te parece?\"},{\"heading\":false,\"text\":\"--Pero, en fin, ¿hay pruebas?\"},{\"heading\":false,\"text\":\"--No se trata ahora de pruebas, sino de las preguntas hechas a Mikolai y de la manera que tiene la gente de policía de entender la naturaleza humana. Bueno, dejemos esto. Para abreviar: de tal manera atormentaron a ese infeliz, que acabó por confesar que no fué en la calle donde encontró los pendientes, sino en el cuarto en que trabajaba con Mitrey. «¿Cómo los has encontrado?», le preguntan. Y él contesta: «Mitrey y yo estuvimos pintando todo el día; eran las ocho e íbamos a marcharnos, cuando Mitrey tomó un pincel, me lo pasó por la cara y echó a correr, después de haberme untado. Me lancé en su persecución, bajé los escalones de cuatro en cuatro gritando como un loco, y en el momento en que llegaba abajo con toda la velocidad de mis piernas, di un empujón al portero y a unos cuantos señores que se encontraban allí también, no recuerdo cuántos. Entonces el portero me injurió, otro portero le hizo coro, la mujer del primer piso salió de la portería, donde se hallaba, y añadió sus insultos a los que los otros me dirigían. En fin, un señor, que entraba en la casa con una señora, nos reprendió, a Mitka y a mí, porque estábamos derribados en el suelo delante de la puerta e impedíamos el paso; yo tenía asido a Mitka por los cabellos y le pegaba puñetazos. El también me tenía agarrado por el pelo y me daba cuantos golpes podía, aunque estaba debajo de mí. Hacíamos esto sin reñir, en broma, riendo a carcajadas. Luego Mitka logró escapar de mis manos y se escurrió a la calle; yo corrí tras él, pero no pude alcanzarle y volví solo al cuarto en que trabajábamos para recoger los útiles del oficio. Mientras los arreglaba, esperando a Mitka, pues estaba seguro de que volvería, vi en un rincón, al lado de la puerta, una cosa envuelta en un papel. Quité el papel y encontré un estuche que contenía unos pendientes...»\"},{\"heading\":false,\"text\":\"--¿Detrás de la puerta? ¿Estaba detrás de la puerta, detrás de la puerta?--repitió Raskolnikoff mirando espantado a Razumikin y haciendo esfuerzos para incorporarse en el sofá.\"},{\"heading\":false,\"text\":\"--Sí. ¿Qué te pasa? ¿Por qué te pones así?--dijo Razumikin, saltando de su asiento.\"},{\"heading\":false,\"text\":\"--No, no es nada--respondió Raskolnikoff con voz débil, dejándose caer de nuevo sobre la almohada y poniéndose de cara a la pared.\"},{\"heading\":false,\"text\":\"Reinó un silencio de algunos minutos.\"},{\"heading\":false,\"text\":\"--Estaba, sin duda, adormilado--dijo Razumikin, interrogando con la mirada a Zosimoff, quien hizo con la cabeza un leve movimiento negativo.\"},{\"heading\":false,\"text\":\"--Continúa--dijo el doctor--; ¿y después?\"},{\"heading\":false,\"text\":\"--Ya sabes lo demás. En cuanto tuvo los pendientes no pensó ni en sus útiles del oficio ni en Mitrey; tomó la gorra y se fué en seguida a la taberna de Dutchkin. Como ya te he dicho, hizo que éste le diera un rublo, diciéndole que había encontrado el estuche en la calle, y en seguida se fué de holgorio. Mas en lo concerniente al asesinato, su lenguaje no varía: «No sé nada, repite constantemente. No tuve noticias del crimen hasta el día después.» «Pero, ¿por qué has desaparecido durante todo ese tiempo?» «Porque temía que me vieran.» «¿Y por qué querías ahorcarte?» «Porque tenía miedo.» «¿De qué tenías miedo?» «De que me procesaran.» Esta es la historia. Ahora bien, ¿qué dirás que sacan en conclusión de todo ello?\"},{\"heading\":false,\"text\":\"--¿Qué quieres que diga? Existe una presunción, discutible, quizá, pero no deja de ser una presunción. ¿Crees tú que debían poner en libertad a ese pintor decorador?\"},{\"heading\":false,\"text\":\"--Sí, pero es el caso que están convencidos de que es el autor del crimen.\"},{\"heading\":false,\"text\":\"--Vamos a ver, y no te exaltes. Te olvidas de los pendientes. El mismo día, pocos instantes después de haberse cometido el crimen, los pendientes, que sin duda se hallaban en el baúl de la víctima, estaban en manos de Mikolai: has de convenir conmigo en que es preciso averiguar cómo llegaron a su poder; es éste un punto que el juez instructor no puede por menos que aclarar.\"},{\"heading\":false,\"text\":\"--¿Que cómo llegaron a su poder?--exclamó Razumikin--. ¿Que cómo llegaron a su poder? Ante todo, doctor, por tu condición de médico has tenido ocasión de estudiar al hombre y profundizar la naturaleza humana. Siendo esto así, ¿es posible que no veas cuál es la de ese Mikolai? ¿Cómo no te haces cargo _a priori_ de que todas las declaraciones prestadas por él en el curso de los interrogatorios son verdaderas? Los pendientes llegaron a sus manos exactamente como él dice: tropezó con el estuche y lo recogió.\"},{\"heading\":false,\"text\":\"--¡Verdaderas!... Sin embargo, él mismo ha confesado que mintió en su primera declaración.\"},{\"heading\":false,\"text\":\"--Escúchame, escúchame atentamente: el portero, la mujer de éste, Koch. Pestriakoff, el otro portero, la inquilina del primer piso que se hallaba a la sazón en la portería, el consejero Krukoff, que en aquel mismo instante acababa de apearse del coche y entraba en la casa con una señora del brazo; todos, es decir, ocho o diez testigos, declaran unánimemente que Mikolai tiró a Mitrey al suelo y que, conforme le tenía debajo, le daba puñetazos, mientras el otro agarraba a su compañero del pelo y procuraba devolverle los golpes recibidos. Estaban tirados delante de la puerta, interceptando el paso; los injurian, y ellos «lo mismo que chiquillos» (es la expresión de los testigos), gritan, se maltratan, lanzan carcajadas y se persiguen en la calle como dos pilluelos. ¿Comprendes? Ahora fíjate en esto: arriba yacen dos cadáveres que no se han enfriado todavía, pues estaban calientes aún cuando los descubrieron. Si hubiesen cometido el crimen los dos obreros o solamente Mikolai, permíteme que te pregunte: ¿Se comprende tal descuido, tal serenidad en personas que acaban de cometer dos asesinatos seguidos de robo? ¿No existe verdadera incompatibilidad entre esos gritos, esas risas, esa lucha infantil y el estado de ánimo en que debieran encontrarse los asesinos? ¡Cómo! ¡A los cinco o diez segundos de haber matado (porque, lo repito, se han encontrado todavía calientes los cadáveres), se van sin cerrar la puerta del cuarto en que yacen sus víctimas, y sabiendo que sube gente al cuarto en donde se ha perpetrado el delito, retozan en el umbral de la puerta cochera, y en lugar de huir apresuradamente interceptan el paso, ríen, atraen la atención de la gente, hasta el punto de que hay diez testigos que declaran unánimemente!\"},{\"heading\":false,\"text\":\"--Es verdad; eso es extraño; parece imposible; pero...\"},{\"heading\":false,\"text\":\"--No hay _pero_ que valga, amigo mío. Reconozco que los pendientes encontrados en poder de Mikolai, poco después de cometido el crimen, constituyen en contra del pintor un hecho grave, hecho por otra parte, explicado de manera plausible por el acusado, y en consecuencia, sujeto a discusión; pero hay que tener también en cuenta los hechos justificativos, tanto más cuanto que éstos están fuera de discusión. Desgraciadamente, dado el espíritu de nuestras leyes, los magistrados son incapaces de admitir que un hecho justificativo, fundado en una pura posibilidad psicológica, pueda destruir cualesquiera cargos materiales. No, no los admitirán, por la única razón de que ha encontrado el estuche y de que el hombre ha querido ahorcarse, «cosa en que no habría pensado si no hubiese sido culpable». Tal es la cuestión capital, y por esta razón me exalto. ¿Comprendes?\"},{\"heading\":false,\"text\":\"--Sí. Veo que te exaltas. Espera un poco. Hay una cosa que me había olvidado preguntarte: ¿Qué prueba que el estuche de los pendientes haya sido robado de casa de la vieja?\"},{\"heading\":false,\"text\":\"--Eso está probado--replicó entre dientes Razumikin--. Koch ha reconocido el objeto y ha indicado la persona que lo había empeñado. Por su parte, esta última persona ha demostrado evidentemente que el estuche le pertenecía.\"},{\"heading\":false,\"text\":\"--Tanto peor. Otra pregunta: ¿No ha visto nadie a Mikolai cuando Koch y Pestriakoff subían al cuarto piso, y, por consiguiente, no puede probarse la coartada?\"},{\"heading\":false,\"text\":\"--El hecho es que nadie le ha visto--respondió con tono malhumorado Razumikin--. Esto es lo que hay de malo. Ni Koch ni Pestriakoff vieron a los pintores al subir la escalera; por otra parte su testimonio no significará gran cosa. «Vimos--dicen--que el cuarto estaba abierto y que sin duda había gente trabajando en él; pero pasamos de largo sin fijarnos, y no podemos asegurar si en aquel momento había allí o no obreros.»\"},{\"heading\":false,\"text\":\"--De modo que toda la justificación de Mikolai descansa sobre la risa y puñetazos que cambiaba con su compañero. Bueno, es una prueba en apoyo de su inocencia; pero permíteme que te pregunte cómo te explicas el hecho: siendo verdadera la versión del acusado, ¿cómo te explicas el hallazgo de los pendientes?\"},{\"heading\":false,\"text\":\"--¿Que cómo me lo explico? ¿Qué hay que explicar aquí? La cosa es clara como la luz meridiana, o a lo menos así se desprende del sumario. El mismo estuche nos da la clave de lo sucedido. El verdadero culpable dejó caer los pendientes. Estaba arriba cuando Koch y Pestriakoff empujaban la puerta, y se había encerrado por dentro con el cerrojo. Koch cometió la insigne torpeza de bajar; entonces el asesino salió del cuarto y empezó a descender, supuesto que no tenía otro medio de escapar. Ya en la escalera, esquivó las miradas de Koch, de Pestriakoff y del portero, refugiándose en la habitación del segundo piso precisamente en el momento en que los obreros acababan de salir. El criminal se ocultó detrás de la puerta en tanto que el portero y los otros subían a casa de las víctimas; esperó a que el ruido de los pasos cesase de oírse y llegó tranquilamente al pie de la escalera en el instante mismo en que Mitrey y Mikolai salían corriendo a la calle. Como todo el mundo se había dispersado, no encontró a nadie en la puerta cochera. Puede que alguien le haya visto; pero nadie se fijó en él: ¿quién se fija en las personas que entran o salen de una casa? El estuche debió de caérsele del bolsillo cuando estaba detrás de la puerta, y no lo advirtió, porque tenía entonces otras muchas cosas en que pensar. El estuche demuestra claramente que el asesino se ocultó en el cuarto desalquilado del segundo piso... Ahí tienes explicado todo el misterio.\"},{\"heading\":false,\"text\":\"--¡Ingenioso, amigo mío, muy ingenioso! Ese relato hace honor a tu imaginación.\"},{\"heading\":false,\"text\":\"--Pero, ¿por qué? ¿Qué tiene que ver en esto mi imaginación? ¿Por qué dices que es ingenioso mi relato?\"},{\"heading\":false,\"text\":\"--Porque todos los detalles están muy bien calculados y todas las circunstancias se presentan con demasiada oportunidad... Ni más ni menos que en el teatro.\"},{\"heading\":false,\"text\":\"Razumikin iba a protestar de nuevo, cuando la puerta se abrió de repente y los tres jóvenes vieron aparecer un visitante a quien ninguno de los tres conocía.\"}]},{\"title\":\"segunda parte — capítulo V\",\"blocks\":[{\"heading\":false,\"text\":\"Era ya de cierta edad, majestuoso, de modales acompasados y de fisonomía reservada y severa. Se detuvo en el umbral dirigiendo miradas a todas partes con sorpresa que no trataba de disimular y que era bastante desagradable. Parecía que se preguntaba: «¿A dónde he venido a meterme?» Contemplaba la habitación estrecha y baja en que se encontraba con desconfianza y con cierta afectación de temor. Su mirada conservó la misma expresión de estupor cuando se posó sobre Raskolnikoff. El joven, con un traje bastante descuidado, estaba tendido en su miserable sofá, y sin hacer movimiento alguno se puso a su vez a contemplar al visitante. Después este último, conservando su aspecto altanero, examinó la inculta barba y los rizados cabellos de Razumikin, el cual, a su vez, sin moverse de su sitio le seguía mirando con impertinente curiosidad. Durante un minuto reinó un silencio molesto para todos. Finalmente, comprendiendo, sin duda, que su arrogancia no imponía a nadie, el buen señor se humanizó un poco, y cortésmente, aunque con cierta sequedad, se dirigió a Zosimoff.\"},{\"heading\":false,\"text\":\"--¿El señor Rodión Romanovitch Raskolnikoff, un joven que es o ha sido estudiante?--preguntó recalcando cada sílaba.\"},{\"heading\":false,\"text\":\"El médico se levantó lentamente y hubiera respondido, si Razumikin, a quien no iba dirigida la pregunta, no se hubiera apresurado a contestar.\"},{\"heading\":false,\"text\":\"--Ahí está en el sofá; ¿pero a usted qué se le ocurre?\"},{\"heading\":false,\"text\":\"El desenfado de estas palabras molestó al caballero de aspecto solemne, que hizo ademán de arrojarse sobre Razumikin, pero se contuvo y volvióse vivamente hacia Zosimoff.\"},{\"heading\":false,\"text\":\"--El señor es Raskolnikoff--dijo negligentemente el doctor, mostrando al enfermo con un ligero movimiento de cabeza.\"},{\"heading\":false,\"text\":\"Después bostezó casi hasta desquijararse, sacó del bolsillo del chaleco un enorme reloj de oro, lo miró, y lo volvió a guardar.\"},{\"heading\":false,\"text\":\"Raskolnikoff, que continuaba echado boca arriba, no apartaba los ojos del recién venido; pero ningún pensamiento reflejaba su mirada después que hubo dejado de contemplar la florecilla del papel, y su rostro, excesivamente pálido, expresó un extraordinario sufrimiento. Hubiérase dicho que el joven acababa de soportar una dolorosa operación quirúrgica o de ser sometido al tormento. Poco a poco, sin embargo, la presencia del visitante despertó en él creciente interés: primero, sorpresa; después, curiosidad, y, finalmente, cierta especie de temor. Cuando el doctor le señaló diciendo: «El señor es Raskolnikoff», nuestro héroe se levantó de repente, se sentó en el sofá, y con voz débil y entrecortada, pero que sonaba a desafío, dijo:\"},{\"heading\":false,\"text\":\"--Sí, yo soy Raskolnikoff. ¿Qué quiere usted?\"},{\"heading\":false,\"text\":\"El señor de aire importante le contempló atentamente y respondió con tono digno:\"},{\"heading\":false,\"text\":\"--Soy Pedro Petrovitch Ludjin; tengo motivo para creer que mi nombre no le es del todo desconocido.\"},{\"heading\":false,\"text\":\"Pero Raskolnikoff, que esperaba, sin duda, otra cosa, se contentó con mirar a su interlocutor silenciosamente y como si el nombre de Pedro Petrovitch hubiese sonado por primera vez en sus oídos.\"},{\"heading\":false,\"text\":\"--¿Cómo? ¿Es posible que no haya usted oído hablar de mí?--preguntó Ludjin un tanto desconcertado.\"},{\"heading\":false,\"text\":\"Por toda respuesta Raskolnikoff se echó lentamente sobre la almohada, se puso las manos bajo la cabeza y fijó los ojos en el techo. Ludjin estaba perplejo. Zosimoff y Razumikin le miraban con curiosidad cada vez mayor, lo que acabó de desconcertarle por completo.\"},{\"heading\":false,\"text\":\"--Pensaba... creía...--balbució--que una carta puesta en el correo hace ocho días o acaso quince...\"},{\"heading\":false,\"text\":\"--Oiga usted; ¿por qué permanece ahí en la puerta?--interrumpió bruscamente Razumikin--. Si tiene algo que decir, siéntese usted. Anastasia y usted no caben los dos en el hueco de la puerta. Es demasiado estrecha. Nastachiuska, apártate y deja pasar a ese señor. Entre usted. Aquí hay una silla. Vamos, venga usted.\"},{\"heading\":false,\"text\":\"Apartó su silla de la mesa, dejó un pequeño espacio libre entre ésta y sus rodillas y esperó en una posición bastante impertinente a que el visitante se le acercase. Pedro Petrovitch se deslizó no sin trabajo hasta la silla, y, después de sentarse, miró con aire de desconfianza a Razumikin.\"},{\"heading\":false,\"text\":\"--Por lo demás, no se incomode usted--dijo el estudiante con voz fuerte--. Rodia hace cinco días que se encuentra enfermo. Durante tres ha estado delirando; ahora ha recobrado el conocimiento y hasta ha comido con apetito; este señor es su médico, y yo un compañero de Rodia, antiguo estudiante como él, y hago las veces de enfermero suyo: no haga usted, pues, caso de nosotros, y hable con él como si no estuviéramos aquí.\"},{\"heading\":false,\"text\":\"--Muchas gracias. Pero mi presencia y mi conversación, ¿no fatigarán al enfermo?--preguntó Pedro Petrovitch dirigiéndose a Zosimoff.\"},{\"heading\":false,\"text\":\"--No, al contrario, así se distraerá--respondió con tono indiferente el médico y volvió a bostezar.\"},{\"heading\":false,\"text\":\"--¡Oh! Ha recobrado el uso de sus facultades hace ya un buen rato, desde esta mañana--añadió Razumikin, cuya familiaridad revelaba tan honrada franqueza, que Pedro Petrovitch comenzó a sentirse menos molesto. Además, aquel hombre incivil y mal vestido se recomendaba por su calidad de estudiante.\"},{\"heading\":false,\"text\":\"--Su madre de usted...\"},{\"heading\":false,\"text\":\"--¡Hum!--exclamó estrepitosamente Razumikin.\"},{\"heading\":false,\"text\":\"Ludjin le miró sorprendido\"},{\"heading\":false,\"text\":\"--No, no es nada, una mala costumbre mía; coutinúe usted.\"},{\"heading\":false,\"text\":\"Ludjin se encogió de hombros y prosiguió:\"},{\"heading\":false,\"text\":\"--Su madre de usted tenía empezada una carta para usted antes de mi partida. Llegado aquí, he diferido de intento mi visita algunos días, a fin de estar bien seguro de que estaba usted perfectamente enterado de todo. Pero ahora veo con asombro que...\"},{\"heading\":false,\"text\":\"--Ya sé, ya sé--interrumpió bruscamente Raskolnikoff, cuyo rostro expresó violenta irritación--. ¿Usted es el futuro...? Está bien, ya lo sé. No hablemos más de eso.\"},{\"heading\":false,\"text\":\"Este lenguaje algo grosero hirió en lo vivo a Ludjin, pero guardó silencio, preguntándose lo que aquello significaba. La conversación se interrumpió momentáneamente.\"},{\"heading\":false,\"text\":\"En tanto, Raskolnikoff, que para responderle se había vuelto un poco hacia él, se puso a contemplarle con marcada atención, como si antes no le hubiese visto o como si le hubiese chocado alguna cosa en el visitante. Se incorporó para mirarle mejor, y la verdad es que el exterior de Ludjin ofrecía no sé qué aspecto particular que justificaba el apelativo de _futuro_ tan caballerescamente aplicado poco antes a aquel personaje.\"},{\"heading\":false,\"text\":\"Desde luego se veía, y quizá se veía demasiado, que Pedro Petrovitch se había apresurado a aprovechar su estancia en San Petersburgo para «embellecerse», en previsión de la próxima llegada de su prometida. Esto, en rigor, era disculpable. Tal vez dejaba adivinar la satisfacción que sentía por haber logrado su propósito; pero también esta debilidad podía ser perdonada a un pretendiente. Iba enteramente vestido de nuevo, y su elegancia no ofrecía a la crítica más que un punto flaco: el de que la ropa estaba demasiado flamante y denunciaba un propósito determinado. ¡De qué respetuosos cuidados rodeaba el elegante sombrero que acababa de comprar! ¡qué miramientos tenía con sus guantes Jouvin, que no se había atrevido a calzarse, contentándose con tenerlos en la mano para muestra! En su traje dominaban los colores claros. Llevaba una graciosa americana de color café claro; pantalón de un color muy delicado y chaleco de la misma tela que el pantalón. La pechera, cuellos y puños eran muy pulcros y finos, y la corbata de batista a listas de color de rosa. Pedro Petrovitch, repitámoslo, presentaba buen aspecto con estos vestidos, parecía mucho más joven de lo que era en realidad.\"},{\"heading\":false,\"text\":\"Su rostro muy fresco y no desprovisto de distinción, ostentaba espesas patillas que hacían resaltar la deslumbrante blancura de una barbilla cuidadosamente afeitada. Tenía pocas canas y su peluquero había logrado rizarle el cabello sin ponerle, como casi siempre sucede, la cabeza tan ridícula como la de un desposado alemán. Si es verdad que en aquella fisonomía seria y bastante bella había algo desagradable y antipático, era por otras causas. Después de haber tratado descortésmente al señor Ludjin, Raskolnikoff sonrió burlonamente, apoyó otra vez la cabeza en la almohada y se puso a contemplar el techo. Pero el señor Ludjin había resuelto no incomodarse por nada, y fingió no reparar en lo extraño de aquel recibimiento. Hasta hizo un esfuerzo para reanudar la conversación.\"},{\"heading\":false,\"text\":\"--Siento muchísimo encontrar a usted en este estado. Si hubiera sabido que se hallaba usted enfermo, habría venido antes; pero ya sabe usted, estoy tan ocupado... Se me ha encargado de un proceso muy importante en el Senado. Esto sin contar con los preparativos y preocupaciones que usted adivinará sin duda. Aguardo de un momento a otro a su familia, es decir, a su madre de usted y a su hermana.\"},{\"heading\":false,\"text\":\"Raskolnikoff quiso decir algo. Su rostro expresó cierta agitación. Pedro Petrovitch se detuvo un instante; espero, pero viendo que el joven guardaba silencio continuó diciendo:\"},{\"heading\":false,\"text\":\"--De un momento a otro. En previsión de su próxima llegada les he buscado hospedaje...\"},{\"heading\":false,\"text\":\"--¿Dónde?--preguntó con voz débil Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Cerca de aquí, en casa de Bakalieff...\"},{\"heading\":false,\"text\":\"--Sí, en el _pereulok_ Vosnesenshy--interrumpió Razumikin--; hay dos pisos amueblados, que los alquila el comerciante Utchin. He estado allí.\"},{\"heading\":false,\"text\":\"--En efecto, en esa casa hay dos cuartos para alquilar. Es aquello un agujero innoblemente sucio y, además, de muy mala fama. Han ocurrido allí sucesos nada limpios... Ni el mismo diablo sabe la gente que la habita. Yo mismo presencié allí cierta aventura escandalosa. ¡Claro! ¡Las habitaciones esas cuestan baratas!\"},{\"heading\":false,\"text\":\"--Como usted comprenderá, yo no podía saber esas cosas, puesto que acababa de llegar de provincias--replicó Ludjin un tanto picado--. De todos modos, las dos habitaciones que he tomado están muy limpias, y como son para tan poco tiempo... Tengo ya apalabrado nuestro futuro alojamiento--añadió dirigiéndose a Raskolnikoff--. Lo están arreglando. Ahora estoy también a pupilo. Vivo a dos pasos de aquí, en casa de la señora Lippevechzel, en el departamento de un joven amigo mío, Andrés Semenitch Lebeziatnikoff, que es quien me ha indicado la casa de Bakalieff.\"},{\"heading\":false,\"text\":\"--Lebeziatnikoff--pronunció lentamente Rodia, como si este nombre le hubiese recordado alguna cosa.\"},{\"heading\":false,\"text\":\"--Sí, Andrés Semenitch Lebeziatnikoff, que es empleado en un ministerio. ¿Usted le conoce?\"},{\"heading\":false,\"text\":\"--Sí, es decir, no--respondió Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Perdone usted. Su pregunta me ha hecho suponer que no le era desconocido su nombre. Fuí en otro tiempo su tutor; es un joven muy agradable y que profesa ideas muy avanzadas. Yo trato con gusto a los jóvenes: por ellos se sabe lo que hay de nuevo.\"},{\"heading\":false,\"text\":\"Al acabar de decir estas palabras, Pedro Petrovitch miró a sus oyentes con la esperanza de encontrar en su fisonomía algún signo de aprobación.\"},{\"heading\":false,\"text\":\"--¿Desde qué punto de vista?--preguntó Razumikin.\"},{\"heading\":false,\"text\":\"--Desde un punto de vista muy serio; quiero decir, desde el punto de vista de la actividad social--respondió Ludjin encantado de que se le hiciese tal pregunta--. Yo no había estado en San Petersburgo desde hace diez años. Todas estas novedades, todas estas reformas, todas estas ideas han llegado hasta nosotros los provincianos; mas para verlo todo claramente, es preciso venir a San Petersburgo. Observando las nuevas generaciones es como se las conoce mejor. Lo confieso, estoy contentísimo.\"},{\"heading\":false,\"text\":\"--¿De qué?\"},{\"heading\":false,\"text\":\"--La pregunta de usted es complicada. Puedo engañarme, pero creo haber notado puntos de vista más concretos, un espíritu crítico, una actividad más razonada.\"},{\"heading\":false,\"text\":\"--Es verdad--dijo negligentemente Zosimoff.\"},{\"heading\":false,\"text\":\"--¿Verdad que sí?--dijo Pedro Petrovitch que recompensó al médico con una amable mirada--. Convendrá usted conmigo--prosiguió dirigiéndose a Razumikin--en que hay progreso, por lo menos en el orden científico y en el económico.\"},{\"heading\":false,\"text\":\"--¡Lugares comunes!\"},{\"heading\":false,\"text\":\"--No, no son lugares comunes. Si a mí, por ejemplo, se me dice: «Ama a tus semejantes», y pongo este consejo en práctica, ¿qué resultará?--se apresuró a responder Ludjin con demasiado calor--. Rasgaría mi capa y daría la mitad a mi prójimo, y los dos nos quedaríamos medio desnudos. Como dice el proverbio ruso: «Si levantáis muchas liebres a la vez, no cazaréis ninguna». La ciencia me ordena no amar a nadie más que a mí, supuesto que todo en el mundo está fundado en el interés personal. Si usted no ama más que a sí mismo, hará usted de un modo conveniente sus negocios y su capa quedará entera. Añade la Economía política que cuantas más fortunas privadas surgen en una sociedad, o en otros términos, cuantas más capas enteras hay, más sólida y felizmente está organizada esa sociedad. Así, pues, al trabajar únicamente para mí, trabajo también para todo el mundo; y resulta en último extremo que mi prójimo recibe un poco más de la mitad de una capa y no solamente gracias a las liberalidades privadas e individuales, sino como consecuencia del progreso general. La idea es sencilla; desgraciadamente ha necesitado mucho tiempo para hacer su camino y para triunfar de la quimera y del sueño. Sin embargo, no es preciso, me parece a mí, mucho ingenio para comprender...\"},{\"heading\":false,\"text\":\"--¡Perdón! pertenezco a la categoría de los imbéciles--interrumpió Razumikin--. No se hable más de eso. Yo tenía un objeto al empezar esta conversación; pero desde hace tres años me zumban los oídos ya con toda esta palabrería y con todas estas vulgaridades, y me da vergüenza hablar y aun oír hablar de ellas. Naturalmente, usted se ha apresurado a darnos a conocer sus teorías... Es cosa muy disculpable y no se la censuro. Solamente deseaba saber quién era usted, porque ya se le alcanza que en estos tiempos hay una porción de embaucadores que han caído sobre los negocios públicos, y, no buscando más que su propio medro, han echado a perder cuanto han tocado con sus manos... y... ¡ea, basta!\"},{\"heading\":false,\"text\":\"--¡Señor!--replicó Ludjin, herido en lo vivo--, ¿eso es decir que yo también...?\"},{\"heading\":false,\"text\":\"--¡Oh! de ninguna manera. ¿Cómo había yo de...? No se hable más--dijo Razumikin, y sin hacer caso del visitante reanudó con Zosimoff la conversación interrumpida con la llegada de Pedro Petrovitch.\"},{\"heading\":false,\"text\":\"Adoptó éste el buen acuerdo de aceptar sin protesta la explicación del estudiante. Tenía, además, la intención de irse en seguida.\"},{\"heading\":false,\"text\":\"--Ahora que ya nos conocemos--dijo, dirigiéndose a Raskolnikoff--, espero que nuestras relaciones continuarán en cuanto se ponga usted bueno del todo, y serán cada vez más íntimas, merced a las circunstancias que ya conoce... Le deseo un pronto restablecimiento.\"},{\"heading\":false,\"text\":\"Raskolnikoff hizo como si no le hubiera entendido. Pedro Petrovitch se levantó.\"},{\"heading\":false,\"text\":\"--De seguro es uno de sus deudores quien ha matado a la vieja--afirmó Zosimoff.\"},{\"heading\":false,\"text\":\"--Seguramente--repitió Razumikin--. Porfirio no dice lo que piensa, pero interroga a los que habían empeñado alhajas en casa de la usurera.\"},{\"heading\":false,\"text\":\"--¿Que los interroga?--preguntó con voz fuerte Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Sí, ¿y qué?\"},{\"heading\":false,\"text\":\"--Nada.\"},{\"heading\":false,\"text\":\"--¿Y cómo los conoce?--preguntó Zosimoff.\"},{\"heading\":false,\"text\":\"--Koch ha designado alguno; se han encontrado los nombres de otros muchos en los papeles que envolvían los objetos. En fin, otros se han presentado en cuanto han tenido noticia del hecho.\"},{\"heading\":false,\"text\":\"--El pillo que ha dado el golpe debe de ser un mozo experimentado. ¡Qué decisión, que audacia!\"},{\"heading\":false,\"text\":\"--No hay tal cosa--replicó Razumikin--. Eso es precisamente lo que te engaña y lo que engaña a todos. Sostengo que el asesino no es ni hábil ni experimentado; ese crimen ha sido probablemente el primero que ha cometido. En la hipótesis de que el criminal fuese un asesino consumado nada explicaría todo un cúmulo de inverosimilitudes... Si, por el contrario, le suponemos novato, habrá que admitir que la casualidad solamente ha sido causa de que pudiera escapar. ¿Quién sabe? Quizá ni ha previsto los obstáculos. ¿Cómo lleva a cabo su empresa? Asesina a dos personas, toma luego alhajas de diez o veinte rublos, y se llena con ellas los bolsillos; revuelve el cofre en que la vieja guardaba sus trapos, no toca el cajón de la cómoda en donde se ha encontrado una cajita que contenía mil quinientos rublos en metálico sin contar los billetes. No, no ha sabido robar, sólo ha sabido matar. Lo repito, es principiante; se aturdió en el momento de cometer el crimen. Si no le han detenido ya, debe dar más gracias al azar que a su destreza.\"},{\"heading\":false,\"text\":\"Pedro Petrovitch iba ya a marcharse, pero antes de salir quiso pronunciar algunas frases profundas. Deseaba dejar buena impresión, y la vanidad le privó de tacto.\"},{\"heading\":false,\"text\":\"--¿Hablan ustedes, sin duda, del asesinato recientemente perpetrado en la persona de una anciana, viuda de un secretario de colegio?--preguntó dirigiéndose a Zosimoff.\"},{\"heading\":false,\"text\":\"--Sí. ¿Usted ha oído hablar de ese crimen?\"},{\"heading\":false,\"text\":\"--¿Cómo no? Si se habla de él en todas partes.\"},{\"heading\":false,\"text\":\"--¿Conoce usted los pormenores?\"},{\"heading\":false,\"text\":\"--No todos; pero este asunto me interesa por la cuestión de carácter general que plantea. No me refiero al aumento de crímenes en la clase baja durante estos cinco últimos años; dejo a un lado la sucesión no interrumpida de robos y de incendios. Lo que más me preocupa es que en las clases elevadas la criminalidad sigue una progresión en cierto modo paralela.\"},{\"heading\":false,\"text\":\"--Pero, ¿de qué se preocupa usted?--dijo bruscamente Raskolnikoff--. Todo eso es el resultado práctico de la teoría de ustedes.\"},{\"heading\":false,\"text\":\"--¿Cómo de nuestra teoría?\"},{\"heading\":false,\"text\":\"--Es la deducción lógica del principio que usted acaba de sentar. Según usted, es lícito matar al prójimo.\"},{\"heading\":false,\"text\":\"--¿Cómo? ¡Yo!--exclamó Ludjin.\"},{\"heading\":false,\"text\":\"--No, no es eso--observó Zosimoff.\"},{\"heading\":false,\"text\":\"Raskolnikoff se puso pálido y respiraba fatigosamente; cierto estremecimiento agitaba su labio superior.\"},{\"heading\":false,\"text\":\"--Todo consiste en los justos medios--prosiguió con tono altanero Pedro Petrovitch--; la idea económica no es aún, que yo sepa, una excitación al asesinato, y de lo que yo he expuesto al principio...\"},{\"heading\":false,\"text\":\"--¿Es verdad--saltó Raskolnikoff con voz temblorosa de cólera--, es verdad que usted dijo a su futura esposa... cuando aceptó la petición de usted, que lo que más le agradaba de ella era su pobreza... porque es mejor casarse con una mujer para dominarla y echarle en cara los beneficios de que se ha colmado?\"},{\"heading\":false,\"text\":\"--¡Caballero!--exclamó Ludjin--, rugiendo de furor--. ¡Caballero! ¡Eso es desnaturalizar mi pensamiento! Dispense usted que le diga que los rumores que han llegado a su conocimiento, o mejor dicho, que han sido puestos en su conocimiento, no tienen ni sombra de fundamento y sospecho que... en una palabra... Ese dardo... en una palabra, que su madre de usted... Ya me había parecido a mí, que, a pesar de sus buenas cualidades, era un poco exaltada y novelesca; sin embargo, estaba a mil leguas de imaginar que pudiese desnaturalizar hasta ese punto el sentido de mis palabras y citarlas alterándolas de tal suerte... En fin...\"},{\"heading\":false,\"text\":\"--¿Sabe usted lo que le digo?--gritó el joven incorporándose y echando lumbre por los ojos--. ¿Sabe usted lo que le digo?\"},{\"heading\":false,\"text\":\"--¿Qué?\"},{\"heading\":false,\"text\":\"Y al decir esta palabra se detuvo Ludjin y esperó con aire de desafío.\"},{\"heading\":false,\"text\":\"Hubo algunos momentos de silencio.\"},{\"heading\":false,\"text\":\"--Pues bien, que si usted se permite decir una sola palabra más de mi madre, le tiro de cabeza por la ventana.\"},{\"heading\":false,\"text\":\"--¿Qué te pasa? ¿Qué arrebato es ése?--exclamó Razumikin.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡Lo haré como lo digo!\"},{\"heading\":false,\"text\":\"Ludjin palideció y se mordió los labios. Se ahogaba de rabia, aunque hacía esfuerzos inauditos para contenerse.\"},{\"heading\":false,\"text\":\"--Escuche usted, caballero--dijo después de una pausa--. La manera como usted me recibió cuando entré, no me dejó ninguna duda acerca de su enemistad; sin embargo, he prolongado mi visita por exceso de cortesía. Hubiera podido perdonar a un enfermo y a un pariente, pero ahora... ¡jamás! ¡jamás!\"},{\"heading\":false,\"text\":\"--¡Yo no estoy enfermo!--gritó Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¡Tanto peor!\"},{\"heading\":false,\"text\":\"--¡Váyase usted al infierno!\"},{\"heading\":false,\"text\":\"Pero Ludjin no tuvo necesidad de esta invitación para marcharse. Se apresuró a salir sin mirar a nadie y sin saludar a Zosimoff, que durante un rato estuvo haciéndole señas de que dejase en reposo al enfermo.\"},{\"heading\":false,\"text\":\"--¿Ese es el modo de portarse?--dijo Razumikin, moviendo la cabeza.\"},{\"heading\":false,\"text\":\"--¡Dejadme! ¡Dejadme todos!--exclamó colérico Raskolnikoff--. ¿Me dejaréis en paz, verdugos? ¡No tengo miedo de vosotros! ¡No temo a nadie, a nadie! Ahora, marchaos. ¡Quiero estar solo, solo, solo!\"},{\"heading\":false,\"text\":\"--Vámonos--dijo Zosimoff haciendo una seña con la cabeza a Razumikin.\"},{\"heading\":false,\"text\":\"--Pero, ¿le vamos a dejar así?\"},{\"heading\":false,\"text\":\"--¡Vámonos!--insistió el médico.\"},{\"heading\":false,\"text\":\"Razumikin reflexionó un instante y se decidió a seguir al doctor, que ya había salido.\"},{\"heading\":false,\"text\":\"--Nuestra resistencia a sus deseos le hubiera sido perjudicial--dijo Zosimoff a su amigo ya en la escalera--. No conviene irritarle.\"},{\"heading\":false,\"text\":\"--¿Qué le pasa?\"},{\"heading\":false,\"text\":\"--Una sacudida que le sacase de sus preocupaciones le haría mucho provecho. Alguna idea fija le atormenta... Eso es lo que más me inquieta.\"},{\"heading\":false,\"text\":\"--El señor Pedro Petrovitch, ¿tendrá algo que ver en esto? Según la conversación que acaban de sostener, parece que ese individuo va a casarle con una hermana de Rodia, y que nuestro amigo ha recibido una carta acerca de este asunto muy pocos días antes de su enfermedad.\"},{\"heading\":false,\"text\":\"--El diablo, sin duda, es quien ha traído de visita a ese señor, que ha podido echarlo todo a perder. Pero, ¿has reparado en que sólo una cosa hace salir al enfermo de su apatía y mutismo? ¡Cómo se excita cuando se habla de ese asesinato!\"},{\"heading\":false,\"text\":\"--Sí, sí, lo he advertido--respondió Razumikin--; presta más atención, se inquieta. Es, sin duda, porque el mismo día que se puso malo le asustaron en la oficina de policía y se desmayó.\"},{\"heading\":false,\"text\":\"--Ya me lo contarás circunstanciadamente en otra ocasión, y a mi vez te diré algo... Me interesa mucho, muchísimo. Dentro de media hora volveré a ver cómo sigue. No es de temer le inflamación...\"},{\"heading\":false,\"text\":\"--Gracias a ti. Ahora voy a entrar un momento en casa de Pashenka, y haré que le cuide Anastasia.\"},{\"heading\":false,\"text\":\"Cuando se quedó solo, Raskolnikoff miró a la criada con impaciencia y disgusto; pero ésta vacilaba antes de irse.\"},{\"heading\":false,\"text\":\"--¿Tomarás ahora el te?--preguntóle la sirvienta.\"},{\"heading\":false,\"text\":\"--Más tarde; quiero dormir. Déjame.\"},{\"heading\":false,\"text\":\"El joven se volvió con un movimiento convulsivo hacia la pared, y la criada salió del aposento.\"}]},{\"title\":\"segunda parte — capítulo VI\",\"blocks\":[{\"heading\":false,\"text\":\"Pero en cuanto la criada hubo salido, Raskolnikoff se levantó, cerró la puerta con el picaporte y se puso las prendas que Razumikin le había llevado. Cosa extraña. De repente se trocó en tranquilidad completa el frenesí de antes y el terror pánico que el joven había sentido en los últimos días. Era aquel el primer momento de una tranquilidad extraña y repentina. Precisos y sin vacilación los movimientos del joven, denotaban una resolución enérgica. «Hoy mismo, hoy mismo», murmuraba. Comprendía, sin embargo, que estaba aún débil; pero la extrema tensión moral a que debía su calma, le daban seguridad y confianza; no quería caerse en la calle. Después de haberse vestido por completo, miró el dinero colocado sobre la mesa, reflexionó un poco y se lo metió en el bolsillo.\"},{\"heading\":false,\"text\":\"La cantidad subía a veinticinco rublos. Tomó también todas las monedas de cobre que quedaban de los diez rublos gastados por Razumikin, abrió suavemente la puerta, salió de su habitación y bajó la escalera. Al pasar por delante de la cocina, cuya puerta estaba abierta de par en par, echó una ojeada. Anastasia estaba vuelta de espaldas, ocupada en soplar el samovar de la patrona y no le vió. Por otra parte, ¿quién hubiera podido prever esta fuga? Un instante después estaba en la calle.\"},{\"heading\":false,\"text\":\"Eran las ocho y se había puesto el sol. Aunque la atmósfera era sofocante como el día anterior, Raskolnikoff respiraba con avidez el aire polvoriento emponzoñado por las exhalaciones mefíticas de la gran ciudad. Sentía algunos ligeros vahídos; sus ojos inflamados, su rostro delgado y lívido expresaban salvaje energía. No sabía dónde ir ni tampoco le preocupaba; sabía solamente que era preciso acabar con «aquella historia»; pero de repente y en seguida; que de otro modo no entraría en su casa. «Porque no quería vivir así.» ¿Cómo acabar? No lo sabía y hacía esfuerzos para desechar esta pregunta que le atormentaba. Sólo comprendía que era menester cambiase todo de una manera o de otra, «cueste lo que cueste», repetía con desesperada resolución.\"},{\"heading\":false,\"text\":\"Siguiendo una antigua costumbre se dirigió al Mercado del Heno. Antes de llegar vió en la calzada, frente a una tiendecilla, a un organillero joven, de cabellos negros, que tocaba una melodía muy sentimental. El músico acompañaba con su instrumento a una joven de quince años, que estaba de pie en la acera. La muchacha, vestida como una señorita, llevaba crinolina, manteleta, guantes, chal y sombrero de paja, adornado con una pluma encarnada, todo viejo y arrugado. Con voz cascada, pero bastante fuerte y agradable, cantaba una romanza, esperando que en la tienda le diesen un par de kopeks. Dos o tres personas se habían detenido; Raskolnikoff hizo como ellas, y después de haber escuchado un momento, sacó del bolsillo un piatak y lo puso en la mano de la joven. La muchacha cortó en seco su canto en la nota más alta y conmovedora--. ¡Basta!--gritó la cantora a su compañero y ambos se dirigieron a la tienda de al lado.\"},{\"heading\":false,\"text\":\"--¿Le gustan a usted las canciones de las calles?--preguntó bruscamente Raskolnikoff a un transeunte, ya de cierta edad, que había estado oyendo a su lado a los músicos callejeros y que parecía un paseante desocupado.\"},{\"heading\":false,\"text\":\"El interrogado miró con sorpresa al que le dirigía esta pregunta.\"},{\"heading\":false,\"text\":\"--Yo--prosiguió Raskolnikoff (al verle se hubiera creído que hablaba de otra cosa que de la música de las calles)--, yo gusto de oír cantar al compás del organillo, sobre todo en una tarde fría, sombría y húmeda de otoño, principalmente húmeda, cuando todos los transeuntes tienen cara verdosa o enfermiza, o mejor aún, cuando la nieve cae verticalmente, sin que el viento le desparrame y cuando las luces brillan al través de las nubes...\"},{\"heading\":false,\"text\":\"--Yo no sé. Usted me dispense--balbuceó el señor, aterrado de la pregunta y del extraño aspecto de Raskolnikoff y se pasó a la otra acera.\"},{\"heading\":false,\"text\":\"El joven continuó su camino y llegó al Mercado del Heno, al sitio mismo en que días antes cierto tendero y su mujer hablaban con Isabel; pero no estaban allí. Reconociendo el lugar, se detuvo, miró en derredor suyo y se dirigió a un mozo de camisa roja que bostezaba a la puerta de un almacén de harinas.\"},{\"heading\":false,\"text\":\"--¿Es aquí en este rincón, donde cierto tendero y su mujer se ponen a vender?\"},{\"heading\":false,\"text\":\"--Todo el mundo vende--respondió el mozo, mirando con desdén a Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¿Cómo le llaman?\"},{\"heading\":false,\"text\":\"--Le llaman por su nombre.\"},{\"heading\":false,\"text\":\"--Tú no eres de Zaraisk. ¿De qué provincia eres?\"},{\"heading\":false,\"text\":\"El mozo miró de nuevo a su interlocutor.\"},{\"heading\":false,\"text\":\"--Alteza, nosotros no somos de una provincia, sino de un distrito. Mi hermano ha partido, y yo me he quedado en la casa, de manera que no sé nada. Perdóneme Vuestra Alteza.\"},{\"heading\":false,\"text\":\"--¿Hay arriba un bodegón?\"},{\"heading\":false,\"text\":\"--Es un _traktir_ y un billar. Hasta princesas van ahí... se ve muy favorecido.\"},{\"heading\":false,\"text\":\"Raskolnikoff se dirigió a otro ángulo de la plaza, en donde había un grupo compacto, exclusivamente compuesto de _mujiks_. Se metió entre la gente, mirando a todas las personas y deseoso de hablar con todo el mundo. Pero los campesinos no fijaban la atención en él, y formando grupos pequeños hablaban en voz alta de sus asuntos. Después de un momento de reflexión, dejó el Mercado del Heno y se entró en el _pereulok_.\"},{\"heading\":false,\"text\":\"En otras varias ocasiones había pasado por esta callejuela, que forma un recodo y une el mercado con la Sadovia. Desde hace algún tiempo, gustábale ir a pasear por aquellos sitios, cuando comenzaba a aburrirse... «a fin de aburrirse todavía más». Ahora iba allí sin propósito algo determinado. Se encuentra en esta callejuela una gran casa, cuya planta baja está ocupada por tabernas y figones de los que salían continuamente mujeres, sin nada a la cabeza y descuidadamente vestidas. Se agrupaban en dos o tres sitios de la acera, principalmente cerca de las escaleras por las que se baja a una especie de cafetines de mala fama. En uno de ellos, sonaba alegre estrépito: cantaban dentro, tocaban la guitarra y el ruido se extendía de un extremo a otro de la calle. La mayor parte de las mujeres se habían reunido en la puerta de aquel antro; unas estaban sentadas en las escaleras, las otras en la acera, las otras, en fin, hablaban en pie. Un soldado borracho, con el cigarrillo en la boca, golpeaba el suelo profiriendo imprecaciones: hubiérase dicho que quería entrar en alguna parte, pero que no sabía dónde. Dos individuos desharrapados se insultaban. Un hombre completamente ebrio yacía tirado, cuan largo era, en medio de la calle. Raskolnikoff se detuvo cerca del principal grupo de mujeres. Hablaban a voces, todas llevaban vestidos de indiana, calzado de piel de cabra y la cabeza descubierta. Muchas habían pasado ya de los cuarenta años; otras no representaban más de diez y siete. Casi todas tenían amoratadas las orejas.\"},{\"heading\":false,\"text\":\"Los cantos y el ruido que salían de la zahurda, llamaron la atención de Raskolnikoff. En medio de las carcajadas y del barullo, una agria voz de falsete cantaba al son de una guitarra y una persona danzaba furiosamente marcando el compás con los tacones. El joven, inclinado hacia la entrada de la escalera, escuchaba sombrío y pensativo.\"},{\"heading\":false,\"text\":\"_Hombrecito de mi alma_ _No me pegues sin razón._\"},{\"heading\":false,\"text\":\"cantaba la voz de falsete. Raskolnikoff no hubiera querido perder palabra de aquella canción, como si el oírla hubiese sido para él cosa de grandísima importancia.\"},{\"heading\":false,\"text\":\"«Si entrase...»--pensaba--. «Se ríen, están borrachos.»\"},{\"heading\":false,\"text\":\"--¿No entras, buen mozo?--le preguntó una de las mujeres con voz bastante bien timbrada y que conservaba aún cierta frescura.\"},{\"heading\":false,\"text\":\"Era una muchacha joven, y la única en el grupo que no daba náuseas.\"},{\"heading\":false,\"text\":\"--¡Oh, bonita muchacha!--respondió el joven levantando la cabeza y mirándola.\"},{\"heading\":false,\"text\":\"Sonrióse la moza, lisonjeada con el requiebro.\"},{\"heading\":false,\"text\":\"--También tú eres muy guapo.\"},{\"heading\":false,\"text\":\"--¡Guapo un tipo semejante!--gruñó en voz baja otra mujer--; de seguro que acaba de salir del hospital.\"},{\"heading\":false,\"text\":\"Bruscamente se aproximó un _mujik_, medio ebrio, con el capote desabrochado y el rostro resplandeciente de maliciosa alegría.\"},{\"heading\":false,\"text\":\"--Parece que son hijas de generales, lo que no les impide ser chatas--dijo el _mujik_--. ¡Oh, qué hermosuras!\"},{\"heading\":false,\"text\":\"--Entra, puesto que has venido.\"},{\"heading\":false,\"text\":\"--Entraré, preciosa--y descendió al cafetín.\"},{\"heading\":false,\"text\":\"Raskolnikoff hizo ademán de alejarse.\"},{\"heading\":false,\"text\":\"--Escuche usted, _barin_[15]--le gritó la joven cuando nuestro héroe volvía ya la espalda.\"},{\"heading\":false,\"text\":\"[15] Señor.\"},{\"heading\":false,\"text\":\"--¿Qué?\"},{\"heading\":false,\"text\":\"--Querido _barin_, tendré mucho gusto en pasar una hora con usted; pero en este momento me siento cortada en su presencia. Déme seis kopeks para echar un trago, amable caballero.\"},{\"heading\":false,\"text\":\"Raskolnikoff buscó en el bolsillo y sacó tres piataks.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡Qué bueno es usted!\"},{\"heading\":false,\"text\":\"--¿Cómo te llamas?\"},{\"heading\":false,\"text\":\"--Pregunte usted por Duklida.\"},{\"heading\":false,\"text\":\"--¡Qué desfachatez!--dijo bruscamente una de las mujeres que se encontraban en el grupo, señalando a Duklida, con un movimiento de cabeza--. ¡No sé cómo hay personas que pidan de ese modo! Yo no me atrevería jamás... Creo que antes me moriría de vergüenza.\"},{\"heading\":false,\"text\":\"Raskolnikoff sintió curiosidad por ver a la mujer que hablaba de aquel modo. Era una moza de treinta años, toda llena de equimosis y el labio superior hinchado. Había lanzado su sentencia con toda calma y seriedad.\"},{\"heading\":false,\"text\":\"«¿En dónde he leído yo--pensaba Raskolnikoff alejándose--, que se concede no sé qué a un condenado a muerte una hora antes de su ejecución? Aunque él tuviese que vivir sobre una cima escarpada, en una roca perdida en medio del Océano, donde no hubiese más que el sitio suficiente para colocar los pies, aunque tuviese que pasar así toda su existencia, mil años... una eternidad, derecho en el espacio de un pie cuadrado, solo en las tinieblas, expuesto a todas las intemperies... preferiría aquella vida a la muerte. Vivir, no importa cómo, pero vivir. ¡Qué verdad es, Dios mío, qué verdad es! ¡Qué cobarde es el hombre y qué cobarde también aquel que por ello le llama cobarde!»--añadió al cabo de un instante.\"},{\"heading\":false,\"text\":\"Hacía largo tiempo que andaba al azar, cuando le llamó la atención la muestra de un café: «¡Hola! _El Palacio de Cristal_. Poco ha me habló de él Razumikin. Pero, ¿qué es lo que yo quiero hacer aquí? ¡Ah! Sí, leer. Zosimoff dice que había leído en los periódicos...»\"},{\"heading\":false,\"text\":\"--¿Tienen ustedes periódicos?--preguntó entrando en un salón muy espacioso y bastante bien decorado, donde había poca gente.\"},{\"heading\":false,\"text\":\"Dos o tres parroquianos tomaban te. En una sala distante, cuatro personas, sentadas a una mesa, bebían _Champagne_. Raskolnikoff creyó reconocer entre ellos a Zametoff, pero la distancia no le permitía distinguirlo bien.\"},{\"heading\":false,\"text\":\"«Después de todo, ¿qué me importa?» se dijo.\"},{\"heading\":false,\"text\":\"--¿Quiere usted aguardiente?--preguntó el mozo.\"},{\"heading\":false,\"text\":\"--Sírveme te y tráeme también los periódicos, los de los últimos cinco días, te daré buena propina.\"},{\"heading\":false,\"text\":\"--Bueno, aquí tiene usted los de hoy. ¿Quiere usted también aguardiente?\"},{\"heading\":false,\"text\":\"Cuando le sirvieron el te y le dieron los periódicos, Raskolnikoff se puso a buscar.\"},{\"heading\":false,\"text\":\"--Izler. Izler. Los Aztekas. Los Aztekas. Bartola. Máximo. Los Aztekas. Izler... ¡Oh, qué lío! ¡Ah! Aquí están los sucesos: una mujer se ha caído por una escalera... Un comerciante trastornado por el vino. El incendio de las Arenas. El incendio de la Petersburgskaia. Otra vez el incendio de la Petersburgskaia. Izler. Izler. Izler. Izler. Máximo... ¡Ah! Aquí está.\"},{\"heading\":false,\"text\":\"Cuando encontró lo que buscaba, comenzó la lectura; danzaban las letras delante de sus ojos. Pudo, sin embargo, leer «los sucesos» hasta el fin y se puso a buscar ávidamente los «nuevos detalles» en los otros números.\"},{\"heading\":false,\"text\":\"Impaciencia febril le hacía temblar las manos conforme ojeaba los periódicos. De repente se sentó a su lado uno. Raskolnikoff miró. Era Zametoff. Zametoff en persona y con el mismo traje que llevaba en el despacho de policía con sus sortijas, sus cadenas, los negros cabellos rizados y llenos de cosmético, separados elegantemente en medio de la cabeza, con su elegante chaleco, su levita algo usada y algo arrugada la camisa.\"},{\"heading\":false,\"text\":\"El jefe de la Cancillería estaba alegre; por lo menos se sonreía con satisfacción y franqueza. Por efecto del _Champagne_ que había bebido, tenía el moreno rostro bastante enrojecido.\"},{\"heading\":false,\"text\":\"--¡Cómo! ¿Usted aquí?--exclamó con asombro y con el tono que hubiera usado para saludar a un antiguo camarada--. ¡Si ayer mismo Razumikin me dijo que seguía usted sin conocimiento!... Es extraño. He estado en su casa...\"},{\"heading\":false,\"text\":\"Raskolnikoff no creía que el jefe de la Cancillería vendría a hablar con él. Apartó los periódicos y se volvió hacia Zametoff con una sonrisa por la cual se transparentaba viva irritación.\"},{\"heading\":false,\"text\":\"--Me han hablado de su visita--contestó--; usted buscó mi bota. Razumikin está loco con usted. Han ido ustedes juntos, según parece, a casa de Luisa Ivanovna, a quien usted trató de defender el otro día. ¿No se acuerda? Usted hacía señas al ayudante _Pólvora_, y él no hacía caso de sus guiños. Sin embargo, no era necesaria mucha penetración para comprenderlos. La cosa es clara, ¿eh?\"},{\"heading\":false,\"text\":\"--Es más charlatán...\"},{\"heading\":false,\"text\":\"--¿Quién? _¿Pólvora?_\"},{\"heading\":false,\"text\":\"--No, Razumikin...\"},{\"heading\":false,\"text\":\"--Pero usted se lleva la mejor vida, señor Zametoff. Tiene usted entrada gratuita en lugares encantadores. ¿Quién le ha regalado a usted el _Champagne_?\"},{\"heading\":false,\"text\":\"--¿Por qué me lo habían de regalar?\"},{\"heading\":false,\"text\":\"--A título de honorarios. Usted saca partido de todo--dijo con sorna Raskolnikoff--. No se incomode usted, querido amigo--añadió dando un golpecito en el hombro a Zametoff--. Lo que le digo a usted es sin malicia, en broma, como decía, a propósito de los puñetazos dados por él a Mitka, el obrero detenido por el asunto de la vieja.\"},{\"heading\":false,\"text\":\"--Pero, ¿usted cómo sabe eso?\"},{\"heading\":false,\"text\":\"--Lo sé quizá mejor que usted.\"},{\"heading\":false,\"text\":\"--¡Qué original es usted!... Verdaderamente está algo enfermo. Ha hecho mal en salir...\"},{\"heading\":false,\"text\":\"--¿Me encuentra usted raro?\"},{\"heading\":false,\"text\":\"--Sí. ¿Qué es lo que usted leía?\"},{\"heading\":false,\"text\":\"--Periódicos.\"},{\"heading\":false,\"text\":\"--Ha habido estos días muchos incendios.\"},{\"heading\":false,\"text\":\"--No me importan los incendios--repuso Raskolnikoff mirando a Zametoff con aire singular y con sonrisa burlona--. No, no son los incendios lo que me interesa--continuó guiñando los ojos--. Pero confiese usted, querido joven, que tiene grandes deseos de saber lo que yo leía.\"},{\"heading\":false,\"text\":\"--No, no tengo ninguno; se lo preguntaba a usted por decir algo. ¿Es que no le puedo preguntar a usted...? Porque siempre...\"},{\"heading\":false,\"text\":\"--Escuche. Usted es un hombre instruído, letrado, ¿no es cierto?\"},{\"heading\":false,\"text\":\"--He seguido mis estudios en el Gimnasio hasta el sexto curso inclusive--respondió con cierto orgullo Zametoff.\"},{\"heading\":false,\"text\":\"--Hasta el sexto curso. ¡Ah, pícaro! Tiene buena raya y sortijas. Es un hombre rico y muy guapo.\"},{\"heading\":false,\"text\":\"Al decir esto, Raskolnikoff se echó a reír en las barbas mismas de su interlocutor. Este se retiró un poco; no ofendido, precisamente, pero sí sorprendido.\"},{\"heading\":false,\"text\":\"--¡Qué original es usted!--repitió con tono muy serio Zametoff--. Me parece que sigue usted delirando.\"},{\"heading\":false,\"text\":\"--¿Que deliro? Te burlas, amiguito... ¿Conque soy original, eh? Es decir que parezco un bicho raro, ¿eh? raro, ¿verdad? ¿Que excito la curiosidad?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Usted deseaba saber lo que leía, lo que buscaba en los periódicos? Vea usted cuántos números me han traído. Esto da mucho en que pensar, ¿no es eso?\"},{\"heading\":false,\"text\":\"--Vamos, diga usted.\"},{\"heading\":false,\"text\":\"--Usted cree haber levantado la liebre.\"},{\"heading\":false,\"text\":\"--¿Qué liebre?\"},{\"heading\":false,\"text\":\"--Luego se lo diré a usted; ahora, querido amigo, le declaro... o más bien, «confieso»... no, no es eso: presto una declaración y usted toma nota de ella. Pues bien, yo declaro que he leído, que tenía curiosidad de leer, que he buscado y que he encontrado.... (Raskolnikoff guiñó los ojos y esperó), por eso he venido aquí para saber los detalles relativos al asesinato de la vieja prestamista.\"},{\"heading\":false,\"text\":\"Al pronunciar estas palabras bajó la voz y arrimó la cara a la de Zametoff. Este le miró fijamente sin pestañear y sin apartar la cabeza. Al jefe de la Cancillería le pareció muy extraño que durante un minuto se estuviesen mirando sin decir palabra.\"},{\"heading\":false,\"text\":\"--¿Sabe usted?--continuó en voz baja Raskolnikoff sin hacer caso de la exclamación de Zametoff--se trata de aquella misma vieja de la cual se hablaba en el despacho de policía cuando yo me desmayé. ¿Comprende usted ahora?\"},{\"heading\":false,\"text\":\"--¿Qué quiere decir con eso de comprende usted?--dijo Zametoff casi asustado.\"},{\"heading\":false,\"text\":\"El rostro inmóvil y serio de Raskolnikoff cambió repentinamente de expresión y se echó a reír de un modo nervioso como si no pudiera contenerse. Experimentaba idéntica sensación que el día del asesinato cuando, sitiado en el cuarto de sus víctimas por Koch y Pestriakoff, le había dado ganas de insultarlos, provocarlos y reírse de ellos en sus propias barbas.\"},{\"heading\":false,\"text\":\"--O usted está loco, o...--comenzó a decir Zametoff y se detuvo como si cruzara por su mente una idea repentina.\"},{\"heading\":false,\"text\":\"--O ¿qué? ¿qué iba usted a decir? Acabe la frase.\"},{\"heading\":false,\"text\":\"--No--replicó Zametoff--; todo eso es absurdo.\"},{\"heading\":false,\"text\":\"Ambos guardaron silencio. Después de un súbito acceso de hilaridad, Raskolnikoff se quedó sombrío y pensativo.\"},{\"heading\":false,\"text\":\"De codos en la mesa, con la cabeza entre las manos, parecía haber olvidado por completo la presencia de Zametoff.\"},{\"heading\":false,\"text\":\"--¿Por qué no toma usted el te?--dijo, al fin éste--. Va a enfriarse.\"},{\"heading\":false,\"text\":\"--¿Qué?... ¿el te?... Bueno.\"},{\"heading\":false,\"text\":\"Raskolnikoff se llevó la taza a los labios, comió un bocado de pan, y fijando los ojos en Zametoff recobró su fisonomía la expresión burlona que tenía antes y continuó tomando el te.\"},{\"heading\":false,\"text\":\"--Los delitos de todo género son ahora muy numerosos--apuntó Zametoff--. Precisamente hace poco leí en la _Moskovskia Viedomosti_ que había sido detenida en Moscou una cuadrilla de monederos falsos, toda una sociedad que se dedicaba a la fabricación y expendición de billetes del Banco.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡Eso es ya viejo! ¡Hace un mes que lo he leído!--respondió flemáticamente Raskolnikoff--. ¿De modo que usted supone que son estafadores?\"},{\"heading\":false,\"text\":\"--¿Cómo? ¿Cree usted que no lo son?\"},{\"heading\":false,\"text\":\"--¿Ellos? Chiquillos, novatos infelices, y no estafadores. ¡Se reunen cincuenta para ese objeto! ¿A quién se le ocurre? En semejante caso, tres son ya mucho, y aun es menester que cada miembro de la asociación esté más seguro de sus asociados que de sí mismo. Basta que a uno de ellos un poco bebido se le escape una palabra, y todo se derrumba. ¡Son novatos! Envían a personas de las cuales no pueden responder a cambiar sus billetes en las casas de banca. ¿Es discreto encargar al primero que se presenta de una comisión semejante? Supongamos que, a pesar de todo, hayan conseguido su propósito; supongamos que el negocio ha producido un millón a cada uno de ellos. Helos durante toda la vida en dependencia los unos de los otros. Mejor es ahorcarse que vivir así. Pero no han sabido representar su papel: uno de sus agentes se presenta a este efecto en una oficina, se le entregan cinco mil rublos y sus manos tiemblan. Cuenta los cuatro primeros miles, el quinto lo guarda sin recontarlo; tanto deseo tenía de escapar. De este modo, despierta sospechas y todo el negocio se echa a perder por la falta de un solo imbécil. Esto es verdaderamente inconcebible.\"},{\"heading\":false,\"text\":\"--¿Que le tiemblan las manos?--replicó Zametoff--. Pues me parece muy natural. En ciertos casos, no es uno dueño de sí mismo. Ahí tiene usted, sin ir más lejos, una prueba reciente. El asesino de esa vieja debe ser un bribón muy resuelto para no haber vacilado en cometer su crimen en pleno día y en las condiciones más peligrosas. Milagro es que ya no esté preso. Pues bien, a pesar de esto, sus manos temblaban: no ha sabido robar: le ha faltado la serenidad, como los hechos demuestran claramente.\"},{\"heading\":false,\"text\":\"Aquel lenguaje hirió en lo más vivo a Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¿Usted cree? Pues bien, échele usted el guante, descúbralo usted ahora--exclamó el joven experimentando maligno placer al mortificar al jefe de la Cancillería.\"},{\"heading\":false,\"text\":\"--No tenga usted cuidado, se le descubrirá.\"},{\"heading\":false,\"text\":\"--¿Quién? ¿Usted? ¿Usted va a descubrirle? Perderá usted el tiempo y el trabajo. Para ustedes toda la cuestión es saber si un hombre hace o no hace gastos. Uno que no poseía nada tira el dinero por la ventana; luego es culpable. Ajustándose a esta regla, un chiquillo, si quisiese, escaparía a las investigaciones de ustedes.\"},{\"heading\":false,\"text\":\"--El hecho es que todos se conducen del mismo modo--respondió Zametoff--. Después de haber desplegado a menudo mucha habilidad y astucia en la perpetración del asesinato, se dejan pescar en la taberna. Los denuncian sus gastos, no son tan astutos como usted. Usted, es claro, no iría a la taberna.\"},{\"heading\":false,\"text\":\"Raskolnikoff frunció las cejas y miró fijamente a Zametoff.\"},{\"heading\":false,\"text\":\"--¿Usted quiere saber cómo obraría yo, en caso semejante?--preguntó con tono malhumorado.\"},{\"heading\":false,\"text\":\"--Sí--replicó con energía el jefe de la Cancillería.\"},{\"heading\":false,\"text\":\"--¿Tiene usted mucho empeño?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--Pues bien, he aquí lo que yo haría--comenzó a decir Raskolnikoff, bajando de repente la voz y aproximando de nuevo la cara a la de su interlocutor, a quien miró fijamente. Por esta vez no pudo menos de temblar--. He aquí lo que haría yo. Tomaría el dinero y las joyas, y después, al salir de la casa, iría, sin un minuto de retraso, a un paraje cerrado y solitario, a un corral o un huerto, por ejemplo. Me aseguraría antes de que en un rincón de este corral, al lado de una valla, hubiese una piedra de cuarenta o sesenta libras de peso, levantaría esta piedra, bajo la cual el suelo debía de estar deprimido, y depositaría en el hueco el dinero y las alhajas. Hecho esto volvería a poner la piedra y me iría. Durante uno, dos, o tres años, dejaría allí los objetos robados, y ya podrían ustedes buscarlos.\"},{\"heading\":false,\"text\":\"--Usted está loco--respondió Zametoff.\"},{\"heading\":false,\"text\":\"Sin que podamos decir por qué, pronunció estas palabras en voz baja y se apartó bruscamente de Raskolnikoff. Los ojos de éste relampagueaban. Había palidecido de un modo horrible y un temblor convulsivo agitaba su labio superior. Se inclinó lo más posible hacia el rostro del funcionario y se puso a mover los labios sin proferir una sola palabra. Así pasó medio minuto. Nuestro héroe no se daba cuenta de lo que hacía, pero no podía contenerse. Estaba a punto de escapársele su espantosa confesión.\"},{\"heading\":false,\"text\":\"--¿Y si fuese yo el asesino de la vieja y de Isabel?--dijo de repente; pero se contuvo ante el sentimiento del peligro.\"},{\"heading\":false,\"text\":\"Zametoff le miró con aire extraño y se puso tan blanco como la servilleta, en tanto que en su rostro se dibujaba una forzada sonrisa.\"},{\"heading\":false,\"text\":\"--Pero, ¿es eso posible?--dijo con voz que apenas podía ser entendida.\"},{\"heading\":false,\"text\":\"Raskolnikoff fijó en él una mirada maliciosa.\"},{\"heading\":false,\"text\":\"--Confiese usted que lo ha creído. ¿A que sí? ¿A que lo ha creído usted?\"},{\"heading\":false,\"text\":\"--No, de ninguna manera--se apresuró a decir Zametoff--. Usted me ha asustado para sugerirme esa idea.\"},{\"heading\":false,\"text\":\"--¿Según eso, usted no lo cree? ¿Entonces, de qué se pusieron a hablar el otro día al salir yo de la oficina? ¿Por qué el ayudante _Pólvora_ me interrogó después de mi desmayo? ¡Eh! ¿Cuánto debo?--gritó al mozo levantándose y tomando la gorra.\"},{\"heading\":false,\"text\":\"--Treinta kopeks--respondió éste, acudiendo a la llamada del parroquiano.\"},{\"heading\":false,\"text\":\"--Toma, además, veinte kopeks de propina. Vea usted cuánto dinero tengo--, prosiguió, mostrando a Zametoff unos cuantos billetes--: ¿los ve usted? Rojos, azules, veinticinco rublos. ¿De dónde procede este dinero? ¿Cómo, además, tengo ropa nueva? Usted sabe, en efecto, que yo no tenía ni un kopek. Apuesto cualquier cosa a que ha preguntado usted a mi patrona... ¡Ea! ¡Bastante hemos hablado! Hasta la vista.\"},{\"heading\":false,\"text\":\"Salió tan agitado con cierta extraña sensación, a la cual se unía un acre placer. Estaba, además, sombrío y terriblemente cansado. Semejaba su rostro convulsivo el de un hombre que acababa de sufrir un ataque de apoplejía. Poco antes, bajo la acción de sus emociones, sentía fuerzas; pero cuando aquel estimulante hubo cesado, invadíale intensa emoción.\"},{\"heading\":false,\"text\":\"Cuando se quedó solo, Zametoff permaneció aún largo tiempo sentado en el mismo sitio. El jefe de la Cancillería parecía pensativo. Raskolnikoff acababa de trastornarle inopinadamente todas sus ideas sobre «cierto punto»; estaba despistado.\"},{\"heading\":false,\"text\":\"--Ilia Petrovitch es un imbécil--dijo por último.\"},{\"heading\":false,\"text\":\"Apenas Raskolnikoff abrió la puerta de la calle, se encontró frente a frente en el vestíbulo con Razumikin que entraba. A un paso de distancia los dos jóvenes no se habían visto y poco faltó para que chocasen uno contra otro. Durante un momento se midieron con la mirada. Razumikin se quedó atónito; pero de repente brilláronle en los ojos llamaradas verdaderas de cólera.\"},{\"heading\":false,\"text\":\"--¿De modo que has venido aquí?--dijo con voz tonante--. ¡Pues no se ha escapado de la cama! ¡Y yo que le he buscado hasta debajo del sofá! ¡Hasta el granero se ha revuelto para ver si se daba contigo! Por causa tuya ha faltado poco para que le pegase a Anastasia... ¡Y vea usted dónde estaba metido! ¿Qué significa esto, Rodia? Di la verdad. Confiesa...\"},{\"heading\":false,\"text\":\"--Esto significa que me fastidiáis todos horrorosamente y que quiero estar solo--respondió fríamente Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¡Solo, cuando no puedes aún ni andar, cuando estás pálido como la cera; cuando te falta el aliento! ¡imbécil! ¿Qué has venido a hacer al _Palacio de Cristal_? Confiésamelo en seguida.\"},{\"heading\":false,\"text\":\"--Déjame pasar--replicó Raskolnikoff, y trató de alejarse.\"},{\"heading\":false,\"text\":\"Esto acabó de poner a Razumikin fuera de sí, y asiendo violentamente a su amigo por el brazo, le dijo:\"},{\"heading\":false,\"text\":\"--¿Y te atreves a decirme que te deje pasar? ¿Que te deje pasar? ¿Sabes lo que voy a hacer ahora mismo? A tomarte debajo del brazo, a llevarte a tu casa, como se lleva un envoltorio y encerrarte allí bajo llave.\"},{\"heading\":false,\"text\":\"--Escucha, Razumikin--dijo sin levantar la voz y con tono en la apariencia muy tranquilo--; ¿qué he de hacer para que comprendas que no necesito de tus beneficios? ¡Qué manía de hacer bien a las personas, en contra de su expresa voluntad! ¿Por qué viniste cuando caí enfermo a instalarte a mi cabecera? ¿Qué sabes tú si yo hubiera sido feliz muriéndome? ¿No te he manifestado hoy con toda claridad que me martirizabas, que me eras insoportable? ¿Qué gusto sacas en mortificar a la gente? Te juro que todo esto impide mi curación, teniéndome en una irritación continua. Ya has visto que Zosimoff se marchó para no martirizarme. ¡Déjame tú también, por amor de Dios!...\"},{\"heading\":false,\"text\":\"Razumikin se quedó un momento pensativo y después soltó el brazo de su amigo.\"},{\"heading\":false,\"text\":\"--Bueno. ¡Vete, con mil diablos!--dijo con voz que no había perdido toda vehemencia.\"},{\"heading\":false,\"text\":\"Pero en cuanto dió un paso Raskolnikoff, con extraordinario arrebato gritó Razumikin:\"},{\"heading\":false,\"text\":\"--¡Espera, escucha! Ya sabes que hoy daré una comida; quizá hayan llegado ya mis convidados; pero he dejado ya allí a mi tío para que los reciba. Si tú no fueses un imbécil, un imbécil rematado, un imbécil incorregible... Escucha, Rodia; reconozco que no te falta inteligencia, pero eres un imbécil. Digo, pues, que si tú no fueses un imbécil, vendrías a pasar la noche en mi casa en vez de estropearte las botas vagando sin objeto por las calles. Puesto que has salido, mejor es que aceptes mi invitación. Haré que te suban un cómodo sofá. Mis patrones lo tienen. Tomarás una taza de te y estarás acompañado. Si no quieres un sofá, te echarás en el catre... Al menos estarás con nosotros; irá Zosimoff... ¿vendrás?\"},{\"heading\":false,\"text\":\"--No.\"},{\"heading\":false,\"text\":\"--Pero esto es absurdo--replicó vivamente Razumikin--. ¿Qué sabes tú? Tú no puedes responder a ti mismo; yo también he escupido mil veces sobre la sociedad, y después de haberme apartado de ella no he tenido más remedio que volver a buscarla. Llega un momento en que se avergüenza uno de su misantropía y procura reunirse con los hombres. Acuérdate, en casa de Potchinkoff, tercer piso.\"},{\"heading\":false,\"text\":\"--No iré, Razumikin--contestó Raskolnikoff alejándose.\"},{\"heading\":false,\"text\":\"--Apuesto que vendrás; de lo contrario, como si no te conociese--le gritó su amigo--. Espera un poco. ¿Está aquí Zametoff?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Te ha visto?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Te ha hablado?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿De qué? Vamos, bueno; no lo digas si no quieres decirlo. Casa de Potchinkoff, núm. 47, habitación de Babusckin. Acuérdate.\"},{\"heading\":false,\"text\":\"Raskolnikoff llegó a la Sadovia y dobló la esquina. Después de haberle seguido con la mirada, Razumikin se decidió a entrar en el café, pero en medio de la escalera se detuvo.\"},{\"heading\":false,\"text\":\"--¡Por vida de...!--continuó casi en voz alta--. Habla con lucidez y como... ¡qué imbécil soy!... ¿Acaso los locos disparatan siempre? Zosimoff, por lo que a mí me parece, también teme como yo--y se llevó el dedo a la frente--. ¿Cómo abandonarle ahora? ¡Puede que vaya a ahogarse!... He hecho una tontería. No hay que vacilar--y echó a correr en busca de Raskolnikoff.\"},{\"heading\":false,\"text\":\"Pero no pudo encontrarle y le fué forzoso volverse a grandes pasos al _Palacio de Cristal_ para interrogar cuanto antes a Zametoff.\"},{\"heading\":false,\"text\":\"Raskolnikoff se fué derecho al puente***, y deteniéndose en medio de él, se puso a mirar a lo lejos. Desde que hubo dejado a Razumikin, su debilidad había aumentado, hasta el punto que solamente a duras penas pudo llegar a aquel sitio. Hubiera querido sentarse o acostarse en cualquier parte, aunque fuese en la calle. Inclinado sobre el agua, contemplaba con mirada distraída los últimos rayos del sol poniente y la fila de casas que la noche velaba poco a poco con sus tinieblas.\"},{\"heading\":false,\"text\":\"--Sea, pues--dijo, alejándose del puente y tomando la dirección de la oficina de policía.\"},{\"heading\":false,\"text\":\"Tenía el corazón como vacío: no quería pensar, ni siquiera sentía angustia. Una completa apatía había sucedido a la energía que experimentara cuando salió de casa resuelto «a acabar con todo».\"},{\"heading\":false,\"text\":\"--Después de todo, lo mismo da una solución que otra--pensaba avanzando lentamente por el muelle del canal--. Por lo menos, el desenlace depende de mi voluntad... ¡Qué fin, sin embargo! ¿Es posible que sea esto el fin? ¿Confesaré o no confesaré?... ¡pero si no puedo más!; quisiera acostarme o sentarme en alguna parte. Lo que me causa más vergüenza es la tontería de lo que he hecho. ¡Vamos, es preciso que esto acabe! ¡Qué ideas tan tontas tiene uno algunas veces!...\"},{\"heading\":false,\"text\":\"Para ir a la comisaría, le era preciso seguir todo derecho y tomar por la segunda calle de la izquierda. Una vez allí, estaba a dos pasos del despacho de policía; pero al llegar al primer recodo se detuvo, reflexionó un instante y entró en el _pereulok_. Después anduvo sin rumbo por otras dos calles, sin duda para ganar un minuto y dar tiempo a sus reflexiones. Andaba con los ojos fijos en tierra. De repente, le parecía que alguien le murmuraba alguna cosa al oído. Levantó la cabeza y advirtió que estaba en la puerta de _aquella casa_. No había pasado por allí desde el día del crimen.\"},{\"heading\":false,\"text\":\"Cediendo a un deseo tan irresistible como inexplicable, Raskolnikoff entró en ella, se dirigió a la escalera de la derecha y se dispuso a subir al cuarto piso. La empinada y estrecha escalera estaba muy obscura. El joven se detenía en cada descansillo y miraba con curiosidad en torno suyo. En el del primer piso habían puesto un vidrio en la ventana. «Ese vidrio no estaba la otra vez»--pensó el joven--. «He aquí el segundo piso en que trabajaban Mikolai y Mitrey: está cerrado y la puerta recién pintada. Sin duda han alquilado la habitación... He aquí el tercero... y el cuarto. Aquí es». Tuvo un momento de vacilación: la puerta de la casa de la vieja estaba abierta de par en par. Raskolnikoff oía que hablaban dentro. No había previsto aquello; sin embargo, tomó en seguida una resolución: subió los últimos escalones y entró.\"},{\"heading\":false,\"text\":\"Varios obreros lo estaban restaurando, lo que causó un asombro grande a Raskolnikoff. Creyó encontrar el cuarto tal como lo había dejado él; quizá se figuró que yacerían los cadáveres en el suelo. Ahora, con gran sorpresa suya, vió que estaban desnudas las paredes. Se aproximó a la ventana y se sentó en el poyo.\"},{\"heading\":false,\"text\":\"No había más que dos obreros, dos jóvenes, de los cuales uno era bastante mayor que el otro. Se ocupaban en cambiar la antigua tapicería amarilla, que estaba muy usada, por otra blanca sembrada de violetas. Esta circunstancia (ignoramos por qué) desagradó mucho a Raskolnikoff, el cual miraba colérico el papel nuevo, como si le contrariasen en extremo tales variaciones.\"},{\"heading\":false,\"text\":\"Los papelistas se disponían a marcharse, y, sin hacer caso del visitante, continuaron su conversación.\"},{\"heading\":false,\"text\":\"Raskolnikoff se levantó y pasó a la otra habitación, que contenía ante el cofre, la cama y la cómoda; este gabinete sin muebles le pareció muy pequeño. La tapicería no había sido cambiada; se podía señalar aún en el rincón el lugar que ocupaba en otro tiempo el armario de las sagradas imágenes. Después de haber satisfecho su curiosidad, Raskolnikoff volvió a sentarse en el poyo de la ventana.\"},{\"heading\":false,\"text\":\"El mayor de los dos obreros le miró de reojo, y de repente, dirigiéndose a él, le dijo:\"},{\"heading\":false,\"text\":\"--¿Qué hace usted ahí?\"},{\"heading\":false,\"text\":\"En vez de responder, Raskolnikoff se levantó, fué al descansillo y se puso a tirar del cordón. Era la misma campanilla, el mismo sonido. Llamó por segunda y tercera vez, aplicando el oído, reconstituyendo sus recuerdos. La impresión terrible que sintiera ante la puerta de la vieja se produjo con vivacidad y lucidez crecientes; temblaba a cada campanillazo y sentía a cada golpe un placer cada vez mayor.\"},{\"heading\":false,\"text\":\"--¿Qué busca usted aquí? ¿quién es usted?--gritó el obrero encarándose con él.\"},{\"heading\":false,\"text\":\"Raskolnikoff volvió a entrar en el cuarto.\"},{\"heading\":false,\"text\":\"--Quiero alquilar una habitación y he venido a mirar ésta--respondió.\"},{\"heading\":false,\"text\":\"--No se va por la noche a ver cuartos, y además debiera usted haber subido acompañado del _dvornik_.\"},{\"heading\":false,\"text\":\"--Han fregado el suelo; ¿van a pintarlo?--prosiguió Raskolnikoff--. ¿No hay sangre?\"},{\"heading\":false,\"text\":\"--¿Cómo sangre?\"},{\"heading\":false,\"text\":\"--Aquí fueron asesinadas la vieja y su hermana; había un verdadero mar de sangre.\"},{\"heading\":false,\"text\":\"--¿Quién eres tú?--gritó el obrero asustado.\"},{\"heading\":false,\"text\":\"--¿Yo?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Quieres saberlo? Vamos a la comisaría y allí te lo diré.\"},{\"heading\":false,\"text\":\"Los dos papelistas le miraron estupefactos.\"},{\"heading\":false,\"text\":\"--Ya es hora de marcharnos. Vamos, Aleshka. Hay que cerrar--dijo el de más edad a su compañero.\"},{\"heading\":false,\"text\":\"--Pues bien, vamos--replicó con tono indiferente Raskolnikoff, y saliendo él primero, precediendo a los dos operarios, bajó lentamente la escalera--. ¡Eh, _dvornik_!--gritó al llegar a la puerta de la calle donde había reunidas varias personas mirando pasar a la gente: dos porteros, un campesino, un ciudadano en traje de casa y algunos otros individuos.\"},{\"heading\":false,\"text\":\"Raskolnikoff se fué derecho a ellos.\"},{\"heading\":false,\"text\":\"--¿Qué se le ofrece a usted?--preguntóle un portero.\"},{\"heading\":false,\"text\":\"--¿Has estado en la oficina de policía?\"},{\"heading\":false,\"text\":\"--De allí vengo.\"},{\"heading\":false,\"text\":\"--¿Están allí todavía?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿El ayudante del comisario también está?\"},{\"heading\":false,\"text\":\"--Estaba hace un momento. ¿Qué es lo que usted desea?\"},{\"heading\":false,\"text\":\"Raskolnikoff no contestó y se quedó pensativo.\"},{\"heading\":false,\"text\":\"--Ha venido a ver el cuarto--dijo uno de los operarios.\"},{\"heading\":false,\"text\":\"--¿Qué cuarto?\"},{\"heading\":false,\"text\":\"--En el que trabajábamos. «¿Por qué se ha lavado la sangre?», nos ha dicho. «Aquí se ha cometido un asesinato y vengo para alquilar el cuarto.» Se puso a tirar de la campanilla. «Vamos a la oficina de policía», añadió después; «allí lo diré todo».\"},{\"heading\":false,\"text\":\"El portero, preocupado, contempló a Raskolnikoff frunciendo las cejas.\"},{\"heading\":false,\"text\":\"--¿Quién es usted?--preguntó, levantando la voz con acento de amenaza.\"},{\"heading\":false,\"text\":\"--Yo soy Rodión Romanovitch Raskolnikoff, antiguo estudiante y vivo cerca de aquí, en el _pereulok_ inmediato, casa de Chill, departamento número 14. Pregunta al portero; me conoce.\"},{\"heading\":false,\"text\":\"Raskolnikoff dijo todo esto con aire indiferente y tranquilo, mirando obstinadamente a la calle y sin fijar la vista una sola vez en su interlocutor.\"},{\"heading\":false,\"text\":\"--¿Y qué ha venido usted a hacer aquí?\"},{\"heading\":false,\"text\":\"--He venido a ver la casa.\"},{\"heading\":false,\"text\":\"--¿Y qué se le ha perdido a usted en ella?\"},{\"heading\":false,\"text\":\"--¿No sería mejor detenerle y conducirle a la comisaría?--propuso de repente el burgués.\"},{\"heading\":false,\"text\":\"Raskolnikoff le miró con atención por encima del hombro.\"},{\"heading\":false,\"text\":\"--Vamos allá--dijo el joven con indiferencia.\"},{\"heading\":false,\"text\":\"--Sí. Es preciso llevarle a la comisaría--siguió diciendo y con mayor seguridad el burgués--. Cuando ha venido aquí, es que algo le pesa en la conciencia.\"},{\"heading\":false,\"text\":\"--¡Dios sabe si estará borracho!--murmuró un obrero.\"},{\"heading\":false,\"text\":\"--¿Pero qué es lo que quieres?--gritó de nuevo el portero, que empezaba a incomodarse de verdad--. ¿Por qué vienes a molestarnos?\"},{\"heading\":false,\"text\":\"--¿Te da miedo ir a la comisaría?--dijo con tono burlón Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¿Por qué he de tener miedo? ¿Sabes que nos estás fastidiando?\"},{\"heading\":false,\"text\":\"--Es un granuja--dijo una campesina.\"},{\"heading\":false,\"text\":\"--¿Para qué disputar con él?--apuntó a su vez el otro portero, un _mujick_ enorme que llevaba un gabán desabrochado y un manojo de llaves pendientes de la cintura--. De seguro es un granuja. ¡Ea! ¡Lárgate en seguida!\"},{\"heading\":false,\"text\":\"Y agarrando a Raskolnikoff por un brazo lo lanzó en medio del arroyo.\"},{\"heading\":false,\"text\":\"El joven estuvo a punto de caer al suelo; sin embargo, pudo sostenerse en pie. Cuando hubo recobrado el equilibrio, miró silenciosamente a todos los espectadores y se alejó silenciosamente.\"},{\"heading\":false,\"text\":\"--¡Vaya un tipo!--observó un obrero.\"},{\"heading\":false,\"text\":\"--Todo el mundo se ha vuelto ahora muy extravagante--dijo la campesina.\"},{\"heading\":false,\"text\":\"--Lo que usted quiera y mucho más--añadió el burgués--; pero hubiera sido conveniente llevarle a la comisaría.\"},{\"heading\":false,\"text\":\"--¿Iré o no iré?--pensaba Raskolnikoff deteniéndose en medio de una encrucijada y mirando en torno suyo, como si hubiese estado esperando un consejo de alguien.\"},{\"heading\":false,\"text\":\"Pero su pregunta no obtuvo respuesta; todo estaba sordo y sin vida, como las piedras de las calles... De pronto, a doscientos pasos de él, distinguió, a través de la obscuridad, un grupo de gente del que partían gritos y palabras animadas... El grupo rodeaba un coche. En el suelo brillaba una débil luz.\"},{\"heading\":false,\"text\":\"--¿Qué pasa ahí?\"},{\"heading\":false,\"text\":\"Raskolnikoff volvió a la derecha y fué a mezclarse con la multitud. Parecía querer aferrarse al menor incidente, y esta pueril predisposición le hacía sonreír, porque ya había tomado su partido y decía para sus adentros:\"},{\"heading\":false,\"text\":\"--De un momento a otro acabará todo esto.\"}]},{\"title\":\"segunda parte — capítulo VII\",\"blocks\":[{\"heading\":false,\"text\":\"Detenido en medio de la calle había un elegante coche particular, tirado por dos sudorosos caballos tordos. En el interior no había nadie y el cochero se había bajado del pescante y sujetaba a los caballos por el bocado. En torno del carruaje se apiñaba la multitud, contenida por los agentes de policía. Uno de éstos tenía una linterna pequeña en la mano e inclinado hacia el suelo alumbrado algo que yacía en el arroyo cerca de las ruedas. Todo el mundo hablaba, gritaba y parecía consternado; por su parte, el cochero, aturdido, no cesaba de repetir:\"},{\"heading\":false,\"text\":\"--¡Qué desgracia, Señor! ¡Qué desgracia!\"},{\"heading\":false,\"text\":\"Raskolnikoff se abrió paso a fuerza de codazos al través de los curiosos y logró ver lo que había sido causa de que la gente se reuniese. En medio de la calle yacía ensangrentado y privado del conocimiento un individuo que acababa de ser atropellado por los caballos. Aunque estaba muy mal vestido, su aspecto no era el de un hombre vulgar. Tenía el cráneo y el rostro cubiertos de horribles heridas, por las cuales salía la sangre a borbotones. No se trataba de un incidente sin importancia.\"},{\"heading\":false,\"text\":\"--¡Dios mío!--decía el cochero--; no he podido impedir esta desgracia. Si yo hubiese llevado los caballos al galope, o si no lo hubiese visto y avisado, bueno que se me echase la culpa. Pero no; el coche iba despacio como todo el mundo ha podido ver. Desgraciadamente, sabido es que un borracho no se fija en nada... Le veo atravesar la calle una vez, dos y tres haciendo eses, y le grito: «¡Eh! ¡cuidado!» Refreno los caballos; pero él se va derecho a ellos. ¡Si parecía que lo hacía adrede! Los animales son jóvenes y fogosos, se lanzaron... el hombre gritó y sus gritos los excitaron más... así ha ocurrido esa desgracia.\"},{\"heading\":false,\"text\":\"--Sí, de ese modo ha pasado--afirmó uno que había sido testigo de la escena.\"},{\"heading\":false,\"text\":\"--En efecto--dijo otro--; por tres veces le avisó el cochero.\"},{\"heading\":false,\"text\":\"--Sí, por tres veces, todos le hemos oído--añadió uno del grupo.\"},{\"heading\":false,\"text\":\"Por su parte, el cochero no parecía muy inquieto por las consecuencias de aquel suceso; evidentemente, el propietario del carruaje era un personaje poderoso que esperaba la llegada de su coche. Esta última circunstancia despertaba la cuidadosa solicitud de los agentes de policía. Era, sin embargo, preciso llevar al herido al hospital. Nadie sabía su nombre.\"},{\"heading\":false,\"text\":\"Raskolnikoff, a fuerza de dar codazos, logró aproximarse al herido. De pronto un rayo de luz iluminó el rostro del desgraciado, y el joven lo reconoció.\"},{\"heading\":false,\"text\":\"--Le reconozco, le reconozco--gritó empujando a los que le rodeaban y colocándose en la primera fila del grupo--; es un antiguo funcionario, el consejero titular Marmeladoff. Vive aquí cerca, en casa de Kozel... ¡Pronto! ¡un médico! ¡yo pago!\"},{\"heading\":false,\"text\":\"Sacó dinero del bolsillo y lo mostró a un agente de policía. Revelaba extraordinaria agitación.\"},{\"heading\":false,\"text\":\"Los agentes se alegraron de saber quién había sido el atropellado. Raskolnikoff dió su nombre y dirección e insistió con empeño para que se transportase el herido a su domicilio. Aunque la víctima del accidente hubiese sido su padre, no habría mostrado el joven mayor solicitud.\"},{\"heading\":false,\"text\":\"--Es ahí, tres casas más allá donde vive; en la de Kozel, un alemán rico... Sin duda se retiraba embriagado. Le reconozco... Es un borracho... Vive ahí con su familia, tiene mujer e hijos. Antes de llevarle al hospital, es menester que le vea un médico; alguno habrá por aquí cerca; yo pagaré lo que sea, lo pagaré; su estado exige una cura inmediata. Si no se le socorre en seguida, morirá antes de llegar al hospital.\"},{\"heading\":false,\"text\":\"Raskolnikoff puso disimuladamente algunas monedas en la mano de un agente de policía. Por otra parte, lo que el joven le mandaba era perfectamente lógico, se explicaba bien. Levantaron a Marmeladoff y algunos voluntarios se ofrecieron a transportarle a su casa. La de Kozel estaba situada a treinta pasos del lugar en que había ocurrido el accidente. Raskolnikoff iba detrás sosteniendo con precaución la cabeza del herido, y enseñando el camino.\"},{\"heading\":false,\"text\":\"--¡Aquí, aquí! En la escalera, tened cuidado de que no vaya la cabeza baja: dad la vuelta... eso es, yo pago. Muchas gracias--murmuraba.\"},{\"heading\":false,\"text\":\"En aquel momento Catalina Ivanovna, como de costumbre, cuando tenía un minuto libre, paseaba de un lado a otro de su reducida sala, yendo de la ventana a la chimenea y viceversa, con los brazos cruzados sobre el pecho, charlando sola y tosiendo. Desde algún tiempo hablaba cada vez de mejor gana con su hija mayor Polenka. Aunque esta niña, de diez años de edad, no comprendía aún muchas cosas, se daba, sin embargo, cuenta de la necesidad que su madre tenía de ella, de modo que fijaba siempre sus grandes e inteligentes ojos en Catalina Ivanovna, y en cuanto ésta le dirigía la palabra, la niña hacía todos los esfuerzos imaginables para comprender, o, por lo menos, para hacer ver que comprendía.\"},{\"heading\":false,\"text\":\"Ahora Polenka desnudaba a su hermanito que había estado durante todo el día enfermo y que iba a acostarse. Esperando a que le quitasen la camisa para lavarla por la noche, el niño, con aspecto serio, estaba sentado en una silla silencioso e inmóvil y escuchaba, abriendo mucho los ojos, lo que su mamá decía a su hermana. La niña más pequeña, Lida (Lidotshka), vestida con verdaderos harapos, esperaba a su vez en pie, cerca de la mampara. La puerta que daba al descansillo estaba abierta, a fin de que saliera el humo del tabaco que llegaba de la habitación contigua, y que, a cada instante, hacía toser a la pobre tísica. Catalina Ivanovna estaba peor desde hacía ocho días, y las siniestras manchas de sus mejillas tenían un color más vivo que nunca.\"},{\"heading\":false,\"text\":\"--No puedes imaginarte, Polenka--decía paseándose por la habitación--, qué alegre y brillante vida era la que hacíamos en casa de papá y cuán desgraciados somos todos a causa de este borracho. Papá tenía en el servicio civil un empleo equivalente al grado de coronel. Era casi gobernador y no le faltaba más que un paso para llegar a este puesto; así es que todo el mundo le decía: «Consideramos a usted ya, Ivan Mikhailtch, como gobernador.»\"},{\"heading\":false,\"text\":\"La interrumpió un golpe de tos.\"},{\"heading\":false,\"text\":\"--¡Oh condenada vida!\"},{\"heading\":false,\"text\":\"Escupió y se apretó el pecho con las manos.\"},{\"heading\":false,\"text\":\"--¿Está ya el agua? ¡Ea! dame la camisa y las medias, Lida--añadió, dirigiéndose a la chiquita--. Esta noche dormirás sin camisa. Pon las medias al lado... Se lavará todo al mismo tiempo... ¡Y ese borracho sin venir!... Quisiera lavar también su camisa con todo lo demás, para no tener que fatigarme dos noches seguidas. ¡Señor, Señor!--volvió a toser--. ¡Otra vez! ¿Eh? ¿Qué es eso?--exclamó al ver que el vestíbulo se llenaba de gente, la cual penetraba en la sala con una especie de fardo--. ¿Qué es eso? ¿Qué es lo que traen? ¡Dios mío!\"},{\"heading\":false,\"text\":\"--¿Dónde hay que ponerlo?--preguntó un agente de policía mirando en derredor suyo mientras introducían en la habitación a Marmeladoff ensangrentado y exánime.\"},{\"heading\":false,\"text\":\"--En el sofá. Extenderle en el sofá... La cabeza aquí--indicó Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Es un borracho que ha sido atropellado en la calle--gritó uno desde la puerta.\"},{\"heading\":false,\"text\":\"Catalina Ivanovna, intensamente pálida, respiraba con dificultad. La pequeña Lida corrió gritando hacia su hermana mayor, y toda temblorosa la estrechó en sus brazos.\"},{\"heading\":false,\"text\":\"Después de haber ayudado a colocar a Marmeladoff en el sofá, Raskolnikoff se acercó a Catalina Ivanovna.\"},{\"heading\":false,\"text\":\"--Por el amor de Dios, tranquilícese, cálmese, no se asuste tanto--dijo el joven vivamente--. Atravesaba la calle y un coche le ha atropellado; no se alarme usted, va a recobrar el conocimiento. He mandado que le traigan aquí. Yo ya he venido a esta casa otra vez. Quizá no se acuerde usted. Volverá en si. Yo pagaré...\"},{\"heading\":false,\"text\":\"--No volverá en si, no volverá en si--dijo con desesperación Catalina Ivanovna y se precipitó hacia su marido.\"},{\"heading\":false,\"text\":\"Raskolnikoff echó de ver en seguida que esta mujer no era propensa a desmayos. En un instante colocó una almohada debajo de la cabeza del herido, cosa en que nadie había pensado. Catalina Ivanovna se puso a desnudar a Marmeladoff, a examinar sus heridas y a prodigarle inteligentes cuidados. La emoción no le quitaba la presencia de ánimo; se olvidaba de sí misma, mordíase los labios temblorosos y contenía en su pecho los gritos prontos a escaparse.\"},{\"heading\":false,\"text\":\"Durante este tiempo, Raskolnikoff mandó por un médico que vivía en la vecindad.\"},{\"heading\":false,\"text\":\"--He mandado a buscar un médico--dijo a Catalina Ivanovna--. No se preocupe usted, yo pagaré. ¿No tiene usted agua? Déme una toalla, una servilleta, cualquier cosa, en seguida. No podemos juzgar de la gravedad de las heridas... está herido, pero no muerto; convénzase usted. Ya veremos lo que dice el doctor.\"},{\"heading\":false,\"text\":\"Catalina Ivanovna corrió a la ventana; colocada sobre una mala silla había una cubeta con agua, preparada para lavar durante la noche la ropa del marido y de sus hijos. Catalina Ivanovna solía hacer este lavado nocturno con sus propias manos, dos veces por semana, cuando no más a menudo, porque los Marmeladoff habían llegado a tal extremo de miseria, que les faltaba casi en absoluto ropa para mudarse: cada miembro de la familia no tenía más camisa que la que llevaba puesta, y como Catalina Ivanovna no podía sufrir la suciedad, prefería la pobre tísica, antes que verla reinar en su casa, fatigarse por las noches lavando la ropa de los suyos, para que ellos la encontrasen limpia y repasada al día siguiente al despertar.\"},{\"heading\":false,\"text\":\"Obedeciendo a Raskolnikoff, tomó la cubeta y se la llevó al joven, pero faltó poco para que se cayese con ella. Raskolnikoff logró encontrar una toalla, la empapó de agua y lavó con ella el rostro ensangrentado de Marmeladoff. Catalina Ivanovna, en pie a su lado, respiraba con dificultad y se apretaba el pecho con las manos.\"},{\"heading\":false,\"text\":\"No hubieran estado de más para ella los cuidados facultativos.\"},{\"heading\":false,\"text\":\"--Quizá he hecho mal en traer el herido a su casa--pensaba Raskolnikoff.\"},{\"heading\":false,\"text\":\"El guardia no sabía qué decidir.\"},{\"heading\":false,\"text\":\"--¡Polia!--gritó Catalina Ivanovna--, ve corriendo a casa de Sonia; pronto, dile que su padre ha sido atropellado por un coche, que venga en seguida. Si no la encuentras en casa, se lo dices a los Kapernumoff para que le den el recado en cuanto vaya. ¡Despáchate, Polia; anda, ponte ese pañuelo en la cabeza!\"},{\"heading\":false,\"text\":\"En tanto, la sala se había llenado de tal modo de gente, que no cabía ya ni un alfiler. Los agentes de policía se retiraron; uno solo se quedó momentáneamente y trató de desalojar algo el aposento. Mientras que ocurría esto, por la puerta de comunicación interior penetraron en la sala casi todos los inquilinos de la señora Lippevechzel: primero se detuvieron en el umbral, pero bien pronto invadieron la habitación. Catalina Ivanovna se puso furiosa.\"},{\"heading\":false,\"text\":\"--Deberíais al menos dejarle morir en paz--gritaba a los asaltantes--. Venís aquí como a un espectáculo--y se interrumpió para toser--. Y entráis con el sombrero puesto; marchaos, tened por lo menos respeto a la muerte.\"},{\"heading\":false,\"text\":\"La tos que la ahogaba la impidió seguir; pero su severa admonición produjo efecto. Evidentemente, Catalina Ivanovna inspiraba cierto temor.\"},{\"heading\":false,\"text\":\"Los inquilinos fueron unos tras otros desfilando hacia la puerta, llevándose en sus corazones ese extraño sentimiento de satisfacción que hasta los hombres más compasivos experimentan a la vista de la desgracia ajena. Después que hubieron salido se oyeron las voces del otro lado de la puerta: decían en alta voz que era preciso enviar el herido al hospital, pues no había derecho para turbar la tranquilidad de la casa.\"},{\"heading\":false,\"text\":\"--Ese es el inconveniente de morirse--vociferó Catalina Ivanovna, y ya se preparaba a desahogar en ellos su indignación, cuando se abrió la puerta y apareció la señora Lippevechzel en persona.\"},{\"heading\":false,\"text\":\"La patrona acababa de saber la desgracia y venía a restablecer el orden. Era una alemana intrigante y mal educada.\"},{\"heading\":false,\"text\":\"--¡Ah, Dios mío!--dijo juntando las manos--, ¡su marido de usted, que estaba borracho, se ha dejado aplastar por un coche! Hay que llevarle al hospital, yo soy la propietaria.\"},{\"heading\":false,\"text\":\"--Amalia Ludvigovna, suplico a usted que piense lo que habla--comenzó a decir con tono arrogante Catalina Ivanovna. (Siempre que hablaba a la patrona empleaba el mismo tono para recordarle la debida compostura; y aun en aquel momento no pudo resistir a semejante placer.)--Amalia Ludvigovna.\"},{\"heading\":false,\"text\":\"--Ya se lo he dicho a usted de una vez para siempre, no quiero que se me llame Amalia Ludvigovna; yo soy Amalia Ivanovna.\"},{\"heading\":false,\"text\":\"--Usted no es Amalia Ivanovna sino Amalia Ludvigovna, y como yo no pertenezco al grupo de viles aduladores de usted, tal como el señor Lebeziatnikoff que se está riendo ahora detrás de la puerta. (Ahora se agarran ji, ji--decía en efecto una voz burlona en la pieza inmediata), yo la llamaré a usted siempre Amalia Ludvigovna, aunque no puedo comprender por qué le molesta este nombre. Ya ve usted lo que acaba de ocurrirle a Simón Zakharovitch: está muriéndose. Suplico a usted que cierre la puerta y que no deje entrar nadie aquí. Déjele, al menos, que muera en paz. De lo contrario le juro a usted que mañana mismo daré parte al gobernador general. El príncipe me conoce desde mi juventud y se acuerda muy bien de Simón Zakharovitch, a quien más de una vez ha hecho algún favor. Todo el mundo sabe que mi marido tenía muchos amigos y protectores; como se daba cuenta de su desgraciado vicio, cesó de tratarse con ellos por un sentimiento noble de delicadeza; pero ahora--añadió señalando a Raskolnikoff--hemos encontrado apoyo en este magnánimo joven que es rico, tiene muy buenas relaciones y es amigo desde la infancia de Simón Zakharovitch. Téngalo usted presente, Amalia Ludvigovna.\"},{\"heading\":false,\"text\":\"Todo este discurso fué pronunciado con creciente rapidez, pero la tos interrumpió la elocuencia de Catalina Ivanovna En aquel momento, Marmeladoff, volviendo en sí, lanzó un gemido. Catalina se acercó solícita a su esposo. Este, sin darse aún cuenta de nada, miraba a Raskolnikoff, en pie a su cabecera. Su respiración era débil y penosa, tenía sangre en las comisuras de los labios y la frente empapada en sudor. No reconociendo a Raskolnikoff le miraba con cierta inquietud. Catalina Ivanovna fijó en el herido una mirada afligida, pero severa. Después la pobre mujer rompió a llorar.\"},{\"heading\":false,\"text\":\"--¡Dios mío! ¡Tiene el pecho aplastado! ¡Cuánta sangre!--decía acongojada--. Hay que quitarle la ropa. ¡Vuélvete un poco, si puedes, Marmeladoff!\"},{\"heading\":false,\"text\":\"Marmeladoff la reconoció.\"},{\"heading\":false,\"text\":\"--¡Un sacerdote!--dijo con voz ronca.\"},{\"heading\":false,\"text\":\"Catalina Ivanovna se aproximó a la ventana y apoyando la frente en el marco gritó con desesperación:\"},{\"heading\":false,\"text\":\"--¡Oh vida, mil veces maldita!\"},{\"heading\":false,\"text\":\"--¡Un sacerdote!--repitió el moribundo después de una pausa.\"},{\"heading\":false,\"text\":\"--¡Silencio!--le gritó Catalina Ivanovna.\"},{\"heading\":false,\"text\":\"El herido obedeció y calló. Buscaba a su mujer con ojos tímidos y ansiosos. Catalina fué de nuevo a situarse a su cabecera; Marmeladoff se tranquilizó, pero no por largo tiempo. De repente vió en el rincón a la pequeña Lida (su predilecta), que temblaba como si le fuese a dar una convulsión y que le miraba con ojos enormemente abiertos de niño asombrado.\"},{\"heading\":false,\"text\":\"--¡Ah, ah!--dijo con gran agitación señalando a la chiquilla.\"},{\"heading\":false,\"text\":\"Se comprendía que trataba de decir algo.\"},{\"heading\":false,\"text\":\"--¿Qué?--gritó Catalina Ivanovna.\"},{\"heading\":false,\"text\":\"--¡No tiene calzado!--y sus ojos, como de loco, no se apartaban de los pies desnudos de la niña.\"},{\"heading\":false,\"text\":\"--¡Cállate!--replicó con tono irritado Catalina Ivanovna--: demasiado sabes que no tiene calzado...\"},{\"heading\":false,\"text\":\"--¡Gracias a Dios! ¡Aquí está el médico!--dijo gozosamente Raskolnikoff.\"},{\"heading\":false,\"text\":\"Entró un viejecillo alemán de modales acompasados, que miraba con desconfianza en derredor suyo. Se aproximó al herido, le tomó el pulso, examinó atentamente la cabeza, y después, ayudado por Catalina Ivanovna, desabrochó la camisa, toda ensangrentada, y dejó el pecho al descubierto, que estaba magullado; varias costillas de la derecha rotas, a la izquierda, al lado del corazón, se veía una gran mancha negruzca y amarillenta marcada por una violenta pisada de caballo. El doctor frunció el entrecejo. El agente de policía acababa de contarle que el herido había sido atropellado en una calle y arrastrado en una extensión de treinta pasos.\"},{\"heading\":false,\"text\":\"--Es asombroso que esté todavía vivo--murmuró en voz baja el doctor dirigiéndose a Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¿Qué le parece a usted?--preguntó este último.\"},{\"heading\":false,\"text\":\"--Caso perdido.\"},{\"heading\":false,\"text\":\"--¿No hay esperanza?\"},{\"heading\":false,\"text\":\"--Ninguna. Va a exhalar el último suspiro... Tiene una herida muy peligrosa en la cabeza. Podría sangrársele... pero sería inútil: morirá de seguro dentro de cinco a seis minutos.\"},{\"heading\":false,\"text\":\"--Sángrele usted, sin embargo.\"},{\"heading\":false,\"text\":\"--Sea; pero le advierto que la sangría no servirá absolutamente de nada.\"},{\"heading\":false,\"text\":\"Estando en esto se oyó otra vez ruido de pasos. La multitud, que se agrupaba en el umbral, se abrió, y apareció un eclesiástico de cabellos blancos. Traía la Extremaunción para el moribundo. El doctor cedió el puesto al sacerdote, con el cual cambió una significativa mirada. Raskolnikoff suplicó al médico que se quedase un momento todavía. El médico accedió encogiéndose de hombros.\"},{\"heading\":false,\"text\":\"Todos se apartaron. La confesión duró muy poco tiempo. Marmeladoff no se hallaba en estado de discurrir. Sólo podía lanzar sonidos entrecortados e ininteligibles. Catalina Ivanovna fué a arrodillarse en el rincón inmediato a la chimenea, e hizo que se arrodillasen delante de ella los dos niños. Lidotshka no hacía más que temblar. El pequeñuelo, de rodillas, imitaba los grandes signos de cruz que hacía su madre y se prosternaba dando en el suelo con la frente, lo que parecía divertirle. Catalina Ivanovna se mordía los labios y contenía las lágrimas. Rezaba arreglando al mismo tiempo la camisa del pequeñuelo, sin interrumpir su oración, y sin levantarse consiguió sacar de la cómoda un pañuelo del cuello que echó sobre los hombros desnudos de la niña. En tanto la puerta de comunicación había sido abierta de nuevo por los curiosos vecinos. En el descansillo había también aumentado el grupo de espectadores. Se encontraban en él todos los inquilinos de los diversos pisos; pero sin franquear el umbral de la estancia. Toda esta escena estaba alumbrada por un cabo de vela.\"},{\"heading\":false,\"text\":\"En aquel momento, Polenka, que había ido a buscar a su hermana, atravesó vivamente el grupo formado en el corredor y entró, pudiendo apenas respirar a causa de lo que había ocurrido. Después de quitarse el pañuelo, buscó con los ojos a su madre, y acercándose a ella le dijo:\"},{\"heading\":false,\"text\":\"--Ahí viene; la he encontrado por la calle.\"},{\"heading\":false,\"text\":\"Catalina Ivanovna la hizo arrodillarse a su lado. Sonia se abrió paso tímidamente, y sin ruido, por en medio de la gente. En aquella habitación, que era la imagen de la miseria, de la desesperación y de la muerte, su entrada repentina produjo extraño efecto. Aunque muy pobremente vestida, iba muy ataviada con ese aire llamativo que distingue a las pobres mujerzuelas del arroyo. Al llegar a la entrada del aposento, la joven se detuvo en el umbral y echó al interior una mirada de asombro. Parecía que no tenía conciencia de nada; no se cuidaba de su falda de seda, comprada de lance, cuyo color chillón y cuya cola desmesuradamente larga eran muy impropias de aquel lugar lo mismo que su inmenso miriñaque que ocupaba toda la anchura de la puerta, sus botas provocadoras, la sombrilla que tenía en la mano, aunque no tuviese necesidad de ella, y, en fin, su ridículo sombrero de paja, adornado con una pluma brillantemente roja.\"},{\"heading\":false,\"text\":\"Bajo aquel sombrero picarescamente ladeado, se veía una carita enfermiza, pálida y asustada con la boca abierta e inmóviles de terror los ojos. Sonia tenía diez y ocho años, era rubia, bajita y delgada, pero bastante linda. Llamaban la atención sus ojos claros. Tenía la mirada fija en el lecho y en el sacerdote. Como Polenka, estaba sofocada por lo de prisa que había venido. Por último, algunas palabras, murmuradas por la gente, llegaron sin duda a sus oídos. Bajando la cabeza franqueó el umbral y penetró en la sala, pero se quedó cerca de la puerta.\"},{\"heading\":false,\"text\":\"Cuando el moribundo hubo recibido los Santos Sacramentos, su mujer se acercó a él. Antes de retirarse, el sacerdote creyó de su deber dirigir algunas palabras de consuelo a Catalina Ivanovna.\"},{\"heading\":false,\"text\":\"--¡Qué va a ser de ellos!--interrumpió la mujer con amargura mostrando sus hijos.\"},{\"heading\":false,\"text\":\"--Dios es misericordioso; confíe usted en el socorro del Altísimo--replicó el eclesiástico.\"},{\"heading\":false,\"text\":\"--¡Misericordioso, sí; pero no para nosotros!\"},{\"heading\":false,\"text\":\"--Eso es un pecado, señora, un pecado--observó el sacerdote moviendo la cabeza.\"},{\"heading\":false,\"text\":\"--¿Y esto no es un pecado?--replicó vivamente Catalina Ivanovna mostrando al moribundo.\"},{\"heading\":false,\"text\":\"--Los que le han privado involuntariamente de su sostén le ofrecerán quizá una indemnización para reparar al menos el perjuicio material.\"},{\"heading\":false,\"text\":\"--Usted no me comprende--replicó con tono irritado Catalina Ivanovna--. ¿De qué hay que indemnizarme si ha sido él mismo que, borracho como estaba, se ha arrojado a los pies de los caballos? ¡El mi sostén! ¡Si ha sido siempre para mí causa de disgusto! ¡Si se lo bebía todo! ¡Si nos despojaba para ir a gastarse el dinero de la casa en la taberna! ¡Dios ha hecho bien llevándoselo! ¡Esto es un verdadero alivio para nosotras!\"},{\"heading\":false,\"text\":\"--Hay que perdonar a un moribundo; esos sentimientos son un pecado, señora, un gran pecado.\"},{\"heading\":false,\"text\":\"Mientras hablaba con el sacerdote, Catalina Ivanovna no cesaba de ocuparse del herido: le daba agua, le enjugaba el sudor y la sangre de su cabeza y arreglaba las almohadas. Las últimas palabras del eclesiástico la pusieron hecha una furia.\"},{\"heading\":false,\"text\":\"--¡Eh, _batuchka_! ¡Esas no son más que palabras! ¡Perdonar! Si hoy no le hubiesen aplastado los caballos, habría entrado en casa, como de costumbre, borracho. Como no tiene más camisa que la que lleva puesta, hubiera tenido yo que lavársela mientras él durmiese, así como la ropa de los niños. Después hubiera necesitado secarlo todo, para repasarlo a la madrugada. Tal es el empleo de mis noches. ¡Y me habla usted de perdón! Además, le he perdonado.\"},{\"heading\":false,\"text\":\"Un violento acceso de tos le impidió seguir adelante. Escupió en un pañuelo y lo extendió ante los ojos del eclesiástico, mientras con la mano izquierda apretaba dolorosamente su pecho. El pañuelo estaba ensangrentado.\"},{\"heading\":false,\"text\":\"El pope bajó la cabeza y no dijo palabra.\"},{\"heading\":false,\"text\":\"Marmeladoff estaba en la agonía; no apartaba los ojos de su mujer, que de nuevo se había inclinado sobre él. Tenía deseos de decirle algo, trataba de hablar, movía los labios con esfuerzo, pero no conseguía otra cosa que prorrumpir en sonidos inarticulados. Catalina Ivanovna, comprendiendo que su marido quería pedirle perdón, le gritó con tono imperioso:\"},{\"heading\":false,\"text\":\"--Cállate. Es inútil... Sé lo que quieres decir...\"},{\"heading\":false,\"text\":\"El herido se calló, pero en aquel instante sus miradas se dirigieron a la puerta y vió a Sonia...\"},{\"heading\":false,\"text\":\"Hasta entonces no había reparado en el rincón sombrío en que la joven se encontraba.\"},{\"heading\":false,\"text\":\"--¿Quién está allí? ¿Quién está allí?--dijo de repente con voz ronca y ahogada mostrando al mismo tiempo con los ojos, que expresaban un gran terror, la puerta frente a la cual estaba en pie su hija.\"},{\"heading\":false,\"text\":\"Marmeladoff trató de incorporarse.\"},{\"heading\":false,\"text\":\"--¡Sigue echado! ¡No te muevas!--gritó Catalina Ivanovna.\"},{\"heading\":false,\"text\":\"Pero, merced a un esfuerzo sobrehumano, logró sentarse en el sofá. Durante algún tiempo contempló a su hija con aire extraño; parecía no reconocerla; era también la vez primera que la veía en aquel traje. Tímida, humillada y avergonzada bajo sus oropeles de mujer pública, la infeliz esperaba humildemente que se le permitiese dar el último beso a su padre. De pronto, éste la reconoció y se pintó en su rostro un sufrimiento inmenso.\"},{\"heading\":false,\"text\":\"--¡Sonia! ¡hija mía!... ¡perdóname!--gritó.\"},{\"heading\":false,\"text\":\"Quiso tender hacia ella la mano, y perdiendo su punto de apoyo rodó pesadamente por el suelo. Se apresuraron a levantarle y le pusieron en el sofá; pero ya todo era inútil. Sonia, casi sin poder sostenerse, lanzó un débil grito, corrió hacia su padre y le besó. El desdichado expiró en los brazos de su hija.\"},{\"heading\":false,\"text\":\"--¡Ha muerto!--exclamó Catalina Ivanovna ante el cadáver de su marido--. ¿Qué hacer ahora? ¿Cómo pagaré el entierro? ¿Cómo daré de comer mañana a mis hijos?\"},{\"heading\":false,\"text\":\"Raskolnikoff se aproximó a la viuda.\"},{\"heading\":false,\"text\":\"--Catalina Ivanovna--le dijo--, la semana pasada me contó su marido toda la vida de usted sin omitir detalle... Puede estar segura de que me habló de usted con verdadero entusiasmo. Desde aquella tarde, al ver cuánto la estimaba, cuánto amaba y honraba a usted, a pesar de su malhadada debilidad, desde aquella tarde, repito, soy su amigo... Permítame, pues, que le ayude a cumplir sus últimos deberes con el difunto. Aquí tiene usted veinte rublos, y si mi presencia puede serle de alguna utilidad... Yo vendré a verla a usted muy pronto... ¡Adiós!\"},{\"heading\":false,\"text\":\"Y salió precipitadamente de la sala; pero al atravesar el descansillo encontró entre el grupo de curiosos a Nikodim Fomitch, que había tenido noticia del accidente e iba a cumplir con los deberes de su cargo llenando las formalidades propias del caso. Desde la escena ocurrida en la oficina de policía, el comisario no había vuelto a ver a Raskolnikoff. Sin embargo, le reconoció en seguida.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿Es usted?--le preguntó.\"},{\"heading\":false,\"text\":\"--Ha muerto--contestó Raskolnikoff--. Le han asistido un médico y un sacerdote; nada le ha faltado. No moleste usted a la pobre viuda; está tísica y su nueva desgracia le será funesta. Consuélela usted... Sé que usted es un hombre muy bueno--añadió sonriendo y mirando frente a frente al comisario.\"},{\"heading\":false,\"text\":\"--Está usted manchado de sangre--dijo Nikodim Fomitch, que acababa de ver algunas manchas recientes en el chaleco de su interlocutor.\"},{\"heading\":false,\"text\":\"--Sí, me ha caído encima... Estoy empapado en sangre--agregó el joven con extraño acento; después, sonrióse, saludó al comisario con un movimiento de cabeza y se alejó.\"},{\"heading\":false,\"text\":\"Bajó la escalera sin apresuramiento. Una especie de fiebre agitaba todo su ser: sentía que una vida potente y nueva brotaba de repente en él. Podía compararse esta sensación a la de un condenado a muerte que recibe a última hora el inesperado indulto. En medio de la escalera se hizo a un lado para dejar pasar al sacerdote que volvía a su domicilio. Lo dos hombres cambiaron un silencioso saludo. Cuando Raskolnikoff bajaba los últimos escalones, oyó pasos presurosos detrás de sí. Alguien trataba de alcanzarle. En efecto, Polenka corría en pos de él gritándole:\"},{\"heading\":false,\"text\":\"--¡Oiga usted, caballero, oiga usted!\"},{\"heading\":false,\"text\":\"Raskolnikoff se volvió. La niña descendió apresuradamente el último tramo y se detuvo enfrente del joven en un escalón por encima de él. Un débil resplandor provenía del patio. Raskolnikoff examinó el rostro demacrado de la niña; Polenka le miraba con alegría infantil que hacía resaltar su delicada belleza. Se le había confiado una misión que, evidentemente, le agradaba mucho.\"},{\"heading\":false,\"text\":\"--Oiga usted, ¿cómo se llama usted?... ¡Ah! ¿Dónde vive usted?--preguntó precipitadamente.\"},{\"heading\":false,\"text\":\"Raskolnikoff le puso las manos en los hombros y la contempló con una especie de felicidad. ¿Por qué experimentaba tal placer mirando a la niña? Ni él mismo lo sabía.\"},{\"heading\":false,\"text\":\"--¿Quién te manda?\"},{\"heading\":false,\"text\":\"--Mi hermana Sonia--respondió la niña sonriendo aún más alegremente.\"},{\"heading\":false,\"text\":\"--Ya suponía yo que venías de parte de tu hermana.\"},{\"heading\":false,\"text\":\"--Sonia me envió primero; pero en seguida mamá me dijo: «Ve corriendo, Polenka.»\"},{\"heading\":false,\"text\":\"--¿Quieres mucho a tu hermana Sonia?\"},{\"heading\":false,\"text\":\"--La quiero más que... a todo el mundo--afirmó con singular energía Polenka, y su sonrisa tomó de repente una expresión seria.\"},{\"heading\":false,\"text\":\"--¿Y a mí me querrás?\"},{\"heading\":false,\"text\":\"En lugar de responder la niña, aproximó la cara a la del joven y presentó cándidamente la boca para besarle. De repente, con sus bracitos delgados como cerillas, estrechó fuertemente a Raskolnikoff, e inclinando la cabeza en el hombro del joven se puso a llorar en silencio.\"},{\"heading\":false,\"text\":\"--¡Pobre papá!--dijo al cabo de un momento, levantando la cabeza y enjugándose las lágrimas con la mano--. Ahora no se ven más que desgracias--añadió sentenciosamente, con esa gravedad particular que afectan los niños cuando quieren hablar como las personas mayores.\"},{\"heading\":false,\"text\":\"--¿Te quería tu papá?\"},{\"heading\":false,\"text\":\"--Quería más a Lidotshka--respondió en el mismo tono serio (su sonrisa había desaparecido),--sentía predilección por ella, porque es la más pequeña y porque está delicada; siempre le traía cosas. Nos enseñaba a leer; me daba lecciones de gramática y doctrina--añadió la niña con dignidad--. Mamá no decía nada; pero nosotros sabíamos que esto le daba gusto y papá también lo sabía. Mamá quiere enseñarme el francés, porque ya es tiempo de comenzar mi educación.\"},{\"heading\":false,\"text\":\"--¿Sabes rezar?\"},{\"heading\":false,\"text\":\"--¡Vaya si sabemos! ¡Desde hace mucho tiempo! Yo, como soy la mayor, rezo sola; Kolia y Lidotshka dicen sus oraciones en voz alta con mamá. Recitan primero las letanías de la Santísima Virgen, luego otra oración: «¡Señor! Concede tu perdón y tu bendición a nuestra hermana Sonia», y luego: «¡Señor! Concede tu perdón y tu bendición a nuestro otro papá», porque no le he dicho a usted que nuestro antiguo papá hace tiempo que murió; éste era otro; pero nosotros rezamos también por el primero.\"},{\"heading\":false,\"text\":\"--Polenka, me llamo Rodión Romanovitch; nómbrame también alguna vez en tus oraciones: «perdona a tu siervo Rodión» y nada más.\"},{\"heading\":false,\"text\":\"--Siempre, siempre rezaré por usted--respondió calurosamente la niña; y echándose a reír, besó de nuevo al joven con ternura.\"},{\"heading\":false,\"text\":\"Raskolnikoff le repitió su nombre, le dió las señas y le prometió volver al otro día sin falta. La niña se separó de él encantada. Eran las diez dadas cuando salía de la casa.\"},{\"heading\":false,\"text\":\"No le costó trabajo encontrar la habitación de Razumikin; en casa de Potchinkoff conocían a su nuevo inquilino y el _dvornik_ indicó en seguida a Raskolnikoff el cuarto de su amigo. Hasta la mitad de la escalera llegaba la algazara de la reunión que debía ser numerosa y animada. La puerta estaba abierta y se oía el ruido de las voces.\"},{\"heading\":false,\"text\":\"La estancia de Razumikin era bastante grande; la reunión se componía de unas quince personas. Raskolnikoff se detuvo en la antesala; detrás del tabique había dos grandes samovars, botellas, platos y fuentes cargados de pastas; dos criados de la patrona se agitaban en medio de todo aquello. Raskolnikoff hizo que llamasen a Razumikin. Este se presentó muy contento. A la primera ojeada se adivinaba que había bebido con exceso; y aunque en general a Razumikin le fuese imposible emborracharse, por esta vez probaba su exterior que no había podido contenerse.\"},{\"heading\":false,\"text\":\"--Escucha--comenzó a decir Raskolnikoff--, he venido con el solo objeto de decirte que, en efecto, has ganado la apuesta y que nadie sabe lo que puede pasar. En cuanto a entrar ahí, no; estoy muy débil; apenas si puedo tenerme en pie. De modo que, buenas noches, y adiós. Mañana pásate por mi casa.\"},{\"heading\":false,\"text\":\"--¿Sabes tú lo que voy a hacer? Acompañarte. Según tu propia confesión, estás débil.\"},{\"heading\":false,\"text\":\"--¿Y tus invitados? ¿Quién es ese hombre de cabello rizado que acaba de entreabrir la puerta?\"},{\"heading\":false,\"text\":\"--¿Ese? ¿Quién lo sabe? Debe de ser un amigo de mi tío o acaso un señor cualquiera que ha venido sin invitación... Los dejaré con mi tío; es un hombre inapreciable; siento que no puedas trabar conocimiento con él. Por lo demás, que el diablo se los lleve. Nada tengo que hacer ahora con ellos; necesito tomar el aire, de modo que has llegado a propósito, amigo mío: dos minutos más tarde, hubiera caído sobre ellos. ¡Dicen tales majaderías! No puedes imaginarte de qué divagaciones suelen algunos hombres ser capaces. Digo, si puedes imaginártelo. ¿Acaso nosotros no divagamos también? ¡Ea! dejémosles decir necedades; no siempre tendrán ocasión de colocarlas... Espera un momentito; voy a traer a Zosimoff.\"},{\"heading\":false,\"text\":\"El doctor acudió con extraordinario apresuramiento a ver a Raskolnikoff. Al echar la vista encima a su cliente se manifestó en su rostro una gran curiosidad que bien pronto se desvaneció.\"},{\"heading\":false,\"text\":\"--Es menester que se acueste usted en seguida--dijo al enfermo--; y tome un calmante para procurarse un sueño apacible. Aquí tiene usted esos polvos que yo he preparado hace poco. ¿Los tomará usted?\"},{\"heading\":false,\"text\":\"--Ciertamente--respondió Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Harás bien en acompañarle--dijo Zosimoff dirigiéndose a Razumikin--; veremos mañana cómo está; hoy no va mal. Ha cambiado mucho en poco tiempo. Cada día se aprende una cosa nueva.\"},{\"heading\":false,\"text\":\"--¿Sabes lo que Zosimoff me decía hace un momento por lo bajo?--comenzó a decir con voz pastosa Razumikin, cuando los dos amigos estuvieron en la calle--. Me recomendaba que hablase contigo en el camino, que te hiciera hablar y que le contase en seguida tus palabras, porque se le ha metido entre ceja y ceja que estás loco o que te encuentras a punto de estarlo. ¿Qué te parece? En primer lugar, tú eres tres veces más inteligente que él. En segundo lugar, puesto que no estás loco puedes burlarte de su estúpida opinión, y en tercer lugar, ese hombrón, cuya especialidad es la cirugía, sólo tiene en la cabeza, desde hace algún tiempo, enfermedades mentales; pero la conversación que has tenido tú hoy con Zametoff, ha modificado por completo sus apreciaciones sobre tu persona.\"},{\"heading\":false,\"text\":\"--¿Zametoff te lo ha contado todo?\"},{\"heading\":false,\"text\":\"--Todo y ha hecho muy bien. He comprendido ahora toda la historia y Zametoff también. ¡Vamos! Sí, en una palabra, Rodia... El hecho es que... En este momento me encuentro un poco alegre... pero no importa... El hecho es que aquel pensamiento... ¿Comprendes? Aquel pensamiento había nacido, en efecto, en su espíritu; es decir, ninguno de ellos se atrevía a formularlo en alta voz, porque era una cosa demasiado absurda, sobre todo desde que ha sido detenido ese pintor de brocha gorda, todo se ha desvanecido para siempre. Pero, ¿cómo son tan imbéciles? Aquí para entre nosotros, he tenido un choque con Zametoff; te suplico que no te des por entendido; he notado que es susceptible. Ese incidente ocurrió en casa de Luisa... Pero actualmente todo está esclarecido. Fué principalmente ese Ilia Petrovitch quien se fundaba en tu desvanecimiento en la comisaría; pero a él mismo le dió vergüenza luego de semejante suposición; yo sé...\"},{\"heading\":false,\"text\":\"Raskolnikoff escuchaba con avidez. Bajo la influencia de la bebida, Razumikin hablaba sin tino.\"},{\"heading\":false,\"text\":\"--Yo me desvanecí entonces porque hacía demasiado calor en la sala y porque el olor de la pintura me trastornó--contestó.\"},{\"heading\":false,\"text\":\"--El busca una explicación, pero no hay otra que la de la pintura: la inflamación estaba latente desde hacía un mes. Ahí está Zosimoff para decirlo. No puedes figurarte lo confuso que se siente ahora ese tonto de Zametoff: «Yo no valgo--dice--ni lo que el dedo pequeño de ese hombre». Así habla refiriéndose a ti. Algunas veces tienen buenos sentimientos; pero la lección que le has dado hoy en el _Palacio de Cristal_ es el colmo de la perfección: has comenzado por hacer que tuviese miedo, que temblase. Le hiciste pensar de nuevo en esa monstruosa tontería, y de repente le has mostrado que te burlabas de él. ¡Se ha quedado con un palmo de narices! Perfectamente. Ahora está aplastado, anonadado. Verdaderamente eres un maestro y le hacía falta lo que has hecho. Siento no haber estado allí. Zametoff está ahora en casa y hubiera querido verte. También desea verte Porfirio Petrovitch.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿Ese también? Pero, ¿por qué se me considera como un loco?\"},{\"heading\":false,\"text\":\"--Como un loco precisamente, no. Amigo mío, yo creo que me he ido un poco de la lengua contigo. Lo que supongo que le ha preocupado más que nada es que sólo _eso_ te interesa, y ahora comprende por qué te interesa: conociendo todas las circunstancias... sabiendo qué especie de enervamiento te ha causado eso y como tal cosa se relaciona con tu enfermedad... Estoy algo chispo, amigo mío; cuanto puedo decirte es que él tiene su idea... te lo repito, no sueña más que con sus enfermedades mentales; no, no tienes por qué inquietarte.\"},{\"heading\":false,\"text\":\"Durante medio minuto ambos guardaron silencio.\"},{\"heading\":false,\"text\":\"--Escucha, Razumikin--dijo Raskolnikoff--. Quiero hablarte con franqueza: vengo de casa de un muerto; el difunto era un funcionario... He dado allí todo mi dinero... y además de eso hace un instante he sido besado por una criatura que, aun cuando yo hubiese matado a alguien... en una palabra, he visto allí también a una joven... con una pluma color de fuego, pero divago; estoy muy débil, sostenme... Aquí está la escalera.\"},{\"heading\":false,\"text\":\"--¿Qué tienes? ¿Qué te pasa?--preguntó Razumikin alarmado.\"},{\"heading\":false,\"text\":\"--La cabeza que me da vueltas; pero esto no es nada; lo malo es que estoy tan triste... como una mujer. Mira: ¿qué es aquello? mira, mira...\"},{\"heading\":false,\"text\":\"--¿Qué he de mirar?\"},{\"heading\":false,\"text\":\"--¿No ves? Hay luz en mi cuarto, ¿no lo estás viendo por la rendija?\"},{\"heading\":false,\"text\":\"Estaban en el último rellano de la escalera, cerca de la puerta de la patrona, desde donde se podía advertir, que, en efecto, en la habitación de Raskolnikoff había luz.\"},{\"heading\":false,\"text\":\"--Es extraño.\"},{\"heading\":false,\"text\":\"--Estará quizá en ella Anastasia--observó Razumikin.\"},{\"heading\":false,\"text\":\"--No viene nunca a mi cuarto a esa hora. Además, se acuesta muy temprano; pero, ¿qué importa? Adiós.\"},{\"heading\":false,\"text\":\"--¡Eh! ¿qué dices? Te acompaño, vamos a subir juntos.\"},{\"heading\":false,\"text\":\"--Sí que subiremos juntos; pero quiero estrecharte la mano y decirte adiós aquí. Vamos, dame la mano. Adiós.\"},{\"heading\":false,\"text\":\"--¿Qué te pasa, Rodia?\"},{\"heading\":false,\"text\":\"--Nada. Subamos y tú serás testigo...\"},{\"heading\":false,\"text\":\"Mientras subían la escalera se le ocurrió a Razumikin que Zosimoff tenía quizás razón.\"},{\"heading\":false,\"text\":\"--Sin duda le he perturbado el espíritu con mi charla--dijo para sí.\"},{\"heading\":false,\"text\":\"Cuando se acercaban a la puerta oyeron voces en la habitación.\"},{\"heading\":false,\"text\":\"--¿Qué es esto?--exclamó Razumikin.\"},{\"heading\":false,\"text\":\"Raskolnikoff tiró de la puerta y la abrió de par en par, quedándose en el umbral como petrificado.\"},{\"heading\":false,\"text\":\"Su madre y su hermana, sentadas en el sofá, le esperaban hacía media hora.\"},{\"heading\":false,\"text\":\"La aparición de Raskolnikoff fué saludada con gritos de alegría. Su madre y su hermana corrieron hacia él; pero el joven quedó inmóvil, y casi privado de sentido; había como helado todo su ser un pensamiento súbito e insoportable. Ni siquiera tuvo fuerza para abrir los brazos. Las dos mujeres le estrecharon contra su pecho, le cubrieron de besos, llorando y riendo al mismo tiempo; Raskolnikoff dió un paso, se tambaleó y cayó desvanecido al suelo.\"},{\"heading\":false,\"text\":\"Alarma, gritos de terror, gemidos. Razumikin, que se había quedado en el umbral, se precipitó en la sala, tomó al enfermo en sus vigorosos brazos y en un abrir y cerrar de ojos le echó en el diván.\"},{\"heading\":false,\"text\":\"--No es nada, no es nada--dijo a la madre y a la hermana--. Esto es un desvanecimiento, no tiene importancia. El médico decía hace un momento que va mucho mejor, que estaba casi restablecido. ¡Un poco de agua! Vamos, ya recobra el conocimiento; miren ustedes, ya vuelve en sí.\"},{\"heading\":false,\"text\":\"Y al decir esto apretaba con inconsciente rudeza el brazo de Dunia obligándola a inclinarse sobre el sofá para comprobar que, en efecto, su hermano volvía en sí.\"},{\"heading\":false,\"text\":\"TERCERA PARTE\"}]},{\"title\":\"tercera parte — capítulo I\",\"blocks\":[{\"heading\":false,\"text\":\"Raskolnikoff se incorporó y se sentó en el diván, e invitando con una leve seña a Razumikin a que suspendiese el curso de su elocuencia consoladora, tomó la mano a su hermana y a su madre y las contempló alternativamente durante dos minutos, sin proferir palabra. Había en su mirada, impregnada de dolorosa sensibilidad, algo de fijo y de insensato. Pulkeria Alexandrovna, asustada, se echó a llorar.\"},{\"heading\":false,\"text\":\"Advocia Romanovna estaba pálida y le temblaba la mano que tenía entre las de su hermano.\"},{\"heading\":false,\"text\":\"--Vuélvete a casa con él--dijo Rodia con voz entrecortada, señalando a Razumikin--. Mañana, mañana... todo. ¿Cuándo habéis llegado?\"},{\"heading\":false,\"text\":\"--Esta noche--respondió Pulkeria Alexandrovna--. El tren traía mucho retraso. Pero ahora, Rodia, por nada del mundo consentiría en separarme de ti. Pasaré la noche a tu lado...\"},{\"heading\":false,\"text\":\"--¡No me atormentéis!--replicó Raskolnikoff con cierta irritación.\"},{\"heading\":false,\"text\":\"--Yo me quedaré aquí con él--saltó vivamente Razumikin--; no le dejaré ni un minuto, y que se vayan al diablo mis convidados. Que se incomoden, si quieren. Además, allí está mi tío para hacer el papel de anfitrión.\"},{\"heading\":false,\"text\":\"--¡Cómo agradecérselo a usted!--empezó a decir Pulkeria Alexandrovna, estrechando de nuevo las manos de Razumikin; pero su hijo le atajó la palabra.\"},{\"heading\":false,\"text\":\"--No puedo, no puedo...--repitió con tono irritado--; no me atormentéis más. Basta, idos; ¡no puedo!...\"},{\"heading\":false,\"text\":\"--Retirémonos, mamá--indicó en voz baja Dunia, inquieta--; salgamos de la habitación, por lo menos, un instante; está visto que nuestra presencia le atormenta.\"},{\"heading\":false,\"text\":\"--¿Será posible que no pueda estar un momento con él, después de tres años de separación?--gimió Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"--Esperad un poco--dijo Raskolnikoff--. Me interrumpís y pierdo el hilo de mis ideas... ¿Habéis visto a Ludjin?\"},{\"heading\":false,\"text\":\"--No, Rodia; pero ya tiene noticias de nuestra llegada. Sabemos que ha tenido la bondad de venir a verte hoy--añadió con cierta timidez Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"--Sí. Ha tenido esa bondad... Dunia, le dije a Ludjin que iba a tirarle por la escalera...\"},{\"heading\":false,\"text\":\"--¿Qué dices, hijo? Pero, ¿tú? ¿Tú?... No es posible--comenzó a decir la madre asustada; pero una mirada de Dunia le impidió continuar.\"},{\"heading\":false,\"text\":\"Advocia Romanovna, con los ojos fijos en su hermano, esperaba que éste se explicase con mayor claridad. Informadas de la querella por Anastasia, que se la había contado a su manera y según la entendió, las dos señoras se encontraban perplejas.\"},{\"heading\":false,\"text\":\"--Dunia--prosiguió, haciendo un esfuerzo, Raskolnikoff--, yo me opongo a ese enlace; por consiguiente, despide mañana a Ludjin y que no se vuelva a hablar más de él.\"},{\"heading\":false,\"text\":\"--¡Dios mío!--exclamó Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"--Hermano mío, piensa un poco en lo que dices--observó con vehemencia Dunia; pero en seguida se contuvo--. No te encuentras ahora en tu estado normal: estás fatigado--añadió con tono cariñoso.\"},{\"heading\":false,\"text\":\"--Que deliro, ¿no es eso? No... te engañas; quieres casarte con Ludjin por mí, pero yo rehuso ese sacrificio. Así, pues, mañana le escribes una carta rompiendo tu compromiso, me la lees a primera hora, la mandas, y asunto concluído.\"},{\"heading\":false,\"text\":\"--Yo no puedo hacer eso--exclamó la joven, un tanto mortificada--. ¿Con qué derecho...?\"},{\"heading\":false,\"text\":\"--Dunia, tú también te exaltas. Hasta mañana... ¿Pero no estás viendo?--balbuceó la madre con temor, dirigiéndose a su hija--. Vamos, vamos; será lo mejor.\"},{\"heading\":false,\"text\":\"--No sabe lo que se dice--exclamó Razumikin con voz que denunciaba su embriaguez--; de lo contrario, no se permitiría... Mañana será razonable... Hoy, en efecto, ha echado con cajas destempladas a ese sujeto; el buen señor se ha incomodado. Estuvo aquí perorando en pro de sus teorías. Después se marchó con las orejas gachas.\"},{\"heading\":false,\"text\":\"--¿De modo que es verdad?--exclamó Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"--Hasta mañana, hermano--dijo con tono compasivo Dunia--. Vámonos, mamá... Adiós, Rodia.\"},{\"heading\":false,\"text\":\"El joven hizo un último esfuerzo para dirigirle algunas palabras.\"},{\"heading\":false,\"text\":\"--Oyeme; no deliro. Ese casamiento sería una infamia. Pase que yo sea un infame... pero tú, tú no debes serlo... Basta con uno... Mas, por miserable que yo sea, renegaría de ti, si contrajeses esa unión. O yo, o Ludjin. Marchaos.\"},{\"heading\":false,\"text\":\"--Pero, ¿has perdido el juicio? ¡Eres un déspota!--gritó Razumikin.\"},{\"heading\":false,\"text\":\"Raskolnikoff no respondió; quizá no se hallaba en estado de hacerlo. Agotadas sus fuerzas, se tendió en el diván, volviéndose del lado de la pared. Advocia Romanovna miró a Razumikin con ojos brillantes que revelaban curiosidad. El estudiante tembló ante aquella mirada. Pulkeria Alexandrovna parecía consternada.\"},{\"heading\":false,\"text\":\"--No me resuelvo a irme--murmuró trémula, al oído de Razumikin--; me quedaré aquí en cualquier parte... Acompañe usted a Dunia.\"},{\"heading\":false,\"text\":\"--Lo echarán ustedes a perder todo--respondió, también en voz baja, Razumikin--. Salgamos, a lo menos, de este cuarto. Anastasia, alúmbranos. Juro a ustedes--continuó en voz queda cuando estuvieron en la escalera--que hace poco rato estuvo a punto de pegarnos al médico y a mí. Figúrese usted, ¡al médico! Por otra parte, es imposible que deje usted sola a Advocia Romanovna en el cuarto de alquiler que han tomado ustedes. ¡Si supieran ustedes en qué casita se han alojado! Ese pillo de Pedro Petrovitch, ¿no podía haber encontrado una más decente?... Yo, es cierto, estoy algo chispo, y ahí tiene usted por qué son mis expresiones bastante vivas. No hagan ustedes caso.\"},{\"heading\":false,\"text\":\"--Pues bien--replicó Pulkeria Alexandrovna--. Voy a ver a la patrona de mi hijo y a suplicarle que nos deje pasar la noche en cualquier rincón. No puedo abandonarle en tal estado, no puedo...\"},{\"heading\":false,\"text\":\"Hablaban en el rellano de la escalera correspondiente a la habitación de la patrona. Anastasia estaba en el último escalón, con la luz en la mano. Razumikin se hallaba extraordinariamente animado. Un poco antes, cuando acompañó a Raskolnikoff a su casa, se había ido de la lengua como él mismo había reconocido; pero tenía la cabeza fuerte y despejada, no obstante la excesiva cantidad de vino que acababa de beber. Ahora estaba sumido en una especie de éxtasis, y la influencia excitante del alcohol obraba doblemente sobre él. Había tomado a las dos señoras a cada una por una mano, las arengaba con un lenguaje de una desenvoltura asombrosa, y, sin duda, para convencerlas mejor, apoyaba cada una de sus palabras con formidable presión de las falanges de sus interlocutoras. Al propio tiempo, con el mayor descaro devoraba con los ojos a Advocia Romanovna.\"},{\"heading\":false,\"text\":\"A veces, vencidas por el dolor, las pobres señoras trataban de separar sus dedos aprisionados en aquellas manos gruesas y huesosas; pero él no hacía caso, y continuaba apretando sin cuidarse de que les hacía daño. Si le hubieran pedido que se tirase de cabeza por la escalera, no habría vacilado un segundo en obedecerlas. Pulkeria Alexandrovna se hacía cargo de que Razumikin era muy original, y, sobre todo, de que tenía unos puños terribles; pero, con el pensamiento puesto en su hijo, cerraba los ojos ante las extrañas maneras del joven, que era en aquel momento una Providencia para ellas.\"},{\"heading\":false,\"text\":\"Por su parte, Advocia Romanovna, aunque participaba de las preocupaciones de su madre, y no fuese de natural tímido, miraba con sorpresa y aun con algo de inquietud, las ardientes ojeadas que le dirigía el amigo de su hermano. A no ser por la confianza sin límites que los relatos de Anastasia le habían inspirado a propósito de aquel hombre singular, no hubiera resistido a la tentación de echar a correr, llevándose a su madre con ella. Comprendía, empero, también que en aquel momento el joven les hacía mucha falta. Esto no obstante, la joven se sintió tranquila al cabo de diez minutos; cualquiera que fuese la disposición de ánimo en que se encontraba Razumikin, una de las propiedades de su carácter era la de revelarse por completo a primera vista, de suerte que en seguida sabía uno a qué atenerse respecto de él.\"},{\"heading\":false,\"text\":\"--Usted no puede solicitar eso de la patrona; sería el colmo de lo absurdo--contestó vivamente a Pulkeria Alexandrovna--. De nada le valdría ser la madre de Rodión; si usted se queda, va a exasperarle, y sabe Dios lo que puede ocurrir. Escuchen ustedes lo que yo les propongo: Anastasia va a quedarse ahora con él, y las acompañaré a ustedes a su casa, porque en San Petersburgo es una imprudencia que anden dos mujeres solas por las calles. Después de haber yo acompañado a ustedes, volveré aquí de dos zancadas, y un cuarto de hora después doy a ustedes mi palabra de honor de que iré allí de nuevo y les contaré todo: cómo está, si duerme, etc. En seguida, escuchen ustedes, en seguida, echo a correr a mi casa; hay mucha gente en ella. Mis invitados están ebrios. Echaré el guante a Zosimoff que es el médico que asiste a Rodia y se halla ahora en mi casa; pero no está borracho porque es abstemio; lo llevaré a ver el enfermo, y de allí a casa de ustedes. En el espacio de una hora recibirán ustedes, por consiguiente, noticias de su hijo; primero, por mí, y después, por el mismo doctor, que es hombre serio. Si Rodia está mal, juro a usted que la traeré otra vez aquí; si está bien se acostará usted. Yo pasaré toda la noche en el vestíbulo, él no lo sabrá. Haré que Zosimoff se acueste en casa de la patrona, para tenerle a mano, si fuese necesario. Creo que en estos momentos la presencia del médico puede ser más útil a Raskolnikoff que la de usted. Por lo tanto, vamos a su casa. Yo puedo, pero ustedes, no, no consentiría en dar a ustedes posada, porque... porque es tonta. Si lo quieren ustedes saber, está enamorada de mí, tendría celos de Advocia Romanovna, y de usted también; pero, de seguro, de Advocia Romanovna. Es un carácter muy extraño. Yo también soy un imbécil. Vamos, vengan ustedes. Tienen confianza en mí, ¿verdad? ¿La tienen ustedes? Sí, o no.\"},{\"heading\":false,\"text\":\"--Vamos, mamá--dijo Advocia Romanovna--; lo que promete, lo hará seguramente. A sus cuidados debe mi hermano la vida; y si el doctor consiente, en efecto, en pasar aquí la noche, ¿qué más podemos desear?\"},{\"heading\":false,\"text\":\"--Usted me comprende, porque es usted un ángel--dijo Razumikin con exaltación--. Vamos, Anastasia, sube en seguida con la luz, y quédate a su lado. Vuelvo dentro de un cuarto de hora.\"},{\"heading\":false,\"text\":\"Aunque no estuviese completamente convencida, Pulkeria Alexandrovna no hizo ninguna objeción.\"},{\"heading\":false,\"text\":\"Razumikin tomó a cada una de las dos señoras por un brazo y, en parte de grado, y en parte por fuerza, las obligó a bajar la escalera.\"},{\"heading\":false,\"text\":\"La madre no dejaba de estar inquieta.\"},{\"heading\":false,\"text\":\"«Seguramente sabe lo que hace; está bien dispuesto con nosotras; pero, ¿podremos confiar en sus promesas en el estado en que se encuentra?»\"},{\"heading\":false,\"text\":\"El joven adivinó aquel pensamiento.\"},{\"heading\":false,\"text\":\"--¡Ah! Comprendo. Usted me cree bajo la influencia del vino--dijo andando a grandes pasos por la acera, sin advertir que apenas podían seguirle las dos señoras--. Esto no significa nada... he bebido como un bruto; pero no se trata de tal cosa. No es el vino lo que me embriaga. En cuanto he visto a ustedes, he recibido como un golpe en la cabeza.... No me hagan ustedes caso, no digo más que tonterías, soy indigno de ustedes. En extremo indigno... En cuanto las lleve a ustedes a su casa, iré al canal que hay aquí cerca y me echaré un cubo de agua por la cabeza. Si supiesen lo que yo las quiero a ustedes... No se rían, ni se incomoden... Enfádense ustedes con todo el mundo menos conmigo. Yo soy amigo de Raskolnikoff, y, por consiguiente, de ustedes. Presentía el año pasado lo que ahora está sucediendo; hubo un momento... Pero no, yo no presentía nada de esto, puesto que ustedes, por decirlo así, han caído del cielo; mas no dormiré en toda la noche... Zosimoff temía hace poco que se volviese loco. He aquí por qué no conviene irritarle.\"},{\"heading\":false,\"text\":\"--¿Qué dice usted?--exclamó la madre.\"},{\"heading\":false,\"text\":\"--¿Es posible que el doctor haya dicho eso?--preguntó Advocia Romanovna asustada.\"},{\"heading\":false,\"text\":\"--Eso ha dicho, pero se engaña, se engaña de medio a medio. Le ha recetado un medicamento, unos polvos, pero, ya hemos llegado... Hubieran ustedes hecho mejor en venir mañana. Hemos hecho bien retirándonos. Dentro de una hora Zosimoff vendrá a darle a usted noticias de su salud. No está ebrio; yo tampoco lo estaré. Pero, ¿por qué estoy tan excitado? ¡Me han hecho discurrir tanto esos malditos! Había jurado no tomar parte en esas discusiones. ¡Dicen tantas majaderías! Un poco más y me agarro con ellos. He dejado allí a mi tío para que presida la reunión... ¿Creerán ustedes que son partidarios de la impersonalidad completa? Para ellos el supremo progreso es parecerse lo menos posible a sí mismo. A los rusos nos ha complacido vivir de ideas ajenas; ya estamos saturados de ellas. ¿Es verdad, es verdad lo que digo?--gritó Razumikin apretando las manos de las dos señoras.\"},{\"heading\":false,\"text\":\"--¡Oh Dios mío, yo no sé!--dijo la pobre Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"--Sí, sí, aunque yo no estoy de acuerdo con ustedes, en líneas generales--añadió con tono grave Advocia Romanovna.\"},{\"heading\":false,\"text\":\"Apenas acababa de pronunciar estas palabras, cuando lanzó un grito de dolor provocado por un enérgico apretón de manos de Razumikin.\"},{\"heading\":false,\"text\":\"--¿Sí? ¿usted, dice que sí? Pues bien, usted es, usted es--vociferó el joven entusiasmado--; usted es una fuente de bondad, de pureza, de razón y de perfección. Déme usted las manos... déme usted también la suya; quiero besar las manos a ustedes. Aquí mismo, en seguida, de rodillas.\"},{\"heading\":false,\"text\":\"Se arrodilló en medio de la calle, que por fortuna estaba desierta en aquel momento.\"},{\"heading\":false,\"text\":\"--¡Basta! ¡Por Dios! ¿qué hace usted?--exclamó Pulkeria Alexandrovna alarmada ante la actitud del estudiante.\"},{\"heading\":false,\"text\":\"--¡Levántese usted, levántese usted!--dijo Dunia, que, aunque se reía, no dejaba de estar inquieta.\"},{\"heading\":false,\"text\":\"--¡De ninguna manera, si no me dan ustedes las manos! Así. Ahora continuemos. Soy un desgraciado imbécil indigno de ustedes, y en este momento trastornado por la bebida... Me avergüenzo... Soy indigno de amar a ustedes... pero inclinarse, prosternarse delante de ustedes, es el deber de cualquiera que no sea un bruto completo. Por eso me he prosternado yo... Esta es la casa. Aunque no sea más que por esto ha hecho bien Rodia en poner en la calle el otro día a Pedro Petrovitch. ¡Cómo se ha atrevido a traer a ustedes aquí! Esto es escandaloso. ¿Saben ustedes qué clase de gente vive aquí? ¿Y usted es su prometida? ¿Sí? Pues bien. Después de esto declaro que su futuro esposo de usted es un canalla.\"},{\"heading\":false,\"text\":\"--Escuche usted, señor Razumikin--comenzó a decir Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"--Sí, sí, tiene usted razón. Yo me he olvidado--dijo excusándose el joven--, pero... pero usted no puede guardarme rencor por mis palabras. He hablado así, porque soy franco y no porque... ¡hum!... sería innoble; en una palabra, no es porque a usted yo... ¡hum!... no me atrevo a acabar... Pero antes, cuando su visita, hemos comprendido todos que ese hombre no era de nuestro mundo. ¡Vamos! ¡Basta!, todo está perdonado. ¿No es cierto que usted me ha perdonado? ¡Ea! ¡adelante! Conozco este corredor. He estado aquí ya; ahí en el número tres hubo una vez un escándalo... ¿Cuál es el cuarto de ustedes? ¿Qué número? ¿Ocho? Entonces harán ustedes muy bien encerrándose en su habitación por la noche, y no dejando entrar a nadie. Dentro de quince minutos, traeré noticias, y media hora después me verán ustedes volver con Zosimoff; escapo.\"},{\"heading\":false,\"text\":\"--¡Dios mío! Dunetshka, ¿qué va a ocurrir?--dijo ansiosamente Pulkeria Alexandrovna a su hija.\"},{\"heading\":false,\"text\":\"--Tranquilízate, mamá--respondió Dunia, quitándose el chal y el sombrero--. Dios mismo nos ha enviado a ese señor; aunque venga de una orgía se puede contar con él. Te lo aseguro... y lo que ha hecho por mi hermano...\"},{\"heading\":false,\"text\":\"--¡Ah, Dunetchka! ¡Dios sabe si volverá! ¡Cómo he podido resolverme a dejar a Rodia!... ¡Cuán de otra manera pensaba encontrarle! ¡Qué acogida nos ha hecho! ¡Cualquiera diría que le disgustaba nuestra llegada!\"},{\"heading\":false,\"text\":\"En sus ojos brillaban las lágrimas.\"},{\"heading\":false,\"text\":\"--No, no es eso, mamá, no lo has visto bien, estás llorando siempre. Acaba de sufrir una grave enfermedad y ésa es la causa de todo.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡Esa enfermedad! ¡Qué resultará de todo eso! ¡Cómo te ha hablado, Dunia!--siguió diciendo la madre, procurando tímidamente leer en los ojos de la joven, y sintiéndose casi consolada porque Dunia tomaba la defensa de su hermano, y por consiguiente, le había perdonado--. Bien sé que mañana será de otra opinión--añadió, queriendo hacer hablar a su hija.\"},{\"heading\":false,\"text\":\"--Pues yo estoy cierta de que mañana dirá lo mismo, respecto de este asunto...--replicó Advocia Romanovna.\"},{\"heading\":false,\"text\":\"La cuestión era tan delicada, que Pulkeria Alexandrovna no se atrevió a proseguir la conversación. Dunia fué a besar a su madre. Esta, sin decir nada, la estrechó fuertemente en sus brazos. Después se sentó y esperó con cruel impaciencia la llegada de Razumikin, mirando tímidamente a su hija, que, pensativa y con los brazos cruzados, se paseaba de un lado a otro de la habitación. Era una costumbre en Advocia Romanovna pasearse así cuando tenía una preocupación, y en tales casos, su madre se guardaba muy bien de interrumpir sus reflexiones.\"},{\"heading\":false,\"text\":\"Razumikin, embriagado y enamorándose repentinamente de Advocia Romanovna, se prestaba ciertamente al ridículo. Sin embargo, contemplando a la joven, sobre todo ahora que, pensativa y triste, se paseaba por la habitación con los brazos cruzados, quizá muchos habrían disculpado al estudiante, sin necesidad de invocar en descargo suyo la circunstancia atenuante de la embriaguez. El exterior de Advocia Romanovna merecía atraer la atención: alta, fuerte, notablemente bien formada, demostraba en cada uno de sus ademanes una confianza en sí misma que en otra parte no quitaba nada a su gracia y delicadeza. Se parecía a su hermano, pero de ella podía decirse que era una beldad. Tenía el cabello castaño, algo más claro que los de Rodia; sus ojos, negros, denotaban orgullo; pero en ocasiones demostraban extraordinaria bondad. Era pálida, pero su palidez no tenía nada de enfermizo; su rostro resplandecía de frescura y de salud. Tenía la boca bastante pequeña, y el labio inferior de subido color rojo avanzaba, un poco, lo mismo que la barbilla. Esta irregularidad, la única que se notaba en su hermoso rostro, le daba una expresión particular de firmeza y casi altanería. Su fisonomía era de ordinario más bien grave y pensativa que alegre; pero, ¡qué encanto el de aquella cara habitualmente seria cuando venía a animarla una risa alegre y juvenil!\"},{\"heading\":false,\"text\":\"Razumikin no había visto jamás nada semejante; era ardiente, sincero, honrado, un poco candoroso. Además, fuerte como un caballero antiguo y entonces exaltado por el vino. En estas condiciones se explica perfectamente el _coup de foudre_. Además, quiso la suerte que viese por primera vez a Dunia en un momento en que la ternura y la alegría de volver a ver a Raskolnikoff habían en cierto modo transfigurado el semblante de la joven. La vió, después, soberbia de indignación ante las insolentes órdenes de su hermano y no pudo contenerse.\"},{\"heading\":false,\"text\":\"Por lo demás, había dicho verdad cuando en su charla de borracho dejó traslucir que la extravagante patrona de Raskolnikoff, Praskovia Pavlovna, tendría celos, no sólo de Advocia Romanovna, sino de la misma Pulkeria Alexandrovna. Aunque ésta tenía cuarenta y tres años, conservaba restos de su antigua belleza, y parecía además mucho más joven de lo que era en realidad; particularidad que se observa en las mujeres que han conservado en los linderos de la vejez la claridad de su espíritu, la frescura de las impresiones, el puro y honrado calor del corazón. Comenzaban ya a blanquearle los cabellos y aun a faltarle; advertíanse ya, desde hacía algún tiempo, algunas arrugas en derredor de los ojos; los cuidados y los disgustos habían demacrado sus mejillas; mas, a pesar de todo, su rostro era bello. Era el rostro de Dunia con veinte años más y sin lo prominente del labio inferior que caracterizaba la fisonomía de la joven. Pulkeria Alexandrovna tenía alma sensible; pero sin llegar a la sensiblería. Naturalmente tímida y dispuesta a ceder, sabía, sin embargo, detenerse en el camino de las concesiones, siempre que su honradez, sus principios y sus convicciones arraigadas se lo exigían.\"},{\"heading\":false,\"text\":\"A los veinte minutos justos de salir Razumikin, sonaron en la puerta dos leves golpes: el joven estaba ya de vuelta.\"},{\"heading\":false,\"text\":\"--No entraré, no tengo tiempo--se apresuró a decir en cuanto abrieron--. Duerme como un bienaventurado, su sueño es muy tranquilo, y quiera Dios que se pase así durmiendo diez horas seguidas. Anastasia está a su lado; tiene orden de permanecer allí hasta que yo vuelva. Ahora voy a buscar a Zosimoff, vendrá a dar a ustedes sus informes, y en seguida a acostarse, porque bien veo que están ustedes extenuadas.\"},{\"heading\":false,\"text\":\"Apenas hubo acabado de decir estas palabras, echó a correr por el corredor.\"},{\"heading\":false,\"text\":\"--¡Qué joven tan simpático y tan cariñoso!--exclamó Pulkeria Alexandrovna muy alegre.\"},{\"heading\":false,\"text\":\"--Parece que es de muy buen carácter--contestó Dunia, y comenzó a pasearse de nuevo por la habitación.\"},{\"heading\":false,\"text\":\"Cerca de una hora después, volvieron a sonar pasos en el corredor y llamaron de nuevo a la puerta. Ahora las dos mujeres esperaban con entera confianza el cumplimiento de la promesa que les había hecho Razumikin. Volvió éste, en efecto, acompañado de Zosimoff. El médico no había vacilado en dejar inmediatamente el banquete para ir a visitar a Raskolnikoff; pero no sin trabajo se decidió a ir a casa de las señoras, porque apenas daba crédito a las palabras de su amigo, que le parecía haber dejado una parte de su razón en el fondo de los vasos. Sin embargo, muy pronto se sintió satisfecho y aun halagado en su amor propio de doctor. Zosimoff comprendió que era, en efecto, escuchado como un oráculo.\"},{\"heading\":false,\"text\":\"Durante diez minutos que duró la visita, logró tranquilizar por completo a Pulkeria Alexandrovna. Manifestó gran interés por el enfermo, expresándose con reserva y seriedad extremadas como conviene a un médico de veintisiete años en circunstancias graves. No se permitió la más leve digresión fuera de su asunto ni manifestó el menor deseo de entablar más relaciones familiares con sus interlocutoras. Habiendo advertido desde que entró la belleza de Advocia, se esforzaba en no prestar ninguna atención a la joven, dirigiéndose exclusivamente a Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"Todo esto le producía un indecible contento interior. En lo concerniente a Raskolnikoff, declaró que le encontraba en un estado muy satisfactorio. Según su opinión, la enfermedad de su cliente dependía, en parte, de las malas condiciones en que éste había vivido durante algunos meses; pero era originada también por otras causas de carácter moral. «Era, por decirlo así, producto complejo de influencias múltiples, bien físicas, bien psicológicas, tales como preocupaciones, cuidados, temores, inquietudes, etc.» Habiendo advertido, sin manifestarlo, que Advocia Romanovna le escuchaba con marcada atención, Zosimoff desarrolló con gusto este tema.\"},{\"heading\":false,\"text\":\"Como Pulkeria Alexandrovna le preguntase con voz tímida e inquieta si había advertido algún síntoma de locura en su hijo, Zosimoff le respondió con calma y franca sonrisa, que se había exagerado el alcance de sus palabras, que sin duda, había echado de ver en el enfermo una idea fija, algo así como monomanía, cuanto que él, Zosimoff, estudiaba ahora de una manera especial esta rama tan interesante de la Medicina.\"},{\"heading\":false,\"text\":\"--Pero--añadió--, es menester considerar que hasta hoy el enfermo ha estado delirando constantemente, y de seguro la llegada de su familia será para él una distracción, contribuirá a devolverle las fuerzas y ejercerá sobre él una acción saludable... Si se pueden evitar nuevas emociones--terminó diciendo con tono significativo.\"},{\"heading\":false,\"text\":\"Levantándose después, y saludando a la vez ceremonioso y cordial, salió seguido de acciones de gracias, de bendiciones y de efusiones de reconocimiento. Advocia Romanovna le tendió su linda mano que el médico no había tratado de estrechar. En una palabra, el doctor se retiró encantado de sí mismo, y más encantado todavía de su visita.\"},{\"heading\":false,\"text\":\"--Mañana hablaremos. Ahora acuéstense ustedes en seguida; ya es tiempo de que descansen--ordenó Razumikin, saliendo con Zosimoff--. Mañana a primera hora vendré a dar a ustedes noticias del enfermo.\"},{\"heading\":false,\"text\":\"--¡Qué encantadora joven es esta Advocia Romanovna!--observó con acento sincero Zosimoff cuando ambos estuvieron en la calle.\"},{\"heading\":false,\"text\":\"--¿Encantadora? ¿Encantadora has dicho?--rugió Razumikin lanzándose sobre el doctor y agarrándole por el cuello--. Si te atreves... ¿Me entiendes? ¿Me entiendes?--gritó apretándole la garganta y arrojándolo contra la pared--. ¿Me entiendes?\"},{\"heading\":false,\"text\":\"--Déjame. ¡Demonio de borracho!--dijo Zosimoff, tratando de soltarse de las manos de su amigo.\"},{\"heading\":false,\"text\":\"Cuando Razumikin le soltó, miróle fijamente y lanzó una carcajada.\"},{\"heading\":false,\"text\":\"El estudiante permanecía en pie delante de él con los brazos caídos y la cara triste.\"},{\"heading\":false,\"text\":\"--Es verdad, soy un bestia--dijo con aire sombrío--; pero tú también lo eres.\"},{\"heading\":false,\"text\":\"--No, amigo, yo no lo soy. No sueño con tonterías.\"},{\"heading\":false,\"text\":\"Continuaron su camino sin decir una palabra, y únicamente cuando llegaron cerca de la casa de Raskolnikoff, Razumikin, muy preocupado, rompió el silencio:\"},{\"heading\":false,\"text\":\"--Escucha--dijo a Zosimoff--, tú eres un buen amigo, pero tienes una variada colección de vicios; eres un voluptuoso, un innoble sibarita, te gusta la comodidad, engordas y de nada te privas. Te digo, pues, que esto es innoble, porque conduce derechamente a las mayores suciedades. Siendo, como eres, afeminado, no comprendo de qué manera puedes ser un buen médico, y además un médico celoso. ¡Duerme sobre colchones de plumas (¡un médico!) y se levanta para ir a visitar a un enfermo! De aquí a tres años estarían llamando a tu puerta y no dejarías la cama. Pero no se trata de esto; lo que yo quiero decirte es lo siguiente: voy a dormir en la cocina; tú pasarás la noche en la habitación de la patrona (he podido, no sin trabajo, obtener su consentimiento); será una ocasión para ti de trabar íntimo conocimiento con ella. No es lo que tú piensas. No hay ni sombra de lo que sospechas.\"},{\"heading\":false,\"text\":\"--¡Pero si yo no sospecho!\"},{\"heading\":false,\"text\":\"--Es, amigo mío, una criatura púdica, silenciosa, tímida, de una castidad a toda prueba, y por añadidura, tan sensible, tan tierna... Líbrame de ella, te lo suplico por todos los diablos. Es muy agradable... Pero al presente estoy satisfecho. Pido un substituto.\"},{\"heading\":false,\"text\":\"Zosimoff se echó a reír de muy buena gana.\"},{\"heading\":false,\"text\":\"--Se conoce que no eres moderado; no sabes lo que dices. ¿Por qué he de hacerle la corte?\"},{\"heading\":false,\"text\":\"--Te aseguro que no te costará trabajo conquistar sus gracias. Te basta con charlar con ella de cualquier cosa, con que te sientes a su lado y la hables. Además, eres médico: empieza por curarla de cualquier tontería. Te juro que no tendrás de que arrepentirte. Tiene un clavicordio; yo, como sabes, canto algo. Le he cantado una cancioncilla rusa: «Mis ojos vierten ardientes lágrimas...» Le gustan mucho las melodías sentimentales. Ese fué mi punto de partida; pero tú eres un verdadero profesor de piano, una especie de Rubinstein... Te aseguro que no te pesará.\"},{\"heading\":false,\"text\":\"--Pero, ¿a qué viene todo eso?\"},{\"heading\":false,\"text\":\"--Por lo visto yo no sé explicarme. Mira, os conozco perfectamente al uno y al otro. No es solamente hoy cuando he pensado en ti. Tú acabarás de ese modo. ¿Qué te importa que sea más pronto o más tarde? Aquí, amigo mío, tendrás colchón de pluma y algo mejor. Encontrarás el puerto, el refugio; el fin de las agitaciones, tortas excelentes, sabrosas blinas[16], excelentes pasteles de pescado, el samovar por la tarde, el calentador por la noche; estarás como muerto, y, sin embargo, vivirás: doble ventaja; pero basta de charla, es hora de acostarse. Escucha: me sucede a veces despertarme por la noche; en tal caso, iré a ver cómo sigue Raskolnikoff. Si te sale del corazón, puedes ir a verle una vez siquiera; y si adviertes en él algo extraordinario, corre a despertarme. Creo, sin embargo, que no será menester.\"},{\"heading\":false,\"text\":\"[16] Especie de galleta.\"}]},{\"title\":\"tercera parte — capítulo II\",\"blocks\":[{\"heading\":false,\"text\":\"Al día siguiente, a las siete dadas, Razumikin se despertó presa de pensamientos que jamás habían turbado su existencia. Se acordó de todos los incidentes de la noche y comprendió que había experimentado una impresión muy diferente de cuantas sintiera hasta entonces. Comprendía, al mismo tiempo, que el sueño que había acariciado era de todo punto irrealizable. Aquella quimera le pareció de tal modo absurda, que tuvo vergüenza de pensar en ella. Así es que se apresuró a pasar a otras cuestiones más prácticas, que en cierto modo le había legado la maldita jornada precedente.\"},{\"heading\":false,\"text\":\"Lo que más le entristecía era haberse presentado el día anterior como un perdido; no solamente le habían visto ebrio sino abusando de las ventajas que su posición de bienhechor le daba sobre una joven obligada a recurrir a él, y sin conocer a punto fijo lo que era el tal señor. ¿Con qué derecho juzgaba tan temeriamente a Pedro Petrovitch? ¿Quién le preguntaba su opinión? Además, una persona como Advocia Romanovna, ¿podía casarse a gusto con un hombre indigno de ella? Sin duda que Pedro Petrovitch Ludjin tenía algún mérito. Claro es que existía la cuestión del alojamiento; pero, ¿qué motivos tenía Ludjin para saber lo que era aquella casa? Por otra parte, las dos señoras se albergaban allí provisionalmente, mientras se les preparaba otra vivienda. ¡Oh, qué miserable era todo aquello! ¿Podría justificarse alegando su embriaguez? Tan necia excusa le envilecía más. La verdad está en el vino, y he aquí que, bajo la influencia del vino, había revelado toda la verdad, es decir, la bajeza de un corazón vulgarmente celoso. ¿Le estaba permitido tal sueño a Razumikin? ¿Qué era él comparado con aquella joven, él, el borracho charlatán y brutal de la víspera? ¿Qué cosa más aborrecible y más ridícula a la vez que la idea de una aproximación entre dos seres tan semejantes?\"},{\"heading\":false,\"text\":\"El joven, avergonzado de tan loco pensamiento, se acordó de repente de haber dicho la noche anterior en la escalera que le amaba la patrona y que ésta tendría celos de Advocia Romanovna. Tal recuerdo le llenó de confusión. Era demasiado. Descargó un puñetazo sobre el fogón. Se hizo daño en la mano y rompió un ladrillo.\"},{\"heading\":false,\"text\":\"--No hay duda--murmuró al cabo de un rato con profunda humillación--; ya está hecho, y no hay medio de borrar tantas torpezas... Inútil es pensar en ellas; me presentaré sin decir nada, cumpliré silenciosamente con mi deber y no daré excusas, me callaré. Ahora es demasiado tarde y el mal está hecho.\"},{\"heading\":false,\"text\":\"Puso, sin embargo, particular esmero en arreglarse; no tenía más que un traje, y aunque hubiese tenido muchos, quizás se hubiera puesto el de la víspera «a fin de no parecer que se había arreglado ex profeso...» Sin embargo, un abandono cínico hubiese sido de muy mal gusto. No tenía derecho a herir los sentimientos ajenos, sobre todo cuando se trataba de personas que necesitaban de él y que le habían suplicado que fuese a verlas; de consiguiente, cepilló con gran cuidado la ropa; en cuanto a la interior, Razumikin no la podía sufrir sucia.\"},{\"heading\":false,\"text\":\"Habiendo encontrado el jabón de Anastasia, se lavó concienzudamente la cabeza, el cuello, y, particularmente, las manos. Después de vacilar si se afeitaría o no (Praskovia Paulovna poseía excelentes navajas, herencia de su difunto marido Zarnitzin), resolvió la cuestión negativamente y con cierta brusca irritación, dijo para sí: «No, me quedaré como estoy. Se figurarían quizá que me había afeitado para... ¡De ninguna manera!»\"},{\"heading\":false,\"text\":\"Estos monólogos fueron interrumpidos por la llegada de Zosimoff, el cual después de haber pasado la noche en casa de Praskovia Paulovna, entró un instante en la suya, y venía ahora a visitar al enfermo. Razumikin le dijo que Raskolnikoff dormía como un lirón; el médico prohibió que se le despertara y prometió volver entre diez y once.\"},{\"heading\":false,\"text\":\"--¡Con tal que esté en su cuarto cuando vuelva!--añadió--. Con un cliente tan dado a las fugas, no se puede contar con él. ¿Sabes si va a ir a verlas o si vendrán ellas?\"},{\"heading\":false,\"text\":\"--Presumo que vendrán--respondió Razumikin, comprendiendo por qué se le hacía esta pregunta--; tendrán, sin duda, que ocuparse en asuntos de familia. Yo me iré. Tú, en calidad de médico, tienes, naturalmente, más derecho que yo.\"},{\"heading\":false,\"text\":\"--Yo no soy confesor. Además, tengo otras cosas que hacer que no son escuchar sus secretos; yo también me iré.\"},{\"heading\":false,\"text\":\"--Me inquieta una cosa--repuso Razumikin frunciendo el entrecejo--. Ayer estaba ebrio, y mientras acompañaba aquí a Rodia no pude contener la lengua: entre otras tonterías, le dije que temía en él una predisposición a la locura.\"},{\"heading\":false,\"text\":\"--Lo mismo le dijiste a las señoras.\"},{\"heading\":false,\"text\":\"--Sí, una majadería. Pégame si quieres, pero aquí, entre nosotros, sinceramente, ¿cuál es tu opinión respecto de mi amigo?\"},{\"heading\":false,\"text\":\"--¿Qué quieres que te diga? Tú mismo, cuando me llevaste a su casa, me lo presentaste, diciéndome que era un monomaníaco... Ayer le encontramos algo trastornado, y digo que le encontramos, porque, aunque yo te acompañaba, fuiste tú el que con tu relato acerca del pintor decorador, provocaste su exaltación; ¡bonita conversación para sostenerla delante de un hombre cuyo trastorno intelectual procede quizá de ese asunto! Si hubiese tenido yo conocimiento, con toda clase de pormenores, de la escena ocurrida en la oficina de policía; si hubiese sabido yo que Raskolnikoff había sido blanco de las sospechas de un miserable, desde la primera palabra te hubiera impedido que hablases. Estos monomaníacos convierten el Océano en una gota de agua; las aberraciones de su imaginación se les presentan como realidades... La mitad de lo que le sucede me lo explico ahora, gracias a lo que Zametoff nos contó anoche en tu casa. A propósito de este Zametoff, te diré que me parece un buen muchacho; pero ayer anduvo poco acertado en decir lo que dijo. Es un terrible charlatán.\"},{\"heading\":false,\"text\":\"--¿Pero, a quién le ha hablado de eso? A ti y a mí.\"},{\"heading\":false,\"text\":\"--Y a Porfirio Petrovitch.\"},{\"heading\":false,\"text\":\"--¿Y qué importa que se lo haya contado a Porfirio?\"},{\"heading\":false,\"text\":\"--Bueno, ya hablaremos de eso. ¿Tienes alguna influencia con la madre y la hermana? Harán bien en ser hoy muy circunspectas con Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Se lo diré--respondió con aire contrariado Razumikin.\"},{\"heading\":false,\"text\":\"--Hasta la vista. Da las gracias de mi parte a Praskovia Pavlovna por su hospitalidad. Se encerró en su habitación, y aunque le di gritando las buenas noches al través de la puerta, no respondió. Sin embargo, a las siete de la mañana ya estaba levantada; he visto en el corredor que le llevaban el samovar de la cocina... No se ha dignado admitirme a su presencia.\"},{\"heading\":false,\"text\":\"A las nueve en punto Razumikin llegaba a la casa Bakaleieff. Las dos señoras le esperaban desde hacía bastante tiempo con febril impaciencia. Se habían levantado antes de las siete. Entró sombrío, saludó sin gracia y se hizo cargo amargamente de haberse presentado así. No había contado con la huéspeda. Pulkeria Alexandrovna corrió inmediatamente a su encuentro, le tomó las manos y faltó poco para que se las besase. El joven miró tímidamente a Advocia Romanovna; pero en lugar de la expresión burlona y de desdén involuntario y mal disimulado que esperaba encontrar en aquel orgulloso semblante, advirtió tal expresión de reconocimiento y de afectuosa simpatía, que su confusión no reconoció límites. Le hubiera contrariado menos, de seguro, que le hubiese acogido con reproches. Por fortuna, tenía un asunto de conversación perfectamente indicado y se fué a él derecho.\"},{\"heading\":false,\"text\":\"Cuando supo Pulkeria Alexandrovna que su hijo no se había despertado aún, pero que su estado era satisfactorio, indicó que tenía necesidad de conferenciar con Razumikin. La madre y la hija preguntaron en seguida al joven si había tomado ya el te y le invitaron a que lo tomase con ellas, porque habían estado esperando su llegada para ponerlo en la mesa.\"},{\"heading\":false,\"text\":\"Advocia Romanovna tiró de la campanilla y se presentó un criado mal vestido; se le ordenó que trajese el te, y, en efecto, lo sirvió, pero de una manera tan poco conveniente y tan poco limpia, que las dos señoras no pudieron menos de sentirse avergonzadas. Razumikin renegó de semejante zahurda, y después, acordándose de Ludjin, se calló, perdió la serenidad y experimentó vivísimo contento cuando pudo librarse de aquella situación embarazosa, merced a la granizada de preguntas que le dirigió Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"Interrogado a cada instante, estuvo hablando durante tres cuartos de hora, y contó cuanto sabía concerniente a los principales hechos que habían llenado la vida de Raskolnikoff durante un año. Como es de suponer, pasó en silencio lo que convenía callar, por ejemplo, la escena de la comisaría y sus consecuencias. Las dos señoras le escuchaban con la boca abierta, y cuando el estudiante creyó haberles dado todos los pormenores que podían interesarlas, aun no se dieron por satisfechas.\"},{\"heading\":false,\"text\":\"--Dígame, dígame, ¿qué piensa usted?... ¡Ah, usted perdone... no sé todavía su nombre!...--dijo vivamente Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"--Demetrio Prokofitch.\"},{\"heading\":false,\"text\":\"--Demetrio Prokofitch, tengo grandes deseos de saber cómo considera mi hijo las cosas; o, para expresarme mejor, qué es lo que ama y lo que aborrece. ¿Sigue siendo tan irritable? ¿Cuáles son sus deseos, sus sueños, si usted quiere? ¿Bajo qué influencia particular se encuentra ahora?\"},{\"heading\":false,\"text\":\"--¿Qué quiere usted que yo le diga? Conozco a Rodia desde hace diez y ocho meses; es triste, sombrío, orgulloso y altanero. En estos últimos tiempos (pero quizá esta predisposición existiese en él desde antigua fecha) se ha vuelto suspicaz e hipocondríaco. Es bueno y generoso. No gusta de revelar sus sentimientos, y prefiere ofender con su reserva a las personas a mostrarse expansivo con ellas. Algunas veces, sin embargo, no parece tan hipocondríaco, sino solamente frío e insensible hasta la inhumanidad. Diríase que existen en él dos caracteres que se manifiestan alternativamente. En ciertos momentos es por extremo taciturno: todo le molesta, todo le desagrada y permanece acurrucado sin hacer nada. No es burlón, aunque su espíritu no carece de causticidad, sino más bien porque desdeña la burla como un pasatiempo demasiado frívolo. No escucha con atención lo que se le dice. Jamás se interesa por las cosas que en un momento dado interesan a todo el mundo. Tiene una alta opinión de sí mismo, y yo creo que en esto no anda del todo equivocado. ¿Qué más puedo añadir? Creo que la llegada de ustedes ejercerá sobre él una acción muy saludable.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡Dios lo quiera!--exclamó Pulkeria Alexandrovna muy preocupada por estas revelaciones sobre el carácter de su hijo.\"},{\"heading\":false,\"text\":\"Por último, Razumikin se atrevió a mirar un poco más detenidamente a Advocia Romanovna. Mientras hablaba la había estado examinando, pero disimuladamente y volviendo en seguida los ojos. Por su parte, la joven ora se sentaba cerca de la mesa y escuchaba atentamente, ora se levantaba, y, según su costumbre, se paseaba por la habitación con los brazos cruzados, cerrados los labios y haciendo de cuando en cuando alguna pregunta sin interrumpir su paseo. Tenía también la costumbre de no escuchar hasta el fin lo que se le decía. Llevaba un traje ligero de tela obscura y una pañoleta blanca al cuello. Por diversos indicios, Razumikin comprendió que las dos mujeres eran muy pobres. Si Advocia Romanovna hubiese ido vestida como una reina, probablemente no hubiera intimidado a Razumikin; mas quizás por lo mismo que iba vestida muy pobremente causaba al joven mucho temor y le hacía pesar con cuidado cada una de sus palabras y cada uno de sus gestos, lo que, naturalmente, aumentaba la cortedad de un hombre ya poco seguro de sí mismo.\"},{\"heading\":false,\"text\":\"--Nos ha dado usted muchos pormenores curiosos acerca de mi hermano y los ha dado usted imparcialmente. Está bien. Yo creía que usted le admiraba--dijo Advocia Romanovna, sonriendo--. Debe de haber alguna mujer en su existencia--añadió la joven, pensativa.\"},{\"heading\":false,\"text\":\"--No he dicho eso; pero puede que tenga usted razón; sin embargo...\"},{\"heading\":false,\"text\":\"--¿Qué?\"},{\"heading\":false,\"text\":\"--No ama a nadie; quizá no amará jamás--replicó Razumikin.\"},{\"heading\":false,\"text\":\"--Es decir, que es incapaz de amar.\"},{\"heading\":false,\"text\":\"--¿Sabe usted, Advocia Romanovna, que se parece usted mucho a su hermano bajo todos los aspectos?--dijo aturdidamente el joven.\"},{\"heading\":false,\"text\":\"Después se acordó repentinamente del juicio que acababa de emitir acerca de Raskolnikoff, se turbó y se puso rojo como un cangrejo. Dunia no pudo por menos que reírse.\"},{\"heading\":false,\"text\":\"--Quizá se engañen ustedes en el modo de juzgar a mi Rodia--apuntó Pulkeria Alexandrovna un poco ofendida--. No me refiero al presente, Dunetchka; lo que Pedro Petrovitch escribe en esta carta... y lo que nosotros hemos supuesto, acaso no sea verdadero; pero no puede usted imaginarse, Demetrio Prokofitch, cuán fantástico y caprichoso es. Hasta cuando tenía quince años su carácter era para mí una sorpresa continua. Aun ahora le creo capaz de hacer locuras tales como no se le ocurrirían a ningún otro hombre... Sin ir más lejos, ¿sabe usted que hace diez y ocho meses que estuvo a punto de causar mi muerte, cuando se decidió a casarse con la hija de esa señora Zarnitzin, su patrona?\"},{\"heading\":false,\"text\":\"--¿No sabía usted nada de esos amores?--preguntó Advocia Romanovna.\"},{\"heading\":false,\"text\":\"--¿Usted creerá--prosiguió la madre con animación--que le conmoverían mis lágrimas, mis súplicas, mi enfermedad, nuestra miseria y el temor de verme morir? Pues no, señor; completamente tranquilo, siguió sus planes, sin detenerse ante ninguna consideración; y, sin embargo, ¿se puede decir por eso que no nos quiere?\"},{\"heading\":false,\"text\":\"--Nada me ha dicho jamás de tal asunto--respondió con reserva Razumikin--; pero algo he sabido por la señora Zarnitzin, que por cierto no es muy habladora, y lo que he sabido no deja de ser bastante extraño.\"},{\"heading\":false,\"text\":\"--¿Qué es lo que ha sabido usted?--preguntaron a un tiempo las dos mujeres.\"},{\"heading\":false,\"text\":\"--¡Oh! A decir verdad, nada de particular. Todo lo que sé es que ese matrimonio, que era ya cosa convenida y que iba a verificarse cuando la novia murió, desagradaba mucho a la misma señora Zarnitzin... Tengo entendido, además, que la joven, no solamente no era bella, sino que era fea, y, según se dice, muy... caprichosa. Sin embargo, parece que no carecía de ciertas buenas cualidades, y seguramente las tendría; de otro modo, ¿cómo comprender...?\"},{\"heading\":false,\"text\":\"--Estoy convencida de que esa joven tenía algún mérito--afirmó lacónicamente Advocia Romanovna.\"},{\"heading\":false,\"text\":\"--Que Dios me perdone; pero la verdad es que me alegré de su muerte. Sin embargo, no sé para cuál de los dos hubiese sido más funesto ese matrimonio--dijo la madre; y luego, tímidamente, tras de varias vacilaciones y sin apartar los ojos de Dunia, se puso a interrogar de nuevo a Razumikin acerca de la escena de la víspera entre Rodia y Ludjin.\"},{\"heading\":false,\"text\":\"Este incidente parecía inquietarla sobre manera...\"},{\"heading\":false,\"text\":\"El joven volvió a referir minuciosamente el altercado de que había sido testigo; pero añadiendo que Raskolnikoff insultó deliberadamente a Pedro Petrovitch, y no excusó la conducta de su amigo con la enfermedad que éste padecía.\"},{\"heading\":false,\"text\":\"--Antes de estar malo--dijo--ya lo tenía premeditado.\"},{\"heading\":false,\"text\":\"--Así lo creo yo también--replicó Pulkeria Alexandrovna, con la consternación pintada en su semblante.\"},{\"heading\":false,\"text\":\"Pero se sorprendió mucho al ver que Razumikin hablaba de Pedro Petrovitch en términos convenientes y aun con cierta especie de consideración. Esto llamó la atención de Advocia Romanovna.\"},{\"heading\":false,\"text\":\"--¿De modo que ésa es la opinión de usted acerca de Pedro Petrovitch?--no pudo por menos de preguntar Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"--No puedo tener otra acerca del futuro esposo de esta señorita--respondió con tono firme y caluroso Razumikin--. Y no es por vana cortesía por lo que hablo de este modo; lo digo porque... porque... porque... basta que ese hombre sea la persona que Advocia Romanovna ha elegido... Si ayer hube de expresarme en tonos injuriosos respecto de él, fué porque estaba ebrio, y, además... insensato; sí, insensato; había perdido la cabeza, estaba completamente loco, y ahora me da vergüenza de...\"},{\"heading\":false,\"text\":\"Se interrumpió poniéndose encendido como la grana. Las mejillas de Advocia Romanovna se colorearon; pero guardó silencio. Desde que empezó a hablar de Ludjin, no había despegado los labios. Privada del apoyo de su hija, Pulkeria Alexandrovna se encontraba visiblemente cortada.\"},{\"heading\":false,\"text\":\"Al fin tomó la palabra, y, con voz vacilante y levantando a cada momento los ojos hacia Dunia, dijo que en aquel momento le preocupaba sobre todas las cosas cierta circunstancia.\"},{\"heading\":false,\"text\":\"--Vea usted, Demetrio Prokofitch--comenzó a decir--. Debemos de ser francas con él, Dunetchka.\"},{\"heading\":false,\"text\":\"--Sin duda, mamá--respondió, con tono de autoridad Advocia Romanovna.\"},{\"heading\":false,\"text\":\"--Verá usted de lo que se trata--se apresuró a decir la madre, como si el comunicar su disgusto le quitase una montaña del pecho--. Esta mañana, a primera hora, hemos recibido una carta de Pedro Petrovitch, respondiendo a lo que nosotros habíamos escrito ayer, dándole cuenta de nuestra llegada. Vea usted, debía haber ido a esperarnos a la estación, como nos había prometido; pero en su lugar nos hemos encontrado con un criado que nos ha conducido hasta aquí, anunciándonos para esta mañana la visita de su amo. Pero ahora, en vez de venir él, nos ha escrito esta carta... (lo mejor será que usted mismo la lea); hay en ella un párrafo que me pone en cuidado. Usted verá en seguida de qué se trata y me dará francamente su opinión, pues usted, Demetrio Prokofitch, conoce mejor que nadie el carácter de Rodia, y está en condiciones de poder aconsejarme. Prevengo a usted que desde el primer momento Dunetshka ha resuelto la cuestión; pero yo no sé qué hacer, y espero que usted...\"},{\"heading\":false,\"text\":\"Razumikin abrió la carta, fechada la víspera.\"},{\"heading\":false,\"text\":\"«Señora Pulkeria Alexandrovna: Tengo el honor de manifestar a usted que asuntos imprevistos me han impedido ir a esperar a ustedes a la estación; por eso me he hecho representar por un hombre de mi confianza. El Senado, donde he de entender en una cuestión, me priva del honor de ver a ustedes por la mañana; por otra parte, no quiero interrumpir la entrevista de usted con su hijo ni la de Advocia Romanovna con su hermano. A las ocho en punto de la tarde tendré la satisfacción de saludar a ustedes en su alojamiento. Encarecidamente les suplico que me eviten la presencia de Rodión Romanovitch, el cual me insultó del modo más grosero en la visita que le hice ayer. Aparte de esto, debo tener con usted una explicación personal a propósito de un punto que acaso no interpretemos ambos de la misma manera. Tengo el honor de advertir a usted anticipadamente que, si a pesar de mi deseo, expresado formalmente, encontrase en casa de ustedes a Rodión Romanovitch, me veré obligado a retirarme en seguida, y usted solamente podrá atribuir a sí misma la causa de mi determinación.\"},{\"heading\":false,\"text\":\"»Digo a usted esto teniendo motivos para creer que Rodión Romanovitch, que parecía tan enfermo cuando yo le visité, recobró la salud dos horas después, y puede, por consiguiente, ir a casa de ustedes. Ayer, en efecto, le vi con mis propios ojos en casa de un borracho que acababa de ser atropellado por un coche. So pretesto de costear los funerales, dió veinticinco rublos a la hija del difunto, joven de conducta notoriamente equívoca. Esto me ha causado verdadero estupor, porque sé con cuánta fatiga se ha procurado usted ese dinero. Suplico a usted que tenga la bondad de presentar mis homenajes más sinceros a la señorita Advocia Romanovna, y permitir que me repita de usted obediente servidor.\"},{\"heading\":false,\"text\":\"»PEDRO PETROVITCH LUDJIN.»\"},{\"heading\":false,\"text\":\"--¿Qué hacer ahora, Demetrio Prokofitch?--preguntó Pulkeria Alexandrovna, a quien casi se le saltaban las lágrimas--. ¿Cómo decirle a Rodia que venga? Ayer insistió tan vivamente para que se despidiese a Pedro Petrovitch, y ahora éste pretende que no reciba a mi hijo... Seguramente que él vendrá ex profeso en cuanto sepa esto; y, ¿qué va a suceder entonces?\"},{\"heading\":false,\"text\":\"--Siga usted el consejo de Advocia Romanovna--respondió tranquilamente Razumikin.\"},{\"heading\":false,\"text\":\"--¡Ah, Dios mío!... Ella dice... no puede imaginarse lo que dice; no acierto a comprender lo que se propone. Según ella, es mejor, o, más bien dicho, es absolutamente indispensable que Rodia venga esta noche y se encuentre aquí con Pedro Petrovitch... Yo preferiría enseñarle la carta a mi hijo, e impedir hábilmente que viniese, y para conseguir tal objeto contaba con usted... No comprendo a qué borracho muerto ni a qué joven se refiere esta carta, ni me explico cómo ha dado a esa persona las últimas monedas de plata que...\"},{\"heading\":false,\"text\":\"--Que representan para ti tantos sacrificios, mamá--interrumpió la joven.\"},{\"heading\":false,\"text\":\"--Ayer no estaba en su estado normal--dijo con aire pensativo Razumikin--. ¡Si supiese usted a qué pasatiempos se entregó ayer en un café! Por lo demás, ha hecho bien. En efecto, me habló ayer de un muerto y de una joven mientras que yo le acompañaba a su casa; pero no comprendí ni una palabra... Como ayer estaba yo...\"},{\"heading\":false,\"text\":\"--Lo mejor es, mamá, ir a su casa, y yo te aseguro que veremos allí lo que conviene hacer. ¡Qué tarde es ya! ¡Las diez dadas!--observó Dunia, mirando un magnífico reloj de oro esmaltado, que llevaba suspendido del cuello por una larga cadena de Venecia y que desentonaba con el resto de su atavío.\"},{\"heading\":false,\"text\":\"--Un regalo de su prometido--pensó Razumikin.\"},{\"heading\":false,\"text\":\"--Es, efectivamente, hora de salir--dijo su madre con apresuramiento--. Va a pensar que le guardamos rencor por la acogida que nos hizo anoche; a esa causa atribuirá nuestro retraso. ¡Ah, Dios mío!\"},{\"heading\":false,\"text\":\"Hablando así se apresuraba a ponerse el sombrero y la pañoleta.\"},{\"heading\":false,\"text\":\"Dunia se preparaba también a salir. Sus guantes estaban, además de descoloridos, agujereados, lo cual no pasó inadvertido a Razumikin; sin embargo, aquel traje, cuya pobreza saltaba a la vista, daba a las dos señoras un sello particular de dignidad, como acontece siempre a las mujeres que saben llevar humildes vestidos.\"},{\"heading\":false,\"text\":\"--Esperen ustedes que me adelante para ver si está despierto--dijo Razumikin cuando comenzaron a subir las escaleras del domicilio de Raskolnikoff.\"},{\"heading\":false,\"text\":\"Las señoras le siguieron muy despacio. Cuando llegaron al cuarto piso, advirtieron que la puerta del departamento de la patrona estaba abierta, y que por la estrecha abertura las observaban dos ojos negros y penetrantes. Las miradas se encontraron y la puerta se cerró con tal estrépito, que Pulkeria Alexandrovna estuvo a punto de lanzar un grito de espanto.\"}]},{\"title\":\"tercera parte — capítulo III\",\"blocks\":[{\"heading\":false,\"text\":\"--¡Va bien, va bien!--exclamó alegremente Zosimoff viendo entrar a las dos mujeres.\"},{\"heading\":false,\"text\":\"El doctor había llegado diez minutos antes y ocupaba en el sofá el mismo sitio que la víspera. Raskolnikoff, sentado en el otro extremo, estaba completamente vestido; habíase tomado también el trabajo de lavarse y peinarse, cosas ambas que no acostumbraba desde hacía algún tiempo. Aunque con la llegada de Razumikin y de las dos señoras quedó llena la habitación, Anastasia logró colocarse detrás de ellas, y se quedó para escuchar la conversación. Efectivamente Raskolnikoff estaba bien, pero su palidez era extrema y parecía absorto en una triste idea.\"},{\"heading\":false,\"text\":\"Cuando Pulkeria Alexandrovna entró con su hija, Zosimoff advirtió con sorpresa el sentimiento que se reveló en la fisonomía del enfermo. En vez de alegría era una especie de estoicismo resignado; parecía que el joven hacía un llamamiento a todas sus fuerzas para soportar durante una hora o dos un tormento inevitable. Cuando la conversación se hubo entablado, observó también el médico que cada palabra abría como una herida en el alma de su cliente; pero al mismo tiempo se asombraba de ver a este último relativamente dueño de sí mismo. El monomaníaco frenético de la víspera sabía ahora dominarse hasta cierto punto y disimular sus impresiones.\"},{\"heading\":false,\"text\":\"--Sí, veo ahora que estoy casi curado--dijo Raskolnikoff, besando a su madre y a su hermana con una cordialidad que hizo brillar de alegría el rostro de Pulkeria Alexandrovna--. Y no lo digo como ayer--añadió dirigiéndose a Razumikin y estrechándole la mano.\"},{\"heading\":false,\"text\":\"--También yo estoy asombrado de su notable mejoría--dijo Zosimoff--. De aquí a tres o cuatro días, si esto continúa, se encontrará como antes, es decir, como estaba hace uno o dos meses, o quizá tres, porque esta enfermedad se hallaba latente desde hace tiempo, ¿eh? Confiese ahora que tenía usted alguna parte de culpa--terminó con sonrisa reprimida el doctor, temeroso de irritar al enfermo.\"},{\"heading\":false,\"text\":\"--Es muy posible--replicó fríamente Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Ahora que se puede hablar con usted--prosiguió Zosimoff--, quisiera convencerle de que es necesario apartarse de las causas primeras, a las cuales hay que atribuir su estado morboso. Si usted hace eso, se curará; de lo contrario, se agravará su mal. Ignoro cuáles son estas causas primeras; pero usted, de seguro, las conoce. Es usted un hombre inteligente, y, sin duda, se observa a sí mismo. Me parece que su salud se ha alterado desde que salió de la Universidad. Usted no puede estar sin ocupación. Le conviene, a mi entender, trabajar, proponerse un proyecto, y perseguirlo tenazmente.\"},{\"heading\":false,\"text\":\"--Sí, sí, tiene usted razón; volveré a la Universidad lo más pronto posible, y entonces todo marchará como una seda.\"},{\"heading\":false,\"text\":\"El doctor dió sus sabios consejos con la intención, en parte, de producir efecto en las señoras. Cuando hubo acabado, miró fijamente a su cliente, y se quedó un poco desconcertado al advertir que el rostro de éste expresaba franca burla. Sin embargo, Zosimoff se consoló bien pronto de su decepción, Pulkeria Alexandrovna se apresuró a darle las gracias manifestándole, en particular, su reconocimiento por la visita que les hizo la noche anterior.\"},{\"heading\":false,\"text\":\"--¡Cómo! ¿Fué a ver a ustedes anoche?--preguntó Raskolnikoff con voz inquieta--. ¿De modo que no habéis descansado después de un viaje tan penoso?\"},{\"heading\":false,\"text\":\"--¡Si no eran más que las dos, querido Rodia, y, en casa, Dunia y yo no nos acostamos nunca antes de esa hora!\"},{\"heading\":false,\"text\":\"--No sé cómo darles las gracias--continuó Raskolnikoff, que de repente frunció las cejas y bajó la cabeza--. Prescindiendo de la cuestión de dinero (perdóneme usted si hago alusión a ella)--dijo dirigiéndose a Zosimoff--, no me explico cómo he podido merecer de usted tal interés. No lo comprendo, y aun diré que tanta benevolencia me pesa, pues es ininteligible para mí. Ya ve usted que soy franco.\"},{\"heading\":false,\"text\":\"--No se atormente usted--replicó Zosimoff afectando reírse--; supóngase usted que es mi primer cliente. Nosotros los médicos, cuando empezamos, tomamos tanto cariño a nuestros primeros enfermos como si fuesen nuestros hijos. Algunas veces hasta parecemos enamorados de ellos, y ya sabe usted que mi clientela no es muy numerosa.\"},{\"heading\":false,\"text\":\"--Y no digo nada de éste--siguió diciendo Raskolnikoff, señalando a Razumikin--. ¡No he hecho más que injuriarle y molestarle sin cesar!\"},{\"heading\":false,\"text\":\"--¡Qué tonterías dices! Según se ve, estás hoy muy sentimental--exclamó Razumikin.\"},{\"heading\":false,\"text\":\"Si hubiera sido más perspicaz, habría echado de ver, que, lejos de estar sentimental, su amigo se encontraba en situación totalmente distinta. Pero Advocia Romanovna no se engañaba, y, muy inquieta, observaba atentamente a su hermano.\"},{\"heading\":false,\"text\":\"--De ti, mamá, apenas me atrevo a hablar--dijo Raskolnikoff, que parecía recitar una lección aprendida por la mañana--; hoy solamente he podido comprender lo que habrás sufrido ayer esperando que volviera a casa.\"},{\"heading\":false,\"text\":\"Al decir estas palabras sonrió y tendió bruscamente la mano a su hermana. Este gesto no fué acompañado de ninguna palabra, pero la sonrisa del joven expresaba un sentimiento verdadero, ahora no fingía. Gozosa y reconocida, Dunia tomó la mano que se le tendía y la estrechó con fuerza. Era la primera satisfacción que le daba después del altercado de la víspera. Al ver esta reconciliación muda y definitiva del hermano con la hermana, Pulkeria Alexandrovna se puso radiante de alegría.\"},{\"heading\":false,\"text\":\"Razumikin se agitó nerviosamente en su silla.\"},{\"heading\":false,\"text\":\"--Aunque no fuera más que por esto le querría--murmuraba con su tendencia a exagerarlo todo--. Son impulsos propios de él.\"},{\"heading\":false,\"text\":\"--¡Qué bien ha estado!--murmuró la madre para sí--. ¡Qué nobles arranques los suyos! Este simple hecho de tender así la mano a su hermana mirándola con afecto, ¿no es la manera más franca y más delicada de poner fin al rozamiento de ayer?--¡Ah, Rodia--añadió en voz alta apresurándose a responder a la observación de Raskolnikoff--, no puedes figurarte lo desgraciadas que nos consideramos anoche Donetshka y yo! Ahora que todo ha pasado y que hemos vuelto a ser felices, puedo decírtelo. Figúrate: en cuanto nos apeamos del tren corrimos aquí para abrazarte, y esta joven, ahí la tienes (buenos días, Anastasia), nos dijo de repente que habías estado en cama con fiebre, que delirando te habías escapado y que se te andaba buscando. No puedes imaginarte la impresión que nos hizo esta noticia.\"},{\"heading\":false,\"text\":\"--Sí, sí... Todo eso es seguramente muy desagradable--murmuró Raskolnikoff; pero dió esta respuesta con aire tan distraído, por no decir indiferente, que Dunia le miró sorprendida.\"},{\"heading\":false,\"text\":\"--¿Qué es lo que yo quería deciros?--continuó esforzándose por coordinar sus recuerdos--. ¡Ah! Sí, os suplico a ti, mamá, y a ti, Dunia, que no vayan a creer que no he querido ir a verlas hoy y que he esperado en casa a que ustedes vinieran.\"},{\"heading\":false,\"text\":\"--¿Por qué dices eso, Rodia?--exclamó Pulkeria Alexandrovna no menos asombrada que su hija.\"},{\"heading\":false,\"text\":\"--Cualquiera diría que nos responde por simple cortesía--pensaba Dunia--; hace las paces y pide perdón como si llenase una pura formalidad o recitase una lección.\"},{\"heading\":false,\"text\":\"--En cuanto desperté quise ir a ver a ustedes, pero no tenía ropa que ponerme; se me olvidó decir ayer a Anastasia que lavase la sangre... Hasta hace un momento no me he podido vestir.\"},{\"heading\":false,\"text\":\"--¿Sangre? ¿Qué sangre?--preguntó Pulkeria Alexandrovna alarmada.\"},{\"heading\":false,\"text\":\"--No es nada... No hay que asustarse... Ayer, durante mi delirio, paseando por la calle, me tropecé con un hombre que acababa de ser atropellado. Un funcionario. Por esta razón tenía manchado de sangre el traje.\"},{\"heading\":false,\"text\":\"--¿Mientras estabas delirando? ¡Si te acuerdas de todo!--interrumpió Razumikin.\"},{\"heading\":false,\"text\":\"--Es verdad--respondió Raskolnikoff algo inquieto--, me acuerdo de todo, hasta de los más insignificantes pormenores; pero mira qué cosa más extraña: no logro explicarme por qué he dicho eso, por qué lo he hecho, por qué he ido a ese sitio.\"},{\"heading\":false,\"text\":\"--Es un fenómeno muy conocido--observó Zosimoff--; se realizan los actos a veces con una exactitud y con una habilidad extraordinarias; pero el principio de que emana ese acto se altera en el alienado y depende de diversas impresiones morbosas.\"},{\"heading\":false,\"text\":\"La palabra «alienado» heló la sangre a todos; Zosimoff la dejó escapar inadvertidamente, porque estaba absorto en su tema favorito. Raskolnikoff, que seguía meditabundo, pareció no prestar atención alguna a las palabras del doctor. En sus pálidos labios vagaba una extraña sonrisa.\"},{\"heading\":false,\"text\":\"--Pero, vamos a ver, ¿ese hombre atropellado...? Te he interrumpido hace un momento--se apresuró a decir a Razumikin.\"},{\"heading\":false,\"text\":\"--¡Ah, sí!--dijo Raskolnikoff como despertando de un sueño--. Me manché de sangre ayudando a transportarle a su casa... A propósito, mamá; hice ayer una cosa imperdonable. Verdaderamente estaba trastornado. Todo el dinero que me habías enviado lo di a la viuda para el entierro. La pobre mujer es bien digna de lástima... Está tísica, le quedan tres hijos y no tiene con qué alimentarlos... Tiene también una hija... Quizá tú hubieses hecho lo mismo que yo si hubieras visto tanta miseria. Sin embargo, lo reconozco; yo no tenía el derecho de hacer eso, sobre todo sabiendo con cuánto trabajo me habéis procurado ese dinero.\"},{\"heading\":false,\"text\":\"--No te preocupes por eso, Rodia; estoy convencida de que todo lo que tú haces está bien hecho--respondió la madre.\"},{\"heading\":false,\"text\":\"--No, no estás muy convencida--replicó él procurando sonreírse.\"},{\"heading\":false,\"text\":\"La conversación quedó suspendida durante unos minutos. Palabras, silencio, reconciliación, perdón, en todo había algo de forzado y cada cual de los presentes lo comprendía.\"},{\"heading\":false,\"text\":\"--¿No sabes que Marfa Petrovna ha muerto?--dijo de repente Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"--¿Qué Marfa Petrovna?\"},{\"heading\":false,\"text\":\"--Marfa Petrovna Svidrigailoff. Te hablé extensamente de ella en mi última carta.\"},{\"heading\":false,\"text\":\"--¡Ah! Sí, ya me acuerdo... ¿De modo que ha muerto?--dijo el joven con el estremecimiento propio del hombre que despierta--. ¿Es posible que haya muerto? ¿Y de qué?\"},{\"heading\":false,\"text\":\"--De repente--se apresuró a decir Pulkeria Alexandrovna, alentada a seguir por la curiosidad que demostraba su hijo--. Murió precisamente el mismo día que yo te escribí. Según parece, aquel pícaro de hombre ha sido la causa de su muerte. Se dice que le pegó demasiado.\"},{\"heading\":false,\"text\":\"--¿Ocurrían con frecuencia esas escenas en su casa?--preguntó Raskolnikoff dirigiéndose a su hermana.\"},{\"heading\":false,\"text\":\"--No, todo lo contrario; siempre se mostraba muy paciente y hasta cortés en ella. En muchos casos, daba pruebas de demasiada indulgencia, y esto durante siete años. Por lo visto le ha faltado, de repente, la paciencia.\"},{\"heading\":false,\"text\":\"--De modo que no era un hombre tan terrible, puesto que la ha soportado durante siete años. Parece que le disculpas, Dunetshka.\"},{\"heading\":false,\"text\":\"La joven frunció el entrecejo.\"},{\"heading\":false,\"text\":\"--Sí, sí, es un hombre terrible. Yo no puedo representármelo más detestable--respondió casi temblando, y se quedó pensativa.\"},{\"heading\":false,\"text\":\"--Había ocurrido esta escena por la mañana--continuó Pulkeria Alexandrovna--. Inmediatamente después Marfa dió orden de enganchar, porque quería ir a la ciudad después de comer, según tenía por costumbre en ocasiones semejantes. Según se dice, comió con mucho apetito.\"},{\"heading\":false,\"text\":\"--¿A pesar de los golpes?\"},{\"heading\":false,\"text\":\"--Estaba ya acostumbrada a ellos. Al levantarse de la mesa fué a tomar el baño para marchar cuanto antes. Se trataba por la hidroterapia; hay una fuente en su casa y se bañaba todos los días. Apenas se metió en el agua, le dió un ataque de apoplejía.\"},{\"heading\":false,\"text\":\"--No es extraño--observó Zosimoff.\"},{\"heading\":false,\"text\":\"--¡Como su marido le había pegado tanto!\"},{\"heading\":false,\"text\":\"--¿Qué importa eso?--dijo Advocia Romanovna.\"},{\"heading\":false,\"text\":\"--¡Hum! Yo no sé, mamá, por qué me cuentas semejantes tonterías--dijo Raskolnikoff con súbita irritación.\"},{\"heading\":false,\"text\":\"--¡Pero si no sabía de qué hablar!--confesó cándidamente Alexandrovna.\"},{\"heading\":false,\"text\":\"--Parece que me tenéis miedo--observó el joven con amarga sonrisa.\"},{\"heading\":false,\"text\":\"--Es la verdad--respondió Dunia fijando en su hermano una mirada severa--. Cuando subíamos a esta casa, mamá ha hecho la señal de la cruz; tan asustada estaba.\"},{\"heading\":false,\"text\":\"Las facciones del joven se alteraron de tal modo, que parecía que iba a darle una convulsión.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿Qué dices, hija? No te incomodes, Rodia, por Dios. ¿Cómo dices eso, Dunia?--añadió excusándose y cortada Pulkeria Alexandrovna--. En el tren no he cesado de pensar en la felicidad de verte y de hablar contigo. Tanta ilusión tenía, que se me ha hecho muy corto el camino, y ahora soy feliz de encontrarme aquí, querido Rodia.\"},{\"heading\":false,\"text\":\"--¡Basta, mamá!--murmuró él muy agitado, y sin mirar a su madre le estrechó la mano--; tiempo tenemos de hablar.\"},{\"heading\":false,\"text\":\"Apenas acabó de decir estas palabras se turbó y se puso pálido; de nuevo sentía un frío mortal en el fondo de su alma, de nuevo se confesaba que acababa de decir una horrible mentira, porque en adelante no le era permitido hablar sinceramente ni con su madre. Ni con nadie. La impresión que le produjo este cruel pensamiento fué tan viva que, olvidando la presencia de sus huéspedes, el joven se adelantó y se dirigió a la puerta.\"},{\"heading\":false,\"text\":\"--¿A dónde vas?--gritó Razumikin asiéndole por un brazo.\"},{\"heading\":false,\"text\":\"Raskolnikoff volvió a sentarse y dirigió en silencio una mirada en torno suyo. Todos le contemplaban con estupor.\"},{\"heading\":false,\"text\":\"--¡Qué fastidiosos son ustedes!--gritó de repente--. Digan algo. ¿Por qué están ahí como mudos? Hablen. Las personas no se reunen para estar calladas.\"},{\"heading\":false,\"text\":\"--¡Bendito sea Dios! Yo pensaba que iba a darle otro acceso como ayer--dijo Pulkeria Alexandrovna haciendo la señal de la cruz.\"},{\"heading\":false,\"text\":\"--¿Qué tienes? ¿Qué te pasa?--preguntó Advocia Romanovna con inquietud.\"},{\"heading\":false,\"text\":\"--Nada; una tontería que me ha venido al pensamiento--y Raskolnikoff se echó a reír.\"},{\"heading\":false,\"text\":\"--Vamos. Si es una tontería, menos mal; pero yo temía...--murmuró Zosimoff levantándose--. Tengo que dejar a ustedes; procuraré dar más tarde una vuelta por aquí.\"},{\"heading\":false,\"text\":\"Saludó y salió.\"},{\"heading\":false,\"text\":\"--¡Qué buen hombre!--exclamó Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"--Sí. Es un buen hombre, un hombre de mérito, instruído, inteligente...--dijo Raskolnikoff pronunciando estas palabras con desacostumbrada animación--. No me acuerdo adónde le he visto antes de mi enfermedad. Tengo idea de que le conocía... ¡Ese sí que es un hombre excelente!--añadió señalando con un movimiento de cabeza a Razumikin, el cual acababa de levantarse.\"},{\"heading\":false,\"text\":\"--Es preciso que me vaya...--dijo--. Tengo que hacer.\"},{\"heading\":false,\"text\":\"--Nada tienes que hacer ahora; ¿quieres dejarnos porque se ha marchado Zosimoff? No, no te vas; pero, ¿qué hora es? ¿las doce? ¡Qué reloj tan bonito tienes, Dunia! ¿Por qué callan ustedes? No habla nadie más que yo...\"},{\"heading\":false,\"text\":\"--Es un regalo de Marfa Petrovna.\"},{\"heading\":false,\"text\":\"--Y ha costado muy caro--añadió Pulkeria.\"},{\"heading\":false,\"text\":\"--Creía que era un obsequio de Ludjin.\"},{\"heading\":false,\"text\":\"--Aun no ha dado nada a Dunetshka.\"},{\"heading\":false,\"text\":\"--¡Ah, mamá! ¿No te acuerdas que estuve enamorado y que quise casarme?--dijo bruscamente, mirando a su madre, que se quedó asombrada del giro imprevisto que tomaba la conversación y del tono con que su hijo le hablaba.\"},{\"heading\":false,\"text\":\"--¡Ah! sí--respondió Pulkeria Alexandrovna, cambiando una mirada con Dunia y Razumikin.\"},{\"heading\":false,\"text\":\"--¿Qué te he de decir de esto?; apenas me acuerdo ya. Era una joven enfermiza y raquítica--continuó como absorto y sin levantar los ojos del suelo--. Le gustaba dar limosna a los pobres y pensaba entrar en un monasterio. Cierto día se echó a llorar cuando me hablaba de estas cosas... Sí, sí, bien me acuerdo. Era más bien fea que guapa. La verdad es que no sé por qué me gustó; quizá porque estaba siempre enferma. Si además hubiese sido jorobada o coja, me parece que la hubiera querido más--añadió sonriéndose--. Aquello no tenía importancia... Fué una locura de primavera.\"},{\"heading\":false,\"text\":\"--No, no era solamente una locura de primavera--afirmó Dunia con convencimiento.\"},{\"heading\":false,\"text\":\"Raskolnikoff miró atentamente a su hermana; pero o no oyó o no comprendió las palabras de la joven. Después, con aire melancólico, se levantó, fué a besar a su madre y volvió a sentarse en su sitio.\"},{\"heading\":false,\"text\":\"--¿La amas aún?--dijo con voz temblorosa Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"--¿Todavía? ¿Habláis de ella? No. Todo eso es para mí como una visión lejana... muy lejana... y desde hace mucho tiempo. Y lo cierto es que me causa la misma impresión cuanto me rodea.\"},{\"heading\":false,\"text\":\"Raskolnikoff miró atentamente a las dos mujeres.\"},{\"heading\":false,\"text\":\"--Están ustedes aquí y me parece que me encuentro a mil verstas de este sitio. Pero, ¿por qué hablamos de estas cosas? ¿Por qué preguntarme?--añadió con cólera; después, silenciosamente, se puso a morderse las uñas y se quedó como ensimismado.\"},{\"heading\":false,\"text\":\"--¡Qué mal alojamiento tienes, Rodia!; parece un sepulcro--dijo bruscamente Pulkeria Alexandrovna para interrumpir aquel penoso silencio--: segura estoy de que esta habitación es la causa de tu hipocondría.\"},{\"heading\":false,\"text\":\"--¿Esta habitación?--repitió él con aire distraído--. Sí, ha contribuído mucho... lo mismo he pensado yo; ¡si supieses, mamá, qué ideas tan extrañas acabas de expresar!--añadió de repente con sonrisa enigmática.\"},{\"heading\":false,\"text\":\"Apenas podía soportar Raskolnikoff la presencia de aquella madre y de aquella hermana, de las cuales había estado separado durante tres años y con quienes comprendía que le era imposible toda conversación. Había, sin embargo, una cosa que no admitía dilación; así es que levantándose pensó que aquello debía ser resuelto de una manera o de otra. En tal momento se sintió feliz de encontrar un medio para salir del paso.\"},{\"heading\":false,\"text\":\"--Ante todo he de pedirte, Dunia--comenzó a decir con tono seco--, que me dispenses por el incidente de ayer; pero creo que es una obligación en mí recordarte que sostengo los términos de mi dilema: o Ludjin o yo. Yo puedo ser un infame; pero tú no debes serlo. Basta con uno. Si te casas con Ludjin ceso de considerarte como a una hermana.\"},{\"heading\":false,\"text\":\"--Hijo mío, hablas como ayer--exclamó asustada Pulkeria Alexandrovna--; ¿por qué te tratas siempre de infame? Yo no puedo soportar que hables así. Ayer empleabas el mismo lenguaje.\"},{\"heading\":false,\"text\":\"--Hermano mío--respondió Dunia con un tono que no cedía en sequedad ni en violencia al de Raskolnikoff--, la falta de acuerdo en que nos encontramos, proviene de un error tuyo. He reflexionado esta noche y he descubierto en qué consiste. Tú supones que me sacrifico por alguien y eso es lo que te engaña. Yo me caso por mí misma, porque mi situación personal es difícil. Sin duda podré entonces ser más útil a mis prójimos; pero no es ése el motivo principal de mi resolución.\"},{\"heading\":false,\"text\":\"--Miente--pensaba Raskolnikoff, que de cólera se mordía las uñas--. ¡Orgullosa! No confiesa que quiere ser mi bienhechora. ¡Oh! ¡los caracteres bajos! ¡Su amor se parece al odio! ¡Oh, cuánto detesto a todos!\"},{\"heading\":false,\"text\":\"--En una palabra--continuó Dunia--, me caso con Pedro Petrovitch, porque de dos males elija el menor. Tengo intención de cumplir lealmente cuanto él espera de mí. Por consiguiente no le engaño. ¿De qué te ríes?\"},{\"heading\":false,\"text\":\"Enrojeció repentinamente la joven y brilló en sus ojos un relámpago de cólera.\"},{\"heading\":false,\"text\":\"--¿Que lo cumplirás todo?--preguntó Raskolnikoff sonriendo con amargura.\"},{\"heading\":false,\"text\":\"--Hasta cierto límite; por la manera como Pedro Petrovitch ha pedido mi mano, he comprendido en seguida a lo que debo atenerme. Acaso tenga una opinión muy alta de sí mismo; mas espero que sabrá también apreciarme. ¿Por qué sigues riéndote?\"},{\"heading\":false,\"text\":\"--Y tú, ¿por qué te pones otra vez colorada? Mientes, hermana, tú no puedes estimar a Ludjin: le he visto y he hablado con él. Te casas por interés; haces en todo caso una bajeza; por lo menos veo con gusto que sabes ruborizarte.\"},{\"heading\":false,\"text\":\"--No es verdad, yo no miento--gritó la joven perdiendo su sangre fría--. No me casaré con él sin estar plenamente convencida de que le estimo. Felizmente tengo el medio de convencerme de ello en seguida, y lo que es más, hoy mismo. Este matrimonio no es una bajeza, como tú dices; pero aunque tuvieses razón, aun cuando yo estuviese convencida de cometer una bajeza, ¿no sería por tu parte una crueldad hablarme de ese modo? ¿Por qué exigir un heroísmo que tú no tienes? Eso es una tiranía, una violencia. Caso de causar algún mal, sólo me lo causaré a mí misma. Yo no he matado todavía a nadie. ¿Por qué me miras así? ¿Por qué te pones pálido? ¿Qué tienes, hermano mío?\"},{\"heading\":false,\"text\":\"--¡Dios mío, se ha desmayado! ¡Y tú has sido la causa!--exclamó Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"--No, no es nada, una tontería... Un ligero mareo... No he llegado a desmayarme del todo... los desmayos son buenos para vosotras... ¡hum! sí... ¿Qué es lo que yo quería decir? ¡Ah! ¿Cómo te convencerás hoy mismo de que puedes estimar a Ludjin y de que él te aprecia? ¿No es eso lo que decías hace un momento, o te he entendido yo mal?\"},{\"heading\":false,\"text\":\"--Mamá, enseña a mi hermano la carta de Pedro Petrovitch--dijo Dunia.\"},{\"heading\":false,\"text\":\"Pulkeria Alexandrovna presentó la carta con mano temblorosa. Raskolnikoff la leyó atentamente por dos veces. Todos esperaban algún acceso de furor. La madre, sobre todo, estaba muy inquieta. Después de haberse quedado pensativo un instante, el joven le devolvió la carta.\"},{\"heading\":false,\"text\":\"--No comprendo nada--comenzó a decir sin dirigirse a nadie--: pronuncia discursos, es abogado, muy redicho en su conversación y escribe como un hombre sin cultura.\"},{\"heading\":false,\"text\":\"Estas palabras causaron una estupefacción general. Nadie las esperaba.\"},{\"heading\":false,\"text\":\"--Por lo menos no escribe muy literariamente; aunque su estilo no sea del todo de un iletrado, maneja la pluma como un hombre de negocios--añadió Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Pedro Petrovitch no oculta que ha recibido poca instrucción y se enorgullece de ser hijo de sus obras--dijo Advocia Romanovna un poco contrariada del tono con que le hablaba su hermano.\"},{\"heading\":false,\"text\":\"--Sí; tiene motivo para enorgullecerse, no digo lo contrario. Parece que te ha incomodado porque sólo se me ha ocurrido una observación frívola a propósito de esta carta, y crees que insisto sobre semejantes tonterías para molestarte. Nada de eso; en lo que concierne al estilo, he hecho una observación que en el caso presente está muy lejos de carecer de importancia. Esta frase: «usted no tendrá que quejarse más que de sí misma», no deja nada que desear en punto a claridad. Además, manifiesta la intención de retirarse sobre la marcha si yo voy a vuestra casa. Esta amenaza de irse viene a decir que si no obedecéis, os plantará a las dos después de haberos hecho venir a San Petersburgo. ¿En qué piensas? Viniendo de Ludjin, ¿estas palabras pueden ofender tanto como podrían ofender si hubiesen sido escritas por éste (señaló a Razumikin), por Zosimoff o por uno de nosotros?\"},{\"heading\":false,\"text\":\"--No--respondió Dunia--; bien me hago cargo de que ha expresado demasiado ingenuamente su pensamiento y de que quizá no es muy hábil para servirse de la pluma... Tu observación es muy juiciosa, hermano mío. Yo no esperaba...\"},{\"heading\":false,\"text\":\"--Supuesto que escribe como un hombre de negocios, no podía expresarse de otro modo, y no hay que echarle en cara que se haya mostrado grosero. Por lo demás, debo quitarte una ilusión: en esta carta hay una frase que contiene una calumnia contra mí, y una calumnia por cierto bastante vil. Yo di ayer, en efecto, dinero a una viuda tísica y agobiada por la desgracia, no a pretexto, como ese señor escribe, de pagar los funerales, sino para pagarlos, y ese dinero se lo di a la viuda misma y no a la hija del difunto, a esa joven de conducta «notoriamente equívoca» a quien vi ayer por primera vez en mi vida. En todo esto descubro el deseo de pintarme con los más negros colores e indisponer a vosotras conmigo. Ha escrito en estilo jurídico, es decir, que revela muy claramente su objeto y lo persigue sin pretender disimularlo. Es inteligente, mas, para conducirse con discreción, no basta siempre la inteligencia. Todo lo que te he hecho notar pinta al hombre... y no creo que te aprecie mucho. Lo digo por tu bien, que de todas veras deseo.\"},{\"heading\":false,\"text\":\"Dunia no respondió; había tomado su partido y esperaba que llegase la noche.\"},{\"heading\":false,\"text\":\"--Está bien, Rodia; ¿pero tú, qué decides?--preguntóle su madre, cuya inquietud iba en aumento oyendo discutir reposadamente a su hijo como un hombre de negocios.\"},{\"heading\":false,\"text\":\"--¿Qué quiero decir?\"},{\"heading\":false,\"text\":\"--Ya ves lo que escribe Pedro Petrovitch; desea que tú no vengas a nuestro alojamiento esta noche, y declara que se irá si te encuentra allí; por eso te pregunto qué piensas hacer.\"},{\"heading\":false,\"text\":\"--Yo no soy quien tiene que decirlo. A ti y a Dunia toca ver si esa exigencia de Pedro Petrovitch tiene o no algo de mortificante para vosotras--contestó fríamente Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Dunetshka ha resuelto la cuestión, y yo estoy de perfecto acuerdo con ella--se apresuró a contestar Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"--Creo que es indispensable que asistas a esa entrevista; te suplico, pues, que no faltes. ¿Vendrás? Suplico a usted también que venga--continuó la joven dirigiéndose a Razumikin--. Mamá, me permito hacer esta invitación a Demetrio Prokofitch.\"},{\"heading\":false,\"text\":\"--Y lo apruebo, hija mía. Hágase lo que vosotros dispongáis--añadió su madre--. Para mí es un alivio, no me gusta fingir ni mentir; lo mejor es una explicación franca. Si Pedro Petrovitch se enfada, peor para él.\"}]},{\"title\":\"tercera parte — capítulo IV\",\"blocks\":[{\"heading\":false,\"text\":\"En aquel momento se abrió la puerta sin ruido y entró en la sala una joven mirando tímidamente en su derredor. Su aparición causó general sorpresa y todos los ojos se fijaron en ella con curiosidad. Al pronto no la conoció Raskolnikoff. Era Sofía Semenovna Marmeladoff. El joven la había visto por primera vez el día antes, en unas circunstancias y en un traje que le dejaron en la memoria una imagen distinta. Ahora era una joven de aspecto modesto, o más bien, pobre, de maneras corteses y reservadas y de expresión tímida. Vestía un traje muy sencillo y llevaba un sombrero pasado de moda. No conservaba ninguno de los adornos de la víspera; pero no había prescindido de la sombrilla. Su confusión al ver tanta gente que no esperaba encontrar fué tan grande, que dió un paso hacia atrás para retirarse.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿es usted?--dijo Raskolnikoff en el colmo del asombro, y él también se quedó turbado.\"},{\"heading\":false,\"text\":\"Recordó entonces que la carta de Ludjin, leída un momento antes, contenía alusiones a cierta joven de conducta «notoriamente equívoca», acababa de protestar contra tal calumnia y de declarar que había visto a aquélla por primera vez el día anterior, y he aquí que se presentaba en su casa. En un abrir y cerrar de ojos todos estos pensamientos atravesaron mezclados por su imaginación; mas al observar más atentamente a la recién llegada, la vió tan abatida por la vergüenza, que sintió hacia ella súbita piedad. En el momento en que, asustada, iba a retirarse, se verificó en él un repentino cambio.\"},{\"heading\":false,\"text\":\"--No esperaba a usted--se apresuró a decir invitándola con la mirada a que se quedase--. Haga usted el favor de tomar asiento. ¿Viene, sin duda, de parte de Catalina Ivanovna? Permítame usted, ahí no, siéntese aquí.\"},{\"heading\":false,\"text\":\"Al entrar Sonia, Razumikin, que estaba sentado cerca de la puerta en una de las tres sillas que había en la habitación, se medio levantó para dejar paso a la joven. El primer impulso de Raskolnikoff fué indicar a Sonia el extremo del diván que Zosimoff había ocupado un momento antes; pero, pensando en que aquel mueble le servía de cama, mostró a la joven la silla de Razumikin.\"},{\"heading\":false,\"text\":\"--Tú siéntate aquí--dijo a su amigo haciéndole sitio a su lado en el sofá.\"},{\"heading\":false,\"text\":\"Sonia se sentó casi temblando y miró con timidez a las dos señoras. Era evidente que ella misma no se daba cuenta de cómo tenía la audacia de sentarse al lado de aquellas personas. Este pensamiento le causó tal impresión, que se levantó bruscamente y se dirigió, confusa, hacia Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Es cuestión de un minuto. Perdóneme usted la molestia--dijo con voz trémula--. Me envía Catalina Ivanovna. No tenía otra persona a quien mandar... Catalina Ivanovna suplica a usted encarecidamente que asista mañana a los funerales... en San Motrifinio, y que venga después a nuestra casa... es decir, a casa de ella a tomar un bocado. Catalina Ivanovna espera que le concederá este honor.\"},{\"heading\":false,\"text\":\"--Ciertamente... haré lo posible por complacerla--balbució Raskolnikoff, que se había incorporado a medias--. Tenga usted la bondad de volver a sentarse; hágame el favor de concederme dos minutos.\"},{\"heading\":false,\"text\":\"Al mismo tiempo la invitaba con un gesto a tomar asiento. Sonia obedeció, y después de dirigir una mirada tímida a las dos señoras, bajó rápidamente los ojos. Las facciones de Raskolnikoff se contrajeron, coloreáronse sus mejillas y sus ojos lanzaron llamas.\"},{\"heading\":false,\"text\":\"--Mamá--dijo con voz vibrante--, es Sofía Semenovna Marmeladoff, la hija del desgraciado funcionario que murió ayer atropellado por un coche y del cual ya te he hablado.\"},{\"heading\":false,\"text\":\"Pulkeria Alexandrovna miró a Sonia y guiñó ligeramente los ojos, pues a pesar del temor que experimentaba delante de su hijo, no pudo negarse esta satisfacción. Dunia se volvió hacia la pobre joven y se puso a examinarla con gravedad. Al oírse nombrar por Raskolnikoff, Sonia, cada vez más cortada, levantó de nuevo los ojos.\"},{\"heading\":false,\"text\":\"--Quería preguntar a usted--prosiguió Rodia--qué ha pasado hoy en su casa, si las han molestado, si les ha causado alguna incomodidad la policía...\"},{\"heading\":false,\"text\":\"--No; no ha ocurrido nada de particular... La causa de la muerte era tan evidente... que nos han dejado tranquilas. Sólo los inquilinos se han incomodado.\"},{\"heading\":false,\"text\":\"--¿Por qué?\"},{\"heading\":false,\"text\":\"--Dicen que el cuerpo está demasiado tiempo en la casa... Como ahora hace calor, el olor... de modo que hoy se le conducirá a la capilla del cementerio, donde permanecerá hasta mañana. Al pronto se negaba Catalina Ivanovna, mas acabó por comprender que era preciso someterse.\"},{\"heading\":false,\"text\":\"--¿De modo que la conducción del cadáver es hoy?\"},{\"heading\":false,\"text\":\"--Catalina Ivanovna espera que nos hará usted el obsequio de asistir a las exequias, y que irá usted después a la comida fúnebre.\"},{\"heading\":false,\"text\":\"--¿Da una comida?\"},{\"heading\":false,\"text\":\"--Una modesta colación: me ha encargado dar a usted mil gracias por el socorro que nos entregó ayer... Sin usted, no hubiéramos podido hacer los gastos del funeral.\"},{\"heading\":false,\"text\":\"Un temblor repentino agitó los labios y la barba de la joven; pero logró dominar su emoción y bajó de nuevo los ojos.\"},{\"heading\":false,\"text\":\"Durante este breve diálogo Raskolnikoff la estuvo contemplando atentamente. Sonia tenía el rostro delgado y pálido; la nariz y la barbilla eran algo angulosas y puntiagudas y el conjunto bastante irregular; no se podía decir que era una beldad; pero, en cambio, sus ojos eran tan límpidos, y cuando se animaban comunicaban a su fisonomía tal expresión de bondad, que atraía irresistiblemente. Además se advertía otra particularidad característica en su rostro como en su persona: representaba mucha menos edad de la que tenía, y a pesar de contar ya diez y ocho años, se la hubiera tomado por una chiquilla. Esta circunstancia hacía reír al ver algunos de sus movimientos.\"},{\"heading\":false,\"text\":\"--¿Pero es posible que Catalina Ivanovna pueda atender a esos gastos con tan escasos recursos? ¿Y todavía se propone dar una colación?--preguntó Raskolnikoff.\"},{\"heading\":false,\"text\":\"--El féretro será muy sencillo... Todo se hará con mucha modestia, de suerte que costará muy poco... Catalina y yo hemos calculado el gasto; después de pagado todo, quedará algo para dar la colación... Catalina Ivanovna tiene mucho interés en darla. No es posible decir nada en contrario... Además, esto le sirve de consuelo, y ya sabe usted cómo está y cómo es ella.\"},{\"heading\":false,\"text\":\"--Comprendo, comprendo... ¿Le ha llamado a usted la atención mi cuarto?... Mi madre dice también que parece un sepulcro.\"},{\"heading\":false,\"text\":\"--Ayer se desprendió usted de todo por nosotras--respondió Sonia con voz sorda y rápida, bajando nuevamente los ojos.\"},{\"heading\":false,\"text\":\"Sus labios y su barba volvieron a temblar. Desde su entrada le había impresionado la pobreza que reinaba en la habitación de Raskolnikoff y las palabras que acababa de pronunciar habíansele escapado a su pesar. Siguióse un cortés silencio. Las pupilas de Dunia brillaron y la misma Pulkeria Alexandrovna miró a Sonia con expresión afable.\"},{\"heading\":false,\"text\":\"--Rodia--dijo levantándose--, supongo que comeremos juntos. Vámonos, Dunetshka... Tú deberías salir, Rodia, dar un paseíto, y, después de descansar un poco, venir a casa lo más pronto posible... Temo haberte fatigado.\"},{\"heading\":false,\"text\":\"--Sí, sí, iré--se apresuró a responder, levantándose también...--Tengo algo que hacer antes.\"},{\"heading\":false,\"text\":\"--¡Cuidado con irte a comer a otra parte!--exclamó Razumikin, mirando con asombro a Raskolnikoff--. Eso no puedes hacerlo de ninguna manera.\"},{\"heading\":false,\"text\":\"--No, no iré con ustedes, les aseguro que iré... Pero tú quédate un minuto. De momento no tenéis necesidad de él, ¿verdad?\"},{\"heading\":false,\"text\":\"--No, puede quedarse por ahora. Le espero, sin embargo, Demetrio Prokofitch, a comer con nosotras--dijo Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"--Yo también se lo ruego, venga usted--añadió Dunia.\"},{\"heading\":false,\"text\":\"Razumikin se inclinó radiante de alegría. Durante unos momentos todos experimentaron un malestar extraño.\"},{\"heading\":false,\"text\":\"--Adiós, es decir, hasta muy pronto; no me gusta decir adiós... Adiós, Anastasia... vamos, ya se me escapó otra vez.\"},{\"heading\":false,\"text\":\"Pulkeria Alexandrovna tenía intención de saludar a Sonia; pero, a pesar de toda su buena voluntad, no pudo resolverse a ello, y salió precipitadamente de la habitación.\"},{\"heading\":false,\"text\":\"No hizo lo mismo Advocia Romanovna, que parecía haber esperado este momento con impaciencia. Cuando, después de su madre, pasó al lado de Sonia, hizo a ésta un saludo en toda regla. La pobre muchacha se turbó, se inclinó con tímido apresuramiento, y en su rostro se manifestó una impresión dolorosa, como si la atención de Dunia para con ella le hubiese afectado penosamente.\"},{\"heading\":false,\"text\":\"--Dunia, adiós--dijo Raskolnikoff desde el rellano--; dame la mano.\"},{\"heading\":false,\"text\":\"--Ya te la he dado. ¿No te acuerdas?--respondió la joven, volviéndose hacia él con aire afable, aunque se sentía contrariada.\"},{\"heading\":false,\"text\":\"--Bueno, dámela otra vez--y estrechó de nuevo la mano de su hermana.\"},{\"heading\":false,\"text\":\"Dunia se sonrió ruborizándose, y en seguida se apresuró a apartar la mano y siguió a su madre. También ella se sentía contenta, sin que podamos decir por qué.\"},{\"heading\":false,\"text\":\"--¡Ea! Está bien--exclamó Raskolnikoff volviendo al lado de Sonia, que se había quedado en el cuarto.\"},{\"heading\":false,\"text\":\"Al mismo tiempo la miraba con aire tranquilo.\"},{\"heading\":false,\"text\":\"La jovencita advirtió, con sorpresa, que el semblante de su interlocutor se había esclarecido de repente. Durante algunos instantes Raskolnikoff la miró en silencio. Venía ahora a su memoria lo que Marmeladoff le había contado de su hija.\"},{\"heading\":false,\"text\":\"--Oye el asunto de que quería hablarte--prosiguió el joven tomando del brazo a Razumikin y llevándoselo a un ángulo del aposento.\"},{\"heading\":false,\"text\":\"--¿De modo que puedo decir a Catalina Ivanovna que irá usted?\"},{\"heading\":false,\"text\":\"Al decir esto, Sonia se dispuso a salir.\"},{\"heading\":false,\"text\":\"--Soy con usted en seguida, Sofía Semenovna; nosotros no tenemos secretos y usted no nos molesta. Tengo que decirle dos palabras.\"},{\"heading\":false,\"text\":\"E interrumpiéndose bruscamente se dirigió a Razumikin.\"},{\"heading\":false,\"text\":\"--¿Tú conoces a ése...? ¿Cómo se llama?... ¡Ah, sí, ahora caigo! A Porfirio Petrovitch.\"},{\"heading\":false,\"text\":\"--Sí, le conozco; es pariente mío. ¿Por qué me lo preguntas?--repuso Razumikin.\"},{\"heading\":false,\"text\":\"--¿No me dijiste ayer que instruía esa sumaria... del asesinato?\"},{\"heading\":false,\"text\":\"--Sí, ¿y qué?--insistió Razumikin sorprendido por el sesgo que tomaba la conversación.\"},{\"heading\":false,\"text\":\"--Me dijiste también que interrogaba a las personas que han empeñado alhajas en casa de la vieja; y como yo he empeñado alguna cosa, que no merece la pena de que se hable de ella... una sortija que me dió mi hermana cuando vine a San Petersburgo; y un reloj de plata, que perteneció a mi padre... Esos objetos no valen cinco rublos, pero tienen para mí el valor del recuerdo. ¿Qué debo hacer ahora? No quiero que se pierdan. Temblando estaba hace un momento, temeroso de que mi madre quisiera verlo cuando se hablaba del reloj de Dunia. Es la única cosa que habíamos conservado de mi padre. Si se hubiese perdido, mi madre tendría un verdadero disgusto, ¡las mujeres! Dime, pues, lo que debo hacer. Ya sé que es necesario prestar una declaración ante la policía; pero, ¿no será mejor que me dirija a Porfirio Petrovitch? ¿Qué te parece? Me corre prisa arreglar este asunto. Ya verás cómo antes de comer me preguntará mi madre por el reloj.\"},{\"heading\":false,\"text\":\"--No es a la policía a quien hay que acudir, sino a Porfirio Petrovitch--exclamó Razumikin extremadamente agitado--. ¡Oh, qué contento estoy! Podemos ir en seguida; vive a dos pasos de aquí; seguro estoy de que le encontraremos.\"},{\"heading\":false,\"text\":\"--Sea; vamos.\"},{\"heading\":false,\"text\":\"--Se alegrará mucho de conocerte. Le he hablado muchas veces de ti. Ayer, sin ir más lejos. Vamos. ¿De modo que tú conocías a la vieja? ¡Ah, todo se explica admirablemente! ¡Ah! sí... Sofía Ivanovna.\"},{\"heading\":false,\"text\":\"--Sofía Semenovna--rectificó Raskolnikoff, y dirigiéndose a la joven añadió--: Mi amigo Razumikin, excelente persona.\"},{\"heading\":false,\"text\":\"--Si usted tiene que salir...--comenzó a decir Sonia a quien esta presentación había dejado aún más confusa y que no se atrevía a levantar los ojos para mirar a Razumikin.\"},{\"heading\":false,\"text\":\"--¡Ea, vamos!--dijo Raskolnikoff--: yo pasaré por su casa, Sofía Semenovna. Dígame sus señas.\"},{\"heading\":false,\"text\":\"Pronunció estas palabras no con cortedad, sino con cierta precipitación y evitando las miradas de la joven. Esta dió sus señas no sin ruborizarse. Los tres salieron juntos.\"},{\"heading\":false,\"text\":\"--¿No cierras la puerta?--preguntó Razumikin mientras bajaban la escalera.\"},{\"heading\":false,\"text\":\"--Nunca... Dos años hace que estoy pensando comprar una cerradura. ¡Felices aquellos que no tienen nada que guardar bajo llave!--añadió alegremente dirigiéndose a Sonia.\"},{\"heading\":false,\"text\":\"Se detuvieron en el umbral de la puerta de la calle.\"},{\"heading\":false,\"text\":\"--¿Usted va por la derecha, Sofía Semenovna? ¡Ah! dígame usted: ¿Cómo ha podido dar con mi habitación?\"},{\"heading\":false,\"text\":\"Veíase bien claro que lo que decía no era lo que quería decir. No se cansaba de contemplar los dulces y claros ojos de la joven.\"},{\"heading\":false,\"text\":\"--¡Pero si dió usted sus señas a Polenka!\"},{\"heading\":false,\"text\":\"--¿Qué Polenka? ¡Ah! Sí. ¿La niña? ¿Es hermanita de usted? ¿De modo que le di mis señas?\"},{\"heading\":false,\"text\":\"--¿Lo había usted olvidado?\"},{\"heading\":false,\"text\":\"--No... me acuerdo.\"},{\"heading\":false,\"text\":\"--Yo había oído hablar de usted al difunto... pero no sabía su nombre... ni tampoco él lo sabía... Ahora he venido, y como ya conocía su nombre he preguntado: ¿es aquí donde vive el señor Raskolnikoff? Adiós... Ya le diré a Catalina Ivanovna... Ignoraba que ocupaba usted un cuarto amueblado...\"},{\"heading\":false,\"text\":\"Muy contenta de poder irse Sonia, se alejó con paso rápido sin levantar la vista. Le faltaba tiempo para llegar a la primera esquina de la calle a la derecha, a fin de substraerse a las miradas de los jóvenes y reflexionar sin testigos, sobre todos los incidentes de esta visita. Jamás había experimentado nada semejante; todo un mundo ignorado surgía confusamente en su alma. Recordó de pronto que Raskolnikoff le había manifestado espontáneamente su intención de ir a verla aquel mismo día, quizá aquella misma mañana, tal vez dentro de un momento.\"},{\"heading\":false,\"text\":\"--¡Ah, ojalá no venga hoy!--murmuró angustiada--. ¡Dios mío! ¡En mi casa! ¡En aquella habitación...! y vería... ¡Dios mío, Dios mío!\"},{\"heading\":false,\"text\":\"Estaba demasiado preocupada para notar que desde su salida de la casa había sido seguida por un desconocido. En el momento en que Raskolnikoff, Razumikin y Sonia se habían detenido en la acera para hablar breves instantes, la casualidad hizo que aquel señor pasase al lado de ellos. Las palabras de la joven: «He preguntado si vive aquí el señor Raskolnikoff», llegaron furtivamente a oídos del desconocido y le hicieron estremecerse. Miró disimuladamente a los tres interlocutores y en particular a Raskolnikoff, a quien Sonia se había dirigido, y le examinó después la cara para poder reconocerle en caso de necesidad; todo esto fué hecho en un abrir y cerrar de ojos y de un modo que no pudiera infundir sospechas, después de lo cual el señor se alejó acortando el paso como si hubiera seguido a alguien. Era a Sonia a quien esperaba; bien pronto la vió despedirse de los dos jóvenes y encaminarse a su casa.\"},{\"heading\":false,\"text\":\"«¿Dónde vive? Yo he visto esta cara en alguna parte. Es menester que lo averigüe.»\"},{\"heading\":false,\"text\":\"Cuando hubo llegado a la esquina de la calle, pasó a la otra acera, se volvió y advirtió que la joven marchaba en la misma dirección que él. Sonia no se daba cuenta de que la seguían y la observaban. Cuando llegó a la esquina, la joven la dobló y el desconocido continuó siguiéndola, andando por la acera opuesta y sin perderla de vista. Al cabo de cincuenta pasos atravesó la calle, alcanzó a Sonia y marchó detrás de ella a una distancia de cinco pasos.\"},{\"heading\":false,\"text\":\"Era un hombre de unos cincuenta años; pero muy bien conservado y que representaba mucha menos edad; era alto, fuerte y algo cargado de espaldas. Vestido de una manera tan cómoda como elegante y con guantes nuevos, llevaba en la mano un buen bastón que hacía sonar a cada paso sobre la acera. Todo en su persona delataba un hombre distinguido. Su ancho rostro era bastante agradable; al mismo tiempo el brillo de su tez y sus rojos labios no permitían tomarle por un petersburgués. Sus cabellos muy espesos, eran excesivamente rubios y apenas empezaban a encanecer; la barba larga, ancha y bien cuidada, tenía todavía un color más claro que sus cabellos. La mirada de sus ojos azules era fría, seria y fija.\"},{\"heading\":false,\"text\":\"El desconocido tuvo bastante tiempo para observar que la joven iba distraída y absorta. Al llegar delante de su casa franqueó el umbral. El señor que la seguía continuó detrás de ella un poco asombrado. Después de entrar en el zaguán, Sonia tomó por la escalera de la derecha que conducía a su habitación. «¡Bah!»--dijo para sí el señor, y subió también. Entonces fué cuando la joven advirtió la presencia del desconocido. Llegó al tercer piso, se entró por un corredor y llamó en el número nueve, debajo del cual se leía en la puerta estas dos palabras escritas con tiza: _Kapernumoff, Sastre_. «¡Bah!»--repitió el hombre sorprendido por aquella coincidencia, y llamó al lado, en el número ocho. Las dos puertas estaban a seis pasos la una de la otra.\"},{\"heading\":false,\"text\":\"--¿Usted vive en casa de Kapernumoff?--dijo, riéndose, a Sonia--. Me arregló ayer un chaleco. Yo vivo aquí, cerca de usted, en el departamento de la señora Gertrudis Karlovna Reslich, ¡qué casualidad!\"},{\"heading\":false,\"text\":\"Sonia le miró con atención.\"},{\"heading\":false,\"text\":\"--Somos vecinos--continuó diciendo con tono alegre--. Llegué ayer a San Petersburgo. Vamos, hasta que tenga el gusto de volver a verla.\"},{\"heading\":false,\"text\":\"Sonia no respondió.\"},{\"heading\":false,\"text\":\"Se abrió la puerta y la joven entró en su cuarto intimidada y vergonzosa.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Razumikin iba muy animado camino de la casa de Porfirio en compañía de su amigo.\"},{\"heading\":false,\"text\":\"--Perfectamente, querido--repetía muchas veces--. Estoy encantado, lo que se dice encantado. No sabía que tuvieses ninguna cosa empeñada en casa de la vieja y... y... ¿hace mucho tiempo que has estado en su casa?\"},{\"heading\":false,\"text\":\"--¿Que cuándo estuve?--murmuró Raskolnikoff, como procurando recordar--. Me parece que fué la antevíspera de su muerte. Por lo demás, no se trata de desempeñar ahora esos objetos--se apresuró a decir como si esta cuestión le hubiese vivamente preocupado--. No tengo más que un rublo, gracias a las locuras que hice ayer bajo la influencia de ese maldito delirio.\"},{\"heading\":false,\"text\":\"Y recalcó de una manera particular la palabra «delirio».\"},{\"heading\":false,\"text\":\"--Vamos, sí, sí--contestó Razumikin respondiendo a un pensamiento que se le había ocurrido en aquel instante--. ¿De modo que por eso tú...? La cosa me había chocado. Ahora me explico por qué no cesabas de hablar de sortijas, de cadenas de oro y de reloj mientras delirabas. Es claro, ahora todo me lo explico.\"},{\"heading\":false,\"text\":\"«¡Oh!--pensó Raskolnikoff--esa idea se la había metido en la cabeza; tengo la prueba: este hombre, que se haría crucificar por mí, se considera ahora feliz al explicarse por qué yo hablaba de sortijas durante mi delirio. Mi lenguaje ha debido confirmar a todos en sus sospechas.»\"},{\"heading\":false,\"text\":\"--¿Y qué, le encontraremos?--preguntó en alta voz.\"},{\"heading\":false,\"text\":\"--Ya lo creo que le encontraremos--respondió sin vacilar Razumikin--. Es un buen muchacho, amigo mío. Un poco desmadejado, es cierto, pero no dudo de que carezca de buenos modales, no; es por otro concepto por lo que lo encuentro desmadejado. Lejos de ser tonto, es muy inteligente; pero tiene un carácter particular... Es incrédulo... escéptico, cínico; le gusta burlarse de sus amigos. A pesar de esto, es fiel al _viejo juego_, es decir, no admite más que pruebas materiales... pero sabe su oficio. El año último desembrolló todo un proceso de asesinato en el cual faltaban todos los indicios. ¡Tiene tantos deseos de conocerte!\"},{\"heading\":false,\"text\":\"--¿Y por qué?\"},{\"heading\":false,\"text\":\"--¡Oh! no es porque... verás. En estos últimos días, cuando tú estabas malo, hemos tenido ocasión de hablar a menudo de ti... Asistía a nuestras conversaciones, y cuando supo que tú eras estudiante de Derecho y que te habías visto obligado a dejar la Universidad, dijo: «¡Qué lástima!» Yo he deducido de aquí... es decir, yo no me fundo solamente en esto, sino en otras cosas. Ayer, Zametoff... Oyeme, Raskolnikoff; cuando ayer te acompañaba estaba borracho y hablaba sin ton ni son; temo que hayas tomado mis palabras demasiado en serio...\"},{\"heading\":false,\"text\":\"--¿Qué es lo que me dijiste? ¿Que me tienen por loco? Acaso tengas razón--respondió Raskolnikoff con sonrisa forzada.\"},{\"heading\":false,\"text\":\"Se callaron. Razumikin estaba radiante de júbilo y Raskolnikoff lo advertía con cólera. Lo que su amigo acababa de decirle acerca del juez de instrucción no dejaba de inquietarle.\"},{\"heading\":false,\"text\":\"«Lo esencial es saber--pensó Raskolnikoff--si Porfirio tiene conocimiento de mi visita ayer a casa de la bruja y de la pregunta que hice acerca de la sangre. Es preciso, ante todo, que yo compruebe esto. Es preciso, desde el primer momento, desde mi entrada en su despacho, que lo lea sobre su rostro; de otro modo, aunque me pierda, seré sincero.»\"},{\"heading\":false,\"text\":\"--¿Sabes una cosa?--dijo bruscamente dirigiéndose a Razumikin con maliciosa sonrisa--. Me parece que desde esta mañana estás muy agitado. ¿No es verdad?\"},{\"heading\":false,\"text\":\"--No, de ninguna manera--respondió Razumikin contrariado.\"},{\"heading\":false,\"text\":\"--No me engaño, amigo mío. Hace poco estabas sentado en el borde de una silla, lo que nunca te ocurre. Parecía que te hallabas sobre pinchos; te sobresaltabas a cada instante. Tu humor variaba sin cesar. Tan pronto te ponías colérico, tan pronto dulce como la miel. Hasta te ruborizabas. Sobre todo, cuando te invitaron a comer, te pusiste del color de la grana.\"},{\"heading\":false,\"text\":\"--¡Qué absurdo! ¿Por qué dices eso?\"},{\"heading\":false,\"text\":\"--¿Sabes que tienes timideces de colegial? ¡Demonio! ¿Te pones otra vez colorado?\"},{\"heading\":false,\"text\":\"--¡Eres insoportable!\"},{\"heading\":false,\"text\":\"--Pero, ¿por qué esa confusión, Romeo? Deja hacer; yo lo contaré todo hoy en alguna parte, ¡ja, ja, ja! ¡cómo se va a reír mi madre y otra persona!\"},{\"heading\":false,\"text\":\"--Escucha, escucha, déjate de bromas y ¡diablo!--murmuró Razumikin helado de terror--. ¿Qué le vas a contar? ¡di!... ¡Qué puerco eres!\"},{\"heading\":false,\"text\":\"--Estás hecho una verdadera rosa de primavera. ¡Y si supieses qué bien te sienta eso! ¡Un Romeo de dos archinas y doce verchok! ¡pero, vamos, veo que te has lavado hoy y te has cortado las uñas! ¿Cuánto tiempo te has estado arreglando? ¡Calle! ¡Si hasta creo que te has dado pomada! ¡Baja, baja la cabeza, para que te huela!\"},{\"heading\":false,\"text\":\"--¡¡¡Indecente!!!\"},{\"heading\":false,\"text\":\"Raskolnikoff soltó la carcajada, y esta hilaridad que el joven, en apariencia, no podía dominar, duraba aún cuando llegaron a casa de Porfirio Petrovitch. Desde el cuarto podían oírse las risas del visitante en la antesala. Esto era precisamente lo que quería Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¡Si dices una palabra, te reviento!--murmuró Razumikin furioso, agarrando por un brazo a su amigo.\"}]},{\"title\":\"tercera parte — capítulo V\",\"blocks\":[{\"heading\":false,\"text\":\"Raskolnikoff entró en el despacho del juez de instrucción con la fisonomía de un hombre que hace todo lo posible para estar serio y sólo lo consigue a medias. Detrás de él entró disgustado Razumikin y más rojo que un pavo, con el semblante alterado por la cólera y por la vergüenza. La figura desgarbada y la cara mohina de este mocetón eran bastante chuscas para justificar la hilaridad de su compañero. Porfirio Petrovitch, en pie en medio de la habitación, interrogaba con la mirada a los dos visitantes. Raskolnikoff se inclinó ante el dueño de la casa, cambió con él un fuerte apretón de manos y fingió hacer un violento esfuerzo para ahogar su deseo de reír, mientras que decía su nombre y clase; acababa de recobrar su sangre fría y de balbucear algunas palabras, cuando, en medio de la presentación, sus ojos se encontraron por casualidad con Razumikin, y entonces no pudo contentarse y su seriedad se trocó en una carcajada, tanto más ruidosa cuanto más comprimida. Razumikin sirvió a maravilla los propósitos de su amigo, porque aquel desatinado reír le hizo montar en cólera, lo que acabó de dar a toda la escena apariencia de franca y natural alegría.\"},{\"heading\":false,\"text\":\"--¡Ah, bribón!--vociferó con tan violento ademán, que derribó un veladorcito sobre el cual estaba un vaso que había contenido te.\"},{\"heading\":false,\"text\":\"--Señores, ¿por qué me echan ustedes a perder el mobiliario? Es un perjuicio que causan ustedes al Estado--exclamó alegremente Porfirio Petrovitch.\"},{\"heading\":false,\"text\":\"Raskolnikoff se reía con tantas ganas, que durante algunos momentos se olvidó de retirar la mano de la del juez de instrucción; pero hubiera sido poco natural dejarla más tiempo; así es que la separó en el momento oportuno para dar la mayor verosimilitud posible al papel que representaba.\"},{\"heading\":false,\"text\":\"Razumikin, por su parte, se hallaba más confuso que al principio, a causa de haber tirado el velador y roto el vaso. Después de haber contemplado con aire sombrío las consecuencias de su arrebato, se dirigió a la ventana, y allí, dando la espalda al público, se puso a mirar por ella, mas sin ver nada. Porfirio Petrovitch se reía por cortesía; pero, evidentemente, aguardaba explicaciones. En un rincón, sentado en una silla, estaba Zametoff. Al entrar los visitantes se había levantado a medias, tratando de sonreír; sin embargo, no parecía engañado por esta escena, y observaba a Raskolnikoff con curiosidad particular. Este último no había esperado encontrar allí al polizonte, y su presencia le causó una desagradable sorpresa.\"},{\"heading\":false,\"text\":\"«He ahí una cosa con la que no contaba»--pensó.\"},{\"heading\":false,\"text\":\"--Perdóneme usted, se lo suplico--dijo alto, con cortedad fingida, Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¡Bah! Me proporcionan ustedes un placer. Han entrado de un modo tan divertido... Ese no quiere dar los buenos días--añadió Porfirio Petrovitch, indicando con un movimiento de cabeza a Razumikin.\"},{\"heading\":false,\"text\":\"--No sé por qué se ha enfurecido conmigo. Le he dicho solamente en la calle que se parecía a Romeo... se lo he demostrado... y no ha pasado más.\"},{\"heading\":false,\"text\":\"--¡Imbécil!--gritó Razumikin, sin volver la cabeza.\"},{\"heading\":false,\"text\":\"--Ha debido de tener motivos más graves, para tomar tan a mal una burla insignificante--observó, riendo, Porfirio Petrovitch.\"},{\"heading\":false,\"text\":\"--Ya pareció el juez de instrucción... Siempre investigador. ¡Todos al diablo!--replicó Razumikin, y echándose a reír y recobrando súbitamente su buen humor, se acercó a Porfirio Petrovitch--. Basta de tonterías, y a nuestro asunto. Te presento a mi amigo Rodión Romanovitch Raskolnikoff, que ha oído hablar mucho de ti y desea conocerte; tiene, además, que hablarte de una cosa. ¡Eh, Zametoff! ¿Por qué diantre estás aquí? De modo que os conocíais, ¿y desde cuándo?\"},{\"heading\":false,\"text\":\"«¿Qué quiere decir esto?»--se preguntó con inquietud Raskolnikoff.\"},{\"heading\":false,\"text\":\"La pregunta de Razumikin pareció molestar algo a Zametoff; sin embargo, se repuso en seguida.\"},{\"heading\":false,\"text\":\"--Fué ayer, en su casa, cuando nos conocimos--dijo con desenvoltura.\"},{\"heading\":false,\"text\":\"--¡Vamos! Entonces ha sido la mano de la Providencia la que ha arreglado todo esto. Figúrate, Porfirio, que la semana pasada me había manifestado vivos deseos de que te lo presentase; pero, según se ve, no habéis tenido necesidad de mí. ¿Tienes tabaco?\"},{\"heading\":false,\"text\":\"El juez estaba en traje de la mañana. Batín de casa, pantuflas en chancleta y camisa muy limpias. Era hombre de treinta y cinco años, más bien bajo que alto, grueso y ligeramente panzudo. No llevaba barba ni bigote, y tenía los cabellos cortados al rape. Su cabeza, gruesa y redonda, presentaba una redondez particular en la región de la nuca. Su rostro gordinflón también redondo y un poco aplastado, no carecía ni de vivacidad ni de alegría, aunque la tez, de un color amarillento obscuro, estaba lejos de indicar buena salud. Se hubiera podido encontrar en él hasta cierta candidez, si no hubiera sido por los ojos que, velados por pestañas casi blancas, parecían estar siempre guiñados, como si hicieran signos de inteligencia a alguien. La mirada de estos ojos daba un extraño mentís al resto de la fisonomía. A primera vista, el físico del juez de instrucción ofrecía cierta semejanza con el de un campesino; pero esta ilusión no engañaba por mucho tiempo al observador inteligente.\"},{\"heading\":false,\"text\":\"En cuanto oyó que Raskolnikoff tenía que tratar con él de un negocio, Porfirio Petrovitch le invitó a que se sentase en el diván, tomando él asiento en el otro extremo, y poniéndose con gran celo a su disposición. De ordinario nos sentimos un poco molestos cuando un hombre, a quien apenas conocemos, manifiesta una gran curiosidad por oírnos, y nuestra cortedad aumenta cuando el objeto de que vamos a hablarle es a nuestros propios ojos de poca importancia.\"},{\"heading\":false,\"text\":\"Sin embargo, Raskolnikoff pudo, en cortas y precisas palabras, exponer su deseo y observar al mismo tiempo, mientras hablaba, a Porfirio Petrovitch. Este, por su parte, no le quitaba los ojos de encima. Razumikin, sentado enfrente de él, escuchaba con impaciencia, y sus miradas iban sin cesar de su amigo al juez de instrucción y viceversa, cosa que pasaba los linderos de lo natural.\"},{\"heading\":false,\"text\":\"«¡Ese imbécil!»--decíase interiormente Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Es preciso hacer una declaración a la policía--respondió con indiferencia Porfirio Petrovitch--. Expondrá usted que, informado de tal acontecimiento, es decir, de ese asesinato, desea manifestar al juez de instrucción encargado del proceso, que tales o cuales objetos le pertenecen a usted, y que quiere desempeñarlos... Por lo demás, ya se le escribirá a usted.\"},{\"heading\":false,\"text\":\"--Desgraciadamente--replicó Raskolnikoff con fingida cortedad--no estoy en fondos... y mis medios no me permiten desempeñar esas baratijas... ¿Ve usted?... Quisiera limitarme a declarar que esos objetos son míos, y que, en cuanto tenga dinero...\"},{\"heading\":false,\"text\":\"--Eso no importa--replicó Porfirio Petrovitch, que acogió fríamente esta explicación financiera--; por lo demás, puede usted, si quiere, escribirme directamente, declarando que, enterado de lo ocurrido, desea usted decirme que tales objetos le pertenecen y que...\"},{\"heading\":false,\"text\":\"--¿Y puedo escribir esa carta en cualquier papel?--interrumpió Raskolnikoff afectando siempre no preocuparse de otra cosa que del aspecto pecuniario de la cuestión.\"},{\"heading\":false,\"text\":\"--¡Oh! en cualquier papel.\"},{\"heading\":false,\"text\":\"Porfirio Petrovitch pronunció estas palabras con aire francamente burlón, haciendo un guiño a Raskolnikoff. Por lo menos, el joven hubiera jurado que aquel movimiento de ojos se dirigía a él y que encubría mal una segunda intención. Quizás después de todo se engañaba, porque aquello duró apenas el espacio de un segundo.\"},{\"heading\":false,\"text\":\"«Ese lo sabe»--se dijo instantáneamente.\"},{\"heading\":false,\"text\":\"--Perdóneme usted haberle molestado por tan poca cosa--añadió bastante desconcertado--. Esos objetos valen en junto cinco rublos, pero tienen para mí especial valor, y confieso que tuve mucha inquietud cuando supe...\"},{\"heading\":false,\"text\":\"--Por esto te pusiste tan alterado ayer al oírme decir a Zosimoff, que Porfirio Petrovitch interrogaba a los propietarios de los objetos empeñados--recalcó con intención evidente Razumikin.\"},{\"heading\":false,\"text\":\"Era demasiado. Raskolnikoff no pudo contenerse y lanzó sobre aquel inadvertido hablador una mirada relampagueante de cólera; mas, comprendiendo en seguida que acababa de cometer una imprudencia, trató de repararla.\"},{\"heading\":false,\"text\":\"--Parece que te burlas de mí, amigo mío--dijo a Razumikin, con aire ofendido--. Reconozco que me preocupo, quizá demasiado, de cosas muy insignificantes a tus ojos; pero esto no es una razón para mirarme como un hombre egoísta y avaro; estas miserias pueden tener valor para mí. Como te decía hace un momento, ese reloj de plata, que apenas vale un groch, es lo único que me queda de mi padre. Búrlate cuanto quieras, pero mi madre ha venido a verme--y al decir esto se volvió hacia el juez--, y si supiese--continuó de nuevo dirigiéndose a Razumikin poniendo la voz todo lo temblorosa que pudo--, si supiese que no tengo el reloj, te aseguro que la pobre sentiría un nuevo disgusto. ¡Oh, las mujeres!\"},{\"heading\":false,\"text\":\"--¿Pero, qué dices? No me has entendido. Has interpretado mal mi pensamiento--protestaba Razumikin todo acongojado.\"},{\"heading\":false,\"text\":\"--¿Habré hecho bien? ¿Habré forzado demasiado la nota?--se preguntaba ansiosamente Raskolnikoff--. ¿Por qué habré dicho yo «las mujeres»?\"},{\"heading\":false,\"text\":\"--¡Ah! ¿Ha venido su madre de usted?--preguntó Porfirio Petrovitch.\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Cuándo ha llegado?\"},{\"heading\":false,\"text\":\"--Ayer noche.\"},{\"heading\":false,\"text\":\"El juez de instrucción se quedó callado un momento como si reflexionase.\"},{\"heading\":false,\"text\":\"--Los objetos que le pertenecen no hubieran podido extraviarse jamás--repuso con tono tranquilo y frío--. Desde hace tiempo, esperaba yo la visita de usted.\"},{\"heading\":false,\"text\":\"Al decir esto aproximó vivamente el cenicero a Razumikin que sacudía implacablemente sobre el tapete su cigarro. Raskolnikoff se estremeció; pero el juez de instrucción no pareció advertirlo, ocupado como estaba en preservar el tapete.\"},{\"heading\":false,\"text\":\"--¿Cómo? ¿Esperabas su visita? ¿De modo que sabías que había empeñado algunas cosas?\"},{\"heading\":false,\"text\":\"Sin responder, Porfirio Petrovitch se dirigió a Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Las alhajas de usted, una sortija y un reloj, se encontraban en casa de la víctima envueltas en un pedazo de papel en el cual estaba completamente legible, escrito con lápiz, el nombre de usted con la indicación del día en que se habían empeñado esos objetos.\"},{\"heading\":false,\"text\":\"--¡Qué memoria tiene usted para todas estas cosas!--dijo Raskolnikoff con sonrisa forzada, procurando sobre todo mirar con serenidad al juez de instrucción; no pudo, sin embargo, contenerse, y añadió bruscamente--: digo esto, porque deben de ser muchos, sin duda, los dueños de objetos empeñados y debe de costarle a usted, me parece a mí, mucho trabajo recordarlos a todos... Pero veo, por el contrario, que no olvida usted ni a uno... y... y...\"},{\"heading\":false,\"text\":\"«¡Estúpido! ¡Idiota! ¿qué necesidad tenías de añadir esto?»\"},{\"heading\":false,\"text\":\"--Es que casi todos se han dado ya a conocer y usted no se había presentado aún--respondió Porfirio con un dejo casi imperceptible de burla.\"},{\"heading\":false,\"text\":\"--No me encontraba muy bien.\"},{\"heading\":false,\"text\":\"--Lo he oído decir. Se me ha dicho que estaba usted muy enfermo. Todavía está usted pálido.\"},{\"heading\":false,\"text\":\"--No, no estoy pálido... al contrario, me siento muy bien--respondió Raskolnikoff con tono brutal y violento.\"},{\"heading\":false,\"text\":\"Sentía hervir en él una cólera que no podía dominar.\"},{\"heading\":false,\"text\":\"«El arrebato va a hacerme cometer alguna tontería--pensó--. Pero, ¿por qué me exasperan?»\"},{\"heading\":false,\"text\":\"--Que no se sentía muy bien, ¡vaya un eufemismo!--exclamó Razumikin--. La verdad es que hasta ayer ha estado casi sin conocimiento. ¿Lo creerías, Porfirio? Ayer, pudiendo apenas sostenerse sobre las piernas, aprovechando un momento en que Zosimoff y yo acabábamos de dejarle, se vistió, salió de su casa y estuvo vagando hasta media noche, Dios sabe por dónde... y estando en completo delirio; ¿puedes imaginarte una cosa semejante? Es un caso de los más notables.\"},{\"heading\":false,\"text\":\"--¡Bah! _¿En estado completo de delirio?_--dijo Petrovitch con el movimiento de cabeza propio de los campesinos rusos.\"},{\"heading\":false,\"text\":\"--Es absurdo, ¿verdad? Por lo demás, yo no tengo necesidad de decirle a usted esto. La convicción de usted está formada--dejó escapar Raskolnikoff cediendo a un arrebato de cólera; pero Porfirio Petrovitch no pareció fijarse en estas extrañas palabras.\"},{\"heading\":false,\"text\":\"--¿Cómo habías de haber salido tú, si no hubieses estado delirando?--dijo exaltándose Razumikin--. ¿Para qué semejante salida? ¿Con qué objeto? Y sobre todo, ¿por qué escapar así, ocultándote? Has de convenir conmigo en que tenías perturbadas tus facultades mentales. Te lo digo así, muy clarito, ahora que el peligro ha pasado.\"},{\"heading\":false,\"text\":\"--Me habían fastidiado tanto ayer...--dijo Raskolnikoff dirigiéndose al juez de instrucción con una sonrisa que parecía un desafío--, y queriendo librarme de ellos salí para alquilar un cuarto en que no pudiesen descubrirme; había tomado para este efecto cierta cantidad. El señor Zametoff me vió el dinero en la mano; dígame usted, señor Zametoff, si deliraba yo ayer o si estaba en mi sano juicio. Sea usted el árbitro de nuestra disputa.\"},{\"heading\":false,\"text\":\"En aquel momento de buena gana hubiera estrangulado al polizonte que le irritaba por su mutismo y la expresión de su mirada.\"},{\"heading\":false,\"text\":\"--Me pareció que hablaba usted muy sensatamente y con mucha sutileza; pero le encontré a usted demasiado irascible--declaró secamente Zametoff.\"},{\"heading\":false,\"text\":\"--Y hoy--añadió Porfirio--me ha dicho Nikodim Fomitch que había encontrado a usted ayer, a hora muy avanzada de la noche, en casa de un funcionario que acababa de ser atropellado por un carruaje...\"},{\"heading\":false,\"text\":\"--Eso mismo viene en apoyo de lo que yo decía--dijo Razumikin--. ¿No te has conducido como un loco en casa de un funcionario? ¿No te despojaste de todo tu dinero para pagar el entierro? Comprendo que quisieses socorrer a la viuda; pero podías haberle dado quince rublos, veinte, si quieres, pero siempre reservándote algo para ti. Por el contrario, lo diste... te desprendiste de tus veinticinco rublos.\"},{\"heading\":false,\"text\":\"--Pero, ¿qué sabes tú? Tal vez he encontrado un tesoro. Ayer estaba yo en vena de ser generoso... El señor Zametoff, aquí presente, sabe que he encontrado un tesoro... Pido a ustedes perdón de haberles molestado durante media hora en mi insubstancial palabrería--prosiguió con los labios temblorosos dirigiéndose a Porfirio--. He importunado a ustedes, ¿no es eso?\"},{\"heading\":false,\"text\":\"--¿Qué dice usted? Todo al contrario; si usted supiese cuánto me interesa y lo curioso que resulta oírle... Confieso a usted que estoy encantado de haber recibido su visita.\"},{\"heading\":false,\"text\":\"--¡Vamos, danos te! Tenemos el gaznate seco--exclamó Razumikin.\"},{\"heading\":false,\"text\":\"--¡Excelente idea!, pero antes del te querrás tomar algo más sólido, ¿eh?\"},{\"heading\":false,\"text\":\"--¡Caracoles! ¡Algo más sólido! ¿A qué esperas?\"},{\"heading\":false,\"text\":\"Porfirio Petrovitch salió para encargar el te.\"},{\"heading\":false,\"text\":\"En el cerebro de Raskolnikoff, hervían multitud de pensamientos. Estaba por extremo excitado.\"},{\"heading\":false,\"text\":\"--Ni siquiera se toman el trabajo de fingir, no usan muchas precauciones; este es el punto principal. Puesto que Porfirio no me conocía, ¿por qué ha hablado de mí con Nikodim Fomitch? No se cuidan de ocultar que husmean mis huellas como traílla de perros. ¡Me escupen en la cara desfachatadamente!--decía temblando de rabia--. Id derechamente contra mí, pero no juguéis conmigo como el gato con el ratón. Eso es una descortesía, Porfirio Petrovitch, y yo no lo tolero... Me levantaré y os arrojaré la verdad a la cara y veréis entonces cuánto os desprecio.\"},{\"heading\":false,\"text\":\"Respiró con ansia y continuó pensando:\"},{\"heading\":false,\"text\":\"--¿Pero si todo esto no existiese más que en mi imaginación, si fuese un espejismo, si hubiese interpretado mal las cosas?... Tratemos de sostener nuestro feo papel y no vayamos a perdernos como un imbécil por un arrebato de cólera. Quizá les atribuyo intenciones que no tienen. Sus palabras carecen en rigor de malicia, nada de particular tienen; pero deben de encerrar una segunda intención. ¿Por qué Zametoff ha observado que yo le _hablé con mucha sutileza_? ¿por qué me han hablado con ese tono? Sí; me han hablado con un tono particular... ¿Cómo todo esto no le ha chocado a Razumikin? Ese estúpido no se entera jamás de nada. Creo que tengo otra vez fiebre. ¿Me hizo Porfirio hace un poco un guiño con los ojos, o acaso me he engañado? No pienso más que absurdos; ¿por qué había de guiñarme los ojos? ¿Se proponen irritar mis nervios para empujarme hasta el fin? todo esto es pura fantasmagoría o saben... Zametoff ha estado insolente; tiempo ha tenido desde ayer de reflexionar. Ya presumía yo que cambiaría de opinión. Está aquí como en su casa, y eso que ha venido hoy por primera vez. Porfirio no le trata como a un extraño y hasta se sienta volviéndole la espalda. Estos dos se han hecho amigos y sin duda por mi causa han comenzado sus relaciones. Seguro estoy de que hablaban de mí cuando he llegado. ¿Tienen noticia de mi visita al cuarto de la vieja? Desearía saberlo... Cuando he dicho que había salido para alquilar un cuarto, Porfirio se ha hecho el desentendido... pero he hecho bien en decirlo; más tarde me podrá servir; en cuanto al delirio, el juez de instrucción no parece darle crédito. «Sabe perfectamente lo que hice yo aquella noche... Ignoraba la llegada de mi madre... ¡Y aquella bruja que había apuntado con lápiz la fecha del empeño!... No, no, la seguridad que afectáis no me engaña; hasta ahora no tenéis hechos; os fundáis solamente en vagas conjeturas. Citadme un hecho, si podéis alegar uno solo en contra mía. La visita que hice a la vieja nada prueba; se puede explicar por un delirio. Me acuerdo de lo que dije a los dos obreros y al _dvornik_... ¿Saben que estuve allí? No me iré hasta que me cerciore de que lo saben o no. ¿Por qué he venido? Pero he aquí que ahora me encolerizo y esto sí que es de temer. ¡Ah, qué irritable soy! Después de todo más vale quizá que sea así: sigo representando un papel de enfermo. Parece que va a interrogarme... Esto me va a hacer vacilar y perder la cabeza. ¿Por qué he venido?»\"},{\"heading\":false,\"text\":\"Todas estas ideas atravesaron su espíritu con la rapidez del relámpago. Al cabo de un instante volvió Porfirio Petrovitch. Parecía de muy buen humor.\"},{\"heading\":false,\"text\":\"--Ayer, al salir de tu casa, amigo mío, no estaba yo muy bien de cabeza--comenzó a decir dirigiéndose a Razumikin con una alegría que no había demostrado hasta entonces--; pero yo estoy bien. ¿Y qué tal? ¿la velada fué interesante? Os dejé en el momento más animado. ¿Por quién quedó la victoria?\"},{\"heading\":false,\"text\":\"--Como es natural, por nadie: todos argumentaron a más y mejor en pro de sus viejas tesis. Figúrate que la discusión versaba ayer sobre lo siguiente--agregó, volviéndose hacia Raskolnikoff--: ¿hay crímenes o no los hay? ¡Cuántas tonterías dijeron con tal motivo!\"},{\"heading\":false,\"text\":\"--¿Qué hay en eso de extraordinario? Es una cuestión social que ni siquiera tiene el mérito de la novedad--respondió distraídamente Raskolnikoff.\"},{\"heading\":false,\"text\":\"--La cuestión no se planteó en esos términos--observó el juez.\"},{\"heading\":false,\"text\":\"--Es verdad, no fué precisamente en esos términos--repuso Razumikin con su insistencia de costumbre--. Escucha, Rodia, y dinos tu opinión. Ayer me hicieron perder la paciencia; te esperaba porque me habías prometido tu visita. Los socialistas comenzaron por exponer su teoría. Sabido es en qué consiste: el crimen es una protesta contra un orden social mal organizado; nada más. Con eso creen haberlo dicho todo; no admiten otro móvil para los actos criminales; según ellos, el hombre es lanzado al crimen únicamente por el ambiente. Es su frase favorita.\"},{\"heading\":false,\"text\":\"--A propósito de crimen y de ambiente--dijo Porfirio Petrovitch, dirigiéndose a Raskolnikoff--; recuerdo un trabajo de usted que me interesó vivamente; hablo de su artículo sobre el _Crimen_... no me acuerdo bien del título. Tuve el gusto de leerlo hace dos meses en _La Palabra Periódica_.\"},{\"heading\":false,\"text\":\"--¡Un artículo mío en _La Palabra Periódica_!--exclamó Raskolnikoff, sorprendido--. Recuerdo que, hace seis meses, cuando salí de la Universidad, escribí un artículo a propósito de un libro; pero lo llevé a _La Palabra Semanal_ y no a _La Palabra Periódica_.\"},{\"heading\":false,\"text\":\"--Pues fué publicado en esta última.\"},{\"heading\":false,\"text\":\"--Como _La Palabra Semanal_ suspendió su publicación, mi artículo no pudo salir.\"},{\"heading\":false,\"text\":\"--Pero como esa revista se fundió con _La Palabra Periódica_, hace dos meses que apareció en ésta el artículo a que me refiero. ¿No lo sabía usted?\"},{\"heading\":false,\"text\":\"--No.\"},{\"heading\":false,\"text\":\"--Pues bien, puede usted ir a cobrar su importe. ¡Qué raro es usted! Ni siquiera se entera de lo que directamente le interesa.\"},{\"heading\":false,\"text\":\"--¡Muy bien, Rodia!--exclamó Razumikin--. Tampoco yo lo sabía. Hoy mismo voy a pedir el número en el gabinete de lectura. ¿Hace dos meses que se publicó? ¿En qué fecha? No importa, lo encontraré. ¡Y qué callado se lo tenía!\"},{\"heading\":false,\"text\":\"--¿Cómo ha sabido usted que el artículo era mío? Yo no lo había firmado.\"},{\"heading\":false,\"text\":\"--Lo he sabido recientemente por una mera casualidad. El redactor jefe es amigo mío, y me descubrió el secreto. Ese trabajo me interesó sobremanera.\"},{\"heading\":false,\"text\":\"--Examinaba yo en él, lo recuerdo perfectamente, el estado psicológico del delincuente en el momento de cometer el crimen.\"},{\"heading\":false,\"text\":\"--Sí, y procuraba usted demostrar que en ese momento el criminal es un enfermo. Me parece una teoría muy original; pero no fué ésa la parte de su artículo que más me interesó; me fijé especialmente en un pensamiento que se encontraba en el mismo, y que, por desgracia, explicaba usted con demasiada concisión. En una palabra, como sin duda recordará usted, parece que quería dar a entender que existen en la tierra hombres que pueden, o por mejor decir, que tienen el derecho absoluto de cometer todo género de acciones culpables y criminales; hombres, en fin, para quienes en cierto modo no rezan las leyes.\"},{\"heading\":false,\"text\":\"Al oír esta pérfida interpretación de su pensamiento, Raskolnikoff se sonrió.\"},{\"heading\":false,\"text\":\"--¿Cómo? ¿Qué? ¿El derecho al crimen? No; lo que quiso decir es que el criminal se ve impulsado al delito por la influencia irresistible del ambiente. ¿No es eso?--preguntó Razumikin con inquietud.\"},{\"heading\":false,\"text\":\"--No, no se trata de eso--replicó Porfirio--. En dicho artículo se clasifica a los hombres en ordinarios y extraordinarios. Los primeros deben vivir en la obediencia y no tienen derecho a violar la ley; los segundos poseen el derecho de cometer todos los crímenes y de saltar por encima de todas las leyes, precisamente porque son hombres extraordinarios: si no me engaño, esto es lo que usted dijo.\"},{\"heading\":false,\"text\":\"--¡Eh! ¿Como? ¡Es imposible que sea eso!--balbució Razumikin estupefacto.\"},{\"heading\":false,\"text\":\"Raskolnikoff volvió a sonreír. Había comprendido en seguida que se trataba de arrancarle una declaración de principios, y acordándose de su artículo no vaciló en explicarlo.\"},{\"heading\":false,\"text\":\"--No es eso--comenzó a decir con tono sencillo y modesto--. Confieso, no obstante, que ha reproducido usted con bastante exactitud mi pensamiento, y hasta, si usted quiere, diré que con mucha exactitud (pronunció estas últimas palabras con cierta satisfacción); lo que yo no he dicho, como usted me lo hace decir, es que las personas extraordinarias tengan absoluto derecho para cometer en todo caso cualesquiera acciones criminales. Supongo que la censura no habría dejado pasar un artículo concebido en tales términos. He aquí sencillamente lo que yo me he permitido decir: el hombre extraordinario tiene el derecho, no oficialmente, sino por sí mismo, de autorizar a su conciencia a franquear ciertos obstáculos; pero sólo en el caso en que se lo exija la realización de su idea, la cual puede ser a veces útil a todo el género humano. Usted pretende que mi artículo no es claro y voy a tratar de explicarlo: quizá no me engañe al suponer que tal es el deseo de usted. Según mi parecer, si los inventos de Kleper y de Newton, a causa de ciertas circunstancias no hubieran podido darse a conocer sino mediante el sacrificio de uno, de diez, de ciento o de un número mayor de vidas que hubiesen sido obstáculos a esos descubrimientos, Newton habría tenido el derecho, más aún, habría tenido el deber de _suprimir_ a esos diez, a esos cien hombres, a fin de que sus descubrimientos fuesen conocidos por el mundo entero. Esto no quiere decir, como usted comprenderá, que Newton tuviese el derecho de asesinar a quien se le antojase ni de robar a quien le viniese en gana. En mi artículo insisto, me acuerdo de ello, sobre esta idea, a saber: que todos los legisladores y guías de la humanidad, comenzando por los más antiguos y pasando por Licurgo, Solón y Mahoma hasta llegar a Napoleón, etc., todos sin excepción han sido delincuentes, porque en el hecho de dar nuevas leyes han violado las antiguas, que eran observadas fielmente por la sociedad y transmitidas a las generaciones futuras; indudablemente no retrocedían ellos ante el derramamiento de sangre en cuanto les podía ser útil. Es también de notar que todos estos bienhechores y guías de la humanidad han sido terriblemente sanguinarios. Por consiguiente, no sólo los grandes hombres sino todos aquellos que se elevan sobre el nivel común y que son capaces de decir alguna cosa nueva, deben, en virtud de su naturaleza propia, ser necesariamente delincuentes, en mayor o menor grado, según los casos. De otro modo, sería imposible salir de la rutina; y quedarse en ella, es cosa en que no pueden consentir, pues, a mi manera de ver, su propio deber se lo prohibe. En resumen, ya ve usted que aquí no hay nada de particular y nuevo en mi artículo. Esto ha sido dicho e impreso mil veces. En cuanto a mi clasificación de personas en ordinarias y extraordinarias, reconozco que es un poco caprichosa, pero dejo a un lado la cuestión de cifras, a la que doy poca importancia. Creo únicamente que en el fondo mi pensamiento es justo. Este pensamiento se resume diciendo que la Naturaleza divide a los hombres en dos categorías: la una inferior, la de los hombres ordinarios, cuya sola misión es la de reproducir seres semejantes a sí mismos; la otra, superior, que comprende los hombres que poseen el don o el talento de hacer oír una palabra nueva. Claro es que las subdivisiones son innumerables; pero las dos categorías presentan rasgos distintivos bastante determinados. Pertenecen a la primera, de una manera general, los conservadores, los hombres de orden que viven en la obediencia y que la aman. En mi opinión están obligados a obedecer, porque tal es su destino, y porque esto no tiene nada de humillante para ellos. El segundo grupo se compone exclusivamente de hombres que violan la ley o tienden, según sus medios, a violar; sus delitos son naturalmente relativos y de una gravedad variable. La mayor parte reclama la destrucción de lo que es, en nombre de lo que debe ser. Mas si por su idea deben verter la sangre y pasar por encima de cadáveres, pueden en conciencia hacer ambas cosas en interés de su idea, por supuesto. En ese sentido, mi artículo reconocía el derecho al crimen (¿recuerda usted que nuestro punto de partida ha sido una cuestión jurídica?). Por otra parte, no hay que inquietarse mucho; casi siempre la masa les niega ese derecho, los decapita o los cuelga, y obrando de esta suerte, cumple con mucha justicia su misión conservadora hasta el día, si bien es verdad que esta misma masa erige estatuas a los supliciados y los venera alguna que otra vez. El primer grupo es siempre dueño del presente, el segundo lo es del porvenir. El uno conserva el mundo y multiplica los habitantes; el otro, mueve al mundo y lo conduce a su objeto. Estos y aquéllos tienen absolutamente el mismo derecho a la existencia y ¡viva la guerra eterna! Hasta la nueva Jerusalén, por supuesto...\"},{\"heading\":false,\"text\":\"--De modo que usted cree en la nueva Jerusalén.\"},{\"heading\":false,\"text\":\"--Sí que creo--respondió enérgicamente Raskolnikoff, que durante su largo discurso había tenido los ojos bajos mirando obstinadamente un punto del tapete.\"},{\"heading\":false,\"text\":\"--¿Y cree usted en Dios? Perdóneme usted esta curiosidad.\"},{\"heading\":false,\"text\":\"--Sí que creo--repitió el joven mirando a Porfirio.\"},{\"heading\":false,\"text\":\"--¿Y en la resurrección de Lázaro?\"},{\"heading\":false,\"text\":\"--Sí. ¿Por qué me lo pregunta usted?\"},{\"heading\":false,\"text\":\"--¿Y cree usted al pie de la letra?\"},{\"heading\":false,\"text\":\"--Al pie de la letra.\"},{\"heading\":false,\"text\":\"--Dispense usted que le haga estas preguntas, esto me interesaba; pero, permítame, vuelvo al asunto de que hablábamos antes; no se ejecuta siempre a esos hombres extraordinarios; hay algunos, por lo contrario, que...\"},{\"heading\":false,\"text\":\"--¿Que triunfan en vida? ¡Oh, sí! esto ocurre, y entonces...\"},{\"heading\":false,\"text\":\"--Son ellos los que llevan al suplicio a los otros.\"},{\"heading\":false,\"text\":\"--Cuando es preciso. Y a decir verdad, ése es el caso más frecuente. En general, la observación es muy exacta.\"},{\"heading\":false,\"text\":\"--Muchas gracias. Pero, dígame usted, ¿cómo pueden distinguirse los hombres extraordinarios de los ordinarios? ¿Traen al nacer alguna señal? Soy de parecer que convendría un poco más de exactitud, una limitación en cierto modo más clara. Dispense usted esta inquietud natural en un hombre práctico y bien intencionado; pero, ¿no podrían llevar un traje particular, un emblema cualquiera? Porque, figúrese usted... si se produce una confusión, si un individuo de una categoría se figura que es de otra, y se pone, según la expresión feliz de usted, «a suprimir todos los obstáculos...»\"},{\"heading\":false,\"text\":\"--Eso ocurre con mucha frecuencia; esa observación es más sutil aún que la primera.\"},{\"heading\":false,\"text\":\"--Muchas gracias.\"},{\"heading\":false,\"text\":\"--No hay de qué darlas. Pero considere usted que el error sólo es posible en la primera categoría, es decir, en aquellos que he llamado quizá con impropiedad «hombres ordinarios». No obstante su tendencia innata a desobedecer, muchos de ellos, por efecto de un juego de la Naturaleza, se consideran hombres de la vanguardia, «demoledores», y se creen llamados a hacer oír la palabra «nueva», y esta ilusión es en ellos muy sincera. Al mismo tiempo no conocen de ordinario a los verdaderos innovadores y los desprecian como a gentes atrasadas y sin elevación de espíritu. Pero yo creo que no hay en eso un verdadero peligro y que no debe usted inquietarse, porque ellos no van muy lejos; sin duda se podría azotarlos como castigo a su error y volverlos de nuevo a su puesto; pero de todos modos, no hay necesidad de molestar al ejecutor: ellos mismos se aplican la disciplina, porque son personas muy morales y unas veces se prestan los unos a los otros estos servicios y otras veces se azotan ellos por sus propias manos... Ocasiones hay en que ellos mismos se imponen diversas penitencias públicas, lo que no deja de ser edificante; no debe usted preocuparse por ellos.\"},{\"heading\":false,\"text\":\"--¡Vamos! Por esta parte al menos, me ha tranquilizado usted; pero hay una cosa que todavía me preocupa: dígame usted, si le place, ¿hay muchas personas «extraordinarias que tienen el derecho de asesinar a las otras»? Pronto estoy a inclinarme ante ellas; pero si son muchas, confiese usted que la cosa será bastante desagradable.\"},{\"heading\":false,\"text\":\"--Tampoco por eso se debe usted inquietar--prosiguió en el mismo tono Raskolnikoff--. En general, nace un número muy escaso de hombres con una idea nueva, ni aun capaces de darse cuenta de lo que es nuevo. Es evidente que el reparto de los nacimientos en las diversas categorías y subdivisiones de la especie humana, debe de estar estrictamente determinado por una ley de la Naturaleza. Claro es que esta ley nos es desconocida; pero yo creo que existe y que llegará a descubrirse algún día. Una enorme masa de gente sólo ha venido a la tierra para dar al mundo, después de largos y misteriosos cruzamientos de razas, un hombre que, entre mil, poseerá alguna independencia; a medida que va aumentando el grado de independencia no se encuentra más que un hombre por cada diez mil, o por cada cien mil (son cifras aproximadas). Se cuenta un genio entre muchos millones de individuos, y quizá pasan millares de millones de hombres sobre la tierra, antes de que surja una de esas altas inteligencias que renuevan la faz del mundo. En una palabra, yo no he ido a mirar en la retorta en que todo eso se opera; pero hay, debe de haber una ley fija. En esto no puede existir el azar.\"},{\"heading\":false,\"text\":\"--Pero, ¿qué es eso? ¿Os estáis burlando los dos?--gritó Razumikin--. Esto es una comedia. ¡Se están divirtiendo el uno a costa del otro! ¿Hablas con formalidad, Rodia?\"},{\"heading\":false,\"text\":\"Sin responderle, Raskolnikoff levantó hacia él su rostro pálido en el que se pintaba cierta expresión de sufrimiento. Al observar la fisonomía tranquila y triste de su amigo, Razumikin encontró extraño el tono cáustico, provocador y descortés que había tomado Porfirio. Luego dijo:\"},{\"heading\":false,\"text\":\"--Sí, amigo mío, en efecto, esto es serio... Sin duda tiene razón al decir que no es nuevo y que se parece a todo lo que hemos oído y leído mil veces; pero lo que hay en ello verdaderamente original y que te pertenece realmente es, siento decirlo, eso del derecho de derramar sangre que concedes o prohibes, perdóname, con tanto fanatismo... He aquí, por consiguiente, el pensamiento principal de tu artículo. Esa autorización moral de matar es, a mi entender, más espantosa que lo sería la autorización legal, oficial...\"},{\"heading\":false,\"text\":\"--Exacto, más espantosa--afirmó Porfirio.\"},{\"heading\":false,\"text\":\"--No. La expresión ha ido más allá de tu pensamiento; no es eso lo que has querido decir; yo leeré tu artículo. Sucede, que hablando suele ir uno más lejos de lo que se proponía. Tú no puedes pensar tal cosa; yo lo leeré.\"},{\"heading\":false,\"text\":\"--No hay nada de eso en mi artículo; apenas he tocado esa cuestión--dijo Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Sí, sí--repuso el juez--; ahora comprendo sobre poco más o menos la manera que tiene usted de considerar el crimen; pero... perdone usted mi insistencia. Si un joven se imagina ser un Licurgo o un Mahoma... futuro, no hay que decir que comenzará por suprimir cuantos obstáculos le impidan cumplir su misión. Este tal me diría: «Yo emprendo una larga campaña, y para una campaña hace falta dinero...» Esto supuesto, se procuraría recursos... Ya adivina usted de qué manera...\"},{\"heading\":false,\"text\":\"Al oír estas palabras, Zametoff refunfuñó, no sabemos qué, en su rincón. Raskolnikoff no le miró siquiera.\"},{\"heading\":false,\"text\":\"--Obligado estoy a reconocer--respondió éste con calma--que, en efecto, existirán algunos de estos casos. Eso es un lazo que el amor propio tiende a los vanidosos y a los tontos. Los jóvenes, sobre todo, se dejan cazar con él.\"},{\"heading\":false,\"text\":\"--¿Lo está usted viendo?\"},{\"heading\":false,\"text\":\"--¿Y qué? Yo no tengo la culpa: sucede y sucederá siempre. Hace un momento, este amigo nuestro me reprendía por autorizar el asesinato--añadió señalando a Razumikin--; ¿qué importa? ¿Acaso no está la sociedad suficientemente protegida por las deportaciones, las cárceles, los jueces de instrucción y los presidios? ¿Por qué inquietarse? ¡Buscad al ladrón!\"},{\"heading\":false,\"text\":\"--¿Y si le encontramos?\"},{\"heading\":false,\"text\":\"--Peor para él.\"},{\"heading\":false,\"text\":\"--Por lo menos usted es lógico; ¿pero qué le diría su conciencia?\"},{\"heading\":false,\"text\":\"--¿Y a usted qué le importa eso?\"},{\"heading\":false,\"text\":\"--Es una cuestión que interesa al sentimiento humano.\"},{\"heading\":false,\"text\":\"--El que tiene conciencia sufre reconociendo su error; ése es su castigo, independientemente del presidio.\"},{\"heading\":false,\"text\":\"--¿De modo--preguntó Razumikin, frunciendo el entrecejo--, que los hombres de genio, aquellos a quienes les es concedido el derecho de matar, no deben experimentar ningún sufrimiento al derramar sangre?\"},{\"heading\":false,\"text\":\"--¿Qué quiere decir eso de «no deben»? El sufrimiento no se permite ni se prohibe. Que sufran si tienen piedad de su víctima... El sufrimiento acompaña siempre a una conciencia amplia y a un corazón profundo. Los hombres verdaderamente grandes, deben, me parece a mí, experimentar honda tristeza en la tierra--añadió Raskolnikoff, acometido de súbita melancolía, que formaba contraste con la conversación precedente.\"},{\"heading\":false,\"text\":\"Levantó los ojos, miró a todos los que estaban en la sala con aire soñador, sonrió y tomó su gorra. Estaba muy tranquilo, con la comparación, con la actitud que tenía cuando entró, y se daba cuenta de ello.\"},{\"heading\":false,\"text\":\"Todos se levantaron.\"},{\"heading\":false,\"text\":\"Porfirio Petrovitch volvió a la carga.\"},{\"heading\":false,\"text\":\"--Puede usted injuriarme o incomodarse o no conmigo; pero mi deseo es más fuerte que yo y es menester que le dirija todavía una pregunta. Verdaderamente me avergüenza abusar de usted de este modo... En tanto que pienso en esto, y para no olvidarla, quisiera comunicar a usted una idea que se me ha ocurrido...\"},{\"heading\":false,\"text\":\"--¡Bueno!... diga usted su idea--respondió Raskolnikoff en pie, pálido y serio, frente al juez de instrucción.\"},{\"heading\":false,\"text\":\"--Verá usted... verdaderamente no sé cómo expresarme... es una idea muy extraña, psicológica... Al escribir su artículo, es muy probable... que se considerase usted como uno de esos hombres «extraordinarios» de quienes hablaba hace poco... ¿No es así?\"},{\"heading\":false,\"text\":\"--Es muy posible--respondió desdeñosamente Raskolnikoff.\"},{\"heading\":false,\"text\":\"Razumikin hizo un movimiento.\"},{\"heading\":false,\"text\":\"--Si eso fuese así, ¿no estaría usted decidido, ya para triunfar de dificultades materiales, ya para facilitar el progreso de la humanidad, no se decidiría usted repito, a franquear el obstáculo, por ejemplo... a matar y a robar?\"},{\"heading\":false,\"text\":\"Al mismo tiempo guiñaba el ojo izquierdo y se reía silenciosamente como antes.\"},{\"heading\":false,\"text\":\"--Si estuviese decidido a eso, no lo diría a usted--replicó Raskolnikoff con acento altanero de desafío.\"},{\"heading\":false,\"text\":\"--Mi pregunta no tenía más objeto que el de una curiosidad literaria; la he hecho únicamente con el fin de penetrar el sentido del artículo de usted.\"},{\"heading\":false,\"text\":\"«¡Oh qué lazo tan grosero! ¡Qué malicia prendida con alfileres!»--pensó Raskolnikoff con algo de desprecio.\"},{\"heading\":false,\"text\":\"--Permítame usted que le diga--respondió secamente--que yo no me creo ni un Mahoma, ni un Napoleón, ni ningún otro personaje de este género: por consiguiente, no puedo explicarle a usted lo que yo haría si estuviese en lugar de ellos.\"},{\"heading\":false,\"text\":\"--¿Quién hay ahora en Rusia que no se crea un Napoleón?--dijo con brusca familiaridad el juez instructor.\"},{\"heading\":false,\"text\":\"Esta vez también la entonación de su voz delataba un segundo fin.\"},{\"heading\":false,\"text\":\"--¿Será acaso un futuro Napoleón el que ha matado a Alena Ivanovna esta semana última?--saltó, de repente, desde su rincón Zametoff.\"},{\"heading\":false,\"text\":\"Sin pronunciar una palabra, Raskolnikoff fijó en Porfirio una mirada fría y penetrante. Las facciones de Razumikin se contrajeron. Un rato hacía ya que parecía dudar de algo. Paseó en torno suyo una mirada irritada. Durante un minuto reinó sombrío silencio. Raskolnikoff se dispuso a salir.\"},{\"heading\":false,\"text\":\"--¿Se marcha usted ya?--dijo cariñosamente Porfirio tendiendo la mano al joven con extrema amabilidad--. Estoy encantado de haberle conocido. En cuanto a su solicitud, esté usted tranquilo. Escriba en el sentido que le he dicho. O más vale que venga usted a verme uno de estos días... mañana, por ejemplo. Estaré aquí sin falta a las once. Lo arreglaremos todo y hablaremos un poco... Como usted es uno de los últimos que ha estado _allí_, podrá quizá decirnos algo--añadió en tono de campesino el juez de instrucción.\"},{\"heading\":false,\"text\":\"--¿Trata usted de interrogarme en toda regla?--preguntó secamente Raskolnikoff.\"},{\"heading\":false,\"text\":\"--De ninguna manera. No se trata de tal cosa en este momento. No me ha comprendido usted. Yo aprovecho todas las ocasiones, y... he hablado ya con todos los que tenían objetos empeñados en casa de la víctima... Muchos me han suministrado datos interesantes... y como usted es el último que estuvo... A propósito--exclamó con súbita alegría--, es una suerte que haya pensado... ya se me olvidaba... (al decir esto se volvió hacia Razumikin); el otro día me mareaba a propósito de ese Mikolai... pues mira, estoy cierto, convencido de su inocencia--prosiguió dirigiéndose a Raskolnikoff--. Pero, ¿qué hacer? Ha sido preciso también molestar a Mitka. He aquí lo que yo quería preguntar a usted: Al subir la escalera de la casa... permítame usted que se lo pregunte, ¿era entre siete y ocho cuando estuvo allí?\"},{\"heading\":false,\"text\":\"--Sí--respondió, y en seguida sintió haber dado esta respuesta, que no tenía necesidad de dar.\"},{\"heading\":false,\"text\":\"--Bueno. Al subir la escalera entre siete y ocho, ¿no vió usted en el segundo piso, en un cuarto cuya puerta estaba abierta, ¿no recuerda usted?, a dos obreros, o por lo menos uno de ellos, que estaba pintando la habitación? ¿No reparó usted? Eso es muy importante para los dos obreros.\"},{\"heading\":false,\"text\":\"--¿Pintores? No, no los vi...--respondió lentamente Raskolnikoff, como si tratase de recordar.\"},{\"heading\":false,\"text\":\"Durante un segundo, puso en tensión violenta todos los resortes de su espíritu para descubrir con claridad qué lazo ocultaba la pregunta hecha por el juez de instrucción.\"},{\"heading\":false,\"text\":\"--No, no los vi ni advertí tampoco si estaba abierto el cuarto--continuó muy contento de haber descubierto la trampa--; de lo que sí me acuerdo es que del cuarto piso el empleado que vivía enfrente de Alena Ivanovna estaba de mudanza. Lo recuerdo muy bien, porque tropecé con dos soldados que llevaban un sofá y tuve necesidad de arrimarme a la pared... Pero lo que es pintores, no recuerdo haberlos visto, ni tampoco de si alguna puerta estaba abierta. No, no lo vi...\"},{\"heading\":false,\"text\":\"--¡Pero qué estás diciendo!--gritó de repente Razumikin, que hasta entonces había estado como reflexionando--: Si fué el mismo día del asesinato cuando los pintores trabajaban en ese cuarto y Rodia estuvo dos días antes en la casa, ¿por qué le haces esa pregunta?\"},{\"heading\":false,\"text\":\"--¡Calle! pues es verdad, he confundido las fechas--exclamó Porfirio dándose una palmada en la frente--. ¡Qué diablos! este asunto me hace perder la cabeza--añadió a modo de excusa dirigiéndose a Raskolnikoff--. Es tan importante saber si alguno los ha visto en el cuarto entre siete y ocho, que sin pararme a reflexionar he creído obtener de usted esta aclaración... He confundido los días.\"},{\"heading\":false,\"text\":\"--Pues convendría fijarse más--gruñó Razumikin.\"},{\"heading\":false,\"text\":\"Estas últimas palabras fueron dichas en la antesala. Porfirio acompañó amablemente a sus visitantes hasta la puerta. Estos estaban tristes y sombríos cuando salieron de la casa y anduvieron muchos pasos sin cambiar una palabra. Raskolnikoff respiraba como hombre que acababa de atravesar por una prueba penosa.\"}]},{\"title\":\"tercera parte — capítulo VI\",\"blocks\":[{\"heading\":false,\"text\":\"--No lo creo. No puedo creerlo--repetía Razumikin, que hacía toda clase de esfuerzos para rechazar las conclusiones de Raskolnikoff.\"},{\"heading\":false,\"text\":\"Estaban ya cerca de la casa Bakalaieff en donde hacía largo tiempo los esperaban Pulkeria Alexandrovna y Dunia.\"},{\"heading\":false,\"text\":\"En el calor de la discusión, Razumikin se detenía a cada instante en medio de la calle; estaba muy agitado, porque era la primera vez que los dos jóvenes hablaban de _aquello_ sin valerse de palabras encubiertas.\"},{\"heading\":false,\"text\":\"--No lo creas si no quieres--respondió con fría e indiferente sonrisa Raskolnikoff--. Tú, según tu costumbre, nada has advertido; pero yo, yo he pesado cada palabra.\"},{\"heading\":false,\"text\":\"--Tú eres desconfiado; por eso descubres en todas partes segundas intenciones. ¡Hum!... Reconozco, en efecto, que el tono de Porfirio era bastante extraño y sobre todo el de ese bribón de Zametoff... Tienes razón, se advertía en él no sé qué... ¿pero cómo puede ser esto?\"},{\"heading\":false,\"text\":\"--Habrá cambiado de opinión desde ayer.\"},{\"heading\":false,\"text\":\"--No, te engañas. Si tuviesen tan estúpida idea, habrían, por el contrario, puesto mucho cuidado en disimularla; habrían ocultado su juego a fin de inspirarte una engañosa confianza, esperando el momento oportuno para descubrir sus baterías... En la hipótesis en que te colocas, su manera de proceder hoy sería tan torpe como desvergonzada...\"},{\"heading\":false,\"text\":\"--Si tuviesen pruebas, hablo de pruebas serias o de presunciones un tanto fundadas, cierto que sin duda se esforzarían en ocultar su juego con la esperanza de obtener nuevas ventajas sobre mí. (Además, habrían hecho un registro en mi domicilio.) Pero no tienen pruebas, ni una sola; todo se reduce a conjeturas gratuitas, a suposiciones que no se apoyan en nada real, y por eso proceden descaradamente. Quizá no haya en todo ello más que el despecho de Porfirio, que rabia por no tener pruebas. Puede también que tenga intenciones... Parece inteligente; acaso haya querido asustarme... Por lo demás, es repugnante ocuparse en estas cosas. Dejémoslas.\"},{\"heading\":false,\"text\":\"--¡Es odioso, odioso! Te comprendo. Pero... puesto que tratamos francamente de este asunto (y creo que hemos hecho bien), no vacilo en confesarte que desde hace mucho tiempo había advertido en ellos esa idea. Cierto que no se atrevían a formularla, que este pensamiento flotaba en su espíritu en el estado de duda vaga; pero demasiado es ya que hayan podido acogerla, aun bajo tal forma. ¿Y qué es lo que ha podido despertar en ellos tan abominables sospechas? ¡Si supieras cuánto furor me han hecho sentir! ¡Cómo! Un pobre estudiante agobiado por la miseria y la hipocondría, en vísperas de enfermedad grave que existía ya en él; un joven desconfiado, lleno de amor propio, que tiene la conciencia de su valer, encerrado desde hace seis meses en su habitación sin ver a nadie; que se presenta vestido de harapos, calzado con botas sin suela, ante miserables polizontes, cuya insolencia soporta, a quien se reclama a quema ropa el pago de una letra de cambio protestada, en una sala llena de gente y en donde hace un calor de treinta grados Réamur y cuyo aire está impregnado de olor insoportable de la pintura reciente... porque el desgraciado se desmaya al oír hablar de una persona en cuya casa ha estado la víspera y porque además tiene el estómago vacío... ¿hay motivos para sospechar de él? En tales condiciones, ¿cómo no había de desmayarse? ¡Y pensar que tales suposiciones caen sobre este desmayo! Tal es el punto de partida de la acusación. ¡Váyanse al diablo! Comprendo que todo esto te será mortificante; pero yo, en tu lugar, Rodia, me reiría de ellos en sus barbas, o mejor aún, les lanzaría al rostro mi desprecio en forma de salivazos; de este modo acabaría yo con ellos. ¡Valor! ¡Escúpeles! ¡Es vergonzoso!\"},{\"heading\":false,\"text\":\"«Se ha despachado, convencido de lo que dice»--pensó Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¡Escupirles al rostro!... Es fácil decirlo. ¡Pero mañana otro interrogatorio!--respondió tristemente--; será menester que yo me rebaje hasta dar explicaciones. Ya consentí ayer en hablar con Zametoff en el _traktir_.\"},{\"heading\":false,\"text\":\"--¡Que se vayan al infierno! Iré a casa de Porfirio. Es mi pariente, y de esta circunstancia me aprovecharé para meterle los dedos en la boca; tendrá que hacerme su confesión completa. En cuanto a Zametoff... ¡Espera!--gritó Razumikin, asiendo de repente a su amigo por el brazo--¡espera! Divagabas hace poco. Después de reflexionar, estoy convencido de que divagabas. ¿En dónde ves la astucia? ¿Dices que la pregunta relativa a los obreros ocultaba un lazo? Razona un poco. Si tú hubieras hecho _eso_, ¿habrías sido tan estúpido de decir que habías visto a los pintores trabajando en el cuarto del segundo piso? Por el contrario, aunque los hubieses visto, lo habrías negado. ¿Quién a sabiendas hace confesiones que pueden comprometerle?\"},{\"heading\":false,\"text\":\"--Si yo hubiese hecho _tal cosa_, no habría dejado de decir que había visto a los obreros--repuso Raskolnikoff, que parecía sostener aquella conversación con violento disgusto.\"},{\"heading\":false,\"text\":\"--¿Para qué decir cosas perjudiciales a los propios intereses?\"},{\"heading\":false,\"text\":\"--Porque solamente los _mujiks_ y las personas más limitadas lo niegan todo sistemáticamente. Un acusado, por poco inteligente que sea, confiesa en lo posible todos los hechos materiales cuya vanidad trataría en vano de destruir; se contrae a explicarlos de otra manera, modifica su significación y los presenta bajo un nuevo aspecto. Según todas las probabilidades, Porfirio contaba con que yo respondería sí; creía que, para dar mayor verosimilitud a mis confesiones, declararía haber visto a los obreros, aunque explicando en seguida el hecho en un sentido favorable a mi causa.\"},{\"heading\":false,\"text\":\"--Pero él hubiera respondido en seguida que la antevíspera del crimen los obreros no estaban allí, y que, por consiguiente, tú habías estado en la casa el día mismo del asesinato entre seis y siete.\"},{\"heading\":false,\"text\":\"--Porfirio contaba que yo no tendría tiempo de reflexionar, y con que obligado a responder de la manera más verosímil habría olvidado esa circunstancia: la imposibilidad de la presencia de los obreros en la casa dos días antes del crimen.\"},{\"heading\":false,\"text\":\"--¿Pero, cómo olvidarlo?\"},{\"heading\":false,\"text\":\"--Nada más fácil. Estos pormenores son el escollo de los maliciosos; respondiendo a ellos es como se da un traspiés en los interrogatorios. Cuanto más agudo es un hombre, menos sospecha de las preguntas insignificantes. Porfirio lo sabe. Es mucho más listo de lo que tú supones.\"},{\"heading\":false,\"text\":\"--Eso quiere decir que es un pillo.\"},{\"heading\":false,\"text\":\"Raskolnikoff no pudo menos de reírse; pero en el mismo instante se asombró de haber dado la misma explicación con verdadero placer, él, que hasta entonces había seguido la conversación a regañadientes y porque no podía menos.\"},{\"heading\":false,\"text\":\"«¿Habré tomado yo gusto a estas cuestiones?»--pensaba.\"},{\"heading\":false,\"text\":\"Pero casi al mismo tiempo sintióse acometido de súbita inquietud, que bien pronto llegó a ser intolerable.\"},{\"heading\":false,\"text\":\"Los dos jóvenes encontrábanse ya a la puerta de la casa Bakalaieff.\"},{\"heading\":false,\"text\":\"--Entra solo--dijo bruscamente Raskolnikoff--; vuelvo en seguida.\"},{\"heading\":false,\"text\":\"--¿A dónde vas? ¿Hemos llegado ya?\"},{\"heading\":false,\"text\":\"--Tengo una cosa que hacer... Estaré aquí dentro de media hora... Tú les dirás...\"},{\"heading\":false,\"text\":\"--Bueno, te acompaño.\"},{\"heading\":false,\"text\":\"--¿Pero has jurado también tú perseguirme hasta la muerte?\"},{\"heading\":false,\"text\":\"Lanzó esta exclamación con tal acento de furor y con tono tan desesperado, que Razumikin no se atrevió a insistir. Permaneció un rato en el umbral siguiendo con mirada sombría a Raskolnikoff, que caminaba aceleradamente en dirección a su domicilio. Por último, después de haber rechinado los dientes apretó los puños y prometiéndose a sí mismo estrujar aquel mismo día a Porfirio como un limón, subió a casa de las señoras para tranquilizar a Pulkeria Alexandrovna, inquieta ya por tan largo retraso.\"},{\"heading\":false,\"text\":\"Cuando Raskolnikoff llegó a su casa tenía las sienes húmedas de sudor, y respiraba penosamente. Subió los escalones de cuatro en cuatro, entró en su habitación, que había quedado abierta y la cerró con el pestillo. En seguida, todo aterrorizado, corrió al escondite, metió la mano bajo la tapicería y exploró el agujero en todos sentidos. No habiendo encontrado nada después de registrarlo cuidadosamente, se levantó y lanzó un suspiro de satisfacción. Poco antes, en el momento en que se aproximaba a la casa Bakalaieff, le asaltó la idea de que alguno de los objetos robados habría podido deslizarse en las hendiduras de la pared: si llegaban a encontrar allí una cadena de reloj, un gemelo o algunos de los papeles que envolvían las alhajas y que tenían anotaciones escritas por mano de la vieja, ¡qué prueba de convicción entonces en contra suya!\"},{\"heading\":false,\"text\":\"Y quedó sumido en un vago sueño, mientras aparecía en sus labios una sonrisa extraña y casi estúpida. Al cabo tomó su gorra y salió sin ruido de la casa. Bajó pensativo la escalera y llegó a la puerta de la calle.\"},{\"heading\":false,\"text\":\"--Ahí lo tiene usted--gritó una voz.\"},{\"heading\":false,\"text\":\"El joven levantó la cabeza. El portero, en pie en el umbral de su habitación, señalaba a Raskolnikoff, mostrándoselo a un hombre de baja estatura y de aspecto burgués. Este individuo iba vestido con una especie de _khalat_ y un chaleco; de lejos hubiera podido tomársele por un campesino. Llevaba una gorra muy grasienta y andaba muy encorvado. A juzgar por las arrugas de su marchito rostro, debía de tener más de cincuenta años. Sus ojillos expresaban dureza y disgusto.\"},{\"heading\":false,\"text\":\"--¿Qué es eso?--preguntó acercándose al _dvornik_.\"},{\"heading\":false,\"text\":\"El burgués le miró de soslayo, lo examinó atentamente sin decir una palabra, volvió la espalda y se alejó de la casa.\"},{\"heading\":false,\"text\":\"--Pero, ¿qué significa esto?--gritó Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Es un hombre que ha venido aquí a ver si vivía un estudiante. Ha dicho el nombre de usted y ha preguntado qué cuarto ocupaba usted. En esto ha bajado usted y le he dicho «ése es» y se ha ido.\"},{\"heading\":false,\"text\":\"El _dvornik_ estaba también un poco asombrado; pero no con exceso. Después de haber reflexionado un poco, entró en su cochitril.\"},{\"heading\":false,\"text\":\"Raskolnikoff se lanzó tras de las huellas del burgués. Apenas salió de la casa tomó el otro lado de la calle. El desconocido andaba con paso lento y regular, los ojos bajos y aire pensativo. El joven hubiera podido alcanzarle en seguida; pero durante algún tiempo se limitó a ir al mismo paso que él; al fin se colocó a su lado y le miró oblicuamente el rostro. El burgués lo advirtió en seguida, le dirigió una rápida ojeada y bajó los ojos; durante un minuto caminaron juntos de esta suerte sin decir una palabra.\"},{\"heading\":false,\"text\":\"--Usted ha preguntado por mí al _dvornik_...--comenzó a decir Raskolnikoff sin levantar la voz.\"},{\"heading\":false,\"text\":\"El burgués no respondió, ni miró siquiera al que le hablaba. Hubo un nuevo silencio.\"},{\"heading\":false,\"text\":\"--Usted ha venido a preguntar por mí... y ahora se calla. ¿Qué quiere decir esto?--añadió Raskolnikoff con voz entrecortada: parecía que las palabras salían con trabajo de sus labios.\"},{\"heading\":false,\"text\":\"Esta vez el burgués levantó los ojos y miró al joven con expresión siniestra.\"},{\"heading\":false,\"text\":\"--¡Asesino!--dijo bruscamente en voz baja, pero clara y distinta.\"},{\"heading\":false,\"text\":\"Raskolnikoff, que marchaba a su lado, sintió que sus piernas se doblaban y que un frío estremecimiento le corría por la espalda. Durante un segundo su corazón desfalleció; después se puso a latir con extraordinaria violencia.\"},{\"heading\":false,\"text\":\"Los dos hombres anduvieron cosa de un centenar de pasos, sin proferir una sola palabra. El burgués no miraba a su compañero.\"},{\"heading\":false,\"text\":\"--¿Pero qué es lo que usted dice?... ¿quién es un asesino?--balbuceó Raskolnikoff con voz casi ininteligible.\"},{\"heading\":false,\"text\":\"--Tú eres el asesino--replicó el otro recalcando sus palabras con más precisión y energía que antes, al mismo tiempo que en sus labios se dibujaba la sonrisa del odio triunfante y miraba fijamente el pálido rostro de Raskolnikoff, cuyos ojos se habían puesto vidriosos.\"},{\"heading\":false,\"text\":\"Se aproximaban en aquel momento a una encrucijada. El burgués tomó por una calle a la derecha y continuó su camino sin volver la vista atrás.\"},{\"heading\":false,\"text\":\"Raskolnikoff le dejó alejarse, pero le siguió largo tiempo con la mirada. Después de haber andado cincuenta pasos el desconocido se volvió para observar al joven que continuaba como clavado en el mismo sitio. La distancia no le permitía ver bien; sin embargo, Raskolnikoff creyó advertir que aquel individuo le miraba todavía sonriendo con expresión de odio frío y triunfante.\"},{\"heading\":false,\"text\":\"Helado de espanto, con las piernas temblorosas, volvió como pudo a su casa y subió a su cuarto. Cuando hubo dejado la gorra sobre la mesa, permaneció de pie inmóvil durante diez minutos. Luego, extenuado, se echó en el sofá y se extendió lánguidamente lanzando un débil suspiro. Al cabo de media hora sonaron pasos apresurados, y al mismo tiempo Raskolnikoff oyó la voz de Razumikin; el joven cerró los ojos y se hizo el dormido. Razumikin abrió la puerta y durante algunos minutos permaneció irresoluto en el umbral. En seguida entró suavemente en la sala y se aproximó con precaución al sofá.\"},{\"heading\":false,\"text\":\"--¡No le despiertes! ¡déjale dormir tranquilo! Comerá más tarde--dijo en voz baja Anastasia.\"},{\"heading\":false,\"text\":\"--Tienes razón--respondió Razumikin.\"},{\"heading\":false,\"text\":\"Salieron andando de puntillas y empujaron la puerta. Pasó otra media hora, al cabo de la cual Raskolnikoff abrió los ojos, se tendió con brusco movimiento boca arriba y colocó las manos debajo de la cabeza.\"},{\"heading\":false,\"text\":\"--¿Quién es, quién es ese hombre salido de debajo de la tierra? ¿Dónde estaba y qué ha visto? Lo ha visto todo, es indudable. ¿Dónde se encontraba y desde qué sitio pudo ver aquella escena? ¿Cómo se explica que no haya dado más pronto señales de vida? ¿Cómo ha podido ver...? ¿Es esto posible?--continuó Raskolnikoff, presa de un frío glacial--. Y el encontrar Mikolai el estuche debajo de la puerta, ¿era también cosa que no podía suponerse?\"},{\"heading\":false,\"text\":\"Comprendía que las fuerzas le abandonaban y experimentaba un violento disgusto de sí mismo.\"},{\"heading\":false,\"text\":\"--¡Yo debía suponer esto!--pensó con amarga sonrisa--. ¿Cómo me he atrevido, conociéndome, previendo lo que ocurriría, cómo me he atrevido a empuñar un hacha y a verter sangre? Estaba obligado a saber de antemano lo que iba a acontecerme... ¡y lo sabía!...--murmuró desesperado.\"},{\"heading\":false,\"text\":\"A veces se detenía ante este pensamiento.\"},{\"heading\":false,\"text\":\"--No, los hombres extraordinarios no están hechos como yo: el verdadero _amo_ a quien le es permitido todo, cañonea a Tolón, mata en París, olvida un ejército en Egipto, pierde medio millón de hombres en la batalla de Moscou y sale de una situación embarazosa en Vilna merced a un retruécano; después de su muerte, se le erigen estatuas en prueba de que todo le es permitido. No, esas personas no están hechas de carne sino de bronce.\"},{\"heading\":false,\"text\":\"Una idea que se le ocurrió de repente le hizo casi reír.\"},{\"heading\":false,\"text\":\"--¡Napoleón, las Pirámides, Waterloo y una vieja criada de un registrador de colegio, una innoble usurera que tiene un cofre forrado de piel encarnada bajo la cama!... ¿Cómo digeriría Porfirio Petrovitch semejante comparación?... La estética se opone a ello: «¿Por ventura Napoleón se hubiera metido debajo de la cama de una vieja?», preguntaría sin duda. ¡Vaya una tontería!\"},{\"heading\":false,\"text\":\"De tiempo en tiempo sentía que casi deliraba; hallábase en estado de exaltación febril. Después continuaba, interrumpiéndose a cada momento:\"},{\"heading\":false,\"text\":\"--La vieja no significa nada--se decía en un acceso--. Supongamos que su muerte sea un error; no se trata de ella. La vieja no ha sido más que un accidente... yo quería saltar el obstáculo lo más pronto posible... no es una criatura humana lo que yo he matado, es un principio. ¡He matado el principio, pero no he sabido pasar por encima! Me he quedado del lado de acá; no he sabido más que matar. Y tampoco, por lo visto, me ha resultado bien esto... ¡un principio! ¿Por qué hace poco ese estúpido de Razumikin atacaba a los socialistas? Son laboriosos, hombres de negocios, «se ocupan en el bienestar de la humanidad...» No, yo no tengo más que una vida, yo no puedo esperar «la felicidad universal». Yo quiero vivir también; de otro modo, mejor es no existir. Yo no quiero pasar al lado de una madre hambrienta apretando mi rublo en el bolsillo a pretexto de que un día todo el mundo será feliz. «Yo llevo, se dice, mi piedra al edificio universal, y esto basta para poner mi corazón en paz.» ¡Ah, ah! ¿por qué os habéis olvidado de mí? Puesto que yo no tengo más que un período de tiempo para vivir, quiero en seguida mi parte de felicidad... yo soy un gusanillo estético nada más, nada más--añadió riendo de repente como un loco, y se aferró a esta idea, experimentando un agrio placer al sondarla en todos sentidos y a darle vueltas por todos los lados--. Sí, en efecto, yo soy un gusanillo, por el hecho solo de que medito ahora sobre la cuestión de averiguar lo que soy. Además, porque durante un mes he estado fastidiando a la divina Providencia tomándola sin cesar por testigo de que yo me decidía a esta empresa, no para procurarme satisfacciones materiales, sino en vista de un objeto grandioso. ¡Ah! ¡Ah! en tercer lugar, porque en la ejecución he querido proceder con toda justicia; entre todos los gusanos he escogido el más dañino, y al matarle contaba con tomar nada más que lo preciso para asegurar mis comienzos en la vida, ni más ni menos (el resto hubiera ido al monasterio, al cual había legado la vieja su fortuna). ¡Ah! ¡Ah!... Soy definitivamente un gusano--añadió rechinando los dientes--, porque soy más vil y más innoble que el gusano que he matado, y porque _presentía_ que después de haberlo matado, diría lo que estoy diciendo. ¿Hay algo comparable con semejante terror? ¡Oh necedad, oh necedad!... ¡Comprendo al Profeta a caballo, con la cimitarra en la mano! «¡Alá lo quiere! ¡obedece, temblorosa criatura!» ¡Tiene razón, tiene razón el Profeta cuando coloca una tropa al través de la calle y hiere indistintamente al justo y al culpable sin dignarse siquiera dar explicaciones! ¡Obedece, temblorosa criatura, y _guárdate de querer_, porque eso no es cosa tuya!... ¡Oh, jamás! ¡jamás perdonaría yo a la vieja!\"},{\"heading\":false,\"text\":\"Tenía los cabellos empapados en sudor, sus labios secos se agitaban y su mirada inmóvil no se apartaba del techo.\"},{\"heading\":false,\"text\":\"--¡Cuánto amaba yo a mi madre y a mi hermana! ¿De qué procede que ahora las deteste? ¡Sí, las detesto, las odio físicamente, no puedo soportarlas cerca de mí! Hace poco me he acercado a mi madre y la he besado, bien me acuerdo; ¡abrazarla pensando que si ella supiese...! ¡Oh, cuánto odio ahora a la vieja! ¡Creo que si volviera a la vida la mataría otra vez!... ¡Pobre Isabel!, ¿por qué la llevó allí la casualidad? Es extraño, sin embargo, que piense en ella, como si no la hubiese matado... ¡Isabel! ¡Sonia! ¡Pobres criaturas de ojos azules!... ¿Por qué no lloran? ¿Por qué no gimen?... Víctimas resignadas, todo lo aceptan en silencio... ¡Sonia, Sonia, dulce Sonia!\"},{\"heading\":false,\"text\":\"Perdió la conciencia de sí mismo y con gran sorpresa advirtió que estaba en la calle. Era ya entrada la noche. Aumentaban las tinieblas, la luna llena brillaba con resplandor cada vez más vivo, pero la atmósfera era sofocante. Había mucha gente en las calles; los obreros y los hombres ocupados volvían apresuradamente a sus casas; los otros se paseaban. Flotaba en la atmósfera olor de cal, de polvo, de agua cenagosa. Raskolnikoff andaba disgustado y preocupado. Recordaba perfectamente que había salido de su casa con algún objeto, que tenía que hacer una cosa urgente; ¿pero cual? La había olvidado. Bruscamente advirtió que desde la acera de enfrente un hombre le hacía señas con la mano; cruzó la calle para juntarse con él, pero, de repente, este hombre giró sobre sus talones, y, como si tal cosa, continuó su marcha con la cabeza baja, sin volverse, sin parecer que llamaba a Raskolnikoff. «¿Me habré engañado?»--pensó este último, y se puso a seguirle. Antes de haber andado diez pasos, lo reconoció de improviso y se aterró: era el burgués de antes, encorvado, con el mismo traje. Raskolnikoff, cuyo corazón latía con fuerza, marchaba a alguna distancia; entraron en un _pereulok_. El hombre no se volvía. «¿Sabe que le sigo?»--se preguntaba Raskolnikoff. El burgués franqueó el umbral de una gran casa. Raskolnikoff avanzó vivamente hacia la puerta y se puso a mirar, pensando que quizá aquel misterioso personaje se volvería para llamarle. En efecto, cuando el burgués estuvo en el zaguán, se volvió bruscamente y pareció llamar con un gesto al joven. Este se apresuró a entrar en la casa; pero cuando estuvo en el patio no vió al burgués. Presumiendo que aquel hombre habría tomado por la primera escalera, Raskolnikoff se puso a subir detrás de él. En efecto, dos pisos más arriba se oían resonar los pasos lentos y regulares en los peldaños. Cosa extraña; le parecía reconocer aquella escalera. He aquí la ventana del primer piso. La luz de la luna misteriosa y triste, se filtraba al través del vidrio; he aquí el segundo piso. «¡Bah! Este es el cuarto en que trabajaban los pintores. ¿Cómo no había reconocido en seguida la casa?» Los pasos del hombre que le precedía cesaron de oírse. «Se ha detenido de seguro u ocultado en alguna parte. He aquí el tercer piso: ¿subiré más arriba? ¡Qué silencio! ¡Este silencio es terrible!» Sin embargo, siguió subiendo la escalera. Le daba miedo el rumor de sus propios pasos. «¡Dios mío! ¡Qué obscuro está! El burgués se ha ocultado seguramente aquí en un rincón. ¡Ah!» El cuarto que daba al rellano estaba abierto de par en par. Raskolnikoff reflexionó un instante; después entró. Halló la antesala completamente vacía y muy obscura. El joven pasó a la sala marchando de puntillas. La luz de la luna daba de lleno sobre esta sala y la iluminaba por completo; el mobiliario no había cambiado. Raskolnikoff encontró en sus antiguos puestos las sillas, el espejo, el sofá amarillo y los cuadros. Por la ventana se veía la luna, cuya enorme faz redonda tenía un color cobrizo. Largo tiempo esperó en medio de un profundo silencio. De repente, oyó un ruido seco, como el de una tabla que se rompe. Después volvió a quedar todo en silencio. Una mosca que se había despertado fué volando a chocar contra el vidrio y se puso a zumbar lastimeramente. En el mismo instante, en un rincón, entre el armarito y la ventana creyó notar que había un manto de mujer colgado en la pared. «¿Por qué está este manto aquí?--pensó--; antes no estaba.» Se aproximó cautelosamente sospechando que tras de aquel vestido debía de haber alguien oculto. Apartando con precaución el manto, vió que había allí una silla, y en esta silla, en el rincón, estaba la vieja. Estaba doblada y de tal modo inclinada tenía la cabeza, que el joven no pudo ver la cara; pero comprendió que era Alena Ivanovna. «¡Tiene miedo!»--se dijo Raskolnikoff. Sacó suavemente el hacha del nudo corredizo y le dió dos golpes en la coronilla; pero, cosa extraña, la vieja no vaciló bajo los golpes: se hubiera dicho que era de madera. Estupefacto el joven, se inclinó hacia ella para examinarla, pero la vieja bajó aún más la cabeza. Entonces él se inclinó hasta el suelo, la miró de abajo arriba y al ver su rostro se quedó espantado: la vieja se reía, sí, reía, con risa silenciosa, haciendo grandes esfuerzos para que no se la oyese. De repente le pareció a Raskolnikoff que la puerta de la alcoba estaba abierta y que allí también se reían y hablaban en voz baja. Se puso entonces rabioso y comenzó a descargar hachazos con toda su fuerza, sobre la cabeza de la vieja; pero a cada hachazo las risas y los cuchicheos de la alcoba se oían más distintamente; en cuanto a la vieja, se retorcía de risa. Quiso huir, mas toda la antesala se había llenado de gente; la puerta que daba sobre el descansillo estaba abierta; en éste y en la escalera había, desde arriba hasta abajo, multitud de individuos. Todos miraban, pero sin pronunciar palabra. Tenía encogido el corazón y parecía que se le habían clavado los pies en el suelo; quiso gritar y se despertó.\"},{\"heading\":false,\"text\":\"Respiró con fuerza; pero creía que aun estaba soñando cuando vió en pie en el umbral de su puerta, abierta del todo, a un hombre a quien no conocía y que le miraba con atención.\"},{\"heading\":false,\"text\":\"Raskolnikoff no había acabado de abrir los ojos cuando los volvió a cerrar en seguida. Tendido como estaba boca arriba no se movió. «Esta es la continuación de mi sueño»--pensó mientras abría casi imperceptiblemente los párpados para fijar una tímida mirada en el desconocido. Este, siempre en el mismo puesto, no cesaba de observarle. Después entró, cerró la puerta detrás de sí, se aproximó a la mesa, y después de haber esperado un minuto, se sentó en una silla cerca del sofá. Durante todo este tiempo no había cesado de mirar a Raskolnikoff. Luego puso el sombrero en el suelo, a su lado, y apoyó ambas manos en el puño del bastón y la barba en las manos, como el que se prepara a una larga espera. Por lo que Raskolnikoff había podido juzgar de él en una mirada furtiva, aquel hombre no era joven; parecía robusto y tenía la barba espesa, de un color rubio casi blanco.\"},{\"heading\":false,\"text\":\"Pasaron así diez minutos. Era aún de día, pero tarde; en la habitación reinaba el más profundo silencio; en la escalera no sonaba tampoco ruido alguno, no se oía más que el ruido de un moscardón que al volar había chocado contra la ventana. Al fin, esta situación se hizo insoportable; Raskolnikoff no pudo más y se sentó de pronto en el sofá.\"},{\"heading\":false,\"text\":\"--Vamos, hable usted; ¿qué es lo que quiere?\"},{\"heading\":false,\"text\":\"--Bien sabía que su sueño no era más que una ficción--respondió el desconocido con sonrisa tranquila--. Permítame usted que me presente: Arcadio Ivanovitch Svidrigailoff...\"},{\"heading\":false,\"text\":\"CUARTA PARTE\"}]},{\"title\":\"cuarta parte — capítulo I\",\"blocks\":[{\"heading\":false,\"text\":\"--¿Estoy bien despierto?--pensó de nuevo Raskolnikoff, mirando desconfiadamente al inesperado visitante--. ¿Svidrigailoff? ¡No puede ser de ningún modo!--dijo al cabo en voz alta, no atreviéndose a dar crédito a sus oídos.\"},{\"heading\":false,\"text\":\"Esta exclamación pareció no sorprender a su extraño visitante.\"},{\"heading\":false,\"text\":\"--He venido a casa de usted por dos razones: primera, por conocerle personalmente, porque desde hace mucho tiempo he oído hablar a menudo y en términos muy halagadores de usted; y después, porque espero que no me negará su concurso en una empresa que tiene relación directa con los intereses de su hermana, Advocia Romanovna. Sólo, sin recomendación, me costaría mucho trabajo ser recibido por ella, puesto que está prevenida contra mí; pero, presentado por usted, la cosa varía.\"},{\"heading\":false,\"text\":\"--Se engaña usted al contar conmigo--replicó Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¿Fué ayer cuando llegaron esas señoras? Permita usted que se lo pregunte.\"},{\"heading\":false,\"text\":\"Raskolnikoff no contestó.\"},{\"heading\":false,\"text\":\"--Sí, fué ayer, lo sé positivamente. Yo llegué anteayer. Escuche usted, Rodión Romanovitch, lo que tengo que decirle a este propósito; creo superfluo justificarme; pero permítame que le pregunte: ¿Qué hay, en rigor, en todo esto de particularmente culpable por mi parte, si se aprecian las cosas con serenidad y sin prejuicios?\"},{\"heading\":false,\"text\":\"Raskolnikoff continuaba examinándole sin despegar los labios.\"},{\"heading\":false,\"text\":\"--Me dirá usted que he perseguido en mi casa a una joven sin defensa y que «la he insultado con proposiciones deshonrosas». (Quiero adelantarme a la acusación.) Pero considere usted que soy hombre, _el nihil humanum_... en una palabra, que soy susceptible de ceder a un arrebato, de enamorarme, cosa independiente de la voluntad. De esta manera todo se explicará del modo más natural del mundo. La cuestión estriba en esto: ¿Soy un monstruo o una víctima? Ciertamente soy una víctima. Cuando yo proponía a mi adorada que huyera conmigo a América o a Suiza, abrigaba respecto a esa persona los más respetuosos sentimientos y pensaba en asegurar nuestra común felicidad... La razón es la esclava de la pasión; yo he sido el principalmente perjudicado.\"},{\"heading\":false,\"text\":\"--No se trata, en modo alguno, de eso--replicó Raskolnikoff con sequedad--. Tenga usted razón o no, me es usted completamente odioso. No quiero conocer a usted, y le echo de mi casa. ¡Salga de aquí!...\"},{\"heading\":false,\"text\":\"Svidrigailoff soltó una carcajada.\"},{\"heading\":false,\"text\":\"--No hay medio de engañar a usted--dijo con franca alegría--; quería echármelas de ingenioso, pero con usted no sirve.\"},{\"heading\":false,\"text\":\"--¿Todavía quiere usted embromarme?\"},{\"heading\":false,\"text\":\"--Bueno, ¿y qué? ¿Qué le sorprende?--repitió su interlocutor, riéndose con toda su alma--; en buena guerra, como dicen los franceses, la malicia no tiene nada de ilícita... Pero usted no me ha dejado acabar. Volviendo a lo que hace un momento decía, nada desagradable ha pasado, sino el incidente del jardín. Marfa Petrovna...\"},{\"heading\":false,\"text\":\"--Se dice también que usted ha matado a su esposa--dijo, interrumpiéndole brutalmente Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿Ya le han hablado a usted de eso? Realmente nada tiene de asombroso... Pues bien, respecto a la pregunta que usted me hace, no sé, en verdad, qué decirle, puesto que tengo la conciencia muy tranquila. No vaya usted a creer que temo las consecuencias; todas las formalidades de costumbre se han cumplido minuciosamente. El informe de los médicos ha demostrado que mi esposa murió de un ataque de apoplejía, producido por un baño tomado inmediatamente después de una abundante comida, rociada con una botella de vino; es lo único que ha podido descubrirse... Por esa parte nada me inquieta. Muchas veces, sobre todo cuando venía en el tren, camino de San Petersburgo, me he preguntado si habría yo contribuído, moralmente, por supuesto, a esa... desgracia, sea causando la desesperación de mi mujer, sea de alguna otra manera semejante; pero he acabado por convencerme de que no ha habido ni sombra de eso.\"},{\"heading\":false,\"text\":\"Raskolnikoff se echó a reír.\"},{\"heading\":false,\"text\":\"--¿De modo que esto le divierte...?\"},{\"heading\":false,\"text\":\"--Y usted, ¿de qué se ríe? Solamente le di dos latigazos sin importancia que no le dejaron señal alguna... No me tenga usted, se lo ruego, por un hombre cínico; sé muy bien que eso de los latigazos es una cosa innoble, etc.; pero tampoco ignoro que mis accesos de brutalidad no desagradaban del todo a Marfa Petrovna. Cuando ocurrió lo de su hermana de usted, mi mujer se fué con el cuento por toda la ciudad y fastidió a cuantos la conocían por la famosa carta (ya sabrá usted, sin duda, que se la leía a todo el mundo); de modo que los dos latigazos fueron propinados muy oportunamente.\"},{\"heading\":false,\"text\":\"A Raskolnikoff le dieron intenciones de levantarse, y salir, a fin de cortar por lo sano la conversación; pero cierta curiosidad y una especie de cálculo le decidieron a tener un poco de paciencia.\"},{\"heading\":false,\"text\":\"--¿Le gusta a usted manejar el látigo?--dijo con aire distraído.\"},{\"heading\":false,\"text\":\"--No mucho--respondió tranquilamente Svidrigailoff--. Casi nunca habíamos reñido mi mujer y yo. Vivíamos en muy buena armonía, y ella estaba siempre contenta de mí. Durante siete años de vida conyugal, no me serví del látigo más que dos veces (prescindiendo de otra ocasión que por lo demás fué un caso bastante ambiguo); la primera, ocurrió dos meses después de nuestro matrimonio, en el momento en que acabábamos de instalarnos en el campo; la segunda, y última, fué en las circunstancias que recordaba hace un momento. Usted me consideraba ya como un monstruo, como un retrógrado, como un partidario de la servidumbre. ¡Ja, ja, ja!\"},{\"heading\":false,\"text\":\"Raskolnikoff estaba convencido de que aquel hombre tenía un plan muy madurado y que todo aquello era fina astucia.\"},{\"heading\":false,\"text\":\"--Debe usted haber pasado muchos días sin hablar con nadie--dijo el joven.\"},{\"heading\":false,\"text\":\"--Algo de verdad hay en esa suposición; pero usted se asombra, ¿no es cierto, de hallarme de tan buen humor?\"},{\"heading\":false,\"text\":\"--Y hasta me parece demasiado bueno...\"},{\"heading\":false,\"text\":\"--¿Porque no me he formalizado con la grosería de las preguntas de usted? ¿Y qué? ¿Por qué había de ofenderme? Como usted me ha preguntado le he respondido--contestó Svidrigailoff con una singular expresión de franqueza--. En verdad, yo no me intereso, digámoslo así, por cosa alguna. Ahora, sobre todo, nada me preocupa. Por lo demás, libre es usted de pensar que abrigo propósitos interesados para captarme sus simpatías, tanto más cuanto que tengo ciertas miras respecto a su hermana, como ya se lo he declarado. Pero, francamente se lo digo, ¡me fastidio mucho! Sobre todo desde hace tres días, que tengo intenciones de venir a ver a usted... No se incomode, Rodión Romanovitch, me parecía usted muy raro. En efecto, advierto en usted algo extraordinario y ahora principalmente, es decir, no en este mismo momento, sino desde hace algún tiempo. Vamos, me callo, no frunza usted el ceño... No soy tan oso como usted cree...\"},{\"heading\":false,\"text\":\"--No lo tengo por oso--dijo Raskolnikoff--; más aún, me parece que es usted un hombre de muy buena sociedad o, por lo menos, que sabe usted ser, en llegando la ocasión, _comme il faut_.\"},{\"heading\":false,\"text\":\"--Me tiene sin cuidado la opinión de los demás--contestó Svidrigailoff con tono seco y ligeramente desdeñoso--; y además, ¿por qué no adoptar las maneras de un hombre mal educado, especialmente en un país en que son tan cómodas y, sobre todo, cuando se tiene para ello propensión natural?--añadió riendo.\"},{\"heading\":false,\"text\":\"Raskolnikoff le miraba sombríamente.\"},{\"heading\":false,\"text\":\"--He oído decir que conoce usted a mucha gente--le dijo--. No es usted lo que se llama «un hombre sin relaciones». Siendo esto así, ¿qué viene usted a hacer a mi casa, si no tiene objeto determinado?\"},{\"heading\":false,\"text\":\"--Es verdad, como usted dice, que tengo aquí muchos conocimientos--repuso el visitante sin responder a la principal pregunta que se le había dirigido--; en los tres días que llevo de corretear por la capital, me he tropezado con muchos conocidos y creo que también ellos han reparado en mí. Visto de una manera conveniente, y se me clasifica entre los que nadan en la abundancia: la abolición de la servidumbre no nos ha arruinado... Sin embargo, no trato de reanudar mis antiguas relaciones, porque me eran ya insoportables. Estoy aquí desde anteayer y no he querido ver a nadie. No; es menester que la gente de los círculos y los parroquianos del restaurant Dugsand se priven de mi presencia. Por otra parte, ¿qué placer hay en hacer trampas en el juego?\"},{\"heading\":false,\"text\":\"--¡Ah! ¿Hace usted trampas en el juego?\"},{\"heading\":false,\"text\":\"--¡Claro está! Hace ocho años formábamos una verdadera sociedad (hombres _comme il faut_, capitalistas y poetas), que pasábamos el tiempo jugando a las cartas y haciendo todas las trampas que podíamos. ¿Ha observado usted que en Rusia las personas de buen tono son todas tramposas? Pero en aquella época, un griego de Niejin, a quien debía ya 70.000 rublos, me hizo encarcelar por deudas. Entonces se presentó Marfa Petrovna y mediante 30.000 rublos que ella pagó a mi acreedor, obtuvo mi libertad. Entonces nos unimos en legítimo matrimonio, y mi esposa se apresuró a llevarme a sus posesiones para ocultarme allí como un tesoro. Tenía cinco años más que yo y me quería mucho. Durante siete años no me he movido de la aldea. Advierto a usted que toda su vida mi señora guardó, a título de precaución contra mí, la letra de cambio que me había hecho firmar el griego y que ella rescató valiéndose de un testaferro; si hubiera tratado de sacudir el yugo, me habría metido bonitamente en la cárcel. A pesar de todo su afecto hacia mí, no hubiera vacilado un momento; en las mujeres se observan contradicciones como ésta.\"},{\"heading\":false,\"text\":\"--Si no le hubiera tenido así agarrado, ¿la habría dejado usted plantada?\"},{\"heading\":false,\"text\":\"--No sé qué responderle. Ese documento no me inquietaba mucho. No deseaba ir a ninguna parte. Dos veces la misma Marfa Petrovna, viendo que me aburría, me animó a hacer un viaje por el extranjero. Pero yo había visitado ya a Europa y me había aburrido horriblemente. Allí, sin duda, solicitan la admiración los grandes espectáculos de la Naturaleza; pero mientras contemplamos un amanecer, el mar, la bahía de Nápoles... sentimos tristeza y hasta tedio sin saber por qué. ¿No es mejor estar entre nosotros? Aquí, por lo menos, se acusa a los demás de todo y se justifica uno a sus propios ojos. Ahora haría de buena gana una expedición al Polo ártico, porque el vino, que era mi solo recurso, ha acabado por disgustarme. No quiero ya beber; he abusado de ello. Pero se dice que hay una ascensión aerostática el domingo en el jardín Jussupoff. Berg intenta, según parece, emprender un gran viaje aéreo y consiente en admitir algunos pasajeros mediante cierto precio... ¿No es verdad?\"},{\"heading\":false,\"text\":\"--¿Desea usted ir en globo?\"},{\"heading\":false,\"text\":\"--¿Yo? No... sí...--murmuró Svidrigailoff, que se había quedado pensativo.\"},{\"heading\":false,\"text\":\"«¿Qué clase de hombre es éste?», se preguntaba Raskolnikoff.\"},{\"heading\":false,\"text\":\"--No, la letra de cambio no me inquietaba--dijo Svidrigailoff--. Por mi gusto permanecía en la aldea. Hará próximamente un año, Marfa Petrovna, con motivo de mi santo, me devolvió el papel acompañado de una cantidad importante a título de regalo. Tenía mucho dinero. «Ya ves, Arcadio Ivanovitch, qué confianza me inspiras», me dijo. Le aseguro a usted que se expresaba así. ¿No lo cree usted? He de decirle que yo cumplía muy bien mis deberes de propietario rural; era muy conocido en el país. Además, para entretener mis ocios, encargaba libros. Al principio, mi mujer aprobaba mi afición a la lectura; pero más tarde llegó a temer que me fatigase mi excesiva aplicación.\"},{\"heading\":false,\"text\":\"--Dispense usted--replicó molestado Raskolnikoff--; déjese de todo eso, y dígame, si quiere, el motivo de su visita, tengo prisa y voy a salir...\"},{\"heading\":false,\"text\":\"--Bueno: ¿Su hermana de usted, Advocia Romanovna, va a casarse con Pedro Petrovitch Ludjin?\"},{\"heading\":false,\"text\":\"--Ruego a usted que deje a mi hermana a un lado en esta entrevista y que no pronuncie su nombre. Me asombra que se atreva usted a pronunciarlo en mi presencia.\"},{\"heading\":false,\"text\":\"--¿Cómo no nombrarla, si he venido precisamente para hablar a usted de ella?\"},{\"heading\":false,\"text\":\"--Está bien; haga usted el favor de terminar cuanto antes.\"},{\"heading\":false,\"text\":\"--Ese señor Ludjin es algo pariente mío, por parte de mi difunta esposa. Estoy seguro de que usted tiene ya formada opinión acerca de él si es que le ha visto, aunque no haya sido más que media hora, o si le ha hablado a usted de él alguna persona digna de crédito. No es un partido conveniente para Advocia Romanovna. Estoy convencido de que su hermana de usted se sacrifica de una manera tan magnánima como inconsiderada; se inmola por... su familia. Después de lo que he sabido respecto a usted, pensaba que vería con gusto la ruptura de ese matrimonio, siempre que no perjudicase a los intereses de su hermana. Ahora que le conozco personalmente, no tengo ninguna duda sobre el particular.\"},{\"heading\":false,\"text\":\"--Por parte de usted eso es muy cándido; perdone usted, quería decir muy desvergonzado--replicó Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Según eso, Rodión Romanovitch, me supone usted miras interesadas. Esté tranquilo: si yo trabajase para mí ocultaría mejor el juego; no soy tan imbécil. Voy a este propósito a descubrirle una particularidad psicológica. Hace poco me acusaba de haber amado a su hermana de usted, diciendo que había sido yo su víctima. Pues bien, al presente no siento ningún amor por ella, de tal modo que me asombro de haber estado seriamente enamorado...\"},{\"heading\":false,\"text\":\"--Era un capricho de un hombre desocupado y vicioso...\"},{\"heading\":false,\"text\":\"--En efecto, soy un hombre desocupado y vicioso. Por otra parte, su hermana de usted posee mérito bastante para impresionar a un libertino como yo; pero todo ello era fuego fatuo, lo veo claramente ahora.\"},{\"heading\":false,\"text\":\"--¿Y desde cuándo lo ha advertido usted?\"},{\"heading\":false,\"text\":\"--Ya lo sospechaba hace algún tiempo y me he convencido definitivamente de ello ayer, casi en el momento de llegar a San Petersburgo. Pero en Moscou todavía estaba decidido a obtener la mano de Advocia Romanovna y a disputársela como rival al señor Ludjin.\"},{\"heading\":false,\"text\":\"--Perdone usted que le interrumpa. ¿No podría abreviar y decirme en seguida el objeto de su visita? Le repito que tengo prisa, que he de hacer varias cosas...\"},{\"heading\":false,\"text\":\"--Con mucho gusto. Determinado ahora a emprender cierto viaje, quisiera antes arreglar varios asuntos. Mis hijos están en casa de su tía, son ricos y no me necesitan para nada. Por otra parte, ¿comprende usted que pueda representar yo como es debido el papel de padre? No he tomado más dinero que el que Marfa Petrovna me regaló hace un año; ese dinero me basta. Dispénseme usted, voy al grano. Antes de ponerme en camino quiero acabar con el señor Ludjin. No es que le deteste precisamente; pero él ha sido la causa de mi última rencilla con mi mujer; me incomodé cuando supe que ella había concertado ese matrimonio. Ahora me dirijo a usted para poder llegar a presencia de Advocia Romanovna; usted puede, si le parece, asistir a nuestra entrevista. En primer lugar desearía poner ante los ojos de su hermana todos los inconvenientes que resultarían para ella de su enlace con Ludjin. Le suplicaría después que me perdonase por los disgustos que le he causado, y le pediría permiso para ofrecerle 10.000 rublos, lo que la indemnizaría de una ruptura con el señor Ludjin, ruptura que, estoy seguro de ello, no repugnaría a su hermana de usted si viera la posibilidad de realizarla.\"},{\"heading\":false,\"text\":\"--¡Está usted loco, rematadamente loco!--exclamó Raskolnikoff con más sorpresa que cólera--. ¿Cómo se atreve a hablar de esa manera?\"},{\"heading\":false,\"text\":\"--Sabía perfectamente que iba usted a ponerse hecho una furia; pero comenzaré haciéndole observar que, aun no siendo rico, puedo disponer, sin embargo, de esos 10.000 rublos; quiero decir, que no los necesito. Si Advocia Romanovna no los acepta, sabe Dios el estúpido empleo que les daría. En segundo lugar, mi conciencia está completamente tranquila; en mi ofrecimiento no entra para nada el cálculo; créanlo o no lo crean, el porvenir se lo demostrará a usted y a Advocia Romanovna. En resumen, he molestado excesivamente a su honradísima hermana de usted; he experimentado un sincero pesar por lo ocurrido, y ansío no reparar por una compensación pecuniaria las contrariedades que le he ocasionado, sino hacerle un servicio insignificante, para que no se diga que sólo la he hecho mal. Si mi ofrecimiento ocultase alguna segunda intención, no lo haría tan francamente y no me limitaría a ofrecer 10.000 rublos, cuando le ofrecí mucho más hace cinco semanas. Por otra parte, yo pienso casarme con una joven dentro de poco, así que no puede sospecharse que yo quiera seducir a Advocia Romanovna. En suma, diré a usted que si se casa con el señor Ludjin, Advocia Romanovna recibirá esa misma cantidad, sólo que por otro conducto... No se incomode, señor Raskolnikoff; juzgue usted las cosas con calma y sangre fría.\"},{\"heading\":false,\"text\":\"Svidrigailoff había pronunciado estas palabras con extraordinaria calma.\"},{\"heading\":false,\"text\":\"--Suplico a usted que no siga--repuso Raskolnikoff--; la proposición de usted es una insolencia imperdonable.\"},{\"heading\":false,\"text\":\"--No hay tal cosa. Según eso, el hombre en este mundo sólo puede hacer mal a sus semejantes; en cambio no tiene derecho a hacer el menor bien. Las conveniencias sociales se oponen a ello. Eso es absurdo. Si yo, por ejemplo, muriese y dejase en mi testamento esa cantidad a su hermana de usted, ¿la rehusaría?\"},{\"heading\":false,\"text\":\"--Es muy probable.\"},{\"heading\":false,\"text\":\"--No hablemos más. Sea como quiera, suplico a usted que transmita mi demanda a Advocia Romanovna.\"},{\"heading\":false,\"text\":\"--No lo haré.\"},{\"heading\":false,\"text\":\"--En ese caso será necesario, Rodión Romanovitch, que yo trate de encontrarme frente a frente con ella, lo que no podré hacer sin inquietarla.\"},{\"heading\":false,\"text\":\"--Y si yo le comunico su pretensión, ¿no hará usted nada por verla?\"},{\"heading\":false,\"text\":\"--No sé qué contestarle; deseo vivamente hablar con ella aunque sea nada más que una vez.\"},{\"heading\":false,\"text\":\"--No lo espere usted.\"},{\"heading\":false,\"text\":\"--Tanto peor. Por lo demás, usted no me conoce. Quizá se establezcan entre nosotros relaciones amistosas.\"},{\"heading\":false,\"text\":\"--¿Usted cree...?\"},{\"heading\":false,\"text\":\"--¿Por qué no?--dijo sonriendo Svidrigailoff, y levantándose tomó el sombrero--; no es que yo quiera imponerme a usted; aunque he venido aquí, no confiaba demasiado... Esta mañana me chocó...\"},{\"heading\":false,\"text\":\"--¿Dónde me ha visto usted esta mañana?--preguntó Raskolnikoff con inquietud.\"},{\"heading\":false,\"text\":\"--Le he visto por casualidad. Me parece que somos dos frutos del mismo árbol.\"},{\"heading\":false,\"text\":\"--Está bien; permítame usted que le pregunte si piensa usted emprender pronto ese viaje.\"},{\"heading\":false,\"text\":\"--¿Qué viaje?\"},{\"heading\":false,\"text\":\"--El de que me ha hablado hace un momento.\"},{\"heading\":false,\"text\":\"--¿He hablado de un viaje? ¡Ah! ¡Sí, en efecto!... ¡Si supiese usted qué cuestión acaba de plantearme!--añadió con amarga sonrisa--, quizá en lugar de hacer ese viaje me casaré. Se está negociando un matrimonio para mí.\"},{\"heading\":false,\"text\":\"--¿Aquí?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--No ha perdido usted el tiempo desde su llegada a San Petersburgo.\"},{\"heading\":false,\"text\":\"--¡Ea! ¡Hasta la vista!... ¡Ah! se me olvidaba. Diga usted a su hermana que Marfa Petrovna le ha legado 3.000 rublos. Es la pura verdad. Mi mujer hizo testamento en mi presencia ocho días antes de su muerte. De aquí a dos o tres semanas, Advocia Romanovna podrá entrar en posesión de ese legado.\"},{\"heading\":false,\"text\":\"--¿Eso es verdad?\"},{\"heading\":false,\"text\":\"--Sí; puede usted comunicárselo. Servidor. Vivo muy cerca de aquí.\"},{\"heading\":false,\"text\":\"Al salir Svidrigailoff se cruzó en el umbral con Razumikin.\"}]},{\"title\":\"cuarta parte — capítulo II\",\"blocks\":[{\"heading\":false,\"text\":\"Eran las ocho. Los dos jóvenes salieron en seguida en dirección a la casa de Bakalaieff, deseosos de llegar antes que Ludjin.\"},{\"heading\":false,\"text\":\"--¿Quién es ése que salía al entrar yo en tu cuarto?--preguntó Razumikin cuando estuvieron en la calle.\"},{\"heading\":false,\"text\":\"--Svidrigailoff, el propietario en cuya casa estuvo mi hermana de institutriz y de donde tuvo que salir porque el dueño la requería de amores. Marfa Petrovna, la mujer de ese señor, la puso a la puerta. Más tarde, esa misma Marfa Petrovna pidió perdón a Dunia. Esa señora ha muerto repentinamente hace pocos días; de ella hablaba mi madre esta tarde. No sé por qué me da mucho miedo ese hombre. Es un tipo muy original y, por añadidura, ha tomado una firme resolución. Cualquiera diría que sabe algo... Ha llegado a San Petersburgo en cuanto se celebraron los funerales de su mujer... Es preciso proteger a Dunia contra él. Eso es lo que yo quería decirte, ¿entiendes?\"},{\"heading\":false,\"text\":\"--¡Protegerla! ¿Qué puede hacer contra Advocia Romanovna? Te agradezco que me hayas dicho eso... La protegeremos, puedes estar tranquilo... ¿Dónde vive?\"},{\"heading\":false,\"text\":\"--No lo sé.\"},{\"heading\":false,\"text\":\"--¿Por qué no se lo has preguntado? Pero no importa, yo le encontraré.\"},{\"heading\":false,\"text\":\"--¿Le has visto?--preguntó Raskolnikoff después de una pausa.\"},{\"heading\":false,\"text\":\"--Sí, le he examinado de pies a cabeza y te aseguro que no se me despintará.\"},{\"heading\":false,\"text\":\"--¿No le confundirás con otro? ¿Le has visto distintamente?--insistió Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¡Ya lo creo! Me acuerdo de su cara y le conocería entre mil. Soy buen fisonomista.\"},{\"heading\":false,\"text\":\"Se callaron de nuevo.\"},{\"heading\":false,\"text\":\"--¡Hum!--exclamó Raskolnikoff--. Me parece que soy víctima de alguna alucinación.\"},{\"heading\":false,\"text\":\"--¿Por qué dices eso?\"},{\"heading\":false,\"text\":\"--He aquí--prosiguió Raskolnikoff con una mueca que tendía a ser sonrisa--, que decís que estoy loco y voy creyendo que es verdad...\"},{\"heading\":false,\"text\":\"--Vamos, déjate de tonterías y escucha lo que he hecho--interrumpió Razumikin--. Entré en tu cuarto y te encontré durmiendo. En seguida comimos, después de lo cual fuí a ver a Porfirio Petrovitch. Zametoff estaba todavía en su casa. Quise hablar en debida forma y no fuí afortunado en mi exordio. No acertaba a entrar en materia; parecía que no entendía, pero me demostraban, por otra parte, la mayor flema. Llevé a Porfirio cerca de una ventana y me puse a hablarle; pero tampoco estuve muy feliz. El miraba de un lado y yo de otro. Por último, le aproximé el puño a las narices y le dije que le iba a reventar. Porfirio se contentó con mirarme en silencio. Yo escupí y me marché. Ya lo sabes todo. Esto es muy tonto. Con Zametoff no cambié ni una palabra. Me daba a los diablos por mi estúpida conducta; pero me he consolado con una reflexión; al bajar la escalera me dije: ¿Vale la pena que tú y yo nos preocupemos de ese modo? Si algún peligro te amenazase sería otra cosa; pero, ¿qué tienes tú que temer? No eres culpable; luego no debes inquietarte de lo que piensen ellos. Más tarde nos burlaremos de su necedad. ¡Qué vergüenza será para ellos el haberse equivocado tan groseramente! No te preocupes; ya les sentaremos la mano; mas por el momento, limitémonos a reír de sus tonterías.\"},{\"heading\":false,\"text\":\"--Es verdad--respondió Raskolnikoff--. ¿Pero qué dirás tú mañana?--añadió para si.\"},{\"heading\":false,\"text\":\"¡Cosa extraña! Hasta entonces no se le había ocurrido ni una vez preguntarse: «¿Qué pensará Razumikin cuando sepa que soy culpable?» Al ocurrírsele esta idea miró fijamente a su amigo. El relato de su visita a Porfirio le había interesado muy poco; otras cosas le preocupaban en aquel momento.\"},{\"heading\":false,\"text\":\"En el corredor encontraron a Ludjin que había llegado a las ocho en punto; pero había perdido algún tiempo en buscar el número; de modo que los tres entraron juntos sin mirarse ni saludarse. Los jóvenes se presentaron los primeros. Pedro Petrovitch, siempre fiel a las conveniencias, se detuvo un momento en la antesala para quitarse el gabán. Pulkeria Alexandrovna se dirigió en seguida a él. Dunia y Raskolnikoff se estrecharon la mano.\"},{\"heading\":false,\"text\":\"Al entrar, Pedro Petrovitch saludó a las señoras de manera bastante cortés, aunque con gravedad extremada. Parecía, sin embargo, algo desconcertado. Pulkeria Alexandrovna, que estaba también algo molesta, se apresuró a hacer sentar a todo el mundo alrededor de la mesa, donde estaba colocado el samovar. Dunia y Ludjin tomaron asiento uno frente al otro, en los dos extremos de la mesa. Razumikin y Raskolnikoff se sentaron también al frente de la mesa: el primero, al lado de Ludjin; el segundo, cerca de su hermana.\"},{\"heading\":false,\"text\":\"Hubo un instante de silencio. Pedro Petrovitch sacó pausadamente un pañuelo de batista perfumado y se sonó. Sus maneras eran, sin duda, las de un hombre benévolo, pero un poco herido en su dignidad y firmemente resuelto a exigir explicaciones. En la antesala, en el momento de quitarse el gabán, se preguntaba si no sería el castigo para las dos señoritas retirarse inmediatamente. Sin embargo, no había ejecutado esa idea, porque le gustaban las situaciones claras; así, pues, existía un punto que permanecía oculto para él; puesto que se había desairado abiertamente su prohibición, debía de haber algún motivo para ello. Mejor era tirar adelante, poner las cosas en claro; siempre habría tiempo de aplicar el castigo, y éste no por ser retrasado sería menos seguro.\"},{\"heading\":false,\"text\":\"--Me alegraré que el viaje de usted haya sido feliz--dijo por cortesía a Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"--Sí que lo ha sido, gracias a Dios.\"},{\"heading\":false,\"text\":\"--Me alegro mucho. Y Advocia Romanovna, ¿se ha fatigado?\"},{\"heading\":false,\"text\":\"--Yo soy joven y fuerte, no me fatigo; mas para mamá este viaje ha sido muy penoso--respondió Dunia.\"},{\"heading\":false,\"text\":\"--¿Qué quiere usted? Nuestros caminos provinciales son muy largos. Rusia es grande... A pesar de mis deseos, no pude ir a recibir a ustedes. Espero, sin embargo, que no se habrán visto en ningún apuro.\"},{\"heading\":false,\"text\":\"--¡Oh! Por el contrario, Pedro Petrovitch; nos hemos encontrado en una situación muy difícil--dijo con una entonación particular Pulkeria Alexandrovna--; y si Dios no nos hubiese deparado ayer a Demetrio Prokofitch, no sé qué hubiera sido de nosotras. Permita usted que le presente a nuestro salvador Demetrio Prokofitch Razumikin.\"},{\"heading\":false,\"text\":\"--¡Ah! Sí, ayer tuve el placer...--balbuceó Ludjin echando una oblicua y malévola mirada al joven; después frunció el entrecejo y calló.\"},{\"heading\":false,\"text\":\"Pedro Petrovitch era una de esas personas que se esfuerzan por ser amables y vivaces en sociedad, pero que bajo la influencia de cualquier contrariedad pierden súbitamente la serenidad, hasta el punto de parecer más bien sacos de harina que despejados caballeros. El silencio volvió a reinar de nuevo; Raskolnikoff se encerraba en un obstinado mutismo. Advocia Romanovna juzgaba que no había llegado para ella el momento de hablar. Razumikin nada tenía que decir, de modo que Pulkeria Alexandrovna se vió en la necesidad penosa de reanudar otra vez la conversación.\"},{\"heading\":false,\"text\":\"--¿Sabe usted que Marfa Petrovna ha muerto?--dijo.\"},{\"heading\":false,\"text\":\"--Me lo comunicaron, y puedo, además, decir a ustedes que inmediatamente después del entierro de su mujer, Arcadio Ivanovitch Svidrigailoff se ha venido a San Petersburgo. Sé de buena tinta esa noticia.\"},{\"heading\":false,\"text\":\"--¿En San Petersburgo? ¿Aquí?--preguntó alarmada Dunia, y cambió una mirada con su madre.\"},{\"heading\":false,\"text\":\"--Precisamente, y debe suponerse que ha venido con alguna intención; la precipitación de su partida y el conjunto de circunstancias precedentes lo hacen creer así.\"},{\"heading\":false,\"text\":\"--¡Señor! ¿Es posible que, hasta aquí venga a acosar a Dunetshka?--exclamó Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"--Me parece que ni la una ni la otra deben ustedes inquietarse mucho de su presencia en San Petersburgo, en el caso, por supuesto, de que ustedes quieran evitar toda especie de relaciones; por mi parte estaré con ojo avizor y sabré pronto dónde se hospeda.\"},{\"heading\":false,\"text\":\"--¡Ay! Pedro Petrovitch, usted no puede imaginarse hasta qué punto me ha asustado--repuso Pulkeria Alexandrovna--. Sólo le he visto dos veces y me pareció terrible. Segura estoy de que ha causado la muerte de la pobre Marfa Petrovna.\"},{\"heading\":false,\"text\":\"--Las noticias exactas no autorizan a suponer tal cosa. Por lo demás, no niego que su mal proceder no haya podido, en cierto modo y en cierta medida, apresurar el curso natural de las cosas. En cuanto a la conducta y en general a la característica moral del personaje, estoy de acuerdo con usted. Ignoro si ahora es rico y lo que su mujer ha podido dejarle: lo sabré dentro de poco. Lo que tengo por cierto es que, encontrándose aquí en San Petersburgo, no tardará en volver a su antigua vida, aunque tenga muy pocos medios pecuniarios. Es el hombre más perdido, vicioso y depravado que existe. Tengo motivos para creer que Marfa Petrovna, la cual tuvo la desgracia de enamorarse de él y que pagó sus deudas hace ocho años, le ha sido útil también en algún otro sentido. A fuerza de gestiones y sacrificios logró que se diese carpetazo a una causa criminal que podía haber dado en Siberia con el señor Svidrigailoff. Se trataba nada menos que de un asesinato cometido en condiciones particularmente espantosas y, por decirlo así, fantásticas. Tal es ese hombre, si ustedes deseaban saberlo.\"},{\"heading\":false,\"text\":\"--¡Ah, señor!--exclamó Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"Raskolnikoff escuchaba atentamente.\"},{\"heading\":false,\"text\":\"--¿Usted habla, dice, según datos ciertos?--preguntó con tono severo Dunia.\"},{\"heading\":false,\"text\":\"--Me limito a repetir lo que oí de labios mismos de Marfa Petrovna. Hay que advertir que, desde el punto de vista jurídico, este asunto es muy obscuro. En aquel tiempo habitaba aquí, y parece que vive todavía, cierta extranjera llamada Reslich que prestaba dinero con módico interés y ejercía otros diversos oficios. Entre esta mujer y Svidrigailoff existían, desde hacía largo tiempo, relaciones tan íntimas como misteriosas. Vivía con ella una parienta lejana, una sobrina, joven de quince años o de catorce, que era sordomuda. La Reslich no podía sufrir a esta muchacha: le echaba en cara cada pedazo de pan que la pobre comía y la maltrataba con inaudita crueldad. Un día se encontró a la infeliz muchacha ahorcada en el granero. La sumaria acostumbrada dió por resultado una comprobación de suicidio, y todo parecía haber terminado aquí, cuando la policía recibió aviso de que la joven había sido violada por Svidrigailoff. En verdad, todo esto era obscuro. La denuncia emanaba de otra alemana, mujer de notoria inmoralidad y cuyo testimonio no podía ser de gran crédito. En una palabra: no hubo proceso. Marfa Petrovna se puso en campaña, prodigó el dinero y logró echar tierra al asunto; pero no dejaron de correr con aquel motivo los más graves rumores acerca de Svidrigailoff. En el tiempo en que usted estuvo en su casa, Advocia Romanovna, habrá oído contar, sin duda, la historia de su criado Philipo, muerto a causa de los malos tratamientos de su amo. Esto ocurrió hace seis años, cuando aun existía la servidumbre.\"},{\"heading\":false,\"text\":\"--Oí decir, por el contrario, que ese Philipo se había ahorcado.\"},{\"heading\":false,\"text\":\"--Perfectamente; pero se vió reducido, o por mejor decir, impulsado a darse la muerte por las brutalidades incesantes y los malos tratamientos sistemáticos de su amo.\"},{\"heading\":false,\"text\":\"--Lo ignoraba--respondió secamente Dunia--. Oí, sí, contar acerca de eso una historia muy extraña. Parece que el tal Philipo era un hipocondríaco, una especie de criado filósofo. Sus compañeros decían que la lectura le había turbado el entendimiento, y, a creerlos, se había ahorcado para huir, no de los golpes, sino de las burlas del señor Svidrigailoff. Le vi tratar muy humanamente a sus servidores y era muy amado de ellos, aunque le imputaban, en efecto, la muerte de Philipo.\"},{\"heading\":false,\"text\":\"--Veo, Advocia Romanovna, que tiende usted a justificarle--repuso Ludjin con una sonrisa agridulce--. Verdad es que le tengo por hombre muy hábil para insinuarse en el corazón de las señoras. La pobre Marfa Petrovna, que acaba de morir en circunstancias muy extrañas, es una lamentable prueba de ello. Yo sólo trato de advertírselo a usted y a su mamá en previsión de las tentativas que de seguro no dejará de renovar. Por otra parte, estoy firmemente convencido de que ese hombre acabará en la prisión por deudas. Marfa Petrovna pensaba demasiado en el porvenir de sus hijos para tener el propósito de asegurar a su marido una parte importante de su fortuna. Es de suponer que le habrá dejado lo suficiente para vivir con decorosa modestia; pero con sus costumbres disipadas se lo comerá todo antes de un año.\"},{\"heading\":false,\"text\":\"--Suplico a usted que no hablemos más de Svidrigailoff. Eso me es desagradable--dijo Dunia.\"},{\"heading\":false,\"text\":\"--Ha estado en mi casa hace un rato--dijo bruscamente Raskolnikoff, que hasta entonces no había despegado los labios.\"},{\"heading\":false,\"text\":\"Todos se volvieron hacia él con exclamaciones de sorpresa; hasta el mismo Pedro Petrovitch se quedó algo pasmado.\"},{\"heading\":false,\"text\":\"--Hace media hora, mientras yo dormía, entró en mi cuarto, y después de despertarme se presentó él mismo. Estaba bastante contento y alegre; espera que yo he de hacerme amigo suyo, y, entre otras cosas, solicita una entrevista contigo para decirte que Marfa Petrovna, ocho días antes de su muerte, te había dejado en su testamento tres mil rublos, cantidad que recibirás en breve plazo.\"},{\"heading\":false,\"text\":\"--¡Alabado sea Dios!--exclamó Pulkeria Alexandrovna, e hizo la señal de la cruz--. ¡Reza por ella, Dunia, reza!\"},{\"heading\":false,\"text\":\"--El hecho es exacto--no pudo menos de afirmar Ludjin.\"},{\"heading\":false,\"text\":\"--¿Y después?--preguntó vivamente Dunia.\"},{\"heading\":false,\"text\":\"--Después me dijo que no era rico, que toda su fortuna pasaba a sus hijos, los cuales están ahora en casa de su tía. También me contó que se hospedaba cerca de mi casa; ¿dónde?, no lo sé; no se lo he preguntado.\"},{\"heading\":false,\"text\":\"--¿Qué otra cosa tiene que decir a Dunia?--preguntó con inquietud Pulkeria Alexandrovna--. ¿Te lo ha dicho?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Y qué?\"},{\"heading\":false,\"text\":\"--Lo diré luego.\"},{\"heading\":false,\"text\":\"Después de esta respuesta, Raskolnikoff se puso a tomar el te.\"},{\"heading\":false,\"text\":\"Pedro Petrovitch miró el reloj.\"},{\"heading\":false,\"text\":\"--Un negocio urgente me obliga a dejar a ustedes, y de este modo no interrumpiré su conferencia--añadió un poco molesto, y al decir estas palabras se levantó.\"},{\"heading\":false,\"text\":\"--Quédese usted, Pedro Petrovitch--dijo Dunia--. Usted tenía intención de dedicarnos la velada. Además, nos ha escrito diciéndonos que deseaba tener una explicación con mamá.\"},{\"heading\":false,\"text\":\"--Es verdad, Advocia Romanovna--respondió con tono punzante Pedro Petrovitch, que se sentó a medias, conservando el sombrero en la mano--; deseaba, en efecto, tener una explicación con su madre y con usted, sobre algunos puntos de suma gravedad. Pero como su hermano no puede explicarse delante de mí acerca de ciertas proposiciones hechas por Svidrigailoff, yo no quiero ni puedo explicarme ante una tercera persona... sobre ciertos puntos de extrema importancia. Por otra parte, ya había expresado en términos formales mi deseo, que no se ha tenido en cuenta.\"},{\"heading\":false,\"text\":\"Las facciones de Ludjin tomaron una expresión dura y altanera.\"},{\"heading\":false,\"text\":\"--Ha pedido usted, en efecto, que mi hermano no asistiese a nuestra entrevista, y si él no ha accedido a su deseo, ha sido únicamente cediendo a mis instancias. Usted nos ha escrito que había sido insultado por nuestro hermano, y yo creo que debe de haber en esto alguna mala inteligencia y que tienen ustedes que reconciliarse. Si verdaderamente Rodia le ha ofendido a usted, debe darle sus excusas, y lo hará.\"},{\"heading\":false,\"text\":\"Al oír estas palabras, Pedro Petrovitch se sintió menos dispuesto que nunca a hacer concesiones.\"},{\"heading\":false,\"text\":\"--A pesar de toda la buena voluntad del mundo, Advocia Romanovna, es imposible olvidar ciertas injurias. En todo hay un límite que es peligroso traspasar, porque una vez que se franquea, no se puede retroceder.\"},{\"heading\":false,\"text\":\"--¡Ah! deseche usted esa vana susceptibilidad, Pedro Petrovitch--interrumpió Dunia con voz conmovida--. Sea el hombre inteligente y noble que yo siempre he visto en usted y que quiero ver en adelante. Le he hecho a usted una gran promesa. Soy la esposa futura de usted. Confíe en mí en este asunto y crea que puedo juzgar con imparcialidad. El papel de árbitro que me atribuyo en este momento es una promesa tan grande para mi hermano como para usted. Cuando hoy, después de la carta de usted, le he suplicado que asistiera a nuestra entrevista, no le dije cuáles eran mis intenciones. Comprenda usted que si rehusan reconciliarse me veré forzada a optar por uno excluyendo al otro. De tal modo se encuentra planteada la cuestión a causa de ustedes dos. No quiero ni debo engañarme en mi elección: para usted es preciso que rompa con mi hermano; para mi hermano es preciso que rompa con usted. Menester es que esté cierta de los sentimientos de ustedes. Ahora deseo saber, de una parte, si tengo en Rodia un hermano; de otra, si tengo en usted un marido que me ama y me estima.\"},{\"heading\":false,\"text\":\"--Advocia Romanovna--repuso Ludjin amostazado--: su lenguaje da lugar a interpretaciones diversas; es más, lo encuentro ofensivo, en vista de la situación que tengo el honor de ocupar respecto de usted. Prescindiendo de lo que hay de mortificante para mí al verme colocado al mismo nivel que un... orgulloso joven, parece que usted admite como posible la ruptura del matrimonio convenido entre nosotros. Dice usted que tiene que elegir entre su hermano y yo; por esto mismo se ve lo poco que significo a los ojos de usted... No puedo aceptar tal cosa, dadas nuestras relaciones y dados nuestros compromisos recíprocos.\"},{\"heading\":false,\"text\":\"--¡Cómo!--exclamó Dunia enrojeciendo vivamente--. ¿Conque pongo el interés de usted en la balanza con todo lo que yo amo más en la vida, y se queja de significar poco a mis ojos?\"},{\"heading\":false,\"text\":\"Raskolnikoff se sonrió sarcásticamente. Razumikin hizo una mueca; pero la respuesta de la joven no calmó a Ludjin, que a cada instante se ponía más pedante e intratable.\"},{\"heading\":false,\"text\":\"--El amor por el esposo, por el futuro compañero de la vida, debe estar por encima del amor fraternal--declaró sentenciosamente--; en todo caso yo no puedo admitir que se me coloque en la misma línea... Aunque haya dicho hace un momento que no quería ni podía explicarme en presencia de su hermano acerca del principal objeto de mi visita, hay un punto de suma gravedad para mí que desearía esclarecer en seguida con su señora madre. Su hijo de usted--continuó dirigiéndose a Pulkeria Alexandrovna--, ayer, delante del señor Razumikin, ¿no es éste el apellido de usted?, dispénseme si he olvidado su nombre--dijo a éste haciéndole un amable saludo--, me ha ofendido, alterando una frase pronunciada por mí el día que tomé café en casa de ustedes. Dije yo que, en mi concepto, una joven pobre y ya experimentada en la desgracia ofrecía a un marido más garantías de moralidad y dicha conyugal que una persona que hubiese vivido siempre en la abundancia. Su hijo de usted, con deliberado propósito, ha dado significado odioso a mis palabras y presumo que se ha fundado para ello en alguna carta de usted. Sería una gran satisfacción para mí si usted me probase que estaba engañado. Dígame con exactitud en qué términos ha reproducido mi pensamiento al escribir al señor Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Ya no me acuerdo--respondió algo confusa Pulkeria Alexandrovna--; le manifesté el pensamiento de usted, tal como lo había comprendido. Ignoro cómo ha repetido Rodia mi frase. Puede que haya forzado mis términos...\"},{\"heading\":false,\"text\":\"--No ha podido hacerlo más que inspirándose en lo que usted haya escrito.\"},{\"heading\":false,\"text\":\"--Pedro Petrovitch--replicó con dignidad Pulkeria Alexandrovna--, la prueba de que Dunia y yo no hemos tomado a mala parte las palabras de usted, es que estamos aquí.\"},{\"heading\":false,\"text\":\"--¡Bien, mamá!--aprobó la joven.\"},{\"heading\":false,\"text\":\"--¿De modo que soy yo el equivocado?--dijo resentido Ludjin.\"},{\"heading\":false,\"text\":\"--¿Ve usted, Pedro Petrovitch? Acusa usted a Rodia sin tener en cuenta que en su carta de hoy le atribuye usted un hecho falso--prosiguió Pulkeria Alexandrovna, muy animada por la aprobación que acababa de manifestarle su hija.\"},{\"heading\":false,\"text\":\"--No me acuerdo de haber escrito nada falso.\"},{\"heading\":false,\"text\":\"--Según la carta de usted--declaró con tono áspero Raskolnikoff sin volverse hacia Ludjin--, el dinero que entregué ayer a la viuda de un hombre atropellado por un coche se lo había dado a su hija (a quien veía entonces por primera vez). Usted ha escrito eso con la intención, sin duda, de indisponerme con mi familia, y para conseguirlo mejor, ha calificado de la manera más innoble la conducta de una joven a quien usted no conocía. Esto es una baja difamación.\"},{\"heading\":false,\"text\":\"--Perdone usted, señor--respondió Ludjin temblando de cólera--. Si en mi carta me he extendido en lo que a usted se refiere, ha sido porque su madre de usted y su hermana me suplicaron que les dijese cómo había encontrado a usted y qué impresión me había usted producido. Por otra parte, le desafío a que señale una sola línea mentirosa en el pasaje en que usted alude. ¿Negará usted, en efecto, que ha dado su dinero? Y en cuanto a la desgraciada familia de que se trata, ¿se atrevería usted a responder de la honradez de todos sus miembros?\"},{\"heading\":false,\"text\":\"--Toda la honradez de usted no vale lo que el dedo meñique de la pobre joven a quien arroja usted la primera piedra.\"},{\"heading\":false,\"text\":\"--¿De modo que no vacilará usted en ponerla en contacto con su madre y su hermana?\"},{\"heading\":false,\"text\":\"--Si lo desea usted saber, le diré que ya lo he hecho. La he invitado a tomar asiento al lado de mi madre y de Dunia.\"},{\"heading\":false,\"text\":\"--¡Rodia!--exclamó Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"Dunia se ruborizó, Razumikin frunció el ceño y Ludjin se sonrió despreciativamente.\"},{\"heading\":false,\"text\":\"--Juzgue usted misma, Advocia Romanovna, si el acuerdo es posible. Supongo que esto es un asunto terminado del cual no hay más que hablar. Me retiro para no interrumpir por más tiempo esta reunión de familia.\"},{\"heading\":false,\"text\":\"Se levantó y tomó el sombrero.\"},{\"heading\":false,\"text\":\"--Pero permítanme ustedes que les diga antes de irme que deseo no verme expuesto en lo sucesivo a semejantes encuentros. Es a usted particularmente, mi distinguida Pulkeria Alexandrovna, a quien dirijo esta súplica; tanto más, cuanto que mi carta era para usted y no para otras personas.\"},{\"heading\":false,\"text\":\"Pulkeria Alexandrovna se sintió un tanto irritada.\"},{\"heading\":false,\"text\":\"--¿Cree usted que es nuestro amo, Pedro Petrovitch? Dunia le ha dicho ya por qué no ha sido satisfecho su deseo; mi hija no tenía más que buenas intenciones. Pero, en verdad, usted me escribe en un estilo muy imperioso, y menester es que miremos sus deseos como una orden. Diré a usted, por el contrario, que ahora, sobre todo, debe tratarnos con consideraciones y miramientos, puesto que la confianza en usted nos ha hecho dejarlo todo para venir aquí, y, por consiguiente, nos tiene ya a su disposición.\"},{\"heading\":false,\"text\":\"--Eso no es del todo exacto, Pulkeria Alexandrovna; sobre todo, desde el momento que conoce usted el legado hecho por Marfa Petrovna a Advocia Romanovna. Estos tres mil rublos llegan muy a punto, según parece, a juzgar por el nuevo tono que toma usted conmigo--añadió agriamente Ludjin.\"},{\"heading\":false,\"text\":\"--Esa observación haría suponer que usted había especulado sobre nuestra miseria--observó Dunia con voz irritada.\"},{\"heading\":false,\"text\":\"--Ahora, por lo menos, no puedo especular con ella. Y sobre todo, no quiero impedir que oiga usted las proposiciones secretas que Arcadio Ivanovitch Svidrigailoff ha encargado, para que se las transmita, a su hermano de usted. Por lo que veo, esas proposiciones tienen para usted una importancia capital y quizá también muy agradable.\"},{\"heading\":false,\"text\":\"--¡Ah! ¡Dios mío!--exclamó Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"Razumikin se agitaba impacientemente en su silla.\"},{\"heading\":false,\"text\":\"--¿No te avergüenza, hermana?--preguntó Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Sí--respondió la joven--. Pedro Petrovitch, ¡salga usted!--añadió pálida de cólera.\"},{\"heading\":false,\"text\":\"Este último no esperaba semejante desenlace. Era demasiado presumido y contaba con su fuerza y con la impotencia de sus víctimas. En aquel momento no daba crédito a sus oídos.\"},{\"heading\":false,\"text\":\"--Advocia Romanovna--dijo pálido y con los labios temblorosos--, si salgo ahora tenga usted por cierto que ya no volveré jamás. Reflexione usted. Yo no tengo más que una palabra.\"},{\"heading\":false,\"text\":\"--¡Qué impudencia!--exclamó Dunia saltando de su asiento--. ¡Pero si lo que quiero es perderle de vista para siempre!\"},{\"heading\":false,\"text\":\"--¿Cómo? ¿Eso dice usted?--vociferó Ludjin, tanto más desconcertado cuanto que hasta el último minuto había creído imposible semejante ruptura--. ¡Ah! ¿Es así? ¿Sabe usted, Advocia Romanovna, que yo podría protestar?\"},{\"heading\":false,\"text\":\"--¿Con qué derecho le habla usted así?--dijo con vehemencia Pulkeria Alexandrovna--. ¿De qué tiene usted que protestar? ¿Cuáles son sus derechos? Sí, sus derechos. ¿Iría yo a dar a mi Dunia a un hombre como usted? ¡Váyase en seguida y déjenos tranquilas! ¿En qué estábamos pensando, sobre todo yo, para consentir en una cosa tan indigna?\"},{\"heading\":false,\"text\":\"--Sin embargo, Pulkeria Alexandrovna--replicó Pedro Petrovitch exasperado--, ustedes me han comprometido, dando una palabra que ahora retiran... y, por último, esto... esto... me ha ocasionado gastos.\"},{\"heading\":false,\"text\":\"La última recriminación estaba tan dentro del carácter de Ludjin, que Raskolnikoff, a pesar del furor que sentía, no pudo oírla sin soltar la carcajada; pero no le sucedió lo mismo a Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"--¿Gastos? ¿Gastos?--replicó violentamente--. ¿Se trata acaso del cajón que usted nos ha mandado? ¡Pero si usted ha obtenido su transporte gratuito! ¿Y pretende usted que le hemos comprometido? ¿Se pueden invertir los papeles hasta ese punto? Nosotras somos las que estamos a merced de usted, y no usted a la nuestra.\"},{\"heading\":false,\"text\":\"--¡Basta, mamá, basta, te lo suplico!--dijo Advocia Romanovna--. Pedro Petrovitch, tenga usted la bondad de marcharse.\"},{\"heading\":false,\"text\":\"--Sí, me voy. Una palabra solamente--respondió casi fuera de sí--. Su mamá de usted parece haber olvidado completamente que pedí su mano cuando corrían acerca de usted muy malos rumores en toda la comarca. Al desafiar por usted la opinión pública, y al restablecer su reputación, tenía derecho a esperar que me lo agradecería usted; pero esto me hace caer la venda de los ojos, y veo que mi conducta ha sido muy inconsiderada y que quizá he cometido un gran error despreciando la voz pública...\"},{\"heading\":false,\"text\":\"--¡Pero este hombre quiere que le rompan la cabeza!--exclamó Razumikin, que se había levantado para castigar al insolente.\"},{\"heading\":false,\"text\":\"--Es usted un malvado--añadió Dunia.\"},{\"heading\":false,\"text\":\"--Ni una palabra, ni un gesto--agregó vivamente Raskolnikoff, deteniendo a Razumikin; y aproximando luego su cara a la de Ludjin, le dijo en voz baja, pero perfectamente clara--: ¡Váyase usted! ¡Ni una palabra más! De lo contrario...\"},{\"heading\":false,\"text\":\"Pedro Petrovitch, con el rostro pálido y contraído por la cólera, le miró durante algunos segundos; después giró sobre sus talones, y desapareció, llevándose en el corazón un odio mortal contra Raskolnikoff, a quien imputaba solamente su desgracia. Mientras descendía la escalera, se imaginaba, empero, que no estaba perdido sin remedio, y que no tenía nada de imposible una reconciliación con las señoras.\"}]},{\"title\":\"cuarta parte — capítulo III\",\"blocks\":[{\"heading\":false,\"text\":\"Durante cinco minutos todos estuvieron muy alegres; su satisfacción les hacía reír estrepitosamente. Sólo Dunia palidecía de vez en cuando al recuerdo de la escena precedente. Pero de todos, el más gozoso era Razumikin. Aunque no se atrevía abiertamente a manifestar su contento, éste se delataba, a pesar suyo, en el temblor febril de toda su persona. Ahora tenía el derecho de dar su vida por las dos señoras, y de consagrarse a su servicio. Ocultaba, sin embargo, estos pensamientos en lo más profundo de sí mismo, y temía dar alas a su imaginación. En cuanto a Raskolnikoff, inmóvil y huraño, no tomaba parte en la alegría general; parecía que su espíritu estaba en otra parte... Después de haber insistido tanto porque se rompiese con Ludjin, hubiérase dicho que esa ruptura, ya consumada, le tenía sin cuidado. Dunia no pudo menos de pensar que su hermano estaba aún enojado con ella, y Pulkeria Alexandrovna le miraba con inquietud.\"},{\"heading\":false,\"text\":\"--¿Qué es lo que te ha dicho Svidrigailoff?--preguntó la joven, acercándose a su hermano.\"},{\"heading\":false,\"text\":\"--¡Ah! Sí, sí--dijo vivamente Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"Raskolnikoff levantó la cabeza.\"},{\"heading\":false,\"text\":\"--Está decidido a regalarte diez mil rublos, y desea verte, pero en mi presencia.\"},{\"heading\":false,\"text\":\"--¿Verle? ¡Jamás!--gritó Pulkeria Alexandrovna--. ¿Cómo se atreve a ofrecerle dinero?\"},{\"heading\":false,\"text\":\"Raskolnikoff refirió entonces con bastante sequedad su entrevista con Svidrigailoff.\"},{\"heading\":false,\"text\":\"A Dunia le preocuparon extraordinariamente las proposiciones de Svidrigailoff, y quedó largo tiempo pensativa.\"},{\"heading\":false,\"text\":\"--Algún terrible designio ha concebido--murmuró para sí, casi temblando.\"},{\"heading\":false,\"text\":\"Raskolnikoff advirtió este terror excesivo.\"},{\"heading\":false,\"text\":\"--Creo que tendré ocasión de verle más de una vez--dijo a su hermana.\"},{\"heading\":false,\"text\":\"--Encontraremos sus huellas--exclamó enérgicamente Razumikin--. Yo lo descubriré. No le perderé de vista, ya que Raskolnikoff me lo permite. El mismo me lo ha dicho hace poco: «Vela por mi hermana». ¿Consiente usted, Advocia Romanovna?\"},{\"heading\":false,\"text\":\"Dunia sonrió y tendió la mano al joven; pero seguía preocupada. Pulkeria Alexandrovna le dirigió una tímida mirada. También es cierto que le habían tranquilizado notablemente los tres mil rublos. Un cuarto de hora después se hablaba con animación. El mismo Raskolnikoff, aunque silencioso, prestó durante algún tiempo oído a lo que se decía. La voz cantante la llevaba Razumikin.\"},{\"heading\":false,\"text\":\"--¿Por qué, pregunto a ustedes, por qué irse?--gritaba convencido--. ¿Qué van ustedes a hacer en aquel pueblucho? Lo que principalmente hay que procurar aquí es que todos ustedes estén juntos, puesto que se han de menester los unos a los otros. No; no deben separarse. Vamos, quédense ustedes siquiera un tiempo. Acéptenme ustedes como amigo y como asociado, y les aseguro que emprenderemos un excelente negocio. Escúchenme ustedes. Voy a explicarles minuciosamente mi proyecto. Se me ocurrió la idea esta mañana, cuando aun no se sabía nada... He aquí de qué se trata: Yo tengo un tío; se lo presentaré a ustedes; es un viejo muy campechano y muy respetable. Este tío posee un capital de mil rublos, que no sabe qué hacer de ellos, porque cobra una pensión que basta a sus necesidades. Desde hace dos años no cesa de ofrecerme esta suma al seis por ciento de interés. Bien comprendo que es un medio de que se vale para ayudarme. El año último, yo no tenía necesidad de dinero; pero al presente sólo esperaba que llegase el buen viejo para decirle que aceptaba. A los mil rublos de mi tío juntan ustedes mil más y ya está formada la asociación.\"},{\"heading\":false,\"text\":\"--¿Qué negocio vamos a emprender?\"},{\"heading\":false,\"text\":\"Entonces Razumikin se puso a desarrollar su proyecto. Según él, la mayor parte de los libreros y editores rusos hacen malos negocios porque conocen mal su oficio; pero con buenas obras se podía ganar dinero. El joven, que llevaba ya dos años trabajando para diversas librerías, estaba al corriente del asunto y conocía bastante bien tres lenguas europeas. Seis días antes le dijo, es cierto, a Raskolnikoff, que no sabía bien el alemán; pero habló de ese modo para decidir a su amigo a que colaborase con él en una traducción que podía proporcionarle algunos rublos. Raskolnikoff no se dejó engañar por aquella mentira.\"},{\"heading\":false,\"text\":\"--¿Por qué, pues, hemos de despreciar un buen negocio, cuando poseemos uno de los medios de acción más esenciales, el dinero?--continuó, animándose, Razumikin--. Claro es que habrá que trabajar mucho; pero trabajaremos, pondremos todos manos a la obra. Usted, Advocia Romanovna, yo, Rodia... ¡Hay publicaciones que producen al presente excelentes rendimientos! Tendremos, sobre todo, la ventaja de conocer lo que conviene traducir. Seremos a la vez traductores, editores y profesores. Ahora puedo ser útil, porque tengo experiencia. Hace dos años que no salgo de casa de los libreros, y sé todas las triquiñuelas del oficio; crean ustedes que lo que propongo no es obra de romanos. Cuando se ofrece la ocasión de ganar algún dinero, ¿por qué no aprovecharla? Podría citar dos o tres libros extranjeros cuya publicación sería una mina de oro. Si se lo indicase a uno de nuestros editores, nada más que por esto debería yo cobrar quinientos rublos; pero no lo soy tanto. Por otra parte, capaces serían los imbéciles de vacilar. En cuanto a la parte material de la empresa, impresión, papel, venta, me encargan ustedes a mí; eso lo entiendo. Comenzaremos modestamente; poco a poco iremos ampliando el negocio, y en todo caso, seguro estoy de que conseguiremos los dos objetos.\"},{\"heading\":false,\"text\":\"A Dunia le brillaban los ojos.\"},{\"heading\":false,\"text\":\"--Lo que usted propone--dijo--me gusta mucho, Demetrio Prokofitch.\"},{\"heading\":false,\"text\":\"--Yo, es claro, no entiendo nada de eso--añadió Pulkeria Alexandrovna--. Sin duda, conviene. Nosotras tenemos que permanecer aquí por algún tiempo--dijo mirando a Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¿Qué piensas tú de esto, hermano?--preguntó Dunia.\"},{\"heading\":false,\"text\":\"--Encuentro su idea excelente--respondió el joven--. Cierto es que no se improvisa de un día a otro una gran librería; pero hay cinco o seis libros cuyo buen éxito no me ofrece duda y son los mejores para comenzar. Conozco uno, sobre todo, que de seguro se vendería. Además, podéis tener confianza completa en la capacidad de Razumikin; sabe lo que se hace... Por lo demás, tiempo tenéis de hablar de esto.\"},{\"heading\":false,\"text\":\"--¡Bravo!--gritó Razumikin--. Ahora, escuchen ustedes: hay aquí, en esta misma casa, un departamento completamente distinto e independiente del local en que se encuentran estas habitaciones; no cuesta caro y está amueblado... tres piezas pequeñas; aconsejo a ustedes que lo alquilen. Estarán allí muy bien; tanto más, cuanto que podrán ustedes vivir todos juntos; por supuesto, con Rodia... Pero, ¿a dónde vas, hombre?\"},{\"heading\":false,\"text\":\"--¡Cómo! ¿te vas ya?--preguntó con inquietud Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"--¿En un momento como éste?--gritó Razumikin.\"},{\"heading\":false,\"text\":\"Dunia miró a su hermano con sorpresa y desconfianza. El joven tenía la gorra en la mano, y se preparaba a salir.\"},{\"heading\":false,\"text\":\"--Cualquiera diría que se trataba de una separación eterna--exclamó con aire extraño.\"},{\"heading\":false,\"text\":\"Sonreía; ¡pero con qué risa!\"},{\"heading\":false,\"text\":\"--Después de todo, ¿quién sabe? Acaso sea ésta la última vez que nos vemos--añadió de repente.\"},{\"heading\":false,\"text\":\"Estas palabras brotaron espontáneamente de sus labios.\"},{\"heading\":false,\"text\":\"--Pero, ¿qué te pasa?--dijo ansiosamente la madre--. ¿A dónde vas, Rodia?--le preguntó dando a su pregunta un acento particular.\"},{\"heading\":false,\"text\":\"--Tengo que irme--respondió el joven.\"},{\"heading\":false,\"text\":\"Su voz era vacilante; pero su pálido rostro expresaba una firme resolución.\"},{\"heading\":false,\"text\":\"--Quería deciros al venir aquí... Quería deciros a ti, mamá, y a ti, Dunia, que debemos separarnos por algún tiempo. No me siento bien; tengo necesidad de reposo... Volveré más tarde. Volveré cuando me sea posible. Guardaré vuestro recuerdo, os amaré... Dejadme, dejadme solo... Era esa mi intención... Mi resolución era irrevocable... Ocúrrame lo que quiera, perdido o no, deseo estar solo. Olvidadme completamente. Esto es lo mejor... No procuréis tener noticias mías... cuando sea menester, yo vendré a vuestra casa u os llamaré. Quizá se arregle todo; pero hasta que esto suceda, si me amáis, renunciad a verme... De otro modo, os odiaré... comprendo que os odiaré... ¡Adiós!\"},{\"heading\":false,\"text\":\"--¡Dios mío! ¡Dios mío!--gimió Pulkeria Alexandrovna.\"},{\"heading\":false,\"text\":\"De las dos mujeres, así como de Razumikin, se apoderó un espanto terrible.\"},{\"heading\":false,\"text\":\"--¡Rodia, Rodia! ¡Reconcíliate con nosotras! ¡Sé lo que siempre fuiste!--gritaba la pobre madre.\"},{\"heading\":false,\"text\":\"Raskolnikoff se dirigió lentamente hacia la puerta, pero al llegar a ella se le acercó Dunia.\"},{\"heading\":false,\"text\":\"--¡Hermano mío! ¿Cómo puedes portarte así con nuestra madre?--murmuró la joven, cuya mirada llameaba de indignación.\"},{\"heading\":false,\"text\":\"Raskolnikoff hizo un esfuerzo para volver los ojos hacia ella.\"},{\"heading\":false,\"text\":\"--No es nada--musitó como hombre que no tiene plena conciencia de lo que dice, y salió de la sala.\"},{\"heading\":false,\"text\":\"--¡Egoísta! ¡Corazón duro y sin piedad!--gritó Dunia.\"},{\"heading\":false,\"text\":\"--¡No es egoísta; es un demente! ¡Está loco! ¡Le digo a usted que está loco! ¿Es posible que usted no lo haya visto? ¡Usted es la que no tiene piedad en este caso!--murmuró Razumikin, inclinándose al oído de la joven, cuya mano estrechó con fuerza--. Vuelvo en seguida--dijo a Pulkeria Alexandrovna, que estaba desvanecida, y se lanzó fuera del cuarto.\"},{\"heading\":false,\"text\":\"Raskolnikoff le esperaba en el corredor.\"},{\"heading\":false,\"text\":\"--Sabía que correrías detrás de mí--dijo--. Vuélvete con ellas, y no las dejes... Acompáñalas también mañana... y siempre. Yo... yo volveré quizá... si hay medio... Adiós.\"},{\"heading\":false,\"text\":\"Iba a alejarse sin dar la mano a Razumikin.\"},{\"heading\":false,\"text\":\"--¿Pero a dónde vas?--balbuceó este último asombrado--. ¿Qué tienes? ¿Cómo procedes de ese modo?\"},{\"heading\":false,\"text\":\"Raskolnikoff se detuvo de nuevo.\"},{\"heading\":false,\"text\":\"--Una vez para todas: no me interrogues más; nada he de responderte. No vuelvo a mi casa. Quizá venga alguna vez aquí. Déjame... Pero a ellas... _no las dejes_. ¿Me comprendes?\"},{\"heading\":false,\"text\":\"El corredor estaba obscuro; ambos amigos se encontraban cerca de una lámpara. Durante un minuto se miraron en silencio. Razumikin se acordó toda su vida de este minuto. La mirada fija e inflamante de Raskolnikoff parecía que intentaba penetrar hasta el fondo de su alma. De repente Razumikin se estremeció y se puso pálido como un cadáver. Acababa de comprender la horrible verdad.\"},{\"heading\":false,\"text\":\"--¿Comprendes ahora?--dijo de repente Raskolnikoff, cuyas facciones se alteraron horriblemente--. Vuelve al lado de ellas--añadió, y con paso rápido salió de la casa.\"},{\"heading\":false,\"text\":\"Inútil es describir la escena que se desarrolló a la entrada de Razumikin en el cuarto de Pulkeria Alexandrovna. Como se comprende fácilmente, el joven puso todo su cuidado en tranquilizar a las dos señoras. Les aseguró que Rodia, como estaba enfermo, necesitaba de reposo; les juró que no dejaría de ir a verlas, que le verían todos los días, que tenía una preocupación constante, que era preciso no irritarle; prometió velar por su amigo, confiarle a los cuidados de un buen médico, del mejor, y si era necesario, llamaría a consulta a los príncipes de la ciencia...\"},{\"heading\":false,\"text\":\"En una palabra, a partir de este día, Razumikin sería para ellas un hijo y un hermano.\"}]},{\"title\":\"cuarta parte — capítulo IV\",\"blocks\":[{\"heading\":false,\"text\":\"Raskolnikoff se dirigió derechamente al domicilio de Sonia.\"},{\"heading\":false,\"text\":\"La casa, de tres pisos, era un edificio viejo pintado de verde. El joven encontró, no sin trabajo, al _dvornik_, y obtuvo de él vagas indicaciones acerca del cuarto del sastre Kapernumoff. Después de haber descubierto en un rincón del patio la entrada de una escalera estrecha y sombría, subió al segundo piso y siguió la galería que daba frente al patio. Mientras andaba en la obscuridad, se preguntaba por dónde se podía entrar en casa de Kapernumoff. De pronto se abrió una puerta a tres pasos de él, y el joven tomó una de las hojas con un movimiento maquinal.\"},{\"heading\":false,\"text\":\"--¿Quién hay aquí?--preguntó una voz de mujer.\"},{\"heading\":false,\"text\":\"--Soy yo. Vengo a ver a usted--replicó Raskolnikoff, y penetró en una antesalita.\"},{\"heading\":false,\"text\":\"Allí, sobre una mala mesa, había una vela, colocada en un estropeado candelero de cobre.\"},{\"heading\":false,\"text\":\"--¡Es usted! ¡Dios mío!--dijo débilmente Sonia, que parecía no tener fuerzas para moverse de su sitio.\"},{\"heading\":false,\"text\":\"--¿Es éste su cuarto?--y Raskolnikoff entró vivamente en la sala, haciendo esfuerzos para no mirar a la joven.\"},{\"heading\":false,\"text\":\"Al cabo de un minuto, Sonia se le acercó y permaneció en pie delante de él, presa de una agitación inexplicable. Esta inesperada visita la turbaba y aun le daba miedo. De pronto su pálido rostro se coloreó y se le llenaron los ojos de lágrimas. Experimentaba una gran angustia, con la cual se mezclaba cierta dulzura. Raskolnikoff se volvió con un rápido movimiento, y se sentó en una silla cerca de una mesa. En un abrir y cerrar de ojos pudo inventariar todo lo que había en la estancia.\"},{\"heading\":false,\"text\":\"Esta sala grande, pero excesivamente baja, era la única alquilada por los Kapernumoff. En el muro de la izquierda había una puerta que comunicaba con la vivienda del sastre; del lado opuesto, en la pared de la derecha, había otra puerta, siempre cerrada: pertenecía a otro alojamiento. El cuarto de Sonia parecía un cobertizo cuadrilátero muy irregular, cuya forma le daba un aspecto monstruoso. La pared, con tres ventanas que daban al canal, la cortaba oblicuamente, formando así un ángulo extremadamente agudo, en el fondo del cual nada se veía, a causa de la débil luz de la vela. Por el contrario, el otro ángulo era desmesuradamente obtuso. Esta gran sala apenas tenía muebles: en el rincón de la derecha estaba la cama; entre la cama y la puerta, una silla; del mismo lado, y precisamente enfrente del alojamiento vecino, una mesa de madera blanca cubierta con un tapete azul, y al lado de ella dos sillas de junco. En la pared opuesta, cerca del ángulo agudo, había adosada una cómoda de madera sin barnizar que parecía perdida en el vacío. A esto se reducía todo el mobiliario. El papel, amarillento y viejo, tenía color obscuro en todos los rincones, efecto probable de la humedad y del humo del carbón. Todo aquel local denotaba pobreza: ni siquiera había cortinas en la cama.\"},{\"heading\":false,\"text\":\"Sonia miraba en silencio al visitante, que examinaba la habitación tan atentamente y de un modo tan despreocupado, que al fin la hizo temblar, como si se hallase delante del árbitro de su destino.\"},{\"heading\":false,\"text\":\"--Vengo a casa de usted por última vez--dijo tristemente Raskolnikoff como si se olvidase que era aquélla la primera que visitaba a la joven--. Quizás no nos volveremos a ver.\"},{\"heading\":false,\"text\":\"--¿Va usted a marcharse?\"},{\"heading\":false,\"text\":\"--No sé... mañana, todo...\"},{\"heading\":false,\"text\":\"--¿De modo que no irá usted mañana a casa de Catalina Ivanovna?--dijo Sonia con voz temblorosa.\"},{\"heading\":false,\"text\":\"--No sé. Mañana por la mañana todo... No se trata de eso. He venido para decirle dos palabras.\"},{\"heading\":false,\"text\":\"Levantó su mirada soñadora, y advirtió de repente que él estaba sentado mientras que ella permanecía derecha.\"},{\"heading\":false,\"text\":\"--¿Por qué está usted en pie? Siéntese--dijo con voz dulce y acariciadora.\"},{\"heading\":false,\"text\":\"La joven obedeció. Durante un minuto, Raskolnikoff la contempló con ojos benévolos y casi enternecidos.\"},{\"heading\":false,\"text\":\"--¡Qué delgada está usted! ¡Qué mano la suya! ¡Se ve la luz al través de ella! ¡Los dedos parecen los de una muerta!\"},{\"heading\":false,\"text\":\"Le tomó la mano.\"},{\"heading\":false,\"text\":\"Sonia se sonrió débilmente.\"},{\"heading\":false,\"text\":\"--Siempre he sido así--dijo.\"},{\"heading\":false,\"text\":\"--¿También cuando vivía usted en casa de sus padres?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--Es claro--dijo bruscamente.\"},{\"heading\":false,\"text\":\"Operóse de nuevo un repentino cambio en la expresión de su rostro y en el sonido de su voz.\"},{\"heading\":false,\"text\":\"Después dirigió una nueva mirada en derredor suyo.\"},{\"heading\":false,\"text\":\"--¿Vive usted en casa de Kapernumoff?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Viven ahí, detrás de esa puerta?\"},{\"heading\":false,\"text\":\"--Sí. Su habitación es completamente igual a ésta.\"},{\"heading\":false,\"text\":\"--¿No tienen más que una sala para todos?\"},{\"heading\":false,\"text\":\"--Nada más.\"},{\"heading\":false,\"text\":\"--Yo, en una habitación como ésta, tendría miedo por la noche--observó el joven con aire sombrío.\"},{\"heading\":false,\"text\":\"--Mis patrones son buenas personas, muy amables--respondió Sonia, que parecía no haber recobrado aún su presencia de espíritu--, y todo el mobiliario les pertenece. Son muy buenos. Sus hijos vienen muy a menudo a verme; los pobrecitos son tartamudos.\"},{\"heading\":false,\"text\":\"--¿Son tartamudos?\"},{\"heading\":false,\"text\":\"--Sí; el padre es tartamudo, y, además, cojo. La madre también. No es precisamente que tartamudee; pero tiene un defecto en la lengua. Es una mujer muy buena. Kapernumoff es un antiguo siervo. Tiene siete hijos. El mayor es el que tartamudea; los otros son enfermizos, pero hablan claro.\"},{\"heading\":false,\"text\":\"--Lo sabía.\"},{\"heading\":false,\"text\":\"--¿Que lo sabía usted?--exclamó Sonia sorprendida.\"},{\"heading\":false,\"text\":\"--Su padre de usted me lo contó hace tiempo. Supe por él toda la historia de usted. Me refirió que usted salió un día a las seis; que volvió a entrar a las ocho dadas, y que Catalina Ivanovna se puso de rodillas delante de la cama de usted.\"},{\"heading\":false,\"text\":\"Sonia se turbó.\"},{\"heading\":false,\"text\":\"--Creo haberle visto hoy--dijo titubeando.\"},{\"heading\":false,\"text\":\"--¿A quién?\"},{\"heading\":false,\"text\":\"--A mi padre. Yo estaba en la calle; en la esquina cerca de casa, entre nueve y diez. Parecía andar delante de mí. Hubiera jurado que era él. Quise ir a decírselo a Catalina Ivanovna, pero...\"},{\"heading\":false,\"text\":\"--¿Paseaba usted?\"},{\"heading\":false,\"text\":\"--Sí...--murmuró Sonia, bajando, avergonzada, los ojos.\"},{\"heading\":false,\"text\":\"--¿Catalina Ivanovna solía pegarla cuando estaba usted en casa de su padre?\"},{\"heading\":false,\"text\":\"--¡Oh, no! ¿Cómo dice usted eso? No--exclamó la joven mirando a Raskolnikoff con cierto espanto.\"},{\"heading\":false,\"text\":\"--¿De modo que usted la quiere?\"},{\"heading\":false,\"text\":\"--¿Cómo no?--repuso Sonia con voz lenta y plañidera. Después juntó bruscamente las manos con expresión de piedad--. ¡Ah, si usted...! ¡Si usted la conociese! Es lo mismo que una niña. Tiene el juicio extraviado por la desgracia. ¡Pero es tan inteligente! ¡Es tan buena y generosa! ¡Ah, si usted supiera!\"},{\"heading\":false,\"text\":\"Sonia dijo estas palabras con un acento casi desesperado. Su agitación era extraña; se acongojaba, se retorcía las manos. Sus pálidas mejillas se habían coloreado de nuevo y sus ojos revelaban un gran sufrimiento. Evidentemente acababa de herírsele una cuerda sensible y no podía menos de hablar, de disculpar a Catalina Ivanovna. De repente se manifestó en todos los rasgos de su fisonomía una expresión de piedad, por decirlo así, insaciable.\"},{\"heading\":false,\"text\":\"--¡Pegarme ella! ¿Qué dice usted, señor? ¡Pegarme ella!... Y, aun cuando me hubiera pegado, ¿qué? ¡si usted supiese! ¡Es tan desgraciada, y, además, está enferma!... Busca la justicia... Es pura... cree que en todo puede reinar la justicia, y clama por ella... La maltrataría usted, y ella no haría nada de injusto.\"},{\"heading\":false,\"text\":\"--Y usted, ¿qué va a hacer?\"},{\"heading\":false,\"text\":\"Sonia le interrogó con la mirada.\"},{\"heading\":false,\"text\":\"--Ahora han quedado a cargo de usted. Cierto que antes era lo mismo; el que ha muerto solía pedirle a usted dinero para ir a gastárselo a la taberna; pero ahora, ¿qué es lo que va a ocurrir?\"},{\"heading\":false,\"text\":\"--No sé--respondió la joven tristemente.\"},{\"heading\":false,\"text\":\"--¿Van a quedarse donde están?\"},{\"heading\":false,\"text\":\"--No sé. Deben a la patrona, y creo que ésta ha dicho hoy mismo que quería ponerlas en la calle. Mi madrastra, por su parte, dice que no ha de permanecer un momento más en aquella casa.\"},{\"heading\":false,\"text\":\"--¿En qué funda esa seguridad? ¿Piensa vivir a costa de usted?\"},{\"heading\":false,\"text\":\"--¡Oh, no! ¡no diga usted eso! Entre nosotras no hay mío ni tuyo; nuestros intereses son los mismos--replicó vivamente Sonia, cuya irritación en aquel instante se parecía a la inofensiva cólera de un pajarillo--. Por otra parte, ¿qué va a ser de ella?--añadió, animándose cada vez más--. ¡Cuánto ha llorado hoy! Tiene perturbado el juicio, ¿no lo ha notado usted? Tan pronto se preocupa febrilmente por lo que ha de hacer mañana, a fin de que todo esté bien, la comida y lo demás, como se retuerce las manos, escupe sangre, llora y se golpea, desesperada, la cabeza contra la pared. En seguida se consuela, pone su esperanza en usted, dice que será usted su sostén, habla de pedir dinero prestado en cualquier parte y de volverse a su ciudad natal conmigo. Allí, dice, fundará un pensionado de señoritas de la nobleza y me confiará la dirección de su establecimiento. «Una vida completamente nueva, una vida feliz comenzará para nosotras», me dice besándome. Estos pensamientos la consuelan. ¡Tiene tanta fe en sus quimeras! ¿Piensa usted que se la puede contradecir? Ha pasado todo el día de hoy lavando y arreglando el cuarto hasta que, rendida, se tuvo que echar en la cama. Luego fuimos de tiendas juntas; queríamos comprar calzado a Poletchka y a Lena, porque sus zapatos están inservibles. Desgraciadamente no teníamos bastante dinero; se necesitaba mucho, ¡y había elegido unos tan bonitos! Porque tiene muy buen gusto. ¡Usted no sabe...! Se echó a llorar allí en la tienda, delante del zapatero, porque no le alcanzaba el dinero... ¡Ah, qué triste era aquello!\"},{\"heading\":false,\"text\":\"--Vamos, se comprende después de esto que usted viva así--dijo Raskolnikoff con amarga sonrisa.\"},{\"heading\":false,\"text\":\"--Y usted, ¿no tiene piedad de ella?--exclamó Sonia--. Usted mismo, lo sé, se ha despojado por ella de sus últimos recursos, y, sin embargo, no ha visto usted nada. ¡Si lo hubiera visto todo! ¡Dios mío! ¡Cuántas veces, cuántas veces la he hecho llorar! La semana última, sin ir más lejos, ocho días antes de la muerte de mi padre... ¡Oh! ¡Cuánto me ha hecho sufrir durante todo el día este recuerdo!\"},{\"heading\":false,\"text\":\"Sonia se retorcía las manos; tan dolorosos le eran estos pensamientos.\"},{\"heading\":false,\"text\":\"--¿Ha sido usted dura con ella?\"},{\"heading\":false,\"text\":\"--Sí; yo, yo. Fuí a verla--continuó llorando--y mi padre me dijo: «Sonia, me duele algo la cabeza... Léeme algo, ahí tienes un libro.» Era un volumen perteneciente a Andrés Semenitch Lebeziatnikoff, el cual solía prestarnos libros muy divertidos. «Tengo que marcharme», le respondí yo. No tenía ganas de leer. Había entrado en la casa para enseñar a Catalina Ivanovna una compra que acababa de hacer. Isabel, la revendedora, me había traído unos cuellos y unos puños muy bonitos, con ramos, casi nuevos. Me costaron muy baratos. A Catalina Ivanovna le gustaron mucho; se los probó, mirándose al espejo, y los encontró preciosos. «Dámelos, Sonia; anda, dámelos», me dijo. No los necesitaba para nada, pero ella es así: se acuerda siempre de los tiempos felices de su juventud. Se contempla al espejo, y eso que no tiene ni vestidos ni nada desde hace no sé cuántos años. Por lo demás, nunca pide nada a nadie, porque es orgullosa, y antes que pedir daría cuanto posee; sin embargo, me pidió los cuellos casi llorando. A mí me costaba trabajo dárselos. «¿Para qué los quiere usted?», le dije. Sí, de ese modo le hablé. No debí decirle tal cosa. Me miró con aire tan afligido, que daba pena verla... y no era por los cuellos por lo que se entristecía, no; lo que la afligió fué mi negativa... ¡Ah, si yo pudiese ahora retirar todo lo dicho, hacer que todas aquellas palabras no hubieran sido pronunciadas!... ¡Oh, sí! Pero le estoy contando a usted lo que no le interesa.\"},{\"heading\":false,\"text\":\"--¿Conocía usted a la revendedora Isabel?\"},{\"heading\":false,\"text\":\"--Sí... ¿La conocía usted también?--preguntó Sonia un poco asombrada.\"},{\"heading\":false,\"text\":\"--Catalina Ivanovna está tísica en el último grado; morirá pronto--dijo Raskolnikoff después de una pausa, sin responder a la pregunta.\"},{\"heading\":false,\"text\":\"--¡Oh, no, no!\"},{\"heading\":false,\"text\":\"Y Sonia, inconsciente de lo que hacía, tomó las dos manos del joven, como si la suerte de Catalina Ivanovna hubiese dependido de él.\"},{\"heading\":false,\"text\":\"--Sería mejor que se muriese.\"},{\"heading\":false,\"text\":\"--No, no sería mejor. ¡Qué había de serlo!\"},{\"heading\":false,\"text\":\"--¿Y los niños? ¿Qué va a hacer usted de ellos, puesto que no puede tenerlos a su lado?\"},{\"heading\":false,\"text\":\"--¡Oh, no sé!--exclamó con acento angustiado la joven, apretándose la cabeza con las manos.\"},{\"heading\":false,\"text\":\"Era evidente que a menudo la había preocupado este pensamiento.\"},{\"heading\":false,\"text\":\"--Supongamos que Catalina Ivanovna viva todavía algún tiempo; pero puede usted caer enferma, y cuando la conduzcan al hospital, ¿qué sucederá entonces?--prosiguió implacablemente Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿Qué dice usted? ¿Qué dice usted?\"},{\"heading\":false,\"text\":\"El espanto demudó por completo el rostro de Sonia.\"},{\"heading\":false,\"text\":\"--¿Cree usted que es imposible?--repuso él con sonrisa sarcástica--. Supongo que no está usted asegurada contra las enfermedades. ¿Qué será entonces de ellos? Toda la familia se encontrará en el arroyo; la madre pedirá limosna, tosiendo y dando con la cabeza en las paredes, como hoy; los niños llorarán, Catalina Ivanovna caerá en medio de la calle, la llevarán al puesto de policía y de allí al hospital, y los niños quedarán sin amparo.\"},{\"heading\":false,\"text\":\"--¡Oh, no! ¡Dios no permitirá semejante horror!--exclamó Sonia con voz ahogada.\"},{\"heading\":false,\"text\":\"Hasta entonces había escuchado en silencio, con los ojos fijos en Raskolnikoff y las manos juntas como en muda plegaria para conjurar la desgracia que el joven predecía.\"},{\"heading\":false,\"text\":\"Raskolnikoff se levantó y se puso a pasear por la habitación. Pasó un minuto. Sonia seguía en pie con los brazos caídos y la cabeza baja presa de atroz sufrimiento.\"},{\"heading\":false,\"text\":\"--¿Y usted no puede hacer economías, ahorrar algún dinero para cuando lleguen los días tristes?--preguntó deteniéndose delante de ella.\"},{\"heading\":false,\"text\":\"--No--murmuró Sonia.\"},{\"heading\":false,\"text\":\"--No, naturalmente. ¿Pero lo ha procurado usted?--añadió con cierta ironía.\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Y no lo ha conseguido? Es claro, sí, se comprende. Inútil es preguntarlo.\"},{\"heading\":false,\"text\":\"Y volvió a pasearse por la habitación.\"},{\"heading\":false,\"text\":\"--Y... ¿no gana usted dinero todos los días?--preguntó al cabo de otro minuto de silencio.\"},{\"heading\":false,\"text\":\"Sonia se turbó más que nunca y sus mejillas se arrebolaron.\"},{\"heading\":false,\"text\":\"--No--respondió en voz baja haciendo un violento esfuerzo.\"},{\"heading\":false,\"text\":\"--La suerte de Poletchka será, indudablemente, la misma de usted--dijo el joven bruscamente.\"},{\"heading\":false,\"text\":\"--No, no; ¡eso es imposible!--exclamó Sonia, herida en el corazón por aquellas palabras como por una puñalada--. Dios... Dios no permitirá semejante abominación.\"},{\"heading\":false,\"text\":\"--Otras permite.\"},{\"heading\":false,\"text\":\"--No, Dios la protegerá--repitió enfáticamente Sonia.\"},{\"heading\":false,\"text\":\"--¿Y si no hay Dios?--replicó con acento de odio Raskolnikoff, y se echó a reír mirando a la muchacha.\"},{\"heading\":false,\"text\":\"La fisonomía de Sonia cambió repentinamente de expresión. Se le contrajeron los músculos y fijó en su interlocutor una mirada preñada de reproches; quiso hablar, pero no pudo articular palabra y rompió en sollozos, tapándose la cara con las manos.\"},{\"heading\":false,\"text\":\"--¿Dice usted que Catalina Ivanovna tiene el juicio perturbado? Y el de usted lo está también--dijo Raskolnikoff después de una pausa.\"},{\"heading\":false,\"text\":\"Pasaron cinco minutos. El joven continuaba paseando por la estancia sin hablar ni mirar a Sonia. Al fin se acercó a ella; tenía los ojos brillantes y los labios temblorosos; puso ambas manos sobre los hombros de la joven, fijó su ardiente mirada en ella, e inclinándose, de repente, le besó los pies. Sonia se echó atrás aterrada, como si estuviese delante de un loco. La fisonomía de Raskolnikoff en aquel momento parecía, en efecto, la de un demente.\"},{\"heading\":false,\"text\":\"--¿Qué hace usted? ¡A mí!--balbució Sonia palideciendo y con el corazón dolorosamente oprimido.\"},{\"heading\":false,\"text\":\"El joven se levantó en seguida.\"},{\"heading\":false,\"text\":\"--No es ante ti ante quien yo me prosterno, sino ante todo el sufrimiento humano--dijo con extraño acento, y fué a ponerse de codos en la ventana--. Escucha--prosiguió, acercándose a ella un momento después--; hace poco le he dicho a un insolente que no valía lo que tu dedo meñique y que yo había hecho a mi hermana el honor de sentarse a tu lado.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿Cómo ha podido usted decir eso? ¡y delante de ella!--exclamó Sonia asombrada--. ¡Sentarse a mi lado un honor! ¡Pero si yo soy una mujer deshonrada!... ¡Ah! ¡Por qué ha dicho usted eso!\"},{\"heading\":false,\"text\":\"--Al hablar así, no pensaba ni en tu deshonor, ni en tus faltas, sino en tus sufrimientos. Sin duda eres culpable--continuó diciendo Raskolnikoff con emoción creciente--; pero lo eres, sobre todo, por haberte inmolado inútilmente. Comprendo perfectamente que eres muy desgraciada: vivir en ese fango que tú detestas y saber al mismo tiempo (puesto que no puedes hacerte ilusiones sobre el particular) que tu sacrificio no sirve de nada y que no aprovechará a nadie... Pero dime--añadió exaltándose cada vez más--, ¿cómo con las delicadezas de tu alma te resignas a semejante oprobio? ¡Sería mejor arrojarse al agua y acabar de una vez!\"},{\"heading\":false,\"text\":\"--¿Y qué sería de ellos?--preguntó débilmente Sonia, levantando hasta él su mirada de mártir; pero al propio tiempo no parecía en modo alguno asombrada del consejo que se le daba.\"},{\"heading\":false,\"text\":\"Raskolnikoff la contempló con singular curiosidad. Esa sola mirada se lo explicó todo. Sin duda la joven había pensado muchas veces en el suicidio; muchas también, quizá, en el exceso de su desesperación, había pensado en acabar de una vez, y de tal manera y tan seriamente se preocupó con la misma idea, que al presente no experimentaba ninguna sorpresa al oír tal solución. No advirtió, sin embargo, la crueldad que encerraban estas palabras; escapósele también el sentido de los reproches del joven. Como ya se habrá comprendido, el punto de vista desde el cual consideraba él su deshonor era para ella letra muerta, y esto lo echó de ver Raskolnikoff. Se hacía cargo de cómo la torturaba la idea de su situación infamante, y se preguntaba qué había podido impedir que acabase con su vida. La única respuesta a tal pregunta era el cariño de Sonia por aquellos pequeñuelos y por Catalina Ivanovna, la desgraciada tísica y medio loca que se golpeaba la cabeza contra las paredes. Sin embargo, era evidente para él que la joven, con su carácter y educación, no podía permanecer así definidamente. Veía claramente que el caso de Sonia era un fenómeno social excepcional; pero esto, en rigor, era una razón de más para que la vergüenza la hubiese matado desde su entrada en un camino del cual debía alejarla todo su pasado de honradez, tanto como su cultura intelectual, relativamente elevada. ¿Qué era, pues, lo que la sostenía? ¿Era inclinación al vicio? No, su cuerpo únicamente se había entregado a aquella vida, el vicio no había penetrado en su alma; así lo comprendía Raskolnikoff, que leía como en libro abierto en el corazón de la joven.\"},{\"heading\":false,\"text\":\"«Su suerte está echada», pensaba. «Tiene delante de sí el canal, el manicomio o el embrutecimiento.»\"},{\"heading\":false,\"text\":\"Más que nada le repugnaba admitir la última probabilidad; pero su escepticismo le llevaba a considerarla como la más segura.\"},{\"heading\":false,\"text\":\"«¿Habrá de suceder así?», se preguntaba. «¿Es posible que esta criatura, que conserva todavía la pureza del alma, acabe por hundirse deliberadamente en el fango? Ha puesto ya los pies en él, y si hasta el presente ha podido soportar semejante vida, ¿es porque para ella el vicio ha perdido ya su aspecto repugnante? No, no; es imposible», exclamó para sí, como antes había exclamado Sonia. «No, lo que hasta este momento la ha impedido arrojarse al canal, es el temor de cometer un pecado y el interés que tiene por _ellos_. Si aun no se ha vuelto loca... ¿pero quién dice que no lo está? ¿Posee, acaso, todas sus facultades? ¿Razonaría una persona de juicio sano como ella razona? ¿Se puede afrontar la propia perdición con esa tranquilidad y sin prestar oídos a consejos o advertencias? ¿Es un milagro lo que espera? Sí, sin duda. ¿No son todos estos signos de enajenación mental?»\"},{\"heading\":false,\"text\":\"Se detenía obstinadamente en esta idea: «¡Sonia loca!» Esta perspectiva le desagradaba menos que cualquiera otra, y pensando en tales cosas se puso a examinar atentamente a la joven. De pronto le preguntó:\"},{\"heading\":false,\"text\":\"--¿De modo que ruegas mucho a Dios?\"},{\"heading\":false,\"text\":\"Ella callaba; en pie, a su lado, el joven esperaba una respuesta.\"},{\"heading\":false,\"text\":\"--¿Qué sería de mí sin Dios?--dijo en voz baja, pero enérgica, y dirigiendo a Raskolnikoff una rápida mirada de sus ojos brillantes, le estrechó la mano con fuerza.\"},{\"heading\":false,\"text\":\"«Vamos», pensó él, «no me engañaba».\"},{\"heading\":false,\"text\":\"--Pero, ¿qué es lo que Dios hace por ti?--preguntó, deseoso de esclarecer por completo sus dudas.\"},{\"heading\":false,\"text\":\"Sonia permaneció silenciosa, como si no hubiera podido responder; se le dilataba el pecho con la emoción.\"},{\"heading\":false,\"text\":\"--¡Calle usted, no me lo pregunte! ¡No tiene usted derecho!--exclamó, mirándole con cólera.\"},{\"heading\":false,\"text\":\"«Eso es, sí; eso es», pensó el joven.\"},{\"heading\":false,\"text\":\"--El lo hace todo--murmuró Sonia rápidamente, bajando los ojos al suelo.\"},{\"heading\":false,\"text\":\"«Ya está encontrada la explicación», afirmó mentalmente Raskolnikoff y miró a la joven con ávida curiosidad. Experimentaba una sensación nueva, extraña, casi dolorosa, contemplando aquella carita pálida, angulosa, delgada, con aquellos ojos tan azules y tan dulces que podían lanzar tales llamas y expresar una expresión tan vehemente, y aquel cuerpecito tembloroso de indignación y de cólera; todo aquello le parecía cada vez más extraño, casi fantástico. «¡Está loca! ¡Está loca!», repetía para sí.\"},{\"heading\":false,\"text\":\"Había un libro sobre la cómoda. Raskolnikoff habíase fijado en él varias veces durante sus idas y venidas por la habitación. Al fin lo tomó para examinarlo. Era una traducción rusa del Nuevo Testamento.\"},{\"heading\":false,\"text\":\"--¿Quién te ha dado esto?--preguntó a Sonia desde el otro lado de la habitación.\"},{\"heading\":false,\"text\":\"La joven, que no se había movido de su sitio, avanzó un paso y dijo:\"},{\"heading\":false,\"text\":\"--Me lo han prestado.\"},{\"heading\":false,\"text\":\"--¿Quién?\"},{\"heading\":false,\"text\":\"--Isabel; se lo pedí yo.\"},{\"heading\":false,\"text\":\"«¿Isabel? ¡Es extraño!», pensó él.\"},{\"heading\":false,\"text\":\"Todo en casa de Sonia tomaba a sus ojos un aspecto más extraordinario. Se aproximó a la luz con el libro y se puso a hojearlo.\"},{\"heading\":false,\"text\":\"--¿En qué parte habla de Lázaro?--preguntó bruscamente.\"},{\"heading\":false,\"text\":\"Sonia, con los ojos obstinadamente fijos en el suelo, guardó silencio. Se había separado un poco de la mesa.\"},{\"heading\":false,\"text\":\"--¿Dónde está la resurrección de Lázaro? Búscame ese pasaje, Sonia.\"},{\"heading\":false,\"text\":\"La joven miró con el rabillo del ojo a su interlocutor.\"},{\"heading\":false,\"text\":\"--No está ahí... Está en el cuarto Evangelio--dijo secamente sin moverse de su sitio.\"},{\"heading\":false,\"text\":\"--Busca ese pasaje y léemelo--dijo, y después se sentó, apoyó los codos en la mesa y la cabeza en la mano, y mirando de través con aire sombrío, se dispuso a escuchar.\"},{\"heading\":false,\"text\":\"Sonia vaciló al pronto dudando aproximarse a la mesa. El extraño deseo manifestado por Raskolnikoff le parecía poco sincero. Sin embargo, tomó el libro.\"},{\"heading\":false,\"text\":\"--¿Acaso no lo ha leído usted nunca?--preguntó, mirando al joven de soslayo.\"},{\"heading\":false,\"text\":\"--Sí... en mi niñez.\"},{\"heading\":false,\"text\":\"--¿No lo ha oído usted en la iglesia?\"},{\"heading\":false,\"text\":\"--Yo no voy a la iglesia. Y tú, ¿vas a menudo?\"},{\"heading\":false,\"text\":\"--No--balbució Sonia.\"},{\"heading\":false,\"text\":\"Raskolnikoff sonrió.\"},{\"heading\":false,\"text\":\"--Comprendo... ¿Entonces no asistirás mañana a las exequias de tu padre?\"},{\"heading\":false,\"text\":\"--Sí; la semana pasada estuve en la iglesia. Asistí a una misa de _Requiem_.\"},{\"heading\":false,\"text\":\"--¿Por quién?\"},{\"heading\":false,\"text\":\"--Por Isabel; la mataron a hachazos.\"},{\"heading\":false,\"text\":\"Los nervios de Raskolnikoff estaban cada vez más irritados y la cabeza se le iba.\"},{\"heading\":false,\"text\":\"--¿Tratabas a Isabel?\"},{\"heading\":false,\"text\":\"--Sí... Era buena, venía a mi casa... pero pocas veces, porque no era libre. Leíamos juntas y hablábamos. Ahora goza de la vista de Dios.\"},{\"heading\":false,\"text\":\"Raskolnikoff se quedó pensativo. ¿Qué significaban las misteriosas confidencias de dos idiotas como Sonia e Isabel?\"},{\"heading\":false,\"text\":\"«Aquí voy a volverme loco yo también. En esta habitación se respira la locura»--pensó--. ¡Lee!--gritó de repente con acento irritado.\"},{\"heading\":false,\"text\":\"Sonia seguía vacilando. Le latía con fuerza el corazón y parecía que le daba miedo leer. Raskolnikoff miró con expresión casi dolorosa a la pobre «loca».\"},{\"heading\":false,\"text\":\"--¿Qué le importa a usted eso si usted no cree?--murmuró con voz ahogada.\"},{\"heading\":false,\"text\":\"--Quiero que leas--insistió él--; bien le leías a Isabel...\"},{\"heading\":false,\"text\":\"Sonia abrió el libro y buscó el pasaje. Le temblaban las manos y las palabras se le atravesaban en la garganta. Dos veces Sonia trató de leer y no pudo articular la primera sílaba.\"},{\"heading\":false,\"text\":\"«Un hombre llamado Lázaro, de Bethania, estaba enfermo», profirió al fin, haciendo un esfuerzo; pero de repente, a la tercera palabra, su voz se hizo sibilante y se rompió como una cuerda demasiado tensa. Faltaba el aliento a su pecho oprimido.\"},{\"heading\":false,\"text\":\"Raskolnikoff se explicaba, en parte, la vacilación de Sonia para obedecerle, y a medida que comprendía mejor, reclamaba más imperiosamente la lectura; comprendía cuánto costaba a la joven descubrirle, en cierto modo, su interior. Evidentemente no podía, sin embargo, resolverse a hacer a un extraño la confidencia de los sentimientos que desde su adolescencia quizá la habían sostenido, que fueron, sin duda, su viático moral, cuando entre un padre borracho y una madrastra loca por la desgracia, en medio de los niños hambrientos, no oía más que reproches y clamores injuriosos. Veía todo esto; pero veía también que, a pesar de su repugnancia, tenía gran deseo de leer, sobre todo para él, «ocurriese lo que quisiera». Los ojos de la joven y la agitación que sentía, se lo dieron a conocer a Raskolnikoff... Por un violento esfuerzo sobre sí misma, Sonia dominó el espasmo que le apretaba la garganta, y continuó leyendo el undécimo capítulo del evangelio de San Juan, y llegó al versículo 19.\"},{\"heading\":false,\"text\":\"«Muchos judíos habían venido a Marta y a María a consolarlas de la muerte de su hermano. Entonces Marta, como oyó que Jesús venía, salió a su encuentro; pero María se estuvo en casa y Marta dijo a Jesús--: Señor, si hubieses estado aquí no fuera muerto mi hermano; mas yo sé ahora que todo lo que pidieres de Dios te dará Dios.»\"},{\"heading\":false,\"text\":\"La joven hizo aquí una pausa para triunfar de la emoción que hacía temblar de nuevo su voz...\"},{\"heading\":false,\"text\":\"«Dícele Jesús--: Tu hermano resucitará. Marta dijo--: Yo sé que resucitará en la resurrección en el día postrero. Dícele Jesús: _Yo soy la resurrección y la vida_; el que crea en Mí, aunque esté muerto, vivirá; y todo aquel que vive y cree en Mí, no morirá eternamente. ¿Crees tú en esto? Ella le dijo:»\"},{\"heading\":false,\"text\":\"(Aunque apenas podía respirar, Sonia levantó la voz, como si al leer las palabras de Marta hiciese ella misma su profesión de fe.)\"},{\"heading\":false,\"text\":\"«Sí, Señor; yo creo que Tú eres el Cristo, el Hijo de Dios que has venido al mundo.»\"},{\"heading\":false,\"text\":\"Sonia se interrumpió, levantó los ojos hasta él; pero los bajó en seguida y prosiguió la lectura. Raskolnikoff escuchaba sin pestañear, apoyado de codos sobre la mesa y mirando de lado. La joven continuó leyendo hasta el versículo 32.\"},{\"heading\":false,\"text\":\"«Mas María como vino donde estaba Jesús, viéndole derribóse a sus pies y le dijo--: Señor, si Tú hubieras estado aquí no fuera muerto mi hermano. Jesús entonces como que la vió llorando y que los judíos que habían venido con ella lloraban también, se conmovió en espíritu y turbóse y dijo--: ¿Dónde le pusisteis? Ellos le respondieron--: Señor, ven y verás. Y lloró Jesús. Y los judíos dijeron entonces--: Mirad cómo le amaba; y algunos dijeron--: ¿No podía éste, que abrió los ojos al ciego, hacer que éste no muriese?»\"},{\"heading\":false,\"text\":\"Raskolnikoff se volvió hacia ella y todo agitado la miró. Sí, era, efectivamente, lo que él había pensado. La joven estaba temblorosa y acometida de verdadera fiebre. Raskolnikoff lo había previsto. Sonia se aproximaba al milagroso relato y se apoderaba de ella un sentimiento de triunfo. Su voz, fortalecida por la alegría, tenía sonoridades metálicas. Las líneas se confundían ante sus ojos ofuscados; pero sabía de memoria este pasaje. En el último versículo, «no podía éste, que abrió los ojos al ciego...» bajó la voz dando un acento apasionado a la duda, al reproche de aquellos judíos incrédulos y ciegos, que un minuto después iban, como heridos del rayo, a caer de rodillas sollozando y creyendo... «Y él, él que es también un ciego, incrédulo; él también, dentro de un instante, oirá, creerá; sí... sí... en seguida... ahora mismo...», pensaba Sonia agitada por esta alegre confianza.\"},{\"heading\":false,\"text\":\"«Jesús, conmoviéndose otra vez en sí mismo, vino al sepulcro; era una cueva la cual tenía una piedra encima. Dice Jesús--: Quitad la piedra. Marta, hermana del muerto, le dice--: Señor, hiede ya, que es de cuatro días.»\"},{\"heading\":false,\"text\":\"Sonia subrayó la palabra cuatro.\"},{\"heading\":false,\"text\":\"«Jesús la respondió--: ¿No te he dicho que si crees verás la gloria de Dios? Entonces quitaron la piedra de donde el muerto había sido puesto, y Jesús, alzando los ojos al cielo, dijo en voz alta--: ¡Padre mío, gracias te doy porque me has oído; yo sabía que siempre me oyes, mas por causa de la compañía que está alrededor lo dije, para que crean que me has enviado! Y habiendo dicho estas palabras, exclamó a gran voz--: ¡Lázaro, ven fuera! y el que había muerto salió (al leer estas líneas Sonia temblaba como si hubiese sido testigo del milagro), con las manos atadas con vendas y el rostro envuelto en un sudario. Y dijo Jesús--: Desatadle y dejadle ir.\"},{\"heading\":false,\"text\":\"»_Entonces, muchos de los judíos que habían venido a María y habían visto lo que Jesús acababa de hacer, creyeron en El._»\"},{\"heading\":false,\"text\":\"La joven no leyó más; le hubiera sido imposible; cerró el libro y se levantó.\"},{\"heading\":false,\"text\":\"--Esto es todo lo que se refiere a la resurrección de Lázaro--dijo en voz baja y nerviosa sin volverse a Raskolnikoff.\"},{\"heading\":false,\"text\":\"Parecía que temiese encontrar su mirada. Su temor febril duraba todavía. El cabo de vela, que estaba para consumirse, alumbraba vagamente aquel cuartucho en que un asesino y una mujer pública acababan de leer juntos el Santo Libro. De repente Raskolnikoff se levantó y se acercó a Sonia.\"},{\"heading\":false,\"text\":\"--He venido para hablarte de una cosa--dijo en alta voz, frunciendo el entrecejo.\"},{\"heading\":false,\"text\":\"La joven levantó los ojos hasta él y vió que su mirada, de una dureza particular, expresaba una resolución feroz.\"},{\"heading\":false,\"text\":\"--Hoy--prosiguió--, he renunciado a todo género de relaciones con mi madre y con mi hermana. Ya no volveré más a mi casa. La ruptura entre los míos y yo está ya consumada.\"},{\"heading\":false,\"text\":\"--¿Por qué?--preguntó asombrada Sonia.\"},{\"heading\":false,\"text\":\"Su encuentro poco antes con Pulkeria Alexandrovna y Dunia, le había dejado una impresión extraordinaria, aunque obscura para ella. Al oír la noticia de que el joven había roto con su familia, sintió una especie de terror.\"},{\"heading\":false,\"text\":\"--Ahora no tengo en el mundo más que a ti--respondió él--. Partamos juntos. He venido a proponértelo. Tú y yo somos malditos; partamos juntos.\"},{\"heading\":false,\"text\":\"Le relampagueaban los ojos.\"},{\"heading\":false,\"text\":\"«Parece que está loco», pensó a su vez Sonia.\"},{\"heading\":false,\"text\":\"--¿A dónde iremos?--preguntó espantada, e involuntariamente se interrumpió.\"},{\"heading\":false,\"text\":\"--¿Cómo he de saberlo? Unicamente sé que el camino y el fin de él, son los mismos para ti y para mí; de eso estoy seguro.\"},{\"heading\":false,\"text\":\"Sonia le miró sin comprender. Una sola idea se desprendía claramente para ella de las palabras de Raskolnikoff: que era inmensamente desgraciado.\"},{\"heading\":false,\"text\":\"--Nadie te comprenderá si tú le hablas--prosiguió él--; pero yo te he comprendido. Tú me eres necesaria; por eso he venido.\"},{\"heading\":false,\"text\":\"--No comprendo...--balbució Sonia.\"},{\"heading\":false,\"text\":\"--Ya comprenderás más tarde. ¿Acaso tú no has procedido como yo? Tú también estás por encima de la regla... Has tenido ese valor. Has alzado la mano sobre ti, has destruído una vida, la tuya. Hubieras podido vivir para un espíritu, para la razón, y acabarás en el Mercado del Heno; pero tú no podrás soportarlo, y si te quedas sola perderás la razón y yo también la perderé. Ahora ya estás como loca. Es preciso, pues, que marchemos juntos; que sigamos el mismo camino. Partamos.\"},{\"heading\":false,\"text\":\"--¿Por qué? ¿Por qué dice usted eso?--repuso Sonia extrañamente turbada por tal lenguaje.\"},{\"heading\":false,\"text\":\"--¿Por qué? ¡Porque tú no puedes quedarte aquí! Es menester razonar seriamente y ver las cosas bajo su verdadero aspecto, en vez de llorar como un niño y de confiarlo todo a Dios. ¿Qué ocurrirá, te pregunto yo ahora, si mañana se te conduce al hospital? Catalina Ivanovna, casi loca y tísica, morirá pronto. ¿Qué será de sus hijos? La perdición de Poletchka, ¿no es cosa segura?\"},{\"heading\":false,\"text\":\"--¿Qué hacer, pues? ¿Qué hacer?--repitió llorando Sonia y retorciéndose las manos.\"},{\"heading\":false,\"text\":\"--¿Qué hacer? Hay que levar el ancla de una vez para ir adelante, ocurra lo que quiera. ¿No comprendes? Más tarde comprenderás... La libertad y el poder, pero sobre todo el poder, reinan sobre todas las criaturas temblorosas, sobre todo el hormiguero. He ahí el objeto. Acuérdate de esto. Ese es el testamento que te dejo. Quizá te hablo por última vez. Si no vengo mañana lo sabrás todo, y entonces acuérdate de lo que te digo. Más tarde, dentro de algunos años, con la experiencia de la vida, comprenderás acaso lo que significan mis palabras. Si vengo mañana, te diré quién es el que ha matado a Isabel.\"},{\"heading\":false,\"text\":\"--Pero, ¿es que usted sabe quién la ha matado?--preguntó la joven helada de espanto.\"},{\"heading\":false,\"text\":\"--Lo sé y lo diré... pero a ti, a ti sola. Te he elegido. No vendré a pedirte perdón sino simplemente a decírtelo. Hace mucho tiempo que te he elegido; desde el momento que tu padre me habló de ti; viviendo aún Isabel se me ocurrió esta idea. Adiós. No me des la mano. Hasta mañana.\"},{\"heading\":false,\"text\":\"Raskolnikoff salió, dejando a Sonia la impresión de que estaba loco; pero ella estaba también como loca y se daba cuenta de su estado; se le iba la cabeza.\"},{\"heading\":false,\"text\":\"--Señor, ¿cómo sabe quién ha matado a Isabel? ¿Qué significan sus palabras? ¡Qué extraño es!\"},{\"heading\":false,\"text\":\"Sin embargo, no tuvo la menor sospecha de la verdad.\"},{\"heading\":false,\"text\":\"--¡Oh! ¡Debe de ser inmensamente desgraciado! Se ha separado de su madre y de su hermana; ¿por qué? ¿qué ha podido pasarle? ¿Cuáles son sus intenciones? ¿Qué es lo que me ha dicho? Me ha besado el pie diciéndome (sí, de ese modo se ha expresado), que no podía vivir sin mí... ¡Oh Señor!\"},{\"heading\":false,\"text\":\"Detrás de la puerta que permanecía siempre cerrada, había una habitación sin ocupar, desde hacía largo tiempo, que pertenecía a la casa de Gertrudis Karlovna Reslich. Esta habitación se alquilaba, como lo indicaban un rótulo colocado en el exterior de la puerta grande y los albaranes colocados en las ventanas que daban al canal. Sonia sabía que no vivía nadie allí. Pero, durante toda la escena precedente, el señor Svidrigailoff, oculto detrás de la puerta, no había perdido sílaba de la conversación. Cuando Raskolnikoff hubo salido, el inquilino de la señora Reslich reflexionó un momento; después volvió a entrar sin ruido en su habitación, que estaba contigua a la pieza desalquilada, tomó una silla y fué a colocarla junto a la puerta. Lo que acababa de oír le interesaba en el más alto grado; así es que llevaba aquella silla para poder escuchar la conversación prometida para el día siguiente, sin verse obligado a permanecer de pie durante una hora por lo menos.\"}]},{\"title\":\"cuarta parte — capítulo V\",\"blocks\":[{\"heading\":false,\"text\":\"Cuando al día siguiente, a las once en punto, Raskolnikoff se presentó en casa del juez de instrucción, se asombró de haber tenido que hacer antesala tanto tiempo. Según sus presunciones, debiera habérsele recibido en seguida; sin embargo, pasaron diez minutos antes de ver a Porfirio Petrovitch. En la sala de entrada, en que esperó primero, varias personas iban y venían sin parecer que reparasen en él. En la habitación siguiente, que se asemejaba a una Cancillería, trabajaban algunos escribientes y saltaba a la vista que ninguno de ellos sospechaba en lo más mínimo lo que pudiera ser Raskolnikoff.\"},{\"heading\":false,\"text\":\"El joven miró en su derredor con desconfianza. ¿Habría allí algún esbirro, algún _Argos_ misterioso encargado de vigilarle, y en el caso oportuno impedir su fuga? Nada de esto descubría; los escribientes estaban todos ocupados en sus tareas y los otros no hacían el menor caso de él. El visitante se iba tranquilizando.\"},{\"heading\":false,\"text\":\"--Si, en efecto, aquel misterioso personaje de ayer, aquel espectro salido de debajo de la tierra, lo supiese todo y lo hubiese visto todo, ¿me dejarían tanto tiempo libre? ¿No me hubieran detenido ya, en vez de esperar que viniese aquí por mi propia voluntad? Siendo esto así, o ese hombre no ha hecho ninguna revelación contra mí, o... sencillamente no sabe nada y no ha visto nada... Y, en rigor, ¿cómo hubiera podido ver? Por consiguiente, he debido estar alucinado, y lo que ayer me ocurrió no fué más que una ilusión de mi imaginación enferma.\"},{\"heading\":false,\"text\":\"Cada vez encontraba más verosímil esta explicación, que ya el día antes se le había ocurrido cuando más inquieto estaba.\"},{\"heading\":false,\"text\":\"Reflexionando en todo esto y preparándose para una nueva lucha, Raskolnikoff advirtió de repente que estaba temblando y hasta se indignó ante el pensamiento de que lo que le hacía temblar era el miedo de una entrevista con el odioso Porfirio Petrovitch. Lo más terrible para él era encontrarse de nuevo en presencia de aquel hombre; le odiaba terriblemente y hasta temía venderse a causa de aquel odio. Se apresuró a entrar con aire frío y tranquilo, y se prometió hablar lo menos posible, estar siempre alerta y dominar, en fin, a toda costa, su temperamento irascible. Pensando en tales cosas, fué introducido en el despacho de Porfirio Petrovitch.\"},{\"heading\":false,\"text\":\"Encontrábase éste solo en su gabinete. Esta habitación, de no muchas dimensiones, contenía una gran mesa colocada frente a un diván forrado de hule, un escritorio, un armario colocado en un rincón y varias sillas; todo este mobiliario, suministrado por el Estado, era de madera amarilla. En la pared del fondo había una puerta cerrada, lo que hacía suponer que había otras habitaciones detrás del tabique.\"},{\"heading\":false,\"text\":\"En cuanto Porfirio Petrovitch vió que Raskolnikoff entraba en su gabinete, fué a cerrar la puerta por la cual acababa de entrar el joven, y ambos quedaron frente a frente. El juez de instrucción dispensó a su visitante una acogida en la apariencia por extremo risueña y afable. Al cabo de algunos minutos advirtió Raskolnikoff ciertos movimientos que revelaban ligera contrariedad en el magistrado; parecía que acababa de interrumpírsele en alguna ocupación clandestina.\"},{\"heading\":false,\"text\":\"--¡Ah, respetabilísimo! Ya está usted aquí... en nuestros dominios--comenzó a decir Porfirio Petrovitch tendiéndole ambas manos--. Vamos, siéntese usted, _batuchka_. Pero quizá no le guste a usted que se le llame respetabilísimo y al mismo tiempo _batuchka_, _tout court_. No lo tome usted a mal; no es una familiaridad excesiva... Siéntese... aquí, en el diván.\"},{\"heading\":false,\"text\":\"Raskolnikoff se sentó, sin apartar los ojos del juez de instrucción.\"},{\"heading\":false,\"text\":\"«Estas palabras «en nuestros dominios», estas excusas por su familiaridad, la expresión francesa _tout court_... ¿qué quiere decir todo esto? Me ha alargado las manos sin darme ninguna; las ha retirado a tiempo», pensó Raskolnikoff con desconfianza.\"},{\"heading\":false,\"text\":\"Ambos se observaban; pero cuando se encontraban sus miradas, apartaban el uno del otro los ojos con la rapidez del relámpago.\"},{\"heading\":false,\"text\":\"--He venido a traer este papel... con motivo del reloj... Tome usted. ¿Está bien así, o hay que escribir otro?\"},{\"heading\":false,\"text\":\"--¿Qué? ¿Qué papel? ¡Ah, sí!... ¡No se preocupe usted; está bien!--respondió con precipitación Porfirio, que pronunció estas palabras aun antes de haber examinado el papel, y después, cuando hubo echado una rápida mirada sobre el documento, añadió--: Sí, está bien; basta con esto--continuó, hablando siempre de prisa, y depositó el papel sobre la mesa.\"},{\"heading\":false,\"text\":\"Un minuto después lo guardó en el escritorio, hablando de otra cosa.\"},{\"heading\":false,\"text\":\"--Me parece que ayer me manifestó usted deseos de interrogarme... en debida forma, a propósito de mis relaciones con la... víctima.\"},{\"heading\":false,\"text\":\"«Vamos, ¿para qué habré dicho yo _me parece_?», pensó de repente Raskolnikoff. «¿Qué importa esa frase? ¿Por qué me he de inquietar yo por ella?», añadió mentalmente y casi al mismo tiempo.\"},{\"heading\":false,\"text\":\"Por el solo hecho de encontrarse en presencia de Porfirio, con quien apenas había cambiado dos palabras, su desconfianza tomaba enormes proporciones, y advirtió súbitamente que esta disposición de ánimo era demasiado peligrosa; su agitación y la exaltación de sus nervios iban en aumento.\"},{\"heading\":false,\"text\":\"«Malo, malo; se me va a escapar alguna tontería.»\"},{\"heading\":false,\"text\":\"--Sí, sí; no se inquiete usted, tenemos tiempo, tenemos tiempo--murmuró Porfirio Petrovitch, que sin intención alguna aparente iba y venía por la habitación, aproximándose, ya a la ventana, ya al escritorio, para acercarse en seguida a la mesa.\"},{\"heading\":false,\"text\":\"Algunas veces evitaba las recelosas miradas de Raskolnikoff; otras se detenía bruscamente y miraba a su interlocutor cara a cara.\"},{\"heading\":false,\"text\":\"Era un espectáculo verdaderamente extraño el que ofrecía en tal momento aquel hombrecillo grueso y redondo, que se movía como una pelota lanzada de una pared a otra.\"},{\"heading\":false,\"text\":\"--No hay prisa, no hay prisa. ¿Fuma usted? Tome un cigarrillo--continuó ofreciendo un paquete al visitante--. Le recibo aquí, ¿sabe usted?; pero mi habitación está ahí, detrás de ese tabique... Es el Estado quien me la suministra... yo estoy aquí provisionalmente, porque hay muchos arreglos que hacer en mi vivienda. Ahora todo está arreglado o poco menos... ¿Sabe usted que es una gran cosa que el Estado le dé a uno casa? ¿No le parece a usted?\"},{\"heading\":false,\"text\":\"--Sí, una gran cosa--respondió Raskolnikoff mirándole con aire burlón.\"},{\"heading\":false,\"text\":\"--Una gran cosa... una gran cosa...--repitió ocupado en otra parte--. ¡Sí, una gran cosa!--volvió a decir bruscamente con voz casi tonante, deteniéndose a dos pasos de Raskolnikoff, a quien miró de repente.\"},{\"heading\":false,\"text\":\"La incesante y necia repetición de esta frase: «Una habitación suministrada por el Estado es una gran cosa», contrastaba por su vacuidad con la mirada seria, profunda, enigmática, que el juez fijaba ahora en su visitante.\"},{\"heading\":false,\"text\":\"La cólera de Raskolnikoff no le impidió dirigir al juez de instrucción un desafío burlón y bastante imprudente.\"},{\"heading\":false,\"text\":\"--¿Sabe usted--comenzó a decir, mirándole casi con insolencia y complaciéndose en ello--, que es, según creo, una regla jurídica, un principio para todos los jueces de instrucción, ponerse a hablar de cosas insignificantes o de una cosa seria, pero ajena a la cuestión, a fin de animar a aquellos a quienes interrogan, o más bien a fin de distraerlos aletargando su prudencia, y después, bruscamente, de improviso, descargarles en medio de la coronilla la más peligrosa pregunta? ¿No es así? ¿No es una costumbre religiosamente observada en la profesión de usted?\"},{\"heading\":false,\"text\":\"--¿De modo que usted supone que si le he hablado tantas veces de la casa que me da el Estado, ha sido para...?\"},{\"heading\":false,\"text\":\"Al decir esto, Porfirio Petrovitch guiñó los ojos y dió a su cara, por un instante, cierta expresión de alegría maliciosa, se borraron las leves arrugas de su frente, se le pusieron los ojos todavía más pequeños de lo que eran, se dilataron sus facciones, y mirando fijamente a Raskolnikoff, se echó a reír de un modo nervioso y prolongado, que agitó toda su persona. El joven se echó a reír también, aunque haciendo un violento esfuerzo. La hilaridad de Porfirio Petrovitch redobló de tal modo, que el rostro del juez de instrucción se puso de color carmesí. Raskolnikoff experimentó entonces un disgusto que le hizo olvidar toda prudencia; cesó de reír, frunció el entrecejo, y durante todo el tiempo en que siguió riendo Porfirio con aquella alegría que parecía un poco fingida, clavó en él unas miradas preñadas de odio. El juez, por su parte, se cuidaba muy poco del descontento de Raskolnikoff. Esta última circunstancia dió mucho que pensar al joven; creyó comprender que su llegada no había interrumpido lo más mínimo al juez de instrucción; era, por el contrario, él, Raskolnikoff, el que había caído en una trampa. Evidentemente había allí algún lazo, alguna emboscada que él no conocía; la mina estaba cargada quizá, e iba a reventar de un momento a otro.\"},{\"heading\":false,\"text\":\"Yéndose derecho al asunto, se levantó y tomó su gorra.\"},{\"heading\":false,\"text\":\"--Porfirio Petrovitch--dijo con tono resuelto, pero en el que se descubría bastante irritación--, ayer manifestó usted el deseo de hacerme sufrir un interrogatorio. (Subrayó la palabra _interrogatorio_.) He venido a ponerme a disposición de usted; si tiene preguntas que dirigirme, pregúnteme usted, si no, permítame que me retire. No puedo perder el tiempo aquí; tengo otra cosa que hacer. He de asistir al entierro de ese funcionario que ha sido atropellado por un coche y de quien ha oído usted hablar...--añadió, y en seguida se arrepintió de haber dicho esta frase--. Después--prosiguió con cólera creciente--, todo eso me fastidia, ¿entiende usted? hace mucho tiempo que dura todo esto, y en parte ha sido causa de mi enfermedad... En una palabra--continuó con voz cada vez más irritada porque comprendía que la frase acerca de su enfermedad era aún más inoportuna que la otra--, en una palabra, o me interroga usted, o permita que me marche ahora mismo... Pero si usted me interroga, que sea en la forma establecida por el procedimiento legal; de otro modo no se lo permitiré a usted, y hasta entonces, adiós, puesto que por el momento nada tenemos que hacer juntos.\"},{\"heading\":false,\"text\":\"--¡Señor! ¿Pero, qué está usted diciendo? ¿Acerca de qué he de interrogar a usted?--replicó el juez de instrucción, que cesó instantáneamente de reír--; no se inquiete usted, se lo suplico.\"},{\"heading\":false,\"text\":\"Incitó a Raskolnikoff a que se sentara, en tanto que él iba y venía de un lado a otro de la habitación.\"},{\"heading\":false,\"text\":\"--Tenemos tiempo, tenemos tiempo, y todo eso carece de importancia. Por el contrario, estoy tan contento de que haya usted venido a nuestra casa... Recibo a usted como a un visitante... En cuanto a ese maldito reír, _batuchka_ Rodión Romanovitch, perdóneme usted... soy muy nervioso y me ha hecho mucha gracia la agudeza de la observación de usted; a veces, le aseguro que me pongo a saltar como una pelota de goma y estoy así durante media hora... Me gusta reír. Mi temperamento me hace temer una apoplejía. Pero siéntese usted, ¿por qué sigue en pie?... Se lo ruego, _batuchka_, de lo contrario creeré que está usted enfadado.\"},{\"heading\":false,\"text\":\"Raskolnikoff, con el entrecejo fruncido, se callaba, escuchaba y observaba; sin embargo, se sentó.\"},{\"heading\":false,\"text\":\"--Por lo que a mí toca, _batuchka_ Rodión Romanovitch, diré a usted una cosa que servirá para explicarle mi carácter--repuso Porfirio Petrovitch, que continuaba yendo y viniendo por la habitación, y seguía evitando el cruzar la mirada con la del joven--. Yo vivo solo, ¿sabe usted? No voy a ninguna parte; soy desconocido. Añada usted que estoy en la decadencia ya acabado... y... ¿ha advertido usted, Rodión Romanovitch, que entre nosotros, es decir, en Rusia, y sobre todo en nuestros círculos de San Petersburgo, cuando se encuentran dos hombres inteligentes que no se conocen aún bien, pero que recíprocamente se estiman, como usted y yo, por ejemplo, en este momento, no pueden decirse una palabra durante media hora y permanecen como petrificados, el uno frente al otro? Todo el mundo tiene materia de conversación; las señoras, la gente de mundo, las personas de alta sociedad... en todos estos ambientes hay de qué hablar, es de rigor; pero las personas de la clase media, como nosotros, son hurañas y taciturnas. ¿De qué procede esto, _batuchka_? ¿No tenemos nosotros intereses sociales, o es que somos demasiado honrados para engañarnos unos a otros? No lo sé. Vamos a ver, ¿cuál es su opinión? Pero deje la gorra; cualquiera diría que desea usted irse, y eso me causa pena... yo, por el contrario, tengo tanto gusto...\"},{\"heading\":false,\"text\":\"Raskolnikoff dejó su gorra. No salía de su mutismo, y con las cejas fruncidas seguía oyendo la vana charla de Porfirio.\"},{\"heading\":false,\"text\":\"«Sin duda dice todas estas tonterías para distraer mi atención.»\"},{\"heading\":false,\"text\":\"--No le ofrezco a usted café, porque éste no es lugar para ello; pero, ¿no será posible pasar cinco minutos con un amigo para procurarle una distracción?--prosiguió el inagotable Porfirio--. Ya sabe usted cuántas son las obligaciones del servicio. No se enoje usted, _batuchka_, porque siga paseándome; perdóneme usted, sentiría mucho molestarle; ¡pero me es tan necesario el movimiento!... Estoy siempre sentado y es para mí un verdadero placer poder pasearme durante cinco minutos... padezco de hemorroides. He tenido siempre intención de tratarme por la gimnasia; el trapecio es, se dice, muy provechoso para los consejeros del Estado, y aun para los consejeros íntimos. En nuestros días, la gimnástica ha venido a ser una verdadera ciencia... En cuanto a los deberes de nuestro cargo, a estos interrogatorios y todo este formalismo, usted mismo, _batuchka_, hablaba hace poco... ¿Sabe usted, en efecto, _batuchka_ Rodión Romanovitch, que estos interrogatorios despistan más al magistrado que al reo?... Usted lo ha hecho notar hace un momento, con tanto ingenio como exactitud. (Raskolnikoff no había hecho semejante observación.) Se embrolla uno, pierde el hilo. En cuanto a nuestras costumbres jurídicas, estoy plenamente de acuerdo con usted. ¿Cuál es, dice usted, el acusado, aunque sea el más obtuso _mujik_, que ignore que ha de comenzarse por hacérsele preguntas extrañas para aletargarle, según la feliz expresión de usted, a fin de asestarle después, bruscamente, un hachazo en medio de la coronilla (sirviéndome de la feliz metáfora de usted)? ¡Je, je! De modo que ha pensado que hablándole de la habitación, yo trataba... ¡je, je! Es usted muy cáustico... vamos, ya no insisto. ¡Ah! Sí, una palabra llama a otra; los pensamientos se atraen mutuamente. Hace un momento hablaba usted de la forma en lo que concierne al magistrado. ¿Pero, qué es la forma? Ya sabe usted que, en muchos casos, una simple conversación amistosa conduce más seguramente a ciertos resultados. La forma no desaparecerá jamás, permítame usted que se lo asegure; ¿pero qué es, en el fondo, la forma? No se puede obligar al juez de instrucción a que la traiga siempre a cuestas. La necesidad del investigador es, en su género, un arte liberal o alguna cosa por el estilo. ¡Je, je!\"},{\"heading\":false,\"text\":\"Porfirio Petrovitch se detuvo un instante para tomar aliento. Hablaba sin interrupción, tan pronto diciendo tonterías, como deslizando, en medio de estas necedades, frasecillas enigmáticas, después de las cuales comenzaba de nuevo con sus trivialidades. Su paseo ahora por la habitación se parecía a una carrera; movía sus gruesas piernas cada vez con más viveza y continuaba con los ojos bajos, la mano derecha metida en el bolsillo, en tanto que con la izquierda hacía incesantemente ademanes que no tenían ninguna relación con sus palabras. Raskolnikoff advirtió, o creyó advertir, que al ir y venir por la habitación, el juez se había detenido dos veces cerca de la puerta como para escuchar un instante... «Sin duda espera algo.»\"},{\"heading\":false,\"text\":\"--Tiene usted completa razón--siguió diciendo alegremente Porfirio, mirando al joven con una candidez que puso a éste en nueva desconfianza--; nuestras costumbres jurídicas merecen, en efecto, las burlas ingeniosas de usted. ¡Je, je! Estos procedimientos, inspirados, según se pretende, por una profunda psicología, son muy ridículos y aun a menudo estériles. Volviendo de nuevo a la forma: Supongamos que yo me encargo de la instrucción de un proceso; yo sé, o más bien creo saber, que el culpable es cierto señor... ¿No estaba usted siguiendo la carrera de Derecho, Rodión Romanovitch?\"},{\"heading\":false,\"text\":\"--Sí; la estudiaba.\"},{\"heading\":false,\"text\":\"--Pues bien, he aquí un ejemplo que podrá servirle a usted más adelante; no vaya a creer que trato de echármelas de profesor con usted; no permita Dios que pretenda yo enseñar una cosa a un hombre que trata en los periódicos las cuestiones de criminalidad; no, me tomo solamente la libertad de citarle un hecho a título de ejemplo. Supongo, pues, que he creído descubrir al culpable; dígame usted ahora: ¿había de inquietarle prematuramente, aunque poseyera pruebas contra él? Acaso a otro que no tuviese el mismo carácter, le haría detener en seguida; pero a éste, ¿por qué no dejarle que se pasee un poco por la ciudad? ¡Je, je! No, veo que usted no me comprende bien; voy a explicarme más claramente. Si, por ejemplo, me apresuro a dictar un auto de prisión contra él, merced a este solo hecho le suministro, por decirlo así, un punto de apoyo moral. ¡Je, je! ¿Se ríe usted? (Raskolnikoff no pensaba en reírse; tenía los labios apretados y no apartaba su ardiente mirada de los ojos de Porfirio Petrovitch.) Sin embargo, así se hace, porque las personas son muy diversas, aunque, desgraciadamente, el procedimiento sea el mismo para todas. Pero desde el momento que tiene usted pruebas, podrá decirme usted, ¿para qué todas esas precauciones? ¡Ah, Dios mío! _Batuchka_, ¿sabe usted lo que son pruebas? Las tres cuartas partes de las veces, las pruebas son armas de dos filos, y, yo, juez de instrucción, soy hombre y, por consiguiente, sujeto a error. Así, pues, quisiera dar a mis investigaciones el rigor absoluto de una demostración matemática y desearía que mis conclusiones fuesen tan claras, tan indiscutibles, como dos y dos son cuatro. De modo que si yo hago detener a ese señor antes del tiempo oportuno, estando bien convencido de que es _él_, me privo de los medios ulteriores de establecer su culpabilidad. ¿Y por qué? Pues porque le doy, en cierto modo, una situación definida; al ponerle en la cárcel le tranquilizo, le coloco en su verdadero equilibrio psicológico; entonces se me escapa, se repliega sobre sí mismo, y comprende que es un detenido. Si por el contrario, dejo perfectamente tranquilo al presunto culpable, si no le detengo y si no le inquieto, pero a todas horas está preocupado de que lo sé todo, de que no le pierdo de vista ni de día ni de noche, de que es objeto por mi parte de una infatigable vigilancia, ¿qué es lo que sucederá en semejantes condiciones? Que infaliblemente se sentirá acometido del vértigo, vendrá él mismo a mi casa, me suministrará buen número de armas contra él, y me pondrá en el caso de dar a las conclusiones de mi investigación un carácter de evidencia matemática que no carece de encantos. Si este procedimiento puede dar resultados eficaces con un _mujik_ inculto, es también muy eficaz cuando se trata de un hombre muy ilustrado, inteligente, y en cierto modo distinguido. Porque lo importante, mi querido amigo, es adivinar en qué sentido está desarrollado un hombre. Supongamos que se trata de uno inteligente, pero que tiene nervios, nervios que están excitados, que son enfermizos... ¡Y la bilis! La bilis que no se tiene en cuenta, ¡qué papel, sin embargo, tan importante desempeña en todas esas personas! Se lo repito a usted: hay en esto una verdadera mina de indicios. ¿Qué me importa que se pasee en libertad por la ciudad? Puedo dejarle gozar un poco más, seguro de que la presa no se me escapará. Y, en efecto, ¿a dónde podría ir? ¿Al extranjero? Un polaco huiría al extranjero, pero él no; tanto más, que yo le vigilo, y tengo, por consiguiente, tomadas mis medidas. ¿Se retirará al interior del país? Allí habitan _mujiks_ groseros, rusos primitivos, desprovistos de civilización; este hombre ilustrado querrá mejor estar preso que vivir en tal ambiente. ¡Je, je! Por otra parte, esto no significa nada todavía; es lo accesorio, el lado exterior de la cuestión. No huirá, no solamente porque no sabría dónde ir, sino porque, y sobre todo, me pertenece psicológicamente. ¡Je, je, je! ¿Qué le parece a usted de esta expresión? En virtud de una ley natural, no huirá, aunque pueda hacerlo. ¿Ha visto usted la mariposa delante de la luz? Pues bien: él dará sin cesar vueltas en derredor mío, como ese insecto en torno de la llama. Para él no tendrá goces la libertad, cada vez estará más inquieto, cada vez más trastornado; si le doy tiempo, se entregará a actos tales que su culpabilidad aparecerá clara como dos y dos son cuatro... y siempre, siempre, dará vueltas en derredor mío, describiendo círculos cada vez más pequeños, hasta que, por último, ¡paf! se meterá él mismo en la boca y me lo tragaré. Es esto muy divertido. ¡Je, je, je! ¿No le parece a usted?\"},{\"heading\":false,\"text\":\"Raskolnikoff guardaba silencio. Pálido e inmóvil, continuaba observando el rostro de Porfirio con un penoso esfuerzo de atención.\"},{\"heading\":false,\"text\":\"«La lección es buena--pensaba aterrado--; no es, como ayer, el gato jugando con el ratón. Sin duda, al hablarme así, no es solamente por placer de mostrarme su fuerza; es demasiado inteligente para eso. Debe de tener otro objeto. ¿Cuál es? ¡Bah! amigo mío, cuanto dices es para asustarme. No tienes pruebas, y el hombre de ayer no existe. Tratas sencillamente de desconcertarme, quieres encolerizarme y dar el gran golpe cuando me veas en ese estado; pero te engañas; pierdes el tiempo y la saliva. Mas, ¿por qué hablas con palabras encubiertas? Cuentas con la excitación de mi sistema nervioso... No, amiguito, no sucederá lo que tú piensas; sea lo que quiera lo que hayas preparado... Ahora veremos qué lazo me tiendes.»\"},{\"heading\":false,\"text\":\"Y se dispuso animosamente a afrontar la terrible catástrofe que preveía. De vez en cuando sentía deseos de lanzarse sobre Porfirio y de estrangularle sobre la marcha. Desde su entrada en el despacho del juez de instrucción, su principal temor era el de no poder dominar su cólera. Sentía los latidos violentos del corazón, se le secaban los labios y le brotaba espuma de ellos. Resolvió, sin embargo, callarse comprendiendo que, en su posición, el silencio era la mejor táctica. De esta suerte, en efecto, no sólo no se comprometería, sino que quizá conseguiría irritar a su enemigo y arrancarle alguna palabra imprudente. Por lo menos, tal era la esperanza de Raskolnikoff.\"},{\"heading\":false,\"text\":\"--No, bien veo que usted no lo cree. Supone usted que me burlo--prosiguió Porfirio, que cada vez estaba más alegre sin dejar su risita, y había reanudado sus paseos por la sala--. Tal vez tenga usted razón; me ha dado Dios una cara que despierta en los que me ven ideas cómicas; soy un bufón; pero perdone usted el lenguaje de un viejo: usted, Rodión Romanovitch, está en la flor de la juventud, y, como todos los de su edad, aprecia sobre todo la inteligencia humana. La agudeza del ingenio y las deducciones abstractas de la razón le seducen. Volviendo al _caso particular_ del que veníamos hablando, diré a usted que es preciso contar con la realidad, con la naturaleza. Es una cosa muy importante. ¡Oh! ¡Cómo triunfa muchas veces de la habilidad! ¡Escuche usted a un viejo! Hablo seriamente, Rodión Romanovitch--al pronunciar estas palabras, el juez, que escasamente tenía treinta y cinco años, parecía, en efecto, que había envejecido de improviso; en su persona y hasta en su voz habíase producido una repentina metamorfosis--. Además, yo soy muy franco... ¿Qué le parece a usted? ¿soy o no soy franco? Creo que no se puede ser más; le confío a usted todas estas cosas sin pedirle nada en cambio. ¡Je, je, je! Pues bien--continuó--: la agudeza de ingenio es, en mi opinión, una cosa excelente; es, por decirlo así, el ornamento de la naturaleza, el consuelo de la vida, y con ella solamente parece que se puede echar la zancadilla a un pobre juez de instrucción, que, por otra parte, suele ser engañado por su propia imaginación, porque, en resumidas cuentas, es hombre. Pero la naturaleza viene en ayuda del pobre juez. En esto es en lo que no piensa la juventud, fiando demasiado en su inteligencia, la juventud que «salta por encima de todos los obstáculos», como dijo usted ayer de una manera tan fina e ingeniosa. En el _caso particular_ de que tratamos, el culpable, yo lo admito, mentirá de una manera asombrosa; pero cuando crea que no tiene más que recoger el fruto de su habilidad, ¡paf! se desmayará en el sitio mismo en que tal accidente ha de ser objeto de mayores comentarios. Supongamos que puede explicar su desmayo por hallarse enfermo, por la atmósfera sofocante de la sala; eso no obstante, nacerán sospechas. Ha mentido de una manera asombrosa; pero no ha sabido tomar precauciones contra la naturaleza. Ahí tiene usted dónde está el verdadero lazo. Otra vez, impulsado por su carácter burlón, se divertirá embromando a alguno que sospecha, y, como por juego, fingirá ser el criminal a quien busca la policía; pero entrará demasiado bien en el ánimo de su modelo, representará su fingida comedia con _demasiada naturalidad_, y éste será otro indicio. De momento, su interlocutor podrá ser juguete de lo que dice; pero, si este último no es un zoquete, rectificará al siguiente día. Nuestro hombre se comprometerá a cada instante, ¡qué digo! vendrá por sí mismo donde no ha sido llamado, se explayará con palabras imprudentes, se extenderá en alegorías cuyo sentido no se escapará a nadie... ¡Je, je, je! Hasta preguntará por qué no se le ha detenido aún. ¡Je, je, je! Y esto puede ocurrir a un hombre muy suspicaz, a un psicólogo, a un literato. ¡No hay espejo tan transparente como la naturaleza! basta con contemplarla... pero, ¿por qué se pone usted tan pálido, Rodión Romanovitch? Quizá hace demasiado calor. ¿Quiere usted que abra la ventana?\"},{\"heading\":false,\"text\":\"--No se moleste usted, se lo ruego--contestó Raskolnikoff, echándose a reír.\"},{\"heading\":false,\"text\":\"El juez se detuvo enfrente de él, esperó un momento, y, de repente, soltó también una carcajada. Raskolnikoff, cuya hilaridad habíase calmado súbitamente, se levantó.\"},{\"heading\":false,\"text\":\"--Porfirio Petrovitch--dijo con voz ruda y fuerte, y manteniéndose con dificultad en pie, a causa del temblor de sus piernas--, no tengo duda: usted sospecha que yo he asesinado a esa vieja y a su hermana Isabel. Por mi parte le declaro que estoy ya hasta la coronilla. Si usted cree que tiene el derecho de perseguirme o de hacerme detener, persígame usted y métame en la cárcel; pero no permito que se burle nadie de mí, ni de que se me martirice.\"},{\"heading\":false,\"text\":\"De pronto comenzaron a temblarle los labios, sus ojos despidieron llamas, y su voz, hasta entonces contenida, alcanzó el diapasón más elevado.\"},{\"heading\":false,\"text\":\"--¡No lo permito!--gritó bruscamente, y dió un vigoroso puñetazo sobre la mesa--. ¿Lo ha oído usted, Porfirio Petrovitch? ¡No lo permito!\"},{\"heading\":false,\"text\":\"--¡Ah! ¡Dios mío! ¿Pero qué le pasa a usted?--dijo el juez de instrucción en apariencia muy inquieto--. ¡_Batuchka_! Rodión Romanovitch, amigo mío, ¿qué está usted diciendo?\"},{\"heading\":false,\"text\":\"--¡No lo permito!--repitió Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¡_Batuchka_, un poco más bajo! Van a oírle. Vendrán, y, entonces, ¿qué diremos? Piense usted un poco en ello--murmuró como asustado Porfirio Petrovitch, que había acercado su cara a la del visitante.\"},{\"heading\":false,\"text\":\"--¡No lo permito! ¡No lo permito!--prosiguió maquinalmente Raskolnikoff; pero hablaba bajando el tono, de modo que sólo podía ser oído por Porfirio.\"},{\"heading\":false,\"text\":\"Este corrió a abrir la ventana.\"},{\"heading\":false,\"text\":\"--Es menester airear la sala. ¿Por qué no bebe usted un poco de agua, querido amigo? Eso no es más que un acceso sin importancia.\"},{\"heading\":false,\"text\":\"Se dirigía ya a la puerta para dar órdenes a un criado, cuando vió en un rincón una jarra de agua.\"},{\"heading\":false,\"text\":\"--¡Beba usted, _batuchka_!--murmuró, aproximándose vivamente al joven con una jarra--. Esto le sentará a usted muy bien.\"},{\"heading\":false,\"text\":\"El susto, y aun la misma solicitud de Porfirio Petrovitch, parecían tan poco fingidos, que Raskolnikoff se calló y se puso a examinarle con tétrica curiosidad; pero rehusó el agua que se le ofrecía.\"},{\"heading\":false,\"text\":\"--¡Rodión Romanovitch! ¡querido amigo! ¡Si usted continúa así, va a volverse loco, se lo aseguro! Beba usted, beba usted, aunque sea un sorbo.\"},{\"heading\":false,\"text\":\"Y le puso casi a la fuerza el vaso en la mano. Maquinalmente, Raskolnikoff se lo llevó a los labios; pero de repente mudó de parecer, y lo dejó con disgusto sobre la mesa.\"},{\"heading\":false,\"text\":\"--Eso no ha sido más que un acceso insignificante. Tanto hará usted, mi querido amigo, que acabará por recaer de nuevo--observó con tono afectuoso el juez de instrucción, que parecía muy afectado--. Señor, ¿pero es posible que se cuide usted tan poco? Lo mismo pasó con Demetrio Prokofitch, que estuvo ayer en mi casa. Reconozco que tengo el genio cáustico, que mi carácter es horrible... pero, ¡señor! ¿qué significación se da a mis inofensivas salidas? Vino ayer después de la visita de usted; íbamos a ponernos a comer y empezó a hablar. Me contenté con apartar los brazos: ¡Ah Dios mío!... Fué usted quien lo envió, ¿verdad? ¡Siéntese usted; _batuchka_; siéntese usted, por el amor de Cristo!\"},{\"heading\":false,\"text\":\"--No, no le mandé yo; pero sabía que estaba en casa de usted y por qué hacía esa visita--respondió sarcásticamente Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¿Usted lo sabía?\"},{\"heading\":false,\"text\":\"--Sí. ¿Qué deduce usted de eso?\"},{\"heading\":false,\"text\":\"--Deduzco, _batuchka_, que conozco, además, otros muchos hechos y excursiones de usted; estoy informado de todo. Sé que a la caída de la tarde fué usted a alquilar el _cuarto_; que se puso a tirar del cordón de la campanilla; que hizo una pregunta acerca de la sangre, y que el aspecto de usted asombró a los obreros y a los _dvorniks_. ¡Oh! comprendo la situación moral en que usted se encontraba entonces; pero no es menos cierto que todos estos trastornos acabarán por volverle loco. En el alma de usted hierve una noble indignación; tiene usted motivos para quejarse de su destino, en primer término, y en segundo, de la policía. Va usted también de aquí para allá forzando, en cierto modo, a la gente para que formule en voz alta sus acusaciones. Estas chismografías estúpidas le son insoportables, y quiere usted acabar con todo ello. ¿No es así? ¿No he adivinado alguno de los sentimientos a que usted obedece? Pero el caso es que no se contenta usted con devanarse los sesos, sino que hace perder también la cabeza al pobre Razumikin, y es verdaderamente una lástima volver loco a tan buen muchacho. Su misma bondad le expone más que a cualquier otro a sufrir el contagio de la enfermedad de usted... Cuando usted se calme, _batuchka_, yo le contaré... Pero, siéntese, ¡por el amor de Cristo! Se lo suplico. Recobre sus ánimos; está usted trastornado; siéntese.\"},{\"heading\":false,\"text\":\"Raskolnikoff se sentó. Un temblor febril agitaba todo su cuerpo. Escuchaba con sorpresa profunda a Porfirio, que le prodigaba demostraciones de amistad; pero no daba ningún crédito a las palabras del juez de instrucción, aunque sentía una propensión extraña a creerlas. Le había impresionado mucho el oír a Porfirio hablarle de su visita al cuarto de la vieja. «¿Cómo sabe esto, y por qué me lo cuenta él mismo?», pensaba el joven.\"},{\"heading\":false,\"text\":\"--Sí, se ha producido en nuestra táctica judiciaria un caso psicológico casi análogo, un caso morboso--continuó Porfirio--. Un hombre se acusó de un homicidio que no había cometido. Contó una historia completa, una alucinación de que él había sido juguete; y su relato era tan verosímil, parecía tan de acuerdo con los hechos, que desafiaba toda contradicción. ¿Cómo explicarse esto? Sin haber intervenido en él, este individuo había sido, en parte, causa de un asesinato. Cuando supo que él había, sin saberlo, facilitado el crimen, se sobrecogió de tal manera, que su razón se alteró e imaginó que él era el verdadero criminal. Al fin y a la postre, el Senado examinó la causa y descubrió que el desgraciado era inocente. Sin el Senado, ¿qué hubiera sido de este pobre diablo? He aquí lo que se arriesga, _batuchka_. Puede uno convertirse en monomaníaco cuando va por la noche a tirar de los cordones de las campanillas y a hacer preguntas acerca de la sangre. En el ejercicio de mi profesión, he tenido ocasión de estudiar toda esta psicología. Es ése de que hablo un atractivo semejante al que impulsa a un hombre a tirarse por una ventana de lo alto de una torre... Usted está enfermo, Rodión Romanovitch, y hace mal en descuidar tanto su enfermedad. Debiera usted consultar un médico experimentado, en vez de hacerse asistir por ese gordinflón de Zosimoff. Todo esto es en usted el efecto del delirio...\"},{\"heading\":false,\"text\":\"Durante un instante, Raskolnikoff creyó ver que todos los objetos daban vueltas en derredor suyo. «¿Es posible que siga mintiendo en este momento?», se preguntaba; y esforzábase para desechar esta idea, presintiendo el exceso de rabia loca a que podía impulsarle.\"},{\"heading\":false,\"text\":\"--Yo no deliraba. Me encontraba en el pleno uso de mi razón--gritó, en tanto que ponía su espíritu en tortura para comprender el juego de Porfirio--. Era dueño de todas mis facultades, ¿entiende usted?\"},{\"heading\":false,\"text\":\"--Sí; comprendo, comprendo. Ya me dijo usted ayer que no deliraba, e insistió particularmente sobre este punto. Comprendo todo lo que puede usted decir. ¡Je, je!... Pero permítame usted que someta a su juicio una observación, querido Rodión Romanovitch: Si en efecto, fuese usted el culpable, o hubiese tomado parte en ese maldito asunto, yo le pregunto: ¿hubiera sostenido que había hecho usted todas esas cosas, no delirando, sino con plena conciencia de sus actos? Supongo que habría usted hecho todo lo contrario. Si creyese usted que su causa estaba prejuzgada, debería precisamente sostener con tenacidad que obró bajo la influencia del delirio; ¿no es así?\"},{\"heading\":false,\"text\":\"El tono de la pregunta hacía sospechar que se le tendía un lazo. Al pronunciar estas últimas palabras, el juez se inclinó hacia Raskolnikoff. Este se recostó en el diván y miró silenciosamente en la cara a su interlocutor.\"},{\"heading\":false,\"text\":\"--Y lo mismo digo respecto de la visita del señor Razumikin. Si usted fuese culpable, debería decir que nuestro amigo vino a mi casa por su propia iniciativa, y ocultar que había dado este paso por instigación de usted. Por el contrario, lejos de ocultarlo, asegura que fué usted quien lo mandó.\"},{\"heading\":false,\"text\":\"Raskolnikoff no había afirmado nada de esto, y sintió, al oírlo, un escalofrío en la espina dorsal.\"},{\"heading\":false,\"text\":\"--Usted sigue mintiendo--dijo con voz lenta y débil, esbozando una sonrisa--. Quiere usted suponer que lee en mi interior y que sabe de antemano todas las respuestas--continuó, comprendiendo que ya no pesaba sus palabras como debía--; usted quiere meterme miedo... o simplemente burlarse de mí.\"},{\"heading\":false,\"text\":\"Hablando de este modo, Raskolnikoff no cesaba de mirar fijamente al juez de instrucción. De repente brillaron de nuevo en sus ojos relámpagos de cólera violenta.\"},{\"heading\":false,\"text\":\"--No hace usted más que mentir--gritó--. Sabe usted perfectamente que la mejor táctica para un culpable es confesar lo que no le es posible tener oculto. Yo no le creo a usted.\"},{\"heading\":false,\"text\":\"--¡Qué listo es usted para ver las cosas!--dijo Porfirio sonriéndose--. Pero en este asunto, _batuchka_, está engañado; es el efecto de la monomanía. ¡Ah! ¿Conque usted no me cree? Pues yo le digo que me crea un poco, y me arreglaré de manera que acabe por creerme del todo; porque yo le quiero a usted sinceramente, y le miro con singular interés.\"},{\"heading\":false,\"text\":\"Los labios de Raskolnikoff comenzaron a temblar.\"},{\"heading\":false,\"text\":\"--Sí; yo le quiero a usted--prosiguió Porfirio asiendo amistosamente el brazo del joven por algo más arriba del codo--; vuelvo a repetírselo a usted: cuídese su enfermedad. Además, la familia de usted se encuentra ahora en San Petersburgo; piense algo en ella. Debería usted hacer la felicidad de sus parientes y, por el contrario, sólo les acarrea inquietudes.\"},{\"heading\":false,\"text\":\"--Y a usted, ¿qué le importa? ¿Cómo sabe usted eso? ¿Por qué se mezcla en mis asuntos? ¿De modo que usted me vigila, y además, me lo dice?\"},{\"heading\":false,\"text\":\"--Pero, _batuchka_. ¡Si es usted mismo quien me lo ha contado! No advierte que, en su agitación, habla usted espontáneamente de sus asuntos a mí y a los demás. Ayer Razumikin me comunicó también muchas particularidades interesantes acerca de usted. Iba a decirle que, a pesar de todo su genio, ha perdido la vista exacta de las cosas, a consecuencia de su carácter suspicaz. Vea usted, el incidente del cordón de la campanilla. Ese es un hecho precioso, un hecho inapreciable para un magistrado observador; yo se lo entrego a usted cándidamente; yo, juez de instrucción. Y esto, ¿no le abre a usted los ojos? Pero si yo le creyera culpable, ¿hubiera procedido de esa suerte? En tal caso, mi línea de conducta estaba perfectamente trazada: hubiera debido, por el contrario, desviar la atención de usted hacia otro punto. Después, bruscamente, le hubiera asestado, según la expresión de usted, sobre la coronilla, la siguiente pregunta: «¿Qué fué usted a hacer a tal hora de la noche al domicilio de la víctima? ¿Por qué tiró usted del cordón de la campanilla? ¿Por qué hizo usted preguntas acerca de la sangre? ¿Por qué aturdió usted a los _dvorniks_ pidiendo que le condujesen a la oficina de policía?» De esta manera hubiera procedido si hubiese tenido alguna sospecha acerca de usted. Hubiera debido someter a usted a un interrogatorio en regla, ordenar una investigación y detenerle. Puesto que he obrado de otro modo, es señal evidente de que no sospecho de usted. Ha perdido el sentido exacto de las cosas, y está ciego, se lo repito.\"},{\"heading\":false,\"text\":\"Raskolnikoff temblaba, lo cual pudo fácilmente advertir Porfirio Petrovitch.\"},{\"heading\":false,\"text\":\"--Sigue usted mintiendo--vociferó el joven--. No sé cuáles son sus intenciones; pero estoy cierto de que miente... Hace poco no hablaba usted en ese sentido y sobre ello no me hago ilusiones... Miente usted.\"},{\"heading\":false,\"text\":\"--¿Que miento?--replicó Porfirio con apariencias de vivacidad. Por lo demás, el juez de instrucción conservaba su aspecto jovial, y parecía no dar importancia alguna a la opinión que Raskolnikoff pudiera tener de él--. ¿Que miento? ¿Pero usted no recuerda cómo acabo de tratarle? Yo, juez de instrucción, le he sugerido los argumentos psicológicos que usted podía emplear: «La enfermedad, el delirio, los sufrimientos del amor propio, la hipocondría, la afrenta recibida en el despacho de policía», etc. ¿No es así? ¡Je, je, je! Verdad es, dicho sea de paso, que estos medios de defensa no siempre dan el resultado apetecido; son armas de dos filos y podría cortarse el que las empleara. Si usted dice: «Yo estaba enfermo, yo deliraba, no sabía lo que hacía, no me acuerdo de nada», podrá respondérsele: «Todo eso está muy bien, _batuchka_, pero, ¿cómo es que el delirio toma siempre en usted el mismo carácter?» Debería manifestarse en otras formas, ¿verdad? ¡Je, je, je!\"},{\"heading\":false,\"text\":\"Raskolnikoff se levantó, y mirándole despreciativamente, dijo:\"},{\"heading\":false,\"text\":\"--En resumen: quiero saber de una manera concreta si sospecha usted o no de mí. Hable usted, Porfirio Petrovitch. Explíquese usted sin ambages ni rodeos; y en seguida, al instante.\"},{\"heading\":false,\"text\":\"--¡Ah, Dios mío! Se parece usted a los niños que piden la luna--replicó Porfirio siempre con su tono zumbón--. ¿Qué necesidad tiene usted de saber nada, si se le deja a usted perfectamente tranquilo? ¿Por qué se altera de ese modo? ¿Por qué viene a mi casa cuando nadie le llama? ¿Cuáles son las razones de usted? ¡Je, je, je!\"},{\"heading\":false,\"text\":\"--Le repito--gritó Raskolnikoff furioso--que ya no me es posible soportar...\"},{\"heading\":false,\"text\":\"--¿Qué? ¿La incertidumbre?--interrumpió el juez de instrucción.\"},{\"heading\":false,\"text\":\"--No me exaspere usted más... No quiero, digo a usted que no quiero... no puedo ni quiero... ¿oye usted?--gritó con voz de trueno Raskolnikoff, descargando un nuevo puñetazo sobre la mesa.\"},{\"heading\":false,\"text\":\"--Más bajo, más bajo; van a oírle a usted, se lo advierto seriamente. Tenga cuidado--murmuró Porfirio.\"},{\"heading\":false,\"text\":\"El juez de instrucción no tenía ya aquel aire de campesino que comunicaba a su rostro cierta candidez; fruncía las cejas, hablaba como amo y estaba a punto de quitarse la careta; pero esta nueva actitud no duró más que un instante. Aunque al punto Raskolnikoff se entregó a un arrebato de cólera, sin embargo, cosa extraña, esta vez, como antes, aunque estaba en el colmo de la exasperación, obedeció la orden de bajar la voz; comprendía, además, que no podía menos de hacerlo, y este pensamiento contribuyó a aumentar su irritación.\"},{\"heading\":false,\"text\":\"--No me dejaré martirizar--murmuró--; deténgame usted, regístreme, haga cuantas investigaciones quiera; pero proceda usted en debida forma, y no juegue conmigo. No tenga usted la audacia...\"},{\"heading\":false,\"text\":\"--No se inquiete usted por la forma--interrumpió Porfirio con su acento sardónico, mientras contemplaba a Raskolnikoff con cierto júbilo--; es familiarmente, _batuchka_, como amigo, como he invitado a usted a que viniera a verme.\"},{\"heading\":false,\"text\":\"--No quiero la amistad de usted; la desprecio. ¿Entiende usted? Y ahora tomo la gorra y me voy. Usted dirá si tiene intención de detenerme.\"},{\"heading\":false,\"text\":\"En el momento en que se acercaba a la puerta, Porfirio Petrovitch le asió de nuevo del brazo, por un poco más arriba del codo.\"},{\"heading\":false,\"text\":\"--¿No quiere usted que le dé una pequeña sorpresa?--dijo, riendo, el juez de instrucción, que cada vez parecía más burlón, lo que acabó de poner a Raskolnikoff fuera de sí.\"},{\"heading\":false,\"text\":\"--¿Qué pequeña sorpresa? ¿Qué quiere usted decir?--preguntó el joven, deteniéndose de repente y mirando con inquietud a Porfirio.\"},{\"heading\":false,\"text\":\"--Una pequeña sorpresa que hay detrás de esa puerta. ¡Je, je, je!--y mostraba con un dedo la puerta cerrada que daba acceso a su habitación, situada detrás del tabique--. Yo mismo la he cerrado con llave para que no se vaya.\"},{\"heading\":false,\"text\":\"--¿Qué es? ¿qué es? ¿Qué hay?\"},{\"heading\":false,\"text\":\"Raskolnikoff se acercó a la puerta; quiso abrirla, pero no pudo.\"},{\"heading\":false,\"text\":\"--Está cerrada. He aquí la llave--y diciendo esto, el juez de instrucción sacó la llave del bolsillo y se la enseñó al joven.\"},{\"heading\":false,\"text\":\"--¡Mientes! ¡Sigues mintiendo!--aulló éste, que ya no era dueño de sí--. ¡Mientes, maldito pulchinela!\"},{\"heading\":false,\"text\":\"Al mismo tiempo hizo ademán de arrojarse sobre Porfirio, el cual se retiró hacia la puerta, pero sin demostrar ningún temor.\"},{\"heading\":false,\"text\":\"--¡Lo comprendo todo!--vociferó Raskolnikoff--. ¡Mientes, mientes para que yo me venda!...\"},{\"heading\":false,\"text\":\"--Pero, ¿por qué ha de venderse usted? ¡Vea en qué estado se encuentra, Rodión Romanovitch! No grite, o llamo.\"},{\"heading\":false,\"text\":\"--¡Mientes, no hay nada! ¡Llama a tu gente! Sabías que estaba enfermo y has querido exasperarme, ponerme en el disparador para arrancarme una confesión; ése era tu objeto. Exhibe tus pruebas. Te he comprendido. No tienes pruebas; no tienes más que suposiciones, las conjeturas de Zametoff. Conocías mi carácter y has querido exasperarme, a fin de hacer en seguida que se presentaran bruscamente los popes y delegados. Los esperas, ¿eh? ¿A quién esperas? ¿A ellos? Hazlos entrar.\"},{\"heading\":false,\"text\":\"--¿Qué habla usted de delegados, _batuchka_? ¡Vaya unas ideas! La misma forma para emplear el mismo lenguaje de usted, no permite proceder de este modo; usted conoce el procedimiento, mi querido amigo... pero será observada la forma, usted lo verá--murmuró Porfirio, que se había puesto a escuchar junto a la puerta.\"},{\"heading\":false,\"text\":\"Sonaba, en efecto, cierto ruido en la pieza contigua.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿Vienen?--gritó Raskolnikoff--. ¿Los has enviado a buscar? Habías contado... Pues bien, introdúcelos a todos, delegados y testigos; haz entrar a quien quieras. Estoy pronto.\"},{\"heading\":false,\"text\":\"Pero entonces ocurrió un incidente muy extraño, tan fuera del curso ordinario de las cosas, que sin duda Raskolnikoff ni Porfirio Petrovitch hubieran podido preverlo.\"}]},{\"title\":\"cuarta parte — capítulo VI\",\"blocks\":[{\"heading\":false,\"text\":\"He aquí el recuerdo que esta escena dejó en el espíritu de Raskolnikoff:\"},{\"heading\":false,\"text\":\"El ruido que sonaba en la habitación inmediata aumentó de repente, y la puerta se entreabrió.\"},{\"heading\":false,\"text\":\"--¿Qué es eso?--gritó Porfirio Petrovitch encolerizado.\"},{\"heading\":false,\"text\":\"No hubo respuesta; pero la causa del ruido se dejaba adivinar en parte: alguna persona quería penetrar en el despacho del juez y trataban de impedírselo.\"},{\"heading\":false,\"text\":\"--¿Qué es lo que sucede?--repitió Porfirio.\"},{\"heading\":false,\"text\":\"--Es el procesado Mikolai, que ha sido conducido aquí.\"},{\"heading\":false,\"text\":\"--No tengo necesidad de él. No quiero verle; llevadle. Esperad un poco. ¿Por qué le han traído? ¡Qué desorden!--murmuró Porfirio lanzándose hacia la puerta.\"},{\"heading\":false,\"text\":\"--El es quien...--replicó la misma voz; y se detuvo de repente.\"},{\"heading\":false,\"text\":\"Durante dos minutos se oyó el ruido de una lucha entre dos hombres; después, uno de ellos rechazó al otro con fuerza, y penetró bruscamente en el despacho.\"},{\"heading\":false,\"text\":\"El recién venido tenía un aspecto muy extraño. Parecía no ver a nadie. En sus ojos llameantes se leía una firme resolución, y al propio tiempo su rostro estaba lívido como el de un condenado a quien se conduce al cadalso. Temblábanle ligeramente los labios, exangües.\"},{\"heading\":false,\"text\":\"Era un hombre muy joven todavía, delgado, de mediana estatura y vestido como un obrero. Tenía el cabello cortado al rape y sus facciones eran finas y angulosas. El que acababa de ser rechazado por él, se lanzó en persecución suya dentro del gabinete y le agarró por un brazo: era un gendarme. Mikolai logró de nuevo soltarse.\"},{\"heading\":false,\"text\":\"En el umbral se agruparon muchos curiosos, algunos de los cuales tenían vivos deseos de entrar. Todo ello había pasado en menos tiempo del que se tarda en referirlo.\"},{\"heading\":false,\"text\":\"--¡Vete! Es todavía pronto; espera a que se te llame... ¿Por qué te han traído tan pronto?--preguntó Porfirio Petrovitch tan irritado como sorprendido; pero de repente Mikolai se puso de rodillas.\"},{\"heading\":false,\"text\":\"--¿Qué haces?--gritó el juez de instrucción cada vez más asombrado.\"},{\"heading\":false,\"text\":\"--¡Perdón! ¡Soy culpable! ¡Yo soy el asesino!--dijo bruscamente Mikolai, con voz bastante fuerte, a pesar de la emoción que le ahogaba.\"},{\"heading\":false,\"text\":\"Pasaron diez segundos en un silencio profundo como si todos los asistentes hubiesen sido acometidos de un ataque de catalepsia. El gendarme no trató de sujetar de nuevo al preso, y dirigiéndose maquinalmente hacia la puerta, se quedó inmóvil en el umbral.\"},{\"heading\":false,\"text\":\"--¿Qué estás diciendo?--exclamó Porfirio Petrovitch cuando el asombro le permitió hablar.\"},{\"heading\":false,\"text\":\"--Yo soy el asesino...--repitió de nuevo Mikolai.\"},{\"heading\":false,\"text\":\"--¿Cómo? ¿Qué? ¿Que tú has asesinado...?\"},{\"heading\":false,\"text\":\"El juez de instrucción estaba visiblemente desconcertado. El preso tardó un instante en responder.\"},{\"heading\":false,\"text\":\"--Yo he asesinado... a hachazos... a Alena Ivanovna y a su hermana Isabel Ivanovna. Estaba trastornado--añadió bruscamente.\"},{\"heading\":false,\"text\":\"Se calló, pero continuaba de rodillas. Después de haber oído esta respuesta, Porfirio Petrovitch pareció reflexionar profundamente, y luego, con un ademán violento, mandó a los testigos que se retirasen. Estos obedecieron al punto y la puerta volvió a cerrarse.\"},{\"heading\":false,\"text\":\"Raskolnikoff, en pie, contemplaba a Mikolai con aire extraño. Durante algunos instantes las miradas del juez de instrucción fueron del detenido al visitante y viceversa. Después se dirigió a Mikolai sin tratar de disimular su cólera.\"},{\"heading\":false,\"text\":\"--Espera a que se te interrogue antes de decirme que estabas trastornado. Yo no te preguntaba eso. Habla ahora: ¿Has matado...?\"},{\"heading\":false,\"text\":\"--Yo soy el asesino... lo confieso--respondió Mikolai.\"},{\"heading\":false,\"text\":\"--¿Oh? ¿Con qué arma has matado?\"},{\"heading\":false,\"text\":\"--Con una hacha. La llevaba prevenida.\"},{\"heading\":false,\"text\":\"--¡Eh, qué apresuramiento! ¿Solo?\"},{\"heading\":false,\"text\":\"Mikolai no comprendió la pregunta.\"},{\"heading\":false,\"text\":\"--¿No tienes cómplices?\"},{\"heading\":false,\"text\":\"--No. Mitka es inocente. No ha tomado la menor parte en el crimen.\"},{\"heading\":false,\"text\":\"--No te apresures tanto para disculpar a Mitka. ¿Acaso te he preguntado acerca de él?... Sin embargo, ¿cómo se explica que los _dvorniks_ os hayan visto bajar corriendo la escalera?\"},{\"heading\":false,\"text\":\"--Corrí adrede detrás de Mitka porque de ese modo pensé evitar sospechas--respondió el preso.\"},{\"heading\":false,\"text\":\"--Está bien. Basta--gritó Porfirio encolerizado--; no dice la verdad--murmuró en seguida como aparte, y de pronto sus ojos se encontraron con los de Raskolnikoff, cuya presencia había evidentemente olvidado durante este diálogo con Mikolai.\"},{\"heading\":false,\"text\":\"Al fijarse en su visitante pareció que se turbaba el juez de instrucción y dirigiéndose a él le dijo:\"},{\"heading\":false,\"text\":\"--Rodión Romanovitch, _batuchka_, perdóneme usted, se lo suplico... Nada tiene usted que hacer aquí... yo mismo... ya ve qué sorpresa...\"},{\"heading\":false,\"text\":\"Tomó al joven por el brazo y le señaló la puerta.\"},{\"heading\":false,\"text\":\"--Según se ve, no esperaba usted tal cosa--observó Raskolnikoff.\"},{\"heading\":false,\"text\":\"Naturalmente, lo que acababa de suceder era para él un enigma. Sin embargo, había recobrado en gran parte su serenidad.\"},{\"heading\":false,\"text\":\"--Tampoco usted lo esperaba, _batuchka_. Vea usted cómo le tiembla la mano. ¡Je, je, je!\"},{\"heading\":false,\"text\":\"--También está usted temblando, Porfirio Petrovitch--observó Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Es verdad... no esperaba esto...\"},{\"heading\":false,\"text\":\"Se encontraban ya en el umbral de la puerta. El juez de instrucción tenía prisa porque se marchase el joven.\"},{\"heading\":false,\"text\":\"--¿De modo que no me enseña usted la «pequeña sorpresa» que me tenía preparada?--preguntó éste bruscamente.\"},{\"heading\":false,\"text\":\"--Apenas si tiene fuerzas para hablar y ya se muestra irónico, ¡je, je, je! ¡Ea, hasta la vista!\"},{\"heading\":false,\"text\":\"--Creo que sería más propio decir _¡adiós!_\"},{\"heading\":false,\"text\":\"--Será lo que Dios quiera--balbuceó Porfirio con risa forzada.\"},{\"heading\":false,\"text\":\"Al atravesar la Cancillería, Raskolnikoff advirtió que muchos de los empleados le miraban fijamente. En la antesala reconoció en medio de la gente a los _dvorniks_ de _aquella casa_, a los que había propuesto la tarde de la extraña visita que le condujesen a la comisaría de policía. Parecía que estaban esperando allí algo, pero apenas hubo llegado al rellano de la escalera, cuando oyó de nuevo la voz de Porfirio Petrovitch. El joven se volvió y vió al juez de instrucción que, todo sofocado, acudía a llamarle.\"},{\"heading\":false,\"text\":\"--Una palabra todavía, Rodión Romanovitch. Dios sabe lo que pasará en este asunto; pero, para la cuestión de forma, tengo que pedirle a usted algunos datos, de modo que nos volveremos a ver de seguro.\"},{\"heading\":false,\"text\":\"Porfirio se detuvo sonriendo delante del joven.\"},{\"heading\":false,\"text\":\"--De seguro--repitió.\"},{\"heading\":false,\"text\":\"Parecía que iba a decir alguna otra cosa; pero nada añadió.\"},{\"heading\":false,\"text\":\"--Perdone usted mi proceder de antes, Porfirio Petrovitch... Me he alterado un poco--comenzó a decir Raskolnikoff, que había recobrado ya toda su serenidad y sentía grandes deseos de burlarse del magistrado.\"},{\"heading\":false,\"text\":\"--¡Bah! Eso no tiene importancia--replicó el juez con tono casi jovial--. También yo tengo un carácter insoportable, lo reconozco. Ya nos veremos; si Dios quiere, nos veremos a menudo.\"},{\"heading\":false,\"text\":\"--Y entonces nos conoceremos a fondo--repuso Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Muy a fondo--repitió como un eco Porfirio Petrovitch, y guiñando un ojo, miró con mucha gravedad a su interlocutor--. ¿Y ahora va usted a comer a una fiesta?\"},{\"heading\":false,\"text\":\"--A un entierro.\"},{\"heading\":false,\"text\":\"--¡Ah! Está bien. Tenga usted cuidado de su salud.\"},{\"heading\":false,\"text\":\"--Por mi parte, no sé qué votos hacer por usted--respondió Raskolnikoff, y comenzó a bajar la escalera; pero de repente se volvió hacia Porfirio--. ¡Ah! Le deseo a usted de todo corazón mejor éxito del que ha conseguido hasta ahora, vea usted, sin embargo, qué cómicas son sus funciones.\"},{\"heading\":false,\"text\":\"Al oír estas palabras, el juez de instrucción, que se disponía a volver a su despacho, aguzó el oído.\"},{\"heading\":false,\"text\":\"--¿Qué es lo que tienen de cómicas?--preguntó.\"},{\"heading\":false,\"text\":\"--Mucho. Ahí tiene a ese pobre Mikolai; ¡cuánto ha debido usted atormentarle! ¡Cuánto lo habrá usted fatigado para arrancarle su confesión! Día y noche, sin duda, le habrá usted repetido en todos los tonos: «¡Tú eres el asesino, tú eres el asesino!» Le habrá usted perseguido sin tregua, según su método psicológico, y ahora, cuando él se reconoce culpable, usted empieza con la cantata en otro tono de «¡Mientes! ¡Tú no eres el asesino! ¡No puedes serlo, no dices la verdad!» Pues bien, después de esto, ¿no tengo derecho para encontrar cómicas las funciones de usted?\"},{\"heading\":false,\"text\":\"--¡Je, je, je! ¿De modo que ha reparado usted que hace poco rato he hecho observar a Mikolai que no decía la verdad?\"},{\"heading\":false,\"text\":\"--¿Cómo no había de observarlo?\"},{\"heading\":false,\"text\":\"--¡Je, je, je! Tiene usted mucho ingenio; nada se le escapa. Además, le da a usted por lo chistoso. Posee usted la cuerda humorística. ¡Je, je, je! Ese era, según dicen, el rasgo distintivo de Cogol.\"},{\"heading\":false,\"text\":\"--Sí, de Cogol.\"},{\"heading\":false,\"text\":\"--En efecto, de Cogol, ¡Hasta la vista!...\"},{\"heading\":false,\"text\":\"--Hasta la vista.\"},{\"heading\":false,\"text\":\"El joven se fué directamente a su casa. Cuando llegó a su domicilio, se echó en el diván y durante un cuarto de hora intentó ordenar algún tanto sus ideas, que eran muy confusas. No trató siquiera de explicarse la conducta de Mikolai, comprendiendo que había allí un misterio cuya clave buscaría en vano por el momento. Por lo demás, no se hacía ilusiones sobre las consecuencias probables del incidente. No tardaría en comprenderse que eran mentirosas las confesiones del obrero, y entonces las sospechas recaerían de nuevo sobre él. Pero, en tanto, era libre y podía tomar sus medidas en previsión del peligro que juzgaba inminente.\"},{\"heading\":false,\"text\":\"¿Hasta qué punto, empero, estaba amenazado? La situación comenzaba a esclarecerse. El joven temblaba aún al acordarse de su reciente entrevista con el juez de instrucción. No podía penetrar todas las intenciones de Porfirio, pero lo que adivinaba era más que suficiente para hacerle comprender de qué terrible peligro acababa de escapar. Un poco más y se hubiera perdido sin remedio. Conociendo la irritabilidad nerviosa de su visitante, el juez se había apoyado sólidamente sobre este dato, y había descubierto con exceso de atrevimiento su juego; pero jugaba sobre seguro. Ciertamente, Raskolnikoff se había comprometido demasiado; sin embargo, las imprudencias de que él se acusaba no constituían todavía una prueba en contra suya: esto no tenía más que un carácter relativo. ¿No se engañaba, sin embargo, al pensar así? ¿Cuál era el proyecto de Porfirio? ¿Habría éste maquinado algo aquel día, y si tenía preparado un golpe, en qué consistía éste? Sin la aparición inesperada de Mikolai, ¿cómo hubiera acabado esta entrevista?\"},{\"heading\":false,\"text\":\"Raskolnikoff estaba sentado en el sofá con los codos apoyados en las rodillas y la cabeza en las manos. Un temblor nervioso agitaba todo su cuerpo. Al fin se levantó, tomó la gorra y después de haber reflexionado un momento, se dirigió hacia la puerta.\"},{\"heading\":false,\"text\":\"--Por hoy, al menos--se dijo--, no tengo nada que temer.\"},{\"heading\":false,\"text\":\"De repente experimentó una especie de alegría y se le ocurrió la idea de dirigirse lo más pronto posible a casa de Catalina Ivanovna. Ya era tarde para asistir al entierro, pero llegaría a tiempo para comer y allí vería a Sonia. Se detuvo, reflexionó, y en sus labios se dibujó una triste sonrisa.\"},{\"heading\":false,\"text\":\"«¡Hoy! ¡Hoy!--repitió--. Sí, hoy mismo. Es preciso.»\"},{\"heading\":false,\"text\":\"En el momento en que se dirigía a la puerta, ésta se abrió por sí misma. El joven retrocedió espantado viendo aparecer al enigmático personaje de la víspera, _al hombre salido de debajo de la tierra_.\"},{\"heading\":false,\"text\":\"El recién venido se detuvo en el umbral, y después de haber mirado silenciosamente a Raskolnikoff, dió un paso en la habitación. Vestía exactamente como el día anterior, pero su rostro no era el mismo.\"},{\"heading\":false,\"text\":\"--¿Qué quiere usted?--preguntó Raskolnikoff pálido como un muerto.\"},{\"heading\":false,\"text\":\"El hombre, en vez de responder, se inclinó casi hasta el suelo. Por lo menos le tocó con el anillo que llevaba en la mano derecha.\"},{\"heading\":false,\"text\":\"--¿Quién es usted?--preguntó Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Pido a usted perdón--dijo el hombre en voz baja.\"},{\"heading\":false,\"text\":\"--¿De qué?\"},{\"heading\":false,\"text\":\"--De mis malos pensamientos.\"},{\"heading\":false,\"text\":\"Los dos hombres se miraron.\"},{\"heading\":false,\"text\":\"--Estaba ciego de ira. Cuando usted fué el otro día, teniendo, sin duda, la razón perturbada por la bebida, hizo preguntas acerca de la sangre y pidió a los _dvorniks_ que lo condujesen a la oficina de policía, vi con disgusto que no hacían caso de las palabras de usted, tomándole por un borracho; esto me contrarió de tal modo, que no pude dormir; pero me acordaba de las señas de usted y vine ayer aquí...\"},{\"heading\":false,\"text\":\"--¿Fué usted quien vino?--interrumpió Raskolnikoff.\"},{\"heading\":false,\"text\":\"Comenzaba a comprender.\"},{\"heading\":false,\"text\":\"--Sí; yo le he insultado a usted.\"},{\"heading\":false,\"text\":\"--¿Estaba usted en aquella casa?\"},{\"heading\":false,\"text\":\"--Sí, me encontraba junto a la puerta cochera cuando la visita de usted. ¿Lo ha olvidado usted? Vivo allí desde hace mucho tiempo. Soy peletero...\"},{\"heading\":false,\"text\":\"Raskolnikoff se acordó súbitamente de toda la escena de la antevíspera. En efecto: independientemente de los _dvorniks_ había en la puerta cochera muchas personas, hombres y mujeres. Uno de ellos había propuesto que se le condujese a la comisaría de policía. No podía acordarse del rostro del que emitió esta idea; tampoco le reconoció en este momento; pero sí se acordaba de haberle respondido algo y de haberse vuelto a mirarle.\"},{\"heading\":false,\"text\":\"Así se explicaba de la manera más sencilla del mundo el terrible misterio de la víspera. ¡Y bajo la impresión de la inquietud que le causaba una circunstancia tan insignificante, había estado a punto de perderse! Aquel hombre no podía contar nada sino que Raskolnikoff se presentó a alquilar el cuarto de la vieja y que preguntó acerca de la sangre. Aparte de esta excursión de un _enfermo en delirio_, salvo esa _psicología de dos filos_, Porfirio no sabía nada. No tenía ningún hecho, nada positivo. «Por consiguiente--pensaba el joven--, si no surgen nuevos cargos (y no surgirán, estoy seguro de ello), ¿qué pueden hacerme? Aunque me detuvieran, ¿cómo demostrarían definitivamente mi culpabilidad?»\"},{\"heading\":false,\"text\":\"Otra conclusión se desprendía para Raskolnikoff de las palabras de su visitante: hacía muy pocas horas que Porfirio tuvo noticia de su visita al cuarto de la víctima.\"},{\"heading\":false,\"text\":\"--¿Usted le ha dicho hoy a Porfirio que estuve yo allí?--preguntó el joven asaltado por súbita idea.\"},{\"heading\":false,\"text\":\"--¿A qué Porfirio?\"},{\"heading\":false,\"text\":\"--Al juez de instrucción.\"},{\"heading\":false,\"text\":\"--Yo se lo he dicho. Como los _dvorniks_ no habían ido, fuí yo.\"},{\"heading\":false,\"text\":\"--¿Hoy?\"},{\"heading\":false,\"text\":\"--Llegué un minuto antes que usted; lo he oído todo y sé que le ha hecho pasar a usted un mal rato.\"},{\"heading\":false,\"text\":\"--¿Dónde? ¿Qué? ¿Cuándo?\"},{\"heading\":false,\"text\":\"--Yo estaba allí, en la pieza contigua a su gabinete, en donde he permanecido todo el tiempo que ha durado la entrevista.\"},{\"heading\":false,\"text\":\"--¿Cómo? ¿De modo que era usted la sorpresa? ¿Cómo ha sido eso? Cuéntemelo usted todo, se lo ruego.\"},{\"heading\":false,\"text\":\"--Viendo--dijo el menestral--que los _dvorniks_ rehusaban avisar a la policía, a pretexto de que era demasiado tarde y de que encontrarían la oficina cerrada, experimenté una viva contrariedad y resolví enterarme por mí mismo; al día siguiente, es decir, ayer, tomé datos y me he presentado al juez de instrucción. La primera vez que estuve en la oficina no se encontraba allí; volví una hora después y no fuí recibido; en fin, la última vez se me hizo entrar. Conté punto por punto cuanto había pasado; al oírme el juez saltaba en la habitación y se daba golpes en el pecho diciendo: «¿De ese modo cumplís, bribones, con vuestra obligación? Si yo hubiese sabido esto antes, le hubiera hecho buscar por la gendarmería.» En seguida salió precipitadamente, llamó a no sé quién y estuvo hablando con él en un rincón; se dirigió otra vez a mí y se puso de nuevo a interrogarme, profiriendo fuertes imprecaciones. No le he ocultado nada; le he dicho que usted no se atrevió a contestar a mis palabras de ayer y que no me había reconocido. Continuaba dándose golpes en el pecho, vociferando y saltando por la habitación. Entonces le anunciaron a usted. «Retírese detrás del tabique--me dijo dándome una silla--, y estése ahí sin chistar, oiga lo que oiga; puede que le interrogue otra vez.» Después cerró la puerta. Cuando condujeron a Mikolai, despidió a usted y me hizo salir a mí. «Tendré aún que interrogarle», me dijo.\"},{\"heading\":false,\"text\":\"--¿Preguntó a Mikolai delante de ti?\"},{\"heading\":false,\"text\":\"--Yo salí inmediatamente después de usted, y entonces fué cuando comenzó el interrogatorio de Mikolai.\"},{\"heading\":false,\"text\":\"Terminado su relato, el menestral se inclinó de nuevo hasta el suelo.\"},{\"heading\":false,\"text\":\"--Perdóneme usted por mi denuncia y por el error en que he incurrido.\"},{\"heading\":false,\"text\":\"--¡Que Dios te perdone!--respondió Raskolnikoff.\"},{\"heading\":false,\"text\":\"«Nada de inculpaciones precisas, nada más que pruebas de dos filos», pensó Raskolnikoff renaciendo a la esperanza, y salió de la habitación. «Todavía podemos luchar», se dijo con sonrisa colérica, mientras bajaba la escalera.\"},{\"heading\":false,\"text\":\"Estaba irritado contra sí mismo y sentíase humillado.\"},{\"heading\":false,\"text\":\"QUINTA PARTE\"}]},{\"title\":\"quinta parte — capítulo I\",\"blocks\":[{\"heading\":false,\"text\":\"Al día siguiente de aquel otro fatal en que Pedro Petrovitch tuvo su explicación con las señoras de Raskolnikoff, las ideas de aquél se esclarecieron y con extremo disgusto suyo le fué forzoso reconocer que la ruptura, en la cual no había querido creer el día antes, era un hecho consumado. La negra serpiente del amor propio herido le estuvo mordiendo el corazón durante toda la noche. Al saltar de la cama, el primer movimiento de Pedro Petrovitch fué irse a mirar al espejo, temiendo que durante la noche le hubiese invadido la ictericia. Por fortuna esta aprensión no era fundada. Al contemplar su rostro pálido y distinguido, llegó hasta a consolarse por breves instantes ante la idea de que no le costaría trabajo reemplazar a Dunia y quién sabe si ventajosamente. Pero no tardó en desechar esta esperanza quimérica y lanzó un fuerte salivazo, lo que hizo sonreír burlonamente a su joven amigo y compañero de habitación, Andrés Semenovitch Lebeziatnikoff.\"},{\"heading\":false,\"text\":\"Pedro Petrovitch advirtió ese mudo sarcasmo y lo puso en la cuenta de su amigo, cuenta que estaba ya bastante cargada, y redobló su cólera después que hubo reflexionado que no debía hablar de esta historia a Andrés Semenovitch. Fué la segunda tontería que el arrebato le hizo cometer el día anterior: había cedido a la necesidad de desahogar el exceso de su irritación.\"},{\"heading\":false,\"text\":\"Durante toda la mañana la suerte se ensañó en perseguir a Ludjin. En el mismo Senado, el negocio en que se ocupaba le reservaba un disgusto. Lo que le molestaba más que nada era la imposibilidad de hacer entrar en razón al propietario de la nueva casa que había alquilado en vista de su próximo enlace. Este individuo, alemán de origen, era un antiguo obrero a quien la fortuna había sonreído; no aceptaba ninguna transacción y reclamaba el pago entero del alquiler estipulado en el contrato, aun cuando Pedro Petrovitch le devolvía el cuarto casi restaurado.\"},{\"heading\":false,\"text\":\"El tapicero no se mostraba más complaciente que el propietario, y pretendía quedarse hasta con el último rublo de la señal recibida por la venta de un mobiliario de que Pedro Petrovitch «aun no se había hecho cargo». «Va a ser menester que me case para recuperar los muebles», decía rechinando los dientes el desgraciado Ludjin. Una última esperanza atravesaba su alma. «¿Era posible que aquel mal no tuviera remedio?» Tenía clavado en el corazón, como una espina, el recuerdo de los encantos de Dunia. Fué para él aquello un trago muy amargo, y si hubiera podido, con un simple deseo, hacer morir a Raskolnikoff, de seguro que Pedro Petrovitch habría matado al joven inmediatamente.\"},{\"heading\":false,\"text\":\"«Otra tontería de mi parte ha sido no darles dinero», pensaba mientras volvía entristecido a casa de Lebeziatnikoff. «¿Por qué he sido yo tan judío? ¡Fué un mal cálculo!... ¡Dejándolas momentáneamente en la estrechez, yo creía prepararlas a que vieran en mí una providencia, y he aquí que se me deslizan entre los dedos!... No, no. Si yo les hubiera dado mil quinientos rublos, por ejemplo, para que comprasen la canastilla en el Almacén Inglés, mi conducta hubiera sido a la vez más noble y más hábil y no me habrían dejado tan fácilmente. Dados sus principios, se hubieran creído, sin duda, obligadas a devolverme regalos y dinero; esta resolución les hubiera sido penosa y difícil, habría sido para ellas cuestión de conciencia. ¿Cómo atreverse entonces a poner así a la puerta a un hombre que se había mostrado tan generoso, y tan delicado?... He hecho una tontería.»\"},{\"heading\":false,\"text\":\"Pedro Petrovitch volvió de nuevo a rechinar los dientes y se trató de imbécil, en su fuero interno, por supuesto. Al llegar a esta conclusión llevó a su alojamiento mucho peor humor y disgusto que sacara de él. Sin embargo, atrajo su curiosidad hasta cierto punto el barullo producido en casa de Catalina Ivanovna, a causa de los preparativos de la comida. Ya había oído hablar la víspera de este banquete; es más, recordaba que le habían invitado; pero sus ocupaciones personales le hicieron que lo olvidara.\"},{\"heading\":false,\"text\":\"En ausencia de Catalina Ivanovna (que a la sazón se hallaba en el cementerio), la señora Lippevechzel andaba atareada alrededor de la mesa, que ya estaba puesta. Hablando con la patrona, Pedro Petrovitch supo que se trataba de una verdadera comida de gala, a la que estaban invitados casi todos los vecinos de la casa, y entre ellos muchos que no habían conocido siquiera al difunto. El propio Andrés Semenovitch recibió la invitación correspondiente, a pesar de estar reñido con Catalina Ivanovna. En fin, se tendría mucho gusto en que Pedro Petrovitch honrase aquella comida con su presencia, puesto que era, entre todos los inquilinos, el personaje más importante. La viuda de Marmeladoff, olvidando todos sus resentimientos con la patrona, había invitado también a Amalia Ivanovna, la cual se ocupaba, en aquellos momentos, con íntima satisfacción, en los preparativos de la comida. Además, la señora Lippevechzel habíase vestido de ceremonia, y aunque su traje era de duelo, se comprendía que su dueña sentía vivo placer en exhibir sus galas. Enterado de todos estos pormenores, Pedro Petrovitch tuvo una idea y entró pensativo en su habitación, o mejor dicho, en la de Andrés Semenovitch Lebeziatnikoff: acababa de saber que Raskolnikoff figuraba en el número de los invitados.\"},{\"heading\":false,\"text\":\"Aquel día Andrés Semenovitch había pasado toda la mañana en su cuarto. Entre este individuo y Ludjin existían extrañas relaciones perfectamente explicables. Pedro Petrovitch le odiaba y le despreciaba en grado superlativo casi desde el mismo día que fué a su casa a pedirle hospitalidad; además, parecía tenerle en poco.\"},{\"heading\":false,\"text\":\"Al llegar a San Petersburgo, Ludjin fué a casa de Lebeziatnikoff, en primer lugar y sobre todo por economía, pero también por otro motivo. En su provincia había oído hablar de Andrés Semenovitch, su antiguo pupilo, como de uno de los progresistas jóvenes más avanzados de la capital y como hombre que ocupaba puesto visible en ciertos círculos ya legendarios. Esta circunstancia tenía mucho valor para Pedro Petrovitch, el cual desde hacía tiempo experimentaba un vago temor respecto a estos círculos poderosos que lo sabían todo, que no respetaban a nadie y hacían la guerra a todo el mundo.\"},{\"heading\":false,\"text\":\"Huelga añadir que la distancia no le permitía tener noción exacta de estas cosas. Como tantos otros, había oído decir que existían en San Petersburgo progresistas, nihilistas, enderezadores de entuertos, etcétera; pero en su espíritu, como en el de otras muchas personas, estas palabras tenían una significación exagerada. Lo que temía principalmente eran las informaciones dirigidas contra tal o cual individuo por el partido revolucionario. Ciertos recuerdos que se remontaban a los primeros tiempos de su carrera, no contribuían poco a fortificar en su ánimo aquel temor, muy vivo ya desde que acariciaba el sueño de establecerse en San Petersburgo.\"},{\"heading\":false,\"text\":\"Dos personajes de una categoría bastante elevada y que protegieron los comienzos de su carrera, fueron objeto de los ataques de los radicales, que llevaron, empero, las de perder. He aquí porque desde su llegada a la capital, Pedro Petrovitch trataba de enterarse de dónde soplaba el viento, para, en caso de necesidad, granjearse las simpatías de _nuestras jóvenes generaciones_. Contaba con Andrés Semenovitch para que le ayudase. La conversación de Ludjin cuando visitó a Raskolnikoff nos ha demostrado ya que había conseguido apropiarse en parte la fraseología de los reformadores.\"},{\"heading\":false,\"text\":\"Andrés Semenovitch estaba empleado en un Ministerio. Pequeño, desmedrado, escrofuloso, tenía el cabello de un rubio casi blanco y llevaba patillas en forma de chuletas con las cuales estaba orgulloso; casi siempre tenía malos los ojos. Aunque en el fondo era una bella persona, mostraba en su lenguaje una presunción a menudo rayana con la temeridad, lo que hacía extraño contraste con su aspecto enfermizo. Se le consideraba, por lo demás, como uno de los inquilinos _comme il faut_ porque no se embriagaba y pagaba con puntualidad su pupilaje. Aparte de estos méritos, Andrés Semenovitch era en realidad bastante necio. Un arrebato irreflexivo le llevó a afiliarse bajo la bandera del progreso: era uno de esos numerosos incautos que se enamoran de las ideas de moda y desacreditan con sus majaderías una causa a la cual se han unido sinceramente.\"},{\"heading\":false,\"text\":\"No obstante su buen carácter, Lebeziatnikoff acabó por encontrar insoportable a su huésped y antiguo tutor. Pedro Petrovitch, por su parte, correspondíale con la misma antipatía. A despecho de su simplicidad, Andrés Semenovitch comenzaba a advertir que en el fondo Pedro Petrovitch le despreciaba y que con este hombre no se podía ir a ninguna parte. Trató de exponerle el sistema de Fourier y el de Darwin; pero Ludjin, que en un principio se contentó con escucharle burlonamente, no se privaba ahora de decir palabras mortificantes a su joven catequista. Lo cierto es que Ludjin acabó por creer que Lebeziatnikoff era no solamente un imbécil, sino un charlatán desprovisto de toda importancia en su propio partido. Su función especial era la _propaganda_, y todavía no debía de estar muy ducho en ella, porque vacilaba a menudo en sus explicaciones. Decididamente, ¿qué tenía que temer Ludjin de semejante sujeto?\"},{\"heading\":false,\"text\":\"Notemos de paso que desde su instalación en casa de Andrés Semenovitch (sobre todo en los primeros días), Pedro Petrovitch aceptaba con placer, o por lo menos sin protesta, los cumplimientos muy extraños de su huésped cuando éste, por ejemplo, le manifestaba un gran celo por el establecimiento de una nueva _commune_ en la calle de los Burgueses, y cuando le decía: «Es usted demasiado inteligente para enfadarse si su mujer toma un amante un mes después de su matrimonio; un hombre ilustrado como usted no bautizará a sus hijos, etc., etc.» Pedro Petrovitch no pestañeaba al oír que le hablaban de tal modo; tan agradables le eran los elogios, fuesen como fuesen.\"},{\"heading\":false,\"text\":\"Había negociado algunos títulos por la mañana, y ahora, sentado delante de la mesa, recontaba la suma que acababa de recibir. Andrés Semenovitch casi nunca tenía dinero y se paseaba por la habitación afectando no mirar aquellos fajos de billetes de Banco sino con despreciativa indiferencia. Ludjin no creía que aquel desdén fuera sincero. Por su parte, Lebeziatnikoff adivinaba, no sin disgusto, el pensamiento escéptico de su huésped y pensaba que éste se había puesto a contar el dinero para humillarle y recordarle la distancia que la fortuna había establecido entre ambos.\"},{\"heading\":false,\"text\":\"Ahora Pedro Petrovitch estaba mucho peor dispuesto y desatento que nunca. Aunque Lebeziatnikoff desarrollaba su tema favorito, el _comunismo_, el hombre de negocios sólo se interrumpía para hacer de vez en cuando alguna observación burlona y descortés. Pero Andrés Semenovitch seguía imperturbable. El mal humor de Ludjin se explicaba a sus ojos por el despecho de un enamorado a quien acababan de dejar compuesto y sin novia. También intentó buscar este motivo de conversación con objeto de consolar a su respetable amigo.\"},{\"heading\":false,\"text\":\"--Parece que se prepara una comida de duelo en casa de esa... viuda--dijo a quema ropa Ludjin interrumpiendo a Lebeziatnikoff en el punto más interesante de su peroración.\"},{\"heading\":false,\"text\":\"--¿No lo sabía usted, acaso? Ya le hablé ayer de eso, y le expuse mi opinión sobre tales costumbres... Según tengo entendido, le han invitado a usted. Ayer mismo habló usted con ella.\"},{\"heading\":false,\"text\":\"--Jamás hubiera creído que la miseria en que se encuentra permitiese a esa imbécil gastar en una comida todo el dinero que le entregó ese otro imbécil de Raskolnikoff. Ahora, al entrar, me he quedado estupefacto viendo todos esos preparativos, todos esos vinos... Ha invitado a muchas personas; el diablo sabrá por qué--continuó Pedro Petrovitch, que parecía haber provocado con intención deliberada aquella conversación--. ¿Qué? ¿Dice usted que me ha invitado?--añadió de repente, levantando la cabeza--. ¿Cuándo ha sido eso? No lo recuerdo. De todas maneras, no pienso ir. ¿Qué tengo que hacer allí? No la conozco más que por haber hablado un minuto con ella ayer; le dije que como viuda de empleado podría obtener un subsidio. ¿Me habrá invitado por eso?\"},{\"heading\":false,\"text\":\"--Tampoco yo tengo intención de asistir--repuso Lebeziatnikoff.\"},{\"heading\":false,\"text\":\"--¡Pues no faltaba más! Después de haberle pegado, natural es que tenga usted escrúpulo de ir a sentarse a su mesa.\"},{\"heading\":false,\"text\":\"--¿A quién he pegado yo? ¿De quién habla usted?--preguntó Lebeziatnikoff turbado y encendido como la grana.\"},{\"heading\":false,\"text\":\"--Hablo de Catalina Ivanovna, a quien pegó usted hará cosa de un mes. Lo supe ayer; ¡ésas son sus convicciones!... ¡Vaya una manera de resolver el problema feminista!\"},{\"heading\":false,\"text\":\"Después de esta salida, que pareció haberle aliviado un poco el corazón, Ludjin se puso a contar de nuevo su dinero.\"},{\"heading\":false,\"text\":\"--Eso es una barbaridad y una calumnia--replicó vivamente Lebeziatnikoff, a quien desagradaba que le recordasen aquel suceso--. Las cosas no pasaron de ese modo; lo que le han contado a usted es completamente falso. En las circunstancias a que usted alude yo no hice más que defenderme. Fué Catalina Ivanovna la que se lanzó sobre mí para arañarme... Me arrancó una de las patillas. Creo que todo hombre tiene derecho a defenderse. Por otra parte, soy enemigo de la violencia, de dondequiera que proceda, y eso por principio, porque la violencia tiene su origen en el despotismo. ¿Qué iba a hacer yo? ¿Había de dejar que esa señora me maltratase a su gusto? Me limité a rechazar una agresión.\"},{\"heading\":false,\"text\":\"--¡Je, je, je!--continuó en son de burla Ludjin.\"},{\"heading\":false,\"text\":\"--Usted me busca querella porque está de mal humor; pero eso no significa nada ni tiene relación alguna con la cuestión feminista. Precisamente yo me he hecho a mí mismo este razonamiento: admitiendo que la mujer es igual al hombre en todo, aun en la fuerza (cosa que se comienza ya a sostener), debe existir también la igualdad en esto. Claro es que he reflexionado inmediatamente que, en rigor, no hay motivo para que se plantee esta cuestión, porque en la sociedad futura no habrá ocasiones de querellas, y, por consiguiente, nadie pasará a vías de hecho... Es, por lo tanto, absurdo hablar de la igualdad en la lucha. No soy tan tonto... Aunque por lo demás haya riñas... es decir, que más tarde no las habrá, aunque por el momento las haya todavía. ¡Ah, diablo, con usted, uno se hace un lío! ¡No, no es eso lo que me impide aceptar la invitación de Catalina Ivanovna! Si no voy a comer a su casa, es sencillamente por cuestión de principios, por no sancionar con mi presencia la estúpida costumbre de las comidas de duelo. Por lo demás, yo podría reírme de eso e ir... Desgraciadamente no habrá allí _popes_; si los hubiese, le aseguro a usted que iría.\"},{\"heading\":false,\"text\":\"--¿De modo que se sentaría usted a su mesa para insultar la hospitalidad de esa mujer?\"},{\"heading\":false,\"text\":\"--No para insultarla, sino para protestar; y esto con un objeto útil. Yo puedo indirectamente ayudar a la propaganda civilizadora, que es el deber de todo hombre. Quizá se realiza esta tarea tanto mejor cuanto menos formalismo se emplea en ella. Puedo sembrar la idea, el grano... De ese grano nacerá un hecho. ¿Cree usted que obrando así se falta a las conveniencias? Al pronto se molestan; pero comprenden al punto que se les presta un gran servicio...\"},{\"heading\":false,\"text\":\"--¡Vamos, bueno!--interrumpió Pedro Petrovitch--. Pero, dígame usted ahora, ¿conoce usted a la hija del difunto, a esa muchacha flacucha? ¿Es verdad lo que de ella se dice?\"},{\"heading\":false,\"text\":\"--Sí, señor; ¿y qué? Según mi opinión, es decir, según mi convicción personal, su situación es la situación normal de la mujer. ¿Por qué no? Es decir, distingamos. En la sociedad actual, sin duda, ese género de vida no es normal, porque es forzado; pero en la sociedad futura será perfectamente normal, porque será libre. Aun ahora mismo tiene el derecho de hacer lo que hace. Era desgraciada, ¿por qué no ha de disponer de lo que es su capital? En la sociedad futura el capital no tendrá razón de ser; pero el papel de la mujer galante tendrá otro sentido y será regulado de una manera racional. En cuanto a Sofía Semenovna, yo, en el tiempo presente, considero sus actos como una enérgica protesta contra la organización de la sociedad, y a causa precisamente de eso, la estimo profundamente; diré más, la contemplo con regocijo.\"},{\"heading\":false,\"text\":\"--Sin embargo, me han contado que usted la obligó a abandonar esta casa.\"},{\"heading\":false,\"text\":\"Lebeziatnikoff se incomodó.\"},{\"heading\":false,\"text\":\"--¡Eso es también una mentira!--replicó enérgicamente--. No ha habido tal cosa. Catalina Ivanovna ha contado esa historia de un modo inexacto porque no la ha comprendido. Yo no he solicitado jamás los favores de Sofía Semenovna; me limitaba pura y simplemente a desenvolver su espíritu, sin ninguna segunda intención personal, esforzándome por despertar en ella el sentimiento de protesta... No he procurado otra cosa; ella es la que ha comprendido que no podía permanecer aquí.\"},{\"heading\":false,\"text\":\"--¿La ha invitado usted a formar parte de la _commune_?\"},{\"heading\":false,\"text\":\"--Sí, actualmente me esfuerzo para atraerla a la _commune_. Sólo que ella estará en otras condiciones que aquí. ¿De qué se ríe usted? Queremos fundar nuestra _commune_ sobre bases mucho más amplias que las precedentes. Vamos más lejos que nuestros precursores; negamos muchas cosas. Si Dobroliuboff y Bielinsky saliesen de sus tumbas, me tendrían por adversario. En tanto, continúo desarrollando a Sofía Semenovna. Es una bella, una bellísima naturaleza.\"},{\"heading\":false,\"text\":\"--¿Y usted se aprovecha de esa bella naturaleza? ¡Je, je, je!\"},{\"heading\":false,\"text\":\"--No, de ninguna manera; todo lo contrario.\"},{\"heading\":false,\"text\":\"--¿Lo contrario?--dijo Ludjin--. ¡Je, je, je!\"},{\"heading\":false,\"text\":\"--Puede usted creerme. ¿Por qué había de ocultárselo a usted? Al contrario, hay una cosa que me asombra: conmigo parece cortada; tiene como cierto tímido pudor.\"},{\"heading\":false,\"text\":\"--Y, es claro, usted la desarrolla. ¡Je, je, je!... Usted le demuestra que todos esos pudores son estúpidos.\"},{\"heading\":false,\"text\":\"--No hay tal cosa, no hay tal cosa. ¡Oh, qué sentido tan grosero y tan tonto, permita que se lo diga, da usted a la palabra desarrollo! ¡Oh Dios mío; qué poco avanzado está usted todavía! ¡Usted no comprende nada! Nosotros buscamos la libertad de la mujer, y usted sólo piensa en bagatelas. Dejando a un lado el pudor y la castidad femeninos, que no hacen al caso, yo admito perfectamente su reserva respecto de mí, puesto que en ello no hace otra cosa que ejercer su libertad y usar de su derecho. Seguramente si me dijese ella misma «yo te quiero», me alegraría mucho, porque esa mujer me gusta en extremo; pero en la situación presente nadie se ha mostrado jamás más cortés y más conveniente con ella que yo; nadie ha hecho más justicia a su mérito... Yo aguardo, espero: eso es todo.\"},{\"heading\":false,\"text\":\"--¿Por qué no le hace usted un regalito? Apuesto a que no ha pensado en eso.\"},{\"heading\":false,\"text\":\"--No comprende usted nada, ya se lo he dicho. Sin duda su situación autoriza en cierto modo sus sarcasmos; pero la cuestión es otra. Usted no tiene más que desprecios para ella. Fundándose en un hecho que le parece deshonroso, rehusa usted considerar con humanidad a una criatura humana. Usted no sabe qué naturaleza es la suya.\"},{\"heading\":false,\"text\":\"--Dígame--replicó Ludjin--, ¿podría usted... o por mejor decir, está usted bastante relacionado con esa joven para suplicar que venga aquí un instante? Deben de haber vuelto ya del cementerio. Me parece que las he oído subir la escalera. Quisiera hablar un instante con la muchacha.\"},{\"heading\":false,\"text\":\"--¿Para qué?--preguntó asombrado Andrés Semenovitch.\"},{\"heading\":false,\"text\":\"--Es menester que le hable. Tengo que irme de aquí hoy o mañana, y necesito decirle una cosa. Puede usted asistir a nuestra conferencia, y aun creo que será mejor que asista. De lo contrario, ¡sabe Dios lo que usted pensaría!\"},{\"heading\":false,\"text\":\"--No pensaría nada... Mi pregunta no tenía importancia. Si tiene usted algo que decirle nada es más fácil que hacerla venir. Voy a buscarla en seguida, y esté seguro de que no le molestaré.\"},{\"heading\":false,\"text\":\"Efectivamente; cinco minutos después, Lebeziatnikoff condujo a Sonia. La joven llegó extremadamente sorprendida y avergonzada. En semejantes circunstancias era siempre muy tímida. Las nuevas caras le causaban temor. Era esto como una impresión de su infancia, y la edad había aumentado su salvajez... Pedro Petrovitch se mostró cortés y benévolo. Al recibir él, hombre serio y respetable, a una muchacha tan joven y en cierto sentido tan interesante, se creyó obligado a acogerla con un ligero tinte de jovial familiaridad. Se apresuró a tranquilizarla y la invitó a que tomase asiento frente a él. Sonia se sentó y miró sucesivamente a Lebeziatnikoff y el dinero colocado sobre la mesa. Después, de repente, sus ojos se fijaron en Pedro Petrovitch y no pudieron apartarse de él; hubiérase dicho que sufría una especie de fascinación. Lebeziatnikoff se dirigió a la puerta. Ludjin se levantó, hizo seña a Sonia para que se sentase, y detuvo a Andrés Semenovitch en el momento en que éste iba a salir.\"},{\"heading\":false,\"text\":\"--¿Raskolnikoff está ahí? ¿Ha venido?--le preguntó en voz baja.\"},{\"heading\":false,\"text\":\"--¿Raskolnikoff? Sí. ¿Y qué? Sí, está ahí. Acaba de llegar. Le he visto... ¿Y qué?\"},{\"heading\":false,\"text\":\"--En ese caso suplico a usted encarecidamente que se quede aquí y no me deje a solas con esta... señorita. El negocio de que se trata es insignificante, pero sabe Dios qué conjeturas podrían hacerse. No quiero que Raskolnikoff vaya a creer... ¿Comprende usted por qué digo esto?\"},{\"heading\":false,\"text\":\"--Sí, comprendo, comprendo--respondió Lebeziatnikoff--. Está usted en su derecho. Sin duda, en mi convicción personal, los temores de usted son muy exagerados, pero... no importa, está usted en su derecho. Bueno, me quedaré. Voy a ponerme cerca de la ventana. No les molestaré; en mi opinión, está usted en su derecho.\"},{\"heading\":false,\"text\":\"Pedro Petrovitch volvió a sentarse enfrente de Sonia, y la contempló atentamente. Después su rostro tomó una expresión muy grave, casi severa, como si indicase: «No vaya usted a figurarse, señorita, cosas que no son». Sonia perdió por completo su serenidad.\"},{\"heading\":false,\"text\":\"--Ante todo suplico a usted, Sonia Semenovna, que presente mis excusas a su respetable mamá. Supongo que no me engaño al expresarme así. Catalina Ivanovna hace con usted veces de madre, ¿no es verdad?--dijo Pedro Petrovitch con tono muy serio, pero a la vez bastante amable.\"},{\"heading\":false,\"text\":\"Evidentemente sus intenciones eran muy amistosas.\"},{\"heading\":false,\"text\":\"--Sí, en efecto: hace conmigo veces de madre--se apresuró a responder la pobre Sonia.\"},{\"heading\":false,\"text\":\"--Pues bien, dígale usted cuánto siento que circunstancias independientes de mi voluntad me impidan aceptar su amable invitación.\"},{\"heading\":false,\"text\":\"--Voy a decírselo--y Sonia se levantó en seguida.\"},{\"heading\":false,\"text\":\"--No es eso todo--continuó Pedro Petrovitch sonriendo al ver la candidez de la joven y su ignorancia de las costumbres sociales--; usted apenas me conoce, Sonia Semenovna; comprenderá que, por un motivo tan fútil y que sólo me interesa a mí, no me hubiera permitido molestar a una persona como usted. Tengo otro objeto.\"},{\"heading\":false,\"text\":\"A una señal de su interlocutor Sonia se apresuró a sentarse. Los billetes de Banco multicolores, colocados sobre la mesa, se ofrecieron de nuevo ante su vista, pero volvió vivamente los ojos y los fijó en Pedro Petrovitch; mirar el dinero ajeno le parecía cosa por extremo inconveniente, sobre todo en su posición. La joven reparó cosa tras cosa: primero, en los lentes de montura de oro que Pedro Petrovitch tenía en la mano izquierda; después, en el grueso anillo adornado con una piedra amarilla que el funcionario llevaba en el dedo del corazón; por último, no sabiendo qué hacer de sus ojos, los fijó en el rostro mismo de Ludjin. Este, después de haber guardado silencio durante algunos instantes, prosiguió:\"},{\"heading\":false,\"text\":\"--Ayer me bastó cambiar dos palabras con la desgraciada Catalina Ivanovna, para comprender que esa señora se encuentra en un estado antinatural, por decirlo así...\"},{\"heading\":false,\"text\":\"--Sí, antinatural--repitió dócilmente Sonia.\"},{\"heading\":false,\"text\":\"--O, para hablar más sencilla e inteligiblemente, que se halla enferma.\"},{\"heading\":false,\"text\":\"--Sí, más sencillamente, más intel... Sí, está enferma...\"},{\"heading\":false,\"text\":\"--Cierto. Por un sentimiento de humanidad y, digámoslo así, de compasión, quisiera, por mi parte, serle útil, previendo que inevitablemente va a encontrarse en una situación muy triste. Ahora, según parece, esa familia no tiene en el mundo otro apoyo que usted.\"},{\"heading\":false,\"text\":\"Sonia se levantó bruscamente.\"},{\"heading\":false,\"text\":\"--Permítame que le pregunte: ¿no le ha dicho usted que podría cobrar una pensión? Ayer me contó que usted se había encargado de hacer que se la concediesen. ¿Es eso cierto?\"},{\"heading\":false,\"text\":\"--No, no hay tal cosa. Me limité a decirle que, como viuda de un funcionario muerto en el servicio, podría obtener un recurso temporal si contaba con recomendaciones. Mas parece que, lejos de haber servido bastante tiempo para disfrutar de los derechos pasivos, su padre no estaba en el servicio cuando murió. En una palabra: siempre se puede esperar; pero la esperanza es muy poco fundada, porque, en rigor, no existe derecho alguno a pensión; al contrario... ¡Ah, soñaba con una pensión! ¡Oh, esa señora lo cree todo posible!\"},{\"heading\":false,\"text\":\"--Sí, soñaba en una pensión. Es crédula y buena, y su bondad hace que dé crédito a todo. Y... y... su espíritu es... sí... Dispénsela usted--dijo Sonia, que se levantó de nuevo para marcharse.\"},{\"heading\":false,\"text\":\"--Permítame usted, tengo todavía que decirle algo más.\"},{\"heading\":false,\"text\":\"--¿Más aún?--balbuceó la joven.\"},{\"heading\":false,\"text\":\"--Siéntese usted.\"},{\"heading\":false,\"text\":\"Sonia, toda confusa, se sentó por tercera vez.\"},{\"heading\":false,\"text\":\"--Viéndola en tal situación, con hijos pequeños, quisiera, como ya le he dicho, serle útil en la medida de mis medios; compréndame usted bien: en la medida de mis medios nada más. Se podría, por ejemplo, organizar, en beneficio suyo, una subscripción, una tómbola... o una cosa análoga, como suelen hacer en caso semejante las personas que desean ayudar, bien sea a los parientes, bien a los extraños. Esto es una cosa posible.\"},{\"heading\":false,\"text\":\"--Sí, eso está bien... pero ella. Dios...--murmuró Sonia, con los ojos fijos en Pedro Petrovitch.\"},{\"heading\":false,\"text\":\"--Se podría; pero ya hablaremos de esto más tarde, es decir, se podría comenzar hoy mismo. Nos veremos esta noche, hablaremos y echaremos, por decirlo así, los fundamentos. Venga usted aquí a las siete. Supongo que Andrés Semenovitch no tendrá inconveniente en asistir a nuestra conferencia, pero... hay un punto que debe de ser previa y cuidadosamente examinado. Por esta razón me he tomado la libertad de molestarle suplicándole que viniese. Según mi opinión, no conviene entregar en sus propias manos el dinero a Catalina Ivanovna; es más, sería peligroso entregárselo; basta como prueba la comida de hoy. No tiene zapatos; no sabe si dentro de dos días tendrá un pedazo de pan que llevarse a la boca, y compra ron Jamaica, vino de Madera y café. Lo he visto al pasar. Mañana toda la familia volverá a estar a cargo de usted, y tendrá usted que buscarle hasta el último pedazo de pan. Por lo tanto, soy de opinión que debe de organizarse la suscripción sin que se entere la desgraciada viuda, y que usted sola sea la que maneje el dinero. ¿Qué le parece a usted?\"},{\"heading\":false,\"text\":\"--No sé. Es solamente hoy cuando ella... Esto no ocurre más que una vez en la vida... Quería honrar la memoria del difunto... pero es muy inteligente. Por lo demás, será lo que usted quiera; yo le quedaré a usted muy... muy... todas ellas serán... y Dios... y los huérfanos...\"},{\"heading\":false,\"text\":\"Sonia no acabó y se echó a llorar.\"},{\"heading\":false,\"text\":\"--De modo que es cosa convenida. Ahora dígnese usted aceptar, para la parienta de usted, esta suma, que representa mi suscripción personal. Deseo vivamente que mi nombre no se pronuncie para nada. Siento mucho que, teniendo yo también apuros pecuniarios, no pueda hacer más.\"},{\"heading\":false,\"text\":\"Y Pedro Petrovitch alargó a Sonia un billete de diez rublos, después de haberlo desplegado cuidadosamente.\"},{\"heading\":false,\"text\":\"La joven recibió el billete ruborizándose, balbuceó algunas palabras ininteligibles y se apresuró a despedirse. Pedro Petrovitch la acompañó hasta la puerta. Al cabo la joven salió de la habitación y entró en la de Catalina Ivanovna extraordinariamente agitada.\"},{\"heading\":false,\"text\":\"Durante toda esta escena, Andrés Semenovitch, no queriendo interrumpir la conversación, permaneció cerca de la ventana. En cuanto salió Sonia, se acercó a Pedro Petrovitch y le tendió solemnemente la mano.\"},{\"heading\":false,\"text\":\"--Lo he oído y lo he visto todo--dijo subrayando intencionadamente la última palabra--. Eso es noble, es humano, quiero decir, porque no admito la palabra noble. Usted ha querido evitar las gracias, lo he visto; y aunque, a decir verdad, soy por principio enemigo de la beneficencia privada, que, lejos de extirpar radicalmente la miseria, favorece sus progresos, no puedo menos de reconocer que he visto con gusto el acto de usted. Sí, sí, eso me complace.\"},{\"heading\":false,\"text\":\"--Lo que he hecho no vale nada--murmuró Ludjin un poco cortado, y miró a Lebeziatnikoff con particular atención.\"},{\"heading\":false,\"text\":\"--Sí, vale, sí vale. Un hombre que, no obstante hallarse bajo la impresión de una afrenta recibida, es capaz todavía de interesarse por la desgracia ajena, aunque proceda en contra de la sana economía social, no es por eso menos digno de estima. No esperaba yo semejante cosa de usted, Pedro Petrovitch... ¡Oh, qué influído está usted por sus antiguas ideas! ¿Por qué turbarse tanto por el asunto de ayer?--exclamó Andrés Semenovitch, que experimentaba un retroceso de viva simpatía hacia Pedro Petrovitch--. ¿Qué necesidad tiene usted de casarse, de casarse _legalmente_, mi noble y muy querido Pedro Petrovitch? ¿Qué le importa a usted la unión _legal_? Pégueme usted, si quiere; pero yo me regocijo del fracaso de sus relaciones, contento de pensar que es usted libre, que no está usted perdido por la humanidad... Ya ve si soy franco.\"},{\"heading\":false,\"text\":\"--Me inclino al matrimonio legal, porque no quiero llevar... nada en la frente ni educar hijos de los cuales yo no sea el padre, como ocurre con vuestros matrimonios libres--respondió, por decir alguna cosa, Pedro Petrovitch.\"},{\"heading\":false,\"text\":\"Estaba pensativo, y apenas prestaba atención a las palabras que decía.\"},{\"heading\":false,\"text\":\"--¿Los hijos? ¿Usted hace alusión a los hijos?--dijo Andrés Semenovitch, animándose de repente como un caballo en batalla cuando oye el sonido del clarín--; los hijos son una cuestión social que será resuelta ulteriormente. Muchos hasta lo niegan sin restricción, como todo lo que concierne a la familia. Hablaremos de los hijos más tarde. Ahora ocupémonos de lo otro. Le confieso a usted que es ésa mi debilidad. Esa palabra baja y grosera, puesta en circulación por Putskin, para señalar a los maridos engañados, no figurará en los diccionarios del porvenir. En resumen: ¿qué viene a ser eso? ¡Oh, ridículo espanto! ¡Qué cosa tan insignificante! Por el contrario, en el matrimonio libre, el peligro que usted teme no existirá. Eso no es más que la consecuencia natural, y, por decirlo así, el correctivo del matrimonio legal, la protesta contra un lazo indisoluble; desde este punto de vista no tiene nada de humillante... Y si, por acaso, lo que es absurdo, contrajese yo un matrimonio legal, sería para mí un encanto llevar _eso_ a que tiene usted tanto miedo. Yo le diría entonces a mi mujer: «Hasta el presente, querida mía, sólo había sentido amor por ti: pero ahora te estimo, porque has sabido protestar». ¿Se ríe usted? ¡Ah! Es porque no tiene fuerzas para romper con los prejuicios. Comprendo que con la unión legítima sea desagradable ser engañado; pero ése es el efecto miserable de una situación que desagrada a los dos esposos. Cuando _eso_ se yergue sobre nuestra frente como en el matrimonio libre, entonces no existe. Cesan de tener significación y dejan de llevar el nombre que se les da. Antes bien, la mujer de usted le prueba por ello que le estima, puesto que le cree incapaz de poner obstáculo a su felicidad, y demasiado ilustrado es usted para querer vengarse de un rival. En verdad, pienso muchas veces que, si llegase a estar casado (libre o legítimamente, importa poco), y mi mujer tardase en tomar un amante, yo, por mí mismo, se lo proporcionaría. «Querida mía (le diría entonces), te amo; pero deseo, sobre todo, que me estimes.» ¿Tengo o no tengo razón?\"},{\"heading\":false,\"text\":\"Estas palabras apenas hicieron sonreír a Pedro Petrovitch. Su pensamiento estaba en otra parte y se restregaba las manos muy preocupado. Andrés Semenovitch había de acordarse más tarde de la preocupación de su amigo.\"}]},{\"title\":\"quinta parte — capítulo II\",\"blocks\":[{\"heading\":false,\"text\":\"Difícil sería decir con exactitud cómo había nacido en el cerebro desequilibrado de Catalina Ivanovna la idea de aquella insensata comida. Gastó, en efecto, en dicho banquete más de la mitad del dinero que le había dado Raskolnikoff para las exequias de Marmeladoff. Tal vez se creía obligada a honrar «convenientemente» la memoria de su marido, a fin de demostrar a todos los inquilinos, y especialmente a Amalia Ivanovna, que el difunto valía tanto como ellos, si era que no valía más. Quizá obedecía a ese orgullo de los pobres que en determinadas circunstancias de la vida, como bautizo, matrimonio, entierro, etc., los impulsa a sacrificar sus últimos recursos con el solo objeto de «hacer las cosas tan bien como los otros». Permitido es suponer que, en el momento mismo en que se veía reducida a la más extremada miseria, Catalina Ivanovna quería mostrar a toda aquella «gentuza», no solamente que ella sabía «vivir y recibir», sino que, hija de un coronel, educada «en una casa noble y aristocrática», no había nacido para fregar el suelo con sus propias manos y lavar por la noche la ropa de sus hijos.\"},{\"heading\":false,\"text\":\"Las botellas de vino no eran ni muy numerosas ni de marcas muy variadas; faltaba el Madera. Pedro Petrovitch había exagerado. Sin embargo, había aguardiente, ron, Oporto, todo de inferior calidad, pero en abundancia. El _menú_, preparado en la cocina de Amalia Ivanovna, comprendía, además del _kutia_, tres o cuatro platos, principalmente _blines_; además, estaban preparados dos samovars para los convidados que quisieran tomar te o ponche después de la comida. Catalina Ivanovna se ocupó por si misma en las compras, con ayuda de un inquilino de la casa, un polaco famélico, que habitaba, sabe Dios en qué condiciones, en casa de la señora Lippevechzel.\"},{\"heading\":false,\"text\":\"Desde el primer momento este pobre hombre se puso a disposición de la viuda, y durante treinta y seis horas no dejó de hacer recados con celo que, por otra parte, el bueno del polaco no perdía ripio para hacerlo notar. A cada instante, por la menor futesa, todo presuroso y atareado acudía a pedir instrucciones a la viuda Marmeladoff. Después de haber declarado que sin la solicitud de este «hombre servicial y magnánimo», no hubiera sabido qué hacer, Catalina Ivanovna acabó por encontrarlo absolutamente insoportable. Era propio de su carácter entusiasmarse de repente por cualquiera; le veía con los colores más brillantes y le atribuía mil méritos que sólo existían en su imaginación, pero en los cuales creía con toda buena fe. Después al entusiasmo sucedía bruscamente la desilusión, y entonces se desataba en injurias contra aquel a quien pocas horas antes había colmado de excesivas alabanzas.\"},{\"heading\":false,\"text\":\"Amalia Ivanovna tomó también súbita importancia a los ojos de Catalina Ivanovna; ésta delegó en ella, cuando se fué al entierro, todos sus poderes, y la señora Lippevechzel se mostró digna de esta confianza. Ella fué, en efecto, quien se encargó de preparar la mesa y de suministrar el servicio de la misma. Claro es que la vajilla, los vasos, las tazas, los tenedores, los cuchillos, prestados por los diversos inquilinos, mostraban en su rica variedad sus diversos orígenes; pero en aquel momento cada cosa estaba en su puesto. Cuando volvió a la casa mortuoria, Catalina Ivanovna pudo advertir una expresión de triunfo en el rostro de la patrona. Orgullosa de haber cumplido tan bien su misión, aquélla se pavoneaba con su traje de duelo completamente nuevo, y su gorrito adornado con lazos. Este orgullo, por legítimo que fuese, no agradó a la viuda: «¡Como si verdaderamente no se hubiera podido poner la mesa sin Amalia Ivanovna!» El gorrito con sus lazos flamantes también le disgustó: «¡Vaya con la tonta alemana esta que no hace más que estorbar!... ¡Se ha dignado, por bondad de alma! ¡Habráse visto! En casa del padre de Catalina Ivanovna, que era coronel, había algunas veces cuarenta personas a comer, y no se hubiera recibido ni aun para el servicio, a una Amalia Ivanovna, o, mejor dicho, Ludvigovna.» La viuda de Marmeladoff no quiso manifestar entonces sus sentimientos; pero se prometió no quedarse con esta impertinencia en el cuerpo.\"},{\"heading\":false,\"text\":\"Otra circunstancia contribuyó también a irritar a Catalina Ivanovna: a excepción del polaco que fué hasta el cementerio, casi ninguno de los invitados acompañó el cadáver hasta su última morada; por el contrario, cuando se trató de sentarse a la mesa, se vió llegar todo lo que había de más pobre y de menos recomendable entre los inquilinos; algunos se presentaron en traje más que descuidado. Los que estaban un poco limpios se habían dado palabra para no venir comenzando por Ludjin, el más distinguido de todos ellos. Sin embargo, el día anterior, por la noche, Catalina Ivanovna había cantado las excelencias de él a todo el mundo, es decir, a la patrona, a Poletchka, a Sonia y al polaco. Era, según aseguraban, un hombre muy noble y muy bueno; además de esto, era inmensamente rico y estaba muy bien relacionado. Afirmaba que había sido amigo de su primer marido, y frecuentado también en otro tiempo la casa de su padre. Aseguraba, además, que había prometido emplear toda su influencia para conseguirle una pensión importante.\"},{\"heading\":false,\"text\":\"Raskolnikoff se presentó cuando acababan de llegar del cementerio. Catalina Ivanovna quedó encantada al verle, en primer lugar, porque, de todas las personas presentes, era el único hombre culto (lo presentó a todos los invitados, diciendo que dentro de dos años sería catedrático de la Universidad de San Petersburgo), y además, por haberse excusado respetuosamente de no haber podido, a pesar de sus deseos, asistir a las exequias. La viuda se apresuró a hacerle sentar a su izquierda, teniendo ya a Amalia Ivanovna sentada a su derecha, y entabló a media voz con el joven una conversación tan seguida como se lo permitían sus deberes de dueña de casa.\"},{\"heading\":false,\"text\":\"Su enfermedad había tomado desde hacía dos días un carácter más alarmante que nunca, y la tos, que le desgarraba el pecho, le impedía a menudo terminar las frases. Sin embargo, se consideraba feliz por tener a quien confiar la indignación que experimentaba ante aquel concurso de figuras grotescas. Al principio, su cólera se manifestaba en las burlas que dirigía a los invitados y, sobre todo, a la propietaria.\"},{\"heading\":false,\"text\":\"--Todo ello es por culpa de esa imbécil. Ya sabe usted de quién hablo--y Catalina Ivanovna mostró con un movimiento de cabeza a la patrona--. Mírela usted cómo abre los ojos; adivina que hablamos de ella; pero no puede comprender lo que decimos; ahí tiene usted por qué pone esos ojos de besugo. ¡Ah, qué coqueta!... ¡Ja, ja, ja! ¿Qué idea le ha dado de ponerse ese bonete? ¡Ja, ja, ja! Quiere hacer creer a todo el mundo que me honra mucho sentándose a mi mesa. Le había suplicado que invitase a las personas más distinguidas, y con preferencia a aquellas que habían conocido al difunto, y mire usted qué colección de desharrapados y de perdidos ha reclutado. Fíjese usted: aquél no se ha lavado, da asco; ¿y esos desgraciados polacos?... ¡Ah, ah! ¡Je, je, je! Aquí nadie los conoce, y yo los veo por primera vez. Dígame usted: ¿Por qué han venido? Ahí están como una ristra de cebollas. ¡Eh!--gritó a uno de ellos--. ¿Ha tomado usted _blines_? Tome usted más; beba usted cerveza. ¿Quiere usted aguardiente? Mire, mire, se ha levantado para saludarme. Son, sin duda, pobres diablos muertos de hambre. Todo les es igual con tal de comer. Por lo menos no hacen ruido; pero yo estoy temblando por los cubiertos de la patrona--dijo casi en voz alta, dirigiéndose a Amalia Ivanovna--. Si por acaso roban sus cucharas, le prevengo que yo de nada respondo.\"},{\"heading\":false,\"text\":\"Después de esta satisfacción dada a sus sentimientos, volviéndose hacia Raskolnikoff, dijo, burlándose y mostrando a la patrona:\"},{\"heading\":false,\"text\":\"--¡Ah, ah, ah! No entiende una palabra; ahí se está con la boca abierta. Fíjese usted; es una verdadera lechuza; una lechuza con lazos de colores. ¡Ja, ja, ja!\"},{\"heading\":false,\"text\":\"La risa acabó con un acceso de tos que duró cinco minutos, se llevó el pañuelo a los labios y después se lo enseñó silenciosamente a Raskolnikoff: estaba manchado de sangre. Gotas de sudor perlaban su frente; sus pómulos se coloreaban de rojo, y cada vez respiraba con mayor dificultad; sin embargo, continuó hablando en voz baja con animación extraordinaria.\"},{\"heading\":false,\"text\":\"--Le habían confiado el encargo muy delicado, es verdad, de invitar a esa señora y a su hija. Ya sabe usted a quienes me refiero. Era preciso proceder en esto con bastante tacto... Pues bien, se ha arreglado de modo que esa imbécil forastera, esa provinciana, que ha venido aquí a solicitar una pensión como viuda de un mayor, y que, de la mañana a la noche, anda recorriendo las Cancillerías con dos dedos de colorete en la cara, y eso que tiene cincuenta años muy corridos... esa remilgada ha rehusado mi invitación, sin excusarse siquiera, como la más vulgar cortesía exige en un caso como éste. No acierto a explicarme cómo es que no haya venido tampoco Pedro Petrovitch. Pero, ¿dónde está Sonia? ¿qué es de ella? ¡Ah! Ahí está. ¿Dónde te habías metido, Sonia? Es extraño que en un día como éste hayas sido tan poco exacta. Rodión Romanovitch, déjela usted colocarse a su lado, ése es tu sitio, Sonia; toma lo que quieras. Te recomiendo el _kabial_, está bueno. Ahora te traerán las _blines_. ¿No se ha dado de ellas a los niños? Que no se os olvide, Poletchka. Vamos, está bien. Sé formal, Lena; y tú, Kolia, deja quietecitas las piernas. Eso es; así debe de estar un niño bien educado. ¿Y qué me cuentas, Sonetchka?\"},{\"heading\":false,\"text\":\"Sonia se apresuró a decir a su madrastra las excusas de Pedro Petrovitch, esforzándose en hablar alto para que todos pudieran oírle. No contenta con reproducir las fórmulas corteses de que Ludjin se había servido, procuró por su parte amplificarlas. Pedro Petrovitch--añadió--le había encargado decir a Catalina Ivanovna que vendría tan pronto como le fuese posible, para hablar de _negocios_ y entenderse con ella acerca de la marcha que debía seguir ulteriormente, etcétera, etc.\"},{\"heading\":false,\"text\":\"Sonia sabía que con esto tranquilizaría a su madrastra, y, sobre todo, que halagaría su amor propio. La joven se sentó al lado de Raskolnikoff, a quien saludó apresuradamente echándole una rápida y curiosa mirada; pero durante el resto de la comida evitó mirarle y aun dirigirle la palabra. Parecía distraída, aunque tenía los ojos fijos en el rostro de Catalina Ivanovna para adivinar sus deseos. Después de haber escuchado con complacencia el relato de Sonia, la viuda preguntó con aire de importancia por la salud de Pedro Petrovitch; en seguida, sin inquietarse demasiado de que pudieran oírla los invitados, hizo observar a Raskolnikoff que un hombre tan respetable y distinguido hubiese estado fuera de su centro en semejante reunión. Se explicaba que no hubiese venido, a pesar de las antiguas relaciones que le unían a su familia.\"},{\"heading\":false,\"text\":\"--He aquí por qué, Rodión Romanovitch, agradezco tanto que no haya usted desdeñado mi hospitalidad; por lo demás--añadió--, convencida estoy de que solamente la amistad de usted con mi pobre difunto es lo que ha decidido a cumplirme su palabra.\"},{\"heading\":false,\"text\":\"Raskolnikoff escuchaba en silencio. Se encontraba a disgusto. Unicamente por cortesía y consideración a Catalina Ivanovna probaba la comida, que la propia viuda le acercaba a la boca.\"},{\"heading\":false,\"text\":\"El joven tenía los ojos fijos en Sonia. Esta, cada vez más pensativa, seguía con inquietud los progresos de la exasperación de su madrastra, que había comenzado a burlarse de sus huéspedes, presintiendo que la comida acabaría mal, porque, entre otras cosas, Sonia sabía que era ella la causa principal de que las dos provincianas hubieran rehusado la invitación. Amalia Ivanovna habíale dicho que cuando fué a invitar a las dos señoras, la madre, muy resentida, había exclamado que cómo podría permitir ella que su hija se sentase al lado de aquella... _señorita_. Sospechaba la joven que su madrastra tenía ya noticia de aquel insulto. Esta injuria a Sonia era para Catalina Ivanovna peor que una afrenta hecha a ella, a sus hijos, o a la memoria de su padre; era un mortal ultraje. Sonia adivinaba que a Catalina Ivanovna sólo le importaba en aquel momento probar a aquellas imbéciles que ambas eran... Precisamente un convidado, sentado en el otro extremo de la mesa, dió a Sonia un plato, con dos corazones de migas de pan atravesados por una flecha. Catalina Ivanovna declaró en seguida, con voz sonora, que el autor de aquella burla era, de seguro, un «asno borracho».\"},{\"heading\":false,\"text\":\"Acto seguido anunció su propósito de retirarse en cuanto hubiera obtenido una pensión, a fundar en T***, su ciudad natal, una casa de educación para hijas de nobles. De repente mostró aquel certificado del cual había hablado Marmeladoff cuando su encuentro con Rodia en la taberna. En las circunstancias presentes, tal documento debía establecer el derecho de Catalina Ivanovna a abrir un pensionado; pero lo había sacado con objeto de confundir a las dos «presumidas», y si éstas hubiesen aceptado su invitación, les hubiera demostrado con pruebas convincentes, que «la hija de un coronel, la descendiente de una familia noble y aristocrática, valía mucho más que las buscadoras de aventuras, cuyo número aumenta cada día». El certificado dió pronto la vuelta en derredor de la mesa; los convidados, ya a medios pelos, se lo pasaban de mano en mano, sin que Catalina Ivanovna se opusiese a ello, porque aquel papel la designaba, con todas sus letras, como hija de un consejero de Corte, lo que la autorizaba, aproximadamente, a considerarse como hija de un coronel.\"},{\"heading\":false,\"text\":\"Extendióse después la viuda en enumerar los encantos de la existencia feliz y tranquila que se prometía pasar en T***. Buscaría el concurso de los profesores del Gimnasio, entre los cuales se encontraba un anciano respetable, el señor Mangot, que le había enseñado en otros tiempos el francés; este señor no vacilaría en dar lecciones en su pensionado, y sería módico en sus honorarios. Por último, anunció la intención de llevarse a Sonia a T*** y de confiarle la dirección de su establecimiento. Al oír estas palabras, uno de los comensales se echó a reír.\"},{\"heading\":false,\"text\":\"Catalina Ivanovna fingió no haberlo oído, pero levantando la voz dijo que Sonia Semenovna poseía cuantas cualidades son menester para secundarla en su tarea. Después de haber elogiado la dulzura de la joven, su paciencia, su abnegación, su cultura intelectual y su nobleza de sentimientos, le dió suavemente unos golpecitos en la mejilla y la besó dos veces seguidas con efusión. Sonia se ruborizó, y Catalina Ivanovna prorrumpió en llanto.\"},{\"heading\":false,\"text\":\"--Tengo los nervios muy excitados--dijo como para excusarse--y estoy muy fatigada. La comida ha acabado, se va a servir el te.\"},{\"heading\":false,\"text\":\"Amalia Ivanovna, muy contrariada por no haber podido meter baza en la conversación precedente, eligió aquel momento para aventurar una nueva tentativa, e hizo observar muy juiciosamente a la futura directora de un pensionado, que «debería conceder mucha atención a la ropa interior de las pensionistas e impedir que leyeran novelas durante la noche». El cansancio y la irritación hacían a Catalina Ivanovna poco tolerante; así es que tomó muy a mal aquellos sabios consejos; a creerla a ella, la patrona no entendía una palabra de lo que estaba hablando. «En un pensionado de señoritas nobles, el cuidado de la ropa blanca correspondía a la mujer encargada de ese servicio, y no a la directora del establecimiento. En cuanto a la observación relativa a la lectura de las novelas, era sencillamente una inconveniencia.» Catalina Ivanovna suplicaba a la patrona que callase.\"},{\"heading\":false,\"text\":\"En lugar de acceder a esta súplica, Amalia Ivanovna respondió con acritud que «no había hablado más que por su bien»; que había tenido siempre las mejores intenciones, y que, desde hacía largo tiempo, Catalina Ivanovna no le pagaba un kopek.\"},{\"heading\":false,\"text\":\"--¡Miente usted hablando de buenas intenciones!--replicó la viuda--. Ayer, sin ir más lejos, cuando mi esposo estaba de cuerpo presente, vino usted a armar un escándalo a propósito de mis atrasos, y por causa suya no han venido ciertas señoras...\"},{\"heading\":false,\"text\":\"Al oír esto la patrona observó con mucha lógica que ella «había invitado a aquellas señoras, pero no habían venido porque eran nobles y no podían ir a casa de una señora que no lo era». A lo cual su interlocutora contestó «que una cocinera no tenía criterio para juzgar de la verdadera nobleza».\"},{\"heading\":false,\"text\":\"Herida Amalia Ivanovna en lo vivo replicó «que su _vater_[17] era un hombre muy importante en Berlín que se paseaba constantemente con las manos en los bolsillos y hacía siempre ¡puf! ¡puf!» Para dar una idea más exacta de su _vater_, la señora Lippevechzel se levantó, se metió las manos en los bolsillos e inflando los carrillos se puso a imitar el ruido de un fuelle de fragua. Aquello provocó una carcajada general entre los inquilinos que, con la esperanza de una batalla entre las dos mujeres, se complacían en azuzar a Amalia Ivanovna. La viuda de Marmeladoff, no pudiendo contenerse más, declaró en voz muy alta que «Amalia Ivanovna quizá no había tenido nunca _vater_, que era sencillamente una finlandesa de San Petersburgo, que había debido ser en otro tiempo cocinera, o tal vez algo más bajo». Respuesta furiosa de la patrona: «Acaso era Catalina Ivanovna la que no había tenido _vater_. En cuanto a ella, su padre era un berlinés que usaba levitas muy largas y que hacía constantemente ¡puf! ¡puf!» Catalina Ivanovna respondió con tono despreciativo que «su nacimiento era conocido de todo el mundo, y que aquel mismo certificado honorífico en caracteres impresos, la designaba como hija de un coronel, y que, en cambio, Amalia Ivanovna (en el supuesto de que hubiese tenido padre conocido), debía ser hija de algún vendedor de leche finlandés; pero, según todas las apariencias, era hospiciana, puesto que no sabía aún cuál era su nombre patronímico, si se llamaba Amalia Ivanovna o Amalia Ludvigovna». La patrona, fuera de sí, gritó, dando puñetazos sobre la mesa, «que ella era Ivanovna y no Ludvigovna; que su padre se llamaba Juan, y que había sido alcalde, cosa que no fué nunca el padre de Catalina Ivanovna». Al oír tales palabras se levantó ésta, y con voz tranquila, desmentida por la palidez de su rostro y por la agitación de su pecho, dijo:\"},{\"heading\":false,\"text\":\"[17] Padre, en alemán.\"},{\"heading\":false,\"text\":\"--Si usted se atreve otra vez a poner en parangón a su miserable _vater_ con mi padre, le arranco el gorro y lo pisoteo.\"},{\"heading\":false,\"text\":\"Amalia Ivanovna, ante su amenaza, empezó a correr por la habitación, gritando con todas sus fuerzas que ella era la propietaria y que Catalina Ivanovna se marcharía de su casa al instante. Después se apresuró a recoger los cubiertos de plata que estaban sobre la mesa. A esto siguió una confusión y un barullo indescriptible; los chiquillos se echaron a llorar; Sonia se abalanzó a su madrastra para impedir que hiciese un disparate, pero como Amalia Ivanovna hubiese lanzado en alta voz una alusión a la _cartilla amarilla_, Catalina Ivanovna rechazó a la joven y se fué derecha a la patrona, decidida a arrancarle el moño.\"},{\"heading\":false,\"text\":\"Mas en aquel momento se abrió la puerta y apareció Pedro Petrovitch Ludjin.\"},{\"heading\":false,\"text\":\"El funcionario dirigió una mirada severa a todos los presentes y Catalina Ivanovna corrió hacia él.\"}]},{\"title\":\"quinta parte — capítulo III\",\"blocks\":[{\"heading\":false,\"text\":\"--¡Pedro Petrovitch!--gritó--. ¡Protéjame usted! Haga comprender a esta imbécil que no tiene derecho para hablar así a una señora noble y desgraciada; que eso no está permitido. Me quejaré al gobernador general... y esa mujer tendrá que responder ante él de lo que ha dicho. En nombre de la hospitalidad que usted recibió de mi padre, venga en ayuda de mis huérfanos.\"},{\"heading\":false,\"text\":\"--Permítame usted, señora... permítame usted--dijo Pedro Petrovitch apartando con un ademán a la solicitante--. Como usted sabe muy bien, no he tenido el honor de conocer a su padre... Permítame usted, señora (uno de los comensales se echó a reír ruidosamente); no pienso tomar parte en las continuas reyertas de usted con Amalia Ivanovna... Vengo aquí por un asunto personal... Deseo tener inmediatamente una explicación con su hijastra de usted, Sonia... Semenovna... ¿no es ése su nombre? Permítame usted que entre...\"},{\"heading\":false,\"text\":\"Y apartándose de Catalina Ivanovna, Pedro Petrovitch se dirigió al rincón de la sala en que se encontraba Sonia.\"},{\"heading\":false,\"text\":\"La viuda se quedó como clavada en su sitio. No podía comprender que Pedro Petrovitch negase haber sido huésped de su padre. Aquella hospitalidad, que no existía más que en su imaginación, se había convertido para ella en artículo de fe. Lo que principalmente la impresionó, fué el tono seco, altanero, y hasta amenazador de Ludjin. Al aparecer este último se restableció el silencio poco a poco. El pulcro y severo traje del hombre de leyes formaba contraste con la sordidez de los demás inquilinos de Amalia Ivanovna. Cada uno de ellos se daba cuenta de que sólo un motivo de gravedad excepcional podía explicar la presencia de aquel personaje en semejante sitio; todos, pues, esperaban que pasase algo. Raskolnikoff, que estaba sentado al lado de Sonia, se levantó para dejar acercarse a Pedro Petrovitch, y éste pareció no reparar en el joven.\"},{\"heading\":false,\"text\":\"Un instante después apareció Lebeziatnikoff; pero en lugar de entrar en la habitación permaneció en el umbral escuchando con curiosidad sin acertar a comprender al pronto de qué se trataba.\"},{\"heading\":false,\"text\":\"--Perdónenme ustedes que turbe su reunión; pero me veo obligado a ello por un asunto de bastante importancia--dijo Pedro Petrovitch sin dirigirse a nadie en particular--; en cuanto a mí, me agrada poder explicarme delante de una reunión numerosa. Amalia Ivanovna, ruego a usted que, como propietaria de esta casa, preste atención a la conferencia que voy a celebrar con Sonia Semenovna.\"},{\"heading\":false,\"text\":\"Después, dirigiéndose a la joven que estaba extremadamente pálida y bastante sorprendida, añadió:\"},{\"heading\":false,\"text\":\"--Sonia Semenovna, inmediatamente después de la visita de usted, he echado de menos un billete de Banco de cien rublos, que había sobre una mesa de la habitación de mi amigo Andrés Semenovitch Lebeziatnikoff. Si usted sabe lo que ha sido de ese billete y me lo dice, doy a usted, en presencia de todas estas personas, mi palabra de honor de que este asunto no tendrá consecuencias; en caso contrario, me veré obligado a recurrir a medidas muy serias, y entonces... no tendrá usted que echar la culpa a nadie sino a sí misma.\"},{\"heading\":false,\"text\":\"Un profundo silencio siguió a estas palabras. Hasta los niños cesaron de llorar. Sonia, mortalmente pálida, miraba a Ludjin sin acertar a responder. Parecía no haber comprendido aún. Así pasaron algunos segundos.\"},{\"heading\":false,\"text\":\"--Vamos, ¿qué responde usted?--preguntó Pedro Petrovitch, mirando atentamente a la joven.\"},{\"heading\":false,\"text\":\"--Yo no sé... no sé nada--dijo al cabo con voz débil.\"},{\"heading\":false,\"text\":\"--¿No? ¿Usted no sabe nada?--preguntó Ludjin, y dejó pasar nuevamente algunos segundos.\"},{\"heading\":false,\"text\":\"En seguida añadió con tono severo:\"},{\"heading\":false,\"text\":\"--Piense usted en lo que le digo, señorita; reflexione usted; quiero darle tiempo bastante. Si no estuviese completamente seguro de mi afirmación, me guardaría muy mucho de lanzar contra usted una acusación tan grave. Tengo demasiada experiencia en los negocios para exponerme a una querella por difamación. Esta mañana he ido a negociar unos títulos, que representaban un valor nominal de 3.000 rublos. De vuelta en mi alojamiento, me he puesto a contar el dinero; Andrés Semenovitch es testigo. Después de haber contado dos mil trescientos rublos, los he guardado en una cartera que he metido en el bolsillo del pecho de la levita. Quedaban sobre la mesa unos quinientos rublos en billetes de Banco, entre los cuales había tres de cien rublos cada uno. Entonces fué cuando, a invitación mía, vino usted a nuestro cuarto, y durante todo el tiempo de su visita ha estado usted extraordinariamente agitada. Por tres veces se ha levantado usted para salir, aun cuando nuestra conversación no había terminado aún. Andrés Semenovitch puede dar fe de todo esto.\"},{\"heading\":false,\"text\":\"»Usted no negará, así por lo menos lo creo, que la he hecho llamar por Andrés Semenovitch con objeto de ocuparme con usted en la situación desgraciada de su madrastra (a cuya casa no podía venir yo a comer), y de la forma de socorrerla por medio de subscripción, lotería, o cosa parecida. Usted me dió las gracias con las lágrimas en los ojos. (Entro en todos estos pormenores, para probarle que no he olvidado ninguna circunstancia.) Inmediatamente he tomado de encima de la mesa un billete de diez rublos, y se lo he entregado a usted como primer recurso para su madrastra. Andrés Semenovitch lo ha visto todo. Después la he acompañado hasta la puerta, y usted se ha retirado con la misma agitación que antes.\"},{\"heading\":false,\"text\":\"»Cuando usted salió del cuarto, he estado hablando durante diez minutos, aproximadamente, con Andrés Semenovitch. Por último él se marchó y yo me acerqué a la mesa para guardar el resto del dinero, viendo entonces, con gran sorpresa, que me faltaba un billete de cien rublos. Ahora juzgue usted. Yo no puedo sospechar de Andrés Semenovitch, ni siquiera concebir semejante idea. No puedo tampoco engañarme en mis cuentas, porque, un momento antes de que usted entrara, acababa de comprobarlas. Comprenderá usted que acordándome de su agitación, de su prontitud en salir y de que tuvo usted durante algún tiempo las manos sobre la mesa, y considerando, finalmente, la posición social de usted, he debido, a despecho de mi propia voluntad, dar acogida a una sospecha, cruel, sin duda, pero legítima.\"},{\"heading\":false,\"text\":\"»Por convencido que me halle de la culpabilidad de usted, repito que sé a lo que me expongo dirigiéndole esta acusación. Sin embargo, no vacilo en formularla, sobre todo, señorita, por su negra ingratitud. ¿Cómo? La mando llamar a usted porque me intereso por su infortunada madrastra y por sus hermanitos; le doy un billete de diez rublos ¡y me recompensa usted de esa manera! ¡No! ¡Eso no está bien! Le hace falta una lección que le sirva de escarmiento para lo sucesivo. Reflexione usted; se lo propongo amistosamente, porque en este momento es lo mejor que puedo hacer en su favor. De lo contrario, seré inflexible. Vamos, confiese usted.»\"},{\"heading\":false,\"text\":\"--Yo nada he tomado--murmuró Sonia espantada--; usted me ha dado diez rublos; aquí están, tómelos, se los devuelvo.\"},{\"heading\":false,\"text\":\"La joven sacó el pañuelo del bolsillo, deshizo un nudo, tomó el billete de diez rublos, que estaba allí guardado, y se lo alargó a Ludjin.\"},{\"heading\":false,\"text\":\"--¿De modo que insiste usted en negar el robo de esos cien rublos?--dijo en tono de reproche Ludjin, sin tomar el billete.\"},{\"heading\":false,\"text\":\"Sonia dirigió una mirada en torno suyo, y en todos los rostros de las personas que la rodeaban sorprendió una expresión severa, irritada o burlona. La joven miró a Raskolnikoff. Este, en pie, apoyado contra la pared, tenía los brazos cruzados y sus ojos llameantes fijos en ella.\"},{\"heading\":false,\"text\":\"--¡Señor, señor!--gimió la muchacha.\"},{\"heading\":false,\"text\":\"--Amalia Ivanovna, será menester llamar a la policía; por lo tanto, suplico a usted humildemente que haga subir al _dvornik_--dijo Ludjin con voz dulce y hasta cariñosa.\"},{\"heading\":false,\"text\":\"--_Gott der barmherzig!_ ¡Bien sabía yo que ésta era una ladrona!--exclamó la señora Lippevechzel palmoteando.\"},{\"heading\":false,\"text\":\"--¿Usted lo sabía?--repuso Pedro Petrovitch--; eso quiere decir que ya ciertos hechos anteriores autorizan a usted a deducir esta consecuencia. Suplico a usted, dignísima Amalia Ivanovna, que no olvide las palabras que acaba de pronunciar. Por lo demás, hay testigos.\"},{\"heading\":false,\"text\":\"En todos lados se hablaba ruidosamente.\"},{\"heading\":false,\"text\":\"--¿Cómo?--exclamó Catalina Ivanovna, saliendo de repente de su estupor, y con rápido movimiento se precipitó hacia Ludjin--. ¿Cómo? ¿La acusa usted de robo? ¿A ella? ¿A Sonia? ¡Oh, cobarde!\"},{\"heading\":false,\"text\":\"Después se aproximó vivamente a la joven y la estrechó entre sus brazos descarnados.\"},{\"heading\":false,\"text\":\"--¿Cómo, Sonia, has podido aceptar diez rublos de él? ¡Oh, tonta! ¡Dámelos! ¡Dame en seguida ese dinero! ¡Así!\"},{\"heading\":false,\"text\":\"Catalina tomó el billete de manos de Sonia, lo arrugó entre sus dedos y se lo tiró a Ludjin a la cara. El papel, hecho una pelota, alcanzó a Pedro Petrovitch y rodó en seguida por el suelo. Amalia Ivanovna se apresuró a levantarlo. El hombre de negocios se incomodó.\"},{\"heading\":false,\"text\":\"--Contengan ustedes a esa loca.\"},{\"heading\":false,\"text\":\"En aquel momento acudieron muchas personas, que se colocaron en el umbral, al lado de Lebeziatnikoff. Entre ellas estaban las dos señoras provincianas.\"},{\"heading\":false,\"text\":\"--¿Loca dices? ¿Me tratas de loca, imbécil?--vociferó Catalina Ivanovna--. ¡Tú, tú eres un imbécil, un vil agente de negocios, un hombre bajo! ¡Sonia! ¿Sonia haber robado dinero? ¿Sonia una ladrona? ¡Pero si ella te daría más que vale ese dinero, imbécil!--y la viuda rompió a reír de un modo nervioso--. ¿Han visto ustedes a este imbécil?--añadió, yendo de uno a otro inquilino y mostrando a Ludjin a cada uno de ellos.\"},{\"heading\":false,\"text\":\"De repente vió a Amalia Ivanovna, y su cólera no tuvo límites.\"},{\"heading\":false,\"text\":\"--¿Cómo, tú también, choricera? ¿Tú también, infame prusiana, dices que Sonia es una ladrona? ¡Ah! ¿Pero esto es posible? ¡Si no ha salido de la habitación! Al venir de tu casa ¡granuja! se puso a la mesa con nosotros; todos la han visto al lado de Rodión Romanovitch... registradla. Puesto que no ha ido a ninguna parte, tendrá el dinero encima. ¡Busca, busca, busca! ¡Pero si no lo encuentras, querido, tendrás que responder de tu conducta! ¡Me quejaré al emperador, al zar misericordioso! ¡Hoy mismo iré a arrojarme a sus pies! ¡Soy huérfana; me dejarán entrar! ¿Crees que no me recibirá? ¡Te engañas! Obtendré una audiencia. ¿Porque Sonia es tan dulce pensabas que no tenías nada que temer? Tú contabas con su timidez, ¿verdad? ¡Pero si ella es tímida, yo, amigo mío, yo no tengo miedo a nada, y así tus cálculos caen por tierra! ¡Busca! ¡Vamos, despáchate!\"},{\"heading\":false,\"text\":\"Y al decir esto, Catalina Ivanovna agarraba a Ludjin por un brazo y le empujaba hacia donde estaba Sonia.\"},{\"heading\":false,\"text\":\"--Si estoy pronto, si no deseo otra cosa... pero, tranquilícese usted, señora, cálmese usted--balbuceaba el funcionario.--Ya veo que no tiene usted miedo. Esto debería hacerse en la oficina de policía. Por lo demás, hay aquí un número más que suficiente de testigos... Sí, yo estoy pronto... no obstante, es muy delicado para un hombre... a causa de su sexo... Si Amalia Ivanovna quisiese prestar su concurso... Sin embargo, no es así como se hacen estas cosas.\"},{\"heading\":false,\"text\":\"--¡Hágala usted registrar por quien quiera!--gritó Catalina Ivanovna--. Sonia, enséñale los bolsillos. ¡Mira, mira, monstruo, ve cómo están vacíos! ¡Aquí no hay más que un pañuelo; mira, nada más que un pañuelo, puedes convencerte de ello! Ahora el otro bolsillo. ¿Ves? ¿ves?\"},{\"heading\":false,\"text\":\"No contenta con vaciar los bolsillos de Sonia, Catalina los volvió, uno después del otro, de dentro afuera. Pero en el momento en que ponía al descubierto el forro del bolsillo derecho, se escapó de él un papelillo, que, describiendo una parábola en el aire, fué a caer a los pies de Ludjin. Todos lo vieron; muchos lanzaron un grito. Pedro Petrovitch se bajó, tomó el billete con los dedos y lo desplegó _coram populo_. Era un billete de cien rublos, doblado en ocho partes. Pedro Petrovitch lo enseñó a todos para que no existiese ninguna duda sobre la culpabilidad de Sonia.\"},{\"heading\":false,\"text\":\"--¡Ladrona, fuera de aquí! ¡La policía, la policía!--aulló Amalia Ivanovna--. ¡Es preciso que la lleven a Siberia! ¡A la calle!\"},{\"heading\":false,\"text\":\"De todas partes brotaban exclamaciones. Raskolnikoff, silencioso, no cesaba de mirar a Sonia más que para echar de vez en cuando una mirada rápida sobre Ludjin. La joven, inmóvil en su sitio, parecía más bien atontada que sorprendida; de repente enrojeció y se cubrió el rostro con las manos.\"},{\"heading\":false,\"text\":\"--¡No! ¡Yo no soy! ¡Yo no he robado nada! ¡Yo no sé nada!--gritó con voz desgarradora y se precipitó hacia Catalina Ivanovna, que abrió los brazos como un asilo inviolable para la desgraciada criatura.\"},{\"heading\":false,\"text\":\"--¡Sonia, Sonia! ¡No lo creo; te digo que no lo creo!--repetía Catalina Ivanovna, rebelde a la evidencia. (Estas palabras iban acompañadas de mil caricias; besaba a la joven, le tomaba las manos, la mecía en sus brazos como a un niño.)--¡Tú haber robado nada! ¡pero qué personas más estúpidas! ¡Oh señor! ¡Sois tontos, tontos!--gritaba a los circunstantes--. ¡No sabéis lo que es esta criatura! ¡Robar ella! ¡Ella, que vendería su último vestido; ella, que iría descalza antes que dejarnos sin recursos; antes que tuvierais necesidad de ellos! ¡Así, así es...! ¡Ha llegado hasta tomar cartilla, porque mis hijos se morían de hambre... se vendió por nosotros! ¡Ah, mi pobre difunto; mi pobre difunto! ¡Dios mío, Dios mío! Pero, ¡defendedla vosotros todos, en vez de estar impasibles! Usted, Rodión Romanovitch, ¿por qué no la defiende? ¿Usted también la cree culpable? ¡Todos vosotros juntos, no valéis lo que el dedo meñique de ella! ¡Dios mío, defiéndela tú!\"},{\"heading\":false,\"text\":\"Las lágrimas, las súplicas, la desesperación de la pobre Catalina Ivanovna parecieron causar una gran impresión en el público. Aquel rostro de tísica, aquellos labios secos, aquella voz ahogada, expresaban un sentimiento tan doloroso, que era difícil no sentirse conmovido ante tanta desolación. Pedro Petrovitch volvió en seguida a expresar los más dulces sentimientos.\"},{\"heading\":false,\"text\":\"--¡Señora, señora!--dijo con solemnidad--. Este negocio no concierne a usted en lo más mínimo. Nadie piensa en acusarla de culpabilidad; usted misma es la que ha sacado los bolsillos y ha descubierto el objeto robado; basta esto para demostrar la completa inocencia de usted. Estoy dispuesto a mostrarme indulgente con un acto a que Sonia Semenovna ha podido ser impulsada por la miseria. Pero, ¿por qué se niega usted a confesar, señorita? ¿Teme la deshonra? ¿Era éste su primer hurto? ¿Lo hizo usted trastornada? La cosa se comprende, se comprende muy bien; vea usted, sin embargo, a lo que se exponía. Señores--dijo dirigiéndose a todos los presentes, mudos por un sentimiento de piedad--: Estoy pronto a perdonar, a pesar de las injurias que se me han dirigido.\"},{\"heading\":false,\"text\":\"Después añadió:\"},{\"heading\":false,\"text\":\"--Señorita, que la humillación de hoy le sirva a usted de lección para el porvenir; no daré parte; las cosas no pasarán de aquí.\"},{\"heading\":false,\"text\":\"Pedro Petrovitch dirigió una mirada de reojo a Raskolnikoff; sus ojos se encontraron; los del joven despedían llamas. En cuanto a Catalina Ivanovna, parecía no haber oído nada y continuaba abrazando a Sonia con una especie de frenesí. A ejemplo de su madre, los niños estrechaban entre sus bracitos a la joven; Poletchka, sin comprender lo que pasaba, sollozaba a más no poder, con su linda carita apoyada en el hombro de Sonia. De repente, en el umbral de la puerta una voz sonora exclamó:\"},{\"heading\":false,\"text\":\"--¡Qué villanía!\"},{\"heading\":false,\"text\":\"Pedro Petrovitch se volvió vivamente.\"},{\"heading\":false,\"text\":\"--¡Qué villanía!--repitió Lebeziatnikoff mirando fijamente a Ludjin.\"},{\"heading\":false,\"text\":\"Este último se estremeció. Todos lo advirtieron (luego se acordaron de esta circunstancia). Lebeziatnikoff entró en la sala.\"},{\"heading\":false,\"text\":\"--¿Y usted se ha atrevido a invocar mi testimonio?--dijo aproximándose a Pedro Petrovitch.\"},{\"heading\":false,\"text\":\"--¿Qué significa esto? ¿De qué habla usted, Andrés Semenovitch?--preguntó Ludjin.\"},{\"heading\":false,\"text\":\"--Esto significa que usted es un... calumniador. Ya tiene usted explicado el sentido de mis palabra--replicó arrebatadamente Lebeziatnikoff.\"},{\"heading\":false,\"text\":\"Estaba extremadamente colérico y fijaba en Pedro Petrovitch sus ojillos enfermizos, que tenían dura e indignada expresión. Raskolnikoff escuchaba ansiosamente con la mirada fija en el rostro del joven socialista.\"},{\"heading\":false,\"text\":\"Hubo una pausa. En el primer momento, Pedro Petrovitch quedó casi desconcertado.\"},{\"heading\":false,\"text\":\"--¿Es a mí a quien...?--murmuró--. ¿Pero qué dice usted? ¿Está usted en su juicio?\"},{\"heading\":false,\"text\":\"--Sí. Estoy en mi juicio, y usted es un... mal hombre. ¡Ah! ¡Qué infamia! Lo he oído todo, y si no he hablado antes, es porque quería comprender bien; hay algunas cosas que... lo confieso, no me las explico. Me gustaría saber por qué ha hecho usted esto.\"},{\"heading\":false,\"text\":\"--¿Pero qué es lo que yo he hecho? ¿Acabará de hablar enigmáticamente? ¡Usted está borracho!\"},{\"heading\":false,\"text\":\"--¡Hombre ruin! Si alguno de nosotros está borracho, es usted. Yo jamás bebo aguardiente, porque esto es contrario a mis principios. Figúrense ustedes que es él, él mismo quien, con sus propias manos ha dejado el billete de cien rublos a Sonia Semenovna; yo lo he visto; yo he sido testigo de ello, y lo declararé bajo la fe de mi juramento. Es él, él--repetía Lebeziatnikoff dirigiéndose a todos y a cada uno.\"},{\"heading\":false,\"text\":\"--¿Está usted loco? ¿Sí, o no? ¡Mentecato!--replicó violentamente Ludjin--. Ella misma aquí, hace un momento, ha afirmado, en presencia de usted y de todo el mundo, que no había recibido más que diez rublos... ¿Cómo es, pues, posible que yo le haya dado más dinero?\"},{\"heading\":false,\"text\":\"--Yo lo he visto--repitió con energía Andrés Semenovitch--; y aunque esto pugna a mis principios, estoy dispuesto a prestar juramento ante la justicia; le he visto a usted deslizar ese dinero con mucho disimulo. Sólo que he sido tan tonto, que he creído que hablaba usted por generosidad. Cuando usted le decía adiós en el umbral de la puerta y le ofrecía usted la mano derecha, le introdujo disimuladamente en el bolsillo el papel que tenía en la izquierda. Yo lo he visto, yo lo he visto.\"},{\"heading\":false,\"text\":\"Ludjin palideció.\"},{\"heading\":false,\"text\":\"--¿Qué es lo que está usted mintiendo?--replicó insolentemente--. Estando al lado de la ventana, ¿cómo podía usted ver eso del billete? Vaya, como está usted mal de la vista, ha sido usted objeto de una ilusión.\"},{\"heading\":false,\"text\":\"--No, yo no he visto visiones. A pesar de la distancia, lo he visto todo muy bien. Desde la ventana, en efecto, era difícil distinguir el billete, en eso tiene usted razón; mas a causa de esa misma circunstancia, sé que era precisamente un billete de cien rublos. Cuando usted dió diez a Sonia Semenovna, yo estaba cerca de la mesa y vi a usted tomar al mismo tiempo un billete de cien rublos. No he podido olvidar este detalle, porque en aquel momento se me ocurrió una idea. Después de haber plegado el billete, lo guardó usted en el hueco de la mano, y cuando se levantó se pasó el papel de la mano derecha a la izquierda, y estuvo a punto de dejarlo caer. Me he acordado porque se me ocurrió la misma idea, a saber: que usted quería obligar a Sonia Semenovna sin que yo me enterara; pero no puede usted imaginarse con qué atención he observado sus gestos y ademanes. Así es que he visto meter el billete en el bolsillo de la joven. Lo he visto, lo he visto, y lo repetiré donde sea necesario bajo la fe del juramento.\"},{\"heading\":false,\"text\":\"Lebeziatnikoff estaba casi sofocado por la indignación. De todos lados se entrecruzaban exclamaciones diversas. La mayor parte expresaban estupor; pero algunas eran proferidas en son de amenaza. Todos rodearon a Pedro Petrovitch. Catalina Ivanovna se lanzó hacia Lebeziatnikoff.\"},{\"heading\":false,\"text\":\"--¡Andrés Semenovitch! ¡Yo no le conocía a usted! ¡Usted la defiende; solamente usted se pone de parte de ella! ¡Dios le envía a usted en socorro de la huérfana! ¡Andrés Semenovitch, mi querido amigo, _batuchka_!\"},{\"heading\":false,\"text\":\"Y Catalina Ivanovna, sin casi tener conciencia de lo que hacía, cayó de rodillas delante del joven.\"},{\"heading\":false,\"text\":\"--¡Esas son tonterías!--vociferó Ludjin arrebatado por la cólera--. ¡No dice usted más que necedades! «Yo he olvidado; me he acordado: me acuerdo; me olvido.» ¿Qué significa todo esto? De modo que si fuera verdad lo que usted dice, yo le habría deslizado a propósito esos cien rublos en el bolsillo. ¿Con qué objeto? ¿Qué tengo yo de común con esa...?\"},{\"heading\":false,\"text\":\"--¿Por qué? Eso es lo que no comprendo; me limito a referir el hecho tal como ha pasado, sin pretender explicarlo, y, dentro de esos límites, garantizo su exactitud... Tampoco me engaño, malvado, así como me acuerdo de haberme hecho esta misma pregunta en el momento en que felicitaba a usted estrechándole la mano. Me preguntaba por qué razón había usted hecho ese regalo en forma clandestina. Quizá, me dije, ha querido ocultarme su buena acción, sabiendo que yo, en virtud de mis principios, soy enemigo de la caridad privada y la considero como un vano paliativo. He pensado después que trataba de dar una sorpresa a Sonia Semenovna. Hay, en efecto, personas que se complacen en dar a sus beneficios el sabor de lo imprevisto. En seguida se me ocurrió otra idea: que la intención de usted era poner a prueba a la joven; que usted quería saber si, cuando ella encontrara en el bolsillo esos cien rublos, vendría a darle las gracias, o acaso quería usted substraerse a su reconocimiento, siguiendo el precepto de que la mano derecha debe ignorar... En una palabra, Dios sabe las suposiciones que se me ocurrieron. La conducta de usted me preocupaba de tal modo, que me proponía reflexionar más tarde sobre ella detenidamente. Además, hubiera creído faltar a la delicadeza, dando a entender que conocía su secreto. Pensando en estas cosas me asaltó un temor. Sonia Semenovna, ignorando la generosidad de usted, podía perder el billete de Banco. He aquí por qué me he decidido a venir: porque quería llamarla aparte y decirle que le habían puesto cien rublos en el bolsillo; pero antes he entrado en casa de las señoras Kobyliatnikoff, para entregarles un _Tratado general sobre el método positivo_, y recomendarles el artículo de Piderit (el de Vagner no carece de valor). Un momento después he llegado aquí y he sido testigo de esta escena. Ahora bien: ¿es posible que yo hubiera podido pensar en todo esto y hacerme todos estos razonamientos, si no le hubiera visto a usted deslizar los cien rublos en el bolsillo de Sonia Semenovna?\"},{\"heading\":false,\"text\":\"Cuando Andrés Semenovitch terminó su discurso, no podía ya más y tenía el rostro bañado de sudor. ¡Ah! Aun en ruso le costaba trabajo expresarse convenientemente, aunque, por lo demás, no conocía ningún otro idioma. Este esfuerzo oratorio le había agotado. Sus palabras produjeron, sin embargo, extraordinario efecto. El acento de sinceridad con que las había pronunciado llevó el convencimiento al alma de todos los oyentes. Pedro Petrovitch comprendió que perdía terreno.\"},{\"heading\":false,\"text\":\"--¡Qué me importan a mí las tonterías que se le han ocurrido a usted!--exclamó--; eso no es una prueba. Ha podido usted soñar cuantas necedades quiera. Le digo que miente. ¡Miente usted, y además me calumnia para satisfacer sus rencores! La verdad es que usted me odia porque me he puesto enfrente del radicalismo impío, de las doctrinas antisociales que usted sostiene.\"},{\"heading\":false,\"text\":\"Pero, lejos de redundar en favor de Pedro Petrovitch, provocó violentos murmullos en su derredor.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿Eso es todo lo que se le ocurre responder? No es muy fuerte su argumento--replicó Lebeziatnikoff--. ¡Llame a la policía; prestaré mi juramento! Una sola cosa queda obscura para mí: el motivo que le ha impulsado a cometer una acción tan baja. ¡Oh miserable, cobarde!\"},{\"heading\":false,\"text\":\"Raskolnikoff avanzó, separándose del grupo.\"},{\"heading\":false,\"text\":\"--Yo puedo explicar su conducta, y si es menester, también prestaré juramento--dijo con voz firme.\"},{\"heading\":false,\"text\":\"A primera vista, la tranquila seguridad del joven probó al público que conocía a fondo el asunto, y que aquel embrollo estaba a punto de llegar a su desenlace.\"},{\"heading\":false,\"text\":\"--Ahora lo comprendo todo--prosiguió Raskolnikoff dirigiéndose a Lebeziatnikoff--. Desde el principio de este accidente había sospechado detrás de esto alguna innoble intriga. Se fundaban mis sospechas en ciertas circunstancias solamente de mí conocidas, y que voy a revelar, porque presentan las cosas en su verdadero aspecto. Usted, Andrés Semenovitch, ha iluminado perfectamente mi espíritu; suplico a ustedes que me escuchen. Ese señor--continuó, designando con un gesto a Pedro Petrovitch--, ha pedido recientemente la mano de mi hermana Advocia Romanovna Raskolnikoff. Llegado hace poco a San Petersburgo, vino a verme anteayer; pero ya en nuestra primera entrevista tuvimos un choque y le eché a la calle, como pueden declarar dos personas que estaban presentes. Ese hombre es muy malo... Anteayer ignoraba yo que viviese con usted, Andrés Semenovitch. Gracias a esta circunstancia, anteayer, es decir, el día mismo de nuestra cuestión, se encontró presente aquí en el momento en que, como amigo del difunto Marmeladoff, le di un poco de dinero a su viuda Catalina Ivanovna para atender a los gastos de los funerales de su marido. Inmediatamente escribió a mi madre diciéndole que yo había dado mi dinero, no a Catalina Ivanovna, sino a Sonia Semenovna, calificando al mismo tiempo a esa joven con los más ultrajantes adjetivos y dando a entender que yo tenía con ella relaciones íntimas. Su objeto, como comprenderán ustedes, era enemistarme con mi familia, insinuándole que yo gasto en disipaciones el dinero de que ella se priva para atender a mis necesidades. Ayer noche, en una entrevista con mi madre y mi hermana, entrevista a la cual asistía él, he restablecido la verdad de los hechos que este señor había desnaturalizado. «El dinero--dije--se lo di a Catalina Ivanovna para pagar el entierro de su marido, y no a Sonia Semenovna a quien aquel día había hablado por primera vez.» Furioso al ver que sus calumnias no obtenían el resultado apetecido, insultó groseramente a mi madre y a mi hermana. Siguióse un rompimiento definitivo y se le echó a la calle. Todo ello pasó anoche. Reflexionen ustedes ahora y comprenderán qué interés le guiaba, en las circunstancias presentes, a inculpar a Sonia Semenovna si lograba hacer pasar a esta joven por ladrona, y resultaba culpable a los ojos de mi madre y de mi hermana, puesto que no tenía temor en comprometer a ésta poniéndola en relaciones con una ladrona; él, por el contrario, al atacarme a mí, salía a la defensa de mi hermana, su futura esposa. En una palabra, éste era para él un medio de enemistarme con los míos y de congraciarse con ellos. Con el mismo golpe se vengaba también de mí, pensando que me intereso vivamente por el honor y la tranquilidad de Sonia Semenovna. Tal es el cálculo que ha hecho, y de este modo es como me explico yo su conducta.\"},{\"heading\":false,\"text\":\"Raskolnikoff terminó su discurso, frecuentemente interrumpido por las exclamaciones del público, que no perdía una sola frase. Pero, a despecho de las interrupciones, su palabra conservó hasta el fin una calma, una seguridad y una claridad imperturbables. Su voz vibrante, su acento convencido y su rostro severo, conmovieron profundamente al auditorio.\"},{\"heading\":false,\"text\":\"--Sí, sí; eso es--se apresuró a reconocer Lebeziatnikoff--, debe usted tener razón, porque en el momento mismo en que entró Sonia Semenovna en nuestro cuarto, me preguntó si había visto a usted y si estaba entre los convidados de su madrastra, llevándome aparte para preguntármelo en voz baja. Tenía, pues, necesidad de que estuviese usted aquí. Sí, eso es.\"},{\"heading\":false,\"text\":\"Ludjin, mortalmente pálido, permanecía silencioso y sonreía con aire despreciativo. Parecía buscar un medio de salir airosamente de aquel trance. Quizá de buena gana hubiera hurtado el cuerpo en seguida; pero en aquel momento la retirada era casi imposible: irse equivalía a reconocer implícitamente las acusaciones que se le dirigían y confesar que había calumniado a Sonia Semenovna.\"},{\"heading\":false,\"text\":\"Por otra parte, la actitud de los circunstantes no era nada tranquilizadora. La mayoría de ellos estaban borrachos. Esta escena atrajo a la habitación un número considerable de inquilinos que no habían comido en casa de la viuda. Los polacos, muy excitados, no cesaban de proferir en sus lenguas mil amenazas contra Pedro Petrovitch.\"},{\"heading\":false,\"text\":\"Sonia escuchaba atentamente, pero no daba señales de haber recobrado su presencia de ánimo; parecía que acababa de volver de un desmayo. No apartaba los ojos de Raskolnikoff, comprendiendo que en él estaba todo su apoyo. Catalina Ivanovna sufría atrozmente: cada vez que respiraba se escapaba de su pecho un ronco sonido.\"},{\"heading\":false,\"text\":\"La figura más estúpida era la de Amalia Ivanovna, que tenía aspecto de no comprender nada, y con la boca abierta miraba como alelada. Tan sólo veía que Pedro Petrovitch estaba metido en grave aprieto. Raskolnikoff quiso tomar de nuevo la palabra, pero tuvo que renunciar a ello a causa de que la gritería no hubiera permitido que le oyeran. De todas partes llovían injurias y amenazas sobre Ludjin, en derredor del cual se había formado un corro tan hostil como compacto. El hombre de negocios sacó fuerzas de flaqueza, y haciéndose cargo de que la partida estaba definitivamente perdida, buscó recursos en la osadía.\"},{\"heading\":false,\"text\":\"--Permítanme ustedes, señores, permítanme ustedes, no me cerquen de este modo; déjenme pasar--dijo, tratando de abrirse paso al través del grupo que le rodeaba--. Aseguro a ustedes que es inútil tratar de intimidarme con amenazas. No me asusto por tan poca cosa. Por el contrario, ustedes deben temblar por el amparo con que encubren un delito. El robo está más que probado, y yo presentaré la correspondiente denuncia contra la autora y sus encubridores. Los jueces son personas ilustradas y no borrachos, y recusarán el testimonio de dos impíos, de dos revolucionarios declarados que me acusan por un acto de venganza personal, como ellos han cometido la necedad de afirmar. Sí, permítanme ustedes.\"},{\"heading\":false,\"text\":\"--No quiero respirar el mismo aire que usted, y le suplico que deje mi cuarto; todo ha acabado entre nosotros--dijo Lebeziatnikoff--. ¡Cuando pienso que desde hace quince días vengo sudando sangre y agua para exponerle...!\"},{\"heading\":false,\"text\":\"--Antes de ahora, Andrés Semenovitch, le he anunciado yo mismo mi partida, precisamente cuando hacía usted instancias para retenerme; ahora me limito a decirle que es usted un imbécil. Le deseo que se cure de los ojos y del entendimiento. Permitan ustedes, señores.\"},{\"heading\":false,\"text\":\"Logró abrirse paso; pero uno de los circunstantes, creyendo que las injurias no eran castigo suficiente, tomó un vaso de la mesa y lo lanzó con todas sus fuerzas contra Pedro Petrovitch. Por desgracia, el proyectil alcanzó a Amalia Ivanovna, que se puso a dar gritos horribles.\"},{\"heading\":false,\"text\":\"Al lanzar el vaso, el agresor perdió el equilibrio y cayó pesadamente bajo la mesa. Ludjin entró en el cuarto de Lebeziatnikoff, y una hora después dejó la casa.\"},{\"heading\":false,\"text\":\"Naturalmente tímida, Sonia sabía ya antes de esta aventura que su situación la exponía a todo género de ataques, y que cualquiera podía ultrajarla casi impunemente. Sin embargo, hasta entonces había esperado desarmar la malevolencia de los demás, a fuerza de circunspección, de humildad y de dulzura con todos y cada uno; pero hasta esta ilusión se disipaba. Tenía, sin duda, bastante paciencia para sufrir aún esto con resignación y casi sin murmurar; pero en aquel momento la decepción era demasiado cruel. Aunque su inocencia hubiese triunfado de la calumnia, y aun cuando su primer terror hubiera pasado, al darse cuenta de lo ocurrido se le oprimió dolorosamente el corazón ante el pensamiento de su abandono y de su soledad en la vida. La joven tuvo una crisis nerviosa, y, no pudiendo contenerse más, salió apresuradamente de la sala y echó a correr a su casa. Su partida fué poco después de la de Ludjin.\"},{\"heading\":false,\"text\":\"El vasazo recibido por Amalia Ivanovna produjo hilaridad general; pero la patrona tomó muy a mal la cosa y revolvió su cólera contra Catalina Ivanovna, la cual, vencida por el sufrimiento, había tenido que echarse en su cama.\"},{\"heading\":false,\"text\":\"--¡Fuera de aquí! ¡En seguida! ¡Ea! ¡A la calle!\"},{\"heading\":false,\"text\":\"Mientras pronunciaba estas palabras con voz irritada, la señora Lippevechzel tomaba todos los objetos pertenecientes a su inquilina y los arrojaba en un montón en medio de la sala. Quebrantada, casi desfallecida, la pobre Catalina Ivanovna saltó de la cama y se lanzó sobre la patrona. Pero la lucha era demasiado desigual, y a Amalia Ivanovna no le costó gran trabajo rechazar este asalto.\"},{\"heading\":false,\"text\":\"--¡Cómo! ¿No es bastante haber calumniado a Sonia, y esta mujer se revuelve ahora contra mí? ¿El día en que han enterrado a mi marido me expulsa; después de haber recibido mi hospitalidad, me arroja a la calle con mis hijos? Pero, ¿a dónde voy a ir yo?--sollozaba la infeliz mujer--. ¡Señor!--exclamó de repente con los ojos centelleantes--. ¿Es posible que no haya justicia? ¿A quién defenderás Tú, Dios mío, si no nos defiendes a nosotras, pobres huérfanas? Pero ya veremos. Jueces y tribunales hay en la tierra; recurriré a ellos; espere un poco, criatura mía. Poletchka, quédate con los niños; yo volveré pronto. Si os echan, esperadme en la calle. ¡Veremos si hay justicia en la tierra!\"},{\"heading\":false,\"text\":\"Catalina Ivanovna se puso en la cabeza aquel mismo pañuelo verde de que habló Marmeladoff en la taberna, y después, hendiendo la multitud ebria y ruidosa de los inquilinos, que continuaban llenando la sala, con el rostro inundado de lágrimas bajó a la calle resuelta a ir, costase lo que costase, a buscar justicia en cualquier parte.\"},{\"heading\":false,\"text\":\"Poletchka, espantada, estrechó entre sus brazos a su hermano y a su hermana, y los tres niños, acurrucados en el rincón inmediato al cofre, esperaron temblando la vuelta de su madre.\"},{\"heading\":false,\"text\":\"Amalia Ivanovna, semejante a una furia, iba y venía por la habitación aullando de rabia y arrojando al suelo cuanto le venía a las manos.\"},{\"heading\":false,\"text\":\"Entre los inquilinos, unos comentaban el acontecimiento, otros disputaban, algunos entonaban canciones...\"},{\"heading\":false,\"text\":\"«Ya es tiempo de que me vaya--pensó Raskolnikoff--. Veremos, Sonia Semenovna, qué es lo que piensas ahora.»\"},{\"heading\":false,\"text\":\"Y se encaminó a casa de la joven.\"}]},{\"title\":\"quinta parte — capítulo IV\",\"blocks\":[{\"heading\":false,\"text\":\"Aunque Raskolnikoff tenía sus preocupaciones y disgustos, había defendido valientemente la causa de la joven Sonia contra Ludjin. Aparte del interés que le inspiraba la joven, había aprovechado con gusto, después de los tormentos de por la mañana, la impresión de sacudir impresiones que se le hacían insoportables. Por otro lado, su próxima entrevista con Sonia le preocupaba y aun le aterraba por momentos. Tenía que revelarle que había matado a Isabel, y presintiendo todo lo que esta confesión tendría de penosa, se esforzaba por apartar de ella el pensamiento.\"},{\"heading\":false,\"text\":\"Cuando al salir de casa de Catalina Ivanovna, había exclamado: «Veremos, Sonia Semenovna, lo que piensas ahora», era el combatiente animado por la lucha, excitado aún por su victoria sobre Ludjin, el que había pronunciado aquella frase de desafío; pero, cosa singular, cuando llegó a la casa de Kapernumoff, su seguridad le abandonó de repente, dejando el puesto al temor. Se detuvo indeciso ante la puerta y se preguntó: «¿Será preciso decir que he matado a Isabel?» La pregunta era extraña, porque en el momento en que él se la hacía comprendía la imposibilidad, no solamente de no hacer esta confesión, sino aun la de diferirla un minuto.\"},{\"heading\":false,\"text\":\"No sabía por qué era imposible; únicamente lo sentía y estaba como aplastado por esta dolorosa conciencia de su debilidad ante la necesidad. Para ahorrarse nuevos tormentos, se apresuró a abrir la puerta, y antes de franquear el umbral miró a Sonia. La joven estaba sentada, con los codos apoyados en la mesita y el rostro oculto entre las manos. Al ver a Raskolnikoff se levantó en seguida y fué a su encuentro, como si lo hubiese esperado.\"},{\"heading\":false,\"text\":\"--¿Qué habría sido de mí sin usted?--dijo vivamente, en tanto que le hacía pasar a la sala.\"},{\"heading\":false,\"text\":\"Parecía que entonces no pensaba más que en el servicio que le había prestado el joven, y tenía prisa de darle las gracias. Después esperó.\"},{\"heading\":false,\"text\":\"Raskolnikoff se aproximó a la mesa y se sentó en la silla que la joven acababa de dejar. Sonia permaneció en pie, a dos pasos de él, exactamente como el día anterior.\"},{\"heading\":false,\"text\":\"--Habrá usted observado--dijo advirtiendo que le temblaba la voz--que la acusación no tenía otro fundamento que la posición social de usted y las costumbres que ella implica. ¿Lo ha comprendido usted así?\"},{\"heading\":false,\"text\":\"El rostro de Sonia se ensombreció.\"},{\"heading\":false,\"text\":\"--No me hable usted como ayer, le suplico que no vuelva a empezar. He sufrido ya bastante...\"},{\"heading\":false,\"text\":\"Se apresuró a sonreír, temiendo que el reproche ofendiese al visitante.\"},{\"heading\":false,\"text\":\"--Hace un momento he venido a casa como una loca. ¿Qué pasa allí ahora? Yo quería volver, pero suponía que vendría usted.\"},{\"heading\":false,\"text\":\"Raskolnikoff le contó que Amalia Ivanovna acababa de echar de casa a los Marmeladoff, y que Catalina Ivanovna había ido a buscar justicia a cualquier parte.\"},{\"heading\":false,\"text\":\"--¡Ah, Dios mío!--exclamó Sonia--. ¡Vamos en seguida!--y tomó apresuradamente su manteleta.\"},{\"heading\":false,\"text\":\"--¡Siempre lo mismo!--replicó Raskolnikoff contrariado--. Usted no piensa más que en ellos. Quédese usted un momento conmigo.\"},{\"heading\":false,\"text\":\"--Pero... Catalina Ivanovna...\"},{\"heading\":false,\"text\":\"--Catalina Ivanovna vendrá aquí, no tenga usted duda--respondió con tono de enfado el joven--. Culpa de usted será si no la encuentra.\"},{\"heading\":false,\"text\":\"Sentóse Sonia, presa de cruel perplejidad. Raskolnikoff, con los ojos bajos, reflexionaba.\"},{\"heading\":false,\"text\":\"--Hoy Ludjin quería, simplemente, desacreditarla a usted; lo concedo--dijo sin mirar a Sonia--; sí, le hubiera convenido meterla a usted en la cárcel, y si no hubiéramos estado allí Lebeziatnikoff y yo, lo habría hecho. ¿No es así?\"},{\"heading\":false,\"text\":\"--Sí--dijo la joven con voz débil--. Sí--repitió maquinalmente, distraída de la conversación a causa de la inquietud que experimentaba.\"},{\"heading\":false,\"text\":\"--Podía, en efecto, no haber estado yo allí, y si Lebeziatnikoff se encontró fué por casualidad.\"},{\"heading\":false,\"text\":\"Sonia guardó silencio.\"},{\"heading\":false,\"text\":\"--Si la hubieran llevado a usted a la cárcel, ¿qué habría sucedido? ¿Se acuerda usted de lo que dije ayer?\"},{\"heading\":false,\"text\":\"Sonia continuó callada, y el joven esperó un momento su respuesta.\"},{\"heading\":false,\"text\":\"--Pensaba que iba usted a exclamar: «¡Ah, no hable usted de eso! ¡No siga usted!»--repuso Raskolnikoff con risa un poco forzada--. Vamos, ¿no dice usted nada?--preguntó al cabo de un minuto--. Será preciso que sostenga yo solo la conversación. Ahí tiene usted; tendría curiosidad por saber cómo resolvería usted una «cuestión», según dice Lebeziatnikoff (comenzaba a ser visible su turbación). No; hablo seriamente. Suponga usted, Sonia, que estuviese enterada de antemano de todos los proyectos de Ludjin; que usted supiese que estos proyectos iban encaminados a asegurar la pérdida de Catalina Ivanovna y de sus hijos, sin contar la de usted (porque usted no hace caso de sí misma para nada). Suponga usted, por consiguiente, que Poletchka fuese condenada a una existencia como la de usted; siendo esto así, si dependiese de usted hacer que pereciese Ludjin, o lo que es lo mismo, salvar a Catalina Ivanovna y su familia, o dejar vivo a Ludjin para que cumpliese sus infames designios; contésteme, ¿por cuál de las dos cosas se decidiría usted?\"},{\"heading\":false,\"text\":\"Sonia le miró con inquietud; bajo estas palabras pronunciadas con voz vacilante, adivinaba algún pensamiento recóndito.\"},{\"heading\":false,\"text\":\"--¿Podría yo esperarme alguna pregunta por el estilo?--dijo la joven interrogándole con los ojos.\"},{\"heading\":false,\"text\":\"--Es posible; pero conteste: ¿por quién se decidiría usted?\"},{\"heading\":false,\"text\":\"--¿Qué interés tiene usted en saber lo que haría en un caso que no puede presentarse?--exclamó Sonia con repugnancia.\"},{\"heading\":false,\"text\":\"--¿De modo que dejaría vivir a Ludjin y que cometiese tales infamias? No tiene usted valor para decirlo con franqueza.\"},{\"heading\":false,\"text\":\"--No conozco los secretos de la divina Providencia... ¿por qué me pregunta usted lo que haría en un caso imposible? ¿A qué vienen esas vanas preguntas? ¿Cómo la existencia de un hombre puede depender de mi voluntad? ¿Quién me erige a mí árbitro de la vida y la muerte de las personas?\"},{\"heading\":false,\"text\":\"--En el momento en que se hace intervenir a la divina Providencia, no hay más que hablar--replicó con tono agrio Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¡Dígame usted lo que tenga que decirme!--exclamó Sonia angustiada--. ¿Otra vez con palabras encubiertas?... ¿Ha venido usted sólo a atormentarme?\"},{\"heading\":false,\"text\":\"No pudo contenerse y se puso a llorar. Durante cinco minutos el joven la contempló con expresión sombría.\"},{\"heading\":false,\"text\":\"--Tienes razón, Sonia--dijo en voz baja.\"},{\"heading\":false,\"text\":\"Se había operado en él un brusco cambio; su fingida serenidad, el tono áspero que afectaba hacía un momento, había desaparecido de pronto. Ahora, apenas se le oía.\"},{\"heading\":false,\"text\":\"--Te dije ayer que no vendría a pedir perdón, y casi con excusas he comenzado mi entrevista. Al hablarte de Ludjin me acusaba, Sonia.\"},{\"heading\":false,\"text\":\"Quiso sonreír; pero, por más que hizo, su fisonomía permaneció triste. Bajó la cabeza y se cubrió la cara con las manos. De repente creyó advertir que detestaba a Sonia. Sorprendido y hasta aterrado por tan extraño descubrimiento, levantó súbitamente la cabeza y contempló de hito en hito a la joven. Esta fijaba en él una mirada ansiosa, en la cual había amor. El odio desapareció instantáneamente del corazón de Raskolnikoff. No era eso, habíase engañado sobre la naturaleza de sus sentimientos; aquello sólo significaba que había llegado el minuto fatal.\"},{\"heading\":false,\"text\":\"De nuevo ocultó su rostro entre las manos y bajó la cabeza; palideció, se levantó, y después de haber mirado a Sonia, fué maquinalmente a sentarse en el lecho sin proferir palabra.\"},{\"heading\":false,\"text\":\"La impresión de Raskolnikoff era entonces exactamente la misma que había experimentado en pie, detrás de la vieja, cuando había sacado el hacha del nudo corredizo, diciendo: «No hay un instante que perder».\"},{\"heading\":false,\"text\":\"--¿Qué tiene usted?--preguntó Sonia sobrecogida.\"},{\"heading\":false,\"text\":\"El joven no pudo responder. Había contado con explicarse en muy otras condiciones y no comprendía lo que pasaba por él. Sonia se aproximó suavemente a Raskolnikoff; se sentó a su lado en la cama, y esperó sin dejar de mirarlo. El corazón le latía como si fuera a romperse. La situación se hacía insoportable. Raskolnikoff volvió hacia la joven su rostro, mortalmente pálido, y movió los labios con esfuerzo para hablar. Sonia estaba aterrada.\"},{\"heading\":false,\"text\":\"--¿Qué tiene usted?--repitió apartándose un poco de él.\"},{\"heading\":false,\"text\":\"--Nada, Sonia; no te asustes; esto no vale la pena. Verdaderamente, es una tontería--murmuró con aire distraído--. ¿Por qué he venido a atormentarte?--añadió de repente mirando a su interlocutora--. Sí, ¿por qué? No ceso de hacerme esta pregunta.\"},{\"heading\":false,\"text\":\"Se la había hecho quizá un cuarto de hora antes; pero en aquel momento era tal su debilidad, que apenas tenía conciencia de sí mismo; un temblor continuo agitaba su cuerpo.\"},{\"heading\":false,\"text\":\"--¡Cuánto sufre usted!--dijo la joven conmovida fijando los ojos en él.\"},{\"heading\":false,\"text\":\"--Esto no es nada. He aquí de lo que se trata, Sonia. (Durante dos segundos sonrió tristemente.) ¿Te acuerdas de lo que te dije ayer?\"},{\"heading\":false,\"text\":\"Sonia esperaba inquieta.\"},{\"heading\":false,\"text\":\"--Te dije, al separarme de ti, que quizá te diría adiós para siempre; pero, que si venía hoy, sabrías quién fué el que mató a Isabel.\"},{\"heading\":false,\"text\":\"La joven se echó a temblar.\"},{\"heading\":false,\"text\":\"--Pues bien; ya sabes a lo que he venido.\"},{\"heading\":false,\"text\":\"--En efecto--dijo Sonia con voz temblorosa--; eso fué lo que me dijo usted ayer. ¿Cómo sabe usted eso?--añadió vivamente.\"},{\"heading\":false,\"text\":\"Sonia respiraba trabajosamente y el rostro se le ponía cada vez más pálido.\"},{\"heading\":false,\"text\":\"--Yo lo sé.\"},{\"heading\":false,\"text\":\"--¿Se _le_ ha encontrado?--preguntó tímidamente después de un minuto de silencio.\"},{\"heading\":false,\"text\":\"--No, no se _le_ ha encontrado.\"},{\"heading\":false,\"text\":\"Siguióse un corto silencio.\"},{\"heading\":false,\"text\":\"--Entonces, ¿cómo lo sabe usted?--preguntó con voz casi ininteligible.\"},{\"heading\":false,\"text\":\"Raskolnikoff se volvió hacia la joven y la miró con una fijeza singular.\"},{\"heading\":false,\"text\":\"--Adivina--dijo.\"},{\"heading\":false,\"text\":\"Sonia se estremeció convulsivamente.\"},{\"heading\":false,\"text\":\"--¿Por qué me asusta usted de ese modo?--preguntó con sonrisa infantil.\"},{\"heading\":false,\"text\":\"--Si yo lo sé es porque estoy íntimamente relacionado con él--repuso Raskolnikoff, cuya mirada seguía fija en la joven, como si no tuviese fuerza para volver los ojos--. A esa Isabel no quería _él_ matarla; la mató sin premeditación... quería asesinar a la vieja cuando estuviese sola... Fué a su casa; pero, cuando estaba en ella, entró Isabel y la mató.\"},{\"heading\":false,\"text\":\"A estas palabras siguió un silencio lúgubre; durante un minuto continuaron mirándose.\"},{\"heading\":false,\"text\":\"--¿De modo que no adivinas?--preguntó bruscamente, con la sensación de un hombre que se arroja de lo alto de un campanario.\"},{\"heading\":false,\"text\":\"--No--balbuceó Sonia con voz apenas distinta.\"},{\"heading\":false,\"text\":\"--Busca bien.\"},{\"heading\":false,\"text\":\"Al pronunciar estas palabras, Raskolnikoff experimentó en el fondo de sí mismo la impresión de frío glacial que le era tan conocida; miraba a Sonia y de pronto le pareció ver a Isabel cuando la desventurada se echó atrás ante el asesino, que avanzaba hacia ella con el hacha levantada. En aquel momento supremo Isabel levantó el brazo como hacen los niños pequeños cuando tienen miedo, y, prontos a echarse a llorar, fijan una mirada inmóvil en el objeto que les espanta. Del mismo modo el rostro de Sonia expresaba un terror indecible; también ella extendió el brazo hacia adelante, rechazando ligeramente a Raskolnikoff, y tocándole el pecho con la mano se apartó poco a poco de él, sin cesar de mirarle fijamente. Su terror se comunicó al joven, que se puso a mirarla asustado.\"},{\"heading\":false,\"text\":\"--¿Lo has adivinado?--murmuró por último.\"},{\"heading\":false,\"text\":\"--¡Dios mío!--exclamó Sonia.\"},{\"heading\":false,\"text\":\"Después se dejó caer sin fuerzas sobre el lecho y hundió el rostro en la almohada. Pero al cabo de un instante se levantó con rápido movimiento, se aproximó a él y tomándole las dos manos que sus deditos estrecharon como tenazas, le miró largo rato de hito en hito. ¿No se había engañado? Así lo esperaba, pero apenas hubo fijado los ojos en su interlocutor, la sospecha que había atravesado su alma se trocó en certidumbre.\"},{\"heading\":false,\"text\":\"--¡Basta, Sonia, basta! Evítame más explicaciones--suplicó él con voz quejumbrosa.\"},{\"heading\":false,\"text\":\"Lo que había pasado contrariaba todas sus previsiones, porque no era ciertamente así como pensó él hacer la confesión de su crimen.\"},{\"heading\":false,\"text\":\"Sonia parecía que estaba fuera de sí. Saltó de su lecho y se fué al centro de la habitación retorciéndose las manos; después volvió bruscamente sobre sus pasos y se sentó, hombro con hombro, al lado del joven. De repente se echó a temblar, lanzó un grito y, sin saber lo que hacía, cayó de rodillas delante de Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¡Está usted perdido!--exclamó con acento desesperado; y levantándose súbitamente se arrojó a su cuello, le besó y le acarició.\"},{\"heading\":false,\"text\":\"Raskolnikoff se separó de ella, y contemplándola con triste sonrisa, dijo:\"},{\"heading\":false,\"text\":\"--No te comprendo, Sonia. Me abrazas después de haberte contado eso... No tienes conciencia de lo que haces.\"},{\"heading\":false,\"text\":\"La joven no oyó esta observación.\"},{\"heading\":false,\"text\":\"--No, no hay en la tierra un hombre más desgraciado que tú--exclamó en un arranque de piedad, y rompió en sollozos.\"},{\"heading\":false,\"text\":\"Raskolnikoff sintió invadida su alma por un sentimiento que desde hacía largo tiempo no había experimentado. No trató de luchar contra esta impresión; dos lágrimas brotaron de sus ojos y rodaron silenciosas por sus mejillas.\"},{\"heading\":false,\"text\":\"--¿No me abandonarás, Sonia?--preguntó con mirada casi suplicante.\"},{\"heading\":false,\"text\":\"--¡No, no! ¡Jamás, jamás!--gritó--. Te seguiré, te seguiré a todas partes. ¡Oh Dios mío!... ¡Oh, qué desgraciada soy!... ¿Por qué? ¿por qué no te he conocido antes? ¿Por qué no habrás venido...?\"},{\"heading\":false,\"text\":\"--Ya ves que lo he hecho--interrumpió Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¡Ahora! ¡Oh! ¿Qué podemos hacer ahora?... ¡Juntos! ¡Juntos!--repitió con una especie de exaltación y se puso a abrazar al joven--. ¡Iré contigo a presidio!\"},{\"heading\":false,\"text\":\"Estas últimas palabras produjeron en Raskolnikoff una sensación penosa y apareció en sus labios una sonrisa amarga y casi altanera.\"},{\"heading\":false,\"text\":\"--Es que yo, malditas las ganas que tengo de ir a presidio.\"},{\"heading\":false,\"text\":\"Sonia volvió rápidamente hacia él los ojos. Hasta entonces había sentido una inmensa piedad por aquel hombre desgraciado; pero lo que acababa de decir el joven y el tono con que fué pronunciado, recordaron bruscamente a Sonia que aquel desgraciado era un asesino. La muchacha le dirigió una mirada de asombro. No sabía aún cómo ni por qué había llegado a convertirse en criminal. En aquel momento, todas estas cuestiones se presentaban ante su espíritu y de nuevo dudó.\"},{\"heading\":false,\"text\":\"«¡El, él un asesino! ¿Es posible?»\"},{\"heading\":false,\"text\":\"--Pero esto no es verdad; ¿dónde estoy?--dijo como si despertase de un terrible sueño--. ¿Cómo, siendo usted lo que es, ha podido resolverse a hacer eso?... ¿Pero por qué lo ha hecho?\"},{\"heading\":false,\"text\":\"--Por robar. Cesa ya, Sonia--respondió algo contrariado el joven.\"},{\"heading\":false,\"text\":\"La muchacha se quedó estupefacta.\"},{\"heading\":false,\"text\":\"--¿Tenías hambre?--exclamó en seguida--. ¿Era para socorrer a tu madre?... ¿Sí?\"},{\"heading\":false,\"text\":\"--No, Sonia, no--replicó Raskolnikoff bajando la cabeza--. Mi miseria no era tan grande... Quería, en efecto, ayudar a mi madre... pero no fué ésta la verdadera razón... No me atormentes, Sonia.\"},{\"heading\":false,\"text\":\"--¿Pero es posible que esto sea verdad?--gritó la joven, dando una palmada--. ¿Es esto posible? ¿Hay medio de creerlo? ¿Ha matado usted para robar? ¡Usted que se despoja de todo en favor de los pobres! ¡Ah!... ¿El dinero que usted dió a mi madrastra...? ¿Ese dinero...?\"},{\"heading\":false,\"text\":\"--¡No, Sonia, no!--interrumpió vivamente Raskolnikoff--. Ese dinero no procedía de _aquello_, tranquilízate; me lo envió mi madre cuando yo estaba enfermo, por medio de un comerciante, y acababa de recibirlo cuando lo di... Razumikin lo vió. Ese dinero me pertenecía.\"},{\"heading\":false,\"text\":\"Sonia escuchaba perpleja y esforzándose por comprender.\"},{\"heading\":false,\"text\":\"--Por lo demás, en cuanto al dinero de la vieja... yo no sé lo que había--añadió vacilando--; le quité del cuello una bolsa de piel que parecía bien repleta... pero no me enteré del contenido, sin duda porque me faltó tiempo... Me apoderé de varias cosas, gemelos, cadenas de reloj... Esos objetos, lo mismo que la bolsa, los oculté al día siguiente bajo una piedra grande en un corral situado en la perspectiva V***. Todo ello está allí todavía.\"},{\"heading\":false,\"text\":\"Sonia escuchaba con avidez.\"},{\"heading\":false,\"text\":\"--Pero, ¿por qué no ha tomado usted nada, puesto que mató para robar?--replicó como agarrándose a una última y muy vaga esperanza.\"},{\"heading\":false,\"text\":\"--No sé... no he decidido aún sí tomaré o no ese dinero--respondió Raskolnikoff con la misma voz vacilante, y luego sonrió--. ¡Qué historia tan tonta te acabo de contar!\"},{\"heading\":false,\"text\":\"«¿Estará loco?», se preguntó Sonia; pero rechazó en seguida esta idea. No, allí había alguna otra cosa para ella inexplicable; pero en vano ponía en prensa su mente.\"},{\"heading\":false,\"text\":\"--¿Sabes lo que quiero decirte, Sonia?--repuso él con voz vibrante--. Si únicamente la necesidad me hubiese impulsado al asesinato--prosiguió recalcando cada una de sus palabras, y su mirada tenía algo de enigmático--, yo sería ahora _feliz_. Sábelo. ¿Qué te importa el motivo, puesto que acabo de confesarte que he obrado mal?--exclamó tras de una corta pausa--. ¿Para qué ese triunfo sobre mí? ¡Ah, Sonia! ¿Es para esto para lo que he venido a tu casa?\"},{\"heading\":false,\"text\":\"La joven quiso hablar, pero se calló.\"},{\"heading\":false,\"text\":\"--Ayer te propuse que vivieses conmigo porque yo no tengo a nadie sino a ti.\"},{\"heading\":false,\"text\":\"--¿Por que querías que viviese contigo?--preguntó tímidamente Sonia.\"},{\"heading\":false,\"text\":\"--No para robar ni matar, puedes estar tranquila--contestó Raskolnikoff riendo sardónicamente--; nosotros no somos de la misma cepa... Y mira, acabo de comprender ahora por qué te invité ayer a venir conmigo. Cuando te dirigía esta petición, no sabía cuál era su objeto... lo veo ahora. No tengo nada más que un deseo: ¡Que no me abandones! ¿No me dejarás, Sonia?\"},{\"heading\":false,\"text\":\"La joven le apretó la mano.\"},{\"heading\":false,\"text\":\"--¿Y por qué? ¿Por qué te he dicho yo esto? ¿por qué te he hecho esta confesión?--exclamó Raskolnikoff al cabo de unos segundos, mirándole con infinita compasión a la vez que con la desesperación más profunda--. Veo que esperas mis explicaciones, Sonia; pero, ¿qué he de decirte? Nada comprenderías, y yo no haría otra cosa que afligirte cada vez más. Vamos, veo que lloras y que empiezas de nuevo a abrazarme; ¿por qué me abrazas? ¿Es porque, falto de valor para llevar mi cruz, me libro así de este peso, cargando con él a otra persona; porque he buscado en el sufrimiento ajeno un alivio a mis pesares? ¿Y puedes amar a semejante cobarde?\"},{\"heading\":false,\"text\":\"--¿Pero no sufres tú también?--exclamó Sonia.\"},{\"heading\":false,\"text\":\"Hubo de nuevo un acceso de sensibilidad.\"},{\"heading\":false,\"text\":\"--Sonia, tengo el corazón enfermo, recapacita... Esto puede explicar multitud de cosas. Porque soy malo he venido. Hay muchos que no lo hubiesen hecho; pero yo soy cobarde y miserable. ¿Por qué he venido? ¡Jamás me lo perdonaré!\"},{\"heading\":false,\"text\":\"--No, no; has hecho bien en venir--repuso Sonia--. Vale más que lo sepa todo; es mucho mejor.\"},{\"heading\":false,\"text\":\"Raskolnikoff la miró con expresión dolorosa.\"},{\"heading\":false,\"text\":\"--He querido ser un Napoleón... por eso he matado. ¿Comprendes ahora?\"},{\"heading\":false,\"text\":\"--No--respondió cándidamente Sonia con voz tímida--; pero habla, habla; lo comprenderé todo.\"},{\"heading\":false,\"text\":\"--¿Que lo comprenderás? Está bien; ya veremos.\"},{\"heading\":false,\"text\":\"Durante un momento, Raskolnikoff estuvo pensativo recogiendo sus ideas.\"},{\"heading\":false,\"text\":\"--El hecho es que cierto día me hice esta pregunta: Si Napoleón, por ejemplo, hubiese estado en mi lugar, si no hubiese tenido para comenzar su carrera ni Tolón ni Egipto, ni el paso de San Bernardo, sino que en lugar de estas brillantes empresas se hubiese encontrado ante la necesidad de cometer un asesinato para asegurar su porvenir, ¿hubiera renunciado a la idea de matar a una vieja y de robarle tres mil rublos? ¿Hubiera pensado que tal acción era demasiado innoble y demasiado criminal? Yo me he devanado durante algún tiempo los sesos con esta pregunta, y no he podido menos de experimentar un sentimiento de vergüenza, cuando he reconocido, por fin, que no sólo no hubiera vacilado, sino que no hubiese comprendido la posibilidad de una vacilación. No teniendo ninguna otra salida no se hubiera andado con escrúpulos. Desde que me hice esta reflexión ya no tenía que vacilar; la autoridad de Napoleón me cubría. ¿Encuentras esto risible? Tienes razón, Sonia.\"},{\"heading\":false,\"text\":\"La joven no tenía el menor deseo de reír.\"},{\"heading\":false,\"text\":\"--Háblame con franqueza, sin ejemplos--dijo con voz tímida y apenas distinta.\"},{\"heading\":false,\"text\":\"Raskolnikoff se volvió hacia ella, la miró con tristeza y le tomó las manos.\"},{\"heading\":false,\"text\":\"--Tienes razón, Sonia. Todo esto es absurdo, carece de sindéresis, no es más que palabrería... Mira, mi madre, como sabes, está casi sin recursos. La casualidad quiso que mi hermana recibiese esmerada educación y estuviera condenada al oficio de institutriz. Todas sus esperanzas reposaban exclusivamente sobre mí. Entré en la Universidad; pero, falto de medios, me vi obligado a interrumpir mis estudios. Supongamos que los hubiese continuado; yendo bien las cosas, hubiera podido, en diez o quince años, ser nombrado profesor de Gimnasio o empleado con mil rublos de sueldo. (Parecía que estaba recitando una lección). Pero de aquí a entonces, los cuidados y los disgustos habrían destruído la salud de mi madre y de mi hermana... quizá les hubiera ocurrido algo peor. Privarse de todo, dejar a mi madre en la miseria, sufrir el deshonor de mi hermana... ¿es esto vivir? Y todo ello para llegar, ¿a qué? Después de haber visto morir a los míos, podría fundar una familia, dejando, al morir, a mi mujer y a mis hijos sin un pedazo de pan. Pues bien, yo me dije que con el dinero de la vieja cesaría de ser una carga para mi madre; que podría volver a entrar en la Universidad y asegurar un porvenir. Ahí lo tienes explicado todo. Claro que he hecho mal en matar a la vieja... pero, en fin, ¡basta!\"},{\"heading\":false,\"text\":\"Raskolnikoff no tenía ya fuerzas, y bajó la cabeza como agobiado.\"},{\"heading\":false,\"text\":\"--¡Oh, no es eso, no es eso!--gritó Sonia con voz quejumbrosa--. ¡Esto no es posible!... ¡No, no; hay alguna otra causa!...\"},{\"heading\":false,\"text\":\"--¡Supones que hay otra causa! Te engañas, he dicho la verdad.\"},{\"heading\":false,\"text\":\"--¡La verdad! ¡Oh, Dios mío!\"},{\"heading\":false,\"text\":\"--Después de todo, Sonia, yo no he matado más que a un gusano innoble y malo.\"},{\"heading\":false,\"text\":\"--¡Ese gusano era una criatura humana!\"},{\"heading\":false,\"text\":\"--Ya lo sé que no era un gusano en el sentido literal de la palabra--replicó Raskolnikoff mirándola con singular expresión--. Por otra parte, lo que digo no tiene sentido común--añadió--; tienes razón, Sonia, no es eso, son otros motivos los que me han impulsado. Desde hace largo tiempo no he hablado con nadie. Esta conversación me ha dado dolor de cabeza.\"},{\"heading\":false,\"text\":\"Los ojos le brillaban a causa de la fiebre. El delirio se había casi apoderado de él y una sonrisa inquieta erraba en sus labios. Bajo su aparente animación se adivinaba verdadero cansancio. Sonia comprendió cuánto sufría. También ella comenzaba a perder la cabeza. «¡Qué lenguaje tan extraño! ¡Presentar como plausibles semejantes explicaciones!» No acertaba a explicárselo y se retorcía las manos en el acceso de su desesperación.\"},{\"heading\":false,\"text\":\"--No, Sonia, no es eso--prosiguió el joven, levantando de repente la cabeza; sus ideas habían tomado súbitamente nuevo rumbo y parecía haber adquirido de repente una nueva energía--; no, no es eso. Cree más bien que te amo con locura, que soy envidioso, malo, vengativo, y, además, propenso a la demencia... Acabo de decirte que tuve que dejar la Universidad. Pues bien; quizá hubiera podido seguir asistiendo a ella. Mi madre habría pagado las matrículas; yo hubiera ganado con mi trabajo para vestir y comer y habría quizás llegado... Tenía lecciones retribuídas con cincuenta kopeks. Razumikin trabaja bien; pero yo estaba exasperado y no quise. Sí, estaba _exasperado_, ésa es la palabra. Entonces me metí en mi casa como la araña en su rincón. Ya conoces mi tugurio, has estado en él... ¿Sabes tú, Sonia, que el alma se ahoga en las habitaciones bajas y estrechas? ¡Oh, lo que yo odiaba ese cuartucho! y, sin embargo, no quería salir de él; me pasaba allí días enteros, sin querer trabajar, no cuidándome ni de comer. «Si Nastachiuska me trae alguna cosa, comeré--me decía--; si no, me pasaré sin comer.» Estaba muy irritado para pedir nada. Había renunciado al estudio y vendido todos mis libros; una pulgada de polvo hay sobre mis notas y cuadernos. Por la noche no tenía luz. Para comprar una vela me hubiera sido forzoso trabajar y no quería; prefería fantasear acostado en mi sofá. Inútil es decirte cuáles eran mis ocupaciones... Entonces comencé a pensar... No, no es esto; no cuento las cosas como son. Yo me preguntaba siempre: «Puesto que sabes que los demás son imbéciles, ¿por qué no procuras ser más inteligente que ellos?» Reconocí entonces, Sonia, que si se esperaba el momento que todo el mundo fuese inteligente, sería forzoso armarse de muy larga paciencia. Más tarde me convencí de que aquel momento no llegaría jamás; de que los hombres no cambiarían y de que se perdía el tiempo tratando de modificarlos. Sí, así es. Es su ley... Yo sé ahora, Sonia, que el amo de todos es el que posee una inteligencia poderosa. Quien se atreve a mucho, tiene razón a sus ojos; quien los desafía y los desprecia, se impone a su respeto. Es lo que se ha visto y se verá siempre. Es preciso estar ciego para no advertirlo.\"},{\"heading\":false,\"text\":\"Mientras hablaba, Raskolnikoff miraba a Sonia; pero no se preocupaba por saber si ella le comprendía. Era presa de una triste exaltación. Desde largo tiempo no había hablado con nadie. La joven comprendió que aquel feroz catecismo eran su fe y su ley.\"},{\"heading\":false,\"text\":\"--Entonces me convencí, Sonia--continuó acalorándose cada vez más--, de que el poder no se toma más que bajándose. Todo estriba en esto. Desde el día en que se me presentó esa verdad clara como el sol, he querido _atreverme_, y he matado. He tratado de hacer un acto de audacia, Sonia; tal ha sido el móvil de mi acción.\"},{\"heading\":false,\"text\":\"--¡Cállese usted! ¡Cállese usted!--exclamó la joven fuera de sí--. Se ha alejado usted de Dios, y Dios le ha herido y le ha entregado al demonio.\"},{\"heading\":false,\"text\":\"--A propósito, Sonia; cuando todas estas ideas venían a visitarme en la obscuridad de mi cuarto, ¿era el demonio quien me tentaba?\"},{\"heading\":false,\"text\":\"--Cállese usted, no se ría, impío. No se ría; usted nada comprende. ¡Oh Dios mío, no comprende nada!\"},{\"heading\":false,\"text\":\"--Cállate, Sonia. Ya no me río. Estoy seguro de que el demonio me ha impulsado. Cállate, Sonia, cállate--repetía con sombría insistencia--. Lo sé, lo sé todo. Cuanto tú pudieras decirme, me lo he dicho yo mil veces cuando estaba acostado en la obscuridad. ¡Qué luchas interiores he sufrido! ¡Cuán insoportables me eran estos sueños, y cómo hubiera querido librarme de ellos para siempre! ¿Crees tú que yo obré como un aturdido, como un hombre sin seso? No hay tal cosa; no hay tal cosa. Procedí después de madura reflexión, y eso precisamente es lo que me ha perdido. Cuando me interrogaba acerca de si tenía o no derecho yo al poder, comprendía muy bien que mi derecho era nulo, por lo mismo que lo ponía en tela de juicio. Cuando me preguntaba si una criatura humana era un gusano, sabía perfectamente que no lo era para mí, sino para el audaz que no se lo hubiese preguntado y hubiese seguido el camino sin atormentarse el espíritu con semejante reflexión. En fin, el solo hecho de plantearme este problema: «¿hubiera Napoleón matado a esa vieja?» basta para demostrarme que yo no era un Napoleón. Por último, he renunciado a buscar justificaciones sutiles. Quise matar dejándome de toda casuística; matar para mí, para mí solo. ¡Si he matado, no ha sido para aliviar el infortunio de mi madre, ni para consagrar al bien de la humanidad el poder y la riqueza que, a mi juicio, debían ayudarme a conquistar este asesinato! No, no; todo eso estaba lejos de mi espíritu en aquel momento. El dinero no ha sido para mí el principal móvil del asesinato; otra razón me determinó a ello; lo veo ahora claramente. Compréndeme; si _esto_ estuviese por hacer, quizá no lo intentaría; pero entonces me corría prisa saber si era yo un gusano como los otros, o un hombre en la verdadera acepción de la palabra, si tenía o no la fuerza de franquear el obstáculo, si era yo una criatura tímida o si tenía el _derecho_...\"},{\"heading\":false,\"text\":\"--¿El derecho de matar?--exclamó Sonia estupefacta.\"},{\"heading\":false,\"text\":\"--¡Sonia!--dijo el joven con cierta irritación; tenía una respuesta en la punta de la lengua; pero se abstuvo desdeñosamente de formularla--. No me interrumpas, Sonia. Quería solamente probarte una cosa: que el diablo me condujo a casa de la vieja, y en seguida me hizo comprender que yo no tenía el derecho de ir allí puesto que soy un gusano, ni más ni menos que los demás. El demonio se ha burlado de mí, y por esa razón he venido a tu casa. Si yo no fuese un gusano, ¿te habría hecho esta visita? Escucha: cuando fuí a casa de la vieja quería hacer solamente una _experiencia_...\"},{\"heading\":false,\"text\":\"--¡Y ha matado usted...! ¡Y ha matado!\"},{\"heading\":false,\"text\":\"--¿Pero cómo he matado? ¿Es así como se mata? ¿Se hace lo que yo he hecho cuando se va a asesinar a una persona? Ya te contaré alguna vez los pormenores. ¿Acaso he matado yo a la vieja? No; es a mí a quien he matado, a quien he perdido sin remedio... En cuanto a la vieja... ha sido asesinada por el demonio, y no por mí... ¡Basta, basta, Sonia; basta! ¡Déjame!--exclamó con voz desgarradora--. ¡Déjame!\"},{\"heading\":false,\"text\":\"Raskolnikoff apoyó los codos sobre las rodillas y se oprimió convulsivamente la cabeza entre las manos.\"},{\"heading\":false,\"text\":\"--¡Qué sufrimientos!--gimió Sonia.\"},{\"heading\":false,\"text\":\"--¿Qué hacer ahora? dímelo--preguntó Raskolnikoff levantando la cabeza.\"},{\"heading\":false,\"text\":\"Tenía las facciones terriblemente alteradas.\"},{\"heading\":false,\"text\":\"--¿Qué hacer?--exclamó la joven, y se lanzó hacia él con ardientes lágrimas en los ojos, en los cuales brillaba extraño resplandor--. Levántate (al decir esto tomó a Raskolnikoff por el brazo; el joven se incorporó y miró a Sonia sorprendido); ve en seguida a la próxima encrucijada; prostérnate y besa la tierra que has contaminado. Después inclínate a un lado y a otro, diciendo en alta voz y a todo el mundo: «Yo he matado». Dios entonces te devolverá la vida. ¿Irás? ¿Irás?--le preguntó la joven temblando y apretándole las manos con fuerza centuplicada, mientras fijaba en él sus ojos llameantes.\"},{\"heading\":false,\"text\":\"La súbita exaltación de Sonia sumió a Raskolnikoff en un estupor profundo.\"},{\"heading\":false,\"text\":\"--¿Quieres que vaya a presidio, Sonia? ¿Es menester que me denuncie? ¿No es eso?--dijo sombríamente.\"},{\"heading\":false,\"text\":\"--Debes aceptar la expiación y mediante ella redimirte.\"},{\"heading\":false,\"text\":\"--No, no iré a denunciarme, Sonia.\"},{\"heading\":false,\"text\":\"--¿Y vivir? ¿Cómo vivirás?--replicó la joven con fuerza--. ¿Ahora es posible? ¿Cómo podrás sostener la mirada de tu madre? ¡Oh!, ¿qué será de ellas ahora? ¿Pero qué es lo que digo? Has dejado ya a tu madre y a tu hermana. Por esa razón has roto los lazos que te unían con tu familia. ¡Oh Dios mío!--exclamó--. ¡El comprende todo esto! ¿Cómo estar fuera de la sociedad humana? ¿Qué va a ser de ti ahora?\"},{\"heading\":false,\"text\":\"--Sé razonable, Sonia--dijo dulcemente Raskolnikoff--. ¿Por qué he de ir a presentarme a la policía? ¿Qué he de decir a esa gente? Todo esto no significa nada... Ellos mismos degüellan a millones de hombres y se ufanan de ello. Son bribones y cobardes, Sonia... No iré. ¿Qué tendría que decirles? ¿Que he cometido un asesinato, y que, no atreviéndome a aprovecharme del dinero robado, lo he ocultado debajo de una piedra?--añadió con amarga sonrisa--. Se burlarán de mí; me dirán que soy un imbécil por no haber hecho uso de lo robado; que soy un imbécil y un cobarde. Ellos, Sonia, no comprenderán. Son incapaces de comprenderme; ¿por qué he de ir a entregarme? No iré, no. Sé razonable, Sonia.\"},{\"heading\":false,\"text\":\"--¡Soportar semejante peso! ¡Y por toda la vida, por toda la vida!\"},{\"heading\":false,\"text\":\"--Ya me acostumbraré--respondió el joven con feroz expresión--. Escucha--dijo un momento después--. Basta de lloriqueos; tiempo es ya de que hablemos formalmente. He venido para decirte que en estos momentos se me busca y van a detenerme.\"},{\"heading\":false,\"text\":\"--¡Ah!--exclamó Sonia espantada.\"},{\"heading\":false,\"text\":\"--¿De qué te asustas? ¿No deseas que vaya a presidio? ¿De qué, pues, te espantas? Solamente que aun no me tienen en su poder. Les he dado mucho quehacer y al fin de cuentas nada conseguirán. No tienen indicios positivos. Ayer corrí un gran peligro y llegué a creer que todo estaba terminado. Por hoy se ha evitado el mal. Todas sus pruebas son de dos filos, es decir, que los cargos formulados contra mí, pueden ser explicados en favor mío. ¿Me comprendes? No me será difícil hacerlo, porque he adquirido experiencia. Pero de seguro van a meterme en la cárcel. Sin una circunstancia fortuita, es muy posible que se me hubiera encerrado ya, y corro peligro de estar preso antes de que termine el día. Esto no significa nada, Sonia; me detendrán, pero se verán obligados a soltarme, porque no tienen verdaderas pruebas, y te doy mi palabra de que no las tendrán. Con simples presunciones, como son las suyas, no se puede condenar a un hombre. ¡Ea, basta! Quería solamente prevenirte. En cuanto a mi madre y a mi hermana, me arreglaré de modo que no se inquietarán. Creo que mi hermana está ahora al abrigo de la miseria; puedo estar tranquilo en lo que se refiere a mi madre... Ya lo sabes todo. Sé prudente. ¿Vendrás a verme cuando esté preso?\"},{\"heading\":false,\"text\":\"--¡Oh, sí, sí!\"},{\"heading\":false,\"text\":\"Estaban sentados uno al lado del otro, tristes y abatidos como los náufragos arrojados por la tempestad en una playa desierta. Contemplando a Sonia, comprendió Raskolnikoff cuánto le amaba la joven, y, cosa extraña, aquella ternura inmensa, de la cual se veía objeto, le causó de repente una impresión dolorosa. Había ido a casa de Sonia, pensando que su sola esperanza, su solo refugio, era ella; había cedido a la necesidad irresistible de desahogar su pena, y ahora que la joven le había dado todo su corazón, se confesaba que era infinitamente más desgraciado que antes.\"},{\"heading\":false,\"text\":\"--Sonia--le dijo--, es mejor que no vengas a verme mientras esté en la cárcel.\"},{\"heading\":false,\"text\":\"La joven no respondió. Lloraba. Pasaron algunos minutos.\"},{\"heading\":false,\"text\":\"--¿Llevas alguna cruz encima?--preguntó inopinadamente, como herida de súbita idea.\"},{\"heading\":false,\"text\":\"Al pronto el joven no comprendió la pregunta.\"},{\"heading\":false,\"text\":\"--No, no la tienes. Pues bien, toma ésta, es de madera de ciprés. Yo tengo otra de cobre, que era de Isabel. Hicimos un cambio, ella me dió una cruz y yo le di una imagen. Quiero llevar ahora la cruz de Isabel y que tú lleves ésta. Tómala... es la mía--insistió--. Juntos iremos por el camino de la expiación; juntos llevaremos la cruz.\"},{\"heading\":false,\"text\":\"--Dámela--dijo Raskolnikoff para no disgustarla, y extendió la mano; pero la retiró casi en seguida--. Ahora no, Sonia; más tarde será mejor--añadió a manera de concesión.\"},{\"heading\":false,\"text\":\"--Sí, sí, más tarde--respondió ella con calor--; te la daré en el momento de la expiación. Vendrás a mi casa, te la pondré al cuello, diremos una oración y partiremos.\"},{\"heading\":false,\"text\":\"En el mismo instante sonaron tres golpes en la puerta.\"},{\"heading\":false,\"text\":\"--¿Puedo entrar, Sonia Semenovna?--dijo una voz afable y muy conocida.\"},{\"heading\":false,\"text\":\"Sonia, turbada, corrió a abrir. El que llamaba no era otro que el señor Lebeziatnikoff.\"}]},{\"title\":\"quinta parte — capítulo V\",\"blocks\":[{\"heading\":false,\"text\":\"Andrés Semenovitch tenía el rostro demudado.\"},{\"heading\":false,\"text\":\"--Vengo a buscar a usted, Sonia Semenovna... perdóneme usted... Esperaba encontrarle aquí--dijo bruscamente a Raskolnikoff--. Es decir, nada malo me imaginaba... no vaya usted a creer... pero precisamente pensaba... Catalina Ivanovna ha vuelto a su cuarto; está loca--dijo dirigiéndose de nuevo a Sonia.\"},{\"heading\":false,\"text\":\"La joven lanzó un grito.\"},{\"heading\":false,\"text\":\"--Por lo menos así parece. No sabemos qué hacer con ella. La han echado del sitio adonde había ido, quizá dándole golpes... Así lo hace todo suponer. Fué después al despacho del jefe de Simón Zakharitch, y no lo encontró. Comía en casa de uno de sus colegas. En seguida, ¿querrá usted creerlo? se fué al domicilio del otro general, porfiando que quería ver al jefe de su difunto esposo, que estaba sentado a la mesa. Como era natural, la echaron a la calle. Cuentan que la llenaron de injurias y aun que le tiraron no sé qué cosa a la cabeza. Es raro que no la hayan detenido. Expone ahora todos sus proyectos a todo el mundo, incluso a Amalia Ivanovna; pero es tanta su agitación, que no se puede sacar nada en claro de sus palabras. ¡Ah, sí! Dice que como no le queda ningún recurso, va a dedicarse a tocar el organillo por las calles, y que sus hijos cantarán y bailarán para solicitar la caridad de los transeuntes; que todos los días irá a colocarse bajo las ventanas de la casa del general... «Se verá--dice--a los hijos de una familia noble, pedir limosna por las calles.» Pega a los niños y les hace llorar. Enseña la _Petit Ferme_ a Alena, y al mismo tiempo da lecciones de baile al niño y a Poletchka... Deshace sus vestidos para improvisar trajes de saltimbanquis, y, a falta de organillo, quiere llevar una cubeta para dar golpes en ella... No tolera que se le haga ninguna observación... No puede usted imaginarse cómo está.\"},{\"heading\":false,\"text\":\"Lebeziatnikoff hubiese hablado mucho más; pero Sonia, que le había escuchado respirando apenas, tomó el sombrero y la manteleta, y se lanzó fuera de la sala, poniéndose estas prendas conforme iba andando. Los dos jóvenes salieron detrás de ella.\"},{\"heading\":false,\"text\":\"--Está positivamente loca--dijo Andrés Semenovitch a Raskolnikoff--. Para no asustar a Sonia he dicho solamente que sólo parecía que lo estaba; pero no hay duda. Creo que suelen formarse tubérculos en el cerebro de los tísicos; es una lástima que yo no sepa Medicina. He tratado de convencer a Catalina Ivanovna, pero no hace caso de nadie.\"},{\"heading\":false,\"text\":\"--¿Le ha hablado usted de tubérculos?\"},{\"heading\":false,\"text\":\"--No, precisamente de tubérculos, no; claro es que no me hubiera entendido. Pero vea usted lo que yo pienso. Si con el auxilio de la lógica usted persuade a uno que no tiene motivo para llorar, no llorará. Esto es claro; ¿por qué había de continuar llorando?\"},{\"heading\":false,\"text\":\"--Si así fuese, la vida sería muy fácil--respondió Raskolnikoff.\"},{\"heading\":false,\"text\":\"Al llegar cerca de su casa saludó a Lebeziatnikoff con un movimiento de cabeza y subió a su cuarto.\"},{\"heading\":false,\"text\":\"Cuando estuvo en él, Raskolnikoff se dejó caer en el sofá.\"},{\"heading\":false,\"text\":\"Jamás había experimentado tan terrible sensación de aislamiento. Sentía de nuevo que quizá, en efecto, detestaba a Sonia, y que la detestaba después de haber contribuído a aumentar su desgracia. ¿Por qué había ido a hacerla llorar? ¿Qué necesidad tenía de emponzoñar su vida? ¡Oh cobardía!\"},{\"heading\":false,\"text\":\"«Estaré solo--se dijo resueltamente--, y ella no vendrá a verme en la cárcel.»\"},{\"heading\":false,\"text\":\"Cinco minutos después levantó la cabeza, y una idea que se le ocurrió de repente le hizo sonreír: «Quizá sea, en efecto, mejor que vaya a presidio», pensaba.\"},{\"heading\":false,\"text\":\"¿Cuánto tiempo duró este sueño? No pudo jamás recordarlo. Súbitamente la puerta se abrió, dando paso a Advocia Romanovna. La joven le miró como poco antes había mirado él a Sonia; después se aproximó y se sentó en una silla frente a su hermano, en el mismo sitio que la víspera. Raskolnikoff la miró en silencio sin que en sus ojos se pudiese leer ninguna idea.\"},{\"heading\":false,\"text\":\"--No te incomodes, hermano mío. Sólo voy a estar un minuto--dijo Dunia.\"},{\"heading\":false,\"text\":\"Su fisonomía estaba seria, pero no severa, y su mirada era dulcemente límpida.\"},{\"heading\":false,\"text\":\"Raskolnikoff comprendió que la mirada de su hermana era dictada por el afecto.\"},{\"heading\":false,\"text\":\"--Hermano mío, lo sé todo. Demetrio Prokofitch me lo ha contado. Se te persigue, se te atormenta, eres objeto de sospechas insensatas como odiosas. Demetrio Prokofitch asegura que nada tienes que temer y que haces mal en preocuparte hasta ese punto. No soy de su opinión; me explico perfectamente el desbordamiento de indignación que se ha producido en ti y no me sorprendería que tu vida entera se resienta de ese golpe. Nos ha dejado. No juzgo tu resolución, no me atrevo a juzgarla, y te suplico que me perdones los reproches que te he dirigido. Comprendo que si estuviera en tu lugar haría lo que tú haces, me desterraría del mundo. Yo procuraré que mamá lo ignore; pero le hablaré sin cesar de ti, y le diré de tu parte que no tardarás en ir a verla. No te inquietes por ella, yo la tranquilizaré; pero tú, por tu parte, no le causes disgustos. Ve, aunque no sea más que una vez. Considera que es tu madre. Mi solo objeto, al hacerte esta visita, ha sido el de decirte--acabó Advocia Romanovna levantándose--, que si por casualidad tienes necesidad de mí, sea para lo que fuere, soy tuya en la vida y en la muerte. Llámame, y vendré. Adiós.\"},{\"heading\":false,\"text\":\"Volvió la espalda y se dirigió a la puerta.\"},{\"heading\":false,\"text\":\"--¡Dunia!--dijo Raskolnikoff levantándose y acercándose a su hermana--. Razumikin, Demetrio Prokofitch, es un hombre excelente.\"},{\"heading\":false,\"text\":\"Dunia se ruborizó.\"},{\"heading\":false,\"text\":\"--¿Y qué?--preguntó después de un minuto de espera.\"},{\"heading\":false,\"text\":\"--Es un hombre activo, laborioso y capaz de grandes afectos... Adiós, hermana.\"},{\"heading\":false,\"text\":\"La joven se puso encendida como la grana; pero en seguida sintió cierto temor.\"},{\"heading\":false,\"text\":\"--¿Pero es que nos separamos para siempre, hermano? Tus palabras son una especie de testamento.\"},{\"heading\":false,\"text\":\"--No hagas caso. Adiós.\"},{\"heading\":false,\"text\":\"Se alejó de ella y se dirigió a la ventana. La joven esperó un momento; le miró con inquietud y se retiró conmovida.\"},{\"heading\":false,\"text\":\"No, no era indiferencia lo que experimentaba respecto de su hermana. Hubo un momento, el único, en que sintió violentos deseos de estrecharla entre sus brazos, de despedirse de ella y de confesárselo todo; no se resolvió, sin embargo, ni aun a tenderle la mano.\"},{\"heading\":false,\"text\":\"«Más tarde se estremecía con este recuerdo y pensaría que le he robado un beso. Y, además, ¿soportaría semejante confesión?--añadió mentalmente algunos minutos después--. No, no la soportaría; _estas mujeres_ no saben soportar nada»--y su pensamiento se fijó en Sonia.\"},{\"heading\":false,\"text\":\"Por la ventana entraba agradable fresco; caía la tarde. Raskolnikoff tomó bruscamente la gorra y salió.\"},{\"heading\":false,\"text\":\"Sin duda no quería ni podía ocuparse de su salud. Pero aquellos terrores, aquellas angustias continuas, por fuerza habían de tener consecuencias, y si la fiebre no se había apoderado de él, era acaso merced a la fuerza ficticia que le prestaba momentáneamente su agitación moral.\"},{\"heading\":false,\"text\":\"Se puso a vagar sin objeto. Se había puesto el sol. Desde hacía algún tiempo, Raskolnikoff experimentaba un sufrimiento que, sin ser particularmente agudo, se presentaba con carácter de continuidad. Entreveía largos años pasados en mortal angustia, «la eternidad en el espacio de un pie cuadrado». De ordinario era por la noche cuando este pensamiento le preocupaba más. «Con el estúpido malestar físico que produce la puesta del sol, ¿cómo no hacer tonterías? Iré, no solamente a casa de Sonia, sino a la de Dunia», murmuraba con voz irritada.\"},{\"heading\":false,\"text\":\"Oyó que le llamaban y se volvió. Lebeziatnikoff corría detrás de él.\"},{\"heading\":false,\"text\":\"--He ido a su casa de usted; le buscaba. Ha puesto en ejecución su programa. Se ha echado a la calle con sus hijos; a Sonia Semenovna y a mí nos ha costado trabajo encontrarlos. Va dando golpes en una sartén, haciendo bailar a los niños. Los pobrecillos lloran. Se detienen en las encrucijadas y a las puertas de las tiendas. Llevan detrás una caterva de imbéciles. Vamos aprisa.\"},{\"heading\":false,\"text\":\"--¿Y Sonia...?--preguntó con inquietud Rodia, que se apresuró a seguir a Lebeziatnikoff.\"},{\"heading\":false,\"text\":\"--Ha perdido la cabeza. Es decir, no es Sonia Semenovna la que ha perdido la cabeza, sino Catalina Ivanovna. Por lo demás, puede decirse lo mismo de la muchacha. En cuanto a Catalina Ivanovna, la locura es completa. Van a llevarla a la comisaría, y calcule usted el efecto que esto habrá de producirle. Están ahora cerca del canal; al lado del puente***, no lejos de la casa de Sonia Semenovna. Vamos a llegar en seguida.\"},{\"heading\":false,\"text\":\"En el canal, a poca distancia del puente, había un grupo, compuesto en gran parte de chiquillos y chiquillas. La voz ronca de Catalina Ivanovna se oía ya en el puente. Verdaderamente el espectáculo era lo bastante extraño para llamar la atención. Tocada con un mal sombrero de paja, vestida con su viejo traje, y echado sobre los hombros un chal de paño, Catalina Ivanovna justificaba plenamente las palabras de Lebeziatnikoff. Estaba quebrantada, jadeante. Su rostro de tísica manifestaba más sufrimiento que nunca (los tísicos, al sol y en la calle tienen siempre peor cara que en su casa); pero, no obstante su debilidad, estaba extraordinariamente excitada.\"},{\"heading\":false,\"text\":\"Se lanzaba sobre sus hijos y los zarandeaba con vivacidad. Se ocupaba allí, delante de todo el mundo, en su educación coreográfica y musical; les decía por qué razón era preciso cantar y bailar, y después, indignada de verlos tan poco inteligentes, les pegaba furiosamente. Interrumpía sus ejercicios para dirigirse al público; veía en el grupo un hombre vestido con alguna decencia, y se apresuraba a explicarle a qué extrema miseria estaban reducidos los hijos de una familia casi aristocrática. Si alguno se reía o burlaba de ella, se encaraba al punto con el insolente y se ponía a disputar con él. El caso es que muchos se burlaban, otros movían la cabeza, y todos miraban a aquella loca rodeada de niños asustados. Lebeziatnikoff se había engañado al hablar de la sartén; por lo menos Raskolnikoff no la vió. Para hacer el acompañamiento, Catalina Ivanovna llevaba el compás con las manos, mientras Poletchka cantaba y Alena y Kolia danzaban. Algunas veces trataba de cantar ella, pero desde la segunda nota interrumpíala un acceso de tos. Entonces se desesperaba, maldecía su enfermedad y no podía contener las lágrimas.\"},{\"heading\":false,\"text\":\"Lo que sobre todo la ponía fuera de sí, era el llanto de Alena y Kolia. Según dijo Lebeziatnikoff, había tratado de vestir a sus hijos como se visten los cantadores callejeros. El chiquillo llevaba en la cabeza una especie de turbante rojo y blanco, para representar a un turco. Faltándole tela para hacer un traje a Alena, su madre se había limitado a ponerle el gorro de dormir o _chapka_ roja de Marmeladoff. Este gorro estaba adornado con una pluma blanca de avestruz que había pertenecido a la abuela de Catalina, y que ésta había conservado hasta entonces en su baúl como precioso recuerdo de familia. Poletchka llevaba la ropa de todos los días. No se separaba de su madre, cuya perturbación intelectual adivinaba, y mirándola tímidamente trataba de ocultarle sus lágrimas. La niña estaba espantada al verse allí, en la calle, en medio de aquella multitud. Sonia no se apartaba de Catalina Ivanovna y le suplicaba llorando que se volviese a su casa; pero Catalina Ivanovna permanecía inflexible.\"},{\"heading\":false,\"text\":\"--¡Cállate, Sonia!--vociferaba tosiendo--. No sabes lo que dices; eres lo mismo que una chiquilla. Ya te he dicho que no vuelvo a casa de esa borracha alemana. Que todo el mundo, que todo San Petersburgo vea reducidos a la mendicidad a los hijos de un padre noble que ha servido lealmente toda su vida y que puede decirse que ha muerto en el servicio.\"},{\"heading\":false,\"text\":\"A Catalina Ivanovna se le había metido esta idea en la cabeza, y hubiera sido imposible sacársela.\"},{\"heading\":false,\"text\":\"--¡Que ese pillo de general sea testigo de nuestra miseria! Pero tú eres tonta, Sonia. Ya te hemos explotado bastante y no quiero explotarte más. ¡Ah, Rodión Romanovitch! ¿es usted?--gritó reparando en el joven, y se lanzó hacia él--; haga usted comprender, se lo suplico, a esa tontuela, que ésta es la mejor vida que podíamos hacer. ¿No se da limosna a los que tocan el organillo? No nos costará trabajo diferenciarnos de ellos. Al primer golpe de vista se reconocerá en nosotros una familia noble caída en la miseria, y ese bribón de general perderá su puesto; ya lo verá usted. Iremos todos los días a ponernos debajo de sus ventanas; pasará el emperador, y yo me pondré de rodillas delante de él y le mostraré a mis hijos. «¡Padre, protégenos!», le diré. El es el padre de los huérfanos; es misericordioso; nos protegerá, ya lo verá usted, y ese infame general... Alena, ponte derecha; tú, Kolia, vas a empezar de nuevo este paso. ¿Por qué estás lloriqueando? ¿No acabarás nunca? Vamos a ver: ¿de qué tienes miedo, imbécil? ¡Dios mío! ¿Qué hacer con ellos? ¡Si supiese usted, Rodión Romanovitch, qué cerrados son de mollera! No hay medio de que hagan nada.\"},{\"heading\":false,\"text\":\"Tenía casi las lágrimas en los ojos, lo que no la impedía hablar incesantemente, mientras mostraba a Raskolnikoff los niños desconsolados. El joven trató de persuadirla de que se fuese a su casa, y creyendo interesar su amor propio, le hizo observar que no era conveniente andar rondando por las calles como los organilleros, siendo así que se proponía abrir un pensionado para las señoritas nobles.\"},{\"heading\":false,\"text\":\"--¡Un pensionado! ¡Ja, ja, ja! ¡Tiene gracia!--exclamó Catalina Ivanovna a quien después de reírse le dió un violento golpe de tos--; no, Rodión Romanovitch; ese sueño se ha desvanecido. Todo el mundo nos ha abandonado y, ¡ese general!... ¿Sabe usted qué le he hecho? Le he tirado a la cara el tintero que estaba sobre la mesa de la antesala, al lado del papel en que los visitantes escriben sus nombres. Después de haber puesto el mío, he tirado el tintero y echado a correr. ¡Oh, los cobardes; los cobardes! pero yo me burlo de ellos. Ahora yo mantendré a mis hijos y no tendré que humillarme ante nadie. Ya la hemos martirizado bastante--añadió dirigiéndose a Sonia--. Poletchka, ¿cuánto dinero hemos recogido? Enséñamelo. ¡Cómo! ¿En junto dos kopeks? ¡Ladrones! Nada, nada, y se contentan con seguirnos haciéndonos desgañita... ¡Oiga! ¿De qué se ríe ese animal? (Señalaba a un hombre del grupo.) La culpa la tiene Kolia; su torpeza es causa de que se burlen de nosotros. ¿Qué quieres, Poletchka? Háblame en francés. Te he dado lecciones; sabes algunas frases... Sin eso, ¿cómo habrá de conocerse que pertenecéis a una familia noble, que sois niños bien educados y no vulgares músicos callejeros? Dejaremos a un lado las canciones triviales; cantaremos sólo nobles romanzas... ¡Ah, sí! Manos a la obra; ¿qué vamos a cantar? Ustedes me interrumpen siempre y nosotros... vea usted, Rodión Romanovitch, nos hemos detenido aquí para elegir nuestro repertorio; porque, como usted comprenderá, esto nos ha tomado desprevenidos, no teníamos nada preparado y nos hace falta un ensayo previo. Después nos dirigiremos a la perspectiva Neusky donde hay muchas más personas de la buena sociedad. Se nos echará de ver inmediatamente. Alena sabe _la Petite Ferme_, sólo que _la Petite Ferme_ comienza a aburrir; por todas partes se oye. Es menester una cosa más distinguida. Pues bien, Poletchka, dame una idea, ven en ayuda de tu madre; yo no tengo memoria... ¿No podríamos cantar _El húsar apoyado en su sable_? No; será mejor que cantemos en francés _Cinco sueldos_; os lo he enseñado; lo sabéis. Como es una canción francesa, se verá en seguida que pertenecéis a la nobleza, y esto conmoverá al público. Podremos cantar también _Mambrú se fué a la guerra_, tanto más cuanto que esta canción es absolutamente infantil y se emplea en todas las casas aristocráticas para dormir a los niños--. Y dicho esto comenzó a cantar:\"},{\"heading\":false,\"text\":\"«Mambrú se fué a la guerra, no sé cuándo vendrá»;\"},{\"heading\":false,\"text\":\"pero no, es mejor _Cinco sueldos_. Vamos, Kolia, ponte la mano en la cadera; vamos, pronto. Tú, Alena, ponte enfrente de él. Poletchka y yo haremos el acompañamiento:\"},{\"heading\":false,\"text\":\"«Cinco sueldos, cinco sueldos para poner nuestra casa.»\"},{\"heading\":false,\"text\":\"Poletchka, levántate la ropa, que se te baja de los hombros--advirtió mientras tosía--. Ahora se trata de que os presentéis convenientemente y que mostréis la finura de vuestro pie, para que se vea que sois hijos de un noble. ¡Otro soldado! ¡Eh! ¿qué es lo que quieres?\"},{\"heading\":false,\"text\":\"Un vigilante se abrió paso entre la gente, y al mismo tiempo un señor de unos cincuenta años y de aspecto grave, que llevaba bajo el abrigo el uniforme de funcionario, se aproximó también al grupo. El recién llegado, cuyo rostro expresaba sincera compasión, llevaba una condecoración, circunstancia que causó gran placer a Catalina Ivanovna, y no dejó de producir bastante buen efecto en el guardia. El señor condecorado alargó a Catalina Ivanovna un billete de tres rublos. Al recibir esta dádiva, la pobre loca se inclinó con la cortesía ceremoniosa de una dama del gran mundo.\"},{\"heading\":false,\"text\":\"--Doy a usted las gracias, señor--empezó a decir en tono lleno de dignidad--. Las causas que nos han conducido... Toma el dinero, Poletchka. ¿Lo ves? Hay hombres generosos y magnánimos, dispuestos a socorrer a una pobre dama que ha caído en la desgracia. Los huérfanos que tiene usted delante, señor, son de linaje noble. Puede decirse que están emparentados con la más elevada aristocracia... y ese general se estaba comiendo un pollo... Ha dado patadas en el suelo porque yo me permitía molestarle. «Vuecencia--le he dicho--ha conocido a Simón Zakharitch, ampare, pues, a sus huérfanos. El día de su entierro, su hija ha sido calumniada por un malvado...» ¿Aún está ahí ese soldado? Protéjame usted--gritó, dirigiéndose al funcionario--; ¿por qué ese soldado se ensaña conmigo? Se nos ha echado ya de la calle de los Burgueses. ¿Qué es lo que quieres, imbécil?\"},{\"heading\":false,\"text\":\"--Está prohibido dar escándalo en las calles. Ruego a usted que guarde más compostura.\"},{\"heading\":false,\"text\":\"--Tú sí que no tienes compostura. Estoy en el mismo caso que los organilleros. Déjame en paz.\"},{\"heading\":false,\"text\":\"--Los organilleros deben proveerse de un permiso que usted no tiene. Es usted causa de que la gente forme grupos en las calles. ¿Dónde vive usted?\"},{\"heading\":false,\"text\":\"--¿Cómo? ¿Un permiso?--vociferó Catalina Ivanovna--. Acabo de enterrar a mi marido; ¿no es ésta una autorización?\"},{\"heading\":false,\"text\":\"--Señora, señora; cálmese usted--dijo el funcionario--; venga usted conmigo. Yo la acompañaré. No es el sitio de usted entre esta gente. Está usted mal.\"},{\"heading\":false,\"text\":\"--¡Ah, señor, señor; si usted supiese!--exclamó Catalina Ivanovna--. Tenemos que ir a la perspectiva Neusky. ¿Por dónde andas, Sonia? También está llorando... ¿Pero qué les pasa a ustedes?... ¡Kolia, Lena! ¿Dónde estáis?--dijo con repentina inquietud--; ¡tontos de chiquillos! ¡Kolia, Lena! ¿Eh dónde se han metido?\"},{\"heading\":false,\"text\":\"Viendo a un guardia que trataba de detenerlos, Kolia y Lena, ya muy aterrados con la presencia de la multitud y las extravagancias de su madre, se habían sentido acometidos de un terror loco. La pobre Catalina Ivanovna, llorando y gimiendo, se lanzó en su persecución; Sonia y Poletchka corrieron tras de ella.\"},{\"heading\":false,\"text\":\"--Hazlos volver, Sonia; llámalos. ¡Oh, qué hijos tan tontos y tan ingratos!... Poletchka, alcánzalos; es por vosotros por lo que yo...\"},{\"heading\":false,\"text\":\"Conforme corría tropezó en un obstáculo y cayó.\"},{\"heading\":false,\"text\":\"--¡Se ha herido! ¡Está bañada en sangre!--gritó Sonia inclinándose sobre su madrastra.\"},{\"heading\":false,\"text\":\"No tardó en formarse un numeroso grupo alrededor de las mujeres, Raskolnikoff y Lebeziatnikoff, así como del funcionario y del guardia entre ellos.\"},{\"heading\":false,\"text\":\"--Retírense ustedes, retírense ustedes--decía sin cesar este último, tratando de restablecer la circulación.\"},{\"heading\":false,\"text\":\"Pero examinando a Catalina Ivanovna, se veía claramente que no estaba herida, como había temido Sonia, y que la sangre con que había manchado el suelo la había echado por la boca.\"},{\"heading\":false,\"text\":\"--Sé lo que es esto--murmuró el funcionario al oído de los dos jóvenes--. Es efecto de la tisis; la sangre brota de este modo y produce la asfixia. No hace mucho tiempo he visto un caso parecido; una de mis parientas echó también un jarro de sangre... ¿Qué hacer? Esta señora se está muriendo.\"},{\"heading\":false,\"text\":\"--Aquí, aquí a mi casa--suplicó Sonia--; vivo aquí al lado. La segunda casa; pronto, pronto. Vayan ustedes por un médico. ¡Oh Dios mío!--repetía asustada yendo de un lado para otro.\"},{\"heading\":false,\"text\":\"Gracias a la activa intervención del funcionario, se arregló este asunto. El guardia ayudó a trasportar a Catalina Ivanovna. Estaba como muerta cuando se la depositó en la cama de Sonia. Continuó la hemorragia durante algún tiempo; pero, poco a poco, la enferma comenzó a volver en sí. En la habitación entraron, además, Sonia, Raskolnikoff, Lebeziatnikoff y el funcionario. El guardia se reunió a ellos después de haber dispersado a los curiosos, muchos de los cuales habían acompañado el triste cortejo hasta la puerta.\"},{\"heading\":false,\"text\":\"Poletchka llegó conduciendo a los dos fugitivos, que temblaban y lloraban. También acudieron los Kapernumoff, el sastre cojo y tuerto. Era un tipo extraño, con el pelo y las patillas de pelos tiesos, como cerdas de puerco; su mujer parecía asustada; pero éste era su aspecto ordinario. El rostro de los chicos sólo expresaba estúpida sorpresa. Entre los presentes apareció rápidamente Svidrigailoff. Ignorando que vivía en esta casa y no acordándose de haberle visto en el grupo, Raskolnikoff se quedó sorprendido de verle allí.\"},{\"heading\":false,\"text\":\"Se habló de llamar a un clérigo y a un médico. El funcionario juzgaba, en las actuales circunstancias, inútiles los recursos de la ciencia, y así se lo dijo por lo bajo a Raskolnikoff; sin embargo, hizo todo lo necesario por encontrar un doctor. Kapernumoff en persona se encargó de ir a buscarlo.\"},{\"heading\":false,\"text\":\"En tanto, Catalina Ivanovna estaba un poco más tranquila y la hemorragia había cesado momentáneamente. La infeliz fijó una mirada triste y penetrante en la pobre Sonia, que, pálida y, temblorosa, le enjugaba la frente con un pañuelo. Finalmente, la enferma pidió que se la incorporase, y la sentaron en el lecho, sosteniéndola de uno y otro lado.\"},{\"heading\":false,\"text\":\"--¿En dónde están los niños?--preguntó con voz débil--. ¿Los has traído, Poletchka? ¡Oh, imbéciles! Decid, ¿por qué habéis echado a correr?... ¡Oh!\"},{\"heading\":false,\"text\":\"La sangre cubría sus labios abrasados. La enferma miró en derredor suyo.\"},{\"heading\":false,\"text\":\"--¿Es así como vives, Sonia? Ni una sola vez había venido aquí... Ha sido menester lo que ha ocurrido para que me conduzcan a tu casa.\"},{\"heading\":false,\"text\":\"Al decir esto dirigió a la joven una mirada de conmiseración.\"},{\"heading\":false,\"text\":\"--Te hemos comido viva, Sonia... Poletchka, Lena, Kolia, venid aquí... Ahí los tienes, Sonia, tómalos a todos. Los pongo entre tus manos... yo, yo ya tengo bastante... el baile ha terminado ya... ¡Soltadme, dejadme morir en paz!\"},{\"heading\":false,\"text\":\"La obedecieron y la enferma se dejó caer sobre la almohada.\"},{\"heading\":false,\"text\":\"--¿Cómo un clérigo?... Yo no tengo necesidad de él. ¿Tenéis acaso, ganas de tirar un rublo? Ningún pecado pesa sobre mi conciencia... y aunque los tuviera, Dios debe perdonarme. El sabe lo que yo he sufrido. Si no me perdona, tanto peor.\"},{\"heading\":false,\"text\":\"Cada vez se confundían más sus ideas. De cuando en cuando temblaba, miraba en derredor suyo y reconocía durante un minuto a los que la rodeaban; pero en seguida volvía a apoderarse de ella el delirio. Respiraba penosamente y se oía como el ruido de un hervor en su garganta.\"},{\"heading\":false,\"text\":\"--Ya le he dicho «Excelencia»--gritaba deteniéndose a cada palabra--; aquella Amalia Ludvigovna... ¡Ah! Lena, Kolia... la mano en la cadera. ¡Vivo, vivo! ¡Deslizaos! Llevad el compás con los pies; así, con gracia.\"},{\"heading\":false,\"text\":\"Du hast Diamanten Und Perlen[18]\"},{\"heading\":false,\"text\":\"Eu hast die schönsten Augen Mädchen, was willst du mehr[19]\"},{\"heading\":false,\"text\":\"Dans une vallée du Daghestan Que le soleil brûle de ses feux...\"},{\"heading\":false,\"text\":\"[18] Tienes diamantes y perlas.\"},{\"heading\":false,\"text\":\"[19] Tienes los más bellos ojos del mundo, ¿qué más quieres, niña?\"},{\"heading\":false,\"text\":\"--¡Oh! ¡Cómo me gustaba; cómo me gustaba esta romanza, Poletchka!... Deliraba por ella... Tu padre la cantaba antes de nuestro matrimonio... ¡Qué días aquellos!... Eso es lo que deberíamos cantar... ¡Oh, sí! ¿Cómo era? Se me ha olvidado, recordádmelo en seguida.\"},{\"heading\":false,\"text\":\"Presa de una agitación extraordinaria pugnaba por incorporarse en el lecho; al cabo, con voz ronca, cascada, siniestra, comenzó, tomando aliento después de cada palabra, en tanto que su rostro expresaba un terror creciente:\"},{\"heading\":false,\"text\":\"Dans une vallée... du Daghestan Que le soleil... brûle... de ses feux. Une balle... dans la poitrine...\"},{\"heading\":false,\"text\":\"De pronto, Catalina Ivanovna rompió a llorar, y, con angustia conmovedora, exclamó:\"},{\"heading\":false,\"text\":\"--Excelencia... proteja a los huérfanos aunque no sea más que recordando la hospitalidad que recibió en casa de Simón Zaharitch Marmeladoff... una casa hasta puede decirse aristocrática... ¡Ah!--exclamó temblando y como tratando de recordar en dónde se encontraba.\"},{\"heading\":false,\"text\":\"Miró con angustia a todos los presentes, y, al reparar en Sonia, pareció sorprendida de verla allí.\"},{\"heading\":false,\"text\":\"--¡Sonia! ¡Sonia!--dijo con voz dulce y tierna--. ¡Sonia querida! ¿Estás aquí?\"},{\"heading\":false,\"text\":\"La incorporaron de nuevo.\"},{\"heading\":false,\"text\":\"--¡Basta, todo ha terminado! ¡Ha reventado la bestia!--gritó la enferma con acento de horrible desesperación y reclinó la cabeza en la almohada.\"},{\"heading\":false,\"text\":\"Catalina Ivanovna volvió a caer en profundo sopor pero no fué por mucho tiempo. Echó hacia atrás su rostro amarillento y descarnado, abrió la boca, extendió convulsivamente las piernas, lanzó un suspiro profundo y expiró.\"},{\"heading\":false,\"text\":\"Sonia, más muerta que viva, se precipitó sobre el cadáver, lo estrechó entre sus brazos, y apoyó la cabeza en el liso pecho de la difunta. Poletchka se puso, sollozando, a besar los pies de su madre. Kolia y Lena, demasiado pequeños para comprender lo que había ocurrido, no por eso dejaban de tener el sentimiento de una terrible catástrofe. Se echaron mutuamente los brazos al cuello, y, después de haberse mirado fijamente, comenzaron a gritar. Los dos chiquillos estaban aún vestidos de saltimbanquis: el uno tenía puesto su turbante; la otra su gorro de dormir, adornado con la pluma de avestruz.\"},{\"heading\":false,\"text\":\"¿Por qué casualidad estaba sobre el lecho, al lado de Catalina Ivanovna, el certificado honorífico? Se hallaba allí, sobre la almohada; Raskolnikoff lo vió. El joven se dirigió a la ventana, y Lebeziatnikoff se apresuró a juntarse con él.\"},{\"heading\":false,\"text\":\"--¡Ha muerto!--dijo Andrés Semenovitch.\"},{\"heading\":false,\"text\":\"Svidrigailoff se aproximó a ellos.\"},{\"heading\":false,\"text\":\"--Rodión Romanovitch, desearía decirle a usted dos palabras.\"},{\"heading\":false,\"text\":\"Lebeziatnikoff cedió el puesto, y se retiró discretamente. Sin embargo, Svidrigailoff creyó conveniente conducir a un rincón a Raskolnikoff, a quien preocupaban aquellas precauciones.\"},{\"heading\":false,\"text\":\"--De todos estos asuntos, es decir, del entierro y de lo demás, yo me encargo. Ya sabe que todo esto es cuestión de dinero, y como ya le he dicho, el que tengo no lo necesito para nada. A esa Poletchka y a estos dos pequeños los haré entrar en un asilo de huérfanos, en donde estarán bien, e impondré a nombre de cada uno mil quinientos rublos hasta su mayor edad, para que Sonia Semenovna no tenga que ocuparse en sus hermanos. En cuanto a esa joven, la retiraré del cenagal en que se halla, porque es una excelente muchacha, ¿no es verdad? Bueno, puede usted decir a Advocia Romanovna qué empleo he hecho de su dinero.\"},{\"heading\":false,\"text\":\"--¿Por qué es usted tan generoso?--preguntó Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¡Qué escéptico es usted!--dijo Svidrigailoff--. Le dije que no necesitaba ese dinero. Pues bien: lo hago por humanidad. ¿No lo cree usted acaso? Después de todo--añadió señalando el rincón en que reposaba la muerta--, esta mujer no es un gusano, como cierta mujer usurera. ¿Conviene usted en que sería mejor que muriese ella y que Ludjin viviese para cometer infamias? Sin mi ayuda, Poletchka, por ejemplo, sería condenada a la misma existencia que su hermana.\"},{\"heading\":false,\"text\":\"Su tono, alegremente malicioso, estaba lleno de reticencias, y cuando hablaba no apartaba los ojos de Raskolnikoff.\"},{\"heading\":false,\"text\":\"Este último palideció y empezó a temblar al oír las frases casi textuales que él mismo había empleado en su conversación con Sonia. Así es que se echó bruscamente hacia atrás, y miró a Svidrigailoff con expresión de asombro.\"},{\"heading\":false,\"text\":\"--¿Cómo sabe usted eso?--balbuceó.\"},{\"heading\":false,\"text\":\"--Porque habito aquí, del otro lado de la pared, en casa de la señora Reslich, mi antigua patrona y excelente amiga. Soy el vecino de Sonia Semenovna.\"},{\"heading\":false,\"text\":\"--¿Usted?\"},{\"heading\":false,\"text\":\"--Yo--continuó Svidrigailoff, que se reía a mandíbula batiente--. Y le doy mi palabra, querido Rodión Romanovitch, de que me ha interesado usted extraordinariamente. Ya le dije que nos encontraríamos. Tenía el presentimiento de ello. Pues bien: ya nos hemos encontrado, y usted verá qué tratable soy. Ya verá usted cómo se puede vivir conmigo.\"},{\"heading\":false,\"text\":\"SEXTA PARTE\"}]},{\"title\":\"sexta parte — capítulo I\",\"blocks\":[{\"heading\":false,\"text\":\"La situación de Raskolnikoff era muy extraña; parecía que una especie de niebla le envolvía y aislaba del resto de los hombres. Cuando, andando el tiempo, se acordaba de este período de su vida, adivinaba que había debido de perder muchas veces la conciencia de sí mismo y que tal estado de ánimo hubo de prolongarse y durar, con ciertos intervalos lúcidos, hasta la catástrofe definitiva. Estaba positivamente convencido de que había incurrido en muchos desaciertos: por ejemplo, el de no haber advertido a menudo la sucesión cronológica de los acontecimientos. Por lo menos, cuando más adelante quiso coordinar sus recuerdos, fuéle forzoso recurrir a testimonios extraños para saber muchas particularidades acerca de sí mismo.\"},{\"heading\":false,\"text\":\"Confundía marcadamente los hechos, o consideraba tal incidente como consecuencia de otro que sólo existía en su imaginación. A veces sentíase dominado por un temor morboso que degeneraba en terror pánico; pero se acordaba también de que había tenido momentos, horas, y tal vez días, en los cuales, por el contrario estuvo sumido en una apatía triste sólo comparable con la indiferencia de ciertos moribundos.\"},{\"heading\":false,\"text\":\"En general, en este último tiempo, lejos de procurar darse cuenta exacta de su situación, hacía esfuerzos para no pensar en ella. Algunos hechos de la vida corriente que no admitían dilación, se imponían, a pesar suyo, a su mente; por lo contrario, se complacía en desdeñar cuestiones cuyo olvido, en una posición como la suya, por fuerza había de serle fatal.\"},{\"heading\":false,\"text\":\"Tenía, sobre todo, miedo a Svidrigailoff. Desde que este último le había repetido las palabras por él pronunciadas en casa de Sonia, los pensamientos de Raskolnikoff tomaron una dirección nueva. Pero aunque esta complicación imprevista le inquietaba mucho, el joven no se apresuraba a poner las cosas en claro. A veces, cuando vagaba por algún barrio lejano y solitario, o cuando se veía solo sentado a la mesa de un mal cafetín, sin saber por qué se encontraba allí, pensaba en Svidrigailoff y se prometía tener lo más pronto posible una explicación decisiva con aquel hombre que era para él una constante pesadilla.\"},{\"heading\":false,\"text\":\"Cierto día fué casualmente a pasear por las afueras y se le figuró que había dado cita a Svidrigailoff en aquel lugar. Otra vez, al despertarse antes de la aurora, se quedó estupefacto al verse tendido en tierra, en medio de un bosquecillo. Por lo demás, durante los dos o tres días que siguieron a la muerte de Catalina Ivanovna, Raskolnikoff encontró dos o tres veces a Svidrigailoff, primero en el cuarto de Sonia, y después en el vestíbulo, al lado de la escalera, del domicilio de la joven.\"},{\"heading\":false,\"text\":\"En ambas ocasiones los dos hombres se limitaron a cambiar algunas palabras muy breves, absteniéndose de tocar el punto capital, como si, por acuerdo tácito, se hubiesen entendido para dejar de lado momentáneamente aquella cuestión. El cadáver de Catalina Ivanovna estaba todavía insepulto. Svidrigailoff tomaba las disposiciones relativas a los funerales. Sonia estaba también ocupadísima. En el último encuentro, Svidrigailoff contó a Rodia que sus gestiones en favor de los hijos de Catalina Ivanovna habían sido coronadas por el éxito: gracias a la influencia de ciertos personajes amigos suyos, pudo, según decía, conseguir la admisión de los tres niños en muy buen asilo. Los mil quinientos rublos colocados a nombre de ellos no habían contribuído poco a este resultado, porque se admitían con muchas menos dificultades a los huérfanos que poseían un capitalito que a aquellos otros que carecían de recursos. Añadió algunas palabras a propósito de Sonia, prometió pasar uno de aquellos días por casa de Raskolnikoff, y dió a entender que existían ciertos asuntos de los que quería tratar reservadamente con él. Mientras hablaba Svidrigailoff, no cesaba de observar a su interlocutor. De repente se calló; pero después preguntó, bajando la voz:\"},{\"heading\":false,\"text\":\"--Pero, ¿qué le pasa a usted, Rodión Romanovitch? Parece que está distraído, no escucha, no mira, diríase que no comprende usted lo que se le habla... Vaya, recobre ánimos. Será preciso que hablemos largo y tendido... Desgraciadamente estoy tan ocupado con mis asuntos como con los ajenos... ¡Eh, Rodión Romanovitch!--añadió bruscamente--. A todos los hombres les hace falta aire, mucho aire, aire ante todo.\"},{\"heading\":false,\"text\":\"Se apartó vivamente para dejar pasar a un clérigo y a un sacristán, que se disponían a subir la escalera. Iban a rezar el oficio de difuntos. Svidrigailoff había cuidado de que esta ceremonia se verificase regularmente dos veces por día. Se alejó luego, y Raskolnikoff, tras un momento de reflexión, siguió al _pope_ a la habitación de Sonia. Se quedó, empero, en el umbral. El oficio comenzó con la tranquila y triste solemnidad de costumbre. Desde su infancia, Raskolnikoff experimentaba una especie de terror místico ante el aparato de la muerte, y evitaba, siempre que podía, asistir a las _panikhida_. Además, ésta tenía para él un carácter particularmente conmovedor. Miró a los niños, que estaban arrodillados cerca del ataúd. Poletchka lloraba; detrás de ellos, Sonia rezaba, procurando ocultar sus lágrimas. «Durante todos estos días no ha levantado una sola vez los ojos hasta mí, ni me ha dicho una sola palabra», pensó Raskolnikoff. El sol inundaba de viva luz la habitación, y el humo del incienso subía en espesas espirales.\"},{\"heading\":false,\"text\":\"El sacerdote recitó las preces de ritual: «Dale, Señor, el reposo eterno.» Raskolnikoff permaneció allí hasta el fin. Al echar la bendición y al despedirse, el clérigo dirigió una mirada de extrañeza en derredor suyo. Después del oficio, Raskolnikoff se acercó a Sonia. La joven tomó las dos manos de Rodia, y reclinó la cabeza sobre su hombro. Aquella demostración de amistad dejó estupefacto al que era objeto de ella. ¿Cómo? ¡Sonia no manifestaba la menor aversión ni el menor horror hacia él, ni le temblaban las manos! Aquello era el colmo de la abnegación. Así por lo menos lo juzgó él. La joven no dijo una palabra. Raskolnikoff le estrechó la mano y salió.\"},{\"heading\":false,\"text\":\"Sentía un profundo malestar. Si en aquel momento le hubiera sido posible encontrar en alguna parte la soledad, aunque esta soledad hubiese de durar toda la vida, se hubiera considerado feliz. ¡Ay! Desde hacía ya algún tiempo, aunque estuviese casi siempre solo, no podía decirse que estuviese aislado. Le ocurría pasearse fuera de la ciudad o irse por una carretera adelante. Una vez penetró en lo más intrincado de un bosque; pero cuanto más solitario era el lugar, más de cerca sentía Raskolnikoff la presencia de un ser invisible, que le irritaba más que le asustaba. Apresurábase a volver a la ciudad, se mezclaba con la multitud, entraba en los cafés y en las tabernas, iba al Tolkutchy o a la Siennia. Allí se encontraba más a gusto y hasta más solo.\"},{\"heading\":false,\"text\":\"A la caída de la noche se cantaban canciones en cierto cafetín. Allí pasó una hora entera, escuchándolas con placer; pero en seguida se apoderó de él nuevamente la inquietud; un pensamiento opresor como un remordimiento empezó a torturarle.\"},{\"heading\":false,\"text\":\"«¿Debo estarme aquí oyendo canciones?»\"},{\"heading\":false,\"text\":\"Adivinaba que no era aquél su único cuidado. Había una cuestión que era preciso resolver sin tardanza; pero, aunque se imponía a su atención, no acertaba a darle una forma precisa.\"},{\"heading\":false,\"text\":\"«No; es preferible la lucha, tener enfrente a Porfirio o a Svidrigailoff. Sí, sí, es mejor un adversario cualquiera, un ataque que rechazar.»\"},{\"heading\":false,\"text\":\"Haciéndose estas reflexiones salió presuroso del cafetín. De repente, el pensamiento de su madre y de su hermana le llenó de terror. Pasó aquella noche en el bosque de Krestorevesy-Ostroff; se despertó antes de la aurora, temblando de fiebre y se encaminó a su casa a donde llegó muy temprano. Después de algunas horas de sueño, desapareció la fiebre, pero se despertó tarde: a las dos.\"},{\"heading\":false,\"text\":\"Se acordó de que aquel día era el señalado para las exequias de Catalina Ivanovna, y se felicitó de no haber asistido a ellas. Anastasia le trajo la comida; el joven comió y bebió con mucho apetito, casi con avidez. Tenía la cabeza más fresca y disfrutaba de una calma que le era desconocida desde tres días antes. Hubo un instante en que se asombró de los accesos de terror pánico que había experimentado.\"},{\"heading\":false,\"text\":\"La puerta se abrió y entró Razumikin.\"},{\"heading\":false,\"text\":\"--¡Ah! Comes, luego no estás malo--dijo el visitante, tomando una silla y sentándose enfrente de Raskolnikoff.\"},{\"heading\":false,\"text\":\"Estaba muy agitado, y no trataba de ocultarlo. Hablaba con cólera visible pero con apresuramientos, y sin levantar mucho la voz: se comprendía que su venida era motivada por alguna causa grave.\"},{\"heading\":false,\"text\":\"--Escucha--comenzó a decir en tono resuelto--; pienso dejar a todos ustedes en paz, porque veo claramente que el juego que hacen es indescifrable para mí. No vayas a creer que vengo a interrogarte; no trato de sacarte las palabras del cuerpo. Aunque tú mismo me dijeras todos tus secretos, me negaría a oírlos; escupiría y me iría. Vengo con el único objeto de estudiar personalmente tu estado mental. Hay personas que te creen loco de remate o en vísperas de estarlo, y te confieso que me sentía inclinado a participar de esa opinión, en vista de que tu proceder es estúpido, bastante feo y completamente inexplicable. Además, ¿qué pensar de tu reciente conducta con tu madre y con tu hermana? ¿Qué hombre, a menos de ser un canalla o un loco, se hubiera portado con ellas como te has portado tú? Luego estás loco.\"},{\"heading\":false,\"text\":\"--¿Cuándo las has visto?\"},{\"heading\":false,\"text\":\"--Ahora mismo. Y tú, ¿no las ves? Dime, te lo ruego, ¿dónde has estado metido todo el día? Tres veces he venido hoy. Desde ayer, tu madre se encuentra seriamente enferma. Ha querido venir a verte. Advocia Romanovna se esforzó por disuadirla, pero Pulkeria Alexandrovna no quiso hacer caso de nada... «Si está malo, si está perturbado--dijo--, ¿quién ha de cuidarle sino su madre?» Para no dejarla venir sola, la acompañamos, suplicándole sin cesar que se tranquilizase. Cuando llegamos, no estabas aquí. Ahí, en ese sitio, ha estado sentada por espacio de diez minutos; nosotros en pie, al lado de ella, callábamos. «Puesto que sale--dijo levantándose--, es señal de que no está enfermo y de que olvida a su madre; no está bien, por lo tanto, que venga yo a mendigar las caricias de mi hijo.» Se volvió a su casa y se metió en la cama. Ahora tiene fiebre. «Lo comprendo perfectamente--dice--; le dedica a ella todo el tiempo.» Supone que Sonia Semenovna es tu novia o tu amante. Fuí en seguida a casa de esa joven, porque, amigo mío, me corría prisa comprobar ese punto. Entro, y ¿qué es lo que veo? un ataúd, niños que lloran, y a Sonia Semenovna que les prueba trajes de luto. Tú no estabas allí. Después de haberte buscado con los ojos, he dado mis excusas, he salido y he ido a contar a Advocia Romanovna el resultado de mis pesquisas. Decididamente todo esto nada significa. Aquí no se trata de ningún amorío; resta, pues, como lo más probable, la hipótesis de la locura. He aquí que ahora te encuentro con trazas de comerte un buey cocido, como si no hubieses tomado nada en cuarenta y ocho horas. Sin duda, el estar loco no impide comer; pero, aunque tú no me hayas dicho una palabra, no estás loco... pondría por ello la mano en el fuego. Para mí, éste es un punto fuera de discusión. Así, pues, os envío a todos al diablo, en vista de que hay aquí un misterio y de que no tengo la intención de romperme la cabeza con vuestros secretos. He venido solamente para decirte cuatro frescas y aliviarme el corazón. Por lo demás, yo sé lo que tengo que hacer.\"},{\"heading\":false,\"text\":\"--¿Qué vas a hacer?\"},{\"heading\":false,\"text\":\"--¿Qué te importa?\"},{\"heading\":false,\"text\":\"--¿Vas a dedicarte a la bebida?\"},{\"heading\":false,\"text\":\"--¿Cómo lo has adivinado?\"},{\"heading\":false,\"text\":\"--No es muy difícil adivinarlo.\"},{\"heading\":false,\"text\":\"Razumikin se quedó un momento silencioso.\"},{\"heading\":false,\"text\":\"--Has sido siempre muy inteligente, y nunca, nunca has estado loco--observó luego--. Has dicho la verdad; voy a dedicarme a la bebida. Adiós.\"},{\"heading\":false,\"text\":\"Y dió un paso hacia la puerta.\"},{\"heading\":false,\"text\":\"--Anteayer, si mal no recuerdo, he hablado de ti a mi hermana--dijo Raskolnikoff.\"},{\"heading\":false,\"text\":\"Razumikin se detuvo de repente.\"},{\"heading\":false,\"text\":\"--¿De mí? ¿Dónde has podido verla anteayer?--preguntó, poniéndose un tanto pálido. Estaba agitadísimo.\"},{\"heading\":false,\"text\":\"--Vino aquí sola. Se ha sentado en este sitio, y ha hablado conmigo.\"},{\"heading\":false,\"text\":\"--¿Ella?\"},{\"heading\":false,\"text\":\"--Sí; ella.\"},{\"heading\":false,\"text\":\"--¿Y qué le has dicho?... de mí, por supuesto.\"},{\"heading\":false,\"text\":\"--Le he dicho que eras un hombre excelente, honrado y laborioso. No le he dicho que tú la amabas, porque lo sabe.\"},{\"heading\":false,\"text\":\"--¿Que ella lo sabe?\"},{\"heading\":false,\"text\":\"--Claro que sí. Le he dicho también que, aunque yo me vaya, ocúrrame lo que me ocurra, tú debes ser siempre su Providencia. Yo las pongo, por decirlo así, en tus manos, Razumikin. Te digo esto, porque sé perfectamente que las amas y estoy convencido de la pureza de tus sentimientos. Sé también que ella puede amarte, si es que ya no te ama. Decide ahora si debes o no debes darte a la bebida.\"},{\"heading\":false,\"text\":\"--Rodia... ¿Lo estás viendo?... Pues bien... ¡Demonio! Pero tú, ¿dónde vas a ir? Bueno. Desde el momento que todo esto es un secreto, no hay que hablar de ello; pero yo... yo sabré de qué se trata. Estoy convencido de que no es una cosa seria, sino tonterías con las cuales forma monstruos tu imaginación; tú eres un hombre excelente. Sí, un hombre excelente.\"},{\"heading\":false,\"text\":\"--Quería añadir: pero me has interrumpido, que tenías razón hace un momento, cuando declarabas que renunciabas a conocer estos secretos. No te preocupes. Las cosas se descubrirán a su tiempo, y lo sabrás todo cuando el momento llegue. Ayer me dijo una persona que al hombre le hacía falta aire, aire, aire. Voy a ir en seguida a preguntarle lo que quieren decir sus palabras.\"},{\"heading\":false,\"text\":\"Razumikin reflexionaba, y al cabo se le ocurrió esta idea:\"},{\"heading\":false,\"text\":\"«Es, de seguro, un conspirador político y está en vísperas de una tentativa audaz; no puede ser de otra manera, y Dunia lo sabe», pensó de repente.\"},{\"heading\":false,\"text\":\"--¿De modo que Advocia Romanovna viene a tu casa--repuso recalcando cada frase--, y tú tratas de ver a alguno que dice que es menester más aire? Probable es que la carta haya sido enviada por ese hombre.\"},{\"heading\":false,\"text\":\"--¿Qué carta?\"},{\"heading\":false,\"text\":\"--Ha recibido una que la ha llenado de inquietud. He querido hablarle de ti y me ha suplicado que me callase. Después... después me dijo que nos separaríamos dentro de breve plazo, y se ha mostrado muy reconocida conmigo, tras de lo cual se encerró en su cuarto.\"},{\"heading\":false,\"text\":\"--¿Ha recibido una carta?--preguntó Raskolnikoff intrigado.\"},{\"heading\":false,\"text\":\"--Sí. ¿No lo sabías?\"},{\"heading\":false,\"text\":\"Los dos permanecieron callados durante un minuto.\"},{\"heading\":false,\"text\":\"--Adiós, Rodia, amigo mío... En cierto tiempo... Vamos, adiós... Tengo también que irme; por lo que hace a darme a la bebida, no haré tal cosa: es inútil.\"},{\"heading\":false,\"text\":\"Salió muy de prisa; pero apenas acababa de cerrar la puerta, cuando volvió a abrirla de repente, mirando de través.\"},{\"heading\":false,\"text\":\"--A propósito, ¿te acuerdas de aquel crimen? ¿del asesinato de aquella vieja? Pues has de saber que se ha descubierto el asesino; él mismo se ha reconocido culpable, y ha suministrado todas las pruebas necesarias en apoyo de sus afirmaciones. Es... ¡pásmate! uno de aquellos pintores a los cuales defendía yo con tanto ardor. ¿Querrás creerlo? La persecución de los dos obreros, corriendo el uno detrás del otro en la escalera, mientras subían el _dvornik_ y los dos testigos, los cachetes que se daban riendo, todo ello no era más que una treta imaginada para evitar sospechas. ¡Qué astucia! ¡Qué presencia de ánimo en ese tunante! Parece imposible; pero lo ha explicado todo; ha confesado por completo. ¡Qué despistado estaba yo! Tengo a ese hombre por el genio del disimulo y de la astucia. Después de esto, no hay ya nada de qué asombrarse. Fuerza es admitir la existencia de semejantes individuos. Si no ha sostenido su papel hasta el fin, si ha entrado en el camino de las confesiones, me veo obligado a admitir la verdad de lo que él dice. ¿Y yo he estado ciego hasta este punto? ¿Y he roto lanzas yo por esos dos hombres?\"},{\"heading\":false,\"text\":\"--Te ruego que me digas cómo lo has sabido, y por qué te interesa tanto ese asunto--preguntó Raskolnikoff visiblemente agitado.\"},{\"heading\":false,\"text\":\"--¿Que por qué me interesa? ¡Vaya una pregunta! En cuanto a la noticia me la han dado muchas personas, y principalmente Porfirio. El es quien me lo ha dicho casi todo.\"},{\"heading\":false,\"text\":\"--¿Porfirio?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--¿Y qué es lo que te ha dicho?--preguntó Raskolnikoff inquieto.\"},{\"heading\":false,\"text\":\"--Me lo ha explicado todo a maravilla, procediendo por el método psicológico, según su costumbre.\"},{\"heading\":false,\"text\":\"--¿Y te lo ha explicado él mismo?\"},{\"heading\":false,\"text\":\"--El mismo; adiós. Algo te diré más adelante. Ahora tengo necesidad de dejarte... Hubo un tiempo en que llegué a creer... vamos, ya te lo contaré otro día... ¿Qué necesidad tengo de beber ahora? Tus palabras han bastado para embriagarme. En este momento estoy ebrio, ebrio sin haber bebido una gota de vino. Adiós, hasta muy pronto.\"},{\"heading\":false,\"text\":\"Y salió.\"},{\"heading\":false,\"text\":\"«Es un conspirador político; sí, de seguro, de seguro--acabó definitivamente Razumikin, mientras bajaba la escalera.--Ha comprometido, sin duda, a su hermana en esta empresa; esta conjetura es muy probable, dado el carácter de Advocia Romanovna. Han celebrado entrevistas... Ya me lo habían hecho sospechar ciertas palabras... esas alusiones... sí, eso es. De otro modo, ¿cómo encontrar una explicación? ¿Y pudo ocurrírseme? ¡Oh, Dios mío, que cosa había imaginado! Sí, había formado un juicio temerario, yo soy culpable respecto de él. La otra noche, en el corredor, al observar su rostro iluminado por la luz de la lámpara, tuve un minuto de alucinación. ¡Oh, qué idea tan horrible pude concebir! Mikolai ha hecho perfectamente en confesar. Sí, al presente se explica todo lo pasado: la enfermedad de Rodia, la extrañeza de su conducta, aquel humor sombrío o feroz que manifestaba ya cuando era estudiante... Pero, ¿qué significa esta carta? ¿de dónde procede? Algo todavía hay ahí... Yo sospecho... no tendré reposo hasta que halle la clave de todo esto.»\"},{\"heading\":false,\"text\":\"Al pensar en Dunia, sintió que se le helaba el corazón y se quedó como clavado en el suelo. Tuvo que hacer un violento esfuerzo sobre sí mismo.\"},{\"heading\":false,\"text\":\"En cuanto se hubo marchado Razumikin, Raskolnikoff se levantó y se acercó a la ventana; luego se paseó de un rincón a otro, como si hubiese olvidado las dimensiones exiguas de su cuartucho. Al fin, volvió a sentarse en el sofá. Un repentino cambio habíase operado en él; tenía aún que luchar; era un recurso.\"},{\"heading\":false,\"text\":\"Sí, un recurso; un medio de escapar de su penosa situación y de la angustia que padecía desde que vió a Mikolai en el despacho de Porfirio. Después de aquel dramático incidente, en el mismo día, ocurrió la escena en casa de Sonia, escena cuyas peripecias y desenlaces habían engañado las previsiones de Raskolnikoff. Se había mostrado débil; había reconocido, de acuerdo con la joven, y reconocido sinceramente, que no podía llevar solo semejante fardo. ¿Y Svidrigailoff? Este era un enigma que le inquietaba, pero de otra manera; existía quizá medio de desembarazarse de Svidrigailoff; pero de Porfirio era harina de otro costal.\"},{\"heading\":false,\"text\":\"«¿De modo que el mismo Porfirio es el que ha explicado a Razumikin la culpabilidad de Mikolai procediendo por el método psicológico?--continuaba diciéndose Raskolnikoff--. De seguro hay aquí algo de esa maldita psicología. ¿Porfirio? ¿Cómo Porfirio ha podido creer durante un solo minuto culpable a Mikolai, después de la escena que acababa de pasar entre nosotros, y que no admite más que _una_ solución? Durante aquella entrevista, sus palabras, sus gestos, sus miradas, el sonido de su voz, todo demostraba en él una convicción tan invencible que no ha podido quebrantar ninguna de las pretendidas confesiones de Mikolai.\"},{\"heading\":false,\"text\":\"»Hasta el mismo Razumikin comenzaba a dudar. El incidente del corredor le ha hecho reflexionar, sin duda. Corrió a casa de Porfirio; pero, ¿por qué este último le ha engañado de este modo? Es evidente que no ha hecho tal cosa sin ningún motivo; debe de tener sus intenciones; pero, ¿cuáles son? En verdad, ha pasado ya bastante tiempo desde aquel día, y no tengo aún ni rastro de noticias de Porfirio. Quién sabe, sin embargo, si éste no será un mal signo...»\"},{\"heading\":false,\"text\":\"Raskolnikoff tomó la gorra, y, después de ligera reflexión, se decidió a salir. Aquel día, por primera vez, después de muy largo tiempo, se sentía en plena posesión de sus facultades intelectuales.\"},{\"heading\":false,\"text\":\"«Es preciso acabar con Svidrigailoff--pensaba--, y, cueste lo que cueste, terminar este asunto lo más pronto posible. Además, parece que espera mi visita.»\"},{\"heading\":false,\"text\":\"En aquel instante se desbordó el odio de tal manera en su corazón, que, si hubiese podido matar al uno o al otro de aquellos dos seres detestables, Svidrigailoff o Porfirio, acaso no habría vacilado en hacerlo.\"},{\"heading\":false,\"text\":\"Mas apenas había acabado de abrir la puerta, cuando se encontró cara a cara con Porfirio en persona. El juez de instrucción venía a su casa. Al pronto Raskolnikoff se quedó estupefacto; pero se repuso en seguida. Cosa extraña: aquella visita, ni le asombró demasiado, ni le causó casi ningún terror.\"},{\"heading\":false,\"text\":\"«Esto es, acaso, el desenlace; mas, ¿por qué ha amortiguado el ruido de sus pasos? Nada he oído. Quizá estaba escuchando detrás de la puerta.»\"},{\"heading\":false,\"text\":\"--No esperaba usted mi visita--dijo alegremente Porfirio Petrovitch--. Tenía desde hace mucho tiempo el propósito de venir a verle y, al pasar delante de su casa, se me ha ocurrido entrar a saludarle. ¿Iba usted a salir? No le detendré. Cinco minutos solamente, el tiempo de fumar un cigarrillo...\"},{\"heading\":false,\"text\":\"--Siéntese usted, Porfirio Petrovitch, siéntese usted--dijo Raskolnikoff ofreciendo una silla al visitante, con un aire tan afable y satisfecho, que él mismo se hubiera sorprendido si hubiese podido verse.\"},{\"heading\":false,\"text\":\"Habían desaparecido todas las huellas de sus impresiones precedentes. Acontece a veces que el hombre que por espacio de media hora ha estado luchando con un ladrón experimentando angustias mortales, no siente ningún temor cuando el puñal del bandido llega a su garganta.\"},{\"heading\":false,\"text\":\"El joven se sentó enfrente de Porfirio y fijó en él una mirada tranquila. El juez de instrucción guiñó los ojos y comenzó por encender un cigarrillo.\"},{\"heading\":false,\"text\":\"«¡Ah! ¡Vamos, habla, habla ya!», le gritaba mentalmente Raskolnikoff.\"}]},{\"title\":\"sexta parte — capítulo II\",\"blocks\":[{\"heading\":false,\"text\":\"--¡Oh, estos cigarrillos--dijo por fin Porfirio--son mi muerte, y no puedo renunciar a ellos! Toso, tengo un principio de irritación en la garganta, y, además, soy asmático. No hace mucho que me hice visitar por Botkin, que emplea para examinar un enfermo por lo menos media hora; después de haberme reconocido atentamente, y auscultado, etc., me dijo, entre otras cosas: «No le prueba a usted el tabaco; tiene usted los pulmones dilatados.» Está bien; pero, ¿cómo dejar de fumar? ¿cómo substituir una costumbre? Yo no bebo. Ahí tiene usted la desgracia; ¡je, je, je! Todo es relativo, señor Raskolnikoff.\"},{\"heading\":false,\"text\":\"«He aquí otra vez un preámbulo que deja traslucir la astucia jurídica», murmuró aparte Raskolnikoff.\"},{\"heading\":false,\"text\":\"Se acordó de su reciente entrevista con el juez de instrucción, y aquel recuerdo aumentó la cólera de que su alma rebosaba.\"},{\"heading\":false,\"text\":\"--Estuve ayer aquí, ¿no lo sabía?--continuó Porfirio Petrovitch, paseando la mirada en derredor suyo;--estuve en este mismo cuarto. Halléme como hoy casualmente en la calle de usted, y se me ocurrió hacerle una visita. La puerta estaba abierta, entré, le esperé un momento, y fuí después, sin decir mi nombre a la criada. ¿No cierra usted nunca?\"},{\"heading\":false,\"text\":\"La fisonomía de Raskolnikoff se obscurecía cada vez más. Porfirio Petrovitch adivinó, sin duda, lo que Raskolnikoff estaba pensando.\"},{\"heading\":false,\"text\":\"--He venido a explicarme, querido Rodión Romanovitch. Debo a usted una explicación--prosiguió sonriendo y dando un golpecito en la rodilla del joven; pero casi al mismo instante tomó su cara una expresión seria, hasta triste, con gran asombro de Raskolnikoff, a quien el juez de instrucción se mostraba ahora bajo una fase inesperada--. La última vez que nos vimos pasó entre nosotros una extraña escena. Quizá he cometido con usted grandes errores, y lo siento. Recordará usted cómo nos separamos. Ambos teníamos los nervios muy excitados. Hemos faltado a las más elementales conveniencias, y, sin embargo, somos caballeros.\"},{\"heading\":false,\"text\":\"«¿A dónde va a parar?»--se preguntaba Raskolnikoff sin apartar los ojos de Porfirio con inquieta curiosidad.\"},{\"heading\":false,\"text\":\"--He pensado que haríamos mejor en adelante en obrar con sinceridad--repuso el juez de instrucción, bajando un poco los ojos, como si temiese turbar por esta vez con sus miradas a su víctima--; no es preciso que se renueven semejantes escenas. El otro día, sin la entrada de Mikolai no se adónde habrían llegado las cosas. Usted es muy irascible por temperamento, Rodión Romanovitch, y sobre esto me apoyé, porque un hombre muy acalorado deja muchas veces escapar sus secretos. ¡Si yo pudiese, me decía, arrancar una prueba cualquiera, aunque fuese la más insignificante, pero real, tangible, palpable, otra cosa distinta, en fin, que todas esas inducciones psicológicas! Tal es el cálculo que había yo hecho. Algunas veces este método da el resultado apetecido; pero esto no ocurre siempre, como he tenido ocasión de comprobar. Me hacía muchas ilusiones respecto del carácter de usted.\"},{\"heading\":false,\"text\":\"--¿Pero usted, por qué me dice todo eso?--balbuceó Raskolnikoff, sin acabar de darse cuenta de la cuestión que se planteaba--. «¿Me creerá acaso inocente?»--añadió para sí.\"},{\"heading\":false,\"text\":\"--¿Por qué digo esto? Considero como un deber sagrado explicar a usted mi conducta, porque le he sometido, y lo reconozco, a una cruel tortura, y no quiero, Rodión Romanovitch, que me considere como un monstruo. Voy, pues, para justificarme, a exponer los antecedentes de este asunto. Al principio circularon rumores acerca de cuyo origen y naturaleza creo superfluo hablar; inútil creo también decirle a usted en qué ocasión se ha mezclado en este asunto la persona de usted. En cuanto a mí, lo que me ha hecho sospechar, es una circunstancia por otra parte puramente fortuita, de la cual no he dicho una palabra. De esos rumores y de esas circunstancias accidentales se ha desprendido para mí la misma conclusión. Lo confieso francamente, porque, a decir verdad, yo he sido el primero que ha puesto su nombre sobre el tapete. Dejo a un lado las anotaciones de los objetos encontrados en casa de la vieja. Tal indicio y otros muchos del mismo género nada significan. Estando en esto, tuve ocasión de conocer el incidente ocurrido en el despacho de policía. Aquella escena me fué referida con todo género de pormenores por alguno que había desempeñado su papel a las mil maravillas. Pues bien; en tales condiciones, ¿cómo no inclinarse en cierta dirección? «Cien conejos no hacen un caballo; cien presunciones no hacen una prueba», dice el proverbio inglés; esto también es lo que aconseja la razón; pero, ¿quién puede luchar contra las pasiones? El juez de instrucción es hombre, y, por consiguiente, apasionado. Me acordé también del trabajo que publicó usted en una Revista. Me había gustado mucho como aficionado, por supuesto, aquel primer ensayo de la juvenil pluma de usted. Se veía allí una convicción sincera y un entusiasmo ardiente. Aquel artículo debió de ser escrito con mano febril durante una noche de insomnio. «El autor no se detendrá aquí», pensé yo al leerlo. ¿Cómo, dígame usted, no relacionar esto con lo que luego se siguió? La atracción era irresistible. ¡Ah, señor! ¿Digo algo? ¿Afirmo al presente lo que esto sea? Me limito a señalar una reflexión que me hice entonces. ¿Qué es lo que pienso ahora? Nada; es decir, poco menos que nada. Por el momento, tengo entre las manos a Mikolai y hay hechos que le acusan... ¡Valientes hechos! Si le digo todo esto, es para que no dé usted torcida interpretación a mi conducta del otro día. ¿Por qué, me preguntará usted, no se hizo un registro en mi casa? Estuve aquí. ¡Je, je! Estuve cuando se hallaba usted enfermo, no como magistrado, sin carácter oficial. El cuarto de usted, desde las primeras sospechas, fué registrado minuciosamente, pero sin resultado. Entonces me dije: «Este hombre vendrá a mi casa, vendrá él mismo a buscarme, y dentro de muy poco tiempo; si es culpable, no puede dejar de venir. Otro no vendría, pero éste no faltará. ¿Se acuerda usted de las palabrerías de Razumikin? Le habíamos comunicado de intento nuestras conjeturas, con la esperanza de que él excitaría a usted hasta el punto de hacerle confesar. El señor Zametoff estaba asombrado de la audacia de usted, y, en efecto, mucha se necesitaba para decir en pleno café «yo he matado». Era eso verdaderamente cosa muy arriesgada. Yo le esperaba a usted con impaciencia confiada, y he aquí que Dios le envió. ¡Con qué fuerza latía mi corazón cuando le vi a usted presentarse! Vamos a ver, ¿qué necesidad tenía usted de ir? Sin duda recordará también que entró riéndose a carcajadas. Su risa me dió mucho que pensar; pero si no hubiese estado prevenido, tal vez no hubiera fijado mi atención en ello. ¡Y Razumikin! ¿Y qué decir de la piedra? ¿Se acuerda usted? La piedra bajo la cual están ocultos los objetos. Me parece que la estoy viendo desde aquí, no sé dónde, en un huerto. ¿No es de un huerto de lo que usted habló a Zametoff? Después, cuando hablamos del artículo de la Revista, creímos ver una segunda intención detrás de cada una de las palabras de usted. He aquí cómo, Rodión Romanovitch, mi convicción se ha ido formando poco a poco. «Ciertamente esto puede explicarse de otra manera», solía decirme yo, y aun podría ser que fuese más natural; convengo en ello. Mejor sería una prueba, por pequeña que fuese. Pero al saber la historia del cordón de la campanilla, no tuve ya duda alguna; creí poseer la prueba deseada, y ya no he querido reflexionar más. En aquel momento hubiera dado de buena gana mil rublos de mi bolsillo por verle a usted con mis propios ojos, andando cien pasos, hombro con hombro con un burgués que le había llamado a usted asesino, sin que usted se atreviese a responderle. Cierto; no se debe dar gran importancia a los hechos y gestos de un enfermo que habla bajo una especie de delirio. Sin embargo, después de lo sucedido, ¿cómo ha podido asombrarse usted, Rodión Romanovitch, de la manera como me he portado? ¿Y por qué, precisamente en aquel momento, vino usted a mi casa? El mismo diablo, sin duda, le impulsó a usted, y si Mikolai no nos hubiese separado... ¿Se acuerda usted de la entrada de Mikolai? Aquello fué como un rayo. ¡Cómo lo recibí! No hice el menor caso de sus palabras, como pudo usted advertir. Después que usted se marchó seguí interrogándole. Me respondió sobre ciertos puntos de una manera tan exacta, que me quedé asombrado; a pesar de esto, sus declaraciones no lograron destruir mi incredulidad, y me quedé tan inquebrantable como una roca.»\"},{\"heading\":false,\"text\":\"--Razumikin acaba de decirme que estaba usted ya convencido de la culpabilidad de Mikolai; que usted mismo le había asegurado que...\"},{\"heading\":false,\"text\":\"Le faltó el habla y no pudo continuar.\"},{\"heading\":false,\"text\":\"--¡Ah, Razumikin!--exclamó Porfirio Petrovitch, que parecía satisfecho de haber oído, al cabo, que salía una observación de labios de Raskolnikoff--. ¡Je, je, je! trataba de verme libre de Razumikin, que venía a mi casa con aires investigadores y que nada tiene que ver en este negocio. Dejémosle a un lado, si a usted le parece. ¿Quiere usted saber la idea que tengo yo formada de Mikolai? Ante todo, es como un niño; aun no ha llegado a su mayor edad. Sin ser precisamente una naturaleza pusilánime, es impresionable como un artista. No se ría usted si le caracterizo de ese modo: es cándido, sensible, fantástico. En su pueblo, canta, baila y narra cuentos, que van a oír los campesinos de las aldeas vecinas. Suele beber hasta perder la razón; no porque sea, propiamente hablando, lo que se dice un borracho, sino porque no sabe resistir a la influencia del ejemplo cuando se halla entre amigos. No comprende que ha cometido un robo apropiándose de un estuche que ha encontrado. «Puesto que lo he encontrado en el suelo, dice, tenía perfecto derecho a tomarlo.» Según los vecinos de Zaraisk, sus paisanos, era devoto hasta la exaltación: pasaba las noches rezando y leía sin cesar libros religiosos (los viejos, los verdaderos). San Petersburgo ha influído mucho en él, y una vez aquí, se ha dado al vino y a las mujeres, lo que le ha hecho olvidar la religión. Sé que uno de nuestros artistas ha comenzado a darle lecciones. En esto ocurre ese crimen. El pobre muchacho se asusta, y se echa una cuerda al cuello. ¿Qué quiere usted? Nuestro pueblo no puede sacudir de su espíritu el prejuicio de que todo hombre buscado por la policía es hombre condenado. En la prisión, Mikolai ha vuelto al misticismo de sus primeros años. Ahora tiene sed de expiación, y sólo por eso se ha confesado culpable. Mi convicción en este punto está basada en ciertos hechos que él mismo no conoce. Por lo demás, acabará por confesarme toda la verdad. ¿Cree usted que sostendrá su papel hasta el fin? Espere usted un poco, y ya verá cómo rectifica sus confesiones. Además, si logra dar sobre ciertos puntos un carácter de verosimilitud a su declaración, en cambio sobre otros se encuentra en completa contradicción con los hechos, y nada sabe de ellos. No, Rodión Romanovitch, no; el culpable no es Mikolai. Nos encontraremos frente a un hecho fantástico y sombrío; este crimen tiene la marca del siglo y lleva hondamente grabado el sello de una época que hace consistir toda la vida en buscar la comodidad. El culpable es un tétrico, una víctima del libro; ha desplegado en su ensayo mucha audacia; pero esta audacia es de un género particular: es la de un hombre que se precipita desde lo alto de una montaña o de un campanario. Ha olvidado cerrar la puerta detrás de él y ha matado a dos personas para poner en práctica una teoría. Ha matado y no ha sabido aprovecharse de su dinero; lo que pudo tomar fué a ocultarlo bajo una piedra. No bastándole las angustias pasadas en la antesala mientras oía los golpes dados a la puerta y el sonido repetido de la campanilla, cediendo a una irresistible necesidad de experimentar la misma emoción, fué más tarde a visitar el cuarto vacío y a tirar del cordón de la campanilla. Atribuyamos esto a la enfermedad, a un semidelirio, bueno; pero he aquí un punto digno de notarse; ha matado, y no deja de considerarse como un hombre honrado, desprecia a los demás, y se da aires de ángel pálido. No, no se trata aquí de Mikolai, Rodión Romanovitch. Mikolai no es culpable.\"},{\"heading\":false,\"text\":\"Este golpe era tanto más inesperado, cuanto que llegaba después de la especie de honrosa disculpa dada por el juez de instrucción. Raskolnikoff se echó a temblar.\"},{\"heading\":false,\"text\":\"--Entonces, ¿quién es el que ha matado?--balbuceó con voz entrecortada.\"},{\"heading\":false,\"text\":\"El juez de instrucción se recostó en el respaldo de la silla, como asombrado de semejante pregunta.\"},{\"heading\":false,\"text\":\"--¿Cómo? ¿Que quién ha matado?--replicó, como si no hubiese dado crédito a sus oídos--. ¿Quién ha de ser? ¡Usted, Rodión Romanovitch, usted es el que ha matado! ¡Sí, usted!...--añadió en voz baja y en tono de profundo convencimiento.\"},{\"heading\":false,\"text\":\"Raskolnikoff se levantó bruscamente, permaneció en pie algunos segundos, y después se sentó sin decir una sola palabra. Ligeras convulsiones agitaban los músculos de su rostro.\"},{\"heading\":false,\"text\":\"--Le tiemblan a usted las manos como el otro día--hizo notar con interés Porfirio--. Por lo que veo, usted no se ha hecho cargo del objeto de mi visita, Rodión Romanovitch--prosiguió, después de una pausa--. De aquí el asombro de usted. He venido precisamente para decirlo todo y esclarecer la verdad.\"},{\"heading\":false,\"text\":\"--¡Yo no he matado!--murmuró el joven, defendiéndose como lo hace un niño sorprendido en falta.\"},{\"heading\":false,\"text\":\"--Sí, ha sido usted, Rodión Romanovitch; ha sido usted, usted solo--replicó severamente el juez de instrucción.\"},{\"heading\":false,\"text\":\"Ambos se callaron y, cosa extraña, este silencio se prolongó por unos diez minutos.\"},{\"heading\":false,\"text\":\"Apoyado de codos sobre la mesa, Raskolnikoff se metía los dedos entre el cabello. Porfirio Petrovitch esperaba sin dar señal alguna de impaciencia. De repente el joven miró despreciativamente al magistrado.\"},{\"heading\":false,\"text\":\"--Vuelve usted a sus antiguas prácticas, Porfirio Petrovitch. ¡Siempre los mismos procedimientos! ¿Cómo no le fastidian a usted ya?\"},{\"heading\":false,\"text\":\"--No se ocupe usted de mis procedimientos. Otra cosa sería si estuviésemos en presencia de testigos; pero aquí hablamos a solas. No he venido para cazarle y prenderle como un pajarito. Que usted confiese o no, en este momento me es igual. En un caso y en otro, mi convicción está formada.\"},{\"heading\":false,\"text\":\"--Si eso es así, ¿por qué ha venido usted?--preguntó con mal gesto Raskolnikoff--; le repito la pregunta que ya en otra ocasión le hice: Si me cree usted culpable, ¿por qué no dicta un auto de prisión contra mí?\"},{\"heading\":false,\"text\":\"--¡Vaya una pregunta! Le responderé a usted punto por punto: en primer lugar, la detención de usted no me serviría para nada.\"},{\"heading\":false,\"text\":\"--¿Cómo? ¿Que no le serviría a usted de nada? Puesto que está convencido, debería usted...\"},{\"heading\":false,\"text\":\"--¿Qué importa mi convicción? Hasta el presente no descansa más que sobre nubes. ¿Y para qué había de poner a usted _en reposo_? Usted lo comprende, puesto que pide usted que se le detenga. Supongo que careado con el burgués, usted diría: «Tú, de seguro, estabas bebido. ¿Quién me ha visto contigo? Te tomé sencillamente por lo que eres, por un borracho.» ¿Qué podría yo replicarle entonces, tanto más, cuanto que la respuesta de usted sería más verosímil que la declaración de él, que es de pura psicología, y porque, además, la apreciación de usted sería exacta, puesto que ese hombre es conocido por su afición a los licores? Muchas veces le he confesado a usted con franqueza que toda esta psicología tiene dos filos, y que, fuera de eso, yo, por el momento, ninguna prueba tengo contra usted. Claro es que, al cabo, le detendré, y he venido aquí para avisárselo, y, sin embargo, no vacilo en manifestarle que eso no me servirá de nada. El segundo objeto de mi venida...\"},{\"heading\":false,\"text\":\"--¿Cuál es?--preguntó Raskolnikoff anhelante.\"},{\"heading\":false,\"text\":\"--... Ya se lo he dicho. Tenía que explicarle mi conducta, porque no quiero pasar a los ojos de usted por un monstruo, y además, porque, créalo o no, mis intenciones son muy favorables a usted. En vista, pues, del interés que yo siento por usted, le propongo francamente vaya a denunciarse. He venido aquí para darle este consejo. Es el partido más ventajoso que puede tomar, ventajoso para usted y para mí, que me vería desembarazado de este asunto. ¿Qué le parece a usted? Soy bastante franco?\"},{\"heading\":false,\"text\":\"Raskolnikoff reflexionó durante un minuto.\"},{\"heading\":false,\"text\":\"--Escuche usted, Porfirio Petrovitch; según sus propias palabras, no tiene contra mí más que inducciones psicológicas y aspira a la evidencia matemática. ¿Quién le dice que no se engaña?\"},{\"heading\":false,\"text\":\"--No, Rodión Romanovitch, no me engaño. Tengo una prueba, que encontré el otro día; Dios me la ha enviado.\"},{\"heading\":false,\"text\":\"--¿Qué prueba es ésa?\"},{\"heading\":false,\"text\":\"--No se lo diré a usted; pero, en todo caso, no tengo el derecho de contemporizar; voy a hacerle detener. Ahora juzgue usted. Cualquier resolución que tome actualmente, poco me importa; cuanto le he dicho es únicamente en interés suyo. La mejor solución es la que yo le indico: créalo usted, Rodión Romanovitch.\"},{\"heading\":false,\"text\":\"El joven se sonrió con expresión de cólera.\"},{\"heading\":false,\"text\":\"--El lenguaje de usted es más que ridículo: es impudente. Supongamos que soy culpable (lo que en modo alguno reconozco): ¿por qué he de ir a denunciarme, puesto que, como dice usted mismo, allí, en la cárcel, estaría _en reposo_?\"},{\"heading\":false,\"text\":\"--¡Oh Rodión Romanovitch! No tome usted estas palabras al pie de la letra. Puede usted encontrar allí reposo, y puede no encontrarlo. Tengo, es cierto, la creencia de que la prisión tranquiliza al culpable; pero esto no es más que una teoría, y una teoría mía personal. Así, pues, ¿soy yo una autoridad para usted? ¡Quién sabe si en este momento mismo no le oculto alguna cosa! No puede usted exigir que le entregue todos mis secretos, ¡je, je, je! Lo incontestable es el provecho que sacará usted haciendo lo que yo le propongo: irá ganando, puesto que su condena disminuirá notablemente. Piense usted un poco en qué momento vendría a denunciarse: en el que otra persona ha asumido sobre sí la responsabilidad del crimen, embrollando, en cierto modo, el proceso. Por lo que a mí toca, juro ante Dios dejarle a usted en el tribunal todas las ventajas de su iniciativa. Los jueces ignorarán, se lo prometo, toda esa psicología, todas las sospechas recaídas sobre usted y su conducta tendrá a los ojos de aquellos magistrados un carácter absolutamente espontáneo. En el crimen de usted no se verá más que el resultado de una impulsión fatal, y no otra cosa. Soy un hombre honrado, Rodión Romanovitch, y mantendré mi palabra.\"},{\"heading\":false,\"text\":\"Raskolnikoff bajó la cabeza y reflexionó durante largo tiempo; luego sonrióse de nuevo; pero esta vez su sonrisa era dulce y melancólica.\"},{\"heading\":false,\"text\":\"--¿Qué me importa?--dijo, sin parecer que se daba cuenta de que su lenguaje equivalía casi a una confesión--, ¿qué me importa la diminución de pena de que usted me habla? No la necesito para nada.\"},{\"heading\":false,\"text\":\"--Vamos, lo que yo temía--exclamó, como a pesar suyo, Porfirio--. Ya me temía yo que desdeñaría usted nuestra indulgencia.\"},{\"heading\":false,\"text\":\"Raskolnikoff le miró con expresión grave y triste.\"},{\"heading\":false,\"text\":\"--No desprecie usted la vida--continuó el juez de instrucción--. Todavía es muy larga para usted. ¿Cómo? ¿No quiere una diminución de pena? ¡A fe que no es usted descontentadizo!\"},{\"heading\":false,\"text\":\"--¿Qué tendría yo en adelante en perspectiva?\"},{\"heading\":false,\"text\":\"--La vida. ¿Acaso es usted profeta, para saber lo que la vida le reserva? Busque usted, y encontrará. Quizá Dios esperaba a usted. Por otra parte, su condena no será perpetua.\"},{\"heading\":false,\"text\":\"--¡Obtendré circunstancias atenuantes!...--dijo riendo Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¿Es quizá, vergüenza burguesa lo que le impide a usted confesarse culpable? ¡Es preciso sobreponerse a eso!\"},{\"heading\":false,\"text\":\"--¡Eh! ¡Yo me burlo de esa preocupación!--murmuró con tono despreciativo el joven.\"},{\"heading\":false,\"text\":\"Hizo ademán de levantarse; pero se quedó sentado, abatidísimo.\"},{\"heading\":false,\"text\":\"--Es usted desconfiado, y piensa, sin duda, que trato de embaucarle groseramente; pero, ¿acaso ha vivido usted mucho? ¿qué sabe usted de la existencia? Ha imaginado usted una teoría que ha venido a producir en la práctica consecuencias cuya falta de originalidad le avergüenza ahora. Ha cometido usted un crimen, es verdad; pero no es usted, ni con mucho, un criminal irremisiblemente perdido. ¿Cuál es mi opinión acerca de usted? Le considero como uno de esos hombres que se dejarían arrancar las entrañas sonriendo a sus verdugos, con tal solamente de haber encontrado una fe o un Dios. Pues bien: encuéntrelos usted, y vivirá. En primer lugar, tiene usted necesidad, desde hace tiempo, de cambiar de aire. Además, el sufrimiento es una buena cosa. Sufra usted. Quizá Mikolai tiene razón al querer sufrir. Ya sé yo que es usted un escéptico, pero sin razonar, abandónese usted a la corriente de la vida; esta corriente le llevará a alguna parte. ¿A dónde? No se preocupe usted; ya llegará a alguna orilla. ¿Cuál? Lo ignoro, creo solamente que usted debe vivir todavía mucho tiempo. Sin duda, piensa usted ahora que estoy representando el papel de juez; pero acaso más tarde se acuerde usted de mis palabras y saque provecho de ellas; por eso le hablo así. Todavía es una ventaja que no haya usted matado más que a una mala vieja. Con otra teoría, habría cometido usted una acción cien mil veces peor. Puede usted aun dar gracias a Dios. ¡Quién puede saber cuáles son sus altos designios acerca de usted! Recobre usted su valor, no retroceda por pusilaminidad ante lo que exige la justicia. Sé que usted no me cree; pero con el tiempo volverá a tomar gusto a la vida. Ahora lo que le hace falta solamente es aire, aire, aire.\"},{\"heading\":false,\"text\":\"Raskolnikoff se estremeció.\"},{\"heading\":false,\"text\":\"--Pero, ¿quién es usted--gritó--para hacerme esas profecías? ¿Qué suprema sabiduría le permite adivinar mi porvenir?\"},{\"heading\":false,\"text\":\"--¿Que quién soy? Un hombre acabado, y nada más. Un hombre sensible y compasivo, a quien la experiencia ha enseñado quizás algo; pero un hombre completamente acabado. Usted es otra cosa; usted se halla al principio de la existencia, y esta aventura, ¿quién sabe? quizá no dejará ninguna huella en la vida de usted. ¿Por qué temer tanto el cambio que va a experimentar en su situación? ¿Son acaso las comodidades de la vida las que usted ha de echar de menos? ¿Se aflige usted pensando que ha de estar largo tiempo confinado en la obscuridad? De usted depende que esta obscuridad no sea eterna. Sea usted un sol, y todo el mundo le verá. ¿Por qué se sonríe usted? ¿Piensa que éstas son maniobras de juez de instrucción? Es muy posible, ¡je, je! No le pido que me crea bajo mi palabra, Rodión Romanovitch; hago mi oficio, convengo en ello; pero acuérdese de lo que le digo. Los acontecimientos le demostrarán si soy un impostor o un hombre honrado.\"},{\"heading\":false,\"text\":\"--¿Cuándo piensa usted detenerme?\"},{\"heading\":false,\"text\":\"--Puedo dejarle a usted aún día y medio o dos días en libertad. Haga usted sus reflexiones, amigo mío; ruegue usted a Dios que le inspire. El consejo que le doy es bueno, créalo usted.\"},{\"heading\":false,\"text\":\"--¿Y si me escapase?--preguntó Raskolnikoff con equívoca sonrisa.\"},{\"heading\":false,\"text\":\"--No se escapará. Un _mujik_ huiría: un revolucionario de ahora, esclavo de pensamiento ajeno, huiría también, porque tiene un _credo_ ciegamente aceptado para toda la vida; pero usted no cree en su teoría. ¿Qué quedaría de ella si huyera usted? Y, por otra parte, ¿puede darse una existencia más innoble y penosa que la de un fugitivo? Si huyese usted, volvería para entregarse espontáneamente... _¡Usted no puede pasarse sin nosotros!_ Cuando yo le detuviese al cabo de un mes o dos, pongamos tres, se acordaría de mis palabras y confesaría. Vendría usted a parar a esto insensiblemente, casi sin darse cuenta de ello. Más aún, estoy persuadido de que, después de haberlo reflexionado usted bien, se decidirá usted a aceptar la expiación. En este momento no lo cree; pero ya verá. En efecto, Rodión Romanovitch, el sufrimiento es una gran cosa. En boca de un hombre que no se priva de nada, este lenguaje puede parecer ridículo. No importa; hay una idea en el sentimiento. Mikolai tiene razón. Usted no emprenderá la fuga, Rodión Romanovitch.\"},{\"heading\":false,\"text\":\"Raskolnikoff se levantó y tomó la gorra; el juez hizo lo mismo.\"},{\"heading\":false,\"text\":\"--¿Va usted a pasearse? La tarde será buena; sólo que no hay tormenta. Sería conveniente, porque refrescaría la temperatura.\"},{\"heading\":false,\"text\":\"--Porfirio Petrovitch--dijo el joven con tono seco y breve--, le ruego que no vaya a figurarse que le he hecho hoy confesiones. Es usted un hombre extraño, y le he escuchado por pura curiosidad; pero no he confesado nada... no lo olvide usted.\"},{\"heading\":false,\"text\":\"--Basta, no lo olvidaré. ¡Oh, cómo tiembla! No se inquiete usted, querido: tomo nota de su recomendación. Pasee usted un poco; pero no traspase ciertos límites. En todo caso, tengo un pequeño encargo que hacer a usted--dijo bajando la voz--; es algo delicado, pero tiene su importancia: en el caso, poco probable según mi creencia, de que durante esas cuarenta y ocho horas le dé a usted la humorada de acabar con su vida (perdóneme esta absurda suposición), deje usted un billetito, nada más que dos líneas, indicando el sitio donde está la piedra; eso será más noble. Ea, hasta la vista; que Dios le inspire buenos pensamientos.\"},{\"heading\":false,\"text\":\"Porfirio se retiró, evitando mirar a Raskolnikoff, y éste se acercó a la ventana y esperó con impaciencia el momento en que, según sus cálculos, el juez de instrucción debía de estar lejos de la casa. En seguida salió de ella apresuradamente.\"}]},{\"title\":\"sexta parte — capítulo III\",\"blocks\":[{\"heading\":false,\"text\":\"Tenía prisa de ver a Svidrigailoff. Ignoraba qué era lo que podía esperar de aquel hombre que ejercía sobre él un poder tan misterioso. Desde que Raskolnikoff se hubo convencido de ello, le devoraba la inquietud, y al presente no podía retrasar el momento de una explicación.\"},{\"heading\":false,\"text\":\"Conforme iba andando le preocupaba, sobre todo, esta sospecha: ¿habrá ido Svidrigailoff a casa de Porfirio?\"},{\"heading\":false,\"text\":\"Pero a lo que él se le alcanzaba, Svidrigailoff no debía haber ido. Raskolnikoff lo hubiera jurado. Repasando en su mente todas las circunstancias de las visitas de Porfirio, llegaba siempre a la misma conclusión negativa. Pero el que Svidrigailoff no hubiese ido aún, no quería decir que no lo haría más tarde.\"},{\"heading\":false,\"text\":\"Sin embargo, en este punto el joven se inclinaba también a creer que no iría. ¿Por qué? No habría podido aducir las razones en que se fundaba, y aunque hubiera podido explicárselo, no se habría preocupado demasiado. Todas estas cosas le atormentaban, y al propio tiempo le eran casi indiferentes. Cosa extraña, casi increíble: por crítica que fuese su situación actual, Raskolnikoff no tenía, a causa de ella, más que una débil inquietud. Lo que le ponía en cuidado era una cuestión mucho más importante, que no era aquélla. Experimentaba, además, un inmenso cansancio moral, aunque para razonar se hallaba en mucho mejor estado que los días precedentes.\"},{\"heading\":false,\"text\":\"Después de tantos combates librados, ¿sería menester aún nueva lucha para triunfar de aquellas miserables dificultades? ¿Convendría, por ejemplo, ir a poner sitio a Svidrigailoff, ante el temor de que fuese a casa del juez de instrucción?\"},{\"heading\":false,\"text\":\"¡Oh, cuánto le enervaba todo aquello!\"},{\"heading\":false,\"text\":\"Sin embargo, tenía prisa de ver a Arcadio Ivanovitch. ¿Esperaba de él algo nuevo, un consejo, un medio de salir de su situación? Los náufragos se agarran a una paja. ¿Era el destino o el instinto lo que empujaba a estos hombres uno hacia el otro? Quizá Raskolnikoff daba este paso sencillamente porque no sabía a qué santo encomendarse; tal vez tenía necesidad de alguien que no fuese Svidrigailoff, y tomaba a este último a falta de otro mejor. ¿Sonia? ¿Para qué había de ir a casa de Sonia? ¿Para hacerla llorar más? Por otra parte, Sonia le daba espanto. Esta joven era para él el decreto irrevocable, la sentencia sin apelación. En aquel momento no se sentía con fuerzas para afrontar la vista de la muchacha. No, era mejor hacer una tentativa acerca de Svidrigailoff. Se confesaba interiormente que desde hacía largo tiempo Arcadio Ivanovitch le era en cierto modo necesario.\"},{\"heading\":false,\"text\":\"No obstante, ¿qué podía haber de común entre ellos? Su criminalidad misma no era motivo para aproximarlos. Aquel hombre le desagradaba mucho, pues evidentemente era muy disipado y quizá muy malo. Acerca de él corrían siniestras leyendas. Cierto que protegía a los huérfanos de Catalina Ivanovna; pero, ¿sabía por qué obraba de este modo? Tratándose de semejante hombre, había de temer siempre algún tenebroso designio.\"},{\"heading\":false,\"text\":\"Desde muchos días antes no cesaba de inquietarle otro pensamiento, aunque el joven, por lo penoso que le era, se esforzase en desecharlo.\"},{\"heading\":false,\"text\":\"«Svidrigailoff anda siempre dando vueltas en derredor mío--se decía--; ha descubierto mi secreto, tuvo intenciones acerca de mi hermana... quizá las tiene todavía. ¿Tratará ahora que posee mi secreto de emplearlo como arma contra Dunia?»\"},{\"heading\":false,\"text\":\"Este pensamiento, que solía preocuparle hasta en sueños, no se había presentado jamás a su imaginación con tanta claridad como en aquel momento en que se dirigía al domicilio de Svidrigailoff. Se le ocurrió la idea de decírselo todo a su hermana, lo que cambiaría extraordinariamente la situación. Pensó después que haría bien en denunciarse, para prevenir un paso imprudente por parte de Dunia. ¿Y la carta? Aquella mañana Dunia había recibido una. ¿Quién, en San Petersburgo, podía escribirle? ¿Acaso Ludjin? En verdad, Razumikin era buen guardián, pero no sabía nada. «¿No debería yo contárselo todo a Razumikin?--se preguntó Raskolnikoff con alivio de corazón--. En todo caso, es preciso ver cuanto antes a Svidrigailoff. Gracias a Dios, los pormenores importan aquí menos que el fondo de la cuestión; pero si Svidrigailoff tiene la audacia de intentar alguna cosa contra mi hermana, le mataré.»\"},{\"heading\":false,\"text\":\"Tenía el alma oprimida por un penoso presentimiento. Se detuvo en medio de la calle y miró en derredor suyo. ¿Qué camino había tomado? ¿En dónde estaba? Se encontraba en la perspectiva***, a treinta o cuarenta pasos del Mercado del Heno, que acababa de atravesar. El piso segundo de la casa a la izquierda estaba ocupado totalmente por un café; todas las ventanas se hallaban abiertas. A juzgar por las cabezas que allí se veían, el café debía estar lleno de gente. En la sala se cantaba, se tocaba el violín, el clarinete y el tambor turco; se oían también gritos de mujeres. Sorprendido de verse en aquel sitio, el joven iba a volver sobre sus pasos, cuando, de pronto, en una de las ventanas vió a Svidrigailoff con la pipa en la boca, sentado delante de una mesa de tomar te. Aquella vista le causó asombro mezclado de terror. Svidrigailoff le contemplaba en silencio y, cosa que asombró aún más a Raskolnikoff, hizo un movimiento como si tratase de impedir que le viesen. Por su parte Raskolnikoff fingió no verle, y se puso a mirar hacia otro lado; pero continuaba siguiéndole con el rabillo del ojo. La inquietud le hacía latir el corazón. Evidentemente Svidrigailoff no quería ser visto. Se quitó la pipa de la boca y quiso retirarse; pero al levantarse reconoció, sin duda, que era demasiado tarde. Repitióse sobre poco más o menos la misma escena que al principio de la entrevista en la habitación de Raskolnikoff; cada uno de ellos sabía que era observado por el otro. Una maliciosa sonrisa erró en los labios de Svidrigailoff, el cual prorrumpió, al fin, en una estrepitosa carcajada.\"},{\"heading\":false,\"text\":\"--¡Pues bien, entre usted, si quiere; aquí estoy!--gritó desde la ventana.\"},{\"heading\":false,\"text\":\"El joven subió.\"},{\"heading\":false,\"text\":\"Encontró a Svidrigailoff en un gabinete pequeño contiguo a una gran sala, en la cual había muchos parroquianos: comerciantes, funcionarios, y otros estaban tomando te y oyendo a los coristas que hacían un estruendo espantoso. En una habitación inmediata se jugaba al billar. Svidrigailoff tenía delante una botella de _Champagne_ empezada y un vaso medio lleno. Le acompañaban dos músicos callejeros: un organillero y una cantante. Esta, muchacha de diez y ocho años, fresca y bien portada, llevaba un traje a rayas y un sombrero tirolés adornado de cintas. Acompañada por el organillero cantaba con voz de contralto, bastante fuerte, una canción trivial en medio del ruido que llegaba de la otra sala.\"},{\"heading\":false,\"text\":\"--¡Ea, basta!--dijo Svidrigailoff cuando entró el hermano de Dunia.\"},{\"heading\":false,\"text\":\"La cantante se detuvo en seguida y esperó en actitud respetuosa. Antes también, mientras dejaba oír sus vulgaridades melódicas, mostraba en su fisonomía cierta expresión de respeto.\"},{\"heading\":false,\"text\":\"--¡Eh, Felipe, un vaso!--gritó Svidrigailoff.\"},{\"heading\":false,\"text\":\"--No bebo vino--dijo Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Como usted guste. Bebe, Katia. Ahora no tengo necesidad de ti; puedes retirarte.\"},{\"heading\":false,\"text\":\"Sirvió un gran vaso de vino y le dió un billetito de color amarillo. Katia bebió el vaso de _Champagne_ a pequeños sorbos como suelen hacerlo las mujeres, y después de haber tomado el billete, besó la mano de Svidrigailoff, que aceptó con aire grave el testimonio de aquel respeto servil.\"},{\"heading\":false,\"text\":\"Aun no hacía ocho días que Arcadio Ivanovitch había llegado a San Petersburgo, y ya se le tenía por un antiguo parroquiano del establecimiento.\"},{\"heading\":false,\"text\":\"--Iba a casa de usted--dijo Raskolnikoff, cuando les dejaron solos--; pero, ¿cómo se explica que atravesando el Mercado del Heno he tomado por la perspectiva***? Jamás paso por aquí. Tomo siempre la derecha al salir del Mercado. Este no es el camino para ir al domicilio de usted. Apenas he asomado por esta parte, cuando le he visto... ¡Es extraño!\"},{\"heading\":false,\"text\":\"--¿Por qué no añade usted que es un milagro?\"},{\"heading\":false,\"text\":\"--Porque quizá no es más que una casualidad.\"},{\"heading\":false,\"text\":\"--Esa es la salida a que recurren todos--contestó riendo Svidrigailoff--. Aunque en el fondo se crea en el milagro, nadie se atreve a confesarlo. Usted mismo acaba de decir que esto «quizá» no es más que una casualidad. No puede usted imaginarse, Rodión Romanovitch, cuán poco valor hay aquí para sostener una opinión. No lo digo por usted, porque sé que si tiene una opinión personal, no teme afirmarla; por eso precisamente ha atraído usted mi curiosidad.\"},{\"heading\":false,\"text\":\"--¿Sólo por eso?\"},{\"heading\":false,\"text\":\"--Me parece que es bastante.\"},{\"heading\":false,\"text\":\"Svidrigailoff se hallaba en un visible estado de excitación, aunque no había bebido más que un vaso de vino espumoso.\"},{\"heading\":false,\"text\":\"--Creo que cuando usted vino a mi casa ignoraba todavía si yo tenía o no eso que llama usted opinión personal--observó Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Entonces era otra cosa. Cada cual tiene su manera de ver; pero, en cuanto al milagro, diré que quizá ha estado usted durmiendo durante todos estos días. Yo mismo le di las señas de este café, y no es sorprendente que haya usted venido derechamente a él. Le indiqué el camino que se debe seguir para encontrarme. ¿No se acuerda usted?\"},{\"heading\":false,\"text\":\"--Lo he olvidado--respondió sorprendido Raskolnikoff.\"},{\"heading\":false,\"text\":\"--No lo dudo; por dos veces le he dado estas indicaciones. La dirección se ha grabado maquinalmente en la memoria de usted, y ella le ha guiado a su pesar; pero he aquí que se me ocurre una cosa: estoy seguro de que en San Petersburgo muchas personas andan hablando consigo mismas. Es una ciudad de semilocos. Si hubiese en ella sabios, médicos, jurisconsultos y filósofos, podrían hacer curiosos estudios, cada cual en su especialidad. No hay otro lugar en el mundo en que el alma humana esté sometida a influencias tan sombrías y tan extrañas; la acción solamente del clima es ya funesta. Desgraciadamente, San Petersburgo es el centro administrativo de la nación, y su carácter debe reflejarse en toda Rusia. Mas ahora no se trata de eso; quería decirle a usted que le he visto pasar muchas veces por la calle. Al salir de casa llevaba usted la cabeza alta; después de andar veinte pasos la baja usted, y cruza los brazos detrás de la espalda. Mira usted, pero es evidente que no ve cosa alguna. Por último, se pone usted a mover los labios y a hablar consigo mismo; unas veces gesticula, otras declama, otras se detiene en medio de la calle, durante más o menos tiempo. Esto, en rigor, nada significa. Sin embargo, se fijan en usted varias personas, como yo, y tal cosa no carece de peligros. A mí, ¿qué me importa? No tengo la pretensión de curarle; pero usted, sin duda, me comprende.\"},{\"heading\":false,\"text\":\"--¿Sabe usted que se me sigue?--preguntó Raskolnikoff fijando en Svidrigailoff una mirada investigadora.\"},{\"heading\":false,\"text\":\"--No--respondió éste asombrado--; no sé nada.\"},{\"heading\":false,\"text\":\"--Bueno, no hablemos de mí--murmuró Raskolnikoff frunciendo las cejas.\"},{\"heading\":false,\"text\":\"--Está bien. No hablaremos de usted.\"},{\"heading\":false,\"text\":\"--Dígame más bien si es verdad que por dos veces me ha indicado este _traktir_ como sitio en que podía encontrarle a usted; ¿por qué, hace un momento, cuando he levantado los ojos a la ventana, se ha ocultado usted, tratando de que yo no le viera? Lo he advertido perfectamente.\"},{\"heading\":false,\"text\":\"--¡Je, je, je! ¿Y por qué el otro día, cuando entré en el cuarto de usted, se fingió el dormido, aunque estaba despierto? Lo advertí muy bien.\"},{\"heading\":false,\"text\":\"--Podía tener razones... usted lo sabe.\"},{\"heading\":false,\"text\":\"--Y yo, ¿no podía también tener razones, aunque usted no las conociese?\"},{\"heading\":false,\"text\":\"Hacía un minuto que Raskolnikoff contemplaba atentamente el rostro de su interlocutor. Aquella cara le causaba siempre un nuevo asombro. Aunque bella, tenía algo que le hacía profundamente antipática. Parecía una máscara; el color era demasiado fresco, los labios demasiado rojos, la barba demasiado rubia, los cabellos demasiado espesos, los ojos demasiado azules y la mirada demasiado fija. Svidrigailoff vestía un elegante traje de verano y eran irreprochables la blancura y finura de su camisa. Llevaba en uno de los dedos un gran anillo con una piedra de valor.\"},{\"heading\":false,\"text\":\"--Entre nosotros no sirven las tergiversaciones--dijo bruscamente el joven--; aunque esté usted en capacidad de hacerme mucho mal, si tiene deseos de molestarme, quiero hablarle franca y claramente. Sepa usted, pues, que si sigue con las mismas intenciones acerca de mi hermana, y si cuenta usted para labrar su objeto con el secreto que ha sorprendido últimamente, le mataré a usted antes de que me hayan metido en la cárcel. Le doy a usted mi palabra de honor. En segundo lugar, he creído advertir estos días que deseaba usted tener una entrevista conmigo. Si algo tiene que comunicarme, despáchese, porque el tiempo es precioso, y quizá bien pronto será demasiado tarde.\"},{\"heading\":false,\"text\":\"--¿Qué es lo que corre a usted tanta prisa?--preguntó Svidrigailoff, mirándole con curiosidad.\"},{\"heading\":false,\"text\":\"--Cada cual tiene sus negocios--dijo Raskolnikoff con aire sombrío.\"},{\"heading\":false,\"text\":\"--Acaba usted de invitarme a que sea franco, y a la primera pregunta rehusa usted responderme--observó Svidrigailoff--. Me supone usted siempre algunos proyectos. En la posición de usted, tal cosa se comprende perfectamente; pero aunque tengo el deseo de vivir en buena armonía con usted, no me tomaré la molestia de desengañarle. Verdaderamente no vale la pena; no tengo nada que decirle.\"},{\"heading\":false,\"text\":\"--¿Por qué está usted siempre dando vueltas en derredor mío?\"},{\"heading\":false,\"text\":\"--Sencillamente porque es usted un sujeto muy digno de ser observado. Ha excitado usted mi curiosidad por lo fantástico de su situación. Además, es usted el hermano de una persona que me interesa mucho; ella me ha hablado de usted varias veces, y su lenguaje me ha hecho pensar que tiene usted una gran influencia sobre ella. ¿No son bastantes razones éstas? ¡Je, je, je! Por lo demás, lo confieso, la pregunta es para mí compleja, y me es muy difícil responder a ella. Si usted, por ejemplo, ha venido a buscarme ahora, es, no sólo por un negocio, sino en la esperanza de que yo le diga a usted algo nuevo; ¿no es verdad? ¿No es verdad?--repitió con sonrisa equívoca Svidrigailoff--. Pues bien, figúrese usted que yo mismo, al volver a San Petersburgo, esperaba también que me diría usted algo nuevo y pensaba en tomar algo prestado. Vea usted cómo somos nosotros los ricos.\"},{\"heading\":false,\"text\":\"--¿Tomarme algo prestado? ¿El qué?\"},{\"heading\":false,\"text\":\"--¿Acaso lo sé yo? Ya ve usted en qué miserable _traktir_ me paso todo el día--repuso Svidrigailoff--; no crea que me divierto; pero en alguna parte he de pasar el tiempo. Me distraigo con esa pobre Katia que acaba de salir... Si tuviese la suerte de ser un glotón, un gastrónomo de club... pero nada de eso; ahí tiene usted todo lo que yo puedo comer (señaló con el dedo una mesita colocada en el rincón, y en ella un plato de hierro galvanizado, que contenía los restos de un mal biftec con patatas). A propósito, ¿ha comido usted? En cuanto al vino sólo bebo _Champagne_, y un vaso me basta para toda la noche. Si he pedido esa botella hoy, es porque tengo que ir a cierta parte y he querido de antemano preparar un poco la cabeza. Hace poco me ocultaba como un colegial, porque temía que la visita de usted fuera un trastorno para mí; pero creo que puedo pasar una hora con usted. Ahora son las cuatro y media--añadió mirando al reloj--. ¿Querrá usted creer que hay momentos en que me disgusta no ser nada; ni fotógrafo, ni periodista...? Suele ser muy fastidioso no tener ninguna especialidad. Ciertamente, pensaba que me diría usted algo nuevo.\"},{\"heading\":false,\"text\":\"--¿Quién es usted y por qué ha venido aquí?\"},{\"heading\":false,\"text\":\"--¿Que quién soy? Lo sabe usted; un gentilhombre; he servido dos años en Caballería, después de lo cual me he paseado por San Petersburgo; más tarde me casé con Marfa Petrovna, y luego me fuí a vivir al campo. Ahí tiene mi biografía.\"},{\"heading\":false,\"text\":\"--Según parece, es usted jugador.\"},{\"heading\":false,\"text\":\"--¿Jugador yo? No diga usted eso; diga usted más bien que soy un tahur.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿usted hace trampas en el juego?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--Habrá recibido usted alguna vez bofetadas.\"},{\"heading\":false,\"text\":\"--Sí, alguna que otra. ¿Por qué me pregunta usted eso?\"},{\"heading\":false,\"text\":\"--Pues bien; podría usted batirse en duelo. Eso produce sensaciones.\"},{\"heading\":false,\"text\":\"--No tengo ninguna objeción que hacer a usted. Además, yo estoy poco fuerte en discusiones fisiológicas. Confieso que si he venido aquí, es sólo por las mujeres.\"},{\"heading\":false,\"text\":\"--¿En seguida de haber enterrado a Marfa Petrovna?\"},{\"heading\":false,\"text\":\"Svidrigailoff se sonrió.\"},{\"heading\":false,\"text\":\"--Pues bien, sí--respondió con una franqueza desconcertante--. Parece que le escandaliza lo que le digo.\"},{\"heading\":false,\"text\":\"--¿Se asombra usted de que me escandalice la disipación?\"},{\"heading\":false,\"text\":\"--¿Por qué no había de seguir mis inclinaciones? ¿Por qué he de renunciar a las mujeres, puesto que las amo? Eso es una ocupación.\"},{\"heading\":false,\"text\":\"Raskolnikoff se levantó. Sentíase a disgusto y se arrepentía de haber venido. Svidrigailoff le parecía el hombre más depravado del mundo.\"},{\"heading\":false,\"text\":\"--¡Eh! Quédese usted un momento; que le traigan te. Vamos, siéntese. Le contaré alguna cosa. ¿Quiere que le refiera cómo una mujer emprendió la tarea de convertirme? Esto será una respuesta a su primera pregunta, puesto que se trata de la hermana de usted. ¿Puedo contarlo? Mataremos el tiempo.\"},{\"heading\":false,\"text\":\"--Sea; mas espero que usted...\"},{\"heading\":false,\"text\":\"--No tenga usted miedo. Aun siendo un hombre tan vicioso, Advocia Romanovna no puede inspirarme más que profunda estimación. Creo haberla comprendido, y de ello me enorgullezco. Pero, ¿sabe usted que cuando no se conoce a las personas se corre el riesgo de engañarse? Pues eso es lo que me ha pasado con su hermana de usted. ¡Lléveme el diablo! ¿por qué es tan hermosa? Yo no tengo la culpa. En una palabra, esto empezó por un capricho de libertino. Es preciso decirle a usted que Marfa Petrovna me concedía cierta libertad con las campesinas. Acababa de venir a nuestra casa, procedente de una aldea vecina, una muchacha, como camarera, llamada Paratcha. Era muy linda, pero tonta de capirote: sus lágrimas y sus gritos, que alborotaban toda la casa, ocasionaron un escándalo. Cierto día, después de comer, Advocia Romanovna me llamó aparte, y mirándome con ojos relampagueantes, _exigió_ de mí que dejase en paz a la pobre Paratcha. Quizá fué la primera vez que hablamos a solas. Es claro, me apresuré a deferir a su demanda. Traté de parecer conmovido y turbado; en una palabra, representé mi papel a conciencia. A partir de este momento tuvimos conferencias secretas, en las cuales me predicaba moral, me suplicaba con las lágrimas en los ojos que cambiase de vida, ¡sí, con las lágrimas en los ojos! Vea usted hasta dónde llega en algunas jóvenes, la pasión por la propaganda. Por supuesto, yo imputaba todos mis errores al destino; me consideraba como un hombre privado de luz, y, finalmente, puse en práctica un medio que no falla jamás con las mujeres: la adulación. Espero que no se incomodará usted porque le diga que Advocia Romanovna no fué en un principio insensible a los elogios que yo la prodigaba. Por desgracia, eché a perder todo el negocio por mi impaciencia y por mi necedad. Al hablar con ella hubiera debido moderar el brillo de mis ojos. Su llama le inquietó, y acabó por parecerle odiosa. Sin entrar en detalles, bastará con que le diga a usted, que hubo entre nosotros un rompimiento. Después hice nuevas tonterías. Me extendí en groseros sarcasmos a propósito de las misioneras; Paratcha entró de nuevo en escena y fué seguida de otras muchas. ¡Oh, si hubiese usted visto entonces, Rodión Romanovitch, qué relámpagos lanzaban los ojos de su hermana! Le aseguro que hasta en sueños me perseguían sus miradas. Llegué a no poder soportar el ruido de sus ropas y temí un ataque de epilepsia. Era de todo punto preciso que me reconciliase con Advocia Romanovna, y la reconciliación era imposible. Imagínese usted lo que hice entonces. ¡A qué grado de estupidez puede llegar el hombre despechado! No emprenda usted nada en ese estado, Rodión Romanovitch. Pensando que Advocia Romanovna era una mendiga (perdón, no quería decir eso; pero la palabra importa poco), que, en fin, vivía de su trabajo y que tenía a su cargo a su madre y a usted (¡ah, caramba! ¡vuelve usted a fruncir el entrecejo!), me decidí a ofrecerle toda mi fortuna (podía reunir entonces 30.000 rublos), y a proponerla que huyese conmigo a San Petersburgo. Una vez aquí por supuesto, la habría jurado amor eterno, etc., etcétera. ¿Querrá usted creerlo? De tal modo estaba enamorado de ella en esta época, que si su hermana de usted me hubiese dicho: «Asesina o envenena a Marfa Petrovna, y cásate conmigo», lo hubiera hecho sin vacilar. Pero todo acabó por la catástrofe que usted ya conoce, y no se puede imaginar cómo me irritaría el saber que mi mujer había negociado el matrimonio entre Advocia Romanovna y ese embrollón de Ludjin; porque, bien mirado, tanto hubiera valido para su hermana de usted aceptar mis ofrecimientos, como dar su mano a un hombre como ése. ¿No es verdad? ¿No es verdad? Advierto que me escucha usted con mucha atención... interesante joven...\"},{\"heading\":false,\"text\":\"Svidrigailoff dió un violento puñetazo sobre la mesa. Estaba sofocado, y aunque apenas había bebido dos vasos de _Champagne_, empezaba a dar señales de embriaguez. Raskolnikoff lo advirtió y resolvió aprovecharse de esta circunstancia para descubrir las intenciones de aquel a quien consideraba como su más peligroso enemigo.\"},{\"heading\":false,\"text\":\"--Pues bien, después de esto, no tengo la menor duda de que usted ha venido aquí por mi hermana--declaró el joven con tanto más atrevimiento, cuanto que quería llevar a su interlocutor a los últimos extremos.\"},{\"heading\":false,\"text\":\"Svidrigailoff trató de borrar el efecto producido por sus palabras.\"},{\"heading\":false,\"text\":\"--¡Eh, deje usted! ¿No le he dicho... que su hermana no puede sufrirme?\"},{\"heading\":false,\"text\":\"--Estoy persuadido; pero no se trata de eso.\"},{\"heading\":false,\"text\":\"--¿Está usted persuadido de que ella no puede sufrirme?--replicó Svidrigailoff guiñando los ojos y sonriéndose con aire burlón--. Dice usted bien, no me ama. Pero no responda usted jamás de lo que pasa entre un marido y su mujer o entre dos amantes. Hay siempre un rinconcillo que queda oculto para todo el mundo y sólo es conocido de los interesados. ¿Se atrevería usted a afirmar que Advocia Romanovna me miraba con repugnancia?\"},{\"heading\":false,\"text\":\"--Ciertas palabras de su relato me prueban que todavía tiene usted infames propósitos acerca de Dunia y que se propone ejecutarlos lo más pronto posible.\"},{\"heading\":false,\"text\":\"--¿Cómo han podido escapárseme tales palabras?--dijo Svidrigailoff poniéndose de repente muy inquieto; pero sin molestarse en lo más mínimo por el epíteto con que se calificaban sus propósitos.\"},{\"heading\":false,\"text\":\"--Pero en este momento mismo se manifiestan los pensamientos ocultos de usted. ¿Por qué tiene miedo? ¿De qué nace ese súbito temor que demuestra?\"},{\"heading\":false,\"text\":\"--¿Yo, miedo? ¿Miedo de usted? ¡Vamos, hombre! Usted sí, amigo, que debe tener miedo... Por lo demás, estoy borracho, ya lo veo; un poco más, y hubiera cometido una tontería. ¡Váyase al diablo el vino! ¡mozo, agua!\"},{\"heading\":false,\"text\":\"Tomó la botella de _Champagne_, y sin andarse con miramientos la tiró por la ventana. Felipe trajo agua.\"},{\"heading\":false,\"text\":\"--Todo esto es absurdo--dijo Svidrigailoff humedeciendo una toalla y pasándosela por la cara--. Yo puedo, con una palabra, reducir a nada todas las sospechas de usted. ¿Sabe usted que voy a casarme?\"},{\"heading\":false,\"text\":\"--Ya me lo había dicho usted.\"},{\"heading\":false,\"text\":\"--¿Que se lo he dicho? pues me había olvidado; pero, de todas maneras, cuando le anuncié mi próximo matrimonio, podía hablar de él en forma dubitativa, pues aun no había nada de cierto. Ahora es cosa hecha, y si en este momento no tuviese que hacer, le conduciría a casa de mi futura. Me gustaría saber si usted aprueba mi decisión. ¡Ah, caramba, no cuento más que con diez minutos! Sin embargo, quiero contarle la historia de mi matrimonio; es bastante curiosa. Bueno... ¿Quiere usted irse aún?\"},{\"heading\":false,\"text\":\"--No, ahora no le dejo a usted.\"},{\"heading\":false,\"text\":\"--¿No? Pues adelante, ya lo veremos. Sin duda, yo le enseñaré a usted mi futura; pero no ahora, porque tenemos que separarnos muy pronto. Usted va por la izquierda y yo por la derecha. ¿Ha oído usted hablar de cierta señora Reslich, en cuya casa estoy actualmente de pupilo? Pues ella es quien cuida de todo. «Tú te aburres--me decía--, y esto será para ti una distracción momentánea.» Yo soy, en efecto, un hombre melancólico y huraño. ¿Usted cree que soy alegre? Desengáñese, yo tengo el humor sombrío, pero no hago mal a nadie. Algunas veces me paso tres días seguidos en un rincón, sin hablar una palabra; por otra parte, esa bribona de Reslich tiene su plan; cuenta con que me disgustaré pronto con mi mujer, que la echaré de mi lado y que ella la lanzará a la circulación. Sé, por ella, que el padre, antiguo funcionario, está enfermo. Desde hace tres años no puede valerse de las piernas y no deja la butaca. La madre es una señora muy inteligente; el hijo está empleado en provincias y no ayuda lo más mínimo a sus padres; la hija mayor está casada y no da señales de vida. Esta pobre gente tiene que mantener a dos sobrinas de corta edad. La hija menor ha sido retirada del colegio antes de haber acabado sus estudios; cumplirá diez y seis años antes de un mes, y ésta es la que me destinan... Provisto de estos datos, me presento a los padres como un propietario viudo, de buena familia, que está bien relacionado, y que además tiene buena fortuna. Mis cincuenta años no suscitan la más ligera objeción. Había que verme hablando con el papá y la mamá. ¡Fué aquello lo más divertido! Llega la muchacha, vestida con traje corto, y me saluda, poniéndose del color de la amapola (sin duda había aprendido la lección). No conozco el gusto de usted en punto a rostros femeninos, mas para mí, esos diez y seis años, esos ojos todavía infantiles, esa timidez, esas lagrimitas púdicas, todo ello tiene más encanto que la belleza; por otra parte, la muchacha es muy linda, con sus cabellos claros, sus ricitos caprichosos, sus labios purpurinos y ligeramente gruesos, unos senos nacientes... Hemos entablado conocimiento. Dije que asuntos de familia me obligaban a apresurar mi matrimonio, y al día siguiente, es decir, anteayer, éramos prometidos. Desde entonces, cuando voy a verla, la tengo sentada sobre mis rodillas durante todo el tiempo que dura mi visita y a cada minuto la beso. La chiquilla se pone como la grana, pero se deja querer. Su mamá le ha dado, sin duda, a entender que un futuro esposo puede permitirse estas libertades. De esta manera comprendidos los derechos de prometido, no son menos agradables que los de marido. Puede decirse que la naturaleza y la verdad hablan por boca de esta niña. He conversado dos veces con ella; la chiquilla no es tonta del todo; tiene una manera de mirarme disimuladamente, que incendia todo mi ser... Su fisonomía se parece mucho a la de la Virgen Sixtina. ¿Ha reparado usted en la expresión fantástica que Rafael supo dar a esa cabeza de Virgen? Pues algo semejante hay en el rostro de la joven. Desde el día siguiente de nuestros esponsales, la he llevado a mi futura regalos por valor de 1.500 rublos: diamantes, perlas, un neceser de _toilette_ de plata; la carita de la _madonna_ resplandecía. Ayer no me privé de sentarla sobre mis rodillas, y vi en sus ojos lágrimas que trataba de ocultar. Nos dejaron solos. Entonces me echó un brazo al cuello, y besándome, me juró que sería para mí una esposa buena, obediente y fiel; que me haría feliz, que me consagraría todos los instantes de su vida y que, en cambio, no quería de mí más que mi cariño, nada más: «No tengo necesidad de regalos», me ha dicho. Oír a un ángel de diez y seis años, con las mejillas coloreadas de un pudor virginal, que le hace a usted esta declaración con lágrimas de entusiasmo en los ojos... Esto es delicioso. ¡Ah, sí! le llevaré a casa de mi prometida; pero no puedo enseñársela a usted en seguida.\"},{\"heading\":false,\"text\":\"--¿De modo que esa monstruosa diferencia de edad aguijonea la sensibilidad de usted? ¿Es posible que piense seriamente en contraer semejante matrimonio?\"},{\"heading\":false,\"text\":\"--¡Qué austero moralista!--dijo burlándose Svidrigailoff--. ¡Dónde va a anidar la virtud! ¡Ja, ja, ja! ¿Sabe usted que me hacen mucha gracia sus exclamaciones de indignación?\"},{\"heading\":false,\"text\":\"Llamó a Felipe, pagó lo que había tomado y se levantó.\"},{\"heading\":false,\"text\":\"--Siento mucho--continuó--no poder detenerme más tiempo con usted; pero ya volveremos a vernos... Tenga usted un poco de paciencia.\"},{\"heading\":false,\"text\":\"Salió del _traktir_. Raskolnikoff le siguió. La embriaguez de Svidrigailoff se disipaba a ojos vistas. Fruncía el ceño y parecía muy preocupado, como hombre que está en vísperas de emprender una cosa muy importante. Desde hacía algunos instantes se revelaba en sus movimientos cierta impaciencia, mientras que su lenguaje se hacía cáustico y agresivo. Todo ello parecía justificar una vez más las aprensiones de Raskolnikoff, el cual resolvió seguir los pasos del extraño personaje.\"},{\"heading\":false,\"text\":\"Cuando estuvieron en la calle, Svidrigailoff dijo:\"},{\"heading\":false,\"text\":\"--Aquí nos separamos. Usted se va por la derecha y yo por la izquierda, o al contrario. Adiós, amigo mío, hasta la vista.\"},{\"heading\":false,\"text\":\"Y se dirigió hacia el Mercado del Heno.\"}]},{\"title\":\"sexta parte — capítulo IV\",\"blocks\":[{\"heading\":false,\"text\":\"Raskolnikoff se puso a seguirle.\"},{\"heading\":false,\"text\":\"--¿Qué significa esto?--preguntó, volviéndose, Svidrigailoff--. Creo haberle dicho a usted...\"},{\"heading\":false,\"text\":\"--Esto significa que estoy decidido a acompañarle.\"},{\"heading\":false,\"text\":\"--¿Qué?\"},{\"heading\":false,\"text\":\"Los dos se detuvieron, y durante un minuto se midieron con la vista.\"},{\"heading\":false,\"text\":\"--En la semiembriaguez de usted--replicó Raskolnikoff--me ha dicho lo bastante para convencerme de que, lejos de haber renunciado a sus odiosos proyectos contra mi hermana, le interesan más que nunca. Sé que esta mañana mi hermana ha recibido una carta. ¡No ha perdido usted el tiempo desde su llegada a San Petersburgo! Que en el curso de las idas y venidas de usted se haya encontrado una mujer, es cosa posible, pero esto nada significa, y deseo convencerme por mí mismo...\"},{\"heading\":false,\"text\":\"Probablemente Raskolnikoff no hubiera sabido decir de qué cosa quería convencerse.\"},{\"heading\":false,\"text\":\"--¿Por lo visto, usted quiere que yo llame a la policía?\"},{\"heading\":false,\"text\":\"--Llámela usted.\"},{\"heading\":false,\"text\":\"Se detuvieron de nuevo uno frente al otro. Al fin, el rostro de Svidrigailoff cambió de expresión. Viendo que su amenaza no intimidaba en lo más mínimo a Raskolnikoff, tomó de repente un tono más alegre y amistoso.\"},{\"heading\":false,\"text\":\"--¡Qué original es usted! A pesar de la curiosidad bien natural que ha despertado en mí, no he querido hablarle de su asunto. Quería dejarlo para ocasión más oportuna; pero, en verdad, es usted capaz de hacer perder la paciencia a un muerto... Bueno, venga usted conmigo; pero le advierto que sólo entro para tomar algún dinero; en seguida saldré, montaré en un coche y me iré a pasar el resto del día a las Islas... ¿Qué necesidad tiene usted de seguirme?\"},{\"heading\":false,\"text\":\"--Tengo que hacer en casa de usted; pero no es a su cuarto adonde voy, sino al de Sofía Semenovna; tengo que disculparme de no haber asistido a las exequias de su madrastra.\"},{\"heading\":false,\"text\":\"--Como usted quiera; pero Sofía Semenovna no está en casa. Ha ido a llevar a los tres niños a la casa de una señora anciana a quien yo conozco hace mucho tiempo y que se halla al frente de muchos asilos. He proporcionado un gran placer a esa señora remitiéndole el dinero para los chiquillos de Catalina Ivanovna, además de un donativo pecuniario para sus establecimientos; le he contado, por último, la historia de Sofía Semenovna, sin omitir ningún detalle. Mi relato ha producido un efecto indescriptible, y ahí tiene usted por qué ha sido invitada Sofía a dirigirse hoy mismo al hotel X***, en el cual la _barinia_ en cuestión reside provisionalmente desde su regreso del campo.\"},{\"heading\":false,\"text\":\"--No importa, de todos modos entraré en su casa.\"},{\"heading\":false,\"text\":\"--Haga usted lo que le plazca, pero yo no he de acompañarle. ¿Para qué? Estoy seguro de que desconfía de mí, porque he tenido hasta este momento la discreción de evitarle preguntas escabrosas. ¿Adivina usted a lo que quiero aludir? Apostaría cualquier cosa a que mi discreción le ha parecido extraordinaria. ¡Sea usted delicado para que se le recompense de ese modo!...\"},{\"heading\":false,\"text\":\"--¿Le parece a usted delicado escuchar detrás de las puertas?\"},{\"heading\":false,\"text\":\"--¡Ja, ja, ja! Ya me sorprendía que no hubiese usted hecho esta observación--respondió riendo Svidrigailoff--. Si cree usted que no está permitido escuchar detrás de las puertas, pero sí asesinar a mujeres indefensas, puede acontecer que los magistrados no sean de ese parecer, y haría usted bien en marcharse cuanto antes a América. Parta usted en seguida, joven. Quizá sea todavía tiempo. Le hablo con toda sinceridad. Si necesita usted dinero para el viaje yo se lo daré.\"},{\"heading\":false,\"text\":\"--No pienso en tal cosa--replicó desdeñosamente Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Lo comprendo. Usted se pregunta si ha obrado con arreglo a la moral, como un buen hombre y como un buen ciudadano. Debiera haberse planteado esa cuestión antes, ahora ya es demasiado tarde. ¡Ja, ja! si usted cree haber cometido un crimen, levántese la tapa de los sesos, ¿no es eso lo que tiene el propósito de hacer?\"},{\"heading\":false,\"text\":\"--Por lo visto trata usted de exasperarme con la esperanza de que así le libraré de mi presencia.\"},{\"heading\":false,\"text\":\"--¡Qué original es usted! Pero hemos llegado; tómese el trabajo de subir la escalera. Ahí tiene usted la puerta del cuarto de Sofía Semenovna. ¿Ve usted? No hay nadie. ¿No lo cree usted? Pregúnteselo a los Kapernumoff, ellos tienen la llave. Aquí está precisamente la señora Kapernumoff. ¡Eh! (es un poco sorda). ¿Sofía Semenovna ha salido? ¿A dónde ha ido? ¿Está usted en lo que digo? «No está aquí, y acaso no vendrá hasta muy tarde.» Vamos, ahora venga usted a mi casa. ¿No tenía usted intención de hacerme una visita? Henos aquí en mi cuarto. La señora Reslich está ausente. Esta mujer tiene siempre mil negocios entre manos; pero es una excelente persona, se lo aseguro; quizá le sería útil si fuese usted más razonable. ¿Ve usted? Tomo de mi cómoda un título del 5 por 100 (mire usted cuántos me quedan todavía); voy a convertirlo en metálico. ¿Se ha enterado usted? Nada tengo que hacer aquí; cierro la cómoda, cierro el cuarto y hétenos en la escalera. Si a usted le parece, tomaremos un coche y nos iremos a las Islas. ¿No le gusta a usted un paseíto en carruaje? ¿Lo ve usted? Ordeno al cochero que me conduzca a la punta de Elaguin. ¿Rehusa usted? Se ha cansado usted de acompañarme; vamos, déjese usted tentar. Va a llover; pero, ¿qué importa? Levantaremos la capota.\"},{\"heading\":false,\"text\":\"Svidrigailoff estaba ya en el coche; por muy desconfiado que fuese Raskolnikoff, pensó que no había peligro inminente; así es que sin responder una palabra, volvió la espalda y tomó la dirección del Mercado del Heno. Si hubiese vuelto la cabeza, habría podido ver que Svidrigailoff, después de haber andado cien pasos en coche, se apeaba y pagaba al cochero. Pero el joven caminaba sin mirar hacia atrás. Muy pronto dobló Raskolnikoff la esquina, y, como siempre, cuando se encontraba solo no tardó en caer en profunda abstracción. Llegado al puente se detuvo en la balaustrada y fijó los ojos en el canal. En pie, a poca distancia de él, le observaba Advocia Romanovna. Al llegar al puente pasó cerca de ella, pero sin verla. A la vista de su hermano, Dunia experimentó un sentimiento de sorpresa y aun de inquietud; durante un momento dudó si se acercaría o no. De pronto echó de ver que, por la parte del Mercado del Heno, Svidrigailoff se dirigía rápidamente hacia ella.\"},{\"heading\":false,\"text\":\"Este parecía avanzar con prudencia y misterio. No subió al puente, se quedó en la acera, procurando no ser visto por Raskolnikoff. Hacía un rato que había reparado en Dunia y que le hacía señas. La joven creyó comprender que la llamaba, indicándole que procurase que su hermano no le viera. Dócil a esta invitación muda, Dunia se alejó, sin hacer ruido, de Raskolnikoff, y se juntó con Svidrigailoff.\"},{\"heading\":false,\"text\":\"--Vamos más de prisa--le dijo por lo bajo este último--. Es preciso que Rodión Romanovitch ignore nuestra entrevista. Advierto a usted que ha venido a buscarme, hace poco, a un café que está cerca de aquí, y que me ha costado trabajo separarme de él. Sabe que he escrito a usted una carta y sospecha algo. Indudablemente no es usted quien le ha hablado de esto; pero si no es usted, ¿quién ha sido, entonces?\"},{\"heading\":false,\"text\":\"--Ya hemos dado vuelta a la esquina--interrumpió Dunia--. Ahora mi hermano no puede vernos. Advierto a usted que no pasaré de aquí en su compañía. Dígame lo que quiera, que todo puede decirse en medio de la calle.\"},{\"heading\":false,\"text\":\"--En primer lugar, no es en la vía publica donde pueden ni deben hacerse ciertas confidencias. Además, usted debe oír también a Sofía Semenovna, y en tercer lugar, es preciso que yo le muestre ciertas pruebas. En fin, si usted no consiente en venir a mi casa, renuncio a toda explicación y me retiro ahora mismo. No olvide usted tampoco que poseo cierto secreto muy curioso que interesa a su querido hermano.\"},{\"heading\":false,\"text\":\"Dunia se detuvo indecisa y dirigió una mirada penetrante a Svidrigailoff.\"},{\"heading\":false,\"text\":\"--¿Qué teme usted?--observó tranquilamente éste--. La ciudad no es el campo, y aun en el campo mismo me ha hecho usted más daño que yo a usted.\"},{\"heading\":false,\"text\":\"--¿Sofía Semenovna está avisada?\"},{\"heading\":false,\"text\":\"--No, no le he dicho una palabra; ni siquiera sé si está en su casa. Creo, sin embargo, que debe de estar, porque hoy se ha verificado el entierro de su madrastra, y no es de suponer que en un día como éste haga visitas. Por el momento no quiero hablar de eso a nadie, y hasta siento, en cierto modo, haberme clareado con usted. En tales casos, la menor palabra pronunciada a la ligera equivale a una denuncia. Yo vivo cerca, en esta casa; he aquí nuestro portero; me conoce muy bien. ¿Ve usted? me saluda. Ve que vengo con una señora; sin duda se ha fijado ya en la fisonomía de usted. Esta circunstancia debe tranquilizarla si desconfía de mí. Perdóneme si le hablo tan crudamente. Vivo aquí, en un cuarto amueblado; no hay más que un tabique entre el cuarto de Semenovna y el mío, y todo el piso está habitado por diferentes vecinos. ¿Por qué, pues, tiene usted tanto miedo como un niño? ¿Qué tengo yo de terrible?\"},{\"heading\":false,\"text\":\"Svidrigailoff trató de sonreírse bondadosamente, pero no lo consiguió. Latíale el corazón con fuerza y tenía oprimido el pecho. Afectaba levantar la voz para ocultar la agitación que experimentaba. Precaución inútil, porque Dunia no advertía en él nada de particular; las últimas palabras de su interlocutor habían irritado demasiado a la orgullosa joven para que pensase en otra cosa que en la herida de su amor propio.\"},{\"heading\":false,\"text\":\"--Aunque sé que es usted un hombre sin honor, no le temo. Condúzcame usted--dijo con tono tranquilo que desmentía, es verdad, la extrema palidez de su semblante.\"},{\"heading\":false,\"text\":\"Svidrigailoff se detuvo delante del cuarto de Sonia.\"},{\"heading\":false,\"text\":\"--Permítame usted que vea si está en la habitación. No, no está; es una contrariedad; pero sé que vendrá dentro de poco. No ha podido salir más que para ver a una señora que se interesa por los huérfanos; yo también me he ocupado en ese asunto. Si Sofía Semenovna no ha vuelto dentro de diez minutos y usted tiene necesidad de hablarle, la enviaré a casa de usted hoy mismo. Este es mi alojamiento; se compone de estas dos habitaciones. Detrás de esa puerta habita mi patrona, la señora Reslich. Ahora fíjese usted, voy a mostrarle mis principales pruebas. Mi alcoba tiene esta puerta que conduce a un alojamiento de dos piezas, el cual está enteramente vacío. Entérese usted; es preciso que tenga un conocimiento exacto de todos los lugares.\"},{\"heading\":false,\"text\":\"Svidrigailoff ocupaba dos habitaciones bastante grandes. Dunia miraba en derredor de sí con desconfianza; pero no descubría nada sospechoso ni en los muebles ni en la disposición del local. No obstante, pudo advertir que Svidrigailoff habitaba entre dos departamentos en cierto modo inhabitados. Para llegar hasta el suyo había que atravesar dos aposentos, puede decirse que vacíos, que formaban parte de la habitación de su propietaria. Abriendo la puerta que ponía en comunicación su alcoba con el departamento no alquilado, Svidrigailoff mostró este último a Dunia. La joven se detuvo en el umbral, sin comprender por qué se le invitaba a mirar; pero en seguida le dió Svidrigailoff la explicación.\"},{\"heading\":false,\"text\":\"--¿Ve usted esa habitación grande, la segunda? fíjese usted en esa puerta cerrada con llave. A su lado hay una silla, la única que se encuentra en las dos habitaciones. Yo la llevé de mi cuarto para escuchar más cómodamente. La mesa de Sofía Semenovna está colocada precisamente detrás de esta puerta. La joven estaba sentada ahí y hablaba con Rodión Romanovitch, mientras que aquí, en una silla, escuchaba yo su conversación. He estado sentado en este sitio dos tardes seguidas, y cada vez dos horas, y así he podido enterarme de alguna cosa. ¿Qué le parece a usted?\"},{\"heading\":false,\"text\":\"--Que ha sido un espía.\"},{\"heading\":false,\"text\":\"--Sí. Ahora entraremos en mi cuarto. Aquí no puede uno ni sentarse.\"},{\"heading\":false,\"text\":\"Condujo a Dunia a la habitación que le servía de sala, y le ofreció un asiento cerca de la mesa. El se sentó a distancia respetuosa; pero le brillaban los ojos con el mismo fuego que en otro tiempo había asustado tanto a la joven. Esta estaba temblando, a pesar de la tranquilidad que procuraba demostrar, y dirigió en torno suyo otra mirada de desconfianza. La situación aislada del alojamiento de Svidrigailoff, acabó por atraer su atención. Quiso preguntar si, por lo menos, estaba en casa la patrona; pero su orgullo no le permitió hacer esta pregunta. Por otra parte, la inquietud relativa a su seguridad personal, no era nada en comparación de la otra ansiedad que torturaba su corazón.\"},{\"heading\":false,\"text\":\"--Aquí tiene usted su carta--comenzó a decir, depositándola encima de la mesa--. Lo que usted me ha escrito, ¿es posible? Usted me da a entender que mi hermano ha cometido un crimen; las insinuaciones de usted son bien claras; no trate ahora de recurrir a subterfugios. Sepa usted que antes de sus pretendidas revelaciones he oído hablar de este cuento absurdo, del cual no creo una palabra; eso es aún más ridículo que odioso. Conozco estas sospechas e ignoro la causa que las ha hecho nacer. Usted no puede tener pruebas. Sin embargo, ha prometido darlas; hable, pues; pero le advierto que no le creo.\"},{\"heading\":false,\"text\":\"Dunia pronunció estas palabras con extrema rapidez, y por un instante la emoción que experimentaba coloreó de rojo sus mejillas.\"},{\"heading\":false,\"text\":\"--Si usted no me creyese, ¿hubiese podido resolverse a venir sola a mi casa? ¿Por qué, pues, ha venido? ¿Por pura curiosidad?\"},{\"heading\":false,\"text\":\"--No me atormente más y hable, hable usted.\"},{\"heading\":false,\"text\":\"--Hay que convenir que es usted una joven valiente. Creía verdaderamente que había usted suplicado al señor Razumikin que la acompañase; pero he podido convencerme de que no sólo no ha venido con usted, sino de que no la ha seguido a distancia. Es usted una mujer discreta y valerosa. Ha pensado en Rodión Romanovitch y... Por lo demás, en usted todo es divino. En lo que concierne a su hermano, ¿qué he de decirle a usted si acaba de verle? ¿Cómo le encuentra?\"},{\"heading\":false,\"text\":\"--¿Y es en eso solamente en lo que funda usted su acusación?\"},{\"heading\":false,\"text\":\"--No; no es en eso precisamente, sino en las propias palabras de Rodión Romanovitch. Ha venido dos días seguidos a hablar con Sofía Semenovna. Ya he indicado a usted dónde estuvieron sentados. Lo confesó todo a la joven: es un asesino. Mató a una vieja usurera, en cuya casa había empeñado algunos objetos. Pocos momentos después del asesinato, la hermana de la víctima, una vendedora de ropa blanca llamada Isabel, entró por casualidad y también la mató. Se sirvió para asesinar a las dos mujeres, de un hacha que llevaba a prevención. Su propósito era robar y robó; tomó dinero y diversos objetos; eso es lo que, palabra por palabra, ha contado a Sofía Semenovna. Ella sola conoce el secreto; pero no es cómplice del asesinato; todo al contrario, al oírlo referir se quedó tan espantada como lo está usted ahora. Puede usted tranquilizarse; no será ella la que denuncie a su hermano de usted.\"},{\"heading\":false,\"text\":\"--¡Eso es imposible!--balbuceó Dunia, jadeante--; no tenía la menor razón ni el más pequeño motivo para cometer ese crimen... Eso es una mentira.\"},{\"heading\":false,\"text\":\"--El robo explica el móvil del asesinato. Su hermano de usted tomó dinero y joyas. Es verdad que, según su propia confesión, ni del uno ni de las otras ha sacado el menor provecho, y que hubo de ocultarlo todo bajo una piedra, en donde está todavía; pero esto es porque no se ha atrevido a utilizarlo.\"},{\"heading\":false,\"text\":\"--¿Es verosímil que haya robado? ¿Ha podido tener siquiera este pensamiento?--exclamó Dunia levantándose vivamente--. ¿Usted lo conoce? ¿Le cree usted capaz de ser ladrón?\"},{\"heading\":false,\"text\":\"--Esa categoría, Advocia Romanovna, comprende infinito número de variedades. En general, los rateros tienen conciencia de su infamia; he oído hablar, sin embargo, de un hombre muy noble que desvalijó un correo. ¿Quién sabe si su hermano de usted pensaba cumplir una acción laudable? También yo, como usted, no hubiera creído esa historia si la hubiese sabido por un medio indirecto, pero forzoso me es dar crédito al testimonio de mis oídos... ¿A dónde va usted, Advocia Romanovna?\"},{\"heading\":false,\"text\":\"--Voy a ver a Sofía Semenovna--respondió con voz débil la joven--. ¿Dónde está la entrada de su cuarto? Puede que ya haya vuelto; quiero verla en seguida. Es menester que ella...\"},{\"heading\":false,\"text\":\"Advocia Romanovna no pudo acabar, se ahogaba materialmente.\"},{\"heading\":false,\"text\":\"--Según todas las apariencias, Sofía Semenovna no estará de vuelta hasta la noche. Su ausencia debía ser muy corta; pero, puesto que no ha vuelto aún, no regresará hasta muy tarde.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿De ese modo mientes? Ya lo veo, has mentido... no dices más que mentiras... no te creo... no te creo--exclamó Dunia en un arranque de cólera que la ponía fuera de sí.\"},{\"heading\":false,\"text\":\"Casi desfallecida, se dejó caer sobre una silla que Svidrigailoff se apresuró a acercarle.\"},{\"heading\":false,\"text\":\"--¿Qué tiene usted, Advocia Romanovna? Tranquilícese; aquí hay agua; beba usted un poco.\"},{\"heading\":false,\"text\":\"Le echó agua en la cara; la joven tembló y volvió en sí.\"},{\"heading\":false,\"text\":\"«Esto ha producido efecto»--murmuraba Svidrigailoff para sí frunciendo el entrecejo--. Cálmese usted, Advocia Romanovna; sepa usted que Rodión Romanovitch tiene amigos; le salvaremos; le sacaremos de este mal paso. ¿Quiere usted que le lleve yo mismo al extranjero? Tengo dinero; de aquí a algunos días habré realizado todo mi haber. En cuanto al crimen, su hermano de usted hará una infinidad de buenas acciones que borrarán su delito. Quizá llegue a ser todavía un grande hombre. Vamos, ¿cómo está usted? ¿Cómo se siente?\"},{\"heading\":false,\"text\":\"--¡El miserable! ¡Todavía se burla! ¡Déjeme usted!\"},{\"heading\":false,\"text\":\"--¿A dónde quiere usted ir?\"},{\"heading\":false,\"text\":\"--A su lado. ¿En dónde está? ¡Usted lo sabe! ¿por qué está cerrada esa puerta? Por ella hemos entrado y ahora está cerrada con llave. ¿Cuándo la ha cerrado usted?\"},{\"heading\":false,\"text\":\"--No era necesario que toda la casa nos oyese. En el estado en que usted se encuentra, ¿para qué quería buscar a su hermano? ¿Quiere usted causar su perdición? La conducta de usted le pondrá furioso, y él mismo irá a denunciarse. Sepa usted también que se le vigila, y que la menor imprudencia por parte de usted le será funesta. Espere un poco. Le he visto, le he hablado hace un momento; todavía puede salvarse. Siéntese, vamos a examinar juntos lo que hay que hacer; para eso la he invitado a venir a mi casa; pero siéntese usted.\"},{\"heading\":false,\"text\":\"Dunia se sentó. Svidrigailoff tomó asiento cerca de ella.\"},{\"heading\":false,\"text\":\"--¿Cómo podría usted salvarle? ¿Acaso eso es posible?\"},{\"heading\":false,\"text\":\"--Todo depende de usted--comenzó a decir en voz baja.\"},{\"heading\":false,\"text\":\"Brillábanle los ojos, y su emoción era tal, que no podía hablar.\"},{\"heading\":false,\"text\":\"Dunia, aterrada, retiró un tanto su silla.\"},{\"heading\":false,\"text\":\"--Una sola palabra de usted y se salva--continuó él todo tembloroso--. Yo, yo le salvaré; tengo dinero y amigos. Le haré partir inmediatamente para el extranjero; le proporcionaré un pasaporte. Buscaré dos: uno para él y otro para mí. Tengo amigos con cuya fidelidad e inteligencia puedo contar... ¿Quiere usted? Tomaré un pasaporte para usted y para su madre... ¿Qué le importa a usted Razumikin?... Mi amor vale tanto como el suyo. La amo a usted con toda mi alma... déjeme besar el borde de su vestido... se lo ruego. El ruido que hace su falda me vuelve loco. Mande usted; ejecutaré todas sus órdenes, cualesquiera que sean; haré lo imposible; las creencias de usted serán las mías. ¡Oh, no me mire usted de ese modo, que me mata!\"},{\"heading\":false,\"text\":\"Comenzaba a delirar. Se hubiera dicho que tenía un ataque de enajenación mental. Dunia dió un salto hacia la puerta y empezó a sacudirla con todas sus fuerzas.\"},{\"heading\":false,\"text\":\"--¡Abrid, abrid!--gritó, creyendo que la oirían fuera--. ¡Abrid! ¿No hay nadie en esta casa?\"},{\"heading\":false,\"text\":\"Svidrigailoff se levantó; había recobrado ya en parte su sangre fría, y una sonrisa amarga erraba en sus labios temblorosos.\"},{\"heading\":false,\"text\":\"--No hay nadie aquí--dijo lentamente--. La patrona ha salido y usted se equivoca al gritar de ese modo; se toma usted un trabajo inútil.\"},{\"heading\":false,\"text\":\"--¿Dónde está la llave? ¡Abre la puerta en seguida, en seguida, infame!\"},{\"heading\":false,\"text\":\"--La he perdido y no puedo encontrarla.\"},{\"heading\":false,\"text\":\"--¿De modo que esto era un lazo?--gritó Dunia pálida como una muerta, y se lanzó a un rincón, en donde se parapetó tras de una mesita.\"},{\"heading\":false,\"text\":\"Después se calló; pero sin apartar los ojos de su enemigo, espiando hasta sus más pequeños movimientos. En pie, frente a ella, en el otro extremo de la habitación, Svidrigailoff no se movía de su sitio. Exteriormente, por lo menos, había logrado dominarse. No obstante, su rostro estaba pálido y continuaba sonriendo a la joven con aire burlón.\"},{\"heading\":false,\"text\":\"--Ha pronunciado usted la palabra lazo, Advocia Romanovna. En efecto, la he preparado a usted un lazo, y mis medidas están bien tomadas. Sofía Semenovna no está en su casa; nos separan cinco piezas del cuarto de los Kapernumoff. Además, soy, cuando menos, dos veces más fuerte que usted, e independientemente de esto nada tengo que temer, porque si usted se querella contra mí, su hermano está perdido. Por otra parte, nadie la creerá; todas las apariencias arguyen contra una joven que va sola a la caja de un hombre; y aunque usted se decidiese a sacrificar a su hermano, nada podría usted probar; son muy difíciles las pruebas de una violación, Advocia Romanovna.\"},{\"heading\":false,\"text\":\"--¡Miserable!--dijo la joven en voz baja pero vibrante de indignación.\"},{\"heading\":false,\"text\":\"--Sí, miserable; pero advierta usted que yo he razonado sencillamente desde el punto de vista de su hipótesis. Personalmente opino como usted, que la violación es un delito abominable; cuanto he dicho ha sido para tranquilizar la conciencia de usted en el caso en que consintiese, de buen grado, en salvar a su hermano como yo se lo he propuesto. Podrá usted decirse a sí misma que no ha cedido más que a las circunstancias, a la fuerza, si es preciso emplear esta palabra. Piense que la suerte de su madre y de su hermano está en sus manos. Seré esclavo de usted durante toda mi vida. Voy a esperar aquí.\"},{\"heading\":false,\"text\":\"Se sentó en el diván a ocho pasos de Dunia. La joven conocía muy bien a Svidrigailoff; no tenía la menor duda de que era inquebrantable su resolución.\"},{\"heading\":false,\"text\":\"De repente sacó del bolsillo un revólver, lo montó y lo colocó sobre la mesa, al alcance de su mano.\"},{\"heading\":false,\"text\":\"Svidrigailoff lanzó un gritó de sorpresa e hizo un brusco movimiento hacia adelante.\"},{\"heading\":false,\"text\":\"--¿Esas tenemos?--dijo con maligna sonrisa--. La situación cambia por completo; usted me simplifica singularmente la tarea; pero, ¿dónde se ha procurado usted ese revólver? ¿Se lo ha prestado a usted Razumikin? ¡Calle, si es el mío, lo reconozco! Lo había buscado en vano... Las lecciones de tiro que yo tuve el honor de darle en el campo, no habrán sido inútiles.\"},{\"heading\":false,\"text\":\"--Ese revólver no era tuyo, sino de Marfa Petrovna, a quien has matado tú. ¡Asesino! ¡Nada te pertenecía en su casa! Yo me apoderé de él cuando comencé a sospechar de lo que eras capaz. ¡Si das un solo paso, te juro que te mato!\"},{\"heading\":false,\"text\":\"Dunia, exasperada, se disponía a poner en práctica su amenaza, si llegaba el caso.\"},{\"heading\":false,\"text\":\"--Bueno, ¿y su hermano de usted? Le hago este pregunta por simple curiosidad--dijo Svidrigailoff, que continuaba en pie en el mismo sitio.\"},{\"heading\":false,\"text\":\"--Denúnciale si quieres. No te acerques, o disparo. Has envenenado a tu mujer, lo sé; tú también eres un asesino.\"},{\"heading\":false,\"text\":\"--¿Está usted bien segura de que yo he envenenado a Marfa Petrovna?\"},{\"heading\":false,\"text\":\"--Sí, tú mismo me lo diste a entender; tú me hablaste de veneno... Sé que te lo procuraste... tú, tú, ciertamente, fuiste, infame.\"},{\"heading\":false,\"text\":\"--Aun cuando eso fuese cierto, lo habría hecho por ti... tú habrías sido la causa.\"},{\"heading\":false,\"text\":\"--¡Mientes; yo te he detestado siempre, siempre!\"},{\"heading\":false,\"text\":\"--Parece que ha olvidado usted, Advocia Romanovna, que en su celo por convertirme se inclinaba hacia mí con lánguidas miradas... yo leía en los ojos de usted, ¿no se acuerda?, por la noche, al resplandor de la luna, mientras cantaba el ruiseñor.\"},{\"heading\":false,\"text\":\"--¡Mientes! (la rabia hacía brillar las pupilas de Dunia). ¡Mientes, calumniador!\"},{\"heading\":false,\"text\":\"--¿Que miento? Está bien. Miento; he mentido; las mujeres no gustan que se les recuerden ciertas cosillas--repuso sonriendo--. ¡Sé que tirarás, precioso monstruo; pues bien, anda!\"},{\"heading\":false,\"text\":\"Dunia le apuntó, no esperando más que un movimiento de él para hacer fuego; el rostro de la joven estaba cubierto de mortal palidez. Agitábasele el labio inferior, movido por la cólera, y llameábanle sus grandes y negros ojos. ¡Jamás la había visto tan hermosa Svidrigailoff! Este avanzó un paso, sonó una detonación, la bala le pasó rozando los cabellos, y fué a incrustarse en la pared, detrás de él. Svidrigailoff se detuvo.\"},{\"heading\":false,\"text\":\"--Una picadura de abeja--dijo riéndose--. Apunta a la cabeza... ¿Qué es esto? Tengo sangre.\"},{\"heading\":false,\"text\":\"Sacó un pañuelo del bolsillo para enjugarse la sangre que le corría a lo largo de la sien derecha. La bala le había rozado la piel del cráneo. Dunia bajó el arma y miró a Svidrigailoff con una especie de estupor. Parecía no darse cuenta de lo que acababa de hacer.\"},{\"heading\":false,\"text\":\"--Pues bien; ha errado usted el tiro. Dispare otra vez; espero--prosiguió Svidrigailoff, cuya alegría tenía algo de siniestro--; si tarda usted en disparar, tendré tiempo de agarrarla antes de que pueda usted defenderse.\"},{\"heading\":false,\"text\":\"Temblorosa Dunia, armó rápidamente el revólver y amenazó de nuevo a su perseguidor.\"},{\"heading\":false,\"text\":\"--¡Déjeme usted!--dijo con desesperación--; ¡le juro que voy a disparar otra vez! ¡Le mataré!\"},{\"heading\":false,\"text\":\"--A tres pasos, en efecto, es imposible que usted no haga blanco; pero si no me mata, entonces...\"},{\"heading\":false,\"text\":\"En los brillantes ojos de Svidrigailoff se podía leer el resto de su pensamiento. Dió dos pasos hacia adelante. Dunia disparó: pero falló el tiro.\"},{\"heading\":false,\"text\":\"--No está bien cargada el arma, no importa, eso puede repararse. Tiene ésta aún una cápsula; espero.\"},{\"heading\":false,\"text\":\"En pie, a dos pasos de la joven fijaba en ella una mirada ardiente, que expresaba indomable resolución. Dunia comprendió que aquel hombre moriría antes que renunciar a su designio.\"},{\"heading\":false,\"text\":\"Sin duda le mataría ahora que estaba solamente a dos pasos de ella.\"},{\"heading\":false,\"text\":\"De repente la joven tiró el revólver.\"},{\"heading\":false,\"text\":\"--¡No quiere usted tirar!--dijo Svidrigailoff asombrado, y respiró libremente.\"},{\"heading\":false,\"text\":\"No era quizá el temor de la muerte el peso más grave de que sentía aliviada su alma; sin embargo, no hubiera podido explicarse a sí mismo la naturaleza del alivio que experimentó.\"},{\"heading\":false,\"text\":\"Se acercó a Dunia y la tomó suavemente por el talle. No resistió la joven; pero, toda temblorosa, le miró con ojos suplicantes. Quiso hablar él; pero no pudo proferir ningún sonido.\"},{\"heading\":false,\"text\":\"--¡Suéltame!--suplicó Dunia.\"},{\"heading\":false,\"text\":\"Al oírse tutear con una voz que no era la de antes, Svidrigailoff se echó a temblar.\"},{\"heading\":false,\"text\":\"--¿De modo que no me amas?--preguntó en voz baja.\"},{\"heading\":false,\"text\":\"Dunia hizo con la cabeza un signo negativo.\"},{\"heading\":false,\"text\":\"--¿Y no podrás amarme... nunca...?--continuó él con acento desesperado.\"},{\"heading\":false,\"text\":\"--¡Nunca!--murmuró la joven.\"},{\"heading\":false,\"text\":\"Durante pocos instantes se libró una lucha terrible en el alma de Svidrigailoff. Tenía fijos los ojos en la joven con una expresión indecible. De repente apartó el brazo que había pasado en derredor del talle de Dunia, y alejándose rápidamente de ésta, fué a colocarse delante de la ventana.\"},{\"heading\":false,\"text\":\"--Ahí está la llave--dijo después de una pausa (la sacó del bolsillo izquierdo del gabán y la colocó detrás de él en la mesa sin volverse hacia Dunia)--. Tómela usted, y váyase pronto.\"},{\"heading\":false,\"text\":\"Seguía mirando obstinadamente por la ventana. Dunia se aproximó a la mesa para tomar la llave.\"},{\"heading\":false,\"text\":\"--¡Pronto, pronto!--repitió Svidrigailoff.\"},{\"heading\":false,\"text\":\"No había cambiado de posición, no la miraba; pero aquella palabra «pronto» había sido pronunciada de modo tal, que su significación no dejaba lugar a dudas.\"},{\"heading\":false,\"text\":\"Dunia tomó la llave, dió un salto hacia la puerta y salió rápidamente de la habitación; un instante después corría como loca a lo largo del canal, en la dirección del puente***.\"},{\"heading\":false,\"text\":\"Svidrigailoff permaneció todavía tres minutos cerca de la ventana. Al cabo se volvió con lentitud, dirigió una mirada en derredor suyo, y se pasó la mano por la frente. Sus facciones, desfiguradas por una extraña sonrisa, expresaban tremenda desesperación. Al advertir que tenía sangre en la mano, la miró con cólera, y luego mojó un paño y se lavó la herida. El revólver arrojado por Dunia había rodado hasta la puerta. Svidrigailoff lo levantó y se puso a examinarlo. Era un revólver pequeño de tres tiros, de antiguo sistema. Tenía aún dos cápsulas vacías y una cargada. Después de un momento de reflexión, guardó el arma en el bolsillo, tomó el sombrero y salió.\"}]},{\"title\":\"sexta parte — capítulo V\",\"blocks\":[{\"heading\":false,\"text\":\"Hasta las diez de la noche Arcadio Ivanovitch Svidrigailoff estuvo recorriendo tabernas y _traktirs_. Habiendo encontrado a Katia le pagó las consumaciones que quiso tomar, y lo mismo al organillero, a los mozos y a dos dependientes de comercio con los cuales tenía extraña simpatía. Había notado que estos dos jóvenes tenían la nariz ladeada, y que la de uno miraba a la derecha y la del otro a la izquierda. Finalmente se dejó llevar por ellos a un «jardín de recreo», donde pagó la entrada a todos. Este establecimiento, que ostentaba pomposamente el nombre de Waus-Hall, era un café cantante de ínfima clase. Los dependientes encontraron allí algunos «colegas» y empezaron a reñir con ellos; poco faltó para que vinieran a las manos. Svidrigailoff fué elegido como árbitro. Después de haber escuchado, durante un cuarto de hora, las recriminaciones confusas de los contendientes, creyó comprender que uno de ellos había robado una cosa, que había vendido a un judío, pero sin querer dar parte a sus camaradas del producto de aquella operación _comercial_. Por último, se averiguó que el objeto robado era una cucharilla de te perteneciente al Waus-Hall. La cuchara fué reconocida por los mozos del establecimiento, y la cosa hubiera acabado mal si Svidrigailoff no hubiera indemnizado a los que se quejaban. Se levantó y salió del jardín. Eran las diez. Durante toda la noche no había bebido ni una gota de vino. En el Waus-Hall se había limitado a pedir te, y eso porque allí estaba obligado a hacerse servir alguna cosa. La temperatura era sofocante, y negras nubes se amontonaban en el cielo. Próximamente a las diez estalló una violenta tempestad. Svidrigailoff llegó a su casa empapado hasta los huesos. Se encerró en su cuarto, abrió el cajón de su cómoda, sacó de él todo el dinero y desgarró dos o tres papeles. Después de haberse guardado el dinero pensó en mudarse de ropa; pero, como continuaba lloviendo, juzgó que no valía la pena; tomó el sombrero, salió sin cerrar la puerta de su habitación, y se dirigió al domicilio de Sonia.\"},{\"heading\":false,\"text\":\"La joven no estaba sola; tenía en derredor suyo los cuatro niños de Kapernumoff, a quienes servía el te. Sonia acogió respetuosamente al visitante, miró con sorpresa sus vestidos mojados, pero no dijo una palabra. A la vista de un extraño todos los chiquillos huyeron asustados.\"},{\"heading\":false,\"text\":\"Svidrigailoff se sentó cerca de la mesa e invitó a Sonia a que se sentase cerca de él. La joven se preparó tímidamente a escucharlo.\"},{\"heading\":false,\"text\":\"--Sofía Semenovna--empezó a decir--, quizá me vaya a América, y, como según todas las probabilidades, nos vemos por última vez, he venido a fin de arreglar algunos asuntos. ¿Ha ido usted esta tarde a casa de esa señora? Sé lo que le ha dicho usted; es inútil que me lo cuente (Sofía Semenovna hizo un movimiento de cabeza y se ruborizó). Esa gente tiene ciertos prejuicios. Por lo que hace a las hermanas de usted y a su hermano, su suerte está asegurada. El dinero que destinaba yo a cada uno de ellos, ha sido depositado por mí en manos seguras. Aquí tiene usted los recibos. Ahora, para usted, tome estos tres títulos del 5 por 100 que representan una suma de 3.000 rublos. Deseo que esto quede entre nosotros y que nadie sepa nada de ello. El dinero le es necesario, Sofía Semenovna, porque no puede usted continuar viviendo de este modo.\"},{\"heading\":false,\"text\":\"--Ha tenido usted tantas bondades con los huérfanos, con la difunta y conmigo--balbuceó Sonia--, que aunque apenas le haya dado a usted las gracias no crea usted que...\"},{\"heading\":false,\"text\":\"--Bueno, basta; basta...\"},{\"heading\":false,\"text\":\"--En cuanto a este dinero, Arcadio Ivanovitch, yo se lo agradezco mucho, pero no lo necesito ahora. No teniendo que pensar más que en mí, podré ir saliendo; no me considere usted ingrata porque rehuse su ofrecimiento. Puesto que es usted tan caritativo, este dinero...\"},{\"heading\":false,\"text\":\"--Tómelo usted, Sofía Semenovna, se lo suplico; no me haga usted objeciones; no tengo tiempo de oírlas. Raskolnikoff se encuentra entre dos alternativas: o pegarse un tiro o ir a Siberia.\"},{\"heading\":false,\"text\":\"Al oír estas palabras, Sonia se echó a temblar y miró aterrada a su interlocutor.\"},{\"heading\":false,\"text\":\"--No se inquiete usted--prosiguió Svidrigailoff--. Lo he oído todo de sus propios labios; no soy hablador y guardaré el terrible secreto. Ha estado usted inspirada aconsejándole que vaya a denunciarse. Es el mejor partido que puede tomar. Cuando vaya a Siberia, usted le acompañará, ¿no es eso? En tal caso, tendrá usted necesidad de dinero. Le hará a usted falta para él. ¿Comprende ahora? La cantidad que le ofrezco se la doy a él por mediación de usted. Además, usted ha prometido a Amalia Ivanovna pagar lo que se le debe. ¿Por qué asume usted siempre, tan ligeramente, semejantes compromisos? La deudora de esa alemana no era usted, sino Catalina Ivanovna; ha debido usted enviar al diablo a la alemana; es preciso más cálculo en la vida. Si mañana, o pasado mañana, le preguntase alguien por mí, no hable de mi visita, ni diga a nadie que le he dado dinero. Y, ahora, hasta la vista (se levantó). Salude usted de mi parte a Rodión Romanovitch. A propósito: hará usted muy bien, por de pronto, confiando el dinero al señor Razumikin. ¿Conoce usted al señor Razumikin? Es un buen muchacho. Lléveselo usted mañana o... cuando tenga usted ocasión. Pero, de aquí a entonces, tenga cuidado de que no se lo quiten.\"},{\"heading\":false,\"text\":\"Sonia se había levantado y fijaba una mirada inquieta en el visitante. Tenía grandes deseos de decir alguna cosa, de hacer alguna pregunta; pero estaba tan intimidada, que no sabía por dónde empezar.\"},{\"heading\":false,\"text\":\"--¿De modo... de modo... que va usted a ponerse en camino con un tiempo tan malo?\"},{\"heading\":false,\"text\":\"--Cuando se va a América no se preocupa uno de la lluvia. Adiós, mi querida Sofía Semenovna; viva usted, viva usted largo tiempo; sea usted útil a sus semejantes... dé usted mis recuerdos al señor Razumikin; dígale que Arcadio Ivanovitch Svidrigailoff le saluda. No se olvide usted.\"},{\"heading\":false,\"text\":\"Cuando hubo salido Svidrigailoff, Sonia quedóse oprimida por un sentimiento de temor.\"},{\"heading\":false,\"text\":\"La misma noche Svidrigailoff hizo una visita muy singular y muy inesperada. La lluvia seguía cayendo. A las once y veinte minutos se presentó, todo calado en casa de los padres de su futura, que ocupaban un cuartito en Wasili-Ostroff. Tuvo que llamar muchas veces antes de que le abriesen, y su llegada, a una hora tan intempestiva, causó en el primer momento gran sorpresa. Creyóse al principio que aquélla sería una humorada de hombre ebrio; pero en seguida hubieron de desechar esta suposición, porque, cuando se lo proponía, Svidrigailoff tenía modales por extremo seductores. La inteligente madre acercó la butaca del padre enfermo y entabló la conversación por medio de diferentes preguntas. Aquella mujer no iba nunca derecha al asunto; quería, por ejemplo, saber cuándo le agradaría celebrar a Arcadio Ivanovitch el matrimonio, y comenzaba interrogándole curiosamente acerca de París y sobre la _high-life_ parisiense, para conducirle poco a poco a Wasili-Ostroff.\"},{\"heading\":false,\"text\":\"Otras veces, esta maniobra resultaba bastante bien; pero en las circunstancias presentes, Svidrigailoff se mostró más impaciente que de costumbre, y quiso ver inmediatamente a su futura, a pesar de que se le dijo que estaba ya acostada. Claro es que se apresuraron a satisfacer su deseo. Svidrigailoff dijo a la joven que un negocio urgente le obligaba a ausentarse por algún tiempo de San Petersburgo, y que le traía 15.000 rublos, suplicándole que aceptare aquella bagatela, que desde largo tiempo antes había tenido intención de regalársela en vísperas del matrimonio. Apenas si había relación lógica entre este regalo y el anunciado viaje; no parecía que fuese necesaria para ello una visita nocturna mientras llovía torrencialmente. Sin embargo, por torpes que pudieran ser estas explicaciones, aquella familia se deshizo, por el contrario, en muestras de gratitud sumamente calurosas, a las cuales mezcló sus lágrimas la madre. Svidrigailoff se levantó, besó a su prometida, le dió suaves golpecitos en la mejilla, y aseguró que estaría muy pronto de vuelta. La muchacha le miraba perpleja; se leía en sus ojos algo más que una simple curiosidad infantil. Arcadio Ivanovitch notó aquella mirada, besó de nuevo a su futura, y se retiró, pensando con verdadero despecho que su regalo sería, de seguro, conservado bajo llave por la más inteligente de las madres.\"},{\"heading\":false,\"text\":\"A media noche volvió a entrar en la ciudad por el puente de***. Había cesado la lluvia; pero el viento soplaba con fuerza. Durante cerca de media hora, Svidrigailoff anduvo por la vasta perspectiva***, como si buscase alguna cosa. Poco tiempo antes reparó que al lado derecho de la perspectiva había un hotel que se llamaba, si la memoria no le era infiel, hotel Andrinópolis. Al fin lo encontró. Era un gran edificio de madera, en el cual, a pesar de lo avanzado de la noche, se veía luz. Entró y pidió habitación a un criado harapiento que encontró en el corredor. Después de echar una mirada sobre Svidrigailoff, el criado le condujo a un cuartito situado al extremo del corredor, debajo de la escalera; era el único disponible.\"},{\"heading\":false,\"text\":\"--¿Hay te?--preguntó Svidrigailoff.\"},{\"heading\":false,\"text\":\"--Puede hacerse.\"},{\"heading\":false,\"text\":\"--¿Qué hay además?\"},{\"heading\":false,\"text\":\"--Carne, aguardiente, entremeses.\"},{\"heading\":false,\"text\":\"--Tráeme carne y te.\"},{\"heading\":false,\"text\":\"--¿No quiere usted nada más?--preguntó con algo de vacilación el camarero.\"},{\"heading\":false,\"text\":\"--No.\"},{\"heading\":false,\"text\":\"El hombre harapiento se alejó muy contrariado.\"},{\"heading\":false,\"text\":\"«Esa casa debe ser alguna otra cosa que un hotel--pensó Svidrigailoff--; pero yo también debo tener el aspecto de un hombre que vuelve de un café cantante y que ha tenido una aventura en el camino. Sin embargo, me gustaría saber qué clase de gente viene aquí.»\"},{\"heading\":false,\"text\":\"Encendió la vela y empezó a examinar detenidamente la habitación. Era tan estrecha y baja, que un hombre de la estatura de Svidrigailoff podía apenas estar de pie. El mobiliario se componía de una cama muy sucia, de una mesa de madera barnizada y de una silla. La tapicería destrozada estaba tan polvorienta, que con dificultad se adivinaba su primitivo color. La escalera cortaba diagonalmente el techo, lo que daba a esta habitación el aspecto de una buhardilla. Svidrigailoff puso la bujía sobre la mesa, se sentó en la cama y se quedó pensativo; pero un incesante ruido que se oía en el cuarto inmediato, acabó por atraer su atención. Se levantó, tomó la vela, y fué a mirar por una hendidura del tabique.\"},{\"heading\":false,\"text\":\"En una habitación un poco mayor que la suya vió dos individuos, uno en pie y otro sentado en una silla. El primero estaba en mangas de camisa, era rojo, y tenía el cabello rizado. Reprendía a su compañero con voz plañidera:\"},{\"heading\":false,\"text\":\"--Tú no tenías posición, estabas en la última miseria, te he sacado del fango, y depende de mí el dejarte caer otra vez en él.\"},{\"heading\":false,\"text\":\"El amigo a quien se dirigían estas palabras tenía el aspecto de un hombre que quisiese estornudar y no pudiese; de vez en cuando fijaba una mirada estúpida en el orador; no comprendía una palabra de lo que se le decía; quizá tampoco la entendía el que hablaba. Sobre la mesa en que la bujía estaba a punto de consumirse, había un jarro de aguardiente casi vacío, vasos de diversos tamaños, pan, cohombros y servicio de te. Después de haber contemplado atentamente este cuadro, Svidrigailoff dejó su observatorio y volvió a sentarse en la cama.\"},{\"heading\":false,\"text\":\"Al traer el te y la carne, el mozo no pudo menos de preguntar de nuevo «si el señor quería otra cosa». Al oír una respuesta negativa, se retiró definitivamente. Svidrigailoff se apresuró a beber una taza de te para entonarse; pero le fué imposible comer. La fiebre, que comenzaba a invadirle, le había quitado el apetito. Despojóse del gabán y el saco, se envolvió en la colcha, y se acostó; estaba quebrantado.\"},{\"heading\":false,\"text\":\"«Mejor sería, por esta vez, estar bien»--se dijo sonriendo.\"},{\"heading\":false,\"text\":\"La atmósfera era sofocante. La vela alumbraba débilmente. El viento zumbaba fuera, se oía el ruido de un ratón y llenaba todo el cuarto olor de ratones y de cuero. Tendido en el lecho, Svidrigailoff soñaba más bien que pensaba. Sus ideas se sucedían confusamente, y hubiera querido fijar en algo su imaginación.\"},{\"heading\":false,\"text\":\"«Debe de haber un jardín bajo la ventana; se percibe rumor de hojas y de ramas de árboles. ¡Cuánto detesto este ruido por la noche en medio de la tempestad y de las tinieblas!»\"},{\"heading\":false,\"text\":\"Se acordó de que un momento antes, al pasar junto al parque Petrovsky, había experimentado la misma penosa impresión. En seguida pensó en el pequeño Neva, y se estremeció del mismo modo que antes, cuando, de pie sobre el puente, contemplaba el río.\"},{\"heading\":false,\"text\":\"«En mi vida me ha gustado el agua, ni aun en los paisajes»--pensó, y de repente una idea extraña le hizo sonreír.\"},{\"heading\":false,\"text\":\"«Me parece que ahora debería burlarme de la estética de las comodidades. Sin embargo, heme aquí tan vacilante como el animal que en parecido caso tiene cuidado de elegir su sitio. ¿Si yo hubiese ido hace poco a Petrovsky-Ostroff? La verdad es que he tenido miedo al frío y a la obscuridad... ¡Je, je! Necesito sensaciones agradables... Pero, ¿por qué no apagar la bujía? (la sopló). Mis vecinos están acostados»--añadió al no ver luz por la hendidura del tabique... Poco a poco se irguió ante su imaginación la figura de Dunia, y súbito temblor agitó sus nervios al recuerdo de la entrevista que pocas horas antes había tenido con la joven.\"},{\"heading\":false,\"text\":\"«No, no pensemos en esto. Cosa extraña, yo no he odiado jamás a nadie; jamás tampoco he experimentado vivos deseos de vengarme... esto es mal signo, mal signo. Jamás he sido tampoco ni pendenciero, ni violento; he aquí otro mal signo. ¡Pero qué promesas he hecho hace poco! ¡Quién sabe adónde habría llegado!»\"},{\"heading\":false,\"text\":\"Se calló y apretó los dientes. Su imaginación le mostró a Dunia tal como la había visto, cuando, después de haber dejado el revólver incapaz en adelante de resistencia, fijaba sobre él una mirada de espanto. Acordóse de la piedad que había sentido en aquel momento, y de lo oprimido que tenía el corazón.\"},{\"heading\":false,\"text\":\"«¡Vayan al diablo tales ideas!... ¡No pensemos más en tal cosa!»\"},{\"heading\":false,\"text\":\"Iba ya a adormecerse; su temblor febril había cesado. De pronto le pareció que por debajo de la colcha corría alguna cosa a lo largo del brazo y de la pierna. Se estremeció. «¡Caramba! ¡Es sin duda un ratón! He dejado la carne sobre la mesa.» Por temor al frío no quería destaparse ni levantarse; pero, de repente, un contacto desagradable le rozó el pie. Arrojó la colcha, encendió la vela, y temblando se incorporó en el lecho y no vió nada. Sacudió la colcha y saltó un ratón sobre la sábana. Trató en seguida de pillarlo, pero sin salir del lecho; el animalito describía zigzags rapidísimos y se deslizaba por entre los dedos que querían apresarlo. Finalmente, el ratón se metió debajo de la almohada. Svidrigailoff arrojó al suelo la almohada; pero en el mismo instante sintió que alguna cosa había saltado sobre él y que se le paseaba sobre el cuerpo debajo de la camisa. Un temblor nervioso se apoderó de él y se despabiló. La obscuridad era completa en la habitación; el seguía echado en la cama, envuelto en la colcha; el viento continuaba silbando en el exterior.\"},{\"heading\":false,\"text\":\"«Esto es insoportable»--se dijo con cólera.\"},{\"heading\":false,\"text\":\"Se sentó en el borde del lecho; con la espalda vuelta hacia la ventana.\"},{\"heading\":false,\"text\":\"«Más vale no dormir»--se dijo.\"},{\"heading\":false,\"text\":\"Por la reja entraba un aire húmedo y frío. Svidrigailoff, sin moverse de su sitio, atrajo hacia sí la colcha y se envolvió en ella. No encendió la luz; no pensaba ni quería pensar en nada; pero sueños e ideas incoherentes atravesaban confusos su cerebro. Estaba como sumido en semi-sueño. ¿Era aquello efecto del frío, de las tinieblas, o del viento que agitaba los árboles? Lo cierto es que estos desvaríos tomaban un aspecto fantástico. Le parecía estar viendo un riente paisaje. Era el día de la Trinidad, y hacía un tiempo soberbio... En medio de floridos arriates aparecía una elegante quinta de gusto inglés; plantas trepadoras tapizaban el vestíbulo; a los lados de la escalera, cubierta de una rica alfombra se erguían dos jarrones chinescos que contenían flores exóticas. En las ventanas había vasos medio llenos de agua en que hundían sus tallos ramilletes de jacintos blancos, que se inclinaban esparciendo un perfume embriagador. Aquellos ramilletes atraían particularmente la atención de Svidrigailoff, tanto, que no hubiera querido alejarse de ellos; sin embargo, subió la escalera y entró en una sala grande y alta; allí, como en las ventanas, como cerca de la puerta que daba a la terraza, y en a terraza misma, había flores; por todas partes flores. El pavimento estaba cubierto de hierbas recientemente segadas y que exhalaban suave olor; por las ventanas abiertas penetraba en la habitación una brisa deliciosa, y los pájaros gorjeaban en los alféizares; pero en medio de la sala, sobre una mesa cubierta con un mantel de raso blanco, estaba colocado un féretro. Le rodeaban guirnaldas de flores, y el interior estaba forrado de seda de Nápoles y de encajes blancos; en aquel ataúd reposaba, sobre un lecho de flores, una jovencita vestida de blanco. Tenía los ojos cerrados, y cruzados sobre el pecho los brazos, que parecían los de una estatua de mármol. Sus cabellos, de color rubio claro, estaban despeinados y húmedos; ceñíale la cabeza una corona de rosas. El perfil severo y ya rígido del rostro parecía también de mármol; pero la sonrisa de sus labios pálidos expresaba tan amarga tristeza, una desolación tan grande, que no parecía propia de su edad. Svidrigailoff conocía a aquella jovencita; cerca de su ataúd no había imágenes, ni cirios encendidos, ni oraciones. La difunta era una suicida; a los catorce años tenía el corazón herido por un ultraje que había destrozado su conciencia infantil, llenado su alma de una inmerecida vergüenza y arrancado de su pecho un grito supremo de desesperación, grito ahogado por los mugidos del viento en medio de una húmeda y fría noche de deshielo.\"},{\"heading\":false,\"text\":\"Svidrigailoff se levantó, dejó el lecho y se aproximó a la ventana. Después de haber buscado a tientas la falleba, abrió los cristales, exponiendo la cara y el cuerpo, apenas protegido por la camisa, al rigor del viento glacial que penetraba en la estrecha habitación. Bajo la ventana debía haber, en efecto, un jardín de recreo; allí, sin duda, durante el día, se cantaban canciones y se servía te en mesitas; pero ahora todo estaba sumido en las tinieblas, y los objetos se ofrecían como manchas negras y apenas distintas. Durante cinco minutos, Svidrigailoff, apoyado de codos en la ventana, trataba de horadar la obscuridad con la mirada. En el silencio de la noche retumbaron dos cañonazos.\"},{\"heading\":false,\"text\":\"«¡Ah! ¡es una señal! ¡El Neva sube!--pensó--. Esta madrugada los barrios bajos de la ciudad van a inundarse; las ratas se ahogarán en las cuevas; los inquilinos de los pisos bajos, chorreando de agua y renegando, tratarán, en medio de la lluvia y del viento, de salvar sus cachivaches, transportándolos a los pisos superiores... pero, ¿qué hora es?»\"},{\"heading\":false,\"text\":\"En el momento mismo que se hacía esta pregunta, un reloj vecino dió tres campanadas.\"},{\"heading\":false,\"text\":\"«Dentro de una hora será de día. ¿Para qué esperar? Voy a salir en seguida y a dirigirme a la isla Petrovsky.»\"},{\"heading\":false,\"text\":\"Cerró la ventana, encendió la vela y se vistió; luego, con el candelero en la mano, salió de la habitación para ir a despertar al mozo, pagar la cuenta y dejar en seguida la posada.\"},{\"heading\":false,\"text\":\"«Es éste el momento más favorable; no se puede esperar otro mejor.»\"},{\"heading\":false,\"text\":\"Anduvo mucho tiempo por el corredor largo y estrecho; y como no encontrara a nadie, se puso a llamar en alta voz. De repente, en un rincón sombrío, entre un armario viejo y una puerta, descubrió un objeto extraño, una cosa que parecía viviente. Inclinándose con la luz, reconoció que aquello era una niña de cinco años; temblaba y lloraba. Su ropita estaba empapada como una esponja. La presencia de Svidrigailoff no pareció asustarla; pero fijó en él los ojos con expresión de insensata sorpresa. Sollozaba a intervalos como suelen hacerlo los niños que, después de haber estado llorando largo rato, comienzan a consolarse. Su rostro era pálido y demacrado; estaba transida de frío; mas, «¿por qué casualidad se encontraba allí?» Sin duda se había ocultado en aquel rincón y no había dormido en toda la noche. Svidrigailoff se puso a interrogarla. Animándose de pronto la niña, comenzó, con voz infantil y tartajosa, un relato interminable, repitiendo a cada instante «mamá» «jícara rota». Creyó comprender Svidrigailoff que era aquélla una niña poco amada. Su madre, probablemente una cocinera del hotel, se entregaba, sin duda, a la bebida. La niña había roto una jícara, y temiendo el castigo había huído la noche del día anterior, en medio de la lluvia. Después de haber estado mucho tiempo fuera, habría acabado por entrar furtivamente, ocultándose detrás del armario, pasando allí toda la noche, temblorosa, llorando, asustada de hallarse en la obscuridad, y más asustada aún ante el temor de que sería cruelmente maltratada, tanto por la jícara rota, como por la escapatoria. Svidrigailoff la tomó en sus brazos, y habiéndola depositado en la cama se puso a desnudarla. La niña no llevaba medias y tenía agujereados los zapatos, tan húmedos como si hubiesen estado metidos toda la noche en un charco. Después la desnudó, la acostó y la envolvió con cuidado en la colcha. La pequeñuela se durmió en seguida, y después que todo hubo terminado, Svidrigailoff volvió a caer otra vez en sus pensamientos sombríos.\"},{\"heading\":false,\"text\":\"«¿Qué me importa a mí eso?--se dijo con un movimiento de cólera--.¡Qué tontería!»\"},{\"heading\":false,\"text\":\"En su irritación tomó la vela y buscó al mozo para dejar cuanto antes el hotel.\"},{\"heading\":false,\"text\":\"«¡Bah! ¡una granujilla!»--dijo, lanzando una blasfemia en el instante en que la puerta se abría; pero se volvió para echar una última mirada sobre la niña, a fin de asegurarse que dormía y cómo dormía. Levantó con precaución la colcha que ocultaba la cabeza. La chiquilla dormía con un sueño profundo; había entrado en calor y sus pálidas mejillas se habían coloreado. Sin embargo, cosa extraña: el encarnado de su tez era mucho más vivo que el que se advierte en el estado normal de los niños.\"},{\"heading\":false,\"text\":\"«Es el color de la fiebre--pensó Svidrigailoff--. Cualquiera diría que ha bebido.»\"},{\"heading\":false,\"text\":\"Sus labios purpurinos parecían arder de repente; el hombre creyó advertir que se movían algo las largas pestañas negras de la pequeña durmiente; bajo los párpados medio cerrados se adivinaban unas pupilas maliciosas, cínicas, en modo alguno infantiles.\"},{\"heading\":false,\"text\":\"«¿Estará despierta esta chiquilla y fingirá dormir?»\"},{\"heading\":false,\"text\":\"En efecto, sus labios sonreían, y temblaban como cuando se hacen esfuerzos para no reír, pero he aquí que cesa de contenerse y prorrumpe en una carcajada; algo desvergonzado, provocativo, aparece en aquel rostro que no tiene ya nada de infantil; es la cara de una prostituta, de una _cocotte_ francesa. Los ojos de la niña se abren; envuelven a Svidrigailoff en una mirada lasciva y apasionada; le llaman y ríen... Nada más repugnante que aquella cara de niña cuyas facciones respiraban lujuria.\"},{\"heading\":false,\"text\":\"«¡Cómo! ¿a los cinco años?--murmuraba, preso de un verdadero espanto--. ¿Es posible?»\"},{\"heading\":false,\"text\":\"Pero he aquí que vuelve hacia él la cara inflamada, le tiende los brazos.\"},{\"heading\":false,\"text\":\"«¡Ah, maldita!»--exclamó con horror Svidrigailoff.\"},{\"heading\":false,\"text\":\"Levanta la mano sobre ella, y en el mismo instante se despierta.\"},{\"heading\":false,\"text\":\"Se encontró acostado en la cama, envuelto en la manta; la vela no estaba encendida; amanecía.\"},{\"heading\":false,\"text\":\"«He tenido una pesadilla.»\"},{\"heading\":false,\"text\":\"Al incorporarse advirtió con cólera que estaba cansado y quebrantado. Eran cerca de las cinco; Svidrigailoff había dormido demasiado rato. Se levantó; se puso la ropa, húmeda todavía, y notando que tenía el revólver en el bolsillo, lo sacó para asegurarse de si las cápsulas estaban bien colocadas. Después se sentó, y en la primera página de su librito de notas escribió algunas líneas de gruesos caracteres. Después de haber releído lo escrito, se apoyó de codos en la mesa y se absorbió en sus reflexiones. Las moscas se regalaban con la porción de carne que había quedado intacta. Las miró durante largo tiempo y se puso después a darles caza. Al fin se asombró de aquella ocupación, y recobrando de repente la conciencia de sus actos, salió apresurado de la habitación: un instante después estaba en la calle.\"},{\"heading\":false,\"text\":\"Espesa niebla envolvía la ciudad. Svidrigailoff caminaba en dirección del pequeño Neva. Mientras andaba por el resbaladizo suelo de madera, veía con la imaginación la isla Petrovsky, con sus senderos, sus céspedes, sus árboles y sus bosquecillos... Ni un transeunte, ni un coche en toda la extensión de la perspectiva. Las casitas amarillas, con las ventanas cerradas, tenían triste y sucio aspecto. El frío y la humedad hacían estremecer al madrugador paseante que se distraía leyendo casi maquinalmente las muestras de las tiendas. Llegado al fin del piso de madera, a la altura de la gran casa de piedra, vió un perro muy feo que atravesaba el arroyo apretando la cola entre las piernas. Un hombre ebrio yacía tendido en la acera. Svidrigailoff miró un instante al borracho y siguió adelante. A la izquierda se ofreció a la vista una torre.\"},{\"heading\":false,\"text\":\"«¡Bah!--pensó--; he aquí un buen sitio; ¿para qué ir a la isla Petrovsky? Aquí, a lo menos, la cosa podrá ser confirmada por un testigo.»\"},{\"heading\":false,\"text\":\"Sonriendo ante esta idea, tomó por la calle***.\"},{\"heading\":false,\"text\":\"Allí se encontraba el edificio coronado por la torre. Vió apoyado en la puerta un hombrecillo envuelto en un capote de soldado y con un gorro turco, quien, al notar que se aproximaba Svidrigailoff, le echó de reojo una mirada huraña. Su fisonomía tenía esa expresión de arisca tristeza que es la marca secular de todos los israelitas. Los dos hombres se examinaron un momento en silencio. Al fin le pareció extraño al funcionario que un individuo que no estaba ebrio se detuviese así, a tres pasos de él, y le mirase sin decir una palabra.\"},{\"heading\":false,\"text\":\"--¿Qué quiere usted?--preguntó, siempre arrimado a la puerta.\"},{\"heading\":false,\"text\":\"--Nada, amigo mío; ¡buenos días!--respondió Svidrigailoff.\"},{\"heading\":false,\"text\":\"--Siga usted su camino.\"},{\"heading\":false,\"text\":\"--Voy al extranjero.\"},{\"heading\":false,\"text\":\"--¿Cómo al extranjero?\"},{\"heading\":false,\"text\":\"--A América.\"},{\"heading\":false,\"text\":\"--¿A América?\"},{\"heading\":false,\"text\":\"Svidrigailoff sacó el revólver y lo montó. El soldado arqueó las cejas.\"},{\"heading\":false,\"text\":\"--¡Oiga usted! Este no es sitio de andarse con bromas.\"},{\"heading\":false,\"text\":\"--¿Por qué no?\"},{\"heading\":false,\"text\":\"--Porque éste no es sitio.\"},{\"heading\":false,\"text\":\"--No importa, amigo mío; el lugar es a propósito. Si te preguntan, di que me he ido a América.\"},{\"heading\":false,\"text\":\"Apoyó el cañón del revólver sobre la sien derecha.\"},{\"heading\":false,\"text\":\"--¡Aquí no se puede hacer eso!--replicó el soldado abriendo desmesuradamente los ojos.\"},{\"heading\":false,\"text\":\"Svidrigailoff oprimió el gatillo.\"}]},{\"title\":\"sexta parte — capítulo VI\",\"blocks\":[{\"heading\":false,\"text\":\"Aquel mismo día, entre seis y siete de la tarde, Raskolnikoff se dirigió a casa de su madre y de su hermana. Las dos mujeres habitaban ahora en casa Bakalaieff, en el cuarto de que les había hablado Razumikin. Al subir la escalera, Raskolnikoff parecía vacilar aún. Sin embargo, por nada del mundo se hubiera vuelto atrás. Estaba resuelto a hacer aquella visita. «Todavía no saben nada--pensó--y están acostumbradas a ver en mí un ser original.»\"},{\"heading\":false,\"text\":\"Tenía el vestido manchado de lodo y desgarrado; de otra parte, la fatiga física, juntamente con la lucha que se libraba en él desde hacía veinticuatro horas, le había puesto la cara casi desconocida. El joven había pasado la noche en vela. Dios sabe dónde; pero, por lo menos, su partido estaba tomado.\"},{\"heading\":false,\"text\":\"Llamó a la puerta, y su madre salió a abrir. Dunia había salido, y la criada no estaba en aquel momento en la casa. Pulkeria Alexandrovna se quedó muda de sorpresa y de alegría; después, tomando a su hijo por la mano, le llevó a la sala.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿Estás aquí?--dijo con voz temblorosa a causa de la emoción--. No te incomodes, Rodia, porque te recibo llorando. Es la felicidad la que me hace verter lágrimas. ¿Crees que estoy triste? No; estoy alegre, ya lo ves, me río, sólo que tengo la tonta costumbre de llorar. Desde la muerte de tu padre, lloro por cualquier cosa. ¡Ah, qué sucio estás!\"},{\"heading\":false,\"text\":\"--¡Me cayó ayer tanta lluvia encima!--comenzó a decir Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Deja eso--interrumpió vivamente Pulkeria Alexandrovna--. ¿Piensas que iba a preguntarte con curiosidad de anciana? Puedes estar tranquilo; lo comprendo todo; pues ahora estoy algo iniciada en las costumbres de San Petersburgo y, verdaderamente, veo que aquí la gente tiene más inteligencia que en nuestras ciudades. Me he dicho, una vez para todas, que no debo mezclarme en tus negocios ni pedirte cuentas; mientras tienes tú quizás el espíritu preocupado sabe Dios en qué pensamientos, ¿habría de ir a distraerte con preguntas inoportunas?... ¡Ah, Dios mío!... ¿Ves, Rodia? Ahora estaba preparándome a leer, por tercera vez, el artículo que has publicado en una Revista. Demetrio Prokofitch me lo ha traído. Ha sido para mí una verdadera revelación; desde el primer momento lo he comprendido todo y he reconocido lo tonta que he sido. «He aquí lo que le preocupa, me he dicho; da vueltas en su cabeza a ideas nuevas y no gusta que se le aparte de sus reflexiones; todos los grandes talentos son así.» A pesar de la atención con que yo lo leo, hay en tu artículo, hijo mío, muchas cosas que no entiendo; pero, como soy ignorante, no me asombra el no comprenderlo todo.\"},{\"heading\":false,\"text\":\"--Enséñamelo, mamá.\"},{\"heading\":false,\"text\":\"Raskolnikoff tomó el número de la Revista, y echó una rápida ojeada sobre su artículo. Todo autor experimenta siempre un vivo placer al verse impreso por la primera vez, sobre todo cuando no tiene más que veintitrés años. Aunque presa de las más crueles angustias, nuestro héroe no pudo substraerse a esta impresión; pero sólo le duró un instante. Después de haber leído algunas líneas, frunció el entrecejo y sintió que le oprimía el corazón terrible sufrimiento. Esta lectura le trajo de repente a la memoria todas las agitaciones morales de los últimos meses; así es que arrojó con violenta repulsión el periódico sobre la mesa.\"},{\"heading\":false,\"text\":\"--Pero, por tonta que yo sea, Rodia--siguió la madre--, puedo, sin embargo, juzgar que de aquí a poco tiempo ocuparás uno de los primeros puestos, si no el primero, en el mundo de la ciencia. ¡Y se han atrevido a suponer que estabas loco! ¡Ah! ¿No sabes que se les había ocurrido esa idea? ¡Pobre gente! Por lo demás, ¿cómo podrían comprender qué es la inteligencia? ¡Pero decir, sin embargo, que Dunia, sí, la misma Dunia no estaba muy distante de creerlo! ¿Es esto posible? Hace seis o siete días, Rodia, me acongojaba ver cómo estabas instalado, vestido, alimentado; pero ahora reconozco que esto era una tontería mía; en cuanto tú quieras, con tu ingenio y tu talento, llegarás al colmo de la fortuna. Por ahora, sin duda, no tratas de eso, sino que te ocupas en cosas más importantes...\"},{\"heading\":false,\"text\":\"--¿Dunia no está aquí, mamá?\"},{\"heading\":false,\"text\":\"--No, hijo; sale con mucha frecuencia y me deja sola. Demetrio Prokofitch tiene la bondad de venir a verme y me habla siempre de ti. Te ama y te estima, hijo mío. En cuanto a tu hermana, no me quejo de las pocas consideraciones que me guarda; tiene su carácter, como yo tengo el mío. Le agrada que ignore sus cosas; allá ella. Yo, en cambio, no tengo nada oculto para mis hijos. Persuadida estoy de que Dunia es muy inteligente y de que, además, nos tiene mucho cariño a ti y a mí; pero no sé en qué irá a parar todo eso. Siento que no pueda aprovecharse de la visita que me haces. Cuando vuelva le diré: «Durante tu ausencia ha venido tu hermano; ¿dónde estabas tú en tanto?» Tú, Rodia, no me mimes demasiado; ven aquí como puedas, sin desatender tus negocios; no eres libre; no te molestes; tendré paciencia; me contentaré con saber que me quieres. Leeré tus obras; oiré hablar de ti en todas partes, y de vez en cuando recibiré tu visita; ¿qué más puedo desear? Ya veo que hoy has venido a consolar a tu madre.\"},{\"heading\":false,\"text\":\"Pulkeria Alexandrovna se echó a llorar bruscamente.\"},{\"heading\":false,\"text\":\"--¡Otra vez! ¡No me hagas caso; estoy loca! ¡Ah, Dios mío! ¡No pienso nada!--gritó levantándose de pronto--. Hay café, y no te he ofrecido una taza. ¿Ves qué grande es el egoísmo de los viejos? Voy en seguida...\"},{\"heading\":false,\"text\":\"--No vale la pena, mamá; voy a irme; no he venido para eso; escúchame, te lo suplico.\"},{\"heading\":false,\"text\":\"Pulkeria Alexandrovna se aproximó tímidamente a su hijo.\"},{\"heading\":false,\"text\":\"--Mamá, ocurra lo que ocurra, oigas lo que oigas de mí, ¿me amarás como ahora?--preguntó de repente.\"},{\"heading\":false,\"text\":\"Estas palabras brotaron espontáneas del fondo de su corazón, aun antes que hubiera tenido tiempo de medir su alcance.\"},{\"heading\":false,\"text\":\"--¡Rodia, Rodia! ¿qué tienes? ¿Cómo puedes hacerme esa pregunta? ¿Quién se atreverá jamás a hablarme mal de ti? Si alguien se permitiese semejante cosa, me negaría a oírle y le arrojaría de mi presencia.\"},{\"heading\":false,\"text\":\"--El objeto de mi visita era asegurarte que te he querido siempre, y ahora me alegro mucho de que estemos tú y yo solos, y aun de que no esté aquí Dunia--prosiguió con el mismo ímpetu--; quizá seas desgraciada; has de saber que tu hijo te ama ahora más que a sí mismo y que te equivocarías si pusieses en duda mi ternura. Jamás cesaré de quererte... ¡Ea, basta! He creído que debía, ante todo, darte esa seguridad.\"},{\"heading\":false,\"text\":\"Pulkeria Alexandrovna besó a su hijo, le estrechó contra su pecho y lloró silenciosamente.\"},{\"heading\":false,\"text\":\"--No sé lo que te pasa, Rodia--dijo--. Hasta ahora, yo había creído sencillamente que nuestra presencia te fastidiaba; mas en este momento me doy cuenta de que te amenaza una gran desgracia y que vives en la intranquilidad. Ya lo sospechaba, Rodia. Perdóname que te hable de esto; pienso en ello constantemente, hasta cuando duermo. La noche pasada, tu hermana deliraba y repetía constantemente tu nombre. He oído algunas palabras; pero no he entendido nada. Desde esta mañana hasta el momento de tu visita, he estado como el reo que espera la ejecución; tenía no sé qué presentimiento. ¡Rodia, Rodia! ¿A dónde vas? Estás a punto de partir, ¿no es verdad?\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--Lo había adivinado. Pero, si tienes que partir, yo puedo ir contigo. Dunia nos acompañará; te quiere mucho. Si es menester, llevaremos también a Sofía Semenovna. Ya lo ves, estoy pronta a aceptarla por hija. Demetrio Prokofitch nos ayudará en nuestros preparativos para el viaje... Pero... ¿a dónde vas?\"},{\"heading\":false,\"text\":\"--Adiós, mamá.\"},{\"heading\":false,\"text\":\"--¡Cómo! ¿hoy mismo?--exclamó, como si se tratase de una separación eterna.\"},{\"heading\":false,\"text\":\"--No puedo quedarme. Es absolutamente preciso que te deje.\"},{\"heading\":false,\"text\":\"--¿Y no puedo ir contigo?...\"},{\"heading\":false,\"text\":\"--No; pero ponte de rodillas y ruega a Dios por mí; Dios oirá acaso tu plegaria.\"},{\"heading\":false,\"text\":\"--¡Ojalá me oiga! Te echaré mi bendición. ¡Oh Dios mío!\"},{\"heading\":false,\"text\":\"Sí, estaba contento de que su hermana no asistiese a aquella entrevista. Para desahogar su ternura, tenía necesidad de estar a solas, y un testigo cualquiera, aunque hubiera sido Dunia, hubiese estorbado. Cayó a los pies de su madre y los besó. Pulkeria Alexandrovna y su hijo se abrazaron llorando; la madre no hizo ninguna pregunta; había comprendido que el joven atravesaba una crisis terrible y que su suerte iba a decidirse en seguida.\"},{\"heading\":false,\"text\":\"--¡Rodia, mi querido primogénito!--dijo la madre sollozando--; hete ahora como eras en tu infancia; de ese modo venías a hacerme caricias y a darme besos. En otro tiempo, cuando tu padre vivía, no teníamos, en medio de nuestra desgracia, otro consuelo que tu presencia, y después que hubo muerto, ¡cuántas veces tú y yo hemos llorado sobre su sepultura abrazados como ahora! Sí, si lloro desde hace tiempo, es porque mi corazón maternal tenía presentimientos siniestros. La tarde en que llegamos a San Petersburgo, desde nuestra primera entrevista, tu cara me lo ha revelado todo; cuando te abrí la puerta pensé, al verte, que había llegado la hora fatal. ¿No te vas en seguida, Rodia?\"},{\"heading\":false,\"text\":\"--No.\"},{\"heading\":false,\"text\":\"--¿Volverás?\"},{\"heading\":false,\"text\":\"--Sí, volveré.\"},{\"heading\":false,\"text\":\"--Hijo, no te enojes; no me atrevo a preguntarte: ¿Te vas muy lejos?\"},{\"heading\":false,\"text\":\"--Muy lejos.\"},{\"heading\":false,\"text\":\"--¿Tendrás allí un empleo, una posición?\"},{\"heading\":false,\"text\":\"--Tendré lo que Dios quiera; ruega solamente por mí.\"},{\"heading\":false,\"text\":\"Raskolnikoff iba a salir; pero su madre se agarró a él y le miró con expresión de desesperado dolor.\"},{\"heading\":false,\"text\":\"--¡Basta, mamá!--dijo el joven, que ante aquella angustia desgarradora sentía profundamente haber venido.\"},{\"heading\":false,\"text\":\"--¿No partes para siempre? ¿No vas a ponerte en camino en seguida? ¿Vendrás mañana?\"},{\"heading\":false,\"text\":\"--Sí, sí; adiós.\"},{\"heading\":false,\"text\":\"Al fin logró escapar.\"},{\"heading\":false,\"text\":\"La tarde era calurosa, aunque no sofocante. Por la mañana, el tiempo había aclarado. Raskolnikoff volvió apresuradamente a su casa. Quería acabarlo todo antes de la puesta del sol; por el momento, cualquier encuentro le hubiese sido muy desagradable. Al subir a su cuarto advirtió que Anastasia, ocupada en preparar el te, había dejado su tarea para mirarle con curiosidad.\"},{\"heading\":false,\"text\":\"«¿Habrá alguien en mi cuarto?» Y, a pesar suyo, pensó en el odioso Porfirio; pero, cuando abrió la puerta de la habitación, vió a Dunia. La joven, pensativa estaba sentada en el sofá. Sin duda esperaba a su hermano hacía mucho tiempo. Raskolnikoff se detuvo en el umbral. Dunia, estremecida, se levantó vivamente y le miró con fijeza. En los ojos de la joven se leía inmensa pesadumbre; una sola mirada probó a Raskolnikoff que la joven lo sabía todo.\"},{\"heading\":false,\"text\":\"--¿Puedo acercarme a ti, o debo retirarme?--le preguntó con voz trémula.\"},{\"heading\":false,\"text\":\"--He pasado el día esperándote en casa de Sofía Semenovna; pensábamos verte allí.\"},{\"heading\":false,\"text\":\"Raskolnikoff entró en la habitación, y se dejó caer desfallecido en una silla.\"},{\"heading\":false,\"text\":\"--Me siento débil, Dunia; estoy muy fatigado, y en este momento, sobre todo, tendría necesidad de todas mis fuerzas.\"},{\"heading\":false,\"text\":\"Fijó en su hermana una mirada de desconfianza.\"},{\"heading\":false,\"text\":\"--¿Dónde has pasado la última noche?\"},{\"heading\":false,\"text\":\"--No me acuerdo bien; quería tomar un partido definitivo, y muchas veces me he aproximado al Neva; de esto sí me acuerdo. Mi intención era acabar así; pero... no he podido resolverme...--dijo en voz baja, tratando de leer en el rostro de Dunia la impresión producida por sus palabras.\"},{\"heading\":false,\"text\":\"--¡Alabado sea Dios! Era precisamente lo que temíamos Sofía Semenovna y yo. ¿Crees en la vida? ¡Alabado sea Dios!\"},{\"heading\":false,\"text\":\"Raskolnikoff se sonrió amargamente.\"},{\"heading\":false,\"text\":\"--No creía en ella; pero hace un momento he estado en casa de nuestra madre, y nos hemos abrazado llorando; soy incrédulo, y, sin embargo, le he pedido que orase por mí. ¡Sólo Dios sabe lo que sucede en este momento! Yo mismo no sé qué pasa por mí.\"},{\"heading\":false,\"text\":\"--¿Que has estado en casa de nuestra madre? ¿Le has hablado?--exclamó Dunia con espanto--. ¿Es posible que hayas tenido valor para decirle _aquello_?\"},{\"heading\":false,\"text\":\"--No, yo no se lo he dicho, pero sospecha algo. Te ha oído soñar en voz alta la última noche, y creo que ha adivinado la mitad de ese secreto. He cometido un error al ir a verla; no sé por qué lo he hecho, Dunia. Soy un hombre bajo...\"},{\"heading\":false,\"text\":\"--Sí; pero un hombre dispuesto a aceptar la expiación. La aceptarás, ¿verdad?\"},{\"heading\":false,\"text\":\"--Al instante. Para huir de ese deshonor quería ahogarme, Dunia; pero en el momento en que iba a arrojarme al agua, me he dicho que un hombre fuerte no debe tener miedo al oprobio. ¿Es esto orgullo, Dunia?\"},{\"heading\":false,\"text\":\"--Sí, Rodia.\"},{\"heading\":false,\"text\":\"Le brillaron los ojos a Raskolnikoff con una especie de relámpago. Se consideraba feliz al pensar que había conservado su orgullo.\"},{\"heading\":false,\"text\":\"--¿Verdad que no crees que he tenido simplemente miedo al agua?--preguntó sonriendo con tristeza.\"},{\"heading\":false,\"text\":\"--¡Oh, Rodia, basta!--respondió la joven, ofendida por tal suposición.\"},{\"heading\":false,\"text\":\"Ambos guardaron silencio durante diez minutos. Raskolnikoff tenía los ojos bajos. Dunia le miraba con expresión de sufrimiento. De repente el joven se levantó.\"},{\"heading\":false,\"text\":\"--La hora avanza. Hay tiempo de partir. Voy a entregarme; pero no sé por qué lo hago.\"},{\"heading\":false,\"text\":\"Por las mejillas de Dunia corrieron gruesas lágrimas.\"},{\"heading\":false,\"text\":\"--Lloras, hermana mía; pero, ¿puedes tenderme la mano?\"},{\"heading\":false,\"text\":\"--¿Lo dudabas?\"},{\"heading\":false,\"text\":\"La joven lo estrechó contra su pecho.\"},{\"heading\":false,\"text\":\"--¿Acaso aceptando la expiación no borras la mitad de tu crimen?--exclamó, al tiempo que abrazaba a su hermano.\"},{\"heading\":false,\"text\":\"--¡Mi crimen! ¿Qué crimen?--repitió en un acceso de cólera--; ¿el de haber matado a un gusano sucio y malo; a una vieja perversa y perjudicial a todo el mundo; un vampiro que chupaba la sangre a los pobres? Tal asesinato debía servir de indulgencia para cuarenta pecados. No pienso en modo alguno en borrarlo, aunque me griten por todos lados: ¡crimen! ¡crimen! Ahora que me he decidido a afrontar voluntariamente ese deshonor, ahora sólo es cuando el absurdo de mi cobarde determinación se me presenta con toda claridad. Es tan sólo por bajeza y por impotencia por lo que me resuelvo a este acto, a menos que no sea también por interés, como me lo aconsejaba Porfirio.\"},{\"heading\":false,\"text\":\"--¡Hermano, hermano! ¿qué estás diciendo? ¿No te haces cargo de que has vertido sangre?--exclamó Dunia consternada.\"},{\"heading\":false,\"text\":\"--¿Y qué? Todo el mundo la vierte--prosiguió con vehemencia creciente--. Siempre ha corrido a torrentes sobre la tierra; las personas que la derramaron como si fuera _Champagne_ subieron en seguida al Capitolio y fueron declarados protectores de la humanidad. Examina las cosas un poco más cerca para juzgarlas. También trataba yo de hacer bien a los hombres; centenares, millares de buenas acciones hubiesen compensando ampliamente aquella única tontería, o, mejor dicho, torpeza, porque la idea no era tan tonta como lo parece ahora. Cuando el éxito falta, los designios mejor concertados parecen estúpidos. Yo tan sólo trataba de crearme, por medio de aquella tontería, una situación independiente, asegurar mis primeros pasos de la vida, procurarme recursos; después hubiera levantado el vuelo... Pero he fracasado, y por eso soy un miserable. Si hubiese logrado mi objeto, se me hubieran dedicado coronas; al presente no sirvo más que para que se me arroje a los perros.\"},{\"heading\":false,\"text\":\"--No se trata de eso. ¿Qué estás diciendo, hermano mío?\"},{\"heading\":false,\"text\":\"--Es cierto, no he procedido según las reglas de la estética. No sé por qué ha de ser más glorioso lanzar bombas sobre una ciudad sitiada, que asesinar a una persona a hachazos. El temor de la estética es el primer signo de la impotencia. Jamás lo he comprendido tan bien como ahora, ni nunca he comprendido menos cuál es mi crimen. Nunca he sido más fuerte ni he estado más convencido que en este momento.\"},{\"heading\":false,\"text\":\"Su pálido y demudado rostro se había de repente coloreado. Pero cuando acababa de proferir esta última exclamación, su mirada se encontró por casualidad con la de Dunia, y ésta le miraba con tanta tristeza, que su exaltación cayó de repente, no pudiendo menos de pensar que en rigor había hecho la desgracia de aquellas dos pobres mujeres.\"},{\"heading\":false,\"text\":\"--Dunia querida: si soy culpable, perdóname, aunque no merezca ningún perdón, si es que realmente soy culpable. Adiós; no disputemos, ya es tiempo de partir. No me sigas, te lo suplico; tengo aún una visita que hacer... Ve al instante a juntarte con nuestra madre, y no te separes de ella, te lo suplico. Es la última petición que te dirijo. Cuando me he separado de ella estaba muy inquieta, y temo que no pueda soportar su desventura: o morirá, o se volverá loca. Vela por ella. Razumikin no os abandonará; ya le he hablado... No llores por mí; aunque asesino, trataré de ser todavía valeroso y honrado. Quizás oigas hablar de mí alguna vez. No os deshonraré; ya verás; aun he de probar... Ahora, adiós--se apresuró a añadir, advirtiendo, mientras hacía sus promesas, una extraña expresión en los ojos de Dunia--. ¿Por qué lloras de ese modo? No llores; no nos separaremos para siempre... ¡Ah, sí! Espera; me olvidaba...\"},{\"heading\":false,\"text\":\"Tomó de la mesa un grueso libro cubierto de polvo. Lo abrió y sacó una miniatura, pintada en marfil. Era el retrato de la hija de su patrona, la joven a quien había amado. Durante un instante contempló aquel rostro expresivo y triste. Después besó el retrato y se lo dió a Dunia.\"},{\"heading\":false,\"text\":\"--Muchas veces he hablado de _aquello_ con ella--dijo distraídamente--; hice depositario a su corazón del proyecto que debía tener tan lamentable resultado. No te alarmes--continuó, dirigiéndose a Dunia--; ella experimentó tanta repugnancia y tanto horror como tú; ahora me alegro de que haya muerto.\"},{\"heading\":false,\"text\":\"Después, volviendo al objeto principal de sus preocupaciones, dijo:\"},{\"heading\":false,\"text\":\"--Lo esencial ahora es saber si he calculado bien lo que voy a hacer, y si estoy pronto a aceptar todas las consecuencias. Se asegura que me es necesaria esta prueba. ¿Es cierto? ¿Qué fuerza moral habré adquirido cuando salga del presidio, quebrantado por veinte años de sufrimiento? ¿Valdrá entonces la pena de vivir? ¡Y yo he consentido en sobrellevar el peso de semejante existencia! ¡Oh! Esta mañana, al irme a arrojar al Neva, he comprendido que era un cobarde.\"},{\"heading\":false,\"text\":\"Al cabo salieron ambos. Durante esta penosa entrevista Dunia había estado sostenida solamente por el amor de su hermano. Se separaron en la calle. Después de haber marchado unos cuantos pasos, la joven se volvió para ver por última vez a Raskolnikoff. Cuando hubo llegado a la esquina, el joven se volvió también, pero advirtiendo Raskolnikoff que la mirada de su hermana estaba fija en él, hizo un gesto de impaciencia, y aun de cólera, invitándola a que continuase el camino. En seguida dió vuelta a la esquina.\"}]},{\"title\":\"sexta parte — capítulo VII\",\"blocks\":[{\"heading\":false,\"text\":\"Comenzaba a caer la noche cuando llegaba a casa de Sonia. Durante la mañana y la tarde, la joven le había esperado con ansiedad. Por la mañana había recibido la visita de Dunia. Esta fué a primera hora, habiendo sabido la víspera por Svidrigailoff que Sofía Semenovna lo sabía todo. No recordaremos minuciosamente la conversación de las dos mujeres; limitémonos a decir que lloraron juntas y se hicieron muy amigas. De esta entrevista sacó Dunia, por lo menos, el consuelo de pensar que no estaría solo su hermano. Era Sonia la primera que había recibido su confesión; a ella se había dirigido cuando sintió la necesidad de confiarse a un ser humano, y ella le acompañaría adondequiera que se le enviase. Sin haber hecho preguntas acerca de tales propósitos, Advocia Romanovna estaba segura de ello. Consideraba a Sonia con una especie de veneración que dejaba a la pobre muchacha toda confusa, porque se creía indigna de levantar los ojos hasta Dunia. Después de su visita a casa de Raskolnikoff, la imagen de la encantadora joven, que la había saludado tan graciosamente aquel día, quedó grabada en su alma como una visión nueva, dulcísima, la más bella de su vida.\"},{\"heading\":false,\"text\":\"Al fin, Dunia se decidió a ir a esperar a su hermano en el domicilio de este último, pensando que Raskolnikoff no podría menos de pasar por allí. En cuanto Sonia se quedó sola, el pensamiento del suicidio probable de Raskolnikoff le quitó todo reposo. Este era también el temor de Dunia; pero al hablar las dos jóvenes se habían dado la una a la otra todo género de razones para tranquilizarse, y lo habían, en parte, conseguido.\"},{\"heading\":false,\"text\":\"Cuando se separaron, volvió la inquietud a apoderarse de cada una de ellas. Sonia se acordó de que Svidrigailoff le había dicho: «Raskolnikoff sólo tiene la elección entre dos alternativas: o ir a Siberia, o...» Además, conocía el orgullo del joven y su carencia de sentimientos religiosos. «¿Es posible que se resigne a vivir solamente por pusilanimidad, por temor a la muerte?»--pensaba con desesperación. No dudaba ya que el desgraciado hubiese puesto fin a sus días, cuando Raskolnikoff entró en su cuarto.\"},{\"heading\":false,\"text\":\"La joven dejó escapar un grito de alegría; pero, cuando hubo observado atentamente el rostro de Raskolnikoff, palideció de pronto.\"},{\"heading\":false,\"text\":\"--Vamos, sí--dijo riendo Raskolnikoff--. Vengo a buscar tus cruces, Sonia. Tú has sido quien me ha impulsado a ir a entregarme; ahora que voy a hacerlo, ¿de qué tienes miedo?\"},{\"heading\":false,\"text\":\"Sonia le miró con asombro. Aquel tono le parecía extraño. Todo su cuerpo se estremeció; pero al cabo de un minuto comprendió que aquella alegría era fingida. Conforme la estaba hablando, Raskolnikoff miraba a un rincón, y parecía tener miedo de fijar los ojos en ella.\"},{\"heading\":false,\"text\":\"--Ya lo ves, Sonia; he pensado que eso es lo mejor. Hay una circunstancia... pero esto sería largo de contar, y no tengo tiempo. ¿Sabes lo que me irrita? Me pone furioso pensar que en un instante me van a rodear todos esos brutos; que todos me asestarán sus miradas, me dirigirán estúpidas preguntas, a las cuales tendré que responder; me señalarán con el dedo... No iré a casa de Porfirio; no puedo aguantar a ese hombre. Prefiero ir a buscar a mi amigo _Pólvora_. ¡Lo que va a sorprenderse éste! Puedo contar de antemano con un excelente éxito de asombro. Pero me convendría tener más sangre fría. En este último tiempo me he hecho muy irritable. ¿Lo creerás? hace un momento ha faltado muy poco para que amenazase con el puño a mi hermana, porque se había vuelto para verme por última vez. Ya ves lo bajo que he caído. Bueno; ¿dónde están las cruces?\"},{\"heading\":false,\"text\":\"El joven no parecía que se hallase en su estado normal. Ni podía permanecer un minuto en su puesto, ni fijar sus pensamientos en un objeto; sus ideas se sucedían sin transición; por mejor decir, deliraba. Le temblaban ligeramente las manos.\"},{\"heading\":false,\"text\":\"Sonia guardaba silencio. Sacó de una caja de cruces una de madera de ciprés y otra de cobre; después se santiguó, y luego de repetir la misma ceremonia en la persona de Raskolnikoff, le puso al cuello la cruz de ciprés.\"},{\"heading\":false,\"text\":\"--¿Es ésta una manera de expresar que yo cargo con la cruz? ¡Je, je, je! ¡Como si empezase a sufrir ahora! La cruz de ciprés es la de los humildes. La cruz de cobre perteneció a Isabel. Tú la guardas para ti; déjamela ver. ¿De modo que la llevaba... en aquel momento? Conozco otros dos o tres objetos de piedad: una cruz de plata y una imagen. Los eché entonces sobre el pecho de la vieja. Esos son los que debiera colgarme yo ahora al cuello. Pero no digo más que tonterías, y olvido mi asunto. Estoy distraído. He venido, sobre todo, para prevenirte, a fin de que sepas... Pues bien; esto es todo... no he venido más que para eso. (¡Hum! Creía, sin embargo, que tenía que decirle otra cosa.) Vamos a ver: tú misma me has exigido que dé este paso. Voy a entregarme, y tu deseo será satisfecho. ¿Por qué lloras entonces? ¡Tú también! ¡Basta, basta! ¡Oh, qué penoso me es todo esto!\"},{\"heading\":false,\"text\":\"Al ver llorar a Sonia, se angustió el corazón del joven. «¿Qué soy yo para ella?--pensaba--. ¿Por qué se interesa por mí tanto como podría interesarse mi madre o Dunia?»\"},{\"heading\":false,\"text\":\"--Haz la señal de la cruz. Di una oración--suplicó con voz temblorosa la joven.\"},{\"heading\":false,\"text\":\"--Sea. Rezaré cuanto quieras y de buena voluntad, Sonia, de buena voluntad.\"},{\"heading\":false,\"text\":\"El hizo muchos signos de cruz. Ella se puso a la cabeza un pañuelo verde, el mismo, probablemente, de que Marmeladoff había hablado en la taberna, y que servía entonces para toda la familia. Tal pensamiento cruzó por la mente de Raskolnikoff; pero se abstuvo de preguntar nada a este propósito. Comenzaba a advertir que tenía distracciones continuas, y que estaba extremadamente turbado; esto le inquietaba. De repente advirtió que Sonia se preparaba a salir con él.\"},{\"heading\":false,\"text\":\"--¿Qué haces? ¿A dónde vas? ¡Quédate, quédate!--exclamó con risa irritada y se dirigió a la puerta--. ¿Qué necesidad tengo de ir allí con acompañamiento?\"},{\"heading\":false,\"text\":\"Sonia no insistió. El, ni siquiera le dijo adiós; se había olvidado de ella, le preocupaba tan sólo una idea.\"},{\"heading\":false,\"text\":\"«Realmente, ¿está ya hecho todo?--se preguntaba al bajar la escalera--. ¿No habrá medio de volverse atrás, de arreglarlo todo... y de no ir allí?»\"},{\"heading\":false,\"text\":\"Sin embargo, siguió su camino, comprendiendo súbitamente que había pasado la hora de las vacilaciones. En la calle se acordó de que no había dicho adiós a Sonia, que se había detenido en medio de la sala, y de que una orden suya la había como clavado en el suelo. Se planteó entonces otra cuestión, que desde hacía algunos minutos flotaba en su espíritu sin formularse con claridad.\"},{\"heading\":false,\"text\":\"«¿Por qué le he hecho yo esta visita? Le he dicho que venía para un asunto: ¿qué asunto? Ninguno tenía con ella. ¿Para decirle que iba allí? ¡Vaya una necesidad! ¿Para decirle que la amo? ¡Si acabo de rechazarla como a un perro! En cuanto a su cruz, ¿qué necesidad tenía yo de ella? ¡Oh, qué bajo he caído! No; lo que yo buscaba eran lágrimas; lo que yo quería era gozar de los desgarramientos de su corazón. ¡Acaso he buscado, yendo a verla, ganar tiempo, retardar un momento el instante fatal! ¡Y me he atrevido a soñar con altos destinos! ¡Y me he creído llamado a hacer grandes cosas! ¡Yo, tan vil, tan miserable, tan cobarde!»\"},{\"heading\":false,\"text\":\"Caminaba a lo largo del muelle, y no tenía que ir más lejos; pero cuando llegó al puente suspendió un instante su marcha, y se dirigió después bruscamente hacia el Mercado del Heno.\"},{\"heading\":false,\"text\":\"Sus miradas se fijaban con avidez en la derecha y en la izquierda. Se esforzaba en examinar cada objeto que encontraba y en nada podía concentrar su atención.\"},{\"heading\":false,\"text\":\"«Dentro de ocho días, dentro de un mes, volveré a pasar por este puente; un coche celular me llevará yo no sé dónde. ¿Con qué ojos contemplaré este canal? ¿Me fijaré entonces en esa muestra? Ahí está escrita la palabra _Compañía_. ¿La leeré yo entonces como la leo ahora? ¿Cuáles serán mis sensaciones y mis pensamientos?... ¡Dios mío, qué mezquinas son todas estas preocupaciones! Sin duda es curioso esto en su género. ¡Ja, ja, ja! ¡De qué cosas me preocupo! Hago como los niños: me engaño a mí mismo, porque, en efecto, debería sonrojarme de mis pensamientos. ¡Qué barullo! Ese hombretón, un alemán, según todas las apariencias, que acaba de empujarme, ¿sabe a quién ha dado con el codo? Esa mujer, que lleva un niño en la mano y que pide limosna, me cree, quizá, más feliz que ella. Casualmente llevo cinco kopeks en el bolsillo. Tómalos, _matuchka_.»\"},{\"heading\":false,\"text\":\"--Dios te lo pague--dijo la mendiga con tono plañidero.\"},{\"heading\":false,\"text\":\"El Mercado del Heno estaba lleno de gente. Esta circunstancia desagradó mucho a Raskolnikoff; sin embargo, se dirigió al sitio en que la multitud era más compacta. Hubiera comprado la soledad a cualquier precio; pero se daba cuenta de que no podría gozar de ella ni un solo instante. Al llegar en medio de la plaza, el joven se acordó de repente de las palabras de Sonia: «Ve a la encrucijada; besa la tierra que has manchado con tu delito, y di en voz alta a la faz del mundo: ¡Soy un asesino!»\"},{\"heading\":false,\"text\":\"Al recordarlo, todo su cuerpo se estremeció. Las angustias de los días anteriores de tal modo habían desecado su alma, que se consideró feliz al encontrarla accesible a una sensación nueva, y se abandonó por completo a ella. Se apoderó de él un enternecimiento dulcísimo y se le llenaron los ojos de lágrimas.\"},{\"heading\":false,\"text\":\"Se puso de rodillas en medio de la plaza, se inclinó hasta el suelo, y besó con alegría la tierra fangosa. Después de haberse levantado, se arrodilló de nuevo.\"},{\"heading\":false,\"text\":\"--He ahí uno que ha empinado el codo más de lo regular--exclamó un joven que estaba a su lado.\"},{\"heading\":false,\"text\":\"Esta observación provocó muchas carcajadas.\"},{\"heading\":false,\"text\":\"--Es un peregrino que va a Jerusalén, amigos míos. Se despide de sus hijos, de su patria; saluda a todo el mundo, y da el beso de la despedida al suelo de la capital--añadió un menestral que estaba ligeramente ebrio.\"},{\"heading\":false,\"text\":\"--Es todavía muy joven--dijo un tercero.\"},{\"heading\":false,\"text\":\"--Es un noble--observó gravemente otro.\"},{\"heading\":false,\"text\":\"--En la actualidad, no se distingue a los nobles de los que no lo son.\"},{\"heading\":false,\"text\":\"Viéndose objeto de la atención general, Raskolnikoff perdió un poco de su serenidad, y las palabras «Soy un asesino», que iban quizá a salir de su boca, expiraron en sus labios. Las exclamaciones y los gestos de la multitud le dejaron, por otra parte, indiferente, y con mucha calma se encaminó a la comisaría de policía. Conforme iba andando, una sola visión atrajo sus miradas; por lo demás, había esperado encontrarla en la calle, y no se asombró.\"},{\"heading\":false,\"text\":\"En el momento en que acababa de prosternarse en el Mercado del Heno por segunda vez, vió a Sonia a una distancia de cincuenta pasos. La joven trató de substraerse a las miradas de Raskolnikoff, ocultándose detrás de una de las barracas de madera que se encuentran en la plaza. ¡Así le acompañaba cuando él subía este calvario! Desde aquel instante, Raskolnikoff adquirió la convicción de que Sonia era suya para siempre, y de que le seguiría a todas partes, aunque su destino hubiera de conducirle al fin del mundo.\"},{\"heading\":false,\"text\":\"Llegó finalmente al sitio fatal. Entró en el zaguán con paso bastante firme. La oficina de policía estaba situada en el tercer piso. «Antes que llegue arriba tengo tiempo de volverme»--pensaba el joven. En tanto que nada había confesado, se complacía en pensar en que podía cambiar de resolución.\"},{\"heading\":false,\"text\":\"Como en su primera visita, encontró la escalera cubierta de suciedad, impregnada de las exhalaciones que vomitaban las cocinas, abiertas sobre cada descansillo. Mientras subía, se le doblaban las piernas, y tuvo que detenerse un instante para tomar aliento, recobrarse un poco, y preparar su entrada.\"},{\"heading\":false,\"text\":\"«Pero, ¿a qué viene eso? ¿Para qué?--se preguntó de repente--. Puesto que hay que apurar el vaso, poco importa cómo he de beberlo. Más valdrá cuanto más amargo sea.»\"},{\"heading\":false,\"text\":\"Después se ofrecieron a su espíritu las imágenes de Ilia Petrovitch y del oficial _Pólvora_. «¿Por qué voy a él? ¿No podría dirigirme a otro? ¿A Nikodim Fomitch, por ejemplo? ¿No sería mejor ir a buscar al comisario a su domicilio particular, y contárselo todo en una conversación privada?... No, no; hablaré a _Pólvora_, y esto se acabará más pronto.»\"},{\"heading\":false,\"text\":\"Con el rostro inundado de frío sudor y casi sin darse cuenta de lo que hacía, Raskolnikoff abrió la puerta de la comisaría. Esta vez no vió en la antesala más que a un _dvornik_ y a un hombre del pueblo. El joven pasó a la otra habitación, donde trabajaban dos escribientes. Zametoff no estaba allí ni Nikodim Fomitch tampoco.\"},{\"heading\":false,\"text\":\"--¿No hay nadie?--dijo Raskolnikoff, dirigiéndose a uno de los empleados.\"},{\"heading\":false,\"text\":\"--¿Por quién pregunta usted?\"},{\"heading\":false,\"text\":\"--A... a...\"},{\"heading\":false,\"text\":\"--Al oír sus palabras, sin ver su rostro, he adivinado la presencia de un ruso... como se dice en no sé qué cuento. Mis respetos--gritó bruscamente una voz conocida.\"},{\"heading\":false,\"text\":\"Raskolnikoff tembló. _Pólvora_ estaba delante de él; acababa de salir de una tercera habitación. «El destino lo ha querido»--pensó el joven.\"},{\"heading\":false,\"text\":\"--¿Usted por aquí? ¿Con qué motivo?--exclamó Ilia Petrovitch, que parecía de muy buen humor y muy animado--. Si ha venido por algún asunto, es aún demasiado pronto. Por una casualidad me encuentro aquí yo... ¿En qué puedo...? Confieso que no le... ¿Cómo, cómo es su nombre?... Perdóneme usted.\"},{\"heading\":false,\"text\":\"--Raskolnikoff.\"},{\"heading\":false,\"text\":\"--¡Ah! Sí; Raskolnikoff. ¡Ha podido usted creer que le había olvidado! Le suplico que no me crea tan... Rodión Ra... Radionitch, ¿no es eso?\"},{\"heading\":false,\"text\":\"--Rodión Romanovitch.\"},{\"heading\":false,\"text\":\"--Sí, sí; Rodión Radiovitch, Rodión Romanovitch; lo tenía en la punta de la lengua. Confieso a usted que siento sinceramente la manera que tuvimos de portarnos con usted hace tiempo. Después me lo explicaron todo y he sabido que era usted un escritor, un sabio... He tenido también noticia de que empezaba usted la carrera de las letras. ¡Oh Dios mío! ¿Cuál es el literato, cuál es el sabio que en sus comienzos no ha hecho más o menos la vida de bohemio? Tanto mi mujer como yo estimamos la literatura; en mi mujer es una pasión. Es loca por las letras y las artes. Excepto el nacimiento, todo lo demás puede adquirirse por el talento, el saber, la inteligencia, el genio. Un sombrero, por ejemplo, ¿qué significa? Un sombrero lo puedo comprar en casa de Zimmermann; pero lo que abriga el sombrero, eso no puedo comprarlo. Confieso que quería ir a casa de usted a darle explicaciones; pero, he pensado que quizá usted... De todos modos, con estas charlas no le he preguntado el objeto de su visita. ¿Parece que la familia de usted está ahora en San Petersburgo?\"},{\"heading\":false,\"text\":\"--Sí, mi madre y mi hermana.\"},{\"heading\":false,\"text\":\"--He tenido el honor y el placer de encontrar a su hermana de usted. Es una persona tan encantadora como distinguida. Verdaderamente deploro con toda mi alma el altercado que tuvimos aquel día. En cuanto a las conjeturas fundadas en el desmayo de usted, se ha reconocido su falsedad. Comprendo la indignación de usted. Ahora que su familia vive en San Petersburgo, ¿va usted, acaso, a cambiar de domicilio?\"},{\"heading\":false,\"text\":\"--No, no por el momento. Había venido a preguntar... Creí encontrar aquí a Zametoff.\"},{\"heading\":false,\"text\":\"--¡Ah! Es verdad. Usted es amigo suyo; lo he oído decir. Pues bien: Zametoff no está ya con nosotros. Sí, lo hemos perdido; nos ha dejado ayer, y antes de su partida ha habido entre él y nosotros un fuerte altercado. Es un galopín sin consistencia; nada más. Había hecho concebir algunas esperanzas; pero ha tenido la desgracia de frecuentar el trato de nuestra brillante juventud, y se le ha metido en la cabeza sufrir exámenes, para poder darse tono y echárselas de sabio. Hay que advertir que Zametoff no tiene nada de común con usted, con usted y con el señor Razumikin. Ustedes han abrazado la carrera de la ciencia, y los reveses de la fortuna no les arredran. Para ustedes los atractivos de la vida no valen nada; hacen la existencia austera, ascética, monacal, del hombre de estudio. Un libro, una pluma detrás de la oreja, una investigación científica, son cosas que bastan para la felicidad de ustedes. Yo mismo, hasta cierto punto... ¿Ha leído usted la correspondencia de Livingstone?\"},{\"heading\":false,\"text\":\"--No.\"},{\"heading\":false,\"text\":\"--Yo sí la he leído. Ahora el número de los nihilistas ha aumentado considerablemente, lo cual no es asombroso en una época como la nuestra. De usted para mí... ¿no es usted nihilista? Respóndame francamente.\"},{\"heading\":false,\"text\":\"--No.\"},{\"heading\":false,\"text\":\"--No tenga usted temor de ser franco conmigo, como lo sería consigo mismo. Una cosa es el servicio y otra cosa... ¿Usted creería que iba a decir la _amistad_?, pues se engaña. No es la amistad, sino el sentimiento del hombre y del ciudadano, el sentimiento de la humanidad y del amor hacia el Omnipotente. Puedo ser un personaje oficial, un funcionario; pero no por eso debo dejar de sentir en mí el hombre y el ciudadano. ¿Hablaba usted de Zametoff? Pues bien, Zametoff es un muchacho que copia el _chic_ francés, que da ruido en los sitios sospechosos cuando ha bebido un vaso de _Champagne_ o de vino del Don. Ahí tiene usted a Zametoff. Quizá he sido un poco vivo con él, pero si mi indignación me ha llevado demasiado lejos, tuvo su origen en un sentimiento elevado: el celo por los intereses del servicio. Por otra parte, yo poseo un cargo, una posición, cierta importancia social; soy casado y padre de familia, y lleno mi deber de hombre y de ciudadano; en tanto que él, ¿qué es él? Permítame usted que se lo pregunte. Me dirijo a usted como a un hombre favorecido con los beneficios de la educación. Ahí tiene usted; las profesoras en partos, por ejemplo, se han multiplicado de un modo extraordinario.\"},{\"heading\":false,\"text\":\"Raskolnikoff miró al oficial con aire asombrado. Las palabras de Ilia Petrovitch, que violentamente acababa de levantarse de la mesa, produjeron en su ánimo una impresión que él no se explicaba. Sin embargo, algo comprendía. En aquel momento preguntaba con los ojos a su interlocutor e ignoraba cómo acabaría todo aquello.\"},{\"heading\":false,\"text\":\"--Hablo de estas jóvenes que llevan el cabello corto a lo Tito--continuó el inagotable Ilia Petrovitch--. Yo las llamo profesoras en partos, y el nombre me parece muy bien aplicado. ¡Je, je! Siguen cursos de anatomía. Dígame, si me pusiese enfermo, ¿cree usted que me dejaría tratar por una de esas señoritas? ¡Je, je!\"},{\"heading\":false,\"text\":\"Ilia Petrovitch se echó a reír encantado de su chiste.\"},{\"heading\":false,\"text\":\"--Admito la sed de instrucción; pero, ¿no se puede uno instruir sin dar en semejantes excesos? ¿Por qué ser insolente? ¿Por qué insultar a nobles personalidades, como lo hace ese necio de Zametoff? ¿Por qué me ha insultado, le pregunto a usted? Otra epidemia que hace terribles progresos, es la del suicidio. Se gasta uno todo lo que tiene, y en seguida se mata. Muchachas, jovenzuelos, viejos. Hemos sabido últimamente que un señor recién llegado aquí acaba de poner fin a sus días. ¡Nil Pavlitch, eh, Nil Pavlitch! ¿cómo se llama el caballero que se ha matado esta mañana en la Petersburgskeria?\"},{\"heading\":false,\"text\":\"--Svidrigailoff--dijo uno que se encontraba en la habitación inmediata.\"},{\"heading\":false,\"text\":\"Raskolnikoff tembló.\"},{\"heading\":false,\"text\":\"--¡Svidrigailoff! ¡Svidrigailoff se ha levantado la tapa de los sesos!\"},{\"heading\":false,\"text\":\"--¡Cómo! ¿Usted conocía a Svidrigailoff?\"},{\"heading\":false,\"text\":\"--Sí; en efecto, había venido hace poco. Acababa de perder a su esposa; era un libertino. Se ha pegado el tiro en condiciones muy escandalosas. Han encontrado sobre su cadáver un librito de notas en que estaban escritas estas palabras: «Muero en posesión de mis facultades; que no se acuse a nadie de mi muerte.» Este hombre tenía, según se dice, dinero. ¿De qué le conocía usted?\"},{\"heading\":false,\"text\":\"--¿Yo...? Había sido mi hermana institutriz en su casa.\"},{\"heading\":false,\"text\":\"--¡Ah, ah!... Entonces puede usted dar noticias acerca de él. ¿No tenía usted sospechas de su proyecto?\"},{\"heading\":false,\"text\":\"--Le vi ayer. Le encontré bebiendo vino... Nada sospeché.\"},{\"heading\":false,\"text\":\"A Raskolnikoff le parecía que tenía una montaña sobre el pecho.\"},{\"heading\":false,\"text\":\"--¿Qué es eso? Se pone usted pálido. ¡Está tan cargada la atmósfera de esta habitación!\"},{\"heading\":false,\"text\":\"--Sí; ya es tiempo de que me vaya--balbuceó el joven--. Perdóneme usted si le he molestado.\"},{\"heading\":false,\"text\":\"--Nada de eso. Aquí estamos siempre a su disposición. Me ha causado gran placer y me complazco en declararlo.\"},{\"heading\":false,\"text\":\"Al pronunciar estas palabras, Ilia Petrovitch tendió la mano al joven.\"},{\"heading\":false,\"text\":\"--Quería solamente... Tenía un asunto que tratar con Zametoff.\"},{\"heading\":false,\"text\":\"--Comprendo, comprendo. Tanto gusto en haberle visto.\"},{\"heading\":false,\"text\":\"--También yo lo he tenido... Hasta la vista--dijo Raskolnikoff sonriendo.\"},{\"heading\":false,\"text\":\"Salió tambaleándose. Le daba vueltas la cabeza. Apenas podía tenerse en pie, y, al bajar la escalera, le fué forzoso apoyarse en la pared para no caerse. Le pareció que un _dvornik_, que se dirigía al despacho de policía, tropezaba con él al pasar; que un perro ladraba en una habitación del primer piso, y que una mujer gritaba para hacer callar al animal. Llegado al pie de la escalera, entró en el patio. Erguida, no lejos de la puerta, Sonia, pálida como la muerte, le miraba con asombro. Se detuvo frente a ella. La joven se retorcía las manos; su fisonomía expresaba la más terrible desesperación. Al verla, Raskolnikoff sonrió; pero, ¡con qué sonrisa! Un instante después volvía a entrar en la oficina de policía.\"},{\"heading\":false,\"text\":\"Ilia Petrovitch estaba ojeando unos papeles. Delante de él se hallaba el mismo _mujik_ que un momento antes había tropezado con Raskolnikoff en la escalera.\"},{\"heading\":false,\"text\":\"--¡Ah! ¿Usted aquí otra vez? ¿Se le ha olvidado algo? ¿Qué le pasa?\"},{\"heading\":false,\"text\":\"Con los labios descoloridos, fija la mirada, Raskolnikoff avanzó lentamente hacia Ilia Petrovitch y, apoyándose con la mano en la mesa ante la cual estaba sentado el oficial de policía, quiso hablar, pero no pudo pronunciar más que sonidos ininteligibles.\"},{\"heading\":false,\"text\":\"--¿Está usted enfermo? ¡Una silla! Aquí está. Siéntese usted. ¡Agua!\"},{\"heading\":false,\"text\":\"Raskolnikoff se dejó caer en el asiento que se le ofrecía; pero sus ojos no se apartaban de Ilia Petrovitch, cuyo semblante expresaba una sorpresa muy desagradable. Durante un minuto ambos se miraron en silencio. Trajeron agua.\"},{\"heading\":false,\"text\":\"--Yo soy...--empezó a decir Raskolnikoff.\"},{\"heading\":false,\"text\":\"--Beba usted.\"},{\"heading\":false,\"text\":\"El joven rechazó con un ademán el vaso que le presentaban, y en voz baja pero clara, hizo, interrumpiéndose muchas veces, la siguiente declaración:\"},{\"heading\":false,\"text\":\"--_Yo soy quien asesinó a hachazos, para robarlas, a la vieja prestamista y a su hermana Isabel._\"},{\"heading\":false,\"text\":\"Ilia Petrovitch llamó; acudieron de todas partes.\"},{\"heading\":false,\"text\":\"Raskolnikoff repitió su confesión.\"},{\"heading\":false,\"text\":\"EPILOGO\"}]},{\"title\":\"sexta parte — capítulo I\",\"blocks\":[{\"heading\":false,\"text\":\"Siberia. A la orilla de un río ancho y desierto se levanta una ciudad, uno de los centros administrativos de Rusia. En la ciudad hay una fortaleza; en la fortaleza una prisión. En la prisión está, desde hace nueve meses, Rodión Romanovitch Raskolnikoff, condenado a trabajos forzados (segunda categoría). Cerca de diez y ocho meses han pasado desde el día que cometió su crimen.\"},{\"heading\":false,\"text\":\"En la instrucción de su proceso no hubo apenas dificultades. El culpable renovó sus confesiones con tanta fuerza como claridad y precisión, sin confundir las circunstancias, sin suavizar el horror, sin falsear los hechos, sin olvidar el menor detalle. Hizo una relación completa del asesinato, esclareció el misterio del objeto encontrado en manos de la vieja (se recordará que era un trozo de madera junto con una placa de hierro), contó cómo había tomado las llaves del bolsillo de la víctima, describió estas llaves y describió también el asesinato de Isabel, que hasta entonces había sido un enigma. Contó cómo Koch había venido y llamado a la puerta, y cómo, después de él, había llegado un estudiante. Refirió minuciosamente la conversación habida entre los dos hombres; cómo, en seguida, el asesino se había lanzado a la escalera y había oído los gritos de Mikolai y de Milka, ocultándose en el cuarto vacío y dirigiéndose después a su casa. Finalmente, en cuanto a los objetos robados, manifestó que los había enterrado debajo de una piedra en un corral que daba a la perspectiva Ascensión. Se encontraron allí, en efecto. En una palabra, todo se esclareció. Lo que, entre otras cosas, asombraba a los jueces, fué la circunstancia de que el asesino, en vez de aprovecharse de los objetos robados a la víctima, fuese a ocultarlos bajo una piedra. Todavía comprendían menos que, no solamente no se acordase de los objetos robados por él, sino que hasta se engañase acerca de su número. Se encontraba, sobre todo, inverosímil que no hubiera abierto una sola vez la bolsa, y que ignorase el contenido de ella. (Encerraba ésta trescientos diez y siete rublos y tres monedas de veinte kopeks cada una; a consecuencia de haber sido enterrados largo tiempo, los billetes se habían deteriorado considerablemente.) Se procuró adivinar por qué únicamente sobre este punto mentía el acusado, cuando en todo lo demás había dicho espontáneamente la verdad. En fin, algunos, principalmente entre los psicólogos, admitieron como posible que, en efecto, no hubiera abierto la bolsa; y que, por consiguiente, se hubiera desembarazado de ella sin saber lo que contenía; pero sacaron asimismo la conclusión de que el crimen había sido necesariamente cometido bajo la influencia de una locura momentánea. El culpable--dijeron--ha cedido a la monomanía morbosa del asesinato y del robo, sin objeto ulterior, sin cálculo interesado. Era aquella ocasión excelente para sostener la teoría moderna de la alienación temporal, teoría con la que se busca actualmente tan a menudo explicar los actos de ciertos criminales. Además, numerosos testigos habían declarado que Raskolnikoff padecía hipocondría. Estos testigos eran; el doctor Zosimoff, los antiguos compañeros del acusado, su patrona, los criados, etc. Todo esto daba muchos fundamentos para pensar que Raskolnikoff no era un asesino vulgar, un malhechor ordinario, sino que había alguna otra cosa en aquel proceso. Con gran despecho de los partidarios de esta opinión, el culpable no se cuidó de defenderse. Interrogado acerca de los motivos que habían podido inducirle al asesinato y al robo, declaró con brutal franqueza que había sido impulsado por la miseria. Esperaba--dijo--encontrar en casa de su víctima lo menos tres mil rublos, y contaba con esta suma asegurar sus primeros pasos en la vida; su carácter ligero y bajo, agriado por las privaciones y las contrariedades, había hecho de él un asesino. Cuando se le preguntó por qué había ido a denunciarse, respondió redondamente que había representado la farsa del arrepentimiento. Todo aquello era casi cínico...\"},{\"heading\":false,\"text\":\"Sin embargo, la sentencia fué menos severa de lo que se hubiera podido presumir en relación con el crimen cometido. Quizá causó buena impresión que el reo, lejos de disculparse, procurase, por el contrario, empeorar su situación. Fueron tomadas en consideración todas las extrañas particularidades de la causa. El estado de enfermedad y estrechez en que se encontraba el acusado antes de la comisión de su delito, no dejaba lugar a la menor duda. Como no se había aprovechado de los objetos robados, se supuso, o que los remordimientos se lo habían impedido, o que sus facultades intelectuales no estaban intactas cuando cometió el hecho. El asesinato, en modo alguno premeditado, de Isabel, suministró un argumento en apoyo de esta última hipótesis: un hombre comete dos asesinatos, y se olvida al mismo tiempo de que la puerta está abierta. Por último, había ido a denunciarse en el momento en que las falsas confesiones de un fanático de espíritu desequilibrado (Mikolai), acababan de desviar completamente la instrucción, y cuando la justicia estaba a cien leguas de sospechar quién era el verdadero culpable. (Porfirio Petrovitch cumplió fielmente su palabra.) Todas estas circunstancias contribuyeron a suavizar la severidad del veredicto.\"},{\"heading\":false,\"text\":\"Por otra parte, los debates dieron a conocer muchos hechos en favor del acusado. Documentos facilitados por el antiguo estudiante Razumikin demostraron que, estando en la Universidad, Raskolnikoff había compartido sus escasos recursos con un compañero pobre y enfermo. Este último había muerto, dejando en la miseria a un padre enfermo, del cual era, desde la edad de trece años, único sostén. Raskolnikoff había hecho entrar al viejo en un asilo, y más tarde había costeado los gastos de su entierro. El testimonio de la viuda Zarnitzin, fué también muy favorable al acusado. Declaró que, en la época en que habitaba en los Cinco Rincones con su inquilino, habiéndose declarado un incendio una noche en cierta casa, Raskolnikoff, con riesgo de su vida, salvó de las llamas a dos niños pequeños, sufriendo graves quemaduras al realizar tal acto de valor. Se abrió una indagatoria a propósito de este hecho, y numerosos testigos certificaron la exactitud de él. En una palabra, el tribunal, teniendo en cuenta las confesiones del culpable, así como sus buenos antecedentes, le condenó tan sólo a ocho años de trabajos forzados (segunda categoría).\"},{\"heading\":false,\"text\":\"Desde la apertura de la vista, la madre de Raskolnikoff estaba mala. Dunia y Razumikin encontraron medio de alejarla de San Petersburgo durante todo el tiempo del proceso. Razumikin eligió una ciudad de la línea férrea, y a poca distancia de la capital; así podía seguir asiduamente las audiencias y ver a Advocia Romanovna. La enfermedad de Pulkeria Alexandrovna era una afección nerviosa bastante extraña, con desarreglo, a lo menos parcial, de las facultades mentales. De vuelta en su domicilio, después de la última entrevista con su hermano, Dunia había encontrado con mucha fiebre a su madre, y con delirio. Aquella misma noche se puso de acuerdo con Razumikin acerca de lo que había de responder cuando Pulkeria Alexandrovna pidiese noticias de Raskolnikoff; a tal fin inventaron una historia, esto es, que Rodia había sido enviado muy lejos a los confines de Rusia, con una misión que debía reportarle mucho honor y provecho. Pero, con gran sorpresa de los jóvenes, ni entonces, ni después, la madre les preguntó nada acerca de este asunto. Ella misma se había forjado en la imaginación una novela, a fin de explicar la brusca desaparición de su hijo. Contaba llorando la visita de despedida que éste le había hecho, con cuyo motivo daba a entender que ella solamente conocía circunstancias misteriosas y muy graves; Rodia se veía obligado a ocultarse, porque tenía enemigos muy poderosos; por lo demás, no dudaba de que el porvenir de su hijo fuese muy brillante, y de que ciertas dificultades serían vencidas. Aseguraba a Razumikin que, con el tiempo, su hijo llegaría a ser un hombre de Estado: tenía prueba de ello en el artículo que el joven había escrito, y que denotaba un talento literario inagotable. Leía sin cesar este artículo, a veces hasta en alta voz; podía decirse que dormía con él; sin embargo, no preguntaba jamás dónde se encontraba Rodia, aunque el cuidado mismo que se ponía para evitar esta conversación hubiese podido parecerle sospechoso. El extraño silencio de Pulkeria Alexandrovna sobre ciertos puntos, acabó por inquietar a Dunia y a Razumikin. Aquélla no se quejaba de que su hijo no la escribiese, siendo así, que antes, en su ciudad natal, esperaba con impaciencia suma las cartas de su querido Rodia. Tan inexplicable era esta última circunstancia, que Dunia llegó a alarmarse. A la joven le ocurrió la idea de que su madre tenía el presentimiento de una terrible desgracia ocurrida a Rodia, y de que no se atrevía a preguntar, temerosa de saber todavía alguna cosa peor. De todos modos, Dunia veía muy claramente que su madre tenía trastornado el cerebro.\"},{\"heading\":false,\"text\":\"Dos veces, sin embargo, condujo la conversación de tal manera, que fué imposible responderle sin indicar en dónde se encontraba Rodia. A continuación de las respuestas necesariamente equívocas y difíciles que se le dieron, cayó en profunda tristeza; durante muy largo tiempo se le vió sombría y taciturna como nunca había estado. Dunia, al cabo, llegó a advertir que las mentiras y las historias inventadas iban contra su propósito, y que lo mejor era encerrarse en un silencio absoluto sobre ciertos puntos; pero llegó a ser cada vez más evidente para ella que Pulkeria Alexandrovna sospechaba algo espantoso. Dunia sabía fijamente (su hermano se lo había contado) que su madre la oyó hablar en sueños la noche siguiente a su entrevista con Svidrigailoff. Las palabras que en el delirio se le escaparon a la joven, ¿no habrían derramado una luz siniestra en el espíritu de la pobre mujer? A menudo, después de días, y aun de semanas de continuo mutismo y de lágrimas silenciosas, se producía en la enferma una especie de exaltación histérica. Se ponía de repente a hablar alto, sin interrumpirse, de su hijo, de sus esperanzas y del porvenir... sus imaginaciones eran a veces muy extrañas. Se fingía ser de su opinión (quizá no era del todo engañoso este sentimiento); sin embargo, no cesaba de hablar.\"},{\"heading\":false,\"text\":\"La sentencia fué pronunciada cinco meses después de la confesión hecha por el criminal a Ilia Petrovitch. En cuanto fué posible, Razumikin visitó al condenado en la cárcel. Sonia le visitó también. Llegó al fin el momento de la separación. Dunia juró a su hermano que esta separación no sería eterna; Razumikin se expresó del mismo modo. El animoso joven tenía un proyecto firmemente formado en su espíritu; cuando ahorrase algún dinero, durante tres o cuatro años se trasladaría a Siberia, país en que tantas riquezas no esperan otra cosa, para ser puestas en circulación, que capitales y brazos. Allí se establecería, en la ciudad en que estuviese Rodia, y juntos comenzarían una nueva vida. Todos lloraban al decirse adiós. Desde hacía algunos días, Raskolnikoff se mostraba muy preocupado, multiplicaba las preguntas acerca de su madre, inquietándose continuamente por ella. Esta excesiva preocupación de su hermano daba pena a Dunia. Cuando el joven se hubo enterado con más detalles del estado enfermizo de Pulkeria Alexandrovna, se puso extremadamente sombrío. Con Sonia estaba siempre taciturno. Provista del dinero que Svidrigailoff le había entregado, la joven se hallaba dispuesta, desde hacía mucho tiempo, a acompañar el convoy de presos de que había de formar parte Raskolnikoff. Nunca había mediado una palabra sobre este particular entre ella y él; pero ambos sabían que sería así. En el momento de la última despedida, el condenado se sonrió de un modo extraño al oír hablar a su hermana y a Razumikin del próspero porvenir que se abriría para ellos después de su salida del presidio. Preveía que la enfermedad de su madre no tardaría en conducirla al sepulcro.\"},{\"heading\":false,\"text\":\"Dos meses después, Dunia se casó con Razumikin. Sus bodas fueron tranquilas y tristes. Entre los invitados se encontraron Porfirio Petrovitch y Zosimoff. Algún tiempo después, todo denotaba en Razumikin una resolución enérgica. Dunia creía ciegamente que realizaría todos sus designios, y no podía menos de creerlo, porque veía en él una voluntad de hierro. Comenzó por entrar de nuevo en la Universidad a fin de terminar sus estudios. Los dos esposos elaboraban sin cesar planes para el porvenir; tenían uno y otra la firme resolución de emigrar a Siberia en un plazo de cinco años. En tanto contaban con que Sonia los reemplazaría cerca del condenado...\"},{\"heading\":false,\"text\":\"Pulkeria Alexandrovna concedió, con alegría, la mano de su hija a Razumikin; pero después de este matrimonio, pareció más triste y preocupada. Para proporcionarle un momento agradable, Razumikin le contó la noble conducta de Raskolnikoff, a propósito del estudiante y de su anciano padre, y le refirió también cómo el año anterior Rodia había expuesto la vida para salvar a dos niños que estaban a punto de perecer en un incendio. Estos relatos exaltaron, hasta el más alto grado, el ya turbado espíritu de Pulkeria Alexandrovna. Desde entonces no hablaba más que de ello, y hasta en la calle refería tales hechos a los transeuntes, aunque la acompañaba siempre Dunia. En los ómnibus, en los almacenes, en todas partes en donde se encontraba un oyente benévolo, hablaba de su hijo, del artículo de su hijo, de la caridad de su hijo con un estudiante, de la valerosa abnegación de que había dado pruebas su hijo en un incendio, etc. Dunia no sabía cómo hacerla callar. Esta morbosa locuacidad no carecía de peligros: además de que agotaba las fuerzas de la pobre mujer, podía ocurrir que alguno, oyendo alabar de Raskolnikoff, se pusiese a hablar del proceso. Pulkeria Alexandrovna averiguó las señas de la mujer cuyos hijos habían sido salvados por el suyo, y quiso resueltamente ir a verlos. Finalmente, su exaltación llegó a los últimos límites. A veces se echaba de repente a llorar, y a veces tenía accesos de fiebre, durante los cuales deliraba. Una mañana declaró redondamente que, según sus cálculos, Rodia debía volver muy pronto, porque cuando se despidió de ella le había anunciado su vuelta en un plazo de nueve meses. Comenzó entonces a prepararlo todo en la casa, en atención a la próxima llegada de su hijo, destinándole su propia habitación; quitó el polvo a los muebles, fregó el suelo, cambió las cortinas, etc. Dunia estaba desolada, pero no decía nada, y hasta ayudaba a su madre en estas diversas ocupaciones. Después de un día lleno todo él de locas visiones, de sueños gozosos y de lágrimas, Pulkeria Alexandrovna se vió acometida de una fiebre alta y murió al cabo de quince días. Varias palabras pronunciadas por la enferma durante su delirio, hicieron creer que había casi adivinado el terrible secreto que con tanto trabajo trataron de ocultarle.\"},{\"heading\":false,\"text\":\"Por mucho tiempo ignoró Raskolnikoff la muerte de su madre, aunque por mediación de Sonia recibiese regularmente noticias de su familia. Cada mes enviaba la joven una carta dirigida a Razumikin, y cada mes se le respondía de San Petersburgo. Las cartas de Sonia parecieron en un principio, a Dunia y Razumikin, algo secas e insuficientes; pero más tarde comprendieron que era imposible escribirlas mejores, puesto que encontraban en ellas datos completos y precisos acerca de la situación de su desgraciado hermano. Sonia describía, de una manera muy sencilla y muy clara, la existencia de Raskolnikoff en la prisión. No hablaba de ella ni de sus propias esperanzas ni de sus conjeturas respecto al porvenir, ni de sus sentimientos personales. En vez de explicar el estado moral, la vida interior del condenado, se limitaba a citar hechos, es decir, las mismas palabras pronunciadas por él. Daba noticias detalladas acerca de su salud, decía qué deseos le había manifestado él, qué preguntas le había dirigido, qué encargos le había hecho durante sus entrevistas, etc.\"},{\"heading\":false,\"text\":\"Pero estos datos, por minuciosos que fuesen, no eran, empero, en los primeros tiempos sobre todo, muy consoladores. Dunia y su marido supieron, por la correspondencia de Sonia, que su hermano seguía siempre sombrío y taciturno. Cuando la joven le comunicaba noticias recibidas de San Petersburgo, apenas si prestaba atención; algunas veces se informaba de su madre, y cuando Sonia, viendo que el preso adivinaba la verdad, le hizo saber la muerte de Pulkeria Alexandrovna, observó con gran sorpresa que se había quedado poco menos que impasible. «Aunque parezca absorto en sí mismo y como extraño a todo lo que le rodea--escribía, entre otras cosas, Sonia--se hace cargo de su vida nueva, comprende muy bien su situación; ni espera nada mejor de aquí a largo tiempo, ni acaricia frívolas esperanzas, ni experimenta casi ningún asombro en este nuevo medio que tanto difiere del antiguo... Su salud es satisfactoria. Va al trabajo sin repugnancia y sin apresuramiento. Es casi indiferente a la comida; pero, excepto los domingos y los días de fiesta, esta nutrición es tan mala, que ha consentido en aceptar de mí algún dinero para procurársela todos los días. En cuanto a lo demás, me suplica que no me inquiete, porque, según asegura, le es desagradable que se ocupen de él.» «En la cárcel--se leía en otra carta--, está instalado con los otros presos; no he visitado el interior de la fortaleza, pero tengo motivos para creer que se está allí muy mal, muy estrechamente y en condiciones muy insalubres. Duerme en una cama de campaña, cubierto con una alfombra de fieltro, y no quiere otro lecho. Si rehusa hacer todo lo que podría proporcionarle su existencia material menos dura y menos grosera, no es, en lo más mínimo, en virtud de sus principios ni de una idea preconcebida, sino, sencillamente, por apatía, por indiferencia.» Sonia confesaba que, al principio, sobre todo, sus visitas, en vez de causar placer a Raskolnikoff, le producían una especie de irritación; no salía de su mutismo más que para decir groserías a la joven. Más tarde, es verdad, dichas visitas habían llegado a ser para él una costumbre, casi una necesidad, hasta el punto de que había estado muy triste cuando una indisposición de algunos días obligó a Sonia a interrumpirlas. Los días de fiesta se veían, ya en la puerta de la prisión, ya en el cuerpo de guardia, a donde se enviaba algunos minutos al prisionero, cuando la joven le hacía llamar. En tiempo ordinario, Sonia iba a buscarle al trabajo en los talleres, en las tejerías, en los tinglados establecidos a las orillas del Irtych. En lo tocante a ella, Sonia decía que había logrado crearse relaciones en su nueva residencia; que se ocupaba en coser, y que, no habiendo en la ciudad casi ninguna modista, se había hecho una buena clientela. Lo que callaba era que había atraído sobre Raskolnikoff el interés de la autoridad, y que, gracias a ella, se le dispensaba de los trabajos más penosos, etcétera. En fin, Razumikin y Dunia recibieron aviso de que Raskolnikoff esquivaba a todo el mundo; que sus compañeros de cadena no le querían; que permanecía silencioso durante horas enteras, y que, de día en día, su palidez era cada vez mayor. Dunia había notado ya cierta inquietud en las últimas cartas de Sonia, la cual no tardó en escribir diciendo que el condenado había caído gravemente enfermo, y que había sido llevado al hospital de la prisión...\"}]},{\"title\":\"sexta parte — capítulo II\",\"blocks\":[{\"heading\":false,\"text\":\"Estaba enfermo desde hacía algún tiempo; pero lo que había quebrantado sus fuerzas no era ni el horror de la prisión, ni el trabajo, ni la mala alimentación, ni la vergüenza de tener la cabeza rapada e ir vestido de harapos. ¡Oh! ¿qué le importaban a él tales tribulaciones y miserias? Lejos de ello, estaba contento de tener que trabajar. La fatiga física le producía algunas horas de sueño agradable, y, ¿qué significaba para él el rancho, aquella mala sopa de coles en que solía encontrar hasta escarabajos? En otro tiempo, siendo estudiante, se hubiera dado algunas veces por muy contento de tener tal comida. Sus vestidos eran de abrigo y a propósito para aquel género de vida; en cuanto a la cadena, apenas si sentía el peso. Quedaba la humillación de tener la cabeza afeitada y llevar el uniforme del presidio; pero, ¿ante quién habría de ruborizarse? ¿Ante Sonia? La joven tenía miedo de él; ¿cómo había de ruborizarse ante ella?\"},{\"heading\":false,\"text\":\"Sin embargo, le daba vergüenza de la misma Sonia; por esta razón se mostraba brutal y despreciativo en sus relaciones con la joven. Pero no procedía esta vergüenza ni de su cabeza rapada, ni de su cadena. Su orgullo había sido cruelmente herido, y Raskolnikoff estaba enfermo de esta herida, ¡Oh, qué feliz habría sido si hubiera podido acusarse a sí mismo! Entonces lo hubiera soportado todo, hasta la vergüenza y el deshonor. Pero en vano se examinaba severamente; su conciencia endurecida no encontraba en su pasado ninguna falta que pudiera ocasionarle grandes remordimientos. Solamente se echaba en cara haber fracasado, cosa que podía ocurrir a todo el mundo. Lo que le humillaba, era verse él, Raskolnikoff, perdido tontamente, sin esperanza de rehabilitación, por una sentencia del ciego destino, y debía someterse, resignarse al absurdo de esa sentencia, si quería encontrar un poco de calma.\"},{\"heading\":false,\"text\":\"Una inquietud sin objeto y sin fin en el presente, un sacrificio continuo y estéril en el porvenir; esto es lo que le quedaba en la tierra. Vano consuelo para él decirse que, dentro de ocho años, no tendría más que treinta y dos, y que, en esta edad, podría aún recomenzar la vida. ¿Para qué vivir? ¿Con qué objeto? ¿Con qué fin? ¿Vivir para existir? En todo momento había estado pronto a dar su existencia por una idea, por una esperanza, por un capricho. Había hecho siempre poco caso de la existencia pura y sencilla; siempre había mirado más allá. Quizá la fuerza sólo de los deseos le había hecho creer en otro tiempo que era uno de esos hombres a quienes les está permitido más que a los otros.\"},{\"heading\":false,\"text\":\"Menos mal si el destino le hubiese enviado el arrepentimiento, el punzante arrepentimiento que rompe el corazón, que quita el sueño; el arrepentimiento cuyos tormentos son tales, que el hombre se ahoga o se ahorca para librarse de ellos. ¡Oh! Los hubiera acogido con felicidad. Sufrir y llorar es todavía vivir; pero no se arrepentía de su crimen.\"},{\"heading\":false,\"text\":\"Por lo menos hubiera podido echarse en cara su tontería, como se había reprochado en otro tiempo las acciones estúpidas y odiosas que le habían conducido a presidio. Pero ahora, que en el vagar de la prisión reflexionaba de nuevo sobre toda su conducta pasada, no la encontraba tan odiosa ni tan estúpida como le había parecido en otro tiempo.\"},{\"heading\":false,\"text\":\"«¿Es que--pensaba--mi idea era más tonta que las otras ideas y teorías que batallan en el mundo desde que el mundo existe? Basta considerar las cosas desde un punto de vista amplio, independiente, libre de los prejuicios del día, y, entonces ciertamente, mi idea no parecerá tan extraña. ¡Oh espíritus sedicentes, libres de prejuicios, filósofos de cinco kopeks! ¿por qué os detenéis a la mitad del camino?\"},{\"heading\":false,\"text\":\"»¿Y por qué les parece tan fea mi conducta?--se preguntaba--. ¿Por qué es un crimen? ¿Qué significa la palabra crimen? Mi conciencia está tranquila. Sin duda he cometido una acción ilícita, he violado la letra de la ley y he vertido sangre... Pues bien, tomad mi cabeza. Cierto es que, en este caso, aun los bienhechores de la humanidad, de aquellos a quienes el poder no ha venido por herencia, sino que se han apoderado de él a viva fuerza, hubieran debido desde sus comienzos ser entregados al suplicio. Pero estas personas han ido hasta el fin, y esto es lo que las justifica, en tanto que yo no he sabido continuar; por consiguiente, no tenía el derecho de comenzar.»\"},{\"heading\":false,\"text\":\"Unicamente se reconocía un error: el de haber cometido la debilidad de ir a denunciarse.\"},{\"heading\":false,\"text\":\"Pero un pensamiento le atormentaba también: ¿por qué no se había matado? ¿Por qué, más bien que arrojarse al agua, había preferido entregarse a la policía? ¿Es el amor de la vida un sentimiento tan difícil de vencer? Svidrigailoff, sin embargo, había triunfado de él.\"},{\"heading\":false,\"text\":\"Se planteaba dolorosamente esta cuestión y no podía comprender que, cuando enfrente del Neva, pensaba en el suicidio, quizá era que presentía en sí y en sus convicciones un error profundo. No comprendía que este pensamiento pudiese contener en germen un nuevo concepto de la vida, que pudiese ser el preludio de una revolución en su existencia, la prenda de su resurrección.\"},{\"heading\":false,\"text\":\"Admitía más bien que había cedido entonces por cobardía y defecto de carácter a la fuerza brutal del instinto. El espectáculo ofrecido por sus compañeros de presidio le asombraba. ¡Cómo amaban todos ellos la vida! ¡Cómo la apreciaban! Parecía a Raskolnikoff que este sentimiento era más vivo en el preso que en el hombre libre. ¡Qué terribles sufrimientos padecían aquellos desgraciados, los vagabundos, por ejemplo! ¿Era posible que un rayo de sol, un bosque sombrío, una fuente fresca, tuviesen tanto valor a sus ojos? A medida que los fué estudiando, descubrió hechos aún más inexplicables.\"},{\"heading\":false,\"text\":\"En el penal, en el ambiente que le rodeaba, se le escapaban, sin duda, muchas cosas; además, no quería fijar su atención en nada. Vivía, por decirlo así, sin levantar jamás los ojos, porque encontraba insoportable el mirar en su derredor. Pero, a la larga, muchas circunstancias le chocaron, e involuntariamente comenzó a advertir lo que ni siquiera había sospechado antes. En general, lo que más le asombraba, era el abismo espantoso, infranqueable, que existía entre él y toda aquella gente. Hubiérase dicho que pertenecían él y ellos a naciones diferentes. Se miraban con desconfianza y hostilidad recíprocas. Sabía y comprendía las causas generales de este fenómeno; pero, hasta entonces, jamás las había supuesto tan fuertes ni tan profundas. Además de los criminales de derecho común, había en la fortaleza polacos enviados a Siberia por delitos políticos. Estos últimos consideraban como brutos a sus compañeros de cadena, para los cuales no tenían más que desprecio; pero Raskolnikoff no participaba de esta manera de ver; advertíase muy bien que, bajo muchos aspectos, aquellos brutos eran más inteligentes que los mismos polacos. Había allí también rusos (un antiguo oficial y dos seminaristas), que despreciaban a la plebe de la prisión. Raskolnikoff advertía igualmente el error de ellos.\"},{\"heading\":false,\"text\":\"En cuanto a él, no se le amaba, se le esquivaba; hasta se acabó por odiarle; ¿por qué? Lo ignoraba. Los malhechores, cien veces más culpables que él, le despreciaban y hacíanle objeto de sus burlas; su crimen era el blanco de sus sarcasmos.\"},{\"heading\":false,\"text\":\"--Tú, tú no eres un _barin_--le decían--. ¿Por qué has asesinado a hachazos? Eso no es propio de un _barin_.\"},{\"heading\":false,\"text\":\"En la segunda semana de la gran Cuaresma, tuvo que asistir a las funciones religiosas con todos los de su cuadra. Fué a la iglesia y oró como los otros. Un día, sin que se supiese por qué motivo, sus compañeros estuvieron a punto de hacerle una mala partida. De repente se vió asaltado por ellos.\"},{\"heading\":false,\"text\":\"--Tú eres un ateo.\"},{\"heading\":false,\"text\":\"--Tú no crees en Dios--gritaban los forzados.\"},{\"heading\":false,\"text\":\"--Hay que matarle.\"},{\"heading\":false,\"text\":\"Jamás él les había hablado ni de Dios, ni de la religión, y, sin embargo, querían matarle por ateo. Raskolnikoff no les respondió ni una palabra. Un forzado, en el colmo de la exasperación, se lanzó sobre él; el joven, tranquilo y silencioso, le esperó sin pestañear, sin que ningún músculo de su rostro temblase. Un cabo de varas se interpuso a tiempo entre él y el asesino. Un instante más, y hubiera corrido la sangre.\"},{\"heading\":false,\"text\":\"Existía otra cuestión que no acertaba a resolver: ¿por qué amaban todos tanto a Sonia? La joven no trataba de ganarse sus voluntades; no tenían a menudo ocasión de encontrarla. Sólo la veían alguna vez que otra en los patios o en el taller, cuando venía a pasar algunos minutos al lado del preso. Sin embargo, todos la conocían. No ignoraban que le había seguido; sabían cómo vivía y dónde estaba alojada. La joven no les daba dinero, apenas les prestaba, propiamente hablando, servicio alguno; solamente una vez, por Nochebuena, hizo un regalo a toda la prisión: pasteles y _kalatschi_[20]; pero, poco a poco, entre ellos y Sonia se establecieron ciertas relaciones más íntimas. Escribía, por encargo de ellos, cartas a sus familias, y las ponía en el correo. Cuando sus parientes venían a la ciudad, era en manos de Sonia en las que, por recomendación de los mismos forzados, dejaban los objetos y hasta el dinero destinado a ellos. Las mujeres y las amantes de los detenidos la conocían e iban a su casa. Cuando visitaba a Raskolnikoff en el trabajo, o en medio de sus compañeros, o encontraba un grupo de presos que se dirigían a la obra, todos se quitaban los gorros y se inclinaban saludándola:\"},{\"heading\":false,\"text\":\"[20] Panecillos blancos.\"},{\"heading\":false,\"text\":\"--_Matuchka_, Sofía Semenovna, tú eres nuestra tierna y querida madre--decían aquellos presidiarios brutales a la pequeña y débil criatura.\"},{\"heading\":false,\"text\":\"Ella les saludaba sonriendo, y a todos les agradaba su sonrisa. Amaban hasta su manera de andar, y se volvían para seguirla con los ojos cuando se alejaba. ¡Y qué alabanzas le dirigían! Hasta la elogiaban por ser pequeñita de cuerpo; no sabían cómo ensalzarla, y aun la consultaban en sus enfermedades.\"},{\"heading\":false,\"text\":\"Raskolnikoff pasó en el hospital todo el fin de la Cuaresma y la semana de Pascuas. Al recobrar la salud se acordó de los sueños que había tenido en su delirio. Le parecía ver el mundo entero asolado por un azote terrible y sin precedentes, que, viniendo del fondo de Asia, había caído sobre Europa. Todos debían perecer, excepto un número reducidísimo de privilegiados. Microbios de una nueva especie, seres microscópicos, se introducían en los cuerpos humanos. Pero estos seres estaban dotados de inteligencia y de voluntad. Los individuos atacados por ellos se ponían al instante locos furiosos. Sin embargo, ¡cosa extraña! nunca hombre alguno se habría creído tan sabio, tan seguramente en posesión de la verdad, como se creían aquellos infortunados. Jamás nadie había tenido más confianza en la infalibilidad de sus juicios, en la solidez de sus conclusiones científicas y de sus principios morales. Aldeas, ciudades, pueblos enteros, estaban atacados de este mal y perdían la razón. Estaban todos agitados y fuera de estado de comprenderse entre ellos. Cada cual creía poseer solo la verdad, y al observar a sus semejantes se entristecía, se golpeaba el pecho, lloraba y se retorcía las manos. No podían entenderse acerca del bien y del mal; no se sabía qué condenar ni qué absolver. Los hombres se mataban entre sí, bajo la impulsión de una cólera ciega. Se reunían formando grandes ejércitos; pero una vez comenzada la campaña, la división aparecía bruscamente en las tropas, las filas se rompían, los guerreros se degollaban y se devoraban. En las ciudades sonaba a todas horas el toque de rebato; mas, ¿para qué esta alarma? ¿Con qué propósito? Nadie lo sabía y todo el mundo estaba inquieto. Se abandonaban los más ordinarios oficios, porque cada cual proponía sus ideas, sus reformas, y nadie se ponía de acuerdo; la agricultura estaba abandonada; aquí y allá la gente se reunía en grupos, entendiéndose para una acción común y jurando no separarse; pero un instante después olvidaban la resolución que habían tomado, y comenzaban a acusarse, a pegarse y a matarse. Los incendios y el hambre contemplaban este triste cuadro. Hombres y cosas, todo perecía. Aquel azote se extendía más y más. Solamente podían salvarse algunos hombres puros, predestinados a rehacer el género humano, a renovar la vida y a purificar la tierra; pero nadie veía a estos hombres, nadie oía sus palabras ni su voz.\"},{\"heading\":false,\"text\":\"Aquellos sueños absurdos dejaban en el ánimo de Raskolnikoff una impresión penosa, que tardó mucho en borrarse. Llegó la segunda semana después de Pascuas; el tiempo era templado, sereno, verdaderamente primaveral; se abrieron las ventanas del hospital (ventanas enrejadas, bajo las cuales se paseaba un centinela). Durante toda la enfermedad de Raskolnikoff, Sonia no había podido hacerle más que dos visitas. Cada vez era preciso pedir una autorización, difícil de obtener; pero, a menudo, sobre todo a la caída de la tarde, se dirigía al patio del hospital, y durante un minuto estaba allí mirando a las ventanas. Un día por la tarde, el recluso, ya casi enteramente curado, se había dormido; al despertar se aproximó por casualidad a la reja, y vió a Sonia que, en pie, cerca de la puerta del hospital, parecía esperar algo. Al verla sintió como un golpe en el corazón, estremecióse convulsivamente y se alejó rápidamente de la ventana. Al día siguiente Sonia no vino, al otro tampoco. Raskolnikoff advirtió que la esperaba con ansiedad. Finalmente salió del hospital. Cuando volvió a la prisión, sus compañeros le dijeron que Sonia estaba mala y que no podía salir de casa.\"},{\"heading\":false,\"text\":\"El joven se inquietó sobremanera, y envió a buscar noticias de la muchacha. Supo en seguida que la enfermedad no era peligrosa. Por su parte Sonia, sabiendo que Raskolnikoff se preocupaba tanto de su salud, le escribió con lápiz una carta, en que le informaba que estaba mucho mejor, que había pescado un ligero enfriamiento, y que no tardaría en ir a verle al trabajo. Al leer esta carta, el corazón de Raskolnikoff latió con violencia.\"},{\"heading\":false,\"text\":\"El día era sereno y templado. A las seis de la mañana iba el joven a trabajar a la orilla del río, en donde se había establecido, bajo cobertizo, un horno de cocer alabastro. Unicamente tres obreros fueron enviados allí. Uno de ellos, acompañado de un capataz, fué a buscar un instrumento a la fortaleza; otro comenzó a calentar el horno. Raskolnikoff salió del cobertizo, se sentó en un banco de madera, y se puso a contemplar el río ancho y desierto. Desde la elevada orilla se descubría una gran extensión de terreno. A lo lejos, del otro lado de Irtych, resonaban cantos cuyos vagos ecos llegaban a los oídos del presidiario. Allá, en la inmensa estepa inundada de sol, aparecían como puntitos negros las tiendas de los nómadas. Aquello era la libertad; allí vivían otros hombres, que no se parecían en nada a los que le rodeaban; allá parecía que el tiempo no había marchado desde el tiempo de Abraham y sus rebaños. Raskolnikoff soñaba con los ojos fijos en aquella lejana visión; no pensaba en nada, aunque le oprimía una especie de inquietud.\"},{\"heading\":false,\"text\":\"De repente se encontró en presencia de Sonia; la joven se le aproximó sin ruido y se sentó a su lado. Como empezaba a dejarse sentir el fresco de la mañana, Sonia llevaba su pobre y viejo _burnus_ y su pañuelo verde. Su rostro delgado y pálido daba testimonio de su reciente enfermedad. Al acercarse al preso, se sonrió con expresión amable y alegre, y con la timidez de costumbre le tendió la mano.\"},{\"heading\":false,\"text\":\"Siempre se la ofrecía tímidamente y algunas veces no se atrevía a dársela, como si temiese verla rechazada; parecíale que ella se la estrechaba con repugnancia, y siempre tenía el aire huraño cuando la joven se acercaba; a veces, ésta no podía obtener de él una palabra. Había días en que temblaba ante él y se retiraba profundamente afligida; pero en esta ocasión se estrecharon durante largo rato las manos. Raskolnikoff miró rápidamente a Sonia. Nada dijo y bajó los ojos. Estaban solos. El cabo de varas se había alejado momentáneamente.\"},{\"heading\":false,\"text\":\"De pronto, y sin que el presidiario supiese cómo había ocurrido aquello, una fuerza irresistible le arrojó a los pies de la joven y lloró abrazándole las rodillas. En el primer momento, Sonia, asustada, se puso intensamente pálida, se levantó con presteza, y temblorosa miró a Raskolnikoff; pero a él le bastó esta mirada para comprenderlo todo. En los ojos de la joven parecía resplandecer una felicidad inmensa; no había para ella duda de que Raskolnikoff la amaba con amor infinito. Había llegado, por fin, este momento...\"},{\"heading\":false,\"text\":\"Quisieron hablar y no pudieron. Tenían lágrimas en los ojos. Ambos estaban pálidos y demacrados; pero sobre sus rostros enfermizos brillaba ya la aurora de un renacimiento completo. El amor les regeneraba; el corazón del uno encerraba una inagotable fuente de vida para el corazón del otro.\"},{\"heading\":false,\"text\":\"Resolvieron esperar, tener paciencia. Les quedaban siete años que pasar en Siberia; ¡qué sufrimientos intolerables y qué infinita felicidad había de llenar para ellos aquel lapso de tiempo! Pero Raskolnikoff había resucitado, lo sabía y lo sentía en todo su ser, y Sonia no vivía más que para la vida de su amado.\"},{\"heading\":false,\"text\":\"Por la noche, después que se hubo recogido a los reclusos, el joven se acostó en su camastro, y pensó en ella. Hasta le parecía que aquel día los presos, sus antiguos enemigos, le habían mirado con otros ojos. Les había dirigido primero la palabra y le habían respondido con afabilidad; se acordaba de esto ahora, le parecía natural. ¿Acaso no debía cambiar todo?\"},{\"heading\":false,\"text\":\"Pensaba en ella. Se acordaba de los disgustos con que continuamente la había atormentado; veía con el pensamiento la carita pálida y delgada de Sonia; pero estos recuerdos eran un remordimiento para él. Comprendía con qué amor infinito iba a rescatar en adelante lo que había sufrido Sonia.\"},{\"heading\":false,\"text\":\"Sí. ¿Qué significaban para él todas las miserias del pasado? En aquel primer día gozoso, de vuelta a la vida, todo, aun su crimen y su condena, y su relegación a Siberia, todo se le presentaba como un hecho extraño; casi dudaba de que todo aquello hubiera ocurrido realmente. Aquella noche se sintió incapaz de reflexionar detenidamente, de concentrar su atención en un objeto cualquiera, de resolver una cuestión con conocimiento de causa; sólo tenía sensaciones. La vida había substituído en él al razonamiento.\"},{\"heading\":false,\"text\":\"Tenía el _Evangelio_ debajo de la almohada y lo tomó maquinalmente. Aquel libro pertenecía a Sonia. En él fué donde la joven le había leído la resurrección de Lázaro. Al principio de su cautividad esperaba una verdadera persecución religiosa por parte de la joven. Creía que le asediaría constantemente con el _Evangelio_; pero, con gran asombro suyo, ni una sola vez hizo recaer la conversación sobre este punto, ni una sola vez le ofreció aquel libro; él mismo fué quien lo pidió poco antes de su enfermedad, y ella se lo trajo sin decir una palabra. Raskolnikoff hasta entonces no lo había abierto.\"},{\"heading\":false,\"text\":\"Ahora tampoco lo abrió; pero un pensamiento cruzó por su mente. «Sus convicciones, ¿pueden ser, al presente, las mías? ¿Puedo, yo, por lo menos, tener otros sentimientos, otras tendencias que ella?»\"},{\"heading\":false,\"text\":\"Durante todo este día Sonia estuvo también muy agitada, y por la noche tuvo una recaída en la enfermedad; pero era tan feliz, y aquella felicidad era para ella una sorpresa tan grande, que casi le causaba espanto. ¡Siete años _solamente_! En la embriaguez de las primeras horas faltó poco para que ambos no considerasen estos siete años como siete días. Raskolnikoff ignoraba que la nueva vida no le sería dada de balde y que tendría que conquistarla al precio de penosos esfuerzos.\"},{\"heading\":false,\"text\":\"Pero comienza aquí una segunda historia. La historia de la lenta renovación de un hombre, de su regeneración progresiva, de su paso gradual de una vida a otra... Esto podría ser el asunto de un nuevo relato; el que hemos querido ofrecer al lector, está terminado.\"}]}]', 'es', 'https://www.gutenberg.org/ebooks/61851', '{}');
INSERT INTO libros (id, titulo, autor, genero, cover, secciones, idioma, fuente, introducciones) VALUES (62359, 'El anacronópete y otros relatos', 'Enrique Gaspar', 'ciencia-ficcion', 'https://www.gutenberg.org/cache/epub/62359/pg62359.cover.medium.jpg', '[{\"title\":\"El anacronópete — capítulo primero\",\"blocks\":[{\"heading\":false,\"text\":\"En el que se prueba que ADELANTE no es la divisa del progreso\"},{\"heading\":false,\"text\":\"París, foco de la animación, centro del movimiento, núcleo del bullicio, presentaba aquel día un aspecto insólito. No era el ordenado desfile de nacionales y extranjeros dirigiéndose a la exposición del Campo de Marte ya para satisfacer la profana curiosidad, ya para estudiar técnicamente los progresos de la ciencia y de la industria. Mucho menos reflejaban aquellas fisonomías la alegre satisfacción con que los habitantes de la antigua Lutecia corren anualmente a ver disputar el gran premio en el concurso hípico destrozando palabras inglesas y luciendo trajes y trenes, capaz cada uno de satisfacer el precio del _handicap_ y de saldar todos juntos la deuda flotante de algún Estado.\"},{\"heading\":false,\"text\":\"Verdad es que aunque época de certamen universal, pues desfilaba el año de 1878, no lo era de carreras, pues no iban transcurridos más que diez días del mes de julio. Además no había vaivén; es decir que no acontecía lo que en aquellos casos, que la gente que se divierte se cruza en opuesta dirección con la que trabaja o huelga. Todos seguían el mismo rumbo llevando impresa en la mirada la huella del asombro. Las tiendas estaban cerradas, los trenes de los cuatro puntos cardinales vomitaban viajeros que asaltando ómnibus y _fiacres_ no tenían más que un grito: «¡Al Trocadero!»\"},{\"heading\":false,\"text\":\"Los vaporcitos del Sena, el ferrocarril de cintura, el _tram-way_ americano, cuantos medios de locomoción en fin existen en la Babilonia moderna, multiplicaban su actividad hacia aquel punto atractivo del general deseo. Aunque el calor era sofocante como de canícula, dos ríos humanos se desbordaban por las aceras de las calles, pues, exceptuando los vehículos de propiedad, París con sus catorce mil carruajes de alquiler, no podía transportar arriba de doscientas ochenta mil personas, concediendo a cada uno diez carreras con dos plazas; y como la población se elevaba a dos millones, en virtud del espectáculo del día a que todos querían asistir, resultaba que un millón y setecientos veinte mil individuos tenían que ir a pie.\"},{\"heading\":false,\"text\":\"El Campo de Marte y el Trocadero, teatro de aquella representación única, habían sido invadidos desde el amanecer por la impaciente multitud que, no contando con billete para la conferencia que en el salón de festejos del palacio debía celebrarse a las diez de la mañana, se contentaba con presenciar la segunda parte, mediante el valor de la entrada, en el área de la Exposición. Los que ya no tuvieron acceso a ella, asaltaron los puentes y las avenidas. Los más perezosos o menos afortunados se vieron reducidos a diseminarse por las alturas de Montmartre, los campanarios de las iglesias, las colinas del Bosque y las prominencias de los Parques. Tejados, obeliscos, columnas, arcos conmemorativos, observatorios, pozos artesianos, cúpulas, pararrayos, cuanto ofrecía una elevación había sido adquirido a la puja; y los almacenes quedaron exhaustos de paraguas, sombrillas, sombreros de paja, abanicos y bebidas refrigerantes para combatir al sol.\"},{\"heading\":false,\"text\":\"¿Qué ocurría en París? Hay que ser justos. Ese pueblo que así se admira a sí propio colocando sus medianías sobre pedestales para que el mundo los tome por genios, como se divierte consigo mismo caricaturándose en sus infinitos ratos de ocio, se conmovía esta vez con sobrada razón. La ciencia acababa de dar un paso que iba a cambiar radicalmente la manera de ser de la humanidad. Un nombre, hasta entonces oscuro y español por añadidura, venía a borrar con los fulgores de su brillantez el recuerdo de las primeras eminencias del mundo sabio. Y en efecto. ¿Qué había hecho Fulton? Aplicar a la locomoción marítima los experimentos de Watt o de Papin a fin de que los buques caminasen con mayor rapidez venciendo más fácilmente la resistencia de las olas con su fuerza impulsiva; pero salir en lunes de un puerto para llegar en martes a otro en que antes, a la vela y viento en popa, no hubiera sido posible fondear hasta el sábado, no puede decirse que fuera ganar tiempo sino perder menos a lo sumo. Stephenson, inventando la locomotora, le hacía devorar espacio sobre dos nervios de metal; pero recorrer mayor distancia en menos minutos era siempre ir en busca del mañana por la senda del hoy. Lo mismo digo de Morse: transmitir el pensamiento por un alambre merced a un agente eléctrico, no destruye el que, aunque el fluido sea capaz de dar cuatro veces la vuelta al orbe terráqueo en un segundo, la idea tarde en volver a su punto de partida en cada revolución sobre la línea equinoccial la duocentésimo-cuadragésima parte de un minuto. Es decir que el resultado es fatalmente posterior en la noción del tiempo. Además, el no poderse prescindir de los conductores hace gráfica la definición que del telégrafo eléctrico daba en esta forma un individuo: «Perro muy largo al que se tira de la cola en Madrid y ladra en Moscú.»\"},{\"heading\":false,\"text\":\"Las hipótesis del famoso Julio Verne tenidas por maravillosas, eran verdaderos juguetes de niño ante la magnitud del invento real del modesto zaragozano vecino de la Corte de las Españas. Bajar al centro de la tierra es cuestión de abrir un orificio por donde verificar el descenso; imitar a los habitantes de Ergasteria que muchos siglos antes de la era cristiana, ya penetraron en los abismos del Laurium para desenterrar el plomo argentífero. El trayecto era más corto; pero la carretera la misma. Navegar en los aires por la ingeniosa teoría del soplete, no ofrece otra ventaja que reducir la dirección a la voluntad del aereonauta suprimiendo la maroma con que en la batalla de Fleurus hacía transportar Jourdan los Montgolfier para descubrir la posición del enemigo. Ir al polo esperando el deshielo es obra de pura paciencia; copia servil aunque sabia de esas personas que, para hacer compras en un almacén, aguardan a que la tienda esté en liquidación. Por lo que al Nautilus respecta, mucho antes que Verne ya había hecho una prueba felicísima con el _Ictíneo_ nuestro compatriota Monturiol. Para relatarnos lo que existe en el fondo de los mares basta reunir un congreso de buzos. Y sobre todo (perdón si me repito) que arrancar en lunes del terreno de aluvión para llegar en martes al eoceno, en miércoles al permeano y concluir la semana en el mar de fuego; trasladarse en veinte horas desde Francia al Senegal por la vía aérea; o alcanzar por la submarina el fin de un viaje más tarde o más temprano, pero siempre _después_, encierra una idea de posterioridad que hace monótona la misión de la ciencia, corriendo invariablemente tras el mañana como si el ayer le fuese conocido.\"},{\"heading\":false,\"text\":\"El mundo es la casa de la humanidad, cuyos habitantes al irse multiplicando, van añadiendo pisos a la fábrica con el fin de estar con más holgura; pero sin cuidarse de estudiar los cimientos del edificio, para cerciorarse de que podrá resistir el peso abrumador que le echan encima. Cuando tan desfigurado vemos media hora después el hecho de que hemos sido testigos treinta minutos antes ¿podemos confiar ciegamente en los relatos que la historia nos hace de los tiempos primitivos sobre los que fundamos nuestra conducta por venir? Si por una serie de deducciones Boucher de Perthes creyó probar la existencia del hombre fósil, ¿no es posible que el fémur que él tomó por humano perteneciera en la escala zoológica a algún congénere de la montura del escudero de don Quijote? El pasado nos es absolutamente desconocido. Las ciencias retrospectivas al estudiarlo, proceden casi por inducción, y mientras no tengamos conciencia del ayer, es inútil que divaguemos sobre el mañana. Antes que ir a la negación por las hipótesis del futuro, aprendamos a creer en Dios tocando de cerca los maravillosos orígenes de su colosal obra de arquitectura.\"},{\"heading\":false,\"text\":\"Tales eran los principios filosóficos del doctor en ciencias exactas, físicas y naturales don Sindulfo García, y su aplicación el espectáculo a que aquel pueblo, ávido de emociones, concurría en masa con la ansiedad y la duda que necesariamente debía despertar en él lo que, a pesar de llamarse París el cerebro del mundo, no cabía en su cabeza.\"},{\"heading\":false,\"text\":\"--Pero, diga usted, señor capitán --preguntaba a uno de húsares de Pavía un caballero que con diecinueve individuos más se dirigía en ómnibus al sitio de la experiencia--. Usted como español debe estar enterado del mecanismo del Anacronópete.\"},{\"heading\":false,\"text\":\"--Dispense usted --respondió el interpelado--: Yo sé batirme contra los enemigos de mi patria; ser comedido con los hombres, galante con las señoras; conozco la disciplina, la táctica y la estrategia; pero en punto a navegar por el aire solo he aprendido a ser manteado en el colegio cuando no tenía la petaca bastante repleta para abastecer a mis condiscípulos.\"},{\"heading\":false,\"text\":\"--Con todo --insistía el preguntón--. A mí se me figura que en calidad de compatriota del sabio inventor del aparato, debe usted poseer nociones más exactas de él que un extranjero.\"},{\"heading\":false,\"text\":\"--Me honro con el título de español y soy además sobrino del señor García; pero no tengo más luces sobre el asunto que cualquier otro.\"},{\"heading\":false,\"text\":\"La noticia del parentesco del capitán con el coloso científico, redobló la curiosidad de los viajeros, que empezaron a querer encontrar en él huellas de su tío, como en las desiertas llanuras de Maratón o entre los viñedos de los campos cataláunicos buscamos las pisadas de Milcíades o el casco del corcel de Atila. Las mujeres preguntaban si don Sindulfo era casado; los hombres si tenía alguna condecoración, y todos si era pariente de Frascuelo.\"},{\"heading\":false,\"text\":\"--Pero, en resumidas cuentas, ¿qué se propone? --decía uno.\"},{\"heading\":false,\"text\":\"--Lo que estamos hartos de hacer los franceses --exclamaba un patriota exaltado--. Viajar por los aires.\"},{\"heading\":false,\"text\":\"--Sí; mas con dirección fija y con una velocidad vertiginosa --argüía prudentemente un guardia nacional reparando que el húsar echaba mano del sable sin más intención que la de colocárselo a su gusto.\"},{\"heading\":false,\"text\":\"--No niego --objetaba un cuarto-- que es maravilla y grande surcar a medida del deseo las corrientes atmosféricas; pero esto más tarde o más temprano hubiera acabado por hacerse. Lo que no concibe la inteligencia humana, es que con ese vehículo pueda el hombre retrogradar en el tiempo saliendo _hoy_ de París después de comer en Véfour para llegar _ayer_ al monasterio de Yuste y tomar chocolate con el emperador Carlos V.\"},{\"heading\":false,\"text\":\"--Eso es imposible --gritaron todos.\"},{\"heading\":false,\"text\":\"--Para nosotros los ignorantes --prosiguió el que hacía uso de la palabra--. No así para la ciencia que ha sancionado la invención en el congreso último. De todos modos, pronto saldremos de dudas. El señor García parte hoy en su Anacronópete para el caos, de donde se propone regresar dentro de un mes trayendo las pruebas de su expedición fabulosa.\"},{\"heading\":false,\"text\":\"--Apuesto a que el inventor es un bonapartista que quiere poner de nuevo sobre el trono de Francia al traidor de Sedán --vociferaba el patriota.\"},{\"heading\":false,\"text\":\"--O traernos el Terror con Robespierre --decía apretando los puños un partidario de la causa legitimista.\"},{\"heading\":false,\"text\":\"--Poco a poco --argumentaba un sensato--. Si el Anacronópete conduce a deshacer lo hecho, a mí me parece que debemos felicitarnos porque eso nos permite reparar nuestras faltas.\"},{\"heading\":false,\"text\":\"--Tiene usted razón --clamaba empotrado en un testero del coche un marido cansado de su mujer--. En cuanto se abra la línea al público, tomo yo un billete para la víspera de mi boda.\"},{\"heading\":false,\"text\":\"Celebrando estaban aún todos la ocurrencia, cuando el ómnibus (no sin gran riesgo de aplastar a la apiñada muchedumbre) se paró en la cabeza del puente; y, apeándose, cada cual trató de abrirse paso como pudo para dirigirse a su destino.\"},{\"heading\":false,\"text\":\"Parece ficción lo que acabamos de oír, y sin embargo nada hay más positivo. El doctor don Sindulfo García se aprestaba a hacer el experimento práctico de la resolución del más arduo problema que hasta hoy registran los anales científicos: viajar hacia atrás en el tiempo.\"},{\"heading\":false,\"text\":\"¿Qué análisis había hecho de él? ¿A qué clase de cuerpos pertenecía, lo que hasta hoy era una idea abstracta, que así podía someterse a la descomposición? ¿De qué agentes se valía para ello? ¿Qué colosal sistema era ese con que amenazaba llegar al descubrimiento de la verdad retrogradando, en un siglo que busca sus ideales en el mañana y que acepta el «adelante» como fórmula del progreso?\"},{\"heading\":false,\"text\":\"El capítulo siguiente nos lo dirá.\"}]},{\"title\":\"El anacronópete — capítulo ii\",\"blocks\":[{\"heading\":false,\"text\":\"Una conferencia al alcance de todos\"},{\"heading\":false,\"text\":\"Componíase el espectáculo de dos partes. En la primera el sabio español se despedía de sus colegas, de las autoridades y del público de París con una conferencia dada en el palacio del Trocadero, en la que, supliendo el tecnicismo con demostraciones vulgares, se proponía hacer comprensible a los menos versados en ciencias, los principios fundamentales de su invención. Formaba la segunda la elevación del monstruoso aparato desde el Campo de Marte hasta la zona atmosférica en que debía realizarse el viaje. Para ser testigo presencial de la última, bastaba haber satisfecho la cuota de entrada en el recinto de la exposición, trepar a las eminencias o diseminarse por las llanuras en espacio abierto; y es lo que, como hemos visto, hicieron las masas desde que empezó a alborear, poniendo a prueba la prudencia y los puños de la gendarmería que al fin logró evitar una irrupción en el palacio de la Industria. Pocos, relativamente, eran los escogidos entre los muchos que alegaban derecho a oír la palabra del doctor. El salón de fiestas, aunque espacioso, no bastaba a contener tanta gente. Ninguno de los espectadores seguía el tratamiento del _anti-fat_, y sin embargo diríase que todos habían enflaquecido, pues en cada asiento cabía por lo menos persona y media. Las entradas estaban obstruidas y los pasillos cuajados de esa multitud que aguarda paciente la ocasión de avanzar un paso, sabiendo que no ha de llegar nunca a la meta.\"},{\"heading\":false,\"text\":\"Los presidentes de la república, de los cuerpos colegisladores y del gabinete; el cuerpo diplomático, las comisiones de los institutos y academias, de las corporaciones sabias y del ejército alternaban, luciendo sus uniformes sembrados de placas y cintas, con el modesto sacerdote sin más cruz que la del Gólgota destacada sobre el fondo negro o morado de su túnica talar. Algunos fracs, aunque pocos, pues en Francia raro es el que no tiene uniforme, asomaban como con vergüenza su condición civil entre océanos de seda, cascadas de blondas, montes de brillantes y nubes de cabellos, negras unas como de tempestad, rubias otras como estratos heridos por el sol poniente y casi ninguna del color que anuncia la nieve en el invierno de la vida: que mujer y vieja va siendo ya cosa incompatible en la patria de Violet y de Pinaud.\"},{\"heading\":false,\"text\":\"Por fin sonó la hora: una ondulación de curiosidad vibró en el recinto y la puerta, abierta de par en par por dos ujieres, dio paso a la comisión científica, a la derecha de cuyo presidente caminaba el héroe con la modestia propia del talento impresa en el semblante. Todo en él era vulgar. Su nombre más que de sabio parecía de barba de sainete. Su apellido no estaba ligado por ninguna partícula a esas hojas patronímicas que, como Paredes, o Córdoba, prestan frondosidad a los árboles genealógicos e impiden la falta de respeto con que un vástago ilustre de los García, la Malibrán, es nombrada en el mundo del arte cual pudiera serlo la Bernaola en el de los criminales célebres. Llevaba sus cincuenta años, no con el soberbio orgullo del titán aportando la piedra para escalar el cielo, sino con la resignación del mozo de cordel que transporta un baúl. Pequeñito, con sus guedejas lisas y en correcta formación, el traje muy cepilladito y como colgado de su armazón de huesos, tenía una de esas caras que parecen hechas bajo la influencia del nombre del que las ha de ostentar. En suma, era digno de llamarse D. Sindulfo García y merecedor del apodo de _Pichichi_ que su criada le había puesto por sambenito. Tal era la envoltura que la sabiduría eligiera para asombrar al mundo probando una vez más que bajo una mala capa se esconde un buen bebedor.\"},{\"heading\":false,\"text\":\"La comisión tomó asiento debajo del órgano monumental; el presidente agitó una campanilla de plata, la sesión quedó abierta, y el inventor del Anacronópete pasó a ocupar la tribuna a través de una tempestad de aplausos que apagó, no su voz harto débil e insonora, sino el movimiento de sus labios que hizo comprender a la multitud que había pronunciado el sacramental «señores» comienzo de todo discurso.\"},{\"heading\":false,\"text\":\"Restablecido el silencio, el héroe se expresó de esta manera:\"},{\"heading\":false,\"text\":\"--Seré breve porque cuantas más horas consuma más alargo la distancia que me separa del ayer a donde me dirijo. Seré vulgar, porque, sancionadas mis teorías por el mundo sabio, solo me resta hacerme comprender de todos. Ello no obstante contestaré a cuantas objeciones se me hagan. Mi propósito nadie lo ignora, es retroceder en el tiempo, no para detener el continuo movimiento de avance de la vida, sino para deshacer su obra y acercarnos más a Dios encaminándonos a los orígenes del planeta que habitamos. Pero para explicar cómo se deshace el tiempo, es preciso que antes sepamos de qué se compone este. Procedamos con orden. Dios hizo el cielo y la tierra: aquel oscuro; esta en la forma caótica. Después dijo:--«Sea hecha la luz»--y la luz quedó hecha. Tenemos pues al Sol flotando en la bóveda celeste y al orbe suspendido en el espacio por la atracción solar. Cualquiera sabe, desde que Galileo demostró el principio de la rotación de la esfera, que el mundo se mueve; pero lo que no ha dicho la ciencia todavía, es por qué la tierra al girar verifica su movimiento de occidente a oriente en vez de hacerlo a la inversa; y esto es lo que yo voy a exponer como base de mi sistema anacronopético.\"},{\"heading\":false,\"text\":\"El auditorio dejó escapar un murmullo de satisfacción, y el sabio continuó de este modo su conferencia:\"},{\"heading\":false,\"text\":\"--La Tierra en un principio estaba sumida en el caos; era una inmensa bola de fuego que, como todo cuerpo incandescente, exhalaba esos vapores que conocemos con el nombre de irradiación. Fija en su eje, pues como obra acabada de crear no había empezado aún las revoluciones que el Hacedor le impuso, su calor era infinitamente más intenso por Oriente en virtud de la influencia del sol que constantemente la estaba bañando por aquella parte. Los que hayan visto fundirse en una marmita sustancias bituminosas habrán observado la enorme cantidad de vapor que se desprende de ellas. Figúrese por lo tanto el que despediría la fusión de un esferoide cuyo volumen es de mil setenta y nueve millones de miriámetros cúbicos. El más lego concibe que semejantes evaporaciones no podían tener lugar sin que cada desprendimiento fuese acompañado de un estampido y de una convulsión. Ahora bien, si al dispararse un cañonazo, la repercusión hace que el cañón retroceda, cada descarga de la irradiación debía llevar consigo dislocaciones en la esfera terráquea. Y como las descargas se repetían con más frecuencia e intensidad por la parte Oriente del planeta en razón del mayor calórico que el sol le suministraba, los repetidos retrocesos originados hacia aquel lado por las constantes sacudidas dieron por resultado la rotación del esferoide sobre su eje, en la dirección de Poniente a Levante, sabiamente prevista por la Providencia para la periódica sucesión de los días y las noches, y tan duradera como a su omnipotente arbitrio plazca que sea el fuego central que le sirve de motor.\"},{\"heading\":false,\"text\":\"Un prolongado hurra acogió esta teoría tan nueva como atrevida e inesperada. El doctor sin humedecerse la boca--lo que no dejó de llamar la atención de los oyentes, acostumbrados a ver a sus oradores hacer siempre uso del agua en la peroración,--reanudó así el hilo de la suya.\"},{\"heading\":false,\"text\":\"--Todo fenómeno obedece a una causa; y sin embargo han transcurrido dos siglos y medio desde que el inventor del termómetro y del compás de proporción, el sabio de Pisa que por el isócrono movimiento del péndulo enseñó a medir las pulsaciones de la arteria y a contar los segundos, Galileo en fin, nos dijo que la Tierra se movía, hasta hoy que nos ha sido revelada la razón de un hecho tan sencillo. Pero ¿basta esto? De ningún modo. Si todo fenómeno obedece a una causa, preciso es también que tenga un fin, que produzca un resultado, que llene un objeto. «La Tierra se mueve» grita un hombre; y en seguida la ciencia pregunta: «¿Por qué se mueve?» «Por el desprendimiento de calórico» responde la observación; pero acto continuo la filosofía da el alto, cruza el arma y exclama a su vez: «¿Y para qué se mueve?» Vamos a contestar a la filosofía. La Tierra se mueve para hacer tiempo. Nuestro planeta que, como hemos visto, no era más que una masa incandescente, llegó a solidificar su corteza, vio surgir de su superficie montañas colosales, llenó de mares sus senos, vistió su aridez con una flora sorprendente y poblóse de una fauna riquísima. ¿Cómo se operó este milagro? Muy sencillamente; por la acción del tiempo: por una sucesión de días o de épocas cuyo trabajo presidía la sabiduría y la voluntad del Hacedor Supremo, el cual permite que la revolución continúe para perfectibilidad del hombre y admiración de su omnipotencia. Las transformaciones del globo son pues la obra del tiempo. Pero ¿quién es este artífice? ¿Dónde están sus materiales? ¿Cuál es su laboratorio? El artífice es la irradiación; sus materiales están en la zona gaseosa; su laboratorio es el espacio: EL TIEMPO ES LA ATMÓSFERA. Todas las maravillas que la naturaleza, la ciencia, el arte y la industria presentan hoy a nuestra admiración y que creyéndolas la expresión genuina del progreso nos llenan de orgullo, proceden íntegras de esa región en que el hombre no ha sabido encontrar hasta ahora más que aire, lluvia, relámpagos, rayos, truenos y media docena más de accidentes meteorológicos. Refrenad vuestra impaciencia: voy a probar lo expuesto con una demostración práctica. A mí me gusta que la convicción llegue al ánimo por el sentido de la vista.\"},{\"heading\":false,\"text\":\"Una oleada que amenazaba ser una explosión se produjo en el auditorio. El presidente agitó su campanilla, y el disertante, que se había vuelto de espaldas un momento, volvió a reaparecer de frente teniendo en la mano un sombrero de copa cuyo cilindro envolvía una de esas enormes gasas con que el hombre va diciendo que está de luto a los que no se lo preguntan, por lo poco que les importa.\"},{\"heading\":false,\"text\":\"La gasa, dispuesta previamente para el caso, daba cinco o seis vueltas al sombrero y no estaba adherida a este más que por su cabo interior. Don Sindulfo empezó a desenvolverla entre las carcajadas de la muchedumbre, que en aquella, como en todas las circunstancias de la vida, aprovechó la que se le presentaba de abandonarse a su condición frívola y bullanguera.\"},{\"heading\":false,\"text\":\"El sabio, como si nada oyese, continuó su tarea; dejó flotar el crespón cosido por un borde a la copa y, exhibiendo la sedosa felpa del sombrero, dijo, señalando el cilindro libre de toda envoltura:\"},{\"heading\":false,\"text\":\"--He aquí la Tierra en su estado incandescente tal y como a Dios le plugo arrojarla en el espacio infinito. Como veis, está fija, inmóvil; pero de pronto, la irradiación representada por esta gasa produce un desprendimiento; este por la repercusión origina una dislocación en el globo y la esfera principia a girar sobre su eje dando lugar al tiempo que no es otra cosa que el movimiento incesante.\"},{\"heading\":false,\"text\":\"Y así diciendo, mientras con la mano derecha tendía la gasa simulando una columna de humo que se elevase, con la izquierda imprimía una imperceptible rotación al sombrero.\"},{\"heading\":false,\"text\":\"--Mirad el tiempo --proseguía señalando el crespón--. ¿Queréis saber cómo por una sucesión no interrumpida de segundos se convierte en minerales, en plantas y en seres orgánicos? ¿Cómo del alga llega al jardín de aclimatación, del caolín al aderezo de diamantes, de la caverna a la arquitectura, del trilobito con sus tres lóbulos, a la frente del hombre y al cálculo infinitesimal? Seguidle conmigo a su laboratorio atmosférico.\"},{\"heading\":false,\"text\":\"La estupefacción estaba pintada en todos los semblantes. El doctor dejó escapar una sonrisa de triunfo, heraldo de su convicción, y remondándose el pecho continuó así:\"}]},{\"title\":\"El anacronópete — capítulo iii\",\"blocks\":[{\"heading\":false,\"text\":\"Teoría del tiempo: cómo se forma: cómo se descompone\"},{\"heading\":false,\"text\":\"Cualquiera que haya visto hervir en un hornillo una cazuela de sopas, habrá tenido que fijarse necesariamente en el fenómeno de transformación que se verifica en el vaho al escaparse por la campana de la chimenea. Lo primero que hace es enfriarse y convertirse en gotas de agua que paralizan la ebullición si caen en el fondo del recipiente; o bien se trueca en hollín si la condensación tiene lugar a tal distancia del fuego que le permite solidificarse. Es decir que si la cazuela continuara hirviendo durante una serie no interrumpida de años, concluiría por formarse en la superficie de las sopas una película o corteza producto de los desprendimientos de los vapores, ni más ni menos que la que se forma en el fogón y que acabaría por petrificarse a fuerza de tiempo. Pues apliquemos este principio a nuestro caso.\"},{\"heading\":false,\"text\":\"El sombrero es la tierra; la gasa el vaho. Este sube y se condensa; pero aquella gira y lo envuelve del mismo modo que la faja se lía en la cintura del chulo o el turbante en la cabeza del musulmán. Y aquí tienen ustedes cómo por esta rotación la primera capa del crespón oculta ya la seda del sombrero como la primera película sólida del globo ocultó la masa ígnea del planeta. La gasa aparece llena de pliegues y hendiduras. ¿Qué representan? Los montes y las llanuras obra del tiempo. ¿En dónde se ha producido este tiempo? En la atmósfera. ¿Es decir que el Himalaya y la montaña del Príncipe Pío; el valle de Josafat y el de Andorra nos han caído de las nubes? Indudablemente. ¿Cómo? Así: los espantosos huracanes que entonces reinaban, barrían hacia un punto dado las sustancias en fusión de la superficie de la Tierra que, aglomeradas y acumuladas, formaban puntos prominentes, del mismo modo que cuando soplamos en un plato de sémola, la sopa se llena de montoncitos. Por otra parte las continuas descargas eléctricas abrían zanjas en la corteza del esferoide o la deprimían produciendo cauces por los que corría la masa incandescente que son los filones de hoy. Vinieron por último las lluvias torrenciales que, enfriándolo y solidificándolo todo, dieron lugar a la formación del terreno primitivo o sea de la primera capa consistente (contando de abajo arriba) de esta corteza de ochenta kilómetros que nos sirve de pedestal.\"},{\"heading\":false,\"text\":\"«Poco a poco, me objetará alguno: Yo no veo en esas revoluciones atmosféricas sino agentes modificadores de las propiedades del globo; pero nunca la idea del tiempo. Obra de este es indudablemente el mundo; sin embargo, la razón no admite que los minerales, los vegetales y los animales que en sí encierra, sean producto del rayo, del huracán o de la lluvia.»\"},{\"heading\":false,\"text\":\"¿Qué es el tiempo? preguntaré yo contestando. El tiempo es el movimiento; en la inacción no hay ni antes ni después. ¿Quién ha impreso el suyo en la Tierra? La irradiación, el desprendimiento de calórico, el vaho en fin por las repercusiones de sus descargas. ¿De qué agentes se componía este vaho? De todos los que hoy constituyen nuestro planeta; y la prueba es que si la Tierra no se hubiese movido, los gases, perdiéndose en el espacio, nos hubieran dejado sin globo llevándose con la evaporación todas sus substancias. Luego la atmósfera, recibiendo incesantemente las respiraciones del planeta, y devolviéndoselas transformadas, es el laboratorio donde se operan las metamorfosis cósmicas, donde el movimiento se realiza y donde por consiguiente el tiempo se produce. ¡Cómo! ¿Vosotros no veis en la lluvia más que la gota de agua, la chispa en el rayo, la ráfaga en el huracán? Levantad el espíritu y adorad al Creador que os envía en esos fluidos el mañana incesante, como hace cerca de siete mil años os mandó el hoy en que vivís y sus maravillas que admiráis. Las nubes arrojaron la columna de Santa Sofía en Constantinopla y el obelisco de Sixto V en la ciudad Eterna trayéndonos en sus gotas el pórfido rojo de Egipto con sus cristalizaciones blancas. De su laboratorio bajaron las agujas de Luxor y la columna de Pompeyo. El bermellón con que el hijo de David y Betsabé mandó pintar el templo de Jehová, ¿quién lo produjo sino el cinabrio llovido sobre Almadén en la Mancha? La cal y el carbono desprendidos de las entrañas del nimbo, os regalaron las casas que habitáis procurándoos las calcáreas y las calizas, de que extraéis el mortero y con que talláis la ménsula. En el mismo chaparrón en que venía envuelta la marga para ladrillos, llegaba el caolín que con el feldespato se vitrificaba para procuraros tazas en que tomar los alimentos y porcelanas con que adornar vuestros salones. ¿Dónde estarían los ferrocarriles que atraviesan el Mont-Cénis y el San Gotardo y los vapores que, como el Vega, se abren ya camino por el estrecho de Behring, sin la acción atmosférica que descomponiendo la vegetación del período carbonífero elaboró la hulla? ¿Negaréis que en cada gota existía el germen de una locomotora o de una goleta y en cada temporal el de un tren o de una escuadra? Pero no llovían solo medios de locomoción; del llanto de la zona gaseosa se desprendían chimeneas, alumbrados públicos y caricias femeniles: porque extraído el hidrógeno de la hulla, aquel levantaba fábricas de gas, mientras sus residuos metamorfoseados en coque congregaban a la familia al amor de la lumbre o servían para firmar las paces entre marido y mujer cuando, carbono cristalizado, se presentaban en la forma de diamante. La brújula y el telégrafo eléctrico tuvieron por inspirador al rayo. ¿Qué sería de la humanidad sin el mercurio que así le señala las variaciones de la temperatura como le sirve para la extracción del oro y de la plata? Pero aún hay más. En los elementos constitutivos de los fenómenos atmosféricos, Dios permite que vengan a la tierra en embrión las conchas, las tortugas, las aves, los reptiles y los mamíferos de la época secundaria; y que, purificado el aire por la absorción que del ácido carbónico ha hecho la vegetación carbonífera, sople ya tan respirable en el período terciario para la familia orgánica, que el infusorio, caído en la tierra con la gota de lluvia, se desarrolle, se cruce y se agigante convirtiéndose en mastodonte, hipopótamo, rinoceronte, caballo, toro, búfalo, ciervo, dromedario, tigre y león. Por fin, el terreno cuaternario nos presenta el mamut, el auroch, el urus, el gamo, el ciervo y el megaterio; hasta que la Providencia para coronar su obra, toma una porción de aquella arcilla elaborada al efecto durante seis días o épocas, y, modelando con ella una figura, le comunica su Divino soplo, la llama hombre y le proclama por su inteligencia rey de la creación. Señores, las envolturas concéntricas de la gasa simbolizan las épocas geológicas de la naturaleza. Estas épocas deben considerarse como las matemáticas del mundo. ¿No son producto de evoluciones atmosféricas? Sí. ¿No contamos por ellas la edad del globo? Sí. Pues si cada película es una serie de siglos, cada gota, cada chispa, cada ráfaga debe ser una porción de segundo; luego las horas se ciernen en el espacio: afirmemos pues que el tiempo es la atmósfera.\"},{\"heading\":false,\"text\":\"El entusiasmo, reprimido en el auditorio por efecto de la admiración, estalló en la primera pausa propicia, y una tempestad de aplausos y aclamaciones retumbó en el recinto haciéndose extensiva hasta los corredores donde la gente aplaudía por espíritu de imitación. Uno de los concurrentes, levantándose del asiento con gran extrañeza del público que creía que abandonaba el local, se encaró con el sabio y le dijo:\"},{\"heading\":false,\"text\":\"--¿Se me permite exponer una duda?\"},{\"heading\":false,\"text\":\"--Todas cuantas se originen --respondió don Sindulfo.\"},{\"heading\":false,\"text\":\"--Si el orador considera al tiempo como una faja densa, ¿no es de presumir que dada la depresión de todo cuerpo esférico por sus polos, los de la tierra queden sin envoltura como la imperial del sombrero y el aro o círculo de la cabeza han quedado sin gasa en la demostración?\"},{\"heading\":false,\"text\":\"--Es indudable; y eso no hace sino confirmar mi tesis. Probado que la atmósfera es el tiempo y que el tiempo lo forman los acontecimientos, si nadie ha ido todavía a los polos, en los polos no ha sucedido nada; y no haciendo falta el crespón o envoltura allí donde no hay vitalidad, esta economía de atmósfera ha sido la sisa del sastre naturaleza.\"},{\"heading\":false,\"text\":\"Una sonora carcajada acogió la humorística refutación del sabio, quien sin inmutarse prosiguió el curso de su conferencia.\"},{\"heading\":false,\"text\":\"--Nada más simple, señores, que descomponer un cuerpo cuando los elementos que lo componen nos son conocidos. Si yo sé que este signo de luto de mi sombrero lo forman capas concéntricas de gasa liadas alrededor del cilindro, con irlas desenvolviendo en sentido contrario al que ellas emplean en su revolución envolvente, es indudable que llegaré a dejar a descubierto la copa; lo cual aplicado al cosmos significa que a fuerza de desliar zonas geológicas se ha de tropezar con el caos. Ahora bien: ¿Cómo tiene lugar esta descomposición? Para explicarlo satisfactoriamente es preciso que me ocupe un poco de mi aparato. El Anacronópete, que es una especie de arca de Noé, debe su nombre a tres voces griegas: _Aná_ que significa hacia atrás, _cronos_ el tiempo y _petes_ el que vuela, justificando de este modo su misión de volar hacia atrás en el tiempo; porque en efecto, merced a él puede uno desayunarse a las siete en París, en el siglo XIX; almorzar a las doce en Rusia con Pedro el Grande; comer a las cinco en Madrid con Miguel de Cervantes Saavedra --si tiene con qué aquel día-- y, haciendo noche en el camino, desembarcar con Colón al amanecer en las playas de la virgen América. Su motor es la electricidad, fluido a que la ciencia no había podido hacer viajar aún sin conductores por más que estuviese cerca de conseguirlo, y que yo he logrado someter dominando su velocidad. Es decir que lo mismo puedo dar en un segundo, como locomoción media, dos vueltas al mundo con mi aparato, que hacerlo andar a paso de carreta, subirlo, bajarlo o pararlo en seco. Dado el agente impulsor, todo lo demás son procedimientos mecánicos cuya relación ningún interés despertaría, especialmente en un público que sabe de memoria las obras de Julio Verne; obras de entretenimiento que si bien no he de comparar con el solemne carácter científico de mis teorías, encierran no obstante hipótesis basadas en estudios físicos y naturales que me eximen de explicaciones enojosas sobre el regulador, los compensadores, termómetros, barómetros, cronómetros, anteojos de gran potencia, recipientes de potasa, aparato Reiset y Regnaut para producir el oxígeno respirable y tantos otros detalles rudimentarios. Elévome, pues, al centro de la atmósfera, que es el cuerpo que se trata de descomponer y al que seguiré llamando tiempo. Como el tiempo para envolverse en la tierra camina en dirección contraria a la rotación del planeta, el Anacronópete para desenvolverlo tiene que andar en sentido inverso al suyo e igual al del esferoide o sea de occidente a oriente. El globo emplea veinticuatro horas en cada revolución sobre su eje; mi aparato navega con una velocidad ciento setenta y cinco mil doscientas veces mayor; de lo cual resulta que en el tiempo que la Tierra tarda en producir un día en el porvenir, yo puedo desandar cuatrocientos ochenta años en el pasado.\"},{\"heading\":false,\"text\":\"Ahora bien; lo primero que salta a la vista es que, cualquiera que sea la velocidad de la locomoción y la altura a que esta se verifique, el Anacronópete no ha de hacer más que describir una órbita alrededor de la tierra como la que alrededor de los planetas describen los satélites; y así sucedería en efecto si la atmósfera permaneciera inalterable; pero como la descompongo, en cada vuelta deshago su obra de un día y allí donde me paro allí está el ayer. Veamos cómo se verifica este fenómeno.\"},{\"heading\":false,\"text\":\"Dícese vulgarmente que para conservar las sardinas de Nantes y los pimientos de Calahorra hay que extraer _el aire_ de las latas. Error. Lo que se extrae es _la atmósfera_ y por consiguiente _el tiempo_; porque el aire no es más que un compuesto de nitrógeno y oxígeno, mientras que la atmósfera, además de constar de ochenta partes del primero y veinte del segundo, lleva en sí una porción de vapor de agua y una pequeña dosis de ácido carbónico, elementos todos que no se separan nunca al llenar un vacío. Pero apartémonos de la ciencia y vengamos al razonamiento vulgar.\"},{\"heading\":false,\"text\":\"Figurémonos que el mundo es una lata de pimientos morrones de la que no hemos extraído la atmósfera. ¿Qué sucede una vez tapada sin esta precaución? Que el tiempo empieza a ejercer su influencia y a verificar su obra. En primer lugar se adhieren a las paredes del bote unas moléculas que, aglomeradas y solidificadas concluirían a fuerza de años por petrificarse y en cuyas substancias encontraríamos los gérmenes minerales de las rocas primitivas. Después observamos que el jugo se cubre de una especie de verdín que no es otra cosa que la vegetación rudimentaria. Y por último los infusorios del vapor de agua vivificados, reproducidos y desarrollados agusanan la conserva enriqueciéndola con las múltiples variantes del reino animal. ¿Puede aún dudarse que la atmósfera es el tiempo?\"},{\"heading\":false,\"text\":\"Pues volvamos la oración por pasiva. Supongamos que hemos extraído el aire y que abrimos la lata cien años después de haberla tapado. ¿Qué vemos? Los pimientos en perfecto estado de conservación sin que el tiempo haya pasado por ellos; luego si la acción atmosférica debió destruirlos o metamorfosearlos y la falta de esta acción los ha mantenido en su completa integridad, es indudable que lo que nos comemos cien años después, es la vida vegetal de una centuria antes y que por consiguiente retrogradamos un siglo. Más claro. No hemos extraído el aire de la lata y la abrimos en el momento en que la descomposición empieza; si tomamos una cuchara y con ella empezamos a quitar las capas de moho que envuelven los pimientos, su rojizo color, aún no alterado, concluirá por descubrirse a través de las injurias de la atmósfera. Pues esta es la teoría del tiempo. Muy joven el mundo todavía para que el fuego central haya desaparecido, se halla no obstante cubierto de esas películas de moho que el Anacronópete va a desenvolver con el auxilio de cuatro grandes cucharas o aparatos neumáticos fijos en sus extremos angulares; con los que, no solo descompongo las miserables veinte leguas de gases que circundan el esferoide en capas concéntricas, sino que al desalojarlas logro navegar en el vacío impidiendo que mi vehículo se inflame con la frotación atmosférica. Porque, volviendo a los símiles: la atmósfera no es más que una aglomeración de átomos imperceptibles, del mismo modo que una playa no es otra cosa que la reunión de millones de granos de arena. O si la queremos más perceptible, la atmósfera es una vastísima plaza pública llena de gente en un día de revolución. Si un hombre temerario e inerme se empeñara en llevar corriendo un parte de un extremo a otro contra la oposición de la atmósfera popular, sucedería que empellón de aquí, tirón de allá, resistencia de todas partes, perecería sin remedio entre las ondas de aquel revuelto piélago, como el Anacronópete acabaría por desaparecer abrasado en su carrera en razón de la frotación y el movimiento.\"},{\"heading\":false,\"text\":\"Pero ¿qué hace un gobernador prudente representado en esta circunstancia por la ciencia? Le da un caballo al encargado de llevar el parte (la electricidad aplicada al Anacronópete), le rodea de un piquete de caballería (los cuatro aparatos neumáticos), y les ordena que, lanza en ristre, desemboquen por una de las calles adyacentes. El fenómeno que se opera es de todos conocido. Los átomos se dispersan delante de los lanceros; las moléculas que quedan atrás tratan de llenar el hueco originado por el desalojamiento o sea la dispersión; pero, como la caballería camina con más velocidad que los amotinados de la retaguardia y los de delante huyen fuera del alcance de las picas, los grupos desaparecen, y el parte, libre de toda fuerza de resistencia llega a feliz término sin obstáculo alguno galopando por el vacío que le van abriendo las lanzas del escuadrón.\"},{\"heading\":false,\"text\":\"El auditorio delirante iba a prorrumpir en una entusiasta exclamación; pero se detuvo al ver que el interruptor volvía a ponerse de pie, y encarándose con el disertante exclamaba:\"},{\"heading\":false,\"text\":\"--No sin temor voy a exponer una duda.\"},{\"heading\":false,\"text\":\"--Escucho --dijo el sabio.\"},{\"heading\":false,\"text\":\"--Si por ese procedimiento, que no admite refutación, camina uno hacia atrás en el tiempo: ¿no sucederá que a medida que el anacronóbata pierda años, se vaya volviendo más joven?\"},{\"heading\":false,\"text\":\"--Indudablemente.\"},{\"heading\":false,\"text\":\"Aquí la sensación del bello sexo se tradujo en un grito de alegría.\"},{\"heading\":false,\"text\":\"--¿De modo que el viajero acabará por no existir a fuerza de irse achicando?\"},{\"heading\":false,\"text\":\"--Eso es lo que acontecería si la ciencia no lo hubiera previsto todo.\"},{\"heading\":false,\"text\":\"--¿Y cómo neutraliza su señoría esos efectos?\"},{\"heading\":false,\"text\":\"--Muy sencillamente: haciéndome inalterable merced a unas corrientes de un fluido de mi invención. ¿No camino yo hacia el pasado? Pues así como pueden guardarse sardinas frescas para el porvenir, me garantizo del ayer que constituye mi mañana. Es el procedimiento de las conservas alimenticias aplicado a la vida animal con el efecto invertido. Y esto sentado, permítaseme poner punto final a mi conferencia, pues avanzan las horas y me urge tener esta noche una entrevista con Felipe II para enterarme de si el pastelero de Madrigal fue o no positivamente el rey portugués cuya desaparición dejará de ser en breve uno de los misterios de la historia.\"},{\"heading\":false,\"text\":\"Un diluvio de hurras se desencadenó en la sala. Los hombres lanzaban al aire sus tricornios y sus sombreros; las señoras cubrían de flores la tribuna del orador, y el órgano, ejecutando una marcha compuesta para aquella solemnidad, lograba a duras penas dejarse oír entre las frenéticas vociferaciones del desbordamiento público.\"},{\"heading\":false,\"text\":\"Por fin, nuestro ilustre compatriota, rodeado del congreso científico y seguido de la multitud consiguió llegar a la puerta; y, dando allí un viva al _atrás_ como nuevo grito de la civilización, atravesó la balaustrada, descendió la colina del Trocadero y se encaminó al Anacronópete que majestuoso descansaba su inmensa mole en la explanada del palacio del campo de Marte.\"}]},{\"title\":\"El anacronópete — capítulo iv\",\"blocks\":[{\"heading\":false,\"text\":\"En el que se tratan asuntos de familia\"},{\"heading\":false,\"text\":\"Los grandes efectos no son siempre el resultado de grandes causas. Ahí tenemos si no las guerras del Peloponeso a las que la historia atribuye una razón eminentemente política y que sin embargo debieron su origen al rapto que de tres doncellas educandas de Aspasia hicieron unos habitantes de Megara, jóvenes de buen humor, sin contar que la cosa no había de ser del agrado de Pericles --de quien dicen malas lenguas si tenía o no tenía que ver con la profesora--. Y paréceme a mí que sí que le gustaba al hombre porque, cuando acusada de impiedad él se encargó de su defensa, no supo hacer más que cubrirse el rostro con el manto y llorar como un chiquillo en el Pnix; lo que por cierto le valió la absolución a la buena discípula de Anaxágoras.\"},{\"heading\":false,\"text\":\"Pues bien, erudición a un lado, tampoco el invento de don Sindulfo era debido, como lo parecía, a su amor por la ciencia; sino a un interés doméstico, mejor diré, a una mira puramente personal.\"},{\"heading\":false,\"text\":\"Cuatro palabras sobre su vida.\"},{\"heading\":false,\"text\":\"Muy joven aún nuestro héroe se encontró solo en el mundo, doctor en ciencias y dueño de una inmensa fortuna cuyos rendimientos invertía, anualmente y casi íntegros, en aparatos de las mejores fábricas extranjeras con que enriquecer su gabinete de física y mineralogía. Tan pródigo para sus estudios como avaro para todo lo demás, llegó a los cuarenta años sin conocer ni los rudimentos del amor. Todas sus afecciones se concretaban en su amistad por Benjamín, otro sabiote dos lustros menor que él, pero casi tan ajeno como don Sindulfo a todas las cosas de la tierra; verdad es que el tiempo le faltaba para cuanto no fuese aprender sánscrito, hebreo, chino y un par de docenas más de lenguas difíciles, para las que tenía una aptitud sin igual. Aunque no habitaban la misma casa, puede decirse que vivían juntos, pues Benjamín no abandonaba la de García en la que diariamente podía contar con su plato de cocido a las dos y su guisado a las ocho, en virtud de lo cual Benjamín, que era pobre, resolvía el problema de ahorrar sin tener, y don Sindulfo encontraba un estómago agradecido que soportase sus impertinencias.\"},{\"heading\":false,\"text\":\"Los periódicos de Zaragoza, como todos los de la Península, amanecieron una mañana anunciando la venta del museo de un célebre arqueólogo de Madrid fallecido pocas semanas antes; y como Benjamín, a quien no se le cocía el pan en el cuerpo cuando de cosas antiguas se trataba, manifestase deseos de adquirir algunas baratijas, su amigo le procuró la ocasión decidiendo trasladarse ambos a la corte de las Españas, y poniendo a disposición del anticuario su bolsillo y sus conocimientos.\"},{\"heading\":false,\"text\":\"Dicho y hecho: llegaron a Madrid, tomaron un cuarto común en las Peninsulares y el día de la venta se trasladaron al gabinete del coleccionador. Benjamín lo hubiera comprado todo a haber tenido dinero; pero se contuvo ante su pobreza y aun fue preciso que don Sindulfo le aguijoneara para hacerse con algunos ejemplares. La verdad es que se necesitaba ser un santo para no quitárselo de la boca, por ser dueño de aquel cúmulo de maravillas. Allí en un estuche de cuero y en estado fósil se encontraba el ojo que Aníbal perdió en el sitio de Sagunto: a su lado se erguía la punta del cuerno del buey Apis: un poco más allá reposaba una carabina llena de moho que, por haberse encontrado cargada con cañamones, se suponía que fuese la de Ambrosio que hasta entonces se había tenido por legendaria. Pero como los precios no estaban al alcance de todas las fortunas, Benjamín tuvo que reducir sus aspiraciones y concretarse a la adquisición de una medalla relativamente importante. El tiempo había corroído parte de la inscripción; pero lo que de ella podía aún leerse que era esto:\"},{\"heading\":false,\"text\":\"SERV C POMP PR JO HONOR\"},{\"heading\":false,\"text\":\"no dejaba duda acerca del origen que el catálogo le atribuía suponiéndola tributo conmemorativo de Servio Cayo, prefecto de Pompeya, en honor de Júpiter.\"},{\"heading\":false,\"text\":\"Ya iban a abandonar el museo cuando llamó la atención del absorto aficionado el ínfimo precio en que estaba tasada una momia de carácter particular. Y en efecto, ni el sarcófago tenía la forma egipcia, ni el procedimiento por que aquel cadáver había sido embalsamado era el que, según Herodoto, se practicaba en Tebas y Memfis abriendo el pecho con una aguzada piedra de Etiopía para sacar el ventrículo y rellenar el vientre con mirra, casia y vino de palmera. Tampoco se había obtenido la momificación con la resina llamada _Katran_ por los árabes, extraída a fuego vivo de un arbusto muy abundante en las orillas del mar Rojo, la Siria y la Arabia feliz, como lo consigna el coronel Bagnole. Su acartonamiento parecía obra natural; pues, sobre no tener huella de incisión alguna, ni estaba envuelta en las tradicionales bandas, ni, falta de depresiones, podía decirse que hubiera sido fajada nunca. El catálogo decía modestamente: «Momia de origen desconocido;» y esta ausencia de abolengo o de historia es lo que la hacía despreciable para los que de ordinario solo se pagan de genealogías apócrifas las más veces.\"},{\"heading\":false,\"text\":\"Benjamín, con su espíritu observador, puso sus cinco sentidos en el estudio de los menores detalles; y fijándose en una ajorca o argolla de metal adaptada en el tobillo derecho y sobre la que campeaba una inscripción china --que el vulgo había tomado por un adorno--, no pudo reprimir un grito de sorpresa.\"},{\"heading\":false,\"text\":\"--¿Qué es eso? --le preguntó don Sindulfo.\"},{\"heading\":false,\"text\":\"--Acabo de hacer un descubrimiento prodigioso.\"},{\"heading\":false,\"text\":\"--¿Cuál?\"},{\"heading\":false,\"text\":\"--Oiga usted lo que dice esta inscripción: «Yo soy la esposa del emperador Hien-ti, enterrada viva por haber pretendido poseer el secreto de ser inmortal.»\"},{\"heading\":false,\"text\":\"--¡Hien-ti! --exclamó don Sindulfo partícipe ya del entusiasmo de su amigo--. ¿El último vástago de la dinastía de los Han?\"},{\"heading\":false,\"text\":\"Destronado en el siglo tercero de la era cristiana por Tsao-pi, fundador de la dinastía de los Ouei.\"},{\"heading\":false,\"text\":\"--Es decir...\"},{\"heading\":false,\"text\":\"--Es decir que ese pueblo, cuna de la civilización del resto del mundo, poseía, si no el secreto de la inmortalidad, por lo menos el de la longevidad fabulosa de los tiempos patriarcales.\"},{\"heading\":false,\"text\":\"Don Sindulfo, sin esperar nuevas explicaciones, sacó su cartera y extendió una orden de pago contra su banquero, encargando el transporte a las Peninsulares de los objetos adquiridos, entre los que figuraba otro hallazgo hecho a última hora y consistente en un hueso petrificado, que tuvieron que pagar a peso de oro, pues se trataba nada menos, según el inventario, de una canilla de hombre fósil descubierta en las inmediaciones de Chartres, en unos terrenos de la época terciaria.\"},{\"heading\":false,\"text\":\"Los dos inseparables no pensaban más que en los preparativos de regreso a Zaragoza para entregarse de lleno a sus investigaciones científicas. Pero un garbanzo interpuesto en su camino cambió de fase la majestuosa monotonía de su existencia. Al ir por la tarde a liquidar y despedirse del banquero, fornido zamorano viudo y enriquecido durante la primera guerra civil con la empresa de suministros para el ejército leal, hubo aquello de:\"},{\"heading\":false,\"text\":\"--¿Y qué tal los tratan a ustedes en la fonda?\"},{\"heading\":false,\"text\":\"--Mal; comida francesa con la que nunca sabe uno lo que se mete en el estómago. Nos vamos de Madrid sin probar un cocido a la usanza de Castilla.\"},{\"heading\":false,\"text\":\"Y lo de:\"},{\"heading\":false,\"text\":\"--Pues hoy satisfarán ustedes su capricho; porque precisamente acabo de recibir unos garbanzos de Fuentesaúco que ni de manteca serían más tiernos.\"},{\"heading\":false,\"text\":\"--Que eso sería mucha incomodidad.\"},{\"heading\":false,\"text\":\"--Que no.\"},{\"heading\":false,\"text\":\"--Que sí.\"},{\"heading\":false,\"text\":\"--Que toma.\"},{\"heading\":false,\"text\":\"--Que daca.\"},{\"heading\":false,\"text\":\"El resultado es que se quedaron a comer con el banquero, el cual banquero tenía una hija; la cual hija era muda; pero, aunque no le faltaba más que la palabra para hablar, a ella no se le quedaba nada por decir, que con pies y manos todo lo daba a entender. Yo no sé cuál de estos aparatos locutorios es el que ella puso más en juego durante la comida; lo cierto es que a los postres, don Sindulfo que ocupaba su derecha, estaba a pesar de sus cuarenta años enamorado ya de la chica como un cadete. Por supuesto que todo se lo merecía la hija de su padre, pues no había línea en su cuerpo que no alcanzase el máximo de curva, ni facción que no incitase a cualquiera a ser Espartero no solo para perseguirlas como en Bilbao sino para abrazarlas como en Vergara.\"},{\"heading\":false,\"text\":\"El viaje se suspendió; las visitas se repitieron; la necesidad de no tener los aparatos físicos encomendados a manos mercenarias para su conservación sirvió a don Sindulfo de tema con Benjamín sobre la conveniencia del matrimonio: el asentimiento de este alentó al sabio, la demanda fue hecha en debida forma; y el banquero, que siempre tenía garbanzos del Saúco que probar cada vez que se le ponía a tiro un hombre en estado de merecer, dijo que sí con la alegría del enfermo a quien se le resuelve un tumor. La muchacha no hay que consignar si recibió bien la noticia, pues sabido es que tratándose de matrimonio hasta las mudas se alegran.\"},{\"heading\":false,\"text\":\"Estipulóse la dote que fue pingüe, dispusiéronse los regalos de boda, y como entre las condiciones figuraba la de residir en Madrid, los sabios se volvieron a Zaragoza para empaquetar convenientemente el laboratorio. Un mes después, marido, mujer y amigo, se instalaban en la calle de los Tres Peces de la coronada villa.\"},{\"heading\":false,\"text\":\"Mamerta, que así se llamaba la señora de García, salió de un natural excelente; porque el que gustase más de estar con Benjamín que con su marido, nada tenía de particular, si se considera que aquel en su calidad de políglota la enseñaba a hablar por señas en varias lenguas diferentes, mientras que don Sindulfo aun en la suya propia no conseguía hacerse entender; y las mujeres se pirran por que les den conversación. También se le iban los ojos detrás de los uniformes; pero don Sindulfo, comprendiendo que este es achaque de muchachas, se ponía de cuando en cuando el de nacional de caballería que usó en el bienio, y la dejaba tan contenta. El único defecto que tenía era el de no podérsela contrariar. Al instante le daba un ataque de nervios que se traducía en una serie de cachetes descargados sobre el occipucio de su marido, en gracia de cuya conservación el hombre tuvo por prudente dejarle hacer su voluntad en adelante para no excitar, decía, su sistema nervioso. Otra particularidad suya digna de notarse es que en cuanto veía una aguja enhebrada, se desmayaba; lo que, a pesar de sus buenos propósitos, la impedía ocuparse de los quehaceres domésticos. Pasábase pues el día poniéndose moños en el tocador, haciendo señas con Benjamín o tañendo a la guitarra una cosa que nadie le había enseñado ni nadie podía entender; pero que ella reproducía siempre invariablemente con el mismo ritmo, idénticas modulaciones y análogos efectos: romper el tímpano de los que la oían.\"},{\"heading\":false,\"text\":\"Y así se deslizaron seis meses llenos de paz y de ventura para aquella trinidad; tras de los cuales vino el verano y con este los baños de mar, que el banquero tomaba en Biarritz para enflaquecer, sin lograrlo nunca, acompañado de su hija a quien se los propinaban para adquirir carnes, sin conseguirlo tampoco. Visto pues que Mamerta, a pesar del matrimonio, no engordaba, se decidió que aquel año iría con su padre, como de costumbre, a ponerse en remojo en la playa favorita de la emperatriz. Llegaron y se zambulleron; pero, con tan mala suerte, que el banquero mientras hacía una habilidad tuvo un vahido y se ahogó. Su hija pidió auxilio por señas; el bote de salvamento acudió como un rehilete; la muchacha no anduvo bastante lista en evitarlo y, dándole en la nuca con la proa, en vez de uno fueron dos los cadáveres que sacó a la orilla. Con lo que, como el padre había sido la primera víctima y Mamerta tenía hecho testamento en favor de su esposo, don Sindulfo se encontró posesor de una fortuna considerable que unida a sus bienes le permitía emular la fama de Creso.\"},{\"heading\":false,\"text\":\"«Bien vengas mal si vienes solo» dice el refrán; y nunca proverbio tuvo más exacta aplicación, pues desde entonces empezaron las tribulaciones de nuestro sabio, si bien pueden darse todas por bien sufridas en gracia de los beneficios que reportaron a la ciencia.\"},{\"heading\":false,\"text\":\"Murió también por aquel entonces una hermana de don Sindulfo, tan rica como él, viuda de luengos años y madre de un tierno pimpollo de quince primaveras que respondía al nombre de Clara. Al dejar esta tierra, en la de Pinto, donde residía, nombró tutor de la niña a su hermano, después de dejarle su manda correspondiente, sin otra condición que la de no separar en vida a la huérfana de una mozuela, cuatro años mayor que Clara, con quien esta se había criado y a quien, no obstante la condición humilde de Juanita --pues no pasaba de ser una criada suya-quería entrañablemente.\"},{\"heading\":false,\"text\":\"La viudez que lloraba nuestro sabio, sus aficiones que le incitaban a la soledad, las circunstancias que le atraían al retiro le indujeron a cambiar de residencia, y los dos inseparables con sus retortas y crisoles, sus pluviómetros y brújulas, sus pedruscos y sus fósiles, fueron a sepultarse en Pinto entre la inocente sencillez de Clara y las inocentes ocurrencias de Juanita que, hija de la tierra --sin dejar de serlo de su padre y de su madre, difuntos--, largaba una fresca al lucero del alba en ese tono mayor que usa la gente de Madrid abandonada a su natural instinto. Los sabios no le entraron a la maritornes por el ojo derecho y ya principió por regalarle a cada uno su mote. A don Sindulfo le llamaba _el tío Pichichi_ y al profesor de lenguas _el locutorio_.\"},{\"heading\":false,\"text\":\"Pero ¡oh fragilidad de las cosas humanas! Aquel hombre que llegara hasta los cuarenta años sin experimentar la atracción de las hijas de Eva, no necesitó más que seis meses de consorcio para no saber ya resistir a la influencia de su imán. Desconociendo que su caso con la muda había sido una chanca matrimonial cedida al primer postor, llegó a figurarse que su cara era moneda de buena ley para adquirir a tan bajo precio artículos no averiados, y siempre se la estaba poniendo delante a su sobrina que, inocente y cariñosa, la contemplaba sin ver en ella más que una cara de tío.\"},{\"heading\":false,\"text\":\"Estimulado por lo que nuestro héroe juzgaba el triunfo de sus atractivos y secundado por las sugestiones de Benjamín, siempre dispuesto a lisonjear las debilidades de su protector, un día al cabo de algunos meses don Sindulfo se decidió a declarar a su pupila su atrevido pensamiento, lo que le valió una negativa rotunda, si bien regada con amargo llanto de Clara que no se resolvía a explicar el motivo de su oposición.\"},{\"heading\":false,\"text\":\"--¡Hombre de Dios! venga usté acá --le dijo Juanita saliendo al encuentro de su amo al enterarse de lo ocurrido--. Hágame usté el favor de mirarse las arrugas delante de ese espejo: ¿Cree usté que a mi señorita le ha de gustar casarse con un fuelle?\"},{\"heading\":false,\"text\":\"--¡Deslenguada! --gritó don Sindulfo ciego de cólera--. No des lugar a que te ponga en el arroyo.\"},{\"heading\":false,\"text\":\"--¿A mí? Ni usté ni nadie. Estoy aquí por la voluntad de la _testaora_ y me defiende la curia. Yo soy una criada ante escribano.\"},{\"heading\":false,\"text\":\"--Pero ¿en qué se funda para desahuciarme? --preguntó el tutor en tono humilde, probando si por la dulzura sacaba mejor partido.\"},{\"heading\":false,\"text\":\"--Pues _miste_; finalmente, que a la señorita y a mí no nos da por la _cencia_ sino por la _melicia_.\"},{\"heading\":false,\"text\":\"--¿Cómo?\"},{\"heading\":false,\"text\":\"--Que ella quiere retemucho a su primo don Luis el capitán de húsares, y yo a su asistente Pendencia; que dentro de tres días llegarán de guarnición a Madrid, y que si nos viene usted con retruécanos verá usted el escabeche de sabio que resulta.\"},{\"heading\":false,\"text\":\"Aquella revelación, confirmada por su sobrina, fue el golpe de gracia para don Sindulfo, cuya pasión alcanzó el período álgido aguijoneada por los celos. El capitán, más enamorado que nunca de su prima, llegó efectivamente a la corte una semana después, y dos horas más tarde se personaba en Pinto; pero la puerta de la casa le fue herméticamente cerrada por don Sindulfo con la intimación de no volver a poner allí los pies so pena de desheredarle. El primer impulso de Luis fue pedir amparo a la justicia contra la arbitrariedad del despiadado tutor; pero ni Clara tenía la edad legal para que el juez supliese el disenso paterno, ni aun teniéndola hubiera ella contrariado la última voluntad de su madre por la que le obligó a no tomar marido que no fuese de la aprobación de don Sindulfo.\"},{\"heading\":false,\"text\":\"Preciso fue por lo tanto sufrir y esperar. Cuando se quiere y se es querido, todo se soporta con resignación. Pero desde aquel punto la casa fue un infierno, pues las cartas iban y venían por conducto del asistente y de la maritornes, y al sabio todo se le volvía vigilar sin fruto y enflaquecer sin resultado.\"},{\"heading\":false,\"text\":\"--¡Oh! --exclamaba el infeliz en su desesperación--. ¿Por qué se habrán liberalizado tanto las leyes? Dichosos tiempos aquellos en que un tutor tenía derecho de imponerse a su pupila. ¿Quién pudiera transportarse a aquella época, mal llamada de oscurantismo, en que el respeto y la obediencia a los superiores constituían la base de la sociedad? ¡Si yo pudiese retrogradar en los siglos!\"},{\"heading\":false,\"text\":\"--¡Ojalá Dios! --contestaba Benjamín haciéndole el dúo--. De ese modo podríamos caer sobre China en el imperio de Hien-ti y aclarar ese enigma iniciado por la momia, para cuya interpretación he leído inútilmente cuantos historiógrafos han escrito sobre los sectarios de Confucio y Mencio.\"},{\"heading\":false,\"text\":\"Esta idea predominante en ambos llegó a tomar en ellos las proporciones de una monomanía. El políglota soñaba en chino y su colega se pasaba la existencia extrayendo aire de los recipientes con la máquina neumática, para su análisis y descomposición. Pero todo fue inútil hasta que la Providencia --que quiso en este caso, como en la mayor parte de los descubrimientos, disfrazarse de casualidad-- vino inesperadamente en su ayuda.\"},{\"heading\":false,\"text\":\"Cierta tarde en que el nuevo don Bartolo, impulsado por sus celos penetró de puntillas en la cocina con el fin de sorprender a las palomas, que huyendo del gavilán se refugiaban casi siempre en el fogón, halló a Juanita deletreando una carta de Pendencia, que ella se guardó precipitadamente donde sabía que don Sindulfo no se la había de coger.\"},{\"heading\":false,\"text\":\"--¿Qué estás haciendo? --le preguntó.\"},{\"heading\":false,\"text\":\"--Instruyéndome --le dijo ella sin inmutarse.\"},{\"heading\":false,\"text\":\"--Más valdría que te entretuvieses en limpiar la chimenea que tiene un palmo de hollín y un regimiento de telarañas.\"},{\"heading\":false,\"text\":\"--Y la creación entera encontrará usted ahí. Eso es la obra del tiempo. Si puede que desde que usted ha nacido no le hayan pasado un escobón.\"},{\"heading\":false,\"text\":\"Don Sindulfo, que tenía un cuchillo a mano, lo blandió con ánimo sin duda de cometer un homicidio; pero deteniéndose oportunamente se puso a rascar con él la campana del hogar como para paliar su arrebato.\"},{\"heading\":false,\"text\":\"--Pues entretente --añadió-- en quitar las capas de basura y verás cómo consigues sacar a luz los hornillos.\"},{\"heading\":false,\"text\":\"--¡Ay! No me haga usté reír. Pues si eso fuera posible ya se hubiera usted puesto como nuevo rascándose con un cuchillo las capas de años que le sobran.\"},{\"heading\":false,\"text\":\"Don Sindulfo se las iba a echar de matón; pero una idea súbita cruzó por su mente y se quedó en un pie como las grullas y en la actitud de Caín al oír al Señor preguntarle: «¿Qué has hecho de tu hermano?» Aquel ser vulgar sin la menor noción científica acababa de iniciarle en la solución del problema que perseguía con tanto empeño.\"},{\"heading\":false,\"text\":\"Desde aquel instante puso manos a la obra. La física, las matemáticas, la geología, la dinámica, la mecánica, el cálculo sublime, la meteorología, todo el saber humano en fin, espoleado por su amor y azotado por sus celos, le abrió sus más recónditos enigmas, y reduciendo a una fórmula su maravillosa invención, sentó el axioma de que retrogradar en los siglos no era otra cosa que deshollinar el tiempo.\"},{\"heading\":false,\"text\":\"Algunos años, todo su capital y gran parte del de su sobrina, se invirtieron en la construcción del Anacronópete. Entre tanto los novios esperaban pacientemente y aventuraban, aunque en vano, alguna tentativa de transacción. Don Sindulfo ejercía cada vez mayor vigilancia, ocultaba a todos, excepto a Benjamín, el trabajo que le absorbía y daba rienda suelta a su pasión con la ilusoria esperanza de la victoria.\"},{\"heading\":false,\"text\":\"La terminación del aparato, coincidiendo con la apertura de la Exposición Universal de 1878, permitió por fin que un día se cargasen varios vagones con todas sus piezas desmontadas; y, encajonados en un coche de primera el inventor, su amigo, la sobrina y el sinapismo de la criada, emprendieron todos súbitamente el camino de París, donde el enamorado tutor se proponía, libre de las persecuciones del húsar, realizar su sueño; lo que no consiguió nunca, como verá el lector que con paciencia quiera seguir el curso de este increíble relato.\"}]},{\"title\":\"El anacronópete — capítulo v\",\"blocks\":[{\"heading\":false,\"text\":\"Cupido y Marte\"},{\"heading\":false,\"text\":\"Mientras se montaba el armatoste en el área que le habían destinado en el palacio de la exposición, don Sindulfo se estableció con su familia en el hotel de la Concordia sito en el boulevard Malesherbes. Inútil es decir que las horas que el sabio se pasaba en el Campo de Marte dirigiendo los trabajos, Clara y Juanita quedaban encerradas bajo llave en sus habitaciones; pues, celoso como un turco, nuestro compatriota temía a cada momento una evasión o un rapto. Cuando sacaba a las muchachas a paseo, siempre lo hacía en coche, y no asistían al teatro sino en palco con celosías.\"},{\"heading\":false,\"text\":\"Todas estas precauciones, la distancia que los separaba de Madrid, la idea de dejar pronto la edad presente y los ineludibles deberes militares de su sobrino que le impedían abandonar su puesto, infundieron cierta tranquilidad relativa en el ánimo de don Sindulfo. Así pasó cerca de un mes viendo disminuir sus temores, cuando una tarde al regresar solo de una sesión del Congreso científico y remontar el lado izquierdo de la Magdalena, sintió como si le tirasen de la levita por detrás. Volvió la cabeza y casi la perdió al encontrarse de manos a boca con Pendencia, el asistente de su sobrino.\"},{\"heading\":false,\"text\":\"--_¿Me da vu de la candel?_ --le dijo este disponiéndose a encender su chicote en el _medianito_ del aturdido zaragozano y traduciendo en lengua de Racine su patrio estilo cordobés.\"},{\"heading\":false,\"text\":\"--¡Un cuerno le daré a usted yo! ¿Qué hace usted en París?\"},{\"heading\":false,\"text\":\"--Puez he venío penzionao por el Gobierno con quince camaradaz máz a las orillaz del Ciena para que aprendan los franceses a jacer zordaoz a nueztra jechura y cemejanza.\"},{\"heading\":false,\"text\":\"Y en efecto, el ministerio de la Guerra enviaba al certamen un individuo de cada arma de que se compone el ejército español, para dar una muestra así de los uniformes como de su envidiable apostura y bizarría.\"},{\"heading\":false,\"text\":\"--¿Y mi sobrino es también de la tanda? --preguntó el sabio presintiendo su desventura.\"},{\"heading\":false,\"text\":\"--¡Ci ez él quien noz manda! Le ezcogieron a pulzo.\"},{\"heading\":false,\"text\":\"--¡Cómo!\"},{\"heading\":false,\"text\":\"--El meniztro le dijo: «Hombre, vaya usté a la dizpocición para que vean allí que todoz no zomoz tan feoz como zu tío de usté.»\"},{\"heading\":false,\"text\":\"--¡Insolente! Comprendo la trama; pero sus inicuos proyectos quedarán frustrados. ¡Ay de él si se atreve a declararme la guerra! Puede usted ir a decírselo de mi parte.\"},{\"heading\":false,\"text\":\"Y como en aquel momento llegasen a la fonda, don Sindulfo se separó bruscamente de Pendencia, que con un: «A la orden, don Pichichi» corrió en busca de su amo, en quien mis lectores habrán ya reconocido al capitán de húsares que al principio de esta historia se apeó del ómnibus en la cabecera del puente.\"},{\"heading\":false,\"text\":\"--¿Quién ha venido? ¿Habéis visto a alguien por el balcón? --fue la primera pregunta formulada por el atribulado tío al entrar en las habitaciones de su sobrina.\"},{\"heading\":false,\"text\":\"--¿Y a quién quiere usted que veamos si nos pone usted candados hasta en las vidrieras? --replicó Juanita con su respingo habitual.\"},{\"heading\":false,\"text\":\"Don Sindulfo no juzgó conveniente dar más explicaciones y se dirigió a su cuarto contiguo al de las reclusas; pero al volverse de espaldas dejó ver unos papeles que, pendientes de un hilo y enganchados a la levita por un alfiler, le había prendido Pendencia durante su trayecto por el boulevard; y de los que Juana se apoderó graciosamente mientras su amo abría la puerta, pues tanto la fregatriz como su señorita estaban seguras de que Cupido había de aprovechar la primera ocasión que se le presentase de comunicar con ellas.\"},{\"heading\":false,\"text\":\"Apenas se quedaron solas empezó la lectura de las cartas. La de Luis encerraba mil protestas de amor para su prima, dándole la seguridad de que en breve se vería libre del yugo de su implacable tío.\"},{\"heading\":false,\"text\":\"La de Pendencia era tan lacónica como digna de conocerse. Decía así:\"},{\"heading\":false,\"text\":\"«Mi coracon es pera, y a esto y acui coma tullo asta la merte ilo es Roce Gomec.»\"},{\"heading\":false,\"text\":\"Juanita, acostumbrada al estilo epistolar de su soldado comprendió que aquello quería decir: «Mi corazón espera. Ya estoy aquí. Coma (o sea la puntuación escrita.) Tuyo hasta la muerte. Y lo es Roque Gómez.»\"},{\"heading\":false,\"text\":\"Al día siguiente Luis ocupaba ya un cuarto en el hotel de la Concordia. Por fortuna don Sindulfo, que marchaba el primero, pudo verle al entrar en el comedor, y retrocediendo antes de que los demás le apercibiesen, volvió a subir las escaleras con todos y dio orden de que en adelante les dieran de comer a él y a los suyos en gabinete aparte. Redobláronse las precauciones: cada vez que el tutor se ausentaba, Benjamín quedábase de centinela; pero, vano empeño; Luis sobornaba al criado de turno y las cartas iban y venían liadas en las servilletas, que era un llover. ¿Descubríase el ajo? ¿Suprimíanse los camareros sirviéndose a sí propios? ¿Prohibíase a Juanita que se acercase a la mesa para cambiar un plato y que saliese de su prisión para nada? Las misivas no por eso dejaban de llegar, ya pegadas con cola en el asiento de los jarros de agua para el tocador, ya en el hueco de un pastelillo que, con una señal convenida de antemano, elegía Clara entre los demás de la fuente, ya por último dentro de una nuez de que era portador un perro de la fonda al que Pendencia había enseñado a escabullirse entre las piernas de don Sindulfo, cada vez que este abría la puerta para recibir por sí mismo los manjares.\"},{\"heading\":false,\"text\":\"Realmente aquello no era vivir; los cien ojos de Argos no bastaban para atender a tantas y tan frecuentes asechanzas. Así es que en cuanto el Anacronópete estuvo en disposición de habitarse, don Sindulfo estableció en él su domicilio obteniendo, bajo pretexto de su custodia, una guardia permanente de dos gendarmes que impedían la aproximación al aparato de todo el que no fuese acompañado por el inventor. Pero si la incorruptibilidad de los guardianes no cedió ni ante las súplicas ni ante las dádivas de Luis, la travesura de su asistente se multiplicó con los obstáculos. Tan pronto mientras los viajeros visitaban los Inválidos, donde ya había hecho él conocimientos, se presentaba con una pierna de palo y unas barbas de chivo sirviendo de cicerone, como envuelto en los andrajos de mendigo, les pedía una limosna en medio de los bulevares, lo que --la mendicidad estando prohibida-- le costaba pasar unas cuantas horas en la prevención. Casi siempre concluía por ser descubierto; así es que don Sindulfo decidió que en lo sucesivo no saldrían más que a misa y en carruaje. Pendencia se disfrazó de cochero; pero se vendió, porque al darle en francés las señas de la Magdalena, él, que no era fuerte en idiomas, los llevó al cementerio del Père Lachaise. Agotados por fin todos los recursos, un día se confabuló con el suizo de la iglesia a que asistían sus compatriotas y, ocupando su puesto a la vanguardia del postulante que durante la ceremonia recoge las limosnas de los fieles, se aprestó a entregar una carta a Clarita; pero la falta de costumbre de circular por entre las filas de los reclinatorios, cargado con la alabarda y el palo de tambor mayor, le hizo enredarse en el espadín en momento tan inoportuno que, cayendo sobre el sabio mientras la peluca se posaba en el devocionario de un caballero y el tricornio en la cabeza de una devota, descubrióse el pastel y don Sindulfo abandonó con su gente el templo regresando al Anacronópete que en adelante quedó convertido para todos sus moradores en prisión celular.\"},{\"heading\":false,\"text\":\"Los días que siguieron a esta catástrofe fueron de desesperación para el enamorado Luis que veía desaparecer sus esperanzas, y para el asistente y sus quince compañeros que sentían aproximarse la hora de la expedición al pasado sin recoger el fruto de sus maquinaciones. El único consuelo del capitán era colocarse con los muchachos en la galería del arco central del palacio de la exposición y contemplar desde allí el Anacronópete que a un centenar de metros se erguía con la sombría majestad de un inmenso sepulcro.\"},{\"heading\":false,\"text\":\"Una tarde, que como de costumbre se hallaban ocupados en esta contemplativa tarea proponiendo quién enviar una misiva encerrada en un proyectil hueco, quién valerse de la balística para lanzar un hilo telefónico, empezaron las nubes a arrojar agua que no parecía sino que se desprendían sobre la tierra las cataratas del cielo.\"},{\"heading\":false,\"text\":\"--Buena va a ponerce la dizpocición ci hay alguna gotera --dijo el asistente prestando oído al diluvio que con fragor se despeñaba por los canalones.\"},{\"heading\":false,\"text\":\"--No hay miedo --le arguyó su amo--. Tal vez los desagües son los trabajos más portentosos de esta fábrica. ¿No has visto los planos expuestos en la sección de París? Las alcantarillas son más altas que esta bóveda.\"},{\"heading\":false,\"text\":\"--¡Cómo! --exclamó Pendencia abriendo desmesuradamente los ojos--. ¿Aquí hay zumieroz?\"},{\"heading\":false,\"text\":\"--¡Qué duda cabe! Mira, el principal circula casi tangente al aparato.\"},{\"heading\":false,\"text\":\"--¡Digo! Turgente y todo, ¿y ce eztá uzté con la lengua pegada al paladar?\"},{\"heading\":false,\"text\":\"--No te entiendo.\"},{\"heading\":false,\"text\":\"--Ci uzté no ha nacido para la guerra. Como genioz militarez Napoleón y yo.\"},{\"heading\":false,\"text\":\"--¿Te explicarás?\"},{\"heading\":false,\"text\":\"--Puez ez muy cencillo. Ci don Cindulfo tiene para zu defenza ezcarpaz y contraezcarpaz, nozotros para el ataque le abrimos minaz y contraminaz. Cabayeroz... al albañal.\"},{\"heading\":false,\"text\":\"Un entusiasta viva acogió la idea del cordobés. Indudablemente la alcantarilla era la última trinchera del amor. Reconocidos los planos vióse con placer que bastaba abrir una galería transversal de pocos metros para encontrarse debajo del centro matemático del Anacronópete. Sobornar al encargado de la limpieza en aquella sección, fue obra tanto más fácil y hacedera, cuanto que el individuo en cuestión era rayano de España por el lado de Canfranc y gustaba de las peluconas de Carlos IV, que Luis no le escaseó para lograr su objeto.\"},{\"heading\":false,\"text\":\"El tiempo apremiaba, pero contra diecisiete españoles, de los cuales la mitad se componía de aragoneses y catalanes, no hay obstáculos, sobre todo tratándose de militares siempre a las órdenes del general _No importa_.\"},{\"heading\":false,\"text\":\"Los picos y azadones fueron abriendo paso; los puntales formando túnel y por último, el día fijado para el inverosímil viaje, mientras don Sindulfo daba su conferencia en el Trocadero acompañado de su inseparable Benjamín, los dieciséis hijos de Marte saludaban la llegada de su capitán con el último golpe de piqueta que los colocaba bajo la plaza enemiga. Al salir del foso se encontraron en una estancia rectangular de la altura de un hombre buen mozo. Era el podio u obra muerta del aparato para precaverle de las humedades en las paradas.\"},{\"heading\":false,\"text\":\"El plan de los invasores era romper a hachazos el suelo del Anacronópete; pero con gran sorpresa suya, se lo encontraron abierto, pues el vehículo tenía en el fondo para la limpieza de la cala una compuerta que funcionaba eléctricamente con el mecanismo de una guillotina horizontal y que, sin duda con el objeto de dar mayor ventilación al piso bajo no se habían cuidado de cerrar, muy ajenos de que por allí pudiera tener efecto un ataque subterráneo.\"},{\"heading\":false,\"text\":\"--¡Arriba! --fue el grito unánime; y transponiendo escaleras, cruzando corredores, invadiendo salas, llegaron a donde estaban las cautivas, que no pudieron reprimir un grito de terror al ver delante de sí a tantos hombres con armas que a prevención para cualquier evento llevaban consigo.\"},{\"heading\":false,\"text\":\"El acto del reconocimiento no hay para qué pintarlo. Siéntanlo los que sepan amar.\"},{\"heading\":false,\"text\":\"--Huyamos, mi bien --fue la primera frase que Luis acosado por el tiempo y las circunstancias acertó a decir a su prima.\"},{\"heading\":false,\"text\":\"--¡Oh! Nunca --le respondió ella--. Cualquiera que sea mi suerte, la soportaré resignada antes que faltar al juramento que hice a mi madre moribunda. Te amaré siempre; pero huir contigo no lo esperes de mí.\"},{\"heading\":false,\"text\":\"Los ruegos, las exhortaciones, las lágrimas eran inútiles ante la irrevocable resolución de aquella hija sumisa y obediente. Perdida parecía ya toda esperanza cuando las aclamaciones de la multitud penetrando en el recinto indujeron a Clara a inquirir el origen de tamaña confusión. Cuando Luis le explicó que obedecía al entusiasmo popular por el invento de su tío, las pobres prisioneras que ignoraban en absoluto los propósitos del tutor, prorrumpieron indignadas en invectivas contra aquel monstruo que con su silencio las obligaba a una peregrinación tan llena de peligros.\"},{\"heading\":false,\"text\":\"--¡Eso es imposible! --balbuceaba la huérfana.\"},{\"heading\":false,\"text\":\"--¡El demonio del sabio! --decía la maritornes--. ¡Pues ni que fuéramos cangrejos para andar hacia atrás!\"},{\"heading\":false,\"text\":\"--¡Digo! Y tú que erez tan echada para adelante.\"},{\"heading\":false,\"text\":\"--¡Huyamos! --repetía Luis apercibiéndose de que la gritería era cada vez más cercana--. Huyamos, no para esconder nuestro amor, sino para pedir a la justicia el amparo que la ley te debe.\"},{\"heading\":false,\"text\":\"Esta juiciosa observación produjo su efecto. Los minutos eran preciosos; el tirano se aproximaba; un espantoso porvenir podía ser el resultado de aquella perplejidad.\"},{\"heading\":false,\"text\":\"--Sea pues --exclamó la pupila resueltamente.\"},{\"heading\":false,\"text\":\"Y todos se encaminaron a la mina.\"},{\"heading\":false,\"text\":\"Pero al querer penetrar por la abertura la encontraron obstruida.\"},{\"heading\":false,\"text\":\"Un desprendimiento del terreno les había cortado la retirada.\"}]},{\"title\":\"El anacronópete — capítulo vi\",\"blocks\":[{\"heading\":false,\"text\":\"El vehículo considerado como escuela de moral\"},{\"heading\":false,\"text\":\"Qué hacer en circunstancias tan adversas? Los pusilánimes proponían permanecer en el espacio hueco del podio y esperar a que el Anacronópete al elevarse les permitiera salir; pero sobre correr el riesgo de ser descubiertos si se notaba la falta de las cautivas, exponíanse --aun salvando esta eventualidad-- a ser pulverizados por una desviación del vehículo en el momento del arranque. Los más resueltos optaban por romper la puerta y conquistar la salida con las armas. Este plan se desechó por violento e infecundo, prevaleciendo al fin la idea sugerida por los prudentes, de ocultarse y aguardar la ocasión propicia de emprender la fuga.\"},{\"heading\":false,\"text\":\"La cala estaba por fortuna harto provista de materiales de construcción, destinados a las reparaciones, y de vituallas de toda especie para que no abundasen los escondrijos. Fuéronse pues metiendo los unos tras la pipería de los caldos, los otros en los intersticios de los balotes de gramíneas; y así se formaban parapetos con los sacos de harina y los cajones de conservas, como se atrincheraban en los montones de legumbres o hacían reducto del sarcófago de la momia.\"},{\"heading\":false,\"text\":\"Clara recomendó a todos la mayor prudencia exhortándoles a no moverse hasta que ella o Juanita viniesen en su busca, lo que, en nombre de sus compañeros, le fue prometido solemnemente por Pendencia, excitando una carcajada unánime al asomar la cara embadurnada de blanco por efecto de sus frotaciones contra unos costales de candeal.\"},{\"heading\":false,\"text\":\"Mientras esta escena tenía lugar en el Anacronópete, fuera ocurrían incidentes dignos de ser narrados.\"},{\"heading\":false,\"text\":\"Concluida la conferencia, don Sindulfo, como hemos visto, empezó su marcha triunfal desde el Trocadero al Campo de Marte entre los vítores de la multitud frenética y dos filas de guardia nacional que la villa de París había puesto a su disposición para conservarle el paso expedito. Una vez dentro del área de la exposición, el _maire_ invitó al sabio a reposarse breves momentos en una elegante tienda de campaña levantada _ad hoc_ cerca del Anacronópete, en el centro de la cual veíase una mesa capaz de satisfacer la intemperancia de Lúculo y de emular la esplendidez de los festines de Cleopatra. Era el _lunch_ de despedida ofrecido por la municipalidad de París al insigne inventor, pues parece imposición de la naturaleza, respetada por la costumbre, que en todo regocijo público el estómago haya de meter la primera cucharada.\"},{\"heading\":false,\"text\":\"Sentáronse anfitriones, convidados y parásitos (planta que brota espontáneamente en todos los comedores) y, con el reposo del cuerpo, dio principio el trabajo de las mandíbulas. Durante los encurtidos, los torsos formaban con la mesa un ángulo recto. A medida que el lastre iba estibando el aparato digestivo, el ángulo se convertía en agudo. Al sonar la hora del champagne los lados móviles trataron de reconquistar el equilibrio; pero la perpendicular al mantel no pudo restablecerse y, dando por tope a los omoplatos el respaldo de los sillones, el ángulo obtuso dominó en toda la línea.\"},{\"heading\":false,\"text\":\"Entonces empezaron los brindis, peores unos que otros, si bien todos malos, pues no hay nada que limite tanto la inteligencia como el elogio. Así es que, haciendo gracia de ellos al asendereado lector, me limito a extractar lo único que en aquel cúmulo de peroraciones hubo de bueno, que fue precisamente lo que no tuvieron de alabanza.\"},{\"heading\":false,\"text\":\"El bibliotecario de la Sorbona, levantándose del asiento y sacando a luz un primoroso ejemplar de la _Iliada_, publicado recientemente a expensas de la sociedad bibliófila, rogó a don Sindulfo que al pasar por la olimpiada en que floreció el padre de la epopeya, obtuviese de Homero que le firmase su obra magna corrigiendo los yerros tipográficos que encontrase y consignando bajo el testimonio de su facsímil si fue en Quío o en Esmirna donde vio la luz primera.\"},{\"heading\":false,\"text\":\"--Propongo que se substituya esa última frase por esta otra: «En dónde nació» --interpuso un académico de la historia--. Porque --prosiguió-suponiendo que la lógica fuese en aquellos tiempos fabulosos una ciencia tan exigente como lo es en nuestros días, nos exponemos a seguir ignorando cuál fue la patria del cantor de Troya, si al preguntarle dónde vio la luz primera, él lo toma _pedem literæ_ y nos contesta que en ninguna parte por ser ciego de nacimiento.\"},{\"heading\":false,\"text\":\"Aprobada la enmienda, tocole el turno al presidente de la junta de agricultura, quien en correcta frase --pues era un poeta el encargado de velar por los intereses agrícolas del país-- encareció a don Sindulfo casi en verso, la necesidad de combatir los efectos del _oidium_ y de la _philoxera_ en las vides: para lo cual creía el medio más seguro hacerse con unos sarmientos de la viña de Noé a fin de reproducirlos en Francia.\"},{\"heading\":false,\"text\":\"Esta proposición levantó una tempestad de aplausos, pues nadie ignora que el vino es una de las principales riquezas del suelo transpirenaico, cuya producción aunque fabulosa, por poco que la cosecha flojee ya no alcanza a cubrir las necesidades del consumo.\"},{\"heading\":false,\"text\":\"Muchas más fueron las ideas que, dirigidas todas al mejoramiento de la condición humana, se desarrollaron en la sobremesa, e infinitos los encargos particulares y de índole risible que se hicieron al doctor. Ya era un empresario de teatros quien le abría un crédito incondicional con el fin de que ajustase a Molière para dar doce representaciones antes de que se cerrara la exposición. Ya un tipógrafo quien se comprometía a trasladarse a la Grecia del siglo de Pericles, con el objeto de imprimir las conferencias de Sócrates y publicar un periódico político.\"},{\"heading\":false,\"text\":\"Don Sindulfo dio las gracias a todos y a cada cual; objetó que aquel su primer viaje no tenía otro carácter que el de exploración, y, ofreciendo desempeñar cuantas pudiera de las diferentes comisiones que se le confiaban, dio por concluido el acto.\"},{\"heading\":false,\"text\":\"No había llegado aún a la puerta cuando el prefecto de policía, apeándose de su carruaje, penetró en el pabellón y se dirigió al sabio.\"},{\"heading\":false,\"text\":\"--¿Puede el señor García acordarme una conferencia de breves minutos? --le dijo.\"},{\"heading\":false,\"text\":\"--Hiciéralo con placer si no fuese ya la hora reglamentaria y temiese abusar de la impaciencia pública.\"},{\"heading\":false,\"text\":\"--Me trae aquí una misión oficial. Vengo en nombre del gabinete.\"},{\"heading\":false,\"text\":\"Ante esta observación no había medio de insistir. Los comensales se retiraron prudentemente a un extremo de la tienda, mientras en el opuesto los dos interlocutores sostenían el siguiente diálogo:\"},{\"heading\":false,\"text\":\"--El gobierno me delega para pedirle a usted un señalado servicio.\"},{\"heading\":false,\"text\":\"--Me honra tal confianza. Escucho a usted.\"},{\"heading\":false,\"text\":\"--A nadie se le oculta que la Francia, desgraciadamente, atraviesa un período de relajación moral que amenaza destruir los ya minados cimientos de la familia, fundamento de todas las sociedades.\"},{\"heading\":false,\"text\":\"--Aunque con dolor, me es fuerza asentir a tan acertado parecer.\"},{\"heading\":false,\"text\":\"--El gobierno, más interesado que nadie en la redención de su patria, ha penetrado con ánimo resuelto en el fondo de esta cuestión pavorosa; y cree poder afirmar que el quebrantamiento de los vínculos sociales proviene de ese escandaloso mercado sensual con que no ya emulamos, sino trasponemos el histórico y poco plausible renombre de Síbaris y Capua.\"},{\"heading\":false,\"text\":\"--Evidentemente; mas no alcanzo cuál pueda ser la parte que me incumba en esa misión redentora.\"},{\"heading\":false,\"text\":\"--A eso voy. Regenerar a la mujer es crear buenas madres de que carecemos.\"},{\"heading\":false,\"text\":\"--No, en absoluto.\"},{\"heading\":false,\"text\":\"--Es usted muy amable. Gracias por la mía. Tener madres es garantizar la educación de los hijos. De los buenos hijos germinan los esposos modelos y los íntegros ciudadanos. Luego hay que purificar la familia para salvar la patria.\"},{\"heading\":false,\"text\":\"--Estamos de acuerdo.\"},{\"heading\":false,\"text\":\"--Ahora bien; de esas desgraciadas mujeres, que, para vergüenza de propios y extraños, arrastran sus vicios por nuestras populosas ciudades pregonando con histéricas carcajadas su mercancía, pocas, contadas, son las que consiguen un resultado beneficioso que consolide su existencia en la vejez. Los hospitales, los teatros, las porterías suelen constituir su última trinchera; y muchas hay que al perder la menguada lozanía de los primeros años volverían con arrepentimiento a la senda de la virtud, a no impedírselo el estado en que los excesos y la depravación las han sumido y que las hacen ineptas para los puros goces de la familia. El gabinete, pues, en consejo extraordinario, me encarga ser intérprete de sus sentimientos cerca de usted y me comisiona para dirigirle a usted una proposición.\"},{\"heading\":false,\"text\":\"El prefecto acercó más aún su silla a la de don Sindulfo y prosiguió de esta manera:\"},{\"heading\":false,\"text\":\"--¿Hemos entendido mal o es cierto que con el maravilloso vehículo de su invención puede el navegante rejuvenecerse a medida que retrograde en el tiempo?\"},{\"heading\":false,\"text\":\"--Así es, con tal de que previamente no se haya sometido a la inalterabilidad de las corrientes del fluido que lleva mi nombre; pues de otro modo vería pasar los siglos sin experimentar alteración alguna.\"},{\"heading\":false,\"text\":\"--¿En qué tiempo puede usted recorrer un espacio de veinte años?\"},{\"heading\":false,\"text\":\"--En una hora.\"},{\"heading\":false,\"text\":\"--¿Y llegado a ese término, le es a usted dable perpetuar la edad de la persona en el punto porque entonces atraviese?\"},{\"heading\":false,\"text\":\"--Sin ningún obstáculo.\"},{\"heading\":false,\"text\":\"--Pues bien. El plan del gobierno es rogar a usted que acepte en la expedición una docena de señoras que frisen en los cuarenta (edad en que la vejez no las ha hecho aún desistir de las ilusiones; pero harto avanzada en mujeres de su condición para abrigar esperanzas de medro), y ofrecerles que en sesenta minutos van a reconquistar sus veinte abriles. De este modo, es indudable que, aleccionadas por la experiencia, y arrepentidas por el fracaso, al encontrarse dueñas de sus hechizos por segunda vez, sigan la senda de la morigeración y abandonen la del vicio.\"},{\"heading\":false,\"text\":\"--Plausible es la intención. ¿Pero no teme usted, señor prefecto, que si lo que entra con el capillo no sale sino con la mortaja, las buenas señoras al verse en el pleno ejercicio de sus facultades quieran volver a tentar fortuna?\"},{\"heading\":false,\"text\":\"--No lo espero. De todos modos este no es más que un ensayo de que desistiremos si no salimos airosos, o que en caso contrario repetiremos en grande escala. ¿Qué responde usted al ministerio?\"},{\"heading\":false,\"text\":\"--La misión me honra sobremanera para rechazarla; pero debo advertir a usted que yo viajo con mi sobrina y...\"},{\"heading\":false,\"text\":\"--No tema usted el menor desafuero. Se portarán dignamente. Ya las hemos exhortado y el miedo al castigo las contendrá.\"},{\"heading\":false,\"text\":\"--Lo celebraría aunque lo dudo.\"},{\"heading\":false,\"text\":\"--Se lo aseguro a usted; la amenaza es temible.\"},{\"heading\":false,\"text\":\"--¿Cuál se les ha impuesto?\"},{\"heading\":false,\"text\":\"--No quitarles ni un año de encima si se exceden en algo.\"},{\"heading\":false,\"text\":\"--Tiene usted razón; me tranquilizo.\"},{\"heading\":false,\"text\":\"--¿Estamos de acuerdo?\"},{\"heading\":false,\"text\":\"--Completamente.\"},{\"heading\":false,\"text\":\"--El gobierno sabrá recompensar a usted favor tan señalado.\"},{\"heading\":false,\"text\":\"--Me basta conseguir por premio que Francia sea digna en el orden moral de la supremacía que por tantos otros conceptos se ha conquistado en el mundo.\"},{\"heading\":false,\"text\":\"Terminada la entrevista, el cortejo con don Sindulfo a la cabeza salió del pabellón, a cuya puerta esperaban en sus carruajes las alegres expedicionarias que, apeándose, se agregaron al grupo oficial, tomando todos juntos la dirección del Anacronópete.\"},{\"heading\":false,\"text\":\"Llegados al pie del coloso cruzóse un último adiós. El sabio, Benjamín y las viajeras penetraron en el vehículo y este, herméticamente cerrado, atrajo desde aquel momento las miradas de todos los circunstantes.\"},{\"heading\":false,\"text\":\"No habría transcurrido un cuarto de hora, cuando un murmullo de dos millones de almas onduló en el espacio. El Anacronópete se elevaba con la majestad de un montgolfier. Nadie aplaudía porque no había mano que no estuviese provista de algún aparato óptico; pero el entusiasmo se traducía en ese silencio más penetrante que el ruido mismo.\"},{\"heading\":false,\"text\":\"Llegado a la zona en que debía tener lugar el viaje, el monstruo, reducido al tamaño de un astro, se paró como si se orientara. De repente estalló un grito en la multitud. Aquel punto, bañado por un sol canicular, había desaparecido en el firmamento con la brusca rapidez con que la estrella errática pasa a nuestros ojos de la luz a las tinieblas.\"}]},{\"title\":\"El anacronópete — capítulo vii\",\"blocks\":[{\"heading\":false,\"text\":\"¡Marchen!\"},{\"heading\":false,\"text\":\"Constaba el Anacronópete, como hemos dicho, de un podio o basamento sobre el que descansaba el suelo de la bodega, y en el espesor de cuyo muro veíanse empotrados los escalones que daban acceso al portón, única entrada del vehículo. La forma de este era rectangular. En sus ángulos erguíanse cuatro formidables tubos correspondientes a los aparatos de desalojamiento que, con sus bocas retorcidas en dirección de los puntos cardinales, parecían otros tantos enormes trabucos arqueados en figura de 7. En el piso principal, y corriendo por sus cuatro lados, circulaba una elegante galería cuya puerta, como todas las demás aberturas del locomóvil, quedaba herméticamente cerrada en viaje. Un inmenso disco de cristal, rasante por cada viento a la pared, servía a los viajeros para desde el interior y con el auxilio de potentes instrumentos ópticos, contemplar el paisaje y rectificar la orientación durante la marcha. Dos frontones coronaban los testeros ostentando en sus tímpanos el nombre del coloso y sosteniendo en sus caballetes la cubierta en plano inclinado, así dispuesta para las paradas; pues en movimiento --navegando por el vacío-- ni había que cuidarse de los desagües ni precaverse contra las afecciones atmosféricas.\"},{\"heading\":false,\"text\":\"Exteriormente, era pues el Anacronópete una especie de arca de Noé sin quilla; toda vez que sus funciones no se relacionaban con el líquido elemento y que, para flotar en caso necesario, bastábale la tripa que, a modo de los antiguos navíos, arrancaba del suelo de la cala y se contraía debajo del balcón sirviéndole de soporte. Examinémosle ahora por dentro.\"},{\"heading\":false,\"text\":\"La planta baja la ocupaba toda la bodega a excepción del pequeño espacio --destinado a vestíbulo y a la escala espiral-- que constituía la entrada de honor para las dependencias superiores, de las que se descendía a la cala por otra escalera de caracol levantada en uno de los ángulos. En el opuesto veíase el aparato del fluido García, con cuyas corrientes hacíanse inalterables los cuerpos; precaución tomada ya de antemano con cuantos materiales de construcción y provisiones de boca había a bordo. Enfrente de aquel, funcionaba el mecanismo Reiset y Regnaut para producir el oxígeno respirable. Tanto este aparato como el de la inalterabilidad estaban prudentemente reproducidos diversas veces en el Anacronópete, aunque sus efectos podían hacerse sentir en cualquiera parte con el auxilio de conductores. También las pilas eléctricas tenían los suyos diseminados por el vehículo, para llevar las corrientes a donde se necesitara un movimiento, porque allí toda actividad era mecánica. Así por ejemplo; la compuerta que, en forma de guillotina horizontal, dio acceso como hemos visto a los hijos de Marte, correspondía con otra de idéntica estructura tallada en el suelo del piso alto. ¿Queríase cargar el Anacronópete? Pues no había más que elevarle convenientemente, colocar debajo las mercancías, aplicarles un conductor y ellas solas subían por las aberturas hasta dar con los aisladores que paralizaban su ascensión en el punto deseado. La limpieza tenía lugar por el mismo procedimiento. Unas escobas mecánicas barrían los espacios libres y conducían los residuos sobre la trampa del piso principal. Abierta esta caían las escorias sobre la cala y, repetida allí la operación, un bostezo de la guillotina las arrojaba fuera; de modo que bastaba empezar en lunes el barrido para en un segundo encontrarse con el sábado hecho.\"},{\"heading\":false,\"text\":\"En la planta alta residía el poderoso agente de la locomoción: la electricidad. Nada tan interesante como el relato de su mecanismo; pero como esto nos llevaría muy lejos y el lector, aceptado el principio, ha de hacerme gracia de las explicaciones técnicas, limítome a decirle que del centro de aquella zona lanzaban las pilas sus torrentes de fluido a todas las articulaciones encargadas de producir el movimiento y a los tubos neumáticos repulsores de la atmósfera. Un elegante registro marcaba la velocidad y una sencilla aguja la regulaba. En la misma pieza estaban el observatorio y el laboratorio con sus lentes, retortas, mapas, compases, bibliotecas, aerómetros y utensilios cronográficos. En las crujías laterales y con el sistema de los camarotes, alternaban por el ala derecha, el gabinete de señoras con el cuarto de baño y la despensa con la cocina; en la que sobre una plancha colocábase un pollo vivo que una descarga eléctrica desplumaba, mientras un chispazo lo convertía en comestible, siete mil doscientas veces más pronto que cualquier asador común.\"},{\"heading\":false,\"text\":\"El lavadero, situado en la extremidad posterior del eje, era un prodigio. Entraba la ropa sucia por un lado y salía por el otro, lavada, planchada, seca y zurcida.\"},{\"heading\":false,\"text\":\"El ala izquierda se la había reservado íntegra el sexo fuerte, y nada tenía de notable a no ser el departamento de los relojes; en que uno marcaba la hora real en la existencia efectiva y otro la relativa al momento histórico del viaje con expresión del siglo, año, mes y día según el cómputo Gregoriano.\"},{\"heading\":false,\"text\":\"Cuando después del entusiasta y último adiós de las corporaciones, los sabios penetraron en su baluarte, el primer cuidado de don Sindulfo fue alojar bajo llave en el cuarto de las colecciones, a las atónitas agregadas, con intimación de no moverse de allí hasta que él fuera en su busca; pues por más confianza que le mereciesen sus protestas, él creía, y con razón, que las rejas no perjudicaban a los votos. En seguida y de una sola conmoción eléctrica dejó herméticamente cerrado el Anacronópete; hecho esto propinó a Benjamín unas descargas del fluido de la inalterabilidad, recibiendo él otras tantas de mano de su amigo.\"},{\"heading\":false,\"text\":\"--Ya no puede el tiempo ejercer su influencia sobre nosotros --exclamó con aire de triunfo una vez terminada la operación.\"},{\"heading\":false,\"text\":\"--¿No cree usted sin embargo --objetó su inseparable-- que nada perdíamos con esperar para fijarnos a que el Anacronópete llevase algunos minutos de marcha?\"},{\"heading\":false,\"text\":\"--Comprendo la intención de usted, y nadie más interesado que yo en perder algunos años para ver si rejuveneciéndome cesaban los rigores de mi sobrina; pero si a usted o a mí, únicos que conocemos este mecanismo, nos sobreviniera un accidente cualquiera ¿cuál sería nuestra suerte disparados sin rumbo en el espacio y qué responsabilidad no pesaría sobre nosotros dejando insoluble el más gigantesco de los problemas científicos?\"},{\"heading\":false,\"text\":\"La observación era tan justa, que el políglota no tuvo nada que objetar. Verdad es que todo hubiera sido inútil, pues, una vez fijados, solo la acción regular del tiempo hubiera tenido poder para destruir la producida por el fluido.\"},{\"heading\":false,\"text\":\"Dirigiéronse por lo tanto al gabinete de señoras, donde Clara y Juanita se habían refugiado como los chicos que se esconden cuando creen haber hecho algún mal; y conduciéndolas capciosamente al laboratorio, mientras Benjamín conseguía con maña que las muchachas se pusiesen en contacto con los conductores, don Sindulfo las volvía inalterables con un par de descargas que las hizo retorcerse como culebras.\"},{\"heading\":false,\"text\":\"--Oiga usté --dijo la de Pinto encarándose con su amo así que pudo enderezarse y articular palabra--, si es que usté quiere no seguir comiendo más que sémola, repita usted esa operación y verá usted salirle muelas... de la boca. ¿Para qué ha dado usted esas vueltas al organillo que nos ha dejado como si tuviésemos alferecía?\"},{\"heading\":false,\"text\":\"--Menos gritos --le arguyó su amo--. Aquí estáis bajo mi férula. Empezó mi dominio y no hay para qué pedirme explicaciones de mi conducta. Vuestra misión es obedecer y callar.\"},{\"heading\":false,\"text\":\"--En cuanto a eso, poco a poco --interpuso Clara.\"},{\"heading\":false,\"text\":\"--¡Cómo! ¿Te me insubordinas?\"},{\"heading\":false,\"text\":\"--No señor; pero protesto de que haya usted abusado de nuestra ignorancia, para obligarnos por sorpresa a emprender un viaje sin precedente en el mundo.\"},{\"heading\":false,\"text\":\"--¿Y quién te ha dicho?...\"},{\"heading\":false,\"text\":\"--¿Quién ha de ser, hombre de Dios, sino la mismísima milicia española que se está burlando de usté, a pesar de saber más matemáticas que Motezuma?\"},{\"heading\":false,\"text\":\"--¿Qué oigo? ¿Ha encontrado Luis medio de hacerte llegar alguna carta? --preguntó el sabio aturdido y sin sospechar que, no obstante su tiranía, hubiera podido ser el capitán esquela viviente.\"},{\"heading\":false,\"text\":\"--¡Digo, digo, una carta!... Toda una baraja completa para hacerle a usted tute.\"},{\"heading\":false,\"text\":\"--Procura no ser insolente, porque de lo contrario en llegando a la Roma de los Césares, te vendo como esclava al primer patricio que encuentre en la calle.\"},{\"heading\":false,\"text\":\"--¿Y qué van a hacerme a mí los patricios? ¡Pues qué! ¿Yo no vengo de liberales? Mi padre fue furriel de voluntarios.\"},{\"heading\":false,\"text\":\"--Oiga usted nuestros ruegos.\"},{\"heading\":false,\"text\":\"--Nunca.\"},{\"heading\":false,\"text\":\"--Si le digo a usted que el tal don Pichichi es el Calomarde de los tíos.\"},{\"heading\":false,\"text\":\"--Se concluyeron las intrigas --vociferaba don Sindulfo lívido de coraje--. Se acabaron los amorcillos de colegiala: y ya que a buenas no has querido aceptar mi mano, yo te sabré conducir a países y edades en que la voluntad del tutor siendo ley para su pupila, mal que te pese tendrás que llamarte mi esposa.\"},{\"heading\":false,\"text\":\"--Eso jamás. Primero la muerte; antes la tortura. Y pues agotada la persuasión recurre usted a la violencia, yo le probaré que tengo valor para afrontarlo todo.\"},{\"heading\":false,\"text\":\"Y dirigiendo una mirada de connivencia a Juanita, añadió:\"},{\"heading\":false,\"text\":\"--En marcha cuando usted guste.\"},{\"heading\":false,\"text\":\"--Sí, señor. Arre; que en el primer cambio de tiro ya nos apearemos para quejarnos a la autoridad.\"},{\"heading\":false,\"text\":\"El sabio no se hizo repetir la orden; juntó los polos y el Anacronópete comenzó su marcha ascensional, no sin cierta emoción de parte de las reclusas que veían desaparecer por instantes los contornos de la ciudad bajo sus plantas.\"},{\"heading\":false,\"text\":\"En el cuarto de las agregadas, la impresión fue más viva por estar esperando con más impaciencia los resultados del viaje. En la cala, el silencio era absoluto. Solo Pendencia se permitió decirle en voz baja a su jefe, al apercibirse de la oscilación:\"},{\"heading\":false,\"text\":\"--Mi capitán: el botacilla.\"},{\"heading\":false,\"text\":\"De repente el coloso tomó rumbo y empezó a desalojar atmósfera sin que nadie se apercibiera de que viajaban con una velocidad de dos vueltas al mundo por segundo; pues la locomoción, verificándose en el vacío, falta de capas con que rozar no producía movimiento alguno sensible.\"},{\"heading\":false,\"text\":\"--Ya andamos --exclamó don Sindulfo con el orgullo paternal que le inspiraba su invención.\"},{\"heading\":false,\"text\":\"--Adelante --prorrumpió resueltamente su sobrina.\"},{\"heading\":false,\"text\":\"--¡Loor al genio! --balbuceó Benjamín abrazando a su protector.\"},{\"heading\":false,\"text\":\"--¡Jesús! --decía Juana--. Si esto es más soso que un cocido sin sal. Ni se ve un campanario, ni una lechuga, ni _ná_ que le pueda alegrar a una el corazón. Prefiero el ordinario de mi pueblo. Vamos, don Sindulfo, _sóoo_... En llegando a los Inválidos pare usted.\"},{\"heading\":false,\"text\":\"La pobrecilla no calculaba que había empezado su frase en París el diez de julio de mil ochocientos setenta y ocho y que la estaba acabando en treinta y uno de diciembre del año anterior sobre la cordillera de los Andes.\"}]},{\"title\":\"El anacronópete — capítulo viii\",\"blocks\":[{\"heading\":false,\"text\":\"Efectos retroactivos\"},{\"heading\":false,\"text\":\"Las suertes estaban echadas y no había medio de retroceder, o mejor dicho, de avanzar, si queremos ser lógicos con la situación. Clara y Juanita se retiraron al gabinete, confiadas en la vecindad de sus defensores y dispuestas a exhibirlos en el primer alto que hicieran; pues en marcha les parecía aventurado sacarlos de su escondite, temerosas de que don Sindulfo, por vengarse, los condenara a todos a movimiento continuo.\"},{\"heading\":false,\"text\":\"El sabio por su parte no se saciaba de saborear su triunfo con Benjamín; y verdaderamente no le faltaba razón para ello, pues jamás experimento alguno había tenido éxito tan satisfactorio.\"},{\"heading\":false,\"text\":\"--¡_Eureka_! --exclamó en un arranque de entusiasmo aquel segundo Arquímedes que, sin el auxilio de una palanca, removía el mundo hasta en sus cimientos.\"},{\"heading\":false,\"text\":\"--¿A qué altura estamos? --preguntó el políglota.\"},{\"heading\":false,\"text\":\"--Hace veintiún minutos que salimos de París --le contestó su amigo consultando el cronómetro--; por consiguiente hemos desandado siete años y nos hallamos en diez de julio de mil ochocientos setenta y uno.\"},{\"heading\":false,\"text\":\"--¿Estudiemos la situación?\"},{\"heading\":false,\"text\":\"--Sea.\"},{\"heading\":false,\"text\":\"--Rumbo a oriente --dijo Benjamín clavando los ojos en su compás.\"},{\"heading\":false,\"text\":\"--Fijo --asintió el sabio mirando el suyo.\"},{\"heading\":false,\"text\":\"--Latitud 50° N.\"},{\"heading\":false,\"text\":\"--Exacto.\"},{\"heading\":false,\"text\":\"--No hay más que inclinar los catalejos un grado al Sur y dirigir nuestras observaciones sobre el punto de partida.\"},{\"heading\":false,\"text\":\"Y asestando los anteojos al disco meridional, cuyas puertas se abrieron de una descarga, ambos profesores se pusieron a sondear el espacio. Por supuesto que previamente apagaron las luces eléctricas que constituían el alumbrado constante de aquella hermética clausura donde siempre era de noche; pues como el vacío solo se hacía alrededor del Anacronópete, las capas atmosféricas inmediatas a él conducían los rayos del sol; y de no haber tenido cerrado el vehículo, nadie hubiera podido resistir las vertiginosas intermitencias de luz y sombra ocasionadas por la violenta transición del día a la noche en una velocidad de cuarenta y ocho horas por segundo.\"},{\"heading\":false,\"text\":\"Pocos llevaban de observación los anacronóbatas sin apercibir en su carrera más que el vapor iluminado con que como aliento fosforescente, les anunciaban su presencia las ciudades en el período nocturno, o las grandes siluetas de las mismas bañadas por el sol y recortadas sobre el fondo oscuro del terreno durante el día, cuando de repente los dos observadores lanzaron un grito tan rápido como fugaz había sido la sensación que experimentaran. En medio de las tinieblas y sobre el meridiano de París, el reflejo de una inmensa hoguera acababa de herir su retina.\"},{\"heading\":false,\"text\":\"--¡La _Commune_! --exclamaron ambos.\"},{\"heading\":false,\"text\":\"Y en efecto, aquel resplandor era el petróleo de los pozos norteamericanos oponiendo en vano su devastadora influencia al sentimiento de civilización de la vieja pero noble Europa.\"},{\"heading\":false,\"text\":\"Los sabios no se movieron de su observatorio hasta dar con otro hecho ostensible que ratificara sus deducciones cronológicas; pocos segundos les bastaron para transponer la primavera y cruzar aquel riguroso invierno teatro de la más espantosa de las luchas internacionales, y digno campo de la locura humana. La tierra era una inmensa sábana de nieve, como si el frío del terror sembrado en las campiñas hubiera germinado en cosechas de hielo. El astro rey no se reflejaba sino en mortíferas superficies de acero y bronce, y las parábolas de los proyectiles parecían arcos de fuego levantados en las sombras para impedir que se desplomase la bóveda sideral. Globos aerostáticos confiando a una corriente atmosférica la salvación de la patria, palomas mensajeras volviendo al arca sin el ramo de olivo, París capitulando, Metz cediendo, Sedán dejando huérfana una corona... ¿A qué más efemérides? El cómputo era exacto. Estaban en el año de los castigos.\"},{\"heading\":false,\"text\":\"Cerradas las compuertas y vuelta a iluminar la estancia:\"},{\"heading\":false,\"text\":\"--Maestro; una duda --exclamó Benjamín.\"},{\"heading\":false,\"text\":\"--¿Cuál?\"},{\"heading\":false,\"text\":\"--Puesto que nosotros nos dirigimos al ayer y vamos a llegar al pasado con la experiencia de la historia, ¿no nos sería dable cambiar la condición humana evitando los cataclismos que tamañas dislocaciones han producido en la sociedad?\"},{\"heading\":false,\"text\":\"--Aclare usted su pensamiento.\"},{\"heading\":false,\"text\":\"--Supongamos que caemos sobre el Guadalete en las postrimerías del imperio godo.\"},{\"heading\":false,\"text\":\"--¿Y bien?\"},{\"heading\":false,\"text\":\"--¿No cree usted que dando un curso de moral a la Cava y a don Rodrigo, o haciendo ver al conde don Julián por medio de la lectura de Cantú, Mariana y Lafuente, las consecuencias de su traición, lograríamos torcer el rumbo de los acontecimientos e impedir que hubiera tenido lugar la dominación árabe en España?\"},{\"heading\":false,\"text\":\"--De ningún modo. Nosotros podemos asistir como testigos presenciales a los hechos consumados en los siglos precedentes; pero nunca destruir su existencia. Más claro; nosotros desenvolvemos el tiempo, pero no lo sabemos anular. Si el hoy es una consecuencia del ayer y nosotros somos ejemplares vivos del presente, no podemos, sin suprimirnos, aniquilar una causa de que somos efectos reales. Un símil le patentizará a usted mi teoría. Figúrese usted que usted y yo somos una tortilla hecha con huevos puestos en el siglo VIII. ¿No existiendo los árabes, que son las gallinas, existiríamos nosotros?\"},{\"heading\":false,\"text\":\"Benjamín recapacitó un momento, después de lo cual repuso:\"},{\"heading\":false,\"text\":\"--¿Y por qué no? Aun admitiendo la hipótesis de que ambos seamos descendientes del moro Muza, el evitar que este y los suyos penetren en España no impide nuestra existencia. Yo no destruyo las gallinas; lo que hago es obligarlas a que sigan poniendo en África. Luego la tortilla puede subsistir sin otra diferencia que tener el Atlas por hornillo en lugar del Guadalete.\"},{\"heading\":false,\"text\":\"Don Sindulfo se mordió los labios no encontrando refutación al argumento de su amigo que él calificó de paradójico, y cortó la conversación abriendo el pupitre y disponiendo a anotar en su diario las observaciones de la derrota. Benjamín a su vez dirigióse al armario en que encerraba los más preciados ejemplares de su museo arqueológico y se entretuvo en comprobar las clasificaciones.\"},{\"heading\":false,\"text\":\"Dejémosles entregados a tan sabia tarea y veamos lo que en el ínterin ocurría en el cuarto de las colecciones, donde esperaban impacientes su transformación las doce hijas de Eva en que el gobierno francés fundaba la regeneración moral de su país.\"},{\"heading\":false,\"text\":\"A aquellos de mis lectores que hayan visitado la Francia, y lo serán todos probablemente, no hay para qué hacerles la descripción de los trajes de las viajeras. Teniendo el lujo por cebo y el arte de agradar por oficio, fácilmente se colige que las tales señoras habían puesto a contribución para adornarse todo el ingenio de la industria sedera de Lyon, agotado los maravillosos recursos que posee la fabricación de encajes en Cluny y Valenciennes y engarzado en el oro de California los diamantes del Brasil, las esmeraldas de Colombia y las perlas del golfo de Bengala.\"},{\"heading\":false,\"text\":\"--Y bien, Niní; ¿qué tal va eso? --preguntó a una esbelta rubia otra que acusaba haber sido incitante morena en sus mocedades y que respondía al nombre de Naná, pues todas tenían el suyo artístico.\"},{\"heading\":false,\"text\":\"--Por ahora no puede decirse nada; pero si la prefectura me vuelve a mis quince años, le juro no casarme sino con un hombre que vote siempre por el gobierno. Hay que ser agradecida.\"},{\"heading\":false,\"text\":\"--Cualquier día me uncen a mí --repuso desde su rincón una nerviosilla que con una carta se estaba entreteniendo en doblar pajaritas de papel.\"},{\"heading\":false,\"text\":\"--¿Pues cuáles son tus propósitos, Emma?\"},{\"heading\":false,\"text\":\"--Hacer que me desembarquen en la corte de Luis XV y pedir que me presenten a S. M.\"},{\"heading\":false,\"text\":\"--Lo que es yo --dijo otra que se llamaba Sabina-- primero me dejo robar por los romanos que volver a París a vestirme de percal y dormir sobre un felpudo.\"},{\"heading\":false,\"text\":\"--Pero hemos dado nuestra palabra --insistió Niní.\"},{\"heading\":false,\"text\":\"--Pensad que la regeneración de la Francia depende de nosotras.\"},{\"heading\":false,\"text\":\"--Para la que se fíe de promesas oficiales --arguyó Emma--. En cuanto nos viesen jóvenes y bonitas, los mismos que hoy nos toman por instrumentos de rehabilitación serían los primeros en querer venir a turbar nuestra paz doméstica. ¡Ah! ¡Los hombres! ¡Los hombres!...\"},{\"heading\":false,\"text\":\"Y como siguiese jugueteando con la pajarita, observó que se le pulverizaba sin que sus dedos la triturasen.\"},{\"heading\":false,\"text\":\"--Aquí tenéis la prueba --añadió explicando a su modo el fenómeno y dando cima a su pensamiento--. Escriben sus protestas de amor sobre papel podrido para que duren poco.\"},{\"heading\":false,\"text\":\"--Eso es el fuego de la pasión que calcina el papel --objetó la optimista Niní.\"},{\"heading\":false,\"text\":\"--O la humedad del recinto que lo deshace --adujo una nueva interlocutora--. No brilla el Anacronópete por su limpieza: desde que hemos entrado en él, no hago otra cosa más que quitarme velloncitos de lana y borrillas de toda especie que sin duda caen del techo.\"},{\"heading\":false,\"text\":\"--Es verdad. Lo mismo he notado yo --dijo Sabina--. No te muevas, aguarda.\"},{\"heading\":false,\"text\":\"--¿Qué es?\"},{\"heading\":false,\"text\":\"--Una mariposa que tienes en el lazo del sombrero. ¡Una polilla!\"},{\"heading\":false,\"text\":\"--¡Ay! ¡y yo un gusano! --gritó otra corriendo en busca de una mano benéfica que la libertara de él.\"},{\"heading\":false,\"text\":\"Emma quiso volar en su auxilio; pero se detuvo al ver sus dedos impregnados de una sustancia viscosa que había sustituido a la pajarilla. Instintivamente produjo con el brazo un sacudimiento nervioso; pero al quererse mirar de nuevo la mano, la pasta había desaparecido y en su lugar pendían de sus falanges pedacitos de trapo y filamentos de todos tamaños y matices.\"},{\"heading\":false,\"text\":\"Un grito de asombro resonó en el cuarto y la algarada se hizo general cuando Sabina, que consultaba con la mirada a Niní, vio que de la boca de esta, abierta por la sorpresa, salía un diente postizo disparado por el empuje de otro verdadero que tomaba su lugar. Simultáneamente el rubio añadido de Naná, perdido el color y falto del cordón que le sujetara, caía en el suelo mientras su cabeza se cubría de sedosas hebras capaces de causar envidia a la Margarita del Fausto.\"},{\"heading\":false,\"text\":\"--Mirad a Emma --vociferaba una--. Ya no tiene pata de gallo.\"},{\"heading\":false,\"text\":\"--Y Coralia ha perdido su verruga --exclamaba otra.\"},{\"heading\":false,\"text\":\"--¡Qué tersura la de mi cutis!\"},{\"heading\":false,\"text\":\"--¡Qué morbidez la de mis hombros!\"},{\"heading\":false,\"text\":\"--¡No más canas!\"},{\"heading\":false,\"text\":\"--¡Ya somos jóvenes!\"},{\"heading\":false,\"text\":\"--¡Viva!\"},{\"heading\":false,\"text\":\"Y todas consultaban los espejos de sus estuches o se miraban en cualquiera superficie bruñida, distribuyéndose besos y abrazos en el vértigo de su admiración.\"},{\"heading\":false,\"text\":\"La causa de tan maravillosos efectos se explica muy fácilmente. El tiempo empujado hacia atrás verificaba su obra de destrucción; las viajeras no habían sido sometidas a la inalterabilidad; pero sus trajes tampoco. Así es que cada minuto que transcurría dejaba lo mismo en su organización física que en su tocado la huella del retroceso; pues todo en ellas caminaba hacia su origen; y del mismo modo el papel pasaba de la consistencia del billete a la trituración del batán y a la primera forma de guiñapo, que el raso se metamorfoseaba en mariposa para degenerar en larva y reducirse a semilla. Nada más encantador que aquellas turgentes formas mal cubiertas por racimos de capullos de seda entretejidos con vellones de finísima lana y contrastando el dorado color de sus tenues filamentos con el nácar de las ostras a medio abrir que servían de lecho a las perlas embrionarias. ¡Qué artística agrupación la de aquellos minerales incrustados en fragmentos de rocas, rodeados de copos de algodón en rama, ceñidos por verdes aristas de cáñamo y cruzados por residuos de cintas que, de confección anterior a aquel momento histórico, conservaban su integridad como un anacronismo de la moda en la armonía de descomposición de la naturaleza!\"},{\"heading\":false,\"text\":\"La estupefacción era unánime; el entusiasmo indescriptible; pero el tiempo no se detenía en su carrera y el fenómeno empezó a tomar proporciones alarmantes. Los productos transformados en primeras materias dejaron en breve de adornar los contornos de aquellas humanas esculturas. Traspuesto el período en que cada porción de materia había sido arrancada de su asiento, las fracciones comenzaron a desertar en busca de sus matrices. El vellón desaparecía para adherirse a la oveja; la ostra atraída por el banco corría a sepultarse en las costas de Malabar; el algodón huía a hundir sus raíces en las llanuras norteamericanas y la cabritilla de los borceguíes despojada del curtido, volaba a revestir el esqueleto de la inocente res de los Alpes, mientras por los huecos que dejaba la deserción asomaban trazos dignos de inspirar el desnudo a los clásicos escoplos de Miguel Ángel, Praxíteles y Fidias.\"},{\"heading\":false,\"text\":\"Las viajeras al contemplar su desnudez se taparon el rostro con las manos, que el pudor es algo inherente a la hermosa mitad de la especie humana, y prorrumpieron en tan desaforados gritos, que don Sindulfo y Benjamín, dejando aquel sus apuntes y este sus clasificaciones, corrieron en averiguación del alboroto.\"},{\"heading\":false,\"text\":\"--No se puede entrar --decían unas al apercibirse de que los sabios trataban de abrir la puerta.\"},{\"heading\":false,\"text\":\"--Ya tenemos bastante --exclamaban otras.\"},{\"heading\":false,\"text\":\"--¡Ay! Mi corsé... --gritaba una tercera.\"},{\"heading\":false,\"text\":\"Clara y Juanita, a quienes los sabios al verlas llegar despavoridas pusieron al corriente de la situación, penetraron en la estancia; y asustadas ante tan insólito espectáculo volvieron a salir pidiendo auxilio a la ciencia.\"},{\"heading\":false,\"text\":\"--¡Hombre de Dios! Que se van a constipar esas señoras --vociferaba la maritornes.\"},{\"heading\":false,\"text\":\"En esto Benjamín que ya había comprendido la situación, llegó con unos transmisores del fluido de la inalterabilidad; y pasándolos por la puerta entornada, aconsejó a las excursionistas que se agarrasen a ellos. Hiciéronlo así ellas, y con cuatro vueltas al aparato y otras tantas docenas de quejidos de las víctimas, quedaron estas fijadas y remediado el mal.\"},{\"heading\":false,\"text\":\"--Prestadles unos vestidos vuestros --dijo don Sindulfo a su pupila y a Juana, en tanto que él y Benjamín desternillándose de risa tornaban a reanudar su tarea en el laboratorio, comentando el incidente. Pero apenas el políglota se había dejado caer en su asiento, cuando con los cabellos de punta y lanzando un grito desgarrador volvió a levantarse como si un sacudimiento galvánico le hubiese arrancado de la silla.\"},{\"heading\":false,\"text\":\"--¿Qué ocurre? --le preguntó el sabio acudiendo en su socorro.\"},{\"heading\":false,\"text\":\"--¡Mire usted... mire usted!... --balbuceaba el infeliz, señalándole la célebre medalla conmemorativa comprada en la almoneda del arqueólogo madrileño y atribuida según el catálogo a Servio Cayo, prefecto de Pompeya, en honor de Júpiter.\"},{\"heading\":false,\"text\":\"Don Sindulfo tomó el disco que reluciente como una chapa de aguador brillaba sobre la mesa. El objeto en cuestión no había sido fijado aún, esperando para hacerlo el instante cronológico que pudiese acusarles su autenticidad; pero este había ya llegado y, destruida la acción del tiempo, los caracteres campeaban sobre el bruñido fondo con una elocuencia aterradora.\"},{\"heading\":false,\"text\":\"SERV... C. POMP... PR... JO... HONOR\"},{\"heading\":false,\"text\":\"era el anuncio sobre latón de una empresa de coches de muerto fundada en París por la época que ellos atravesaban y que restituida a su integridad decía así:\"},{\"heading\":false,\"text\":\"SERVICE DE POMPES FUNÈBRES RUE D’ANJOU SAINT HONORÉ.\"}]},{\"title\":\"El anacronópete — capítulo ix\",\"blocks\":[{\"heading\":false,\"text\":\"Reducción gradual del ejército hasta su supresión definitiva\"},{\"heading\":false,\"text\":\"Reparadas las averías causadas por la retrogradación en el indumento, las viajeras corrieron al laboratorio en busca de don Sindulfo y empezaron a darle múltiples pruebas de su gratitud.\"},{\"heading\":false,\"text\":\"Los dos sabios no habían vuelto aún del estupor que les produjera la metamorfosis del disco; y en verdad que no les faltaba motivo para renegar de la ciencia que en tal ocasión los había tratado como madrastra. Ello no obstante hicieron de tripas corazón, disimularon su enojo y, cerrando los armarios, consagraron su atención preferente a la contemplación de aquellos tan variados ejemplares de la más hermosa mitad del género humano. La colección era completa: creeríase uno transportado al paraíso de Mahoma o al _foyer de la danse_ en la grande ópera de París.\"},{\"heading\":false,\"text\":\"Aunque la conducta de las agregadas a bordo era irreprochable, don Sindulfo, temeroso de alguna imprudencia, quiso evitar a Clara su contacto y la exhortó a que con Juanita se retirara al gabinete.\"},{\"heading\":false,\"text\":\"--Como que nos vamos a quedar encerradas allí dentro --dijo la de Pinto-- ahora que hemos encontrado que la casa está habitada por _presonas_.\"},{\"heading\":false,\"text\":\"--No importa --repuso el tutor tragando bilis--. No os conocéis, no habláis el mismo idioma.\"},{\"heading\":false,\"text\":\"--Mi señorita entiende el francés, y estas señoras conocen todas las lenguas. Ya nos han dicho que viajan por gusto y eso que andan a repelo.\"},{\"heading\":false,\"text\":\"Y efectivamente: en los pocos minutos que habían tenido disponibles para conferenciar, no solo Juanita las había impuesto en la situación, sino que se había conquistado el concurso de las expedicionarias para obligar con ardides a don Sindulfo a hacer un alto que les permitiera sacar de su escondite a la fuerza armada y emprender juntos la fuga; pues hay que advertir que, al verse rejuvenecidas las doce hijas de Eva, ya no tenían más que una aspiración: ser libres.\"},{\"heading\":false,\"text\":\"Comprendiendo el tutor que la lucha era desigual y tranquilizado con la falsa idea de que, restituidas a la edad del candor relativo, las parisienses solo abrigarían sentimientos puros e inocentes, puso en olvido aquello de «lo que entra con el capillo sale con la mortaja» y las dejó a todas juntas, si bien bajo la custodia de su inspección inquisitorial.\"},{\"heading\":false,\"text\":\"--En este momento entramos en el año 1860 --exclamó Benjamín consultando el derrotero.\"},{\"heading\":false,\"text\":\"--¡Ay! El día en que perdí a mi novio en Constantina --interpuso Niní poniendo en juego la sensibilidad para mover el corazón de don Sindulfo y auxiliar los planes de Clara.\"},{\"heading\":false,\"text\":\"--Y el mismo en que yo abandoné el hogar materno en Bona, por los excesivos rigores de mi padrastro --adujo Sabina mojándose los ojos con saliva para fingir que lloraba.\"},{\"heading\":false,\"text\":\"El sabio tomó oportunamente la palabra, pues de tardar unos segundos más, todas aquellas jóvenes hubiesen resultado oriundas de la Argelia.\"},{\"heading\":false,\"text\":\"--Poco a poco --objetó don Sindulfo--. Se están ustedes enterneciendo prematuramente. Recapaciten ustedes que andamos hacia atrás; y que por lo tanto el año principia para nosotros en 31 de diciembre, o lo que es lo mismo, que entramos en él cuando en la vida real se sale. De modo que aún les quedan a ustedes tres minutos para consagrarse a su doloroso aniversario.\"},{\"heading\":false,\"text\":\"--Tanto mejor --prorrumpió Niní en un arranque de alegría--. Así podré verle vivo. Pídame usted lo que quiera; pero restitúyame usted a sus brazos y empezará una era de ventura para mí que solo he tocado humillaciones.\"},{\"heading\":false,\"text\":\"--Por piedad --vociferaba Sabina--. Ya que se ha encargado usted de nuestra rehabilitación, que se la debamos completa.\"},{\"heading\":false,\"text\":\"--Lo que solicitan es imposible. Yo las restituiré a ustedes a Francia al regreso de nuestro viaje; pero el tiempo es oro y no puedo permitirme un alto. De hacer uno en África lo verificaría sobre Tetuán para asistir a la memorable jornada que tan alto puso el honor de las armas españolas.\"},{\"heading\":false,\"text\":\"--¡Cómo! --arguyó Juanita tomando parte en la trama--. ¿Vamos a pasar por el Riff, donde murió de un balazo, antes de nacer yo, mi tío el trompeta de cazadores, y será usted tan cruel que no le deje dar un abrazo a su sobrina predilecta?\"},{\"heading\":false,\"text\":\"--¿Pues no acabas de decir que no le conociste?\"},{\"heading\":false,\"text\":\"--Eso no importa. Tenemos en casa su retrato al _garrotipo_.\"},{\"heading\":false,\"text\":\"--Creo --balbuceó Clara, empleando todos sus medios de seducción-que mi tío considera lo bastante el nombre castellano para no dejar de rendir este justo tributo de admiración al heroísmo de nuestros compatriotas; y es harto amable para no acceder al ruego de su pupila.\"},{\"heading\":false,\"text\":\"--Sea, pues tú lo quieres --respondió el tutor vencido--. Asistiremos a aquella epopeya; pero sin bajar.\"},{\"heading\":false,\"text\":\"--¿A vista de pájaro? --preguntó Juanita tratando de insistir; pero un gesto de su ama la hizo comprender que puesto en el camino de las concesiones, don Sindulfo no tardaría en rendirse.\"},{\"heading\":false,\"text\":\"El sabio torció el rumbo hacia el 35° de latitud N.; y, al marcar el cronómetro el crepúsculo vespertino del 4 de febrero de 1860, redujo la marcha a paso de carreta y dejó que el Anacronópete se deslizara sobre Tetuán, fuera del alcance de los proyectiles; pero bastante cerca del teatro de la lucha para poder apreciar los menores detalles de aquella memorable batalla.\"},{\"heading\":false,\"text\":\"Todos los corazones nacidos de la vertiente meridional de los Pirineos a la punta de Tarifa, palpitaban con violencia. Abierto el disco, cada cual asestó su instrumento óptico al campo de operaciones y un grito de entusiasmo resonó en la estancia.\"},{\"heading\":false,\"text\":\"--Allí se divisan los combatientes --exclamó Naná, arreglándose el tocado por si levantaba los ojos alguno de los oficiales de Estado Mayor, mientras Juanita atónita balbuceaba:\"},{\"heading\":false,\"text\":\"--¡Jesús! Si parece un _titirimundi_.\"},{\"heading\":false,\"text\":\"--¡Pero, es extraño!... --adujo Clara, fijándose en el fenómeno que se desarrollaba a sus ojos--. Yo no me explico sus movimientos.\"},{\"heading\":false,\"text\":\"--Es verdad --prorrumpieron todos parando mientes en caso tan original.\"},{\"heading\":false,\"text\":\"--¿Qué es ello? --preguntó el sabio.\"},{\"heading\":false,\"text\":\"--Mire usted. Lo hacen todo a la inversa.\"},{\"heading\":false,\"text\":\"--¡Ah! sí --repuso el sabio dándose cuenta de lo que para él carecía de importancia, pues ya lo tenía previsto--. Eso consiste en que, como nosotros vamos viajando hacia atrás en el tiempo, empezamos a ver la batalla por el fin.\"},{\"heading\":false,\"text\":\"--¡Ya! --interpuso Juanita--. ¡Cosas de usted, que lo principia todo por la cola!...\"},{\"heading\":false,\"text\":\"Y efectivamente, los viajeros observaban la batalla de Tetuán con el orden cronológico invertido; como el héroe de _Lumen_ de Flammarión veía la de Waterloo, al remontarse en espíritu a la estrella Capella, teniendo que pasar antes por los rayos luminosos de la Tierra que alumbraban en el espacio hechos posteriores.\"},{\"heading\":false,\"text\":\"--Observen ustedes --proseguía don Sindulfo-- cómo lo primero que se advierte es que los cadáveres se incorporan.\"},{\"heading\":false,\"text\":\"--Es verdad --asentía Benjamín--. Y luego disparan sus fusiles.\"},{\"heading\":false,\"text\":\"--Y después cargan.\"},{\"heading\":false,\"text\":\"--¿_Cargan_? Porque serán sabios --argüía la maritornes, no desperdiciando ocasión de zaherir a su víctima.\"},{\"heading\":false,\"text\":\"--¿Qué es eso? ¿Huyen?\"},{\"heading\":false,\"text\":\"--No. Es que retroceden, porque caminamos hacia el momento en que están ocupando las posiciones que tenían antes de avanzar. Es decir, que ahora llegamos propiamente al principio de la batalla. De modo que parándonos podríamos asistir a ella por su orden.\"},{\"heading\":false,\"text\":\"--Pues, _sóoo_ --dijo la lugareña excitando la hilaridad en todos, a cuyas reiteradas súplicas el sabio no tuvo valor de resistir, aguijoneado a su vez por el orgullo patrio. El Anacronópete quedó suspendido en la atmósfera merced a un ligero movimiento en el graduador.\"},{\"heading\":false,\"text\":\"Escritos estos renglones veintiún años después de aquel memorable acontecimiento, paréceme que su relato, aunque hecho a vuela pluma, no ha de carecer de atractivo para la generación que nos está acabando de reemplazar. Copio aquí, pues, la narración del diario de don Sindulfo, en la que sin duda se ha inspirado el pintor Castellani para reproducir con el pincel aquella jornada, y que también ha servido a la prensa de la corte para describir el panorama que se exhibe en Madrid frente a la casa de la Moneda. Dice así:\"},{\"heading\":false,\"text\":\"«Estamos en el centro del campamento marroquí de Muley-Ahmed. Las tropas españolas llegan hacia él persiguiendo de cerca al enemigo, cuyas posiciones corona simultáneamente. Tenemos en frente el mar, Tetuán a la espalda, el río Martín a la derecha, y a la izquierda la torre de Geleli y la Casa Blanca.\"},{\"heading\":false,\"text\":\"»El general O’Donnell dispone que sus fuerzas ejecuten un movimiento envolvente sobre el campamento de Muley-Ahmed, con objeto de atacarlo por dos puntos distintos con las tropas de los generales Prim y Ros de Olano, entre las que se sitúa la artillería protegida por los ingenieros. Rómpese el fuego de cañón por cuarenta piezas que avanzan gradualmente hasta colocarse a cuatrocientos metros de las trincheras marroquíes.\"},{\"heading\":false,\"text\":\"»En primer término se destaca el general en jefe a caballo con su estado mayor, dando órdenes al comandante Ruiz Dana y teniendo a su lado al coronel Jovellar y al jefe del Estado mayor, general García. Detrás las baterías españolas cañonean los reductos. En el fondo a lo lejos el mar y la escuadra.\"},{\"heading\":false,\"text\":\"»A la derecha el general Ros de Olano, dando instrucciones a su hijo y dirigiendo el movimiento de la primera división del tercer cuerpo, mandada por el general Turón, consigue que sus soldados penetren por distintos puntos en las trincheras. El regimiento de Albuera con su coronel Alaminos; Ciudad-Rodrigo con el teniente coronel Cos-Gayón, y el brigadier Cervino al frente de los batallones de Zamora y Asturias, invaden a la vez el campamento a pesar de la tenaz resistencia de los enemigos; uno de los cuales en las ansias de la muerte, encuentra fuerzas suficientes en su fanatismo para arrastrarse hasta un cañón abandonado, y dispararlo causando horroroso estrago en las primeras filas de nuestras tropas.\"},{\"heading\":false,\"text\":\"»Por la izquierda el general Prim ataca las trincheras seguido del coronel Gaminde; penetra por una tronera rodeado de catalanes, soldados de Alba de Tormes, Princesa, Córdoba y León; forma confuso tropel con los enemigos y sostiene cuerpo a cuerpo una lucha encarnizada. A su lado veo caer moribundos al comandante Sugrañes y al teniente Moxó, tremolando el primero en sus manos la bandera de los intrépidos tercios catalanes. Don Enrique O’Donnell apoya enérgicamente el ataque de su jefe el general Prim, y se dirige luego al campamento de Muley-Abbas en la torre de Geleli, que los moros abandonan precipitadamente.\"},{\"heading\":false,\"text\":\"»Muley-Ahmed intenta en vano con enérgico valor detener la fuga de sus soldados, que huyen despavoridos ante las aguerridas huestes de Prim y abandonan la Casa Blanca. Llenos de terror, desoyen el mandato de su jefe, le arrastran en su huida y dejan en poder de nuestras tropas, como trofeo de tan señalado triunfo, el campamento con ochocientas tiendas, ocho cañones, armas, municiones, camellos, caballos y bagajes.\"},{\"heading\":false,\"text\":\"»En el fondo, hacia Tetuán, el sultán de Marruecos contempla consternado la derrota de su ejército numeroso.\"},{\"heading\":false,\"text\":\"»Durante la marcha de nuestros soldados, los enemigos amenazan atacar la retaguardia; pero el general O’Donnell, sin detenerse, destaca hacia Tetuán dos batallones del tercer cuerpo a las órdenes del general Makenna, quien adelantando rápidamente a lo largo del río Martín protegido por la brigada de coraceros del general Alcalá Galiano, rechaza al enemigo sobre la plaza después de breve lucha y paraliza sus esfuerzos.\"},{\"heading\":false,\"text\":\"»Formidables fuerzas enemigas, bajando a la vez de la torre de Geleli, amagan atacar nuestra derecha con sus infantes y tres mil jinetes; pero el general en jefe, atento a todas las peripecias del combate, hace adelantar la brigada de lanceros del conde de Balmaseda. Las tropas cargan vigorosamente sobre el enemigo y le ponen en precipitada fuga protegidas en su movimiento por el cuerpo de reserva del general Ríos, situado en el reducto de la Estrella.\"},{\"heading\":false,\"text\":\"»La jornada ha sido completa. Tetuán no tardará en abrir sus puertas al vencedor, y el emperador de Marruecos debe ya empezar a arrepentirse de haber excitado el justo enojo de la nación española.»\"},{\"heading\":false,\"text\":\"El entusiasmo a bordo no reconocía límites. Todos suplicaban a don Sindulfo que les permitiese bajar para dar un abrazo a aquellos héroes, inclusa Juanita que pretextaba haber reconocido los pulmones de su familia en un paso de ataque tocado por su tío con la trompeta. El sabio que, además de estar poseído de la admiración general, tenía un carácter vengativo impropio de sus luces intelectuales, vio en aquella circunstancia una ocasión de desembarazarse del torcedor de su fregatriz, y accedió a la demanda decidido a volver a emprender la marcha en cuanto Juanita traspusiese los umbrales del Anacronópete en busca del supuesto pariente. Eligióse pues para el descenso un bosquecillo que les garantizase de una bala perdida, y con gran contentamiento de todos y una sencillísima manipulación, el vehículo tocó tierra.\"},{\"heading\":false,\"text\":\"Pero ¡ay! que no comete el hombre acción mala sin recibir tarde o temprano por ella el condigno castigo. Saboreando estaba cada cual la realización de sus propósitos, cuando Benjamín, que, asomado al disco contemplaba el horizonte, dio un grito y retrocedió involuntariamente.\"},{\"heading\":false,\"text\":\"--¿Qué es eso? --le preguntó su inseparable, corriendo a su lado.\"},{\"heading\":false,\"text\":\"--¡Friolera! --contestó el políglota perdiendo el color--. Que sin duda hemos caído en una emboscada tendida por los marroquíes a nuestras tropas.\"},{\"heading\":false,\"text\":\"Un sudor frío circuló por la frente de todos los viajeros.\"},{\"heading\":false,\"text\":\"--¡Huyamos! --fue la opinión general.\"},{\"heading\":false,\"text\":\"--Mire usted los kabilas que se dirigen hacia aquí.\"},{\"heading\":false,\"text\":\"--No hay más remedio que apelar a la fuga --adujo el sabio corriendo al regulador y poniendo en movimiento la máquina, mientras Benjamín cerraba los discos y restablecía el alumbrado eléctrico, exclamando:\"},{\"heading\":false,\"text\":\"--Pronto, que nos alcanzan.\"},{\"heading\":false,\"text\":\"Aún no había acabado de pronunciar la frase cuando:\"},{\"heading\":false,\"text\":\"--¡Un moro! --articuló con voz ahogada una de las viajeras.\"},{\"heading\":false,\"text\":\"--¡Dos! --prorrumpió Juanita parapetándose detrás de su amo.\"},{\"heading\":false,\"text\":\"--¡Veinte! --profirieron todos poseídos de un terror pánico cobijándose en un rincón del laboratorio en compacto grupo.\"},{\"heading\":false,\"text\":\"Eran en efecto dos docenas de fugitivos del campamento de Muley-Ahmed que, buscando su salvación en el bosque, presenciaron el descenso del vehículo y tomándolo por arma de guerra habían resuelto atacarlo; pero, no encontrándole entrada franca, se valieron de sus cuerpos salientes y, escalándolos con la entereza que da el fanatismo, lograron introducirse por los tubos de desalojamiento antes de que el coloso emprendiese la marcha.\"},{\"heading\":false,\"text\":\"Pasado el primer momento de estupor, en que nadie osaba levantar los ojos ante aquellos morazos de seis pies de altura provistos de gumías y espingardas y llevando escrito en el rostro el vengativo ceño del enemigo derrotado, Naná se resolvió a preguntar a don Sindulfo:\"},{\"heading\":false,\"text\":\"--Diga usted. ¿Nos harán algo?\"},{\"heading\":false,\"text\":\"--A nosotros rebanarnos el pescuezo; y a ustedes llevárselas al harem en calidad de odaliscas.\"},{\"heading\":false,\"text\":\"--¿Con los eunucos? ¡Qué horror! --articularon las aludidas por lo bajo.\"},{\"heading\":false,\"text\":\"--Pues lo que es al harem --interpuso Juana encarándose con su señor-creo que también podría usted venir.\"},{\"heading\":false,\"text\":\"--¡Insolente!\"},{\"heading\":false,\"text\":\"--Para hacernos compañía y enseñarnos ciencias en los ratos de ocio.\"},{\"heading\":false,\"text\":\"El tutor no se había equivocado acerca del propósito de los invasores, según la traducción que Benjamín le hizo de las órdenes dictadas por el jefe de la fuerza. Los expedicionarios estaban irremisiblemente perdidos. Una idea luminosa brotó sin embargo en el cerebro del atribulado don Sindulfo.\"},{\"heading\":false,\"text\":\"--Si logramos ganar tiempo --dijo al políglota-- nos hemos salvado.\"},{\"heading\":false,\"text\":\"--¿De qué modo?\"},{\"heading\":false,\"text\":\"--Dando al vehículo la velocidad máxima y consiguiendo que estos kabilas, que no están sometidos a la inalterabilidad, se vayan empequeñeciendo hasta que concluyan por desaparecer una vez traspuesto el instante de su natalicio.\"},{\"heading\":false,\"text\":\"--¡Sublime idea!\"},{\"heading\":false,\"text\":\"Y forzando el graduador, la máquina se puso a funcionar con una rapidez vertiginosa.\"},{\"heading\":false,\"text\":\"--¡A ellos! --gritó el capitán; y los moros se aprestaron a consumar su obra; pero los ayes y las lamentaciones del sexo débil eran tan repetidos y penetrantes, que, no logrando restablecer el silencio, les pusieron a todos a guisa de mordaza un lienzo atado en la boca y, oprimiendo sus brazos con fuertes ligaduras, los arrastraron tras sí para conducir los esclavos al asilo del disperso campamento.\"},{\"heading\":false,\"text\":\"Cerca de un cuarto de hora anduvieron buscando los riffeños inútilmente la salida, con gran satisfacción de los cautivos que, si bien no podían pedir socorro ni fugarse maniatados como estaban, veían en cambio que sus opresores se rejuvenecían rápidamente y acariciaban la esperanza de hallarse en breve libres de su yugo.\"},{\"heading\":false,\"text\":\"Pero los caracteres meridionales son impetuosos y no tienen la paciencia por virtud. Agotada la de los hijos del desierto al sospechar que estaban siendo los prisioneros de sus rehenes, se conformaron con salir por donde entraran; mas, convencidos de la imposibilidad de hacerlo con su presa, adoptaron la extrema resolución de exterminar a los viajeros.\"},{\"heading\":false,\"text\":\"Encontrábanse a la sazón en la cala y las mujeres se desesperaban al pensar que cuando una sola voz les bastaría para llamar en su auxilio a sus salvadores, tenían que sucumbir al mutismo. Colocados los reos en un ángulo de la bodega, los moros ocuparon el centro y apercibieron sus espingardas. Ya no les quedaba duda a aquellos infelices acerca de la triste suerte que les deparaba el destino. Apiñados y confundidos revolvíanse los desgraciados en la desesperación de la impotencia y ya los cañones estaban apuntados hacia su pecho, cuando el tiempo, ejerciendo su poderoso influjo, convirtió de repente la cuerda que sujetaba al tutor en finísimos filamentos de cáñamo que le dejaron libre el ejercicio de sus músculos. Apercibirse de tan providencial beneficio y emplearlo en poner en contacto los conductores que junto a él descendían por las paredes de la cala, fue operación tan rápida como el pensamiento. Acto continuo las compuertas se abrieron y los hijos de Agar desaparecieron para siempre en el espacio insondable.\"},{\"heading\":false,\"text\":\"La alegría que sucedió a aquellos minutos de angustia no hay quien la describa. Restituidos a la libertad abrazábanse todos sin distinción de sexos ni condiciones; y hasta la misma Juanita no pudo prescindir de decir a su amo, en un arranque de gratitud:\"},{\"heading\":false,\"text\":\"--Si no fuera usted tan feo, me casaba con usted.\"},{\"heading\":false,\"text\":\"Saboreando estaba el sabio su triunfo muy convencido de haber conquistado con él un lugar preferente en el corazón de su pupila, cuando esta temiendo ver surgir nuevos contratiempos,\"},{\"heading\":false,\"text\":\"--Ya es ocasión de revelárselo todo --exclamó, pidiendo consejo a Juanita.\"},{\"heading\":false,\"text\":\"--¿Qué duda cabe? --respondió la resuelta asesora.\"},{\"heading\":false,\"text\":\"Y añadiendo:\"},{\"heading\":false,\"text\":\"--¡A mí, valientes! --incitó a salir de su guarida a los soldados españoles, riéndose con descaro del asombro del buen tío que intuitivamente comprendió la asechanza de que le habían hecho objeto.\"},{\"heading\":false,\"text\":\"--¡Cómo! ¿Están aquí? --prorrumpió lívido de coraje.\"},{\"heading\":false,\"text\":\"--¡Perdón! --repetía Clara.\"},{\"heading\":false,\"text\":\"--Ni para ti ni para ellos --proseguía el celoso tutor dando golpes en cuantos objetos tenía a tiro.\"},{\"heading\":false,\"text\":\"--Pues, ea --arguyó Juanita--. Guerra a muerte; y el sabio que sea hombre, que salga. Don Luis, Pendencia, melitares: ¡Mueran las matemáticas!\"},{\"heading\":false,\"text\":\"Un ay de espanto reemplazó a tan enérgico apóstrofe. Los diecisiete hijos de Marte aparecieron en la cala trepando por los sacos de harina y los barriles de provisiones; pero, como no habían sido sometidos a la inalterabilidad y el mayor de ellos no contaba veinticinco primaveras, los cuatro lustros desandados en el tiempo desde la salida de París los habían reducido a la condición de tiernos parvulillos.\"},{\"heading\":false,\"text\":\"--¡Esto es espantoso! --murmuraban las francesas que se las habían prometido muy felices de la galantería española.\"},{\"heading\":false,\"text\":\"--¡Yo desfallezco! --articulaba la pupila no dando crédito a la realidad, mientras Juanita hecha un basilisco exclamaba enseñándole los puños a su amo:\"},{\"heading\":false,\"text\":\"--Si es _usté_ el sabio más animal que conozco.\"},{\"heading\":false,\"text\":\"El tutor se bañaba en agua de rosas al contemplar la venganza que le servía el azar. Entre tanto el vehículo caminaba y los infantes se achicaban hasta el extremo de no poderse tener ya en pie.\"},{\"heading\":false,\"text\":\"--Pero, hombre de Dios, ¿no ve usted que se nos deshacen como la sal en el agua? --argüía la maritornes echando espuma por la boca.\"},{\"heading\":false,\"text\":\"--Mejor --contestaba aquel segundo Otelo--. Así acabaremos de una vez.\"},{\"heading\":false,\"text\":\"Y los angelitos yacían tendidos en el suelo agitando brazos y piernas en la inacción de los primeros meses y llorando a pulmón lleno. Compadecidas de su situación, cada hija de Eva tomó en brazos al suyo y se puso a pasearlo por la cala viéndolos mermarse progresivamente, en tanto que el implacable tío se frotaba las manos con satisfacción y sonreía con satánico gesto.\"},{\"heading\":false,\"text\":\"--¡Luis mío! --repetía Clara anegada en llanto y tributando sus caricias a aquel residuo de su capitán de húsares.\"},{\"heading\":false,\"text\":\"--¿Ya no tienes una gracia para tu Juanita? --preguntaba a su microscópico Pendencia la de Pinto.\"},{\"heading\":false,\"text\":\"Y el bribón del asistente, como si aún quisiera darle una prueba de su travesura, le mordió el vestido por la parte en que a los niños de su edad se les sirven los alimentos.\"},{\"heading\":false,\"text\":\"De pronto aquellas mujeres se quedaron pálidas con los brazos cruzados sobre el pecho; ya no abarcaban objeto alguno: el ejército se les había disuelto entre las manos.\"}]},{\"title\":\"El anacronópete — capítulo x\",\"blocks\":[{\"heading\":false,\"text\":\"En que tiene lugar un incidente que parece insignificante y es, sin embargo, de mucha importancia\"},{\"heading\":false,\"text\":\"La pérdida de un ser querido es una de las más terribles pruebas a que puede exponerse la sensibilidad humana: y aun así la aflicción pasa por distintas gradaciones según las circunstancias que han acompañado al hecho.\"},{\"heading\":false,\"text\":\"--Al menos ha muerto en su cama y rodeado de los suyos --le dicen al atribulado pariente los encargados de consolarle.\"},{\"heading\":false,\"text\":\"--Y ha tenido usted la satisfacción de que Dios se lo conserve hasta una edad avanzada --añaden otros.\"},{\"heading\":false,\"text\":\"Y efectivamente, todas estas reflexiones son un lenitivo al dolor que, resultado de una máquina pensante y contante, paga la situación en su justo precio reservándose para las grandes catástrofes el máximum de intensidad.\"},{\"heading\":false,\"text\":\"Ahora bien: imagínense los lectores cuál sería la disposición de ánimo de los viajeros ante aquel quinto acto de una tragedia para cuyo desenlace no había _Deus ex machina_ posible. Porque un novio es algo más que un pariente a los ojos del objeto de su cariño; y además de la amargura de separarse para siempre del suyo, las enamoradas doncellas sufrían el vejamen de ver que, siendo el amor un numen que engrandece cuanto toca, a ellas al revés, se les achicaba todo entre las manos.\"},{\"heading\":false,\"text\":\"Clara perdió el sentido ante la inmensidad de su infortunio y tuvo que ser conducida al gabinete en brazos de las expedicionarias. Juana, más entera aunque no menos herida, se desahogaba dando gritos contra el opresor y llamando a la guardia en su socorro.\"},{\"heading\":false,\"text\":\"Pero la situación más grave era sin duda la de don Sindulfo. Por malo que tuviese el genio, por mezquina que fuera su condición, por miras estrechas que lo alentasen, distaba mucho de ser un malvado: y la muerte de los veinticuatro moros, aunque llevada a cabo en legítima defensa propia, eran dos docenas de puñales que tenía hundidos en el corazón. Agréguese a esto la aparición de los hijos de Marte, en la que veía no solo una desobediencia a sus mandatos sino la inutilidad de haber agotado su ciencia y sus recursos para desembarazarse de un rival, y se comprenderá fácilmente que su razón trastornada le indujese a permitir que el tiempo devorase a aquellos infelices, sin prestarles el menor auxilio. Primer paso suyo en la senda del crimen por la que hemos de verle avanzar presa de los celos, la desesperación y la locura. No adelantemos empero el discurso.\"},{\"heading\":false,\"text\":\"Los mahometanos, aunque hombres, eran enemigos de Dios y habían atentado contra su vida; por consiguiente, bien muertos estaban. ¿Pero aquellos diecisiete infantes, a quienes había servido de implacable Herodes, qué daño le habían hecho? ¿Merecía tan horroroso castigo una travesura de la juventud? ¿No era su sobrino una de las víctimas? ¿No hubiera sido más humano, pues no estaban sometidos a la acción del fluido, hacer rumbo hacia el presente y, una vez reconquistadas sus naturales proporciones, desembarcarlos en los alrededores de su edad?\"},{\"heading\":false,\"text\":\"Todas estas y otras muchas observaciones se hacía don Sindulfo, pero la imagen de su pasión desatendida, y su amor propio sublevado concluían por vencer, y resultado de tan acerba lucha fue que delirante cayese en los brazos de su amigo bajo los efectos de una continua convulsión.\"},{\"heading\":false,\"text\":\"¿Pues no estaba garantizado por la inalterabilidad? me objetará alguien. Ciertamente, pero la acción del fluido, penetrando por la membrana epidérmica, atravesando el dermis e infiltrándose por los tejidos musculares, solo alcanza a la superficie de los huesos, que petrifica como las demás vías por donde circula. Así pues el ejemplar influido por sus corrientes, ni pierde la tersura del cutis, o sea la juventud, ni sufre de erupciones cutáneas, ni está expuesto a las inflamaciones producidas por la acción atmosférica: pero experimenta hambre, sed y sueño y no se exime de padecimientos viscerales, productos las más veces del sistema moral al que la ciencia no ha llegado a dar todavía la osificación que a un tegumento.\"},{\"heading\":false,\"text\":\"Cargó pues Benjamín con aquel cuerpo inanimado y lo condujo a su dormitorio para ver de provocar la reacción metiéndolo en la cama; pero, al pasar por el laboratorio, recordó la velocidad vertiginosa que habían impreso al aparato en el momento de la invasión marroquí, y temeroso de alguna catástrofe por imprudencia, dio un golpe a la aguja del graduador, reduciendo el Anacronópete, a su entender, a la locomoción media.\"},{\"heading\":false,\"text\":\"¡Qué pequeños incidentes son origen de los más grandes acontecimientos!\"},{\"heading\":false,\"text\":\"Don Sindulfo, acurrucado en el lecho, daba diente con diente de continuo y alguna que otra sacudida por intervalos a Benjamín.\"},{\"heading\":false,\"text\":\"--Juanita --dijo este saliendo al encuentro de la de aparejo redondo--. Calienta un poco de agua para hacer una infusión a tu amo que se siente mal.\"},{\"heading\":false,\"text\":\"--¿Quién? ¿Yo? Pues como no sea para escaldarle vivo, que se aguarde a que encienda fuego.\"},{\"heading\":false,\"text\":\"--¡Vamos! Deja a un lado el enojo y recapacita que si él se muere nadie podrá llevarnos a puerto de salvación.\"},{\"heading\":false,\"text\":\"--¿Pues usted no entiende la maquinaria?\"},{\"heading\":false,\"text\":\"--Muy poco. Además, la caridad te aconseja ser compasiva. Prepara la lumbre mientras yo saco el té y el azúcar de la despensa.\"},{\"heading\":false,\"text\":\"Sea el miedo a permanecer indefinidamente en el espacio o la compasión inherente a su sexo, Juanita no replicó e hizo rumbo a la cocina.\"},{\"heading\":false,\"text\":\"--Ya sabes. Con un par de chispazos eléctricos alumbras una hoguera en un decir Jesús.\"},{\"heading\":false,\"text\":\"--A mí déjeme usted de _telégrafos_, que yo me las compondré a la moda antigua.\"},{\"heading\":false,\"text\":\"Y, así diciendo, llegó al hornillo, colocó en él unos carbones y tomando unos fósforos frotó uno tras otro sobre la lija, sin conseguir encender ninguno; pero lo más notable del caso era que ni dejaba huella la cerilla en el raspador ni la cabeza del de Cascante se gastaba.\"},{\"heading\":false,\"text\":\"--Es claro. Las babas de don Sindulfo que lo reblandecen todo --murmuró, y echóse en busca de otra caja y de algunas virutas y trapos con qué facilitar la combustión. No encontrando nada a propósito, dio al pasar por el cuarto de las agregadas con unos fragmentos de telas y pieles que, aunque acusaban una rica procedencia, eran retales al fin y muy del caso en circunstancias tan apremiantes. Dispuso los residuos en el fogón y, haciendo una nueva e inútil tentativa con los fósforos:\"},{\"heading\":false,\"text\":\"--A ver si usted tiene más gracia --dijo a Benjamín que acudía cargado con un pilón de azúcar y un bote de té Hulón.\"},{\"heading\":false,\"text\":\"--Esto es más breve --arguyó el políglota comunicando la chispa eléctrica al hornillo a merced de la cual los trapos se encendieron pero no los carbones; siendo de notar, por más que ninguno de ambos observase el fenómeno, que las suplentes virutas iban tomando extrañas formas parecidas a lazos, mangas de vestido, tacones de bota y objetos de mercería.\"},{\"heading\":false,\"text\":\"--Parte un poco de azúcar --ordenó Benjamín a Juanita en tanto que él, puestas las hojas en la tetera, derramaba encima el agua hirviendo.\"},{\"heading\":false,\"text\":\"--¡El demonio que pueda con esta pirámide de Egipto! Si es más dura que la cabeza de un sabio --repetía Juanita dando golpes en el pilón con un martillo sin conseguir levantar una arista.\"},{\"heading\":false,\"text\":\"--Déjate; aquí hay azúcar molido --exclamó el interpelado poniendo una cucharada en la taza de otro paquete que para el uso ordinario había en el vasar y sirviendo en ella el licor benéfico.\"},{\"heading\":false,\"text\":\"--Pero aguarde usted... ¡si eso no está aún! Todavía no ha tomado color.\"},{\"heading\":false,\"text\":\"Un sudor frío circuló por la frente de Benjamín, en quien la resistencia del pilón, la incombustibilidad de los carbones y la inalterabilidad del agua vinieron a darle la llave del enigma. Presa de una agitación nerviosa se puso a disolver el azúcar en la infusión; y al llevarse una cucharada a los labios:\"},{\"heading\":false,\"text\":\"--¡Horror! --dijo palideciendo.\"},{\"heading\":false,\"text\":\"--¿Qué ocurre? --preguntó la doncella mirándole de hito en hito temerosa de que también empezara él a reducirse como los otros.\"},{\"heading\":false,\"text\":\"--¿Qué ha de ser? Que hemos vuelto inalterables para su conservación los artículos de consumo, y ahora nos encontramos con que son resistentes a toda influencia física.\"},{\"heading\":false,\"text\":\"--¿Es decir?...\"},{\"heading\":false,\"text\":\"--Que ni el azúcar endulza, ni el carbón se enciende, ni el pilón se parte, ni habrá quién le pueda hincar el diente a una patata.\"},{\"heading\":false,\"text\":\"--¿De modo que nos vamos a morir de hambre? --balbuceó Juanita con los ojos desencajados.\"},{\"heading\":false,\"text\":\"--No; pero tendremos que apearnos a cada comida y tomar los alimentos propios de la época y de la localidad; pues de fijarlos ya ves lo que sucede; y de abandonarlos a la acción retrógrada del tiempo, en tres minutos el pan se nos convertiría en espigas y el vino en cepas.\"},{\"heading\":false,\"text\":\"--¿Y dónde tomaremos hoy la pitanza? --repuso la lugareña a quien la idea de un alto sonreía por lo que encerraba de salvador para las reclusas.\"},{\"heading\":false,\"text\":\"--En los infiernos --salió murmurando Benjamín con la taza del agua caliente en la mano; la que propinada a su amigo le produjo las consecuencias de un emético sumiéndole después en una dulce y agradable somnolencia.\"},{\"heading\":false,\"text\":\"Entretanto Juanita volaba a dar parte de lo ocurrido a sus compañeras de infortunio, quienes rodeando el lecho de la pupila, presenciaban una escena no menos digna de admiración que la precedente.\"},{\"heading\":false,\"text\":\"Es pues el caso que mientras prodigaban sus consuelos a la pobre huérfana, Niní, que no sin profunda aflicción había visto desaparecer de sus lóbulos, antes de ser fijada, las dos hermosas perlas que llevaba por pendientes, dio un grito de alegría al llevarse las manos hacia los desheredados cartílagos y encontrarse con la restitución de sus preciadas joyas.\"},{\"heading\":false,\"text\":\"--Mirad, esto es milagroso...\"},{\"heading\":false,\"text\":\"--En efecto --exclamaron todas. Y al tender en torno suyo una mirada de asombro, este creció de punto al observar que todos los objetos arrebatados por la acción retrógrada del tiempo les eran devueltos sin saber cómo. Ya un girón del vestido de Naná, cubriéndose de larvas, tomaba la forma de capullos para metamorfosearse en tupido raso de Lyon; ya una tira de becerro, curtiéndose repentinamente y modelándose al pie de Sabina se llenaba de pespuntes y lazos hasta elevarse a la categoría de un borceguí Carlos IX.\"},{\"heading\":false,\"text\":\"--¡Mi chal! --gritaba una...\"},{\"heading\":false,\"text\":\"--¡Mis encajes! --decían otras.\"},{\"heading\":false,\"text\":\"Y todas se libraban al más expansivo arranque de entusiasmo, cuando la más razonadora de ellas:\"},{\"heading\":false,\"text\":\"--Poco a poco --les arguyó--. Moderad vuestro júbilo. Cierto es que reconquistamos nuestro ajuar; pero ¿quién os asegura que la devolución no será completa?\"},{\"heading\":false,\"text\":\"--¡Cómo!\"},{\"heading\":false,\"text\":\"--¿No teméis que por este fenómeno, cuya explicación ignoramos, cada perla que creemos ganada nos devuelva la arruga que juzgamos perdida?\"},{\"heading\":false,\"text\":\"La observación era tan atinada y el temor de perder los encantos tan profundo, que un grito unánime salió de todos los labios en demanda de socorro; y las viajeras, dejando a Clara en el gabinete al cuidado de Juanita, echáronse en busca de los sabios encontrando felizmente en el laboratorio a Benjamín que consiguió a duras penas imponer silencio a aquella rebelde turba.\"},{\"heading\":false,\"text\":\"--¿Qué significa esto? --preguntó la más osada--. ¿Tratáis de volvernos a envejecer?\"},{\"heading\":false,\"text\":\"--Que se nos admita a libre plática --argumentaba otra--. Ya hemos pasado la cuarentena.\"},{\"heading\":false,\"text\":\"--¡No más lazareto! --vociferaban a coro.\"},{\"heading\":false,\"text\":\"Benjamín, que no acertaba a darse razón de lo que veía, estudiaba el caso con los ojos fijos en el suelo; y maquinalmente al notar un objeto que relucía, lo recogió y dio con un ochavo moruno.\"},{\"heading\":false,\"text\":\"--Alguna moneda que se le ha caído a un kabila --dijo Niní llamándole la atención hacia lo más urgente--, no haga usted caso de eso.\"},{\"heading\":false,\"text\":\"--Pero si esta moneda --repuso el políglota-- procede de un marroquí, ¿cómo, no estando sometida a la inalterabilidad, subsiste todavía? Debería haberse descompuesto toda vez que viajamos hacia atrás.\"},{\"heading\":false,\"text\":\"--Acaso sea más antigua que el año en que nos hallamos.\"},{\"heading\":false,\"text\":\"--No. Su fecha es del 1237; y como el cómputo árabe principia en 622, época de la Hégira, este ochavo corresponde al 1859 de nuestra era o sea al año anterior en que fuímos atacados por los riffeños y que debimos trasponer tres minutos después de la invasión.\"},{\"heading\":false,\"text\":\"--¿Entonces?... --interrogaron las atónitas viajeras con la mirada.\"},{\"heading\":false,\"text\":\"Y como Benjamín dirigiese la suya hacia el cuarto de los relojes:\"},{\"heading\":false,\"text\":\"--¡Maldición! --dijo al consultar el cronómetro del tiempo relativo.\"},{\"heading\":false,\"text\":\"E inmediatamente hizo parar en seco el Anacronópete.\"},{\"heading\":false,\"text\":\"--¿Qué es ello?\"},{\"heading\":false,\"text\":\"--Que al querer moderar hace poco la locomoción, he rebasado sin duda la línea de la aguja y caminábamos hacia adelante. Hemos deshecho lo andado. Estamos sobre Versalles a 9 de julio o sea en la víspera del día que salimos de París.\"},{\"heading\":false,\"text\":\"La alegría que se pintó en el rostro de las viajeras al convencerse de que, sin detrimento de su juventud, eran restituidas al teatro de sus operaciones, no hay quien la describa. Todas suplicaron a Benjamín que las desembarcase; y aunque este temía las iras de don Sindulfo, pudo más en él la idea del ridículo de que iba a cubrirse cuando su colega advirtiese su ineptitud. Así es que confiado en el seguro del secreto, toda vez que ni Clara ni Juanita eran testigos de su derrota; y en la persuasión de cohonestar con una medida de buen gobierno el abandono de las agregadas, determinóse a darles gusto, lo que le valió una abundante y envidiable cosecha de abrazos y besos.\"},{\"heading\":false,\"text\":\"El vehículo descendió majestuoso en el parque contiguo al Trianon; las viajeras lo abandonaron sigilosamente, y Benjamín, dando la velocidad máxima se echó por el espacio a desquitarse de lo perdido diciendo:\"},{\"heading\":false,\"text\":\"--Ahora a China en busca del secreto de la inmortalidad.\"},{\"heading\":false,\"text\":\"Al día siguiente los periódicos de París traían dos noticias: una que fue comentada por todos los desocupados de los bulevares; otra que solo conmovió al mundo sabio.\"},{\"heading\":false,\"text\":\"Decía la primera, que habían sido reducidas a prisión doce jóvenes que, valiéndose de las circunstancias, querían explotar la credulidad pública haciéndose pasar por las expedicionarias del Anacronópete; siendo así que en ninguna de ellas se encontraban trazos que acusasen ser las agraciadas por la Prefectura, donde constaba su filiación y se les había entregado pasaportes de que las impostoras no venían provistas a su regreso.\"},{\"heading\":false,\"text\":\"La segunda era más lacónica aunque más trascendental para la ciencia, en cuyos anales sigue constando como artículo de fe: se reducía a dar cuenta de que a las nueve y cuarenta y cinco minutos de la mañana el observatorio astronómico había presenciado la caída de un enorme aereolito en las inmediaciones de Versalles.\"},{\"heading\":false,\"text\":\"¡Así se escribe la historia!\"}]},{\"title\":\"El anacronópete — capítulo xi\",\"blocks\":[{\"heading\":false,\"text\":\"Un poco de erudición fastidiosa aunque necesaria\"},{\"heading\":false,\"text\":\"El día 14 del noveno mes del año 604 (antes de J. C.) en la aldea de Li, estado feudal de Tsou, hoy provincia de Hou-nan, nacía con los cabellos blancos después de ochenta y un años de gestación (al decir de sus sectarios) el gran metafísico de la China, apellidado por esta circunstancia Lao-tseu o sea el viejo niño.\"},{\"heading\":false,\"text\":\"Hasta su aparición, la filosofía más remota del Celeste Imperio estaba reducida al _Y-King_, enciclopedia puesta en orden por _Fo-hi_, en quien los historiadores creen reconocer a Noé después que salió del Arca e hizo su viaje a la provincia de _Xen-si_ cerca del monte Ararat en la parte opuesta de la Bactriana. Su fundamento es enseñar el origen de las cosas y las transformaciones sufridas en el curso de las edades. Dios es considerado en ella como la piedra angular sobre que todo descansa. Es a un tiempo mismo _Ly_ y _Tao_ (razón y ley) y como tal se revela a la inteligencia humana.\"},{\"heading\":false,\"text\":\"Lao-tseu, guiado por una sabiduría apacible, enseñó a despreciar las pasiones, a elevarse sobre todos los intereses, grandezas y glorias terrenales, recomendando hacer abnegación de sí propio en beneficio de los demás y humillarse para ser enaltecido: lenguaje que recuerda la humildad y la caridad de la doctrina del Salvador.\"},{\"heading\":false,\"text\":\"Todo el tesoro de su inteligencia lo encerró en su obra titulada _Tao-te-King_. _King_ significa que el libro es clásico: _Tao_ y _Te_ son las palabras porque empiezan las dos partes de que consta su tratado y que, como sucede con el Pentatéuco, le han servido para darle el nombre. Ambos títulos reunidos quieren decir _Libro de la razón suprema y de la virtud_.\"},{\"heading\":false,\"text\":\"He aquí un fragmento que confirma que, ante el espectáculo de las desgracias de su patria, en vez de aspirar a una reforma, como Confucio lo hizo más tarde, Lao-tseu se aisló, exhortando al hombre a buscar el bien supremo en la soledad ascética y haciéndolo consistir en la calma absoluta:\"},{\"heading\":false,\"text\":\"«El hombre, dice, debe esforzarse en obtener el último grado de _incorporeidad_ a fin de conservarse tan inalterable cuanto le sea posible. Los seres aparecen en la vida y cumplen sus destinos: nosotros contemplamos su renovación sucesiva por la cual cada uno de ellos vuelve a su origen. Volver a su origen significa ponerse en reposo; ponerse en reposo es restituir su mandato; restituir su mandato es hacerse eterno. El que sabe hacerse eterno es iluminado; el que no, se convierte en víctima del error y de todas las calamidades.»\"},{\"heading\":false,\"text\":\"Esta moral, que podemos llamar pasiva, fue exagerada por sus prosélitos que se apellidaron _Tao-sse_ o sean doctores celestes. Y en efecto, mientras Lao-tseu no asentaba el bien público y el privado sino en el ejercicio de la virtud y en la identificación con la razón suprema para dominar los sentidos y alcanzar la impasibilidad, sus sectarios abusaron de esta inacción para abandonarse a un rígido ascetismo; y, proclamando que la sabiduría engendra los desórdenes, recomendaron al pueblo la ignorancia más absoluta, reservándose no obstante las artes cabalísticas y adivinatorias a fin de embaucar con ellas a las masas cuando, a la aparición del budismo en China, los _Tao-sse_ se confundieron con los bonzos.\"},{\"heading\":false,\"text\":\"Las dos sectas de los _Yang_ y los _Me_ no son sino ramas del mismo tronco: sus diferencias son tan insignificantes que no merecen ser reseñadas sino comprendidas en el principio fundamental de la religión de los _Tao-sse_, cuya consecuencia fue elevar a dogma la ociosidad entre las clases ignorantes.\"},{\"heading\":false,\"text\":\"El año 551 antes de la era vulgar, hacia el solsticio de invierno del año vigésimo segundo del reinado de _Ling-uan_, nació en la aldea de _Tseu_, reino feudal de _Lu_ (hoy provincia de _Chan-tung_), el gran _Kun-fu-tseu_ o Confucio como le llamamos en Europa.\"},{\"heading\":false,\"text\":\"Tan distante este filósofo de la ciega credulidad como de las mágicas ficciones de los _Tao-sse_, jamás se ocupó ni de la naturaleza humana, ni del principio divino, ni de la metafísica en fin. Su carácter no es el de un innovador; limítase tan solo a restablecer las bases de la moral práctica de las sociedades primitivas.\"},{\"heading\":false,\"text\":\"«Lo que yo os enseño, decía él, lo podéis aprender por vosotros mismos haciendo un legítimo uso de las facultades de vuestro espíritu. Nada tan natural ni tan sencillo como la moral cuyas prácticas saludables trato de inculcaros. Todo lo que yo os predico, los sabios de la antigüedad lo han ejecutado ya. Su práctica se reduce a tres leyes fundamentales: de relación entre vasallos y señores, entre padre e hijo y entre marido y mujer, y el ejercicio de estas cinco virtudes capitales: la humanidad, es decir, el amor de todos sin distinción ninguna; la justicia, que da a cada uno lo que le pertenece; la observancia de las ceremonias y usos establecidos, a fin de que todos los que viven juntos sigan una misma regla y participen de las mismas ventajas y de los mismos inconvenientes; la rectitud de juicio y de sentimiento para buscar y desear lo verdadero en todo, sin alucinaciones egoístas para sí, ni apasionadas para los otros; la sinceridad, o sea un corazón abierto que excluya la ficción y el disimulo, así en las palabras como en las obras. Estas son las virtudes que han valido el dictado de venerables a los primeros institutores del género humano, en vida, y los han conducido después a la inmortalidad: Tomémoslos por modelo y esforcémonos en imitarlos.»\"},{\"heading\":false,\"text\":\"Tal es en resumen la moral de Confucio, cuyo carácter distintivo es hacer derivar todos los deberes de los de la familia, y reducir las virtudes a una sola: la piedad filial. Su dogma es la obediencia del inferior al superior.\"},{\"heading\":false,\"text\":\"En cuanto a metafísica, he aquí lo que al padre Pedranzini decía un mandarín sectario de Confucio:\"},{\"heading\":false,\"text\":\"«Nosotros nos guardamos mucho de decidir sobre cosas que no son evidentes y que los sabios antiguos tenían por inciertas. El axioma de los hombres santos consiste en la partícula si, puesto que dicen: Si hay un paraíso, los virtuosos gozarán en él mil delicias; si hay un infierno, los malvados serán precipitados en él; pero ¿quién puede afirmar que existan o no? Abstenerse del mal y hacer bien, he aquí el punto importante. El _Tai-hio_ recomienda que lo principal es la virtud y lo accesorio las riquezas y el bienestar. El _Liun-in_ encarga que no hagas a otro lo que no quieras para ti. Todo estriba en esto. Procédase así y basta; las felicidades del paraíso, si hay uno, vendrán como consecuencia.»\"},{\"heading\":false,\"text\":\"Esta moral fue la que dominó en las clases ilustradas cuyos sectarios, hostiles a los preceptos oscurantistas de los _Tao-sse_, tomaron el nombre de _letrados_ y su comunión el de _academia_.\"},{\"heading\":false,\"text\":\"Entre los discípulos de Confucio el más notable es Meng-tseu o Mencio, muerto en 314 (a. de J. C.). Afligido de ver triunfantes las dos sectas de _Tao-sse_, o sean la de _Yang_ que predicaba el egoísmo como el principal regulador de las acciones humanas, y la de _Me_ que sostenía que el afecto debía extenderse a todos por igual sin distinción de parentesco, propagó una filantropía generosa basada en la moral de Confucio cuyo resumen es este: «_Sirve bien al cielo quien sigue la recta razón._» Su libro reunido a los tres de apotegmas de Confucio, es aún hoy de texto entre los que aspiran a los cargos públicos.\"},{\"heading\":false,\"text\":\"Vemos, pues, dos grandes grupos disputándose el dominio de las conciencias: la metafísica de Lao-tse, relajada por los mágicos procedimientos de los _Tao-sse_, sus sectarios, dueña de las masas ignorantes y perezosas: la moral de Confucio, observada por los letrados, alumbrando las inteligencias privilegiadas y siendo, por decirlo así, la religión del estado, patrocinada y seguida por los emperadores, indiferentes más que tolerantes de todas las demás prácticas y creencias. Hubo sin embargo una época en que los cabalísticos amenazaron invadirlo todo. Fue en el siglo II (antes de J. C.) cuando los _Tao-sse_, separándose de la pura doctrina de Lao-tse, empezaron a librarse a extrañas especulaciones y pretendieron haber descubierto el secreto de la inmortalidad contenido en un misterioso brebaje. En vano fue que los sectarios de Confucio quisieran desenmascararlos; protegidos por el emperador Wu-ti hubieran sin duda alguna triunfado de los letrados, si uno de estos, tomando la copa que sus rivales destinaban al monarca, no la hubiese apurado de un sorbo desafiando el enojo del augusto personaje que, en su ceguedad, le condenó a morir en su presencia.\"},{\"heading\":false,\"text\":\"--Si la eficacia de este licor es verdadera --le dijo el confucista-la orden que acabáis de dar es inútil: si por el contrario es falsa, con mi muerte destruiréis vuestro error.\"},{\"heading\":false,\"text\":\"El engaño descubierto, Wu-ti volvió su crédito a los letrados, y los _Tao-sse_ continuaron ejerciendo su influencia tan solo entre los ignorantes y amigos de la ociosidad. Estos siguiendo la religión de los espíritus, como ya se ha visto; aquellos predicando el escepticismo y la indiferencia y consignando que la muerte no tiene más objeto que hacer pasar el alma a otro cuerpo o descomponerla en aire, sin que quede nada del hombre a no ser la sangre en sus hijos y el nombre en su patria.\"},{\"heading\":false,\"text\":\"Ello no obstante, como en sus libros consignase Confucio que él no trataba sino de restablecer la doctrina primitiva y que no era más que _el precursor de un ilustre personaje que vendría de Occidente_, el rey Ming-ti envió en el siglo primero de nuestra era una flota hacia aquella parte, en busca del gran reformador. Las naves fueron bastante lejos; pero no atreviéndose a ir más allá, abordaron una isla en que encontraron una estatua de Buda que, trasladada a China en el año 65 de Jesucristo, fue desde entonces adorada bajo el nombre de _Fo_ y sigue compartiendo el culto con los prosélitos de Lao-tse y los letrados.\"},{\"heading\":false,\"text\":\"Algunos cristianos, huyendo por esta época de las persecuciones de Nerón, llegaron hasta el Celeste Imperio; pero cohibidos por la escasez del número y por las condiciones del país, quedaron oscurecidos hasta que en 635 de nuestra era, bajo el reinado de _Tai-tsung_, fue recibido en _Chang-ngan_ el sacerdote nestoriano _O-lo-pen_ del _Ta-tsin_, es decir del imperio romano. El emperador envió a su encuentro los principales dignatarios que le condujeron al palacio; hizo traducir sus santos libros y, persuadido de que encerraban una doctrina verdadera y saludable, decretó que fuese erigido un templo a la nueva religión y que veintiún sacerdotes se consagrasen a su servicio. El hecho está consignado en un monumento levantado en _Si ngan fu_, en el cual la doctrina cristiana se encuentra expuesta sucintamente, y se dice que los misioneros llamados por _O-lo-pen_ llegaron en 636 a la corte de _Tai-tsung_; que este publicó un edicto en favor del cristianismo; que _Kao-tsung_ hizo construir iglesias en todas las ciudades; que _Vu-heu_ persiguió a sus sectarios y que Kuo-tsé iba siempre seguido de un sacerdote cristiano en las batallas.\"},{\"heading\":false,\"text\":\"Las revueltas políticas, que a principios del siglo tercero de nuestra era (en que va a tener lugar este relato) agitaban la China, no podían por menos de transmitir su influencia a los antagonismos religiosos que entre sí despertaban los tres principios de Lao-tse, Confucio y Fo o Buda.\"},{\"heading\":false,\"text\":\"El emperador _Ho-ti_ fue el primero que en el año 120, era cristiana como todo lo que a seguir va, concedió honores y dignidades a los eunucos de palacio, en detrimento del ascendiente que los letrados habían tenido hasta entonces en la corte. Unos y otros continuaron disputándose el poder hasta el año 187 en que los eunucos hicieron sospechosa a los ojos del monarca la academia, presentándole la unión de los hombres instruidos como un peligro contra su tiranía. El emperador _Chung-ti_ desterró a los doctores y libró a los tribunales a los más ilustres proclamándose él a su vez amigo de la ciencia por haber hecho grabar sobre cuarenta y seis lápidas de mármol y en tres clases de caracteres los cinco libros clásicos del _I-King_.\"},{\"heading\":false,\"text\":\"Aunque los _Tao-sse_ hacían aparentemente causa común con los eunucos, no tardaron, aprovechando las circunstancias, en utilizarlas en su provecho. La peste, habiendo desolado el imperio durante once años, un _Tao-sse_ llamado _Chang-kio_ halló contra ella un remedio seguro en cierta agua preparada con unas palabras misteriosas. Este charlatán obtuvo fácilmente crédito entre las masas. Seguido por una turba de empíricos, los disciplinó, y en breve encontróse a la cabeza de un partido numeroso. Su doctrina era que el _cielo azul_, o sea la dinastía de los _Han_ dominante a la sazón en la persona del emperador Hien-ti, tocaba a su término para dejar paso al _cielo amarillo_. Descubiertos sus propósitos y viendo su pérdida segura, se echó al campo en abierta rebelión. Cincuenta mil hombres secundaron su grito, y tomando un gorro amarillo por insignia, se aprestaron a devastar el país. Sus expediciones fueron favorecidas por el levantamiento de muchos ambiciosos que aspiraban a repartirse la China en diversos estados; pero la prudencia y el valor del general _Tsao-tsao_, jefe del partido de los letrados a quienes el monarca llamó en su auxilio, sofocaron la insurrección y los vencidos se acogieron a su bandera. Hien-ti le nombró su primer ministro; pero enorgullecido por su triunfo, pronto se vio a _Tsao-tsao_ ceñirse el sombrerete de doce colgantes, adornado con cincuenta y tres piedras preciosas --atributo distintivo de la majestad-- y hacerse llevar en el coche de eje de oro con tiro de seis caballos. No hubiera tardado mucho en apoderarse del sello imperial si la muerte no le hubiera atajado el camino. Su obra no obstante fue consumada por su hijo _Tsao-pi_, primer _calado_ o ministro de _Hien-ti_ a quien arrebató la corona en el año 220 dando fin a la dinastía de los _Han_ para dar comienzo a la de los _Ouei_.\"},{\"heading\":false,\"text\":\"Pero, no adelantemos los sucesos toda vez que vamos a hacer asistir a los lectores a este acontecimiento memorable; y dejemos consignado para su mayor inteligencia que el Anacronópete llegó a _Ho-nan_, corte entonces del imperio chino, en el año 220, bajo el reinado de _Huen-ti_ y en sazón en que la revuelta dominada, muerto _Tsao-tsao_ y elevado a la dignidad de _Calado_ su hijo _Tsao-pi_, el poder había sido reconquistado por los letrados, quienes perseguían sin piedad así a los sectarios de Fo, por lo que tenía de nuevo la religión búdica importada del Indostán, como a los _Tao-sse_ por la grosería de sus empíricos recursos.\"}]},{\"title\":\"El anacronópete — capítulo xii\",\"blocks\":[{\"heading\":false,\"text\":\"Cuarenta y ocho horas en el Celeste Imperio\"},{\"heading\":false,\"text\":\"Miente como un bellaco el refrán, cuando asegura que no hay mal que dure cien años; pues sus dieciséis centurias bien contadas se pasó don Sindulfo en el lecho del dolor, desde que arrojó a los hijos de Mahoma en el espacio y a los de Marte en la nada, hasta que el Anacronópete se posó en los alrededores de Ho-nan, capital a la sazón del imperio chino.\"},{\"heading\":false,\"text\":\"En los tres días y medio que duró el viaje, Benjamín, aprovechándose del sopor del sabio y del sueño de las muchachas, hizo sus correspondientes altos y salió sigilosamente del vehículo para proveerse de las indispensables municiones de boca; pues ya hemos visto que las que a bordo llevaban eran inútiles. El primer festín se lo debió a la piadosa munificencia de la reina Isabel la Católica; y por cierto que estuvo a punto de costarle la vida porque llegado al campamento de Santa-Fe, donde el ejército castellano se desesperaba ante la tenaz resistencia de los moros de Granada, fue tomado por espía de Boabdil, a lo que contribuía no poco el extraño disfraz que para aquella época constituían su americana y sus pantalones con boca de trabuco. Afortunadamente el políglota no perdió la serenidad; y acordándose de lo beneficiosos que podían serle los conocimientos adquiridos en la cátedra de historia, pidió ser conducido a presencia de la reina a fin de hacerle revelaciones importantes. Acompañada estaba doña Isabel de su esposo don Fernando, del cardenal Ximénez y de sus primeros capitanes; y todos, menos la augusta señora, sostenían el parecer de levantar un sitio en que se enterraban la paciencia de los sitiadores y los fondos del erario, cuando Benjamín haciendo irrupción en la tienda:\"},{\"heading\":false,\"text\":\"--¿Qué es levantar el sitio? --exclamó con alientos de profeta.\"},{\"heading\":false,\"text\":\"E inclinándose al oído de la reina añadió en voz baja:\"},{\"heading\":false,\"text\":\"--Hoy 2 de enero de 1492, día de viernes, como aquel en que el Redentor de los hombres derramó en el Calvario su preciosa sangre, y a las tres, hora precisa en que el Verbo encarnado exhaló su postrer suspiro, el pendón de Santiago y el estandarte real ondearán en la torre de la Alhambra.\"},{\"heading\":false,\"text\":\"Doña Isabel palideció; los cortesanos que la rodeaban, recelando algún desafuero, echaron mano a sus espadas; y no lo hubiera pasado muy bien el maestro de lenguas si los añafiles moros mezclándose con la trompetería cristiana no hubieran traído con sus ecos una pausa salvadora.\"},{\"heading\":false,\"text\":\"--¿Qué ocurre? --preguntó el rey al ver aparecer en la tienda al conde de Cifuentes llevando en el semblante impresa la alegría.\"},{\"heading\":false,\"text\":\"--Ocurre, señor --dijo el noble caballero-- que Boabdil acaba de rendirse; y que para que los vencedores puedan entrar en Granada con entera seguridad, el vencido envía en rehenes al campo de Castilla a sus hijos con seiscientos hombres de armas al mando de dos de sus más esclarecidos jefes.\"},{\"heading\":false,\"text\":\"Un grito de asombro se escapó de todos los pechos.\"},{\"heading\":false,\"text\":\"--¿Quién eres tú? --preguntó la reina casi prosternándose atónita ante el que en su fe bendita tomaba por aparición celeste.\"},{\"heading\":false,\"text\":\"--Un pobre mortal --respondió Benjamín-- que os pide por toda recompensa que le dejéis seguir libremente su camino suministrándole un bocado de pan con que aplacar su hambre.\"},{\"heading\":false,\"text\":\"Tan limitada exigencia acabó de ratificar el juicio que doña Isabel formara del profeta; y sin atreverse a insistir en premiarle con dádivas humanas, ella por sus propias manos le aderezó unas alforjas henchidas de rico jamón de las Alpujarras y rebosando de pan del mejor candeal de Castilla, amén de una cantimplora de vino de Aragón del que, para el servicio de la mesa de don Fernando, custodiaban en el repuesto los despenseros de campaña.\"},{\"heading\":false,\"text\":\"Ya se disponía Benjamín a abandonar la tienda, cuando la soberana llamándole aparte y con las manos cruzadas en ademán de súplica:\"},{\"heading\":false,\"text\":\"--¿Qué puedo hacer --le dijo-- para felicidad de mis vasallos y esclarecimiento de mi trono?\"},{\"heading\":false,\"text\":\"--Dad oídos, señora --le contestó el políglota-- a un genovés que vendrá a ofreceros un mundo.\"},{\"heading\":false,\"text\":\"--¿A Colón? --preguntó la reina admirada--. Ya le he visto; ¡pero si aseguran que es un loco!... Además, mi tesoro está exhausto.\"},{\"heading\":false,\"text\":\"--Vended vuestras joyas si es preciso. Él centuplicará su valor creando vicios para la humanidad.\"},{\"heading\":false,\"text\":\"Y así diciendo entregó a la reina una breva de Cabañas a la que la pobre señora daba vueltas entre sus dedos sin explicarse su virtud.\"},{\"heading\":false,\"text\":\"--¿Y qué es esto? --se resolvió a inquirir al cabo.\"},{\"heading\":false,\"text\":\"--¡Humo! --exclamó Benjamín, y desapareció.\"},{\"heading\":false,\"text\":\"Y en efecto, dos años después, corriendo en busca de otro rumbo para las Indias orientales, volvía Colón de América con un nuevo mundo para España y una infinidad de estancos para las viudas de militares pobres.\"},{\"heading\":false,\"text\":\"El segundo descenso que en busca de vitualla hizo Benjamín a la tierra, veinte horas más tarde o sea en las postrimerías del siglo XI, no ofreció nada de notable. No así el que después de un período equivalente verificó en el año 696 a la ciudad de Rávena al declinar la tarde de un domingo.\"},{\"heading\":false,\"text\":\"Esta villa, como saben todos, era a la sazón la residencia de los exarcas que dirigían los destinos de la parte de Italia sometida al poder de Bizancio. Gobernada por las instituciones municipales del Bajo-Imperio, estaba distribuida en escuelas para las milicias urbanas; pero una bárbara costumbre tenía allí lugar. Los días de fiesta, jóvenes y viejos, niños y mujeres, cualquiera que fuese su condición, salían de la ciudad y, divididos en bandos, se libraban a unas pedreas de que resultaban siempre heridos y muertos. Gozoso volvía Benjamín de un convento en que, gracias a los harapos de mendigo que se había colgado, recibiera abundantes provisiones; y dirigiéndose iba hacia su vehículo, cuando una desaforada gritería y una multitud de gente que avanzaba en precipitada fuga le dieron a comprender, compulsando fechas y según lo que en Agnelli había leído, que atravesaba aquel histórico momento en que los de la puerta Tiguriana, vencedores de los de la poterna de Sommovico, los persiguieron hasta dar cuenta de la mitad del opuesto campo.\"},{\"heading\":false,\"text\":\"--Esto no reza conmigo --dijo para su capote el viajero, y se echó a correr a campo traviesa; pero los guijarros llovían con tal profusión que a fin de acelerar su marcha no titubeó en apoderarse de un burro lombardo que pacía en una pradera y cuyos lomos oprimiendo sacó al escape. Desgraciadamente una piedra salida de una honda tiguriana hirió con tan mala suerte a su cabalgadura que, dándole de lleno en un corvejón, le rebanó la pata por entero sin que al reponerse de la caída pudiera el jinete dar con el miembro mutilado que deseaba conservar como recuerdo de aquel drama cuyo fin, según diremos de paso, fue el siguiente: Vencidos los de la poterna simularon una reconciliación; e invitando a un festín a los de la escuela Tiguriana, los degollaron a todos arrojando sus cadáveres en las cloacas. Los traidores fueron ahorcados, sus muebles consumidos por el fuego; y, allanadas sus viviendas, el área en que se alzaban fue conocida en adelante con el nombre del _barrio de los asesinos_.\"},{\"heading\":false,\"text\":\"Restituido milagrosamente Benjamín al Anacronópete, compartió su pitanza con Clara y con Juanita que desde la desaparición del ejército no salían de su cuarto en el que la aflicción las tenía relegadas; propinó algunas yerbas saludables que había cogido para don Sindulfo y emprendió su marcha hacia el celeste imperio. Pero al abrir su armario para hacer unas apuntaciones en el diario de bordo ¿qué creerán mis lectores que encontró dentro? Pues nada menos que la pata del burro hirsuta y sanguinolenta ocupando en el casilicio el lugar del famoso hueso que el desgraciado comprara en Madrid a peso de oro tomándolo por una canilla de hombre fósil descubierta en las inmediaciones de Chartres.\"},{\"heading\":false,\"text\":\"Por fin sonó el año 220 en el cuadrante del tiempo relativo y, haciendo alto el coloso en los arrabales de Ho-nan, la esperanza de hacerse dueño del secreto de la inmortalidad borró el desengaño antropológico de que jamás hizo mención Benjamín a sus compañeros de viaje.\"},{\"heading\":false,\"text\":\"Repuesto ya don Sindulfo de su acceso, aunque con la razón no muy conforme, como se verá por el curso de los acontecimientos, y entregadas las muchachas a esa obediencia pasiva que es la indiferencia del dolor, dispusiéronse todos a penetrar en la corte de Hien-ti, no sin que previamente cohonestara el políglota la desaparición de las francesas con una insurrección a bordo que le había puesto en el caso de desembarcarlas según sus deseos.\"},{\"heading\":false,\"text\":\"Nadie le hizo observación alguna sobre el particular.\"},{\"heading\":false,\"text\":\"Clara y Juanita sentían el corazón muy lacerado para ocuparse de otra cosa que de su desgracia, y el sabio por su parte, silencioso como un marmolillo, solo tenía puesta su imaginación en su proyecto, que era desembarcar en una época de oscurantismo y de autocracia donde la arbitrariedad de las leyes le permitiera obligar a su pupila a llamarse su esposa.\"},{\"heading\":false,\"text\":\"La ciudad estaba desierta. La primera emperatriz había fallecido la noche antes, y el luto nacional, según el edicto del emperador, prohibía a todo hijo del celeste Imperio salir de sus viviendas ni abrir puertas ni ventanas en el transcurso de cuarenta y ocho horas.\"},{\"heading\":false,\"text\":\"Llegados los viajeros a los muros de Ho-nan e interrogados por el jefe de la guardia acerca de sus designios, Benjamín, que era el intérprete de la expedición, le expuso sus deseos de ser recibidos en audiencia por el emperador Hien-ti. El traje de los excursionistas, los rasgos fisonómicos de la raza europea, la vigilancia que se le tenía prescrita y la sospecha de que los anacronóbatas pudieran ser sectarios de los _Tao-sse_, tan perseguidos a la sazón por el partido de los letrados dueños del poder, hicieron parar mientes al oficial, y creyendo servir con ello la causa de su monarca, dispuso que, escoltados por su gente y con los ojos vendados, fueran conducidos a la presencia del emperador.\"},{\"heading\":false,\"text\":\"Obtenida la venia del monarca, los viajeros, no sin gran susto aunque tranquilizados por la erudición de Benjamín que se esforzaba en persuadirles de que en la conducta del jefe de guardia no había malevolencia sino cumplimiento del ritual observado en la corte china, se encontraron delante de Hien-ti.\"},{\"heading\":false,\"text\":\"Era este soberano un hombre corrompido, de condición viciosa, en quien la sed de placeres no bastaba a saciar el insultante lujo de que se rodeaba a costa de sus abyectos vasallos. El palacio o _yamen_ que habitaba y del que tomó copia el príncipe _Tchao_ para construir el suyo en _Yé_ un siglo más tarde, era de una suntuosidad indescriptible. En sus muros no se veía sino mármol y en sus techos resbalaban los rayos del sol sobre la tersa superficie de los barnices y las lacas. Las campanillas que colgaban de los cornisamentos eran de oro; de plata las columnas que sostenían el entablamento, y toda suerte de piedras preciosas esmaltaban los cortinajes que cubrían las puertas.\"},{\"heading\":false,\"text\":\"Las más hermosas mujeres, así de la clase mandarina como de la plebe, lo habitaban con más de diez mil personas que entre astrólogos y artistas formaban el séquito del emperador. Mil doncellas montadas en corceles ricamente enjaezados le servían de guardia y le acompañaban en sus excursiones, cuando no se hacía llevar en un ligero carruaje tirado por corderos adiestrados que se paraban allí donde una de las cinco mil actrices destinadas a la voluptuosidad de Hien-ti, ofrecía a los rumiantes pastos frescos para detener su carrera y lograr la insigne honra de que el monarca se reposase en sus brazos.\"},{\"heading\":false,\"text\":\"Apenas los viajeros se presentaron en la estancia en que los aguardaba Hien-ti, este no pudo reprimir un movimiento de sorpresa, arrancado por la hermosura de Clara. Dominándose no obstante por el decoro que le imponía su condición de viudo, contentóse con cruzar una mirada de inteligencia con su primer ministro Tsao-pi; quien a su vez, y tal vez por adulación hacia su amo, hizo un gesto significativo contemplando a Juanita como quien dice: «Pues esta otra tampoco me parece a mí costal de paja.»\"},{\"heading\":false,\"text\":\"Nos llevaría tan lejos la descripción del ceremonial empleado en la entrevista y el extraño estilo usado por los interlocutores que, para dar una idea de ambos, haremos un resumen de lo que el historiador Cantú y otros sinólogos cuentan sobre el particular; advirtiendo de paso que estos usos siguen practicándose hoy en China casi en absoluto, pues sabido es que el estacionamiento constituye la base de su carácter.\"},{\"heading\":false,\"text\":\"«La cortesía artificial de los chinos --dicen los que de relatar estas ceremonias se han ocupado-- se manifiesta en todos sus actos, en sus visitas sujetas a reglamentación, en el modo de colocarse en ellas según la categoría, en su manera de andar y en sus interminables cumplimientos. Jamás emplean el _yo_ personal en la conversación; dicen, sí, _vuestro criado_; o si el rango lo exige, _vuestro indigno y humilde esclavo_. No dirigen la palabra a nadie sin tratarle de _muy noble señor_. Su país es _vil, miserable y abyecto_, lo mismo que sus presentes por suntuosos que los hagan; al paso que cuanto pertenece al _señor_ a quien hablan es _digno de la consideración más elevada_. En sus visitas todo esta prescrito por el código de la etiqueta, que tiene fuerza de ley, y el que descuidase la menor de sus prescripciones inferiría al otro un insulto, quedaría deshonrado y hasta se haría acreedor a un castigo. Los embajadores europeos quedaban antes sometidos a cuarenta días de aprendizaje y eran examinados por el tribunal de los ritos; transcurridos los cuales, si cometían algún yerro ante el emperador, eran responsables de él sus institutores.»\"},{\"heading\":false,\"text\":\"«Cuéntase que un duque de Moscovia rogó al emperador en sus credenciales que dispensara a su enviado si, falto de práctica, caía en alguna falta venial; y que el Hijo del cielo dando sus pasaportes al plenipotenciario, contestó en estos términos al soberano moscovita: _Legatus tuus multa fecit rústice._»\"},{\"heading\":false,\"text\":\"«Pero no es solamente en la corte donde se procede así; todo chino que desea hacer una visita a otro, sea letrado o mercader, hace presentar por el criado que le precede una tarjeta (_tie tsée_) con su nombre y sus cumplidos, en la que se lee por ejemplo: _El amigo tierno y sincero de su señoría, o el discípulo perpetuo de su doctrina se presenta para hacerle su reverencia hasta el suelo._\"},{\"heading\":false,\"text\":\"»Si el visitado le recibe, la silla o litera entra a través de los patios hasta la sala de recepción. Llegado a ella el ceremonial marca uno por uno los saludos que deben hacerse, las conversiones a derecha y a izquierda, las cabezadas, la súplica de pasar el primero y el no aceptarlo, la reverencia que el amo de la casa tributa al sitial destinado al huésped que este no ocupa sin que aquel le limpie antes el polvo con sus vestidos. Siéntanse por fin con la cabeza cubierta, pues lo contrario sería irreverente, y empieza la conversación cuidando mucho de llamarse viejos, refinamiento exquisito de amabilidad y buena educación. En seguida se sirve el té para el cual hay también su manera de ofrecerlo, de aceptarlo, de llevárselo a la boca y de devolvérselo al criado. Al despedirse, media hora bien contada se pierde en palabrería vana de la que tienen a provisión un buen repuesto. Si uno dice una galantería, _fei-sin_ responde el otro, es decir: _Prodiga usted su corazón._ El menor servicio le vale a uno un _Sie-putsin_. (_Mi gratitud no puede tener fin._) Favor pedido va siempre acompañado del indispensable _te-tsui_ (_¡Qué gran pecado tomarme tamaña libertad!_) La alabanza no se recibe sin protestar _Ki can_. (_¿Cómo poder creerlo?_) Y el postre de toda comida es esta frase del anfitrión: _Yeu-mau, tai-man_. (_Mal te hemos recibido, mal te hemos tratado._)»\"},{\"heading\":false,\"text\":\"«El amo de la casa sale a la puerta para ver subir en la silla a su amigo. Este asegura que no lo hará nunca en su noble presencia: y después de un cange de instancias y de negativas, aquel se retira y el otro se mete en la litera; pero aún no se ha sentado cuando el primero llega a la carrera para desearle feliz viaje. El huésped le devuelve sus saludos, insiste en no marcharse sin que el amigo se retire, y aunque el amigo dice que allí permanecerá clavado hasta perderle de vista, el buen tono aconseja que al cabo sea él quien después de muchas dificultades ceda y se aleje. Parte el huésped, y apenas ha dado unos pasos, cuando el que lo recibió sale a la puerta para darle el adiós último al que el otro responde por gestos sacando la cabeza por la ventanilla; hasta que al fin logra llegar a su casa, y a los dos minutos un criado del anfitrión viene a enterarse de su salud de parte de su amo, a darle las gracias por su visita y a hacer votos para que se repita en breve.»\"},{\"heading\":false,\"text\":\"Enterados de estas minuciosidades, demos cuenta en nuestro estilo usual de la interesante entrevista que los cuatro viajeros tuvieron con el emperador Hien-ti y con su primer _calado_, en el palacio de la corte de Ho-nan.\"}]},{\"title\":\"El anacronópete — capítulo xiii\",\"blocks\":[{\"heading\":false,\"text\":\"La Europa del siglo XIX ante la China del siglo III\"},{\"heading\":false,\"text\":\"El espectáculo de tantas maravillas acumuladas no pudo menos de sacar de su estupor a Clara y a Juanita; especialmente a la última que, si bien no logró reconquistar su buen humor, empezó a hacer uso de la palabra.\"},{\"heading\":false,\"text\":\"--Oiga usted --preguntó dirigiéndose a su amo--. ¿Pues no dicen que los chinos llevan coleta? ¿Cómo es que estos son rabones?\"},{\"heading\":false,\"text\":\"--Porque los celestiales --le contestó don Sindulfo-- conservaron su integridad capilar hasta el siglo XVII en que, vencidos por los tártaros manchures, estos les obligaron a dejarse crecer en la cabeza un _como rabo de perro_ en señal de esclavitud.\"},{\"heading\":false,\"text\":\"--Me lo estudiaré --dijo gravemente la de Pinto, sentándose a una indicación del calado.\"},{\"heading\":false,\"text\":\"Terminado el ritual de las salutaciones, el emperador interrogó a los viajeros acerca de su origen y del objeto que los conducía a su presencia; a lo que Benjamín respondió que eran habitantes de la región occidental; que vivían en una época mil seiscientos años posterior a la suya, y que, poseedores del secreto de retrogradar en los siglos, acudían a Ho-nan para inquirir el principio de la inmortalidad predicado por los _Tao-sse_ y poder, perfeccionándolo, abrir al hombre las puertas del porvenir como ya le tenían abiertas las del pasado.\"},{\"heading\":false,\"text\":\"Hien-ti cruzó con su valido una mirada de inteligencia. Para ellos era indudable que los excursionistas pertenecían a la secta derrotada de los embaucadores que con tan inverosímiles relatos trataban sin duda de alucinar a la corte y al pueblo, para renovar las luchas de los _gorros amarillos_. Su sentencia de muerte estaba tácitamente dictada desde aquel instante, si bien el arrobamiento con que contemplaba las facciones de ambas doncellas parecía presagiar en su favor una conmutación de la pena capital.\"},{\"heading\":false,\"text\":\"--¿Y qué pruebas podéis aducir que nos den testimonio de vuestra veracidad? --adujo el monarca a fin de conocer los subterfugios de que los impostores pensaban servirse para cohonestar sus afirmaciones.\"},{\"heading\":false,\"text\":\"--Señor --repuso Benjamín--. Tarea fácil ha de sernos la de convencer a V. M. con solo presentarle alguna pequeña muestra de los progresos operados por la civilización en los dieciséis siglos que nos separan, y de que tan buen uso puede hacer el imperio, ya apropiándose los realizados en otras naciones, o ya anteponiéndose en su descubrimiento a los que, en centurias muy posteriores a la que atravesamos, llevó a cabo la China.\"},{\"heading\":false,\"text\":\"--En efecto --dijo Hien-ti con una sonrisa de incredulidad--. Si la cosa es como aseguras, bien merece tomarse en cuenta. Haznos admirar esas maravillas de la civilización.\"},{\"heading\":false,\"text\":\"Benjamín no se hizo repetir la orden; y, echando mano a un saquito de noche que a prevención llevaba provisto de multitud de zarandajas, empezó a vaciarlo con el orgullo de un hijo del siglo XIX que, engreído con las conquistas de su época, cree poder burlarse impunemente de sus antecesores, a quienes, después de todo, debe la base de unos conocimientos que él no ha hecho las más veces sino perfeccionar.\"},{\"heading\":false,\"text\":\"--Aquí tenéis --dijo exhibiéndolo con paternal solicitud-- un vaso de bronce, imitación del ánfora griega. Sustancia fusible desconocida en vuestro imperio, cuyas aplicaciones os será grato saber.\"},{\"heading\":false,\"text\":\"--Poco a poco --replicó el emperador cortándole el discurso y llevando a Benjamín a una puerta, ante cuyas antas se erguían dos colosales jarrones del mismo metal.\"},{\"heading\":false,\"text\":\"--¡Cómo! --preguntó el políglota aturdido--. ¿No solo tenéis idea de la fusión sino que sabéis aplicarla a trabajos artísticos monumentales?\"},{\"heading\":false,\"text\":\"Hien-ti no pudo reprimir una carcajada; y poniendo el dedo sobre unos caracteres chinos que por los adornos corrían:\"},{\"heading\":false,\"text\":\"--Lee aquí --añadió.\"},{\"heading\":false,\"text\":\"El atribulado viajero dio un paso atrás, producido por el asombro, al ver sobre el cuello del vaso esta máxima: _A fin de mejorar tu condición purifícate cada día_; lema perteneciente a todos los enseres del uso del emperador _Chang_ fundador de la segunda dinastía, y de cuya autenticidad no dejaba duda el sello de su reinado que campeaba en el centro.\"},{\"heading\":false,\"text\":\"--Señores --gritó Benjamín dirigiéndose a los suyos--. Estos jarrones han sido fundidos en el año 1766 antes de la era cristiana.\"},{\"heading\":false,\"text\":\"--De modo --interpuso el tutor-- que según nuestra cuenta, tienen de existencia casi treinta y seis siglos y medio.\"},{\"heading\":false,\"text\":\"Mordiéndose los labios por despecho arqueológico estaba aún Benjamín, cuando descubriendo, a través de la pedrería que lo ocultaba, el fondo del cortinaje:\"},{\"heading\":false,\"text\":\"--¿Qué es esto? ¿También os es familiar el arte de tejer la seda?\"},{\"heading\":false,\"text\":\"--Tu ignorancia me asusta --le contestó el calado--. ¿No sabes que ese descubrimiento tuvo lugar en el año sesenta y uno del reinado de _Hoang-ti_, época en que dan principio para los letrados los tiempos históricos de la China y el ciclo de sesenta años divididos estos en 365 días y 6 horas, base de nuestro cómputo?\"},{\"heading\":false,\"text\":\"--Y apuesto --dijo Juanita al oír la traducción-- que ese don _Juan Tic_ era ya viejo en tiempo de Jesucristo.\"},{\"heading\":false,\"text\":\"--Como que floreció 2698 años antes --replicó don Sindulfo.\"},{\"heading\":false,\"text\":\"--Lo que yo decía; contemporáneo de usted.\"},{\"heading\":false,\"text\":\"--Pase por el bronce y vaya en gracia la seda --insistió Benjamín, que no se acomodaba a ser vencido en el certamen--. Pero a fe que esto no sabrá V. M. para lo que sirve.\"},{\"heading\":false,\"text\":\"Y desdoblando un papel presentó al emperador una brújula.\"},{\"heading\":false,\"text\":\"Hien-ti se sonrió con el ministro; y, conduciendo al políglota a una ventana que sobre el río caía,\"},{\"heading\":false,\"text\":\"--¿Ves esos barcos? --le preguntó.\"},{\"heading\":false,\"text\":\"--¡Con casco de hierro! --exclamó el interpelado atónito, pudiendo distinguir las planchas del forro a través de la luz crepuscular.\"},{\"heading\":false,\"text\":\"--Sí; hace ya seiscientos años que no nos servimos de los buques de madera; y más de doce siglos que hacemos uso en ellos de ese aparato que tú nos presentas como una maravilla y cuya invención sabe el cielo a quién pertenece.\"},{\"heading\":false,\"text\":\"Absortos estaban los dos sabios sin acertar a darse la explicación de lo que veían, cuando un confuso tropel de gente que, gritando para abrirse camino, precedía a unos carromatos de extraña forma, les sacó de su atolondramiento.\"},{\"heading\":false,\"text\":\"--¿Qué ocurre? --inquirió don Sindulfo.\"},{\"heading\":false,\"text\":\"--Nada importante --repuso Tsao-pi--. Algún incendio. Eso son las bombas que van a sofocarlo.\"},{\"heading\":false,\"text\":\"--¡Las bombas! --prorrumpieron todos.\"},{\"heading\":false,\"text\":\"--Que le echen a usted un roción --dijo la de Pinto a su amo-- a ver si le calman a usted esos ardores de la juventud.\"},{\"heading\":false,\"text\":\"--Pero esa invención --añadió Benjamín oponiéndose aún a la evidencia-como la de los pozos artesianos, la porcelana, los puentes colgantes, los naipes y el papel moneda, no datan en China, según nuestros historiógrafos, sino de los siglos octavo al trece, y estamos a principios del tercero. Pues si bien es cierto que el sabio sinólogo Estanislao Julien comunicó en 1847 a la academia de ciencias de París la fecha de ciertos descubrimientos de los chinos, las épocas que cita parecen tan fabulosas que el orgullo europeo se resiste a aceptarlas.\"},{\"heading\":false,\"text\":\"--¿Y qué dice de nosotros ese buen señor?\"},{\"heading\":false,\"text\":\"--Supone que en el siglo X de nuestra era ya poseíais el grabado y la litografía.\"},{\"heading\":false,\"text\":\"El emperador por toda respuesta le enseñó su retrato y el de su difunta, que, hechos por ambos procedimientos, pendían de los muros con siete siglos de antelación a la hipótesis de Julien.\"},{\"heading\":false,\"text\":\"--¿Y qué más refiere? --añadió Hien-ti.\"},{\"heading\":false,\"text\":\"El políglota, bajando la voz, repuso:\"},{\"heading\":false,\"text\":\"--Que en el siglo XI erais dueños de la maravillosa invención de Gutenberg.\"},{\"heading\":false,\"text\":\"Y así diciendo le alargó un periódico al monarca, explicándole al propio tiempo la misión que venía a llenar la prensa periódica.\"},{\"heading\":false,\"text\":\"--¡Ah! Sí. Mi predecesor trató de permitir la publicación de una gaceta con el fin de que todos sus vasallos pudieran convertirse en censores de los abusos del poder; pero en vez de utilizarla ellos como instrumento de censura, la convirtieron en palenque de diatribas e insultos, y fue preciso derogar la autorización y limitar el permiso de imprimir a la publicación de nuestros libros sagrados.\"},{\"heading\":false,\"text\":\"E hizo ver a los viajeros un ejemplar de los apotegmas de Confucio que, ricamente encuadernado, yacía sobre un velador.\"},{\"heading\":false,\"text\":\"Los dos sabios se abalanzaron a él con hidrofobia bibliómana; pero las sombras de la noche eran ya tan espesas que no lo hubieran podido examinar si Tsao-pi, dando la orden de encender las luces, no hubiera mandado entrar a unos esclavos que con unas esponjas, empapadas en cierta substancia inflamable, llenaron de claridad el recinto con solo aplicar la llama a unos mecheros salientes en el muro.\"},{\"heading\":false,\"text\":\"--¡Gas! --fue el grito unánime.\"},{\"heading\":false,\"text\":\"--Sí, gas --dijo tranquilamente el emperador.\"},{\"heading\":false,\"text\":\"--¿Pero de dónde lo extraen?\"},{\"heading\":false,\"text\":\"--Del seno de la tierra; de las materias fecales, cuyas emanaciones conducimos a donde queremos merced a unos tubos subterráneos.\"},{\"heading\":false,\"text\":\"--Eso también lo dice Julien; pero se lo atribuye al siglo VIII. No os admire, señor, nuestra extrañeza; pues aunque teníamos vagos indicios de vuestros adelantos, son estos tales y tan en abierta contradicción con la decadencia y el atraso de la China del siglo XIX, que no nos atrevíamos a dar crédito a la civilización del pasado por el estacionamiento y hasta retroceso del presente.\"},{\"heading\":false,\"text\":\"--Todas las naciones que alcanzan un gran desenvolvimiento, suelen ver desaparecer su grandeza, que utilizan otros estados nacientes --arguyó Hien-ti, no creyendo prudente, en razón de los planes que abrigaba, decir a los viajeros que eran unos impostores vulgares que querían hacer pasar por prodigios de supuestas edades futuras las nociones más rudimentarias de la ciencia practicada a la sazón.\"},{\"heading\":false,\"text\":\"--¿De modo que habrá que tomar por artículo de fe el aserto de Julien que, con la tinta y el papel de trapo, coloca la pólvora entre los descubrimientos del siglo segundo, anterior a Jesucristo?\"},{\"heading\":false,\"text\":\"--¿La pólvora?\"},{\"heading\":false,\"text\":\"--Sí. Esa composición de setenta y cinco partes de sal de nitro con quince y media de carbón y nueve y media de azufre, atribuida en la Edad media al monje alemán Schwartz, y que el sinólogo en cuestión cree que fue introducida en Europa, de la China, donde el nitrato de potasa lo da ya preparado la naturaleza.\"},{\"heading\":false,\"text\":\"--Como no te refieras a los cañones, no sé qué quieres decir. A ver si es esto.\"},{\"heading\":false,\"text\":\"Y tomando el emperador de una panoplia una flecha embadurnada de un polvo negro (que no era otra cosa sino pólvora), a cuyo extremo inferior había un cohete amarrado, prendió fuego a la corta mecha que de este pendía, apoyó el rehilete en la cuerda del arco y disparándolo por la ventana se incendió en el espacio como una lengua de fuego, acrecentando su marcha con la nueva fuerza impulsiva que le prestaba la explosión del petardo en la atmósfera.\"},{\"heading\":false,\"text\":\"El monje alemán quedó relegado desde aquel momento a la categoría de los seres fabulosos.\"},{\"heading\":false,\"text\":\"--No dudo --prosiguió Hien-ti-- que todos estos procedimientos se perfeccionarán con la marcha de los siglos; pero ya veis que esencialmente no podéis enseñarnos nada nuevo; y la prueba es que venís a nuestros dominios en busca del secreto de la inmortalidad que se tiene por dogma entre los sectarios de los espíritus del celeste imperio. Pues bien; no quiero que vuestro viaje sea infructuoso. Yo os descubriré ese arcano con una condición.\"},{\"heading\":false,\"text\":\"--¿Cuál?\"},{\"heading\":false,\"text\":\"--Ayer he perdido a la emperatriz mi compañera; las leyes me autorizan a tomar nueva esposa transcurridas que sean las cuarenta y ocho horas del luto nacional. Mañana vence el plazo. Concededme que comparta el trono con esta linda joven.\"},{\"heading\":false,\"text\":\"Y acompañando la acción a la frase puso entre las suyas la mano de Clara que, asustada, la retiró, pidiendo que la explicaran tan brusca acometida. La traducción que Benjamín les hizo de la exigencia del monarca sublevó a la pupila y exasperó a don Sindulfo, que en vano había puesto en las autoritarias leyes del imperio la esperanza de ser el esposo de su sobrina.\"},{\"heading\":false,\"text\":\"--Dígale usted que no se ha hecho la miel para la boca del asno --argumentaba la maritornes. Y todos, menos el políglota, se disponían a protestar tumultuosamente, cuando la idea de poder perder la vida si se obstinaban en rehusar, sugirió a don Sindulfo un plan conciliador.\"},{\"heading\":false,\"text\":\"--Finjamos ceder --dijo por lo bajo a los suyos--, y una vez restituidos al Anacronópete, a donde pediremos que se nos conduzca para disponer los trajes de ceremonia, nos ponemos en movimiento y que nos echen galgos.\"},{\"heading\":false,\"text\":\"Las muchachas asintieron a la proposición; pero Benjamín se resistía porque la fuga le privaba del secreto de la inmortalidad tan codiciado. Sin embargo, no tardó en avenirse aparentemente, pues abrigaba el proyecto que más tarde se verá.\"},{\"heading\":false,\"text\":\"Entre tanto el emperador organizaba con su ministro la manera de desembarazarse de los embaucadores, en cuanto la autoridad del jefe de la familia (tan ineludible en China para el matrimonio) le concediese el honor a que aspiraba.\"},{\"heading\":false,\"text\":\"El ritual chino prescribe que la novia quede en su casa hasta que la comitiva nupcial vaya en su busca para transportarla a la del marido. Determinóse, pues, que los viajeros volviesen a su morada de donde al día siguiente por la noche iría a sacarla el cortejo imperial.\"},{\"heading\":false,\"text\":\"Despidiéronse todos de Hien-ti y de su ministro; y, acompañados de una guardia de honor, para custodiar exteriormente el Anacronópete, y de multitud de esclavos cargados de provisiones y presentes, se encaminaron los anacronóbatas al vehículo cuya puerta abrió Benjamín entrando en él el primero.\"},{\"heading\":false,\"text\":\"En cuanto los servidores se hubieron retirado y los centinelas esparcido por los alrededores del coloso, a distancia respetuosa, don Sindulfo tocando el regulador y soltando una carcajada:\"},{\"heading\":false,\"text\":\"--No dirán que no los engañamos como a chinos --exclamó.\"},{\"heading\":false,\"text\":\"Pero de pronto quedóse pálido; el engañado era él. El aparato eléctrico no funcionaba. Estaban reducidos a prisión.\"}]},{\"title\":\"El anacronópete — capítulo xiv\",\"blocks\":[{\"heading\":false,\"text\":\"Un huésped inesperado\"},{\"heading\":false,\"text\":\"Triste, como la misma noche triste de Hernán Cortés en la víspera de la batalla de Otumba, fue la pasada a bordo del Anacronópete por los expedicionarios. Clara, la más digna de compasión sin duda, no hacía sino llorar y preguntarse, en su situación desesperada, qué delito había cometido para ser directa o indirectamente la víctima expiatoria de todos los caprichos del destino inexorable. El tutor protestaba de su buena fe en las circunstancias presentes, puesto que su plan al acceder había sido burlar los designios del emperador emprendiendo la fuga; pero sus buenos propósitos, que no encerraban más que una mira egoísta, se estrellaban contra una fuerza mayor que los reducía a la inmovilidad contra todas las previsiones de sus cálculos científicos.\"},{\"heading\":false,\"text\":\"--Una solución de continuidad no es la causa de la paralización, puesto que las corrientes circulan sin impedimento; decía el sabio fundándose en las observaciones que él y su amigo habían hecho repetidas veces en el vehículo y sin sospechar que Benjamín pudiera hacerle traición.\"},{\"heading\":false,\"text\":\"--Me juego la cabeza de usted --argüía Juana a su señor-- a que si llamamos a un herrero chino nos dice en seguida en qué consiste la atascadura del carro. ¡Vaya! Que han quedado ustedes lucidos delante de su majestad. Alumbre usted su inteligencia, hombre, ya que, según le ha probado a usted el emperador, lleva usted una fábrica de gas en su persona.\"},{\"heading\":false,\"text\":\"Don Sindulfo miraba a su amigo en demanda de consejo; pero Benjamín permanecía mudo como todo el que tiene sobre su conciencia algún delito de que no se arrepiente y cuya responsabilidad procura eludir con el silencio. Y en efecto, la culpa de aquella situación era exclusivamente del políglota. Verdad es que él ignoraba los proyectos de Hien-ti sobre la parte masculina de la tripulación y confiaba en que un subterfugio cualquiera restituiría a Clara al Anacronópete a fin de escapar apenas terminase la ceremonia, pero la ciencia es tan egoísta que todo lo juzga _anima vili_ cuando se trata de un experimento; y la idea de perder el secreto de la inmortalidad, si abandonaban la China del siglo III, podía más en él que las contingencias a que, si se quedaban, exponía a sus compañeros de infortunio. Así es que entrando el primero en el Anacronópete, como hemos visto, colocó capciosamente una jícara de porcelana entre los conductores del fluido y el volante, con cuyo aislador perdida la corriente eléctrica, el aparato dejaba de funcionar. Cada vez que don Sindulfo, sin sospechar la asechanza de su correligionario, verificaba con él un reconocimiento, Benjamín, afectando oficiosidad, se adelantaba y escabullía el pocillo con un hábil escamoteo, volviéndolo a ingerir en cuanto el sabio, convencido de que no había ningún obstáculo, pasaba adelante para poner en actividad el mecanismo.\"},{\"heading\":false,\"text\":\"Agotados todos los recursos técnicos se pensó seriamente en desertar; pero ni era posible realizarlo con éxito, toda vez que la guardia afecta a su servicio tenía la orden de no abandonar un instante a los viajeros sospechosos, ni aun suponiendo posible la evasión mejoraban su precaria suerte; pues advirtiendo su ausencia, poco habían de tardar en dar alcance a los fugitivos. Además existía otra razón poderosa para oponerse; y era que no podían abandonar el Anacronópete sin correr el riesgo de permanecer indefinidamente a más de mil seiscientos años de distancia de su edad; cosa que hubiera sonreído a don Sindulfo si las circunstancias locales le hubieran permitido realizar su desideratum de imponer a la pupila su conyugal yugo.\"},{\"heading\":false,\"text\":\"Tomóse pues la resolución de esperar a que la Providencia les enviara con la luz del nuevo día algún rayo de esperanza, y rendidos por la fatiga se recostaron en sus lechos.\"},{\"heading\":false,\"text\":\"La noche fue larga como de dolor: cada cuarto de hora el grito de los centinelas cortaba la monotonía del silencio interrumpido además a intervalos por unos golpes secos como los que da el martillo sobre el clavo. El ruido parecía subir de la cala y, temiendo alguna invasión de los celestiales, don Sindulfo y Benjamín bajaron a la bodega; pero aunque permanecieron allí más de quince minutos, no volvieron a oír los martillazos que no obstante se reprodujeron apenas restituidos a sus habitaciones.\"},{\"heading\":false,\"text\":\"--Es por este otro lado sin duda --exclamó Benjamín.\"},{\"heading\":false,\"text\":\"--Sí --interpuso el sabio--. Algún arco de triunfo que nos preparan.\"},{\"heading\":false,\"text\":\"Y absortos en sus pensamientos quedáronse ambos aguardando la aurora que no tardó en venirlos a saludar con una sonrisa que parecía feliz augurio de esperanza. Pero el día, sin detenerse en su carrera, seguía su curso no solo desprovisto de todo medio de salvación, sino devorando en cada minuto una ilusión de los viajeros.\"},{\"heading\":false,\"text\":\"Al anochecer espiraba el plazo de las cuarenta y ocho horas prescrito por la ley para el luto nacional, y acto continuo la nueva emperatriz debía dirigirse al _yamen_ a compartir el trono con el soberano.\"},{\"heading\":false,\"text\":\"Desde muy temprano fue visitado el Anacronópete por la servidumbre de Hien-ti, que, con opíparos manjares, ricos presentes y trajes de boda, a la usanza china, para todos los expedicionarios, estaba presidida por _King-seng_, maestro de ceremonias de la corte y joven simpático, de gallarda apostura, a quien todos otorgaron una preferencia espontánea, no sé si por el sello de tristeza que llevaba en el semblante o por las atenciones que guardaba a los cautivos.\"},{\"heading\":false,\"text\":\"Por fin al declinar la tarde llegaron las esclavas y los eunucos encargados de vestir y aderezar el tocado, así de la contrayente como de su séquito, lo que quería decir que la hora había sonado de abandonar toda esperanza. La desesperación, último baluarte del impotente, se apoderó de los expedicionarios. Clara y Juanita abrazadas en un rincón se resistían heroicamente a entregar sus cuerpos a aquel para ellas fúnebre atavío. Don Sindulfo con los ojos extraviados incitaba a su amigo a que protestase de aquella violencia en el idioma de Confucio, como él lo hacía en el más enérgico aragonés. Benjamín, sin arrepentirse de lo hecho, empezaba a experimentar cierta compasión por sus correligionarios; y todo era lamentos, confusión y desorden cuando el maestro de ceremonias, mandando salir del laboratorio a la servidumbre y tomando aparte a los viajeros:\"},{\"heading\":false,\"text\":\"--Desgraciados --les dijo-- no temáis; yo os salvaré.\"},{\"heading\":false,\"text\":\"Júzguese de la sorpresa y de la alegría de los cuatro ante las palabras de King-seng, cuya traducción les iba haciendo Benjamín. Clara le estrechaba las manos, don Sindulfo le daba gracias en latín por si las humanidades habían llegado hasta el celeste Imperio, y Juanita le largó un abrazo a la usanza de Pinto que casi lo derriba.\"},{\"heading\":false,\"text\":\"--Silencio, imprudentes --prosiguió el ángel tutelar de los desahuciados--. Evitad que nos oigan. El emperador os ha tomado por _Tao-sse_ venidos a Ho-nan para renovar las luchas de los gorros amarillos y se propone exterminaros apenas verificada la ceremonia nupcial. Esta boda no la lleva a cabo más que para saciar un grosero apetito, toda vez que una ley reciente le prohíbe aumentar el número de sus concubinas.\"},{\"heading\":false,\"text\":\"--¡Qué horror! --balbucearon los reos.\"},{\"heading\":false,\"text\":\"--Sí; pero aquí estoy yo que lo sé todo.\"},{\"heading\":false,\"text\":\"--¿Cómo? --inquirieron los circunstantes estrechando el grupo.\"},{\"heading\":false,\"text\":\"--Hace como diez lunas que llegó de Occidente un hombre fugitivo. Oculto en Ho-nan encontró medio de ponerse en contacto con la emperatriz _Sun-ché_, la esposa mártir del opresor. Lo que le dijo lo ignoro; pero la augusta señora, que me honraba con sus confidencias, me dio a comprender que aquel hombre era el que en sus apotegmas dice Confucio que traería de Occidente la revelación de su doctrina y que, en efecto, le había ofrecido la inmortalidad.\"},{\"heading\":false,\"text\":\"--¡La inmortalidad! --repitieron todos escuchando con interés creciente un relato que justificaba la monomanía de Benjamín.\"},{\"heading\":false,\"text\":\"--Sí --prosiguió King-seng--; para ella y para los suyos. La emperatriz me encargó de crear prosélitos y ordenó al misterioso personaje que hiciese venir de sus apartadas regiones algunas familias que alimentaran y propagasen sus luces. Vosotros sois sin duda los primeros en acudir al llamamiento y yo os brindo con mi protección.\"},{\"heading\":false,\"text\":\"La oferta tenía demasiada importancia para que nadie se atreviera a destruir la suposición del maestro de ceremonias; así es que viendo en ello su salvación, se convinieron en seguirle la corriente, y sobre todo el políglota que tocaba la meta de sus aspiraciones.\"},{\"heading\":false,\"text\":\"--¿Y ese occidental dónde encontrarle? --preguntó Benjamín.\"},{\"heading\":false,\"text\":\"--La desgracia os persigue --adujo King-seng--. Ha muerto.\"},{\"heading\":false,\"text\":\"--¡Muerto! --exclamaron todos fingiendo una profunda aflicción.\"},{\"heading\":false,\"text\":\"--Pero vosotros proseguiréis su obra. Hace dos días el emperador, que ya miraba a su esposa con malos ojos por creerla sectaria de los _Tao-sse_, sorprendió al extranjero en conferencia con la emperatriz; y al oír que la brindaba con la inmortalidad, acabó por convencerse de que ambos pertenecían a la secta de los embaucadores. Tsao-pi, su primer ministro y jefe del partido de los letrados, pidió venganza; y, mientras el occidental era aserrado en la plaza de las ejecuciones, anunciábase al pueblo, para el que es un arcano cuanto en palacio ocurre, que Sun-ché había sucumbido repentinamente; pero la infeliz había sido enterrada viva en las mazmorras del yamen por orden de su despiadado esposo.\"},{\"heading\":false,\"text\":\"--¡Qué inhumanidad! --arguyeron los oyentes a excepción de Benjamín que parecía absorto en profundas reflexiones.\"},{\"heading\":false,\"text\":\"--La indignación ha dado un grito en el pecho de todos los parciales de la emperatriz, que aún es posible que exista, porque ese género de muerte es lento. Pero animada o cadáver la sacaremos de su tumba, para lo cual, mis secuaces reunidos, harán que estalle la rebelión mientras se celebre el banquete nupcial. Vosotros desechad todo temor; yo me encargo de protegeros con mis tropas; pero disponeos al ceremonial secundando así mis planes, pues la menor sospecha puede perdernos. Confiad en la gente que he traído para vuestro servicio. Me obedecen con absoluta abnegación. Andad, que la hora avanza.\"},{\"heading\":false,\"text\":\"La idea de una lucha con resultados desconocidos no era en verdad halagüeña para gentes pacíficas, ajenas a los intereses del imperio; pero su situación particular se presentaba tan erizada de peligros insuperables, que no titubearon en decidirse por el término del dilema que les ofrecía alguna probabilidad de éxito.\"},{\"heading\":false,\"text\":\"Llamada la servidumbre dejáronse ataviar con todo el esplendor debido a su rango, y aun sazonada estuvo la tarea con algunos chistes, pues no hay que olvidar que eran españoles los que corrían tamañas contingencias.\"},{\"heading\":false,\"text\":\"Concluido el tocado, un ruido infernal de tamboriles, címbalos y el obligado _gong_ o campana china, además de multitud de linternas de caprichosa estructura que por los abiertos discos divisaron, les anunció que la comitiva imperial llegaba a las puertas del Anacronópete, donde se detuvo, pues el ritual prescribe que no se invada el domicilio de la virgen.\"},{\"heading\":false,\"text\":\"--Adelante --exclamó King-seng tomando de la mano a Clara para conducirla a la litera en nombre del emperador.\"},{\"heading\":false,\"text\":\"--¡Adelante! --gritaron todos poseídos del entusiasmo que infunde la esperanza.\"},{\"heading\":false,\"text\":\"Y atravesando estaban la bodega para ganar el portón, cuando unos golpes secos y repetidos obligaron al séquito a pararse en medio de la estancia.\"},{\"heading\":false,\"text\":\"--¿Qué es ello? --preguntó el maestro.\"},{\"heading\":false,\"text\":\"--¿No habéis oído? --repuso Benjamín.\"},{\"heading\":false,\"text\":\"--Sí. Parece que alguien llama.\"},{\"heading\":false,\"text\":\"Y como todos prestasen atención, los golpes se reprodujeron con mayor insistencia.\"},{\"heading\":false,\"text\":\"--¿No advertís? --hizo notar Clara--. Resuenan por este lado.\"},{\"heading\":false,\"text\":\"--En la caja --añadió Juanita consultando con los ojos al anticuario.\"},{\"heading\":false,\"text\":\"--¡Cómo! ¿En la de la momia? --balbuceó don Sindulfo tan asombrado como sus compañeros.\"},{\"heading\":false,\"text\":\"En esto, Benjamín que había permanecido en la actitud de la meditación:\"},{\"heading\":false,\"text\":\"--Sí; eso es --articuló, dándose un golpe en la frente.\"},{\"heading\":false,\"text\":\"--¿El qué? --prorrumpieron todos en coro.\"},{\"heading\":false,\"text\":\"--Que retrogradando hemos llegado al período en que la emperatriz aún vivía, si bien enterrada, y mi momia no es sino la desgraciada consorte del emperador Hien-ti.\"},{\"heading\":false,\"text\":\"Y dirigiéndose estaba ya al sarcófago, cuando un nuevo golpe más formidable que los otros hizo saltar los goznes de la caja, y una hermosa mujer en toda la lozanía de la juventud salió de aquel lecho de muerte.\"},{\"heading\":false,\"text\":\"--¡Sun-ché! --gritaron todos los chinos reconociéndola y prosternándose ante la maravillosa aparición.\"},{\"heading\":false,\"text\":\"--¡La emperatriz! --repitieron los atónitos expedicionarios.\"},{\"heading\":false,\"text\":\"Juanita no decía nada; pero en conciencia empezaba a sospechar que los sabios no eran tan estúpidos como ella se figuraba.\"}]},{\"title\":\"El anacronópete — capítulo xv\",\"blocks\":[{\"heading\":false,\"text\":\"La resurrección de los muertos antes del Juicio final\"},{\"heading\":false,\"text\":\"Venganza! --fue la primera frase que articuló la emperatriz al verse rodeada de los suyos.\"},{\"heading\":false,\"text\":\"--¡Venganza! --repitieron sus parciales aclamando a Sun-ché.\"},{\"heading\":false,\"text\":\"--Dejad --prosiguió la egregia dama-- que bese las rodillas de la criatura que ha velado por mi existencia.\"},{\"heading\":false,\"text\":\"Y sus ojos arrasados de lágrimas se posaron con gratitud en King-seng.\"},{\"heading\":false,\"text\":\"--No es mía desgraciadamente la honra de haber salvado vuestros preciosos días --replicó el maestro de ceremonias que, no explicándose de otro modo la presencia de la emperatriz en el Anacronópete, supuso desde luego que sus tripulantes, más felices que él, habían logrado con astucia sacar de las mazmorras a la víctima inocente de Hien-ti.\"},{\"heading\":false,\"text\":\"Los viajeros, aunque sabían que la momia encerrada en un sarcófago de alcanfor de época harto remota para poder resistir victoriosamente la acción retrógrada del tiempo, debía su resurrección a la circunstancia de no estar sometida a la inalterabilidad, dejaron al mandarín en su creencia, tanto por lo que tenía de racional, cuanto por lo que favorecía sus planes.\"},{\"heading\":false,\"text\":\"--¡Cómo! ¿Son estos? --adujo la emperatriz al enterarse de la situación y besando con transportes de gozo a Clara y a Juanita; con gran contentamiento de la última que por primera vez se veía objeto de las caricias de una soberana.\"},{\"heading\":false,\"text\":\"--Sí; estos son los que han roto vuestras cadenas. Desgraciadamente llegaron tarde para librar de la muerte al occidental su hermano, que como no ignoráis os precedió en el suplicio.\"},{\"heading\":false,\"text\":\"--¡Pobre mártir! --articuló Sun-ché tributando un triste recuerdo al que fue su mejor amigo.\"},{\"heading\":false,\"text\":\"Pero de pronto, levantando sus hermosas pupilas negras y fijándolas en don Sindulfo y en Benjamín que, con fruición arqueológica, saboreaban aquel triunfo de la ciencia,\"},{\"heading\":false,\"text\":\"--Es extraño --repuso--. Yo os he visto antes de ahora. Vuestras facciones despiertan en mí un recuerdo vago y confuso que no acierto a precisar.\"},{\"heading\":false,\"text\":\"--¡Ca! No lo crea Usía --interrumpió Juana--. Si estos moscones no se separan de nuestro lado. Son dos granos malignos que nos han salido a la señorita y a mí.\"},{\"heading\":false,\"text\":\"El políglota, buscando la lógica de tamaño fenómeno, supuso, y así se lo comunicó a su amigo, que la momia al volver a la vida los había visto en la bodega a través de algún resquicio de la caja; pero que, expuesta a síncopes frecuentes antes de entrar en la plenitud de la existencia, había perdido la noción del tiempo en sus alternativas de insensibilidad, atribuyendo así a épocas remotas sucesos recientes. Error craso, como se probará en el curso de esta inverosímil historia.\"},{\"heading\":false,\"text\":\"--¿Pero qué significa esta música? ¿Qué anuncian estos aprestos de fiesta? --preguntó Sun-ché al oír unos golpes de gong con los que se daba a entender a la comitiva que la hora avanzaba y que la paciencia del emperador tocaba a su término.\"},{\"heading\":false,\"text\":\"Entonces King-seng narró lo ocurrido y puso al corriente a su soberana de cómo Hien-ti, pretextando al pueblo su muerte por accidente natural, se disponía a celebrar segundas nupcias con la extranjera a cuyos parientes había ofrecido, en cambio del consentimiento, el secreto de la inmortalidad.\"},{\"heading\":false,\"text\":\"--Miente el infame --exclamó con voz de trueno la emperatriz--. Lo que medita es vuestro exterminio; pero no lo conseguirá.\"},{\"heading\":false,\"text\":\"Y por un instintivo movimiento se abrazó a don Sindulfo como para defenderle de toda asechanza.\"},{\"heading\":false,\"text\":\"--No hay más; la ha flechado --dijo Juana a su señorita--. A ver si así la deja a usted de mortificar ese sinapismo.\"},{\"heading\":false,\"text\":\"--No lo conseguirá --replicó el maestro de ceremonias--; porque presintiendo que aún no habíais exhalado el postrer suspiro, vuestros parciales solo aguardan a que dé principio la ceremonia para provocar la rebelión.\"},{\"heading\":false,\"text\":\"--Pues bien, marchemos; yo os guiaré al combate.\"},{\"heading\":false,\"text\":\"--Poco a poco --objetó Benjamín, a quien el bélico entusiasmo de la augusta señora cercenaba las probabilidades de éxito si, vencidos en la refriega, no podía hacerse dueño del talismán que tanto ambicionaba--. La prudencia dicta meditar bien el caso antes de abandonarse a una aventura peligrosa.\"},{\"heading\":false,\"text\":\"--Sí --adujo King-seng--. Vuestra egregia persona no debe exponerse. Todo está ya previsto para caer oportunamente sobre el tirano cuando menos lo presuma. No por anticipar el triunfo lo convirtamos en derrota.\"},{\"heading\":false,\"text\":\"--Esperemos a que nos libre el arcano de la inmortalidad.\"},{\"heading\":false,\"text\":\"--¿La inmortalidad? --inquirió con cierto orgullo la emperatriz--. ¿Y qué sabe él de ella? Os ha mentido. Yo sola poseo las pruebas que me dio el occidental y que he sabido sustraer a las requisas de Hien-ti ocultándolas en lo más recóndito del palacio.\"},{\"heading\":false,\"text\":\"--Con doble motivo debéis proceder con cautela si vuestro objeto es recuperarlas; pues no imagino que queráis dejar ignorada tan preciosa conquista.\"},{\"heading\":false,\"text\":\"--¡Oh! No. Decís bien. Es preciso aclarar ese enigma cuya solución parece hallarse en Occidente.\"},{\"heading\":false,\"text\":\"--¡Cómo! --interrogaron todos.\"},{\"heading\":false,\"text\":\"--No es este el momento de las explicaciones --continuó Sun-ché--. La noche avanza y el tirano debe estar impaciente. Seguid a la comitiva; fingid doblegaros a los proyectos del emperador. Yo os precedo a palacio para hacerme con las pruebas; y en cuanto la ceremonia comience en el patio del Dragón, me presento a mis secuaces; tras breve lucha os apoderáis de Hien-ti y, libertando al pueblo de un opresor, yo os indicaré quién debe compartir conmigo el trono de Fo-hi.\"},{\"heading\":false,\"text\":\"Y así hablando, lanzó una mirada a don Sindulfo que heló a este la sangre en las venas, y le valió el que su criada le dijese al oído:\"},{\"heading\":false,\"text\":\"--La suerte no es para el que la busca sino para el que la encuentra. ¡Viva don Pichichi primero! ¡Valiente rey de bastos va usted a hacer!\"},{\"heading\":false,\"text\":\"Todos iban a prorrumpir en una aclamación; pero Sun-ché imponiéndoles silencio, vistióse, para no ser reconocida, las túnicas de una esclava; y seguida de dos eunucos de su confianza absoluta, salió del Anacronópete. King-seng llevando de la mano a Clara la condujo al palanquín; y cerrado este con llave, la música hirió el espacio y el cortejo nupcial tomó lentamente, entre la apiñada multitud, el camino del _yamen_.\"},{\"heading\":false,\"text\":\"Catorce patios había que atravesar para dirigirse a las habitaciones imperiales, siendo el llamado de honor el inmediato al cuerpo del edificio. En el centro se hallaba el dragón sagrado, monstruo fundido en bronce con las fauces abiertas rasantes al suelo y la cola enroscada perdida en las alturas. Limitaban el área innumerables kioskos que servían de tribuna en las grandes solemnidades para los mandarines y dignatarios de alto rango y que formaban, por decirlo así, escolta al templete imperial al que solo el monarca, su familia y su primer ministro podían tener acceso.\"},{\"heading\":false,\"text\":\"Todas estas fábricas, como el _yamen_ que abierto a cuatro vientos se erguía en el fondo sobre una suntuosa escalinata de mármol con adornos de jade sanguíneo, estaban profusamente iluminadas con miles de linternas de múltiples formas y dimensiones: ya un tulipán y una rosa robaban sus colores a la naturaleza, ya un enorme globo a través de sus paredes hechas de arroz con toda la transparencia del cristal, lucía figuras de movimiento. Junto a un pez de luz que agitaba sus natatorias y coleaba, veíanse dos gallos que libraban entre sí descomunal combate. Ora eran dos medias sandías las que luciendo su rojiza pulpa pendían de un arquitrabe, ora una langosta la que contrayendo y dilatando sus articulaciones coronaba el vértice de un frontón. Gomas odorantes se consumían en centenares de pebeteros; escudos de flores simulando mariposas e insectos alados embalsamaban el ambiente. La entrada estaba custodiada por los dioses porteros: dos gigantescas figuras de siniestra faz, de musculatura titánica y de una riqueza indumentaria solo comparable con su candor artístico. La guardia de doncellas rodeaba el templete del emperador; las demás fuerzas militares con sus arcos terciados y sus partesanas en reposo ocupaban el segundo término. La baja servidumbre del palacio invadía el graderío.\"},{\"heading\":false,\"text\":\"--¿Estás seguro de lo que dices? --murmuró por lo bajo el monarca a Tsao-pi para evitar el ser oído por sus tres concubinas oficiales que detrás de él tomaban asiento.\"},{\"heading\":false,\"text\":\"--No tardaréis en convenceros ante la evidencia. La rebelión debe estallar esta misma noche en el _yamen_; pero será sofocada, yo os lo juro. Los rebeldes me son conocidos y mis precauciones están tomadas.\"},{\"heading\":false,\"text\":\"--¿De modo que esos impostores eran realmente sectarios de los gorros amarillos?\"},{\"heading\":false,\"text\":\"--Y parciales de la emperatriz.\"},{\"heading\":false,\"text\":\"Aquí llegaban en su diálogo cuando la comitiva nupcial empezó a trasponer con solemne paso el patio de honor, y a la voz de alerta cada cual se aprestó a llenar su cometido. Linternas y banderolas componían el fondo de esta procesión terminada por el palanquín de la desposada, a cuya puerta caminaba de vigía el maestro de ceremonias delegado por el augusto consorte para la presentación. Don Sindulfo, Benjamín y Juana hacían uso de su derecho de rodear la litera como miembros de la familia. Los cortesanos y la servidumbre venían detrás. Fuerzas de caballería cerraban la marcha.\"},{\"heading\":false,\"text\":\"Depuesta la preciosa carga en mitad del patio, previas las rituales genuflexiones, King-seng entregó la llave del palanquín al monarca que, saliendo al encuentro de su futura, la condujo al templete. Acto continuo el jefe de los letrados leyó los preceptos de Confucio sobre los deberes que contrae la mujer para con el marido; y a felicitar a Hien-ti comenzaba en nombre de la academia cuando una melancólica canción de ritmo particular hizo volver la cabeza a los circunstantes que, atónitos, vieron aparecer a la emperatriz por entre las abiertas fauces del dragón sagrado.\"},{\"heading\":false,\"text\":\"--_¡Sun-ché!_ --exclamó toda la corte presa de sentimientos distintos.\"},{\"heading\":false,\"text\":\"--¡Traición! --gritó Hien-ti ante la resurrección de su víctima.\"},{\"heading\":false,\"text\":\"Pero la extrañeza de los celestiales al recuperar a su soberana era juego de niños ante la que experimentó Juanita al sentirse cogida de los brazos como con tenazas por don Sindulfo y Benjamín que, con los ojos fuera de las órbitas y el pelo de punta balbuceaban entre sacudidas nerviosas:\"},{\"heading\":false,\"text\":\"--¡Mamerta!...\"},{\"heading\":false,\"text\":\"--¡Mi mujer!...\"},{\"heading\":false,\"text\":\"Juanita creyó que estaban locos; pero no; era en efecto que los sabios habían reconocido en las modulaciones de aquella cantinela el célebre e ininteligible estribillo con que, en vida, les destrozaba el tímpano constantemente la hija del banquero, la muda de los garbanzos, la esposa del inventor ahogada con su padre, como recordarán mis lectores, al tomar un baño en las playas de Biarritz.\"},{\"heading\":false,\"text\":\"En vano buscaban en los rasgos fisonómicos de la emperatriz trazos que acusasen alguna afinidad con la difunta. Empezando por que hablaba, todo en ella era diametralmente opuesto; mas no obstante, aquella rara melodía ¿era posible que fuese calcada con tan asombrosa exactitud de pausas e inflexiones por otro ser humano nacido a más de tres mil leguas de distancia y a dieciséis siglos de separación del primitivo ejemplar?\"},{\"heading\":false,\"text\":\"Los dos amigos no tuvieron tiempo de rectificar ni de ratificar sus impresiones, porque la impaciencia de los rebeldes desbordada por el entusiasmo, les hizo prorrumpir en un viva a Sun-ché; y antes de que los secuaces del emperador pudieran apercibirse al combate, volvieron contra ellos sus armas. Por desgracia para los generosos libertadores, la previsión de Tsao-pi había hecho frotar las cuerdas con una sustancia corrosiva; de modo que al tender los arcos aquellas se rompieron; y las flechas en vez de salir disparadas por la tensión cayeron a sus pies dejándolos inermes.\"},{\"heading\":false,\"text\":\"--¡A ellos! --gritó el calado a los suyos; y sin respetar jerarquías ni condiciones, la emperatriz, los anacronóbatas y los insurrectos fueron ceñidos por estrechas ligaduras y sus gritos ahogados por mordazas de cuero.\"},{\"heading\":false,\"text\":\"--¿Tenéis más cómplices? --preguntó el emperador a Clara, que con desesperados esfuerzos protestaba de su inocencia.\"},{\"heading\":false,\"text\":\"--Advierte --añadió Hien-ti-- que mis bodas no han sido más que un pretexto para descubrir vuestros planes. Solo la delación puede salvarte la vida. Responde.\"},{\"heading\":false,\"text\":\"Clara hizo un gesto negativo.\"},{\"heading\":false,\"text\":\"--¿Y bien? ¿Vuestras órdenes? --dijo Tsao-pi al tirano.\"},{\"heading\":false,\"text\":\"--Cumple con tu deber --repuso este tras breve pausa--. Y para que mi pueblo vea que nada me hace retroceder ante la salud del estado, comienza el sacrificio por la emperatriz rebelde y por los encubiertos partidarios de los gorros amarillos.\"},{\"heading\":false,\"text\":\"Y mientras obligaban a los reos a arrodillarse delante del dragón, un pelotón de arqueros destacándose de las fuerzas se aprestó espontáneamente a consumar la hecatombe.\"},{\"heading\":false,\"text\":\"Apuntaron en efecto; pero al dar el emperador la voz de tirar, volvieron contra este sus armas y el feroz Hien-ti cayó sin vida en el suelo atravesado por las flechas y bañado en sangre. Sus soldados, poseídos de la superstición de que cuando el jefe muere, sus legiones no alcanzan jamás la victoria, emprendieron despavoridos la fuga sin que los esfuerzos de Tsao-pi los pudieran detener, y perseguidos por los defensores de Sun-ché que libertados de sus trabas por los arqueros corrieron a coronar su obra.\"},{\"heading\":false,\"text\":\"Entretanto las inocentes víctimas restituidas a la existencia, se abrazaban entre sí, lloraban de emoción; y por señas, pues la voz no salía del pecho, daban gracias a sus salvadores.\"},{\"heading\":false,\"text\":\"--¿A quién debemos la vida? --pudo por fin articular Clara.\"},{\"heading\":false,\"text\":\"--¡Viva España! --gritaron diecisiete voces. Y los arqueros despojándose de sus vestiduras dejaron ver a los hijos de Marte en toda la plenitud de su desarrollo.\"},{\"heading\":false,\"text\":\"--¡Ellos! --exclamaron sus compatriotas ante aquel espectáculo más fenomenal que los anteriores.\"},{\"heading\":false,\"text\":\"--¡Tú! ¡Y de tamaño natural! --repetía Juanita sin cansarse de mirar a su Pendencia y midiéndole la caja del cuerpo con los brazos.\"},{\"heading\":false,\"text\":\"--¡Pues qué! ¿Crees tú que a mí ze me encoge el corazón ante el peligro?\"},{\"heading\":false,\"text\":\"Clara estuvo a punto de desmayarse de alegría; pero como las mujeres tienen el talento de la oportunidad, no perdió el sentido más que lo estrictamente necesario para tener que apoyarse en el hombro de Luis. Benjamín discurría sobre las causas del fenómeno, y don Sindulfo echaba espumarajos por la boca vociferando:\"},{\"heading\":false,\"text\":\"--¿Cómo estáis aquí?\"},{\"heading\":false,\"text\":\"--¡Toma! ¿Puz no viajamos juntoz?\"},{\"heading\":false,\"text\":\"--Yo os lo explicaré --repuso la emperatriz--. Al dirigirme a palacio los vi rondando la poterna; conocí por sus trajes que eran de los vuestros; y ellos, comprendiendo por mis señas mis intenciones, se acomodaron a ejecutar mis planes que eran velar por vosotros.\"},{\"heading\":false,\"text\":\"--Pero no es eso --gritaba el tutor cada vez más exaltado--. ¿En qué consiste que después de evaporarse en el camino reaparecen en China en toda su integridad?\"},{\"heading\":false,\"text\":\"--No es este el momento de las explicaciones --adujo Benjamín, temiendo alguna nueva complicación--. ¿Traéis las pruebas de la inmortalidad?\"},{\"heading\":false,\"text\":\"--Sí --repuso Sun-ché.\"},{\"heading\":false,\"text\":\"--Pues lo que urge es ponernos en salvo.\"},{\"heading\":false,\"text\":\"--¡Al Anacronópete! --propusieron todos.\"},{\"heading\":false,\"text\":\"--¡Si no funciona!\"},{\"heading\":false,\"text\":\"--¿Quién sabe? Allá veremos --objetó Benjamín, seguro de lo que anticipaba--; lo principal es parapetarnos en sitio seguro.\"},{\"heading\":false,\"text\":\"Y la emperatriz, cobijándose en don Sindulfo:\"},{\"heading\":false,\"text\":\"--Partamos --añadió--, que ya libres del monstruo, la que fue dueña de un imperio podrá abandonarse a la irresistible atracción que por ti siente y tendrá orgullo en llamarse tu esclava.\"},{\"heading\":false,\"text\":\"No le faltaba al sabio más que aquella declaración a quemarropa para acabar de perder el juicio; y hubiera cometido alguna inconveniencia en el estado en que se hallaba su razón, si el chocar de las armas no hubiera acusado la proximidad del enemigo y la precisión de huir. Colocaron pues a las damas entre las filas del sexo fuerte, y unos abandonados a su legítimo gozo y alguno a su desesperación, tomaron todos el camino del Anacronópete al que llegaron sin contratiempo.\"},{\"heading\":false,\"text\":\"Para terminar los anales de la contienda civil entre los _Tao-sse_ y los letrados, diremos, que vueltas de su estupor las huestes de Hien-ti, concluyeron por vencer a los parciales de Sun-ché desanimados ante la desaparición de su soberana y sin un jefe que los condujera al combate. Tsao-pi, viendo huérfano el trono, subió sus gradas, se ciñó el sombrerete y fundó la séptima dinastía de los emperadores, conocida en la historia con el nombre de los _Ouei_.\"}]},{\"title\":\"El anacronópete — capítulo xvi\",\"blocks\":[{\"heading\":false,\"text\":\"En que todo se explica complicándose todo\"},{\"heading\":false,\"text\":\"La situación a bordo había cambiado completamente. Las muchachas bailaban en un pie ante un aumento de tripulación tan inesperado como de su gusto, y la misma emperatriz no ocultaba a nadie el contento que le producía su viudez. Los mílites arrullados por Cupido perdían la memoria de sus pasadas desventuras; y Benjamín, próximo a tocar su _desideratum_, bendecía las circunstancias que le colocaban en el caso de dar cima a su obra sin entorpecimiento alguno, puesto que de hecho él se hallaba convertido en jefe de la expedición.\"},{\"heading\":false,\"text\":\"Y efectivamente; desde el punto en que entraron en el Anacronópete, don Sindulfo, que no había desplegado sus labios por el camino, se dejó caer en una silla víctima de un abatimiento alarmante. Tan pronto su mirada se clavaba en el suelo en la actitud del hombre que medita, como sus ojos desencajados erraban de uno a otro de sus compañeros, brillando con el siniestro resplandor de la amenaza. Cien ideas confusas se disputaban el paso por las inyectadas venas de su frente, en cuyas pulsaciones, alternativamente regulares y febriles, podía leerse ya el planteamiento de un teorema en demanda de una explicación científica para tantos fenómenos incomprensibles, ya los arrebatos de la ira caminando ciega de los celos a la venganza.\"},{\"heading\":false,\"text\":\"--Me parece que a don _Pichichi_ se le ha aflojado algún tornillo del Capitolio; --dijo Pendencia observando como los demás el estado del tutor.\"},{\"heading\":false,\"text\":\"--Y a usted también se le desmorona el cimborio --adujo Juanita encarándose con Benjamín--. Figúrense ustedes que hace poco, cuando los chinos querían mecharnos, estos dos señores han creído reconocer a la difunta de don Sindulfo que _requiescat_. ¿Habráse visto despropósito mayor?\"},{\"heading\":false,\"text\":\"--En cuanto a eso, hablaremos más tarde --contestó el políglota un sí es no es picado. No por desconocer las causas hemos de negar los efectos de las cosas.\"},{\"heading\":false,\"text\":\"--¿Cómo?\"},{\"heading\":false,\"text\":\"--En este viaje inverosímil lo lógico es tal vez lo absurdo. Demos tiempo al tiempo.\"},{\"heading\":false,\"text\":\"En aquel momento oyeron un penetrante grito y vieron a Sun-ché que, asida por el brazo, hacía esfuerzos para desprenderse de las férreas y convulsas manos de don Sindulfo. La infeliz, llevada de su instintivo amor hacia el sabio, había querido prodigarle una caricia, y el pobre loco la había recibido como algunos cuerdos reciben a la mujer propia, por la sola razón de serlo. Pero la víctima, cediendo a una convulsión nerviosa, agitaba los remos que le quedaban libres, con tan mala suerte para el presunto marido, que a más de algunos puntapiés en las espinillas se llevó desde la boca a la nuca una colección de redobles a puño cerrado, en que las narices, como punto más saliente, no fueron las menos favorecidas.\"},{\"heading\":false,\"text\":\"--¡Es ella! ¡Es ella! --exclamó don Sindulfo soltándola por fin, y corriendo despavorido al lado de su familia--. ¡Es Mamerta! ¿Recuerda usted que tampoco podíamos contrariarla sin que sufriésemos las consecuencias de sus crispaciones, con lo que conseguía hacer siempre su voluntad?\"},{\"heading\":false,\"text\":\"--Calma, amigo mío, calma --repetía Benjamín no menos absorto que el tutor ante la analogía de la soberana con la hija del banquero zamorano. Mientras no nos expliquemos racional o científicamente cómo una mujer española y del estado llano, ahogada en el siglo XIX, puede ser una emperatriz china del siglo tercero, estamos en el caso de suponerlo todo pura coincidencia.\"},{\"heading\":false,\"text\":\"--Pero, hombre de Dios --arguyó Juana--: si eso es achaque de cada hija de vecino; la gramática parda del sexo. Y yo misma, si no hubiera usted sido mi señor, del primer ataque que me tomo cuando nos sacó usted de París, le deshago a usted el depósito de la sabiduría.\"},{\"heading\":false,\"text\":\"--¡Y los cazcoz zon para ello! --repuso Pendencia haciendo notar los puños que Juanita crispaba.\"},{\"heading\":false,\"text\":\"--¿No tendría la difunta alguna especialidad más marcada a cuyo cotejo someter a la emperatriz por vía de prueba? --preguntó el capitán de húsares participando de la extrañeza general.\"},{\"heading\":false,\"text\":\"--Piénselo usted bien --insistió Clara.\"},{\"heading\":false,\"text\":\"Don Sindulfo recogió un momento sus ideas, y después de reiterados esfuerzos:\"},{\"heading\":false,\"text\":\"--Sí --exclamó dándose un golpe en la frente y sacando del reverso de la solapa una aguja que enhebrada tenía siempre a prevención para ensartar papeletas del catálogo.\"},{\"heading\":false,\"text\":\"Y antes de que los circunstantes pudieran inquirir su propósito, dirigióse a donde Sun-ché se hallaba descansando del accidente.\"},{\"heading\":false,\"text\":\"--Cósame usted esto --dijo arrancándose bruscamente un botón de la levita, y presentándoselo a la emperatriz, a quien miraba de hito en hito para no perder detalle del experimento.\"},{\"heading\":false,\"text\":\"La buena señora que, no entendiendo nada de lo que ocurría en torno suyo, comenzaba a aburrirse, echó mano al botón considerándolo un objeto de curiosidad; pero al ver el arma de costura dio un penetrante grito, y doblando la cabeza sobre el pecho quedó desmayada en la silla; circunstancia que, como dijimos al comienzo de este relato, era peculiar de la organización de la muda y que Benjamín, lívido de estupor, refirió a los atónitos viajeros.\"},{\"heading\":false,\"text\":\"--No hay duda, no --gritaba don Sindulfo retorciéndose como una culebra--; el mismo horror a las agujas enhebradas que no la permitió zurcirme nunca un par de calcetines.\"},{\"heading\":false,\"text\":\"--Se conoce que la banquera era catedrática en holgazanería --arguyó en voz baja la doméstica; mientras el atribulado don Sindulfo, pronunciando frases incoherentes, golpeando cuanto en el camino encontraba, y echando espuma por la boca y fuego por los ojos, se dirigió frenético a su gabinete en busca de una solución para aquel problema.\"},{\"heading\":false,\"text\":\"Todos se precipitaron tras él; pero la puerta, cerrada con estrépito, les cortó el paso. Entonces se resolvieron a prestar algún auxilio a la emperatriz; precaución que fue inútil, porque la augusta dama, como si se lo hubiesen soplado al oído, en cuanto la aguja desapareció, se quedó más buena que antes.\"},{\"heading\":false,\"text\":\"--Supongo --dijo Luis al políglota-- que en el estado en que está mi tío no le confiará usted el rumbo de la expedición.\"},{\"heading\":false,\"text\":\"--¡Dios me libre! Podría hacernos víctimas de su enojo --adujo Clara.\"},{\"heading\":false,\"text\":\"--Con ece arriero eztamoz ceguroz de volcar.\"},{\"heading\":false,\"text\":\"--Descuiden ustedes --objetó Benjamín--. Me interesa demasiado el asunto para confiar la derrota a un demente.\"},{\"heading\":false,\"text\":\"--¡Cómo! ¿Ha perdido el juicio? --preguntaron los demás.\"},{\"heading\":false,\"text\":\"--Mucho me lo temo. Con todo, no desespero de salvarle. Confíen ustedes en mí.\"},{\"heading\":false,\"text\":\"E invitando a Sun-ché a acercarse al aparato de la inalterabilidad, en tanto que los viajeros hacían comentarios sobre la situación, la descargó unas corrientes que debieron contrariarla también a juzgar por las sacudidas nerviosas que llovieron sobre el occipucio del anticuario. Acto continuo separó el aislador que entorpecía la acción del volante; y elevando el vehículo a la zona atmosférica en que debía tener efecto la locomoción, hizo parar en seco el Anacronópete exclamando:\"},{\"heading\":false,\"text\":\"--Ahora sepamos a dónde nos dirigimos.\"},{\"heading\":false,\"text\":\"--¡A París! --fue el grito unánime.\"},{\"heading\":false,\"text\":\"--Juzto; a Pariz para encerrar al zabio en un _manucordio_ y hacer que a nozotroz noz eche el cura el garabato _nuncial_.\"},{\"heading\":false,\"text\":\"--Antes --objetó Benjamín-- veamos si el principal objeto de nuestra expedición se ha logrado satisfactoriamente.\"},{\"heading\":false,\"text\":\"--¿Cuál?\"},{\"heading\":false,\"text\":\"--La posesión del secreto de la inmortalidad que nos ha ofrecido la emperatriz.\"},{\"heading\":false,\"text\":\"Instada esta a explicarse, sacó un pergamino en el que había trazado por una mano experta el plano de una ciudad.\"},{\"heading\":false,\"text\":\"--¿Qué es esto? --preguntó el ansioso arqueólogo temiendo un desengaño.\"},{\"heading\":false,\"text\":\"--Algún pellejo de zambomba de la adoración de los pastores en el Portal de Belén --dijo Juanita.\"},{\"heading\":false,\"text\":\"--Pero, ¡la fórmula!... --volvió a insistir impaciente Benjamín apremiando a Sun-ché.\"},{\"heading\":false,\"text\":\"--El occidental no tuvo ocasión de iniciarme en ese misterio, sorprendido como fue por mi tirano esposo; pero al encarecerme la eficacia de su principio, me manifestó que las pruebas de la inmortalidad habían sido enterradas por uno de sus antecesores en Pompeya, debajo de la estatua de un emperador, marcada en el pergamino con un círculo rojo.\"},{\"heading\":false,\"text\":\"--Sí, aquí está --interpuso Benjamín señalando en el papiro una mancha circular bajo la que en correcto latín se leía: «Efigie pétrea de Nerón.»\"},{\"heading\":false,\"text\":\"--Parece ser --prosiguió la emperatriz-- que el conocimiento de esta circunstancia pasó tradicionalmente por varias generaciones sin que nadie se atreviera a evidenciarlo; hasta que el intrépido mártir cuya muerte sentimos, se resolvió a sacarlo a luz; pero acusado de profanación por habérsele sorprendido en el instante en que se disponía a zapar la estatua, consiguió a duras penas evadirse de la prisión y llegar a mis dominios donde tuve la fortuna de conocerle. Una expedición secreta a su patria estaba ya decidida para hacerse con el misterioso talismán, cuando el fin que todos sabéis ha venido a destruir nuestros proyectos.\"},{\"heading\":false,\"text\":\"--Aún vive quien los secundará --dijo Benjamín con los ojos centelleantes de entusiasmo. Y dirigiéndose a los suyos--: A Pompeya --añadió.\"},{\"heading\":false,\"text\":\"Algunas protestas levantó aquel grito; pero la felicidad es tan complaciente y era tan natural el deseo de los viajeros de hacer una excursión por el pasado, libres ya de los riesgos que hasta entonces habían corrido, que aplacados los murmullos, Benjamín orientó el vehículo y poniéndolo en movimiento, hizo rumbo hacia la hija tan feliz como mimada del risueño golfo de _Neápolis_.\"},{\"heading\":false,\"text\":\"Las siete horas que habían de tardar en recorrer los ciento cuarenta y un años que separaban a los anacronóbatas del principio del tercer siglo al último tercio del primero, no eran intervalo para que se aburriesen unas personas que tanto tenían que contarse y tantas curiosidades que admirar. Capitaneados pues por Juanita, los neófitos pusiéronse a girar una visita de inspección al Anacronópete en tanto que Benjamín, normalizada relativamente la situación, buscaba la causa de aquellos efectos fenomenales.\"},{\"heading\":false,\"text\":\"Lo primero que trató de explicarse es la aparición de los mílites evaporados. Retrogradó por consiguiente en sus pensamientos, y a fuerza de hombre lógico, se dijo que si la consecuencia era anómala, el origen tenía que ser necesariamente irregular. Ahora bien: ¿qué circunstancia extraordinaria había ocurrido durante la navegación? Al momento le vino a las mientes el impulso retroactivo que él mismo imprimió al Anacronópete poco después de la catástrofe de los riffeños, cuando creyendo caminar hacia el pasado estuvo haciendo rumbo al presente hasta llegar a Versalles en la víspera del día de partida. La luz estaba hecha y las tinieblas disipadas: la deducción no tenía vuelta de hoja.\"},{\"heading\":false,\"text\":\"Y en efecto, si mis lectores recuerdan el incidente del ochavo moruno (que, perdido por un kabila, se aniquiló en cuanto traspuso el instante en que fue acuñado, pero que volvió a cobrar forma apenas el Anacronópete, marchando hacia el presente, rebasó el minuto de la acuñación), comprenderán que el fenómeno de la resurrección de los hijos de Marte obedecía a la misma causa. Evaporados al retrogradar, habían perdido su forma humana, obra del tiempo; pero su espíritu inmortal no había abandonado el Anacronópete, como el grano de trigo oculto en la gleba no deja de existir en el terruño aunque invisible hasta la germinación. Así es que, cuando en su marcha hacia el hoy, sonó en el vehículo la hora del nacimiento de los soldados, la envoltura de carne acudió al llamamiento cronológico; y el germen, rompiendo la tierra, dejó ver el tallo para ser robusta caña y volver a tomar las proporciones de su espiga.\"},{\"heading\":false,\"text\":\"El cómo se sustrajeron a una segunda disolución cuando, apercibido de la falta, Benjamín reconquistó el verdadero rumbo, tiene una explicación muy sencilla. Los soldados, que alternativamente se habían visto reducirse y desarrollarse, al recobrar sus proporciones quisieron no volverlas a perder y escalaron el laboratorio decididos a implorar el amparo de la ciencia; pero al llegar al pasillo, oyeron las explicaciones que sobre la inalterabilidad estaba dando Benjamín a las parisienses; y como el capitán de húsares tenía sus rudimentos de física, propinóse con sus compañeros unas corrientes del fluido y opinó muy sabiamente que permaneciendo ocultos servirían mejor la causa de las reclusas doncellas que exponiéndose, si se exhibían, a ignotas contingencias provocadas por los celos del tutor. Y así es cómo ocultos en sus gazaperas llegaron a China oportunamente para evitar una catástrofe.\"},{\"heading\":false,\"text\":\"Apuntó Benjamín estas observaciones en su memorandum particular; pero abstúvose muy mucho de divulgarlas, prefiriendo dejar a todos en la persuasión de lo maravilloso a confesarse reo de ineptitud.\"},{\"heading\":false,\"text\":\"El segundo problema era más difícil de resolver. ¿Cómo a través de dieciséis siglos una emperatriz china se presentaba a sus ojos con tan señaladas diferencias físicas, pero con analogías de organización tan evidentes con aquella Mamerta ahogada en las playas de Biarritz? Ensimismado estaba el políglota en tan metafísicos conceptos y ya el trayecto casi tocaba a su fin sin que hubiese podido coordinar dos ideas afines, cuando unos gritos desaforados que partían del gabinete de don Sindulfo le sacaron de su abstracción.\"},{\"heading\":false,\"text\":\"--¡El loco! ¡El loco! --exclamaron los excursionistas, que al oír las voces acudieron precipitadamente en busca de Benjamín.\"},{\"heading\":false,\"text\":\"--Sí. ¿Qué podrá ser?\"},{\"heading\":false,\"text\":\"--Algún calambre en la mollera --dijo el andaluz.\"},{\"heading\":false,\"text\":\"E instintivamente todos se dirigieron al cuarto; pero apenas iniciado el movimiento, la puerta se abrió; y don Sindulfo con el traje en desorden, las manos crispadas y la púrpura de la ira en el semblante, hizo irrupción en el laboratorio vociferando:\"},{\"heading\":false,\"text\":\"--¡Maldición! --Ya dí con la clave del enigma. Ya comprendo cómo Sun-ché puede ser mi difunta Mamerta.\"},{\"heading\":false,\"text\":\"--¿Cómo?\"},{\"heading\":false,\"text\":\"--¡Por la metempsicosis!...\"},{\"heading\":false,\"text\":\"Los profanos no entendían ni una palabra; pero el políglota se quedó pensativo luchando entre la fe y la duda.\"},{\"heading\":false,\"text\":\"--Diga uzté; ¿y ezo ce come con cuchara o con tenedor?\"},{\"heading\":false,\"text\":\"--¡La metempsicosis! --prosiguió el sabio sin atender a observaciones--. La transmigración de las almas, por la cual el espíritu de los que mueren pasa al cuerpo de otro animal racional o inmundo según sus merecimientos en vida.\"},{\"heading\":false,\"text\":\"--¡Ay! --arguyó Juanita--. Pues lo que es ustedes dos, por lo chinches que han sido con nosotros, van a parar al Rastro.\"},{\"heading\":false,\"text\":\"--¿Es decir --interrogó el sobrino, a quien el asunto empezaba a interesar-- que la emperatriz por una serie de transmigraciones llegó en su última evolución a ser la esposa de usted?\"},{\"heading\":false,\"text\":\"--Justamente. Y al retrogradar en el tiempo se nos presenta bajo la envoltura real que tenía en esta época, como en el alto que hicimos en África pudimos --a haber tropezado con ella-- hallarla convertida en vegetal o en acémila entre los bagajes.\"},{\"heading\":false,\"text\":\"--Permítame usted --objetó Benjamín--. Nosotros somos cristianos y nuestro dogma rechaza esas teorías.\"},{\"heading\":false,\"text\":\"--¿Y qué importa? --replicaba el demente exaltándose por grados.\"},{\"heading\":false,\"text\":\"--Nosotros somos católicos; pero ella es china, sectaria de Buda; luego bien puede transmigrar según prescribe su religión. Porque ¿quién le dice a usted que la Providencia no impone sus castigos con arreglo a las creencias que profesa cada uno?\"},{\"heading\":false,\"text\":\"Todos, menos Sun-ché, que estaba como en el limbo sin saber lo que pasaba, comprendieron que el pobre doctor tenía el juicio extraviado. Solo Benjamín, a fuer de hombre de ciencia, entusiasmado con el descubrimiento de aquella especie de metafísica experimental, concluyó por dar al loco la razón; que era como perder la suya.\"},{\"heading\":false,\"text\":\"--Es indudable. ¡Eureka! --gritó como Arquímedes abrazando a su amigo.\"},{\"heading\":false,\"text\":\"--Pero si aquella no hablaba --insistió Juanita-- y esta echa cada discurso como un diputado.\"},{\"heading\":false,\"text\":\"--Ezo no; porque ci zu marido no entiende lo que dice, para él ez lo mismo que ci fuese muda.\"},{\"heading\":false,\"text\":\"--Además --dijo Luis sonriendo-- que si entonces perdió el uso de la palabra, tal vez fue un castigo del dios Buda por el abuso que de ella hizo acaso en una existencia anterior.\"},{\"heading\":false,\"text\":\"--De modo --argumentó Clara aprovechando aquella ocasión de romper sus cadenas-- que ya cesará usted de perseguirme; porque ligado como está usted a esta señora por los vínculos del matrimonio, ¿no pretenderá usted casarse conmigo cuando nuestra religión proscribe la bigamia?\"},{\"heading\":false,\"text\":\"El doctor, al sentirse hostigado en lo que precisamente constituía su preocupación desde que sorprendido hubo la afinidad de la emperatriz con Mamerta, estalló al ser argüido de aquel modo por Clara, y de la monomanía pacífica pasó al vértigo furioso.\"},{\"heading\":false,\"text\":\"--¿Desistir yo de un cariño al que he consagrado todas las fuerzas de mi vida, mi actividad, mi inteligencia? --decía apretando los puños y haciendo rodar los ojos en sus órbitas--. ¡Oh, nunca!\"},{\"heading\":false,\"text\":\"--¡Que muerde! --interrumpió Pendencia separándose por precaución, como los demás, del delirante sabio que persiguiéndolos añadía:\"},{\"heading\":false,\"text\":\"--No. Si el destino me es adverso, lucharé contra el destino; pero serás mi mujer aunque para ello tenga que ir hasta el crimen.\"},{\"heading\":false,\"text\":\"--Es inútil --repuso la atrevida maritornes--. Si aunque nos degüelle usted, aquí los muertos resucitan.\"},{\"heading\":false,\"text\":\"--Pues bien, pereceremos todos. Es preciso acabar con esta situación.\"},{\"heading\":false,\"text\":\"--¿Cómo?\"},{\"heading\":false,\"text\":\"--En la cala hay diez barriles de pólvora; les aplicaré una mecha, y ni rastro quedará del Anacronópete.\"},{\"heading\":false,\"text\":\"--No cea uzté bárbaro.\"},{\"heading\":false,\"text\":\"--Tranquilícense ustedes --exclamó Benjamín recordando el incidente que en diversas ocasiones le obligó a descender a tierra en busca de vitualla en su trayecto de África a China--. Las provisiones, sometidas a la inalterabilidad, resultan ineficaces para su uso, según prácticamente he observado.\"},{\"heading\":false,\"text\":\"--¡Ignorante! --interrumpió el loco recobrando por un momento su lucidez.\"},{\"heading\":false,\"text\":\"--¿Qué?\"},{\"heading\":false,\"text\":\"--Arrojando nuevo fluido sobre los cuerpos para que las corrientes anteriores se pongan en contacto con las nuevas y formen una sola, no hay más que dar vueltas a la inversa al disco del aparato transmisor para recogerlas todas y, neutralizadas, devolver a las provisiones sus propiedades específicas.\"},{\"heading\":false,\"text\":\"--Bueno es saberlo; pero estamos perdidos.\"},{\"heading\":false,\"text\":\"--Hay que inundar la Zanta Bárbara.\"},{\"heading\":false,\"text\":\"--Corramos.\"},{\"heading\":false,\"text\":\"--No, no temáis --interpuso el tutor pasando, para detenerlos, de la amenaza a la súplica--. Una voladura acabaría con todos, y yo no quiero que ella muera. Respetaré sus días. Pero vosotros --añadió dirigiéndose a los militares y a la emperatriz, y volviendo a la exaltación con más fuerza que nunca-- preparaos a sufrir mi venganza. Sois el obstáculo de mi dicha y os exterminaré a fin de realizar mis designios, aunque para llegar con Clara al altar tenga que cruzar ríos de sangre. ¡Ah! ¡Ya sé cómo!...\"},{\"heading\":false,\"text\":\"Y así diciendo traspuso la puerta y se dirigió frenético a la cala. Sus compañeros, recelando no sin razón algún inminente peligro, corrieron tras él con intención de detenerle.\"},{\"heading\":false,\"text\":\"Luis, capitaneando a los suyos, fue el primero en llegar a la bodega; pero el doctor, que acariciando su plan se había ocultado capciosamente, apenas vio a los hijos de Marte y a su sobrino en medio de la estancia, hizo girar el portón de la limpieza, y los diecisiete héroes desaparecieron en el espacio entre los gritos de las enamoradas doncellas y de Benjamín, que al ir en su seguimiento solo alcanzaron a ser testigos de tan horrorosa catástrofe.\"},{\"heading\":false,\"text\":\"--¡Salvémonos! --fue la voz general, sin que nadie pensara en desmayarse ante la gravedad de las circunstancias. Y todos se abalanzaron a la escalera; pero Benjamín, apercibiéndose de que don Sindulfo trataba de cortarles el paso subiendo por otra escala espiral que había en el fondo, aconsejó a las tres cadavéricas mujeres que le esperasen allí; y trepando como un gamo por los salientes de la maquinaria, se introdujo por la claraboya del techo en el laboratorio, paró en seco el Anacronópete, interpuso previsoramente el aislador, descendió por el mismo conducto y, abriendo la puerta, abandonó con sus compañeras de infortunio aquel lugar de muerte antes de que el loco se apercibiera de su fuga.\"},{\"heading\":false,\"text\":\"La suerte les favorecía en medio de tantas contrariedades. Habían arribado a Pompeya.\"}]},{\"title\":\"El anacronópete — capítulo xvii\",\"blocks\":[{\"heading\":false,\"text\":\"Panem et circenses\"},{\"heading\":false,\"text\":\"Pocos meses hacía que, sucediendo a su progenitor, imperaba Tito en Roma. Este príncipe generoso, que llamaba día perdido a aquel en que no había dispensado algún bien, empezaba a borrar con su clemencia el sangriento recuerdo de Nerón y la sórdida avaricia de Vespasiano su padre.\"},{\"heading\":false,\"text\":\"El triunfador de Jerusalén, _las delicias del género humano_ como le apellidaban, había proscrito las persecuciones contra los sectarios del Nazareno, iniciadas por Tiberio y sobrepujadas por el hijo de Agripina. Ello no obstante, los suplicios no cesaron completamente.\"},{\"heading\":false,\"text\":\"Las provincias, gobernadas por prefectos arbitrarios revestidos de una autoridad suprema y escudados en una irresponsabilidad absoluta, se libraban a cruentos espectáculos, ora para satisfacer los naturales instintos de la plebe, ya para secundar los ocultos planes de los pretores. En este caso se hallaba Pompeya.\"},{\"heading\":false,\"text\":\"Residencia de estío de las familias patricias de la Campania y del Lacio, sus habitantes más que de luchas políticas se ocupaban del embellecimiento de su ciudad con el fin de atraer a la población flotante que tan buenos rendimientos les daba. Y tal era su fanatismo para la conservación del ornato público que, cuando a la caída de Nerón la Italia entera destruyó las estatuas de este monstruo, ellos respetaron, sin deificarlas, todas las que erigidas en sus calles encerraban alguna notoriedad artística. Pero así que el caliginoso aliento del verano empujaba hacia aquella vertiente del Vesubio a los levantiscos ciudadanos de Neápolis y Salerno, las pasiones se encendían y Pompeya era durante cuatro meses émula en discordias civiles de Roma su metrópoli.\"},{\"heading\":false,\"text\":\"Tenían los pompeyanos a la sazón por _Præfectus urbis_ un senador vendido a la causa de Domiciano, aquel segundo Calígula que dos años después debía precipitar la muerte de su hermano Tito, colocándole en la fila de los dioses mientras le denigraba entre los simples mortales. Fingiendo pues someterse a los designios del emperador, el prefecto no desperdiciaba coyuntura de atizar el fuego de la indisciplina para favorecer, bajo mano, los ambiciosos planes del Caín su protector.\"},{\"heading\":false,\"text\":\"Habían dado comienzo las _vindemiales_, ferias de las vendimias que desde el tres de septiembre al tres de octubre se celebraban en toda la Italia agrícola. La época de los grandes juegos se aproximaba y con ella el descontento público; no solo porque su terminación era la señal de desfile para los veraneantes impelidos mal de su grado a consagrarse a sus tareas ordinarias, sino porque desde el advenimiento de Tito las circenses no eran ya las lúgubres hecatombes en que el pueblo romano bebía su bélica inspiración. Reducidos a la carrera, al salto, al disco y al pugilato, echaban de menos los _gladiadores_, los _bestiarios_, los _secutores_ y los _dimaqueres_ con su polvo, sus rugidos, su sangre y sus cadáveres.\"},{\"heading\":false,\"text\":\"Pero a las ya expuestas uníase aún otra circunstancia. Habiendo consumido un incendio en Roma el Capitolio, el Panteón, la Biblioteca de Augusto y el Teatro de Pompeyo, amén de otros monumentos menos importantes, Tito prometió que todo sería reedificado a sus expensas; y, rehusando los donativos que le ofrecían así las ciudades del imperio como los príncipes sus aliados, vendió hasta los muebles de su palacio para cumplir su palabra. El entusiasmo público desbordó en todas partes organizándose festejos con que solemnizar la largueza del emperador. Pero los secuaces de Domiciano, valiéndose de ocasión tan propicia para tomar en ridículo la clemencia del soberano, indujeron a la plebe a reclamar con tal insistencia la restitución de su espectáculo predilecto, que Tito debió ceder ante el clamor general y, al inaugurar su célebre anfiteatro, otorgó gladiadores, _naumaquias_ o combates navales y hasta cinco mil fieras. Los pompeyanos no fueron los que contribuyeron en menor parte a esta dolorosa reconquista instigados por el _Præfectus urbis_.\"},{\"heading\":false,\"text\":\"Era el anochecer del día 7 de septiembre del año 79 de Jesucristo. El _ceryx_ encargado de la conservación del orden, recorría presuroso todos los puestos recomendando a sus _vigiles_ que atendieran a la seguridad pública, sin oponerse no obstante al torrente popular que, desbordando de las termas, de la Basílica, de los templos de Júpiter y Hércules, de las tiendas de la avenida de la Abundancia y de los tugurios de la calle de la Fortuna, se dirigía en tropel a la morada del Pretor, llevando teas encendidas y gritando como en la Roma cesárea:\"},{\"heading\":false,\"text\":\"--¡Panem et circenses!...\"},{\"heading\":false,\"text\":\"El prefecto, queriendo cubrir con cierto velo de legalidad su propia obra, presentóse en la puerta de palacio, rodeado de la guardia pretoriana; y, precedido de seis lictores que vestidos con el _sagum_ descansaban los _fasces_ sobre el hombro izquierdo mientras con la _virga_ en la opuesta mano separaban los grupos:\"},{\"heading\":false,\"text\":\"--Al foro, dijo --y tomó el camino de las asambleas generales seguido de la multitud que tras él continuaba vociferando:\"},{\"heading\":false,\"text\":\"--¡Panem et circenses!...\"},{\"heading\":false,\"text\":\"En aquel santuario de la opinión pública, una representación verbal le fue elevada en nombre de todos los ciudadanos de Pompeya.\"},{\"heading\":false,\"text\":\"--¿Sabéis --arguyó-- que las leyes lo prohíben?\"},{\"heading\":false,\"text\":\"--Entiende tú --repuso el tribuno que llevaba la voz-- que si se enerva el pueblo en la molicie, el día de la lucha no tendrá fuerzas para abrir las puertas del templo de Jano.\"},{\"heading\":false,\"text\":\"--¡No más _quadriga_!...\"},{\"heading\":false,\"text\":\"--No más disco.\"},{\"heading\":false,\"text\":\"--¡Luchadores!... --fue el grito unánime.\"},{\"heading\":false,\"text\":\"Y como la exasperación amenazara convertirse en motín, el prefecto les concedió los _andabates_ que, peleando con una venda en los ojos o cubiertos con una armadura, ofrecían menos riesgo.\"},{\"heading\":false,\"text\":\"--No: ¡gladiadores! --repitió la turba.\"},{\"heading\":false,\"text\":\"Y el demandado fingiendo doblegarse a las circunstancias, asintió a los clamores de la plebe; pero como la debilidad de parte de la fuerza es la señal del abuso en el oprimido:\"},{\"heading\":false,\"text\":\"--¡Bestiarios! --prorrumpieron unos pocos; lo que no tardó en hacerse el eco general. Y de concesión en concesión, los pompeyanos consiguieron que les restituyesen no solo los _laquearios_ (que por un lazo escurridizo tirado con destreza procuraban detener y cazar a los adversarios) y los _retiarios_ que, con una mano armada de un tridente y llevando en la otra una red, envolvían con ella a su antagonista para darle muerte una vez vencido, sino el repugnante espectáculo de las bestias feroces, desgarrando entre los aplausos de la abyecta muchedumbre las carnes de los prisioneros de guerra, o abriendo con sus dientes el camino de la gloria a los mártires sublimes de la religión cristiana.\"},{\"heading\":false,\"text\":\"La impaciencia popular señaló el día siguiente para renovar el derramamiento de sangre en el anfiteatro. La premura de la exigencia no permitiendo que se restablecieran los abolidos gladiadores _fiscales_, que eran los que el Fisco suministraba a sus expensas, ni los _postulatitii_, o sea los que por más hábiles el pueblo reclama preferentemente, hubo de recurrirse a los _privados_, sostenidos por empresas particulares que los alquilaban mediante una retribución pecuniaria.\"},{\"heading\":false,\"text\":\"En cuanto a los _bestiarios_, a falta de prisioneros de guerra y de delincuentes condenados a este género de lucha, se determinó substituirlos con esclavos o con gente ya acusada de impiedad, ya sospechosa de seguir la doctrina del que llamaban impostor de Galilea.\"},{\"heading\":false,\"text\":\"Restituido el prefecto en triunfo al pretorio y agotados los vítores al emperador, la ebria muchedumbre se retiró a sus hogares a esperar el mañana, quedando sumida Pompeya en esa calma precursora de toda tempestad horrible.\"},{\"heading\":false,\"text\":\"Este fue el instante en que los fugitivos del Anacronópete, deslizándose como sombras sobre el empedrado de lava de sus rectas y elegantes avenidas, penetraron en la ciudad.\"},{\"heading\":false,\"text\":\"Benjamín, que en medio de las mayores contrariedades perseguía su fin científico con la terquedad de un sabio aragonés, se había provisto en su fuga de un zapapico y caminaba consultando al resplandor de la luna creciente el plano del teatro de sus operaciones. Sun-ché, que además de haber asistido a la trágica desaparición de los militares había sido impuesta por el políglota en la locura del doctor, se apoyaba en el brazo izquierdo de su intérprete rendida de cansancio y entregada a tristes pensamientos. Pendida del derecho arrastrábase mejor que andaba la más digna de compasión de todos: la desventurada pupila que por breves horas había tocado el séptimo cielo de sus ilusiones para ser precipitada desde más alto en los últimos abismos de la desesperación.\"},{\"heading\":false,\"text\":\"Juana era la única que, no obstante la gravedad de las circunstancias, no se abandonaba al desaliento.\"},{\"heading\":false,\"text\":\"--Verá usted --decía-- cómo a lo mejor nos los vemos aparecer por ahí vestidos como judíos del monumento.\"},{\"heading\":false,\"text\":\"--No, esta vez los hemos perdido para siempre.\"},{\"heading\":false,\"text\":\"--¡Quiá! Si ellos son como el ave _Félix_ que según cuentan renace después de hecha _cecina_.\"},{\"heading\":false,\"text\":\"--Por fin llegamos --exclamó Benjamín deteniéndose en un _quadrivium_ o desembocadura de cuatro avenidas, en cuyo centro se alzaba la estatua de Nerón dando frente a la puerta de Herculano situada en la extremidad de la calle Domiciana.\"},{\"heading\":false,\"text\":\"Invitados los viajeros por el impaciente sabio a tomar algún reposo mientras él se libraba a sus excavaciones, Clara y Sun-ché se recostaron en los poyos de una fuente que junto a ellas corría con manso murmullo; y, entregadas a sus reflexiones, quedáronse pronto, si no dormidas, aletargadas.\"},{\"heading\":false,\"text\":\"Juanita, en la esperanza de ver aparecer a Pendencia en la forma de centurión o de _draconarius_, se quedó haciendo compañía al arqueólogo amenizándole la tarea con sus aceradas pullas.\"},{\"heading\":false,\"text\":\"La situación del tesoro estaba tan perfectamente señalada en el plano, que a la media hora escasa de remover la tierra, el zapapico tropezó en un cuerpo resistente.\"},{\"heading\":false,\"text\":\"Benjamín, con el corazón hecho un molino de viento, desenterró una pequeña caja de metal que, sin inscripción alguna, revelaba servir solo de estuche a algún objeto precioso. Abierta por fin en medio de la mayor ansiedad, sacó a luz el políglota unos manojos de cordelillos en los que de distancia en distancia había nudos que a primera vista dejaban comprender por sus combinaciones que no habían sido hechos al azar. El sabio dio un grito de asombro.\"},{\"heading\":false,\"text\":\"--¡Cordeles! --dijo Juanita--. ¿Hombre, y no le dan a usted ganas de ahorcarse?\"},{\"heading\":false,\"text\":\"--Silencio, profana.\"},{\"heading\":false,\"text\":\"--Siquiera propínese usted con ellos una docena de disciplinazos.\"},{\"heading\":false,\"text\":\"--¿Sabes tú lo que es esto?\"},{\"heading\":false,\"text\":\"--A que salimos ahora con que es alguna libra de fideos del tiempo de Salomón...\"},{\"heading\":false,\"text\":\"--Esta es la primera escritura que usaron los hombres sobre la tierra, legada a la humanidad por _Fo hi_, como le llaman los chinos, o según nosotros por Noé a su salida del arca. Este es el prototipo de la palabra escrita revelado al mundo sabio en la academia de inscripciones por el paleógrafo Shuckford.\"},{\"heading\":false,\"text\":\"Y con verdadera hidrofobia científica Benjamín se dispuso a interpretar el enigma. Desgraciadamente una densa nube le eclipsó el tenue rayo de la luna próxima ya a desaparecer en el horizonte occidental; y no bastándole el simple tacto, tuvo que diferir su empresa.\"},{\"heading\":false,\"text\":\"--Pero diga usted: ¿qué tintero empleaban esos _potrotipos_? Pues qué: ¿siempre no se ha escrito del mismo modo?\"},{\"heading\":false,\"text\":\"--Ni por soñación. Que sepamos, hasta ahora son tres las maneras conocidas de trazar la escritura: Por línea perpendicular, por orbicular o redonda y por horizontal; y aun así estas tres grandes ramas se subdividen en muchas variantes.\"},{\"heading\":false,\"text\":\"--¡Jesús! Y yo que no sé poner una carta más que con falsilla, porque, si no, me tuerzo.\"},{\"heading\":false,\"text\":\"Benjamín, a quien la nube se empeñaba en velar el astro de la noche, tanto para distraer su inacción, como cediendo a sus naturales aficiones, tomó así la palabra creyendo asistir a un curso de paleografía:\"},{\"heading\":false,\"text\":\"En la _Mitología_ de Carrasco se lee que los indios de la isla Trapobana, según Diodoro de Sicilia, escriben por líneas perpendiculares rectas. Du-Halde consigna que los chinos y japoneses, aunque usan la escritura perpendicular, la trazan como los hebreos de derecha a izquierda; así es que sus libros comienzan por donde los nuestros tienen su fin. Los septentrionales o Escitas grababan en las rocas sus letras llamadas Runas o Rúnicas en renglones curvos, reuniendo las líneas de alto abajo y vice-versa; pero oblicuamente o en espiral. Los tártaros, según Nienhoff, cuyas consonantes son parecidas a las de los etíopes porque las enlazan con sus vocales, escriben en línea perpendicular de derecha a izquierda; y los mogoles, de alto abajo en opinión de Treveux. Los habitantes de las Islas Filipinas y de Malaca, refiere Giró del Mundo que comienzan, por el contrario, de abajo hacia arriba y de izquierda a derecha. Y los mejicanos, según Acosta, lo verifican por línea perpendicular ocupando de alto abajo toda la página. Conocieron también el uso de unas cuerdecitas teñidas de diversos colores anudadas y entrelazadas de varios modos según la importancia del suceso que debía referirse; esta costumbre era común en todos los salvajes de la América septentrional. Las grandes poblaciones del Perú, dice Baltasar Bonifacio, usaron como las de la América del Norte las mencionadas cuerdecitas, que conservaban en archivos (establecidos y custodiados por personas instruidas) para consulta de todos los sucesos dignos de ser transmitidos a la posteridad.\"},{\"heading\":false,\"text\":\"--Aguarde usted --interrumpió Juanita--. ¿Va a ser muy larga la procesión?\"},{\"heading\":false,\"text\":\"--Si te molesta la dejaremos.\"},{\"heading\":false,\"text\":\"--Nada de eso; a mí no me incomoda, porque lo que no entiendo, por un oído me entra y por otro me sale; pero si usted me lo permite me sentaré. Con que quedamos en los salvajes de la _Habana serpentrional_.\"},{\"heading\":false,\"text\":\"Benjamín la miró con lástima y prosiguió así:\"},{\"heading\":false,\"text\":\"--Entrando en el segundo sistema, aseguran Pausanias y Bimard de la Bastie, que los griegos conocieron la escritura orbicular como se desprende de la inscripción del disco de Ífito que se reputa posterior en 300 años al sitio de Troya. También se sirvieron de ella, según Maffei, los etruscos o antiguos toscanos. Los más remotos pueblos septentrionales enlazaron la escritura de alto abajo y vice-versa; pero también en líneas oblicuas o en espiral. Y no ofreciendo dificultad el que estos caracteres sean los verdaderos runos, resultan legítimas las inscripciones que cita el mismo Pausanias por tener sus líneas mucha semejanza y aun identidad con las de los pueblos del Norte. Las inscripciones griegas del monumento erigido en Olimpia por los cipsélidas, eran difíciles de leerse a causa de sus multiplicadas curvas.\"},{\"heading\":false,\"text\":\"--Lo mismo me pasaba a mí con las cartas de Pendencia; y eso que venían en papel rayado; pero cada renglón parecía un _via-crucis_: aquello sí que a estar en latín, lo cree usted escritura _articular_.\"},{\"heading\":false,\"text\":\"--Tomemos la horizontal --continuó el sabio.\"},{\"heading\":false,\"text\":\"Y Juanita, creyendo que se trataba de una orden que empezaba a lisonjearla, se tendió cuan larga era en el arroyo, como lo pudiera hacer en el más mullido lecho.\"},{\"heading\":false,\"text\":\"--No me duermo, no señor --adujo al comprender por el movimiento de extrañeza de Benjamín que se había equivocado--. Siga usted, que si me aburro ya le diré a usted que se pare.\"},{\"heading\":false,\"text\":\"Benjamín buscó la luna; pero como ella no se dejase ver, reanudó su discurso con desaliento.\"},{\"heading\":false,\"text\":\"--Pues bien: la escritura por línea horizontal abraza varias especies. La _bustrofedona_ de la primera edad, de derecha a izquierda; la del segundo hasta el cuarto período, de izquierda a derecha; y la _aratoria_ que reúne las precedentes yendo y volviendo por líneas paralelas y frente por frente del punto de partida.\"},{\"heading\":false,\"text\":\"--¡Vaya un trajín! ¿Sabe usted que una plana de esas parecerá un ejercicio de bomberos?\"},{\"heading\":false,\"text\":\"--Los orientales siempre han escrito de derecha a izquierda como los etruscos; menos los armenios y los habitantes del Indostán que lo hacen de izquierda a derecha. En los griegos se ha observado que, bien sea por los métodos de Pelasgo, de Cécrope o de Cadmo, participa aunque a lo oriental de las dos especies; porque cuando escriben muchas líneas vuelven de derecha a izquierda. Esta dirección es la que empleaban los hunos.\"},{\"heading\":false,\"text\":\"--¿Y los otros?\"},{\"heading\":false,\"text\":\"--Hablo de los hunos, hoy _zikulos_ de la parte de la Transilvania.\"},{\"heading\":false,\"text\":\"--¡Ah! sí. Adelante, no los conozco.\"},{\"heading\":false,\"text\":\"--Los etíopes o abisinios, los siameses y los tibetanos escriben de izquierda a derecha, y estos últimos casi horizontalmente. Dos inscripciones notables presenta la escritura _bustrofedona_ de la primera edad, admitida también entre los galos y los francos; la una se halló en las ruinas del templo de _Apolo Amyclæus_ en Amycles, villa de la Laconia, hacia el año 1400 antes de J. C.; la segunda, que refiere Muratori, consta en el mármol de Nointel o Baudelot descubierto en 1672 en una iglesia de Atenas, cuyo mármol fija la época por los años 457 antes de la era cristiana. Las pieles de los cuadrúpedos preparadas de diversas maneras, las de los pescados, los intestinos de las serpientes y de otros animales, las telas de lienzo y de seda, las hojas, la corteza y la madera de los árboles, la borra de las plantas y su corazón, el hueso, el marfil, las piedras comunes y preciosas, los metales, el vidrio, la cera, el ladrillo, la greda y el yeso, han sido las materias sobre las que en todos tiempos y en el día se escriben los caracteres.\"},{\"heading\":false,\"text\":\"--Pues en cuestión de caracteres, aunque el mío no es de los peores, como don Sindulfo no nos devuelva los militares, aún ha de ver usted a las criadas escribir con las uñas sobre pellejo de sabio.\"},{\"heading\":false,\"text\":\"--Los mármoles, los bronces y las planchas o láminas de metal han sido de uso común entre los griegos y romanos: el de las pieles data del tiempo de Job. En planchas de madera y tablitas de bambú escribieron los chinos, dice Du-Halde, antes de la invención del papel. Las pirámides, los obeliscos y las columnas de las observaciones astronómicas de los babilonios, que refiere Flavio Josefo, fueron de mármoles, piedras y ladrillo. Las leyes de Solón estaban escritas en madera; las de los romanos en bronce, de las que tres mil se perdieron en el incendio del Capitolio. Los pueblos septentrionales grababan sus inscripciones rúnicas en las piedras y en las rocas. La escritura en plomo sube al tiempo del Diluvio. La hecha en marfil se ha conservado en las tablas llamadas _dípticas_ o de dos hojas, porque las _polípticas_ son las que exceden de este número. Se escribía también, según Plinio, en las hojas de palmera y de ciertas malvas; así es que en algunas comarcas de las Indias orientales, afirma Alfonso Costadan, escriben en las hojas del Macareguo, hojas que tienen seis pies de largo por uno de ancho. Lo propio hacen, dice Michael Boim, los habitantes del fuerte de Mieu, junto a Bengala y Pegú, sirviéndose del Areca, especie de palmera, y de la corteza del árbol llamado Avo. Los del reino de Siam y Camboya y los insulares de Filipinas (aunque estos últimos siguen el método de los españoles) se valen de las hojas de plátano, de palmera o de la parte lisa de las cañas en las que trazan sus caracteres con un punzón o cuchillo. Los siracusanos lo hacían en hojas de olivo y los atenienses en conchas. En Atenas, cuenta Suidas, que se consignaban los nombres de los valientes que habían sucumbido en defensa de la patria, sobre el velo de Minerva.\"},{\"heading\":false,\"text\":\"--Pues buena la pondrían la mantilla a la pobre señora. ¡Vamos! sería de casco y lo escribirían por el revés.\"},{\"heading\":false,\"text\":\"--Los indios, según Filostrato, hacían su escritura en los _Syndones_, que así llamaban a sus telas o vestidos.\"},{\"heading\":false,\"text\":\"--¡Ay! Pues yo siempre los he visto en cueros; es decir, en las estampas.\"},{\"heading\":false,\"text\":\"--Los judíos tenían una particular habilidad en unir los diferentes trozos del pergamino, haciéndolo en términos de no poderse distinguir señal alguna. Con este motivo, añade Flavio Josefo que Tolomeo Filadelfo se llenó de admiración cuando los setenta ancianos, enviados por el gran sacerdote, desdoblaron en su presencia los rollos de la ley toda escrita con caracteres de oro. No obstante, el grabado en seco, sin auxilio de la tinta ni de otro color, parece haber sido el primer procedimiento: los montañeses de _Kuei-cheu_ en China, así lo ejecutan sobre unas tablitas de madera muy tierna. Los parthos hacían en sus vestidos las letras con aguja, no usando del _papyrus_ que podrían haber hallado en abundancia en Babilonia.\"},{\"heading\":false,\"text\":\"--Ya que me vuelve usted loca con tanto nombre extranjero, explíqueme usted siquiera alguno de esos terminachos que como guijarros de punta me están levantando chichones en la cabeza.\"},{\"heading\":false,\"text\":\"--El _papyrus_ es una especie de caña parecida a la _typha_ propia de los parajes bajos y húmedos. Sus raíces leñosas tienen por lo regular diez pies de longitud: su tallo triangular no excede de dos codos en tanto que no se eleva sobre la superficie de las aguas; pero en su totalidad alcanza hasta cuatro o cinco. Después de varios procedimientos llegaba a ser papel, no excediendo nunca de la marca que se le tenía asignada, que era dos pies de longitud. Los instrumentos empleados para escribir han sido con corta diferencia los mismos que usamos en el día, a saber: la regla, el compás, el plomo, las tijeras, el cortaplumas, la piedra para afilar, la esponja, el estilo o punzón, la pluma o caña, el tintero o escribanía, el atril y las ampolletas o botellitas de vidrio, conteniendo una el líquido para volver más suelta la tinta espesada, y otra el bermellón o rojo para escribir los principios de los capítulos. El estilo, _stylus graphium_, y el buril, _cælum celtes_, sirvieron para la escritura en seco o sin tinta; de consiguiente se empleaban en los mármoles, metales y en las tablas preparadas con cera y yeso, y eran de varios tamaños y formas. La caña, _arundo_; el junco, _juncus_ y el _calamus_ usáronse en la escritura que se hacía con tinta; pero antes de conocerse la aplicación de las plumas. El Egipto, Gnido y el lago Amais en Asia, según Plinio, daban profusión de estos juncos o cálamos que los griegos se hacían llevar de Persia y que, cogidos en el mes de marzo en Aurac, dejaban endurecer por espacio de seis meses entre el fiemo o estiércol, tomando de este modo un hermoso barniz jaspeado de negro y amarillo oscuro.\"},{\"heading\":false,\"text\":\"En aquel instante sonó un ronquido; pero Benjamín embriagado en su peroración, no se detuvo hasta terminar su relato.\"},{\"heading\":false,\"text\":\"--El uso de las plumas de ánsares, cisnes, pavos y grullas --continuó disparado-- no data al parecer sino del siglo quinto. Los siameses se valían del lápiz. Los chinos emplean actualmente, como en la antigüedad, el pincel de pelo de conejo por mejor y más suave. La tinta de los tiempos remotos no tenía de común con la nuestra sino el color y la goma que entraba en su composición: Se llamaba _atramentum scriptorium_ o _librarium_, para distinguirla del _atramentum sutorium_ o _calchantum_. El negro lo hacían con el humo de la resina, de pez, de tártaro, marfil quemado y carbones triturados; cuyos ingredientes en fusión se sometían a la acción solar. Los pueblos orientales empleaban la gibia y el alumbre que los africanos substituían a veces con la adormidera o el jugo del calamar. Refiere Allatius haber visto la tinta de pelo de cabra quemado que, aunque un poco roja, tenía las propiedades de no perder su color, ser lustrosa y adherirse muy bien al pergamino; de modo que era muy difícil borrarla. La tinta china, conocida 1120 años antes de J. C., se extrae de varias materias y especialmente de los pinos o del aceite quemado. Entre los indios la decocción de las ramas de un árbol llamado _aradranto_ les suministra este licor tan...\"},{\"heading\":false,\"text\":\"Aquí llegaba Benjamín en su afluente desbordamiento, cuando un\"},{\"heading\":false,\"text\":\"--«Mátame al sabio», de Juanita que soñaba, le hizo comprender que su erudición era inútil y dio por terminada la conferencia.\"},{\"heading\":false,\"text\":\"En esto un hombre, que con una linterna encendida en la mano doblaba la esquina, desembocó en el _quadrivium_.\"},{\"heading\":false,\"text\":\"--¡El loco! --gritó Benjamín reconociendo a don Sindulfo, que en efecto venía en busca de los fugitivos; a cuya voz despertáronse los tres durmientes como si hubiesen sentido un sacudimiento galvánico.\"},{\"heading\":false,\"text\":\"--¡Favor! --exclamaron las infelices, abrazándose en defensa mutua.\"},{\"heading\":false,\"text\":\"Pero Benjamín, para quien aquella luz era como el relámpago para el caminante perdido en las tinieblas, antes de que su amigo les apercibiese, corrió a su encuentro vociferando como el sabio de Siracusa cuando al dar con la teoría del peso específico dicen que salió desnudo del baño repitiendo: ¡Eureka!\"},{\"heading\":false,\"text\":\"--¿De qué se trata? ¿Ha vuelto a la vida mi rival? --preguntó el demente persiguiendo su manía.\"},{\"heading\":false,\"text\":\"--No. He hallado el secreto de la inmortalidad. Leamos, alúmbreme usted.\"},{\"heading\":false,\"text\":\"Y consultando los cordelillos, su pecho se dilató al ver que la disposición de los nudos correspondía a la escritura armenia en la que creía poder alardear sus conocimientos.\"},{\"heading\":false,\"text\":\"--Y bien: ¿Qué dice?\"},{\"heading\":false,\"text\":\"Benjamín con no poca dificultad leyó lo que sigue:\"},{\"heading\":false,\"text\":\"--«Si quieres ser inmortal, anda a la tierra de Noé y...» ¡Maldición!\"},{\"heading\":false,\"text\":\"--¿Qué es ello?\"},{\"heading\":false,\"text\":\"--Que no puedo interpretar el sentido de los demás caracteres. No importa --continuó en su delirio--. Volaremos a la región del Patriarca y daremos solución a este enigma indescifrable.\"},{\"heading\":false,\"text\":\"--Si usted en cuestión de lenguas no conoce más que la estofada --se permitió argüir la intemperante Juanita; a cuya voz el loco fijando mientes en el grupo de las tres gracias, crispó los puños, y dirigiéndose a Sun-ché:\"},{\"heading\":false,\"text\":\"--Tú también me estorbas --dijo-- pero pronto no serás más que un cadáver.\"},{\"heading\":false,\"text\":\"E iba a abalanzarse sobre ella, cuando por dicha suya el sabio tropezó en uno de los poyos y cayó al suelo de bruces. Benjamín acudió en su auxilio mientras la trinidad femenina se replegaba con espanto hacia la fuente.\"},{\"heading\":false,\"text\":\"--Esto no se hace entre cristianos --gritó la de Pinto con toda la fuerza que le prestaba la indignación.\"},{\"heading\":false,\"text\":\"--¡Cristianos han dicho! --murmuró por lo bajo a su gente el ceryx, que atraído por la linterna de don Sindulfo, acechaba a los viajeros y que, por la relación de la palabra española con la latina dedujo una verdad funesta para los anacronóbatas.\"},{\"heading\":false,\"text\":\"--¿Qué? --se preguntaron todos al verse rodeados de los _vigiles_.\"},{\"heading\":false,\"text\":\"--Apoderaos de ellos.\"},{\"heading\":false,\"text\":\"El terror fue general.\"},{\"heading\":false,\"text\":\"--Yo soy inocente --aducía Clara.\"},{\"heading\":false,\"text\":\"--Respetad a la emperatriz --ordenaba Sun-ché en chino.\"},{\"heading\":false,\"text\":\"--¡Prenda usted a ese, señor guindilla! --balbuceaba la maritornes señalando al tutor.\"},{\"heading\":false,\"text\":\"Pero como los gritos fuesen en aumento, les aplicaron unas mordazas y maniatados los condujeron a la presencia del prefecto que en desenfrenada orgía saboreaba en el pretorio el motín tan favorable a la causa de Domiciano.\"},{\"heading\":false,\"text\":\"--¡Piedad! --articularon todos, libertados de sus ligaduras y cayendo a los pies del ebrio senador.\"},{\"heading\":false,\"text\":\"--No le excitéis con vuestros ayes --observó el políglota--. Reparad que no entiende más que el latín.\"},{\"heading\":false,\"text\":\"--Pues bien: _In nomine Domini nostri Jesu-Cristi_ --dijo Juanita muerta de miedo y recordando la salutación con que el cura de su lugar daba los buenos días a sus feligreses.\"},{\"heading\":false,\"text\":\"--¿Quién pronuncia aquí el nombre del impostor de Galilea? --rugió el prefecto pudiendo apenas mantenerse en equilibrio.\"},{\"heading\":false,\"text\":\"--Estos cristianos que acaban de profanar la estatua de Nerón.\"},{\"heading\":false,\"text\":\"--¿Cuál es el jefe?\"},{\"heading\":false,\"text\":\"--Este, el más viejo --contestó Juanita impuesta por la traducción de Benjamín.\"},{\"heading\":false,\"text\":\"--Subidlo al cráter y arrojadlo en las entrañas del Vesubio.\"},{\"heading\":false,\"text\":\"Una explosión de lágrimas y lamentos sucedió a tan bárbara orden; pero antes de que las excursionistas pudieran dirigir una palabra de consuelo a don Sindulfo, este había desaparecido entre un grupo de _vigiles_ encargados de la ejecución del decreto.\"},{\"heading\":false,\"text\":\"--Los demás --prosiguió el togado beodo-- apréstense a servir de bestiarios en los circenses de mañana.\"},{\"heading\":false,\"text\":\"--¡Horror! Nos destinan al circo --tradujo el arqueólogo, cubriéndose el rostro con las manos, mientras Clara perdía el sentido y Sun-ché interrogaba con ojos extraviados sin obtener contestación.\"},{\"heading\":false,\"text\":\"--¿Al circo? Pues no se apuren ustedes --objetó Juana-- que si es en el de _Price_ yo tengo allí un primo aposentador.\"},{\"heading\":false,\"text\":\"--No: se nos condena a ser devorados por las bestias feroces.\"},{\"heading\":false,\"text\":\"Amordazados de nuevo, nadie pudo proferir una queja. Los _vigiles_ sacaron del pretorio a los reos, y el _Præfectus urbis_, tambaleándose, volvió a la sala del festín gritando a sus comensales con feroz alegría:\"},{\"heading\":false,\"text\":\"--El pueblo tendrá bestiarios: la paz de Pompeya queda por ahora asegurada.\"},{\"heading\":false,\"text\":\"Y en efecto; unas horas después, al resplandor del sol naciente, el pobre tutor con los pies ensangrentados por la penosa ascensión del Vesubio rodaba a los profundos abismos del volcán, al mismo tiempo que sus compañeros de viaje penetraban en las mazmorras del anfiteatro para servir de pasto a las fieras y de diversión a la más soez de las plebes.\"}]},{\"title\":\"El anacronópete — capítulo xviii\",\"blocks\":[{\"heading\":false,\"text\":\"«Sic transit gloria mundi»\"},{\"heading\":false,\"text\":\"No me detengo a describir el anfiteatro porque, exceptuando los ciegos de nacimiento, todos en España han visto una plaza de toros, con la que aquel guarda una completa analogía. Baste saber que los veinte mil espectadores, de que era capaz el de Pompeya, invadieron desde muy temprano aquel día los asientos que los _locarios_ les designaban en los _cunei_ o secciones previamente dispuestas por los _designatores_ o maestros de ceremonias, según el rango y circunstancias de cada uno.\"},{\"heading\":false,\"text\":\"El _podium_, que era como si dijéramos la meseta del toril con gradines y extendiéndose por todo el círculo de la plaza, estaba destinado a los funcionarios de alta jerarquía. En él campeaba el _cubiculum_ o palco del prefecto, a imitación del _suggestum_ o trono del emperador en Roma, cubierto con un dosel a manera de pabellón; distintivo que, aunque menos suntuoso, ostentaban asimismo las localidades accidentalmente ocupadas por una vestal, un senador o algún enviado de las naciones extranjeras.\"},{\"heading\":false,\"text\":\"A continuación del _podium_ venían las filas de gradas para los caballeros; y tras de ellas la _popularia_, el tendido, el sol por decirlo así; aunque la comparación no es fiel, pues maldito si los rayos del rubicundo Febo molestaban al público. Y no es porque nubes lo empañasen, que esplendente brillaba en mitad del firmamento, y con alientos tales que, no por ser el octavo día del mes de septiembre, pudieron prescindir de refrescar el ambiente, como lo verificaban en canícula, merced a un licor odorífero compuesto de agua, vino y azafrán, conducido por unos tubos hasta el espacio cubierto, consagrado a las mujeres en la parte superior del edificio, para desde allí hacerlo caer en lluvia cernida sobre el concurso. Tampoco obedecía el eclipse al capricho de ninguna empresa niveladora de clases en beneficio de sus intereses, como la de Casiano, que en Madrid y en el año de gracia de 1874, se permitió fijar este anuncio célebre la víspera de una corrida extraordinaria: _De orden de la autoridad mañana no hay sol_. Consistía sencillamente en que por encima de las cabezas de los circunstantes corrían unos toldos de lona que en los grandes circenses romanos solían ser de seda y púrpura bordados de oro.\"},{\"heading\":false,\"text\":\"Bajo el podio, en derredor de la arena, estaban las _caveæ_, bóvedas o casetas poco elevadas, con sus _posticæ_ o compuertas cerradas por los _ferreis clathris_ --grifos de hierro-- en las que se metía a los gladiadores y las fieras destinados al combate. En frente se hallaba situada la puerta _libitinensis_, por donde se sacaba a los bestiarios muertos para ser conducidos al _spoliarium_, en el que se les despojaba completamente de lo que sobre sí tenían.\"},{\"heading\":false,\"text\":\"Los ecos de los clarines anunciaron la aproximación de los gladiadores; y en efecto, no tardaron en presentarse en la arena todos juntos para saludar al auditorio; siendo recibidos por este con un batir de palmas que no parecía sino que Frascuelo y Lagartijo habían cambiado de traje y que el público de los barrios altos y bajos de Madrid estaba veraneando en Pompeya. Porque hay que tener presente que aplaudir y silbar ha sido en todas épocas el modo más admitido por el pueblo de expresar su satisfacción o su desagrado; y cuando esta última manifestación tenía lugar en un teatro, el actor que de ella era objeto, estaba en el deber de quitarse la máscara como para acusar recibo de la silba.\"},{\"heading\":false,\"text\":\"Despejado el redondel después del paseo, un nuevo punto de clarín echó al anillo a los _essedarios_; luchadores que combatían sobre carros, a ejemplo de los galos y bretones. Vinieron en seguida los _hoplomacos_, armados de pies a cabeza y antagonistas de los _provocadores_. Ni unos ni otros consiguieron hacerse sangre, quedando todo reducido, con gran descontentamiento de la muchedumbre, a unos cuantos chichones sin consecuencia. Tras estos exhibiéronse los _mirmillones_ o _gallos_, que usando de lanza y escudo a la manera de los originarios de la Galia, reñían con los _retiarios_; los cuales al perseguirlos con la red y el tridente les gritaban: «_Galle, non te peto; piscem peto_». Es decir: «_Gallo, no a ti; a tu pescado quiero_». Con lo que aludían a un pez de metal que en la cimera de sus cascos ostentaban los opuestos combatientes. O el gallo había perdido los espolones o el pescador lo era más de caña que de red, ello es lo positivo que en una de las intentonas tuvieron la mala suerte de tropezar, cayendo cada cual por su lado, y sobre los dos una rechifla que ni cuando el concejal presidente deja pasar un toro de varas.\"},{\"heading\":false,\"text\":\"Por fin sonó la hora de los _meridianos_, gladiadores que peleaban a la de medio día, y cuyo espectáculo era, para hablar técnicamente, el bicho de la tarde, el _quinto_ escogido a pulso: una circunstancia excepcional venía a hacerlos más interesantes; ambos luchadores eran _rudiarii_; o lo que es igual, que habiendo servido tres años consecutivos, tenían ganado el _rudis_, grueso bastón con nudos, símbolo de retiro o licenciamiento en los circenses, donde ya no debían volver a presentarse sino, como en la ocasión aquella, por un acto de su voluntad omnímoda.\"},{\"heading\":false,\"text\":\"Aplaudidos y otorgada la venia por el gobernador o prefecto presidente, empuñaron las _arma lusoria_; espadas de madera recibidas en premio en varios ejercicios; y con ellas empezaron a ejercitarse cruzándolas en continuos choques: especie de proemio, como cuando los picadores prueban las puyas sobre la valla, al que daban el nombre de _præludere_, _ventilare_. Pero era necesario andar muy listos en esta operación; porque, en cuanto el clarín sonaba, deponían los juguetes; y, echando mano de los verdaderos trastos de matar, propinábanse cada linternazo que era una bendición de Dios.\"},{\"heading\":false,\"text\":\"Así lo hicieron; y como los dos eran _mataores_ de fama, costó gran trabajo al más afortunado --pues no sé si era el más fuerte-- derribar de un _volapié_ a su antagonista que cayó a plomo revolcándose en la arena.\"},{\"heading\":false,\"text\":\"A la vista de la sangre, el pueblo lanzó un rugido de entusiasmo. El vencedor consultó con la mirada al auditorio que, teniendo derecho de vida o muerte sobre el vencido, podía otorgarle gracia presentando la palma de la mano con el pulgar encogido; pero la sed de matanza era tal, que los jueces, tendiendo por el contrario el pólice y cerrando el puño, prorrumpieron unánimemente en voces de: _recipere ferrum_; lo que equivalía a exigir que se le diera el cachete. Solo faltaba la ratificación del prefecto al clamor popular; pero el presidente, sea por lástima o por capricho autoritario de oposición, agitó un lienzo blanco en señal de conceder el _missio_ o perdón por aquella vez en nombre del monarca augusto. Clemencia estéril entonces porque el herido acababa de ascender a cadáver. Retirado su cuerpo de la arena con unos garfios de que tiraban cuatro esclavos, dos ediles salieron a ofrecer al victorioso atleta la palma de plata otorgada a su valor. Los espectadores no creyendo justa la recompensa, pusiéronse a gritar:\"},{\"heading\":false,\"text\":\"--_¡Lemnisci! ¡Lemnisci!_\"},{\"heading\":false,\"text\":\"Y el prefecto, a fin de no herir susceptibilidades, accedió a la demanda disponiendo entregar al gladiador, en sustitución de la palma, las guirnaldas de flores sujetas por cintas de lana, símbolo de los _lemniscati_; con lo que el agraciado quedaba manumitido de la esclavitud, entrando desde aquel instante en la categoría de los _libertos_.\"},{\"heading\":false,\"text\":\"Un murmullo de satisfacción que con el arrellanarse en los asientos es en toda asamblea precursor del espectáculo preferente, indicó el turno de los bestiarios.\"},{\"heading\":false,\"text\":\"Clara y Sun-ché, agobiadas bajo el peso de tan espantosa situación, eran casi conducidas en vilo por unos soldados, pues su abatimiento las impedía caminar. Benjamín, sacando fuerzas de flaqueza, procuraba mostrarse hombre y filósofo, avanzando serenamente. Juanita era la que con una resolución impropia de las circunstancias, entró en la arena emulando en desenvoltura a los chicos que se echan al redondel a correr novillos embolados. Habiendo escapado ya a tan varios como inminentes peligros, creíase _impermeable_, valiéndonos de su propia expresión para traducir la idea de invulnerabilidad. El éxito que obtuvo su porte no se puede comparar sino a las ovaciones que alcanzan en Madrid las malas comedias.\"},{\"heading\":false,\"text\":\"Vestían los reos calzón y túnica corta y llevaban los brazos y piernas liados con unas tiras de cuero como los primitivos guerreros de la Lombardía. Blandiendo con la mano derecha una espada corta, pendía de su izquierda un paño rojo destinado a excitar a las fieras, de lo que acaso ha tomado origen nuestra suerte de matar en el arte de Pepe-Hillo.\"},{\"heading\":false,\"text\":\"Llevados ante el _cubiculum_ del prefecto, les obligaron a entonar por tres veces el _morituri te salutant_; pero Juanita, amiga siempre de chacota, queriendo patentizar sus conocimientos en el latín de su uso, tomó los trastos con la extremidad del siniestro remo anterior y, simulando descubrirse con el brazo libre:\"},{\"heading\":false,\"text\":\"--_Dominus vobiscum_ --le dijo al senador--. _Brindo para que usiam reventatur como un perri de una indigestionem de morcillam. Salutem y sarnam._\"},{\"heading\":false,\"text\":\"Concluida la peroración y diseminados los luchadores por el anillo, los guardias se retiraron y el prefecto hizo la señal de que soltasen las fieras. Juanita, cuadrándose delante de las _caveæ_, se dispuso a _recibir_ y las puertas giraron sobre sus goznes. Pero en vez de los leones del desierto de Lybia, Luis y Pendencia con sus quince compañeros de armas desembocaron en el circo apercibiendo los revólveres ya habilitados por el sistema de la _desinalterabilidad_, de que el malogrado don Sindulfo les enseñó a hacer uso en su primer rapto de locura.\"},{\"heading\":false,\"text\":\"Verlos y arrojarse cada una sobre su cada cual, inclusa Sun-ché aunque no tenía cuyo, y Benjamín que simpatizaba con todos, obra fue de un mismo instante.\"},{\"heading\":false,\"text\":\"--¿No se lo decía yo a usted? --gritaba la de Pinto--. Si son como los espárragos, perdonando el modo de señalar; que les corta usté la cabeza y en seguida les vuelve a salir otra.\"},{\"heading\":false,\"text\":\"Pero la ocasión no era la más propicia para entretenerse con símiles. Los espectadores, defraudados en sus esperanzas y comprendiendo por lo que veían, que estaban siendo víctimas de un engaño, prorrumpieron en voces de:\"},{\"heading\":false,\"text\":\"--¡Traición!\"},{\"heading\":false,\"text\":\"Y abandonando las gradas, echaron fuera sus aceros y se aprestaron a hacer irrupción en la arena, para tomarse venganza por su mano.\"},{\"heading\":false,\"text\":\"Luis, que todo lo tenía previsto, formó el cuadro con su fuerza, y, colocando en el centro a las mujeres, antes de que la turba transpusiese el podio, le envió una descarga de la que ni un solo tiro quedó por aprovechar. Sucedió una pausa producida por el asombro; mas como el valor de los pompeyanos era incontestable y no habían tenido aún tiempo de encontrar la explicación del fenómeno, trataron de insistir con más vehemencia, siendo detenidos en su empuje por una segunda hecatombe. Los pusilánimes se detuvieron; los más esforzados solo tuvieron un grito:\"},{\"heading\":false,\"text\":\"--¡Adelante!\"},{\"heading\":false,\"text\":\"Y ya empezaban a descolgarse en la arena cuando Luis, mandando hacer fuego graneado sobre ellos, dispuso una especie de caza, cuyos efectos los dejó consternados. Aquellos pequeños útiles de guerra que a tal distancia enviaban la muerte arrojando proyectiles sin interrupción, tomaron a sus ojos un carácter sobrenatural que no titubearon en atribuir al implacable enojo de sus dioses: el pánico sobrevino y la dispersión se hizo general.\"},{\"heading\":false,\"text\":\"¡Poder del progreso que permitía a un puñado de hombres ver correr en su presencia a veinte mil legionarios conquistadores del mundo entero!\"},{\"heading\":false,\"text\":\"El anfiteatro se quedó vacío. Entonces comenzaron las expansiones, el deplorar la suerte adversa del tutor para cuyo rescate toda tentativa se juzgó inútil, pues debía haberse ya cumplido la sentencia; y por último las explicaciones y muy particularmente la que con la reaparición de los hijos de Marte se relacionaba. Esta no podía ser más sencilla.\"},{\"heading\":false,\"text\":\"Mis lectores recordarán sin duda unos martillazos que don Sindulfo y Benjamín oyeron mientras recorrían el Anacronópete la noche que pernoctaron en China. Pues bien, dábanlos los mílites que, buscando asilo más seguro para hacer la travesía aérea que los parapetos de las provisiones, se confeccionaron, con unas lonas embreadas que había en la cala, un enorme zurrón o hamaca tendida en el espacio hueco del podio, con la que comunicaban merced a una abertura, provista para mayor disimulo de su correspondiente compuerta, practicada junto a la guillotina de la descarga, y donde el gas respirable entraba por un tubo de goma a través de un simple agujero.\"},{\"heading\":false,\"text\":\"--De modo --concluyó Pendencia-- que cuando don Pichichi, que requiezcat, creyó arrojarnos en el _dezpacio_, no hizo más que abrirnos la puerta prencipal de nuestra propia caza.\"},{\"heading\":false,\"text\":\"Dadas gracias a Dios y celebrada la ocurrencia:\"},{\"heading\":false,\"text\":\"--Ahora escapemos; la tierra de Noé nos aguarda --dijo Benjamín sacándose del pecho los cordeles que había conservado en medio de tanta tribulación.\"},{\"heading\":false,\"text\":\"Embriagados todos en su felicidad le siguieron automáticamente; pero al llegar a la puerta la encontraron cerrada; y, por los alaridos que daba el populacho al exterior, dedujeron que forzarla sería imprudencia. Y efectivamente, todo el pueblo acarreando muebles, canastas, maderos y cuantos utensilios pudieran servirles para formar barricadas, levantaban una colosal alrededor del edificio en el que los anacronóbatas iban a ser sitiados por hambre.\"},{\"heading\":false,\"text\":\"La situación era grave. Restituidos al redondel, ya se habían puesto a discutir en consejo de familia, cuando un estampido horroroso retumbó en todos los ámbitos de la ciudad y una luz cárdena iluminó el espacio. El susto fue de padre y muy señor mío, porque, sin pensar en el anacronismo que cometían, los expedicionarios atribuyeron la detonación a la pólvora de alguna mina con que los indígenas querían volar el edificio.\"},{\"heading\":false,\"text\":\"--Piensen ustedes en la fecha relativa de hoy --decía Benjamín--. ¿En qué día creen ustedes que vivimos?\"},{\"heading\":false,\"text\":\"--Lo que es para nosotros siempre es martes --repuso Juanita.\"},{\"heading\":false,\"text\":\"Una segunda conmoción aumentó la alarma. El arqueólogo se puso pálido como la muerte y, aspirando el olorcillo de azufre de que estaba impregnada la atmósfera:\"},{\"heading\":false,\"text\":\"--¡Maldición! --gritó mesándose los cabellos.\"},{\"heading\":false,\"text\":\"--¿Qué pasa? --interrogaron los excursionistas.\"},{\"heading\":false,\"text\":\"--¡Sí... eso es... día 8 de septiembre del año setenta y nueve de la era cristiana!... ¡La erupción del Vesubio!... ¡¡¡Nos hallamos en el último día de Pompeya!!!...\"},{\"heading\":false,\"text\":\"Aún no había concluido la frase, cuando un calambre geológico, una sacudida del suelo volcánico, sacando al circo de su asiento, derribó gran parte de sus muros haciendo rodar por la arena a los interlocutores sin que, felizmente, ninguno de ellos fuera alcanzado por los escombros. La lava caía a torrentes, la ceniza embargaba la respiración.\"},{\"heading\":false,\"text\":\"--Salvémonos --gritó Benjamín apenas pudo ponerse en pie; y todos se precipitaron por la abertura, pasando por encima de cadáveres abrasados por la erupción y desatendiendo los ayes de los moribundos y la desesperación de los vivos.\"},{\"heading\":false,\"text\":\"La inalterabilidad a que estaban sujetos haciéndolos insensibles a la influencia de cualquiera acción física, les permitió llegar al Anacronópete sin obstáculo alguno; pues las sustancias en fusión resbalaban sobre sus carnes sin adherirse.\"},{\"heading\":false,\"text\":\"Instalados en él, Benjamín elevó el vehículo a la zona de locomoción. Un ruido como el de una piedra chocando en un tubo de desalojamiento, produjo un sonido campanudo; pero ya el coloso había emprendido su vertiginosa marcha y, devorando tiempo, se lanzaba a enriquecer la ciencia con el descubrimiento del pasado, mientras a sus pies dejaba una dolorosa enseñanza para el porvenir.\"}]},{\"title\":\"El anacronópete — capítulo xix\",\"blocks\":[{\"heading\":false,\"text\":\"Los náufragos del aire\"},{\"heading\":false,\"text\":\"El trayecto que tenían que recorrer, pues determinaron no detenerse en ningún punto, era el más largo que se había llevado a efecto en toda la expedición. Se encontraban en el año 79 de la era cristiana; y el Diluvio Universal corresponde como nadie ignora al 3308 antes de J. C.\"},{\"heading\":false,\"text\":\"Aunque la zona en que viajaba el Anacronópete estuviese muy por encima de la región en que se forman las tempestades y no tuvieran nada que temer por consiguiente del cataclismo provocado por la maldad de los hombres, creyeron no obstante deber dar oídos a la prudencia y se convino en hacer alto en un período posterior, históricamente hablando; lo que caminando hacia atrás equivale a tocar tierra antes de llegar a aquella gran catástrofe.\"},{\"heading\":false,\"text\":\"Su objeto era avistarse con Noé; y como este repoblador del mundo vivió todavía 350 años después de salir del arca, no solamente podían evitar las contingencias del Diluvio, sino hacerse más pronto dueños del secreto de la inmortalidad desembarcando en el 2958 (a. de J. C.) en que acaeció su muerte; o sea a 3037 años de la destrucción de Pompeya añadiendo los 79 que les faltaba trasponer del siglo primero.\"},{\"heading\":false,\"text\":\"Con todo; como no era cosa de irle a entretener de semejante asunto en las postrimerías de su existencia, y teniendo tiempo a mano de que disponer, se votaron un par de lustros más para imprevistos, y se fijó el descenso en el año 3050 del día de la fecha; trece antes del fin del patriarca, a los 937 de su edad y con 258 de antelación al desquiciamiento del globo.\"},{\"heading\":false,\"text\":\"Contando pues en números redondos una marcha de cinco siglos diarios, necesitaban siete días (incluyendo las paradas de las comidas en plena atmósfera) para tragarse las treinta centurias y media en cuestión. Pero el humor no faltaba, si bien turbado a intervalos por el recuerdo de don Sindulfo, y había provisiones para dos meses; de modo que, si nada es más largo que una semana de hambre, ellos parafraseando el axioma, presentían que nada iba a ser más corto que otra de felicidad.\"},{\"heading\":false,\"text\":\"La expedición tuvo principio en las mejores condiciones. Los ocios se mataban ora explicando a Sun-ché las maravillas del invento y narrándole las peripecias del viaje (si bien haciendo caso omiso de su parentesco con el inventor para evitarle las amarguras de la viudez), ora fundando planes sobre el porvenir, todos por supuesto de color de rosa y perfumados con el incienso de la vicaría.\"},{\"heading\":false,\"text\":\"Poco más de la mitad del camino tenían ya andado, cuando en la hora meridiana del cuarto día y en sazón en que el vehículo cortaba la más limpia y transparente de las atmósferas, el aparato dejó repentinamente de funcionar.\"},{\"heading\":false,\"text\":\"--¿Qué ocurre? --se preguntaron todos con extrañeza.\"},{\"heading\":false,\"text\":\"--Algún cambio de tiro --repuso Juanita.\"},{\"heading\":false,\"text\":\"Pero la actitud alarmante de Benjamín no permitió a nadie saborear el chiste.\"},{\"heading\":false,\"text\":\"--Tal vez una solución de continuidad... --dijo este meditabundo.\"},{\"heading\":false,\"text\":\"--Entonces vamos a despeñarnos sobre la tierra si la corriente no se establece --adujo Luis.\"},{\"heading\":false,\"text\":\"--Sin embargo --objetó el políglota-- no nos movemos.\"},{\"heading\":false,\"text\":\"--¡Cómo! ¿Ezto ni zube ni baja?\"},{\"heading\":false,\"text\":\"--No.\"},{\"heading\":false,\"text\":\"--Puez ací ce quedó Quevedo.\"},{\"heading\":false,\"text\":\"Y precedidos de Benjamín los excursionistas se consagraron al reconocimiento del mecanismo sin hallar desperfecto alguno que les procurara la clave del enigma. La tarde se pasó en vanas tentativas, y con las sombras de la noche la alarma, exagerando el peligro, alcanzó proporciones considerables. Pocos fueron los que lograron dormitar; dormir ninguno. Con la luz del alba repitiéronse las observaciones; y como casi todos alcanzaban los mismos grados de inteligencia en mecánica, las opiniones podían contarse por los individuos.\"},{\"heading\":false,\"text\":\"Al tercer día, los militares como recurso supremo y sin dar cuenta a Benjamín de lo que consideraban muy luminosa idea, se decidieron a deslastrar el Anacronópete; y empezaron a arrojar por las compuertas las cajas y costales que más a mano se les vinieron, sin reparar en clase ni condición. Término estaban poniendo a su tarea, cuando Benjamín que, atraído por los golpes, llegó a la cala:\"},{\"heading\":false,\"text\":\"--¡Desgraciados! ¿Qué hacéis? Deteneos --gritó fuera de sí.\"},{\"heading\":false,\"text\":\"--¡Le peza mucho la tripa a la cabalgadura!\"},{\"heading\":false,\"text\":\"--Pero nos estáis dejando sin provisiones de boca; y nuestro caso es horrible: ¡Hemos naufragado en el aire!...\"},{\"heading\":false,\"text\":\"Aquel grito fue la señal del pánico. Toda esperanza estaba en efecto perdida; y por un azar hijo de la impremeditación se veían sin vitualla, pues las existentes apenas alcanzaban para cuarenta y ocho horas.\"},{\"heading\":false,\"text\":\"Semejante peligro era indudablemente el más grave a que habían estado expuestos.\"},{\"heading\":false,\"text\":\"--¿Quién podrá venir en nuestro socorro? --preguntaba la pupila con las de sus ojos arrasados en lágrimas.\"},{\"heading\":false,\"text\":\"--Deje usted; que puede que pase algún titiritero de esos que suben en globo y nos echará una cuerda --aducía Juana optimista hasta competir con el célebre Panglos.\"},{\"heading\":false,\"text\":\"--¿Aereonautas aquí? --exclamaba con desaliento el arqueólogo consultando la situación--. ¿Ignoras que estamos en el año 1645 antes de la era cristiana y encima mismo del desierto de Sin?\"},{\"heading\":false,\"text\":\"--Ci a mí me dan un cable yo me comprometo a dezcolgarme para ezplorar el horizonte --propuso Pendencia.\"},{\"heading\":false,\"text\":\"Pero ni había a bordo soga tan larga, ni, aun siendo posible el descenso, debía exponerse el valiente andaluz a quedar en tierra si al vehículo se le ocurría emprender la marcha sin más razón que la que había tenido para pararse. Encomendóse pues la salvación de los náufragos a aquella débil pero única probabilidad, y como medida de precaución se acortaron las raciones.\"},{\"heading\":false,\"text\":\"Seis días después de la detención ya no tenían qué llevarse a la boca. Al séptimo hubo que triturar las sustancias que contenían algún jugo y elaborar una especie de harina con sus principios leñosos. Al octavo la fiebre había ganado las filas. Al noveno no quedaba ningún recurso; y el aire que por todas las ventanas abiertas penetraba, era insuficiente para la respiración de aquellos infelices asfixiados por la sed y demacrados por el hambre.\"},{\"heading\":false,\"text\":\"Al amanecer del décimo, los excursionistas yacían tendidos por el laboratorio, cuyo aspecto tenía muchos puntos de contacto con un campo de batalla sembrado de cadáveres.\"},{\"heading\":false,\"text\":\"--Decidámonos. ¿Qué se hace? --preguntó Benjamín dando un rugido con el aliento que le prestaba la desesperación.\"},{\"heading\":false,\"text\":\"--Devorarnos a la suerte --gritó un soldado. A cuya proposición asintieron en coro todos los hijos de Marte cerrando los oídos a las súplicas que las mujeres anonadadas les dirigían.\"},{\"heading\":false,\"text\":\"--Un momento de reflexión --adujo Luis pensando en Clara--. Acaso se le ocurra a alguien otro plan menos cruento.\"},{\"heading\":false,\"text\":\"--No; a la suerte --vociferaron los mílites tomando una actitud amenazadora.\"},{\"heading\":false,\"text\":\"--Dicen bien --objetó Benjamín--. No hay salvación para nosotros; hace diez días que permanece inmóvil el aparato.\"},{\"heading\":false,\"text\":\"--Zobre todo el dijeztivo.\"},{\"heading\":false,\"text\":\"--El hambre nos acosa y el instinto de conservación aconseja una determinación radical.\"},{\"heading\":false,\"text\":\"--¡Qué lástima que los judíos hayan matado a don Sindulfo! --balbuceó la decidora Juanita--. ¿Quién le tuviera aquí?\"},{\"heading\":false,\"text\":\"--¿Para qué? ¡Una boca más!\"},{\"heading\":false,\"text\":\"--No, señor; para hacerle pagar el pato.\"},{\"heading\":false,\"text\":\"Al oír el pato verificóse un movimiento de reacción en los viajeros que les hizo incorporarse; pero convencidos de que eran víctimas de una ilusión, todos ahogaron un suspiro y volvieron a dejarse caer.\"},{\"heading\":false,\"text\":\"--¡No más treguas! --insistieron los peticionarios.\"},{\"heading\":false,\"text\":\"--¡Piedad! --murmuró Clara, estrechando las manos de Luis.\"},{\"heading\":false,\"text\":\"--Por última vez --intercedió el enamorado capitán dirigiéndose a los suyos-- yo os exhorto a que hagáis gracia a las mujeres.\"},{\"heading\":false,\"text\":\"--Ci. Puez para hacerlaz reír eztamoz ahora.\"},{\"heading\":false,\"text\":\"--¡No!\"},{\"heading\":false,\"text\":\"--Pues bien; yo os doy mi vida por la suya.\"},{\"heading\":false,\"text\":\"--Ezo ez diztinto; ze aprueba, porque todoz hemoz de ir cayendo por turno. Ahora te convenceráz de mi amor, Juanita.\"},{\"heading\":false,\"text\":\"--¿Por qué?\"},{\"heading\":false,\"text\":\"--Porque mil vecez te he dicho: «Te quiero tanto, que te comería.» Y ci te toca número bajo yo te probaré mi cariño.\"},{\"heading\":false,\"text\":\"Perdida ante el hambre toda noción de humanidad y de respeto, los soldados puestos de pie exigían con tal ahínco el cumplimiento de su demanda, que hubiera sido temeridad exponerse a que, tomando por sí mismo la justicia, se convirtiese en ley del capricho lo que podía concretarse a contingencia de la fortuna.\"},{\"heading\":false,\"text\":\"--Resignación --dijo Benjamín--. Manos a la obra. Apuntemos los nombres; venga papel.\"},{\"heading\":false,\"text\":\"--¿Papel? Nos hemos engullido hasta los billetes de banco.\"},{\"heading\":false,\"text\":\"--Pues echemos pajas.\"},{\"heading\":false,\"text\":\"--No; que nos podemos comer el juego.\"},{\"heading\":false,\"text\":\"--Ya sé --prosiguió el políglota--. Aquí tengo mi colección de minerales y piedras preciosas; cada cual tome un ejemplar cuya inicial del color corresponda con la de su nombre. Así, por ejemplo: Luis, lázuli: Pendencia... perla: Clara, coral.\"},{\"heading\":false,\"text\":\"--Usted, Benjamín, tomará el verde --interpuso Juanita.\"},{\"heading\":false,\"text\":\"--Verde se escribe con V.\"},{\"heading\":false,\"text\":\"--Para prozodias eztá el estómago.\"},{\"heading\":false,\"text\":\"Distribuidas aquellas boletas de nueva invención, metiéronlas en un pañuelo y dispusiéronse a dar comienzo al acto.\"},{\"heading\":false,\"text\":\"--¡A ver! Una mano inocente.\"},{\"heading\":false,\"text\":\"--Como no zea la del almirez...\"},{\"heading\":false,\"text\":\"--Usted, Clara.\"},{\"heading\":false,\"text\":\"--Yo no quiero ser responsable de la muerte de mi prójimo --dijo la pupila eludiendo la oferta.\"},{\"heading\":false,\"text\":\"--Tú, Juana.\"},{\"heading\":false,\"text\":\"--No, que estoy segura de sacar la _jota_. Que escoja la emperatriz, que justo es que le toque a ella la China.\"},{\"heading\":false,\"text\":\"Y ya le iban a presentar el bombo a Sun-ché, cuando un bulto que se desprendía por uno de los ventiladores, hizo volver a todos la cabeza hacia aquel sitio.\"},{\"heading\":false,\"text\":\"--¡Don Sindulfo! --gritó el arqueólogo dejando caer las piedras.\"},{\"heading\":false,\"text\":\"--¡El loco! --exclamaron los circunstantes no atreviéndose a creer lo que veían.\"},{\"heading\":false,\"text\":\"Era realmente el asendereado tutor el que, excitado por la locura, aunque impotente por la inanición, se presentaba a sus ojos convertido en un esqueleto parlante.\"},{\"heading\":false,\"text\":\"¿Cómo se encontraba allí? Es muy sencillo. Al arrojarle al Vesubio, su cuerpo en vez de seguir hasta el fondo, se detuvo en una de las rocas salientes del interior del cráter. La inalterabilidad a que estaba sometido le permitió no solo resistir la caída sin el menor daño, sino soportar también la alta temperatura de aquel antro en fusión. Al verificarse la erupción fue lanzado al espacio con la peña que le sustentaba; pero como en aquel instante el Anacronópete, al salir huyendo de Pompeya, cortase la parábola que don Sindulfo describía, uno de los tubos de desalojamiento le recibió como el buzón recibe una carta, produciendo aquel extraño ruido que los viajeros tomaron por el choque de una piedra sobre el vehículo.\"},{\"heading\":false,\"text\":\"--¿De modo, que del boleo que le dio a usted el volcán, vino usted a colarce por el rezpiradero del _ana compepe_?\"},{\"heading\":false,\"text\":\"--Sí; para satisfacer mi venganza.\"},{\"heading\":false,\"text\":\"--¿Cómo?\"},{\"heading\":false,\"text\":\"--Al oír que mi sobrina y Luis se abandonaban a los mayores transportes de felicidad: al ver vivo al rival de quien ya me juzgaba libre, los celos ejercieron sobre mí su funesto poder y concebí la idea de que pereciésemos todos juntos.\"},{\"heading\":false,\"text\":\"--Pero ¿por qué medio? --interrogó su colega.\"},{\"heading\":false,\"text\":\"--Fijando en el espacio el Anacronópete, cuyo mecanismo secreto no conocéis ninguno, para condenaros a la inmovilidad en la atmósfera insondable y complacerme en vuestra lenta agonía.\"},{\"heading\":false,\"text\":\"--¡Miserable! --prorrumpieron los soldados--... ¡Muera!\"},{\"heading\":false,\"text\":\"--Ci, muera; que cea ezta la primera rez que ce zacrifique en nuestro _holoclauztro_.\"},{\"heading\":false,\"text\":\"--Matadme en buen hora; no haré sino precederos. Vuestra suerte no por eso ha de cambiar.\"},{\"heading\":false,\"text\":\"--Tiene razón --objetó Benjamín--, no adelantamos nada.\"},{\"heading\":false,\"text\":\"--Sí; se adelanta la comida --arguyó la de Pinto.\"},{\"heading\":false,\"text\":\"--¿Luego no hay clemencia?\"},{\"heading\":false,\"text\":\"--Ninguna. Muramos.\"},{\"heading\":false,\"text\":\"--Corriente, muramoz; pero lo que ez usted inaugura el matadero.\"},{\"heading\":false,\"text\":\"--A él, camaradaz.\"},{\"heading\":false,\"text\":\"Los soldados se precipitaron sobre don Sindulfo a pesar de la resistencia de Sun-ché que por gestos les pedía el perdón del hombre por quien experimentaba tan invencible simpatía. Ya iban a descargarle el golpe fatal, cuando una lluvia benéfica que penetraba por la claraboya del techo, suspendió la mano de aquellas sedientas criaturas.\"},{\"heading\":false,\"text\":\"--¡Agua! --articularon todos abriendo la boca para recibir el celestial rocío.\"},{\"heading\":false,\"text\":\"--¡Es nieve! --exclamó Juanita reparando que más que gotas aquello parecían copos.\"},{\"heading\":false,\"text\":\"--¡Tampoco ez nieve! --repuso con alegría Pendencia al saborearlo--. Hay dentro azí como unos chícharoz.\"},{\"heading\":false,\"text\":\"Benjamín que hasta entonces permaneciera silencioso, dióse un golpe en la frente, y embriagado de gozo:\"},{\"heading\":false,\"text\":\"--¡Nos hemos salvado! --dijo.\"},{\"heading\":false,\"text\":\"Y corrió en busca de una biblia que en el armario estaba, mientras don Sindulfo se mesaba los cabellos de desesperación al presentir su derrota.\"},{\"heading\":false,\"text\":\"--Mirad --insistió el políglota leyendo en el libro--. «Capítulo XVI del Éxodo. Israel vino a parar en el desierto de Sin que está entre Elim y Sinaí.» Donde nos hallamos nosotros.\"},{\"heading\":false,\"text\":\"--¿Y bien? --preguntaron los circunstantes atónitos al contemplar que envueltos en la lluvia caían por la claraboya centenares de pájaros animando el laboratorio con sus voces y aleteos.\"},{\"heading\":false,\"text\":\"--«Y vinieron codornices que cubrieron el campamento, el cual se llenó también de un rocío que los israelitas llamaron maná.»\"},{\"heading\":false,\"text\":\"--¡El maná! ¡Bendito sea Dios!\"},{\"heading\":false,\"text\":\"Y todos se hincaron de rodillas.\"},{\"heading\":false,\"text\":\"--¿Y ahora persistirá usted en su criminal proyecto? --preguntó Luis a su tío.\"},{\"heading\":false,\"text\":\"--Y la peregrinación duró cuarenta años --interpuso Juanita--. Con que de aquí a que se nos acaben las provisiones, tiempo le queda a usted de ver cómo se arrullan.\"},{\"heading\":false,\"text\":\"--En vano es luchar --exclamó el tutor vencido y humillado--. Llevadme adonde os plazca.\"},{\"heading\":false,\"text\":\"--A la tierra de Noé en el Ararat --gritó Benjamín.\"},{\"heading\":false,\"text\":\"--Sea --balbuceó el sabio; pero por lo bajo añadió: «Todavía puedo vengarme».\"},{\"heading\":false,\"text\":\"Y los excursionistas, después de recoger abundante cantidad de aquel pan del cielo y de reconfortar sus perdidas fuerzas, obligaron a don Sindulfo a dejar desembarazados los movimientos del Anacronópete, encerrándole luego por precaución en el cuarto de los relojes para no verse expuestos a algún nuevo rapto de locura.\"},{\"heading\":false,\"text\":\"--Que nadie ce coma laz plumaz de laz codornicez que han de cervir para hacerle un plumero al zabio.\"},{\"heading\":false,\"text\":\"--¿No se lo decía yo a usted, señorita? --observó Juana--. Nosotros somos como los tentetiesos; aunque nos tiren de cabeza, siempre caemos de pie.\"},{\"heading\":false,\"text\":\"Y el Anacronópete emprendió su majestuosa marcha sobre el pueblo escogido por Dios, al que aún tuvieron ocasión de ver atravesando el mar Rojo a pie enjuto mientras sus aguas, uniéndose tras él, abrían ancha tumba a los ejércitos del cuarto Amenophis.\"}]},{\"title\":\"El anacronópete — capítulo xx\",\"blocks\":[{\"heading\":false,\"text\":\"El mejor, no porque sea el más bueno, sino por ser el último\"},{\"heading\":false,\"text\":\"Sesteaban tranquilamente los pastores mientras el ganado se esparcía por la falda de la montaña o por las laderas de dos ríos que, al cruzar sus brazos, parecían decirse estrechamente adiós como si presintieran que en su curso iban a separarse para no volver a reunirse nunca.\"},{\"heading\":false,\"text\":\"Los labradores en el valle, congregados en familia, dormitaban bajo sus tiendas, soñando tal vez al resguardarse de los rayos del sol, en el botín que la noche les reservaba en el ataque de la vecina tribu.\"},{\"heading\":false,\"text\":\"La mujer, reducida en aquellos tiempos a la condición de animal, el menos mimado del hombre, aderezaba las pieles que habían de servir de envoltura al fornido Triptolemo y al infatigable Nemrod, o disponía el tasajo con cuyos restos, disputados a los canes, se la premiaba el ejercicio de la maternidad.\"},{\"heading\":false,\"text\":\"Dominando el campamento sobre una no muy elevada colina, alzábase la tienda del jefe, donde este y los ancianos organizaban el pillaje y resolvían las diferencias de la tribu con veredictos que nada tenían de común con la justicia.\"},{\"heading\":false,\"text\":\"El descenso del Anacronópete en aquel risueño valle, produjo en la nómada multitud la extrañeza supersticiosa y cobarde que en la ignorancia infunde siempre lo desconocido. Al despertar sobresaltados por el aviso de los vigías, todos apercibieron sus hondas, empuñaron sus cayados y corrieron adonde el consejo estaba reunido para preguntar tumultuosamente si era al ataque o a la defensa a lo que debían disponerse.\"},{\"heading\":false,\"text\":\"Aunque la caída del vehículo tenía algo de sobrenatural a sus ojos, y los trajes de los expedicionarios aumentaban su confusión, la exigüidad del número con relación a la tribu restableció la confianza y se determinó dejarlos avanzar para despojarlos en sazón oportuna y repartirse las mujeres entre los que más se distinguieran por la noche en el rebato del aduar enemigo.\"},{\"heading\":false,\"text\":\"En aquel momento una negruzca nube, que poco antes empezara a subir por el horizonte, llenó el valle de sombras y descargó en lluvia torrencial.\"},{\"heading\":false,\"text\":\"--¡Ah de la tienda! --gritó Benjamín al llegar con los suyos a la de los ancianos.\"},{\"heading\":false,\"text\":\"--Me parece que también aquí van a recibirnos con tanto gusto como al casero --murmuró Juanita al ver la actitud de la gente.\"},{\"heading\":false,\"text\":\"--¿Por qué venís a turbar el sosiego de nuestro campo?\"},{\"heading\":false,\"text\":\"--Somos viajeros errantes y pedimos hospitalidad.\"},{\"heading\":false,\"text\":\"--Pagadla.\"},{\"heading\":false,\"text\":\"--Ved nuestra extenuación --prosiguió el políglota--. Reconfortad con algún alimento nuestras perdidas fuerzas.\"},{\"heading\":false,\"text\":\"Y la verdad es que, hartos de codornices, los excursionistas deseaban adquirir a cualquier precio una cazuela de modestas sopas de ajo.\"},{\"heading\":false,\"text\":\"--Trocadlo por vuestras vestiduras --repuso el jefe--. Aquí no se da nada sino por algo.\"},{\"heading\":false,\"text\":\"Convenido el trueque, se transmitió la orden de servirles leche, frutas y un par de recentales.\"},{\"heading\":false,\"text\":\"Entre tanto la tempestad seguía rugiendo y el eco de las descargas eléctricas repercutía en el valle con imponente fragor.\"},{\"heading\":false,\"text\":\"--Mirad, mirad esa colección de ancianos venerables --repetía Benjamín dominado por su idea y contemplando con éxtasis la ratificación de sus esperanzas en aquellas cabezas cubiertas de nieve--. Decidme si no son ellos los que poseen el secreto de la inmortalidad.\"},{\"heading\":false,\"text\":\"--¿Cuántoz añoz tiene usted, abuelo?\"},{\"heading\":false,\"text\":\"--Quinientos setenta y cinco --repuso el interpelado al enterarse por Benjamín de la pregunta de Pendencia.\"},{\"heading\":false,\"text\":\"--Gemelo de usted --dijo Juanita a don Sindulfo que, absorto y reflexivo, solo dejaba escapar una sonrisa de satisfacción cada vez que el rayo iluminaba la tienda con su cárdena luz.\"},{\"heading\":false,\"text\":\"--Puez habrá usted conocido a Mahoma.\"},{\"heading\":false,\"text\":\"--Creo prudente, don Benjamín --observó el capitán de húsares--, que mientras disponen los alimentos, aclare usted su enigma a fin de emprender el rumbo hacia nuestras tierras.\"},{\"heading\":false,\"text\":\"--Sí... voy a realizar mi sueño dorado.\"},{\"heading\":false,\"text\":\"Temblando de emoción y rodeado de sus compañeros que, después de tantos peligros, esperaban saborear las delicias del triunfo, el paleógrafo sacó los cordeles encontrados en Pompeya, y enseñándoselos avaramente al jefe de la tribu:\"},{\"heading\":false,\"text\":\"--A ver --le dijo-- si podéis descifrarme esta escritura de que solo me ha sido dado interpretar los primeros caracteres.\"},{\"heading\":false,\"text\":\"Todos los circunstantes contenían la respiración. El cinco veces centenario patriarca repasó los nudos entre sus dedos y, lanzando una carcajada estrepitosa:\"},{\"heading\":false,\"text\":\"--¡Mirad! --exclamó haciendo circular el _documento_ entre los suyos que con irreverentes signos de desprecio hicieron coro a la hilaridad del anciano.\"},{\"heading\":false,\"text\":\"--¿Pero en suma?... --preguntó Benjamín con desconcierto.\"},{\"heading\":false,\"text\":\"--Esto son tonterías del soñador Noé: consejos que ha repartido por todas las tribus para curarnos de lo que él llama la corrupción de los hombres.\"},{\"heading\":false,\"text\":\"--¿Qué? --interrumpieron los circunstantes presintiendo algún desengaño.\"},{\"heading\":false,\"text\":\"--Él sabe que nosotros no nos acomodamos sino con el robo, el pillaje y el escándalo, y pretende que Dios, a quien no conocemos, va a castigarnos con sus iras.\"},{\"heading\":false,\"text\":\"--No parece que os haya escarmentado el Diluvio --objetó Benjamín ante aquella tan paladina como desvergonzada confesión.\"},{\"heading\":false,\"text\":\"--¿El Diluvio? No sé. Nosotros venimos de luengas tierras.\"},{\"heading\":false,\"text\":\"--¿Pero no habéis experimentado una inundación general?\"},{\"heading\":false,\"text\":\"--No en mis días.\"},{\"heading\":false,\"text\":\"--Bien hice yo en sostener en el Ateneo que el cataclismo no había sido universal. En fin; volviendo a nuestro asunto, aquí dice: «Si quieres ser inmortal, anda a la tierra de Noé y»...\"},{\"heading\":false,\"text\":\"--«Y él --prosiguió el viejo interpretando la escritura-- enseñándote a conocer a Dios te dará la vida eterna.»\"},{\"heading\":false,\"text\":\"Los expedicionarios no pudieron reprimir un movimiento de indignación contra Benjamín, al ver reducido a un precepto moral lo que ellos acariciaron como receta empírica. Todo se explicaba perfectamente: los cordeles transmitidos a varias generaciones habían sido enterrados bajo la estatua de Nerón por algún cristiano habitante de la Campania deseoso de eludir las persecuciones del siglo primero; y el occidental refugiado en China, descendiente suyo e iniciado en el secreto, se había introducido en Ho-nan para difundir la doctrina del Salvador anteponiéndose a las gloriosas conquistas de las misiones católicas en el extremo Oriente.\"},{\"heading\":false,\"text\":\"--¿De modo?... --balbuceó el políglota ruborizado...\"},{\"heading\":false,\"text\":\"--Que nos ha hecho usted pasar las de Caín --repuso Juanita-- para aprender lo que desde chiquitines sabíamos ya por el catecismo del Padre Ripalda.\"},{\"heading\":false,\"text\":\"--¡Ci zon uztedes doz zabioz de cimilor!...\"},{\"heading\":false,\"text\":\"Las pullas y las diatribas no hubieran tenido fin sin una detonación espantosa que, pareciendo conmover hasta los cimientos del mundo, produjo un silencio de muerte.\"},{\"heading\":false,\"text\":\"La lluvia se despeñó de golpe como si cataratas la vomitasen, y todos por instinto trataron de salir de la tienda; pero un vigía penetrando en ella con la mirada errante:\"},{\"heading\":false,\"text\":\"--¡Salvaos! --dijo con terror--. El firmamento se desgaja; los ríos han roto sus barreras y el valle ha desaparecido bajo las hondas encrespadas de un mar de espuma. ¡A la montaña!\"},{\"heading\":false,\"text\":\"--¡A la montaña! --gritó la tribu desapareciendo al par que la tienda: aquella impelida por el pánico; esta arrebatada por el huracán.\"},{\"heading\":false,\"text\":\"Las mujeres, perdiendo el sentido, impidieron emprender la fuga a los anacronóbatas, que con espanto veían flotar los cadáveres sobre las aguas, ganar los vivos las alturas, iluminar el espacio sierpes de fuego, y sobre el negro fondo del horizonte subir el nivel de aquella rugiente masa líquida hasta lamer la cúspide del montículo que les servía de base.\"},{\"heading\":false,\"text\":\"--¡Valiente chaparrón, caballeroz! ¿Ci cerá el Diluvio?\"},{\"heading\":false,\"text\":\"--Imposible --dijo Benjamín--. Aquella catástrofe tuvo lugar en el 3308 antes de Jesucristo y nosotros hemos hecho alto en el 2971 o sea 337 años antes.\"},{\"heading\":false,\"text\":\"--¿Y mi venganza? --vociferó don Sindulfo con la alegría de una satánica satisfacción.\"},{\"heading\":false,\"text\":\"--¿Cómo?\"},{\"heading\":false,\"text\":\"--Me habéis encerrado como una fiera en el cuarto de los relojes y yo los he retrasado para que, dirigidos por un falso cómputo, seáis víctimas conmigo de esta conflagración universal.\"},{\"heading\":false,\"text\":\"Un rugido prolongado sucedió a las palabras del implacable loco. La situación era insostenible; las aguas desprendían bajo los pies de los viajeros las piedras de la colina, y la oscuridad era tan profunda que a dos pasos no se distinguían los objetos. Las fuerzas de Luis cedían al peso de su preciosa carga. Ello no obstante trató de subir hasta la punta del promontorio; pero una ráfaga le derribó y Clara desasida de sus brazos sepultóse en el abismo.\"},{\"heading\":false,\"text\":\"--¡Dejarme a mí que nado como un boquerón! --dijo Pendencia y se arrojó al agua; pero al caer, sin lastimarse gracias a la inalterabilidad, en vez de sumergirse en un cuerpo líquido dio con el inanimado de Clara tendido sobre una superficie sólida y dura. Un manojo de rayos iluminó el firmamento, y a su resplandor pudo el intrépido soldado medir la inagotable bondad de la Providencia, enviándole en un grito agudo todo un himno de alabanza.\"},{\"heading\":false,\"text\":\"--¡El cangrejo! --exclamó reconociendo el Anacronópete y recordando su condición retrógrada.\"},{\"heading\":false,\"text\":\"Era en efecto el vehículo, que arrastrado por la corriente flotaba sobre las olas junto a aquella colina que de tumba se había trocado en embarcadero.\"},{\"heading\":false,\"text\":\"Don Sindulfo, con los ojos inyectados en sangre, fue el primero en penetrar en él ciego de cólera.\"},{\"heading\":false,\"text\":\"El trasbordo se verificó sin dificultad por la galería que recibiera a Clara y al asistente, y unos segundos más tarde los expedicionarios, hendiendo aquella cortina de agua y fuego, seguían su curso navegando por la más diáfana y apacible de las atmósferas primitivas.\"},{\"heading\":false,\"text\":\"Ocupados en prestar auxilios a las enfermas y preocupados con la duración del síncope, todos advirtieron que andaba; pero a nadie se le ocurrió preguntar quién había puesto en actividad al coloso. Luis, ante el temor de que su pobre tío cometiese por razón de su estado alguna nueva imprudencia, le puso cuatro centinelas de vista señalándole otros tantos pies cuadrados de zona de movimiento fuera del alcance del mecanismo.\"},{\"heading\":false,\"text\":\"En las primeras horas se desconfió de salvar a aquellos exánimes seres harto resistentes hasta entonces a tantas vicisitudes; pero la juventud suele acordarse en medio de sus derrotas del indisputable derecho que la asiste a la vida, y provoca crisis tan rápidas y absolutas como la que a nuestras simpáticas viajeras devolvió el uso de sus facultades.\"},{\"heading\":false,\"text\":\"Abrazado que se hubieron como hacían después de haber corrido algún gran peligro, por cuya razón paréceme que si no los deseaban tampoco los temían, nadie pensó sino en la felicidad que al regreso les esperaba.\"},{\"heading\":false,\"text\":\"--¡Ah! --decía Juanita--. Cuando yo vuelva a oír pregonar por Madrid la _Correspondencia_...\"},{\"heading\":false,\"text\":\"--Nada, nada: cada oveja con zu pareja. Uzté, capitán, con la ceñorita; don _Pichichi_ con la emperatriz y yo con la doncella (perdonando el modo de ceñalar) --con lo que se refería a un cariñoso golpe que le había dado en la espalda a la de Pinto-- noz vamos a la parroquia, noz echa el cura el garabato y a vivir.\"},{\"heading\":false,\"text\":\"--A este paso no tardaremos en llegar --adujo Luis.\"},{\"heading\":false,\"text\":\"Entonces fue cuando el políglota fijó mientes en la vertiginosa rapidez que llevaban; pero ignorando si la imprudencia estaba de su parte, se calló limitándose a consultar los relojes que con gran asombro suyo encontró desmontados y con las manillas fijas en el año 3308, época del Diluvio que habían traspuesto hacía seis horas.\"},{\"heading\":false,\"text\":\"--¿Qué es esto? --se preguntó alarmado. Y abriendo uno de los discos del laboratorio, trató de reconocer la posición. Aquello era horrible; las alternativas de luz y sombra se sucedían como las vibraciones de un timbre eléctrico en que la transición del sonido al silencio no deja espacio perceptible. De vez en cuando el Anacronópete suspendía su marcha; diríase que se procuraba algún reposo, tras del cual, nuevo Judío Errante, emprendía su curso como si una voz oculta le gritase: «Anda.» Aprovechando estos fenómenos, para él incomprensibles, Benjamín con la vista clavada en el telescopio asistía al desfile de la descomposición de la naturaleza. Ora, al cruzar la antigua Hélade, robaba sus secretos a la mitología apercibiéndose de que los cíclopes no eran más que los primeros explotadores de las minas bajando a las entrañas de la tierra con una linterna en la frente, convertida por los poetas en un ojo; ya al cortar los confines del Asia y de la América, sorprendía que los siberianos habían sido los pobladores de las regiones descubiertas por Colón, pues los veía atravesar en caravanas, lo que entonces era un istmo, abierto más tarde por las aguas para formar el estrecho de Behring; el Mediterráneo no existía; los Alpes eran una llanura; el desierto de Lybia un mar. Tras los hijos de Caín, aparecía el cadáver de Abel: después del Paraíso la Creación...\"},{\"heading\":false,\"text\":\"Una carcajada sacó a Benjamín de su estupor: era don Sindulfo que, recreándose en el asombro del arqueólogo, gritaba en el paroxismo de la locura:\"},{\"heading\":false,\"text\":\"--Habéis provocado mi venganza y yo no cejo en la empresa.\"},{\"heading\":false,\"text\":\"--¿Qué? --exclamaron todos presintiendo alguna nueva desventura.\"},{\"heading\":false,\"text\":\"--Creíais caminar hacia adelante, y ya veis que seguís retrocediendo.\"},{\"heading\":false,\"text\":\"--¿Pero aquí no se acaban las tribulaciones? --decía Juana.\"},{\"heading\":false,\"text\":\"--Ce noz orvidó trincarlo.\"},{\"heading\":false,\"text\":\"--Cambiemos de rumbo.\"},{\"heading\":false,\"text\":\"--Sí.\"},{\"heading\":false,\"text\":\"--Es inútil --prosiguió el loco con sus carcajadas convulsivas--. ¿No observáis que viajamos con una velocidad quintuplicada? No hay quien nos detenga: he destruido el regulador, y el Anacronópete disparado corre a precipitarse en las masas candentes primitivas.\"},{\"heading\":false,\"text\":\"--¡Horror!...\"},{\"heading\":false,\"text\":\"--La muerte nos espera a todos en el caos.\"},{\"heading\":false,\"text\":\"--¡El caos!\"},{\"heading\":false,\"text\":\"--Mirad.\"},{\"heading\":false,\"text\":\"Y en efecto; a través del disco brillaba una tenue luz, principio del orden de la naturaleza y fin de la confusión de los elementos; pero, al retrogradar, la masa caótica iba espesándose gradualmente, y el grueso vidrio no alcanzaba a resistir los aluviones de agua, tierra y fuego que, agitados por el aire suspendían a intervalos y con violentos choques el empuje del vehículo flotante en aquel barro incandescente. La inalterabilidad había perdido sus propiedades; la asfixia se apoderaba de los viajeros, por el calórico desprendido de las paredes; hasta que por fin el cristal fundido, dando paso a un torrente de sustancias ígneas, ¡¡¡se abrió con el estampido de cien volcanes!!!...\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Era el público del teatro de la _Porte Saint Martin_ que, concluida la representación de una comedia de Julio Verne, premiaba la inventiva del autor. Juanita con Pendencia y los agregados militares enviados por nuestro gobierno a la exposición de París, ocupaban unos asientos de galería. Clara, casada desde la víspera con Luis, compartía con este las miradas de los curiosos en un palco de proscenio, acompañada de su tutor y de su inseparable amigo el arqueólogo, parte integrante de la existencia de don Sindulfo desde que perdió a la muda en las playas de Biarritz, y atraídos ambos a la Babilonia moderna por el aliciente del universal concurso.\"},{\"heading\":false,\"text\":\"Ya se comprende lo demás: el tutor se había dormido y había soñado. Cuando por el camino contó el sueño a su familia, todos rieron grandemente; lo que dudo mucho que haya acontecido a mis lectores con este relato. Y no obstante hay que reconocer que mi obra tiene por lo menos un mérito: el de que un hijo de las Españas se haya atrevido a tratar de deshacer el tiempo, cuando por el contrario es sabido que _hacer tiempo_ constituye la casi exclusiva ocupación de los españoles.\"}]},{\"title\":\"Viaje a China — Macao, 26 de septiembre de 1878\",\"blocks\":[{\"heading\":false,\"text\":\"Querido amigo: A las diez en punto de la mañana del 11 de agosto, el vapor _Tigris_, de las Mensajerías Marítimas, largó sus amarras, y como flecha salida del arco, se desprendió de Marsella con rumbo al extremo Oriente.\"},{\"heading\":false,\"text\":\"Todos tus lectores saben sin duda lo que es un barco; pero pocos habrán estado a pupilo en uno correo durante treinta y ocho días, y por si alguno llegara a necesitar ese hospedaje, allá van unos cuantos informes sobre el particular.\"},{\"heading\":false,\"text\":\"Los buques tienen su fisonomía como las personas; pero como en ellas, el cruzamiento de razas influye en la alteración de las facciones. No sé si la estética naval o la conveniencia indujo, no hace mucho, a los ingleses a suprimir el tajamar en sus _steamers_, y naturalmente, del comercio de sus astilleros con las naciones marítimas, resultó una generación de buques chatos que se pasea por los mares con los quevedos en la frente, puesto que los dos vigías de proa ya no encuentran narices sobre qué cabalgar. El _Tigris_, harto viejo para someterse a las exigencias de la moda, conserva aún su cartílago nasal, y hace bien, pues tengo para mí que en cuestiones de navegación, tan indispensable es el olfato como la vista.\"},{\"heading\":false,\"text\":\"La patrona de estos pupilajes, que se llama _Agencia general_, y que tiene sucursales en las cinco partes del mundo, reside en Marsella, y le indica a uno el cuarto que puede ocupar en tal o cual de las nueve casas que desde la _Joliette_ hasta _Shang-hai_ tiene en aquel momento disponible; y he aquí lo que por 52 francos y 50 céntimos al día puede exigir el huésped.\"},{\"heading\":false,\"text\":\"Una de las dos camas de que se compone cada camarote y los accesorios correspondientes a un cuarto-tocador con ropa; un camarero; baño diario, caliente o frío; un peluquero; el derecho de usar como costureras a las camareras destinadas al servicio de señoras; un médico; un boticario; cuarenta fogonistas, africanos, en su mayor parte salidos del golfo de Adén, encargados de alimentar los hornos; un primer maquinista y cuatro segundos; dos cocineros con sus marmitones correspondientes; un _maître d’hôtel_ y doce criados para las mesas de primera y segunda; cerca de cuarenta chinos para el servicio secundario, entre los cuales algunos _boys_ (voz inglesa que significa muchacho o criado de distinción), consagrados a agitar _las pancas_ de que hablaré a su tiempo; un capitán de armas conservador de las de a bordo, y con el deber de cerrar las escotillas de los camarotes cada vez que al mar se le hinchan las narices y amenaza invadir el buque por la menor abertura; despenseros; carniceros; un repostero; sobre cincuenta tripulantes para poner y quitar las cortinas de los balcones, según el viento que sopla; un agente de correos; un comisario, a cuyo cargo corre la administración general, pago de haberes, compra de provisiones y que recibe las quejas de los inquilinos si alguna tienen que formular; no sé cuántos timoneros; tres oficiales y un segundo capitán, salidos del cuerpo de pilotos, cada uno de los cuales hace el servicio de puente durante cuatro horas, lo que en lenguaje técnico se llama _el cuarto_, y por último, un comandante, por lo común teniente de navío de la marina de guerra, jefe nato de todo el personal, y por decirlo así, intendente de la casa.\"},{\"heading\":false,\"text\":\"De paso, y como detalle, te diré que el carbón que se gasta diariamente a bordo se eleva a 50 toneladas, que, a 60 francos una como mínimum, representa una suma de 3.000 por día.\"},{\"heading\":false,\"text\":\"Pasemos a la alimentación.\"},{\"heading\":false,\"text\":\"A las seis y media de la mañana empiezan los desayunos de café solo o con leche, té, chocolate, pan con manteca, una copa de vino generoso u otra bagatela por el estilo. A las nueve y media se sirve el almuerzo, compuesto de cuatro _hors d’œuvres_, como sardinas de Nantes, salchichón, agujas u otro pastelillo de carne, huevos, manteca, ostras, langostinos, etc., etc., a los que siguen dos platos fuertes de cocina, tan abundantes como variados, y el indispensable _karrick_ (arroz con salsa muy cargada de pimienta), terminándose con un surtido postruario y una taza de café. Las libaciones se hacen con vino tinto francés, Marsala, Jerez seco, cerveza y coñac. También hay agua.\"},{\"heading\":false,\"text\":\"Cuanto sale de este programa se paga a parte.\"},{\"heading\":false,\"text\":\"«Y ya me tiene usted como un reloj», diría el _caballero particular_, hasta las doce y media, hora en que se sirve el _tiffin_, palabra con que se designa en Asia el _tente en pie_, que en Europa llaman los ingleses y sus adeptos _lunch_, y que consta de caldo, salchichón, pollo o carnes fiambres, queso, sandwiches, vino, cerveza, refrescos de limón y brandy, y otras menudencias. Concluido el _tiffin_, ya no se yanta nada más... hasta las cinco y media, en que la campana vuelve a congregar a los pasajeros en el refectorio para la comida. Afortunadamente esta es ligera: una sopa, un _relevé_, cuatro suculentas entradas, dos asados (de ave y de carne), ensalada, _karrick_, un plato de legumbres, dos _entremets_ o platos dulces, uno de los que muy a menudo es sustituido por un rico helado, queso, frutas frescas y secas, pastas, café, pan, vinos y licores.\"},{\"heading\":false,\"text\":\"Y ya no toma uno otra cosa hasta las ocho y media. Entonces, con el pretexto de la taza de té, se paladea un bombón por aquí, se engulle una galleta por allá, se discute y se prueba experimentalmente que el sandwich es mejor por la noche que por la mañana; y con una limonada ahora, un vaso de cerveza poco después y un _grog_ más tarde, dan las diez de la noche, y las mandíbulas se entregan al reposo, para emprender de nuevo su tarea al romper el alba, ni más ni menos que un peón de albañil, sin domingos ni fiestas de guardar.\"},{\"heading\":false,\"text\":\"A propósito de fiestas, te diré que estas no se solemnizan, por no haber a bordo sacerdotes; y que habiendo preguntado la causa de esta omisión, se me contestó, y me convencieron, que de establecer en los vapores un presbítero católico, había que dar cabida en ellos, por equidad, a un pastor protestante, a un _papa_ griego, a un derviche musulmán, a un bonzo chino y a tantos otros encargados de los diferentes cultos con que los hombres interpretan la idea de la Divinidad.\"},{\"heading\":false,\"text\":\"Las diversiones y los espectáculos se dividen en naturales y técnicos. Son naturales el _whist_ y el ajedrez; el piano y canto, prodigados generalmente por los que menos aptitudes deben a la madre naturaleza y al arte auxiliar; el mareo desde la palidez, su primer síntoma en ambos sexos, hasta la abstinencia del tabaco en el hombre y la descompostura e impudibundez sin conciencia en las señoras; el rodar sobre cubierta de los pasajeros con sus sillas en días de marejada; los equilibrios y el cojeo de aquellos valientes que se pasean por vanidad, y a quienes al echar el pie les falta el barco; el pajarito que vuela, el pez que salta, el buque que se divisa, el promontorio que sale de las aguas, el panorama del puerto a que se arriba, y el ridículo tocado con que el europeo se disfraza por estas latitudes, y que contrasta con el traje negativo de la mayor parte de los indígenas asiáticos.\"},{\"heading\":false,\"text\":\"Constituyen los técnicos las maniobras de la marinería, que los pasajeros experimentados explican a los novicios con gravedad cómica y en detrimento de la exactitud la mayor parte de las veces; las noticias geográficas, hidrográficas y etnográficas con que el viajero se enriquece, gracias a la amabilidad de los oficiales; el lenguaje de las banderas y de las luces; las de Bengala con que se saludan por la noche al cruzarse dos vapores de la misma compañía, y que, tomadas por un incendio a bordo, hicieron salir de su camarote a cierta señora tan despavorida, como ligera de ropa, enhebrada en un enorme salva-vidas de cerca de dos varas de diámetro; la revista de inspección que el domingo pasa el comandante, seguido de su estado mayor, a todo el personal, vestido de gala y formado en su puesto; el simulacro de fuego a bordo que se hace cada jueves y en el que, al minuto de dar la campana la señal de alarma, todo tripulante debe hallarse en su destino, la bomba funcionando, el doctor en la farmacia y las camareras preparando hilas y vendajes; por último, el zafarrancho de combate que, una vez en el viaje de ida y otro en el de vuelta, se simula para el horrible caso de abandono del buque, y que se practica tomando cada oficial el mando de un bote cuyas amarras hace picar, y saliendo primero el más joven con los niños, después el que le sigue en edad con las mujeres, el tercero con los viejos, y los sucesivos con el resto de la tripulación: todos los oficiales, armados de revólveres, tienen la consigna de levantar la tapa de los sesos al que no se someta a la disciplina del caso.\"},{\"heading\":false,\"text\":\"_¡Delisioso!_ como diría el capitán de la zarzuela _Robinson_.\"},{\"heading\":false,\"text\":\"Y enterado ya de lo que es el domicilio flotante y de la vida que en él has de llevar, pasemos a lo que podrás ver, si te da la ocurrencia de venir a hacerme una visita; para lo cual principias por gastarte dos mil francos para meterte como un libro en el estante de una biblioteca; y una vez encasillado, si el mareo no te vuelve tísico, o la diferencia de climas no te mata, ni te asfixia el mar Rojo, ni la nostalgia te impele a suicidarte, ya estás seguro de que a menos de que la máquina estalle, o se declare una manga de agua que sumerja el buque, o que haya un incendio a bordo, o que otro barco aborde el tuyo, o que un error de cálculo en una noche oscura te haga estrellar contra una roca, o que el mistral te quiera guardar en el Mediterráneo antes de que el Monzón pueda engullirte en el Océano Índico o devorarte un tifón en el mar de la China, ya estás seguro, repito, de llegar sano y salvo a Hong-Kong y poder exclamar al pisar sus playas: «Me separan de mi casa treinta y ocho días de mar y tres de tierra, descompuestos en tres mil leguas de veinte al grado. Aquí son las ocho de la noche y en mi patria apenas si será medio día: me hallo en pleno Celeste Imperio y he hecho la mitad de la vuelta al mundo: escribiré mi llegada a la familia y antes de tres meses tendré la contestación, si la manda a correo seguido.»\"},{\"heading\":false,\"text\":\"Créeme, llévate pañuelo, porque si no tendrías que secarte más de una lágrima con el dorso de la mano.\"},{\"heading\":false,\"text\":\"En fin, no pensemos más en ello; el comandante sobre el puente, grita con voz de trueno: «_Larguez tout: en avant_», y las amarras se divorcian de los bitones.\"},{\"heading\":false,\"text\":\"Partamos.\"}]},{\"title\":\"Viaje a China — Macao, 8 de octubre de 1878\",\"blocks\":[{\"heading\":false,\"text\":\"Querido amigo: No me exijas que entre en un análisis profundo de las cosas que vamos a ver. Recuerdo aún la sorpresa que me produjo siendo niño, y ya empieza a ser larga la fecha, el primer prestidigitador que admiré en un teatro, y el desengaño que experimenté cuando, ya mozo, supe que tenían doble fondo las cajas; y desde entonces, siempre que puedo, me limito a la superficie, sin meterme en honduras, convencido de que la ilusión es más bella que la realidad.\"},{\"heading\":false,\"text\":\"Te convido, pues, a una función de fantasmagoría sin alardes de erudición, en la que, si errores cometo, no serán de trascendencia, puesto que no trato de producir enseñanza.\"},{\"heading\":false,\"text\":\"Pasemos el estrecho de Bonifacio, con la Córcega a un lado y la Cerdeña al otro. ¿Ves a la derecha una casita blanca con un toldo de pámpanos? Es la residencia de Garibaldi en Caprera. El brazo de la unidad italiana está allí para señalar enfrente al viajero la cuna de los Bonapartes.\"},{\"heading\":false,\"text\":\"Alborea el día 13 y fondeamos en Nápoles. Su extensa y hermosa bahía se baña de luz; los vendedores de objetos de coral y de lava invaden el _Tigris_, mientras los músicos ambulantes, metidos en lanchas, te saludan con sus cantos populares, llenos de poesía y ejecutados con una admirable precisión por jovencillas vivarachas de ojos de fuego, para quienes la música es como la palabra: no saben cuándo la aprendieron.\"},{\"heading\":false,\"text\":\"El vapor debe zarpar a las nueve, y no hay tiempo para visitar todo lo notable que encierra este primer punto de escala. Afortunadamente, yo la conozco desde mi regreso de Atenas y voy, aunque muy de prisa, a señalarte lo que más impresión ha de producirte.\"},{\"heading\":false,\"text\":\"Figúrate que desembarcamos a las seis de la tarde.\"},{\"heading\":false,\"text\":\"En primer lugar, tomemos un sorbete en casa de Benvenuto; es un tributo que hay que pagar al gran confeccionador de helados que tiene Europa. Por media lira, o sean dos reales, te sirven una como rodaja de queso de bola, de dos dedos de gruesa y en forma de media luna, que te deja recuerdo indeleble del nombre de _pezzi_ con que lo bautizan. De allí nos vamos al teatro de San Carlos, suntuoso edificio dirigido por un arquitecto español y academia en que se sanciona, como en la Scala de Milán, la fama de los artistas líricos.\"},{\"heading\":false,\"text\":\"Ya es media noche y el estómago pide que nos ocupemos de él; por consiguiente, en lugar de meternos entre las ahogadas paredes de un restaurant, nos vamos a _Santa Lucía_. Allí, a la orilla del mar, al aire libre, sobre magníficas mesas de mármol, alumbradas por globos de gas, unos criados vestidos de rigurosa etiqueta nos sirven pescado frito, langostinos y ostras frescas, que unas vendedoras muy jóvenes y bien ataviadas abren y preparan en elegantes casilicios alineados al borde del parapeto del muelle; y todo esto rociado con Salerno y Siracusa, y amenizado con las picarescas canciones de tanta Malibrán en flor y tanto Paganini degenerado como fecunda en aquella tierra privilegiada la lava del Vesubio.\"},{\"heading\":false,\"text\":\"Una carretela nos aguarda. Subamos a ella y sigamos la herradura de la bahía. Al cabo de dos horas de marcha, me preguntas admirado si aquella calle de Nápoles no acaba nunca; y tu asombro crece de punto al saber que hace más de una y media que hemos dejado la ciudad, y que aquella serie interminable de quintas, caseríos, _villas_ y hasta palacios, no son otra cosa que pueblecillos, jardines y granjas que se suceden sin interrupción ni intervalo desde Nápoles hasta _Reggio_, extremo occidental de la Italia en el estrecho de Mesina. Nosotros nos paramos en _Portici_, donde, a defecto de la _Muda_ del maestro Auber, encontramos a un locuaz arriero, que nos prepara las caballerías para la ascensión al Vesubio.\"},{\"heading\":false,\"text\":\"Larga y penosa esta, fuera del interés científico que puede despertar en un geólogo, no tiene otro encanto que la satisfacción de haber marchado sobre cenizas, la vanidad de haber tocado los bordes de su inmenso cráter y oído la bronca respiración de sus pulmones; y para el que, como yo, madruga poco, haber asistido a la iluminación del golfo por los primeros rayos del sol naciente. Plata en el mar, verde en la montaña, rojo en el horizonte, azul en el cielo, tornasoles en la ciudad, perfume en el ambiente, música en el espacio, luz en el aire. Tú, poeta, dispón en tu fantasía y como te dicte el sentimiento, los colores y los ruidos que te libro a granel; pero que son los verdaderos componentes de una alborada en Nápoles.\"},{\"heading\":false,\"text\":\"Desde allí, y por otra vertiente, las acémilas nos bajan a Pompeya, sepultada en el primer siglo de la era cristiana y descubierta en tiempo de Carlos III, de la que hoy se conoce ya todo el perímetro y más de tres cuartas partes de la ciudad están desenterradas. ¿Qué podré decirte de ella? Su orden arquitectónico te es bien conocido. Pues bien; imagínatela toda cortada a la altura del primer piso de sus casas y sin más que la planta baja en pie. Pórticos, vestíbulos, patios con fuentes microscópicas y detalles liliputienses, y detrás el gineceo o habitaciones para las mujeres; columnas estriadas como base de apoyo, mosaicos por adorno y el _cave canem_ inscrito en el suelo cerca de la perrera, como aviso prudente para las pantorrillas del visitante. Parece una ciudad cuyos moradores han salido para asistir a alguna fiesta cercana, y a cada momento crees que van a hacer irrupción en sus dominios. En su museo se admiran cosas sorprendentes: trigo y legumbres carbonizadas, pan cocido el día de la erupción, aceite metido en tinajas, joyas pertenecientes a los cadáveres, que se han encontrado envueltos en una capa petrificada de lava y azufre, y de los que han sacado vaciados en yeso, conservando la posición en que los sorprendió la muerte; papiros a los que se da cierta consistencia con una substancia química, y que colocados bajo una campana de cristal, se los sujeta a un aparato que desenvuelve dos milímetros por día, hasta que toda la hoja desarrollada, se la fotografía, y pegada a un cartón, pasa a enriquecer la biblioteca de manuscritos, más notable bajo el punto de vista de la curiosidad que de la historia. ¡Qué impresión al visitar aquel teatro donde resonó la musa de Plauto y de Terencio! ¡Qué movimiento de horror ante aquel circo, donde tantos gladiadores han apagado con su sangre la sed de espectáculos cruentos del pueblo latino! ¡Qué sobrecogimiento ante aquel foro, que Cicerón ha sabido llenar con su presencia cuando para reposar de las tareas de Roma, iba a solazarse durante el estío en la patricia residencia pompeyana! ¡Qué asombro al visitar aquellas termas, germen en un principio de salubridad y de higiene en una raza guerrera; fomentador más tarde de la corrupción y la molicie en aquellos imitadores de Capua! ¡Qué vergüenza en aquellos templos del amor, con sus lechos de mármol, sus estimulantes del deseo artísticamente pintados en las paredes, y su padrón de ignominia esculpido en la puerta como testimonio de la divinidad a que se rendía culto!\"},{\"heading\":false,\"text\":\"Las ruinas de Herculano son más importantes en el concepto del arte; pero lo difícil del descenso y la premura de nuestro viaje nos impiden ir a verlas.\"},{\"heading\":false,\"text\":\"Tomemos el tren, y atravesando vergeles llenos de quintas, con sus colgantes de macarrones puestos a secar en todas las ventanas (y de que el pueblo napolitano hace un inconcebible consumo, comiéndolos la gente baja con las manos y por madejas), volvamos a Nápoles, y a uña de caballo, echemos una ojeada al museo de Borbón. Vasto y suntuoso edificio; posee numerosos y notables cuadros; y en escultura se honra con el grupo de Farnesio; pero como no podemos apreciar una por una las bellezas que atesora, vamos a ceñirnos a una sola, aunque típica especialidad. Me refiero a la venta de copias de aquellos lienzos maestros, ejecutadas, no diré por artistas, mas sí por obreros del arte de Apeles que, a centenares, invaden las espaciosas crujías del palacio y asaltan al curioso con ofertas tentadoras y en competencia sin igual. Allá va un ejemplo para muestra: una copia de una Santa Familia del Sarto, midiendo media vara, tendida en un bastidor con cuñas, y aunque ligeramente tratada, representando un trabajo de tres sesiones por lo menos, me ha sido adjudicado en la suma de... ¡_una peseta_!\"},{\"heading\":false,\"text\":\"Y basta, que nos esperan a bordo. Atravesemos a escape la _Chioja_ y _Toledo_, las dos grandes arterias de la populosa Nápoles, el palacio real y la multitud de teatrillos que, como hongos, salen por todos lados; y mientras el _Tigris_ larga sus amarras, echemos unas monedas de cobre a esos buzos, que desde su lancha nos desean buen viaje. Míralos cómo se zambullen, cómo luchan en el agua, y cómo, por fin, el más hábil se presenta en la superficie, llevando en la boca los dos cuartos de la presea. Por fin, zarpamos; los músicos ambulantes entonan desde sus canoas una marcha, cuyos ecos se van debilitando poco a poco; la bahía parece como que se contrae, y la ciudad como que se repliega; ya un solo punto luminoso se ve en el horizonte: el Vesubio; después su aliento... después nada; el mar, tan imponente cuando aleja al viajero; tan juguetón y bullicioso cuando le vuelve a los suyos.\"},{\"heading\":false,\"text\":\"A las nueve de la noche, el _Stromboli_, como faro de las islas Líparis, se presenta por estribor, arrojando fuego de su cráter. A media noche, el vapor corre entre dos cordones de luces; son Mesina y Reggio; Scila y Caribdis. La Sicilia se borra por fin con la vaga silueta del Etna, y al otro lado la Calabria ulterior se pierde en las olas y se confunde en la bruma. Dos días después llegan hasta nosotros las brisas del archipiélago griego que, envidiosas de la isla de Candía, que nos sale al paso, trepan por sus ásperas montañas, y nos saludan con la más cariñosa de las sonrisas; y el 17, a las dos de la tarde, el vigía de Daimieta anuncia nuestra llegada a Puerto-Said. Estamos en África.\"},{\"heading\":false,\"text\":\"Instintivamente la mirada se vuelve hacia atrás como buscando algo que se lleva el agua al borrar la estela de nuestro barco. Es que acabamos de dejar una parte del mundo; la nuestra. ¡Adiós, Europa!\"},{\"heading\":false,\"text\":\"Hay dos itinerarios para llegar hasta el mar Rojo; el que seguimos nosotros y el que se hace desembarcando en Alejandría y tomando el ferrocarril que pasa por el Cairo y va a Suez. Este último es más largo, no por la duración del viaje, sino porque una vez en la capital del Egipto, ¿quién se vuelve sin visitar la Esfinge, la pirámide de Gizeh, las demás tumbas de los Faraones y lavarse en la corriente del Nilo?\"},{\"heading\":false,\"text\":\"He dicho que el viaje es más largo, _no por su duración_, y debo rectificar este aserto, pues según me han referido, parece ser que la locomoción ferrocativa de los _fellah_, hace de la lentísima española algo vertiginoso, como los convoyes de San Francisco de California a Nueva-York, pues entre otras causas hay la muy poderosa de que cuando al maquinista se le cae la petaca, o encuentra a un amigo que sigue a pie la ruta, para el tren, y recoge a una o a otro, sin que nadie le dirija cargos por ello.\"},{\"heading\":false,\"text\":\"Nosotros, ya puestos en la boca del canal, seguiremos la recta trazada por el inmortal Lesseps.\"},{\"heading\":false,\"text\":\"En Puerto-Said desembarcan los pasajeros para Beirut, Damasco, Esmirna, y toda la costa de Siria y Palestina, y en los que seguimos al extremo Oriente, empieza a verificarse la metamorfosis reglamentaria de trajes, usos y costumbres.\"},{\"heading\":false,\"text\":\"Lo primero es despojarnos de todo sombrero a la europea, y calzarnos el _hélmed_ (con _h_ aspirada); casco para el uso de los ingleses en la India, que le da a uno el aspecto de un cocinero de bomberos, en razón de la forma del utensilio y de la blanca funda que lo reviste. A este preservativo de la insolación sigue el aligeramiento de traje, como recurso contra los calores sofocantes que nos aguardan, y que consiste en la sustitución de la lanilla por el lino y el empleo de _la morisca_ por la noche. La morisca es un traje de algodón, compuesto de calzones anchos y blusa de manga perdida, que se viste con exclusión de camisa e interioridades equivalentes. A bordo da comienzo el consumo de arroz hervido, rociado con una salsa muy picante, de la que toma el nombre de _Kury_ para los ingleses, _Cary_ para los franceses, y que todos, indistintamente, llamábamos _Karrik_ en tono de broma, porque, como dicha prenda de vestir, servía de abrigo al estómago contra el desnivel de calórico producido por la transpiración. Las _pancas_, que son como unas bambalinas de lona pendientes del techo, forradas de algo que sin hacerlas pesadas las vuelva consistentes, y que se adornan con un volante al canto, son puestas en movimiento de vaivén por un chino que, desde el extremo del comedor tira de la cuerda que las une todas, y que es como la mano de aquellos abanicos, encargados de refrescar el aire a las horas de comer; o lo que es lo mismo, constantemente. Por último, se nos da la orden de dormir sobre cubierta, pues ha habido casos, como el de unas religiosas que por pudor se quedaron en el camarote, y amanecieron asfixiadas por la atmósfera de fuego que reina por las noches, principalmente en el mar Rojo.\"},{\"heading\":false,\"text\":\"Puerto-Said no tiene nada de notable, aunque su porvenir es inmenso; ciudad brotada de la apertura del istmo, no hay nada en ella, fuera del sol, que acuse el carácter oriental; todo está construido a la europea, si bien con arreglo a las exigencias locales; su faro recuerda los de los puertos franceses; su plaza de Lesseps es un pequeño _square_ a la inglesa; las casas, aun las más fastuosas, como la agencia de las mensajerías y las oficinas del canal, podrían pasar por quintas de recreo en los alrededores de Roma, o en la campiña de Pau; las tiendas, pobres en general, se parecen a las de una provincia de segundo orden de España.\"},{\"heading\":false,\"text\":\"Las calles, tiradas a cordel y a medio construir, son un remedo, en fin, de las modernas poblaciones. En ellas abundan los cafés cantantes con orquestas alemanas, billares, ruletas y demás entretenimientos. Pero lo que a Puerto-Said le falta como sello urbano, lo suple con creces con la diversidad de razas orientales que lo pueblan. Desde el negro del Sudán que en la barcaza conduce el carbón para _El Tigris_, hasta el chipriota que vende fotografías en el bazar, todo difiere de lo nuestro. Ya es el indolente mozo de cordel, que sucio y harapiento, acorta su miseria durmiendo en la arista de sombra que proyecta en la calle el alero de un tejado; ya el habitante de la Arabia pétrea, que con su túnica azul y su tabardo gris, ostenta sobre un fondo de luz los viriles y correctos contornos de una fisonomía abierta como el desierto; ya el beduíno de la fuente de Moisés, con la bruñida y negra faz, destacándose sobre el blanco y recogido turbante, y acariciando la espingarda, compañera de su soledad. Allí se codean la beduína de las montañas de Altaka, con la cara descubierta y llena de ajorcas y de joyeles, y la mujer fellah, de mirada incitante, que lanza rayos de sus pupilas por encima del velo que le cubre el rostro; el chek de la guardia nocturna, de rugosa frente y acusadas facciones, y el beduíno del monte Sinaí, con su turbante en punta y el torso desnudo; la dama turca y la esclava del Sudán; el derviche y el camellero, el hombre de mar y el de la montaña; el mercader, en fin, de bazar cubierto, y el hijo de los aduares; pero todo con tal perfume de Mahoma, con un sello tan marcado de _Corán_, que, para que la ilusión sea completa, hasta el cielo parece asociarse a nuestra causa, retrasando el plenilunio, y coronando en una luna creciente el inmenso turbante azul, bajo el que asoma la islamita fisonomía de Puerto-Said.\"},{\"heading\":false,\"text\":\"Volvamos a bordo. Aquí ya nadie canta como en Nápoles; pero todos gritan. El batelero no te transporta al _Tigris_ si antes no pagas al chek el precio del pasaje. El buhonero ya no vende baratijas de su confección, sino artículos de viaje traídos de Europa. El arte se acabó en Italia, para no volver a verlo. En Egipto la fuerza natural impera, pero con un carácter retrógrado a medida que avancemos. Con los primeros albores del día 18, el vapor se pone en marcha para entrar en el canal, admirable corrección hecha por la ciencia sobre el libro de la naturaleza, sublime puerta por la que la civilización va a invadir los dominios de la barbarie. Entremos.\"},{\"heading\":false,\"text\":\"Largamente debatida ha sido la cuestión de si en los tiempos antiguos existió o no un canal que ligaba el mar Mediterráneo al golfo Arábigo. Los que lo afirman, aducen como razón la presencia de los lagos en el istmo; lagos que, hábilmente utilizados por Lesseps, han facilitado notablemente su titánica empresa. Yo dejo al tiempo y a la ciencia que aclaren este punto, y limitándome a mi papel de cronista, relato lo que veo.\"},{\"heading\":false,\"text\":\"Para no andar buscando mapas, vamos a formarnos uno, que nos dé una idea aproximada del istmo de Suez. Apoyemos las dos manos de plano sobre una mesa y unamos los pulgares por sus extremos como para formar la cadena magnética, con la que dicen que se hacen girar los platos y los sombreros. La mano derecha representa el continente africano, la izquierda es el Asia. El vacío que resulta entre los pulgares y el pecho significa el Mediterráneo que, extendiéndose por la muñeca derecha (a la que supondremos cortada, para que nos haga el efecto del Estrecho de Gibraltar), toma, desde el lado opuesto de la misma muñeca hasta el extremo del meñique izquierdo, el nombre de Océano Atlántico.\"},{\"heading\":false,\"text\":\"El hueco desde los pulgares hasta los nudillos de los índices, es el mar Rojo o golfo Arábigo; y desde dichos nudillos hasta la extremidad de los dedos, el mar de las Indias.\"},{\"heading\":false,\"text\":\"Los pulgares, unidos, son la lengua de tierra que une al Asia con el África, y que, impidiendo que el Mediterráneo y el mar Rojo se junten, toma el nombre de istmo de Suez.\"},{\"heading\":false,\"text\":\"Cuando, antiguamente, un buque tenía que transportar mercancías a las Indias o a los puertos chinos colonizados por europeos, abordaba el Océano Atlántico, costeaba la punta de la mano derecha, y navegando después de índice a índice, estaba seguro de llegar en unos seis meses a su destino, cuando no tenía que detenerse un par de ellos, esperando viento favorable sobre la extremidad del anular derecho, conocido con el nombre de Cabo de las Tormentas o de Buena Esperanza.\"},{\"heading\":false,\"text\":\"Pero un día el orbe entero se conmovió. Era por los años 1820. Un inglés llamado Mr. Wagorne había imaginado el modo de hacer llegar el correo desde Europa a las Indias, ganando más de una mitad de tiempo. _Time is money_, gritó la Gran Bretaña; y la Mala inglesa quedó establecida de este modo: un buque de vapor conducía los paquetes desde Gibraltar hasta el nudillo del pulgar derecho, o sea Alejandría; desde allí, atravesando el dedo, o sea el istmo, el correo era llevado por tierra con graves riesgos y exposiciones, hasta el puerto de Suez, en la bifurcación del pulgar y el índice: y una vez en Suez, otro vapor de la compañía Peninsular y Oriental inglesa lo dirigía a su destino por el mar Rojo.\"},{\"heading\":false,\"text\":\"Era este un inmenso adelanto, y bien merecido tiene Mr. Wagorne el busto que la Compañía le ha levantado en el extremo del canal; pero la rapidez de la comunicación postal no hacía sino aguijonear la impaciencia del mercader que, si bien recibía la remesa con mucha antelación, no por eso las mercancías tardaban menos. En esto apareció Mr. de Lesseps, y esgrimiendo unas tijeras de gran temple intelectual y de muchos millones de coste, dio un corte en el istmo, hizo que dos mares, hasta entonces separados por dimes y diretes de una mala lengua de tierra, quedasen amigos hasta el extremo de vivir juntos, y ayudado por el vapor, logró que en la quinta parte del tiempo que un buque invertía antes en costear el África, pueda hoy el viajero trasladarse desde el Campo de Marte hasta Pekín.\"},{\"heading\":false,\"text\":\"El canal no es otra cosa que una inmensa zanja abierta en el istmo y que se ensancha de cuando en cuando por la presencia de los lagos Menzaleh, Ballah, Timsah y los Amargos. A derecha e izquierda el desierto con sus ribazos blancos de sal por la evaporación del agua. De distancia en distancia un _chalouf_ o estación de la empresa, donde un poco de tierra vegetal, llevada exprofeso, ha permitido que broten algunas plantas para solaz y entretenimiento del guarda y remembranza de la vegetación en la mente del viajero. Por rara casualidad, un árabe con la espingarda al hombro atraviesa aquellos arenales, veloz como el pensamiento y como huyendo de la soledad. En las horas en que el sol cae más a plomo, algún camellero, con cinco o seis de sus fieles rumiantes, busca saludable refugio cerca de la corriente de las aguas, tendido en la vertiente del talud. Constantemente el espejismo, produciendo extraños fenómenos de óptica. Ya son montículos de arena que, reflejados en la atmósfera, semejan islotes saliendo del fondo de un lago: ya es una ciudad con sus cúpulas y minaretes, que la realidad destruye y convierte en la reflexión de una bandada de grullas que dispersa el silbido del vapor. En el medio del canal, un verdadero oasis: Ismailía con el palacio del virrey, rodeado de palmeras, naranjos y bananeros. Un poco más lejos nos sorprende la noche; pero como la navegación está aquí prohibida fuera de las horas de sol, hacemos alto. Se respira plomo; las bujías del piano ostentan una llama fija e inmóvil sobre cubierta; estamos atracados junto al ribazo y nadie se atreve a desembarcar: hay fieras. Amanece el 19 y nos ponemos en marcha.\"},{\"heading\":false,\"text\":\"Tres horas después estamos en Suez. La ciudad, distante como una legua del puerto, se une a este por una faja de tierra echada sobre el agua, sin una piedra, sin un árbol, sin el menor pretexto de sombra. Pocos minutos después, el vapor sigue su rumbo y penetra en el mar Rojo.\"},{\"heading\":false,\"text\":\"La sacudida de la hélice repercute en el corazón del viajero, y de un solo latido de su frente, retrograda miles de años. Va a pasar de Mahoma a Moisés, del Corán al Génesis; de la leyenda árabe al dogma bíblico; del mórbido seno de la desnuda poesía, al severo y majestuoso pliegue de la túnica cristiana.\"}]},{\"title\":\"Viaje a China — Macao, 14 de marzo de 1879\",\"blocks\":[{\"heading\":false,\"text\":\"Mi querido amigo: Estamos atravesando el golfo de Suez; parece que, con solo extender los brazos, vamos a tocar al África por la derecha y al Asia por la izquierda. A un lado llevamos la tierra de los Faraones, el poema de José, el Nilo, cuna del gran legislador del pueblo Israelita; al otro el desierto, cuarenta años de peregrinación, Judea, el Jordán, Jerusalén.\"},{\"heading\":false,\"text\":\"¿Ves por babor aquel pequeño paraíso destacándose en medio del arenal de la Arabia pétrea? Es un grupo de palmeras y plátanos dando sombra a la fuente de Moisés, primer alto de los Israelitas después de pasar a pie enjuto el mar Rojo. Por la noche, el pico del monte Sinaí sale a recordarnos los preceptos del Decálogo. El mar se ensancha, bórranse las costas; pero la imaginación le hace adivinar a uno la proximidad de Medina, tumba del Profeta Mahoma, y los vapores que, hacinados de sectarios del Corán en caravana, se cruzan con el nuestro, nos señalan la situación de la Meca, la ciudad santa del islamismo.\"},{\"heading\":false,\"text\":\"Durante tres días el calor nos sofoca. Por fin, llegamos al estrecho de Bab-el-Mandeb, o puerta de los Suspiros, perfumada con el aroma de los cafetales de Moka. Destacado de la costa africana se ve un peñón; es Perrin, la primera portería del estrecho; aquel guardián habla inglés, y a guisa de llavero ostenta un variado y surtido manojo de cañones. Unas horas más tarde, al amanecer el día 24, otro inglés, con más cañones que el primero, nos abre, por decirlo así, la otra hoja de la puerta, y fondeamos en Adén, pequeño rincón de la Arabia feliz.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Los hijos de Albión han impuesto al mundo conocido la sacramental frase de las casas de Madrid: _Nadie pase sin hablar con el portero_. Inglaterra es el conserje universal. Desde su casa puede pasar revista a todo el que se proponga dirigirse por el mar del Norte a las regiones árticas. El estrecho de Gibraltar le permite husmear cuanto ocurre en el Océano y el Mediterráneo. Queda un boquete abierto entre la Sicilia y Túnez; lo tapa con Malta; y Constantinopla, sobre la que de hecho ejerce el protectorado, cierra la marcha de esta serie de mamelones, que forman la gran muralla marítima de la Europa. En el triángulo del África es dueña de los ángulos: Sierra Leona, el canal de Suez, en la forma de la mitad de sus acciones, y el Cabo. La América se halla prensada entre la Nueva-Bretaña, o Canadá, la Jamaica y las posesiones antárticas y las de la Oceanía; y por lo que al Asia respecta, empezando en Chipre, siguiendo por Adén (donde se convierte en oro el café de Moka y desde el que se escudriña todo el movimiento de la costa S. E. del África, del cabo Guardafui al de Buena Esperanza) y terminando en el estrecho de Bering, todo habla inglés y nada escapa a la vigilancia de la Gran-Bretaña. El Indostán, enclavado entre dos golfos, está defendido en el de Omán por Adén y la isla de Ceylán, y por esta y Singapore en el de Bengala; amén del refuerzo de la Australia para tener en jaque a toda la Malasia y la Micronesia en el Océano equinoccial; la Cochinchina no puede moverse entre la Península de Malaca y Hong-Kong; y por último, las concesiones otorgadas en Shang-hai, Tien-tsing y la costa de la China, llevan la influencia del Reino Unido hasta las regiones árticas en el estrecho de Davis, y puede decirse que la Inglaterra tiene al mundo metido en el bolsillo.\"},{\"heading\":false,\"text\":\"Pero hablemos de Adén. Allí dejamos a los viajeros que se dirigen a Zanzíbar, Mozambique, Madagascar, Mauricio y Borbón. Una serie de rocas peladas, sin más vegetación que una lujuriante de artillería de grueso calibre, sirve de asiento a la ciudad. Esta es una de las primeras fortificaciones del mundo; luego la visitaremos; antes fijémonos en lo que rodea al _Tigris_. Ya han trepado por la borda multitud de mercaderes y se han cerrado las portillas de los camarotes para evitar el hurto y la rapiña. Aquello es una invasión de hordas salvajes de aspecto aterrador, color de ébano, ojos inyectados en sangre, pelo crespo, sonrisa infernal, alaridos de fiera, desnudos la mayor parte, y ofreciéndote sus mercancías, consistentes en pieles de tigre, de leopardo o de mono, maderas toscamente labradas, flechas, crises, armas, dientes de animales; la especulación, en fin, en su forma más rudimentaria.\"},{\"heading\":false,\"text\":\"Nuestro vapor se ve rodeado por infinidad de barcazas, tripuladas por seres que parecen monstruos salidos del Averno, y que en un inglés _sui generis_, te brindan con llevarte a tierra. Los niños, que de cinco o seis años ya manejan sus embarcaciones, tienen el aspecto de monos; como el simio, rechinan los dientes, y como él tienen los pies y las manos aplastadas, y muy largas las falanges. Han nacido para vivir en el agua, y es de ver como, por una pequeña retribución, se precipitan desde la borda del _Tigris_, atraviesan su quilla de babor a estribor, luchan entre sí y pescan la moneda, que muchas veces el remolino ha conducido al fondo. Otras, como en el viaje anterior al del _Tigris_, acontece que un tiburón se encarga de dirimir la contienda, devorando a alguna de aquellas pobres criaturas.\"},{\"heading\":false,\"text\":\"Lo que llama poderosamente la atención, es que la mayor parte de aquellos negros ostenta una cabellera rubia como un hijo de las orillas del Támesis. Confieso que mi primera intención fue creer que la influencia del dominio inglés entraba por algo en aquel mesticismo de la raza; pero luego supe que solo se debe a la moda, que allí, como en todas partes, hace sentir su presión. Parece, en efecto, que este es un signo de distinción entre los habitantes del golfo de Adén, y que para obtener el resultado que se proponen, se untan la cabeza, después de raspada, con una mezcla de cal y no sé qué otra sustancia; y lo prueba el que muchos de ellos llevaban su hedionda plasta sobre el occipucio, pareciendo como atacados de alguna asquerosa enfermedad cutánea. Después dejan crecer el pelo, que, crespo y de colores distintos, les abulta la cabeza en tres o cuatro veces el tamaño natural, y excuso decirte si, al ver correr hacia ti a un fenómeno semejante, no echas mano al revólver, como medida de precaución.\"},{\"heading\":false,\"text\":\"Lo primero que, después de los cañones, se ve al tocar tierra, es el barrio comercial, con sus agencias, fondas, factorías y la residencia del gobernador. Unos sucios e incómodos coches de cuatro asientos le llevan a uno por la ciudad indígena, formada de chozas y zaquizamíes; y después de cruzar el verdadero Adén, con sus cuarteles, sus casuchas jalbegadas y sus estrechas calles, sigues subiendo, con el mar siempre a la izquierda y algunos arrabales hediondos a la derecha, hasta llegar a las cisternas, obra titánica donde apaga su sed aquel pueblo, asfixiado por los rayos de un sol tropical.\"},{\"heading\":false,\"text\":\"En todo el trayecto de dos horas no se encuentra ni el vestigio de una planta; solo al pie de las cisternas han conseguido, llevando tierra vegetal de Europa, plantar una docena de árboles, pero una docena literalmente hablando, que han alcanzado el desarrollo de una mata de laurel. En los puestos de la policía, que se suceden de trecho en trecho, se ve por vez primera el _gong_ o campana china, disco de metal que da un sonido como el del címbalo, y con el cual se comunican los agentes. Estos dominan a la turba a palos, y te libertan por ese medio de los innumerables chiquillos que te siguen y asedian pidiéndote una limosna, lo que no quita para que, después de despejado el terreno, el _policeman_ tienda también la mano en demanda de retribución.\"},{\"heading\":false,\"text\":\"Asombra la diversidad de razas que allí pululan. El árabe, de correctas facciones; el abisinio, desafiando al sol con su cabeza siempre descubierta, y tapando sus piernas con una sábana llamada _sarrong_, que, liada a la cintura, pende hasta los tobillos, mientras que embozado en otra, echada sobre los hombros, encuadra con elegantes pliegues su bronceada fisonomía, de puras aunque acentuadas líneas, y juguetea con el inseparable junco en forma de cayado, indispensable atributo de su elegante condición; el somaulís, con su gracioso turbante; el afeitado y desnudo habitante de Nubia, cabalgando sobre el paciente asno; el parsi, descendiente de los antiguos persas, sectario de Zoroastro y adorador del fuego, cubierto con un jaique sobre calzones a la europea, y calzada la cabeza con una como mitra en forma idéntica a la boquilla de un clarinete; el indostánico o malabar, con la chaquetilla de vivísimos colores y el abultado turbante escarlata, fumando sus _ehibuc_, incrustado en las jorobas de su camello; hasta el hombre, en fin, que sin otro traje que un pañuelo pendiente de la cintura, ignora su patria, su religión y su lengua; todo se encuentra allí en mezcla confusa, como si la especie humana se hubiera dado cita para asombro del viajero, que solo conoce el mundo por las cartas geográficas.\"},{\"heading\":false,\"text\":\"Amanece el día 25, y zarpamos con rumbo a Ceylán. A las dos de la tarde doblamos el cabo Guardafui, y dejamos el estrecho de Bab-el-Mandeb para cruzar el golfo de Omán por el mar de las Indias, y aquí empieza a danzar el buque impelido por un violento SO., que no es otra cosa que los últimos, pero respetables, aletazos del monzón.\"},{\"heading\":false,\"text\":\"Son los monzones unos vientos que en dirección distinta reinan periódicamente en estas latitudes. De octubre a marzo soplan de NE., y de mayo a agosto del SO.; pero hasta entablarse o fijarse, hay en los meses intermedios una lucha entre ambos, que produce en el mar de la China los horrorosos huracanes conocidos con el nombre de tiffones que, aunque de menor importancia que los ciclones del Atlántico, ocasionan catástrofes espantosas.\"},{\"heading\":false,\"text\":\"Pasemos lo mejor que podamos estos ocho días que nos esperan sin ver tierra, y colocándonos por entre las Maldivas y las Laquedivas, recalemos sobre el cabo Comorin, crucemos el golfo de Manaar y fondeemos al terminar el 2 de septiembre en la parte meridional de la isla de Ceylán, en aquel paraíso, portugués primero, luego holandés y británico últimamente, que lleva el nombre de Punta de Gales.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Busco, pero en vano, la manera de describirte esta maravilla; no se me ocurre más que compararla a una decoración de ópera de gran espectáculo. Voy a ver si puedo dar de ello alguna idea. Estando en rada, miras de frente a la ciudad, y por tu derecha se extiende la costa. ¿Te has detenido a observar alguna vez el innumerable tejido de troncos y ramas de que se componen los zarzales y las malezas? Pues figúrate que toda aquella inextricable red de palitos se convierten en elevados y airosos cocoteros, que se cimbrean al soplo de una benéfica brisa, y tendrás la base de esta inconcebible vegetación. Imagínate que del centro de la ciudad, surgen cúpulas de templos católicos, pingorotes de capillas ojivales o góticas, promontorios de pagodas búdicas, pirámides de monumentos bramines, minaretes de mezquitas árabes, terrazas de opulentas moradas; y todo esto entre bosques de jardinería. Yo no sé si me explico; pero a ver si me entiendes: recuerdo que en todas partes por donde la vegetación es rica, se ve una masa hermosa, imponente; pero _masa_ en fin, cosa maciza. En Gales no; los troncos están tan compactos que se tocan; pero las ramas son tan variadas, tan elegantes, tienen una languidez tan poética, que parece como que el artífice de aquella naturaleza ha estudiado la combinación de la luz sobre los colores de las plantas, y se ha complacido en recortar aquellas hojas festoneadas, para que un cielo siempre azul caiga a pabellones por las ondulaciones de los árboles, y un sol tropical se infiltre por entre los hilos de aquel encaje de verdura. Junto al cocotero de cubierto tronco y arqueado penacho, surgen el bananero, de ancha y deshilachada hoja, y la palma del viajero, abanico abierto de colosales ramas, que lanza al aire sus varillas, adornadas de plumas de esmeralda, con la regularidad de los radios de una circunferencia; y si de los prismas pasamos a los olores, dime el maridaje que resultará de la mezcla de aquellas gomas, con los efluvios de unos frutos que, empezando en la odorante piña, espiran y se ahogan en los bosques de caneleros. ¡Aquello es un caos de colores y perfumes!\"},{\"heading\":false,\"text\":\"Saltemos pronto a tierra; hay que entrar allí. ¿Pero qué es esto? En Gales todo es sorprendente. Las lanchas tampoco son como en los demás países; los botes, las canoas, las falúas, todo aquello concluyó. Aquí nos sale al encuentro la piragua, embarcación típica y original, que merece describirse.\"},{\"heading\":false,\"text\":\"Figúrate un cajón de madera, de la longitud y de la altura de una canoa ordinaria, con dos proas como esta, pero sin tripa, toda vez que sus costados lo forman sencillamente dos planchas, unidas entre sí por unos travesaños en la parte superior, y una especie de peana o contrapeso por abajo. Su anchura no llega a media vara, de tal modo que los tripulantes, al sentarse en ellas, llevan las piernas encajadas, y las caderas fuera de la embarcación. Como supones, sería imposible que este aparato flotase, a no ser por el balancín que le agregan por un costado, y que consiste en dos largos remos armados y sujetos a la borda en posición de bogar, a cuyos extremos se ata transversalmente, o sea paralelo a la piragua, un cilindro de madera que, descansando sobre el agua, establece el equilibrio, presentando un extenso polígono de resistencia que le impide zozobrar.\"},{\"heading\":false,\"text\":\"Ya asaltan el _Tigris_ los buhoneros del país. La raza humana, que en Nápoles era morena, tostada en África y negra en Adén, empieza a perder color en la India; el cingalés es un moreno con fondo amarillo y pelo de azabache. Hombres y mujeres se peinan echándose las melenas hacia atrás, y retorciéndolas para sujetarlas, hechas un bodrio, sobre la nuca; un peine de goma como el que en Europa usan las niñas, completa su tocado. El cuerpo le ciñen con un sarrong de colores, como la sábana de los abisinios, y una chaquetilla europea en ellos y un gabancito o _caracó_ en ellas, que tiene poco de airoso. El sexo feo suele usar patillas, lo que acaba de asimilarlos a los gitanos.\"},{\"heading\":false,\"text\":\"La venta a bordo ha cambiado también de fase. A los productos artísticos de Italia y a los zoológicos de la Arabia, han sucedido los finísimos encajes de Lahor, los bordados y telas primorosas de Cachemira, los productos persas, que las caravanas indostánicas transportan de Ispahán y de Teherán, y por último, las piedras preciosas con que en calidad y cantidad compite la India con el mundo entero.\"},{\"heading\":false,\"text\":\"Debo advertirte que se venden muy caras y que te piden por ellas el cuádruplo de su valor; así como que hay que ser muy experto para no tomar gato por liebre, pues son más las piedras falsas que las verdaderas que se ponen en circulación. Solo de ese modo se explica que yo adquiriese ocho grandes rubíes, tres enormes zafiros y un topacio en cambio de tres levitas, dos pantalones y cuatro chalecos fuera de uso. Fue un cambalache de cristal por paño, muy admitido entre los joyeros falsos cingaleses.\"},{\"heading\":false,\"text\":\"Desembarquemos; pero no me preguntes lo que es Punta de Gales; no lo sé. Allí no hay calles; son bosques inmensos en los que, diseminados, encuentras templos, casas, chozas, hoteles, agencias, joyerías; coches que se cruzan con carretas tiradas por bueyes pequeños, que trotan como caballos, bayaderas que bailan, magnetizadores de serpientes que las electrizan al son de la flauta, juglares que te asombran, titiriteros que te horripilan. Ya sabes que los indios del Malabar son los más hábiles gimnastas que se conocen; estoy persuadido, sin embargo, de que van a maravillarte estos dos ejemplos de acrobacia y prestidigitación de que he sido testigo en uno de aquellos jardines que llaman plazas.\"},{\"heading\":false,\"text\":\"Un hombre coloca tres venablos o chuzos atados en forma de trípode y con los hierros hacia abajo, sobre el puño de un sable; apoya la punta de este sobre una lanza, y acostándose en el suelo, tiene todo aquel armatoste en equilibrio sobre su frente, hasta que dándole una sacudida, despide la lanza por un lado, el sable por otro y los venablos vienen a clavarse en el suelo entre las rodillas y los sobacos del titiritero.\"},{\"heading\":false,\"text\":\"Otro individuo puso sobre una mesa, sin tapete, una canasta de mimbre, en la que, encogiéndose mucho, se arrebuñó un muchachuelo; cubrió el cesto con su tapa, y blandiendo un enorme cris, se entretuvo en dar de puñaladas al continente y al contenido. Oyéronse los ayes más desgarradores, la sangre corría por la mesa...\"},{\"heading\":false,\"text\":\"--¡Basta! ¡Basta! --gritamos todos, no dando crédito a nuestros ojos.\"},{\"heading\":false,\"text\":\"El juglar destapó entonces el canasto; el canasto estaba vacío y el rapazuelo entraba en el corro pidiendo con su platillo unas monedas de cobre por aquel inconcebible espectáculo al aire libre.\"},{\"heading\":false,\"text\":\"Una de las imprescindibles excursiones que hay que hacer en Punta de Gales es a Wackwella (pronuncia Guacuela). Un cómodo y bien acondicionado coche te lleva, mediante tres rupias (treinta reales), y durante cuatro horas, a visitar el bosque de los caneleros; y por un camino imposible de describir, en el que abundan los árboles más raros, las aves más trinadoras y pintadas que puede soñar la fantasía, y por el que constantemente te sigue una turba de rapaces ofreciéndote, ya un mangustán rojo como la grana y blanco como la nieve, ya un coco con que aplacar la sed, ya una rama de canela con que perfumarte, llegas a la plataforma en cuestión, desde la que, saboreando un refresco del país, divisas un extenso horizonte, cuajado de islas de cocoteros y de colinas de cafetales, por las que serpentea lo que al pronto parece un ancho y caudaloso río de muchas leguas, y que resulta ser una interminable y consecutiva serie de plantaciones de arroz. En el fondo se destaca el pico de Adán, monte situado al N. de la isla, detrás del que existe el puente de Eva, que une la isla de Ceylán al continente Índico, separados por el estrecho de Palk. Porque, debo advertirte, que los cingaleses pretenden, y creo que con razón, que el Paraíso terrenal estaba en su casa; así es que se encuentran allí todos los nombres de nuestras Sagradas Escrituras, y hasta se rinde culto a la Virgen María.\"},{\"heading\":false,\"text\":\"Oye cómo la teogonía de los bramines cierra el capítulo de su Génesis:\"},{\"heading\":false,\"text\":\"«Atani entristecía en el Paraíso; Dios le dio a Iva por compañera (aquí sigue una bellísima descripción imposible de traducir, pero tan admirable como el cántico de los cánticos). Y al contemplar Dios tanta ventura, dijo: “Ahora sí que estoy satisfecho de mi obra; ya es perfecta; _he producido el amor_”.»\"},{\"heading\":false,\"text\":\"Suenan las once de la mañana del día 4 y no tenemos tiempo que perder. Despidámonos de los pasajeros para Pondichery, Madras, Calcuta y Bengala en el E. de la India, y de los que se dirijan a Bombay por el ferrocarril del continente. Volvamos al _Tigris_ y zarpemos. En cuatro días cruzamos el golfo de Bengala. El 8 se aparece Penang, el portero inglés de los Estrechos, con su artillería correspondiente, formando _pendant_ con la punta de Achem, de la isla de Sumatra, en la Oceanía. Al amanecer del 9 concluímos de pasar el estrecho de Malaca y atracamos junto al muelle de Singapore. Estamos sobre el Ecuador; un grado más y cortamos la línea.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"La entrada a esta posesión inglesa es uno de los espectáculos más bonitos que puede soñarse y comparte justamente la admiración del viajero con el Bósforo, el Rhin, el Danubio, la bahía de Río de Janeiro y el golfo de Nápoles. Imagínate que Singapore es un gigante cuyos enormes pies, que son las costas, están bañados por el agua. El vapor se desliza por la punta de sus dedos; pero cada vez que cruza una de sus bifurcaciones, viene a sorprenderte un panorama pintoresco y variado, que te lleva de sorpresa en sorpresa. Entre una vegetación, si no tan exuberante, por lo menos tan coqueta como la de Ceylán, ves aparecer en la cumbre los _bungalows_, o casas de campo inglesas, con sus galerías corridas bajo una serie de arcadas, mientras por abajo, en los repliegues de los dedos, pueblos enteros de chozas plantadas sobre estacas, se reflejan en las ondas, de las que brotan árboles copudos y en que se bañan las aves domésticas. Cada una de aquellas ensenadas parece un Nacimiento.\"},{\"heading\":false,\"text\":\"Aquí la raza es ya amarilla, con ese tinte enfermizo que caracteriza al malayo.\"},{\"heading\":false,\"text\":\"Elegantes y ventilados cochecillos llamados palanquines, tirados por caballitos malabares, de la alzada de un borriquillo moruno y guiados por un cochero indio, con quien generalmente se cierra el ajuste a bofetadas, te transportan por un larguísimo camino poblado de tenduchos, en su mayoría chinos, a la _city_ o barrio comercial. Este es sombrío, sucio; pero importante y lleno de animación.\"},{\"heading\":false,\"text\":\"Singapore es el punto de escala de los que van y de los que vienen, y el almacén de depósito de todas las mercancías imaginables. Así es que, relacionado con el resto del mundo, pululan en su seno todas las razas que vimos en Adén, enriquecidas con el concurso de los siameses y anamitas, los chinos del N. y S. del Celeste Imperio, los tagalos del Septentrión, los visayas del Centro y los moros del Mediodía del archipiélago Filipino, los javaneses y los indígenas, en fin, de las Molucas, las Célebes, la Oceanía y Australia. Allí no tienes que preguntar al europeo el derrotero que sigue; su rostro te lo indica; el que llega tiene color, está rozagante, ríe, charla, nace. El que regresa se lleva el sello del país, amarillea, calla, se queja, muere. En Singapore el traje se simplifica; el sarrong se reduce a un taparrabos, el desnudo impera y empiezan a verse los shalakos, enormes discos de junco de infinitas formas, para cubrirse aquellas cabezas afeitadas o aderezadas con tufos de pelo, que ya brotan en el principio del occipucio, ya se corren hacia la nuca o se inclinan caprichosamente sobre una de ambas orejas.\"},{\"heading\":false,\"text\":\"En la _City_ vi el tipo que más ha excitado mi hilaridad. Era a la puerta de una tonelería; y sobre una pipa un hombre totalmente desnudo, con la cabeza afeitada, ostentando sobre sus narices unos anteojos chinos, cada uno de cuyos cristales tienen, sin exageración, el diámetro de una copa para agua, y su montura en concha medio dedo de ancho, leía puesto en cuclillas, a la usanza asiática, el _Times_ de Londres.\"},{\"heading\":false,\"text\":\"Por un magnífico puente colgante, se atraviesa el río y se penetra en la ciudad propiamente dicha. Allí están las casas habitables, el palacio del gobierno, el _City hall_ o casa municipal, las iglesias, colegios, congregaciones, paseos, espectáculos; todo en medio de árboles y de flores; pero con carácter europeo adaptado a las condiciones locales. Poca sociabilidad, trato inglés, formalidad, mucho _comfort_; pero expansión, cero.\"},{\"heading\":false,\"text\":\"El 10 salimos de Singapore y empezamos a subir hacia el N. el mar de la China, cruzando el golfo de Siam. El 12 recalamos en el cabo de San Jaime, mole imponente erizada de bosque virgen, en cuya cumbre se levanta el semáforo, visitado constantemente por fieras, contra las que tienen que vivir apercibidos los vigías condenados a aquel peligroso servicio. Siguiendo la costa, aparece de repente, bajo la pesadumbre de aquella montaña, un fondeadero llamado la Bahía de los cocoteros; pintoresco y ameno lugar donde se halla establecida la estación telegráfica del cable submarino, por la que, pocos días después, recibía mi familia la noticia de mi feliz llegada, a las siete horas de mi desembarco en Hong-Kong, mediante la módica suma de once pesetas por palabra.\"},{\"heading\":false,\"text\":\"Remontamos con la luna el Donaí, ancho y profundo río, lleno de zig-zag con monótonos, pero verdes ribazos, en los que duermen algunos cocodrilos; y antes de que alborease el día 13, atracábamos delante de la Agencia de las Mensajerías en Saigon, capital de la Cochinchina francesa.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Situado al lado opuesto del río, hay que atravesar este en una lancha para llegar a la ciudad. Sin querer exclama uno: «Esto es Francia.» En efecto, los hijos de San Luis tienen tres necesidades, que no pueden dejar de satisfacer, y que imprimen el sello hasta a sus colonias menos importantes: _Cafés_, _restaurants_ y _demi-monde_. Saigon está alumbrada por gas, como todas las posesiones inglesas del Asia; pero como en estas los establecimientos de diversión pública no existen, resultan oscuros, mientras que en la metrópoli de la Cochinchina la luz incita al paseante a recorrer su muelle, y la gente vive de noche, sin cuidarse de la hora del apaga-fuegos.\"},{\"heading\":false,\"text\":\"Otro distintivo peculiar de la buena administración francesa es que el barquero o el cochero no te exigen nunca más dinero del que tú les das por su trabajo.\"},{\"heading\":false,\"text\":\"Las calles, nacientes aún, están edificadas sobre bosques y jardines; pero estos, ni tienen el aspecto virgen de Ceylán, ni el ondulante y caprichoso de Singapore. El rectángulo impera; han obligado a los árboles a aprender táctica, y todos se han tenido que alinear, para producir anchos boulevares sujetos a escuadra. El palacio del gobernador es un magnífico y suntuoso monumento, los jardines recuerdan el parque Monceau de París. Dentro de algunos años aquello no se diferenciará en nada de una capital de provincia francesa, aparte de las chozas de los naturales.\"},{\"heading\":false,\"text\":\"La arteria principal de Saigon se llama calle de España. Es el único testimonio y el solo provecho que hemos sacado de la campaña de Cochinchina, en la que las armas españolas han regalado a sus vecinos de allende el Pirineo la hegemonía sobre el imperio de Annam, la costa del golfo de Tonkín y el reino de Camboya. Solo falta Siam para tener el protectorado sobre toda la India Transgangética.\"},{\"heading\":false,\"text\":\"A rumbosos no nos gana nadie.\"},{\"heading\":false,\"text\":\"Amanece el día 14, levamos ancla, y Norte arriba del mar de la China, bordeamos la isla de Hai Nam, enfilada al canal de Formosa, y fondeamos el 17 a las nueve de la noche, en la rada de Hong-Kong, colonia inglesa del Celeste Imperio.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Y terminados aquí los treinta y ocho días de navegación, en que a escape hemos visitado lo que nos salía al encuentro, hagamos alto y empecemos a tratar detenidamente de los usos, costumbres, ceremonias y fisonomía del pueblo chino, así como del aspecto de las principales poblaciones del país de Confucio.\"}]},{\"title\":\"Viaje a China — Macao, 19 de abril de 1879\",\"blocks\":[{\"heading\":false,\"text\":\"Mi querido amigo: Cuando desde Europa se le ocurre a uno pensar en China, se la representa en su imaginación como una inmensa tela de esos abanicos que llegan allí del Celeste Imperio. Por lo menos así me la forjaba yo. Por todas partes verdes praderas como la esmeralda, salpicadas de flores rojas y azules; en medio de aquellas limpias sábanas de verdura, casitas con su agalerada techumbre, flanqueadas de kioskos en forma de parasoles superpuestos, con su campanilla correspondiente al extremo de cada radio; el arqueado puente como la joroba de un camello tendido sobre un riachuelo transparente que refleja los vivísimos colores del junco al deslizarse por su superficie; a la puerta, en forma de una O, de la casa, ataviadas damas con sus bordados trajes de seda y diminuto pie departiendo tranquilamente con gallardos mancebos envueltos en talares túnicas de recamo de oro, y saboreando una taza de té; en el fondo niños remontando cometas sobre una terraza, y ancianos venerables de luenga barba blanca viendo volar pintados pajarillos. Todos ellos, por supuesto, con caras de marfil, aguzadas y nacaradas uñas y ojos oblicuos. En resumen, la China del europeo es el progreso material del siglo XIX combinado con las patriarcales costumbres de los tiempos bíblicos; de la tela del abanico se desprenden para él estas tres condiciones distintivas de la raza mongólica: lujo, limpieza y silencio.\"},{\"heading\":false,\"text\":\"Cerremos el abanico y abramos la puerta del hoy imperio tártaro. Vas a ver el desengaño que nos espera.\"},{\"heading\":false,\"text\":\"Una gritería, comparable tan solo a una riña de verduleras, es lo primero que te llama la atención al despedirte de la gente de a bordo y disponerte a tomar una embarcación que, desde la inmensa y hermosa bahía de Hong-Kong, te conduzca a tierra. Son los barqueros pugnando por atracar sus champanes al _Tigris_, ofreciéndote sus servicios o diciendo buenos días simplemente a un camarada, pues para todo se alborota aquí.\"},{\"heading\":false,\"text\":\"Y palpitando de emoción bajas las escaleras con los ojos cerrados para abrirlos de repente y gozar del espectáculo de aquella China soñada.\"},{\"heading\":false,\"text\":\"Lo primero que ves es el _champan_ o bote para conducción de pasajeros y mercancías, tosca embarcación parecida a una barcaza muy tripuda, con un toldo de bambú en la popa, chorreando mugre por todas partes y exhalando una fetidez insoportable, a la que concluyes por habituarte, pues la forma un conjunto de circunstancias inherentes a la raza indígena, que constituye el perfume local, conocido por el europeo con el nombre genérico de «olor de chino.» La tripulación está compuesta de varias mujeres de distintas edades, pero de fealdad idéntica; algunas veces hay también un hombre; pero como este viste el mismo traje que aquellas, carece en absoluto de barba y todos poseen los mismos rasgos fisonómicos, resulta que para el viajero inexperto el chino es _el ser que bajo una misma terminación y artículo comprende los dos sexos, masculino y femenino_, y que la gramática coloca en el género epiceno. Ojo pequeño y algo oblicuo, encerrado en un párpado carnoso, sin casi ceja, frente no muy deprimida, nariz aplastada, pómulos salientes, labio superior con honores de hocico, dientes un poco más pequeños que teclas de piano, color mejor que ictérico, amarillo de vicio, pelo negro de sartén con la aspereza exacta de la crin; lampiño el hombre, rechoncha la mujer, pero ambos escrofulosos y llenos de pupas y asquerosidades, son los componentes de una cabeza china de la clase humilde, que comprenderemos en la denominación de _culi_, como aquí se llama al bracero, mozo de cuerda y todo el que ejerce un oficio bajo.\"},{\"heading\":false,\"text\":\"Un calzón ancho hasta el tobillo, de una tela que debió ser percal negro o azul y que, perdido el aderezo de goma, ha degenerado en tejido de grasa, y una blusa de lo mismo abrochada por el costado, pendiente hasta el muslo, con mangas perdidas y largas hasta rebasar un palmo las manos, que quedan ocultas en ellas, constituyen el traje común de dos. No hay camisa ni cosa que lo valga. El pie desnudo; alguno que otro lleva una suela sujeta con cordeles al tobillo; pero es raro. Como ves, nada más parecido al disfraz del _pierrot_ francés, salvo el color y la limpieza. La mujer lleva la cabeza cubierta con un pañuelo de algodón, colocado lo mismo que nuestra gente del pueblo; el hombre la ostenta casi siempre desnuda. Usa, sin embargo, en verano un _shalakó_ o sombrero de bambú, en forma de un disco desmesurado, con un pingorote en el centro, como la tapadera de una taza, y en invierno una montera de fieltro oscuro, menos alta, pero idéntica en la forma al sombrero del pierrot.\"},{\"heading\":false,\"text\":\"Tanto el macho como la hembra se abrigan con un saco hasta la cintura, sin mangas y guatado, que visten sobre el traje descrito, y llamado _patchama_. Los niños emplean el mismo uniforme, pero de colores rabiosos, y les cubren la cabeza, ya con un simple aro, del que penden borlas y cordones, ya con una cosa parecida a las carteras en que los chicos de la escuela guardan los libros, colocada de modo que la cubierta penda sobre el cogote, y adornando los dos picos del remate de arriba con unas orejitas de gato hechas de algodón en rama.\"},{\"heading\":false,\"text\":\"Pasemos al peinado. Los parvulillos llevan sobre cualquiera de ambas orejas un plumerito, como la perilla de un hombre, atadito con una cinta de color; el resto afeitado; con lo cual se consigue que se fortalezca la parte de pelo que más tarde han de dejarse crecer, y que, como dejo dicho, toma la consistencia de la cerda. En efecto: en cuanto el niño llega a adulto, se le afeita también el tuferito y se le hace adoptar el invariable aderezo de la epidermis capilar masculina; porque debo advertirte que aquí nada cambia, todo es inmutable; no hay modas ni caprichos. El pasado se sabe por el presente, el mañana puede leerse por el hoy, la tradición impera; el estacionamiento es la base de su sistema.\"},{\"heading\":false,\"text\":\"Hasta hace dos siglos el habitante del Celeste Imperio lucía larga cabellera y ostentaba el traje con que vemos representados en sus estampas a los ídolos y los héroes de sus leyendas; pero al caer la dinastía china de los _Ming_ y tener que soportar la dominación tártara de los manchures del N., la dinastía _Tsing_, que hoy subsiste, impuso a sus vasallos la dura ley del vencedor, y haciéndoles cambiar de traje, les obligó a afeitarse la cabeza y dejarse _una cola de perro_, en signo de servidumbre.\"},{\"heading\":false,\"text\":\"Coloca sobre la cabeza un solideo; afeita todo lo que no esté cubierto por él; deja crecer hasta donde quiera el pelo que aquel encubre; haz después una trenza que, con el auxilio de cordones, casi siempre negros, pero alguna vez azules o encarnados, llegue hasta los tobillos, y tendrás la idea exacta del peinado chino, desde el primer mandarín hasta el último culi, sin más diferencia que, mientras las clases acomodadas se afeitan semanalmente y llevan los cordones limpios, el pobre lo toma por semestres y cambia de cordón cuando la miseria se ha comido el primero. Algunos _fashionables_ dejan crecer alrededor de la mata una como aureola de pelos cortos, que flotan a merced del viento y que acaba de embellecerlos. Agrega a todo esto las rarezas de configuración de aquellas cabezas, cuyos defectos nada hay que disimule; los chirlos, las protuberancias y las cicatrices de todo género que las ornan, y calcula los purgantes que ha debido uno tomar hasta acostumbrar el estómago y la vista.\"},{\"heading\":false,\"text\":\"Ya que de pelos me ocupo, consignaré que la barba en los chinos son diez o doce hebras de esparto, brotadas al azar, y que les está prohibido por sus leyes y costumbres llevar bigote hasta que han cumplido cuarenta y ocho años, o tienen nietos, o bien a los veintiocho si son mandarines.\"},{\"heading\":false,\"text\":\"Pasemos a las mujeres. La soltera se echa atrás todo el cabello, rematado por una trenza larga, en cuyo tronco lleva liada una cinta de color, formando un anillo; saca de la sien izquierda un banda de pelo como de tres dedos de ancha, lo que consigue abriéndose una pequeña raya vertical, y se circuye lo alto de la frente con aquella faja, que va a mezclarse con el resto de la cabellera por el lado opuesto. Como ves, las hijas de Eva conservan toda su integridad capilar, si bien son tan lampiñas como los chinos, pues las cejas y las pestañas hay que verlas con microscopio.\"},{\"heading\":false,\"text\":\"El peinado de la casada es muy difícil de explicar: echado todo atrás, sin raya alguna, salen de los lados dos enormes cocas, que sujetan con alambres por dentro; el topo se separa más de un palmo de la nuca, y le forma todo el pelo de la mata, saliendo como el espolón de un buque de guerra, y el del cogote, subiendo a enlazarse con aquel: un cordón de pelo retorcido baja desde la parte alta y posterior de la cabeza hasta el vértice de aquel ángulo agudo, y multitud de broches y alfileres sujetan, con el auxilio de la goma, tan complicado aparato, al que dan el nombre de _peinado del ave de la inmortalidad_. Y esta denominación me sugiere una explicación más exacta del efecto que produce este tocado. Córtale a una gallina el cuello y las patas, ábrela por la pechuga, encájasela en la cabeza a una china por esta abertura, ábrele las alas en toda su extensión, que son las cocas, y adereza el topo de manera que quede formando la cola. Es idéntico hasta en sus proporciones.\"},{\"heading\":false,\"text\":\"Por decreto de no sé qué emperador, cierta gente de mar está proscrita de la tierra, y por consiguiente no puede habitar más que en sus embarcaciones. De modo que el champan es el estrado, la cocina, el dormitorio, la pagoda, la cuna y el lecho de muerte de sus moradores; allí nacen, viven, rezan, se reproducen y mueren.\"},{\"heading\":false,\"text\":\"Las madres, consagradas a sus tareas, no pueden atender muy asiduamente a sus hijos; así es que para trabajar desembarazadamente, se los echan a la espalda, sujetándolos con un como pañuelo de lana, al que va sentado el rapaz y del que penden cuatro correas, que se ajustan como cinturón y como tirantes en las caderas. Esto, si el infante es aún mamón; pues apenas anda, ya se bandea por su cuenta; y la única precaución que se toma es atarle un cordel a la cintura para pescarle cada una de las veinte veces que al día se cae al agua: algunos añaden corchos o vejigas, para que flote el náufrago; pero no es de rigor, en atención a que sin ellos aprende a nadar más pronto.\"},{\"heading\":false,\"text\":\"Al cruzar la bahía, mi primer cuidado fue estudiar su aspecto; allí te encuentras el pontón para hospital militar, navío de tres puentes sin arboladura; el comodoro inglés, el almirante francés, corbetas rusas y alemanas, la Mala francesa que llega de Europa, la inglesa que sale para la India, vapores británicos para Shang-hai y Emuy, españoles para Manila, la Mala americana del Pacífico, los anexos de las Mensajerías para el Japón; pero te preguntas: «¿Y la marina china?» Allí la tienes representada por miles de champanes y centenares de _lorchas_ para la pesca y el tráfico costero, única empresa de estos nautas con coleta.\"},{\"heading\":false,\"text\":\"La _lorcha_ es lo que vulgarmente llamamos junco; barco tripudo, más o menos grande, con una popa semi-esférica, anchísima y desmesuradamente alta, timón descomunal calado en celosía, y dos palos, a los que van sujetas unas velas latinas despuntadas con una serie de travesaños horizontales de madera, a modo de entenas, para tomar los rizos. Muchas de ellas, aun las mercantes, llevan a bordo cañones de hierro, que ni el famoso de Barba-Azul. Como el champan, la lorcha es una casa de familia, cuyo desaseo está en proporción de su mayor capacidad. El día se lo pasan tocando el _gong_, o tan-tan, o campana chinesca, que estos tres nombres tiene el disco en cuestión; y la noche quemando papelitos para ahuyentar a los espíritus maléficos.\"},{\"heading\":false,\"text\":\"La media docena de lanchas cañoneras que posee el gobierno, están mandadas por capitanes franceses, ingleses o americanos.\"},{\"heading\":false,\"text\":\"Por fin, desembarcamos en el muelle; culis machos y hembras transportando mercancías, pendientes a los extremos de un bambú, colocado sobre el hombro, culis de silla asaltándote con las de mano o literas, único medio de locomoción en estas regiones, agentes de policía india con sus abultados turbantes encarnados, repartiendo bofetones y latigazos con que hacer entrar en orden a aquellas acémilas humanas del servicio público, y mucho europeo consagrado a sus tareas, constituyen el movimiento de la población; pero aquello no es China; las casas que veo son las de mis latitudes, la gente con coleta que circula por las calles es la hez del pueblo uniformemente vestida, y yo necesito la tela del abanico, los colores, la luz, el recamo de oro, los bordados en seda, el Oriente, en fin, con sus mandarines, sus tropas, sus mujeres, su industria, sus diversiones, su vida peculiar. «Ya le veo a usted a la caída de la tarde persiguiendo modistillas chinescas» --escribía a un amigo mío residente en Hong-Kong otro suyo de Madrid--, y yo, aunque sin instintos de pirata callejero, deseaba conocer en toda su integridad la fisonomía del Celeste Imperio. Luego iremos al barrio chino; ahora recorramos la ciudad europea.\"},{\"heading\":false,\"text\":\"Hong-Kong es una maravilla. Edificada en anfiteatro sobre una peña que hace cuarenta años no tenía ni una planta, asombra el ver lo que los ingleses han hecho de ella en tan corto espacio. Calles paralelas y escalonadas, abiertas a lo largo de la isla, te ofrecen por doquiera la grata sombra de sus amenos, elegantes y caprichosos jardines; porque es de notar que, aprovechando los accidentes del terreno, han edificado sus avenidas de modo que las calles no parecen calles; al lado de un templo ves una esbelta escalinata que conduce a la casa contigua, levantada sobre un terraplén con árboles; junto al graderío que te hizo subir, se abre una cuesta con artística ornamentación, que te hace bajar al _bungalow_ vecino; una tapia te oculta el _cottage_ que se alza sobre el promontorio de una colina interior; de modo, que la vista va de sorpresa en sorpresa, descubriendo aquel sembrado de moradas espléndidas entre una vegetación artificial, y de fortificación en fortificación, de paseo en paseo, de la iglesia al club, del teatro al hospital, subes por magníficos caminos en zig-zag, hasta el pico Victoria, donde se halla el semáforo y desde el que abarcas todo el panorama de la rica colonia inglesa.\"},{\"heading\":false,\"text\":\"El mando superior de la isla es conferido por la corona inglesa a un gobernador, con la categoría (aunque civil) de vicealmirante y comandante en jefe, que preside los dos Consejos, ejecutivo y legislativo. La administración comprende la secretaría colonial, el tesoro, obras públicas, registro y correos.\"},{\"heading\":false,\"text\":\"La de justicia tiene tres jurisdicciones, la Suprema corte o audiencia, la corte de policía o tribunal sumario y de primera instancia, y la corte de marina. La institución del jurado existe para lo civil y lo criminal.\"},{\"heading\":false,\"text\":\"Además del pontón destinado en la bahía a hospital militar, hay en la población un hospital civil para europeos, otro para chinos, otro para variolosos y otro para la marina.\"},{\"heading\":false,\"text\":\"Hay ocho o diez centros de enseñanza pública, la mayor parte encomendados a los misioneros.\"},{\"heading\":false,\"text\":\"El material de incendios es una cosa admirable. En cada distrito estacionan varias bombas de vapor, que en pocos minutos se transportan al lugar del siniestro. Esto no quita para que el 25 de diciembre de 1878 se declarase un incendio a las once de la noche, y el 26, a las tres de la tarde, estuviesen convertidas en escombros seiscientas casas. Las libaciones de Navidad influyeron mucho en ello.\"},{\"heading\":false,\"text\":\"Fue el espectáculo más imponente que he presenciado. En cuanto se da la señal de fuego, todo individuo con tienda abierta tiene obligación de mandar a los culis que están a su servicio, provistos de una linterna china de papel de colores, y vestidos con un saco de arpillera, en que consta la razón de la casa en grandes caracteres. Figúrate, pues, toda la población dominando las alturas de la ciudad, la gente de los barrios amenazados por el incendio salvando sus muebles, los culis transportándolos a hombros en medio de la gritería más espantosa y de la confusión menos descriptible, toda la fuerza armada de la plaza y la de los buques surtos en la bahía prestando su concurso, el gas apagado, las calles convertidas en ríos y en campamentos, la dinamita y el cañón derribando manzanas enteras, y en el fondo aquella hoguera colosal, de la que, como chispas, se desprendían millares de linternas en todas direcciones, y que convertía el mar en un espejo de fuego: comprendí a Nerón.\"},{\"heading\":false,\"text\":\"La vida en Hong-Kong, como país comercial, tiene pocos atractivos. Algunas familias desperdigadas pasean por este o el otro vericueto, como medida higiénica; pero sin un punto fijo de cita para el _high-life_. Hay alguna que otra reunión, y un teatro inglés, al que apenas asisten señoras: verdad es que estas son escasas. En cambio el hombre se divierte mucho a la inglesa, es decir, haciendo excursiones campestres y desarrollando las fuerzas físicas en ejercicios gímnicos. Como no hay cafés públicos, existen un club alemán, otro portugués y otro parsi, pero ninguno puede compararse al británico, que es un verdadero modelo. El ingreso cuesta treinta duros y cuatro la cuota mensual; el edificio, suntuoso, pertenece a la sociedad, que ya no sabe en qué invertir el dinero que le sobra; del seno del mismo club emanan multitud de sociedades de _sport_, tales como el club de regatas, el de carreras, el de declamación, el de conciertos, el juego de pelota con variadísimas manifestaciones, la lucha de la maroma, en la que dos bandos tiran de los extremos de una cuerda hasta atraerse el uno al otro; por supuesto que para cada cosa tienen su magnífico local _ad hoc_, no siendo el menos notable las praderas que les sirven de trinquete; el gobernador y los notables presiden muchas de estas fiestas, y a todas tiene derecho el miembro del club general.\"},{\"heading\":false,\"text\":\"En este puede decirse que vive la parte europea masculina de Hong-Kong. Es su Bolsa. Allí escribe su correo en magnífico papel que, a granel, y con preciosos membretes, anda tirado por las mesas, y recibe la correspondencia que en un cuadro está a merced del que la quiera tomar, sin que se le ocurra hacerlo nunca mas que al interesado. En el salón de lectura hay todos los periódicos notables del mundo; de la biblioteca, rica en obras sobre la China, toma el socio los volúmenes que le da la gana y se los lleva a su casa, dejando en cambio un recibo. Hay un _bar-room_, o sitio de bebidas, un _lunch-room_ o puesto de fiambres para el tente-en-pie, y un _diner-room_ o comedor, donde almuerza y come muchísima gente, teniendo sus platos huecos, que se llenan de agua caliente en el invierno, y su hielo, pancas y ventiladores para el verano. Existen trece dormitorios, con el objeto de que el socio que llegue de fuera esté seguro de tener cuarto donde pasar la noche, aunque las fondas estén atestadas. Y al efecto, cada uno que se sucede toma su turno; de modo que cuando arriba un décimo-cuarto huésped, el número uno se va con la música a otra parte, pues se supone que ya ha debido tener tiempo de procurarse posada. Lo que se consume no se paga hasta fin de mes, a la presentación del _ticket_, o boleta, que por cada cosa ha firmado el socio, así es que los dependientes, todos chinos, no pueden robar ni un céntimo. Magníficos billares, tocadores espléndidos y salones confortabilísimos completan este prototipo de casinos, cuya administración corre a cargo de un solo dependiente inglés con el título de secretario.\"},{\"heading\":false,\"text\":\"La vida es cara en Hong-Kong. Una casa, no muy grande, cuesta ochenta duros al mes y ciento cincuenta el orificarle a uno cinco muelas. En las fondas se paga cuatro duros por día, sin los vinos, y cinco reales en el Club por una copa de licor cualquiera.\"},{\"heading\":false,\"text\":\"Pero dejemos ya todo lo que huela a Europa y corramos en busca de cosas celestes.\"},{\"heading\":false,\"text\":\"En _Queen’s road_, o sea en la arteria principal, alternan con establecimientos europeos, multitud de tiendas chinas, cuyo aspecto en nada difiere de las que vemos en nuestra casa, a excepción de las mercancías que en ellas se expenden.\"},{\"heading\":false,\"text\":\"Trabajos en marfil, filigranas de plata, vasos de porcelana, pendientes de jade (piedra verde de gran valor en estas regiones), juegos de ajedrez, abanicos de concha y de laca, muebles de maqué y otras industrias parecidas, yacen en anaquelerías y escaparates, relativamente limpios, pero sin agrupación artística. Las muestras de los bazares son unas planchas de madera rojas o negras, colocadas en las puertas verticalmente y de canto como columnas, con caracteres chinos de relieve y dorados, que constituyen el mejor adorno posible, pues sabido es que la escritura china es un acabado modelo de elegancia en dibujo. En el fondo y detrás del mostrador, uno o dos chinos macilentos aguardan su presa. El mueblaje es invariable, como el de todo el Celeste Imperio. Sillas o sitiales, en ángulos rectos, de una madera oscura, casi negra, con más o menos tallado, según su riqueza, y con asiento por lo común de piedra, con unas mesas pequeñas, rectangulares también, con su tapa de mármol incrustada en el marco. Con estas tiendas alternan algún bazar japonés, con sus elegantes productos de idéntica fisonomía, pero más artísticos que los chinos, y mercaderes parsis e indostanes con sus cachemires, telas de la India y mantones de capuchas, hechos con retalitos del tamaño de dos reales, cosidos entre sí, y que parecen remiendos, de los que no compré uno porque me pidieron por él más de mil pesos, y era usado.\"},{\"heading\":false,\"text\":\"Por fin, a la terminación de _Queen’s road_, en el extremo occidental de la ciudad, empieza el barrio chino. ¡Horror! ¡Abominación! ¿Y para esto he empleado treinta y ocho días y me he expuesto a las contingencias de un viaje de tres mil leguas? Figúrate unas casuchas de ladrillo gris azulado, sin enlucido de yeso, ni por dentro ni por fuera, con una puerta y una ventana embutidas en dos pilares de mampostería, porque es preciso que así sea, a fin de que no entren los espíritus maléficos. Unos gruesos barrotes de palo en sentido vertical hacen de cancela. En cada una de estas viviendas habitan treinta o cuarenta individuos, la mayor parte con el torso desnudo, destilando pringue, viviendo entre estiércol, en compañía del marrano y de las gallinas, ejerciendo su industria en colaboración con otro artesano de índole distinta. Así media tienda pertenece a un sastre y la otra media a un platero o pintor de retratos.\"},{\"heading\":false,\"text\":\"Todo son abacerías, expendedurías de verduras, pescado salado y objetos de culto para las pagodas, tocinerías, zapateros remendones, armeros y artículos de ferretería oxidados por el moho y la incuria. En fin, el rastro de la grasa, de la fetidez y de la basura elevado al infinito. Ya hablaremos de ello al ocuparnos detenidamente de los usos y costumbres locales. Por hoy basta, pues al ver que en vano sería buscar en Hong-Kong la tan deseada tela del abanico, me falta tiempo para abandonar este muladar indígena y hacer rumbo hacia Macao.\"}]},{\"title\":\"Viaje a China — Macao, 30 de abril de 1879\",\"blocks\":[{\"heading\":false,\"text\":\"Querido amigo: Un elegante vapor de ruedas, estilo americano como los del Misisipí, pintado de blanco y con la gran cámara a proa sobre cubierta, te hace recorrer en tres horas y cuarto, y por la suma de 3 duros, las cuarenta millas que separan a Hong-Kong de Macao. Las segundas están en el través del barco. Los chinos, cualquiera que sea su categoría, no son admitidos más que en la cala.\"},{\"heading\":false,\"text\":\"Al ponerse en marcha el buque, lo primero que te llama la atención es un guardián que, con un sable desnudo, vigila una escotilla de proa, que comunica con la cala, y que antes ha tenido cuidado de tapar con unos barrotes de hierro, a los que ha echado la llave.\"},{\"heading\":false,\"text\":\"Otro centinela, igualmente armado, custodia la escalera que desciende al sollado. Por último, en la cámara hay dos panoplias con machetes, puñales, carabinas, revólveres y municiones de reserva, con un letrero que dice: _loaded_, es decir, cargados. Son precauciones tomadas, invitaciones hechas al viajero para el caso probable, y antes muy frecuentemente reproducido, de que los chinos se subleven al pasar por las _Islas de los Ladrones_ y entreguen la tripulación a los piratas que infestan estos mares y que no perdonan vidas ni haciendas.\"},{\"heading\":false,\"text\":\"Por fin, llegamos a Macao, pequeña península que afecta la forma de una S, en cuya cabeza y tripa existen unas fortificaciones. La curva inferior es el puerto interior, en la desembocadura del río. La bahía, huérfana de todo buque que no sean las lorchas chinas y sin casi calado, la representa el semicírculo entre el cuello y la cabeza, en cuyo muelle está situada la _Praia Grande_, la mejor o la única calle de la ciudad. Las demás, abiertas paralelamente a esta sobre la colina, y las transversales, son callejones tristes, sombríos, conventuales, acusando pobreza, ruina y privaciones. El barrio chino, idéntico al de Hong-Kong, se extiende por la espalda de la S desde la embocadura del río hasta la nuca, de la que arranca un istmo, el que liga la isla al continente chinesco, largo de un kilómetro y ancho lo suficiente para que un coche pase por él sin caerse al agua, si no se desvía del centro. Al cruzar la bahía, Macao, del que solo se ve la _Praia Grande_, parece un pequeño Nápoles; después se cree uno en un pueblo de Aragón o de Castilla en pleno siglo XVI.\"},{\"heading\":false,\"text\":\"No voy a hacer historia, ni te enseñaría nada diciéndote que esta es la primera factoría europea que el arrojo de los portugueses abrió en los mares de China. Tampoco te importa saber que el mando de la isla esté confiado a un gobernador, teniente de navío; que existen un juez de derecho, un procurador de asuntos sínicos, una oficina de hacienda, encargados de obras públicas, sanidad, capitanía de puerto, una guarnición al mando de un comandante, jefes de fortificación, y media docena más de funcionarios portugueses, todos ellos amabilísimos y de franco y abierto carácter. Entre la colonia lusitana figura un señor don Lorenzo Marqués, dueño de una casa con un espacioso parque, en el que se encuentra la gruta de Camoens, compuesta de dos peñascos verticales y uno horizontal, apoyándose en aquellos a semejanza de _dolmen_ o altar druida, y en la cual el desterrado vate compuso la mayor parte de sus _Lusiadas_. Un templete con el busto de Camoens, y algunas estrofas de su poema esculpidas en mármol, alternan con ditirambos de poetas modernos de todas las naciones, figurando en muy buen lugar una octava de don José Heriberto García de Quevedo, ministro que fue de S. M. Católica en China.\"},{\"heading\":false,\"text\":\"Las señoras europeas son nones y no llegan a tres, como canta el dicho. De la raza macaense no sé qué decirte para darte una idea de su fealdad. Es imposible que nada en el mundo se parezca al cruzamiento de chino con portugués, ya de la metrópoli, ya de sus posesiones de Goa en la India, Timor en Oceanía o Cabo Verde y demás establecimientos del África occidental. Imagínate un _bull-dog_ con vestimentas humanas, y te quedas atrás. Por supuesto, no se tratan con ningún europeo, ni se las ve a ellas en ninguna parte; deben estar enmohecidas. Por las tardes se colocan detrás de las persianas (cierre ineludible de todo hueco de Macao), y desde allí ven sin ser vistas. Los días de fiesta van a misa, vestidas de negro, y cubiertas con un enorme manto de seda del mismo color, que pende hasta las rodillas, y en el que esconden la cara, en lo cual obran con gran prudencia; además, las que pueden usan silla de mano, con puerta apersianada también; es su único ventilador. Te aseguro que al contemplar aquellas recatadas damas, cruzando en sus literas las tortuosas y empinadas calles de la ciudad, alumbradas de noche por algún modesto reverbero de aceite, y empedradas de pedernal y guijarros en punta, le da a uno gana de calarse un chambergo con pluma, embozarse en un tabardo y ceñir una espada de cazoleta, para no destruir la armonía de un cuadro digno de la época de Velázquez.\"},{\"heading\":false,\"text\":\"Abolida en 1874 la emigración de culis o trabajadores para Cuba y el Perú, solo recurso, pero beneficioso, con que contaba Macao desde que la apertura del puerto de Hong-Kong le privó del gran tráfico con la Europa y la Oceanía, esta mísera colonia no cuenta con industria de ninguna clase, si no es la torrefacción del té, de la que están encargadas casas chinas. Se puede decir que los macaenses se hallan sumidos en la indigencia. Como puerto libre, el gobierno portugués no saca de ella más rendimientos que los que el juego público le procura; porque hay que notar que Macao es el Mónaco o el Baden-Baden del Celeste Imperio. El juego prohibido, perseguido y castigado severamente en todo el imperio, se ha refugiado en Macao, a la sombra de la bandera lusitana.\"},{\"heading\":false,\"text\":\"El chino, que posee todos los vicios, no podía dejar de ser jugador, y lo es, en efecto, en grado superlativo. Además del ajedrez, las damas, el billar y el volante, para el que se sirve de los pies con suma destreza, tiene cartas más numerosas que las nuestras (128 naipes), pero en estrechas tiras, como los dedos de las manos, y con caracteres en vez de figuras; dominó, con 32 fichas de madera, al que llama _Paí_; el _atchen_, o juego de tres dados, en que sobre un cartón, en que figuran los seis números de uno de aquellos y las combinaciones de los tres, apunta el jugador, y al que por onomatopeya se le da el nombre de _Kulú-Kulú_, pues imita el ruido que producen los dados cuando el banquero los agita sobre un platillo cubierto de una pequeña taza de porcelana. Estos y otros muchos juegos se juegan en mitad de las calles del bazar chino por culis y arrapiezos que apenas pueden tenerse en pie, y es muy frecuente el ver a dos chinos comiendo naranjas y apostando sobre los gajos que tendrán, o, a defecto de otra cosa, sobre las sillas que pasarán en tal transcurso de tiempo por la esquina en que están sentados.\"},{\"heading\":false,\"text\":\"Ya que de sentarse hablo, te diré que la manera que tienen de hacerlo los chinos y todos los pueblos del Asia es especial, e incomprensible que con ella hallen reposo. Abren las piernas, se dejan caer en cuclillas, sin tocar al suelo, y así se pasan horas enteras. Pruébalo y me contestarás.\"},{\"heading\":false,\"text\":\"Pero volvamos a los juegos y consignemos los tres más productivos para el gobierno portugués.\"},{\"heading\":false,\"text\":\"El _Pakopio_ es una especie de lotería antigua o primitiva, en la que, mediante una contribución, un comerciante chino es banquero. Al efecto, distribuye en todas las tiendas del bazar unos papeles o billetes como cartones de lotería con cuarenta caracteres arriba, y otros cuarenta abajo. Llega el jugador, y con un pincel borra a su elección cinco caracteres de la sección superior y otros cinco de la inferior, arriesgando en ellos el dinero que quiere. El banquero a su vez, y a una hora dada, antes de que empiece el juego en las tiendas expendedoras de billetes, ha borrado a su arbitrio otros cinco caracteres de cada sección, y depositado esta boleta en una caja, cuya llave tiene un delegado gubernativo. Ábrese esta al medio día, y los jugadores cuyas combinaciones son iguales a la que el banquero imaginó, cobran el premio proporcional a la suma expuesta. La operación vuelve a repetirse a las doce de la noche. ¡Dos extracciones diarias! ¡Oh moralidad!\"},{\"heading\":false,\"text\":\"El segundo en jerarquía superior es el _Fantan_. Doce son las casas, entre primera, segunda y tercera clase, que se consagran hasta media noche a tan plausible tarea, dejando al fisco un rendimiento de cuarenta y cuatro mil duros anuales en concepto de contribución.\"},{\"heading\":false,\"text\":\"Entras por una puerta adornada con calados dorados, como todas las casas lujosas de China, y alumbrada por linternas de papel de colores o de cola de pescado, con inscripciones. Un biombo de madera oscura, con los obligados calados, te oculta el lugar del suplicio. Tomas una escalerilla lateral, sucia y ennegrecida por el aceite de coco de las _iluminaciones_, y penetras en un cuartucho con un balcón o galería elíptica en el centro, que deja ver la sala de abajo, donde está el _tapete_. Algunas casas tienen otra galería en el segundo piso, tan falta de aseo como la del primero. Allí te sientas en un escabel de madera, forrado de grasa, en compañía de varios culis y europeos, que los sábados, en particular, vienen de Hong-Kong, y otros puntos a probar fortuna. Unas canastillas, pendientes de unas cuerdas sujetas a la baranda de la galería, te permiten hacer llegar a los de abajo el dinero que vas a exponer. Nada te digo de los perfumes que allí se aspiran entre efluvios de tabaco, tufo de las lámparas y eructaciones de los chinos, que consideran este desahogo como el más delicado refinamiento de cortesía, y en especial cuando uno está convidado en casa ajena para demostrar que la comida le ha sentado bien.\"},{\"heading\":false,\"text\":\"Veamos ahora el salón. Un público tan numeroso y escogido como el de las galerías, rodea un mostrador, cubierto, a falta de tapete, con una esterilla fina de junco, en el centro del cual hay como un ladrillo de plomo, cada uno de cuyos ángulos representa un número del 1 al 4. Un culi, desnudo hasta la mismísima región umbilical, es el encargado de colocar las apuestas donde el público le marca, y de pagar a los gananciosos (con 7 por 100 de descuento, que se reserva la casa para la contribución), o de cobrar íntegro de los perdularios. Otro caballero chino, en lucha anatómica con el primero, se entretiene en un aditamento del mostrador en ordenar los billetes de banco, pesar los duros mejicanos, que por aquí son la moneda corriente, y envolver en papelitos los fragmentos de plata, escribiendo encima el valor efectivo para facilitar las transacciones. Conocidos el cobrador y el cajero, pasemos al _croupier_, o tenedor de la banca. Es este, por lo común, un señor carnoso y tranquilo, que no exhibe lo que sus vecinos, no porque deje de estar tan desnudo como ellos, sino por impedírselo un pliegue abdominal que candorosamente descansa sobre la mesa. Tiene delante como quinientas o seiscientas _sapecas_. La sapeca es la moneda china de cobre en circulación; su diámetro es el de un cuarto de los nuestros, con un agujero cuadrado en el centro; cada ciento veinte forman dos reales. Las sapecas destinadas al _Fantan_ son, sin embargo, _ad hoc_, más perfectas y sin inscripción como las otras. Toma un puñado como de doscientas próximamente, y las coloca en el mostrador, cubriendo aquel promontorio con una pequeña tapa de latón para impedir que el público pueda contarlas con la vista, tapa que mientras está puesta, indica que puede hacerse juego.\"},{\"heading\":false,\"text\":\"Por fin la quita, y esgrimiendo una varita afilada por el extremo inferior, empieza con una delicadeza exquisita a separar con ella sapecas de cuatro en cuatro, hasta dejar una última porción que, según resulta ser de una, dos, tres o cuatro, da la ganancia a los que han jugado a estos números, amén de las infinitas combinaciones a que da lugar el sistema. Por supuesto, que cuando aún quedan por separar sesenta o más sapecas, hay jugador que ya sabe cuál va a ser el residuo. Dícese también que no obstante la vigilancia del público y el esmero con que la operación se practica, el banquero sabe sacar dos juntas cuando le conviene. De mí he de decir que he estado tres veces para enseñar este juego típico a extranjeros, y ellos y yo hemos perdido siempre.\"},{\"heading\":false,\"text\":\"Pero el que revela hasta dónde llega la pasión del azar en los sectarios de Confucio y su inmoralidad en grado supino, es el juego del _Vaisen_ o de los examinandos.\"},{\"heading\":false,\"text\":\"Si las instituciones chinas y sus preceptos sociales y políticos tuviesen en la práctica la observancia exigida por sus códigos, habría que confesar que era la primera nación del mundo, y tendríamos a honra el imitarlos. Pero nada más falseado en el ejercicio que las sanas doctrinas de sus moralistas y legisladores.\"},{\"heading\":false,\"text\":\"Hable el _Vaisen_.\"},{\"heading\":false,\"text\":\"En China no hay otra aristocracia que la del talento. Honores, títulos, condecoraciones, cargos públicos, todo, en fin, se le otorga al que más sabe, sin que el más oscuro y humilde del país deje de poder optar a la dignidad suprema. Al efecto, todos los años hay en Pekín y en Cantón, alternativamente, exámenes públicos, para cuyos ejercicios existen espaciosos locales con cuatro, cinco mil o más celdas, en las que, tapiados como los cardenales en la elección de Papa, ejecutan los examinandos sus composiciones; no creas que de ciencias exactas, naturales y físicas, no; toda la sabiduría de los celestes se reduce a conocer el mayor número de signos de que se compone su escritura, las máximas de Confucio y Mencio, y la genealogía de sus monarcas con hechos notables de su historia. Así obtienen el título de mandarín, que comprende nueve grados y se distinguen por el color del botón que colocan sobre el sombrero oficial, como te explicaré a su tiempo, con lo cual se hallan en aptitud para ejercer un destino público, el que, con una gran longevidad y un hijo varón, completa los tres mayores beneficios que estos señores se desean entre sí. Al terminar los exámenes de un año se reparten las listas de los examinandos para el siguiente, y aquí entra aquello. Fórmanse con estas listas millones de cuadernos en que figuran los nombres de los alumnos; estos cuadernos, que son otros tantos billetes de lotería, se venden a distintos precios a los jugadores, quienes marcan, como en el _Pakopio_, los nombres de los que juzgan que han de ser aprobados, ganando al terminar los exámenes en proporción de los nombres que acertaron y de la cantidad que representaba el cuaderno. ¡Qué sumas se jugarán al _Vaisen_ cuando el monopolizador de esta industria en Macao, único punto donde se tolera, paga al gobierno portugués cuatrocientos cincuenta mil duros anuales!\"},{\"heading\":false,\"text\":\"Excuso decirte que cuando se aproxima la época de los ejercicios, todo se vuelve recomendaciones a los catedráticos y ofertas pecuniarias para que desaprueben a fulano o a mengano, sobre el que se ha inclinado la balanza de las apuestas; o bien recurren al examinando mismo para que conteste mal a trueque de dinero. En fin, no hay género de cohecho ni de prevaricación que deje de ponerse en práctica, con lo que resulta una segunda lotería para alumnos y examinadores.\"},{\"heading\":false,\"text\":\"Ahora, antes de empezar a tratar al chino, acabemos de conocerle. Ya te he descrito al _culi_ macho y hembra, con su traje y su fisonomía; ambos son uno, salvo el que en la _patchama_ de las mujeres las mangas perdidas solo llegan a la mitad del brazo, que adornan con una pulsera de jade, como la ajorca del tobillo y los aretes de las orejas. ¡Coquetuelas en todas partes! Subiendo un peldaño en la escala femenina, tropezamos con la camarera o _ama_, como la llaman por aquí. Es la misma mujer culi, más limpia, con traje idéntico, si bien aseado, y con la patchama azul de lustrina ornada al canto con una faja negra de cuatro dedos. Usa zapatos con dos tacones, a proa y a popa, o de seda como el de los hombres, de forma agalerada, con una suela blanca de fieltro sumamente gruesa. Las hay que llevan medias de Europa; pero nunca se tapan la cabeza con _shalakó_ como las jornaleras; se preservan del sol con una sombrilla. Y ya se acabaron las hijas de Eva, puesto que la que ocupa una posición desahogada, la mujer de clase, si aquí puede llamarse de ese modo, no sale nunca de casa ni la ve, hasta después de casado con ella, el hombre mismo que ha de ser su marido.\"},{\"heading\":false,\"text\":\"Vamos a hablar ahora del famoso pie pequeño de las chinas. En todas las clases lo encuentras con profusión. He aquí cómo se practica esta bárbara costumbre. Al nacer la niña le descoyuntan hacia dentro, triturándoselos, todos los dedos, menos el mayor, le doblan el pie de modo que se apoye al andar sobre las falanjes, quedando el dedo gordo formando el empeine, y le maceran el talón, que desaparece por completo en el tobillo. Es decir, que el pie lo forma solo el dedo respetado; lo demás es un muñón informe. Naturalmente el zapato, estrecho y muy puntiagudo, de vistosos colores y bordados, y sujeto a la canilla por una faja para que se sostenga, resulta de una pequeñez inconcebible y se da al pie la apariencia de una pata de cabra. El origen de esta aberración nadie lo conoce, o mejor dicho, se le atribuyen varias causas. Pretenden unos escritores que fue por adulación hacia una emperatriz que, por lo diminuto de su pie, mereció ser española; suponen otros que es signo de distinción para dar a entender con ello que no necesitan andar y pueden pagarse una camarera que las sirva de apoyo, pues hay muchas que, sin este requisito, no dan un paso. Algo de esto último debe haber dado la inclinación del chino a hacer ver que puede derrochar dinero, y sus aficiones a lo simbólico y emblemático, como lo es también el dejarse crecer las uñas, muy ribeteadas por lo común, para indicar que no se consagran a tareas manuales. Mujeres hay que las llevan cubiertas con dediles, y en Siam se ven individuos con treinta centímetros de uñas, que concluyen por retorcerse en forma de tirabuzón.\"},{\"heading\":false,\"text\":\"Volviendo al pie pequeño, y respetando las opiniones de los que saben más que yo, opino, sin embargo, que hay otra razón para este martirio. Con la trituración desaparece por completo la pantorrilla; desde el tobillo a la rótula, la pierna no es más que una canilla; pero en compensación los muslos y las caderas adquieren un desarrollo fenomenal y muy en armonía con los gustos estéticos de los chinitos.\"},{\"heading\":false,\"text\":\"--¿Por qué no suprimen ustedes esa costumbre? --pregunté a un celeste de quien me asesoro para mis apuntes.\"},{\"heading\":false,\"text\":\"--Porque nos gusta --me respondió-- ver cimbrearse al andar a la mujer, que teniendo cuello de cisne, debe tener piernas de faisán.\"},{\"heading\":false,\"text\":\"--Pero eso es bárbaro --añadí.\"},{\"heading\":false,\"text\":\"--¿No lo es más el corsé europeo? --objetó en son de demanda.\"},{\"heading\":false,\"text\":\"--De ese modo condenan ustedes a la pobre mujer a no participar de ninguno de los goces de su sexo --proseguí eludiendo la pulla.\"},{\"heading\":false,\"text\":\"--¿Cuáles?\"},{\"heading\":false,\"text\":\"--El baile, verbi gracia.\"},{\"heading\":false,\"text\":\"--¡El baile! --me dijo soltando una carcajada--. Nosotros no bailamos nunca. Es una de las cosas que más nos llaman la atención en ustedes; que se sofoquen y echen los hígados para no gozar del espectáculo. ¿No sería más natural y más noble dejar bailar a los criados, y que los amos los contemplasen? Es lo que nosotros hacemos con los músicos y los juglares; nosotros los pagamos y ellos nos divierten.\"},{\"heading\":false,\"text\":\"--Tiene usted buenas ocurrencias.\"},{\"heading\":false,\"text\":\"--No, señor, es que ustedes tienen cosas muy raras.\"},{\"heading\":false,\"text\":\"--¡Hombre!\"},{\"heading\":false,\"text\":\"--Sí, señor, muy raras y muy inútiles. Así, por ejemplo, nosotros creemos que los botones están muy en razón en el traje cuando sirven para abrochar algo.\"},{\"heading\":false,\"text\":\"--Y nosotros lo mismo --le argüí.\"},{\"heading\":false,\"text\":\"--Entonces ¿por qué se ponen ustedes estos? --me dijo haciéndome dar media vuelta y señalándome los dos tradicionales botones del talle de la levita.\"},{\"heading\":false,\"text\":\"Ante tamaño argumento confieso que me quedé mudo. Desde entonces cada vez que marcha delante de mí un europeo, no puedo dejar de mirar aquellas dos obleas que me parecen los ojos del chino riéndose de las modas de París, y diciéndome: «Te veo».\"},{\"heading\":false,\"text\":\"En todas partes del mundo se nota diferencia en los rasgos fisonómicos entre un hombre de baja condición y otro educado. Hay en este último más delicadeza en los trazos, más suavidad en los músculos, más distinción en general. Aquí no; todos son iguales. El príncipe _Kung_, regente del imperio, el virrey de Cantón, el opulento empresario del opio, el mercader y el culi, son ejemplares del mismo cliché.\"},{\"heading\":false,\"text\":\"Una sola cosa los distingue, y es la mejor tela del traje. Todo el que no es culi usa _patchama_ de la misma forma que la de aquel, pero de merino o de seda cruda, de delicados colores celeste, violeta o amarillo de hoja seca. Los pantalones, de igual forma que unos calzoncillos, no de punto, van atados al tobillo sobre unos calcetines de lienzo blanco, muy ajustados del pie y anchos de la canilla. En invierno añaden unas _pistoleras_, o sea un segundo calzón sin fondillos, que deja ver el de abajo por detrás desde las corvas hasta arriba y un capotón guatado y sin mangas como el de los culis, pero limpio relativamente. La blusa se convierte en ellos en túnica talar llamada _Kavalla_, cuando se visten de gala, de igual forma y color que la _patchama_, pero descansando en los talones. La cabeza, en verano descubierta y garantizada por un paraguas, en los meses de frío se la tapan con una flanerita de seda negra del tamaño de un solideo y colocada como este.\"},{\"heading\":false,\"text\":\"El _boy_ o ayuda de cámara es el único chino de modales más desenvueltos y de rostro más simpático; yo creo que en ello influye su trato constante con europeos. Habla inglés o portugués, según la colonia en que habita, francés los de los puntos en que hay concesión de terreno a aquella nación, algunos alemán por análoga causa, y muchísimos español por haber permanecido en Manila o ido a Cuba en el período de la emigración. El boy es el jefe de todos los criados de una casa; las mujeres no hacen otro servicio que el de camareras. Se necesitan los siguientes: Un cocinero con siete duros mensuales: él provee el menaje de cocina y se agencia el pinche o aprendiz. Dos culis de silla; algunos tienen de cuatro a seis duros; encargados de la limpieza de la casa y de servirle a uno de acémila enganchados a la litera. Un _office coolie_, para las comisiones, correo y mandados burocráticos, con igual salario, y por último, el boy con ocho duros.\"},{\"heading\":false,\"text\":\"Reservados, respetuosos, fieles, salvo las pequeñas sisas, serviciales, exactos, aunque rutinarios en el cumplimiento de su deber, los chinos son un verdadero modelo de criados. No viven más que para adivinar lo que a su amo puede hacerle falta. Hace pocas noches, con el deán de la Catedral de Manila, que me hizo el honor de pasar dos días conmigo, me fui al Círculo; de allí nos trasladamos a una casa de _Fantan_ para que conociera este juego. A la salida, sobre media noche, advertimos que llovía; pero al trasponer la puerta, los culis de casa estaban allí con la silla, sin que nadie los hubiera avisado y en un sitio al que jamás concurro.\"},{\"heading\":false,\"text\":\"Un diplomático, amigo mío, asistió de uniforme a una comida oficial en Hong-Kong. Después se fue a tomar el té en casa de unos amigos; sintiéndose algo indispuesto, le obligaron a pasar allí la noche: al amanecer del día siguiente estaba su boy personado en la casa con el traje de levantarse y otro de calle para cuando su amo se despertara.\"},{\"heading\":false,\"text\":\"Te vas de paseo al campo, llega una carta para ti y el _office coolie_, como un podenco, se pone a olfatear tu rastro, sin que vuelva a casa hasta encontrarte y haberte dado la misiva.\"},{\"heading\":false,\"text\":\"Con su salario se mantienen, se visten y economizan para dar la mitad lo menos a su padre, o sostener su casa si no son solteros.\"},{\"heading\":false,\"text\":\"En cambio no les mandes nada que esté fuera de sus deberes. Cada cual tiene los suyos y no sale de ellos. _El office coolie_ no te encenderá una lámpara ni tomará una escoba, el culi de silla no te sacará una camisa del armario, el boy no irá con un recado a casa de tu vecino.\"},{\"heading\":false,\"text\":\"Ayer estaba en mi escritorio dándole unas instrucciones al boy; de pronto una ráfaga se me lleva todos los papeles.\"},{\"heading\":false,\"text\":\"--Cierra esa ventana --le digo. Él gira sobre sus talones, y desde la puerta grita:\"},{\"heading\":false,\"text\":\"--¡Culi! Ventana.\"},{\"heading\":false,\"text\":\"El culi, como si hubiera presentido la caricia de Eolo, estaba ya trasponiendo el dintel.\"},{\"heading\":false,\"text\":\"--¿Por qué no la has cerrado tú? --le grito al boy indignado. Y él sin alterarse, me contesta:\"},{\"heading\":false,\"text\":\"--_Not my business, sir._ No es de mi incumbencia.\"}]},{\"title\":\"Viaje a China — Macao, 18 de noviembre de 1879\",\"blocks\":[{\"heading\":false,\"text\":\"Mi querido amigo: Una representación teatral china es sin disputa lo que más llama la atención del europeo, acostumbrado a ver que entre los celestiales todo pasa al revés que entre nosotros. Así, por ejemplo, estar con la cabeza descubierta delante de una visita, se considera como signo irrespetuoso y hasta insultante. El lado izquierdo es el preferente en toda ceremonia. Una sonora eructación hacia el final de una comida, es la prueba más relevante de cortesía que puedes dar a tu anfitrión, para hacerle entender con ello que sus manjares te han sentado bien. Cuando a uno le llamas viejo, le prodigas el elogio más cumplido, y es hasta fórmula precisa preguntar a la persona a quien ves por la vez primera los años que tiene, y responderle que aparenta más edad. Por supuesto, ya sabes que escriben de arriba a abajo y de derecha a izquierda; de modo que sus libros, impresos en pliegos como los del papel de cartas por un solo lado, y encuadernados de manera que el doblez haga las veces de canto, formando una sola página lo que entre nosotros constituiría la primera y la cuarta, tienen el fin en el lugar en que en Europa se pone el principio.\"},{\"heading\":false,\"text\":\"Pues bien, todo esto son tortas y pan pintado en comparación de los templos en donde se rinde culto a Melpómene y Talía.\"},{\"heading\":false,\"text\":\"Los chinos son idólatras del teatro: es una verdadera pasión la que tienen por estos espectáculos, en que se representan batallas y pasajes de su historia, alternados con entremeses, de autor siempre anónimo, pues entre ellos es oficio vil el de dramaturgo, en lo que muy pronto creo que los vamos a imitar en Europa, si seguimos por donde andamos.\"},{\"heading\":false,\"text\":\"Pero vayamos por partes.\"},{\"heading\":false,\"text\":\"Las compañías, por lo menos las que yo he visto, están compuestas de hombres solos, y es notabilísima por cierto la habilidad con que los encargados de los papeles de mujer las imitan _en todo_; llegando la perfección hasta el punto de remedar el pie pequeño de las chinas, formado con un taruguito de madera que se colocan en la punta de los dedos, y con el que tienen que andar de puntillas. Su identificación con la metamorfosis es tal, que hasta fuera de la escena se los toma por mujeres. Me han asegurado que hay compañías exclusivamente formadas por el bello sexo y otras mixtas; y verdad debe ser, por cuanto las leyes chinas niegan a las actrices el derecho de contraer matrimonio legal, relegándolas a la condición de concubinas.\"},{\"heading\":false,\"text\":\"Estas compañías, más o menos numerosas, se dividen en de 1.º, 2.º y 3.er orden, y llevan una vida nómada y errante, como la de nuestros antiguos _faranduleros_, trabajando allí donde los ajustan, si bien su adquisición es siempre disputada. Rara vez son empresarios los actores.\"},{\"heading\":false,\"text\":\"Lo que llamaremos temporada dura cinco días consecutivos, y los artistas reciben por su trabajo una remuneración que varía entre 600 y 1,500 duros.\"},{\"heading\":false,\"text\":\"Generalmente los teatros se improvisan con bambú en los pueblos de poca importancia; pero donde las representaciones son frecuentes, hay edificios de planta, hechos de ladrillo y yeso, a cuya categoría pertenecen los dos que posee Macao.\"},{\"heading\":false,\"text\":\"La sala es un rectángulo. Dos órdenes de lunetas de madera oscura, separadas por un callejón en el centro, componen, como en nuestros coliseos, el patio, al que concurre la gente acomodada. Estas lunetas están separadas de la pared por un ancho pasillo a cada lado, a los que de pie y gratis asiste el pueblo. En el primer piso hay dos galerías laterales para señoras y caballeros preferentes. En el segundo y en el fondo, paralelamente a la escena, se levanta un graderío para todos, como el paraíso del Real, cuyas delanteras, separadas del _vulgo_ por una barrera y de los vecinos por un tabique, son los palcos para las autoridades de la Colonia.\"},{\"heading\":false,\"text\":\"Los precios de las localidades varían desde un real hasta cinco. Las paredes, que en algún tiempo debieron estar enlucidas de yeso, no están ya más que relucientes de mugre, y jamás hubo mano de pintura en ellas ni en el maderamen, negro por tan distintas y frecuentes fumigaciones. Alguna que otra lámpara de aceite de coco, despabilada a intervalos por culis (_coolies_), vestidos lo estrictamente necesario para no poder decir que van desnudos, alumbran y asfixian al público. El traje del que no paga y el de la muchedumbre de a real, viene a ser como el del culi. Los de los _caballeros_ y _señoras_ ya nos son conocidos. Pero hay otra clase de Evas, luciendo _patchamas_ de la forma invariable china, si bien bordados en sedas de colores vistosísimos, que por las flores de su peinado, los oropeles de su prendido y el blanco de magnesia y rojo de ladrillo con que embadurnan sus mejillas, para imitar a las grandes damas, acusan a la legua su triste condición de _hetairas_. Su misión se reduce a dar testimonio con su presencia de la prodigalidad del que las alquila. Y en efecto, el chino, ostentoso por naturaleza, no la lleva allí con fin alguno ulterior: el oficio de aquella mujer termina con el espectáculo. Aquel buen hombre necesita hacer ver que se ha gastado en tal circunstancia algo más que el precio del billete, y ha convidado a aquella criatura, para que esté sentada junto a él, le abanique, le rasque y le prepare la pipa; pues se me olvidaba decir que todos, sin distinción de sexos, fuman durante la representación, comen y beben y _se dicen que les ha sentado bien_.\"},{\"heading\":false,\"text\":\"En los pasillos hay puestos donde se confecciona toda clase de alimentos, desde el pastel hasta la morcilla asada, que aún humeante, sirven por la sala los dependientes de los abastecedores. Imagínate el olor que allí habrá, si agregas a esto el que todos los descartes de la naturaleza se llevan a cabo donde al público le place. Aquello es un vasto _jardín_. ¡Quién fuera alcalde de barrio de Sevilla para poder poner aquel célebre aviso: «_¡No se premite jumar en el zalon ni llevar castora ni náa que puea incomodal ar veyo sejo!_»\"},{\"heading\":false,\"text\":\"Se me pasaba por consignar un detalle. Las representaciones dan comienzo a las siete de la noche, continúan hasta las cuatro de la madrugada, se suspenden hasta las once, y terminan a las cinco de la tarde. El que tiene sueño echa allí su siestecita y ronca. Los ruidos alternan con los perfumes.\"},{\"heading\":false,\"text\":\"Pasemos a la escena, poco elevada sobre el nivel del público. Figúrate una decoración de sala cerrada; pero que en vez de ser de tela y madera, sea de ladrillo y yeso, es decir, fija, invariable, sin más puertas que dos pequeñas en el fondo, y adornada con pinturas y hojarascas de talla dorada. De los muros penden grandes tarjetones encarnados o negros, donde con caracteres de oro se consignan el nombre de la compañía y sus títulos. Dos pasillos laterales interiores, prosecución de los que en el público sirven para espacio gratuito, conducen al foro, donde en un solo recinto se hallan la guardarropía, la sastrería, el vestuario y todas las dependencias.\"},{\"heading\":false,\"text\":\"En el centro del escenario está la orquesta destinada a acompañar a los ejecutantes. Su instrumental se compone de una especie de rabel o violín de una sola cuerda, una o dos guitarras chinas, desmesuradamente grandes, y con la caja en forma de concha, una como a modo de dulzaina, címbalos, gong o campana china, un tambor convexo de metal, como una cazuela pequeña, tocado con palillos, y unos crótalos que producen el sonido de nuestras castañuelas. Todo el proscenio está invadido por un centenar de culis, parte de ellos espectadores, otros guardarropas, despabiladores y dependientes, colocados, como los coros de las óperas en los teatros de provincia, en fila a guisa de soldados de papel. Comprenderás, por lo dicho, que el espacio libre para representar se reduce a unas cuatro varas en cuadro.\"},{\"heading\":false,\"text\":\"Las decoraciones, cualquiera que sea el sitio en que pase la acción, se reducen a una mesa tosca de madera con una silla de bambú a cada lado. Si el teatro representa una casa rica, revisten las sillas de un paño encarnado. Cuando se trata de un accesorio que juega algún papel en la obra, como por ejemplo, un árbol a cuyo pie debe sentarse un personaje, cúbrese el asiento de un paño negro, al que se sujeta un cartelón que dice: «Árbol.»\"},{\"heading\":false,\"text\":\"Fácilmente se ve hasta dónde puede llegarse por este camino de la ideología. Algunas veces la mesa se convierte en cama, agregándose unos riquísimos cortinajes: es el único lujo, pero preciso, que se permiten en la _mise en scène_.\"},{\"heading\":false,\"text\":\"Desterrados del teatro los trajes de la dinastía reinante de los Tsing, raza tártara de la Manchuria, los artistas usan los de la época de los Ming, pura rama celestial o del imperio del Centro, que son lujosísimos, raros hasta lo indescriptible, y de que solo puedo darte una ligera idea, recordándote los personajes de ciertos abanicos y de algunas porcelanas antiguas del país. Carecen de consuetas y de traspuntes, y todo va fiado a la memoria; con la particularidad de que el público conoce casi siempre la obra tan bien o mejor que los actores, a quienes nunca aplaude, reduciéndose la manifestación de su agrado a un murmullo de aprobación.\"},{\"heading\":false,\"text\":\"La mímica es entre los chinos el fundamento de la declamación; todo lo componen con gestos. Un personaje que escribe, otro que come, no se servirán nunca del pincel (que es su pluma), ni de la taza o los palillos (que forman el plato y el cubierto); con las manos dan a entender como pueden lo que hacen; y sin duda para ellos debió escribir aquel libretista del baile _El robo de las Sabinas_, la célebre acotación que decía: «Los romanos dejan ver por sus ademanes que carecen de mujeres.» Los chinos lo hubieran interpretado sin apurarse.\"},{\"heading\":false,\"text\":\"Hay, sin embargo, algunos utensilios de que se sirven como símbolo: por ejemplo, el personaje que figura estar montado lleva como látigo una cola de caballo; el que navega blande un remo, porque es de notar que la acción no se interrumpe nunca ni se subsanan ciertas justificaciones con recursos de arte. Si alguien dice que se va de Cantón a Pekín, y la escena que sigue tiene ya lugar en el sitio de su destino, es preciso que emprenda el viaje, ejecutando todos los medios de locomoción de que ha de servirse, llegando a tal extremo la escrupulosidad de estos detalles, que no omite el de cerrar la puerta, bajar la escalera y golpear el aire con sus nudillos cuando figura que llama en otra casa.\"},{\"heading\":false,\"text\":\"Pero lo más raro sin duda en este convencionalismo, es la manera de dar a entender que uno de los interlocutores no ha oído lo que los otros se han dicho aparte. Consiste el movimiento en volver la espalda al público.\"},{\"heading\":false,\"text\":\"Siguiendo por la vía de los emblemas, no te sorprenderá el saber que, para demostrar un personaje que es hipócrita y de doble intención en sus actos, se pinta las narices con una mancha blanca. Por supuesto que abundan las prosopopeyas o personificaciones de ideas, entre las cuales he visto a la inspiración, vestida como de arlequín, penetrar en el cerebro de varios examinandos que concurrían a un certamen del grado de mandarines, dando brincos por encima de sus cabezas.\"},{\"heading\":false,\"text\":\"Su literatura dramática no puedo yo apreciarla, aunque conozco algunas traducciones de obras antiguas. Sin embargo, sé de ella lo bastante para consignar que los entremeses modernos son, en su mayoría, obscenos y repugnantes, pintura fiel y exacta de sus costumbres. En ellos ves títulos como este: _El castigo de una mujer que no ha tenido hijos varones_, circunstancia que entre los celestiales autoriza al marido a tomar concubina legal; como verás cuando te dé a conocer al chino en familia. Son de larga duración, sin estar divididos en actos, o constando de uno solo. Se representa y se canta en ellos, siendo de notar que, tanto los personajes masculinos como los femeninos, cantan en falsete con unas modulaciones imposibles de comprender, y llevando un compás muy parecido a un laberinto. Añade el acompañamiento de aquellas chicharras, y el ruido infernal del gong y los platillos, que aprietan sin compasión al final de cada pieza, y tendrás una idea de cómo se rinde aquí culto a Euterpe. Esto no obsta para que en Pekín haya un ministerio que se llama de la música.\"},{\"heading\":false,\"text\":\"Yo he asistido a la representación de una obra, que es la historia de un matrimonio, a cuyos contrayentes otorga el cielo, _coram populo_, el beneficio de un hijo en la forma de un muñeco de cartón, y a cuya paternidad legal puede el público servir de _testigo de prueba_.\"},{\"heading\":false,\"text\":\"Por la contra, existen obras antiguas de un delicioso carácter y de una intención filosófico-social del mejor cuño. Juzga por este relato.\"},{\"heading\":false,\"text\":\"Tchuang-Tsen es un sabio y viejo confucista, casado con la hermosa Tián. Un día que el marido se paseaba por el monte, observó junto a una tumba a una linda mujer aventando la tierra con su abanico. Preguntándole lo que aquello significaba, contestóle ella que aquel sepulcro era el de su marido, que al morir le había impuesto la obligación de no volverse a casar hasta que la tierra de su lecho de muerte estuviese completamente seca, y que trataba de ver si con sus esfuerzos lograría lo que la naturaleza se empeñaba en negarle: secarla.\"},{\"heading\":false,\"text\":\"El sabio, que al mismo tiempo tiene sus ribetes de hechicero, compadecido de la pobre viuda, hace que la humedad de la tumba desaparezca, lo que ella acoge con evidentes muestras de júbilo, llenando de caricias a Tchuang-Tsen, y concluyendo por regalarle su abanico. De regreso a su casa, entera a Tián de lo ocurrido, y esta, que demuestra ser mujer rígida en sus principios e intransigente en cuanto con la decencia y la consideración se relaciona, se desata en improperios y llena de dictados a aquella mujer, que tan pronto y sin recato alguno olvida el respeto debido a su difunto esposo.\"},{\"heading\":false,\"text\":\"--Lo mismo harías tú y todas --le contesta el sabio.\"},{\"heading\":false,\"text\":\"--Nunca --replica Tián--. Eso es indecoroso e impropio de mujer que se estima.\"},{\"heading\":false,\"text\":\"Finalmente, tras una larga discusión, cada uno se queda con su razón, sin avenirse.\"},{\"heading\":false,\"text\":\"A los pocos días, Tchuang-Tsen cae enfermo, y se muere. Tián se abandona al más vehemente y más ostensible dolor. Terminadas las ceremonias fúnebres, mete el cadáver en la caja, y se dispone, según la usanza china, a guardarle en la cámara mortuoria los tres o cuatro meses de rigor entre la gente rica.\"},{\"heading\":false,\"text\":\"En este intervalo, llega a la casa Wang-Sun, joven y apuesto mancebo, que ignorando la muerte de Tchuang-Tsen, venía con una carta de recomendación, desde lejanas tierras, a ser su discípulo y compartir con él su hogar. La viuda le da alojamiento hasta que disponga su regreso, y ambos lloran al difunto, encomiando las excelencias de su carácter y sus virtudes. Pero el diablo las carga, y de _fil en aiguille_, como dicen los franceses, Tián concluye por enamorarse de Wang-Sun, que, nuevo José, quiere buscar en la fuga amparo contra las tentaciones de la viuda del Putifar chino. La pasión de Tián se excita con su esquivez, y por fin... ambos se ablandan.\"},{\"heading\":false,\"text\":\"Entonces óyense golpes en la caja; Wang-Sun, aterrado, echa a correr; Tián, con mano trémula, abre el féretro, y lo halla vacío. Vuelve a la sala en busca de su amante, y se encuentra con su marido Tchuang-Tsen, que la recibe con una carcajada, y le explica que es él quien ha tomado la forma de Wang-Sun, concluyendo con esta frase:\"},{\"heading\":false,\"text\":\"«¡Vamos! ¿Te convences de que lo mismo sois todas?»\"},{\"heading\":false,\"text\":\"Los hechos históricos que en el teatro se representan, son más bien escenas gimnásticas, en las que los combatientes se entregan a saltos muy notables, luciendo trajes lujosísimos y armas de una rareza ejemplar, cuya autenticidad es notoria, pues aún se usan, y las describiré a su tiempo cuando te hable de mi visita al virrey de Cantón.\"},{\"heading\":false,\"text\":\"Lo original de estas representaciones es el combate. Si la crónica refiere que el héroe de la leyenda mató a quinientos combatientes, no cesará el espectáculo mientras los comparsas no hayan pasado otras tantas veces bajo el filo de su espada, que él blande de un modo muy artístico, figurando que mata con ella a sus enemigos; hasta que al fin, para indicar que la lucha ha terminado, coge una cabeza de cartón que está sobre la mesa, y hace como si la derribara de un tajo. Entonces retumban vivas y gritos de victoria, y cercándole de banderas, se lo llevan en triunfo; el público murmura, y si no cae el telón por no haberlo, sale uno a respirar el fresco ambiente de la tarde.\"}]},{\"title\":\"Viaje a China — Macao, 26 de marzo de 1880\",\"blocks\":[{\"heading\":false,\"text\":\"Mi querido amigo: Ya te he dicho que en vano busca uno colores en China; pues lo mismo sucede con los olores (salvo los malos, peculiares de este país), los ruidos, los afectos y las pasiones. Todo aquí es vergonzante o rudimentario; no hay nada franco y decidido. Aspirando bien, llegas a encontrar a la flor algún perfume recatado y modesto; las frutas no son ni agrias ni dulces, pero sí insípidas; los instrumentos músicos carecen de sonoridad, su ruido es _mate_; chinos y chinas cantan en falsete, sin vibraciones en la voz y en el diapasón de la confidencia; se diría que hacen música en secreto. No extrañarás, por lo tanto, el saber que en China no hay amor, con lo que probado queda que no hay nada: lo que no obsta para que los estadistas difieran en reconocerle de cuatrocientos a quinientos millones de población, que es una apreciable diferencia. Esto indica que hay familia en el sentido de la multiplicación. Veamos cómo está organizada esta operación aritmética.\"},{\"heading\":false,\"text\":\"El nacimiento de una hembra es una desgracia en el hogar. La ley protege al marido cuya mujer no le ha dado hijos varones, y le autoriza a tomar concubina legal. La superstición, base de esta sociedad, va aún más lejos, y madres hay que considerando como un castigo celeste el no tener sino hijas, las matan, por aplacar el enojo divino. Venderlas es cosa frecuente; por dos reales adquieres una niña de tres o cuatro años. No hace muchos días vino una madre a regalarnos la suya, en agradecimiento de unos juguetes que a su hijo le habían dado los míos.\"},{\"heading\":false,\"text\":\"Es tan inconcebible lo que voy a contarte y tan frecuente en los escritores el inventar por producir efecto, que, aunque te consta mi veracidad, creo de mi deber repetirte bajo palabra, para satisfacción de tus lectores, que estas correspondencias no tienen otro mérito que el de la exactitud, _reducidos sus detalles las más veces a las menores proporciones_, pues cosas hay que no sabe uno cómo decirlas, y que no obstante se deben dar a conocer.\"},{\"heading\":false,\"text\":\"Entre muchas hermanas hay siempre una que es la predilecta de los padres, predilección que debe trascender al público, lo que consiguen colocándole en un lado de la cabeza el tuferito de pelo que las demás ostentan en mitad del occipucio, hasta que ya adultas unas y otras, dejan crecer la parte afeitada y adoptan el peinado de soltera o el de casada, aun siendo célibes, si no quieren consagrarse al matrimonio. Por supuesto, no las enseñan a leer ni a escribir, y su educación se reduce a empezar a comprimirlas el pie desde que tienen cuatro años, para destinarlas a esposas, que necesariamente han de ser de pie pequeño. Hablo de las clases acomodadas, pues los pobres, como en todas partes, hacen lo que pueden, y se casan sin miramiento a la base.\"},{\"heading\":false,\"text\":\"Muchas de estas desgraciadas mujeres quedan relegadas a la condición de concubinas de algún chino acomodado, o pasan a ser mercancía vil del transeúnte, porque sucede que, si joven aún, cae enferma, _in articulo mortis_ la madre la vende a una curandera, que se encarga de cerrarle los ojos y sufragar su entierro; pero si sana, la empírica, que a su profesión agrega el oficio de zurcidora de voluntades, queda dueña exclusiva de la infeliz, y la explota hasta que ella puede emanciparse mediante un rescate pecuniario.\"},{\"heading\":false,\"text\":\"La _elefantíasis_, esa terrible enfermedad hereditaria conocida vulgarmente con el nombre de _lázaro_, hace en China estragos horrorosos; y la mujer que por desgracia cuenta algún lazarino en su abolengo, es llevada por su propia madre a esos centros de la higiene pública, donde cubriéndose treinta y seis veces de oprobio, asegura la superstición que desaparece el germen del mal.\"},{\"heading\":false,\"text\":\"Pero nace un hijo y la decoración cambia; no creas que hay bautizo ni inscripción civil; toda la ceremonia se reduce a celebrar tan fausto suceso con una comilona, mucho más copiosa para el mayorazgo que para los demás hermanos varones que le sigan: derecho de gradación que se refleja en todos los actos de la vida china, alcanzando hasta la herencia, de la que, excluidas las hembras, toca a cada hijo una parte tanto mayor cuanto aventaja en años a sus hermanos menores.\"},{\"heading\":false,\"text\":\"El padre pone un nombre a su antojo al chico, y este lo conserva hasta que se halla en disposición de empezar su instrucción primaria. Entonces lo cambia, operación que verifica también al casarse y al desempeñar un cargo público. Los emperadores mudan asimismo de nombre al subir al trono, al entrar en la mayor edad y al ser juzgados después de su muerte por los censores, quienes le conceden el dictado con que han de ser conocidos en la historia.\"},{\"heading\":false,\"text\":\"Empieza, pues, el muchacho por estudiar los caracteres de que se compone su lengua, y que se elevan a la enorme cifra de 85,000. Conocer la mayor cantidad posible de ellos constituye el desideratum de los chinos. Escritura ideológica trazada con pincel de arriba abajo y de derecha a izquierda, cada signo de sus más de doscientas radicales corresponde a la representación de un objeto, y combinados, producen esa multiplicidad de caracteres a cuya absoluta posesión no hay nadie que haya podido llegar todavía. Agrega a esto el que cada signo tiene una pronunciación monosílaba y que cada monosílabo es susceptible de ser pronunciado de cuatro maneras diferentes, y tendrás una idea, aunque remota, de las dificultades de la lengua.\"},{\"heading\":false,\"text\":\"El idioma oficial es el mandarín o pekinés, existiendo además muchísimos dialectos o _puncti_ (lengua del país), entre los cuales el más generalizado es el cantonés. El populacho y la gente de mar hablan una jerga conocida con el nombre de _Aka_.\"},{\"heading\":false,\"text\":\"Como en China no hay universidades ni centros de enseñanza oficial, el muchacho tiene que estudiar con maestros particulares, empezando por imponerse en moral según las máximas de Confucio, retórica, historia la estrictamente necesaria para conocer la cronología de sus reyes, pues la de los demás pueblos maldito lo que les interesa; filosofía con las ampliaciones de Mencio a los preceptos de Confucio y comentaristas de este, y legislación, la cosa menos parecida al derecho que puedas suponer.\"},{\"heading\":false,\"text\":\"Y aquí se acabó toda la enseñanza. Lo importante es obtener un grado de mandarín, única aristocracia personal, no hereditaria, en China, a la que tiene opción el individuo cualquiera que sea su origen, y que si se otorgase exclusivamente al mérito, en vez de adjudicarse al mejor postor, justificaría en los chinos el dictado de celestiales con que se adornan; pero ya te dije al hablar de los juegos cómo se verifican estos exámenes.\"},{\"heading\":false,\"text\":\"Nueve son los grados de mandarín y se distinguen por el botón o bellota con que adornan su sombrero. Este es como una gorra de _jockey_, a la que se le añadiese, en lugar de visera, un ala o baranda como la de un sombrero calañés ceñida al casquete, es decir, sin vuelo y tan alta como este, teniendo por remate en el centro de la copa, su borla de fleco encarnada y el botón distintivo de la categoría. Su efecto es el de un cubo de ancha base, puesto por la boca sobre el cráneo.\"},{\"heading\":false,\"text\":\"El botón rubí o rojo transparente, es el signo de los mandarines de primera clase, la más elevada. Su número es de veinticinco. Seis están en el ministerio, quince presiden los tribunales de provincia y cuatro tienen a sus órdenes al ejército. Todos ellos han de ser letrados y forman el Consejo del emperador.\"},{\"heading\":false,\"text\":\"El botón rojo coral opaco, lo usan los mandarines de segunda clase, en la que están comprendidos los magistrados y jefes militares, y los de los ramos de la administración pública, entre ellos los gobernadores de las provincias.\"},{\"heading\":false,\"text\":\"El zafiro o azul transparente, corresponde a la tercera clase, o sea a los presidentes de los tribunales de segundo orden, en las provincias, estando comprendidos en la cuarta los individuos de estos mismos tribunales con derecho al uso del botón azul opaco.\"},{\"heading\":false,\"text\":\"La quinta y sexta, relativas a cargos públicos de menor importancia, se diferencian por el botón blanco transparente y blanco opaco; y la séptima, octava y novena, que abrazan los maestros de instrucción y los encargados de la vigilancia y conservación del orden público, ostentan el botón dorado, ya liso, ya trabajado a cincel.\"},{\"heading\":false,\"text\":\"Su número total asciende a 25.000; de ellos, 15.000 pertenecientes a ramos civiles y 10.000 al ejército, si bien estos pueden triplicarse en caso de guerra.\"},{\"heading\":false,\"text\":\"Los cuatro grados principales son: el de _siut-sai_ o bachiller, cuyos exámenes escritos, verificados por el sistema celular y juzgados por tres tribunales distintos a pliego cerrado y con lema, como en los concursos poéticos, tiene lugar anualmente en las ciudades todas del imperio. El _siut-sai_ se subdivide en _ling-sen_, que con sueldo del Estado, sirve a las órdenes de mandarines de alto rango; en _seng-seng_ o agregado del _ling-sen_, con sueldo temporal, y en _fu-hio_, o sea una especie de alumno de la normal dedicado a la enseñanza.\"},{\"heading\":false,\"text\":\"El grado inmediato superior es el de _Ku-jin_ o licenciado, el primero que da aptitud para aspirar a los cargos públicos, y cuyos exámenes, verificados como todos, por el mismo sistema celular, tienen lugar en la capital de la provincia.\"},{\"heading\":false,\"text\":\"El de _Tsin_ o doctor, y el de _Ham-ling_ profesor, han de pasarse en Pekín. Todos los gastos en época de exámenes, son costeados por el emperador. Y ya en aptitud por razón de su categoría, lo mismo desempeña el mandarín un cargo en la magistratura que en la administración, en el ejército que en la marina. Lo compra y luego lo usufructúa como mejor le place, con arreglo a la tarifa de su capricho. Ya te he dicho que, una vez mandarín, el chino puede y debe dejarse crecer el bigote.\"},{\"heading\":false,\"text\":\"Llegada la época de casar al muchacho, lo que si es mandarín no tendrá efecto sino con hija de mandarín precisamente, he aquí lo que ocurre. En primer lugar los novios no se conocen; uno y otro ignoran en absoluto con quién van a compartir la existencia. Una casamentera de oficio arregla con los padres de los contrayentes las condiciones del contrato, en las que para nada interviene el dote, pues no le hay. Basta saber que la novia es de pie pequeño y su familia de posición análoga a la del novio. Si es posible, se procura que los dos contrayentes hayan nacido en el mismo día de la luna (los chinos computan por lunaciones), si bien en año diferente, en atención a que ella debe ser más joven. Te diré de paso que, como para los celestiales el ser viejo es un título, todo chino cuenta adelantado, y desde que nace tiene un año: de modo que cuando realmente cumple uno, para él son dos.\"},{\"heading\":false,\"text\":\"Unos días antes del destinado para la ceremonia, recorren las calles multitud de culis, harapientos como siempre, cargados con los regalos de la novia, consistentes en provisiones de boca para un mes, y el ajuar; todo metido en cajas, sobre las que hay unos letreros expresando el contenido, que nunca es tan ostentoso como reza el cartel, dado el defecto de ostentación de la raza.\"},{\"heading\":false,\"text\":\"El día de la boda, a las nueve o las diez de la noche, la novia se viste con lo peor que tiene; deshace su peinado de soltera, y a medio hacer el de casada, se despide de su madre. Es condición precisa que alborote la casa, fingiendo gran desesperación; y así la bajan hasta el zaguán, donde la espera la silla nupcial, palanquín cerrado por todas partes y adornado de vistosa talla, que se alquila _ad hoc_, y en el que la meten a puñados y como por violencia, al compás de sus berridos, ahogados por los golpes del gong, la dulzaina, el tamborete convexo de metal y los cohetes del séquito, compuesto de culis provistos de linternas de papel de todos tamaños y hechuras.\"},{\"heading\":false,\"text\":\"Antes de salir del hogar paterno, la madre arroja sobre la silla unos puñados de arroz y unas gotas de vino, extraído de este grano, para que la abundancia acompañe a su hija, y puesto un velo rojo a modo de cortina sobre el palanquín, la comitiva se pone en marcha hacia la casa del novio, seguida de la casamentera y de un marrano abierto en canal y asado, con que la suegra tiene que obsequiar necesariamente al yerno. En cuanto este advierte la proximidad del cortejo, sale a la puerta y espera que depositen la preciosa carga. Su primer cuidado es descorrer el velo que cubre la litera y llamar a su esposa, que continúa lanzando ayes como si la desollaran viva. Si el novio acepta con gusto el matrimonio, lo demuestra llamando a su mujer merced a una patada que da contra la puerta del palanquín; si, por el contrario, la boda le viene cuesta arriba, se concreta a golpear la silla con los nudillos. Por fin, ábrese el castillo encantado y la novia se presenta cubierto el rostro en señal de rubor. La casamentera la toma sobre sus espaldas, y como pudiera hacerlo con un fardo, la sube las escaleras y la deposita detrás de la cama, sobre el duro suelo. Síguela el marido, contempla a su cónyuge, y si no es de su agrado, se presenta ante los circunstantes con el abanico metido en la babucha; pero si merece su aprobación, se lo coloca entre el pescuezo y la _cavalla_ o túnica, cena con los circunstantes y remite a su suegra la cabeza y el rabo del cerdo, en testimonio de satisfacción absoluta.\"},{\"heading\":false,\"text\":\"La noche se pasa devorando, bebiendo té, disparando cohetes y oyendo aquella música infernal. A la mañana siguiente tiene lugar la recepción de los parientes y amigos, provistos de su correspondiente regalo. Una vez reunidos, colocan a la novia en el centro, y las mujeres que la rodean principian a decir todo género de obscenidades y conceptos libres, que aquella debe escuchar con aparente rubor, pues el acto envuelve una especie de examen de su inocencia. Restituida al hogar paterno, y convencida la madre de que su hija ni ha sido impaciente ni ha faltado al recato, descósele las vestiduras que iban unidas entre sí para que no pudiera ser despojada de ellas, lávale la cabeza, la casamentera la adoba el peinado de casada, y con los aderezos propios de su condición, regresa definitivamente a casa de su marido, donde tiene sus habitaciones reservadas o su _gineceo_, inaccesible al sexo fuerte extraño a la familia.\"},{\"heading\":false,\"text\":\"La mujer, degradada y envilecida en el Celeste Imperio, no come jamás con su marido, quien no titubea en sentarse a la mesa con los últimos culis de su servidumbre; y mientras no tenga un hijo varón, está en el deber de considerarse como la esclava de su suegra.\"},{\"heading\":false,\"text\":\"El adulterio contra mujer legítima o primera, es decir, no concubina, es castigado de muerte _sin substitución_; pues en los demás casos de pena capital, el reo puede comprar substituto, y la ley se da por satisfecha con decapitar a un hombre que se avenga a purgar el delito ajeno.\"},{\"heading\":false,\"text\":\"Los chinos, ostentosos por naturaleza, toman concubinas sin limitación, como cuestión de lujo, aun cuando su mujer les haya dado hijos varones. Todas habitan bajo el mismo techo y en perfecta armonía; pero los hijos de las segundas mujeres no pueden llamar madre sino a la esposa legal (de quien son criadas las otras), si bien gozan de toda consideración y derechos, incluso el de primogenitura, como hijos legítimos que son según sus Códigos.\"},{\"heading\":false,\"text\":\"Uno de los cuidados más importantes del chino es hallarse rodeado de los suyos en el momento de la muerte; el hijo mayor es el encargado de dar a las cenizas de sus padres los honores más exagerados posibles, honores que a veces conducen hasta a la ruina. Vayamos por partes.\"},{\"heading\":false,\"text\":\"Desde el instante en que principia la agonía de un celestial, todos los suyos rodean el lecho y prorrumpen en exclamaciones de dolor, que cesan en cuanto aquel espira, pues, rituales, más que espontáneas, tienen por solo objeto dar al moribundo un postrer testimonio de consideración; y muchas veces se alquilan llorones de oficio, si la familia no es bastante numerosa para armar todo el ruido de precepto.\"},{\"heading\":false,\"text\":\"Con las ansias de la muerte se ponen a hacerle el tocado, incluso peinarle, operación que en las mujeres invierte horas enteras; y acto continuo le revisten de todos los trajes que constituyen su ajuar, puestos unos sobre otros, a fin de que en la otra vida no carezca de abrigo. Ya en las postrimerías, le arrojan de la cama abajo, pues ningún chino debe morir sino en el duro suelo, y cerrados los ojos, guardan el cadáver durante tres días, en los que los bonzos, con los invariables instrumentos de gong, chirimía o dulzaina y timbalillo de metal, se entregan en la casa mortuoria a sus oraciones fúnebres, acompañados de los parientes más cercanos, que se distinguen por una montera de tela blanca con que cubren la cabeza. El luto consiste en ponerse el cordón de la coleta de color azul y revestir la casa con entrepaños de papel celeste, también con caracteres dorados, en los que se consignan el nombre del finado y las máximas sobre el respeto debido a los que ya no son.\"},{\"heading\":false,\"text\":\"Transcurrido aquel plazo, meten el cuerpo en una caja cuadrilonga con una especie de medias cañas superpuestas en toda la longitud de sus lados, lo que, vistas por sus testeros, le da la apariencia de una flor de cuatro hojas, y en tal estado conservan el cadáver en la casa dos, cuatro meses y hasta un año, según los medios de que dispone la familia, pues en todo este intervalo continúan las preces, y por consiguiente los gastos.\"},{\"heading\":false,\"text\":\"Llegado el día del entierro, se reunen parientes, amigos, llorones, bonzos y músicos, y precedidos de dos con estandartes de madera, se dirigen al sitio de la inhumación. Si el muerto es pobre, le dan sepultura en el cementerio general, que es el lomo de una colina sin tapia ni cercado, lleno de pilares de piedra, donde está inscrito el nombre del que debajo reposa.\"},{\"heading\":false,\"text\":\"Si, por el contrario, se trata de un rico, el féretro es transportado a veces a centenares de leguas de distancia, a la tumba que, el finado en vida o el hijo a su muerte, ha adquirido en virtud de informaciones dadas por una especie de agoreros o adivinos, que viven de esta especulación. Su misión es estudiar el terreno, siempre montuoso, en que el cadáver hallará más dulce bienestar, y que mejor se adapte a sus condiciones de carácter, según las revelaciones atribuidas a sus sortilegios. Inútil es decirte que los tales arúspices se ponen a menudo de acuerdo con el propietario de un yermo invendible; y que, abusando de la supersticiosa credulidad en que todo chino incurre, llega hasta a hacer pagar a su cliente cien mil duros por lo que no valdría veinticinco en buena venta.\"},{\"heading\":false,\"text\":\"La tumba china afecta invariablemente la forma de Omega, o para los que no sepan griego, de una corcheta, mucho más elevada por el centro de la curva que por los extremos, y con el espesor suficiente para contener un cuerpo humano entre el doble tabique de su línea. Su diámetro alcanza catorce o más metros; el hueco central está esmaltado de flores, y una verja de caprichosa forma circuye, aunque no siempre, el todo.\"},{\"heading\":false,\"text\":\"La comitiva enciende grandes teas de ramas secas, con las que a los cuatro vientos se ponen todos a dar golpes al aire para ahuyentar los malos espíritus, operación muy frecuente en los actos de la vida china, concluido lo cual dan sepultura al muerto, gritan otro ratito, y depositando en la tumba comestibles y otras menudencias, se da por terminado el acto.\"},{\"heading\":false,\"text\":\"La idea de que el espíritu del muerto anda errante, y puede carecer en la otra vida de los artículos más necesarios, incluso el dinero, hace que el chino esté enviando constantemente remesas a sus deudos de todo género de cosas; pero como el procedimiento saldría muy caro, han inventado un expediente tan original como lucrativo para los que a tal industria se dedican. Consiste este en la fabricación de enseres fúnebres de papel representando corpóreamente sillas, mesas, barcos, literas, caballos, armas, camas, pagodas y hasta dinero (pedacitos cuadrados de talco pegados sobre una cuartilla de papel de estraza); todo lo cual se vende en multitud de almacenes especiales, para que los chinos lo quemen diariamente, y convertido en humo, lo hagan llegar a su destino. En fin, conduce a tal extremo la superstición de estas gentes sobre el particular, que, aunque algo en desuso, todavía se practica una bárbara costumbre; al dar sepultura a un chino opulento, entierran vivos con él a dos o más muchachos para que desempeñen con el muerto las funciones de criados... y otras.\"}]},{\"title\":\"Viaje a China — Macao, 30 de enero de 1881\",\"blocks\":[{\"heading\":false,\"text\":\"Mi querido amigo: Los chinos computan por lunaciones y por los años de entronizamiento del príncipe reinante. Hoy, es, pues, primer día de luna del año séptimo del emperador Kuang. La única fiesta, propiamente hablando, que le está concedida al celestial, y cuya duración es generalmente de treinta días. Es condición indispensable que nadie entre en el año nuevo sin haber pagado todas las deudas contraídas en el anterior; de ahí el que a la espiración de diciembre los artículos de lujo se vendan en las tiendas por la mitad del precio, la estadística de hurtos, nunca robos, aumente de una manera considerable, y los prestamistas no puedan dar abasto a los clientes.\"},{\"heading\":false,\"text\":\"Quince días antes del que hoy se conmemora, las transacciones se paralizan; el chino, comerciante con lonja abierta o propietario con casa cerrada --como lo están todas las que no son expendedurías, pues el prurito del celestial es que nadie inspeccione sus actos, y para ello fabrica su vivienda a cubierto del murallón que adopta por fachada-- todo confucista, budista o taotista, en fin, barre o manda barrer su hogar; operación que no vuelve a repetir hasta el año siguiente, pues entre otras preocupaciones, tiene la de creer que quitar las inmundicias, es ahuyentar la fortuna. Tanto es así, que el mayor castigo que en su superstición puede dársele a un celestial, es condenarle a pobreza eterna, pasándole una escoba por la cara. Y por mi nombre, que deben ser riquísimos, a juzgar por los ostensibles signos de economía de que hacen alarde.\"},{\"heading\":false,\"text\":\"Engalánanse los almacenes con hojarasca de papel de oro y de colores, con flores de artificio, con macetas de plantas naturales, algunas de las cuales, por su rareza, alcanzan ciento o más duros de valor; ilumínase todo con arañas, linternas y candelabros; dispónese en el centro una mesita cubierta con riquísimo tapete de seda recamado de oro, sobre la cual el dragón sagrado u otro ídolo de su devoción recibe la ofrenda de las golosinas que los visitantes han de comerse después, y da comienzo al disparo de millones de pequeños cohetes, con que sin interrupción están saludando a la luna.\"},{\"heading\":false,\"text\":\"Al principiar el año nuevo, o sea a las doce de la noche, pues nadie duerme para no entrar en él con malos sueños, todo el mundo --menos la mujer de condición que vive siempre reclusa-- échase a la calle a contemplar las iluminaciones, aspirar el olor de la pólvora, asistir a los espectáculos teatrales y decir Kon-ji o sea «viva» al deudo, pariente o amigo. Amanece, y desde aquel punto las tiendas, cuyo cierre además de la puerta ordinaria, consiste en gruesos barrotes verticales de madera al exterior, ingeniosamente atrancados por una traviesa que los sujeta todos por dentro, quedan cerradas, a excepción del postigo, para dar paso a las visitas. Estas las constituyen _caballeros_, que aquel día no parecen millonarios por lo limpios que se ponen, que van a comer alguna golosina y a emborracharse jugando a la morra, o sea a acertar el número de dedos que entre los jugadores presentan simultáneamente. Al revés que entre nosotros, el que pierde es el que queda obligado a beber, y el que gana el que paga el vino de arroz, único que ellos conocen y que liban en tazas microscópicas de porcelana. Aunque la embriaguez llega a su colmo en estas fiestas de Baco, ni hay que deplorar nunca una consecuencia triste, ni en esta ni en otra época del año se encuentra un chino beodo por la calle. La morigeración de este pueblo, en lo que a costumbres públicas se refiere, es ejemplar. ¿Será la civilización el germen de nuestros vicios? Creamos que no, y pasemos adelante.\"},{\"heading\":false,\"text\":\"Por supuesto que en ese día no puedes contar con ninguno de tus servidores; tienes que andar a pie, prescindir de recados y darte por muy feliz si, en gracia de los aguinaldos recibidos, alguno de ellos se digna hacerte la cama y darte de comer algo frito, para acabar pronto. Desde muy temprano vienen todos a prosternarse en tu presencia, y en seguida echan a correr al bazar a comprarse zapatos, de que hacen provisión para los doce meses restantes; pues nadie deja de estrenar algo en año nuevo; y hasta los pobres de solemnidad, a falta de otra cosa, renuevan el cordón con que se trenzan la coleta. En cambio ellos te obsequian con toda clase de dulces, desde el de toronja o zambúa, hasta el de guisantes en vaina azucarados; y te regalan cohetes.\"},{\"heading\":false,\"text\":\"Entre las clases acomodadas el ceremonial es el mismo, sin más diferencia que el hacerse a cencerros tapados. Se saludan por tarjetas, pedazos rectangulares de papel grana, de un palmo de largo, con tres o cuatro caracteres negros, del diámetro de un napoleón; se envían presentes comestibles, y se visitan con el ritual que te explicaré al hablarte de _mis relaciones sociales_ con los hijos del cielo. Poco a poco el bullicio va perdiendo en intensidad, y quince días después todo torna a su natural estado.\"},{\"heading\":false,\"text\":\"Los chinos celebran otras festividades; pero en ninguna de ellas se cierran los establecimientos ni se suspende la vida pública. La conmemoración de los difuntos, que tiene lugar durante la cuarta luna, se reduce a quemar objetos de uso doméstico, simulados en papel, que por ese medio creen enviar a los errantes espíritus para que no carezcan en la otra vida de lo necesario. Lo más notable de este rito son las visitas a las pagodas que entonces se construyen a expensas de los consumidores, pues se sufragan con el producto de una especie de subsidio con que todo expendedor recarga sus ventas anuales y que religiosamente entrega a la comisión encargada de alquilar o adquirir los adornos y de dirigir los festejos.\"},{\"heading\":false,\"text\":\"Estas construcciones, que ocupan un área como la plaza Mayor de Madrid y tienen una elevación como la de la nave del Escorial, están hechas exclusivamente de bambú sin el auxilio de un clavo ni otra trabazón que la de sus muescas y nudos. De aquellas inmensas bóvedas penden millares de lámparas y objetos de adorno, cuyo peso maravilla que puedan resistir unos soportes tan débiles en apariencia. Las lucernas, algunas de las cuales sustentan hasta cien globos de luz, tienen sus brazos y machones revestidos de diminutas plumas de un pájaro azul turquí que se confunden entre filamentos de oro con el más acabado esmalte de orfebrería. El interior de las pagodas no puede describirse; es de un efecto maravilloso, hasta para los europeos acostumbrados a ver prodigios en los concursos universales de la industria. Sobre colosales armazones de sutil mimbre, vuelan por el espacio gigantescas mariposas, aves e insectos de flores naturales con todos los matices y perfumes de que es susceptible la naturaleza de la zona tropical. Alternando con estos ramilletes y encuadradas en magníficos marcos de talla, vense representaciones esculturales de tamaño natural y de movimiento, recordando pasajes de las mejores obras dramáticas; cuyos personajes, luciendo los trajes de la pasada dinastía Ming, son un asombro de lujo, con tamaña profusión de sedería bordada, que nadie ha podido aún igualar en perfección ni en opulencia. Más allá los bronces del culto y suntuarios se mezclan con los vasos y discos del más puro caolín, de los tiempos remotos, confundidos a su vez con los monstruosos bloques de verde jade o de sanguinolento mármol de la Tartaria. Mientras la susurrante fuente humedece las espirales de humo perfumado que exhalan centenares de pebeteros, los ídolos búdicos, de quince codos de altura, resisten con sus atléticos brazos los arranques del entablamento, y las obras más acabadas del recamo de oro y plata sobre seda, cuelgan desde el friso hasta el pavimento como ramificaciones de un Pactolo aéreo e inagotable. Es la primera vez que he visto realizado el esplendor de mi China soñada. Desgraciadamente solo dura la ilusión ocho días al año. Quince minutos han bastado muchas veces para que un incendio lo devorase todo y produjese innumerables víctimas; pero ¿quién se resiste a visitar de noche aquel admirable conjunto, realzado con millares de luces y transparentes de tan delicado gusto como caprichosas formas? Desgraciadamente el encanto huye con solo fijarse en el sucio porte de la concurrencia. No hay compensación.\"},{\"heading\":false,\"text\":\"Contrastando con esta magnífica exposición, llega la fiesta del plenilunio de la octava luna; manifestación modesta, pero imprescindible, del culto budista. En ella se conmemora el aniversario de la creación por Dios del astro de la noche. Todo chino permanece en su casa, y aguarda con la ventana abierta y a oscuras a que la casta Selene haga su aparición en la rendija del firmamento que le permite ver su angosta calle; y, apenas la divisa, le alumbra candelillas, le quema pebetes, la saluda prosternándose hasta el suelo y come en su honor un pedazo de pastel, confeccionado exprofeso con tocino y almendra para aquella solemnidad, cuya virtud no se me alcanza; pero te diré acerca de su consumo, que una sola pastelería de Hong-Kong produce anualmente a cada uno de sus cinco socios, la enorme cifra de diez mil pesos fuertes. Verdad es que se trata de un pastelero más famoso que el mismo de Madrigal.\"},{\"heading\":false,\"text\":\"Otro espectáculo que realmente tiene importancia y novedad para el europeo es una procesión de linternas. Estas no se verifican en épocas determinadas; son expansiones accidentales que se permite sufragar, ya un vecino acomodado a quien un negocio le ha salido bien, ya un gremio que solemniza una circunstancia memorable, ya, en fin, un barrio que impetra el favor del cielo ante una enfermedad epidémica. Porque, aunque retarde con una digresión su relato, debes saber que aquí la medicina no constituye facultad ni se aprende en colegio alguno. Todo es empirismo; no hay más que curanderos, cuyo mérito está en proporción del número de recetas que poseen. Su diagnóstico es muy sencillo: para ellos las enfermedades se reducen a fuego o aire. Su terapéutica aún lo es más. El fuego lo apagan con jugos de vegetales, y el aire lo sacan con ventosas y con cauterios. De ahí que no haya chino que no tenga el cuerpo, y en especial el cuello y la cabeza, lleno de cicatrices y quemaduras. El tifus, que en China se llama fiebre del cabello, consiste, a su juicio, en una como venita o hebra capilar que circula por el cuerpo llena de sangre corrompida y que hay que extraer. Para asesorarse de que el enfermo padece semejante dolencia, le dan a saborear un manjar amargo; y si lo halla dulce, es prueba inconcusa de que el mal existe. Entonces hay que buscar el sitio en que puede encontrarse el cabello, y si dan con él, lo extirpan vaciándole la sangre inficionada. Poseen, sin embargo, algunos medicamentos de virtud reconocidísima; y no puedo resistir a la tentación de transcribirte el que para combatir el cólera emplean en el Ton-Khin. Se lo debo a nuestro compatriota el Reverendo Padre monseñor Colomer, natural de Reus, obispo y jefe de nuestras misiones en aquella región de Annam; que siempre lo ha usado con resultados satisfactorios. Tuéstanse al horno unos cangrejos, mejor de río que de mar; machácanse bien con su cáscara; se disuelve media cucharada de aquellos polvos en una copa pequeña de buen vino añejo y se le da a beber al paciente. Generalmente basta con la primera dosis; pero si el mal no cediera, se repite la operación. Suele ocurrir que al desaparecer el cólico, se paralizan también los descartes diuréticos. Para provocarlos y combatir la irritación que origina aquel estado, no hay sino machacar vivos, y por consiguiente crudos, dos o tres cangrejos; mezclarlos con igual cantidad de vino y de la misma clase que en el procedimiento anterior, y, colado su jugo, dárselo a beber al enfermo.\"},{\"heading\":false,\"text\":\"Volvamos ahora a la procesión de linternas, a la que concurren todos los vecinos del barrio con objetos de su exclusiva confección o alquilados a industriales al efecto; pero de un modo o de otro, llevados a cabo con una perfección asombrosa. El elemento principal de ellos, como de casi todos los adornos chinos, es el papel, y una pasta de arroz transparente como el cristal, y muy parecida, aunque más pura, a nuestra cola de pescado, que adaptan primorosamente a unos armazones de mimbre o bambú finísimo.\"},{\"heading\":false,\"text\":\"En cuanto anochece, se reúne el cortejo en el lugar de la cita; y al estampido de algunos morteretes y de algunos millares de petardos, da comienzo el desfile por el orden siguiente: abren la marcha unas cuantas docenas de individuos, vestidos como todos los que componen la procesión con los pintorescos e indescriptibles trajes de la época de los Ming, llevando piras embreadas en recipientes de metal, que iluminan el espeso humo que van produciendo. Síguense unas banderas más grandes, pero idénticas en corte a las de los gremios valencianos, puestas sobre el hombro del porta-estandarte y en sentido horizontal. Y allí principia un ascua de fuego producida por cuatro o cinco mil linternas de todos tamaños, formas y colores, levantadas sobre unas perchas, cuyo río de luz corta de trecho en trecho, ya un grupo de músicos con címbalos, crótalos, dulzaina, timbales, discos convexos (sobre los que repican con una sola baqueta) y el obligado gong; ya unas pagodillas del tamaño de nuestras andas, llenas de molduras y rodeadas de pebetes; ora unas mangas y parasoles de espléndido tisú de oro, parecidas a las del culto católico; luego los monstruosos ídolos de la teogonía búdica. No ha concluido aún la sorpresa que te producen el insecto, el pájaro, el buque, el jarrón, el kiosco y el templo montados con flores naturales y circuidos de puntos luminosos, cuando te arranca un nuevo grito de admiración el niño que, simbolizando un guerrero mitológico cabalga sobre un microscópico caballo de los confines del desierto de Gobi, enjaezado a la usanza mandarina y cubierto de gualdrapas dignas del tocado del imperial jinete; te encanta la imaginación que han desarrollado en la gigantesca concha con todos los cambiantes de la madrépora, en cuyo seno descansa una elegante china simulando una perla del río de Cantón, o te seducen el albérchigo y la naranja que, abiertos en gajos, presentan a tus atónitos ojos, humanas simientes en la clásica agrupación del arte asiático. Pero donde está el mérito sobresaliente de la procesión, es en la infinita variedad de aquella multitud de linternas, donde parece haberse agotado la fuerza imaginativa de la inspiración del hombre. Sin detenerme a describir los faroles ordinarios, pequeños unos y colosales otros, ostentando un carácter chino, que ya por sí constituye un adorno singular; pasando en silencio los tulipanes, girasoles, estrellas, globos y pirámides; ¿cómo no llamar la atención el racimo de uvas de luz, contrastando con el oro de su fruto el verde tono de sus pámpanos; las dos medias sandías con la púrpura de su seno salpicada de relucientes pepitas; la carpa, el salmonete y el atún abriendo la boca y agitando sus aletas; los dos gallos combatiendo con la saña de la verdad; el pavo que se esponja ante la contemplación del auditorio; la langosta que despide aletazos o contrae y dilata sus articulaciones; el faisán de Shang-hai; los monstruos gesticulantes emblema de las pasiones humanas; y por último, las monumentales pagodas con sus cubiertas agaleradas, sus frisos esculpidos y sus afiligranados detalles --más numerosos y sutiles que los de la arquitectura gótica-dejando escapar por el mosaico de su policromía torrentes de luz y de perfumes? Una guardia, provista de partesanas y lanzones dignos del lápiz de Gustavo Doré, precede a un hombre con cabeza de león (animal fatídico de esta fauna mitológica), huyendo ante el dragón sagrado, que lo persigue para ver si lo puede devorar. Es la lucha de la virtud con el vicio. Este dragón, de formidables fauces y armado con anillos que le permiten plegarse a discreción de los doscientos hombres que lo llevan sobre puntales de bambú, está forrado de seda verde transparente, y va alumbrado por dentro. Tiene más de cien metros de longitud, y se considera como un favor celeste y un signo de felicidad el que incline la cabeza delante de la casa de uno. El favorecido le dispara entonces unos millares de cohetes en justo reconocimiento, y el reptil se libra a una graciosa y bien combinada serie de ondulaciones, contrayéndose, dilatándose y retorciéndose en espirales luminosas.\"},{\"heading\":false,\"text\":\"Terminaré mi catálogo de festejos con la descripción de los fuegos artificiales, a que son muy aficionados los chinos. Para el concurso del gran _patchon_ (cohete), se exhiben con anterioridad en un barracón los premios consistentes en un espejito de mano, un transparente, un ramo de papel de talco, o cualquiera zarandaja por el estilo, que ellos en dar no son muy pródigos.\"},{\"heading\":false,\"text\":\"Llegada la tarde de la lucha, colócase el pirotécnico sobre un tablado y empieza a disparar voladores. La muchedumbre, apiñada alrededor, observa la dirección de la caña; aguarda a que baje, y entonces hace prodigios de agilidad por apoderarse de ella; con lo cual y consecuente con la superstición que preside todos sus actos, no solo alcanza ventura para sí y los suyos --mayor cuanto es más gordo el cohete-sino que obtiene una recompensa, quedando obligado a sufragar otra para la justa del año siguiente.\"},{\"heading\":false,\"text\":\"Sus tan decantados fuegos artificiales, repetidos con frecuencia y siempre con igual monotonía, no tienen de particular más que la candidez. Divídense en diez o doce actos, y cada uno de estos en tres transformaciones, lo que da lugar a que el espectáculo termine a las cuatro de la mañana habiendo empezado apenas anochecido. Allá va un acto por cuyo patrón están cortados todos los demás. Princípiase por disparar en medio de la calle y sobre una mesita, una cantidad de voladores con poca o ninguna luz, muchas chispas, profusión de humo y largos compases de espera. Luego la escena se traslada a un catafalco, sobre el que se alza un andamiaje de bambú de la altura de una casa de cuatro pisos. Ízanse en él tres como bombos, de cuádruple diámetro que el de los de una orquesta, en que van encerrados los fuegos. Se aplica una mecha al inferior, y después de diez largos minutos, el armazón se abre y deja ver una maceta con una planta cuyas hojas van cambiando lentamente de colores. Llegado el turno del segundo tambor, aparece una rueda horizontal, en que dan vueltas unas figuras de movimiento que montan a caballo, se apean, riñen o se abrazan, pero todo tan diminuto, alumbrado por unas lucecitas de tan poca intensidad y tan envuelto en humo, que solo el espectador de primera fila puede apreciarlo. La última caja contiene el _bouquet_; y en honor de la verdad, algunos de ellos no dejan de llamar la atención, pues fatigada la vista con tanto inútil esfuerzo, gusta de que la sorprendan con una masa luminosa; y lo consigue una gran torre transparente de forma octógona, que se desprende desde lo alto del andamiaje hasta el suelo, llevando pendiente de cada ángulo de su tejado una sarta de linternas encendidas, que ni sabe uno darse cuenta de cómo se alumbran, ni se explica que puedan caber en tan estrecho recinto.\"},{\"heading\":false,\"text\":\"Fiestas de Hon-Kung en Macao\"}]},{\"title\":\"Viaje a China — Macao, 26 de septiembre de 1881\",\"blocks\":[{\"heading\":false,\"text\":\"La primera parte la constituye la afluencia de cien mil forasteros a una ciudad de sesenta y ocho mil almas; se albergan donde pueden, duermen donde se albergan y comen en la alcoba: no he nombrado la calle porque se sobreentiende.\"},{\"heading\":false,\"text\":\"Cuatro días de fiesta: ni una borrachera, ni un robo, ni una disputa.\"},{\"heading\":false,\"text\":\"¿Quién es Hon-Kung? No lo sé, ni tengo tiempo de estudiarlo en este momento. Es, según voz pública, el primero, después de Dios, de los santos de la corte celestial china. Se le invoca para que conceda paz a todo el imperio, le preserve de epidemias y le otorgue riquezas innúmeras; participa, por consiguiente, del Jano de los paganos, del San Roque de los católicos y de la lotería de los españoles.\"},{\"heading\":false,\"text\":\"En el cómputo chino, cada tres años traen uno bisiesto, que se compone de una luna más de veintinueve o treinta días en la lunación séptima, época en que debe verificarse la fiesta del santo; pero como no siempre hay dinero disponible, redúcese aquella a una modesta manifestación, transcurriendo a veces catorce y más años sin que tenga efecto una solemnidad como la que voy a describir, y que en la ocasión presente ha sobrepujado a cuanto se ha hecho hasta ahora en Macao, matriz, metrópoli, casa solariega del festival en cuestión.\"},{\"heading\":false,\"text\":\"¿Cómo se arbitran los fondos? Como no puede copiar ningún pueblo que no tenga la buena fe, el patriotismo, el amor, en una palabra, del celestial a su enorme familia de cuatrocientos millones de individuos con coleta. Todo comerciante con tienda abierta está obligado a recargar cada objeto que vende en cinco _sapecas_ (cada sapeca vale medio maravedí), que entrega religiosamente a una comisión económica, la cual se encarga de aumentar los productos con el interés que hace ganar al dinero y con los donativos espontáneos de los particulares, cuyos nombres figuran después inscritos en sendos papeles encarnados en el pabellón central del barrio chino. Desde el año 1868 hasta hoy se han recaudado sesenta mil pesos fuertes, que son los que se han invertido en _alquiler_ de los objetos de ornamentación para la ceremonia: calcúlese por ahí el valor intrínseco de este Pactolo de oro, seda y luces.\"},{\"heading\":false,\"text\":\"Describamos, si podemos:\"},{\"heading\":false,\"text\":\"Una cruz griega forma la parte engalanada del Bazar; son dos calles perpendiculares que se cortan casi por el centro y a cada una de las cuales puede que el kilómetro le venga como a su medida. Unos armazones, o andamios de bambú, atados con hojas de la misma caña, y sin que en su sostenimiento entre un clavo, se elevan hasta por encima de las casas, produciendo en algunos sitios tres cúpulas superpuestas de una elevación como el cimborio del Escorial. Todo aquel armazón se cubre con lo que ahora diré; y el vecino a quien le tapan una ventana, ni se queja al alcalde, ni habla mal del gobierno; come a oscuras, y se calla.\"},{\"heading\":false,\"text\":\"Reviste el techo un lienzo de colores abigarrados con flores, hojarasca, animales y quimeras, del que penden tulipanes, peces, frutas e infinitas representaciones, que no son sino otras tantas linternas que le dan el aspecto de una bóveda tachonada de puntos luminosos. Hasta poco más de la altura de dos hombres, caen, sujetos por gruesas maromas, millares de lucernas, arañas, girandolas y quinqués, cuya forma no hay medio de describir ni por su variedad ni por su complicación. Voy a ver si, ciñéndome a una sola, logro hacerme comprensible. Figúrense los lectores la Catedral de Milán reproducida materialmente en madera, con siete metros de altura, y todo el resalte de filigrana de oro. El fondo para el profano es de esmalte azul; para el observador que lo toca y se convence de que la paciencia del hombre pueda llegar a tal límite, es de plumas microscópicas de alción o martín pescador, pegadas con cola. Añádansele centenares de estatuitas esculpidas en pirámides o en racimos como los grupos de los juegos acrobáticos; e iluminándola con doscientos globos de luz con colgantes o lágrimas de cristal de todos los colores del prisma, se sabrá lo que es una de estas lámparas, como se sabe que el punto que asoma en la lontananza del mar es un vapor, porque se ve el humo con el catalejo.\"},{\"heading\":false,\"text\":\"Sin que la bóveda se venga abajo por el enorme peso que resiste, sustenta además de todo lo que es luz, una asiática profusión de gigantescas mariposas, dragones colosales, caracteres chinos titánicos y un centenar más de variantes en ramos de flores; que no otra cosa son los tales monstruos sino la parte perfumada de la naturaleza, adornada con pedazos de espejo y cintas de seda y oro.\"},{\"heading\":false,\"text\":\"Nosotros decimos que todo pende de Dios, pero los chinos deben creer que todo pende del bambú; porque después de lo que dejo colgado, aún faltan unos centenares de cajones con veinte o treinta figuras de medio tamaño natural en cada uno, reproduciendo escenas de los dramas y entremeses más notables de la dramática celeste. La encarnación de los personajes es perfecta; el indumento riquísimo, y las armas, como el sable que le regalé a un sobrino mío en ciertas Navidades, y que, según él, era de _buena verdad... de carne_.\"},{\"heading\":false,\"text\":\"Las calles están cortadas a trechos por arcos de triunfo _colgantes_; pues son sin pies, no tienen más que un cornisamento y un gran friso, se estriban en las paredes y los sostiene el entablamento. Cada arco parece el puente de los Suspiros en Venecia.\"},{\"heading\":false,\"text\":\"Todas las fachadas de las casas están literalmente cubiertas, desde el zócalo hasta el alero del tejado, de ricas obras de talla, altos y bajos relieves, cuadros de algunos metros con figurillas hacinadas del color del lapislázuli, hojarascas de ricas maderas aromáticas, otras doradas, transparentes y adornos policrómicos, mientras cada puerta (que lo es de una tienda) se halla convertida en una pagoda con su altar en el centro, su ídolo, flores, pebetes y ofrendas de comestibles. A intervalos una música deleita al transeúnte (si es chino) con sus chirriantes ecos, o un juglar luce sus habilidades sobre un estrado.\"},{\"heading\":false,\"text\":\"Pero donde está la verdadera maravilla es en el pabellón principal; vasto recinto, colosal nave formando la cabeza de la cruz, y en el que, lo que ya llevamos visto, está centuplicado en profusión y en riqueza. ¿Qué hay allí? Yo no sé si podré explicarlo. Lucernas, cuadros, flores, relieves, esculturas, cincuenta mil nombres de contribuyentes o donantes, músicos, un teatro en el fondo con representación permanente y quince mil espectadores, además de otros dos coliseos que funcionan en las calles contiguas, y millares de macetas que parecen receptáculos de plantas y son vasos de prodigios: aquel arbolillo, que se tomaría por un juguete de Nuremberg, es un ejemplar liliputiense del corpulento ébano guardando todas las proporciones debidas en sus microscópicos detalles. Un arbusto que más allá simula un león hecho con astas de venado, es una raíz que a fuerza de mutilaciones, injertos, paciencia y sabiduría, ha tomado aquella forma en un transcurso de doscientos años tal vez, y con el concurso de seis o siete generaciones. Lo mismo digo del carácter chino que está a su lado; con la apariencia de una rama de boj recortado recientemente para aquella circunstancia, es no obstante un tronco con sus brazos y hojas educados desde hace siglos para concluir por simular el nombre de una divinidad, de un emperador o de un simple individuo. Que hay planta de ellas que vale dos mil pesos, no hay para qué consignarlo.\"},{\"heading\":false,\"text\":\"La calle termina por un inmenso altar a cada lado, defendido por dos gigantes de cartón; cuya cabeza, como los telamones del orden atlántico, sostiene el piso. En el pebetero que hay delante arde todo un tronco, de madera de sándalo. Relicarios de filigrana de algunos metros de tamaño, cajas y linternas de orfebrería, monstruos y quimeras de metal, apoyados en el suelo y enroscándose hasta la bóveda, cascadas de paños bordados de oro y sedas, vasos de jade y otras piedras preciosas; todo está allí hacinado, como si la mano de un Pluto invisible hubiera removido las entrañas del universo para hacer ante la humanidad el inventario de su riqueza.\"},{\"heading\":false,\"text\":\"Hablemos ya de la procesión. Esta en algunos casos suele ir por dentro; pero en el presente va por todas partes, porque es de rigor que pase por la casa de cuantos a ella han contribuido. No se extrañará por lo tanto que el desfile, que dura más de dos horas a paso de marcha, con raras detenciones de un minuto a lo más, empiece a las ocho de la mañana, termine a las seis de la tarde y tenga que reanudarse durante tres días consecutivos.\"},{\"heading\":false,\"text\":\"Relatar todo lo que va en ella y por su turno correspondiente, es tarea superior a mi asendereada memoria. El oro, la seda y los adornos que hemos visto en el bazar, constituyen su base. Pero asusta pensar que el traje más modesto de la comitiva no baja de doscientos pesos de valor, que pasan de tres mil los asistentes, y que no hay medio de contar las banderas monumentales de raso recamado de oro, los estandartes de sedas flojas, los parasoles de plumas de pavo real, los bronces suntuarios, vasos de jade, mármoles sanguinolentos, maderas preciosas y tanto y tan infinito detalle de un exagerado precio, ya por su rareza como por su antigüedad o mérito artístico.\"},{\"heading\":false,\"text\":\"Aunque variados hasta la saciedad, he aquí el patrón de los dos figurines, que dan la norma en esta especial indumentaria.\"},{\"heading\":false,\"text\":\"Las congregaciones de chinos ricos llevan el tradicional zapato de galera bordado; media blanca con polainas de cintas de seda de colores hasta la rodilla; calzón de satín blanco; blusa de _lo_, color de plomo claro; faja de gró muy ancha que forma como un delantal, y cuyos cabos bordados en seda y oro de relieves valen un dineral: cordón de torzal grana en la coleta y esta enroscada sobre la frente; un sombrero tártaro de paja, igual a los paveros de España, forrado de gró, y con caracteres y adornos de terciopelo y oro en la copa; y el inseparable abanico de plumas de cisne, ensartado en la cintura por detrás, lo que les da el aspecto de una cola de palomo.\"},{\"heading\":false,\"text\":\"Todos llevan su correspondiente _culi_ o criado portador del banquillo para reposarse en las paradas.\"},{\"heading\":false,\"text\":\"El otro traje yo no lo sé explicar. Se compone de una túnica y una sobretúnica bordadas; mejor diré, empedradas de oro y plata, comparables tan solo, aunque más ricas, a los vestidos de luces de nuestros toreros. Los sombreros, ya representando un enorme tulipán con franjas de seda, ya un capacete o casco con aletas y plumas de faisán, son de lo mismo, y el efecto general es el de un ejército de astros.\"},{\"heading\":false,\"text\":\"Con ellos alternan los mandarines modernos en traje de gala, con vestas y capacetes de seda del mismo color en cada individuo, y mil reproducciones del iris entre todos; los bonzos, de cabeza rasa, y los ejecutores de la justicia (séquito de los grandes personajes), con sus hopalandas negras, uno como cencerro de mimbre oscuro en la cabeza, y portador cada cual de un instrumento de suplicio.\"},{\"heading\":false,\"text\":\"A las banderas, grandes como las de los gremios valencianos, suceden niños a caballo en traje de emperadores de la dinastía de los _Ming_. Detalle curioso; entre las cabalgaduras figuraba un pollino, especie rarísima en estas regiones. A aquellos siguen timbaleros redoblando sus tamboretes de metal (porque aquí se puede repicar y andar en la procesión); andas con objetos raros, perfumes, pagodillas, músicas, angarillas con comestibles y bebidas para los que tengan necesidad de reconfortar sus fuerzas; armarios con trajes para reponer los desperfectos, cuadros de talla, lemas, parasoles de flores naturales, y multitud de centenares de representaciones humanas, simbolizando pasajes de su teogonía, cuya explicación no es de este lugar, pero cuyo efecto sorprendente no puedo dejar de transmitir.\"},{\"heading\":false,\"text\":\"Imagínense los lectores un pescador y una tancalera colocados de pie sobre un torniquete giratorio; él echa las redes, ella rema; ambos dan vueltas como la tablilla de un barquillero, y ninguno se cae ni oscila, a pesar de ser párvulos como todos los actores de esta especie de autos religiosos.\"},{\"heading\":false,\"text\":\"Otra de las andas es una mujer que se abanica mientras que un mandarinete se sostiene en equilibrio sobre el país del abanico.\"},{\"heading\":false,\"text\":\"Ya un anciano tao-tsé ve brotar un guerrero de su dedo índice, ya una virgen se posa sobre la cabeza de una paloma viva, ora dos héroes cruzan sus partesanas y sostienen terrible lucha en el aire, o un Buda en fin apoya un pie en los pétalos de un lotho mientras en su infantil mano se yergue su elegido, que vuela a la región de los espíritus descartado de su envoltura material. No se ve ni un alambre, ni el menor asomo de mecanismo: aquello asombra.\"},{\"heading\":false,\"text\":\"Precedido de un lujoso acompañamiento y al son de atambores (algunos del tamaño y configuración de una pipa de cien arrobas sobre la que pegan a quien más puede dos robustos mancebos), aparece el dragón cornúpeto; monstruo de cartón con escamas de oro y marabus en las articulaciones, con cincuenta metros de longitud, tres mil duros de coste, y admirable obra de atrezista cantonés. Es llevado por treinta hombres, que ejecutan con él variadas evoluciones, y el público le saluda con cohetes y petardos, que se confunden con los acordes de la música que graciosamente y en honor del pueblo chino, ha dispuesto el señor gobernador de la colonia que toque a su paso por delante del palacio. El reptil, en cambio, recorre todo el vestíbulo, pues sabido es que donde mete la cabeza el tal animal sagrado, entra la felicidad.\"},{\"heading\":false,\"text\":\"Cierra la marcha la guardia de honor, ostentando armas blancas de una rareza que casi frisa en extravagante. Lanzones, partesanas, pinchos, medias lunas, harpones, horquillas, machetillos y adargas de mimbres son los objetos más salientes de aquella hoy ya inocente armería.\"},{\"heading\":false,\"text\":\"Y aquí da fin este desaliñado relato hecho a vuela pluma, para que no pierda su sello de oportunidad.\"},{\"heading\":false,\"text\":\"Los chinos dentro de casa.\"},{\"heading\":false,\"text\":\"Visita a una familia rica. -- La habitación. -- El mobiliario. -- El banquete. -- Elaboración del té. -- Uso del opio.\"}]},{\"title\":\"Viaje a China — Macao, 10 de marzo de 1882\",\"blocks\":[{\"heading\":false,\"text\":\"Mi querido amigo: El tiempo y el comercio se han encargado de destruir la preocupación con que los celestiales miraban a los europeos. Hoy encuentran que sus _dollars_ son excelente lazo de unión, y gracias a las transacciones mercantiles, las puertas de la casa china no están ya cerradas al _diablo blanco_, mote de todo occidental. El gineceo continúa siendo inaccesible; pues sabido es que las hijas de Eva no son aquí visitadas sino por los parientes íntimos, ni salen a la calle más que para llenar deberes de cortesía, y aun eso en palanquín cerrado y con previo anuncio. Ello no obstante, como satisfacción de una curiosidad y con alguna influencia, consigue uno ingerirse hasta el santuario de las mujeres, acompañado, como es natural, del gallo del gallinero. Mi mujer y yo hemos tenido la dicha de ser recibidos por la familia de un miembro de la alta banca, y creo que será grato conocer mis impresiones sobre el particular.\"},{\"heading\":false,\"text\":\"Como en China el ir a ver a una señora no es aquello de «me voy a pasar un ratito con fulana,» como sucede en nuestros países, sino que el acto, sobre poco frecuente, reviste el carácter de una solemnidad, es preciso tomar día, pedir audiencia como si dijéramos, y acompañar la solicitud con un regalito de tanta más monta, cuanto mayor es la categoría del visitante.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Las viviendas ya tengo dicho que están a cubierto de la curiosidad pública; así es que tienes que atravesar uno o más patios para encontrar la puerta de la casa, donde el dueño te está esperando, y en la que te recibe con las cortesías propias de su ceremonial. Consisten estas en juntar las manos sobre el pecho, como el oficiante católico al dirigirse al ara, pero con los puños cerrados, que agita repetidas veces al mismo tiempo que inclina la cabeza. Apenas transpuesto el umbral, se tropieza con un gran biombo o mampara, último tapujo del interior, en que alineadas y puestas sobre pies derechos, se destacan unas planchas (a veces quince o veinte) pintadas de encarnado y con letras de oro acusando el nombre, títulos, cargo y dignidades del morador.\"},{\"heading\":false,\"text\":\"El zaguán, que en algunas partes es un patio cubierto alrededor con su _impluvium_ en el centro, a la pompeyana, constituye el estrado del marido. Allí me recibió el banquero, mientras su primera esposa, acompañada de una hermanita suya, de sus hijas, y de su servidumbre (entre la que hay que colocar a las concubinas de su esposo), apareciendo en lo alto de una escalera, se llevó a mi mujer y a la del señor que me servía de intérprete, a las habitaciones superiores.\"},{\"heading\":false,\"text\":\"La disposición del mobiliario es igual en todas partes. Las sillas, grandes sitiales de tamarindo, de la forma de nuestros sillones de baqueta, pesados como el plomo y negros como el ébano, tienen el asiento y el respaldo de piedra cuyas vetas --simulando montañas y paisajes-- les dan un valor fabuloso. Cuando el personaje es muy rico, los muebles están cubiertos de paños color de grana, con bordados de oro y sedas. Arrimados a la pared, de la que nunca se separan, a cada dos sillones sucede una mesita alta, estrecha y con tres estantes, que sirve de pedestal a un jarrón de flores, y de apoyo al té y los dulces con que el que visita es obsequiado apenas llega. Frutas escarchadas, entre las que figuraban guisantes en su vaina, cigarros y otras golosinas, nos fueron ofrecidos en una bandeja circular con radios que constituían otros tantos casilicios. Mi anfitrión se entretuvo mientras hablaba en roer unas pepitas secas de sandía, con cuyos desperdicios, expelidos ruidosamente de la boca, ensució mi Hou-lon, rico _cha_, como aquí se llama al té, presentado en tazas sin asas, provistas de una cobertera que uno entreabre para beber con la misma mano con que la sostiene, y cuyo objeto es impedir el sorber las hojas que flotan en el líquido.\"},{\"heading\":false,\"text\":\"El chino no usa el agua como bebida; el consumo, por lo tanto, de _cha_, es incalculable; no le ponen jamás azúcar, ni emplean más que el negro. Su precio varía, desde diez reales hasta treinta y dos duros la libra. Este es el mandarín, que se vende en manojitos de la cantidad de cada toma, atados con cintas de colores.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Allá va una sucinta reseña sobre la elaboración del té. Recibido en las fábricas, todavía fresco, se escogen sus infinitas variedades; sométesele a la acción del fuego en unas colosales cacerolas, como las perolas de hilar la seda, y agitándolo constantemente, espérase a que las hojas queden contraídas por la torrefacción. El que posee aroma propio no sufre nuevas operaciones; al inodoro se le perfuma después con unas fumigaciones de azahar, de jazmín y otras olorosas flores, y encerrado en cajas de plomo, recubiertas de otra de madera, se le exporta. El verde procede de unas hojas superiosísimas, que se tuestan muy poco; pero como la cosecha es escasa y el consumo en Europa grande, se le falsifica como los vinos de Lebrija, las Cabezas, Valencia y Cataluña, que tomamos por Jerez y Burdeos. Los ácidos son la base de aquella mistificación, contra la que hay que ponerse en guardia.\"},{\"heading\":false,\"text\":\"El espíritu de especulación lleva tan lejos a los chinos, que los agentes de las casas europeas necesitan ojos de Argos para no caer en las mil y una añagazas que les tienden los celestiales. La prueba del té destinado a la exportación, es muy curiosa. Tómanse unos puñados de diversas calidades extraídos de cualquiera caja al azar; colócanlos en unas cubetas bañadas de luz zenital, que penetra por un enorme embudo de madera fijado en la ventana donde se apoya el mostrador. Pésase un tael (próximamente una onza) de cada montón, y se deposita en tantas teteras como especies han de analizarse, y que, numeradas como las tazas que tienen delante, corresponden a las cubetas. Echase encima el agua hirviendo, y transcurridos los cinco minutos que marca un diminuto reloj de arena, viértese el licor en los pocillos y los residuos pasan al mostrador junto con el puñado correspondiente. Entonces se escudriña con minuciosidad la diferencia entre el cha en crudo y el poso de la infusión. El color acusa la frescura de la hoja. Si esta, al desrizarse queda entera, es prueba de que no se la ha hecho servir ya, porque en China, donde nada se desperdicia, recogen los detritus del té y lo venden a los fabricantes, para mezclarlo con el virgen. La sed de ganancia hace que también el europeo, cuando no hay abuso, pero sí rebaja de precio, pase por esta mala fe, que no sospechan los consumidores de Occidente; pero en cambio son muy rigurosos con el peso, por lo que, provistos de un imán muy potente, lo restriegan por los montones de las cubetas, y extraen de ese modo las limaduras de hierro con que se mezcla el artículo. Ahora bien; problema: Cuando un enfermo se propina en España una taza de Pei-Kó, ¿qué es lo que cura, el té, la herradura o las babas de chino que por tercios entran en su composición?\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Reanudemos nuestra visita, en la que es de rigor permanecer cubiertos, porque ya sabes que aquí todo se hace al revés que entre nosotros. El primer cumplido que te espeta el dueño de la casa es decirte que pareces un viejo; la senectud es para el celestial la condición más respetable. Todo lo que es tuyo lo eleva a las nubes con hipérboles extremadamente orientales, y lo que con él se relaciona lo pone a los pies de los caballos. Si le encomias la buena disposición de la casa, te contestará que vive en una pocilga, y si le alabas la hermosura de su mujer, te argüirá que es una _bruta_ (sic).\"},{\"heading\":false,\"text\":\"Después nos hizo pasar a sus oficinas de comercio, donde, con el cajero, tenedor de libros, dependientes y mozos de carga, nos congregamos alrededor de una mesa, abandonándonos a un expansivo banquete de todo género de sucia pastelería.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Como creo que ha de interesarte el relato de una comida a su usanza, voy a permitirme esta digresión. Las mujeres no asisten; la confusión de ambos sexos es degradante para el fuerte, que ve en la madre de sus hijos una esclava y no una compañera. Cada mesa no puede contener más de ocho personas; por consiguiente aquellas se multiplican en proporción del número de convidados. Manteles no los hay; en cuanto a servilletas, cada uno va provisto de un pañuelo de seda que hace sus veces. Los manjares están ya servidos en grandes escudillas de porcelana, rodeadas de otras más pequeñas para las salsas y jugos con que han de adobarse, y que vierte el comensal con una cucharilla de loza, cuando no _pringa_ en el líquido condimento el bocado que, por ser muy grande, ha tenido que llevar tres o cuatro veces a la boca. Una taza sin asas, para los comestibles, y otra microscópica para el único vino que ellos beben, extraído del arroz y perfumado con una esencia, constituyen la vajilla. El cubierto son los célebres palillos, llamados _fachi_, que colocan uno en la bifurcación del pulgar y el índice, y otro entre el índice y el anular, mientras el del corazón y el meñique funcionan, a guisa de muelle, para abrirlos y cerrarlos como unas tenazas. Con este aparato cada cual toma de la vasija común el pedazo que más le apetece, y lo traslada a la suya parcial, después de multitud de paseos y baños por las diferentes salseras.\"},{\"heading\":false,\"text\":\"El sitio preferente es el de la izquierda. He aquí ahora el orden del _menú_: abren la marcha los dulces y las frutas. Síguense a estos las cuatro entradas de manjares finos, entre los que figuran los deliciosos cangrejos con huevos, las no despreciables aletas de tiburón, las insípidas pechugas de codorniz y los repugnantes nidos de pájaro, que nosotros llamamos de golondrina. Este refinamiento culinario, que se paga a peso de oro, son verdaderos nidos de un pajarillo, que se encuentra en Java. Formado de tallos y yerbecillas, se los limpia de plumones y otras adherencias, y deshechos por la cocción, quedan reducidos a una sustancia gelatinosa, con la que mezclan almendras de varias frutas, y de la que, a pesar de sus condiciones pectorales, no he podido intentar una segunda prueba. Su nombre es _ning-vo_.\"},{\"heading\":false,\"text\":\"A estas delicadezas suceden los platos fuertes. Manos de cerdo rellenas, chuletas azucaradas, patos salados y prensados, que saben a jamón, faisanes que en Shang-hai valen a dos reales pieza, corzo y pescados ahumados. La salazón abunda en su cocina, lo que produce escrófulas y asquerosidades a que la pluma se resiste. Excuso decirte que, dado el cubierto, todo tiene que presentarse hecho pedacitos; y que si algo hay que trinchar, los dedos se encargan de la operación.\"},{\"heading\":false,\"text\":\"Aquí principian las libaciones, en las que son muy parcos. En seguida entra en tanda el arroz hervido simplemente y servido en cubos de madera, de los que cada convidado se propina dos o tres tazas, pues constituye la verdadera y diaria alimentación del chino, que nunca prueba el pan. Amenízanlo con langostinos, cerdo, aves, pescado y todo género de _chow-chow_ (chau-chau), como ellos llaman a las mezclas. La manera de devorarlo, pues no puede decirse que lo comen, es nauseabunda. Pizcan de la fuente general un trozo de chow-chow, lo trasladan a su escudilla y, colocándose esta debajo de la barba, como una bacía de afeitar, empujan precipitadamente con los fachis el arroz, ni más ni menos que si rellenasen de casquijo un agujero, y no lo mascan hasta que se les sale por la boca.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Relatarte lo que come el indigente es tarea ímproba. Aquí no se desperdicia nada. La carne de perro y de gato se vende públicamente; a la de ratón y toda suerte de animales inmundos se le da caza en el propio domicilio. Sé que voy a extralimitarme poniendo a prueba el estómago de tus lectores; pero la cosa es tan notable, que no puede pasarse en silencio. Para el chino pobre, peinarse es un banquete. De ese modo pretenden que recuperan la sangre que el _insecto_ les ha chupado.\"},{\"heading\":false,\"text\":\"Terminada la comida, es preciso colocar los _fachi_ cruzados sobre la taza en signo de satisfacción y gratitud; el anfitrión los va retirando y poniendo sobre la mesa como contestando: no hay de qué. Un par de eructaciones son del mejor tono para atestiguar que los manjares te han sentado bien.\"},{\"heading\":false,\"text\":\"El té sin azúcar y unas chupadas de pésimo tabaco ponen fin a la fiesta. Las pipas en que fuman, indescriptibles y variadas hasta lo infinito, no contienen, por enormes que sean, más tabaco que el indispensable para una bocanada; por consiguiente, hay que cargarlas en cada aspiración, valiéndose para encenderlas de unas mechas de papel retorcido (que también se usa como cordel) sobre las que soplan muy hábilmente para que produzcan llama.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Admitidos por fin en el gineceo, nos encontramos a las señoras terminando su _tiffin_ y en sazón que la dueña de la casa, quitándose un _nivat_ de plata (horquilla) y pinchando con él un pastelillo, se lo ofrecía a mi mujer; que como puedes imaginarte, _no tenía ya más apetito_. En vista de lo cual la criada sirvió agua caliente, en la que remojó un pañuelo de espumilla de seda, con el que su ama se limpió las manos y la boca, pasándolo después a toda la reunión _para que hiciera lo propio_. Luego sacaron las pipas. Todo el sexo bello fuma.\"},{\"heading\":false,\"text\":\"Acto continuo nos llevaron a visitar las habitaciones, idénticamente amuebladas a las que ya he descrito. En el salón penden algunos retratos de familia, horriblemente pintados al óleo, cuadros inocentes como los países de los abanicos y entrepaños con máximas y caracteres. Las paredes no están enlucidas; ostentan el ladrillo vivo de color gris azulado y ennegrecido por el humo de los pebetes que a todas horas están ardiendo en nichos destinados a los dioses penates y porteros. En el oratorio álzase un altar con pebeteros y relicarios de metal blanco, flores artificiales, estatuitas de Lao-tse, el fundador de la metafísica, de _Cug-ñan_, la Virgen de la pureza, y de la multitud de ídolos de las teogonías búdica y de Brahma, que mezcladas con la moral de Confucio, forman las tres religiones dominantes en el país.\"},{\"heading\":false,\"text\":\"En los dormitorios, arcones de sándalo y armarios de alcanfor alternan con las camas de tamarindo, confundiéndose la de la primera mujer con las de las concubinas, que el dueño comparte indistintamente. Duermen vestidos y sobre una esterilla que sustituye al colchón, sin más sábanas que un abrigo de lana, en que se arrebujan. La almohada es de loza del tamaño y forma de las almohadillas que antiguamente usaban las señoras en España para coser; y no apoyan en ellas la cabeza sino el cuello, con lo que las mujeres consiguen no deshacerse el peinado que, por su complicación, no restauran más que semanal o quincenalmente. En la cabecera hay colgados infinidad de amuletos, acusadores de la superstición que los domina. Un sobre de un despacho imperial trae fortuna; y, si se le hierve, su agua cura enfermedades epidémicas. Unas monedas de cobre ensartadas evitan el mal de ojo. La infusión de una bolita de oro, otra de plata y una ramita de coral es eficacísima contra los sustos. La nuez extraída de la garganta de un mono vivo no tiene rival para las fiebres. Y en la casa donde, como acontece en la mía que está apoyada sobre un monte, entran culebras, ya no hay más que pedir.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"El fumador de opio pertenece a lo reservado; los hay públicos para los transeúntes, sin perjuicio de tener cada uno el suyo particular en el domicilio. Este horrible vicio, que embrutece al hombre y le acorta la vida, no ha podido ser desterrado, a pesar de los esfuerzos del gobierno imperial, que ha tenido que contentarse con infligirle un impuesto de diez pesetas por bola de cuatro libras, que es como se expende en crudo. En las colonias está monopolizado, mediante una suma, que en Macao asciende, con la inclusión de la pequeña isla de Taipa y Colowane, a cerca de cincuenta mil duros al año. Sus efectos son espantosos; el pobre compra el residuo del de la gente acomodada, y no gasta menos de un real diario. Yo conozco en Hong-Kong a un rico mandarín que invierte más de peso y medio cada día, y que, a consecuencia del abuso, tiene que trasladarse a Cantón de dos en dos meses, para hacerse operar por la paralización absoluta de sus funciones digestivas.\"},{\"heading\":false,\"text\":\"El opio, que cocido toma el nombre de _anfión_ (_a-pin hi_ en chino), se reduce por esta operación a una pasta bastante dura. Para fumarlo, se necesita que la habitación esté cerrada, a fin de que el aroma no se evapore. En el centro del cuarto elévase un entarimado cubierto con un boca-porto, más o menos lujoso, que imprime al conjunto el carácter del escenario de un teatro, del tamaño de una cama de matrimonio. En él, provistos de dos almohadas, se acuestan los fumadores, separados por un banquillo, sobre el que arde una lamparilla de aceite. Cuando el chino no tiene un amigo que le acompañe, lo reemplaza por una concubina que, aunque no comparte su placer, le arrulla y le canta. La mujer propia jamás se presta a lo que entre ellos es el colmo de la abyección. La pipa es de las dimensiones y estructura de una flauta, con un agujero en el centro, al que se adapta el hornillo de barro, como un hongo o seta, provisto de un oído diminuto. Las sustancias de estos aparatos varían hasta lo infinito; y a veces su mérito, por la saturación del tubo o la riqueza del utensilio, es tal, que lámpara, cilindro y horno cuestan tres mil duros, como los que yo he visto destinados al último embajador de China en Rusia. El procedimiento es este: con un alambre se extrae del bote una partícula de anfión como un guisante; se somete a la acción de la llama para fundirlo, y rozándolo sobre el hornillo de la pipa, se le hace tomar, cilindrándolo, el tamaño del oído, en el que se adapta, después de repetidas manipulaciones. Aplícasele a la luz, arde y se aspira. Su sabor es acre como su perfume; pero no tiene nada de repulsivo. Sus efectos son la atrofia y sus consecuencias, la imbecilidad.\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Una revista, pasada a las joyas y telas bordadas del ajuar de la señora, puso término a una visita en que invertimos más de tres horas de reloj, volviendo a casa cargados con multitud de golosinas, de que nos llenaron los bolsillos, como testimonio comestible de la honra que les acabábamos de dispensar.\"},{\"heading\":false,\"text\":\"Hasta la otra.\"},{\"heading\":false,\"text\":\"CANTÓN\"},{\"heading\":false,\"text\":\"I\"}]},{\"title\":\"Viaje a China — Macao, 8 de diciembre de 1882\",\"blocks\":[{\"heading\":false,\"text\":\"Cantón es para los chinos lo que París para los europeos; la ciudad de los placeres, del lujo, de la industria, de la actividad y de la riqueza. Pekín, con ser la capital del Imperio, no tiene para los celestiales otro aliciente que el de la vida pública con su balumba oficial.\"},{\"heading\":false,\"text\":\"Nacer en _Suchau_, que produce los hombres más hermosos; vivir en Cantón, paraíso de los bienes terrenales, y morir en _Lauchan_, donde se fabrican las mejores cajas de muerto, son los tres dones más preciados que la naturaleza puede hacer a un hijo de Confucio.\"},{\"heading\":false,\"text\":\"Las noventa y tantas millas que separan al emporio chino de la colonia de Hong-Kong, y de las cuales más de dos tercios son de navegación fluvial, se recorren en unas siete horas en vapores de río, sistema americano, pertenecientes a compañías, ya indígenas, ya inglesas, con servicio cuotidiano de día y de noche.\"},{\"heading\":false,\"text\":\"Ni Cunard, ni las Mensajerías, ni la Mala del Pacífico, ni la Trasatlántica, ni la Trinacria pueden compararse en lujo y comodidad con algunos de los buques de esta empresa británica. Construidos para cortas travesías, sin riesgo de ninguna especie (pues al menor indicio de tifón dejan de circular), estos _steamers_ tienen en el centro de la cubierta la cámara; vasto y elegante salón ventilado en verano por multitud de ventanas que permiten al viajero admirar las riberas sin moverse de su sitio, y abrigado en invierno por caloríferos y estufas.\"},{\"heading\":false,\"text\":\"Los camarotes son verdaderos gabinetes, con camas en vez de literas, lámparas suspendidas e inmensos tocadores de mármol provistos de irreprochables artículos de limpieza. El pasaje no cuesta más que tres duros, y uno y medio cada comida, que en cantidad satisfaría la intemperancia de Lúculo, y en calidad merecería el aplauso de Brillat-Savarin; se la rocía con Burdeos, Jerez, Porter y Pale-ale, sin contar los licores que precipitan el Moka, y añadiendo un desayuno a elección en los viajes de noche.\"},{\"heading\":false,\"text\":\"Viajar por agua sin columpiarse, es el bello ideal de la locomoción: metido, pues, en un palacio que se desliza, avanza uno con vertiginosa rapidez embelleciendo con la feliz disposición del ánimo los detalles que le salen al encuentro. Para Boca Tigris, fortificación que defiende la entrada del río, es la primera sonrisa del excursionista, que en cada montón de tierra que saca la cabeza del agua, reconoce siempre a un simpático amigo. Renuncio a juzgar si este mamelón está bien o mal artillado, porque en punto a cañones, yo no he tenido trato más que con los de las plumas cuando se estilaban de ave. Lo único que sé, es que los chinos lo miran como un Gibraltar, y los europeos se ríen de él. Sumando, pues, ambos términos, y tomando la proporción media, deduzco que con unas leccioncitas de los oficiales del ramo ingleses y buena pólvora de Albión, el ruido y las nueces andarían equilibrados.\"},{\"heading\":false,\"text\":\"Remontando aquellas riberas amenizadas con las típicas torres de cinco, seis o siete pisos, terminados por tejadillos en forma de araña y alfombradas de diversas plantaciones, llégase a Wampoa, avanzada de Cantón, donde ya nos interceptan el paso los innumerables botes de la población flotante, condenada a vivir y morir en sus esquifes, y cuyo número excede a toda ponderación. Los ingleses llaman a estas embarcaciones _Slipper-boat_ (barco zapatilla) por la forma que afectan con su puntiaguda proa y sus toldos agalerados de bambú: el efecto real es el de un cerdo nadando. Al verlos hacinados a miles bajo los puentes de Cantón y en los puntos más resguardados del río, se le ocurre a uno preguntar si la ciudad está abandonada, pues no parece sino que se ha trasladado a bordo el millón y medio de sus habitantes.\"},{\"heading\":false,\"text\":\"Por fin se atraca: estamos en el emporio chino. Cerremos los ojos ante aquella especie de muladar que constituye el carácter distintivo de los barrios celestiales, y apretemos el paso para hacer entrar a los sentidos en puertos de salvación. Después nos encenagaremos.\"},{\"heading\":false,\"text\":\"Antes de rebasar la línea, nos sorprende un edificio severo y majestuoso con cara de persona decente y acomodada. Es el _Custom house_ o aduana inglesa. Sabido es que cuando la poderosa Albión terminó a cañonazos sus diferencias con el imperio del Medio, intervino las aduanas, como garantía del pago de la indemnización de guerra. Saldada que fue la operación, observó el gobierno chino que los rendimientos durante la gestión administrativa de sus apaleadores, habían sido mucho más pingües que en manos de sus funcionarios nacionales; y rogó a aquellos que continuasen en su tarea por cuenta del Estado en lo que se refiriera a importación o exportación en buques extranjeros. Desde entonces radica en Pekín un inteligentísimo Director general, retribuido con un elevado tanto por ciento sobre el total de la recaudación, a cuyo cargo, elección y coste, están los funcionarios de las diferentes agencias fiscales del imperio. Sujetos a un escalafón riguroso y a reglamentos fijos, exígeseles a estos empleados el conocimiento perfecto del inglés, e ingresan en el cuerpo, después de unos meses de prueba, con un haber mínimo de ciento veinte pesos al mes y casa en común o independiente si son casados. Simultaneando con el ejercicio de sus funciones, aprenden la lengua mandarina y obtienen sus ascensos a medida de su aplicación, hasta llegar a jefes de departamento con diez, doce y creo que hasta catorce mil duros anuales, y habitación, criados, convites oficiales y otros gastos satisfechos. El personal se compone de ingleses, americanos, españoles, franceses, italianos; de todas las nacionalidades en fin. De ese modo el día que el gobierno chino quisiera prescindir de la administración inglesa, habría una reclamación universal de intereses lastimados, y tendría que someterse a la dura ley de la fuerza. Esto es entenderlo y saber hacer duraderas las cosas. Lo mismo nos pasa a nosotros.\"},{\"heading\":false,\"text\":\"No nos entristezcamos y pasemos adelante.\"},{\"heading\":false,\"text\":\"Atravesando el puente de los señores, pues el otro que lo separa de la población china está destinado a la servidumbre, nos encontramos en _Shameen_; islote no más grande que una manta de cama pequeña de matrimonio, cuyo terreno constituye la concesión o morada europea. Habitado por el cuerpo consular, los funcionarios de la aduana y los agentes de las casas de comercio extranjeras, _Shameen_ encierra en junto treinta familias. Cada casa es un pequeño hotel con su galería abierta sobre la fachada, respirando alegría, riqueza y buen gusto. El arroyo es de césped y las calles andenes de jardín. Hay una capilla protestante y hasta gente que se pasea a caballo y al trote. ¡Qué temeridad! Pero no vayan ustedes a figurarse que aquí se detienen las maravillas del pequeño Lilliput: es todo un Estado bajo la base del comunismo. Un cónsul es administrador de correos con la responsabilidad y formalidades de un funcionario público. Todos los habitantes, excepto las señoras (que me parece que son nones y no llegan a tres), están obligados a prestar servicio como bomberos. El de las armas es gratuito y obligatorio: al menor asomo de revuelta por parte de los chinos, como aconteció hace dos o tres años, cada cual empuña el útil de guerra de que dispone, organízanse guardias y retenes, los vapores de la línea aprontan sus calderas; y, como fuera vano empeño resistir, al primer tiro de alarma, todo el mundo a bordo: el ejército de tierra se convierte en fuerzas de mar.\"},{\"heading\":false,\"text\":\"Sobre ser tan pequeña la isla, aún queda espacio para un elegante paseo sobre el malecón; desde el cual, dirigiendo la vista del lado de la tierra, apercíbense hombres que se agitan en diversas direcciones, pelotas que describen giros parabólicos y raquetas que muy a menudo resignan sus poderes en la cara de su dueño. Son praderas públicas, trinquetes a la inglesa, _sport_ verdadero, donde los moradores entretienen sus ocios con el ejercicio gímnico del _cricket_. Teniendo ya _lawn-tennis_, no pierdo la esperanza de asistir a un _handicap_ en el futuro hipódromo de Shameen.\"},{\"heading\":false,\"text\":\"¿Me preguntan ustedes qué ruido de billar es el que sale por las ventanas de ese magnífico edificio? Pues qué quieren ustedes que sea sino el del billar del club inglés; donde además de todos los juegos lícitos y de todas las bebidas y reconfortantes gástricos apetecibles, encontrarán ustedes una magnífica biblioteca, de cuyas obras se puede disponer a domicilio, y habitación dispuesta para que pernocte el socio transeúnte. Esto sin contar los periódicos y el papel gratis para la correspondencia.\"},{\"heading\":false,\"text\":\"Pero no nos detengamos aquí, que mejor que el club inglés es el alemán, en el que, amén de las mismas comodidades y atractivos, existe un teatro, un verdadero teatro común de dos; pues en él los pobladores de Shameen hacen de hombres y mujeres; de actores y público; de empresario y abono.\"},{\"heading\":false,\"text\":\"¿Quieren ustedes más? Pues como no nos metamos en un _houseboat_ (bote-casa), con su dormitorio, cocina y demás menesteres, para entrarnos río adentro y pasar ocho días consagrados a la pesca o a la caza en domicilio flotante propio, de que nadie carece, la isla ya no da más de sí.\"},{\"heading\":false,\"text\":\"Ahora repasemos el puente; hagamos irrupción en la ciudad china y digamos como en los libretos de las comedias de magia: Mutación.\"},{\"heading\":false,\"text\":\"Así como el comedor de la casa de aquel chusco era tan bajo de techo que no podía comerse en él más que lenguados, así las calles de Cantón son tan estrechas que no hay mortal que entre en su recinto si no es con calzador. Extendiendo los brazos, y hablo en serio, se tocan ambas paredes; y en todas las esquinas hay una tienda con una puerta en cada lado del ángulo, a fin de que, al cruzarse dos palanquines, mientras el uno sigue por el arroyo, el otro tome por el almacén y no se interrumpa la circulación. De trecho en trecho un enorme portón se atraviesa en el camino para limitar un barrio; abierto al tránsito de día, ciérrase al ponerse el sol, y nadie pasa sin permiso del portero, lo que permite no solo localizar cualquier motín en un momento dado, sino saber quién trasnocha y por qué motivo.\"},{\"heading\":false,\"text\":\"El que haya visto una población china las conoce todas; su construcción es idéntica. Casas hechas con un ladrillo gris azulado, sin más presión que la de los pies del obrero, y que no enlucen jamás ni en paredes ni en tabiques: vigas al aire; en el interior una zahurda; en la fachada una puerta con una ventana encima. Escalas de mano para el acceso: dos o tres industriales viviendo en comunidad, y toda clase de animales domésticos, desde el guarro hasta la chinche, compartiendo el hogar con los moradores racionales. El chino rico solo se diferencia del pobre en tener casa más grande y poseer más dinero.\"},{\"heading\":false,\"text\":\"Pekín es la única ciudad que reviste otro carácter. Sus calles anchas tienen en el centro a modo de un terraplén formado por la basura, que arrojan los vecinos y que el sol se encarga de secar y corromper. Sobre esta alfombra transita la gente, ya a caballo ya en carretas, en las que no cabe más que un individuo sentado en el fondo de la caja; porque asientos, Dios nos los dé. El polvo es asfixiante y fétido; pero la _municipalidad_ ya lo tiene previsto todo: ha colocado de distancia en distancia unos recipientes de barro que hacen el oficio de columnas mingitorias; y a determinadas horas del día la escuadra de la limpieza, provista de sendos cazos, riega la vía con aquel precioso licor. No hablemos más de Pekín; en primer lugar porque no lo conozco y me alegro; y en segundo, porque mis lectores han de participar de mi alegría.\"},{\"heading\":false,\"text\":\"CANTÓN\"},{\"heading\":false,\"text\":\"II\"},{\"heading\":false,\"text\":\"Ya estamos dentro de Cantón; ya estamos en medio de esta red de estrechas callejas, llenas en toda su extensión de tiendas y tiendecillas.\"},{\"heading\":false,\"text\":\"¿En dónde están los que consumen? se pregunta uno al ver aquella profusión de abastecedores. Porque en efecto, no hay una sola casa que no sea una tienda, a excepción del barrio tártaro, erigido en una zona especial, cuyos moradores, de más bizarro continente que los chinos, y soldados por derecho de raza (pues pertenecen a la nacionalidad de la dinastía _manchú_ reinante) tienen viviendas de un solo piso, jalbegadas por el exterior, y si mucho menos aseadas, parecidas a las de algunas aldeas pobres españolas. El fenómeno se explica con recordar que Cantón es a Asia lo que París a Europa. Los cuatrocientos millones de habitantes del Celeste imperio se surten en él, no solo de los artículos de lujo, sino de los de boca de primera necesidad que, salados y secos, transportan a los últimos confines en millares de _lorchas_ o juncos de su temeraria cuanto rutinariamente diestra marina mercante.\"},{\"heading\":false,\"text\":\"Dicho sea en honor de la verdad, hay algunos establecimientos que seducen, no por la suntuosidad de los edificios, que en poco o en nada difieren de los otros, sino por la riqueza de los objetos que en ellos se expenden. Los bordados de seda, las lacas, las porcelanas, los tejidos, las incrustaciones de nácar sobre madera, peculiares del Tonkín, las sillerías de tamarindo (el ébano local), las tallas perfeccionadas de Ning-po con aplicaciones de marfil, las filigranas de plata y oro, y las antigüedades, fascinan por su valor intrínseco y por la novedad que producen a nuestros ojos; pero carecen de aquella variedad infinita, del gusto ejemplar de la industria europea, y sobre todo de su perfección irreprochable. Aquí no hay nada bien concluido, y las más preciadas joyas concluyen por hastiar a fuerza de monotonía. Se fabrica sobre un tipo y solo varía la materia. El arte, como la existencia del chino, está sujeto a patrón. Así es que cuando se han aprendido ya de memoria las dos docenas de moldes en que se vacía su inteligencia industrial, los bazares suntuarios con sus preciosidades gemelas (o por lo menos con su aire incontestable de familia) y sus enormes muestras de planchas de charol con caracteres de oro que, pendientes del arquitrabe y rasando el suelo en sentido vertical, dan a la calle el aspecto de una columnata, quedan eclipsados por la asombrosa multiplicidad y el inagotable surtido de abacerías, bodegones, ropavejeros, confeccionadores de toscos objetos de papel para conmemoración de los difuntos, y tantos y tan repugnantes comercios bajos que, ora detienen la marcha del transeúnte con un buey o un cerdo abierto en canal junto a la carcomida tabla anunciadora: ya le salpican el rostro con la sangre del pescado que cortan a rebanadas; o provocan sus náuseas, en fin, con la exhibición de verduras en salmuera, salazones de especies desconocidas, gusanos de seda sacados de las perolas de las fábricas de filatura para ser comidos con arroz, hierro enmohecido, festines de animales al aire libre, dentistas ambulantes revestidos de rosarios de muelas, barberos que sacuden sus navajas sobre los circunstantes, hombres desnudos que, con sus amarillentas manos provistas de largas y negras uñas, sacan de las vasijas los manjares que aquel pueblo famélico devora con avidez; ciegos en filas de seis y ocho tocando campanillas para no ser atropellados por la muchedumbre, mendigos con úlceras y escrófulas que solo se creen viéndolas, truhanes, agoreros, jugadores de dados y fumadores de opio. Este es el Cantón típico: miseria, basura, abyección.\"},{\"heading\":false,\"text\":\"Apenas anochece cesa el ruido; las puertas se cierran herméticamente. En las primeras horas arden unas candelillas, que cada familia enciende a sus dioses penates en hornacinas abiertas sobre el umbral. Cuando se apagan, todo queda en tinieblas. Entonces aparecen las rondas nocturnas, armadas de lanzones retorcidos, partesanas, escudos de mimbre, y precedidos de un _gong_ o campana china, en el que dan sendos porrazos; con lo que consiguen dos objetos: despertar al que duerme y prevenir a los ladrones para que burlen su vigilancia.\"},{\"heading\":false,\"text\":\"Una buena costumbre, que debe ser imitada en ciertos países donde la policía deja mucho que desear, es la de hacer responsables a los inquilinos con tienda abierta de los desórdenes que pueden ocurrir en la calle delante de su casa. De ese modo el temor de una multa, hace que en cuanto en el arroyo se origina una disputa, salga el tendero provisto de un garrote o de cualquier otro argumento de persuasión, y se lleve a los contendientes a la zona de su vecino, quien a su vez repite la operación, y así sucesivamente hasta dar con la fuerza pública, que termina en la cárcel la partida de tente-tieso.\"},{\"heading\":false,\"text\":\"Las pagodas, aunque en la parte consagrada al culto difieren poco entre sí, tienen notables diferencias de aspecto como edificios. Cuéntanse a centenares, por lo que no nos detendremos mas que en las que ofrezcan alguna particularidad. La de los Quinientos ídolos es sencillamente un museo de escultura encargado de perpetuar, en toscas figurillas de madera dorada de medio tamaño natural, la memoria de los que se han distinguido por cualquier concepto. Un padre que tuvo muchos hijos, un hombre que alcanzó una gordura fenomenal (signo de favor celeste), un individuo virtuoso, un general valiente, están seguros de inmortalizarse en aquel _totum revolutum_ de santos, héroes y monstruos de feria. No hablemos del mérito artístico de las estatuas. Hay allí (y por cierto que es circunstancia singular) una reproducción del gran viajero del siglo XIII, del veneciano Marco Polo, con una chaquetilla de trajinero de la Mancha y un hongo pavero, que pedir más fuera gollería.\"},{\"heading\":false,\"text\":\"La de la Campana es solo notable por el gigantesco tamaño de la que pende de una oscura y medio derruida linterna. Todos estos templos poseen la suya además del _gong_ y del bombo con parche de piel de vaca sin curtir; pues, según la tradición, los primitivos bonzos eran criminales condenados al aislamiento; y debían anunciar, con una campanada repetida cada quince minutos, que no habían apelado a la fuga.\"},{\"heading\":false,\"text\":\"La Torre de porcelana, mal comprendida entre las pagodas, es uno de esos polígonos de varios cuerpos que figuran en todas las telas de abanicos y cuyas tejas barnizadas relucen al sol con varios cambiantes. Sus relieves de buen gusto y su elegante forma la conquistan un primer lugar entre los monumentos de su especie.\"},{\"heading\":false,\"text\":\"La Pagoda de los Cerdos, así llamada por una pocilga en la que pasan feliz existencia cinco o seis ejemplares sagrados de ellos, que se renuevan anualmente, encierra un culto simbólico; pues parece ser que, según la metempsicosis, el hombre que transmigra a aquel animal inmundo es de los menos pecaminosos; y tiene la seguridad de recobrar pronto su condición primitiva, visto que la vida del marrano no excede por lo común de doce meses. Constituye, en una palabra, una dosis de purgatorio a su manera, tanto más pronto redimido cuanto menos tardan en desarrollarse las mantecas del pecador.\"},{\"heading\":false,\"text\":\"La de los Cinco pisos, desmantelada, no sirve ya mas que de mirador, en gracia de su altura, y fue cuartel general del ejército de ocupación.\"},{\"heading\":false,\"text\":\"El ritual del culto de Buda, cuya religión tiene tantos puntos de contacto con el cristianismo, se parece bastante al ceremonial católico. El oficiante junta las manos sobre el pecho, como nuestros sacerdotes, con ligeras alteraciones en la colocación de los dedos; y hasta en sus cantos hay inflexiones que diríanse copiadas de nuestra liturgia.\"},{\"heading\":false,\"text\":\"Jamás olvidaré la impresión que me produjo un servicio fúnebre a que asistí en Macao con motivo del entierro más suntuoso que registran los fastos chinos. Invirtiéronse en él cerca de cuarenta mil duros; pues en los cien días que se conservó el cadáver en la casa y que, según el budismo, es el tiempo que el alma anda errante hasta ocupar su puesto en la región de los espíritus, cuantos parientes, deudos y amigos acudieron a rendir el último tributo al finado, fueron mantenidos, incluso de opio, a expensas del hijo primogénito. Sin detenerme a describir las maravillas de ornamentación de la casa mortuoria, atestada de muebles excepcionales, de plantas en cuya cultura habían intervenido tres o cuatro generaciones para ir conduciendo los tallos hasta formar con las robustas ramas caracteres, figuras y símbolos; de objetos de papel para quemar ante la tumba que se confundían con el marfil, el bronce y el cristal; omitiendo la narración de los tres meses de ceremonias religiosas, en las que tomaron parte sesenta bonzos y dos obispos o jefes de comunidad, referiré a la ligera la que tuvo efecto la víspera de la inhumación. Una pagoda, aislada de la capilla ardiente, ocupaba dos habitaciones contiguas. En la interior y bajo unos arcos de ramaje de una transparencia cristalina, profusamente iluminados, doce bonzos y un superior vestidos de seda y oro y apoyados en una fauna simbólica, se mantenían en éxtasis. ¡Qué inmovilidad en aquellas difíciles posiciones! ¡Qué inercia y qué absorción en aquella actitud contemplativa! Era preciso detenerse media hora ante aquellas estatuas animadas, para sorprender una ligera oscilación que acusase un soplo de vida en su marmórea rigidez. Así se mantuvieron desde las seis de la tarde hasta la una de la madrugada. En la pieza vecina, atestada de relicarios gigantescos de filigrana, revestida de paños bordados, en que el oro entraba por arrobas, e iluminada profusamente, veíanse unas mesas dispuestas en trapecio, como en los festines de las óperas. Ocupaban las de los lados los bonzos de orden menor, cubiertos de unas hopalandas oscuras y ceñidos de unas fajas y bandas de diversos colores, según la comunidad a que pertenecían. En las tres del fondo estaban los oficiantes. Sobre estos y en un trono de nubes pendiente del techo, yacía recostado un obispo en el mismo arrobamiento que sus otros compañeros de reposo; si bien acompañado de dos harapientos culis, que con sendos abanicos, le refrescaban la atmósfera deletérea de aquella elevación en que se acumulaban las emanaciones del aceite de las luminarias y la respiración, a menudo ruidosa, de sus colegas y del auditorio celeste. Otros mancebos, con más o menos mugre, distribuían té a los religiosos. Preces, invocaciones, purificación de la morada por el fuego y mucho golpe de gong acompañado de dulzaina, formaron la parte esencial de la ceremonia. Por fin, el oficiante principal se puso en pie detrás de su mesa; y en medio de un silencio sepulcral, levantó los ojos al cielo, blandió dos campanillas y se puso a comunicar con el muerto.\"},{\"heading\":false,\"text\":\"Después del _Dies iræ_ del catolicismo, no conozco nada más sublime que ese coloquio de la religión con el pecador. Ni una voz, ni un canto, ni una palabra; pero ¡cuánto arte en las vibraciones del timbre que, ora simulan el terror del alma puesta al borde del abismo de las penas eternas; ora traducen la satisfacción y la gratitud del espíritu arrancado de repente a la condenación, por las plegarias de los vivos; o bien, por último, evaporándose en una imperceptible noción del sonido, acusan el alejamiento del hálito vital por las regiones etéreas, para volar a fundirse en Dios, principio y germen de todo lo creado, de quien era partícula y a cuyo todo se restituye! Es un pasmo de ejecución y un torrente de sentimiento. Por desgracia, pronto descubren la oreja; pues el difunto, para quien aquel día suele ser siempre nefasto, responde que su alma está sufriendo crueles torturas, que no cesarán hasta que doten con una fuente en que naden peces de colores a tal convento, o hagan a cual otro los donativos que sus riquezas le permitan; de modo que el estómago se apodera de la sublimidad de la concepción, y toda la grandeza del espíritu se desvanece entre la gente bonza, ante una solución gástrica de refectorio.\"},{\"heading\":false,\"text\":\"Cerremos esta crónica religiosa con cuatro palabras sobre la Catedral erigida en el centro del barrio tártaro. De orden gótico, está tallada en duro granito y recuerda la de Amiens. Carece aún de pavimento, de ornamentación, de altares y de objetos de culto, y van invertidos en ella ocho millones de francos, producto de donaciones y limosnas. Su diócesis alcanzará a veinte personas; sin embargo, al verla ostentar su inmensa nave en medio de millón y medio de gentiles, diríase que ha sido construida en la previsión de que pueda servir para millón y medio de católicos. Todo es de esperar de nuestras intrépidas misiones.\"},{\"heading\":false,\"text\":\"CANTÓN\"},{\"heading\":false,\"text\":\"III\"},{\"heading\":false,\"text\":\"En la parte opuesta del río, llamado _Honam_, hay unos jardines, que visitaremos, por no quedarnos sin verlo todo; pero no porque merezca la pena de perniquebrarse al pasar aquellos carcomidos puentes, ni de atrapar unas fiebres palúdicas por intentar en vano reflejar nuestra imagen en el impuro seno de unas charcas cenagosas. La flora es rica, pero descuidada; y como esta excursión no es científica, suprimo por inoportuno lo que habla a la inteligencia y callo por inexistente lo que halaga los sentidos. No saldremos, sin embargo, de allí sin entonar un himno de asombro a la camelia de Cantón, rarísima variedad, que solo florece de dos en dos años y cuya forma es una verdadera maravilla. Redúcese a una estrella de varias puntas, cada uno de cuyos radios está compuesto de pétalos sobremontados, que disminuyen hacia las extremidades con una simetría y proporción geométricas. Estos pétalos, que son de color de rosa pálida, doblan sus bordes hacia fuera, presentando una fimbria de matiz más fuerte, que dan a la flor, como dejo dicho, el aspecto de una estrella de escamas, con círculos concéntricos festoneados de rojo.\"},{\"heading\":false,\"text\":\"No salgamos del _slipper boat_, toda vez que nos hallamos en el río; y desafiando su impetuosa corriente, dirijámonos de nuevo a las márgenes de la ciudad china, en busca de los tan afamados botes de flores, donde los celestiales comparten los placeres nocturnos con los teatros y los _culaus_; bodegones sobre los que vale más callarse, y espectáculos de que es preferible no volver a decir una palabra.\"},{\"heading\":false,\"text\":\"Constituyen aquellas mansiones de la alegría unas enormes barcazas flotantes, que en nada difieren entre sí, a pesar de su número. Vista una, vistas todas. Alegremente pintadas al exterior, ocupa el puente un salón alumbrado por linternas y amueblado con sitiales y mesillas. Unos canastillos de flores penden del techo: y allí se come, se bebe y se fuma, mientras unas cuantas mujeres de jalbegado rostro, con los pómulos y los párpados cubiertos de almazarrón (aristocrático afeite del bello sexo), bien vestidas y mejor peinadas (pero nunca limpias), cantan, al parecer acompañadas de instrumentos músicos, muy semejantes para nosotros a los de tortura, preparan las pipas de los consumidores y les dan conversación. Todo ello sin algazara expansiva, pacíficamente y sin ulteriores consecuencias. Los hombres pagan y no riñen; y a las cantantes les dura el peinado intacto una semana, que es lo que tarda en volver la peinadora. No hay propinas.\"},{\"heading\":false,\"text\":\"Se me olvidaba consignar que los europeos deben ir provistos de algún frasco de esencia con que preservar el olfato de ciertas emanaciones, porque además de los perfumes urbanos, existen los fluviales, despedidos por unas _góndolas_ que constantemente están cruzando el río cargadas con materias para el abono de sus fértiles tierras de labor, y a las que los habitantes de Shameen han bautizado con el nombre de _tigres_, no sé si por el aliento que exhalan o por el terror que inspiran: lo cierto es que se las presiente y se las huye.\"},{\"heading\":false,\"text\":\"Saltemos a tierra. ¿Pero qué es esto? ¿Tocan somatén? ¿Hay algún incendio? Toda la gente mira hacia arriba, y provistos de gongs, cacerolas, latas de petróleo o simples pedazos de bambú, grandes y chicos, jóvenes y viejos, hombres y mujeres golpean y gritan a quien mete más ruido. ¡Ah! No hay que asustarse. Es que hay eclipse, y como según la astronomía china, este fenómeno tiene lugar porque la luna riñe con el sol, y en la contienda lleva la casta Selene la mejor parte, pues empieza ya a comerse al astro del día, los moradores de la tierra la obligan por aquel medio a soltar el bocado, a fin de no quedarse sin luz y sin calor; lo que consiguen siempre, porque aquí no tiene el mismo significado que en Europa lo de ladrar a la luna.\"},{\"heading\":false,\"text\":\"Verifícanse en Pekín y en Cantón alternativamente los exámenes anuales para los diversos grados de mandarín. Los ejercicios se hacen por el sistema celular; es decir, que cada examinando queda recluso y tabicado durante unos días, con el objeto de escribir su tesis sin el auxilio de bibliotecas ni consultores; y a este fin se destina un edificio conocido con el nombre de las once mil celdas, que mas propiamente deberían llamarse chiqueros. No es, pues, una universidad, porque la enseñanza es libre y a domicilio; y tampoco es una pocilga, porque son miles de ellas. Con saber las máximas de Confucio, los comentarios de Mencio, la cronología de los emperadores y contar hasta diez mil, sale de allí un hombre con aptitud para general, almirante, presidente del Supremo, obispo, ministro de la música (existe un ministerio _ad hoc_) o cualquier otro cargo en armonía con sus aficiones o al alcance de sus recursos, pues importa saber que en China la administración del Estado se concede a la puja. Luego nos extenderemos sobre este particular. Recordemos antes a los lectores que lo hayan puesto en olvido, que existe una lotería llamada _Vaiseng_ (desterrada del imperio y acogida al pabellón portugués en Macao), reducida a jugar sobre el nombre de los examinandos que se presume que han de ganar el curso. Cuál sea el número de los jugadores dedúzcase de lo que el monopolizador paga al gobierno del establecimiento lusitano, que en la última subasta trienal satisfizo la enorme suma de seiscientos cuarenta mil duros. Así es que cuando la opinión se inclina por tal o cual estudiante de reconocida aplicación e incontestable inteligencia, el concesionario, ante la probabilidad de tener que satisfacer grandes premios, procura sobornar a los examinadores para que desahucien al candidato, o corromper a este con dádivas para que abdique del éxito.\"},{\"heading\":false,\"text\":\"Volvamos a lo de la puja. Cantón, capital de los dos Kuanes (Kuan-tung y Kuan-si) es la sede de un a modo de gobierno de provincia; con la sola diferencia de que el gobernador tiene el título de virrey y ejerce jurisdicción sobre cuarenta millones de habitantes en una extensión de 435,000 kilómetros cuadrados. Pues bien; cuando el gabinete de la metrópoli, o más propiamente hablando, el emperador --y en su defecto el regente, si como acontece ahora, el soberano está aún en la menor edad-- trata de proveer el cargo, elige un mandarín de la más elevada categoría; pero siendo muchos los aspirantes, opta por aquel que ofrece mayor suma de rendimientos al Estado. Por supuesto que el monarca repite, como Luis XIV, _el Estado soy yo_. Una vez el agraciado en el ejercicio de sus funciones, saca sus cuentas y dice: «Seis que me cuesta el destino y seis que yo quiero ganar son doce, que corresponden a los contribuyentes. Dividiendo estos doce por tres, que son los años que ha de durar mi ejercicio, tocan a cuatro anual.» Y en efecto; llama a los mandarines sufragáneos, y suma por aquí, multiplica por allá, él se las arregla de modo que le salgan los cuatro. Pero ¿qué acontece? Que, como las autoridades inferiores han escalado sus destinos por igual procedimiento, apelan a los mismos recursos económicos; y pídales lo que les pida el virrey, se lo dan, pues toda la operación se reduce a aumentar la derrama entre sus administrados. No hay más ley que el capricho, y es inútil quejarse, porque al que protesta se le confiscan los bienes, y al que se resiste lo decapitan.\"},{\"heading\":false,\"text\":\"Para muestra basta un botón. El general de las fuerzas militares de Cantón, a quien tuve el gusto de conocer, y que entre varias cosas notables me preguntó si España estaba junto al Perú, responde de un contingente de doscientos mil soldados, pues el efectivo apenas llega a la mitad; los restantes figuran solo nominalmente en los cuadros del ejército, y el pre se cobra pero no se paga. El día que hay una revista general, lo que ocurre de higos a brevas, se echa mano de los culis de los oficiales, de los cargadores, mozos de esquina, vagos y mendigos, y hasta la otra. Este espectáculo, que tiene mucho de curioso (y no en la acepción de limpio), se divide en dos partes.\"},{\"heading\":false,\"text\":\"Es la primera una parodia de táctica al estilo europeo, en que las voces de mando son sustituidas por golpes de gong y las descargas dirigidas por los banderines de las secciones. Los movimientos resultan a discreción, sin duda para corresponder al calzado de la tropa, que es también discrecional. Unos llevan borceguíes viejos de señora con bigotera de charol, otros botas de hombre con la caña por fuera, algunos los usan de gendarme francés montado, y la generalidad _caret utroque_. En fusiles los hay desde el arcabuz hasta el de aguja, largos y cortos, y que apuntan y no tiran.\"},{\"heading\":false,\"text\":\"La parte nacional comprende el tiro al blanco con arcos de un peso y de una tensión excepcionales; la esgrima de lanza, en la que agotan todos los recursos de la gesticulación para hacerse miedo; y las maniobras hípicas con jinetes, que montan y desmontan a la carrera, se tienden sobre el caballo, que es poco mayor que una rata gorda, y ejecutan, en fin, todas las habilidades propias de los _clowns_.\"},{\"heading\":false,\"text\":\"Ahí van algunos datos curiosos.\"},{\"heading\":false,\"text\":\"Según la estadística de Behm y Wagner de 1874 a 76, las veinticinco provincias en que se divide el Imperio del medio, contando la China propiamente dicha y los países tributarios, miden una superficie de 10.466.655 kilómetros cuadrados, y tienen una densidad de 434.446.514 habitantes. Pero vaya usted a saber la verdad en un país donde no hay censo y en el que es preciso sacar las cuentas como las presupuestaba de las obras municipales aquel arquitecto de Soria, que, preguntándole lo que podría costar un matadero, respondía: «De quinientos a sesenta mil duros.»\"},{\"heading\":false,\"text\":\"Los ingresos de la nación, según los ingleses, que son los más versados en la contabilidad china, ascienden por el presupuesto de 1875 a 79.500.000 taels (cada tael valiendo peso y medio), y se descomponen así:\"},{\"heading\":false,\"text\":\"Por territorial                           18.000.000 Impuesto sobre mercancías                 20.000.000 Renta de aduanas                          15.000.000 Sal                                        5.000.000 VENTA DE CATEGORÍAS                        7.000.000 Ingresos eventuales                        1.000.000 Ganados, agricultura y demás productos naturales y en especie                  13.100.000 -----------TOTAL               79.100.000\"},{\"heading\":false,\"text\":\"En 1874 emitió el gobierno chino el primer empréstito exterior por 15.691.875 francos, dando en garantía la renta de aduanas.\"},{\"heading\":false,\"text\":\"Careciendo de administración civil, no es para extrañarse que tampoco la tenga militar. Verdad es que el mismo vacío se nota en ingenieros y estado mayor; y aun me atrevería a decir en el ejército en absoluto, si no vinieran a desmentirlo los siguientes datos de Klaprotz, de que él no sale garante, ni yo tampoco, pues están adquiridos en los cuadros mitológicos del ya conocido contingente ideal.\"},{\"heading\":false,\"text\":\"Infantería regular                    300.180 hombres. Caballería regular                    227.000    » Artillería                             17.000    » Reserva                                30.000    » Oficiales del ejército regular          6.000    » Infantería irregular                  400.000    » Caballería irregular                  273.000    » Oficiales del ejército irregular        5.200    » Marina                                 32.440    » ---------TOTAL         1.290.820 hombres.\"},{\"heading\":false,\"text\":\"Si yo fuera ministro de la Guerra en China, pondría una nota al pie de mi presupuesto departamental, como la de los antiguos billetes de diligencia en las observaciones sobre los equipajes, diciendo: «No se responde de robos por fuerza mayor.» Como no lo soy, y me alegro, me limito a consignar que el efectivo del ejército celeste depende del resultado de las cosechas generales.\"},{\"heading\":false,\"text\":\"CANTÓN\"},{\"heading\":false,\"text\":\"IV\"},{\"heading\":false,\"text\":\"Según hemos consignado al principio, la dinastía reinante no es china, propiamente hablando, sino tártara manchú; es decir, invasora, dominante por derecho de conquista, y mirada, por consiguiente, con prevención por los oprimidos. De aquí nace el que, favorecidos por la gran desorganización del Estado, tengan estos formadas sociedades secretas, que funcionan en el misterio, y cuyo fin, como fácilmente se colige, no es correr tras la libertad en busca del derecho político moderno, sino sencillamente cambiar de yugo. Dos siglos hace que trabajan con este objeto, sin lograrlo.\"},{\"heading\":false,\"text\":\"Hay además otro partido: el extranjerista, compuesto indistintamente de tártaros y chinos, que reconociendo las ventajas de la civilización, pide telégrafos, ferrocarriles, reformas en las costumbres y progreso, en una palabra; pero sus sectarios se hallan en minoría, pues ni el espectáculo del gas incita a la masa tradicional del pueblo a desprenderse de sus linternas, ni el espíritu revolucionario del movimiento en sentido de avance, se aviene con la rutinaria y perezosa marcha de estos seres mecánicos. Ello vendrá, no obstante, y acaso muy pronto, pues ya empiezan a observar que la actividad es un elemento de riqueza, y el chino es avaro.\"},{\"heading\":false,\"text\":\"Tomando pretexto de cualquiera de estas razones políticas, sucede a lo mejor que un mandarín cuyas aspiraciones no han sido satisfechas, se levanta en armas, recluta ciento cincuenta mil hombres, y recorre con ellos las provincias, amenazando absorber el imperio. Pero como en Pekín le ven las cartas, le envían un emisario para que ajuste la paz con él; le dan algo de lo mucho que pide y una mañana el rebelde no amanece en el campo, con lo cual se disuelve el ejército; porque, lo mismo en sublevaciones que en batallas, en faltando el jefe se acabó el cotarro. Algunas veces, pocas, pillan al descontento y le cortan la cabeza, como acaeció hace cuatros años con el general Li, que se había enseñoreado del Tonkín, y cuyo recuerdo me trae a la memoria una frase del virrey de Cantón, que no debo pasar en silencio. Esto me da pie para relatar nuestra visita al _yamen_ o palacio del feudal lugarteniente del emperador.\"},{\"heading\":false,\"text\":\"Agregado en calidad de curioso a la misión diplomática que cerca de Li-u (nombre del virrey, que no hay que confundir con el del general rebelde) fue a desempeñar por entonces nuestro malogrado ministro en China D. Carlos A. de España, vestíme, como los demás señores del cortejo, de chaqué y sombrero gacho; y suprimidos con el frac los guantes como innecesario e incomprensible atributo de cortesía en las altas y bajas regiones celestes, encaminámonos todos en sendas sillas mandarinas forradas de algo que fue paño verde, y con alamares, que a haber conservado su envoltura de seda, hubieran sido negros, al yamen del gobernador, precedidos del porta-tarjetas para anunciarnos.\"},{\"heading\":false,\"text\":\"Forman el palacio en cuestión multitud de anchurosos patios con pabellones sueltos, que en nada difieren, como arquitectura y muebles, de las casas de los chinos ricos. En la puerta exterior unos harapientos culis disparan seis morteretes; y unos hombres vestidos de colorines, con la cabeza calzada de una especie de enorme cencerro colorado, del que salía como cimera una tiesa, larga y única pluma de faisán, se pusieron en fila junto a unos figurones gigantescos y ridículos de cartón, dioses porteros de la morada.\"},{\"heading\":false,\"text\":\"En el último patio, y acompañado de su séquito, nos esperaba el virrey, que graciosamente nos saludó a todos cerrando los puños, juntándolos por las falanges y agitándolos a la altura del pecho, como si zarandease una sonajera. Li-u, que respecto a fisonomía y modales está cortado por el patrón general de su raza, en la que no se nota nunca esta diferencia de cutis, de movimientos, de dicción y de forma que distinguen a nuestras clases privilegiadas del común de las gentes, vestía túnica de riquísimo satín celeste con caballa o balandrán azul tina, ostentando en el pecho, a modo de sacerdote bíblico, una placa cuadrada con los emblemas de su magistratura bordados en seda y oro. Botas de raso negro con ancha suela de fieltro blanco cubrían sus piernas hasta la rodilla; y de sus hombros pendía una esclavina de lustrosa piel de nutria, sobre cuyo fondo destacábase un profuso collar de cuentas de ámbar. Cubría su cabeza el sombrerete mandarín de castor, con un botón de coral del tamaño de un huevo de paloma, y de la parte posterior del bonete salía en sentido horizontal un plumero a modo de rabo de zorra, que se extendía hasta media espalda.\"},{\"heading\":false,\"text\":\"Invitados a pasar al pabellón de las recepciones, encontramos servida en él una mesa con dulces, vinos, tazas de té y cubiertos europeos. El virrey puso al ministro a su izquierda, lugar de honor según los usos locales, y al intérprete a su derecha. Los secretarios, la oficialidad del aviso _Marqués del Duero_, el vice-cónsul de España en Cantón, y el cronista, muy servidor de ustedes, nos acomodamos donde quisimos, permaneciendo con nuestros hongos encasquetados, para seguir el ceremonial de la etiqueta confucista. Los oficiales de Li-u, de pie detrás de nosotros a manera de coperos, nos escanciaban el champagne, y colmaban los platos de sabrosos limoncillos en almíbar, jengibre en dulce, guisantes azucarados y otras golosinas, por las que previamente había pasado sus manos el virrey, atestiguando así que podíamos comerlas con entera confianza, seguros de que no contenían veneno. El gobernador, entre bocado y bocado, daba una chupada a la pipa, que cada vez le cargaba su secretario particular; pues sabido es que el recipiente de estos utensilios no admite tabaco más que para una sola aspiración. Y allí empezaron a tratarse los asuntos de Estado con la asistencia de nuestros culis de silla y de los barrenderos, apaga luces y encargados de las salvas en el _yamen_, que hicieron irrupción en la sala, en uso por lo visto de un legítimo derecho; pues nadie los estorbó en su faena de interrumpir con sus animadas conversaciones y carcajadas a los conferenciantes.\"},{\"heading\":false,\"text\":\"--¿Qué noticias hay de la insurrección de Li? --preguntó nuestro plenipotenciario.\"},{\"heading\":false,\"text\":\"--Eso acabará pronto --contestó el virrey.\"},{\"heading\":false,\"text\":\"Y haciendo un gesto de contrariedad:\"},{\"heading\":false,\"text\":\"--El caso es --añadió-- que yo he tenido en la mano el evitar esta revuelta, porque días antes de levantarse en armas, y cuando todavía nadie sospechaba de su lealtad, vino a visitarme, y en su conferencia conmigo noté cierta vaguedad en su mirada que no me dio buena espina. Tanto, que tuve _una corazonada_, y determiné mandarle cortar la cabeza; pero luego ¡SE ME OLVIDÓ!\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"¡Desventurado país donde la vida de los ciudadanos está a merced de las corazonadas de un gobernador! A él debían mandarse a todos los que en la vieja Europa se rebelan contra la tiranía imaginaria del cumplimiento de sus obligaciones, porque ávidos de privilegios injustos, olvidan que sus ansiados derechos no son más que sus propios deberes ejercidos por otro.\"},{\"heading\":false,\"text\":\"Li-u, quitando la cobertera a su taza de té, nos invitó a apurar las nuestras; lo que significaba que la conferencia había dado fin.\"},{\"heading\":false,\"text\":\"Al día siguiente, embarcado en un bote de flores, remolcado por una lancha de vapor, fue a devolver la visita al ministro; sin que en ella ocurriera otro incidente digno de relato, que la súplica dirigida a don Guillermo Lobé, comandante del _Marqués del Duero_, de no saludarle con los cañonazos de ordenanza, hasta encontrarse fuera del alcance de los tacos. Lo que se cumplió, esperando para hacer la salva a que tomase tierra, y metido en la silla que allí le aguardaba, desapareciese entre la multitud precedido de soldados, tocando gongs y caracoles (que hacen las veces de trompetas).\"},{\"heading\":false,\"text\":\"Yo quería llevar a mis lectores a conocer la cárcel, pero no me atrevo, porque, francamente, es un espectáculo que con dificultad se resiste. Me limito, pues, a pasearlos por delante del establecimiento, sito en una plazoleta cerrada por un murallón, sobre el que se ven pintados monstruos de una fauna _sui generis_. Allí, convenientemente custodiados, se _solean_ centenares de presos con la coleta cortada, envueltos en andrajos, comidos por la miseria, y ostentando la importancia de su penalidad, quien con la cabeza metida en la canga, cual arrastrándose con los pies en cepo; otro, en fin, con una cadena sujeta a la garganta, y de cuyo extremo inferior pende una piedra como un queso de bola, en la que estriba su libertad, pues solo puede recobrarla el día en que, por efecto del uso, el adoquín se desprenda de la cadena.\"},{\"heading\":false,\"text\":\"Los mandarines encargados de administrar la justicia, proceden también por corazonadas. Cuando hay un delito que castigar, echan mano del presunto reo; pero si este se fuga, lo substituyen con su pariente más próximo, o en defecto de familia, con el vecino más inmediato. El interrogatorio da principio, suspendiendo al que va a servir para satisfacción de la vindicta pública, a un como banquillo de cama puesto en sentido vertical, amarrándole por los pulgares de manos y pies. Por no prolongar esta posición insostenible, el acusado reconoce las más veces una culpabilidad de que está inocente; y ya convicto, no hay más procedimientos ni apelaciones: se le mete en la cárcel y se aguarda la llegada de la primavera, que es la época en que a granel se verifican las ejecuciones. Ya no consisten estas, como antiguamente, en aserrar en dos a lo largo a la víctima, ni en cortarle lentamente en miles de pedacitos, ni en quemar a fuego lento, ni en ninguno de tantos primores como aún se admiran en efigie en la pagoda de los tormentos; pero se flagela hasta la muerte; se divide viva en setenta y cinco trozos a la mujer adúltera; se estrangula a los cómplices atándoles una soga al pescuezo y tirando un verdugo de cada uno de los cabos; se tritura liando al reo con una cuerda y oprimiendo el cable a merced de un torno; y se decapita, por último, a gusto del consumidor; porque si es pobre, se arrodilla en el suelo con las manos sujetas a la espalda y recibe dos o tres sablazos, hasta dividirle la cabeza del tronco: si tiene con qué pagar la supresión del sufrimiento, elige un ejecutor afamado, que con solo apoyar en la nuca la hoja, le corta de un golpe las vértebras cervicales, ni más ni menos que como se descabella a un toro: y si es muy rico, compra quien lo reemplace en el cadalso; lo que se obtiene, tanto por la indiferencia con que mira la muerte el chino de precaria condición (que halla en este mercado manera de que sus hijos le hagan honras fúnebres de que carecería de otra suerte), cuanto por la benevolencia de los tribunales, que se contentan con que al crimen suceda el castigo, sea quien fuere el que lo sufra: por último, cuando se cuenta con influencias, se soborna a los jueces, y entonces la faena se lleva a efecto fuera de la época reglamentaria; pero en lugar de salir el reo de la cárcel metido en un canasto con las piernas colgando _coram populo_ y a la luz del día, lo llevan por la noche al campo del suplicio, donde le aguarda una litera que lo conduce a otra provincia, y el público se da por satisfecho con creer que la cabeza del inocente que yace en el suelo es la del verdadero criminal.\"},{\"heading\":false,\"text\":\"Después de referir tantos horrores, quisiera concluir con una frase de consuelo. Ya dí con ella:\"},{\"heading\":false,\"text\":\"No hablemos más de Cantón.\"}]},{\"title\":\"La metempsicosis — capítulo I\",\"blocks\":[{\"heading\":false,\"text\":\"Pues señor, era una vez un tal don Abundio Recogido con quien tan bien cuadraba el apellido por la morigeración de sus costumbres, como contrastaba el nombre por la escasez de sus recursos. Ex-profesor de Historia de un instituto de provincia, vivía reducido a los estrechos límites de su jubilación de catedrático de entrada, pues jamás pudo conseguir el ascenso. Era sin embargo feliz, tan feliz como puede serlo un hombre que a los sesenta años habita un piso cuarto en la calle de la Palma Alta de Madrid, posee una regular biblioteca, se hace servir por una maritornes alcarreña el chocolate con buñuelos a las siete de la mañana, come a las dos su eterno cocido, y digo eterno por carecer de principio y de fin, y cena a las once su inevitable guisado con patatas, precedido en invierno de unas sopas de ajo y seguido en la época canicular del indigesto pero refrescante gazpacho con pepino.\"},{\"heading\":false,\"text\":\"Por las tardes de tres a cinco o de cinco a siete, según la estación, se encaminaba _pian pianino_ a la calle de la Victoria y, ya saboreando un vasito de café con leche, ya paladeando un chico de horchata, repasaba la prensa del día que el camarero le iba presentando, seguro de que los dos cuartos de propina no habían de faltarle. Todos los parroquianos del café de la Vizcaína conocían a don Abundio; pero ninguno le trataba. No tenía amigos, y desde diez años atrás se le había bautizado con el mote de Juan Palomo, por aquello de _yo me lo guiso y yo me lo como_ que reza el refrán. Los domingos amenizaba el Moka con una copita de ron o las chufas con una ración de bizcochos. El primero de mes se permitía el despilfarro de una peseta para asistir al paraíso del teatro Real, y el quince se deleitaba con lo que entonces era literatura dramática en el teatro Español, donde por cinco reales ocupaba un asiento de galería alta. Practicaba las fiestas de precepto, nunca faltaban en su bolsillo los cuatro ochavos que destinaba diariamente a la limosna de un anciano, de una mujer, de un niño y de un lisiado, y así tranquilo, ordenado y solo, llevaba don Abundio su existencia calzada con chanclos, tanto para evitar el lodo del mundo como para pasar por él sin hacer ruido y evitar el molestar y que le molestasen.\"},{\"heading\":false,\"text\":\"Había con todo una nube en su horizonte, y el género de vida que se había impuesto era como una especie de expiación de su pasado. Hagamos historia.\"},{\"heading\":false,\"text\":\"Allá en sus mocedades, don Abundio había tenido por amigo fraternal a un don Serapio Benigno Prudencio Manso y Cordero, natural de Toro, propietario, viudo y padre de un niño llamado León, de quien el catedrático de historia había sido padrino al mismo tiempo que albacea testamentario de la madre. El lazo que los unía era tan estrecho que no tenían pan partido como suele decirse; y en casa del propietario había el cuarto de don Abundio, el cubierto de don Abundio y hasta las zapatillas de don Abundio, pues allí se descalzaba, comía a menudo y aun pernoctaba con frecuencia.\"},{\"heading\":false,\"text\":\"_Fragility, your name is woman_: Fragilidad, tu nombre es mujer, ha dicho Shakespeare, y aun cuando yo no sé lo que quiso dar a entender con ello el poeta de Stratford, aquí lo aplico por si viniera bien, pues la fragilidad de don Serapio le condujo a contraer segundas nupcias en cuanto hubo acabado de llorar los doce meses reglamentarios a su difunta esposa.\"},{\"heading\":false,\"text\":\"Ocioso creo consignar que don Abundio fue padrino de la boda y que, si bien retiró sus zapatillas del hogar conyugal, siguió compartiendo frecuentemente con sus amigos el cocido de la amistad sazonado con el chorizo de la abundancia.\"},{\"heading\":false,\"text\":\"_Non bis in idem_, dice el proverbio latino, que cito para que vean ustedes que lo mismo manejo yo las lenguas muertas que las vivas, y también para probar que efectivamente no se debe reincidir en nada si es esto lo que aquella máxima prescribe; pues así como le pudo salir bien a don Serapio la segunda edición de su esclavitud, le salió en la frente, como vulgarmente se dice, para dar a entender que algo le sale a uno mal.\"},{\"heading\":false,\"text\":\"Y en efecto, doña Remigia, pues así se llamaba la consorte, le salió rana; y no lo digo porque careciese de pelo, que mata era la de sus trenzas capaz de adornar la cimera del casco de un oficial de caballería; lo que ya creo que había tenido lugar cuando estuvo en relaciones con un teniente de lanceros de Calatrava; y en cuanto a guapa, llamábanla en su pueblo la hermosa Judit no solo por sus encantos personales sino porque hacía perder la cabeza a cuanto Holofernes se le ponía a tiro. Pero pagada de sí misma, esclava de su belleza, manirrota y poco dada al trabajo, resultó madrastra del hijastro y cara mitad del esposo; cara, en lo que tenía de dispendiosa, y mitad en lo que dividía al entero. Alegre como unas castañuelas eso sí; porque su cama podría parecer un plantel de espárragos por los cuarenta dedos que ella y su marido dejaban asomar por los agujeros de las sábanas, las calcetas asemejar a los desiertos africanos por no tener una planta, los baberos del niño competir en barbas con un albañil en sábado; pero ni una noche faltaría en su casa la tertulia de hombres solos, en la que se entretenían en juegos inocentes, entre los cuales el escondite, siendo don Serapio el encargado de buscar siempre sin encontrar nunca, especialmente a su mujer y a un empleado en consumos que tenían una habilidad notable para esconderse.\"},{\"heading\":false,\"text\":\"Hubo a la sazón una de esas expansiones populares que, como lluvia tras sequía, lo fecundan todo, y del chaparrón aquel brotó una milicia nacional. Don Serapio fue nombrado capitán de la cuarta del primero y don Abundio su teniente. Con este motivo las visitas del catedrático se sucedían sin interrupción, pues a los deberes de la amistad se agregaban las exigencias de la patria.\"},{\"heading\":false,\"text\":\"Aunque don Abundio frisaba ya en los cuarenta años, conservaba rasgos de esa belleza a lo Espartaco que tanto cautiva a ciertas Evas idólatras de la forma. Además en su calidad de catedrático de historia, relataba con frecuencia la de España a doña Remigia que, a fuer de mujer, se encantaba aprendiendo vidas ajenas. Si a esto se añade el aliciente del uniforme y la veleidad de la dama, fácilmente se deducirá de todo junto que, nueva edición de la señora de Putifar, doña Remigia trató de quedarse entre las manos más de una vez la capa de don Abundio. Fiel este al que, imitando los tiempos de la Edad Media, llamaba su hermano de armas, rechazó como pudo las obsesiones de aquel súcubo tentador en quien la virtud de la víctima no hacía sino aguijonear el deseo.\"},{\"heading\":false,\"text\":\"Pero _ce que femme veut, Dieu ou le diable le veut_. ¡Cuidado si sé yo lenguas! Vamos al decir que doña Remigia se empeñó en que allí fuera Troya, y Troya hubo con su Paris y su Menelao correspondientes.\"},{\"heading\":false,\"text\":\"Un día de parada, estando reunido el batallón en el patio de un ex-convento de carmelitas, don Serapio se apercibió de que se había dejado olvidada en su casa la alocución que debía dirigir a su compañía en el convite que después de la formación había de darle, para agradecer el honor de haberle elegido capitán. Don Abundio fue el encargado de ir en su busca. Al entrar en el domicilio de su jefe, lo primero que vio fue a doña Remigia acabando de ataviarse para asistir a la parada. Estaba hecha un brazo de mar; pero si hemos de ser justos, él no la iba en zaga. Aquellos pantalones blancos y relucientes cuya posesión se disputaban por arriba dos tirantes con las hebillas corridas hasta los hombros y por debajo unas trabillas con las que parecía llevar los pies en cabestrillo, eran el _summum_ de la marcialidad de afición. ¿Pues dónde me dejan ustedes la casaca de paño verde botella con vivos y golpes de color de canario, que amarillo era el distintivo de los fusileros, y botones de metal numerados a un lado y otro del _péti_ cerradito en forma de pechuga de pichón? No había medio de resistir a un hombre que sobre sus cinco pies y cinco pulgadas se ponía un morrión de un palmo cumplido, con una visera como el pescante de un coche, una chapa hasta la imperial despidiendo rayos de latón y un par de carrilleras con escamas. Pues no digo nada cuando repicaban gordo y le añadían el último piso al chacó. El golpe maestro era aquella cuarta de plumero en forma de nabo arqueado hacia delante, utensilio de triple utilidad, pues no solo quitaba el sol, sino que aventaba las moscas y llenaba de cortesías a los transeúntes. En esta forma, más la espada en el biricú y el corbatín de suela, se presentó don Abundio ante la esposa de don Serapio; y si hoy estaría para pegarle un tiro, entonces no cabe duda que estaba seductor.\"},{\"heading\":false,\"text\":\"Doña Remigia al verle lanzó una exclamación de asombro que le hizo dar tres o cuatro vueltas al plumero. Él se descubrió, y arreglándose el cucuné le expuso el objeto de su visita. Busca por aquí, busca por allá, ni sombra de alocución en el pupitre de don Serapio. Con la confusión y las prisas debieron ponerse tan cerca uno del otro, que el fleco de la berta de doña Remigia se enredó en uno de los botones de la casaca del catedrático, y cátenlos ustedes trabajando por desasirse. Primero todo fueron risas, después ya empezaron como a ponerse formales, el fleco no se desprendía y los dedos se enredaban. En suma, cuando don Serapio que había encontrado el discurso en el fondo del morrión, entró en la casa para decirle a su amigo que no se molestase en buscarlo, pues había dado con él donde menos lo presumía, es decir cerca de su cabeza, encontró al teniente ascendido, y, señalándole la puerta, dimitió la capitanía y se retiró con su mujer a Toro de donde ya he dicho que era natural.\"},{\"heading\":false,\"text\":\"Los remordimientos, la vergüenza y el desprecio de sí mismo que le inspiraba su conducta, produjeron en don Abundio unas viruelas que le pusieron entre la vida y la muerte. Por fin se restableció; pero ya no volvió a ser ni sombra de lo pasado. Transcurrido el tiempo reglamentario pidió su jubilación y retiróse a Madrid donde le tenemos buscando por la paz del cuerpo la tranquilidad del espíritu.\"},{\"heading\":false,\"text\":\"Pero _nada hay duradero sobre la tierra_, ha dicho el sabio (y no lo repito en griego no sé por qué).\"},{\"heading\":false,\"text\":\"Un día recibió una carta que, si empezó llamándole la atención por la ridícula forma del sobre, le llenó de alarma al abrirla y verla fechada en Toro. Decía así; salvo la ortografía:\"},{\"heading\":false,\"text\":\"«Muy señor mío y mi dueño: Tengo el gusto de participar a usted que ayer se murió el difunto don Serapio Manso, lo que hemos sentido mucho y rogad por él. Lo hemos enterrado junto con doña Remigia (q. b. s. p.) que también se murió hace dos días de una indigestión en el vientre que el médico dice que es cólera; pero yo no quiero que sea cólera que para eso soy alcalde, servidor de usted, y después se asustarán los vecinos.\"},{\"heading\":false,\"text\":\"»El niño está en mi casa, jugando a la pelota de luto, porque son criaturas que nada entienden de aflicciones, y el sastre que es el pregonero se lo ha cosido en dos trancos.\"},{\"heading\":false,\"text\":\"»Don Serapio ordena y manda que usted sea tutor y curador de Leoncito, y se lo remitiremos si usted no viene según la disposición del difunto cuya vida Dios guarde muchos años. Juan Artola -- Alcalde. Por no saber firmar hace la señal de la cruz, †.»\"},{\"heading\":false,\"text\":\"Don Abundio lloró al amigo, rezó por la pecadora, comprendió que aquella disposición testamentaria era el castigo impuesto a su felonía, y quince días después entraba en Madrid con su pupilo León.\"}]},{\"title\":\"La metempsicosis — capítulo II\",\"blocks\":[{\"heading\":false,\"text\":\"El angelito acababa de cumplir los quince años y tenía ya la cara llena de vello como melocotón verde de Calatayud. Mal criado y voluntarioso como si fuera hijo de su madrastra, había que darle gusto en todo, so pena de que escandalizase el barrio a berridos. Insolente a fuer de rico ignorante, y desarrollado por las faenas agrícolas de su pueblo, don Abundio no tenía sobre él dominio alguno físico ni moral. En vano trató de inculcarle algunas nociones de Historia; los resultados fueron nulos. Una vez al preguntarle quién era Colón respondió que un hombre que había puesto un huevo de punta; y en Geografía sostenía que la capital de Holanda era _Bola_, de donde tomaba su nombre el queso.\"},{\"heading\":false,\"text\":\"¿Asistir a las academias? Perdone por Dios, hermano. De pedrea todos los días, eso sí, con los pilletes de la puerta de Santa Bárbara; y llenos andaban los encantes de sus libros de enseñanza que malvendía para comprar un tendido de sol en los novillos, su pasión dominante. Él era siempre el primero en saltar a la arena en cuanto tocaba el turno de los embolados para el público, y más de un revolcón le costaba la aficioncilla. Su aula predilecta era el matadero, de donde siempre volvía con algún chirlo más y unas tajadas menos.\"},{\"heading\":false,\"text\":\"En la casa todos eran sus víctimas. Tan pronto era el perro de aguas, compañero inseparable de don Abundio, el que atado por el rabo y sujeto a una escarpia de la pared, pasaba media hora boca abajo atronando la manzana con sus aullidos, como el _minino_ el que, con un mazo de cohetes encendidos en la cola, salía bufando por la calle como alma que lleva el diablo. El pobre tutor le hacía reflexiones amenizadas siempre con su poquito de Historia para ver si, por la misma puerta por donde trataba de inculcarle la morigeración y el respeto, le entraba también la instrucción; pero, nada; era como lavarle la cara con jabón a un burro negro.\"},{\"heading\":false,\"text\":\"Un día en que León había atado mano con mano y pata con pata a los dos pobres bichos, unidos así de costado como los hermanos siameses, y los había lanzado a la calle con unas alcuzas en las extremidades posteriores, don Abundio, que atropellado por los fugitivos midió el suelo, habló así a su pupilo:\"},{\"heading\":false,\"text\":\"--Tu conducta es salvaje, León. El que hace daño a los animales está en camino de hacérselo a los hombres. Además, si tú no fueses un ignorantón, sabrías que los egipcios creían en la metempsicosis o transmigración de las almas, por la cual el hombre que no había cumplido con todos sus deberes morales y sociales, en vida, pasaba al morir a la condición de bruto o bestia inmunda. Esta creencia, más generalizada de lo que algunos suponen, la profesan también los chinos, quienes consideran como un don celeste el transmigrar a un cerdo, porque de ese modo solo ha de durar un año la esclavitud de su espíritu en una envoltura irracional. Ahora bien; ¿quién te asegura que semejante castigo no es una de las manifestaciones de nuestras penas eternas? ¿Por qué no ha de formar parte eso del infierno o del purgatorio de los creyentes? Y si es así ¿quién te dice que al martirizar a un pobre bruto no estás lastimando a un amigo, a un pariente, acaso a los mismos que te dieron el ser?\"},{\"heading\":false,\"text\":\"Yo no sé el efecto que esta homilía produjo en el ánimo del adolescente; pero lo que sí puedo atestiguar es, que algunos días más tarde, la maritornes volvió de la plazuela trayendo una marranilla de leche que su padre (el de la criada, no el de la _lechona_) remitía a don Abundio, por vía de regalo, con el ordinario de su pueblo; y que León, aprovechando un descuido, cargó con ella y la vendió al primer transeúnte para, con su producto, asistir a la corrida de toros. El ex-profesor de Historia, enfurecido ante la pérdida de aquel suculento manjar, raro en su mesa, repetía:\"},{\"heading\":false,\"text\":\"--¡Vender una marranilla de tres meses!\"},{\"heading\":false,\"text\":\"--Esos hace que lloramos a doña Remigia --contestó el pupilo--. ¿Querría usted que me expusiera a comerme a mi madrastra?\"},{\"heading\":false,\"text\":\"*       *       *       *       *\"},{\"heading\":false,\"text\":\"Y efectivamente, desde aquel día, empezó a dejar en paz a los animales; pero la emprendió con las personas; y así llenaba de recortes de ortiga la cama de su tutor, como conteniendo el aliento y de puntillas, se acercaba por detrás a la alcarreña mientras espumaba el puchero, de bruces sobre el fogón, y metiendo una mano entre el zagalejo corto y sus piernas sin medias, le clavaba los dedos en la robusta pantorrilla al par que imitaba el ladrido de un perro; con lo que la pobre muchacha al principio se asustaba mucho; pero luego se fue acostumbrando.\"},{\"heading\":false,\"text\":\"Las cosas iban llegando a tal punto que el infeliz don Abundio no gozaba momento de reposo. César Cantú, Lafuente, Mariana y multitud de historiógrafos habían desaparecido de su biblioteca y tomado la forma de tendidos; el uniforme de teniente de nacionales yacía en una casa de préstamos de donde salió el dinero para una tienda de manzanilla. Finalmente una noche en que, a hora muy avanzada, León se dirigía a oscuras desde su cuarto al de la alcarreña con intención de darle algún susto, tropezó en las sombras con su tutor que, con los brazos abiertos, buscaba la manera de orientarse por el pasillo.\"},{\"heading\":false,\"text\":\"--¿Qué hace usted aquí? --le preguntó con severidad don Abundio.\"},{\"heading\":false,\"text\":\"--¿Y usted? --le replicó el mozalbete.\"},{\"heading\":false,\"text\":\"--Yo he sentido pasos; y temeroso de alguna trastada de las de usted, me he levantado a velar por el reposo de esa inocente criatura.\"},{\"heading\":false,\"text\":\"--Pues yo he venido a preguntarle si había puesto a remojo los garbanzos.\"},{\"heading\":false,\"text\":\"Y al día siguiente, con el pretexto de dar un paseo matinal, tutor y pupilo se encaminaron a la calle de _Sal si puedes_, donde Leoncito quedó como pensionista en el colegio de don Tranquilino Verdugo, bajo la advocación de San Juan Capistrano.\"},{\"heading\":false,\"text\":\"Ustedes habrán oído decir, y por si no yo se lo digo, que no hay nada peor que un chico travieso a no ser dos chicos traviesos. Pues bien, en el colegio de don Tranquilino había treinta pensionistas, de los que pronto se hizo jefe nuestro héroe; y si antes León valía por cuatro, concluyó por hacerse insoportable con la emulación de sus compañeros.\"},{\"heading\":false,\"text\":\"El desgraciado director, hombre entrado en edad y cuyas narices eran una bomba aspirante de rapé, apeló a todos los correctivos imaginables para meterlo en cintura; pero no alcanzó mejor suerte que don Abundio. Ya era un bramante sujeto por un extremo a la mampara y prendido por el otro con un alfiler a su peluca el que dejaba al profesor con la calva al aire cada vez que abrían la puerta; ya una vejiga provista de un pito la que, al ir a sentarse en el sillón, aplastaba con su cuerpo y le hacía saltar hasta las vigas creyendo, con el quejido que daba al deshincharse, que había despanzurrado a su gata de Angora. Por supuesto que no cejó en su manía de asustar a las criadas; pero a la de don Tranquilino, que era del Escorial, le cayó en gracia el chico, y lejos de incomodarse, engordaba, como suele decirse, con las travesuras de León.\"},{\"heading\":false,\"text\":\"Un domingo del mes de diciembre en que había novillos con mojiganga y dos toros estoqueados, el director tuvo la desgraciada ocurrencia de llevarse de paseo a sus alumnos por la calle de Alcalá para que asistiesen al espectáculo de la ida de la gente a la plaza. León, que formaba a la cola de la ruta, contemplaba con ojos de envidia aquel torrente humano que a pie, en berlina, en ómnibus, en calesa y aun en tartana, se precipitaba desde la Puerta del Sol hasta la Cibeles como desbordando por un embudo invertido. La cara de satisfacción de los transeúntes, la idea de las emociones que iban a experimentar aquellos con quienes se codeaba al paso y de quienes tan lejos estaría dentro de poco, el humo de los cigarros, pues hasta los que no van a los toros fuman el día de corrida para hacer creer a los que los ven que van; el ruido, el sol, el conjunto, en fin, trastornaron el juicio del hijastro de doña Remigia, y unas se le iban y otras se le venían sin cocérsele el pan en el cuerpo. De repente la luz parece como que adquirió más intensidad y el ambiente un olor como de carne muerta y tripas rotas. Todas las miradas convergieron a un punto dado. Era la cuadrilla de chulos que en coches abiertos se dirigían al redondel luciendo colores, lentejuelas, moñas y pasamanería. La sangre afluyó al corazón del aficionado y un velo cubrió su vista; pero no tan tupido que le impidiese percibir entre la comitiva a un picador que, caballero en una alimaña, llevaba a la grupa a uno de esos pilletes que les sirven de escuderos y que, bajo la égida de su protector, tienen entrada triunfal y gratuita en la plaza. León no resistió más; echó a correr como deudor perseguido por acreedores y, agarrando de un tobillo al escudero, lo desmontó de una sacudida y de un salto ocupó su lugar. Aunque se subía el embozo del capote para no ser conocido, sus camaradas de colegio le olfatearon y fueron con el soplo a don Tranquilino que, ahogado por la pena, y en la imposibilidad de darle alcance, volvió a casa con la ruta y participó a don Abundio lo ocurrido, consignando en la carta su irrevocable resolución de despedir al mozalbete.\"},{\"heading\":false,\"text\":\"El ex-catedrático de Historia, que le estaba poniendo a la alcarreña unos pendientes de similor que le había regalado por su buen comportamiento, recibió la misiva como si fuera el casero, es decir, de mal humor, y se echó a la calle confeccionando un discurso con que ablandar a don Tranquilino y evitarse la irrupción del ahijado en su hogar, si bien metiéndose tres reales en el bolsillo del chaleco para, si no lograba convencer al señor Verdugo, comprar a su criada unas medias de estambre. En todo pensaba el bendito señor.\"},{\"heading\":false,\"text\":\"Llegado que hubo al colegio de San Juan Capistrano, pudo convencerse de que la determinación de don Tranquilino no tenía vuelta de hoja. Le ofreció aumentarle los honorarios, le habló de Cicerón y de Séneca probándole que sabía más que ellos. Nada, ni las dádivas, ni la adulación quebrantaron aquella naturaleza de diamante: «Usted que tiene criada --concluyó por decirle-- comprenda usted lo que a la mía le espera».\"},{\"heading\":false,\"text\":\"En estas estaban departiendo en el refectorio, pues ya había anochecido y los muchachos cenaban bajo la vigilancia del director que andaba viendo a quienes tocaba el turno del castigo para ahorrarse las diez raciones que diariamente suprimía bajo el pretexto de penas correccionales, cuando se presentó León con la gorra encasquetada y embozado en un capote que, si no tan roto como el del lazarillo de Tormes, quien tiraba piedras sin desembozarse, estaba reducido al tercio de su peso específico en virtud de tanto agujero por donde se tamizaba su individuo.\"},{\"heading\":false,\"text\":\"Verle llegar y caer sobre él una granizada de improperios de don Tranquilino y don Abundio acompañada de una rechifla de los imberbes fue cosa simultánea. León impávido se mantenía de pie en un rincón.\"},{\"heading\":false,\"text\":\"Restablecido el orden y penetrado el tutor de que no tenía más remedio que compartir el hogar con su ahijado, pronunció su discurso de despedida y exhortó al reo a que pidiera perdón a su víctima. Resistióse aquel, y como don Abundio se empeñara en apelar a la violencia, el muchacho dejó caer su capa en el suelo, blandió un par de banderillas que ocultas llevaba y, aprovechando la actitud de don Tranquilino que había dejado caer su pañuelo de yerbas y se disponía a recogerlo, se las clavó de frente en medio de las dos paletillas y emprendió la fuga entre la algazara de los alumnos, los berridos del director y las convulsiones de don Abundio que, con la boca a un lado y agitando pies y manos como si nadase, se revolcaba por los suelos. Media hora después sucumbía el desgraciado a un ataque de apoplegía fulminante, y a don Tranquilino, de bruces en la cama, le hacían la primera cura.\"},{\"heading\":false,\"text\":\"De este no volveremos a saber nada. De los demás nos ocuparemos en los capítulos siguientes.\"}]},{\"title\":\"La metempsicosis — capítulo III\",\"blocks\":[{\"heading\":false,\"text\":\"Han transcurrido cinco años desde los últimos acontecimientos y nos hallamos _donde Tajo a Jarama el nombre quita_, o sea en la _provincia_ de Aranjuez, como decía un amigo mío que se gastó todo su patrimonio en que le eligieran diputado con el objeto de ser nombrado gobernador, lo que no pudo lograr ni siquiera del punto en que tiene lugar esta escena.\"},{\"heading\":false,\"text\":\"Yo les describiría a ustedes Aranjuez; pero temo abusar, porque pocos serán mis lectores que no hayan estado allí, y además porque con la explicación de los países pasa lo que con la de las personas en las novelas, que por más que los autores se empeñen en pintarnos la forma de sus narices, el color de sus ojos y el timbre de su voz, los personajes pasarían impunemente al lado de uno sin cuidado de ser conocidos, a no haberlos visto antes, pues en la cara es donde se admira la fecundidad y la inventiva de la naturaleza: todas están compuestas de los mismos órganos y ninguna se parece.\"},{\"heading\":false,\"text\":\"Así pues plantemos árboles, tracemos alamedas, hagamos brotar abundantes pastos, dejemos serpentear por allí brazos de ríos, y que cada cual se lo forme en su imaginación como le parezca que ha de estar más bonito y más adecuado a un sitio real cantado por los poetas y atravesado por el ferrocarril. Solo les exijo a ustedes no dar al olvido que allí hay dehesas en donde se crían toros que, después de corridos y martirizados en el espectáculo más típico y peculiar de nuestro país, nos los comemos en estofado los españoles y las españolas.\"},{\"heading\":false,\"text\":\"_La luna de octubre siete meses cubre_, dice el proverbio; y, como la de aquel año hubiera sido esplendente y limpia, he aquí por qué en el mes de enero, en que empieza este relato, el sol brillaba en el cielo como el ojo de una muchacha bonita; que si a soles comparan los poetas los ojos, no hay razón para que a ojo no compare yo el sol, si es verdad aquello de que el orden de los factores no altera el producto.\"},{\"heading\":false,\"text\":\"En fin, eran las dos y sereno de una tarde del mes de los gatos, y la yerbecilla, caldeada por los rayos de Febo, parecía cama de canónigo atemperada por confortante calentador.\"},{\"heading\":false,\"text\":\"Sobre aquella sábana de esmeralda, rumiando los tallos tiernecitos, como quien después de una comida abundante no desdeña el paladear una golosina, un enorme cabestro yacía muellemente tendido haciendo firmas con la cola sobre el suelo, como las hace cualquiera con el bastón cuando está sentado pensando en las musarañas. Un colosal cencerro pendiente de un collarín de baqueta cortaba las líneas de su cuello, y era su pelo cárdeno como espalda de azotado. Colmillos de elefante de Bankok eran sus astas, y por la redondez de su cuerpo parecía ir diciendo a todos: «Pues señor, no estoy descontento de mi suerte.»\"},{\"heading\":false,\"text\":\"Y apuesto a que ya han reconocido ustedes en él al cónyuge de doña Remigia, al bueno de don Serapio que, después de seis años de transmigración, estaba reducido a custodiar cornúpetos jarameños, del mismo modo que entre los seres racionales se cuida de las odaliscas en el harem.\"},{\"heading\":false,\"text\":\"No olviden ustedes que, aunque transmigrado, don Serapio conservaba recuerdos de su vida anterior, porque de lo contrario ¿dónde estarían la gracia y el castigo de la metempsicosis? Sentado este precedente, asistamos a su soliloquio penetrando en sus reflexiones.\"},{\"heading\":false,\"text\":\"«Lo que es este año se puede decir que no tenemos invierno. Miren ustedes qué días estos. Yo estoy con un palmo de lengua fuera; y si es los muchachos, andan por ahí revueltos como en canícula; hace materialmente calor. La verdad es que esta existencia no deja de tener su encanto, sobre todo para las naturalezas pacíficas como la mía. Nadie se mete con uno, a uno le importa un pito todo cuanto pasa a su lado; buena yerba, buen establo y ningún quebradero de cabeza. Verdad es que tampoco me la quebraba mucho cuando era hombre; pero me la quebraban los demás, porque ya era el inquilino que no pagaba, el investigador de hacienda que me aumentaba la contribución, y eso que siempre que pasaba por el pueblo venía a vivir a mi casa; por más señas que como al maldito no le gustaba acostarse temprano, mi pobre mujer se tenía que quedar acompañándole hasta las tantas para hacerle la tertulia, porque lo que es yo con la primera campanada de las diez las buenas noches y a dormir. Ahora, nada; en cuanto amanece viene el mayoral, me dice: arriba, _Manteca_, y yo _dolón, dolón, dolón_ a llevar a pacer a la gente del bronce; una vez en la pradera, a comer y a revolcarse; si hay alguna disputilla, de las que siempre tienen la culpa las vacas, los meto en cintura, porque, parece mentira; pero ahora que no tengo ni voluntad, ni inteligencia, ni raciocinio, ni nada, soy más valiente que cuando lo tenía todo. Y así que empieza a anochecer vuelve a decir el mayoral: arriba, Manteca, y yo _dolón, dolón, dolón_, a casa con ellos. Y ¡cómo me obedecen! ahora sí que puede decirse que soy capitán y no cuando lo era de nacionales, que tenía descuidados todos mis asuntos con la bendita patria, y el tiempo se me pasaba en recibir a los subalternos que me venían a pedir la orden, hasta que tuve que tomar la determinación de que fuera mi mujer la que se entendiera con los oficiales. ¡Pobre Remigia! ¿Qué habrá sido de ella? La echo mucho de menos, no porque la necesite, que maldita la falta que me hace el que venga a turbar mi sosiego, sino por saber qué suerte ha sido la suya. ¡Cómo lloró su extravío! se empeñó en hacer testamento porque quería suicidarse, lo que hubiera llevado a cabo a no ser porque me previno el escribano y convinimos él y yo en que pretextaría un quehacer apremiante siempre que ella fuera a su casa con objeto de testar.\"},{\"heading\":false,\"text\":\"»Pues así y todo estuvo Remigia yendo diariamente por espacio de un año en busca de don José, hasta que se le pasó aquello no sé cómo. La verdad es que yo procedí muy cruelmente; llevármela a Toro donde no tenía trato con nadie, ella, acostumbrada toda la vida a alternar con los unos y con los otros... Pues no digo nada, despedir de mi casa a Abundio, al amigo de toda la vida; porque de aquel incidente, como de ello me convenció mi mujer, solo era responsable la casualidad, el demonio que anda suelto y hace que se enrede un fleco en un botón, precisamente en el momento en que a mí se me ocurre volver a mi casa; porque si yo me quedo con el batallón en el convento, nada. ¿Y cómo estará mi hijo? ¡Qué adelantos habrá hecho bajo la inspección de Abundio para quien lo mismo eran griegos y romanos que paja y avena para mí! ¿Vivirán? ¿Serán infelices? ¿Dónde estarán?»\"},{\"heading\":false,\"text\":\"Y así pensando, y con la boca abierta se fue quedando dulcemente dormido, cayéndosele la baba de gusto.\"},{\"heading\":false,\"text\":\"Pocos minutos hacía que se hallaba entregado al reposo, cuando un alboroto promovido en la torada vino a sacarle de su letargo.\"},{\"heading\":false,\"text\":\"--¿Qué será ello? --se preguntó don Serapio levantándose y dirigiéndose hacia el teatro de la lucha. En esto vio llegar una vaca que desalentada corría hacia él gritando:\"},{\"heading\":false,\"text\":\"--Señor Manteca, señor Manteca; venga usted pronto, que se matan.\"},{\"heading\":false,\"text\":\"--Pero ¿qué ocurre?\"},{\"heading\":false,\"text\":\"--Un toro que han traído de las dehesas del Norte, donde nadie le podía domeñar y que, dada la fama de usted, le ponen bajo su vigilancia. Apenas entró en el prado se empeñó en decirme chicoleos, y como mi _Caramelo_ es tan celoso, se trabaron de palabras, de las palabras vinieron a las manos, sus amigos tomaron parte por él, y allí los tiene usted a todos revueltos sin que zagales ni mansos los puedan hacer entrar en razón.\"},{\"heading\":false,\"text\":\"Un silbido acompañado de un grito de _Manteca_ lanzado por el mayoral, le hizo apretar el paso a don Serapio que, sonando el cencerro, se interpuso entre los combatientes. El intruso era un toro de cinco años berrendo en negro, bonito de estampa y duro de cabeza; pero en cuanto don Serapio metió la suya en el corro, allá fue rodando el otro como tente-tieso de mojiganga.\"},{\"heading\":false,\"text\":\"--¿Conque contigo no ha podido nadie? Pues a ver si yo te enseño a tratar a las personas decentes.\"},{\"heading\":false,\"text\":\"Y a darle se disponía un nuevo revolcón, cuando el vencido bajando la voz para no ser oído de nadie le dijo al cabestro:\"},{\"heading\":false,\"text\":\"--Detente, Serapio. ¿No me reconoces?\"},{\"heading\":false,\"text\":\"--¡Abundio! --murmuró este con un ahogado gemido solo perceptible del catedrático. Y los dos quedaron mirándose silenciosos.\"},{\"heading\":false,\"text\":\"Los demás testigos de la escena fueron a comentar el triunfo de Manteca diseminados en corrillos por el prado, y cuando los dos estuvieron solos se hablaron de esta manera:\"},{\"heading\":false,\"text\":\"--¿Tú por aquí, Abundio? ¡Qué alegría! Pero déjame que te mire. Te encuentro hasta buen mozo. Al pronto no te había reconocido.\"},{\"heading\":false,\"text\":\"--Pues yo a ti, Serapio, al momento. No has cambiado nada; estás lo mismo.\"},{\"heading\":false,\"text\":\"--Cuéntame qué ha sido de ti. ¿Te has casado? ¿Y mi hijo? ¿Vive? ¿Es hombre de bien? ¿Estudia mucho?\"},{\"heading\":false,\"text\":\"Aquí el berrendo lanzó un suspiro y, tomando sus precauciones para no dar a su amigo tan triste noticia de sopetón, fue poco a poco y con rodeos detallándole las proezas de León hasta el paso de las banderillas, último detalle de que había podido ser testigo el profesor de historia. Por supuesto que bien pudo ahorrarse ceremonias, porque don Serapio en vez de afligirse lanzó una sonora carcajada y pareció divertirse mucho con el relato.\"},{\"heading\":false,\"text\":\"--¡Qué diablillo! ¡Qué diablillo! --decía sin dejar de reír--. La misma afición de su madre, que esté en gloria, que se moría por los toreros. Y en cuanto a lo de asustar a las criadas, vamos, no lo ha robado de nadie, ¡que yo también cuando chico las daba cada susto! ¡Qué diantre! Todos hemos sido jóvenes. ¿Verdad, Abundio?\"},{\"heading\":false,\"text\":\"Y diciendo así le daba con el cuerno en el hombro maliciosos golpecitos.\"},{\"heading\":false,\"text\":\"--Serapio, tu grandeza de sentimientos me humilla y me degrada más y más a tus ojos.\"},{\"heading\":false,\"text\":\"--¿Qué quieres decir con eso?\"},{\"heading\":false,\"text\":\"--Que no obstante mi conducta para contigo, me conservas tu amistad y...\"},{\"heading\":false,\"text\":\"--¿Vas a ponerte de mal humor por una niñería que no vale un pito? Ya sé yo que en el fondo ninguno de los dos teníais la culpa de aquello. ¡Ea! lo pasado, pasado y abracémonos.\"},{\"heading\":false,\"text\":\"--Pero... --insistía el profesor titubeando.\"},{\"heading\":false,\"text\":\"--Si no me abrazas para probarme que no me guardas rencor por haberte echado de mi casa, me incomodo.\"},{\"heading\":false,\"text\":\"Y los dos amigos se confundieron en un estrecho abrazo.\"},{\"heading\":false,\"text\":\"--Ahora vente conmigo y te enseñaré una praderita donde hay unos pastos con los que te vas a chupar los dedos, pero te encargo que delante de gente no me llames Serapio sino Manteca. Y tú, ¿qué nombre tienes?\"},{\"heading\":false,\"text\":\"--A mí me llaman _Pendenciero_.\"},{\"heading\":false,\"text\":\"--Y lo eres, según me han referido.\"},{\"heading\":false,\"text\":\"--Chico, no es esto revolverme contra lo que ya no tiene remedio; pero encuentro que mi transmigración no es justa.\"},{\"heading\":false,\"text\":\"--Hombre, no le dan a uno a elegir. Yo tampoco merecía esta suerte; pero ¿qué hacer? Hay que conformarse. Después de todo, esto no es tan malo; y si en vez de mostrarte bravucón y gallito haces por aparecer reflexivo y prudente, llegarás a verte como yo, y ya tienes tu vida asegurada.\"},{\"heading\":false,\"text\":\"Y departiendo así, los dos amigos recorrieron la dehesa con gran contentamiento de los pastores, que en aquella unión no veían sino el ascendiente de Manteca, cuya fama de cabestro número uno quedó asegurada para siempre.\"},{\"heading\":false,\"text\":\"Y así transcurrió como medio año, hasta que un domingo del mes de julio...\"},{\"heading\":false,\"text\":\"Pero lo que sigue merece capítulo aparte.\"}]},{\"title\":\"La metempsicosis — capítulo IV\",\"blocks\":[{\"heading\":false,\"text\":\"--¿En dónde estoy? --se decía para sí don Abundio dando vueltas y más vueltas en un pequeño espacio sin luz alguna cuyos límites medía con la cabeza y con la cola--. Vamos a ver, recojamos las ideas --se repetía--. Ayer por la tarde con cinco compañeros más y acompañado de don Serapio y algunos otros cabestros, me metieron en una jaula de madera y me empaquetaron en un vagón del ferrocarril; pero las portezuelas eran tan altas que no pude orientarme en todo el trayecto. Por la noche, que era oscura como boca de lobo, nos desembarcaron a todos juntos; custodiados por zagales, vinimos a un corralón en donde sin pegar los ojos, la hemos pasado tratando inútilmente de explorar el terreno y haciendo comentarios sobre lo que nos ocurría. Esta mañana, obligándome a pasar por un corredor con puertas a los lados, una de las cuales estaba abierta, y con gente por arriba, a quien no he visto, si bien oía su algazara, han empezado a pincharme y a hacer conmigo tales cosas, que me metí no sé por dónde y de repente me encontré encerrado en este cuchitril. Mi primer cuidado fue llamar a gritos a Manteca; pero en lugar de la suya, fueron las cinco voces de mis camaradas las que me contestaron contándome que también ellos se hallaban en idéntica situación. Yo creo sin embargo que esto no ha de durar mucho, porque mis compañeros han ido saliendo por turno, y al pasar por aquí delante decían a los que quedábamos: «¡Una puerta abierta! ¡Sálvese el que pueda!» Y ya no he vuelto a oírlos; lo que me prueba que han logrado evadirse. Hasta ahora van cuatro, de modo que solo gemimos presos el _Carabinero_ y yo.\"},{\"heading\":false,\"text\":\"Así discurría Pendenciero cuando de repente encontróse inundado en luz; la puerta de su mazmorra se había abierto de par en par como movida por un resorte, e inútil es decir que se echó fuera dando brincos de alegría y gritando con toda la fuerza de sus pulmones:\"},{\"heading\":false,\"text\":\"--¡Carabinero, Carabinero! ya me han soltado, estoy libre. ¡Viva la libertad! ¡Viva Riego!\"},{\"heading\":false,\"text\":\"--Acérquese usted por acá --le contestaba el otro-- y ayúdeme usted a derribar esta maldita puerta a ver si podemos escaparnos juntos.\"},{\"heading\":false,\"text\":\"Y don Abundio por una parte y Carabinero por la de dentro, pusieron a prueba sus testuces; pero aquello era más duro que pan de limosna. En esto el liberto sintió un agudo dolor entre las paletillas y notó que le colgaban unas como cintas escaroladas por el lomo.\"},{\"heading\":false,\"text\":\"--¡Brutos! --exclamó con un prolongado bramido.\"},{\"heading\":false,\"text\":\"--¿Qué es eso?\"},{\"heading\":false,\"text\":\"--Una cerbatana que algún mal intencionado acaba de propinarme. ¡Y cómo me pica! Carabinero, compóngaselas usted como pueda que yo no aguanto más. Aquí hay una salida y por ella me escurro. Hasta más ver.\"},{\"heading\":false,\"text\":\"Y colóse en efecto por una como boca de antro que, apenas lo recibió en su seno, cerróse herméticamente dejándolo tan a oscuras como lo estuviera hasta entonces.\"},{\"heading\":false,\"text\":\"--Pues, vaya, que esto es salir de Málaga y entrar en Malagón --decía el pobre don Abundio frotándose contra las paredes tanto para orientarse como para calmar el escozor de la espaldilla.\"},{\"heading\":false,\"text\":\"Aplicó el oído y percibió en confusa mezcla, aplausos, gritos y música hacia la parte exterior. Un rayo de luz, que entraba por un agujero en forma de calabaza, hirió su vista, velada por el dolor y el enojo, y, colocando su cuerpo de modo que la armadura no le molestase, guiñó un ojo y aplicó el abierto al de la cerradura.\"},{\"heading\":false,\"text\":\"--¡Horror! --gritó retrocediendo y alcanzando toda la medida de su situación--. ¡Estoy en una plaza de toros! ¡Soy el quinto; el predilecto de la corrida!...\"},{\"heading\":false,\"text\":\"Y empezó a revolverse con furia loca, embistiendo a todas partes y haciendo ariete de su cabeza con que producir brecha y escapar. Pero fue inútil. Una serie de puyazos dirigidos por una ventanilla que abrieron en el techo del toril, acabaron de hacerle perder el juicio: y, cuando al son de los clarines y timbales giró sobre sus goznes la ferrada puerta, salió a la plaza dispuesto a comerse al que se le pusiera delante.\"},{\"heading\":false,\"text\":\"Del primer arranque despanzurró a dos jamelgos cuyos jinetes quedaron sepultados bajo las cabalgaduras.\"},{\"heading\":false,\"text\":\"--¡Caballos! ¡Caballos! --aullaba el público, o sea la fiera de los tendidos, entusiasmado con aquel prólogo que tan bello porvenir prometía.\"},{\"heading\":false,\"text\":\"La gente de a pie apenas si tenía tiempo de saltar el olivo.\"},{\"heading\":false,\"text\":\"--El toro de la tarde --decían unos.\"},{\"heading\":false,\"text\":\"--El de la temporada --argumentaban otros.\"},{\"heading\":false,\"text\":\"--Sentarse --gritaban los de arriba, poniéndose de pie como los de abajo.\"},{\"heading\":false,\"text\":\"Un picador de los de reserva, que quería contraer méritos para asegurar su contrata, se acercó al ángulo cinco, y echando al aire su sombrero,\"},{\"heading\":false,\"text\":\"--Vaya por ustedes --dijo, y se encaminó sobre su sardina en busca de don Abundio.\"},{\"heading\":false,\"text\":\"--¡Bravo! ¡bravo! --fue el grito general.\"},{\"heading\":false,\"text\":\"Pero apenas se había puesto en suerte cuando caballo y caballero fueron rodando por la arena con gran peligro del segundo que, solo dando vueltas como una perinola, logró escapar de una muerte segura, llevando dos pisotones en la cabeza, un varetazo en el muslo y un susto en todo su cuerpo.\"},{\"heading\":false,\"text\":\"--¿Me haría usted el favor de repetir esa suerte, que estaba distraído y se me ha pasado? --le dijo un chusco; pero como en aquel momento se apercibiera el público de que, con el _marronazo_, el reserva había despaldillado al toro, se armó una de silbidos que ni en un teatro en noche de estreno infeliz.\"},{\"heading\":false,\"text\":\"--¡A la cárcel! --decía la sombra.\"},{\"heading\":false,\"text\":\"--¡Que lo ahorquen! --coreaba el sol, siempre partidario de los recursos extremos.\"},{\"heading\":false,\"text\":\"Y las botellas y los proyectiles andaban por los aires como murciélagos perseguidos, mientras los alguaciles agitando sus penachos y luciendo sus pantorrillas, se llevaban al reserva al palco presidencial e intimaban a los picadores la orden de salir a los medios.\"},{\"heading\":false,\"text\":\"Restablecida la calma y normalizada la corrida, don Abundio empezó a experimentar cansancio, y ya le era preciso traer a la memoria su desesperada suerte para que se decidiera a tomar varas.\"},{\"heading\":false,\"text\":\"Un prolongado punto de clarín despejó de cuadrúpedos el redondel, no sin que el presidente se llevara una silba por no haber dejado al toro dar todo su juego, y don Abundio creyó que todo había concluido. Pero como viese delante a un mozalbete que, con unos palitos en la mano, se entretenía en dar saltos, ya corriendo hacia delante ya hacia atrás:\"},{\"heading\":false,\"text\":\"--Tú vas a pagar por todos --dijo el berrendo, y fuese a él en derechura; pero el chulo, dándole un gracioso quiebro como bolero en _salida_, le dejó clavadas en el morrillo dos banderillas que le hicieron dar un bote y exclamar:\"},{\"heading\":false,\"text\":\"--¡Pobre don Tranquilino! ¡Qué rato pasaría usted!...\"},{\"heading\":false,\"text\":\"Al segundo par sintió no haberse fingido cobarde como le aconsejó don Serapio, cuya condición envidiaba; y al tercero se decidió a vender cara su vida y se _entableró_ pegando la cola a la valla sin que los capotes de los chicos lograran hacerle _arrancar_.\"},{\"heading\":false,\"text\":\"--Ande usted, que nos ha engañado --gritó una voz femenina desde la barrera--. Salió usted más valiente que el Cid y se ha quedado usted más reflexivo que un catedrático de Historia.\"},{\"heading\":false,\"text\":\"Al oír la alusión volvió don Abundio la cabeza y se encontró con una hermosa muchacha, vestida de manola, apoyada sobre la capa de paseo del matador puesta a guisa de colgadura en el antepecho.\"},{\"heading\":false,\"text\":\"--¡Sí, señor!, yo se lo digo a usted --proseguía ella--, la moza de _Pinturita_ que va a mandarle a usted de un volapié a la eternidad, en cuanto el señor presidente acabe de sonarse y pueda hacer seña con el pañuelo.\"},{\"heading\":false,\"text\":\"Don Abundio dio un bramido horroroso. ¿Ustedes creen que de indignación? Nada de eso; es que acababa de reconocer en aquella manola a la alcarreña su criada. El pobre señor ya no tuvo momento de reposo; se fue al centro de la plaza y, tomando carrera, saltó el olivo con tal empuje que a no haber maroma, se cuela en el tendido con ánimo de dar un abrazo a su antigua maritornes. Tres veces repitió la tentativa, y solo a duras penas, y después de haberle clavado un rejón en al anca, se logró que fuera a entablerarse al lado opuesto.\"},{\"heading\":false,\"text\":\"Por fin, tocaron a matar; _Pinturita_ tomó los trastos, y después del correspondiente brindis, se fue solo a la fiera, paró los pies y se puso en facha.\"},{\"heading\":false,\"text\":\"Tres pases al natural y dos de pecho forzados llevaba cumplidos el matador con gran contentamiento del público y absorta extrañeza de Pendenciero que no le quitaba ojo, cuando, liando el trapo y armándose para el volapié, echó atrás la cabeza el diestro y dejóle ver al toro un lunar como una pieza de dos reales que tenía junto a la nuez. Descubrir don Abundio aquel signo y echarse a correr por la plaza todo fue uno.\"},{\"heading\":false,\"text\":\"--¡Está huido! --vociferaban todos silbando al toro como pudieran hacerlo con un actor que no supiera su papel.\"},{\"heading\":false,\"text\":\"Y sin embargo, el pobre cornúpeto llevaba la razón en su fuga; quería evitar una horrorosa catástrofe. Había reconocido en Pinturita a su ahijado León.\"},{\"heading\":false,\"text\":\"En vano fue que este cambiara de muleta y apelara a todos los recursos para traer al toro a jurisdicción; don Abundio, transido de pena, esquivaba la lucha. Lo que pasó por su pupilo, nadie lo sabe. ¿Temía el fiasco? ¿Recordaba lo que sobre la metempsicosis le había repetido tantas veces su tutor y, compulsando fechas, abrigaba algún temor sobre el caso presente? Lo ignoro; lo cierto es que se puso pálido, y volviendo a la barrera depositó trapo y estoque y se sentó en el estribo diciendo que él no podía hacer más.\"},{\"heading\":false,\"text\":\"--¡Perros! ¡perros! --gritó el público; porque se me olvidaba decir a ustedes que esto pasaba antes de que la media-luna se hubiera introducido en la lidia.\"},{\"heading\":false,\"text\":\"Y, en efecto, la traílla salió a la arena con gran contentamiento de don Abundio que, no hallando motivos de consideración para los canes, los fue despanzurrando por turno después de llevarlos y traerlos como pelota en trinquete. La única que se le resistía era una perra con cara de patrona de casa de huéspedes sin principio, que siempre encontraba modo de escabullírsele entre las patas.\"},{\"heading\":false,\"text\":\"--También llevarás tu merecido --murmuró el catedrático dando un derrote al aire.\"},{\"heading\":false,\"text\":\"--¿Yo? --le contestó la perra soltando una de esas carcajadas más insultantes que un bofetón--. ¡Si no ha podido conmigo mi marido! Caro va usted a pagar el haberme puesto en el caso de ir a acabar mis días en Toro con Serapio.\"},{\"heading\":false,\"text\":\"--¡Remigia! --pues la mastina no era otra-- argüía Pendenciero falto de fuerzas para resistir a tanta tribulación. Mira que yo no soy manso, y si me buscas camorra la encontrarás.\"},{\"heading\":false,\"text\":\"--Calle usted la boca, teniente de papel. Ni a usted ni a todo Jarama junto temo yo. Y el toro que sea hombre, que salga.\"},{\"heading\":false,\"text\":\"Y daba brincos procurando hincar el diente donde podía; hasta que convencida de la inutilidad de sus esfuerzos y oyendo al tendido pedir a voz en cuello que se llevaran al toro al corral, porque la noche se venía encima, se dirigió resueltamente a donde León estaba, y ladrando y enseñándole los dientes, le increpó de esta manera:\"},{\"heading\":false,\"text\":\"--Lo mismo que tú, torero de invierno, ¿así vuelves por la honra de tu familia? ¿Por qué no le diste un golletazo? ¡Si me voy convenciendo de que eres hijo de tu padre!...\"},{\"heading\":false,\"text\":\"León no entendía; pero no quitaba los ojos de la perra y meditaba.\"},{\"heading\":false,\"text\":\"Por fin soltaron a los cabestros y, en cuanto doña Remigia reconoció a su marido, se le abalanzó a una oreja diciéndole con transportes de fingido gozo:\"},{\"heading\":false,\"text\":\"--¡Serapito mío! Esta vez sí que no nos separaremos; yo quiero ir a donde tu vayas. Mira, aquí tienes a Leoncito que se hará pastor, y reunidos pasaremos la existencia. Hasta si tú quieres consentiré en que nos acompañe don Abundio.\"},{\"heading\":false,\"text\":\"Y don Serapio, inmóvil, conmovido y con la cabeza inclinada por el peso de su esposa, cuyas virtudes admiraba, quiso hablar, pero solo tuvo fuerzas para decir: _Muuu_...\"},{\"heading\":false,\"text\":\"Todo parecía augurar un feliz desenlace, cuando uno de los pastores, creyendo por la actitud de Manteca que la perra le martirizaba en vez de acariciarle, tomando por odio de raza lo que era expansión de familia, llegó con el garrote enarbolado a donde los cónyuges estaban, y descargó con él tan tremendo como infortunado golpe sobre la cabeza de doña Remigia, que esta, dando media vuelta, cayó exánime a los pies de su marido.\"},{\"heading\":false,\"text\":\"--¡Pobrecita! ¡tan buena! --murmuró Serapio.\"},{\"heading\":false,\"text\":\"Y, dirigiéndose a donde el catedrático estaba:\"},{\"heading\":false,\"text\":\"--La hemos perdido --exclamó--. ¡Valor, amigo!\"},{\"heading\":false,\"text\":\"Y ambos tomaron el camino del toril, lanzando al pasar junto a León una mirada y un mugido que conmovieron al émulo de Costillares. Pero al llegar a la puerta, don Abundio dobló las rodillas y, sin proferir una queja, quedó muerto de repente.\"},{\"heading\":false,\"text\":\"En las reseñas de los periódicos dijeron que le había ocasionado la muerte la despaldilladura del reserva. ¡Así se escribe la Historia! En el matadero se vio que tenía el corazón deshecho. Había muerto de un aneurisma.\"},{\"heading\":false,\"text\":\"Don Serapio siguió llevando el cencerro y acabó por olvidar y ser feliz.\"},{\"heading\":false,\"text\":\"Lo que pasó por León nadie lo sabe; pero es lo cierto que al día siguiente se cortó la coleta con asombro de sus admiradores; se volvió misántropo y concluyó por fundar en Madrid la primera sociedad protectora de los animales.\"},{\"heading\":false,\"text\":\"En cuanto a la alcarreña, continuó sirviendo.\"},{\"heading\":false,\"text\":\"FIN\"},{\"heading\":false,\"text\":\"ÍNDICE\"},{\"heading\":false,\"text\":\"PÁGINAS\"},{\"heading\":false,\"text\":\"EL ANACRONÓPETE                                                     7\"},{\"heading\":false,\"text\":\"Capítulo primero. En el que se prueba que ADELANTE no es la divisa del progreso.                                            7\"},{\"heading\":false,\"text\":\"Capítulo II. Una conferencia al alcance de todos.                15\"},{\"heading\":false,\"text\":\"Capítulo III. Teoría del tiempo: cómo se forma: cómo se descompone.                                                    22\"},{\"heading\":false,\"text\":\"Capítulo IV. En el que se tratan asuntos de familia.             33\"},{\"heading\":false,\"text\":\"Capítulo V. Cupido y Marte.                                      47\"},{\"heading\":false,\"text\":\"Capítulo VI. El vehículo considerado como escuela de moral.      56\"},{\"heading\":false,\"text\":\"Capítulo VII. ¡Marchen!                                          64\"},{\"heading\":false,\"text\":\"Capítulo VIII. Efectos retroactivos.                             71\"},{\"heading\":false,\"text\":\"Capítulo IX. Reducción gradual del ejército hasta su supresión definitiva.                                                    82\"},{\"heading\":false,\"text\":\"Capítulo X. En que tiene lugar un incidente que parece insignificante y es, sin embargo, de mucha importancia.        96\"},{\"heading\":false,\"text\":\"Capítulo XI. Un poco de erudición fastidiosa aunque necesaria.  105\"},{\"heading\":false,\"text\":\"Capítulo XII. Cuarenta y ocho horas en el Celeste Imperio.      114\"},{\"heading\":false,\"text\":\"Capítulo XIII. La Europa del siglo XIX ante la China del siglo III.                                                    125\"},{\"heading\":false,\"text\":\"Capítulo XIV. Un huésped inesperado.                            135\"},{\"heading\":false,\"text\":\"Capítulo XV. La resurrección de los muertos antes del Juicio final.                                                        144\"},{\"heading\":false,\"text\":\"Capítulo XVI. En que todo se explica complicándose todo.        155\"},{\"heading\":false,\"text\":\"Capítulo XVII. Panem et circenses.                              167\"},{\"heading\":false,\"text\":\"Capítulo XVIII. «Sic transit gloria mundi»                      186\"},{\"heading\":false,\"text\":\"Capítulo XIX. Los náufragos del aire.                           197\"},{\"heading\":false,\"text\":\"Capítulo XX. El mejor, no porque sea el más bueno, sino por ser el último.                                                207\"},{\"heading\":false,\"text\":\"VIAJE A CHINA -- Cartas al director de «Las Provincias»           219\"},{\"heading\":false,\"text\":\"Macao, 26 de septiembre de 1878.                                221\"},{\"heading\":false,\"text\":\"Macao, 8 de octubre de 1878.                                    227\"},{\"heading\":false,\"text\":\"Macao, 14 de marzo de 1879.                                     240\"},{\"heading\":false,\"text\":\"Macao, 19 de abril de 1879.                                     256\"},{\"heading\":false,\"text\":\"Macao, 30 de abril de 1879.                                     269\"},{\"heading\":false,\"text\":\"Macao, 18 de noviembre de 1879.                                 283\"},{\"heading\":false,\"text\":\"Macao, 26 de marzo de 1880.                                     293\"},{\"heading\":false,\"text\":\"Macao, 30 de enero de 1881.                                     305\"},{\"heading\":false,\"text\":\"Fiestas de Hon-Kung en Macao. Macao, 26 de septiembre de 1881.  316\"},{\"heading\":false,\"text\":\"Los chinos dentro de casa. Macao, 10 de marzo de 1882.          324\"},{\"heading\":false,\"text\":\"Cantón I. Macao, 8 de diciembre de 1882.                        335\"},{\"heading\":false,\"text\":\"Cantón II.                                                      342\"},{\"heading\":false,\"text\":\"Cantón III.                                                     349\"},{\"heading\":false,\"text\":\"Cantón IV.                                                      356\"},{\"heading\":false,\"text\":\"LA METEMPISCOSIS                                                  363\"},{\"heading\":false,\"text\":\"I.                                                              365\"},{\"heading\":false,\"text\":\"II.                                                             371\"},{\"heading\":false,\"text\":\"III.                                                            379\"},{\"heading\":false,\"text\":\"IV.                                                             386\"},{\"heading\":false,\"text\":\"ÍNDICE                                                            395\"}]}]', 'es', 'https://www.gutenberg.org/ebooks/62359', '{}');
INSERT INTO libros (id, titulo, autor, genero, cover, secciones, idioma, fuente, introducciones) VALUES (64317, 'El gran Gatsby', 'F. Scott Fitzgerald', 'novela', 'https://covers.openlibrary.org/b/isbn/9780743273565-L.jpg', '[{\"title\":\"Introducción\",\"blocks\":[{\"heading\":true,\"text\":\"The Great GatsbybyF. Scott Fitzgerald\"},{\"heading\":false,\"text\":\"Once again\\nto\\nZelda\"},{\"heading\":false,\"text\":\"Then wear the gold hat, if that will move her;\\n\\nIf you can bounce high, bounce for her too,\\n\\nTill she cry “Lover, gold-hatted, high-bouncing lover,\\n\\nI must have you!”\"},{\"heading\":false,\"text\":\"Thomas Parke d’Invilliers\"}]},{\"title\":\"I\",\"blocks\":[{\"heading\":false,\"text\":\"In my younger and more vulnerable years my father gave me some advice that I’ve been turning over in my mind ever since.\"},{\"heading\":false,\"text\":\"“Whenever you feel like criticizing anyone,” he told me, “just remember that all the people in this world haven’t had the advantages that you’ve had.”\"},{\"heading\":false,\"text\":\"He didn’t say any more, but we’ve always been unusually communicative in a reserved way, and I understood that he meant a great deal more than that. In consequence, I’m inclined to reserve all judgements, a habit that has opened up many curious natures to me and also made me the victim of not a few veteran bores. The abnormal mind is quick to detect and attach itself to this quality when it appears in a normal person, and so it came about that in college I was unjustly accused of being a politician, because I was privy to the secret griefs of wild, unknown men. Most of the confidences were unsought—frequently I have feigned sleep, preoccupation, or a hostile levity when I realized by some unmistakable sign that an intimate revelation was quivering on the horizon; for the intimate revelations of young men, or at least the terms in which they express them, are usually plagiaristic and marred by obvious suppressions. Reserving judgements is a matter of infinite hope. I am still a little afraid of missing something if I forget that, as my father snobbishly suggested, and I snobbishly repeat, a sense of the fundamental decencies is parcelled out unequally at birth.\"},{\"heading\":false,\"text\":\"And, after boasting this way of my tolerance, I come to the admission that it has a limit. Conduct may be founded on the hard rock or the wet marshes, but after a certain point I don’t care what it’s founded on. When I came back from the East last autumn I felt that I wanted the world to be in uniform and at a sort of moral attention forever; I wanted no more riotous excursions with privileged glimpses into the human heart. Only Gatsby, the man who gives his name to this book, was exempt from my reaction—Gatsby, who represented everything for which I have an unaffected scorn. If personality is an unbroken series of successful gestures, then there was something gorgeous about him, some heightened sensitivity to the promises of life, as if he were related to one of those intricate machines that register earthquakes ten thousand miles away. This responsiveness had nothing to do with that flabby impressionability which is dignified under the name of the “creative temperament”—it was an extraordinary gift for hope, a romantic readiness such as I have never found in any other person and which it is not likely I shall ever find again. No—Gatsby turned out all right at the end; it is what preyed on Gatsby, what foul dust floated in the wake of his dreams that temporarily closed out my interest in the abortive sorrows and short-winded elations of men.\"},{\"heading\":false,\"text\":\"My family have been prominent, well-to-do people in this Middle Western city for three generations. The Carraways are something of a clan, and we have a tradition that we’re descended from the Dukes of Buccleuch, but the actual founder of my line was my grandfather’s brother, who came here in fifty-one, sent a substitute to the Civil War, and started the wholesale hardware business that my father carries on today.\"},{\"heading\":false,\"text\":\"I never saw this great-uncle, but I’m supposed to look like him—with special reference to the rather hard-boiled painting that hangs in father’s office. I graduated from New Haven in 1915, just a quarter of a century after my father, and a little later I participated in that delayed Teutonic migration known as the Great War. I enjoyed the counter-raid so thoroughly that I came back restless. Instead of being the warm centre of the world, the Middle West now seemed like the ragged edge of the universe—so I decided to go East and learn the bond business. Everybody I knew was in the bond business, so I supposed it could support one more single man. All my aunts and uncles talked it over as if they were choosing a prep school for me, and finally said, “Why—ye-es,” with very grave, hesitant faces. Father agreed to finance me for a year, and after various delays I came East, permanently, I thought, in the spring of twenty-two.\"},{\"heading\":false,\"text\":\"The practical thing was to find rooms in the city, but it was a warm season, and I had just left a country of wide lawns and friendly trees, so when a young man at the office suggested that we take a house together in a commuting town, it sounded like a great idea. He found the house, a weather-beaten cardboard bungalow at eighty a month, but at the last minute the firm ordered him to Washington, and I went out to the country alone. I had a dog—at least I had him for a few days until he ran away—and an old Dodge and a Finnish woman, who made my bed and cooked breakfast and muttered Finnish wisdom to herself over the electric stove.\"},{\"heading\":false,\"text\":\"It was lonely for a day or so until one morning some man, more recently arrived than I, stopped me on the road.\"},{\"heading\":false,\"text\":\"“How do you get to West Egg village?” he asked helplessly.\"},{\"heading\":false,\"text\":\"I told him. And as I walked on I was lonely no longer. I was a guide, a pathfinder, an original settler. He had casually conferred on me the freedom of the neighbourhood.\"},{\"heading\":false,\"text\":\"And so with the sunshine and the great bursts of leaves growing on the trees, just as things grow in fast movies, I had that familiar conviction that life was beginning over again with the summer.\"},{\"heading\":false,\"text\":\"There was so much to read, for one thing, and so much fine health to be pulled down out of the young breath-giving air. I bought a dozen volumes on banking and credit and investment securities, and they stood on my shelf in red and gold like new money from the mint, promising to unfold the shining secrets that only Midas and Morgan and Maecenas knew. And I had the high intention of reading many other books besides. I was rather literary in college—one year I wrote a series of very solemn and obvious editorials for the Yale News—and now I was going to bring back all such things into my life and become again that most limited of all specialists, the “well-rounded man.” This isn’t just an epigram—life is much more successfully looked at from a single window, after all.\"},{\"heading\":false,\"text\":\"It was a matter of chance that I should have rented a house in one of the strangest communities in North America. It was on that slender riotous island which extends itself due east of New York—and where there are, among other natural curiosities, two unusual formations of land. Twenty miles from the city a pair of enormous eggs, identical in contour and separated only by a courtesy bay, jut out into the most domesticated body of salt water in the Western hemisphere, the great wet barnyard of Long Island Sound. They are not perfect ovals—like the egg in the Columbus story, they are both crushed flat at the contact end—but their physical resemblance must be a source of perpetual wonder to the gulls that fly overhead. To the wingless a more interesting phenomenon is their dissimilarity in every particular except shape and size.\"},{\"heading\":false,\"text\":\"I lived at West Egg, the—well, the less fashionable of the two, though this is a most superficial tag to express the bizarre and not a little sinister contrast between them. My house was at the very tip of the egg, only fifty yards from the Sound, and squeezed between two huge places that rented for twelve or fifteen thousand a season. The one on my right was a colossal affair by any standard—it was a factual imitation of some Hôtel de Ville in Normandy, with a tower on one side, spanking new under a thin beard of raw ivy, and a marble swimming pool, and more than forty acres of lawn and garden. It was Gatsby’s mansion. Or, rather, as I didn’t know Mr. Gatsby, it was a mansion inhabited by a gentleman of that name. My own house was an eyesore, but it was a small eyesore, and it had been overlooked, so I had a view of the water, a partial view of my neighbour’s lawn, and the consoling proximity of millionaires—all for eighty dollars a month.\"},{\"heading\":false,\"text\":\"Across the courtesy bay the white palaces of fashionable East Egg glittered along the water, and the history of the summer really begins on the evening I drove over there to have dinner with the Tom Buchanans. Daisy was my second cousin once removed, and I’d known Tom in college. And just after the war I spent two days with them in Chicago.\"},{\"heading\":false,\"text\":\"Her husband, among various physical accomplishments, had been one of the most powerful ends that ever played football at New Haven—a national figure in a way, one of those men who reach such an acute limited excellence at twenty-one that everything afterward savours of anticlimax. His family were enormously wealthy—even in college his freedom with money was a matter for reproach—but now he’d left Chicago and come East in a fashion that rather took your breath away: for instance, he’d brought down a string of polo ponies from Lake Forest. It was hard to realize that a man in my own generation was wealthy enough to do that.\"},{\"heading\":false,\"text\":\"Why they came East I don’t know. They had spent a year in France for no particular reason, and then drifted here and there unrestfully wherever people played polo and were rich together. This was a permanent move, said Daisy over the telephone, but I didn’t believe it—I had no sight into Daisy’s heart, but I felt that Tom would drift on forever seeking, a little wistfully, for the dramatic turbulence of some irrecoverable football game.\"},{\"heading\":false,\"text\":\"And so it happened that on a warm windy evening I drove over to East Egg to see two old friends whom I scarcely knew at all. Their house was even more elaborate than I expected, a cheerful red-and-white Georgian Colonial mansion, overlooking the bay. The lawn started at the beach and ran towards the front door for a quarter of a mile, jumping over sundials and brick walks and burning gardens—finally when it reached the house drifting up the side in bright vines as though from the momentum of its run. The front was broken by a line of French windows, glowing now with reflected gold and wide open to the warm windy afternoon, and Tom Buchanan in riding clothes was standing with his legs apart on the front porch.\"},{\"heading\":false,\"text\":\"He had changed since his New Haven years. Now he was a sturdy straw-haired man of thirty, with a rather hard mouth and a supercilious manner. Two shining arrogant eyes had established dominance over his face and gave him the appearance of always leaning aggressively forward. Not even the effeminate swank of his riding clothes could hide the enormous power of that body—he seemed to fill those glistening boots until he strained the top lacing, and you could see a great pack of muscle shifting when his shoulder moved under his thin coat. It was a body capable of enormous leverage—a cruel body.\"},{\"heading\":false,\"text\":\"His speaking voice, a gruff husky tenor, added to the impression of fractiousness he conveyed. There was a touch of paternal contempt in it, even toward people he liked—and there were men at New Haven who had hated his guts.\"},{\"heading\":false,\"text\":\"“Now, don’t think my opinion on these matters is final,” he seemed to say, “just because I’m stronger and more of a man than you are.” We were in the same senior society, and while we were never intimate I always had the impression that he approved of me and wanted me to like him with some harsh, defiant wistfulness of his own.\"},{\"heading\":false,\"text\":\"We talked for a few minutes on the sunny porch.\"},{\"heading\":false,\"text\":\"“I’ve got a nice place here,” he said, his eyes flashing about restlessly.\"},{\"heading\":false,\"text\":\"Turning me around by one arm, he moved a broad flat hand along the front vista, including in its sweep a sunken Italian garden, a half acre of deep, pungent roses, and a snub-nosed motorboat that bumped the tide offshore.\"},{\"heading\":false,\"text\":\"“It belonged to Demaine, the oil man.” He turned me around again, politely and abruptly. “We’ll go inside.”\"},{\"heading\":false,\"text\":\"We walked through a high hallway into a bright rosy-coloured space, fragilely bound into the house by French windows at either end. The windows were ajar and gleaming white against the fresh grass outside that seemed to grow a little way into the house. A breeze blew through the room, blew curtains in at one end and out the other like pale flags, twisting them up toward the frosted wedding-cake of the ceiling, and then rippled over the wine-coloured rug, making a shadow on it as wind does on the sea.\"},{\"heading\":false,\"text\":\"The only completely stationary object in the room was an enormous couch on which two young women were buoyed up as though upon an anchored balloon. They were both in white, and their dresses were rippling and fluttering as if they had just been blown back in after a short flight around the house. I must have stood for a few moments listening to the whip and snap of the curtains and the groan of a picture on the wall. Then there was a boom as Tom Buchanan shut the rear windows and the caught wind died out about the room, and the curtains and the rugs and the two young women ballooned slowly to the floor.\"},{\"heading\":false,\"text\":\"The younger of the two was a stranger to me. She was extended full length at her end of the divan, completely motionless, and with her chin raised a little, as if she were balancing something on it which was quite likely to fall. If she saw me out of the corner of her eyes she gave no hint of it—indeed, I was almost surprised into murmuring an apology for having disturbed her by coming in.\"},{\"heading\":false,\"text\":\"The other girl, Daisy, made an attempt to rise—she leaned slightly forward with a conscientious expression—then she laughed, an absurd, charming little laugh, and I laughed too and came forward into the room.\"},{\"heading\":false,\"text\":\"“I’m p-paralysed with happiness.”\"},{\"heading\":false,\"text\":\"She laughed again, as if she said something very witty, and held my hand for a moment, looking up into my face, promising that there was no one in the world she so much wanted to see. That was a way she had. She hinted in a murmur that the surname of the balancing girl was Baker. (I’ve heard it said that Daisy’s murmur was only to make people lean toward her; an irrelevant criticism that made it no less charming.)\"},{\"heading\":false,\"text\":\"At any rate, Miss Baker’s lips fluttered, she nodded at me almost imperceptibly, and then quickly tipped her head back again—the object she was balancing had obviously tottered a little and given her something of a fright. Again a sort of apology arose to my lips. Almost any exhibition of complete self-sufficiency draws a stunned tribute from me.\"},{\"heading\":false,\"text\":\"I looked back at my cousin, who began to ask me questions in her low, thrilling voice. It was the kind of voice that the ear follows up and down, as if each speech is an arrangement of notes that will never be played again. Her face was sad and lovely with bright things in it, bright eyes and a bright passionate mouth, but there was an excitement in her voice that men who had cared for her found difficult to forget: a singing compulsion, a whispered “Listen,” a promise that she had done gay, exciting things just a while since and that there were gay, exciting things hovering in the next hour.\"},{\"heading\":false,\"text\":\"I told her how I had stopped off in Chicago for a day on my way East, and how a dozen people had sent their love through me.\"},{\"heading\":false,\"text\":\"“Do they miss me?” she cried ecstatically.\"},{\"heading\":false,\"text\":\"“The whole town is desolate. All the cars have the left rear wheel painted black as a mourning wreath, and there’s a persistent wail all night along the north shore.”\"},{\"heading\":false,\"text\":\"“How gorgeous! Let’s go back, Tom. Tomorrow!” Then she added irrelevantly: “You ought to see the baby.”\"},{\"heading\":false,\"text\":\"“I’d like to.”\"},{\"heading\":false,\"text\":\"“She’s asleep. She’s three years old. Haven’t you ever seen her?”\"},{\"heading\":false,\"text\":\"“Never.”\"},{\"heading\":false,\"text\":\"“Well, you ought to see her. She’s—”\"},{\"heading\":false,\"text\":\"Tom Buchanan, who had been hovering restlessly about the room, stopped and rested his hand on my shoulder.\"},{\"heading\":false,\"text\":\"“What you doing, Nick?”\"},{\"heading\":false,\"text\":\"“I’m a bond man.”\"},{\"heading\":false,\"text\":\"“Who with?”\"},{\"heading\":false,\"text\":\"I told him.\"},{\"heading\":false,\"text\":\"“Never heard of them,” he remarked decisively.\"},{\"heading\":false,\"text\":\"This annoyed me.\"},{\"heading\":false,\"text\":\"“You will,” I answered shortly. “You will if you stay in the East.”\"},{\"heading\":false,\"text\":\"“Oh, I’ll stay in the East, don’t you worry,” he said, glancing at Daisy and then back at me, as if he were alert for something more. “I’d be a God damned fool to live anywhere else.”\"},{\"heading\":false,\"text\":\"At this point Miss Baker said: “Absolutely!” with such suddenness that I started—it was the first word she had uttered since I came into the room. Evidently it surprised her as much as it did me, for she yawned and with a series of rapid, deft movements stood up into the room.\"},{\"heading\":false,\"text\":\"“I’m stiff,” she complained, “I’ve been lying on that sofa for as long as I can remember.”\"},{\"heading\":false,\"text\":\"“Don’t look at me,” Daisy retorted, “I’ve been trying to get you to New York all afternoon.”\"},{\"heading\":false,\"text\":\"“No, thanks,” said Miss Baker to the four cocktails just in from the pantry. “I’m absolutely in training.”\"},{\"heading\":false,\"text\":\"Her host looked at her incredulously.\"},{\"heading\":false,\"text\":\"“You are!” He took down his drink as if it were a drop in the bottom of a glass. “How you ever get anything done is beyond me.”\"},{\"heading\":false,\"text\":\"I looked at Miss Baker, wondering what it was she “got done.” I enjoyed looking at her. She was a slender, small-breasted girl, with an erect carriage, which she accentuated by throwing her body backward at the shoulders like a young cadet. Her grey sun-strained eyes looked back at me with polite reciprocal curiosity out of a wan, charming, discontented face. It occurred to me now that I had seen her, or a picture of her, somewhere before.\"},{\"heading\":false,\"text\":\"“You live in West Egg,” she remarked contemptuously. “I know somebody there.”\"},{\"heading\":false,\"text\":\"“I don’t know a single—”\"},{\"heading\":false,\"text\":\"“You must know Gatsby.”\"},{\"heading\":false,\"text\":\"“Gatsby?” demanded Daisy. “What Gatsby?”\"},{\"heading\":false,\"text\":\"Before I could reply that he was my neighbour dinner was announced; wedging his tense arm imperatively under mine, Tom Buchanan compelled me from the room as though he were moving a checker to another square.\"},{\"heading\":false,\"text\":\"Slenderly, languidly, their hands set lightly on their hips, the two young women preceded us out on to a rosy-coloured porch, open toward the sunset, where four candles flickered on the table in the diminished wind.\"},{\"heading\":false,\"text\":\"“Why candles?” objected Daisy, frowning. She snapped them out with her fingers. “In two weeks it’ll be the longest day in the year.” She looked at us all radiantly. “Do you always watch for the longest day of the year and then miss it? I always watch for the longest day in the year and then miss it.”\"},{\"heading\":false,\"text\":\"“We ought to plan something,” yawned Miss Baker, sitting down at the table as if she were getting into bed.\"},{\"heading\":false,\"text\":\"“All right,” said Daisy. “What’ll we plan?” She turned to me helplessly: “What do people plan?”\"},{\"heading\":false,\"text\":\"Before I could answer her eyes fastened with an awed expression on her little finger.\"},{\"heading\":false,\"text\":\"“Look!” she complained; “I hurt it.”\"},{\"heading\":false,\"text\":\"We all looked—the knuckle was black and blue.\"},{\"heading\":false,\"text\":\"“You did it, Tom,” she said accusingly. “I know you didn’t mean to, but you did do it. That’s what I get for marrying a brute of a man, a great, big, hulking physical specimen of a—”\"},{\"heading\":false,\"text\":\"“I hate that word ‘hulking,’ ” objected Tom crossly, “even in kidding.”\"},{\"heading\":false,\"text\":\"“Hulking,” insisted Daisy.\"},{\"heading\":false,\"text\":\"Sometimes she and Miss Baker talked at once, unobtrusively and with a bantering inconsequence that was never quite chatter, that was as cool as their white dresses and their impersonal eyes in the absence of all desire. They were here, and they accepted Tom and me, making only a polite pleasant effort to entertain or to be entertained. They knew that presently dinner would be over and a little later the evening too would be over and casually put away. It was sharply different from the West, where an evening was hurried from phase to phase towards its close, in a continually disappointed anticipation or else in sheer nervous dread of the moment itself.\"},{\"heading\":false,\"text\":\"“You make me feel uncivilized, Daisy,” I confessed on my second glass of corky but rather impressive claret. “Can’t you talk about crops or something?”\"},{\"heading\":false,\"text\":\"I meant nothing in particular by this remark, but it was taken up in an unexpected way.\"},{\"heading\":false,\"text\":\"“Civilization’s going to pieces,” broke out Tom violently. “I’ve gotten to be a terrible pessimist about things. Have you read The Rise of the Coloured Empires by this man Goddard?”\"},{\"heading\":false,\"text\":\"“Why, no,” I answered, rather surprised by his tone.\"},{\"heading\":false,\"text\":\"“Well, it’s a fine book, and everybody ought to read it. The idea is if we don’t look out the white race will be—will be utterly submerged. It’s all scientific stuff; it’s been proved.”\"},{\"heading\":false,\"text\":\"“Tom’s getting very profound,” said Daisy, with an expression of unthoughtful sadness. “He reads deep books with long words in them. What was that word we—”\"},{\"heading\":false,\"text\":\"“Well, these books are all scientific,” insisted Tom, glancing at her impatiently. “This fellow has worked out the whole thing. It’s up to us, who are the dominant race, to watch out or these other races will have control of things.”\"},{\"heading\":false,\"text\":\"“We’ve got to beat them down,” whispered Daisy, winking ferociously toward the fervent sun.\"},{\"heading\":false,\"text\":\"“You ought to live in California—” began Miss Baker, but Tom interrupted her by shifting heavily in his chair.\"},{\"heading\":false,\"text\":\"“This idea is that we’re Nordics. I am, and you are, and you are, and—” After an infinitesimal hesitation he included Daisy with a slight nod, and she winked at me again. “—And we’ve produced all the things that go to make civilization—oh, science and art, and all that. Do you see?”\"},{\"heading\":false,\"text\":\"There was something pathetic in his concentration, as if his complacency, more acute than of old, was not enough to him any more. When, almost immediately, the telephone rang inside and the butler left the porch Daisy seized upon the momentary interruption and leaned towards me.\"},{\"heading\":false,\"text\":\"“I’ll tell you a family secret,” she whispered enthusiastically. “It’s about the butler’s nose. Do you want to hear about the butler’s nose?”\"},{\"heading\":false,\"text\":\"“That’s why I came over tonight.”\"},{\"heading\":false,\"text\":\"“Well, he wasn’t always a butler; he used to be the silver polisher for some people in New York that had a silver service for two hundred people. He had to polish it from morning till night, until finally it began to affect his nose—”\"},{\"heading\":false,\"text\":\"“Things went from bad to worse,” suggested Miss Baker.\"},{\"heading\":false,\"text\":\"“Yes. Things went from bad to worse, until finally he had to give up his position.”\"},{\"heading\":false,\"text\":\"For a moment the last sunshine fell with romantic affection upon her glowing face; her voice compelled me forward breathlessly as I listened—then the glow faded, each light deserting her with lingering regret, like children leaving a pleasant street at dusk.\"},{\"heading\":false,\"text\":\"The butler came back and murmured something close to Tom’s ear, whereupon Tom frowned, pushed back his chair, and without a word went inside. As if his absence quickened something within her, Daisy leaned forward again, her voice glowing and singing.\"},{\"heading\":false,\"text\":\"“I love to see you at my table, Nick. You remind me of a—of a rose, an absolute rose. Doesn’t he?” She turned to Miss Baker for confirmation: “An absolute rose?”\"},{\"heading\":false,\"text\":\"This was untrue. I am not even faintly like a rose. She was only extemporizing, but a stirring warmth flowed from her, as if her heart was trying to come out to you concealed in one of those breathless, thrilling words. Then suddenly she threw her napkin on the table and excused herself and went into the house.\"},{\"heading\":false,\"text\":\"Miss Baker and I exchanged a short glance consciously devoid of meaning. I was about to speak when she sat up alertly and said “Sh!” in a warning voice. A subdued impassioned murmur was audible in the room beyond, and Miss Baker leaned forward unashamed, trying to hear. The murmur trembled on the verge of coherence, sank down, mounted excitedly, and then ceased altogether.\"},{\"heading\":false,\"text\":\"“This Mr. Gatsby you spoke of is my neighbour—” I began.\"},{\"heading\":false,\"text\":\"“Don’t talk. I want to hear what happens.”\"},{\"heading\":false,\"text\":\"“Is something happening?” I inquired innocently.\"},{\"heading\":false,\"text\":\"“You mean to say you don’t know?” said Miss Baker, honestly surprised. “I thought everybody knew.”\"},{\"heading\":false,\"text\":\"“I don’t.”\"},{\"heading\":false,\"text\":\"“Why—” she said hesitantly. “Tom’s got some woman in New York.”\"},{\"heading\":false,\"text\":\"“Got some woman?” I repeated blankly.\"},{\"heading\":false,\"text\":\"Miss Baker nodded.\"},{\"heading\":false,\"text\":\"“She might have the decency not to telephone him at dinner time. Don’t you think?”\"},{\"heading\":false,\"text\":\"Almost before I had grasped her meaning there was the flutter of a dress and the crunch of leather boots, and Tom and Daisy were back at the table.\"},{\"heading\":false,\"text\":\"“It couldn’t be helped!” cried Daisy with tense gaiety.\"},{\"heading\":false,\"text\":\"She sat down, glanced searchingly at Miss Baker and then at me, and continued: “I looked outdoors for a minute, and it’s very romantic outdoors. There’s a bird on the lawn that I think must be a nightingale come over on the Cunard or White Star Line. He’s singing away—” Her voice sang: “It’s romantic, isn’t it, Tom?”\"},{\"heading\":false,\"text\":\"“Very romantic,” he said, and then miserably to me: “If it’s light enough after dinner, I want to take you down to the stables.”\"},{\"heading\":false,\"text\":\"The telephone rang inside, startlingly, and as Daisy shook her head decisively at Tom the subject of the stables, in fact all subjects, vanished into air. Among the broken fragments of the last five minutes at table I remember the candles being lit again, pointlessly, and I was conscious of wanting to look squarely at everyone, and yet to avoid all eyes. I couldn’t guess what Daisy and Tom were thinking, but I doubt if even Miss Baker, who seemed to have mastered a certain hardy scepticism, was able utterly to put this fifth guest’s shrill metallic urgency out of mind. To a certain temperament the situation might have seemed intriguing—my own instinct was to telephone immediately for the police.\"},{\"heading\":false,\"text\":\"The horses, needless to say, were not mentioned again. Tom and Miss Baker, with several feet of twilight between them, strolled back into the library, as if to a vigil beside a perfectly tangible body, while, trying to look pleasantly interested and a little deaf, I followed Daisy around a chain of connecting verandas to the porch in front. In its deep gloom we sat down side by side on a wicker settee.\"},{\"heading\":false,\"text\":\"Daisy took her face in her hands as if feeling its lovely shape, and her eyes moved gradually out into the velvet dusk. I saw that turbulent emotions possessed her, so I asked what I thought would be some sedative questions about her little girl.\"},{\"heading\":false,\"text\":\"“We don’t know each other very well, Nick,” she said suddenly. “Even if we are cousins. You didn’t come to my wedding.”\"},{\"heading\":false,\"text\":\"“I wasn’t back from the war.”\"},{\"heading\":false,\"text\":\"“That’s true.” She hesitated. “Well, I’ve had a very bad time, Nick, and I’m pretty cynical about everything.”\"},{\"heading\":false,\"text\":\"Evidently she had reason to be. I waited but she didn’t say any more, and after a moment I returned rather feebly to the subject of her daughter.\"},{\"heading\":false,\"text\":\"“I suppose she talks, and—eats, and everything.”\"},{\"heading\":false,\"text\":\"“Oh, yes.” She looked at me absently. “Listen, Nick; let me tell you what I said when she was born. Would you like to hear?”\"},{\"heading\":false,\"text\":\"“Very much.”\"},{\"heading\":false,\"text\":\"“It’ll show you how I’ve gotten to feel about—things. Well, she was less than an hour old and Tom was God knows where. I woke up out of the ether with an utterly abandoned feeling, and asked the nurse right away if it was a boy or a girl. She told me it was a girl, and so I turned my head away and wept. ‘All right,’ I said, ‘I’m glad it’s a girl. And I hope she’ll be a fool—that’s the best thing a girl can be in this world, a beautiful little fool.’\"},{\"heading\":false,\"text\":\"“You see I think everything’s terrible anyhow,” she went on in a convinced way. “Everybody thinks so—the most advanced people. And I know. I’ve been everywhere and seen everything and done everything.” Her eyes flashed around her in a defiant way, rather like Tom’s, and she laughed with thrilling scorn. “Sophisticated—God, I’m sophisticated!”\"},{\"heading\":false,\"text\":\"The instant her voice broke off, ceasing to compel my attention, my belief, I felt the basic insincerity of what she had said. It made me uneasy, as though the whole evening had been a trick of some sort to exact a contributory emotion from me. I waited, and sure enough, in a moment she looked at me with an absolute smirk on her lovely face, as if she had asserted her membership in a rather distinguished secret society to which she and Tom belonged.\"},{\"heading\":false,\"text\":\"Inside, the crimson room bloomed with light. Tom and Miss Baker sat at either end of the long couch and she read aloud to him from the Saturday Evening Post—the words, murmurous and uninflected, running together in a soothing tune. The lamplight, bright on his boots and dull on the autumn-leaf yellow of her hair, glinted along the paper as she turned a page with a flutter of slender muscles in her arms.\"},{\"heading\":false,\"text\":\"When we came in she held us silent for a moment with a lifted hand.\"},{\"heading\":false,\"text\":\"“To be continued,” she said, tossing the magazine on the table, “in our very next issue.”\"},{\"heading\":false,\"text\":\"Her body asserted itself with a restless movement of her knee, and she stood up.\"},{\"heading\":false,\"text\":\"“Ten o’clock,” she remarked, apparently finding the time on the ceiling. “Time for this good girl to go to bed.”\"},{\"heading\":false,\"text\":\"“Jordan’s going to play in the tournament tomorrow,” explained Daisy, “over at Westchester.”\"},{\"heading\":false,\"text\":\"“Oh—you’re Jordan Baker.”\"},{\"heading\":false,\"text\":\"I knew now why her face was familiar—its pleasing contemptuous expression had looked out at me from many rotogravure pictures of the sporting life at Asheville and Hot Springs and Palm Beach. I had heard some story of her too, a critical, unpleasant story, but what it was I had forgotten long ago.\"},{\"heading\":false,\"text\":\"“Good night,” she said softly. “Wake me at eight, won’t you.”\"},{\"heading\":false,\"text\":\"“If you’ll get up.”\"},{\"heading\":false,\"text\":\"“I will. Good night, Mr. Carraway. See you anon.”\"},{\"heading\":false,\"text\":\"“Of course you will,” confirmed Daisy. “In fact I think I’ll arrange a marriage. Come over often, Nick, and I’ll sort of—oh—fling you together. You know—lock you up accidentally in linen closets and push you out to sea in a boat, and all that sort of thing—”\"},{\"heading\":false,\"text\":\"“Good night,” called Miss Baker from the stairs. “I haven’t heard a word.”\"},{\"heading\":false,\"text\":\"“She’s a nice girl,” said Tom after a moment. “They oughtn’t to let her run around the country this way.”\"},{\"heading\":false,\"text\":\"“Who oughtn’t to?” inquired Daisy coldly.\"},{\"heading\":false,\"text\":\"“Her family.”\"},{\"heading\":false,\"text\":\"“Her family is one aunt about a thousand years old. Besides, Nick’s going to look after her, aren’t you, Nick? She’s going to spend lots of weekends out here this summer. I think the home influence will be very good for her.”\"},{\"heading\":false,\"text\":\"Daisy and Tom looked at each other for a moment in silence.\"},{\"heading\":false,\"text\":\"“Is she from New York?” I asked quickly.\"},{\"heading\":false,\"text\":\"“From Louisville. Our white girlhood was passed together there. Our beautiful white—”\"},{\"heading\":false,\"text\":\"“Did you give Nick a little heart to heart talk on the veranda?” demanded Tom suddenly.\"},{\"heading\":false,\"text\":\"“Did I?” She looked at me. “I can’t seem to remember, but I think we talked about the Nordic race. Yes, I’m sure we did. It sort of crept up on us and first thing you know—”\"},{\"heading\":false,\"text\":\"“Don’t believe everything you hear, Nick,” he advised me.\"},{\"heading\":false,\"text\":\"I said lightly that I had heard nothing at all, and a few minutes later I got up to go home. They came to the door with me and stood side by side in a cheerful square of light. As I started my motor Daisy peremptorily called: “Wait!\"},{\"heading\":false,\"text\":\"“I forgot to ask you something, and it’s important. We heard you were engaged to a girl out West.”\"},{\"heading\":false,\"text\":\"“That’s right,” corroborated Tom kindly. “We heard that you were engaged.”\"},{\"heading\":false,\"text\":\"“It’s a libel. I’m too poor.”\"},{\"heading\":false,\"text\":\"“But we heard it,” insisted Daisy, surprising me by opening up again in a flower-like way. “We heard it from three people, so it must be true.”\"},{\"heading\":false,\"text\":\"Of course I knew what they were referring to, but I wasn’t even vaguely engaged. The fact that gossip had published the banns was one of the reasons I had come East. You can’t stop going with an old friend on account of rumours, and on the other hand I had no intention of being rumoured into marriage.\"},{\"heading\":false,\"text\":\"Their interest rather touched me and made them less remotely rich—nevertheless, I was confused and a little disgusted as I drove away. It seemed to me that the thing for Daisy to do was to rush out of the house, child in arms—but apparently there were no such intentions in her head. As for Tom, the fact that he “had some woman in New York” was really less surprising than that he had been depressed by a book. Something was making him nibble at the edge of stale ideas as if his sturdy physical egotism no longer nourished his peremptory heart.\"},{\"heading\":false,\"text\":\"Already it was deep summer on roadhouse roofs and in front of wayside garages, where new red petrol-pumps sat out in pools of light, and when I reached my estate at West Egg I ran the car under its shed and sat for a while on an abandoned grass roller in the yard. The wind had blown off, leaving a loud, bright night, with wings beating in the trees and a persistent organ sound as the full bellows of the earth blew the frogs full of life. The silhouette of a moving cat wavered across the moonlight, and, turning my head to watch it, I saw that I was not alone—fifty feet away a figure had emerged from the shadow of my neighbour’s mansion and was standing with his hands in his pockets regarding the silver pepper of the stars. Something in his leisurely movements and the secure position of his feet upon the lawn suggested that it was Mr. Gatsby himself, come out to determine what share was his of our local heavens.\"},{\"heading\":false,\"text\":\"I decided to call to him. Miss Baker had mentioned him at dinner, and that would do for an introduction. But I didn’t call to him, for he gave a sudden intimation that he was content to be alone—he stretched out his arms toward the dark water in a curious way, and, far as I was from him, I could have sworn he was trembling. Involuntarily I glanced seaward—and distinguished nothing except a single green light, minute and far away, that might have been the end of a dock. When I looked once more for Gatsby he had vanished, and I was alone again in the unquiet darkness.\"}]},{\"title\":\"II\",\"blocks\":[{\"heading\":false,\"text\":\"About halfway between West Egg and New York the motor road hastily joins the railroad and runs beside it for a quarter of a mile, so as to shrink away from a certain desolate area of land. This is a valley of ashes—a fantastic farm where ashes grow like wheat into ridges and hills and grotesque gardens; where ashes take the forms of houses and chimneys and rising smoke and, finally, with a transcendent effort, of ash-grey men, who move dimly and already crumbling through the powdery air. Occasionally a line of grey cars crawls along an invisible track, gives out a ghastly creak, and comes to rest, and immediately the ash-grey men swarm up with leaden spades and stir up an impenetrable cloud, which screens their obscure operations from your sight.\"},{\"heading\":false,\"text\":\"But above the grey land and the spasms of bleak dust which drift endlessly over it, you perceive, after a moment, the eyes of Doctor T. J. Eckleburg. The eyes of Doctor T. J. Eckleburg are blue and gigantic—their retinas are one yard high. They look out of no face, but, instead, from a pair of enormous yellow spectacles which pass over a nonexistent nose. Evidently some wild wag of an oculist set them there to fatten his practice in the borough of Queens, and then sank down himself into eternal blindness, or forgot them and moved away. But his eyes, dimmed a little by many paintless days, under sun and rain, brood on over the solemn dumping ground.\"},{\"heading\":false,\"text\":\"The valley of ashes is bounded on one side by a small foul river, and, when the drawbridge is up to let barges through, the passengers on waiting trains can stare at the dismal scene for as long as half an hour. There is always a halt there of at least a minute, and it was because of this that I first met Tom Buchanan’s mistress.\"},{\"heading\":false,\"text\":\"The fact that he had one was insisted upon wherever he was known. His acquaintances resented the fact that he turned up in popular cafés with her and, leaving her at a table, sauntered about, chatting with whomsoever he knew. Though I was curious to see her, I had no desire to meet her—but I did. I went up to New York with Tom on the train one afternoon, and when we stopped by the ash-heaps he jumped to his feet and, taking hold of my elbow, literally forced me from the car.\"},{\"heading\":false,\"text\":\"“We’re getting off,” he insisted. “I want you to meet my girl.”\"},{\"heading\":false,\"text\":\"I think he’d tanked up a good deal at luncheon, and his determination to have my company bordered on violence. The supercilious assumption was that on Sunday afternoon I had nothing better to do.\"},{\"heading\":false,\"text\":\"I followed him over a low whitewashed railroad fence, and we walked back a hundred yards along the road under Doctor Eckleburg’s persistent stare. The only building in sight was a small block of yellow brick sitting on the edge of the waste land, a sort of compact Main Street ministering to it, and contiguous to absolutely nothing. One of the three shops it contained was for rent and another was an all-night restaurant, approached by a trail of ashes; the third was a garage—Repairs. George B. Wilson. Cars bought and sold.—and I followed Tom inside.\"},{\"heading\":false,\"text\":\"The interior was unprosperous and bare; the only car visible was the dust-covered wreck of a Ford which crouched in a dim corner. It had occurred to me that this shadow of a garage must be a blind, and that sumptuous and romantic apartments were concealed overhead, when the proprietor himself appeared in the door of an office, wiping his hands on a piece of waste. He was a blond, spiritless man, anaemic, and faintly handsome. When he saw us a damp gleam of hope sprang into his light blue eyes.\"},{\"heading\":false,\"text\":\"“Hello, Wilson, old man,” said Tom, slapping him jovially on the shoulder. “How’s business?”\"},{\"heading\":false,\"text\":\"“I can’t complain,” answered Wilson unconvincingly. “When are you going to sell me that car?”\"},{\"heading\":false,\"text\":\"“Next week; I’ve got my man working on it now.”\"},{\"heading\":false,\"text\":\"“Works pretty slow, don’t he?”\"},{\"heading\":false,\"text\":\"“No, he doesn’t,” said Tom coldly. “And if you feel that way about it, maybe I’d better sell it somewhere else after all.”\"},{\"heading\":false,\"text\":\"“I don’t mean that,” explained Wilson quickly. “I just meant—”\"},{\"heading\":false,\"text\":\"His voice faded off and Tom glanced impatiently around the garage. Then I heard footsteps on a stairs, and in a moment the thickish figure of a woman blocked out the light from the office door. She was in the middle thirties, and faintly stout, but she carried her flesh sensuously as some women can. Her face, above a spotted dress of dark blue crêpe-de-chine, contained no facet or gleam of beauty, but there was an immediately perceptible vitality about her as if the nerves of her body were continually smouldering. She smiled slowly and, walking through her husband as if he were a ghost, shook hands with Tom, looking him flush in the eye. Then she wet her lips, and without turning around spoke to her husband in a soft, coarse voice:\"},{\"heading\":false,\"text\":\"“Get some chairs, why don’t you, so somebody can sit down.”\"},{\"heading\":false,\"text\":\"“Oh, sure,” agreed Wilson hurriedly, and went toward the little office, mingling immediately with the cement colour of the walls. A white ashen dust veiled his dark suit and his pale hair as it veiled everything in the vicinity—except his wife, who moved close to Tom.\"},{\"heading\":false,\"text\":\"“I want to see you,” said Tom intently. “Get on the next train.”\"},{\"heading\":false,\"text\":\"“All right.”\"},{\"heading\":false,\"text\":\"“I’ll meet you by the newsstand on the lower level.”\"},{\"heading\":false,\"text\":\"She nodded and moved away from him just as George Wilson emerged with two chairs from his office door.\"},{\"heading\":false,\"text\":\"We waited for her down the road and out of sight. It was a few days before the Fourth of July, and a grey, scrawny Italian child was setting torpedoes in a row along the railroad track.\"},{\"heading\":false,\"text\":\"“Terrible place, isn’t it,” said Tom, exchanging a frown with Doctor Eckleburg.\"},{\"heading\":false,\"text\":\"“Awful.”\"},{\"heading\":false,\"text\":\"“It does her good to get away.”\"},{\"heading\":false,\"text\":\"“Doesn’t her husband object?”\"},{\"heading\":false,\"text\":\"“Wilson? He thinks she goes to see her sister in New York. He’s so dumb he doesn’t know he’s alive.”\"},{\"heading\":false,\"text\":\"So Tom Buchanan and his girl and I went up together to New York—or not quite together, for Mrs. Wilson sat discreetly in another car. Tom deferred that much to the sensibilities of those East Eggers who might be on the train.\"},{\"heading\":false,\"text\":\"She had changed her dress to a brown figured muslin, which stretched tight over her rather wide hips as Tom helped her to the platform in New York. At the newsstand she bought a copy of Town Tattle and a moving-picture magazine, and in the station drugstore some cold cream and a small flask of perfume. Upstairs, in the solemn echoing drive she let four taxicabs drive away before she selected a new one, lavender-coloured with grey upholstery, and in this we slid out from the mass of the station into the glowing sunshine. But immediately she turned sharply from the window and, leaning forward, tapped on the front glass.\"},{\"heading\":false,\"text\":\"“I want to get one of those dogs,” she said earnestly. “I want to get one for the apartment. They’re nice to have—a dog.”\"},{\"heading\":false,\"text\":\"We backed up to a grey old man who bore an absurd resemblance to John D. Rockefeller. In a basket swung from his neck cowered a dozen very recent puppies of an indeterminate breed.\"},{\"heading\":false,\"text\":\"“What kind are they?” asked Mrs. Wilson eagerly, as he came to the taxi-window.\"},{\"heading\":false,\"text\":\"“All kinds. What kind do you want, lady?”\"},{\"heading\":false,\"text\":\"“I’d like to get one of those police dogs; I don’t suppose you got that kind?”\"},{\"heading\":false,\"text\":\"The man peered doubtfully into the basket, plunged in his hand and drew one up, wriggling, by the back of the neck.\"},{\"heading\":false,\"text\":\"“That’s no police dog,” said Tom.\"},{\"heading\":false,\"text\":\"“No, it’s not exactly a police dog,” said the man with disappointment in his voice. “It’s more of an Airedale.” He passed his hand over the brown washrag of a back. “Look at that coat. Some coat. That’s a dog that’ll never bother you with catching cold.”\"},{\"heading\":false,\"text\":\"“I think it’s cute,” said Mrs. Wilson enthusiastically. “How much is it?”\"},{\"heading\":false,\"text\":\"“That dog?” He looked at it admiringly. “That dog will cost you ten dollars.”\"},{\"heading\":false,\"text\":\"The Airedale—undoubtedly there was an Airedale concerned in it somewhere, though its feet were startlingly white—changed hands and settled down into Mrs. Wilson’s lap, where she fondled the weatherproof coat with rapture.\"},{\"heading\":false,\"text\":\"“Is it a boy or a girl?” she asked delicately.\"},{\"heading\":false,\"text\":\"“That dog? That dog’s a boy.”\"},{\"heading\":false,\"text\":\"“It’s a bitch,” said Tom decisively. “Here’s your money. Go and buy ten more dogs with it.”\"},{\"heading\":false,\"text\":\"We drove over to Fifth Avenue, warm and soft, almost pastoral, on the summer Sunday afternoon. I wouldn’t have been surprised to see a great flock of white sheep turn the corner.\"},{\"heading\":false,\"text\":\"“Hold on,” I said, “I have to leave you here.”\"},{\"heading\":false,\"text\":\"“No you don’t,” interposed Tom quickly. “Myrtle’ll be hurt if you don’t come up to the apartment. Won’t you, Myrtle?”\"},{\"heading\":false,\"text\":\"“Come on,” she urged. “I’ll telephone my sister Catherine. She’s said to be very beautiful by people who ought to know.”\"},{\"heading\":false,\"text\":\"“Well, I’d like to, but—”\"},{\"heading\":false,\"text\":\"We went on, cutting back again over the Park toward the West Hundreds. At 158th Street the cab stopped at one slice in a long white cake of apartment-houses. Throwing a regal homecoming glance around the neighbourhood, Mrs. Wilson gathered up her dog and her other purchases, and went haughtily in.\"},{\"heading\":false,\"text\":\"“I’m going to have the McKees come up,” she announced as we rose in the elevator. “And, of course, I got to call up my sister, too.”\"},{\"heading\":false,\"text\":\"The apartment was on the top floor—a small living-room, a small dining-room, a small bedroom, and a bath. The living-room was crowded to the doors with a set of tapestried furniture entirely too large for it, so that to move about was to stumble continually over scenes of ladies swinging in the gardens of Versailles. The only picture was an over-enlarged photograph, apparently a hen sitting on a blurred rock. Looked at from a distance, however, the hen resolved itself into a bonnet, and the countenance of a stout old lady beamed down into the room. Several old copies of Town Tattle lay on the table together with a copy of Simon Called Peter, and some of the small scandal magazines of Broadway. Mrs. Wilson was first concerned with the dog. A reluctant elevator boy went for a box full of straw and some milk, to which he added on his own initiative a tin of large, hard dog biscuits—one of which decomposed apathetically in the saucer of milk all afternoon. Meanwhile Tom brought out a bottle of whisky from a locked bureau door.\"},{\"heading\":false,\"text\":\"I have been drunk just twice in my life, and the second time was that afternoon; so everything that happened has a dim, hazy cast over it, although until after eight o’clock the apartment was full of cheerful sun. Sitting on Tom’s lap Mrs. Wilson called up several people on the telephone; then there were no cigarettes, and I went out to buy some at the drugstore on the corner. When I came back they had both disappeared, so I sat down discreetly in the living-room and read a chapter of Simon Called Peter—either it was terrible stuff or the whisky distorted things, because it didn’t make any sense to me.\"},{\"heading\":false,\"text\":\"Just as Tom and Myrtle (after the first drink Mrs. Wilson and I called each other by our first names) reappeared, company commenced to arrive at the apartment door.\"},{\"heading\":false,\"text\":\"The sister, Catherine, was a slender, worldly girl of about thirty, with a solid, sticky bob of red hair, and a complexion powdered milky white. Her eyebrows had been plucked and then drawn on again at a more rakish angle, but the efforts of nature toward the restoration of the old alignment gave a blurred air to her face. When she moved about there was an incessant clicking as innumerable pottery bracelets jingled up and down upon her arms. She came in with such a proprietary haste, and looked around so possessively at the furniture that I wondered if she lived here. But when I asked her she laughed immoderately, repeated my question aloud, and told me she lived with a girl friend at a hotel.\"},{\"heading\":false,\"text\":\"Mr. McKee was a pale, feminine man from the flat below. He had just shaved, for there was a white spot of lather on his cheekbone, and he was most respectful in his greeting to everyone in the room. He informed me that he was in the “artistic game,” and I gathered later that he was a photographer and had made the dim enlargement of Mrs. Wilson’s mother which hovered like an ectoplasm on the wall. His wife was shrill, languid, handsome, and horrible. She told me with pride that her husband had photographed her a hundred and twenty-seven times since they had been married.\"},{\"heading\":false,\"text\":\"Mrs. Wilson had changed her costume some time before, and was now attired in an elaborate afternoon dress of cream-coloured chiffon, which gave out a continual rustle as she swept about the room. With the influence of the dress her personality had also undergone a change. The intense vitality that had been so remarkable in the garage was converted into impressive hauteur. Her laughter, her gestures, her assertions became more violently affected moment by moment, and as she expanded the room grew smaller around her, until she seemed to be revolving on a noisy, creaking pivot through the smoky air.\"},{\"heading\":false,\"text\":\"“My dear,” she told her sister in a high, mincing shout, “most of these fellas will cheat you every time. All they think of is money. I had a woman up here last week to look at my feet, and when she gave me the bill you’d of thought she had my appendicitis out.”\"},{\"heading\":false,\"text\":\"“What was the name of the woman?” asked Mrs. McKee.\"},{\"heading\":false,\"text\":\"“Mrs. Eberhardt. She goes around looking at people’s feet in their own homes.”\"},{\"heading\":false,\"text\":\"“I like your dress,” remarked Mrs. McKee, “I think it’s adorable.”\"},{\"heading\":false,\"text\":\"Mrs. Wilson rejected the compliment by raising her eyebrow in disdain.\"},{\"heading\":false,\"text\":\"“It’s just a crazy old thing,” she said. “I just slip it on sometimes when I don’t care what I look like.”\"},{\"heading\":false,\"text\":\"“But it looks wonderful on you, if you know what I mean,” pursued Mrs. McKee. “If Chester could only get you in that pose I think he could make something of it.”\"},{\"heading\":false,\"text\":\"We all looked in silence at Mrs. Wilson, who removed a strand of hair from over her eyes and looked back at us with a brilliant smile. Mr. McKee regarded her intently with his head on one side, and then moved his hand back and forth slowly in front of his face.\"},{\"heading\":false,\"text\":\"“I should change the light,” he said after a moment. “I’d like to bring out the modelling of the features. And I’d try to get hold of all the back hair.”\"},{\"heading\":false,\"text\":\"“I wouldn’t think of changing the light,” cried Mrs. McKee. “I think it’s—”\"},{\"heading\":false,\"text\":\"Her husband said “Sh!” and we all looked at the subject again, whereupon Tom Buchanan yawned audibly and got to his feet.\"},{\"heading\":false,\"text\":\"“You McKees have something to drink,” he said. “Get some more ice and mineral water, Myrtle, before everybody goes to sleep.”\"},{\"heading\":false,\"text\":\"“I told that boy about the ice.” Myrtle raised her eyebrows in despair at the shiftlessness of the lower orders. “These people! You have to keep after them all the time.”\"},{\"heading\":false,\"text\":\"She looked at me and laughed pointlessly. Then she flounced over to the dog, kissed it with ecstasy, and swept into the kitchen, implying that a dozen chefs awaited her orders there.\"},{\"heading\":false,\"text\":\"“I’ve done some nice things out on Long Island,” asserted Mr. McKee.\"},{\"heading\":false,\"text\":\"Tom looked at him blankly.\"},{\"heading\":false,\"text\":\"“Two of them we have framed downstairs.”\"},{\"heading\":false,\"text\":\"“Two what?” demanded Tom.\"},{\"heading\":false,\"text\":\"“Two studies. One of them I call Montauk Point—The Gulls, and the other I call Montauk Point—The Sea.”\"},{\"heading\":false,\"text\":\"The sister Catherine sat down beside me on the couch.\"},{\"heading\":false,\"text\":\"“Do you live down on Long Island, too?” she inquired.\"},{\"heading\":false,\"text\":\"“I live at West Egg.”\"},{\"heading\":false,\"text\":\"“Really? I was down there at a party about a month ago. At a man named Gatsby’s. Do you know him?”\"},{\"heading\":false,\"text\":\"“I live next door to him.”\"},{\"heading\":false,\"text\":\"“Well, they say he’s a nephew or a cousin of Kaiser Wilhelm’s. That’s where all his money comes from.”\"},{\"heading\":false,\"text\":\"“Really?”\"},{\"heading\":false,\"text\":\"She nodded.\"},{\"heading\":false,\"text\":\"“I’m scared of him. I’d hate to have him get anything on me.”\"},{\"heading\":false,\"text\":\"This absorbing information about my neighbour was interrupted by Mrs. McKee’s pointing suddenly at Catherine:\"},{\"heading\":false,\"text\":\"“Chester, I think you could do something with her,” she broke out, but Mr. McKee only nodded in a bored way, and turned his attention to Tom.\"},{\"heading\":false,\"text\":\"“I’d like to do more work on Long Island, if I could get the entry. All I ask is that they should give me a start.”\"},{\"heading\":false,\"text\":\"“Ask Myrtle,” said Tom, breaking into a short shout of laughter as Mrs. Wilson entered with a tray. “She’ll give you a letter of introduction, won’t you, Myrtle?”\"},{\"heading\":false,\"text\":\"“Do what?” she asked, startled.\"},{\"heading\":false,\"text\":\"“You’ll give McKee a letter of introduction to your husband, so he can do some studies of him.” His lips moved silently for a moment as he invented, “ ‘George B. Wilson at the Gasoline Pump,’ or something like that.”\"},{\"heading\":false,\"text\":\"Catherine leaned close to me and whispered in my ear:\"},{\"heading\":false,\"text\":\"“Neither of them can stand the person they’re married to.”\"},{\"heading\":false,\"text\":\"“Can’t they?”\"},{\"heading\":false,\"text\":\"“Can’t stand them.” She looked at Myrtle and then at Tom. “What I say is, why go on living with them if they can’t stand them? If I was them I’d get a divorce and get married to each other right away.”\"},{\"heading\":false,\"text\":\"“Doesn’t she like Wilson either?”\"},{\"heading\":false,\"text\":\"The answer to this was unexpected. It came from Myrtle, who had overheard the question, and it was violent and obscene.\"},{\"heading\":false,\"text\":\"“You see,” cried Catherine triumphantly. She lowered her voice again. “It’s really his wife that’s keeping them apart. She’s a Catholic, and they don’t believe in divorce.”\"},{\"heading\":false,\"text\":\"Daisy was not a Catholic, and I was a little shocked at the elaborateness of the lie.\"},{\"heading\":false,\"text\":\"“When they do get married,” continued Catherine, “they’re going West to live for a while until it blows over.”\"},{\"heading\":false,\"text\":\"“It’d be more discreet to go to Europe.”\"},{\"heading\":false,\"text\":\"“Oh, do you like Europe?” she exclaimed surprisingly. “I just got back from Monte Carlo.”\"},{\"heading\":false,\"text\":\"“Really.”\"},{\"heading\":false,\"text\":\"“Just last year. I went over there with another girl.”\"},{\"heading\":false,\"text\":\"“Stay long?”\"},{\"heading\":false,\"text\":\"“No, we just went to Monte Carlo and back. We went by way of Marseilles. We had over twelve hundred dollars when we started, but we got gyped out of it all in two days in the private rooms. We had an awful time getting back, I can tell you. God, how I hated that town!”\"},{\"heading\":false,\"text\":\"The late afternoon sky bloomed in the window for a moment like the blue honey of the Mediterranean—then the shrill voice of Mrs. McKee called me back into the room.\"},{\"heading\":false,\"text\":\"“I almost made a mistake, too,” she declared vigorously. “I almost married a little kike who’d been after me for years. I knew he was below me. Everybody kept saying to me: ‘Lucille, that man’s way below you!’ But if I hadn’t met Chester, he’d of got me sure.”\"},{\"heading\":false,\"text\":\"“Yes, but listen,” said Myrtle Wilson, nodding her head up and down, “at least you didn’t marry him.”\"},{\"heading\":false,\"text\":\"“I know I didn’t.”\"},{\"heading\":false,\"text\":\"“Well, I married him,” said Myrtle, ambiguously. “And that’s the difference between your case and mine.”\"},{\"heading\":false,\"text\":\"“Why did you, Myrtle?” demanded Catherine. “Nobody forced you to.”\"},{\"heading\":false,\"text\":\"Myrtle considered.\"},{\"heading\":false,\"text\":\"“I married him because I thought he was a gentleman,” she said finally. “I thought he knew something about breeding, but he wasn’t fit to lick my shoe.”\"},{\"heading\":false,\"text\":\"“You were crazy about him for a while,” said Catherine.\"},{\"heading\":false,\"text\":\"“Crazy about him!” cried Myrtle incredulously. “Who said I was crazy about him? I never was any more crazy about him than I was about that man there.”\"},{\"heading\":false,\"text\":\"She pointed suddenly at me, and everyone looked at me accusingly. I tried to show by my expression that I expected no affection.\"},{\"heading\":false,\"text\":\"“The only crazy I was was when I married him. I knew right away I made a mistake. He borrowed somebody’s best suit to get married in, and never even told me about it, and the man came after it one day when he was out: ‘Oh, is that your suit?’ I said. ‘This is the first I ever heard about it.’ But I gave it to him and then I lay down and cried to beat the band all afternoon.”\"},{\"heading\":false,\"text\":\"“She really ought to get away from him,” resumed Catherine to me. “They’ve been living over that garage for eleven years. And Tom’s the first sweetie she ever had.”\"},{\"heading\":false,\"text\":\"The bottle of whisky—a second one—was now in constant demand by all present, excepting Catherine, who “felt just as good on nothing at all.” Tom rang for the janitor and sent him for some celebrated sandwiches, which were a complete supper in themselves. I wanted to get out and walk eastward toward the park through the soft twilight, but each time I tried to go I became entangled in some wild, strident argument which pulled me back, as if with ropes, into my chair. Yet high over the city our line of yellow windows must have contributed their share of human secrecy to the casual watcher in the darkening streets, and I saw him too, looking up and wondering. I was within and without, simultaneously enchanted and repelled by the inexhaustible variety of life.\"},{\"heading\":false,\"text\":\"Myrtle pulled her chair close to mine, and suddenly her warm breath poured over me the story of her first meeting with Tom.\"},{\"heading\":false,\"text\":\"“It was on the two little seats facing each other that are always the last ones left on the train. I was going up to New York to see my sister and spend the night. He had on a dress suit and patent leather shoes, and I couldn’t keep my eyes off him, but every time he looked at me I had to pretend to be looking at the advertisement over his head. When we came into the station he was next to me, and his white shirtfront pressed against my arm, and so I told him I’d have to call a policeman, but he knew I lied. I was so excited that when I got into a taxi with him I didn’t hardly know I wasn’t getting into a subway train. All I kept thinking about, over and over, was ‘You can’t live forever; you can’t live forever.’ ”\"},{\"heading\":false,\"text\":\"She turned to Mrs. McKee and the room rang full of her artificial laughter.\"},{\"heading\":false,\"text\":\"“My dear,” she cried, “I’m going to give you this dress as soon as I’m through with it. I’ve got to get another one tomorrow. I’m going to make a list of all the things I’ve got to get. A massage and a wave, and a collar for the dog, and one of those cute little ashtrays where you touch a spring, and a wreath with a black silk bow for mother’s grave that’ll last all summer. I got to write down a list so I won’t forget all the things I got to do.”\"},{\"heading\":false,\"text\":\"It was nine o’clock—almost immediately afterward I looked at my watch and found it was ten. Mr. McKee was asleep on a chair with his fists clenched in his lap, like a photograph of a man of action. Taking out my handkerchief I wiped from his cheek the spot of dried lather that had worried me all the afternoon.\"},{\"heading\":false,\"text\":\"The little dog was sitting on the table looking with blind eyes through the smoke, and from time to time groaning faintly. People disappeared, reappeared, made plans to go somewhere, and then lost each other, searched for each other, found each other a few feet away. Some time toward midnight Tom Buchanan and Mrs. Wilson stood face to face discussing, in impassioned voices, whether Mrs. Wilson had any right to mention Daisy’s name.\"},{\"heading\":false,\"text\":\"“Daisy! Daisy! Daisy!” shouted Mrs. Wilson. “I’ll say it whenever I want to! Daisy! Dai—”\"},{\"heading\":false,\"text\":\"Making a short deft movement, Tom Buchanan broke her nose with his open hand.\"},{\"heading\":false,\"text\":\"Then there were bloody towels upon the bathroom floor, and women’s voices scolding, and high over the confusion a long broken wail of pain. Mr. McKee awoke from his doze and started in a daze toward the door. When he had gone halfway he turned around and stared at the scene—his wife and Catherine scolding and consoling as they stumbled here and there among the crowded furniture with articles of aid, and the despairing figure on the couch, bleeding fluently, and trying to spread a copy of Town Tattle over the tapestry scenes of Versailles. Then Mr. McKee turned and continued on out the door. Taking my hat from the chandelier, I followed.\"},{\"heading\":false,\"text\":\"“Come to lunch some day,” he suggested, as we groaned down in the elevator.\"},{\"heading\":false,\"text\":\"“Where?”\"},{\"heading\":false,\"text\":\"“Anywhere.”\"},{\"heading\":false,\"text\":\"“Keep your hands off the lever,” snapped the elevator boy.\"},{\"heading\":false,\"text\":\"“I beg your pardon,” said Mr. McKee with dignity, “I didn’t know I was touching it.”\"},{\"heading\":false,\"text\":\"“All right,” I agreed, “I’ll be glad to.”\"},{\"heading\":false,\"text\":\"… I was standing beside his bed and he was sitting up between the sheets, clad in his underwear, with a great portfolio in his hands.\"},{\"heading\":false,\"text\":\"“Beauty and the Beast… Loneliness… Old Grocery Horse… Brook’n Bridge…”\"},{\"heading\":false,\"text\":\"Then I was lying half asleep in the cold lower level of the Pennsylvania Station, staring at the morning Tribune, and waiting for the four o’clock train.\"}]},{\"title\":\"III\",\"blocks\":[{\"heading\":false,\"text\":\"There was music from my neighbour’s house through the summer nights. In his blue gardens men and girls came and went like moths among the whisperings and the champagne and the stars. At high tide in the afternoon I watched his guests diving from the tower of his raft, or taking the sun on the hot sand of his beach while his two motorboats slit the waters of the Sound, drawing aquaplanes over cataracts of foam. On weekends his Rolls-Royce became an omnibus, bearing parties to and from the city between nine in the morning and long past midnight, while his station wagon scampered like a brisk yellow bug to meet all trains. And on Mondays eight servants, including an extra gardener, toiled all day with mops and scrubbing-brushes and hammers and garden-shears, repairing the ravages of the night before.\"},{\"heading\":false,\"text\":\"Every Friday five crates of oranges and lemons arrived from a fruiterer in New York—every Monday these same oranges and lemons left his back door in a pyramid of pulpless halves. There was a machine in the kitchen which could extract the juice of two hundred oranges in half an hour if a little button was pressed two hundred times by a butler’s thumb.\"},{\"heading\":false,\"text\":\"At least once a fortnight a corps of caterers came down with several hundred feet of canvas and enough coloured lights to make a Christmas tree of Gatsby’s enormous garden. On buffet tables, garnished with glistening hors-d’oeuvre, spiced baked hams crowded against salads of harlequin designs and pastry pigs and turkeys bewitched to a dark gold. In the main hall a bar with a real brass rail was set up, and stocked with gins and liquors and with cordials so long forgotten that most of his female guests were too young to know one from another.\"},{\"heading\":false,\"text\":\"By seven o’clock the orchestra has arrived, no thin five-piece affair, but a whole pitful of oboes and trombones and saxophones and viols and cornets and piccolos, and low and high drums. The last swimmers have come in from the beach now and are dressing upstairs; the cars from New York are parked five deep in the drive, and already the halls and salons and verandas are gaudy with primary colours, and hair bobbed in strange new ways, and shawls beyond the dreams of Castile. The bar is in full swing, and floating rounds of cocktails permeate the garden outside, until the air is alive with chatter and laughter, and casual innuendo and introductions forgotten on the spot, and enthusiastic meetings between women who never knew each other’s names.\"},{\"heading\":false,\"text\":\"The lights grow brighter as the earth lurches away from the sun, and now the orchestra is playing yellow cocktail music, and the opera of voices pitches a key higher. Laughter is easier minute by minute, spilled with prodigality, tipped out at a cheerful word. The groups change more swiftly, swell with new arrivals, dissolve and form in the same breath; already there are wanderers, confident girls who weave here and there among the stouter and more stable, become for a sharp, joyous moment the centre of a group, and then, excited with triumph, glide on through the sea-change of faces and voices and colour under the constantly changing light.\"},{\"heading\":false,\"text\":\"Suddenly one of these gypsies, in trembling opal, seizes a cocktail out of the air, dumps it down for courage and, moving her hands like Frisco, dances out alone on the canvas platform. A momentary hush; the orchestra leader varies his rhythm obligingly for her, and there is a burst of chatter as the erroneous news goes around that she is Gilda Gray’s understudy from the Follies. The party has begun.\"},{\"heading\":false,\"text\":\"I believe that on the first night I went to Gatsby’s house I was one of the few guests who had actually been invited. People were not invited—they went there. They got into automobiles which bore them out to Long Island, and somehow they ended up at Gatsby’s door. Once there they were introduced by somebody who knew Gatsby, and after that they conducted themselves according to the rules of behaviour associated with an amusement park. Sometimes they came and went without having met Gatsby at all, came for the party with a simplicity of heart that was its own ticket of admission.\"},{\"heading\":false,\"text\":\"I had been actually invited. A chauffeur in a uniform of robin’s-egg blue crossed my lawn early that Saturday morning with a surprisingly formal note from his employer: the honour would be entirely Gatsby’s, it said, if I would attend his “little party” that night. He had seen me several times, and had intended to call on me long before, but a peculiar combination of circumstances had prevented it—signed Jay Gatsby, in a majestic hand.\"},{\"heading\":false,\"text\":\"Dressed up in white flannels I went over to his lawn a little after seven, and wandered around rather ill at ease among swirls and eddies of people I didn’t know—though here and there was a face I had noticed on the commuting train. I was immediately struck by the number of young Englishmen dotted about; all well dressed, all looking a little hungry, and all talking in low, earnest voices to solid and prosperous Americans. I was sure that they were selling something: bonds or insurance or automobiles. They were at least agonizingly aware of the easy money in the vicinity and convinced that it was theirs for a few words in the right key.\"},{\"heading\":false,\"text\":\"As soon as I arrived I made an attempt to find my host, but the two or three people of whom I asked his whereabouts stared at me in such an amazed way, and denied so vehemently any knowledge of his movements, that I slunk off in the direction of the cocktail table—the only place in the garden where a single man could linger without looking purposeless and alone.\"},{\"heading\":false,\"text\":\"I was on my way to get roaring drunk from sheer embarrassment when Jordan Baker came out of the house and stood at the head of the marble steps, leaning a little backward and looking with contemptuous interest down into the garden.\"},{\"heading\":false,\"text\":\"Welcome or not, I found it necessary to attach myself to someone before I should begin to address cordial remarks to the passersby.\"},{\"heading\":false,\"text\":\"“Hello!” I roared, advancing toward her. My voice seemed unnaturally loud across the garden.\"},{\"heading\":false,\"text\":\"“I thought you might be here,” she responded absently as I came up. “I remembered you lived next door to—”\"},{\"heading\":false,\"text\":\"She held my hand impersonally, as a promise that she’d take care of me in a minute, and gave ear to two girls in twin yellow dresses, who stopped at the foot of the steps.\"},{\"heading\":false,\"text\":\"“Hello!” they cried together. “Sorry you didn’t win.”\"},{\"heading\":false,\"text\":\"That was for the golf tournament. She had lost in the finals the week before.\"},{\"heading\":false,\"text\":\"“You don’t know who we are,” said one of the girls in yellow, “but we met you here about a month ago.”\"},{\"heading\":false,\"text\":\"“You’ve dyed your hair since then,” remarked Jordan, and I started, but the girls had moved casually on and her remark was addressed to the premature moon, produced like the supper, no doubt, out of a caterer’s basket. With Jordan’s slender golden arm resting in mine, we descended the steps and sauntered about the garden. A tray of cocktails floated at us through the twilight, and we sat down at a table with the two girls in yellow and three men, each one introduced to us as Mr. Mumble.\"},{\"heading\":false,\"text\":\"“Do you come to these parties often?” inquired Jordan of the girl beside her.\"},{\"heading\":false,\"text\":\"“The last one was the one I met you at,” answered the girl, in an alert confident voice. She turned to her companion: “Wasn’t it for you, Lucille?”\"},{\"heading\":false,\"text\":\"It was for Lucille, too.\"},{\"heading\":false,\"text\":\"“I like to come,” Lucille said. “I never care what I do, so I always have a good time. When I was here last I tore my gown on a chair, and he asked me my name and address—inside of a week I got a package from Croirier’s with a new evening gown in it.”\"},{\"heading\":false,\"text\":\"“Did you keep it?” asked Jordan.\"},{\"heading\":false,\"text\":\"“Sure I did. I was going to wear it tonight, but it was too big in the bust and had to be altered. It was gas blue with lavender beads. Two hundred and sixty-five dollars.”\"},{\"heading\":false,\"text\":\"“There’s something funny about a fellow that’ll do a thing like that,” said the other girl eagerly. “He doesn’t want any trouble with anybody.”\"},{\"heading\":false,\"text\":\"“Who doesn’t?” I inquired.\"},{\"heading\":false,\"text\":\"“Gatsby. Somebody told me—”\"},{\"heading\":false,\"text\":\"The two girls and Jordan leaned together confidentially.\"},{\"heading\":false,\"text\":\"“Somebody told me they thought he killed a man once.”\"},{\"heading\":false,\"text\":\"A thrill passed over all of us. The three Mr. Mumbles bent forward and listened eagerly.\"},{\"heading\":false,\"text\":\"“I don’t think it’s so much that,” argued Lucille sceptically; “It’s more that he was a German spy during the war.”\"},{\"heading\":false,\"text\":\"One of the men nodded in confirmation.\"},{\"heading\":false,\"text\":\"“I heard that from a man who knew all about him, grew up with him in Germany,” he assured us positively.\"},{\"heading\":false,\"text\":\"“Oh, no,” said the first girl, “it couldn’t be that, because he was in the American army during the war.” As our credulity switched back to her she leaned forward with enthusiasm. “You look at him sometimes when he thinks nobody’s looking at him. I’ll bet he killed a man.”\"},{\"heading\":false,\"text\":\"She narrowed her eyes and shivered. Lucille shivered. We all turned and looked around for Gatsby. It was testimony to the romantic speculation he inspired that there were whispers about him from those who had found little that it was necessary to whisper about in this world.\"},{\"heading\":false,\"text\":\"The first supper—there would be another one after midnight—was now being served, and Jordan invited me to join her own party, who were spread around a table on the other side of the garden. There were three married couples and Jordan’s escort, a persistent undergraduate given to violent innuendo, and obviously under the impression that sooner or later Jordan was going to yield him up her person to a greater or lesser degree. Instead of rambling, this party had preserved a dignified homogeneity, and assumed to itself the function of representing the staid nobility of the countryside—East Egg condescending to West Egg and carefully on guard against its spectroscopic gaiety.\"},{\"heading\":false,\"text\":\"“Let’s get out,” whispered Jordan, after a somehow wasteful and inappropriate half-hour; “this is much too polite for me.”\"},{\"heading\":false,\"text\":\"We got up, and she explained that we were going to find the host: I had never met him, she said, and it was making me uneasy. The undergraduate nodded in a cynical, melancholy way.\"},{\"heading\":false,\"text\":\"The bar, where we glanced first, was crowded, but Gatsby was not there. She couldn’t find him from the top of the steps, and he wasn’t on the veranda. On a chance we tried an important-looking door, and walked into a high Gothic library, panelled with carved English oak, and probably transported complete from some ruin overseas.\"},{\"heading\":false,\"text\":\"A stout, middle-aged man, with enormous owl-eyed spectacles, was sitting somewhat drunk on the edge of a great table, staring with unsteady concentration at the shelves of books. As we entered he wheeled excitedly around and examined Jordan from head to foot.\"},{\"heading\":false,\"text\":\"“What do you think?” he demanded impetuously.\"},{\"heading\":false,\"text\":\"“About what?”\"},{\"heading\":false,\"text\":\"He waved his hand toward the bookshelves.\"},{\"heading\":false,\"text\":\"“About that. As a matter of fact you needn’t bother to ascertain. I ascertained. They’re real.”\"},{\"heading\":false,\"text\":\"“The books?”\"},{\"heading\":false,\"text\":\"He nodded.\"},{\"heading\":false,\"text\":\"“Absolutely real—have pages and everything. I thought they’d be a nice durable cardboard. Matter of fact, they’re absolutely real. Pages and—Here! Lemme show you.”\"},{\"heading\":false,\"text\":\"Taking our scepticism for granted, he rushed to the bookcases and returned with Volume One of the Stoddard Lectures.\"},{\"heading\":false,\"text\":\"“See!” he cried triumphantly. “It’s a bona-fide piece of printed matter. It fooled me. This fella’s a regular Belasco. It’s a triumph. What thoroughness! What realism! Knew when to stop, too—didn’t cut the pages. But what do you want? What do you expect?”\"},{\"heading\":false,\"text\":\"He snatched the book from me and replaced it hastily on its shelf, muttering that if one brick was removed the whole library was liable to collapse.\"},{\"heading\":false,\"text\":\"“Who brought you?” he demanded. “Or did you just come? I was brought. Most people were brought.”\"},{\"heading\":false,\"text\":\"Jordan looked at him alertly, cheerfully, without answering.\"},{\"heading\":false,\"text\":\"“I was brought by a woman named Roosevelt,” he continued. “Mrs. Claud Roosevelt. Do you know her? I met her somewhere last night. I’ve been drunk for about a week now, and I thought it might sober me up to sit in a library.”\"},{\"heading\":false,\"text\":\"“Has it?”\"},{\"heading\":false,\"text\":\"“A little bit, I think. I can’t tell yet. I’ve only been here an hour. Did I tell you about the books? They’re real. They’re—”\"},{\"heading\":false,\"text\":\"“You told us.”\"},{\"heading\":false,\"text\":\"We shook hands with him gravely and went back outdoors.\"},{\"heading\":false,\"text\":\"There was dancing now on the canvas in the garden; old men pushing young girls backward in eternal graceless circles, superior couples holding each other tortuously, fashionably, and keeping in the corners—and a great number of single girls dancing individually or relieving the orchestra for a moment of the burden of the banjo or the traps. By midnight the hilarity had increased. A celebrated tenor had sung in Italian, and a notorious contralto had sung in jazz, and between the numbers people were doing “stunts” all over the garden, while happy, vacuous bursts of laughter rose toward the summer sky. A pair of stage twins, who turned out to be the girls in yellow, did a baby act in costume, and champagne was served in glasses bigger than finger-bowls. The moon had risen higher, and floating in the Sound was a triangle of silver scales, trembling a little to the stiff, tinny drip of the banjoes on the lawn.\"},{\"heading\":false,\"text\":\"I was still with Jordan Baker. We were sitting at a table with a man of about my age and a rowdy little girl, who gave way upon the slightest provocation to uncontrollable laughter. I was enjoying myself now. I had taken two finger-bowls of champagne, and the scene had changed before my eyes into something significant, elemental, and profound.\"},{\"heading\":false,\"text\":\"At a lull in the entertainment the man looked at me and smiled.\"},{\"heading\":false,\"text\":\"“Your face is familiar,” he said politely. “Weren’t you in the First Division during the war?”\"},{\"heading\":false,\"text\":\"“Why yes. I was in the Twenty-eighth Infantry.”\"},{\"heading\":false,\"text\":\"“I was in the Sixteenth until June nineteen-eighteen. I knew I’d seen you somewhere before.”\"},{\"heading\":false,\"text\":\"We talked for a moment about some wet, grey little villages in France. Evidently he lived in this vicinity, for he told me that he had just bought a hydroplane, and was going to try it out in the morning.\"},{\"heading\":false,\"text\":\"“Want to go with me, old sport? Just near the shore along the Sound.”\"},{\"heading\":false,\"text\":\"“What time?”\"},{\"heading\":false,\"text\":\"“Any time that suits you best.”\"},{\"heading\":false,\"text\":\"It was on the tip of my tongue to ask his name when Jordan looked around and smiled.\"},{\"heading\":false,\"text\":\"“Having a gay time now?” she inquired.\"},{\"heading\":false,\"text\":\"“Much better.” I turned again to my new acquaintance. “This is an unusual party for me. I haven’t even seen the host. I live over there—” I waved my hand at the invisible hedge in the distance, “and this man Gatsby sent over his chauffeur with an invitation.”\"},{\"heading\":false,\"text\":\"For a moment he looked at me as if he failed to understand.\"},{\"heading\":false,\"text\":\"“I’m Gatsby,” he said suddenly.\"},{\"heading\":false,\"text\":\"“What!” I exclaimed. “Oh, I beg your pardon.”\"},{\"heading\":false,\"text\":\"“I thought you knew, old sport. I’m afraid I’m not a very good host.”\"},{\"heading\":false,\"text\":\"He smiled understandingly—much more than understandingly. It was one of those rare smiles with a quality of eternal reassurance in it, that you may come across four or five times in life. It faced—or seemed to face—the whole eternal world for an instant, and then concentrated on you with an irresistible prejudice in your favour. It understood you just so far as you wanted to be understood, believed in you as you would like to believe in yourself, and assured you that it had precisely the impression of you that, at your best, you hoped to convey. Precisely at that point it vanished—and I was looking at an elegant young roughneck, a year or two over thirty, whose elaborate formality of speech just missed being absurd. Some time before he introduced himself I’d got a strong impression that he was picking his words with care.\"},{\"heading\":false,\"text\":\"Almost at the moment when Mr. Gatsby identified himself a butler hurried toward him with the information that Chicago was calling him on the wire. He excused himself with a small bow that included each of us in turn.\"},{\"heading\":false,\"text\":\"“If you want anything just ask for it, old sport,” he urged me. “Excuse me. I will rejoin you later.”\"},{\"heading\":false,\"text\":\"When he was gone I turned immediately to Jordan—constrained to assure her of my surprise. I had expected that Mr. Gatsby would be a florid and corpulent person in his middle years.\"},{\"heading\":false,\"text\":\"“Who is he?” I demanded. “Do you know?”\"},{\"heading\":false,\"text\":\"“He’s just a man named Gatsby.”\"},{\"heading\":false,\"text\":\"“Where is he from, I mean? And what does he do?”\"},{\"heading\":false,\"text\":\"“Now you’re started on the subject,” she answered with a wan smile. “Well, he told me once he was an Oxford man.”\"},{\"heading\":false,\"text\":\"A dim background started to take shape behind him, but at her next remark it faded away.\"},{\"heading\":false,\"text\":\"“However, I don’t believe it.”\"},{\"heading\":false,\"text\":\"“Why not?”\"},{\"heading\":false,\"text\":\"“I don’t know,” she insisted, “I just don’t think he went there.”\"},{\"heading\":false,\"text\":\"Something in her tone reminded me of the other girl’s “I think he killed a man,” and had the effect of stimulating my curiosity. I would have accepted without question the information that Gatsby sprang from the swamps of Louisiana or from the lower East Side of New York. That was comprehensible. But young men didn’t—at least in my provincial inexperience I believed they didn’t—drift coolly out of nowhere and buy a palace on Long Island Sound.\"},{\"heading\":false,\"text\":\"“Anyhow, he gives large parties,” said Jordan, changing the subject with an urban distaste for the concrete. “And I like large parties. They’re so intimate. At small parties there isn’t any privacy.”\"},{\"heading\":false,\"text\":\"There was the boom of a bass drum, and the voice of the orchestra leader rang out suddenly above the echolalia of the garden.\"},{\"heading\":false,\"text\":\"“Ladies and gentlemen,” he cried. “At the request of Mr. Gatsby we are going to play for you Mr. Vladmir Tostoff’s latest work, which attracted so much attention at Carnegie Hall last May. If you read the papers you know there was a big sensation.” He smiled with jovial condescension, and added: “Some sensation!” Whereupon everybody laughed.\"},{\"heading\":false,\"text\":\"“The piece is known,” he concluded lustily, “as ‘Vladmir Tostoff’s Jazz History of the World!’ ”\"},{\"heading\":false,\"text\":\"The nature of Mr. Tostoff’s composition eluded me, because just as it began my eyes fell on Gatsby, standing alone on the marble steps and looking from one group to another with approving eyes. His tanned skin was drawn attractively tight on his face and his short hair looked as though it were trimmed every day. I could see nothing sinister about him. I wondered if the fact that he was not drinking helped to set him off from his guests, for it seemed to me that he grew more correct as the fraternal hilarity increased. When the “Jazz History of the World” was over, girls were putting their heads on men’s shoulders in a puppyish, convivial way, girls were swooning backward playfully into men’s arms, even into groups, knowing that someone would arrest their falls—but no one swooned backward on Gatsby, and no French bob touched Gatsby’s shoulder, and no singing quartets were formed with Gatsby’s head for one link.\"},{\"heading\":false,\"text\":\"“I beg your pardon.”\"},{\"heading\":false,\"text\":\"Gatsby’s butler was suddenly standing beside us.\"},{\"heading\":false,\"text\":\"“Miss Baker?” he inquired. “I beg your pardon, but Mr. Gatsby would like to speak to you alone.”\"},{\"heading\":false,\"text\":\"“With me?” she exclaimed in surprise.\"},{\"heading\":false,\"text\":\"“Yes, madame.”\"},{\"heading\":false,\"text\":\"She got up slowly, raising her eyebrows at me in astonishment, and followed the butler toward the house. I noticed that she wore her evening-dress, all her dresses, like sports clothes—there was a jauntiness about her movements as if she had first learned to walk upon golf courses on clean, crisp mornings.\"},{\"heading\":false,\"text\":\"I was alone and it was almost two. For some time confused and intriguing sounds had issued from a long, many-windowed room which overhung the terrace. Eluding Jordan’s undergraduate, who was now engaged in an obstetrical conversation with two chorus girls, and who implored me to join him, I went inside.\"},{\"heading\":false,\"text\":\"The large room was full of people. One of the girls in yellow was playing the piano, and beside her stood a tall, red-haired young lady from a famous chorus, engaged in song. She had drunk a quantity of champagne, and during the course of her song she had decided, ineptly, that everything was very, very sad—she was not only singing, she was weeping too. Whenever there was a pause in the song she filled it with gasping, broken sobs, and then took up the lyric again in a quavering soprano. The tears coursed down her cheeks—not freely, however, for when they came into contact with her heavily beaded eyelashes they assumed an inky colour, and pursued the rest of their way in slow black rivulets. A humorous suggestion was made that she sing the notes on her face, whereupon she threw up her hands, sank into a chair, and went off into a deep vinous sleep.\"},{\"heading\":false,\"text\":\"“She had a fight with a man who says he’s her husband,” explained a girl at my elbow.\"},{\"heading\":false,\"text\":\"I looked around. Most of the remaining women were now having fights with men said to be their husbands. Even Jordan’s party, the quartet from East Egg, were rent asunder by dissension. One of the men was talking with curious intensity to a young actress, and his wife, after attempting to laugh at the situation in a dignified and indifferent way, broke down entirely and resorted to flank attacks—at intervals she appeared suddenly at his side like an angry diamond, and hissed: “You promised!” into his ear.\"},{\"heading\":false,\"text\":\"The reluctance to go home was not confined to wayward men. The hall was at present occupied by two deplorably sober men and their highly indignant wives. The wives were sympathizing with each other in slightly raised voices.\"},{\"heading\":false,\"text\":\"“Whenever he sees I’m having a good time he wants to go home.”\"},{\"heading\":false,\"text\":\"“Never heard anything so selfish in my life.”\"},{\"heading\":false,\"text\":\"“We’re always the first ones to leave.”\"},{\"heading\":false,\"text\":\"“So are we.”\"},{\"heading\":false,\"text\":\"“Well, we’re almost the last tonight,” said one of the men sheepishly. “The orchestra left half an hour ago.”\"},{\"heading\":false,\"text\":\"In spite of the wives’ agreement that such malevolence was beyond credibility, the dispute ended in a short struggle, and both wives were lifted, kicking, into the night.\"},{\"heading\":false,\"text\":\"As I waited for my hat in the hall the door of the library opened and Jordan Baker and Gatsby came out together. He was saying some last word to her, but the eagerness in his manner tightened abruptly into formality as several people approached him to say goodbye.\"},{\"heading\":false,\"text\":\"Jordan’s party were calling impatiently to her from the porch, but she lingered for a moment to shake hands.\"},{\"heading\":false,\"text\":\"“I’ve just heard the most amazing thing,” she whispered. “How long were we in there?”\"},{\"heading\":false,\"text\":\"“Why, about an hour.”\"},{\"heading\":false,\"text\":\"“It was… simply amazing,” she repeated abstractedly. “But I swore I wouldn’t tell it and here I am tantalizing you.” She yawned gracefully in my face. “Please come and see me… Phone book… Under the name of Mrs. Sigourney Howard… My aunt…” She was hurrying off as she talked—her brown hand waved a jaunty salute as she melted into her party at the door.\"},{\"heading\":false,\"text\":\"Rather ashamed that on my first appearance I had stayed so late, I joined the last of Gatsby’s guests, who were clustered around him. I wanted to explain that I’d hunted for him early in the evening and to apologize for not having known him in the garden.\"},{\"heading\":false,\"text\":\"“Don’t mention it,” he enjoined me eagerly. “Don’t give it another thought, old sport.” The familiar expression held no more familiarity than the hand which reassuringly brushed my shoulder. “And don’t forget we’re going up in the hydroplane tomorrow morning, at nine o’clock.”\"},{\"heading\":false,\"text\":\"Then the butler, behind his shoulder:\"},{\"heading\":false,\"text\":\"“Philadelphia wants you on the phone, sir.”\"},{\"heading\":false,\"text\":\"“All right, in a minute. Tell them I’ll be right there… Good night.”\"},{\"heading\":false,\"text\":\"“Good night.”\"},{\"heading\":false,\"text\":\"“Good night.” He smiled—and suddenly there seemed to be a pleasant significance in having been among the last to go, as if he had desired it all the time. “Good night, old sport… Good night.”\"},{\"heading\":false,\"text\":\"But as I walked down the steps I saw that the evening was not quite over. Fifty feet from the door a dozen headlights illuminated a bizarre and tumultuous scene. In the ditch beside the road, right side up, but violently shorn of one wheel, rested a new coupé which had left Gatsby’s drive not two minutes before. The sharp jut of a wall accounted for the detachment of the wheel, which was now getting considerable attention from half a dozen curious chauffeurs. However, as they had left their cars blocking the road, a harsh, discordant din from those in the rear had been audible for some time, and added to the already violent confusion of the scene.\"},{\"heading\":false,\"text\":\"A man in a long duster had dismounted from the wreck and now stood in the middle of the road, looking from the car to the tyre and from the tyre to the observers in a pleasant, puzzled way.\"},{\"heading\":false,\"text\":\"“See!” he explained. “It went in the ditch.”\"},{\"heading\":false,\"text\":\"The fact was infinitely astonishing to him, and I recognized first the unusual quality of wonder, and then the man—it was the late patron of Gatsby’s library.\"},{\"heading\":false,\"text\":\"“How’d it happen?”\"},{\"heading\":false,\"text\":\"He shrugged his shoulders.\"},{\"heading\":false,\"text\":\"“I know nothing whatever about mechanics,” he said decisively.\"},{\"heading\":false,\"text\":\"“But how did it happen? Did you run into the wall?”\"},{\"heading\":false,\"text\":\"“Don’t ask me,” said Owl Eyes, washing his hands of the whole matter. “I know very little about driving—next to nothing. It happened, and that’s all I know.”\"},{\"heading\":false,\"text\":\"“Well, if you’re a poor driver you oughtn’t to try driving at night.”\"},{\"heading\":false,\"text\":\"“But I wasn’t even trying,” he explained indignantly, “I wasn’t even trying.”\"},{\"heading\":false,\"text\":\"An awed hush fell upon the bystanders.\"},{\"heading\":false,\"text\":\"“Do you want to commit suicide?”\"},{\"heading\":false,\"text\":\"“You’re lucky it was just a wheel! A bad driver and not even trying!”\"},{\"heading\":false,\"text\":\"“You don’t understand,” explained the criminal. “I wasn’t driving. There’s another man in the car.”\"},{\"heading\":false,\"text\":\"The shock that followed this declaration found voice in a sustained “Ah-h-h!” as the door of the coupé swung slowly open. The crowd—it was now a crowd—stepped back involuntarily, and when the door had opened wide there was a ghostly pause. Then, very gradually, part by part, a pale, dangling individual stepped out of the wreck, pawing tentatively at the ground with a large uncertain dancing shoe.\"},{\"heading\":false,\"text\":\"Blinded by the glare of the headlights and confused by the incessant groaning of the horns, the apparition stood swaying for a moment before he perceived the man in the duster.\"},{\"heading\":false,\"text\":\"“Wha’s matter?” he inquired calmly. “Did we run outa gas?”\"},{\"heading\":false,\"text\":\"“Look!”\"},{\"heading\":false,\"text\":\"Half a dozen fingers pointed at the amputated wheel—he stared at it for a moment, and then looked upward as though he suspected that it had dropped from the sky.\"},{\"heading\":false,\"text\":\"“It came off,” someone explained.\"},{\"heading\":false,\"text\":\"He nodded.\"},{\"heading\":false,\"text\":\"“At first I din’ notice we’d stopped.”\"},{\"heading\":false,\"text\":\"A pause. Then, taking a long breath and straightening his shoulders, he remarked in a determined voice:\"},{\"heading\":false,\"text\":\"“Wonder’ff tell me where there’s a gas’line station?”\"},{\"heading\":false,\"text\":\"At least a dozen men, some of them a little better off than he was, explained to him that wheel and car were no longer joined by any physical bond.\"},{\"heading\":false,\"text\":\"“Back out,” he suggested after a moment. “Put her in reverse.”\"},{\"heading\":false,\"text\":\"“But the wheel’s off!”\"},{\"heading\":false,\"text\":\"He hesitated.\"},{\"heading\":false,\"text\":\"“No harm in trying,” he said.\"},{\"heading\":false,\"text\":\"The caterwauling horns had reached a crescendo and I turned away and cut across the lawn toward home. I glanced back once. A wafer of a moon was shining over Gatsby’s house, making the night fine as before, and surviving the laughter and the sound of his still glowing garden. A sudden emptiness seemed to flow now from the windows and the great doors, endowing with complete isolation the figure of the host, who stood on the porch, his hand up in a formal gesture of farewell.\"},{\"heading\":false,\"text\":\"Reading over what I have written so far, I see I have given the impression that the events of three nights several weeks apart were all that absorbed me. On the contrary, they were merely casual events in a crowded summer, and, until much later, they absorbed me infinitely less than my personal affairs.\"},{\"heading\":false,\"text\":\"Most of the time I worked. In the early morning the sun threw my shadow westward as I hurried down the white chasms of lower New York to the Probity Trust. I knew the other clerks and young bond-salesmen by their first names, and lunched with them in dark, crowded restaurants on little pig sausages and mashed potatoes and coffee. I even had a short affair with a girl who lived in Jersey City and worked in the accounting department, but her brother began throwing mean looks in my direction, so when she went on her vacation in July I let it blow quietly away.\"},{\"heading\":false,\"text\":\"I took dinner usually at the Yale Club—for some reason it was the gloomiest event of my day—and then I went upstairs to the library and studied investments and securities for a conscientious hour. There were generally a few rioters around, but they never came into the library, so it was a good place to work. After that, if the night was mellow, I strolled down Madison Avenue past the old Murray Hill Hotel, and over 33rd Street to the Pennsylvania Station.\"},{\"heading\":false,\"text\":\"I began to like New York, the racy, adventurous feel of it at night, and the satisfaction that the constant flicker of men and women and machines gives to the restless eye. I liked to walk up Fifth Avenue and pick out romantic women from the crowd and imagine that in a few minutes I was going to enter into their lives, and no one would ever know or disapprove. Sometimes, in my mind, I followed them to their apartments on the corners of hidden streets, and they turned and smiled back at me before they faded through a door into warm darkness. At the enchanted metropolitan twilight I felt a haunting loneliness sometimes, and felt it in others—poor young clerks who loitered in front of windows waiting until it was time for a solitary restaurant dinner—young clerks in the dusk, wasting the most poignant moments of night and life.\"},{\"heading\":false,\"text\":\"Again at eight o’clock, when the dark lanes of the Forties were lined five deep with throbbing taxicabs, bound for the theatre district, I felt a sinking in my heart. Forms leaned together in the taxis as they waited, and voices sang, and there was laughter from unheard jokes, and lighted cigarettes made unintelligible circles inside. Imagining that I, too, was hurrying towards gaiety and sharing their intimate excitement, I wished them well.\"},{\"heading\":false,\"text\":\"For a while I lost sight of Jordan Baker, and then in midsummer I found her again. At first I was flattered to go places with her, because she was a golf champion, and everyone knew her name. Then it was something more. I wasn’t actually in love, but I felt a sort of tender curiosity. The bored haughty face that she turned to the world concealed something—most affectations conceal something eventually, even though they don’t in the beginning—and one day I found what it was. When we were on a house-party together up in Warwick, she left a borrowed car out in the rain with the top down, and then lied about it—and suddenly I remembered the story about her that had eluded me that night at Daisy’s. At her first big golf tournament there was a row that nearly reached the newspapers—a suggestion that she had moved her ball from a bad lie in the semifinal round. The thing approached the proportions of a scandal—then died away. A caddy retracted his statement, and the only other witness admitted that he might have been mistaken. The incident and the name had remained together in my mind.\"},{\"heading\":false,\"text\":\"Jordan Baker instinctively avoided clever, shrewd men, and now I saw that this was because she felt safer on a plane where any divergence from a code would be thought impossible. She was incurably dishonest. She wasn’t able to endure being at a disadvantage and, given this unwillingness, I suppose she had begun dealing in subterfuges when she was very young in order to keep that cool, insolent smile turned to the world and yet satisfy the demands of her hard, jaunty body.\"},{\"heading\":false,\"text\":\"It made no difference to me. Dishonesty in a woman is a thing you never blame deeply—I was casually sorry, and then I forgot. It was on that same house-party that we had a curious conversation about driving a car. It started because she passed so close to some workmen that our fender flicked a button on one man’s coat.\"},{\"heading\":false,\"text\":\"“You’re a rotten driver,” I protested. “Either you ought to be more careful, or you oughtn’t to drive at all.”\"},{\"heading\":false,\"text\":\"“I am careful.”\"},{\"heading\":false,\"text\":\"“No, you’re not.”\"},{\"heading\":false,\"text\":\"“Well, other people are,” she said lightly.\"},{\"heading\":false,\"text\":\"“What’s that got to do with it?”\"},{\"heading\":false,\"text\":\"“They’ll keep out of my way,” she insisted. “It takes two to make an accident.”\"},{\"heading\":false,\"text\":\"“Suppose you met somebody just as careless as yourself.”\"},{\"heading\":false,\"text\":\"“I hope I never will,” she answered. “I hate careless people. That’s why I like you.”\"},{\"heading\":false,\"text\":\"Her grey, sun-strained eyes stared straight ahead, but she had deliberately shifted our relations, and for a moment I thought I loved her. But I am slow-thinking and full of interior rules that act as brakes on my desires, and I knew that first I had to get myself definitely out of that tangle back home. I’d been writing letters once a week and signing them: “Love, Nick,” and all I could think of was how, when that certain girl played tennis, a faint moustache of perspiration appeared on her upper lip. Nevertheless there was a vague understanding that had to be tactfully broken off before I was free.\"},{\"heading\":false,\"text\":\"Everyone suspects himself of at least one of the cardinal virtues, and this is mine: I am one of the few honest people that I have ever known.\"}]},{\"title\":\"IV\",\"blocks\":[{\"heading\":false,\"text\":\"On Sunday morning while church bells rang in the villages alongshore, the world and its mistress returned to Gatsby’s house and twinkled hilariously on his lawn.\"},{\"heading\":false,\"text\":\"“He’s a bootlegger,” said the young ladies, moving somewhere between his cocktails and his flowers. “One time he killed a man who had found out that he was nephew to Von Hindenburg and second cousin to the devil. Reach me a rose, honey, and pour me a last drop into that there crystal glass.”\"},{\"heading\":false,\"text\":\"Once I wrote down on the empty spaces of a timetable the names of those who came to Gatsby’s house that summer. It is an old timetable now, disintegrating at its folds, and headed “This schedule in effect July 5th, 1922.” But I can still read the grey names, and they will give you a better impression than my generalities of those who accepted Gatsby’s hospitality and paid him the subtle tribute of knowing nothing whatever about him.\"},{\"heading\":false,\"text\":\"From East Egg, then, came the Chester Beckers and the Leeches, and a man named Bunsen, whom I knew at Yale, and Doctor Webster Civet, who was drowned last summer up in Maine. And the Hornbeams and the Willie Voltaires, and a whole clan named Blackbuck, who always gathered in a corner and flipped up their noses like goats at whosoever came near. And the Ismays and the Chrysties (or rather Hubert Auerbach and Mr. Chrystie’s wife), and Edgar Beaver, whose hair, they say, turned cotton-white one winter afternoon for no good reason at all.\"},{\"heading\":false,\"text\":\"Clarence Endive was from East Egg, as I remember. He came only once, in white knickerbockers, and had a fight with a bum named Etty in the garden. From farther out on the Island came the Cheadles and the O. R. P. Schraeders, and the Stonewall Jackson Abrams of Georgia, and the Fishguards and the Ripley Snells. Snell was there three days before he went to the penitentiary, so drunk out on the gravel drive that Mrs. Ulysses Swett’s automobile ran over his right hand. The Dancies came, too, and S. B. Whitebait, who was well over sixty, and Maurice A. Flink, and the Hammerheads, and Beluga the tobacco importer, and Beluga’s girls.\"},{\"heading\":false,\"text\":\"From West Egg came the Poles and the Mulreadys and Cecil Roebuck and Cecil Schoen and Gulick the State senator and Newton Orchid, who controlled Films Par Excellence, and Eckhaust and Clyde Cohen and Don S. Schwartz (the son) and Arthur McCarty, all connected with the movies in one way or another. And the Catlips and the Bembergs and G. Earl Muldoon, brother to that Muldoon who afterward strangled his wife. Da Fontano the promoter came there, and Ed Legros and James B. (“Rot-Gut”) Ferret and the De Jongs and Ernest Lilly—they came to gamble, and when Ferret wandered into the garden it meant he was cleaned out and Associated Traction would have to fluctuate profitably next day.\"},{\"heading\":false,\"text\":\"A man named Klipspringer was there so often that he became known as “the boarder”—I doubt if he had any other home. Of theatrical people there were Gus Waize and Horace O’Donavan and Lester Myer and George Duckweed and Francis Bull. Also from New York were the Chromes and the Backhyssons and the Dennickers and Russel Betty and the Corrigans and the Kellehers and the Dewars and the Scullys and S. W. Belcher and the Smirkes and the young Quinns, divorced now, and Henry L. Palmetto, who killed himself by jumping in front of a subway train in Times Square.\"},{\"heading\":false,\"text\":\"Benny McClenahan arrived always with four girls. They were never quite the same ones in physical person, but they were so identical one with another that it inevitably seemed they had been there before. I have forgotten their names—Jaqueline, I think, or else Consuela, or Gloria or Judy or June, and their last names were either the melodious names of flowers and months or the sterner ones of the great American capitalists whose cousins, if pressed, they would confess themselves to be.\"},{\"heading\":false,\"text\":\"In addition to all these I can remember that Faustina O’Brien came there at least once and the Baedeker girls and young Brewer, who had his nose shot off in the war, and Mr. Albrucksburger and Miss Haag, his fiancée, and Ardita Fitz-Peters and Mr. P. Jewett, once head of the American Legion, and Miss Claudia Hip, with a man reputed to be her chauffeur, and a prince of something, whom we called Duke, and whose name, if I ever knew it, I have forgotten.\"},{\"heading\":false,\"text\":\"All these people came to Gatsby’s house in the summer.\"},{\"heading\":false,\"text\":\"At nine o’clock, one morning late in July, Gatsby’s gorgeous car lurched up the rocky drive to my door and gave out a burst of melody from its three-noted horn.\"},{\"heading\":false,\"text\":\"It was the first time he had called on me, though I had gone to two of his parties, mounted in his hydroplane, and, at his urgent invitation, made frequent use of his beach.\"},{\"heading\":false,\"text\":\"“Good morning, old sport. You’re having lunch with me today and I thought we’d ride up together.”\"},{\"heading\":false,\"text\":\"He was balancing himself on the dashboard of his car with that resourcefulness of movement that is so peculiarly American—that comes, I suppose, with the absence of lifting work in youth and, even more, with the formless grace of our nervous, sporadic games. This quality was continually breaking through his punctilious manner in the shape of restlessness. He was never quite still; there was always a tapping foot somewhere or the impatient opening and closing of a hand.\"},{\"heading\":false,\"text\":\"He saw me looking with admiration at his car.\"},{\"heading\":false,\"text\":\"“It’s pretty, isn’t it, old sport?” He jumped off to give me a better view. “Haven’t you ever seen it before?”\"},{\"heading\":false,\"text\":\"I’d seen it. Everybody had seen it. It was a rich cream colour, bright with nickel, swollen here and there in its monstrous length with triumphant hatboxes and supper-boxes and toolboxes, and terraced with a labyrinth of windshields that mirrored a dozen suns. Sitting down behind many layers of glass in a sort of green leather conservatory, we started to town.\"},{\"heading\":false,\"text\":\"I had talked with him perhaps half a dozen times in the past month and found, to my disappointment, that he had little to say. So my first impression, that he was a person of some undefined consequence, had gradually faded and he had become simply the proprietor of an elaborate roadhouse next door.\"},{\"heading\":false,\"text\":\"And then came that disconcerting ride. We hadn’t reached West Egg village before Gatsby began leaving his elegant sentences unfinished and slapping himself indecisively on the knee of his caramel-coloured suit.\"},{\"heading\":false,\"text\":\"“Look here, old sport,” he broke out surprisingly, “what’s your opinion of me, anyhow?”\"},{\"heading\":false,\"text\":\"A little overwhelmed, I began the generalized evasions which that question deserves.\"},{\"heading\":false,\"text\":\"“Well, I’m going to tell you something about my life,” he interrupted. “I don’t want you to get a wrong idea of me from all these stories you hear.”\"},{\"heading\":false,\"text\":\"So he was aware of the bizarre accusations that flavoured conversation in his halls.\"},{\"heading\":false,\"text\":\"“I’ll tell you God’s truth.” His right hand suddenly ordered divine retribution to stand by. “I am the son of some wealthy people in the Middle West—all dead now. I was brought up in America but educated at Oxford, because all my ancestors have been educated there for many years. It is a family tradition.”\"},{\"heading\":false,\"text\":\"He looked at me sideways—and I knew why Jordan Baker had believed he was lying. He hurried the phrase “educated at Oxford,” or swallowed it, or choked on it, as though it had bothered him before. And with this doubt, his whole statement fell to pieces, and I wondered if there wasn’t something a little sinister about him, after all.\"},{\"heading\":false,\"text\":\"“What part of the Middle West?” I inquired casually.\"},{\"heading\":false,\"text\":\"“San Francisco.”\"},{\"heading\":false,\"text\":\"“I see.”\"},{\"heading\":false,\"text\":\"“My family all died and I came into a good deal of money.”\"},{\"heading\":false,\"text\":\"His voice was solemn, as if the memory of that sudden extinction of a clan still haunted him. For a moment I suspected that he was pulling my leg, but a glance at him convinced me otherwise.\"},{\"heading\":false,\"text\":\"“After that I lived like a young rajah in all the capitals of Europe—Paris, Venice, Rome—collecting jewels, chiefly rubies, hunting big game, painting a little, things for myself only, and trying to forget something very sad that had happened to me long ago.”\"},{\"heading\":false,\"text\":\"With an effort I managed to restrain my incredulous laughter. The very phrases were worn so threadbare that they evoked no image except that of a turbaned “character” leaking sawdust at every pore as he pursued a tiger through the Bois de Boulogne.\"},{\"heading\":false,\"text\":\"“Then came the war, old sport. It was a great relief, and I tried very hard to die, but I seemed to bear an enchanted life. I accepted a commission as first lieutenant when it began. In the Argonne Forest I took the remains of my machine-gun battalion so far forward that there was a half mile gap on either side of us where the infantry couldn’t advance. We stayed there two days and two nights, a hundred and thirty men with sixteen Lewis guns, and when the infantry came up at last they found the insignia of three German divisions among the piles of dead. I was promoted to be a major, and every Allied government gave me a decoration—even Montenegro, little Montenegro down on the Adriatic Sea!”\"},{\"heading\":false,\"text\":\"Little Montenegro! He lifted up the words and nodded at them—with his smile. The smile comprehended Montenegro’s troubled history and sympathized with the brave struggles of the Montenegrin people. It appreciated fully the chain of national circumstances which had elicited this tribute from Montenegro’s warm little heart. My incredulity was submerged in fascination now; it was like skimming hastily through a dozen magazines.\"},{\"heading\":false,\"text\":\"He reached in his pocket, and a piece of metal, slung on a ribbon, fell into my palm.\"},{\"heading\":false,\"text\":\"“That’s the one from Montenegro.”\"},{\"heading\":false,\"text\":\"To my astonishment, the thing had an authentic look. “Orderi di Danilo,” ran the circular legend, “Montenegro, Nicolas Rex.”\"},{\"heading\":false,\"text\":\"“Turn it.”\"},{\"heading\":false,\"text\":\"“Major Jay Gatsby,” I read, “For Valour Extraordinary.”\"},{\"heading\":false,\"text\":\"“Here’s another thing I always carry. A souvenir of Oxford days. It was taken in Trinity Quad—the man on my left is now the Earl of Doncaster.”\"},{\"heading\":false,\"text\":\"It was a photograph of half a dozen young men in blazers loafing in an archway through which were visible a host of spires. There was Gatsby, looking a little, not much, younger—with a cricket bat in his hand.\"},{\"heading\":false,\"text\":\"Then it was all true. I saw the skins of tigers flaming in his palace on the Grand Canal; I saw him opening a chest of rubies to ease, with their crimson-lighted depths, the gnawings of his broken heart.\"},{\"heading\":false,\"text\":\"“I’m going to make a big request of you today,” he said, pocketing his souvenirs with satisfaction, “so I thought you ought to know something about me. I didn’t want you to think I was just some nobody. You see, I usually find myself among strangers because I drift here and there trying to forget the sad things that happened to me.” He hesitated. “You’ll hear about it this afternoon.”\"},{\"heading\":false,\"text\":\"“At lunch?”\"},{\"heading\":false,\"text\":\"“No, this afternoon. I happened to find out that you’re taking Miss Baker to tea.”\"},{\"heading\":false,\"text\":\"“Do you mean you’re in love with Miss Baker?”\"},{\"heading\":false,\"text\":\"“No, old sport, I’m not. But Miss Baker has kindly consented to speak to you about this matter.”\"},{\"heading\":false,\"text\":\"I hadn’t the faintest idea what “this matter” was, but I was more annoyed than interested. I hadn’t asked Jordan to tea in order to discuss Mr. Jay Gatsby. I was sure the request would be something utterly fantastic, and for a moment I was sorry I’d ever set foot upon his overpopulated lawn.\"},{\"heading\":false,\"text\":\"He wouldn’t say another word. His correctness grew on him as we neared the city. We passed Port Roosevelt, where there was a glimpse of red-belted oceangoing ships, and sped along a cobbled slum lined with the dark, undeserted saloons of the faded-gilt nineteen-hundreds. Then the valley of ashes opened out on both sides of us, and I had a glimpse of Mrs. Wilson straining at the garage pump with panting vitality as we went by.\"},{\"heading\":false,\"text\":\"With fenders spread like wings we scattered light through half Astoria—only half, for as we twisted among the pillars of the elevated I heard the familiar “jug-jug-spat!” of a motorcycle, and a frantic policeman rode alongside.\"},{\"heading\":false,\"text\":\"“All right, old sport,” called Gatsby. We slowed down. Taking a white card from his wallet, he waved it before the man’s eyes.\"},{\"heading\":false,\"text\":\"“Right you are,” agreed the policeman, tipping his cap. “Know you next time, Mr. Gatsby. Excuse me!”\"},{\"heading\":false,\"text\":\"“What was that?” I inquired. “The picture of Oxford?”\"},{\"heading\":false,\"text\":\"“I was able to do the commissioner a favour once, and he sends me a Christmas card every year.”\"},{\"heading\":false,\"text\":\"Over the great bridge, with the sunlight through the girders making a constant flicker upon the moving cars, with the city rising up across the river in white heaps and sugar lumps all built with a wish out of nonolfactory money. The city seen from the Queensboro Bridge is always the city seen for the first time, in its first wild promise of all the mystery and the beauty in the world.\"},{\"heading\":false,\"text\":\"A dead man passed us in a hearse heaped with blooms, followed by two carriages with drawn blinds, and by more cheerful carriages for friends. The friends looked out at us with the tragic eyes and short upper lips of southeastern Europe, and I was glad that the sight of Gatsby’s splendid car was included in their sombre holiday. As we crossed Blackwell’s Island a limousine passed us, driven by a white chauffeur, in which sat three modish negroes, two bucks and a girl. I laughed aloud as the yolks of their eyeballs rolled toward us in haughty rivalry.\"},{\"heading\":false,\"text\":\"“Anything can happen now that we’ve slid over this bridge,” I thought; “anything at all…”\"},{\"heading\":false,\"text\":\"Even Gatsby could happen, without any particular wonder.\"},{\"heading\":false,\"text\":\"Roaring noon. In a well-fanned Forty-second Street cellar I met Gatsby for lunch. Blinking away the brightness of the street outside, my eyes picked him out obscurely in the anteroom, talking to another man.\"},{\"heading\":false,\"text\":\"“Mr. Carraway, this is my friend Mr. Wolfshiem.”\"},{\"heading\":false,\"text\":\"A small, flat-nosed Jew raised his large head and regarded me with two fine growths of hair which luxuriated in either nostril. After a moment I discovered his tiny eyes in the half-darkness.\"},{\"heading\":false,\"text\":\"“—So I took one look at him,” said Mr. Wolfshiem, shaking my hand earnestly, “and what do you think I did?”\"},{\"heading\":false,\"text\":\"“What?” I inquired politely.\"},{\"heading\":false,\"text\":\"But evidently he was not addressing me, for he dropped my hand and covered Gatsby with his expressive nose.\"},{\"heading\":false,\"text\":\"“I handed the money to Katspaugh and I said: ‘All right, Katspaugh, don’t pay him a penny till he shuts his mouth.’ He shut it then and there.”\"},{\"heading\":false,\"text\":\"Gatsby took an arm of each of us and moved forward into the restaurant, whereupon Mr. Wolfshiem swallowed a new sentence he was starting and lapsed into a somnambulatory abstraction.\"},{\"heading\":false,\"text\":\"“Highballs?” asked the head waiter.\"},{\"heading\":false,\"text\":\"“This is a nice restaurant here,” said Mr. Wolfshiem, looking at the presbyterian nymphs on the ceiling. “But I like across the street better!”\"},{\"heading\":false,\"text\":\"“Yes, highballs,” agreed Gatsby, and then to Mr. Wolfshiem: “It’s too hot over there.”\"},{\"heading\":false,\"text\":\"“Hot and small—yes,” said Mr. Wolfshiem, “but full of memories.”\"},{\"heading\":false,\"text\":\"“What place is that?” I asked.\"},{\"heading\":false,\"text\":\"“The old Metropole.”\"},{\"heading\":false,\"text\":\"“The old Metropole,” brooded Mr. Wolfshiem gloomily. “Filled with faces dead and gone. Filled with friends gone now forever. I can’t forget so long as I live the night they shot Rosy Rosenthal there. It was six of us at the table, and Rosy had eat and drunk a lot all evening. When it was almost morning the waiter came up to him with a funny look and says somebody wants to speak to him outside. ‘All right,’ says Rosy, and begins to get up, and I pulled him down in his chair.\"},{\"heading\":false,\"text\":\"“ ‘Let the bastards come in here if they want you, Rosy, but don’t you, so help me, move outside this room.’\"},{\"heading\":false,\"text\":\"“It was four o’clock in the morning then, and if we’d of raised the blinds we’d of seen daylight.”\"},{\"heading\":false,\"text\":\"“Did he go?” I asked innocently.\"},{\"heading\":false,\"text\":\"“Sure he went.” Mr. Wolfshiem’s nose flashed at me indignantly. “He turned around in the door and says: ‘Don’t let that waiter take away my coffee!’ Then he went out on the sidewalk, and they shot him three times in his full belly and drove away.”\"},{\"heading\":false,\"text\":\"“Four of them were electrocuted,” I said, remembering.\"},{\"heading\":false,\"text\":\"“Five, with Becker.” His nostrils turned to me in an interested way. “I understand you’re looking for a business gonnegtion.”\"},{\"heading\":false,\"text\":\"The juxtaposition of these two remarks was startling. Gatsby answered for me:\"},{\"heading\":false,\"text\":\"“Oh, no,” he exclaimed, “this isn’t the man.”\"},{\"heading\":false,\"text\":\"“No?” Mr. Wolfshiem seemed disappointed.\"},{\"heading\":false,\"text\":\"“This is just a friend. I told you we’d talk about that some other time.”\"},{\"heading\":false,\"text\":\"“I beg your pardon,” said Mr. Wolfshiem, “I had a wrong man.”\"},{\"heading\":false,\"text\":\"A succulent hash arrived, and Mr. Wolfshiem, forgetting the more sentimental atmosphere of the old Metropole, began to eat with ferocious delicacy. His eyes, meanwhile, roved very slowly all around the room—he completed the arc by turning to inspect the people directly behind. I think that, except for my presence, he would have taken one short glance beneath our own table.\"},{\"heading\":false,\"text\":\"“Look here, old sport,” said Gatsby, leaning toward me, “I’m afraid I made you a little angry this morning in the car.”\"},{\"heading\":false,\"text\":\"There was the smile again, but this time I held out against it.\"},{\"heading\":false,\"text\":\"“I don’t like mysteries,” I answered, “and I don’t understand why you won’t come out frankly and tell me what you want. Why has it all got to come through Miss Baker?”\"},{\"heading\":false,\"text\":\"“Oh, it’s nothing underhand,” he assured me. “Miss Baker’s a great sportswoman, you know, and she’d never do anything that wasn’t all right.”\"},{\"heading\":false,\"text\":\"Suddenly he looked at his watch, jumped up, and hurried from the room, leaving me with Mr. Wolfshiem at the table.\"},{\"heading\":false,\"text\":\"“He has to telephone,” said Mr. Wolfshiem, following him with his eyes. “Fine fellow, isn’t he? Handsome to look at and a perfect gentleman.”\"},{\"heading\":false,\"text\":\"“Yes.”\"},{\"heading\":false,\"text\":\"“He’s an Oggsford man.”\"},{\"heading\":false,\"text\":\"“Oh!”\"},{\"heading\":false,\"text\":\"“He went to Oggsford College in England. You know Oggsford College?”\"},{\"heading\":false,\"text\":\"“I’ve heard of it.”\"},{\"heading\":false,\"text\":\"“It’s one of the most famous colleges in the world.”\"},{\"heading\":false,\"text\":\"“Have you known Gatsby for a long time?” I inquired.\"},{\"heading\":false,\"text\":\"“Several years,” he answered in a gratified way. “I made the pleasure of his acquaintance just after the war. But I knew I had discovered a man of fine breeding after I talked with him an hour. I said to myself: ‘There’s the kind of man you’d like to take home and introduce to your mother and sister.’ ” He paused. “I see you’re looking at my cuff buttons.”\"},{\"heading\":false,\"text\":\"I hadn’t been looking at them, but I did now. They were composed of oddly familiar pieces of ivory.\"},{\"heading\":false,\"text\":\"“Finest specimens of human molars,” he informed me.\"},{\"heading\":false,\"text\":\"“Well!” I inspected them. “That’s a very interesting idea.”\"},{\"heading\":false,\"text\":\"“Yeah.” He flipped his sleeves up under his coat. “Yeah, Gatsby’s very careful about women. He would never so much as look at a friend’s wife.”\"},{\"heading\":false,\"text\":\"When the subject of this instinctive trust returned to the table and sat down Mr. Wolfshiem drank his coffee with a jerk and got to his feet.\"},{\"heading\":false,\"text\":\"“I have enjoyed my lunch,” he said, “and I’m going to run off from you two young men before I outstay my welcome.”\"},{\"heading\":false,\"text\":\"“Don’t hurry Meyer,” said Gatsby, without enthusiasm. Mr. Wolfshiem raised his hand in a sort of benediction.\"},{\"heading\":false,\"text\":\"“You’re very polite, but I belong to another generation,” he announced solemnly. “You sit here and discuss your sports and your young ladies and your—” He supplied an imaginary noun with another wave of his hand. “As for me, I am fifty years old, and I won’t impose myself on you any longer.”\"},{\"heading\":false,\"text\":\"As he shook hands and turned away his tragic nose was trembling. I wondered if I had said anything to offend him.\"},{\"heading\":false,\"text\":\"“He becomes very sentimental sometimes,” explained Gatsby. “This is one of his sentimental days. He’s quite a character around New York—a denizen of Broadway.”\"},{\"heading\":false,\"text\":\"“Who is he, anyhow, an actor?”\"},{\"heading\":false,\"text\":\"“No.”\"},{\"heading\":false,\"text\":\"“A dentist?”\"},{\"heading\":false,\"text\":\"“Meyer Wolfshiem? No, he’s a gambler.” Gatsby hesitated, then added, coolly: “He’s the man who fixed the World’s Series back in 1919.”\"},{\"heading\":false,\"text\":\"“Fixed the World’s Series?” I repeated.\"},{\"heading\":false,\"text\":\"The idea staggered me. I remembered, of course, that the World’s Series had been fixed in 1919, but if I had thought of it at all I would have thought of it as a thing that merely happened, the end of some inevitable chain. It never occurred to me that one man could start to play with the faith of fifty million people—with the single-mindedness of a burglar blowing a safe.\"},{\"heading\":false,\"text\":\"“How did he happen to do that?” I asked after a minute.\"},{\"heading\":false,\"text\":\"“He just saw the opportunity.”\"},{\"heading\":false,\"text\":\"“Why isn’t he in jail?”\"},{\"heading\":false,\"text\":\"“They can’t get him, old sport. He’s a smart man.”\"},{\"heading\":false,\"text\":\"I insisted on paying the check. As the waiter brought my change I caught sight of Tom Buchanan across the crowded room.\"},{\"heading\":false,\"text\":\"“Come along with me for a minute,” I said; “I’ve got to say hello to someone.”\"},{\"heading\":false,\"text\":\"When he saw us Tom jumped up and took half a dozen steps in our direction.\"},{\"heading\":false,\"text\":\"“Where’ve you been?” he demanded eagerly. “Daisy’s furious because you haven’t called up.”\"},{\"heading\":false,\"text\":\"“This is Mr. Gatsby, Mr. Buchanan.”\"},{\"heading\":false,\"text\":\"They shook hands briefly, and a strained, unfamiliar look of embarrassment came over Gatsby’s face.\"},{\"heading\":false,\"text\":\"“How’ve you been, anyhow?” demanded Tom of me. “How’d you happen to come up this far to eat?”\"},{\"heading\":false,\"text\":\"“I’ve been having lunch with Mr. Gatsby.”\"},{\"heading\":false,\"text\":\"I turned toward Mr. Gatsby, but he was no longer there.\"},{\"heading\":false,\"text\":\"One October day in nineteen-seventeen—\"},{\"heading\":false,\"text\":\"(said Jordan Baker that afternoon, sitting up very straight on a straight chair in the tea-garden at the Plaza Hotel)\"},{\"heading\":false,\"text\":\"—I was walking along from one place to another, half on the sidewalks and half on the lawns. I was happier on the lawns because I had on shoes from England with rubber knobs on the soles that bit into the soft ground. I had on a new plaid skirt also that blew a little in the wind, and whenever this happened the red, white, and blue banners in front of all the houses stretched out stiff and said tut-tut-tut-tut, in a disapproving way.\"},{\"heading\":false,\"text\":\"The largest of the banners and the largest of the lawns belonged to Daisy Fay’s house. She was just eighteen, two years older than me, and by far the most popular of all the young girls in Louisville. She dressed in white, and had a little white roadster, and all day long the telephone rang in her house and excited young officers from Camp Taylor demanded the privilege of monopolizing her that night. “Anyways, for an hour!”\"},{\"heading\":false,\"text\":\"When I came opposite her house that morning her white roadster was beside the kerb, and she was sitting in it with a lieutenant I had never seen before. They were so engrossed in each other that she didn’t see me until I was five feet away.\"},{\"heading\":false,\"text\":\"“Hello, Jordan,” she called unexpectedly. “Please come here.”\"},{\"heading\":false,\"text\":\"I was flattered that she wanted to speak to me, because of all the older girls I admired her most. She asked me if I was going to the Red Cross to make bandages. I was. Well, then, would I tell them that she couldn’t come that day? The officer looked at Daisy while she was speaking, in a way that every young girl wants to be looked at sometime, and because it seemed romantic to me I have remembered the incident ever since. His name was Jay Gatsby, and I didn’t lay eyes on him again for over four years—even after I’d met him on Long Island I didn’t realize it was the same man.\"},{\"heading\":false,\"text\":\"That was nineteen-seventeen. By the next year I had a few beaux myself, and I began to play in tournaments, so I didn’t see Daisy very often. She went with a slightly older crowd—when she went with anyone at all. Wild rumours were circulating about her—how her mother had found her packing her bag one winter night to go to New York and say goodbye to a soldier who was going overseas. She was effectually prevented, but she wasn’t on speaking terms with her family for several weeks. After that she didn’t play around with the soldiers any more, but only with a few flat-footed, shortsighted young men in town, who couldn’t get into the army at all.\"},{\"heading\":false,\"text\":\"By the next autumn she was gay again, gay as ever. She had a début after the armistice, and in February she was presumably engaged to a man from New Orleans. In June she married Tom Buchanan of Chicago, with more pomp and circumstance than Louisville ever knew before. He came down with a hundred people in four private cars, and hired a whole floor of the Muhlbach Hotel, and the day before the wedding he gave her a string of pearls valued at three hundred and fifty thousand dollars.\"},{\"heading\":false,\"text\":\"I was a bridesmaid. I came into her room half an hour before the bridal dinner, and found her lying on her bed as lovely as the June night in her flowered dress—and as drunk as a monkey. She had a bottle of Sauterne in one hand and a letter in the other.\"},{\"heading\":false,\"text\":\"“ ’Gratulate me,” she muttered. “Never had a drink before, but oh how I do enjoy it.”\"},{\"heading\":false,\"text\":\"“What’s the matter, Daisy?”\"},{\"heading\":false,\"text\":\"I was scared, I can tell you; I’d never seen a girl like that before.\"},{\"heading\":false,\"text\":\"“Here, dearies.” She groped around in a wastebasket she had with her on the bed and pulled out the string of pearls. “Take ’em downstairs and give ’em back to whoever they belong to. Tell ’em all Daisy’s change’ her mine. Say: ‘Daisy’s change’ her mine!’ ”\"},{\"heading\":false,\"text\":\"She began to cry—she cried and cried. I rushed out and found her mother’s maid, and we locked the door and got her into a cold bath. She wouldn’t let go of the letter. She took it into the tub with her and squeezed it up in a wet ball, and only let me leave it in the soap-dish when she saw that it was coming to pieces like snow.\"},{\"heading\":false,\"text\":\"But she didn’t say another word. We gave her spirits of ammonia and put ice on her forehead and hooked her back into her dress, and half an hour later, when we walked out of the room, the pearls were around her neck and the incident was over. Next day at five o’clock she married Tom Buchanan without so much as a shiver, and started off on a three months’ trip to the South Seas.\"},{\"heading\":false,\"text\":\"I saw them in Santa Barbara when they came back, and I thought I’d never seen a girl so mad about her husband. If he left the room for a minute she’d look around uneasily, and say: “Where’s Tom gone?” and wear the most abstracted expression until she saw him coming in the door. She used to sit on the sand with his head in her lap by the hour, rubbing her fingers over his eyes and looking at him with unfathomable delight. It was touching to see them together—it made you laugh in a hushed, fascinated way. That was in August. A week after I left Santa Barbara Tom ran into a wagon on the Ventura road one night, and ripped a front wheel off his car. The girl who was with him got into the papers, too, because her arm was broken—she was one of the chambermaids in the Santa Barbara Hotel.\"},{\"heading\":false,\"text\":\"The next April Daisy had her little girl, and they went to France for a year. I saw them one spring in Cannes, and later in Deauville, and then they came back to Chicago to settle down. Daisy was popular in Chicago, as you know. They moved with a fast crowd, all of them young and rich and wild, but she came out with an absolutely perfect reputation. Perhaps because she doesn’t drink. It’s a great advantage not to drink among hard-drinking people. You can hold your tongue and, moreover, you can time any little irregularity of your own so that everybody else is so blind that they don’t see or care. Perhaps Daisy never went in for amour at all—and yet there’s something in that voice of hers…\"},{\"heading\":false,\"text\":\"Well, about six weeks ago, she heard the name Gatsby for the first time in years. It was when I asked you—do you remember?—if you knew Gatsby in West Egg. After you had gone home she came into my room and woke me up, and said: “What Gatsby?” and when I described him—I was half asleep—she said in the strangest voice that it must be the man she used to know. It wasn’t until then that I connected this Gatsby with the officer in her white car.\"},{\"heading\":false,\"text\":\"When Jordan Baker had finished telling all this we had left the Plaza for half an hour and were driving in a victoria through Central Park. The sun had gone down behind the tall apartments of the movie stars in the West Fifties, and the clear voices of children, already gathered like crickets on the grass, rose through the hot twilight:\"},{\"heading\":false,\"text\":\"“I’m the Sheik of Araby.\\n\\nYour love belongs to me.\\n\\nAt night when you’re asleep\\n\\nInto your tent I’ll creep—”\"},{\"heading\":false,\"text\":\"“It was a strange coincidence,” I said.\"},{\"heading\":false,\"text\":\"“But it wasn’t a coincidence at all.”\"},{\"heading\":false,\"text\":\"“Why not?”\"},{\"heading\":false,\"text\":\"“Gatsby bought that house so that Daisy would be just across the bay.”\"},{\"heading\":false,\"text\":\"Then it had not been merely the stars to which he had aspired on that June night. He came alive to me, delivered suddenly from the womb of his purposeless splendour.\"},{\"heading\":false,\"text\":\"“He wants to know,” continued Jordan, “if you’ll invite Daisy to your house some afternoon and then let him come over.”\"},{\"heading\":false,\"text\":\"The modesty of the demand shook me. He had waited five years and bought a mansion where he dispensed starlight to casual moths—so that he could “come over” some afternoon to a stranger’s garden.\"},{\"heading\":false,\"text\":\"“Did I have to know all this before he could ask such a little thing?”\"},{\"heading\":false,\"text\":\"“He’s afraid, he’s waited so long. He thought you might be offended. You see, he’s regular tough underneath it all.”\"},{\"heading\":false,\"text\":\"Something worried me.\"},{\"heading\":false,\"text\":\"“Why didn’t he ask you to arrange a meeting?”\"},{\"heading\":false,\"text\":\"“He wants her to see his house,” she explained. “And your house is right next door.”\"},{\"heading\":false,\"text\":\"“Oh!”\"},{\"heading\":false,\"text\":\"“I think he half expected her to wander into one of his parties, some night,” went on Jordan, “but she never did. Then he began asking people casually if they knew her, and I was the first one he found. It was that night he sent for me at his dance, and you should have heard the elaborate way he worked up to it. Of course, I immediately suggested a luncheon in New York—and I thought he’d go mad:\"},{\"heading\":false,\"text\":\"“ ‘I don’t want to do anything out of the way!’ he kept saying. ‘I want to see her right next door.’\"},{\"heading\":false,\"text\":\"“When I said you were a particular friend of Tom’s, he started to abandon the whole idea. He doesn’t know very much about Tom, though he says he’s read a Chicago paper for years just on the chance of catching a glimpse of Daisy’s name.”\"},{\"heading\":false,\"text\":\"It was dark now, and as we dipped under a little bridge I put my arm around Jordan’s golden shoulder and drew her toward me and asked her to dinner. Suddenly I wasn’t thinking of Daisy and Gatsby any more, but of this clean, hard, limited person, who dealt in universal scepticism, and who leaned back jauntily just within the circle of my arm. A phrase began to beat in my ears with a sort of heady excitement: “There are only the pursued, the pursuing, the busy, and the tired.”\"},{\"heading\":false,\"text\":\"“And Daisy ought to have something in her life,” murmured Jordan to me.\"},{\"heading\":false,\"text\":\"“Does she want to see Gatsby?”\"},{\"heading\":false,\"text\":\"“She’s not to know about it. Gatsby doesn’t want her to know. You’re just supposed to invite her to tea.”\"},{\"heading\":false,\"text\":\"We passed a barrier of dark trees, and then the façade of Fifty-Ninth Street, a block of delicate pale light, beamed down into the park. Unlike Gatsby and Tom Buchanan, I had no girl whose disembodied face floated along the dark cornices and blinding signs, and so I drew up the girl beside me, tightening my arms. Her wan, scornful mouth smiled, and so I drew her up again closer, this time to my face.\"}]},{\"title\":\"V\",\"blocks\":[{\"heading\":false,\"text\":\"When I came home to West Egg that night I was afraid for a moment that my house was on fire. Two o’clock and the whole corner of the peninsula was blazing with light, which fell unreal on the shrubbery and made thin elongating glints upon the roadside wires. Turning a corner, I saw that it was Gatsby’s house, lit from tower to cellar.\"},{\"heading\":false,\"text\":\"At first I thought it was another party, a wild rout that had resolved itself into “hide-and-go-seek” or “sardines-in-the-box” with all the house thrown open to the game. But there wasn’t a sound. Only wind in the trees, which blew the wires and made the lights go off and on again as if the house had winked into the darkness. As my taxi groaned away I saw Gatsby walking toward me across his lawn.\"},{\"heading\":false,\"text\":\"“Your place looks like the World’s Fair,” I said.\"},{\"heading\":false,\"text\":\"“Does it?” He turned his eyes toward it absently. “I have been glancing into some of the rooms. Let’s go to Coney Island, old sport. In my car.”\"},{\"heading\":false,\"text\":\"“It’s too late.”\"},{\"heading\":false,\"text\":\"“Well, suppose we take a plunge in the swimming pool? I haven’t made use of it all summer.”\"},{\"heading\":false,\"text\":\"“I’ve got to go to bed.”\"},{\"heading\":false,\"text\":\"“All right.”\"},{\"heading\":false,\"text\":\"He waited, looking at me with suppressed eagerness.\"},{\"heading\":false,\"text\":\"“I talked with Miss Baker,” I said after a moment. “I’m going to call up Daisy tomorrow and invite her over here to tea.”\"},{\"heading\":false,\"text\":\"“Oh, that’s all right,” he said carelessly. “I don’t want to put you to any trouble.”\"},{\"heading\":false,\"text\":\"“What day would suit you?”\"},{\"heading\":false,\"text\":\"“What day would suit you?” he corrected me quickly. “I don’t want to put you to any trouble, you see.”\"},{\"heading\":false,\"text\":\"“How about the day after tomorrow?”\"},{\"heading\":false,\"text\":\"He considered for a moment. Then, with reluctance: “I want to get the grass cut,” he said.\"},{\"heading\":false,\"text\":\"We both looked down at the grass—there was a sharp line where my ragged lawn ended and the darker, well-kept expanse of his began. I suspected that he meant my grass.\"},{\"heading\":false,\"text\":\"“There’s another little thing,” he said uncertainly, and hesitated.\"},{\"heading\":false,\"text\":\"“Would you rather put it off for a few days?” I asked.\"},{\"heading\":false,\"text\":\"“Oh, it isn’t about that. At least—” He fumbled with a series of beginnings. “Why, I thought—why, look here, old sport, you don’t make much money, do you?”\"},{\"heading\":false,\"text\":\"“Not very much.”\"},{\"heading\":false,\"text\":\"This seemed to reassure him and he continued more confidently.\"},{\"heading\":false,\"text\":\"“I thought you didn’t, if you’ll pardon my—you see, I carry on a little business on the side, a sort of side line, you understand. And I thought that if you don’t make very much—You’re selling bonds, aren’t you, old sport?”\"},{\"heading\":false,\"text\":\"“Trying to.”\"},{\"heading\":false,\"text\":\"“Well, this would interest you. It wouldn’t take up much of your time and you might pick up a nice bit of money. It happens to be a rather confidential sort of thing.”\"},{\"heading\":false,\"text\":\"I realize now that under different circumstances that conversation might have been one of the crises of my life. But, because the offer was obviously and tactlessly for a service to be rendered, I had no choice except to cut him off there.\"},{\"heading\":false,\"text\":\"“I’ve got my hands full,” I said. “I’m much obliged but I couldn’t take on any more work.”\"},{\"heading\":false,\"text\":\"“You wouldn’t have to do any business with Wolfshiem.” Evidently he thought that I was shying away from the “gonnegtion” mentioned at lunch, but I assured him he was wrong. He waited a moment longer, hoping I’d begin a conversation, but I was too absorbed to be responsive, so he went unwillingly home.\"},{\"heading\":false,\"text\":\"The evening had made me lightheaded and happy; I think I walked into a deep sleep as I entered my front door. So I don’t know whether or not Gatsby went to Coney Island, or for how many hours he “glanced into rooms” while his house blazed gaudily on. I called up Daisy from the office next morning, and invited her to come to tea.\"},{\"heading\":false,\"text\":\"“Don’t bring Tom,” I warned her.\"},{\"heading\":false,\"text\":\"“What?”\"},{\"heading\":false,\"text\":\"“Don’t bring Tom.”\"},{\"heading\":false,\"text\":\"“Who is ‘Tom’?” she asked innocently.\"},{\"heading\":false,\"text\":\"The day agreed upon was pouring rain. At eleven o’clock a man in a raincoat, dragging a lawn-mower, tapped at my front door and said that Mr. Gatsby had sent him over to cut my grass. This reminded me that I had forgotten to tell my Finn to come back, so I drove into West Egg Village to search for her among soggy whitewashed alleys and to buy some cups and lemons and flowers.\"},{\"heading\":false,\"text\":\"The flowers were unnecessary, for at two o’clock a greenhouse arrived from Gatsby’s, with innumerable receptacles to contain it. An hour later the front door opened nervously, and Gatsby in a white flannel suit, silver shirt, and gold-coloured tie, hurried in. He was pale, and there were dark signs of sleeplessness beneath his eyes.\"},{\"heading\":false,\"text\":\"“Is everything all right?” he asked immediately.\"},{\"heading\":false,\"text\":\"“The grass looks fine, if that’s what you mean.”\"},{\"heading\":false,\"text\":\"“What grass?” he inquired blankly. “Oh, the grass in the yard.” He looked out the window at it, but, judging from his expression, I don’t believe he saw a thing.\"},{\"heading\":false,\"text\":\"“Looks very good,” he remarked vaguely. “One of the papers said they thought the rain would stop about four. I think it was The Journal. Have you got everything you need in the shape of—of tea?”\"},{\"heading\":false,\"text\":\"I took him into the pantry, where he looked a little reproachfully at the Finn. Together we scrutinized the twelve lemon cakes from the delicatessen shop.\"},{\"heading\":false,\"text\":\"“Will they do?” I asked.\"},{\"heading\":false,\"text\":\"“Of course, of course! They’re fine!” and he added hollowly, “… old sport.”\"},{\"heading\":false,\"text\":\"The rain cooled about half-past three to a damp mist, through which occasional thin drops swam like dew. Gatsby looked with vacant eyes through a copy of Clay’s Economics, starting at the Finnish tread that shook the kitchen floor, and peering towards the bleared windows from time to time as if a series of invisible but alarming happenings were taking place outside. Finally he got up and informed me, in an uncertain voice, that he was going home.\"},{\"heading\":false,\"text\":\"“Why’s that?”\"},{\"heading\":false,\"text\":\"“Nobody’s coming to tea. It’s too late!” He looked at his watch as if there was some pressing demand on his time elsewhere. “I can’t wait all day.”\"},{\"heading\":false,\"text\":\"“Don’t be silly; it’s just two minutes to four.”\"},{\"heading\":false,\"text\":\"He sat down miserably, as if I had pushed him, and simultaneously there was the sound of a motor turning into my lane. We both jumped up, and, a little harrowed myself, I went out into the yard.\"},{\"heading\":false,\"text\":\"Under the dripping bare lilac-trees a large open car was coming up the drive. It stopped. Daisy’s face, tipped sideways beneath a three-cornered lavender hat, looked out at me with a bright ecstatic smile.\"},{\"heading\":false,\"text\":\"“Is this absolutely where you live, my dearest one?”\"},{\"heading\":false,\"text\":\"The exhilarating ripple of her voice was a wild tonic in the rain. I had to follow the sound of it for a moment, up and down, with my ear alone, before any words came through. A damp streak of hair lay like a dash of blue paint across her cheek, and her hand was wet with glistening drops as I took it to help her from the car.\"},{\"heading\":false,\"text\":\"“Are you in love with me,” she said low in my ear, “or why did I have to come alone?”\"},{\"heading\":false,\"text\":\"“That’s the secret of Castle Rackrent. Tell your chauffeur to go far away and spend an hour.”\"},{\"heading\":false,\"text\":\"“Come back in an hour, Ferdie.” Then in a grave murmur: “His name is Ferdie.”\"},{\"heading\":false,\"text\":\"“Does the gasoline affect his nose?”\"},{\"heading\":false,\"text\":\"“I don’t think so,” she said innocently. “Why?”\"},{\"heading\":false,\"text\":\"We went in. To my overwhelming surprise the living-room was deserted.\"},{\"heading\":false,\"text\":\"“Well, that’s funny,” I exclaimed.\"},{\"heading\":false,\"text\":\"“What’s funny?”\"},{\"heading\":false,\"text\":\"She turned her head as there was a light dignified knocking at the front door. I went out and opened it. Gatsby, pale as death, with his hands plunged like weights in his coat pockets, was standing in a puddle of water glaring tragically into my eyes.\"},{\"heading\":false,\"text\":\"With his hands still in his coat pockets he stalked by me into the hall, turned sharply as if he were on a wire, and disappeared into the living-room. It wasn’t a bit funny. Aware of the loud beating of my own heart I pulled the door to against the increasing rain.\"},{\"heading\":false,\"text\":\"For half a minute there wasn’t a sound. Then from the living-room I heard a sort of choking murmur and part of a laugh, followed by Daisy’s voice on a clear artificial note:\"},{\"heading\":false,\"text\":\"“I certainly am awfully glad to see you again.”\"},{\"heading\":false,\"text\":\"A pause; it endured horribly. I had nothing to do in the hall, so I went into the room.\"},{\"heading\":false,\"text\":\"Gatsby, his hands still in his pockets, was reclining against the mantelpiece in a strained counterfeit of perfect ease, even of boredom. His head leaned back so far that it rested against the face of a defunct mantelpiece clock, and from this position his distraught eyes stared down at Daisy, who was sitting, frightened but graceful, on the edge of a stiff chair.\"},{\"heading\":false,\"text\":\"“We’ve met before,” muttered Gatsby. His eyes glanced momentarily at me, and his lips parted with an abortive attempt at a laugh. Luckily the clock took this moment to tilt dangerously at the pressure of his head, whereupon he turned and caught it with trembling fingers, and set it back in place. Then he sat down, rigidly, his elbow on the arm of the sofa and his chin in his hand.\"},{\"heading\":false,\"text\":\"“I’m sorry about the clock,” he said.\"},{\"heading\":false,\"text\":\"My own face had now assumed a deep tropical burn. I couldn’t muster up a single commonplace out of the thousand in my head.\"},{\"heading\":false,\"text\":\"“It’s an old clock,” I told them idiotically.\"},{\"heading\":false,\"text\":\"I think we all believed for a moment that it had smashed in pieces on the floor.\"},{\"heading\":false,\"text\":\"“We haven’t met for many years,” said Daisy, her voice as matter-of-fact as it could ever be.\"},{\"heading\":false,\"text\":\"“Five years next November.”\"},{\"heading\":false,\"text\":\"The automatic quality of Gatsby’s answer set us all back at least another minute. I had them both on their feet with the desperate suggestion that they help me make tea in the kitchen when the demoniac Finn brought it in on a tray.\"},{\"heading\":false,\"text\":\"Amid the welcome confusion of cups and cakes a certain physical decency established itself. Gatsby got himself into a shadow and, while Daisy and I talked, looked conscientiously from one to the other of us with tense, unhappy eyes. However, as calmness wasn’t an end in itself, I made an excuse at the first possible moment, and got to my feet.\"},{\"heading\":false,\"text\":\"“Where are you going?” demanded Gatsby in immediate alarm.\"},{\"heading\":false,\"text\":\"“I’ll be back.”\"},{\"heading\":false,\"text\":\"“I’ve got to speak to you about something before you go.”\"},{\"heading\":false,\"text\":\"He followed me wildly into the kitchen, closed the door, and whispered: “Oh, God!” in a miserable way.\"},{\"heading\":false,\"text\":\"“What’s the matter?”\"},{\"heading\":false,\"text\":\"“This is a terrible mistake,” he said, shaking his head from side to side, “a terrible, terrible mistake.”\"},{\"heading\":false,\"text\":\"“You’re just embarrassed, that’s all,” and luckily I added: “Daisy’s embarrassed too.”\"},{\"heading\":false,\"text\":\"“She’s embarrassed?” he repeated incredulously.\"},{\"heading\":false,\"text\":\"“Just as much as you are.”\"},{\"heading\":false,\"text\":\"“Don’t talk so loud.”\"},{\"heading\":false,\"text\":\"“You’re acting like a little boy,” I broke out impatiently. “Not only that, but you’re rude. Daisy’s sitting in there all alone.”\"},{\"heading\":false,\"text\":\"He raised his hand to stop my words, looked at me with unforgettable reproach, and, opening the door cautiously, went back into the other room.\"},{\"heading\":false,\"text\":\"I walked out the back way—just as Gatsby had when he had made his nervous circuit of the house half an hour before—and ran for a huge black knotted tree, whose massed leaves made a fabric against the rain. Once more it was pouring, and my irregular lawn, well-shaved by Gatsby’s gardener, abounded in small muddy swamps and prehistoric marshes. There was nothing to look at from under the tree except Gatsby’s enormous house, so I stared at it, like Kant at his church steeple, for half an hour. A brewer had built it early in the “period” craze, a decade before, and there was a story that he’d agreed to pay five years’ taxes on all the neighbouring cottages if the owners would have their roofs thatched with straw. Perhaps their refusal took the heart out of his plan to Found a Family—he went into an immediate decline. His children sold his house with the black wreath still on the door. Americans, while willing, even eager, to be serfs, have always been obstinate about being peasantry.\"},{\"heading\":false,\"text\":\"After half an hour, the sun shone again, and the grocer’s automobile rounded Gatsby’s drive with the raw material for his servants’ dinner—I felt sure he wouldn’t eat a spoonful. A maid began opening the upper windows of his house, appeared momentarily in each, and, leaning from the large central bay, spat meditatively into the garden. It was time I went back. While the rain continued it had seemed like the murmur of their voices, rising and swelling a little now and then with gusts of emotion. But in the new silence I felt that silence had fallen within the house too.\"},{\"heading\":false,\"text\":\"I went in—after making every possible noise in the kitchen, short of pushing over the stove—but I don’t believe they heard a sound. They were sitting at either end of the couch, looking at each other as if some question had been asked, or was in the air, and every vestige of embarrassment was gone. Daisy’s face was smeared with tears, and when I came in she jumped up and began wiping at it with her handkerchief before a mirror. But there was a change in Gatsby that was simply confounding. He literally glowed; without a word or a gesture of exultation a new well-being radiated from him and filled the little room.\"},{\"heading\":false,\"text\":\"“Oh, hello, old sport,” he said, as if he hadn’t seen me for years. I thought for a moment he was going to shake hands.\"},{\"heading\":false,\"text\":\"“It’s stopped raining.”\"},{\"heading\":false,\"text\":\"“Has it?” When he realized what I was talking about, that there were twinkle-bells of sunshine in the room, he smiled like a weather man, like an ecstatic patron of recurrent light, and repeated the news to Daisy. “What do you think of that? It’s stopped raining.”\"},{\"heading\":false,\"text\":\"“I’m glad, Jay.” Her throat, full of aching, grieving beauty, told only of her unexpected joy.\"},{\"heading\":false,\"text\":\"“I want you and Daisy to come over to my house,” he said, “I’d like to show her around.”\"},{\"heading\":false,\"text\":\"“You’re sure you want me to come?”\"},{\"heading\":false,\"text\":\"“Absolutely, old sport.”\"},{\"heading\":false,\"text\":\"Daisy went upstairs to wash her face—too late I thought with humiliation of my towels—while Gatsby and I waited on the lawn.\"},{\"heading\":false,\"text\":\"“My house looks well, doesn’t it?” he demanded. “See how the whole front of it catches the light.”\"},{\"heading\":false,\"text\":\"I agreed that it was splendid.\"},{\"heading\":false,\"text\":\"“Yes.” His eyes went over it, every arched door and square tower. “It took me just three years to earn the money that bought it.”\"},{\"heading\":false,\"text\":\"“I thought you inherited your money.”\"},{\"heading\":false,\"text\":\"“I did, old sport,” he said automatically, “but I lost most of it in the big panic—the panic of the war.”\"},{\"heading\":false,\"text\":\"I think he hardly knew what he was saying, for when I asked him what business he was in he answered: “That’s my affair,” before he realized that it wasn’t an appropriate reply.\"},{\"heading\":false,\"text\":\"“Oh, I’ve been in several things,” he corrected himself. “I was in the drug business and then I was in the oil business. But I’m not in either one now.” He looked at me with more attention. “Do you mean you’ve been thinking over what I proposed the other night?”\"},{\"heading\":false,\"text\":\"Before I could answer, Daisy came out of the house and two rows of brass buttons on her dress gleamed in the sunlight.\"},{\"heading\":false,\"text\":\"“That huge place there?” she cried pointing.\"},{\"heading\":false,\"text\":\"“Do you like it?”\"},{\"heading\":false,\"text\":\"“I love it, but I don’t see how you live there all alone.”\"},{\"heading\":false,\"text\":\"“I keep it always full of interesting people, night and day. People who do interesting things. Celebrated people.”\"},{\"heading\":false,\"text\":\"Instead of taking the shortcut along the Sound we went down to the road and entered by the big postern. With enchanting murmurs Daisy admired this aspect or that of the feudal silhouette against the sky, admired the gardens, the sparkling odour of jonquils and the frothy odour of hawthorn and plum blossoms and the pale gold odour of kiss-me-at-the-gate. It was strange to reach the marble steps and find no stir of bright dresses in and out the door, and hear no sound but bird voices in the trees.\"},{\"heading\":false,\"text\":\"And inside, as we wandered through Marie Antoinette music-rooms and Restoration Salons, I felt that there were guests concealed behind every couch and table, under orders to be breathlessly silent until we had passed through. As Gatsby closed the door of “the Merton College Library” I could have sworn I heard the owl-eyed man break into ghostly laughter.\"},{\"heading\":false,\"text\":\"We went upstairs, through period bedrooms swathed in rose and lavender silk and vivid with new flowers, through dressing-rooms and poolrooms, and bathrooms with sunken baths—intruding into one chamber where a dishevelled man in pyjamas was doing liver exercises on the floor. It was Mr. Klipspringer, the “boarder.” I had seen him wandering hungrily about the beach that morning. Finally we came to Gatsby’s own apartment, a bedroom and a bath, and an Adam’s study, where we sat down and drank a glass of some Chartreuse he took from a cupboard in the wall.\"},{\"heading\":false,\"text\":\"He hadn’t once ceased looking at Daisy, and I think he revalued everything in his house according to the measure of response it drew from her well-loved eyes. Sometimes too, he stared around at his possessions in a dazed way, as though in her actual and astounding presence none of it was any longer real. Once he nearly toppled down a flight of stairs.\"},{\"heading\":false,\"text\":\"His bedroom was the simplest room of all—except where the dresser was garnished with a toilet set of pure dull gold. Daisy took the brush with delight, and smoothed her hair, whereupon Gatsby sat down and shaded his eyes and began to laugh.\"},{\"heading\":false,\"text\":\"“It’s the funniest thing, old sport,” he said hilariously. “I can’t—When I try to—”\"},{\"heading\":false,\"text\":\"He had passed visibly through two states and was entering upon a third. After his embarrassment and his unreasoning joy he was consumed with wonder at her presence. He had been full of the idea so long, dreamed it right through to the end, waited with his teeth set, so to speak, at an inconceivable pitch of intensity. Now, in the reaction, he was running down like an over-wound clock.\"},{\"heading\":false,\"text\":\"Recovering himself in a minute he opened for us two hulking patent cabinets which held his massed suits and dressing-gowns and ties, and his shirts, piled like bricks in stacks a dozen high.\"},{\"heading\":false,\"text\":\"“I’ve got a man in England who buys me clothes. He sends over a selection of things at the beginning of each season, spring and fall.”\"},{\"heading\":false,\"text\":\"He took out a pile of shirts and began throwing them, one by one, before us, shirts of sheer linen and thick silk and fine flannel, which lost their folds as they fell and covered the table in many-coloured disarray. While we admired he brought more and the soft rich heap mounted higher—shirts with stripes and scrolls and plaids in coral and apple-green and lavender and faint orange, with monograms of indian blue. Suddenly, with a strained sound, Daisy bent her head into the shirts and began to cry stormily.\"},{\"heading\":false,\"text\":\"“They’re such beautiful shirts,” she sobbed, her voice muffled in the thick folds. “It makes me sad because I’ve never seen such—such beautiful shirts before.”\"},{\"heading\":false,\"text\":\"After the house, we were to see the grounds and the swimming pool, and the hydroplane, and the midsummer flowers—but outside Gatsby’s window it began to rain again, so we stood in a row looking at the corrugated surface of the Sound.\"},{\"heading\":false,\"text\":\"“If it wasn’t for the mist we could see your home across the bay,” said Gatsby. “You always have a green light that burns all night at the end of your dock.”\"},{\"heading\":false,\"text\":\"Daisy put her arm through his abruptly, but he seemed absorbed in what he had just said. Possibly it had occurred to him that the colossal significance of that light had now vanished forever. Compared to the great distance that had separated him from Daisy it had seemed very near to her, almost touching her. It had seemed as close as a star to the moon. Now it was again a green light on a dock. His count of enchanted objects had diminished by one.\"},{\"heading\":false,\"text\":\"I began to walk about the room, examining various indefinite objects in the half darkness. A large photograph of an elderly man in yachting costume attracted me, hung on the wall over his desk.\"},{\"heading\":false,\"text\":\"“Who’s this?”\"},{\"heading\":false,\"text\":\"“That? That’s Mr. Dan Cody, old sport.”\"},{\"heading\":false,\"text\":\"The name sounded faintly familiar.\"},{\"heading\":false,\"text\":\"“He’s dead now. He used to be my best friend years ago.”\"},{\"heading\":false,\"text\":\"There was a small picture of Gatsby, also in yachting costume, on the bureau—Gatsby with his head thrown back defiantly—taken apparently when he was about eighteen.\"},{\"heading\":false,\"text\":\"“I adore it,” exclaimed Daisy. “The pompadour! You never told me you had a pompadour—or a yacht.”\"},{\"heading\":false,\"text\":\"“Look at this,” said Gatsby quickly. “Here’s a lot of clippings—about you.”\"},{\"heading\":false,\"text\":\"They stood side by side examining it. I was going to ask to see the rubies when the phone rang, and Gatsby took up the receiver.\"},{\"heading\":false,\"text\":\"“Yes… Well, I can’t talk now… I can’t talk now, old sport… I said a small town… He must know what a small town is… Well, he’s no use to us if Detroit is his idea of a small town…”\"},{\"heading\":false,\"text\":\"He rang off.\"},{\"heading\":false,\"text\":\"“Come here quick!” cried Daisy at the window.\"},{\"heading\":false,\"text\":\"The rain was still falling, but the darkness had parted in the west, and there was a pink and golden billow of foamy clouds above the sea.\"},{\"heading\":false,\"text\":\"“Look at that,” she whispered, and then after a moment: “I’d like to just get one of those pink clouds and put you in it and push you around.”\"},{\"heading\":false,\"text\":\"I tried to go then, but they wouldn’t hear of it; perhaps my presence made them feel more satisfactorily alone.\"},{\"heading\":false,\"text\":\"“I know what we’ll do,” said Gatsby, “we’ll have Klipspringer play the piano.”\"},{\"heading\":false,\"text\":\"He went out of the room calling “Ewing!” and returned in a few minutes accompanied by an embarrassed, slightly worn young man, with shell-rimmed glasses and scanty blond hair. He was now decently clothed in a “sport shirt,” open at the neck, sneakers, and duck trousers of a nebulous hue.\"},{\"heading\":false,\"text\":\"“Did we interrupt your exercise?” inquired Daisy politely.\"},{\"heading\":false,\"text\":\"“I was asleep,” cried Mr. Klipspringer, in a spasm of embarrassment. “That is, I’d been asleep. Then I got up…”\"},{\"heading\":false,\"text\":\"“Klipspringer plays the piano,” said Gatsby, cutting him off. “Don’t you, Ewing, old sport?”\"},{\"heading\":false,\"text\":\"“I don’t play well. I don’t—hardly play at all. I’m all out of prac—”\"},{\"heading\":false,\"text\":\"“We’ll go downstairs,” interrupted Gatsby. He flipped a switch. The grey windows disappeared as the house glowed full of light.\"},{\"heading\":false,\"text\":\"In the music-room Gatsby turned on a solitary lamp beside the piano. He lit Daisy’s cigarette from a trembling match, and sat down with her on a couch far across the room, where there was no light save what the gleaming floor bounced in from the hall.\"},{\"heading\":false,\"text\":\"When Klipspringer had played “The Love Nest” he turned around on the bench and searched unhappily for Gatsby in the gloom.\"},{\"heading\":false,\"text\":\"“I’m all out of practice, you see. I told you I couldn’t play. I’m all out of prac—”\"},{\"heading\":false,\"text\":\"“Don’t talk so much, old sport,” commanded Gatsby. “Play!”\"},{\"heading\":false,\"text\":\"“In the morning,\\n\\nIn the evening,\\n\\nAin’t we got fun—”\"},{\"heading\":false,\"text\":\"Outside the wind was loud and there was a faint flow of thunder along the Sound. All the lights were going on in West Egg now; the electric trains, men-carrying, were plunging home through the rain from New York. It was the hour of a profound human change, and excitement was generating on the air.\"},{\"heading\":false,\"text\":\"“One thing’s sure and nothing’s surer\\n\\nThe rich get richer and the poor get—children.\\n\\nIn the meantime,\\n\\nIn between time—”\"},{\"heading\":false,\"text\":\"As I went over to say goodbye I saw that the expression of bewilderment had come back into Gatsby’s face, as though a faint doubt had occurred to him as to the quality of his present happiness. Almost five years! There must have been moments even that afternoon when Daisy tumbled short of his dreams—not through her own fault, but because of the colossal vitality of his illusion. It had gone beyond her, beyond everything. He had thrown himself into it with a creative passion, adding to it all the time, decking it out with every bright feather that drifted his way. No amount of fire or freshness can challenge what a man can store up in his ghostly heart.\"},{\"heading\":false,\"text\":\"As I watched him he adjusted himself a little, visibly. His hand took hold of hers, and as she said something low in his ear he turned toward her with a rush of emotion. I think that voice held him most, with its fluctuating, feverish warmth, because it couldn’t be over-dreamed—that voice was a deathless song.\"},{\"heading\":false,\"text\":\"They had forgotten me, but Daisy glanced up and held out her hand; Gatsby didn’t know me now at all. I looked once more at them and they looked back at me, remotely, possessed by intense life. Then I went out of the room and down the marble steps into the rain, leaving them there together.\"}]},{\"title\":\"VI\",\"blocks\":[{\"heading\":false,\"text\":\"About this time an ambitious young reporter from New York arrived one morning at Gatsby’s door and asked him if he had anything to say.\"},{\"heading\":false,\"text\":\"“Anything to say about what?” inquired Gatsby politely.\"},{\"heading\":false,\"text\":\"“Why—any statement to give out.”\"},{\"heading\":false,\"text\":\"It transpired after a confused five minutes that the man had heard Gatsby’s name around his office in a connection which he either wouldn’t reveal or didn’t fully understand. This was his day off and with laudable initiative he had hurried out “to see.”\"},{\"heading\":false,\"text\":\"It was a random shot, and yet the reporter’s instinct was right. Gatsby’s notoriety, spread about by the hundreds who had accepted his hospitality and so become authorities upon his past, had increased all summer until he fell just short of being news. Contemporary legends such as the “underground pipeline to Canada” attached themselves to him, and there was one persistent story that he didn’t live in a house at all, but in a boat that looked like a house and was moved secretly up and down the Long Island shore. Just why these inventions were a source of satisfaction to James Gatz of North Dakota, isn’t easy to say.\"},{\"heading\":false,\"text\":\"James Gatz—that was really, or at least legally, his name. He had changed it at the age of seventeen and at the specific moment that witnessed the beginning of his career—when he saw Dan Cody’s yacht drop anchor over the most insidious flat on Lake Superior. It was James Gatz who had been loafing along the beach that afternoon in a torn green jersey and a pair of canvas pants, but it was already Jay Gatsby who borrowed a rowboat, pulled out to the Tuolomee, and informed Cody that a wind might catch him and break him up in half an hour.\"},{\"heading\":false,\"text\":\"I suppose he’d had the name ready for a long time, even then. His parents were shiftless and unsuccessful farm people—his imagination had never really accepted them as his parents at all. The truth was that Jay Gatsby of West Egg, Long Island, sprang from his Platonic conception of himself. He was a son of God—a phrase which, if it means anything, means just that—and he must be about His Father’s business, the service of a vast, vulgar, and meretricious beauty. So he invented just the sort of Jay Gatsby that a seventeen-year-old boy would be likely to invent, and to this conception he was faithful to the end.\"},{\"heading\":false,\"text\":\"For over a year he had been beating his way along the south shore of Lake Superior as a clam-digger and a salmon-fisher or in any other capacity that brought him food and bed. His brown, hardening body lived naturally through the half-fierce, half-lazy work of the bracing days. He knew women early, and since they spoiled him he became contemptuous of them, of young virgins because they were ignorant, of the others because they were hysterical about things which in his overwhelming self-absorption he took for granted.\"},{\"heading\":false,\"text\":\"But his heart was in a constant, turbulent riot. The most grotesque and fantastic conceits haunted him in his bed at night. A universe of ineffable gaudiness spun itself out in his brain while the clock ticked on the washstand and the moon soaked with wet light his tangled clothes upon the floor. Each night he added to the pattern of his fancies until drowsiness closed down upon some vivid scene with an oblivious embrace. For a while these reveries provided an outlet for his imagination; they were a satisfactory hint of the unreality of reality, a promise that the rock of the world was founded securely on a fairy’s wing.\"},{\"heading\":false,\"text\":\"An instinct toward his future glory had led him, some months before, to the small Lutheran College of St. Olaf’s in southern Minnesota. He stayed there two weeks, dismayed at its ferocious indifference to the drums of his destiny, to destiny itself, and despising the janitor’s work with which he was to pay his way through. Then he drifted back to Lake Superior, and he was still searching for something to do on the day that Dan Cody’s yacht dropped anchor in the shallows alongshore.\"},{\"heading\":false,\"text\":\"Cody was fifty years old then, a product of the Nevada silver fields, of the Yukon, of every rush for metal since seventy-five. The transactions in Montana copper that made him many times a millionaire found him physically robust but on the verge of soft-mindedness, and, suspecting this, an infinite number of women tried to separate him from his money. The none too savoury ramifications by which Ella Kaye, the newspaper woman, played Madame de Maintenon to his weakness and sent him to sea in a yacht, were common property of the turgid journalism in 1902. He had been coasting along all too hospitable shores for five years when he turned up as James Gatz’s destiny in Little Girl Bay.\"},{\"heading\":false,\"text\":\"To young Gatz, resting on his oars and looking up at the railed deck, that yacht represented all the beauty and glamour in the world. I suppose he smiled at Cody—he had probably discovered that people liked him when he smiled. At any rate Cody asked him a few questions (one of them elicited the brand new name) and found that he was quick and extravagantly ambitious. A few days later he took him to Duluth and bought him a blue coat, six pairs of white duck trousers, and a yachting cap. And when the Tuolomee left for the West Indies and the Barbary Coast, Gatsby left too.\"},{\"heading\":false,\"text\":\"He was employed in a vague personal capacity—while he remained with Cody he was in turn steward, mate, skipper, secretary, and even jailor, for Dan Cody sober knew what lavish doings Dan Cody drunk might soon be about, and he provided for such contingencies by reposing more and more trust in Gatsby. The arrangement lasted five years, during which the boat went three times around the Continent. It might have lasted indefinitely except for the fact that Ella Kaye came on board one night in Boston and a week later Dan Cody inhospitably died.\"},{\"heading\":false,\"text\":\"I remember the portrait of him up in Gatsby’s bedroom, a grey, florid man with a hard, empty face—the pioneer debauchee, who during one phase of American life brought back to the Eastern seaboard the savage violence of the frontier brothel and saloon. It was indirectly due to Cody that Gatsby drank so little. Sometimes in the course of gay parties women used to rub champagne into his hair; for himself he formed the habit of letting liquor alone.\"},{\"heading\":false,\"text\":\"And it was from Cody that he inherited money—a legacy of twenty-five thousand dollars. He didn’t get it. He never understood the legal device that was used against him, but what remained of the millions went intact to Ella Kaye. He was left with his singularly appropriate education; the vague contour of Jay Gatsby had filled out to the substantiality of a man.\"},{\"heading\":false,\"text\":\"He told me all this very much later, but I’ve put it down here with the idea of exploding those first wild rumours about his antecedents, which weren’t even faintly true. Moreover he told it to me at a time of confusion, when I had reached the point of believing everything and nothing about him. So I take advantage of this short halt, while Gatsby, so to speak, caught his breath, to clear this set of misconceptions away.\"},{\"heading\":false,\"text\":\"It was a halt, too, in my association with his affairs. For several weeks I didn’t see him or hear his voice on the phone—mostly I was in New York, trotting around with Jordan and trying to ingratiate myself with her senile aunt—but finally I went over to his house one Sunday afternoon. I hadn’t been there two minutes when somebody brought Tom Buchanan in for a drink. I was startled, naturally, but the really surprising thing was that it hadn’t happened before.\"},{\"heading\":false,\"text\":\"They were a party of three on horseback—Tom and a man named Sloane and a pretty woman in a brown riding-habit, who had been there previously.\"},{\"heading\":false,\"text\":\"“I’m delighted to see you,” said Gatsby, standing on his porch. “I’m delighted that you dropped in.”\"},{\"heading\":false,\"text\":\"As though they cared!\"},{\"heading\":false,\"text\":\"“Sit right down. Have a cigarette or a cigar.” He walked around the room quickly, ringing bells. “I’ll have something to drink for you in just a minute.”\"},{\"heading\":false,\"text\":\"He was profoundly affected by the fact that Tom was there. But he would be uneasy anyhow until he had given them something, realizing in a vague way that that was all they came for. Mr. Sloane wanted nothing. A lemonade? No, thanks. A little champagne? Nothing at all, thanks… I’m sorry—\"},{\"heading\":false,\"text\":\"“Did you have a nice ride?”\"},{\"heading\":false,\"text\":\"“Very good roads around here.”\"},{\"heading\":false,\"text\":\"“I suppose the automobiles—”\"},{\"heading\":false,\"text\":\"“Yeah.”\"},{\"heading\":false,\"text\":\"Moved by an irresistible impulse, Gatsby turned to Tom, who had accepted the introduction as a stranger.\"},{\"heading\":false,\"text\":\"“I believe we’ve met somewhere before, Mr. Buchanan.”\"},{\"heading\":false,\"text\":\"“Oh, yes,” said Tom, gruffly polite, but obviously not remembering. “So we did. I remember very well.”\"},{\"heading\":false,\"text\":\"“About two weeks ago.”\"},{\"heading\":false,\"text\":\"“That’s right. You were with Nick here.”\"},{\"heading\":false,\"text\":\"“I know your wife,” continued Gatsby, almost aggressively.\"},{\"heading\":false,\"text\":\"“That so?”\"},{\"heading\":false,\"text\":\"Tom turned to me.\"},{\"heading\":false,\"text\":\"“You live near here, Nick?”\"},{\"heading\":false,\"text\":\"“Next door.”\"},{\"heading\":false,\"text\":\"“That so?”\"},{\"heading\":false,\"text\":\"Mr. Sloane didn’t enter into the conversation, but lounged back haughtily in his chair; the woman said nothing either—until unexpectedly, after two highballs, she became cordial.\"},{\"heading\":false,\"text\":\"“We’ll all come over to your next party, Mr. Gatsby,” she suggested. “What do you say?”\"},{\"heading\":false,\"text\":\"“Certainly; I’d be delighted to have you.”\"},{\"heading\":false,\"text\":\"“Be ver’ nice,” said Mr. Sloane, without gratitude. “Well—think ought to be starting home.”\"},{\"heading\":false,\"text\":\"“Please don’t hurry,” Gatsby urged them. He had control of himself now, and he wanted to see more of Tom. “Why don’t you—why don’t you stay for supper? I wouldn’t be surprised if some other people dropped in from New York.”\"},{\"heading\":false,\"text\":\"“You come to supper with me,” said the lady enthusiastically. “Both of you.”\"},{\"heading\":false,\"text\":\"This included me. Mr. Sloane got to his feet.\"},{\"heading\":false,\"text\":\"“Come along,” he said—but to her only.\"},{\"heading\":false,\"text\":\"“I mean it,” she insisted. “I’d love to have you. Lots of room.”\"},{\"heading\":false,\"text\":\"Gatsby looked at me questioningly. He wanted to go and he didn’t see that Mr. Sloane had determined he shouldn’t.\"},{\"heading\":false,\"text\":\"“I’m afraid I won’t be able to,” I said.\"},{\"heading\":false,\"text\":\"“Well, you come,” she urged, concentrating on Gatsby.\"},{\"heading\":false,\"text\":\"Mr. Sloane murmured something close to her ear.\"},{\"heading\":false,\"text\":\"“We won’t be late if we start now,” she insisted aloud.\"},{\"heading\":false,\"text\":\"“I haven’t got a horse,” said Gatsby. “I used to ride in the army, but I’ve never bought a horse. I’ll have to follow you in my car. Excuse me for just a minute.”\"},{\"heading\":false,\"text\":\"The rest of us walked out on the porch, where Sloane and the lady began an impassioned conversation aside.\"},{\"heading\":false,\"text\":\"“My God, I believe the man’s coming,” said Tom. “Doesn’t he know she doesn’t want him?”\"},{\"heading\":false,\"text\":\"“She says she does want him.”\"},{\"heading\":false,\"text\":\"“She has a big dinner party and he won’t know a soul there.” He frowned. “I wonder where in the devil he met Daisy. By God, I may be old-fashioned in my ideas, but women run around too much these days to suit me. They meet all kinds of crazy fish.”\"},{\"heading\":false,\"text\":\"Suddenly Mr. Sloane and the lady walked down the steps and mounted their horses.\"},{\"heading\":false,\"text\":\"“Come on,” said Mr. Sloane to Tom, “we’re late. We’ve got to go.” And then to me: “Tell him we couldn’t wait, will you?”\"},{\"heading\":false,\"text\":\"Tom and I shook hands, the rest of us exchanged a cool nod, and they trotted quickly down the drive, disappearing under the August foliage just as Gatsby, with hat and light overcoat in hand, came out the front door.\"},{\"heading\":false,\"text\":\"Tom was evidently perturbed at Daisy’s running around alone, for on the following Saturday night he came with her to Gatsby’s party. Perhaps his presence gave the evening its peculiar quality of oppressiveness—it stands out in my memory from Gatsby’s other parties that summer. There were the same people, or at least the same sort of people, the same profusion of champagne, the same many-coloured, many-keyed commotion, but I felt an unpleasantness in the air, a pervading harshness that hadn’t been there before. Or perhaps I had merely grown used to it, grown to accept West Egg as a world complete in itself, with its own standards and its own great figures, second to nothing because it had no consciousness of being so, and now I was looking at it again, through Daisy’s eyes. It is invariably saddening to look through new eyes at things upon which you have expended your own powers of adjustment.\"},{\"heading\":false,\"text\":\"They arrived at twilight, and, as we strolled out among the sparkling hundreds, Daisy’s voice was playing murmurous tricks in her throat.\"},{\"heading\":false,\"text\":\"“These things excite me so,” she whispered. “If you want to kiss me any time during the evening, Nick, just let me know and I’ll be glad to arrange it for you. Just mention my name. Or present a green card. I’m giving out green—”\"},{\"heading\":false,\"text\":\"“Look around,” suggested Gatsby.\"},{\"heading\":false,\"text\":\"“I’m looking around. I’m having a marvellous—”\"},{\"heading\":false,\"text\":\"“You must see the faces of many people you’ve heard about.”\"},{\"heading\":false,\"text\":\"Tom’s arrogant eyes roamed the crowd.\"},{\"heading\":false,\"text\":\"“We don’t go around very much,” he said; “in fact, I was just thinking I don’t know a soul here.”\"},{\"heading\":false,\"text\":\"“Perhaps you know that lady.” Gatsby indicated a gorgeous, scarcely human orchid of a woman who sat in state under a white-plum tree. Tom and Daisy stared, with that peculiarly unreal feeling that accompanies the recognition of a hitherto ghostly celebrity of the movies.\"},{\"heading\":false,\"text\":\"“She’s lovely,” said Daisy.\"},{\"heading\":false,\"text\":\"“The man bending over her is her director.”\"},{\"heading\":false,\"text\":\"He took them ceremoniously from group to group:\"},{\"heading\":false,\"text\":\"“Mrs. Buchanan… and Mr. Buchanan—” After an instant’s hesitation he added: “the polo player.”\"},{\"heading\":false,\"text\":\"“Oh no,” objected Tom quickly, “not me.”\"},{\"heading\":false,\"text\":\"But evidently the sound of it pleased Gatsby for Tom remained “the polo player” for the rest of the evening.\"},{\"heading\":false,\"text\":\"“I’ve never met so many celebrities,” Daisy exclaimed. “I liked that man—what was his name?—with the sort of blue nose.”\"},{\"heading\":false,\"text\":\"Gatsby identified him, adding that he was a small producer.\"},{\"heading\":false,\"text\":\"“Well, I liked him anyhow.”\"},{\"heading\":false,\"text\":\"“I’d a little rather not be the polo player,” said Tom pleasantly, “I’d rather look at all these famous people in—in oblivion.”\"},{\"heading\":false,\"text\":\"Daisy and Gatsby danced. I remember being surprised by his graceful, conservative foxtrot—I had never seen him dance before. Then they sauntered over to my house and sat on the steps for half an hour, while at her request I remained watchfully in the garden. “In case there’s a fire or a flood,” she explained, “or any act of God.”\"},{\"heading\":false,\"text\":\"Tom appeared from his oblivion as we were sitting down to supper together. “Do you mind if I eat with some people over here?” he said. “A fellow’s getting off some funny stuff.”\"},{\"heading\":false,\"text\":\"“Go ahead,” answered Daisy genially, “and if you want to take down any addresses here’s my little gold pencil.”… She looked around after a moment and told me the girl was “common but pretty,” and I knew that except for the half-hour she’d been alone with Gatsby she wasn’t having a good time.\"},{\"heading\":false,\"text\":\"We were at a particularly tipsy table. That was my fault—Gatsby had been called to the phone, and I’d enjoyed these same people only two weeks before. But what had amused me then turned septic on the air now.\"},{\"heading\":false,\"text\":\"“How do you feel, Miss Baedeker?”\"},{\"heading\":false,\"text\":\"The girl addressed was trying, unsuccessfully, to slump against my shoulder. At this inquiry she sat up and opened her eyes.\"},{\"heading\":false,\"text\":\"“Wha’?”\"},{\"heading\":false,\"text\":\"A massive and lethargic woman, who had been urging Daisy to play golf with her at the local club tomorrow, spoke in Miss Baedeker’s defence:\"},{\"heading\":false,\"text\":\"“Oh, she’s all right now. When she’s had five or six cocktails she always starts screaming like that. I tell her she ought to leave it alone.”\"},{\"heading\":false,\"text\":\"“I do leave it alone,” affirmed the accused hollowly.\"},{\"heading\":false,\"text\":\"“We heard you yelling, so I said to Doc Civet here: ‘There’s somebody that needs your help, Doc.’ ”\"},{\"heading\":false,\"text\":\"“She’s much obliged, I’m sure,” said another friend, without gratitude, “but you got her dress all wet when you stuck her head in the pool.”\"},{\"heading\":false,\"text\":\"“Anything I hate is to get my head stuck in a pool,” mumbled Miss Baedeker. “They almost drowned me once over in New Jersey.”\"},{\"heading\":false,\"text\":\"“Then you ought to leave it alone,” countered Doctor Civet.\"},{\"heading\":false,\"text\":\"“Speak for yourself!” cried Miss Baedeker violently. “Your hand shakes. I wouldn’t let you operate on me!”\"},{\"heading\":false,\"text\":\"It was like that. Almost the last thing I remember was standing with Daisy and watching the moving-picture director and his Star. They were still under the white-plum tree and their faces were touching except for a pale, thin ray of moonlight between. It occurred to me that he had been very slowly bending toward her all evening to attain this proximity, and even while I watched I saw him stoop one ultimate degree and kiss at her cheek.\"},{\"heading\":false,\"text\":\"“I like her,” said Daisy, “I think she’s lovely.”\"},{\"heading\":false,\"text\":\"But the rest offended her—and inarguably because it wasn’t a gesture but an emotion. She was appalled by West Egg, this unprecedented “place” that Broadway had begotten upon a Long Island fishing village—appalled by its raw vigour that chafed under the old euphemisms and by the too obtrusive fate that herded its inhabitants along a shortcut from nothing to nothing. She saw something awful in the very simplicity she failed to understand.\"},{\"heading\":false,\"text\":\"I sat on the front steps with them while they waited for their car. It was dark here in front; only the bright door sent ten square feet of light volleying out into the soft black morning. Sometimes a shadow moved against a dressing-room blind above, gave way to another shadow, an indefinite procession of shadows, who rouged and powdered in an invisible glass.\"},{\"heading\":false,\"text\":\"“Who is this Gatsby anyhow?” demanded Tom suddenly. “Some big bootlegger?”\"},{\"heading\":false,\"text\":\"“Where’d you hear that?” I inquired.\"},{\"heading\":false,\"text\":\"“I didn’t hear it. I imagined it. A lot of these newly rich people are just big bootleggers, you know.”\"},{\"heading\":false,\"text\":\"“Not Gatsby,” I said shortly.\"},{\"heading\":false,\"text\":\"He was silent for a moment. The pebbles of the drive crunched under his feet.\"},{\"heading\":false,\"text\":\"“Well, he certainly must have strained himself to get this menagerie together.”\"},{\"heading\":false,\"text\":\"A breeze stirred the grey haze of Daisy’s fur collar.\"},{\"heading\":false,\"text\":\"“At least they are more interesting than the people we know,” she said with an effort.\"},{\"heading\":false,\"text\":\"“You didn’t look so interested.”\"},{\"heading\":false,\"text\":\"“Well, I was.”\"},{\"heading\":false,\"text\":\"Tom laughed and turned to me.\"},{\"heading\":false,\"text\":\"“Did you notice Daisy’s face when that girl asked her to put her under a cold shower?”\"},{\"heading\":false,\"text\":\"Daisy began to sing with the music in a husky, rhythmic whisper, bringing out a meaning in each word that it had never had before and would never have again. When the melody rose her voice broke up sweetly, following it, in a way contralto voices have, and each change tipped out a little of her warm human magic upon the air.\"},{\"heading\":false,\"text\":\"“Lots of people come who haven’t been invited,” she said suddenly. “That girl hadn’t been invited. They simply force their way in and he’s too polite to object.”\"},{\"heading\":false,\"text\":\"“I’d like to know who he is and what he does,” insisted Tom. “And I think I’ll make a point of finding out.”\"},{\"heading\":false,\"text\":\"“I can tell you right now,” she answered. “He owned some drugstores, a lot of drugstores. He built them up himself.”\"},{\"heading\":false,\"text\":\"The dilatory limousine came rolling up the drive.\"},{\"heading\":false,\"text\":\"“Good night, Nick,” said Daisy.\"},{\"heading\":false,\"text\":\"Her glance left me and sought the lighted top of the steps, where “Three O’Clock in the Morning,” a neat, sad little waltz of that year, was drifting out the open door. After all, in the very casualness of Gatsby’s party there were romantic possibilities totally absent from her world. What was it up there in the song that seemed to be calling her back inside? What would happen now in the dim, incalculable hours? Perhaps some unbelievable guest would arrive, a person infinitely rare and to be marvelled at, some authentically radiant young girl who with one fresh glance at Gatsby, one moment of magical encounter, would blot out those five years of unwavering devotion.\"},{\"heading\":false,\"text\":\"I stayed late that night. Gatsby asked me to wait until he was free, and I lingered in the garden until the inevitable swimming party had run up, chilled and exalted, from the black beach, until the lights were extinguished in the guestrooms overhead. When he came down the steps at last the tanned skin was drawn unusually tight on his face, and his eyes were bright and tired.\"},{\"heading\":false,\"text\":\"“She didn’t like it,” he said immediately.\"},{\"heading\":false,\"text\":\"“Of course she did.”\"},{\"heading\":false,\"text\":\"“She didn’t like it,” he insisted. “She didn’t have a good time.”\"},{\"heading\":false,\"text\":\"He was silent, and I guessed at his unutterable depression.\"},{\"heading\":false,\"text\":\"“I feel far away from her,” he said. “It’s hard to make her understand.”\"},{\"heading\":false,\"text\":\"“You mean about the dance?”\"},{\"heading\":false,\"text\":\"“The dance?” He dismissed all the dances he had given with a snap of his fingers. “Old sport, the dance is unimportant.”\"},{\"heading\":false,\"text\":\"He wanted nothing less of Daisy than that she should go to Tom and say: “I never loved you.” After she had obliterated four years with that sentence they could decide upon the more practical measures to be taken. One of them was that, after she was free, they were to go back to Louisville and be married from her house—just as if it were five years ago.\"},{\"heading\":false,\"text\":\"“And she doesn’t understand,” he said. “She used to be able to understand. We’d sit for hours—”\"},{\"heading\":false,\"text\":\"He broke off and began to walk up and down a desolate path of fruit rinds and discarded favours and crushed flowers.\"},{\"heading\":false,\"text\":\"“I wouldn’t ask too much of her,” I ventured. “You can’t repeat the past.”\"},{\"heading\":false,\"text\":\"“Can’t repeat the past?” he cried incredulously. “Why of course you can!”\"},{\"heading\":false,\"text\":\"He looked around him wildly, as if the past were lurking here in the shadow of his house, just out of reach of his hand.\"},{\"heading\":false,\"text\":\"“I’m going to fix everything just the way it was before,” he said, nodding determinedly. “She’ll see.”\"},{\"heading\":false,\"text\":\"He talked a lot about the past, and I gathered that he wanted to recover something, some idea of himself perhaps, that had gone into loving Daisy. His life had been confused and disordered since then, but if he could once return to a certain starting place and go over it all slowly, he could find out what that thing was…\"},{\"heading\":false,\"text\":\"… One autumn night, five years before, they had been walking down the street when the leaves were falling, and they came to a place where there were no trees and the sidewalk was white with moonlight. They stopped here and turned toward each other. Now it was a cool night with that mysterious excitement in it which comes at the two changes of the year. The quiet lights in the houses were humming out into the darkness and there was a stir and bustle among the stars. Out of the corner of his eye Gatsby saw that the blocks of the sidewalks really formed a ladder and mounted to a secret place above the trees—he could climb to it, if he climbed alone, and once there he could suck on the pap of life, gulp down the incomparable milk of wonder.\"},{\"heading\":false,\"text\":\"His heart beat faster as Daisy’s white face came up to his own. He knew that when he kissed this girl, and forever wed his unutterable visions to her perishable breath, his mind would never romp again like the mind of God. So he waited, listening for a moment longer to the tuning-fork that had been struck upon a star. Then he kissed her. At his lips’ touch she blossomed for him like a flower and the incarnation was complete.\"},{\"heading\":false,\"text\":\"Through all he said, even through his appalling sentimentality, I was reminded of something—an elusive rhythm, a fragment of lost words, that I had heard somewhere a long time ago. For a moment a phrase tried to take shape in my mouth and my lips parted like a dumb man’s, as though there was more struggling upon them than a wisp of startled air. But they made no sound, and what I had almost remembered was uncommunicable forever.\"}]},{\"title\":\"VII\",\"blocks\":[{\"heading\":false,\"text\":\"It was when curiosity about Gatsby was at its highest that the lights in his house failed to go on one Saturday night—and, as obscurely as it had begun, his career as Trimalchio was over. Only gradually did I become aware that the automobiles which turned expectantly into his drive stayed for just a minute and then drove sulkily away. Wondering if he were sick I went over to find out—an unfamiliar butler with a villainous face squinted at me suspiciously from the door.\"},{\"heading\":false,\"text\":\"“Is Mr. Gatsby sick?”\"},{\"heading\":false,\"text\":\"“Nope.” After a pause he added “sir” in a dilatory, grudging way.\"},{\"heading\":false,\"text\":\"“I hadn’t seen him around, and I was rather worried. Tell him Mr. Carraway came over.”\"},{\"heading\":false,\"text\":\"“Who?” he demanded rudely.\"},{\"heading\":false,\"text\":\"“Carraway.”\"},{\"heading\":false,\"text\":\"“Carraway. All right, I’ll tell him.”\"},{\"heading\":false,\"text\":\"Abruptly he slammed the door.\"},{\"heading\":false,\"text\":\"My Finn informed me that Gatsby had dismissed every servant in his house a week ago and replaced them with half a dozen others, who never went into West Egg village to be bribed by the tradesmen, but ordered moderate supplies over the telephone. The grocery boy reported that the kitchen looked like a pigsty, and the general opinion in the village was that the new people weren’t servants at all.\"},{\"heading\":false,\"text\":\"Next day Gatsby called me on the phone.\"},{\"heading\":false,\"text\":\"“Going away?” I inquired.\"},{\"heading\":false,\"text\":\"“No, old sport.”\"},{\"heading\":false,\"text\":\"“I hear you fired all your servants.”\"},{\"heading\":false,\"text\":\"“I wanted somebody who wouldn’t gossip. Daisy comes over quite often—in the afternoons.”\"},{\"heading\":false,\"text\":\"So the whole caravansary had fallen in like a card house at the disapproval in her eyes.\"},{\"heading\":false,\"text\":\"“They’re some people Wolfshiem wanted to do something for. They’re all brothers and sisters. They used to run a small hotel.”\"},{\"heading\":false,\"text\":\"“I see.”\"},{\"heading\":false,\"text\":\"He was calling up at Daisy’s request—would I come to lunch at her house tomorrow? Miss Baker would be there. Half an hour later Daisy herself telephoned and seemed relieved to find that I was coming. Something was up. And yet I couldn’t believe that they would choose this occasion for a scene—especially for the rather harrowing scene that Gatsby had outlined in the garden.\"},{\"heading\":false,\"text\":\"The next day was broiling, almost the last, certainly the warmest, of the summer. As my train emerged from the tunnel into sunlight, only the hot whistles of the National Biscuit Company broke the simmering hush at noon. The straw seats of the car hovered on the edge of combustion; the woman next to me perspired delicately for a while into her white shirtwaist, and then, as her newspaper dampened under her fingers, lapsed despairingly into deep heat with a desolate cry. Her pocketbook slapped to the floor.\"},{\"heading\":false,\"text\":\"“Oh, my!” she gasped.\"},{\"heading\":false,\"text\":\"I picked it up with a weary bend and handed it back to her, holding it at arm’s length and by the extreme tip of the corners to indicate that I had no designs upon it—but everyone near by, including the woman, suspected me just the same.\"},{\"heading\":false,\"text\":\"“Hot!” said the conductor to familiar faces. “Some weather!… Hot!… Hot!… Hot!… Is it hot enough for you? Is it hot? Is it… ?”\"},{\"heading\":false,\"text\":\"My commutation ticket came back to me with a dark stain from his hand. That anyone should care in this heat whose flushed lips he kissed, whose head made damp the pyjama pocket over his heart!\"},{\"heading\":false,\"text\":\"… Through the hall of the Buchanans’ house blew a faint wind, carrying the sound of the telephone bell out to Gatsby and me as we waited at the door.\"},{\"heading\":false,\"text\":\"“The master’s body?” roared the butler into the mouthpiece. “I’m sorry, madame, but we can’t furnish it—it’s far too hot to touch this noon!”\"},{\"heading\":false,\"text\":\"What he really said was: “Yes… Yes… I’ll see.”\"},{\"heading\":false,\"text\":\"He set down the receiver and came toward us, glistening slightly, to take our stiff straw hats.\"},{\"heading\":false,\"text\":\"“Madame expects you in the salon!” he cried, needlessly indicating the direction. In this heat every extra gesture was an affront to the common store of life.\"},{\"heading\":false,\"text\":\"The room, shadowed well with awnings, was dark and cool. Daisy and Jordan lay upon an enormous couch, like silver idols weighing down their own white dresses against the singing breeze of the fans.\"},{\"heading\":false,\"text\":\"“We can’t move,” they said together.\"},{\"heading\":false,\"text\":\"Jordan’s fingers, powdered white over their tan, rested for a moment in mine.\"},{\"heading\":false,\"text\":\"“And Mr. Thomas Buchanan, the athlete?” I inquired.\"},{\"heading\":false,\"text\":\"Simultaneously I heard his voice, gruff, muffled, husky, at the hall telephone.\"},{\"heading\":false,\"text\":\"Gatsby stood in the centre of the crimson carpet and gazed around with fascinated eyes. Daisy watched him and laughed, her sweet, exciting laugh; a tiny gust of powder rose from her bosom into the air.\"},{\"heading\":false,\"text\":\"“The rumour is,” whispered Jordan, “that that’s Tom’s girl on the telephone.”\"},{\"heading\":false,\"text\":\"We were silent. The voice in the hall rose high with annoyance: “Very well, then, I won’t sell you the car at all… I’m under no obligations to you at all… and as for your bothering me about it at lunch time, I won’t stand that at all!”\"},{\"heading\":false,\"text\":\"“Holding down the receiver,” said Daisy cynically.\"},{\"heading\":false,\"text\":\"“No, he’s not,” I assured her. “It’s a bona-fide deal. I happen to know about it.”\"},{\"heading\":false,\"text\":\"Tom flung open the door, blocked out its space for a moment with his thick body, and hurried into the room.\"},{\"heading\":false,\"text\":\"“Mr. Gatsby!” He put out his broad, flat hand with well-concealed dislike. “I’m glad to see you, sir… Nick…”\"},{\"heading\":false,\"text\":\"“Make us a cold drink,” cried Daisy.\"},{\"heading\":false,\"text\":\"As he left the room again she got up and went over to Gatsby and pulled his face down, kissing him on the mouth.\"},{\"heading\":false,\"text\":\"“You know I love you,” she murmured.\"},{\"heading\":false,\"text\":\"“You forget there’s a lady present,” said Jordan.\"},{\"heading\":false,\"text\":\"Daisy looked around doubtfully.\"},{\"heading\":false,\"text\":\"“You kiss Nick too.”\"},{\"heading\":false,\"text\":\"“What a low, vulgar girl!”\"},{\"heading\":false,\"text\":\"“I don’t care!” cried Daisy, and began to clog on the brick fireplace. Then she remembered the heat and sat down guiltily on the couch just as a freshly laundered nurse leading a little girl came into the room.\"},{\"heading\":false,\"text\":\"“Bles-sed pre-cious,” she crooned, holding out her arms. “Come to your own mother that loves you.”\"},{\"heading\":false,\"text\":\"The child, relinquished by the nurse, rushed across the room and rooted shyly into her mother’s dress.\"},{\"heading\":false,\"text\":\"“The bles-sed pre-cious! Did mother get powder on your old yellowy hair? Stand up now, and say—How-de-do.”\"},{\"heading\":false,\"text\":\"Gatsby and I in turn leaned down and took the small reluctant hand. Afterward he kept looking at the child with surprise. I don’t think he had ever really believed in its existence before.\"},{\"heading\":false,\"text\":\"“I got dressed before luncheon,” said the child, turning eagerly to Daisy.\"},{\"heading\":false,\"text\":\"“That’s because your mother wanted to show you off.” Her face bent into the single wrinkle of the small white neck. “You dream, you. You absolute little dream.”\"},{\"heading\":false,\"text\":\"“Yes,” admitted the child calmly. “Aunt Jordan’s got on a white dress too.”\"},{\"heading\":false,\"text\":\"“How do you like mother’s friends?” Daisy turned her around so that she faced Gatsby. “Do you think they’re pretty?”\"},{\"heading\":false,\"text\":\"“Where’s Daddy?”\"},{\"heading\":false,\"text\":\"“She doesn’t look like her father,” explained Daisy. “She looks like me. She’s got my hair and shape of the face.”\"},{\"heading\":false,\"text\":\"Daisy sat back upon the couch. The nurse took a step forward and held out her hand.\"},{\"heading\":false,\"text\":\"“Come, Pammy.”\"},{\"heading\":false,\"text\":\"“Goodbye, sweetheart!”\"},{\"heading\":false,\"text\":\"With a reluctant backward glance the well-disciplined child held to her nurse’s hand and was pulled out the door, just as Tom came back, preceding four gin rickeys that clicked full of ice.\"},{\"heading\":false,\"text\":\"Gatsby took up his drink.\"},{\"heading\":false,\"text\":\"“They certainly look cool,” he said, with visible tension.\"},{\"heading\":false,\"text\":\"We drank in long, greedy swallows.\"},{\"heading\":false,\"text\":\"“I read somewhere that the sun’s getting hotter every year,” said Tom genially. “It seems that pretty soon the earth’s going to fall into the sun—or wait a minute—it’s just the opposite—the sun’s getting colder every year.\"},{\"heading\":false,\"text\":\"“Come outside,” he suggested to Gatsby, “I’d like you to have a look at the place.”\"},{\"heading\":false,\"text\":\"I went with them out to the veranda. On the green Sound, stagnant in the heat, one small sail crawled slowly toward the fresher sea. Gatsby’s eyes followed it momentarily; he raised his hand and pointed across the bay.\"},{\"heading\":false,\"text\":\"“I’m right across from you.”\"},{\"heading\":false,\"text\":\"“So you are.”\"},{\"heading\":false,\"text\":\"Our eyes lifted over the rose-beds and the hot lawn and the weedy refuse of the dog-days alongshore. Slowly the white wings of the boat moved against the blue cool limit of the sky. Ahead lay the scalloped ocean and the abounding blessed isles.\"},{\"heading\":false,\"text\":\"“There’s sport for you,” said Tom, nodding. “I’d like to be out there with him for about an hour.”\"},{\"heading\":false,\"text\":\"We had luncheon in the dining-room, darkened too against the heat, and drank down nervous gaiety with the cold ale.\"},{\"heading\":false,\"text\":\"“What’ll we do with ourselves this afternoon?” cried Daisy, “and the day after that, and the next thirty years?”\"},{\"heading\":false,\"text\":\"“Don’t be morbid,” Jordan said. “Life starts all over again when it gets crisp in the fall.”\"},{\"heading\":false,\"text\":\"“But it’s so hot,” insisted Daisy, on the verge of tears, “and everything’s so confused. Let’s all go to town!”\"},{\"heading\":false,\"text\":\"Her voice struggled on through the heat, beating against it, moulding its senselessness into forms.\"},{\"heading\":false,\"text\":\"“I’ve heard of making a garage out of a stable,” Tom was saying to Gatsby, “but I’m the first man who ever made a stable out of a garage.”\"},{\"heading\":false,\"text\":\"“Who wants to go to town?” demanded Daisy insistently. Gatsby’s eyes floated toward her. “Ah,” she cried, “you look so cool.”\"},{\"heading\":false,\"text\":\"Their eyes met, and they stared together at each other, alone in space. With an effort she glanced down at the table.\"},{\"heading\":false,\"text\":\"“You always look so cool,” she repeated.\"},{\"heading\":false,\"text\":\"She had told him that she loved him, and Tom Buchanan saw. He was astounded. His mouth opened a little, and he looked at Gatsby, and then back at Daisy as if he had just recognized her as someone he knew a long time ago.\"},{\"heading\":false,\"text\":\"“You resemble the advertisement of the man,” she went on innocently. “You know the advertisement of the man—”\"},{\"heading\":false,\"text\":\"“All right,” broke in Tom quickly, “I’m perfectly willing to go to town. Come on—we’re all going to town.”\"},{\"heading\":false,\"text\":\"He got up, his eyes still flashing between Gatsby and his wife. No one moved.\"},{\"heading\":false,\"text\":\"“Come on!” His temper cracked a little. “What’s the matter, anyhow? If we’re going to town, let’s start.”\"},{\"heading\":false,\"text\":\"His hand, trembling with his effort at self-control, bore to his lips the last of his glass of ale. Daisy’s voice got us to our feet and out on to the blazing gravel drive.\"},{\"heading\":false,\"text\":\"“Are we just going to go?” she objected. “Like this? Aren’t we going to let anyone smoke a cigarette first?”\"},{\"heading\":false,\"text\":\"“Everybody smoked all through lunch.”\"},{\"heading\":false,\"text\":\"“Oh, let’s have fun,” she begged him. “It’s too hot to fuss.”\"},{\"heading\":false,\"text\":\"He didn’t answer.\"},{\"heading\":false,\"text\":\"“Have it your own way,” she said. “Come on, Jordan.”\"},{\"heading\":false,\"text\":\"They went upstairs to get ready while we three men stood there shuffling the hot pebbles with our feet. A silver curve of the moon hovered already in the western sky. Gatsby started to speak, changed his mind, but not before Tom wheeled and faced him expectantly.\"},{\"heading\":false,\"text\":\"“Have you got your stables here?” asked Gatsby with an effort.\"},{\"heading\":false,\"text\":\"“About a quarter of a mile down the road.”\"},{\"heading\":false,\"text\":\"“Oh.”\"},{\"heading\":false,\"text\":\"A pause.\"},{\"heading\":false,\"text\":\"“I don’t see the idea of going to town,” broke out Tom savagely. “Women get these notions in their heads—”\"},{\"heading\":false,\"text\":\"“Shall we take anything to drink?” called Daisy from an upper window.\"},{\"heading\":false,\"text\":\"“I’ll get some whisky,” answered Tom. He went inside.\"},{\"heading\":false,\"text\":\"Gatsby turned to me rigidly:\"},{\"heading\":false,\"text\":\"“I can’t say anything in his house, old sport.”\"},{\"heading\":false,\"text\":\"“She’s got an indiscreet voice,” I remarked. “It’s full of—” I hesitated.\"},{\"heading\":false,\"text\":\"“Her voice is full of money,” he said suddenly.\"},{\"heading\":false,\"text\":\"That was it. I’d never understood before. It was full of money—that was the inexhaustible charm that rose and fell in it, the jingle of it, the cymbals’ song of it… High in a white palace the king’s daughter, the golden girl…\"},{\"heading\":false,\"text\":\"Tom came out of the house wrapping a quart bottle in a towel, followed by Daisy and Jordan wearing small tight hats of metallic cloth and carrying light capes over their arms.\"},{\"heading\":false,\"text\":\"“Shall we all go in my car?” suggested Gatsby. He felt the hot, green leather of the seat. “I ought to have left it in the shade.”\"},{\"heading\":false,\"text\":\"“Is it standard shift?” demanded Tom.\"},{\"heading\":false,\"text\":\"“Yes.”\"},{\"heading\":false,\"text\":\"“Well, you take my coupé and let me drive your car to town.”\"},{\"heading\":false,\"text\":\"The suggestion was distasteful to Gatsby.\"},{\"heading\":false,\"text\":\"“I don’t think there’s much gas,” he objected.\"},{\"heading\":false,\"text\":\"“Plenty of gas,” said Tom boisterously. He looked at the gauge. “And if it runs out I can stop at a drugstore. You can buy anything at a drugstore nowadays.”\"},{\"heading\":false,\"text\":\"A pause followed this apparently pointless remark. Daisy looked at Tom frowning, and an indefinable expression, at once definitely unfamiliar and vaguely recognizable, as if I had only heard it described in words, passed over Gatsby’s face.\"},{\"heading\":false,\"text\":\"“Come on, Daisy,” said Tom, pressing her with his hand toward Gatsby’s car. “I’ll take you in this circus wagon.”\"},{\"heading\":false,\"text\":\"He opened the door, but she moved out from the circle of his arm.\"},{\"heading\":false,\"text\":\"“You take Nick and Jordan. We’ll follow you in the coupé.”\"},{\"heading\":false,\"text\":\"She walked close to Gatsby, touching his coat with her hand. Jordan and Tom and I got into the front seat of Gatsby’s car, Tom pushed the unfamiliar gears tentatively, and we shot off into the oppressive heat, leaving them out of sight behind.\"},{\"heading\":false,\"text\":\"“Did you see that?” demanded Tom.\"},{\"heading\":false,\"text\":\"“See what?”\"},{\"heading\":false,\"text\":\"He looked at me keenly, realizing that Jordan and I must have known all along.\"},{\"heading\":false,\"text\":\"“You think I’m pretty dumb, don’t you?” he suggested. “Perhaps I am, but I have a—almost a second sight, sometimes, that tells me what to do. Maybe you don’t believe that, but science—”\"},{\"heading\":false,\"text\":\"He paused. The immediate contingency overtook him, pulled him back from the edge of theoretical abyss.\"},{\"heading\":false,\"text\":\"“I’ve made a small investigation of this fellow,” he continued. “I could have gone deeper if I’d known—”\"},{\"heading\":false,\"text\":\"“Do you mean you’ve been to a medium?” inquired Jordan humorously.\"},{\"heading\":false,\"text\":\"“What?” Confused, he stared at us as we laughed. “A medium?”\"},{\"heading\":false,\"text\":\"“About Gatsby.”\"},{\"heading\":false,\"text\":\"“About Gatsby! No, I haven’t. I said I’d been making a small investigation of his past.”\"},{\"heading\":false,\"text\":\"“And you found he was an Oxford man,” said Jordan helpfully.\"},{\"heading\":false,\"text\":\"“An Oxford man!” He was incredulous. “Like hell he is! He wears a pink suit.”\"},{\"heading\":false,\"text\":\"“Nevertheless he’s an Oxford man.”\"},{\"heading\":false,\"text\":\"“Oxford, New Mexico,” snorted Tom contemptuously, “or something like that.”\"},{\"heading\":false,\"text\":\"“Listen, Tom. If you’re such a snob, why did you invite him to lunch?” demanded Jordan crossly.\"},{\"heading\":false,\"text\":\"“Daisy invited him; she knew him before we were married—God knows where!”\"},{\"heading\":false,\"text\":\"We were all irritable now with the fading ale, and aware of it we drove for a while in silence. Then as Doctor T. J. Eckleburg’s faded eyes came into sight down the road, I remembered Gatsby’s caution about gasoline.\"},{\"heading\":false,\"text\":\"“We’ve got enough to get us to town,” said Tom.\"},{\"heading\":false,\"text\":\"“But there’s a garage right here,” objected Jordan. “I don’t want to get stalled in this baking heat.”\"},{\"heading\":false,\"text\":\"Tom threw on both brakes impatiently, and we slid to an abrupt dusty stop under Wilson’s sign. After a moment the proprietor emerged from the interior of his establishment and gazed hollow-eyed at the car.\"},{\"heading\":false,\"text\":\"“Let’s have some gas!” cried Tom roughly. “What do you think we stopped for—to admire the view?”\"},{\"heading\":false,\"text\":\"“I’m sick,” said Wilson without moving. “Been sick all day.”\"},{\"heading\":false,\"text\":\"“What’s the matter?”\"},{\"heading\":false,\"text\":\"“I’m all run down.”\"},{\"heading\":false,\"text\":\"“Well, shall I help myself?” Tom demanded. “You sounded well enough on the phone.”\"},{\"heading\":false,\"text\":\"With an effort Wilson left the shade and support of the doorway and, breathing hard, unscrewed the cap of the tank. In the sunlight his face was green.\"},{\"heading\":false,\"text\":\"“I didn’t mean to interrupt your lunch,” he said. “But I need money pretty bad, and I was wondering what you were going to do with your old car.”\"},{\"heading\":false,\"text\":\"“How do you like this one?” inquired Tom. “I bought it last week.”\"},{\"heading\":false,\"text\":\"“It’s a nice yellow one,” said Wilson, as he strained at the handle.\"},{\"heading\":false,\"text\":\"“Like to buy it?”\"},{\"heading\":false,\"text\":\"“Big chance,” Wilson smiled faintly. “No, but I could make some money on the other.”\"},{\"heading\":false,\"text\":\"“What do you want money for, all of a sudden?”\"},{\"heading\":false,\"text\":\"“I’ve been here too long. I want to get away. My wife and I want to go West.”\"},{\"heading\":false,\"text\":\"“Your wife does,” exclaimed Tom, startled.\"},{\"heading\":false,\"text\":\"“She’s been talking about it for ten years.” He rested for a moment against the pump, shading his eyes. “And now she’s going whether she wants to or not. I’m going to get her away.”\"},{\"heading\":false,\"text\":\"The coupé flashed by us with a flurry of dust and the flash of a waving hand.\"},{\"heading\":false,\"text\":\"“What do I owe you?” demanded Tom harshly.\"},{\"heading\":false,\"text\":\"“I just got wised up to something funny the last two days,” remarked Wilson. “That’s why I want to get away. That’s why I been bothering you about the car.”\"},{\"heading\":false,\"text\":\"“What do I owe you?”\"},{\"heading\":false,\"text\":\"“Dollar twenty.”\"},{\"heading\":false,\"text\":\"The relentless beating heat was beginning to confuse me and I had a bad moment there before I realized that so far his suspicions hadn’t alighted on Tom. He had discovered that Myrtle had some sort of life apart from him in another world, and the shock had made him physically sick. I stared at him and then at Tom, who had made a parallel discovery less than an hour before—and it occurred to me that there was no difference between men, in intelligence or race, so profound as the difference between the sick and the well. Wilson was so sick that he looked guilty, unforgivably guilty—as if he had just got some poor girl with child.\"},{\"heading\":false,\"text\":\"“I’ll let you have that car,” said Tom. “I’ll send it over tomorrow afternoon.”\"},{\"heading\":false,\"text\":\"That locality was always vaguely disquieting, even in the broad glare of afternoon, and now I turned my head as though I had been warned of something behind. Over the ash-heaps the giant eyes of Doctor T. J. Eckleburg kept their vigil, but I perceived, after a moment, that other eyes were regarding us with peculiar intensity from less than twenty feet away.\"},{\"heading\":false,\"text\":\"In one of the windows over the garage the curtains had been moved aside a little, and Myrtle Wilson was peering down at the car. So engrossed was she that she had no consciousness of being observed, and one emotion after another crept into her face like objects into a slowly developing picture. Her expression was curiously familiar—it was an expression I had often seen on women’s faces, but on Myrtle Wilson’s face it seemed purposeless and inexplicable until I realized that her eyes, wide with jealous terror, were fixed not on Tom, but on Jordan Baker, whom she took to be his wife.\"},{\"heading\":false,\"text\":\"There is no confusion like the confusion of a simple mind, and as we drove away Tom was feeling the hot whips of panic. His wife and his mistress, until an hour ago secure and inviolate, were slipping precipitately from his control. Instinct made him step on the accelerator with the double purpose of overtaking Daisy and leaving Wilson behind, and we sped along toward Astoria at fifty miles an hour, until, among the spidery girders of the elevated, we came in sight of the easygoing blue coupé.\"},{\"heading\":false,\"text\":\"“Those big movies around Fiftieth Street are cool,” suggested Jordan. “I love New York on summer afternoons when everyone’s away. There’s something very sensuous about it—overripe, as if all sorts of funny fruits were going to fall into your hands.”\"},{\"heading\":false,\"text\":\"The word “sensuous” had the effect of further disquieting Tom, but before he could invent a protest the coupé came to a stop, and Daisy signalled us to draw up alongside.\"},{\"heading\":false,\"text\":\"“Where are we going?” she cried.\"},{\"heading\":false,\"text\":\"“How about the movies?”\"},{\"heading\":false,\"text\":\"“It’s so hot,” she complained. “You go. We’ll ride around and meet you after.” With an effort her wit rose faintly. “We’ll meet you on some corner. I’ll be the man smoking two cigarettes.”\"},{\"heading\":false,\"text\":\"“We can’t argue about it here,” Tom said impatiently, as a truck gave out a cursing whistle behind us. “You follow me to the south side of Central Park, in front of the Plaza.”\"},{\"heading\":false,\"text\":\"Several times he turned his head and looked back for their car, and if the traffic delayed them he slowed up until they came into sight. I think he was afraid they would dart down a side-street and out of his life forever.\"},{\"heading\":false,\"text\":\"But they didn’t. And we all took the less explicable step of engaging the parlour of a suite in the Plaza Hotel.\"},{\"heading\":false,\"text\":\"The prolonged and tumultuous argument that ended by herding us into that room eludes me, though I have a sharp physical memory that, in the course of it, my underwear kept climbing like a damp snake around my legs and intermittent beads of sweat raced cool across my back. The notion originated with Daisy’s suggestion that we hire five bathrooms and take cold baths, and then assumed more tangible form as “a place to have a mint julep.” Each of us said over and over that it was a “crazy idea”—we all talked at once to a baffled clerk and thought, or pretended to think, that we were being very funny…\"},{\"heading\":false,\"text\":\"The room was large and stifling, and, though it was already four o’clock, opening the windows admitted only a gust of hot shrubbery from the Park. Daisy went to the mirror and stood with her back to us, fixing her hair.\"},{\"heading\":false,\"text\":\"“It’s a swell suite,” whispered Jordan respectfully, and everyone laughed.\"},{\"heading\":false,\"text\":\"“Open another window,” commanded Daisy, without turning around.\"},{\"heading\":false,\"text\":\"“There aren’t any more.”\"},{\"heading\":false,\"text\":\"“Well, we’d better telephone for an axe—”\"},{\"heading\":false,\"text\":\"“The thing to do is to forget about the heat,” said Tom impatiently. “You make it ten times worse by crabbing about it.”\"},{\"heading\":false,\"text\":\"He unrolled the bottle of whisky from the towel and put it on the table.\"},{\"heading\":false,\"text\":\"“Why not let her alone, old sport?” remarked Gatsby. “You’re the one that wanted to come to town.”\"},{\"heading\":false,\"text\":\"There was a moment of silence. The telephone book slipped from its nail and splashed to the floor, whereupon Jordan whispered, “Excuse me”—but this time no one laughed.\"},{\"heading\":false,\"text\":\"“I’ll pick it up,” I offered.\"},{\"heading\":false,\"text\":\"“I’ve got it.” Gatsby examined the parted string, muttered “Hum!” in an interested way, and tossed the book on a chair.\"},{\"heading\":false,\"text\":\"“That’s a great expression of yours, isn’t it?” said Tom sharply.\"},{\"heading\":false,\"text\":\"“What is?”\"},{\"heading\":false,\"text\":\"“All this ‘old sport’ business. Where’d you pick that up?”\"},{\"heading\":false,\"text\":\"“Now see here, Tom,” said Daisy, turning around from the mirror, “if you’re going to make personal remarks I won’t stay here a minute. Call up and order some ice for the mint julep.”\"},{\"heading\":false,\"text\":\"As Tom took up the receiver the compressed heat exploded into sound and we were listening to the portentous chords of Mendelssohn’s Wedding March from the ballroom below.\"},{\"heading\":false,\"text\":\"“Imagine marrying anybody in this heat!” cried Jordan dismally.\"},{\"heading\":false,\"text\":\"“Still—I was married in the middle of June,” Daisy remembered. “Louisville in June! Somebody fainted. Who was it fainted, Tom?”\"},{\"heading\":false,\"text\":\"“Biloxi,” he answered shortly.\"},{\"heading\":false,\"text\":\"“A man named Biloxi. ‘Blocks’ Biloxi, and he made boxes—that’s a fact—and he was from Biloxi, Tennessee.”\"},{\"heading\":false,\"text\":\"“They carried him into my house,” appended Jordan, “because we lived just two doors from the church. And he stayed three weeks, until Daddy told him he had to get out. The day after he left Daddy died.” After a moment she added as if she might have sounded irreverent, “There wasn’t any connection.”\"},{\"heading\":false,\"text\":\"“I used to know a Bill Biloxi from Memphis,” I remarked.\"},{\"heading\":false,\"text\":\"“That was his cousin. I knew his whole family history before he left. He gave me an aluminium putter that I use today.”\"},{\"heading\":false,\"text\":\"The music had died down as the ceremony began and now a long cheer floated in at the window, followed by intermittent cries of “Yea—ea—ea!” and finally by a burst of jazz as the dancing began.\"},{\"heading\":false,\"text\":\"“We’re getting old,” said Daisy. “If we were young we’d rise and dance.”\"},{\"heading\":false,\"text\":\"“Remember Biloxi,” Jordan warned her. “Where’d you know him, Tom?”\"},{\"heading\":false,\"text\":\"“Biloxi?” He concentrated with an effort. “I didn’t know him. He was a friend of Daisy’s.”\"},{\"heading\":false,\"text\":\"“He was not,” she denied. “I’d never seen him before. He came down in the private car.”\"},{\"heading\":false,\"text\":\"“Well, he said he knew you. He said he was raised in Louisville. Asa Bird brought him around at the last minute and asked if we had room for him.”\"},{\"heading\":false,\"text\":\"Jordan smiled.\"},{\"heading\":false,\"text\":\"“He was probably bumming his way home. He told me he was president of your class at Yale.”\"},{\"heading\":false,\"text\":\"Tom and I looked at each other blankly.\"},{\"heading\":false,\"text\":\"“Biloxi?”\"},{\"heading\":false,\"text\":\"“First place, we didn’t have any president—”\"},{\"heading\":false,\"text\":\"Gatsby’s foot beat a short, restless tattoo and Tom eyed him suddenly.\"},{\"heading\":false,\"text\":\"“By the way, Mr. Gatsby, I understand you’re an Oxford man.”\"},{\"heading\":false,\"text\":\"“Not exactly.”\"},{\"heading\":false,\"text\":\"“Oh, yes, I understand you went to Oxford.”\"},{\"heading\":false,\"text\":\"“Yes—I went there.”\"},{\"heading\":false,\"text\":\"A pause. Then Tom’s voice, incredulous and insulting:\"},{\"heading\":false,\"text\":\"“You must have gone there about the time Biloxi went to New Haven.”\"},{\"heading\":false,\"text\":\"Another pause. A waiter knocked and came in with crushed mint and ice but the silence was unbroken by his “thank you” and the soft closing of the door. This tremendous detail was to be cleared up at last.\"},{\"heading\":false,\"text\":\"“I told you I went there,” said Gatsby.\"},{\"heading\":false,\"text\":\"“I heard you, but I’d like to know when.”\"},{\"heading\":false,\"text\":\"“It was in nineteen-nineteen, I only stayed five months. That’s why I can’t really call myself an Oxford man.”\"},{\"heading\":false,\"text\":\"Tom glanced around to see if we mirrored his unbelief. But we were all looking at Gatsby.\"},{\"heading\":false,\"text\":\"“It was an opportunity they gave to some of the officers after the armistice,” he continued. “We could go to any of the universities in England or France.”\"},{\"heading\":false,\"text\":\"I wanted to get up and slap him on the back. I had one of those renewals of complete faith in him that I’d experienced before.\"},{\"heading\":false,\"text\":\"Daisy rose, smiling faintly, and went to the table.\"},{\"heading\":false,\"text\":\"“Open the whisky, Tom,” she ordered, “and I’ll make you a mint julep. Then you won’t seem so stupid to yourself… Look at the mint!”\"},{\"heading\":false,\"text\":\"“Wait a minute,” snapped Tom, “I want to ask Mr. Gatsby one more question.”\"},{\"heading\":false,\"text\":\"“Go on,” Gatsby said politely.\"},{\"heading\":false,\"text\":\"“What kind of a row are you trying to cause in my house anyhow?”\"},{\"heading\":false,\"text\":\"They were out in the open at last and Gatsby was content.\"},{\"heading\":false,\"text\":\"“He isn’t causing a row,” Daisy looked desperately from one to the other. “You’re causing a row. Please have a little self-control.”\"},{\"heading\":false,\"text\":\"“Self-control!” repeated Tom incredulously. “I suppose the latest thing is to sit back and let Mr. Nobody from Nowhere make love to your wife. Well, if that’s the idea you can count me out… Nowadays people begin by sneering at family life and family institutions, and next they’ll throw everything overboard and have intermarriage between black and white.”\"},{\"heading\":false,\"text\":\"Flushed with his impassioned gibberish, he saw himself standing alone on the last barrier of civilization.\"},{\"heading\":false,\"text\":\"“We’re all white here,” murmured Jordan.\"},{\"heading\":false,\"text\":\"“I know I’m not very popular. I don’t give big parties. I suppose you’ve got to make your house into a pigsty in order to have any friends—in the modern world.”\"},{\"heading\":false,\"text\":\"Angry as I was, as we all were, I was tempted to laugh whenever he opened his mouth. The transition from libertine to prig was so complete.\"},{\"heading\":false,\"text\":\"“I’ve got something to tell you, old sport—” began Gatsby. But Daisy guessed at his intention.\"},{\"heading\":false,\"text\":\"“Please don’t!” she interrupted helplessly. “Please let’s all go home. Why don’t we all go home?”\"},{\"heading\":false,\"text\":\"“That’s a good idea,” I got up. “Come on, Tom. Nobody wants a drink.”\"},{\"heading\":false,\"text\":\"“I want to know what Mr. Gatsby has to tell me.”\"},{\"heading\":false,\"text\":\"“Your wife doesn’t love you,” said Gatsby. “She’s never loved you. She loves me.”\"},{\"heading\":false,\"text\":\"“You must be crazy!” exclaimed Tom automatically.\"},{\"heading\":false,\"text\":\"Gatsby sprang to his feet, vivid with excitement.\"},{\"heading\":false,\"text\":\"“She never loved you, do you hear?” he cried. “She only married you because I was poor and she was tired of waiting for me. It was a terrible mistake, but in her heart she never loved anyone except me!”\"},{\"heading\":false,\"text\":\"At this point Jordan and I tried to go, but Tom and Gatsby insisted with competitive firmness that we remain—as though neither of them had anything to conceal and it would be a privilege to partake vicariously of their emotions.\"},{\"heading\":false,\"text\":\"“Sit down, Daisy,” Tom’s voice groped unsuccessfully for the paternal note. “What’s been going on? I want to hear all about it.”\"},{\"heading\":false,\"text\":\"“I told you what’s been going on,” said Gatsby. “Going on for five years—and you didn’t know.”\"},{\"heading\":false,\"text\":\"Tom turned to Daisy sharply.\"},{\"heading\":false,\"text\":\"“You’ve been seeing this fellow for five years?”\"},{\"heading\":false,\"text\":\"“Not seeing,” said Gatsby. “No, we couldn’t meet. But both of us loved each other all that time, old sport, and you didn’t know. I used to laugh sometimes”—but there was no laughter in his eyes—“to think that you didn’t know.”\"},{\"heading\":false,\"text\":\"“Oh—that’s all.” Tom tapped his thick fingers together like a clergyman and leaned back in his chair.\"},{\"heading\":false,\"text\":\"“You’re crazy!” he exploded. “I can’t speak about what happened five years ago, because I didn’t know Daisy then—and I’ll be damned if I see how you got within a mile of her unless you brought the groceries to the back door. But all the rest of that’s a God damned lie. Daisy loved me when she married me and she loves me now.”\"},{\"heading\":false,\"text\":\"“No,” said Gatsby, shaking his head.\"},{\"heading\":false,\"text\":\"“She does, though. The trouble is that sometimes she gets foolish ideas in her head and doesn’t know what she’s doing.” He nodded sagely. “And what’s more, I love Daisy too. Once in a while I go off on a spree and make a fool of myself, but I always come back, and in my heart I love her all the time.”\"},{\"heading\":false,\"text\":\"“You’re revolting,” said Daisy. She turned to me, and her voice, dropping an octave lower, filled the room with thrilling scorn: “Do you know why we left Chicago? I’m surprised that they didn’t treat you to the story of that little spree.”\"},{\"heading\":false,\"text\":\"Gatsby walked over and stood beside her.\"},{\"heading\":false,\"text\":\"“Daisy, that’s all over now,” he said earnestly. “It doesn’t matter any more. Just tell him the truth—that you never loved him—and it’s all wiped out forever.”\"},{\"heading\":false,\"text\":\"She looked at him blindly. “Why—how could I love him—possibly?”\"},{\"heading\":false,\"text\":\"“You never loved him.”\"},{\"heading\":false,\"text\":\"She hesitated. Her eyes fell on Jordan and me with a sort of appeal, as though she realized at last what she was doing—and as though she had never, all along, intended doing anything at all. But it was done now. It was too late.\"},{\"heading\":false,\"text\":\"“I never loved him,” she said, with perceptible reluctance.\"},{\"heading\":false,\"text\":\"“Not at Kapiolani?” demanded Tom suddenly.\"},{\"heading\":false,\"text\":\"“No.”\"},{\"heading\":false,\"text\":\"From the ballroom beneath, muffled and suffocating chords were drifting up on hot waves of air.\"},{\"heading\":false,\"text\":\"“Not that day I carried you down from the Punch Bowl to keep your shoes dry?” There was a husky tenderness in his tone… “Daisy?”\"},{\"heading\":false,\"text\":\"“Please don’t.” Her voice was cold, but the rancour was gone from it. She looked at Gatsby. “There, Jay,” she said—but her hand as she tried to light a cigarette was trembling. Suddenly she threw the cigarette and the burning match on the carpet.\"},{\"heading\":false,\"text\":\"“Oh, you want too much!” she cried to Gatsby. “I love you now—isn’t that enough? I can’t help what’s past.” She began to sob helplessly. “I did love him once—but I loved you too.”\"},{\"heading\":false,\"text\":\"Gatsby’s eyes opened and closed.\"},{\"heading\":false,\"text\":\"“You loved me too?” he repeated.\"},{\"heading\":false,\"text\":\"“Even that’s a lie,” said Tom savagely. “She didn’t know you were alive. Why—there’s things between Daisy and me that you’ll never know, things that neither of us can ever forget.”\"},{\"heading\":false,\"text\":\"The words seemed to bite physically into Gatsby.\"},{\"heading\":false,\"text\":\"“I want to speak to Daisy alone,” he insisted. “She’s all excited now—”\"},{\"heading\":false,\"text\":\"“Even alone I can’t say I never loved Tom,” she admitted in a pitiful voice. “It wouldn’t be true.”\"},{\"heading\":false,\"text\":\"“Of course it wouldn’t,” agreed Tom.\"},{\"heading\":false,\"text\":\"She turned to her husband.\"},{\"heading\":false,\"text\":\"“As if it mattered to you,” she said.\"},{\"heading\":false,\"text\":\"“Of course it matters. I’m going to take better care of you from now on.”\"},{\"heading\":false,\"text\":\"“You don’t understand,” said Gatsby, with a touch of panic. “You’re not going to take care of her any more.”\"},{\"heading\":false,\"text\":\"“I’m not?” Tom opened his eyes wide and laughed. He could afford to control himself now. “Why’s that?”\"},{\"heading\":false,\"text\":\"“Daisy’s leaving you.”\"},{\"heading\":false,\"text\":\"“Nonsense.”\"},{\"heading\":false,\"text\":\"“I am, though,” she said with a visible effort.\"},{\"heading\":false,\"text\":\"“She’s not leaving me!” Tom’s words suddenly leaned down over Gatsby. “Certainly not for a common swindler who’d have to steal the ring he put on her finger.”\"},{\"heading\":false,\"text\":\"“I won’t stand this!” cried Daisy. “Oh, please let’s get out.”\"},{\"heading\":false,\"text\":\"“Who are you, anyhow?” broke out Tom. “You’re one of that bunch that hangs around with Meyer Wolfshiem—that much I happen to know. I’ve made a little investigation into your affairs—and I’ll carry it further tomorrow.”\"},{\"heading\":false,\"text\":\"“You can suit yourself about that, old sport,” said Gatsby steadily.\"},{\"heading\":false,\"text\":\"“I found out what your ‘drugstores’ were.” He turned to us and spoke rapidly. “He and this Wolfshiem bought up a lot of side-street drugstores here and in Chicago and sold grain alcohol over the counter. That’s one of his little stunts. I picked him for a bootlegger the first time I saw him, and I wasn’t far wrong.”\"},{\"heading\":false,\"text\":\"“What about it?” said Gatsby politely. “I guess your friend Walter Chase wasn’t too proud to come in on it.”\"},{\"heading\":false,\"text\":\"“And you left him in the lurch, didn’t you? You let him go to jail for a month over in New Jersey. God! You ought to hear Walter on the subject of you.”\"},{\"heading\":false,\"text\":\"“He came to us dead broke. He was very glad to pick up some money, old sport.”\"},{\"heading\":false,\"text\":\"“Don’t you call me ‘old sport’!” cried Tom. Gatsby said nothing. “Walter could have you up on the betting laws too, but Wolfshiem scared him into shutting his mouth.”\"},{\"heading\":false,\"text\":\"That unfamiliar yet recognizable look was back again in Gatsby’s face.\"},{\"heading\":false,\"text\":\"“That drugstore business was just small change,” continued Tom slowly, “but you’ve got something on now that Walter’s afraid to tell me about.”\"},{\"heading\":false,\"text\":\"I glanced at Daisy, who was staring terrified between Gatsby and her husband, and at Jordan, who had begun to balance an invisible but absorbing object on the tip of her chin. Then I turned back to Gatsby—and was startled at his expression. He looked—and this is said in all contempt for the babbled slander of his garden—as if he had “killed a man.” For a moment the set of his face could be described in just that fantastic way.\"},{\"heading\":false,\"text\":\"It passed, and he began to talk excitedly to Daisy, denying everything, defending his name against accusations that had not been made. But with every word she was drawing further and further into herself, so he gave that up, and only the dead dream fought on as the afternoon slipped away, trying to touch what was no longer tangible, struggling unhappily, undespairingly, toward that lost voice across the room.\"},{\"heading\":false,\"text\":\"The voice begged again to go.\"},{\"heading\":false,\"text\":\"“Please, Tom! I can’t stand this any more.”\"},{\"heading\":false,\"text\":\"Her frightened eyes told that whatever intentions, whatever courage she had had, were definitely gone.\"},{\"heading\":false,\"text\":\"“You two start on home, Daisy,” said Tom. “In Mr. Gatsby’s car.”\"},{\"heading\":false,\"text\":\"She looked at Tom, alarmed now, but he insisted with magnanimous scorn.\"},{\"heading\":false,\"text\":\"“Go on. He won’t annoy you. I think he realizes that his presumptuous little flirtation is over.”\"},{\"heading\":false,\"text\":\"They were gone, without a word, snapped out, made accidental, isolated, like ghosts, even from our pity.\"},{\"heading\":false,\"text\":\"After a moment Tom got up and began wrapping the unopened bottle of whisky in the towel.\"},{\"heading\":false,\"text\":\"“Want any of this stuff? Jordan?… Nick?”\"},{\"heading\":false,\"text\":\"I didn’t answer.\"},{\"heading\":false,\"text\":\"“Nick?” He asked again.\"},{\"heading\":false,\"text\":\"“What?”\"},{\"heading\":false,\"text\":\"“Want any?”\"},{\"heading\":false,\"text\":\"“No… I just remembered that today’s my birthday.”\"},{\"heading\":false,\"text\":\"I was thirty. Before me stretched the portentous, menacing road of a new decade.\"},{\"heading\":false,\"text\":\"It was seven o’clock when we got into the coupé with him and started for Long Island. Tom talked incessantly, exulting and laughing, but his voice was as remote from Jordan and me as the foreign clamour on the sidewalk or the tumult of the elevated overhead. Human sympathy has its limits, and we were content to let all their tragic arguments fade with the city lights behind. Thirty—the promise of a decade of loneliness, a thinning list of single men to know, a thinning briefcase of enthusiasm, thinning hair. But there was Jordan beside me, who, unlike Daisy, was too wise ever to carry well-forgotten dreams from age to age. As we passed over the dark bridge her wan face fell lazily against my coat’s shoulder and the formidable stroke of thirty died away with the reassuring pressure of her hand.\"},{\"heading\":false,\"text\":\"So we drove on toward death through the cooling twilight.\"},{\"heading\":false,\"text\":\"The young Greek, Michaelis, who ran the coffee joint beside the ash-heaps was the principal witness at the inquest. He had slept through the heat until after five, when he strolled over to the garage, and found George Wilson sick in his office—really sick, pale as his own pale hair and shaking all over. Michaelis advised him to go to bed, but Wilson refused, saying that he’d miss a lot of business if he did. While his neighbour was trying to persuade him a violent racket broke out overhead.\"},{\"heading\":false,\"text\":\"“I’ve got my wife locked in up there,” explained Wilson calmly. “She’s going to stay there till the day after tomorrow, and then we’re going to move away.”\"},{\"heading\":false,\"text\":\"Michaelis was astonished; they had been neighbours for four years, and Wilson had never seemed faintly capable of such a statement. Generally he was one of these worn-out men: when he wasn’t working, he sat on a chair in the doorway and stared at the people and the cars that passed along the road. When anyone spoke to him he invariably laughed in an agreeable, colourless way. He was his wife’s man and not his own.\"},{\"heading\":false,\"text\":\"So naturally Michaelis tried to find out what had happened, but Wilson wouldn’t say a word—instead he began to throw curious, suspicious glances at his visitor and ask him what he’d been doing at certain times on certain days. Just as the latter was getting uneasy, some workmen came past the door bound for his restaurant, and Michaelis took the opportunity to get away, intending to come back later. But he didn’t. He supposed he forgot to, that’s all. When he came outside again, a little after seven, he was reminded of the conversation because he heard Mrs. Wilson’s voice, loud and scolding, downstairs in the garage.\"},{\"heading\":false,\"text\":\"“Beat me!” he heard her cry. “Throw me down and beat me, you dirty little coward!”\"},{\"heading\":false,\"text\":\"A moment later she rushed out into the dusk, waving her hands and shouting—before he could move from his door the business was over.\"},{\"heading\":false,\"text\":\"The “death car” as the newspapers called it, didn’t stop; it came out of the gathering darkness, wavered tragically for a moment, and then disappeared around the next bend. Mavro Michaelis wasn’t even sure of its colour—he told the first policeman that it was light green. The other car, the one going toward New York, came to rest a hundred yards beyond, and its driver hurried back to where Myrtle Wilson, her life violently extinguished, knelt in the road and mingled her thick dark blood with the dust.\"},{\"heading\":false,\"text\":\"Michaelis and this man reached her first, but when they had torn open her shirtwaist, still damp with perspiration, they saw that her left breast was swinging loose like a flap, and there was no need to listen for the heart beneath. The mouth was wide open and ripped a little at the corners, as though she had choked a little in giving up the tremendous vitality she had stored so long.\"},{\"heading\":false,\"text\":\"We saw the three or four automobiles and the crowd when we were still some distance away.\"},{\"heading\":false,\"text\":\"“Wreck!” said Tom. “That’s good. Wilson’ll have a little business at last.”\"},{\"heading\":false,\"text\":\"He slowed down, but still without any intention of stopping, until, as we came nearer, the hushed, intent faces of the people at the garage door made him automatically put on the brakes.\"},{\"heading\":false,\"text\":\"“We’ll take a look,” he said doubtfully, “just a look.”\"},{\"heading\":false,\"text\":\"I became aware now of a hollow, wailing sound which issued incessantly from the garage, a sound which as we got out of the coupé and walked toward the door resolved itself into the words “Oh, my God!” uttered over and over in a gasping moan.\"},{\"heading\":false,\"text\":\"“There’s some bad trouble here,” said Tom excitedly.\"},{\"heading\":false,\"text\":\"He reached up on tiptoes and peered over a circle of heads into the garage, which was lit only by a yellow light in a swinging metal basket overhead. Then he made a harsh sound in his throat, and with a violent thrusting movement of his powerful arms pushed his way through.\"},{\"heading\":false,\"text\":\"The circle closed up again with a running murmur of expostulation; it was a minute before I could see anything at all. Then new arrivals deranged the line, and Jordan and I were pushed suddenly inside.\"},{\"heading\":false,\"text\":\"Myrtle Wilson’s body, wrapped in a blanket, and then in another blanket, as though she suffered from a chill in the hot night, lay on a worktable by the wall, and Tom, with his back to us, was bending over it, motionless. Next to him stood a motorcycle policeman taking down names with much sweat and correction in a little book. At first I couldn’t find the source of the high, groaning words that echoed clamorously through the bare garage—then I saw Wilson standing on the raised threshold of his office, swaying back and forth and holding to the doorposts with both hands. Some man was talking to him in a low voice and attempting, from time to time, to lay a hand on his shoulder, but Wilson neither heard nor saw. His eyes would drop slowly from the swinging light to the laden table by the wall, and then jerk back to the light again, and he gave out incessantly his high, horrible call:\"},{\"heading\":false,\"text\":\"“Oh, my Ga-od! Oh, my Ga-od! Oh, Ga-od! Oh, my Ga-od!”\"},{\"heading\":false,\"text\":\"Presently Tom lifted his head with a jerk and, after staring around the garage with glazed eyes, addressed a mumbled incoherent remark to the policeman.\"},{\"heading\":false,\"text\":\"“M-a-v—” the policeman was saying, “—o—”\"},{\"heading\":false,\"text\":\"“No, r—” corrected the man, “M-a-v-r-o—”\"},{\"heading\":false,\"text\":\"“Listen to me!” muttered Tom fiercely.\"},{\"heading\":false,\"text\":\"“r—” said the policeman, “o—”\"},{\"heading\":false,\"text\":\"“g—”\"},{\"heading\":false,\"text\":\"“g—” He looked up as Tom’s broad hand fell sharply on his shoulder. “What you want, fella?”\"},{\"heading\":false,\"text\":\"“What happened?—that’s what I want to know.”\"},{\"heading\":false,\"text\":\"“Auto hit her. Ins’antly killed.”\"},{\"heading\":false,\"text\":\"“Instantly killed,” repeated Tom, staring.\"},{\"heading\":false,\"text\":\"“She ran out ina road. Son-of-a-bitch didn’t even stopus car.”\"},{\"heading\":false,\"text\":\"“There was two cars,” said Michaelis, “one comin’, one goin’, see?”\"},{\"heading\":false,\"text\":\"“Going where?” asked the policeman keenly.\"},{\"heading\":false,\"text\":\"“One goin’ each way. Well, she”—his hand rose toward the blankets but stopped halfway and fell to his side—“she ran out there an’ the one comin’ from N’York knock right into her, goin’ thirty or forty miles an hour.”\"},{\"heading\":false,\"text\":\"“What’s the name of this place here?” demanded the officer.\"},{\"heading\":false,\"text\":\"“Hasn’t got any name.”\"},{\"heading\":false,\"text\":\"A pale well-dressed negro stepped near.\"},{\"heading\":false,\"text\":\"“It was a yellow car,” he said, “big yellow car. New.”\"},{\"heading\":false,\"text\":\"“See the accident?” asked the policeman.\"},{\"heading\":false,\"text\":\"“No, but the car passed me down the road, going faster’n forty. Going fifty, sixty.”\"},{\"heading\":false,\"text\":\"“Come here and let’s have your name. Look out now. I want to get his name.”\"},{\"heading\":false,\"text\":\"Some words of this conversation must have reached Wilson, swaying in the office door, for suddenly a new theme found voice among his grasping cries:\"},{\"heading\":false,\"text\":\"“You don’t have to tell me what kind of car it was! I know what kind of car it was!”\"},{\"heading\":false,\"text\":\"Watching Tom, I saw the wad of muscle back of his shoulder tighten under his coat. He walked quickly over to Wilson and, standing in front of him, seized him firmly by the upper arms.\"},{\"heading\":false,\"text\":\"“You’ve got to pull yourself together,” he said with soothing gruffness.\"},{\"heading\":false,\"text\":\"Wilson’s eyes fell upon Tom; he started up on his tiptoes and then would have collapsed to his knees had not Tom held him upright.\"},{\"heading\":false,\"text\":\"“Listen,” said Tom, shaking him a little. “I just got here a minute ago, from New York. I was bringing you that coupé we’ve been talking about. That yellow car I was driving this afternoon wasn’t mine—do you hear? I haven’t seen it all afternoon.”\"},{\"heading\":false,\"text\":\"Only the negro and I were near enough to hear what he said, but the policeman caught something in the tone and looked over with truculent eyes.\"},{\"heading\":false,\"text\":\"“What’s all that?” he demanded.\"},{\"heading\":false,\"text\":\"“I’m a friend of his.” Tom turned his head but kept his hands firm on Wilson’s body. “He says he knows the car that did it… It was a yellow car.”\"},{\"heading\":false,\"text\":\"Some dim impulse moved the policeman to look suspiciously at Tom.\"},{\"heading\":false,\"text\":\"“And what colour’s your car?”\"},{\"heading\":false,\"text\":\"“It’s a blue car, a coupé.”\"},{\"heading\":false,\"text\":\"“We’ve come straight from New York,” I said.\"},{\"heading\":false,\"text\":\"Someone who had been driving a little behind us confirmed this, and the policeman turned away.\"},{\"heading\":false,\"text\":\"“Now, if you’ll let me have that name again correct—”\"},{\"heading\":false,\"text\":\"Picking up Wilson like a doll, Tom carried him into the office, set him down in a chair, and came back.\"},{\"heading\":false,\"text\":\"“If somebody’ll come here and sit with him,” he snapped authoritatively. He watched while the two men standing closest glanced at each other and went unwillingly into the room. Then Tom shut the door on them and came down the single step, his eyes avoiding the table. As he passed close to me he whispered: “Let’s get out.”\"},{\"heading\":false,\"text\":\"Self-consciously, with his authoritative arms breaking the way, we pushed through the still gathering crowd, passing a hurried doctor, case in hand, who had been sent for in wild hope half an hour ago.\"},{\"heading\":false,\"text\":\"Tom drove slowly until we were beyond the bend—then his foot came down hard, and the coupé raced along through the night. In a little while I heard a low husky sob, and saw that the tears were overflowing down his face.\"},{\"heading\":false,\"text\":\"“The God damned coward!” he whimpered. “He didn’t even stop his car.”\"},{\"heading\":false,\"text\":\"The Buchanans’ house floated suddenly toward us through the dark rustling trees. Tom stopped beside the porch and looked up at the second floor, where two windows bloomed with light among the vines.\"},{\"heading\":false,\"text\":\"“Daisy’s home,” he said. As we got out of the car he glanced at me and frowned slightly.\"},{\"heading\":false,\"text\":\"“I ought to have dropped you in West Egg, Nick. There’s nothing we can do tonight.”\"},{\"heading\":false,\"text\":\"A change had come over him, and he spoke gravely, and with decision. As we walked across the moonlight gravel to the porch he disposed of the situation in a few brisk phrases.\"},{\"heading\":false,\"text\":\"“I’ll telephone for a taxi to take you home, and while you’re waiting you and Jordan better go in the kitchen and have them get you some supper—if you want any.” He opened the door. “Come in.”\"},{\"heading\":false,\"text\":\"“No, thanks. But I’d be glad if you’d order me the taxi. I’ll wait outside.”\"},{\"heading\":false,\"text\":\"Jordan put her hand on my arm.\"},{\"heading\":false,\"text\":\"“Won’t you come in, Nick?”\"},{\"heading\":false,\"text\":\"“No, thanks.”\"},{\"heading\":false,\"text\":\"I was feeling a little sick and I wanted to be alone. But Jordan lingered for a moment more.\"},{\"heading\":false,\"text\":\"“It’s only half-past nine,” she said.\"},{\"heading\":false,\"text\":\"I’d be damned if I’d go in; I’d had enough of all of them for one day, and suddenly that included Jordan too. She must have seen something of this in my expression, for she turned abruptly away and ran up the porch steps into the house. I sat down for a few minutes with my head in my hands, until I heard the phone taken up inside and the butler’s voice calling a taxi. Then I walked slowly down the drive away from the house, intending to wait by the gate.\"},{\"heading\":false,\"text\":\"I hadn’t gone twenty yards when I heard my name and Gatsby stepped from between two bushes into the path. I must have felt pretty weird by that time, because I could think of nothing except the luminosity of his pink suit under the moon.\"},{\"heading\":false,\"text\":\"“What are you doing?” I inquired.\"},{\"heading\":false,\"text\":\"“Just standing here, old sport.”\"},{\"heading\":false,\"text\":\"Somehow, that seemed a despicable occupation. For all I knew he was going to rob the house in a moment; I wouldn’t have been surprised to see sinister faces, the faces of “Wolfshiem’s people,” behind him in the dark shrubbery.\"},{\"heading\":false,\"text\":\"“Did you see any trouble on the road?” he asked after a minute.\"},{\"heading\":false,\"text\":\"“Yes.”\"},{\"heading\":false,\"text\":\"He hesitated.\"},{\"heading\":false,\"text\":\"“Was she killed?”\"},{\"heading\":false,\"text\":\"“Yes.”\"},{\"heading\":false,\"text\":\"“I thought so; I told Daisy I thought so. It’s better that the shock should all come at once. She stood it pretty well.”\"},{\"heading\":false,\"text\":\"He spoke as if Daisy’s reaction was the only thing that mattered.\"},{\"heading\":false,\"text\":\"“I got to West Egg by a side road,” he went on, “and left the car in my garage. I don’t think anybody saw us, but of course I can’t be sure.”\"},{\"heading\":false,\"text\":\"I disliked him so much by this time that I didn’t find it necessary to tell him he was wrong.\"},{\"heading\":false,\"text\":\"“Who was the woman?” he inquired.\"},{\"heading\":false,\"text\":\"“Her name was Wilson. Her husband owns the garage. How the devil did it happen?”\"},{\"heading\":false,\"text\":\"“Well, I tried to swing the wheel—” He broke off, and suddenly I guessed at the truth.\"},{\"heading\":false,\"text\":\"“Was Daisy driving?”\"},{\"heading\":false,\"text\":\"“Yes,” he said after a moment, “but of course I’ll say I was. You see, when we left New York she was very nervous and she thought it would steady her to drive—and this woman rushed out at us just as we were passing a car coming the other way. It all happened in a minute, but it seemed to me that she wanted to speak to us, thought we were somebody she knew. Well, first Daisy turned away from the woman toward the other car, and then she lost her nerve and turned back. The second my hand reached the wheel I felt the shock—it must have killed her instantly.”\"},{\"heading\":false,\"text\":\"“It ripped her open—”\"},{\"heading\":false,\"text\":\"“Don’t tell me, old sport.” He winced. “Anyhow—Daisy stepped on it. I tried to make her stop, but she couldn’t, so I pulled on the emergency brake. Then she fell over into my lap and I drove on.\"},{\"heading\":false,\"text\":\"“She’ll be all right tomorrow,” he said presently. “I’m just going to wait here and see if he tries to bother her about that unpleasantness this afternoon. She’s locked herself into her room, and if he tries any brutality she’s going to turn the light out and on again.”\"},{\"heading\":false,\"text\":\"“He won’t touch her,” I said. “He’s not thinking about her.”\"},{\"heading\":false,\"text\":\"“I don’t trust him, old sport.”\"},{\"heading\":false,\"text\":\"“How long are you going to wait?”\"},{\"heading\":false,\"text\":\"“All night, if necessary. Anyhow, till they all go to bed.”\"},{\"heading\":false,\"text\":\"A new point of view occurred to me. Suppose Tom found out that Daisy had been driving. He might think he saw a connection in it—he might think anything. I looked at the house; there were two or three bright windows downstairs and the pink glow from Daisy’s room on the ground floor.\"},{\"heading\":false,\"text\":\"“You wait here,” I said. “I’ll see if there’s any sign of a commotion.”\"},{\"heading\":false,\"text\":\"I walked back along the border of the lawn, traversed the gravel softly, and tiptoed up the veranda steps. The drawing-room curtains were open, and I saw that the room was empty. Crossing the porch where we had dined that June night three months before, I came to a small rectangle of light which I guessed was the pantry window. The blind was drawn, but I found a rift at the sill.\"},{\"heading\":false,\"text\":\"Daisy and Tom were sitting opposite each other at the kitchen table, with a plate of cold fried chicken between them, and two bottles of ale. He was talking intently across the table at her, and in his earnestness his hand had fallen upon and covered her own. Once in a while she looked up at him and nodded in agreement.\"},{\"heading\":false,\"text\":\"They weren’t happy, and neither of them had touched the chicken or the ale—and yet they weren’t unhappy either. There was an unmistakable air of natural intimacy about the picture, and anybody would have said that they were conspiring together.\"},{\"heading\":false,\"text\":\"As I tiptoed from the porch I heard my taxi feeling its way along the dark road toward the house. Gatsby was waiting where I had left him in the drive.\"},{\"heading\":false,\"text\":\"“Is it all quiet up there?” he asked anxiously.\"},{\"heading\":false,\"text\":\"“Yes, it’s all quiet.” I hesitated. “You’d better come home and get some sleep.”\"},{\"heading\":false,\"text\":\"He shook his head.\"},{\"heading\":false,\"text\":\"“I want to wait here till Daisy goes to bed. Good night, old sport.”\"},{\"heading\":false,\"text\":\"He put his hands in his coat pockets and turned back eagerly to his scrutiny of the house, as though my presence marred the sacredness of the vigil. So I walked away and left him standing there in the moonlight—watching over nothing.\"}]},{\"title\":\"VIII\",\"blocks\":[{\"heading\":false,\"text\":\"I couldn’t sleep all night; a foghorn was groaning incessantly on the Sound, and I tossed half-sick between grotesque reality and savage, frightening dreams. Toward dawn I heard a taxi go up Gatsby’s drive, and immediately I jumped out of bed and began to dress—I felt that I had something to tell him, something to warn him about, and morning would be too late.\"},{\"heading\":false,\"text\":\"Crossing his lawn, I saw that his front door was still open and he was leaning against a table in the hall, heavy with dejection or sleep.\"},{\"heading\":false,\"text\":\"“Nothing happened,” he said wanly. “I waited, and about four o’clock she came to the window and stood there for a minute and then turned out the light.”\"},{\"heading\":false,\"text\":\"His house had never seemed so enormous to me as it did that night when we hunted through the great rooms for cigarettes. We pushed aside curtains that were like pavilions, and felt over innumerable feet of dark wall for electric light switches—once I tumbled with a sort of splash upon the keys of a ghostly piano. There was an inexplicable amount of dust everywhere, and the rooms were musty, as though they hadn’t been aired for many days. I found the humidor on an unfamiliar table, with two stale, dry cigarettes inside. Throwing open the French windows of the drawing-room, we sat smoking out into the darkness.\"},{\"heading\":false,\"text\":\"“You ought to go away,” I said. “It’s pretty certain they’ll trace your car.”\"},{\"heading\":false,\"text\":\"“Go away now, old sport?”\"},{\"heading\":false,\"text\":\"“Go to Atlantic City for a week, or up to Montreal.”\"},{\"heading\":false,\"text\":\"He wouldn’t consider it. He couldn’t possibly leave Daisy until he knew what she was going to do. He was clutching at some last hope and I couldn’t bear to shake him free.\"},{\"heading\":false,\"text\":\"It was this night that he told me the strange story of his youth with Dan Cody—told it to me because “Jay Gatsby” had broken up like glass against Tom’s hard malice, and the long secret extravaganza was played out. I think that he would have acknowledged anything now, without reserve, but he wanted to talk about Daisy.\"},{\"heading\":false,\"text\":\"She was the first “nice” girl he had ever known. In various unrevealed capacities he had come in contact with such people, but always with indiscernible barbed wire between. He found her excitingly desirable. He went to her house, at first with other officers from Camp Taylor, then alone. It amazed him—he had never been in such a beautiful house before. But what gave it an air of breathless intensity, was that Daisy lived there—it was as casual a thing to her as his tent out at camp was to him. There was a ripe mystery about it, a hint of bedrooms upstairs more beautiful and cool than other bedrooms, of gay and radiant activities taking place through its corridors, and of romances that were not musty and laid away already in lavender but fresh and breathing and redolent of this year’s shining motorcars and of dances whose flowers were scarcely withered. It excited him, too, that many men had already loved Daisy—it increased her value in his eyes. He felt their presence all about the house, pervading the air with the shades and echoes of still vibrant emotions.\"},{\"heading\":false,\"text\":\"But he knew that he was in Daisy’s house by a colossal accident. However glorious might be his future as Jay Gatsby, he was at present a penniless young man without a past, and at any moment the invisible cloak of his uniform might slip from his shoulders. So he made the most of his time. He took what he could get, ravenously and unscrupulously—eventually he took Daisy one still October night, took her because he had no real right to touch her hand.\"},{\"heading\":false,\"text\":\"He might have despised himself, for he had certainly taken her under false pretences. I don’t mean that he had traded on his phantom millions, but he had deliberately given Daisy a sense of security; he let her believe that he was a person from much the same strata as herself—that he was fully able to take care of her. As a matter of fact, he had no such facilities—he had no comfortable family standing behind him, and he was liable at the whim of an impersonal government to be blown anywhere about the world.\"},{\"heading\":false,\"text\":\"But he didn’t despise himself and it didn’t turn out as he had imagined. He had intended, probably, to take what he could and go—but now he found that he had committed himself to the following of a grail. He knew that Daisy was extraordinary, but he didn’t realize just how extraordinary a “nice” girl could be. She vanished into her rich house, into her rich, full life, leaving Gatsby—nothing. He felt married to her, that was all.\"},{\"heading\":false,\"text\":\"When they met again, two days later, it was Gatsby who was breathless, who was, somehow, betrayed. Her porch was bright with the bought luxury of star-shine; the wicker of the settee squeaked fashionably as she turned toward him and he kissed her curious and lovely mouth. She had caught a cold, and it made her voice huskier and more charming than ever, and Gatsby was overwhelmingly aware of the youth and mystery that wealth imprisons and preserves, of the freshness of many clothes, and of Daisy, gleaming like silver, safe and proud above the hot struggles of the poor.\"},{\"heading\":false,\"text\":\"“I can’t describe to you how surprised I was to find out I loved her, old sport. I even hoped for a while that she’d throw me over, but she didn’t, because she was in love with me too. She thought I knew a lot because I knew different things from her… Well, there I was, way off my ambitions, getting deeper in love every minute, and all of a sudden I didn’t care. What was the use of doing great things if I could have a better time telling her what I was going to do?”\"},{\"heading\":false,\"text\":\"On the last afternoon before he went abroad, he sat with Daisy in his arms for a long, silent time. It was a cold fall day, with fire in the room and her cheeks flushed. Now and then she moved and he changed his arm a little, and once he kissed her dark shining hair. The afternoon had made them tranquil for a while, as if to give them a deep memory for the long parting the next day promised. They had never been closer in their month of love, nor communicated more profoundly one with another, than when she brushed silent lips against his coat’s shoulder or when he touched the end of her fingers, gently, as though she were asleep.\"},{\"heading\":false,\"text\":\"He did extraordinarily well in the war. He was a captain before he went to the front, and following the Argonne battles he got his majority and the command of the divisional machine-guns. After the armistice he tried frantically to get home, but some complication or misunderstanding sent him to Oxford instead. He was worried now—there was a quality of nervous despair in Daisy’s letters. She didn’t see why he couldn’t come. She was feeling the pressure of the world outside, and she wanted to see him and feel his presence beside her and be reassured that she was doing the right thing after all.\"},{\"heading\":false,\"text\":\"For Daisy was young and her artificial world was redolent of orchids and pleasant, cheerful snobbery and orchestras which set the rhythm of the year, summing up the sadness and suggestiveness of life in new tunes. All night the saxophones wailed the hopeless comment of the “Beale Street Blues” while a hundred pairs of golden and silver slippers shuffled the shining dust. At the grey tea hour there were always rooms that throbbed incessantly with this low, sweet fever, while fresh faces drifted here and there like rose petals blown by the sad horns around the floor.\"},{\"heading\":false,\"text\":\"Through this twilight universe Daisy began to move again with the season; suddenly she was again keeping half a dozen dates a day with half a dozen men, and drowsing asleep at dawn with the beads and chiffon of an evening-dress tangled among dying orchids on the floor beside her bed. And all the time something within her was crying for a decision. She wanted her life shaped now, immediately—and the decision must be made by some force—of love, of money, of unquestionable practicality—that was close at hand.\"},{\"heading\":false,\"text\":\"That force took shape in the middle of spring with the arrival of Tom Buchanan. There was a wholesome bulkiness about his person and his position, and Daisy was flattered. Doubtless there was a certain struggle and a certain relief. The letter reached Gatsby while he was still at Oxford.\"},{\"heading\":false,\"text\":\"It was dawn now on Long Island and we went about opening the rest of the windows downstairs, filling the house with grey-turning, gold-turning light. The shadow of a tree fell abruptly across the dew and ghostly birds began to sing among the blue leaves. There was a slow, pleasant movement in the air, scarcely a wind, promising a cool, lovely day.\"},{\"heading\":false,\"text\":\"“I don’t think she ever loved him.” Gatsby turned around from a window and looked at me challengingly. “You must remember, old sport, she was very excited this afternoon. He told her those things in a way that frightened her—that made it look as if I was some kind of cheap sharper. And the result was she hardly knew what she was saying.”\"},{\"heading\":false,\"text\":\"He sat down gloomily.\"},{\"heading\":false,\"text\":\"“Of course she might have loved him just for a minute, when they were first married—and loved me more even then, do you see?”\"},{\"heading\":false,\"text\":\"Suddenly he came out with a curious remark.\"},{\"heading\":false,\"text\":\"“In any case,” he said, “it was just personal.”\"},{\"heading\":false,\"text\":\"What could you make of that, except to suspect some intensity in his conception of the affair that couldn’t be measured?\"},{\"heading\":false,\"text\":\"He came back from France when Tom and Daisy were still on their wedding trip, and made a miserable but irresistible journey to Louisville on the last of his army pay. He stayed there a week, walking the streets where their footsteps had clicked together through the November night and revisiting the out-of-the-way places to which they had driven in her white car. Just as Daisy’s house had always seemed to him more mysterious and gay than other houses, so his idea of the city itself, even though she was gone from it, was pervaded with a melancholy beauty.\"},{\"heading\":false,\"text\":\"He left feeling that if he had searched harder, he might have found her—that he was leaving her behind. The day-coach—he was penniless now—was hot. He went out to the open vestibule and sat down on a folding-chair, and the station slid away and the backs of unfamiliar buildings moved by. Then out into the spring fields, where a yellow trolley raced them for a minute with people in it who might once have seen the pale magic of her face along the casual street.\"},{\"heading\":false,\"text\":\"The track curved and now it was going away from the sun, which, as it sank lower, seemed to spread itself in benediction over the vanishing city where she had drawn her breath. He stretched out his hand desperately as if to snatch only a wisp of air, to save a fragment of the spot that she had made lovely for him. But it was all going by too fast now for his blurred eyes and he knew that he had lost that part of it, the freshest and the best, forever.\"},{\"heading\":false,\"text\":\"It was nine o’clock when we finished breakfast and went out on the porch. The night had made a sharp difference in the weather and there was an autumn flavour in the air. The gardener, the last one of Gatsby’s former servants, came to the foot of the steps.\"},{\"heading\":false,\"text\":\"“I’m going to drain the pool today, Mr. Gatsby. Leaves’ll start falling pretty soon, and then there’s always trouble with the pipes.”\"},{\"heading\":false,\"text\":\"“Don’t do it today,” Gatsby answered. He turned to me apologetically. “You know, old sport, I’ve never used that pool all summer?”\"},{\"heading\":false,\"text\":\"I looked at my watch and stood up.\"},{\"heading\":false,\"text\":\"“Twelve minutes to my train.”\"},{\"heading\":false,\"text\":\"I didn’t want to go to the city. I wasn’t worth a decent stroke of work, but it was more than that—I didn’t want to leave Gatsby. I missed that train, and then another, before I could get myself away.\"},{\"heading\":false,\"text\":\"“I’ll call you up,” I said finally.\"},{\"heading\":false,\"text\":\"“Do, old sport.”\"},{\"heading\":false,\"text\":\"“I’ll call you about noon.”\"},{\"heading\":false,\"text\":\"We walked slowly down the steps.\"},{\"heading\":false,\"text\":\"“I suppose Daisy’ll call too.” He looked at me anxiously, as if he hoped I’d corroborate this.\"},{\"heading\":false,\"text\":\"“I suppose so.”\"},{\"heading\":false,\"text\":\"“Well, goodbye.”\"},{\"heading\":false,\"text\":\"We shook hands and I started away. Just before I reached the hedge I remembered something and turned around.\"},{\"heading\":false,\"text\":\"“They’re a rotten crowd,” I shouted across the lawn. “You’re worth the whole damn bunch put together.”\"},{\"heading\":false,\"text\":\"I’ve always been glad I said that. It was the only compliment I ever gave him, because I disapproved of him from beginning to end. First he nodded politely, and then his face broke into that radiant and understanding smile, as if we’d been in ecstatic cahoots on that fact all the time. His gorgeous pink rag of a suit made a bright spot of colour against the white steps, and I thought of the night when I first came to his ancestral home, three months before. The lawn and drive had been crowded with the faces of those who guessed at his corruption—and he had stood on those steps, concealing his incorruptible dream, as he waved them goodbye.\"},{\"heading\":false,\"text\":\"I thanked him for his hospitality. We were always thanking him for that—I and the others.\"},{\"heading\":false,\"text\":\"“Goodbye,” I called. “I enjoyed breakfast, Gatsby.”\"},{\"heading\":false,\"text\":\"Up in the city, I tried for a while to list the quotations on an interminable amount of stock, then I fell asleep in my swivel-chair. Just before noon the phone woke me, and I started up with sweat breaking out on my forehead. It was Jordan Baker; she often called me up at this hour because the uncertainty of her own movements between hotels and clubs and private houses made her hard to find in any other way. Usually her voice came over the wire as something fresh and cool, as if a divot from a green golf-links had come sailing in at the office window, but this morning it seemed harsh and dry.\"},{\"heading\":false,\"text\":\"“I’ve left Daisy’s house,” she said. “I’m at Hempstead, and I’m going down to Southampton this afternoon.”\"},{\"heading\":false,\"text\":\"Probably it had been tactful to leave Daisy’s house, but the act annoyed me, and her next remark made me rigid.\"},{\"heading\":false,\"text\":\"“You weren’t so nice to me last night.”\"},{\"heading\":false,\"text\":\"“How could it have mattered then?”\"},{\"heading\":false,\"text\":\"Silence for a moment. Then:\"},{\"heading\":false,\"text\":\"“However—I want to see you.”\"},{\"heading\":false,\"text\":\"“I want to see you, too.”\"},{\"heading\":false,\"text\":\"“Suppose I don’t go to Southampton, and come into town this afternoon?”\"},{\"heading\":false,\"text\":\"“No—I don’t think this afternoon.”\"},{\"heading\":false,\"text\":\"“Very well.”\"},{\"heading\":false,\"text\":\"“It’s impossible this afternoon. Various—”\"},{\"heading\":false,\"text\":\"We talked like that for a while, and then abruptly we weren’t talking any longer. I don’t know which of us hung up with a sharp click, but I know I didn’t care. I couldn’t have talked to her across a tea-table that day if I never talked to her again in this world.\"},{\"heading\":false,\"text\":\"I called Gatsby’s house a few minutes later, but the line was busy. I tried four times; finally an exasperated central told me the wire was being kept open for long distance from Detroit. Taking out my timetable, I drew a small circle around the three-fifty train. Then I leaned back in my chair and tried to think. It was just noon.\"},{\"heading\":false,\"text\":\"When I passed the ash-heaps on the train that morning I had crossed deliberately to the other side of the car. I supposed there’d be a curious crowd around there all day with little boys searching for dark spots in the dust, and some garrulous man telling over and over what had happened, until it became less and less real even to him and he could tell it no longer, and Myrtle Wilson’s tragic achievement was forgotten. Now I want to go back a little and tell what happened at the garage after we left there the night before.\"},{\"heading\":false,\"text\":\"They had difficulty in locating the sister, Catherine. She must have broken her rule against drinking that night, for when she arrived she was stupid with liquor and unable to understand that the ambulance had already gone to Flushing. When they convinced her of this, she immediately fainted, as if that was the intolerable part of the affair. Someone, kind or curious, took her in his car and drove her in the wake of her sister’s body.\"},{\"heading\":false,\"text\":\"Until long after midnight a changing crowd lapped up against the front of the garage, while George Wilson rocked himself back and forth on the couch inside. For a while the door of the office was open, and everyone who came into the garage glanced irresistibly through it. Finally someone said it was a shame, and closed the door. Michaelis and several other men were with him; first, four or five men, later two or three men. Still later Michaelis had to ask the last stranger to wait there fifteen minutes longer, while he went back to his own place and made a pot of coffee. After that, he stayed there alone with Wilson until dawn.\"},{\"heading\":false,\"text\":\"About three o’clock the quality of Wilson’s incoherent muttering changed—he grew quieter and began to talk about the yellow car. He announced that he had a way of finding out whom the yellow car belonged to, and then he blurted out that a couple of months ago his wife had come from the city with her face bruised and her nose swollen.\"},{\"heading\":false,\"text\":\"But when he heard himself say this, he flinched and began to cry “Oh, my God!” again in his groaning voice. Michaelis made a clumsy attempt to distract him.\"},{\"heading\":false,\"text\":\"“How long have you been married, George? Come on there, try and sit still a minute, and answer my question. How long have you been married?”\"},{\"heading\":false,\"text\":\"“Twelve years.”\"},{\"heading\":false,\"text\":\"“Ever had any children? Come on, George, sit still—I asked you a question. Did you ever have any children?”\"},{\"heading\":false,\"text\":\"The hard brown beetles kept thudding against the dull light, and whenever Michaelis heard a car go tearing along the road outside it sounded to him like the car that hadn’t stopped a few hours before. He didn’t like to go into the garage, because the work bench was stained where the body had been lying, so he moved uncomfortably around the office—he knew every object in it before morning—and from time to time sat down beside Wilson trying to keep him more quiet.\"},{\"heading\":false,\"text\":\"“Have you got a church you go to sometimes, George? Maybe even if you haven’t been there for a long time? Maybe I could call up the church and get a priest to come over and he could talk to you, see?”\"},{\"heading\":false,\"text\":\"“Don’t belong to any.”\"},{\"heading\":false,\"text\":\"“You ought to have a church, George, for times like this. You must have gone to church once. Didn’t you get married in a church? Listen, George, listen to me. Didn’t you get married in a church?”\"},{\"heading\":false,\"text\":\"“That was a long time ago.”\"},{\"heading\":false,\"text\":\"The effort of answering broke the rhythm of his rocking—for a moment he was silent. Then the same half-knowing, half-bewildered look came back into his faded eyes.\"},{\"heading\":false,\"text\":\"“Look in the drawer there,” he said, pointing at the desk.\"},{\"heading\":false,\"text\":\"“Which drawer?”\"},{\"heading\":false,\"text\":\"“That drawer—that one.”\"},{\"heading\":false,\"text\":\"Michaelis opened the drawer nearest his hand. There was nothing in it but a small, expensive dog-leash, made of leather and braided silver. It was apparently new.\"},{\"heading\":false,\"text\":\"“This?” he inquired, holding it up.\"},{\"heading\":false,\"text\":\"Wilson stared and nodded.\"},{\"heading\":false,\"text\":\"“I found it yesterday afternoon. She tried to tell me about it, but I knew it was something funny.”\"},{\"heading\":false,\"text\":\"“You mean your wife bought it?”\"},{\"heading\":false,\"text\":\"“She had it wrapped in tissue paper on her bureau.”\"},{\"heading\":false,\"text\":\"Michaelis didn’t see anything odd in that, and he gave Wilson a dozen reasons why his wife might have bought the dog-leash. But conceivably Wilson had heard some of these same explanations before, from Myrtle, because he began saying “Oh, my God!” again in a whisper—his comforter left several explanations in the air.\"},{\"heading\":false,\"text\":\"“Then he killed her,” said Wilson. His mouth dropped open suddenly.\"},{\"heading\":false,\"text\":\"“Who did?”\"},{\"heading\":false,\"text\":\"“I have a way of finding out.”\"},{\"heading\":false,\"text\":\"“You’re morbid, George,” said his friend. “This has been a strain to you and you don’t know what you’re saying. You’d better try and sit quiet till morning.”\"},{\"heading\":false,\"text\":\"“He murdered her.”\"},{\"heading\":false,\"text\":\"“It was an accident, George.”\"},{\"heading\":false,\"text\":\"Wilson shook his head. His eyes narrowed and his mouth widened slightly with the ghost of a superior “Hm!”\"},{\"heading\":false,\"text\":\"“I know,” he said definitely. “I’m one of these trusting fellas and I don’t think any harm to nobody, but when I get to know a thing I know it. It was the man in that car. She ran out to speak to him and he wouldn’t stop.”\"},{\"heading\":false,\"text\":\"Michaelis had seen this too, but it hadn’t occurred to him that there was any special significance in it. He believed that Mrs. Wilson had been running away from her husband, rather than trying to stop any particular car.\"},{\"heading\":false,\"text\":\"“How could she of been like that?”\"},{\"heading\":false,\"text\":\"“She’s a deep one,” said Wilson, as if that answered the question. “Ah-h-h—”\"},{\"heading\":false,\"text\":\"He began to rock again, and Michaelis stood twisting the leash in his hand.\"},{\"heading\":false,\"text\":\"“Maybe you got some friend that I could telephone for, George?”\"},{\"heading\":false,\"text\":\"This was a forlorn hope—he was almost sure that Wilson had no friend: there was not enough of him for his wife. He was glad a little later when he noticed a change in the room, a blue quickening by the window, and realized that dawn wasn’t far off. About five o’clock it was blue enough outside to snap off the light.\"},{\"heading\":false,\"text\":\"Wilson’s glazed eyes turned out to the ash-heaps, where small grey clouds took on fantastic shapes and scurried here and there in the faint dawn wind.\"},{\"heading\":false,\"text\":\"“I spoke to her,” he muttered, after a long silence. “I told her she might fool me but she couldn’t fool God. I took her to the window”—with an effort he got up and walked to the rear window and leaned with his face pressed against it—“and I said ‘God knows what you’ve been doing, everything you’ve been doing. You may fool me, but you can’t fool God!’ ”\"},{\"heading\":false,\"text\":\"Standing behind him, Michaelis saw with a shock that he was looking at the eyes of Doctor T. J. Eckleburg, which had just emerged, pale and enormous, from the dissolving night.\"},{\"heading\":false,\"text\":\"“God sees everything,” repeated Wilson.\"},{\"heading\":false,\"text\":\"“That’s an advertisement,” Michaelis assured him. Something made him turn away from the window and look back into the room. But Wilson stood there a long time, his face close to the window pane, nodding into the twilight.\"},{\"heading\":false,\"text\":\"By six o’clock Michaelis was worn out, and grateful for the sound of a car stopping outside. It was one of the watchers of the night before who had promised to come back, so he cooked breakfast for three, which he and the other man ate together. Wilson was quieter now, and Michaelis went home to sleep; when he awoke four hours later and hurried back to the garage, Wilson was gone.\"},{\"heading\":false,\"text\":\"His movements—he was on foot all the time—were afterward traced to Port Roosevelt and then to Gad’s Hill, where he bought a sandwich that he didn’t eat, and a cup of coffee. He must have been tired and walking slowly, for he didn’t reach Gad’s Hill until noon. Thus far there was no difficulty in accounting for his time—there were boys who had seen a man “acting sort of crazy,” and motorists at whom he stared oddly from the side of the road. Then for three hours he disappeared from view. The police, on the strength of what he said to Michaelis, that he “had a way of finding out,” supposed that he spent that time going from garage to garage thereabout, inquiring for a yellow car. On the other hand, no garage man who had seen him ever came forward, and perhaps he had an easier, surer way of finding out what he wanted to know. By half-past two he was in West Egg, where he asked someone the way to Gatsby’s house. So by that time he knew Gatsby’s name.\"},{\"heading\":false,\"text\":\"At two o’clock Gatsby put on his bathing-suit and left word with the butler that if anyone phoned word was to be brought to him at the pool. He stopped at the garage for a pneumatic mattress that had amused his guests during the summer, and the chauffeur helped him to pump it up. Then he gave instructions that the open car wasn’t to be taken out under any circumstances—and this was strange, because the front right fender needed repair.\"},{\"heading\":false,\"text\":\"Gatsby shouldered the mattress and started for the pool. Once he stopped and shifted it a little, and the chauffeur asked him if he needed help, but he shook his head and in a moment disappeared among the yellowing trees.\"},{\"heading\":false,\"text\":\"No telephone message arrived, but the butler went without his sleep and waited for it until four o’clock—until long after there was anyone to give it to if it came. I have an idea that Gatsby himself didn’t believe it would come, and perhaps he no longer cared. If that was true he must have felt that he had lost the old warm world, paid a high price for living too long with a single dream. He must have looked up at an unfamiliar sky through frightening leaves and shivered as he found what a grotesque thing a rose is and how raw the sunlight was upon the scarcely created grass. A new world, material without being real, where poor ghosts, breathing dreams like air, drifted fortuitously about… like that ashen, fantastic figure gliding toward him through the amorphous trees.\"},{\"heading\":false,\"text\":\"The chauffeur—he was one of Wolfshiem’s protégés—heard the shots—afterwards he could only say that he hadn’t thought anything much about them. I drove from the station directly to Gatsby’s house and my rushing anxiously up the front steps was the first thing that alarmed anyone. But they knew then, I firmly believe. With scarcely a word said, four of us, the chauffeur, butler, gardener, and I hurried down to the pool.\"},{\"heading\":false,\"text\":\"There was a faint, barely perceptible movement of the water as the fresh flow from one end urged its way toward the drain at the other. With little ripples that were hardly the shadows of waves, the laden mattress moved irregularly down the pool. A small gust of wind that scarcely corrugated the surface was enough to disturb its accidental course with its accidental burden. The touch of a cluster of leaves revolved it slowly, tracing, like the leg of transit, a thin red circle in the water.\"},{\"heading\":false,\"text\":\"It was after we started with Gatsby toward the house that the gardener saw Wilson’s body a little way off in the grass, and the holocaust was complete.\"}]},{\"title\":\"IX\",\"blocks\":[{\"heading\":false,\"text\":\"After two years I remember the rest of that day, and that night and the next day, only as an endless drill of police and photographers and newspaper men in and out of Gatsby’s front door. A rope stretched across the main gate and a policeman by it kept out the curious, but little boys soon discovered that they could enter through my yard, and there were always a few of them clustered open-mouthed about the pool. Someone with a positive manner, perhaps a detective, used the expression “madman” as he bent over Wilson’s body that afternoon, and the adventitious authority of his voice set the key for the newspaper reports next morning.\"},{\"heading\":false,\"text\":\"Most of those reports were a nightmare—grotesque, circumstantial, eager, and untrue. When Michaelis’s testimony at the inquest brought to light Wilson’s suspicions of his wife I thought the whole tale would shortly be served up in racy pasquinade—but Catherine, who might have said anything, didn’t say a word. She showed a surprising amount of character about it too—looked at the coroner with determined eyes under that corrected brow of hers, and swore that her sister had never seen Gatsby, that her sister was completely happy with her husband, that her sister had been into no mischief whatever. She convinced herself of it, and cried into her handkerchief, as if the very suggestion was more than she could endure. So Wilson was reduced to a man “deranged by grief” in order that the case might remain in its simplest form. And it rested there.\"},{\"heading\":false,\"text\":\"But all this part of it seemed remote and unessential. I found myself on Gatsby’s side, and alone. From the moment I telephoned news of the catastrophe to West Egg village, every surmise about him, and every practical question, was referred to me. At first I was surprised and confused; then, as he lay in his house and didn’t move or breathe or speak, hour upon hour, it grew upon me that I was responsible, because no one else was interested—interested, I mean, with that intense personal interest to which everyone has some vague right at the end.\"},{\"heading\":false,\"text\":\"I called up Daisy half an hour after we found him, called her instinctively and without hesitation. But she and Tom had gone away early that afternoon, and taken baggage with them.\"},{\"heading\":false,\"text\":\"“Left no address?”\"},{\"heading\":false,\"text\":\"“No.”\"},{\"heading\":false,\"text\":\"“Say when they’d be back?”\"},{\"heading\":false,\"text\":\"“No.”\"},{\"heading\":false,\"text\":\"“Any idea where they are? How I could reach them?”\"},{\"heading\":false,\"text\":\"“I don’t know. Can’t say.”\"},{\"heading\":false,\"text\":\"I wanted to get somebody for him. I wanted to go into the room where he lay and reassure him: “I’ll get somebody for you, Gatsby. Don’t worry. Just trust me and I’ll get somebody for you—”\"},{\"heading\":false,\"text\":\"Meyer Wolfshiem’s name wasn’t in the phone book. The butler gave me his office address on Broadway, and I called Information, but by the time I had the number it was long after five, and no one answered the phone.\"},{\"heading\":false,\"text\":\"“Will you ring again?”\"},{\"heading\":false,\"text\":\"“I’ve rung three times.”\"},{\"heading\":false,\"text\":\"“It’s very important.”\"},{\"heading\":false,\"text\":\"“Sorry. I’m afraid no one’s there.”\"},{\"heading\":false,\"text\":\"I went back to the drawing-room and thought for an instant that they were chance visitors, all these official people who suddenly filled it. But, though they drew back the sheet and looked at Gatsby with shocked eyes, his protest continued in my brain:\"},{\"heading\":false,\"text\":\"“Look here, old sport, you’ve got to get somebody for me. You’ve got to try hard. I can’t go through this alone.”\"},{\"heading\":false,\"text\":\"Someone started to ask me questions, but I broke away and going upstairs looked hastily through the unlocked parts of his desk—he’d never told me definitely that his parents were dead. But there was nothing—only the picture of Dan Cody, a token of forgotten violence, staring down from the wall.\"},{\"heading\":false,\"text\":\"Next morning I sent the butler to New York with a letter to Wolfshiem, which asked for information and urged him to come out on the next train. That request seemed superfluous when I wrote it. I was sure he’d start when he saw the newspapers, just as I was sure there’d be a wire from Daisy before noon—but neither a wire nor Mr. Wolfshiem arrived; no one arrived except more police and photographers and newspaper men. When the butler brought back Wolfshiem’s answer I began to have a feeling of defiance, of scornful solidarity between Gatsby and me against them all.\"},{\"heading\":false,\"text\":\"Dear Mr. Carraway. This has been one of the most terrible shocks of my life to me I hardly can believe it that it is true at all. Such a mad act as that man did should make us all think. I cannot come down now as I am tied up in some very important business and cannot get mixed up in this thing now. If there is anything I can do a little later let me know in a letter by Edgar. I hardly know where I am when I hear about a thing like this and am completely knocked down and out.\"},{\"heading\":false,\"text\":\"Yours truly\"},{\"heading\":false,\"text\":\"Meyer Wolfshiem\"},{\"heading\":false,\"text\":\"and then hasty addenda beneath:\"},{\"heading\":false,\"text\":\"Let me know about the funeral etc do not know his family at all.\"},{\"heading\":false,\"text\":\"When the phone rang that afternoon and Long Distance said Chicago was calling I thought this would be Daisy at last. But the connection came through as a man’s voice, very thin and far away.\"},{\"heading\":false,\"text\":\"“This is Slagle speaking…”\"},{\"heading\":false,\"text\":\"“Yes?” The name was unfamiliar.\"},{\"heading\":false,\"text\":\"“Hell of a note, isn’t it? Get my wire?”\"},{\"heading\":false,\"text\":\"“There haven’t been any wires.”\"},{\"heading\":false,\"text\":\"“Young Parke’s in trouble,” he said rapidly. “They picked him up when he handed the bonds over the counter. They got a circular from New York giving ’em the numbers just five minutes before. What d’you know about that, hey? You never can tell in these hick towns—”\"},{\"heading\":false,\"text\":\"“Hello!” I interrupted breathlessly. “Look here—this isn’t Mr. Gatsby. Mr. Gatsby’s dead.”\"},{\"heading\":false,\"text\":\"There was a long silence on the other end of the wire, followed by an exclamation… then a quick squawk as the connection was broken.\"},{\"heading\":false,\"text\":\"I think it was on the third day that a telegram signed Henry C. Gatz arrived from a town in Minnesota. It said only that the sender was leaving immediately and to postpone the funeral until he came.\"},{\"heading\":false,\"text\":\"It was Gatsby’s father, a solemn old man, very helpless and dismayed, bundled up in a long cheap ulster against the warm September day. His eyes leaked continuously with excitement, and when I took the bag and umbrella from his hands he began to pull so incessantly at his sparse grey beard that I had difficulty in getting off his coat. He was on the point of collapse, so I took him into the music-room and made him sit down while I sent for something to eat. But he wouldn’t eat, and the glass of milk spilled from his trembling hand.\"},{\"heading\":false,\"text\":\"“I saw it in the Chicago newspaper,” he said. “It was all in the Chicago newspaper. I started right away.”\"},{\"heading\":false,\"text\":\"“I didn’t know how to reach you.”\"},{\"heading\":false,\"text\":\"His eyes, seeing nothing, moved ceaselessly about the room.\"},{\"heading\":false,\"text\":\"“It was a madman,” he said. “He must have been mad.”\"},{\"heading\":false,\"text\":\"“Wouldn’t you like some coffee?” I urged him.\"},{\"heading\":false,\"text\":\"“I don’t want anything. I’m all right now, Mr.—”\"},{\"heading\":false,\"text\":\"“Carraway.”\"},{\"heading\":false,\"text\":\"“Well, I’m all right now. Where have they got Jimmy?”\"},{\"heading\":false,\"text\":\"I took him into the drawing-room, where his son lay, and left him there. Some little boys had come up on the steps and were looking into the hall; when I told them who had arrived, they went reluctantly away.\"},{\"heading\":false,\"text\":\"After a little while Mr. Gatz opened the door and came out, his mouth ajar, his face flushed slightly, his eyes leaking isolated and unpunctual tears. He had reached an age where death no longer has the quality of ghastly surprise, and when he looked around him now for the first time and saw the height and splendour of the hall and the great rooms opening out from it into other rooms, his grief began to be mixed with an awed pride. I helped him to a bedroom upstairs; while he took off his coat and vest I told him that all arrangements had been deferred until he came.\"},{\"heading\":false,\"text\":\"“I didn’t know what you’d want, Mr. Gatsby—”\"},{\"heading\":false,\"text\":\"“Gatz is my name.”\"},{\"heading\":false,\"text\":\"“—Mr. Gatz. I thought you might want to take the body West.”\"},{\"heading\":false,\"text\":\"He shook his head.\"},{\"heading\":false,\"text\":\"“Jimmy always liked it better down East. He rose up to his position in the East. Were you a friend of my boy’s, Mr.—?”\"},{\"heading\":false,\"text\":\"“We were close friends.”\"},{\"heading\":false,\"text\":\"“He had a big future before him, you know. He was only a young man, but he had a lot of brain power here.”\"},{\"heading\":false,\"text\":\"He touched his head impressively, and I nodded.\"},{\"heading\":false,\"text\":\"“If he’d of lived, he’d of been a great man. A man like James J. Hill. He’d of helped build up the country.”\"},{\"heading\":false,\"text\":\"“That’s true,” I said, uncomfortably.\"},{\"heading\":false,\"text\":\"He fumbled at the embroidered coverlet, trying to take it from the bed, and lay down stiffly—was instantly asleep.\"},{\"heading\":false,\"text\":\"That night an obviously frightened person called up, and demanded to know who I was before he would give his name.\"},{\"heading\":false,\"text\":\"“This is Mr. Carraway,” I said.\"},{\"heading\":false,\"text\":\"“Oh!” He sounded relieved. “This is Klipspringer.”\"},{\"heading\":false,\"text\":\"I was relieved too, for that seemed to promise another friend at Gatsby’s grave. I didn’t want it to be in the papers and draw a sightseeing crowd, so I’d been calling up a few people myself. They were hard to find.\"},{\"heading\":false,\"text\":\"“The funeral’s tomorrow,” I said. “Three o’clock, here at the house. I wish you’d tell anybody who’d be interested.”\"},{\"heading\":false,\"text\":\"“Oh, I will,” he broke out hastily. “Of course I’m not likely to see anybody, but if I do.”\"},{\"heading\":false,\"text\":\"His tone made me suspicious.\"},{\"heading\":false,\"text\":\"“Of course you’ll be there yourself.”\"},{\"heading\":false,\"text\":\"“Well, I’ll certainly try. What I called up about is—”\"},{\"heading\":false,\"text\":\"“Wait a minute,” I interrupted. “How about saying you’ll come?”\"},{\"heading\":false,\"text\":\"“Well, the fact is—the truth of the matter is that I’m staying with some people up here in Greenwich, and they rather expect me to be with them tomorrow. In fact, there’s a sort of picnic or something. Of course I’ll do my best to get away.”\"},{\"heading\":false,\"text\":\"I ejaculated an unrestrained “Huh!” and he must have heard me, for he went on nervously:\"},{\"heading\":false,\"text\":\"“What I called up about was a pair of shoes I left there. I wonder if it’d be too much trouble to have the butler send them on. You see, they’re tennis shoes, and I’m sort of helpless without them. My address is care of B. F.—”\"},{\"heading\":false,\"text\":\"I didn’t hear the rest of the name, because I hung up the receiver.\"},{\"heading\":false,\"text\":\"After that I felt a certain shame for Gatsby—one gentleman to whom I telephoned implied that he had got what he deserved. However, that was my fault, for he was one of those who used to sneer most bitterly at Gatsby on the courage of Gatsby’s liquor, and I should have known better than to call him.\"},{\"heading\":false,\"text\":\"The morning of the funeral I went up to New York to see Meyer Wolfshiem; I couldn’t seem to reach him any other way. The door that I pushed open, on the advice of an elevator boy, was marked “The Swastika Holding Company,” and at first there didn’t seem to be anyone inside. But when I’d shouted “hello” several times in vain, an argument broke out behind a partition, and presently a lovely Jewess appeared at an interior door and scrutinized me with black hostile eyes.\"},{\"heading\":false,\"text\":\"“Nobody’s in,” she said. “Mr. Wolfshiem’s gone to Chicago.”\"},{\"heading\":false,\"text\":\"The first part of this was obviously untrue, for someone had begun to whistle “The Rosary,” tunelessly, inside.\"},{\"heading\":false,\"text\":\"“Please say that Mr. Carraway wants to see him.”\"},{\"heading\":false,\"text\":\"“I can’t get him back from Chicago, can I?”\"},{\"heading\":false,\"text\":\"At this moment a voice, unmistakably Wolfshiem’s, called “Stella!” from the other side of the door.\"},{\"heading\":false,\"text\":\"“Leave your name on the desk,” she said quickly. “I’ll give it to him when he gets back.”\"},{\"heading\":false,\"text\":\"“But I know he’s there.”\"},{\"heading\":false,\"text\":\"She took a step toward me and began to slide her hands indignantly up and down her hips.\"},{\"heading\":false,\"text\":\"“You young men think you can force your way in here any time,” she scolded. “We’re getting sickantired of it. When I say he’s in Chicago, he’s in Chicago.”\"},{\"heading\":false,\"text\":\"I mentioned Gatsby.\"},{\"heading\":false,\"text\":\"“Oh-h!” She looked at me over again. “Will you just—What was your name?”\"},{\"heading\":false,\"text\":\"She vanished. In a moment Meyer Wolfshiem stood solemnly in the doorway, holding out both hands. He drew me into his office, remarking in a reverent voice that it was a sad time for all of us, and offered me a cigar.\"},{\"heading\":false,\"text\":\"“My memory goes back to when first I met him,” he said. “A young major just out of the army and covered over with medals he got in the war. He was so hard up he had to keep on wearing his uniform because he couldn’t buy some regular clothes. First time I saw him was when he came into Winebrenner’s poolroom at Forty-third Street and asked for a job. He hadn’t eat anything for a couple of days. ‘Come on have some lunch with me,’ I said. He ate more than four dollars’ worth of food in half an hour.”\"},{\"heading\":false,\"text\":\"“Did you start him in business?” I inquired.\"},{\"heading\":false,\"text\":\"“Start him! I made him.”\"},{\"heading\":false,\"text\":\"“Oh.”\"},{\"heading\":false,\"text\":\"“I raised him up out of nothing, right out of the gutter. I saw right away he was a fine-appearing, gentlemanly young man, and when he told me he was at Oggsford I knew I could use him good. I got him to join the American Legion and he used to stand high there. Right off he did some work for a client of mine up to Albany. We were so thick like that in everything”—he held up two bulbous fingers—“always together.”\"},{\"heading\":false,\"text\":\"I wondered if this partnership had included the World’s Series transaction in 1919.\"},{\"heading\":false,\"text\":\"“Now he’s dead,” I said after a moment. “You were his closest friend, so I know you’ll want to come to his funeral this afternoon.”\"},{\"heading\":false,\"text\":\"“I’d like to come.”\"},{\"heading\":false,\"text\":\"“Well, come then.”\"},{\"heading\":false,\"text\":\"The hair in his nostrils quivered slightly, and as he shook his head his eyes filled with tears.\"},{\"heading\":false,\"text\":\"“I can’t do it—I can’t get mixed up in it,” he said.\"},{\"heading\":false,\"text\":\"“There’s nothing to get mixed up in. It’s all over now.”\"},{\"heading\":false,\"text\":\"“When a man gets killed I never like to get mixed up in it in any way. I keep out. When I was a young man it was different—if a friend of mine died, no matter how, I stuck with them to the end. You may think that’s sentimental, but I mean it—to the bitter end.”\"},{\"heading\":false,\"text\":\"I saw that for some reason of his own he was determined not to come, so I stood up.\"},{\"heading\":false,\"text\":\"“Are you a college man?” he inquired suddenly.\"},{\"heading\":false,\"text\":\"For a moment I thought he was going to suggest a “gonnegtion,” but he only nodded and shook my hand.\"},{\"heading\":false,\"text\":\"“Let us learn to show our friendship for a man when he is alive and not after he is dead,” he suggested. “After that my own rule is to let everything alone.”\"},{\"heading\":false,\"text\":\"When I left his office the sky had turned dark and I got back to West Egg in a drizzle. After changing my clothes I went next door and found Mr. Gatz walking up and down excitedly in the hall. His pride in his son and in his son’s possessions was continually increasing and now he had something to show me.\"},{\"heading\":false,\"text\":\"“Jimmy sent me this picture.” He took out his wallet with trembling fingers. “Look there.”\"},{\"heading\":false,\"text\":\"It was a photograph of the house, cracked in the corners and dirty with many hands. He pointed out every detail to me eagerly. “Look there!” and then sought admiration from my eyes. He had shown it so often that I think it was more real to him now than the house itself.\"},{\"heading\":false,\"text\":\"“Jimmy sent it to me. I think it’s a very pretty picture. It shows up well.”\"},{\"heading\":false,\"text\":\"“Very well. Had you seen him lately?”\"},{\"heading\":false,\"text\":\"“He come out to see me two years ago and bought me the house I live in now. Of course we was broke up when he run off from home, but I see now there was a reason for it. He knew he had a big future in front of him. And ever since he made a success he was very generous with me.”\"},{\"heading\":false,\"text\":\"He seemed reluctant to put away the picture, held it for another minute, lingeringly, before my eyes. Then he returned the wallet and pulled from his pocket a ragged old copy of a book called Hopalong Cassidy.\"},{\"heading\":false,\"text\":\"“Look here, this is a book he had when he was a boy. It just shows you.”\"},{\"heading\":false,\"text\":\"He opened it at the back cover and turned it around for me to see. On the last flyleaf was printed the word schedule, and the date September 12, 1906. And underneath:\"},{\"heading\":false,\"text\":\"General Resolves\"},{\"heading\":false,\"text\":\"No wasting time at Shafters or [a name, indecipherable]\"},{\"heading\":false,\"text\":\"No more smokeing or chewing.\"},{\"heading\":false,\"text\":\"Bath every other day\"},{\"heading\":false,\"text\":\"Read one improving book or magazine per week\"},{\"heading\":false,\"text\":\"Save $5.00 [crossed out] $3.00 per week\"},{\"heading\":false,\"text\":\"Be better to parents\"},{\"heading\":false,\"text\":\"“I came across this book by accident,” said the old man. “It just shows you, don’t it?”\"},{\"heading\":false,\"text\":\"“It just shows you.”\"},{\"heading\":false,\"text\":\"“Jimmy was bound to get ahead. He always had some resolves like this or something. Do you notice what he’s got about improving his mind? He was always great for that. He told me I et like a hog once, and I beat him for it.”\"},{\"heading\":false,\"text\":\"He was reluctant to close the book, reading each item aloud and then looking eagerly at me. I think he rather expected me to copy down the list for my own use.\"},{\"heading\":false,\"text\":\"A little before three the Lutheran minister arrived from Flushing, and I began to look involuntarily out the windows for other cars. So did Gatsby’s father. And as the time passed and the servants came in and stood waiting in the hall, his eyes began to blink anxiously, and he spoke of the rain in a worried, uncertain way. The minister glanced several times at his watch, so I took him aside and asked him to wait for half an hour. But it wasn’t any use. Nobody came.\"},{\"heading\":false,\"text\":\"About five o’clock our procession of three cars reached the cemetery and stopped in a thick drizzle beside the gate—first a motor hearse, horribly black and wet, then Mr. Gatz and the minister and me in the limousine, and a little later four or five servants and the postman from West Egg, in Gatsby’s station wagon, all wet to the skin. As we started through the gate into the cemetery I heard a car stop and then the sound of someone splashing after us over the soggy ground. I looked around. It was the man with owl-eyed glasses whom I had found marvelling over Gatsby’s books in the library one night three months before.\"},{\"heading\":false,\"text\":\"I’d never seen him since then. I don’t know how he knew about the funeral, or even his name. The rain poured down his thick glasses, and he took them off and wiped them to see the protecting canvas unrolled from Gatsby’s grave.\"},{\"heading\":false,\"text\":\"I tried to think about Gatsby then for a moment, but he was already too far away, and I could only remember, without resentment, that Daisy hadn’t sent a message or a flower. Dimly I heard someone murmur “Blessed are the dead that the rain falls on,” and then the owl-eyed man said “Amen to that,” in a brave voice.\"},{\"heading\":false,\"text\":\"We straggled down quickly through the rain to the cars. Owl-eyes spoke to me by the gate.\"},{\"heading\":false,\"text\":\"“I couldn’t get to the house,” he remarked.\"},{\"heading\":false,\"text\":\"“Neither could anybody else.”\"},{\"heading\":false,\"text\":\"“Go on!” He started. “Why, my God! they used to go there by the hundreds.”\"},{\"heading\":false,\"text\":\"He took off his glasses and wiped them again, outside and in.\"},{\"heading\":false,\"text\":\"“The poor son-of-a-bitch,” he said.\"},{\"heading\":false,\"text\":\"One of my most vivid memories is of coming back West from prep school and later from college at Christmas time. Those who went farther than Chicago would gather in the old dim Union Station at six o’clock of a December evening, with a few Chicago friends, already caught up into their own holiday gaieties, to bid them a hasty goodbye. I remember the fur coats of the girls returning from Miss This-or-That’s and the chatter of frozen breath and the hands waving overhead as we caught sight of old acquaintances, and the matchings of invitations: “Are you going to the Ordways’? the Herseys’? the Schultzes’?” and the long green tickets clasped tight in our gloved hands. And last the murky yellow cars of the Chicago, Milwaukee and St. Paul railroad looking cheerful as Christmas itself on the tracks beside the gate.\"},{\"heading\":false,\"text\":\"When we pulled out into the winter night and the real snow, our snow, began to stretch out beside us and twinkle against the windows, and the dim lights of small Wisconsin stations moved by, a sharp wild brace came suddenly into the air. We drew in deep breaths of it as we walked back from dinner through the cold vestibules, unutterably aware of our identity with this country for one strange hour, before we melted indistinguishably into it again.\"},{\"heading\":false,\"text\":\"That’s my Middle West—not the wheat or the prairies or the lost Swede towns, but the thrilling returning trains of my youth, and the street lamps and sleigh bells in the frosty dark and the shadows of holly wreaths thrown by lighted windows on the snow. I am part of that, a little solemn with the feel of those long winters, a little complacent from growing up in the Carraway house in a city where dwellings are still called through decades by a family’s name. I see now that this has been a story of the West, after all—Tom and Gatsby, Daisy and Jordan and I, were all Westerners, and perhaps we possessed some deficiency in common which made us subtly unadaptable to Eastern life.\"},{\"heading\":false,\"text\":\"Even when the East excited me most, even when I was most keenly aware of its superiority to the bored, sprawling, swollen towns beyond the Ohio, with their interminable inquisitions which spared only the children and the very old—even then it had always for me a quality of distortion. West Egg, especially, still figures in my more fantastic dreams. I see it as a night scene by El Greco: a hundred houses, at once conventional and grotesque, crouching under a sullen, overhanging sky and a lustreless moon. In the foreground four solemn men in dress suits are walking along the sidewalk with a stretcher on which lies a drunken woman in a white evening dress. Her hand, which dangles over the side, sparkles cold with jewels. Gravely the men turn in at a house—the wrong house. But no one knows the woman’s name, and no one cares.\"},{\"heading\":false,\"text\":\"After Gatsby’s death the East was haunted for me like that, distorted beyond my eyes’ power of correction. So when the blue smoke of brittle leaves was in the air and the wind blew the wet laundry stiff on the line I decided to come back home.\"},{\"heading\":false,\"text\":\"There was one thing to be done before I left, an awkward, unpleasant thing that perhaps had better have been let alone. But I wanted to leave things in order and not just trust that obliging and indifferent sea to sweep my refuse away. I saw Jordan Baker and talked over and around what had happened to us together, and what had happened afterward to me, and she lay perfectly still, listening, in a big chair.\"},{\"heading\":false,\"text\":\"She was dressed to play golf, and I remember thinking she looked like a good illustration, her chin raised a little jauntily, her hair the colour of an autumn leaf, her face the same brown tint as the fingerless glove on her knee. When I had finished she told me without comment that she was engaged to another man. I doubted that, though there were several she could have married at a nod of her head, but I pretended to be surprised. For just a minute I wondered if I wasn’t making a mistake, then I thought it all over again quickly and got up to say goodbye.\"},{\"heading\":false,\"text\":\"“Nevertheless you did throw me over,” said Jordan suddenly. “You threw me over on the telephone. I don’t give a damn about you now, but it was a new experience for me, and I felt a little dizzy for a while.”\"},{\"heading\":false,\"text\":\"We shook hands.\"},{\"heading\":false,\"text\":\"“Oh, and do you remember”—she added—“a conversation we had once about driving a car?”\"},{\"heading\":false,\"text\":\"“Why—not exactly.”\"},{\"heading\":false,\"text\":\"“You said a bad driver was only safe until she met another bad driver? Well, I met another bad driver, didn’t I? I mean it was careless of me to make such a wrong guess. I thought you were rather an honest, straightforward person. I thought it was your secret pride.”\"},{\"heading\":false,\"text\":\"“I’m thirty,” I said. “I’m five years too old to lie to myself and call it honour.”\"},{\"heading\":false,\"text\":\"She didn’t answer. Angry, and half in love with her, and tremendously sorry, I turned away.\"},{\"heading\":false,\"text\":\"One afternoon late in October I saw Tom Buchanan. He was walking ahead of me along Fifth Avenue in his alert, aggressive way, his hands out a little from his body as if to fight off interference, his head moving sharply here and there, adapting itself to his restless eyes. Just as I slowed up to avoid overtaking him he stopped and began frowning into the windows of a jewellery store. Suddenly he saw me and walked back, holding out his hand.\"},{\"heading\":false,\"text\":\"“What’s the matter, Nick? Do you object to shaking hands with me?”\"},{\"heading\":false,\"text\":\"“Yes. You know what I think of you.”\"},{\"heading\":false,\"text\":\"“You’re crazy, Nick,” he said quickly. “Crazy as hell. I don’t know what’s the matter with you.”\"},{\"heading\":false,\"text\":\"“Tom,” I inquired, “what did you say to Wilson that afternoon?”\"},{\"heading\":false,\"text\":\"He stared at me without a word, and I knew I had guessed right about those missing hours. I started to turn away, but he took a step after me and grabbed my arm.\"},{\"heading\":false,\"text\":\"“I told him the truth,” he said. “He came to the door while we were getting ready to leave, and when I sent down word that we weren’t in he tried to force his way upstairs. He was crazy enough to kill me if I hadn’t told him who owned the car. His hand was on a revolver in his pocket every minute he was in the house—” He broke off defiantly. “What if I did tell him? That fellow had it coming to him. He threw dust into your eyes just like he did in Daisy’s, but he was a tough one. He ran over Myrtle like you’d run over a dog and never even stopped his car.”\"},{\"heading\":false,\"text\":\"There was nothing I could say, except the one unutterable fact that it wasn’t true.\"},{\"heading\":false,\"text\":\"“And if you think I didn’t have my share of suffering—look here, when I went to give up that flat and saw that damn box of dog biscuits sitting there on the sideboard, I sat down and cried like a baby. By God it was awful—”\"},{\"heading\":false,\"text\":\"I couldn’t forgive him or like him, but I saw that what he had done was, to him, entirely justified. It was all very careless and confused. They were careless people, Tom and Daisy—they smashed up things and creatures and then retreated back into their money or their vast carelessness, or whatever it was that kept them together, and let other people clean up the mess they had made…\"},{\"heading\":false,\"text\":\"I shook hands with him; it seemed silly not to, for I felt suddenly as though I were talking to a child. Then he went into the jewellery store to buy a pearl necklace—or perhaps only a pair of cuff buttons—rid of my provincial squeamishness forever.\"},{\"heading\":false,\"text\":\"Gatsby’s house was still empty when I left—the grass on his lawn had grown as long as mine. One of the taxi drivers in the village never took a fare past the entrance gate without stopping for a minute and pointing inside; perhaps it was he who drove Daisy and Gatsby over to East Egg the night of the accident, and perhaps he had made a story about it all his own. I didn’t want to hear it and I avoided him when I got off the train.\"},{\"heading\":false,\"text\":\"I spent my Saturday nights in New York because those gleaming, dazzling parties of his were with me so vividly that I could still hear the music and the laughter, faint and incessant, from his garden, and the cars going up and down his drive. One night I did hear a material car there, and saw its lights stop at his front steps. But I didn’t investigate. Probably it was some final guest who had been away at the ends of the earth and didn’t know that the party was over.\"},{\"heading\":false,\"text\":\"On the last night, with my trunk packed and my car sold to the grocer, I went over and looked at that huge incoherent failure of a house once more. On the white steps an obscene word, scrawled by some boy with a piece of brick, stood out clearly in the moonlight, and I erased it, drawing my shoe raspingly along the stone. Then I wandered down to the beach and sprawled out on the sand.\"},{\"heading\":false,\"text\":\"Most of the big shore places were closed now and there were hardly any lights except the shadowy, moving glow of a ferryboat across the Sound. And as the moon rose higher the inessential houses began to melt away until gradually I became aware of the old island here that flowered once for Dutch sailors’ eyes—a fresh, green breast of the new world. Its vanished trees, the trees that had made way for Gatsby’s house, had once pandered in whispers to the last and greatest of all human dreams; for a transitory enchanted moment man must have held his breath in the presence of this continent, compelled into an aesthetic contemplation he neither understood nor desired, face to face for the last time in history with something commensurate to his capacity for wonder.\"},{\"heading\":false,\"text\":\"And as I sat there brooding on the old, unknown world, I thought of Gatsby’s wonder when he first picked out the green light at the end of Daisy’s dock. He had come a long way to this blue lawn, and his dream must have seemed so close that he could hardly fail to grasp it. He did not know that it was already behind him, somewhere back in that vast obscurity beyond the city, where the dark fields of the republic rolled on under the night.\"},{\"heading\":false,\"text\":\"Gatsby believed in the green light, the orgiastic future that year by year recedes before us. It eluded us then, but that’s no matter—tomorrow we will run faster, stretch out our arms further… And one fine morning—\"},{\"heading\":false,\"text\":\"So we beat on, boats against the current, borne back ceaselessly into the past.\"}]}]', 'en', NULL, '{\"en\":{\"title\":\"Introduction\",\"blocks\":[{\"heading\":false,\"text\":\"F. Scott Fitzgerald (1896–1940) published The Great Gatsby in 1925. Portrait of the 1920s, follows Nick Carraway on Long Island between parties and rumors of money.\"},{\"heading\":true,\"text\":\"Gatsby and Daisy\"},{\"heading\":false,\"text\":\"Jay Gatsby raises mansion and parties to get back Daisy Buchanan, married to Tom. Summer is tense between desire and class.\"},{\"heading\":true,\"text\":\"Dream and façade\"},{\"heading\":false,\"text\":\"The novel crosses the American dream with its contrast: credit, show and guilt. The green light on the other side of the water condenses everything.\"},{\"heading\":true,\"text\":\"Style\"},{\"heading\":false,\"text\":\"Concise prose, ellipsis and cinematographic editing make a short novel that is read at once.\"},{\"heading\":true,\"text\":\"The edition\"},{\"heading\":false,\"text\":\"The local text is in English. This introduction in Spanish provides context without replacing Fitzgerald\'s words.\"}]},\"es\":{\"title\":\"Introducción\",\"blocks\":[{\"heading\":false,\"text\":\"F. Scott Fitzgerald (1896–1940) publicó El gran Gatsby en 1925. Retrato de los años veinte, sigue a Nick Carraway en Long Island entre fiestas y rumor de dinero.\"},{\"heading\":true,\"text\":\"Gatsby y Daisy\"},{\"heading\":false,\"text\":\"Jay Gatsby levanta mansión y fiestas para recuperar a Daisy Buchanan, casada con Tom. El verano se tensa entre deseo y clase.\"},{\"heading\":true,\"text\":\"Sueño y fachada\"},{\"heading\":false,\"text\":\"La novela cruza el sueño americano con su contracara: crédito, espectáculo y culpa. La luz verde al otro lado del agua condensa todo.\"},{\"heading\":true,\"text\":\"Estilo\"},{\"heading\":false,\"text\":\"Prosa concisa, elipsis y montaje cinematográfico hacen una novela breve que se lee de un tirón.\"},{\"heading\":true,\"text\":\"La edición\"},{\"heading\":false,\"text\":\"El texto local está en inglés. Esta introducción en español ofrece contexto sin reemplazar las palabras de Fitzgerald.\"}]}}');

-- todas las tablas van en proyectodetodo, que es la base que usa la app

CREATE TABLE IF NOT EXISTS usuarios (
    id_usuario   INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    nombre       VARCHAR(100) NOT NULL UNIQUE,
    correo       VARCHAR(150) NOT NULL UNIQUE,
    contrasenia   VARCHAR(255) NOT NULL,  -- guardar el hash (password_hash en PHP), nunca el texto
    rol          ENUM('cliente', 'administrador') NOT NULL DEFAULT 'cliente',
    fecha_alta   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;



CREATE TABLE categorias (
    id_categoria INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    nombre       VARCHAR(80) NOT NULL UNIQUE
) ENGINE=InnoDB;




CREATE TABLE articulos (
    id_articulo    INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    id_libro       INT UNSIGNED NOT NULL,
    formato        ENUM('fisico', 'digital') NOT NULL,
    precio         DECIMAL(10,2) NOT NULL CHECK (precio >= 0),
    stock          INT NULL CHECK (stock >= 0),                 -- NULL en los digitales
    codigo_barras  VARCHAR(30) NULL UNIQUE,         -- NULL en los digitales (no se escanean)
    archivo        VARCHAR(255) NULL,        -- solo digitales
    activo         TINYINT(1) NOT NULL DEFAULT 1,  -- baja lógica
    CONSTRAINT fk_articulos_libro FOREIGN KEY (id_libro)
        REFERENCES libros (id),
    digital_de INT UNSIGNED GENERATED ALWAYS AS (IF(formato = 'digital', id_libro, NULL)) STORED, 
    CONSTRAINT uq_articulos_digital_libro UNIQUE (digital_de),
    CONSTRAINT ck_articulos_formato CHECK (
        (formato = 'digital' AND stock IS NULL AND codigo_barras IS NULL)
        OR
        (formato = 'fisico' AND stock IS NOT NULL AND archivo IS NULL) 
    )
) ENGINE=InnoDB;



CREATE TABLE ventas (
    id_venta     INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    id_cliente   INT UNSIGNED NULL,   -- venta web
    id_vendedor  INT UNSIGNED NULL,   -- venta de mostrador
    fecha        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    total        DECIMAL(10,2) NOT NULL DEFAULT 0 CHECK (total >= 0),
    CONSTRAINT fk_ventas_cliente FOREIGN KEY (id_cliente)
        REFERENCES usuarios (id_usuario),
    CONSTRAINT fk_ventas_vendedor FOREIGN KEY (id_vendedor)
        REFERENCES usuarios (id_usuario),
    CONSTRAINT ck_ventas_alguien CHECK (id_cliente IS NOT NULL OR id_vendedor IS NOT NULL)
) ENGINE=InnoDB;



CREATE TABLE venta_lineas (
    id_linea         INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    id_venta         INT UNSIGNED NOT NULL,
    id_articulo      INT UNSIGNED NOT NULL,
    cantidad         INT UNSIGNED NOT NULL DEFAULT 1 CHECK (cantidad > 0),
    precio_unitario  DECIMAL(10,2) NOT NULL CHECK (precio_unitario >= 0),
    CONSTRAINT fk_lineas_venta FOREIGN KEY (id_venta)
        REFERENCES ventas (id_venta) ON DELETE CASCADE,
    -- RESTRICT: la base rechaza borrar un artículo que ya se vendió
    CONSTRAINT fk_lineas_articulo FOREIGN KEY (id_articulo)
        REFERENCES articulos (id_articulo) ON DELETE RESTRICT,
    CONSTRAINT uq_lineas_venta_articulo UNIQUE (id_venta, id_articulo)
) ENGINE=InnoDB;



CREATE TABLE resenias (
    id_resenia   INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    id_libro     INT UNSIGNED NOT NULL,
    id_usuario   INT UNSIGNED NOT NULL,
    puntaje      TINYINT UNSIGNED NOT NULL CHECK (puntaje BETWEEN 1 AND 5),
    comentario   TEXT,
    fecha        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_resenias_libro FOREIGN KEY (id_libro)
        REFERENCES libros (id),
    CONSTRAINT fk_resenias_usuario FOREIGN KEY (id_usuario)
        REFERENCES usuarios (id_usuario),
    CONSTRAINT uq_resenias_usuario_libro UNIQUE (id_usuario, id_libro)
) ENGINE=InnoDB;